INSERT INTO hymns VALUES('S2424',NULL,NULL,NULL,'De Jehová es la tierra y su plenitud;','S',NULL,'DE JEHOVÁ ES LA TIERRA Y SU PLENITUD (Sal. 24)',NULL,'2424',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2425',NULL,NULL,NULL,'En Su segunda venida,','S',NULL,'EN SU SEGUNDA VENIDA EL TOMARÁ POSESIÓN DE LA TIERRA',NULL,'2425',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2426',NULL,NULL,'UN SÓLO‿ESPÍRITU Y‿UNA SOLA NATURALEZA,','Señor, que vivas en mí,','S',NULL,'SEÑOR QUE VIVAS EN MI, SEÑOR QUE YO VIVA EN TI',NULL,'2426',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2427',NULL,NULL,NULL,'Si amamos al Señor,','S',NULL,'SI AMAMOS AL SEÑOR Y VELAMOS POR SU ÚNICO CUERPO',NULL,'2427',NULL,NULL,'51233334443231','NS10086',NULL,NULL,'NS10086');
INSERT INTO hymns VALUES('S2428',NULL,NULL,'TE AMO LOCAMENTE, OH JESÚS,','Tu dulzura es para nuestro disfrute,','S',NULL,'TU DULZURA ES PARA NUESTRO DISFRUTE',NULL,'2428',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2429',NULL,NULL,'TRIUNO DIOS,','Dios, Padre amoroso.','S',NULL,'DIOS PADRE AMOROSO - TRIUNO DIOS, OH CUANTO NOS AMAS',NULL,'2429',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2430',NULL,NULL,'SEÑOR TE AMO,','El Dios Triuno se procesó,','S',NULL,'EL DIOS TRIUNO SE PROCESÓ (ETC-C -2023)',NULL,'2430',NULL,NULL,NULL,NULL,NULL,NULL,'');
INSERT INTO hymns VALUES('S2431',NULL,NULL,'DIOS DE PAZ APLASTA BAJO','¡Exultad, oh pueblos todos!','S',NULL,'EXULTAD, OH PUEBLOS TODOS (Traducción provisional)',NULL,'2431',NULL,NULL,'1231616512314321','NS471',NULL,NULL,'NS471');
INSERT INTO hymns VALUES('S2432',NULL,NULL,'¡ÉL ESCUCHARÁ!','El gran secreto he aprendido','S',NULL,'EL GRAN SECRETO HE APRENDIDO DE EN JESÚS TODO HACER',NULL,'2432',NULL,NULL,'1233112353234321',NULL,NULL,NULL,'');
INSERT INTO stanza VALUES('E1','1','Glory be to God the Father,<br/>And to Christ the Son,<br/>Glory to the Holy Spirit-<br/>Ever One.<br/>',NULL,1,1);
INSERT INTO stanza VALUES('E1','2','As we view the vast creation,<br/>Planned with wondrous skill,<br/>So our hearts would move to worship,<br/>And be still.<br/>',NULL,2,2);
INSERT INTO stanza VALUES('E1','3','But, our God, how great Thy yearning<br/>To have sons who love<br/>In the Son e''en now to praise Thee,<br/>Love to prove!<br/>',NULL,3,3);
INSERT INTO stanza VALUES('E1','4','''Twas Thy thought in revelation,<br/>To present to men<br/>Secrets of Thine own affections,<br/>Theirs to win.<br/>',NULL,4,4);
INSERT INTO stanza VALUES('E1','5','So in Christ, through His redemption<br/>(Vanquished evil powers!)<br/>Thou hast brought, in new creation,<br/>Worshippers!<br/>',NULL,5,5);
INSERT INTO stanza VALUES('E1','6','Glory be to God the Father,<br/>And to Christ the Son,<br/>Glory to the Holy Spirit<br/>Ever One.<br/>',NULL,6,6);
INSERT INTO stanza VALUES('E2','1','Glory, glory, glory, praise and adoration!<br/>Hear the anthems swelling out thro'' all eternity!<br/>Father, Son, and Spirit-God in revelation-<br/>Prostrate each soul before the Deity!<br/>',NULL,7,7);
INSERT INTO stanza VALUES('E2','2','Father, source of glory, naming every fam''ly;<br/>And the Son upholding all by His almighty power;<br/>Holy Spirit, filling the vast scene of glory-<br/>O glorious Fullness, let our hearts adore!<br/>',NULL,8,8);
INSERT INTO stanza VALUES('E2','3','God supreme, we worship now in holy Splendor,<br/> Head of the vast scene of bliss, before Thy face we fall!<br/>Majesty and greatness, glory, praise and power<br/>To Thee belong, eternal Source of all!<br/>',NULL,9,9);
INSERT INTO stanza VALUES('E3','1','Come, Thou Almighty King,<br/>Help us Thy name to sing,<br/>Help us to praise.<br/>Father, all glorious,<br/>O''er all victorious,<br/>Come, and reign over us,<br/>Ancient of Days.<br/>',NULL,10,10);
INSERT INTO stanza VALUES('E3','2','Come, Thou incarnate Word,<br/>Gird on Thy mighty sword,<br/>Our prayer attend:<br/>Come, and Thy people bless,<br/>And give Thy word success;<br/>Spirit of holiness,<br/>On us descend.<br/>',NULL,11,11);
INSERT INTO stanza VALUES('E3','3','Come, holy Comforter,<br/>Thy sacred witness bear<br/>In this glad hour:<br/>Thou who Almighty art,<br/>Now rule in every heart,<br/>And ne''er from us depart,<br/>Spirit of power.<br/>',NULL,12,12);
INSERT INTO stanza VALUES('E3','4','To Thee, great One in Three,<br/>Eternal praises be<br/>Hence evermore.<br/>Thy sov''reign majesty<br/>May we in glory see,<br/>And to eternity<br/>Love and adore.<br/>',NULL,13,13);
INSERT INTO stanza VALUES('E4','1','Father of heav''n, whose love profound<br/>A ransom for our souls hath found,<br/>Before Thy throne we sinners bend;<br/>To us Thy pardoning love extend.<br/>',NULL,14,14);
INSERT INTO stanza VALUES('E4','2','Almighty Son, incarnate Word,<br/>Our Prophet, Priest, Redeemer, Lord,<br/>Before Thy throne we sinners bend;<br/>To us Thy saving grace extend.<br/>',NULL,15,15);
INSERT INTO stanza VALUES('E4','3','Eternal Spirit, by whose breath<br/>The soul is raised from sin and death,<br/>Before Thy throne we sinners bend;<br/>To us Thy quickening power extend.<br/>',NULL,16,16);
INSERT INTO stanza VALUES('E4','4','Thrice holy-Father, Spirit, Son;<br/>Mysterious Godhead, Three in One,<br/>Before Thy throne we sinners bend;<br/>Grace, pardon, life to us extend.<br/>',NULL,17,17);
INSERT INTO stanza VALUES('E5','1','God, our Father, we adore Thee!<br/>We, Thy children, bless Thy Name!<br/>Chosen in the Christ before Thee,<br/>We are "holy without blame."<br/>We adore Thee! We adore Thee!<br/>Abba''s praises we proclaim!<br/>We adore Thee! We adore Thee!<br/>Abba''s praises we proclaim!<br/>',NULL,18,18);
INSERT INTO stanza VALUES('E5','2','Son Eternal, we adore Thee!<br/>Lamb upon the throne on high!<br/>Lamb of God, we bow before Thee,<br/>Thou hast brought Thy people nigh!<br/>We adore Thee! We adore Thee!<br/>Son of God, Who came to die!<br/>We adore Thee! We adore Thee!<br/>Son of God, Who came to die!<br/>',NULL,19,19);
INSERT INTO stanza VALUES('E5','3','Father, Son and Holy Spirit-<br/>Three in One! We give Thee praise!<br/>For the riches we inherit,<br/>Heart and voice to Thee we raise!<br/>We adore Thee! We adore Thee!<br/>Thee we bless, through endless days!<br/>We adore Thee! We adore Thee!<br/>Thee we bless, through endless days!<br/>',NULL,20,20);
INSERT INTO stanza VALUES('E6','1','Holy, Holy, Holy, Lord God Almighty!<br/>Unto everlasting days our song shall rise to Thee;<br/>Holy, Holy, Holy, Merciful and Mighty!<br/>God in Three Persons, blessed Trinity!<br/>',NULL,21,21);
INSERT INTO stanza VALUES('E6','2','Holy, Holy, Holy! All the saints adore Thee;<br/>Heaven''s elders cast their crowns down by the glassy sea;<br/>Cherubim and seraphim worship too before Thee,<br/>Who wert, and art, and evermore shalt be.<br/>',NULL,22,22);
INSERT INTO stanza VALUES('E6','3','Holy, Holy, Holy! Though the darkness hide Thee,<br/>Though the eye of sinful man Thy glory may not see,<br/>Only Thou art holy, there is none beside Thee<br/>Perfect in power, in love, and purity.<br/>',NULL,23,23);
INSERT INTO stanza VALUES('E7','1','Glory, glory to the Father!<br/>Glory, glory to the Son!<br/>Glory, glory to the Spirit!<br/>Glory to the Three in One!<br/>',NULL,24,24);
INSERT INTO stanza VALUES('E7','chorus','Let us praise Him! Let us praise Him!<br/>Praise our God, the Three in One!<br/>Give Him glory; give Him glory!<br/>Wondrous things for us our God hath done!<br/>',NULL,25,25);
INSERT INTO stanza VALUES('E7','2','Praise the Father who has purposed!<br/>Praise the Son who all has done!<br/>Praise the Spirit who transmitteth!<br/>Praise the Three who work as one!<br/>',NULL,26,26);
INSERT INTO stanza VALUES('E8','1','Praise God, from whom all blessings flow;<br/>Praise Him, all creatures here below;<br/>Praise Him above, ye heav''nly host;<br/>Praise Father, Son, and Holy Ghost!<br/>',NULL,27,27);
INSERT INTO stanza VALUES('E8','2','Praise God the Father who''s the source;<br/>Praise God the Son who is the course;<br/>Praise God the Spirit who''s the flow;<br/>Praise God, our portion here below!<br/>',NULL,28,28);
INSERT INTO stanza VALUES('E9','1','Glory be to God the Father,<br/>Glory be to God the Son,<br/>Glory be to God the Spirit,<br/>Great Jehovah, Three in One!<br/>As it was, is now, and shall be<br/>While the endless ages run.<br/>',NULL,29,29);
INSERT INTO stanza VALUES('E10','1','O God, th'' eternal Father, Thou,<br/>The uncreated, great I AM!<br/>More ancient than the ancients are,<br/>Before the primal age began!<br/>',NULL,30,30);
INSERT INTO stanza VALUES('E10','2','From everlasting Thou art God,<br/>All time and space Thou dost transcend!<br/>The fulness of eternity,<br/>Without beginning, without end!<br/>',NULL,31,31);
INSERT INTO stanza VALUES('E10','3','Th'' eternal source of all Thou art,<br/>Before the heavens were decreed!<br/>Thou art the first of all the first,<br/>And e''en the foremost dost precede!<br/>',NULL,32,32);
INSERT INTO stanza VALUES('E10','4','Thou art the life that ever lasts,<br/>From age to age Thou endest not!<br/>More lasting than all that which lasts,<br/>Beyond the ultimate Thou art!<br/>',NULL,33,33);
INSERT INTO stanza VALUES('E10','5','Thou art the Alpha as the first,<br/>Omega, as the last Thou art!<br/>From start to end Thou hast no lack, Complete<br/>and perfect, wanting not!<br/>',NULL,34,34);
INSERT INTO stanza VALUES('E10','6','We praise Thee for Thine endless years,<br/>Extol Thee for Thy boundlessness!<br/>We praise Thee for Thy fulness vast,<br/>Extol Thee for Thy perfectness<br/>',NULL,35,35);
INSERT INTO stanza VALUES('E11','1','Thou, Father, who art Spirit true,<br/>The holiest of all;<br/>We worship in the spirit now,<br/>In truth upon Thee call.<br/>',NULL,36,36);
INSERT INTO stanza VALUES('E11','2','A spirit Thou hast made for us<br/>That we may worship Thee,<br/>That echoing in spirit thus<br/>One spirit we will be.<br/>',NULL,37,37);
INSERT INTO stanza VALUES('E11','3','The Father in the Son has come,<br/>The Son the Spirit is,<br/>That to our spirit God may come.<br/>O what a grace is this!<br/>',NULL,38,38);
INSERT INTO stanza VALUES('E11','4','The Son is Thine eternal Word,<br/>The Word is Spirit too;<br/>The Spirit as our life has come<br/>Our spirit to renew.<br/>',NULL,39,39);
INSERT INTO stanza VALUES('E11','5','Thy Spirit in our spirit is,<br/>And thus in unity<br/>Thy Spirit witnesseth with ours<br/>That we are born of Thee.<br/>',NULL,40,40);
INSERT INTO stanza VALUES('E11','6','In everything Thy Spirit leads<br/>That we may follow Him;<br/>We thus may spiritual become,<br/>With life and peace within.<br/>',NULL,41,41);
INSERT INTO stanza VALUES('E11','7','In spirit we would worship Thee,<br/>In spirit Thee address,<br/>Until our spirit is released<br/>Thine image to express.<br/>',NULL,42,42);
INSERT INTO stanza VALUES('E11','8','Our Father, we would praise Thee now<br/>That Thou the Spirit art;<br/>In spirit and in truth to Thee<br/>True worship we impart.<br/>',NULL,43,43);
INSERT INTO stanza VALUES('E12','1','O God, Thou art the source of life,<br/>Divine, and rich and free!<br/>As living water flowing out<br/>Unto eternity<br/>',NULL,44,44);
INSERT INTO stanza VALUES('E12','2','In love Thou in the Son didst flow<br/>Among the human race;<br/>Thou dost as Spirit also flow<br/>Within us thru Thy grace.<br/>',NULL,45,45);
INSERT INTO stanza VALUES('E12','3','Though we in sin and wickedness<br/>Went far from Thee apace,<br/>Yet in the Son Thou didst redeem,<br/>Bestowing life and grace.<br/>',NULL,46,46);
INSERT INTO stanza VALUES('E12','4','Though we have often slighted Thee,<br/>Thy Spirit often grieved,<br/>Yet Thou dost still as Spirit come<br/>As life to be received.<br/>',NULL,47,47);
INSERT INTO stanza VALUES('E12','5','Thou as the Spirit in the Son<br/>Hast mingled heretofore;<br/>Thou wilt thru fellowship anoint.<br/>And increase more and more.<br/>',NULL,48,48);
INSERT INTO stanza VALUES('E12','6','The love of God, the grace of Christ,<br/>The Spirit''s flowing free,<br/>Enable us God''s wealth to share<br/>Thru all eternity.<br/>',NULL,49,49);
INSERT INTO stanza VALUES('E12','7','The Father, Son, and Spirit-one,<br/>So richly care for us;<br/>Thy love with one accord we sing<br/>And e''er would praise Thee thus.<br/>',NULL,50,50);
INSERT INTO stanza VALUES('E13','1','Thou art love and Thou art light, Lord,<br/>In the Son as life Thou art;<br/>Love expressing, light illum''ning,<br/>Thou dost life to us impart.<br/>',NULL,51,51);
INSERT INTO stanza VALUES('E13','chorus','Thou art love! Thou art light!<br/>In the Son as life Thou art;<br/>Love expressing, light illum''ning<br/>Thou dost life to us impart.<br/>',NULL,52,52);
INSERT INTO stanza VALUES('E13','2','Love bespeaks Thy very being,<br/>What Thou dost is shown by light;<br/>Love is inward, light is outward,<br/>Love accompanies the light.<br/>',NULL,53,53);
INSERT INTO stanza VALUES('E13','3','Love by grace is manifested,<br/>And the light by truth is shown;<br/>By Thy love we may enjoy Thee;<br/>By Thy light Thou, Lord, art known.<br/>',NULL,54,54);
INSERT INTO stanza VALUES('E13','4','Thru Thy love, which led to Calvary,<br/>We receive the life of God;<br/>Light our understanding opens,<br/>That we may apply the blood.<br/>',NULL,55,55);
INSERT INTO stanza VALUES('E13','5','Thru Thy love, as life Thou enter''st<br/>Fellowship with Thee to give;<br/>Thru Thy light we take Thy cleansing<br/>And in fellowship may live.<br/>',NULL,56,56);
INSERT INTO stanza VALUES('E13','6','By the light and blood which cleanses,<br/>The anointing we shall know;<br/>Then the life of love Thine essence,<br/>More and more in us will flow.<br/>',NULL,57,57);
INSERT INTO stanza VALUES('E13','7','By Thy love we are Thy children,<br/>Abba Father calling Thee;<br/>Light disperses all our darkness,<br/>Till, like Him, Thy Son, we see.<br/>',NULL,58,58);
INSERT INTO stanza VALUES('E13','chorus','O what grace! O what truth!<br/>Love is seen and light is shown!<br/>We would praise Thee never ceasing,<br/>Thou by love and light art known!<br/>',NULL,59,59);
INSERT INTO stanza VALUES('E14','1','Immortal, invisible, God only wise,<br/>In light inaccessible hid from our eyes,<br/>Most blessed, most glorious, the Ancient of Days,<br/>Almighty, victorious, Thy great name we praise.<br/>',NULL,60,60);
INSERT INTO stanza VALUES('E14','2','Unresting, unhasting, and silent as light,<br/>Nor wanting, nor wasting, Thou rulest in might;<br/>Thy justice like mountains high soaring above,<br/>Thy clouds which are fountains of goodness and love.<br/>',NULL,61,61);
INSERT INTO stanza VALUES('E14','3','To all life Thou givest, to both great and small;<br/>In all life Thou livest, the true life of all;<br/>We blossom and flourish as leaves on the tree,<br/>And wither and perish, but nought changeth Thee.<br/>',NULL,62,62);
INSERT INTO stanza VALUES('E14','4','Great Father of Glory, pure Father of Light,<br/>Thine angels adore Thee, all veiling their sight;<br/>All laud we would render, O help us to see:<br/>''Tis only the splendor of light hideth Thee.<br/>',NULL,63,63);
INSERT INTO stanza VALUES('E14','5','Immortal, invisible, God only wise,<br/>In light inaccessible hid from our eyes,<br/>Most blessed, most glorious, the Ancient of Days,<br/>Almighty, victorious, Thy great name we praise.<br/>',NULL,64,64);
INSERT INTO stanza VALUES('E15','1','O God, Thou art transcendent,<br/>The Holy One Thou art!<br/>None other is Thine equal,<br/>Incomp''rable Thou art!<br/>The holiest of the holy<br/>The universe may call!<br/>Thy power and Thy nature<br/>Do far exceed it all!<br/>',NULL,65,65);
INSERT INTO stanza VALUES('E15','2','Distinct, unique, and holy,<br/>Not only right and pure;<br/>Not only without defect,<br/>But with perfection more;<br/>For nothing can approach Thee,<br/>Nor e''er Thine equal be;<br/>If aught Thy place hath taken,<br/>''Tis insult unto Thee.<br/>',NULL,66,66);
INSERT INTO stanza VALUES('E15','3','The excellent excelling,<br/>The fairest of the fair,<br/>Yet differing from the finest,<br/>For none with Thee compare.<br/>From all the righteous different,<br/>For Thine is absolute;<br/>None beauteous with Thee vying,<br/>For Thine excels repute.<br/>',NULL,67,67);
INSERT INTO stanza VALUES('E15','4','Thy holiness transcendent<br/>Thou hast for us prepared,<br/>And this distinctive nature<br/>We have already shared.<br/>We share in Thy transcendence,<br/>Since we Thy nature own;<br/>Thy holy life we follow<br/>Till unto fulness grown.<br/>',NULL,68,68);
INSERT INTO stanza VALUES('E15','5','We give Thee praise and worship<br/>For all Thy holiness,<br/>For Thy transcendent nature,<br/>Thine utter peerlessness.<br/>We praise Thee that Thy nature-<br/>Unique, distinct-we share;<br/>This separating nature<br/>Is ours now and fore''er.<br/>',NULL,69,69);
INSERT INTO stanza VALUES('E16','1','Our Father, as the evergreen,<br/>Thou art forever new;<br/>Thou art the ever living Lord,<br/>Thy freshness as the dew.<br/>',NULL,70,70);
INSERT INTO stanza VALUES('E16','chorus','O Father, Thou art unchanging,<br/>Thou never hast grown old;<br/>Thru countless ages, ever fresh,<br/>Thy newness doth unfold.<br/>',NULL,71,71);
INSERT INTO stanza VALUES('E16','2','O Thou art God, and Thou art "new";<br/>Without Thee all is worn,<br/>But all with Thee is ever fresh,<br/>Though many years have gone.<br/>',NULL,72,72);
INSERT INTO stanza VALUES('E16','3','Each blessing Thou hast given us<br/>Thy newness doth contain;<br/>Thy covenant, Thy ways are new,<br/>And ever thus remain.<br/>',NULL,73,73);
INSERT INTO stanza VALUES('E16','4','Now we Thy new creation are<br/>New spirit and new heart;<br/>We''re daily from the old renewed,<br/>New life Thou dost impart.<br/>',NULL,74,74);
INSERT INTO stanza VALUES('E16','5','The earth and heavens will be new<br/>And Thy new city share;<br/>New fruits each month will be supplied,<br/>For all is newness there.<br/>',NULL,75,75);
INSERT INTO stanza VALUES('E16','6','O Father, Thou art ever new,<br/>And all is new in Thee;<br/>We sing the new eternal song,<br/>New praise we give to Thee.<br/>',NULL,76,76);
INSERT INTO stanza VALUES('E17','1','My Father God, when on Thy vast creation.<br/>The wonders of the heav''n and earth, I gaze.<br/>Things great and small, beyond enumeration,<br/>Which manifest Thy pow''r in untold ways;<br/>',NULL,77,77);
INSERT INTO stanza VALUES('E17','chorus','Then all my being sings in praise to Thee,<br/>How marvelous! How great Thou art!<br/>And this I''ll sing through all eternity,<br/>How marvelous! How great Thou art!<br/>',NULL,78,78);
INSERT INTO stanza VALUES('E17','2','As I enjoy the grace of Thy salvation<br/>And contemplate how Thou Thy Son hast sent,<br/>Who died that we might be Thy new creation,<br/>Thy life expressing to the full extent;<br/>',NULL,79,79);
INSERT INTO stanza VALUES('E17','3','When in the church, in blest participation,<br/>I see how millions Thine own life possess,<br/>How they are built to form Thy habitation,<br/>Containing Thee, Thy fulness to express;<br/>',NULL,80,80);
INSERT INTO stanza VALUES('E17','4','As I expect the coming age of fulness<br/>And hope to share the new Jerusalem,<br/>With all the heavens and the earth in newness<br/>And all Thou art expressed in all of them;<br/>',NULL,81,81);
INSERT INTO stanza VALUES('E18','1','How faithful and trustworthy too,<br/>My Father God, art Thou;<br/>The universe and all therein<br/>Thy faithfulness avow.<br/>',NULL,82,82);
INSERT INTO stanza VALUES('E18','chorus','How steadfast is Thy faithfulness!<br/>For this I worship Thee;<br/>It is established in the heav''n,<br/>And ever stands for me.<br/>',NULL,83,83);
INSERT INTO stanza VALUES('E18','2','No turning shadow could there be,<br/>Nor any change with Thee;<br/>As Thou hast been, and now Thou art,<br/>Forever Thou wilt be.<br/>',NULL,84,84);
INSERT INTO stanza VALUES('E18','3','Thy word, as certain as Thyself,<br/>Can never pass away;<br/>Though heav''n and earth shall disappear,<br/>Thy word abides for aye.<br/>',NULL,85,85);
INSERT INTO stanza VALUES('E18','4','Thy gifts without repentance are,<br/>Thy calling is the same;<br/>Thy grace forever lasting is,<br/>Thy mercy as Thy name.<br/>',NULL,86,86);
INSERT INTO stanza VALUES('E18','5','Thy word with Thine own faithfulness<br/>A surety is to me;<br/>By it, with Thy salvation true,<br/>I have the certainty.<br/>',NULL,87,87);
INSERT INTO stanza VALUES('E18','6','If, due to self, I trust Thee not,<br/>Yet Thou art faithful still;<br/>Thou never canst deny Thyself,<br/>Thy word Thou shalt fulfill.<br/>',NULL,88,88);
INSERT INTO stanza VALUES('E18','7','As Thou art faithful to perform<br/>Thy promise and Thy call;<br/>So, feeding on Thy faithfulness,<br/>I take Thyself withal.<br/>',NULL,89,89);
INSERT INTO stanza VALUES('E18','8','The rainbow round about Thy throne<br/>Thy faithfulness declares;<br/>This attribute forevermore<br/>The holy city bears.<br/>',NULL,90,90);
INSERT INTO stanza VALUES('E19','1','"Great is Thy faithfulness," O God my Father,<br/>There is no shadow of turning with Thee;<br/>Thou changest not, Thy compassions, they fail<br/>not; As Thou hast been Thou forever wilt be.<br/>',NULL,91,91);
INSERT INTO stanza VALUES('E19','chorus','"Great is Thy faithfulness!"<br/>"Great is Thy faithfulness!"<br/>Morning by morning new mercies I see;<br/>All I have needed Thy hand hath provided-<br/>"Great is Thy faithfulness," Lord, unto me!<br/>',NULL,92,92);
INSERT INTO stanza VALUES('E19','2','Summer and winter, and springtime and<br/>harvest, Sun, moon and stars in their courses above,<br/>Join with all nature in manifold witness<br/>To Thy great faithfulness, mercy and love.<br/>',NULL,93,93);
INSERT INTO stanza VALUES('E19','3','Pardon for sin and a peace that endureth,<br/>Thy own dear presence to cheer and to guide;<br/>Strength for today and bright hope for tomorrow,<br/>Blessings all mine, with ten thousand beside!<br/>',NULL,94,94);
INSERT INTO stanza VALUES('E20','1','God our Father, we adore Thee,<br/>For the sake of righteousness;<br/>Thou in Christ hast justified us,<br/>Who our conscience can depress?<br/>Thou art righteous, and art faithful,<br/>On Thy righteousness we stand;<br/>No unrighteousness is in Thee,<br/>None can turn Thy righteous hand.<br/>',NULL,96,96);
INSERT INTO stanza VALUES('E20','2','Thou hast laid our sins on Jesus,<br/>By Thy justice He was killed;<br/>All Thy holy law''s requirements<br/>For Thy justice He fulfilled.<br/>Recompense from Him receiving,<br/>Thou art fully satisfied;<br/>How couldst Thou, O God most righteous,<br/>Claim it once more from our side?<br/>',NULL,97,97);
INSERT INTO stanza VALUES('E20','3','Father God, Thou hast accepted<br/>Jesus as our Substitute;<br/>Judged the Just One for the unjust,<br/>Couldst Thou change Thy attitude?<br/>As a proof of perfect justice,<br/>At Thine own right hand He sits;<br/>He, as Thy full satisfaction,<br/>Righteously Thy need befits.<br/>',NULL,98,98);
INSERT INTO stanza VALUES('E20','4','Father, through the blood of Jesus<br/>We possess Thy righteousness;<br/>By Thy righteousness protected,<br/>None can shake our steadfastness.<br/>Righteousness of Thine Thou mad''st us,<br/>None can ever us condemn;<br/>We''ll forever testify this<br/>In the new Jerusalem.<br/>',NULL,99,99);
INSERT INTO stanza VALUES('E21','1','We praise Thee for Thy righteousness;<br/>Thy justice, Father, we confess,<br/>And fully testify.<br/>Thou art the judge of all mankind,<br/>In Thee injustice none can find,<br/>Nor wrong to Thee apply.<br/>',NULL,100,100);
INSERT INTO stanza VALUES('E21','2','O holy Father, righteous One,<br/>Thy righteousness upholds Thy throne,<br/>''Tis a foundation sure.<br/>''Tis through this righteousness of Thine<br/>That reigns in Christ the grace divine,<br/>And peace we thus secure.<br/>',NULL,101,101);
INSERT INTO stanza VALUES('E21','3','Thy righteousness has caused Thy Son<br/>To die for us that we be won,<br/>Redemption thus was bought;<br/>Thy righteousness has justified<br/>When Christ''s redemption was applied,<br/>Salvation thus was wrought.<br/>',NULL,102,102);
INSERT INTO stanza VALUES('E21','4','That Thou might show Thy righteousness,<br/>With Thy forgiveness Thou didst bless<br/>Men in the ancient age;<br/>For Thee Thy righteousness to show,<br/>Remission Thou dost now bestow<br/>On sinners in this age.<br/>',NULL,103,103);
INSERT INTO stanza VALUES('E21','5','All people Thou wilt judge one day,<br/>Thy righteousness to all display<br/>By Christ, Thy Son, our Lord;<br/>Yet fast we''ll stand, for none can move,<br/>Thy righteousness we''ll ever prove,<br/>With grace Thou wilt afford.<br/>',NULL,104,104);
INSERT INTO stanza VALUES('E21','6','With justice is Thy kingdom filled,<br/>And peace upon it Thou dost build<br/>With all in harmony;<br/>In the new heaven and new earth<br/>Thy righteousness will be their worth,<br/>As promised, God, by Thee.<br/>',NULL,105,105);
INSERT INTO stanza VALUES('E22','1','Holy Father, we adore Thee,<br/>Rev''rent song to Thee we raise;<br/>Thou art holy, Thou art lofty,<br/>"Holy is Thy Name," we praise.<br/>',NULL,106,106);
INSERT INTO stanza VALUES('E22','2','Loving is Thy heart, dear Father,<br/>Righteous ever are Thy ways;<br/>But how holy is Thy nature,<br/>Yet, to us, Christ it conveys.<br/>',NULL,107,107);
INSERT INTO stanza VALUES('E22','3','Thou hast ever sanctified us<br/>With the blood of Christ our Lord;<br/>Thou hast separated sinners<br/>Thru the truth which is Thy Word.<br/>',NULL,108,108);
INSERT INTO stanza VALUES('E22','4','Thou hast, by Thy Holy Spirit,<br/>Made us holy unto Thee;<br/>And our spirit, soul,. and body<br/>Wholly sanctified will be.<br/>',NULL,109,109);
INSERT INTO stanza VALUES('E22','5','Oh! The holy life of Jesus<br/>Thru Thy grace we now possess;<br/>Thou wilt make us e''en partakers<br/>Of Thy very holiness.<br/>',NULL,110,110);
INSERT INTO stanza VALUES('E22','6','When within that holy city,<br/>Thy full holiness we''ll share,<br/>To the uttermost forever,<br/>"Thou art holy," we''ll declare.<br/>',NULL,111,111);
INSERT INTO stanza VALUES('E23','1','In all Thy wisdom, Father God,<br/>According to Thy will,<br/>Eternal purpose Thou hast made<br/>That all Thy Son might fill.<br/>',NULL,112,112);
INSERT INTO stanza VALUES('E23','chorus','How deep and rich Thy wisdom is,<br/>O who can search and trace?<br/>Yet, Father God, in it we find<br/>Thy mercy and Thy grace!<br/>',NULL,113,113);
INSERT INTO stanza VALUES('E23','2','How wondrously Thou mad''st all things,<br/>O who can know Thy mind?<br/>All are of Thee, thru Thee, to Thee,<br/>Thy wisdom here we find.<br/>',NULL,114,114);
INSERT INTO stanza VALUES('E23','3','Thy wisdom shuts up all in sin,<br/>That mercy may be shown,<br/>That none may boast in anything<br/>But in Thyself alone.<br/>',NULL,115,115);
INSERT INTO stanza VALUES('E23','4','In wisdom, by the cross, Thou hast<br/>For us redemption made,<br/>That in our spirit we may have<br/>Thyself, the treasure, laid.<br/>',NULL,116,116);
INSERT INTO stanza VALUES('E23','5','Thy wisdom thru Thy Church is known<br/>By principalities,<br/>Thru us Thy wisdom manifold<br/>Shown in the heavenlies.<br/>',NULL,117,117);
INSERT INTO stanza VALUES('E23','6','When in the new Jerusalem<br/>In mercy we will boast,<br/>Thy wisdom will be known for aye<br/>Unto the uttermost.<br/>',NULL,118,118);
INSERT INTO stanza VALUES('E24','1','O God in Christ all focused is<br/>Thy wisdom with Thy grace;<br/>As wisdom Thou mad''st Him to us,<br/>In Him Thy way we trace.<br/>',NULL,119,119);
INSERT INTO stanza VALUES('E24','2','What Thou has planned is all in Him,<br/>Thy way of grace is He;<br/>In Him, Thy Wisdom, we have all,<br/>That glory be to Thee.<br/>',NULL,120,120);
INSERT INTO stanza VALUES('E24','3','In Him, who is our righteousness,<br/>Have we been justified;<br/>In Him, who is our holiness,<br/>We''re being sanctified.<br/>',NULL,121,121);
INSERT INTO stanza VALUES('E24','4','Redemption too He is to us,<br/>According to Thy plan,<br/>That we may fully be redeemed<br/>To be a perfect man.<br/>',NULL,122,122);
INSERT INTO stanza VALUES('E24','5','He is Thy wisdom, Father God,<br/>In Thine economy;<br/>For Him we offer praise to Thee<br/>With all humility.<br/>',NULL,123,123);
INSERT INTO stanza VALUES('E24','6','Thy wisdom we have seen in Him,<br/>So rich and so profound;<br/>Yet richer, deeper, in Thy way,<br/>By us will it be found.<br/>',NULL,124,124);
INSERT INTO stanza VALUES('E25','1','Father, to us Thy mercy Thou hast shown,<br/>In Thine own way;<br/>Sinners like us as dear sons Thou wouldst own,<br/>In love for aye.<br/>Vessels of mercy, Thou didst us prepare;<br/>Vessels of honor, we Thyself declare.<br/>',NULL,125,125);
INSERT INTO stanza VALUES('E25','2','"In mercy I delight, not sacrifice,"<br/>Thou hast declared;<br/>Thru this Thy mercy, favor in Thine eyes<br/>We all have shared.<br/>''Tis not of them that will nor them that run,<br/>But of Thee showing mercy as was done.<br/>',NULL,126,126);
INSERT INTO stanza VALUES('E25','3','Father, Thy mercy with Thy love and grace<br/>Did we obtain;<br/>And in Thy mercy, with Thee face to face,<br/>We''ll e''er remain;<br/>And for Thy mercy we would worship Thee<br/>Through all our days and through eternity.<br/>',NULL,127,127);
INSERT INTO stanza VALUES('E26','1','God, we praise Thee for Thy mercy,<br/>''Tis so great and so profound!<br/>In our weakness and our failures;<br/>With its greatness it abounds.<br/>We adore Thee! We adore Thee!<br/>With such mercy we''ve been crowned!<br/>',NULL,128,128);
INSERT INTO stanza VALUES('E26','2','How we marvel at this mercy<br/>So far-reaching and so vast!<br/>It has reached us, e''en the sinners,<br/>And will ever hold us fast.<br/>From this mercy, from this mercy,<br/>What can cause us to be cast?<br/>',NULL,129,129);
INSERT INTO stanza VALUES('E26','3','For Thy mercy we are grateful,<br/>''Tis so rich, so plenteous!<br/>Thru Thy mercy in redemption,<br/>Thou hast richly favored us.<br/>If without this, if without this,<br/>How could we be favored thus?<br/>',NULL,130,130);
INSERT INTO stanza VALUES('E26','4','Oh, Thy mercy, so inspiring!<br/>Gentle, tender, dear and sweet!<br/>With Thy patience and Thy kindness,<br/>Us in all our need it meets.<br/>It we treasure, it we treasure,<br/>Nothing can with it compete.<br/>',NULL,131,131);
INSERT INTO stanza VALUES('E26','5','Father we enjoy Thy mercy,<br/>Ever fresh and ever new;<br/>Every morning shed upon us,<br/>It refreshes as the dew.<br/>How we taste it! How we taste it!<br/>Giving Thee the praises due.<br/>',NULL,132,132);
INSERT INTO stanza VALUES('E26','6','We can never cease to praise Thee,<br/>As Thy mercy e''er endures;<br/>All Thy grace and all Thy favor,<br/>Ever for us it secures.<br/>Trusting in it, trusting in it,<br/>Thy sure mercy us assures.<br/>',NULL,133,133);
INSERT INTO stanza VALUES('E27','1','Come, let us all unite to sing,<br/>God is love, God is love.<br/>Let heav''n and earth their praises bring;<br/>God is love, God is love.<br/>Let ev''ry soul from sin awake,<br/>Each in his heart sweet music make,<br/>And sing with us, for Jesus'' sake,<br/>God is love! God is love!<br/>',NULL,134,134);
INSERT INTO stanza VALUES('E27','2','How happy is our portion here!<br/>God is love, God is love.<br/>His promises our spirits cheer;<br/>God is love, God is love.<br/>He is our sun and shield by day,<br/>Our help, our hope, our strength, and stay,<br/>He will be with us all the way:<br/>God is love! God is love!<br/>',NULL,135,135);
INSERT INTO stanza VALUES('E27','3','In glory we shall sing again,<br/>God is love, God is love.<br/>Yes, this shall be our lofty strain,<br/>God is love, God is love.<br/>While endless ages roll along,<br/>In concert with the heav''nly throng,<br/>This shall be still our sweetest song,<br/>God is love! God is love!<br/>',NULL,136,136);
INSERT INTO stanza VALUES('E28','1','The love of God is greater far<br/>Than tongue or pen can ever tell<br/>It goes beyond the highest star<br/>And reaches to the lowest hell.<br/>The guilty pair, bowed down with care,<br/>God gave His Son to win;<br/>His erring child He reconciled<br/>And pardoned from his sin.<br/>',NULL,137,137);
INSERT INTO stanza VALUES('E28','chorus','O love of God, how rich and pure!<br/>How measureless and strong!<br/>It shall forevermore endure<br/>The saints'' and angels'' song.<br/>',NULL,138,138);
INSERT INTO stanza VALUES('E28','2','When hoary time shall pass away,<br/>And earthly thrones and kingdoms fall;<br/>When men who here refuse to pray,<br/>On rocks and hills and mountains call;<br/>God''s love, so sure, shall still endure,<br/>All measureless and strong;<br/>Redeeming grace to Adam''s race -<br/>The saints'' and angels'' song.<br/>',NULL,139,139);
INSERT INTO stanza VALUES('E28','3','Could we with ink the ocean fill,<br/>And were the skies of parchment made;<br/>Were every stalk on earth a quill,<br/>And every man a scribe by trade;<br/>To write the love of God above<br/>Would drain the ocean dry;<br/>Nor could the scroll contain the whole,<br/>Though stretched from sky to sky<br/>',NULL,140,140);
INSERT INTO stanza VALUES('E29','1','What was it, blessed God,<br/>Led Thee to give Thy Son,<br/>To yield Thy Well-beloved<br/>For us by sin undone?<br/>''Twas love unbounded led Thee thus,<br/>''Twas love unbounded led Thee thus,<br/>To give Thy Well-beloved for us.<br/>',NULL,141,141);
INSERT INTO stanza VALUES('E29','2','What led Thy Son, O God,<br/>To leave Thy throne on high,<br/>To shed His precious blood,<br/>To suffer and to die?<br/>''Twas love-unbounded love to us<br/>''Twas love-unbounded love to us<br/>Led Him to die and suffer thus.<br/>',NULL,142,142);
INSERT INTO stanza VALUES('E29','3','What moved Thee to impart<br/>Thy Spirit from above,<br/>Therewith to fill our heart<br/>With heavenly peace and love?<br/>''Twas love-unbounded love to us,<br/>''Twas love-unbounded love to us<br/>Moved Thee to give Thy Spirit thus.<br/>',NULL,143,143);
INSERT INTO stanza VALUES('E29','4','What love to Thee we owe,<br/>Our God, for all Thy grace!<br/>Our hearts may well o''erflow<br/>In everlasting praise!<br/>Make us, O God, to praise Thee thus<br/>Make us, O God, to praise Thee thus<br/>For all Thy boundless love to us.<br/>',NULL,144,144);
INSERT INTO stanza VALUES('E30','1','What love Thou hast bestowed on us,<br/>We thank Thee from our heart;<br/>Our Father, we would worship Thee<br/>And praise for all Thou art.<br/>',NULL,145,145);
INSERT INTO stanza VALUES('E30','2','Thy heart Thou hast revealed to us,<br/>Made known th'' eternal will;<br/>Within the Son Thou hast come forth,<br/>Thy purpose to fulfill.<br/>',NULL,146,146);
INSERT INTO stanza VALUES('E30','3','Thou gavest Thy beloved Son<br/>In love to come and die,<br/>That we may be Thy many sons,<br/>As heirs with Him, made nigh.<br/>',NULL,147,147);
INSERT INTO stanza VALUES('E30','4','Through Him we have Thy very life<br/>And Thou our Father art;<br/>Thy very nature, all Thyself,<br/>Thou dost to us impart.<br/>',NULL,148,148);
INSERT INTO stanza VALUES('E30','5','Thy Spirit into ours has come<br/>That we may "Abba" cry;<br/>Of Spirit born, with Spirit sealed,<br/>To be transformed thereby.<br/>',NULL,149,149);
INSERT INTO stanza VALUES('E30','6','The many sons to glory brought<br/>Is Thine eternal goal,<br/>And to Thy Son''s own image wrought,<br/>Thou wilt conform the whole.<br/>',NULL,150,150);
INSERT INTO stanza VALUES('E30','7','Throughout Thy transformation work<br/>Thou dost direct each one,<br/>From glory unto glory bring<br/>Until the work is done.<br/>',NULL,151,151);
INSERT INTO stanza VALUES('E30','8','What love Thou, Father, hast bestowed;<br/>We''ll ever grateful be;<br/>We''ll worship Thee forevermore<br/>And praise unceasingly.<br/>',NULL,152,152);
INSERT INTO stanza VALUES('E31','1','All that we were-our sin, our guilt,<br/>Our death-was all our own:<br/>All that we are we owe to Thee,<br/>Thou God of grace alone.<br/>',NULL,153,153);
INSERT INTO stanza VALUES('E31','2','Thy mercy found us in our sins,<br/>And gave us to believe;<br/>Then, in believing, peace we found,<br/>And in Thy Christ we live.<br/>',NULL,154,154);
INSERT INTO stanza VALUES('E31','3','All that we are, as saints on earth,<br/>All that we hope to be,<br/>When Jesus comes and glory dawns,<br/>We owe it all to Thee.<br/>',NULL,155,155);
INSERT INTO stanza VALUES('E31','4','O God, how rich, how vast Thy love,<br/>Whoe''er can Thee repay?<br/>Thy love is past man''s finding out,<br/>Thy grace no man can say.<br/>',NULL,156,156);
INSERT INTO stanza VALUES('E31','5','But Lord, to me I pray Thee grant,<br/>More clearly may I see,<br/>That I may e''er more fully know<br/>How much I owe to Thee.<br/>',NULL,157,157);
INSERT INTO stanza VALUES('E31','6','But if man''s heart should e''er suppose<br/>He could repay Thy love,<br/>It only means he nothing knows<br/>Of love, all loves above.<br/>',NULL,158,158);
INSERT INTO stanza VALUES('E31','7','So may we never bargains make<br/>With that dear love of Thine:<br/>The love that made Thine heart once break,<br/>Whoe''er that love could win?<br/>',NULL,159,159);
INSERT INTO stanza VALUES('E31','8','Then nevermore suggest return,<br/>His love is far too high;<br/>But let our hearts with rapture burn<br/>That He for us should die.<br/>',NULL,160,160);
INSERT INTO stanza VALUES('E31','9','O Father God, we owe Thee all!<br/>All that we are and have!<br/>With grateful thanks before Thee fall,<br/>''Tis all that we can give.<br/>',NULL,161,161);
INSERT INTO stanza VALUES('E32','1','We bow and worship, Father, here<br/>And marvel at Thy wondrous love.<br/>O what is man that Thou shouldst deign<br/>To him such boundless grace to prove!<br/>',NULL,162,162);
INSERT INTO stanza VALUES('E32','2','We praise Thee for Thy heart''s intent<br/>That man Thy likeness should possess,<br/>That with Thy life and nature filled<br/>Thine image he should manifest.<br/>',NULL,163,163);
INSERT INTO stanza VALUES('E32','3','Man in Thine image Thou didst make,<br/>To him authority didst give;<br/>Thyself presenting as his life,<br/>That by Thy riches he might live.<br/>',NULL,164,164);
INSERT INTO stanza VALUES('E32','4','To enter man Thou dost desire,<br/>With him to mingle thru Thy grace,<br/>That man may be transformed and built<br/>To be Thy worthy dwelling place.<br/>',NULL,165,165);
INSERT INTO stanza VALUES('E32','5','Tho'' man did fall, Thou didst not leave<br/>Thy heart''s intent, but Thou didst move;<br/>Redeeming man to bring him back,<br/>Thou didst Thy love and wisdom prove.<br/>',NULL,166,166);
INSERT INTO stanza VALUES('E32','6','In Christ Thou didst Thyself reveal,<br/>Who died and rose, redemption wrought;<br/>In Spirit Thou hast entered man<br/>And to him life and grace hast brought.<br/>',NULL,167,167);
INSERT INTO stanza VALUES('E32','7','My spirit is Thy holiest place,<br/>Thy throne of grace is founded there;<br/>Thou wouldst that we in spirit come<br/>To burn the incense thru our prayer.<br/>',NULL,168,168);
INSERT INTO stanza VALUES('E32','8','Such grace is like a river full<br/>Which from the throne of grace doth come;<br/>It floweth thru, transforming us,<br/>And builds us up to be Thy home.<br/>',NULL,169,169);
INSERT INTO stanza VALUES('E32','9','Receiving of Thy matchless grace,<br/>We marvel at Thy gift so free;<br/>With grateful hearts for Thy great love,<br/>In spirit now we worship Thee.<br/>',NULL,170,170);
INSERT INTO stanza VALUES('E33','1','Father, long before creation,<br/>Thou hadst chosen us in love;<br/>And that love, so deep, so moving,<br/>Draws us close to Christ above,<br/>And will keep us, and will keep us,<br/>Firmly fixed in Christ alone,<br/>Firmly fixed in Christ alone.<br/>',NULL,171,171);
INSERT INTO stanza VALUES('E33','2','Though the world may change its fashion,<br/>Yet our God is e''er the same;<br/>His compassion and His cov''nant<br/>Through all ages will remain.<br/>God''s own children, God''s own children,<br/>Must forever praise His name,<br/>Must forever praise His name.<br/>',NULL,172,172);
INSERT INTO stanza VALUES('E33','3','God''s compassion is my story,<br/>Is my boasting all the day;<br/>Mercy free and never failing<br/>Moves my will, directs my way.<br/>God so loved us, God so loved us,<br/>That His only Son He gave,<br/>That His only Son He gave.<br/>',NULL,173,173);
INSERT INTO stanza VALUES('E33','4','Loving Father, now before Thee<br/>We will ever praise Thy love;<br/>And our song will sound unceasing<br/>Till we meet Thy Son above,<br/>Giving glory, giving glory,<br/>To our God and to the Lamb,<br/>To our God and to the Lamb.<br/>',NULL,174,174);
INSERT INTO stanza VALUES('E34','1','Father, ''twas Thy love that knew us<br/>Earth''s foundation long before:<br/>That same love to Jesus drew us<br/>By its sweet constraining pow''r,<br/>And will keep us, and will keep us,<br/>Safely now, and evermore,<br/>Safely now, and evermore.<br/>',NULL,175,175);
INSERT INTO stanza VALUES('E34','2','Now that changeless love enfolds us,<br/>All its wealth on us bestows;<br/>While its pow''r unchanging holds us<br/>In a holy calm repose.<br/>God and Father, God and Father,<br/>Unto Thee our worship flows,<br/>Unto Thee our worship flows.<br/>',NULL,176,176);
INSERT INTO stanza VALUES('E34','3','God of love, our souls adore Thee!<br/>We would still Thy grace proclaim,<br/>Till we cast our crowns before Thee,<br/>And in glory praise Thy name;<br/>Praise and worship, praise and worship<br/>Be to God and to the Lamb!<br/>Be to God and to the Lamb!<br/>',NULL,177,177);
INSERT INTO stanza VALUES('E35','1','Blest Father of glory, we worship:<br/>Thy greatness surpasses our praise;<br/>We bless Thee Thy Spirit within us<br/>Gives pow''r to these heavenly lays.<br/>',NULL,178,178);
INSERT INTO stanza VALUES('E35','2','We think of the Man in Thy presence,<br/>Set down there, exalted as Head;<br/>Once raised by the might of Thy power,<br/>When numbered along with the dead.<br/>',NULL,179,179);
INSERT INTO stanza VALUES('E35','3','We think of the glory that chose us,<br/>''Twas Thine, blessed Father, the Source;<br/>The glory of love that redeemed us<br/>Through Jesus, the Man of Thy choice.<br/>',NULL,180,180);
INSERT INTO stanza VALUES('E35','4','As marked out beforehand for sonship,<br/>We praise now the glory of grace<br/>And bow in Thy presence and worship,<br/>As conscious, in Christ, of our place.<br/>',NULL,181,181);
INSERT INTO stanza VALUES('E36','1','We praise Thee, glorious Father,<br/>As objects of Thy grace,<br/>Who for Thine own heart''s pleasure<br/>Are now before Thy face:<br/>Thy sons marked out for glory-<br/>Known from eternity-<br/>With Christ Thy Well-beloved,<br/>Object supreme to Thee.<br/>',NULL,182,182);
INSERT INTO stanza VALUES('E36','2','Who else but Thee, O Father,<br/>Could in Thine only Son<br/>So bless us with Thy Spirit,<br/>And have us for Thine own?<br/>Soon shall we be forever<br/>With Christ in glory; then<br/>We''ll shine in His blest image<br/>Eternally, Amen!<br/>',NULL,183,183);
INSERT INTO stanza VALUES('E37','1','O God! We see Thee in the Lamb<br/>To be our hope, our joy, our rest;<br/>The glories that compose Thy name<br/>Standing engaged to make us blest.<br/>',NULL,184,184);
INSERT INTO stanza VALUES('E37','2','Thou great and good! Thou just and wise!<br/>Hail! As our Father and our God!<br/>For we are Thine by sacred ties,<br/>Thy sons and daughters-bought with blood.<br/>',NULL,185,185);
INSERT INTO stanza VALUES('E37','3','Then, Oh! To us this grace afford,<br/>That far from Thee we ne''er may move;<br/>Our guard-the presence of the Lord;<br/>Our joy-Thy perfect present love.<br/>',NULL,186,186);
INSERT INTO stanza VALUES('E37','4','This gives us ever to rejoice,<br/>Turning to light our darkest days:<br/>And lifts on high each feeble voice,<br/>While we have breath to pray or praise.<br/>',NULL,187,187);
INSERT INTO stanza VALUES('E38','1','Of all the gifts Thy love bestows,<br/>Thou Giver of all good!<br/>E''en heav''n itself no richer knows<br/>Than Jesus and His blood.<br/>',NULL,188,188);
INSERT INTO stanza VALUES('E38','2','Faith, too, that trusts in Him through grace,<br/>From that same love we gain;<br/>Else, sweetly as it suits our case,<br/>The gift had been in vain.<br/>',NULL,189,189);
INSERT INTO stanza VALUES('E38','3','We praise Thee, and would praise Thee more,<br/>To Thee our all we owe:<br/>The precious Savior, and the power<br/>That makes Him precious too.<br/>',NULL,190,190);
INSERT INTO stanza VALUES('E39','1','To God be the glory, great things He hath done,<br/>So loved He the world that He gave us His Son,<br/>Who yielded His life our redemption to win,<br/>And opened the life-gate that all may go in.<br/>',NULL,191,191);
INSERT INTO stanza VALUES('E39','chorus','Praise the Lord, praise the Lord,<br/>Let the earth hear His voice:<br/>Praise the Lord, praise the Lord,<br/>Let the people rejoice;<br/>Oh, come to the Father, through Jesus the<br/>Son, And give Him the glory; great things He hath done.<br/>',NULL,192,192);
INSERT INTO stanza VALUES('E39','2','Oh, perfect redemption, the purchase of blood,<br/>To every believer the promise of God;<br/>The vilest offender who truly believes,<br/>That moment from Jesus a pardon receives.<br/>',NULL,193,193);
INSERT INTO stanza VALUES('E39','3','Great things He hath taught us, great things He<br/>hath done,<br/>And great our rejoicing through Jesus the Son;<br/>But purer, and higher, and greater will be<br/>Our wonder, our transport when Jesus we see.<br/>',NULL,194,194);
INSERT INTO stanza VALUES('E40','1','We praise Thee, O God,<br/>For the Son of Thy love,<br/>For our Savior who died and<br/>Is now gone above.<br/>',NULL,195,195);
INSERT INTO stanza VALUES('E40','chorus','Hallelujah! Thine the glory,<br/>Hallelujah! Amen;<br/>Hallelujah! Thine the glory,<br/>We praise Thee again.<br/>',NULL,196,196);
INSERT INTO stanza VALUES('E40','2','We praise Thee, O God,<br/>For Thy Spirit of light,<br/>Who has shown us our Savior,<br/>And scattered our night.<br/>',NULL,197,197);
INSERT INTO stanza VALUES('E40','3','All glory and praise<br/>To Thee, Father of love,<br/>For through Jesus'' redemption<br/>Thy heart we may prove.<br/>',NULL,198,198);
INSERT INTO stanza VALUES('E40','4','We praise Thee again;<br/>We are filled with Thy love,<br/>And each heart is rekindled<br/>With fire from above.<br/>',NULL,200,200);
INSERT INTO stanza VALUES('E41','1','We are never weary singing our eternal song:<br/>Glory to God, hallelujah!<br/>We would sing His praise forever with our<br/>spirit strong: Glory to God, hallelujah!<br/>',NULL,201,201);
INSERT INTO stanza VALUES('E41','chorus','O the children of the Lord have a wondrous<br/>song to sing,<br/>For the Lord will by His grace many sons<br/>to glory bring.<br/>We are going in that day to the presence of<br/>the King:<br/>Glory to God, hallelujah!<br/>',NULL,202,202);
INSERT INTO stanza VALUES('E41','2','We are lost amid the rapture of redeeming love:<br/>Glory to God, hallelujah!<br/>We are seeking every moment all its grace to<br/>prove:<br/>Glory to God, hallelujah!<br/>',NULL,203,203);
INSERT INTO stanza VALUES('E41','3','We are going on to glory as the Lord has told:<br/>Glory to God, hallelujah!<br/>Where the King in all His beauty we shall soon behold:<br/>Glory to God, hallelujah!<br/>',NULL,204,204);
INSERT INTO stanza VALUES('E41','4','There we''ll sing His grace and mercy in a glad<br/>new song:<br/>Glory to God, hallelujah!<br/>There we''ll praise our glorious Savior with the<br/>blessed throng:<br/>Glory to God, hallelujah!<br/>',NULL,205,205);
INSERT INTO stanza VALUES('E42','1','By Thee, O God, invited,<br/>We look unto the Son,<br/>In whom Thy heart delighted,<br/>Who all Thy will hath done;<br/>And by the one chief treasure<br/>Thy bosom freely gave,<br/>Thine own pure love we measure,<br/>Thy willing mind to save.<br/>',NULL,206,206);
INSERT INTO stanza VALUES('E42','2','O God of mercy-Father!<br/>The one unchanging claim,<br/>The brightest hopes, we gather<br/>From Christ''s most precious name:<br/>What always sounds so sweetly<br/>In Thine unwearied ear,<br/>Has freed our souls completely<br/>From all our guilt and fear.<br/>',NULL,207,207);
INSERT INTO stanza VALUES('E42','3','The trembling sinner feareth<br/>That God can ne''er forget;<br/>But one full payment cleareth<br/>His memory of all debt.<br/>When nought beside could free us,<br/>Or set our souls at large,<br/>The death of God''s Beloved<br/>Secured a full discharge.<br/>',NULL,208,208);
INSERT INTO stanza VALUES('E42','4','No wrath God''s heart retaineth<br/>To usward who believe;<br/>No dread in ours remaineth<br/>As we His love receive;<br/>Returning sons He kisses,<br/>And with His robe invests;<br/>His perfect love dismisses<br/>All terror from our breasts.<br/>',NULL,209,209);
INSERT INTO stanza VALUES('E43','1','"Abba, Father," we approach Thee<br/>In our Savior''s precious name.<br/>We, Thy children, here assembling,<br/>Now the promised blessing claim.<br/>From our guilt His blood has washed us,<br/>''Tis through Him our souls draw nigh,<br/>And Thy Spirit too has taught us<br/>"Abba, Father," thus to cry.<br/>',NULL,210,210);
INSERT INTO stanza VALUES('E43','2','Once as prodigals we wandered,<br/>In our folly, far from Thee;<br/>But Thy grace, o''er sin abounding,<br/>Rescued us from misery.<br/>Clothed in garments of salvation<br/>At Thy table is our place;<br/>We rejoice, and Thou rejoicest,<br/>In the riches of Thy grace.<br/>',NULL,211,211);
INSERT INTO stanza VALUES('E43','3','Thou the prodigal hast pardoned,<br/>"Kissed us" with a Father''s love;<br/>"Killed the fatted calf," and made us<br/>Fit Thy purpose to approve<br/>"It is meet," we hear Thee saying,<br/>"We should merry be and glad;<br/>I have found My once-lost children,<br/>Now they live who once were dead."<br/>',NULL,212,212);
INSERT INTO stanza VALUES('E43','4','"Abba, Father," we adore Thee,<br/>While the hosts in heaven above<br/>E''en in us now learn the wonders<br/>Of Thy wisdom, grace, and love.<br/>Soon before Thy throne assembled,<br/>All Thy children shall proclaim<br/>Abba''s love shown in redemption,<br/>And how full is Abba''s name!<br/>',NULL,213,213);
INSERT INTO stanza VALUES('E44','1','O Holy Father, who in tender love<br/>Didst give Thine only Son for us to die,<br/>The while He pleads at Thy right hand above,<br/>We in one Spirit now with faith draw nigh;<br/>And, as we eat this bread and drink this wine,<br/>Plead His once offered sacrifice Divine.<br/>',NULL,214,214);
INSERT INTO stanza VALUES('E44','2','We are not worthy to be called Thy sons,<br/>Nor gather up the fragments of Thy feast;<br/>Yet look on us, Thy sorrowing contrite ones,<br/>On us in Him our Advocate and Priest,<br/>Whose robe is fringed with mercy''s golden bells,<br/>Whose breastplate fathomless compassion tells.<br/>',NULL,215,215);
INSERT INTO stanza VALUES('E44','3','Oh, hear us, for Thou always hearest Him;<br/>Behold us sprinkled with His precious blood;<br/>And from between the shadowing cherubim<br/>Shine forth, and grant us by this heav''nly food<br/>Foretastes of coming glory, and meanwhile<br/>A Father''s blessing and a Father''s smile.<br/>',NULL,216,216);
INSERT INTO stanza VALUES('E44','4','And, Father, ere we leave Thy mercy-throne,<br/>Bound by these sacred pledges, yet most free,<br/>We give our hearts, and not our hearts alone,<br/>But all we are and all we have to Thee;<br/>Glad free-will offerings all our pilgrim days,<br/>Hereafter an eternity of praise.<br/>',NULL,217,217);
INSERT INTO stanza VALUES('E45','1','Abba, Father! We adore Thee,<br/>Humbly now our homage pay;<br/>''Tis Thy children''s bliss to know Thee,<br/>None but children "Abba" say.<br/>This high honor we inherit,<br/>Thy free gift through Jesus'' blood;<br/>God the Spirit, with our spirit,<br/>Witnesseth we''re sons of God.<br/>',NULL,218,218);
INSERT INTO stanza VALUES('E45','2','Thine own purpose gave us being''<br/>When in Christ, in that vast plan,<br/>Thou in Christ didst choose Thy people<br/>E''en before the world began.<br/>Oh, what love Thou, Father, bore us!<br/>Oh, how precious in Thy sight!<br/>When to Thine own Son Thou gav''st us,<br/>To Thy Son, Thy soul''s delight.<br/>',NULL,219,219);
INSERT INTO stanza VALUES('E45','3','Though our nature''s fall in Adam<br/>Shut us wholly out from God,<br/>Thine eternal counsel brought us<br/>Nearer still, through Jesus'' blood;<br/>For in Him we found redemption,<br/>Grace and glory in Thy Son;<br/>O the height and depth of mercy!<br/>Christ and His redeemed are one.<br/>',NULL,220,220);
INSERT INTO stanza VALUES('E45','4','Hence, through all the changing seasons,<br/>Trouble, sickness, sorrow, woe,<br/>Nothing changeth Thine affections,<br/>Love divine shall bring us through;<br/>Soon shall all Thy blood-bought children<br/>Round the throne their anthems raise,<br/>And, in songs of rich salvation,<br/>Shout to Thine eternal praise.<br/>',NULL,221,221);
INSERT INTO stanza VALUES('E46','1','O gracious God, Thy pleasure<br/>Is in Thy Christ made known,<br/>And tells the boundless measure<br/>Of blessing for Thine own.<br/>He has Thy presence entered,<br/>As Man in heav''n is known;<br/>In Him Thy glory''s centered,<br/>In Him Thy purpose shown.<br/>',NULL,222,222);
INSERT INTO stanza VALUES('E46','2','And O what love is beaming<br/>Refulgent in that face!<br/>What blessed light is streaming<br/>From that most glorious place!<br/>Both love and light proclaiming<br/>What Thou, the Father, art,<br/>And wondrous grace revealing,<br/>With Thine own Son, our part.<br/>',NULL,223,223);
INSERT INTO stanza VALUES('E46','3','Thou source of every blessing!<br/>Thou spring of all delight!<br/>Thy Name with joy confessing<br/>Let all the saints unite!<br/>Each heart its praise outpouring<br/>To Thee all praise above,<br/>Each voice in strains adoring<br/>Re-echoes-"God is love."<br/>',NULL,224,224);
INSERT INTO stanza VALUES('E47','1','Father, Thy name our souls would bless,<br/>As children taught by grace,<br/>Lift up our hearts in righteousness,<br/>And joy before Thy face.<br/>',NULL,225,225);
INSERT INTO stanza VALUES('E47','2','Sweet is the confidence Thou giv''st,<br/>Though high above our praise;<br/>Our hearts resort to where Thou liv''st<br/>In heaven''s unclouded rays,<br/>',NULL,226,226);
INSERT INTO stanza VALUES('E47','3','Eternal ages shall declare<br/>The riches of Thy grace,<br/>To those who with Thy Son shall share<br/>A son''s eternal place.<br/>',NULL,227,227);
INSERT INTO stanza VALUES('E47','4','Absent as yet, we rest in hope,<br/>Treading the desert path,<br/>Waiting for Him who takes us up<br/>Beyond the pow''r of death.<br/>',NULL,228,228);
INSERT INTO stanza VALUES('E47','5','We joy in Thee, Thy fulness shall<br/>Our endless portion be,<br/>Like Thine own Son, with whom we''ll dwell<br/>In bright eternity.<br/>',NULL,229,229);
INSERT INTO stanza VALUES('E47','6','O Holy Father, keep us here<br/>In that blest name of love,<br/>Walking before Thee without fear,<br/>Thy perfect will to prove.<br/>',NULL,230,230);
INSERT INTO stanza VALUES('E48','1','We bless Thee, God and Father,<br/>We joy before Thy face;<br/>Beyond dark death for ever,<br/>We share Thy Son''s blest place.<br/>He lives a Man before Thee,<br/>In cloudless light above,<br/>In Thine unbounded favor,<br/>Thine everlasting love.<br/>',NULL,231,231);
INSERT INTO stanza VALUES('E48','2','His Father and our Father,<br/>His God and ours Thou art;<br/>And He is Thy Beloved,<br/>The gladness of Thy heart.<br/>We''re His, in joy He brings us<br/>To share His part and place,<br/>To know Thy love and favor,<br/>The shining of Thy face.<br/>',NULL,232,232);
INSERT INTO stanza VALUES('E48','3','Thy love that now enfolds us<br/>Can ne''er wax cold or dim;<br/>In Him that love doth center,<br/>And we are loved in Him.<br/>In Him Thy love and glory<br/>Find their eternal rest;<br/>The many sons-His brethren-<br/>In Him, how near, how blest!<br/>',NULL,233,233);
INSERT INTO stanza VALUES('E49','1','Gracious God, we worship Thee,<br/>Rev''rently we bow the knee;<br/>Jesus Christ, our only plea:<br/>Father, we adore Thee.<br/>',NULL,234,234);
INSERT INTO stanza VALUES('E49','2','Vast Thy love, how deep, how wide,<br/>In the gift of Him who died;<br/>Righteous claims all satisfied:<br/>Father, we adore Thee.<br/>',NULL,235,235);
INSERT INTO stanza VALUES('E49','3','Low we bow before Thy face,<br/>Sons of God, O wondrous place;<br/>Great the riches of Thy grace:<br/>Father, we adore Thee.<br/>',NULL,236,236);
INSERT INTO stanza VALUES('E49','4','By Thy Spirit grant that we<br/>Worshipers in truth may be;<br/>Praise, as incense sweet to Thee:<br/>Father, we adore Thee.<br/>',NULL,237,237);
INSERT INTO stanza VALUES('E49','5','Yet again our song we raise,<br/>Note of deep adoring praise;<br/>Now, and soon through endless days:<br/>Father, we adore Thee.<br/>',NULL,238,238);
INSERT INTO stanza VALUES('E50','1','Father, Thy Son beloved leads our praise<br/>After the banquet feast is had and done;<br/>How dear, how sweet to Thee the praise He leads,<br/>And in His praises joining we are one.<br/>',NULL,239,239);
INSERT INTO stanza VALUES('E50','2','Father, we need no goodness more than Thee,<br/>Nor do we seek a love that''s less than Thine;<br/>How we adore Thee now that here we know<br/>Thy searchless, uncreated life divine.<br/>',NULL,240,240);
INSERT INTO stanza VALUES('E50','3','Father, within Thy love our love to Thee<br/>Grows, far transcending all our earthly ties;<br/>Thine own dear love in power leads our hearts<br/>Where Thine own presence deeply satisfies.<br/>',NULL,241,241);
INSERT INTO stanza VALUES('E50','4','Father, by joining with Thy Son beloved,<br/>We all with gladness praise Thee now again;<br/>Joyfully feasting on Thy holy love,<br/>Tasting, as sons, the sweetness of Thy name.<br/>',NULL,242,242);
INSERT INTO stanza VALUES('E51','1','Our God and Father, we respond to Thee<br/>As sons brought near,<br/>Suited, in love and holy liberty,<br/>To this blest sphere.<br/>O wondrous thought, that many there should be<br/>Like Christ, for Thy delight eternally!<br/>',NULL,243,243);
INSERT INTO stanza VALUES('E51','2','He, Thy delight, in whom we have our part,<br/>Through grace to share<br/>Thy love for Him, the Object of Thy heart<br/>Beyond compare.<br/>His glory in Thy presence now we see,<br/>As with Him there in love''s complacency.<br/>',NULL,244,244);
INSERT INTO stanza VALUES('E51','3','''Tis here He sings-what joy His heart doth find,<br/>Thyself to praise,<br/>While many sons are stirred in heart and mind<br/>One voice to raise<br/>In worship, God and Father, unto Thee,<br/>Supreme, Thou Source in love''s economy!<br/>',NULL,245,245);
INSERT INTO stanza VALUES('E52','1','Father, to Thee a joyful song we raise<br/>With all Thine own;<br/>And in Thy presence sound a note of praise<br/>To Thee alone;<br/>Bro''t nigh, bro''t home to Thee-<br/>O wondrous grace,<br/>That gives us now with Thine own Son our<br/>place<br/>',NULL,246,246);
INSERT INTO stanza VALUES('E52','2','How deep the holy joy that fills that scene,<br/>Where love is known!<br/>Thy love, our God and Father, now is seen,<br/>In Him alone;<br/>As, in the holy calm of Thine own rest,<br/>He leads the praise of those Thy love has<br/>blessed.<br/>',NULL,247,247);
INSERT INTO stanza VALUES('E52','3','He leads the praise! How precious to Thine ear<br/>The song He sings!<br/>How precious, too, to Thee-How near how dear<br/>Are those He brings<br/>To share His place: ''twas thus that Thou didst<br/>plan;<br/>Thou lovedst Him before the world began.<br/>',NULL,248,248);
INSERT INTO stanza VALUES('E53','1','Our God and Father, we respond anew<br/>To love in Christ revealed, and praise Thy Name.<br/>He did Thy will; and for the joy in view,<br/>Endured the cross, despising all the shame.<br/>',NULL,249,249);
INSERT INTO stanza VALUES('E53','2','He, midst His brethren, strikes the note of praise;<br/>We hear His song, our hearts responsive swell;<br/>And on this day when He His voice doth raise,<br/>In spirit we do join and praise Thee well.<br/>',NULL,250,250);
INSERT INTO stanza VALUES('E53','3','Chosen in Him, Thy well-beloved Son,<br/>We have our part in joy before Thy face;<br/>Predestined, ere this world had yet begun,<br/>For that blest world, where all bespeaks Thy grace.<br/>',NULL,251,251);
INSERT INTO stanza VALUES('E53','4','Sons loved and loving, whom Thy Spirit fills,<br/>Our endless portion Christ in us to be;<br/>Each with some trait of Him whose love us thrills,<br/>For Thy delight and joy eternally.<br/>',NULL,252,252);
INSERT INTO stanza VALUES('E54','1','O God and Father, we our praises bring,<br/>For who more worthy of our praise could be<br/>Than Thou, who seekest worshipers who sing<br/>In spirit and in truth adoringly!<br/>',NULL,253,253);
INSERT INTO stanza VALUES('E54','2','All worlds Thou hast created by the Son,<br/>All things are held by His unmeasured power;<br/>Yet we approach Thee in that glorious One:<br/>What cause for worship in this holy hour!<br/>',NULL,254,254);
INSERT INTO stanza VALUES('E54','3','''Tis He who leads us in this blessed sphere,<br/>In the assembly singing praise to Thee; What<br/>joy to Him that we should thus be near<br/>As suited and in perfect liberty!<br/>',NULL,255,255);
INSERT INTO stanza VALUES('E54','4','Here we unite, our song of joy is one!<br/>And Thou, O God, art fully satisfied.<br/>Amidst the praises led by Christ, Thy Son,<br/>Thou hast a dwelling ever to abide.<br/>',NULL,256,256);
INSERT INTO stanza VALUES('E55','1','O God our Father, we would come to Thee<br/>In virtue of our Savior''s precious blood;<br/>All distance gone, our souls by grace set free,<br/>We worship Thee, our Father and our God.<br/>',NULL,257,257);
INSERT INTO stanza VALUES('E55','2','We would, O God, present before Thy face<br/>The fragrant name of Thy beloved Son;<br/>By faith we view Him through Thy boundless grace,<br/>Which, by His dying, He for us has won.<br/>',NULL,258,258);
INSERT INTO stanza VALUES('E55','3','Thy joy in Him who is with Thee we share;<br/>Our hearts delight in Thy delight in Him;<br/>Chiefest of thousands, fairer than the fair;<br/>His glory nought can tarnish, nought can dim.<br/>',NULL,259,259);
INSERT INTO stanza VALUES('E55','4','We bow in worship now before Thy throne,<br/>By faith the Object of Thy love would see;<br/>Who, in the midst, His brethren''s song doth lead.<br/>To Him, our Savior, shall the glory be!<br/>',NULL,260,260);
INSERT INTO stanza VALUES('E56','1','Dear Lord, Thou art the Word of God,<br/>Thou art God''s very Son;<br/>Thou art His holy image true,<br/>And with Him ever one.<br/>',NULL,261,261);
INSERT INTO stanza VALUES('E56','2','Thou art Thyself the very God,<br/>Thou dost embody Him;<br/>In Thee is manifested God,<br/>And we see God therein.<br/>',NULL,262,262);
INSERT INTO stanza VALUES('E56','3','Effulgence of God''s glory, Thou,<br/>By Thee God shines on us;<br/>Expression of His substance, Thou,<br/>In Thee He''s real to us.<br/>',NULL,263,263);
INSERT INTO stanza VALUES('E56','4','In Thee God is the life to us,<br/>In Thee He is the light;<br/>In Thee His nature we partake<br/>And with Him we unite.<br/>',NULL,264,264);
INSERT INTO stanza VALUES('E56','5','In Thee the grace of God subsists,<br/>God we enjoy in Thee;<br/>His truth in Thee is also found,<br/>His full reality.<br/>',NULL,265,265);
INSERT INTO stanza VALUES('E56','6','In Thee God''s fulness we receive,<br/>Which fills from grace to grace;<br/>In Thee with God we''re mingled here,<br/>Till one in every phase.<br/>',NULL,266,266);
INSERT INTO stanza VALUES('E56','7','O Lord our God, we worship Thee,<br/>In Thee we have our all;<br/>Thyself we treasure in our heart,<br/>Thy Name we love to call.<br/>',NULL,267,267);
INSERT INTO stanza VALUES('E57','1','The image of the Father God,<br/>Lord, we behold in Thee;<br/>The fulness of the Godhead true<br/>In Thee dwells bodily.<br/>',NULL,268,268);
INSERT INTO stanza VALUES('E57','2','Lord, Thou art God''s eternal Word<br/>With life divine in Thee;<br/>In Thee His grace we all receive<br/>With His reality.<br/>',NULL,269,269);
INSERT INTO stanza VALUES('E57','3','Effulgence of God''s glory true,<br/>The Son of God art Thou;<br/>The very substance of Himself<br/>In Thee we all avow.<br/>',NULL,270,270);
INSERT INTO stanza VALUES('E57','4','Embodiment of God Thou art,<br/>And with Him ever one;<br/>In Thee is God expressed to us<br/>Beyond comparison.<br/>',NULL,271,271);
INSERT INTO stanza VALUES('E57','5','God we enjoy in Thee, dear Lord,<br/>As life and everything;<br/>To Thee and God our heartfelt thanks<br/>And praise we''ll ever bring.<br/>',NULL,272,272);
INSERT INTO stanza VALUES('E58','1','Thou art the living Word, O Lord,<br/>Which ever was with God;<br/>His glory Thou hast fully shown<br/>When Thou on earth hast trod.<br/>',NULL,273,273);
INSERT INTO stanza VALUES('E58','chorus','We praise Thee, O Thou living Word,<br/>For God in Thee we see;<br/>His glory and His character<br/>Are all revealed by Thee.<br/>',NULL,274,274);
INSERT INTO stanza VALUES('E58','2','The heavens do God''s glory speak,<br/>Creation vast doth show<br/>The things of God, His character<br/>And pow''r for man to know.<br/>',NULL,275,275);
INSERT INTO stanza VALUES('E58','3','The Word of God-how rich, profound,<br/>His testimony shown;<br/>Within the Word Thou art declared,<br/>That God should be made known.<br/>',NULL,276,276);
INSERT INTO stanza VALUES('E58','4','Thou, living Word, didst flesh become,<br/>With man on earth hast, trod;<br/>And all Thy words and conduct here<br/>Expression gave to God.<br/>',NULL,277,277);
INSERT INTO stanza VALUES('E58','5','O living Word, Thou art the life,<br/>Thou art the living light;<br/>As life Thou dost illuminate<br/>The Father to our sight.<br/>',NULL,278,278);
INSERT INTO stanza VALUES('E58','6','God''s judgment Thou wilt yet perform,<br/>His righteousness make known;<br/>This also doth expression give<br/>That God be fully shown.<br/>',NULL,279,279);
INSERT INTO stanza VALUES('E58','7','God''s full expression, Lord, Thou art,<br/>Himself Thou hast revealed;<br/>Declaring all He is to man,<br/>No more is God concealed.<br/>',NULL,280,280);
INSERT INTO stanza VALUES('E59','1','Thou art the everlasting Word,<br/>The Father''s only Son,<br/>God manifestly seen and heard,<br/>And heav''n''s beloved One:<br/>Divine, O Son of God, art Thou,<br/>In Thee God''s fulness find we now.<br/>',NULL,281,281);
INSERT INTO stanza VALUES('E59','2','In Thee most perfectly expressed<br/>The Father''s glories shine;<br/>Of the full Deity possessed,<br/>Eternally divine:<br/>Divine, O Son of God, art Thou,<br/>In Thee God''s fulness find we now.<br/>',NULL,282,282);
INSERT INTO stanza VALUES('E59','3','True image of the Infinite,<br/>Whose essence is concealed;<br/>Brightness of uncreated light;<br/>The heart of God revealed:<br/>Divine, O Son of God, art Thou,<br/>In Thee God''s fulness find we now.<br/>',NULL,283,283);
INSERT INTO stanza VALUES('E59','4','But the, high mysteries of T''ny Name<br/>An angel''s grasp transcend;<br/>The Father only, glorious claim!<br/>The Son can comprehend:<br/>Divine, O Son of God, art Thou,<br/>In Thee God''s fulness find we now.<br/>',NULL,284,284);
INSERT INTO stanza VALUES('E59','5','Throughout the universe of bliss,<br/>The center, Thou, and sun;<br/>Th'' eternal theme of praise is this,<br/>To heav''n''s beloved One:<br/>Divine, O Son of God, art Thou,<br/>In Thee God''s fulness find we now.<br/>',NULL,285,285);
INSERT INTO stanza VALUES('E60','1','Of the Father''s love begotten,<br/>Ere the worlds began to be,<br/>He is Alpha and Omega,<br/>He the source, the ending He,<br/>Of the things that are and have been,<br/>And that future years shall see,<br/>Evermore and evermore.<br/>',NULL,286,286);
INSERT INTO stanza VALUES('E60','2','This is He whom they in old time<br/>Chanted of with one accord,<br/>Whom the voices of the prophets<br/>Promised in their faithful word;<br/>Now He shines, the long-expected;<br/>Let creation praise its Lord,<br/>Evermore and evermore.<br/>',NULL,287,287);
INSERT INTO stanza VALUES('E60','3','O ye heights of hea''n, adore Him;<br/>Angel hosts, His praises sing;<br/>All dominions, bow before Him,<br/>And extol our Lord and King.<br/>Let no tongue on earth be silent,<br/>Every voice in concert ring,<br/>Evermore and evermore.<br/>',NULL,288,288);
INSERT INTO stanza VALUES('E60','4','Christ, to Thee, with God the Father,<br/>And, with Holy Ghost, to Thee,<br/>Hymn and chant and high thanksgiving,<br/>And unwearied praises be;<br/>Honor, glory, and dominion,<br/>And eternal victory,<br/>Evermore and evermore.<br/>',NULL,289,289);
INSERT INTO stanza VALUES('E61','1','O Lord, Thou art the Son of man,<br/>Our human nature Thou didst take;<br/>Begotten of a virgin true,<br/>Of flesh and blood Thou didst partake.<br/>',NULL,290,290);
INSERT INTO stanza VALUES('E61','2','In bondman''s form, with lowliness,<br/>Thou walkedst on this earth of woe;<br/>The human living Thou didst have<br/>And all its suff''rings undergo.<br/>',NULL,291,291);
INSERT INTO stanza VALUES('E61','3','Born in a manger as a babe,<br/>Thou wast a child among the poor;<br/>Thou as a carpenter didst work,<br/>And e''en an outlaw''s death endure.<br/>',NULL,292,292);
INSERT INTO stanza VALUES('E61','4','Then Thou wast raised up from the dead, Still<br/>with the human nature true;<br/>And as a man in form divine,<br/>Thou didst ascend to heaven too.<br/>',NULL,293,293);
INSERT INTO stanza VALUES('E61','5','Now over all, and on the throne,<br/>Thou, still a man, art glorified;<br/>A man with God in light divine<br/>With whom our God is satisfied.<br/>',NULL,294,294);
INSERT INTO stanza VALUES('E61','6','In glory Thou wilt come again,<br/>Still as a man appearing then;<br/>As King of kings, with pow''r divine,<br/>With human nature seen by men.<br/>',NULL,295,295);
INSERT INTO stanza VALUES('E61','7','Thou, as the center of all things,<br/>In the new heav''n and earth shalt be,<br/>Forever as the One divine,<br/>Existing in humanity.<br/>',NULL,296,296);
INSERT INTO stanza VALUES('E62','1','Dear Lord Jesus, we adore Thee,<br/>"Seed of woman" Thou became;<br/>Of the virgin wast begotten,<br/>Called e''en with a human name.<br/>Taking thus the human nature,<br/>Thou as man the serpent trod;<br/>By the Cross his head Thou bruised<br/>And fulfilled the plan of God.<br/>',NULL,297,297);
INSERT INTO stanza VALUES('E62','chorus','Lord, we see Thy glory,<br/>Shown in human beauty,<br/>Full of splendor, manifested In humanity.<br/>',NULL,298,298);
INSERT INTO stanza VALUES('E62','2','As a man, by incarnation,<br/>Flesh and blood didst Thou partake<br/>To destroy the devil, Satan,<br/>In our stead and for our sake.<br/>With the name of Jesus given<br/>And Emmanuel called too,<br/>Thou becam''st our precious Savior,<br/>Bringing us salvation true.<br/>',NULL,299,299);
INSERT INTO stanza VALUES('E62','3','Thou, "Last Adam" wast entitled,<br/>And wast called the "second man",<br/>Head of all the new creation,<br/>Better than the first man.<br/>On this earth in life and conduct<br/>Thou indeed wast Son of man;<br/>Now in heaven with this nature<br/>Thou dost still appear as man.<br/>',NULL,300,300);
INSERT INTO stanza VALUES('E62','4','In the time which God appointed<br/>Thou wilt come, dear Lord, again,<br/>With the glory of the Father,<br/>Still appearing as a man.<br/>Even on the throne of judgment<br/>Son of man Thou still wilt be;<br/>And with this, our human nature,<br/>Thou forevermore wilt be.<br/>',NULL,301,301);
INSERT INTO stanza VALUES('E63','1','Praise to the Holiest in the height,<br/>And in the depth be praise:<br/>In all His words most wonderful;<br/>Most sure in all His ways.<br/>',NULL,302,302);
INSERT INTO stanza VALUES('E63','2','O loving wisdom of our God,<br/>When all was sin and shame,<br/>He, the last Adam, to the fight<br/>And to the rescue came.<br/>',NULL,303,303);
INSERT INTO stanza VALUES('E63','3','O wisest love! That flesh and blood<br/>Which did in Adam fail,<br/>Should strive afresh against the foe,<br/>Should strive and should prevail.<br/>',NULL,304,304);
INSERT INTO stanza VALUES('E63','4','And that a higher gift than grace<br/>Should flesh and blood refine,<br/>God''s presence, and His very self<br/>And essence all-divine.<br/>',NULL,305,305);
INSERT INTO stanza VALUES('E63','5','O generous love! That He, who smote<br/>In man for man the foe,<br/>The double agony in man<br/>For man should undergo.<br/>',NULL,306,306);
INSERT INTO stanza VALUES('E63','6','And in the garden secretly,<br/>And on the cross on high,<br/>Should teach His brethren, and inspire<br/>To suffer and to die.<br/>',NULL,307,307);
INSERT INTO stanza VALUES('E63','7','Praise to the Holiest in the height,<br/>And in the depth be praise:<br/>In all His words most wonderful;<br/>Most sure in all His ways.<br/>',NULL,308,308);
INSERT INTO stanza VALUES('E64','1','O soul-inspiring story-<br/>God''s majesty and grace<br/>In lustrous strokes of glory<br/>Deep-carved in Jesus'' face!<br/>Hearts rapt in contemplation<br/>Of Godhead''s Image bright,<br/>Break forth in adoration,<br/>In wonder and delight!<br/>',NULL,309,309);
INSERT INTO stanza VALUES('E64','2','There Manhood, all perfection,<br/>And Godhead-fulness shine;<br/>God''s love and Man''s affection,<br/>The human, the divine;<br/>A life, a death, transcendent,<br/>Revealing God as love:<br/>Here, lowly Man, dependent-<br/>God over all, above!<br/>',NULL,310,310);
INSERT INTO stanza VALUES('E64','3','Unsullied blaze of glory!<br/>O ever-radiant Face!<br/>Thy rich, unfathomed story<br/>Transfigures us in grace!<br/>Made like Thee, soon, completely,<br/>With love-lit eyes we''ll scan<br/>God''s face unveiled so sweetly<br/>In Thine, Thou Son of man!<br/>',NULL,311,311);
INSERT INTO stanza VALUES('E65','1','Jesus! That name we love,<br/>Jesus, our Lord!<br/>Jesus, all names above,<br/>Jesus, the Lord!<br/>Thou, Lord, our all must be;<br/>Nothing that''s good have we,<br/>Nothing apart from Thee,<br/>Jesus, our Lord!<br/>',NULL,312,312);
INSERT INTO stanza VALUES('E65','2','As Son of Man it was,<br/>Jesus, the Lord!<br/>Thou gav''st Thy life for us,<br/>Jesus, our Lord!<br/>Great was indeed Thy love,<br/>All other loves above,<br/>Love Thou didst dearly prove,<br/>Jesus, our Lord!<br/>',NULL,313,313);
INSERT INTO stanza VALUES('E65','3','Righteous alone in Thee,<br/>Jesus, the Lord!<br/>Thou wilt a refuge be,<br/>Jesus, our Lord!<br/>Whom, then, have we to fear,<br/>What trouble, grief, or care,<br/>Since Thou art ever near,<br/>Jesus, our Lord!<br/>',NULL,314,314);
INSERT INTO stanza VALUES('E65','4','Soon Thou wilt come again,<br/>Jesus, the Lord!<br/>We shall be happy then,<br/>Jesus, our Lord!<br/>When Thine own face we see,<br/>Then shall we like Thee be,<br/>Then evermore with Thee,<br/>Jesus, our Lord!<br/>',NULL,315,315);
INSERT INTO stanza VALUES('E66','1','How sweet the Name of Jesus sounds<br/>In a believer''s ear!<br/>It soothes his sorrow, heals his wounds,<br/>And drives away his fear.<br/>',NULL,316,316);
INSERT INTO stanza VALUES('E66','2','It makes the wounded spirit whole,<br/>And calms the troubled breast;<br/>''Tis manna to the hungry soul,<br/>And to the weary rest.<br/>',NULL,317,317);
INSERT INTO stanza VALUES('E66','3','Dear Name! The Rock on which we build;<br/>Our shield and hiding-place;<br/>Our never-failing treasury, filled<br/>With boundless stores of grace.<br/>',NULL,318,318);
INSERT INTO stanza VALUES('E66','4','Jesus, our Savior, Shepherd, Friend,<br/>Our Prophet, Priest, and King;<br/>Our Lord, our Life, our Way, our End,<br/>Accept the praise we bring.<br/>',NULL,319,319);
INSERT INTO stanza VALUES('E66','5','Weak is the effort of our heart,<br/>And cold our warmest thought;<br/>But when we see Thee as Thou art,<br/>We''ll praise Thee as we ought.<br/>',NULL,320,320);
INSERT INTO stanza VALUES('E66','6','Till then we would Thy love proclaim<br/>With every fleeting breath;<br/>And triumph in that blessed Name<br/>Which quells the pow''r of death.<br/>',NULL,321,321);
INSERT INTO stanza VALUES('E66','end-note','(Repeat the last two lines of each stanza)<br/>',NULL,322,322);
INSERT INTO stanza VALUES('E67','1','The name of Jesus is so sweet,<br/>I love its music to repeat;<br/>It makes my joys full and complete,<br/>The precious name of Jesus.<br/>',NULL,323,323);
INSERT INTO stanza VALUES('E67','chorus','Jesus! Oh, how sweet the name,<br/>Jesus! Every day the same;<br/>Jesus! Let all saints proclaim<br/>Its worthy praise forever.<br/>',NULL,324,324);
INSERT INTO stanza VALUES('E67','2','I love the name of Him whose heart<br/>Knows all my griefs and bears a part;<br/>Who bids all anxious fears depart,<br/>I love the name of Jesus.<br/>',NULL,325,325);
INSERT INTO stanza VALUES('E67','3','That name I fondly love to hear,<br/>It never fails my heart to cheer,<br/>Its music dries the falling tear;<br/>Exalt the name of Jesus.<br/>',NULL,326,326);
INSERT INTO stanza VALUES('E67','4','No word of man can ever tell<br/>How sweet the name I love so well,<br/>Oh, let its praises ever swell,<br/>Oh, praise the name of Jesus.<br/>',NULL,327,327);
INSERT INTO stanza VALUES('E68','1','Lord, Thy Name is called Jesus,<br/>Wonderful is this dear Name;<br/>Thou wast brought forth of the virgin,<br/>And the Son of man became.<br/>Thou art our Jehovah-Savior,<br/>Saving us from all our sins;<br/>When as Savior we receive Thee,<br/>Life divine in us begins.<br/>',NULL,328,328);
INSERT INTO stanza VALUES('E68','2','Thou as "Christ" art also titled,<br/>Title of Thy ministry;<br/>Thou art truly God''s anointed,<br/>Even from eternity.<br/>Thou, O Lord, art God''s Messiah;<br/>God appointed Thee in love,<br/>That Thou might fulfill His purpose<br/>And to all His glory prove.<br/>',NULL,329,329);
INSERT INTO stanza VALUES('E68','3','Thou art also, called "Emmanuel";<br/>"God with us" Thou cam''st to be;<br/>God in grace is wholly mingled<br/>With our own humanity.<br/>God in flesh is manifested,<br/>Full of grace and truth therein;<br/>We have seen in Thee God''s glory,<br/>And in faith partake of Him.<br/>',NULL,330,330);
INSERT INTO stanza VALUES('E68','4','How we treasure all Thy names, Lord,<br/>How much they to us unfold;<br/>All their worth and all their sweetness<br/>We in love will ever hold.<br/>Precious Savior, we adore Thee,<br/>Worship unto Thee we bring;<br/>Our Emmanuel we exalt Thee,<br/>And Thy praise will ever sing.<br/>',NULL,331,331);
INSERT INTO stanza VALUES('E69','1','Thy name we love, Lord Jesus,<br/>And lowly bow before Thee;<br/>And while we live, to Thee we give<br/>All blessing, worship, glory.<br/>We sing aloud Thy praises,<br/>Our hearts and voices blending,<br/>''Tis Thou alone we worthy own,<br/>Thy beauty''s all-transcending.<br/>',NULL,332,332);
INSERT INTO stanza VALUES('E69','2','Thy name we love, Lord Jesus;<br/>It tells God''s love unbounded<br/>To ruined man, ere time began,<br/>Or heav''n and earth were founded:<br/>Thine is a love eternal,<br/>That found in us its pleasure,<br/>That brought Thee low to bear our woe<br/>And make us Thine own treasure.<br/>',NULL,333,333);
INSERT INTO stanza VALUES('E69','3','Thy name we love, Lord Jesus;<br/>It tells Thy birth so lowly,<br/>Thy patience, grace, and gentleness,<br/>Thy lonely path, so holy;<br/>Thou wast the "Man of Sorrows";<br/>Our grief, too, Thou didst bear it;<br/>Our bitter cup Thou drankest up;<br/>The thorny crown, didst wear it.<br/>',NULL,334,334);
INSERT INTO stanza VALUES('E69','4','Thy name we love, Lord Jesus;<br/>God''s Lamb-Thou wast ordained,<br/>To bear our sins (Thyself all clean)<br/>And hast our guilt sustained.<br/>We see Thee crowned in glory,<br/>Above the heavens now seated,<br/>The vict''ry won, Thy work well done,<br/>Our righteousness completed.<br/>',NULL,335,335);
INSERT INTO stanza VALUES('E70','1','There is a name I love to hear,<br/>I love to sing its worth;<br/>It sounds like music in mine ear,<br/>The sweetest name on earth.<br/>',NULL,336,336);
INSERT INTO stanza VALUES('E70','chorus','Oh, how I love Jesus,<br/>Oh, how I love Jesus,<br/>Oh, how I love Jesus,<br/>Because He first loved me!<br/>',NULL,337,337);
INSERT INTO stanza VALUES('E70','2','It tells me of a Savior''s love,<br/>Who died to set me free;<br/>It tells me of His precious blood,<br/>The sinner''s perfect plea.<br/>',NULL,338,338);
INSERT INTO stanza VALUES('E70','3','It tells me what my Father hath,<br/>In store for every day,<br/>And though I tread a darksome path,<br/>Yields sunshine all the way.<br/>',NULL,339,339);
INSERT INTO stanza VALUES('E70','4','It tells of One whose loving heart<br/>Can feel my deepest woe,<br/>Who in each sorrow bears a part<br/>That none can bear below.<br/>',NULL,340,340);
INSERT INTO stanza VALUES('E71','1','Jesus! How much Thy name unfolds<br/>To every opened ear;<br/>The pardoned sinner''s mem''ry holds<br/>None other half so dear.<br/>',NULL,341,341);
INSERT INTO stanza VALUES('E71','2','Thy name encircles every grace<br/>That God as man could show;<br/>There only could He fully trace<br/>A life divine below.<br/>',NULL,342,342);
INSERT INTO stanza VALUES('E71','3','Jesus-it speaks a life of love,<br/>Of sorrows meekly borne;<br/>It tells of sympathy above.<br/>Whatever makes us mourn.<br/>',NULL,343,343);
INSERT INTO stanza VALUES('E71','4','Jesus, the One who knew no sin,<br/>Made sin to make us just;<br/>Thou gav''st Thyself our love to win,<br/>Our full confiding trust.<br/>',NULL,344,344);
INSERT INTO stanza VALUES('E71','5','The mention of Thy name shall bow<br/>Our hearts to worship Thee;<br/>The chiefest of ten thousand Thou,<br/>Whose love has set us free.<br/>',NULL,345,345);
INSERT INTO stanza VALUES('E72','1','Jesus, the name high over all,<br/>In hell, or earth, or sky:<br/>Angels and men before it fall,<br/>And devils fear and fly.<br/>',NULL,346,346);
INSERT INTO stanza VALUES('E72','2','Jesus, the name to sinners dear,<br/>The name to sinners giv''n;<br/>It scatters all their guilty fear,<br/>It brings them peace of heav''n.<br/>',NULL,347,347);
INSERT INTO stanza VALUES('E72','3','Jesus the prisoner''s fetters breaks,<br/>And bruises Satan''s head;<br/>Pow''r into strengthless souls He speaks,<br/>And life into the dead.<br/>',NULL,348,348);
INSERT INTO stanza VALUES('E72','4','Oh, that the world might taste and see,<br/>The riches of His grace!<br/>The arms of love that compass me,<br/>Would all mankind embrace.<br/>',NULL,349,349);
INSERT INTO stanza VALUES('E72','5','Him as my righteousness I show,<br/>His saving truth proclaim:<br/>''Tis all my business here below,<br/>To cry, Behold the Lamb!<br/>',NULL,350,350);
INSERT INTO stanza VALUES('E72','6','Happy, if with my latest breath<br/>I may but gasp His name:<br/>Preach Him to all, and cry in death,<br/>"Behold, behold the Lamb!"<br/>',NULL,351,351);
INSERT INTO stanza VALUES('E73','1','Glorious, mighty Name of Jesus,<br/>Into Thy dear Name I flee;<br/>"Set aloft," I praise and worship,<br/>For Thy Name is victory!<br/>',NULL,352,352);
INSERT INTO stanza VALUES('E73','2','Blessed Jesus! Mighty Savior!<br/>In Thy Name is all I need;<br/>Just to breathe the Name of Jesus,<br/>Is to drink of Life indeed.<br/>',NULL,353,353);
INSERT INTO stanza VALUES('E73','3','Glorious, mighty Name of Jesus,<br/>Heav''n and earth its pow''r proclaim;<br/>But forgiven sinners only,<br/>Know the balm of Jesus'' Name.<br/>',NULL,354,354);
INSERT INTO stanza VALUES('E73','4','Jesus! Jesus! Name most precious,<br/>Balm in pain or mighty sword;<br/>In Thy Name, we live and conquer,<br/>Blessed, glorious, coming Lord.<br/>',NULL,355,355);
INSERT INTO stanza VALUES('E74','1','There is a name to Jesus given,<br/>His matchless love its accents tell;<br/>For it declares: He is my Brother,<br/>And this His name-Emmanuel!<br/>The Lord, by angels worshiped yonder,<br/>Has stooped to earth with men to dwell,<br/>Incarnate God, and man forever-<br/>Our own beloved Emmanuel.<br/>',NULL,356,356);
INSERT INTO stanza VALUES('E74','2','There is a name that''s still more precious,<br/>That stirs our hearts with fondest love:<br/>It is the charming name of Jesus,<br/>The name all other names above.<br/>It tells me that He is my Savior<br/>From sin and sickness and the grave.<br/>I love the precious name of Jesus,<br/>For I am one He came to save!<br/>',NULL,357,357);
INSERT INTO stanza VALUES('E74','3','Though dear to us the name of Jesus,<br/>The name of Christ is higher still!<br/>It tells of Him who dwells within us,<br/>Our old heart to renew and fill.<br/>It tells me of the Spirit''s fullness,<br/>It brings the pow''r of Pentecost.<br/>O blessed Christ, anoint me also,<br/>And fill me with the Holy Ghost!<br/>',NULL,358,358);
INSERT INTO stanza VALUES('E75','1','Jesus, Name of matchless splendor!<br/>Name all other names above!<br/>Glorious Son of God incarnate,<br/>King of kings, and Lord of love!<br/>',NULL,359,359);
INSERT INTO stanza VALUES('E75','2','Name that to our hearts is nearest,<br/>Here the stricken soul doth hide;<br/>Name that to our hearts is dearest,<br/>As in Jesus we confide.<br/>',NULL,360,360);
INSERT INTO stanza VALUES('E75','3','"Call Him Jesus!" He shall save us<br/>From the tyranny of sin;<br/>From its condemnation save us,<br/>From iniquity within.<br/>',NULL,361,361);
INSERT INTO stanza VALUES('E75','4','Thanks we give, and adoration,<br/>Every day and every hour,<br/>For an uttermost salvation,<br/>Freedom from sin''s guilt and power.<br/>',NULL,362,362);
INSERT INTO stanza VALUES('E75','5','Jesus! Sweetest note of any<br/>In the lowly pilgrim''s song;<br/>Jesus! The triumphant music<br/>Of the bright angelic throng.<br/>',NULL,363,363);
INSERT INTO stanza VALUES('E75','6','Earth to Him her face upraises,<br/>Knows Him as the great I AM!<br/>Heaven resounds with Jesus'' praises,<br/>Glory to the bleeding Lamb!<br/>',NULL,364,364);
INSERT INTO stanza VALUES('E76','1','In the Name of Jesus<br/>Every knee shall bow,<br/>Every tongue confess Him<br/>King of glory now;<br/>''Tis the Father''s pleasure<br/>We should call Him Lord,<br/>Who from the beginning<br/>Was the Mighty Word.<br/>',NULL,365,365);
INSERT INTO stanza VALUES('E76','2','At His voice creation<br/>Sprang at once to sight:<br/>All the angel faces,<br/>All the hosts of light,<br/>Thrones and dominations,<br/>Stars upon their way,<br/>All the heav''nly orders,<br/>In their great array.<br/>',NULL,366,366);
INSERT INTO stanza VALUES('E76','3','Humbled for a season,<br/>To receive a Name<br/>From the lips of sinners<br/>Unto whom He came,<br/>Faithfully He bore it<br/>Spotless to the last,<br/>Brought it back victorious,<br/>When from death He passed;<br/>',NULL,367,367);
INSERT INTO stanza VALUES('E76','4','Bore it up triumphant,<br/>With its human light,<br/>Through all ranks of creatures,<br/>To the central height;<br/>To the throne of Godhead,<br/>To the Father''s breast,<br/>Filled it with the glory<br/>Of that perfect rest.<br/>',NULL,368,368);
INSERT INTO stanza VALUES('E76','5','Name Him, brothers, name Him,<br/>With love strong as death,<br/>But with awe and wonder,<br/>And with bated breath;<br/>He is God the Savior,<br/>He is Christ the Lord,<br/>Ever to be worshiped,<br/>Trusted, and adored.<br/>',NULL,369,369);
INSERT INTO stanza VALUES('E76','6','In your hearts enthrone Him;<br/>There let Him subdue<br/>All that is not holy,<br/>All that is not true;<br/>Crown Him as your Captain<br/>In temptation''s hour;<br/>Let His will enfold you<br/>In its light and power.<br/>',NULL,370,370);
INSERT INTO stanza VALUES('E76','7','Brothers, this Lord Jesus<br/>Shall return again,<br/>With His Father''s glory,<br/>With His angel train;<br/>For all wreaths of empire<br/>Meet upon His brow,<br/>And our hearts confess Him<br/>King of glory now.<br/>',NULL,371,371);
INSERT INTO stanza VALUES('E77','1','Lift that Name high! That glorious Name,<br/>Let heav''n and earth its pow''r proclaim;<br/>Our mighty, conqu''ring, coming King,<br/>Earth yet shall with His praises ring.<br/>',NULL,372,372);
INSERT INTO stanza VALUES('E77','2','Lift that Name high! To that high tower<br/>We flee in every trial hour,<br/>Safe, sheltered, satisfied and free,<br/>For Jesus'' Name is victory.<br/>',NULL,373,373);
INSERT INTO stanza VALUES('E77','3','Lift that Name high! Until one day<br/>His mighty Name the earth shall sway,<br/>And sin and death, distress and pain<br/>Shall be no more, for Christ shall reign.<br/>',NULL,374,374);
INSERT INTO stanza VALUES('E77','4','Lift that Name high! Jesus shall reign,<br/>And kings shall follow in His train;<br/>Lift that Name high, all names above,<br/>The Name of Him we own and love.<br/>',NULL,375,375);
INSERT INTO stanza VALUES('E77','5','Lift that Name high! For every knee<br/>Shall bow to Him; Jesus shall see<br/>Fruit of His Cross, when earth shall bring<br/>Her tribute to her Lord and King.<br/>',NULL,376,376);
INSERT INTO stanza VALUES('E78','1','Gracious Lord, Thy name "I AM" is,<br/>Precious name, how rich and full ''tis,<br/>All-inclusive, faithful too ''tis-<br/>All, we need, Thou art!<br/>',NULL,377,377);
INSERT INTO stanza VALUES('E78','2','Thou the Son, the Father in Thee,<br/>As the Spirit now indwell me,<br/>That the riches of Thyself we<br/>May experience.<br/>',NULL,378,378);
INSERT INTO stanza VALUES('E78','3','Thou the Temple for God''s dwelling,<br/>Thou the Father''s life e''er telling;<br/>We in Thee with joy excelling<br/>Face to face see Him.<br/>',NULL,379,379);
INSERT INTO stanza VALUES('E78','4','Thou the Lamb and Thou the Bridegroom,<br/>For the bride Thou sufferedst sin''s doom,<br/>Wounded, crucified in our room;<br/>Thus we find our rest.<br/>',NULL,380,380);
INSERT INTO stanza VALUES('E78','5','Thou art wisdom and the way, Lord,<br/>Thou our lives dost plan each day, Lord,<br/>Grace to us Thou dost convey, Lord,<br/>In Thy path to walk.<br/>',NULL,381,381);
INSERT INTO stanza VALUES('E78','6','Pure and holy, righteous Thou art,<br/>One with God, well-pleasing His heart,<br/>Thou within to us dost impart<br/>Harmony with God.<br/>',NULL,382,382);
INSERT INTO stanza VALUES('E78','7','Thou art life and Thou art light, Lord,<br/>Death hast swallowed, banished night, Lord,<br/>Thou hast quickened, given sight, Lord;<br/>We are now set free.<br/>',NULL,383,383);
INSERT INTO stanza VALUES('E78','8','Thou art resurrection power,<br/>Thou the conqu''ror in hell''s hour;<br/>Thou dost us with might empower<br/>Over all to reign.<br/>',NULL,384,384);
INSERT INTO stanza VALUES('E78','9','Living water, food supply, Lord,<br/>Thou Thyself art, and didst die, Lord,<br/>All our want to satisfy, Lord;<br/>Now we feast on Thee.<br/>',NULL,385,385);
INSERT INTO stanza VALUES('E78','10','Thou the Shepherd and Physician,<br/>Thou hast healed our sick condition;<br/>Comfort, guide, protect-Thy mission;<br/>Thou dost care for us.<br/>',NULL,386,386);
INSERT INTO stanza VALUES('E78','11','Priest and King Thou art fore''er, Lord;<br/>Into God we''re brought, and there, Lord,<br/>Thine authority we share, Lord;<br/>What an honored place!<br/>',NULL,387,387);
INSERT INTO stanza VALUES('E78','12','Thou our Hope and our Redemption,<br/>Thou wilt change our old creation,<br/>Make of Thee a duplication,<br/>Thus Thyself express.<br/>',NULL,388,388);
INSERT INTO stanza VALUES('E78','13','Thou our Joy, our Peace, our Glory;<br/>Truth, and Grace, the Rock, the Life-tree,<br/>Building, Mountain, Sun, and Shield-we<br/>Ne''er can tell it all.<br/>',NULL,389,389);
INSERT INTO stanza VALUES('E78','14','What Thou art-eternal, boundless,<br/>Full and perfect, rich, exhaustless-<br/>Meets our need to utter fullness<br/>And from us o''erflows.<br/>',NULL,390,390);
INSERT INTO stanza VALUES('E79','1','All praise to Him who reigns on high,<br/>In majesty supreme,<br/>Who gave His life for man to die, That He<br/>might man redeem.<br/>',NULL,391,391);
INSERT INTO stanza VALUES('E79','chorus','Blessed be the name,<br/>Blessed be the name,<br/>Blessed be the name of the Lord.<br/>Blessed be the name,<br/>Blessed be the name,<br/>Blessed be the name of the Lord.<br/>',NULL,392,392);
INSERT INTO stanza VALUES('E79','2','His name above all names shall stand,<br/>Exalted more and more,<br/>At God the Father''s own right hand,<br/>Where angel hosts adore.<br/>',NULL,393,393);
INSERT INTO stanza VALUES('E79','3','Redeemer, Savior, Friend of man<br/>Once ruined by the fall,<br/>Thou hast devised salvation''s plan,<br/>For Thou hast died for all.<br/>',NULL,394,394);
INSERT INTO stanza VALUES('E79','4','His name shall be the Counselor,<br/>The mighty Prince of Peace,<br/>Of all earth''s kingdoms, Conqueror,<br/>Whose reign shall never cease.<br/>',NULL,395,395);
INSERT INTO stanza VALUES('E80','1','Join all the glorious names<br/>Of wisdom, love, and pow''r,<br/>That mortals ever knew,<br/>That angels ever bore;<br/>All are too mean to speak His worth,<br/>Too mean to set my Savior forth.<br/>',NULL,396,396);
INSERT INTO stanza VALUES('E80','2','Great Prophet of my God,<br/>My tongue would bless Thy name;<br/>By Thee the joyful news<br/>Of our salvation came;<br/>The joyful news of sins forgiv''n,<br/>Of death annulled, and Thy life giv''n.<br/>',NULL,397,397);
INSERT INTO stanza VALUES('E80','3','Jesus, my great High Priest,<br/>Offered His blood, and died;<br/>My guilty conscience seeks<br/>No sacrifice beside:<br/>His pow''rful blood did me redeem,<br/>''Tis worthy of my heart''s esteem.<br/>',NULL,398,398);
INSERT INTO stanza VALUES('E80','4','I love my Shepherd''s voice:<br/>His watchful eye shall keep<br/>My wand''ring soul among<br/>The thousands of His sheep:<br/>He feeds His flock, He calls their names,<br/>His bosom bears the tender lambs.<br/>',NULL,399,399);
INSERT INTO stanza VALUES('E80','5','My Savior and my Lord,<br/>My Conqu''ror and my King,<br/>Thy scepter and Thy sword,<br/>Thy reigning grace I sing:<br/>Thine is the pow''r; behold I sit<br/>In willing bonds beneath Thy feet.<br/>',NULL,400,400);
INSERT INTO stanza VALUES('E81','1','O Lord, Thy being is of old,<br/>Before th'' eternal past began!<br/>For Thou th'' eternal Father art,<br/>The uncreated, great I AM!<br/>',NULL,401,401);
INSERT INTO stanza VALUES('E81','2','Although a man with men become,<br/>Yet Thou with God eternal art!<br/>The same completeness Thou dost share,<br/>And infinite as God Thou art!<br/>',NULL,402,402);
INSERT INTO stanza VALUES('E81','3','Thine origin, the same as God,<br/>Before creation was decreed!<br/>Before the foremost, Thou art first,<br/>None other doth Thyself precede!<br/>',NULL,403,403);
INSERT INTO stanza VALUES('E81','4','Thou never changest thru all time,<br/>Thy years are to eternity!<br/>None is as lasting as Thyself,<br/>Nor is there any after Thee!<br/>',NULL,404,404);
INSERT INTO stanza VALUES('E81','5','Just as the Father, diff''ring not,<br/>The same perfection Thou too hast!<br/>Thou art the Alpha and the First,<br/>Thou art Omega and the Last!<br/>',NULL,405,405);
INSERT INTO stanza VALUES('E81','6','We praise Thee for Thine endless years,<br/>Extol Thee for Thy perfectness!<br/>Admiring all Thy fulness vast,<br/>We marvel at Thy boundlessness<br/>',NULL,406,406);
INSERT INTO stanza VALUES('E82','1','Down from His glory,<br/>Ever living story,<br/>My God and Savior came,<br/>And Jesus was His name.<br/>Born in a manger,<br/>To His own a stranger,<br/>A Man of sorrows, tears and agony.<br/>',NULL,407,407);
INSERT INTO stanza VALUES('E82','chorus','O how I love Him! How I adore Him!<br/>My breath, my sunshine, my all in all!<br/>The great Creator became my Savior,<br/>And all God''s fulness dwelleth in Him.<br/>',NULL,408,408);
INSERT INTO stanza VALUES('E82','2','What condescension,<br/>Bringing us redemption;<br/>That in the dead of night,<br/>Not one faint hope in sight,<br/>God, gracious, tender,<br/>Laid aside His splendor,<br/>Stooping to woo, to win, to save my soul.<br/>',NULL,409,409);
INSERT INTO stanza VALUES('E82','3','Without reluctance,<br/>Flesh and blood His substance<br/>He took the form of man,<br/>Revealed the hidden plan.<br/>O glorious myst''ry,<br/>Sacrifice of Calv''ry,<br/>And now I know Thou art the great "I AM."<br/>',NULL,410,410);
INSERT INTO stanza VALUES('E83','1','Hark! What mean those holy voices<br/>Sweetly sounding in the skies?<br/>Lo! Th'' angelic host rejoices,<br/>Loudest hallelujahs rise.<br/>',NULL,411,411);
INSERT INTO stanza VALUES('E83','2','Listen to the wondrous story<br/>Which they chant in hymns of joy:<br/>"Glory in the highest, glory!<br/>Glory be to God most high!<br/>',NULL,412,412);
INSERT INTO stanza VALUES('E83','3','"Peace on earth, good-will from heaven,<br/>Reaching far as man is found;<br/>Souls redeemed and sins forgiven,<br/>Loud our golden harps shall sound.<br/>',NULL,413,413);
INSERT INTO stanza VALUES('E83','4','"Christ is born! The great Anointed!<br/>Heaven and earth His glory sing;<br/>Oh, receive whom God appointed<br/>For your Prophet, Priest, and King!<br/>',NULL,414,414);
INSERT INTO stanza VALUES('E83','5','"Hasten, mortals, to adore Him<br/>Learn His name and taste His joy,<br/>Till one day ye sing before Him<br/>Glory be to God most high! "<br/>',NULL,415,415);
INSERT INTO stanza VALUES('E83','6','Let us learn the wondrous story<br/>Of our great Redeemer''s birth;<br/>Spread the brightness of His glory,<br/>Till it cover all the earth.<br/>',NULL,416,416);
INSERT INTO stanza VALUES('E84','1','Hark! The herald angels sing,<br/>"Glory to the new-born King;<br/>Peace on earth, and mercy mild;<br/>God and sinners reconciled."<br/>Joyful, all ye nations, rise,<br/>Join the triumph of the skies;<br/>With angelic hosts proclaim,<br/>"Christ is born in Bethlehem."<br/>(Repeat the last two lines)<br/>',NULL,417,417);
INSERT INTO stanza VALUES('E84','2','Christ, by highest heav''n adored,<br/>Christ, the everlasting Lord:<br/>Late in time behold Him come,<br/>Offspring of a virgin''s womb.<br/>Veiled in flesh the Godhead see,<br/>Hail th'' incarnate Deity!<br/>Pleased as man with man to dwell,<br/>Jesus our Immanuel.<br/>',NULL,418,418);
INSERT INTO stanza VALUES('E84','3','Hail the heav''n-born Prince of Peace!<br/>Hail the Sun of righteousness!<br/>Light and life to all He brings,<br/>Ris''n with healing in His wings:<br/>Mild He lays His glory by,<br/>Born that man no more may die;<br/>Born to raise the sons of earth;<br/>Born to give them second birth.<br/>',NULL,419,419);
INSERT INTO stanza VALUES('E84','4','Come, Desire of nations, come!<br/>Fix in us Thy humble home:<br/>Rise, the woman''s conqu''ring seed,<br/>Bruise in us the serpent''s head;<br/>Adam''s likeness now efface,<br/>Stamp Thine image in its place:<br/>Final Adam from above,<br/>Reinstate us in Thy love.<br/>',NULL,420,420);
INSERT INTO stanza VALUES('E85','1','O come, all ye faithful! Joyfully triumphant,<br/>To Bethlehem hasten now with glad accord;<br/>Lo! In a manger lies the God Almighty;<br/>',NULL,421,421);
INSERT INTO stanza VALUES('E85','chorus','O come, let us adore Him,<br/>O come, let us adore Him,<br/>O come, let us adore Him,<br/>Christ the Lord!<br/>',NULL,422,422);
INSERT INTO stanza VALUES('E85','2','Raise, raise choirs of angels, songs of loudest triumph,<br/>Through heaven''s high arches be your praises poured:<br/>Now to our God be glory in the highest;<br/>',NULL,423,423);
INSERT INTO stanza VALUES('E85','3','Amen! Lord, we bless Thee, born for our salvation!<br/>O Jesus! forever be Thy Name adored;<br/>Word of the Father, late in flesh appearing;<br/>',NULL,424,424);
INSERT INTO stanza VALUES('E86','1','Though Thou art God, most glorious, high,<br/>Thou in the flesh to us came nigh,<br/>A lowly man become thereby;<br/>Lord, I remember Thee!<br/>',NULL,425,425);
INSERT INTO stanza VALUES('E86','2','Glory divine was put away<br/>Under the tent of flesh to stay,<br/>No outward beauty to display;<br/>Lord, I remember Thee!<br/>',NULL,426,426);
INSERT INTO stanza VALUES('E86','3','Thou art a root from out dry ground,<br/>Thou wast the Man of sorrows found,<br/>Hated, despised by man around;<br/>Lord, I remember Thee!<br/>',NULL,427,427);
INSERT INTO stanza VALUES('E86','4','Gentle and lowly is Thy heart,<br/>Willing to suffer all Thou art,<br/>To God and man complaining not;<br/>Lord, I remember Thee!<br/>',NULL,428,428);
INSERT INTO stanza VALUES('E86','5','Thou as a man art tender, sweet,<br/>Balanced in every way, complete,<br/>Meal-offering to the Father meet;<br/>Lord, I remember Thee!<br/>',NULL,429,429);
INSERT INTO stanza VALUES('E86','6','Doing the Father''s will Thy prize,<br/>Never accepting Satan''s lies,<br/>None like Thyself, so faithful, wise;<br/>Lord, I remember Thee!<br/>',NULL,430,430);
INSERT INTO stanza VALUES('E86','7','For Thine obedience to God''s will,<br/>Willing to suffer deathly ill,<br/>E''en on the Cross my place to fill,<br/>Lord, I remember Thee!<br/>',NULL,431,431);
INSERT INTO stanza VALUES('E86','8','Therefore hath God exalted Thee,<br/>Given Thee glory, majesty,<br/>Heaven and earth will bow the knee;<br/>O Lord, I worship Thee!<br/>',NULL,432,432);
INSERT INTO stanza VALUES('E87','1','O Lord! When we the path retrace<br/>Which Thou on earth hast trod,<br/>To men Thy wondrous love and grace,<br/>Thy faithfulness to God;<br/>',NULL,433,433);
INSERT INTO stanza VALUES('E87','2','Thy love, by man so sorely tried,<br/>Proved stronger than the grave;<br/>The very spear that pierced<br/>Thy side Drew forth the blood to save;<br/>',NULL,434,434);
INSERT INTO stanza VALUES('E87','3','Though Thou didst pass through woes and grief,<br/>Thy works were ever good;<br/>Although midst sorrows all Thy life,<br/>Thou spak''st no murmuring word.<br/>',NULL,435,435);
INSERT INTO stanza VALUES('E87','4','Faithful amidst unfaithfulness,<br/>''Mid darkness only light,<br/>Thou didst Thy Father''s name confess,<br/>And in His will delight;<br/>',NULL,436,436);
INSERT INTO stanza VALUES('E87','5','Unmoved by Satan''s subtle wiles,<br/>Or, suffering, shame, and loss,<br/>Thy path, uncheered by earthly smiles,<br/>Led only to the cross.<br/>',NULL,437,437);
INSERT INTO stanza VALUES('E87','6','We wonder at Thy lowly mind,<br/>And fain would like Thee be,<br/>And all our rest and pleasure find<br/>In learning, Lord, of Thee.<br/>',NULL,438,438);
INSERT INTO stanza VALUES('E88','1','How beauteous were the marks divine,<br/>That in Thy meekness used to shine,<br/>That lit Thy lonely pathway, trod<br/>In wondrous love, O Son of God!<br/>',NULL,439,439);
INSERT INTO stanza VALUES('E88','2','O who like Thee, so mild, so bright,<br/>Thou Son of man, Thou Light of light?<br/>O who like Thee did ever go<br/>So patient, through a world of woe?<br/>',NULL,440,440);
INSERT INTO stanza VALUES('E88','3','O who like Thee so humbly bore<br/>The scorn, the scoffs of men, before?<br/>So meek, so lowly, yet so high,<br/>So glorious in humility?<br/>',NULL,441,441);
INSERT INTO stanza VALUES('E88','4','And death, that sets the prisoner free,<br/>Was pang, and scoff, and scorn to Thee;<br/>Yet love through all Thy torture glowed,<br/>And mercy with Thy life-blood flowed.<br/>',NULL,442,442);
INSERT INTO stanza VALUES('E88','5','O wondrous Lord, my soul would be<br/>Still more and more conformed to Thee,<br/>And learn of Thee, the lowly One,<br/>And like Thee, all my journey run.<br/>',NULL,443,443);
INSERT INTO stanza VALUES('E89','1','What grace, O Lord, and beauty shone<br/>Around Thy steps below!<br/>What patient love was seen in all<br/>Thy life and death of woe!<br/>',NULL,444,444);
INSERT INTO stanza VALUES('E89','2','Forever on Thy burdened heart<br/>A weight of sorrow hung,<br/>Yet no ungentle, murm''ring word<br/>Escaped Thy silent tongue.<br/>',NULL,445,445);
INSERT INTO stanza VALUES('E89','3','Thy foes did hate, despise, revile,<br/>Thy friends unfaithful prove;<br/>Unwearied in forgiveness still<br/>Thy heart could only love!<br/>',NULL,446,446);
INSERT INTO stanza VALUES('E90','1','Lord, accept our feeble song!<br/>Pow''r and praise to Thee belong;<br/>We would all Thy grace record,<br/>Holy, gracious, loving Lord!<br/>',NULL,447,447);
INSERT INTO stanza VALUES('E90','2','Rich in glory, Thou didst stoop,<br/>Thence is all Thy people''s hope;<br/>Thou wast poor, that we might be<br/>Rich in glory, Lord, with Thee.<br/>',NULL,448,448);
INSERT INTO stanza VALUES('E90','3','Wherefore Thou high heaven didst spurn?<br/>Wherefore Thou to earth didst turn?<br/>Why leave heav''n to come to earth<br/>Lonely, scorned, e''en suffering death?<br/>',NULL,449,449);
INSERT INTO stanza VALUES('E90','4','Thou in heav''n-the glorious One!<br/>Thou on earth-the outcast Man!<br/>Though this suffering Thou didst know,<br/>Love would come to bear our woe.<br/>',NULL,450,450);
INSERT INTO stanza VALUES('E90','5','When we think of love like this,<br/>Joy and shame our hearts possess;<br/>Joy, that Thou couldst pity thus;<br/>Shame, for such returns from us.<br/>',NULL,451,451);
INSERT INTO stanza VALUES('E90','6','Yet we hope the day to see<br/>When from every hindrance free,<br/>When to Thee, in glory, brought,<br/>We shall serve Thee as we ought.<br/>',NULL,452,452);
INSERT INTO stanza VALUES('E90','7','Now, O Lord, we wait for Thee,<br/>Wait "the blessed hope" to see.<br/>May we ever for Thee live,<br/>Till Thy saints Thou dost receive.<br/>',NULL,453,453);
INSERT INTO stanza VALUES('E91','1','It was alone the Savior prayed<br/>In dark Gethsemane;<br/>Alone He drained the bitter cup<br/>And suffered there for me.<br/>',NULL,454,454);
INSERT INTO stanza VALUES('E91','chorus','Alone, alone,<br/>He bore it all alone;<br/>He gave Himself to save His own,<br/>He suffered, bled and died alone, alone.<br/>',NULL,455,455);
INSERT INTO stanza VALUES('E91','2','It was alone the Savior stood<br/>In Pilate''s judgment hall;<br/>Alone the crown of thorns He wore,<br/>Forsaken thus by all.<br/>',NULL,456,456);
INSERT INTO stanza VALUES('E91','3','Alone upon the cross He hung<br/>That others He might save;<br/>Forsaken then by God and man.<br/>Alone, His life He gave.<br/>',NULL,457,457);
INSERT INTO stanza VALUES('E91','4','Can you reject such matchless love?<br/>Can you His claim disown?<br/>Come, give your all in gratitude,<br/>Nor leave Him thus alone.<br/>',NULL,458,458);
INSERT INTO stanza VALUES('E92','1','O dearest Lord, what law hast Thou e''er broken<br/>That such sharp sentence should on Thee be spoken?<br/>Of what misdeed hast Thou to make confession-<br/>What dark transgression?<br/>',NULL,459,459);
INSERT INTO stanza VALUES('E92','2','They crown Thy head with thorns, they smite,<br/>they scourge Thee;<br/>With cruel mockings to the cross they urge Thee;<br/>They give Thee gall to drink, they still decry Thee;<br/>They crucify Thee.<br/>',NULL,460,460);
INSERT INTO stanza VALUES('E92','3','What punishment so strange is suffered yonder?<br/>The shepherd dies for sheep that loved to wander;<br/>The Master pays the debt His servants owe Him,<br/>Who would not know Him.<br/>',NULL,461,461);
INSERT INTO stanza VALUES('E92','4','The sinless Son of God must die in sadness;<br/>The sinful child of man may live in gladness;<br/>Man forfeited His life and is acquitted-<br/>God is committed.<br/>',NULL,462,462);
INSERT INTO stanza VALUES('E92','5','O mighty King, no time can dim Thy glory!<br/>How shall I spread abroad Thy wondrous story?<br/>How shall I find some worthy gift to proffer?<br/>What dare I offer?<br/>',NULL,463,463);
INSERT INTO stanza VALUES('E92','6','I''ll think upon Thy mercy without ceasing;<br/>That earth''s vain joys no more to me be pleasing;<br/>To do Thy will shall be my sole endeavor<br/>Henceforth forever.<br/>',NULL,464,464);
INSERT INTO stanza VALUES('E93','1','Lord, we treasure with affection<br/>All Thy path of sorrow here,<br/>And those closing scenes of anguish<br/>To our hearts Thyself endear.<br/>',NULL,465,465);
INSERT INTO stanza VALUES('E93','chorus','Praise Thee, Savior! Praise Thee, Savior!<br/>Praise Thee, Lord, for sinners slain!<br/>Give Thee glory! Give Thee glory!<br/>Give Thee glory for the life we gain!<br/>',NULL,466,466);
INSERT INTO stanza VALUES('E93','2','Deep Thy sorrow then, Lord Jesus,<br/>Deeper far than thought can reach;<br/>Grief intense and suff''rings holy,<br/>Far beyond all tongues to teach.<br/>',NULL,467,467);
INSERT INTO stanza VALUES('E93','3','None could follow there, blest Savior,<br/>When redemption''s work was done;<br/>For those suff''rings, deep, unfathomed,<br/>Were, Lord Jesus, Thine alone!<br/>',NULL,468,468);
INSERT INTO stanza VALUES('E93','4','Thou didst measure then sin''s distance,<br/>Darkness, wrath and curse were Thine:<br/>Man-betrayed, by God forsaken;<br/>Thus we learn Thy love divine!<br/>',NULL,469,469);
INSERT INTO stanza VALUES('E94','1','O Christ, what burdens bow''d Thy head!<br/>Our load was laid on Thee;<br/>Thou stoodest in the sinner''s stead,<br/>Didst bear all ill for me.<br/>A victim led; Thy blood was shed;<br/>Now there''s no load for me.<br/>',NULL,470,470);
INSERT INTO stanza VALUES('E94','2','Death and the curse were in our cup,<br/>O Christ, ''twas full for Thee!<br/>But Thou hast drained the last dark drop-<br/>''Tis empty now for me.<br/>That bitter cup-love drank it up;<br/>Now blessings'' draught for me.<br/>',NULL,471,471);
INSERT INTO stanza VALUES('E94','3','Jehovah lifted up His rod,<br/>O Christ, it fell on Thee!<br/>Thou wast sore stricken of Thy God;<br/>There''s not one stroke for me.<br/>Thy tears, Thy blood, beneath it flowed;<br/>Thy bruising healeth me.<br/>',NULL,472,472);
INSERT INTO stanza VALUES('E94','4','The tempest''s awful voice was heard,<br/>O Christ, it broke on Thee!<br/>Thy open bosom was my ward,<br/>It braved the storm for me.<br/>Thy form was scarred, Thy visage marred;<br/>Now cloudless peace for me.<br/>',NULL,473,473);
INSERT INTO stanza VALUES('E94','5','Jehovah bade His sword awake,<br/>O Christ, it woke ''gainst Thee!<br/>Thy blood the flaming blade must slake;<br/>Thy heart its sheath must be-<br/>All for my sake, my peace to make;<br/>Now sleeps that sword for me.<br/>',NULL,474,474);
INSERT INTO stanza VALUES('E94','6','For me, Lord Jesus, Thou hast died,<br/>And I have died in Thee;<br/>Thou''rt ris''n: my bands are all untied,<br/>And now Thou liv''st in me.<br/>When purified, made white, and tried,<br/>Thy glory then for me!<br/>',NULL,475,475);
INSERT INTO stanza VALUES('E95','1','O Head once full of bruises,<br/>So full of pain and scorn,<br/>Mid other sore abuses,<br/>Mocked with a crown of thorn:<br/>O Head e''en now surrounded<br/>With brightest majesty,<br/>In death once bowed and wounded<br/>On the accursed tree:<br/>',NULL,476,476);
INSERT INTO stanza VALUES('E95','2','Thou Countenance transcendent!<br/>Thou life-creating Sun!<br/>To worlds on Thee dependent-<br/>Yet bruised and spit upon:<br/>O Lord, what Thee tormented<br/>Was our sins'' heavy load,<br/>We had the debt augmented<br/>Which Thou didst pay in blood.<br/>',NULL,477,477);
INSERT INTO stanza VALUES('E95','3','We give Thee thanks unfeigned,<br/>O Savior, Friend in need,<br/>For what Thy soul sustained<br/>When Thou for us didst bleed.<br/>Grant us to lean unshaken<br/>Upon Thy faithfulness,<br/>Until, to glory taken,<br/>We see Thee face to face.<br/>',NULL,478,478);
INSERT INTO stanza VALUES('E96','1','My song is love unknown,<br/>My Savior''s love to me;<br/>Love to the loveless shown,<br/>That they might lovely be.<br/>O who am I,<br/>That for my sake<br/>My Lord should take<br/>Frail flesh, and die?<br/>',NULL,479,479);
INSERT INTO stanza VALUES('E96','2','He came from His blest throne<br/>Salvation to bestow;<br/>But men made strange, and none<br/>The longed-for Christ would know:<br/>But oh, my Friend,<br/>My Friend indeed,<br/>Who at my need<br/>His life did spend.<br/>',NULL,480,480);
INSERT INTO stanza VALUES('E96','3','Sometimes they strew His way,<br/>And His sweet praises sing;<br/>Resounding all the day<br/>Hosannas to their King:<br/>Then "Crucify!"<br/>Is all their breath,<br/>And for His death<br/>They thirst and cry.<br/>',NULL,481,481);
INSERT INTO stanza VALUES('E96','4','They rise and needs will have<br/>My dear Lord made away;<br/>A murderer they save ''<br/>The Prince of life they slay.<br/>Yet cheerful He<br/>To suffering goes,<br/>That He His foes<br/>From thence might free.<br/>',NULL,482,482);
INSERT INTO stanza VALUES('E96','5','In life, no house, no home<br/>My Lord on earth might have;<br/>In death, no friendly tomb,<br/>But what a stranger gave.<br/>What may I say?<br/>Heav''n was His home;<br/>But mine the tomb<br/>Wherein He lay.<br/>',NULL,483,483);
INSERT INTO stanza VALUES('E96','6','Here might I stay and sing,<br/>No story so divine;<br/>Never was love, dear King,<br/>Never was grief like Thine.<br/>This is my Friend,<br/>In whose sweet praise<br/>I all my days<br/>Could gladly spend.<br/>',NULL,484,484);
INSERT INTO stanza VALUES('E97','1','Thy sorrows, Savior, we retrace,<br/>And tears of praise Thy griefs compel.<br/>What love and grace illume Thy face<br/>As Jesus, as Immanuel!<br/>',NULL,485,485);
INSERT INTO stanza VALUES('E97','2','Amid Thy loneliness below,<br/>What scorn and outrage Thee befell:<br/>Deep shame and woe, rude blow on blow,<br/>Endured for us, Immanuel!<br/>',NULL,486,486);
INSERT INTO stanza VALUES('E97','3','But oh, what grief, what agony,<br/>When wrathful judgment''s awful spell<br/>Burst over Thee on Calv''ry''s tree,<br/>God''s Lamb for us, Immanuel!<br/>',NULL,487,487);
INSERT INTO stanza VALUES('E97','4','Arisen radiant from the dead,<br/>Thy sorrow''s scars forever tell,<br/>Creation''s Head is He who bled-<br/>Still Jesus, still Immanuel!<br/>',NULL,488,488);
INSERT INTO stanza VALUES('E97','5','E''en now from saints, in concord sweet,<br/>Celestial strains of worship well;<br/>For, O, ''tis meet glad songs should greet<br/>Thy heart of love, Immanuel!<br/>',NULL,489,489);
INSERT INTO stanza VALUES('E97','6','But when Thy glorious face we see,<br/>How shall the bursting paean swell!<br/>Our souls shall be outpoured for Thee-<br/>Outpoured for Thee, Immanuel!<br/>',NULL,490,490);
INSERT INTO stanza VALUES('E98','1','Jesus! Source of life eternal!<br/>Jesus, Author of our breath!<br/>Victor o''er the hosts infernal,<br/>By defeat, and shame, and death,<br/>Thou through deepest tribulation<br/>Deigned to pass for our salvation:<br/>Thousand, thousand praises be,<br/>Lord of glory, unto Thee!<br/>',NULL,491,491);
INSERT INTO stanza VALUES('E98','2','Thou, O Son of God! wert bearing<br/>Cruel mockings, hatred, scorn;<br/>Thou, the King of glory, wearing,<br/>For our sake, the crown of thorn:<br/>Dying, Thou didst us deliver<br/>From the chains of sin for ever;<br/>Thousand, thousand praises be,<br/>Precious Savior, unto Thee!<br/>',NULL,492,492);
INSERT INTO stanza VALUES('E98','3','All the shame men heaped upon Thee,<br/>Thou didst patiently endure;<br/>Not the pains of death too bitter,<br/>Our redemption to procure:<br/>Wondrous Thy humiliation<br/>To accomplish our salvation:<br/>Thousand, thousand praises be,<br/>Precious Savior, unto Thee!<br/>',NULL,493,493);
INSERT INTO stanza VALUES('E98','4','Heart-felt praise and adoration,<br/>Savior, thus to Thee we give:<br/>For Thy life''s humiliation,<br/>For Thy death, whereby we live;<br/>All the grief Thou wert enduring,<br/>All the bliss Thou wert securing,<br/>Evermore the theme shall be,<br/>Of thanksgivings, Lord, to Thee.<br/>',NULL,494,494);
INSERT INTO stanza VALUES('E99','1','''Tis midnight, and on Olive''s brow<br/>The star is dimmed that lately shone;<br/>''Tis midnight in the garden now,<br/>The suff''ring Savior prays alone.<br/>',NULL,495,495);
INSERT INTO stanza VALUES('E99','2','''Tis midnight, and from all removed,<br/>The Savior wrestles lone with fears-<br/>E''en that disciple whom He loved<br/>Heeds not his Master''s grief and tears.<br/>',NULL,496,496);
INSERT INTO stanza VALUES('E99','3','''Tis midnight, and for other''s guilt<br/>The Man of Sorrows weeps in blood;<br/>Yet He that hath in anguish knelt<br/>Is not forsaken by His God.<br/>',NULL,497,497);
INSERT INTO stanza VALUES('E99','4','''Tis midnight, and from ether-plains<br/>Is borne the song that angels know-<br/>Unheard by mortals are the strains<br/>That sweetly soothe the Savior''s woe.<br/>',NULL,498,498);
INSERT INTO stanza VALUES('E100','1','The Maker of the universe<br/>As Man, for man was made a curse.<br/>The claims of law which He had made,<br/>Unto the uttermost He paid.<br/>',NULL,499,499);
INSERT INTO stanza VALUES('E100','2','His holy fingers made the bough<br/>Which grew the thorns that, crowned His brow.<br/>The nails that pierced His hands were mined<br/>In secret places He designed.<br/>',NULL,500,500);
INSERT INTO stanza VALUES('E100','3','He made the forest whence there sprung<br/>The tree on which His body hung.<br/>He died upon a cross of wood,<br/>Yet made the hill on which it stood.<br/>',NULL,501,501);
INSERT INTO stanza VALUES('E100','4','The sky that darkened o''er His head<br/>By Him above the earth was spread.<br/>The sun that hid from Him its face<br/>By His decree was poised in space.<br/>',NULL,502,502);
INSERT INTO stanza VALUES('E100','5','The spear which spilled His precious blood<br/>Was tempered in the fires of God.<br/>The grave in which His form was laid,<br/>Was hewn in rocks His hands had made.<br/>',NULL,503,503);
INSERT INTO stanza VALUES('E100','6','The throne on which He now appears<br/>Was His from everlasting years,<br/>But a new glory crowns His brow,<br/>And every knee to Him shall bow.<br/>',NULL,504,504);
INSERT INTO stanza VALUES('E101','1','When we survey the wondrous cross<br/>On which the Lord of glory died,<br/>Our richest gain we count but loss,<br/>And pour contempt on all our pride.<br/>',NULL,505,505);
INSERT INTO stanza VALUES('E101','2','Our God, forbid that we should boast,<br/>Save in the death of Christ, our Lord;<br/>All the vain things that charm us most,<br/>We''d sacrifice them to His blood.<br/>',NULL,506,506);
INSERT INTO stanza VALUES('E101','3','There from His head, His hands, His feet,<br/>Sorrow and love flowed mingled down;<br/>Did e''er such love and sorrow meet,<br/>Or thorns compose so rich a crown?<br/>',NULL,507,507);
INSERT INTO stanza VALUES('E101','4','His dying crimson, from His head<br/>Spreads o''er His body on the tree;<br/>To all the world then am I dead,<br/>And all the world is dead to me.<br/>',NULL,508,508);
INSERT INTO stanza VALUES('E101','5','Were the whole realm of nature ours,<br/>That were an offering far too small;<br/>Love that transcends our highest pow''rs,<br/>Demands our heart, our life, our all.<br/>',NULL,509,509);
INSERT INTO stanza VALUES('E102','1','We sing the praise of Him who died,<br/>Of Him who died upon the Cross;<br/>The sinner''s hope let men deride,<br/>For this we count the world but loss.<br/>',NULL,510,510);
INSERT INTO stanza VALUES('E102','2','Inscribed upon the Cross we see<br/>In shining letters, God is love!<br/>He bears our sins upon the tree,<br/>He brings us mercy from above.<br/>',NULL,511,511);
INSERT INTO stanza VALUES('E102','3','The Cross: it takes our guilt away;<br/>It holds the fainting spirit up;<br/>It cheers with hope the gloomy day,<br/>And sweetens every bitter cup.<br/>',NULL,512,512);
INSERT INTO stanza VALUES('E102','4','The balm of life, the cure of woe,<br/>The measure and the pledge of love,<br/>The sinner''s refuge here below,<br/>The angels'' theme in heav''n above.<br/>',NULL,513,513);
INSERT INTO stanza VALUES('E103','1','Behold! Behold the Lamb of God,<br/>On the cross! On the cross!<br/>For us He shed His precious blood,<br/>On the cross! On the cross!<br/>O hear His all-important cry,<br/>"Eli, lama sabachthani?"<br/>Draw near and see the Savior die,<br/>On the cross! On the cross!<br/>',NULL,514,514);
INSERT INTO stanza VALUES('E103','2','Behold His arms extended wide,<br/>On the cross! On the cross!<br/>Behold His bleeding hands and side,<br/>On the cross! On the cross!<br/>The sun withholds its rays of light,<br/>The heav''ns are clothed in shades of night,<br/>While Jesus wins the glorious fight,<br/>On the cross! On the cross!<br/>',NULL,515,515);
INSERT INTO stanza VALUES('E103','3','By faith we see Him lifted up,<br/>On the cross! On the cross!<br/>He drinks for us the bitter cup,<br/>On the cross! On the cross!<br/>The rocks do rend, the mountains quake,<br/>While Jesus all our sins doth take,<br/>While Jesus suffers for our sake,<br/>On the cross! On the cross!<br/>',NULL,516,516);
INSERT INTO stanza VALUES('E103','4','And now the mighty deed is done,<br/>On the cross! On the cross!<br/>The battle fought, the vict''ry won,<br/>On the cross! On the cross!<br/>To heav''n He turns triumphant eyes;<br/>" ''Tis finished" now, the Conqu''ror cries,<br/>Then bows His sacred head and dies,<br/>On the cross! On the cross!<br/>',NULL,517,517);
INSERT INTO stanza VALUES('E103','5','But now He''s ris''n, ascended, crowned,<br/>On the throne! On the throne!<br/>Heav''n''s highest place for Him is found,<br/>On the throne! On the throne!<br/>Our hearts we low in worship bow,<br/>And join, as one, to hail Him now:<br/>"Worthy, O Lamb of God, art Thou!"<br/>On the throne! On the throne!<br/>',NULL,518,518);
INSERT INTO stanza VALUES('E104','1','Alas! And did my Savior bleed?<br/>And did my Sov''reign die,<br/>Would He devote that sacred head<br/>For such a worm as I?<br/>',NULL,519,519);
INSERT INTO stanza VALUES('E104','2','Was it for sins that I had done<br/>He groaned upon the tree?<br/>Amazing pity! Grace unknown!<br/>And love beyond degree!<br/>',NULL,520,520);
INSERT INTO stanza VALUES('E104','3','Well might the sun in darkness hide,<br/>And shut his glories in,<br/>When the incarnate Maker died<br/>For man, His creature''s sin.<br/>',NULL,521,521);
INSERT INTO stanza VALUES('E104','4','Thus might I hide my blushing face<br/>While His dear cross appears<br/>Dissolve my heart in thankfulness,<br/>And melt mine eyes to tears.<br/>',NULL,522,522);
INSERT INTO stanza VALUES('E104','5','But drops of grief can ne''er repay<br/>The debt of love I owe;<br/>Here, Lord, I give myself away:<br/>''Tis all that I can do.<br/>',NULL,523,523);
INSERT INTO stanza VALUES('E105','1','Himself He could not save,<br/>He on the cross must die,<br/>Or mercy could not come<br/>To ruined sinners nigh;<br/>Yes Christ, the Son of God, must bleed,<br/>That sinners might from sin be freed.<br/>',NULL,524,524);
INSERT INTO stanza VALUES('E105','2','Himself He could not save,<br/>For justice must be done;<br/>Our sins'' full weight must fall<br/>Upon the sinless One;<br/>For nothing less can God accept<br/>In payment of that fearful debt.<br/>',NULL,525,525);
INSERT INTO stanza VALUES('E105','3','Himself He could not save,<br/>For He the Surety stood<br/>For all who now rely<br/>Upon His precious blood;<br/>He bore the penalty of guilt<br/>When on the cross His blood was spilt.<br/>',NULL,526,526);
INSERT INTO stanza VALUES('E105','4','Himself He could not save,<br/>What wondrous love is this!<br/>In love Himself He gave,<br/>There ne''er was love like His!<br/>Such love should melt a heart of stone,<br/>Till praise flows forth to Him alone!<br/>',NULL,527,527);
INSERT INTO stanza VALUES('E106','1','No blood, no altar now,<br/>The sacrifice is o''er!<br/>No flame, no smoke ascends on high,<br/>The lamb is slain no more,<br/>But richer blood has flowed from nobler veins,<br/>To purge the soul from guilt, and cleanse the<br/>reddest stains.<br/>',NULL,528,528);
INSERT INTO stanza VALUES('E106','2','We thank Thee for the blood,<br/>The blood of Christ, God''s Son:<br/>The blood by which our peace is made,<br/>Redemption great is won,<br/>Delivering us from hell, and sin, and woe;<br/>That His eternal life God may to us bestow.<br/>',NULL,529,529);
INSERT INTO stanza VALUES('E107','1','Not all the blood of beasts,<br/>On Jewish altars slain,<br/>Could give the guilty conscience peace,<br/>Or wash away its stain.<br/>',NULL,530,530);
INSERT INTO stanza VALUES('E107','2','But Christ, the heavenly Lamb,<br/>Takes all our sins away;<br/>A sacrifice of nobler name,<br/>And richer blood than they.<br/>',NULL,531,531);
INSERT INTO stanza VALUES('E107','3','My faith would lay her hand<br/>On that dear head of Thine,<br/>While like a penitent I stand,<br/>And there confess my sin.<br/>',NULL,532,532);
INSERT INTO stanza VALUES('E107','4','My soul looks back to see<br/>The burdens Thou didst bear<br/>When hanging on the cursed tree,<br/>And knows her guilt was there.<br/>',NULL,533,533);
INSERT INTO stanza VALUES('E107','5','Believing, we rejoice<br/>To see the curse remove;<br/>We bless the Lamb with cheerful voice,<br/>And sing His bleeding love.<br/>',NULL,534,534);
INSERT INTO stanza VALUES('E108','1','"Man of Sorrows," what a name<br/>For the Son of God who came<br/>Ruined sinners to reclaim!<br/>Hallelujah! What a Savior!<br/>',NULL,535,535);
INSERT INTO stanza VALUES('E108','2','Bearing shame and scoffing rude,<br/>In my place condemned He stood;<br/>Sealed my pardon with His blood;<br/>Hallelujah! What a Savior!<br/>',NULL,536,536);
INSERT INTO stanza VALUES('E108','3','Guilty, vile, and helpless, we,<br/>Spotless Lamb of God was He;<br/>Full redemption-can it be?<br/>Hallelujah! What a Savior!<br/>',NULL,537,537);
INSERT INTO stanza VALUES('E108','4','Lifted up was He to die,<br/>"It is finished!" was His cry;<br/>Now in heaven exalted high;<br/>Hallelujah! What a Savior!<br/>',NULL,538,538);
INSERT INTO stanza VALUES('E108','5','When He comes, our glorious King,<br/>To His kingdom us to bring,<br/>Then anew this song we''ll sing:<br/>Hallelujah! What a Savior!<br/>',NULL,539,539);
INSERT INTO stanza VALUES('E109','1','The veil is rent! Lo! Jesus stands<br/>Before the throne of grace;<br/>And clouds of incense from His hands<br/>Fill all that glorious place.<br/>',NULL,540,540);
INSERT INTO stanza VALUES('E109','2','His precious blood is sprinkled there,<br/>Before and on the throne;<br/>And His own wounds in heav''n declare<br/>His work on earth is done.<br/>',NULL,541,541);
INSERT INTO stanza VALUES('E109','3','" ''Tis finished!" on the cross He said,<br/>''In agonies and blood;<br/>''Tis finished: now He lives to plead<br/>Before the face of God.<br/>',NULL,542,542);
INSERT INTO stanza VALUES('E109','4','" ''Tis finished!" Here our souls can rest,<br/>His work can never fail;<br/>By Him, our Sacrifice and Priest,<br/>We enter through the veil.<br/>',NULL,543,543);
INSERT INTO stanza VALUES('E110','1','O solemn hour! O hour alone,<br/>In solitary night,<br/>When God the Father''s only Son,<br/>As Man, for sinners lost, undone,<br/>Expires-amazing sight!<br/>The Lord of glory crucified!<br/>The Lord of Life has bled and died!<br/>',NULL,544,544);
INSERT INTO stanza VALUES('E110','2','O mystery of mysteries!<br/>Of life and death the tree!<br/>Center of two eternities,<br/>Which look with rapt, adoring eyes,<br/>Onward, and back to Thee!<br/>O cross of Christ, where all His pain<br/>And death is our eternal gain.<br/>',NULL,545,545);
INSERT INTO stanza VALUES('E110','3','O how our inmost hearts do move,<br/>While gazing on that cross!<br/>The death of the incarnate Love!<br/>What shame, what grief, what joy we prove,<br/>That He should die for us!<br/>Our hearts were broken by that cry,<br/>"Eli, lama sabachthani!"<br/>',NULL,546,546);
INSERT INTO stanza VALUES('E110','4','Worthy of death, O Lord, we were;<br/>That vengeance was our due;<br/>In grace Thou, spotless Lamb, didst bear<br/>Thyself our sins, and guilt, and fear;<br/>Justice our Surety slew.<br/>With Thee, our Surety, we have died;<br/>With Thee, we there were crucified.<br/>',NULL,547,547);
INSERT INTO stanza VALUES('E110','5','Quickened with Thee with life divine,<br/>Raised with Thee from the dead;<br/>Thine Own, now human and divine,<br/>Shall with Thee in Thy glories shine,<br/>The Church''s living Head!<br/>We, who were worthy but to die,<br/>Now with Thee, "Abba Father," cry.<br/>',NULL,548,548);
INSERT INTO stanza VALUES('E111','1','Jesus, the sinner''s Friend,<br/>We hide ourselves in Thee;<br/>God looks upon Thy sprinkled blood,<br/>It is our only plea.<br/>',NULL,549,549);
INSERT INTO stanza VALUES('E111','2','He hears Thy precious Name,<br/>We claim it as our own;<br/>The Father must accept and bless<br/>His well-beloved Son.<br/>',NULL,550,550);
INSERT INTO stanza VALUES('E111','3','Thou hast fulfilled the law,<br/>And we are justified:<br/>Ours is the blessing, Thine the curse;<br/>We live, for Thou hast died.<br/>',NULL,551,551);
INSERT INTO stanza VALUES('E111','4','Jesus, the sinner''s Friend!<br/>We cannot speak Thy praise;<br/>No mortal voice can sing the song<br/>That ransomed hearts would raise.<br/>',NULL,552,552);
INSERT INTO stanza VALUES('E111','5','But when before the throne,<br/>Thy face we all shall see,<br/>Clothed in our blood-bought robes of white,<br/>We''ll stand complete in Thee.<br/>',NULL,553,553);
INSERT INTO stanza VALUES('E111','6','Jesus, we''ll give Thee then<br/>Such praises as are meet,<br/>And give ten thousand thanks to Thee,<br/>Adoring, at Thy feet.<br/>',NULL,554,554);
INSERT INTO stanza VALUES('E112','1','How sweet is the story of Christ''s boundless love,<br/>That brought Him to suffer from glory above!<br/>He died in our stead upon Calvary''s tree,<br/>Obtaining redemption that we might be free.<br/>',NULL,555,555);
INSERT INTO stanza VALUES('E112','chorus','Sound His praise! Sound His praise!<br/>All the work has been done;<br/>Praise His name! Praise His name!<br/>Jesus, God''s blessed Son.<br/>We give Him the glory, our Savior and Friend;<br/>Our song is of Jesus and never will end.<br/>',NULL,556,556);
INSERT INTO stanza VALUES('E112','2','How wondrous the story! the law''s holy claims<br/>Were met by the blood which redemption proclaims.<br/>The judgment of sin has been borne by the Son,<br/>Who glorified God in the work He has done.<br/>',NULL,557,557);
INSERT INTO stanza VALUES('E112','3','How brilliant the glory where Christ is enthroned<br/>How rightly His name above others is owned!<br/>Yes, Jesus, the Savior, the glory-crowned Lord,<br/>Is worthy by all to be ever adored.<br/>',NULL,558,558);
INSERT INTO stanza VALUES('E113','1','How pleasant is the sound of praise!<br/>It well becomes the saints of God;<br/>Should we refuse our songs to raise,<br/>The stones might tell our shame abroad.<br/>',NULL,559,559);
INSERT INTO stanza VALUES('E113','2','For Him Who washed us in His blood,<br/>Let us our sweetest songs prepare;<br/>He sought us wandering far from God,<br/>And now preserves us by His care.<br/>',NULL,560,560);
INSERT INTO stanza VALUES('E113','3','One string there is of sweetest tone,<br/>Reserved for sinners saved by grace;<br/>''Tis sacred to one class alone<br/>And touched by one peculiar race.<br/>',NULL,561,561);
INSERT INTO stanza VALUES('E113','4','Though angels may with rapture see<br/>How mercy flows in Jesus'' blood,<br/>It is not theirs to prove, as we,<br/>The cleansing virtue of this flood.<br/>',NULL,562,562);
INSERT INTO stanza VALUES('E113','5','Though angels praise the heavenly King,<br/>And worship Him as God alone,<br/>We can with exultation sing,<br/>"He wears our nature on the throne."<br/>',NULL,563,563);
INSERT INTO stanza VALUES('E113','6','Lord, we adore Thy wondrous love,<br/>Which brought Thee here to bleed and die<br/>That Thou lost sinners may restore<br/>And to the Father bring them nigh.<br/>',NULL,564,564);
INSERT INTO stanza VALUES('E114','1','Hail, Thou once despised Jesus!<br/>Hail, Thou still rejected King!<br/>Thou didst suffer to release us,<br/>Thou didst free salvation bring;<br/>Through Thy death and resurrection,<br/>Bearer of our sin and shame!<br/>We enjoy divine protection,<br/>Life and glory through Thy name.<br/>',NULL,565,565);
INSERT INTO stanza VALUES('E114','2','Paschal Lamb, by God appointed,<br/>All our sins on Thee were laid;<br/>By our Father''s love anointed,<br/>Thou redemption''s price hast paid.<br/>All who trust Thee are forgiven<br/>Through the virtue of Thy blood;<br/>Opened are the things of heaven,<br/>Grace shines forth to man from God.<br/>',NULL,566,566);
INSERT INTO stanza VALUES('E114','3','Savior, hail! Enthroned in glory,<br/>Where for us Thou dost abide;<br/>We, by faith, do now adore Thee,<br/>Seated at Thy Father''s side.<br/>There, for us Thou now art pleading,<br/>There Thou dost our sorrows share,<br/>Ever for us interceding,<br/>Till in glory we appear.<br/>',NULL,567,567);
INSERT INTO stanza VALUES('E114','4','Worship, honor, praise, and blessing,<br/>Thou art worthy to receive;<br/>Loudest praises, without ceasing,<br/>Meet it is for us to give.<br/>In that day Thy saints will meet Thee,<br/>Welcome Thee with grateful song;<br/>Joyful hearts will ever greet Thee,<br/>Source of joy to all the throng!<br/>',NULL,568,568);
INSERT INTO stanza VALUES('E115','1','Glory be to Jesus,<br/>Who in bitter pains<br/>Poured for me the life-blood<br/>From His sacred veins.<br/>',NULL,569,569);
INSERT INTO stanza VALUES('E115','2','Grace and life eternal<br/>In that Blood I find;<br/>Blest be His compassion,<br/>Infinitely kind.<br/>',NULL,570,570);
INSERT INTO stanza VALUES('E115','3','Blest through endless ages<br/>Be the precious stream,<br/>Which from endless torments<br/>Did the world redeem.<br/>',NULL,571,571);
INSERT INTO stanza VALUES('E115','4','Abel''s blood for vengeance<br/>Pleaded to the skies;<br/>But the blood of Jesus<br/>For our pardon cries.<br/>',NULL,572,572);
INSERT INTO stanza VALUES('E115','5','It the conscience sprinkles,<br/>Frees our guilty hearts;<br/>Satan in confusion<br/>Terror-struck departs.<br/>',NULL,573,573);
INSERT INTO stanza VALUES('E115','6','Oft as earth exulting<br/>Wafts its praise on high,<br/>Angel-hosts rejoicing<br/>Make their glad reply.<br/>',NULL,574,574);
INSERT INTO stanza VALUES('E115','7','Lift ye then your voices;<br/>Swell the mighty flood;<br/>Louder still and louder<br/>Praise the precious blood.<br/>',NULL,575,575);
INSERT INTO stanza VALUES('E116','1','How wonderful redemption is,<br/>My gracious Lord, in Thee!<br/>Not seen, nor heard, nor e''er conceived<br/>What Thou hast done for me!<br/>Thou art divine, mysterious,<br/>Beyond my grandest phrase!<br/>Redemption is so marvelous,<br/>Beyond all pow''r to praise!<br/>',NULL,576,576);
INSERT INTO stanza VALUES('E116','2','For us Thou on the Cross wast pierced,<br/>And blood and water streamed;<br/>That life divine be giv''n to us,<br/>That we may be redeemed.<br/>Thy precious blood has made us clean,<br/>That we accepted be;<br/>Regenerated by Thy life,<br/>We now are one with Thee.<br/>',NULL,577,577);
INSERT INTO stanza VALUES('E116','3','Thou art the grain divine that died<br/>The many grains to bear,<br/>Which, blent and formed, Thy Body are,<br/>And all Thy nature share.<br/>We are the increase of Thyself,<br/>And Thou our content art;<br/>Through us Thou livest and dost move<br/>And manifested art.<br/>',NULL,578,578);
INSERT INTO stanza VALUES('E116','4','Since we''re Thy Body, Thou may come<br/>And settle down in us;<br/>In us Thou may obtain Thy home<br/>And we become Thy trust.<br/>Thy heart to satisfy and please,<br/>We are Thy counterpart,<br/>Now in one Body with Thyself,<br/>Enjoying all Thou art.<br/>',NULL,579,579);
INSERT INTO stanza VALUES('E116','5','While in remembrance now we meet<br/>And here the symbols see,<br/>For Thy redemption great and full<br/>We''re filled with praise to Thee.<br/>Since we are made Thy Body, Lord,<br/>Thy dwelling place and bride,<br/>We would give thanks and worship Thee<br/>And in Thy praise abide.<br/>',NULL,580,580);
INSERT INTO stanza VALUES('E117','1','Christ the Lord is ris''n indeed,<br/>Hallelujah!<br/>He has met His people''s need,<br/>Hallelujah!<br/>Raise your joys and triumphs high,<br/>Hallelujah!<br/>Sing, ye heav''ns and earth, reply,<br/>Hallelujah!<br/>',NULL,581,581);
INSERT INTO stanza VALUES('E117','2','Lives again our glorious King,<br/>Hallelujah!<br/>Where, O Death, is now thy sting?<br/>Hallelujah!<br/>Dying once He all doth save,<br/>Hallelujah!<br/>Where thy victory, O grave?<br/>Hallelujah!<br/>',NULL,582,582);
INSERT INTO stanza VALUES('E117','3','Love''s redeeming work is done,<br/>Hallelujah!<br/>Fought the fight, the battle won,<br/>Hallelujah!<br/>Death in vain forbade Him rise,<br/>Hallelujah!<br/>Christ ascended o''er the skies,<br/>Hallelujah!<br/>',NULL,583,583);
INSERT INTO stanza VALUES('E117','4','Soar we now where Christ hath led,<br/>Hallelujah!<br/>Following our exalted Head,<br/>Hallelujah!<br/>Made like Him, like Him we rise,<br/>Hallelujah!<br/>Free from all the earthly ties,<br/>Hallelujah!<br/>',NULL,584,584);
INSERT INTO stanza VALUES('E118','1','Christ is risen! Hallelujah!<br/>Risen our victorious Head;<br/>Sing His praises; Hallelujah!<br/>Christ is risen from the dead.<br/>Gratefully our hearts adore Him,<br/>As His light once more appears;<br/>Bowing down in joy before Him,<br/>Rising up from griefs and tears.<br/>',NULL,585,585);
INSERT INTO stanza VALUES('E118','chorus','Christ is risen: Hallelujah!<br/>Risen our victorious Head;<br/>Sing His praises; Hallelujah!<br/>Christ is risen from the dead.<br/>',NULL,586,586);
INSERT INTO stanza VALUES('E118','2','Christ is risen! All the sadness<br/>Of His earthly life is o''er;<br/>Through the open gates of gladness<br/>He returns to life once more;<br/>Death and hell before Him bending,<br/>He doth rise the Victor now,<br/>Angels on His steps attending,<br/>Glory round His wounded brow.<br/>',NULL,587,587);
INSERT INTO stanza VALUES('E118','3','Christ is risen! Henceforth never<br/>Death nor hell shall us enthrall;<br/>We are Christ''s, in Him forever<br/>We have triumphed over all;<br/>All the doubting and dejection<br/>Of our trembling hearts have ceased,<br/>''Tis His day of resurrection;<br/>Let us rise and keep the feast.<br/>',NULL,588,588);
INSERT INTO stanza VALUES('E119','1','Hallelujah, "He is risen!"<br/>Jesus is gone up on high!<br/>Burst the bars of death asunder;<br/>Angels shout, and men reply:<br/>He is risen, He is risen,<br/>Living now, no more to die.<br/>',NULL,589,589);
INSERT INTO stanza VALUES('E119','2','Hallelujah, He is risen!<br/>Our exalted Head to be;<br/>Sends the witness of the Spirit<br/>That our Advocate is He:<br/>He is risen, He is risen,<br/>Justified in Him are we.<br/>',NULL,590,590);
INSERT INTO stanza VALUES('E119','3','Hallelujah, He is risen!<br/>Death for aye has lost his sting;<br/>Christ, Himself the Resurrection,<br/>From the grave "His own" will bring:<br/>He is risen, He is risen,<br/>Living Lord and coming King<br/>',NULL,591,591);
INSERT INTO stanza VALUES('E120','1','The Lord is ris''n; and death''s dark judgment flood<br/>Is passed, in Him who bought us with His blood.<br/>The Lord is ris''n: we stand beyond the doom<br/>Of all our sin, through Jesus'' empty tomb.<br/>',NULL,592,592);
INSERT INTO stanza VALUES('E120','2','The Lord is ris''n: with Him we also rose,<br/>And in His grave see vanquished all our foes.<br/>The Lord is ris''n: beyond the judgment land,<br/>In Him, in resurrection-life we stand.<br/>',NULL,593,593);
INSERT INTO stanza VALUES('E120','3','The Lord is ris''n: and now redeemed to God,<br/>We tread the desert which His feet have trod.<br/>The Lord is ris''n: the sanctu''ry''s our place,<br/>Where now we dwell before the Father''s face.<br/>',NULL,594,594);
INSERT INTO stanza VALUES('E120','4','The Lord is ris''n: the Lord is gone before.<br/>We long to see Him, and to sin no more.<br/>The Lord is ris''n: our triumph-shout shall be,<br/>"Thou hast prevailed! Thy people, Lord, are free!"<br/>',NULL,595,595);
INSERT INTO stanza VALUES('E121','1','Thine be the glory, risen, conquering Son,<br/>Endless is the vict''ry Thou o''er death hast won<br/>Angels in bright raiment rolled the stone away,<br/>Kept the folded grave-clothes, where Thy body lay.<br/>',NULL,596,596);
INSERT INTO stanza VALUES('E121','chorus','Thine be the glory, risen, conqu''ring Son,<br/>Endless is the vict''ry Thou o''er death hast won.<br/>',NULL,597,597);
INSERT INTO stanza VALUES('E121','2','Lo! Jesus meets us, risen from the tomb;<br/>Lovingly He greets us, scatters fear and gloom;<br/>Let the Church with gladness, hymns of triumph sing,<br/>For her Lord now liveth, death hath lost its sting.<br/>',NULL,598,598);
INSERT INTO stanza VALUES('E122','1','Thou, Lord, to death''s domain<br/>Didst go alone.<br/>Death had on Thee no claim,<br/>Thou sinless One!<br/>He who had death''s dread pow''r<br/>Met Thee in that dark hour:<br/>Vanquished by Thee his power,<br/>By Thee alone.<br/>',NULL,599,599);
INSERT INTO stanza VALUES('E122','2','But Thou hast burst the grave,<br/>Risen art Thou;<br/>Death could not Thee enslave,<br/>Death had to bow!<br/>Victorious hast Thou come<br/>Out of the darksome tomb,<br/>Broken the bands of gloom:<br/>Beyond death now.<br/>',NULL,600,600);
INSERT INTO stanza VALUES('E122','3','What mighty triumphs, Lord,<br/>Thou didst achieve!<br/>What fruitfulness doth God<br/>From Thee receive!<br/>Out of Thy death has sprung<br/>A wondrous living throng:<br/>All, all to Thee belong,<br/>And in Thee live.<br/>',NULL,601,601);
INSERT INTO stanza VALUES('E122','4','Firstborn of all Thou art,<br/>Lowly we bow;<br/>Chief in Thy Father''s heart-<br/>Chief to us now.<br/>Thou art indeed supreme,<br/>Our great eternal theme,<br/>Worthy of all esteem:<br/>Worthy art Thou!<br/>',NULL,602,602);
INSERT INTO stanza VALUES('E123','1','Low in the grave He lay-<br/>Jesus my Savior!<br/>Waiting the coming day-<br/>Jesus my Lord!<br/>',NULL,603,603);
INSERT INTO stanza VALUES('E123','chorus','Up from the grave He arose,<br/>With a mighty triumph o''er His foes;<br/>He arose a Victor from the dark domain,<br/>And He lives forever with His saints to reign.<br/>He arose! He arose.<br/>Hallelujah! Christ arose!<br/>',NULL,604,604);
INSERT INTO stanza VALUES('E123','2','Vainly they watch His bed-<br/>Jesus, my Savior!<br/>Vainly they seal the dead-<br/>Jesus, my Lord!<br/>',NULL,605,605);
INSERT INTO stanza VALUES('E123','3','Death cannot keep his prey-<br/>Jesus, my Savior!<br/>He tore the bars away-<br/>Jesus, my Lord!<br/>',NULL,606,606);
INSERT INTO stanza VALUES('E124','1','Praise Him! Praise Him! Christ is Victor!<br/>He has won the victory!<br/>Sin is judged, old Adam finished,<br/>Full redemption now we see!<br/>Vanquished all the evil powers<br/>Thru the Cross triumphantly!<br/>',NULL,607,607);
INSERT INTO stanza VALUES('E124','2','Praise Him! Christ is resurrected!<br/>God hath raised Him from the dead!<br/>All the pow''r of death is swallowed,<br/>Man from death to life is led!<br/>Broken through are hell and darkness<br/>And His pow''r exhibited!<br/>',NULL,608,608);
INSERT INTO stanza VALUES('E124','3','Praise Him! Christ hath now ascended!<br/>God hath raised Him to the throne!<br/>Far above all rule and power,<br/>He the highest Name doth own!<br/>All authority receiving<br/>Till His foe is overthrown!<br/>',NULL,609,609);
INSERT INTO stanza VALUES('E124','4','Hallelujah, Christ the Victor<br/>Triumphed on Mt. Calvary!<br/>Hallelujah, resurrected,<br/>He displays His victory!<br/>Hallelujah, now ascended,<br/>He shall reign eternally!<br/>',NULL,610,610);
INSERT INTO stanza VALUES('E125','1','Hallelujah! Sing to Jesus,<br/>His the scepter, His the throne;<br/>Hallelujah! His the triumph,<br/>His the victory alone.<br/>Hark, the songs of His redeemed ones<br/>Thunder like a mighty flood:<br/>Jesus out of every nation<br/>Hath redeemed us by His blood.<br/>',NULL,611,611);
INSERT INTO stanza VALUES('E125','2','Hallelujah! Not as orphans<br/>Are we left in sorrow now;<br/>Hallelujah! He is near us,<br/>Faith believes, nor questions how.<br/>Though the clouds from sight received Him<br/>When the forty days were o''er,<br/>Shall our hearts forget His promise,<br/>"I am with you evermore"?<br/>',NULL,612,612);
INSERT INTO stanza VALUES('E125','3','Hallelujah! Bread of heaven,<br/>Thou on earth our food, our stay;<br/>Hallelujah! Here the hungry<br/>Come to Thee from day to day.<br/>Advocate and Intercessor,<br/>My Redeemer pleads for me,<br/>On the throne of the Almighty<br/>Now and to eternity.<br/>',NULL,613,613);
INSERT INTO stanza VALUES('E125','4','Hallelujah! Sing to Jesus,<br/>His the scepter, His the throne;<br/>Hallelujah! His the triumph,<br/>His the victory alone.<br/>Hark, the songs of His redeemed ones<br/>Thunder like a mighty flood:<br/>Jesus out of every nation,<br/>Hath redeemed us by His blood.<br/>',NULL,614,614);
INSERT INTO stanza VALUES('E126','1','To Thee, dear Lord, O Christ of God,<br/>We sing, we ever sing;<br/>For Thou hast shed Thy precious blood<br/>Our cup of joy to bring.<br/>Thy mighty arm the fight hath fought,<br/>Thou art enthroned above;<br/>We into glory will be brought<br/>Thy wondrous grace to prove.<br/>',NULL,615,615);
INSERT INTO stanza VALUES('E126','2','To Thee, dear Lord, O Christ of God,<br/>We sing, we ever sing;<br/>Thou hast invaded death''s abode<br/>And robbed him of his sting.<br/>The house of dust enthralls no more,<br/>For Thou, the strong to save,<br/>Thyself doth guard that silent door,<br/>Great Keeper of the grave.<br/>',NULL,616,616);
INSERT INTO stanza VALUES('E126','3','To Thee, dear Lord, O Christ of God,<br/>We sing, we ever sing;<br/>For Thou hast crushed beneath Thy rod<br/>The world''s proud rebel king,<br/>And plunged in Thine imperial strength<br/>To gulfs of darkness down,<br/>And brought Thy trophy up at length,<br/>The foiled usurper''s crown.<br/>',NULL,617,617);
INSERT INTO stanza VALUES('E126','4','To Thee, dear Lord, O Christ of God,<br/>We sing, we ever sing;<br/>Thou hast redeemed us with Thy blood<br/>From every evil thing.<br/>God''s saving strength Thine arm upbore,<br/>The arm that set us free;<br/>Glory, O Christ, for evermore<br/>Be to Thy God and Thee.<br/>',NULL,618,618);
INSERT INTO stanza VALUES('E127','1','Hark! Ten thousand voices crying,<br/>"Lamb of God!" with one accord;<br/>Thousand thousand saints replying,<br/>Wake at once the echo''ng chord.<br/>',NULL,619,619);
INSERT INTO stanza VALUES('E127','2','"Praise the Lamb!" the chorus waking,<br/>All in heav''n together throng;<br/>Loud and far each tongue partaking<br/>Rolls around the endless song.<br/>',NULL,620,620);
INSERT INTO stanza VALUES('E127','3','Grateful incense this, ascending<br/>Ever to the Father''s throne;<br/>Every knee to Jesus bending,<br/>All the mind in heav''n is one.<br/>',NULL,621,621);
INSERT INTO stanza VALUES('E127','4','All the Father''s counsels claiming<br/>Equal honors to the Son,<br/>All the Son''s effulgence beaming,<br/>Makes the Father''s glory known.<br/>',NULL,622,622);
INSERT INTO stanza VALUES('E127','5','By the Spirit all pervading,<br/>Hosts unnumbered round the Lamb,<br/>Crowned with light and joy unfading,<br/>Hail Him as the great "I AM."<br/>',NULL,623,623);
INSERT INTO stanza VALUES('E127','6','Joyful now the new creation<br/>Rests in undisturbed repose,<br/>Blest in Jesus'' full salvation,<br/>Sorrow now nor thraldom knows.<br/>',NULL,624,624);
INSERT INTO stanza VALUES('E127','7','Hark! The heavenly notes again!<br/>Loudly swells the song of praise;<br/>Through creation''s vault, Amen!<br/>Amen! Responsive joy doth raise.<br/>',NULL,625,625);
INSERT INTO stanza VALUES('E128','1','Far above all is our Savior enthroned;<br/>Crown''d is the Lamb who by sinners is owned,<br/>Living forever to list to our call,<br/>God hath exalted Him far above all.<br/>',NULL,626,626);
INSERT INTO stanza VALUES('E128','chorus','Far above all! Far above all!<br/>Jesus the crucified far above all!<br/>High as His members upon Him we call,<br/>God hath exalted Him far above all!<br/>',NULL,627,627);
INSERT INTO stanza VALUES('E128','2','When the fierce tempest, uplifting its waves,<br/>Seeks to engulf us, we cry and He saves;<br/>Looking to Jesus, upheld by His hand,<br/>Tread we the billows as safe as on land.<br/>',NULL,628,628);
INSERT INTO stanza VALUES('E128','3','High are the cities that dare our assault,<br/>Strong are the barriers that call us to halt;<br/>March we on fearless, and down they must fall,<br/>Vanquish''d by faith in Him far above all.<br/>',NULL,629,629);
INSERT INTO stanza VALUES('E128','4','His is the kingdom from pole unto pole,<br/>Far above all while the ages shall roll,<br/>With Him the victors, who follow''d His call,<br/>Share in His royalty far above all.<br/>',NULL,630,630);
INSERT INTO stanza VALUES('E129','1','Behold the Lamb with glory crowned,<br/>To Him all pow''r is giv''n:<br/>No place too high for Him is found,<br/>No place too high in heav''n.<br/>',NULL,631,631);
INSERT INTO stanza VALUES('E129','2','He fills the throne-the throne above;<br/>Its rights to Him belong;<br/>The object of His Father''s love,<br/>Theme of the ransomed''s song.<br/>',NULL,632,632);
INSERT INTO stanza VALUES('E129','3','Though high yet He accepts the praise<br/>His people offer here;<br/>The faintest, feeblest note they raise<br/>Will reach the Savior''s ear.<br/>',NULL,633,633);
INSERT INTO stanza VALUES('E129','4','This song be ours, we join in one<br/>To celebrate the Name<br/>Of Him that sits upon the throne,<br/>And to exalt the Lamb.<br/>',NULL,634,634);
INSERT INTO stanza VALUES('E129','5','To Him whom men despise and slight,<br/>To Him be glory giv''n;<br/>The crown is His, and His by right<br/>The highest place in heav''n.<br/>',NULL,635,635);
INSERT INTO stanza VALUES('E130','1','See the Conqu''ror mount in triumph,<br/>See the King in royal state<br/>Riding on the clouds His chariot<br/>To His heav''nly palace gate;<br/>Hark! The choirs of angel voices<br/>Joyful hallelujahs sing,<br/>And the portals high are lifted<br/>To receive, to receive, to receive their<br/>heav''nly King.<br/>',NULL,636,636);
INSERT INTO stanza VALUES('E130','2','Who is this that comes in glory,<br/>With the trump of jubilee?<br/>Lord of battles, God of armies,<br/>He has gained the victory;<br/>He who on the cross did suffer,<br/>He who from the grave arose,<br/>He has vanquished sin and Satan,<br/>He by death, He by death, He by<br/>death has spoiled His foes.<br/>',NULL,637,637);
INSERT INTO stanza VALUES('E130','3','While He lifts His hands in blessing<br/>He is parted from His friends;<br/>While their eager eyes behold Him,<br/>He upon the clouds ascends;<br/>He who walked with God and pleased Him,<br/>Preaching truth and doom to come,<br/>He, our Enoch, is translated<br/>To His home, to His home, to His everlasting<br/>home.<br/>',NULL,638,638);
INSERT INTO stanza VALUES('E130','4','Now our heavenly Aaron enters,<br/>With His blood, within the veil;<br/>Joshua now is come to Canaan,<br/>And the kings before Him quail;<br/>Now He plants the tribes of Israel<br/>In their promised resting-place;<br/>Now our great Elijah offers<br/>Of His grace, of His grace,<br/>double portion of His grace.<br/>',NULL,639,639);
INSERT INTO stanza VALUES('E130','5','He has raised our human nature<br/>On the clouds to God''s right hand;<br/>There we sit in heav''nly places,<br/>There with Him in glory stand.<br/>Jesus reigns, adored by angels;<br/>Man with God is on the throne;<br/>Mighty Lord, in Thine ascension<br/>We by faith, we by faith, we by<br/>faith behold our own.<br/>',NULL,640,640);
INSERT INTO stanza VALUES('E131','1','O Jesus, Lord, ''tis joy to know<br/>Thy path is o''er of shame and woe,<br/>By Thee so meekly trod.<br/>All finished is Thy work of toil,<br/>Thou reapest now the fruit and spoil,<br/>Exalted by our God.<br/>',NULL,641,641);
INSERT INTO stanza VALUES('E131','2','Thy holy head, once bound with thorns,<br/>The crown of glory now adorns;<br/>Thy seat, the Father''s throne.<br/>O Lord, e''en now we sing Thy praise,<br/>Ours the eternal song to raise,<br/>Worthy the Lord alone!<br/>',NULL,642,642);
INSERT INTO stanza VALUES('E131','3','We triumph in Thy triumphs, Lord,<br/>Thy joys our deepest joys afford,<br/>The fruit of love divine.<br/>While sorrowing, suff''ring, toiling here,<br/>How does the thought our spirits cheer,<br/>The throne of glory''s Thine!<br/>',NULL,643,643);
INSERT INTO stanza VALUES('E132','1','Lo! In heaven Jesus sitting,<br/>Christ the Lord is there enthroned;<br/>As the man by God exalted,<br/>With God''s glory He is crowned.<br/>',NULL,644,644);
INSERT INTO stanza VALUES('E132','2','He hath put on human nature,<br/>Died according to God''s plan,<br/>Resurrected with a body,<br/>And ascended as a man.<br/>',NULL,645,645);
INSERT INTO stanza VALUES('E132','3','God in Him on earth was humbled,<br/>God with man was domiciled;<br/>Man in Him in heav''n exalted,<br/>Man with God is reconciled.<br/>',NULL,646,646);
INSERT INTO stanza VALUES('E132','4','He as God with man is mingled,<br/>God in man is testified;<br/>He as man with God is blended,<br/>Man in God is glorified.<br/>',NULL,647,647);
INSERT INTO stanza VALUES('E132','5','From the Glorified in heaven<br/>The inclusive Spirit came;<br/>All of Jesus'' work and Person<br/>Doth this Spirit here proclaim.<br/>',NULL,648,648);
INSERT INTO stanza VALUES('E132','6','With the Glorified in heaven<br/>Is the Church identified;<br/>By the Spirit of this Jesus<br/>Are His members edified.<br/>',NULL,649,649);
INSERT INTO stanza VALUES('E132','7','Lo! A man is now in heaven<br/>As the Lord of all enthroned;<br/>This is Jesus Christ our Savior,<br/>With God''s glory ever crowned!<br/>',NULL,650,650);
INSERT INTO stanza VALUES('E133','1','Lord Jesus , Thou art Lord of all,<br/>With glory ever crowned;<br/>In power and in majesty<br/>Thou art to all renowned.<br/>',NULL,651,651);
INSERT INTO stanza VALUES('E133','2','As God in man, on earth Thou wast,<br/>A slave-form Thou didst own;<br/>As man in God, in heav''n Thou art,<br/>As Lord of all art known.<br/>',NULL,652,652);
INSERT INTO stanza VALUES('E133','3','Thou art the Man in glory there,<br/>And there by God enthroned;<br/>All pow''r in heaven and on earth<br/>Now by Thyself is owned.<br/>',NULL,653,653);
INSERT INTO stanza VALUES('E133','4','Exalted highly to the heav''ns<br/>And giv''n the highest Name,<br/>All shall confess Thee as the Lord<br/>And all bow at Thy Name.<br/>',NULL,654,654);
INSERT INTO stanza VALUES('E133','5','God made Thee both the Lord and Christ,<br/>The Spirit hath declared;<br/>In glory and in heav''n we see<br/>God''s throne by Thee is shared.<br/>',NULL,655,655);
INSERT INTO stanza VALUES('E133','6','As Lord of glory we adore,<br/>To Thee our song we raise;<br/>We worship Thee as Lord of all,<br/>How worthy of our praise!<br/>',NULL,656,656);
INSERT INTO stanza VALUES('E134','1','Glory, everlasting glory<br/>Be to Christ, the throned Lamb.<br/>Glory, everlasting glory<br/>Be to His most precious Name;<br/>Name above all names in heaven,<br/>Name above all names on earth.<br/>Glory, everlasting glory<br/>Be to Him of peerless worth.<br/>',NULL,657,657);
INSERT INTO stanza VALUES('E134','2','Throned in heav''n, the Prince of Glory,<br/>Equal God, with God on high;<br/>Form of lowest servant taking,<br/>On the cross of shame to die:<br/>In obedience, strong, unswerving,<br/>His blest Father''s will to do;<br/>Death of shame, all undeserved,<br/>E''en to that His love could go.<br/>',NULL,658,658);
INSERT INTO stanza VALUES('E134','3','Heaven''s crown of brightest glory<br/>Be to Him, the humbled One.<br/>Heaven''s robe of brightest splendor<br/>Be to Him and Him alone.<br/>In the Name of Jesus bowing,<br/>Every tongue shall Him confess<br/>Lord of earth and Lord of heaven;<br/>Myriads shall this Monarch bless.<br/>',NULL,659,659);
INSERT INTO stanza VALUES('E134','4','Glory, everlasting glory<br/>Be to Him of peerless worth.<br/>In the highest heav''n be glory,<br/>Glory be to Him on earth.<br/>Unto God, our God, be glory,<br/>Glory to the great I AM.<br/>Glory, everlasting glory<br/>Be to Christ, the throned Lamb.<br/>',NULL,660,660);
INSERT INTO stanza VALUES('E135','1','O my Savior, glorified!<br/>Now the heavens, opened wide,<br/>Show to faith''s exultant eye<br/>One in beauteous majesty.<br/>',NULL,661,661);
INSERT INTO stanza VALUES('E135','2','Worthy of the sweetest praise<br/>That my ransomed heart can raise,<br/>Is that Man in whom alone<br/>God Himself is fully known.<br/>',NULL,662,662);
INSERT INTO stanza VALUES('E135','3','For those clustering glories prove<br/>That glad gospel, "God is Love"<br/>Whilst those wounds, in glory bright,<br/>Voice the solemn, "God is Light."<br/>',NULL,663,663);
INSERT INTO stanza VALUES('E135','4','Hark, my soul! Thy Savior sings;<br/>Catch the joy that music brings,<br/>And, with that sweet flood of song,<br/>Pour thy whispering praise along.<br/>',NULL,664,664);
INSERT INTO stanza VALUES('E135','5','O my Savior, glorified,<br/>Turn my eye from all beside,<br/>Let me but Thy beauty see,<br/>Other light is dark to me.<br/>',NULL,665,665);
INSERT INTO stanza VALUES('E136','1','Gazing on the Lord in glory,<br/>While our hearts in worship bow,<br/>There we read the wondrous story<br/>Of the cross-its shame and woe.<br/>',NULL,666,666);
INSERT INTO stanza VALUES('E136','2','Every mark of dark dishonor<br/>Heaped upon the thorn-crowned brow,<br/>All the depths of Thy heart''s sorrow<br/>Told in answ''ring glory now.<br/>',NULL,667,667);
INSERT INTO stanza VALUES('E136','3','On that cross, alone, forsaken,<br/>Where no pity''ng eye was found;<br/>Now, to God''s right hand exalted,<br/>With Thy praise the heavens resound.<br/>',NULL,668,668);
INSERT INTO stanza VALUES('E136','4','Did Thy God e''en then forsake Thee,<br/>Hide His face from Thy deep need?<br/>In Thy face once marred and smitten,<br/>All His glory now we read.<br/>',NULL,669,669);
INSERT INTO stanza VALUES('E136','5','Gazing on it we adore Thee,<br/>Blessed, precious, holy Lord;<br/>Thou, the Lamb, alone art worthy-<br/>This be earth''s and heaven''s accord.<br/>',NULL,670,670);
INSERT INTO stanza VALUES('E136','6','Rise our hearts, and bless the Father,<br/>Ceaseless song e''en here begun,<br/>Endless praise and adoration<br/>To the Father and the Son.<br/>',NULL,671,671);
INSERT INTO stanza VALUES('E137','1','All hail the pow''r of Jesus'' name!<br/>Before Him prostrate fall;<br/>With one accord His praise proclaim,<br/>And crown Him Lord of all!<br/>',NULL,672,672);
INSERT INTO stanza VALUES('E137','2','Ye saints redeemed from, Adam’s race,<br/>Ye ransomed from the fall,<br/>Hail Him who saves you by His grace,<br/>And crown Him Lord of all.<br/>',NULL,673,673);
INSERT INTO stanza VALUES('E137','3','Tell forth the only Name that''s giv''n<br/>On which we now may call,<br/>The Name adored by hosts in heav''n,<br/>And crown Him Lord of all.<br/>',NULL,674,674);
INSERT INTO stanza VALUES('E137','4','In glory all the ransomed throng<br/>Soon at His feet shall fall;<br/>Join in the blest eternal song,<br/>And crown Him Lord of all.<br/>(Repeat the last two lines of each stanza)<br/>',NULL,675,675);
INSERT INTO stanza VALUES('E138','1','All hail the pow''r of Jesus'' name!<br/>Let angels prostrate fall;<br/>Bring forth the royal diadem,<br/>',NULL,676,676);
INSERT INTO stanza VALUES('E138','chorus','And crown Him, crown Him,<br/>crown Him,<br/>Crown Him Lord of all!<br/>',NULL,677,677);
INSERT INTO stanza VALUES('E138','2','Crown Him, ye martyrs of your God<br/>Who from His altar call;<br/>Extol the Stem of Jesse''s rod,<br/>',NULL,678,678);
INSERT INTO stanza VALUES('E138','3','Hail Him, ye heirs of David''s line,<br/>Whom David Lord did call;<br/>The God incarnate, Man Divine;<br/>',NULL,679,679);
INSERT INTO stanza VALUES('E138','4','Ye chosen seed of Israel''s race,<br/>Ye ransomed from the fall,<br/>Hail Him who saves you by His grace,<br/>',NULL,680,680);
INSERT INTO stanza VALUES('E138','5','Sinners, whose love can ne''er forget<br/>The wormwood and the gall,<br/>Go, spread your trophies at His feet,<br/>',NULL,681,681);
INSERT INTO stanza VALUES('E138','6','Let every kindred, every tribe,<br/>On this terrestrial ball,<br/>To Him all majesty ascribe,<br/>',NULL,682,682);
INSERT INTO stanza VALUES('E138','7','O that with yonder sacred throng<br/>We at His feet may fall!<br/>We''ll join the everlasting song,<br/>',NULL,683,683);
INSERT INTO stanza VALUES('E139','1','All hail the pow''r of Jesus'' name!<br/>Let angels prostrate fall,<br/>Let angels prostrate fall:<br/>Bring forth the royal diadem,<br/>',NULL,684,684);
INSERT INTO stanza VALUES('E139','chorus','And crown Him, crown Him,<br/>crown Him, crown Him;<br/>And crown Him Lord of all!<br/>',NULL,685,685);
INSERT INTO stanza VALUES('E139','2','Ye chosen seed of Israel''s race,<br/>Ye ransomed from the fall,<br/>Ye ransomed from the fall,<br/>Hail Him who saves you by His grace,<br/>',NULL,686,686);
INSERT INTO stanza VALUES('E139','3','Sinners, whose love can ne''er forget<br/>The wormwood and the gall,<br/>The wormwood and the gall,<br/>Go, spread your trophies at His feet,<br/>',NULL,687,687);
INSERT INTO stanza VALUES('E139','4','Let every kindred, every tribe,<br/>On this terrestrial ball,<br/>On this terrestrial ball,<br/>To Him all majesty ascribe,<br/>',NULL,688,688);
INSERT INTO stanza VALUES('E139','5','O that with yonder sacred throng<br/>We at His feet may fall,<br/>We at His feet may fall!<br/>We''ll join the everlasting song,<br/>',NULL,689,689);
INSERT INTO stanza VALUES('E140','1','Look, ye saints, the sight is glorious;<br/>See the Man of sorrows now;<br/>From the fight returned victorious,<br/>Every knee to Him shall bow;<br/>Crown Him! Crown Him!<br/>Crown Him! Crown Him!<br/>Crowns become the Victor''s brow.<br/>',NULL,690,690);
INSERT INTO stanza VALUES('E140','2','Crown the Savior! Angels, crown Him!<br/>Rich the trophies Jesus brings;<br/>In the seat of pow''r enthrone Him,<br/>While the vault of heaven rings:<br/>Crown Him! Crown Him!<br/>Crown Him! Crown Him!<br/>Crown the Savior King of kings.<br/>',NULL,691,691);
INSERT INTO stanza VALUES('E140','3','Sinners in derision crowned Him,<br/>Mocking thus the Savior''s claim;<br/>Saints and angels crowd around Him,<br/>Own His title, praise His name:<br/>Crown Him! Crown Him!<br/>Crown Him! Crown Him!<br/>Spread abroad the Victor''s fame.<br/>',NULL,692,692);
INSERT INTO stanza VALUES('E140','4','Hark! Those bursts of acclamation!<br/>Hark! Those loud triumphant chords!<br/>Jesus takes the highest station;<br/>O what joy the sight affords!<br/>Crown Him! Crown Him!<br/>Crown Him! Crown Him!<br/>King of kings, and Lord of lords!<br/>',NULL,693,693);
INSERT INTO stanza VALUES('E141','1','Jesus, Thy head, once crown''d with thorns,<br/>Is crown''d with glory now;<br/>Heaven''s royal diadem adorns<br/>The mighty Victor''s brow.<br/>',NULL,694,694);
INSERT INTO stanza VALUES('E141','2','Thou glorious light of courts above,<br/>Joy of the saints below,<br/>To us still manifest Thy love,<br/>That we its depths may know.<br/>',NULL,695,695);
INSERT INTO stanza VALUES('E141','3','To us Thy cross with all its shame,<br/>With all its grace be giv''n;<br/>Though earth disowns Thy lowly name,<br/>God honors it in heav''n.<br/>',NULL,696,696);
INSERT INTO stanza VALUES('E141','4','Who suffer with Thee, Lord, today,<br/>Shall also with Thee reign:<br/>Then let it be our joy to pay<br/>The price, this goal attain.<br/>',NULL,697,697);
INSERT INTO stanza VALUES('E141','5','To us Thy cross is life and health;<br/>''Twas shame and death to Thee;<br/>Our present glory, joy and wealth,<br/>Our everlasting stay.<br/>',NULL,698,698);
INSERT INTO stanza VALUES('E142','1','Crown Him with many crowns,<br/>The Lamb upon His throne;<br/>Hark! How the heav''nly anthem drowns<br/>All music but its own!<br/>Awake, my soul, and sing<br/>Of Him who died for thee,<br/>And hail Him as thy matchless King<br/>Through all eternity.<br/>',NULL,699,699);
INSERT INTO stanza VALUES('E142','2','Crown Him the Virgin''s Son,<br/>The God Incarnate born,<br/>Whose arm those crimson trophies won<br/>Which now His brow adorn:<br/>Fruit of the mystic Tree,<br/>As of that Tree the Stem;<br/>The Root whence flows Thy mercy free,<br/>The Babe of Bethlehem.<br/>',NULL,700,700);
INSERT INTO stanza VALUES('E142','3','Crown Him the Lord of Love:<br/>Behold His hands and side;<br/>Rich wounds yet visible above<br/>In beauty glorified:<br/>No angel in the sky<br/>Can fully bear that sight,<br/>But downward bends his burning eye<br/>At mysteries so bright.<br/>',NULL,701,701);
INSERT INTO stanza VALUES('E142','4','Crown Him the Lord of peace,<br/>Whose power a scepter sways<br/>From pole to pole, that wars may cease,<br/>And all be prayer and praise.<br/>His reign shall know no end,<br/>And round His pierced feet<br/>Fair flowers of glory now extend<br/>Their fragrance ever sweet.<br/>',NULL,702,702);
INSERT INTO stanza VALUES('E142','5','Crown Him the Lord of years,<br/>The Potentate of time,<br/>Creator of the rolling spheres,<br/>Ineffably sublime.<br/>All hail, Redeemer, hail!<br/>For Thou hast died for me;<br/>Thy praise shall never, never fail<br/>Throughout eternity.<br/>',NULL,703,703);
INSERT INTO stanza VALUES('E143','1','On His Father''s throne is seated<br/>Christ the Lord, the living One!<br/>All His toil on earth completed,<br/>All His work for sinners done.<br/>In the glory, in the glory,<br/>See Him-God''s eternal Son!<br/>',NULL,704,704);
INSERT INTO stanza VALUES('E143','2','Every knee shall bow before Him,<br/>Every tongue confess His name,<br/>Ransomed myriads shall adore Him,<br/>Who endured the sinner''s shame!<br/>From the glory, from the glory,<br/>God doth now His worth proclaim.<br/>',NULL,705,705);
INSERT INTO stanza VALUES('E143','3','Man, the cross to Him awarded;<br/>Man, the Savior crucified;<br/>This world''s judgment stands recorded,<br/>God''s own justice satisfied!<br/>By the glory, by the glory,<br/>Christ was claimed on earth who died.<br/>',NULL,706,706);
INSERT INTO stanza VALUES('E143','4','Son of Man, His incarnation<br/>Opened first the tale of grace;<br/>Son of Man, in new creation<br/>Leader of a chosen race!<br/>Well may glory, well may glory,<br/>Give to Him the honored place!<br/>',NULL,707,707);
INSERT INTO stanza VALUES('E144','1','Lord of glory, we adore Thee!<br/>Christ of God, ascended high!<br/>Heart and soul we bow before Thee,<br/>Glorious now beyond the sky:<br/>Thee we worship, Thee we praise-<br/>Excellent in all Thy ways.<br/>',NULL,708,708);
INSERT INTO stanza VALUES('E144','2','Anointed King, with glory crowned,<br/>Rightful Heir and Lord of all!<br/>Once rejected, scorned, disowned,<br/>E''en by those Thou cam''st to call:<br/>Thee we honor, Thee adore-<br/>Glorious now and evermore.<br/>',NULL,709,709);
INSERT INTO stanza VALUES('E144','3','Lord of life! To death once subject;<br/>Blesser, yet a curse once made;<br/>Of Thy Father''s heart the object,<br/>Yet in depths of anguish laid;<br/>Thee we gaze on, Thee recall-<br/>Bearing here our sorrows all.<br/>',NULL,710,710);
INSERT INTO stanza VALUES('E144','4','Royal robes shall soon invest Thee,<br/>Royal splendors crown Thy brow;<br/>Christ of God, our souls confess Thee<br/>King and Sov''reign even now!<br/>Thee we rev''rence, Thee obey-<br/>Own Thee Lord and Christ alway.<br/>',NULL,711,711);
INSERT INTO stanza VALUES('E145','1','Jesus shall reign where''er the sun<br/>Doth his successive journeys run;<br/>His Kingdom stretch from shore to shore,<br/>Till moons shall wax and wane no more.<br/>',NULL,712,712);
INSERT INTO stanza VALUES('E145','2','To Him shall endless prayer be made,<br/>And princes throng to crown His head,<br/>His name like sweet perfume shall rise<br/>With every morning sacrifice.<br/>',NULL,713,713);
INSERT INTO stanza VALUES('E145','3','People and realms of every tongue<br/>Dwell on His love with sweetest song;<br/>And infant voices shall proclaim<br/>Their early blessings on His name.<br/>',NULL,714,714);
INSERT INTO stanza VALUES('E145','4','Blessings abound where''er He reigns:<br/>The prisoner leaps to lose his chains,<br/>The weary find eternal rest,<br/>And all the sons of want are blest.<br/>',NULL,715,715);
INSERT INTO stanza VALUES('E145','5','Where He displays His healing power<br/>Death and the curse are known no more;<br/>In Him the tribes of Adam boast<br/>More blessings than their father lost.<br/>',NULL,716,716);
INSERT INTO stanza VALUES('E145','6','Let every creature rise and bring<br/>Peculiar honors to our King;<br/>Angels descend with songs again,<br/>And earth repeat the loud Amen.<br/>',NULL,717,717);
INSERT INTO stanza VALUES('E146','1','Rejoice, the Lord is King,<br/>Your Lord and King adore;<br/>Mortals, give thanks and sing,<br/>And triumph evermore:<br/>',NULL,718,718);
INSERT INTO stanza VALUES('E146','chorus','Lift up your heart, lift up your voice;<br/>Rejoice, again I say, rejoice.<br/>',NULL,719,719);
INSERT INTO stanza VALUES('E146','2','His kingdom cannot fail;<br/>He rules o''er earth and heav''n;<br/>The keys of death and hell<br/>Are to our Jesus giv''n:<br/>',NULL,720,720);
INSERT INTO stanza VALUES('E146','3','Jesus, the Savior reigns,<br/>The God of truth and love:<br/>When He had purged our stains,<br/>He took His seat above:<br/>',NULL,721,721);
INSERT INTO stanza VALUES('E146','4','He sits, at God''s right hand<br/>Till all His foes submit,<br/>And bow to His command,<br/>And fall beneath His feet:<br/>',NULL,722,722);
INSERT INTO stanza VALUES('E147','1','Lord, Thou art God''s anointed,<br/>Thou art of kings the King!<br/>Here in full adoration<br/>Our song to Thee we bring!<br/>Thy kingdom is forever,<br/>Established is Thy throne!<br/>Thy reign with love and justice<br/>In glory stands alone!<br/>',NULL,723,723);
INSERT INTO stanza VALUES('E147','2','Upon the hill of Zion<br/>Hath God established Thee<br/>And all the nations given<br/>Thy heritage to be.<br/>To Thee hath God committed<br/>His full authority<br/>To rule with might the nations<br/>Unto eternity.<br/>',NULL,724,724);
INSERT INTO stanza VALUES('E147','3','Before the time of fulness,<br/>While darkness still prevails,<br/>Ten thousands daily render<br/>To Thee their loyal hails!<br/>From shore to shore Thy people<br/>To Thee their praises sing;<br/>They worship, love, and serve Thee<br/>As their dear Savior-King!<br/>',NULL,725,725);
INSERT INTO stanza VALUES('E147','4','When in the time appointed<br/>With glory Thou wilt come,<br/>The earth with all its nations<br/>Thy kingdom will become.<br/>In majesty and splendor<br/>Wilt Thou be served as King,<br/>All kindreds and all peoples<br/>To Thee their praise shall ring!<br/>',NULL,726,726);
INSERT INTO stanza VALUES('E148','1','Lord, the King of kings art Thou,<br/>In Thy presence here we bow;<br/>God''s anointed we adore,<br/>Worship Thee in holy awe.<br/>Unto Thee, of kings the King,<br/>All the saints Thy praises sing!<br/>',NULL,727,727);
INSERT INTO stanza VALUES('E148','2','Thine authority and pow''r<br/>Shall prevail from shore to shore!<br/>All shall serve and worship<br/>Thee In Thy kingly majesty!<br/>Unto Thee, of kings the King,<br/>All Thy praise shall ever ring!<br/>',NULL,728,728);
INSERT INTO stanza VALUES('E148','3','Lord, Thy kingdom stands alone,<br/>And forever is Thy throne!<br/>To Thy glory and Thy pow''r<br/>We will sing forevermore!<br/>Now to Thee, of kings the King,<br/>All the saints Thy praises sing!<br/>',NULL,729,729);
INSERT INTO stanza VALUES('E148','4','Gracious Lord, our sovereign King,<br/>Thy dear name we love to sing!<br/>O how sweet Thy reign and rule,<br/>May Thy kingdom come in full!<br/>Yet to Thee, of kings the King,<br/>Here Thy praise we gladly sing!<br/>',NULL,730,730);
INSERT INTO stanza VALUES('E149','1','Hark! Ten thousand heav''nly voices<br/>Sound the note of praise above;<br/>Jesus reigns and heav''n rejoices,<br/>Jesus reigns, the God of love.<br/>See, He sits on yonder throne;<br/>Jesus rules the world alone.<br/>',NULL,731,731);
INSERT INTO stanza VALUES('E149','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Amen.<br/>',NULL,732,732);
INSERT INTO stanza VALUES('E149','2','Sing how Jesus came from heaven,<br/>How He bore the cross below,<br/>How all power to Him is given,<br/>How He reigns in glory now.<br/>''Tis a great and endless theme-<br/>Oh, ''tis sweet to Sing of Him.<br/>',NULL,733,733);
INSERT INTO stanza VALUES('E149','3','Jesus, hail! Thy glory brightens<br/>All above and gives it worth;<br/>Lord of life, Thy smile enlightens,<br/>Cheers, and charms Thy saints on earth.<br/>When we think of love like Thine,<br/>Lord, we own it love divine.<br/>',NULL,734,734);
INSERT INTO stanza VALUES('E149','4','King of glory, reign forever!<br/>Thine an everlasting crown.<br/>Nothing from Thy love shall sever<br/>Those whom Thou hast made Thine own:<br/>Happy objects of Thy grace,<br/>Destined to behold Thy face.<br/>',NULL,735,735);
INSERT INTO stanza VALUES('E149','5','Savior, hasten Thine appearing:<br/>Bring, oh, bring the glorious day,<br/>When, the awful summons hearing,<br/>Heav''n and earth shall pass away.<br/>Then with raptured hearts we''ll sing,<br/>"Glory, glory to our King!"<br/>',NULL,736,736);
INSERT INTO stanza VALUES('E150','1','Praise, praise ye the name of our Savior and God;<br/>Declare, oh, declare ye His glories abroad;<br/>Proclaim ye His mercy, from nation to nation,<br/>Till the uttermost islands have heard His salvation.<br/>',NULL,737,737);
INSERT INTO stanza VALUES('E150','chorus','For His love floweth on, free and full as a river;<br/>And His mercy endureth forever and ever.<br/>',NULL,738,738);
INSERT INTO stanza VALUES('E150','2','Praise, praise ye the Lamb, who for sinners was slain;<br/>Who went down to the grave, and ascended again;<br/>And who soon shall return, when these dark days are o''er,<br/>To set up His kingdom, in glory and power.<br/>',NULL,739,739);
INSERT INTO stanza VALUES('E150','3','Then the heav''ns and the earth. and the sea shall rejoice;<br/>The field and the forest shall lift their glad voice;<br/>The sands of the desert shall flourish in green,<br/>And Lebanon''s glory be shed o''er the scene.<br/>',NULL,740,740);
INSERT INTO stanza VALUES('E150','4','Her bridal attire, and her festal array,<br/>All nature shall see on that glorious day;<br/>For her King cometh down with His people to reign,<br/>And His presence shall bless her with glory in men.<br/>',NULL,741,741);
INSERT INTO stanza VALUES('E151','1','Sing we the King who is coming to reign,<br/>Glory to Jesus, the Lamb that was slain;<br/>Righteousness, peace then His empire shall bring,<br/>Joy to the nations when Jesus is King.<br/>',NULL,742,742);
INSERT INTO stanza VALUES('E151','chorus','Come let us sing: Praise to our King,<br/>Jesus our King, Jesus our King:<br/>This is our song, who to Jesus belong:<br/>Glory to Jesus, to Jesus our King.<br/>',NULL,743,743);
INSERT INTO stanza VALUES('E151','2','All men shall dwell in His marvelous light,<br/>Races long severed His love shall unite,<br/>Justice and truth from His scepter shall spring,<br/>Wrong shall be ended when Jesus is King.<br/>',NULL,744,744);
INSERT INTO stanza VALUES('E151','3','All shall be well in His kingdom of peace,<br/>Freedom shall flourish and wisdom increase,<br/>Foe shall be friend when His triumph we sing,<br/>Sword shall be sickle when Jesus is King.<br/>',NULL,745,745);
INSERT INTO stanza VALUES('E151','4','Knowledge and fear of the Lord then shall be<br/>As the deep waters that cover the sea;<br/>All things shall be in the splendor of spring<br/>And all harmonious when Jesus is King.<br/>',NULL,746,746);
INSERT INTO stanza VALUES('E151','5','Kingdom of Christ, for thy coming we pray,<br/>Hasten, O Father, the dawn of the day<br/>When this new song Thy creation shall sing,<br/>Satan is vanquished and Jesus is King.<br/>',NULL,747,747);
INSERT INTO stanza VALUES('E152','1','O how deep and how far-reaching<br/>Is Thy love, dear Lord, to me!<br/>Far beyond my pow''r to fathom,<br/>Deeper than the deepest sea!<br/>It has caused Thee death to suffer<br/>And to me Thyself impart,<br/>That in Thee I might be grafted<br/>And become of Thee a part.<br/>',NULL,748,748);
INSERT INTO stanza VALUES('E152','2','Who can tell of all the wonders<br/>Which Thy love for me has wrought,<br/>Yet the greatest of these wonders<br/>Is that Thou to me art brought.<br/>Oh! To me Thy love has given<br/>All Thou art as my supply;<br/>As true life I now may share Thee<br/>And Thy riches e''er enjoy.<br/>',NULL,749,749);
INSERT INTO stanza VALUES('E152','3','Lord, Thy love is the expression<br/>Of Thy loving self divine,<br/>Making life so full of meaning,<br/>Harmonized with God''s design.<br/>Grace of life, how all-sufficient,<br/>Is my portion day by day;<br/>I''m the object of Thy favor<br/>And Thy sweetness taste alway.<br/>',NULL,750,750);
INSERT INTO stanza VALUES('E152','4','What from Thee can separate me?<br/>Thou wilt love me to the end!<br/>Oh! Thy love is so prevailing,<br/>E''en Thyself with me to blend!<br/>We two one will be for ever;<br/>I am Thine and Thou art mine!<br/>This will be my testimony:<br/>In Thy love we''ll ever twine!<br/>',NULL,751,751);
INSERT INTO stanza VALUES('E153','1','O blessed Savior, is Thy love<br/>So great! So full! So free!<br/>Fain would we have our thoughts, our hearts,<br/>Our lives, engaged with Thee.<br/>',NULL,752,752);
INSERT INTO stanza VALUES('E153','2','We love Thee for the glorious worth<br/>Which in Thyself we see;<br/>We love Thee for that shameful cross,<br/>Endured so patiently.<br/>',NULL,753,753);
INSERT INTO stanza VALUES('E153','3','No man of greater love can boast<br/>Than for his friend to die;<br/>Thou for Thine enemies wast slain!<br/>What love with Thine can vie?<br/>',NULL,754,754);
INSERT INTO stanza VALUES('E153','4','Though in the very form of God,<br/>With heav''nly glory crowned,<br/>Thou didst a servant''s form assume,<br/>Beset with sorrow round.<br/>',NULL,755,755);
INSERT INTO stanza VALUES('E153','5','Thou wouldst like wretched man be made<br/>In everything but sin,<br/>That we as like Thee might become<br/>As we unlike had been:<br/>',NULL,756,756);
INSERT INTO stanza VALUES('E153','6','Like Thee in strength, in meekness, love,<br/>In life in ev''ry phase;<br/>From glory into glory changed,<br/>Till we behold Thy face.<br/>',NULL,757,757);
INSERT INTO stanza VALUES('E153','7','O Lord, we treasure in our hearts<br/>The mem''ry of Thy love;<br/>And ever shall Thy name to us<br/>A grateful odor prove.<br/>',NULL,758,758);
INSERT INTO stanza VALUES('E154','1','It passeth knowledge, that dear love of Thine,<br/>My Savior, Jesus; yet this soul of mine<br/>Would of Thy love in all its breadth and length,<br/>Its height and depth, its everlasting strength,<br/>Know more and more.<br/>',NULL,759,759);
INSERT INTO stanza VALUES('E154','2','It passeth telling, that dear love of Thine,<br/>My Savior, Jesus; yet these lips of mine<br/>Would fain proclaim to sinners, far and near,<br/>A love which can remove all guilty fear,<br/>And love beget.<br/>',NULL,760,760);
INSERT INTO stanza VALUES('E154','3','It passeth praises, that dear love of Thine,<br/>My Savior Jesus; yet this heart of mine<br/>Would sing that love, so full, so rich, so free,<br/>Which brings a rebel sinner, such as me,<br/>Nigh unto God.<br/>',NULL,761,761);
INSERT INTO stanza VALUES('E154','4','But though I cannot sing, or tell, or know<br/>The fullness of Thy love, while here below,<br/>My empty vessel I may freely bring;<br/>O Thou, who art of love the living spring,<br/>My vessel fill.<br/>',NULL,762,762);
INSERT INTO stanza VALUES('E154','5','I am an empty vessel-not one thought<br/>Or look of love to Thee I''ve ever brought;<br/>Yet I may come, and come again to Thee,<br/>With this the empty sinner''s only plea,<br/>Thou lovest me.<br/>',NULL,763,763);
INSERT INTO stanza VALUES('E154','6','Oh, fill me, Jesus, Savior, with Thy love!<br/>Lead, lead me to the living fount above;<br/>Thither may I, in simple faith draw nigh,<br/>And never to another fountain fly,<br/>But unto Thee.<br/>',NULL,764,764);
INSERT INTO stanza VALUES('E154','7','Lord Jesus, when Thee face to face I see,<br/>When on Thy lofty throne I sit with Thee,<br/>Then of Thy love, in all its breadth and length,<br/>Its height and depth, its everlasting strength,<br/>My soul shall sing.<br/>',NULL,765,765);
INSERT INTO stanza VALUES('E155','1','Christ delivered me when bound,<br/>And when bleeding, healed my wound;<br/>Sought me wand''ring, set me right,<br/>Turned my darkness into light.<br/>',NULL,766,766);
INSERT INTO stanza VALUES('E155','2','Can a woman''s tender care<br/>Cease towards the child she bare?<br/>Yes, she may forgetful be;<br/>Yet will He remember me.<br/>',NULL,767,767);
INSERT INTO stanza VALUES('E155','3','His is an unchanging love,<br/>Higher than the heights above;<br/>Deeper than the depths beneath,<br/>Free and faithful, strong as death.<br/>',NULL,768,768);
INSERT INTO stanza VALUES('E155','4','I shall see His glory soon,<br/>When the work of grace is done;<br/>Partner of His throne shall be;<br/>Such is His great love for me!<br/>',NULL,769,769);
INSERT INTO stanza VALUES('E155','5','Lord, it is my chief complaint<br/>That my love is weak and faint;<br/>Yet I love Thee, and adore:<br/>Oh, for grace to love Thee more.<br/>',NULL,770,770);
INSERT INTO stanza VALUES('E156','1','I have a Friend, whose faithful love<br/>Is more than all the world to me:<br/>''Tis higher than the heights above,<br/>And deeper than the soundless sea;<br/>So old, so new,<br/>So strong, so true;<br/>Before the earth received its frame,<br/>He loved me-Blessed be His name!<br/>',NULL,771,771);
INSERT INTO stanza VALUES('E156','2','He held the highest place above,<br/>Adored by all the sons of flame,<br/>Yet such His self-denying love,<br/>He laid aside His crown and came<br/>To seek the lost,<br/>And at the cost<br/>Of heavenly rank and earthly fame<br/>He sought me-Blessed be His name!<br/>',NULL,772,772);
INSERT INTO stanza VALUES('E156','3','It was a lonely path He trod,<br/>From every human soul apart;<br/>Known only to Himself and God<br/>Was all the grief that filled His heart,<br/>Yet from the track<br/>He turned not back,<br/>Till where I lay in want and shame,<br/>He found me-Blessed be His name!<br/>',NULL,773,773);
INSERT INTO stanza VALUES('E156','4','Then dawned at last that day of dread,<br/>When desolate, yet undismayed,<br/>With wearied frame and thorn-crowned head,<br/>He, God-forsaken, man-betrayed,<br/>Was then made sin<br/>On Calvary,<br/>And, dying there in grief and shame,<br/>He saved me-Blessed be His name!<br/>',NULL,774,774);
INSERT INTO stanza VALUES('E156','5','Long as I live my song shall tell<br/>The wonders of His dying love;<br/>And when at last I go to dwell<br/>With Him His sovereign grace to prove,<br/>My joy shall be<br/>His face to see,<br/>And bowing there with loud acclaim<br/>I''ll praise Him-Blessed be His name!<br/>',NULL,775,775);
INSERT INTO stanza VALUES('E157','1','Lord Jesus, are we one with Thee?<br/>O height, O depth of love!<br/>Thou one with us on Calvary,<br/>We one with Thee above.<br/>',NULL,776,776);
INSERT INTO stanza VALUES('E157','2','Such was Thy grace that for our sake<br/>Thou didst from heaven come down,<br/>With us of flesh and blood partake,<br/>In all our misery one.<br/>',NULL,777,777);
INSERT INTO stanza VALUES('E157','3','Our sins, our guilt, in love Divine<br/>Confessed and borne by Thee;<br/>The gall, the curse, the wrath were Thine,<br/>To set Thy members free.<br/>',NULL,778,778);
INSERT INTO stanza VALUES('E157','4','Ascended now, in glory bright,<br/>Head of the Church Thou art;<br/>Nor life nor death, nor depth nor height,<br/>Thy saints and Thee can part.<br/>',NULL,779,779);
INSERT INTO stanza VALUES('E157','5','Oh teach us, Lord, to know and own<br/>This wondrous mystery,<br/>That Thou in heaven with us art one,<br/>And we are one with Thee.<br/>',NULL,780,780);
INSERT INTO stanza VALUES('E157','6','Soon, soon shall come that glorious day<br/>When, seated on Thy throne,<br/>Thou shalt to wondering worlds display<br/>That Thou with us art one.<br/>',NULL,781,781);
INSERT INTO stanza VALUES('E158','1','Lord, Thy love has sought and found us<br/>Wand''ring in this desert wide;<br/>Thou hast thrown Thine arms around us,<br/>For us suffered, bled, and died.<br/>Sing, my soul! He loved thee,<br/>Jesus gave Himself for me.<br/>',NULL,782,782);
INSERT INTO stanza VALUES('E158','2','Hark! What sounds of bitter weeping<br/>From yon lonesome garden sweep;<br/>''Tis the Lord His vigil keeping,<br/>While His followers sink in sleep.<br/>Ah, my soul, He loved thee,<br/>Yes, He gave Himself for me.<br/>',NULL,783,783);
INSERT INTO stanza VALUES('E158','3','He is speaking to His Father,<br/>Tasting deep that bitter cup,<br/>Yet He takes it, willing rather<br/>For our sakes to drink it up.<br/>Oh, what love! He loved me!<br/>Gave Himself, my soul, for thee.<br/>',NULL,784,784);
INSERT INTO stanza VALUES('E158','4','Then that closing scene of anguish:<br/>All God''s waves and billows roll<br/>Over Him, there left to languish<br/>On the cross, to save my soul.<br/>Matchless love! How vast, how free,<br/>Jesus gave Himself for me.<br/>',NULL,785,785);
INSERT INTO stanza VALUES('E158','5','Hark again! His cries are waking<br/>Echoes on dark Calvary''s hill;<br/>God, my God, art Thou forsaking<br/>Him who always did Thy will?<br/>Ah, my soul! It was for thee,<br/>Yes! He gave Himself for me.<br/>',NULL,786,786);
INSERT INTO stanza VALUES('E158','6','Lord, we joy, Thy toils are ended,<br/>Glad Thy suff''ring time is o''er;<br/>To Thy Father''s throne ascended,<br/>There Thou liv''st, to die no more.<br/>Yes, my soul, He lives for thee,<br/>He who gave Himself for me.<br/>',NULL,787,787);
INSERT INTO stanza VALUES('E158','7','Lord, we worship and adore Thee<br/>For Thy rich, Thy matchless grace;<br/>Perfect soon in joy before Thee,<br/>We shall see Thee face to face.<br/>Yet e''en now our song shall be,<br/>Jesus gave Himself for me.<br/>',NULL,788,788);
INSERT INTO stanza VALUES('E159','1','Give me a sight, O Savior,<br/>Of Thy wondrous love to me,<br/>Of the love that brought Thee down to earth,<br/>To die on Calvary.<br/>',NULL,789,789);
INSERT INTO stanza VALUES('E159','chorus','Oh, make me understand it,<br/>Help me to take it in,<br/>What it meant to Thee, the Holy One,<br/>To bear away my sin.<br/>',NULL,790,790);
INSERT INTO stanza VALUES('E159','2','Was it the nails, O Savior,<br/>That bound Thee to the tree?<br/>Nay, ''twas Thine everlasting love,<br/>Thy love for me, for me.<br/>',NULL,791,791);
INSERT INTO stanza VALUES('E159','3','Oh, wonder of all wonders,<br/>That through Thy death for me,<br/>My open sins, my secret sins,<br/>Can all forgiven be.<br/>',NULL,792,792);
INSERT INTO stanza VALUES('E159','4','Then melt my heart, O Savior,<br/>Bend me, yea, break me down,<br/>Until I own Thee Conqueror,<br/>And Lord and Sov''reign crown<br/>',NULL,793,793);
INSERT INTO stanza VALUES('E160','1','King of my life, I crown Thee now,<br/>Thine shall the glory be;<br/>Lest I forget Thy thorn-crowned brow,<br/>Lead me to Calvary.<br/>',NULL,794,794);
INSERT INTO stanza VALUES('E160','chorus','Lest I forget Gethsemane;<br/>Lest I forget Thine agony;<br/>Lest I forget Thy love for me,<br/>Lead me to Calvary.<br/>',NULL,795,795);
INSERT INTO stanza VALUES('E160','2','Show me the tomb where Thou wast laid,<br/>Tenderly mourned and wept;<br/>Angels in robes of light arrayed<br/>Guarded Thee while Thou slept.<br/>',NULL,796,796);
INSERT INTO stanza VALUES('E160','3','Let me like Mary, through the gloom,<br/>Come with a gift to Thee;<br/>Show to me now the empty tomb,<br/>Lead me to Calvary.<br/>',NULL,797,797);
INSERT INTO stanza VALUES('E160','4','May I be willing, Lord, to bear<br/>Daily my cross for Thee;<br/>Even Thy cup of grief to share,<br/>Thou hast borne all for me.<br/>',NULL,798,798);
INSERT INTO stanza VALUES('E160','5','Fill me, O Lord, with Thy desire<br/>For all that know not Thee;<br/>Then touch my lips with holy fire,<br/>To speak of Calvary.<br/>',NULL,799,799);
INSERT INTO stanza VALUES('E161','1','Praise the Savior, ye who know Him!<br/>Who can tell how much we owe Him?<br/>Gladly let us render to Him<br/>All we are and have.<br/>',NULL,800,800);
INSERT INTO stanza VALUES('E161','2','Jesus is the name that charms us;<br/>He for conflicts fits and arms us;<br/>Nothing moves and nothing harms us<br/>When we trust in Him.<br/>',NULL,801,801);
INSERT INTO stanza VALUES('E161','3','Trust in Him, ye saints, forever;<br/>He is faithful, changing never;<br/>Neither force nor guile can sever<br/>Those He loves from Him.<br/>',NULL,802,802);
INSERT INTO stanza VALUES('E161','4','Keep us, Lord, oh, keep us cleaving<br/>To Thyself and still believing,<br/>Till the hour of Thy receiving<br/>The victorious Bride.<br/>',NULL,803,803);
INSERT INTO stanza VALUES('E161','5','Then we shall be where we would be;<br/>Then we shall be what we should be;<br/>Things which are not now, nor could be,<br/>Then shall be our own.<br/>',NULL,804,804);
INSERT INTO stanza VALUES('E162','1','With praise and thanksgiving there<br/>stands a great throng<br/>In the presence of Jesus and sing<br/>this new song.<br/>',NULL,805,805);
INSERT INTO stanza VALUES('E162','chorus','Unto Him Who hath loved us and<br/>washed us from sin,<br/>Unto Him be the glory forever!<br/>Amen!<br/>',NULL,806,806);
INSERT INTO stanza VALUES('E162','2','All these once were sinners, defiled<br/>in His sight,<br/>Now arrayed in pure garments, in<br/>praise they unite.<br/>',NULL,807,807);
INSERT INTO stanza VALUES('E162','3','He maketh the rebel a priest and a<br/>king,<br/>He hath bought us, and taught us<br/>this new song to sing.<br/>',NULL,808,808);
INSERT INTO stanza VALUES('E162','4','How helpless and hopeless we sinners<br/>had been,<br/>If He never had loved us till cleansed from our<br/>sin.<br/>',NULL,809,809);
INSERT INTO stanza VALUES('E162','5','Aloud in His praises our voices shall<br/>ring,<br/>So that others, believing, this new song shall<br/>sing.<br/>',NULL,810,810);
INSERT INTO stanza VALUES('E163','1','O for a thousand tongues to sing<br/>My great Redeemer''s praise,<br/>The glories of my God and King,<br/>The triumphs of His grace.<br/>',NULL,811,811);
INSERT INTO stanza VALUES('E163','2','My gracious Master and my God,<br/>Assist me to proclaim,<br/>To spread through all the earth abroad,<br/>The honors of Thy name.<br/>',NULL,812,812);
INSERT INTO stanza VALUES('E163','3','Jesus! The name that charms our fears,<br/>That bids our sorrows cease;<br/>''Tis music in the sinner''s ears,<br/>''Tis life, and health, and peace.<br/>',NULL,813,813);
INSERT INTO stanza VALUES('E163','4','His love my heart has captive made,<br/>His captive would I be,<br/>For He was bound, and scourged and died,<br/>My captive soul to free.<br/>',NULL,814,814);
INSERT INTO stanza VALUES('E163','5','He breaks the power of canceled sin,<br/>He sets the prisoner free;<br/>His blood can make the foulest clean;<br/>His blood availed for me.<br/>',NULL,815,815);
INSERT INTO stanza VALUES('E163','6','So now Thy blessed Name I love,<br/>Thy will would e''er be mine.<br/>Had I a thousand hearts to give,<br/>My Lord, they all were Thine!<br/>',NULL,816,816);
INSERT INTO stanza VALUES('E164','1','Let me sing, for the glory of heaven<br/>Like a sunbeam has swept o''er my heart;<br/>I would praise Thee for sins all forgiven,<br/>For Thy love, which shall never depart.<br/>',NULL,817,817);
INSERT INTO stanza VALUES('E164','2','If Thy works praise Thee, Giver of good,<br/>If the sun shines his praise unto Thee,<br/>If the wind, as it sighs through the wood,<br/>Makes a murmur of song from each tree,<br/>',NULL,818,818);
INSERT INTO stanza VALUES('E164','3','Then these lips, sure, a tribute shall bring,<br/>Though unworthy the praises must be;<br/>Shall all nature be vocal and sing,<br/>And no psalm of rejoicing from me?<br/>',NULL,819,819);
INSERT INTO stanza VALUES('E164','4','O wonderful, glorious Redeemer!<br/>I would worship Thee, Savior Divine;<br/>And rejoice, though surrounded with praises,<br/>Thou wilt still hear a song such as mine.<br/>',NULL,820,820);
INSERT INTO stanza VALUES('E165','1','My song shall be of Jesus;<br/>His mercy crowns my days,<br/>He fills my cup with blessings,<br/>And tunes my heart to praise.<br/>My song shall be of Jesus,<br/>The precious Lamb of God,<br/>Who gave Himself my ransom,<br/>And bought me with His blood.<br/>',NULL,821,821);
INSERT INTO stanza VALUES('E165','2','My song shall be of Jesus<br/>When, sitting at His feet,<br/>I call to mind His goodness<br/>In meditation sweet:<br/>My song shall be of Jesus,<br/>Whatever ill betide;<br/>I''ll sing the grace that saves me,<br/>And keeps me at His side.<br/>',NULL,822,822);
INSERT INTO stanza VALUES('E165','3','My song shall be of Jesus<br/>While pressing on my way<br/>To reach the blissful kingdom<br/>Of pure and perfect day:<br/>And when my soul shall enter<br/>That realm of splendor fair,<br/>A song of praise to Jesus<br/>I''ll sing forever there.<br/>',NULL,823,823);
INSERT INTO stanza VALUES('E166','1','Praise to the Lord, the Almighty, the<br/>King of creation!<br/>O my soul, praise Him, for He is thy<br/>health and salvation!<br/>All ye who hear,<br/>Now to His temple draw near;<br/>Sing now in glad adoration!<br/>',NULL,824,824);
INSERT INTO stanza VALUES('E166','2','Praise to the Lord, who o''er all<br/>things so wondrously reigneth,<br/>Who, as on wings of an eagle,<br/>uplifteth, sustaineth.<br/>Hast thou not seen<br/>How thy desires all have been<br/>Granted in what He ordaineth?<br/>',NULL,825,825);
INSERT INTO stanza VALUES('E166','3','Praise to the Lord, who hath fearfully,<br/>wondrously, made thee!<br/>Health hath vouchsafed and, when<br/>heedlessly falling, hath stayed thee.<br/>What need-or grief<br/>Ever hath failed of reliefs<br/>Wings of His mercy did shade thee.<br/>',NULL,826,826);
INSERT INTO stanza VALUES('E166','4','Praise to the Lord, who doth prosper<br/>thy work and defend thee,<br/>Who from the heavens the streams of<br/>His mercy doth send thee.<br/>Ponder anew<br/>What the Almighty can do,<br/>Who with His love doth befriend thee.<br/>',NULL,827,827);
INSERT INTO stanza VALUES('E166','5','Praise to the Lord!<br/>Oh, let all that is in me adore Him!<br/>All that hath life and breath, come<br/>now with praises before Him!<br/>Let the Amen<br/>Sound from His people again;<br/>Gladly for aye we adore Him.<br/>',NULL,828,828);
INSERT INTO stanza VALUES('E167','1','How good is the Lord we adore,<br/>Our faithful, unchangeable Friend;<br/>His love is as great as His pow''r<br/>And knows neither measure nor end.<br/>',NULL,829,829);
INSERT INTO stanza VALUES('E167','2','''Tis Jesus the first and the last,<br/>Who shall guide us through all to the throne;<br/>We''ll praise Him for all that is past,<br/>We''ll trust Him for all that''s to come.<br/>',NULL,830,830);
INSERT INTO stanza VALUES('E168','1','Now in a song of grateful praise,<br/>To Thee, O Lord, my voice I''ll raise;<br/>With all Thy saints I''ll join to tell,<br/>My Savior has done all things well.<br/>',NULL,831,831);
INSERT INTO stanza VALUES('E168','chorus','And above the rest this note shall swell,<br/>This note shall swell, this note shall swell,<br/>And above the rest this note shall swell,<br/>My Savior has done all things well.<br/>',NULL,832,832);
INSERT INTO stanza VALUES('E168','2','How sov''reign, wonderful and free,<br/>Has been Thy love to sinful me!<br/>Thou sav''dst me from the jaws of hell;<br/>My Savior has done all things well.<br/>',NULL,833,833);
INSERT INTO stanza VALUES('E168','3','Since e''er my soul has known His love,<br/>What mercies He has made me prove,<br/>Mercies which do all praise excel,<br/>My Savior has done all things well.<br/>',NULL,834,834);
INSERT INTO stanza VALUES('E168','4','And when on that bright day I rise,<br/>And join the anthems of the skies,<br/>Above the rest this note shall swell,<br/>My Savior has done all things well.<br/>',NULL,835,835);
INSERT INTO stanza VALUES('E169','1','Thou, Lord, to God art precious,<br/>His chosen, His delight;<br/>With oil of joy, anointed,<br/>How comely in His sight.<br/>',NULL,836,836);
INSERT INTO stanza VALUES('E169','chorus','We treasure with affection<br/>Thy perfect comeliness,<br/>Thy sweetness and Thy fragrance,<br/>And all Thy loveliness.<br/>',NULL,837,837);
INSERT INTO stanza VALUES('E169','2','The altogether lovely,<br/>The fairest of the fair,<br/>Thy mouth with grace o''erfloweth;<br/>Our hearts their love declare.<br/>',NULL,838,838);
INSERT INTO stanza VALUES('E169','3','The wise men offered treasures<br/>And honored Thee at birth;<br/>Thou wast by noble buried,<br/>Still lovable in death.<br/>',NULL,839,839);
INSERT INTO stanza VALUES('E169','4','Thy head has been anointed,<br/>The lovely One Thou art;<br/>Thy feet anointed also,<br/>Beloved in every part.<br/>',NULL,840,840);
INSERT INTO stanza VALUES('E169','5','Thy death as myrrh in sweetness<br/>Man''s spirit comforteth;<br/>Thy resurrection fragrance<br/>God''s longing answereth.<br/>',NULL,841,841);
INSERT INTO stanza VALUES('E169','6','As henna flow''rs, Thy beauty<br/>In loveliness complete;<br/>As apple trees that flourish,<br/>Thy fruit abundant, sweet.<br/>',NULL,842,842);
INSERT INTO stanza VALUES('E169','7','Sweet wine Thy love surpasseth,<br/>Thy name an ointment is;<br/>We take Thee as our love feast<br/>And taste the sweetest bliss.<br/>',NULL,843,843);
INSERT INTO stanza VALUES('E169','8','As on Thyself we ponder<br/>And all Thy beauty trace,<br/>We taste to full Thy sweetness<br/>And rest in Thine embrace.<br/>',NULL,844,844);
INSERT INTO stanza VALUES('E170','1','Lord, Thou art the lovely Bridegroom,<br/>God appointed, dear to us;<br/>Thy dear self is so, attractive,<br/>To our heart so beauteous!<br/>',NULL,845,845);
INSERT INTO stanza VALUES('E170','2','Dear Beloved, we admire Thee,<br/>Who can tell Thy preciousness;<br/>All Thy love we deeply treasure<br/>And Thine untold loveliness.<br/>',NULL,846,846);
INSERT INTO stanza VALUES('E170','3','Thou art fairer than the fairest,<br/>Thou art sweeter than the sweet;<br/>Thou art meek and Thou art gracious,<br/>None can e''er with Thee compete.<br/>',NULL,847,847);
INSERT INTO stanza VALUES('E170','4','Full of myrrh are all Thy garments,<br/>And Thy lips are filled with grace;<br/>In the savor of Thy suffering,<br/>We in love Thyself embrace.<br/>',NULL,848,848);
INSERT INTO stanza VALUES('E170','5','It is with the oil of gladness<br/>Thy God hath anointed Thee;<br/>From the palaces of ivory<br/>Praise shall ever rise to Thee.<br/>',NULL,849,849);
INSERT INTO stanza VALUES('E170','6','God hath blessed Thee, Lord, forever,<br/>Thou hast won the victory;<br/>Now we see Thee throned in glory<br/>With Thy pow''r and majesty.<br/>',NULL,850,850);
INSERT INTO stanza VALUES('E170','7','Thou art the desire of nations,<br/>All Thy worth they''ll ever prove;<br/>Thou, the chiefest of ten thousand,<br/>Ever worthy of our love.<br/>',NULL,851,851);
INSERT INTO stanza VALUES('E171','1','Lord Jesus Christ, our heart feels sweet<br/>Whene''er we think on Thee,<br/>And long that to Thy presence dear<br/>We soon might raptured be!<br/>',NULL,852,852);
INSERT INTO stanza VALUES('E171','chorus','Lord, like the pretty +henna-flower,<br/>In vineyards blossoming Thou art;<br/>Incomp''rable Thy beauty is,<br/>Admires and loves our heart!<br/>',NULL,853,853);
INSERT INTO stanza VALUES('E171','2','There is no music adequate<br/>Thy grace in full to praise,<br/>Nor there a heart which could enjoy<br/>Thy love in every phase.<br/>',NULL,854,854);
INSERT INTO stanza VALUES('E171','3','Yet, what delights our heart the most<br/>Is not Thy love, Thy grace;<br/>But it is Thine own loving Self<br/>That satisfies always.<br/>',NULL,855,855);
INSERT INTO stanza VALUES('E171','4','Oh, Thou art fairer than the fair,<br/>And sweeter than the sweet;<br/>Beside Thee, none in heaven or earth<br/>Our heart''s desire could meet.<br/>',NULL,856,856);
INSERT INTO stanza VALUES('E171','end-note','+Henna - An Old World plant, prized for its fragrant yellow and white flowers. (Song of Sol. 1:14, A.S.V)<br/>',NULL,857,857);
INSERT INTO stanza VALUES('E172','1','I cannot breathe enough of Thee,<br/>O gentle breeze of love;<br/>More fragrant than the myrtle tree<br/>The +Henna-flower is to me,<br/>The Balm of Heaven above.<br/>',NULL,858,858);
INSERT INTO stanza VALUES('E172','2','I cannot gaze enough on Thee,<br/>Thou Fairest of the Fair;<br/>My heart is filled with ecstasy,<br/>As in Thy face of radiancy<br/>I see such beauty there.<br/>',NULL,859,859);
INSERT INTO stanza VALUES('E172','3','I cannot yield enough to Thee,<br/>My Savior, Master, Friend;<br/>I do not wish to go out free,<br/>But ever, always, willingly,<br/>To serve Thee to the end.<br/>',NULL,860,860);
INSERT INTO stanza VALUES('E172','4','I cannot sing enough of Thee,<br/>The sweetest name on earth;<br/>A note so full of melody<br/>Comes from my heart so joyously,<br/>And fills my soul with mirth.<br/>',NULL,861,861);
INSERT INTO stanza VALUES('E172','5','I cannot speak enough of Thee,<br/>I have so much to tell;<br/>Thy heart it beats so tenderly<br/>As Thou dost draw me close to Thee,<br/>And whisper, "All is well."<br/>',NULL,862,862);
INSERT INTO stanza VALUES('E172','end-note','+Henna - An Old World plant, prized for its fragrant yellow and white flowers. (Song of Sol. 1:14, A.S.V)<br/>',NULL,863,863);
INSERT INTO stanza VALUES('E173','1','Thou art fairer than the morning,<br/>O my Savior and my King!<br/>Of Thy grandeur and Thy beauty,<br/>How my soul delights to sing.<br/>',NULL,864,864);
INSERT INTO stanza VALUES('E173','chorus','Thou art fairer than the morning,<br/>Thou art brighter, brighter than the day<br/>At the glory of Thy presence<br/>Clouds and darkness flee away.<br/>',NULL,865,865);
INSERT INTO stanza VALUES('E173','2','Clothed in light as with a garment,<br/>Crowned with majesty divine,<br/>Lo, the scepter of dominion<br/>Now and ever, Lord, is Thine.<br/>',NULL,866,866);
INSERT INTO stanza VALUES('E173','3','O the greatness of Thy mercy,<br/>And the richness of Thy grace!<br/>O the love that in Thy kingdom<br/>Is preparing me a place!<br/>',NULL,867,867);
INSERT INTO stanza VALUES('E173','4','When at last I reach the kingdom,<br/>Win the crown, the battle o''er,<br/>With ten thousand times ten thousand<br/>I shall sing forevermore.<br/>',NULL,868,868);
INSERT INTO stanza VALUES('E174','1','O Morning Star, how fair and bright,<br/>Thou beamest forth in truth and light!<br/>O Sov''reign meek and lowly,<br/>Thou Root of Jesse, David''s Son,<br/>My Lord and Master, Thou hast won<br/>My heart to serve Thee solely!<br/>Thou art holy,<br/>Fair and glorious, all-victorious,<br/>Rich in blessing,<br/>Rule and might o''er all possessing.<br/>',NULL,869,869);
INSERT INTO stanza VALUES('E174','2','Thou heav''nly Brightness, Light divine,<br/>O deep within my heart now shine,<br/>And make Thee there an altar.<br/>Fill me with joy and strength to be<br/>Thy member, ever joined to Thee<br/>In love that cannot falter;<br/>Toward Thee longing<br/>Doth possess me; turn and bless me;<br/>Here in sadness<br/>Eye and heart long for Thy gladness.<br/>',NULL,870,870);
INSERT INTO stanza VALUES('E175','1','Fairest Lord Jesus!<br/>Ruler of all nature!<br/>O Thou of God and man the Son!<br/>Thee will I cherish,<br/>Thee will I honor,<br/>Thou, my soul''s glory, joy, and crown!<br/>',NULL,871,871);
INSERT INTO stanza VALUES('E175','2','Fair are the meadows,<br/>Fairer still the woodlands,<br/>Robed in the blooming garb of spring;<br/>Jesus is fairer,<br/>Jesus is purer,<br/>Who makes the woeful heart to sing!<br/>',NULL,872,872);
INSERT INTO stanza VALUES('E175','3','Fair is the sunshine,<br/>Fairer still the moonlight,<br/>And all the twinkling starry host;<br/>Jesus shines brighter,<br/>Jesus shines purer,<br/>Than all the angels heav''n can boast!<br/>',NULL,873,873);
INSERT INTO stanza VALUES('E175','4','All fairest beauty,<br/>Heavenly and earthly,<br/>Wondrously, Jesus, is found in Thee;<br/>None can be nearer,<br/>Fairer, or dearer,<br/>Than Thou my Savior art to me.<br/>',NULL,874,874);
INSERT INTO stanza VALUES('E176','1','Jesus, wondrous Savior!<br/>Christ, of kings the King!<br/>Angels fall before Thee,<br/>Prostrate, worshipping;<br/>Fairest they confess Thee<br/>In the heav''n above.<br/>We would sing Thee fairest<br/>Here in hymns of love.<br/>',NULL,875,875);
INSERT INTO stanza VALUES('E176','2','All earth''s flowing pleasures<br/>Were a wintry sea;<br/>Heav''n itself without Thee<br/>Dark as night would be.<br/>Lamb of God! Thy glory<br/>Is the light above.<br/>Lamb of God! Thy glory<br/>Is the life of love.<br/>',NULL,876,876);
INSERT INTO stanza VALUES('E176','3','Life is death, if severed<br/>From Thy throbbing heart.<br/>Death with life abundant<br/>At Thy touch would start.<br/>Worlds and men and angels<br/>All consist in Thee,<br/>Yet Thou camest to us<br/>In humility.<br/>',NULL,877,877);
INSERT INTO stanza VALUES('E176','4','Jesus! All perfections<br/>Rise and end in Thee;<br/>Brightness of God''s glory<br/>Thou, eternally.<br/>Favored beyond measure<br/>They Thy face who see;<br/>May we, gracious Savior,<br/>Share this ecstasy.<br/>',NULL,878,878);
INSERT INTO stanza VALUES('E177','1','Majestic sweetness sits enthroned<br/>Upon the Savior''s brow;<br/>His head with radiant glories crowned,<br/>His lips with grace o''erflow.<br/>',NULL,879,879);
INSERT INTO stanza VALUES('E177','2','No mortal can with Him compare<br/>Among the sons of men;<br/>Fairer is He than all the fair<br/>That fill the heavenly train.<br/>',NULL,880,880);
INSERT INTO stanza VALUES('E177','3','To Him I owe my life and breath,<br/>And all the joys I have;<br/>He makes me triumph over death,<br/>And saves me from the grave.<br/>',NULL,881,881);
INSERT INTO stanza VALUES('E177','4','To God, the Father, my abode,<br/>He brings my weary feet;<br/>Shows me, the glories, of my God,<br/>And makes my joys complete.<br/>',NULL,882,882);
INSERT INTO stanza VALUES('E177','5','Since from His bounty I receive<br/>Such proofs of love divine,<br/>Had I a thousand hearts to give,<br/>Lord, they should all be Thine.<br/>',NULL,883,883);
INSERT INTO stanza VALUES('E178','1','Our hearts are full of Christ and long<br/>Their glorious matter to declare!<br/>Of Him we make our loftier song,<br/>We cannot from His praise forbear:<br/>Our ready tongues make haste to sing The<br/>glories of the heav''nly,King.<br/>',NULL,884,884);
INSERT INTO stanza VALUES('E178','2','Fairer than all the earthborn race,<br/>Perfect in comeliness Thou art;<br/>Replenished are Thy lips with grace,<br/>And full of love Thy tender heart.<br/>God ever-blest! We bow the knee,<br/>And own all fulness dwells in Thee.<br/>',NULL,885,885);
INSERT INTO stanza VALUES('E179','1','Glory to Christ on high!<br/>Let praises fill the sky!<br/>Praise ye His name:<br/>He all our sorrows bore;<br/>Angels His name adore,<br/>And saints cry evermore,<br/>"Worthy the Lamb!"<br/>',NULL,886,886);
INSERT INTO stanza VALUES('E179','2','All they around the throne<br/>Cheerfully join in one,<br/>Praising His name:<br/>We who have known His blood<br/>Sealing our peace with God,<br/>Spread His dear name abroad;<br/>Worthy the Lamb!<br/>',NULL,887,887);
INSERT INTO stanza VALUES('E179','3','Join all the human race<br/>Our Lord, God''s Christ, to bless,<br/>Praise ye His name:<br/>In Him we will rejoice,<br/>Making a cheerful noise,<br/>Saying with heart and voice,<br/>"Worthy the Lamb!"<br/>',NULL,888,888);
INSERT INTO stanza VALUES('E179','4','Though we must change our place,<br/>Our hearts shall never cease<br/>Praising His name:<br/>To Him we''ll tribute bring,<br/>Laud Him, our gracious King,<br/>And, without ceasing, sing,<br/>"Worthy the Lamb!"<br/>',NULL,889,889);
INSERT INTO stanza VALUES('E180','1','Jesus, our Lord, with what joy we adore Thee,<br/>Chanting our praise to Thyself on the throne!<br/>Blest in Thy presence, we worship before<br/>Thee,<br/>Own Thou art worthy, and worthy alone.<br/>',NULL,890,890);
INSERT INTO stanza VALUES('E180','chorus','Lord, Thou art worthy: Lord, Thou art<br/>worthy;<br/>Lord, Thou art worthy, and worthy alone!<br/>Blest in Thy presence, we worship before<br/>Thee,<br/>Own Thou art worthy, and worthy alone!<br/>',NULL,891,891);
INSERT INTO stanza VALUES('E180','2','Verily God, yet become truly human,<br/>Lower than angels to die in our stead;<br/>How has that long promised "Seed of the<br/>woman"<br/>Trod on the serpent and bruised his head!<br/>',NULL,892,892);
INSERT INTO stanza VALUES('E180','3','How didst Thou humble Thyself to be taken,<br/>Led by Thy creatures and nailed to the cross,<br/>Hated of men, and of God too forsaken,<br/>Shunning not darkness, the curse, and the loss.<br/>',NULL,893,893);
INSERT INTO stanza VALUES('E180','4','How hast Thou triumphed, and triumphed<br/>with glory,<br/>Battled death''s forces, rolled back every wave!<br/>Can we refrain then from telling the story?<br/>Lord, Thou art Victor o''er death and the grave.<br/>',NULL,894,894);
INSERT INTO stanza VALUES('E181','1','''Tis the Church triumphant singing,<br/>Worthy the Lamb;<br/>Heav''n throughout with praises ringing,<br/>Worthy the Lamb.<br/>Thrones and pow''rs before, Him bending,<br/>Odors sweet with voice ascending<br/>Swell the chorus never ending,<br/>Worthy the Lamb.<br/>',NULL,895,895);
INSERT INTO stanza VALUES('E181','2','Every kindred, tongue and nation,<br/>Worthy the Lamb;<br/>Join to sing the great salvation,<br/>Worthy the Lamb.<br/>Loud as mighty thunders roaring,<br/>Floods of mighty waters pouring,<br/>Prostrate at His feet adoring,<br/>Worthy the Lamb.<br/>',NULL,896,896);
INSERT INTO stanza VALUES('E181','3','Harps and songs forever sounding,<br/>Worthy the Lamb;<br/>Mighty grace o''er sin abounding,<br/>Worthy the Lamb.<br/>By His blood He dearly bought us;<br/>Wand''ring from the fold He sought us,<br/>And to glory safely brought us;<br/>Worthy the Lamb.<br/>',NULL,897,897);
INSERT INTO stanza VALUES('E181','4','Sing with blest anticipation<br/>Worthy the Lamb;<br/>Through the vale of tribulation,<br/>Worthy the Lamb.<br/>Sweetest notes, all notes excelling,<br/>On the theme forever dwelling,<br/>Still untold, though ever telling,<br/>Worthy the Lamb.<br/>',NULL,898,898);
INSERT INTO stanza VALUES('E182','1','Jesus, Thou alone art worthy<br/>Ceaseless praises to receive;<br/>For Thy love and grace and goodness<br/>Rise o''er all our thoughts conceive.<br/>',NULL,899,899);
INSERT INTO stanza VALUES('E182','2','With adoring heart, we render<br/>Honor to Thy precious name,<br/>Overflowing with Thy mercies,<br/>Far and wide Thy worth proclaim.<br/>',NULL,900,900);
INSERT INTO stanza VALUES('E182','3','Praise Him! Praise Him! Praise the Savior!<br/>Saints, aloud your voices raise,<br/>Praise Him! Praise Him! Till in glory<br/>Perfected we''ll sing His praise.<br/>',NULL,901,901);
INSERT INTO stanza VALUES('E183','1','Come, let us join our cheerful songs,<br/>And thus approach the throne;<br/>Had we ten thousand thousand tongues,<br/>Our theme of joy''s but one:<br/>',NULL,902,902);
INSERT INTO stanza VALUES('E183','2','"Worthy the Lamb that''s gone on high,<br/>To be exalted thus!"<br/>"Worthy the Lamb that died!" we cry,<br/>"For He was slain for us."<br/>',NULL,903,903);
INSERT INTO stanza VALUES('E183','3','Jesus is worthy to receive<br/>Honor and pow''r divine;<br/>And blessings more than we can give<br/>Be, Lord, forever Thine.<br/>',NULL,904,904);
INSERT INTO stanza VALUES('E183','4','Soon shall the saints, exalted high,<br/>A glorious anthem raise,<br/>And all that dwell beneath the sky<br/>Speak forth Thine endless praise.<br/>',NULL,905,905);
INSERT INTO stanza VALUES('E183','5','Redeemed creation join in one,<br/>T''adore the sacred name<br/>Of Him that sits upon the throne,<br/>And to exalt the Lamb.<br/>',NULL,906,906);
INSERT INTO stanza VALUES('E184','1','Come, let us sing the song of songs,<br/>The saints of old began the strain,<br/>The blessing which to Christ belongs:<br/>Worthy the Lamb, for He was slain!<br/>',NULL,907,907);
INSERT INTO stanza VALUES('E184','2','Slain to redeem us by His blood,<br/>To cleanse from every sinful stain;<br/>And make us kings and priests to God;<br/>Worthy the Lamb, for He was slain!<br/>',NULL,908,908);
INSERT INTO stanza VALUES('E184','3','Long as we live, and should we die,<br/>And while in light with Him we reign,<br/>This song our song of songs shall be:<br/>Worthy the Lamb, for He was slain!<br/>',NULL,909,909);
INSERT INTO stanza VALUES('E185','1','Blessed Lord, our hallelujahs<br/>Now to Thee we raise.<br/>Never could we fully utter<br/>All Thy worth and praise!<br/>',NULL,910,910);
INSERT INTO stanza VALUES('E185','chorus','Praise the Lamb, for He is worthy!<br/>Sweet eternal strain.<br/>Hallelujah! Hallelujah!<br/>Praise the Lord! Amen.<br/>',NULL,911,911);
INSERT INTO stanza VALUES('E185','2','Praise the Lamb! Yes, Thou art worthy,<br/>Who didst shed Thy blood<br/>To redeem Thy saints, and make us<br/>Kings and priests to God!<br/>',NULL,912,912);
INSERT INTO stanza VALUES('E185','3','Hallelujah! Thou, Lord Jesus,<br/>Canst not cease to love;<br/>Thine we are and Thine forever,<br/>One with Thee above.<br/>',NULL,913,913);
INSERT INTO stanza VALUES('E185','4','Praise the Lord! Yes, hallelujah!<br/>Who would hush the song?<br/>Join with saints from every nation,<br/>Every tribe and tongue.<br/>',NULL,914,914);
INSERT INTO stanza VALUES('E186','1','Glory be to Him who loved us,<br/>Washed us from each sinful stain;<br/>Glory be to Him who made us<br/>Priests and kings with Him to reign;<br/>Glory, worship, laud and blessing<br/>To the Lamb who once was slain.<br/>',NULL,915,915);
INSERT INTO stanza VALUES('E186','2','Glory, worship, laud and blessing,<br/>Thus the choir triumphant sings;<br/>Honor, riches, power, dominion,<br/>Thus its praise creation brings;<br/>Thou art worthy, Thou art worthy,<br/>Lord of lords, and King of kings.<br/>',NULL,916,916);
INSERT INTO stanza VALUES('E186','3','Glory to the King of angels,<br/>Glory to the Church''s King,<br/>Glory to the King of nations,<br/>Heaven and earth His praises sing;<br/>Glory ever and forever<br/>To the King of Glory bring.<br/>',NULL,917,917);
INSERT INTO stanza VALUES('E187','end-note','This hymn may be used as five separate<br/>hymns as follows:<br/>Verses 1 to 8 and 26<br/>2. Verses 1 and 9 to 13 and 26<br/>3. Verses I and 14 to 17 and 26<br/>4. Verses I and 18 to 21 and 26<br/>5. Verses 1 and 22 to 26<br/>',NULL,918,946);
INSERT INTO stanza VALUES('E187','1','O Lord, how rich Thou art to us,<br/>Thy love reveals the measure!<br/>The boundless riches of Thyself,<br/>In spirit here we treasure.<br/>',NULL,920,920);
INSERT INTO stanza VALUES('E187','2','Thou art the Word, e''en God Himself,<br/>With God in the beginning;<br/>Incarnate in the flesh with us,<br/>And God to us defining.<br/>',NULL,921,921);
INSERT INTO stanza VALUES('E187','3','Thou art the tabernacle true,<br/>In Thee we see God''s glory;<br/>For God Thou art the temple too,<br/>In Thee is God''s full story.<br/>',NULL,922,922);
INSERT INTO stanza VALUES('E187','4','Thou art the only Son of God,<br/>The Father e''er declaring,<br/>That we may have the life divine,<br/>God''s very nature sharing.<br/>',NULL,923,923);
INSERT INTO stanza VALUES('E187','5','Thou art the Son of Man like us,<br/>And truly share our nature,<br/>That we may be the sons of God<br/>And grow to Thy full stature.<br/>',NULL,924,924);
INSERT INTO stanza VALUES('E187','6','Thou art the Christ, the Lord of all,<br/>By God Thou art anointed;<br/>The One who is the All in all,<br/>For God and us appointed.<br/>',NULL,925,925);
INSERT INTO stanza VALUES('E187','7','Thou art the Savior crucified,<br/>Whence issued blood and water,<br/>That we might be redeemed to God,<br/>And life divine may enter.<br/>',NULL,926,926);
INSERT INTO stanza VALUES('E187','8','Thou now art Jesus glorified,<br/>From whom descends the Spirit;<br/>The all-inclusive Spirit comes<br/>To us with all Thy merit.<br/>',NULL,927,927);
INSERT INTO stanza VALUES('E187','9','Thou art the very light of life<br/>That shineth in the darkness;<br/>The light divine that shines with God<br/>Within our hearts in fulness.<br/>',NULL,928,928);
INSERT INTO stanza VALUES('E187','10','Thou art the very life divine,<br/>Which all our spirits quickens;<br/>The life which brings us out of death<br/>And all our being strengthens.<br/>',NULL,929,929);
INSERT INTO stanza VALUES('E187','11','Lord, Thou art God''s reality,<br/>The truth that meets God''s pleasure;<br/>The truth that, brings Thyself to us,<br/>That we may know Thy measure.<br/>',NULL,930,930);
INSERT INTO stanza VALUES('E187','12','Thou also art the way of life,<br/>Which unto glory leads us;<br/>The way of Thy reality,<br/>Which into vict''ry speeds us.<br/>',NULL,931,931);
INSERT INTO stanza VALUES('E187','13','Thou art the resurrection too,<br/>All death Thy life doth swallow;<br/>''Tis by Thy resurrection pow''r,<br/>We bear the cross and follow.<br/>',NULL,932,932);
INSERT INTO stanza VALUES('E187','14','Thou art the spotless Lamb of God,<br/>Who died for our redemption;<br/>Thou art the Spirit-giver too,<br/>For our regeneration.<br/>',NULL,933,933);
INSERT INTO stanza VALUES('E187','15','Thou art the serpent made of brass,<br/>Who saveth us from evil;<br/>Thou on the tree wast lifted up,<br/>To crush for us the devil.<br/>',NULL,934,934);
INSERT INTO stanza VALUES('E187','16','Thou art the Shepherd and the door,<br/>For us to leave the sheepfold,<br/>By Thee we have full liberty<br/>And share the pasture freehold.<br/>',NULL,935,935);
INSERT INTO stanza VALUES('E187','17','Thy washing keeps us always clean,<br/>In function like the laver;<br/>Thus we are kept in fellowship,<br/>Partaking of Thy favor.<br/>',NULL,936,936);
INSERT INTO stanza VALUES('E187','18','Thou art the heav''nly riven rock,<br/>With living water flowing;<br/>We drink of this refreshing stream,<br/>Thy quenching power knowing.<br/>',NULL,937,937);
INSERT INTO stanza VALUES('E187','19','Thou art the heav''nly well, in Thee<br/>Is living water ever;<br/>We drink of Thine eternal life,<br/>And thirst no more forever.<br/>',NULL,938,938);
INSERT INTO stanza VALUES('E187','20','Thou art the heav''nly bread of life,<br/>Thy food divine doth flourish;<br/>With all Thy riches bountiful<br/>Our spirits Thou dost nourish.<br/>',NULL,939,939);
INSERT INTO stanza VALUES('E187','21','Thou even art our breath of life<br/>Thyself we breathe in spirit,<br/>By Thee we live, in Thee we walk,<br/>Thy riches we inherit.<br/>',NULL,940,940);
INSERT INTO stanza VALUES('E187','22','Thou art the grain of wheat divine,<br/>That died and rose with glory,<br/>To bring forth us as many grains<br/>To form Thy glorious Body.<br/>',NULL,941,941);
INSERT INTO stanza VALUES('E187','23','Thou art the true and heav''nly vine,<br/>And we in Thee are<br/>In Thee abiding, Thou in us,<br/>We share in all Thy riches.<br/>',NULL,942,942);
INSERT INTO stanza VALUES('E187','24','Thou art the Bridegroom from above<br/>To take the Bride, Thy Body;<br/>That we may be with Thee as one,<br/>In life and love and glory.<br/>',NULL,943,943);
INSERT INTO stanza VALUES('E187','25','Thou art the ladder Jacob saw,<br/>By Thee the heav''n is open;<br/>In Thee we are the house of God,<br/>And earth is joined to heaven.<br/>',NULL,944,944);
INSERT INTO stanza VALUES('E187','26','O Lord, Thou art the great "I AM,"<br/>Who all our need doth furnish;<br/>Enjoying Thee as all in all,<br/>God''s purpose we accomplish.<br/>',NULL,945,945);
INSERT INTO stanza VALUES('E188','end-note','This hymn may be shortened by singing only<br/>verses 1, 2, 7, 9, 11, 14, 17, 21 & 22, as marked<br/>with asterisks.<br/>',NULL,946,969);
INSERT INTO stanza VALUES('E188','1','Dear Lord, Thou art the Son of God,<br/>His absolute expression;<br/>In Thee God speaks to us today,<br/>Thou art His definition.<br/>',NULL,947,947);
INSERT INTO stanza VALUES('E188','2','The impress of God''s substance true,<br/>Effulgence of His glory,<br/>Thou even art our God Himself,<br/>In Thee is His full story.<br/>',NULL,948,948);
INSERT INTO stanza VALUES('E188','3','By Thee was made, the universe,<br/>Subsisting by Thy merit;<br/>The heir God hath appointed Thee,<br/>That all Thou may inherit.<br/>',NULL,949,949);
INSERT INTO stanza VALUES('E188','4','Since Thou hast purged our sins by death,<br/>In heaven Thou art seated,<br/>Till all Thy foes will be subdued<br/>And all God''s will completed.<br/>',NULL,950,950);
INSERT INTO stanza VALUES('E188','5','A better name than angels have,<br/>From God Thou didst inherit;<br/>As Son of God to us as life,<br/>Thou now art in the Spirit.<br/>',NULL,951,951);
INSERT INTO stanza VALUES('E188','6','Thy kingdom is of righteousness,<br/>Thy throne will stand forever;<br/>God hath in love anointed Thee,<br/>And Thou shalt wax old never.<br/>',NULL,952,952);
INSERT INTO stanza VALUES('E188','7','Thou also art a man indeed,<br/>With all our human nature;<br/>By grace Thou tastedst death for us<br/>That we may have Thy stature.<br/>',NULL,953,953);
INSERT INTO stanza VALUES('E188','8','With glory and with honor crowned,<br/>All things to Thee are subject,<br/>As Captain of salvation, full,<br/>Thou art thru sufferings perfect.<br/>',NULL,954,954);
INSERT INTO stanza VALUES('E188','9','By death the devil Thou hast spoiled,<br/>And from death''s bondage freed us;<br/>Thou sanctifiest us in life<br/>And dost to glory speed us.<br/>',NULL,955,955);
INSERT INTO stanza VALUES('E188','10','To us, Thy brethren, Thou art here,<br/>The Father''s Name declaring;<br/>Within the Church Thou singest hymns,<br/>God''s praises with us sharing.<br/>',NULL,956,956);
INSERT INTO stanza VALUES('E188','11','Superior Thou to Moses, Lord,<br/>As to the house the builder;<br/>Thou, our Apostle sent flow God,<br/>Art worthy of more splendor.<br/>',NULL,957,957);
INSERT INTO stanza VALUES('E188','12','Thou art our real Joshua,<br/>By Thee the rest we enter;<br/>Our full salvation is of Thee,<br/>Our faith on Thee doth center.<br/>',NULL,958,958);
INSERT INTO stanza VALUES('E188','13','Thou art the heav''nly rest -to us,<br/>Now dwelling in our spirit,<br/>For us to enter as the land<br/>And all Thy good inherit.<br/>',NULL,959,959);
INSERT INTO stanza VALUES('E188','14','Superior Thou to Aaron too-<br/>Thyself, the offering given,<br/>Thou enteredst, as our Great High Priest,<br/>The holiest place in heaven.<br/>',NULL,960,960);
INSERT INTO stanza VALUES('E188','15','Thou art our true Melchisedec,<br/>With endless life in power,<br/>To minister the "bread and wine,"<br/>In every needful hour.<br/>',NULL,961,961);
INSERT INTO stanza VALUES('E188','16','Thou art the better sacrifice,<br/>Thru the eternal Spirit,<br/>Once offered unto God for us,<br/>That we may gain Thy merit.<br/>',NULL,962,962);
INSERT INTO stanza VALUES('E188','17','A better covenant was made<br/>With Thy dear blood in heaven;<br/>By Thee this sure new testament<br/>To Thy redeemed was given.<br/>',NULL,963,963);
INSERT INTO stanza VALUES('E188','18','Thou, art its Maker adequate,<br/>For Thou dost have the merit;<br/>Thou art its Giver competent<br/>That we may all inherit;<br/>',NULL,964,964);
INSERT INTO stanza VALUES('E188','19','Its qualified Executor,<br/>By life of resurrection;<br/>Its potent Mediator too,<br/>Fulfilling God''s election.<br/>',NULL,965,965);
INSERT INTO stanza VALUES('E188','20','Lord, Thou art now within the veil,<br/>As our unique Forerunner,<br/>That by Thy life, without the camp,<br/>We''ll in the race be runners.<br/>',NULL,966,966);
INSERT INTO stanza VALUES('E188','21','Thou art the Finisher of faith,<br/>As well its Author perfect;<br/>By faith and love we follow Thee,<br/>And e''er to Thee are subject.<br/>',NULL,967,967);
INSERT INTO stanza VALUES('E188','22','Unequaled is Thy worth, dear Lord,<br/>And all Thou art we treasure;<br/>Thou art so perfect and complete,<br/>Beyond all human measure.<br/>',NULL,968,968);
INSERT INTO stanza VALUES('E189','1','Thou art the Son beloved,<br/>The image of our God;<br/>Thou art the saints'' dear portion,<br/>Imparted thru Thy blood.<br/>Among all God''s creation<br/>Thou art the firstborn One;<br/>By Thee all was created,<br/>All for Thyself to own.<br/>',NULL,969,969);
INSERT INTO stanza VALUES('E189','2','Thou art before all creatures,<br/>In Thee all things consist;<br/>Of all Thou art the center,<br/>By Thee all things subsist.<br/>Thou art the sole beginning,<br/>The Firstborn from the dead;<br/>And for the Church, Thy Body,<br/>Thou art the glorious Head.<br/>',NULL,970,970);
INSERT INTO stanza VALUES('E189','3','Because it pleased the Father,<br/>All fulness dwells in Thee,<br/>That Thou might have the first place<br/>In all we ever see.<br/>All things Thou reconciledst<br/>To God by Thy shed blood,<br/>To thus present us holy<br/>And blameless unto God.<br/>',NULL,971,971);
INSERT INTO stanza VALUES('E189','4','In Thee God''s fulness dwelleth,<br/>Thou art God''s mystery;<br/>The treasures of all wisdom<br/>And knowledge are in Thee.<br/>Thou art the hope of glory,<br/>In us Thou dost abide;<br/>In Thee we are perfected<br/>And God is satisfied.<br/>',NULL,972,972);
INSERT INTO stanza VALUES('E189','5','All things are but a shadow<br/>Which unto us reveal<br/>Thyself, in whom we''re rooted,<br/>The only One that''s real.<br/>Enjoying all Thy riches,<br/>Thy fulness we will be;<br/>We''ll hold Thee, as Thy Body,<br/>And grow with God in Thee.<br/>',NULL,973,973);
INSERT INTO stanza VALUES('E189','6','With Thee in God we''re hidden,<br/>Thou art in us our life;<br/>Thy peace in us presiding,<br/>We rest from all our strife.<br/>In the new man, Thy Body,<br/>Thou art the all in all;<br/>Our all-inclusive Savior,<br/>Thyself we''ll ever call.<br/>',NULL,974,974);
INSERT INTO stanza VALUES('E190','1','O Lord, as we consider Thee,<br/>We worship Thee for all Thou art;<br/>Thou art so rich, so wonderful,<br/>So dear and precious to our heart.<br/>',NULL,975,975);
INSERT INTO stanza VALUES('E190','chorus','What Thou art meets our every need!<br/>Our hearts o''erflow with praise to Thee!<br/>All our desires Thou dost exceed<br/>And satisfy continually.<br/>',NULL,976,976);
INSERT INTO stanza VALUES('E190','2','Thou art the very God in truth,<br/>The God who is both love and light;<br/>The God who is to us our life,<br/>The God in whom we all delight.<br/>',NULL,977,977);
INSERT INTO stanza VALUES('E190','3','Thou also art a man indeed,<br/>A man so fine, so good, so pure;<br/>A man in whom our God delights,<br/>A man who can our love secure.<br/>',NULL,978,978);
INSERT INTO stanza VALUES('E190','4','Thou even art a lowly slave,<br/>A slave of God to serve for us;<br/>Obedient to the cross''s death<br/>That we might be delivered thus.<br/>',NULL,979,979);
INSERT INTO stanza VALUES('E190','5','Thou art, beside all these, a King,<br/>A King in life and love to reign,<br/>By God anointed with His pow''r<br/>To rule with us in His domain.<br/>',NULL,980,980);
INSERT INTO stanza VALUES('E190','6','Dear Lord, as we remember Thee,<br/>We thus partake of all Thou art;<br/>As we enjoy Thyself in love,<br/>We share Thee as Thy counterpart.<br/>',NULL,981,981);
INSERT INTO stanza VALUES('E191','1','Lord, Thou art the "Seed of woman,"<br/>Born to bruise the enemy;<br/>Thou didst take the human nature,<br/>Die to win the victory.<br/>As the very God incarnate,<br/>Flesh and blood Thou didst partake;<br/>Thou thru death hast crushed the devil<br/>And his pow''r of death didst break.<br/>',NULL,982,982);
INSERT INTO stanza VALUES('E191','2','"Seed of Abraham," Thou art, Lord,<br/>By God''s promise Thou hast come,<br/>That the blessing He hath promised<br/>On all people thus might come.<br/>Abraham Thou hast preceded,<br/>For Thou art the great "I AM,"<br/>Yet Thou cam''st to be his offspring<br/>And become God''s promised "Lamb."<br/>',NULL,983,983);
INSERT INTO stanza VALUES('E191','3','Lord, Thou art the "Seed of David,"<br/>For the kingdom Thou wast raised;<br/>For God''s glory and His building<br/>On the throne Thou hast been placed.<br/>Truly Thou art "David''s offspring,"<br/>Yet "my Lord" he calleth Thee,<br/>For Thou art his "root" and fountain,<br/>"Lord of all" eternally.<br/>',NULL,984,984);
INSERT INTO stanza VALUES('E191','4','Though "a child" born with our nature,<br/>Thou the "Mighty God" art called;<br/>Thou, "a son." to us art given,<br/>"Everlasting Father" called.<br/>All the blessings God hath promised,<br/>With our faith on Thee depend;<br/>Thou art "Yea" and "Amen" for them,<br/>All the content and the end!<br/>',NULL,985,985);
INSERT INTO stanza VALUES('E192','1','We come, O Christ, to Thee,<br/>True Son of God and man,<br/>By whom all things consist,<br/>In whom all life began:<br/>In Thee alone we live and move<br/>And have our being in Thy love.<br/>',NULL,986,986);
INSERT INTO stanza VALUES('E192','2','Thou art the Way to God,<br/>Thy blood our ransom paid;<br/>In Thee we face our Judge<br/>And Maker unafraid.<br/>Before the Throne absolved we stand:<br/>Thy love has met Thy law''s demand.<br/>',NULL,987,987);
INSERT INTO stanza VALUES('E192','3','Thou art the living Truth!<br/>All wisdom dwells in Thee,<br/>Thou Source of every skill,<br/>Eternal Verity!<br/>Thou great I Am! In Thee we rest,<br/>True answer to our every quest.<br/>',NULL,988,988);
INSERT INTO stanza VALUES('E192','4','Thou only art true Life,<br/>To know Thee is to live<br/>The more abundant life<br/>That earth can never give:<br/>O Risen Lord! We live in Thee<br/>And Thou in us eternally!<br/>',NULL,989,989);
INSERT INTO stanza VALUES('E192','5','We worship Thee Lord Christ,<br/>Our Savior and our King,<br/>To Thee our youth and strength<br/>Adoringly we bring:<br/>So fill our hearts that men may see<br/>Thy life in us and turn to Thee!<br/>',NULL,990,990);
INSERT INTO stanza VALUES('E193','1','Dear Lord, Thou art so much to us<br/>Thou art our all in all;<br/>What Thou art fully meets our needs,<br/>Though they be great or small.<br/>Our hearts appreciate what Thou art,<br/>Our spirits worship Thee;<br/>Our grateful praise to Thee we give<br/>As we Thy riches see.<br/>',NULL,991,991);
INSERT INTO stanza VALUES('E193','2','Thou art the Prophet raised by God,<br/>With pow''r for God to speak;<br/>Like Moses, Thou God''s plan hast shown,<br/>That we God''s will may seek.<br/>Thou art like Jonah sent by God,<br/>To enter death and live,<br/>That by this sign of death and life,<br/>We may in Thee believe.<br/>',NULL,992,992);
INSERT INTO stanza VALUES('E193','3','Thou art the Prophet raised from men,<br/>To speak with pow''r and light;<br/>Thou, like Elisha, filled with love,<br/>Thy miracles in might.<br/>Thou, like Isaiah, full of grace,<br/>God''s Christ dost e''er reveal,<br/>That we may share this Christ of all<br/>As life both rich and real.<br/>',NULL,993,993);
INSERT INTO stanza VALUES('E193','4','Thou art the Priest from us to God,<br/>The holy Priest for us,<br/>Like Aaron called of God from men,<br/>For us Thou servest thus.<br/>In love Thou bearest us to God,<br/>The great High Priest to serve;<br/>With love Thou intercedest there<br/>And dost with strength preserve.<br/>',NULL,994,994);
INSERT INTO stanza VALUES('E193','5','Thou art the Priest from God to us,<br/>The royal Priest of God;<br/>Like Salem''s King, Melchisedec,<br/>The minister of God.<br/>With bread and wine Thou cam''st from God<br/>To us in time of need;<br/>Thou cam''st with God that we in Him<br/>Might fully share indeed.<br/>',NULL,995,995);
INSERT INTO stanza VALUES('E193','6','Thou art the King as David was,<br/>And God''s desire dost seek;<br/>The battle fought, the foe subdued,<br/>God''s heart Thou dost bespeak.<br/>Thou art empowered on the throne,<br/>Not with a human rod,<br/>But with authority divine<br/>To reign for us and God.<br/>',NULL,996,996);
INSERT INTO stanza VALUES('E193','7','Thou art the King like Solomon,<br/>Whose rule with peace was filled;<br/>With wisdom Thou dost reign in pow''r<br/>And Thou God''s house dost build.<br/>As King unseen Thou reignest now<br/>Among Thy saints with love;<br/>One day, when Thou shalt reign with us,<br/>Thou wilt Thy kingship prove.<br/>',NULL,997,997);
INSERT INTO stanza VALUES('E193','8','As King and Priest and Prophet too,<br/>How precious, Lord, art Thou;<br/>Thy worth to God, Thy worth to us,<br/>We all with love avow.<br/>O how we treasure what Thou art,<br/>Our hearts are drawn by Thee;<br/>To Thee we''ll give our thanks and praise<br/>Throughout eternity.<br/>',NULL,998,998);
INSERT INTO stanza VALUES('E194','1','Thou art God''s testimony, Lord,<br/>Much better than the law;<br/>The law in letter was engraved,<br/>In it Thy type men saw.<br/>A definition was the law,<br/>God''s picture to provide;<br/>But Thou art God''s reality,<br/>In Thee doth God abide.<br/>',NULL,999,999);
INSERT INTO stanza VALUES('E194','2','The ark of testimony too<br/>Was but a type of Thee;<br/>In it the law of God was placed,<br/>But God in Thee we see.<br/>The ark, in type, was made of wood<br/>And. overlaid with gold;<br/>It typifies Thee as a man,<br/>Who God in full doth hold.<br/>',NULL,1000,1000);
INSERT INTO stanza VALUES('E194','3','Thou art the tabernacle too,<br/>God''s holy dwelling place;<br/>Incarnate in the flesh Thou art,<br/>And full of truth and grace.<br/>God''s glory we behold in Thee,<br/>Thou art the Word divine;<br/>Thy words and deeds of love and light<br/>Do God in life define.<br/>',NULL,1001,1001);
INSERT INTO stanza VALUES('E194','4','The temple was a type of Thee;<br/>The house of God Thou art;<br/>God dwells in Thee, Himself to show,<br/>His fulness to impart.<br/>Though Thou by Satan wast destroyed<br/>And numbered with the dead,<br/>In resurrection Thou dost build<br/>A larger one instead.<br/>',NULL,1002,1002);
INSERT INTO stanza VALUES('E194','5','The city shows Thy fulness true,<br/>A figure of Thy Bride,<br/>The increase of Thyself in full,<br/>In whom Thou dost abide.<br/>In Thee is God, the light divine,<br/>The lamp in her art Thou;<br/>With Thee God shines thru her on all,<br/>His glory to avow.<br/>',NULL,1003,1003);
INSERT INTO stanza VALUES('E194','6','The tabernacle and the ark,<br/>The law within them stored,<br/>The temple and the city too,<br/>Are all Thyself, dear Lord.<br/>Thou art the hub, Thou art the rim,<br/>The all in all Thou art!<br/>In Thee we see both God and man,<br/>How precious to our heart!<br/>',NULL,1004,1004);
INSERT INTO stanza VALUES('E195','1','Lord, Thou art all the offerings<br/>Prepared by God for us;<br/>They are so rich in meaning,<br/>So sweet and glorious.<br/>They have fulfilled God''s purpose<br/>And met His heart''s desire;<br/>They too have satisfied us,<br/>And faced what we require.<br/>',NULL,1005,1005);
INSERT INTO stanza VALUES('E195','2','Thou art the burnt-oblation,<br/>Consumed by holy fire;<br/>To God as a sweet savor,<br/>Fulfilling His desire.<br/>Thou walkedst in God''s presence,<br/>And all His will pursued;<br/>Thyself the spotless offering,<br/>For us to God as food.<br/>',NULL,1006,1006);
INSERT INTO stanza VALUES('E195','3','Thou art the meal-oblation,<br/>With "oil" and "frankincense";<br/>''Tis holy, fine, and perfect,<br/>And sweet to every sense.''<br/>Thou art the peace-oblation,<br/>The peace for us to make,<br/>That we with God may share Thee,<br/>As food of Thee partake.<br/>',NULL,1007,1007);
INSERT INTO stanza VALUES('E195','4','Thou art the sin-oblation,<br/>For us Thou sin wast made;<br/>By death for our redemption<br/>The ransom Thou hast paid.<br/>Thou art the trespass-offering,<br/>Thou all our sins didst bear<br/>To satisfy God''s justice,<br/>That we His pardon share.<br/>',NULL,1008,1008);
INSERT INTO stanza VALUES('E195','5','Thou art the wave-oblation,<br/>The resurrected One;<br/>O''er Hades, death and darkness,<br/>The vict''ry Thou hast won.<br/>Thou art the heave-oblation,<br/>Thou didst ascend to God;<br/>As such in heav''nly places<br/>Thou art our holy food.<br/>',NULL,1009,1009);
INSERT INTO stanza VALUES('E196','1','Lord, the ancient types and symbols<br/>As our all Thyself portrayed;<br/>As was shadowed in those figures,<br/>Real to us Thou now art made.<br/>Contemplating such a picture,<br/>As we on its wonders gaze,<br/>How we marvel at Thy riches<br/>And our song of worship raise.<br/>',NULL,1010,1010);
INSERT INTO stanza VALUES('E196','2','Lord, Thou art our true Passover,<br/>God passed over us thru, Thee;<br/>By Thyself and Thy redemption<br/>We with God have harmony.<br/>Thou, the Lamb of God, redeemedst us<br/>With Thyself and with Thy blood;<br/>We apply Thy blood, our ransom,<br/>Eating Thee, our real food.<br/>',NULL,1011,1011);
INSERT INTO stanza VALUES('E196','3','Lord, Thou art the Bread from heaven,<br/>The unleavened Bread of life;<br/>Eating Thee, with Thee we mingle,<br/>Ceasing from our sin and strife.<br/>Lamb and Bread are both Thy figures,<br/>Showing Thou art life to us;<br/>Feasting on Thee at Thy table,<br/>We enjoy Thy riches thus.<br/>',NULL,1012,1012);
INSERT INTO stanza VALUES('E196','4','Lord, Thou art the Heav''nly Manna,<br/>As our daily food supply;<br/>Strengthening and energizing,<br/>All our need to satisfy.<br/>Living Rock Thou also art, Lord,<br/>Cleft for us with life to flow;<br/>Drinking of this living water,<br/>Thirst is quenched, Thy life we know.<br/>',NULL,1013,1013);
INSERT INTO stanza VALUES('E196','5','Lord, Thou art the Land of Canaan-<br/>Elevated, rich and good,<br/>Flowing with both milk and honey<br/>In a glorious plenitude.<br/>By Thy surplus God we worship,<br/>In Thy fellowship we move;<br/>Thus in love we''re joined together<br/>And God''s building we will prove.<br/>',NULL,1014,1014);
INSERT INTO stanza VALUES('E197','1','How all-inclusive, Lord, Thou art;<br/>Of God we are in Thee-<br/>The portion God prepared for us,<br/>Our all in all to be.<br/>',NULL,1015,1015);
INSERT INTO stanza VALUES('E197','2','Thou art to us God''s wisdom true,<br/>We all are saved through Thee;<br/>Thou art God''s only way to save,<br/>Thou art our only plea.<br/>',NULL,1016,1016);
INSERT INTO stanza VALUES('E197','3','Thou art to us our righteousness,<br/>All God requires to meet;<br/>In Thee we all are justified,<br/>In Thee we are complete.<br/>',NULL,1017,1017);
INSERT INTO stanza VALUES('E197','4','Thou art to us our holiness<br/>That we may be transformed;<br/>In Thee we all are sanctified,<br/>To Thee we''ll be conformed.<br/>',NULL,1018,1018);
INSERT INTO stanza VALUES('E197','5','Thou art to us redemption too,<br/>That we Thy likeness bear;<br/>Transfigured will our bodies be<br/>Thy liberty to share.<br/>',NULL,1019,1019);
INSERT INTO stanza VALUES('E197','6','Dear Lord, while we remember Thee,<br/>Enjoying all Thou art,<br/>We thus would hasten Thy return<br/>And ne''er from Thee depart.<br/>',NULL,1020,1020);
INSERT INTO stanza VALUES('E197','7','How sweet to have this foretaste here,<br/>A taste so wonderful,<br/>Yet still we fain would be with Thee,<br/>And share Thyself in full.<br/>',NULL,1021,1021);
INSERT INTO stanza VALUES('E198','1','Dear Lord, Thou art the Tree of Life,<br/>The very life supply;<br/>Thy fruits, replete with life divine,<br/>Our hunger satisfy.<br/>',NULL,1022,1022);
INSERT INTO stanza VALUES('E198','2','Thou art the true and heav''nly Vine,<br/>Our very source of life;<br/>By Thee we live, in Thee abide,<br/>And rest from all our strife.<br/>',NULL,1023,1023);
INSERT INTO stanza VALUES('E198','3','Dear Lord, Thou art the Apple Tree,<br/>Thyself we all en''oy;<br/>Thy fruits are sweet to all our taste,<br/>Thy shadow brings us joy.<br/>',NULL,1024,1024);
INSERT INTO stanza VALUES('E198','4','Thou art to us the healing Tree;<br/>Our death Thou didst endure;<br/>Thou on a tree for us wast slain,<br/>That we may have Thy cure.<br/>',NULL,1025,1025);
INSERT INTO stanza VALUES('E198','5','Thou art the very Branch of God,<br/>''His fulness dwells in Thee;<br/>In Thee we take of Him as grace<br/>And the reality.<br/>',NULL,1026,1026);
INSERT INTO stanza VALUES('E198','6','Lord, Thou art also David''s Branch<br/>Incarnate here to be;<br/>In Thee we see and comprehend<br/>The true humanity.<br/>',NULL,1027,1027);
INSERT INTO stanza VALUES('E198','7','Thou art the sprouting Rod with God,<br/>In Thee is endless life,<br/>Before Thy resurrection pow''r<br/>Death never can be rife.<br/>',NULL,1028,1028);
INSERT INTO stanza VALUES('E198','8','Thou also art the swimming Stick,<br/>The fallen "ax" are we;<br/>By Thine uplifting pow''r of life,<br/>From death we''re lifted free.<br/>',NULL,1029,1029);
INSERT INTO stanza VALUES('E198','9','Lord, Thou art such a "Plant of Fame,"<br/>Of Thee we richly share;<br/>As we are here remembering Thee,<br/>Thyself we thus declare!<br/>',NULL,1030,1030);
INSERT INTO stanza VALUES('E199','1','Thou art the Rock everlasting,<br/>Spiritual Rock cleft for me;<br/>Drinking of Thee as the Spirit,<br/>Thus I become one with Thee.<br/>Thou art the Rock never shaken,<br/>''Tis on this Rock we are built;<br/>Joined unto Thee thru redemption,<br/>Nothing can shake us thru guilt.<br/>',NULL,1031,1031);
INSERT INTO stanza VALUES('E199','chorus','Lord, how we treasure Thy value,<br/>All that Thou art is for us;<br/>While here in loving remembrance<br/>We share Thy wealth glorious.<br/>',NULL,1032,1032);
INSERT INTO stanza VALUES('E199','2','Thou art the Stone tried by many,<br/>Precious to God, dear to us,<br/>Thou art so sure and trustworthy,<br/>Thy strength is so marvelous.<br/>Thou art the Stone that is living,<br/>Chosen of God, made our own;<br/>So energetic and pow''rful,<br/>With endless life to us known.<br/>',NULL,1033,1033);
INSERT INTO stanza VALUES('E199','3','Thou art the Stone of Foundation<br/>Laid by our God, safe and sure;<br/>It is by this sure foundation<br/>Safety fore''er we secure.<br/>To us no other foundation<br/>Of any kind man can lay;<br/>Thou art the only foundation<br/>Which we have now and for aye.<br/>',NULL,1034,1034);
INSERT INTO stanza VALUES('E199','4','Lord, for God''s spiritual building,<br/>Thou art the Chief Cornerstone;<br/>Both of the Jews and the Gentiles<br/>By Thee are built into one.<br/>Lord, Thou art also the Topstone,<br/>Brought forth in measureless grace;<br/>Thou art our cover and glory,<br/>Moving our hearts in Thy praise.<br/>',NULL,1035,1035);
INSERT INTO stanza VALUES('E200','1','Thou art the Sun of righteousness<br/>With healing in Thy wings;<br/>The shining of Thy glorious face<br/>To us Thy riches brings.<br/>',NULL,1036,1036);
INSERT INTO stanza VALUES('E200','2','The tender mercy of our God<br/>Caused Thee on us to dawn,<br/>To those in darkness giving light<br/>That shades of death be gone.<br/>',NULL,1037,1037);
INSERT INTO stanza VALUES('E200','3','Thou art the Morning without clouds,<br/>And as the Morning Light;<br/>We are the tender grass on earth,<br/>Who in Thy rays delight.<br/>',NULL,1038,1038);
INSERT INTO stanza VALUES('E200','4','Thy shining light with pleasant rays<br/>Increases all the way;<br/>It shines within us more and more<br/>Until the perfect day.<br/>',NULL,1039,1039);
INSERT INTO stanza VALUES('E200','5','It shines thru woe with clearest beams,<br/>As shining after rain;<br/>And in Thy mercy with Thy love<br/>Thy shining e''er remains.<br/>',NULL,1040,1040);
INSERT INTO stanza VALUES('E200','6','Thou also art the Morning Star<br/>To us as a reward;<br/>While still ''tis dark it shines with light<br/>To those who love the Lord.<br/>',NULL,1041,1041);
INSERT INTO stanza VALUES('E200','7','Lord, help us e''er to love Thy light<br/>And see things from afar;<br/>And look for Thee in watch and prayer<br/>As for the Morning Star.<br/>',NULL,1042,1042);
INSERT INTO stanza VALUES('E201','1','O Lord, Thou art our Paraclete,<br/>Our Comforter indeed,<br/>Our Patron with our God above,<br/>The Advocate we need.<br/>',NULL,1043,1043);
INSERT INTO stanza VALUES('E201','2','Thou art our Counsel of defense,<br/>The Pleader of our case,<br/>Our Interceder for all things,<br/>Our Helper in all ways.<br/>',NULL,1044,1044);
INSERT INTO stanza VALUES('E201','3','Lord, Thou dost manage all affairs<br/>For us in God''s delight,<br/>Both in the heavens and in us<br/>With power in Thy right.<br/>',NULL,1045,1045);
INSERT INTO stanza VALUES('E201','4','Thou intercedest all the time,<br/>Lord Spirit, with Thy grace,<br/>In heav''n to plead, in us to groan,<br/>Entreating in our place.<br/>',NULL,1046,1046);
INSERT INTO stanza VALUES('E201','5','Thou helpest as the living One,<br/>And actest by God''s plan<br/>In resurrection pow''r of life,<br/>Empow''ring our inner man.<br/>',NULL,1047,1047);
INSERT INTO stanza VALUES('E201','6','Thou, as the Spirit giving life,<br/>In weakness dost sustain;<br/>And in our spirit with, Thy strength,<br/>Our being dost maintain.<br/>',NULL,1048,1048);
INSERT INTO stanza VALUES('E201','7','Thou servest ever with Thyself,<br/>In mercy and in love,<br/>That Thou may be our all in all,<br/>And we Thy fulness prove.<br/>',NULL,1049,1049);
INSERT INTO stanza VALUES('E202','1','O Lord, Thou art the Alpha<br/>And the Omega too;<br/>Thou art the First, before all,<br/>And art the Last so true.<br/>Thou art the sole Beginning,<br/>The only End of all;<br/>In Thee all is included,<br/>Creations great and small.<br/>',NULL,1050,1050);
INSERT INTO stanza VALUES('E202','2','Lord, since Thou art the Alpha,<br/>All things commenced of Thee;<br/>And as the sole Omega,<br/>All things will end in Thee;<br/>As God''s full, Alphabet, Lord,<br/>All is of Thee composed;<br/>Since Thou art all the letters,<br/>All is in Thee enclosed.<br/>',NULL,1051,1051);
INSERT INTO stanza VALUES('E202','3','As First of all the creatures,<br/>Thou art the Head of all;<br/>As Last in God''s creation,<br/>Thou art the close of all.<br/>As First of all the creatures,<br/>All things by Thee consist;<br/>As Last in God''s creation,<br/>All things for Thee subsist.<br/>',NULL,1052,1052);
INSERT INTO stanza VALUES('E202','4','Since Thou art the Beginning,<br/>Thou hast preceded all;<br/>And since Thou art the Ending,<br/>Thou wilt inherit all.<br/>Thou, the unique Beginning,<br/>Didst all originate;<br/>Thou, as the only Ending,<br/>Wilt all things terminate.<br/>',NULL,1053,1053);
INSERT INTO stanza VALUES('E202','5','O Lord, how we adore Thee<br/>And treasure Thee with love;<br/>As Alpha and Omega,<br/>Thou art all things above.<br/>We praise Thee, the Beginning,<br/>The very First we call;<br/>We worship Thee, the Ending,<br/>The only Last of all.<br/>',NULL,1054,1054);
INSERT INTO stanza VALUES('E203','1','In the bosom of the Father,<br/>Ere the ages had begun,<br/>Thou wast in the Father''s glory,<br/>God''s unique begotten Son.<br/>When to us the Father gave Thee,<br/>Thou in person wast the same,<br/>All the fulness of the Father<br/>In the Spirit to proclaim.<br/>',NULL,1055,1055);
INSERT INTO stanza VALUES('E203','2','By Thy death and resurrection,<br/>Thou wast made God''s firstborn Son;<br/>By Thy life to us imparting,<br/>Was Thy duplication done.<br/>We, in Thee regenerated,<br/>Many sons to God became;<br/>Truly as Thy many brethren,<br/>We are as Thyself the same.<br/>',NULL,1056,1056);
INSERT INTO stanza VALUES('E203','3','Once Thou wast the only grain, Lord,<br/>Falling to the earth to die,<br/>That thru death and resurrection<br/>Thou in life may multiply.<br/>We were brought forth in Thy nature<br/>And the many grains became;<br/>As one loaf we all are blended,<br/>All Thy fulness to proclaim.<br/>',NULL,1057,1057);
INSERT INTO stanza VALUES('E203','4','We''re Thy total reproduction,<br/>Thy dear Body and Thy Bride,<br/>Thine expression and Thy fulness,<br/>For Thee ever to abide.<br/>We are Thy continuation,<br/>Thy life-increase and Thy spread,<br/>Thy full growth and Thy rich surplus,<br/>One with Thee, our glorious Head.<br/>',NULL,1058,1058);
INSERT INTO stanza VALUES('E204','1','Gathered in Thy name, Lord Jesus,<br/>Losing sight of all but Thee,<br/>O what joy Thy presence gives us,<br/>Calling up our hearts to Thee!<br/>',NULL,1060,1060);
INSERT INTO stanza VALUES('E204','2','Loved with love which knows no measure,<br/>Save the Father''s love to Thee,<br/>Blessed Lord, our hearts would treasure<br/>All the Father''s thoughts of Thee.<br/>',NULL,1061,1061);
INSERT INTO stanza VALUES('E204','3','All His joy, His rest, His pleasure-<br/>All His deep delight in Thee-<br/>Lord, Thy heart alone can measure<br/>What Thy Father found in Thee.<br/>',NULL,1062,1062);
INSERT INTO stanza VALUES('E204','4','How He set His love upon Thee-<br/>Called Thee His beloved Son;<br/>Yet for us He did not spare Thee,<br/>By Thy death our life was won.<br/>',NULL,1063,1063);
INSERT INTO stanza VALUES('E204','5','O the joy, the wondrous singing,<br/>When we see Thee, as Thou art!<br/>Thy blest name, Lord Jesus, bringing<br/>Sweetest music to God''s heart.<br/>',NULL,1064,1064);
INSERT INTO stanza VALUES('E204','6','Notes of gladness, songs unceasing,<br/>Hymns of everlasting praise,<br/>Psalms of glory, joy increasing,<br/>Through God''s endless day of days.<br/>',NULL,1065,1065);
INSERT INTO stanza VALUES('E205','1','Jesus, Thou Joy of loving hearts,<br/>Thou Fount of life, Thou Light of men,<br/>From the best bliss that earth imparts,<br/>We turn unfilled to Thee again.<br/>',NULL,1066,1066);
INSERT INTO stanza VALUES('E205','2','Thy truth unchanged hath ever stood;<br/>Thou savest those that on Thee call;<br/>To them that seek Thee, Thou art good,<br/>To them that find Thee, all in all!<br/>',NULL,1067,1067);
INSERT INTO stanza VALUES('E205','3','We taste Thee, O Thou living Bread,<br/>And long to feast upon Thee still;<br/>We drink of Thee, the Fountain-head,<br/>And thirst our souls from Thee to fill!<br/>',NULL,1068,1068);
INSERT INTO stanza VALUES('E205','4','Our restless spirits yearn for Thee,<br/>Where''er our changeful lot is cast;<br/>Glad when Thy gracious smile we see,<br/>Blest, when our faith can hold Thee fast.<br/>',NULL,1069,1069);
INSERT INTO stanza VALUES('E205','5','O Lord, be Thou our strength and stay!<br/>Make all our moments calm and bright,<br/>Chase all dark thoughts of sin away,<br/>Shed o''er us here Thy holy light.<br/>',NULL,1070,1070);
INSERT INTO stanza VALUES('E206','1','O Christ He is the fountain,<br/>The deep, sweet well of life:<br/>Its living streams I''ve tasted<br/>Which save from grief and strife.<br/>And to an ocean fullness,<br/>His mercy doth expand;<br/>His grace is all-sufficient<br/>As by His wisdom planned.<br/>',NULL,1071,1071);
INSERT INTO stanza VALUES('E206','2','O I am my Beloved''s.<br/>And my Beloved''s mine;<br/>He brings a poor vile sinner<br/>Into His house of wine!<br/>I stand upon His merit;<br/>I know no other stand.<br/>I''m hidden in his presence<br/>And held by His own hand.<br/>',NULL,1072,1072);
INSERT INTO stanza VALUES('E206','3','The Bride eyes not her garment,<br/>But her dear Bridegroom''s face;<br/>I will not gaze at glory.<br/>But on my King of grace:<br/>Not at the crown He giveth,<br/>But on His pierced hand;<br/>The Lamb is all the glory,<br/>And my eternal stand!<br/>',NULL,1073,1073);
INSERT INTO stanza VALUES('E207','1','Lord Jesus! When we think of Thee,<br/>Of all Thy love and grace,<br/>Our spirits long and fain would see<br/>Thy beauty face to face.<br/>',NULL,1074,1074);
INSERT INTO stanza VALUES('E207','2','And though the wilderness we tread,<br/>A barren, thirsty ground,<br/>With thorns and briars overspread,<br/>Where foes and snares abound;<br/>',NULL,1075,1075);
INSERT INTO stanza VALUES('E207','3','Yet in Thy love such depths we see,<br/>Our hearts o''erflow with praise-<br/>Content ourselves, while, Lord to Thee<br/>A joyful song we raise.<br/>',NULL,1076,1076);
INSERT INTO stanza VALUES('E207','4','Our Lord, our Life, our Rest, our Shield,<br/>Our Rock, our Food, our Light;<br/>Each thought of Thee doth constant yield<br/>Unchanging, fresh delight.<br/>',NULL,1077,1077);
INSERT INTO stanza VALUES('E207','5','Blest Savior, keep our spirit stayed,<br/>Hard following after Thee,<br/>Till we, in victory displayed,<br/>Thy face in glory see.<br/>',NULL,1078,1078);
INSERT INTO stanza VALUES('E208','1','O Jesus, Jesus, dearest Lord!<br/>Forgive me if I say,<br/>For very love, Thy sacred name<br/>A thousand times a day.<br/>',NULL,1079,1079);
INSERT INTO stanza VALUES('E208','chorus','O Jesus, Lord, with me abide;<br/>I rest in Thee, whate''er betide;<br/>Thy gracious smile is my reward;<br/>I love, I love Thee, Lord!<br/>',NULL,1080,1080);
INSERT INTO stanza VALUES('E208','2','I love Thee so I know not how<br/>My transports to control;<br/>Thy love is like a burning fire<br/>Within my very soul.<br/>',NULL,1081,1081);
INSERT INTO stanza VALUES('E208','3','For Thou to me art all in all;<br/>My honor and my wealth;<br/>My heart''s desire, my body''s strength,<br/>My soul''s eternal health.<br/>',NULL,1082,1082);
INSERT INTO stanza VALUES('E208','4','Burn, burn, O love, within my heart,<br/>Burn fiercely night and day,<br/>Till all the dross of earthly loves<br/>Is burned, and burned away.<br/>',NULL,1083,1083);
INSERT INTO stanza VALUES('E208','5','O light in darkness, joy in grief,<br/>O heaven''s life on earth;<br/>Jesus, my love, my treasure, who<br/>Can tell what Thou art worth?<br/>',NULL,1084,1084);
INSERT INTO stanza VALUES('E208','6','What limit is there to this love?<br/>Thy flight, where wilt Thou stay?<br/>On, on! Our Lord is sweeter far<br/>Today than yesterday.<br/>',NULL,1085,1085);
INSERT INTO stanza VALUES('E209','1','Jesus, the very thought of Thee<br/>With sweetness fills my breast;<br/>But sweeter far Thy face to see,<br/>And in Thy presence rest.<br/>',NULL,1086,1086);
INSERT INTO stanza VALUES('E209','2','Nor voice can sing, nor heart can frame,<br/>Nor can the memory find<br/>A sweeter sound than Thy blest Name,<br/>O Savior of mankind!<br/>',NULL,1087,1087);
INSERT INTO stanza VALUES('E209','3','O Hope of every contrite heart,<br/>O Joy of all the meek,<br/>To those who fall, how kind Thou art!<br/>How good to those who seek!<br/>',NULL,1088,1088);
INSERT INTO stanza VALUES('E209','4','But what to those who find? Ah, this<br/>Nor tongue nor pen can show;<br/>The love of Jesus, what it is<br/>None but His loved ones know.<br/>',NULL,1089,1089);
INSERT INTO stanza VALUES('E209','5','O Jesus! Light of all below!<br/>Thou fount of life and fire!<br/>Surpassing all the joys we know,<br/>And all we can desire.<br/>',NULL,1090,1090);
INSERT INTO stanza VALUES('E209','6','No other source have we but Thee,<br/>Soul-thirst to satisfy.<br/>Exhaustless spring! The waters free!<br/>All other streams are dry.<br/>',NULL,1091,1091);
INSERT INTO stanza VALUES('E209','7','Jesus, our only Joy be Thou,<br/>As Thou our Prize wilt be;<br/>Jesus, be Thou our Glory now,<br/>And through eternity.<br/>',NULL,1092,1092);
INSERT INTO stanza VALUES('E210','1','I''ve found a friend in Jesus, He''s everything to me,<br/>He''s the fairest of ten thousand to my soul;<br/>The Apple-tree of trees, in Him alone I see<br/>All I need to cleanse and make me fully whole.<br/>In sorrow He''s my comfort, in trouble He''s my stay,<br/>He tells me every care on Him to roll:<br/>He''s the Apple-tree of trees, the Bright and Morning Star,<br/>He''s the fairest of ten thousand to my soul.<br/>',NULL,1093,1093);
INSERT INTO stanza VALUES('E210','2','He all my griefs has taken, and all my sorrows borne;<br/>In temptation He''s my strong and mighty tower;<br/>I''ve all for Him forsaken, and all my idols torn<br/>From my heart, and now He keeps me by His power.<br/>Though all the world forsake me, and Satan tempt me sore,<br/>Through Jesus I shall safely reach the goal:<br/>He''s the Apple-tree of trees, the Bright and Morning Star,<br/>He''s the fairest of ten thousand to my soul.<br/>',NULL,1094,1094);
INSERT INTO stanza VALUES('E210','3','He''ll never, never leave me, nor yet forsake me here,<br/>While I live by faith and do His blessed will;<br/>A wall of fire about me, I''ve nothing now to fear,<br/>With His manna He my hungry soul shall fill.<br/>Then sweeping up to glory to see His blessed face,<br/>Where rivers of delight shall ever roll:<br/>He''s the Apple-tree of trees, the Bright and Morning Star,<br/>He''s the fairest of ten thousand to my soul.<br/>',NULL,1095,1095);
INSERT INTO stanza VALUES('E211','1','Jesus, my Savior! Thou art mine,<br/>The Father''s gift of love divine;<br/>All Thou hast done, and all Thou art,<br/>Are now the portion of my heart.<br/>',NULL,1096,1096);
INSERT INTO stanza VALUES('E211','2','Poor, feeble, wretched, as I am,<br/>I now can glory in Thy name;<br/>Now cleansed in Thy most precious blood<br/>And made the righteousness of God.<br/>',NULL,1097,1097);
INSERT INTO stanza VALUES('E211','3','All that Thou hast Thou hast for me,<br/>All my fresh springs are hid in Thee;<br/>In Thee I live; while I confess<br/>I nothing am, yet all possess.<br/>',NULL,1098,1098);
INSERT INTO stanza VALUES('E211','4','O Savior, teach me to abide<br/>Close sheltered at Thy wounded side,<br/>Each hour receiving "grace on grace"<br/>Until I see Thee face to face.<br/>',NULL,1099,1099);
INSERT INTO stanza VALUES('E212','1','Lord Jesus, gladly do our lips express<br/>Our heart''s deep sense of all Thy worthiness;<br/>Thou risen One, the Holy and the True,<br/>We give Thee now the praise so justly due.<br/>',NULL,1100,1100);
INSERT INTO stanza VALUES('E212','2','Thou giv''st us, Lord, once more to taste down here<br/>The joy Thy presence brings, its warmth and cheer;<br/>With great delight we ''neath Thy shadow rest;<br/>Thy fruit is sweet to those Thy love has blest.<br/>',NULL,1101,1101);
INSERT INTO stanza VALUES('E212','3','Thou wast alone, till like the precious grain<br/>In death Thou layest, but didst rise again;<br/>And in Thy risen life a countless host<br/>Are "all of one" with Thee, Thy joy and boast.<br/>',NULL,1102,1102);
INSERT INTO stanza VALUES('E213','1','On that same night, Lord Jesus,<br/>When all around Thee joined<br/>To cast its darkest shadow<br/>Across Thy holy mind,<br/>We hear Thy voice, blest Savior,<br/>"This do, remember me",<br/>With grateful hearts responding,<br/>We do remember Thee.<br/>',NULL,1103,1103);
INSERT INTO stanza VALUES('E213','2','The depth of all Thy suffering<br/>No heart could e''er conceive,<br/>The cup of wrath o''erflowing<br/>For us Thou didst receive;<br/>And, oh, of God forsaken<br/>On the accursed tree;<br/>With grateful hearts, Lord Jesus,<br/>We now remember Thee.<br/>',NULL,1104,1104);
INSERT INTO stanza VALUES('E213','3','We think of all the darkness<br/>Which round Thy spirit pressed,<br/>Of all those waves and billows,<br/>Which rolled across Thy breast.<br/>Oh, there Thy grace unbounded<br/>And perfect love we see;<br/>With joy and sorrow mingling,<br/>We would remember Thee.<br/>',NULL,1105,1105);
INSERT INTO stanza VALUES('E213','4','We know Thee now as risen,<br/>The Firstborn from the dead;<br/>We see Thee now ascended,<br/>The Church''s glorious Head.<br/>In Thee by grace accepted,<br/>The heart and mind set free<br/>To think of all Thy sorrow,<br/>And thus remember Thee.<br/>',NULL,1106,1106);
INSERT INTO stanza VALUES('E213','5','Till Thou shalt come in glory,<br/>And call us hence away,<br/>To rest in all the brightness<br/>Of that unclouded day,<br/>We show Thy death, Lord Jesus,<br/>And here would seek to be<br/>More to Thy death conformed,<br/>While we remember Thee.<br/>',NULL,1107,1107);
INSERT INTO stanza VALUES('E214','1','According to Thy gracious word,<br/>In meek humility,<br/>This will I do, my dying Lord,<br/>I will remember Thee.<br/>',NULL,1108,1108);
INSERT INTO stanza VALUES('E214','2','Thy body, broken for my sake,<br/>My bread from heaven shall be;<br/>Thy testamental cup I take,<br/>And thus remember Thee.<br/>',NULL,1109,1109);
INSERT INTO stanza VALUES('E214','3','Gethsemane can I forget?<br/>Or there Thy conflict see,<br/>Thine agony and bloody sweat,<br/>And not remember Thee?<br/>',NULL,1110,1110);
INSERT INTO stanza VALUES('E214','4','When to the cross I turn mine eyes<br/>And rest on Calvary,<br/>O Lamb of God, my sacrifice,<br/>I must remember Thee-<br/>',NULL,1111,1111);
INSERT INTO stanza VALUES('E214','5','Remember Thee and all Thy pains<br/>And all Thy love to me;<br/>Yea, while a breath, a pulse remains,<br/>I will remember Thee.<br/>',NULL,1112,1112);
INSERT INTO stanza VALUES('E214','6','And when these failing lips grow dumb<br/>And mind and memory flee,<br/>When Thou shalt in Thy kingdom come,<br/>Jesus, remember me.<br/>',NULL,1113,1113);
INSERT INTO stanza VALUES('E215','1','Jesus, Lord, we know Thee present<br/>At Thy table freshly spread,<br/>Seated at Thy priceless banquet<br/>With Thy banner overhead.<br/>Precious moments at Thy table,<br/>From all fear and doubt set free;<br/>Here to rest, so sweetly able,<br/>Occupied alone with Thee.<br/>',NULL,1114,1114);
INSERT INTO stanza VALUES('E215','2','Here rejoicing in Thy nearness,<br/>Gladly by Thy Spirit led;<br/>Calmly in the blest remembrance<br/>Of Thyself, Thy blood once shed.<br/>Lord, we take each simple token<br/>In fond memory of Thee,<br/>Muse upon Thy body broken<br/>And Thy blood shed on the tree.<br/>',NULL,1115,1115);
INSERT INTO stanza VALUES('E215','3','Oh, what joy it is to see Thee,<br/>In these chosen emblems here;<br/>In the bread and wine of blessing-<br/>Bread to strengthen, wine to cheer!<br/>Lord, behold us met together,<br/>One in Thee, our risen Head,<br/>Thus we take the cup of blessing,<br/>Thus we share the broken bread.<br/>',NULL,1116,1116);
INSERT INTO stanza VALUES('E215','4','Lord, we know how true Thy promise<br/>To be with us where we meet,<br/>When in Thy loved name we gather<br/>To enjoy communion sweet;<br/>Dearer still that looked-for promise<br/>To each waiting, yearning heart,<br/>That with Thee we soon shall be, Lord,<br/>Yes, "forever" where Thou art.<br/>',NULL,1117,1117);
INSERT INTO stanza VALUES('E216','1','Around Thy table, holy Lord,<br/>In fellowship we meet,<br/>Obedient to Thy gracious word,<br/>This feast of love to eat.<br/>',NULL,1118,1118);
INSERT INTO stanza VALUES('E216','2','Here every one that loves Thy name,<br/>Our willing hearts embrace;<br/>Our source of life and hope the same,<br/>All debtors to Thy grace.<br/>',NULL,1119,1119);
INSERT INTO stanza VALUES('E216','3','Commune with each at this blest hour,<br/>Thy peace, Thy joy impart;<br/>Thy thoughts of love, of truth, of pow''r,<br/>Impress upon each heart.<br/>',NULL,1120,1120);
INSERT INTO stanza VALUES('E217','1','On that night of nights most solemn,<br/>Jesus call His own<br/>''Round the table of remembrance,<br/>All alone.<br/>',NULL,1121,1121);
INSERT INTO stanza VALUES('E217','2','Then this feast of feasts He ordered,<br/>Feast of grace Divine;<br/>Sacred symbols He appointed,<br/>Bread and wine.<br/>',NULL,1122,1122);
INSERT INTO stanza VALUES('E217','3','Thus His death of deaths is shadowed<br/>In this simple way,<br/>Looking backward, pointing upward,<br/>To that day.<br/>',NULL,1123,1123);
INSERT INTO stanza VALUES('E217','4','Till the morn of morns bright dawning,<br/>Earth''s dark shadows passed;<br/>And the splendor of God''s glory<br/>Breaks at last.<br/>',NULL,1124,1124);
INSERT INTO stanza VALUES('E217','5','Thus the day of days shall open,<br/>Deathless, cloudless, fair;<br/>In that day, the Savior''s glories<br/>We shall share!<br/>',NULL,1125,1125);
INSERT INTO stanza VALUES('E218','1','As gathered in Thy precious name,<br/>This table we surround,<br/>Thy death, Lord Jesus, to proclaim,<br/>O may our praise abound.<br/>',NULL,1126,1126);
INSERT INTO stanza VALUES('E218','2','We give what from Thee we receive,<br/>For all we have is Thine-<br/>O may each heart with joy believe,<br/>And echo "Thine is mine!"<br/>',NULL,1127,1127);
INSERT INTO stanza VALUES('E218','3','Grace, grace it was that brought Thee down;<br/>Love shone in all Thy ways;<br/>Through death Thine is the Victor''s crown,<br/>And Thine the endless praise.<br/>',NULL,1128,1128);
INSERT INTO stanza VALUES('E218','4','We, here, in silence, or in song,<br/>Together worship Thee;<br/>Before our God we shall ere long<br/>Give praise eternally.<br/>',NULL,1129,1129);
INSERT INTO stanza VALUES('E218','5','Lord Jesus Christ, Thou comest soon-<br/>Today Thy death we show;<br/>In light, eclipsing sun at noon,<br/>Its myst''ry we shall know.<br/>',NULL,1130,1130);
INSERT INTO stanza VALUES('E219','1','Lord Jesus Christ, we would remember Thee,<br/>As, on the table, we the emblems see;<br/>Thy holy body shadowed in the bread,<br/>Thy precious blood is in the cup portrayed.<br/>',NULL,1131,1131);
INSERT INTO stanza VALUES('E219','2','Lord, we adore Thee for Thy matchless grace,<br/>That Thou, for us, didst take the servant''s place;<br/>From Godhead''s glory to the shameful tree,<br/>From wealth, so vast, to abject poverty!<br/>',NULL,1132,1132);
INSERT INTO stanza VALUES('E219','3','O Lamb of God, we join to bless Thy name,<br/>That Thou, on Calv''ry, bore our sin and shame;<br/>And, by Thy death, didst put our guilt away,<br/>Triumphant rose, our night to turn to day.<br/>',NULL,1133,1133);
INSERT INTO stanza VALUES('E219','4','We see Thee now, at God''s right hand enthroned,<br/>Vested with honor and with glory crowned;<br/>Blessed Redeemer, Savior, Lord, to Thee<br/>Be all the glory, pow''r and majesty!<br/>',NULL,1134,1134);
INSERT INTO stanza VALUES('E220','1','When on Thy table, Lord, we gaze,<br/>We marvel at the signs:<br/>A loaf of bread, a cup of wine,<br/>Displayed as God designs.<br/>',NULL,1135,1135);
INSERT INTO stanza VALUES('E220','2','The loaf portrays the bread of life<br/>As heav''nly food to us,<br/>Imparted by Thy mystic death<br/>That we may share Thee thus.<br/>',NULL,1136,1136);
INSERT INTO stanza VALUES('E220','3','The portion is the cup divine,<br/>Composed of Jesus'' blood;<br/>This cup of blessing we receive<br/>And gain what is of God.<br/>',NULL,1137,1137);
INSERT INTO stanza VALUES('E220','4','We eat of Thee, the Bread of life,<br/>By sharing here this bread;<br/>Thus we remember Thee in love<br/>And with Thyself are fed.<br/>',NULL,1138,1138);
INSERT INTO stanza VALUES('E220','5','We all enjoy the blessings gained<br/>By drinking of this cup;<br/>Thus we remember Thee with joy,<br/>Till we are taken up.<br/>',NULL,1139,1139);
INSERT INTO stanza VALUES('E220','6','By feasting on this bread and cup<br/>Thy death we now declare,<br/>And testify Thou art our life<br/>And all we daily share.<br/>',NULL,1140,1140);
INSERT INTO stanza VALUES('E220','7','We''re waiting for that glorious hour,<br/>When in the fullest way<br/>We''ll feed on Thee and feast with Thee<br/>And worship Thee for aye.<br/>',NULL,1141,1141);
INSERT INTO stanza VALUES('E221','1','Lord, we thank Thee for the table,<br/>With the bread and with the wine;<br/>At this table we enjoy Thee<br/>As the feast of love divine.<br/>We partake the bread, the emblem<br/>Of Thy body giv''n for us;<br/>And we share the wine, the symbol<br/>Of Thy blood Thou shedd''st for us.<br/>',NULL,1142,1142);
INSERT INTO stanza VALUES('E221','chorus','Lo, the holy table!<br/>With the sacred symbols;<br/>Its significance in figure<br/>Is unsearchable!<br/>',NULL,1143,1143);
INSERT INTO stanza VALUES('E221','2','By the death of Thy redemption,<br/>That Thy life Thou may impart,<br/>E''en Thyself to us Thou gavest<br/>That we share in all Thou art.<br/>By the bread and wine partaking,<br/>We Thy death display and prove;<br/>Eating, drinking of Thyself, Lord,<br/>We remember Thee with love.<br/>',NULL,1144,1144);
INSERT INTO stanza VALUES('E221','3','By this bread which signifieth<br/>Thy one body mystical,<br/>We commune with all Thy members<br/>In one bond identical.<br/>By this holy cup of blessing,<br/>Cup of wine which now we bless,<br/>Of Thy blood we have communion<br/>With all those who faith possess.<br/>',NULL,1145,1145);
INSERT INTO stanza VALUES('E221','4','Thou art our eternal portion,<br/>Here we take a sweet foretaste;<br/>We are waiting for Thy kingdom,<br/>And Thy coming now we haste.<br/>At Thy coming, in Thy kingdom,<br/>With all saints that overcome,<br/>We anew will feast upon Thee<br/>And Thy loving Bride become.<br/>',NULL,1146,1146);
INSERT INTO stanza VALUES('E222','1','Dear Lord, we thank Thee for this bread,<br/>It is a sign divine;<br/>In it we see the mysteries<br/>Of God''s unique design.<br/>',NULL,1147,1147);
INSERT INTO stanza VALUES('E222','2','This bread Thy body signifies,<br/>Which Thou hast giv''n for us,<br/>That we may share Thy life divine,<br/>Partaking of Thee thus.<br/>',NULL,1148,1148);
INSERT INTO stanza VALUES('E222','3','For us Thy body Thou didst break<br/>That Thou may thus impart<br/>Thyself as life to us that we<br/>May be Thy counterpart.<br/>',NULL,1149,1149);
INSERT INTO stanza VALUES('E222','4','This bread thus also signifies<br/>Thy body mystical,<br/>Of which we living members are,<br/>With Thee identical.<br/>',NULL,1150,1150);
INSERT INTO stanza VALUES('E222','5','Though we are many grains of wheat,<br/>Yet all one loaf, one bread;<br/>Remembering Thee in such a way,<br/>With Thee we all are fed.<br/>',NULL,1151,1151);
INSERT INTO stanza VALUES('E222','6','As of this bread we all commune,<br/>Thou, Lord, dost satisfy,<br/>With all the saints we fellowship,<br/>And Thee we testify.<br/>',NULL,1152,1152);
INSERT INTO stanza VALUES('E223','1','On the table of Thy love,<br/>With the bread the cup is spread.<br/>By partaking of these signs,<br/>We with Thee are richly fed.<br/>How we thank Thee for this cup,<br/>For the cup of blessing, Lord,<br/>Cup of Thy Salvation full,<br/>Cup of all Thou dost afford.<br/>',NULL,1153,1153);
INSERT INTO stanza VALUES('E223','2','''Tis the blood Thou shedd''st for us,<br/>That our sins may be forgiv''n;<br/>''Tis the cov''nant made for us,<br/>That Thy blessings may be giv''n.<br/>Thou didst drink the cup of wrath,<br/>Thou hast tasted death for us,<br/>Thus the cup of blessing bought,<br/>As the portion gained for us.<br/>',NULL,1154,1154);
INSERT INTO stanza VALUES('E223','3','In this portion we have God,<br/>Whom we lost thru Adam''s fall;<br/>By the shedding of Thy blood,<br/>God becomes our all in all.<br/>In this portion all we have-<br/>Life and peace, redemption sure;<br/>All that God has planned and willed,<br/>In this portion we secure.<br/>',NULL,1155,1155);
INSERT INTO stanza VALUES('E223','4','An eternal portion, ''tis,<br/>Overflowing cup divine;<br/>Heav''nly taste do we enjoy<br/>In this cup of God''s design.<br/>Here in love we drink this cup<br/>In remembrance, Lord, of Thee;<br/>Thus in spirit we partake<br/>All Thy work on Calvary.<br/>',NULL,1156,1156);
INSERT INTO stanza VALUES('E224','1','As we''re sharing of the cup,<br/>How can we restrain our praise;<br/>For the blood Thou shedd''st for us,<br/>Worth of which none can appraise.<br/>O how precious is Thy blood!<br/>All our problems it resolves;<br/>In Thine efficacious blood<br/>All our care and fear dissolves.<br/>',NULL,1157,1157);
INSERT INTO stanza VALUES('E224','2','It is by this blood of worth<br/>The new testament was made;<br/>For this better covenant,<br/>''Tis a sure foundation laid.<br/>We have been redeemed by God,<br/>Not with silver or with gold,<br/>But, Lord, with Thy precious blood,<br/>Which Thy love doth e''er unfold.<br/>',NULL,1158,1158);
INSERT INTO stanza VALUES('E224','3','For remission of our sins<br/>Thou hast shed Thy cleansing blood,<br/>Which for us has fully met<br/>All the righteous claims of God.<br/>Thou has washed us from our sins<br/>In Thy pow''rful purging blood:<br/>And our conscience purged by it,<br/>Thus to serve the living God.<br/>',NULL,1159,1159);
INSERT INTO stanza VALUES('E224','4','By Thy separating blood,<br/>We have all been sanctified;<br/>''Tis by Thy preserving blood<br/>Holiness is testified.<br/>By Thy propitiating blood,<br/>We have all been justified;<br/>''Tis by Thy redeeming blood<br/>God is fully satisfied.<br/>',NULL,1160,1160);
INSERT INTO stanza VALUES('E224','5','Thru Thy blood shed on the cross,<br/>We are reconciled to God,<br/>That the way to contact Him<br/>May in peace by us be trod.<br/>By partaking of Thy blood,<br/>We have Thine eternal life;<br/>In Thy blood and life received,<br/>We have rest, free from all strife.<br/>',NULL,1161,1161);
INSERT INTO stanza VALUES('E224','6','Now, in heav''n Thy sprinkled blood<br/>Speaks for us, of better things;<br/>Under its defending pow''r<br/>We are kept from Satan''s stings.<br/>By Thine overcoming blood,<br/>We defeat the enemy;<br/>Over our accuser thus,<br/>We will have the victory.<br/>',NULL,1162,1162);
INSERT INTO stanza VALUES('E224','7','Of Thy blood, for fellowship,<br/>We commune with all the saints;<br/>Under its full covering,<br/>Our freed spirit never faints.<br/>How can we exhaust, in words,<br/>The account of Thy dear blood;<br/>We will need eternity<br/>To declare its boundless good.<br/>',NULL,1163,1163);
INSERT INTO stanza VALUES('E225','1','Here, O my Lord, I see Thee face to face;<br/>Here faith can touch and handle things unseen;<br/>Here would I grasp with firmer hand Thy grace,<br/>And all my weariness upon Thee lean.<br/>',NULL,1164,1164);
INSERT INTO stanza VALUES('E225','2','Here would I feed upon the Bread of God;<br/>Here drink with Thee the royal wine of heav''n;<br/>Here would I lay aside each earthly load;<br/>Here taste afresh the calm of sin forgiv''n.<br/>',NULL,1165,1165);
INSERT INTO stanza VALUES('E225','3','I have no help but Thine; nor do I need<br/>Another arm save Thine to lean upon;<br/>It is enough, my Lord, enough indeed;<br/>My strength is in Thy might, Thy might alone.<br/>',NULL,1166,1166);
INSERT INTO stanza VALUES('E225','4','This is the hour of banquet and of song;<br/>This is the heav''nly table spread for me;<br/>Here let me feast, and, feasting, still prolong<br/>The brief bright hour of fellowship with Thee.<br/>',NULL,1167,1167);
INSERT INTO stanza VALUES('E225','5','Too soon we rise; the symbols disappear;<br/>The feast, though not the love, is past and gone;<br/>The bread and wine remove, but Thou art here,<br/>Nearer than ever still our Shield and Sun.<br/>',NULL,1168,1168);
INSERT INTO stanza VALUES('E225','6','Feast after feast thus comes and passes by,<br/>Yet passing, points to the glad feast above,<br/>Giving sweet foretastes of the festal joy,<br/>The Lamb''s great bridal-feast of bliss and love.<br/>',NULL,1169,1169);
INSERT INTO stanza VALUES('E226','1','For the bread and for the wine,<br/>For the pledge that seals Him mine,<br/>For the words of love divine,<br/>We give Thee thanks, O Lord.<br/>',NULL,1170,1170);
INSERT INTO stanza VALUES('E226','2','Only bread and only wine,<br/>Yet to faith, the solemn sign<br/>Of the heav''nly and divine!<br/>We give Thee thanks, O Lord.<br/>',NULL,1171,1171);
INSERT INTO stanza VALUES('E226','3','For the words that turn our eye<br/>To the cross of Calvary,<br/>Bidding us in faith draw nigh,<br/>We give Thee thanks, O Lord.<br/>',NULL,1172,1172);
INSERT INTO stanza VALUES('E226','4','For the words that fragrance breathe<br/>These plain symbols underneath,<br/>Words that His own peace bequeath,<br/>We give Thee thanks, O Lord.<br/>',NULL,1173,1173);
INSERT INTO stanza VALUES('E226','5','For Thy words in Spirit shown,<br/>For Thy will to us made known,<br/>"Do ye this until I come,"<br/>We give Thee thanks, O Lord.<br/>',NULL,1174,1174);
INSERT INTO stanza VALUES('E226','6','Till He come we take the bread,<br/>Type of Him on whom we feed,<br/>Him who liveth and was dead!<br/>We give Thee thanks, O Lord.<br/>',NULL,1175,1175);
INSERT INTO stanza VALUES('E226','7','Till He come we take the cup;<br/>As we at His table sup,<br/>Eye and heart are lifted up!<br/>We give Thee thanks, O Lord.<br/>',NULL,1176,1176);
INSERT INTO stanza VALUES('E226','8','For that coming, here foreshown,<br/>For that day to man unknown,<br/>For the glory and the throne,<br/>We give Thee thanks, O Lord.<br/>',NULL,1177,1177);
INSERT INTO stanza VALUES('E227','1','Through the bread and cup, Lord Jesus,<br/>We Thy death exhibit here;<br/>What Thy love has done reviewing,<br/>All Thy suff''ring we revere.<br/>Bread and cup in separation,<br/>Show that Thou thru death hast gone;<br/>Grateful now, our spirit worships,<br/>And to Thee we give our song.<br/>',NULL,1178,1178);
INSERT INTO stanza VALUES('E227','chorus','Thine the cup of suff''ring,<br/>Mine the cup of blessing;<br/>For Thy love in Thy redemption,<br/>Praise we ever sing!<br/>',NULL,1179,1179);
INSERT INTO stanza VALUES('E227','2','Thou, in love, hast shed Thy blood, Lord,<br/>Bringing us to God in grace,<br/>That from God, no longer severed,<br/>We may ever see His face.<br/>All God''s righteousness and glory<br/>Have been fully satisfied;<br/>Thru Thy death''s abundant merit<br/>We may now with God abide.<br/>',NULL,1180,1180);
INSERT INTO stanza VALUES('E227','3','By Thy death the veil was riven,<br/>Opened was the holiest place,<br/>All the barriers have been broken;<br/>We approach the throne of grace,<br/>There receiving grace and mercy,<br/>Thus the timely need to meet,<br/>Drinking as of living water,<br/>Tasting God Himself replete.<br/>',NULL,1181,1181);
INSERT INTO stanza VALUES('E227','4','Thou in grace hast so redeemed us,<br/>We the priests may be fore''er<br/>To fulfill that holy office,<br/>All God''s sweetness thus to share.<br/>Such a blessing, such a mercy,<br/>From Thy death for us ensue;<br/>We would ever Thee remember<br/>Till with Thee we drink anew.<br/>',NULL,1182,1182);
INSERT INTO stanza VALUES('E228','1','Sweet feast of love divine!<br/>''Tis grace that makes us free<br/>To feed upon this bread and wine,<br/>In mem''ry, Lord, of Thee.<br/>',NULL,1183,1183);
INSERT INTO stanza VALUES('E228','2','Here every welcome guest<br/>Waits, Lord, from Thee to learn<br/>The secrets of Thy Father''s breast,<br/>And all Thy grace discern.<br/>',NULL,1184,1184);
INSERT INTO stanza VALUES('E228','3','Here conscience ends its strife,<br/>And faith delights to prove<br/>The sweetness of the Bread of Life,<br/>The fulness of Thy love.<br/>',NULL,1185,1185);
INSERT INTO stanza VALUES('E228','4','That blood that flowed for sin<br/>In symbol here we see,<br/>And feel the blessed pledge within<br/>That we are loved of Thee.<br/>',NULL,1186,1186);
INSERT INTO stanza VALUES('E228','5','O if this glimpse of love<br/>Is so divinely sweet,<br/>What will it be, O Lord, above,<br/>Thy gladd''ning smile to meet!<br/>',NULL,1187,1187);
INSERT INTO stanza VALUES('E228','6','To see Thee face to face,<br/>Thy perfect likeness wear,<br/>And all Thy ways of wondrous grace<br/>Through endless years declare.<br/>',NULL,1188,1188);
INSERT INTO stanza VALUES('E229','1','Gathered round Thyself, Lord Jesus,<br/>We now seek Thy face;<br/>May we know Thy presence with us,<br/>Lord of grace!<br/>',NULL,1189,1189);
INSERT INTO stanza VALUES('E229','2','Love divine first drew us to Thee,<br/>In our sin and need;<br/>For our sin, in deep compassion,<br/>Thou didst bleed.<br/>',NULL,1190,1190);
INSERT INTO stanza VALUES('E229','3','Risen Lord, in glory seated,<br/>We are one with Thee;<br/>Thou hast snapt the chains that bound us,<br/>We are free.<br/>',NULL,1191,1191);
INSERT INTO stanza VALUES('E229','4','Gratefully we Thee remember<br/>As we break the bread,<br/>Symbol of Thy body given<br/>In our stead.<br/>',NULL,1192,1192);
INSERT INTO stanza VALUES('E229','5','Drink we too "the cup of blessing"<br/>Which Thy love has filled;<br/>Through Thy blood we have redemption<br/>Fears are stilled.<br/>',NULL,1193,1193);
INSERT INTO stanza VALUES('E229','6','Backward look we, drawn to Calv''ry,<br/>Musing while we sing;<br/>Forward haste we to Thy coming,<br/>Lord and King!<br/>',NULL,1194,1194);
INSERT INTO stanza VALUES('E230','1','Lord Jesus, in Thy precious name,<br/>And in that name alone;<br/>At Thy request we gladly meet,<br/>Thy Lordship here would own.<br/>',NULL,1195,1195);
INSERT INTO stanza VALUES('E230','2','As on that dark betrayal night,<br/>Thou didst this feast ordain;<br/>We too, the bread and cup would take,<br/>Thy death, Lord, thus proclaim.<br/>',NULL,1196,1196);
INSERT INTO stanza VALUES('E230','3','The bread, Thy body doth portray;<br/>The cup, Thy precious blood;<br/>By which our sin was put away,<br/>Our peace was made with God.<br/>',NULL,1197,1197);
INSERT INTO stanza VALUES('E230','4','The Host art Thou, Our blessed Lord,<br/>Thy honored guest are we;<br/>With grateful and adoring hearts<br/>We would remember Thee!<br/>',NULL,1198,1198);
INSERT INTO stanza VALUES('E230','5','Lord Jesus, whom unseen we love,<br/>As thus we muse on Thee;<br/>We none would see, save Thee alone,<br/>Thou Man of Calvary!<br/>',NULL,1199,1199);
INSERT INTO stanza VALUES('E231','1','Amidst us our Beloved stands,<br/>And bids us view His pierced hands;<br/>Points to the wounded feet and side,<br/>Blest emblems of the Crucified.<br/>',NULL,1200,1200);
INSERT INTO stanza VALUES('E231','2','What food luxurious loads the board<br/>When, at His table, sits the Lord!<br/>The wine how rich, the bread how sweet,<br/>When Jesus deigns the guests to meet!<br/>',NULL,1201,1201);
INSERT INTO stanza VALUES('E231','3','If now, with eyes defiled and dim,<br/>We see the signs, but see not Him;<br/>Oh, may His love the scales displace,<br/>And bid us see Him face to face!<br/>',NULL,1202,1202);
INSERT INTO stanza VALUES('E231','4','Thou glorious Bridegroom of our hearts,<br/>Thy present smile Thy grace imparts!<br/>Oh, lift the veil, if veil there be,<br/>Let every saint Thy glory see!<br/>',NULL,1203,1203);
INSERT INTO stanza VALUES('E232','1','By Christ redeemed, in Christ restored,<br/>We keep the memory adored,<br/>And show the death of our dear Lord<br/>Until He come.<br/>',NULL,1204,1204);
INSERT INTO stanza VALUES('E232','2','His body broken in our stead<br/>Is seen in this memorial bread,<br/>And so our feeble love is fed<br/>Until He come.<br/>',NULL,1205,1205);
INSERT INTO stanza VALUES('E232','3','The drops of His dread agony,<br/>His life-blood shed for us, we see;<br/>The wine shall tell the mystery<br/>Until He come.<br/>',NULL,1206,1206);
INSERT INTO stanza VALUES('E232','4','And thus that dark betrayal-night<br/>With the last advent we unite,<br/>By one blest chain of loving rite,<br/>Until He come.<br/>',NULL,1207,1207);
INSERT INTO stanza VALUES('E232','5','Until the trump of God be heard,<br/>Until the ancient graves be stirred,<br/>And with the great commanding word<br/>The Lord shall come.<br/>',NULL,1208,1208);
INSERT INTO stanza VALUES('E232','6','O blessed hope! With this elate;<br/>Let not our heart be desolate,<br/>But, strong in faith, in patience wait<br/>Until He come.<br/>',NULL,1209,1209);
INSERT INTO stanza VALUES('E233','1','O what a miracle, my Lord,<br/>That I''m in Thee and Thou in me,<br/>That Thou and I are really one;<br/>O what a wondrous mystery!<br/>',NULL,1210,1210);
INSERT INTO stanza VALUES('E233','2','For me Thy body Thou didst give,<br/>That I may ever share in Thee;<br/>For me Thy precious blood was shed,<br/>That from my sins I might be free.<br/>',NULL,1211,1211);
INSERT INTO stanza VALUES('E233','3','By resurrection Thou didst change<br/>Thy form and as the Spirit come;<br/>Thou wouldst that I be filled with Thee<br/>That all Thy riches mine become.<br/>',NULL,1212,1212);
INSERT INTO stanza VALUES('E233','4','Now as the symbols we behold,<br/>Thy loving self we see anew;<br/>We thank Thee for Thy heart''s desire<br/>As all Thy travail we review.<br/>',NULL,1213,1213);
INSERT INTO stanza VALUES('E233','5','We eat the bread and drink the wine,<br/>And to Thy sweetness we are led;<br/>In spirit each receiving Thee,<br/>Our spirits with Thyself are fed.<br/>',NULL,1214,1214);
INSERT INTO stanza VALUES('E233','6','We long to eat and drink e''en more,<br/>To take Thyself in spirit thus,<br/>Till Thou shalt all our being fill<br/>And true remembrance have from us.<br/>',NULL,1215,1215);
INSERT INTO stanza VALUES('E234','1','Who is He in yonder stall,<br/>At whose feet the shepherds fall?<br/>',NULL,1216,1216);
INSERT INTO stanza VALUES('E234','chorus','''Tis the Lord! Oh wondrous story!<br/>''Tis the Lord! The King of glory!<br/>At His feet we humbly fall,<br/>Crown Him! Crown Him, Lord of all!<br/>',NULL,1217,1217);
INSERT INTO stanza VALUES('E234','2','Who is He in deep distress,<br/>Fasting in the wilderness?<br/>',NULL,1218,1218);
INSERT INTO stanza VALUES('E234','3','Who is He the people bless<br/>For His words of gentleness?<br/>',NULL,1219,1219);
INSERT INTO stanza VALUES('E234','4','Who is He to whom they bring<br/>All the sick and sorrowing?<br/>',NULL,1220,1220);
INSERT INTO stanza VALUES('E234','5','Who is He that stands and weeps<br/>At the grave where Lazarus sleeps?<br/>',NULL,1221,1221);
INSERT INTO stanza VALUES('E234','6','Who is He the gathering throng<br/>Greet with loud triumphant song?<br/>',NULL,1222,1222);
INSERT INTO stanza VALUES('E234','7','Lo! At midnight, who is He<br/>Prays in dark Gethsemane?<br/>',NULL,1223,1223);
INSERT INTO stanza VALUES('E234','8','Who is He on yonder tree<br/>Dies in grief and agony?<br/>',NULL,1224,1224);
INSERT INTO stanza VALUES('E234','9','Who is He who from the grave<br/>Comes to succor, help, and save?<br/>',NULL,1225,1225);
INSERT INTO stanza VALUES('E234','10','Who is He who from His throne<br/>Rules through all the world alone?<br/>',NULL,1226,1226);
INSERT INTO stanza VALUES('E235','1','Praise Him! Praise Him! Jesus, our blessed Redeemer!<br/>Sing, ye saints! His wonderful love proclaim!<br/>Hail Him! Hail Him! Mightiest angels in glory;<br/>Strength and honor give to His holy name!<br/>Like a shepherd, Jesus will feed His people,<br/>In His arms He carried them all day long;<br/>O ye saints that live in the light of His presence,<br/>Praise Him! Praise Him! Ever in joyful song!<br/>',NULL,1227,1227);
INSERT INTO stanza VALUES('E235','2','Praise Him! Praise Him! Jesus, our blessed Redeemer!<br/>For our sins He suffered and bled and died;<br/>He, our Rock, our Hope of eternal salvation,<br/>Hail Him! Hail Him! Jesus, the Crucified;<br/>Loving Savior, meekly enduring sorrow,<br/>Crowned with thorns that cruelly pierced His brow;<br/>Once for us rejected, despised, and forsaken,<br/>Prince of Glory, ever triumphant now.<br/>',NULL,1228,1228);
INSERT INTO stanza VALUES('E235','3','Praise Him! Praise Him! Jesus, our blessed Redeemer!<br/>Heavenly portals, loud with hosannas ring!<br/>Jesus, Savior, reigneth for ever and ever;<br/>Crown Him! Crown Him! Prophet and Priest and King!<br/>Death is vanquished! Tell it with joy, ye faithful,<br/>Where is now thy victory, boasting grave?<br/>Jesus lives! No longer thy portals are cheerless;<br/>Jesus lives, the mighty and strong to save.<br/>',NULL,1229,1229);
INSERT INTO stanza VALUES('E236','1','Lamb of God! Our souls adore Thee,<br/>While upon Thy face we gaze;<br/>There the Father''s love and glory<br/>Shine in all their brightest rays;<br/>Thine Almighty pow''r and wisdom<br/>All creation''s works proclaim;<br/>Heav''n and earth alike confess Thee<br/>As the ever great "I AM."<br/>',NULL,1230,1230);
INSERT INTO stanza VALUES('E236','2','Lamb of God! Thy Father''s bosom<br/>Ever was Thy dwelling place;<br/>His delight, in Him rejoicing,<br/>One with Him in pow''r and grace;<br/>O what wondrous love and mercy!<br/>Thou didst lay Thy glory by;<br/>And for us didst come from heaven<br/>As the Lamb of God to die.<br/>',NULL,1231,1231);
INSERT INTO stanza VALUES('E236','3','Lamb of God! When we behold Thee<br/>Lowly in the manger laid,<br/>Wand''ring as a homeless stranger<br/>In the world Thy hands had made;<br/>When we see Thee in the garden<br/>In Thine agony of blood,<br/>At Thy grace we are confounded,<br/>Holy, spotless Lamb of God!<br/>',NULL,1232,1232);
INSERT INTO stanza VALUES('E236','4','When we see Thee, as the victim,<br/>Bound to the accursed tree,<br/>For our guilt and folly striken,<br/>All our judgment borne by Thee,<br/>Lord, we own, with hearts adoring,<br/>Thou hast loved us unto blood;<br/>Glory, glory everlasting<br/>Be to Thee, Thou Lamb of God.<br/>',NULL,1233,1233);
INSERT INTO stanza VALUES('E236','5','Lamb of God, Thou soon in glory<br/>Wilt to this sad earth return;<br/>All Thy foes shall quake before Thee,<br/>All that now despise Thee mourn;<br/>Then Thy saints all gathered to Thee,<br/>With Thee in Thy kingdom reign;<br/>Thine the praise and Thine the glory,<br/>Lamb of God, for sinners slain!<br/>',NULL,1234,1234);
INSERT INTO stanza VALUES('E237','1','Amazing words!-He ''gave Himself for me,''<br/>For me-rebellious, sinful, guilty me.<br/>For me the Savior bore the cross and shame;<br/>Rejoice, my soul, and bless His sacred name.<br/>',NULL,1235,1235);
INSERT INTO stanza VALUES('E237','2','For me He left His glorious throne above,<br/>For me revealed His Father''s wondrous love,<br/>For me He tabernacled here below,<br/>For me He drank the bitter cup of woe.<br/>',NULL,1236,1236);
INSERT INTO stanza VALUES('E237','3','For me He reviled, despised, betrayed;<br/>For me was scourged, condemned and crucified;<br/>For me He suffered on th'' accursed tree<br/>For me-lost, wretched, vile, unworthy me.<br/>',NULL,1237,1237);
INSERT INTO stanza VALUES('E237','4','For me in agony He groaned and died,<br/>For me God''s righteous law He satisfied,<br/>For me His precious blood He shed to save,<br/>For me He rose triumphant from the grave.<br/>',NULL,1238,1238);
INSERT INTO stanza VALUES('E238','1','When morning gilds the skies,<br/>My heart awaking cries:<br/>May Jesus Christ be praised!<br/>Alike at work and prayer<br/>To Jesus I repair:<br/>May Jesus Christ be praised!<br/>',NULL,1239,1239);
INSERT INTO stanza VALUES('E238','2','To Thee, my God above,<br/>I cry with glowing love,<br/>May Jesus Christ be praised!<br/>The fairest graces spring<br/>In hearts that ever sing,<br/>May Jesus Christ be praised!<br/>',NULL,1240,1240);
INSERT INTO stanza VALUES('E238','3','Does sadness fill my mind?<br/>A solace here I find,<br/>May Jesus Christ be praised!<br/>Or fades my earthly bliss?<br/>My comfort still is this,<br/>May Jesus Christ be praised!<br/>',NULL,1241,1241);
INSERT INTO stanza VALUES('E238','4','When evil thoughts molest,<br/>With this I shield my breast,<br/>May Jesus Christ be praised!<br/>The powers of darkness fear,<br/>When this sweet chant they hear,<br/>May Jesus Christ be praised!<br/>',NULL,1242,1242);
INSERT INTO stanza VALUES('E238','5','When sleep her balm denies,<br/>My silent spirit sighs,<br/>May Jesus Christ be praised!<br/>The night becomes as day,<br/>When from the heart we say,<br/>May Jesus Christ be praised!<br/>',NULL,1243,1243);
INSERT INTO stanza VALUES('E238','6','Be this, while life is mine,<br/>My canticle divine,<br/>May Jesus Christ be praised!<br/>Be this th'' eternal song<br/>Through all the ages long,<br/>May Jesus Christ be praised!<br/>',NULL,1244,1244);
INSERT INTO stanza VALUES('E239','1','Ten thousand thanks to Jesus,<br/>Whose life our ransom paid,<br/>Whose blood a full redemption<br/>For all the world has made:<br/>Let every heart adore Him;<br/>Let every creature sing<br/>Ten thousand thanks to Jesus,<br/>Our Savior and our King.<br/>',NULL,1245,1245);
INSERT INTO stanza VALUES('E239','chorus','Ten thousand thanks, ten thousand thanks,<br/>We''ll praise Him o''er and o''er;<br/>And for the life with Him to live,<br/>Ten thousand thousand more.<br/>',NULL,1246,1246);
INSERT INTO stanza VALUES('E239','2','Ten thousand hearts to Jesus<br/>How gladly would we give;<br/>Ten thousand lives to Jesus,<br/>Had we so long to live;<br/>Ten thousand tongues shall praise Him,<br/>Ten thousand songs ascend<br/>To Him, our blest Redeemer,<br/>To Him, our dearest Friend.<br/>',NULL,1247,1247);
INSERT INTO stanza VALUES('E239','3','Ten thousand thanks to Jesus<br/>For blessings every hour;<br/>Ten thousand times ten thousand,<br/>For love''s redeeming pow''r;<br/>And when, He comes in glory<br/>His blessed face we''ll see,<br/>His love through endless ages<br/>Our sweetest song shall be.<br/>',NULL,1248,1248);
INSERT INTO stanza VALUES('E240','1','Glory, honor, praise and power,<br/>Be unto the Lamb forever!<br/>Jesus Christ is our Redeemer,<br/>Hallelujah! Hallelujah!<br/>Hallelujah! Praise ye the Lord!<br/>',NULL,1249,1249);
INSERT INTO stanza VALUES('E241','1','Blessing and honor and glory be Thine,<br/>And glory be Thine,<br/>And glory be Thine.<br/>Blessing and honor and glory be Thine,<br/>Both now and evermore.<br/>Praise Him! Praise Him!<br/>All ye saints adore Him.<br/>Praise Him! Praise Him!<br/>Both now and evermore.<br/>Hallelujah!<br/>Blessing and honor and glory be Thine,<br/>And glory be Thine,<br/>And glory be Thine.<br/>Blessing and honor and glory be Thine,<br/>Both now and evermore.<br/>',NULL,1250,1250);
INSERT INTO stanza VALUES('E242','1','The Spirit of God today<br/>The Spirit of Jesus is,<br/>The God-man who died and rose,<br/>Ascending to glory His.<br/>',NULL,1251,1251);
INSERT INTO stanza VALUES('E242','2','''Tis from such a Jesus came<br/>The Spirit of Jesus to us,<br/>To make His reality<br/>Experience unto us.<br/>',NULL,1252,1252);
INSERT INTO stanza VALUES('E242','3','The Spirit of Jesus has<br/>All elements human, divine,<br/>The living of man in Him<br/>And glory of God combine.<br/>',NULL,1253,1253);
INSERT INTO stanza VALUES('E242','4','The suff''ring of human life,<br/>Effectiveness of His death,<br/>His rising and reigning too<br/>Are all in the Spirit''s breath.<br/>',NULL,1254,1254);
INSERT INTO stanza VALUES('E242','5','With all these components true<br/>His Spirit in us doth move,<br/>And by His anointing full<br/>The riches of Christ we prove.<br/>',NULL,1255,1255);
INSERT INTO stanza VALUES('E242','6','This Spirit of Jesus doth<br/>Encompass both great and small;<br/>Inclusively He doth work<br/>In us, making God our all.<br/>',NULL,1256,1256);
INSERT INTO stanza VALUES('E243','1','God''s Spirit is of Christ today,<br/>The Spirit of reality,<br/>He dwells in me with Christ as life<br/>To make this Christ so real to me.<br/>',NULL,1257,1257);
INSERT INTO stanza VALUES('E243','2','As Christ is God''s embodiment,<br/>Expressing God as life divine;<br/>So is the Spirit unto Christ,<br/>Revealing Him in life sublime.<br/>',NULL,1258,1258);
INSERT INTO stanza VALUES('E243','3','The fulness of the Father God<br/>In Christ the Son dwells bodily;<br/>And all the riches of the Son<br/>Are Spirit, our reality.<br/>',NULL,1259,1259);
INSERT INTO stanza VALUES('E243','4','Oh in the Son the Father is,<br/>And now the Spirit is the Son;<br/>The Father with the Son is joined,<br/>The Spirit with the Son is one.<br/>',NULL,1260,1260);
INSERT INTO stanza VALUES('E243','5','''Tis when the Spirit strengthens us<br/>And Christ His home makes in our hearts,<br/>The Father''s fulness with His love<br/>Will fill us in our inward parts.<br/>',NULL,1261,1261);
INSERT INTO stanza VALUES('E243','6','In Christ, the Father we possess,<br/>Receiving Him for all our need;<br/>In Spirit we experience Christ<br/>As life and everything indeed.<br/>',NULL,1262,1262);
INSERT INTO stanza VALUES('E243','7','With Thy divine reality,<br/>Lord, fill us by Thy Spirit now,<br/>That we may all be full of Thee,<br/>And all Thy riches thus avow.<br/>',NULL,1263,1263);
INSERT INTO stanza VALUES('E244','1','The Holy Spirit is today<br/>The Spirit of the life divine,<br/>He quickens us and gives us life,<br/>And makes us fit for God''s design.<br/>',NULL,1264,1264);
INSERT INTO stanza VALUES('E244','2','As living water quenching thirst<br/>The stream of life He e''er supplies;<br/>Imparting Christ as life divine,<br/>My hungry heart He satisfies.<br/>',NULL,1265,1265);
INSERT INTO stanza VALUES('E244','3','Enlight''ning with the light of life,<br/>He chases darkness far away;<br/>Imparting Christ as light divine,<br/>He turns for us the night to day.<br/>',NULL,1266,1266);
INSERT INTO stanza VALUES('E244','4','He strengthens with the pow''r of life<br/>To energize our inner man;<br/>Imparting Christ as strength divine,<br/>He moves within us for God''s plan.<br/>',NULL,1267,1267);
INSERT INTO stanza VALUES('E244','5','By law of life He liberates,<br/>And frees us from the law of sin;<br/>And with the nature all divine<br/>He regulates us from within.<br/>',NULL,1268,1268);
INSERT INTO stanza VALUES('E244','6','As Spirit of the life divine,<br/>Thru us abundant fruit He bears;<br/>Expressing God-like attributes,<br/>To others Christ in life He shares.<br/>',NULL,1269,1269);
INSERT INTO stanza VALUES('E244','7','The Spirit ever giving life<br/>Transforms me thus with life divine;<br/>Renewing all my inward parts,<br/>In life He makes Christ''s image mine.<br/>',NULL,1270,1270);
INSERT INTO stanza VALUES('E244','8','Oh, by Thy Spirit, fill me, Lord,<br/>The Spirit of Thy life divine,<br/>And saturate me thoroughly<br/>Till all my life is filled with Thine.<br/>',NULL,1271,1271);
INSERT INTO stanza VALUES('E245','1','Oh, spread the tidings ''round, wherever man is found,<br/>Wherever human hearts and human woes abound;<br/>Let every Christian tongue proclaim the joyful sound:<br/>The Comforter has come!<br/>',NULL,1272,1272);
INSERT INTO stanza VALUES('E245','chorus','The Comforter has come,<br/>The Comforter has come!<br/>The Holy Ghost from heav''n,<br/>The Lord''s dear promise giv''n;<br/>Oh, spread the tidings ''round,<br/>Wherever man is found -<br/>The Comforter has come!<br/>',NULL,1273,1273);
INSERT INTO stanza VALUES('E245','2','The long, long night is past, the morning breaks at last;<br/>And hushed the dreadful wail and fury of the blast,<br/>As o''er the golden hills the day advances fast!<br/>The Comforter has come!<br/>',NULL,1274,1274);
INSERT INTO stanza VALUES('E245','3','Lo, the great King of kings, with healing in His wings,<br/>To every captive soul a full deliverance brings;<br/>And through the vacant cells the song of triumph rings:<br/>The Comforter has come!<br/>',NULL,1275,1275);
INSERT INTO stanza VALUES('E245','4','O boundless love divine! How shall this tongue of mine<br/>To wond''ring mortals tell the matchless grace divine-<br/>That I, a child of hell, should in His image shine!<br/>The Comforter has come''<br/>',NULL,1276,1276);
INSERT INTO stanza VALUES('E246','1','Joys are flowing like a river,<br/>Since the Comforter has come;<br/>He abides with us forever,<br/>Makes the trusting heart His home.<br/>',NULL,1277,1277);
INSERT INTO stanza VALUES('E246','chorus','Blessed quietness, holy quietness-<br/>What assurance in my soul!<br/>On the stormy sea He speaks peace to me.<br/>How the billows cease to roll!<br/>',NULL,1278,1278);
INSERT INTO stanza VALUES('E246','2','Bringing life and health and gladness<br/>All around, this heavenly Guest<br/>Banished unbelief and sadness,<br/>Changed our weariness to rest.<br/>',NULL,1279,1279);
INSERT INTO stanza VALUES('E246','3','Like the rain that falls from heaven,<br/>Like the sunlight from the sky,<br/>So the Holy Ghost is given,<br/>Coming to us from on high.<br/>',NULL,1280,1280);
INSERT INTO stanza VALUES('E246','4','See a fruitful field is growing<br/>Blessed fruits of righteousness,<br/>And the streams of life are flowing<br/>In the lonely wilderness.<br/>',NULL,1281,1281);
INSERT INTO stanza VALUES('E246','5','What a wonderful salvation<br/>Where we always see His face!<br/>What a perfect habitation!<br/>What a quiet resting place!<br/>',NULL,1282,1282);
INSERT INTO stanza VALUES('E247','1','Our blest Redeemer ere He breathed<br/>His tender last farewell,<br/>A guide, a comforter, bequeathed<br/>With us to dwell.<br/>',NULL,1283,1283);
INSERT INTO stanza VALUES('E247','2','He came sweet influence to impart,<br/>A gracious, willing guest,<br/>While He can find one humble heart<br/>Wherein to rest.<br/>',NULL,1284,1284);
INSERT INTO stanza VALUES('E247','3','And His that gentle voice we hear,<br/>Soft as the breath of even,<br/>That checks each fault, that calms each fear<br/>With peace of heav''n.<br/>',NULL,1285,1285);
INSERT INTO stanza VALUES('E247','4','And every virtue we possess,<br/>And every victory won,<br/>And every thought of holiness,<br/>Are His alone.<br/>',NULL,1286,1286);
INSERT INTO stanza VALUES('E247','5','Lord, in Thy purity and grace,<br/>Our weakness pitying see;<br/>Oh, make our heart Thy dwelling place,<br/>And worthier Thee.<br/>',NULL,1287,1287);
INSERT INTO stanza VALUES('E248','1','Fainting in the desert,<br/>Israel''s thousands stand<br/>At the rock of Kadesh.<br/>Hark! The Lord''s command,<br/>Speak to the Rock,<br/>Bid the waters flow,<br/>Strike not its bosom<br/>Opened long ago,<br/>Speak to the Rock,<br/>Till the waters flow.<br/>',NULL,1288,1288);
INSERT INTO stanza VALUES('E248','chorus','Speak to the Rock,<br/>Bid the waters flow,<br/>Doubt not the Spirit,<br/>Given long ago;<br/>Take what He waiteth,<br/>Freely to bestow,<br/>Drink till its fulness<br/>All Thy being know.<br/>',NULL,1289,1289);
INSERT INTO stanza VALUES('E248','2','Blessed Rock of Ages,<br/>Thou art open still;<br/>Thy blest Holy Spirit<br/>All our being fill;<br/>Still Thou dost say,<br/>Wherefore struggle so?<br/>Call for the Spirit,<br/>Whisper soft and low,<br/>Speak to the Rock<br/>Bid the waters flow.<br/>',NULL,1290,1290);
INSERT INTO stanza VALUES('E248','3','Oh, for trust more simple,<br/>Fully to believe;<br/>Oh, for hearts more childlike,<br/>Freely to receive;<br/>E''en as a babe,<br/>On its mother''s breast,<br/>So on Thy bosom<br/>Let my spirit rest,<br/>Filled with Thy life,<br/>With Thy blessing blest.<br/>',NULL,1291,1291);
INSERT INTO stanza VALUES('E249','1','Flow through me, Lord, a weak and earthly vessel,<br/>Cleansed by Thy blood, and quickened at Thy call.<br/>Flow through me, Lord, all utterly abandoned,<br/>To Thy dear service, great, or high, or small.<br/>',NULL,1292,1292);
INSERT INTO stanza VALUES('E249','2','Flow through me, Lord, with overflowing fulness,<br/>Make me to know Thine own deep love for souls.<br/>Work in me, Lord, the faith that moveth mountains,<br/>As power, Almighty power, my being holds.<br/>',NULL,1293,1293);
INSERT INTO stanza VALUES('E249','3','Flow through me, Lord, till sin in all its blackness<br/>To captives bound by Satan is revealed.<br/>Flow through me, Lord, till hearts are stricken, broken,<br/>And in Thy cleansing fountain saved and healed.<br/>',NULL,1294,1294);
INSERT INTO stanza VALUES('E249','4','Flow through me, Lord, till lagging souls are quickened,<br/>Till lives of failure sing the victory song,<br/>Till praise from lips long dumb and silent, open,<br/>And join with rapture earth''s glad, cleansed throng.<br/>',NULL,1295,1295);
INSERT INTO stanza VALUES('E249','5','Flow through me, Lord, till waters from Thy fountain<br/>Shall slake the thirst of souls in deserts drear.<br/>Flow through me, Lord, till arid places blossom<br/>With roses fresh and sweet, and wondrous fair.<br/>',NULL,1296,1296);
INSERT INTO stanza VALUES('E249','6','Flow through me, Lord, set all my heart-strings thrilling,<br/>With Thine own love, so matchless, perfect, free.<br/>Flow through me, Lord, till naught in earth or heaven,<br/>Can satisfy my being, Lord, but Thee.<br/>',NULL,1297,1297);
INSERT INTO stanza VALUES('E250','1','Spring up, well, with water;<br/>Dig Thou, Lord, completely"<br/>Dig away all barriers<br/>That Thy stream flow through me.<br/>',NULL,1298,1298);
INSERT INTO stanza VALUES('E250','2','Christ, the Rock, is riven;<br/>Living water''s flowing;<br/>But within my heart now<br/>It is blocked from going.<br/>',NULL,1299,1299);
INSERT INTO stanza VALUES('E250','3','I will dig by praying,<br/>Dig the dirt entirely,<br/>Thus release the Spirit,<br/>Let the stream flow freely.<br/>',NULL,1300,1300);
INSERT INTO stanza VALUES('E250','4','There''s no need again that<br/>Christ, the Rock, be riven,<br/>But unto the digging<br/>That I should be given.<br/>',NULL,1301,1301);
INSERT INTO stanza VALUES('E250','5','What I need most deeply<br/>Is the Spirit''s filling,<br/>That the living water<br/>From my heart be welling.<br/>',NULL,1302,1302);
INSERT INTO stanza VALUES('E250','6','Dig till there is nothing<br/>Left to block the passage;<br/>Dig until the stream flows<br/>With the living message.<br/>',NULL,1303,1303);
INSERT INTO stanza VALUES('E250','7','Spring up, well, with water;<br/>Dig Thou, Lord, completely;<br/>Dig away all barriers<br/>That Thy stream flow through me.<br/>',NULL,1304,1304);
INSERT INTO stanza VALUES('E251','1','Rivers of living water,<br/>Rivers that flow from the throne,<br/>Rivers o''erflowing with blessing,<br/>Coming from Jesus alone.<br/>',NULL,1305,1305);
INSERT INTO stanza VALUES('E251','chorus','Rivers of living water,<br/>Rivers of life so free,<br/>Flowing from Thee, my Savior,<br/>Send now the rivers through me.<br/>',NULL,1306,1306);
INSERT INTO stanza VALUES('E251','2','Whoso is thirsty come hither,<br/>Here is abundant supply;<br/>Water transparent as crystal,<br/>Come without money and buy.<br/>',NULL,1307,1307);
INSERT INTO stanza VALUES('E251','3','Cleanse me, oh, cleanse me, my Savior,<br/>Make me a channel today;<br/>Empty me, fill me and use me,<br/>Teach me to trust and obey.<br/>',NULL,1308,1308);
INSERT INTO stanza VALUES('E251','4','Then, and then only, Lord Jesus,<br/>Through me the rivers can flow;<br/>Thus and thus only will others<br/>Learn Thy great fulness to know.<br/>',NULL,1309,1309);
INSERT INTO stanza VALUES('E251','5','Now I surrender to Jesus,<br/>Here I lay all at His feet<br/>Anything, anywhere only,<br/>Just for His service made meet!<br/>',NULL,1310,1310);
INSERT INTO stanza VALUES('E252','1','Thou Breath from still eternity<br/>Breathe o''er my spirit''s barren land-<br/>The pine tree and the myrtle tree<br/>Shall spring amid the desert sand;<br/>And where Thy living water flows<br/>The waste shall blossom as the rose.<br/>',NULL,1311,1311);
INSERT INTO stanza VALUES('E252','2','May I in will and deed and word<br/>Obey Thee as a little child;<br/>And keep me in Thy love, my Lord,<br/>For ever holy, undefiled;<br/>Within me teach, and strive, and pray,<br/>Lest I should choose my own wild way.<br/>',NULL,1312,1312);
INSERT INTO stanza VALUES('E252','3','Thy Spirit, Stream by Thee, the Son,<br/>Is opened to us crystal pure,<br/>Forth flowing from the heavenly throne<br/>To waiting hearts and spirits poor;<br/>Athirst and weary do I sink<br/>Beside Thy waters, there to drink.<br/>',NULL,1313,1313);
INSERT INTO stanza VALUES('E252','4','My spirit turns to Thee and clings,<br/>All else forsaking, unto Thee;<br/>Forgetting all created things,<br/>Remembering only "God in me."<br/>Thy living Stream, Thy gracious Rain,<br/>None wait for these, and wait in vain.<br/>',NULL,1314,1314);
INSERT INTO stanza VALUES('E253','1','Breathe on us, Lord of life,<br/>Fill us with life anew,<br/>That we may love what Thou dost love,<br/>And do what Thou wouldst do.<br/>',NULL,1315,1315);
INSERT INTO stanza VALUES('E253','2','Breathe on us, Lord of life,<br/>Until our hearts are pure,<br/>Until with Thee we will one will,<br/>To do or to endure.<br/>',NULL,1316,1316);
INSERT INTO stanza VALUES('E253','3','Breathe on us, Lord of life,<br/>Till we are wholly Thine,<br/>Till all this earthly part of us<br/>Glows with Thy fire divine.<br/>',NULL,1317,1317);
INSERT INTO stanza VALUES('E253','4','Breathe on us, Lord of life,<br/>So shall we never die,<br/>But live with Thee the perfect life<br/>Of Thine eternity.<br/>',NULL,1318,1318);
INSERT INTO stanza VALUES('E254','1','O Lord of life, breathe on us now,<br/>And move within us while we pray;<br/>The spring of our new life art Thou,<br/>The very light of our new day.<br/>',NULL,1319,1319);
INSERT INTO stanza VALUES('E254','2','O strangely art Thou with us, Lord,<br/>Neither in height nor depth to seek;<br/>In nearness shall Thy voice be heard;<br/>Spirit to spirit Thou dost speak.<br/>',NULL,1320,1320);
INSERT INTO stanza VALUES('E254','3','Thou art our Advocate on high;<br/>He is our Advocate within;<br/>O plead the truth, and make reply<br/>To every argument of sin.<br/>',NULL,1321,1321);
INSERT INTO stanza VALUES('E254','4','But ah, this faithless heart of mine!<br/>The way I know, I know my guide;<br/>Forgive me, O my Friend divine,<br/>That I so often turn aside.<br/>',NULL,1322,1322);
INSERT INTO stanza VALUES('E254','5','Be with me when no other friend<br/>The myst''ry of my heart can share;<br/>And be Thou known, when fears transcend,<br/>By Thy best name of Comforter.<br/>',NULL,1323,1323);
INSERT INTO stanza VALUES('E255','1','O Lord, breathe Thy Spirit on me,<br/>Teach me how to breathe Thee in;<br/>Help me pour into Thy bosom<br/>All my life of self and sin.<br/>',NULL,1324,1324);
INSERT INTO stanza VALUES('E255','chorus','I am breathing out my sorrow,<br/>Breathing out my sin;<br/>I am breathing, breathing, breathing,<br/>All Thy fulness in.<br/>',NULL,1325,1325);
INSERT INTO stanza VALUES('E255','2','I am breathing out my own life,<br/>That I may be filled with Thine;<br/>Letting go my strength and weakness,<br/>Breathing in Thy life divine.<br/>',NULL,1326,1326);
INSERT INTO stanza VALUES('E255','3','Breathing out my sinful nature,<br/>Thou hast borne it all for me;<br/>Breathing in Thy cleansing fulness,<br/>Finding all my life in Thee.<br/>',NULL,1327,1327);
INSERT INTO stanza VALUES('E255','4','I am breathing out my sorrow,<br/>On Thy kind and gentle breast;<br/>Breathing in Thy joy and comfort,<br/>Breathing in Thy peace and rest.<br/>',NULL,1328,1328);
INSERT INTO stanza VALUES('E255','5','I am breathing out my sickness,<br/>Thou hast borne its burden too;<br/>I am breathing in Thy healing,<br/>Ever promised, ever new.<br/>',NULL,1329,1329);
INSERT INTO stanza VALUES('E255','6','I am breathing out my longings<br/>In Thy listening, loving ear;<br/>I am breathing in Thy answers,<br/>Stilling every doubt and fear.<br/>',NULL,1330,1330);
INSERT INTO stanza VALUES('E255','7','I am breathing every moment,<br/>Drawing all my life from Thee;<br/>Breath by breath I live upon Thee,<br/>Lord, Thy Spirit breathe in me.<br/>',NULL,1331,1331);
INSERT INTO stanza VALUES('E256','1','Oh, blow upon us, Lord, while here we wait on Thee;<br/>Oh, blow with mighty wind and bring us liberty;<br/>Oh, blow till in our midst revival we shall see;<br/>Oh, blow upon us, Lord, we pray!<br/>',NULL,1332,1332);
INSERT INTO stanza VALUES('E256','chorus','Oh, blow upon us, Lord, today!<br/>Oh, blow all sloth and sleep away!<br/>Oh, may Thy wind descend,<br/>All our backsliding end!<br/>Oh, blow upon us, Lord, we pray!<br/>',NULL,1333,1333);
INSERT INTO stanza VALUES('E256','2','Oh, blow with love divine and stir up our cold heart;<br/>Oh, blow and to our soul the breath of heav''n impart;<br/>Oh, blow till from each one indifference shall depart;<br/>Oh, blow upon us, Lord, we pray!<br/>',NULL,1334,1334);
INSERT INTO stanza VALUES('E256','3','Oh, blow with pow''r from heav''n our spirit to inspire;<br/>Oh, blow and quicken us and fill with Thy desire;<br/>Oh, blow till all of us be wholly set on fire;<br/>Oh, blow upon us, Lord, we pray!<br/>',NULL,1335,1335);
INSERT INTO stanza VALUES('E257','1','Lord, may Thy Wind of heaven blow<br/>Upon us here today!<br/>With stirring and reviving might,<br/>To us Thy pow''r display.<br/>',NULL,1336,1336);
INSERT INTO stanza VALUES('E257','chorus','Oh, mighty Lord, on us descend,<br/>Oh, may Thy Spirit blow!<br/>With power cause us to transcend,<br/>Grant us the living flow!<br/>',NULL,1337,1337);
INSERT INTO stanza VALUES('E257','2','With Thy empow''ring Spirit blow<br/>And all the barriers break;.<br/>With Thy life-giving Spirit breathe,<br/>That we of Thee partake.<br/>',NULL,1338,1338);
INSERT INTO stanza VALUES('E257','3','Thy Spirit is of sevenfold wealth,<br/>For us to share of Thee;<br/>Grant us the full experience of<br/>The God in persons Three.<br/>',NULL,1339,1339);
INSERT INTO stanza VALUES('E258','1','"With one accord" within an upper room<br/>The faithful followers of Jesus met:<br/>One was the hope of every waiting soul,<br/>And on one object great each heart was set.<br/>',NULL,1340,1340);
INSERT INTO stanza VALUES('E258','2','"With one accord," until the mighty gift<br/>Of Pentecostal power was outpoured;<br/>Then forth as witnesses possessed of God,<br/>To preach the resurrection of the Lord!<br/>',NULL,1341,1341);
INSERT INTO stanza VALUES('E258','3','"With one accord" within the house of God<br/>A hallelujah song is daily raised,<br/>As with the voice of one, from vocal hearts<br/>Christ Jesus'' name is glorified and praised.<br/>',NULL,1342,1342);
INSERT INTO stanza VALUES('E258','4','Pour down Thy Spirit once again, dear Lord;<br/>Our cry goes up to Thee for "latter rain";<br/>Unite Thy people as the "heart of one,"<br/>And Pentecostal days shall come again!<br/>',NULL,1343,1343);
INSERT INTO stanza VALUES('E259','1','Lord, I hear of show''rs of blessing<br/>Thou art scattering full and free,<br/>Show''rs the thirsty land refreshing;<br/>Let some drops now fall on me.<br/>',NULL,1344,1344);
INSERT INTO stanza VALUES('E259','chorus','Even me, even me,<br/>Let some drops now fall on me.<br/>',NULL,1345,1345);
INSERT INTO stanza VALUES('E259','2','Pass me not, O gracious Father!<br/>Sinful though my heart may be;<br/>Thou might''st leave me, but the rather<br/>Let Thy mercy fall on me.<br/>',NULL,1346,1346);
INSERT INTO stanza VALUES('E259','3','Pass me not, O tender Savior!<br/>Let me love and cling to Thee;<br/>I am longing for Thy favor;<br/>While Thou''rt calling, call for me.<br/>',NULL,1347,1347);
INSERT INTO stanza VALUES('E259','4','Pass me not, O Lord, the Spirit!<br/>Thou canst make the blind to see;<br/>By the Witness of Thy merit,<br/>Speak the word of power to me.<br/>',NULL,1348,1348);
INSERT INTO stanza VALUES('E259','5','Love of God, so pure and changeless!<br/>Blood of Christ, so rich and free!<br/>Grace of God, so strong and boundless!<br/>Magnify them all in me.<br/>',NULL,1349,1349);
INSERT INTO stanza VALUES('E259','6','Pass me not! Thy lost one bringing,<br/>Bind my heart, O Lord, to Thee;<br/>While the streams of life are springing,<br/>Blessing others, oh, bless me.<br/>',NULL,1350,1350);
INSERT INTO stanza VALUES('E260','1','There shall be showers of blessing:<br/>This is the promise of love;<br/>There shall be seasons refreshing,<br/>Sent from the Savior above.<br/>',NULL,1351,1351);
INSERT INTO stanza VALUES('E260','chorus','Showers of blessing,<br/>Showers of blessing we need;<br/>Mercy-drops round us are falling,<br/>But for the showers we plead.<br/>',NULL,1352,1352);
INSERT INTO stanza VALUES('E260','2','There shall be showers of blessing-<br/>Precious reviving again;<br/>Over the hills and the valleys,<br/>Sound of abundance of rain.<br/>',NULL,1353,1353);
INSERT INTO stanza VALUES('E260','3','There shall be showers of blessing;<br/>Send them upon us, O Lord!<br/>Grant to us now a refreshing;<br/>Come, and now honor Thy Word.<br/>',NULL,1354,1354);
INSERT INTO stanza VALUES('E260','4','There shall be showers of blessing;<br/>O that today they might fall,<br/>Now as to God we''re confessing,<br/>Now as on Jesus we call!<br/>',NULL,1355,1355);
INSERT INTO stanza VALUES('E260','5','There shall be showers of blessing,<br/>If we but trust and obey;<br/>There shall be seasons refreshing,<br/>If we let God have His way.<br/>',NULL,1356,1356);
INSERT INTO stanza VALUES('E261','1','Praise waiteth Thee in mercy''s court,<br/>Where Thy beloved dwell;<br/>Ransomed, released from Satan''s thrall,<br/>Their Hallelujahs swell.<br/>Come, as the Spirit, Lord, today,<br/>Our songs of praise inspire;<br/>Purge the iniquity, and touch<br/>Our lips with living fire.<br/>',NULL,1357,1357);
INSERT INTO stanza VALUES('E261','2','Praise for what Thou our God hast wrought;<br/>For promised blessings ours;<br/>The cloud on faith''s horizon seen,<br/>The Pentecostal showers.<br/>Praise for Thine own right way, dear Lord,<br/>We did not understand,<br/>But as Thy-plans unfolded lie,<br/>We see Thy guiding hand.<br/>',NULL,1358,1358);
INSERT INTO stanza VALUES('E261','3','Enlarge our soul''s capacity,<br/>Cut deeper channels, Lord;<br/>Room for the floods of blessing now,<br/>According to Thy Word.<br/>E''en while we praise, the heavens rend,<br/>In power come from on high;<br/>Make this another Pentecost,<br/>Answer our spirit''s cry.<br/>',NULL,1359,1359);
INSERT INTO stanza VALUES('E262','1','Come, Lord, as the Spirit come,<br/>Lo! We stretch our hands to Thee;<br/>From the Father to the Son,<br/>Let us now Thy glory see.<br/>',NULL,1360,1360);
INSERT INTO stanza VALUES('E262','chorus','Come, oh Lord, Great Spirit, come!<br/>Let the mighty deed be done!<br/>Satisfy our soul''s desire,<br/>See us waiting for the fire,<br/>Waiting, waiting,<br/>See us waiting for the fire.<br/>',NULL,1361,1361);
INSERT INTO stanza VALUES('E262','2','On the altar now we lay<br/>Soul and body, mind and will;<br/>All the evil passions slay,<br/>Come, and every corner fill.<br/>',NULL,1362,1362);
INSERT INTO stanza VALUES('E262','3','Now the sacrifice we make,<br/>Though as dear as a right eye,<br/>For our blessed Savior''s sake,<br/>Who for us did bleed and die.<br/>',NULL,1363,1363);
INSERT INTO stanza VALUES('E262','4','Now, by faith, the gift I claim,<br/>Bought for me by blood divine:<br/>Through the all-prevailing Name<br/>All the promises are mine.<br/>',NULL,1364,1364);
INSERT INTO stanza VALUES('E263','1','God Sent His mighty pow''r<br/>To this poor, sinful heart,<br/>To keep me every hour,<br/>And needful grace impart;<br/>And since His Spirit came,<br/>To take supreme control,<br/>The love-enkindled flame<br/>Is burning in my soul.<br/>',NULL,1365,1365);
INSERT INTO stanza VALUES('E263','chorus','''Tis burning in my soul,<br/>''Tis burning in my soul;<br/>The fire of heav''nly love is<br/>burning in my soul;<br/>The Holy Spirit came,<br/>All glory to His name!<br/>The fire of heav''nly love is<br/>burning in my soul.<br/>',NULL,1366,1366);
INSERT INTO stanza VALUES('E263','2','Before the cross I bow,<br/>Upon the altar lay<br/>A willing off''ring now,<br/>My all from day to day.<br/>My Savior paid the price,<br/>My name He sweetly calls;<br/>Upon the sacrifice<br/>The fire from heaven falls.<br/>',NULL,1367,1367);
INSERT INTO stanza VALUES('E263','3','No good that I have done,<br/>His promise I embrace;<br/>Accepted in the Son,<br/>He saves me by His grace.<br/>All glory be to God!<br/>Let hallelujahs roll;<br/>His love is shed abroad,<br/>The fire is in my soul.<br/>',NULL,1368,1368);
INSERT INTO stanza VALUES('E264','1','Jesus, Thine all-victorious love<br/>Shed in my soul abroad;<br/>Then shall my heart no longer rove,<br/>Rooted and fixed in God,<br/>Rooted and fixed in God.<br/>',NULL,1369,1369);
INSERT INTO stanza VALUES('E264','2','Oh, that in me the sacred fire<br/>Might now begin to glow;<br/>Burn up the dross of base desire,<br/>And make the mountains flow,<br/>And make the mountains flow.<br/>',NULL,1370,1370);
INSERT INTO stanza VALUES('E264','3','He, who at Pentecost didst fall,<br/>May He my sins consume;<br/>Thy Holy Ghost, for Him I call;<br/>Thy burning Spirit, come,<br/>Thy burning Spirit, come.<br/>',NULL,1371,1371);
INSERT INTO stanza VALUES('E264','4','Refining fire, go through my heart,<br/>Illuminate my soul;<br/>Scatter Thy life through every part,<br/>And sanctify the whole,<br/>And sanctify the whole.<br/>',NULL,1372,1372);
INSERT INTO stanza VALUES('E264','5','My steadfast soul, from falling free,<br/>Shall then no longer move,<br/>While Christ is all the world to me,<br/>And all my heart is love,<br/>And all my heart is love.<br/>',NULL,1373,1373);
INSERT INTO stanza VALUES('E265','1','Where the sprinkling of the blood is,<br/>There the ointment doth remain;<br/>Man in touch with God thus bringing,<br/>These the fellowship maintain.<br/>',NULL,1374,1374);
INSERT INTO stanza VALUES('E265','2','Blood, the emblem of redemption,<br/>Cleansing all the sins away;<br/>Ointment, symbol of the Spirit,<br/>Bringing God to man for aye.<br/>',NULL,1375,1375);
INSERT INTO stanza VALUES('E265','3','Blood doth speak of what God worketh,<br/>Ointment, what He is for us;<br/>By His work and by His person<br/>God Himself is blent with us.<br/>',NULL,1376,1376);
INSERT INTO stanza VALUES('E265','4','By the blood of Christ''s redemption<br/>We are cleansed from all alloy;<br/>By th'' anointing of the Spirit<br/>God Himself we may enjoy.<br/>',NULL,1377,1377);
INSERT INTO stanza VALUES('E265','5','By the cleansing and anointing<br/>We with God are kept in one;<br/>By the blood and by the ointment<br/>God, our portion full, is won.<br/>',NULL,1378,1378);
INSERT INTO stanza VALUES('E265','6','We in faith must claim the cleansing<br/>When we need the precious blood.<br/>Ever to obey th'' anointing,<br/>Thus to live and walk with God.<br/>',NULL,1379,1379);
INSERT INTO stanza VALUES('E265','7','God as light we''ll then be knowing,<br/>God experience as love,<br/>And in God as life e''er growing,<br/>God as power we will prove.<br/>',NULL,1380,1380);
INSERT INTO stanza VALUES('E266','1','Divine anointing in me dwelleth,<br/>And it teaches me all things;<br/>It ever leads me in the Lord to live<br/>And to me His presence brings.<br/>',NULL,1381,1381);
INSERT INTO stanza VALUES('E266','chorus','In my spirit the anointing dwells,<br/>O the anointing dwells and teaches everything;<br/>In my spirit the anointing dwells<br/>And ever teaches everything.<br/>',NULL,1382,1382);
INSERT INTO stanza VALUES('E266','2','It is the moving of the Spirit<br/>Gracious as the ointment pure;<br/>''Tis based upon the sprinkling of the blood,<br/>And it ever shall endure.<br/>',NULL,1383,1383);
INSERT INTO stanza VALUES('E266','3','With God''s own essence it anoints me,<br/>God to know subjectively,<br/>That I may have His very element<br/>Fully saturating me.<br/>',NULL,1384,1384);
INSERT INTO stanza VALUES('E266','4','''Tis by this inner life-anointing<br/>I in fellowship may move;<br/>In God, the light of truth, I''m walking,<br/>And the love of grace I prove.<br/>',NULL,1385,1385);
INSERT INTO stanza VALUES('E267','1','Fill me with Thy gracious Spirit,<br/>Fill my longing spirit now;<br/>Fill me with Thy hallowed presence,<br/>Come, dear Lord, and fill me now!<br/>',NULL,1386,1386);
INSERT INTO stanza VALUES('E267','chorus','Fill me now! Fill me now!<br/>Fill me with Thy Spirit now!<br/>Strip me wholly, empty throughly,<br/>Fill me with Thy Spirit now!<br/>',NULL,1387,1387);
INSERT INTO stanza VALUES('E267','2','Thou can''st fill me with Thy Spirit,<br/>Though I cannot tell Thee how;<br/>But I need Thee, greatly need Thee;<br/>Come, dear Lord, and fill me now!<br/>',NULL,1388,1388);
INSERT INTO stanza VALUES('E267','3','I am weakness, full of weakness;<br/>At Thy sacred feet I bow;<br/>By Thy blest, eternal Spirit,<br/>Fill with strength, and fill me now!<br/>',NULL,1389,1389);
INSERT INTO stanza VALUES('E267','4','Cleanse and comfort, bless and save me;<br/>Fill my broken spirit now!<br/>Thou art comforting and saving,<br/>Thou art sweetly filling now.<br/>',NULL,1390,1390);
INSERT INTO stanza VALUES('E268','1','How I praise Thee, precious Savior,<br/>That Thy love laid hold of me;<br/>Thou hast saved and cleansed and filled me,<br/>That I might Thy channel be.<br/>',NULL,1391,1391);
INSERT INTO stanza VALUES('E268','chorus','Channels only, blessed Master,<br/>But with all Thy wondrous grace,<br/>Flowing through us, Thou canst use us<br/>Every hour in every place.<br/>',NULL,1392,1392);
INSERT INTO stanza VALUES('E268','2','Just a channel, full of blessing,<br/>To the thirsty hearts around;<br/>To tell out Thy full salvation,<br/>All Thy loving message sound.<br/>',NULL,1393,1393);
INSERT INTO stanza VALUES('E268','3','Emptied that Thou shouldest fill me,<br/>A clean vessel in Thine hand;<br/>With no strength but as Thou givest<br/>Graciously with each command.<br/>',NULL,1394,1394);
INSERT INTO stanza VALUES('E268','4','Witnessing Thy grace to save me,<br/>Setting free from self and sin;<br/>Thou hast bought me to possess me,<br/>In Thy fulness, Lord, come in.<br/>',NULL,1395,1395);
INSERT INTO stanza VALUES('E268','5','O Lord, fill now with Thy Spirit<br/>Hearts that full surrender know;<br/>That the streams of living water<br/>From our inner man may flow.<br/>',NULL,1396,1396);
INSERT INTO stanza VALUES('E269','1','O Lord, with Thy Holy Ghost,<br/>Fill me to the uttermost;<br/>Let my life Thy channel be,<br/>Just a channel, Lord, for Thee;<br/>Through me all Thy riches pour,<br/>Give me ever more and more.<br/>',NULL,1397,1397);
INSERT INTO stanza VALUES('E269','2','O Lord, with Thy Holy Ghost,<br/>Fill me to the uttermost;<br/>Be it unto me, O Lord,<br/>Now, according to Thy word;<br/>Let the life of Jesus be,<br/>Ever filling, even me.<br/>',NULL,1398,1398);
INSERT INTO stanza VALUES('E269','3','O Lord, with Thy Holy Ghost,<br/>Fill me to the uttermost;<br/>Cleansed and holy, pure and clean,<br/>Let the life of Christ be seen;<br/>Hold o''er me Thy gracious sway,<br/>Every hour of every day.<br/>',NULL,1399,1399);
INSERT INTO stanza VALUES('E269','4','O Lord, with Thy Holy Ghost,<br/>Fill me to the uttermost;<br/>For Thy love, Thy light, Thy grace,<br/>Just a channel all my days;<br/>Till my Savior''s face I see,<br/>Fill me, Lord, fill even me.<br/>',NULL,1400,1400);
INSERT INTO stanza VALUES('E270','1','Lord, in Thy Spirit, take and fill my heart;<br/>Wean it from earth, through all its pulses move;<br/>Into my spirit all Thy grace impart,<br/>And make me love Thee as I ought to love.<br/>',NULL,1401,1401);
INSERT INTO stanza VALUES('E270','2','I ask no dream, no prophet ecstasies,<br/>No sudden rending of the veil of clay,<br/>No angel visitant, no opening skies;<br/>But take the dimness of my soul away.<br/>',NULL,1402,1402);
INSERT INTO stanza VALUES('E270','3','Hast Thou not bid us love Thee, God and King?<br/>All, all Thine own — soul, heart and strength and mind.<br/>I see Thy cross — there teach my heart to cling.<br/>Oh, let me seek Thee, and, oh, let me find.<br/>',NULL,1403,1403);
INSERT INTO stanza VALUES('E270','4','Teach me to feel that Thou art always nigh;<br/>Teach me the struggles of the soul to bear,<br/>To check the rising doubt, the rebel sigh;<br/>Teach me the patience of unanswered prayer.<br/>',NULL,1404,1404);
INSERT INTO stanza VALUES('E270','5','Teach me to love Thee with a virgin love,<br/>One holy passion filling all my frame;<br/>Thus all the riches of Thyself to prove,<br/>My heart an altar, and Thy love the flame.<br/>',NULL,1405,1405);
INSERT INTO stanza VALUES('E271','1','Of the Spirit born in spirit,<br/>As the sons of God indeed,<br/>We possess the Holy Spirit,<br/>Dwelling in us for all need.<br/>Yet we still need more of Him, Lord,<br/>That we may be full of Thee;<br/>May Thou fill us with Thy Spirit,<br/>Give us life abundantly.<br/>',NULL,1406,1406);
INSERT INTO stanza VALUES('E271','2','Lord, we know the Spirit in us,<br/>But of life Thy Spirit is,<br/>That the riches of Thy fulness<br/>We may share thru what He is.<br/>Yet we still require Thy Spirit<br/>As the power from on high,<br/>That for all Thy work and service,<br/>We may be equipped thereby.<br/>',NULL,1407,1407);
INSERT INTO stanza VALUES('E271','3','Lord, baptize us with Thy Spirit,<br/>Clothe us with Thy pow''r of might;<br/>With this "mantle" of Thy power,<br/>We may then the battle fight.<br/>May Thy wind now blow upon us,<br/>Giving us the tongues of fire,<br/>That, as witnesses anointed,<br/>We''ll fulfill Thy heart''s desire.<br/>',NULL,1408,1408);
INSERT INTO stanza VALUES('E271','4','With the power of Thy Spirit,<br/>Still we need the gifts to share,<br/>That as members we may function<br/>And Thy testimony bear.<br/>By Thy Spirit''s full outpouring,<br/>Lord, impart the gifts we need,<br/>That the building of Thy Body<br/>With Thy blessing might proceed.<br/>',NULL,1409,1409);
INSERT INTO stanza VALUES('E271','5','For Thy glory and Thy kingdom,<br/>May Thou hear Thy Body''s cry!<br/>Now fulfill Thy holy purpose,<br/>All our hunger satisfy.<br/>May we all partake Thy Spirit,<br/>Him apply in many ways;<br/>His infilling, His outpouring,<br/>And His gifts to share always.<br/>',NULL,1410,1410);
INSERT INTO stanza VALUES('E272','1','Christ indeed was born of Spirit<br/>When He came a man to be;<br/>And before His service started,<br/>With the Spirit filled was He.<br/>Yet He still received the baptism<br/>Of the Spirit from on high<br/>When He came to start His service<br/>And was clothed with pow''r thereby.<br/>',NULL,1411,1411);
INSERT INTO stanza VALUES('E272','2','Peter and the Lord''s disciples<br/>All were Spirit born and filled,<br/>Breathing in the Holy Spirit<br/>As on them Christ breathed and willed.<br/>Yet they still received the baptism<br/>Of the Spirit from on high<br/>When they were equipped for service,<br/>And were clothed with pow''r thereby.<br/>',NULL,1412,1412);
INSERT INTO stanza VALUES('E272','3','Saul of Tarsus, the Ephesians,<br/>And Samaritans believed;<br/>Thus by Spirit generated,<br/>Of His fulness they received.<br/>Yet they still received the baptism<br/>Of the Spirit from on high<br/>When some laid their hands upon them,<br/>And were clothed with pow''r thereby.<br/>',NULL,1413,1413);
INSERT INTO stanza VALUES('E272','4','We are also born of Spirit<br/>On the day when we believe,<br/>And of Him we now are drinking<br/>As we daily Him receive.<br/>Yet we also must be baptized<br/>With the Spirit from on high,<br/>Thus to be equipped for service,<br/>And be clothed with pow''r thereby.<br/>',NULL,1414,1414);
INSERT INTO stanza VALUES('E272','5','Lord, baptize us with Thy Spirit!<br/>This is what we need today;<br/>Clothe us with Thy heav''nly power,<br/>Bring us under its full sway.<br/>Oh, baptize us in this hour!<br/>This is all our earnest cry;<br/>Now on us repeat Thine answer,<br/>Clothe with power from on high.<br/>',NULL,1415,1415);
INSERT INTO stanza VALUES('E273','1','Lord, we come to Thee, and with liberty<br/>Claim we now from Thee pow''r of might;<br/>For Thy kingdom''s sake, may we pow''r partake,<br/>Sitting in the heavenlies to fight.<br/>',NULL,1416,1416);
INSERT INTO stanza VALUES('E273','chorus','Power! Power! Clothe us with Thy power!<br/>With Thy mighty power from on high!<br/>Power! Power! Clothe us with Thy power!<br/>Boldly, as Thy Body, now we cry!<br/>',NULL,1417,1417);
INSERT INTO stanza VALUES('E273','2','Lord, we look to Thee and with certainty<br/>Claim we now from Thee show''r divine,<br/>For Thy Body''s sake, may we show''r partake,<br/>Thus be fitted for the work of Thine.<br/>',NULL,1418,1418);
INSERT INTO stanza VALUES('E273','chorus','Shower! Shower! Pour on us Thy shower!<br/>Pour Thy heav''nly shower from on high!<br/>Shower! Shower! Pour on us Thy shower!<br/>Boldly, as Thy Body, now we cry!<br/>',NULL,1419,1419);
INSERT INTO stanza VALUES('E273','3','Lord, we wait on Thee, and with surety<br/>Claim we now from Thee fire divine.<br/>For Thy gospel''s sake, may we fire partake,<br/>That the people''s heart Thou may refine.<br/>',NULL,1420,1420);
INSERT INTO stanza VALUES('E273','chorus','Fire! Fire! Give us tongues of fire!<br/>To proclaim Thy message from on high!<br/>Fire! Fire! Give us tongues of fire!<br/>Boldly, as Thy Body, now we cry!<br/>',NULL,1421,1421);
INSERT INTO stanza VALUES('E274','1','O Lord, we seek the power we need;<br/>We are so weak in word and in deed<br/>And in Thy service cannot proceed,<br/>Clothe us with pow''r we pray!<br/>',NULL,1422,1422);
INSERT INTO stanza VALUES('E274','chorus','We are waiting, and to Thee we bow,<br/>In Thy presence all our need avow;<br/>Give us Thy power, give even now,<br/>Clothe us with pow''r today.<br/>',NULL,1423,1423);
INSERT INTO stanza VALUES('E274','2','Lord, come and visit us at this place,<br/>Grant to Thy Church the gifts of Thy grace,<br/>Fully with might our service embrace,<br/>Clothe us with pow''r we pray!<br/>',NULL,1424,1424);
INSERT INTO stanza VALUES('E274','3','Send us Thy power with its full sway,<br/>As Thou didst send on Pentecost day;<br/>Answer our prayer and make no delay,<br/>Clothe us with pow''r we pray!<br/>',NULL,1425,1425);
INSERT INTO stanza VALUES('E274','4','Here, as Thy Body, Thy pow''r we claim;<br/>Claiming by faith in Thy mighty Name,<br/>Thy heav''nly show''r with Thy heav''nly flame;<br/>Clothe us with pow''r we pray!<br/>',NULL,1426,1426);
INSERT INTO stanza VALUES('E275','1','Thy Holy Spirit, Lord, alone<br/>Can meet our need today;<br/>His might alone empow''ring us<br/>Can bring us neath Thy sway.<br/>',NULL,1427,1427);
INSERT INTO stanza VALUES('E275','chorus','Thy Spirit of pow''r with might,<br/>Send in our midst, we pray,<br/>And come upon each seeking soul;<br/>Baptize us with power today.<br/>',NULL,1428,1428);
INSERT INTO stanza VALUES('E275','2','Thy Holy Spirit, Lord, alone<br/>Can grant us Thy desire;<br/>His Power alone can turn our heart<br/>And light the sacred fire.<br/>',NULL,1429,1429);
INSERT INTO stanza VALUES('E275','3','Thy Holy Spirit, Lord, can give<br/>The gifts we seek to share;<br/>His pow''r can signs and wonders work<br/>And stir up holy fear.<br/>',NULL,1430,1430);
INSERT INTO stanza VALUES('E275','4','Thy Holy Spirit, Lord, can bring<br/>The show''r we need this hour;<br/>And while we seek, Lord Jesus, come<br/>In motivating power.<br/>',NULL,1431,1431);
INSERT INTO stanza VALUES('E275','chorus','Thy Spirit of pow''r with might,<br/>Send in our midst, we pray,<br/>And like a rushing, mighty wind<br/>Sweep over our souls today.<br/>',NULL,1432,1432);
INSERT INTO stanza VALUES('E276','1','What a blessed fact! What a tiding glad!<br/>In the Spirit we have been baptized;<br/>Take this settled fact, nothing need we add,<br/>In the Spirit we have been baptized.<br/>',NULL,1433,1433);
INSERT INTO stanza VALUES('E276','chorus','Take it! Take it!<br/>Take now this fact by living faith;<br/>Take it! Take it!<br/>Take now this accomplished fact by faith.<br/>',NULL,1434,1434);
INSERT INTO stanza VALUES('E276','2','In the testament it is clearly told,<br/>In the Spirit we have been baptized;<br/>It is so complete, we need only hold,<br/>In the Spirit we have been baptized.<br/>',NULL,1435,1435);
INSERT INTO stanza VALUES('E276','chorus','Hold it! Hold it!<br/>Hold now this fact by living faith;<br/>Hold it! Hold it!<br/>Hold now this accomplished fact by faith.<br/>',NULL,1436,1436);
INSERT INTO stanza VALUES('E276','3','Christ upon the Church hath His Spirit poured,<br/>In the Spirit we have been baptized;<br/>Share her portion now, share in full accord,<br/>In the Spirit we have been baptized.<br/>',NULL,1437,1437);
INSERT INTO stanza VALUES('E276','chorus','Share it! Share it!<br/>Share now this fact by living faith;<br/>Share it! Share it!<br/>Share now this accomplished fact by faith.<br/>',NULL,1438,1438);
INSERT INTO stanza VALUES('E276','4','With the Body right, on the Body ground,<br/>Move and act on this accomplished fact;<br/>Sins and doubts condemn, wait no more around,<br/>But by living faith now move and act.<br/>',NULL,1439,1439);
INSERT INTO stanza VALUES('E276','chorus','Act now! Act now!<br/>Act on this fact by living faith;<br/>Act now! Act now!<br/>Act on this accomplished fact by faith.<br/>',NULL,1440,1440);
INSERT INTO stanza VALUES('E277','1','Christ the Savior hath ascended<br/>To the heavens far above,<br/>Crowned with glory and with honor<br/>By the Father God in love;<br/>He hath made Him Head of all things,<br/>His supremacy to prove.<br/>',NULL,1441,1441);
INSERT INTO stanza VALUES('E277','2','From this Christ to God ascended<br/>Hath the Spirit been outpoured,<br/>Poured upon the Church, His Body,<br/>That His members be empow''red;<br/>Thus the Lord of all in heaven<br/>Thru His Church will be adored.<br/>',NULL,1442,1442);
INSERT INTO stanza VALUES('E277','3','In the flesh by incarnation,<br/>Into man He God hath brought;<br/>By His death and resurrection,<br/>Into God He man hath brought;<br/>God and man together mingled,<br/>In Himself is fully wrought.<br/>',NULL,1443,1443);
INSERT INTO stanza VALUES('E277','4','Now in heaven by ascension<br/>He is seated on the throne;<br/>All the lordship, all the headship,<br/>He Himself doth fully own;<br/>And by pouring out His Spirit,<br/>He as such might be made known.<br/>',NULL,1444,1444);
INSERT INTO stanza VALUES('E277','5','By this outpour, His descension<br/>On the Church was realized;<br/>''Tis by this, that in His Spirit<br/>All the Church He hath baptized;<br/>Thus the baptism of the Spirit<br/>Was forever actualized.<br/>',NULL,1445,1445);
INSERT INTO stanza VALUES('E277','6','Hallelujah, ''tis accomplished,<br/>And accomplished once for all!<br/>Hallelujah, we''re included,<br/>All included, great or small!<br/>Praise Him, He hath sent the Spirit<br/>And baptized the Church withal!<br/>',NULL,1446,1446);
INSERT INTO stanza VALUES('E278','1','The Spirit of life is within us today,<br/>Who''s likened to water our thirst to allay;<br/>Of Him we may drink and be filled thus with Him,<br/>Until as a river He flows from within.<br/>',NULL,1447,1447);
INSERT INTO stanza VALUES('E278','2','The Spirit of pow''r comes upon us today,<br/>Who''s likened to clothing ourselves to array;<br/>In Him we are baptized, with Him we are dressed,<br/>For service equipping with power possessed.<br/>',NULL,1448,1448);
INSERT INTO stanza VALUES('E278','3','The Spirit of life is as breath glorious,<br/>As spirit of life it is breathed into us;<br/>The Spirit of pow''r doth the wind typify,<br/>Which bloweth upon us with pow''r from on high.<br/>',NULL,1449,1449);
INSERT INTO stanza VALUES('E278','4','Into His disciples the risen Lord breathed,<br/>The Spirit of life thus to them He bequeathed;<br/>Th'' ascended Lord poured at the Pentecost hour<br/>Upon His disciples the Spirit of pow''r.<br/>',NULL,1450,1450);
INSERT INTO stanza VALUES('E278','5','The Spirit of life is within as the life,<br/>The Spirit of power is giv''n for this life;<br/>As blowing of wind brings the fresh air to breathe,<br/>The Spirit of power to life doth bequeath.<br/>',NULL,1451,1451);
INSERT INTO stanza VALUES('E278','6','These are not two spirits apart and afar,<br/>But of the one Spirit the two functions are,<br/>To clothe us with God and to fill us within,<br/>That we may be thoroughly mingled with Him.<br/>',NULL,1452,1452);
INSERT INTO stanza VALUES('E278','7','Lord, fill with Thy Spirit of life every part,<br/>That we may grow up in Thy life as Thou art;<br/>And clothe us without with Thy Spirit of pow''r<br/>Thy will to fulfill in Thy service each hour.<br/>',NULL,1453,1453);
INSERT INTO stanza VALUES('E279','1','First the blood, and then the ointment,<br/>Cleansing, then anointing comes;<br/>If we pass not thru Golgotha,<br/>Ne''er to Pentecost we''ll come.<br/>If the blood has never cleansed us,<br/>Ne''er the Spirit''s pow''r we''ll know,<br/>If for Christ we''d truly witness,<br/>Self-life to the Cross must go.<br/>',NULL,1454,1454);
INSERT INTO stanza VALUES('E279','chorus','Through the Cross, O Lord, I pray,<br/>Put my soul-life all away;<br/>Make me any price to pay,<br/>Full anointing to receive.<br/>',NULL,1455,1455);
INSERT INTO stanza VALUES('E279','2','Christ, the Rock, must first be smitten,<br/>That the living water flow;<br/>Without death the Spirit''s fulness<br/>Ne''er could dwell in man below.<br/>If with Christ we die completely,<br/>Willing thus our all to lose,<br/>He will clothe us with His power<br/>And to win the world will use.<br/>',NULL,1456,1456);
INSERT INTO stanza VALUES('E279','3','First the altar, then the fire,<br/>If no loss, there''ll be no gain;<br/>If our all has not been offered,<br/>To the throne we''ll ne''er attain.<br/>If to sacrifice we''re willing,<br/>All forsaking, God t''obey,<br/>He to us will be committed<br/>And thru us His pow''r display.<br/>',NULL,1457,1457);
INSERT INTO stanza VALUES('E279','4','First we must prepare the vessels<br/>That the Oil they may contain;<br/>Dig the valley full of ditches<br/>That they may be filled with Rain.<br/>First we must go thru the Jordan<br/>Ere anointed from above;<br/>First in death we must be baptized,<br/>Then experience the Dove.<br/>',NULL,1458,1458);
INSERT INTO stanza VALUES('E279','5','When we see the ripened harvest<br/>Of the golden countryside,<br/>We may know that many seeds have<br/>Fallen to the earth and died.<br/>Ere the fruit of life may blossom,<br/>We must surely suffer death;<br/>If with Christ we''ve not been buried,<br/>We''ll not feel the Spirit''s breath.<br/>',NULL,1459,1459);
INSERT INTO stanza VALUES('E279','6','Since it must be thus, I pray, Lord,<br/>Help me go the narrow way;<br/>Deal with pride and make me willing<br/>Thus to suffer, Thee t''obey.<br/>I for greater power pray not,<br/>Deeper death is what I need;<br/>All the meaning of the Cross, Lord,<br/>Work in me-for this I plead.<br/>',NULL,1460,1460);
INSERT INTO stanza VALUES('E280','1','Lord, may Thy blood now cleanse me,<br/>Wash all my sins away,<br/>That with Thy Holy Spirit<br/>Thou may anoint, I pray.<br/>My service, I confess, Lord,<br/>Is failure-full and weak;<br/>The filling of Thy Spirit<br/>To live for Thee I seek.<br/>',NULL,1461,1461);
INSERT INTO stanza VALUES('E280','chorus','Oh, from myself deliver,<br/>From all its misery;<br/>I''d henceforth be forever<br/>Completely filled with Thee.<br/>',NULL,1462,1462);
INSERT INTO stanza VALUES('E280','2','Oh, Lord, how dry my heart is,<br/>It yearns and pants for Thee;<br/>The filling of Thy Spirit<br/>Is now my fervent plea.<br/>Within the smitten Rock, Lord,<br/>I would entirely hide;<br/>Pour thru Thy living water,<br/>Till I am satisfied.<br/>',NULL,1463,1463);
INSERT INTO stanza VALUES('E280','3','How cold my heart has been, Lord,<br/>How slow obeying Thee;<br/>So fill me with Thy Spirit,<br/>I''ll ne''er rebellious be.<br/>I lie upon Thy altar<br/>And dare not move away;<br/>Oh, may Thy flame descending<br/>Consume my all, I pray.<br/>',NULL,1464,1464);
INSERT INTO stanza VALUES('E280','4','Oh, may Thy Cross within me<br/>Deepen its work and burn,<br/>In me enlarge Thy measure,<br/>And me to ashes turn.<br/>Oh, may Thy Spirit fill me<br/>Each day more than before,<br/>And may Thy living water<br/>On me and thru me pour.<br/>',NULL,1465,1465);
INSERT INTO stanza VALUES('E281','1','Lord, the Spirit, Truth divine,<br/>Dawn upon this heart of mine;<br/>Word of God, and inward light,<br/>Wake my spirit, clear my sight.<br/>',NULL,1466,1466);
INSERT INTO stanza VALUES('E281','2','Lord, the Spirit, Love divine,<br/>Glow within this heart of mine,<br/>Kindle every high desire,<br/>Perish self in Thy pure fire.<br/>',NULL,1467,1467);
INSERT INTO stanza VALUES('E281','3','Lord, the Spirit, Power divine,<br/>Fill and nerve this will of mine;<br/>By Thee may I strongly live,<br/>Bravely bear, and nobly strive.<br/>',NULL,1468,1468);
INSERT INTO stanza VALUES('E281','5','Lord, the Spirit, Peace divine,<br/>Still this restless heart of mine,<br/>Speak to calm this tossing sea,<br/>Stayed in Thy tranquility.<br/>',NULL,1469,1469);
INSERT INTO stanza VALUES('E281','6','Lord, the Spirit, Joy divine,<br/>Gladden Thou this heart of mine;<br/>In the desert ways I''ll sing:<br/>Spring, O Well, forever spring!<br/>(Repeat the last line of each stanza)<br/>',NULL,1470,1470);
INSERT INTO stanza VALUES('E282','1','Lord of light, with light divine,<br/>Shine upon this heart of mine;<br/>Chase the shades of night away,<br/>Turn the darkness into day.<br/>',NULL,1471,1471);
INSERT INTO stanza VALUES('E282','2','Lord of power, with power divine,<br/>Cleanse this guilty heart of mine;<br/>Long has sin without control<br/>Held dominion o''er my soul.<br/>',NULL,1472,1472);
INSERT INTO stanza VALUES('E282','3','Lord of joy, with joy divine,<br/>Cheer this saddened heart of mine;<br/>Bid my many woes depart,<br/>Heal my wounded, bleeding heart.<br/>',NULL,1473,1473);
INSERT INTO stanza VALUES('E282','4','Lord, the Spirit, all divine,<br/>Dwell within this heart of mine;<br/>Cast down every idol throne,<br/>Reign supreme, and reign alone.<br/>',NULL,1474,1474);
INSERT INTO stanza VALUES('E283','1','Lord, Thou knowest all the hunger<br/>Of the heart that seeks Thee now;<br/>How my soul hath long been craving<br/>What Thou only canst bestow.<br/>',NULL,1475,1475);
INSERT INTO stanza VALUES('E283','chorus','Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1476,1476);
INSERT INTO stanza VALUES('E283','2','Failure in my walk and witness,<br/>Failure in my work I see;<br/>Fruitless toil, un-Christlike living,<br/>Calling forth no praise to Thee.<br/>Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1477,1477);
INSERT INTO stanza VALUES('E283','3','Now to Thee my soul confesses<br/>All its failure, all its sin;<br/>All the pride, the self-contentment,<br/>All the "secret faults" within.<br/>Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1478,1478);
INSERT INTO stanza VALUES('E283','4','Save me from myself, my Father,<br/>From each subtle form of pride;<br/>Lead me now with Christ to Calvary,<br/>Show me I with Him have died.<br/>Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1479,1479);
INSERT INTO stanza VALUES('E283','5','No more let it be my working,<br/>Nor my wisdom, love, or power,<br/>But the life of Jesus only,<br/>Passing through me hour by hour.<br/>Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1480,1480);
INSERT INTO stanza VALUES('E283','6','Let the fulness of Thy Spirit<br/>Resting on Him cover me,<br/>That the witness borne to others.<br/>May bring glory, Lord, to Thee.<br/>Seeking now, seeking now,<br/>Let Thy Spirit meet me now.<br/>',NULL,1481,1481);
INSERT INTO stanza VALUES('E283','7','Father, in Thy Son''s Name, pleading,<br/>I believe my prayer is heard;<br/>And I praise Thee for the answer,<br/>Resting simply on Thy word.<br/>',NULL,1482,1482);
INSERT INTO stanza VALUES('E283','chorus','Praising now, praising now,<br/>Thou hast answered, Lord, I know.<br/>',NULL,1483,1483);
INSERT INTO stanza VALUES('E284','1','Loved with everlasting love,<br/>Led by grace that love to know;<br/>Spirit, breathing from above,<br/>Thou hast taught me it is so.<br/>Oh, this full and perfect peace!<br/>Oh, this transport all divine!<br/>In a love which cannot cease,<br/>I am His, and He is mine.<br/>',NULL,1484,1484);
INSERT INTO stanza VALUES('E284','2','Heaven above is softer blue,<br/>Earth around is sweeter green;<br/>Something lives in every hue<br/>Christless eyes have never seen:<br/>Birds with gladder songs o''erflow,<br/>Flow''rs with deeper beauties shine,<br/>Since I know, as now I know,<br/>I am His, and He is mine.<br/>',NULL,1485,1485);
INSERT INTO stanza VALUES('E284','3','Things that once were wild alarms<br/>Cannot now disturb my rest;<br/>Closed in everlasting arms,<br/>Pillowed on the loving breast.<br/>Oh, to lie forever here,<br/>Doubt and care and self resign,<br/>While He whispers in my ear,<br/>I am His, and He is mine.<br/>',NULL,1486,1486);
INSERT INTO stanza VALUES('E284','4','His forever, only His:<br/>Who the Lord and me shall part?<br/>Ah, with what a rest of bliss<br/>Christ can fill the loving heart.<br/>Heaven and earth may fade and flee,<br/>Firstborn light in gloom decline;<br/>But, while God and I shall be,<br/>I am His, and He is mine.<br/>',NULL,1487,1487);
INSERT INTO stanza VALUES('E285','1','Come and rejoice with me!<br/>For once my heart was poor,<br/>And I have found a treasury<br/>Of love, a boundless store.<br/>',NULL,1488,1488);
INSERT INTO stanza VALUES('E285','2','Come and rejoice with me!<br/>I, once so sick at heart,<br/>Have met with One who knows my case,<br/>And knows the healing art.<br/>',NULL,1489,1489);
INSERT INTO stanza VALUES('E285','3','Come and rejoice with me!<br/>For I was wearied sore,<br/>And I have found a mighty arm<br/>Which holds me evermore.<br/>',NULL,1490,1490);
INSERT INTO stanza VALUES('E285','4','Come and rejoice with me!<br/>My feet so wide did roam,<br/>And One has brought me from afar,<br/>To find in Him my home.<br/>',NULL,1491,1491);
INSERT INTO stanza VALUES('E285','5','Come and rejoice with me!<br/>For I have found a Friend<br/>Who knows my heart''s most secret depths,<br/>Yet loves me without end.<br/>',NULL,1492,1492);
INSERT INTO stanza VALUES('E285','6','I knew not of His love;<br/>And He had loved so long,<br/>With love so faithful and so deep,<br/>So tender and so strong.<br/>',NULL,1493,1493);
INSERT INTO stanza VALUES('E285','7','And now I know it all,<br/>Have heard and known His voice,<br/>And hear it still from day to day.<br/>Can I enough rejoice?<br/>',NULL,1494,1494);
INSERT INTO stanza VALUES('E286','1','Of Jesus'' love that sought me,<br/>When I was lost in sin;<br/>Of wondrous grace that brought me<br/>Back to His fold again;<br/>Of heights and depths of mercy,<br/>Far deeper than the sea,<br/>And higher than the heavens,<br/>My theme shall ever be.<br/>',NULL,1495,1495);
INSERT INTO stanza VALUES('E286','chorus','Sweeter as the years go by,<br/>Sweeter as the years go by;<br/>Richer, fuller, deeper,<br/>Jesus'' love is sweeter,<br/>Sweeter as the years go by.<br/>',NULL,1496,1496);
INSERT INTO stanza VALUES('E286','2','He trod in old Judea<br/>Life''s pathway long ago;<br/>The people thronged about Him,<br/>His saving grace to know.<br/>He healed the broken-hearted,<br/>And caused the blind to see;<br/>And still His great heart yearneth<br/>In love for even me.<br/>',NULL,1497,1497);
INSERT INTO stanza VALUES('E287','1','Jesus, Jesus, Jesus!<br/>Sweetest Name on earth,<br/>How can I, a sinner,<br/>Come to know its worth?<br/>',NULL,1498,1498);
INSERT INTO stanza VALUES('E287','2','Oh! The sinful sorrow,<br/>Oh! The strangest shame,<br/>That I saw no beauty<br/>In that sacred Name.<br/>',NULL,1499,1499);
INSERT INTO stanza VALUES('E287','3','Never felt the sweetness!<br/>Never knew the grace,<br/>Never saw the love-pain<br/>In that wounded face!<br/>',NULL,1500,1500);
INSERT INTO stanza VALUES('E287','4','Never found the mystery<br/>In that simple word —<br/>Jesus, Jesus, Jesus,<br/>Savior, Lover, Lord.<br/>',NULL,1501,1501);
INSERT INTO stanza VALUES('E287','5','Now ''tis past and over.<br/>Gone my guilt and shame;<br/>Jesus, Jesus did it,<br/>Glory to His Name!<br/>',NULL,1502,1502);
INSERT INTO stanza VALUES('E287','6','Wonderful compassion,<br/>Reaching even me;<br/>Bows my humbled spirit<br/>In captivity.<br/>',NULL,1503,1503);
INSERT INTO stanza VALUES('E287','7','Jesus! Jesus! Jesus!<br/>Loved me in my shame.<br/>Oh! The joy and rapture<br/>Of that sacred Name.<br/>',NULL,1504,1504);
INSERT INTO stanza VALUES('E288','1','I''ve found a Friend, oh, such a Friend!<br/>He loved me ere I knew Him;<br/>He drew me with the cords of love,<br/>And thus He bound me to Him.<br/>And round my heart still closely twine<br/>Those ties which naught can sever,<br/>For I am His, and He is mine,<br/>Forever and forever.<br/>',NULL,1505,1505);
INSERT INTO stanza VALUES('E288','2','I''ve found a Friend, oh, such a Friend!<br/>He bled, He died to save me;<br/>And not alone the gift of life,<br/>But His own self He gave me.<br/>Naught that I have my own I call,<br/>I hold it for the Giver;<br/>My heart, my strength, my life, my all,<br/>Are His, and His forever.<br/>',NULL,1506,1506);
INSERT INTO stanza VALUES('E288','3','I''ve found a Friend, oh, such a Friend!<br/>So kind, and true, and tender,<br/>So wise a Counselor and Guide,<br/>So mighty a Defender!<br/>From Him who loves me now so well,<br/>What power my soul can sever?<br/>Shall life or death, or earth or hell?<br/>No, I am His forever.<br/>',NULL,1507,1507);
INSERT INTO stanza VALUES('E289','1','I stand all amazed at the love Jesus offers me,<br/>Confused at the grace that so fully He proffers me;<br/>I tremble to know that for me He was crucified,<br/>That for me, a sinner, He suffered, He bled and died.<br/>',NULL,1508,1508);
INSERT INTO stanza VALUES('E289','chorus','O it is wonderful that He should care for me<br/>Enough to die for me!<br/>O it is wonderful, wonderful to me!<br/>',NULL,1509,1509);
INSERT INTO stanza VALUES('E289','2','I marvel that He would descend from His throne divine<br/>To rescue a soul so rebellious and proud as mine;<br/>That He should extend His great love unto such as I,<br/>Sufficient to own, to redeem, and to justify.<br/>',NULL,1510,1510);
INSERT INTO stanza VALUES('E289','3','I think of His side, pierced and bleeding to pay the debt,<br/>Such mercy, such love and devotion can I forget?<br/>No, no! I will praise and adore at the mercy seat,<br/>And testify all my desires He doth fully meet.<br/>',NULL,1511,1511);
INSERT INTO stanza VALUES('E290','1','I stand amazed in the presence<br/>Of Jesus the Nazarene,<br/>And wonder how He could love me,<br/>A sinner condemned, unclean.<br/>',NULL,1512,1512);
INSERT INTO stanza VALUES('E290','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me!<br/>',NULL,1513,1513);
INSERT INTO stanza VALUES('E290','2','For me it was in the garden,<br/>He prayed: "Not my will, but Thine."<br/>He had no tears for His own griefs,<br/>But sweat-drops of blood for mine.<br/>',NULL,1514,1514);
INSERT INTO stanza VALUES('E290','3','In pity angels beheld Him,<br/>And came from the world of light<br/>To strengthen Him in the sorrows<br/>He bore for my soul that night.<br/>',NULL,1515,1515);
INSERT INTO stanza VALUES('E290','4','He took my sins and my sorrows,<br/>He made them His very own;<br/>He bore the burden to Calv''ry<br/>And suffered, and died alone.<br/>',NULL,1516,1516);
INSERT INTO stanza VALUES('E290','5','When with the ransomed in glory<br/>His face I at last shall see,<br/>''Twill be my joy through the ages<br/>To sing of His love for me.<br/>',NULL,1517,1517);
INSERT INTO stanza VALUES('E291','1','I am so glad that our Father in heav''n<br/>Tells of His love in the Book He has giv''n;<br/>Wonderful things in the Bible I see:<br/>This is the dearest, that Jesus loves me.<br/>',NULL,1518,1518);
INSERT INTO stanza VALUES('E291','chorus','I am so glad that Jesus loves me,<br/>Jesus loves me, Jesus loves me;<br/>I am so glad that Jesus loves me,<br/>Jesus loves even me.<br/>',NULL,1519,1519);
INSERT INTO stanza VALUES('E291','2','Though I forget Him and wander away,<br/>Still He doth love me whenever I stray;<br/>Back to His dear loving arms would I flee,<br/>When I remember that Jesus loves me.<br/>',NULL,1520,1520);
INSERT INTO stanza VALUES('E291','3','Oh, if there''s only one song I can sing,<br/>When in His beauty I see the great King,<br/>This shall my song in eternity be:<br/>"Oh, what a wonder that Jesus loves me."<br/>',NULL,1521,1521);
INSERT INTO stanza VALUES('E292','1','A debtor to mercy alone,<br/>Of covenant mercy I sing,<br/>Nor fear, with God''s righteousness on,<br/>My person and off''rings to bring.<br/>The terrors of law and of God<br/>With me can have nothing to do;<br/>My Savior''s obedience and blood<br/>Hide all my transgressions from view.<br/>',NULL,1522,1522);
INSERT INTO stanza VALUES('E292','2','The work which His goodness began,<br/>The arm of His strength will complete;<br/>His promise is Yea and Amen,<br/>And never was forfeited yet.<br/>Things future, nor things that are now,<br/>Not all things below or above,<br/>Can make Him His purpose forego,<br/>Or sever my soul from His love.<br/>',NULL,1523,1523);
INSERT INTO stanza VALUES('E292','3','My name from the palms of His hands<br/>Eternity will not erase;<br/>Imprest on His heart, it remains<br/>In marks of indelible grace.<br/>Yes! I to the end shall endure,<br/>As sure as the earnest is giv''n;<br/>More happy, but not more secure,<br/>When all earthly ties have been riv''n.<br/>',NULL,1524,1524);
INSERT INTO stanza VALUES('E293','1','Cleansed in our Savior''s precious Blood,<br/>Filled with the fulness of our God,<br/>Walking by faith the path He trod,<br/>Hallelujah! Hallelujah!<br/>',NULL,1525,1525);
INSERT INTO stanza VALUES('E293','2','Leaning our heads on Jesus'' breast,<br/>Knowing the joy of that sweet rest,<br/>Finding in Him the chief, the best,<br/>Hallelujah! Hallelujah!<br/>',NULL,1526,1526);
INSERT INTO stanza VALUES('E293','3','Kept by His pow''r from day to day,<br/>Held by His hand, we cannot stray,<br/>Glory to glory all the way,<br/>Hallelujah! Hallelujah!<br/>',NULL,1527,1527);
INSERT INTO stanza VALUES('E293','4','Living in us His own pure life,<br/>Giving us rest from inward strife,<br/>From strength to strength, from death to life,<br/>Hallelujah! Hallelujah!<br/>',NULL,1528,1528);
INSERT INTO stanza VALUES('E293','5','O what a Savior we have found;<br/>Well may we make the world resound<br/>With one continual joyous sound,<br/>Hallelujah! Hallelujah!<br/>',NULL,1529,1529);
INSERT INTO stanza VALUES('E294','1','Gone from my heart the world and all its charms;<br/>Now through the blood I''m saved from all alarms;<br/>Down at the cross my heart is bending low;<br/>The precious blood of Jesus cleanses white as snow.<br/>',NULL,1530,1530);
INSERT INTO stanza VALUES('E294','chorus','I love Him, I love Him, .<br/>Because He first loved me,<br/>And purchased my salvation on Calv''ry''s tree.<br/>',NULL,1531,1531);
INSERT INTO stanza VALUES('E294','2','Once I was lost, and fallen deep in sin;<br/>Once was a slave to passions fierce within;<br/>Once was afraid to meet an angry God,<br/>But now I''m cleansed from every stain thro'' Jesus'' blood.<br/>',NULL,1532,1532);
INSERT INTO stanza VALUES('E294','3','Once I was bound, but now I am set free;<br/>Once I was blind, but now the light I see;<br/>Once I was dead, but now in Christ I live,<br/>To tell the world around the peace that He doth give.<br/>',NULL,1533,1533);
INSERT INTO stanza VALUES('E295','1','God''s Christ, who is my righteousness,<br/>My beauty is, my glorious dress;<br/>Midst flaming worlds, in this arrayed,<br/>With joy shall I lift up my head.<br/>',NULL,1534,1534);
INSERT INTO stanza VALUES('E295','2','Lord, I believe Thy precious blood,<br/>Which, at the mercy seat of God,<br/>Forever doth for sinners plead,<br/>For me, e''en for my soul, was shed.<br/>',NULL,1535,1535);
INSERT INTO stanza VALUES('E295','3','Lord, I believe were sinners more<br/>Than sands upon the ocean shore,<br/>Thou hast for all a ransom paid,<br/>For all a full redemption made.<br/>',NULL,1536,1536);
INSERT INTO stanza VALUES('E295','4','Bold can I stand in every way,<br/>For who aught to my charge shall lay?<br/>Fully, by Thee, absolved I am<br/>From sin and fear, from guilt and shame.<br/>',NULL,1537,1537);
INSERT INTO stanza VALUES('E295','5','This spotless robe the same appears,<br/>When ruined nature sinks in years;<br/>No age can change its glorious hue,<br/>Its glory is forever new.<br/>',NULL,1538,1538);
INSERT INTO stanza VALUES('E295','6','Thou God of power, Thou God of love,<br/>Let all Thy saints Thy mercy prove;<br/>Our beauty this, our glorious dress,<br/>Jesus the Lord, our Righteousness.<br/>',NULL,1539,1539);
INSERT INTO stanza VALUES('E296','1','And can it be that I should gain<br/>An int''rest in the Savior''s blood?<br/>Died He for me, who caused His pain?<br/>For me, who Him to death pursued?<br/>Amazing love! How can it be<br/>That Thou, my God, shouldst die for me?<br/>Amazing love! How can it be<br/>That Thou, my God, shouldst die for me?<br/>',NULL,1540,1540);
INSERT INTO stanza VALUES('E296','2','''Tis mystery all! The Immortal dies!<br/>Who can explore His strange design?<br/>In vain the firstborn seraph tries<br/>To sound the depths of love Divine!<br/>''Tis mercy all! Let earth adore,<br/>Let angel minds inquire no more.<br/>''Tis mercy all! Let earth adore,<br/>Let angel minds inquire no more.<br/>',NULL,1541,1541);
INSERT INTO stanza VALUES('E296','3','He left His Father''s throne above,<br/>So free, so infinite His grace;<br/>Emptied Himself of all but love,<br/>And bled for Adam''s helpless race:<br/>''Tis mercy all, immense and free;<br/>For, O my God, it found out me.<br/>''Tis mercy all, immense and free;<br/>For, O my God, it found out me.<br/>',NULL,1542,1542);
INSERT INTO stanza VALUES('E296','4','Long my imprisoned spirit lay<br/>Fast bound in sin and nature''s night;<br/>Thine eye diffused a quickening ray,<br/>I woke, the dungeon flamed with light;<br/>My chains fell off, my heart was free,<br/>I rose, went forth, and followed Thee.<br/>My chains fell off, my heart was free,<br/>I rose, went forth, and followed Thee.<br/>',NULL,1543,1543);
INSERT INTO stanza VALUES('E296','5','No condemnation now I dread;<br/>Jesus, and all in Him, is mine!<br/>Alive in Him, my living Head,<br/>And clothed in righteousness Divine,<br/>Bold I approach the eternal throne,<br/>And claim the crown, through Christ my own.<br/>Bold I approach the eternal throne,<br/>And claim the crown, through Christ my own.<br/>',NULL,1544,1544);
INSERT INTO stanza VALUES('E297','1','"No condemnation!" precious word!<br/>Consider it, my soul!<br/>Thy sins were all on Jesus laid,<br/>His stripes have made thee whole.<br/>',NULL,1545,1545);
INSERT INTO stanza VALUES('E297','2','In God''s own presence now for us<br/>The Savior doth appear;<br/>The saints, as jewels on His heart,<br/>Jesus doth ever bear.<br/>',NULL,1546,1546);
INSERT INTO stanza VALUES('E297','3','"No condemnation!" O my soul,<br/>''Tis God that speaks the word;<br/>Perfect in comeliness art thou<br/>In Christ, the risen Lord.<br/>',NULL,1547,1547);
INSERT INTO stanza VALUES('E297','4','Teach me, O God, to fix mine eyes<br/>On Christ, the spotless Lamb,<br/>So shall I love Thy precious will,<br/>And glorify His name.<br/>',NULL,1548,1548);
INSERT INTO stanza VALUES('E298','1','My hope is built on nothing less<br/>Than Jesus Christ, my righteousness;<br/>I dare not trust the sweetest frame,<br/>But wholly lean on Jesus'' name.<br/>',NULL,1549,1549);
INSERT INTO stanza VALUES('E298','chorus','On Christ, the solid Rock, I stand;<br/>All other ground is sinking sand,<br/>All other ground is sinking sand.<br/>',NULL,1550,1550);
INSERT INTO stanza VALUES('E298','2','When darkness veils His lovely face,<br/>I rest on His unchanging grace;<br/>In every high and stormy gale,<br/>My anchor holds within the veil.<br/>',NULL,1551,1551);
INSERT INTO stanza VALUES('E298','3','His oath, His covenant, His blood,<br/>Support me in the whelming flood;<br/>When all around my soul gives way,<br/>He then is all my hope and stay.<br/>',NULL,1552,1552);
INSERT INTO stanza VALUES('E298','4','When He shall come with trumpet sound,<br/>Oh, may I then in Him be found;<br/>In Him, my righteousness, alone<br/>Faultless to stand before the throne.<br/>',NULL,1553,1553);
INSERT INTO stanza VALUES('E299','1','A mind at perfect peace with God;<br/>O what a word is this!<br/>A sinner reconciled through blood;<br/>This, this indeed is peace.<br/>',NULL,1554,1554);
INSERT INTO stanza VALUES('E299','2','By nature and by practice far,<br/>How very far from God,<br/>Yet now by grace brought nigh to Him,<br/>Through faith in Jesus'' blood.<br/>',NULL,1555,1555);
INSERT INTO stanza VALUES('E299','3','So nigh, so very nigh to God,<br/>I cannot nearer be;<br/>For in the person of His Son<br/>I am as near as He.<br/>',NULL,1556,1556);
INSERT INTO stanza VALUES('E299','4','So dear, so very dear to God,<br/>More dear I cannot be;<br/>The love wherewith He loves the Son,<br/>Such is His love to me.<br/>',NULL,1557,1557);
INSERT INTO stanza VALUES('E299','5','Why should I ever anxious be,<br/>Since such a God is mine?<br/>He watches o''er me night and day,<br/>And tells me "Mine is thine."<br/>',NULL,1558,1558);
INSERT INTO stanza VALUES('E300','1','Arise, my soul, arise!<br/>Shake off thy guilty fears;<br/>The bleeding Sacrifice<br/>In my behalf appears.<br/>Before the throne my Surety stands;<br/>My name is written on His hands.<br/>',NULL,1559,1559);
INSERT INTO stanza VALUES('E300','2','He ever lives above<br/>For me to intercede,<br/>His all-redeeming love,<br/>His precious blood to plead.<br/>His blood was shed for all our race,<br/>And sprinkles now the throne of grace.<br/>',NULL,1560,1560);
INSERT INTO stanza VALUES('E300','3','Five bleeding wounds He bears,<br/>Received on Calvary;<br/>They pour effectual prayers;<br/>They strongly speak for me.<br/>Forgive him, O forgive, they cry,<br/>Nor let that ransomed sinner die!<br/>',NULL,1561,1561);
INSERT INTO stanza VALUES('E300','4','The Father hears Him pray,<br/>His dear anointed One;<br/>He cannot turn away<br/>The presence of His Son.<br/>His Spirit answers to the blood,<br/>And tells me I am born of God.<br/>',NULL,1562,1562);
INSERT INTO stanza VALUES('E300','5','To God I''m reconciled,<br/>His pardoning voice I hear;<br/>He owns me for His child,<br/>I can no longer fear.<br/>With confidence I now draw nigh,<br/>And Father, Abba, Father, cry.<br/>',NULL,1563,1563);
INSERT INTO stanza VALUES('E301','1','Redeemed — how I love to proclaim it!<br/>Redeemed by the blood of the Lamb;<br/>Redeemed through His infinite mercy,<br/>His child, and forever, I am.<br/>',NULL,1564,1564);
INSERT INTO stanza VALUES('E301','chorus','Redeemed, redeemed,<br/>Redeemed by the blood of the Lamb;<br/>Redeemed, redeemed,<br/>His child, and forever, I am.<br/>',NULL,1565,1565);
INSERT INTO stanza VALUES('E301','2','Redeemed and so happy in Jesus,<br/>No language my rapture can tell;<br/>I know that the light of His presence<br/>With me doth continually dwell.<br/>',NULL,1566,1566);
INSERT INTO stanza VALUES('E301','3','I think of my blessed Redeemer,<br/>I think of Him all the day long;<br/>I sing, for I cannot be silent;<br/>His love is the theme of my song.<br/>',NULL,1567,1567);
INSERT INTO stanza VALUES('E301','4','I know I shall see in His beauty<br/>The King in whose way I delight;<br/>Who lovingly guardeth my footsteps,<br/>And giveth me songs in the night.<br/>',NULL,1568,1568);
INSERT INTO stanza VALUES('E302','1','I have a song I love to sing,<br/>Since I have been redeemed,<br/>Of my Redeemer, Savior, King —<br/>Since I have been redeemed.<br/>',NULL,1569,1569);
INSERT INTO stanza VALUES('E302','chorus','Since I have been redeemed,<br/>Since I have been redeemed,<br/>I will glory in His name;<br/>Since I have been redeemed,<br/>I will glory in the Savior''s name.<br/>',NULL,1570,1570);
INSERT INTO stanza VALUES('E302','2','I have a Christ that satisfies,<br/>Since I have been redeemed,<br/>To do His will my highest prize —<br/>Since I have been redeemed.<br/>',NULL,1571,1571);
INSERT INTO stanza VALUES('E302','3','I have a witness bright and clear,<br/>Since I have been redeemed,<br/>Dispelling every doubt and fear —<br/>Since I have been redeemed.<br/>',NULL,1572,1572);
INSERT INTO stanza VALUES('E302','4','I have a joy I can''t express,<br/>Since I have been redeemed,<br/>All through the Lord, my righteousness —<br/>Since I have been redeemed.<br/>',NULL,1573,1573);
INSERT INTO stanza VALUES('E302','5','I have a God who is for me,<br/>Since I have been redeemed,<br/>With whom I''ll dwell eternally —<br/>Since I have been redeemed.<br/>',NULL,1574,1574);
INSERT INTO stanza VALUES('E303','1','Nor silver nor gold hath obtained my redemption;<br/>No riches of earth could have saved my poor soul.<br/>The blood of the cross is my only foundation;<br/>The death of my Savior now maketh me whole.<br/>',NULL,1575,1575);
INSERT INTO stanza VALUES('E303','chorus','I am redeemed, but not with silver;<br/>I am bought, but not with gold;<br/>Bought with a price — the blood of Jesus,<br/>Precious price of love untold.<br/>',NULL,1576,1576);
INSERT INTO stanza VALUES('E303','2','Nor silver nor gold hath obtained my redemption;<br/>The guilt on my conscience too heavy had grown.<br/>The blood of the cross is my only foundation;<br/>The death of my Savior I only can own.<br/>',NULL,1577,1577);
INSERT INTO stanza VALUES('E303','3','Nor silver nor gold hath obtained my redemption;<br/>The holy commandment forbade me draw near.<br/>The blood of the cross is my only foundation;<br/>The death of my Savior removeth my fear.<br/>',NULL,1578,1578);
INSERT INTO stanza VALUES('E303','4','Nor silver nor gold hath obtained my redemption;<br/>The way to God''s kingdom could not thus be bought.<br/>The blood of the cross is my only foundation;<br/>The death of my Savior redemption hath wrought.<br/>',NULL,1579,1579);
INSERT INTO stanza VALUES('E304','1','How should the Lord keep back His sword from blood?<br/>"The soul that sinneth it shall surely die:"<br/>But ah, can Justice make His counsels good?<br/>Can Law bring in the glory from on high?<br/>Grace must provide a Lamb — a Ransom find;<br/>Redeem by One whom death no more may bind.<br/>',NULL,1580,1580);
INSERT INTO stanza VALUES('E304','2','"One poor wise man" hath cried, O God, to Thee;<br/>His blood is counted precious in Thy sight.<br/>He liveth, and His name shall ever be<br/>Thy praise, Thy glory, Thy supreme delight.<br/>By Jesus'' blood — that new and living way —<br/>God''s priests shall now within the holiest stay.<br/>',NULL,1581,1581);
INSERT INTO stanza VALUES('E304','3','The blood of bulls and goats for ages failed<br/>To purge the conscience, burdened sore with sins;<br/>Thy precious blood, O Lamb of God, prevailed —<br/>Through Thee, sweet Peace her endless reign begins.<br/>Thy blood hath made redemption e''en for me;<br/>Complete I stand, O risen Christ, in Thee.<br/>',NULL,1582,1582);
INSERT INTO stanza VALUES('E304','4','The precious blood of Christ, it speaketh peace<br/>To guilty sinners, groaning ''neath their load;<br/>To captive spirits it proclaims release,<br/>And Pharaoh''s slaves become the "hosts of God."<br/>His flesh is meat — His blood is drink indeed;<br/>He died, He rose, His people''s cause to plead.<br/>',NULL,1583,1583);
INSERT INTO stanza VALUES('E304','5','Oh, precious blood! Poured freely forth for me,<br/>My sins are sunk beneath thy crimson tide.<br/>No more before th'' Avenger''s sword I flee!<br/>Christ is the Refuge-City, where I hide.<br/>My life''s dark page, blood-sprinkled, gleameth white;<br/>My name shines forth in heaven in words of light.<br/>',NULL,1584,1584);
INSERT INTO stanza VALUES('E305','1','I will sing of my Redeemer,<br/>And His wondrous love to me;<br/>On the cruel cross He suffered,<br/>From the curse to set me free.<br/>',NULL,1585,1585);
INSERT INTO stanza VALUES('E305','chorus','Sing, oh, sing of my Redeemer,<br/>With His blood He purchased me,<br/>On the cross He sealed my pardon,<br/>Paid the debt, and made me free.<br/>',NULL,1586,1586);
INSERT INTO stanza VALUES('E305','2','I will tell the wondrous story,<br/>How my lost estate to save,<br/>In His boundless love and mercy,<br/>He the ransom freely gave.<br/>',NULL,1587,1587);
INSERT INTO stanza VALUES('E305','3','I will praise my dear Redeemer,<br/>His triumphant pow''r I''ll tell,<br/>How the victory He giveth<br/>Over sin, and death, and hell.<br/>',NULL,1588,1588);
INSERT INTO stanza VALUES('E305','4','I will sing of my Redeemer,<br/>And His heav''nly love to me;<br/>He from death to life hath brought me,<br/>Son of God with Him to be.<br/>',NULL,1589,1589);
INSERT INTO stanza VALUES('E306','1','I belong to Jesus;<br/>I am not my own;<br/>All I have and all I am<br/>Shall be His alone.<br/>',NULL,1590,1590);
INSERT INTO stanza VALUES('E306','2','I belong to Jesus;<br/>He is Lord and King,<br/>Reigning in my inmost heart<br/>Over everything.<br/>',NULL,1591,1591);
INSERT INTO stanza VALUES('E306','3','I belong to Jesus;<br/>What can hurt or harm,<br/>When He folds around my soul<br/>His almighty Arm?<br/>',NULL,1592,1592);
INSERT INTO stanza VALUES('E306','4','I belong to Jesus;<br/>Blessed, blessed thought!<br/>With His own most precious blood<br/>Has my soul been bought.<br/>',NULL,1593,1593);
INSERT INTO stanza VALUES('E306','5','I belong to Jesus;<br/>He has died for me;<br/>I am His and He is mine<br/>Through eternity.<br/>',NULL,1594,1594);
INSERT INTO stanza VALUES('E306','6','I belong to Jesus;<br/>He will keep my soul,<br/>If the deathly waters dark<br/>Round about me roll.<br/>',NULL,1595,1595);
INSERT INTO stanza VALUES('E306','7','I belong to Jesus;<br/>And ere long I''ll be<br/>With my precious Savior there<br/>In His royalty.<br/>',NULL,1596,1596);
INSERT INTO stanza VALUES('E307','1','On Calvary''s brow my Savior died<br/>''Twas there my Lord was crucified;<br/>''Twas on the cross He bled for me,<br/>And purchased there my pardon free.<br/>',NULL,1597,1597);
INSERT INTO stanza VALUES('E307','chorus','O Calvary! Dark Calvary!<br/>Where Jesus shed His blood for me;<br/>O Calvary! Blest Calvary!<br/>''Twas there my Savior died for me.<br/>',NULL,1598,1598);
INSERT INTO stanza VALUES('E307','2','''Mid rending rocks and darkening skies<br/>My Savior bows His head and dies;<br/>The opening veil reveals the way<br/>To life divine and endless day.<br/>',NULL,1599,1599);
INSERT INTO stanza VALUES('E307','3','O Jesus, Lord, how can it be<br/>That Thou shouldst give Thy life for me,<br/>To bear the cross and agony<br/>In that dread hour on Calvary!<br/>',NULL,1600,1600);
INSERT INTO stanza VALUES('E308','1','Blessed assurance, Jesus is mine;<br/>Oh, what a foretaste of glory divine!<br/>Heir of salvation, purchase of God,<br/>Born of His Spirit, washed in His blood.<br/>',NULL,1601,1601);
INSERT INTO stanza VALUES('E308','chorus','This is my story, this is my song,<br/>Praising my Savior all the day long.<br/>This is my story, this is my song,<br/>Praising my Savior all the day long.<br/>',NULL,1602,1602);
INSERT INTO stanza VALUES('E308','2','Perfect submission, perfect delight,<br/>Visions of rapture now burst on my sight;<br/>Angels descending, bring from above<br/>Echoes of mercy, whispers of love.<br/>',NULL,1603,1603);
INSERT INTO stanza VALUES('E308','3','Perfect submission, all is at rest,<br/>I in my Savior am happy and blest;<br/>Watching and waiting, looking above,<br/>Filled with His goodness, lost in His love.<br/>',NULL,1604,1604);
INSERT INTO stanza VALUES('E309','1','What a wonderful change in my life has been wrought<br/>Since Jesus came into my heart!<br/>I have light in my soul for which long I had sought,<br/>Since Jesus came into my heart!<br/>',NULL,1605,1605);
INSERT INTO stanza VALUES('E309','chorus','Since Jesus came into my heart!<br/>Since Jesus came into my heart!<br/>Floods of joy o''er my soul like the sea billows roll,<br/>Since Jesus came into my heart!<br/>',NULL,1606,1606);
INSERT INTO stanza VALUES('E309','2','I have ceased from my wand''ring and going astray,<br/>Since Jesus came into my heart!<br/>And my sins which were many are all washed away,<br/>Since Jesus came into my heart!<br/>',NULL,1607,1607);
INSERT INTO stanza VALUES('E309','3','I''m possessed of a hope that is steadfast and sure,<br/>Since Jesus came into my heart!<br/>And no dark clouds of doubt now my pathway obscure,<br/>Since Jesus came into my heart!<br/>',NULL,1608,1608);
INSERT INTO stanza VALUES('E309','4','There''s a light in the valley of death now for me,<br/>Since Jesus came into my heart!<br/>And the gates of the City beyond I can see,<br/>Since Jesus came into my heart!<br/>',NULL,1609,1609);
INSERT INTO stanza VALUES('E309','5','I shall go there to dwell in that City I know,<br/>Since Jesus came into my heart!<br/>And I''m happy, so happy as onward I go,<br/>Since Jesus came into my heart!<br/>',NULL,1610,1610);
INSERT INTO stanza VALUES('E310','1','Once I was bound by sin''s galling fetters,<br/>Chained like a slave I struggled in vain;<br/>But I received a glorious freedom,<br/>When Jesus broke my fetters in twain.<br/>',NULL,1611,1611);
INSERT INTO stanza VALUES('E310','chorus','Glorious freedom, wonderful freedom,<br/>No more in chains of sin I repine!<br/>Jesus the glorious Emancipator,<br/>Now and forever He shall be mine.<br/>',NULL,1612,1612);
INSERT INTO stanza VALUES('E310','2','Freedom from all the carnal affections,<br/>Freedom from envy, hatred and strife;<br/>Freedom from vain and worldly ambitions,<br/>Freedom from all that saddened my life.<br/>',NULL,1613,1613);
INSERT INTO stanza VALUES('E310','3','Freedom from pride and all sinful follies,<br/>Freedom from love and glitter of gold;<br/>Freedom from evil temper and anger,<br/>Glorious freedom, rapture untold.<br/>',NULL,1614,1614);
INSERT INTO stanza VALUES('E310','4','Freedom from fear with all of its torments,<br/>Freedom from care with all of its pain;<br/>Freedom in Christ my blessed Redeemer,<br/>He who has rent my fetters in twain.<br/>',NULL,1615,1615);
INSERT INTO stanza VALUES('E311','1','Naught have I gotten but what I received;<br/>Grace hath bestowed it since I have believed;<br/>Boasting excluded, pride I abase;<br/>I''m only a sinner saved by grace!<br/>',NULL,1616,1616);
INSERT INTO stanza VALUES('E311','chorus','Only a sinner saved by grace!<br/>Only a sinner saved by grace!<br/>This is my story, to God be the glory,<br/>I''m only a sinner saved by grace!<br/>',NULL,1617,1617);
INSERT INTO stanza VALUES('E311','2','Once I was foolish, and sin ruled my heart,<br/>Causing my footsteps from God to depart;<br/>Jesus hath found me, happy my case;<br/>I now am a sinner saved by grace!<br/>',NULL,1618,1618);
INSERT INTO stanza VALUES('E311','3','Tears unavailing, no merit had I;<br/>Mercy had saved me, or else I must die;<br/>Sin had alarmed me, fearing God''s face;<br/>But now I''m a sinner saved by grace!<br/>',NULL,1619,1619);
INSERT INTO stanza VALUES('E311','4','Suffer a sinner whose heart overflows,<br/>Loving his Savior to tell what he knows;<br/>Once more to tell it, would I embrace —<br/>I''m only a sinner saved by grace!<br/>',NULL,1620,1620);
INSERT INTO stanza VALUES('E312','1','Grace! ''Tis a charming sound.<br/>Harmonious to the ear;<br/>Heav''n with the echo shall resound,<br/>And all the earth shall hear.<br/>',NULL,1621,1621);
INSERT INTO stanza VALUES('E312','chorus','All sufficient grace!<br/>Never powerless!<br/>It is Christ who lives in me,<br/>In His exhaustlessness.<br/>',NULL,1622,1622);
INSERT INTO stanza VALUES('E312','2','''Twas grace that wrote my name<br/>In life''s eternal book;<br/>''Twas grace that gave me to the Lamb,<br/>Who all my sorrows took.<br/>',NULL,1623,1623);
INSERT INTO stanza VALUES('E312','3','Grace taught my wandering feet<br/>To tread the pilgrim road;<br/>And new supplies each hour I meet<br/>While pressing on to God.<br/>',NULL,1624,1624);
INSERT INTO stanza VALUES('E312','4','Grace taught my heart to pray,<br/>And made my eyes o''erflow;<br/>''Tis grace which kept me to this day,<br/>And will not let me go.<br/>',NULL,1625,1625);
INSERT INTO stanza VALUES('E312','5','Grace all the work shall crown<br/>Through everlasting days;<br/>It lays in love the topmost stone,<br/>And well deserves the praise.<br/>',NULL,1626,1626);
INSERT INTO stanza VALUES('E312','6','Oh, let that grace inspire<br/>My heart with strength divine;<br/>May all my powers to Thee aspire,<br/>And all my days be Thine.<br/>',NULL,1627,1627);
INSERT INTO stanza VALUES('E313','1','Amazing grace! How sweet the sound,<br/>That saved a wretch like me!<br/>I once was lost, but now am found,<br/>Was blind, but now I see.<br/>',NULL,1628,1628);
INSERT INTO stanza VALUES('E313','2','''Twas grace that taught my heart to fear,<br/>And grace my fears relieved;<br/>How precious did that grace appear<br/>The hour I first believed!<br/>',NULL,1629,1629);
INSERT INTO stanza VALUES('E313','3','The Lord hath promised good to me,<br/>His word my hope secures;<br/>He will my shield and portion be<br/>As long as life endures.<br/>',NULL,1630,1630);
INSERT INTO stanza VALUES('E313','4','When we''ve been there ten thousand years,<br/>Bright shining as the sun,<br/>We''ve no less days to sing God''s praise<br/>Than when we first begun.<br/>',NULL,1631,1631);
INSERT INTO stanza VALUES('E314','1','Sov''reign grace o''er sin abounding,<br/>Ransomed souls, the tidings swell;<br/>''Tis a deep that knows no sounding,<br/>Who its breadth or length can tell?<br/>On its glories, on its glories,<br/>Let my soul forever dwell!<br/>On its glories, on its glories,<br/>Let my soul forever dwell!<br/>',NULL,1632,1632);
INSERT INTO stanza VALUES('E314','2','What from Christ the soul can sever,<br/>Bound by everlasting bands?<br/>Once in Him, in Him forever,<br/>Thus th'' eternal cov''nant stands.<br/>None shall pluck thee, none shall pluck thee<br/>From the Savior''s mighty hands!<br/>None shall pluck thee, none shall pluck thee<br/>From the Savior''s mighty hands!<br/>',NULL,1633,1633);
INSERT INTO stanza VALUES('E314','3','Heirs of God, joint-heirs with Jesus,<br/>Long ere time its race begun;<br/>To His name eternal praises,<br/>O what wonders love has done!<br/>One with Jesus, one with Jesus,<br/>By eternal union one.<br/>One with Jesus, one with Jesus,<br/>By eternal union one.<br/>',NULL,1634,1634);
INSERT INTO stanza VALUES('E314','4','On such love, my soul, still ponder,<br/>Love, so great, so rich, so free;<br/>Say, while lost in holy wonder,<br/>Why, O Lord, such love to me?<br/>Hallelujah! Hallelujah!<br/>Grace shall reign eternally!<br/>Hallelujah! Hallelujah!<br/>Grace shall reign eternally!<br/>',NULL,1635,1635);
INSERT INTO stanza VALUES('E315','1','Saved to the uttermost, I am the Lord''s;<br/>Jesus my Savior salvation affords;<br/>Gives me His Spirit a witness within,<br/>Whisp''ring of pardon, and saving from sin.<br/>',NULL,1636,1636);
INSERT INTO stanza VALUES('E315','chorus','Saved, saved, saved to the uttermost:<br/>Saved, saved by power divine;<br/>Saved, saved, I''m saved to the uttermost;<br/>Jesus the Savior is mine!<br/>',NULL,1637,1637);
INSERT INTO stanza VALUES('E315','2','Saved to the uttermost; Jesus is near;<br/>Keeping me safely, He casteth out fear;<br/>Trusting His promises, how I am blest;<br/>Leaning upon Him, how sweet is my rest.<br/>',NULL,1638,1638);
INSERT INTO stanza VALUES('E315','3','Saved to the uttermost: this I can say,<br/>"Once all was darkness, but now it is day."<br/>Beautiful visions of glory I see;<br/>Jesus in brightness revealed unto me.<br/>',NULL,1639,1639);
INSERT INTO stanza VALUES('E315','4','Saved to the uttermost: cheerfully sing<br/>Loud hallelujahs to Jesus my King!<br/>Ransomed and pardoned, redeemed by His blood,<br/>Cleansed from unrighteousness, glory to God!<br/>',NULL,1640,1640);
INSERT INTO stanza VALUES('E316','1','Some day the silver cord will break,<br/>And I no more as now shall sing;<br/>But, O the joy when I shall wake<br/>Within the presence of the King!<br/>',NULL,1641,1641);
INSERT INTO stanza VALUES('E316','chorus','And I shall see Him face to face,<br/>And tell the story, saved by grace:<br/>And I shall see Him face to face,<br/>And tell the story, saved by grace.<br/>',NULL,1642,1642);
INSERT INTO stanza VALUES('E316','2','Some day my earthly house will fall,<br/>I cannot tell how soon ''twill be,<br/>But this I know — my All in all<br/>Has now a place with Him for me.<br/>',NULL,1643,1643);
INSERT INTO stanza VALUES('E316','3','Or some day when my Lord will come,<br/>And called to meet Him I''ll be blest,<br/>He then will say to me, "Well done,"<br/>And I shall enter into rest.<br/>',NULL,1644,1644);
INSERT INTO stanza VALUES('E316','4','Some day, till then I''ll watch and wait,<br/>My lamp all trimmed and burning bright,<br/>That when my Savior I will greet,<br/>My faith will then be changed to sight.<br/>',NULL,1645,1645);
INSERT INTO stanza VALUES('E317','1','Dear Savior, Thou art mine,<br/>How sweet the thought to me;<br/>Let me repeat Thy name,<br/>And lift my heart to Thee.<br/>',NULL,1646,1646);
INSERT INTO stanza VALUES('E317','chorus','Mine! Mine! Mine!<br/>I know Thou art mine;<br/>Savior, dear Savior,<br/>I know thou art mine.<br/>',NULL,1647,1647);
INSERT INTO stanza VALUES('E317','2','Thou art the sinner''s friend,<br/>So I Thy friendship claim,<br/>A sinner saved by grace,<br/>When thy sweet message came.<br/>',NULL,1648,1648);
INSERT INTO stanza VALUES('E317','3','My hardened heart was touched;<br/>Thy pard''ning voice I heard;<br/>And joy and peace came in<br/>While list''ning to Thy word.<br/>',NULL,1649,1649);
INSERT INTO stanza VALUES('E317','4','So let me sing Thy praise,<br/>So let me call Thee mine.<br/>I cannot doubt Thy word,<br/>I know that I am Thine.<br/>',NULL,1650,1650);
INSERT INTO stanza VALUES('E318','1','Precious Savior, Thou hast saved me;<br/>Thine, and only Thine, I am:<br/>Oh, the cleansing blood has reached me!<br/>Glory, glory to the Lamb!<br/>',NULL,1651,1651);
INSERT INTO stanza VALUES('E318','chorus','Glory, glory, hallelujah!<br/>Glory, glory to the Lamb!<br/>Oh, the cleansing blood has reached me!<br/>Glory, glory to the Lamb!<br/>',NULL,1652,1652);
INSERT INTO stanza VALUES('E318','2','Long my yearning heart was striving<br/>To obtain this precious rest;<br/>But, when all my struggles ended,<br/>Simply trusting, I was blessed.<br/>',NULL,1653,1653);
INSERT INTO stanza VALUES('E318','3','Trusting, trusting every moment;<br/>Feeling now the blood applied;<br/>Lying in the cleansing fountain,<br/>Dwelling in my Savior''s side.<br/>',NULL,1654,1654);
INSERT INTO stanza VALUES('E318','4','Consecrated to Thy service,<br/>I will live and die to Thee;<br/>I will witness to Thy glory,<br/>Of salvation, full and free.<br/>',NULL,1655,1655);
INSERT INTO stanza VALUES('E318','5','Yes, I will stand up for Jesus,<br/>He has sweetly saved my soul,<br/>Cleansed my soul from sin''s corruption,<br/>Sanctified, and made me whole.<br/>',NULL,1656,1656);
INSERT INTO stanza VALUES('E318','6','Glory to the Lord who bought me,<br/>Glory for His saving power;<br/>Glory to the Lord who keeps me,<br/>Glory, glory evermore!<br/>',NULL,1657,1657);
INSERT INTO stanza VALUES('E319','1','Come, Thou Fount of every blessing,<br/>Tune my heart to sing Thy grace;<br/>Streams of mercy, never ceasing,<br/>Call for songs of loudest praise.<br/>Jesus sought me when a stranger,<br/>Wand''ring from the face of God;<br/>He, to save my soul from danger,<br/>Interposed His precious blood.<br/>',NULL,1658,1658);
INSERT INTO stanza VALUES('E319','2','O to grace how great a debtor<br/>Daily I''m constrained to be!<br/>Let that grace, Lord, like a fetter,<br/>Bind my wand''ring heart to Thee.<br/>Teach me, Lord, some rapturous measure,<br/>Meet for me Thy grace to prove,<br/>While I sing the countless treasure<br/>Of my God''s unchanging love.<br/>',NULL,1659,1659);
INSERT INTO stanza VALUES('E319','3','Prone to wander, Lord, I feel it;<br/>Prone to leave the God I love:<br/>Take my heart, oh, take and seal it<br/>With Thy Spirit from above.<br/>Rescued thus from sin and danger,<br/>Purchased by the Savior''s blood,<br/>May I walk on earth a stranger,<br/>As a son and heir of God.<br/>',NULL,1660,1660);
INSERT INTO stanza VALUES('E320','1','In loving-kindness Jesus came<br/>My soul in mercy to reclaim,<br/>And from the depths of sin and shame<br/>Through grace He lifted me.<br/>',NULL,1661,1661);
INSERT INTO stanza VALUES('E320','chorus','From sinking sand He lifted me,<br/>With tender hand He lifted me,<br/>From shades of night to plains of light,<br/>Oh, praise His name, He lifted me!<br/>',NULL,1662,1662);
INSERT INTO stanza VALUES('E320','2','He called me long before I heard,<br/>Before my sinful heart was stirred,<br/>But when I took Him at His word,<br/>Forgiv''n, He lifted me.<br/>',NULL,1663,1663);
INSERT INTO stanza VALUES('E320','3','His brow was pierced with many a thorn,<br/>His hands by cruel nails were tom,<br/>When from my guilt and grief, forlorn,<br/>In love He lifted me.<br/>',NULL,1664,1664);
INSERT INTO stanza VALUES('E320','4','Now on a higher plane I dwell,<br/>And with my soul I know ''tis well;<br/>Yet how or why, I cannot tell,<br/>He should have lifted me.<br/>',NULL,1665,1665);
INSERT INTO stanza VALUES('E321','1','Full salvation! Full salvation!<br/>Lo, the fountain opened wide,<br/>Streams through every land and nation<br/>From the Savior''s wounded side.<br/>Full salvation! Full salvation!<br/>Streams an endless crimson tide.<br/>',NULL,1666,1666);
INSERT INTO stanza VALUES('E321','2','Oh, the glorious revelation!<br/>See the cleansing current flow,<br/>Washing stains of condemnation<br/>Whiter than the driven snow:<br/>Full salvation! Full salvation!<br/>Oh, the rapturous bliss to know.<br/>',NULL,1667,1667);
INSERT INTO stanza VALUES('E321','3','Love''s resistless current sweeping<br/>All the regions deep within;<br/>Thought, and wish, and senses keeping<br/>Now, and every instant, clean:<br/>Full salvation! Full salvation!<br/>From the guilt and power of sin.<br/>',NULL,1668,1668);
INSERT INTO stanza VALUES('E321','4','Life immortal, Christ descending,<br/>Lo! My heart the Spirit''s shrine:<br/>God and man in oneness blending,<br/>Oh, what fellowship is mine!<br/>Full salvation! Full salvation!<br/>Raised in Christ to life divine!<br/>',NULL,1669,1669);
INSERT INTO stanza VALUES('E321','5','Care and doubting, gloom and sorrow,<br/>Fear and shame are mine no more;<br/>Faith knows naught of dark tomorrow,<br/>For my Savior goes before:<br/>Full salvation! Full salvation!<br/>Full and free for evermore!<br/>',NULL,1670,1670);
INSERT INTO stanza VALUES('E322','1','Many weary years I vainly sought a spring,<br/>One that never would run dry;<br/>Unavailing all that earth to me could bring,<br/>Nothing seemed to satisfy.<br/>',NULL,1671,1671);
INSERT INTO stanza VALUES('E322','chorus','Drinking at the Fountain that never runs dry,<br/>Drinking at the Fountain of life am I;<br/>Finding joy and pleasure<br/>In abounding measure<br/>I am drinking at the Fountain of life.<br/>',NULL,1672,1672);
INSERT INTO stanza VALUES('E322','2','Through the desert land of sin I roam no more,<br/>For I find a living Spring,<br/>And my cup of gladness now is running o''er,<br/>Jesus is my Lord and King.<br/>',NULL,1673,1673);
INSERT INTO stanza VALUES('E322','3','Here is sweet contentment as the days go by,<br/>Here is holy peace and rest;<br/>Here is consolation as the moments fly,<br/>Here my heart is always blest.<br/>',NULL,1674,1674);
INSERT INTO stanza VALUES('E322','4','Here I find a never ending, sure supply,<br/>While the endless ages roll;<br/>To this healing Fountain I would ever fly,<br/>There to bathe my weary soul.<br/>',NULL,1675,1675);
INSERT INTO stanza VALUES('E323','1','I heard the voice of Jesus say,<br/>"Come unto Me, and rest;<br/>Lay down, thou weary one, lay down<br/>Thy head upon My breast."<br/>I came to Jesus as I was,<br/>Weary, and worn, and sad;<br/>I found in Him a resting-place,<br/>And He has made me glad.<br/>',NULL,1676,1676);
INSERT INTO stanza VALUES('E323','2','I heard the voice of Jesus say,<br/>"Behold, I freely give<br/>The living water: thirsty one,<br/>Stoop down, and drink, and live."<br/>I came to Jesus, and I drank<br/>Of that life-giving stream;<br/>My thirst was quenched, my soul revived,<br/>And now I live in Him.<br/>',NULL,1677,1677);
INSERT INTO stanza VALUES('E323','3','I heard the voice of Jesus say,<br/>"I am this dark world''s Light;<br/>Look unto Me, thy morn shall rise,<br/>And all thy day be bright."<br/>I looked to Jesus, and I found<br/>In Him my Star, my Sun;<br/>And in that Light of life I''ll walk<br/>Till traveling days are done.<br/>',NULL,1678,1678);
INSERT INTO stanza VALUES('E324','1','Far away the noise of strife upon my ear is falling,<br/>Then I know the sins of earth beset on every hand;<br/>Doubt and fear and things of earth in vain to me are calling,<br/>None of these shall move me from Beulah Land.<br/>',NULL,1679,1679);
INSERT INTO stanza VALUES('E324','chorus','I''m living on the mountain, underneath a cloudless sky,<br/>I''m drinking at the fountain that never shall run dry;<br/>O yes, I''m feasting on the manna from a bountiful supply,<br/>For I am dwelling in Beulah Land.<br/>',NULL,1680,1680);
INSERT INTO stanza VALUES('E324','2','Far below the storm of doubt upon the world is beating,<br/>Sons of men in battle long the enemy withstand;<br/>Safe am I within the castle of God''s word retreating,<br/>Nothing then can reach me, ''tis Beulah Land.<br/>',NULL,1681,1681);
INSERT INTO stanza VALUES('E324','3','Let the stormy breezes blow, their cry cannot alarm me,<br/>I am safely sheltered here, protected by God''s hand;<br/>Here the sun is always shining, here there''s naught can harm me,<br/>I am safe forever in Beulah Land.<br/>',NULL,1682,1682);
INSERT INTO stanza VALUES('E324','4','Viewing here the works of God, I sink in contemplation,<br/>Hearing now His blessed voice, I see the way is planned;<br/>Dwelling in the spirit, here I learn of full salvation,<br/>Gladly will I tarry in Beulah Land.<br/>',NULL,1683,1683);
INSERT INTO stanza VALUES('E325','1','All my life long I had panted<br/>For a draught from some cool spring,<br/>That I hoped would quench the burning<br/>Of the thirst I felt within.<br/>',NULL,1684,1684);
INSERT INTO stanza VALUES('E325','chorus','Hallelujah! I have found Him<br/>Whom my soul so long has craved!<br/>Jesus satisfies my longings;<br/>Through His life I now am saved.<br/>',NULL,1685,1685);
INSERT INTO stanza VALUES('E325','2','Feeding on the husks around me,<br/>Till my strength was almost gone,<br/>Longed my soul for something better,<br/>Only still to hunger on.<br/>',NULL,1686,1686);
INSERT INTO stanza VALUES('E325','3','Poor I was, and sought for riches,<br/>Something that would satisfy,<br/>But the dust I gathered round me<br/>Only mocked my soul''s sad cry.<br/>',NULL,1687,1687);
INSERT INTO stanza VALUES('E325','4','Well of water, ever springing,<br/>Bread of life, so rich and free,<br/>Untold wealth that never faileth,<br/>My Redeemer is to me.<br/>',NULL,1688,1688);
INSERT INTO stanza VALUES('E326','1','He lives, the great Redeemer lives,<br/>What joy the blest assurance gives!<br/>And now, before His Father, God,<br/>Pleads the full merits of His blood.<br/>',NULL,1689,1689);
INSERT INTO stanza VALUES('E326','2','Repeated crimes awake our fears,<br/>And Justice armed with frowns appears;<br/>But in the Savior''s lovely face<br/>Sweet Mercy smiles, and all is peace.<br/>',NULL,1690,1690);
INSERT INTO stanza VALUES('E326','3','Hence, then, ye black, despairing thoughts;<br/>Above our fears, above our faults,<br/>His mighty intercessions rise,<br/>And guilt recedes, and terror dies.<br/>',NULL,1691,1691);
INSERT INTO stanza VALUES('E326','4','In every dark, distressful hour,<br/>When sin and Satan join their power,<br/>Let this dear hope repel the dart,<br/>That Jesus bears us on His heart.<br/>',NULL,1692,1692);
INSERT INTO stanza VALUES('E326','5','Great Advocate, almighty Friend!<br/>On Him our humble hopes depend;<br/>Our cause can never, never fail,<br/>For Jesus pleads, and must prevail.<br/>',NULL,1693,1693);
INSERT INTO stanza VALUES('E327','1','Before the throne of God above<br/>I have a strong, a perfect plea;<br/>A great High Priest, whose Name is Love,<br/>Who ever lives and pleads for me.<br/>',NULL,1694,1694);
INSERT INTO stanza VALUES('E327','2','My name is graven on His hands,<br/>My name is written on His heart;<br/>I know that while with God He stands<br/>No tongue can bid me thence depart.<br/>',NULL,1695,1695);
INSERT INTO stanza VALUES('E327','3','When Satan tempts me to despair,<br/>And tells me of the guilt within,<br/>Upward I look, and see Him there<br/>Who made an end of all my sin.<br/>',NULL,1696,1696);
INSERT INTO stanza VALUES('E327','4','Because the sinless Savior died,<br/>My sinful soul is counted free;<br/>For God, the Just, is satisfied<br/>To look on Him and pardon me.<br/>',NULL,1697,1697);
INSERT INTO stanza VALUES('E327','5','Behold Him there, the risen Lamb!<br/>My perfect, spotless Righteousness,<br/>The great unchangeable I AM,<br/>The King of glory and of grace.<br/>',NULL,1698,1698);
INSERT INTO stanza VALUES('E327','6','One with Himself, I cannot die;<br/>My soul is purchased by His blood;<br/>My life is hid with Christ on high,<br/>With Christ, my Savior and my God.<br/>',NULL,1699,1699);
INSERT INTO stanza VALUES('E328','1','Complete in Thee! No work of mine<br/>May take, dear Lord, the place of Thine;<br/>Thy blood hath pardon bought for me,<br/>And I am now complete in Thee.<br/>',NULL,1700,1700);
INSERT INTO stanza VALUES('E328','chorus','Yea, justified! O blessed thought!<br/>And sanctified! Salvation wrought!<br/>Thy blood hath pardon bought for me,<br/>And glorified, I too, shall be!<br/>',NULL,1701,1701);
INSERT INTO stanza VALUES('E328','2','Complete in Thee — no more shall sin,<br/>Thy grace hath conquered, reign within;<br/>Thy voice shall bid the tempter flee,<br/>And I shall stand complete in Thee.<br/>',NULL,1702,1702);
INSERT INTO stanza VALUES('E328','3','Complete in Thee — each want supplied,<br/>And no good thing to me denied;<br/>Since Thou my portion, Lord, wilt be,<br/>I ask no more, complete in Thee.<br/>',NULL,1703,1703);
INSERT INTO stanza VALUES('E328','4','Dear Savior! When before Thy bar<br/>All tribes and tongues assembled are,<br/>Among Thy chosen will I be,<br/>At Thy right hand — complete in Thee.<br/>',NULL,1704,1704);
INSERT INTO stanza VALUES('E329','1','Blessed be God, our God,<br/>Who gave for us His well-beloved Son,<br/>The gift of gifts, all other gifts in one;<br/>Blessed be God, our God!<br/>',NULL,1705,1705);
INSERT INTO stanza VALUES('E329','2','What will He not bestow!<br/>Who freely gave this mighty gift unbought,<br/>Unmerited, unheeded, and unsought,<br/>What will He not bestow?<br/>',NULL,1706,1706);
INSERT INTO stanza VALUES('E329','3','He spared not His Son!<br/>''Tis this that silences each rising fear,<br/>''Tis this that bids the hard thought disappear;<br/>He spared not His Son!<br/>',NULL,1707,1707);
INSERT INTO stanza VALUES('E329','4','Who shall condemn us now?<br/>Since Christ has died, and ris''n, and gone above,<br/>For us to plead at the right hand of Love;<br/>Who shall condemn us now?<br/>',NULL,1708,1708);
INSERT INTO stanza VALUES('E329','5','''Tis God that justifies!<br/>Who shall recall His pardon or His grace?<br/>Or who the broken chain of guilt replace?<br/>''Tis God that justifies!<br/>',NULL,1709,1709);
INSERT INTO stanza VALUES('E329','6','The victory is ours!<br/>For us in might came forth the mighty One;<br/>For us He fought the fight, the triumph won:<br/>The victory is ours!<br/>',NULL,1710,1710);
INSERT INTO stanza VALUES('E330','1','My faith has found a resting place,<br/>Not in device nor creed;<br/>I trust the Ever-living One,<br/>His wounds for me shall plead.<br/>',NULL,1711,1711);
INSERT INTO stanza VALUES('E330','chorus','I need no other argument,<br/>I need no other plea;<br/>It is enough that Jesus died,<br/>And that He died for me.<br/>',NULL,1712,1712);
INSERT INTO stanza VALUES('E330','2','Enough for me that Jesus saves,<br/>This ends my fear and doubt;<br/>A sinful soul I come to Him,<br/>He''ll never cast me out.<br/>',NULL,1713,1713);
INSERT INTO stanza VALUES('E330','3','My heart is leaning on the Word,<br/>The written Word of God,<br/>Salvation by my Savior''s name,<br/>Salvation through His blood.<br/>',NULL,1714,1714);
INSERT INTO stanza VALUES('E330','4','My great Physician heals the sick,<br/>The lost He came to save;<br/>For me His precious blood He shed,<br/>For me His life He gave.<br/>',NULL,1715,1715);
INSERT INTO stanza VALUES('E331','1','Will your anchor hold in the storms of life,<br/>When the clouds unfold their wings of strife?<br/>When the strong tides lift, and the cables strain,<br/>Will your anchor drift or firm remain?<br/>',NULL,1716,1716);
INSERT INTO stanza VALUES('E331','chorus','We have an anchor that keeps the soul<br/>Steadfast and sure while the billows roll,<br/>Fastened to the Rock which cannot move,<br/>Grounded firm and deep in the Savior''s love.<br/>',NULL,1717,1717);
INSERT INTO stanza VALUES('E331','2','It is safely moored, ''twill the storm withstand,<br/>For ''tis well secured by the Savior''s hand;<br/>And the cables passed from His heart to mine,<br/>Can defy the blast, through strength divine.<br/>',NULL,1718,1718);
INSERT INTO stanza VALUES('E331','3','It will firmly hold in the straits of fear,<br/>When the breakers have told the reef is near;<br/>Though the tempest rave and the wild winds blow,<br/>Not an angry wave shall our bark o''erflow.<br/>',NULL,1719,1719);
INSERT INTO stanza VALUES('E331','4','It will surely hold in the floods of death,<br/>When the waters cold chill our latest breath;<br/>On the rising tide it can never fail,<br/>While our hopes abide within the veil.<br/>',NULL,1720,1720);
INSERT INTO stanza VALUES('E332','1','I hear the words of love,<br/>I gaze upon the blood,<br/>I see the mighty sacrifice,<br/>And I have peace with God.<br/>',NULL,1721,1721);
INSERT INTO stanza VALUES('E332','2','''Tis everlasting peace!<br/>Sure as Jehovah''s Name,<br/>''Tis stable as His steadfast throne,<br/>For evermore the same.<br/>',NULL,1722,1722);
INSERT INTO stanza VALUES('E332','3','The clouds may go and come,<br/>And storms may sweep my sky;<br/>This blood-sealed friendship changes not,<br/>The Cross is ever nigh.<br/>',NULL,1723,1723);
INSERT INTO stanza VALUES('E332','4','My love is ofttimes low,<br/>My joy still ebbs and flows,<br/>But peace with Him remains the same,<br/>No change my Savior knows.<br/>',NULL,1724,1724);
INSERT INTO stanza VALUES('E332','5','I change, He changes not;<br/>The Christ can never die;<br/>His love, not mine, the resting-place,<br/>His truth, not mine, the tie.<br/>',NULL,1725,1725);
INSERT INTO stanza VALUES('E332','6','The Cross still stands unchanged,<br/>Though heaven is now His home;<br/>The mighty stone is rolled away,<br/>But yonder is His tomb!<br/>',NULL,1726,1726);
INSERT INTO stanza VALUES('E332','7','And yonder is my peace,<br/>The grave of all my woes!<br/>I know the Son of God has come,<br/>I know He died and rose.<br/>',NULL,1727,1727);
INSERT INTO stanza VALUES('E332','8','I know He liveth now<br/>At God''s right hand above;<br/>I know the throne on which He sits,<br/>I know His truth and love!<br/>',NULL,1728,1728);
INSERT INTO stanza VALUES('E333','1','I know not why God''s wondrous grace<br/>To me He hath made known,<br/>Nor why, unworthy, Christ in love<br/>Redeemed me for His own.<br/>',NULL,1729,1729);
INSERT INTO stanza VALUES('E333','chorus','But "I know Whom I have believed<br/>And am persuaded that He is able<br/>To keep that which I''ve committed<br/>Unto Him against that day."<br/>',NULL,1730,1730);
INSERT INTO stanza VALUES('E333','2','I know not how this saving faith<br/>To me He did impart,<br/>Nor how believing in His word<br/>Wrought peace within my heart.<br/>',NULL,1731,1731);
INSERT INTO stanza VALUES('E333','3','I know not how the Spirit moves,<br/>Convincing men of sin,<br/>Revealing Jesus through the Word,<br/>Creating faith in Him.<br/>',NULL,1732,1732);
INSERT INTO stanza VALUES('E333','4','I know not what of good or ill<br/>May be reserved for me,<br/>Of weary ways or golden days,<br/>Before His face I see.<br/>',NULL,1733,1733);
INSERT INTO stanza VALUES('E333','5','I know not when my Lord may come,<br/>At night or noon-day fair,<br/>Nor if I''ll walk the vale with Him,<br/>Or "meet Him in the air."<br/>',NULL,1734,1734);
INSERT INTO stanza VALUES('E334','1','A wonderful Savior is Jesus my Lord,<br/>A wonderful Savior to me;<br/>He hideth my soul in the cleft of the rock,<br/>Where rivers of pleasure I see.<br/>',NULL,1735,1735);
INSERT INTO stanza VALUES('E334','chorus','He hideth my soul in the cleft of the rock<br/>That shadows a dry, thirsty land;<br/>He hideth my life in the depths of His love,<br/>And covers me there with His hand,<br/>And covers me there with His hand.<br/>',NULL,1736,1736);
INSERT INTO stanza VALUES('E334','2','A wonderful Savior is Jesus my Lord,<br/>He taketh my burden away;<br/>He holdeth me up and I shall not be moved.,<br/>He giveth me strength as my day.<br/>',NULL,1737,1737);
INSERT INTO stanza VALUES('E334','3','With numberless blessings each moment He crowns,<br/>And, filled with His fulness divine,<br/>I sing in my rapture, oh, glory to God,<br/>For such a Redeemer as mine!<br/>',NULL,1738,1738);
INSERT INTO stanza VALUES('E334','4','When clothed in His brightness, transported I rise<br/>To meet Him in clouds of the sky,<br/>His perfect salvation, His wonderful love,<br/>I''ll shout with the millions on high.<br/>',NULL,1739,1739);
INSERT INTO stanza VALUES('E335','1','I was lost in sin but Jesus rescued me,<br/>He''s a wonderful Savior to me;<br/>I was bound by fear but Jesus set me free,<br/>He''s a wonderful Savior to me.<br/>',NULL,1740,1740);
INSERT INTO stanza VALUES('E335','chorus','For He''s a wonderful Savior to me,<br/>He''s a wonderful Savior to me;<br/>I was lost in sin, but Jesus took me in,<br/>He''s a wonderful Savior to me.<br/>',NULL,1741,1741);
INSERT INTO stanza VALUES('E335','2','He''s a Friend so true, so patient and so kind,<br/>He''s a wonderful Savior to me;<br/>Everything I need in Him I always find,<br/>He''s a wonderful Savior to me.<br/>',NULL,1742,1742);
INSERT INTO stanza VALUES('E335','3','He is always near to comfort and to cheer,<br/>He''s a wonderful Savior to me;<br/>He forgives my sins, He dries my every tear,<br/>He''s a wonderful Savior to me.<br/>',NULL,1743,1743);
INSERT INTO stanza VALUES('E335','4','Dearer grows the love of Jesus day by day,<br/>He''s a wonderful Savior to me;<br/>Sweeter is His grace while pressing on my way,<br/>He''s a wonderful Savior to me.<br/>',NULL,1744,1744);
INSERT INTO stanza VALUES('E336','1','Jesus has loved me, wonderful Savior!<br/>Jesus has loved me, I cannot tell why;<br/>Came He to rescue sinners all worthless;<br/>My heart He conquered, for Him I would die.<br/>',NULL,1745,1745);
INSERT INTO stanza VALUES('E336','chorus','Glory to Jesus, wonderful Savior!<br/>Glory to Jesus, the One I adore;<br/>Glory to Jesus, wonderful Savior!<br/>Glory to Jesus, and praise evermore.<br/>',NULL,1746,1746);
INSERT INTO stanza VALUES('E336','2','Jesus has saved me, wonderful Savior!<br/>Jesus has saved me, I cannot tell how;<br/>All that I know is He was my ransom,<br/>Dying on Calv''ry with thorns on His brow.<br/>',NULL,1747,1747);
INSERT INTO stanza VALUES('E336','3','Jesus will lead me, wonderful Savior!<br/>Jesus will lead me, I cannot tell where;<br/>But I will follow, through joy or sorrow,<br/>Sunshine or tempest, sweet peace or despair.<br/>',NULL,1748,1748);
INSERT INTO stanza VALUES('E336','4','Jesus will crown me, wonderful Savior!<br/>Jesus will crown me, I cannot tell when;<br/>His throne of splendor hail I with gladness,<br/>Crowned with the glory of God among men.<br/>',NULL,1749,1749);
INSERT INTO stanza VALUES('E337','1','I will sing the wondrous story<br/>Of the Christ who died for me,<br/>How He left His home in glory<br/>For the cross of Calvary.<br/>',NULL,1750,1750);
INSERT INTO stanza VALUES('E337','chorus','Yes, I''ll sing the wondrous story<br/>Of the Christ who died for me,<br/>Sing it in the light of glory,<br/>Sing it through eternity.<br/>',NULL,1751,1751);
INSERT INTO stanza VALUES('E337','2','I was lost, but Jesus found me,<br/>Found the sheep that went astray,<br/>Threw His loving arms around me,<br/>Drew me back into His way.<br/>',NULL,1752,1752);
INSERT INTO stanza VALUES('E337','3','I was bruised, but Jesus healed me;<br/>Faint was I from many a fall;<br/>Sight was gone, and fears possessed me,<br/>But He freed me from them all.<br/>',NULL,1753,1753);
INSERT INTO stanza VALUES('E337','4','Days of darkness still come o''er me,<br/>Sorrow''s paths I often tread,<br/>But the Savior still is with me;<br/>By His hand I''m safely led.<br/>',NULL,1754,1754);
INSERT INTO stanza VALUES('E337','5','He will keep me till the rapture,<br/>Day by day He''ll wash my feet,<br/>And will transform all my nature<br/>That in glory we may meet.<br/>',NULL,1755,1755);
INSERT INTO stanza VALUES('E338','1','Wounded for me, wounded for me,<br/>There on the cross He was wounded for me;<br/>Gone my transgressions, and now I am free,<br/>All because Jesus was wounded for me.<br/>',NULL,1756,1756);
INSERT INTO stanza VALUES('E338','2','Dying for me, dying for me,<br/>There on the cross He was dying for me;<br/>Now in His death my redemption I see,<br/>All because Jesus was dying for me.<br/>',NULL,1757,1757);
INSERT INTO stanza VALUES('E338','3','Risen for me, risen for me,<br/>Up from the grave He has risen for me;<br/>Now evermore from death''s sting I am free,<br/>All because Jesus has risen for me.<br/>',NULL,1758,1758);
INSERT INTO stanza VALUES('E338','4','Living for me, living for me,<br/>Up in the skies He is living for me;<br/>Daily He''s pleading and praying for me,<br/>All because Jesus is living for me.<br/>',NULL,1759,1759);
INSERT INTO stanza VALUES('E338','5','Coming for me, coming for me,<br/>Soon in the air He is coming for me;<br/>Then with what joy His dear face I shall see,<br/>Oh, how I praise Him! He''s coming for me.<br/>',NULL,1760,1760);
INSERT INTO stanza VALUES('E339','1','How firm a foundation, ye saints of the Lord,<br/>Is laid for your faith in His excellent word!<br/>What more can He say than to you He hath said,<br/>To you who for refuge to Jesus have fled?<br/>',NULL,1761,1761);
INSERT INTO stanza VALUES('E339','2','"Fear not, I am with thee, O be not dismayed,<br/>For I am thy God, and will still give thee aid;<br/>I''ll strengthen thee, help thee, and cause thee to stand,<br/>Upheld by My righteous, omnipotent hand.<br/>',NULL,1762,1762);
INSERT INTO stanza VALUES('E339','3','"When through the deep waters I call thee to go,<br/>The rivers of sorrow shall not overflow;<br/>For I will be with thee, thy troubles to bless,<br/>And sanctify to thee thy deepest distress.<br/>',NULL,1763,1763);
INSERT INTO stanza VALUES('E339','4','"When through fiery trials thy pathway shall lie,<br/>My grace, all sufficient, shall be thy supply;<br/>The flame shall not hurt thee; I only design<br/>Thy dross to consume, and thy gold to refine.<br/>',NULL,1764,1764);
INSERT INTO stanza VALUES('E339','5','"E''en down to old age all My people shall prove<br/>My sovereign, eternal, unchangeable love;<br/>And then, when grey hairs shall their temples adorn,<br/>Like lambs they shall still in My bosom be borne.<br/>',NULL,1765,1765);
INSERT INTO stanza VALUES('E339','6','"The soul that on Jesus hath leaned for repose,<br/>I will not, I will not desert to his foes;<br/>That soul, though all hell should endeavor to shake,<br/>I''ll never, no, never, no, never forsake!"<br/>',NULL,1766,1766);
INSERT INTO stanza VALUES('E340','1','Standing on the promises of Christ my King,<br/>Through eternal ages let His praises ring,<br/>Glory in the highest, I will shout and sing,<br/>Standing on the promises of God.<br/>',NULL,1767,1767);
INSERT INTO stanza VALUES('E340','chorus','Standing, standing,<br/>Standing on the promises of God my Savior;<br/>Standing, standing,<br/>I''m standing on the promises of God.<br/>',NULL,1768,1768);
INSERT INTO stanza VALUES('E340','2','Standing on the promises that cannot fail,<br/>When the howling storms of doubt and fear assail,<br/>By the living Word of God I shall prevail,<br/>Standing on the promises of God.<br/>',NULL,1769,1769);
INSERT INTO stanza VALUES('E340','3','Standing on the promises I now can see<br/>Perfect, present cleansing in the blood for me;<br/>Standing in the liberty where Christ makes free,<br/>Standing on the promises of God.<br/>',NULL,1770,1770);
INSERT INTO stanza VALUES('E340','4','Standing on the promises of Christ the Lord,<br/>Bound to Him eternally by love''s strong cord,<br/>Overcoming daily with the Spirit''s sword,<br/>Standing on the promises of God.<br/>',NULL,1771,1771);
INSERT INTO stanza VALUES('E340','5','Standing on the promises I shall not fall,<br/>List''ning every moment to the Spirit''s call.<br/>Resting in my Savior as my All in all,<br/>Standing on the promises of God.<br/>',NULL,1772,1772);
INSERT INTO stanza VALUES('E341','1','When peace like a river attendeth my way,<br/>When sorrows like sea billows roll;<br/>Whatever my lot Thou hast taught me to say,<br/>"It is well, it is well with my soul!"<br/>',NULL,1773,1773);
INSERT INTO stanza VALUES('E341','chorus','It is well with my soul!<br/>It is well, it is well with my soul!<br/>',NULL,1774,1774);
INSERT INTO stanza VALUES('E341','2','Though Satan should buffet, though trials should come,<br/>Let this blest assurance control,<br/>That Christ hath regarded my helpless estate,<br/>And hath shed His own blood for my soul.<br/>',NULL,1775,1775);
INSERT INTO stanza VALUES('E341','3','My sin — oh, the bliss of this glorious thought —<br/>My sin, not in part, but the whole,<br/>Is nailed to His Cross, and I bear it no more;<br/>Praise the Lord, praise the Lord, O my soul!<br/>',NULL,1776,1776);
INSERT INTO stanza VALUES('E341','4','For me, be it Christ, be it Christ hence to live;<br/>If dark hours about me shall roll,<br/>No pang shall be mine, for in death as in life<br/>Thou wilt whisper Thy peace to my soul.<br/>',NULL,1777,1777);
INSERT INTO stanza VALUES('E342','1','Years I spent in vanity and pride,<br/>Caring not my Lord was crucified,<br/>Knowing not it was for me He died<br/>On Calvary.<br/>',NULL,1778,1778);
INSERT INTO stanza VALUES('E342','chorus','Mercy there was great, and grace was free;<br/>Pardon there was multiplied to me;<br/>There my burdened soul found liberty,<br/>At Calvary.<br/>',NULL,1779,1779);
INSERT INTO stanza VALUES('E342','2','By God''s Word at last my sin I learned;<br/>Then I trembled at the law I''d spurned,<br/>Till my guilty soul imploring turned<br/>To Calvary.<br/>',NULL,1780,1780);
INSERT INTO stanza VALUES('E342','3','Now I''ve giv''n to Jesus everything,<br/>Now I gladly own Him as my King,<br/>Now my raptured soul can only sing<br/>Of Calvary.<br/>',NULL,1781,1781);
INSERT INTO stanza VALUES('E342','4','Oh, the love that drew salvation''s plan!<br/>Oh, the grace that brought it down to man!<br/>Oh, the mighty gulf that God did span<br/>At Calvary!<br/>',NULL,1782,1782);
INSERT INTO stanza VALUES('E343','1','There is sunshine in my soul today,<br/>More glorious and bright<br/>Than glows in any earthly sky,<br/>For Jesus is my light.<br/>',NULL,1783,1783);
INSERT INTO stanza VALUES('E343','chorus','O there''s sunshine, blessed sunshine,<br/>While the peaceful, happy moments roll;<br/>When Jesus shows His smiling face<br/>There is sunshine in my soul.<br/>',NULL,1784,1784);
INSERT INTO stanza VALUES('E343','2','There is music in my soul today,<br/>A carol to my King;<br/>And Jesus, listening, can hear<br/>The song I cannot sing.<br/>',NULL,1785,1785);
INSERT INTO stanza VALUES('E343','3','There is springtime in my soul today,<br/>For when the Lord is near<br/>The dove of peace sings in my heart,<br/>The flowers of grace appear.<br/>',NULL,1786,1786);
INSERT INTO stanza VALUES('E343','4','There is gladness in my soul today,<br/>And hope, and praise, and love,<br/>For blessings which He gives me now,<br/>For joys laid up above.<br/>',NULL,1787,1787);
INSERT INTO stanza VALUES('E344','1','Grace there is my every debt to pay,<br/>Blood to wash my every sin away,<br/>Pow''r to keep me spotless day by day,<br/>In Christ for me.<br/>',NULL,1788,1788);
INSERT INTO stanza VALUES('E345','1','I wandered in the shades of night,<br/>Till Jesus came to me,<br/>And with the sunlight of His love<br/>Bid all my darkness flee.<br/>',NULL,1789,1789);
INSERT INTO stanza VALUES('E345','chorus','Sunlight, sunlight, in my soul today,<br/>Sunlight, sunlight, all along the way,<br/>Since the Savior found me, took away my sin,<br/>I have had the sunlight of His love within.<br/>',NULL,1790,1790);
INSERT INTO stanza VALUES('E345','2','Though clouds may gather in the sky,<br/>And billows ''round me roll,<br/>However dark the world may be,<br/>I''ve sunlight in my soul.<br/>',NULL,1791,1791);
INSERT INTO stanza VALUES('E345','3','While walking in the light of God,<br/>I sweet communion find;<br/>I press with holy vigor on<br/>And leave the world behind.<br/>',NULL,1792,1792);
INSERT INTO stanza VALUES('E345','4','Soon I shall see Him as He is,<br/>The Light that came to me;<br/>Behold the brightness of His face,<br/>Throughout eternity.<br/>',NULL,1793,1793);
INSERT INTO stanza VALUES('E346','1','I am not skilled to understand<br/>What God hath willed, what God hath planned;<br/>I only know at His right hand<br/>Stands One who is my Savior.<br/>',NULL,1794,1794);
INSERT INTO stanza VALUES('E346','2','I take Him at His word indeed:<br/>"Christ died for sinners" — this I read;<br/>For in my heart I find a need<br/>Of Him to be my Savior!<br/>',NULL,1795,1795);
INSERT INTO stanza VALUES('E346','3','That He should leave His place on high<br/>And come for sinful man to die,<br/>You count it strange? So once did I<br/>Before I knew my Savior!<br/>',NULL,1796,1796);
INSERT INTO stanza VALUES('E346','4','And, oh, that He fulfilled may see<br/>The travail of His soul in me,<br/>And with His work contented be,<br/>As I with my dear Savior!<br/>',NULL,1797,1797);
INSERT INTO stanza VALUES('E346','5','Yes, living, dying, let me bring<br/>My strength, my solace from this spring —<br/>That He who lives to be my King<br/>Once died to be my Savior!<br/>',NULL,1798,1798);
INSERT INTO stanza VALUES('E347','1','O happy day that fixed my choice<br/>On Thee, my Savior and my God!<br/>Well may this glowing heart rejoice,<br/>And tell its raptures all abroad.<br/>',NULL,1799,1799);
INSERT INTO stanza VALUES('E347','chorus','Happy day, happy day,<br/>When Jesus washed my sins away!<br/>He taught me how to watch and pray,<br/>And live rejoicing every day;<br/>Happy day, happy day,<br/>When Jesus washed my sins away!<br/>',NULL,1800,1800);
INSERT INTO stanza VALUES('E347','2','''Tis done — the great transaction''s done;<br/>I am my Lord''s, and He is mine;<br/>He drew me and I followed on,<br/>Rejoiced to own the call divine.<br/>',NULL,1801,1801);
INSERT INTO stanza VALUES('E347','3','Now rest, my long-divided heart,<br/>Fixed on this blissful center, rest;<br/>Here have I found a nobler part,<br/>Here heav''nly pleasures fill my breast.<br/',NULL,1802,1802);
INSERT INTO stanza VALUES('E347','4','High heav''n that hears the solemn vow,<br/>That vow renewed shall daily hear!<br/>Till in life''s latest hour I bow,<br/>And bless, in death, a bond so dear.<br/>',NULL,1803,1803);
INSERT INTO stanza VALUES('E348','1','Since Christ my soul from sin set free,<br/>This life has been a joy to me;<br/>And ''mid earth''s sorrows and its woe,<br/>''Tis joy my Jesus here to know.<br/>',NULL,1804,1804);
INSERT INTO stanza VALUES('E348','chorus','O hallelujah, yes, ''tis joy!<br/>For it is Christ that I enjoy!<br/>On land or sea, what matters where?<br/>Where Jesus is, my joy is there.<br/>',NULL,1805,1805);
INSERT INTO stanza VALUES('E348','2','The earth was once a bitter place<br/>Till Jesus showed His smiling face;<br/>Now joy''s begun within my soul,<br/>''Twill last while endless ages roll.<br/>',NULL,1806,1806);
INSERT INTO stanza VALUES('E348','3','What matters where on earth we dwell?<br/>On mountain top, or in the dell,<br/>In cottage, or a mansion fair,<br/>Where Jesus is, my joy is there. ?<br/>',NULL,1807,1807);
INSERT INTO stanza VALUES('E349','1','As pants the hart for cooling streams<br/>When heated in the chase,<br/>So longs my soul, O God, for Thee,<br/>And Thy refreshing grace.<br/>',NULL,1808,1808);
INSERT INTO stanza VALUES('E349','2','Why restless, why cast down, my soul?<br/>Trust God, who will employ<br/>His aid for thee, and change these sighs<br/>To thankful hymns of joy.<br/>',NULL,1809,1809);
INSERT INTO stanza VALUES('E349','3','For Thee, my God, the living God,<br/>My thirsty soul doth pine;<br/>Oh, when shall I behold Thy face,<br/>Thou Majesty Divine?<br/>',NULL,1810,1810);
INSERT INTO stanza VALUES('E349','4','God of my strength, how long shall I,<br/>Like one forgotten, mourn,<br/>Forlorn, forsaken, and exposed<br/>To my oppressor''s scorn?<br/>',NULL,1811,1811);
INSERT INTO stanza VALUES('E349','5','Why restless, why cast down, my soul?<br/>Hope still, and thou shalt sing<br/>The praise of Him who is thy God,<br/>Thy health''s eternal spring.<br/>',NULL,1812,1812);
INSERT INTO stanza VALUES('E350','1','My goal is God Himself, not joy, nor peace,<br/>Nor even blessing, but Himself, my God;<br/>''Tis His to lead me there — not mine, but His —<br/>At any cost, dear Lord, by any road.<br/>',NULL,1813,1813);
INSERT INTO stanza VALUES('E350','2','So faith bounds forward to its goal in God,<br/>And love can trust her Lord to lead her there;<br/>Upheld by Him, my soul is following hard<br/>Till God hath full fulfilled my deepest prayer.<br/>',NULL,1814,1814);
INSERT INTO stanza VALUES('E350','3','No matter if the way be sometimes dark,<br/>No matter though the cost be oft-times great,<br/>He knoweth how I best shall reach the mark,<br/>The way that leads to Him must needs be strait.<br/>',NULL,1815,1815);
INSERT INTO stanza VALUES('E350','4','One thing I know, I cannot say Him nay;<br/>One thing I do, I press towards my Lord;<br/>My God my glory here, from day to day,<br/>And in the glory there my great Reward.<br/>',NULL,1816,1816);
INSERT INTO stanza VALUES('E351','1','God the Almighty, Uncreated Life,<br/>List to my cry as I lie in the dust,<br/>Fathomless glory all about Thee is;<br/>Life Giver, my Creator, know Thee I must.<br/>',NULL,1817,1817);
INSERT INTO stanza VALUES('E351','2','Oh, by the Cross, the passion of Thy Christ,<br/>Oh, by the death of my Lord crucified,<br/>From pow''r of darkness translate me today<br/>Into the kingdom of Thy light to abide.<br/>',NULL,1818,1818);
INSERT INTO stanza VALUES('E351','3','Fill from the center with Thine utmost filling,<br/>Fill to circumf''rence, fill right to the brim;<br/>Blaze forth, the light, the glory of Thy being<br/>About and ''round me to the uttermost rim.<br/>',NULL,1819,1819);
INSERT INTO stanza VALUES('E351','4','Life Uncreated, Thou most holy God,<br/>Life-giving Spirit, oh, create in me<br/>Something that speaks of Thee and of Thy glory,<br/>Something compelling that will draw to Thee.<br/>',NULL,1820,1820);
INSERT INTO stanza VALUES('E351','5','Father, I thank Thee that my quest is ended.<br/>I reign in life with Christ upon the throne,<br/>How satisfied to triumph now in Him,<br/>The Cross the touchstone that makes me His own.<br/>',NULL,1821,1821);
INSERT INTO stanza VALUES('E352','1','In the wilderness for God!<br/>Just a common bush aflame!<br/>Thus may I be, blessed Lord,<br/>For the glory of Thy Name.<br/>',NULL,1822,1822);
INSERT INTO stanza VALUES('E352','2','Just a common bush to be,<br/>Something in which God can dwell,<br/>Something thru which God can speak,<br/>Something thru which God can tell,<br/>',NULL,1823,1823);
INSERT INTO stanza VALUES('E352','3','All His yearning over men,<br/>All His purposes of love,<br/>Flaming with no light of earth,<br/>But with glory from above:<br/>',NULL,1824,1824);
INSERT INTO stanza VALUES('E352','4','God Himself within the bush,<br/>Nothing seen but just the flame;<br/>Make me that, just that, O God,<br/>For the glory of Thy Name.<br/>',NULL,1825,1825);
INSERT INTO stanza VALUES('E353','1','I need Jesus, my need I now confess;<br/>No friend like Him in times of deep distress;<br/>I need Jesus, the need I gladly own;<br/>Though some may bear their load alone,<br/>Yet I need Jesus.<br/>',NULL,1826,1826);
INSERT INTO stanza VALUES('E353','chorus','I need Jesus, I need Jesus,<br/>I need Jesus every day;<br/>Need Him in the sunshine hour,<br/>Need Him when the storm-clouds low''r;<br/>Every day along my way,<br/>Yes, I need Jesus.<br/>',NULL,1827,1827);
INSERT INTO stanza VALUES('E353','2','I need Jesus, I need a friend like Him,<br/>A friend to guide when paths of life are dim;<br/>I need Jesus, when foes my soul assail;<br/>Alone I know I can but fail,<br/>So I need Jesus.<br/>',NULL,1828,1828);
INSERT INTO stanza VALUES('E353','3','I need Jesus, I need Him to the end;<br/>No one like Him, He is the sinner''s friend;<br/>I need Jesus, no other friend will do;<br/>So constant, kind, so strong and true,<br/>Yes, I need Jesus.<br/>',NULL,1829,1829);
INSERT INTO stanza VALUES('E354','1','Come in, O come! The door stands open now;<br/>I knew Thy voice; Lord Jesus, it was Thou.<br/>The sun has set long since; the storms begin;<br/>''Tis time for Thee, my Savior, O come in!<br/>',NULL,1830,1830);
INSERT INTO stanza VALUES('E354','2','Alas, ill-ordered shows the dreary room;<br/>The household stuff lies heaped amidst the gloom,<br/>The table empty stands, the couch undressed;<br/>Ah, what a welcome for th'' Eternal Guest!<br/>',NULL,1831,1831);
INSERT INTO stanza VALUES('E354','3','Yet welcome, and tonight; this doleful scene<br/>Is e''en itself my cause to hail Thee in;<br/>This dark confusion e''en at once demands<br/>Thine own bright presence, Lord, and ord''ring hands.<br/>',NULL,1832,1832);
INSERT INTO stanza VALUES('E354','4','I seek no more to alter things, or mend,<br/>Before the coming of so great a Friend;<br/>All were at best unseemly; and ''twere ill<br/>Beyond all else to keep Thee waiting still.<br/>',NULL,1833,1833);
INSERT INTO stanza VALUES('E354','5','Come, not to find, but make this troubled heart<br/>A dwelling worthy of Thee as Thou art;<br/>To chase the gloom, the terror, and the sin:<br/>Come, all Thyself, yea come, Lord Jesus, in!<br/>',NULL,1834,1834);
INSERT INTO stanza VALUES('E355','1','O blessed, living Lord,<br/>Engage our hearts with Thee,<br/>And strike within some answ''ring chord<br/>To love so rich and free!<br/>',NULL,1835,1835);
INSERT INTO stanza VALUES('E355','2','To know Thy loving heart!<br/>To cleave to Thy blest side!<br/>To gaze upon Thee where Thou art,<br/>And in Thy love abide!<br/>',NULL,1836,1836);
INSERT INTO stanza VALUES('E355','3','To walk with Thee below!<br/>To learn Thy holy ways!<br/>And more to Thine own stature grow,<br/>To Thine eternal praise!<br/>',NULL,1837,1837);
INSERT INTO stanza VALUES('E355','4','Thyself our one Desire!<br/>Thyself our Object here!<br/>The goal to which our hearts aspire —<br/>To meet Thee in the air!<br/>',NULL,1838,1838);
INSERT INTO stanza VALUES('E356','1','Thou Magnet of my soul!<br/>Let me come nearer, till<br/>The life of self pulsates no more,<br/>But is forever still.<br/>',NULL,1839,1839);
INSERT INTO stanza VALUES('E356','2','Thou Sunshine of my heart!<br/>Fill Thou each crevice there,<br/>And let Thy garden yield to Thee<br/>A fragrance sweet and rare.<br/>',NULL,1840,1840);
INSERT INTO stanza VALUES('E356','3','Thou Ransomer from death!<br/>Possess Thy ransomed one:<br/>Appropriate to Thine Own use<br/>The spoil that Thou hast won.<br/>',NULL,1841,1841);
INSERT INTO stanza VALUES('E356','4','Thou Lord of Life and Light!<br/>I bow beneath Thy sway,<br/>And count it holy privilege<br/>Thy precepts to obey.<br/>',NULL,1842,1842);
INSERT INTO stanza VALUES('E356','5','Thou Gift unspeakable!<br/>Straight from God''s heart of love;<br/>I break my heart to give Thee room<br/>And thus Thy sweetness prove.<br/>',NULL,1843,1843);
INSERT INTO stanza VALUES('E357','1','Come, Jesus, Lord, with holy fire,<br/>Come, and my quickened heart inspire,<br/>My conscience purged by blood;<br/>Now to my soul Thyself reveal,<br/>Thy mighty working let me feel,<br/>Since I am born of God.<br/>',NULL,1844,1844);
INSERT INTO stanza VALUES('E357','2','Let nothing now my heart divide,<br/>Since with Thee I am crucified,<br/>And live to God in Thee.<br/>Dead to the world and all its toys,<br/>Its idle pomp and fading joys,<br/>Jesus, my glory be.<br/>',NULL,1845,1845);
INSERT INTO stanza VALUES('E357','3','Now with a quenchless thirst inspire,<br/>A longing, infinite desire,<br/>And fill my craving heart.<br/>Less than Thyself, oh, do not give,<br/>In might Thyself within me live;<br/>Come, all Thou hast and art.<br/>',NULL,1846,1846);
INSERT INTO stanza VALUES('E357','4','My will be swallowed up in Thee,<br/>Light in Thy light still may I see<br/>In Thine unclouded face:<br/>Called the full strength of trust to prove,<br/>Let all my quickened heart be love,<br/>My spotless life be praise.<br/>',NULL,1847,1847);
INSERT INTO stanza VALUES('E358','1','Love Divine, all love excelling,<br/>Joy of heav''n, to earth come down;<br/>Fix in us Thy humble dwelling,<br/>All Thy faithful mercies crown.<br/>Jesus, Thou art all compassion;<br/>Pure, unbounded love Thou art;<br/>Visit us with Thy salvation,<br/>Enter every trembling heart.<br/>',NULL,1848,1848);
INSERT INTO stanza VALUES('E358','2','Breathe, O breathe Thy loving Spirit<br/>Into every troubled breast;<br/>Let us all in Thee inherit,<br/>Let us find the promised rest.<br/>Take away the love of sinning;<br/>Alpha and Omega be;<br/>End of faith, as its beginning,<br/>Set our hearts at liberty.<br/>',NULL,1849,1849);
INSERT INTO stanza VALUES('E358','3','Come, Almighty, to deliver,<br/>Let us all Thy life receive;<br/>May Thy presence e''er be with us,<br/>Never more Thy temples leave.<br/>Thee we would be always blessing,<br/>Serve Thee as Thou wouldst approve,<br/>Pray, and praise Thee without ceasing,<br/>Glory in Thy perfect love.<br/>',NULL,1850,1850);
INSERT INTO stanza VALUES('E358','4','Finish, then, Thy new creation;<br/>Pure and spotless let us be;<br/>Let us see Thy great salvation<br/>Perfectly restored in Thee;<br/>Changed from glory into glory<br/>Till with Thee we take our place,<br/>Till we cast our crowns before Thee,<br/>Lost in wonder, love and praise.<br/>',NULL,1851,1851);
INSERT INTO stanza VALUES('E359','1','O Light of light, shine in!<br/>Cast out, this night of sin,<br/>Create true day within:<br/>O Light of light, shine in!<br/>',NULL,1852,1852);
INSERT INTO stanza VALUES('E359','chorus','O Light, all light excelling,<br/>Make my heart Thy dwelling;<br/>O Joy, all grief dispelling,<br/>To my poor heart come in!<br/>',NULL,1853,1853);
INSERT INTO stanza VALUES('E359','2','O Joy of joys, come in!<br/>End Thou this grief of sin,<br/>Create calm peace within:<br/>O Joy of joys, come in!<br/>',NULL,1854,1854);
INSERT INTO stanza VALUES('E359','3','O Life of life, pour in!<br/>Expel this death of sin,<br/>Awake true life within:<br/>O Life of life, pour in!<br/>',NULL,1855,1855);
INSERT INTO stanza VALUES('E359','4','O Love of love, flow in!<br/>This hateful root of sin<br/>Deal with, renew, within:<br/>O Love of love, flow in!<br/>',NULL,1856,1856);
INSERT INTO stanza VALUES('E359','5','O Heaven of heavens, descend!<br/>This cloudy curtain rend,<br/>And all earth''s turmoil end:<br/>O Heaven of heavens, descend!<br/>',NULL,1857,1857);
INSERT INTO stanza VALUES('E359','6','My God and Lord, O come!<br/>Of joys the Joy and Sum,<br/>Make in this heart Thy home:<br/>My God and Lord, O come!<br/>',NULL,1858,1858);
INSERT INTO stanza VALUES('E360','1','O Everlasting Light,<br/>Shine graciously within;<br/>Brightest of all on earth that''s bright,<br/>Come, shine away my sin.<br/>',NULL,1859,1859);
INSERT INTO stanza VALUES('E360','2','O Everlasting Truth,<br/>Truest of all that''s true,<br/>Sure guide of erring age or youth,<br/>Lead me, and teach me too.<br/>',NULL,1860,1860);
INSERT INTO stanza VALUES('E360','3','O Everlasting Strength,<br/>Uphold me in the way;<br/>Bring me, in spite of foes, at length<br/>To joy and light of day.<br/>',NULL,1861,1861);
INSERT INTO stanza VALUES('E360','4','O Everlasting Love,<br/>Wellspring of grace and peace,<br/>Pour down Thy fulness from above,<br/>Bid doubt and trouble cease.<br/>',NULL,1862,1862);
INSERT INTO stanza VALUES('E360','5','O Everlasting Rest,<br/>Lift off life''s load of care;<br/>Relieve, revive this burdened breast<br/>And every sorrow bear.<br/>',NULL,1863,1863);
INSERT INTO stanza VALUES('E360','6','Thou art in heaven our all,<br/>Our all on earth art Thou;<br/>Upon Thy glorious Name we call,<br/>Lord Jesus, bless us now.<br/>',NULL,1864,1864);
INSERT INTO stanza VALUES('E361','1','O Love divine, by Christ revealed,<br/>Incarnate Love that died for me,<br/>To Thee myself I gladly yield,<br/>I consecrate my all to Thee.<br/>',NULL,1865,1865);
INSERT INTO stanza VALUES('E361','2','O Light divine, by Christ displayed,<br/>Source of all light, who flesh became,<br/>Shed Thy bright beams upon my head,<br/>Burn in my heart a constant flame.<br/>',NULL,1866,1866);
INSERT INTO stanza VALUES('E361','3','O Truth divine, by Christ made known,<br/>All truth must Thy reflection be;<br/>Within my heart set up Thy throne,<br/>And in Thy freedom make me free.<br/>',NULL,1867,1867);
INSERT INTO stanza VALUES('E361','4','O Cross divine, by Christ endured,<br/>Thou cross on which He groaned and died,<br/>And man''s redemption thus secured,<br/>In Thy blest shadow let me hide.<br/>',NULL,1868,1868);
INSERT INTO stanza VALUES('E361','5','O Peace divine, by Christ bestowed,<br/>Thy heavenly dove to earth come down,<br/>May He within make His abode,<br/>My life with His dear presence crown.<br/>',NULL,1869,1869);
INSERT INTO stanza VALUES('E361','6','O Joy divine, by Christ possessed,<br/>For which He did the cross endure,<br/>Fill with Thyself and make me blest,<br/>Contented, restful and secure.<br/>',NULL,1870,1870);
INSERT INTO stanza VALUES('E362','1','He died for me that I might live;<br/>I live for Him who died,<br/>My life, my love to Him I give-<br/>Jesus, the Crucified.<br/>',NULL,1871,1871);
INSERT INTO stanza VALUES('E362','chorus','O Jesus, my Lord and Savior,<br/>Help me to fully follow Thee<br/>In life and death and loving service,<br/>As Thou hast lived and died for me.<br/>',NULL,1872,1872);
INSERT INTO stanza VALUES('E362','2','He died for me that I might die<br/>To Satan, self, and sin;<br/>O death so deep! O life so high!<br/>Help me to enter in.<br/>',NULL,1873,1873);
INSERT INTO stanza VALUES('E362','3','He lives for me that I may live<br/>As spotless e''en as He;<br/>Savior, to me Thy nature give,<br/>And live Thy life in me.<br/>',NULL,1874,1874);
INSERT INTO stanza VALUES('E362','4','He lives for me that I may give<br/>His love to hearts that pine;<br/>Let me like Him for others live,<br/>And trace His steps divine.<br/>',NULL,1875,1875);
INSERT INTO stanza VALUES('E363','1','Lord, I would have Thyself in all Thy beauty,<br/>Take Thou control of all my life just now;<br/>In Thee to live, and move, and have my being,<br/>With full abandon, Lord, to Thee I bow.<br/>',NULL,1876,1876);
INSERT INTO stanza VALUES('E363','chorus','Thy blood was shed to cleanse from sin, Lord Jesus,<br/>Thy risen life transforms the old to new;<br/>I take my stand upon Thy word of promise:<br/>Sin shall not have dominion over you!<br/>',NULL,1877,1877);
INSERT INTO stanza VALUES('E363','2','Show me the things of which I am unconscious,<br/>Lord, put Thy finger now upon my heart;<br/>Whisper to me, through Thy blest Holy Spirit,<br/>Tell me what grieves Him, that it may depart.<br/>',NULL,1878,1878);
INSERT INTO stanza VALUES('E363','3','Thou art my Victor over keen temptation,<br/>Thou art my Shield, to meet the darts of sin;<br/>Lord Jesus, Thou alone can keep me trusting,<br/>And living out Thy glorious life within.<br/>',NULL,1879,1879);
INSERT INTO stanza VALUES('E364','1','Jesus, my life, Thyself apply;<br/>Thy Holy Spirit breathe;<br/>My vile affections crucify;<br/>Conform me to Thy death.<br/>',NULL,1880,1880);
INSERT INTO stanza VALUES('E364','2','Conqu''ror of hell and earth and sin,<br/>Still with the rebel strive;<br/>Enter my soul and work within,<br/>And kill and make alive.<br/>',NULL,1881,1881);
INSERT INTO stanza VALUES('E364','3','More of Thy life, and more I have,<br/>As the old Adam dies;<br/>Bury me, Savior, in Thy grave,<br/>That I with Thee may rise.<br/>',NULL,1882,1882);
INSERT INTO stanza VALUES('E364','4','Reign in me, Lord; Thy foes control,<br/>Who would not own Thy sway;<br/>Diffuse Thine image through my soul;<br/>Shine to the perfect day.<br/>',NULL,1883,1883);
INSERT INTO stanza VALUES('E364','5','Scatter the last remains of sin,<br/>And seal me Thine abode;<br/>O make me glorious all within,<br/>A temple built by God!<br/>',NULL,1884,1884);
INSERT INTO stanza VALUES('E365','1','Jesus, Thy life is mine,<br/>Dwell evermore in me;<br/>And let me see<br/>That nothing can untwine<br/>Thy life from mine.<br/>',NULL,1885,1885);
INSERT INTO stanza VALUES('E365','2','Thy life in me be shown,<br/>Lord, I would henceforth seek<br/>To think and speak<br/>Thy thoughts, Thy words alone,<br/>No more my own.<br/>',NULL,1886,1886);
INSERT INTO stanza VALUES('E365','3','Thy love, Thy joy, Thy peace,<br/>Continuously impart<br/>Unto my heart,<br/>Fresh springs that never cease,<br/>But still increase.<br/>',NULL,1887,1887);
INSERT INTO stanza VALUES('E365','4','The blest reality<br/>Of resurrection power,<br/>Thy Church''s dower,<br/>Life more abundantly,<br/>Lord, give to me.<br/>',NULL,1888,1888);
INSERT INTO stanza VALUES('E365','5','Thy fullest gift, O Lord,<br/>Now at Thy word I claim,<br/>Through Thy dear Name,<br/>And touch the rapturous chord<br/>Of praise forth-poured.<br/>',NULL,1889,1889);
INSERT INTO stanza VALUES('E365','6','Jesus, my life is Thine,<br/>And evermore shall be<br/>Hidden in Thee,<br/>For nothing can untwine<br/>Thy life from mine.<br/>',NULL,1890,1890);
INSERT INTO stanza VALUES('E366','1','Christ, whose glory fills the skies<br/>Christ, the true, the only Light,<br/>Sun of Righteousness, arise,<br/>Triumph o''er the shades of night;<br/>Dayspring from on high, be near,<br/>Daystar, in my heart appear.<br/>',NULL,1891,1891);
INSERT INTO stanza VALUES('E366','2','Dark and cheerless is the morn<br/>Unaccompanied by Thee;<br/>Joyless is the day''s return,<br/>Till Thy mercy''s beams I see,<br/>Till Thou inward light impart,<br/>Glad my eyes, and warm my heart.<br/>',NULL,1892,1892);
INSERT INTO stanza VALUES('E366','3','Visit then this soul of mine,<br/>Pierce the gloom of sin and grief;<br/>Fill me, Radiancy divine,<br/>Scatter all my unbelief;<br/>More and more Thyself display,<br/>Shining to the perfect day.<br/>',NULL,1893,1893);
INSERT INTO stanza VALUES('E367','1','Be Thou supreme, O Jesus Christ,<br/>Nor creed, nor form, nor word,<br/>Nor holy Church, nor human love,<br/>Compare with Thee, my Lord!<br/>',NULL,1894,1894);
INSERT INTO stanza VALUES('E367','2','Be Thou supreme, O Jesus Christ,<br/>Thy love has conquered me;<br/>Beneath Thy Cross I die to self,<br/>And live alone to Thee.<br/>',NULL,1895,1895);
INSERT INTO stanza VALUES('E367','3','Be Thou supreme, O Jesus Christ,<br/>My inmost being fill;<br/>So shall I think as Thou dost think,<br/>And will as Thou dost will.<br/>',NULL,1896,1896);
INSERT INTO stanza VALUES('E367','4','Be Thou supreme, O Jesus Christ,<br/>Thy life transfigure mine;<br/>And through this veil of mortal flesh,<br/>Lord, let Thy splendor shine.<br/>',NULL,1897,1897);
INSERT INTO stanza VALUES('E367','5','Be Thou supreme, O Jesus Christ,<br/>My soul exults in Thee;<br/>To be Thy slave, to do Thy will,<br/>Is my felicity.<br/>',NULL,1898,1898);
INSERT INTO stanza VALUES('E368','1','More love to Thee, O Lord,<br/>More love to Thee!<br/>Hear Thou the prayer I make<br/>On bended knee;<br/>This is my earnest plea:<br/>More love, O Lord, to Thee,<br/>More love to Thee,<br/>More love to Thee!<br/>',NULL,1899,1899);
INSERT INTO stanza VALUES('E368','2','Once earthly joy I craved,<br/>Sought peace and rest;<br/>Now Thee alone I seek,<br/>Give what is best;<br/>This all my prayer shall be:<br/>More love, O Lord, to Thee,<br/>More love to Thee,<br/>More love to Thee!<br/>',NULL,1900,1900);
INSERT INTO stanza VALUES('E368','3','Let sorrow do its work,<br/>Send grief and pain;<br/>Sweet are Thy messengers,<br/>Sweet their refrain,<br/>When they can sing with me,<br/>More love, O Lord, to Thee,<br/>More love to Thee,<br/>More love to Thee!<br/>',NULL,1901,1901);
INSERT INTO stanza VALUES('E368','4','Then shall my latest breath<br/>Whisper Thy praise;<br/>This be the parting cry<br/>My heart shall raise;<br/>This still its prayer shall be:<br/>More love, O Lord, to Thee,<br/>More love to Thee,<br/>More love to Thee!<br/>',NULL,1902,1902);
INSERT INTO stanza VALUES('E369','1','Let me love Thee, Thou art claiming<br/>Every feeling of my soul;<br/>Let that love in pow''r prevailing,<br/>Render Thee my life, my all;<br/>For life''s burdens they are easy,<br/>And life''s sorrows lose their sting,<br/>If they''re carried, Lord, to please Thee,<br/>If their pain Thy smile should win.<br/>',NULL,1903,1903);
INSERT INTO stanza VALUES('E369','chorus','Let me love Thee, Savior,<br/>Take my heart forever;<br/>Nothing but Thy favor<br/>My soul can satisfy.<br/>',NULL,1904,1904);
INSERT INTO stanza VALUES('E369','2','Let me love Thee, come revealing<br/>All Thy love has done for me;<br/>Help my heart, so unbelieving,<br/>By the sight of Calvary:<br/>Let me see Thy love despising<br/>All the shame my sins had brought;<br/>By Thy torments realizing<br/>What a price my pardon bought.<br/>',NULL,1905,1905);
INSERT INTO stanza VALUES('E369','3','Let me love Thee, I am gladdest<br/>When I''m loving Thee, the best;<br/>For in sunshine or in sadness<br/>I can find in Thee a rest;<br/>But without Thee life is fading,<br/>Treasureless its choicest flowers;<br/>Taken are its gifts eternal;<br/>Left, its empty passing hours.<br/>',NULL,1906,1906);
INSERT INTO stanza VALUES('E369','4','Let me love Thee, love is mighty,<br/>Swaying realms of deed and thought;<br/>By it I shall walk uprightly,<br/>I shall serve Thee as I ought:<br/>Love will soften every sorrow,<br/>Love will lighten every care,<br/>Love unquestioning will follow,<br/>Love will triumph, love will dare.<br/>',NULL,1907,1907);
INSERT INTO stanza VALUES('E370','1','Abide with me! Fast falls the eventide;<br/>The darkness deepens; Lord, with me abide!<br/>When other helpers fail and comforts flee,<br/>Help of the helpless, oh, abide with me.<br/>',NULL,1908,1908);
INSERT INTO stanza VALUES('E370','2','Swift to its close ebbs out life''s little day;<br/>Earth''s joys grow dim, its glories pass away;<br/>Change and decay in all around I see;<br/>O Thou who changest not, abide with me.<br/>',NULL,1909,1909);
INSERT INTO stanza VALUES('E370','3','Come not in terrors, as the King of kings;<br/>But kind and good, with healing in Thy wings:<br/>Tears for all woes, a heart for every plea;<br/>Come, Friend of sinners, thus abide with me.<br/>',NULL,1910,1910);
INSERT INTO stanza VALUES('E370','4','I need Thy presence every passing hour:<br/>What but Thy grace can foil the tempter''s power?<br/>Who like Thyself my guide and stay can be?<br/>Through cloud and sunshine, oh, abide with me.<br/>',NULL,1911,1911);
INSERT INTO stanza VALUES('E370','5','I fear no foe, with Thee at hand to bless:<br/>Ills have no weight, and tears no bitterness:<br/>Where is death''s sting? Where, grave, thy victory?<br/>I triumph still, if Thou abide with me.<br/>',NULL,1912,1912);
INSERT INTO stanza VALUES('E371','1','I need Thee every hour,<br/>Most gracious Lord;<br/>No tender voice like Thine<br/>Can peace afford.<br/>',NULL,1913,1913);
INSERT INTO stanza VALUES('E371','chorus','I need Thee, oh, I need Thee;<br/>Every hour I need Thee;<br/>Oh, bless me now, my Savior!<br/>I come to Thee.<br/>',NULL,1914,1914);
INSERT INTO stanza VALUES('E371','2','I need Thee every hour,<br/>Stay Thou near by;<br/>Temptations lose their power<br/>When Thou art nigh.<br/>',NULL,1915,1915);
INSERT INTO stanza VALUES('E371','3','I need Thee every hour,<br/>In joy or pain;<br/>Come quickly and abide,<br/>Or life is vain.<br/>',NULL,1916,1916);
INSERT INTO stanza VALUES('E371','4','I need Thee every hour,<br/>Teach me Thy will;<br/>And Thy rich promises<br/>In me fulfill.<br/>',NULL,1917,1917);
INSERT INTO stanza VALUES('E371','5','I need Thee every hour,<br/>Most Holy One;<br/>Oh, make me Thine indeed,<br/>Thou blessed Son.<br/>',NULL,1918,1918);
INSERT INTO stanza VALUES('E372','1','Nothing between my soul and the Savior,<br/>Naught of this world''s delusive dream;<br/>I have renounced all sinful pleasure;<br/>Jesus is mine, there''s nothing between.<br/>',NULL,1919,1919);
INSERT INTO stanza VALUES('E372','chorus','Nothing between my soul and the Savior,<br/>So that His blessed face may be seen;<br/>Nothing preventing the least of His favor,<br/>Keep the way clear! Let nothing between.<br/>',NULL,1920,1920);
INSERT INTO stanza VALUES('E372','2','Nothing between, like worldly pleasure;<br/>Habits of life, though harmless they seem,<br/>Must not my heart from Him e''er sever;<br/>He is my all, there''s nothing between.<br/>',NULL,1921,1921);
INSERT INTO stanza VALUES('E372','3','Nothing between, like pride or station;<br/>Self-life or friends shall not intervene;<br/>Though it may cost me much tribulation,<br/>I am resolved; there''s nothing between.<br/>',NULL,1922,1922);
INSERT INTO stanza VALUES('E372','4','Nothing between, e''en many hard trials,<br/>Though the whole world against me convene;<br/>Watching with prayer and much self-denial,<br/>I''ll triumph at last, with nothing between.<br/>',NULL,1923,1923);
INSERT INTO stanza VALUES('E373','1','Nothing between, Lord, nothing between;<br/>Let me Thy glory see,<br/>Draw my soul close to Thee,<br/>Then speak in love to me —<br/>Nothing between.<br/>',NULL,1924,1924);
INSERT INTO stanza VALUES('E373','2','Nothing between, Lord, nothing between;<br/>Let not earth''s din and noise<br/>Stifle Thy still small voice;<br/>In it let me rejoice —<br/>Nothing between.<br/>',NULL,1925,1925);
INSERT INTO stanza VALUES('E373','3','Nothing between, Lord, nothing between;<br/>Nothing of earthly care,<br/>Nothing of tear or prayer<br/>No robe that self may wear —<br/>Nothing between.<br/>',NULL,1926,1926);
INSERT INTO stanza VALUES('E373','4','Nothing between, Lord, nothing between;<br/>Unbelief disappear,<br/>Vanish each doubt and fear,<br/>Fading when Thou art near —<br/>Nothing between.<br/>',NULL,1927,1927);
INSERT INTO stanza VALUES('E373','5','Nothing between, Lord, nothing between;<br/>Shine with unclouded ray,<br/>Chasing each mist away,<br/>O''er my whole heart bear sway —<br/>Nothing between.<br/>',NULL,1928,1928);
INSERT INTO stanza VALUES('E373','6','Nothing between, Lord, nothing between;<br/>Thus may I walk with Thee,<br/>Thee only may I see,<br/>Thine only let me be —<br/>Nothing between.<br/>',NULL,1929,1929);
INSERT INTO stanza VALUES('E373','7','Nothing between, Lord, nothing between;<br/>Till Thine eternal light,<br/>Rising on earth''s dark night,<br/>Bursts on my open sight —<br/>Nothing between.<br/>',NULL,1930,1930);
INSERT INTO stanza VALUES('E374','1','Sun of my soul, Thou Savior dear,<br/>It is not night if Thou be near;<br/>Oh, may no earthborn cloud arise<br/>To hide Thee from Thy servant''s eyes.<br/>',NULL,1931,1931);
INSERT INTO stanza VALUES('E374','2','When the soft dews of kindly sleep<br/>My wearied eyelids gently steep,<br/>Be my last thought how sweet to rest<br/>Forever on my Savior''s breast.<br/>',NULL,1932,1932);
INSERT INTO stanza VALUES('E374','3','Abide with me from morn till eve,<br/>For without Thee I cannot live;<br/>Abide with me when night is nigh,<br/>For without Thee I dare not die.<br/>',NULL,1933,1933);
INSERT INTO stanza VALUES('E374','4','Come near, and bless us when we wake,<br/>Ere through the world our way we take;<br/>Till in the ocean of Thy love<br/>We lose ourselves in Thee above.<br/>',NULL,1934,1934);
INSERT INTO stanza VALUES('E375','1','There is a place of quiet rest,<br/>Near to the heart of God,<br/>A place where sin cannot molest,<br/>Near to the heart of God.<br/>',NULL,1935,1935);
INSERT INTO stanza VALUES('E375','chorus','O Jesus, blest Redeemer,<br/>Sent from the heart of God,<br/>Hold us, who wait before Thee,<br/>Near to the heart of God.<br/>',NULL,1936,1936);
INSERT INTO stanza VALUES('E375','2','There is a place of comfort sweet,<br/>Near to the heart of God,<br/>A place where we our Savior meet,<br/>Near to the heart of God.<br/>',NULL,1937,1937);
INSERT INTO stanza VALUES('E375','3','There is a place of full release,<br/>Near to the heart of God,<br/>A place where all is joy and peace,<br/>Near to the heart of God.<br/>',NULL,1938,1938);
INSERT INTO stanza VALUES('E376','1','Fill Thou my life, O Lord my God,<br/>In every part with praise,<br/>That my whole being may proclaim<br/>Thy being and Thy ways.<br/>',NULL,1939,1939);
INSERT INTO stanza VALUES('E376','2','Not for the lip of praise alone,<br/>Nor e''en the praising heart,<br/>I ask, but for a life made up<br/>Of praise in every part:<br/>',NULL,1940,1940);
INSERT INTO stanza VALUES('E376','3','Praise in the common things of life,<br/>Its goings out and in;<br/>Praise in each duty and each deed,<br/>However small and mean.<br/>',NULL,1941,1941);
INSERT INTO stanza VALUES('E376','4','Fill every part of me with praise;<br/>Let all my being speak<br/>Of Thee and of Thy love, O Lord,<br/>Poor though I be and weak.<br/>',NULL,1942,1942);
INSERT INTO stanza VALUES('E376','5','So shall no part of day or night<br/>From sacredness be free,<br/>But all my life, in every step,<br/>Be fellowship with Thee.<br/>',NULL,1943,1943);
INSERT INTO stanza VALUES('E377','1','If the path I travel<br/>Lead me to the cross,<br/>If the way Thou choosest<br/>Lead to pain and loss,<br/>Let the compensation<br/>Daily, hourly, be<br/>Shadowless communion,<br/>Blessed Lord, with Thee.<br/>',NULL,1944,1944);
INSERT INTO stanza VALUES('E377','2','If there''s less of earth joy,<br/>Give, Lord, more of heaven.<br/>Let the spirit praise Thee,<br/>Though the heart be riven;<br/>If sweet earthly ties, Lord,<br/>Break at Thy decree,<br/>Let the tie that binds us,<br/>Closer, sweeter, be.<br/>',NULL,1945,1945);
INSERT INTO stanza VALUES('E377','3','Lonely though the pathway,<br/>Cheer it with Thy smile;<br/>Be Thou my companion<br/>Through earth''s little while;<br/>Selfless may I live, Lord,<br/>By Thy grace to be<br/>Just a cleansed channel<br/>For Thy life through me.<br/>',NULL,1946,1946);
INSERT INTO stanza VALUES('E378','1','Savior, lead me up the mountain,<br/>Where the Lord alone is seen,<br/>Where we hear the voice from heaven,<br/>Where the air is pure and clean.<br/>',NULL,1947,1947);
INSERT INTO stanza VALUES('E378','chorus','Lead me higher up the mountain,<br/>Give me fellowship with Thee;<br/>In Thy light I see the fountain,<br/>And the blood it cleanses me.<br/>',NULL,1948,1948);
INSERT INTO stanza VALUES('E378','2','Higher up where light increases,<br/>Far above all earthly strife,<br/>Where the strain of effort ceases,<br/>Where in Christ we reign in Life.<br/>',NULL,1949,1949);
INSERT INTO stanza VALUES('E378','3','Savior, keep me up the mountain<br/>Pressing on toward the goal,<br/>Till, as one, we share Thine image,<br/>And Thy love and grace extol.<br/>',NULL,1950,1950);
INSERT INTO stanza VALUES('E379','1','I hunger and I thirst;<br/>Jesus, my manna be;<br/>Ye living waters, burst<br/>Out of the rock for me.<br/>',NULL,1951,1951);
INSERT INTO stanza VALUES('E379','2','Thou bruised and broken Bread,<br/>My lifelong wants supply;<br/>As living souls are fed,<br/>O feed me, or I die.<br/>',NULL,1952,1952);
INSERT INTO stanza VALUES('E379','3','Thou true life-giving Vine,<br/>Let me Thy sweetness prove;<br/>Renew my life with Thine,<br/>Refresh my soul with love.<br/>',NULL,1953,1953);
INSERT INTO stanza VALUES('E379','4','For still the desert lies<br/>My thirsting soul before;<br/>O living waters, rise<br/>Within me evermore.<br/>',NULL,1954,1954);
INSERT INTO stanza VALUES('E380','1','O Bread to pilgrims given,<br/>O Food for saints to eat,<br/>O Manna sent from heaven,<br/>For heav''n-born natures meet;<br/>Give us, for Thee long pining,<br/>To eat till richly filled;<br/>Till, earth''s delights resigning,<br/>Our every wish is stilled.<br/>',NULL,1955,1955);
INSERT INTO stanza VALUES('E380','2','O Water, life bestowing,<br/>From out the Savior''s heart,<br/>A fountain purely flowing,<br/>A fount of love Thou art.<br/>Oh, let us, freely tasting,<br/>Our burning thirst assuage;<br/>Thy sweetness, never wasting,<br/>Avails from age to age.<br/>',NULL,1956,1956);
INSERT INTO stanza VALUES('E380','3','Jesus, this feast receiving,<br/>We Thee unseen adore;<br/>Thy faithful word believing,<br/>We take, and doubt no more.<br/>Give us, Thou true and loving,<br/>On earth to live in Thee;<br/>Then, God the veil removing,<br/>Thy glorious face to see.<br/>',NULL,1957,1957);
INSERT INTO stanza VALUES('E381','1','Fill all my vision, Savior, I pray,<br/>Let me see only Jesus today;<br/>Though through the valley Thou leadest me,<br/>Thy fadeless glory encompasseth me.<br/>',NULL,1958,1958);
INSERT INTO stanza VALUES('E381','chorus','Fill all my vision, Savior divine,<br/>Till with Thy glory my spirit shall shine.<br/>Fill all my vision, that all may see<br/>Thy Holy Image reflected in me.<br/>',NULL,1959,1959);
INSERT INTO stanza VALUES('E381','2','Fill all my vision, every desire<br/>Keep for Thy glory; my soul inspire<br/>With Thy perfection, Thy holy love,<br/>Flooding my pathway with light from above.<br/>',NULL,1960,1960);
INSERT INTO stanza VALUES('E381','3','Fill all my vision, let naught of sin<br/>Shadow the brightness shining within.<br/>Let me see only Thy blessed face,<br/>Feasting my soul on Thy infinite grace.<br/>',NULL,1961,1961);
INSERT INTO stanza VALUES('E382','1','More about Jesus would I know,<br/>More of His grace to others show;<br/>More of His saving fulness see,<br/>More of His love who died for me.<br/>',NULL,1962,1962);
INSERT INTO stanza VALUES('E382','chorus','More, more about Jesus,<br/>More, more about Jesus;<br/>More of His saving fulness see,<br/>More of His love who died for me.<br/>',NULL,1963,1963);
INSERT INTO stanza VALUES('E382','2','More about Jesus let me learn,<br/>More of His holy will discern;<br/>Spirit of God my teacher be,<br/>Showing the things of Christ to me.<br/>',NULL,1964,1964);
INSERT INTO stanza VALUES('E382','3','More about Jesus; in His Word,<br/>Holding communion with my Lord;<br/>Hearing His voice in every line,<br/>Making each faithful saying mine.<br/>',NULL,1965,1965);
INSERT INTO stanza VALUES('E382','4','More about Jesus; on His throne,<br/>Riches in glory all His own;<br/>More of His kingdom''s sure increase;<br/>More of His coming, Prince of Peace.<br/>',NULL,1966,1966);
INSERT INTO stanza VALUES('E383','1','My stubborn will at last hath yielded;<br/>I would be Thine, and Thine alone,<br/>And this the prayer my lips are bringing,<br/>"Lord, let in me Thy will be done."<br/>',NULL,1967,1967);
INSERT INTO stanza VALUES('E383','chorus','Sweet will of God, still fold me closer,<br/>Till I am wholly lost in Thee;<br/>Sweet will of God, still fold me closer,<br/>Till I am wholly lost in Thee.<br/>',NULL,1968,1968);
INSERT INTO stanza VALUES('E383','2','I''m tired of sin, footsore and weary,<br/>The darksome path hath dreary grown,<br/>But now a light has ris''n to cheer me;<br/>I find in Thee my Star, my Sun.<br/>',NULL,1969,1969);
INSERT INTO stanza VALUES('E383','3','Thy precious will, O conqu''ring Savior,<br/>Doth now embrace and compass me;<br/>All discords hushed, my peace a river,<br/>My soul a prisoned bird set free.<br/>',NULL,1970,1970);
INSERT INTO stanza VALUES('E383','4','Shut in with Thee, O Lord, forever,<br/>My wayward feet no more to roam;<br/>What pow''r from Thee my soul can sever?<br/>The center of God''s will my home.<br/>',NULL,1971,1971);
INSERT INTO stanza VALUES('E384','1','My Jesus, as Thou wilt!<br/>Oh, may Thy will be mine!<br/>Into Thy hand of love<br/>I would my all resign;<br/>Through sorrow, or through joy,<br/>Conduct me as Thine own,<br/>And help me still to say,<br/>My Lord, Thy will be done!<br/>',NULL,1972,1972);
INSERT INTO stanza VALUES('E384','2','My Jesus, as Thou Wilt!<br/>Though seen through many a tear,<br/>Let not my star of hope<br/>Grow dim or disappear;<br/>Since Thou on earth hast wept,<br/>And sorrowed oft alone,<br/>If I must weep with Thee,<br/>My Lord, Thy will be done!<br/>',NULL,1973,1973);
INSERT INTO stanza VALUES('E384','3','My Jesus, as Thou wilt!<br/>All shall be well for me;<br/>Each changing future scene<br/>I gladly trust with Thee.<br/>Straight to Thy rest above<br/>I travel calmly on,<br/>And sing, in life or death,<br/>My Lord, Thy will be done!<br/>',NULL,1974,1974);
INSERT INTO stanza VALUES('E385','1','Oh, tame me, Lord! Rebellious nature calm,<br/>Oh, tame me, Lord!<br/>This heart, so tossed and filled with wild alarm,<br/>Oh, tame me, Lord!<br/>These human longings, let them end in Thee,<br/>And let me be Thy bondslave, even me!<br/>',NULL,1975,1975);
INSERT INTO stanza VALUES('E385','2','I will not ask Thee to account to me<br/>For aught Thou dost;<br/>For crosses sore, or paths I cannot see:<br/>But I will trust.<br/>No second causes shall perplex my soul,<br/>Or stay from yielding all to Thy control.<br/>',NULL,1976,1976);
INSERT INTO stanza VALUES('E385','3','The raging storm I dare not fight alone,<br/>Ah, show Thy face!<br/>Say, "It is I!" Thyself to me make known,<br/>Ah, show Thy face!<br/>Then what care I for darkest depths of woe?<br/>Thine arms, O Christ, shall fold me close, I know!<br/>',NULL,1977,1977);
INSERT INTO stanza VALUES('E385','4','Oh, save me, Lord! Subdue this stubborn will;<br/>Oh, save me, Lord!<br/>In spite of all, Thy purposes fulfill<br/>In me, Oh, Lord;<br/>I yield my self, and all I have and am,<br/>To follow Thee, Thou all redeeming Lamb!<br/>',NULL,1978,1978);
INSERT INTO stanza VALUES('E385','5','How can I fear? Thou art so near to me;<br/>How can I fear?<br/>I hear Thee say, "Believe, and thou shalt see!"<br/>How can I fear?<br/>I now believe, and trust Thy mighty power,<br/>To save, to heal, to keep this very hour!<br/>',NULL,1979,1979);
INSERT INTO stanza VALUES('E386','1','Thou my everlasting Portion,<br/>More than friend or life to me,<br/>All along my pilgrim journey,<br/>Savior, let me walk with Thee.<br/>',NULL,1980,1980);
INSERT INTO stanza VALUES('E386','chorus','Close to Thee, close to Thee,<br/>Close to Thee, close to Thee;<br/>All along my pilgrim journey,<br/>Savior, let me walk with Thee.<br/>',NULL,1981,1981);
INSERT INTO stanza VALUES('E386','2','Not for ease or worldly pleasure,<br/>Not for fame my prayer shall be;<br/>Gladly will I toil and suffer,<br/>Only let me walk with Thee.<br/>',NULL,1982,1982);
INSERT INTO stanza VALUES('E386','chorus','Close to Thee, close to Thee,<br/>Close to Thee, close to Thee;<br/>Gladly will I toil and suffer,<br/>Only let me walk with Thee.<br/>',NULL,1983,1983);
INSERT INTO stanza VALUES('E386','3','Lead me through the vale of shadows,<br/>Bear me o''er life''s fitful sea;<br/>Then the gate of life eternal<br/>May I enter, Lord, with Thee.<br/>',NULL,1984,1984);
INSERT INTO stanza VALUES('E386','chorus','Close to Thee, close to Thee,<br/>Close to Thee, close to Thee;<br/>Then the gate of life eternal<br/>May I enter, Lord, with Thee.<br/>',NULL,1985,1985);
INSERT INTO stanza VALUES('E387','1','I am Thine, O Lord, I have heard Thy voice,<br/>And it told Thy love to me;<br/>But I long to rise in the arms of faith,<br/>And be closer drawn to Thee.<br/>',NULL,1986,1986);
INSERT INTO stanza VALUES('E387','chorus','Draw me nearer, nearer, blessed Lord,<br/>To the cross where Thou hast died;<br/>Draw me nearer, nearer, nearer, blessed Lord,<br/>To Thy precious, bleeding side.<br/>',NULL,1987,1987);
INSERT INTO stanza VALUES('E387','2','Consecrate me now to Thy service, Lord,<br/>By the pow''r of grace divine;<br/>Let my soul look up with a steadfast hope,<br/>And my will be lost in Thine.<br/>',NULL,1988,1988);
INSERT INTO stanza VALUES('E387','3','O the pure delight of a single hour<br/>That before Thy throne I spend,<br/>When I kneel in prayer, and with Thee, my God,<br/>I commune as friend with friend!<br/>',NULL,1989,1989);
INSERT INTO stanza VALUES('E387','4','There are depths of love that I yet may know<br/>Ere Thee face to face I see;<br/>There are heights of joy that I yet may reach<br/>Ere I rest in peace with Thee.<br/>',NULL,1990,1990);
INSERT INTO stanza VALUES('E388','1','Hold Thou my hand: so weak I am, and helpless;<br/>I dare not take one step without Thy aid.<br/>Hold Thou my hand: for then, O Loving Savior,<br/>No dread of ill shall make my soul afraid.<br/>',NULL,1991,1991);
INSERT INTO stanza VALUES('E388','2','Hold Thou my hand: and closer, closer draw me<br/>To Thy dear self, my hope, my joy, my all;<br/>Hold Thou my hand: lest haply I should wander,<br/>And missing Thee, my trembling feet should fall.<br/>',NULL,1992,1992);
INSERT INTO stanza VALUES('E388','3','Hold Thou my hand: the way is dark before me<br/>Without the sunlight of Thy face divine;<br/>But when by faith I catch its radiant glory,<br/>What heights of joy, what rapturous songs are mine.<br/>',NULL,1993,1993);
INSERT INTO stanza VALUES('E389','1','Lord Jesus, I long in Thy presence to live,<br/>From morning to evening my one world Thou art;<br/>O let not my heart be contented or rest<br/>When loving or seeking what with Thee doth part.<br/>Each moment, each day, throughout suff''ring and pain,<br/>When nought in the world can give comfort or cheer,<br/>When sighing and weeping encompasses me,<br/>Lord, still all my sighing and wipe every tear.<br/>',NULL,1994,1994);
INSERT INTO stanza VALUES('E389','2','Each time when I dream of the goodness of life,<br/>I pray Thee, dear Lord, that Thou in it may be;<br/>O do not allow me to choose by myself,<br/>Nor seek any pleasure that''s other than Thee.<br/>Each night when alone in the stillness I lie,<br/>I pray Thee, Lord Jesus, that Thou wilt be near;<br/>Each morning ere dawn comes, while still in my sleep,<br/>Then whispering call me and open my ear.<br/>',NULL,1995,1995);
INSERT INTO stanza VALUES('E389','3','Each time, Lord, when reading in Thy holy Word,<br/>I pray that Thy glory may shine on each line,<br/>That clearly I''ll see what a Savior I have<br/>And how great salvation that Thou hast made mine.<br/>When helpless I come, Lord, to kneel at Thy throne,<br/>I pray Thee to hear me and grant me Thy grace;<br/>If thru my shortcomings Thou hear not my prayer,<br/>Withdraw not Thy presence, O hide not Thy face.<br/>',NULL,1996,1996);
INSERT INTO stanza VALUES('E389','4','Each time when of heavenly blessings I think,<br/>O let my heart long to be raptured to Thee;<br/>My only hope here is Thy coming again,<br/>My only joy there, Lord, Thy presence will be.<br/>Lord, teach me each day in Thy presence to live,<br/>From morning to evening my one world Thou art;<br/>O let not my heart be contented or rest<br/>When loving or seeking what with Thee doth part.<br/>',NULL,1997,1997);
INSERT INTO stanza VALUES('E390','1','Savior, lead me, this I pray,<br/>In the Spirit all the day;<br/>Walking in the light of life,<br/>I would cease from all my strife.<br/>',NULL,1998,1998);
INSERT INTO stanza VALUES('E390','chorus','Lead me, lead me,<br/>Savior, lead me, this I pray;<br/>Deeply in the stream of life,<br/>Lead me, Savior, in Thy way.<br/>',NULL,1999,1999);
INSERT INTO stanza VALUES('E390','2','Thou as life in me indeed,<br/>By the law of life dost lead;<br/>When Thou reignest in Thy might,<br/>All my darkness turns to light.<br/>',NULL,2000,2000);
INSERT INTO stanza VALUES('E390','3','Liberating Spirit, Thou,<br/>Wholly regulate me now;<br/>Thus my mind Thou wilt renew<br/>And Thy will I''ll fully know.<br/>',NULL,2001,2001);
INSERT INTO stanza VALUES('E391','1','Guide me, O Thou gracious Savior,<br/>Pilgrim through this barren land;<br/>I am weak, but Thou art mighty,<br/>Hold me with Thy pow''rful hand;<br/>Bread of heaven,<br/>Feed me till I want no more;<br/>Bread of heaven,<br/>Feed me till I want no more.<br/>',NULL,2002,2002);
INSERT INTO stanza VALUES('E391','2','Open now the crystal fountain,<br/>Whence the healing waters flow;<br/>Let the fiery, cloudy pillar<br/>Lead me all my journey through;<br/>Strong Deliv''rer,<br/>Be Thou still my strength and shield;<br/>Strong Deliv''rer,<br/>Be Thou still my strength and shield.<br/>',NULL,2003,2003);
INSERT INTO stanza VALUES('E392','1','Jesus, Savior, pilot me<br/>Over life''s tempestuous sea;<br/>Unknown waves before me roll,<br/>Hiding rock and treach''rous shoal;<br/>Chart and compass come from Thee;<br/>Jesus, Savior, pilot me.<br/>',NULL,2004,2004);
INSERT INTO stanza VALUES('E392','2','As a mother stills her child,<br/>Thou canst hush the ocean wild;<br/>Boist''rous waves obey Thy will<br/>When Thou say''st to them, "Be still."<br/>Wondrous Sov''reign of the sea,<br/>Jesus, Savior, pilot me.<br/>',NULL,2005,2005);
INSERT INTO stanza VALUES('E392','3','Though death''s valley I may pass,<br/>Still Thy grace will fear surpass;<br/>In Thy presence I will rest,<br/>And, while leaning on Thy breast,<br/>I will hear Thee say to me,<br/>"Fear not, I will pilot thee."<br/>',NULL,2006,2006);
INSERT INTO stanza VALUES('E393','1','Thy way, not mine, O Lord,<br/>However dark it be;<br/>Lead me by Thine own hand,<br/>Choose out the path for me.<br/>',NULL,2007,2007);
INSERT INTO stanza VALUES('E393','2','Smooth let it be, or rough,<br/>It will be still the best;<br/>Winding or straight it leads<br/>Right onward to Thy rest.<br/>',NULL,2008,2008);
INSERT INTO stanza VALUES('E393','3','I dare not choose my lot;<br/>I would not if I might:<br/>Choose Thou for me, my God,<br/>So shall I walk aright.<br/>',NULL,2009,2009);
INSERT INTO stanza VALUES('E393','4','Take Thou my cup, and it<br/>With joy or sorrow fill,<br/>As best to Thee may seem;<br/>Choose Thou my good and ill.<br/>',NULL,2010,2010);
INSERT INTO stanza VALUES('E393','5','Choose Thou for me my friends,<br/>My sickness or my health.<br/>Choose Thou my cares for me,<br/>My poverty or wealth.<br/>',NULL,2011,2011);
INSERT INTO stanza VALUES('E393','6','Not mine, not mine the choice,<br/>In things both great and small;<br/>Be Thou my guide, my strength,<br/>My wisdom and my all.<br/>',NULL,2012,2012);
INSERT INTO stanza VALUES('E394','1','Unto him that hath Thou givest<br/>Ever more abundantly;<br/>Lord, I live because Thou livest,<br/>Therefore give more life to me,<br/>Therefore speed me in the race,<br/>Therefore let me grow in grace.<br/>',NULL,2013,2013);
INSERT INTO stanza VALUES('E394','2','Deepen all Thy work, O Master,<br/>Strengthen every downward root;<br/>Only do Thou ripen faster,<br/>More and more Thy pleasant fruit;<br/>Purge me, prune me, self abase;<br/>Only let me grow in grace.<br/>',NULL,2014,2014);
INSERT INTO stanza VALUES('E394','3','Let me grow by sun and shower,<br/>Every moment water me;<br/>Make me really, hour by hour,<br/>More and more conformed to Thee,<br/>That Thy loving eye may trace<br/>Day by day my growth in grace.<br/>',NULL,2015,2015);
INSERT INTO stanza VALUES('E394','4','From Thy fulness grace outpouring,<br/>Show me ever greater things;<br/>Raise me higher, sunward soaring,<br/>Mounting as on eagle-wings.<br/>By the brightness of Thy face,<br/>Ever let me grow in grace.<br/>',NULL,2016,2016);
INSERT INTO stanza VALUES('E394','5','Let me, then, be always growing,<br/>Never, never standing still,<br/>Listening, learning, better knowing<br/>Thee and Thy most blessed will.<br/>Till I win the glorious race,<br/>Daily let me grow in grace.<br/>',NULL,2017,2017);
INSERT INTO stanza VALUES('E395','1','O Jesus Christ, grow Thou in me,<br/>And all things else recede;<br/>My heart be daily nearer Thee,<br/>From sin be daily freed.<br/>',NULL,2018,2018);
INSERT INTO stanza VALUES('E395','chorus','Each day let Thy supporting might<br/>My weakness still embrace;<br/>My darkness vanish in Thy light,<br/>Thy life my death efface.<br/>',NULL,2019,2019);
INSERT INTO stanza VALUES('E395','2','In Thy bright beams which on me fall,<br/>Fade every evil thought;<br/>That I am nothing, Thou art all,<br/>I would be daily taught.<br/>',NULL,2020,2020);
INSERT INTO stanza VALUES('E395','3','More of Thy glory let me see,<br/>Thou Holy, Wise, and True;<br/>I would Thy living image be,<br/>In joy and sorrow too.<br/>',NULL,2021,2021);
INSERT INTO stanza VALUES('E395','4','Fill me with gladness from above,<br/>Hold me by strength divine;<br/>Lord, let the glow of Thy great love<br/>Through all my being shine.<br/>',NULL,2022,2022);
INSERT INTO stanza VALUES('E395','5','Make this poor self grow less and less,<br/>Be Thou my life and aim;<br/>Oh, make me daily through Thy grace<br/>More meet to bear Thy name.<br/>',NULL,2023,2023);
INSERT INTO stanza VALUES('E396','1','I''m pressing on the upward way,<br/>New heights I''m gaining every day;<br/>Still praying as I onward bound,<br/>"Lord, plant my feet on higher ground."<br/>',NULL,2024,2024);
INSERT INTO stanza VALUES('E396','chorus','Lord, lift me up, and let me stand<br/>By faith on Canaan''s tableland;<br/>A higher plane than I have found,<br/>Lord, plant my feet on higher ground.<br/>',NULL,2025,2025);
INSERT INTO stanza VALUES('E396','2','My heart has no desire to stay<br/>Where doubts arise and fears dismay;<br/>Though some may dwell where these abound,<br/>My prayer, my aim, is higher ground.<br/>',NULL,2026,2026);
INSERT INTO stanza VALUES('E396','3','I want to live above the world,<br/>Though Satan''s darts at me are hurled;<br/>For faith has caught the joyful sound,<br/>The song of saints on higher ground.<br/>',NULL,2027,2027);
INSERT INTO stanza VALUES('E396','4','I want to scale the utmost height<br/>And catch a gleam of glory bright;<br/>But still I''ll pray till rest I''ve found,<br/>"Lord, lead me on to higher ground.''''<br/>',NULL,2028,2028);
INSERT INTO stanza VALUES('E397','1','More holiness give me,<br/>More sweetness within,<br/>More patience in suff''ring,<br/>More sorrow for sin,<br/>More faith in my Savior,<br/>More sense of His care,<br/>More joy in His service,<br/>More freedom in prayer.<br/>',NULL,2029,2029);
INSERT INTO stanza VALUES('E397','chorus','Come, my Savior, and help me,<br/>Comfort, strengthen and keep me;<br/>Thou each moment wilt save me,<br/>Thou art saving me now.<br/>',NULL,2030,2030);
INSERT INTO stanza VALUES('E397','2','More gratitude give me,<br/>More trust in the Lord,<br/>More zeal for His glory,<br/>More hope in His Word,<br/>More tears for His sorrows,<br/>More pain at His grief,<br/>More meekness in trial,<br/>More praise for relief.<br/>',NULL,2031,2031);
INSERT INTO stanza VALUES('E397','3','More victory give me,<br/>More strength to o''ercome,<br/>More freedom from earth-stains,<br/>More quest for the throne,<br/>More fit for the kingdom,<br/>More useful I''d be,<br/>More blessed and holy,<br/>More, Savior, like Thee.<br/>',NULL,2032,2032);
INSERT INTO stanza VALUES('E398','1','O to be like Thee! Blessed Redeemer;<br/>This is my constant longing and prayer;<br/>Gladly I''ll forfeit all of earth''s treasures,<br/>Jesus, Thy perfect likeness to wear.<br/>',NULL,2033,2033);
INSERT INTO stanza VALUES('E398','chorus','O to be like Thee! O to be like Thee!<br/>Blessed Redeemer, pure as Thou art;<br/>Come in Thy sweetness, come in Thy fullness;<br/>Stamp Thine own image deep on my heart.<br/>',NULL,2034,2034);
INSERT INTO stanza VALUES('E398','2','O to be like Thee! Full of compassion,<br/>Loving, forgiving, tender and kind,<br/>Helping the helpless, cheering the fainting,<br/>Seeking the wand''ring sinners to find.<br/>',NULL,2035,2035);
INSERT INTO stanza VALUES('E398','3','O to be like Thee! Lowly in spirit,<br/>Holy and harmless, patient and brave;<br/>Meekly enduring cruel reproaches,<br/>Willing to suffer, others to save.<br/>',NULL,2036,2036);
INSERT INTO stanza VALUES('E398','4','O to be like Thee! Lord, I am coming,<br/>Now to receive th'' anointing divine;<br/>All that I am and have I am bringing;<br/>Lord, from this moment all shall be Thine.<br/>',NULL,2037,2037);
INSERT INTO stanza VALUES('E398','5','O to be like Thee! While I am pleading<br/>Pour out Thy Spirit, fill with Thy love.<br/>Make me a temple meet for Thy dwelling,<br/>Fit for a life which Thou wouldst approve.<br/>',NULL,2038,2038);
INSERT INTO stanza VALUES('E399','1','Changed into His likeness!<br/>This my heart''s desire!<br/>May the Lord fulfill it,<br/>All my soul inspire.<br/>',NULL,2039,2039);
INSERT INTO stanza VALUES('E399','2','Changed into His likeness!<br/>He the Spirit is!<br/>If the Spirit governs,<br/>He''ll fulfill my wish.<br/>',NULL,2040,2040);
INSERT INTO stanza VALUES('E399','3','As a glass, beholding<br/>With uncovered face,<br/>I can see His glory<br/>And reflect His grace.<br/>',NULL,2041,2041);
INSERT INTO stanza VALUES('E399','4','O that no more covering<br/>May the Lord obscure,<br/>That I may reflect Him<br/>With a heart made pure.<br/>',NULL,2042,2042);
INSERT INTO stanza VALUES('E399','5','Gazing on His glory,<br/>Face to face to see;<br/>Constantly beholding,<br/>Ever would I be.<br/>',NULL,2043,2043);
INSERT INTO stanza VALUES('E399','6','Changed into His likeness!<br/>This my heart''s one quest!<br/>From my heart reflected,<br/>He will be expressed.<br/>',NULL,2044,2044);
INSERT INTO stanza VALUES('E399','7','Changed into His likeness<br/>And reflecting more<br/>Glory unto glory,<br/>Boundless evermore.<br/>',NULL,2045,2045);
INSERT INTO stanza VALUES('E400','1','Earthly pleasures vainly call me,<br/>I would be like Jesus;<br/>Nothing worldly shall enthrall me,<br/>I would be like Jesus.<br/>',NULL,2046,2046);
INSERT INTO stanza VALUES('E400','chorus','Be like Jesus, this my song,<br/>In the home and in the throng;<br/>Be like Jesus, all day long!<br/>I would be like Jesus.<br/>',NULL,2047,2047);
INSERT INTO stanza VALUES('E400','2','He has broken every fetter,<br/>I would be like Jesus;<br/>That my soul may serve Him better,<br/>I would be like Jesus.<br/>',NULL,2048,2048);
INSERT INTO stanza VALUES('E400','3','All the way from earth to glory,<br/>I would be like Jesus;<br/>Telling o''er and o''er the story,<br/>I would be like Jesus.<br/>',NULL,2049,2049);
INSERT INTO stanza VALUES('E401','1','May the mind of Christ my Savior<br/>Live in me from day to day,<br/>By His love and pow''r controlling<br/>All I do and say.<br/>',NULL,2050,2050);
INSERT INTO stanza VALUES('E401','2','May the Word of Christ dwell richly<br/>In my heart from hour to hour,<br/>So that all may see I triumph<br/>Only through His pow''r.<br/>',NULL,2051,2051);
INSERT INTO stanza VALUES('E401','3','May the peace of Christ my Savior<br/>Rule my life in every thing,<br/>That I may be calm to comfort<br/>Sick and sorrowing.<br/>',NULL,2052,2052);
INSERT INTO stanza VALUES('E401','4','May the love of Jesus fill me,<br/>As the waters fill the sea;<br/>Him exalting, self abasing,<br/>This is victory.<br/>',NULL,2053,2053);
INSERT INTO stanza VALUES('E401','5','May I run the race before me,<br/>Strong and brave to face the foe,<br/>Looking only unto Jesus<br/>As I onward go.<br/>',NULL,2054,2054);
INSERT INTO stanza VALUES('E401','6','May His beauty rest upon me<br/>As I seek the lost to win,<br/>And may they forget the channel,<br/>Seeing only Him.<br/>',NULL,2055,2055);
INSERT INTO stanza VALUES('E402','1','I want that adorning divine,<br/>Thou only, my Lord, canst bestow;<br/>I want in those beautiful garments to shine,<br/>Which mark out Thy beauty below.<br/>',NULL,2056,2056);
INSERT INTO stanza VALUES('E402','2','I want every moment to feel<br/>Thy Spirit indwelling my heart,<br/>His pow''r ever present to cleanse and to heal,<br/>And newness of life to impart.<br/>',NULL,2057,2057);
INSERT INTO stanza VALUES('E402','3','I want, oh, I want to attain<br/>Some likeness, my Savior, to Thee;<br/>That longed-for resemblance once more to regain;<br/>Thy comeliness put upon me.<br/>',NULL,2058,2058);
INSERT INTO stanza VALUES('E402','4','I want to be marked for Thine own,<br/>Thy seal on my forehead to wear;<br/>And have that new name on the mystic white stone,<br/>Which none but Thyself can declare.<br/>',NULL,2059,2059);
INSERT INTO stanza VALUES('E402','5','I want, and this sums up my prayer,<br/>To glorify Thee till I die;<br/>Then calmly to yield up my soul to Thy care,<br/>And breathe out in faith my last sigh!<br/>',NULL,2060,2060);
INSERT INTO stanza VALUES('E403','1','Live Thyself, Lord Jesus, through me,<br/>For my very life art Thou;<br/>Thee I take to all my problems<br/>As the full solution now.<br/>Live Thyself, Lord Jesus, through me,<br/>In all things Thy will be done;<br/>I but a transparent vessel<br/>To make visible the Son.<br/>',NULL,2061,2061);
INSERT INTO stanza VALUES('E403','2','Consecrated is Thy temple,<br/>Purged from every stain and sin;<br/>May Thy flame of glory now be<br/>Manifested from within.<br/>Let the earth in solemn wonder<br/>See my body willingly<br/>Offered as Thy slave obedient,<br/>Energized alone by Thee.<br/>',NULL,2062,2062);
INSERT INTO stanza VALUES('E403','3','Every moment, every member,<br/>Girded, waiting Thy command;<br/>Underneath the yoke to labor<br/>Or be laid aside as planned.<br/>When restricted in pursuing,<br/>No disquiet will beset;<br/>Underneath Thy faithful dealing<br/>Not a murmur or regret.<br/>',NULL,2063,2063);
INSERT INTO stanza VALUES('E403','4','Ever tender, quiet, restful,<br/>Inclinations put away,<br/>That Thou may for me choose freely<br/>As Thy finger points the way.<br/>Live Thyself, Lord Jesus, through me,<br/>For my very life art Thou<br/>Thee I take to all my problems<br/>As the full solution now.<br/>',NULL,2064,2064);
INSERT INTO stanza VALUES('E404','1','Let me come closer to Thee, Lord Jesus,<br/>Oh, closer day by day;<br/>Let me lean harder on Thee, Lord Jesus,<br/>Yes, harder, all the way.<br/>',NULL,2065,2065);
INSERT INTO stanza VALUES('E404','2','Let me show forth Thy beauty, Lord Jesus,<br/>Like sunshine on the hills;<br/>Oh, let my lips pour forth all Thy sweetness<br/>In joyous sparkling rills.<br/>',NULL,2066,2066);
INSERT INTO stanza VALUES('E404','3','Yes, like a channel, precious Lord Jesus,<br/>Make me and let me be;<br/>Keep me and use me daily, Lord Jesus,<br/>For Thee, for only Thee.<br/>',NULL,2067,2067);
INSERT INTO stanza VALUES('E404','4','In all my heart and will, O Lord Jesus,<br/>Be altogether king;<br/>Make me a loyal subject, Lord Jesus,<br/>To Thee in everything.<br/>',NULL,2068,2068);
INSERT INTO stanza VALUES('E404','5','Thirsting and hungering for Thee, Lord Jesus,<br/>With blessed hunger here.<br/>Longing for New Jerusalem''s fullness-<br/>No thirst, no hunger there.<br/>',NULL,2069,2069);
INSERT INTO stanza VALUES('E405','1','Having seen the world''s fair beauty,<br/>Lord, I would be blind once more,<br/>Lest I lose the loving Presence<br/>And Delight I knew before.<br/>',NULL,2070,2070);
INSERT INTO stanza VALUES('E405','chorus','Having seen the world''s fair beauty,<br/>Lord, I would be blind once more,<br/>Lest I lose the loving Presence<br/>And Delight I knew before.<br/>',NULL,2071,2071);
INSERT INTO stanza VALUES('E405','2','Dawn and sunset, star and moonlight,<br/>I can see in paradise,<br/>But while here on earth His mercy<br/>For my blindness will suffice.<br/>',NULL,2072,2072);
INSERT INTO stanza VALUES('E405','3','I no more would be delivered<br/>From my thorn, but look for grace,<br/>While within the veil His glory<br/>Shineth brightly on my face.<br/>',NULL,2073,2073);
INSERT INTO stanza VALUES('E405','4','In the deep dark night, His beauty<br/>I by faith, not sight, may trace;<br/>He was ridiculed and hated,<br/>Yet I see His glorious face.<br/>',NULL,2074,2074);
INSERT INTO stanza VALUES('E405','5','Sun and moonlight far surpassing,<br/>Clouds and Milky Way o''erspread,<br/>Is the glory all transcending<br/>Shining from His thorn-crowned head.<br/>',NULL,2075,2075);
INSERT INTO stanza VALUES('E406','1','Teach me Thy way, O Lord,<br/>Teach me Thy way;<br/>Thy gracious aid afford,<br/>Teach me Thy way.<br/>Help me to walk aright;<br/>More by faith, less by sight;<br/>Lead me with heav''nly light,<br/>Teach me Thy way.<br/>',NULL,2076,2076);
INSERT INTO stanza VALUES('E406','2','When doubts and fears arise,<br/>Teach me Thy way;<br/>When storms overspread the skies,<br/>Teach me Thy way.<br/>Shine through the cloud and rain,<br/>Through sorrow, toil, and pain;<br/>Make Thou my pathway plain,<br/>Teach me Thy way.<br/>',NULL,2077,2077);
INSERT INTO stanza VALUES('E406','3','Long as my life shall last,<br/>Teach me Thy way;<br/>Where''er my lot be cast,<br/>Teach me Thy way.<br/>Until the race is run,<br/>Until the journey''s done,<br/>Until the crown is won,<br/>Teach me Thy way.<br/>',NULL,2078,2078);
INSERT INTO stanza VALUES('E407','1','Search me, O God, my actions try,<br/>And let my life appear<br/>As seen by Thine all-searching eye-<br/>To mine my ways make clear.<br/>',NULL,2079,2079);
INSERT INTO stanza VALUES('E407','2','Search all my sense, and know my heart<br/>Who only canst make known,<br/>And let the deep, the hidden part<br/>To me be fully shown.<br/>',NULL,2080,2080);
INSERT INTO stanza VALUES('E407','3','Throw light into the darkened cells,<br/>Where passion reigns within;<br/>Quicken my conscience till it feels<br/>The loathsomeness of sin.<br/>',NULL,2081,2081);
INSERT INTO stanza VALUES('E407','4','Search all my thoughts, the secret springs,<br/>The motives that control;<br/>The chambers where polluted things<br/>Hold empire o''er the soul.<br/>',NULL,2082,2082);
INSERT INTO stanza VALUES('E407','5','Search, till Thy fiery glance has cast<br/>Its holy light through all,<br/>And I by grace am brought at last<br/>Before Thy face to fall.<br/>',NULL,2083,2083);
INSERT INTO stanza VALUES('E407','6','Thus prostrate I shall learn of Thee,<br/>What now I feebly prove,<br/>That God alone in Christ can be<br/>Unutterable love.<br/>',NULL,2084,2084);
INSERT INTO stanza VALUES('E408','1','Lord Jesus, I long to be perfectly whole,<br/>I want Thee forever to live in my soul;<br/>Break down every idol, cast out every foe;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2085,2085);
INSERT INTO stanza VALUES('E408','chorus','Whiter than snow; yes, whiter than snow;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2086,2086);
INSERT INTO stanza VALUES('E408','2','Lord Jesus, let nothing unholy remain,<br/>Apply Thine own blood and extract every stain;<br/>To get this blest cleansing I all things forego;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2087,2087);
INSERT INTO stanza VALUES('E408','3','Lord Jesus, look down from Thy throne in the skies,<br/>And help me to make a complete sacrifice;<br/>I give up myself and whatever I know;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2088,2088);
INSERT INTO stanza VALUES('E408','4','Lord Jesus, for this I most humbly entreat;<br/>I wait, blessed Lord, at Thy crucified feet;<br/>By faith, for my cleansing I see Thy blood flow;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2089,2089);
INSERT INTO stanza VALUES('E408','5','Lord Jesus, Thou seest I patiently wait;<br/>Come now, and within me a new heart create;<br/>To those who have sought Thee Thou never saidst, No;<br/>Now wash me, and I shall be whiter than snow.<br/>',NULL,2090,2090);
INSERT INTO stanza VALUES('E409','1','One thing I of the Lord desire,<br/>For all my path hath miry been:<br/>Be it by water or by fire,<br/>Oh, make me clean, oh, make me clean!<br/>',NULL,2091,2091);
INSERT INTO stanza VALUES('E409','chorus','So wash me, Thou, without, within,<br/>Or purge with fire, if that must be;<br/>No matter how, if only sin<br/>Die out in me, die out in me.<br/>',NULL,2092,2092);
INSERT INTO stanza VALUES('E409','2','I watch to shun the miry way,<br/>And staunch the springs of guilty thought;<br/>But, watch and struggle as I may,<br/>Pure I am not, pure I am not.<br/>',NULL,2093,2093);
INSERT INTO stanza VALUES('E409','3','If clearer vision Thou impart,<br/>Grateful and glad my soul shall be,<br/>But yet to have a purer heart<br/>Is more to me, is more to me.<br/>',NULL,2094,2094);
INSERT INTO stanza VALUES('E409','4','Yea, only as this heart is clean<br/>May larger vision yet be mine,<br/>For mirrored in the depths are seen<br/>The things divine, the things divine.<br/>',NULL,2095,2095);
INSERT INTO stanza VALUES('E410','1','Oh, for a heart to praise my God,<br/>A heart from sin set free,<br/>With conscience sprinkled by the blood<br/>So freely shed for me.<br/>',NULL,2096,2096);
INSERT INTO stanza VALUES('E410','2','A heart resigned, submissive, meek,<br/>My dear Redeemer''s throne;<br/>Where only Christ is heard to speak,<br/>Where Jesus reigns alone.<br/>',NULL,2097,2097);
INSERT INTO stanza VALUES('E410','3','A humble, lowly, contrite heart,<br/>Believing, true, and clean,<br/>Which neither death nor life can part<br/>From Him that dwells within.<br/>',NULL,2098,2098);
INSERT INTO stanza VALUES('E410','4','A heart in every thought renewed,<br/>And filled with love divine;<br/>Perfect and right, and pure and good,<br/>A copy, Lord, of Thine.<br/>',NULL,2099,2099);
INSERT INTO stanza VALUES('E410','5','Thy nature, gracious Lord, impart,<br/>Come quickly from above;<br/>Write Thy new name upon my heart,<br/>Thy new, best name of Love.<br/>',NULL,2100,2100);
INSERT INTO stanza VALUES('E411','1','Bless''d are the pure in heart,<br/>For they shall see our God;<br/>The secret of the Lord is theirs,<br/>Their heart is Christ''s abode.<br/>',NULL,2101,2101);
INSERT INTO stanza VALUES('E411','2','The Lord, who left the heavens,<br/>Our life and peace to bring,<br/>To dwell in lowliness with men,<br/>Their pattern and their King.<br/>',NULL,2102,2102);
INSERT INTO stanza VALUES('E411','3','He to the lowly soul<br/>Doth still Himself impart,<br/>And for His dwelling and His throne<br/>Chooseth the pure in heart.<br/>',NULL,2103,2103);
INSERT INTO stanza VALUES('E411','4','Lord, we Thy presence seek;<br/>May ours this blessing be;<br/>Give us a pure and lowly heart,<br/>A temple meet for Thee.<br/>',NULL,2104,2104);
INSERT INTO stanza VALUES('E412','1','Lord, reveal Thyself to me,<br/>That the flesh I''ll fully know;<br/>May Thy grace so work in me,<br/>That in dust I''ll lowly bow.<br/>How I long for victory,<br/>Yet, thru all my life, how weak!<br/>Evil things I cannot leave,<br/>Nor can do the good I seek.<br/>',NULL,2105,2105);
INSERT INTO stanza VALUES('E412','2','Inwardly I want the Lord,<br/>But my conduct hateful is;<br/>Though I would, I cannot change,<br/>O what real bondage ''tis!<br/>By God''s law my sin''s revealed,<br/>But the law of sin doth bind;<br/>Though I struggle to be free,<br/>No release my soul can find.<br/>',NULL,2106,2106);
INSERT INTO stanza VALUES('E412','3','Many times I fall and rise,<br/>Oft resolve, and often fail;<br/>Craving vict''ry, I retreat,<br/>And my sad defeat bewail.<br/>Truly I am sold to sin<br/>And completely powerless;<br/>There''s no good within my flesh,<br/>All is dark and sinfulness.<br/>',NULL,2107,2107);
INSERT INTO stanza VALUES('E412','4','Now I know myself in part,<br/>And confess my helplessness;<br/>All my temperament is odd,<br/>All my life corrupted is.<br/>Subtle self I cannot trust,<br/>Nor to fleshly strength can cling;<br/>All my trust and all my hope<br/>Is in Jesus Christ my King.<br/>',NULL,2108,2108);
INSERT INTO stanza VALUES('E412','5','May the Cross put me to death<br/>That on Christ I may rely;<br/>May His Holy Spirit fill,<br/>That Himself I may apply.<br/>May His death so work in me<br/>Daily deeper than before,<br/>That my self may be destroyed<br/>And His life thru me may pour.<br/>',NULL,2109,2109);
INSERT INTO stanza VALUES('E412','6','O how bitter is my case!<br/>Who this wretched slave can free,<br/>Who deliver from this death,<br/>To a life of victory?<br/>Jesus shed His blood for me,<br/>Christ is now my holiness;<br/>I receive Him as my life<br/>And my portion measureless.<br/>',NULL,2110,2110);
INSERT INTO stanza VALUES('E412','7','Now I''m wholly sanctified,<br/>Selfless, I obey His word;<br/>Nevermore to feel ashamed<br/>When I come before the Lord.<br/>How transcendent is this life!<br/>Grace thru faith He gives to me!<br/>Praise the Lord, He heard my cry<br/>And has made me wholly free.<br/>',NULL,2111,2111);
INSERT INTO stanza VALUES('E413','1','Jesus, cast a look on me;<br/>Give me sweet simplicity;<br/>Make me poor, and keep me low,<br/>Seeking only Thee to know.<br/>',NULL,2112,2112);
INSERT INTO stanza VALUES('E413','2','Weaned from all my lordly self,<br/>Weaned from all the miser''s pelf,<br/>Weaned from all the scorner''s ways,<br/>Weaned from all the lust of praise.<br/>',NULL,2113,2113);
INSERT INTO stanza VALUES('E413','3','All that feeds my busy pride,<br/>Cast it evermore aside;<br/>Bid my will to Thine submit,<br/>Lay me humbly at Thy feet.<br/>',NULL,2114,2114);
INSERT INTO stanza VALUES('E413','4','Make me like a little child,<br/>Of my strength and wisdom spoiled;<br/>Seeing only in Thy light,<br/>Walking only in Thy might;<br/>',NULL,2115,2115);
INSERT INTO stanza VALUES('E413','5','Leaning on Thy loving breast,<br/>Where a weary soul may rest;<br/>Feeling well the peace of God<br/>Flowing from Thy precious blood.<br/>',NULL,2116,2116);
INSERT INTO stanza VALUES('E413','6','In this posture let me live,<br/>And hosannas daily give;<br/>In this temper let me die,<br/>And hosannas ever cry.<br/>',NULL,2117,2117);
INSERT INTO stanza VALUES('E414','1','My Savior, Thou has offered rest:<br/>Oh, give it then to me;<br/>The rest of ceasing from myself,<br/>To find my all in Thee.<br/>',NULL,2118,2118);
INSERT INTO stanza VALUES('E414','2','This cruel self, oh, how it strives<br/>And works within my breast,<br/>To come between Thee and my soul,<br/>And keep me back from rest.<br/>',NULL,2119,2119);
INSERT INTO stanza VALUES('E414','3','How many subtle forms it takes<br/>Of seeming verity,<br/>As if it were not safe to rest<br/>And venture all on Thee.<br/>',NULL,2120,2120);
INSERT INTO stanza VALUES('E414','4','O Lord, I seek a holy rest,<br/>A victory over sin;<br/>I seek that Thou alone shouldst reign<br/>O''er all without, within.<br/>',NULL,2121,2121);
INSERT INTO stanza VALUES('E414','5','In Thy strong hand I lay me down,<br/>So shall the work be done;<br/>For who can work so wondrously<br/>As the Almighty One?<br/>',NULL,2122,2122);
INSERT INTO stanza VALUES('E414','6','Work on, then, Lord, till on my soul<br/>Eternal light shall break,<br/>And, in Thy likeness perfected,<br/>I "satisfied" shall wake.<br/>',NULL,2123,2123);
INSERT INTO stanza VALUES('E415','1','There is a foe whose hidden pow''r<br/>The Christian well may fear,<br/>More subtle far than inbred sin,<br/>And to the heart more dear.<br/>It is the pow''r of selfishness,<br/>It is the willful I,<br/>And ere my Lord can live in me,<br/>My very self must die.<br/>',NULL,2124,2124);
INSERT INTO stanza VALUES('E415','2','There is, like Anak''s sons of old,<br/>A race of giants still:<br/>Self-glorying, self-confidence,<br/>Self-seeking and self-will.<br/>Still must these haughty Anakims<br/>By Caleb''s sword be slain,<br/>Ere Hebron''s heights of heav''nly love,<br/>Our conqu''ring feet can gain.<br/>',NULL,2125,2125);
INSERT INTO stanza VALUES('E415','3','Oh, save me from self-will, dear Lord,<br/>Which claims Thy sacred throne;<br/>Oh! Let my will be lost in Thine,<br/>And let Thy will be done.<br/>Oh, keep me from self-confidence,<br/>And self-sufficiency;<br/>Let me exchange my strength for Thine,<br/>And lean alone on Thee.<br/>',NULL,2126,2126);
INSERT INTO stanza VALUES('E415','4','Oh, save me from self-seeking, Lord,<br/>Let me not be my own;<br/>A living sacrifice I come,<br/>Lord, keep me Thine alone.<br/>From proud vain glory save me, Lord,<br/>From pride of praise and fame;<br/>To Christ be all the honor given,<br/>The glory to His name.<br/>',NULL,2127,2127);
INSERT INTO stanza VALUES('E415','5','Oh, Savior, slay the self in me<br/>By Thy consuming breath;<br/>Show me Thy heart, Thy wounds, Thy shame,<br/>That self be put to death.<br/>When the Shekinah flame came down,<br/>E''en Moses could not stay;<br/>So let Thy glory fill me now,<br/>And self forever slay.<br/>',NULL,2128,2128);
INSERT INTO stanza VALUES('E416','1','Lower and lower, dear Lord, at Thy feet,<br/>Seeking Thy Spirit, Thy mercy so sweet;<br/>Down in our need, blessed Master, we fall,<br/>Lower and lower; be Thou all in all.<br/>',NULL,2129,2129);
INSERT INTO stanza VALUES('E416','chorus','Lower and lower, down at Thy cross,<br/>All the world''s treasure counting but dross;<br/>Down at Thy feet, blessed Savior, we fall,<br/>Lower, still lower, Christ all in all!<br/>',NULL,2130,2130);
INSERT INTO stanza VALUES('E416','2','Lower and lower, dear Savior, we pray,<br/>Losing the self-life still more every day;<br/>Weak and unworthy, we''re looking above;<br/>Empty us wholly; then fill us with love.<br/>',NULL,2131,2131);
INSERT INTO stanza VALUES('E416','3','Lower and lower; yet higher we rise,<br/>Lifted in Christ, freed from all the earth ties;<br/>Humbly we follow the way of the cross,<br/>Then, crowns of glory, and gain for all loss.<br/>',NULL,2132,2132);
INSERT INTO stanza VALUES('E417','1','Deep in me, Lord, mark Thou Thy holy Cross,<br/>On motives, choices, private dear desires.<br/>Let all that self in any form inspires<br/>Be unto me as dross.<br/>',NULL,2133,2133);
INSERT INTO stanza VALUES('E417','2','And when Thy touch of death is here and there<br/>Laid on a thing most precious in mine eyes,<br/>Let me not wonder, let me recognize<br/>The answer to my prayer.<br/>',NULL,2134,2134);
INSERT INTO stanza VALUES('E418','1','From pray''r that asks that I may be<br/>Sheltered from winds that beat on Thee,<br/>From fearing when I should aspire,<br/>From falt''ring when I should climb high''r,<br/>From silken self, O Captain, free<br/>Thy soldier who would follow Thee.<br/>',NULL,2135,2135);
INSERT INTO stanza VALUES('E418','2','From subtle love of softening things,<br/>From easy choices, weakenings,<br/>(Not thus are spirits fortified,<br/>Not this way went the Crucified),<br/>From all that dims Thy Calvary,<br/>O Lamb of God, deliver me.<br/>',NULL,2136,2136);
INSERT INTO stanza VALUES('E418','3','Give me the love that leads the way,<br/>The faith that nothing can dismay,<br/>The hope no disappointments tire,<br/>The passion that will burn like fire,<br/>Let me not sink to be a clod:<br/>Make me Thy fuel, O flame of God.<br/>',NULL,2137,2137);
INSERT INTO stanza VALUES('E419','1','O God, unblessing and unblest,<br/>A withered plant, but not at rest,<br/>A useless cumberer I''m found<br/>Upon Thy field, Thy purchased ground;<br/>And yet I pray-"Do not forsake me,<br/>But in Thy hand, O Savior, take me.<br/>',NULL,2138,2138);
INSERT INTO stanza VALUES('E419','2','As women take unbroken flax,<br/>As molder take unshapen wax,<br/>As smith, the iron, rough and cold,<br/>A useful instrument to mold,<br/>So in Thy skillful hands, O take me,<br/>And never let Thy love forsake me."<br/>',NULL,2139,2139);
INSERT INTO stanza VALUES('E419','3','Like rock uncrushed, the stubborn will,<br/>Though bearing gold is barren still;<br/>Like marble in the quarry rough,<br/>The natural heart is useless stuff;<br/>And so, I pray-"Do not forsake me,<br/>But with Thy hand, O Savior, break me.<br/>',NULL,2140,2140);
INSERT INTO stanza VALUES('E419','4','As mortars crush the hardest rock,<br/>As hammers break the stony block,<br/>As millstones bruise the finest wheat,<br/>As nuts are broken for their meat,<br/>So with Thy mighty hand, O break me,<br/>And never let Thy love forsake me.<br/>',NULL,2141,2141);
INSERT INTO stanza VALUES('E419','5','Though crushed and broken, yet I''m nought<br/>But fragments to the furnace brought;<br/>Though bruised, I have no worth to feed<br/>The multitudes that die in need;<br/>And so, I pray-"Do not forsake me,<br/>But meet for service, Savior, make me.<br/>',NULL,2142,2142);
INSERT INTO stanza VALUES('E419','6','As into useful forms the ore<br/>From molten scraps the molders'' pour;<br/>As fire doth make the bruised wheat,<br/>When mixed and molded, fit to eat;<br/>So, fit for use by fire, O make me,<br/>And never let Thy love forsake me."<br/>',NULL,2143,2143);
INSERT INTO stanza VALUES('E420','1','Jesus, Redeemer and my one Inspirer,<br/>Heat in my coldness, set my life aglow.<br/>Break down my barriers; draw, yea, draw me nigher.<br/>Thee would I know, whom it is life to know.<br/>',NULL,2144,2144);
INSERT INTO stanza VALUES('E420','2','Deepen me, rid me of the superficial;<br/>From pale delusion set my spirit free;<br/>All the entangled in me quick unravel;<br/>Pluck forth each thread of insincerity.<br/>',NULL,2145,2145);
INSERT INTO stanza VALUES('E420','3','The vows are on me, oh to serve Thee truly-<br/>Love perfectly, in purity obey-<br/>Burn, burn, O Fire, O Wind, now winnow throughly;<br/>O Sword, awake against the flesh and slay.<br/>',NULL,2146,2146);
INSERT INTO stanza VALUES('E421','1','Jesus, meek and gentle,<br/>Son of God most High,<br/>Pitying, loving Savior,<br/>Hear Thy children''s cry.<br/>',NULL,2147,2147);
INSERT INTO stanza VALUES('E421','2','Pardon our offences,<br/>Loose our captive chains,<br/>Break down every idol<br/>Which our soul detains.<br/>',NULL,2148,2148);
INSERT INTO stanza VALUES('E421','3','Give us holy freedom,<br/>Fill our heart with grace;<br/>Lead us on our journey,<br/>Till we win the race.<br/>',NULL,2149,2149);
INSERT INTO stanza VALUES('E421','4','Jesus, meek and gentle,<br/>Son of God most high,<br/>Pitying, loving Savior,<br/>Hear Thy children''s cry.<br/>',NULL,2150,2150);
INSERT INTO stanza VALUES('E422','1','Make me a captive, Lord,<br/>And then I shall be free;<br/>Force me to render up my sword,<br/>And I shall conq''ror be.<br/>I sink in life''s alarms<br/>When by myself I stand,<br/>Imprisons me within Thy arms,<br/>And strong shall be my hand.<br/>',NULL,2151,2151);
INSERT INTO stanza VALUES('E422','2','My heart is weak and poor<br/>Until it master find:<br/>It has not spring of action sure,<br/>It varies with the wind;<br/>It cannot freely move<br/>Till Thou hast wrought its chain;<br/>Enslave it with Thy matchless love,<br/>And deathless it shall reign.<br/>',NULL,2152,2152);
INSERT INTO stanza VALUES('E422','3','My power is faint and low<br/>Till I have learned to serve:<br/>It wants the needed fire to glow,<br/>It wants the breeze to nerve;<br/>It cannot drive the world<br/>Until itself be driven;<br/>Its flag can only be unfurled<br/>When Thou shalt breathe from heaven.<br/>',NULL,2153,2153);
INSERT INTO stanza VALUES('E422','4','My will is not my own<br/>Till Thou hast made it Thine;<br/>If it would reach the monarch''s throne<br/>It must its crown resign;<br/>It only stands unbent<br/>Amid the clashing strife,<br/>When on Thy bosom it has leant,<br/>And found in Thee its life.<br/>',NULL,2154,2154);
INSERT INTO stanza VALUES('E423','1','Thou hidden love of God, whose height,<br/>Whose depth unfathomed no man knows,<br/>I see from far Thy beauteous light,<br/>Inly I sigh for Thy repose;<br/>My heart is pained, nor can it be<br/>At rest, till it finds rest in Thee.<br/>',NULL,2155,2155);
INSERT INTO stanza VALUES('E423','2','Thy secret voice invites me still<br/>The sweetness of Thy yoke to prove;<br/>And fain I would: but though my will<br/>Seems fixed, yet wide my passion rove;<br/>Yet hindrances strew all the way;<br/>I aim at Thee, yet from Thee stray.<br/>',NULL,2156,2156);
INSERT INTO stanza VALUES('E423','3','''Tis mercy all, that Thou hast brought<br/>My mind to seek her peace in Thee;<br/>Yet, while I seek but find Thee not,<br/>No peace my wand''ring soul shall see.<br/>Oh, when shall all my wand''rings end,<br/>And all my steps to Thee-ward tend!<br/>',NULL,2157,2157);
INSERT INTO stanza VALUES('E423','4','Is there a thing beneath the sun<br/>That strives with Thee my heart to share?<br/>Ah! Tear it thence, and reign alone,<br/>The Lord of every motion there.<br/>Then shall my heart from earth be free,<br/>When it has found repose in Thee.<br/>',NULL,2158,2158);
INSERT INTO stanza VALUES('E423','5','Oh, hide this self from me, that I<br/>No more, but Christ in me may live;<br/>My vile affections mortify,<br/>Nor let one darling sin survive.<br/>In all things nothing may I see,<br/>Nothing desire or seek but Thee.<br/>',NULL,2159,2159);
INSERT INTO stanza VALUES('E423','6','O Lord, Thy sovereign aid impart,<br/>To save me from low-thoughted care;<br/>Chase this self-will through all my heart,<br/>Through all its latent mazes there.<br/>Make me Thy duteous child, that I<br/>Ceaseless may Abba, Father, cry.<br/>',NULL,2160,2160);
INSERT INTO stanza VALUES('E423','7','Each moment draw from earth away<br/>My heart which lowly waits Thy call;<br/>Speak to my inmost soul and say.<br/>"I am Thy Love, Thy God, Thy All."<br/>To feel Thy power, to hear Thy voice,<br/>To taste Thy love, be all my choice.<br/>',NULL,2161,2161);
INSERT INTO stanza VALUES('E424','1','Lord, I believe a rest remains<br/>To all Thy people known;<br/>A rest where pure enjoyment reigns,<br/>And Thou art loved alone.<br/>',NULL,2162,2162);
INSERT INTO stanza VALUES('E424','2','A rest, where all our soul''s desire<br/>Is fixed on things above;<br/>Where fear and sin and grief expire,<br/>Cast out by perfect love.<br/>',NULL,2163,2163);
INSERT INTO stanza VALUES('E424','3','Oh, that I now the rest might know,<br/>Believe, and enter in;<br/>Now, Savior, now the power bestow,<br/>And let me cease from sin.<br/>',NULL,2164,2164);
INSERT INTO stanza VALUES('E424','4','Remove this hardness from my heart,<br/>This unbelief remove;<br/>To me the rest of faith impart,<br/>The Sabbath of Thy love.<br/>',NULL,2165,2165);
INSERT INTO stanza VALUES('E424','5','I would be Thine, Thou know''st I would,<br/>And have Thee all my own;<br/>Thee, O my all-sufficient Good.<br/>I want, and Thee alone.<br/>',NULL,2166,2166);
INSERT INTO stanza VALUES('E425','1','Prince of peace, control my will;<br/>Bid this struggling heart be still:<br/>Bid my fears and doubtings cease:<br/>Hush my spirit into peace.<br/>',NULL,2167,2167);
INSERT INTO stanza VALUES('E425','2','Thou hast bought me with Thy blood,<br/>Opened wide the gate to God;<br/>Peace I ask, but peace must be,<br/>Lord, in being one with Thee.<br/>',NULL,2168,2168);
INSERT INTO stanza VALUES('E425','3','May Thy will, not mine be done;<br/>May Thy will and mine be one;<br/>Chase these doubtings from my heart,<br/>Now Thy perfect peace impart.<br/>',NULL,2169,2169);
INSERT INTO stanza VALUES('E425','4','Savior, at Thy feet I fall,<br/>Thou, my life, my God, my all;<br/>Let Thy happy servant be<br/>One forevermore with Thee.<br/>',NULL,2170,2170);
INSERT INTO stanza VALUES('E426','1','Remove my covering, Lord,<br/>That I may see Thy light,<br/>And be deceived no more,<br/>But all things see aright.<br/>',NULL,2171,2171);
INSERT INTO stanza VALUES('E426','chorus','Oh, may Thy living light, Lord,<br/>Scatter all my night, Lord,<br/>And everything make bright, Lord,<br/>For this I pray to Thee.<br/>',NULL,2172,2172);
INSERT INTO stanza VALUES('E426','2','I hardly know myself;<br/>Deceived so much by pride,<br/>I often think I''m right<br/>And am self-satisfied.<br/>',NULL,2173,2173);
INSERT INTO stanza VALUES('E426','3','I know Thee even less;<br/>In doctrine, shallowly;<br/>True revelation lack<br/>Of Thy reality.<br/>',NULL,2174,2174);
INSERT INTO stanza VALUES('E426','4','As for Thy life within,<br/>In darkness I mistake-<br/>If spirit or the flesh,<br/>One for the other take.<br/>',NULL,2175,2175);
INSERT INTO stanza VALUES('E426','5','As for Thy way, O Lord,<br/>I often am not clear;<br/>I toward seclusion tend<br/>And from the pathway veer.<br/>',NULL,2176,2176);
INSERT INTO stanza VALUES('E426','6','As for Thy will for me,<br/>I do not know it well;<br/>I substitute my own<br/>And often would rebel.<br/>',NULL,2177,2177);
INSERT INTO stanza VALUES('E426','7','As for the church, I need<br/>Thy revelation more,<br/>The Body-life to know,<br/>Thy wisdom to explore.<br/>',NULL,2178,2178);
INSERT INTO stanza VALUES('E426','8','I long to be unveiled,<br/>In everything made clear,<br/>No more to be deceived<br/>Or to my pride adhere.<br/>',NULL,2179,2179);
INSERT INTO stanza VALUES('E427','1','O Love divine, how sweet Thou art,<br/>When shall I find my willing heart<br/>All taken up by Thee?<br/>My thirsty spirit faints to prove<br/>The greatness of redeeming love,<br/>The love of Christ to me.<br/>',NULL,2180,2180);
INSERT INTO stanza VALUES('E427','2','Stronger His love than death and hell,<br/>Its riches are unsearchable:<br/>The first-born sons of light<br/>Desire in vain its depths to see;<br/>They cannot reach the mystery,<br/>The length, and breadth, and height.<br/>',NULL,2181,2181);
INSERT INTO stanza VALUES('E427','3','God only knows the love of God;<br/>Oh, that it now were shed abroad<br/>In this poor stony heart;<br/>For love I sigh, for love I pine;<br/>This only portion, Lord, be mine,<br/>Be mine this better part.<br/>',NULL,2182,2182);
INSERT INTO stanza VALUES('E427','4','Oh, that I could forever sit<br/>Like Mary, at the Master''s feet;<br/>Be this my happy choice;<br/>My only care, delight, and bliss,<br/>My joy, my rest on earth be this,<br/>To hear the Bridegroom''s voice.<br/>',NULL,2183,2183);
INSERT INTO stanza VALUES('E428','1','O Lord, Thy boundless love to me<br/>No thought can reach, no tongue declare;<br/>Oh, knit my thankful heart to Thee,<br/>And reign without a rival there;<br/>Thine wholly, Thine alone I am;<br/>Lord, with Thy love my heart inflame.<br/>',NULL,2184,2184);
INSERT INTO stanza VALUES('E428','2','Oh, grant that nothing in my soul<br/>May dwell but Thy pure love alone;<br/>Oh, may Thy love possess me whole,<br/>My joy, my treasure, and my crown;<br/>All coldness from my heart remove;<br/>May every act, word, thought, be love.<br/>',NULL,2185,2185);
INSERT INTO stanza VALUES('E428','3','O Love, how cheering is Thy ray,<br/>All pain before Thy presence flies;<br/>Care, anguish, sorrow, melt away,<br/>Where''er Thy healing beams arise;<br/>Lord Jesus, nothing may I see,<br/>And naught desire, or seek, but Thee.<br/>',NULL,2186,2186);
INSERT INTO stanza VALUES('E429','1','My faith looks up to Thee,<br/>Thou Lamb of Calvary,<br/>Savior Divine;<br/>Now hear me while I pray;<br/>Take all my guilt away;<br/>Oh, let me from this day<br/>Be wholly Thine.<br/>',NULL,2187,2187);
INSERT INTO stanza VALUES('E429','2','May Thy rich grace impart<br/>Strength to my fainting heart,<br/>My zeal inspire;<br/>As Thou hast died for me,<br/>Oh, may my love to Thee<br/>Pure, warm, and changeless be,<br/>A living fire.<br/>',NULL,2188,2188);
INSERT INTO stanza VALUES('E429','3','While life''s dark maze I tread,<br/>And griefs around me spread,<br/>Be Thou my Guide;<br/>Bid darkness turn to day,<br/>Wipe sorrow''s tears away,<br/>Nor let me ever stray<br/>From Thee aside.<br/>',NULL,2189,2189);
INSERT INTO stanza VALUES('E429','4','All thru life''s transient dream,<br/>Until death''s sullen stream<br/>Shall o''er me roll,<br/>Blest Savior, with Thy love,<br/>Fear and distrust remove;<br/>Make me Thy grace to prove,<br/>Transform my soul.<br/>',NULL,2190,2190);
INSERT INTO stanza VALUES('E430','1','When I am in the natural man,<br/>How very strong I feel I am,<br/>I do not know, I cannot scan<br/>How weak I am.<br/>',NULL,2191,2191);
INSERT INTO stanza VALUES('E430','2','When in the world I have my life,<br/>I cannot sense my failure rife,<br/>But boasting in my earnest strife,<br/>I forward press.<br/>',NULL,2192,2192);
INSERT INTO stanza VALUES('E430','3','When I within the darkness dwell,<br/>My shallow state I cannot tell,<br/>I only think how I excel,<br/>And proudly dream.<br/>',NULL,2193,2193);
INSERT INTO stanza VALUES('E430','4','But when at last I come to Thee,<br/>Thy searching light uncovers me,<br/>I see what I could never see-<br/>My self exposed.<br/>',NULL,2194,2194);
INSERT INTO stanza VALUES('E430','5','I wither ''neath Thy piercing ray,<br/>And all my strength dissolves away,<br/>My self-esteem in dust I lay,<br/>And lowly bow.<br/>',NULL,2195,2195);
INSERT INTO stanza VALUES('E430','6','How blind and foolish is the pride<br/>With which my soul was fortified;<br/>From my dark heart, self-satisfied,<br/>It issued forth.<br/>',NULL,2196,2196);
INSERT INTO stanza VALUES('E430','7','There''s not a thing that pride can claim,<br/>There''s not a member but is lame,<br/>There''s only deep regret and shame,<br/>How can I pray?<br/>',NULL,2197,2197);
INSERT INTO stanza VALUES('E430','8','Thy blood from judgment saveth me,<br/>Thy life from wrath delivers me,<br/>How filthy yet in poverty<br/>I really am.<br/>',NULL,2198,2198);
INSERT INTO stanza VALUES('E430','9','I want to pray, but faith have not,<br/>I fain would seek Thee as Thou art.<br/>Oh, canst Thou e''er renew my heart,<br/>Have mercy, Lord!<br/>',NULL,2199,2199);
INSERT INTO stanza VALUES('E431','1','Thy mighty love, O God, constraineth me,<br/>As some strong tide it presseth on its way,<br/>Seeking a channel in my self-bound soul,<br/>Yearning to sweep all barriers away.<br/>',NULL,2200,2200);
INSERT INTO stanza VALUES('E431','2','Shall I not yield to that constraining power?<br/>Shall I not say, O tide of love, flow in?<br/>My God, Thy gentleness hath conquered me,<br/>Life cannot be as it hath hither been.<br/>',NULL,2201,2201);
INSERT INTO stanza VALUES('E431','3','Break through my nature, mighty,<br/>heavenly love,<br/>Clear every avenue of thought and brain,<br/>Flood my affections, purify my will,<br/>Let nothing but Thine own pure life remain.<br/>',NULL,2202,2202);
INSERT INTO stanza VALUES('E431','4','Thus wholly mastered and possessed<br/>by God,<br/>Forth from my life, spontaneous and free,<br/>Shall flow a stream of tenderness and grace.<br/>Loving , because God loved, eternally.<br/>',NULL,2203,2203);
INSERT INTO stanza VALUES('E432','1','O Love, that wilt not let me go,<br/>I rest my weary soul in Thee;<br/>I give Thee back the life I owe,<br/>That in Thine ocean depths its flow<br/>May richer, fuller be.<br/>',NULL,2204,2204);
INSERT INTO stanza VALUES('E432','2','O Light, that followest all my way,<br/>I yield my flickering torch to Thee;<br/>My heart restores its borrowed ray,<br/>That in Thy sunshine''s blaze its day<br/>May brighter, fairer be.<br/>',NULL,2205,2205);
INSERT INTO stanza VALUES('E432','3','O Joy, that seekest me through pain,<br/>I cannot close my heart to Thee;<br/>I trace the rainbow through the rain,<br/>And feel the promise is not vain<br/>That morn shall tearless be.<br/>',NULL,2206,2206);
INSERT INTO stanza VALUES('E432','4','O Cross, that liftest up my head,<br/>I dare not ask to fly from Thee;<br/>I lay in dust life''s glory dead,<br/>And from the ground there blossoms red<br/>Life that shall endless be.<br/>',NULL,2207,2207);
INSERT INTO stanza VALUES('E433','1','I am the Lord''s! O joy beyond expression,<br/>O sweet response to voice of love Divine;<br/>Faith''s joyous "Yes" to the assuring whisper,<br/>"Fear not! I have redeemed thee; thou art<br/>Mine."<br/>',NULL,2208,2208);
INSERT INTO stanza VALUES('E433','2','I am the Lord''s! It is the glad confession<br/>Wherewith the Bride recalls the happy day,<br/>When love''s "I will" accepted Him forever,<br/>"The Lord''s," to love, to honor and obey.<br/>',NULL,2209,2209);
INSERT INTO stanza VALUES('E433','3','I am the Lord''s! Yet teach me all it meaneth,<br/>All it involves of love and loyalty,<br/>Of holy service, absolute surrender,<br/>And unreserved obedience unto Thee.<br/>',NULL,2210,2210);
INSERT INTO stanza VALUES('E433','4','I am the Lord''s! Yes; body, soul, and spirit,<br/>O seal them irrecoverably Thine;<br/>As Thou, Beloved, in Thy grace and fulness<br/>Forever and forevermore art mine.<br/>',NULL,2211,2211);
INSERT INTO stanza VALUES('E434','1','Lord, Thou hast won, at length I yield;<br/>My heart by mighty grace compelled<br/>Surrenders all to Thee;<br/>Against Thy terrors long I strove,<br/>But who can stand against Thy love?<br/>Love conquers even me.<br/>',NULL,2212,2212);
INSERT INTO stanza VALUES('E434','2','If Thou hadst bid Thy thunder roll,<br/>And light''nings flash, to blast my soul,<br/>I still had stubborn been;<br/>But mercy has my heart subdued,<br/>A bleeding Savior I have viewed,<br/>And now I hate my sin.<br/>',NULL,2213,2213);
INSERT INTO stanza VALUES('E434','3','Now, Lord, I would be Thine alone,<br/>Come, take possession for Thine own,<br/>For Thou hast set me free;<br/>Released from Satan''s hard command,<br/>See all my powers waiting stand,<br/>To be employed by Thee.<br/>',NULL,2214,2214);
INSERT INTO stanza VALUES('E435','1','Oh, the bitter shame and sorrow,<br/>That a time could ever be,<br/>When I let the Savior''s pity<br/>Plead in vain, and proudly answered,<br/>All of self, and none of Thee,<br/>All of self, and none of Thee.<br/>',NULL,2215,2215);
INSERT INTO stanza VALUES('E435','2','Yet He found me; I beheld Him<br/>Bleeding on the cursed tree;<br/>Heard Him pray, Forgive them, Father,<br/>And my wistful heart said faintly,<br/>Some of self, and some of Thee,<br/>Some of self, and some of Thee,<br/>',NULL,2216,2216);
INSERT INTO stanza VALUES('E435','3','Day by day His tender mercy,<br/>Healing, helping, full and free,<br/>Sweet and strong, and ah! So patient,<br/>Brought me lower while I whispered,<br/>Less of self, and more of Thee,<br/>Less of self, and more of Thee.<br/>',NULL,2217,2217);
INSERT INTO stanza VALUES('E435','4','Higher than the highest heavens,<br/>Deeper than the deepest sea,<br/>Lord, Thy love at last hath conquered;<br/>Grant me now my heart''s petition,<br/>None of self, and all of Thee,<br/>None of self, and all of Thee.<br/>',NULL,2218,2218);
INSERT INTO stanza VALUES('E436','1','Thy Life was giv''n for me,<br/>Thy blood, O Lord, was shed,<br/>That I might ransomed be,<br/>And quickened from the dead;<br/>Thy Life was giv''n for me, for me;<br/>What have I giv''n for Thee?<br/>',NULL,2219,2219);
INSERT INTO stanza VALUES('E436','2','Long years were spent for me<br/>In weariness and woe,<br/>That through eternity<br/>Thy glory I might know;<br/>Long years were spent for me, for me;<br/>Have I spent one for Thee?<br/>',NULL,2220,2220);
INSERT INTO stanza VALUES('E436','3','Thy Father''s home of light,<br/>Thy rainbow-circled throne,<br/>Were left for earthly night,<br/>For wanderings sad and lone;<br/>Yea, all was left for me, for me;<br/>Have I left aught for Thee?<br/>',NULL,2221,2221);
INSERT INTO stanza VALUES('E436','4','Thou, Lord, hast borne for me<br/>More than my tongue can tell<br/>Of bitterest agony,<br/>To rescue me from hell;<br/>Thou suff''redst all for me, for me;<br/>What have I borne for Thee?<br/>',NULL,2222,2222);
INSERT INTO stanza VALUES('E436','5','And Thou hast brought to me<br/>Down from Thy home above<br/>Salvation full and free,<br/>Thy pardon and Thy love;<br/>Great gifts, great gifts Thou broughtest me;<br/>What have I brought to Thee?<br/>',NULL,2223,2223);
INSERT INTO stanza VALUES('E436','6','Oh, let my life be given,<br/>My years for Thee be spent;<br/>World-fetters all be riven,<br/>And joy with suff''ring blent;<br/>Thou gav''st Thyself for me, for me,<br/>I give myself to Thee.<br/>',NULL,2224,2224);
INSERT INTO stanza VALUES('E437','1','Hast thou heard Him, seen Him, known Him?<br/>Is not thine a captured heart?<br/>Chief among ten thousand own Him;<br/>Joyful choose the better part.<br/>',NULL,2225,2225);
INSERT INTO stanza VALUES('E437','chorus','Captivated by His beauty,<br/>Worthy tribute haste to bring;<br/>Let His peerless worth constrain thee,<br/>Crown Him now unrivaled King.<br/>',NULL,2226,2226);
INSERT INTO stanza VALUES('E437','2','Idols once they won thee, charmed thee,<br/>Lovely things of time and sense;<br/>Gilded thus does sin disarm thee,<br/>Honeyed lest thou turn thee thence.<br/>',NULL,2227,2227);
INSERT INTO stanza VALUES('E437','3','What has stripped the seeming beauty<br/>From the idols of the earth?<br/>Not a sense of right or duty,<br/>But the sight of peerless worth.<br/>',NULL,2228,2228);
INSERT INTO stanza VALUES('E437','4','Not the crushing of those idols,<br/>With its bitter void and smart;<br/>But the beaming of His beauty,<br/>The unveiling of His heart.<br/>',NULL,2229,2229);
INSERT INTO stanza VALUES('E437','5','Who extinguishes their taper<br/>Till they hail the rising sun?<br/>Who discards the garb of winter<br/>Till the summer has begun?<br/>',NULL,2230,2230);
INSERT INTO stanza VALUES('E437','6','''Tis that look that melted Peter,<br/>''Tis that face that Stephen saw,<br/>''Tis that heart that wept with Mary,<br/>Can alone from idols draw:<br/>',NULL,2231,2231);
INSERT INTO stanza VALUES('E437','7','Draw and win and fill completely,<br/>Till the cup o''erflow the brim;<br/>What have we to do with idols<br/>Who have companied with Him?<br/>',NULL,2232,2232);
INSERT INTO stanza VALUES('E438','1','I''ve turned my back upon the world<br/>With all its idle pleasures,<br/>And set my heart on better things,<br/>On higher, holier treasures;<br/>No more its glitter and its glare,<br/>And vanity shall bind me;<br/>I''ve crossed the separating line,<br/>And left the world behind me.<br/>',NULL,2233,2233);
INSERT INTO stanza VALUES('E438','chorus','Far, far behind me!<br/>Far, far behind me!<br/>I''ve crossed the separating line,<br/>And left the world behind me.<br/>',NULL,2234,2234);
INSERT INTO stanza VALUES('E438','2','I''ve left the old sad life of sin,<br/>Its follies all forsaken;<br/>My standing place is now in Christ,<br/>His holy vows I''ve taken;<br/>Beneath the standing of the cross<br/>The world henceforth shall find me;<br/>I''ve passed in Christ from death to life,<br/>And left the world behind me.<br/>',NULL,2235,2235);
INSERT INTO stanza VALUES('E438','chorus','Far, far behind me!<br/>Far, far behind me!<br/>I''ve passed in Christ from death to life,<br/>And left the world behind me.<br/>',NULL,2236,2236);
INSERT INTO stanza VALUES('E438','3','My soul shall ne''er return again<br/>Back to its former station,<br/>For here alone is perfect peace,<br/>And rest from condemnation;<br/>I''ve made exchange of masters now,<br/>The vows of glory bind me,<br/>And once for all I''ve left the world,<br/>Yes, left the world behind me.<br/>',NULL,2237,2237);
INSERT INTO stanza VALUES('E438','chorus','Far, far behind me!<br/>Far, far behind me!<br/>And once for all I''ve left the world,<br/>Yes, left the world behind me.<br/>',NULL,2238,2238);
INSERT INTO stanza VALUES('E438','4','My choice is made forevermore,<br/>I want no other Savior;<br/>I ask no purer happiness<br/>Than His sweet love and favor;<br/>My heart is fixed on Jesus Christ,<br/>No more the world shall blind me;<br/>I''ve crossed the Red Sea of His death,<br/>And left the world behind me.<br/>',NULL,2239,2239);
INSERT INTO stanza VALUES('E438','chorus','Far, far behind me!<br/>Far, far behind me!<br/>I''ve crossed the Red Sea of His death,<br/>And left the world behind me.<br/>',NULL,2240,2240);
INSERT INTO stanza VALUES('E439','1','Utterly abandoned<br/>To the Holy Ghost!<br/>Seeking all His fulness<br/>At whatever cost;<br/>Cutting all the shorelines,<br/>Launching in the deep<br/>Of His mighty power,<br/>Strong to save and keep.<br/>',NULL,2241,2241);
INSERT INTO stanza VALUES('E439','chorus','Utterly abandoned<br/>To the Lord of all,<br/>Seeking all His fulness,<br/>Answ''ring His dear call.<br/>',NULL,2242,2242);
INSERT INTO stanza VALUES('E439','2','Utterly abandoned<br/>To the Holy Ghost!<br/>Oh! The sinking, sinking,<br/>Till the self is lost!<br/>Till the vessel''s emptied<br/>Broken at His feet;<br/>Waiting till His filling<br/>Makes the work complete.<br/>',NULL,2243,2243);
INSERT INTO stanza VALUES('E439','3','Utterly abandoned<br/>To the will of God;<br/>Walking in the pathway<br/>That my Master trod;<br/>Leaving ease and pleasure;<br/>Making Him my choice,<br/>Waiting for His guidance,<br/>Listening for His voice.<br/>',NULL,2244,2244);
INSERT INTO stanza VALUES('E439','4','Utterly abandoned!<br/>Through eternity;<br/>My will never choosing,<br/>His it e''er shall be;<br/>All my plans and longings<br/>Lost in His sweet will,<br/>Having nothing, owning<br/>All things in Him still.<br/>',NULL,2245,2245);
INSERT INTO stanza VALUES('E439','5','Utterly abandoned!<br/>''Tis so sweet to be<br/>Captive in His love-bonds,<br/>Yet so wondrous free;<br/>Free from sin''s dominion,<br/>Free from doubt and fear,<br/>Free from every worry,<br/>Burden, grief or care.<br/>',NULL,2246,2246);
INSERT INTO stanza VALUES('E439','6','Utterly abandoned!<br/>Oh, the rest is sweet,<br/>Waiting in His presence<br/>At His blessed feet;<br/>Waiting for the filling<br/>Of the Host divine,<br/>Who my inward parts shall<br/>Perfectly refine.<br/>',NULL,2247,2247);
INSERT INTO stanza VALUES('E439','7','Lo! His Spirit fills me,<br/>With His presence sweet!<br/>I, in Him, am blessed!<br/>I, in Him, complete!<br/>Now, the light within me<br/>Never shall grow dim<br/>While abandoned ever,<br/>Living unto Him!<br/>',NULL,2248,2248);
INSERT INTO stanza VALUES('E440','1','Holy, happy separation!<br/>They alone are truly blest<br/>Who from all besides retiring,<br/>And Himself alone desiring<br/>Find in Jesus only rest,<br/>Find in Jesus only rest.<br/>',NULL,2249,2249);
INSERT INTO stanza VALUES('E440','2','Jesus calls to separation,<br/>And Himself hath led the way;<br/>His own life the explanation,<br/>His own life the illustration<br/>Who is ready to obey?<br/>Who is ready to obey?<br/>',NULL,2250,2250);
INSERT INTO stanza VALUES('E440','3','Blessed Jesus, make us willing,<br/>Thus without the camp to go<br/>Unto Thee in glad subjection,<br/>Unto Thee in Thy rejection,<br/>Unto Thee from all below,<br/>Unto Thee from all below!<br/>',NULL,2251,2251);
INSERT INTO stanza VALUES('E440','4','Separate from all that grieves Thee,<br/>Separate from sinners too;<br/>Yet, like Thee, for sinners caring,<br/>And, like Thee, with sinners bearing,<br/>Asking, "What would Jesus do?"<br/>Asking, "What would Jesus do?"<br/>',NULL,2252,2252);
INSERT INTO stanza VALUES('E440','5','Unto Thee! Beloved Master,<br/>Nearer, nearer let us be;<br/>Unto Thee in consecration,<br/>Unto Thee in separation,<br/>Ever, only, unto Thee,<br/>Ever, only, unto Thee!<br/>',NULL,2253,2253);
INSERT INTO stanza VALUES('E441','1','All to Jesus, I surrender,<br/>All to Him I freely give;<br/>I will ever love and trust Him,<br/>In His presence daily live.<br/>',NULL,2254,2254);
INSERT INTO stanza VALUES('E441','chorus','I surrender all,<br/>I surrender all.<br/>All to Thee, my blessed Savior,<br/>I surrender all.<br/>',NULL,2255,2255);
INSERT INTO stanza VALUES('E441','2','All to Jesus I surrender,<br/>Humbly at His feet I bow,<br/>Worldly pleasures all forsaken;<br/>Take me, Jesus, take me now.<br/>',NULL,2256,2256);
INSERT INTO stanza VALUES('E441','3','All to Jesus I surrender,<br/>Make me, Savior, wholly Thine;<br/>Let me feel Thy Holy Spirit,<br/>Truly know that Thou art mine.<br/>',NULL,2257,2257);
INSERT INTO stanza VALUES('E441','4','All to Jesus I surrender,<br/>Lord, I give myself to Thee;<br/>Fill me with Thy love and power,<br/>Let Thy blessing fall on me.<br/>',NULL,2258,2258);
INSERT INTO stanza VALUES('E441','5','All to Jesus I surrender,<br/>Now I feel the sacred flame.<br/>Oh, the joy of full salvation!<br/>Glory, glory to His name!<br/>',NULL,2259,2259);
INSERT INTO stanza VALUES('E442','1','Fully surrendered-Lord, I would be,<br/>Fully surrendered, dear Lord, to Thee.<br/>All on the altar laid,<br/>Surrender fully made,<br/>Thou hast my ransom paid;<br/>I yield to Thee.<br/>',NULL,2260,2260);
INSERT INTO stanza VALUES('E442','2','Fully surrendered-life, time, and all,<br/>All Thou hast given me held at Thy call.<br/>Speak but the word to me,<br/>Gladly I''ll follow Thee,<br/>Now and eternally<br/>Obey my Lord.<br/>',NULL,2261,2261);
INSERT INTO stanza VALUES('E442','3','Fully surrendered-silver and gold,<br/>His, who hath given me riches untold.<br/>All, all belong to Thee,<br/>For Thou didst purchase me,<br/>Thine evermore to be,<br/>Jesus, my Lord.<br/>',NULL,2262,2262);
INSERT INTO stanza VALUES('E442','4','Fully surrendered-Lord, I am Thine;<br/>Fully surrendered, Savior divine!<br/>Live Thou Thy life in me;<br/>All fullness dwells in Thee;<br/>Not I, but Christ in me,<br/>Christ all in all.<br/>',NULL,2263,2263);
INSERT INTO stanza VALUES('E443','1','In full and glad surrender,<br/>I give myself to Thee,<br/>Thine utterly and only<br/>And evermore to be.<br/>',NULL,2264,2264);
INSERT INTO stanza VALUES('E443','2','O Son of God, who lov''st me,<br/>I will be Thine alone;<br/>And all I have and am, Lord,<br/>Shall henceforth be Thine own!<br/>',NULL,2265,2265);
INSERT INTO stanza VALUES('E443','3','Reign over me, Lord Jesus;<br/>Oh, make my heart Thy throne;<br/>It shall be Thine, dear Savior,<br/>It shall be Thine alone.<br/>',NULL,2266,2266);
INSERT INTO stanza VALUES('E443','4','Oh, come and reign, Lord Jesus,<br/>Rule over everything!<br/>And keep me always loyal,<br/>And true to Thee, my King.<br/>',NULL,2267,2267);
INSERT INTO stanza VALUES('E444','1','All for Jesus! All for Jesus!<br/>All my being''s ransomed pow''rs:<br/>All my thoughts and words and doings,<br/>All my days and all my hours.<br/><br/>All for Jesus! All for Jesus!<br/>All my days and all my hours.<br/>All for Jesus! All for Jesus!<br/>All my days and all my hours.<br/>',NULL,2268,2268);
INSERT INTO stanza VALUES('E444','2','Let my hands perform His bidding;<br/>Let my feet run in His ways;<br/>Let mine eyes see Jesus only;<br/>Let my lips speak forth His praise.<br/><br/>All for Jesus! All for Jesus!<br/>Let my lips speak forth His praise.<br/>All for Jesus! All for Jesus!<br/>Let my lips speak forth His praise.<br/>',NULL,2269,2269);
INSERT INTO stanza VALUES('E444','3','Worldlings prize their gems of beauty,<br/>Cling to gilded toys of dust;<br/>Boast of wealth, and fame, and pleasure;<br/>Only Jesus will I trust.<br/><br/>All for Jesus! All for Jesus!<br/>Only Jesus will I trust.<br/>All for Jesus! All for Jesus!<br/>Only Jesus will I trust.<br/>',NULL,2270,2270);
INSERT INTO stanza VALUES('E444','4','Since mine eyes were fixed on Jesus,<br/>I''ve lost sight of all beside-<br/>So enchained my spirit''s vision,<br/>Looking at the Crucified.<br/><br/>All for Jesus! All for Jesus!<br/>Looking at the Crucified.<br/>All for Jesus! All for Jesus!<br/>Looking the Crucified.<br/>',NULL,2271,2271);
INSERT INTO stanza VALUES('E444','5','Oh, what wonder! How amazing!<br/>Jesus, glorious King of kings,<br/>Deigns to call me His beloved,<br/>Resting now beneath His wings.<br/><br/>All for Jesus! All for Jesus!<br/>Resting now beneath His wings.<br/>All for Jesus! All for Jesus!<br/>Lets me rest beneath His wings.<br/>',NULL,2272,2272);
INSERT INTO stanza VALUES('E445','1','Take my life, and let it be<br/>Consecrated, Lord, to Thee;<br/>Take my moments and my days,<br/>Let them flow in ceaseless praise,<br/>Let them flow in ceaseless praise.<br/>',NULL,2273,2273);
INSERT INTO stanza VALUES('E445','2','Take my hands, and let them move<br/>At the impulse of Thy love;<br/>Take my feet and let them be<br/>Swift and beautiful for Thee,<br/>Swift and beautiful for Thee.<br/>',NULL,2274,2274);
INSERT INTO stanza VALUES('E445','3','Take my voice, and let me sing<br/>Always, only, for my King;<br/>Take my lips, and let them be<br/>Filled with messages from Thee,<br/>Filled with messages from Thee.<br/>',NULL,2275,2275);
INSERT INTO stanza VALUES('E445','4','Take my silver and my gold;<br/>Not a mite would I withhold;<br/>Take my intellect, and use<br/>Every power as Thou shalt choose,<br/>Every power as Thou shalt choose.<br/>',NULL,2276,2276);
INSERT INTO stanza VALUES('E445','5','Take my will, and make it Thine;<br/>It shall be no longer mine.<br/>Take my heart; it is Thine own;<br/>It shall be Thy royal throne,<br/>It shall be Thy royal throne.<br/>',NULL,2277,2277);
INSERT INTO stanza VALUES('E445','6','Take my love; my Lord, I pour<br/>At Thy feet its treasure-store.<br/>Take myself, and I will be<br/>Ever, only, all for Thee,<br/>Ever, only, all for Thee.<br/>',NULL,2278,2278);
INSERT INTO stanza VALUES('E446','1','What shall I give Thee, Master?<br/>Thou who didst die for me.<br/>Shall I give less of what I possess,<br/>Or shall I give all to Thee?<br/>',NULL,2279,2279);
INSERT INTO stanza VALUES('E446','chorus','Jesus, my Lord and Savior;<br/>Thou hast giv''n all for me;<br/>Thou didst leave Thy home above<br/>To die on Calvary.<br/>What shall I give Thee, Master?<br/>Thou hast giv''n all for me;<br/>Not just a part or half of my heart,<br/>I will give all to Thee.<br/>',NULL,2280,2280);
INSERT INTO stanza VALUES('E446','2','What shall I give Thee, Master?<br/>Thou hast redeemed my soul;<br/>My gift is small but it is my all-<br/>Surrendered to Thy control.<br/>',NULL,2281,2281);
INSERT INTO stanza VALUES('E446','3','What shall I give Thee, Master?<br/>Giver of gifts divine!<br/>I will not hold time, talents or gold-<br/>For everything shall be Thine.<br/>',NULL,2282,2282);
INSERT INTO stanza VALUES('E447','1','My spirit, soul, and body,<br/>Dear Lord, I give to Thee,<br/>A consecrated offering,<br/>Thine evermore to be.<br/>',NULL,2283,2283);
INSERT INTO stanza VALUES('E447','chorus','My all is on the altar;<br/>Lord, I am all Thine own;<br/>Oh, may my faith ne''er falter!<br/>Lord, keep me Thine alone.<br/>',NULL,2284,2284);
INSERT INTO stanza VALUES('E447','2','Lord Jesus, mighty Savior,<br/>I trust in Thy great name;<br/>I look for Thy salvation,<br/>Thy promise now I claim.<br/>',NULL,2285,2285);
INSERT INTO stanza VALUES('E447','3','Now, Lord, I yield my members,<br/>From sin''s dominion free,<br/>For warfare and for triumph,<br/>As weapons unto Thee.<br/>',NULL,2286,2286);
INSERT INTO stanza VALUES('E447','4','Oh, blissful self-surrender,<br/>To live, my Lord, by Thee;<br/>Now, Son of God, my Savior,<br/>Live out Thy life in me.<br/>',NULL,2287,2287);
INSERT INTO stanza VALUES('E447','5','I''m Thine, O dear Lord Jesus,<br/>Washed in Thy precious blood,<br/>Sealed by Thy Holy Spirit,<br/>A sacrifice to God.<br/>',NULL,2288,2288);
INSERT INTO stanza VALUES('E447','chorus','My all is on the altar;<br/>I''m waiting for the fire;<br/>I''m waiting, waiting, waiting;<br/>I''m waiting for the fire.<br/>',NULL,2289,2289);
INSERT INTO stanza VALUES('E448','1','You have longed for sweet peace, and for faith to increase,<br/>And have earnestly, fervently prayed;<br/>But you cannot have rest, or be perfectly blest,<br/>Until all on the altar is laid.<br/>',NULL,2290,2290);
INSERT INTO stanza VALUES('E448','chorus','Is your all on the altar of sacrifice laid?<br/>Your heart, does the Spirit control?<br/>You can only be blest and have peace<br/>and sweet rest,<br/>As you yield Him your body and soul.<br/>',NULL,2291,2291);
INSERT INTO stanza VALUES('E448','2','Would you walk with the Lord in the light of His Word,<br/>And have peace and contentment alway;<br/>You must do His sweet will to be free from all ill;<br/>On the altar your all you must lay.<br/>',NULL,2292,2292);
INSERT INTO stanza VALUES('E448','3','Oh, we never can know what the Lord will bestow<br/>Of the blessings for which we have prayed,<br/>Till our body and soul He doth fully<br/>control,<br/>And our all on the altar is laid.<br/>',NULL,2293,2293);
INSERT INTO stanza VALUES('E448','4','Who can tell all the love He will send from above!<br/>Oh, how happy our heart will be made!<br/>Oh, what fellowship sweet we shall share at His feet,<br/>When our all on the altar is laid!<br/>',NULL,2294,2294);
INSERT INTO stanza VALUES('E449','1','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Thou art the Potter,<br/>I am the clay.<br/>Mould me and make me<br/>After Thy will,<br/>While I am waiting,<br/>Yielded and still.<br/>',NULL,2295,2295);
INSERT INTO stanza VALUES('E449','2','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Search me and try me,<br/>Master, today.<br/>Whiter than snow, Lord,<br/>Wash me just now,<br/>As in Thy presence<br/>Humbly I bow.<br/>',NULL,2296,2296);
INSERT INTO stanza VALUES('E449','3','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Wounded and weary,<br/>Help me, I pray.<br/>Power, all power,<br/>Surely is Thine,<br/>Touch me and heal me,<br/>Savior divine.<br/>',NULL,2297,2297);
INSERT INTO stanza VALUES('E449','4','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Hold o''er my being<br/>Absolute sway.<br/>Fill with Thy Spirit<br/>Till all shall see<br/>Christ only, always,<br/>Living in me.<br/>',NULL,2298,2298);
INSERT INTO stanza VALUES('E450','1','Lie still, and let Him mould thee!<br/>Oh, Lord, I would obey;<br/>Be Thou the skillful, Potter,<br/>And I the yielding clay.<br/>',NULL,2299,2299);
INSERT INTO stanza VALUES('E450','chorus','Bend me, oh, bend me to Thy will,<br/>While in Thy hand I''m lying still.<br/>',NULL,2300,2300);
INSERT INTO stanza VALUES('E450','2','In Thy dear hand I''m resting,<br/>Oh, hold me quiet there;<br/>Then soften me and mould me,<br/>And for Thy will prepare.<br/>',NULL,2301,2301);
INSERT INTO stanza VALUES('E450','3','I need not fear to trust Thee,<br/>Thy love and skill are such,<br/>New lessons Thou wilt teach me,<br/>While yielding to Thy touch.<br/>',NULL,2302,2302);
INSERT INTO stanza VALUES('E450','4','Impress Thine image on me,<br/>Fulfill Thy blest design,<br/>Till others see upon me<br/>That beauteous face of Thine.<br/>',NULL,2303,2303);
INSERT INTO stanza VALUES('E451','1','Not by wrestling, but by clinging<br/>Shall we be most blest;<br/>Wrestling only brings us sorrow;<br/>Clinging brings us rest.<br/>',NULL,2304,2304);
INSERT INTO stanza VALUES('E451','2','When we stay our feeble efforts,<br/>And from struggling cease,<br/>Unconditional surrender<br/>Bring us God''s own peace.<br/>',NULL,2305,2305);
INSERT INTO stanza VALUES('E451','3','Lean we all our weight on Jesus,<br/>Who alone can save;<br/>He by might of love hath triumphed<br/>O''er His willing slave.<br/>',NULL,2306,2306);
INSERT INTO stanza VALUES('E451','4','Yielding, we shall know true conquest;<br/>Dying, we shall live;<br/>"Not my will, but Thine'' prevaileth,<br/>Victory to give.<br/>',NULL,2307,2307);
INSERT INTO stanza VALUES('E452','1','Tell me not of earthly pleasures,<br/>Tempt me not with sordid gain;<br/>Mock me not with earth''s illusions,<br/>Vex me not with honors vain.<br/>I am weaned from sinful idols;<br/>I am henceforth not my own;<br/>I have given my heart to Jesus,<br/>I belong to Him alone.<br/>',NULL,2308,2308);
INSERT INTO stanza VALUES('E452','chorus','I am not my own,<br/>I am not my own.<br/>I belong to Jesus,<br/>And I am not my own.<br/>',NULL,2309,2309);
INSERT INTO stanza VALUES('E452','2','Oh, the blessed rest it brings us<br/>To belong to Christ alone;<br/>We can draw on all His fulness<br/>When we''ve nothing of our own.<br/>Blessed Jesus, take me, own me,<br/>Make me, keep me wholly Thine.<br/>Deign to find in me Thy portion,<br/>While I joy to call Thee mine.<br/>',NULL,2310,2310);
INSERT INTO stanza VALUES('E452','3','Weary soul, give up the struggle,<br/>Cease at length thyself to own;<br/>Give yourself away to Jesus,<br/>And belong to Him alone.<br/>Once He gave His all to win thee,<br/>Now He asks as much of thee;<br/>All He has He fully give thee;<br/>Let thy love His portion be.<br/>',NULL,2311,2311);
INSERT INTO stanza VALUES('E453','1','Under an eastern sky,<br/>Amid a rabble''s cry,<br/>A Man went forth to die,<br/>For me! For me!<br/>',NULL,2312,2312);
INSERT INTO stanza VALUES('E453','2','Thorn-crowned His blessed head,<br/>Blood-stained His every tread;<br/>Cross-laden He was led,<br/>For me! For me!<br/>',NULL,2313,2313);
INSERT INTO stanza VALUES('E453','3','Pierced His hands and feet,<br/>Three hours o''er Him beat<br/>Fierce rays of noon-tide heat,<br/>For me! For me!<br/>',NULL,2314,2314);
INSERT INTO stanza VALUES('E453','4','Thus wert Thou made all mine;<br/>Lord, make me wholly Thine;<br/>Grant grace and strength divine<br/>To me! To me!<br/>',NULL,2315,2315);
INSERT INTO stanza VALUES('E453','5','In thought and word and deed,<br/>Thy will to do, O lead<br/>My soul, e''en though I bleed,<br/>To Thee, to Thee.<br/>',NULL,2316,2316);
INSERT INTO stanza VALUES('E454','1','I lift my heart to Thee,<br/>Savior Divine,<br/>For Thou art all to me,<br/>And I am Thine;<br/>Is there on earth a closer bond than this,<br/>That my Beloved''s mine, and I am His?<br/>',NULL,2317,2317);
INSERT INTO stanza VALUES('E454','2','Thine am I by all ties,<br/>And chiefly Thine,<br/>For through Thy sacrifice<br/>Thou, Lord, art mine;<br/>By Thine own cords of love, so sweetly wound<br/>Around me, closely I to Thee am bound.<br/>',NULL,2318,2318);
INSERT INTO stanza VALUES('E454','3','To Thee, Thou Bleeding Lamb,<br/>I all things owe,<br/>All that I have and am,<br/>And all I know;<br/>All that I have is now no longer mine,<br/>And I am not my own: Lord, I am Thine.<br/>',NULL,2319,2319);
INSERT INTO stanza VALUES('E454','4','How can I, Lord, withhold<br/>Life''s brightest hour<br/>From Thee; or gathered gold,<br/>Or any power?<br/>Why should I keep one precious thing from Thee,<br/>When Thou hast given Thine own dear Self to me?<br/>',NULL,2320,2320);
INSERT INTO stanza VALUES('E454','5','I pray Thee, Savior, keep<br/>Me in Thy love,<br/>Until the world Thou sweep<br/>And me remove<br/>To that fair realm, where, sin and sorrow o''er,<br/>Thou and Thine own are one for evermore.<br/>',NULL,2321,2321);
INSERT INTO stanza VALUES('E455','1','Every thread I wind this day,<br/>Every footstep on life''s way,<br/>Every clod I shall unearth,<br/>Every task, whate''er its worth:<br/>Only for God''s glory living,<br/>Blessing, praise and honor giving!<br/>',NULL,2322,2322);
INSERT INTO stanza VALUES('E455','2','All the burdens of the day,<br/>All the words which I shall say,<br/>All the works my God may send,<br/>All the hours in rest I spend:<br/>Ever for His glory living,<br/>Blessing, praise and honor giving!<br/>',NULL,2323,2323);
INSERT INTO stanza VALUES('E455','3','Every blood-drop in the heart,<br/>Every grief and aching smart,<br/>Every bitter pulse of pain,<br/>Every hour of joy again:<br/>Only for God''s glory living,<br/>Blessing, praise and honor giving!<br/>',NULL,2324,2324);
INSERT INTO stanza VALUES('E455','5','All, from deeds of little worth,<br/>To the greatest things on earth;<br/>Mine to build some world to be,<br/>Or to lie and gaze on Thee:<br/>For Thy glory daily living,<br/>Blessing, praise and honor giving!<br/>',NULL,2325,2325);
INSERT INTO stanza VALUES('E456','1','Living for Jesus a life that is true,<br/>Striving to please Him in all that I do;<br/>Yielding allegiance, glad-hearted and free,<br/>This is the pathway of blessing for me.<br/>',NULL,2326,2326);
INSERT INTO stanza VALUES('E456','chorus','O Jesus, Lord and Savior,<br/>I give myself to Thee,<br/>For Thou, in Thy redemption,<br/>Didst give Thyself for me;<br/>I own no other Master,<br/>My heart shall be Thy throne,<br/>My life I give, henceforth to live,<br/>O Christ, for Thee alone.<br/>',NULL,2327,2327);
INSERT INTO stanza VALUES('E456','2','Living for Jesus who died in my place,<br/>Bearing on Calv''ry my sin and disgrace;<br/>Such love constrains me to answer His call,<br/>Follow His leading and give Him my all.<br/>',NULL,2328,2328);
INSERT INTO stanza VALUES('E456','3','Living for Jesus wherever I am,<br/>Doing each duty in His holy name;<br/>Willing to suffer affliction and loss,<br/>Deeming each trial a part of my cross.<br/>',NULL,2329,2329);
INSERT INTO stanza VALUES('E456','4','Living for Jesus through earth''s little while,<br/>My dearest treasure, the light of His smile;<br/>Seeking the lost ones He died to redeem,<br/>Bringing the weary to find rest in Him.<br/>',NULL,2330,2330);
INSERT INTO stanza VALUES('E457','1','My life, my love, I give to Thee,<br/>Thou Lamb of God who died for me;<br/>Oh, may I ever faithful be,<br/>My Savior and my God!<br/>',NULL,2331,2331);
INSERT INTO stanza VALUES('E457','chorus','I''ll live for Him who died for me,<br/>How happy then my life shall be!<br/>I''ll live for Him who died for me,<br/>My Savior and my God!<br/>',NULL,2332,2332);
INSERT INTO stanza VALUES('E457','2','The world and all its joys I leave;<br/>My life, O Lord, Thou wilt receive;<br/>Henceforth no more Thyself I''ll grieve,<br/>My Savior and my God!<br/>',NULL,2333,2333);
INSERT INTO stanza VALUES('E457','3','O Thou who died on Calvary,<br/>To save my soul and make me free,<br/>That I may ever live to Thee<br/>My Savior and my God!<br/>',NULL,2334,2334);
INSERT INTO stanza VALUES('E458','1','Living for Jesus, oh, what peace!<br/>Rivers of pleasure never cease;<br/>Trials may come, yet I''ll not fear,<br/>Living for Jesus, He is near.<br/>',NULL,2335,2335);
INSERT INTO stanza VALUES('E458','chorus','Help me to serve Thee more and more,<br/>Help me to praise Thee o''er and o''er;<br/>Live in Thy presence day by day,<br/>Never to turn from Thee away.<br/>',NULL,2336,2336);
INSERT INTO stanza VALUES('E458','2','Living for Jesus, oh, what rest!<br/>Pleasing my Savior, I am blest;<br/>Only to live for Him alone,<br/>Doing His will till life is done.<br/>',NULL,2337,2337);
INSERT INTO stanza VALUES('E458','3','Living for Jesus, everywhere,<br/>All of my burdens He doth bear;<br/>Friends may forsake me, He''ll be true;<br/>Trusting in Him, He''ll guide me through.<br/>',NULL,2338,2338);
INSERT INTO stanza VALUES('E458','4','Living for Jesus, till at last<br/>Into His glory I have passed;<br/>There to behold Him on His throne,<br/>Hear from His lips, "My child, well done!"<br/>',NULL,2339,2339);
INSERT INTO stanza VALUES('E459','1','Not to ourselves again,<br/>Not to flesh we live;<br/>Not to world henceforth shall we<br/>Our strength, our being give.<br/>',NULL,2340,2340);
INSERT INTO stanza VALUES('E459','2','The time past of our lives<br/>Sufficeth to have wrought<br/>The fleshly will, which only ill<br/>Hath to us ever brought.<br/>',NULL,2341,2341);
INSERT INTO stanza VALUES('E459','3','No longer is our life<br/>A thing unused or vain;<br/>To us e''en here to live is Christ,<br/>To us to die is gain.<br/>',NULL,2342,2342);
INSERT INTO stanza VALUES('E459','4','Our life is hid with Christ,<br/>With Christ in God above,<br/>Upward our heart would go to Him,<br/>Whom, seeing not, we love.<br/>',NULL,2343,2343);
INSERT INTO stanza VALUES('E459','5','He liveth, and we live!<br/>His life for us prevails;<br/>His fulness fills our mighty void,<br/>His strength for us avails.<br/>',NULL,2344,2344);
INSERT INTO stanza VALUES('E460','1','Jesus, I my cross taken,<br/>All to leave and follow Thee;<br/>Destitute, despised, forsaken,<br/>Thou, from hence, my all shalt be.<br/>Perish every fond ambition,<br/>All I''ve sought, and hoped, and known;<br/>Yet how rich is my condition,<br/>God and Christ are still my own!<br/>',NULL,2345,2345);
INSERT INTO stanza VALUES('E460','2','Let the world despise and leave me,<br/>They have left my Savior, too;<br/>Human hearts and looks deceive me;<br/>Thou art not, like man, untrue;<br/>And, while Thou shalt smile upon me,<br/>God of wisdom, love, and might,<br/>Foes may hate, and friends disown me;<br/>Show Thy face, and all is bright.<br/>',NULL,2346,2346);
INSERT INTO stanza VALUES('E460','3','Man may trouble and distress me,<br/>''Twill but drive me to Thy breast;<br/>Life with trials hard may press me,<br/>Christ will bring me sweeter rest.<br/>O ''tis not in grief to harm me,<br/>While Thy love is left to me;<br/>O ''twere not in joy to charm me,<br/>Were that joy unmixed with Thee.<br/>',NULL,2347,2347);
INSERT INTO stanza VALUES('E460','4','Haste thee on from grace to glory,<br/>Armed by faith and winged by prayer;<br/>God''s eternal day''s before thee,<br/>God''s own hand shall guide thee there.<br/>Soon shall close thy earthly mission,<br/>Swift shall pass thy pilgrim days,<br/>Hope shall change to glad fruition,<br/>Faith to sight, and prayer to praise.<br/>',NULL,2348,2348);
INSERT INTO stanza VALUES('E461','1','Down in the valley with my Savior I would go,<br/>Where the flowers are blooming and the<br/>sweet waters flow;<br/>Everywhere He leads me I would follow,<br/>follow on,<br/>Walking in His footsteps till the crown be<br/>won.<br/>',NULL,2349,2349);
INSERT INTO stanza VALUES('E461','chorus','Follow! Follow! I would follow Jesus!<br/>Anywhere, everywhere, I would follow on!<br/>Follow! Follow! I would follow Jesus!<br/>Everywhere He leads me I would follow on!<br/>',NULL,2350,2350);
INSERT INTO stanza VALUES('E461','2','Down in the valley with my Savior I would go,<br/>Where the storms are sweeping and the<br/>dark waters flow;<br/>With His hand to lead me I will never,<br/>never fear,<br/>Dangers cannot fright me if my Lord is near.<br/>',NULL,2351,2351);
INSERT INTO stanza VALUES('E461','3','Down in the valley, or upon the mountain steep,<br/>Close beside my Savior would my heart ever keep;<br/>He will lead me safely in the path that He has trod,<br/>Up to where they gather in the rest of God.<br/>',NULL,2352,2352);
INSERT INTO stanza VALUES('E462','1','How shall I follow Him I serve?<br/>How shall I copy Him I love?<br/>Nor from those blessed footsteps swerve,<br/>Which lead me to His seat above?<br/>',NULL,2353,2353);
INSERT INTO stanza VALUES('E462','2','Privations, sorrows, bitter scorn,<br/>The life of toil, the mean abode,<br/>The faithless kiss, the crown of thorn-<br/>Are these the consecrated road?<br/>',NULL,2354,2354);
INSERT INTO stanza VALUES('E462','3','Lord, should my path through suff''ring lie,<br/>Forbid it I should e''er repine;<br/>Still let me turn to Calvary,<br/>Nor heed my griefs, rememb''ring Thine.<br/>',NULL,2355,2355);
INSERT INTO stanza VALUES('E462','4','O let me think how Thou didst leave<br/>Untasted every pure delight,<br/>To fast, to faint, to watch, to grieve,<br/>The toilsome day, the homeless night:<br/>',NULL,2356,2356);
INSERT INTO stanza VALUES('E462','5','To faint, to grieve, to die for me!<br/>Thou camest, not Thyself to please;<br/>And, dear as earthly comforts be,<br/>Shall I not love Thee more than these?<br/>',NULL,2357,2357);
INSERT INTO stanza VALUES('E463','1','I love, I love my Master,<br/>I will not go out free,<br/>For He is my Redeemer;<br/>He paid the price for me.<br/>I would not leave His service,<br/>It is so sweet and blest;<br/>And in the weariest moments<br/>He gives the truest rest.<br/>',NULL,2358,2358);
INSERT INTO stanza VALUES('E463','2','My Master shed His life-blood<br/>My vassal life to win,<br/>And save me from the bondage<br/>Of tyrant self and sin.<br/>He chose me for His service,<br/>And gave me power to choose<br/>That blessed, perfect freedom,<br/>Which I shall never lose.<br/>',NULL,2359,2359);
INSERT INTO stanza VALUES('E463','3','I would not halve my service,<br/>His only it must be!<br/>His only, who so loved me,<br/>And gave Himself for me.<br/>Rejoicing and adoring,<br/>Henceforth my song shall be,<br/>I love, I love my Master,<br/>I will not go out free.<br/>',NULL,2360,2360);
INSERT INTO stanza VALUES('E464','1','My glorious Victor, Prince Divine,<br/>Clasp these surrendered hands in Thine;<br/>At length my will is all Thine own,<br/>Glad vassal of my Savior''s throne.<br/>',NULL,2361,2361);
INSERT INTO stanza VALUES('E464','2','My Master, lead me to Thy door;<br/>Pierce this now willing ear once more;<br/>Thy bonds are freedom; let me stay<br/>With Thee, to toil, endure, obey.<br/>',NULL,2362,2362);
INSERT INTO stanza VALUES('E464','3','Yes, ear and hand, and thought and will,<br/>Use all in Thy dear slav''ry still!<br/>Self''s weary liberties I cast<br/>Beneath Thy feet; there keep them fast.<br/>',NULL,2363,2363);
INSERT INTO stanza VALUES('E464','4','Tread them still down; and then I know,<br/>These hands shall with Thy gifts o''erflow;<br/>And pierced ears shall hear the tone<br/>Which tells me Thou and I are one.<br/>',NULL,2364,2364);
INSERT INTO stanza VALUES('E465','1','O Jesus, I have promised<br/>To serve Thee to the end;<br/>Be Thou forever near me,<br/>My Master and my Friend;<br/>I shall not fear the battle<br/>If Thou art by my side,<br/>Nor wander from the pathway<br/>If Thou wilt be my Guide.<br/>',NULL,2365,2365);
INSERT INTO stanza VALUES('E465','2','Oh, let me feel Thee near me;<br/>The world is ever near;<br/>I see the sights that dazzle,<br/>The tempting sounds I hear;<br/>My foes are ever near me,<br/>Around me and within;<br/>But, Jesus, draw Thou nearer,<br/>And shield my soul from sin.<br/>',NULL,2366,2366);
INSERT INTO stanza VALUES('E465','3','Oh, let me hear Thee speaking,<br/>In accents clear and still,<br/>Above the storms of passion,<br/>The murmurs of self-will;<br/>Oh, speak to reassure me,<br/>To hasten, or control;<br/>Oh, speak, and make me listen,<br/>Thou Guardian of my soul.<br/>',NULL,2367,2367);
INSERT INTO stanza VALUES('E465','4','O Jesus, Thou hast promised<br/>To all who follow Thee<br/>That where Thou art in glory<br/>There shall Thy servant be;<br/>And, Jesus, I have promised<br/>To serve Thee to the end;<br/>Oh, give me grace to follow,<br/>My Master and my Friend.<br/>',NULL,2368,2368);
INSERT INTO stanza VALUES('E465','5','Oh, let me see Thy footmarks,<br/>And in them plant mine own;<br/>My hope to follow duly<br/>Is in Thy strength alone.<br/>Oh, guide me, call me, draw me,<br/>Uphold me to the end;<br/>And then to rest receive me,<br/>My Savior and my Friend.<br/>',NULL,2369,2369);
INSERT INTO stanza VALUES('E466','1','He has entered! He has entered!<br/>Every guest may now depart;<br/>He has taken all the chamber<br/>Of my once divided heart.<br/>',NULL,2370,2370);
INSERT INTO stanza VALUES('E466','2','He has entered! He has entered!<br/>Vanish every doubt and sin;<br/>He has taken full possession,<br/>He is Lord of all within.<br/>',NULL,2371,2371);
INSERT INTO stanza VALUES('E466','3','Long at my poor heart He tarried,<br/>Knocking with His wounded hand;<br/>Wide at last to Him I opened,<br/>Yielding all to His command.<br/>',NULL,2372,2372);
INSERT INTO stanza VALUES('E466','4','He has entered! He has entered!<br/>Every sorrow now must flee;<br/>Where He reigns as King and Master,<br/>There no grief can ever be.<br/>',NULL,2373,2373);
INSERT INTO stanza VALUES('E467','1','This day the Lord has spoken,<br/>This day my choice is made:<br/>I will be all for Jesus,<br/>Who all for me has paid.<br/>',NULL,2374,2374);
INSERT INTO stanza VALUES('E467','2','Now His shall be the empire,<br/>In all things over me;<br/>And I will be His bond slave,<br/>Yet gloriously free.<br/>',NULL,2375,2375);
INSERT INTO stanza VALUES('E467','3','From henceforth, owning nothing,<br/>I cannot lose at all;<br/>I cannot well be poorer,<br/>Whatever may befall.<br/>',NULL,2376,2376);
INSERT INTO stanza VALUES('E467','4','Yet could I not be richer,<br/>If I the world should gain;<br/>For heav''n and earth shall perish,<br/>But Jesus will remain.<br/>',NULL,2377,2377);
INSERT INTO stanza VALUES('E467','5','And He will be my treasure,<br/>And He my boundless store;<br/>And those who live on Jesus,<br/>Will never hunger more.<br/>',NULL,2378,2378);
INSERT INTO stanza VALUES('E467','6','Though I am utter weakness,<br/>In Him I shall prevail;<br/>And though my love may falter,<br/>Yet His will never fail.<br/>',NULL,2379,2379);
INSERT INTO stanza VALUES('E468','1','Am I a soldier of the Cross-<br/>A follower of the Lamb?<br/>And shall I fear to own His cause,<br/>Or blush to speak His name?<br/>',NULL,2380,2380);
INSERT INTO stanza VALUES('E468','chorus','In the name, the precious name,<br/>Of Him who died for me,<br/>Through grace I''ll win the promised crown,<br/>Whate''er my cross may be.<br/>',NULL,2381,2381);
INSERT INTO stanza VALUES('E468','2','Must I be carried to the skies<br/>On flowery beds of ease,<br/>While others fought to win the prize<br/>And sailed through bloody seas?<br/>',NULL,2382,2382);
INSERT INTO stanza VALUES('E468','3','Are there no foes for me to face?<br/>Must I not stem the flood?<br/>Is this vile world a friend to grace,<br/>To help me on to God?<br/>',NULL,2383,2383);
INSERT INTO stanza VALUES('E468','4','Since I must fight if I would reign,<br/>Increase my courage, Lord!<br/>I''ll bear the toil, endure the pain,<br/>Supported by Thy Word.<br/>',NULL,2384,2384);
INSERT INTO stanza VALUES('E469','1','Who is on the Lord''s side?<br/>Who will serve the King?<br/>Who will be His helpers,<br/>Other lives to bring?<br/>Who will leave the world''s side?<br/>Who will face the foe?<br/>Who is on Lord''s side?<br/>Who for Him will go?<br/>',NULL,2385,2385);
INSERT INTO stanza VALUES('E469','chorus','By Thy grand redemption,<br/>By Thy grace divine,<br/>We are on the Lord''s side;<br/>Savior, we are Thine.<br/>',NULL,2386,2386);
INSERT INTO stanza VALUES('E469','2','Not for weight of glory,<br/>Not for crown and palm,<br/>Enter we the army,<br/>Raise the warrior psalm;<br/>But for love that claimeth<br/>Lives for whom He died;<br/>He whom Jesus nameth<br/>Must be on His side.<br/>',NULL,2387,2387);
INSERT INTO stanza VALUES('E469','3','Jesus, Thou hast brought us,<br/>Not with gold or gem,<br/>But with Thine own life-blood,<br/>For Thy diadem;<br/>With Thy blessing filling<br/>Each who comes to Thee,<br/>Thou hast made us willing,<br/>Thou hast made us free.<br/>',NULL,2388,2388);
INSERT INTO stanza VALUES('E469','4','Fierce may be the conflict,<br/>Strong may be the foe,<br/>But the King''s own army<br/>None can overthrow.<br/>Round His standard ranging<br/>Victory is secure,<br/>For His truth unchanging<br/>Makes the triumph sure.<br/>',NULL,2389,2389);
INSERT INTO stanza VALUES('E469','5','Chosen to be soldiers<br/>In an alien land:<br/>Chosen, called, and faithful,<br/>For our Captain''s band;<br/>In the service royal<br/>Let us not grow cold;<br/>Let us be right loyal,<br/>Noble, true, and bold.<br/>',NULL,2390,2390);
INSERT INTO stanza VALUES('E470','1','Father, Son and Holy Ghost,<br/>One in Three, and Three in One,<br/>As by the celestial host,<br/>Let Thy will on earth be done;<br/>Praise by all to Thee be giv''n,<br/>Glorious Lord of earth and heav''n!<br/>',NULL,2391,2391);
INSERT INTO stanza VALUES('E470','2','Vilest of the sinful race,<br/>Lo, I answer to Thy call:<br/>Meanest vessel of Thy grace,<br/>Grace divinely free for all;<br/>Lo, I come to do Thy will,<br/>All Thy counsel to fulfill.<br/>',NULL,2392,2392);
INSERT INTO stanza VALUES('E470','3','If so poor a worm as I,<br/>May to Thy great glory live,<br/>All my actions sanctify,<br/>All my words and thoughts receive;<br/>Claim me for Thy service, claim<br/>All I have, and all I am.<br/>',NULL,2393,2393);
INSERT INTO stanza VALUES('E470','4','Take my soul and body''s powers,<br/>Take my mem''ry, mind, and will;<br/>All my goods and all my hours,<br/>All I know, and all I feel;<br/>All I think, or speak, or do;<br/>Take my heart, but make it new.<br/>',NULL,2394,2394);
INSERT INTO stanza VALUES('E470','5','Now, O God, Thine own I am,<br/>Now I give Thee back Thine own:<br/>Freedom, friends, and health, and fame,<br/>Consecrate to Thee alone;<br/>Thine I live, thrice happy I;<br/>Happier still when Thine I die.<br/>',NULL,2395,2395);
INSERT INTO stanza VALUES('E471','1','How can I ever stay away<br/>And grieve Thy Spirit all the day<br/>While Thou dost wait for me?<br/>I now am willing to return,<br/>And wait no longer, for I yearn<br/>Henceforth to follow Thee.<br/>',NULL,2396,2396);
INSERT INTO stanza VALUES('E471','2','I offer now without reserve<br/>All that I am and all I have<br/>Thy purpose to fulfill.<br/>Oh, may the Lord accept and keep,<br/>That henceforth I may only seek<br/>To do the Father''s will.<br/>',NULL,2397,2397);
INSERT INTO stanza VALUES('E471','3','When I look back, what grief and shame<br/>That I''ve brought none to trust Thy name,<br/>Thy word I''ve locked within.<br/>Oh, may the Lord anointing give<br/>And richly through my being live,<br/>That I may speak of Him.<br/>',NULL,2398,2398);
INSERT INTO stanza VALUES('E471','4','My gracious Lord has giv''n much grace,<br/>Exceeding e''en a friend my place;<br/>I fain would be His bride.<br/>I''d share His life and suffer loss,<br/>Accepting willingly the cross,<br/>With Him identified.<br/>',NULL,2399,2399);
INSERT INTO stanza VALUES('E472','1','Many crowd the Savior''s kingdom,<br/>Few receive His cross;<br/>Many seek His consolation,<br/>Few will suffer loss.<br/>For the dear sake of the Master,<br/>Counting all but dross,<br/>For the dear sake of the Master,<br/>Counting all but dross.<br/>',NULL,2400,2400);
INSERT INTO stanza VALUES('E472','2','Many sit at Jesus'' table,<br/>Few will fast with Him,<br/>When the sorrow-cup of anguish<br/>Trembles to the brim.<br/>Few watch with Him in the garden,<br/>Who have sung the hymn,<br/>Few watch with Him in the garden,<br/>Who have sung the hymn.<br/>',NULL,2401,2401);
INSERT INTO stanza VALUES('E472','3','Many will confess His wisdom,<br/>Few embrace His shame.<br/>Many, should He smile upon them,<br/>Will His praise proclaim;<br/>Then, if for a while He leave them,<br/>They desert His name,<br/>Then, if for a while He leave them,<br/>They desert His name.<br/>',NULL,2402,2402);
INSERT INTO stanza VALUES('E472','4','But the souls who love Him truly,<br/>Let woe come or bliss,<br/>These will count their dearest heart''s blood<br/>Not their own, but His.<br/>Savior, Thou who thus hast loved me,<br/>Give me love like this,<br/>Savior, Thou who thus hast loved me,<br/>Give me love like this.<br/>',NULL,2403,2403);
INSERT INTO stanza VALUES('E473','1','No mortal tongue can e''er describe<br/>The freedom of the soul,<br/>When passed beyond all earthly bribe<br/>To God''s complete control.<br/>All things are his, yes, life, and death,<br/>Things present or to come;<br/>In Christ he draws in peace each breath,<br/>In Christ he finds his home.<br/>',NULL,2404,2404);
INSERT INTO stanza VALUES('E473','2','When such as we the King can choose,<br/>To share with Him His throne,<br/>''Tis passing strange that we refuse<br/>To be our Lord''s alone.<br/>O never speak of sacrifice!<br/>A privilege untold<br/>Is to be His at any price,<br/>In Calv''ry''s hosts enrolled.<br/>',NULL,2405,2405);
INSERT INTO stanza VALUES('E473','3','Arise! The holy bargain strike-<br/>The fragment for the whole-<br/>All men and all events alike<br/>Must serve the ransomed soul.<br/>All things are yours when you are His,<br/>And He and you are one;<br/>A boundless life in Him there is,<br/>And kingdom yet to come.<br/>(The last line of the last verse is originally: Whence doubt and fear are gone.)<br/>',NULL,2406,2406);
INSERT INTO stanza VALUES('E474','1','I am one with Thee, Lord Jesus,<br/>One in spirit now with Thee;<br/>All Thyself I now possess, Lord,<br/>All Thou art now lives in me.<br/>',NULL,2407,2407);
INSERT INTO stanza VALUES('E474','chorus','One with Thee, one with Thee.<br/>One with Thee, one with Thee.<br/>Day by day I share Thy riches,<br/>Thou art everything to me.<br/>',NULL,2408,2408);
INSERT INTO stanza VALUES('E474','2','Now I share Thy human life, Lord,<br/>Filled with Thy humanity,<br/>All of Thy complete obedience<br/>Is available to me.<br/>',NULL,2409,2409);
INSERT INTO stanza VALUES('E474','3','One with Thee in crucifixion,<br/>On the cross I died in Thee;<br/>I am dead unto the world, Lord,<br/>And the world is dead to me.<br/>',NULL,2410,2410);
INSERT INTO stanza VALUES('E474','4','One with Thee in resurrection,<br/>Risen now to live in Thee,<br/>With that life which is Thyself, Lord,<br/>Now in me, Lord, even me.<br/>',NULL,2411,2411);
INSERT INTO stanza VALUES('E474','5','One with Thee in Thine ascension,<br/>In the heavens now with Thee;<br/>Here a pilgrim and a stranger,<br/>My true life is hid in Thee.<br/>',NULL,2412,2412);
INSERT INTO stanza VALUES('E474','6','One with Thee in Thine enthronement,<br/>Sharing Thine authority,<br/>Even as I share Thy life, Lord,<br/>I in Thee and Thou in me.<br/>',NULL,2413,2413);
INSERT INTO stanza VALUES('E475','1','One with Thee, Thou Son eternal,<br/>Joined by faith in spirit one,<br/>Share we in Thy death inclusive<br/>And Thy life, O God the Son.<br/>One with Thee, Thou Son beloved,<br/>Part of Thee become thru grace,<br/>Heirs with Thee of our one Father,<br/>We''re Thy Spirit''s dwelling place.<br/>',NULL,2414,2414);
INSERT INTO stanza VALUES('E475','2','One with Thee, Thou Son incarnate,<br/>Born with Thee, the Man of worth,<br/>We, the members of Thy body,<br/>Sojourn with Thee here on earth.<br/>One with Thee, Thou Son anointed,<br/>Sharing too the Spirit''s power,<br/>We in full cooperation<br/>Labor with Thee hour by hour.<br/>',NULL,2415,2415);
INSERT INTO stanza VALUES('E475','3','One with Thee, Thou Son forsaken,<br/>Judgment and the curse we''ve passed;<br/>We to sin are dead forever,<br/>Hell beneath our feet is cast.<br/>One with Thee in resurrection,<br/>Death can never us oppress;<br/>Live we in Thy new creation,<br/>Bearing fruits of righteousness.<br/>',NULL,2416,2416);
INSERT INTO stanza VALUES('E475','4','One with Thee, Thou Son ascended,<br/>Seated with Thee on the throne,<br/>Thine authority we share and<br/>Rule with Thee, Thy rank our own.<br/>One with Thee, Thou Son returning,<br/>Glorified with Thee we''ll be,<br/>E''er to manifest Thy beauty,<br/>One with Thee eternally.<br/>',NULL,2417,2417);
INSERT INTO stanza VALUES('E476','1','Oh, sacred union with the Perfect Mind,<br/>Transcendent bliss which Thou alone canst give;<br/>How blest are they this Peerless One who find,<br/>And, dead to earth, have learned in Thee to live.<br/>',NULL,2418,2418);
INSERT INTO stanza VALUES('E476','2','Thus in Thine arms of love, O Christ, I live,<br/>Lost, and forever lost to all but Thee.<br/>My happy soul, since it hath learned to die,<br/>Hath found new life in Thine Infinity.<br/>',NULL,2419,2419);
INSERT INTO stanza VALUES('E476','3','Go, then, and learn this lesson of the Cross,<br/>And tread the way that saints and prophets trod:<br/>Who, counting life and self and all things loss,<br/>Have found in inward death the life of God.<br/>',NULL,2420,2420);
INSERT INTO stanza VALUES('E477','1','Though Christ a thousand times<br/>In Bethlehem be born,<br/>If He''s not born in thee<br/>Thy soul is still forlorn.<br/>The Cross on Golgotha,<br/>Will never save thy soul;<br/>The Cross in thine own heart,<br/>Alone can make thee whole,<br/>',NULL,2421,2421);
INSERT INTO stanza VALUES('E477','chorus','O, Cross of Christ, I take thee<br/>Into this heart of mine,<br/>That I to my own self may die<br/>And rise to thy life Divine.<br/>',NULL,2422,2422);
INSERT INTO stanza VALUES('E477','2','What e''er thou lovest, man,<br/>That too become thou must;<br/>God, if thou lovest God,<br/>Dust, if thou lovest dust.<br/>Go out, God will come in;<br/>Die thou and let Him live;<br/>Be not and He will be;<br/>Wait and He''ll all things give.<br/>',NULL,2423,2423);
INSERT INTO stanza VALUES('E477','3','To bring thee to thy God,<br/>Love takes the shortest route;<br/>The way which knowledge leads,<br/>Is but a roundabout.<br/>Drive out from thee the world,<br/>And then thy heart shall be<br/>Filled with the love of God,<br/>And holy like as He.<br/>',NULL,2424,2424);
INSERT INTO stanza VALUES('E478','1','Once I stood in condemnation,<br/>Waiting thus the sinner''s doom;<br/>Christ in death has wrought salvation,<br/>God has raised Him from the tomb.<br/>Once I was to God a stranger,<br/>Filled with enmity and fear;<br/>He has rescued me from danger,<br/>Love revealed and brought me near.<br/>He has rescued me from danger,<br/>Love revealed and brought me near.<br/>',NULL,2425,2425);
INSERT INTO stanza VALUES('E478','2','Now I see in Christ''s acceptance<br/>But the measure of my own;<br/>He who lay beneath my sentence,<br/>Seated high upon the Throne.<br/>Quickened, raised, and in Him seated,<br/>I a full deliverance know;<br/>Every foe has been defeated,<br/>Every enemy laid low,<br/>Every foe has been defeated,<br/>Every enemy laid low.<br/>',NULL,2426,2426);
INSERT INTO stanza VALUES('E478','3','Now I have a life in union<br/>With the risen Lord above;<br/>Now I drink in sweet communion<br/>Some rich foretaste of His love.<br/>Soon, O Lord! In highest glory,<br/>All its vastness I''ll explore;<br/>Soon I''ll cast my crown before Thee,<br/>While I worship and adore,<br/>Soon I''ll cast my crown before Thee,<br/>While I worship and adore.<br/>',NULL,2427,2427);
INSERT INTO stanza VALUES('E479','1','Oh, what a wonderful place<br/>Jesus has given to me!<br/>Saved by His glorious grace,<br/>I may be even as He.<br/>When with my Lord I appear,<br/>Like Him I know I shall be;<br/>But while I walk with Him here,<br/>I may be even as He.<br/>',NULL,2428,2428);
INSERT INTO stanza VALUES('E479','chorus','Even as He, even as He,<br/>Wonderful words that even we,<br/>Saved by His marvelous grace may be<br/>One with the Savior, even as He.<br/>',NULL,2429,2429);
INSERT INTO stanza VALUES('E479','2','One in His death on the tree,<br/>One as He rose from the dead;<br/>I from the curse am as free<br/>E''en as my glorious Head.<br/>One on the throne by His side,<br/>One in His sonship divine;<br/>One as the bride-groom and the bride,<br/>One as the branch and the vine.<br/>',NULL,2430,2430);
INSERT INTO stanza VALUES('E479','3','One in His merits I stand,<br/>One as I pray in His name;<br/>All that His worth can command,<br/>I can with confidence claim.<br/>One in His faith and His love,<br/>One in His life I may be.<br/>Sealed by the heavenly Dove,<br/>I may be holy as He. ?<br/>',NULL,2431,2431);
INSERT INTO stanza VALUES('E480','1','Joined unto Christ the Conqueror,<br/>His Calv''ry triumph, too,<br/>Assures me in the darkest hour<br/>That He will take me through.<br/>',NULL,2432,2432);
INSERT INTO stanza VALUES('E480','2','Joined unto Christ the risen Lord,<br/>Triumphant now above;<br/>The glory of His cross reveals<br/>Magnificence of love.<br/>',NULL,2433,2433);
INSERT INTO stanza VALUES('E480','3','Joined unto Christ''s full victory,<br/>Magnificently free;<br/>Declare it in the conquering name,<br/>And powers of darkness flee.<br/>',NULL,2434,2434);
INSERT INTO stanza VALUES('E480','4','Joined unto Christ! Magnificent!<br/>His wondrous Calvary plan,<br/>Draws us through ages to adore;<br/>For "Worthy is the Lamb."<br/>',NULL,2435,2435);
INSERT INTO stanza VALUES('E481','1','Crucified with Christ my Savior,<br/>To the world and self and sin;<br/>To the death-born life of Jesus<br/>I am sweetly ent''ring in:<br/>In His fellowship of suff''ring,<br/>To His death conformed to be,<br/>I am going with my Savior<br/>All the way to Calvary.<br/>',NULL,2436,2436);
INSERT INTO stanza VALUES('E481','chorus','All the way to Calvary,<br/>Where my Savior went for me,<br/>Help me, Lord, to go with Thee,<br/>All the way to Calvary.<br/>',NULL,2437,2437);
INSERT INTO stanza VALUES('E481','2','''Tis not hard to die with Christ<br/>When His risen life we know;<br/>''Tis not hard to share His suff''rings<br/>When our hearts with joy o''erflow.<br/>In His resurrection power<br/>He has come to dwell in me,<br/>And my heart is gladly going<br/>All the way to Calvary.<br/>',NULL,2438,2438);
INSERT INTO stanza VALUES('E481','3','If we die we''ll live with Christ,<br/>If we suffer we shall reign;<br/>Only thus the prize of glory<br/>Can the conqueror attain.<br/>Oh, how sweet, on that glad morning<br/>Should the Master say to thee,<br/>"Yes, my child, thou didst go with me<br/>All the way to Calvary."<br/>',NULL,2439,2439);
INSERT INTO stanza VALUES('E482','1','I am crucified with Christ,<br/>And the cross hath set me free;<br/>I have ris''n again with Christ,<br/>And He lives and reigns in me.<br/>',NULL,2440,2440);
INSERT INTO stanza VALUES('E482','chorus','Oh! It is so sweet to die with Christ,<br/>To the world, and self, and sin;<br/>Oh! It is so sweet to live with Christ,<br/>As He lives and reigns within.<br/>',NULL,2441,2441);
INSERT INTO stanza VALUES('E482','2','Mystery hid from ancient ages!<br/>But at length to faith made plain:<br/>Christ in me the Hope of Glory,<br/>Tell it o''er and o''er again.<br/>',NULL,2442,2442);
INSERT INTO stanza VALUES('E482','3','This the secret nature hideth,<br/>Harvest grows from buried grain;<br/>A poor tree with better grafted,<br/>Richer, sweeter life doth gain.<br/>',NULL,2443,2443);
INSERT INTO stanza VALUES('E482','4','This the secret of the holy,<br/>Not our holiness, but Him;<br/>O Lord! Empty us and fill us,<br/>With Thy fulness to the brim.<br/>',NULL,2444,2444);
INSERT INTO stanza VALUES('E482','5','This the balm for pain and sickness,<br/>Just to all our strength to die,<br/>And to find His life and fulness,<br/>All our being''s need supply.<br/>',NULL,2445,2445);
INSERT INTO stanza VALUES('E482','6','This the story of the Master,<br/>Thru the Cross, He reached the Throne,<br/>And like Him our path to glory,<br/>Ever leads through death alone.<br/>',NULL,2446,2446);
INSERT INTO stanza VALUES('E483','1','Buried with Christ, and raised with Him too;<br/>What is there left for me to do?<br/>Simply to cease from struggling and strife,<br/>Simply to walk in newness of life.<br/>Glory be to God!<br/>',NULL,2447,2447);
INSERT INTO stanza VALUES('E483','2','Risen with Christ, my glorious Head,<br/>Holiness now the pathway I tread,<br/>Beautiful thought, while walking therein:<br/>He that is dead is freed from sin.<br/>Glory be to God!<br/>',NULL,2448,2448);
INSERT INTO stanza VALUES('E483','3','Living with Christ, who dieth no more,<br/>Following Christ, who goeth before;<br/>I am from bondage utterly freed,<br/>Reckoning self as dead indeed.<br/>Glory be to God!<br/>',NULL,2449,2449);
INSERT INTO stanza VALUES('E483','4','Living for Christ, my members I yield,<br/>Servants for God, for evermore sealed,<br/>Not under law, I''m now under grace,<br/>Sin is dethroned, and Christ takes its place.<br/>Glory be to God!<br/>',NULL,2450,2450);
INSERT INTO stanza VALUES('E483','5','Growing in Christ; no more shall be named<br/>Thing of which now I''m truly ashamed,<br/>Fruit unto holiness will I bear,<br/>Life evermore, the end I shall share.<br/>Glory be to God!<br/>',NULL,2451,2451);
INSERT INTO stanza VALUES('E484','1','When Christ once died on Calvary,<br/>I too was there;<br/>''Twas in my place He stood for me,<br/>And now accepted e''en as He,<br/>His name I bear.<br/>',NULL,2452,2452);
INSERT INTO stanza VALUES('E484','chorus','I am crucified with Christ, nevertheless I live,<br/>Yet, not I, but Christ who liveth in me;<br/>And the life I live in the flesh,<br/>I live by the faith of the Son of God,<br/>Who loved, and gave Himself for me.<br/>',NULL,2453,2453);
INSERT INTO stanza VALUES('E484','2','When Christ once rose with life divine,<br/>I too was there;<br/>His resurrection pow''r is mine,<br/>And as the branches and the vine<br/>His life I share.<br/>',NULL,2454,2454);
INSERT INTO stanza VALUES('E484','3','When Christ will come some day for me,<br/>I shall be there;<br/>With Him and like Him I shall be,<br/>And all His glorious majesty<br/>I too shall share.<br/>',NULL,2455,2455);
INSERT INTO stanza VALUES('E484','4','O blessed life so deep, so high,<br/>Lord, keep me there;<br/>Help me with Him, bye and bye<br/>His glory share.<br/>',NULL,2456,2456);
INSERT INTO stanza VALUES('E485','1','What great provision God has made<br/>In Jesus'' death on Calvary!<br/>I hung with Him upon the tree,<br/>And in His tomb I too was laid.<br/>',NULL,2457,2457);
INSERT INTO stanza VALUES('E485','2','I rose with Him from out the grave-<br/>And how shall I died to sin<br/>Continue still to live therein,<br/>The victor living as the slave?<br/>',NULL,2458,2458);
INSERT INTO stanza VALUES('E485','3','At God''s right hand He took His place,<br/>And while for saints my Savior pleads,<br/>My heart for sinners intercedes<br/>That they might know His saving grace.<br/>',NULL,2459,2459);
INSERT INTO stanza VALUES('E485','4','Oh, what a name to me is given-<br/>A son of God, by second birth!<br/>I represent Him on the earth,<br/>He represents me now in heaven.<br/>',NULL,2460,2460);
INSERT INTO stanza VALUES('E485','5','As Jesus dwells beyond the skies,<br/>I dwell within this world of strife;<br/>And as He lives within my life,<br/>In Him I''m in the heavenlies!<br/>',NULL,2461,2461);
INSERT INTO stanza VALUES('E486','1','Dying with Jesus, by death reckoned mine;<br/>Living with Jesus a new life divine;<br/>Looking to Jesus till glory doth shine,<br/>Moment by moment, O Lord, I am Thine.<br/>',NULL,2462,2462);
INSERT INTO stanza VALUES('E486','chorus','Moment by moment I''m kept in His love,<br/>Moment by moment I''ve life from above;<br/>Looking to Jesus till glory doth shine;<br/>Moment by moment, O Lord, I am Thine.<br/>',NULL,2463,2463);
INSERT INTO stanza VALUES('E486','2','Never a battle with wrong for the right,<br/>Never a contest that He doth not fight;<br/>Lifting above us His banner so white;<br/>Moment by moment I''m kept in His sight.<br/>',NULL,2464,2464);
INSERT INTO stanza VALUES('E486','3','Never a trial that He is not there,<br/>Never a burden that He doth not bear;<br/>Never a sorrow that He doth not share,<br/>Moment by moment, I''m under His care.<br/>',NULL,2465,2465);
INSERT INTO stanza VALUES('E486','4','Never a heartache, and never a groan,<br/>Never a teardrop, and never a moan;<br/>Never a danger but there on the throne<br/>Moment by moment He thinks of His own.<br/>',NULL,2466,2466);
INSERT INTO stanza VALUES('E486','5','Never a weakness that He doth not feel,<br/>Never a sickness that He cannot heal;<br/>Moment by moment, in woe or in weal,<br/>Jesus, my Savior, abides with me still.<br/>',NULL,2467,2467);
INSERT INTO stanza VALUES('E487','1','What a wondrous fact, I''m crucified with Christ;<br/>Of my flesh and passion I''m relieved;<br/>What a glorious fact, with Christ, the Lord, I live,<br/>Resurrected life in Him received.<br/>',NULL,2468,2468);
INSERT INTO stanza VALUES('E487','2','On the Cross of Calvary the Lord and I<br/>Were crucified, were crucified;<br/>Now in resurrection life with Him I live<br/>And in Him e''er abide.<br/>',NULL,2469,2469);
INSERT INTO stanza VALUES('E488','1','Lord, Thou hast show the mystery,<br/>How on the Cross I died with Thee;<br/>I need no other pow''r or way<br/>That I may triumph day by day.<br/>',NULL,2470,2470);
INSERT INTO stanza VALUES('E488','2','That cross of Thine is also mine,<br/>Into my life its light doth shine;<br/>When I believe I''m dead with Thee,<br/>The world has lost it pow''r o''er me.<br/>',NULL,2471,2471);
INSERT INTO stanza VALUES('E488','3','Since I am crucified with Thee,<br/>From sin and self I am set free;<br/>How can I still enjoy the world<br/>Or seek its vanities unfurled?<br/>',NULL,2472,2472);
INSERT INTO stanza VALUES('E488','4','I take my place, dear Lord, with Thee<br/>Upon the cross of Calvary.<br/>Thy life and power then are mine,<br/>Since Thou and I in oneness twine.<br/>',NULL,2473,2473);
INSERT INTO stanza VALUES('E488','5','Since Thou didst come to slay the foe,<br/>His work and power to overthrow,<br/>I too can overcome in Thee<br/>And prove Thy mighty pow''r in me.<br/>',NULL,2474,2474);
INSERT INTO stanza VALUES('E488','6','Yet, for the vict''ry we rely<br/>Upon the death which Thou didst die;<br/>We tread the path which Thou hast trod<br/>Until we reach the goal in God.<br/>',NULL,2475,2475);
INSERT INTO stanza VALUES('E488','7','My death with Thee I now believe<br/>And all its meaning would receive.<br/>Thy death more deeply show to me,<br/>That from my flesh I may be free.<br/>',NULL,2476,2476);
INSERT INTO stanza VALUES('E488','8','I long to win as Thou hast won,<br/>To reign with Thee when Thou dost come.<br/>If we the cross will gladly bear,<br/>Then in Thy glory we will share.<br/>',NULL,2477,2477);
INSERT INTO stanza VALUES('E489','1','Oh, Jesus, Lord, when Thou on earth<br/>Accompanied Thy faithful band,<br/>It seemed they knew, but knew Thee not,<br/>Thyself they did not understand.<br/>',NULL,2478,2478);
INSERT INTO stanza VALUES('E489','2','They heard Thy voice, beheld Thy form,<br/>Thy beauteous stature unforgot;<br/>They crowded ''round Thee, met Thy gaze,<br/>But who Thou art, they knew it not.<br/>',NULL,2479,2479);
INSERT INTO stanza VALUES('E489','3','As they of old we too are veiled;<br/>We''ve known Thee long apparently;<br/>Yet if we say we know, at best<br/>We know Thee not transparently.<br/>',NULL,2480,2480);
INSERT INTO stanza VALUES('E489','4','But as the Spirit now Thou art,<br/>Another Comforter become;<br/>Reveal Thyself within my heart,<br/>Since to Thy temple Thou hast come.<br/>',NULL,2481,2481);
INSERT INTO stanza VALUES('E489','5','With Thy blest Spirit, Lord, fill me,<br/>Fill every corner of my soul;<br/>May Thou inspire my every part,<br/>Oh may Thou touch, renew the whole.<br/>',NULL,2482,2482);
INSERT INTO stanza VALUES('E489','6','The Spirit then revealing make<br/>Thyself more real within my heart,<br/>That ear not hear, nor eye may see<br/>How very real to me Thou art.<br/>',NULL,2483,2483);
INSERT INTO stanza VALUES('E489','7','When Thou in mercy dost reveal<br/>And give Thyself as Spirit thus,<br/>What in the world can be more real,<br/>More true than what Thou art to us?<br/>',NULL,2484,2484);
INSERT INTO stanza VALUES('E489','8','Thy Spirit, Lord, in mine, I pray,<br/>O''erflow my being as a flood,<br/>That every part with glory shine<br/>And everywhere be Thee and God.<br/>',NULL,2485,2485);
INSERT INTO stanza VALUES('E489','9','How close we are in such a life,<br/>In one is blended earth with heav''n;<br/>Thy presence sweetly fills our souls;<br/>Our hearts are to Thy praises giv''n.<br/>',NULL,2486,2486);
INSERT INTO stanza VALUES('E490','1','Lord, when the Father ne''er was known,<br/>The Father came through Thee below,<br/>That we who lived in ignorance<br/>Might through Thyself the Father know.<br/>',NULL,2487,2487);
INSERT INTO stanza VALUES('E490','2','But, Lord, when Thou wast here on earth,<br/>How scarce were those Thyself who knew;<br/>A veil there was ''twixt Thee and them;<br/>They crowded ''round but saw not through.<br/>',NULL,2488,2488);
INSERT INTO stanza VALUES('E490','3','Now as the Spirit Thou hast come<br/>E''en as the Father came in Thee;<br/>As we through Thee the Father know,<br/>Now through the Spirit we know Thee.<br/>',NULL,2489,2489);
INSERT INTO stanza VALUES('E490','4','Not with the flesh Thou now art clothed-<br/>Then must Thou walk with toil around;<br/>But as the Spirit in our heart<br/>Thou dost supply Thyself unbound.<br/>',NULL,2490,2490);
INSERT INTO stanza VALUES('E490','5','Thou, Lord, the Father once wast called,<br/>But now the Holy Spirit art;<br/>The Spirit is Thine other form,<br/>Thyself to dwell within our heart.<br/>',NULL,2491,2491);
INSERT INTO stanza VALUES('E490','6','By knowing Thee as Spirit, Lord,<br/>We realize Thy life''s outflow,<br/>Thy glory and Thy character,<br/>And all Thy being''s wonders know.<br/>',NULL,2492,2492);
INSERT INTO stanza VALUES('E490','7','Praise to Thy Name now floods our heart;<br/>There is no one as dear as Thee;<br/>For since we know how real Thou art,<br/>No other one could lovelier be.<br/>',NULL,2493,2493);
INSERT INTO stanza VALUES('E491','1','Lord, Thou didst know when in the flesh,<br/>As such I''d know Thee shallowly;<br/>Then as the Spirit Thou didst come<br/>Within my spirit, known to be.<br/>',NULL,2494,2494);
INSERT INTO stanza VALUES('E491','2','In flesh Redeemer mine Thou art;<br/>As Spirit now my Comforter.<br/>The outward touch has passed away<br/>For inward union worthier.<br/>',NULL,2495,2495);
INSERT INTO stanza VALUES('E491','3','Because Thou art the Spirit now,<br/>Thyself revealing ceaselessly,<br/>Within my spirit I may know<br/>Thy presence and reality.<br/>',NULL,2496,2496);
INSERT INTO stanza VALUES('E491','4','I know Thy life surpassing far<br/>The knowledge Thy disciples had,<br/>Although they walked and lived with Thee,<br/>When Thou on earth in flesh wast clad.<br/>',NULL,2497,2497);
INSERT INTO stanza VALUES('E491','5','Because Thy Spirit dwells within,<br/>How real, O Lord, Thou art to me;<br/>Not touched, yet more reliable,<br/>Not seen, yet loved more fervently.<br/>',NULL,2498,2498);
INSERT INTO stanza VALUES('E491','6','Thy Holy Spirit deep within<br/>Supplies Thyself as righteousness,<br/>As holiness, redemption full,<br/>As wisdom and as fruitfulness.<br/>',NULL,2499,2499);
INSERT INTO stanza VALUES('E491','7','Thy Spirit in my spirit now<br/>Supplies Thyself, unites with me,<br/>Thus I am all the time myself<br/>And constantly am also Thee.<br/>',NULL,2500,2500);
INSERT INTO stanza VALUES('E492','1','In all Thy work, O Lord, Thou didst<br/>At Calv''ry''s cross once come to rest;<br/>Yet Thou art working still today,<br/>But in another form expressed.<br/>',NULL,2501,2501);
INSERT INTO stanza VALUES('E492','2','Thy saving pow''r Thou still dost show;<br/>Thou still dost speak, enlighten, guide;<br/>Thou and the Spirit in one stream<br/>Sweep many in Thy living tide.<br/>',NULL,2502,2502);
INSERT INTO stanza VALUES('E492','3','Through Him Thy power''s not withheld;<br/>Through Him Thy working does not cease;<br/>Thou still dost comfort and command,<br/>Encourage, strengthen, and release.<br/>',NULL,2503,2503);
INSERT INTO stanza VALUES('E492','4','Since Thou art with the Spirit one<br/>His coming means that Thou hast come,<br/>And His indwelling is Thine own,<br/>Since Thou the Spirit hast become.<br/>',NULL,2504,2504);
INSERT INTO stanza VALUES('E492','5','He executes within my heart<br/>All Thy desires and Thy demands,<br/>As for the Father here on earth<br/>Thou hast performed all His commands.<br/>',NULL,2505,2505);
INSERT INTO stanza VALUES('E492','6','By knowing Him we know Thyself;<br/>Obeying Him we Thee obey;<br/>Allowing Him ourselves to fill,<br/>We''re filled with Thee, O wondrous way!<br/>',NULL,2506,2506);
INSERT INTO stanza VALUES('E492','7','Thou art not far away in heav''n,<br/>Leaving us here alone, apart;<br/>But Thou art still on earth; how grand!<br/>Thou livest right within my heart.<br/>',NULL,2507,2507);
INSERT INTO stanza VALUES('E493','1','O Lord, Thou art the Spirit now<br/>That gives us life and quickens us,<br/>With all Thy riches strengthening,<br/>O how divine and glorious!<br/>',NULL,2508,2508);
INSERT INTO stanza VALUES('E493','2','O Lord, Thou art the Spirit now<br/>That with Thy power liberates;<br/>And by Thy liberation true<br/>The law of life now regulates.<br/>',NULL,2509,2509);
INSERT INTO stanza VALUES('E493','3','O Lord, Thou art the Spirit now<br/>That transforms us and saturates,<br/>And to Thine image true conforms<br/>And with Thy light illuminates.<br/>',NULL,2510,2510);
INSERT INTO stanza VALUES('E493','4','O Lord, Thou art the Spirit now<br/>Who in my spirit makes His home;<br/>He mingles with my spirit too,<br/>And both one spirit thus become.<br/>',NULL,2511,2511);
INSERT INTO stanza VALUES('E493','5','Lord, teach me how to exercise<br/>My spirit now to contact Thee,<br/>That in Thy Spirit I may walk<br/>And live by Thy reality.<br/>',NULL,2512,2512);
INSERT INTO stanza VALUES('E494','1','Christ is the testimony true<br/>Of God in essence and in deed;<br/>God''s glory He has fully shown,<br/>And we in Him God''s nature read.<br/>',NULL,2513,2513);
INSERT INTO stanza VALUES('E494','2','His testimony is more full<br/>Than was the witness of the law,<br/>Which only God in letter showed,<br/>And not in endless living pow''r.<br/>',NULL,2514,2514);
INSERT INTO stanza VALUES('E494','3','The fulness of the Godhead dwells<br/>In Him, His very element;<br/>God''s full embodiment is He-<br/>A vessel, God the resident.<br/>',NULL,2515,2515);
INSERT INTO stanza VALUES('E494','4','The Father God He manifests;<br/>God''s glorious features He displays;<br/>In Him consummately are seen<br/>The Father''s heart and all His ways.<br/>',NULL,2516,2516);
INSERT INTO stanza VALUES('E494','5','Christ as the Spirit now has come<br/>That He our portion be fore''er;<br/>In spirit we partake of Him<br/>And all God''s being fully share.<br/>',NULL,2517,2517);
INSERT INTO stanza VALUES('E495','1','Christ is God'' centrality<br/>And His universality;<br/>He is God''s delight and joy<br/>Throughout all eternity.<br/>',NULL,2518,2518);
INSERT INTO stanza VALUES('E495','2','He''s th'' embodiment of God,<br/>In Him all God''s fulness dwells;<br/>His unique supremacy<br/>And His Godhead none excels.<br/>',NULL,2519,2519);
INSERT INTO stanza VALUES('E495','3','All God''s purpose is for Him,<br/>That He might be all in all''<br/>All the things in heav''n or earth<br/>With Himself are made withal.<br/>',NULL,2520,2520);
INSERT INTO stanza VALUES('E495','4','All creation is for Christ,<br/>Everything was made by Him;<br/>''Tis by Him all things subsist,<br/>He''s the hub and He''s the rim.<br/>',NULL,2521,2521);
INSERT INTO stanza VALUES('E495','5','In redemption He is all,<br/>All through Him is reconciled;<br/>By His blood all things with God<br/>Now in peace are domiciled.<br/>',NULL,2522,2522);
INSERT INTO stanza VALUES('E495','6','He the great beginning is,<br/>And the Church''s living Head;<br/>He her life and content too,<br/>And the firstborn from the dead.<br/>',NULL,2523,2523);
INSERT INTO stanza VALUES('E495','7','In God''s Kingdom He''s the King,<br/>All the pow''r to Him is giv''n;<br/>In His glory He shall rule<br/>Over all in earth and heav''n.<br/>',NULL,2524,2524);
INSERT INTO stanza VALUES('E495','8','In new heaven and new earth<br/>Center of all things He''ll be,<br/>For the Godhead and for man<br/>Throughout all eternity.<br/>',NULL,2525,2525);
INSERT INTO stanza VALUES('E495','9','God intends in everything<br/>Christ should have preeminence,<br/>And that such a Christ of all<br/>We should now experience.<br/>',NULL,2526,2526);
INSERT INTO stanza VALUES('E496','1','Christ is the one reality of all,<br/>Of Godhead and of man and all things else;<br/>No man without Him ever findeth God,<br/>Without Him man and everything is false.<br/>',NULL,2527,2527);
INSERT INTO stanza VALUES('E496','2','All types and figures of the ancient time,<br/>All things we ever need, both great and small,<br/>Only are shadows of the Christ of God,<br/>Showing that He must be our all in all.<br/>',NULL,2528,2528);
INSERT INTO stanza VALUES('E496','3','All things are vanity of vanities,<br/>Christ, the reality all things to fill;<br/>Though everything we may enjoy and own,<br/>If we''re devoid of Christ we''re empty still.<br/>',NULL,2529,2529);
INSERT INTO stanza VALUES('E496','4','Christ is our real God, our real Lord,<br/>Christ is our real life, our real light;<br/>Christ is our real food, our real drink,<br/>Our real clothing, and our real might.<br/>',NULL,2530,2530);
INSERT INTO stanza VALUES('E496','5','Christ also is the one reality<br/>Of all our doctrine and theology;<br/>And all our scriptural knowledge without Him<br/>Is just in letter and is vanity.<br/>',NULL,2531,2531);
INSERT INTO stanza VALUES('E496','6','Christ, the reality of time and space,<br/>Christ, the reality of every stage;<br/>Christ is the one reality of all<br/>Thru all eternity from age to age.<br/>',NULL,2532,2532);
INSERT INTO stanza VALUES('E497','1','Grace in its highest definition is<br/>God in the Son to be enjoyed by us;<br/>It is not only something done or giv''n,<br/>But God Himself, our portion glorious.<br/>',NULL,2533,2533);
INSERT INTO stanza VALUES('E497','2','God is incarnate in the flesh that we<br/>Him may receive, experience ourself;<br/>This is the grace which we receive of God,<br/>Which come thru Christ and which is Christ Himself.<br/>',NULL,2534,2534);
INSERT INTO stanza VALUES('E497','3','Paul the Apostle counted all as dung,<br/>''Twas only God in Christ he counted grace;<br/>''Tis by this grace-the Lord experienced-<br/>That he surpassed the others in the race.<br/>',NULL,2535,2535);
INSERT INTO stanza VALUES('E497','4','It is this grace-Christ as our inward strength-<br/>Which with His all-sufficiency doth fill;<br/>It is this grace which in our spirit is,<br/>There energizing, working out God''s will.<br/>',NULL,2536,2536);
INSERT INTO stanza VALUES('E497','5','This grace, which is the living Christ Himself,<br/>Is what we need and must experience;<br/>Lord, may we know this grace and by it live,<br/>Thyself increasingly as grace to sense.<br/>',NULL,2537,2537);
INSERT INTO stanza VALUES('E498','1','This is my wonderful story,<br/>Christ to my heart has come;<br/>Jesus, the King of Glory,<br/>Finds in my heart a home.<br/>',NULL,2538,2538);
INSERT INTO stanza VALUES('E498','chorus','Christ in me, Christ in me,<br/>Christ in me, O wonderful story,<br/>Christ in me, Christ in me,<br/>Christ in me, the hope of glory.<br/>',NULL,2539,2539);
INSERT INTO stanza VALUES('E498','2','Was there e''er story so moving,<br/>Story of love and pain;<br/>Was there e''er Bridegroom so loving,<br/>Seeking our hearts to gain.<br/>',NULL,2540,2540);
INSERT INTO stanza VALUES('E498','3','I am so glad I received Him,<br/>Jesus my heart''s dear King;<br/>I who so often have grieved Him,<br/>All to His feet would bring.<br/>',NULL,2541,2541);
INSERT INTO stanza VALUES('E498','4','How can I ever be lonely,<br/>How can I ever fall;<br/>What can I want, if only<br/>Christ is my all in all?<br/>',NULL,2542,2542);
INSERT INTO stanza VALUES('E498','5','Now in His bosom confiding,<br/>This my glad song shall be;<br/>I am in Christ abiding,<br/>And Christ abides in me.<br/>',NULL,2543,2543);
INSERT INTO stanza VALUES('E499','1','Oh, what a life! Oh, what a peace!<br/>The Christ who''s all within me lives.<br/>With Him I have been crucified;<br/>This glorious fact to me He gives.<br/>Now it''s no longer I that live,<br/>But Christ the Lord within me lives.<br/>',NULL,2544,2544);
INSERT INTO stanza VALUES('E499','2','Oh, what a Joy! Oh, what a rest!<br/>Christ now is being formed in me.<br/>His very nature and life divine<br/>In my whole being inwrought shall be.<br/>All that I am came to an end,<br/>And all of Christ is all to me.<br/>',NULL,2545,2545);
INSERT INTO stanza VALUES('E499','3','Oh, what a thought! Oh, what a boast!<br/>Christ shall in me be magnified.<br/>In nothing shall I be ashamed,<br/>For He in all shall be applied.<br/>In woe or blessing death or life,<br/>Through me shall Christ be testified.<br/>',NULL,2546,2546);
INSERT INTO stanza VALUES('E499','4','Oh, what a prize! Oh, what a gain!<br/>Christ is the goal toward which I press.<br/>Nothing I treasure, nor aught desire,<br/>But Christ of all-inclusiveness.<br/>My hope, my glory, and my crown<br/>Is Christ, the One of peerlessness.<br/>',NULL,2547,2547);
INSERT INTO stanza VALUES('E499','end-note','(Repeat the last two lines of each stanzas)<br/>',NULL,2548,2548);
INSERT INTO stanza VALUES('E500','1','Oh, what a might! Oh, what a strength!<br/>God wrought to raise Christ from the dead.<br/>Far above all at His right hand,<br/>O''er all to us He is the Head.<br/>All this great pow''r is to the Church<br/>That she o''er all her foes may tread.<br/>All this great pow''r is to the Church<br/>That she o''er all her foes may tread.<br/>',NULL,2549,2549);
INSERT INTO stanza VALUES('E500','2','Oh, what a fact! Oh, what a bliss!<br/>That I of Christ a member am.<br/>With all the saints I blend as one<br/>And share the life of the new man.<br/>Joined to our great ascended Head,<br/>We''ll be the Church of His own plan.<br/>Joined to our great ascended Head,<br/>We''ll be the Church of His own plan.<br/>',NULL,2550,2550);
INSERT INTO stanza VALUES('E500','3','Oh, what a breadth! Oh, what a length!<br/>The height, the depth unsearchable!<br/>Christ the Lord is unlimited,<br/>So vast, immense, immeas''rable.<br/>All that He is and all He has<br/>Is now our life unspeakable.<br/>All that He is and all He has<br/>Is now our life unspeakable.<br/>',NULL,2551,2551);
INSERT INTO stanza VALUES('E501','1','O glorious Christ, Savior mine,<br/>Thou art truly radiance divine;<br/>God infinite, in eternity,<br/>Yet man in time, finite to be.<br/>',NULL,2552,2552);
INSERT INTO stanza VALUES('E501','chorus','Oh! Christ, expression of God, the Great,<br/>Inexhaustible, rich, and sweet!<br/>God mingled with humanity<br/>Lives in me my all to be.<br/>',NULL,2553,2553);
INSERT INTO stanza VALUES('E501','2','The fulness of God dwells in Thee;<br/>Thou dost manifest God''s glory;<br/>In flesh Thou hast redemption wrought;<br/>As Spirit, oneness with me sought.<br/>',NULL,2554,2554);
INSERT INTO stanza VALUES('E501','3','All things of the Father are Thine;<br/>All Thou art in Spirit is mine;<br/>The Spirit makes Thee real to me,<br/>That Thou experienced might be.<br/>',NULL,2555,2555);
INSERT INTO stanza VALUES('E501','4','The Spirit of life causes Thee<br/>By Thy Word to transfer to me.<br/>Thy Spirit touched, Thy Word received,<br/>Thy life in me is thus conceived.<br/>',NULL,2556,2556);
INSERT INTO stanza VALUES('E501','5','In spirit while gazing on Thee,<br/>As a glass reflecting Thy glory,<br/>Like to Thyself transformed I''ll be,<br/>That Thou might be expressed thru me.<br/>',NULL,2557,2557);
INSERT INTO stanza VALUES('E501','6','In no other way could we be<br/>Sanctified and share Thy vict''ry;<br/>Thus only spiritual we''ll be,<br/>And touch the life of glory.<br/>',NULL,2558,2558);
INSERT INTO stanza VALUES('E501','7','Thy Spirit will me saturate,<br/>Every part will God permeate,<br/>Deliv''ring me from the old man,<br/>With all saints building for His plan.<br/>',NULL,2559,2559);
INSERT INTO stanza VALUES('E502','1','Once I was dead in sin,<br/>And hope within me died;<br/>But now I''m dead to sin,<br/>With Christ I''m crucified.<br/>',NULL,2560,2560);
INSERT INTO stanza VALUES('E502','chorus','And can it be that "He loved me,<br/>And gave Himself for me"?<br/>',NULL,2561,2561);
INSERT INTO stanza VALUES('E502','2','O height I cannot reach!<br/>O depth I cannot sound!<br/>O love, O boundless love,<br/>In my Redeemer found!<br/>',NULL,2562,2562);
INSERT INTO stanza VALUES('E502','3','I live-and yet not I,<br/>But Christ that lives in me,<br/>Who from the law of sin<br/>And death has made me free.<br/>',NULL,2563,2563);
INSERT INTO stanza VALUES('E503','1','I serve a risen Savior;<br/>He''s in the world today.<br/>I know that He is living,<br/>Whatever men may say.<br/>I see His hand of mercy;<br/>I hear His voice of cheer;<br/>And just the time I need Him<br/>He''s always near.<br/>',NULL,2564,2564);
INSERT INTO stanza VALUES('E503','chorus','He lives, He lives, Christ Jesus lives today!<br/>He walks with me and talks with me along<br/>life''s narrow way.<br/>He lives, He lives, salvation to impart!<br/>You ask me how I know He lives?<br/>He lives within my heart.<br/>',NULL,2565,2565);
INSERT INTO stanza VALUES('E503','2','In all the world around me<br/>I see His loving care,<br/>And though my heart grows weary,<br/>I never will despair;<br/>I know that He is leading,<br/>Through all the stormy blast;<br/>The day of His appearing<br/>Will come at last.<br/>',NULL,2566,2566);
INSERT INTO stanza VALUES('E503','3','Rejoice, rejoice, O Christian,<br/>Lift up your voice and sing<br/>Eternal hallelujahs<br/>To Jesus Christ the King!<br/>The Hope of all who seek Him,<br/>The Help of all who find,<br/>None other is so loving,<br/>So good and kind.<br/>',NULL,2567,2567);
INSERT INTO stanza VALUES('E504','1','Jesus, I live to Thee,<br/>The Loveliest and Best;<br/>My life in Thee, Thy life in me,<br/>In Thy blest love I rest.<br/>',NULL,2568,2568);
INSERT INTO stanza VALUES('E504','2','Jesus, I die to Thee,<br/>Whenever death shall come;<br/>To die in Thee is life to me,<br/>With Thee I''m ever one!<br/>',NULL,2569,2569);
INSERT INTO stanza VALUES('E504','3','Whether to live or die,<br/>I know not which is best;<br/>To live in Thee is bliss to me,<br/>To die is endless rest.<br/>',NULL,2570,2570);
INSERT INTO stanza VALUES('E504','4','Living or dying, Lord,<br/>I ask but to be Thine;<br/>My life in Thee, Thy life in me,<br/>Makes Thee forever mine.<br/>',NULL,2571,2571);
INSERT INTO stanza VALUES('E505','1','There''s a Man in the glory<br/>Whose Life is for me.<br/>He''s pure and He''s holy,<br/>Triumphant and free.<br/>He''s wise and He''s loving,<br/>How tender is He!<br/>His Life in the glory,<br/>My life must be;<br/>His Life in the glory,<br/>My life must be.<br/>',NULL,2572,2572);
INSERT INTO stanza VALUES('E505','2','There''s a Man in the glory<br/>Whose Life is for me.<br/>He overcame Satan;<br/>From bondage He''s free.<br/>In Life He is reigning;<br/>How kingly is He!<br/>His Life in the glory,<br/>My life must be;<br/>His Life in the glory,<br/>My life must be.<br/>',NULL,2573,2573);
INSERT INTO stanza VALUES('E505','3','There''s a Man in the glory<br/>Whose Life is for me.<br/>In Him is no sickness;<br/>No weakness has He.<br/>He''s strong and in vigor,<br/>How buoyant is He!<br/>His Life in the glory<br/>My life may be;<br/>His Life in the glory<br/>My life may be.<br/>',NULL,2574,2574);
INSERT INTO stanza VALUES('E505','4','There''s a Man in the glory<br/>Whose Life is for me.<br/>His peace is abiding;<br/>How patient is He!<br/>He''s joyful and radiant,<br/>Expecting to see<br/>His Life in the glory<br/>Lived out in me;<br/>His life in the glory<br/>Lived out in me.<br/>',NULL,2575,2575);
INSERT INTO stanza VALUES('E506','1','Jesus lives! Thy terrors now<br/>Can, O Death, no more apall us;<br/>Jesus lives! By this we know<br/>Thou, O grave, canst not enthrall us.<br/>Hallelujah!<br/>',NULL,2576,2576);
INSERT INTO stanza VALUES('E506','2','Jesus lives! Henceforth is death<br/>But the gate of Life immortal;<br/>This shall calm our trembling breath,<br/>When we pass its gloomy portal.<br/>Hallelujah!<br/>',NULL,2577,2577);
INSERT INTO stanza VALUES('E506','3','Jesus lives! For us He died;<br/>Then alone to Jesus living,<br/>Pure in heart may we abide,<br/>Glory to our Savior giving.<br/>Hallelujah!<br/>',NULL,2578,2578);
INSERT INTO stanza VALUES('E506','4','Jesus lives! Our hearts know well<br/>Naught from us His love shall server;<br/>Tear us from His keeping ever.<br/>Hallelujah!<br/>',NULL,2579,2579);
INSERT INTO stanza VALUES('E506','5','Jesus lives! To Him the Throne<br/>Over all the world is given;<br/>We, in spirit with Him one<br/>Rest and reign with Him in heaven.<br/>Hallelujah!<br/>',NULL,2580,2580);
INSERT INTO stanza VALUES('E507','1','Once far from God and dead in sin,<br/>No light my heart could see;<br/>But in God''s Word the light I found,<br/>Now Christ liveth in me.<br/>',NULL,2581,2581);
INSERT INTO stanza VALUES('E507','chorus','Christ liveth in me,<br/>Christ liveth in me;<br/>Oh! What a salvation this,<br/>That Christ liveth in me.<br/>',NULL,2582,2582);
INSERT INTO stanza VALUES('E507','2','As rays of light from yonder sun,<br/>The flow''rs of earth set free,<br/>So life and light and love come forth<br/>From Christ living in me.<br/>',NULL,2583,2583);
INSERT INTO stanza VALUES('E507','3','As lives the flow''r within the seed,<br/>As in the cone the tree,<br/>So, praise the Christ of truth and grace,<br/>His Spirit dwelleth in me.<br/>',NULL,2584,2584);
INSERT INTO stanza VALUES('E507','4','With longing all my heart is filled,<br/>That like Him I may be,<br/>As on the wondrous thought I dwell<br/>That Christ liveth in me.<br/>',NULL,2585,2585);
INSERT INTO stanza VALUES('E508','1','Made free! Made free! O captive!<br/>Bound by the law of sin,<br/>The law of life in Spirit<br/>Will quicken you within.<br/>And counting on the Spirit,<br/>His life shall now control<br/>The members of your body,<br/>The portals of your soul.<br/>',NULL,2586,2586);
INSERT INTO stanza VALUES('E508','2','Made free! Made free in Jesus:<br/>For crucified with Him,<br/>From center to circumf''rence,<br/>He breaks the power of sin.<br/>No longer act in body<br/>As if it had no "law";<br/>His "law of life" must govern<br/>All that ran wild before.<br/>',NULL,2587,2587);
INSERT INTO stanza VALUES('E508','3','Made free! Made free in Jesus:<br/>Deep planted in His death,<br/>He liberates His life pow''r,<br/>And breathes His Spirit''s breath.<br/>Then waxing strong in spirit,<br/>With force of quickening life;<br/>The soul and body governed,<br/>Its members cease from strife!<br/>',NULL,2588,2588);
INSERT INTO stanza VALUES('E508','4','Made free! Made free in Jesus:<br/>Joined to the Risen One,<br/>By conflict prayer you triumph,<br/>And claim His victory won.<br/>Freed with His glorious freedom,<br/>Above the darkness rife;<br/>For now the law of sin and death<br/>Is conquered by His life.<br/>',NULL,2589,2589);
INSERT INTO stanza VALUES('E509','1','A flowing river and a tree,<br/>Eden''s outstanding features are,<br/>Man to supply with food and drink<br/>That he may live fore''er.<br/>',NULL,2590,2590);
INSERT INTO stanza VALUES('E509','chorus','God is in Christ to be my supply,<br/>God as the Spirit nourisheth me;<br/>If upon Christ in spirit I feed,<br/>Filled with His life I''ll be.<br/>',NULL,2591,2591);
INSERT INTO stanza VALUES('E509','2','The tree the glorious Christ does show,<br/>As living food to man supplied,<br/>That he God''s riches may enjoy,<br/>Thus to be satisfied.<br/>',NULL,2592,2592);
INSERT INTO stanza VALUES('E509','3','The river does the Spirit show,<br/>Coming man''s spirit to supply,<br/>That with God''s riches he be filled,<br/>Holy to be thereby.<br/>',NULL,2593,2593);
INSERT INTO stanza VALUES('E509','4','The Christ of glory is my life,<br/>He as the Spirit lives in mine,<br/>That I with God be fully blent<br/>And in His image shine.<br/>',NULL,2594,2594);
INSERT INTO stanza VALUES('E509','5','I would exalt this glorious Christ,<br/>Ever the Spirit I''d obey,<br/>Making His glory fully known,<br/>Filled with His grace for aye.<br/>',NULL,2595,2595);
INSERT INTO stanza VALUES('E510','1','I''ve found the One of peerless worth.<br/>My heart doth sing for joy;<br/>And sing I must, for Christ I have:<br/>Oh, what a Christ have I!<br/>',NULL,2596,2596);
INSERT INTO stanza VALUES('E510','2','My Christ, He is the Lamb of God,<br/>Who full salvation brings;<br/>He is the Sun of Righteousness,<br/>With healing in His wings.<br/>',NULL,2597,2597);
INSERT INTO stanza VALUES('E510','3','My Christ, He is the Tree of Life<br/>With fruit abundant, sweet;<br/>My hunger He doth satisfy;<br/>Of Him I daily eat.<br/>',NULL,2598,2598);
INSERT INTO stanza VALUES('E510','4','My Christ, He is the smitten Rock<br/>Whence living waters burst;<br/>He is the fountain in my heart<br/>Which quenches all my thirst.<br/>',NULL,2599,2599);
INSERT INTO stanza VALUES('E510','5','Christ is my life, my light my way,<br/>My comfort and my health,<br/>My peace, my rest, my joy, my hope,<br/>My glory and my wealth.<br/>',NULL,2600,2600);
INSERT INTO stanza VALUES('E510','6','Christ is my wisdom and my pow''r,<br/>My boast and righteousness,<br/>My vict''ry and redemption sure,<br/>My truth and holiness.<br/>',NULL,2601,2601);
INSERT INTO stanza VALUES('E510','7','Christ is my Savior, Shepherd, Lord,<br/>My Advocate above,<br/>My Counselor, my Father, God,<br/>My Brother, Friend, and Love.<br/>',NULL,2602,2602);
INSERT INTO stanza VALUES('E510','8','Christ is my Captain and my Guard,<br/>My Teacher and my Guide,<br/>My Bridegroom, Master and my Head;<br/>In me doth He reside.<br/>',NULL,2603,2603);
INSERT INTO stanza VALUES('E510','9','Christ is my Prophet, Priest, and King;<br/>My Prophet full of sight;<br/>My Priest that stands ''twixt me and God,<br/>My King that rules with might.<br/>',NULL,2604,2604);
INSERT INTO stanza VALUES('E510','10','Christ is the Author of my faith,<br/>And its Perfecter too,<br/>My Mediator, Guarantee,<br/>And faithful Witness true.<br/>',NULL,2605,2605);
INSERT INTO stanza VALUES('E510','11','Christ is my everlasting home,<br/>My all-sufficient land;<br/>My fortress, tower, hiding-place,<br/>And my eternal stand.<br/>',NULL,2606,2606);
INSERT INTO stanza VALUES('E510','12','Christ is my Sabbath and new moon,<br/>My morning and my day,<br/>My age and my eternity<br/>That ne''er will pass away.<br/>',NULL,2607,2607);
INSERT INTO stanza VALUES('E510','13','Christ is my trust and my desire,<br/>In comeliness replete,<br/>My satisfaction and delight,<br/>Who all my need doth meet.<br/>',NULL,2608,2608);
INSERT INTO stanza VALUES('E510','14','My Christ, the all-inclusive One,<br/>My Christ what shall I call?<br/>He is the first, He is the last,<br/>My Christ is All in all.<br/>',NULL,2609,2609);
INSERT INTO stanza VALUES('E510','15','Since such a treasure I possess,<br/>My heart doth sing for joy;<br/>And I must sing, and sing again;<br/>Oh, what a Christ have I!<br/>',NULL,2610,2610);
INSERT INTO stanza VALUES('E511','1','Jesus only is our message,<br/>Jesus all our theme shall be;<br/>We will lift up Jesus ever,<br/>Jesus only will we see.<br/>',NULL,2611,2611);
INSERT INTO stanza VALUES('E511','chorus','Jesus only, Jesus ever,<br/>Jesus all in all we sing,<br/>Savior, Sanctifier, and Healer,<br/>Glorious Lord and coming King.<br/>',NULL,2612,2612);
INSERT INTO stanza VALUES('E511','2','Jesus only is our Savior,<br/>All our guilt He bore away,<br/>He, our righteousness forever,<br/>All our strength from day to day.<br/>',NULL,2613,2613);
INSERT INTO stanza VALUES('E511','3','Jesus is our Sanctifier,<br/>Saving us from self and sin,<br/>And with all His Spirit''s fulness,<br/>Filling all our hearts within.<br/>',NULL,2614,2614);
INSERT INTO stanza VALUES('E511','4','Jesus only is our Healer,<br/>All our sickness He bare,<br/>And His risen life and fulness,<br/>All His members still may share.<br/>',NULL,2615,2615);
INSERT INTO stanza VALUES('E511','5','Jesus only is our Power,<br/>He the gift of Pentecost;<br/>Jesus, breathe Thy pow''r upon us,<br/>Fill us with the Holy Ghost.<br/>',NULL,2616,2616);
INSERT INTO stanza VALUES('E511','6','And for Jesus we are waiting,<br/>List''ning for the Advent Call;<br/>But ''twill still be Jesus only,<br/>Jesus ever, all in all.<br/>',NULL,2617,2617);
INSERT INTO stanza VALUES('E512','1','Jesus, Sun and Shield art Thou,<br/>Sun and Shield forever.<br/>Never canst Thou cease to shine,<br/>Cease to guard us, never.<br/>Cheer our steps as on we go,<br/>Come between us and the foe.<br/>',NULL,2618,2618);
INSERT INTO stanza VALUES('E512','2','Jesus, Bread and Wine art Thou,<br/>Wine and Bread forever.<br/>Never canst Thou cease to feed<br/>Or refresh us, never.<br/>Feed us still on bread divine,<br/>Drink we still of heavenly wine.<br/>',NULL,2619,2619);
INSERT INTO stanza VALUES('E512','3','Jesus, Love and Life art Thou,<br/>Life and Love forever.<br/>Ne''er to quicken shalt Thou cease,<br/>Or to love us, never.<br/>All of life and love we need<br/>Is in Thee, in Thee indeed.<br/>',NULL,2620,2620);
INSERT INTO stanza VALUES('E512','4','Jesus, Peace and Joy art Thou,<br/>Joy and Peace forever.<br/>Joy that fades not, changes not.<br/>Peace that leaves us never.<br/>Joy and Peace we have in Thee<br/>Now and through eternity.<br/>',NULL,2621,2621);
INSERT INTO stanza VALUES('E512','5','Jesus, Song and Strength art Thou,<br/>Strength and Song forever.<br/>Strength that never can decay,<br/>Song that ceaseth never.<br/>Still to us this strength and song,<br/>Through eternal days prolong.<br/>',NULL,2622,2622);
INSERT INTO stanza VALUES('E513','1','Once it was the blessing,<br/>Now it is the Lord;<br/>Once it was the feeling,<br/>Now it is His Word;<br/>Once His gift I wanted,<br/>Now, the Giver own;<br/>Once I sought for healing,<br/>Now Himself alone.<br/>',NULL,2623,2623);
INSERT INTO stanza VALUES('E513','chorus','All in all forever,<br/>Only Christ I''ll sing;<br/>Everything is in Christ,<br/>And Christ is everything.<br/>',NULL,2624,2624);
INSERT INTO stanza VALUES('E513','2','Once ''twas painful trying,<br/>Now ''tis perfect trust;<br/>Once a half salvation,<br/>Now the uttermost;<br/>Once ''twas ceaseless holding,<br/>Now He holds me fast;<br/>Once ''twas constant drifting,<br/>Now my anchor''s cast.<br/>',NULL,2625,2625);
INSERT INTO stanza VALUES('E513','3','Once ''twas busy planning,<br/>Now ''tis trustful prayer;<br/>Once ''twas anxious caring,<br/>Now He has the care;<br/>Once ''twas what I wanted,<br/>Now what Jesus says;<br/>Once ''twas constant asking,<br/>Now ''tis ceaseless praise.<br/>',NULL,2626,2626);
INSERT INTO stanza VALUES('E513','4','Once it was my working,<br/>His it hence shall be;<br/>Once I tried to use Him,<br/>Now He uses me;<br/>Once the pow''r I wanted,<br/>Now the Mighty One;<br/>Once for self I labored,<br/>Now for Him alone.<br/>',NULL,2627,2627);
INSERT INTO stanza VALUES('E513','5','Once I hoped in Jesus,<br/>Now I know He''s mine;<br/>Once my lamps were dying,<br/>Now they brightly shine;<br/>Once for death I waited,<br/>Now His coming hail;<br/>And my hopes are anchored<br/>Safe within the veil.<br/>',NULL,2628,2628);
INSERT INTO stanza VALUES('E514','1','There is One amid all changes<br/>Who standeth ever fast,<br/>One who covers all the future,<br/>The present and the past;<br/>It is Christ the Rock of Ages,<br/>The first and the last,<br/>The first and the last.<br/>',NULL,2629,2629);
INSERT INTO stanza VALUES('E514','chorus','Jesus is the first,<br/>Jesus is the last,<br/>Trust Him for thy future,<br/>Leave with Him the past;<br/>Jesus is the first,<br/>Jesus is the last,<br/>Christ the Rock of Ages,<br/>The first and the last.<br/>',NULL,2630,2630);
INSERT INTO stanza VALUES('E514','2','There is One whose arms upholdeth<br/>This whole creation vast,<br/>Yet He bids us on His bosom<br/>Our cares and sorrows cast;<br/>Let us bring them all to Jesus,<br/>The first and the last,<br/>The first and the last.<br/>',NULL,2631,2631);
INSERT INTO stanza VALUES('E514','3','There is One whose love has kept us<br/>Through every stormy blast,<br/>And His hand will guard and guide us<br/>Till all the storms are past;<br/>Jesus, we will trust Thee ever,<br/>The first and the last,<br/>The first and the last.<br/>',NULL,2632,2632);
INSERT INTO stanza VALUES('E514','4','First and last, O Christ, we crown Thee,<br/>Our fondest love Thou hast;<br/>Lord of lords, before Thy footstool<br/>Let every crown be cast;<br/>Haste the day when all shall crown Thee,<br/>The first and the last,<br/>The first and the last.<br/>',NULL,2633,2633);
INSERT INTO stanza VALUES('E515','1','All is in Christ;<br/>God''s dear Son is Lord of all.<br/>Jesus Christ is life''s perfection,<br/>Perfect love and perfect light.<br/>Son of God, the true reflection<br/>Of the Father''s radiance bright.<br/>All the treasures of God''s riches,<br/>All the secrets of His wisdom,<br/>All in Christ are hid away.<br/>Let His name be praised today!<br/>',NULL,2634,2634);
INSERT INTO stanza VALUES('E515','2','All is in Christ;<br/>God''s dear Son is Lord of all.<br/>Blessings are imparted to us<br/>By the shameful cross He bore.<br/>By His suffering inglorious<br/>We have peace forevermore.<br/>By the Cross we have forgiveness,<br/>Life eternal, endless mercy.<br/>By God''s Son is freely giv''n<br/>Everything in earth and heav''n.<br/>',NULL,2635,2635);
INSERT INTO stanza VALUES('E515','3','All is in Christ;<br/>God''s dear Son is Lord of all.<br/>In me there is naught but weakness,<br/>I am worthless, full of sin,<br/>Stricken by its mortal sickness,<br/>Lacking light and hope within.<br/>Now in Christ I find abundant<br/>Victory and strength and power.<br/>Savior, come and live in me,<br/>Come and make me rich in Thee.<br/>',NULL,2636,2636);
INSERT INTO stanza VALUES('E515','4','All is in Christ;<br/>God''s dear Son is Lord of all.<br/>Savior, pardon my transgressions,<br/>For my love is still so small;<br/>Though I gave all my possessions,<br/>This would profit scarce at all.<br/>''Tis myself that Thou desirest;<br/>So I give myself, dear Master;<br/>No thing hast Thou kept from me-<br/>Nor will I keep aught from Thee.<br/>',NULL,2637,2637);
INSERT INTO stanza VALUES('E515','5','All is in Christ;<br/>Your whole self present to Him.<br/>Vain your quest for lasting pleasure,<br/>Wealth, success, and worldly fame;<br/>Christ alone must be your treasure,<br/>His resource your only claim.<br/>Come, let Him disperse the famine<br/>Of your arid, waste existence.<br/>Let God''s Son, th'' Immortal King<br/>Freely give you everything.<br/>',NULL,2638,2638);
INSERT INTO stanza VALUES('E516','1','Lord of all being, throned afar,<br/>Thy glory flames from sun and star;<br/>Center and light of every sphere,<br/>Yet to each loving heart how near.<br/>',NULL,2639,2639);
INSERT INTO stanza VALUES('E516','2','Sun of our life, Thy quickening ray<br/>Sheds on our path the glow of day;<br/>Star of our hope, Thy softened light<br/>Cheers the long watches of the night.<br/>',NULL,2640,2640);
INSERT INTO stanza VALUES('E516','3','Our midnight is Thy smile withdrawn,<br/>Our noontide is Thy gracious dawn,<br/>Our rainbow arch Thy mercy''s sign;<br/>All, save the clouds of sin, are Thine.<br/>',NULL,2641,2641);
INSERT INTO stanza VALUES('E516','4','Lord of all life, below, above,<br/>Whose light is truth, whose warmth is love,<br/>Before Thy ever-blazing throne<br/>We ask no luster of our own.<br/>',NULL,2642,2642);
INSERT INTO stanza VALUES('E516','5','Grant us Thy truth to make us free,<br/>And kindling hearts that burn for Thee,<br/>Till all Thy living altars claim<br/>One holy light, one heavenly flame.<br/>',NULL,2643,2643);
INSERT INTO stanza VALUES('E517','1','Jesus, my Savior, is all things to me;<br/>Oh, what a wonderful Savior is He,<br/>Guiding, protecting, o''er life''s rolling sea,<br/>Mighty Deliv''rer-Jesus for me.<br/>',NULL,2644,2644);
INSERT INTO stanza VALUES('E517','chorus','Jesus for me,<br/>Jesus for me,<br/>All the time everywhere,<br/>Jesus for me.<br/>',NULL,2645,2645);
INSERT INTO stanza VALUES('E517','2','Jesus in sickness, and Jesus in health,<br/>Jesus in poverty, comfort or wealth;<br/>Sunshine or tempest, whatever it be,<br/>He is my safety-Jesus for me.<br/>',NULL,2646,2646);
INSERT INTO stanza VALUES('E517','3','He is my Refuge, my Rock, and my Tower,<br/>He is my Fortress, my Strength and my Pow''r;<br/>Life everlasting, my Daysman is He,<br/>Blessed Redeemer-Jesus for me.<br/>',NULL,2647,2647);
INSERT INTO stanza VALUES('E517','4','He is my Prophet, my Priest and my King,<br/>He is my Bread of Life, Fountain and Spring;<br/>Bright Sun of Righteousness, Daystar is He,<br/>Horn of Salvation-Jesus for me.<br/>',NULL,2648,2648);
INSERT INTO stanza VALUES('E517','5','Jesus in sorrow, in joy, or in pain,<br/>Jesus my Treasure in loss or in gain;<br/>Constant Companion where''er I may be,<br/>Living or dying-Jesus for me.<br/>',NULL,2649,2649);
INSERT INTO stanza VALUES('E518','1','Whom have I, Lord, in heav''n but Thee?<br/>None but Thee! None but Thee!<br/>And this my song through life shall be:<br/>Christ for me! Christ for me!<br/>He hath for me the serpent trod,<br/>He hath redeemed me "by His blood,"<br/>And reconciled my soul to God:<br/>Christ for me! Christ for me!<br/>',NULL,2650,2650);
INSERT INTO stanza VALUES('E518','2','I envy not the rich their joys:<br/>Christ for me! Christ for me!<br/>I covet not earth''s glitt''ring toys:<br/>Christ for me! Christ for me!<br/>Earth can no lasting bliss bestow,<br/>"Fading" is stamped on all below;<br/>Mine is a joy no end can know:<br/>Christ for me! Christ for me!<br/>',NULL,2651,2651);
INSERT INTO stanza VALUES('E518','3','Though with the poor be cast my lot:<br/>Christ for me! Christ for me!<br/>"He knoweth best," I murmur not:<br/>Christ for me! Christ for me!<br/>Though "vine" and "fig-tree" blight assail,<br/>The "labor of the olive fail,"<br/>And death o''er flock and herd prevail,<br/>Christ for me! Christ for me!<br/>',NULL,2652,2652);
INSERT INTO stanza VALUES('E518','4','Though I am now on hostile ground,<br/>Christ for me! Christ for me!<br/>And sin beset me all around,<br/>Christ for me! Christ for me!<br/>Let earth her fiercest battles wage,<br/>And foes against my soul engage,<br/>Strong in His strength I scorn their rage:<br/>Christ for me! Christ for me!<br/>',NULL,2653,2653);
INSERT INTO stanza VALUES('E518','5','And when my life draws to its close,<br/>Christ for me! Christ for me!<br/>Safe in His arms I shall repose,<br/>Christ for me! Christ for me!<br/>When sharpest pains my frame pervade,<br/>And all the powers of nature fade,<br/>Still will I sing through death''s cold shade;<br/>Christ for me! Christ for me!<br/>',NULL,2654,2654);
INSERT INTO stanza VALUES('E519','1','My heart is fixed, eternal God,<br/>Fixed on Thee, fixed on Thee;<br/>And my immortal choice is made,<br/>Christ for me, Christ for me;<br/>He is my prophet, priest, and king,<br/>Who did for me salvation bring,<br/>And while I''ve breath I mean to sing,<br/>Christ for me, Christ for me.<br/>',NULL,2655,2655);
INSERT INTO stanza VALUES('E519','2','In Him I see the Godhead shine,<br/>Christ for me, Christ for me;<br/>He is the majesty divine,<br/>Christ for me, Christ for me;<br/>The Father''s well-beloved Son,<br/>Co-partner of His royal throne,<br/>Who bore the guilt of man alone,<br/>Christ for me, Christ for me.<br/>',NULL,2656,2656);
INSERT INTO stanza VALUES('E519','3','Let others boast of heaps of gold,<br/>Christ for me, Christ for me;<br/>His riches never can be told,<br/>Christ for me, Christ for me;<br/>Your gold will waste and wear away,<br/>Your honors perish in a day;<br/>My portion never can decay,<br/>Christ for me, Christ for me.<br/>',NULL,2657,2657);
INSERT INTO stanza VALUES('E519','4','In pining sickness, or in health,<br/>Christ for me, Christ for me;<br/>In deepest poverty or wealth,<br/>Christ for me, Christ for me;<br/>And in that all-important day,<br/>When I the summons must obey,<br/>And pass from this dark world away,<br/>Christ for me, Christ for me.<br/>',NULL,2658,2658);
INSERT INTO stanza VALUES('E520','1','None other Lamb, none other Name,<br/>None other hope in heav''n or earth or sea,<br/>None other hiding-place from guilt and shame,<br/>None beside Thee.<br/>',NULL,2659,2659);
INSERT INTO stanza VALUES('E520','2','My faith burns low, my hope burns low;<br/>Only my heart''s desire cries out in me<br/>By the deep thunder of it want and woe,<br/>Cries out to Thee.<br/>',NULL,2660,2660);
INSERT INTO stanza VALUES('E520','3','Lord, Thou art Life, though I be dead;<br/>Love''s fire Thou art, however cold I be;<br/>Nor heaven have I, nor place to lay my head,<br/>Nor home but Thee.<br/>',NULL,2661,2661);
INSERT INTO stanza VALUES('E521','1','I thank Thee, Lord, that Thou hast shown,<br/>And I begin to see,<br/>What Thou canst be to all Thine own,<br/>What they may be to Thee;<br/>If only they will yield Thee all,<br/>And trustingly obey Thy call.<br/>',NULL,2662,2662);
INSERT INTO stanza VALUES('E521','2','How wonderful! I never knew<br/>That I might trust Thee so;<br/>That Thou wouldst be so much to me,<br/>In all the way I go,<br/>That every need Thou wouldst supply,<br/>And all my longings satisfy.<br/>',NULL,2663,2663);
INSERT INTO stanza VALUES('E521','3','I take Thee as my keeper now,<br/>And I commit to Thee<br/>My soul, my way, my works, my cause,<br/>In Thy sole charge to be;<br/>And my deposit, Thou, I know<br/>Wilt guard secure from every foe.<br/>',NULL,2664,2664);
INSERT INTO stanza VALUES('E521','4','I take Thee for my peace, O Lord.<br/>My heart to keep and fill,<br/>Thine own great calm, amid earth''s storms<br/>Shall keep me always still;<br/>And as Thy kingdom doth increase,<br/>So shall Thine ever-deep''ning peace.<br/>',NULL,2665,2665);
INSERT INTO stanza VALUES('E521','5','I take Thee as my wisdom too,<br/>For wisdom''s sum Thou art;<br/>Thou, who dost choose the foolish things,<br/>Set me henceforth apart,<br/>That I may speak and work for Thee<br/>As Thou shalt work and speak in me.<br/>',NULL,2666,2666);
INSERT INTO stanza VALUES('E521','6','I take Thee, Lord, to be my all,<br/>Since all Thou art is mine;<br/>I nothing have, and nothing am;<br/>That nothing, Lord, is Thine.<br/>Thou shalt be everything to me,<br/>In all things my sufficiency.<br/>',NULL,2667,2667);
INSERT INTO stanza VALUES('E522','1','O Christ, in Thee my soul hath found,<br/>And found in Thee alone,<br/>The peace, the joy I sought so long,<br/>The bliss till now unknown.<br/>',NULL,2668,2668);
INSERT INTO stanza VALUES('E522','chorus','Now none but Christ can satisfy,<br/>None other name for me;<br/>There''s love and life and lasting joy,<br/>Lord Jesus, found in Thee.<br/>',NULL,2669,2669);
INSERT INTO stanza VALUES('E522','2','I sighed for rest and happiness,<br/>I yearned for them, not Thee;<br/>But, while I passed my Savior by,<br/>His love laid hold on me.<br/>',NULL,2670,2670);
INSERT INTO stanza VALUES('E522','3','I tried the broken cisterns, Lord,<br/>But, ah, the waters failed!<br/>E''en as I stooped to drink they fled,<br/>And mocked me as I wailed.<br/>',NULL,2671,2671);
INSERT INTO stanza VALUES('E522','4','The pleasures lost I sadly mourned,<br/>But never wept for Thee,<br/>Till grace the sightless eyes received,<br/>Thy loveliness to see.<br/>',NULL,2672,2672);
INSERT INTO stanza VALUES('E523','1','I have come to the Fountain of Life,<br/>A fountain that flows from above;<br/>I have passed from the waters of strife<br/>And come to the Elim of love;<br/>I have drunk of the heavenly well,<br/>In the depths of my being it springs.<br/>No mortal can measure or tell<br/>The gladness the Comforter brings.<br/>',NULL,2673,2673);
INSERT INTO stanza VALUES('E523','chorus','Oh, come to the Fountain of Life,<br/>The fountain that never runs dry;<br/>Oh, drink of the boundless supply,<br/>For Christ is the Fountain of Life.<br/>',NULL,2674,2674);
INSERT INTO stanza VALUES('E523','2','I have come to the Fountain of Blood<br/>That for guilt and uncleanness doth flow;<br/>I have washed in its sin-cleansing flood<br/>And my garments are whiter than snow.<br/>I count not my righteousness mine-<br/>''Tis Jesus that lives in my soul.<br/>I partake of His nature divine,<br/>And in Him I am perfectly whole.<br/>',NULL,2675,2675);
INSERT INTO stanza VALUES('E523','3','I have come to the Fountain of Health,<br/>A boundless and endless supply;<br/>''Tis a secret man''s wisdom or wealth<br/>Can never discover or buy.<br/>But the secret my Lord hath revealed<br/>In the fountain that flows from His side,<br/>In the stripes by whose pain we are healed,<br/>In Himself as He comes to abide.<br/>',NULL,2676,2676);
INSERT INTO stanza VALUES('E523','4','I have come to the Fountain of Joy;<br/>His joy is the strength of my heart.<br/>My delight is unmixed with alloy,<br/>My sunshine can never depart.<br/>The fig tree may wither and die,<br/>Earth''s pleasures and prospects decline;<br/>But my fountains can never be dry-<br/>My portion, my joy is divine.<br/>',NULL,2677,2677);
INSERT INTO stanza VALUES('E524','1','I have found, I have found the way<br/>Which leads to heav''nly rest;<br/>I have found, I have found the peace<br/>Which filled my Savior''s breast.<br/>O friends in the desert past,<br/>Come, join in the prayer and praise;<br/>E''en now He waits our cry,<br/>The Savior who saves always.<br/>',NULL,2678,2678);
INSERT INTO stanza VALUES('E524','2','He hath taken our sins away,<br/>When on Calv''ry''s cross He bled;<br/>The disease of our soul He heals<br/>By His Spirit freely shed;<br/>Though Satan hath pierced us deep,<br/>And great the grace each prays;<br/>The more we prove His might,<br/>The Savior who saves always.<br/>',NULL,2679,2679);
INSERT INTO stanza VALUES('E524','3','Long alas! In the gloom I fought,<br/>''Mid strife of wind and waves;<br/>Jesus seemed only this to me:<br/>A Savior who sometimes saves.<br/>But sweet are the light and calm<br/>That fill my happy days,<br/>Since now I fully trust<br/>The Savior who saves always.<br/>',NULL,2680,2680);
INSERT INTO stanza VALUES('E524','4','O my Sun and my Shield art Thou!<br/>Lead on where Thou hast trod;<br/>My Salvation, my Joy, my Song,<br/>My Brother, and yet my God.<br/>Whate''er then my life betide,<br/>I now can trust and praise;<br/>Each moment Thou wilt save,<br/>O Savior, who sav''st always.<br/>',NULL,2681,2681);
INSERT INTO stanza VALUES('E525','1','Jesus, Fountain of my days,<br/>Well-spring of my heart''s delight,<br/>Brightness of my morning rays,<br/>Solace of my hours of night;<br/>When I see Thee, I arise<br/>To the hope of cloudless skies.<br/>',NULL,2682,2682);
INSERT INTO stanza VALUES('E525','2','Oh, how weary were the years<br/>Ere Thy form to me was known;<br/>Oh, how gloomy were the fears<br/>When I seemed to be alone;<br/>I despaired the storm to brave<br/>Till Thy footprints touched the wave.<br/>',NULL,2683,2683);
INSERT INTO stanza VALUES('E525','3','But Thy presence on the deep<br/>Calmed the pulses of the sea,<br/>And the waters sank to sleep<br/>In the rest of seeing Thee;<br/>And my once rebellious will<br/>Heard the mandate, Peace, be still!<br/>',NULL,2684,2684);
INSERT INTO stanza VALUES('E525','4','Now Thy will and mine are one,<br/>Heart in heart, and hand in hand;<br/>All the clouds have touched the sun,<br/>And the ships have reached the land;<br/>For Thy love has said to me,<br/>No more night! And No more sea!<br/>',NULL,2685,2685);
INSERT INTO stanza VALUES('E526','1','Lord, Thou hast made Thyself to me<br/>A living, bright reality,<br/>More present to faith''s vision keen<br/>Than any earthly object seen;<br/>More dear, more intimately nigh<br/>Than e''en the closest earthly tie.<br/>',NULL,2686,2686);
INSERT INTO stanza VALUES('E526','2','And Thou, blest vision of my soul,<br/>Hast made my broken nature whole;<br/>Hast purified my base desires,<br/>And kindled passion''s holiest fires;<br/>My nature Thou hast lifted up,<br/>And filled me with a glorious hope.<br/>',NULL,2687,2687);
INSERT INTO stanza VALUES('E526','3','Nearer and dearer still to me,<br/>Thou living, loving Savior be;<br/>Brighter the vision of Thy face,<br/>More charming still Thy words of grace;<br/>So, life shall be transformed to love,<br/>Thy grace and mercy more to prove.<br/>',NULL,2688,2688);
INSERT INTO stanza VALUES('E527','1','The Lord''s my Shepherd, I''ll not want;<br/>He make me down to lie<br/>In pastures green; He leadeth me<br/>The quiet waters by.<br/>',NULL,2689,2689);
INSERT INTO stanza VALUES('E527','2','My soul He doth restore again,<br/>And me to walk doth make<br/>Within the paths of righteousness,<br/>E''en for His own name''s sake.<br/>',NULL,2690,2690);
INSERT INTO stanza VALUES('E527','3','Yea, though I walk in death''s dark vale,<br/>Yet will I fear no ill;<br/>For Thou art with me, and Thy rod<br/>And staff me comfort still.<br/>',NULL,2691,2691);
INSERT INTO stanza VALUES('E527','4','My table Thou hast furnished<br/>In presence of my foes;<br/>My head Thou dost with oil anoint,<br/>And my cup overflows.<br/>',NULL,2692,2692);
INSERT INTO stanza VALUES('E527','5','Goodness and mercy all my life<br/>Shall surely follow me,<br/>And in God''s house forevermore<br/>My dwelling-place shall be.<br/>',NULL,2693,2693);
INSERT INTO stanza VALUES('E528','1','The King of love my Shepherd is,<br/>Whose goodness faileth never;<br/>I nothing lack if I am His,<br/>And He is mine forever.<br/>',NULL,2694,2694);
INSERT INTO stanza VALUES('E528','2','Where streams of living water flow<br/>My ransomed soul He leadeth,<br/>And, where the verdant pastures grow,<br/>With food celestial feedeth.<br/>',NULL,2695,2695);
INSERT INTO stanza VALUES('E528','3','Perverse and foolish oft I strayed,<br/>But yet in love He sought me,<br/>And on His shoulder gently laid,<br/>And home rejoicing brought me.<br/>',NULL,2696,2696);
INSERT INTO stanza VALUES('E528','4','In death''s dark vale I fear no ill<br/>With Thee, dear Lord, beside me;<br/>Thy rod and staff my comfort still,<br/>Thy Cross before to guide me.<br/>',NULL,2697,2697);
INSERT INTO stanza VALUES('E528','5','Thou spread''st a table in my sight;<br/>Thy unction grace bestoweth;<br/>And oh, what transport of delight<br/>From Thy pure chalice floweth!<br/>',NULL,2698,2698);
INSERT INTO stanza VALUES('E528','6','And so through all the length of days<br/>Thy goodness faileth never;<br/>Good Shepherd, may I sing Thy praise<br/>Within Thy house forever.<br/>',NULL,2699,2699);
INSERT INTO stanza VALUES('E529','1','How tedious and tasteless the hours<br/>When Jesus no longer I see!<br/>Sweet prospects, sweet birds and sweet<br/>flow''rs,<br/>Have all lost their sweetness to me.<br/>The midsummer sun shines but dim,<br/>The fields strive in vain to look gay;<br/>But when I am happy in Him<br/>December''s as pleasant as May.<br/>',NULL,2700,2700);
INSERT INTO stanza VALUES('E529','2','His name yields the richest perfume,<br/>And sweeter than music His voice;<br/>His presence disperses my gloom,<br/>And makes all within me rejoice.<br/>I should, were He always thus nigh,<br/>Have nothing to wish or to fear;<br/>No mortal so happy as I;<br/>My summer would last all the year.<br/>',NULL,2701,2701);
INSERT INTO stanza VALUES('E529','3','Content with beholding His face,<br/>My all to His pleasure resigned;<br/>No changes of season or place,<br/>Would make any change in my mind.<br/>While blessed with a sense of His love,<br/>A palace a toy would appear;<br/>And prisons would palaces prove,<br/>If Jesus would dwell with me there.<br/>',NULL,2702,2702);
INSERT INTO stanza VALUES('E529','4','My Lord, if indeed I am Thine,<br/>If Thou art my sun and my song,<br/>Say, why do I languish and pine?<br/>And why are my winters so long?<br/>Oh, drive these dark clouds from the sky,<br/>Thy soul-cheering presence restore;<br/>Or take me to Thee up on high,<br/>Where winter and clouds are no more.<br/>',NULL,2703,2703);
INSERT INTO stanza VALUES('E530','1','Jesus is all the world to me:<br/>My life, my joy, my all.<br/>He is my strength from day to day;<br/>Without Him I would fall.<br/>When I am sad, to Him I go;<br/>No other one can cheer me so.<br/>When I am sad, He makes me glad;<br/>He''s my Friend.<br/>',NULL,2704,2704);
INSERT INTO stanza VALUES('E530','2','Jesus is all the world to me,<br/>My Friend in trial sore.<br/>I go to Him for blessings, and<br/>He gives them o''er and o''er.<br/>He sends the sunshine and the rain;<br/>He sends the harvest''s golden grain:<br/>Sunshine and rain, harvest of grain-<br/>He''s my Friend.<br/>',NULL,2705,2705);
INSERT INTO stanza VALUES('E530','3','Jesus is all the world to me,<br/>And true to Him I''ll be.<br/>Oh, how could I this Friend deny<br/>When He''s so true to me?<br/>Following Him I know I''m right;<br/>He watches o''er me day and night.<br/>Following Him by day and night,<br/>He''s my Friend.<br/>',NULL,2706,2706);
INSERT INTO stanza VALUES('E530','4','Jesus is all the world to me,<br/>I want no better friend.<br/>I trust Him now; I''ll trust Him when<br/>Life''s fleeting days shall end.<br/>Beautiful life with such a Friend;<br/>Beautiful life that has no end!<br/>Eternal life, eternal joy,<br/>He''s my Friend.<br/>',NULL,2707,2707);
INSERT INTO stanza VALUES('E531','1','Fade, fade each earthly joy;<br/>Jesus is mine.<br/>Break every tender tie;<br/>Jesus is mine.<br/>Dark is the wilderness,<br/>Earth has no resting place,<br/>Jesus alone can bless;<br/>Jesus is mine.<br/>',NULL,2708,2708);
INSERT INTO stanza VALUES('E531','2','Tempt not my soul away;<br/>Jesus is mine.<br/>Here would I ever stay;<br/>Jesus is mine.<br/>Perishing things of clay,<br/>Born but for one brief day,<br/>Pass from my heart away;<br/>Jesus is mine.<br/>',NULL,2709,2709);
INSERT INTO stanza VALUES('E531','3','Farewell, ye dreams of night;<br/>Jesus is mine.<br/>Lost in this dawning bright;<br/>Jesus in mine.<br/>All that my soul has tried<br/>Left but a dismal void;<br/>Jesus has satisfied;<br/>Jesus is mine.<br/>',NULL,2710,2710);
INSERT INTO stanza VALUES('E531','4','Farewell, mortality;<br/>Jesus is mine.<br/>Welcome, eternity;<br/>Jesus is mine.<br/>Welcome, O Loved and Blest,<br/>Welcome, sweet scenes of rest,<br/>Welcome, my Savior''s breast;<br/>Jesus is mine.<br/>',NULL,2711,2711);
INSERT INTO stanza VALUES('E532','1','Thou hidden sources of calm repose,<br/>Thou all-sufficient love divine;<br/>My help and refuge from my foes,<br/>Secure I am, if Thou art mine;<br/>From sin and grief, from guilt and shame,<br/>I hide me, Jesus, in Thy name.<br/>',NULL,2712,2712);
INSERT INTO stanza VALUES('E532','2','Jesus, my All in all Thou art,<br/>My rest in toil, mine ease in pain;<br/>The med''cine of my broken heart<br/>In war, my peace; in loss, my gain;<br/>My smile beneath the tyrant''s frown;<br/>In shame, my glory and my crown.<br/>',NULL,2713,2713);
INSERT INTO stanza VALUES('E532','3','In want, my plentiful supply;<br/>In weakness, mine almighty power;<br/>In bonds, my perfect liberty;<br/>My light in Satan''s darkest hour;<br/>In grief, my joy unspeakable;<br/>My life in death; my Lord, my all.<br/>',NULL,2714,2714);
INSERT INTO stanza VALUES('E533','1','For every sin however deep,<br/>For every path however steep,<br/>For all the weary ones who weep,<br/>Thou art sufficient, Lord.<br/>',NULL,2715,2715);
INSERT INTO stanza VALUES('E533','2','For every trial great or small,<br/>For every care that would appall,<br/>For all the stumbling feet that fall,<br/>Thou art sufficient, Lord.<br/>',NULL,2716,2716);
INSERT INTO stanza VALUES('E533','3','When earthly things bring sweet delight,<br/>When all is well, and skies are bright,<br/>When ease would cloud the heavenly light,<br/>Thou art sufficient, Lord.<br/>',NULL,2717,2717);
INSERT INTO stanza VALUES('E533','4','When sorrow darkens all the day,<br/>When disappointments bar the way,<br/>When hearts are numb and cannot pray,<br/>Thou art sufficient, Lord.<br/>',NULL,2718,2718);
INSERT INTO stanza VALUES('E533','5','Whate''er my circumstances be,<br/>Help me in all Thy hand to see,<br/>So wilt Thou then be unto me,<br/>My all-sufficient Lord.<br/>',NULL,2719,2719);
INSERT INTO stanza VALUES('E534','1','The Savior can lift every burden,<br/>The heavy as well as the light;<br/>His strength is made perfect in weakness,<br/>In Him there is power and might.<br/>',NULL,2720,2720);
INSERT INTO stanza VALUES('E534','chorus','The Savior can solve every problem,<br/>The tangles of life can undo;<br/>There is nothing too hard for Jesus,<br/>There is nothing that He cannot do.<br/>',NULL,2721,2721);
INSERT INTO stanza VALUES('E534','2','The Savior can bear every sorrow,<br/>In Him there is comfort and rest;<br/>No matter how great the affliction,<br/>He only permits what is best.<br/>',NULL,2722,2722);
INSERT INTO stanza VALUES('E534','3','The Savior can strengthen the weary,<br/>His grace is sufficient for all;<br/>He knows every step of the pathway<br/>And listens to hear when we call.<br/>',NULL,2723,2723);
INSERT INTO stanza VALUES('E534','4','The Savior can break sin''s dominion.<br/>The vict''ry He won long ago;<br/>In Him there is freedom from bondage,<br/>He''s able to conquer the foe.<br/>',NULL,2724,2724);
INSERT INTO stanza VALUES('E534','5','The Savior can satisfy fully<br/>The heart that the world cannot fill;<br/>His Spirit will sanctify wholly<br/>The soul that is yielded and still.<br/>',NULL,2725,2725);
INSERT INTO stanza VALUES('E535','1','All things are possible to him<br/>That can in Jesus'' name believe;<br/>Lord, I no more Thy name blaspheme,<br/>Thy truth I lovingly receive.<br/>I can, I do believe in Thee;<br/>All things are possible to me.<br/>',NULL,2726,2726);
INSERT INTO stanza VALUES('E535','2','''Twas most impossible for all<br/>That here sin''s reign in me should cease;<br/>Yet shall it be, I know it shall;<br/>Jesus, I trust Thy faithfulness.<br/>If nothing is too hard for Thee,<br/>All things are possible to me.<br/>',NULL,2727,2727);
INSERT INTO stanza VALUES('E535','3','Though earth and hell the Word gainsay,<br/>The Word of God shall never fail;<br/>The Lord can break sin''s iron sway;<br/>''Tis certain, though impossible.<br/>The thing impossible shall be,<br/>All things are possible to me.<br/>',NULL,2728,2728);
INSERT INTO stanza VALUES('E535','4','All things are possible to God;<br/>To Christ, the power of God in man;<br/>To me when I am all renewed,<br/>In Christ am fully formed again,<br/>And from the reign of sin set free,<br/>All things are possible to me.<br/>',NULL,2729,2729);
INSERT INTO stanza VALUES('E535','5','All things are possible to God;<br/>To Christ, the power of God in me;<br/>Now shed Thy mighty Self abroad,<br/>Let me no longer live, but Thee;<br/>Give me this hour in Thee to prove<br/>The sweet omnipotence of love.<br/>',NULL,2730,2730);
INSERT INTO stanza VALUES('E536','1','Objective and subjective Christ is to us,<br/>In heaven He''s pleading objectively thus;<br/>Subjectively now in His members He lives<br/>And inwardly to them His being He gives.<br/>',NULL,2731,2731);
INSERT INTO stanza VALUES('E536','2','In heaven He sits at the right hand of God,<br/>Where as the High Priest He presented His blood;<br/>Our Advocate, bearing our burdens above,<br/>Our Surety, He careth for us in His love.<br/>',NULL,2732,2732);
INSERT INTO stanza VALUES('E536','3','He now is the Spirit, our spirit within;<br/>He''s there as our life, all things bringing with Him;<br/>He''s there as our strength and our grace every hour,<br/>Our Paraclete in us, sustaining with pow''r.<br/>',NULL,2733,2733);
INSERT INTO stanza VALUES('E536','4','In heaven for us He''s the glorified man,<br/>The Forerunner entered, fulfilling God''s plan;<br/>Man into God bringing and making him one<br/>With God in the heav''nlies, in Him as the Son.<br/>',NULL,2734,2734);
INSERT INTO stanza VALUES('E536','5','In us all the fulness of God dwells in Him;<br/>As Spirit He brings God Himself thus within,<br/>Revealing and making God real unto us,<br/>God one with us building in life glorious.<br/>',NULL,2735,2735);
INSERT INTO stanza VALUES('E536','6','The Savior ascending in heaven now dwells,<br/>And soon He''s returning for us His Word tells;<br/>Deliverer indwelling, He now in us lives,<br/>And soon will transfigure, His glory to give.<br/>',NULL,2736,2736);
INSERT INTO stanza VALUES('E536','7','The day soon is coming when heaven and earth<br/>Will mingle in one in that city of worth;<br/>Objective and subjective will in that day<br/>Be mingled within us in glory for aye.<br/>',NULL,2737,2737);
INSERT INTO stanza VALUES('E537','1','Christ to me is so subjective,<br/>In my spirit dwelleth He;<br/>Christ to me is all-inclusive,<br/>As the Spirit one with me.<br/>',NULL,2738,2738);
INSERT INTO stanza VALUES('E537','chorus','So subjective is my Christ to me!<br/>Real in me, and rich and sweet!<br/>All-inclusive is my Christ to me!<br/>All my needs He fully meets.<br/>',NULL,2739,2739);
INSERT INTO stanza VALUES('E537','2','Christ to me is so subjective,<br/>Life imparting all the way;<br/>As the Spirit He revives me<br/>And refreshes day by day.<br/>',NULL,2740,2740);
INSERT INTO stanza VALUES('E537','3','Christ to me is so subjective,<br/>All my being He transforms;<br/>By the mind and will renewing<br/>To His image He conforms.<br/>',NULL,2741,2741);
INSERT INTO stanza VALUES('E537','4','Christ to me is so subjective,<br/>Liberating pow''r is He,<br/>By the law of life and power<br/>As the Spirit setting free.<br/>',NULL,2742,2742);
INSERT INTO stanza VALUES('E537','5','Christ to me is so subjective,<br/>Regulating all the day;<br/>He corrects and rules and guides me,<br/>And adjusts in every way.<br/>',NULL,2743,2743);
INSERT INTO stanza VALUES('E537','6','Christ to me is so subjective,<br/>All my thirst He satisfies;<br/>With His riches He supplies me,<br/>Thus God''s fulness testifies.<br/>',NULL,2744,2744);
INSERT INTO stanza VALUES('E538','1','It is God''s intent and pleasure<br/>To have Christ revealed in me,<br/>Nothing outward as religion,<br/>But His Christ within to be.<br/>',NULL,2745,2745);
INSERT INTO stanza VALUES('E538','chorus','It is God''s intent and pleasure<br/>That His Christ be wrought in me;<br/>Nothing outwardly performing,<br/>But His Christ my all to be.<br/>',NULL,2746,2746);
INSERT INTO stanza VALUES('E538','2','It is God''s intent and pleasure<br/>That His Christ may live in me;<br/>Nothing as an outward practice,<br/>But Christ working inwardly.<br/>',NULL,2747,2747);
INSERT INTO stanza VALUES('E538','3','It is God''s intent and pleasure<br/>That His Christ be formed in me;<br/>Not the outward forms to follow,<br/>But Christ growing inwardly.<br/>',NULL,2748,2748);
INSERT INTO stanza VALUES('E538','4','It is God''s intent and pleasure<br/>That His Christ make home in me;<br/>Not just outwardly to serve Him,<br/>But Christ dwelling inwardly.<br/>',NULL,2749,2749);
INSERT INTO stanza VALUES('E538','5','It is God''s intent and pleasure<br/>That His Christ my hope may be;<br/>It is not objective glory,<br/>But ''tis Christ subjectively.<br/>',NULL,2750,2750);
INSERT INTO stanza VALUES('E538','6','It is God''s intent and pleasure<br/>That His Christ be all in me;<br/>Nothing outwardly possessing,<br/>But His Christ eternally.<br/>',NULL,2751,2751);
INSERT INTO stanza VALUES('E539','1','O Lord, Thou art in me as life<br/>And everything to me!<br/>Subjective and available,<br/>Thus I experience Thee.<br/>',NULL,2752,2752);
INSERT INTO stanza VALUES('E539','chorus','O Lord, Thou art the Spirit!<br/>How dear and near to me!<br/>How I enjoy Thy marvelous<br/>Availability!<br/>',NULL,2753,2753);
INSERT INTO stanza VALUES('E539','2','To all my needs both great and small<br/>Thou art the rich supply;<br/>So ready and sufficient too<br/>For me now to apply.<br/>',NULL,2754,2754);
INSERT INTO stanza VALUES('E539','3','Thy sweet anointing with Thy might<br/>In weakness doth sustain;<br/>By Thy supply of energy<br/>My strength Thou dost maintain.<br/>',NULL,2755,2755);
INSERT INTO stanza VALUES('E539','4','Thy law of life in heart and mind<br/>My conduct regulates;<br/>The wealth of Thy reality<br/>My being saturates.<br/>',NULL,2756,2756);
INSERT INTO stanza VALUES('E539','5','O Thou art ever one with me,<br/>Unrivaled unity!<br/>One spirit with me all the time<br/>For all eternity!<br/>',NULL,2757,2757);
INSERT INTO stanza VALUES('E540','1','What release the Savior gave me!<br/>Christ indeed has set me free!<br/>All the pow''r of sin is broken,<br/>All death''s sting is passed from me!<br/>',NULL,2758,2758);
INSERT INTO stanza VALUES('E540','chorus','Christ has made me more than conqu''ror,<br/>By His mighty victory,<br/>Now His resurrection power<br/>From my spirit strengthens me!<br/>',NULL,2759,2759);
INSERT INTO stanza VALUES('E540','2','From the law Christ has delivered,<br/>To its claims I''m ever dead;<br/>Nevermore the law shall bind me,<br/>But by grace I''ll live instead.<br/>',NULL,2760,2760);
INSERT INTO stanza VALUES('E540','3','Christ has sin condemned at Calv''ry<br/>And its power done away;<br/>Now it has no ground within me,<br/>I am freed from all its sway.<br/>',NULL,2761,2761);
INSERT INTO stanza VALUES('E540','4','Death by Him has been abolished,<br/>Incorrupted life is shown;<br/>Death''s enthralling bonds are broken,<br/>Resurrection life is known.<br/>',NULL,2762,2762);
INSERT INTO stanza VALUES('E540','5','Christ through death has crushed the devil,<br/>World and demons by His might,<br/>From the pow''r of darkness brought me<br/>To the realm of life and light.<br/>',NULL,2763,2763);
INSERT INTO stanza VALUES('E540','6','All-sufficient grace He giveth,<br/>With His pow''r He covers me,<br/>Makes me glory in my weakness<br/>And in weakness strengthens me.<br/>',NULL,2764,2764);
INSERT INTO stanza VALUES('E541','1','Not the law of letters,<br/>But the Christ of life<br/>God desires to give us,<br/>Saving us from strife;<br/>It is not some doctrine,<br/>But ''tis Christ Himself<br/>Who alone releases<br/>From our sinful self.<br/>',NULL,2765,2765);
INSERT INTO stanza VALUES('E541','2','Any kind of teaching,<br/>Any kind of form,<br/>Cannot quicken spirits<br/>Or our souls transform;<br/>It is Christ as Spirit<br/>Gives us life divine,<br/>Thus thru us to live the<br/>Life of God''s design.<br/>',NULL,2766,2766);
INSERT INTO stanza VALUES('E541','3','Not philosophy nor<br/>Any element<br/>Can to Christ conform us<br/>As His complement;<br/>But ''tis Christ Himself who<br/>All our nature takes<br/>And in resurrection<br/>Us His members makes.<br/>',NULL,2767,2767);
INSERT INTO stanza VALUES('E541','4','Not religion, even<br/>Christianity,<br/>Can fulfill God''s purpose<br/>Or economy;<br/>But ''tis Christ within us<br/>As our all in all<br/>Satisfies God''s wishes,<br/>And His plan withal.<br/>',NULL,2768,2768);
INSERT INTO stanza VALUES('E541','5','All the gifts we''re given<br/>By the Lord in grace,<br/>All the different functions<br/>Cannot Christ replace.<br/>Only Christ Himself must<br/>Be our all in all!<br/>Only Christ Himself in<br/>All things, great or small!<br/>',NULL,2769,2769);
INSERT INTO stanza VALUES('E542','1','O the riches of my Savior,<br/>So unsearchable, immense;<br/>All the fulness of the Godhead<br/>I may now experience.<br/>',NULL,2770,2770);
INSERT INTO stanza VALUES('E542','chorus','O the riches, O the riches,<br/>Christ my Savior has for me!<br/>How unsearchable their measure,<br/>Yet my full reality!<br/>',NULL,2771,2771);
INSERT INTO stanza VALUES('E542','2','O the riches of my Savior,<br/>All-embracing: life and light,<br/>Wisdom, power, healing, comfort,<br/>Treasures rich of God''s delight;<br/>',NULL,2772,2772);
INSERT INTO stanza VALUES('E542','3','God''s redemption, full salvation,<br/>And His resurrection pow''r,<br/>Sanctifying, glorifying,<br/>All transcending every hour!<br/>',NULL,2773,2773);
INSERT INTO stanza VALUES('E542','4','O the riches of my Savior-<br/>Nothing less than God as all!<br/>All His person and possessions,<br/>Now my spirit doth enthrall.<br/>',NULL,2774,2774);
INSERT INTO stanza VALUES('E542','5','O the riches of my Savior!<br/>Who can know their breadth and length,<br/>Or their depth and height unmeasured,<br/>Yet they are my joy and strength.<br/>',NULL,2775,2775);
INSERT INTO stanza VALUES('E542','6','May I know these boundless riches,<br/>Christ experienced in full;<br/>And with others may I share them<br/>In their content bountiful.<br/>',NULL,2776,2776);
INSERT INTO stanza VALUES('E543','1','I give my heart to Thee,<br/>O Jesus most desired;<br/>And heart for heart the gift shall be,<br/>For Thou my heart hast fired.<br/>',NULL,2777,2777);
INSERT INTO stanza VALUES('E543','2','Thou hearts alone wouldst move,<br/>Thou only hearts dost love;<br/>I would love Thee as Thou lov''st me,<br/>O Jesus most desired.<br/>',NULL,2778,2778);
INSERT INTO stanza VALUES('E543','3','What off''ring can I make,<br/>Dear Lord, to love like Thine;<br/>That Thou, the Word, didst stoop to take<br/>A human form like mine?<br/>',NULL,2779,2779);
INSERT INTO stanza VALUES('E543','4','"Give Me thy heart, my son":<br/>Lord, Thou my heart hast won;<br/>I would love Thee as Thou lov''st me,<br/>O Jesus most desired.<br/>',NULL,2780,2780);
INSERT INTO stanza VALUES('E543','5','Thy heart is opened wide,<br/>Its offered love most free,<br/>That heart to heart I may abide,<br/>And hide myself in Thee.<br/>',NULL,2781,2781);
INSERT INTO stanza VALUES('E543','6','Ah, how Thy love doth burn,<br/>Till I that love return!<br/>I would love Thee as Thou lov''st me,<br/>O Jesus most desired.<br/>',NULL,2782,2782);
INSERT INTO stanza VALUES('E543','7','Here finds my heart its rest,<br/>Repose that knows no shock,<br/>The strength of love that keeps it blest<br/>In Thee, the riven Rock.<br/>',NULL,2783,2783);
INSERT INTO stanza VALUES('E543','8','My heart, as girt around,<br/>Her citadel hath found;<br/>I would love Thee as Thou lov''st me,<br/>O Jesus most desired.<br/>',NULL,2784,2784);
INSERT INTO stanza VALUES('E544','1','Lord Jesus, I love Thee, I know Thou art mine;<br/>For Thee all the pleasures of sin I resign;<br/>My gracious Redeemer, my Savior art Thou,<br/>If ever I love Thee, Lord Jesus, ''tis now.<br/>',NULL,2785,2785);
INSERT INTO stanza VALUES('E544','2','I love Thee, because Thou hast first loved me,<br/>And purchased my pardon on Calvary''s tree;<br/>I love Thee for wearing the thorns on Thy brow,<br/>If ever I loved Thee, Lord Jesus, ''tis now.<br/>',NULL,2786,2786);
INSERT INTO stanza VALUES('E544','3','I''ll love Thee in life, I will love Thee in death,<br/>And praise Thee as long as Thou lendest me breath;<br/>And say when the death-dew lies cold on my brow,<br/>If ever I loved Thee, Lord Jesus, ''tis now.<br/>',NULL,2787,2787);
INSERT INTO stanza VALUES('E544','4','In ages eternal of endless delight<br/>I''ll ever adore Thee in glory so bright;<br/>I''ll sing with the glittering crown on my brow,<br/>If ever I loved Thee, Lord Jesus, ''tis now.<br/>',NULL,2788,2788);
INSERT INTO stanza VALUES('E545','1','When this passing world is done,<br/>When has sunk yon glaring sun,<br/>When we stand with Christ on high,<br/>Looking o''er life''s history;<br/>Then, Lord, shall I fully know,<br/>Not till then, how much I owe.<br/>',NULL,2789,2789);
INSERT INTO stanza VALUES('E545','2','When I stand before the throne<br/>Dressed in beauty not my own,<br/>When I see Thee as Thou art,<br/>Love Thee with unsinning heart;<br/>Then, Lord, shall I fully know,<br/>Not till then, how much I owe.<br/>',NULL,2790,2790);
INSERT INTO stanza VALUES('E545','3','E''en on earth, as through a glass<br/>Darkly, let Thy glory pass;<br/>Make forgiveness feel so sweet;<br/>Make Thy Spirit''s help so meet:<br/>E''en on earth, Lord, make me know<br/>Something of how much I owe.<br/>',NULL,2791,2791);
INSERT INTO stanza VALUES('E546','1','I love my Lord, but with no love of mine,<br/>For I have none to give;<br/>I love my Lord, but all the love is Thine,<br/>For by Thy love I live.<br/>I am as nothing, and rejoice to be<br/>Emptied, and lost, and swallowed up in Thee.<br/>',NULL,2792,2792);
INSERT INTO stanza VALUES('E546','2','Thou, Lord, alone, art all Thy children need,<br/>And there is none beside;<br/>From Thee the streams of blessedness proceed,<br/>In Thee the bless''d abide.<br/>Fountain of life, and all-abounding grace,<br/>Our source, our center, and our dwelling place.<br/>',NULL,2793,2793);
INSERT INTO stanza VALUES('E547','1','Something every heart is loving:<br/>If not Jesus, none can rest;<br/>Lord, my heart to Thee is given;<br/>Take it, for it loves Thee best.<br/>',NULL,2794,2794);
INSERT INTO stanza VALUES('E547','2','Thus I cast the world behind me;<br/>Jesus most beloved shall be;<br/>Beauteous more than all things beauteous,<br/>He alone is joy to me.<br/>',NULL,2795,2795);
INSERT INTO stanza VALUES('E547','3','Bright with all eternal radiance<br/>Is the glory of Thy face;<br/>Thou art loving, sweet, and tender,<br/>Full of pity, full of grace.<br/>',NULL,2796,2796);
INSERT INTO stanza VALUES('E547','4','When I hated, Thou didst love me,<br/>Shedd''st for me Thy precious blood;<br/>Still Thou lovest, lovest ever,<br/>Shall I not love Thee, my God?<br/>',NULL,2797,2797);
INSERT INTO stanza VALUES('E547','5','Keep my heart still faithful to Thee,<br/>That my earthly life may be<br/>But a shadow to that glory<br/>Of my hidden life in Thee.<br/>',NULL,2798,2798);
INSERT INTO stanza VALUES('E548','1','Earthen vessel I was made,<br/>Christ in me the treasure laid;<br/>His container I must be,<br/>As the content He in me.<br/>',NULL,2799,2799);
INSERT INTO stanza VALUES('E548','2','In His image I was made,<br/>Fit that Christ should all pervade;<br/>Thus the vessel God did form<br/>With the content uniform.<br/>',NULL,2800,2800);
INSERT INTO stanza VALUES('E548','3','In my spirit He remains,<br/>With His power He sustains;<br/>As the Spirit one with me,<br/>He is my reality.<br/>',NULL,2801,2801);
INSERT INTO stanza VALUES('E548','4','Moving in me day by day,<br/>Mingling with me all the way,<br/>All my steps He regulates,<br/>Every part He saturates.<br/>',NULL,2802,2802);
INSERT INTO stanza VALUES('E548','5','Him expressing from within,<br/>Making Him to others seen,<br/>I transparent have to be<br/>That He may be shown thru me.<br/>',NULL,2803,2803);
INSERT INTO stanza VALUES('E548','6','Transformation is my need,<br/>To be broken more indeed,<br/>That the clay may change in form,<br/>To the treasure to conform.<br/>',NULL,2804,2804);
INSERT INTO stanza VALUES('E549','1','Enter the veil and go without the camp,<br/>Taste heaven''s sweetness, thus the earth<br/>forsake;<br/>If by the Holiest I am satisfied,<br/>How can I of earth''s vanities partake?<br/>',NULL,2805,2805);
INSERT INTO stanza VALUES('E549','2','Enter the veil and go without the camp,<br/>By heaven''s presence will the earth depart;<br/>If heaven''s glory doth my spirit charm,<br/>How can earth''s happiness possess my heart?<br/>',NULL,2806,2806);
INSERT INTO stanza VALUES('E549','3','Enter the veil, behold the glorious Christ,<br/>Go out the camp to Jesus, let Him lead;<br/>If throne and crown my spirit here enthrall,<br/>Manger and cross cannot my steps impede.<br/>',NULL,2807,2807);
INSERT INTO stanza VALUES('E549','4','Enter the veil for resurrection pow''r,<br/>Go out the camp to bear the cross and woe,<br/>If I His radiant face in heaven see,<br/>His footsteps I will follow here below.<br/>',NULL,2808,2808);
INSERT INTO stanza VALUES('E549','5','Enter the veil, on heaven''s fatness feast,<br/>Without the camp, in hardship persevere;<br/>Though earthly trials sorely pain my heart,<br/>Heaven''s communion doth my spirit cheer.<br/>',NULL,2809,2809);
INSERT INTO stanza VALUES('E549','6','Enter the veil, Christ''s riches there enjoy,<br/>Without the camp, the needs of men supply;<br/>The life of heaven living out thru me<br/>The souls of earth will bless and satisfy.<br/>',NULL,2810,2810);
INSERT INTO stanza VALUES('E549','7','Enter the veil till it exists no more,<br/>Go out the camp till all the camps are gone;<br/>Until the heavens and the earth unite,<br/>Till God and man together dwell in one.<br/>',NULL,2811,2811);
INSERT INTO stanza VALUES('E550','1','Through Thy precious body broken-<br/>Inside the veil.<br/>Oh! What words to sinners spoken-<br/>Inside the veil.<br/>Precious as the blood that brought us;<br/>Perfect, as the love that sought us;<br/>Holy, as the Lamb that brought us-<br/>Inside the veil.<br/>',NULL,2812,2812);
INSERT INTO stanza VALUES('E550','2','When we see Thy love unshaken-<br/>Outside the camp.<br/>Scorned by man, by God forsaken-<br/>Outside the camp.<br/>Thy loved cross alone can charm us;<br/>Shame need now no more alarm us;<br/>Glad we follow, nought can harm us-<br/>Outside the camp.<br/>',NULL,2813,2813);
INSERT INTO stanza VALUES('E550','3','Lamb of God, through Thee we enter-<br/>Inside the veil.<br/>Cleansed by Thee, we boldly venture-<br/>Inside the veil.<br/>Not a stain; a new creation:<br/>Ours is such a full salvation;<br/>Low we bow in adoration-<br/>Inside the veil.<br/>',NULL,2814,2814);
INSERT INTO stanza VALUES('E550','4','Unto Thee, the homeless stranger-<br/>Outside the camp.<br/>Forth we hasten, fear no danger-<br/>Outside the camp.<br/>Thy reproach, far richer treasure<br/>Than all Egypt''s boasted pleasure;<br/>Drawn by love that know no measure-<br/>Outside the camp.<br/>',NULL,2815,2815);
INSERT INTO stanza VALUES('E550','5','Soon Thy saints shall all be gathered-<br/>Inside the veil.<br/>All with Thee-no more be scattered-<br/>Inside the veil.<br/>Nought from Thee, our hearts shall sever;<br/>We shall see Thee; grieve Thee never;<br/>"Praise the Lamb!" shall sound forever-<br/>Inside the veil.<br/>',NULL,2816,2816);
INSERT INTO stanza VALUES('E551','1','I''ve believed the true report,<br/>Hallelujah to the Lamb!<br/>I have passed the outer court,<br/>O glory be to God!<br/>I am all on Jesus'' side,<br/>On the altar sanctified,<br/>To the world and sin I''ve died,<br/>Hallelujah to the Lamb!<br/>',NULL,2817,2817);
INSERT INTO stanza VALUES('E551','chorus','Hallelujah! Hallelujah!<br/>I have passed the riven veil,<br/>Here the glories never fail,<br/>Hallelujah! Hallelujah!<br/>I am living in the presence of the King.<br/>',NULL,2818,2818);
INSERT INTO stanza VALUES('E551','2','I''m a king and priest to God,<br/>Hallelujah to the Lamb!<br/>By the cleansing of the blood,<br/>O glory be to God!<br/>By the Spirit''s pow''r and light,<br/>I am living day and night,<br/>In the holiest place so bright,<br/>Hallelujah to the Lamb!<br/>',NULL,2819,2819);
INSERT INTO stanza VALUES('E551','3','I have passed the outer veil,<br/>Hallelujah to the Lamb!<br/>Which did once God''s light conceal,<br/>O glory be to God!<br/>But the blood has brought me in<br/>To God''s holiness so clean,<br/>Where there''s death to self and sin,<br/>Hallelujah to the Lamb!<br/>',NULL,2820,2820);
INSERT INTO stanza VALUES('E551','4','I''m within the holiest pale,<br/>Hallelujah to the Lamb!<br/>I have passed the inner veil,<br/>O glory be to God!<br/>I am sanctified to God<br/>By the power of the blood,<br/>Now the Lord is my abode,<br/>Hallelujah to the Lamb!<br/>',NULL,2821,2821);
INSERT INTO stanza VALUES('E552','1','Marvel not that Christ in glory<br/>All my inmost heart hath won;<br/>Not a star to cheer my darkness,<br/>But a light beyond the sun,<br/>All below lies dark and shadowed,<br/>Nothing here to claim my heart,<br/>Save the lonely track of sorrow<br/>Where of old He walked apart.<br/>',NULL,2822,2822);
INSERT INTO stanza VALUES('E552','2','Other in the earthly sunshine<br/>Wearily may journey on,<br/>I have seen a light from heaven<br/>Past the brightness of the sun-<br/>Light that knows no cloud, no waning,<br/>Light wherein I see His face,<br/>All His love''s uncounted treasures,<br/>All the riches of His grace:<br/>',NULL,2823,2823);
INSERT INTO stanza VALUES('E552','3','All the wonders of His glory,<br/>Deeper wonders of His love-<br/>How for me He won, He keepeth<br/>That high standing all above;<br/>Not a glimpse-the veil uplifted-<br/>But within the veil to dwell,<br/>Gazing on His face forever,<br/>Hearing words unspeakable.<br/>',NULL,2824,2824);
INSERT INTO stanza VALUES('E552','4','I have seen the face of Jesus-<br/>Tell me not of aught beside;<br/>I have heard the voice of Jesus-<br/>All my soul is satisfied.<br/>In the radiance of the glory<br/>First I saw His blessed face,<br/>And forever shall that glory<br/>Be my home, my dwelling-place.<br/>',NULL,2825,2825);
INSERT INTO stanza VALUES('E553','1','In the secret of His presence<br/>How my soul delights to hide!<br/>Oh, how precious are the lessons<br/>Which I learn at Jesus'' side!<br/>Earthly cares can never vex me,<br/>Neither trials lay me low;<br/>For when Satan comes to tempt me,<br/>To the secret place I go.<br/>(Repeat the last line of each stanza)<br/>',NULL,2826,2826);
INSERT INTO stanza VALUES('E553','2','When my soul is faint and thirsty,<br/>''Neath the shadow of His wing<br/>There is cool and pleasant shelter,<br/>And a fresh and crystal spring;<br/>And my Savior rests beside me,<br/>As we hold communion sweet;<br/>If I tried, I could not utter<br/>What He says when thus we meet.<br/>',NULL,2827,2827);
INSERT INTO stanza VALUES('E553','3','Only this I know: I tell Him<br/>All my doubts and griefs and fears;<br/>Oh, how patiently He listens!<br/>And my drooping soul He cheers;<br/>Do you think He ne''er reproves me?<br/>What a false friend He would be,<br/>If He never, never told me<br/>Of the sins which He must see.<br/>',NULL,2828,2828);
INSERT INTO stanza VALUES('E553','4','Would you like to know the sweetness<br/>Of the secret of the Lord?<br/>Go and hide beneath the shadow;<br/>This shall then be your reward;<br/>And whene''er you leave the silence<br/>Of that happy meeting-place,<br/>By the Spirit bear the image<br/>Of the Master in your face.<br/>',NULL,2829,2829);
INSERT INTO stanza VALUES('E554','1','I come to His presence afresh<br/>Ere the night has passed into morning;<br/>And His face I see as it shines on me-<br/>The Lord within is dawning.<br/>And He speaks to me and reveals to me<br/>All His riches for me today;<br/>And with sweet delight I partake of Him,<br/>My hunger has passed away.<br/>',NULL,2830,2830);
INSERT INTO stanza VALUES('E554','2','As Spirit He speaks thru the Word<br/>Till my heart in echo is singing,<br/>And the fount of life with His grace and pow''r<br/>Within my soul is springing.<br/>And He speaks to me and reveals to me<br/>All His riches for me today;<br/>And I drink of Him for my every need,<br/>My thirsting has passed away.<br/>',NULL,2831,2831);
INSERT INTO stanza VALUES('E554','3','In tenderness He deals with me,<br/>While I stay with joy in His presence;<br/>And He saturates and supplies my soul<br/>With all His precious essence.<br/>And He speaks to me and reveals to me<br/>All His riches for me today;<br/>And in every way I partake of Him,<br/>My problems all passed away.<br/>',NULL,2832,2832);
INSERT INTO stanza VALUES('E555','1','Still, still with Thee, when purple morning breaketh,<br/>When the bird waketh, and the shadows flee;<br/>Fairer than morning, lovelier than daylight,<br/>Dawns the sweet consciousness, I am with Thee.<br/>',NULL,2833,2833);
INSERT INTO stanza VALUES('E555','2','As in the dawning, o''er the waveless ocean,<br/>The image of the morning star doth rest,<br/>So in this stillness Thou beholdest only<br/>Thine image in the waters of my breast.<br/>',NULL,2834,2834);
INSERT INTO stanza VALUES('E555','3','When sinks the soul, subdued by toil, to slumber,<br/>Its closing eye looks up to Thee in prayer;<br/>Sweet the repose, beneath Thy wings o''ershadowing,<br/>But sweeter still to wake and find Thee there.<br/>',NULL,2835,2835);
INSERT INTO stanza VALUES('E555','5','So shall it be at last, in that bright morning<br/>When the soul waketh, and life''s shadows flee;<br/>Oh, in that hour, fairer than daylight''s dawning,<br/>Shall rise the glorious thought, I am with Thee!<br/>',NULL,2836,2836);
INSERT INTO stanza VALUES('E556','1','Thy name is sweet as ointment poured forth;<br/>Better Thy love than wine, O draw Thou me!<br/>If we the footsteps follow of the flock,<br/>Entered Thy fellowship of love we''ll be.<br/>',NULL,2837,2837);
INSERT INTO stanza VALUES('E556','2','He''s my Beloved, I am His own love;<br/>He draweth me, pursue I after Him.<br/>Fragrant as myrrh, I''d hide Him in my heart;<br/>Beauteous as henna, I''d be clothed with Him;<br/>',NULL,2838,2838);
INSERT INTO stanza VALUES('E556','3','Bathe in His love, and of His fatness taste,<br/>Lie on His breast, His sweetness there enjoy;<br/>His love the banner, His affection shown<br/>Tenderly soothes my heart to purest joy.<br/>',NULL,2839,2839);
INSERT INTO stanza VALUES('E556','4','Oh, my Beloved''s mine, and I am His;<br/>I am a lily and my Shepherd He;<br/>May daybreak come, the shadows flee away,<br/>Him on the mountains as a hart I''d see.<br/>',NULL,2840,2840);
INSERT INTO stanza VALUES('E556','5','Myrrh of the death with Him and frankincense,<br/>The resurrection, permeate my heart;<br/>North wind awake, and let the south wind blow,<br/>Make my heart''s garden pleasure to His heart.<br/>',NULL,2841,2841);
INSERT INTO stanza VALUES('E556','6','I''d be to Him a dove that''s undefiled,<br/>As a pure lily in His presence be,<br/>His, wholly His, the joy of all His joys,<br/>He wholly mine, the Song of songs to me.<br/>',NULL,2842,2842);
INSERT INTO stanza VALUES('E556','7','Fair as the moon, conformed to Him I''d be,<br/>Clear as the sun, unto His stature grown;<br/>For my Beloved, all to please His heart,<br/>For my Beloved, that His life be shown.<br/>',NULL,2843,2843);
INSERT INTO stanza VALUES('E556','8','Thou art my life, and I Thine image real;<br/>Love in such union is as death most strong,<br/>Ne''er can it be destroyed or e''er replaced<br/>Till Thou on spices mountains come ere long.<br/>',NULL,2844,2844);
INSERT INTO stanza VALUES('E557','1','Jesus Himself drew near,<br/>And joined them as they walked,<br/>And soon their hearts began to burn,<br/>As of Himself He talked:<br/>Draw near, O Lord.<br/>',NULL,2845,2845);
INSERT INTO stanza VALUES('E557','2','Jesus Himself drew near,<br/>They were no longer sad;<br/>When He was walking at their side,<br/>How could they but be glad?<br/>Draw near, O Lord.<br/>',NULL,2846,2846);
INSERT INTO stanza VALUES('E557','3','Jesus Himself drew near,<br/>And all their doubts were solved;<br/>He showed them why Christ came to die,<br/>And what that death involved:<br/>Draw near, O Lord.<br/>',NULL,2847,2847);
INSERT INTO stanza VALUES('E557','4','Jesus Himself drew near,<br/>And at the journey''s end<br/>They could not let Him leave them thus,<br/>The Stranger was their Friend:<br/>Draw near, O Lord.<br/>',NULL,2848,2848);
INSERT INTO stanza VALUES('E558','1','What a fellowship, what a joy divine,<br/>Leaning on the Everlasting Arms!<br/>What a blessedness, what a peace is mine,<br/>Leaning on the Everlasting Arms!<br/>',NULL,2849,2849);
INSERT INTO stanza VALUES('E558','chorus','Leaning, leaning,<br/>Safe and secure from all alarms;<br/>Leaning, leaning,<br/>Leaning on the Everlasting Arms!<br/>',NULL,2850,2850);
INSERT INTO stanza VALUES('E558','2','O how sweet to walk in this pilgrim way,<br/>Leaning on the Everlasting Arms!<br/>O how bright the path grows from day to day,<br/>Leaning on the Everlasting Arms!<br/>',NULL,2851,2851);
INSERT INTO stanza VALUES('E558','3','What have I to dread, what have I to fear,<br/>Leaning on the Everlasting Arms!<br/>I have peace complete with my Lord so near,<br/>Leaning on the Everlasting Arms!<br/>',NULL,2852,2852);
INSERT INTO stanza VALUES('E559','1','Savior, I by faith am touching<br/>Thee, the source of every good;<br/>Virtue now, by faith am claiming,<br/>Through the cleansing of Thy blood.<br/>',NULL,2853,2853);
INSERT INTO stanza VALUES('E559','chorus','Touching Thee, new life is glowing<br/>By Thy Spirit''s burning flame;<br/>Cleansing, purging, Spirit filling,<br/>Glory to Thy Holy Name!<br/>',NULL,2854,2854);
INSERT INTO stanza VALUES('E559','2','Touching Thee in faith, I take Thee<br/>In Thy riches full and free;<br/>All I am I open to Thee,<br/>All Thou art Thou giv''st to me.<br/>',NULL,2855,2855);
INSERT INTO stanza VALUES('E559','3','Touching now Thine outstretched scepter,<br/>O most mighty King of kings;<br/>Of Thy fulness now receiving,<br/>High I mount on eagle wings.<br/>',NULL,2856,2856);
INSERT INTO stanza VALUES('E559','4','Grace and virtue, strength and wisdom,<br/>All my need, by Thee supplied;<br/>Keep me touching, keep me claiming,<br/>Keep me ever at Thy side.<br/>',NULL,2857,2857);
INSERT INTO stanza VALUES('E560','1','Come, O Thou Traveler unknown,<br/>Whom still I hold but cannot see;<br/>My company before is gone,<br/>And I am left alone with Thee;<br/>With Thee all night I mean to stay,<br/>And wrestle till the break of day.<br/>',NULL,2858,2858);
INSERT INTO stanza VALUES('E560','2','I need not tell Thee who I am,<br/>My sin and misery declare;<br/>Thyself hast called me by my name,<br/>Look on Thy hands, and read it there;<br/>But who, I ask Thee, who art Thou?<br/>Tell me Thy name, and tell me now.<br/>',NULL,2859,2859);
INSERT INTO stanza VALUES('E560','3','In vain Thou strugglest to get free;<br/>I never will unloose my hold;<br/>Art Thou the Man that died for me?<br/>The secret of Thy love unfold;<br/>Wrestling, I will not let Thee go,<br/>Till I Thy name, Thy nature know.<br/>',NULL,2860,2860);
INSERT INTO stanza VALUES('E560','4','Yield to me now, for I am weak,<br/>But confident in self-despair;<br/>Speak to my heart, in blessings speak,<br/>Be conquered by my instant prayer;<br/>Speak, or Thou never hence shalt move,<br/>And tell me if Thy name be Love.<br/>',NULL,2861,2861);
INSERT INTO stanza VALUES('E560','5','''Tis Love! ''Tis Love! Thou diedst for me;<br/>I hear Thy whisper in my heart;<br/>The morning breaks, the shadows flee:<br/>Pure, universal Love Thou art;<br/>To me, to all Thy mercies move;<br/>Thy nature and Thy name is Love.<br/>',NULL,2862,2862);
INSERT INTO stanza VALUES('E560','6','Lame as I am, I take the prey;<br/>Hell, earth and sin, with ease o''ercome.<br/>I leap for joy, pursue my way,<br/>And, as a bounding hart, I run,<br/>Through all eternity to prove<br/>Thy nature and Thy name is Love.<br/>',NULL,2863,2863);
INSERT INTO stanza VALUES('E561','1','Thou hast said Thou art the Vine, Lord,<br/>And that I''m a branch in Thee,<br/>But I do not know the reason<br/>Why I should so barren be.<br/>',NULL,2864,2864);
INSERT INTO stanza VALUES('E561','2','Bearing fruit is my deep longing,<br/>More Thy life to manifest,<br/>To Thy throne to being more glory,<br/>That Thy will may be expressed.<br/>',NULL,2865,2865);
INSERT INTO stanza VALUES('E561','3','But I fail to understand, Lord,<br/>What it means-"abide in me"<br/>For the more I seek "abiding,"<br/>More I feel I''m not in Thee.<br/>',NULL,2866,2866);
INSERT INTO stanza VALUES('E561','4','How I feel I''m not abiding;<br/>Though I pray and strongly will,<br/>Yet from me Thou seemest distant<br/>And my life is barren still.<br/>',NULL,2867,2867);
INSERT INTO stanza VALUES('E561','5','Yet Thou art the Vine, Thou saidst it,<br/>And I am a branch in Thee;<br/>When I take Thee as my Savior,<br/>Then this fact is wrought in me.<br/>',NULL,2868,2868);
INSERT INTO stanza VALUES('E561','6','Now I''m in Thee and I need not<br/>Seek into Thyself to come,<br/>For I''m joined to Thee already,<br/>With Thy flesh and bones I''m one.<br/>',NULL,2869,2869);
INSERT INTO stanza VALUES('E561','7','Not to "go in" is the secret,<br/>But that I''m "already in"!<br/>That I ne''er may leave I''d ask Thee,<br/>Not how I may get within.<br/>',NULL,2870,2870);
INSERT INTO stanza VALUES('E561','8','I am in, already in Thee!<br/>What a place to which I''m brought!<br/>There''s no need for prayer or struggling,<br/>God Himself the work has wrought.<br/>',NULL,2871,2871);
INSERT INTO stanza VALUES('E561','9','Since I''m in, why ask to enter;<br/>O how ignorant I''ve been!<br/>Now with praise and much rejoicing<br/>For Thy Word, I dwell therein.<br/>',NULL,2872,2872);
INSERT INTO stanza VALUES('E561','10','Now in Thee I rest completely,<br/>With myself I gladly part;<br/>Thou art life and Thou art power,<br/>All in all to me Thou art.<br/>',NULL,2873,2873);
INSERT INTO stanza VALUES('E562','1','Abiding, oh, so wondrous sweet,<br/>I''m resting at the Savior''s feet;<br/>I trust in Him, I''m satisfied,<br/>I''m resting in the Crucified.<br/>',NULL,2874,2874);
INSERT INTO stanza VALUES('E562','chorus','Abiding, abiding,<br/>Oh! So wondrous sweet;<br/>I''m resting, resting<br/>At the Savior''s feet.<br/>',NULL,2875,2875);
INSERT INTO stanza VALUES('E562','2','He speaks, and by His word is giv''n<br/>His peace, a blessed gift from heav''n;<br/>Not as the world He peace doth give,<br/>''Tis through this hope my soul shall live.<br/>',NULL,2876,2876);
INSERT INTO stanza VALUES('E562','3','I live; not I; ''tis He alone<br/>By whom the mighty work is done;<br/>Dead to myself, alive to Him,<br/>I count all loss His rest to gain.<br/>',NULL,2877,2877);
INSERT INTO stanza VALUES('E562','4','Now rest, my heart, the work is done,<br/>I''m saved through the Eternal Son;<br/>Let all my pow''rs my soul employ,<br/>To tell the world my peace and joy.<br/>',NULL,2878,2878);
INSERT INTO stanza VALUES('E563','1','Abide in Thee! In that deep love of Thine,<br/>My Jesus, Lord, Thou Lamb of God divine,<br/>Down, closely down, as living branch with tree,<br/>I would abide, my Lord, my Christ, in Thee.<br/>',NULL,2879,2879);
INSERT INTO stanza VALUES('E563','2','Abide in Thee! My Savior God, I know<br/>How love of Thine so vast in me may flow,<br/>My empty vessel, running o''er with joy,<br/>Must overflow to Thee without alloy.<br/>',NULL,2880,2880);
INSERT INTO stanza VALUES('E563','3','Abide in Thee! Nor doubt, nor self, nor sin,<br/>Can e''er prevail with Thy blest life within;<br/>Joined to Thyself, communing deep, my soul<br/>Know naught besides its motions to control.<br/>',NULL,2881,2881);
INSERT INTO stanza VALUES('E563','4','Abide in Thee! ''Tis thus I only know<br/>The secrets of Thy mind e''en while below-<br/>All joy and peace, and knowledge of Thy word,<br/>All pow''r and fruit, and service for the Lord.<br/>',NULL,2882,2882);
INSERT INTO stanza VALUES('E564','1','I have learned the wondrous secret<br/>Of abiding in the Lord;<br/>I have tasted life''s pure fountain,<br/>I am drinking of His word;<br/>I have found the strength and sweetness<br/>Of abiding ''neath the blood;<br/>I have lost myself in Jesus,<br/>I am sinking into God.<br/>',NULL,2883,2883);
INSERT INTO stanza VALUES('E564','chorus','I''m abiding in the Lord<br/>And confiding in His word;<br/>I am hiding in the bosom of His love.<br/>Yes, abiding in the Lord<br/>And confiding in His word,<br/>I am hiding in the bosom of His love.<br/>',NULL,2884,2884);
INSERT INTO stanza VALUES('E564','2','I am crucified with Jesus,<br/>And He lives and dwells with me;<br/>I have ceased from all my struggling,<br/>''Tis no longer I, but He.<br/>All my will is yielded to Him,<br/>And His Spirit reigns within;<br/>And His precious blood each moment<br/>Keeps me cleansed and free from sin.<br/>',NULL,2885,2885);
INSERT INTO stanza VALUES('E564','3','All my sicknesses I bring Him,<br/>And He bears them all away;<br/>All my fears and griefs I tell Him,<br/>All my cares from day to day,<br/>All my strength I draw from Jesus,<br/>By His breath I live and move;<br/>E''en His very mind He gives me,<br/>And His faith, and life, and love.<br/>',NULL,2886,2886);
INSERT INTO stanza VALUES('E564','4','For my words I take His wisdom,<br/>For my works His Spirit''s power;<br/>For my ways His ceaseless presence<br/>Guards and guides me every hour.<br/>Of my heart, He is the portion,<br/>Of my joy the boundless spring;<br/>Savior, Sanctifier, Healer,<br/>Glorious Lord, and coming King.<br/>',NULL,2887,2887);
INSERT INTO stanza VALUES('E565','1','Under His wings I am safely abiding;<br/>Though the night deepens and tempests are wild,<br/>Still I can trust Him, I know He will keep me;<br/>He has redeemed me, and I am His child.<br/>',NULL,2888,2888);
INSERT INTO stanza VALUES('E565','chorus','Under His wings, under His wings,<br/>Who from His love can sever?<br/>Under His wings my soul shall abide,<br/>Safely abide forever.<br/>',NULL,2889,2889);
INSERT INTO stanza VALUES('E565','2','Under His wings-what a refuge in sorrow!<br/>How the heart yearningly turns to His rest!<br/>Often when earth has no balm for my healing,<br/>There I find comfort, and there I am blest.<br/>',NULL,2890,2890);
INSERT INTO stanza VALUES('E565','3','Under His wings-oh, what precious<br/>enjoyment!<br/>There will I hide till life''s trials are o''er;<br/>Sheltered, protected, no evil can harm me;<br/>Resting in Jesus I''m safe evermore.<br/>Under His wings, under His wings,<br/>Who from His love can sever?<br/>Under His wings my soul shall abide,<br/>Safely abide forever.<br/>',NULL,2891,2891);
INSERT INTO stanza VALUES('E566','1','Oh, safe to the Rock that is higher than I,<br/>My soul in its conflicts and sorrows would fly,<br/>So sinful, so weary, Thine, Thine would I be,<br/>Thou blest Rock of Ages, I''m hiding in Thee.<br/>',NULL,2892,2892);
INSERT INTO stanza VALUES('E566','chorus','Hiding in Thee, hiding in Thee,<br/>Thou blest Rock of Ages, I''m hiding in Thee.<br/>',NULL,2893,2893);
INSERT INTO stanza VALUES('E566','2','In the calm of the noontide, in sorrow''s lone hour,<br/>In times when temptation cast o''er me its power;<br/>In the tempest of life, on its wide, heaving sea,<br/>Thou blest Rock of Ages, I''m hiding in Thee.<br/>',NULL,2894,2894);
INSERT INTO stanza VALUES('E566','3','How oft in the conflict, when pressed by the foe,<br/>I have fled to my Refuge and breathed out my woe;<br/>How often, when trials like sea-billows roll,<br/>Have I hidden in Thee, O Thou Rock of my soul.<br/>',NULL,2895,2895);
INSERT INTO stanza VALUES('E567','1','O Lamb of God, still keep me<br/>Close to Thy wounded side;<br/>''Tis only there in safety<br/>And peace I can abide.<br/>',NULL,2896,2896);
INSERT INTO stanza VALUES('E567','2','What foes and snares surround me,<br/>What lusts and fears within;<br/>The grace that sought and found me<br/>Alone can keep me clean.<br/>',NULL,2897,2897);
INSERT INTO stanza VALUES('E567','3','''Tis only in Thee hiding<br/>I feel myself secure;<br/>Only in Thee abiding,<br/>The conflict can endure;<br/>',NULL,2898,2898);
INSERT INTO stanza VALUES('E567','4','Thine arm the victory gaineth<br/>O''er every hateful foe;<br/>Thy love my heart sustaineth<br/>In all its care and woe.<br/>',NULL,2899,2899);
INSERT INTO stanza VALUES('E567','5','Soon shall my eyes behold Thee,<br/>With rapture face to face;<br/>One half hath not been told me<br/>Of all Thy power and grace;<br/>',NULL,2900,2900);
INSERT INTO stanza VALUES('E567','6','The beauty, Lord, and glory,<br/>The wonders of Thy love,<br/>Shall be the endless story<br/>Of all Thy saints above.<br/>',NULL,2901,2901);
INSERT INTO stanza VALUES('E568','1','''Tis so sweet to trust in Jesus,<br/>Just to take Him at His word;<br/>Just to rest upon His promise;<br/>Just to know, Thus saith the Lord.<br/>',NULL,2902,2902);
INSERT INTO stanza VALUES('E568','chorus','Jesus, Jesus, how I trust Him,<br/>How I''ve proved Him o''er and o''er,<br/>Jesus, Jesus, Precious Jesus!<br/>O for grace to trust Him more.<br/>',NULL,2903,2903);
INSERT INTO stanza VALUES('E568','2','O how sweet to trust in Jesus,<br/>Just to trust His cleansing blood;<br/>Just in simple faith to plunge me,<br/>''Neath the healing, cleansing flood.<br/>',NULL,2904,2904);
INSERT INTO stanza VALUES('E568','3','Yes, ''tis sweet to trust in Jesus,<br/>Just from sin and self to cease;<br/>Just from Jesus simply taking<br/>Life, and rest, and joy, and peace.<br/>',NULL,2905,2905);
INSERT INTO stanza VALUES('E568','4','I''m so glad I learned to trust Thee,<br/>Precious Jesus, Savior, Friend;<br/>And I know that Thou art with me,<br/>Wilt be with me to the end.<br/>',NULL,2907,2907);
INSERT INTO stanza VALUES('E569','1','Simply trusting every day;<br/>Trusting through a stormy way;<br/>Even when my faith is small,<br/>Trusting Jesus, that is all.<br/>',NULL,2909,2909);
INSERT INTO stanza VALUES('E569','chorus','Trusting as the moment fly,<br/>Trusting as the days go by,<br/>Trusting Him, whate''er befall,<br/>Trusting Jesus, that is all.<br/>',NULL,2910,2910);
INSERT INTO stanza VALUES('E569','2','Brightly doth His Spirit shine<br/>Into this poor heart of mine;<br/>While He leads I cannot fall,<br/>Trusting Jesus, that is all.<br/>',NULL,2911,2911);
INSERT INTO stanza VALUES('E569','3','Singing if my way be clear,<br/>Praying of the path be drear;<br/>If in danger, for Him call,<br/>Trusting Jesus, that is all.<br/>',NULL,2912,2912);
INSERT INTO stanza VALUES('E569','4','Trusting Him while life shall last,<br/>Trusting Him till earth is past,<br/>Till His gracious advent call,<br/>Trusting Jesus, that is all.<br/>',NULL,2913,2913);
INSERT INTO stanza VALUES('E570','1','All my doubts I give to Jesus;<br/>I''ve His gracious promise heard:<br/>I shall never be confounded,<br/>I am trusting in that word.<br/>',NULL,2914,2914);
INSERT INTO stanza VALUES('E570','chorus','I am trusting, fully trusting,<br/>Sweetly trusting in His word;<br/>I am trusting, fully trusting,<br/>Sweetly trusting in His word.<br/>',NULL,2915,2915);
INSERT INTO stanza VALUES('E570','2','All my sins I lay on Jesus,<br/>He doth wash me in His blood,<br/>He will keep me pure and holy,<br/>He will keep me close to God.<br/>',NULL,2916,2916);
INSERT INTO stanza VALUES('E570','3','All my fears I give to Jesus,<br/>Rests my weary soul on Him;<br/>Though my way be hid in darkness,<br/>Never can His light grow dim.<br/>',NULL,2917,2917);
INSERT INTO stanza VALUES('E570','4','All my joys I give to Jesus,<br/>He is all I want of bliss;<br/>He of all the worlds is Master;<br/>He has all I need in this.<br/>I am trusting, fully trusting,<br/>Sweetly trusting in His word;<br/>I am trusting, fully trusting,<br/>Sweetly trusting in His word.<br/>',NULL,2918,2918);
INSERT INTO stanza VALUES('E570','5','All I am I give to Jesus;<br/>All my body, all my soul;<br/>All I have, and all I hope for;<br/>While eternal ages roll.<br/>I am trusting, fully trusting,<br/>Sweetly trusting in His word;<br/>I am trusting, fully trusting,<br/>Sweetly trusting in His word.<br/>',NULL,2919,2919);
INSERT INTO stanza VALUES('E571','1','Thou whose name is called Jesus,<br/>Risen Lord of life and pow''r,<br/>Oh, it is so sweet to trust Thee,<br/>Every day and every hour;<br/>Of Thy wondrous grace I sing,<br/>Savior, Counselor, and King.<br/>',NULL,2920,2920);
INSERT INTO stanza VALUES('E571','2','Thou canst keep my feet from falling,<br/>Even my poor wayward feet;<br/>Thou who dost present me faultless<br/>In Thee-Righteousness complete;<br/>Jesus, Lord, in knowing Thee,<br/>Oh, what strength and victory.<br/>',NULL,2921,2921);
INSERT INTO stanza VALUES('E571','3','All the sin in me, my Savior,<br/>Thou canst conquer and subdue;<br/>With Thy sanctifying power<br/>Permeate my spirit through;<br/>Let Thy government increase,<br/>Risen, crowned, Prince of Peace.<br/>',NULL,2922,2922);
INSERT INTO stanza VALUES('E571','4','Thou canst keep my upward looking,<br/>Ever upward in Thy face;<br/>Thou canst make me stand, upholden<br/>By the greatness of Thy grace;<br/>Every promise of Thy word<br/>Now I claim from Thee, dear Lord.<br/>',NULL,2923,2923);
INSERT INTO stanza VALUES('E571','5','Oh! What joy to trust in Thee, Jesus,<br/>Mighty Victor o''er the grave,<br/>And to learn amid earth''s shadows<br/>Thine unceasing power to save!<br/>Only those who prove Thee know<br/>What the grace Thou dost bestow.<br/>',NULL,2924,2924);
INSERT INTO stanza VALUES('E571','6','Make my life a bright outshining<br/>Of Thy life, that all my see<br/>Thine own resurrection power<br/>Mightily put forth in me;<br/>Ever let my heart become<br/>Yet more consciously Thy home.<br/>',NULL,2925,2925);
INSERT INTO stanza VALUES('E572','1','Jesus hath died and hath risen again,<br/>Pardon and peace to bestow;<br/>Fully I trust Him; from sin''s guilty stain,<br/>Jesus saves me now.<br/>',NULL,2926,2926);
INSERT INTO stanza VALUES('E572','chorus','Jesus saves me now,<br/>Jesus saves me now;<br/>Yes, Jesus saves me all the time;<br/>Jesus saves me now;<br/>',NULL,2927,2927);
INSERT INTO stanza VALUES('E572','2','Sin''s condemnation is over and gone,<br/>Jesus alone knoweth how;<br/>Life and salvation my soul hath put on:<br/>Jesus saves me now.<br/>',NULL,2928,2928);
INSERT INTO stanza VALUES('E572','3','Satan may tempt, but he never shall reign,<br/>That Christ will never allow;<br/>Doubts I have buried, and this is my strain,<br/>Jesus saves me now.<br/>',NULL,2929,2929);
INSERT INTO stanza VALUES('E572','4','Resting in Jesus, abiding in Him,<br/>Gladly my faith can avow,<br/>Never again need my pathway be dim:<br/>Jesus saves me now.<br/>',NULL,2930,2930);
INSERT INTO stanza VALUES('E572','5','Jesus is stronger than Satan and sin,<br/>Satan to Jesus must bow;<br/>Therefore I triumph without and within:<br/>Jesus saves me now.<br/>',NULL,2931,2931);
INSERT INTO stanza VALUES('E572','6','Sorrow and pain may beset me about,<br/>Nothing can darken my brow;<br/>Battling in faith, I can joyfully shout:<br/>"Jesus saves me now."<br/>',NULL,2932,2932);
INSERT INTO stanza VALUES('E573','1','Once I thought I walked with Jesus,<br/>Yet such changeful feelings had;<br/>Sometimes trusting, sometimes doubting,<br/>Sometimes joyful, sometimes sad.<br/>',NULL,2933,2933);
INSERT INTO stanza VALUES('E573','chorus','Oh, the peace the Savior gives!<br/>Peace I never knew before;<br/>And my way has brighter grown<br/>Since I''ve learned to trust Him more.<br/>',NULL,2934,2934);
INSERT INTO stanza VALUES('E573','2','But He call''d me closer to Him,<br/>Bade my doubting, fearing, cease;<br/>And when I had fully yielded,<br/>Filled my soul with perfect peace.<br/>',NULL,2935,2935);
INSERT INTO stanza VALUES('E573','3','Now I''m trusting every moment,<br/>Nothing less can be enough;<br/>And the Savior bears me gently<br/>O''er those places once so rough.<br/>',NULL,2936,2936);
INSERT INTO stanza VALUES('E573','4','Day by day my soul He''s keeping<br/>By His wondrous power within;<br/>And my heart is full of singing<br/>To my Savior from all sin.<br/>',NULL,2937,2937);
INSERT INTO stanza VALUES('E574','1','Lord Jesus, Thou dost keep Thy child<br/>Thru sunshine or thru tempests wild;<br/>Jesus, I trust in Thee:<br/>Thine is such wondrous pow''r to save;<br/>Thine is the mighty love that gave<br/>Its all on Calvary.<br/>',NULL,2938,2938);
INSERT INTO stanza VALUES('E574','2','O glorious Savior, Thee I praise;<br/>To Thee my new glad song I raise,<br/>And tell of what Thou art.<br/>Thy grace is boundless in its store;<br/>Thy face of love shines evermore;<br/>Thou givest me Thy heart.<br/>',NULL,2939,2939);
INSERT INTO stanza VALUES('E574','3','Upon Thy promise I stand,<br/>Trusting in Thee: Thine own right hand<br/>Doth keep and comfort me;<br/>My soul doth triumph in Thy word;<br/>Thine, Thine be all the praise, dear Lord,<br/>As Thine the victory.<br/>',NULL,2940,2940);
INSERT INTO stanza VALUES('E574','4','Love perfecteth what it begins;<br/>Thy power doth save me from my sins;<br/>Thy grace upholdeth me.<br/>This life of trust, how glad, how sweet;<br/>My need and Thy great fulness meet,<br/>And I have all in Thee.<br/>',NULL,2941,2941);
INSERT INTO stanza VALUES('E575','1','I take Thy promise, Lord, in all its length,<br/>And breadth and fulness, as my daily strength;<br/>Into life''s future fearless I may gaze,<br/>For, Savior, Thou art with me all the days.<br/>',NULL,2942,2942);
INSERT INTO stanza VALUES('E575','2','Days may be coming fraught with loss and change,<br/>New scenes surround my life and fancies strange;<br/>I thank Thee that no day can ever break,<br/>Savior, when Thou wilt leave me or forsake.<br/>',NULL,2943,2943);
INSERT INTO stanza VALUES('E575','3','There may be days of darkness and distress,<br/>When sin has power to tempt, and care to press,<br/>Yet in the darkest day I will not fear,<br/>For, ''mid the shadows, Thou wilt still be near.<br/>',NULL,2944,2944);
INSERT INTO stanza VALUES('E575','4','Days there may be of joy and deep delight,<br/>When earth seems fairest, and her skies most bright,<br/>Then draw me closer to Thee, lest I rest<br/>Elsewhere, my Savior, than upon Thy breast.<br/>',NULL,2945,2945);
INSERT INTO stanza VALUES('E575','5','And all the other days that make my life,<br/>Marked by no special joy or grief or strife,<br/>Days filled with quiet duties, trivial care,<br/>Burdens too small for other hearts to share;<br/>',NULL,2946,2946);
INSERT INTO stanza VALUES('E575','6','Spend Thou those days with me, all shall be Thine,<br/>So shall the darkest hour with glory shine.<br/>Then when these earthly years have passed away,<br/>Let me be with Thee in the perfect day.<br/>',NULL,2947,2947);
INSERT INTO stanza VALUES('E576','1','I clasp the hand of Love divine,<br/>I claim the gracious promise mine,<br/>And add to His my countersign,<br/>"I take"-"He undertakes."<br/>',NULL,2948,2948);
INSERT INTO stanza VALUES('E576','chorus','I take Thee, blessed Lord,<br/>I give myself to Thee,<br/>And Thou, according to Thy word,<br/>Dost undertake for me.<br/>',NULL,2949,2949);
INSERT INTO stanza VALUES('E576','2','I take salvation full and free,<br/>Through Him who gave His life for me,<br/>He undertakes my all to be,<br/>“I take”—“He undertakes.”<br/>',NULL,2950,2950);
INSERT INTO stanza VALUES('E576','3','I take Him as my holiness,<br/>My spirit’s spotless, heavenly dress,<br/>I take the Lord, my righteousness,<br/>“I take”—“He undertakes.”<br/>',NULL,2951,2951);
INSERT INTO stanza VALUES('E576','4','I take the promised Holy Ghost,<br/>I take the power of Pentecost,<br/>To fill me to the uttermost,<br/>“I take”—“He undertakes.”<br/>',NULL,2952,2952);
INSERT INTO stanza VALUES('E577','1','When I fear my faith will fail,<br/>Christ will hold me fast;<br/>When the tempter would prevail,<br/>He can hold me fast.<br/>',NULL,2953,2953);
INSERT INTO stanza VALUES('E577','chorus','He will hold me fast,<br/>He will hold me fast;<br/>For my Savior loves me so,<br/>He will hold me fast.<br/>',NULL,2954,2954);
INSERT INTO stanza VALUES('E577','2','I could never keep my hold,<br/>He will hold me fast;<br/>For my love is often cold,<br/>He must hold me fast.<br/>',NULL,2955,2955);
INSERT INTO stanza VALUES('E577','3','I am precious in His sight,<br/>He will hold me fast;<br/>Those He saves are His delight,<br/>He will hold me fast.<br/>',NULL,2956,2956);
INSERT INTO stanza VALUES('E577','4','He''ll not let my soul be lost,<br/>Christ will hold me fast;<br/>Bought by Him at such as cost,<br/>He will hold me fast.<br/>',NULL,2957,2957);
INSERT INTO stanza VALUES('E578','1','My will is weak, my strength is frail,<br/>And all my hope is nearly gone;<br/>I can but trust Thy working true<br/>To gently hold and lead me on.<br/>',NULL,2958,2958);
INSERT INTO stanza VALUES('E578','2','I''ve tried my best, but still have failed,<br/>E''en as before I''ve failed and erred;<br/>Thy patience is my only trust<br/>To hold and keep me to Thy word.<br/>',NULL,2959,2959);
INSERT INTO stanza VALUES('E578','3','When''er my heart is lifted up,<br/>How very near I am to fall;<br/>I dare not do, I dare not think,<br/>I need Thyself in great or small.<br/>',NULL,2960,2960);
INSERT INTO stanza VALUES('E578','4','Thou art my Savior, strength and stay,<br/>O Lord, I come to seek Thy face;<br/>Though I''m the weakest of the weak,<br/>My strength is nothing but Thy grace.<br/>',NULL,2961,2961);
INSERT INTO stanza VALUES('E579','1','Jesus! I am resting, resting<br/>In the joy of what Thou art;<br/>I am finding out the greatness<br/>Of Thy loving heart.<br/>Thou hast bid me gaze upon Thee,<br/>And Thy beauty fills my soul,<br/>For, by Thy transforming power,<br/>Thou has made me whole.<br/>',NULL,2962,2962);
INSERT INTO stanza VALUES('E579','chorus','Jesus! I am resting, resting<br/>In the joy of what Thou art;<br/>I am finding out the greatness<br/>Of Thy loving heart.<br/>',NULL,2963,2963);
INSERT INTO stanza VALUES('E579','2','Oh, how great Thy loving kindness,<br/>Vaster, broader than the sea;<br/>Oh, how marvelous Thy goodness,<br/>Lavished all on me!<br/>Yes, I rest in Thee, Beloved,<br/>Know what wealth of grace is Thine,<br/>Know Thy certainty of promise,<br/>And have made it mine.<br/>',NULL,2964,2964);
INSERT INTO stanza VALUES('E579','3','Simply trusting Thee, Lord Jesus,<br/>I behold Thee as Thou art,<br/>And Thy love, so pure, so changeless,<br/>Satisfies my heart,<br/>Satisfies its deepest longings,<br/>Meets, supplies its every need,<br/>Compasseth me round with blessings,<br/>Thine is love indeed.<br/>',NULL,2965,2965);
INSERT INTO stanza VALUES('E579','4','Ever lift Thy face upon me,<br/>As I work and wait for Thee;<br/>Resting ''neath Thy smile, Lord Jesus,<br/>Earth''s dark shadows flee.<br/>Brightness of my Father''s glory,<br/>Sunshine of my Father''s face,<br/>Keep me ever trusting, resting,<br/>Fill me with Thy grace.<br/>',NULL,2966,2966);
INSERT INTO stanza VALUES('E580','1','Resting on the faithfulness of Christ our Lord,<br/>Resting on the fulness of His own sure word,<br/>Resting on His wisdom, on His love and pow''r,<br/>Resting on His covenant from hour to hour.<br/>',NULL,2967,2967);
INSERT INTO stanza VALUES('E580','2','Resting ''neath His guiding hand for untrack''d days,<br/>Resting ''neath His shadow from noontide rays,<br/>Resting at the eventide beneath His wing,<br/>In the glorious presence of our Savior King.<br/>',NULL,2968,2968);
INSERT INTO stanza VALUES('E580','3','Resting in the fortress while the foe is nigh,<br/>Resting in the lifeboat while the waves roll high,<br/>Resting in His chariot for the swift, glad race,<br/>Resting, always resting, in His boundless grace.<br/>',NULL,2969,2969);
INSERT INTO stanza VALUES('E580','4','Resting in the pastures and beneath the Rock,<br/>Resting by the waters where He leads His flock,<br/>Resting, while we listen, at His glorious feet,<br/>Resting in His very arms, oh, rest complete!<br/>',NULL,2970,2970);
INSERT INTO stanza VALUES('E580','5','Resting and believing, let us onward press;<br/>Resting on Himself, the Lord our righteousness;<br/>Resting and rejoicing, let His saved ones sing,<br/>Glory, glory, glory be to Christ our King!<br/>',NULL,2971,2971);
INSERT INTO stanza VALUES('E581','1','On Thee my heart is resting,<br/>Ah, this is rest indeed:<br/>What else, Almighty Savior,<br/>Can a poor sinner need?<br/>Thy light is all my wisdom,<br/>Thy love is all my stay;<br/>Thy coming back in glory,<br/>Draws nearer every day.<br/>',NULL,2972,2972);
INSERT INTO stanza VALUES('E581','chorus','On Thee my heart is resting,<br/>Ah, this is rest indeed:<br/>What else, Almighty Savior,<br/>Can a poor sinner need?<br/>',NULL,2973,2973);
INSERT INTO stanza VALUES('E581','2','My guilt is great, but greater<br/>The mercy Thou dost give;<br/>Thyself, a spotless Off''ring,<br/>Hast died that I should live.<br/>With Thee, my soul unfettered<br/>Has risen from the dust;<br/>Thy blood is all my treasure,<br/>Thy word is all my trust.<br/>',NULL,2974,2974);
INSERT INTO stanza VALUES('E581','3','Through me, Thou gentle Master,<br/>Thy purpose fulfill;<br/>I yield myself forever<br/>To Thy most holy will.<br/>What though I be but weakness?<br/>My strength is not in me;<br/>The poorest for Thy people<br/>Has all things, having Thee.<br/>',NULL,2975,2975);
INSERT INTO stanza VALUES('E581','4','When clouds are darkest round me,<br/>Thou, Lord, art then most near,<br/>My drooping faith to quicken,<br/>My weary soul to cheer.<br/>Safe nestling in Thy bosom,<br/>I gaze upon Thy face;<br/>In vain my foes would drive me<br/>From Thee, my hiding-place.<br/>',NULL,2976,2976);
INSERT INTO stanza VALUES('E581','5','''Tis Thou hast made me happy,<br/>''Tis Thou hast set me free;<br/>To whom shall I give glory<br/>Forever, but to Thee?<br/>Of earthly love and blessing<br/>Should every stream run dry,<br/>Thy grace shall still be with me,<br/>Thy grace, to live and die.<br/>',NULL,2977,2977);
INSERT INTO stanza VALUES('E582','1','When we walk with the Lord<br/>In the light of His Word,<br/>What a glory He sheds on our way;<br/>While we do His good will,<br/>He abides with us still,<br/>And with all who will trust and obey.<br/>',NULL,2978,2978);
INSERT INTO stanza VALUES('E582','chorus','Trust and obey,<br/>For there''s no other way<br/>To be happy in Jesus,<br/>But to trust and obey.<br/>',NULL,2979,2979);
INSERT INTO stanza VALUES('E582','2','Not a shadow can rise,<br/>Not a cloud in the skies,<br/>But His smile quickly drives it away;<br/>Not a doubt or a fear,<br/>Not a sigh or a tear,<br/>Can abide while we trust and obey.<br/>',NULL,2980,2980);
INSERT INTO stanza VALUES('E582','3','Not a burden we bear,<br/>Not a sorrow we share,<br/>But our toil He doth richly repay;<br/>Not a grief or a loss,<br/>Not a frown or a cross,<br/>But is blest if we trust and obey.<br/>',NULL,2981,2981);
INSERT INTO stanza VALUES('E582','4','But we never can prove<br/>The delights of His love,<br/>Until all on the altar we lay;<br/>For the favor He shows,<br/>And the joy He bestows,<br/>Are for them who will trust and obey.<br/>',NULL,2982,2982);
INSERT INTO stanza VALUES('E582','5','Then in fellowship sweet<br/>We will sit at His feet,<br/>Or we''ll walk by His side in the way;<br/>What He says we will do;<br/>Where He sends we will go,<br/>Never fear, only trust and obey.<br/>',NULL,2983,2983);
INSERT INTO stanza VALUES('E583','1','Go to Him "without the camp,"<br/>His reproach to gladly bear.<br/>Suffered He without the gate,<br/>How can I in comfort share?<br/>',NULL,2984,2984);
INSERT INTO stanza VALUES('E583','2','Go to Him "without the camp,"<br/>Willing e''en to bear the cross;<br/>He has trod the narrow way,<br/>I will follow, suff''ring loss.<br/>',NULL,2985,2985);
INSERT INTO stanza VALUES('E583','3','Go to Him "without the camp,"<br/>Dear ones, relatives forsake;<br/>He the Father''s will did mind,<br/>In His passion I partake.<br/>',NULL,2986,2986);
INSERT INTO stanza VALUES('E583','4','Go to Him "without the camp,"<br/>His companion I will be;<br/>Never join religion''s ranks<br/>Or the world''s society.<br/>',NULL,2987,2987);
INSERT INTO stanza VALUES('E583','5','Go to Him "without the camp,"<br/>Though the path be lone and grim;<br/>Let all human friends desert,<br/>I am satisfied with Him.<br/>',NULL,2988,2988);
INSERT INTO stanza VALUES('E583','6','Go to Him "without the camp,"<br/>There to walk with Him, how blest!<br/>E''er to see His smiling face<br/>Ever in His presence rest.<br/>',NULL,2989,2989);
INSERT INTO stanza VALUES('E583','7','Go to Him "without the camp,"<br/>Till the dawning of the day;<br/>Then I''ll see Him and rejoice,<br/>With Him in His kingdom stay.<br/>',NULL,2990,2990);
INSERT INTO stanza VALUES('E584','1','Anywhere with Jesus I can safely go,<br/>Anywhere He leads me in this world below,<br/>Anywhere without Him, dearest joys would fade;<br/>Anywhere with Jesus I am not afraid.<br/>',NULL,2991,2991);
INSERT INTO stanza VALUES('E584','chorus','Anywhere! Anywhere! Fear I cannot know.<br/>Anywhere with Jesus I can safely go.<br/>',NULL,2992,2992);
INSERT INTO stanza VALUES('E584','2','Anywhere with Jesus I am not alone,<br/>Other friends may fail me, He is still my own.<br/>Though His hand may lead me over dreary ways,<br/>Anywhere with Jesus is a house of praise.<br/>',NULL,2993,2993);
INSERT INTO stanza VALUES('E584','3','Anywhere with Jesus I can go to sleep,<br/>When the darkling shadows round about me creep;<br/>Knowing I shall waken never more to roam,<br/>Anywhere with Jesus will be home, sweet home.<br/>',NULL,2994,2994);
INSERT INTO stanza VALUES('E585','1','He leadeth me! O blessed thought,<br/>O words with heav''nly comfort fraught;<br/>Whate''er I do, where''er I be,<br/>Still ''tis Christ''s hand that leadeth me.<br/>',NULL,2995,2995);
INSERT INTO stanza VALUES('E585','chorus','He leadeth me! He leadeth me!<br/>By His own hand He leadeth me;<br/>His faithful follower I would be,<br/>For by His hand He leadeth me.<br/>',NULL,2996,2996);
INSERT INTO stanza VALUES('E585','2','Sometimes ''mid scenes of deepest gloom,<br/>Sometimes where Eden''s bowers bloom,<br/>By waters still, o''er troubled sea,<br/>Still ''tis His hand that leadeth me.<br/>',NULL,2997,2997);
INSERT INTO stanza VALUES('E585','3','Lord, I would clasp Thy hand in mine,<br/>Nor ever murmur or repine;<br/>Content, whatever lot I see,<br/>Since it is Thou that leadest me.<br/>',NULL,2998,2998);
INSERT INTO stanza VALUES('E585','4','And when my task on earth is done,<br/>When, by Thy grace, the vict''ry''s won,<br/>E''en death''s cold wave I will not flee,<br/>Since Thou in triumph leadest me.<br/>',NULL,2999,2999);
INSERT INTO stanza VALUES('E586','1','I can hear my Savior calling,<br/>In the tend''rest accents calling;<br/>On my ear these words are falling,<br/>"Take thy cross, and daily follow me."<br/>',NULL,3000,3000);
INSERT INTO stanza VALUES('E586','chorus','I will take my cross and follow,<br/>My dear Savior I will follow,<br/>Where He leads me I will follow,<br/>I''ll go with Him, with Him all the way.<br/>',NULL,3001,3001);
INSERT INTO stanza VALUES('E586','2','Though the way be dark and dreary,<br/>Though my feet be worn and weary,<br/>Yet my heart keeps bright and cheery<br/>As I follow, follow all the way.<br/>',NULL,3002,3002);
INSERT INTO stanza VALUES('E586','3','Savior, ever go before me,<br/>Shining heaven''s sunlight o''er me,<br/>And when weak, by grace restore me<br/>As I follow, follow all the way.<br/>',NULL,3003,3003);
INSERT INTO stanza VALUES('E586','4','Through the valley safely lead me,<br/>Heav''nly manna daily feed me;<br/>Every hour, dear Lord, I need Thee<br/>As I follow, follow all the way.<br/>',NULL,3004,3004);
INSERT INTO stanza VALUES('E586','5','In Thy heart''s affection hold me,<br/>In Thy arms of love enfold me,<br/>And with Thine own grace uphold me,<br/>As I follow, follow all the way.<br/>',NULL,3005,3005);
INSERT INTO stanza VALUES('E586','6','I would never leave Thee, never;<br/>Faithful I would be forever;<br/>Nothing from Thy love can sever<br/>As I follow, follow all the way.<br/>',NULL,3006,3006);
INSERT INTO stanza VALUES('E587','1','''Tis so sweet to walk with Jesus,<br/>Step by step and day by day;<br/>Stepping in His very footprints,<br/>Walking with Him all the way.<br/>',NULL,3007,3007);
INSERT INTO stanza VALUES('E587','chorus','Step by step, step by step,<br/>I would walk with Jesus,<br/>All the day, all the way,<br/>Keeping step with Jesus.<br/>',NULL,3008,3008);
INSERT INTO stanza VALUES('E587','2','''Tis so safe I''ll walk with Jesus,<br/>Leaning hard upon His arm,<br/>Following closely where He leads us,<br/>None can hurt and naught can harm.<br/>',NULL,3009,3009);
INSERT INTO stanza VALUES('E587','3','Step by step I''ll walk with Jesus,<br/>Just a moment at a time,<br/>Heights I have not wings to soar to,<br/>Step by step my feet can climb.<br/>',NULL,3010,3010);
INSERT INTO stanza VALUES('E587','4','All the way I''ll walk with Jesus,<br/>Through the sunshine, through the gloom,<br/>Though His blood-marked steps may lead me<br/>To the garden, to the tomb.<br/>',NULL,3011,3011);
INSERT INTO stanza VALUES('E587','5','Here a while we walk with Jesus,<br/>But the time will not be long<br/>Till the night shall change to morning,<br/>And the sorrow into song.<br/>',NULL,3012,3012);
INSERT INTO stanza VALUES('E587','6','Then, with all who walked with Jesus,<br/>We shall walk with Him in white,<br/>While He turns our grief to gladness,<br/>And our darkness into light.<br/>',NULL,3013,3013);
INSERT INTO stanza VALUES('E587','7','Jesus, keep me closer-closer,<br/>Step by step, and day by day;<br/>Stepping in Thy very footprints,<br/>Walking with Thee all the way.<br/>',NULL,3014,3014);
INSERT INTO stanza VALUES('E588','1','O blessed life-the heart at rest<br/>When all without tumultuous seems,<br/>That trusts a higher will, and deems,<br/>That higher will, not mine, the best.<br/>',NULL,3015,3015);
INSERT INTO stanza VALUES('E588','2','O blessed life, the mind that sees,<br/>Whatever change the years may bring,<br/>A mercy still in everything,<br/>And shining through all mysteries.<br/>',NULL,3016,3016);
INSERT INTO stanza VALUES('E588','3','O blessed life, as spirit soars,<br/>When sense of mortal sight is dim,<br/>Beyond the sense, beyond to Him,<br/>Whose love unlocks the glorious doors.<br/>',NULL,3017,3017);
INSERT INTO stanza VALUES('E588','4','O blessed life, heart, mind, and soul,<br/>From self-born aims and wishes free,<br/>In all at one with Deity,<br/>And loyal to the Lord''s control.<br/>',NULL,3018,3018);
INSERT INTO stanza VALUES('E588','5','O life, how blessed, how divine,<br/>High life, the earnest of a higher;<br/>Savior, fulfill my deep desire,<br/>And let this blessed life be mine.<br/>',NULL,3019,3019);
INSERT INTO stanza VALUES('E589','1','God in heaven hath a treasure,<br/>Riches none may count or tell;<br/>Hath a deep eternal pleasure,<br/>Christ the Son, He loveth well.<br/>God hath here on earth a treasure,<br/>None but He its price may know-<br/>Deep, unfathomable pleasure,<br/>Christ revealed in saints below.<br/>',NULL,3020,3020);
INSERT INTO stanza VALUES('E589','2','God in tongues of fire descending,<br/>Chosen vessels thus to fill<br/>With the treasure never ending,<br/>Ever spent-unfailing still.<br/>God''s own hand the vessel filling<br/>From the glory far above,<br/>Longing hearts forever stilling<br/>With the riches of His love.<br/>',NULL,3021,3021);
INSERT INTO stanza VALUES('E589','3','Thus though worn, and tried, and tempted,<br/>Glorious calling, saint, is thine;<br/>Let the Lord but find thee emptied,<br/>Living branch in Christ the Vine!<br/>Vessels of the world''s despising,<br/>Vessels weak and poor and base,<br/>Bearing wealth God''s heart is prizing,<br/>Glory from Christ''s blessed face.<br/>',NULL,3022,3022);
INSERT INTO stanza VALUES('E589','4','Oh to be but emptier, lowlier,<br/>Mean, unnoticed-and unknown,<br/>And to God a vessel holier,<br/>Filled with Christ and Christ alone!<br/>Naught of earth to cloud the glory,<br/>Naught of self the light to dim,<br/>Telling forth His wondrous story,<br/>Emptied to be filled with Him.<br/>',NULL,3023,3023);
INSERT INTO stanza VALUES('E590','1','Lo, from vessels, earthen only,<br/>Shining forth in ceaseless grace,<br/>Reaching weary hearts, and lonely,<br/>Beams the light from Jesus'' face!<br/>',NULL,3024,3024);
INSERT INTO stanza VALUES('E590','2','Christ, the light that fills the heavens<br/>Shining forth on earth beneath,<br/>Through His Spirit freely given<br/>Light of life ''midst shades of death;<br/>',NULL,3025,3025);
INSERT INTO stanza VALUES('E590','3','Down from heaven''s unclouded glory<br/>God Himself the treasure brought,<br/>Closing thus His love''s sweet story<br/>With His sweetest, deepest thought.<br/>',NULL,3026,3026);
INSERT INTO stanza VALUES('E590','4','Earthen vessels, marred, unsightly,<br/>But the treasure as of old,<br/>Fresh from glory, gleaming brightly,<br/>Heaven''s undimmed, unchanging gold.<br/>',NULL,3027,3027);
INSERT INTO stanza VALUES('E590','5','Vessels, broken, frail, yet bearing<br/>Through the hungry ages on<br/>Riches giv''n with hand unsparing-<br/>God''s great Gift, His precious Son!<br/>',NULL,3028,3028);
INSERT INTO stanza VALUES('E591','1','Not I, but Christ be honored, loved, exalted,<br/>Not I, but Christ be seen, be known and heard;<br/>Not I, but Christ in every look and action,<br/>Not I, but Christ in every thought and word.<br/>',NULL,3029,3029);
INSERT INTO stanza VALUES('E591','chorus','Oh, to be saved from myself, dear Lord,<br/>Oh, to be lost in Thee,<br/>Oh, that it may be no more I,<br/>But Christ that lives in me.<br/>',NULL,3030,3030);
INSERT INTO stanza VALUES('E591','2','Not I, but Christ to gently soothe in sorrow,<br/>Not I, but Christ to wipe the falling tear;<br/>Not I, but Christ to lift the weary burden,<br/>Not I, but Christ to hush away all fear.<br/>',NULL,3031,3031);
INSERT INTO stanza VALUES('E591','3','Christ, only Christ, no idle word e''er falling,<br/>Christ, only Christ, no needless bustling sound;<br/>Christ, only Christ, no self-important bearing,<br/>Christ, only Christ, no trace of I be found.<br/>',NULL,3032,3032);
INSERT INTO stanza VALUES('E591','4','Not I, but Christ my every need supplying,<br/>Not I, but Christ my strength and health to be;<br/>Christ, only Christ, for spirit, soul, and body,<br/>Christ, only Christ, live then Thy life in me.<br/>',NULL,3033,3033);
INSERT INTO stanza VALUES('E591','5','Christ, only Christ, ere long will fill my vision,<br/>Glory excelling soon, full soon I''ll see;<br/>Christ, only Christ, my every wish fulfilling,<br/>Christ, only Christ, my all in all to be.<br/>',NULL,3034,3034);
INSERT INTO stanza VALUES('E592','1','The earth absorbs the soft, refreshing rain,<br/>And sends it back in flow''rs and fruits again;<br/>So we receive Thy life so rich and free,<br/>And live it out for joy and praise to Thee.<br/>',NULL,3035,3035);
INSERT INTO stanza VALUES('E592','2','The moon receives the sun''s bright, golden light,<br/>And gives it forth to cheer the darksome night;<br/>So we receive the rays of light Divine,<br/>And with them on this darkened world we shine.<br/>',NULL,3036,3036);
INSERT INTO stanza VALUES('E592','3','''Tis by Thy love that I can love and bless<br/>The foes who seek to blast my happiness;<br/>Can e''en rejoice, when bearing wrong and shame,<br/>Thou deem''st me meet to suffer for Thy name.<br/>',NULL,3037,3037);
INSERT INTO stanza VALUES('E592','4','Naught but Thyself can satisfy my heart,<br/>Constrain my will from self and sin to part:<br/>In love so great Thou giv''st Thyself to me;<br/>That I may Thee express eternally.<br/>',NULL,3038,3038);
INSERT INTO stanza VALUES('E593','1','All I have in Adam is but sin and death,<br/>I in Christ inherit life and righteousness;<br/>When in flesh abiding, Adam I express,<br/>But when in the spirit Christ is manifest.<br/>',NULL,3039,3039);
INSERT INTO stanza VALUES('E593','2','When I am in Adam, though I may not sin,<br/>Unto death, a sinner, sentenced I have been;<br/>When in Christ I need not righteously to act,<br/>I''m already righteous, justified in fact.<br/>',NULL,3040,3040);
INSERT INTO stanza VALUES('E593','3','In the flesh I need no effort to express<br/>Marks of Adam''s nature and its sinfulness;<br/>In the spirit I need not to strive or strain,<br/>I can live as He is and in spirit reign.<br/>',NULL,3041,3041);
INSERT INTO stanza VALUES('E593','4','Thru my death with Christ, from Adam I am free,<br/>Thru my life with Christ, new life is given me!<br/>Minding not the flesh, old Adam cannot move,<br/>Minding just the spirit, life divine I prove.<br/>',NULL,3042,3042);
INSERT INTO stanza VALUES('E593','5','Minding just the spirit is God''s saving way,<br/>Minding just the spirit, Christ we will display;<br/>Minding just the spirit, we can overcome,<br/>Minding just the spirit, we the race may run.<br/>',NULL,3043,3043);
INSERT INTO stanza VALUES('E593','6','Minding just the spirit, we the cross will know,<br/>And His resurrection pow''r thru us will flow;<br/>Minding just the spirit, Christ will live thru me,<br/>And His life within will reach maturity.<br/>',NULL,3044,3044);
INSERT INTO stanza VALUES('E593','7','In the spirit Christ is life and all to me,<br/>Strengthening and blessing all-inclusively;<br/>Living in the spirit, holiness I prove,<br/>And the triune God within my heart doth move.<br/>',NULL,3045,3045);
INSERT INTO stanza VALUES('E594','1','Christ my very peace is<br/>And my life within;<br/>Sharing in the spirit<br/>I unite with Him.<br/>',NULL,3046,3046);
INSERT INTO stanza VALUES('E594','chorus','Following the Spirit,<br/>Living in the Lord,<br/>Life He doth supply me<br/>And His peace afford.<br/>',NULL,3047,3047);
INSERT INTO stanza VALUES('E594','2','To the Lord belonging,<br/>Bound I''ll never be,<br/>For the law of life now<br/>Sets me wholly free.<br/>',NULL,3048,3048);
INSERT INTO stanza VALUES('E594','3','Minding flesh no longer,<br/>I''ll the spirit mind;<br/>Self-will never follow,<br/>But the Spirit''s find.<br/>',NULL,3049,3049);
INSERT INTO stanza VALUES('E594','4','Christ within empow''rs me<br/>Spiritual to be!<br/>E''en my body quick''ning<br/>By His pow''r in me.<br/>',NULL,3050,3050);
INSERT INTO stanza VALUES('E594','5','Spirit with the spirit<br/>Witnesseth in one,<br/>I''m of God begotten,<br/>Heir with Christ the Son.<br/>',NULL,3051,3051);
INSERT INTO stanza VALUES('E595','1','There is always something over,<br/>When we taste our gracious Lord;<br/>Every cup He fills o''erfloweth,<br/>Rich supply He doth afford.<br/>Nothing narrow, nothing stinted,<br/>Ever issued from His store;<br/>To His own He gives full measure,<br/>Running over, evermore.<br/>To His own He gives full measure,<br/>Running over, evermore.<br/>',NULL,3052,3052);
INSERT INTO stanza VALUES('E595','2','There is always something over,<br/>When we, from the Father''s hand,<br/>Take our portion with thanksgiving,<br/>Praising for the things He planned.<br/>Satisfaction, full and deepening,<br/>All our need He doth supply.<br/>When the heart has tasted Jesus<br/>Its desires to satisfy.<br/>When the heart has tasted Jesus<br/>Its desires to satisfy.<br/>',NULL,3053,3053);
INSERT INTO stanza VALUES('E595','3','There is always something over,<br/>When we share in all His love;<br/>Unplumbed depths still lie beneath us,<br/>Unscaled heights rise far above.<br/>Human lips can never utter<br/>All His wondrous tenderness.<br/>We can only praise and wonder<br/>And His Name forever bless.<br/>We can only praise and wonder<br/>And His Name forever bless.<br/>',NULL,3054,3054);
INSERT INTO stanza VALUES('E596','1','Mine is the earth, the worlds in all their fulness;<br/>Mine, every ocean, river, plain, and hill;<br/>Mine are the stars within the heaven''s stillness,<br/>Mine are the clouds that wander at their will.<br/>',NULL,3055,3055);
INSERT INTO stanza VALUES('E596','2','Mine is the spring, when blossoms sweet are blowing,<br/>Wakened from slumb''ring neath the winter snow;<br/>Mine, summer''s wealth, with her bright colors glowing;<br/>Mine is the fruit rich autumn doth bestow.<br/>',NULL,3056,3056);
INSERT INTO stanza VALUES('E596','3','Mine, all the things created: praise the Giver!<br/>Fish, and all beasts, the birds upon the wing,<br/>Sun-loving butterflies-now and forever;<br/>Beauty and grace of every living thing.<br/>',NULL,3057,3057);
INSERT INTO stanza VALUES('E596','4','Mine, all things lovely, blessing every hour,<br/>Wealth of creation, over and around;<br/>Mine is the sun, with it life-giving power,<br/>Mine is the music wonderful of sound.<br/>',NULL,3058,3058);
INSERT INTO stanza VALUES('E596','5','Mine are the pillars which cannot be shaken-<br/>Truth in the Word, the Word that cannot fall.<br/>Mine is the wisdom which great thoughts awaken<br/>In a man''s soul, that this life is not all.<br/>',NULL,3059,3059);
INSERT INTO stanza VALUES('E596','6','Knowledge as needed, skill in all the doing,<br/>Mine, when kept closely for my Lord above;<br/>Beauty and wisdom, living streams e''er flowing<br/>Fresh from the springs of God, the God of love.<br/>',NULL,3060,3060);
INSERT INTO stanza VALUES('E596','7','Mine are the battles, triumph-shouts e''er ringing-<br/>Joy of the warriors for the truth and right;<br/>Mine are the trophies God''s brave ones are bringing,<br/>Heroes of the faith and overcoming might.<br/>',NULL,3061,3061);
INSERT INTO stanza VALUES('E596','8','Mine, mercies granted, and each new awaking,<br/>Every experience, and each soul that''s won;<br/>Mine, the confessions sinners poor are making,<br/>Yea, I am joined with them, one in God''s Son.<br/>',NULL,3062,3062);
INSERT INTO stanza VALUES('E596','9','One Lord in all, and all one in His Spirit,<br/>Heavenly fellowship earth has not known;<br/>Faith sees the riches we shall yet inherit,<br/>Glorious treasure laid up for His own.<br/>',NULL,3063,3063);
INSERT INTO stanza VALUES('E596','10','All in the bounds of earth and sea and heaven,<br/>Creation''s wonders and Thy grace are stored:<br/>Praise to Thee, Christ, for all the wealth<br/>Thou''st given!<br/>Poor in myself, but wealthy in the Lord!<br/>',NULL,3064,3064);
INSERT INTO stanza VALUES('E597','1','I know that my Redeemer lives<br/>And ever prays for me;<br/>A token of His love He gives,<br/>A pledge of liberty.<br/>',NULL,3065,3065);
INSERT INTO stanza VALUES('E597','2','I know that my Redeemer lives,<br/>A quick''ning Spirit He;<br/>I know eternal life He gives-<br/>Amazing grace-to me.<br/>',NULL,3066,3066);
INSERT INTO stanza VALUES('E597','3','I find Him lifting up my head;<br/>He brings salvation near;<br/>His presence make me free indeed,<br/>And He will soon appear.<br/>',NULL,3067,3067);
INSERT INTO stanza VALUES('E597','4','He wills that I should holy be:<br/>What can withstand His will?<br/>The counsel of His grace in me<br/>He surely shall fulfill.<br/>',NULL,3068,3068);
INSERT INTO stanza VALUES('E597','5','Jesus, I hang upon Thy word:<br/>I steadfastly believe<br/>Thou wilt return and claim me, Lord,<br/>And to Thyself receive.<br/>',NULL,3069,3069);
INSERT INTO stanza VALUES('E598','1','All fair within those children of the light,<br/>Though dark their brows beneath the desert sun;<br/>Mysterious joys, far hidden from all sight,<br/>The King of Glory giveth to each one;<br/>No thought of man has pictured them,<br/>No hand may touch that diadem;<br/>Within God''s light His own abide<br/>With hidden glory glorified.<br/>',NULL,3070,3070);
INSERT INTO stanza VALUES('E598','2','To earthly eyes they are as Adam''s race-<br/>They wear the earthly form, and scars of pain<br/>On them as on all sinners leave their trace;<br/>Their outward needs are those of other men.<br/>And theirs the forms of earthly life,<br/>Theirs sleeping, waking, want, and strife,<br/>Yet this they have that they despise<br/>What fairest seems to earthly eyes.<br/>',NULL,3071,3071);
INSERT INTO stanza VALUES('E598','3','And inwardly their life is from above,<br/>The Lord''s Almighty Word hath quickened them;<br/>Flames kindled from the everlasting Love,<br/>The children of the New Jerusalem;<br/>Their brethren are the saints in light,<br/>And songs of sweetness infinite<br/>They sing with them to God Most High,<br/>A deep and wondrous melody.<br/>',NULL,3072,3072);
INSERT INTO stanza VALUES('E598','4','They walk upon the earth, and dwell in heaven,<br/>Though pow''rless, guard the world with arms unseen;<br/>Deep peace to them in midst of strife is given,<br/>And all they wish they have, though poor and mean.<br/>Storms beat them, but may not destroy,<br/>Fast rooted in eternal joy;<br/>They walk as in the shade of death,<br/>Yet living on in silent faith.<br/>',NULL,3073,3073);
INSERT INTO stanza VALUES('E598','5','When Christ their Life shall be made manifest,<br/>When He shall come with all His pow''r to rule,<br/>Their glory, hidden long, shall be confessed;<br/>Arise and shine! O bright and beautiful!<br/>With Christ ye shall ascend on high,<br/>Victorious in His victory-<br/>The hidden light shall shine afar,<br/>Each saint an everlasting star.<br/>',NULL,3074,3074);
INSERT INTO stanza VALUES('E599','1','Lord, I was blind; I could not see<br/>In Thy marred visage any grace,<br/>But now the beauty of Thy face<br/>In radiant vision dawns on me.<br/>',NULL,3075,3075);
INSERT INTO stanza VALUES('E599','2','Lord, I was deaf; I could not hear<br/>The thrilling music of Thy voice;<br/>But now I hear Thee and rejoice,<br/>And all Thine uttered words are dear!<br/>',NULL,3076,3076);
INSERT INTO stanza VALUES('E599','3','Lord, I was dumb; I could not speak<br/>The grace and glory of Thy name;<br/>But now, as touched with living flame,<br/>My lips Thine eager praises wake.<br/>',NULL,3077,3077);
INSERT INTO stanza VALUES('E599','4','Lord, I was dead; I could not stir<br/>My lifeless soul to come to Thee;<br/>But now, since Thou hast quickened me,<br/>I rise from sin''s dark sepulcher.<br/>',NULL,3078,3078);
INSERT INTO stanza VALUES('E599','5','For Thou hast made the blind to see,<br/>The deaf to hear, the dumb to speak,<br/>The dead to live; and, lo, I break<br/>The chains of my captivity.<br/>',NULL,3079,3079);
INSERT INTO stanza VALUES('E600','1','My God, my Portion, and my Love,<br/>My everlasting All,<br/>I''ve none but Thee in heav''n above,<br/>Or on this earthly ball,<br/>Or on this earthly ball.<br/>',NULL,3080,3080);
INSERT INTO stanza VALUES('E600','2','What empty things are all the skies,<br/>And this inferior clod!<br/>There''s nothing here deserves my joys,<br/>There''s nothing like my God,<br/>There''s nothing like my God.<br/>',NULL,3081,3081);
INSERT INTO stanza VALUES('E600','3','To Thee I owe my wealth, and friends,<br/>And health, and safe abode;<br/>Thanks to Thy name for meaner things,<br/>But they are not my God,<br/>But they are not my God.<br/>',NULL,3082,3082);
INSERT INTO stanza VALUES('E600','4','How vain a toy is glittering wealth,<br/>If once compared to Thee!<br/>Or what''s my safety, or my health,<br/>Or all my friends to me,<br/>Or all the friends to me.<br/>',NULL,3083,3083);
INSERT INTO stanza VALUES('E600','5','Were I possessor of the earth,<br/>And called the stars my own,<br/>Without Thy graces and Thyself,<br/>I were a wretch undone,<br/>I were a wretch undone.<br/>',NULL,3084,3084);
INSERT INTO stanza VALUES('E600','6','Let others stretch their arms like seas,<br/>And grasp in all the shore;<br/>Grant me the visits of Thy grace,<br/>And I desire no more,<br/>And I desire no more.<br/>',NULL,3085,3085);
INSERT INTO stanza VALUES('E601','1','My heart is resting, O my God,<br/>I will give thanks and sing;<br/>My heart is at the secret source<br/>Of every precious thing.<br/>',NULL,3086,3086);
INSERT INTO stanza VALUES('E601','chorus','Oh, peace of God that passeth thought,<br/>I daily, hourly sing;<br/>My heart is at the secret source<br/>Of every precious thing.<br/>',NULL,3087,3087);
INSERT INTO stanza VALUES('E601','2','Now this frail vessel Thou hast made,<br/>No hand but Thine shall fill;<br/>The waters of the earth have failed,<br/>And I am thirsty still.<br/>',NULL,3088,3088);
INSERT INTO stanza VALUES('E601','3','I thirst for springs of heavenly life,<br/>And here all day they rise;<br/>I seek the treasure of Thy love,<br/>And close at hand it lies.<br/>',NULL,3089,3089);
INSERT INTO stanza VALUES('E601','4','A glad, new song is in my mouth,<br/>To long-loved music set,<br/>A song of praise for all the grace<br/>I have not tasted yet.<br/>',NULL,3090,3090);
INSERT INTO stanza VALUES('E601','5','I have a heritage of joy<br/>That yet I must not see;<br/>The hand that bled to make it mine<br/>Is keeping it for me.<br/>',NULL,3091,3091);
INSERT INTO stanza VALUES('E601','6','There is a certainty of love<br/>That sets my heart at rest;<br/>A calm assurance for today<br/>That to be poor is best.<br/>',NULL,3092,3092);
INSERT INTO stanza VALUES('E601','7','A prayer reposing on His truth,<br/>Who hath made all things mine;<br/>That draws my captive will to Him,<br/>And makes it one with Thine.<br/>',NULL,3093,3093);
INSERT INTO stanza VALUES('E602','1','O how glorious! O how holy!<br/>God is the eternal life!<br/>Full, unlimited, and pow''rful,<br/>Pure, and merciful, and bright!<br/>In this life are all His riches,<br/>All His nature, love and light.<br/>',NULL,3094,3094);
INSERT INTO stanza VALUES('E602','2','O how loving! O how gracious!<br/>God Himself is life to man!<br/>He in man hath made a spirit<br/>That He might fulfill His plan.<br/>''Tis His heart''s delight and longing<br/>E''er to be received by man.<br/>',NULL,3095,3095);
INSERT INTO stanza VALUES('E602','3','O what love and grace unbounding!<br/>God as life to man doth flow!<br/>He no more is hid in secret<br/>But Himself to man doth show,<br/>First in flesh and then as Spirit<br/>That His life all men may know.<br/>',NULL,3096,3096);
INSERT INTO stanza VALUES('E602','4','How approachable! How near us!<br/>God in Christ our life to be!<br/>Christ is God in flesh incarnate,<br/>Manifest for man to see.<br/>Died and risen, now He enters<br/>Into man, his life to be.<br/>',NULL,3097,3097);
INSERT INTO stanza VALUES('E602','5','O what wonder! As the Spirit<br/>God as life to man is shown!<br/>''Tis His other transformation,<br/>He as Spirit thus is known;<br/>Men convicting and inspiring,<br/>He within them makes His home.<br/>',NULL,3098,3098);
INSERT INTO stanza VALUES('E602','6','O how glorious! O how precious!<br/>Thus the triune God to know!<br/>First the Father in the Son came,<br/>Now the Son as Spirit flows.<br/>When in man the Spirit enters<br/>God as life He doth bestow.<br/>',NULL,3099,3099);
INSERT INTO stanza VALUES('E602','7','How mysterious, yet how real!<br/>God Himself now flows in me!<br/>In my heart, with me in oneness,<br/>He has come my life to be.<br/>Hallelujah! Hallelujah!<br/>I will praise unceasingly!<br/>',NULL,3100,3100);
INSERT INTO stanza VALUES('E603','1','Eternal Light! Eternal Light!<br/>How pure the soul must be<br/>When, placed within Thy searching sight,<br/>It shrinks not, but with calm delight<br/>Can live and look on Thee.<br/>',NULL,3101,3101);
INSERT INTO stanza VALUES('E603','2','The spirits that surround Thy throne<br/>May bear the burning bliss;<br/>But that is surely theirs alone,<br/>Since they have never, never known<br/>A fallen world like this.<br/>',NULL,3102,3102);
INSERT INTO stanza VALUES('E603','3','Oh, how shall I, whose native sphere<br/>Is dark, whose mind is dim,<br/>Before th'' Ineffable appear,<br/>And on my natural spirit bear<br/>The uncreated beam?<br/>',NULL,3103,3103);
INSERT INTO stanza VALUES('E603','4','There is a way for man to rise<br/>To Thee, sublime Abode;<br/>And Offering and a Sacrifice,<br/>A Holy Spirit''s energies,<br/>And Advocate with God:<br/>',NULL,3104,3104);
INSERT INTO stanza VALUES('E603','5','These, these prepare us for the sight<br/>Of holiness above;<br/>The sons of ignorance and night<br/>May dwell in the eternal Light,<br/>Through the eternal Love.<br/>',NULL,3105,3105);
INSERT INTO stanza VALUES('E604','1','Unto the hills around do I lift up<br/>My longing eyes;<br/>O whence for me shall my salvation come,<br/>From whence arise?<br/>From God the Lord doth come my certain aid,<br/>From God the Lord, who heaven and earth hath made.<br/>',NULL,3106,3106);
INSERT INTO stanza VALUES('E604','2','He will not suffer that thy foot be moved:<br/>Safe shalt thou be.<br/>No careless slumber shall His eyelids close,<br/>Who keepeth thee.<br/>Behold, He sleepeth not, He slumbereth ne''er,<br/>Who keepeth Israel in His holy care.<br/>',NULL,3107,3107);
INSERT INTO stanza VALUES('E604','3','Jehovah is Himself thy keeper true,<br/>Thy changeless shade;<br/>Jehovah thy defense on thy right hand<br/>Himself hath made.<br/>And thee no sun by day shall ever smite;<br/>No moon shall harm thee in the silent night.<br/>',NULL,3108,3108);
INSERT INTO stanza VALUES('E604','4','From every evil shall He keep thy soul,<br/>From every sin;<br/>Jehovah shall preserve thy going out,<br/>Thy coming in.<br/>Above thee, watching, He whom we adore<br/>Shall keep thee henceforth, yea, for evermore.',NULL,3109,3109);
INSERT INTO stanza VALUES('E605','1','My home is God Himself; Christ brought me there,<br/>And bade me dwell in Him, rejoicing there;<br/>He bore me where no foot but His hath trod,<br/>Within the holiest at home with God.<br/>O holy place! O home divinely fair!<br/>And we, God''s little ones, abiding there.<br/>',NULL,3110,3110);
INSERT INTO stanza VALUES('E605','2','A long, long road I traveled night and day,<br/>And sought to find within myself some way,<br/>Aught I could do, or feel to bring me near;<br/>Self effort failed, and I was filled with fear,<br/>And then I found Christ was the only way<br/>That I must come to Him and in Him stay.<br/>',NULL,3111,3111);
INSERT INTO stanza VALUES('E605','3','O wondrous place! O home divinely fair!<br/>And I, God''s little one, safe hidden there.<br/>Lord, as I dwell in Thee and Thou in me,<br/>So make me dead to everything but Thee;<br/>That as I rest within my home most fair,<br/>I''ll share my God in all and everywhere.<br/>',NULL,3112,3112);
INSERT INTO stanza VALUES('E606','1','Oh, how the thought of God attracts<br/>And draws the heart from earth,<br/>And sickens it of passing shows<br/>And dissipating mirth!<br/>',NULL,3113,3113);
INSERT INTO stanza VALUES('E606','2','''Tis not enough to save our souls,<br/>To shun th'' eternal fires;<br/>The thought of God will rouse the heart<br/>To more sublime desires.<br/>',NULL,3114,3114);
INSERT INTO stanza VALUES('E606','3','God only is the creature''s home,<br/>Though rough and straight the road;<br/>Yet nothing less can satisfy<br/>The love that longs for God.<br/>',NULL,3115,3115);
INSERT INTO stanza VALUES('E606','4','Oh, utter but the Name of God<br/>Down in your heart of hearts,<br/>And see how from the world at once<br/>All tempting light departs.<br/>',NULL,3116,3116);
INSERT INTO stanza VALUES('E606','5','A trusting heart, a yearning eye,<br/>Can win their way above;<br/>If mountains can be move by faith,<br/>Is there less power in love?<br/>',NULL,3117,3117);
INSERT INTO stanza VALUES('E606','6','How little of that road, my soul!<br/>How little hast thou gone!<br/>Take heart, and let the thought of God<br/>Allure thee further on.<br/>',NULL,3118,3118);
INSERT INTO stanza VALUES('E606','7','The freedom from all willful sin,<br/>The Christian''s daily task;<br/>Oh! These are graces far below<br/>What longing love would ask!<br/>',NULL,3119,3119);
INSERT INTO stanza VALUES('E606','8','The perfect way is hard to flesh;<br/>It is not hard to love;<br/>If thou wert sick from want of God,<br/>How swiftly wouldst thou move!<br/>',NULL,3120,3120);
INSERT INTO stanza VALUES('E606','9','Then keep thy conscience sensitive;<br/>No inward token miss:<br/>And go where grace entices thee-<br/>Perfection lies in this.<br/>',NULL,3121,3121);
INSERT INTO stanza VALUES('E607','1','O God, our help in ages past,<br/>Our hope for years to come,<br/>Our shelter from the stormy blast,<br/>And our eternal home.<br/>',NULL,3122,3122);
INSERT INTO stanza VALUES('E607','2','Under the shadow of Thy throne<br/>Thy saints have dwelt secure;<br/>Sufficient is Thine arm alone,<br/>And our defense is sure.<br/>',NULL,3123,3123);
INSERT INTO stanza VALUES('E607','3','Before the hills in order stood,<br/>Or earth received her frame,<br/>From everlasting Thou art God,<br/>To endless years the same.<br/>',NULL,3124,3124);
INSERT INTO stanza VALUES('E607','4','A thousand ages in Thy sight<br/>Are like an evening gone;<br/>Short as the watch that ends the night<br/>Before the rising sun.<br/>',NULL,3125,3125);
INSERT INTO stanza VALUES('E607','5','Time, like an ever-rolling stream,<br/>Bears all its sons away;<br/>They fly forgotten, as a dream<br/>Dies at the opening day.<br/>',NULL,3126,3126);
INSERT INTO stanza VALUES('E607','6','O God, our help in ages past,<br/>Our hope for years to come,<br/>Be Thou our guard while life shall last,<br/>And our eternal home.<br/>',NULL,3127,3127);
INSERT INTO stanza VALUES('E608','1','What mystery, the Father, Son and Spirit,<br/>In person three, in substance all are one.<br/>How glorious, this God our being enters<br/>To be our all, thru Spirit in the Son!<br/>',NULL,3128,3128);
INSERT INTO stanza VALUES('E608','chorus','The Triune God has now become our all!<br/>How wonderful! How glorious!<br/>This Gift divine we never can exhaust!<br/>How excellent! How marvelous!<br/>',NULL,3129,3129);
INSERT INTO stanza VALUES('E608','2','How rich the source, the Father as the fountain,<br/>And all this wealth He wants man to enjoy!<br/>O blessed fact, this vast exhaustless portion<br/>Is now for us forever to employ!<br/>',NULL,3130,3130);
INSERT INTO stanza VALUES('E608','3','How wonderful, the Son is God''s expression<br/>Come in the flesh to dwell with all mankind!<br/>Redemption''s work, how perfectly effective,<br/>That sinners we with God might oneness find.<br/>',NULL,3131,3131);
INSERT INTO stanza VALUES('E608','4','The Spirit is the Son''s transfiguration<br/>Come into us as life the full supply.<br/>Amazing fact, our spirit with the Spirit<br/>Now mingles and in oneness joins thereby!<br/>',NULL,3132,3132);
INSERT INTO stanza VALUES('E608','5','How real it is that God is now the Spirit<br/>For us to touch, experience day by day!<br/>Astounding fact, with God we are one spirit,<br/>And differ not in life in any way!<br/>',NULL,3133,3133);
INSERT INTO stanza VALUES('E609','1','I praise Thee for Thy mystery,<br/>That I may truly contact Thee;<br/>In unapproachable light Thou wast<br/>But now as Spirit nigh to me.<br/>',NULL,3134,3134);
INSERT INTO stanza VALUES('E609','2','The Father, Son, and Spirit, Thou,<br/>The triune God, my life fore''er;<br/>In me Thou art the full supply<br/>That I Thy holy nature share.<br/>',NULL,3135,3135);
INSERT INTO stanza VALUES('E609','3','The triune God the Spirit is,<br/>And comes as breath and wind to me;<br/>''Tis thus I may experience<br/>The Godhead''s wondrous mystery.<br/>',NULL,3136,3136);
INSERT INTO stanza VALUES('E609','4','All that the Father is and has<br/>In His beloved Son doth rest,<br/>And all the riches of the Son<br/>Are by the Spirit now possessed.<br/>',NULL,3137,3137);
INSERT INTO stanza VALUES('E609','5','The Spirit doth descend on me<br/>And to my spirit enters in,<br/>That He, the Father in the Son,<br/>My blessed portion be within.<br/>',NULL,3138,3138);
INSERT INTO stanza VALUES('E609','6','The Father is the fountainhead,<br/>The Son expression gives to Him;<br/>The Spirit is His very flow,<br/>As my reality within.<br/>',NULL,3139,3139);
INSERT INTO stanza VALUES('E609','7','The Father in the Son has come<br/>That God to man Himself may show;<br/>The Son as Spirit enters me<br/>That God I inwardly may know.<br/>',NULL,3140,3140);
INSERT INTO stanza VALUES('E609','8','The Father purposed that the Son<br/>Should be the first in everything;<br/>The Son the Father takes as Head<br/>And over all His headship brings.<br/>',NULL,3141,3141);
INSERT INTO stanza VALUES('E609','9','The Spirit perfectly desires<br/>That Christ, the Son, be glorified,<br/>And He reveals Him unto me,<br/>That He be fully testified.<br/>',NULL,3142,3142);
INSERT INTO stanza VALUES('E609','10','Thy final form the Spirit is,<br/>Our worship to receive within;<br/>If I Thy riches would enjoy,<br/>In spirit I must contact Him.<br/>',NULL,3143,3143);
INSERT INTO stanza VALUES('E609','11','If I in spirit worship Thee,<br/>In spirit live, in spirit pray,<br/>The Holy Spirit I will touch<br/>And Thee enjoy in every way.<br/>',NULL,3144,3144);
INSERT INTO stanza VALUES('E610','1','God''s Spirit His transmission is,<br/>In Him God enters into us;<br/>It is in Him that God in Christ<br/>May be experienced by us.<br/>',NULL,3145,3145);
INSERT INTO stanza VALUES('E610','2','God as the Father is the source,<br/>And God the Son doth Him express;<br/>God as the Spirit enters us,<br/>That God as all we may possess.<br/>',NULL,3146,3146);
INSERT INTO stanza VALUES('E610','3','The Father, who is veiled in light,<br/>The Son to man hath fully shown;<br/>The Spirit then transmitteth Him<br/>That He may inwardly be known.<br/>',NULL,3147,3147);
INSERT INTO stanza VALUES('E610','4','The Son within the Father is,<br/>And now the Spirit is the Son.<br/>The Spirit, Son, and Father God<br/>Are now in us and with us one.<br/>',NULL,3148,3148);
INSERT INTO stanza VALUES('E610','5','God as the Father in the Son<br/>Has been embodied and expressed,<br/>And God the Spirit is the Son''s<br/>Reality to be possessed.<br/>',NULL,3149,3149);
INSERT INTO stanza VALUES('E610','6','May God the Father''s love to us<br/>In God the Son as grace be known,<br/>Thru God the Spirit''s fellowship,<br/>That God our portion we may own.<br/>',NULL,3150,3150);
INSERT INTO stanza VALUES('E611','1','God''s glorious substance Spirit is,<br/>His essence, holy and divine;<br/>To contact God and Him enjoy,<br/>His Spirit I must touch with mine.<br/>',NULL,3151,3151);
INSERT INTO stanza VALUES('E611','2','The spirit is the innermost,<br/>The part of man most deep and real;<br/>If he would contact God in life,<br/>''Tis with the spirit he must deal.<br/>',NULL,3152,3152);
INSERT INTO stanza VALUES('E611','3','The worship which the Father seeks<br/>Is in the spirit''s strength alone;<br/>His Spirit into man''s would come,<br/>That His and man''s may thus be one.<br/>',NULL,3153,3153);
INSERT INTO stanza VALUES('E611','4','When Spirit unto spirit calls<br/>The two commingle and are one;<br/>Man''s spirit is the Spirit''s home,<br/>The Spirit doth man''s life become.<br/>',NULL,3154,3154);
INSERT INTO stanza VALUES('E611','5','Man''s spirit must God''s Spirit touch<br/>If in God''s fulness he would live;<br/>''Tis only with the spirit thus<br/>That he to God may worship give.<br/>',NULL,3155,3155);
INSERT INTO stanza VALUES('E611','6','In ministry and fellowship<br/>Man to the spirit we must bring;<br/>All ministry should turn to prayer,<br/>Spirit to spirit answering.<br/>',NULL,3156,3156);
INSERT INTO stanza VALUES('E611','7','In spirit we must pray and serve,<br/>In spirit touch the life divine,<br/>In spirit grow, in spirit build,<br/>That Christ thru us may fully shine.<br/>',NULL,3157,3157);
INSERT INTO stanza VALUES('E611','8','Lord, to the spirit I would turn<br/>And learn to truly contact Thee;<br/>Thy Spirit thus will flow with mine<br/>And overflow eternally.<br/>',NULL,3158,3158);
INSERT INTO stanza VALUES('E612','1','God intends that all His being<br/>Be my full supply;<br/>With Him I must be united,<br/>In spirit nigh.<br/>',NULL,3159,3159);
INSERT INTO stanza VALUES('E612','chorus','All God''s being, all His riches<br/>In the Spirit flow;<br/>I must exercise my spirit<br/>Him to know.<br/>',NULL,3160,3160);
INSERT INTO stanza VALUES('E612','2','All the riches of His nature<br/>He has given me;<br/>I must touch Him in the spirit,<br/>These to see.<br/>',NULL,3161,3161);
INSERT INTO stanza VALUES('E612','3','With the mind we understand Him,<br/>With the spirit touch;<br/>Those who never use the spirit<br/>Lack very much.<br/>',NULL,3162,3162);
INSERT INTO stanza VALUES('E612','4','When to messages I listen,<br/>I must pray them in;<br/>Thus the word will be digested<br/>From within.<br/>',NULL,3163,3163);
INSERT INTO stanza VALUES('E612','5','When the Word of God I study,<br/>I must touch the Lord;<br/>If in mind and not in spirit,<br/>Dead is the Word.<br/>',NULL,3164,3164);
INSERT INTO stanza VALUES('E612','6','O what riches, O what glory<br/>In the Spirit shine!<br/>When I exercise my spirit,<br/>All are mine.<br/>',NULL,3165,3165);
INSERT INTO stanza VALUES('E613','1','I would commune with Thee, my God;<br/>E''en to Thy seat I come;<br/>I leave my joys, I leave my sins,<br/>And seek in Thee my home.<br/>I leave my joys, I leave my sins,<br/>And seek in Thee my home.<br/>',NULL,3166,3166);
INSERT INTO stanza VALUES('E613','2','I stand upon the mount of God,<br/>With sunlight in my soul;<br/>I see the storms in vales beneath,<br/>I hear the thunder''s roll.<br/>I see the storms in vales beneath,<br/>I hear the thunder''s roll.<br/>',NULL,3167,3167);
INSERT INTO stanza VALUES('E613','3','But I am calm with Thee, my God,<br/>Beneath these glorious skies;<br/>And to the height on which I stand<br/>Nor storms nor clouds can rise.<br/>And to the height on which I stand<br/>Nor storms nor clouds can rise.<br/>',NULL,3168,3168);
INSERT INTO stanza VALUES('E613','4','Oh, this is life! Oh, this is joy,<br/>My God, to find Thee so;<br/>Thy face to see, Thy voice to hear,<br/>And all Thy love to know.<br/>Thy face to see, Thy voice to hear,<br/>And all Thy love to know.<br/>',NULL,3169,3169);
INSERT INTO stanza VALUES('E614','1','Nearer, my God, to Thee,<br/>Nearer to Thee;<br/>E''en though it be a cross<br/>That raiseth me,<br/>Still all my song shall be<br/>Nearer, my God, to Thee,<br/>Nearer, my God, to Thee,<br/>Nearer to Thee.<br/>',NULL,3170,3170);
INSERT INTO stanza VALUES('E614','2','Though, like a wanderer,<br/>The sun gone down,<br/>Darkness comes over me,<br/>My rest a stone;<br/>Yet in my dreams I''d be<br/>Nearer, my God, to Thee,<br/>Nearer, my God, to Thee,<br/>Nearer to Thee.<br/>',NULL,3171,3171);
INSERT INTO stanza VALUES('E614','3','There let me see the sight,<br/>An open heaven;<br/>All that Thou sendest me,<br/>In mercy given;<br/>Angels to beckon me<br/>Nearer, my God, to Thee,<br/>Nearer, my God, to Thee,<br/>Nearer to Thee.<br/>',NULL,3172,3172);
INSERT INTO stanza VALUES('E614','4','Then, with my waking thoughts<br/>Bright with Thy praise,<br/>Out of my stony griefs<br/>Bethel I''ll raise,<br/>So by my woes to be<br/>Nearer, my God, to Thee,<br/>Nearer, my God, to Thee,<br/>Nearer to Thee.<br/>',NULL,3173,3173);
INSERT INTO stanza VALUES('E615','1','Begin the day with God!<br/>He is thy Sun and Day!<br/>His is the radiance of thy dawn;<br/>To Him address thy lay.<br/>',NULL,3174,3174);
INSERT INTO stanza VALUES('E615','2','Sing a new song at morn!<br/>Join the glad woods and hills;<br/>Join the fresh winds and seas and plains,<br/>Join the bright flowers and rills.<br/>',NULL,3175,3175);
INSERT INTO stanza VALUES('E615','3','Sing thy first song to God!<br/>Not to thy fellow men;<br/>Not to the creatures of His hand,<br/>But to the glorious One.<br/>',NULL,3176,3176);
INSERT INTO stanza VALUES('E615','4','Take thy first walk with God!<br/>Let Him go forth with thee;<br/>By stream, or sea, or mountain path,<br/>Seek still His company.<br/>',NULL,3177,3177);
INSERT INTO stanza VALUES('E615','5','Thy first transaction be<br/>With God Himself above;<br/>So shall thy business prosper well<br/>And all the day be love.<br/>',NULL,3178,3178);
INSERT INTO stanza VALUES('E616','1','Day is dying in the west,<br/>Heav''n is touching earth with rest,<br/>Wait and worship while the night<br/>Sets her evening lamps alight<br/>Through all the sky.<br/>',NULL,3179,3179);
INSERT INTO stanza VALUES('E616','chorus','Holy, holy, holy,<br/>Lord God of Hosts!<br/>Heav''n and earth are full of Thee!<br/>Heav''n and earth are praising Thee,<br/>O Lord, most high!<br/>',NULL,3180,3180);
INSERT INTO stanza VALUES('E616','2','Lord of life, beneath the dome<br/>Of the universe, Thy home,<br/>Gather us, who seek Thy face,<br/>To fold of Thy embrace,<br/>For Thou art nigh.<br/>',NULL,3181,3181);
INSERT INTO stanza VALUES('E616','3','While the deepening shadows fall,<br/>Heart of love, enfolding all,<br/>Through the glory and the grace<br/>Of the stars that veil Thy face,<br/>Our hearts ascend.<br/>',NULL,3182,3182);
INSERT INTO stanza VALUES('E617','1','Thou sweet, beloved will of God,<br/>My anchor ground, my fortress hill,<br/>My spirit''s silent, fair abode,<br/>In Thee I hide me and am still.<br/>',NULL,3183,3183);
INSERT INTO stanza VALUES('E617','2','O Will, that willest good alone,<br/>Lead Thou the way, Thou guidest best;<br/>A little child, I follow one,<br/>And, trusting, lean upon Thy breast.<br/>',NULL,3184,3184);
INSERT INTO stanza VALUES('E617','3','God''s will doth make the bitter sweet,<br/>And all is well when it is done;<br/>Unless His will doth hallow it,<br/>The glory of all joy is gone.<br/>',NULL,3185,3185);
INSERT INTO stanza VALUES('E617','4','Thy beautiful sweet will, my God,<br/>Hold fast in its sublime embrace<br/>My captive will, a gladsome bird,<br/>Prisoned in such a realm of grace.<br/>',NULL,3186,3186);
INSERT INTO stanza VALUES('E617','5','Within this place of certain good<br/>Love evermore expands her wings,<br/>Or nestling in Thy perfect choice,<br/>Abides content with what it brings.<br/>',NULL,3187,3187);
INSERT INTO stanza VALUES('E617','6','Oh, lightest burden, sweetest yoke;<br/>It lifts, it bears my happy soul,<br/>It giveth wings to this poor heart;<br/>My freedom is Thy grand control.<br/>',NULL,3188,3188);
INSERT INTO stanza VALUES('E617','7','Upon God''s will I lay me down,<br/>As child upon its mother''s breast;<br/>No silken couch, nor softest bed,<br/>Could ever give me such deep rest.<br/>',NULL,3189,3189);
INSERT INTO stanza VALUES('E617','8','Thy wonderful grand will, my God,<br/>With triumph now I make it mine;<br/>And faith shall cry a joyous Yes<br/>To every dear command of Thine.<br/>',NULL,3190,3190);
INSERT INTO stanza VALUES('E618','1','On a hill far away stood an old rugged cross,<br/>The emblem of suff''ring and shame,<br/>And I love that old cross where the Dearest and Best<br/>For a world of lost sinners was slain.<br/>',NULL,3191,3191);
INSERT INTO stanza VALUES('E618','chorus','So I''ll cherish the old rugged cross,<br/>Till my trophies at last I lay down;<br/>I will cling to the old rugged cross,<br/>And exchange it some day for a crown.<br/>',NULL,3192,3192);
INSERT INTO stanza VALUES('E618','2','Oh, that old rugged cross, so despised by the world,<br/>Has a wondrous attraction to me;<br/>For the dear Lamb of God left His glory above,<br/>To bear it to dark Calvary.<br/>',NULL,3193,3193);
INSERT INTO stanza VALUES('E618','3','In the old rugged cross, stained with blood so divine,<br/>A wondrous beauty I see;<br/>For ''twas on that old cross Jesus suffered and died,<br/>To pardon and sanctify me.<br/>',NULL,3194,3194);
INSERT INTO stanza VALUES('E619','1','In the cross of Christ I glory,<br/>Tow''ring o''er the wrecks of time;<br/>All the light of sacred story<br/>Gather round its head sublime.<br/>',NULL,3195,3195);
INSERT INTO stanza VALUES('E619','2','When the woes of life o''ertake me,<br/>Hopes deceive, and fears annoy,<br/>Never shall the cross forsake me,<br/>Lo! It glows with peace and joy.<br/>',NULL,3196,3196);
INSERT INTO stanza VALUES('E619','3','When the sun of bliss is beaming<br/>Light and love upon my way,<br/>From the cross the radiance streaming<br/>Adds more luster to the day.<br/>',NULL,3197,3197);
INSERT INTO stanza VALUES('E619','4','Bane and blessing, pain and pleasure,<br/>By the cross are sanctified;<br/>Peace is there that knows now measure,<br/>Joys that through all time abide.<br/>',NULL,3198,3198);
INSERT INTO stanza VALUES('E620','1','The cross it standeth fast,<br/>Hallelujah! Hallelujah!<br/>Defying every blast,<br/>Hallelujah! Hallelujah!<br/>The winds of hell have blown,<br/>The world its hate hath shown,<br/>Yet it is not overthrown,<br/>Hallelujah for the cross!<br/>',NULL,3199,3199);
INSERT INTO stanza VALUES('E620','chorus','Hallelujah, hallelujah,<br/>Hallelujah for the cross;<br/>Hallelujah, hallelujah,<br/>It shall never suffer loss.<br/>',NULL,3200,3200);
INSERT INTO stanza VALUES('E620','2','It is the old cross still,<br/>Hallelujah! Hallelujah!<br/>Its triumph let us tell,<br/>Hallelujah! Hallelujah!<br/>The grace of God here shone,<br/>Through Christ the blessed Son,<br/>Who hath redemption won,<br/>Hallelujah for the cross!<br/>',NULL,3201,3201);
INSERT INTO stanza VALUES('E620','3','''Twas here the debt was paid,<br/>Hallelujah! Hallelujah!<br/>Our sins on Jesus laid,<br/>Hallelujah! Hallelujah!<br/>So round the cross we sing<br/>Of Christ, our offering,<br/>Of Christ, our offering,<br/>Of Christ, our living King,<br/>Hallelujah for the cross!<br/>',NULL,3202,3202);
INSERT INTO stanza VALUES('E621','1','Beneath the cross of Jesus<br/>I fain would take my stand,<br/>The shadow of a might Rock<br/>Within a weary land;<br/>A rest upon the way,<br/>From the burning of the noontide heat,<br/>And the burden of the day.<br/>',NULL,3203,3203);
INSERT INTO stanza VALUES('E621','2','Oh, safe and happy shelter!<br/>Oh, refuge tried and sweet!<br/>Oh, trysting place where heaven''s love<br/>And heaven''s justice meet.<br/>As to the holy patriarch<br/>That wondrous dream was given,<br/>So is my Savior by the cross<br/>A ladder up to heaven.<br/>',NULL,3204,3204);
INSERT INTO stanza VALUES('E621','3','There lies beneath its shadow,<br/>But on the farther side,<br/>The darkness of an awful grave<br/>That gapes both deep and wide;<br/>And there between us stands the cross,<br/>Two arms outstretched to save,<br/>Like a watchman set to guard the way<br/>From that eternal grave.<br/>',NULL,3205,3205);
INSERT INTO stanza VALUES('E621','4','Upon that cross of Jesus<br/>Mine eyes at times can see<br/>The very dying form of One,<br/>Who suffered there for me;<br/>And from my smitten heart, with tears,<br/>Two wonders I confess,<br/>The wonders of His glorious love,<br/>And my own worthlessness.<br/>',NULL,3206,3206);
INSERT INTO stanza VALUES('E621','5','I take, O cross, thy shadow<br/>For my abiding place;<br/>I ask no other sunshine than<br/>The sunshine of His face;<br/>Content to let the world go by,<br/>To know no gain nor loss,<br/>My sinful self my only shame,<br/>My glory all the cross.<br/>',NULL,3207,3207);
INSERT INTO stanza VALUES('E622','1','If we take up the cross, will we but suffer pain?<br/>Nay, if we bear the cross, be sure that we will die!<br/>The meaning of the cross is that we may be slain;<br/>The cross experienced the self will crucify.<br/>',NULL,3208,3208);
INSERT INTO stanza VALUES('E622','2','Divine deliverance e''er slays man by the cross;<br/>Though cruel it may seem, it is a grand release.<br/>Christ ne''er will be our life if we escape the cross;<br/>Christ ne''er will be expressed but by our sure decease.<br/>',NULL,3209,3209);
INSERT INTO stanza VALUES('E622','3','The cross''s final goal, that God''s will be fulfilled;<br/>His will''s arch enemy is but the self of man.<br/>If self be done away and all the soul-life killed,<br/>God''s will shall then prevail and prospered be His plan.<br/>',NULL,3210,3210);
INSERT INTO stanza VALUES('E623','1','There is no gain but by a loss;<br/>We cannot save but by the cross,<br/>The corn of wheat to multiply<br/>Must fall into the ground and die;<br/>O should a soul alone remain<br/>When it a hundredfold can gain?<br/>O should a soul alone remain<br/>When it a hundredfold can gain?<br/>',NULL,3211,3211);
INSERT INTO stanza VALUES('E623','2','Our souls are held by all they hold;<br/>Slaves still are slaves in chains of gold;<br/>To whatsoever we may cling,<br/>We make it a soul-chaining thing.<br/>Whether it be a life or land,<br/>And dear as our right eye or hand.<br/>Whether it be a life or land,<br/>And dear as our right eye or hand.<br/>',NULL,3212,3212);
INSERT INTO stanza VALUES('E623','3','Wherever you ripe field behold,<br/>Waving to God their sheaves of gold,<br/>Be sure some corn of wheat had died,<br/>Some saintly soul been crucified;<br/>Someone has suffered, wept and prayed,<br/>And fought hell''s legions undismayed.<br/>Someone has suffered, wept and prayed,<br/>And fought hell''s legions undismayed.<br/>',NULL,3213,3213);
INSERT INTO stanza VALUES('E624','1','The heavier the cross, the nearer God;<br/>No cross without, no God within!<br/>The prince of darkness thus is trod,<br/>Amid the world''s false glare and din.<br/>Oh, happy he, with all his loss,<br/>Whom God hath set beneath the cross.<br/>',NULL,3214,3214);
INSERT INTO stanza VALUES('E624','2','The heavier the cross, the better saint;<br/>This is the touchstone God applies.<br/>The gardens many would be faint,<br/>Unwet by showers from weeping eyes!<br/>The gold by fire is purified;<br/>The saint is by much trouble tried.<br/>',NULL,3215,3215);
INSERT INTO stanza VALUES('E624','3','The heavier the cross, the stronger faith:<br/>The loaded palm strikes deeper root;<br/>The vine juice sweetly issueth<br/>When men have pressed the clustered fruit;<br/>And courage grows where dangers come,<br/>Like pearls beneath the salty foam.<br/>',NULL,3216,3216);
INSERT INTO stanza VALUES('E624','4','The heavier the cross, the deeper prayer;<br/>The bruised herbs most fragrant are.<br/>If sky and wind were always fair,<br/>The sailor would not watch the star;<br/>And David''s Psalms had ne''er been sung<br/>If grief his heart had never wrung.<br/>',NULL,3217,3217);
INSERT INTO stanza VALUES('E624','5','The heavier the cross, the more inspired;<br/>From vales to climb to mountain crest;<br/>The pilgrim, of the desert tried,<br/>Longs for the Canaan of his rest.<br/>The dove has here no rest in sight,<br/>And to the ark she wings her flight.<br/>',NULL,3218,3218);
INSERT INTO stanza VALUES('E624','6','The heavier the cross, the easier to die;<br/>Death is a kinder face to see;<br/>Our life''s decay we dare defy,<br/>From life''s distress we then are free.<br/>The cross sublimely lifts our faith<br/>To Him who triumphed over death.<br/>',NULL,3219,3219);
INSERT INTO stanza VALUES('E624','7','Thou Crucified! The cross I bear.<br/>The longer, may it dearer be;<br/>And lest I faint while ling''ring here,<br/>Implant Thou such a heart in me<br/>That faith and love may flourish e''er,<br/>Till for the cross the crown I wear.<br/>',NULL,3220,3220);
INSERT INTO stanza VALUES('E625','1','''Tis my happiness below<br/>Not to live without the cross;<br/>But the Savior''s pow''r to know<br/>Sanctifying every loss.<br/>',NULL,3221,3221);
INSERT INTO stanza VALUES('E625','2','Trail must and will befall;<br/>But with humble faith to see<br/>Love inscribed upon them all-<br/>This is happiness to me.<br/>',NULL,3222,3222);
INSERT INTO stanza VALUES('E625','3','Did I meet no trial here,<br/>No chastisement by the way,<br/>Might I not with reason fear<br/>I should prove a castaway?<br/>',NULL,3223,3223);
INSERT INTO stanza VALUES('E625','4','Trails make the promise sweet;<br/>Trials give new life to prayer;<br/>Bring me to my Savior''s feet,<br/>Lay me low and keep me there.<br/>',NULL,3224,3224);
INSERT INTO stanza VALUES('E626','1','Olives that have known no pressure<br/>No oil can bestow;<br/>If the grapes escape the winepress,<br/>Cheering wine can never flow;<br/>Spikenard only through the crushing,<br/>Fragrance can diffuse.<br/>Shall I then, Lord, shrink from suff''ring<br/>Which Thy love for me would choose?<br/>',NULL,3225,3225);
INSERT INTO stanza VALUES('E626','chorus','Each blow I suffer<br/>Is true gain to me.<br/>In the place of what Thou takest<br/>Thou dost give Thyself to me.<br/>',NULL,3226,3226);
INSERT INTO stanza VALUES('E626','2','Do my heartstrings need Thy stretching,<br/>Songs divine to prove?<br/>Do I need for sweetest music<br/>Cruel treatment of Thy love?<br/>Lord, I fear no deprivation<br/>If it draws to Thee;<br/>I would yield in full surrender<br/>All Thy heart of love to see.<br/>',NULL,3227,3227);
INSERT INTO stanza VALUES('E626','3','I''m ashamed, my Lord, for seeking<br/>Self to guard always;<br/>Though Thy love has done its stripping,<br/>Yet I''ve been compelled this way.<br/>Lord, according to Thy pleasure<br/>Fully work on me;<br/>Heeding not my human feelings,<br/>Only do what pleases Thee.<br/>',NULL,3228,3228);
INSERT INTO stanza VALUES('E626','4','If Thy mind and mine should differ,<br/>Still pursue Thy way;<br/>If Thy pleasure means my sorrow,<br/>Still my heart shall answer, "Yea!"<br/>''Tis my deep desire to please Thee,<br/>Though I suffer loss;<br/>E''en though Thy delight and glory<br/>Mean that I endure the cross.<br/>',NULL,3229,3229);
INSERT INTO stanza VALUES('E626','5','Oh, I''ll praise Thee, e''en if weeping<br/>Mingle with my song.<br/>Thine increasing sweetness calls forth<br/>Grateful praises all day long.<br/>Thou hast made Thyself more precious<br/>Than all else to me:<br/>Thou increase and I decrease, Lord-<br/>This is now my only plea.<br/>',NULL,3230,3230);
INSERT INTO stanza VALUES('E627','1','Lord, day by day I view Thy wondrous Cross<br/>On Calvary!<br/>And day by day I stretch my hands thereon<br/>And die with Thee.<br/>',NULL,3231,3231);
INSERT INTO stanza VALUES('E627','2','I "glory in the Cross" most loving Lord,<br/>Because I know<br/>It is the power to save and satisfy,<br/>Where''er I go.<br/>',NULL,3232,3232);
INSERT INTO stanza VALUES('E627','3','The daily Cross becomes the deepest joy,<br/>For just beyond<br/>The Cross, I clearly see how Cross and Crown<br/>Do correspond.<br/>',NULL,3233,3233);
INSERT INTO stanza VALUES('E627','4','Oh, gracious Lord, how sweet to take from Thee<br/>The daily Cross!<br/>And know that I can never separate<br/>Its gain and loss.<br/>',NULL,3234,3234);
INSERT INTO stanza VALUES('E627','5','The daily Cross is daily loss to all<br/>That keeps from Thee;<br/>The daily Cross is daily gain of all<br/>Thou art for me.<br/>',NULL,3235,3235);
INSERT INTO stanza VALUES('E628','1','Via Bethlehem we journey,<br/>We whose hearts on God are set;<br/>Babe-like souls of Jesus learning,<br/>While our cheeks with tears are wet;<br/>For the manger and the stable<br/>Are not pleasant to our eyes,<br/>But our feet must follow Jesus,<br/>If our hands would grasp the prize.<br/>',NULL,3236,3236);
INSERT INTO stanza VALUES('E628','2','Via Nazareth! The pathway<br/>Narrows still as on we go,<br/>Years of toil none understanding,<br/>Yet God teaches us to know<br/>That the servant is not greater<br/>Than the Lord, who through long years<br/>Hid Himself from this world''s glory,<br/>Follow Him! Count not the tears.<br/>',NULL,3237,3237);
INSERT INTO stanza VALUES('E628','3','Via Galilee, we see Him!<br/>Stones are hurled, and cursed hissed<br/>By the men who gather round Him,<br/>Has He not the pathway missed?<br/>No! Unharmed the Savior passes,<br/>And this rough bit of the way<br/>We must travel, since like Jesus,<br/>Nothing can our purpose stay.<br/>',NULL,3238,3238);
INSERT INTO stanza VALUES('E628','4','Via too, the awful anguish<br/>Of the hours beneath the trees,<br/>Where the host of Satan linger,<br/>Awful hours of anguish these!<br/>Yet we fail not, for God''s angels<br/>Minister to us, and say,<br/>"Look, beloved, at the glory,<br/>Conflict is but for a day!"<br/>',NULL,3239,3239);
INSERT INTO stanza VALUES('E628','5','Then the Cross! For via Calvary<br/>Every royal soul must go;<br/>Here we draw the veil, for Jesus<br/>Only can the pathway show;<br/>"If we suffer with Him," listen,<br/>Just a little, little while,<br/>And the memory will have faded<br/>In the glory of His smile!<br/>',NULL,3240,3240);
INSERT INTO stanza VALUES('E628','6','Then the grave, with dear ones weeping,<br/>Knowing that all life had fled;<br/>(Fellow-pilgrims, art thou numbered<br/>With the men the world calls dead?)<br/>Thence we rise, and live with Jesus,<br/>Throned above the world''s mad strife,<br/>Gladly forfeiting forever,<br/>All that worldlings count as life.<br/>',NULL,3241,3241);
INSERT INTO stanza VALUES('E628','7','On we press! And yonder gleaming,<br/>Nearer every day, we see<br/>The great walls of that fair city,<br/>God had built for such as we;<br/>And we catch the tender music<br/>Of the choirs that sing of One<br/>Who once died to have us with Him<br/>In His kingdom, on the throne.<br/>',NULL,3242,3242);
INSERT INTO stanza VALUES('E628','8','Just a few more miles, beloved!<br/>And our feet shall ache no more;<br/>No more sin, and no more sorrow,<br/>Hush thee, Jesus went before;<br/>And I hear Him sweetly whispering,<br/>"Faint not, fear not, still press on,<br/>For it may be ere tomorrow,<br/>The long journey will be done."<br/>',NULL,3243,3243);
INSERT INTO stanza VALUES('E629','1','Hast thou no scar?<br/>No hidden scar on foot, or side, or hand?<br/>I hear thee sung throughout the land,<br/>I hear them hail thy shining star,<br/>Hast thou no scar? No scar?<br/>',NULL,3244,3244);
INSERT INTO stanza VALUES('E629','2','Hast thou no wound?<br/>Yet I was wounded by the archers, spent,<br/>Leaned Me against a tree; and rent<br/>By ravening beasts ''round Me, I swooned:<br/>Hast thou not wound? No wound?<br/>',NULL,3245,3245);
INSERT INTO stanza VALUES('E629','3','No wound? No scar?<br/>Yet, as the Master shall the servant be,<br/>And pierced the feet that follow Me;<br/>But whole? Can he have followed far<br/>Who has no wound nor scar?<br/>',NULL,3246,3246);
INSERT INTO stanza VALUES('E630','1','The way of the Cross means sacrifice,<br/>As to God you yield your all<br/>To be laid on the altar, the place of death,<br/>Where fire will surely fall.<br/>',NULL,3247,3247);
INSERT INTO stanza VALUES('E630','chorus','''Tis the way of the Cross, are you willing for this?<br/>What does bearing the Cross mean to you?<br/>You who''ve given yourself, your all to God!<br/>To God are you wholly true?<br/>',NULL,3248,3248);
INSERT INTO stanza VALUES('E630','2','As the voice of song and prayer we raise,<br/>How easy to say, We give all;<br/>Till some rougher cross lies just before,<br/>And sterner is duty''s call.<br/>',NULL,3249,3249);
INSERT INTO stanza VALUES('E630','3','Do you falter then, or, true to death,<br/>Just die on the cross in the way,<br/>Till the fulness of life from the Living One<br/>Is filling you day by day?<br/>',NULL,3250,3250);
INSERT INTO stanza VALUES('E630','4','''Tis the plan of life, for you die to live,<br/>One with Jesus crucified;<br/>With the life alone to be lived through you,<br/>Of the Risen, the Glorified.<br/>',NULL,3251,3251);
INSERT INTO stanza VALUES('E631','1','If I''d know Christ''s risen power,<br/>I must ever love the Cross;<br/>Life from death alone arises;<br/>There''s no gain except by loss.<br/>',NULL,3252,3252);
INSERT INTO stanza VALUES('E631','chorus','If no death, no life,<br/>If no death, no life;<br/>Life from death alone arises;<br/>If no death, no life.<br/>',NULL,3253,3253);
INSERT INTO stanza VALUES('E631','2','If I''d have Christ formed within me,<br/>I must breathe my final breath,<br/>Live within the Cross''s shadow,<br/>Put my soul-life e''er to death.<br/>',NULL,3254,3254);
INSERT INTO stanza VALUES('E631','3','If God thru th'' Eternal Spirit<br/>Nail me ever with the Lord;<br/>Only then as death is working<br/>Will His life thru me be poured.<br/>',NULL,3255,3255);
INSERT INTO stanza VALUES('E632','1','Never further than Thy Cross,<br/>Never higher than Thy feet,<br/>Here earth''s precious things seem dross,<br/>Here earth''s bitter things grow sweet.<br/>',NULL,3256,3256);
INSERT INTO stanza VALUES('E632','2','Gazing thus our sin we see,<br/>Learn Thy love while gazing thus;<br/>Sin which laid the Cross on Thee;<br/>Love which bore the Cross for us.<br/>',NULL,3257,3257);
INSERT INTO stanza VALUES('E632','3','Here we learn to serve and give,<br/>And rejoicing, self deny;<br/>Here we gather love to live;<br/>Here we gather faith to die.<br/>',NULL,3258,3258);
INSERT INTO stanza VALUES('E632','4','Symbols of our liberty<br/>And our service here unite;<br/>Captives, by Thy Cross set free;<br/>Soldiers of Thy Cross, we fight.<br/>',NULL,3259,3259);
INSERT INTO stanza VALUES('E632','5','Pressing onwards as we can,<br/>Still to this our hearts must tend;<br/>Where our earliest hopes began,<br/>There our last aspirings end.<br/>',NULL,3260,3260);
INSERT INTO stanza VALUES('E632','6','Till amid the host of light<br/>We in Thee redeemed, complete,<br/>Through Thy Cross made pure and white,<br/>Cast our crowns before Thy feet.<br/>',NULL,3261,3261);
INSERT INTO stanza VALUES('E633','1','And wouldst thou live on earth as "more than conqu''ror"?<br/>Victorious o''er the worldly life around?<br/>Mark well the pathway that thy Lord hath trodden,<br/>Since here alone the secret can be found.<br/>',NULL,3262,3262);
INSERT INTO stanza VALUES('E633','2','He died, and by His death He dealt the death-blow<br/>To sin and Satan''s power for evermore,<br/>And they, who die with Him, shall rise victorious,<br/>And "in this sign" shall triumph more and more.<br/>',NULL,3263,3263);
INSERT INTO stanza VALUES('E633','3','The Cross henceforth their mark of perfect freedom,<br/>What can they lose, who have surrendered all?<br/>What can they fear, who have no reputation?<br/>What shall they shrink from, when His voice doth call?<br/>',NULL,3264,3264);
INSERT INTO stanza VALUES('E633','4','"In this sign," therefore, go henceforth and conquer,<br/>Finding the place of death the gate of life,<br/>"Life more abundant," life in all its fulness,<br/>In the deep calm of God, set free from strife.<br/>',NULL,3265,3265);
INSERT INTO stanza VALUES('E634','1','Cross of Christ! Lead onward,<br/>Through the holy war;<br/>In this sign we conquer<br/>Now and evermore.<br/>Not of man the power,<br/>Not of man the fame;<br/>We are victors only<br/>In our leader''s name.<br/>',NULL,3266,3266);
INSERT INTO stanza VALUES('E634','chorus','Cross of Christ! Lead onward,<br/>Through the holy war;<br/>In this sign we conquer<br/>Now and evermore.<br/>',NULL,3267,3267);
INSERT INTO stanza VALUES('E634','2','Not with pomp and pageant,<br/>Not in earthly pride;<br/>We must fight our battles<br/>Like the Crucified.<br/>Overcome by suff''ring,<br/>Conquer through defeat;<br/>Tried and tested daily<br/>In the furnace heat.<br/>',NULL,3268,3268);
INSERT INTO stanza VALUES('E634','3','Kind, yet we are fighting,<br/>Bold, yet humbly meek;<br/>Resting while we''re working,<br/>Strong, but ever weak.<br/>Timid, though courageous,<br/>Gaining, as we give;<br/>Crucified with Jesus,<br/>Yet, in Him, we live.<br/>',NULL,3269,3269);
INSERT INTO stanza VALUES('E634','4','By a cloud encompassed,<br/>Witnesses to prove,<br/>Saints, apostles, prophets,<br/>Precious ones we love;<br/>While "advance!" is sounding,<br/>Mounts the battle thrill.<br/>Cross of Christ! Lead onward<br/>Where the Captain will.<br/>',NULL,3270,3270);
INSERT INTO stanza VALUES('E634','5','Marching in the pathway<br/>That the Master trod,<br/>Walks One daily with us<br/>Like the Son of God.<br/>To the end enduring,<br/>Armor ne''er laid down,<br/>Till the Cross leads upward<br/>To the blood-bought crown.<br/>',NULL,3271,3271);
INSERT INTO stanza VALUES('E635','1','Let us contemplate the grape vine,<br/>From its life now let us learn,<br/>How its growth is fraught with suff''ring,<br/>Midst environment so stern;<br/>How unlike the untamed flowers<br/>Growing in the wilderness<br/>In a maze of wild confusion,<br/>Making patterns numberless.<br/>',NULL,3272,3272);
INSERT INTO stanza VALUES('E635','2','But the blossoms of the grape vine<br/>Without glory are and small;<br/>Though they do have some expression,<br/>They are hardly seen withal.<br/>But a day since they have flowered<br/>Into fruit the blooms have grown;<br/>Never may they wave corollas<br/>With luxuriant beauty shown.<br/>',NULL,3273,3273);
INSERT INTO stanza VALUES('E635','3','To a post the vine is fastened;<br/>Thus it cannot freely grow;<br/>When its branches are extended,<br/>To the trellis tied they go.<br/>To the stony soil committed,<br/>Drawing thence its food supply;<br/>It can never choose its own way,<br/>Or from difficulty fly.<br/>',NULL,3274,3274);
INSERT INTO stanza VALUES('E635','4','Oh, how beautiful its verdure,<br/>Which in spring spread o''er the field.<br/>From life''s energy and fulness<br/>Growth abundant doth it yield.<br/>Till it''s full of tender branches<br/>Twining freely everywhere,<br/>Stretching ''gainst the sky''s deep azure<br/>Tasting sweetly of the air.<br/>',NULL,3275,3275);
INSERT INTO stanza VALUES('E635','5','But the master of the vineyard<br/>Not in lenience doth abide,<br/>But with knife and pruning scissors<br/>Then would strip it of its pride.<br/>Caring not the vine is tender,<br/>But with deep, precision stroke<br/>From the vine are neatly broke.<br/>',NULL,3276,3276);
INSERT INTO stanza VALUES('E635','6','In this time of loss and ruin,<br/>Dare the vine self-pity show?<br/>Nay, it gives itself more fully<br/>To the one who wounds it so,<br/>To the hand that strips its branches,<br/>Till of beauty destitute,<br/>That its life may not be wasted,<br/>But preserved for bearing fruit.<br/>',NULL,3277,3277);
INSERT INTO stanza VALUES('E635','7','Into hard wood slowly hardens<br/>Every stump of bleeding shoot,<br/>Each remaining branch becoming<br/>Clusters of abundant fruit.<br/>Then, beneath the scorching sunshine,<br/>Leaves are dried and from it drop;<br/>Thus the fruit more richly ripens<br/>Till the harvest of the crop.<br/>',NULL,3278,3278);
INSERT INTO stanza VALUES('E635','8','Bowed beneath its fruitful burden,<br/>Loaded branches are brought low-<br/>Labor of its growth thru suff''ring<br/>Many a purposed, cutting blow.<br/>Now its fruit is fully ripened,<br/>Comforted the vine would be;<br/>But the harvest soon is coming,<br/>And its days of comfort flee.<br/>',NULL,3279,3279);
INSERT INTO stanza VALUES('E635','9','Hands will pick and feet will trample<br/>All the riches of the vine,<br/>Till from out the reddened wine-press<br/>Flows a river full of wine.<br/>All the day its flow continues,<br/>Bloody-red, without alloy,<br/>Gushing freely, richly, sweetly,<br/>Filling all the earth with joy.<br/>',NULL,3280,3280);
INSERT INTO stanza VALUES('E635','10','In appearance now the grape vine<br/>Barren is and pitiful;<br/>Having given all, it enters<br/>Into night inscrutable.<br/>No one offers to repay it<br/>For the cheering wine that''s drunk,<br/>But ''tis stripped and cut e''en further<br/>To a bare and branchless trunk<br/>',NULL,3281,3281);
INSERT INTO stanza VALUES('E635','11','Yet its wine throughout the winter<br/>Warmth and sweetness ever bears<br/>Unto those in coldness shiv''ring,<br/>Pressed with sorrow, pain, and cares.<br/>Yet without, alone, the grape vine<br/>Midst the ice and snow doth stand,<br/>Steadfastly its lot enduring,<br/>Though ''tis hard to understand.<br/>',NULL,3282,3282);
INSERT INTO stanza VALUES('E635','12','Winter o''er, the vine prepareth<br/>Fruit again itself to bear;<br/>Budding forth and growing branches,<br/>Beauteous green again to wear;<br/>Never murmuring or complaining<br/>For the winter''s sore abuse,<br/>Or for all its loss desiring<br/>Its fresh off''ring to reduce.<br/>',NULL,3283,3283);
INSERT INTO stanza VALUES('E635','13','Breathing air, untainted, heavenly,<br/>As it lifts its arms on high,<br/>Earth''s impure, defiled affections<br/>Ne''er the vine may occupy.<br/>Facing sacrifice, yet smiling,<br/>And while love doth prune once more,<br/>Strokes it bears as if it never<br/>Suffered loss and pain before.<br/>',NULL,3284,3284);
INSERT INTO stanza VALUES('E635','14','From the branches of the grape vine<br/>Sap and blood and wine doth flow.<br/>Does the vine, for all it suffered,<br/>Lost, and yielded, poorer grow?<br/>Drunkards of the earth and wanderers,<br/>From it drink and merry make,<br/>From their pleasure and enjoyment<br/>Do they richer thereby wake?<br/>',NULL,3285,3285);
INSERT INTO stanza VALUES('E635','15','Not by gain our life is measured,<br/>But by what we''ve lost ''tis scored;<br/>''Tis not how much wine is drunken,<br/>But how much has been outpoured.<br/>For the strength of love e''er standeth<br/>In the sacrifice we bear;<br/>He who has the greatest suff''ring<br/>Ever has the most to share.<br/>',NULL,3286,3286);
INSERT INTO stanza VALUES('E635','16','He who treats himself severely<br/>Is the best for God to gain;<br/>He who hurts himself most dearly<br/>Most can comfort those in pain.<br/>He who suffering never beareth<br/>Is but empty "sounding brass";<br/>He who self-like never spareth<br/>Has the joys which all surpass.<br/>',NULL,3287,3287);
INSERT INTO stanza VALUES('E636','1','"If it die," oh, hear the message<br/>Falling from thy Lord,<br/>"If it die," much fruit it beareth,<br/>''Tis thy Savior''s word.<br/>',NULL,3288,3288);
INSERT INTO stanza VALUES('E636','2','Would''st thou see life work in others,<br/>Thou thyself must die.<br/>Fall into the ground, be buried,<br/>Low in darkness lie.<br/>',NULL,3289,3289);
INSERT INTO stanza VALUES('E636','3','But He leaves thee not in darkness,<br/>Light shall greet thine eyes,<br/>And in glad new life and glory<br/>He shall bid thee rise.<br/>',NULL,3290,3290);
INSERT INTO stanza VALUES('E636','4','Dost thou crave to tread the pathway<br/>And His life to share?<br/>As thou passeth thru death''s gateway<br/>He will meet thee there.<br/>',NULL,3291,3291);
INSERT INTO stanza VALUES('E636','5','Thou shalt learn the blessed secret,<br/>He shall live that dies;<br/>From the life poured out in secret<br/>Shall a harvest rise.<br/>',NULL,3292,3292);
INSERT INTO stanza VALUES('E637','1','"Wrecked outright on Jesus'' breast":<br/>Only "wrecked" souls thus can sing;<br/>Little boats that hug the shore,<br/>Fearing what the storm may bring,<br/>Never find on Jesus'' breast,<br/>All that "wrecked" souls mean by rest.<br/>',NULL,3293,3293);
INSERT INTO stanza VALUES('E637','2','"Wrecked outright!" So we lament;<br/>But when storms have done their worst,<br/>Then the soul, surviving all,<br/>In Eternal arms is nursed;<br/>There to find that nought can move<br/>One, embosomed in such love.<br/>',NULL,3294,3294);
INSERT INTO stanza VALUES('E637','3','"Wrecked outright!" No more to own<br/>E''en a craft to sail the sea;<br/>Still a voyager, yet now<br/>Anchored to Infinity;<br/>Nothing left to do but fling<br/>Care aside, and simply cling.<br/>',NULL,3295,3295);
INSERT INTO stanza VALUES('E637','4','"Wrecked outright!" ''Twas purest gain,<br/>Henceforth other craft can see<br/>That the storm may be a boon,<br/>That, however rough the sea,<br/>God Himself doth watchful stand,<br/>For the "wreck'' is in His hand.<br/>',NULL,3296,3296);
INSERT INTO stanza VALUES('E638','1','To Calv''ry let our eyes be turned,<br/>With Calv''ry love our hearts be burned;<br/>For there in Calv''ry''s awful hour,<br/>Love conquered sin and Satan''s pow''r.<br/>',NULL,3297,3297);
INSERT INTO stanza VALUES('E638','2','Lord, turn our gaze upon Thy Cross,<br/>Counting all else not gain but loss;<br/>For this we pray, this is our plea-<br/>Lord, keep our eyes on Calvary.<br/>',NULL,3298,3298);
INSERT INTO stanza VALUES('E639','1','Death cannot hold the resurrection life,<br/>The life of God eternal manifest;<br/>''Tis uncreated, indestructible,<br/>''Tis Christ Himself, unconqu''rable, expressed.<br/>',NULL,3299,3299);
INSERT INTO stanza VALUES('E639','2','Death cannot hold the resurrection life,<br/>Though all its force against it may combine;<br/>Death only gives it opportunity<br/>To show the boundless pow''r of life divine.<br/>',NULL,3300,3300);
INSERT INTO stanza VALUES('E639','3','Death cannot hold the resurrection life,<br/>The more interred, the more it multiplies;<br/>All kinds of suff''ring only help it grow<br/>And fruits of life abundant realize.<br/>',NULL,3301,3301);
INSERT INTO stanza VALUES('E639','4','Death cannot hold the resurrection life,<br/>Thru every block and barrier it breaks;<br/>Conqu''ring the pow''r of darkness and of hell,<br/>It swallows death and victory partakes.<br/>',NULL,3302,3302);
INSERT INTO stanza VALUES('E639','5','Death cannot hold the resurrection life,<br/>All of God''s fulness it will manifest;<br/>God''s righteousness and holiness it yields,<br/>His glorious image by it is expressed.<br/>',NULL,3303,3303);
INSERT INTO stanza VALUES('E639','6','Oh, may I know this resurrection life,<br/>In every kind of death its pow''r outpoured,<br/>In my experience ever realize<br/>This life is nought but Christ my living Lord.<br/>',NULL,3304,3304);
INSERT INTO stanza VALUES('E640','1','Life out of death-dear Master, is it spoken<br/>Of the life here, or in the better land?<br/>Nay, wherefore wait? The vessel marred and broken,<br/>Shall now be molded by the Potter''s hand.<br/>',NULL,3305,3305);
INSERT INTO stanza VALUES('E640','2','Life out of death-oh, wondrous resurrection!<br/>Seed sown in conscious weakness, raised in power;<br/>Thy life lived out in days of toil and friction,<br/>"Not I, but Christ" in me from hour to hour.<br/>',NULL,3306,3306);
INSERT INTO stanza VALUES('E640','3','Life out of death-a pilgrim path and lonely,<br/>Trodden by those who glory in the Cross.<br/>They live in fellowship with "Jesus only,"<br/>And for His sake count earthly gain but loss.<br/>',NULL,3307,3307);
INSERT INTO stanza VALUES('E640','4','Life out of death-blest mission to be ever<br/>Bearing the living water brimming o''er.<br/>With life abundant from the clear, pure river,<br/>Telling that thirsty souls need thirst no more.<br/>',NULL,3308,3308);
INSERT INTO stanza VALUES('E641','1','Art thou hung''ring for the fulness<br/>Of the blessing Christ doth give?<br/>Longing now to learn the secret<br/>Of the life He bids thee live?<br/>In His word thine answer standeth,<br/>"Christ who is our Life" it saith;<br/>Open now thy heart, and trust Him,<br/>There to dwell, henceforth, by faith.<br/>',NULL,3309,3309);
INSERT INTO stanza VALUES('E641','2','Christ, the Lord''s Anointed, reigning<br/>O''er the life He died to win,<br/>Daily shall reveal more fully<br/>His great power, without, within.<br/>What thou never could''st accomplish<br/>Shall His Spirit work through thee,<br/>While thy soul this witness beareth,<br/>''Tis not I, but Christ in me.<br/>',NULL,3310,3310);
INSERT INTO stanza VALUES('E641','3','In Him dwelleth all God''s fulness,<br/>In Him thou art made complete;<br/>Rise, and claim thy heavenly birthright,<br/>Kneeling at thy Father''s feet.<br/>He will never disappoint thee,<br/>Praise Him that the gift is thine;<br/>Then go forth to live each moment<br/>On sufficiency divine.<br/>',NULL,3311,3311);
INSERT INTO stanza VALUES('E641','4','Lord, I come, and simply resting<br/>On Thy faithful, changeless word,<br/>I believe the blood doth cleanse me,<br/>And that Christ is crowned outflow<br/>Of Thy life and love through me;<br/>Reaching those who sit in darkness,<br/>Winning priceless souls to Thee.<br/>',NULL,3312,3312);
INSERT INTO stanza VALUES('E642','1','"Within the Veil": be this, belov''d, thy portion,<br/>Within the secret of thy Lord to dwell;<br/>Beholding Him until thy face His glory,<br/>Thy life His love, thy lips His praise shall tell.<br/>',NULL,3313,3313);
INSERT INTO stanza VALUES('E642','2','"Within the Veil," for only as thou gazest<br/>Upon the matchless beauty of His face,<br/>Canst thou become a living revelation<br/>Of His great heart of love, His untold grace.<br/>',NULL,3314,3314);
INSERT INTO stanza VALUES('E642','3','"Within the Veil," His fragrance poured upon thee,<br/>Without the Veil, that fragrance shed abroad;<br/>"Within the Veil," His hand shall tune the music<br/>Which sounds on earth the praises of Thy Lord.<br/>',NULL,3315,3315);
INSERT INTO stanza VALUES('E642','4','"Within the Veil," thy spirit deeply anchored,<br/>Thou walkest calm above a world of strife;<br/>"Within the Veil," thy soul with Him united,<br/>Shall live on earth His resurrection life.<br/>',NULL,3316,3316);
INSERT INTO stanza VALUES('E643','1','Take time to behold Him,<br/>Speak oft with Thy Lord,<br/>Abide in Him always,<br/>And feed on His Word.<br/>Wait thou in His presence,<br/>Submissive and meek,<br/>Forgetting in nothing<br/>His blessing to seek.<br/>',NULL,3317,3317);
INSERT INTO stanza VALUES('E643','2','Take time to behold Him,<br/>The world rushes on;<br/>Spend much time in secret<br/>With Jesus alone.<br/>By looking to Jesus<br/>Like Him thou shalt be;<br/>Thy friends, in thy conduct,<br/>His likeness shall see.<br/>',NULL,3318,3318);
INSERT INTO stanza VALUES('E643','3','Take time to behold Him,<br/>Let Him be thy guide;<br/>And run not before Him<br/>Whatever betide;<br/>In joy or in sorrow<br/>Still follow thy Lord,<br/>And, looking to Jesus,<br/>Still trust in His Word.<br/>',NULL,3319,3319);
INSERT INTO stanza VALUES('E643','4','Take time to behold Him,<br/>Be calm in thy soul,<br/>Each thought and each temper<br/>Beneath His control.<br/>Thus led by His Spirit<br/>To fountains of love,<br/>Thou then shalt be fitted<br/>His mercy to prove.<br/>',NULL,3320,3320);
INSERT INTO stanza VALUES('E644','1','Looking unto Jesus,<br/>Never need we yield!<br/>Over all the armor,<br/>Faith the battle-shield!<br/>Standard of salvation,<br/>In our hearts unfurled,<br/>Let its elevation<br/>Overcome the world.<br/>',NULL,3321,3321);
INSERT INTO stanza VALUES('E644','chorus','Looking unto Jesus,<br/>Never need we yield!<br/>Over all the armor,<br/>Faith the battle-shield!<br/>',NULL,3322,3322);
INSERT INTO stanza VALUES('E644','2','Look away to Jesus,<br/>Look away from all!<br/>Then we need not stumble,<br/>Then we shall not fall.<br/>From each snare that lureth,<br/>Foe or phantom grim,<br/>Safety this ensureth,<br/>Look away to Him.<br/>',NULL,3323,3323);
INSERT INTO stanza VALUES('E644','3','Looking into Jesus,<br/>Wond''ringly we trace<br/>Heights of power and glory,<br/>Depths of love and grace.<br/>Vistas far unfolding<br/>Ever stretch before,<br/>As we gaze, beholding,<br/>Ever more and more.<br/>',NULL,3324,3324);
INSERT INTO stanza VALUES('E644','4','Looking up to Jesus<br/>On the emerald throne,<br/>Faith shall pierce the heavens,<br/>Where our King is gone.<br/>Lord, on Thee depending,<br/>Now, continually,<br/>Heart and mind ascending,<br/>Let us dwell with Thee.<br/>',NULL,3325,3325);
INSERT INTO stanza VALUES('E645','1','O soul, are you weary and troubled?<br/>No light in the darkness you see?<br/>There''s light for a look at the Savior,<br/>And life more abundant and free.<br/>',NULL,3326,3326);
INSERT INTO stanza VALUES('E645','chorus','Turn your eyes upon Jesus,<br/>Look full in His wonderful face,<br/>And the things of earth will grow strangely dim,<br/>In the light of His glory and grace.<br/>',NULL,3327,3327);
INSERT INTO stanza VALUES('E645','2','Through death into life everlasting<br/>He passed, and we follow Him there;<br/>O''er us sin no more hath dominion<br/>For more than conqu''rors we are!<br/>',NULL,3328,3328);
INSERT INTO stanza VALUES('E645','3','His Word shall not fail you, He promised;<br/>Believe Him and all will be well;<br/>Then go to a world that is dying,<br/>His perfect salvation to tell!<br/>',NULL,3329,3329);
INSERT INTO stanza VALUES('E646','1','Oh, trust thyself to Jesus<br/>When conscious of thy sin,<br/>Its heavy weight upon thee,<br/>Its mighty pow''r within:<br/>Then is the hour for pleading<br/>His finished work for thee:<br/>Then is the time for singing,<br/>His blood was shed for me.<br/>',NULL,3330,3330);
INSERT INTO stanza VALUES('E646','2','Oh, trust thyself to Jesus<br/>When tempted to transgress,<br/>By word or look of anger,<br/>Or thought of bitterness:<br/>Then is the hour for claiming<br/>Thy Lord to fight for thee:<br/>Then is the time for singing,<br/>He doth deliver me.<br/>',NULL,3331,3331);
INSERT INTO stanza VALUES('E646','3','Oh, trust thyself to Jesus<br/>When daily cares perplex,<br/>And trifles seem so mighty<br/>Thy inner soul to vex:<br/>Then is the hour for grasping<br/>His hand who walked the sea:<br/>Then is the time for singing,<br/>He makes it calm for me.<br/>',NULL,3332,3332);
INSERT INTO stanza VALUES('E646','4','Oh, trust thyself to Jesus<br/>When thou art wearied sore,<br/>When head or hand refuses<br/>To think or labor more:<br/>Then is the hour for leaning<br/>Upon the Master''s breast:<br/>Then is the time for singing,<br/>My Savior give me rest.<br/>',NULL,3333,3333);
INSERT INTO stanza VALUES('E647','1','Trust Him when thy wants are many;<br/>Trust Him when thy friends are few''<br/>And the time of swift temptation<br/>Is the time to trust Him too.<br/>',NULL,3334,3334);
INSERT INTO stanza VALUES('E647','2','Trust Him when thy soul is burdened<br/>With the sense of all its sin;<br/>He will speak the word of pardon,<br/>He will make thee clean within.<br/>',NULL,3335,3335);
INSERT INTO stanza VALUES('E647','3','Trust Him for the grace sufficient,<br/>Ever equal to thy need;<br/>Trust Him always for the answer,<br/>When in His dear name you plead.<br/>',NULL,3336,3336);
INSERT INTO stanza VALUES('E647','4','Trust Him for the grace to conquer,<br/>He is able to subdue;<br/>Trust Him for the power for service;<br/>Trust Him for the blessing too.<br/>',NULL,3337,3337);
INSERT INTO stanza VALUES('E647','5','Trust Him when dark doubts assail thee,<br/>Trust Him when thy strength is small,<br/>Trust Him when to simply trust Him<br/>Seems the hardest thing of all.<br/>',NULL,3338,3338);
INSERT INTO stanza VALUES('E647','6','Trust Him; His is ever faithful;<br/>Trust Him, for His will is best;<br/>Trust Him, for the heart of Jesus<br/>Is the only place of rest.<br/>',NULL,3339,3339);
INSERT INTO stanza VALUES('E647','7','Trust Him, then, through cloud and sunshine,<br/>All the cares upon Him cast,<br/>Till the storm of life is over,<br/>And the trusting days are past.<br/>',NULL,3340,3340);
INSERT INTO stanza VALUES('E648','1','Soldier, soldier, fighting in the world''s great strife,<br/>On thyself relying, battling for thy life;<br/>Trust thyself no longer,<br/>Trust to Christ-He''s stronger;<br/>I can all things, all things do<br/>Through Christ, which strengtheneth me.<br/>',NULL,3341,3341);
INSERT INTO stanza VALUES('E648','2','In your daily duty, standing up for right,<br/>Are you sometimes weary-heart not always light?<br/>Doubt your Savior never,<br/>This your motto ever:<br/>I can all things, all things do<br/>Through Christ, which strengtheneth me.<br/>',NULL,3342,3342);
INSERT INTO stanza VALUES('E648','3','If your way be weary He will help you through-<br/>Help you in your troubles and your pleasures too;<br/>Say, when Satan''s by you;<br/>Say, when all things try you:<br/>I can all things, all things do<br/>Through Christ, which strengtheneth me.<br/>',NULL,3343,3343);
INSERT INTO stanza VALUES('E648','4','In a world of trouble, tempted oft to stray,<br/>You need never stumble, Satan cannot stay,<br/>Will but tempt you vainly,<br/>If you tell him plainly,<br/>I can all things, all things do<br/>Through Christ, which strengtheneth me.<br/>',NULL,3344,3344);
INSERT INTO stanza VALUES('E648','5','Jesus'' power is boundless, boundless as the sea;<br/>He is always able, able to keep me,<br/>Power bring from my weakness,<br/>Glory from my meekness,<br/>I can all things, all things do<br/>Through Christ, which strengtheneth me.<br/>',NULL,3345,3345);
INSERT INTO stanza VALUES('E649','1','Fear not, little flock, from the cross to the throne,<br/>From death into life He went for His own;<br/>All power in earth, all power above,<br/>Is given to Him for the flock of His love.<br/>',NULL,3346,3346);
INSERT INTO stanza VALUES('E649','chorus','Only believe, only believe;<br/>All things are possible, only believe;<br/>Only believe, only believe;<br/>All things are possible, only believe.<br/>',NULL,3347,3347);
INSERT INTO stanza VALUES('E649','2','Fear not, little flock, He goeth ahead,<br/>Your Shepherd selecteth the path you must tread;<br/>The waters of Marah He''ll sweeten for thee,<br/>He drank all the bitter in Gethsemane.<br/>',NULL,3348,3348);
INSERT INTO stanza VALUES('E649','3','Fear not, little flock, whatever your lot,<br/>He enters all rooms, "the doors being shut";<br/>He never forsakes, He never is gone,<br/>So count on His presence in darkness and dawn.<br/>',NULL,3349,3349);
INSERT INTO stanza VALUES('E650','1','O doubting, struggling Christian,<br/>Why thus in anguish pray?<br/>O cease to doubt and struggle,<br/>There is a better way.<br/>',NULL,3350,3350);
INSERT INTO stanza VALUES('E650','chorus','O settle it all with Jesus,<br/>O settle it all today;<br/>O cease to doubt and struggle,<br/>O cease to plead and pray;<br/>O rest in His word forever,<br/>And settle it all today.<br/>',NULL,3351,3351);
INSERT INTO stanza VALUES('E650','2','Give up thy will to Jesus,<br/>And trust Him though He slay;<br/>Hush all thy fears and questions,<br/>And settle it today.<br/>',NULL,3352,3352);
INSERT INTO stanza VALUES('E650','3','O soul so tossed with tempest,<br/>Upon His promise stay;<br/>Cast out faith''s strong sheet anchor,<br/>And settle it today.<br/>',NULL,3353,3353);
INSERT INTO stanza VALUES('E650','4','Lord, I give up the struggle,<br/>To Thee commit my way;<br/>I trust Thy word forever,<br/>And settle it today.<br/>',NULL,3354,3354);
INSERT INTO stanza VALUES('E651','1','When is the time to trust?<br/>Is it when all is calm,<br/>When waves the victor''s palm,<br/>And life is one glad psalm?<br/>Nay! But the time to trust<br/>Is when the waves beat high,<br/>When storm clouds fill the sky,<br/>And pray''r is one long cry.<br/>',NULL,3355,3355);
INSERT INTO stanza VALUES('E651','2','When is the time to trust?<br/>Is it when friends are true?<br/>Is it when comforts woo<br/>In all we say and do?<br/>Nay! But the time to trust<br/>Is when we stand alone,<br/>And summer birds are flown,<br/>And every prop is gone.<br/>',NULL,3356,3356);
INSERT INTO stanza VALUES('E651','3','When is the time to trust?<br/>Is it some future day,<br/>When you have tried your way,<br/>And learned to trust and pray?<br/>Nay! But the time to trust<br/>Is in this moment''s need,<br/>Poor, broken, bruised reed,<br/>Poor, troubled soul, make speed!<br/>',NULL,3357,3357);
INSERT INTO stanza VALUES('E651','4','When is the time to trust?<br/>Is it when hopes beat high,<br/>When sunshine gilds the sky<br/>With joy and ecstasy?<br/>Nay! But the time to trust<br/>Is when our joy has fled,<br/>When sorrow bows the head,<br/>And all is cold and dead.<br/>',NULL,3358,3358);
INSERT INTO stanza VALUES('E652','1','O troubled soul, beneath the rod<br/>Thy Father speaks-be still, be still;<br/>Learn to be silent unto God,<br/>And let Him mold thee to His will.<br/>',NULL,3359,3359);
INSERT INTO stanza VALUES('E652','chorus','Be still, O troubled soul, be still;<br/>Fear not, thy Father''s arms enfold thee.<br/>Take up thy cross, lay down thy will;<br/>Be silent unto God, and let Him mold thee.<br/>',NULL,3360,3360);
INSERT INTO stanza VALUES('E652','2','O anxious soul, lay down thy load,<br/>Oh, hear His voice, He speaks to thee,<br/>"Be still and know that I am God,<br/>And cast thy every care on Me."<br/>',NULL,3361,3361);
INSERT INTO stanza VALUES('E652','3','O fearful soul, be still, be still,<br/>Be of good cheer; has He not said,<br/>"I will be with you, fear no ill,<br/>''Tis I, ''tis I, be not afraid"?<br/>',NULL,3362,3362);
INSERT INTO stanza VALUES('E652','4','O praying soul, be still, be still,<br/>He cannot break His plighted word;<br/>Sink down into His blessed will,<br/>And wait in patience on the Lord.<br/>',NULL,3363,3363);
INSERT INTO stanza VALUES('E652','5','O waiting soul, be still, be strong,<br/>And though He tarry, trust and wait;<br/>Doubt not, He will not wait too long,<br/>Fear not, He will not come too late.<br/>',NULL,3364,3364);
INSERT INTO stanza VALUES('E653','1','Rest, rest thee, weary heart,<br/>Let toil and anguish cease;<br/>Take from Thy Savior''s hands<br/>Thine heritage of peace.<br/>',NULL,3365,3365);
INSERT INTO stanza VALUES('E653','2','Lie low before His feet,<br/>Too low thou canst not be,<br/>For sacred calm is here,<br/>And here is liberty.<br/>',NULL,3366,3366);
INSERT INTO stanza VALUES('E653','3','Submit, lay down thine arms,<br/>Nor question, nor rebel;<br/>So shalt thou hear erewhile<br/>His whisper, It is well.<br/>',NULL,3367,3367);
INSERT INTO stanza VALUES('E653','4','No secret wound of thine,<br/>Though it be great or small,<br/>Presume to hide from Him;<br/>Confess, confess it all;<br/>',NULL,3368,3368);
INSERT INTO stanza VALUES('E653','5','Nor merit of thine own<br/>Upon His altar place;<br/>All is of Christ alone,<br/>And of His perfect grace.<br/>',NULL,3369,3369);
INSERT INTO stanza VALUES('E653','6','Rest, rest thee, weary heart,<br/>Let care and anguish cease;<br/>Take from thy Savior''s hands<br/>Thine heritage of peace.<br/>',NULL,3370,3370);
INSERT INTO stanza VALUES('E654','1','"Be all at rest, my soul!" Oh! Blessed secret<br/>Of the true life that glorifies thy Lord;<br/>Not always doth the busiest soul best serve Him,<br/>But he who resteth on His faithful word.<br/>',NULL,3371,3371);
INSERT INTO stanza VALUES('E654','2','"Be all at rest!" for rest is highest service;<br/>To the still heart God doth His secrets tell;<br/>Thus shalt thou learn to wait, and watch, and labor,<br/>Strengthened to bear, since Christ in thee doth dwell.<br/>',NULL,3372,3372);
INSERT INTO stanza VALUES('E654','3','"Be all at rest!" for rest alone becometh<br/>The soul that casts on Him its every care;<br/>"Be all at rest!" so shall thy life proclaim Him<br/>A God who worketh and who heareth prayer.<br/>',NULL,3373,3373);
INSERT INTO stanza VALUES('E654','4','"Be all at rest!" so shalt thou be an answer<br/>To those who question, "Who is God, and where?"<br/>For God is rest, and where He dwells is stillness,<br/>And they who dwell in Him that rest shall share.<br/>',NULL,3374,3374);
INSERT INTO stanza VALUES('E655','1','Feed on His faithfulness, my soul,<br/>Who chose thee for His own,<br/>Who bears thy name in Love''s pure flame<br/>Before the heav''nly throne;<br/>Lay at His feet thy fear,<br/>Thy burdens, thy distress,<br/>Prostate embrace thy Fount of Grace-<br/>Feed on His faithfulness.<br/>',NULL,3375,3375);
INSERT INTO stanza VALUES('E655','2','Feed on His faithfulness, my soul,<br/>Who suffered Calvary,<br/>Who Victor rose o''er all thy foes,<br/>Who lives, who prays, for thee!<br/>Not thine the battle is,<br/>Though close the conflict press;<br/>''Tis His alone who wears the crown-<br/>Feed on His faithfulness.<br/>',NULL,3376,3376);
INSERT INTO stanza VALUES('E655','3','Feed on His faithfulness, my soul,<br/>Then naught shall thee affright;<br/>His perfect will all fear shall still,<br/>His wisdom guide aright.<br/>He slumbers not nor sleeps,<br/>But waits His saints to bless;<br/>Th'' eternal Throne is His alone-<br/>Feed on His faithfulness.<br/>',NULL,3377,3377);
INSERT INTO stanza VALUES('E655','4','Feed on His faithfulness, my soul;<br/>So shalt thou see His face,<br/>Transforming thee till all shall see<br/>The glory of His grace;<br/>Closer to His great heart<br/>In glad abandon press;<br/>Fling thy soul down upon His own-<br/>Feed on His faithfulness.<br/>',NULL,3378,3378);
INSERT INTO stanza VALUES('E656','1','"Consider Him," let Christ thy pattern be,<br/>And know that He hath apprehended thee<br/>To share His very life, His pow''r divine,<br/>And in the likeness of thy Lord to shine.<br/>',NULL,3379,3379);
INSERT INTO stanza VALUES('E656','2','"Consider Him"; so shalt thou, day by day,<br/>Seek out the lowliest place, and therein stay,<br/>Content to pass away, a thing of nought,<br/>That glory to the Father''s name be brought.<br/>',NULL,3380,3380);
INSERT INTO stanza VALUES('E656','3','Shrink not, O child of God, but fearless go<br/>Down into death with Jesus; thou shalt know<br/>The power of an endless life begin,<br/>With glorious liberty from self and sin.<br/>',NULL,3381,3381);
INSERT INTO stanza VALUES('E656','4','"Consider Him," and thus thy life shall be<br/>Filled with self-sacrifice and purity;<br/>God will work out in thee the pattern true,<br/>And Christ''s example ever keep in view.<br/>',NULL,3382,3382);
INSERT INTO stanza VALUES('E656','5','"Consider Him," and as you run the race,<br/>Keep ever upward looking in His face;<br/>And thus transformed, illumined thou shalt be,<br/>And Christ''s own image shall be seen in thee.<br/>',NULL,3383,3383);
INSERT INTO stanza VALUES('E657','1','Can you be obedient<br/>To the Lord of all,<br/>Though the earth should totter,<br/>Though the heav''ns should fall?<br/>Face e''en a disaster<br/>With a faith-filled heart,<br/>Knowing naught can harm him<br/>Who with Christ will start?<br/>',NULL,3384,3384);
INSERT INTO stanza VALUES('E657','2','Can you be obedient<br/>To the Lord you serve,<br/>Never even flinch, friend,<br/>Never even swerve;<br/>Though your next step onward<br/>Seem to lead to death?<br/>Can you then obey Him<br/>Without bated breath?<br/>',NULL,3385,3385);
INSERT INTO stanza VALUES('E657','3','Can you trust your Leader<br/>When He bids you go<br/>Right into the battle<br/>With a mighty foe?<br/>Can you step up briskly<br/>And with joy obey?<br/>Can you fight the battle,<br/>Till the end of day?<br/>',NULL,3386,3386);
INSERT INTO stanza VALUES('E657','4','Can you? Then beloved,<br/>Christ just waits for you;<br/>Listen for His orders,<br/>Glad His will to do;<br/>Then when soldiers muster<br/>At the set of sun,<br/>And your name is mentioned,<br/>Christ will say, "Well done."<br/>',NULL,3387,3387);
INSERT INTO stanza VALUES('E658','1','Walk in the light, and thou shalt know<br/>That fellowship of love<br/>His Spirit only can bestow,<br/>Who reigns in light above.<br/>',NULL,3388,3388);
INSERT INTO stanza VALUES('E658','2','Walk in the light, and thou shalt find<br/>Thy heart made truly His;<br/>Who dwells in cloudless light enshrined,<br/>In whom no darkness is.<br/>',NULL,3389,3389);
INSERT INTO stanza VALUES('E658','3','Walk in the light, and sin abhorred<br/>Shall ne''er defile again;<br/>The blood of Jesus Christ the Lord<br/>Shall cleanse from every stain.<br/>',NULL,3390,3390);
INSERT INTO stanza VALUES('E658','4','Walk in the light, and e''en the tomb<br/>No fearful shade shall wear;<br/>The glory shall dispel the gloom,<br/>For Christ hath conquered there.<br/>',NULL,3391,3391);
INSERT INTO stanza VALUES('E658','5','Walk in the light, and thou shalt own<br/>Thy darkness passed away,<br/>Because that light hath on thee shone<br/>In which is perfect day.<br/>',NULL,3392,3392);
INSERT INTO stanza VALUES('E658','6','Walk in the light, thy path shall be<br/>Serene and clear and bright;<br/>For God, by grace, shall dwell in thee,<br/>And God Himself is Light.<br/>',NULL,3393,3393);
INSERT INTO stanza VALUES('E659','1','Rejoice in the Lord! Oh, let His mercy cheer;<br/>He sunders the bands that enthrall;<br/>Redeemed by His blood, why should we ever fear,<br/>Since Jesus is our all in all?<br/>',NULL,3394,3394);
INSERT INTO stanza VALUES('E659','chorus','If God be for us, if God be for us,<br/>if God be for us,<br/>Who can be against us?<br/>Who? Who? Who?<br/>Who can be against us, against us?<br/>',NULL,3395,3395);
INSERT INTO stanza VALUES('E659','2','Be strong in the Lord! Rejoicing in His might,<br/>Be loyal and true day by day;<br/>When evils assail, be valiant for the right,<br/>And He will be our strength and stay.<br/>',NULL,3396,3396);
INSERT INTO stanza VALUES('E659','3','Confide in His Word, His promises so sure;<br/>In Christ they are yea and amen;<br/>Though earth pass away, they ever shall endure,<br/>''Tis written o''er and o''er again.<br/>',NULL,3397,3397);
INSERT INTO stanza VALUES('E659','4','Abide in the Lord, secure in His control,<br/>''Tis life everlasting begun;<br/>To pluck from His hand the weakest, trembling soul,<br/>It never, never can be done!<br/>',NULL,3398,3398);
INSERT INTO stanza VALUES('E660','1','In nothing be anxious; the Lord is at hand.<br/>In peace and in vict''ry triumphantly stand;<br/>Let nothing affright thee and nothing dismay,<br/>For Jesus is coming! It may be today.<br/>',NULL,3399,3399);
INSERT INTO stanza VALUES('E660','2','In nothing be anxious; on Him roll thy care.<br/>Thy sins were laid on Him, thy sorrows He''ll bear;<br/>Care free and triumphant press on, still to prove<br/>The strength of His arm and the balm of His love.<br/>',NULL,3400,3400);
INSERT INTO stanza VALUES('E660','3','In nothing be anxious; should Jesus delay<br/>His strength will be thine till the end of the day.<br/>His arm thou canst lean on; His Spirit will cheer;<br/>Then wherefore be anxious, press on without fear.<br/>',NULL,3401,3401);
INSERT INTO stanza VALUES('E661','1','Master, how shall I bless Thy name<br/>For love so great to me,<br/>For sweet enablings of Thy grace,<br/>So sov''reign, yet so free,<br/>That taught me to obey Thy word,<br/>And cast my care on Thee?<br/>',NULL,3402,3402);
INSERT INTO stanza VALUES('E661','2','No anxious thought upon thy brow<br/>The watching world should see;<br/>No carefulness! O child of God,<br/>For nothing careful be!<br/>But cast thou all thy care on Him<br/>Who always cares for thee.<br/>',NULL,3403,3403);
INSERT INTO stanza VALUES('E661','3','How shall I praise Thee, Savior dear,<br/>For this new life so sweet,<br/>For taking all the care I laid<br/>At Thy beloved feet,<br/>Keeping Thy hand upon my heart<br/>To still each anxious beat?<br/>',NULL,3404,3404);
INSERT INTO stanza VALUES('E661','4','I long to praise Thee more, and yet<br/>This is no care to me;<br/>If Thou shalt fill my mouth with songs<br/>Then I shall sing to Thee;<br/>And if my silence praise Thee best,<br/>Then silent I will be.<br/>',NULL,3405,3405);
INSERT INTO stanza VALUES('E661','5','Yet if it be Thy will, dear Lord,<br/>Oh, send me forth to be<br/>Thy messenger to careful hearts,<br/>To bid them taste, and see<br/>How good Thou art to those who cast<br/>All, all their care on Thee.<br/>',NULL,3406,3406);
INSERT INTO stanza VALUES('E662','1','"On toward the goal!" Press on!<br/>Alone, yet unafraid;<br/>He cut the path, who beckons thee,<br/>On then, and undismayed.<br/>',NULL,3407,3407);
INSERT INTO stanza VALUES('E662','2','"On toward the goal!" Press on!<br/>The eyes that are a flame<br/>Are watching thee, what then are men?<br/>What matter praise, or blame?<br/>',NULL,3408,3408);
INSERT INTO stanza VALUES('E662','3','"On toward the goal!" Press on!<br/>Look not behind thee now,<br/>When just ahead lies His "Well done,"<br/>And crowns await thy brow.<br/>',NULL,3409,3409);
INSERT INTO stanza VALUES('E662','4','"On toward the goal!" Press on!<br/>Blind, deaf and sometimes dumb<br/>Along the blood-marked, uphill way,<br/>Hard after Christ, press on!<br/>',NULL,3410,3410);
INSERT INTO stanza VALUES('E663','1','"Forward!" be our watchword,<br/>Steps and voices joined;<br/>Seek the things before us,<br/>Not a look behind;<br/>Burns the fiery pillar<br/>At our army''s head;<br/>Who shall dream of shrinking,<br/>By our Captain led?<br/>Forward through the desert,<br/>Through the toil and fight.<br/>Heaven''s Kingdom waits us,<br/>Forward into light.<br/>',NULL,3411,3411);
INSERT INTO stanza VALUES('E663','2','Glories upon glories<br/>Hath our God prepared,<br/>By the souls that love Him,<br/>One day that be shared:<br/>Eye hath not beheld them,<br/>Ear hath never heard;<br/>Nor of these hath uttered<br/>Thought or speech or word;<br/>Forward, marching forward<br/>Where the kingdom''s bright,<br/>Till the veil be lifted,<br/>Till our faith be sight!<br/>',NULL,3412,3412);
INSERT INTO stanza VALUES('E664','1','Rise, my soul, thy God directs thee;<br/>Stranger hands no more impede;<br/>Pass thou on, His strength protects thee,<br/>Strength that has the captive freed.<br/>',NULL,3413,3413);
INSERT INTO stanza VALUES('E664','2','Is the wilderness before thee,<br/>Desert lands where drought abides?<br/>Heavenly springs shall there restore thee,<br/>Fresh from God''s exhaustless tides.<br/>',NULL,3414,3414);
INSERT INTO stanza VALUES('E664','3','Light divine surrounds thy going,<br/>God Himself shall mark thy way;<br/>Secret blessings, richly flowing,<br/>Lead to everlasting day.<br/>',NULL,3415,3415);
INSERT INTO stanza VALUES('E664','4','God, thine everlasting portion,<br/>Feeds thee with the Mighty''s meat;<br/>Saved from Egypt''s hard extortion,<br/>Egypt''s food no more to eat.<br/>',NULL,3416,3416);
INSERT INTO stanza VALUES('E664','5','Art thou weaned from Egypt''s pleasures?<br/>God in secret shall thee keep;<br/>There unfold His hidden treasures,<br/>There His love''s exhaustless deep.<br/>',NULL,3417,3417);
INSERT INTO stanza VALUES('E664','6','In the desert God will teach thee<br/>What the God that thou hast found-<br/>Patient, gracious, powerful, holy;<br/>All His grace shall there abound.<br/>',NULL,3418,3418);
INSERT INTO stanza VALUES('E664','7','On to Canaan''s rest still wending,<br/>E''en thy wants and woes shall bring<br/>Suited grace from high descending;<br/>Thou shalt taste of mercy''s spring.<br/>',NULL,3419,3419);
INSERT INTO stanza VALUES('E664','8','Though thy way be long and dreary,<br/>Eagle strength He''ll still renew;<br/>Garments fresh, and feet unweary,<br/>Tell how God hath brought thee through.<br/>',NULL,3420,3420);
INSERT INTO stanza VALUES('E664','9','When to Canaan''s long-loved dwelling<br/>Love divine thy feet shall bring,<br/>Thou, with shouts of triumph swelling,<br/>Zion''s songs in rest shall sing.<br/>',NULL,3421,3421);
INSERT INTO stanza VALUES('E665','1','Come, let us to the Lord our God<br/>With contrite heart return;<br/>Our God is gracious, nor will leave<br/>The desolate to mourn.<br/>',NULL,3422,3422);
INSERT INTO stanza VALUES('E665','2','His voice commands the tempest forth,<br/>And stills the stormy wave;<br/>And though His arm be strong to smite,<br/>''Tis also strong to save.<br/>',NULL,3423,3423);
INSERT INTO stanza VALUES('E665','3','Long hath the night of sorrow reigned;<br/>The dawn shall bring us light;<br/>God shall appear, and we shall rise<br/>With gladness in His sight.<br/>',NULL,3424,3424);
INSERT INTO stanza VALUES('E665','4','Our heart, if God we seek to know,<br/>Shall know Him, and rejoice;<br/>His coming like the morn shall be,<br/>Like morning songs His voice.<br/>',NULL,3425,3425);
INSERT INTO stanza VALUES('E665','5','As dew upon the tender herb,<br/>Diffusing fragrance round,<br/>As showers that usher in the spring,<br/>And cheer the thirsty ground;<br/>',NULL,3426,3426);
INSERT INTO stanza VALUES('E665','6','So shall His presence bless our souls,<br/>And shed a joyful light;<br/>That hallowed morn shall chase away<br/>The sorrows of the night.<br/>',NULL,3427,3427);
INSERT INTO stanza VALUES('E666','1','Watch, for the night is ending!<br/>Watch, and the world not seek;<br/>Watch, for the day is dawning!<br/>Watch, sink not in sleep.<br/>Watch, for the Lord is coming!<br/>Watch for the foe''s attack:<br/>Watch, for the Lord is waiting!<br/>Watch, be never slack.<br/>',NULL,3428,3428);
INSERT INTO stanza VALUES('E666','2','Watch, and arise in service!<br/>Watch, though the day be drear;<br/>Watch, and go forth to labor!<br/>Watch, the end is near.<br/>Watch and put on the armor!<br/>Watch with thy spirit strong;<br/>Watch to resist the devil!<br/>Watch, Christ comes ere long.<br/>',NULL,3429,3429);
INSERT INTO stanza VALUES('E666','3','Watch for the Savior''s coming!<br/>Watch for the Morning Star;<br/>Watch and pursue the Kingdom!<br/>Watch with many a scar.<br/>Watch, and be ever watchful!<br/>Watch, till the night is done;<br/>Watch till the dawn of glory!<br/>Watch till the Lord shall come.<br/>',NULL,3430,3430);
INSERT INTO stanza VALUES('E667','1','Seek ye first, not earthly pleasure,<br/>Fading joy and failing treasure,<br/>But the love that knows no measure<br/>Seek ye first.<br/>',NULL,3431,3431);
INSERT INTO stanza VALUES('E667','2','Seek ye first, not earth''s aspirings,<br/>Ceaseless longings, vain desirings,<br/>But your precious soul''s requirings<br/>Seek ye first,<br/>',NULL,3432,3432);
INSERT INTO stanza VALUES('E667','3','Seek ye first God''s peace and blessing;<br/>Ye have all if this possessing;<br/>Come, your need and sin confessing,<br/>Seek Him first.<br/>',NULL,3433,3433);
INSERT INTO stanza VALUES('E667','4','Seek Him first, then when forgiven,<br/>Pardoned, with the peace of heaven,<br/>Let your life to Him be given:<br/>Seek this first.<br/>',NULL,3434,3434);
INSERT INTO stanza VALUES('E667','5','Seek this first-Be pure and holy;<br/>Like the Master, meek and lowly;<br/>Yielded to His service wholly:<br/>Seek this first.<br/>',NULL,3435,3435);
INSERT INTO stanza VALUES('E667','6','Seek the coming of His kingdom;<br/>Seek the souls around to win them,<br/>Seek to Jesus Christ to bring them:<br/>Seek this first.<br/>',NULL,3436,3436);
INSERT INTO stanza VALUES('E667','7','Seek this first, His promise trying;<br/>It is sure, all need supplying.<br/>Heavenly things, on Him relying,<br/>Seek ye first.<br/>',NULL,3437,3437);
INSERT INTO stanza VALUES('E668','1','Have you felt the Father''s love?<br/>Still there''s more to follow;<br/>And His mercy have you proved?<br/>Still there''s more to follow.<br/>Oh, the love the Father shows,<br/>Still there''s more to follow;<br/>Freely He His love bestows,<br/>Still there''s more to follow.<br/>',NULL,3438,3438);
INSERT INTO stanza VALUES('E668','chorus','More and more, more and more,<br/>Always more to follow;<br/>Oh, His matchless, boundless love,<br/>Still there''s more to follow.<br/>',NULL,3439,3439);
INSERT INTO stanza VALUES('E668','2','Have you felt the Savior near?<br/>Still there''s more to follow;<br/>Does His blessed presence cheer?<br/>Still there''s more to follow;<br/>Oh, the grace that Jesus shows,<br/>Still there''s more to follow;<br/>Freely He His grace bestows,<br/>Still there''s more to follow.<br/>',NULL,3440,3440);
INSERT INTO stanza VALUES('E668','3','Have you felt the Spirit''s power?<br/>Still there''s more to follow;<br/>Falling like the gentle shower?<br/>Still there''s more to follow;<br/>Oh, the power the Spirit shows,<br/>Still there''s more to follow;<br/>Freely He His power bestows,<br/>Still there''s more to follow.<br/>',NULL,3441,3441);
INSERT INTO stanza VALUES('E669','1','In the heart of Jesus<br/>There is love for you,<br/>Love most pure and tender,<br/>Love most deep and true;<br/>Why should you be lonely,<br/>Why for friendship sigh,<br/>When the heart of Jesus<br/>Has a full supply?<br/>',NULL,3442,3442);
INSERT INTO stanza VALUES('E669','2','In the mind of Jesus<br/>There is thought of you,<br/>Warm as summer sunshine,<br/>Sweet as morning dew;<br/>Why should you be fearful,<br/>Why take anxious thought,<br/>Since the mind of Jesus<br/>Cares for those He brought?<br/>',NULL,3443,3443);
INSERT INTO stanza VALUES('E669','3','In the field of Jesus<br/>There is work for you;<br/>Such as even angels<br/>Might rejoice to do;<br/>Why stand idly sighing<br/>For some life-work grand,<br/>While the field of Jesus<br/>Seeks your reaping hand?<br/>',NULL,3444,3444);
INSERT INTO stanza VALUES('E669','4','In the Church of Jesus<br/>There''s a place for you;<br/>Glorious, bright, and joyous,<br/>Right and peaceful too;<br/>Why then, like a wand''rer,<br/>Roam with weary pace,<br/>If the Church of Jesus<br/>Hold for you a place?<br/>',NULL,3445,3445);
INSERT INTO stanza VALUES('E670','1','Take the name of Jesus with you,<br/>Child of sorrow and of woe;<br/>It will joy and comfort give you,<br/>Take it then where''er you go.<br/>',NULL,3446,3446);
INSERT INTO stanza VALUES('E670','chorus','Precious name! Oh, how sweet!<br/>Hope of earth and joy of heav''n;<br/>Precious name! Oh, how sweet!<br/>Hope of earth and joy of heav''n.<br/>',NULL,3447,3447);
INSERT INTO stanza VALUES('E670','2','Take the name of Jesus ever,<br/>As a shield from every snare.<br/>If temptations round you gather,<br/>Breathe that holy name in prayer.<br/>',NULL,3448,3448);
INSERT INTO stanza VALUES('E670','3','Oh, the precious name of Jesus,<br/>How it thrills our souls with joy;<br/>All the favor of the Father<br/>In this name we may enjoy.<br/>',NULL,3449,3449);
INSERT INTO stanza VALUES('E670','4','At the name of Jesus bowing,<br/>Falling prostrate at His feet,<br/>Claim His vict''ry over evil<br/>And the enemy defeat.<br/>',NULL,3450,3450);
INSERT INTO stanza VALUES('E671','1','Deep down into the depths of this Thy Name,<br/>My God, I sink and dwell in calm delight;<br/>Thou art enough however long the day,<br/>Thou art enough however dark the night.<br/>',NULL,3451,3451);
INSERT INTO stanza VALUES('E671','2','Thou art my God-the All-Sufficient One,<br/>Thou canst create for me whate''er I lack;<br/>Thy mighty hand has strewn the lonely track<br/>With miracles of love and tender care.<br/>',NULL,3452,3452);
INSERT INTO stanza VALUES('E671','3','For me Thy trusting one. My God I dare<br/>Once more to fling myself upon Thy breast,<br/>And there adore Thy ways in faith''s deep rest,<br/>And there adore Thy ways in faith''s quiet rest.<br/>',NULL,3453,3453);
INSERT INTO stanza VALUES('E672','1','Not what I am, O Lord, but what Thou art;<br/>That, that alone, can be my soul''s true rest;<br/>Thy love, not mine, bids fear and doubt depart,<br/>And stills the tempest of my tossing breast.<br/>',NULL,3454,3454);
INSERT INTO stanza VALUES('E672','2','It is Thy perfect love that casts out fear;<br/>I know the voice that speaks the It is I,<br/>And in these well-known words of heavenly cheer<br/>I hear the joy that bids each sorrow fly.<br/>',NULL,3455,3455);
INSERT INTO stanza VALUES('E672','3','Thy Name is Love! I hear it from yon Cross;<br/>Thy Name is Love! I read it in yon tomb:<br/>All meaner love is perishable dross,<br/>But this shall light me through time''s thickest gloom.<br/>',NULL,3456,3456);
INSERT INTO stanza VALUES('E672','4','It blesses now, and shall forever bless;<br/>It saves me now, and shall for ever save;<br/>It holds me up in days of helplessness,<br/>It bears me safely o''er each swelling wave.<br/>',NULL,3457,3457);
INSERT INTO stanza VALUES('E672','5','''Tis what I know of Thee, my Lord and God,<br/>That fills my soul with peace, my lips with song;<br/>Thou art my health, my joy, my staff, my rod;<br/>Leaning on Thee, in weakness I am strong.<br/>',NULL,3458,3458);
INSERT INTO stanza VALUES('E672','6','More of Thyself, Oh, show me, hour by hour;<br/>More of Thy glory, O my God and Lord;<br/>More of Thyself in all Thy grace and power;<br/>More of Thy love and truth, Incarnate Word.<br/>',NULL,3459,3459);
INSERT INTO stanza VALUES('E673','1','I take my portion from Thy hand,<br/>And do not seek to understand;<br/>For I am blind, while Thou dost see,<br/>Thy will is mine, whate''er it be.<br/>',NULL,3460,3460);
INSERT INTO stanza VALUES('E673','chorus','Whate''er it be! Whate''er it be!<br/>I do not fear, whate''er it be!<br/>Thy love divine sustaineth me;<br/>Thy will is mine, whate''er it be.<br/>',NULL,3461,3461);
INSERT INTO stanza VALUES('E673','2','When darkness doth Thy face obscure,<br/>And many sorrows I endure,<br/>I think of Christ''s Gethsemane;<br/>Thy will is mine, whate''er it be.<br/>',NULL,3462,3462);
INSERT INTO stanza VALUES('E673','3','When tender joys to me are known,<br/>I render thanks to Thee alone;<br/>I know my cup is filled by Thee;<br/>Thy will is mine, whate''er it be.<br/>',NULL,3463,3463);
INSERT INTO stanza VALUES('E673','4','Thus calmly do I face my lot,<br/>Accept it, Lord, and doubt Thee not;<br/>Lo! All things work for good to me;<br/>Thy will is mine, whate''er it be.<br/>',NULL,3464,3464);
INSERT INTO stanza VALUES('E674','1','The Lord will silently plan for thee,<br/>Thou object of omniscient care;<br/>God undertakes Himself to be<br/>Thy Pilot through each subtle snare.<br/>',NULL,3465,3465);
INSERT INTO stanza VALUES('E674','2','The Lord will silently plan for thee,<br/>So certainly, He cannot fail!<br/>Rest on the faithfulness of God,<br/>In Him thou surely shalt prevail.<br/>',NULL,3466,3466);
INSERT INTO stanza VALUES('E674','3','The Lord will silently plan for thee,<br/>Some wonderful surprise of love.<br/>Eye hath not seen, nor ear hath heard,<br/>But it is kept for thee to prove.<br/>',NULL,3467,3467);
INSERT INTO stanza VALUES('E674','4','The Lord will silently plan for thee,<br/>His purpose He''ll to thee unfold;<br/>The tangled skein shall shine at last,<br/>A masterpiece of skill untold.<br/>',NULL,3468,3468);
INSERT INTO stanza VALUES('E674','5','The Lord will silently plan for thee,<br/>A happy child kept in His care<br/>As though no other claimed His love,<br/>But thou alone to Him wert dear.<br/>',NULL,3469,3469);
INSERT INTO stanza VALUES('E675','1','God moves in a mysterious way<br/>His wonders to perform:<br/>He plants His footsteps in the sea,<br/>And rides upon the storm.<br/>',NULL,3470,3470);
INSERT INTO stanza VALUES('E675','2','Deep in unfathomable mines<br/>Of never-failing skill,<br/>He treasures up His bright designs,<br/>And works His sovereign will.<br/>',NULL,3471,3471);
INSERT INTO stanza VALUES('E675','3','Ye fearful saints, fresh courage take;<br/>The clouds ye so much dread<br/>Are big with mercy, and shall break<br/>In blessings on your head.<br/>',NULL,3472,3472);
INSERT INTO stanza VALUES('E675','4','Judge not the Lord by feeble sense,<br/>But trust Him for His grace;<br/>Behind a frowning providence<br/>He hides a smiling face.<br/>',NULL,3473,3473);
INSERT INTO stanza VALUES('E675','5','His purpose will ripen fast,<br/>Unfolding every hour:<br/>The bud may have a bitter taste,<br/>But sweet will be the flower.<br/>',NULL,3474,3474);
INSERT INTO stanza VALUES('E675','6','Blind unbelief is sure to err,<br/>And scan His work in vain;<br/>God is His own Interpreter,<br/>And He will make it plain.<br/>',NULL,3475,3475);
INSERT INTO stanza VALUES('E676','1','All thy griefs by Him are ordered,<br/>Needful is each one for thee;<br/>All thy tears by Him are counted,<br/>One too much there cannot be;<br/>And if while they fall so quickly<br/>Thou canst own His way is right,<br/>Then each bitter tear of anguish<br/>Precious is in Jesus'' sight.<br/>',NULL,3476,3476);
INSERT INTO stanza VALUES('E676','2','Far too well thy Savior loves thee<br/>To allow thy life to be<br/>One long, calm, unbroken summer-<br/>One unruffled, storm less sea;<br/>He would have thee fondly nestling<br/>Closer to His loving breast,<br/>He would have that day seem brighter<br/>When alone is perfect rest.<br/>',NULL,3477,3477);
INSERT INTO stanza VALUES('E677','1','Art thou sunk in depths of sorrow<br/>Where no arm can reach so low?<br/>There is One whose arms almighty<br/>Reach beyond thy deepest woe.<br/>God th'' Eternal is thy refuge,<br/>Let it still thy wild alarms;<br/>Underneath thy deepest sorrow,<br/>Are the everlasting arms.<br/>',NULL,3478,3478);
INSERT INTO stanza VALUES('E677','chorus','Underneath thee, underneath thee,<br/>Are the everlasting arms,<br/>Everlasting, everlasting,<br/>Are the everlasting arms.<br/>',NULL,3479,3479);
INSERT INTO stanza VALUES('E677','2','Other arms grow faint and weary,<br/>These can never faint, nor fail;<br/>Others reach our mounts of blessing,<br/>These our lowest loneliest vale.<br/>O that all might know His friendship!<br/>O that all might see His charms!<br/>O that all might have beneath them<br/>Jesus'' everlasting arms.<br/>',NULL,3480,3480);
INSERT INTO stanza VALUES('E677','3','Underneath us, O how easy;<br/>We have not to mount on high,<br/>But to sink into His fulness,<br/>And in trustful weakness lie.<br/>And we find our humbling failures<br/>Save us from the strength that harms!<br/>We may fail, but underneath us<br/>Are the everlasting arms.<br/>',NULL,3481,3481);
INSERT INTO stanza VALUES('E677','4','Arms of Jesus! Fold me closer,<br/>To Thy strong and loving breast,<br/>Till my spirit on Thy bosom<br/>Finds its everlasting rest;<br/>And when time''s last sands are sinking,<br/>Shield my heart from all alarms,<br/>Softly whispering, "Underneath thee,<br/>Are the everlasting arms."<br/>',NULL,3482,3482);
INSERT INTO stanza VALUES('E678','1','I will not be afraid;<br/>I will not be afraid;<br/>I will look upward,<br/>And travel onward,<br/>And not be afraid.<br/>',NULL,3483,3483);
INSERT INTO stanza VALUES('E678','2','He says He will be with me;<br/>He says He will be with me;<br/>He goes before me,<br/>And is beside me,<br/>So I''m not afraid.<br/>',NULL,3484,3484);
INSERT INTO stanza VALUES('E678','3','His arms are underneath me;<br/>His arms are underneath me;<br/>His hands uphold me,<br/>His love enfolds me,<br/>So I''m not afraid.<br/>',NULL,3485,3485);
INSERT INTO stanza VALUES('E678','4','His Word will stand for ever;<br/>His Word will stand for ever;<br/>His truth it shall be<br/>My shield and buckler,<br/>So I''m not afraid.<br/>',NULL,3486,3486);
INSERT INTO stanza VALUES('E678','5','He will give grace and glory;<br/>He will give grace and glory;<br/>His cross before me,<br/>His banner o''er me,<br/>So I''m not afraid.<br/>',NULL,3487,3487);
INSERT INTO stanza VALUES('E678','6','So we go singing onward;<br/>So we go singing onward;<br/>We''re pressing forward,<br/>We''re marching upward,<br/>To Him unafraid.<br/>',NULL,3488,3488);
INSERT INTO stanza VALUES('E679','1','Safe in the arms of Jesus,<br/>Safe on His gentle breast,<br/>There by His love o''ershaded,<br/>Sweetly my soul doth rest.<br/>Hark! ''tis a song of heaven<br/>Borne in the sweetest voice,<br/>Echoed by saints in spirit,<br/>Making my heart rejoice.<br/>',NULL,3489,3489);
INSERT INTO stanza VALUES('E679','chorus','Safe in the arms of Jesus,<br/>Safe on His gentle breast,<br/>There by His love o''ershaded,<br/>Sweetly my soul doth rest.<br/>',NULL,3490,3490);
INSERT INTO stanza VALUES('E679','2','Safe in the arms of Jesus,<br/>Safe from corroding care,<br/>Safe from the world''s temptations,<br/>Sin cannot harm me there.<br/>Free from the blight of sorrow,<br/>Free from my doubts and fears;<br/>Only a few more trials,<br/>Only a few more tears.<br/>',NULL,3491,3491);
INSERT INTO stanza VALUES('E679','3','Jesus, my heart''s dear Refuge,<br/>Jesus has died for me;<br/>Firm on the Rock of Ages<br/>Ever my trust shall be.<br/>Here let my wait with patience,<br/>Wait till the night is o''er,<br/>Wait till I see the morning<br/>Break on the golden shore.<br/>',NULL,3492,3492);
INSERT INTO stanza VALUES('E680','1','"All in His hands"-what confidence it brings<br/>To tested hearts, to know that all the things<br/>That make up life and circumstance, He holds<br/>In His strong hands, and patiently unfolds<br/>Th'' eternal purpose of His sovereign Will-<br/>That all things shall His grace and glory fill.<br/>',NULL,3493,3493);
INSERT INTO stanza VALUES('E680','2','"All in His hands"? Then life with purpose moves<br/>Within the circle of His will, and proves<br/>It good, acceptable. The hands of man<br/>Or Satan cannot mar or foil the plan<br/>Which God ordained-to manifest His Son<br/>In earthen vessels, to the world undone.<br/>',NULL,3494,3494);
INSERT INTO stanza VALUES('E681','1','Our times are in Thy hand;<br/>O God, we wish them there;<br/>Our lives, our souls, our all, we leave<br/>Entirely to Thy care.<br/>',NULL,3495,3495);
INSERT INTO stanza VALUES('E681','2','Our times are in Thy hand:<br/>Whatever they may be;<br/>Pleasing or painful, dark or bright,<br/>As best may seem to Thee.<br/>',NULL,3496,3496);
INSERT INTO stanza VALUES('E681','3','Our times are in Thy hand;<br/>Why should we doubt or fear?<br/>A father''s hand will never cause<br/>His child a needless tear.<br/>',NULL,3497,3497);
INSERT INTO stanza VALUES('E681','4','Our times are in Thy hand;<br/>Jesus, the Crucified,<br/>Whose hand our many sins have pierced,<br/>Is now our guard and guide.<br/>',NULL,3498,3498);
INSERT INTO stanza VALUES('E681','5','Our times are in Thy hand;<br/>We''ll always trust in Thee,<br/>Till we possess the promised crown,<br/>And all Thy glory see.<br/>',NULL,3499,3499);
INSERT INTO stanza VALUES('E682','1','When I survey life''s varied scene,<br/>Amid the darkest hours<br/>Sweet rays of comfort shine between<br/>And thorns are mixed with flowers.<br/>',NULL,3500,3500);
INSERT INTO stanza VALUES('E682','2','Lord, teach me to adore Thy hand,<br/>From whence my comforts flow,<br/>And let me in this desert land<br/>A glimpse of glory know.<br/>',NULL,3501,3501);
INSERT INTO stanza VALUES('E682','3','Father, whate''er of earthly bliss<br/>Thy sovereign hand denies,<br/>Accepted at Thy throne of grace,<br/>Let this petition rise:<br/>',NULL,3502,3502);
INSERT INTO stanza VALUES('E682','4','Give me a calm, a thankful heart,<br/>From every murmur free;<br/>The blessings of Thy grace impart,<br/>And let me live to Thee.<br/>',NULL,3503,3503);
INSERT INTO stanza VALUES('E682','5','Let the sweet hope that Thou art mine<br/>My life and death attend,<br/>Thy presence through my journey shine,<br/>And crown my journey''s end.<br/>',NULL,3504,3504);
INSERT INTO stanza VALUES('E683','1','God holds the key to all unknown,<br/>And I am glad;<br/>If other hands should hold the key,<br/>Or if He trusted it to me,<br/>I might be sad.<br/>',NULL,3505,3505);
INSERT INTO stanza VALUES('E683','2','What if tomorrow''s cares were here,<br/>Without its rest?<br/>I''d rather He unlocked the day,<br/>And, as the hours swing open, say,<br/>My will is best.<br/>',NULL,3506,3506);
INSERT INTO stanza VALUES('E683','3','The very dimness of my sight<br/>Makes me secure;<br/>For, groping in my misty way,<br/>I feel His hand; I hear Him say,<br/>My help is sure.<br/>',NULL,3507,3507);
INSERT INTO stanza VALUES('E683','4','I cannot read His future plans;<br/>But this I know:<br/>I have the smiling of His face,<br/>And all the refuge of His grace<br/>While here below.<br/>',NULL,3508,3508);
INSERT INTO stanza VALUES('E683','5','Enough; this covers all my wants;<br/>And so I rest;<br/>For what I cannot, He can see,<br/>And in His care I saved shall be,<br/>Forever blest.<br/>',NULL,3509,3509);
INSERT INTO stanza VALUES('E684','1','Come, ye disconsolate, where''er ye languish;<br/>Come to the mercy-seat, fervently kneel;<br/>Here bring your wounded hearts, here tell your anguish,<br/>Earth has no sorrow that heaven cannot heal.<br/>',NULL,3510,3510);
INSERT INTO stanza VALUES('E684','2','Joy of the comfortless, light of the straying,<br/>Hope of the penitent, fadeless and pure;<br/>Here speaks the Comforter, tenderly saying-<br/>Earth has no sorrow that heaven cannot cure.<br/>',NULL,3511,3511);
INSERT INTO stanza VALUES('E684','3','Here see the Bread of Life; see water flowing<br/>Forth from the throne of God, pure from above;<br/>Come to the feast of love; come, ever knowing<br/>Earth has no sorrow but heaven can remove.<br/>',NULL,3512,3512);
INSERT INTO stanza VALUES('E685','1','Lord, Thou art with me!<br/>Whom shall I fear?<br/>Who then can harm me<br/>While Thou art near?<br/>Under Thy shadow<br/>Is my retreat;<br/>There to my taste,<br/>Lord, Thy fruit is sweet.<br/>',NULL,3513,3513);
INSERT INTO stanza VALUES('E685','2','Lord, Thou art with me,<br/>And Thou dost give<br/>Strength for the journey,<br/>Grace now to live.<br/>Mercies each morning<br/>Thou dost renew;<br/>And for my prospect,<br/>Thy rest in view.<br/>',NULL,3514,3514);
INSERT INTO stanza VALUES('E685','3','Lord, Thou art with me;<br/>Onward I move;<br/>Each day I''m proving<br/>More of Thy love.<br/>Now Thou art training,<br/>Setting me free<br/>From all that hinders,<br/>To dwell with Thee.<br/>',NULL,3515,3515);
INSERT INTO stanza VALUES('E686','1','"Fear not, I am with thee";<br/>Blessed golden ray,<br/>Like a star of glory,<br/>Lighting up my way!<br/>Through the clouds of midnight,<br/>This bright promise shone,<br/>"I will never leave thee,<br/>Never will leave thee alone."<br/>',NULL,3516,3516);
INSERT INTO stanza VALUES('E686','chorus','No, never alone,<br/>No, never alone;<br/>He promised never to leave me,<br/>Never to leave me alone;<br/>No, never alone,<br/>No, never alone;<br/>He promised never to leave me,<br/>Never to leave me alone.<br/>',NULL,3517,3517);
INSERT INTO stanza VALUES('E686','2','Roses fade around me,<br/>Lilies bloom and die,<br/>Earthly sunbeams vanish-<br/>Radiant still the sky!<br/>Jesus, Henna-flower,<br/>Blooming for His own,<br/>Jesus, heaven''s sunshine,<br/>Never will leave me alone.<br/>',NULL,3518,3518);
INSERT INTO stanza VALUES('E686','3','Steps unseen before me,<br/>Hidden dangers near;<br/>Nearer still my Savior,<br/>Whispering, "Be of cheer";<br/>Joys, like birds of springtime,<br/>To my heart have flown,<br/>Singing all so sweetly,<br/>"He will not leave me alone."<br/>',NULL,3519,3519);
INSERT INTO stanza VALUES('E687','1','O Thou, in whose presence my soul takes delight,<br/>On whom in affliction I call,<br/>My comfort by day and my song in the night,<br/>My hope, my salvation, my all!<br/>',NULL,3520,3520);
INSERT INTO stanza VALUES('E687','2','Where dost Thou, dear Shepherd, resort with Thy sheep,<br/>To feed them in pastures of love;<br/>Say, why in the valley of death should I weep,<br/>Or alone in this wilderness rove?<br/>',NULL,3521,3521);
INSERT INTO stanza VALUES('E687','3','Oh, why should I wander, and alien from Thee,<br/>Or cry in the desert for bread?<br/>Thy foes will rejoice when my sorrows they see,<br/>And smile at the tears I have shed.<br/>',NULL,3522,3522);
INSERT INTO stanza VALUES('E687','4','Ye daughters of Zion, declare, have you seen<br/>The Star that on Israel shone?<br/>Say, if in your tents my Beloved has been,<br/>And where with His flocks He is gone.<br/>',NULL,3523,3523);
INSERT INTO stanza VALUES('E687','5','Dear Shepherd! I hear, and will follow Thy call;<br/>I know the sweet sound of Thy voice;<br/>Restore and defend me, for Thou art my all,<br/>And in Thee I''ll ever rejoice.<br/>',NULL,3524,3524);
INSERT INTO stanza VALUES('E688','1','I''ve seen the lighting flashing,<br/>And heard the thunder roll;<br/>I''ve felt sin''s breakers dashing,<br/>Trying to conquer my soul;<br/>I''ve heard the voice of Jesus,<br/>Telling me still to fight on;<br/>He promised never to leave me,<br/>Never to leave me alone.<br/>',NULL,3525,3525);
INSERT INTO stanza VALUES('E688','chorus','No, never alone,<br/>No, never alone;<br/>He promised never to leave me,<br/>Never to leave me alone;<br/>No, never alone,<br/>No, never alone;<br/>He promised never to leave me,<br/>Never to leave me alone.<br/>',NULL,3526,3526);
INSERT INTO stanza VALUES('E688','2','The world''s fierce winds are blowing,<br/>Temptations are sharp and keen;<br/>I feel a peace in knowing<br/>My Savior stands between;<br/>He stands to shield me from danger,<br/>When earthly friends are gone,<br/>He promised never to leave me,<br/>Never to leave me alone.<br/>',NULL,3527,3527);
INSERT INTO stanza VALUES('E688','3','When in affliction''s valley,<br/>I''m treading the road of care,<br/>My Savior helps me to carry<br/>My cross when heavy to bear;<br/>My feet entangled with briars,<br/>Ready to cast me down;<br/>My Savior whispered His promise,<br/>Never to leave me alone.<br/>',NULL,3528,3528);
INSERT INTO stanza VALUES('E688','4','He died for me on the mountain,<br/>For me they pierced His side,<br/>For me He opened that fountain,<br/>The crimson, cleaning tide;<br/>For me He waiteth in glory,<br/>Seated upon His throne;<br/>He promised never to leave me,<br/>Never to leave me alone.<br/>',NULL,3529,3529);
INSERT INTO stanza VALUES('E689','1','O child of the Kingdom in doubt and distress!<br/>Why linger-thy Father is waiting to bless?<br/>Assured of the mercy and love of thy Lord,<br/>Claim each precious promise, take God at His Word!<br/>',NULL,3530,3530);
INSERT INTO stanza VALUES('E689','chorus','Take God at His Word,<br/>Take God at His Word!<br/>Believe every promise,<br/>Take God at His Word!<br/>',NULL,3531,3531);
INSERT INTO stanza VALUES('E689','2','Thy pathway through sorrows and trials may go,<br/>Though deep be the waters, they will not o''erflow;<br/>Oh, trust in the Savior, His name be adored!<br/>Confide in His promise, take God at His Word!<br/>Take God at His Word,<br/>Take God at His Word!<br/>Believe every promise,<br/>Take God at His Word!<br/>',NULL,3532,3532);
INSERT INTO stanza VALUES('E689','3','He says He will guide thee through sunshine and gloom;<br/>His presence shall brighten thy path to the throne;<br/>And down in death''s valley His voice shall be heard:<br/>Fear not, tempted Christian, take God at His Word!<br/>Take God at His Word,<br/>Take God at His Word!<br/>Believe every promise,<br/>Take God at His Word!<br/>',NULL,3533,3533);
INSERT INTO stanza VALUES('E689','4','An heir to a kingdom, and promised a crown;<br/>With God thy protector-oh, why be cast down?<br/>Oh, think of the triumphs of faith thou hast heard;<br/>Be not unbelieving, take God at His Word!<br/>Take God at His Word,<br/>Take God at His Word!<br/>Believe every promise,<br/>Take God at His Word!<br/>',NULL,3534,3534);
INSERT INTO stanza VALUES('E690','1','Hark! A voice from heav''n proclaiming,<br/>"It is done."<br/>Faith repeats the echo claiming,<br/>"It is done."<br/>',NULL,3535,3535);
INSERT INTO stanza VALUES('E690','chorus','Hear the message from the throne,<br/>Claim the promise, doubting one;<br/>God hath spoken, "It is done."<br/>Faith has answered, "It is done."<br/>Prayer is over, praise begun.<br/>Hallelujah, "It is done."<br/>',NULL,3536,3536);
INSERT INTO stanza VALUES('E690','2','Hear the bleeding Savior crying,<br/>"It is done."<br/>Claim His finished work, replying,<br/>"It is done."<br/>',NULL,3537,3537);
INSERT INTO stanza VALUES('E690','3','Yield thyself in consecration,<br/>"It is done."<br/>Take the Lord for full salvation,<br/>"It is done."<br/>',NULL,3538,3538);
INSERT INTO stanza VALUES('E690','4','Claim the promise of His healing,<br/>"It is done."<br/>Trust without a sign or feeling,<br/>"It is done."<br/>',NULL,3539,3539);
INSERT INTO stanza VALUES('E690','5','Say of every promised blessing,<br/>"It is done."<br/>Rest upon His word, confessing,<br/>"It is done."<br/>',NULL,3540,3540);
INSERT INTO stanza VALUES('E690','6','This the secret of receiving,<br/>"It is done."<br/>Take Him at His word believing,<br/>"It is done."<br/>',NULL,3541,3541);
INSERT INTO stanza VALUES('E691','1','Hark! The voice of love and mercy<br/>Sounds aloud from Calvary;<br/>See, it rends the rocks asunder,<br/>Shakes the earth, and veils the sky:<br/>"It is finished!" "It is finished!"<br/>Hear the dying Savior cry.<br/>',NULL,3542,3542);
INSERT INTO stanza VALUES('E691','2','"It is finished!" Oh, what pleasure<br/>Do these charming words afford!<br/>Heavenly blessings without measure<br/>Flow to us from Christ, the Lord:<br/>"It is finished!" "It is finished!"<br/>Saints, the dying words record.<br/>',NULL,3543,3543);
INSERT INTO stanza VALUES('E691','3','Finished all the types and shadows<br/>Of the ceremonial law!<br/>Finished all that God had promised;<br/>Death and hell no more shall awe:<br/>"It is finished!" "It is finished!"<br/>Saints, from hence your comfort draw.<br/>',NULL,3544,3544);
INSERT INTO stanza VALUES('E691','4','Tune your harps anew, ye seraphs,<br/>Join to sing the pleasing theme;<br/>All on earth and all in heaven<br/>Join to praise Immanuel''s name:<br/>Hallelujah! Hallelujah!<br/>Glory to the bleeding Lamb!<br/>',NULL,3545,3545);
INSERT INTO stanza VALUES('E692','1','There''s a little word that the Lord has giv''n<br/>For our help in the hour of need:<br/>Let us reckon ourselves to be dead to sin,<br/>To be dead and dead indeed.<br/>',NULL,3546,3546);
INSERT INTO stanza VALUES('E692','chorus','Let us reckon, reckon, reckon,<br/>Let us reckon, rather than feel;<br/>Let us be true to the reck''ning,<br/>And He will make it real.<br/>',NULL,3547,3547);
INSERT INTO stanza VALUES('E692','2','There''s another word that the Lord has giv''n,<br/>In the very same verse we read,<br/>Let us reckon ourselves as alive to Him,<br/>As alive and alive indeed.<br/>',NULL,3548,3548);
INSERT INTO stanza VALUES('E692','3','While we trust in feeling or inward frames<br/>We shall always be tossed about,<br/>Let us anchor fast to the Word of God,<br/>And reckon away our doubt.<br/>',NULL,3549,3549);
INSERT INTO stanza VALUES('E692','4','As the mariner, when the skies are dim,<br/>Sails on by his compass true;<br/>So our faith would cling to the promise firm,<br/>And reckon the journey through.<br/>',NULL,3550,3550);
INSERT INTO stanza VALUES('E692','5','O how sweet it is to be anchored fast<br/>To a hope that can never fail;<br/>Let us reckon on with a firmer trust,<br/>Till we anchor within the veil.<br/>',NULL,3551,3551);
INSERT INTO stanza VALUES('E692','6','You may claim the promise from every pain,<br/>You may know His power to heal;<br/>But your faith must rest in His word alone,<br/>And reckon, rather than feel.<br/>',NULL,3552,3552);
INSERT INTO stanza VALUES('E693','1','He faileth not, for He is God;<br/>He faileth not, His grace how good!<br/>He faileth not, His Word is clear;<br/>If we have God, whom need we fear?<br/>',NULL,3553,3553);
INSERT INTO stanza VALUES('E693','2','The highest mount, He can make plain;<br/>The wildest flood, He can restrain!<br/>God of Impossibilities!<br/>Poor puny man, now learn His ways.<br/>',NULL,3554,3554);
INSERT INTO stanza VALUES('E693','3','The axe did swim on Jordan''s wave!<br/>Our God the Red Sea''s waters clave!<br/>He stopped the sun! Made long the day!<br/>This is the God to whom we pray.<br/>',NULL,3555,3555);
INSERT INTO stanza VALUES('E693','4','He bars the sea with feeble sand!<br/>The proud waves bow at His command!<br/>If God is thine, what more your need?<br/>Can He not work for you indeed?<br/>',NULL,3556,3556);
INSERT INTO stanza VALUES('E693','5','Our God is love; your needs are known;<br/>His promises He''ll fully own.<br/>Our gracious God bows down His ear<br/>The feeblest, weakest cry to hear.<br/>',NULL,3557,3557);
INSERT INTO stanza VALUES('E693','6','Our God is light, and never yet,<br/>One promise did He e''er forget.<br/>His promises in Christ the Son<br/>Are fully pledged, Yea and Amen.<br/>',NULL,3558,3558);
INSERT INTO stanza VALUES('E693','7','Our faithful God, faith cannot break,<br/>Nor death, nor hell, His promise shake!<br/>Who ask in faith, He''ll not deny;<br/>His Word is sure, He must reply.<br/>',NULL,3559,3559);
INSERT INTO stanza VALUES('E693','8','He faileth not, let all men hear;<br/>He faileth not, His Word is clear.<br/>He faileth not, His grace how good;<br/>He faileth not, for He is God!<br/>',NULL,3560,3560);
INSERT INTO stanza VALUES('E694','1','Be not dismayed whate''er betide,<br/>God will take care of you!<br/>Beneath His wings of love abide,<br/>God will take care of you!<br/>',NULL,3561,3561);
INSERT INTO stanza VALUES('E694','chorus','God will take care of you,<br/>Through every day o''er all the way;<br/>He will take care of you;<br/>God will take care of you!<br/>',NULL,3562,3562);
INSERT INTO stanza VALUES('E694','2','Through days of toil when heart doth fail,<br/>God will take care of you!<br/>When dangers fierce your path assail,<br/>God will take care of you!<br/>',NULL,3563,3563);
INSERT INTO stanza VALUES('E694','3','All you may need He will provide,<br/>God will take care of you!<br/>Trust Him, and you will be satisfied,<br/>God will take care of you!<br/>',NULL,3564,3564);
INSERT INTO stanza VALUES('E694','4','Lonely and sad, from friends apart,<br/>God will take care of you!<br/>He will give peace to your aching heart,<br/>God will take care of you!<br/>',NULL,3565,3565);
INSERT INTO stanza VALUES('E694','5','No matter what may be the test,<br/>God will take care of you!<br/>Lean, weary one, upon His breast,<br/>God will take care of you!<br/>',NULL,3566,3566);
INSERT INTO stanza VALUES('E695','1','Does Jesus care when my heart is pained<br/>Too deeply for mirth or song,<br/>As the burdens press,<br/>And the cares distress,<br/>And the way grows weary and long?<br/>',NULL,3567,3567);
INSERT INTO stanza VALUES('E695','chorus','O yes, He cares, I know He cares,<br/>His heart is touched with my grief;<br/>When the days are weary,<br/>The long night dreary,<br/>I know my Savior cares.<br/>',NULL,3568,3568);
INSERT INTO stanza VALUES('E695','2','Does Jesus care when my way is dark<br/>With a nameless dread and fear?<br/>As the daylight fades<br/>Into deep night shades,<br/>Does He care enough to be near?<br/>',NULL,3569,3569);
INSERT INTO stanza VALUES('E695','3','Does Jesus care when I''ve tried and failed<br/>To resist some temptation strong;<br/>When for my deep grief<br/>There in no relief,<br/>Though my tear flow all the night long?<br/>',NULL,3570,3570);
INSERT INTO stanza VALUES('E695','4','Does Jesus care when I''ve said "goodbye"<br/>To the dearest on earth to me,<br/>And my sad heart aches<br/>Till it nearly breaks,<br/>Is it aught to Him? Does He see?<br/>',NULL,3571,3571);
INSERT INTO stanza VALUES('E696','1','Cast thou thy care upon the Lord,<br/>The care that loads thy heart;<br/>Take Him this moment at His word,<br/>And let Him do His part.<br/>',NULL,3572,3572);
INSERT INTO stanza VALUES('E696','2','The need is deep, the care is great,<br/>The burden hard to bear;<br/>Roll it on Him with all its weight,<br/>And leave it resting there.<br/>',NULL,3573,3573);
INSERT INTO stanza VALUES('E696','3','This heavy thing, it is His gift,<br/>His portion, thee to bless;<br/>Give it Him back; what He shall lift<br/>No more on thee shall press.<br/>',NULL,3574,3574);
INSERT INTO stanza VALUES('E696','4','Cast all thy care, and not a part,<br/>The great things and the small;<br/>The Lord''s all-loving, mighty heart<br/>Has room and thought for all.<br/>',NULL,3575,3575);
INSERT INTO stanza VALUES('E696','5','Yes, He will ponder every care,<br/>Consider each detail;<br/>Thyself, thy burden, let Him bear;<br/>He will not, cannot, fail.<br/>',NULL,3576,3576);
INSERT INTO stanza VALUES('E697','1','Weary pilgrim on life''s pathway-<br/>Struggling on beneath thy load-<br/>Hear these words of consolation,<br/>"Cast thy burden on the Lord."<br/>',NULL,3577,3577);
INSERT INTO stanza VALUES('E697','chorus','Cast thy burden on the Lord!<br/>Cast thy burden on the Lord,<br/>And He will strengthen thee,<br/>sustain and comfort thee-<br/>Cast thy burden on the Lord.<br/>',NULL,3578,3578);
INSERT INTO stanza VALUES('E697','2','Are thy tired feet unsteady?<br/>Does thy lamp no light afford?<br/>Is thy cross too great and heavy?<br/>"Cast thy burden on the Lord."<br/>',NULL,3579,3579);
INSERT INTO stanza VALUES('E697','3','Are the ties of friendship severed?<br/>Hushed the voices fondly heard?<br/>Breaks thy heart with weight of anguish?<br/>"Cast thy burden on the Lord."<br/>',NULL,3580,3580);
INSERT INTO stanza VALUES('E697','4','Does thy heart with faintness falter?<br/>Does thy mind forget His word?<br/>Does thy strength succumb to weakness?<br/>"Cast thy burden on the Lord."<br/>',NULL,3581,3581);
INSERT INTO stanza VALUES('E697','5','He will hold thee up from falling;<br/>He will guide thy steps aright;<br/>He will strengthen each endeavor;<br/>He will keep thee by His might.<br/>',NULL,3582,3582);
INSERT INTO stanza VALUES('E698','1','Amid the trials that I meet,<br/>Amid the thorns that pierce my feet,<br/>One thought remains supremely sweet-<br/>Thou thinkest, Lord, of me!<br/>',NULL,3583,3583);
INSERT INTO stanza VALUES('E698','chorus','Thou thinkest, Lord, of me!<br/>Thou thinkest, Lord, of me!<br/>What need I fear when Thou art near,<br/>And thinkest, Lord, of me!<br/>',NULL,3584,3584);
INSERT INTO stanza VALUES('E698','2','The cares of life come thronging fast,<br/>Upon my soul their shadows cast;<br/>Their gloom reminds my heart at last<br/>Thou thinkest, Lord, of me!<br/>',NULL,3585,3585);
INSERT INTO stanza VALUES('E698','3','Let shadows come, let shadows go,<br/>Let life be bright, or dark with woe,<br/>I am content, for this I know<br/>Thou thinkest, Lord, of me!<br/>',NULL,3586,3586);
INSERT INTO stanza VALUES('E699','1','In the hour of trial,<br/>Jesus, plead for me,<br/>Lest by base denial,<br/>I depart from Thee;<br/>When Thou seest me waver,<br/>With a look recall,<br/>Nor for fear or favor<br/>Suffer me to fall.<br/>',NULL,3587,3587);
INSERT INTO stanza VALUES('E699','2','Should Thy mercy send me<br/>Sorrow, toil, and woe;<br/>Or should pain attend me<br/>On my path below;<br/>Grant that I may never<br/>Fail Thy hand to see;<br/>Grant that I may ever<br/>Cast my care on Thee.<br/>',NULL,3588,3588);
INSERT INTO stanza VALUES('E699','3','When the last hour cometh,<br/>Fraught with strife and pain,<br/>When Thou, Lord, returneth<br/>To the earth again;<br/>On Thy truth relying<br/>As that hour draws near,<br/>Jesus, take me, waiting,<br/>To Thy presence dear.<br/>',NULL,3589,3589);
INSERT INTO stanza VALUES('E700','1','"Be not anxious for the morrow,"<br/>Jesus said;<br/>Why should we its trials borrow?<br/>Trust instead!<br/>For each hour of need or sorrow,<br/>Grace He gives, and daily bread.<br/>',NULL,3590,3590);
INSERT INTO stanza VALUES('E700','2','Thus our treasure safe investing<br/>In His care,<br/>Kept in His pavilion resting,<br/>May we dare<br/>Still to trust, thru faith''s deep testing,<br/>Sure, God will His ways declare.<br/>',NULL,3591,3591);
INSERT INTO stanza VALUES('E701','1','All the way my Savior leads me;<br/>What have I to ask beside?<br/>Can I doubt His tender mercy,<br/>Who through life has been my Guide?<br/>Heav''nly peace, divinest comfort,<br/>Here by faith in Him to dwell!<br/>For I know, whate''er befall me,<br/>Jesus doeth all things well.<br/>',NULL,3592,3592);
INSERT INTO stanza VALUES('E701','2','?All the way my Savior leads me,<br/>Cheers each winding path I tread,<br/>Gives me grace for every trial,<br/>Feeds me with the living bread.<br/>Though my weary steps may falter,<br/>And my soul athirst may be,<br/>Gushing from the Rock before me,<br/>Lo! A spring of joy I see,<br/>Gushing from the Rock before me,<br/>Lo! A spring of joy I see,<br/>',NULL,3593,3593);
INSERT INTO stanza VALUES('E701','3','All the way my Savior leads me;<br/>Oh, the fullness of His grace!<br/>Perfect rest to me is promised<br/>In my Father''s blest embrace.<br/>When my spirit, clothed immortal,<br/>Wings its flight to realm of day,<br/>This my song through endless ages:<br/>Jesus led me all the way,<br/>This my song through endless ages:<br/>Jesus led me all the way.<br/>',NULL,3594,3594);
INSERT INTO stanza VALUES('E702','1','''Tis now in part I know His grace;<br/>I catch sweet glimpses of His face,<br/>But in that better world of His,<br/>I shall behold Him as He is.<br/>',NULL,3595,3595);
INSERT INTO stanza VALUES('E702','chorus','Then shall I know as I am known,<br/>And sing His praise before the throne;<br/>Then shall I know as I am known,<br/>And sing His praise before the throne.<br/>',NULL,3596,3596);
INSERT INTO stanza VALUES('E702','2','''Tis now in part I know His love;<br/>Bright sunbeams shine from skies above;<br/>But glories more exceeding far,<br/>Shall rise beyond life''s evening star.<br/>',NULL,3597,3597);
INSERT INTO stanza VALUES('E702','3','''Tis now in part I understand<br/>The leadings of my Father''s hand;<br/>But I shall own His ways were right,<br/>When welcomed to His presence bright.<br/>',NULL,3598,3598);
INSERT INTO stanza VALUES('E702','4','''Tis now in part, but O how sweet<br/>To rest by faith at His dear feet;<br/>Though now we see as through a glass,<br/>The veil will lift, the shadows pass.<br/>',NULL,3599,3599);
INSERT INTO stanza VALUES('E703','1','Precious promise God doth give thee,<br/>Thou, the weary passerby,<br/>On the way from earth to glory:<br/>"I will guide thee with Mine eye."<br/>',NULL,3600,3600);
INSERT INTO stanza VALUES('E703','chorus','I will guide thee, I will guide thee,<br/>I will guide thee with Mine eye;<br/>On the way from earth to glory,<br/>I will guide thee with Mine eye.<br/>',NULL,3601,3601);
INSERT INTO stanza VALUES('E703','2','When temptations fierce assail thee,<br/>When thy trusted helpers fly,<br/>Let this promise ring within thee,<br/>"I will guide thee with Mine eye."<br/>',NULL,3602,3602);
INSERT INTO stanza VALUES('E703','3','When thy secret hopes have perished<br/>In the grave of years gone by,<br/>Let this promise still be cherished,<br/>"I will guide thee with Mine eye."<br/>',NULL,3603,3603);
INSERT INTO stanza VALUES('E703','4','When the shades of life are falling,<br/>And the hour has come to die,<br/>Hear thy faithful Pilot calling,<br/>"I will guide thee with Mine eye."<br/>',NULL,3604,3604);
INSERT INTO stanza VALUES('E704','1','Though troubles assail,<br/>And dangers affright;<br/>Though friends should all fail,<br/>And foes all unite,<br/>Yet one thing secures us,<br/>Whatever betide:<br/>The Scripture assures us,<br/>"The Lord will provide."<br/>',NULL,3605,3605);
INSERT INTO stanza VALUES('E704','2','The birds, without barn<br/>Or storehouse, are fed;<br/>From them let us learn<br/>To trust for our bread;<br/>His saints what is fitting<br/>Shall ne''er be denied,<br/>So long as ''tis written,<br/>"The Lord will provide."<br/>',NULL,3606,3606);
INSERT INTO stanza VALUES('E704','3','His call we obey,<br/>Like Abram of old,<br/>Not knowing our way,<br/>But faith makes us bold;<br/>For though we are strangers,<br/>We have a good Guide;<br/>And trust in all dangers:<br/>"The Lord will provide."<br/>',NULL,3607,3607);
INSERT INTO stanza VALUES('E704','4','When Satan appear<br/>To stop up our path,<br/>And fills us with fears,<br/>We triumph by faith;<br/>He cannot take from us,<br/>Though of he has tried,<br/>The heart-cheering promise,<br/>"The Lord will provide."<br/>',NULL,3608,3608);
INSERT INTO stanza VALUES('E704','5','He tells us we''re weak,<br/>Our hope is in vain;<br/>The good that we seek<br/>We ne''er shall obtain;<br/>But when such suggestions<br/>Our faith thus have tried,<br/>This answers all questions,<br/>"The Lord will provide."<br/>',NULL,3609,3609);
INSERT INTO stanza VALUES('E704','6','No strength of our own,<br/>Nor goodness we claim;<br/>Our trust is all thrown<br/>On Jesus'' dear name.<br/>In this our strong tower<br/>For safety we hide;<br/>The Lord is our power,<br/>"The Lord will provide."<br/>',NULL,3610,3610);
INSERT INTO stanza VALUES('E704','7','When life sinks apace,<br/>And death is in view,<br/>The word of His grace<br/>Shall comfort us through;<br/>Not fearing or doubting,<br/>With Christ on our side,<br/>We hope to die shouting,<br/>"The Lord will provide."<br/>',NULL,3611,3611);
INSERT INTO stanza VALUES('E705','1','In some way or other the Lord will provide.<br/>It may not be my way, it may not be thy way;<br/>And yet in His own way, "the Lord will provide."<br/>',NULL,3612,3612);
INSERT INTO stanza VALUES('E705','chorus','Then we''ll trust in the Lord, and He will provide;<br/>Yes, we''ll trust in the Lord, and He will provide.<br/>',NULL,3613,3613);
INSERT INTO stanza VALUES('E705','2','At some time or other the Lord will provide:<br/>It may not be my time, it may not be thy time;<br/>And yet in His own time, "the Lord will provide."<br/>',NULL,3614,3614);
INSERT INTO stanza VALUES('E705','3','Despond then no longer; the Lord will provide;<br/>And this be the token-no word He hath spoken<br/>Was ever yet broken: "The Lord will provide."<br/>',NULL,3615,3615);
INSERT INTO stanza VALUES('E705','4','March on then right boldly: the sea shall divide;<br/>The pathway made glorious, with shoutings victorious,<br/>We''ll join in the chorus, "The Lord will provide."<br/>',NULL,3616,3616);
INSERT INTO stanza VALUES('E706','1','Sometimes a light surprises<br/>The Christian while he sings;<br/>It is the Lord who rises<br/>With healing in His wings;<br/>When comforts are declining,<br/>He grants the soul again<br/>A season of clear shining,<br/>To cheer it after rain.<br/>',NULL,3617,3617);
INSERT INTO stanza VALUES('E706','2','In holy contemplation<br/>We sweetly then pursue<br/>The theme of God''s salvation,<br/>And find it ever new;<br/>Set free from present sorrow,<br/>We cheerfully can say-<br/>E''en let the unknown morrow<br/>Bring with it what it may.<br/>',NULL,3618,3618);
INSERT INTO stanza VALUES('E706','3','It can bring with it nothing,<br/>But He will bear us through;<br/>Who gives the lilies clothing,<br/>Will clothe His people too:<br/>Beneath the spreading heavens<br/>No creature but is fed;<br/>And He, who feeds the ravens,<br/>Will give His children bread.<br/>',NULL,3619,3619);
INSERT INTO stanza VALUES('E706','4','Though vine nor fig tree neither<br/>Their wonted fruit shall bear;<br/>Though all the fields should wither<br/>Nor flocks nor herds be there;<br/>Yet God the same abiding,<br/>His praise shall tune my voice,<br/>For, while in Him confiding,<br/>I cannot but rejoice.<br/>',NULL,3620,3620);
INSERT INTO stanza VALUES('E707','1','When upon life''s billows you are tempest tossed,<br/>When you are discouraged, thinking all is lost,<br/>Count your many blessings name them one by one,<br/>And it will surprise you what the Lord hath done.<br/>',NULL,3621,3621);
INSERT INTO stanza VALUES('E707','chorus','Count your blessings, name them one by one;<br/>Count your blessings, see what God hath done;<br/>Count your blessings, name them one by one,<br/>And it will surprise you what the Lord hath done.<br/>',NULL,3622,3622);
INSERT INTO stanza VALUES('E707','2','Are you ever burdened with a load of care?<br/>Does the cross seem heavy you are called to bear?<br/>Count your blessings, every doubt will fly,<br/>And you will be singing as the days go by.<br/>',NULL,3623,3623);
INSERT INTO stanza VALUES('E707','3','When you look at others with their lands and gold,<br/>Think that Christ has promised you His wealth untold.<br/>Count your blessings, money cannot buy<br/>Your reward in heaven, nor your Lord on high.<br/>',NULL,3624,3624);
INSERT INTO stanza VALUES('E707','4','So amid the conflict, whether great or small,<br/>Do not be discouraged, God is over all;<br/>Count your many blessings, angels will attend,<br/>Help and comfort give you to your journey''s end.<br/>',NULL,3625,3625);
INSERT INTO stanza VALUES('E708','1','Fresh as the dew of the morning,<br/>Bringing a sweet rest unheard,<br/>Christ, in the gentle anointing,<br/>Whispers His comforting word:<br/>Stand till the trial is over,<br/>Stand till the tempest is gone,<br/>Stand for the glory of Jesus,<br/>Stand till the kingdom is won.<br/>',NULL,3626,3626);
INSERT INTO stanza VALUES('E708','chorus','Lord of all hope, O how<br/>Sweet is Thy voice,<br/>Making my heart in Thy<br/>presence rejoice.<br/>',NULL,3627,3627);
INSERT INTO stanza VALUES('E708','2','If in the test of my trouble,<br/>Faint be my spirit and heart,<br/>Faint, with the star of hope glimm''ring,<br/>Shall all be taken apart,<br/>May then Thy faith with Thy life-pow''r<br/>Over me hold its full sway<br/>That all Thy riches of glory<br/>Now I may share and for aye.<br/>',NULL,3628,3628);
INSERT INTO stanza VALUES('E708','3','Lord, as the morning sun dawning,<br/>Chase all my darkness away,<br/>And with Thy kind wings of healing<br/>Turn all my night into day,<br/>Come Thou, O come, Lord of comfort,<br/>Come to my sad, weary heart,<br/>Come, O Thou blest hope of glory,<br/>Never, O never depart.<br/>',NULL,3629,3629);
INSERT INTO stanza VALUES('E709','1','Jesus triumphant when the storm-clouds break,<br/>And the loud thunder bids the soul awake;<br/>When biting blasts lay earthly projects low,<br/>And one by one the fondest treasures go.<br/>',NULL,3630,3630);
INSERT INTO stanza VALUES('E709','2','Jesus triumphant, through the fleeting years;<br/>Jesus triumphant, spite of blinding tears;<br/>High over all, to hear Thy loving voice,<br/>Which bids the heart look upward and rejoice.<br/>',NULL,3631,3631);
INSERT INTO stanza VALUES('E709','3','Jesus triumphant, when in work for thee,<br/>Sad and disheartened, no results we see;<br/>When gathered force of evil seems to win,<br/>And work for Christ seems lost in work of sin.<br/>',NULL,3632,3632);
INSERT INTO stanza VALUES('E709','4','Jesus triumphant all along the line;<br/>Triumphant Savior, all Thy triumph mine;<br/>For since I am a partner in Thy love,<br/>My life on earth is lived through Thee above.<br/>',NULL,3633,3633);
INSERT INTO stanza VALUES('E709','5','Jesus triumphant when the spirit wings<br/>Onward and upward to the King of kings;<br/>And through the last great triumph of Thy grace<br/>Triumphant saints shall see Thee face to face.<br/>',NULL,3634,3634);
INSERT INTO stanza VALUES('E710','1','The days may grow darker,<br/>The nights more weary grow,<br/>And Jesus may still tarry,<br/>But this one thing I know:<br/>The Lord will still grow dearer,<br/>And fellowship will be<br/>The closer and the sweeter<br/>Between my Lord and me.<br/>',NULL,3635,3635);
INSERT INTO stanza VALUES('E710','2','''Tis our dear Lord we wait for,<br/>Our Hope! Our Joy! Our Friend!<br/>Himself we long to welcome,<br/>And just beyond the bend<br/>Hidden, perchance to meet us<br/>Before the day is done,<br/>The waiting will be over<br/>And rest will have begun.<br/>',NULL,3636,3636);
INSERT INTO stanza VALUES('E711','1','I know not what awaits me,<br/>God kindly veils my eyes,<br/>And o''er each step of my onward way<br/>He make new scenes to rise;<br/>And every joy He sends me comes<br/>A sweet and glad surprise.<br/>',NULL,3637,3637);
INSERT INTO stanza VALUES('E711','chorus','Where He may lead I''ll follow,<br/>My trust in Him repose;<br/>And every hour in perfect peace,<br/>I''ll sing, "He knows, He knows";<br/>And every hour in perfect peace,<br/>I''ll sing, "He knows, He knows."<br/>',NULL,3638,3638);
INSERT INTO stanza VALUES('E711','2','One step I see before me,<br/>''Tis all I need to see,<br/>The light of heaven more brightly shines<br/>When earth''s illusions flee;<br/>And sweetly through the silence comes,<br/>His loving, "Trust in Me!"<br/>',NULL,3639,3639);
INSERT INTO stanza VALUES('E711','3','Oh, blissful lack of wisdom,<br/>''Tis blessed not to know;<br/>He holds me with His own right hand,<br/>And will not let me go,<br/>And lulls my troubled soul to rest<br/>In Him who loves me so.<br/>',NULL,3640,3640);
INSERT INTO stanza VALUES('E711','4','So on I go not knowing;<br/>I would not if might;<br/>I''d rather walk in the dark with God<br/>Than go alone in the light;<br/>I''d rather walk by faith with Him<br/>Than go alone by sight.<br/>',NULL,3641,3641);
INSERT INTO stanza VALUES('E712','1','Be still my heart! These anxious cares<br/>To thee are burdens, thorns and snares;<br/>They cast dishonor on the Lord,<br/>And contradict His gracious word.<br/>',NULL,3642,3642);
INSERT INTO stanza VALUES('E712','2','Brought safely by His hand thus far,<br/>Why wilt thou now give place to fear?<br/>How canst thou want if He provide,<br/>Or lose thy way with such a Guide?<br/>',NULL,3643,3643);
INSERT INTO stanza VALUES('E712','3','When first before His mercy-seat<br/>Thou didst to Him thine all commit;<br/>He gave thee warrant from that hour<br/>To trust His wisdom, love, and power.<br/>',NULL,3644,3644);
INSERT INTO stanza VALUES('E712','4','Did ever trouble yet befall,<br/>And He refuse to hear thy call?<br/>And has He not His promise passed,<br/>That thou shalt overcome at last?<br/>',NULL,3645,3645);
INSERT INTO stanza VALUES('E712','5','He who has helped me hitherto<br/>Will help me all my journey through,<br/>And give me daily cause to raise<br/>New Ebenezers to His praise.<br/>',NULL,3646,3646);
INSERT INTO stanza VALUES('E712','5','Though rough and thorny be the road,<br/>It leads thee on, apace, to God;<br/>Then count thy present trials small,<br/>For God will make amends for all.<br/>',NULL,3647,3647);
INSERT INTO stanza VALUES('E713','1','Day by day, and with each passing moment,<br/>Strength I find to meet my trials here;<br/>Trusting in my Father''s wise bestowment,<br/>I''ve no cause for worry or for fear.<br/>He, whose heart is kind beyond all measure,<br/>Gives unto each day what He deems best,<br/>Lovingly its part of pain and pleasure,<br/>Mingling toil with peace and rest.<br/>',NULL,3648,3648);
INSERT INTO stanza VALUES('E713','2','Every day the Lord Himself is near me,<br/>With a special mercy for each hour;<br/>All my cares He fain would bear and cheer me,<br/>He whose name is Counselor and Pow''r.<br/>The protection of His child and treasure<br/>Is a charge that on Himself He laid;<br/>"As thy days, thy strength shall be in measure,"<br/>This the pledge to me He made.<br/>',NULL,3649,3649);
INSERT INTO stanza VALUES('E713','3','Help me then, in every tribulation,<br/>So to trust Thy promises, O Lord,<br/>That I lose not faith''s sweet consolation,<br/>Offered me within Thy holy Word.<br/>Help me, Lord, when toil and trouble meeting,<br/>E''er to take, as from a father''s hand,<br/>One by one, the days, the moments fleeting,<br/>Till with Christ the Lord I stand.<br/>',NULL,3650,3650);
INSERT INTO stanza VALUES('E714','1','Through all the changing scenes of life,<br/>In trouble and in joy,<br/>The praises of my God shall still<br/>My heart and tongue employ.<br/>',NULL,3651,3651);
INSERT INTO stanza VALUES('E714','2','Oh, magnify the Lord with me,<br/>With me exalt His name;<br/>When in distress to Him I called,<br/>He to my rescue came.<br/>',NULL,3652,3652);
INSERT INTO stanza VALUES('E714','3','The hosts of God encamp around<br/>The dwellings of the just;<br/>Deliverance He affords to all<br/>Who on His succor trust.<br/>',NULL,3653,3653);
INSERT INTO stanza VALUES('E714','4','Oh, make but trial of His love,<br/>Experience will decide<br/>How blest they are, and only they,<br/>Who in His truth confide.<br/>',NULL,3654,3654);
INSERT INTO stanza VALUES('E714','5','Fear Him, ye saints, and you will then<br/>Have nothing else to fear;<br/>Make you His service your delight,<br/>Your wants shall be His care.<br/>',NULL,3655,3655);
INSERT INTO stanza VALUES('E715','1','Not now, but in the coming years,<br/>It may be when with Christ we stand,<br/>We''ll read the meaning of our tears,<br/>And there, sometime, we''ll understand.<br/>',NULL,3656,3656);
INSERT INTO stanza VALUES('E715','chorus','Then trust in God through all thy days;<br/>Fear not, for He doth hold thy hand;<br/>Though dark thy way, still sing and praise,<br/>Sometime, sometime, we''ll understand.<br/>',NULL,3657,3657);
INSERT INTO stanza VALUES('E715','2','We''ll catch the broken thread again,<br/>And finish what we here began;<br/>God will the mysteries explain,<br/>And then, ah, then, we''ll understand.<br/>',NULL,3658,3658);
INSERT INTO stanza VALUES('E715','3','We''ll know why clouds instead of sun<br/>Were over many a cherished plan;<br/>Why song has ceased when scarce begun;<br/>''Tis then, sometime, we''ll understand.<br/>',NULL,3659,3659);
INSERT INTO stanza VALUES('E715','4','Why what we long for most of all,<br/>Eludes so oft our eager hand;<br/>Why hopes are crushed and castles fall,<br/>Till then, sometime, we''ll understand.<br/>',NULL,3660,3660);
INSERT INTO stanza VALUES('E715','5','God knows the way, He holds the key,<br/>He guides us with unerring hand;<br/>Sometime with tearless eyes we''ll see;<br/>Yes, then, ''tis then, we''ll understand.<br/>',NULL,3661,3661);
INSERT INTO stanza VALUES('E716','1','Begone, unbelief,<br/>My Savior is near,<br/>And for my relief<br/>Will surely appear;<br/>By prayer let me wrestle,<br/>And He will perform;<br/>With Christ in the vessel,<br/>I smile at the storm.<br/>',NULL,3662,3662);
INSERT INTO stanza VALUES('E716','2','Though dark be my way,<br/>Since He is my Guide,<br/>''Tis mine to obey,<br/>''Tis His to provide;<br/>Though cisterns be broken,<br/>And creatures all fail,<br/>The word He hath spoken<br/>Shall surely prevail.<br/>',NULL,3663,3663);
INSERT INTO stanza VALUES('E716','3','His love, in time past,<br/>Forbids me to think<br/>He''ll leave me at last<br/>In trouble to sink:<br/>Each sweet Ebenzer<br/>I have in review<br/>Confirms His good pleasure<br/>To help me quite through.<br/>',NULL,3664,3664);
INSERT INTO stanza VALUES('E716','4','Why should I complain<br/>Of want or distress,<br/>Temptation or pain?<br/>He told me no less;<br/>The heirs of salvation,<br/>I know from His Word,<br/>Through much tribulation<br/>Must follow their Lord.<br/>',NULL,3665,3665);
INSERT INTO stanza VALUES('E716','5','How bitter that cup<br/>No heart can conceive,<br/>Which He drank quite up,<br/>That sinners might live!<br/>His way was much rougher<br/>And darker than mine;<br/>Did Christ, my Lord, suffer,<br/>And shall I repine?<br/>',NULL,3666,3666);
INSERT INTO stanza VALUES('E716','6','Since all that I meet<br/>Shall work for my good,<br/>The bitter is sweet,<br/>The medicine, food;<br/>Though painful at present,<br/>''Twill cease before long,<br/>And then, oh, how pleasant<br/>The conqueror''s song!<br/>',NULL,3667,3667);
INSERT INTO stanza VALUES('E717','1','O let us rejoice in the Lord evermore,<br/>Though all things around us be trying,<br/>Though floods of affliction like sea<br/>billows roar,<br/>It''s better to sing than be sighing.<br/>',NULL,3668,3668);
INSERT INTO stanza VALUES('E717','chorus','Then rejoice evermore, rejoice evermore,<br/>It is better to sing than be sighing:<br/>It is better to live than be dying;<br/>So let us rejoice evermore.<br/>',NULL,3669,3669);
INSERT INTO stanza VALUES('E717','2','O let us rejoice in the Lord evermore,<br/>When the darts of the tempter are flying,<br/>For Satan still dreads, as he oft did of yore,<br/>Our singing much more than our sighing.<br/>',NULL,3670,3670);
INSERT INTO stanza VALUES('E717','3','O let us rejoice in the Lord evermore,<br/>When sickness upon us is stealing,<br/>No cordial like gladness our strength can restore,<br/>For joy is the fountain of healing.<br/>',NULL,3671,3671);
INSERT INTO stanza VALUES('E718','1','Peace, perfect peace, in this dark world of sin?<br/>The blood of Jesus whispers peace within.<br/>',NULL,3672,3672);
INSERT INTO stanza VALUES('E718','2','Peace, perfect peace, by thronging duties pressed?<br/>To do the will of Jesus-this is rest.<br/>',NULL,3673,3673);
INSERT INTO stanza VALUES('E718','3','Peace, perfect peace, with sorrows surging round?<br/>On Jesus'' bosom naught but calm is found.<br/>',NULL,3674,3674);
INSERT INTO stanza VALUES('E718','4','Peace, perfect peace, with loved ones far away?<br/>In Jesus'' keeping we are safe, and they.<br/>',NULL,3675,3675);
INSERT INTO stanza VALUES('E718','5','Peace, perfect peace, our future all unknown?<br/>Jesus we know, and He is on the throne.<br/>',NULL,3676,3676);
INSERT INTO stanza VALUES('E719','1','Like a river, glorious<br/>Is God''s perfect peace,<br/>Over all victorious<br/>In its bright increase;<br/>Perfect, yet it floweth<br/>Fuller every day,<br/>Perfect, yet it groweth<br/>Deeper all the way.<br/>',NULL,3677,3677);
INSERT INTO stanza VALUES('E719','chorus','Stayed upon Christ Jesus,<br/>Hearts are fully blest;<br/>Finding, as He promised,<br/>Perfect peace and rest.<br/>',NULL,3678,3678);
INSERT INTO stanza VALUES('E719','2','Hidden in the hollow<br/>Of His blessed hand,<br/>Never foe can follow,<br/>Never traitor stand;<br/>Not a surge of worry,<br/>Not a shade of care,<br/>Not a blast of hurry<br/>Touch the spirit there.<br/>',NULL,3679,3679);
INSERT INTO stanza VALUES('E719','3','Every joy or trial<br/>Falleth from above,<br/>Traced upon our dial<br/>By the Sun of Love.<br/>We must trust Him fully<br/>All for us to do;<br/>They who trust Him wholly<br/>Find Him wholly true.<br/>',NULL,3680,3680);
INSERT INTO stanza VALUES('E720','1','God hath not promised skies always blue,<br/>Flower-strewn pathways all our lives through;<br/>God hath not promised sun without rain,<br/>Joy without sorrow, peace without pain.<br/>',NULL,3681,3681);
INSERT INTO stanza VALUES('E720','chorus','But God hath promised strength for the day,<br/>Rest for the labor, light for the way,<br/>Grace for the trials, help from above,<br/>Unfailing sympathy, undying love.<br/>',NULL,3682,3682);
INSERT INTO stanza VALUES('E720','2','God hath not promised we shall not know<br/>Toil and temptation, trouble and woe;<br/>He hath not told us we shall not bear<br/>Many a burden, many a care.<br/>',NULL,3683,3683);
INSERT INTO stanza VALUES('E720','3','God hath not promised smooth roads and wide,<br/>Swift, easy travel, needing not guide;<br/>Never a mountain, rocky and steep,<br/>Never a river, turbid and deep.<br/>',NULL,3684,3684);
INSERT INTO stanza VALUES('E721','1','I''ll sing of the wonderful promise<br/>That Jesus has given to me;<br/>"My strength is made perfect in weakness,<br/>My grace is sufficient for thee."<br/>And lest my poor heart should forget it,<br/>Or ever forgetful should be,<br/>He still keeps repeating the promise,<br/>My grace is sufficient for thee.<br/>',NULL,3685,3685);
INSERT INTO stanza VALUES('E721','chorus','Yes, over and over and over,<br/>My Savior keeps saying to me;<br/>My strength is made perfect in weakness,<br/>My grace is sufficient for thee.<br/>',NULL,3686,3686);
INSERT INTO stanza VALUES('E721','2','His grace is sufficient to save me,<br/>And cleanse me from guilt and from sin;<br/>Sufficient to sanctify wholly,<br/>And give me His Spirit within.<br/>His grace is sufficient for trials,<br/>No matter how hard they may be,<br/>This promise stands over against them,<br/>My grace is sufficient for thee.<br/>',NULL,3687,3687);
INSERT INTO stanza VALUES('E721','3','His grace is sufficient for sickness,<br/>Sustaining and making me whole;<br/>His grace is sufficient when sorrows<br/>Like billows roll over the soul.<br/>His grace is sufficient for service,<br/>It sets us from selfishness free,<br/>And send us to tell the tried ones,<br/>His grace is sufficient for thee.<br/>',NULL,3688,3688);
INSERT INTO stanza VALUES('E721','4','His grace is sufficient to live by,<br/>And should we be summoned to die<br/>''Twill light up the valley of shadows,<br/>And bear us away to Him nigh.<br/>Or when we shall stand in His vict''ry,<br/>And Christ in His glory shall see,<br/>We''ll fall at His footstool confessing,<br/>Thy grace was sufficient for me.<br/>',NULL,3689,3689);
INSERT INTO stanza VALUES('E721','5','It is not our grace that''s sufficient,<br/>But His grace, it ever must be:<br/>Our graces are transient and changing;<br/>His grace is unfailing as He.<br/>And so I am ever repeating<br/>His wonderful promise to me,<br/>My strength is made perfect in weakness,<br/>My grace is sufficient for thee.<br/>',NULL,3690,3690);
INSERT INTO stanza VALUES('E722','1','The cross that He gave may be heavy,<br/>But it ne''er outweighs His grace;<br/>The storm that I feared may surround me,<br/>But it ne''er excludes His face.<br/>',NULL,3691,3691);
INSERT INTO stanza VALUES('E722','chorus','The cross is not greater than His grace,<br/>The storm cannot hide His blessed face;<br/>I am satisfied to know<br/>That with Jesus here below,<br/>I can conquer every foe.<br/>',NULL,3692,3692);
INSERT INTO stanza VALUES('E722','2','The thorns in my path are not sharper<br/>Than composed His crown for me;<br/>The cup that I drink not more bitter<br/>Than He drank at Gethsemane.<br/>',NULL,3693,3693);
INSERT INTO stanza VALUES('E722','3','The light of His love shineth brighter,<br/>As it falls on paths of woe;<br/>The toil of my work groweth lighter,<br/>As I stoop to raise the low.<br/>',NULL,3694,3694);
INSERT INTO stanza VALUES('E722','4','His will I have joy in fulfilling,<br/>As I''m walking in His sight;<br/>My trials more blessings are bringing,<br/>Christ in them is my delight.<br/>',NULL,3695,3695);
INSERT INTO stanza VALUES('E723','1','He giveth more grace when the burdens grow greater,<br/>He sendeth more strength when the labors increase,<br/>To added affliction He addeth His mercy,<br/>To multiplied trials, His multiplied peace.<br/>',NULL,3696,3696);
INSERT INTO stanza VALUES('E723','2','When we have exhausted our store of endurance,<br/>When our strength has failed ere the day is half-done,<br/>When we reach the end of our hoarded resources,<br/>Our Father''s full giving is only begun.<br/>',NULL,3697,3697);
INSERT INTO stanza VALUES('E723','3','His love has no limit, His grace has no measure,<br/>His power no boundary known unto men,<br/>For out of His infinite riches in Jesus,<br/>He giveth and giveth and giveth again.<br/>',NULL,3698,3698);
INSERT INTO stanza VALUES('E724','1','A little bird I am,<br/>Shut from the fields of air,<br/>And in my cage I sit and sing<br/>To Him who place me there;<br/>Well pleased a prisoner to be,<br/>Because, my God, it pleaseth Thee.<br/>',NULL,3699,3699);
INSERT INTO stanza VALUES('E724','2','Nought have I else to do,<br/>I sing the whole day long;<br/>And He whom most I love to please<br/>Doth listen to my song;<br/>He caught and bound my wandering wing;<br/>But still He bends to hear me sing.<br/>',NULL,3700,3700);
INSERT INTO stanza VALUES('E724','3','Thou hast an ear to hear<br/>A heart to love and bless;<br/>And though my notes were e''er so rude,<br/>Thou wouldst not hear the less;<br/>Because Thou knowest as they fall,<br/>That love, sweet love, inspires them all.<br/>',NULL,3701,3701);
INSERT INTO stanza VALUES('E724','4','My cage confines me round;<br/>Abroad I cannot fly;<br/>But though my wing is closely bound,<br/>My heart''s at liberty;<br/>For prison walls cannot control<br/>The flight, the freedom of the soul.<br/>',NULL,3702,3702);
INSERT INTO stanza VALUES('E724','5','O it is good to soar<br/>These bolts and bars above!<br/>To Him whose purpose I adore,<br/>Whose providence I love;<br/>And in Thy mighty will to find<br/>The joy, the freedom of the mind.<br/>',NULL,3703,3703);
INSERT INTO stanza VALUES('E725','1','Strong are the walls around me,<br/>That hold me all the day;<br/>But they who thus have bound me,<br/>Cannot keep God away:<br/>My very dungeon walls are dear,<br/>Because the God I love is here.<br/>',NULL,3704,3704);
INSERT INTO stanza VALUES('E725','2','They know, who thus oppress me,<br/>''Tis hard to be alone;<br/>But know not One can bless me,<br/>Who comes through bars and stone;<br/>He makes my dungeon''s darkness bright,<br/>And fills my bosom with delight.<br/>',NULL,3705,3705);
INSERT INTO stanza VALUES('E725','3','Thy love, O God, restores me<br/>From sighs and tears to praise;<br/>And deep my soul adores Thee,<br/>Nor thinks of time or place;<br/>I ask no more, in good or ill,<br/>But union with Thy holy will.<br/>',NULL,3706,3706);
INSERT INTO stanza VALUES('E725','4','''Tis that which make me treasure,<br/>''Tis that which brings me gain;<br/>Converting woe to pleasure,<br/>And reaping joy from pain.<br/>Oh, ''tis enough, whate''er befall,<br/>To know that God is All in all.<br/>',NULL,3707,3707);
INSERT INTO stanza VALUES('E726','1','Long plunged in sorrow, I resign<br/>My soul to that dear hand of Thine,<br/>Without reserve or fear;<br/>That hand shall wipe my streaming eyes,<br/>Or into smiles of glad surprise<br/>Transform the falling tear.<br/>',NULL,3708,3708);
INSERT INTO stanza VALUES('E726','2','Adieu! Ye vain delights of earth;<br/>Insipid sports, and childish mirth,<br/>I taste no sweets in you;<br/>Unknown delights are in the cross,<br/>All joy beside to me is dross;<br/>And Jesus thought so too.<br/>',NULL,3709,3709);
INSERT INTO stanza VALUES('E726','3','The Cross! O ravishment and bliss-<br/>How grateful e''en its anguish is;<br/>Its bitterness how sweet!<br/>There every sense, and all the mind,<br/>In all her faculties refined,<br/>Taste happiness complete.<br/>',NULL,3710,3710);
INSERT INTO stanza VALUES('E726','4','Self-love no grace in sorrow sees,<br/>Consults her own peculiar ease:<br/>''Tis all the bliss she knows;<br/>But nobler aims true love employ.<br/>In self-denial is her joy,<br/>In suffering her repose.<br/>',NULL,3711,3711);
INSERT INTO stanza VALUES('E726','5','Thy choice and mine shall be the same,<br/>Inspirer of that holy flame<br/>Which must forever blaze!<br/>To take the cross and follow Thee,<br/>Where love and duty lead, shall be<br/>My portion and my praise.<br/>',NULL,3712,3712);
INSERT INTO stanza VALUES('E727','1','Light after darkness,<br/>Gain after loss,<br/>Strength after weakness,<br/>Crown after cross;<br/>Sweet after bitter,<br/>Hope after fears,<br/>Home after wand''ring,<br/>Praise after tears.<br/>',NULL,3713,3713);
INSERT INTO stanza VALUES('E727','2','Sheaves after sowing,<br/>Sun after rain,<br/>Sight after mystery,<br/>Peace after pain;<br/>Joy after sorrow,<br/>Calm after blast,<br/>Rest after weariness,<br/>Sweet rest at last.<br/>',NULL,3714,3714);
INSERT INTO stanza VALUES('E727','3','Near after distant,<br/>Gleam after gloom,<br/>Love after loneliness,<br/>Life after tomb;<br/>After long agony,<br/>Rapture of bliss,<br/>Right was the pathway,<br/>Leading to this.<br/>',NULL,3715,3715);
INSERT INTO stanza VALUES('E728','1','I have been through the valley of sorrow and weeping,<br/>The valley of trouble and pain;<br/>But the "God of all comfort," the "God of all comfort,"<br/>Was with me to hold and sustain.<br/>',NULL,3716,3716);
INSERT INTO stanza VALUES('E728','2','As the earth needs the clouds and the rain with the sunshine,<br/>Our souls need both sorrow and joy,<br/>So He places us oft in the fire of affliction<br/>The dross from the gold to destroy.<br/>',NULL,3717,3717);
INSERT INTO stanza VALUES('E728','3','When He leads thru the valleys of trouble and sorrow,<br/>His mercy and love there we trace;<br/>For the trials and sorrows He sends us in wisdom<br/>Are part of His lessons in grace.<br/>',NULL,3718,3718);
INSERT INTO stanza VALUES('E728','4','Yet how often we shrink from the purging and pruning,<br/>Forgetting the Husbandman knows<br/>That the deeper and closer the cutting and paring,<br/>The richer the cluster that grows.<br/>',NULL,3719,3719);
INSERT INTO stanza VALUES('E728','5','O how well does He know the afflictions are needed;<br/>He has a wise purpose in view,<br/>And within the dark valley He whispers to comfort,<br/>"Hereafter thou''lt know what I do."<br/>',NULL,3720,3720);
INSERT INTO stanza VALUES('E728','6','As we travel the pathway thru life''s shadowed valleys,<br/>Fresh springs of His love ever rise;<br/>And we learn that our troubles, our sorrows and losses,<br/>Are blessings just sent in disguise.<br/>',NULL,3721,3721);
INSERT INTO stanza VALUES('E728','7','So we''ll follow Him faithfully where''er He leadeth,<br/>The pathway be dreary or bright;<br/>For we''ve proved that our God is the "God of all comfort,"<br/>The God who gives songs in the night.<br/>',NULL,3722,3722);
INSERT INTO stanza VALUES('E729','1','Is it raining, little flower?<br/>Oh, be glad of rain!<br/>Too much sun would wither thee;<br/>Soon ''twill shine again.<br/>Though the sky is black, ''tis true,<br/>Yet behind it shines the blue.<br/>',NULL,3723,3723);
INSERT INTO stanza VALUES('E729','2','Art thou weary, tender heart?<br/>Oh, be glad of pain;<br/>Sweetest things in sorrow grow<br/>As the flow''rs in rain.<br/>God is watching, thou''lt have sun<br/>When the clouds their work have done.<br/>',NULL,3724,3724);
INSERT INTO stanza VALUES('E730','1','Pressed out of measure, pressed beyond all length;<br/>Pressed so intensely, seeming beyond strength;<br/>Pressed in the body, pressed within the soul,<br/>Pressed in the mind till darksome surges roll.<br/>',NULL,3725,3725);
INSERT INTO stanza VALUES('E730','chorus','God is my hope and God is my joy;<br/>He is the resurrection life I enjoy.<br/>',NULL,3726,3726);
INSERT INTO stanza VALUES('E730','2','Pressure by foes, and pressure from our friends;<br/>Pressure on pressure, till life nearly ends;<br/>Pressed into knowing none to help but God,<br/>Pressed into loving both the staff and the rod.<br/>',NULL,3727,3727);
INSERT INTO stanza VALUES('E730','3','Pressed into liberty where nothing clings,<br/>Pressed into faith for hard and hopeless things;<br/>Pressed into life, a life in Christ the Lord,<br/>Pressed into life, the life of Christ outpoured.<br/>',NULL,3728,3728);
INSERT INTO stanza VALUES('E731','1','Why should I fear the darkest hour,<br/>Or tremble at the tempter''s power?<br/>Jesus vouchsafes to be my tower.<br/>',NULL,3729,3729);
INSERT INTO stanza VALUES('E731','2','Though hot the fight, why quit the field?<br/>Why must I either fly or yield,<br/>Since Jesus is my mighty shield?<br/>',NULL,3730,3730);
INSERT INTO stanza VALUES('E731','3','When creature comforts fade and die,<br/>Worldlings may weep, but why should I?<br/>Jesus still lives, and still is nigh.<br/>',NULL,3731,3731);
INSERT INTO stanza VALUES('E731','4','Though all the flocks and herds were dead,<br/>My soul a famine need not dread,<br/>For Jesus is my living bread.<br/>',NULL,3732,3732);
INSERT INTO stanza VALUES('E731','5','I know not what may soon betide,<br/>Or how my wants shall be supplied;<br/>But Jesus knows, and will provide.<br/>',NULL,3733,3733);
INSERT INTO stanza VALUES('E731','6','Though sin would fill me with distress,<br/>The throne of grace I dare address,<br/>For Jesus is my righteousness.<br/>',NULL,3734,3734);
INSERT INTO stanza VALUES('E731','7','Though faint my prayers and cold my love,<br/>My steadfast hope shall not remove,<br/>While Jesus intercedes above.<br/>',NULL,3735,3735);
INSERT INTO stanza VALUES('E731','8','Against me earth and hell combine;<br/>But on my side is power divine;<br/>Jesus is all, and He is mine!<br/>',NULL,3736,3736);
INSERT INTO stanza VALUES('E732','1','My Father is rich in houses and lands,<br/>He holdeth the wealth of the world in His hands!<br/>Of rubies and diamonds, of silver and gold,<br/>His coffers are full, He has riches untold.<br/>',NULL,3737,3737);
INSERT INTO stanza VALUES('E732','chorus','I''m a child of the King,<br/>A child of the King:<br/>With Jesus my Savior,<br/>I''m a child of the King.<br/>',NULL,3738,3738);
INSERT INTO stanza VALUES('E732','2','My Father''s own Son, the Savior of men,<br/>Once wandered on earth as the poorest of them.<br/>But now He is pleading our pardon on high,<br/>That we may be His when He come by and by.<br/>',NULL,3739,3739);
INSERT INTO stanza VALUES('E732','3','I once was an out-cast stranger on earth,<br/>A sinner by choice, and an alien by birth;<br/>But I''ve been adopted, my name''s written down,<br/>An heir of salvation, the kingdom and crown.<br/>',NULL,3740,3740);
INSERT INTO stanza VALUES('E732','4','Though poor on this earth, oh, why should I care?<br/>Since glorious things for me God doth prepare;<br/>Though trials abound, yet, still I may sing:<br/>All glory to God, I''m a child of the King.<br/>',NULL,3741,3741);
INSERT INTO stanza VALUES('E733','1','In Eden''s garden fair we see<br/>That God before two trees placed man,<br/>The trees of life, and knowledge too,<br/>Which for the Lord and Satan stand.<br/>',NULL,3742,3742);
INSERT INTO stanza VALUES('E733','2','The tree of life the center is<br/>Of God''s eternal, perfect plan,<br/>Denoting God in Christ as life<br/>To be received as all by man.<br/>',NULL,3743,3743);
INSERT INTO stanza VALUES('E733','3','The tree of knowledge standing there,<br/>Bespeaks a sure and warning voice:<br/>Outside of God there is a source<br/>Of death to all who make this choice.<br/>',NULL,3744,3744);
INSERT INTO stanza VALUES('E733','4','If man would eat the tree of life,<br/>Then God as life he will receive,<br/>And be transformed to precious stones,<br/>God''s will and purpose to achieve.<br/>',NULL,3745,3745);
INSERT INTO stanza VALUES('E733','5','If man the tree of knowledge takes,<br/>Then Satan enters into man<br/>As sin, which brings him into death,<br/>That he may not fulfill God''s plan.<br/>',NULL,3746,3746);
INSERT INTO stanza VALUES('E733','6','This signifies that only God<br/>Is our full source of life and breath;<br/>To touch ought else is but to touch<br/>The source of knowledge and of death.<br/>',NULL,3747,3747);
INSERT INTO stanza VALUES('E733','7','For knowledge only bringeth death,<br/>Though evil or though good it seem;<br/>For any thing apart from God,<br/>Is but the fruit of Satan''s scheme.<br/>',NULL,3748,3748);
INSERT INTO stanza VALUES('E733','8','Not only evil, but the good<br/>Is contradictory to Christ;<br/>Not only knowledge of the bad,<br/>But even good is versus Christ.<br/>',NULL,3749,3749);
INSERT INTO stanza VALUES('E733','9','Lord, teach us only Thee to touch,<br/>That with Thy life we filled may be,<br/>And not to touch the good or bad,<br/>Or anything apart from Thee.<br/>',NULL,3750,3750);
INSERT INTO stanza VALUES('E734','1','The law of God is holy, good,<br/>To practice good it doth command;<br/>Its purpose is to clearly show<br/>That we cannot meet God''s demand.<br/>',NULL,3751,3751);
INSERT INTO stanza VALUES('E734','2','Yet in our mind there is a law<br/>Which always tries the good to do;<br/>But in our members is a law<br/>Which always doth this law subdue.<br/>',NULL,3752,3752);
INSERT INTO stanza VALUES('E734','3','The law within our mind is good,<br/>''Tis of our human life obtained<br/>At our creation from the Lord,<br/>That good behavior be maintained.<br/>',NULL,3753,3753);
INSERT INTO stanza VALUES('E734','4','The law within our members is<br/>The evil of satanic life;<br/>Into our members at the fall<br/>It came thru Satan''s subtle strife.<br/>',NULL,3754,3754);
INSERT INTO stanza VALUES('E734','5','This evil law of Satan is<br/>The law of sin, in us its seat;<br/>''Tis stronger than the law of good<br/>And always brings it to defeat.<br/>',NULL,3755,3755);
INSERT INTO stanza VALUES('E734','6','But in our spirit is a law,<br/>Which is the Spirit''s law of life;<br/>''Tis of the very life of God<br/>Which we from our rebirth derive.<br/>',NULL,3756,3756);
INSERT INTO stanza VALUES('E734','7','This law divine the strongest is,<br/>Transcending all the others o''er;<br/>From sin''s law freeing, it fulfills<br/>The full requirement of God''s law.<br/>',NULL,3757,3757);
INSERT INTO stanza VALUES('E734','8','We then must always set our mind<br/>Upon the spirit deep within,<br/>And not upon the things of flesh,<br/>The body ruined by the sin.<br/>',NULL,3758,3758);
INSERT INTO stanza VALUES('E734','9','To set the mind upon the flesh<br/>Is sin and death and darkest night;<br/>The mind upon the spirit set<br/>Is life and peace and full of light.<br/>',NULL,3759,3759);
INSERT INTO stanza VALUES('E734','10','This is the way of true release!<br/>This is the way of victory!<br/>Lord, may we in the spirit live,<br/>And by the Spirit walk with Thee.<br/>',NULL,3760,3760);
INSERT INTO stanza VALUES('E735','1','The law of letters God defines,<br/>It is His testimony true;<br/>It shows how loving, holy, just,<br/>Is God, with whom we have to do.<br/>',NULL,3761,3761);
INSERT INTO stanza VALUES('E735','2','According to His nature shown<br/>God''s law requires that we must live,<br/>That He our souls may justify<br/>And unto us His blessing give.<br/>',NULL,3762,3762);
INSERT INTO stanza VALUES('E735','3','The law can never give us life,<br/>Nor any strength to us supply,<br/>But doth its full demands exact<br/>And all our weakness show thereby.<br/>',NULL,3763,3763);
INSERT INTO stanza VALUES('E735','4','It was not for God''s final plan,<br/>But of man''s sin was introduced,<br/>That man by breaking it might know<br/>Himself, his sin to him adduced.<br/>',NULL,3764,3764);
INSERT INTO stanza VALUES('E735','5','''Tis by the law all mouths are stopped<br/>And all are shut up under sin;<br/>It brings us to the Christ of God<br/>That God may bless us all in Him.<br/>',NULL,3765,3765);
INSERT INTO stanza VALUES('E735','6','The law is but a type of Christ,<br/>Who God''s full testimony is,<br/>Who fully has expressed His love,<br/>His holiness and righteousness.<br/>',NULL,3766,3766);
INSERT INTO stanza VALUES('E735','7','''Tis Christ, God''s testimony real,<br/>Who doth with life divine supply,<br/>That with the law''s demands we may<br/>Be more than able to comply.<br/>',NULL,3767,3767);
INSERT INTO stanza VALUES('E735','8','God''s living testimony, He;<br/>By whom God''s potent life we share;<br/>Thru Him we''re dead unto the law,<br/>And in His Spirit fruit we bear.<br/>',NULL,3768,3768);
INSERT INTO stanza VALUES('E736','1','In ancient times the law of God<br/>In letter was engraved on stone;<br/>But now it is a law of life,<br/>Which in our heart is written down.<br/>',NULL,3769,3769);
INSERT INTO stanza VALUES('E736','2','The law in letters good demands<br/>And thus our utter weakness shows;<br/>But now the law of life sustains,<br/>And strength for God to please bestows.<br/>',NULL,3770,3770);
INSERT INTO stanza VALUES('E736','3','The law in letters brings to us<br/>God''s knowledge only outwardly;<br/>But now the law of life supplies<br/>A deeper knowledge inwardly.<br/>',NULL,3771,3771);
INSERT INTO stanza VALUES('E736','4','The law in letters can but rule<br/>By dead commandments outwardly;<br/>But now the law of life controls<br/>By living knowledge inwardly.<br/>',NULL,3772,3772);
INSERT INTO stanza VALUES('E736','5','This living law is moving now<br/>In all of our experience,<br/>To regulate us from within<br/>And check us by our inner sense.<br/>',NULL,3773,3773);
INSERT INTO stanza VALUES('E736','6','How deep its regulation is<br/>Within the inmost part of us,<br/>A living consciousness to give,<br/>And God Himself impart to us.<br/>',NULL,3774,3774);
INSERT INTO stanza VALUES('E736','7','''Tis by this living law of life<br/>We need not teaching outwardly,<br/>For all God''s living knowledge now<br/>This law will teach us inwardly.<br/>',NULL,3775,3775);
INSERT INTO stanza VALUES('E736','8','Lord, teach us by this law to walk,<br/>Its inner ruling to obey,<br/>That we may of Thyself partake<br/>And know Thee in a living way.<br/>',NULL,3776,3776);
INSERT INTO stanza VALUES('E737','1','Life eternal brings us<br/>Fellowship of life,<br/>Fellowship in Spirit,<br/>Saving us from strife.<br/>',NULL,3777,3777);
INSERT INTO stanza VALUES('E737','2','Life eternal gives us<br/>Fellowship divine;<br/>Thus the Lord as Spirit<br/>May with us combine.<br/>',NULL,3778,3778);
INSERT INTO stanza VALUES('E737','3','It is life in Spirit<br/>Brings this fellowship;<br/>Fellowship in Spirit<br/>Doth with grace equip.<br/>',NULL,3779,3779);
INSERT INTO stanza VALUES('E737','4','We, by life''s enabling,<br/>Fellowship aright;<br/>Fellowship in Spirit<br/>Brings us into light.<br/>',NULL,3780,3780);
INSERT INTO stanza VALUES('E737','5','By the outward cleansing,<br/>Fellowship we keep;<br/>Inwardly anointed,<br/>Fellowship we reap.<br/>',NULL,3781,3781);
INSERT INTO stanza VALUES('E737','6','Fellowship is deepened<br/>Thru the cross of death;<br/>Fellowship is lifted<br/>By the Spirit''s breath.<br/>',NULL,3782,3782);
INSERT INTO stanza VALUES('E737','7','Fellowship will free us<br/>From our sinful self;<br/>Fellowship will bring us<br/>Into God Himself.<br/>',NULL,3783,3783);
INSERT INTO stanza VALUES('E738','1','There is a certain sense of life<br/>With life of every kind;<br/>And in th'' eternal life in us<br/>It is a sense divine.<br/>',NULL,3784,3784);
INSERT INTO stanza VALUES('E738','2','The higher any life may be,<br/>The better is its sense;<br/>The life divine the highest is<br/>And has the highest sense.<br/>',NULL,3785,3785);
INSERT INTO stanza VALUES('E738','3','It is the sense of life in us,<br/>It is the sense of God;<br/>''Tis in our spirit made alive,<br/>And more than sense of good.<br/>',NULL,3786,3786);
INSERT INTO stanza VALUES('E738','4','It is the inner sense in us,<br/>The inmost consciousness,<br/>Discerning matters inwardly,<br/>God''s will to thus express.<br/>',NULL,3787,3787);
INSERT INTO stanza VALUES('E738','5','''Tis by this sense that God we know,<br/>The sense of inner life;<br/>''Tis pow''rful and spontaneous,<br/>And not of any strife.<br/>',NULL,3788,3788);
INSERT INTO stanza VALUES('E738','6','The greater is our growth in life,<br/>The keener is this sense;<br/>The more we walk and act in life,<br/>The more it is intense.<br/>',NULL,3789,3789);
INSERT INTO stanza VALUES('E738','7','The sense of life when exercised<br/>Will make our spirit bold,<br/>And by this inner sense of God<br/>True fellowship we hold.<br/>',NULL,3790,3790);
INSERT INTO stanza VALUES('E739','1','In those regenerated by the Lord<br/>There is an inner knowledge bountiful;<br/>Thus we the outward teachings do not need,<br/>But God we inwardly may know in full.<br/>',NULL,3791,3791);
INSERT INTO stanza VALUES('E739','2','Eternal life, the highest and the best,<br/>Possesses full divine capacity,<br/>That by this life God''s knowledge we may have<br/>More than by knowledge given outwardly.<br/>',NULL,3792,3792);
INSERT INTO stanza VALUES('E739','3','The law of life is put within our mind<br/>And on our heart ''tis written sovereignly,<br/>Inwardly ruling us that God we know<br/>More than by teachings given outwardly.<br/>',NULL,3793,3793);
INSERT INTO stanza VALUES('E739','4','Holy anointing in our spirit dwells,<br/>Showing the things of God to mind and heart;<br/>By this anointing we God''s knowledge have<br/>More than man''s teachings can to us impart.<br/>',NULL,3794,3794);
INSERT INTO stanza VALUES('E739','5','We have the triune God indwelling us,<br/>Living and acting, working all the time,<br/>That by the inner sense we have of Him<br/>God we may know in magnitude sublime.<br/>',NULL,3795,3795);
INSERT INTO stanza VALUES('E739','6','This inner knowledge obviates the need<br/>Of outward knowledge, human eloquence,<br/>But in the spirit we must ever live<br/>And walk according to the inner sense.<br/>',NULL,3796,3796);
INSERT INTO stanza VALUES('E739','7','The more we live in Christ, the life divine,<br/>And by the inner consciousness behave,<br/>The more we''ll have the inward knowledge true,<br/>And on our heart God will His Son engrave.<br/>',NULL,3797,3797);
INSERT INTO stanza VALUES('E739','8','''Tis by this living inward knowledge gained<br/>That fellowship with God in life we hold;<br/>''Tis by this hidden knowledge thus obtained<br/>God unto us His fulness doth unfold.<br/>',NULL,3798,3798);
INSERT INTO stanza VALUES('E740','1','The principle of incarnation<br/>Is but the blend of God and man,<br/>Both acting in cooperation<br/>To thus fulfill th'' eternal plan.<br/>',NULL,3799,3799);
INSERT INTO stanza VALUES('E740','2','To God, the man in His expression,<br/>And man is of God''s life possessed;<br/>The man is wholly God''s possession,<br/>And God thru man is thus expressed.<br/>',NULL,3800,3800);
INSERT INTO stanza VALUES('E740','3','Redemption is accomplished fully<br/>In man, God''s wisdom thus to show;<br/>Salvation is expounded wholly<br/>By man, that all creation know.<br/>',NULL,3801,3801);
INSERT INTO stanza VALUES('E740','4','God''s service in this dispensation<br/>Requires that man should work with Him;<br/>Thus God and man in close relation<br/>And joint dependence work therein.<br/>',NULL,3802,3802);
INSERT INTO stanza VALUES('E740','5','It is not God Himself to labor,<br/>Nor man to try to serve alone,<br/>But God and man to work together<br/>Each moment that His plan be shown.<br/>',NULL,3803,3803);
INSERT INTO stanza VALUES('E740','6','The principle of incarnation<br/>To all our work we must apply,<br/>To all our gift and operation,<br/>That we as one may serve thereby.<br/>',NULL,3804,3804);
INSERT INTO stanza VALUES('E741','1','God ordained us unto sonship,<br/>Ere creation''s work was done,<br/>To conform us by His Spirit<br/>To the image of His Son;<br/>That His only dear Begotten<br/>Might become the firstborn One,<br/>And by Him with many brethren<br/>His expression full be won.<br/>',NULL,3805,3805);
INSERT INTO stanza VALUES('E741','2','By divine regeneration<br/>We the sons of God became,<br/>But we must mature to fullness,<br/>Thus the birthright to obtain.<br/>Born and fully grown to manhood,<br/>God''s adoption we may share;<br/>By the measure of full stature,<br/>We God''s sonship will declare.<br/>',NULL,3806,3806);
INSERT INTO stanza VALUES('E741','3','All our spirit, soul and body<br/>Unto Christ conformed must be;<br/>This will be accomplished fully<br/>When our glorious Lord we see.<br/>By our body''s full redemption<br/>Shall adoption be complete;<br/>By the final transformation<br/>All God''s purpose we shall meet.<br/>',NULL,3807,3807);
INSERT INTO stanza VALUES('E741','4','By the final transformation,<br/>We''ll be fully sanctified;<br/>God will bring us into glory,<br/>With His Son identified.<br/>All creation is expecting<br/>Sons of God revealed to be,<br/>That they might be freed from bondage<br/>Into glorious liberty.<br/>',NULL,3808,3808);
INSERT INTO stanza VALUES('E742','1','Man is a being of three parts,<br/>The body, soul, and spirit too,<br/>Th'' eternal purpose to fulfill<br/>With God''s inheritance in view.<br/>',NULL,3809,3809);
INSERT INTO stanza VALUES('E742','2','The body is the outward part<br/>That man a world-sense may possess;<br/>Thus he may touch the outward things<br/>And bodily himself express.<br/>',NULL,3810,3810);
INSERT INTO stanza VALUES('E742','3','The soul within-the inward part-<br/>Is but the very self of man;<br/>The sense of self it gives to him<br/>To touch the psychic world of man.<br/>',NULL,3811,3811);
INSERT INTO stanza VALUES('E742','4','The spirit is the inmost part<br/>With which the Lord he may receive;<br/>The sense of God it gives to man<br/>That he the spirit-world perceive.<br/>',NULL,3812,3812);
INSERT INTO stanza VALUES('E742','5','Within the soul of man there are<br/>The mind, emotion, and the will;<br/>These are the functions for the man<br/>His human nature to fulfill.<br/>',NULL,3813,3813);
INSERT INTO stanza VALUES('E742','6','Within the spirit of the man,<br/>Are found the conscience, fellowship,<br/>And intuition, which thereby<br/>The man to worship God equip.<br/>',NULL,3814,3814);
INSERT INTO stanza VALUES('E742','7','The man must exercise his soul<br/>To choose that God he may possess,<br/>And by his spirit God partake,<br/>And thru his body God express.<br/>',NULL,3815,3815);
INSERT INTO stanza VALUES('E742','8','Man''s spirit had to be reborn<br/>With life divine to him conveyed;<br/>His soul must be transformed by God,<br/>His body like Christ''s body made.<br/>',NULL,3816,3816);
INSERT INTO stanza VALUES('E742','9','''Tis by these steps of work divine<br/>In each of man''s three separate parts<br/>That man is mingled with the Lord<br/>And His expression full imparts.<br/>',NULL,3817,3817);
INSERT INTO stanza VALUES('E743','1','God created us His vessels<br/>His expression to achieve;<br/>Thus He made a heart to love Him<br/>And a spirit to receive.<br/>',NULL,3818,3818);
INSERT INTO stanza VALUES('E743','2','With our heart we have to love Him,<br/>With our spirit Him possess<br/>As our life, of Him partaking,<br/>That Himself we may express.<br/>',NULL,3819,3819);
INSERT INTO stanza VALUES('E743','3','Satan has our heart corrupted,<br/>To our spirit death did give,<br/>That the Lord we should not contact<br/>But by self attempt to live.<br/>',NULL,3820,3820);
INSERT INTO stanza VALUES('E743','4','Thus the Lord in His salvation<br/>Heart and spirit has renewed<br/>To recover our receiving<br/>And our loving aptitude.<br/>',NULL,3821,3821);
INSERT INTO stanza VALUES('E743','5','It is by our heart''s renewal<br/>We may God in love pursue,<br/>And in newness of the spirit<br/>We may contact God anew.<br/>',NULL,3822,3822);
INSERT INTO stanza VALUES('E743','6','Ever true and pure and single<br/>To the Lord our heart must be,<br/>Poor in spirit, ever seeking<br/>God to contact constantly.<br/>',NULL,3823,3823);
INSERT INTO stanza VALUES('E743','7','Keep our heart, Lord, in love''s freshness,<br/>And our spirit strengthen more,<br/>That in newness of the spirit<br/>We may touch Thee o''er and o''er.<br/>',NULL,3824,3824);
INSERT INTO stanza VALUES('E744','1','In dealings with the Lord as life<br/>We need a proper heart,<br/>That of His riches, in His grace,<br/>We fully may take part.<br/>',NULL,3825,3825);
INSERT INTO stanza VALUES('E744','2','We need a heart in all things pure,<br/>With mind both sound and clear,<br/>To understand His mind and heart<br/>In trembling and in fear.<br/>',NULL,3826,3826);
INSERT INTO stanza VALUES('E744','3','We need a fervent, loving heart,<br/>A heart on fire with love,<br/>With an emotion filled with zeal<br/>For Him, all else above.<br/>',NULL,3827,3827);
INSERT INTO stanza VALUES('E744','4','We need a true, obedient heart,<br/>With a submissive will,<br/>A will made pliable, yet strong,<br/>God''s purpose to fulfill.<br/>',NULL,3828,3828);
INSERT INTO stanza VALUES('E744','5','We need a heart condemning not,<br/>In all things right with God;<br/>A heart which has a conscience purged<br/>And covered with the blood.<br/>',NULL,3829,3829);
INSERT INTO stanza VALUES('E744','6','Lord, grant us such a heart as this,<br/>Forever fixed on Thee,<br/>That of Thyself we may partake<br/>And Thy true fulness be.<br/>',NULL,3830,3830);
INSERT INTO stanza VALUES('E745','1','O Lord, Thou art the Spirit now<br/>Who in our spirit lives;<br/>One spirit have the two become,<br/>Which oneness to us gives.<br/>',NULL,3831,3831);
INSERT INTO stanza VALUES('E745','2','Thy Spirit with our spirit, Lord,<br/>The witness ever bears<br/>That we the Father''s children are<br/>And of God''s glory heirs.<br/>',NULL,3832,3832);
INSERT INTO stanza VALUES('E745','3','''Tis in our spirit Thee we touch<br/>Thy riches to enjoy,<br/>And as the Spirit Thou dost give<br/>Thyself without alloy.<br/>',NULL,3833,3833);
INSERT INTO stanza VALUES('E745','4','''Tis in our spirit we may walk<br/>And follow Thee always,<br/>While, as the Spirit, Thou dost lead<br/>And light impart each day.<br/>',NULL,3834,3834);
INSERT INTO stanza VALUES('E745','5','In spirit, by Thy Spirit, Lord,<br/>We live and worship Thee;<br/>Thou, in our spirit, thru Thine own<br/>Strengtheneth constantly.<br/>',NULL,3835,3835);
INSERT INTO stanza VALUES('E745','6','In spirit, with Thy Spirit, Lord,<br/>We offer prayer to Thee,<br/>While, as the Spirit, Thou in us<br/>Groanest unutterably.<br/>',NULL,3836,3836);
INSERT INTO stanza VALUES('E745','7','We to our spirit would return<br/>And there would contact Thine;<br/>''Tis in the spirit we may share<br/>Our heritage divine.<br/>',NULL,3837,3837);
INSERT INTO stanza VALUES('E745','8','What oneness, O my Lord, is this-<br/>Two spirits intertwine!<br/>Thy Spirit in our spirit lives,<br/>And ours abides in Thine!<br/>',NULL,3838,3838);
INSERT INTO stanza VALUES('E746','1','Lord, teach us to discern the spirit<br/>From soul that we Thyself may know;<br/>Thou art the Spirit in our spirit,<br/>In oneness mingled with us so.<br/>',NULL,3839,3839);
INSERT INTO stanza VALUES('E746','2','Lord, teach us to discern the spirit<br/>The soul-life ever to deny,<br/>And ever follow Thee in spirit,<br/>Thyself, the Spirit, to apply.<br/>',NULL,3840,3840);
INSERT INTO stanza VALUES('E746','3','Lord, teach us to discern the spirit<br/>That we may never set our mind<br/>Upon the flesh but on the spirit,<br/>That sin and self no more may bind.<br/>',NULL,3841,3841);
INSERT INTO stanza VALUES('E746','4','Lord, teach us to discern the spirit<br/>That we may never soulish be,<br/>But truly spiritual, in spirit<br/>To know all things discernibly.<br/>',NULL,3842,3842);
INSERT INTO stanza VALUES('E746','5','Lord, teach us to discern the spirit<br/>That subtle self exposed might be,<br/>That by the cross to it applying<br/>We''ll live not by ourselves but Thee.<br/>',NULL,3843,3843);
INSERT INTO stanza VALUES('E746','6','Lord, teach us to discern the spirit<br/>That we may be transformed in soul,<br/>Till we''re conformed to Thine own image,<br/>Till we''re matured and reach the goal.<br/>',NULL,3844,3844);
INSERT INTO stanza VALUES('E746','7','Lord, teach us to discern the spirit<br/>To us Thy living Word so give<br/>That soul from spirit be divided<br/>And in the holiest place we''ll live.<br/>',NULL,3845,3845);
INSERT INTO stanza VALUES('E747','1','The holiest of God''s temple is<br/>The inmost part; the mercy seat,<br/>God''s presence and the ark are there,<br/>And there the priests the Lord may meet.<br/>',NULL,3846,3846);
INSERT INTO stanza VALUES('E747','2','Now we''re God''s temple in three parts;<br/>Our inmost part the spirit is;<br/>There God and Christ as Spirit dwell,<br/>The holiest place of holy ''tis.<br/>',NULL,3847,3847);
INSERT INTO stanza VALUES('E747','3','''Tis here within our inmost part<br/>That God in Christ is all to us;<br/>''Tis here the Holy Spirit makes<br/>The Lord reality to us.<br/>',NULL,3848,3848);
INSERT INTO stanza VALUES('E747','4','''Tis here within the spirit-part<br/>We contact Christ and dwell with Him;<br/>''Tis by our spirit we with God<br/>Have fellowship and worship Him.<br/>',NULL,3849,3849);
INSERT INTO stanza VALUES('E747','5','''Tis here that Christ is like the land<br/>Where we may dwell, its wealth enjoy;<br/>''Tis here that we must fight the foe,<br/>And Christ''s authority employ.<br/>',NULL,3850,3850);
INSERT INTO stanza VALUES('E747','6','The spirit we must seek to know,<br/>Discerning spirit from the soul,<br/>And live within this holiest place,<br/>To worship God and reach His goal.<br/>',NULL,3851,3851);
INSERT INTO stanza VALUES('E747','7','The soul we ever must forsake,<br/>Press on, God''s rest to enter in,<br/>That Christ we may possess in full<br/>And all God''s plan fulfill therein.<br/>',NULL,3852,3852);
INSERT INTO stanza VALUES('E748','1','By the cross discern the spirit,<br/>Put the soul to death away;<br/>Bear the cross, deny the self-life,<br/>Walk in spirit day by day.<br/>',NULL,3853,3853);
INSERT INTO stanza VALUES('E748','2','By the cross discern the spirit,<br/>Through the living Word of God,<br/>Separating soul from spirit,<br/>That the right path may be trod.<br/>',NULL,3854,3854);
INSERT INTO stanza VALUES('E748','3','By the cross discern the spirit,<br/>With the mind by light renewed,<br/>All emotion consecrated,<br/>And the will in love subdued.<br/>',NULL,3855,3855);
INSERT INTO stanza VALUES('E748','4','By the cross discern the spirit,<br/>Passing thru the riven veil,<br/>Flesh and soul are wholly broken,<br/>And the spirit doth prevail.<br/>',NULL,3856,3856);
INSERT INTO stanza VALUES('E748','5','By the cross discern the spirit,<br/>''Tis the holiest place divine;<br/>There commune with God in spirit<br/>And His presence will be thine.<br/>',NULL,3857,3857);
INSERT INTO stanza VALUES('E748','6','By the cross discern the spirit,<br/>And the Jordan River cross;<br/>Enter then the Land of Canaan,<br/>And enjoy Christ thru the cross.<br/>',NULL,3858,3858);
INSERT INTO stanza VALUES('E748','7','By the cross discern the spirit,<br/>And within the spirit move;<br/>As good land, on Christ e''er labor,<br/>And His riches thou wilt prove.<br/>',NULL,3859,3859);
INSERT INTO stanza VALUES('E749','1','The Spirit of the triune God<br/>Within our spirit now doth rest;<br/>He ever seeks thru us to flow,<br/>That God in Christ may be expressed.<br/>',NULL,3860,3860);
INSERT INTO stanza VALUES('E749','2','But by the outward, natural man<br/>The Spirit is confined within;<br/>Instead of giving Him a home,<br/>A prison we''ve become to Him.<br/>',NULL,3861,3861);
INSERT INTO stanza VALUES('E749','3','He''s like a treasure of great worth<br/>Contained in vessels earthen-made;<br/>The vessel must be broken through<br/>And thus the treasure be displayed.<br/>',NULL,3862,3862);
INSERT INTO stanza VALUES('E749','4','Oh, how the Lord our self must break,<br/>Our outward man does so impede!<br/>It must be broken thoroughly,<br/>And thus the Spirit will be freed.<br/>',NULL,3863,3863);
INSERT INTO stanza VALUES('E749','5','This is the reason why the Lord<br/>For us a certain measure makes<br/>Of circumstantial suffering;<br/>''Tis thus our outward man He breaks.<br/>',NULL,3864,3864);
INSERT INTO stanza VALUES('E749','6','The outward man, the self, the soul,<br/>Must be consumed, must be decreased;<br/>The inner man, our spirit, then<br/>Shall with the Spirit be released.<br/>',NULL,3865,3865);
INSERT INTO stanza VALUES('E749','7','Lord, grant Thy holy brokenness,<br/>Deliver me from being whole;<br/>And make me willing to receive<br/>The wounds that Thou wouldst give my soul.<br/>',NULL,3866,3866);
INSERT INTO stanza VALUES('E749','8','Oh, cause me to appreciate<br/>Thy breaking, never to complain;<br/>And grant that I may value more<br/>All kinds of loss instead of gain.<br/>',NULL,3867,3867);
INSERT INTO stanza VALUES('E750','1','God''s intention is to have us<br/>All conformed to His dear Son;<br/>Thus a work of transformation<br/>By the Spirit must be done.<br/>',NULL,3868,3868);
INSERT INTO stanza VALUES('E750','chorus','Lord, transform us to Thine image<br/>In emotion, mind and will;<br/>Saturate us with Thy Spirit,<br/>All our being wholly fill.<br/>',NULL,3869,3869);
INSERT INTO stanza VALUES('E750','2','God hath us regenerated<br/>In our spirit with His life;<br/>But He must transform us further;<br/>In our soul by His own life.<br/>',NULL,3870,3870);
INSERT INTO stanza VALUES('E750','3','Spreading outward from our spirit<br/>Doth the Lord transform our soul,<br/>By the inward parts renewing,<br/>Till within His full control.<br/>',NULL,3871,3871);
INSERT INTO stanza VALUES('E750','4','By the power of His Spirit<br/>In His pattern He transforms;<br/>From His glory to His glory<br/>To His image He conforms.<br/>',NULL,3872,3872);
INSERT INTO stanza VALUES('E750','5','He transforms, all sanctifying,<br/>Till like Him we are matured;<br/>He transforms, our soul possessing,<br/>Till His stature is secured.<br/>',NULL,3873,3873);
INSERT INTO stanza VALUES('E751','1','It is not by struggling,<br/>But by yielding all,<br/>I may rest from labor,<br/>All my burden fall.<br/>It is not resolving,<br/>But Thyself to heed,<br/>I''m from sin delivered<br/>And from bondage freed.<br/>',NULL,3874,3874);
INSERT INTO stanza VALUES('E751','2','It is not by letter,<br/>But by Spirit ''tis,<br/>I will be approved,<br/>Share Thy life of bliss.<br/>It is not man''s teaching,<br/>But anointing Thine,<br/>Which imparts Thy light and<br/>Fellowship divine.<br/>',NULL,3875,3875);
INSERT INTO stanza VALUES('E751','3','It is not resolving<br/>Now to run the race,<br/>But ''tis by Thy mercy<br/>I receive Thy grace.<br/>It is not by knowledge,<br/>But by grace alone,<br/>I can pass thru suff''ring<br/>To Thine image grown.<br/>',NULL,3876,3876);
INSERT INTO stanza VALUES('E751','4','Not by lofty phrases,<br/>But by power Thine,<br/>I the lost can pilot<br/>Unto life divine.<br/>It is not my wisdom,<br/>But Thy Spirit, Lord,<br/>Which alone can fit me<br/>To fulfill Thy Word.<br/>',NULL,3877,3877);
INSERT INTO stanza VALUES('E752','1','I am the Lord that healeth thee,<br/>I am the Lord that healeth thee;<br/>Jehovah-Rapha is My Name:<br/>For I am the Lord that healeth thee.<br/>',NULL,3878,3878);
INSERT INTO stanza VALUES('E752','2','I am the Lord that healeth thee,<br/>I am the Lord that healeth thee;<br/>Sickness must flee at My command:<br/>For I am the Lord that healeth thee.<br/>',NULL,3879,3879);
INSERT INTO stanza VALUES('E752','3','I am the Lord that healeth thee,<br/>I am the Lord that healeth thee;<br/>The prayer of faith shall banish disease:<br/>For I am the Lord that healeth thee.<br/>',NULL,3880,3880);
INSERT INTO stanza VALUES('E752','4','I am the Lord that healeth thee,<br/>I am the Lord that healeth thee;<br/>My Name is still as ointment poured forth:<br/>For I am the Lord that healeth thee.<br/>',NULL,3881,3881);
INSERT INTO stanza VALUES('E752','5','I am the Lord that healeth thee,<br/>I am the Lord that healeth thee;<br/>Come and be free from all your pains:<br/>For I am the Lord that healeth thee.<br/>',NULL,3882,3882);
INSERT INTO stanza VALUES('E753','1','There is a healing branch that grows<br/>Where every bitter Marah flows;<br/>This is our health-renewing tree.<br/>"I am the Lord that healeth thee."<br/>',NULL,3883,3883);
INSERT INTO stanza VALUES('E753','2','There is an old appointed way<br/>For those who harken and obey;<br/>Above the gate these words we see:<br/>"I am the Lord that healeth thee."<br/>',NULL,3884,3884);
INSERT INTO stanza VALUES('E753','3','There is an ordinance that has stood<br/>Since Israel crossed the parted flood;<br/>It stands today for you and me-<br/>"I am the Lord that healeth thee."<br/>',NULL,3885,3885);
INSERT INTO stanza VALUES('E753','4','There is a great Physician still<br/>Whose hand has all its ancient skill;<br/>At His command our pains will flee-<br/>"I am the Lord that healeth thee."<br/>',NULL,3886,3886);
INSERT INTO stanza VALUES('E754','1','To those who fear Jehovah''s name<br/>How sweet the word the prophet brings:<br/>The Sun of Righteousness shall rise<br/>With healing in His wings.<br/>',NULL,3887,3887);
INSERT INTO stanza VALUES('E754','2','It is to those that fear His name<br/>His healing power the Savior brings;<br/>Oh, let us hide with contrite hearts<br/>Beneath His healing wings.<br/>',NULL,3888,3888);
INSERT INTO stanza VALUES('E754','3','He is the Sun of Righteousness;<br/>And while to sin our being clings<br/>We cannot know His healing touch<br/>Or rest beneath His wings.<br/>',NULL,3889,3889);
INSERT INTO stanza VALUES('E754','4','It is His wings that heal our pains<br/>And soothe the serpent''s poisoned stings;<br/>Close to His bosom we must press<br/>To feel His healing wings.<br/>',NULL,3890,3890);
INSERT INTO stanza VALUES('E754','5','Beneath those healing wings I rest,<br/>While all my heart with rapture sings:<br/>The Sun of Righteousness has risen<br/>With healing in His wings.<br/>',NULL,3891,3891);
INSERT INTO stanza VALUES('E755','1','He healeth me, oh, bless His name!<br/>I want to spread abroad His fame;<br/>From dread disease He sets me free,<br/>The Lord my healer, strong is He!<br/>',NULL,3892,3892);
INSERT INTO stanza VALUES('E755','chorus','He healeth me, He healeth me!<br/>By power divine He healeth me;<br/>He healed the sick in Galilee,<br/>And now by faith He healeth me!<br/>',NULL,3893,3893);
INSERT INTO stanza VALUES('E755','2','He healeth me! My simple faith<br/>Believes the word that Jesus saith,<br/>And takes the place of ardent hope,<br/>Believes the Lord will raise me up.<br/>',NULL,3894,3894);
INSERT INTO stanza VALUES('E755','3','He healeth me! I touch for cure<br/>The border of His garment pure,<br/>And virtue through my being flows,<br/>And healing balm for nature''s woes.<br/>',NULL,3895,3895);
INSERT INTO stanza VALUES('E755','4','He healeth me, as when of yore,<br/>Their sins and sickness He bore;<br/>Nor has He lost His power and skill-<br/>Our blessed Christ is living still.<br/>',NULL,3896,3896);
INSERT INTO stanza VALUES('E755','5','He healeth me! How oft I sought<br/>This healing power, but found it not:<br/>But now I trust with all my soul,<br/>And now through faith He makes me whole.<br/>',NULL,3897,3897);
INSERT INTO stanza VALUES('E756','1','When Christ of old with healing pow''r<br/>When forth through all the suffering land,<br/>His word so oft was wont to be,<br/>''Stretch forth thy hand, stretch forth thy hand!"<br/>And though the palsied arm might shrink<br/>And tremble at the strange command,<br/>The healing touch was only felt<br/>While stretching forth the withered hand.<br/>',NULL,3898,3898);
INSERT INTO stanza VALUES('E756','chorus','O suffering one, stretch forth your hand,<br/>Upon His promise take your stand.<br/>At His command stretch forth your hand,<br/>And Christ shall make you whole.<br/>',NULL,3899,3899);
INSERT INTO stanza VALUES('E756','2','That changeless Christ is still as near<br/>And just as kind and strong to save;<br/>He came to lift our fallen race<br/>From sin and sickness and the grave.<br/>As in the days of Galilee,<br/>Disease still flees at His command;<br/>But ere His touch your frame can feel,<br/>You, too, must still stretch forth your hand.<br/>',NULL,3900,3900);
INSERT INTO stanza VALUES('E756','3','What though you feel so weak and faint?<br/>He can your will with strength endue,<br/>New faith and courage breathe within<br/>And work in you to will and do.<br/>Reach out to meet His quickening touch;<br/>Take up your bed, arise and stand;<br/>And pressing through to meet your Lord,<br/>Stretch forth your hand, stretch forth your hand.<br/>',NULL,3901,3901);
INSERT INTO stanza VALUES('E757','1','At even when the sun was set,<br/>The sick, O Lord, around Thee lay;<br/>O in what divers pains they meet!<br/>O with what joy they went away!<br/>',NULL,3902,3902);
INSERT INTO stanza VALUES('E757','2','Once more ''tis eventide, and we<br/>Oppressed with various ills draw near;<br/>What if Thy form we cannot see?<br/>We know and feel that Thou art here.<br/>',NULL,3903,3903);
INSERT INTO stanza VALUES('E757','3','O Savior Christ, our woes dispel;<br/>For some are sick, and some are sad,<br/>And some have never love Thee well<br/>And some have lost the love they had;<br/>',NULL,3904,3904);
INSERT INTO stanza VALUES('E757','4','And some have found the world is vain,<br/>Yet from the world they break not free;<br/>And some have friends who give them pain,<br/>Yet have not sought a friend in Thee;<br/>',NULL,3905,3905);
INSERT INTO stanza VALUES('E757','5','And none, O Lord, have perfect rest,<br/>For none are wholly free from sin;<br/>And they who fain would serve Thee best<br/>Are conscious most of wrong within.<br/>',NULL,3906,3906);
INSERT INTO stanza VALUES('E757','6','O Savior Christ, Thou too art Man;<br/>Thou hast been troubled, tempted, tried;<br/>Thy kind but searching glance can scan<br/>The very wounds that shame would hide.<br/>',NULL,3907,3907);
INSERT INTO stanza VALUES('E757','7','Thy touch has still its ancient power;<br/>No word from Thee can fruitless fall;<br/>Hear in this solemn evening hour,<br/>And in Thy mercy heal us all.<br/>',NULL,3908,3908);
INSERT INTO stanza VALUES('E758','1','Have you found the great Physician,<br/>Jesus Christ of Galilee?<br/>He who bore our pain and sorrow,<br/>On the shameful, cruel tree?<br/>Still He heals the sick and suff''ring,<br/>As before He went away;<br/>For His word most plainly tells us,<br/>"He is just the same today."<br/>',NULL,3909,3909);
INSERT INTO stanza VALUES('E758','chorus','He is just the same today;<br/>As before He went away.<br/>Look to Him, believe and pray;<br/>Trust His word and then obey.<br/>"Praise God, He is just the same today."<br/>',NULL,3910,3910);
INSERT INTO stanza VALUES('E758','2','Consecrate your life to Jesus,<br/>Spirit, soul, and body too;<br/>For "the Lord is for the body,"<br/>Every pow''r He gave to you.<br/>Let there be no reservation,<br/>Give the Lord full right of way;<br/>He will come and heal His temple,<br/>For He is the same today.<br/>',NULL,3911,3911);
INSERT INTO stanza VALUES('E758','3','Do you doubt God''s will to heal you?<br/>Take His word and ask for light;<br/>If you seek in deep contrition,<br/>He will guide your heart aright.<br/>Do you fear to claim His promise,<br/>He will not your trust betray;<br/>When on earth He gladly healed them,<br/>And He is the same today.<br/>',NULL,3912,3912);
INSERT INTO stanza VALUES('E758','4','Oh! I''m glad to tell you, suff''rer,<br/>Christ has more than healing too;<br/>Life abundant overflowing,<br/>He will gladly give to you.<br/>Step out boldly, claim His fulness,<br/>Let your sadness, flee away;<br/>When on earth He made them joyful,<br/>And He is the same today.<br/>',NULL,3913,3913);
INSERT INTO stanza VALUES('E759','1','Just one touch as He move along,<br/>Pushed and pressed by the jostling throng,<br/>Just one touch and the weak was strong,<br/>Cured by the Healer divine.<br/>',NULL,3914,3914);
INSERT INTO stanza VALUES('E759','chorus','Just one touch as He passes by,<br/>He will list to the faintest cry.<br/>Come and be cured while the Lord is nigh,<br/>Christ is the Healer divine.<br/>',NULL,3915,3915);
INSERT INTO stanza VALUES('E759','2','Just one touch! And He makes me whole,<br/>Speaks sweet peace to my sin-sick soul,<br/>At His feet all my burdens roll,<br/>Cured by the Healer divine.<br/>',NULL,3916,3916);
INSERT INTO stanza VALUES('E759','3','Just one touch! And the work is done,<br/>I am cured by the blessed Son,<br/>I will sing while the ages run,<br/>Cured by the Healer divine.<br/>',NULL,3917,3917);
INSERT INTO stanza VALUES('E759','4','Just one touch! And He turns to me,<br/>O the love in His eyes I see!<br/>I am His for He bears my plea,<br/>Cured by the Healer divine.<br/>',NULL,3918,3918);
INSERT INTO stanza VALUES('E759','5','Just one touch! By His mighty power<br/>He can heal thee this very hour,<br/>Thou canst hear though the tempests low''r,<br/>Cured by the Healer divine.<br/>',NULL,3919,3919);
INSERT INTO stanza VALUES('E760','1','She only touched the hem of His garment<br/>As to His side she stole,<br/>Amid the crowd that gathered around Him;<br/>And straightway she was whole.<br/>',NULL,3920,3920);
INSERT INTO stanza VALUES('E760','chorus','Oh, touch the hem of His garment,<br/>And thou, too, shalt be free!<br/>His healing pow''r this very hour<br/>Shall give new life to thee!<br/>',NULL,3921,3921);
INSERT INTO stanza VALUES('E760','2','She came in fear and trembling before Him,<br/>She knew her Lord had come,<br/>She felt that from Him virtue had healed her,<br/>The mighty deed was done.<br/>',NULL,3922,3922);
INSERT INTO stanza VALUES('E760','3','He turned with "Daughter, be of good comfort,<br/>Thy faith hath made thee whole";<br/>And peace that passeth all understanding<br/>With gladness filled her soul.<br/>',NULL,3923,3923);
INSERT INTO stanza VALUES('E761','1','Prayer is the soul''s sincere desire,<br/>Uttered, or unexpressed;<br/>The motion of a hidden fire<br/>That trembles in the breast.<br/>',NULL,3924,3924);
INSERT INTO stanza VALUES('E761','2','Prayer is the burden of a sigh,<br/>The falling of a tear;<br/>The upward glancing of an eye<br/>When none but God is near.<br/>',NULL,3925,3925);
INSERT INTO stanza VALUES('E761','3','Prayer is the simplest form of speech<br/>That infant lips can try;<br/>Prayer the sublimest strains that reach<br/>The Majesty on high.<br/>',NULL,3926,3926);
INSERT INTO stanza VALUES('E761','4','Prayer is the Christian''s vital breath,<br/>The Christian''s native air;<br/>His watchword at the gates of death;<br/>He enters rest with prayer.<br/>',NULL,3927,3927);
INSERT INTO stanza VALUES('E761','5','The saints in prayer appear as one,<br/>In word, and deed, and mind;<br/>While with the Father and the Son<br/>Sweet fellowship they find.<br/>',NULL,3928,3928);
INSERT INTO stanza VALUES('E761','6','O Thou, by whom we come to God,<br/>The Life, the Truth, the Way,<br/>The path of prayer Thyself hast trod-<br/>Lord, teach us how to pray.<br/>',NULL,3929,3929);
INSERT INTO stanza VALUES('E762','1','Prayer is the incense of a holy heart<br/>Rising to God from bruised and broken things,<br/>When kindled by the Spirit''s burning breath<br/>And upward borne by faith''s burning breath<br/>And upward borne by faith''s ascending wings.<br/>',NULL,3930,3930);
INSERT INTO stanza VALUES('E762','2','Prayer is the perfume of the plants of grace,<br/>The flowers of patience, faith, and suffering love;<br/>Treasured in "vials full of odors sweet,"<br/>God breathes their fragrance in His courts above.<br/>',NULL,3931,3931);
INSERT INTO stanza VALUES('E762','3','Prayer is th'' ascending vapor which supplies<br/>The showers of blessing, and the stream that flows<br/>Through earth''s dry places, till on every side<br/>"The wilderness shall blossom as the rose."<br/>',NULL,3932,3932);
INSERT INTO stanza VALUES('E762','4','Prayer is the heavenly telephone that brings<br/>The distant near, till heaven to earth comes down,<br/>And in our Father''s ear and heart we may<br/>Our burdens tell and all our sorrows drown.<br/>',NULL,3933,3933);
INSERT INTO stanza VALUES('E762','5','Prayer is the wireless telegraph that sends<br/>Its heart throbs on the ether waves of heaven;<br/>It finds the heart of God, and back to earth<br/>The answering thrill to faith and love are given.<br/>',NULL,3934,3934);
INSERT INTO stanza VALUES('E762','6','Prayer is the golden pipes the Spirit fills,<br/>Which feed the lamps of God with oil divine,<br/>And, as with one accord we wait and pray,<br/>The Spirit fills, the lamps with brightness shine.<br/>',NULL,3935,3935);
INSERT INTO stanza VALUES('E762','7','Prayer is the mightiest force of earth and heaven,<br/>Prayer is the very dynamite of God;<br/>It moves the hand that all things moves, and turns<br/>The living wheels that sweep through earth abroad.<br/>',NULL,3936,3936);
INSERT INTO stanza VALUES('E762','8','Teach us to pray! Move on our hearts, O Lord,<br/>Till Thine own passion all our being move!<br/>Teach us! Pray in us, till our prayer shall be<br/>Christ in us praying to the Christ above!<br/>',NULL,3937,3937);
INSERT INTO stanza VALUES('E762','9','Teach us to pray! Reveal Thy will to us,<br/>Till Thine own purpose all our being move!<br/>Teach us! Pray in us, till our prayer shall be<br/>God in us answering to the God above!<br/>',NULL,3938,3938);
INSERT INTO stanza VALUES('E763','1','Christ is the Alpha of our prayers;<br/>We know not how to pray<br/>Save as His Spirit in our hearts<br/>Shall teach us what to say.<br/>',NULL,3939,3939);
INSERT INTO stanza VALUES('E763','2','Christ is the Omega of our prayer,<br/>The Father''s great Amen<br/>That rounds our halting periods<br/>To sense beyond our ken.<br/>',NULL,3940,3940);
INSERT INTO stanza VALUES('E763','3','But in the little space between,<br/>He let us make the links,<br/>And with our slow and stammering speech<br/>Interpret what He thinks.<br/>',NULL,3941,3941);
INSERT INTO stanza VALUES('E763','4','O First and Last, take Thou the prayers<br/>Of every trusting soul,<br/>And weld them to Thine own desire<br/>To make a perfect whole.<br/>',NULL,3942,3942);
INSERT INTO stanza VALUES('E763','5','Thou great Beginning of that Word<br/>We cannot speak or spell,<br/>Of the short syllable we lisp<br/>Be Thou the End as well!<br/>',NULL,3943,3943);
INSERT INTO stanza VALUES('E764','1','Lord, in Thy presence silent I would be,<br/>That in the inmost I to Thee may come;<br/>I would not in my own way pray to Thee,<br/>But let Thy prayer in me my prayer become.<br/>',NULL,3944,3944);
INSERT INTO stanza VALUES('E764','2','It seems Thou art in heaven hearing me,<br/>But right within my spirit Thou dost dwell;<br/>It seems that I am praying unto Thee,<br/>But really from Thyself the prayer do well.<br/>',NULL,3945,3945);
INSERT INTO stanza VALUES('E764','3','When, Lord, no words my burden can express,<br/>My spirit with Thy Spirit deeply groans;<br/>Not verbally I then my plea address,<br/>But Thou dost pray within my words unknown.<br/>',NULL,3946,3946);
INSERT INTO stanza VALUES('E764','4','I would inhale Thee, Lord, e''en as I breathe,<br/>And eat and drink Thee as my life supply.<br/>A deeper fellowship with Thee bequeath<br/>That Thou express Thyself through me thereby.<br/>',NULL,3947,3947);
INSERT INTO stanza VALUES('E764','5','Here in this fellowship Thy light doth shine,<br/>Thy precious blood doth cleanse and make me clean;<br/>May I not only, Lord, Thy light enshrine,<br/>But may Thou be expressed and clearly seen.<br/>',NULL,3948,3948);
INSERT INTO stanza VALUES('E764','6','Thy oil anoints me here in every way,<br/>Anointing Thee within unceasingly;<br/>I more decrease, Thou more increase each day,<br/>Thus full expression Thou shalt have through me.<br/>',NULL,3949,3949);
INSERT INTO stanza VALUES('E764','7','Myself I open that Thou may flow in;<br/>Op''ning myself to others, Lord, flow out;<br/>By such a stream, the fellowship within,<br/>Thou, Lord, expressed will be my life throughout.<br/>',NULL,3950,3950);
INSERT INTO stanza VALUES('E765','1','Christian, seek not yet repose,<br/>Hear thy gracious Savior say;<br/>Thou are in the midst of foes:<br/>Watch and pray.<br/>',NULL,3951,3951);
INSERT INTO stanza VALUES('E765','2','Principalities and powers,<br/>Mustering their unseen array,<br/>Wait for thy unguarded hours:<br/>Watch and pray.<br/>',NULL,3952,3952);
INSERT INTO stanza VALUES('E765','3','Gird thy heavenly armor on,<br/>Wear it ever night and day;<br/>Ambushed lies the evil one:<br/>Watch and pray.<br/>',NULL,3953,3953);
INSERT INTO stanza VALUES('E765','4','Hear the victors who o''ercame,<br/>Still they mark each warrior''s way;<br/>All with on sweet voice exclaim,<br/>Watch and pray.<br/>',NULL,3954,3954);
INSERT INTO stanza VALUES('E765','5','Hear, above all, hear thy Lord,<br/>Him thou lovest to obey;<br/>Hide within thy heart His word:<br/>Watch and pray.<br/>',NULL,3955,3955);
INSERT INTO stanza VALUES('E765','6','Watch, as if on that alone<br/>Hung the issue of the day;<br/>Pray, that help may be sent down:<br/>Watch and pray.<br/>',NULL,3956,3956);
INSERT INTO stanza VALUES('E766','1','Teach me to pray, Lord, teach me to pray;<br/>This is my heart-cry day unto day;<br/>I long to know Thy will and Thy way;<br/>Teach me to pray, Lord teach me to pray.<br/>',NULL,3957,3957);
INSERT INTO stanza VALUES('E766','chorus','Living in Thee, Lord, and Thou in me,<br/>Constant abiding, this is my plea;<br/>Grant me Thy power, boundless and free,<br/>Power with men and power with Thee.<br/>',NULL,3958,3958);
INSERT INTO stanza VALUES('E766','2','Power in prayer, Lord, power in prayer!<br/>Here ''mid earth''s sin and sorrow and care,<br/>Men lost and dying, souls in despair;<br/>O give me power, power in prayer!<br/>',NULL,3959,3959);
INSERT INTO stanza VALUES('E766','3','My weakened will, Lord, Thou canst renew;<br/>My sinful nature Thou canst subdue;<br/>Fill me just not with power anew;<br/>Power to pray and power to do!<br/>',NULL,3960,3960);
INSERT INTO stanza VALUES('E766','4','Teach me to pray, Lord, teach me to pray;<br/>Thou art my pattern day unto day;<br/>Thou art my surety, now and for aye;<br/>Teach me to pray, Lord teach me to pray.<br/>',NULL,3961,3961);
INSERT INTO stanza VALUES('E767','1','Teach us to pray that we may cause<br/>The enemy to flee,<br/>That we his evil pow''r may bind,<br/>His prisoner to free.<br/>',NULL,3962,3962);
INSERT INTO stanza VALUES('E767','2','Teach us to pray and firmly stand<br/>Upon the battleground,<br/>To fight and break the stronghold down,<br/>The enemy confound.<br/>',NULL,3963,3963);
INSERT INTO stanza VALUES('E767','3','Teach us to pray and use Thy rod<br/>In strong, prevailing prayer,<br/>Beneath Thy blood to shake the earth<br/>And powers of the air.<br/>',NULL,3964,3964);
INSERT INTO stanza VALUES('E767','4','By prayer and faith, O may we learn<br/>To labor, Lord, with Thee,<br/>To know the victory is ours<br/>And Thine authority.<br/>',NULL,3965,3965);
INSERT INTO stanza VALUES('E768','1','Lord, teach us to use<br/>The intercessor''s rod,<br/>As Moses did of old<br/>Upon the hill of God.<br/>',NULL,3966,3966);
INSERT INTO stanza VALUES('E768','2','Before the upstayed arm<br/>The ranks of darkness quailed!<br/>In great Jehovah''s Name<br/>The host of light prevailed!<br/>',NULL,3967,3967);
INSERT INTO stanza VALUES('E768','3','Teach us to bind the foe<br/>With iron chains of prayer,<br/>That all Thy Church may move<br/>To victory everywhere.<br/>',NULL,3968,3968);
INSERT INTO stanza VALUES('E768','4','Give us the steady arm,<br/>Until the sun go down,<br/>That we in Christ may win<br/>The overcomer''s crown.<br/>',NULL,3969,3969);
INSERT INTO stanza VALUES('E769','1','To the holiest place I''d come,<br/>There within the veil to be;<br/>There to touch the throne of grace,<br/>Let Life''s water flow thru me.<br/>',NULL,3970,3970);
INSERT INTO stanza VALUES('E769','2','Now the holiest place of all<br/>Right within my spirit is;<br/>Here the Lord in me abides,<br/>And my spirit joins with His.<br/>',NULL,3971,3971);
INSERT INTO stanza VALUES('E769','3','To my spirit I''d return,<br/>For ''tis here the Lord I''ll meet;<br/>O how marvelous it is!<br/>He''s within, in me complete.<br/>',NULL,3972,3972);
INSERT INTO stanza VALUES('E769','4','Fragrance of the risen Christ<br/>Thru my spirit may be spread;<br/>If in spirit I will pray<br/>Christ will be exhibited.<br/>',NULL,3973,3973);
INSERT INTO stanza VALUES('E769','5','If in spirit Him I touch,<br/>With His riches filled I''ll be;<br/>Life and light and love and grace<br/>As a stream will flow thru me.<br/>',NULL,3974,3974);
INSERT INTO stanza VALUES('E769','6','Touching deeply, richly I<br/>Of Himself experience,<br/>Thus the law of life I touch<br/>And His clear anointing sense.<br/>',NULL,3975,3975);
INSERT INTO stanza VALUES('E769','7','In my spirit deeper still<br/>I would touch the Lord I love,<br/>Touch Him in His hidden depth<br/>And His hidden manna prove.<br/>',NULL,3976,3976);
INSERT INTO stanza VALUES('E769','8','When the resurrection life<br/>Is made real in pow''r to me,<br/>As the rod with sprouting buds,<br/>I will then accepted be.<br/>',NULL,3977,3977);
INSERT INTO stanza VALUES('E769','9','Here I find the throne of grace,<br/>Where the living water flows<br/>As a river full of grace<br/>Into me grace to bestow.<br/>',NULL,3978,3978);
INSERT INTO stanza VALUES('E769','10','Then whene''er we meet to pray,<br/>All our spirits we''ll release;<br/>Mingled will our spirits be,<br/>And we''ll serve the Lord as priests.<br/>',NULL,3979,3979);
INSERT INTO stanza VALUES('E769','11','This the holiest place is too,<br/>Where we all may touch the Lord,<br/>Touch His throne in many ways<br/>Till His grace on us is poured.<br/>',NULL,3980,3980);
INSERT INTO stanza VALUES('E770','1','In the holiest place, touch the throne of grace,<br/>Grace as a river shall flow;<br/>In the holiest place, touch the throne of grace,<br/>Grace as a river shall flow;<br/>',NULL,3981,3981);
INSERT INTO stanza VALUES('E770','chorus','Hallelujah! Hallelujah!<br/>Grace as a river shall flow;<br/>Hallelujah! Hallelujah!<br/>Grace as a river shall flow;<br/>',NULL,3982,3982);
INSERT INTO stanza VALUES('E770','2','In the holiest place, live before His face,<br/>Light of glory thru me will shine;<br/>In the holiest place, live before His face,<br/>Light of glory thru me will shine;<br/>',NULL,3983,3983);
INSERT INTO stanza VALUES('E770','chorus','Hallelujah! Hallelujah!<br/>Light of glory thru me will shine;<br/>Hallelujah! Hallelujah!<br/>Light of glory thru me will shine;<br/>',NULL,3984,3984);
INSERT INTO stanza VALUES('E770','3','To the spirit turn, and the incense burn,<br/>Touch the living fountain of life;<br/>To the spirit turn, and the incense burn,<br/>Touch the living fountain of life;<br/>',NULL,3985,3985);
INSERT INTO stanza VALUES('E770','chorus','Hallelujah! Hallelujah!<br/>Touch the living fountain of life;<br/>Hallelujah! Hallelujah!<br/>Touch the living fountain of life;<br/>',NULL,3986,3986);
INSERT INTO stanza VALUES('E771','1','The veil is rent and opened is<br/>A new and living way;<br/>With boldness thru the precious blood,<br/>We come to Thee to pray.<br/>',NULL,3987,3987);
INSERT INTO stanza VALUES('E771','2','By Thy redemption we may come<br/>Into the holiest place;<br/>Thy Spirit now anointing us,<br/>We touch the throne of grace.<br/>',NULL,3988,3988);
INSERT INTO stanza VALUES('E771','3','In spirit only we would pray,<br/>Ourselves by Thee possessed,<br/>That from our spirit Christ the Lord<br/>As incense be expressed.<br/>',NULL,3989,3989);
INSERT INTO stanza VALUES('E771','4','Thy grace and mercy as a stream<br/>From out the throne does flow,<br/>Refreshing in the hour of need-<br/>How rich, how sweet to know!<br/>',NULL,3990,3990);
INSERT INTO stanza VALUES('E771','5','Though for our needs we do not ask<br/>But by Thy Spirit pray,<br/>Our every need is known to Thee,<br/>We''re in Thy care alway.<br/>',NULL,3991,3991);
INSERT INTO stanza VALUES('E771','6','Though griefs and trials on us press,<br/>We will not anxious be,<br/>But all our care upon Thee cast<br/>And set our spirit free.<br/>',NULL,3992,3992);
INSERT INTO stanza VALUES('E771','7','O may I concentrated be<br/>In fellowship with Thee,<br/>My prayer and incense offering,<br/>Thy Spirit leading me.<br/>',NULL,3993,3993);
INSERT INTO stanza VALUES('E772','1','Lord, we meet to seek Thy face<br/>And in one accord to pray;<br/>We a holy priesthood are,<br/>Waiting on Thee here today.<br/>',NULL,3994,3994);
INSERT INTO stanza VALUES('E772','chorus','Here together we would pray,<br/>Touch the highest and the best,<br/>Till our spirits mingled are<br/>And Thy Church is built and blest.<br/>',NULL,3995,3995);
INSERT INTO stanza VALUES('E772','2','As true priests we long to be,<br/>With our spirit sense Thy will,<br/>Thus to serve before Thee here<br/>That Thy plan Thou may fulfill.<br/>',NULL,3996,3996);
INSERT INTO stanza VALUES('E772','3','To the holiest place we come,''<br/>Now to touch Thy throne of grace,<br/>By the inner sense to pray<br/>And Thy Spirit''s flow to trace.<br/>',NULL,3997,3997);
INSERT INTO stanza VALUES('E772','4','From Thy throne of grace to me<br/>Rivers of Thy grace proceed;<br/>Thus my spirit is refreshed,<br/>Helping me in time of need.<br/>',NULL,3998,3998);
INSERT INTO stanza VALUES('E772','5','May our prayers expression give<br/>To Thy Spirit''s mind alone;<br/>Praying not by our desire,<br/>But according to Thine own.<br/>',NULL,3999,3999);
INSERT INTO stanza VALUES('E772','6','Though with temporal matters pressed,<br/>Which we fain would bring to Thee,<br/>Rather than Thy care to seek,<br/>We would here Thy channel be.<br/>',NULL,4000,4000);
INSERT INTO stanza VALUES('E772','7','Here we seek Thy list''ning ear,<br/>May Thy living water flow;<br/>When Thy grace does satisfy,<br/>Only then Thy work we''ll know.<br/>',NULL,4001,4001);
INSERT INTO stanza VALUES('E773','1','Lord Jesus Christ, we seek Thy face;<br/>Within the veil we bow the knee;<br/>Oh, let Thy glory fill the place,<br/>And bless us while we wait on Thee.<br/>',NULL,4002,4002);
INSERT INTO stanza VALUES('E773','2','We thank Thee for the precious blood<br/>That purged our sins and brought us nigh;<br/>All cleansed and sanctified to God,<br/>Thy holy name to magnify.<br/>',NULL,4003,4003);
INSERT INTO stanza VALUES('E773','3','Shut in with Thee far, far above<br/>The restless world that wars below;<br/>We seek to learn and prove Thy love,<br/>Thy wisdom and Thy grace to know.<br/>',NULL,4004,4004);
INSERT INTO stanza VALUES('E773','4','The brow that once with thorns was bound,<br/>Thy hands, Thy side, we fain would see;<br/>Draw near, Lord Jesus, glory crowned,<br/>And bless us while we wait on Thee.<br/>',NULL,4005,4005);
INSERT INTO stanza VALUES('E774','1','From every stormy wind that blows,<br/>From every swelling tide of woes,<br/>There is a calm, a sure retreat-<br/>''Tis found beneath the mercy seat.<br/>',NULL,4006,4006);
INSERT INTO stanza VALUES('E774','2','There is a place where Jesus sheds<br/>The oil of gladness on our heads,<br/>A place than all besides more sweet-<br/>It is the blood-brought mercy seat.<br/>',NULL,4007,4007);
INSERT INTO stanza VALUES('E774','3','There is a scene where spirits blend,<br/>Where friend holds fellowship with friend;<br/>Though sundered far, by faith they meet<br/>Around one common mercy seat.<br/>',NULL,4008,4008);
INSERT INTO stanza VALUES('E774','4','There, there on eagle''s wings we soar,<br/>And time and sense seem all no more,<br/>And heaven comes down our souls to greet,<br/>And glory crowns the mercy seat.<br/>',NULL,4009,4009);
INSERT INTO stanza VALUES('E775','1','In the mighty Name of Jesus,<br/>When we bow before the throne,<br/>Many deadly foes are vanquished,<br/>Many victories are won.<br/>',NULL,4010,4010);
INSERT INTO stanza VALUES('E775','chorus','Mighty Name! Mighty Name!<br/>In that Name alone we win.<br/>Mighty Name! Mighty Name!<br/>Conquering Satan, death and sin.<br/>',NULL,4011,4011);
INSERT INTO stanza VALUES('E775','2','When we plead the Name of Jesus,<br/>Satan and His hosts must flee.<br/>Jesus! Jesus! Precious Jesus!<br/>In Thy Name is victory.<br/>',NULL,4012,4012);
INSERT INTO stanza VALUES('E775','3','Soon shall come the blessed moment<br/>When the battle shall be won,<br/>When the Mighty Name of Jesus<br/>Shall exalt us to the throne.<br/>',NULL,4013,4013);
INSERT INTO stanza VALUES('E776','1','"Ask in faith," the Name of Jesus<br/>All your plea before the throne;<br/>As you trust, the Lord will whisper,<br/>"See my child, the work is done."<br/>',NULL,4014,4014);
INSERT INTO stanza VALUES('E776','2','"Ask in faith," God waits to answer<br/>Each petition, Spirit-wrought;<br/>He will work in wondrous power,<br/>Far beyond your highest thought.<br/>',NULL,4015,4015);
INSERT INTO stanza VALUES('E776','3','"Ask in faith," ''tis just the asking,<br/>In faith that dares to stand,<br/>Full of joyful expectation,<br/>With an open, outstretched hand.<br/>',NULL,4016,4016);
INSERT INTO stanza VALUES('E776','4','"Ask in faith," for God is waiting<br/>For thy faith-filled, earnest prayer.<br/>Faith delights Him; faith can touch Him,<br/>Every moment, everywhere.<br/>',NULL,4017,4017);
INSERT INTO stanza VALUES('E777','1','Say to this mountain, "Go,<br/>Be cast into the sea!"<br/>And doubt not in thine heart<br/>That it shall be to thee.<br/>It shall be done, doubt not His Word,<br/>Command thy mountain in the Lord!<br/>',NULL,4018,4018);
INSERT INTO stanza VALUES('E777','2','Claim thy redemption right,<br/>Purchased by precious blood;<br/>The Trinity unite<br/>To make it true and good,<br/>It shall be done, obey the Word,<br/>Command thy mountain in the Lord!<br/>',NULL,4019,4019);
INSERT INTO stanza VALUES('E777','3','Self, sickness, sorrow, sin,<br/>The Lord did meet that day<br/>One His beloved One,<br/>And thou art "loosed away."<br/>It shall be done, rest on His Word!<br/>Command thy mountain in the Lord!<br/>',NULL,4020,4020);
INSERT INTO stanza VALUES('E777','4','Compass the frowning wall<br/>With silent prayer, then raise-<br/>Before its ramparts fall-<br/>The victor''s shout of praise.<br/>It shall be done, faith rests assured,<br/>Command thy mountain in the Lord!<br/>',NULL,4021,4021);
INSERT INTO stanza VALUES('E777','5','The two-leaved gates of brass,<br/>The bars of iron yield,<br/>To let the faithful pass,<br/>Conquerors in every field.<br/>It shall be done, the foe ignored,<br/>Command thy mountain in the Lord!<br/>',NULL,4022,4022);
INSERT INTO stanza VALUES('E777','6','Take then the faith of God,<br/>Free from the taint of doubt;<br/>The wonder-working rod<br/>That casts all reasoning out,<br/>It shall be done, stand on the Word.<br/>Command thy mountain in the Lord!<br/>',NULL,4023,4023);
INSERT INTO stanza VALUES('E778','1','Keep up the song of faith,<br/>However dark the night;<br/>And as you praise, the Lord will work<br/>To change your faith to sight.<br/>',NULL,4024,4024);
INSERT INTO stanza VALUES('E778','2','Keep up the song of faith,<br/>And let your heart be strong,<br/>For God delights when faith can praise<br/>Though dark the night and long.<br/>',NULL,4025,4025);
INSERT INTO stanza VALUES('E778','3','Keep up the song of faith,<br/>The foe will hear and flee;<br/>Oh, let not Satan hush your song,<br/>For praise is victory.<br/>',NULL,4026,4026);
INSERT INTO stanza VALUES('E778','4','Keep up the song of faith,<br/>The dawn will break ere long,<br/>And we shall go to meet the Lord,<br/>And join the endless song.<br/>',NULL,4027,4027);
INSERT INTO stanza VALUES('E779','1','Pray with one accord in spirit,<br/>Not according to our thought,<br/>But alone by the anointing,<br/>As the Lord has ever sought.<br/>',NULL,4028,4028);
INSERT INTO stanza VALUES('E779','chorus','Pray with one accord in spirit,<br/>Not according to our thought,<br/>But alone by the anointing,<br/>As the Lord has ever sought.<br/>',NULL,4029,4029);
INSERT INTO stanza VALUES('E779','2','Pray with one accord in spirit,<br/>By the cross deny the soul;<br/>All desires and all intentions<br/>Let the Spirit now control.<br/>',NULL,4030,4030);
INSERT INTO stanza VALUES('E779','3','Pray with one accord in spirit,<br/>Pray as in the heavenlies;<br/>All the earthly interests treading,<br/>Fight the principalities.<br/>',NULL,4031,4031);
INSERT INTO stanza VALUES('E779','4','Pray with one accord in spirit,<br/>Supplicate relatedly;<br/>Seek the Lord, His mind, His leading,<br/>In the Spirit''s harmony.<br/>',NULL,4032,4032);
INSERT INTO stanza VALUES('E779','5','Pray with one accord in spirit,<br/>Pray and watch persistently;<br/>For God''s kingdom and His glory,<br/>Pray and watch in harmony.<br/>',NULL,4033,4033);
INSERT INTO stanza VALUES('E779','6','Pray with one accord in spirit,<br/>Seeking God in unity;<br/>In the Spirit of the Body<br/>Ever pray in harmony.<br/>',NULL,4034,4034);
INSERT INTO stanza VALUES('E780','1','Praying always in the spirit,<br/>Never in the flesh or mind!<br/>If this secret we will practice,<br/>God''s full presence we will find.<br/>',NULL,4035,4035);
INSERT INTO stanza VALUES('E780','chorus','Praying always in the spirit,<br/>Is the secret we are told!<br/>In the spirit, God to contact,<br/>Is the secret we must hold!<br/>',NULL,4036,4036);
INSERT INTO stanza VALUES('E780','2','Praying always in the spirit,<br/>Never by our human thought!<br/>Fellowship with God the Spirit<br/>Only thus to us is brought.<br/>',NULL,4037,4037);
INSERT INTO stanza VALUES('E780','3','Praying always in the spirit,<br/>Thus expressing God''s desire;<br/>Staying with the Lord in spirit,<br/>We''ll be wholly set afire.<br/>',NULL,4038,4038);
INSERT INTO stanza VALUES('E780','4','Praying always in the spirit,<br/>Even groaning from within,<br/>Thus we utter God''s intention<br/>By the Spirit''s discipline.<br/>',NULL,4039,4039);
INSERT INTO stanza VALUES('E780','5','Praying always in the spirit,<br/>In the holiest place divine;<br/>It is only in the spirit<br/>God and we in oneness twine.<br/>',NULL,4040,4040);
INSERT INTO stanza VALUES('E780','6','Praying always in the spirit,<br/>''Tis the only way of prayer;<br/>All the fulness of the Godhead<br/>By this secret we may share.<br/>',NULL,4041,4041);
INSERT INTO stanza VALUES('E781','1','Exercise the spirit,<br/>Pray in every way!<br/>I have prayed too little,<br/>Keen my spirit, nay.<br/>Even when I prayed, my<br/>Spirit seldom proved<br/>Even just to follow<br/>As Thy Spirit moved.<br/>',NULL,4042,4042);
INSERT INTO stanza VALUES('E781','2','Now I''d pray in spirit<br/>As Thy Spirit groans;<br/>Pray by the anointing,<br/>Not as memory owns.<br/>Not the mind applying,<br/>But with spirit pray,<br/>Praising or beseeching,<br/>Spirit-led always.<br/>',NULL,4043,4043);
INSERT INTO stanza VALUES('E781','3','Not just by myself my<br/>Spirit exercise,<br/>But with others praying<br/>I would do likewise;<br/>Praying in the spirit,<br/>As the spirit wants,<br/>For ''tis in the inmost<br/>Spirits have response.<br/>',NULL,4044,4044);
INSERT INTO stanza VALUES('E781','4','When we serve together,<br/>We thru prayer would move,<br/>Fellowship in spirit,<br/>Not in word to prove.<br/>Never pray together,<br/>Shouting, crying much,<br/>Yet the fellowship in<br/>Spirit never touch.<br/>',NULL,4045,4045);
INSERT INTO stanza VALUES('E781','5','Exercise the spirit<br/>Here and everywhere,<br/>Few or many present,<br/>Caring not who''s there.<br/>Not a place or person<br/>Will influence me,<br/>In all kinds of meetings<br/>I''ll my spirit free.<br/>',NULL,4046,4046);
INSERT INTO stanza VALUES('E781','6','Thus my spirit lifted<br/>Gives the Lord His way;<br/>Thus, my spirit strengthened,<br/>I''ll be used each day.<br/>In the spirit''s flowing<br/>Living water see;<br/>Thus the saints are mingled,<br/>Built the church will be.<br/>',NULL,4047,4047);
INSERT INTO stanza VALUES('E782','1','How mysterious, O Lord,<br/>That Thy Spirit dwells in mine;<br/>O how marvelous it is,<br/>Into one, two spirits twine.<br/>',NULL,4048,4048);
INSERT INTO stanza VALUES('E782','2','By the spirit I can walk,<br/>Spiritual in spirit be;<br/>By the spirit I can serve,<br/>And in spirit worship Thee.<br/>',NULL,4049,4049);
INSERT INTO stanza VALUES('E782','3','Thru Thy Word and by my prayer<br/>In the spirit touching Thee,<br/>Lifted high my spirit is,<br/>Strengthened shall my spirit be.<br/>',NULL,4050,4050);
INSERT INTO stanza VALUES('E782','4','Make my spirit strong I pray<br/>Others'' spirits to revive;<br/>Lift my spirit high and free,<br/>Others'' spirits then may thrive.<br/>',NULL,4051,4051);
INSERT INTO stanza VALUES('E782','5','Every time I speak, O Lord,<br/>May my spirit actuate;<br/>And whatever I may do,<br/>Let my spirit motivate.<br/>',NULL,4052,4052);
INSERT INTO stanza VALUES('E782','6','Every time my spirit acts<br/>Others'' spirits opened be,<br/>Every time my spirit moves<br/>Others'' lifted unto Thee.<br/>',NULL,4053,4053);
INSERT INTO stanza VALUES('E782','7','Lord, have mercy, from above<br/>May Thy Spirit breathe on me;<br/>Then my spirit will be rich,<br/>Strengthened and refreshed by Thee.<br/>',NULL,4054,4054);
INSERT INTO stanza VALUES('E783','1','Pray to touch the throne of God,<br/>Touch the throne of grace divine,<br/>Grace to find and mercy too<br/>Which will meet the need of thine.<br/>',NULL,4055,4055);
INSERT INTO stanza VALUES('E783','2','Pray to touch the throne of God,<br/>Deeply sense thy need of grace;<br/>In the spirit stay with God,<br/>Fellowshipping face to face.<br/>',NULL,4056,4056);
INSERT INTO stanza VALUES('E783','3','Pray to touch the throne of God,<br/>Learning all the wealth of grace;<br/>Ever take and ever taste,<br/>Giving God the thanks and praise.<br/>',NULL,4057,4057);
INSERT INTO stanza VALUES('E783','4','Pray to touch the throne of God,<br/>Touch the throne of power too;<br/>In the name of Jesus Christ<br/>Deal with what you have to do.<br/>',NULL,4058,4058);
INSERT INTO stanza VALUES('E783','5','Pray to touch the throne of God<br/>By the hand of living faith;<br/>Exercise authority<br/>Over all the pow''r of death.<br/>',NULL,4059,4059);
INSERT INTO stanza VALUES('E783','6','Pray to touch the throne of God,<br/>Pray to shake the evil pow''r;<br/>Pray with kingship on the throne,<br/>Pray with Christ this very hour.<br/>',NULL,4060,4060);
INSERT INTO stanza VALUES('E784','1','Pray to fellowship with Jesus,<br/>In the spirit seek His face;<br/>Ask and listen in His presence,<br/>Waiting in the secret place.<br/>',NULL,4061,4061);
INSERT INTO stanza VALUES('E784','chorus','Pray to fellowship with Jesus,<br/>In the spirit seek His face;<br/>Ask and listen in His presence,<br/>Waiting in the secret place.<br/>',NULL,4062,4062);
INSERT INTO stanza VALUES('E784','2','Pray to fellowship with Jesus,<br/>Fully opened from within,<br/>With thy face unveiled, beholding,<br/>Single, pure, and genuine.<br/>',NULL,4063,4063);
INSERT INTO stanza VALUES('E784','3','Pray to fellowship with Jesus,<br/>Seeking Him in confidence;<br/>Learn to touch Him as the Spirit,<br/>Looking up in reverence.<br/>',NULL,4064,4064);
INSERT INTO stanza VALUES('E784','4','Pray to fellowship with Jesus,<br/>Speaking nothing in pretense;<br/>Ask according to the spirit,<br/>Praying by the inner sense.<br/>',NULL,4065,4065);
INSERT INTO stanza VALUES('E784','5','Pray to fellowship with Jesus,<br/>List''ning earnestly to Him;<br/>Be impressed with His intentions,<br/>Yielding to Him from within.<br/>',NULL,4066,4066);
INSERT INTO stanza VALUES('E784','6','Pray to fellowship with Jesus,<br/>Bathing in His countenance;<br/>Saturated with His beauty,<br/>Radiate His excellence.<br/>',NULL,4067,4067);
INSERT INTO stanza VALUES('E785','1','Praying to express the Lord,<br/>We must not ourselves express,<br/>But let Christ reveal Himself,<br/>His desire in us impress.<br/>',NULL,4068,4068);
INSERT INTO stanza VALUES('E785','2','Praying to express the Lord,<br/>We must utter His intent,<br/>Quieting our human thoughts<br/>That with His our mind be blent.<br/>',NULL,4069,4069);
INSERT INTO stanza VALUES('E785','3','Praying to express the Lord,<br/>Ever looking unto Him<br/>As a mirror to reflect<br/>All His glory from within.<br/>',NULL,4070,4070);
INSERT INTO stanza VALUES('E785','4','Praying to express the Lord,<br/>Letting Him beseech in us;<br/>Christ indwelling prays within<br/>To the Christ in heaven thus.<br/>',NULL,4071,4071);
INSERT INTO stanza VALUES('E785','5','Praying to express the Lord,<br/>Learning not to pray by self,<br/>Praying wholly with the Lord,<br/>Praying only by Himself.<br/>',NULL,4072,4072);
INSERT INTO stanza VALUES('E786','1','Pray to labor with the Lord,<br/>Pray to pave the way for Him;<br/>Pray to move Him and be moved<br/>From the center to the rim.<br/>',NULL,4073,4073);
INSERT INTO stanza VALUES('E786','2','Pray to labor with the Lord,<br/>Be identified with Him<br/>In His purpose and His aim<br/>Till His blessing floodeth in.<br/>',NULL,4074,4074);
INSERT INTO stanza VALUES('E786','3','Pray to labor with the Lord;<br/>Self-ambition and self-will<br/>We must ever cast away<br/>All His purpose to fulfill.<br/>',NULL,4075,4075);
INSERT INTO stanza VALUES('E786','4','Pray to labor with the Lord;<br/>Let the Lord initiate<br/>All the plan and all the work;<br/>Then thru us He''ll operate.<br/>',NULL,4076,4076);
INSERT INTO stanza VALUES('E786','5','Pray to labor with the Lord<br/>Till the wheel begins to move;<br/>Pray together with the Lord<br/>Till the Church His pow''r shall prove.<br/>',NULL,4077,4077);
INSERT INTO stanza VALUES('E787','1','I must tell Jesus all of my trials;<br/>I cannot bear these burdens alone;<br/>In my distress He kindly will help me;<br/>He ever loves and cares for His own.<br/>',NULL,4078,4078);
INSERT INTO stanza VALUES('E787','chorus','I must tell Jesus! I must tell Jesus!<br/>I cannot bear my burdens alone;<br/>I must tell Jesus! I must tell Jesus!<br/>Jesus can help me, Jesus alone.<br/>',NULL,4079,4079);
INSERT INTO stanza VALUES('E787','2','I must tell Jesus all of my troubles;<br/>He is a kind, compassionate Friend;<br/>If I ask Him, He will deliver,<br/>And in my griefs with me He will blend.<br/>',NULL,4080,4080);
INSERT INTO stanza VALUES('E787','3','Tempted and tried I need a great Savior,<br/>One who can help my burdens to bear;<br/>I must tell Jesus, I must tell Jesus;<br/>He all my cares and sorrows will share.<br/>',NULL,4081,4081);
INSERT INTO stanza VALUES('E787','4','O how the world to evil allures me!<br/>O how my heart is tempted to sin!<br/>I must tell Jesus; He will enable<br/>Over the world the vic''try to win.<br/>',NULL,4082,4082);
INSERT INTO stanza VALUES('E788','1','When thou wakest in the morning<br/>Ere thou tread''st the untried way<br/>Of the lot that lies before thee<br/>Through the coming busy day;<br/>Whether sunbeams promise brightness,<br/>Whether dim forebodings fall,<br/>Be thy dawning glad or gloomy,<br/>Go to Jesus, tell Him all.<br/>',NULL,4083,4083);
INSERT INTO stanza VALUES('E788','2','In the calm of sweet communion<br/>Let thy daily work be done;<br/>In the peace of soul-outpouring<br/>Care be banished, patience won;<br/>And if earth with its enchantments<br/>Seek the spirit to enthrall,<br/>Ere thou listen, ere thou answer,<br/>Turn to Jesus, tell Him all.<br/>',NULL,4084,4084);
INSERT INTO stanza VALUES('E788','3','Then, as hour by hour glides by thee,<br/>Thou will blessed guidance know,<br/>Thine own burdens being lightened,<br/>Thou canst bear another''s woe;<br/>Thou canst help the weak ones onward,<br/>Thou canst raise up those that fall:<br/>But remember, while thou servest,<br/>Still tell Jesus, tell Him all.<br/>',NULL,4085,4085);
INSERT INTO stanza VALUES('E788','4','And if weariness creeps o''er thee<br/>As the day wears to its close,<br/>Or if sudden fierce temptation<br/>Bring thee face to face with foes;<br/>In thy weakness, in thy peril,<br/>Raise to heaven a truthful call;<br/>Strength and calm for every crisis<br/>Come, in telling Jesus all.<br/>',NULL,4086,4086);
INSERT INTO stanza VALUES('E789','1','What a Friend we have in Jesus,<br/>All our sins and griefs to bear!<br/>What a privilege to carry<br/>Everything to God in prayer!<br/>O what peace we often forfeit,<br/>O what needless pain we bear,<br/>All because we do not carry<br/>Everything to God in prayer!<br/>',NULL,4087,4087);
INSERT INTO stanza VALUES('E789','2','Have we trials and temptations?<br/>Is there trouble anywhere?<br/>We should never be discouraged,<br/>Take it to the Lord in prayer.<br/>Can we find a friend so faithful<br/>Who will all our sorrows share?<br/>Jesus knows our every weakness,<br/>Take it to the Lord in prayer.<br/>',NULL,4088,4088);
INSERT INTO stanza VALUES('E789','3','Are we weak and heavy-laden,<br/>Cumbered with a load of care?<br/>Precious Savior, still our refuge-<br/>Take it to the Lord in prayer;<br/>Do thy friends despise, forsake thee?<br/>Take it to the Lord in prayer;<br/>In His arms He''ll take and shield thee,<br/>Thou wilt find a solace there.<br/>',NULL,4089,4089);
INSERT INTO stanza VALUES('E790','1','"Keep the incense burning"<br/>On the altar fire;<br/>Let thy heart''s petition,<br/>Let thy deep desire,<br/>Be a cloud of incense<br/>Wreathing God''s own throne,<br/>Till His will among us<br/>Shall be fully done.<br/>',NULL,4090,4090);
INSERT INTO stanza VALUES('E790','2','"Keep the incense burning"<br/>On the altar fire;<br/>Feed the flame, Lord Jesus,<br/>Till Thy whole desire<br/>Shall in us, Thy children,<br/>Find free course, and be<br/>Breathed through lips anointed<br/>For this ministry.<br/>',NULL,4091,4091);
INSERT INTO stanza VALUES('E790','3','"Keep the incense burning"<br/>Though the faith be weak;<br/>Though in words thou canst not<br/>All thy longings speak;<br/>Silent heart-petitions,<br/>Spirit-taught, will be<br/>Gloriously answered;<br/>Wrought by God for thee.<br/>',NULL,4092,4092);
INSERT INTO stanza VALUES('E790','4','"Keep the incense burning"<br/>Hourly let it rise,<br/>Till from opened heavens,<br/>Till from flame-swept skies,<br/>Fire shall fall and kindle<br/>All hearts to a flame;<br/>Making us a glory<br/>To our Savior''s name.<br/>',NULL,4093,4093);
INSERT INTO stanza VALUES('E791','1','The priest''s position holy is;<br/>He sacrifices e''er to God,<br/>Beholds His beauty, incense burns<br/>Of prayer before the Lord.<br/>',NULL,4094,4094);
INSERT INTO stanza VALUES('E791','chorus','Let us the incense burn<br/>Of prayer before the Lord;<br/>The lamp we''d light, through day and night<br/>Our praise to Him outpoured.<br/>',NULL,4095,4095);
INSERT INTO stanza VALUES('E791','2','No natural light, but just the lamp<br/>Within the holy place gives sight;<br/>Whene''er the priest the incense burns,<br/>The lamp he too must light.<br/>',NULL,4096,4096);
INSERT INTO stanza VALUES('E791','3','The grace of God let us extol<br/>And stir our heart sweet praise to sing;<br/>For priests not only light the lamp,<br/>But constant praises bring.<br/>',NULL,4097,4097);
INSERT INTO stanza VALUES('E791','4','I''ll offer prayers as incense burns,<br/>Christ''s resurrection bring therein,<br/>God''s wish thus meet, His heart give joy,<br/>And I''ll rejoice with Him.<br/>',NULL,4098,4098);
INSERT INTO stanza VALUES('E791','5','I''ll read His Word, His light receive,<br/>E''en as the lamp before Him lit,<br/>His holy light illum''ning me<br/>To others I''ll transmit.<br/>',NULL,4099,4099);
INSERT INTO stanza VALUES('E791','6','Unto the Lord His praise I''ll sing<br/>As holy priests their songs did raise;<br/>O may my heart be filled with Him<br/>His love and grace to praise.<br/>',NULL,4100,4100);
INSERT INTO stanza VALUES('E791','7','I''ll offer Christ to God in prayer,<br/>I''ll read the Word, His light to know,<br/>For all His grace I''ll sing His praise,<br/>The Spirit then may flow.<br/>',NULL,4101,4101);
INSERT INTO stanza VALUES('E792','1','Waiting on Thee, Lord, waiting on Thee;<br/>Let me now rest in Thee;<br/>Make Thy will clear to me,<br/>This is my earnest plea-<br/>Waiting on Thee, waiting on Thee.<br/>',NULL,4102,4102);
INSERT INTO stanza VALUES('E792','2','Waiting on Thee, Lord, waiting on Thee;<br/>While here with Thee I stay,<br/>Show me Thy glorious way,<br/>Ever by Thee to pray-<br/>Waiting on Thee, waiting on Thee.<br/>',NULL,4103,4103);
INSERT INTO stanza VALUES('E792','3','Waiting on Thee, Lord, waiting on Thee;<br/>Mingle Thyself with me,<br/>Till truly one with Thee<br/>Thine image I will be-<br/>Waiting on Thee, waiting on Thee.<br/>',NULL,4104,4104);
INSERT INTO stanza VALUES('E792','4','Waiting on Thee, Lord, waiting on Thee;<br/>Make me Thy will to know,<br/>Help me Thy way to go,<br/>That life thru me may flow-<br/>Waiting on Thee, waiting on Thee.<br/>',NULL,4105,4105);
INSERT INTO stanza VALUES('E792','5','Waiting on Thee, Lord, waiting on Thee;<br/>Make all my prayer to Thee<br/>Thyself expressed thru me,<br/>Give me Thy secret key-<br/>Waiting on Thee, waiting on Thee.<br/>',NULL,4106,4106);
INSERT INTO stanza VALUES('E793','1','My soul, be silent, wait upon the Lord!<br/>First let Him speak to thee, then speak to Him;<br/>True prayer in thee the Lord initiates,<br/>Thou but a channel art expressing Him.<br/>',NULL,4107,4107);
INSERT INTO stanza VALUES('E793','2','My soul, be silent, wait upon the Lord!<br/>Learn to deny thy thought and all thy will.<br/>Learn to let God anoint thee with Himself<br/>And thru thy prayer His purpose fulfill.<br/>',NULL,4108,4108);
INSERT INTO stanza VALUES('E793','3','My soul, be silent, wait upon the Lord!<br/>Silent to all thy wishes and thy plans,<br/>Silent to all thy earthly cares and calls,<br/>That God may work in thee all His demands.<br/>',NULL,4109,4109);
INSERT INTO stanza VALUES('E793','4','My soul, be silent, wait upon the Lord!<br/>Yield to the spirit all thy heart and mind;<br/>Here let the spirit show what God reveals,<br/>Thee its obedient servant thus to find.<br/>',NULL,4110,4110);
INSERT INTO stanza VALUES('E793','5','My soul, be silent, wait upon the Lord!<br/>Learn thus to let the Spirit pray thru thee;<br/>All of thy being with the Spirit move,<br/>Thy prayer will thus God''s own expression be.<br/>',NULL,4111,4111);
INSERT INTO stanza VALUES('E793','6','My soul, be silent, wait upon the Lord!<br/>Till in the spirit thou with God art one,<br/>Till thru the spirit God possesses all<br/>And thus transforms each part unto His Son.<br/>',NULL,4112,4112);
INSERT INTO stanza VALUES('E793','7','My soul, be silent, wait upon the Lord!<br/>Till God may freely, fully flow thru thee,<br/>Till all thy words and actions hour by hour<br/>Are the fulfillment of God''s will thru thee.<br/>',NULL,4113,4113);
INSERT INTO stanza VALUES('E794','1','Stir, me oh, stir me, Lord, I care not how,<br/>But stir my heart in passion for the world,<br/>Stir me to give, to go, but most to pray;<br/>Stir till the blood-red banner be unfurled<br/>O''er lands that still in heathen darkness lie,<br/>O''er deserts where no cross is lifted high.<br/>',NULL,4114,4114);
INSERT INTO stanza VALUES('E794','2','Stir, me oh, stir me, Lord, till all my heart<br/>Is filled with strong compassion for these souls;<br/>Till Thy compelling word drives me to pray;<br/>Till Thy constraining love reach to the poles<br/>Far north and south, in burning deep desire,<br/>Till east and west are caught in love''s great fire.<br/>',NULL,4115,4115);
INSERT INTO stanza VALUES('E794','3','Stir, me oh, stir me, Lord, till prayer is pain,<br/>Till prayer is joy, till prayer turns into praise;<br/>Stir me, till heart and will and mind, yea, all<br/>Is wholly Thine to use through all the days.<br/>Stir, till I learn to pray exceedingly;<br/>Stir, till I learn to wait expectantly.<br/>',NULL,4116,4116);
INSERT INTO stanza VALUES('E794','4','Stir, me oh, stir me, Lord, Thy heart was stirred<br/>By love''s intensest fire, till Thou didst give<br/>Thine only Son, Thy best beloved One,<br/>E''en to the dreadful cross, that I might live.<br/>Stir me to give myself so back to Thee,<br/>That Thou canst give Thyself again through me.<br/>',NULL,4117,4117);
INSERT INTO stanza VALUES('E794','5','Stir, me oh, stir me, Lord, for I can see<br/>Thy glorious triumph-day begin to break;<br/>The dawn already gilds the eastern sky;<br/>Oh, Church of Christ, arise, awake, awake.<br/>Oh! Stir us, Lord, as heralds of that day.<br/>For night is past, our King is on His way.<br/>',NULL,4118,4118);
INSERT INTO stanza VALUES('E795','1','Father, let Thy kingdom come,<br/>Let it come with living power;<br/>Speak at length the final word,<br/>Usher in the triumph hour.<br/>',NULL,4119,4119);
INSERT INTO stanza VALUES('E795','2','As it came in days of old,<br/>In the deepest hearts of men,<br/>When Thy martyrs died for Thee,<br/>Let it come, O God, again.<br/>',NULL,4120,4120);
INSERT INTO stanza VALUES('E795','3','Tyrant thrones and idol shrines,<br/>Let them from their place be hurled;<br/>Enter on Thy better reign,<br/>Wear the crown of this poor world.<br/>',NULL,4121,4121);
INSERT INTO stanza VALUES('E795','4','Oh, what long, sad years have gone,<br/>Since Thy Church was taught this prayer;<br/>Oh, what eyes have watched and wept<br/>For the dawning everywhere.<br/>',NULL,4122,4122);
INSERT INTO stanza VALUES('E795','5','Break, triumphant day of God!<br/>Break at last our hearts to cheer;<br/>Throbbing souls and holy songs<br/>Wait to hail Thy dawning here.<br/>',NULL,4123,4123);
INSERT INTO stanza VALUES('E795','6','Empires, temples, scepters, thrones,<br/>May they all for God be won;<br/>And, in every human heart,<br/>Father, let Thy kingdom come.<br/>',NULL,4124,4124);
INSERT INTO stanza VALUES('E796','1','Christ, from whom all blessings flow,<br/>Perfecting the saints below,<br/>Hear us, who Thy nature share,<br/>Who Thy mystic body are.<br/>',NULL,4125,4125);
INSERT INTO stanza VALUES('E796','2','Join us, in one spirit join,<br/>Let us still receive of Thine;<br/>Still for more on Thee we call,<br/>Thou who fillest all in all.<br/>',NULL,4126,4126);
INSERT INTO stanza VALUES('E796','3','Move, and actuate, and guide:<br/>Divers gifts to each divide;<br/>Placed according to Thy will,<br/>Let us all our work fulfill.<br/>',NULL,4127,4127);
INSERT INTO stanza VALUES('E796','4','Sweetly may we all agree,<br/>Touched with loving sympathy;<br/>Kindly for each other care,<br/>Every member feel its share.<br/>',NULL,4128,4128);
INSERT INTO stanza VALUES('E796','5','Love, like death, hath all destroyed,<br/>Rendered all distinctions void;<br/>Name, and sects, and parties fall:<br/>Thou, O Christ, art all in all.<br/>',NULL,4129,4129);
INSERT INTO stanza VALUES('E797','1','Revive Thy work, O Lord!<br/>Now to Thy saints appear!<br/>Oh, speak with power to every soul,<br/>And let Thy people hear!<br/>',NULL,4130,4130);
INSERT INTO stanza VALUES('E797','chorus','Revive Thy work, O Lord!<br/>While here to Thee we bow;<br/>Descend, O gracious Lord, descend!<br/>Oh, come, and bless us now!<br/>',NULL,4131,4131);
INSERT INTO stanza VALUES('E797','2','Revive Thy work, O Lord!<br/>And every soul inspire;<br/>Oh, kindle in each heart, we pray,<br/>The Pentecostal fire!<br/>',NULL,4132,4132);
INSERT INTO stanza VALUES('E797','3','Revive Thy work, O Lord!<br/>Exalt Thy precious name!<br/>And may Thy love in every heart<br/>Be kindled to a flame!<br/>',NULL,4133,4133);
INSERT INTO stanza VALUES('E797','4','Revive Thy work, O Lord!<br/>And bless to all Thy Word!<br/>And may its pure and sacred truth<br/>In living faith be heard!<br/>',NULL,4134,4134);
INSERT INTO stanza VALUES('E797','5','Revive Thy work, O Lord!<br/>And make Thy servant bold;<br/>Convict of sin and work once more<br/>As in the days of old.<br/>',NULL,4135,4135);
INSERT INTO stanza VALUES('E797','6','Revive Thy work, O Lord!<br/>Give Pentecostal showers!<br/>Be Thine the glory, Thine alone!<br/>The blessing, Lord, be ours!<br/>',NULL,4136,4136);
INSERT INTO stanza VALUES('E798','1','Revive Thy work, dear Lord!<br/>Thy mighty arm make bare;<br/>Move in the hearts and wake the souls,<br/>And make Thy presence dear.<br/>',NULL,4137,4137);
INSERT INTO stanza VALUES('E798','chorus','Revive Thy work, dear Lord!<br/>And manifest Thy power;<br/>O come upon Thy church as in<br/>The Pentecostal hour.<br/>',NULL,4138,4138);
INSERT INTO stanza VALUES('E798','2','Revive Thy work, dear Lord!<br/>Disturb this sleep of death;<br/>Quicken the smoldering embers now<br/>By Thine almighty breath.<br/>',NULL,4139,4139);
INSERT INTO stanza VALUES('E798','3','Revive Thy work, dear Lord!<br/>Create soul-thirst for Thee;<br/>And hungering for the Bread of Life,<br/>O may our spirits be!<br/>',NULL,4140,4140);
INSERT INTO stanza VALUES('E798','4','Revive Thy work, dear Lord!<br/>And give abounding joy;<br/>O fill our heart with perfect love,<br/>And burn out all alloy!<br/>',NULL,4141,4141);
INSERT INTO stanza VALUES('E798','5','Revive Thy work, dear Lord!<br/>Repeat Thy deeds of grace;<br/>Thy mighty name be magnified,<br/>To Thee be all the praise.<br/>',NULL,4142,4142);
INSERT INTO stanza VALUES('E799','1','All Scripture is the very breath of God,<br/>And by His Spirit into words was breathed;<br/>By godly men the words were written down,<br/>With all God''s fulness unto man bequeathed.<br/>',NULL,4143,4143);
INSERT INTO stanza VALUES('E799','2','It is the breath of God as light to man,<br/>With rays divine man to illuminate;<br/>It shines in darkness and to man reveals.<br/>What is his truest need and actual state.<br/>',NULL,4144,4144);
INSERT INTO stanza VALUES('E799','3','It is the breath of God as life to man,<br/>Nature divine to man it doth impart;<br/>The dead it quickens and regenerates,<br/>Transforms the soul-life and renews the heart.<br/>',NULL,4145,4145);
INSERT INTO stanza VALUES('E799','4','It is the breath of God as wisdom too,<br/>Knowledge divine to man it has to teach;<br/>Th'' eternal purpose of the Lord it shows,<br/>And leadeth man God''s final goal to reach.<br/>',NULL,4146,4146);
INSERT INTO stanza VALUES('E799','5','It is the breath of God as strength to man,<br/>Power divine to man it doth transmit,<br/>Strength''ning the weak, empowering the faint,<br/>Enabling man God''s purpose full to fit.<br/>',NULL,4147,4147);
INSERT INTO stanza VALUES('E799','6','It is the breath of God for us to breathe,<br/>That as our portion God we may enjoy;<br/>Receiving it by spirits exercised,<br/>Our need is met, His wealth we may employ.<br/>',NULL,4148,4148);
INSERT INTO stanza VALUES('E800','1','God the Lord has spoken, God has been unveiled;<br/>All His character and persons are expressed;<br/>Unto Adam''s sons His mystery is revealed,<br/>Fully illustrated and made manifest.<br/>',NULL,4149,4149);
INSERT INTO stanza VALUES('E800','2','God the Lord has spoken, and His heart disclosed,<br/>That His Son should have pre-eminence in all,<br/>That in His dear Son He might be glorified<br/>Midst all His creation, either great or small.<br/>',NULL,4150,4150);
INSERT INTO stanza VALUES('E800','3','God the Lord has spoken, Christ has been revealed;<br/>He is very God and yet is truly man;<br/>He is all in all, in Him all things subsist,<br/>Center and circumference of th'' eternal plan.<br/>',NULL,4151,4151);
INSERT INTO stanza VALUES('E800','4','God the Lord has spoken, and His mystery shown,<br/>Christ and His expression has His counsel willed:<br/>Christ with all God''s fulness as the glorious Head,<br/>And the Church His Body, with His riches filled.<br/>',NULL,4152,4152);
INSERT INTO stanza VALUES('E800','5','God the Lord has spoken, and from heaven shown<br/>The triune God would blend with creature-man:<br/>Father in the Son, the Son the Spirit is,<br/>Dwelling in the Body to fulfill His plan.<br/>',NULL,4153,4153);
INSERT INTO stanza VALUES('E800','6','God the Lord has spoken, revelation giv''n<br/>Of His vast creation and His lowly birth,<br/>Of His great redemption and salvation full;<br/>May His adoration ever fill the earth.<br/>',NULL,4154,4154);
INSERT INTO stanza VALUES('E801','1','O living Word of God, God''s image true,<br/>Thou art the content of God''s written word;<br/>God in Thee we have met, God''s fulness found,<br/>And in the Scripture we Thyself have heard.<br/>',NULL,4155,4155);
INSERT INTO stanza VALUES('E801','2','No man has e''er seen God, apart from Thee,<br/>Without the Scripture Thee we''d hardly see;<br/>Thou to the human race God hast declared,<br/>And thru the Scripture Thou art shown to me.<br/>',NULL,4156,4156);
INSERT INTO stanza VALUES('E801','3','Perfect embodiment Thou art of God,<br/>A portrait full the Scripture gives of Thee;<br/>In Thee we comprehend God''s image true,<br/>And thru the Scripture Thou art real to me.<br/>',NULL,4157,4157);
INSERT INTO stanza VALUES('E801','4','Life-giving Spirit Thou, as well as Word,<br/>Now e''en the Spirit in the Word Thou art;<br/>When thru the Spirit giv''n, I touch the Word,<br/>Fulness divine to me Thou dost impart.<br/>',NULL,4158,4158);
INSERT INTO stanza VALUES('E801','5','In Thee I may with God have fellowship,<br/>And thru the Scripture I on Thee may feed;<br/>Thru study of the Word with prayer to God<br/>Thy glorious riches fully meet my need.<br/>',NULL,4159,4159);
INSERT INTO stanza VALUES('E801','6','Teach me to exercise my spirit, Lord,<br/>Thy word to study, so to contact Thee,<br/>That Thou, the living Word, with Scripture, too,<br/>As one my daily manna e''er may be.<br/>',NULL,4160,4160);
INSERT INTO stanza VALUES('E802','1','Thou art the Word and Spirit, Lord;<br/>Now in one spirit worship we;<br/>''Tis by the Word we understand,<br/>And in the Spirit contact Thee.<br/>',NULL,4161,4161);
INSERT INTO stanza VALUES('E802','2','Since Thou with me has joined in one,<br/>Thou art my all, O Lord, thereby;<br/>And as the Spirit and the Word<br/>Thou cam''st to me as my supply.<br/>',NULL,4162,4162);
INSERT INTO stanza VALUES('E802','3','If Thou art Lord, yet not the Word,<br/>How couldest Thou be known to me?<br/>If Thou art God yet Spirit not,<br/>How could I ever contact Thee?<br/>',NULL,4163,4163);
INSERT INTO stanza VALUES('E802','4','The Word reveals Thyself to me<br/>And knowledge of Thyself imparts;<br/>The Spirit is Thy substance true<br/>Whereby I touch Thee as Thou art.<br/>',NULL,4164,4164);
INSERT INTO stanza VALUES('E802','5','Thou art my life, my light, my way,<br/>My food, my strength and guaranty;<br/>By Word made known, as Spirit these<br/>Become experience to me.<br/>',NULL,4165,4165);
INSERT INTO stanza VALUES('E802','6','The Word in Scripture is expressed,<br/>Thy Spirit, the Indwelling One;<br/>Thy Word is spirit and is life<br/>When to my spirit it doth come.<br/>',NULL,4166,4166);
INSERT INTO stanza VALUES('E802','7','If I Thy Word would understand,<br/>I must Thy Holy Spirit touch;<br/>Not only grasp it with my mind,<br/>But with my spirit it doth come.<br/>',NULL,4167,4167);
INSERT INTO stanza VALUES('E802','8','Thy precious Word my heart doth love,<br/>My spirit fellowships with Thine;<br/>My heart rejoices in Thy Word,<br/>My spirit praises sings in Thine.<br/>',NULL,4168,4168);
INSERT INTO stanza VALUES('E803','1','O Word of God incarnate,<br/>O Wisdom from on high,<br/>O Truth unchanged, unchanging,<br/>O Light of our dark sky,<br/>We praise Thee for the radiance<br/>That from the hallowed page,<br/>A lantern to the footsteps,<br/>Shines on from age to age.<br/>',NULL,4169,4169);
INSERT INTO stanza VALUES('E803','2','The Church from her dear Master<br/>Received the gift divine,<br/>And still that light she lifteth<br/>O''er all the earth to shine:<br/>It is the golden treasure<br/>Where gems of truth are stored;<br/>It is the heaven-drawn picture<br/>Of Christ, the living Word.<br/>',NULL,4170,4170);
INSERT INTO stanza VALUES('E803','3','It floateth like a banner<br/>Before God''s host unfurled;<br/>It shineth like a beacon<br/>Above the darkling world;<br/>It is the chart and compass<br/>That, o''er life''s surging sea,<br/>''Mid mists and rocks and quicksands<br/>Still guide, O Christ, to Thee.<br/>',NULL,4171,4171);
INSERT INTO stanza VALUES('E803','4','O make Thy Church, dear Savior,<br/>A lamp stand of pure gold,<br/>To bear before the nations<br/>Thy light, that all behold;<br/>O teach Thy wandering pilgrims<br/>By this their path to trace,<br/>Till, clouds and darkness ended,<br/>They see Thee face to face.<br/>',NULL,4172,4172);
INSERT INTO stanza VALUES('E804','1','Thy Word is like a storehouse, Lord,<br/>With full provision there,<br/>And everyone who seeks may come,<br/>Its glorious wealth to share.<br/>Thy Word is like a deep, deep mine,<br/>And jewels rich and rare<br/>Are hidden in its mighty depths<br/>For every searcher there.<br/>',NULL,4173,4173);
INSERT INTO stanza VALUES('E804','2','Thy Word is like a starry host:<br/>A thousand rays of light<br/>Are seen to guide the traveler,<br/>And make his pathway bright.<br/>Thy Word is like an armory,<br/>Where soldiers may repair,<br/>And find, for life''s long battle day,<br/>All needful weapons there.<br/>',NULL,4174,4174);
INSERT INTO stanza VALUES('E804','3','O may I love Thy precious Word,<br/>May I explore the mine,<br/>May I its glorious riches take,<br/>May light upon me shine.<br/>O may I find my armor there,<br/>Thy Word my trusty sword;<br/>I''ll learn to fight with every foe<br/>The battle of the Lord.<br/>',NULL,4175,4175);
INSERT INTO stanza VALUES('E804','4','Word of the ever living God,<br/>Will of His glorious Son;<br/>Without Thee how could earth be trod,<br/>Or God and Christ be won?<br/>Lord, grant us all aright to learn<br/>The wisdom it imparts,<br/>And to its heav''nly teaching turn,<br/>With simple, child-like hearts.<br/>',NULL,4176,4176);
INSERT INTO stanza VALUES('E805','1','Oh, how I love this blessed Book!<br/>The story of redeeming grace,<br/>Love letter of my Bridegroom''s heart<br/>And mirror of my Savior''s face.<br/>',NULL,4177,4177);
INSERT INTO stanza VALUES('E805','2','Oh, how I love this blessed Book!<br/>My checkbook on the bank above,<br/>Deed of my heavenly heritage<br/>And dying will of Him I love.<br/>',NULL,4178,4178);
INSERT INTO stanza VALUES('E805','3','Oh, how I love this blessed Book!<br/>Bright telescope through which I view<br/>The wonders of the world to come<br/>And gaze on glories ever new.<br/>',NULL,4179,4179);
INSERT INTO stanza VALUES('E805','4','Oh, how I love this blessed Book!<br/>My Guide Book all my earthly way,<br/>The lamp that cheers my darkest night,<br/>The sunshine of my brightest day.<br/>',NULL,4180,4180);
INSERT INTO stanza VALUES('E806','1','Break Thou the Bread of Life,<br/>Dear Lord, to me,<br/>As Thou didst break the loaves<br/>Beside the sea;<br/>Beyond the sacred page<br/>I seek Thee, Lord;<br/>My spirit pants for Thee,<br/>O Living Word.<br/>',NULL,4181,4181);
INSERT INTO stanza VALUES('E806','2','Thou art the Bread of Life,<br/>O Lord, to me,<br/>Thy holy Word the truth<br/>That saveth me;<br/>Give me to eat and live<br/>With Thee above;<br/>Teach me to love Thy truth,<br/>For Thou art Love.<br/>',NULL,4182,4182);
INSERT INTO stanza VALUES('E806','3','Oh, send Thy Spirit, Lord,<br/>Now unto me,<br/>That He may touch my eyes,<br/>And make me see;<br/>Show me the truth concealed<br/>Within Thy Word,<br/>And in Thy Book revealed<br/>I see the Lord.<br/>',NULL,4183,4183);
INSERT INTO stanza VALUES('E806','4','Bless Thou the truth, dear Lord,<br/>To me, to me,<br/>As Thou didst bless the bread<br/>By Galilee;<br/>Then shall all bondage cease,<br/>All fetters fall,<br/>And I shall find my peace,<br/>My All in all.<br/>',NULL,4184,4184);
INSERT INTO stanza VALUES('E807','1','Open my eyes that I may see<br/>Glimpses of truth Thou hast for me;<br/>Place in my hands the wonderful key<br/>That shall unclasp and set me free.<br/>',NULL,4185,4185);
INSERT INTO stanza VALUES('E807','chorus','Silently now I wait for Thee,<br/>Ready, my God, Thy will to see;<br/>Open my eyes, illumine me,<br/>Spirit Divine!<br/>',NULL,4186,4186);
INSERT INTO stanza VALUES('E807','2','Open my ears that I may hear<br/>Voices of truth Thou sendest clear;<br/>And while the wave notes fall on my ear,<br/>Everything false will disappear.<br/>',NULL,4187,4187);
INSERT INTO stanza VALUES('E807','3','Open my mouth and let me bear<br/>Tidings of mercy everywhere;<br/>Open my heart and let me prepare<br/>Love with Thy children thus to share.<br/>',NULL,4188,4188);
INSERT INTO stanza VALUES('E807','4','Open my mind that I may read<br/>More of Thy love in word and deed;<br/>What shall I fear while yet Thou dost lead?<br/>Only for light from Thee I plead.<br/>',NULL,4189,4189);
INSERT INTO stanza VALUES('E808','1','Master, speak! Thy servant heareth,<br/>Waiting for Thy gracious word,<br/>Longing for Thy voice that cheereth,<br/>Master, let it now be heard.<br/>I am list''ning, Lord, for Thee;<br/>What hast Thou to say to me?<br/>',NULL,4190,4190);
INSERT INTO stanza VALUES('E808','2','Often through my heart is pealing<br/>Many another voice than Thine,<br/>Many and unwilled echo stealing<br/>From the walls of this Thy shrine.<br/>Let Thy longed-for accents fall;<br/>Master, speak! And silence all.<br/>',NULL,4191,4191);
INSERT INTO stanza VALUES('E808','3','Master speak! Though least and lowest,<br/>Let me not unheard depart;<br/>Master, speak! For oh, Thou knowest<br/>All the yearning of my heart.<br/>Knowest all its truest need;<br/>Speak! And make me blest indeed.<br/>',NULL,4192,4192);
INSERT INTO stanza VALUES('E808','4','Master speak! And make me ready,<br/>When Thy voice is truly heard,<br/>With obedience glad and steady,<br/>Still to follow every word,<br/>I am listening, Lord, for Thee:<br/>Master, speak, oh, speak to me!<br/>',NULL,4193,4193);
INSERT INTO stanza VALUES('E808','5','Speak to me by name, O Master,<br/>Let me know it is to me;<br/>Speak, that I may follow faster,<br/>With a step more firm and free,<br/>Where the Shepherd leads the flock,<br/>In the shadow of the Rock!<br/>',NULL,4194,4194);
INSERT INTO stanza VALUES('E809','1','Speak, Lord, in the stillness,<br/>While I wait on Thee;<br/>Hushed my heart to listen,<br/>In expectancy.<br/>',NULL,4195,4195);
INSERT INTO stanza VALUES('E809','2','Speak, O blessed Master,<br/>In this quiet hour;<br/>Let me see Thy face, Lord,<br/>Feel Thy touch of power.<br/>',NULL,4196,4196);
INSERT INTO stanza VALUES('E809','3','For the words Thou speakest,<br/>They are life indeed;<br/>Living bread from heaven,<br/>Now my spirit feed!<br/>',NULL,4197,4197);
INSERT INTO stanza VALUES('E809','4','All to Thee is yielded,<br/>I am not my own;<br/>Blissful, glad surrender,<br/>I am Thine alone.<br/>',NULL,4198,4198);
INSERT INTO stanza VALUES('E809','5','Speak, Thy servant heareth,<br/>Be not silent, Lord;<br/>Waits my soul upon Thee<br/>For the quickening word.<br/>',NULL,4199,4199);
INSERT INTO stanza VALUES('E809','6','Fill me with the knowledge<br/>Of Thy glorious will;<br/>All Thine own good pleasure<br/>In Thy child fulfill.<br/>',NULL,4200,4200);
INSERT INTO stanza VALUES('E809','7','Like a watered garden,<br/>Full of fragrance rare,<br/>Lingering in Thy presence,<br/>Let my life appear.<br/>',NULL,4201,4201);
INSERT INTO stanza VALUES('E810','1','Lord, hast Thou not one word for me<br/>To bind my soul more close to Thee,<br/>That every evil I may flee;<br/>One word, O Lord! One word from Thee?<br/>',NULL,4202,4202);
INSERT INTO stanza VALUES('E810','2','One word, to show how weak am I<br/>When in my strength alone I try,<br/>In vain I toil, in vain I sigh;<br/>One word, O Lord! One word from Thee.<br/>',NULL,4203,4203);
INSERT INTO stanza VALUES('E810','3','One word, to show how near Thou art,<br/>For Thou dost dwell within my heart;<br/>And for Thy life I share a part;<br/>One word, O Lord! One word from Thee.<br/>',NULL,4204,4204);
INSERT INTO stanza VALUES('E810','4','One word of power, oh, let me hear,<br/>Above the heart''s most anxious fear,<br/>Thy still, small voice, yet deep and clear;<br/>One word, O Lord! One word from Thee.<br/>',NULL,4205,4205);
INSERT INTO stanza VALUES('E810','5','One word of final triumph, Lord;<br/>Sweet hope Thy promises afford,<br/>To dwell with Thee in sweet accord;<br/>One word, O Lord! One word from Thee.<br/>',NULL,4206,4206);
INSERT INTO stanza VALUES('E811','1','My heart is hungry, my spirit doth thirst;<br/>I come to Thee, Lord, to seek Thy supply;<br/>All that I need is none other but Thee,<br/>Thou canst my hunger and thirst satisfy.<br/>',NULL,4207,4207);
INSERT INTO stanza VALUES('E811','chorus','Feed me, Lord Jesus, give me to drink,<br/>Fill all my hunger, quench all my thirst;<br/>Flood me with joy, be the strength of my life,<br/>Fill all my hunger, quench all my thirst.<br/>',NULL,4208,4208);
INSERT INTO stanza VALUES('E811','2','Thou art the food and the water of life,<br/>Thou canst revive me, my spirit upbear;<br/>I long to eat and to drink here of Thee,<br/>Thyself enjoy through my reading and prayer.<br/>',NULL,4209,4209);
INSERT INTO stanza VALUES('E811','3','Thou art the Word with God''s fulness in Thee,<br/>Thou too the Spirit that God my life be;<br/>Thee in the Word I enjoy as my food,<br/>Thou as the Spirit art water to me.<br/>',NULL,4210,4210);
INSERT INTO stanza VALUES('E811','4','Thou from the heavens as food camest down,<br/>Thou to be drink hast been smitten for me;<br/>Thou as the food, my exhaustless supply,<br/>Thou as the water, a stream unto me.<br/>',NULL,4211,4211);
INSERT INTO stanza VALUES('E811','5','Thou in the Word art the Spirit and life,<br/>Thus by the Word I may feed upon Thee;<br/>Thou dost as Spirit in my spirit live,<br/>Thus I may drink in the spirit of Thee.<br/>',NULL,4212,4212);
INSERT INTO stanza VALUES('E811','6','Now to enjoy Thee I come to Thy Word,<br/>On Thee to feed till my hunger is o''er.<br/>Now in my spirit I turn unto Thee,<br/>Of Thee to drink till I''m thirsty no more.<br/>',NULL,4213,4213);
INSERT INTO stanza VALUES('E812','1','I come to Thee, dear Lord,<br/>My heart doth thirst for Thee;<br/>Of Thee I''d eat, of Thee I''d drink,<br/>Enjoy Thee thoroughly.<br/>',NULL,4214,4214);
INSERT INTO stanza VALUES('E812','2','Just to behold Thy face,<br/>For this my heart doth cry;<br/>I deeply long to drink of Thee<br/>My thirst to satisfy.<br/>',NULL,4215,4215);
INSERT INTO stanza VALUES('E812','3','Thy glorious, radiant face<br/>My heart delights to see;<br/>Here I''d abide and ne''er depart,<br/>Beholding constantly.<br/>',NULL,4216,4216);
INSERT INTO stanza VALUES('E812','4','In such a fellowship<br/>Thou, Lord, art grace to me;<br/>My heart and spirit gladdened, filled,<br/>I enter rest in Thee.<br/>',NULL,4217,4217);
INSERT INTO stanza VALUES('E812','5','Lord, I would linger here,<br/>Still seeking after Thee,<br/>Continue in the Word and prayer<br/>Till Thou dost flow thru me.<br/>',NULL,4218,4218);
INSERT INTO stanza VALUES('E813','1','I come before Thy throne of grace<br/>With hungry heart on Thee to feed,<br/>Thy grace and mercy to receive<br/>To help me in this hour of need.<br/>',NULL,4219,4219);
INSERT INTO stanza VALUES('E813','2','Here I behold Thy radiant face,<br/>Its light upon my heart doth shine<br/>With healing rays consuming all<br/>The weakness and faults of mine.<br/>',NULL,4220,4220);
INSERT INTO stanza VALUES('E813','3','''Tis here Thy light illuminates<br/>My true condition unto me;<br/>''Tis here Thy blood''s effectiveness<br/>To cleanse from sin I gladly see.<br/>',NULL,4221,4221);
INSERT INTO stanza VALUES('E813','4','Thy Spirit too anoints me here<br/>And makes Thy very substance mine;<br/>Thy very self I thus enjoy<br/>And know Thy very heart''s design.<br/>',NULL,4222,4222);
INSERT INTO stanza VALUES('E813','5','Thy Word I read before Thee here<br/>E''en as the priests the lamp did light;<br/>Thy Spirit is as oil to me<br/>To light Thy Word and give me sight.<br/>',NULL,4223,4223);
INSERT INTO stanza VALUES('E813','6','E''en as the priests the incense burned,<br/>In prayer to Thee I persevere;<br/>As incense Thou the Spirit art<br/>Mixed with the prayer I offer here.<br/>',NULL,4224,4224);
INSERT INTO stanza VALUES('E813','7','Thy Word is light, Thy Word is food;<br/>Which doth enlighten and supply;<br/>I long to read and feed much more,<br/>For light and food to satisfy.<br/>',NULL,4225,4225);
INSERT INTO stanza VALUES('E813','8','Thou art the living water too<br/>Which full revival doth bestow;<br/>I wish to pray and drink e''en more<br/>That through me living rivers flow.<br/>',NULL,4226,4226);
INSERT INTO stanza VALUES('E813','9','Thou art the incense unto God,<br/>In Thee acceptance is complete;<br/>I want to pray yet more and more,<br/>To offer up this fragrance sweet.<br/>',NULL,4227,4227);
INSERT INTO stanza VALUES('E813','10','By reading I''m enlightened, filled,<br/>By prayer my thirst is quenched indeed;<br/>Thus Thou to me may be supplied,<br/>And Thou through me may meet the need.<br/>',NULL,4228,4228);
INSERT INTO stanza VALUES('E813','11','I long to have such fellowship,<br/>To read and pray and blend with Thee;<br/>I long that Thou wouldst saturate<br/>Till Thou may overflow from me.<br/>',NULL,4229,4229);
INSERT INTO stanza VALUES('E814','1','"Man shall not live by bread alone,<br/>But by each word which doth proceed<br/>From God''s own mouth"; these we must eat<br/>And let them be our life indeed.<br/>',NULL,4230,4230);
INSERT INTO stanza VALUES('E814','2','Not just a body we were made,<br/>But body, soul, and spirit too;<br/>The inmost part the spirit is<br/>To contact God and Him pursue.<br/>',NULL,4231,4231);
INSERT INTO stanza VALUES('E814','3','Just as we need the earthly food<br/>Our body''s need to satisfy,<br/>We need the food for spirit too-<br/>Thyself, Thy Word, its true supply.<br/>',NULL,4232,4232);
INSERT INTO stanza VALUES('E814','4','Thou art the Spirit, and Thy Word<br/>Thy very Self expressed doth make;<br/>Thus, it is Spirit as Thyself,<br/>Which by our spirit we must take.<br/>',NULL,4233,4233);
INSERT INTO stanza VALUES('E814','5','Thus, to receive Thy Word is not<br/>To read it only with our eyes<br/>And understand it in our mind,<br/>But ''tis the spirit''s exercise.<br/>',NULL,4234,4234);
INSERT INTO stanza VALUES('E814','6','Thy Word in spirit we must eat<br/>And to our inmost part receive;<br/>''Tis by our spirit''s exercise<br/>To pray with what our minds perceive.<br/>',NULL,4235,4235);
INSERT INTO stanza VALUES('E814','7','Thy Word remaining in our mind<br/>Is only knowledge burdensome,<br/>But when it to the spirit goes<br/>Then life and spirit it becomes.<br/>',NULL,4236,4236);
INSERT INTO stanza VALUES('E814','8','''Tis only when our spirit acts<br/>To take Thy Word and contact Thee,<br/>We truly feed upon Thy Word<br/>And touch Thyself most inwardly.<br/>',NULL,4237,4237);
INSERT INTO stanza VALUES('E814','9','Lord, teach us how to exercise<br/>Our spirit when Thy Word we read;<br/>Then will our spirit nourished be<br/>As thus upon Thyself we feed.<br/>',NULL,4238,4238);
INSERT INTO stanza VALUES('E815','1','Christ is the Word and Spirit too,<br/>And as the Spirit in the Word;<br/>And all the words He speaks to us<br/>Are life and spirit thus conferred.<br/>',NULL,4239,4239);
INSERT INTO stanza VALUES('E815','2','The Holy Word we have without,<br/>The Holy Spirit is within;<br/>The greatest gifts divine are these,<br/>That we may God enjoy therein.<br/>',NULL,4240,4240);
INSERT INTO stanza VALUES('E815','3','The Word the Spirit doth express,<br/>The Spirit its reality;<br/>They''re but two aspects of one thing<br/>And should not separated be.<br/>',NULL,4241,4241);
INSERT INTO stanza VALUES('E815','4','Whene''er the Spirit lights the Word<br/>The Word becometh life to us;<br/>When Word from Spirit is divorced,<br/>''Tis empty mental stimulus.<br/>',NULL,4242,4242);
INSERT INTO stanza VALUES('E815','5','When we the Word in spirit touch,<br/>As life the Spirit it becomes;<br/>The Spirit, when expressed from us,<br/>As words of life to others comes.<br/>',NULL,4243,4243);
INSERT INTO stanza VALUES('E815','6','Our spirit we must exercise<br/>To take the Word most inwardly,<br/>And then to give the Spirit forth;<br/>The two as one with us should be.<br/>',NULL,4244,4244);
INSERT INTO stanza VALUES('E815','7','Lord, may Thy Word in me become<br/>The Spirit as my life supply,<br/>And may Thy Spirit in Thy Word<br/>My true expression be thereby.<br/>',NULL,4245,4245);
INSERT INTO stanza VALUES('E816','1','God''s own Word must not be taken<br/>Just as knowledge but as life,<br/>Not alone God''s thought conveying,<br/>But Himself to us as life;<br/>Not alone God''s mind revealing,<br/>But His Christ as life within,<br/>Not alone the teaching giving,<br/>But experience of Him.<br/>',NULL,4246,4246);
INSERT INTO stanza VALUES('E816','2','It is only knowledge to us<br/>If we in the letter read,<br/>But when reading in the spirit<br/>It is truly life indeed.<br/>All the knowledge in the letter<br/>Only brings us into death,<br/>But the Word in spirit taken<br/>Gives to us the quickening breath.<br/>',NULL,4247,4247);
INSERT INTO stanza VALUES('E816','3','It we miss the Lord in Scripture,<br/>It is just as knowledge vain;<br/>But when Christ we touch within it,<br/>Then His life we may obtain.<br/>When we read, the Lord not touching,<br/>''Tis but mental stimulus;<br/>But when Christ we touch by reading,<br/>It becometh life to us.<br/>',NULL,4248,4248);
INSERT INTO stanza VALUES('E816','4','All the knowledge of the Scriptures<br/>Into life must be transformed,<br/>All the mental understanding<br/>In the spirit must be formed;<br/>All the Scriptural understanding<br/>Must become the life received,<br/>All the knowledge of the letters<br/>In the spirit be conceived.<br/>',NULL,4249,4249);
INSERT INTO stanza VALUES('E816','5','Just to touch the Word for knowledge<br/>Is to take the very way<br/>By which Eve was lured by Satan<br/>And by knowledge led astray;<br/>But as life to take the Scripture<br/>Is the tree of life to eat;<br/>Thus the Word we must be taking<br/>In the spirit as our meat.<br/>',NULL,4250,4250);
INSERT INTO stanza VALUES('E817','1','We limit not the truth of God<br/>To our poor reach of mind,<br/>By notions of our day and sect,<br/>Crude, partial and confined.<br/>Now let a new and better hope<br/>Within our hearts be stirred:<br/>The Lord hath yet more light and truth<br/>To break forth from His Word.<br/>',NULL,4251,4251);
INSERT INTO stanza VALUES('E817','2','Who dares to bind by his dull sense<br/>The oracles of heaven,<br/>For all the nations, tongues and climes<br/>And all the ages given!<br/>The universe how much unknown!<br/>The ocean unexplored!<br/>The Lord hath yet more light and truth<br/>To break forth from His Word.<br/>',NULL,4252,4252);
INSERT INTO stanza VALUES('E817','3','Darkling our great forefathers went<br/>The first steps of the way;<br/>''Twas but the dawning yet to grow<br/>Into the perfect day;<br/>And grow it shall, our glorious Sun<br/>More fervid rays afford:<br/>The Lord hath yet more light and truth<br/>To break forth from His Word.<br/>',NULL,4253,4253);
INSERT INTO stanza VALUES('E817','4','The valleys past, ascending still,<br/>Our souls would higher climb,<br/>And look down from supernal heights,<br/>On all the bygone times;<br/>Upward we press, the air is clear,<br/>And the sphere-music heard!<br/>The Lord hath yet more light and truth<br/>To break forth from His Word.<br/>',NULL,4254,4254);
INSERT INTO stanza VALUES('E817','5','O Father, Son and Spirit, send<br/>Us increase from above;<br/>Enlarge, expand all Christian hearts<br/>To comprehend Thy love;<br/>And make us all go on to know<br/>With nobler powers conferred:<br/>The Lord hath yet more light and truth<br/>To break forth from His Word.<br/>',NULL,4255,4255);
INSERT INTO stanza VALUES('E818','1','Christ is the mystery of God;<br/>God is invisible, unshown,<br/>His image man hath never seen,<br/>But Christ the Son hath made Him known.<br/>',NULL,4256,4256);
INSERT INTO stanza VALUES('E818','2','Christ is the very Word of God,<br/>He is God''s explanation true;<br/>God''s full embodiment is He<br/>And God''s own image brings to view.<br/>',NULL,4257,4257);
INSERT INTO stanza VALUES('E818','3','Image of God invisible,<br/>Effulgence of God''s glory fair;<br/>God''s fulness ever dwells in Him,<br/>God''s testimony He doth bear.<br/>',NULL,4258,4258);
INSERT INTO stanza VALUES('E818','4','The Church the myst''ry is of Christ,<br/>For He is now to man unshown;<br/>No man on earth may see Him now,<br/>But thru the Church He is made known.<br/>',NULL,4259,4259);
INSERT INTO stanza VALUES('E818','5','The Church is Christ''s expression full,<br/>In her Christ dwelleth bodily;<br/>She is His duplication true,<br/>And man in her Himself may see.<br/>',NULL,4260,4260);
INSERT INTO stanza VALUES('E818','6','The Church the image has of Christ,<br/>She is His increase and His spread;<br/>Christ''s very self is found in her,<br/>The Body, she, to Christ the Head.<br/>',NULL,4261,4261);
INSERT INTO stanza VALUES('E818','7','Thus, in the Son the Father is,<br/>And now the Spirit is the Son;<br/>The Spirit of the triune God<br/>Is in the Church and with her one.<br/>',NULL,4262,4262);
INSERT INTO stanza VALUES('E819','1','As the body is the fulness<br/>To express our life,<br/>So to Christ the Church, His Body,<br/>Doth express His life.<br/>',NULL,4263,4263);
INSERT INTO stanza VALUES('E819','2','E''en as Eve is part of Adam<br/>Taken out of him,<br/>So the Church is Christ''s own increase<br/>With Himself within.<br/>',NULL,4264,4264);
INSERT INTO stanza VALUES('E819','3','As from out the buried kernel<br/>Many grain are formed,<br/>As the grains together blended<br/>To a loaf are formed;<br/>',NULL,4265,4265);
INSERT INTO stanza VALUES('E819','4','So the Church, of many Christians,<br/>Christ doth multiply,<br/>Him expressing as one Body,<br/>God to glorify.<br/>',NULL,4266,4266);
INSERT INTO stanza VALUES('E819','5','As the branches of the grapevine<br/>Are its outward spread,<br/>With it one, abiding, bearing<br/>Clusters in its stead;<br/>',NULL,4267,4267);
INSERT INTO stanza VALUES('E819','6','So the Church''s many members<br/>Christ''s enlargement are,<br/>One with Him in life and living,<br/>Spreading Him afar.<br/>',NULL,4268,4268);
INSERT INTO stanza VALUES('E819','7','Fulness, increase, duplication,<br/>His expression full,<br/>Growth and spread, continuation,<br/>Surplus plentiful,<br/>',NULL,4269,4269);
INSERT INTO stanza VALUES('E819','8','Is the Church to Christ, and thereby<br/>God in Christ may be<br/>Glorified thru His redeemed ones<br/>To eternity.<br/>',NULL,4270,4270);
INSERT INTO stanza VALUES('E819','9','Thus the Church and Christ together,<br/>God''s great mystery,<br/>Is the mingling of the Godhead<br/>With humanity.<br/>',NULL,4271,4271);
INSERT INTO stanza VALUES('E820','1','Riches of Christ we should enjoy<br/>And then His fulness we will be;<br/>Partaking of His very self,<br/>His testimony men will see.<br/>',NULL,4272,4272);
INSERT INTO stanza VALUES('E820','2','Riches of Christ are what He is<br/>To us who are His members true;<br/>His fulness is what we become<br/>As body doth to man accrue.<br/>',NULL,4273,4273);
INSERT INTO stanza VALUES('E820','3','Riches of Christ are typified<br/>By Canaan''s produce rich and sweet,<br/>With which the temple great was built,<br/>The Church''s greatest type replete.<br/>',NULL,4274,4274);
INSERT INTO stanza VALUES('E820','4','As Eve to Adam fulness was,<br/>So is the Church to Christ her Head;<br/>As Eve from Adam''s being came,<br/>The Church by Christ''s own life is bred.<br/>',NULL,4275,4275);
INSERT INTO stanza VALUES('E820','5','Christ''s riches are Himself within,<br/>His fulness is the Church without,<br/>As His expression, full of Him;<br/>The Church with Christ is built throughout.<br/>',NULL,4276,4276);
INSERT INTO stanza VALUES('E821','1','The Church the vessel is to Christ,<br/>Him to contain and Him express,<br/>Just as the human body doth<br/>Man''s life show forth, his life possess.<br/>',NULL,4277,4277);
INSERT INTO stanza VALUES('E821','2','As was the temple to the ark,<br/>Receptacle and resting-place;<br/>So Christ the Church''s content is,<br/>And in the Church, Christ''s dwelling-place.<br/>',NULL,4278,4278);
INSERT INTO stanza VALUES('E821','3','As Christ is God''s true mystery,<br/>God to explain and God express;<br/>So is the Church Christ''s mystery,<br/>Christ to explain and manifest.<br/>',NULL,4279,4279);
INSERT INTO stanza VALUES('E821','4','The members of the Church of Christ<br/>Are all primarily of clay;<br/>They need to be transformed and made<br/>Transparent, precious day by day.<br/>',NULL,4280,4280);
INSERT INTO stanza VALUES('E821','5','By transformation they are built,<br/>A vessel they to Christ afford;<br/>His all-inclusiveness they hold;<br/>Transparent, they express the Lord.<br/>',NULL,4281,4281);
INSERT INTO stanza VALUES('E821','6','Thru all the transformation work<br/>The triune God performs in them,<br/>The Church a corporate vessel is<br/>And like the new Jerusalem.<br/>',NULL,4282,4282);
INSERT INTO stanza VALUES('E821','7','How precious she in each respect,<br/>Transparent too in every phase;<br/>Christ with God''s fulness she contains,<br/>Christ with God''s glory she displays.<br/>',NULL,4283,4283);
INSERT INTO stanza VALUES('E821','8','With Christ as life, with God as light,<br/>And with the Spirit''s living flow,<br/>The triune God she manifests<br/>For all the universe to know.<br/>',NULL,4284,4284);
INSERT INTO stanza VALUES('E822','1','The Church the lampstand is to Christ,<br/>Christ is the lamp with God as light;<br/>The light divine from Christ doth shine,<br/>The Church upholds its glory bright.<br/>',NULL,4285,4285);
INSERT INTO stanza VALUES('E822','2','The light which shines within the lamp<br/>Is God as life, unique, divine;<br/>The stand must therefore be of gold<br/>To match the glory which doth shine.<br/>',NULL,4286,4286);
INSERT INTO stanza VALUES('E822','3','Amid the darkness of this age<br/>The light of life divine doth beam<br/>In many centers of mankind<br/>Where Jesus'' testimony''s seen.<br/>',NULL,4287,4287);
INSERT INTO stanza VALUES('E822','4','To be this testimony pure<br/>"First love" to Christ the Church must keep;<br/>Then from the "tree of life" she may<br/>The overcomer''s portion reap.<br/>',NULL,4288,4288);
INSERT INTO stanza VALUES('E822','5','She must the persecution bear<br/>That she the "crown of life" may gain;<br/>Adult''ry spiritual o''ercome,<br/>The "hidden manna" to obtain.<br/>',NULL,4289,4289);
INSERT INTO stanza VALUES('E822','6','The deeds of "Jezebel" desert,<br/>That she may rule the earth with might;<br/>Defiling deadness overcome<br/>To be arrayed in "garments white."<br/>',NULL,4290,4290);
INSERT INTO stanza VALUES('E822','7','Like "Philadelphia" she must be<br/>To keep Christ''s word, confess His Name;<br/>All "lukewarm" pride she must o''ercome<br/>To feast with Him who overcame.<br/>',NULL,4291,4291);
INSERT INTO stanza VALUES('E822','8','Thus will the Church be purified<br/>To be the lampstand of pure gold,<br/>To match the testimony pure,<br/>The life of Jesus fit to hold.<br/>',NULL,4292,4292);
INSERT INTO stanza VALUES('E822','9','The local churches here on earth<br/>The lampstands in this age should be;<br/>The glorious new Jerusalem<br/>The lampstand in eternity.<br/>',NULL,4293,4293);
INSERT INTO stanza VALUES('E822','10','The city as pure gold will be,<br/>The final lampstand consummate;<br/>Christ as the lamp she e''er will hold<br/>And God''s full light will radiate.<br/>',NULL,4294,4294);
INSERT INTO stanza VALUES('E823','1','God before the world''s foundation<br/>Chose the Church in Christ the Son,<br/>That the Church might share the sonship,<br/>Holy, blameless, with Him one;<br/>That the Church be His possession<br/>With the Spirit as the seal,<br/>Of our heritage the earnest<br/>While His Son He does reveal.<br/>',NULL,4295,4295);
INSERT INTO stanza VALUES('E823','2','To the throne Christ has ascended,<br/>Far above all rule and power;<br/>God has made Him Head o''er all things<br/>To the Church, His Body here.<br/>All in all He ever filleth,<br/>And His fulness is expressed<br/>Through the Church, which is His Body<br/>And His image manifests.<br/>',NULL,4296,4296);
INSERT INTO stanza VALUES('E823','3','We, once dead in our offences,<br/>Walking in the worldly course,<br/>Lusts of flesh and mind fulfilling,<br/>Satan and his hosts their source,<br/>God with Christ has resurrected,<br/>Seated in the heavenlies;<br/>We, His masterpiece, created<br/>In Christ Jesus, Him to please.<br/>',NULL,4297,4297);
INSERT INTO stanza VALUES('E823','4','Jews and Gentiles are one body-<br/>God His myst''ry has made known-<br/>On apostles, prophets founded,<br/>Jesus Christ the cornerstone;<br/>We in Him are built together<br/>For God''s dwelling manifest,<br/>Fitly framed by God the Spirit<br/>For His pleasure and His rest.<br/>',NULL,4298,4298);
INSERT INTO stanza VALUES('E823','5','In eternal ages purposed<br/>That His wisdom be made known,<br/>Was the Church, His hidden myst''ry,<br/>Where the Son could make His home;<br/>That the saints may all in spirit<br/>Apprehend His boundlessness,<br/>Know His love which passes knowledge,<br/>All God''s fulness to possess.<br/>',NULL,4299,4299);
INSERT INTO stanza VALUES('E823','6','One in body, hope, and Spirit,<br/>One in faith, one Lord, the Son,<br/>One baptizing, with one Father,<br/>That the Church may thus be one;<br/>Christ to know in all His fulness,<br/>Unto manhood be matured,<br/>Ne''er by winds of doctrine<br/>Carried,<br/>Nor by cunning men allured.<br/>',NULL,4300,4300);
INSERT INTO stanza VALUES('E823','7','Many gifts the Lord has given,<br/>That His Body He may build,<br/>That the saints may be perfected<br/>And their ministry fulfilled.<br/>Thus we must put off the old man<br/>That we may put on the new;<br/>Thus, renewed in mind and spirit,<br/>We will bear God''s image true.<br/>',NULL,4301,4301);
INSERT INTO stanza VALUES('E823','8','Christ in love Himself has given<br/>That the Church be sanctified,<br/>Without blemish, spot, or wrinkle,<br/>To become His glorious bride.<br/>He does nourish her and cherish<br/>As a man his body treats;<br/>He and she become one body-<br/>Thus the myst''ry very great.<br/>',NULL,4302,4302);
INSERT INTO stanza VALUES('E823','9','Body, house, new man the Church is,<br/>Bride, and temple, and yet more:<br/>She''s the army too which fighteth<br/>All God''s foe to triumph o''er.<br/>She is clothed with all God''s armor,<br/>In His mighty strength is strong,<br/>Standing in the Lord, resisting,<br/>With all prayers she fighteth on.<br/>',NULL,4303,4303);
INSERT INTO stanza VALUES('E824','1','The Church is Christ''s own Body,<br/>The Father''s dwelling-place,<br/>The gathering of the called ones,<br/>God blended with man''s race;<br/>Elect before creation,<br/>Redeemed by Calv''ry''s death,<br/>Her character and standing<br/>Of heaven, not of earth.<br/>',NULL,4304,4304);
INSERT INTO stanza VALUES('E824','2','New man of new creation,<br/>Born through her risen Lord,<br/>Baptized in God the Spirit,<br/>Made holy by His Word;<br/>Christ is her life and content,<br/>Himself her glorious Head;<br/>She has ascended with Him<br/>O''er all her foes to tread.<br/>',NULL,4305,4305);
INSERT INTO stanza VALUES('E824','3','Christ is her one foundation,<br/>None other man may lay;<br/>All that she has, as Christ, is<br/>Divine in every way;<br/>Her members through the Spirit<br/>Their death on Calv''ry own;<br/>They''re built in resurrection-<br/>Gold, silver, precious stone.<br/>',NULL,4306,4306);
INSERT INTO stanza VALUES('E824','4','One God, one Lord, one Spirit-<br/>Her elements all one-<br/>One faith, one hope, one baptism,<br/>One Body in the Son;<br/>The triune God is in her,<br/>One Body members own,<br/>By faith they are united,<br/>In hope of glory shown.<br/>',NULL,4307,4307);
INSERT INTO stanza VALUES('E824','5','From every tribe and nation<br/>Do all the members come,<br/>Regardless of their classes<br/>United to be one.<br/>No high, there is, nor lowly,<br/>No Jew, nor Gentile clan,<br/>No free, nor slave, nor master,<br/>But Christ, the "one new man."<br/>',NULL,4308,4308);
INSERT INTO stanza VALUES('E824','6','One Body universal,<br/>One in each place expressed;<br/>Locality of dwelling<br/>Her only ground possessed;<br/>Administration local,<br/>Each answ''ring to the Lord;<br/>Communion universal,<br/>Upheld in one accord.<br/>',NULL,4309,4309);
INSERT INTO stanza VALUES('E824','7','Her local gatherings model<br/>The New Jerusalem;<br/>Its aspects and its details<br/>Must show in all of them.<br/>Christ is the Lamp that shineth,<br/>With God within, the Light;<br/>They are the lampstands bearing<br/>His glorious Image bright.<br/>',NULL,4310,4310);
INSERT INTO stanza VALUES('E825','1','Church of God, beloved and chosen,<br/>Church of Christ for whom He died,<br/>Claim thy gifts and praise the Giver,<br/>Ye are washed and sanctified.<br/>Sanctified by God the Father,<br/>And by Jesus Christ His Son,<br/>And by God the Holy Spirit,<br/>Holy, Holy, Three in One.<br/>',NULL,4311,4311);
INSERT INTO stanza VALUES('E825','2','By His will He sanctifieth,<br/>By the Spirit''s power within;<br/>By the loving hand that chasteneth<br/>Fruits of righteousness to win;<br/>By His truth and by His promise,<br/>By the Word, His gift unpriced,<br/>By His own blood, and by union<br/>With the risen life of Christ.<br/>',NULL,4312,4312);
INSERT INTO stanza VALUES('E825','3','Holiness by faith in Jesus,<br/>Not by effort of thine own,<br/>Sin''s dominion crushed and broken<br/>By the power of grace alone,<br/>Christ, the holiness within thee,<br/>His own beauty on thy brow:<br/>This shall be thy pilgrim brightness,<br/>This thy blessed portion now.<br/>',NULL,4313,4313);
INSERT INTO stanza VALUES('E825','4','He will sanctify thee wholly;<br/>Body, spirit, soul shall be<br/>Blameless till thy Savior''s coming<br/>In His glorious majesty!<br/>He hath perfected forever<br/>Those whom He hath sanctified:<br/>Spotless, glorious, and holy,<br/>Is the Church, His chosen Bride.<br/>',NULL,4314,4314);
INSERT INTO stanza VALUES('E826','1','I saw great throngs-each was a brother dear,<br/>Linked with each other in one Body here;<br/>Each in close union with the living Head,<br/>The witness-folk, by Jesus'' Spirit led.<br/>',NULL,4315,4315);
INSERT INTO stanza VALUES('E826','2','At every time, in every clime I found<br/>Those, not with words of Christ, but Spirit bound.<br/>He strengthens them with might each day, each hour;<br/>Through them true works divine are wrought in power.<br/>',NULL,4316,4316);
INSERT INTO stanza VALUES('E826','3','This is the Church the Spirit hath begot,<br/>Elect from every people, Christ their lot.<br/>They follow where His shepherd-staff doth lead;<br/>The members of this host are blessed indeed.<br/>',NULL,4317,4317);
INSERT INTO stanza VALUES('E826','4','And when on earth they meet His death to show,<br/>To Him their vows of love they oft renew.<br/>Some little flock will gather there or here;<br/>Christ, Head of all, to every soul most near.<br/>',NULL,4318,4318);
INSERT INTO stanza VALUES('E826','5','This is the temple which our Lord approves,<br/>The Church which truly honors Him and loves,<br/>Whose sacrifice is on the altar bound;<br/>She soon in glory will His throne surround.<br/>',NULL,4319,4319);
INSERT INTO stanza VALUES('E827','1','I have found life''s Giver, and the Prince of Life;<br/>He has quenched my thirst, and vanquished all my strife.<br/>He, my living bread, became my daily meat;<br/>Death has died in me, Life''s triumph is complete.<br/>',NULL,4320,4320);
INSERT INTO stanza VALUES('E827','2','In the Church, what glory! Far horizons glow!<br/>And His Name all radiant on each brow doth show.<br/>Christ doth breathe upon her, He''s her living Rock,<br/>Shepherd of His sheep all gathered in one flock.<br/>',NULL,4321,4321);
INSERT INTO stanza VALUES('E827','3','There on holy flame doth burn within each breast;<br/>By one blood redeemed, in Christ they find their rest.<br/>All their thirst He quenches from on living stream;<br/>They in adoration lowly worship Him.<br/>',NULL,4322,4322);
INSERT INTO stanza VALUES('E827','4','There as Bread of life faint souls He ever feeds;<br/>There each hungry soul may take whate''er he needs.<br/>Lovingly He draws each soul that truly lives,<br/>And in bread and wine Himself to them He gives.<br/>',NULL,4323,4323);
INSERT INTO stanza VALUES('E827','5','Gone is all the earth-taint thru abounding grace;<br/>Hear the song of triumph from the ransomed race.<br/>All in glory shining, glory not their own,<br/>Blended into oneness, they approach the throne.<br/>',NULL,4324,4324);
INSERT INTO stanza VALUES('E828','1','The "churches" here below, so narrow bound,<br/>Reach not the hungry throngs which us surround;<br/>They run partway with truth, but miss the goal.<br/>Earth-vision blurred and dim, their eyes doth hold-<br/>But broken gleams have they of radiance gold;<br/>Too dazzling is the splendor of the whole.<br/>',NULL,4325,4325);
INSERT INTO stanza VALUES('E828','2','Brothers with brothers have not all one heart,<br/>In wrath they turn away and walk apart,<br/>Who from one stream of life had common birth.<br/>What fight for forms! O''er doctrines what vain strife!<br/>Instead together sharing God''s on life,<br/>Who worshipped is by heaven and by earth.<br/>',NULL,4326,4326);
INSERT INTO stanza VALUES('E828','3','"Where is the truth?" I asked; for this I longed:<br/>None answered right ''mid all the answering throng;<br/>For ever side by side lay light and shade.<br/>"Where is," I cried, "the one communion pure?<br/>Where is the Church in which, clear-traced and sure,<br/>The Spirit''s very likeness is portrayed?<br/>',NULL,4327,4327);
INSERT INTO stanza VALUES('E828','4','So sought I long, and hopeless was my quest;<br/>These eyes grew dim and blind and found no rest,<br/>Till God''s touch opened them, and I was freed.<br/>I found the Spirit''s Church in souls made one<br/>In this, that they in troth to Christ had come-<br/>His Bride, to follow where the cross may lead.<br/>',NULL,4328,4328);
INSERT INTO stanza VALUES('E828','5','Thus when I see this small world''s narrow thought,<br/>Behold the brother not with brother brought,<br/>Yet serving Christ-as each one deemeth right-<br/>Ah, then a voice from realms of glory calls,<br/>Where the last veil is rent and earthward falls,<br/>And where God''s love, eternal, burneth bright.<br/>',NULL,4329,4329);
INSERT INTO stanza VALUES('E828','6','No more we put that query without end,<br/>To which self-chosen church our feet did trend-<br/>What doctrine we believed, what sacred rites.<br/>In Christ we were in bonds that nought could break;<br/>Who, by His cross and death, do all forsake,<br/>Such as were far asunder He unites.<br/>',NULL,4330,4330);
INSERT INTO stanza VALUES('E828','7','No longer does one heed mere formal phrase,<br/>Or seek for others'' creeds through winding maze,<br/>For in Himself was truth made manifest.<br/>And out of every tongue and every land<br/>He formed one Church to meet His own demand-<br/>His Body, where His fulness is expressed.<br/>',NULL,4331,4331);
INSERT INTO stanza VALUES('E829','1','The Church''s seed is nought by Christ Himself<br/>Sown into human hearts as life, thereby<br/>Growing as wheat, producing flour fine<br/>For bread both God and man to satisfy.<br/>',NULL,4332,4332);
INSERT INTO stanza VALUES('E829','2','But Satan hath the false believers sown<br/>Among the saints as tares among the wheat,<br/>To bring confusion and to hinder growth<br/>That they may not fulfill God''s plan complete.<br/>',NULL,4333,4333);
INSERT INTO stanza VALUES('E829','3','The Church''s life just as the herb must be,<br/>Grown out of Christ, who is the mustard seed;<br/>Hidden and transient, little on earth,<br/>But good for food the hungry ones to feed.<br/>',NULL,4334,4334);
INSERT INTO stanza VALUES('E829','4','But Satan came and made the little herb<br/>To change its nature and to change its form,<br/>That fully grown it did a tree become<br/>Where many evil ones may lodge and swarm.<br/>',NULL,4335,4335);
INSERT INTO stanza VALUES('E829','5','Satan has also used the fallen "church"<br/>Evil and heathen practice to include,<br/>As leaven mingled with the meal of wheat,<br/>Thus to corrupt its purity as food.<br/>',NULL,4336,4336);
INSERT INTO stanza VALUES('E829','6','But Christ as life would so transform the saints<br/>That they may be a pearl and precious stone,<br/>As the materials suitable to build<br/>Into His Church to make His Kingdom known.<br/>',NULL,4337,4337);
INSERT INTO stanza VALUES('E829','7','Such an assembly grown in Christ as life,<br/>Transformed and built with Christ in them annealed,<br/>Is as the goodly pearl for preciousness<br/>And as the treasure hidden in the field.<br/>',NULL,4338,4338);
INSERT INTO stanza VALUES('E829','8','Lord, separate us from the devil''s "tares,"<br/>Each on deliver from the monstrous "tree,"<br/>From all the "leaven" may Thou purify,<br/>That we may be as food to man and Thee.<br/>',NULL,4339,4339);
INSERT INTO stanza VALUES('E829','9','Cause us to grow in life divine each day<br/>That we may be transformed and built by Thee<br/>Into a body to express Thyself,<br/>That Thou in us Thy Church and Kingdom see.<br/>Back to Verse 1 ??<br/>',NULL,4340,4340);
INSERT INTO stanza VALUES('E830','1','Faith of our fathers, living still<br/>In spite of dungeons, fire and sword,<br/>O how our hearts beat high with joy<br/>Whene''er we hear that glorious word!<br/>Faith of our fathers! Holy faith!<br/>We will be true to thee till death!<br/>',NULL,4341,4341);
INSERT INTO stanza VALUES('E830','2','Our fathers, chained in prisons dark,<br/>Were still in heart and conscience free;<br/>And blest would be their children''s fate,<br/>If they, like them should die for thee:<br/>Faith of our fathers! Holy faith!<br/>We will be true to thee till death!<br/>',NULL,4342,4342);
INSERT INTO stanza VALUES('E830','3','Faith of our fathers, we will strive<br/>To win all nations unto thee;<br/>And through the truth that comes from God<br/>Mankind shall then indeed be free.<br/>Faith of our fathers! Holy faith!<br/>We will be true to thee till death!<br/>',NULL,4343,4343);
INSERT INTO stanza VALUES('E830','4','Faith of our fathers, we will love<br/>Both friend and foe in all our strife,<br/>And preach thee, too, as love knows how<br/>By kindly words and virtuous life.<br/>Faith of our fathers! Holy faith!<br/>We will be true to thee till death!<br/>',NULL,4344,4344);
INSERT INTO stanza VALUES('E831','1','The unity of the Church is but<br/>The saints in oneness living;<br/>The Spirit which indwelleth them<br/>This oneness ever giving.<br/>Thus it is realized and called<br/>The unity of Spirit;<br/>''Tis based upon the common faith<br/>Which all the saints inherit.<br/>',NULL,4345,4345);
INSERT INTO stanza VALUES('E831','2','This precious faith all the saints,<br/>Is constituted solely<br/>Of Christ and His redemptive work,<br/>Which are unique and holy.<br/>In this the saints are truly one,<br/>Together all agreeing,<br/>And it is from this common faith<br/>The Church came into being.<br/>',NULL,4346,4346);
INSERT INTO stanza VALUES('E831','3','The Church within the universe<br/>Is one as Christ''s possession;<br/>The Church must therefore locally<br/>Be one in her expression;<br/>For all her elements are one-<br/>One God, one Lord, one Spirit,<br/>One faith, baptism, Body too,<br/>One hope all saints inherit.<br/>',NULL,4347,4347);
INSERT INTO stanza VALUES('E831','4','This oneness is the Church''s ground,<br/>The ground of common standing,<br/>The only ground of unity<br/>The Spirit is demanding.<br/>The Church in actual practice thus<br/>May keep her vital union,<br/>And her expression locally<br/>Be built up in communion.<br/>',NULL,4348,4348);
INSERT INTO stanza VALUES('E831','5','Lord, help us ever strive to keep<br/>This unity by taking<br/>The Church''s ground of unity,<br/>The Body-life partaking,<br/>That all Thy heart''s profound desire<br/>May full be effected,<br/>And God''s eternal purpose may<br/>Completely be perfected.<br/>',NULL,4349,4349);
INSERT INTO stanza VALUES('E832','1','Christ the Son of God and His redemptive deed<br/>Are the saving faith which is our only creed.<br/>All the other doctrines do not faith comprise;<br/>Christ, His work and person, only qualifies.<br/>',NULL,4350,4350);
INSERT INTO stanza VALUES('E832','2','All the other teachings used improperly<br/>Are the "winds of doctrine," spoiling unity:<br/>Blowing saints away from Christ who is the Head,<br/>Building not the Body, tearing down instead.<br/>',NULL,4351,4351);
INSERT INTO stanza VALUES('E832','3','Thus we must relinquish doctrines of all kinds,<br/>Only keep the faith that oneness we may find.<br/>In the Lord the Spirit we are one indeed;<br/>Just to keep this oneness is our only need.<br/>',NULL,4352,4352);
INSERT INTO stanza VALUES('E832','4','Truth we must be holding, which is Christ Himself,<br/>That we be delivered from the sects of self,<br/>That in all things growing into Christ the Head,<br/>Build will be the Body and to fulness led.<br/>',NULL,4353,4353);
INSERT INTO stanza VALUES('E832','5','To the "unity of faith" we must attain,<br/>All the "winds of doctrine" evermore disdain;<br/>Holding Christ the Spirit, our reality,<br/>For the Body''s growing in its unity.<br/>',NULL,4354,4354);
INSERT INTO stanza VALUES('E833','1','The Church''s one foundation<br/>Is Jesus Christ her Lord;<br/>She is His new creation<br/>By water and the Word:<br/>From heav''n He came and sought her<br/>To be His holy Bride;<br/>With His own blood He bought her,<br/>And for her life He died.<br/>',NULL,4355,4355);
INSERT INTO stanza VALUES('E833','2','Elect from every nation,<br/>Yet one o''er all the earth,<br/>Her character of salvation,<br/>One Lord, one faith, one birth;<br/>One holy Name she blesses,<br/>Partakes one holy food,<br/>And to one hope she presses,<br/>With every grace endured.<br/>',NULL,4356,4356);
INSERT INTO stanza VALUES('E833','3','''Mid toil and tribulation,<br/>And tumult of her war,<br/>She waits the consummation<br/>Of peace for evermore;<br/>Till, with the vision glorious,<br/>Her longing eyes are blest,<br/>And the great Church victorious<br/>Shall be the Church at rest.<br/>',NULL,4357,4357);
INSERT INTO stanza VALUES('E833','4','Yet she on earth hath union<br/>With God the Three in One,<br/>And mystic sweet communion<br/>With those whose rest is won:<br/>O happy ones and holy!<br/>Lord, give us grace that we,<br/>Like them, the meek and lowly,<br/>In love may dwell with Thee.<br/>',NULL,4358,4358);
INSERT INTO stanza VALUES('E834','1','The chief Cornerstone Thou art, Lord,<br/>Jewish builders did despise;<br/>God by resurrection placed Thee,<br/>Thou art precious in His eyes.<br/>Through Thee we receive salvation,<br/>And, together build by Thee,<br/>Jews and Gentiles are Thy dwelling,<br/>One new man, in harmony.<br/>',NULL,4359,4359);
INSERT INTO stanza VALUES('E834','2','Thou too art the smitten Rock, Lord,<br/>That man''s thirst by Thee be filled,<br/>That frail man may stand upon Thee,<br/>But e''en more, God''s house to build.<br/>The Foundation Stone in Zion,<br/>Tested and secure, Thou art;<br/>And the Rock, the Church supporting,<br/>Her foundation to impart.<br/>',NULL,4360,4360);
INSERT INTO stanza VALUES('E834','3','On Thyself the Church is builded,<br/>And though many storms assail,<br/>Still it stands erect, for ''gainst it<br/>Gates of hell cannot prevail.<br/>Thine authority possessing,<br/>It doth bind and loose in Thee,<br/>Bringing men into Thy kingdom,<br/>Satan''s captives setting free.<br/>',NULL,4361,4361);
INSERT INTO stanza VALUES('E834','4','Living Stone of life art Thou, Lord,<br/>Precious, chosen thus to be;<br/>Living stones Thou too hast made us,<br/>One in character with Thee.<br/>Built together as a temple<br/>That our God may dwell therein,<br/>Thus we are a holy priesthood,<br/>Offering sacrifice to Him.<br/>',NULL,4362,4362);
INSERT INTO stanza VALUES('E834','5','Lord, Thou art the Son of David<br/>That God''s temple Thou may build;<br/>King and Priest Thou art together,<br/>That Thy calling be fulfilled.<br/>As the King, for God Thou rulest,<br/>Making men submit to Him;<br/>As the Priest before God''s presence,<br/>Bringing men to enter in.<br/>',NULL,4363,4363);
INSERT INTO stanza VALUES('E834','6','Thine authority doth issue<br/>From the throne to render peace;<br/>Fellowship is in the river<br/>To supply and give increase.<br/>When these, balanced, go together,<br/>Then God''s purpose is fulfilled;<br/>King and Priest in Thee combining,<br/>Thou God''s dwelling place dost build.<br/>',NULL,4364,4364);
INSERT INTO stanza VALUES('E834','7','Thou art God, yet flesh becamest,<br/>God with man in Thee doth dwell;<br/>Thou, the Temple for His glory,<br/>God in Thee Himself doth tell.<br/>Thus the Church too is the mingling<br/>Into one of God and man;<br/>So it is with every member<br/>For the building of God''s plan.<br/>',NULL,4365,4365);
INSERT INTO stanza VALUES('E834','8','Thou, the everlasting Dwelling,<br/>In all ages art our home;<br/>We in Thee enjoy protection,<br/>Living in Thyself alone.<br/>Thou our Sanctuary art, Lord,<br/>We and God abide in Thee;<br/>Thou, God''s presence art within us,<br/>Where we worship ceaselessly.<br/>',NULL,4366,4366);
INSERT INTO stanza VALUES('E834','9','Cornerstone, Foundation, Topstone,<br/>Rock, and Church, and Living Stone,<br/>Dwelling-place, and Sanctuary,<br/>Builder too art Thou, we own.<br/>Praise we give for what Thou art, Lord,<br/>As Thy wondrousness we see!<br/>Grant that we may be built up, Lord,<br/>As the living stones in Thee.<br/>',NULL,4367,4367);
INSERT INTO stanza VALUES('E835','1','On Christ, salvation rests secure;<br/>The Rock of Ages must endure;<br/>Nor can that faith be overthrown<br/>Which rest upon the "Living Stone."<br/>',NULL,4368,4368);
INSERT INTO stanza VALUES('E835','2','No other hope shall intervene;<br/>To Him we look, on Him we lean;<br/>Other foundations we disown,<br/>And build on Christ, the "Living Stone."<br/>',NULL,4369,4369);
INSERT INTO stanza VALUES('E835','3','In Him it is ordained to raise<br/>A temple to Jehovah''s praise,<br/>Composed of all His saints, who own<br/>No Savior but the "Living Stone."<br/>',NULL,4370,4370);
INSERT INTO stanza VALUES('E835','4','View the vast building, see it rise:<br/>The work how great! The plan how wise!<br/>O wondrous fabric! Pow''r unknown:<br/>That rests it on the "Living Stone."<br/>',NULL,4371,4371);
INSERT INTO stanza VALUES('E835','5','But most adore His precious name:<br/>His glory and His grace proclaim!<br/>For us, the lost, condemned, undone,<br/>He gave Himself, the "Living Stone."<br/>',NULL,4372,4372);
INSERT INTO stanza VALUES('E836','1','Christ is made the sure foundation,<br/>Christ the head and cornerstone,<br/>Chosen of the Lord and precious,<br/>Binding all the Church in one;<br/>Holy Zion''s help forever,<br/>And her confidence alone.<br/>',NULL,4373,4373);
INSERT INTO stanza VALUES('E836','2','Founded on the Lord victorious,<br/>Christ the everlasting Rock,<br/>Stands the Church in heav''nly places,<br/>Dreading not the storm or shock;<br/>Built with life divine she ever<br/>Stands against attack and mock.<br/>',NULL,4374,4374);
INSERT INTO stanza VALUES('E836','3','Though the gates of Hades frustrate,<br/>Yet the Church still stands for God,<br/>Overcoming evil spirits<br/>By her Lord''s victorious blood;<br/>And at Christ''s return in triumph<br/>All her foes will then be trod.<br/>',NULL,4375,4375);
INSERT INTO stanza VALUES('E837','1','We praise Thee, Lord, for Thy great plan<br/>That we Thy dwelling-place may be;<br/>Thou live in us, we filled with Thee,<br/>Thou in the Son expressed might be.<br/>',NULL,4376,4376);
INSERT INTO stanza VALUES('E837','2','Though in Thine image made by Thee<br/>And given Thine authority,<br/>Yet we are only made of clay<br/>Without a trace of divinity.<br/>',NULL,4377,4377);
INSERT INTO stanza VALUES('E837','3','When we receive Thee as our life,<br/>Thy nature we thru grace possess;<br/>Mingled together, we with Thee<br/>One Body glorious will express.<br/>',NULL,4378,4378);
INSERT INTO stanza VALUES('E837','4','When flows Thy life thru all our souls,<br/>Filling, renewing every part,<br/>We will be pearls and precious stones,<br/>Changed to Thine image, as Thou art.<br/>',NULL,4379,4379);
INSERT INTO stanza VALUES('E837','5','But, Lord, we fully realize<br/>These are not wrought men''s praise to rouse,<br/>But as material to be built<br/>Together for Thy glorious house.<br/>',NULL,4380,4380);
INSERT INTO stanza VALUES('E837','6','Here, Lord, we give ourselves to Thee;<br/>Receive us into Thy wise hands;<br/>Bend, break, and build together in Thee<br/>To be the house to meet Thy demands.<br/>',NULL,4381,4381);
INSERT INTO stanza VALUES('E837','7','Break all the natural life for us,<br/>Deal Thou with each peculiar way,<br/>That we no more independent be<br/>But with all saints are one for aye.<br/>',NULL,4382,4382);
INSERT INTO stanza VALUES('E837','8','Then we shall be Thy Bride beloved,<br/>Together in Thy chamber abide,<br/>Enjoy the fulness of Thy love.<br/>How Thou wilt then be satisfied!<br/>',NULL,4383,4383);
INSERT INTO stanza VALUES('E838','1','Thy blueprint, Lord, I treasure dear,<br/>It shows Thy tabernacle real,<br/>It tells how Thou wouldst have it built,<br/>How Thou Thy glory wouldst reveal.<br/>',NULL,4384,4384);
INSERT INTO stanza VALUES('E838','2','The ark''s the center of the tent,<br/>The tent is but its resting-place:<br/>In it the ten commandments are,<br/>And in the tent it ever stays.<br/>',NULL,4385,4385);
INSERT INTO stanza VALUES('E838','3','The ark the God-man, Christ, displays-<br/>God mixed with man, as gold, wood meet;<br/>The law is God''s expression full,<br/>Which dwells in Christ the Son complete.<br/>',NULL,4386,4386);
INSERT INTO stanza VALUES('E838','4','Thus Christ''s the center of the Church,<br/>Which is to Him a resting-place;<br/>In Christ the Father ever dwells,<br/>And in the Church, Christ''s dwelling-place.<br/>',NULL,4387,4387);
INSERT INTO stanza VALUES('E838','5','The tent''s the increase of the ark,<br/>Both are of wood with gold o''erlaid;<br/>The Church the increase is of Christ,<br/>God blent with man here too displayed.<br/>',NULL,4388,4388);
INSERT INTO stanza VALUES('E838','6','The boards when joined support the tent<br/>On silver sockets standing sure;<br/>Gold overlaid, with golden rings<br/>And interlocking bars, secure.<br/>',NULL,4389,4389);
INSERT INTO stanza VALUES('E838','7','The Church is thus the gathered saints,<br/>On Christ''s redemption standing sure;<br/>In life divine, by Spirit bound,<br/>Together built and framed secure.<br/>',NULL,4390,4390);
INSERT INTO stanza VALUES('E838','8','The tent''s four-layered cover shows<br/>The Christ of God in every phase;<br/>God''s glory thus is signified,<br/>Covering His holy dwelling-place.<br/>',NULL,4391,4391);
INSERT INTO stanza VALUES('E838','9','Covered by such a glorious Christ,<br/>All saints together knit may be;<br/>Enjoying all His is for them,<br/>In Him they''re builded gloriously.<br/>',NULL,4392,4392);
INSERT INTO stanza VALUES('E838','10','The law is place within the ark,<br/>The ark within the tent doth rest;<br/>So God in Christ within the Church<br/>His wondrous glory manifests.<br/>',NULL,4393,4393);
INSERT INTO stanza VALUES('E839','1','Lord, Thou art a potter skilled<br/>And a glorious builder too,<br/>Molding for Thy vessel great,<br/>Building with Thy house in view.<br/>I am both a man of clay<br/>And a new-made living stone,<br/>That Thy vessel I may be<br/>And the temple Thou wouldst own.<br/>',NULL,4394,4394);
INSERT INTO stanza VALUES('E839','2','Though of clay Thou madest us.<br/>Thou wouldst have us be transformed;<br/>With Thy life as purest gold,<br/>Unto precious stones conformed.<br/>We shall, through Thy building work,<br/>Then become Thy loving Bride,<br/>In one Body joined to Thee,<br/>That Thy heart be satisfied.<br/>',NULL,4395,4395);
INSERT INTO stanza VALUES('E839','3','What Thy heart desires and loves<br/>Are not precious stones alone,<br/>But together these to build<br/>For Thy glory, for Thy home.<br/>Thou, the all-inclusive Christ,<br/>Dost a builded Church require,<br/>That Thy glorious riches may<br/>Radiate their light entire.<br/>',NULL,4396,4396);
INSERT INTO stanza VALUES('E839','4','Not a person spiritual<br/>In an individual way,<br/>But the corporate life expressed<br/>Will Thy heart''s desire display.<br/>Members separate and detached<br/>Ne''er express Thee perfectly,<br/>But Thy Body tempered, built,<br/>Ever shall Thy fulness be.<br/>',NULL,4397,4397);
INSERT INTO stanza VALUES('E839','5','Build me, Lord, with other saints,<br/>Independence ne''er allow,<br/>But according to Thy plan<br/>Fitly frame and join me now.<br/>In experience not my boast,<br/>Nor in gifts would be my pride;<br/>For Thy building I give all,<br/>That Thou may be glorified.<br/>',NULL,4398,4398);
INSERT INTO stanza VALUES('E840','1','Freed from self and Adam''s nature,<br/>Lord, I would be built by Thee<br/>With the saints into Thy temple,<br/>Where Thy glory we shall see.<br/>From peculiar traits deliver,<br/>From my independent ways,<br/>That a dwelling place for Thee, Lord,<br/>We will be thru all our days,<br/>',NULL,4399,4399);
INSERT INTO stanza VALUES('E840','2','By Thy life and by its flowing<br/>I can grow and be transformed,<br/>With the saints coordinated,<br/>Builded up, to Thee conformed;<br/>Keep the order in the Body,<br/>There to function in Thy will,<br/>Ever serving, helping others,<br/>All Thy purpose to fulfill.<br/>',NULL,4400,4400);
INSERT INTO stanza VALUES('E840','3','In my knowledge and experience<br/>I would not exalted be,<br/>But submitting and accepting<br/>Let the Body balance me;<br/>Holding fast the Head, and growing<br/>With His increase, in His way,<br/>By the joints and bands supplying,<br/>Knit together day by day.<br/>',NULL,4401,4401);
INSERT INTO stanza VALUES('E840','4','By Thy Spirit daily strengthened<br/>In the inner man with might,<br/>I would know Thy love surpassing,<br/>Know Thy breadth and length and height;<br/>Ever of Thy riches taking,<br/>Unto all Thy fulness filled,<br/>Ever growing into manhood,<br/>That Thy Body Thou may build.<br/>',NULL,4402,4402);
INSERT INTO stanza VALUES('E840','5','In God''s house and in Thy Body<br/>Builded up I long to be,<br/>That within this corporate vessel<br/>All shall then Thy glory see;<br/>That Thy Bride, the glorious city,<br/>May appear upon the earth,<br/>As a lampstand brightly beaming<br/>To express to all Thy worth.<br/>',NULL,4403,4403);
INSERT INTO stanza VALUES('E841','1','Thou art all my life, Lord,<br/>In me Thou dost live;<br/>With Thee all God''s fulness<br/>Thou to me dost give.<br/>By Thy holy nature<br/>I am sanctified,<br/>By Thy resurrection,<br/>Vict''ry is supplied.<br/>',NULL,4404,4404);
INSERT INTO stanza VALUES('E841','2','Now Thy flowing life, Lord,<br/>Doth enlighten me,<br/>Bringing in the spirit<br/>Fellowship with Thee;<br/>All my need supplying,<br/>Making Thy demand,<br/>Leading me to cleansing<br/>And in Thee to stand.<br/>',NULL,4405,4405);
INSERT INTO stanza VALUES('E841','3','Thy anointing Spirit<br/>Me shall permeate,<br/>All my soul and spirit<br/>Thou wouldst saturate;<br/>Every part transforming<br/>Till conformed to Thee,<br/>Till Thy life shall bring me<br/>To maturity.<br/>',NULL,4406,4406);
INSERT INTO stanza VALUES('E841','4','Lord, Thy life abundant,<br/>Flowing, rich and free,<br/>Constantly refreshes<br/>And empowers me.<br/>Death by life is swallowed,<br/>Weakness is made strong,<br/>All my bonds are broken,<br/>Gloom is turned to song.<br/>',NULL,4407,4407);
INSERT INTO stanza VALUES('E841','5','I would give myself, Lord,<br/>Fully unto Thee,<br/>That Thy heart''s desire<br/>Be fulfilled in me.<br/>I no more would struggle<br/>To myself reform,<br/>Thus in me to hinder<br/>What Thou wouldst perform.<br/>',NULL,4408,4408);
INSERT INTO stanza VALUES('E841','6','I would cease completely<br/>From my efforts vain,<br/>Let Thy life transform me,<br/>Full release to gain;<br/>Build me up with others<br/>Till in us Thou see<br/>Thy complete expression<br/>Glorifying Thee.<br/>',NULL,4409,4409);
INSERT INTO stanza VALUES('E842','1','Breathe Thou, O Lord, on me,<br/>My drooping spirit raise;<br/>Deliver me from fear and death<br/>Into Thy life of praise.<br/>',NULL,4410,4410);
INSERT INTO stanza VALUES('E842','2','Breathe Thou, O Lord, on me,<br/>Strength to my spirit bring,<br/>That running, walking, fainting not,<br/>I''ll mount on eagle''s wings.<br/>',NULL,4411,4411);
INSERT INTO stanza VALUES('E842','3','Breathe Thou, O Lord, on me,<br/>That I may enter rest,<br/>That heart and spirit joyful be<br/>By leaning on Thy breast.<br/>',NULL,4412,4412);
INSERT INTO stanza VALUES('E842','4','Breathe Thou, O Lord, on me,<br/>Till filled with Thee, I plead,<br/>No longer I that live, but Christ<br/>In thought, and word, and deed.<br/>',NULL,4413,4413);
INSERT INTO stanza VALUES('E842','5','Breathe Thou on me and touch<br/>My independency,<br/>That in Thy Body I''ll be built<br/>With all the saints in Thee.<br/>',NULL,4414,4414);
INSERT INTO stanza VALUES('E843','1','Lord, breathe Thy breath of life upon me,<br/>I''m as a bone disjoined and dry;<br/>O may Thou quicken and restore me<br/>And with Thy Body unify.<br/>',NULL,4415,4415);
INSERT INTO stanza VALUES('E843','2','Lord, breathe Thy breath of life upon me,<br/>My spirit is so bound and slow;<br/>O break my shackles and release me,<br/>To mingle in Thy Body''s flow.<br/>',NULL,4416,4416);
INSERT INTO stanza VALUES('E843','3','Lord, breathe Thy breath of life upon me,<br/>My burdened spirit cannot rise;<br/>May Thou encourage and revive me<br/>To share Thy Body''s full supplies.<br/>',NULL,4417,4417);
INSERT INTO stanza VALUES('E843','4','Lord, breathe Thy breath of life upon me,<br/>My barren spirit has not joy;<br/>O may Thou satisfy and bless me,<br/>Thy Body''s riches to enjoy.<br/>',NULL,4418,4418);
INSERT INTO stanza VALUES('E843','5','Lord, breathe Thy breath of life upon me,<br/>To me a true dependence give;<br/>Deal with my death and isolation,<br/>That in Thy Body I may live.<br/>',NULL,4419,4419);
INSERT INTO stanza VALUES('E844','1','Lord, speak Thy Word, upon us breathe;<br/>Behold, dry bones fill all the earth<br/>In graves and scattered ''round in death;<br/>Lord, speak and breathe upon us!<br/>',NULL,4420,4420);
INSERT INTO stanza VALUES('E844','2','Lord, speak Thy Word, upon us breathe,<br/>Revive the bones with quickening breath,<br/>That we may leave our graves, our death;<br/>Lord, speak and breathe upon us!<br/>',NULL,4421,4421);
INSERT INTO stanza VALUES('E844','3','Lord, speak Thy Word, upon us breathe;<br/>Thy people all to make alive,<br/>A mighty host, the foe to drive;<br/>Lord, speak and breathe upon us!<br/>',NULL,4422,4422);
INSERT INTO stanza VALUES('E844','4','Lord, speak Thy Word, upon us breathe;<br/>That all Thy people may be one,<br/>Led by the headship of the Son;<br/>Lord, speak and breathe upon us!<br/>',NULL,4423,4423);
INSERT INTO stanza VALUES('E844','5','Lord, speak Thy Word, upon us breathe;<br/>Thy people fitly frame with grace<br/>To be Thy rest, Thy dwelling-place;<br/>Lord, speak and breathe upon us!<br/>',NULL,4424,4424);
INSERT INTO stanza VALUES('E844','6','Lord, speak to me, upon me breathe,<br/>Revive me, in Thy Body build,<br/>No more secluded and self-willed;<br/>Breathe now, O Lord, upon me!<br/>',NULL,4425,4425);
INSERT INTO stanza VALUES('E844','7','Lord, speak to me, upon me breathe,<br/>That with Thy saints the foe I''ll fight,<br/>That in Thy house Thou may delight,<br/>Breathe now, O Lord, upon me!<br/>',NULL,4426,4426);
INSERT INTO stanza VALUES('E845','1','Release my spirit! This is what I need:<br/>O may my spirit with the saints'' be knit;<br/>No more in private ways Thyself to seek,<br/>But freed from self and for Thy building fit.<br/>',NULL,4427,4427);
INSERT INTO stanza VALUES('E845','2','Release my spirit! This is what I ask,<br/>That self-confined or closed I may not be;<br/>How deep within myself I long have been,<br/>If Thou deliver not, I''ll ne''er be free.<br/>',NULL,4428,4428);
INSERT INTO stanza VALUES('E845','3','Release my spirit! ''Tis for this I pray,<br/>That from myself I fully may come forth;<br/>Thy Spirit then through me may freely flow,<br/>And Thou Thy presence fully may show forth.<br/>',NULL,4429,4429);
INSERT INTO stanza VALUES('E845','4','Release my spirit! This is what I want,<br/>That I from my seclusion may depart;<br/>My private seeking poverty has brought,<br/>Now save from self, Thy wealth to me impart.<br/>',NULL,4430,4430);
INSERT INTO stanza VALUES('E845','5','Release my spirit! This is what I seek,<br/>That prisoned in my self no more I''ll be;<br/>By Satan''s cunning cheated nevermore,<br/>But loosed from self to Thine infinity.<br/>',NULL,4431,4431);
INSERT INTO stanza VALUES('E845','6','Release my spirit! ''Tis for this I yearn,<br/>That self may bind my spirit nevermore;<br/>With all the saints I''d mingle in Thy life,<br/>And all Thou art enjoy forevermore.<br/>',NULL,4432,4432);
INSERT INTO stanza VALUES('E846','1','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>Now I beseech Thee, Lord,<br/>Oh, may it flow!<br/>My past I would forsake,<br/>The iron walls would break,<br/>My spirit free would make;<br/>Oh, may it flow!<br/>',NULL,4433,4433);
INSERT INTO stanza VALUES('E846','2','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>Now I implore Thee, Lord,<br/>Oh, may it flow!<br/>No more self-satisfied,<br/>No more in self-bound pride,<br/>No more my spirit tied;<br/>Oh, may it flow!<br/>',NULL,4434,4434);
INSERT INTO stanza VALUES('E846','3','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>For this I plead with Thee,<br/>Oh, may it flow!<br/>High-minded, not to be,<br/>Pride shall not prison me,<br/>I''d flow unceasingly,<br/>In spirit flow.<br/>',NULL,4435,4435);
INSERT INTO stanza VALUES('E846','4','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>For this I seek Thee, Lord,<br/>Oh, may it flow!<br/>No more to isolate,<br/>Nor self to perfect make,<br/>My spirit nought abate,<br/>Deeply to flow.<br/>',NULL,4436,4436);
INSERT INTO stanza VALUES('E846','5','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>I ask Thee, gracious Lord,<br/>Oh, may it flow!<br/>My trust in self o''erthrow,<br/>Down from self''s throne I''ll go,<br/>That living water flow<br/>In spirit, Lord.<br/>',NULL,4437,4437);
INSERT INTO stanza VALUES('E846','6','Oh, may my spirit flow,<br/>Oh, may it flow!<br/>Answer my prayer, dear Lord,<br/>Oh, may it flow!<br/>Not just commune with Thee,<br/>I long to builded be,<br/>Mingled with others free<br/>In spirit, Lord.<br/>',NULL,4438,4438);
INSERT INTO stanza VALUES('E847','1','I long for fellowship in spirit,<br/>That mingled with the saints I''ll be,<br/>Long to be saved from independence<br/>And to be built with saints in Thee.<br/>',NULL,4439,4439);
INSERT INTO stanza VALUES('E847','2','I long for fellowship in spirit,<br/>That opened shall my spirit be,<br/>Long to be rescued from seclusion,<br/>And with the saints to worship Thee.<br/>',NULL,4440,4440);
INSERT INTO stanza VALUES('E847','3','I long for fellowship in spirit,<br/>Long that my spirit forth may come,<br/>Long to be saved from self-deception,<br/>And every hindrance overcome.<br/>',NULL,4441,4441);
INSERT INTO stanza VALUES('E847','4','I long for fellowship in spirit,<br/>With saints in spirit thus to pray,<br/>Long for deliv''rance from pretension,<br/>Long for true fellowship today.<br/>',NULL,4442,4442);
INSERT INTO stanza VALUES('E847','5','I long for fellowship in spirit,<br/>Long thus to know authority;<br/>Long for true fellowship in service,<br/>Coordinated thus to be.<br/>',NULL,4443,4443);
INSERT INTO stanza VALUES('E847','6','O Lord, fulfill our heart''s deep longing,<br/>Saints for such fellowship inspire,<br/>That we may realize Thy building<br/>And soon fulfill Thy heart''s desire.<br/>',NULL,4444,4444);
INSERT INTO stanza VALUES('E848','1','What a blessing, what a priv''lege!<br/>Called of God a royal priest,<br/>That this glorious, holy office<br/>I should bear, though last and least.<br/>',NULL,4445,4445);
INSERT INTO stanza VALUES('E848','chorus','All the building of the Body<br/>On the priesthood doth depend;<br/>Ever praying in the spirit<br/>I this office would attend.<br/>',NULL,4446,4446);
INSERT INTO stanza VALUES('E848','2','If I keep this royal calling<br/>Under Thine authority,<br/>Priestly duty thus fulfilling,<br/>Then the church will builded be.<br/>',NULL,4447,4447);
INSERT INTO stanza VALUES('E848','3','Now the church is but the priesthood;<br/>Thus the priesthood formed we need;<br/>When the priests are knit together,<br/>Then the church is built indeed.<br/>',NULL,4448,4448);
INSERT INTO stanza VALUES('E848','4','Through the church''s degradation,<br/>Saints this office desolate;<br/>Through the weakness of their spirits<br/>Preaching doth predominate.<br/>',NULL,4449,4449);
INSERT INTO stanza VALUES('E848','5','Most are leaning on the message<br/>And the preaching emphasize,<br/>Yet neglect the priestly praying<br/>And their spirits'' exercise.<br/>',NULL,4450,4450);
INSERT INTO stanza VALUES('E848','6','Deal with me and make me balanced,<br/>As in preaching, so in prayer;<br/>Leading others oft in praying,<br/>As Thy Word I too declare.<br/>',NULL,4451,4451);
INSERT INTO stanza VALUES('E848','7','Only serving by our praying<br/>Will our spirits mingled be;<br/>Stressing prayer as much as preaching-<br/>Thus the church is built for Thee.<br/>',NULL,4452,4452);
INSERT INTO stanza VALUES('E849','1','Holy priests are living stones<br/>For God''s building work today;<br/>If these stones would builded be<br/>All the priest must learn to pray.<br/>',NULL,4453,4453);
INSERT INTO stanza VALUES('E849','chorus','To the holiest often come,<br/>In the spirit touch the throne,<br/>Let the Lord flow thru in prayer,<br/>Thus the building work is done.<br/>',NULL,4454,4454);
INSERT INTO stanza VALUES('E849','2','All the saints must serve as priests,<br/>That the living stones they be;<br/>Each must priestly work perform,<br/>Then their functions we will see.<br/>',NULL,4455,4455);
INSERT INTO stanza VALUES('E849','3','Tent and priests of olden times<br/>Always did together go;<br/>When the priests served in the tent,<br/>Into one the two did flow.<br/>',NULL,4456,4456);
INSERT INTO stanza VALUES('E849','4','Now the building spiritual<br/>And the priesthood all are one;<br/>Now the building of the house<br/>By the priestly work is done.<br/>',NULL,4457,4457);
INSERT INTO stanza VALUES('E849','5','In the priests the substance is<br/>Of the building work replete;<br/>When the priests their work discharge,<br/>Then God''s house will be complete.<br/>',NULL,4458,4458);
INSERT INTO stanza VALUES('E849','6','Building God and man in one<br/>Is their work before the Lord;<br/>In this fellowship divine<br/>Saints are built in one accord.<br/>',NULL,4459,4459);
INSERT INTO stanza VALUES('E849','7','When in prayer our spirits blend,<br/>Then together built are we,<br/>Then a priesthood we become,<br/>Off''ring sacrifice to Thee.<br/>',NULL,4460,4460);
INSERT INTO stanza VALUES('E849','8','Grant us grace, O Lord, that we<br/>Treasure dear the priestly call;<br/>In the spirit serve and pray,<br/>That Thy church be built withal.<br/>',NULL,4461,4461);
INSERT INTO stanza VALUES('E850','1','O Lord, we have loved her fair beauty,<br/>The house Thou hast chosen for Thee,<br/>The courts where Thy gladness rejoiceth,<br/>And where Thou delightest to be.<br/>We love to be made the fair dwelling<br/>Where God in His grace may abide;<br/>We''d cast forth whatever may grieve Thee,<br/>And welcome none other beside.<br/>',NULL,4462,4462);
INSERT INTO stanza VALUES('E850','2','O blessed the grace that has made us<br/>The home of the gladness of God,<br/>The dwelling wherein Thou delightest,<br/>The house Thou hast bought with Thy blood.<br/>''Tis there that Thy joy overfloweth,<br/>We feel it, we take of it there;<br/>By all that Thou workest within us,<br/>Thy temple is holy and fair.<br/>',NULL,4463,4463);
INSERT INTO stanza VALUES('E850','3','The secret of that inner chamber,<br/>Thy place is of heavenly rest;<br/>The stillness of thoughts that adore Thee,<br/>The shrine that Thou lovest the best.<br/>The temple where Christ hath His dwelling,<br/>The souls He hath ransomed, forgiv''n;<br/>The temple where I have my dwelling,<br/>Is Christ in the glory of heav''n.<br/>',NULL,4464,4464);
INSERT INTO stanza VALUES('E851','1','How lovely is Thy dwelling-place!<br/>Within Thy courts I long to be;<br/>Thy presence, Lord, my spirit craves,<br/>For this my heart cries out to Thee.<br/>',NULL,4465,4465);
INSERT INTO stanza VALUES('E851','2','At Thy burnt-offering altar, Lord<br/>And at Thine incense altar blest,<br/>Even the sparrow finds a home,<br/>And swallow there prepares her nest.<br/>',NULL,4466,4466);
INSERT INTO stanza VALUES('E851','3','Men, as the sparrow, frail and small,<br/>When living in Thy house find rest,<br/>Relying on the altar''s blood,<br/>Enjoying there the incense blest.<br/>',NULL,4467,4467);
INSERT INTO stanza VALUES('E851','4','How blessed are those men indeed!<br/>Trusting in Thee they are made strong;<br/>Highways to Zion in their hearts,<br/>The way they care not, rough or long.<br/>',NULL,4468,4468);
INSERT INTO stanza VALUES('E851','5','Passing the weeping valley they<br/>Make it a place of springing wells;<br/>The rain with blessings covers it<br/>And in the way God''s mercy tells.<br/>',NULL,4469,4469);
INSERT INTO stanza VALUES('E851','6','From strength to strength they go, and all<br/>Before the Lord in Zion meet;<br/>Thus ever seeking Thine own self,<br/>They need Thy care and grace replete.<br/>',NULL,4470,4470);
INSERT INTO stanza VALUES('E851','7','Better a day within Thy courts<br/>Than days a thousand I would tell;<br/>I''d rather at Thy threshold stand<br/>Than in the wicked''s tents to dwell.<br/>',NULL,4471,4471);
INSERT INTO stanza VALUES('E851','8','Thou art the sun, Thou art a shield,<br/>Thou grace and glory wilt supply;<br/>Thy presence and Thy very self<br/>My need in fulness satisfy.<br/>',NULL,4472,4472);
INSERT INTO stanza VALUES('E851','9','Not one good thing wilt Thou withhold<br/>From those who walk in uprightness;<br/>Bless''d is the man that trust in Thee<br/>With grace and glory measureless.<br/>',NULL,4473,4473);
INSERT INTO stanza VALUES('E852','1','Thy dwelling-place, O Lord, I love;<br/>It is Thy Church so blessed,<br/>It is Thy joy and heart''s delight<br/>And where Thy heart finds rest.<br/>',NULL,4474,4474);
INSERT INTO stanza VALUES('E852','2','For her, Thyself Thou gavest, Lord,<br/>That she be Thine, complete;<br/>For her, I too my body give,<br/>Thy heart''s desire to meet.<br/>',NULL,4475,4475);
INSERT INTO stanza VALUES('E852','3','For her, Thou hast become my life,<br/>That she my living be;<br/>For her, I would forsake myself,<br/>That she be filled with Thee.<br/>',NULL,4476,4476);
INSERT INTO stanza VALUES('E852','4','The Church is Thy beloved Bride,<br/>Thou in Thy Body seen;<br/>She is my joy and heart''s desire,<br/>The one on whom I lean.<br/>',NULL,4477,4477);
INSERT INTO stanza VALUES('E852','5','In her, Thy full supply, O Lord,<br/>Thou dost to me impart;<br/>In her am I possessed by Thee<br/>To satisfy Thy heart.<br/>',NULL,4478,4478);
INSERT INTO stanza VALUES('E852','6','Thy dwelling-place, O Lord, I love;<br/>It is Thy Church, Thy home;<br/>In it I would forever live<br/>And never longer roam.<br/>',NULL,4479,4479);
INSERT INTO stanza VALUES('E853','1','I love Thy kingdom, Lord,<br/>The house of Thine abode,<br/>The Church our blest Redeemer bought<br/>With His own precious blood.<br/>',NULL,4480,4480);
INSERT INTO stanza VALUES('E853','2','I love the Church, O God!<br/>Her walls before Thee stand,<br/>Dear as the apple of Thine eye<br/>And graven on Thy hand.<br/>',NULL,4481,4481);
INSERT INTO stanza VALUES('E853','3','For her my tears shall fall,<br/>For her my prayers ascend;<br/>To her my cares and toils be given<br/>Till toils and cares shall end.<br/>',NULL,4482,4482);
INSERT INTO stanza VALUES('E853','4','Beyond my highest joy<br/>I prize her heavenly ways,<br/>Her sweet communion, solemn vows,<br/>Her hymns of love and praise.<br/>',NULL,4483,4483);
INSERT INTO stanza VALUES('E853','5','Sure as Thy truth shall last,<br/>To Zion shall be given<br/>The brightest glories earth can yield,<br/>And brighter bliss of heaven.<br/>',NULL,4484,4484);
INSERT INTO stanza VALUES('E854','1','All the saints of Christ are<br/>Members every one;<br/>All coordinating<br/>Into oneness come.<br/>',NULL,4485,4485);
INSERT INTO stanza VALUES('E854','2','Though the gifts are many,<br/>Yet the Spirit one;<br/>Many too the functions,<br/>But one Lord, the Son.<br/>',NULL,4486,4486);
INSERT INTO stanza VALUES('E854','3','Each, the others needing,<br/>Must impartial be;<br/>Each its place possesses<br/>And utility.<br/>',NULL,4487,4487);
INSERT INTO stanza VALUES('E854','4','By our grace are measured<br/>Gifts both large and small;<br/>Each with sober judgment<br/>Takes his place with all.<br/>',NULL,4488,4488);
INSERT INTO stanza VALUES('E854','5','Each fulfills his duty,<br/>Shows his usefulness,<br/>Fervent in the spirit,<br/>Girt with faithfulness.<br/>',NULL,4489,4489);
INSERT INTO stanza VALUES('E854','6','Knitting and supplying,<br/>Bearing much in grace;<br/>Not a trace of discord,<br/>Christ is giv''n His place.<br/>',NULL,4490,4490);
INSERT INTO stanza VALUES('E854','7','We, the Church, His Body,<br/>He, the Head, the Son;<br/>By the Spirit''s flowing,<br/>We are joined in one.<br/>',NULL,4491,4491);
INSERT INTO stanza VALUES('E855','1','Behold, how good, how pleasant ''tis<br/>When brethren dwell in one!<br/>''Tis like the oil on Aaron''s head,<br/>Which to his skirts did run;<br/>As dew of Hermon that descends<br/>On Zion''s mountains o''er;<br/>The Lord His blessing there commands,<br/>E''en life forevermore.<br/>',NULL,4492,4492);
INSERT INTO stanza VALUES('E856','1','How pleasant and how good it is<br/>When brethren in the Lord<br/>In one another''s joy delight<br/>And dwell in sweet accord.<br/>',NULL,4493,4493);
INSERT INTO stanza VALUES('E856','2','Such oneness, like anointing oil<br/>On head to body poured;<br/>Such oneness, like the morning dew,<br/>With sweet refreshment stored.<br/>',NULL,4494,4494);
INSERT INTO stanza VALUES('E856','3','To those who dwell in brotherhood<br/>The Lord His blessing sends,<br/>He crowns them with the bliss of life,<br/>Of life that never ends.<br/>',NULL,4495,4495);
INSERT INTO stanza VALUES('E857','1','How sweet, how heav''nly is the sight,<br/>When those who love the Lord<br/>In one another''s peace delight,<br/>And so fulfill His Word;<br/>',NULL,4496,4496);
INSERT INTO stanza VALUES('E857','2','When each can feel his brother''s sigh,<br/>And with him bear a part;<br/>When sorrow flows from eye to eye,<br/>And joy from heart to heart;<br/>',NULL,4497,4497);
INSERT INTO stanza VALUES('E857','3','When, free from envy, scorn and pride,<br/>Our wishes all above,<br/>Each can his brother''s failings hide,<br/>And show a brother''s love;<br/>',NULL,4498,4498);
INSERT INTO stanza VALUES('E857','4','When love, in one delightful stream,<br/>Through every bosom flows;<br/>When union sweet, and dear esteem,<br/>In every action glows.<br/>',NULL,4499,4499);
INSERT INTO stanza VALUES('E857','5','Love is the golden chain that binds;<br/>The saints Thy grace thus prove.<br/>And he is glory''s heir that finds<br/>His bosom glow with love.<br/>',NULL,4500,4500);
INSERT INTO stanza VALUES('E858','1','All praise to our redeeming Lord,<br/>Who joins us by His grace,<br/>And bids us, each to each restored,<br/>Together seek His face,<br/>Together seek His face.<br/>',NULL,4501,4501);
INSERT INTO stanza VALUES('E858','2','He bids us build each other up;<br/>And, gathered into one,<br/>To our high calling''s glorious hope,<br/>We hand in hand go on,<br/>We hand in hand go on.<br/>',NULL,4502,4502);
INSERT INTO stanza VALUES('E858','3','The gift which He on one bestows,<br/>We all delight to prove;<br/>The grace through every vessel flows,<br/>In purest streams of love,<br/>In purest streams of love.<br/>',NULL,4503,4503);
INSERT INTO stanza VALUES('E858','4','We all partake the joy of one;<br/>The common peace we feel;<br/>A peace to worldly minds unknown,<br/>A joy unspeakable,<br/>A joy unspeakable.<br/>',NULL,4504,4504);
INSERT INTO stanza VALUES('E858','5','And if our fellowship below<br/>In Christ yet be so sweet,<br/>What height of rapture shall we know,<br/>When round His throne we meet,<br/>When round His throne we meet!<br/>',NULL,4505,4505);
INSERT INTO stanza VALUES('E859','1','Let party names no more<br/>The Christian world o''erspread;<br/>Gentile and Jew, and bond and free,<br/>Are one in Christ, their Head.<br/>',NULL,4506,4506);
INSERT INTO stanza VALUES('E859','2','Among the saints on earth<br/>Let mutual love be found;<br/>Heirs of the same inheritance,<br/>With mutual blessings crowned.<br/>',NULL,4507,4507);
INSERT INTO stanza VALUES('E859','3','Let envy, child of hell!<br/>Be banished far away:<br/>Those in sweet fellowship should dwell,<br/>Who the same Lord obey.<br/>',NULL,4508,4508);
INSERT INTO stanza VALUES('E859','4','Thus will the Church below<br/>God''s purpose ever prove;<br/>Where streams of endless pleasure flow,<br/>And every heart is love.<br/>',NULL,4509,4509);
INSERT INTO stanza VALUES('E860','1','Blest be the tie that binds<br/>Our hearts in Christian love;<br/>The fellowship our spirit finds<br/>Is like to that above.<br/>',NULL,4510,4510);
INSERT INTO stanza VALUES('E860','2','Before our Father''s throne,<br/>We pour our ardent prayers;<br/>Our fears, our hopes, our aims are one-<br/>Our comforts and our cares.<br/>',NULL,4511,4511);
INSERT INTO stanza VALUES('E860','3','We share our mutual woes;<br/>Our mutual burdens bear;<br/>And often of each other flows<br/>The sympathizing tear.<br/>',NULL,4512,4512);
INSERT INTO stanza VALUES('E860','4','When we asunder part,<br/>It gives us inward pain;<br/>But we shall still be joining in heart,<br/>And hope to meet again.<br/>',NULL,4513,4513);
INSERT INTO stanza VALUES('E860','5','From sorrow, toil, and pain,<br/>And sin we shall be free;<br/>And perfect love and oneness reign<br/>Through all eternity.<br/>',NULL,4514,4514);
INSERT INTO stanza VALUES('E861','1','God be with you till we meet again;<br/>By His counsels guide, uphold you,<br/>With His sheep in love enfold you;<br/>God be with you till we meet again.<br/>',NULL,4515,4515);
INSERT INTO stanza VALUES('E861','chorus','Till we meet, till we meet,<br/>Till we meet at Jesus'' feet;<br/>Till we meet, till we meet,<br/>God be with you till we meet again.<br/>',NULL,4516,4516);
INSERT INTO stanza VALUES('E861','2','God be with you till we meet again!<br/>''Neath His wings protecting hide you,<br/>Daily manna still provide you;<br/>God be with you till we meet again!<br/>',NULL,4517,4517);
INSERT INTO stanza VALUES('E861','3','God be with you till we meet again!<br/>When life''s perils thick confound you,<br/>Put His arms unfailing round you;<br/>God be with you till we meet again!<br/>',NULL,4518,4518);
INSERT INTO stanza VALUES('E861','4','God be with you till we meet again!<br/>Keep love''s banner floating o''er you,<br/>Smite death''s threatening wave before you;<br/>God be with you till we meet again!<br/>',NULL,4519,4519);
INSERT INTO stanza VALUES('E862','1','Jesus, where''er Thy people meet,<br/>There they behold Thy mercy-seat;<br/>Where''er they seek Thee, Thou art found,<br/>With grace and mercy to abound.<br/>',NULL,4520,4520);
INSERT INTO stanza VALUES('E862','2','For Thou, within no walls confined,<br/>Inhabitest the humble mind;<br/>Such ever bring Thee where they come,<br/>And going, take Thee to their home.<br/>',NULL,4521,4521);
INSERT INTO stanza VALUES('E862','3','Dear Shepherd of Thy chosen few,<br/>Thy former mercies here renew;<br/>Here, to our waiting hearts, proclaim<br/>The sweetness of Thy saving Name.<br/>',NULL,4522,4522);
INSERT INTO stanza VALUES('E862','4','Here may we prove the power of prayer<br/>To strengthen faith and sweeten care;<br/>To teach our faith desires to rise,<br/>And bring Thy light before our eyes.<br/>',NULL,4523,4523);
INSERT INTO stanza VALUES('E862','5','Lord, we are few, but Thou art near;<br/>Nor short Thine arm, nor deaf Thine ear;<br/>Oh, rend the heavens, come quickly down,<br/>And make our waiting hearts Thine own.<br/>',NULL,4524,4524);
INSERT INTO stanza VALUES('E862','6','Command Thy blessing in this hour;<br/>And as the Spirit full of pow''r<br/>With life and vision full this place,<br/>That all Thy purpose we may trace.<br/>',NULL,4525,4525);
INSERT INTO stanza VALUES('E862','7','O Thou, our Head, our Life, our Guide,<br/>May nought in life or death divide<br/>The saints in Thy communion blessed,<br/>That all Thy fulness be expressed.<br/>',NULL,4526,4526);
INSERT INTO stanza VALUES('E863','1','In daily walk and in our meetings too,<br/>Christ is the center, Christ is everything;<br/>''Tis not for form nor doctrine good and true,<br/>But ''tis for Christ alone we''re gathering.<br/>',NULL,4527,4527);
INSERT INTO stanza VALUES('E863','2','Christ is the way and Christ the light of life,<br/>In Him we walk and by Him we are led;<br/>Christ is the living water and the food;<br/>Of Him we drink and we with Him are fed.<br/>',NULL,4528,4528);
INSERT INTO stanza VALUES('E863','3','Christ is the truth, ''tis Him we testify,<br/>Christ is the life, ''tis Him we minister;<br/>Christ is the Lord, ''tis Him we magnify,<br/>Christ is the Head, and we exalt Him here.<br/>',NULL,4529,4529);
INSERT INTO stanza VALUES('E863','4','Christ is the All in all to God and man-<br/>With Him both we and God are satisfied;<br/>Christ, the reality within the Church-<br/>By Him are life and numbers multiplied.<br/>',NULL,4530,4530);
INSERT INTO stanza VALUES('E863','5','By all the hymns and prayers we offer here,<br/>Christ the reality we would express;<br/>All the activities in fellowship-<br/>Christ thus in operation manifest.<br/>',NULL,4531,4531);
INSERT INTO stanza VALUES('E863','6','''Tis in His Name we meet, in Spirit act,<br/>With nothing in our mind to formalize;<br/>''Tis by His pow''r we pray, in unction praise,<br/>And with Himself in spirit exercise.<br/>',NULL,4532,4532);
INSERT INTO stanza VALUES('E863','7','All things forgetting, cleaving unto Christ,<br/>Applying Him until maturity;<br/>Let us count everything but loss for Him,<br/>For Him, our All in all, eternally.<br/>',NULL,4533,4533);
INSERT INTO stanza VALUES('E864','1','Whene''er we meet with Christ endued,<br/>The surplus of His plenitude<br/>We offer unto God as food,<br/>And thus exhibit Christ.<br/>',NULL,4534,4534);
INSERT INTO stanza VALUES('E864','chorus','Let us exhibit Christ,<br/>Let us exhibit Christ;<br/>We''ll bring His surplus to the church<br/>And thus exhibit Christ.<br/>',NULL,4535,4535);
INSERT INTO stanza VALUES('E864','2','In Christ we live, by Christ we fight,<br/>On Christ we labor day and night,<br/>And with His surplus we unite<br/>To thus exhibit Christ.<br/>',NULL,4536,4536);
INSERT INTO stanza VALUES('E864','3','Our life and all we are and do<br/>Is Christ Himself, the substance true,<br/>That every time we meet anew<br/>We may exhibit Christ.<br/>',NULL,4537,4537);
INSERT INTO stanza VALUES('E864','4','In meetings Christ to God we bear<br/>And Christ with one another share,<br/>And Christ with God enjoying there,<br/>We thus exhibit Christ.<br/>',NULL,4538,4538);
INSERT INTO stanza VALUES('E864','5','The risen Christ to God we bring,<br/>And Christ ascended offering,<br/>God''s satisfaction answering,<br/>We thus exhibit Christ.<br/>',NULL,4539,4539);
INSERT INTO stanza VALUES('E864','6','The center and reality,<br/>The atmosphere and ministry,<br/>Of all our meetings is that we<br/>May thus exhibit Christ.<br/>',NULL,4540,4540);
INSERT INTO stanza VALUES('E864','7','The testimony and the prayer,<br/>And all the fellowship we share,<br/>The exercise of gifts, whate''er,<br/>Should just exhibit Christ.<br/>',NULL,4541,4541);
INSERT INTO stanza VALUES('E864','8','The Father we would glorify,<br/>Exalting Christ the Son, thereby<br/>The meeting''s purpose satisfy<br/>That we exhibit Christ.<br/>',NULL,4542,4542);
INSERT INTO stanza VALUES('E865','1','In spirit and in truth, O Lord,<br/>We meet to worship here;<br/>As taught by Christ, the Son of God,<br/>We now in Him draw near.<br/>',NULL,4543,4543);
INSERT INTO stanza VALUES('E865','2','Thank God, He is a Spirit true,<br/>So near, so dear to us;<br/>That we may contact Him in life,<br/>In truth to worship thus.<br/>',NULL,4544,4544);
INSERT INTO stanza VALUES('E865','3','A spirit God has made for us<br/>That we may worship Him,<br/>Not striving, serving outwardly,<br/>But seeking for within.<br/>',NULL,4545,4545);
INSERT INTO stanza VALUES('E865','4','Regenerated by the Lord,<br/>Renewed in mind and heart,<br/>He dwells within us as our life<br/>True worship to impart.<br/>',NULL,4546,4546);
INSERT INTO stanza VALUES('E865','5','We worship here according to<br/>The inner consciousness,<br/>Anointed by His Spirit now<br/>His fulness we express.<br/>',NULL,4547,4547);
INSERT INTO stanza VALUES('E865','6','In truth we serve and worship too,<br/>In shadows nevermore,<br/>In Christ, the one reality,<br/>The Father we adore.<br/>',NULL,4548,4548);
INSERT INTO stanza VALUES('E865','7','To God we offer Christ the Lord<br/>Whom we experience;<br/>With God we too delight in Him,<br/>His light and sweetness sense.<br/>',NULL,4549,4549);
INSERT INTO stanza VALUES('E865','8','In spirit and reality<br/>Together here we meet,<br/>To worship, praise, and fellowship<br/>Around the mercy-seat.<br/>',NULL,4550,4550);
INSERT INTO stanza VALUES('E866','1','Exercise the spirit!<br/>Human thought reject;<br/>Meet with one another,<br/>Body life respect.<br/>',NULL,4551,4551);
INSERT INTO stanza VALUES('E866','2','Exercise the spirit!<br/>All the forms forsake;<br/>Share with one another,<br/>Each of Christ partake.<br/>',NULL,4552,4552);
INSERT INTO stanza VALUES('E866','3','Exercise the spirit!<br/>Natural sense renounce;<br/>Serve with one another,<br/>Christ the Lord announce.<br/>',NULL,4553,4553);
INSERT INTO stanza VALUES('E866','4','Exercise the spirit!<br/>Soulish life deny;<br/>Helping one another,<br/>On the Lord rely.<br/>',NULL,4554,4554);
INSERT INTO stanza VALUES('E866','5','Freed within the spirit<br/>From self-righteousness,<br/>From self-condemnation,<br/>And self-consciousness.<br/>',NULL,4555,4555);
INSERT INTO stanza VALUES('E866','6','Freed within the spirit<br/>From self-will and pride,<br/>From self-love and glory,<br/>All to override.<br/>',NULL,4556,4556);
INSERT INTO stanza VALUES('E866','7','Exercise the spirit,<br/>Victory to claim<br/>By the blood which cleanses<br/>And the mighty Name.<br/>',NULL,4557,4557);
INSERT INTO stanza VALUES('E866','8','Exercise the spirit<br/>Thus to touch the Lord;<br/>Ever by the spirit<br/>Take Him thru His Word.<br/>',NULL,4558,4558);
INSERT INTO stanza VALUES('E866','9','It is by the spirit<br/>Christ is testified;<br/>It is by the spirit<br/>Man is satisfied.<br/>',NULL,4559,4559);
INSERT INTO stanza VALUES('E866','10','Exercise the spirit!<br/>This is what we need!<br/>Exercise the spirit!<br/>May the Lord so lead!<br/>',NULL,4560,4560);
INSERT INTO stanza VALUES('E867','1','As members of the Body<br/>Christ we would manifest,<br/>Each learning how to function<br/>His fulness to express;<br/>We would not be spectators<br/>But each as members move,<br/>None bringing death or damage<br/>But each our profit prove.<br/>',NULL,4561,4561);
INSERT INTO stanza VALUES('E867','2','As in a team we''d never<br/>Act independently,<br/>But in coordination,<br/>Each would dependent be;<br/>Not acting by our choosing<br/>But following the flow,<br/>Distraction never bringing,<br/>The Spirit''s way we''d know.<br/>',NULL,4562,4562);
INSERT INTO stanza VALUES('E867','3','On Christ we here would focus,<br/>No other center make;<br/>With Christ in sweet communion<br/>His riches to partake.<br/>He is our Head and content,<br/>His Body we express;<br/>Whate''er we do while meeting<br/>Himself must manifest.<br/>',NULL,4563,4563);
INSERT INTO stanza VALUES('E867','4','Built up in love together,<br/>Not one would criticize;<br/>To perfect one another,<br/>We all would exercise.<br/>Each one from self delivered,<br/>The natural life forsakes;<br/>In grace each trained in spirit<br/>The Body-life partakes.<br/>',NULL,4564,4564);
INSERT INTO stanza VALUES('E868','1','Ere from our gathering we''re dismissed, dear Lord,<br/>We sing again to thank Thee from our heart,<br/>For Thy dear presence and refreshing grace,<br/>Which Thou so richly didst to us impart.<br/>',NULL,4565,4565);
INSERT INTO stanza VALUES('E868','2','Though now the meeting''s over, in Thy grace,<br/>Thy presence never will from us depart;<br/>But as the Spirit Thy sustaining strength<br/>Thou wouldst in love unceasingly impart.<br/>',NULL,4566,4566);
INSERT INTO stanza VALUES('E868','3','Lord, may Thy presence go with us, we pray,<br/>To bear with us the burden on our heart,<br/>That every moment we Thyself enjoy,<br/>Till in the coming meeting we take part.<br/>',NULL,4567,4567);
INSERT INTO stanza VALUES('E869','1','Ere we depart, we praise Thee, Lord, again<br/>For Thy dear presence and Thy living word;<br/>We are attracted by Thy preciousness,<br/>Our hearts incline to Thee through what we''ve heard.<br/>',NULL,4568,4568);
INSERT INTO stanza VALUES('E869','2','Thy word is spirit and is life to us,<br/>By it we''re nourished, growing, Lord, in Thee;<br/>Thus to Thine image we may be transformed,<br/>With Thy full measure to maturity.<br/>',NULL,4569,4569);
INSERT INTO stanza VALUES('E869','3','Impart Thyself to us, Lord, more and more,<br/>And make us in the spirit walk and move,<br/>That we be kept in fellowship with Thee,<br/>Until we meet again, Thy grace to prove.<br/>',NULL,4570,4570);
INSERT INTO stanza VALUES('E870','1','Stand up! Stand up for Jesus!<br/>Ye soldiers of the cross;<br/>Lift high His royal banner,<br/>It must not suffer loss:<br/>From vict''ry unto vict''ry<br/>His army shall He lead,<br/>Till every foe is vanquished<br/>And Christ is Lord indeed.<br/>',NULL,4571,4571);
INSERT INTO stanza VALUES('E870','chorus','Stand up for Jesus<br/>Ye soldiers of the cross;<br/>Lift high His royal banner,<br/>It must not, it must not suffer loss.<br/>',NULL,4572,4572);
INSERT INTO stanza VALUES('E870','2','Stand up! Stand up for Jesus!<br/>The trumpet call obey;<br/>Forth to the mighty conflict<br/>In this His glorious day.<br/>Ye that are men, now serve Him<br/>Against unnumbered foes;<br/>Let courage rise with danger,<br/>And strength to strength oppose.<br/>',NULL,4573,4573);
INSERT INTO stanza VALUES('E870','3','Stand up! Stand up for Jesus!<br/>Stand in His strength alone;<br/>The arm of flesh will fail you;<br/>Ye dare not trust your own.<br/>Put on the Gospel armor,<br/>And, watching unto prayer,<br/>Where duty calls, or danger,<br/>Be never wanting there.<br/>',NULL,4574,4574);
INSERT INTO stanza VALUES('E870','4','Stand up! Stand up for Jesus!<br/>The strife will not be long:<br/>This day the noise of battle,<br/>The next the victor''s song;<br/>To him that overcometh<br/>A crown of life shall be;<br/>He, with the King of glory,<br/>Shall reign eternally.<br/>',NULL,4575,4575);
INSERT INTO stanza VALUES('E871','1','Onward Christian soldiers!<br/>Marching as to war,<br/>With the cross of Jesus<br/>Going on before.<br/>Christ, the royal Master,<br/>Leads against the foe;<br/>Forward into battle,<br/>See, His banner go!<br/>',NULL,4576,4576);
INSERT INTO stanza VALUES('E871','chorus','Onward Christian soldiers!<br/>Marching as to war,<br/>With the cross of Jesus<br/>Going on before.<br/>',NULL,4577,4577);
INSERT INTO stanza VALUES('E871','2','At the name of Jesus<br/>Satan''s host doth flee;<br/>On then, Christian soldiers,<br/>On to victory!<br/>Hell''s foundations quiver<br/>At the shout of praise:<br/>Brothers, lift your voices,<br/>Loud your anthems raise!<br/>',NULL,4578,4578);
INSERT INTO stanza VALUES('E871','3','Like a mighty army<br/>Moves the Church of God:<br/>Brothers, we are treading<br/>Where the saints have trod;<br/>We are not divided,<br/>All one Body we-<br/>One in faith and Spirit,<br/>One eternally.<br/>',NULL,4579,4579);
INSERT INTO stanza VALUES('E871','4','Crowns and thrones may perish,<br/>Kingdoms rise and wane;<br/>But the Church of Jesus<br/>Constant will remain.<br/>Gates of hell can never<br/>''Gainst the Church prevail;<br/>We have Christ''s own promise,<br/>Which can never fail.<br/>',NULL,4580,4580);
INSERT INTO stanza VALUES('E871','5','Onward, then, ye people!<br/>Join our happy throng;<br/>Blend with ours your voices<br/>In the triumph song.<br/>Glory, laud and honor<br/>Unto Christ, the King;<br/>This through countless ages<br/>Men and angels sing.<br/>',NULL,4581,4581);
INSERT INTO stanza VALUES('E872','1','Fight the good fight with all thy might!<br/>Christ is thy strength, and Christ thy right;<br/>Lay hold on life, and it shall be<br/>Thy joy and crown eternally.<br/>',NULL,4582,4582);
INSERT INTO stanza VALUES('E872','2','Run the straight race through God''s good grace,<br/>Lift up thine eyes, and seek His face;<br/>Life with its way before us lies,<br/>Christ is the path, and Christ the prize.<br/>',NULL,4583,4583);
INSERT INTO stanza VALUES('E872','3','Cast care aside, lean on thy Guide;<br/>His boundless mercy will provide;<br/>Trust, and thy trusting soul shall prove<br/>Christ is its life, and Christ its love.<br/>',NULL,4584,4584);
INSERT INTO stanza VALUES('E872','4','Faint not nor fear, His arms are near,<br/>He changeth not, and thou art dear;<br/>Only believe, and thou shalt see<br/>That Christ is all in all to thee.<br/>',NULL,4585,4585);
INSERT INTO stanza VALUES('E873','1','Charge, soldiers, charge in battle!<br/>The conflict has begun;<br/>Thy battle song triumphant-<br/>''The victory is won!"<br/>Hell''s power must be vanquished<br/>And Satan''s forces strewn;<br/>The Captain of the Army<br/>Will come and triumph soon.<br/>',NULL,4586,4586);
INSERT INTO stanza VALUES('E873','2','Charge, soldiers, charge in battle!<br/>And gaze upon thy Lord;<br/>If thou wilt fight His battle,<br/>The throne is thy reward.<br/>This war is of the spirit,<br/>Not fought on earthly ground;<br/>The Lord well knows the foe is near,<br/>Encircling us around.<br/>',NULL,4587,4587);
INSERT INTO stanza VALUES('E873','3','Charge, soldiers, charge in battle!<br/>Christ''s throne awaiteth thee;<br/>His resurrection power<br/>Will lift thy spirit free.<br/>Through Him thou wilt have power,<br/>The foe to battle down;<br/>Through Him thou wilt the triumph sing,<br/>And wear the victor''s crown.<br/>',NULL,4588,4588);
INSERT INTO stanza VALUES('E873','4','Charge, soldiers, charge in battle!<br/>Thou shalt ascend the throne;<br/>A feast He is preparing,<br/>How happy thou to own.<br/>With Him we''re resurrected<br/>Above the battle din;<br/>Transcending all that binds us,<br/>We''re far above in Him.<br/>',NULL,4589,4589);
INSERT INTO stanza VALUES('E873','5','Charge, soldiers, charge in battle!<br/>Thou art the royal heir;<br/>The Lord from dust did chose thee,<br/>That thou His kingdom share.<br/>Thou hast not part in darkness,<br/>Thy future, O how bright;<br/>With Christ to dwell forever<br/>And in His love delight.<br/>',NULL,4590,4590);
INSERT INTO stanza VALUES('E873','6','With joyful shouts charge forward!<br/>The kingdom is before;<br/>Upon the peak of Zion<br/>We''ll sing, the battle o''er.<br/>The Lamb has won the victory!<br/>The Lamb is on the throne!<br/>With shouts of joy we praise Him,<br/>For He must overcome.<br/>',NULL,4591,4591);
INSERT INTO stanza VALUES('E874','1','Standing in the evil day,<br/>Heeding not what men may say,<br/>Fearing not the face of clay,<br/>Christian soldier, stand.<br/>',NULL,4592,4592);
INSERT INTO stanza VALUES('E874','2','Standing for the Word of God,<br/>Standing for the precious blood,<br/>Following where the saints have trod,<br/>Christian, soldier, stand.<br/>',NULL,4593,4593);
INSERT INTO stanza VALUES('E874','3','Stand ''mid Satan''s every wile,<br/>Stand ''mid pleasure''s wanton smile,<br/>Stand when error would beguile;<br/>Christian soldier, stand.<br/>',NULL,4594,4594);
INSERT INTO stanza VALUES('E874','4','Stand till ends life''s little day,<br/>Stand for Jesus, come what may,<br/>Stand and fight and watch and pray;<br/>Christian soldier, stand.<br/>',NULL,4595,4595);
INSERT INTO stanza VALUES('E875','1','''Tis easy when the morning<br/>Appears at last to view<br/>To praise thy strong Redeemer<br/>Who burst the bondage through,<br/>But ''tis the praise at midnight<br/>That gives the foe alarm,<br/>That glorifies thy Savior,<br/>And bares His strong right arm.<br/>',NULL,4596,4596);
INSERT INTO stanza VALUES('E875','2','If thou wouldst be a conqueror,<br/>Yea, more than conqueror thou,<br/>If thou wilt shout in triumph<br/>And claim the victory now;<br/>The prison-doors will open,<br/>The dungeon gleam with light,<br/>And sin-chained souls around thee<br/>Shall see thy Lord''s great might.<br/>',NULL,4597,4597);
INSERT INTO stanza VALUES('E876','1','When war is hot and fierce,<br/>And Satan strong,<br/>Then firmly trust God''s Word<br/>And sing faith''s song.<br/>',NULL,4598,4598);
INSERT INTO stanza VALUES('E876','2','You need to shout but once,<br/>And you will win;<br/>Oh, do not shut your mouth<br/>And lose therein.<br/>',NULL,4599,4599);
INSERT INTO stanza VALUES('E876','3','If pressed your spirit is<br/>And powerless,<br/>Pray thru the precious blood,<br/>Victorious.<br/>',NULL,4600,4600);
INSERT INTO stanza VALUES('E876','4','The foe though fierce, you can<br/>Still fight with him;<br/>If you will keep your stand,<br/>You soon will win.<br/>',NULL,4601,4601);
INSERT INTO stanza VALUES('E876','5','Therefore you must declare<br/>Christ''s victory;<br/>The situation dark<br/>Soon changed will be.<br/>',NULL,4602,4602);
INSERT INTO stanza VALUES('E877','1','I dare not be defeated<br/>With Calvary in view,<br/>Where Jesus conquered Satan,<br/>Where all His foes He slew;<br/>Come, Lord, and give the vision<br/>To nerve me for the fight,<br/>Make me an overcomer,<br/>Clothed with Thy Spirit''s might.<br/>',NULL,4603,4603);
INSERT INTO stanza VALUES('E877','chorus','A victor, a victor!<br/>Because of Calvary.<br/>Make me an overcomer,<br/>A conqu''ror, a conqu''ror, Lord, in Thee.<br/>',NULL,4604,4604);
INSERT INTO stanza VALUES('E877','2','I dare not be defeated<br/>Since Christ, my conquering King<br/>Has called me to the battle<br/>Which He did surely win.<br/>Come, Lord, and give me courage,<br/>Thy conquering Spirit give,<br/>Make me an overcomer,<br/>In power within me live.<br/>',NULL,4605,4605);
INSERT INTO stanza VALUES('E877','3','I dare not be defeated,<br/>When Jesus leads me on<br/>To press through hellish regions<br/>To share with Him His Throne;<br/>Come, Lord, and give Thy soldier<br/>The power to wield the sword,<br/>Make me an overcomer<br/>Through Thine inerrant Word.<br/>',NULL,4606,4606);
INSERT INTO stanza VALUES('E877','4','I dare not be defeated,<br/>Just at the set of sun,<br/>When Jesus waits to whisper,<br/>"Well done, beloved, well done";<br/>Come, Lord, bend from the Glory,<br/>On me Thy Spirit cast,<br/>Make me an overcomer,<br/>A victor to the last.<br/>',NULL,4607,4607);
INSERT INTO stanza VALUES('E878','1','Conquering now and still to conquer,<br/>Rideth a King in His might,<br/>Leading the host of all the faithful<br/>Into the midst of the fight;<br/>See them with courage advancing,<br/>Clad in their brilliant array,<br/>Shouting the name of their Leader,<br/>Hear them exultingly say:<br/>',NULL,4608,4608);
INSERT INTO stanza VALUES('E878','chorus','"Not to the strong is the battle,<br/>Not to the swift is the race;<br/>Yet to the true and the faithful<br/>Vict''ry is promised through grace."<br/>',NULL,4609,4609);
INSERT INTO stanza VALUES('E878','2','Conquering now and still to conquer,<br/>Who is this wonderful King?<br/>Whence are the armies which He leadeth<br/>While of His glory they sing?<br/>He is our Lord and Redeemer,<br/>Savior and Monarch divine;<br/>They are the stars that forever<br/>Bright in His kingdom will shine.<br/>',NULL,4610,4610);
INSERT INTO stanza VALUES('E878','3','Conquering now and still to conquer,<br/>Jesus, Thou Ruler of all,<br/>Thrones and their scepters all shall perish,<br/>Crowns and their splendor shall fall,<br/>Yet shall the armies Thou leadest<br/>Faithful and true to the last,<br/>Find in Thy kingdom eternal<br/>Rest, when their warfare is past.<br/>',NULL,4611,4611);
INSERT INTO stanza VALUES('E879','1','Christian, dost thou see them<br/>On the holy ground,<br/>How the powers of darkness<br/>Compass thee around?<br/>Christian, up and smite them,<br/>Counting gain but loss;<br/>Smite them by the merit<br/>Of the holy cross.<br/>',NULL,4612,4612);
INSERT INTO stanza VALUES('E879','2','Christian, dost thou feel them,<br/>How they work within,<br/>Striving, tempting, luring,<br/>Goading into sin?<br/>Christian, never tremble,<br/>Never be downcast;<br/>Gird thee for the conflict;<br/>Watch, and pray, and fast.<br/>',NULL,4613,4613);
INSERT INTO stanza VALUES('E879','3','Christian, dost thou hear them,<br/>How they speak thee fair?<br/>"Always fast and vigil,<br/>Always watch and prayer?"<br/>Christian, answer boldly,<br/>"While I breathe I pray";<br/>Peace shall follow battle,<br/>Night shall end in day.<br/>',NULL,4614,4614);
INSERT INTO stanza VALUES('E880','1','To the foe my word is always, "No,"<br/>To the Father it is, "Yes,"<br/>That His plan and all His counsel<br/>Be accomplished with success;<br/>When Thine orders I''m obeying,<br/>Grant me, Lord, authority<br/>To fulfill Thy plan eternal<br/>Thru the Spirit''s power in me.<br/>',NULL,4615,4615);
INSERT INTO stanza VALUES('E880','2','To the foe my word is always, "No,"<br/>To the Father it is, "Yes,"<br/>''Tis my attitude eternal;<br/>May the Lord protect and bless,<br/>Lest while walking in obedience<br/>Satan undermine the way;<br/>When I''m list''ning to Thine orders,<br/>Grant me mercy, Lord, I pray.<br/>',NULL,4616,4616);
INSERT INTO stanza VALUES('E880','3','To the foe my word is always, "No,"<br/>To the Father it is, "Yes,"<br/>I completely would obey Him,<br/>Though deep suff''ring may oppress.<br/>If the Lord will save and keep me,<br/>As I forward press with Him,<br/>Then no trials shall prevent me,<br/>Nor will opposition grim.<br/>',NULL,4617,4617);
INSERT INTO stanza VALUES('E881','1','We rest on Thee, our Shield and our Defender;<br/>We go not forth alone against the foe;<br/>Strong in Thy strength, safe in Thy keeping tender,<br/>We rest on Thee, and in Thy Name we go.<br/>',NULL,4618,4618);
INSERT INTO stanza VALUES('E881','2','Yea, in Thy Name, O Captain of salvation!<br/>In Thy dear Name, all other names above;<br/>Jesus our Righteousness, our sure Foundation,<br/>Our Prince of glory and our King of love.<br/>',NULL,4619,4619);
INSERT INTO stanza VALUES('E881','3','We go in faith, our own great weakness feeling,<br/>And needing more each day Thy grace to know:<br/>Yet from our hearts a song of triumph pealing;<br/>We rest on Thee, and in Thy Name we go.<br/>',NULL,4620,4620);
INSERT INTO stanza VALUES('E881','4','We rest on Thee, our Shield and our Defender:<br/>Thine is the battle, Thine shall be the praise<br/>When reigning in the Kingdom of Thy splendor,<br/>Victors, we rest with Thee, through endless days.<br/>',NULL,4621,4621);
INSERT INTO stanza VALUES('E882','1','Encamped along the hills of light,<br/>Ye Christian soldiers rise,<br/>And press the battle ere the night<br/>Shall veil the glowing skies;<br/>Against the foe in vales below<br/>Let all our strength be hurled;<br/>Faith is the victory, we know,<br/>That overcomes the world.<br/>',NULL,4622,4622);
INSERT INTO stanza VALUES('E882','chorus','Faith is the victory!<br/>Faith is the victory!<br/>O glorious victory,<br/>That overcomes the world.<br/>',NULL,4623,4623);
INSERT INTO stanza VALUES('E882','2','His banner over us is love,<br/>Our sword the Word of God;<br/>We tread the road the saints before<br/>With shouts of triumph trod.<br/>By faith, they like a whirlwind''s breath,<br/>Swept on o''er every field;<br/>The faith by which they conquered death<br/>Is still our shining shield.<br/>',NULL,4624,4624);
INSERT INTO stanza VALUES('E882','3','On every hand the foe we find<br/>Drawn up in dread array;<br/>Let tents of ease be left behind,<br/>And onward to the fray.<br/>Salvation''s helmet on each head,<br/>With truth all girt about,<br/>The earth shall tremble ''neath our tread,<br/>And echo with our shout.<br/>',NULL,4625,4625);
INSERT INTO stanza VALUES('E882','4','To him that overcomes the foe,<br/>White raiment shall be giv''n;<br/>Before the angels he shall know<br/>His name confessed in heav''n;<br/>Then onward from the hills of light,<br/>Our hearts with love aflame,<br/>We''ll vanquish all the host of night,<br/>In Jesus'' conqu''ring name.<br/>',NULL,4626,4626);
INSERT INTO stanza VALUES('E883','1','In the Overcomer''s Name<br/>Be an overcomer too!<br/>Stand and put the foe to shame<br/>All the livelong battle through!<br/>',NULL,4627,4627);
INSERT INTO stanza VALUES('E883','2','Jesus is the Name to sound,<br/>Name to rally fainting hearts!<br/>To recapture "forfeit" ground,<br/>Lost awhile through Satan''s arts.<br/>',NULL,4628,4628);
INSERT INTO stanza VALUES('E883','3','Backward drive the Evil One!<br/>Force him out of every hold;<br/>Smite until the sinking sun<br/>Sets upon the warrior bold!<br/>',NULL,4629,4629);
INSERT INTO stanza VALUES('E883','4','In the Overcomer''s Name<br/>Be an overcomer too!<br/>Stand and put the foe to shame<br/>All the livelong battle through!<br/>',NULL,4630,4630);
INSERT INTO stanza VALUES('E884','1','The Son of God goes forth to war,<br/>A kingly crown to gain;<br/>His blood-red banner streams afar:<br/>Who follows in His train?<br/>Who best can drink his cup of woe,<br/>Triumphant over pain,<br/>Who patient bears his cross below,<br/>He follows in His train.<br/>',NULL,4631,4631);
INSERT INTO stanza VALUES('E884','2','The martyr first, whose eagle eye<br/>Could pierce beyond the grave,<br/>Who saw is Master in the sky,<br/>And called Him to save:<br/>Like Him, with pardon on his tongue,<br/>In midst of mortal pain,<br/>He prayed for them that did the wrong:<br/>Who follows in his train?<br/>',NULL,4632,4632);
INSERT INTO stanza VALUES('E884','3','A glorious band, the chosen few<br/>On whom the Spirit came,<br/>Twelve valiant saints, their hope they knew,<br/>And mocked the cross and flame.<br/>They met the tyrant’s brandished steel,<br/>The lion''s gory mane,<br/>They bowed their necks, the death to feel:<br/>Who follows in his train?<br/>',NULL,4633,4633);
INSERT INTO stanza VALUES('E884','4','A noble army, men and boys,<br/>The matron and the maid,<br/>Around the Savior''s throne rejoice,<br/>In robes of light arrayed.<br/>They climbed by strength divine from heaven,<br/>Through peril, toil, and pain:<br/>O God, to us may grace be given<br/>To follow in their train.<br/>',NULL,4634,4634);
INSERT INTO stanza VALUES('E885','1','Fight the battle in the Body,<br/>Never fight it on your own;<br/>With the Body to the Head joined,<br/>Fight the battle on the throne.<br/>',NULL,4635,4635);
INSERT INTO stanza VALUES('E885','chorus','Fight the battle in the Body!<br/>By the virtue of the Head;<br/>Standing firmly with the Body,<br/>Into vict''ry you''ll be led.<br/>',NULL,4636,4636);
INSERT INTO stanza VALUES('E885','2','For the Body is God''s armor,<br/>Not for anyone alone;<br/>When you wrestle in the Body,<br/>All its benefits you own.<br/>',NULL,4637,4637);
INSERT INTO stanza VALUES('E885','3','''Tis the Church on Christ established<br/>Satan shall not overpow''r;<br/>''Tis the Body built together<br/>Which resists the evil pow''r.<br/>',NULL,4638,4638);
INSERT INTO stanza VALUES('E885','4','In the Body, by the Headship,<br/>Sitting in the heavenlies,<br/>Struggle with the wicked spirits<br/>And the principalities.<br/>',NULL,4639,4639);
INSERT INTO stanza VALUES('E885','5','As a member of the Body,<br/>With the brethren stand for God;<br/>Praying always in the Spirit,<br/>Claim the vict''ry through the Blood.<br/>',NULL,4640,4640);
INSERT INTO stanza VALUES('E885','6','In the heav''nlies more than conqu''ror,<br/>In the power of His might,<br/>As a soldier in the army,<br/>In the Lord the battle fight.<br/>',NULL,4641,4641);
INSERT INTO stanza VALUES('E885','7','Keep on wrestling in the Body,<br/>Mighty vict''ry you will see,<br/>Bind and loose, God''s will fulfilling,<br/>And the foes your food will be.<br/>',NULL,4642,4642);
INSERT INTO stanza VALUES('E886','1','A mighty Fortress is our God,<br/>A Bulwark never failing;<br/>Our Helper He amid the flood<br/>Of mortal ills prevailing:<br/>For still our ancient foe<br/>Doth seek to work us woe;<br/>His craft and power are great,<br/>And, armed with cruel hate,<br/>On earth is not his equal.<br/>',NULL,4643,4643);
INSERT INTO stanza VALUES('E886','2','Did we in our own strength confide,<br/>Our striving would be losing;<br/>Were not the right Man on our side,<br/>The Man of God''s own choosing:<br/>Dost ask who that may be?<br/>Christ Jesus, it is He;<br/>Lord Sabbaoth His Name,<br/>From age to age the same,<br/>And He must win the battle.<br/>',NULL,4644,4644);
INSERT INTO stanza VALUES('E886','3','And though this world, with devils filled,<br/>Should threaten to undo us,<br/>We will not fear, for God hath willed<br/>His truth to triumph through us:<br/>The Prince of Darkness grim,<br/>We tremble not for him;<br/>His rage we can endure,<br/>For lo! His doom is sure,<br/>One little word shall fell him.<br/>',NULL,4645,4645);
INSERT INTO stanza VALUES('E886','4','That word above all earthly powers,<br/>No thanks to them abideth;<br/>The Spirit and the gifts are ours<br/>Through Him who with us sideth:<br/>Let goods and kindred go,<br/>This mortal life also;<br/>The body they may kill:<br/>God''s truth abideth still,<br/>His Kingdom is forever.<br/>',NULL,4646,4646);
INSERT INTO stanza VALUES('E887','1','The name of Jesus is our stand,<br/>It is our victory;<br/>Not on ourselves do we rely,<br/>But, mighty Lord, on Thee.<br/>Our weapons are not arms of flesh,<br/>But ours the Spirit''s sword,<br/>And God''s whole armor putting on,<br/>We battle in the Lord.<br/>',NULL,4647,4647);
INSERT INTO stanza VALUES('E887','2','Behold, the foe doth meet and plot,<br/>Stand firm in one accord!<br/>Though war be fierce and darkness thick,<br/>Resist him in the Lord!<br/>If one thru fear should backward turn,<br/>He undermines the rest.<br/>Oh, do not let your brothers down,<br/>Nor by you be distressed.<br/>',NULL,4648,4648);
INSERT INTO stanza VALUES('E887','3','The devil knows his time is short,<br/>He is the more enraged,<br/>And by his wiles would weaken us<br/>Before the battle''s waged.<br/>The trials now more numerous are,<br/>The suff''ring e''en more sore,<br/>The force of hell opposing us<br/>More dreadful than before.<br/>',NULL,4649,4649);
INSERT INTO stanza VALUES('E887','4','What should our posture be today<br/>In such a desperate hour?<br/>Should we our ease and pleasure seek<br/>And let the foe devour?<br/>Or with increasing conflict strong,<br/>Courageous to endure?<br/>''Tis here that life or death is won!<br/>Who will God''s praise secure?<br/>',NULL,4650,4650);
INSERT INTO stanza VALUES('E887','5','For Christ the Lord we then would stand,<br/>He is the Conqueror!<br/>For Him we would endure the pain<br/>Until the fight is o''er.<br/>The hour of triumph soon we''ll see-<br/>The Lord will come again;<br/>If now we suffer for His sake,<br/>Then we with Him shall reign.<br/>',NULL,4651,4651);
INSERT INTO stanza VALUES('E888','1','Soldiers of Christ arise,<br/>And put your armor on,<br/>Strong in the strength which God supplies,<br/>Through His eternal Son;<br/>Strong in the Lord of Hosts,<br/>And in His mighty pow''r,<br/>Who in the strength of Jesus trusts<br/>Is more than conqueror.<br/>',NULL,4652,4652);
INSERT INTO stanza VALUES('E888','2','Stand then in His great might,<br/>With all His strength endued;<br/>And take, to arm you for the fight,<br/>The panoply of God,<br/>That, having all things done,<br/>And all your conflicts past,<br/>Ye may o''ercome through Christ alone,<br/>And stand complete at last.<br/>',NULL,4653,4653);
INSERT INTO stanza VALUES('E888','3','Leave no unguarded place,<br/>No weakness of the soul,<br/>Take every virtue, every grace,<br/>And fortify the whole.<br/>To keep your armor bright<br/>Attend with constant care,<br/>Still walking in your Captain''s sight<br/>And watching unto prayer.<br/>',NULL,4654,4654);
INSERT INTO stanza VALUES('E888','4','Pray, without ceasing pray,<br/>Your Captain gives the word;<br/>His summons cheerfully obey,<br/>And call upon the Lord:<br/>To God your every want<br/>In instant prayer display;<br/>Pray always; pray, and never faint;<br/>Pray, without ceasing pray.<br/>',NULL,4655,4655);
INSERT INTO stanza VALUES('E888','5','From strength to strength go on;<br/>Wrestle, and fight, and pray;<br/>Tread all the powers of darkness down<br/>And win the well-fought day:<br/>Still let the Spirit cry<br/>In all His soldiers, "Come!"<br/>Till Christ the Lord descend from high,<br/>And take the conquerors home.<br/>',NULL,4656,4656);
INSERT INTO stanza VALUES('E889','1','By the blood of Christ the Victor<br/>Overcome the enemy;<br/>But its virtue and its power<br/>You will win the victory.<br/>',NULL,4657,4657);
INSERT INTO stanza VALUES('E889','chorus','By the blood of Christ the Victor<br/>Overcome the enemy;<br/>By its virtue and its power<br/>You will win the victory.<br/>',NULL,4658,4658);
INSERT INTO stanza VALUES('E889','2','By the blood of Christ the Victor<br/>Counter him who doth accuse;<br/>By the blood for you defending<br/>All the sland''rer''s blame refuse.<br/>',NULL,4659,4659);
INSERT INTO stanza VALUES('E889','3','By the blood of Christ the Victor<br/>God''s sure faithfulness believe;<br/>Thru the blood of your Redeemer<br/>God''s forgiveness now receive.<br/>',NULL,4660,4660);
INSERT INTO stanza VALUES('E889','4','By the blood of Christ the Victor<br/>Your position now declare;<br/>Thru the blood, prevailing ever,<br/>All His vict''ry fully share.<br/>',NULL,4661,4661);
INSERT INTO stanza VALUES('E889','5','By the blood of Christ the Victor<br/>Claim His full authority;<br/>Just apply the blood of Jesus<br/>And defeat the enemy.<br/>',NULL,4662,4662);
INSERT INTO stanza VALUES('E889','6','By the blood of Christ the Victor<br/>Standing in the heavenlies;<br/>In the pow''r of Christ ascended,<br/>Tread the principalities.<br/>',NULL,4663,4663);
INSERT INTO stanza VALUES('E890','1','Hallelujah! Christ is Victor,<br/>Tell with every breath,<br/>That the Savior still is conqu''ror<br/>Over sin and death.<br/>',NULL,4664,4664);
INSERT INTO stanza VALUES('E890','chorus','Hallelujah! Christ is Victor,<br/>Tell where''er you go,<br/>That the Lord is still the conqu''ror,<br/>Over every foe.<br/>',NULL,4665,4665);
INSERT INTO stanza VALUES('E890','2','Hallelujah! Christ is Victor,<br/>Pain and sickness flee,<br/>When we plead the mighty victory<br/>Won on Calvary.<br/>',NULL,4666,4666);
INSERT INTO stanza VALUES('E890','3','Hallelujah! Christ is Victor,<br/>Therefore do and dare;<br/>Go wherever Jesus sends you<br/>In prevailing prayer.<br/>',NULL,4667,4667);
INSERT INTO stanza VALUES('E890','4','Hallelujah! Christ is Victor,<br/>No defeat nor fear<br/>Evermore must dim the vision!<br/>Christ the way will clear.<br/>',NULL,4668,4668);
INSERT INTO stanza VALUES('E890','5','Hallelujah! Christ is Victor,<br/>Soon His voice shall ring,<br/>"Come ye conquerors, come up hither,<br/>Join thy conquering King."<br/>',NULL,4669,4669);
INSERT INTO stanza VALUES('E891','1','O Lord, to conflict new<br/>You daily call your servant;<br/>With joy and spirits fervent<br/>We rise to follow You.<br/>Lead us to battle too,<br/>We are Your soldiers true.<br/>',NULL,4670,4670);
INSERT INTO stanza VALUES('E891','chorus','Our hands empow''r,<br/>Our hearts enflame!<br/>We''ll overcome in Jesus'' name,<br/>We''ll overcome in Jesus'' name!<br/>Our hands empow''r, our hearts enflame!<br/>',NULL,4671,4671);
INSERT INTO stanza VALUES('E891','2','Fully equip us, Lord,<br/>With faith and perseverance,<br/>With wisdom and adherence,<br/>With zeal and love outpoured;<br/>Set us on fire, O Lord,<br/>To win the great reward.<br/>',NULL,4672,4672);
INSERT INTO stanza VALUES('E891','3','We lift up firm and high<br/>The Cross, our banner glorious.<br/>The enemy notorious<br/>By Blood we dare defy.<br/>To self the Cross apply,<br/>On Christ alone rely.<br/>',NULL,4673,4673);
INSERT INTO stanza VALUES('E891','4','Wrestle, suffer and pray!<br/>The end shall be victorious.<br/>The promised crown all-glorious<br/>We shall receive one day.<br/>Wrestle, suffer and pray!<br/>We''ll reign with Christ for aye.<br/>',NULL,4674,4674);
INSERT INTO stanza VALUES('E892','1','With all the pow''r in heav''n and earth<br/>Our resurrected Lord''s endued;<br/>If we unite and live by Him,<br/>The enemy will be subdued.<br/>',NULL,4675,4675);
INSERT INTO stanza VALUES('E892','2','In Jesus'' name we must declare<br/>That we shall overcome the foe;<br/>We draw authority from Him<br/>The serpent''s head to crush below.<br/>',NULL,4676,4676);
INSERT INTO stanza VALUES('E892','3','No matter what, thou mountain high,<br/>In heav''n or earth, where''er thou art,<br/>At any cost we''ll level thee,<br/>In Jesus'' name thou must depart!<br/>',NULL,4677,4677);
INSERT INTO stanza VALUES('E892','4','Faith orders thee "Remove from here,<br/>And be thou cast into the sea!"<br/>We should, we must, we can, we will,<br/>Fulfill God''s purpose faithfully.<br/>',NULL,4678,4678);
INSERT INTO stanza VALUES('E893','1','Conflict today is fierce,<br/>The strength of Satan more;<br/>The cry of battle calling now<br/>Is louder than before.<br/>The rebel voice of hell<br/>E''en stronger now becomes;<br/>But list, the midnight cry resounds,<br/>Behold, I quickly come!<br/>',NULL,4679,4679);
INSERT INTO stanza VALUES('E893','2','Trials more bitter grow,<br/>The fighting doth enlarge;<br/>Hell''s forces rally all their pow''rs<br/>And gather for the charge.<br/>Yet while we wait and watch<br/>And feel the war severe,<br/>We hear the joyful song ring out,<br/>Jesus, the Lord, is near!<br/>',NULL,4680,4680);
INSERT INTO stanza VALUES('E893','3','''Tis harder at the end<br/>The word to testify,<br/>For Satan fights with all his pow''r<br/>Our witness to defy.<br/>Much greater strength we need<br/>The foe to overcome;<br/>How happy when the Lord we see<br/>And all our sighing''s done!<br/>',NULL,4681,4681);
INSERT INTO stanza VALUES('E893','4','Who then will forward go<br/>Strong in His mighty power?<br/>Who then will firmly trust the Lord<br/>Until the vict''ry hour;<br/>Till with the conqu''rors blest,<br/>The triumph song''s begun?<br/>That man will then rejoice to hear,<br/>Behold, I quickly come!<br/>',NULL,4682,4682);
INSERT INTO stanza VALUES('E893','5','Who then will choose God''s best,<br/>And take the narrow track,<br/>Though passing thru the wildest storms,<br/>Yet never turning back?<br/>Who now will dare press on,<br/>Enduring pain and fear?<br/>All such will then rejoice to see<br/>Jesus, the Lord, is near!<br/>',NULL,4683,4683);
INSERT INTO stanza VALUES('E893','6','Though deep the darkness be<br/>We still would onward go,<br/>Till we the day of rapture greet<br/>And glory ''round shall glow.<br/>''Tis there we''ll see the Lord,<br/>And Satan overcome;<br/>The overcomers will rejoice,<br/>Jesus, the Lord, has come!<br/>',NULL,4684,4684);
INSERT INTO stanza VALUES('E894','1','Will you be an overcomer?<br/>Christ is calling now!<br/>Will you then be such a follower,<br/>Though you know not how?<br/>',NULL,4685,4685);
INSERT INTO stanza VALUES('E894','chorus','Will you be an overcomer?<br/>Will you make this choice?<br/>Christ is calling, Christ is calling,<br/>Listen to His voice!<br/>',NULL,4686,4686);
INSERT INTO stanza VALUES('E894','2','Will you be an overcomer?<br/>To the Lord be drawn!<br/>Keep the "first love," never leave it,<br/>Till the break of dawn.<br/>',NULL,4687,4687);
INSERT INTO stanza VALUES('E894','3','Will you be an overcomer?<br/>On His life depend!<br/>Dare to suffer persecution,<br/>Faithful to the end.<br/>',NULL,4688,4688);
INSERT INTO stanza VALUES('E894','4','Will you be an overcomer?<br/>Testimony bear!<br/>Keep away from false religion,<br/>"Hidden manna" share.<br/>',NULL,4689,4689);
INSERT INTO stanza VALUES('E894','5','Will you be an overcomer,<br/>Simple, real, and pure?<br/>Overcome all evil mixture,<br/>Ruling pow''r secure.<br/>',NULL,4690,4690);
INSERT INTO stanza VALUES('E894','6','Will you be an overcomer?<br/>Trust the living Lord!<br/>Keep your "garments" from the deadness,<br/>Win the life-reward.<br/>',NULL,4691,4691);
INSERT INTO stanza VALUES('E894','7','Will you be an overcomer?<br/>Never lukewarm be,<br/>Ne''er content with what you''ve gotten,<br/>More you need to see.<br/>',NULL,4692,4692);
INSERT INTO stanza VALUES('E894','8','Will you be an overcomer?<br/>Christ is calling still!<br/>Will you now be loyal to Him,<br/>His demand fulfill.<br/>',NULL,4693,4693);
INSERT INTO stanza VALUES('E895','1','To the work! To the work! We are servants of God,<br/>Let us follow the path that our Master has trod;<br/>With the might of His power our strength to renew,<br/>Let us do by His grace what He calls us to do.<br/>',NULL,4694,4694);
INSERT INTO stanza VALUES('E895','chorus','Work for Him by His grace;<br/>Work thru Him for His praise;<br/>Work with Him all the days;<br/>And work in Him in many ways.<br/>',NULL,4695,4695);
INSERT INTO stanza VALUES('E895','2','To the work! To the work! Let the hungry be fed;<br/>To the fountain of life let thirsty be led;<br/>In the cross and its vict''ry our glory shall be,<br/>While we herald the tidings, "Salvation is free!"<br/>',NULL,4696,4696);
INSERT INTO stanza VALUES('E895','3','To the work! To the work! In the strength of the Lord,<br/>By the pow''r of His Name, with the light of His Word,<br/>All the slaves of the darkness of Satan set free<br/>And His riches of grace in His glory we''ll see.<br/>',NULL,4697,4697);
INSERT INTO stanza VALUES('E896','1','Go, labor on; spend, and be spent;<br/>Thy joy to do the Father''s will;<br/>It is the way the Master went;<br/>Should not the servant tread it still?<br/>',NULL,4698,4698);
INSERT INTO stanza VALUES('E896','2','Go, labor on: ''tis not for nought;<br/>Thy earthly loss is heav''nly gain;<br/>Men heed thee, love thee, praise thee not;<br/>The Master praises, what are men?<br/>',NULL,4699,4699);
INSERT INTO stanza VALUES('E896','3','Go, labor on: your hands are weak,<br/>Your knees are faint, your souls cast down;<br/>Yet falter not; the prize you seek<br/>Is near, a kingdom and a crown.<br/>',NULL,4700,4700);
INSERT INTO stanza VALUES('E896','4','Go, labor on while it is day,<br/>The world''s dark night is hastening on;<br/>Speed, speed the work, cast sloth away,<br/>It is not thus that souls are won.<br/>',NULL,4701,4701);
INSERT INTO stanza VALUES('E896','5','Men die in darkness at your side,<br/>Without a hope to cheer the tomb;<br/>Take up the torch and wave it wide,<br/>The torch that lights time''s thickest gloom.<br/>',NULL,4702,4702);
INSERT INTO stanza VALUES('E896','6','Press on, faint not, keep watch and pray;<br/>Be wise the erring soul to win;<br/>Go forth into the world''s highway,<br/>Compel the wanderer to come in.<br/>',NULL,4703,4703);
INSERT INTO stanza VALUES('E896','7','Press on, and in thy work rejoice;<br/>For work comes rest, the prize thus won;<br/>Soon shalt thou hear the Master''s voice,<br/>The midnight cry, Behold, I come!<br/>',NULL,4704,4704);
INSERT INTO stanza VALUES('E897','1','Work, for the Day is coming,<br/>Day in the Word foretold,<br/>When, ''mid the scenes triumphant,<br/>Longed for by saints of old,<br/>He, who on earth a stranger<br/>Traversed its paths of pain,<br/>Jesus, the Prince, the Savior,<br/>Comes evermore to reign.<br/>',NULL,4705,4705);
INSERT INTO stanza VALUES('E897','2','Work, for the Day is coming,<br/>Darkness will soon be gone;<br/>Then o''er the night of weeping<br/>Day without end shall dawn,<br/>What now we sow in sadness<br/>Then we shall reap in joy;<br/>Hope will be changed to gladness,<br/>Praise be our blest employ.<br/>',NULL,4706,4706);
INSERT INTO stanza VALUES('E897','3','Work, for the Day is coming,<br/>Made for the saints of light;<br/>Off with the garments dreary,<br/>On with the armor bright:<br/>Soon will the strife be ended,<br/>Soon all our toils below;<br/>Not to the dark we''re tending,<br/>But to the Day we go.<br/>',NULL,4707,4707);
INSERT INTO stanza VALUES('E897','4','Work, for the Day is coming,<br/>Children of light are we;<br/>From Jesus'' bright appearing<br/>Powers of darkness flee.<br/>Out of the mist, at His bidding,<br/>Souls like the dew are born:<br/>O''er all the East are spreading<br/>Tints of the rosy morn.<br/>',NULL,4708,4708);
INSERT INTO stanza VALUES('E897','5','Work, then, the Day is coming,<br/>No time for sighing now;<br/>Prize for the race awaits thee,<br/>Wreaths for the victor''s brow.<br/>Now morning Light is breaking,<br/>Soon will the Day appear;<br/>Night shades appall no longer,<br/>Jesus, our Lord, is near.<br/>',NULL,4709,4709);
INSERT INTO stanza VALUES('E898','1','The love of Christ constraineth;<br/>Oh, let the watchword ring<br/>Till all the world adoring<br/>To Jesus'' feet it bring.<br/>Till north and south the kingdoms<br/>Shall own His glorious sway,<br/>And east and west the nations<br/>Rejoice to see His Day.<br/>',NULL,4710,4710);
INSERT INTO stanza VALUES('E898','2','The love of Christ constraineth;<br/>At home, abroad, where''er<br/>By sea or shore abiding<br/>His Name and mark we bear.<br/>We ask not that our service<br/>Or great or small may be,<br/>If only Thou wilt own it,<br/>Dear Lord, as unto Thee.<br/>',NULL,4711,4711);
INSERT INTO stanza VALUES('E898','3','The love of Christ constraineth;<br/>And we who trust His Word,<br/>Who know and feel its power<br/>To gladder service stirred,<br/>Shall neither faint nor falter,<br/>Though dark the night and long,<br/>And weak our hands that labor;<br/>His strength shall make us strong.<br/>',NULL,4712,4712);
INSERT INTO stanza VALUES('E898','4','The love of Christ constraineth;<br/>Then let us work and pray,<br/>And watch the glad appearing<br/>Of that triumphant day,<br/>When Father, Son, and Spirit,<br/>By every tongue confessed,<br/>All earth His broad dominion<br/>In His dear love shall rest.<br/>',NULL,4713,4713);
INSERT INTO stanza VALUES('E899','1','The work is Thine, O Christ our Lord,<br/>The cause for which we stand;<br/>And being Thine, ''twill overcome<br/>Its foe on every hand.<br/>Yet grains of wheat, before they grow,<br/>Are buried in the earth below;<br/>All that is old doth perish there<br/>To form a life both new and fair:<br/>So too are we from self and sin made free.<br/>',NULL,4714,4714);
INSERT INTO stanza VALUES('E899','2','Through suff''ring Thou, O Christ, didst go<br/>Unto Thy throne above,<br/>And leadest now the selfsame way<br/>Those true in faith and love;<br/>So lead us, then, though suff''rings wait,<br/>To share Thy kingdom''s heav''nly state;<br/>Thy death has broken Satan''s might,<br/>And leads the faithful to the light;<br/>Eternal light, from darkness into light.<br/>',NULL,4715,4715);
INSERT INTO stanza VALUES('E899','3','Thou hast, O Savior, led the way<br/>Through agony and death;<br/>O give, we pray, yet more and more<br/>Thy Spirit''s living breath!<br/>Send messengers o''er land and sea<br/>To bring Thy children all to Thee;<br/>Thy name can save, Thy name makes free;<br/>We consecrate ourselves to Thee<br/>As servants true, as warriors brave and true.<br/>',NULL,4716,4716);
INSERT INTO stanza VALUES('E900','1','Oh, to be nothing, nothing!<br/>Only to lie at His feet,<br/>A broken and emptied vessel-<br/>For the Master''s use made meet!<br/>Emptied that He might fill me<br/>As forth to His service I go;<br/>Broken, that so unhindered,<br/>His life through me might flow.<br/>',NULL,4717,4717);
INSERT INTO stanza VALUES('E900','chorus','Oh, to be nothing, nothing!<br/>Only to lie at His feet,<br/>A broken and emptied vessel-<br/>For the Master''s use made meet!<br/>',NULL,4718,4718);
INSERT INTO stanza VALUES('E900','2','Oh, to be nothing, nothing!<br/>Only as led by His hand-<br/>A messenger at His gateway,<br/>Only waiting for His command;<br/>Only an instrument ready<br/>His praises to sound at His will-<br/>Willing, should He not require me,<br/>In silence to wait on Him still.<br/>',NULL,4719,4719);
INSERT INTO stanza VALUES('E900','3','Oh, to be nothing, nothing!<br/>Painful the humbling may be!<br/>Yet low in the dust I''d lay me<br/>That the world might my Savior see!<br/>Rather be nothing, nothing!<br/>To Him let their voices be raised!<br/>He is the fountain of blessing,<br/>He only is meet to be praised!<br/>',NULL,4720,4720);
INSERT INTO stanza VALUES('E901','1','Lord, how can man e''er preach Thy Word?<br/>He is brittle, crazy glass;<br/>Yet in Thy temple is conferred<br/>This glorious and transcendent place,<br/>To be window through Thy grace.<br/>',NULL,4721,4721);
INSERT INTO stanza VALUES('E901','2','But when Thou dost anneal Thy story<br/>In glass, Thy life to shine within<br/>The holy preachers, light of glory<br/>More radiant grows and more doth win,<br/>Which else shows waterish, bleak, and thin.<br/>',NULL,4722,4722);
INSERT INTO stanza VALUES('E901','3','The life and doctrine blent in one<br/>As light and color mingled, bring<br/>A strong regard; but speech alone<br/>Doth vanish like a flaring thing,<br/>And in the ear, not spirit ring.<br/>',NULL,4723,4723);
INSERT INTO stanza VALUES('E902','1','Shine Thou upon us, Lord,<br/>True Light of men, today,<br/>And through the written Word<br/>Thy very self display;<br/>That so from hearts which burn<br/>With gazing on Thy face,<br/>Thy little ones may learn<br/>The wonders of Thy grace.<br/>',NULL,4724,4724);
INSERT INTO stanza VALUES('E902','2','Breathe Thou upon us, Lord,<br/>Thy Spirit''s living flame,<br/>That so with one accord<br/>Our lips may tell Thy name;<br/>Give Thou the hearing ear,<br/>Fix Thou the wandering thought,<br/>That those we teach may hear<br/>The great things Thou has wrought.<br/>',NULL,4725,4725);
INSERT INTO stanza VALUES('E902','3','Speak Thou for us, O Lord,<br/>In all we say of Thee;<br/>According to Thy Word<br/>Let all our teaching be;<br/>That so Thy lambs may know<br/>Their own true Shepherd''s voice,<br/>Where''er He lead them go,<br/>And in His love rejoice.<br/>',NULL,4726,4726);
INSERT INTO stanza VALUES('E902','4','Live Thou within us, Lord;<br/>Thy mind and will be ours;<br/>Be Thou beloved, adored,<br/>And served with all our powers;<br/>That so our lives may teach<br/>Thy children what Thou art,<br/>And plead, by more than speech,<br/>For Thee with every heart.<br/>',NULL,4727,4727);
INSERT INTO stanza VALUES('E903','1','Lord, speak to me, that I may speak<br/>In living echoes of Thy tone;<br/>As Thou hast sought, so let me seek<br/>Thy erring children lost and lone.<br/>',NULL,4728,4728);
INSERT INTO stanza VALUES('E903','2','O lead me, Lord, that I may lead<br/>The wandering and the wavering feet;<br/>O feed me, Lord, that I may feed<br/>Thy hungering ones with manna sweet.<br/>',NULL,4729,4729);
INSERT INTO stanza VALUES('E903','3','O strengthen me, that while I stand<br/>Firm on the rock, and strong in Thee,<br/>I may stretch out a loving hand<br/>To wrestlers with the troubled sea.<br/>',NULL,4730,4730);
INSERT INTO stanza VALUES('E903','4','O teach me, Lord, that I may teach<br/>The precious things Thou dost impart;<br/>And wing my words, that they may reach<br/>The hidden depths of many a heart.<br/>',NULL,4731,4731);
INSERT INTO stanza VALUES('E903','5','O give Thine own sweet rest to me,<br/>That I may speak with soothing power<br/>A word in season, as from Thee<br/>To weary ones in needful hour.<br/>',NULL,4732,4732);
INSERT INTO stanza VALUES('E903','6','O fill me with Thy fulness, Lord,<br/>Until my very heart o''erflow<br/>In kindling thought and glowing word,<br/>Thy love to tell, Thy praise to show.<br/>',NULL,4733,4733);
INSERT INTO stanza VALUES('E903','7','O use me, Lord, use even me,<br/>Just as Thou wilt, and when, and where,<br/>Until Thy blessed face I see,<br/>Thy rest, Thy joy, Thy glory share!<br/>',NULL,4734,4734);
INSERT INTO stanza VALUES('E904','1','We have a most glorious King;<br/>The heavens, He says, are His throne;<br/>All worlds are His mighty domain,<br/>All kingdoms His scepter shall own.<br/>He dwells with His people below,<br/>He loves in their trials to share;<br/>We dwell with the King for His work,<br/>His burden we willingly bear.<br/>',NULL,4735,4735);
INSERT INTO stanza VALUES('E904','2','I''m dwelling with Jesus my King;<br/>I''ve found where He dwells with His own;<br/>I''ve opened the door of my heart;<br/>He''s made it His temple and throne.<br/>Like Mary I sit at His feet,<br/>Like John I recline on His breast;<br/>His presence is fulness of joy,<br/>His bosom is infinite rest.<br/>',NULL,4736,4736);
INSERT INTO stanza VALUES('E904','3','I dwell with the King for His work,<br/>I''ve part in His glorious plan<br/>To bring in His kingdom to earth<br/>And tell His salvation to man.<br/>The world has its work and rewards,<br/>I count them but folly and loss;<br/>My business is only His work,<br/>My message is only His cross.<br/>',NULL,4737,4737);
INSERT INTO stanza VALUES('E904','4','I dwell with the King for His work,<br/>The work, it is His and not mine;<br/>He plans and prepares it for me<br/>And fills me with power divine.<br/>So duty is changed to delight,<br/>And prayer into praise as I sing;<br/>I dwell with my King for His work<br/>And work in the strength of my King.<br/>',NULL,4738,4738);
INSERT INTO stanza VALUES('E904','5','We''ll dwell with the King for His work<br/>And work thru each day of the year.<br/>Perhaps ere it passes, the King<br/>In glory Himself shall appear.<br/>Oh, then in some closer embrace,<br/>Oh, then in some nobler employ<br/>We''ll dwell with the King for His work<br/>In endless, ineffable joy!<br/>',NULL,4739,4739);
INSERT INTO stanza VALUES('E905','1','O Master, let me walk with Thee<br/>In lowly paths of service free;<br/>Tell me Thy secret, help me bear<br/>The strain of toil, the fret of care.<br/>',NULL,4740,4740);
INSERT INTO stanza VALUES('E905','2','Help me the slow of heart to move<br/>By some clear, winning word of love;<br/>Teach me the wayward feet to stay,<br/>And guide them in the Godward way.<br/>',NULL,4741,4741);
INSERT INTO stanza VALUES('E905','3','Teach me Thy patience; still with Thee<br/>In closer, dearer company,<br/>In work that keeps faith sweet and strong,<br/>In trust that triumphs over wrong.<br/>',NULL,4742,4742);
INSERT INTO stanza VALUES('E905','4','In hope that sends a shining ray<br/>Far down the future''s broad''ning way,<br/>In peace that only Thou canst give,<br/>With Thee, O Master, let me live.<br/>',NULL,4743,4743);
INSERT INTO stanza VALUES('E906','1','How much can we do for our Savior?<br/>How much for our dear fellow man?<br/>The way to do more than we''re able<br/>Is Jesus within to enable;<br/>Thus we can do more than we can.<br/>',NULL,4744,4744);
INSERT INTO stanza VALUES('E906','2','How much can we be for our Savior<br/>In life with its brief, fleeting span?<br/>If Jesus within us is dwelling<br/>Our life and our actions infilling,<br/>We all can do more than we can.<br/>',NULL,4745,4745);
INSERT INTO stanza VALUES('E906','3','How much can we bear for our Savior?<br/>How much for our dear fellow man?<br/>If in us His love is constraining,<br/>If ''neath us His arms are sustaining,<br/>We all can do more that we can.<br/>',NULL,4746,4746);
INSERT INTO stanza VALUES('E906','4','How much can we give for our Savior?<br/>To succor our dear fellow man?<br/>If from us His love is o''erflowing,<br/>Our life will be ever outgoing;<br/>We''ll always do more than we can.<br/>',NULL,4747,4747);
INSERT INTO stanza VALUES('E907','1','Not where we elect to go,<br/>But where Jesus leads the way,<br/>There the living waters flow,<br/>There our darkness turns to day.<br/>',NULL,4748,4748);
INSERT INTO stanza VALUES('E907','2','Not our self-appointed task<br/>Will the Lord''s approval win,<br/>But the work we did not ask,<br/>Finished humbly, just for Him.<br/>',NULL,4749,4749);
INSERT INTO stanza VALUES('E907','3','Not the prayer we long to plead<br/>When we bend before the Throne,<br/>But the touching deeper need<br/>Of the Spirit''s wordless groan.<br/>',NULL,4750,4750);
INSERT INTO stanza VALUES('E907','4','Not the gift we proudly lay<br/>On His altar will He heed,<br/>If our hearts have said Him, "Nay,"<br/>When He whispered, "I have need."<br/>',NULL,4751,4751);
INSERT INTO stanza VALUES('E907','5','Thus we die, and dying live<br/>In the heavenlies with the Lord;<br/>Thus we serve, and pray, and give,<br/>Christ Himself our great Reward.<br/>',NULL,4752,4752);
INSERT INTO stanza VALUES('E908','1','Not of letters, but of spirit,<br/>The New Testamental way;<br/>For ''tis life the spirit giveth,<br/>But the letters always slay.<br/>Outward work God never reckons,<br/>But what''s from the inmost part;<br/>It is not to serve in letter,<br/>But life''s newness to impart.<br/>',NULL,4753,4753);
INSERT INTO stanza VALUES('E908','2','Not just by the outward teachings,<br/>But by His anointing moved;<br/>Not just by the outward pattern,<br/>But by inward vision proved.<br/>Not by human rules or rituals,<br/>But by heaven''s rule within;<br/>Not by human-made decisions,<br/>But by guidance giv''n of Him.<br/>',NULL,4754,4754);
INSERT INTO stanza VALUES('E908','3','Not a dead religion serving,<br/>But in Christ as life to live;<br/>Not theology dispensing,<br/>But a living Christ to give.<br/>Not the knowledge of mere doctrine,<br/>But the message Christ should be;<br/>Not the gifts, the forms, the teachings,<br/>But God''s Christ -- reality.<br/>',NULL,4755,4755);
INSERT INTO stanza VALUES('E908','4','Not objectively to worship,<br/>But to serve Him inwardly;<br/>Not to preach a Christ objective,<br/>But Himself subjectively.<br/>Not just by the Scripture serving,<br/>But in spirit and in life;<br/>Not by flesh, but by the Spirit<br/>Filling, freeing from all strife.<br/>',NULL,4756,4756);
INSERT INTO stanza VALUES('E909','1','In the stream! In the stream! Let us work for the Lord,<br/>By His mind, in His way, as revealed in His Word;<br/>In the flow of His life let us work with His pow''r<br/>For His Kingdom and Church in the time of His hour.<br/>',NULL,4757,4757);
INSERT INTO stanza VALUES('E909','chorus','In the stream! In the stream!<br/>Let us work in the stream!<br/>In the stream! In the stream!<br/>We''ll work as in the heav''nly team!<br/>',NULL,4758,4758);
INSERT INTO stanza VALUES('E909','2','In the stream! In the stream! Let us work with the Lord<br/>In the flow of the Spirit, as taught by His Word;<br/>Never working by self, independent and free,<br/>But in service related in full harmony.<br/>',NULL,4759,4759);
INSERT INTO stanza VALUES('E909','3','In the stream! In the stream! Let us work in the Lord<br/>With the Church, with the saints, in the light of His Word;<br/>Give the Word, life supply to the people in need,<br/>Thus fulfilling God''s plan, in His flow we''ll proceed.<br/>',NULL,4760,4760);
INSERT INTO stanza VALUES('E910','1','The overflow of life is work,<br/>The work should be our living!<br/>What we experience e''er should be<br/>The message we are giving.<br/>When living and the work are one,<br/>The work will be effectual;<br/>When message and the life are one,<br/>The word will be successful.<br/>',NULL,4761,4761);
INSERT INTO stanza VALUES('E910','2','The work must be the fruit of life,<br/>Born thru the Spirit''s flowing<br/>As branches of the Lord, the vine,<br/>Fruit bearing, life bestowing.<br/>''Tis Christ Himself thru us to work,<br/>Himself as life expressing,<br/>And all the riches of His life<br/>To others manifesting.<br/>',NULL,4762,4762);
INSERT INTO stanza VALUES('E910','3','''Tis not a movement borne of man,<br/>But by His power moving;<br/>''Tis not the deeds done outwardly,<br/>But inward action proving.<br/>''Tis not the work of enterprise,<br/>But ''tis His life confessing;<br/>''Tis not to toil for our success,<br/>But ''tis Himself expressing.<br/>',NULL,4763,4763);
INSERT INTO stanza VALUES('E910','4','Our plans, our aims, our energy<br/>We must abandon wholly,<br/>That He may work His plan thru us,<br/>His aim and object solely.<br/>Ourselves, with all we are and have,<br/>To death we must surrender,<br/>That Christ may live Himself thru us<br/>With riches and with splendor.<br/>',NULL,4764,4764);
INSERT INTO stanza VALUES('E911','1','O how blessed is the priest''s life,<br/>Christ to him is all in all:<br/>All His clothing, food, and dwelling,<br/>And His portion therewithal.<br/>',NULL,4765,4765);
INSERT INTO stanza VALUES('E911','chorus','O how blessed is the priest''s life,<br/>Christ to him is all in all:<br/>All His clothing, food, and dwelling,<br/>And His portion therewithal.<br/>',NULL,4766,4766);
INSERT INTO stanza VALUES('E911','2','All the clothing of his service<br/>Is the beauty of the Lord;<br/>Glorious splendor do his garments,<br/>Breast and shoulder-piece afford.<br/>',NULL,4767,4767);
INSERT INTO stanza VALUES('E911','3','When in sacrifice he offers<br/>Christ to God as God has willed,<br/>Then as food he doth enjoy Him<br/>And is with His riches filled.<br/>',NULL,4768,4768);
INSERT INTO stanza VALUES('E911','4','Putting on the Lord as clothing,<br/>Christ without he doth express;<br/>Eating, drinking, with Him mingled,<br/>Christ within doth him possess.<br/>',NULL,4769,4769);
INSERT INTO stanza VALUES('E911','5','Holy, glorious is their dwelling,<br/>''Tis the increase of the Lord;<br/>Here the priests built up together<br/>Unto God a house afford.<br/>',NULL,4770,4770);
INSERT INTO stanza VALUES('E911','6','All his portion, all his living,<br/>Everything the priests possess-<br/>All is Christ and Christ forever,<br/>In His all-inclusiveness.<br/>',NULL,4771,4771);
INSERT INTO stanza VALUES('E912','1','Christ to minister is service<br/>Both to God and others too,<br/>Christ, the surplus, e''er supplying,<br/>Off''ring Him as service true.<br/>',NULL,4772,4772);
INSERT INTO stanza VALUES('E912','chorus','Christ to minister is service<br/>Both to God and others too,<br/>Christ, the surplus, e''er supplying,<br/>Off''ring Him as service true<br/>',NULL,4773,4773);
INSERT INTO stanza VALUES('E912','2','As the Israelites did offer<br/>From the surplus of their land,<br/>Thus some produce reaped of Jesus<br/>Must be in our serving hand.<br/>',NULL,4774,4774);
INSERT INTO stanza VALUES('E912','3','We on Christ, as land, must labor,<br/>Harvest Him for all our fare;<br/>Tasting Him to overflowing,<br/>Christ with others we may share.<br/>',NULL,4775,4775);
INSERT INTO stanza VALUES('E912','4','Holding Christ, as members growing,<br/>Each his function must observe;<br/>Christ receiving, Christ partaking,<br/>To His Body Christ we serve.<br/>',NULL,4776,4776);
INSERT INTO stanza VALUES('E912','5','Fellowship and testimony,<br/>Ministry and worship too,<br/>In all helps and ministrations<br/>Christ is all our service true.<br/>',NULL,4777,4777);
INSERT INTO stanza VALUES('E913','1','Serve and work within the Body,<br/>This the Lord doth signify;<br/>For His purpose is the Body<br/>And with it we must comply.<br/>',NULL,4778,4778);
INSERT INTO stanza VALUES('E913','chorus','Serve and work within the Body,<br/>Never independently;<br/>As the members of the Body,<br/>Functioning relatedly.<br/>',NULL,4779,4779);
INSERT INTO stanza VALUES('E913','2','As the members we''ve been quickened<br/>Not as individuals free;<br/>We must always serve together,<br/>All related mutually.<br/>',NULL,4780,4780);
INSERT INTO stanza VALUES('E913','3','Living stones, we''re built together,<br/>And a house for God must be,<br/>As the holy priesthood serving,<br/>In a blessed harmony.<br/>',NULL,4781,4781);
INSERT INTO stanza VALUES('E913','4','Thus we must be built together,<br/>In position minister;<br/>For the basis of our service<br/>Is the body character.<br/>',NULL,4782,4782);
INSERT INTO stanza VALUES('E913','5','In our ministry and service,<br/>From the Body, our supply;<br/>If detached and isolated,<br/>Out of function we will die.<br/>',NULL,4783,4783);
INSERT INTO stanza VALUES('E913','6','''Tis by serving in the Body<br/>Riches of the Head we share;<br/>''Tis by functioning as members<br/>Christ''s full measure we will bear.<br/>',NULL,4784,4784);
INSERT INTO stanza VALUES('E913','7','To the Head fast holding ever,<br/>That we may together grow,<br/>From the Head supplies incoming<br/>Thru us to the Body flow.<br/>',NULL,4785,4785);
INSERT INTO stanza VALUES('E913','8','Lord, anew we give our bodies;<br/>May we be transformed to prove<br/>All Thy will, to know Thy Body,<br/>And therein to serve and move.<br/>',NULL,4786,4786);
INSERT INTO stanza VALUES('E914','1','For the Church should be our service,<br/>''Tis the perfect will of God;<br/>''Tis the only way of working<br/>Which the Lord''s apostles trod.<br/>',NULL,4787,4787);
INSERT INTO stanza VALUES('E914','chorus','For the Church should be our service,<br/>Not our aims to satisfy;<br/>This, the perfect will of God is,<br/>And with it we must comply.<br/>',NULL,4788,4788);
INSERT INTO stanza VALUES('E914','2','For ''tis God''s eternal purpose<br/>That the Church His vessel be;<br/>He intends that all our service<br/>Build His Church continually.<br/>',NULL,4789,4789);
INSERT INTO stanza VALUES('E914','3','All the gifted persons given<br/>To the Body by the Head<br/>Are to aid the Church''s building,<br/>That to fulness she be led.<br/>',NULL,4790,4790);
INSERT INTO stanza VALUES('E914','4','All the gifts and all the functions,<br/>All the spirit''s power shown,<br/>All the ministries are given<br/>For the Church and that alone.<br/>',NULL,4791,4791);
INSERT INTO stanza VALUES('E914','5','All the preaching of the gospel,<br/>All the teaching ministry,<br/>Every other kind of service<br/>For the Church alone should be.<br/>',NULL,4792,4792);
INSERT INTO stanza VALUES('E914','6','Ministry is for the Churches,<br/>Not the Church for ministry;<br/>All the lampstands are the Churches,<br/>Not a form of ministry.<br/>',NULL,4793,4793);
INSERT INTO stanza VALUES('E914','7','This will keep the Church''s oneness,<br/>Saving us from every sect;<br/>This will ever test our motives,<br/>And our aim will thus correct.<br/>',NULL,4794,4794);
INSERT INTO stanza VALUES('E914','8','Lord, deliver us from our work,<br/>From the work of any sect;<br/>For Thy Church alone we''d labor<br/>And its building up effect.<br/>',NULL,4795,4795);
INSERT INTO stanza VALUES('E915','1','From Greenland''s icy mountains,<br/>From India''s coral strand,<br/>Where Afric''s sunny fountains<br/>Roll down their golden sand;<br/>From many an ancient river,<br/>From many a palmy plain,<br/>They call us to deliver<br/>Their land from error''s chain.<br/>',NULL,4796,4796);
INSERT INTO stanza VALUES('E915','2','What though the spicy breezes<br/>Blow soft on Ceylon''s isle;<br/>Though every prospect pleases,<br/>And only man is vile;<br/>In vain with lavish kindness<br/>The gifts of God are strown;<br/>The heathen, in his blindness,<br/>Bow down to wood and stone.<br/>',NULL,4797,4797);
INSERT INTO stanza VALUES('E915','3','Can we, whose souls are lighted<br/>With wisdom from on high;<br/>Can we to men benighted<br/>The lamp of life deny?<br/>Salvation! O salvation!<br/>The joyful sound proclaim,<br/>Till each remotest nation<br/>Has learned Messiah''s name.<br/>',NULL,4798,4798);
INSERT INTO stanza VALUES('E915','4','Waft, waft, ye winds, His story;<br/>And you, ye waters, roll,<br/>Till, like a sea of glory,<br/>It spreads from pole to pole;<br/>Till o''er our ransomed nature,<br/>The Lamb for sinners slain,<br/>Redeemed, King, Creator,<br/>In bliss returns to reign.<br/>',NULL,4799,4799);
INSERT INTO stanza VALUES('E916','1','Now the Lord our soul has fed,<br/>With Himself, the Living Bread;<br/>Fed us, sitting at His feet,<br/>With the finest of the wheat.<br/>',NULL,4800,4800);
INSERT INTO stanza VALUES('E916','2','We have endless treasure found;<br/>We have all things and abound;<br/>Rich abundance and to spare;<br/>Shall we not the blessing share?<br/>',NULL,4801,4801);
INSERT INTO stanza VALUES('E916','3','For, while we are feasting here,<br/>Starving millions, far and near,<br/>Call us with the bitter cry:<br/>Come and help us, or we die.<br/>',NULL,4802,4802);
INSERT INTO stanza VALUES('E916','4','In this day of full increase,<br/>Shall we, can we, hold our peace?<br/>Staying here we do not well;<br/>Now then, let us go and tell:<br/>',NULL,4803,4803);
INSERT INTO stanza VALUES('E916','5','Tell how He hath set us free,<br/>How He leads triumphantly;<br/>How He satisfies our need;<br/>How His rest is rest indeed.<br/>',NULL,4804,4804);
INSERT INTO stanza VALUES('E916','6','Speak, for we, Thy servants, hear;<br/>Thou hast taught us not to fear;<br/>And whate''er Thy word shall be,<br/>We can do it, Lord, in Thee.<br/>',NULL,4805,4805);
INSERT INTO stanza VALUES('E917','1','Far, far away, in heathen darkness dwelling,<br/>Millions of souls forever may be lost;<br/>Who, who will go, salvation''s story telling,<br/>Looking to Jesus, counting not the cost?<br/>',NULL,4806,4806);
INSERT INTO stanza VALUES('E917','chorus','"All pow''r is given unto me,<br/>All pow''r is given unto me,<br/>Go ye into all the world and preach the gospel,<br/>And lo, I am with you alway."<br/>',NULL,4807,4807);
INSERT INTO stanza VALUES('E917','2','See o''er the world, wide open doors inviting:<br/>Soldiers of Christ, arise and enter in!<br/>Christians, awake! Your forces all uniting,<br/>Send forth the Gospel, break the chains of sin.<br/>',NULL,4808,4808);
INSERT INTO stanza VALUES('E917','3','"Why will ye die?" the voice of God is calling,<br/>"Why will ye die? re-echo in His name:<br/>Jesus hath died to save from death appalling,<br/>Life and salvation therefore go proclaim.<br/>',NULL,4809,4809);
INSERT INTO stanza VALUES('E918','1','Christians, make haste, your mission high fulfilling,<br/>To tell to all the world that God is Light,<br/>That He who made all nation is not willing<br/>One soul should perish, lost in shades of night.<br/>',NULL,4810,4810);
INSERT INTO stanza VALUES('E918','chorus','Publish glad tidings, tidings of peace;<br/>Tidings of Jesus, redemption and release.<br/>',NULL,4811,4811);
INSERT INTO stanza VALUES('E918','2','Behold how many thousands still are lying,<br/>Bound in the darksome prison-house of sin,<br/>With none to tell them of the Savior''s dying<br/>Or of the life He died for them to win.<br/>',NULL,4812,4812);
INSERT INTO stanza VALUES('E918','3','''Tis yours to save from peril of perdition<br/>The soul for whom the Lord His life laid down;<br/>Beware lest, slothful to fulfill your mission,<br/>You lose one jewel that should deck His crown.<br/>',NULL,4813,4813);
INSERT INTO stanza VALUES('E918','4','Proclaim to every people, tongue, and nation<br/>That God, in whom they move and live, is love;<br/>Tell how He stooped to save His lost creation,<br/>And died on earth that men He might approve.<br/>',NULL,4814,4814);
INSERT INTO stanza VALUES('E918','5','Give of your sons to bear the message glorious;<br/>Give of your wealth to speed them on their way;<br/>Pour out your soul for them in prayer victorious,<br/>And all you spend our Savior will repay.<br/>',NULL,4815,4815);
INSERT INTO stanza VALUES('E918','6','He comes again; O brothers, ere you meet Him,<br/>Make known to every heart His saving grace;<br/>Let none whom He hath ransomed fail to greet Him,<br/>Through your neglect unfit to see His face.<br/>',NULL,4816,4816);
INSERT INTO stanza VALUES('E919','1','He shall reign o''er all the earth,<br/>He who wore the crown of thorn,<br/>Whom they deemed of little worth,<br/>Whom they met with hate and scorn;<br/>Send the tidings forth, that all<br/>Humbly at His feet may fall.<br/>',NULL,4817,4817);
INSERT INTO stanza VALUES('E919','2','Long His heritage hath lain<br/>''Neath the false usurper''s sway;<br/>He will claim it back again,<br/>Rout the foes and win the day.<br/>Send the tidings forth, that all<br/>Humbly at His feet may fall.<br/>',NULL,4818,4818);
INSERT INTO stanza VALUES('E919','3','Then, beneath His rule of peace<br/>Heaven shall smile, and earth shall sing,<br/>Ever yielding rich increase<br/>To the honor of the King.<br/>Send the tidings forth, that all<br/>Humbly at His feet may fall.<br/>',NULL,4819,4819);
INSERT INTO stanza VALUES('E919','4','Hasten, Lord, the wondrous hour,<br/>Bid it strike from shore to shore,<br/>Thine the kingdom and the power,<br/>Thine the glory evermore.<br/>Bow each rebel heart, that all<br/>At Thy feet adoring fall.<br/>',NULL,4820,4820);
INSERT INTO stanza VALUES('E920','1','Sound ye the trumpet-call;<br/>Heralds proclaim<br/>Jesus as Lord of all,<br/>Sound forth His fame;<br/>Tell of His great renown,<br/>Lift high the kingly crown,<br/>Let every knee bow down<br/>At His blest name.<br/>',NULL,4821,4821);
INSERT INTO stanza VALUES('E920','2','Who will go forth for Him?<br/>Who will arise?<br/>Though eyes with tears are dim,<br/>Severed love''s ties:<br/>Counting all things but loss,<br/>Earth''s highest gain but dross,<br/>And glorying in the cross,<br/>Who will arise?<br/>',NULL,4822,4822);
INSERT INTO stanza VALUES('E920','3','Go, for the crowning day<br/>Draws ever near;<br/>Time will soon pass away,<br/>Jesus be here:<br/>Raise ye the cross where now<br/>Nations to idols bow;<br/>Dawn o''er the mountain''s brow<br/>Tells He is near.<br/>',NULL,4823,4823);
INSERT INTO stanza VALUES('E920','4','Hark to the trumpet-blast!<br/>Jesus is King!<br/>He comes to reign at last,<br/>All conquering:<br/>Then the wide world shall own,<br/>Bending before His throne,<br/>Jesus is King alone,<br/>Jesus is King!<br/>',NULL,4824,4824);
INSERT INTO stanza VALUES('E921','1','Rescue the perishing,<br/>Care for the dying,<br/>Snatch them in pity from sin and the grave;<br/>Weep o''er the erring one,<br/>Lift up the fallen,<br/>Tell them of Jesus the mighty to save.<br/>',NULL,4825,4825);
INSERT INTO stanza VALUES('E921','chorus','Rescue the perishing,<br/>Care for the dying;<br/>Jesus is merciful,<br/>Jesus will save.<br/>',NULL,4826,4826);
INSERT INTO stanza VALUES('E921','2','Though they are slighting Him,<br/>Still He is waiting,<br/>Waiting the penitent child to receive;<br/>Plead with them earnestly,<br/>Plead with them gently;<br/>He will forgive if they only believe.<br/>',NULL,4827,4827);
INSERT INTO stanza VALUES('E921','3','Down in the human heart,<br/>Crushed by the tempter,<br/>Feelings lie buried that grace can restore;<br/>Touched by a loving heart,<br/>Wakened by kindness,<br/>Chords that are broken will vibrate once more.<br/>',NULL,4828,4828);
INSERT INTO stanza VALUES('E921','4','Rescue the perishing,<br/>Duty demands it;<br/>Strength for thy labor the Lord will provide;<br/>Back to the narrow way<br/>Patiently win them;<br/>Tell the poor wand''rer a Savior has died.<br/>',NULL,4829,4829);
INSERT INTO stanza VALUES('E922','1','To the lost world minister Christ,<br/>Not just by word, but by life,<br/>Imparting Christ by living deeds<br/>To the poor souls living in strife.<br/>',NULL,4830,4830);
INSERT INTO stanza VALUES('E922','chorus','To the lost world minister Christ,<br/>By daily walk making Him known;<br/>Imparting Christ by whom you live,<br/>Share with all men what you own.<br/>',NULL,4831,4831);
INSERT INTO stanza VALUES('E922','2','To the lost world minister Christ,<br/>The precious One you possess,<br/>Imparting Christ to those you love<br/>As all their gain and success.<br/>',NULL,4832,4832);
INSERT INTO stanza VALUES('E922','3','To the lost world minister Christ,<br/>The very Christ you enjoy,<br/>Imparting Christ to all your friends<br/>As all their boast and their joy.<br/>',NULL,4833,4833);
INSERT INTO stanza VALUES('E922','4','To the lost world minister Christ,<br/>Who is your life and your all,<br/>Imparting Christ to all you meet,<br/>All fallen ones, great or small.<br/>',NULL,4834,4834);
INSERT INTO stanza VALUES('E923','1','Go to collect material for the House,<br/>Go to convince dear souls and bring them in;<br/>Bring in the very souls whom God has made,<br/>Bring in the souls usurped by every sin.<br/>',NULL,4835,4835);
INSERT INTO stanza VALUES('E923','2','Go to collect materials for the House,<br/>Go to deliver people from the world,<br/>From all Satanic darkness and deceit,<br/>From the allurements Satan has unfurled.<br/>',NULL,4836,4836);
INSERT INTO stanza VALUES('E923','3','Go to collect materials for the House,<br/>Go to win souls to glorify the Lord;<br/>Go to defeat the enemy of God,<br/>Go, sinners to release, with one accord.<br/>',NULL,4837,4837);
INSERT INTO stanza VALUES('E923','4','Go to collect materials for the House,<br/>Go, Christ proclaiming, on the Body ground;<br/>Go thus in oneness with the faithful saints,<br/>And let the trumpet of the gospel sound.<br/>',NULL,4838,4838);
INSERT INTO stanza VALUES('E924','1','Along the shores of Galilee,<br/>When Christ five thousand fed,<br/>Not one was omitted<br/>In the breaking of the bread.<br/>Today they die in heathen lands,<br/>They die in want and dread,<br/>For they have been omitted<br/>In the breaking of the Bread.<br/>',NULL,4839,4839);
INSERT INTO stanza VALUES('E924','chorus','Lord, I would give them the Bread of Life,<br/>The Living Water too:<br/>My heart cries out, "Oh, here am I,<br/>Ready, Thy will to do."<br/>',NULL,4840,4840);
INSERT INTO stanza VALUES('E924','2','Long years have passed and few have heard<br/>That Jesus Christ had bled,<br/>That they might feed on Him who died<br/>To be the Living Bread.<br/>To gods of stone and wood they cry,<br/>Yet they are never fed,<br/>For they have been omitted<br/>In the breaking of the Bread.<br/>',NULL,4841,4841);
INSERT INTO stanza VALUES('E924','3','Great God, who gave Thine only Son,<br/>Help us, now Spirit-led,<br/>To tell the story of Thy love<br/>To those who ask for bread.<br/>Then gladly will we go or send,<br/>Till this blest news has spread,<br/>And they have been included<br/>In the breaking of the Bread.<br/>',NULL,4842,4842);
INSERT INTO stanza VALUES('E925','1','Outreach of the glorious gospel<br/>Is the flow of life within;<br/>It is by our testimony<br/>That lost sinners we may win.<br/>',NULL,4843,4843);
INSERT INTO stanza VALUES('E925','chorus','Grant us, Lord, the living outflow,<br/>May Thy life through us be seen;<br/>Through us as Thy living vessels<br/>Quicken people from within.<br/>',NULL,4844,4844);
INSERT INTO stanza VALUES('E925','2','It is by the life convincing<br/>That the people may believe;<br/>It is by the life imparting<br/>That the souls may life receive.<br/>',NULL,4845,4845);
INSERT INTO stanza VALUES('E925','3','Always in the Lord abiding,<br/>As the branches fruit to bear;<br/>By the inner life out-flowing<br/>Christ with others we may share.<br/>',NULL,4846,4846);
INSERT INTO stanza VALUES('E925','4','May our living be the preaching,<br/>Making Christ to others known;<br/>Not the word of doctrine-preaching,<br/>But the seed of life be sown.<br/>',NULL,4847,4847);
INSERT INTO stanza VALUES('E926','1','Send Thou, O Lord, to every place<br/>Swift messengers before Thy face,<br/>The heralds of Thy wondrous grace,<br/>Where Thou Thyself wilt come.<br/>',NULL,4848,4848);
INSERT INTO stanza VALUES('E926','2','Send men whose eyes have seen the King!<br/>Men in whose eyes His sweet words ring;<br/>Send such Thy lost ones home to bring;<br/>Send them where Thou wilt come.<br/>',NULL,4849,4849);
INSERT INTO stanza VALUES('E926','3','To bring good news to souls in sin;<br/>The bruised and broken hearts to win;<br/>In every place to bring them in,<br/>Where Thou Thyself wilt come.<br/>',NULL,4850,4850);
INSERT INTO stanza VALUES('E926','4','Gird each one with the Spirit''s sword,<br/>The sword of Thine own deathless word;<br/>And make them conquerors, conquering Lord,<br/>Where Thou Thyself wilt come.<br/>',NULL,4851,4851);
INSERT INTO stanza VALUES('E926','5','Raise up, O Lord the Holy Ghost,<br/>From this broad land a mighty host,<br/>Their war-cry, We will seek the lost,<br/>Where Thou, O Christ, wilt come!<br/>',NULL,4852,4852);
INSERT INTO stanza VALUES('E927','1','O God of burning altar fire,<br/>O God of love''s consuming flame,<br/>Make pure the flame of our desire<br/>To win the lost to seek Thy Name.<br/>',NULL,4853,4853);
INSERT INTO stanza VALUES('E927','2','There is no coldness, Lord, in Thee,<br/>Oh, keep us kindled lest we bring<br/>To our dear Lord of Calvary,<br/>Dead ashes for our offering.<br/>',NULL,4854,4854);
INSERT INTO stanza VALUES('E927','3','Dead ashes, husk of corn for wheat<br/>Lord of our consecration vow,<br/>We gather round Thy wounded feet,<br/>We see the thorn about Thy brow.<br/>',NULL,4855,4855);
INSERT INTO stanza VALUES('E927','4','Oh, by Thy cross and passion, Lord,<br/>Grant us this plea, this sovereign plea,<br/>Save us from choosing peace for sword,<br/>And give us souls to give to Thee.<br/>',NULL,4856,4856);
INSERT INTO stanza VALUES('E928','1','Is your life a channel of blessing?<br/>Is the love of God flowing through you?<br/>Are you telling the lost of the Savior?<br/>Are you ready His service to do?<br/>',NULL,4857,4857);
INSERT INTO stanza VALUES('E928','chorus','Make me a channel of blessing today,<br/>Make me a channel of blessing, I pray;<br/>My life possessing, my service blessing,<br/>Make me a channel of blessing today.<br/>',NULL,4858,4858);
INSERT INTO stanza VALUES('E928','2','Is your life a channel of blessing?<br/>Are you burdened for those that are lost?<br/>Have you urged upon those who are straying,<br/>The Savior who died on the cross?<br/>',NULL,4859,4859);
INSERT INTO stanza VALUES('E928','3','We cannot be channels of blessing<br/>If our lives are not free from all sin;<br/>We will barriers be and a hindrance<br/>To those we are trying to win.<br/>',NULL,4860,4860);
INSERT INTO stanza VALUES('E929','1','Out in the highways and byways of life,<br/>Many are weary and sad;<br/>Carry the sunshine where darkness is rife,<br/>Making the sorrowing glad.<br/>',NULL,4861,4861);
INSERT INTO stanza VALUES('E929','chorus','Make me a blessing, make me a blessing,<br/>Out of my life may Jesus shine;<br/>Make me a blessing, O Savior, I pray,<br/>Make me a blessing to someone today.<br/>',NULL,4862,4862);
INSERT INTO stanza VALUES('E929','2','Tell the sweet story of Christ and His love,<br/>Tell of His pow''r to forgive;<br/>Others will trust Him if only you prove<br/>True, every moment you live.<br/>',NULL,4863,4863);
INSERT INTO stanza VALUES('E929','3','Give as ''twas given to you in your need,<br/>Love as the Master loved you;<br/>Be to the helpless a helper indeed,<br/>Unto your mission be true.<br/>',NULL,4864,4864);
INSERT INTO stanza VALUES('E930','1','"Must I go, and empty-handed,"<br/>Thus my dear Redeemer meet?<br/>Not one day of service give Him,<br/>Lay no trophy at His feet?<br/>',NULL,4865,4865);
INSERT INTO stanza VALUES('E930','chorus','"Must I go, and empty-handed?"<br/>Must I meet my Savior so?<br/>Not one soul with which to greet Him:<br/>Must I empty-handed go?<br/>',NULL,4866,4866);
INSERT INTO stanza VALUES('E930','2','Not at death I shrink nor falter,<br/>For my Savior saves me now;<br/>But to meet Him empty-handed,<br/>Thought of that now clouds my brow.<br/>',NULL,4867,4867);
INSERT INTO stanza VALUES('E930','3','O the years in sinning wasted;<br/>Could I but recall them now,<br/>I would give them to my Savior,<br/>To His will I''d gladly bow.<br/>',NULL,4868,4868);
INSERT INTO stanza VALUES('E930','4','O ye saints, arouse, be earnest,<br/>Up the work while yet ''tis day;<br/>Ere the night of death o''ertake thee,<br/>Strive for souls while still you may.<br/>',NULL,4869,4869);
INSERT INTO stanza VALUES('E931','1','Out of the darkness,<br/>Shadowed by sin,<br/>Souls are in bondage,<br/>Souls we would win.<br/>How can we win them?<br/>How show the way?<br/>"Love never faileth,"<br/>Love is the way.<br/>',NULL,4870,4870);
INSERT INTO stanza VALUES('E931','2','Think how the Savior<br/>Came from above<br/>Suffered on Calvary,<br/>Breathed out love;<br/>Think how He loves us,<br/>E''en when we stray:<br/>We must love others,<br/>Love is His way.<br/>',NULL,4871,4871);
INSERT INTO stanza VALUES('E931','3','See, they are waiting,<br/>Looking at you,<br/>Silently watching<br/>All that you do;<br/>Seeming so careless,<br/>Hardened and lost;<br/>"Love never faileth,"<br/>Count not the cost.<br/>',NULL,4872,4872);
INSERT INTO stanza VALUES('E931','4','"Love never faileth,"<br/>Love is pure gold:<br/>Love is what Jesus<br/>Come to unfold;<br/>Love these souls thru us,<br/>Savior, we pray;<br/>Thy love ne''er faileth,<br/>Love is Thy way.<br/>',NULL,4873,4873);
INSERT INTO stanza VALUES('E932','1','Lord, lay some soul upon my heart,<br/>And love that soul through me;<br/>And may I bravely do my part<br/>To win that soul for Thee.<br/>',NULL,4874,4874);
INSERT INTO stanza VALUES('E932','chorus','Some soul for Thee, some soul for Thee,<br/>This is my earnest plea;<br/>Help me each day, on life''s highway,<br/>To win some soul for Thee.<br/>',NULL,4875,4875);
INSERT INTO stanza VALUES('E932','2','Lord, lead me to some soul to sin,<br/>And grant that I may be<br/>Endured with power and love to win<br/>That soul, dear Lord, for Thee.<br/>',NULL,4876,4876);
INSERT INTO stanza VALUES('E932','3','To win that soul for Thee, my Lord,<br/>Will be my constant prayer;<br/>That when I''ve won Thy full reward<br/>I''ll with that dear one share.<br/>',NULL,4877,4877);
INSERT INTO stanza VALUES('E933','1','I have a Savior, He''s pleading in glory,<br/>A dear loving Savior, though earth-friends be few;<br/>And now He is watching in tenderness o''er me,<br/>But oh, that my Savior were your Savior too!<br/>',NULL,4878,4878);
INSERT INTO stanza VALUES('E933','chorus','For you I am praying,<br/>For you I am praying,<br/>For you I am praying,<br/>I''m praying for you.<br/>',NULL,4879,4879);
INSERT INTO stanza VALUES('E933','2','I have a Father: to me He has given<br/>A hope for eternity, blessed and true;<br/>He''ll call me one day to the kingdom of heaven,<br/>But oh, that He''d let me bring you with me too!<br/>',NULL,4880,4880);
INSERT INTO stanza VALUES('E933','3','I have a peace: it is calm as river,<br/>A peace that the friends of this world never knew;<br/>My Savior alone is its Author and Giver,<br/>And oh, could I know it was given to you!<br/>',NULL,4881,4881);
INSERT INTO stanza VALUES('E934','1','I cannot tell why He, whom angels worship,<br/>Should set His love upon the sons of men,<br/>Or why, as Shepherd, He should seek the wand''rers,<br/>To bring them back, they know not how or when.<br/>But this I know, that He was born of Mary,<br/>When Bethl''hem''s manager was His only home,<br/>And that He lived at Nazareth and labored,<br/>And so the Savior, Savior of the world, is come.<br/>',NULL,4882,4882);
INSERT INTO stanza VALUES('E934','2','I cannot tell how silently He suffered,<br/>As with His peace He graced this place of tears,<br/>Or how His heart upon the cross was broken,<br/>The crown of pain to three and thirty years.<br/>But this I know, He heals the broken-hearted,<br/>And stays our sin, and calms our lurking fear,<br/>And lifts the burden from the heavy laden,<br/>For yet the Savior, Savior of the world, is here.<br/>',NULL,4883,4883);
INSERT INTO stanza VALUES('E934','3','I cannot tell how He will win the nations,<br/>How He will claim His earthly heritage,<br/>How satisfy the needs and aspirations<br/>Of east and west, of sinner and of sage.<br/>But this I know, all flesh shall see His glory,<br/>And He shall reap the harvest He has sown,<br/>And some glad day His sun shall shine in splendor<br/>When He the Savior, Savior of the world, is known.<br/>',NULL,4884,4884);
INSERT INTO stanza VALUES('E934','4','I cannot tell how all the lands shall worship,<br/>When, at His bidding, every storm is stilled,<br/>Or who can say how great the jubilation<br/>When all the hearts of men with love are filled.<br/>But this I know, the skies will thrill with rapture,<br/>And myriad, myriad human voices sing,<br/>And earth to heaven, and heaven to earth, will answer:<br/>At last the Savior, Savior of the world, is King.<br/>',NULL,4885,4885);
INSERT INTO stanza VALUES('E935','1','Around Thy grave, Lord Jesus,<br/>In spirit here we stand,<br/>With hearts all full of praises,<br/>To keep Thy blest command:<br/>Our souls by faith rejoicing,<br/>To trace Thy path of love,<br/>Down through death''s angry billows,<br/>Up to the throne above.<br/>',NULL,4886,4886);
INSERT INTO stanza VALUES('E935','2','Lord Jesus! We remember<br/>The travail of Thy soul,<br/>When through Thy love''s deep pity,<br/>The waves did o''er Thee roll;<br/>Baptized in death''s dark waters,<br/>For us Thy blood was shed;<br/>For us Thou, Lord of Glory,<br/>Wast numbered with the dead.<br/>',NULL,4887,4887);
INSERT INTO stanza VALUES('E935','3','O Lord! Thou now art risen,<br/>Thy travail all is o''er;<br/>For sin Thou once hast suffered,<br/>Thou liv''st to die no more;<br/>Sin, death and hell are vanquished<br/>By Thee, the Church''s Head;<br/>And lo! We share Thy triumphs,<br/>Thou first-born from the dead.<br/>',NULL,4888,4888);
INSERT INTO stanza VALUES('E935','4','Unto Thy death baptized,<br/>We own with Thee we died;<br/>With Thee, our Life, we''re risen,<br/>And shall be glorified.<br/>From sin, the world, and Satan,<br/>We''re ransomed by Thy blood,<br/>And here would walk as strangers,<br/>Alive with Thee to God.<br/>',NULL,4889,4889);
INSERT INTO stanza VALUES('E936','1','In death''s waters I am buried,<br/>For with Christ my Savior, I have died;<br/>Now the world cannot pursue me,<br/>For its power here is nullified.<br/>I with Christ have risen too,<br/>Out of death with Him I walk and live;<br/>Now the Spirit life supplies<br/>And His strength exhaustless unto me doth give.<br/>',NULL,4890,4890);
INSERT INTO stanza VALUES('E937','1','Lord, when by baptism we confess<br/>Our oneness in Thy death,<br/>Oh, by Thy mercy and Thy grace,<br/>May Thou reveal its worth.<br/>',NULL,4891,4891);
INSERT INTO stanza VALUES('E937','2','By baptism in Thy death we''re one<br/>And buried too with Thee;<br/>Thus we''re forever dead to sin<br/>And from its bondage free.<br/>',NULL,4892,4892);
INSERT INTO stanza VALUES('E937','3','By baptism in Thy death we''re one<br/>And buried too with Thee;<br/>Thus to the world we bid farewell,<br/>From Satan''s slavery free.<br/>',NULL,4893,4893);
INSERT INTO stanza VALUES('E937','4','We''re resurrected with Thee too,<br/>From death''s great pow''r set free;<br/>Now fruit of holiness we bear<br/>In our new life with Thee.<br/>',NULL,4894,4894);
INSERT INTO stanza VALUES('E937','5','We''re baptized unto Thy dear name,<br/>No more our own are we;<br/>Thy steps we''d follow, for Thee live,<br/>And e''er be one with Thee.<br/>',NULL,4895,4895);
INSERT INTO stanza VALUES('E938','1','Already dead! And buried too!<br/>With the old man I am through!<br/>Already dead! And buried too!<br/>With the old man I am through!<br/>',NULL,4896,4896);
INSERT INTO stanza VALUES('E938','2','No longer I! No longer I!<br/>Christ in me I''ll testify!<br/>No longer I! No longer I!<br/>Christ in me I''ll testify!<br/>',NULL,4897,4897);
INSERT INTO stanza VALUES('E939','1','O day of resurrection,<br/>O day of joy and light,<br/>O seal of our redemption,<br/>Most beautiful, most bright:<br/>On thee the high and lowly,<br/>Bending before the throne,<br/>Sing "Holy, holy, holy,"<br/>To the great Three in One.<br/>',NULL,4898,4898);
INSERT INTO stanza VALUES('E939','2','On thee at the creation<br/>The light first had its birth;<br/>On thee, for our salvation,<br/>Christ rose from depths of earth;<br/>On thee, our Lord, victorious,<br/>The Spirit sent from heaven;<br/>And thus on thee, most glorious,<br/>A triple light was given.<br/>',NULL,4899,4899);
INSERT INTO stanza VALUES('E939','3','Today on weary nations<br/>The heavenly manna falls!<br/>To holy convocations<br/>The silver trumpet calls,<br/>Where gospel light is glowing<br/>With pure and radiant beams,<br/>And living water flowing<br/>With soul-refreshing streams.<br/>',NULL,4900,4900);
INSERT INTO stanza VALUES('E939','4','New graces ever gaining<br/>From this of days the best,<br/>We reach the rest remaining<br/>For people who are blest;<br/>To Holy Ghost be praises,<br/>To Father and to Son;<br/>The Church her voice upraises<br/>To Thee, blest Three in One.<br/>',NULL,4901,4901);
INSERT INTO stanza VALUES('E940','1','Passing through another week,<br/>God has granted us His aid;<br/>Let us now a blessing seek,<br/>On the day the Lord hath made;<br/>Day of all the week the best,<br/>Emblem of eternal rest.<br/>Day of all the week the best,<br/>Emblem of eternal rest.<br/>',NULL,4902,4902);
INSERT INTO stanza VALUES('E940','2','While we pray for pard''ning grace,<br/>Through the dear Redeemer''s name,<br/>Show Thy reconciled face;<br/>Take away our sin and shame:<br/>From our worldly cares set free,<br/>May we rest this day in Thee.<br/>From our worldly cares set free,<br/>May we rest this day in Thee.<br/>',NULL,4903,4903);
INSERT INTO stanza VALUES('E940','3','Here we come Thy name to praise,<br/>Let us feel Thy presence near;<br/>May Thy glory meet our eyes,<br/>While we in Thy house appear:<br/>Here afford us, Lord, a taste<br/>Of our everlasting feast.<br/>Here afford us, Lord, a taste<br/>Of our everlasting feast.<br/>',NULL,4904,4904);
INSERT INTO stanza VALUES('E940','4','May Thy gospel''s joyful sound<br/>Conquer sinners, comfort saints;<br/>Make the fruits of grace abound,<br/>Bring relief for all complaints:<br/>Thus may all our Lord''s Days prove,<br/>Till we meet the Lord above.<br/>Thus may all our Lord''s Days prove,<br/>Till we meet the Lord above.<br/>',NULL,4905,4905);
INSERT INTO stanza VALUES('E941','1','God''s kingdom is God''s reigning,<br/>His glory to maintain;<br/>It is His sovereign ruling,<br/>His order to sustain.<br/>He exercises fully<br/>His own authority<br/>Within His kingdom ever<br/>And to eternity.<br/>',NULL,4906,4906);
INSERT INTO stanza VALUES('E941','2','Upon the throne, the center<br/>Of government divine,<br/>God reigns, and with His purpose<br/>Brings everything in line.<br/>God''s headship and His lordship<br/>He only can maintain<br/>As King within His kingdom,<br/>O''er everything to reign.<br/>',NULL,4907,4907);
INSERT INTO stanza VALUES('E941','3','By reigning in His kingdom<br/>God worketh all His will,<br/>And under His dominion<br/>His purpose doth fulfill.<br/>''Tis only in God''s kingdom<br/>His blessing we may know;<br/>''Tis from His throne almighty<br/>The streams of life doth flow.<br/>',NULL,4908,4908);
INSERT INTO stanza VALUES('E941','4','Submitted to God''s ruling,<br/>All virtue thus will win;<br/>Rebellion to His Headship<br/>Is but the root of sin.<br/>The evil aim of Satan-<br/>God''s throne to overthrow;<br/>Our aim and goal is ever<br/>His rule to fully know.<br/>',NULL,4909,4909);
INSERT INTO stanza VALUES('E941','5','Within God''s sovereign kingdom<br/>His Christ is magnified;<br/>When Christ in life is reigning,<br/>The Father''s glorified.<br/>When God is in dominion,<br/>All things are truly blessed;<br/>When Christ for God is reigning,<br/>God''s glory is expressed.<br/>',NULL,4910,4910);
INSERT INTO stanza VALUES('E941','6','In fulness of the seasons<br/>God''s Christ will head up all,<br/>Then all will own His reigning<br/>And worship, great and small.<br/>Such reign in life and glory<br/>The Church e''en now foretastes,<br/>And to His rule submitting<br/>Unto His kingdom haste.<br/>',NULL,4911,4911);
INSERT INTO stanza VALUES('E942','1','God''s Kingdom on the earth is now<br/>His sovereign government within;<br/>''Tis Christ Himself in us to live<br/>As Lord and King to rule and reign.<br/>',NULL,4912,4912);
INSERT INTO stanza VALUES('E942','2','His life with His authority<br/>Enthrones Him now within our hearts<br/>To govern all our words and deeds<br/>And regulate our inward parts.<br/>',NULL,4913,4913);
INSERT INTO stanza VALUES('E942','3','The Lord enthroned within our hearts<br/>His Kingdom doth establish there,<br/>Assuring His full right to reign<br/>And for God''s purpose to prepare.<br/>',NULL,4914,4914);
INSERT INTO stanza VALUES('E942','4','''Tis by His reign within our hearts<br/>That life to us He e''er supplies;<br/>When taking Him as Lord and King,<br/>His wealth our being satisfies.<br/>',NULL,4915,4915);
INSERT INTO stanza VALUES('E942','5','''Tis by His ruling from within<br/>His fulness vast is testified;<br/>''Tis when His inner kingdom rules<br/>His Body''s blessed and edified.<br/>',NULL,4916,4916);
INSERT INTO stanza VALUES('E942','6','''Tis by His heav''nly rule within<br/>As heav''nly citizens we live;<br/>''Tis by submission to His rule<br/>Expression of His reign we give.<br/>',NULL,4917,4917);
INSERT INTO stanza VALUES('E942','7','Here in this heav''nly realm we live,<br/>And with this heav''nly pow''r possessed<br/>We walk and fight in heav''nly light<br/>Until the Kingdom''s manifest.<br/>',NULL,4918,4918);
INSERT INTO stanza VALUES('E943','1','Requirements of the Kingdom are<br/>Much stricter than the law''s decrees;<br/>No other requisite of God<br/>Has ever higher been than these.<br/>',NULL,4919,4919);
INSERT INTO stanza VALUES('E943','2','"Repent, the Kingdom has come near,"<br/>This is the Kingdom''s first demand;<br/>A change of mind we all must have<br/>And on God''s side must firmly stand.<br/>',NULL,4920,4920);
INSERT INTO stanza VALUES('E943','3','That we the Kingdom enter in,<br/>Surpassing righteousness we need,<br/>Exceeding that which is of law;<br/>From life alone it must proceed.<br/>',NULL,4921,4921);
INSERT INTO stanza VALUES('E943','4','That we the Kingdom enter in,<br/>We need to do the Father''s will,<br/>Not by our choice to work or act<br/>But His one purpose to fulfill.<br/>',NULL,4922,4922);
INSERT INTO stanza VALUES('E943','5','That we the Kingdom enter in,<br/>A simple child we must become-<br/>Adjustable, obedient, meek-<br/>And everything of self o''ercome.<br/>',NULL,4923,4923);
INSERT INTO stanza VALUES('E943','6','The Heav''nly Kingdom e''en requires<br/>That we as God should perfect be;<br/>This standard we must fully meet<br/>That we may share its ecstasy.<br/>',NULL,4924,4924);
INSERT INTO stanza VALUES('E943','7','The Kingdom is the reign of God<br/>To match His nature is required;<br/>''Tis only by the life of God<br/>The Kingdom''s entry is acquired.<br/>',NULL,4925,4925);
INSERT INTO stanza VALUES('E943','8','The Kingdom is the rule of heav''n;<br/>With heaven''s state we must accord;<br/>''Tis only by the life of heav''n<br/>That we may share it with the Lord.<br/>',NULL,4926,4926);
INSERT INTO stanza VALUES('E944','1','The essence of the Kingdom is<br/>A life that''s under heaven''s rule,<br/>A life whose nature is divine<br/>With Christ experienced in full.<br/>',NULL,4927,4927);
INSERT INTO stanza VALUES('E944','2','Such is this life: in spirit poor,<br/>With heart repentant, mourning, meek,<br/>Which is to others merciful<br/>And purely God Himself doth seek;<br/>',NULL,4928,4928);
INSERT INTO stanza VALUES('E944','3','As sons of God the peace to make,<br/>For righteousness e''en suffering pain;<br/>Reviled and hurt for Jesus'' sake,<br/>Exceeding joyfulness to gain;<br/>',NULL,4929,4929);
INSERT INTO stanza VALUES('E944','4','As salt to kill corruption rife,<br/>In darkness shining as the light,<br/>In heart and action right and true,<br/>In perfect love to claim no right.<br/>',NULL,4930,4930);
INSERT INTO stanza VALUES('E944','5','This life self-glory doth renounce<br/>And ever for God''s kingdom prays;<br/>It trusts in God for every need<br/>And seeks His kingdom first always.<br/>',NULL,4931,4931);
INSERT INTO stanza VALUES('E944','6','''Tis strict with self, with others kind,<br/>And always dealing with the Lord;<br/>It ever does the Father''s will<br/>And acts according to His word.<br/>',NULL,4932,4932);
INSERT INTO stanza VALUES('E944','7','To Satan it does not give ground,<br/>Not to the world, or self, or sin,<br/>But seeks beneath the heaven''s rule<br/>God''s full authority to win.<br/>',NULL,4933,4933);
INSERT INTO stanza VALUES('E944','8','''Tis such a life which subjugates<br/>All things with pow''r to God''s behest;<br/>The time it hastens when the Lord<br/>Will here His kingdom manifest.<br/>',NULL,4934,4934);
INSERT INTO stanza VALUES('E945','1','The Son of God has come to sow<br/>Himself, the seed of life, in man,<br/>That thru Himself God''s Kingdom grow<br/>And thus fulfill th'' eternal plan.<br/>',NULL,4935,4935);
INSERT INTO stanza VALUES('E945','2','He was the only grain of wheat<br/>Whence many grains have been produced<br/>To be the Kingdom''s children meet,<br/>Thru whom God''s reign is introduced.<br/>',NULL,4936,4936);
INSERT INTO stanza VALUES('E945','3','But Satan, enemy of God,<br/>Sowed many tares among the wheat,<br/>The Kingdom''s children to confuse,<br/>And awful damage to create.<br/>',NULL,4937,4937);
INSERT INTO stanza VALUES('E945','4','''Tis by this subtle work of his,<br/>The mixing of the tares with wheat,<br/>The Kingdom in appearance is<br/>Abnormal and grotesquely great.<br/>',NULL,4938,4938);
INSERT INTO stanza VALUES('E945','5','The Kingdom should as mustard be,<br/>A little herb, yet good for food,<br/>But it has changed into a "tree,"<br/>A system of great multitude.<br/>',NULL,4939,4939);
INSERT INTO stanza VALUES('E945','6','Instead of being good for food,<br/>A lodge of "birds" it has become;<br/>''Tis now a place where evil men<br/>And evil spirits make their home.<br/>',NULL,4940,4940);
INSERT INTO stanza VALUES('E945','7','A great religion of the world<br/>Its outward form to us reveals,<br/>Including pagan, evil things,<br/>As leaven mingled with the meal.<br/>',NULL,4941,4941);
INSERT INTO stanza VALUES('E945','8','A system of the world as such,<br/>It thus has changed in outward form;<br/>By evil things which it imbibes,<br/>Corruption inwardly doth swarm.<br/>',NULL,4942,4942);
INSERT INTO stanza VALUES('E945','9','But something hidden God doth seek,<br/>As "pearl" and "treasure in the field",<br/>As such the Lord would us transform<br/>That pearl and treasure be revealed.<br/>',NULL,4943,4943);
INSERT INTO stanza VALUES('E945','10','''Tis hidden from vast Christendom<br/>And from the Kingdom''s great facade,<br/>Yet in its full reality<br/>''Tis transformed like to Christ and God.<br/>',NULL,4944,4944);
INSERT INTO stanza VALUES('E945','11','Lord, separate us from the "tares,"<br/>And save us from the monstrous "tree",<br/>From all the "leaven" purge us now<br/>That we may purely be of Thee.<br/>',NULL,4945,4945);
INSERT INTO stanza VALUES('E945','12','May Thou in life transform our souls<br/>That we as precious stones may be,<br/>Meet for Thy house to build and in<br/>Thy Kingdom''s full reality.<br/>',NULL,4946,4946);
INSERT INTO stanza VALUES('E946','1','Lo, the glory! Lo, the splendor!<br/>Heaven''s Kingdom manifest!<br/>And its glorious King, our Master,<br/>Is by God''s appointment blest.<br/>Once in flesh He came so lowly,<br/>Hated and despised by man;<br/>Now He comes again in glory<br/>To fulfill the Kingdom plan.<br/>',NULL,4947,4947);
INSERT INTO stanza VALUES('E946','2','Going to receive the Kingdom<br/>From His God, the Ancient of Days,<br/>Now He cometh with the Kingdom<br/>And its glorious, ruling rays.<br/>He''s "the Stone" which breaks the nations<br/>Into pieces lowliest,<br/>Which "a mountain great" becometh<br/>As the Kingdom manifest.<br/>',NULL,4948,4948);
INSERT INTO stanza VALUES('E946','3','Lo, the earth, all lands and kingdoms,<br/>By the Lord and Christ possessed;<br/>Earth beneath their sovereign ruling<br/>Will be full of peace and rest.<br/>No more war and no more hatred<br/>''Twixt the nations will there be;<br/>But God''s knowledge shall suffuse them<br/>As the waters fill the sea.<br/>',NULL,4949,4949);
INSERT INTO stanza VALUES('E946','4','All the Christian overcomers<br/>Shall with Christ in glory reign,<br/>And the remnant saved of Israel<br/>Then God''s priesthood shall obtain.<br/>As God''s people shall the nations<br/>''Neath their rule and teaching be,<br/>And a glorious restoration<br/>All creation then shall see.<br/>',NULL,4950,4950);
INSERT INTO stanza VALUES('E946','5','Satan will be bound and banished;<br/>From his rule will earth be freed;<br/>With Christ''s sovereign reign and headship<br/>Earth will then be blessed indeed.<br/>All to Christ will then be subject,<br/>To His pow''r and to His will;<br/>As the Head and Center glorious,<br/>He God''s purpose will fulfill.<br/>',NULL,4951,4951);
INSERT INTO stanza VALUES('E947','1','God''s Kingdom today is a real exercise,<br/>But when Christ comes to reign it will be a great prize;<br/>It is wisdom divine that we now may be trained<br/>That His plan be fulfilled and His justice maintained.<br/>',NULL,4952,4952);
INSERT INTO stanza VALUES('E947','2','God''s children, we''re born to be kings with His Son,<br/>And we need to be trained that we may overcome<br/>And to know how to rule in His kingdom as kings,<br/>That His kingship thru us be expressed o''er all things.<br/>',NULL,4953,4953);
INSERT INTO stanza VALUES('E947','3','Today we must learn to submit to His throne,<br/>How to have a strict life and His government own;<br/>His authority then we''ll be able to share,<br/>O''er the nations to rule with God''s Son as the heir.<br/>',NULL,4954,4954);
INSERT INTO stanza VALUES('E947','4','With a life strict to self we must righteousness hold,<br/>Kind to others in peace, and with God joyful, bold;<br/>In the Kingdom''s reality e''er to remain,<br/>For its manifestation prepared thus to reign.<br/>',NULL,4955,4955);
INSERT INTO stanza VALUES('E947','5','Then Christ when He comes with the kingdom from God<br/>Will to us grant His kingship to share as reward;<br/>Thus the Lord will His righteousness thru us maintain<br/>And His wisdom to heavenly powers make plain.<br/>',NULL,4956,4956);
INSERT INTO stanza VALUES('E947','6','For this the Apostle pressed on at all cost,<br/>For the Kingdom assured that he would not be lost;<br/>''Tis for this he charged others, Be true to the Lord,<br/>That the Kingdom might be unto them a reward.<br/>',NULL,4957,4957);
INSERT INTO stanza VALUES('E947','7','O Lord, give us grace for Thy Kingdom to live,<br/>To be trained that Thou may the reward to us give;<br/>Make the Kingdom''s reality our exercise,<br/>That its manifestation may be our great prize.<br/>',NULL,4958,4958);
INSERT INTO stanza VALUES('E948','1','Myst''ry hid from ages now revealed to me,<br/>''Tis the Christ of God''s reality.<br/>He embodies God, and He is life to me,<br/>And the glory of my hope He''ll be.<br/>',NULL,4959,4959);
INSERT INTO stanza VALUES('E948','chorus','Glory, glory, Christ is life in me!<br/>Glory, glory, what a hope is He!<br/>Now within my spirit He''s the mystery!<br/>Then the glory He will be to me.<br/>',NULL,4960,4960);
INSERT INTO stanza VALUES('E948','2','In my spirit He regenerated me,<br/>In my soul He''s now transforming me.<br/>He will change my body like unto His own,<br/>Wholly making me the same as He.<br/>',NULL,4961,4961);
INSERT INTO stanza VALUES('E948','3','Now in life and nature He is one with me;<br/>Then in Him, the glory, I will be;<br/>I''ll enjoy His presence for eternity<br/>With Him in complete conformity.<br/>',NULL,4962,4962);
INSERT INTO stanza VALUES('E949','1','Christ is the hope of glory, my very life is He,<br/>He has regenerated and saturated me;<br/>He comes to change my body by His subduing might<br/>Like to His glorious body in glory bright!<br/>',NULL,4963,4963);
INSERT INTO stanza VALUES('E949','chorus','He comes, He comes, Christ comes to glorify me!<br/>My body He''ll transfigure, like His own it then will be.<br/>He comes, He comes, redemption to apply!<br/>As Hope of glory He will come, His saints to glorify.<br/>',NULL,4964,4964);
INSERT INTO stanza VALUES('E949','2','Christ is the hope of glory, He is God''s mystery;<br/>He shares with me God''s fulness and brings God into me.<br/>He comes to make me blended with God in every way,<br/>That I may share His glory with Him for aye.<br/>',NULL,4965,4965);
INSERT INTO stanza VALUES('E949','3','Christ is the hope of glory, redemption full is He:<br/>Redemption to my body, from death to set it free,<br/>He comes to make my body a glorious one to be<br/>And swallow death forever in victory.<br/>',NULL,4966,4966);
INSERT INTO stanza VALUES('E949','4','Christ is the hope of glory, He is my history:<br/>His life is my experience, for He is one with me;<br/>He comes to bring me into His glorious liberty,<br/>That one with Him completely I''ll ever be.<br/>',NULL,4967,4967);
INSERT INTO stanza VALUES('E950','1','And it is so! I shall be like Thy Son?<br/>Is this the grace which He for me has won?<br/>Father of glory-thought beyond all thought!-<br/>In glory, to His own blest likeness brought!<br/>',NULL,4968,4968);
INSERT INTO stanza VALUES('E950','2','Oh, Jesus, Lord, who loved me like to Thee?<br/>Fruit of Thy work, with Thee, too, there to see<br/>Thy glory, Lord, while endless ages roll,<br/>Myself the prize and travail of Thy soul.<br/>',NULL,4969,4969);
INSERT INTO stanza VALUES('E950','3','Yet it must be: Thy love had not its rest<br/>Were Thy redeemed not with Thee fully blest;<br/>That love that gives not as the world, but shares<br/>All it possesses with its loved co-heirs.<br/>',NULL,4970,4970);
INSERT INTO stanza VALUES('E950','4','Nor I alone; Thy loved ones, all complete<br/>In glory, round Thee there with joy shall meet;<br/>All like Thee, for Thy glory like Thee, Lord,<br/>Object supreme of all, by all adored.<br/>',NULL,4971,4971);
INSERT INTO stanza VALUES('E951','1','Christ is coming! Let creation<br/>From her groans and travail cease,<br/>Let the glorious proclamation<br/>Hope restore, and faith increase.<br/>Christ is coming! Christ is coming!<br/>Come, Thou blessed Prince of Peace.<br/>',NULL,4972,4972);
INSERT INTO stanza VALUES('E951','2','Earth can now but tell the story<br/>Of Thy bitter cross and pain;<br/>She shall yet behold Thy glory<br/>When Thou comest back to reign.<br/>Christ is coming! Christ is coming!<br/>Let each heart repeat the strain.<br/>',NULL,4973,4973);
INSERT INTO stanza VALUES('E951','3','Long Thy people have been pining<br/>For Thy peace and rest, and Thee,<br/>Soon, in heav''nly glory shining,<br/>Their Restorer shall they see,<br/>Christ is coming! Christ is coming!<br/>Haste the joyous jubilee.<br/>',NULL,4974,4974);
INSERT INTO stanza VALUES('E951','4','With that blessed hope before us,<br/>Let no harp remain unstrung;<br/>Let the mighty advent chorus<br/>Onward roll on every tongue.<br/>Christ is coming! Christ is coming!<br/>Come, Lord Jesus, quickly come.<br/>',NULL,4975,4975);
INSERT INTO stanza VALUES('E952','1','A lamp in the night, a song in time of sorrow,<br/>A great glad hope which faith can borrow<br/>To gild the passing day with the glory of the morrow,<br/>Is the hope of the coming of the Lord.<br/>',NULL,4976,4976);
INSERT INTO stanza VALUES('E952','chorus','Blessed hope, blessed hope,<br/>Blessed hope of the coming of the Lord;<br/>How the aching heart it cheers;<br/>How it glistens through our tears,<br/>Blessed hope of the coming of the Lord.<br/>',NULL,4977,4977);
INSERT INTO stanza VALUES('E952','2','A star in the sky, a beacon bright to guide us;<br/>An anchor sure to hold when storms betide us;<br/>A refuge for the soul, where in quiet we may hide us,<br/>Is the hope of the coming of the Lord.<br/>',NULL,4978,4978);
INSERT INTO stanza VALUES('E952','3','A call of command, like trumpet clearly sounding,<br/>To make us bold when evil is surrounding;<br/>To stir the sluggish heart, and to keep in good abounding,<br/>Is the hope of the coming of the Lord.<br/>',NULL,4979,4979);
INSERT INTO stanza VALUES('E952','4','A word from the One to all our hearts the dearest,<br/>A parting word to make Him aye the nearest;<br/>Of all His precious words, the sweetest, brightest, clearest,<br/>Is the hope of the coming of the Lord.<br/>',NULL,4980,4980);
INSERT INTO stanza VALUES('E953','1','Our Lord is now rejected,<br/>And by the world disowned,<br/>By the many still neglected,<br/>And by the few enthroned;<br/>But soon He''ll come in glory!<br/>The hour is drawing nigh,<br/>For the crowning day is coming<br/>By-and-by.<br/>',NULL,4981,4981);
INSERT INTO stanza VALUES('E953','chorus','O the crowning day is coming,<br/>Is coming by-and-by,<br/>When our Lord shall come in power<br/>And glory from on high.<br/>O the glorious sight will gladden<br/>Each waiting, watchful eye,<br/>In the crowning day that''s coming<br/>By-and-by.<br/>',NULL,4982,4982);
INSERT INTO stanza VALUES('E953','2','The heavens shall glow with splendor,<br/>But brighter far than they,<br/>The saints shall shine in glory,<br/>As Christ shall them array.<br/>The beauty of the Savior<br/>Shall dazzle every eye,<br/>In the crowning day that''s coming<br/>By-and-by.<br/>',NULL,4983,4983);
INSERT INTO stanza VALUES('E953','3','Our pain shall then be over,<br/>We''ll sin and sigh no more,<br/>Behind us all of sorrow,<br/>And naught but joy before,<br/>A joy in our Redeemer,<br/>As we to Him are nigh,<br/>In the crowning day that''s coming<br/>By-and-by.<br/>',NULL,4984,4984);
INSERT INTO stanza VALUES('E953','4','Let all that look for hasten<br/>The coming joyful day,<br/>By earnest consecration,<br/>To walk the narrow way;<br/>By gathering in the lost ones,<br/>For whom our Lord did die,<br/>For the crowning day that''s coming<br/>By-and-by.<br/>',NULL,4985,4985);
INSERT INTO stanza VALUES('E954','1','There''s a light upon the mountains,<br/>and the day is at the spring,<br/>When our eyes shall see the beauty<br/>and the glory of the King;<br/>Weary was our heart with waiting,<br/>and the night-watch seemed so long,<br/>But His triumph-day is breaking,<br/>and we hail it with a song.<br/>',NULL,4986,4986);
INSERT INTO stanza VALUES('E954','2','In the fading of the starlight we can<br/>see the coming of the morn;<br/>And the lights of men are paling in<br/>the splendor of the dawn;<br/>For the eastern skies are glowing<br/>as with lights of hidden fire,<br/>And the hearts of men are stirring<br/>with the throb of deep desire.<br/>',NULL,4987,4987);
INSERT INTO stanza VALUES('E954','3','There''s a hush of expectation,<br/>and a quiet in the air;<br/>And the breath of God is moving in<br/>the fervent breath of prayer;<br/>For the suffering,<br/>dying Jesus is the Christ upon the throne,<br/>And the travail of our spirit<br/>is the travail of His own.<br/>',NULL,4988,4988);
INSERT INTO stanza VALUES('E954','4','He is breaking down the barriers,<br/>He is casting up the way;<br/>He is calling for His angels to build<br/>up the gates of day;<br/>But His angels here are human,<br/>not the shining hosts above,<br/>For the drum-beats of His army are<br/>the heart-beats of our love.<br/>',NULL,4989,4989);
INSERT INTO stanza VALUES('E954','5','Hark! We hear a distant music,<br/>and it comes with fuller swell;<br/>''Tis the triumph song of Jesus,<br/>of our King Emmanuel;<br/>Zion, go ye forth to meet Him,<br/>and my soul, be swift to bring<br/>All thy sweetest and thy dearest for<br/>the triumph of our King.<br/>',NULL,4990,4990);
INSERT INTO stanza VALUES('E955','1','In the advent light, O Savior,<br/>I am living day by day;<br/>Waiting, working, watching ever,<br/>Knowing Thou are on Thy way.<br/>',NULL,4991,4991);
INSERT INTO stanza VALUES('E955','2','Separated unto Jesus,<br/>Loosed from all the world beside;<br/>Blinded by the advent glory,<br/>Hour by hour would I abide.<br/>',NULL,4992,4992);
INSERT INTO stanza VALUES('E955','3','So from glory unto glory,<br/>Gladdened by the advent ray;<br/>All the path is growing brighter,<br/>Shining unto perfect day.<br/>',NULL,4993,4993);
INSERT INTO stanza VALUES('E955','4','In the advent light to witness<br/>To a dark and dying world;<br/>This the holy ordination;<br/>May His banner be unfurled.<br/>',NULL,4994,4994);
INSERT INTO stanza VALUES('E955','5','In the advent light rejoicing;<br/>Songs of praise along the road<br/>Seem to make the journey shorter,<br/>Mounting upward to our God.<br/>',NULL,4995,4995);
INSERT INTO stanza VALUES('E955','6','He is coming! He is coming!<br/>Pass the heavenly watchword on:<br/>Go ye forth to meet the Bridegroom,<br/>Hail! To God''s anointed Son.<br/>',NULL,4996,4996);
INSERT INTO stanza VALUES('E955','7','See the advent glory breaking;<br/>Faith will soon be lost in sight;<br/>Face to face I shall behold Him,<br/>Bathed in His eternal light.<br/>',NULL,4997,4997);
INSERT INTO stanza VALUES('E956','1','Soon our Lord will come, the day is drawing nigh,<br/>Sound of His approaching we can hear.<br/>Watchful we must be and always on alert<br/>That the Lord our hearts with rapture cheer.<br/>',NULL,4998,4998);
INSERT INTO stanza VALUES('E956','chorus','Glory! Glory! Christ will come again!<br/>Glory! Glory! We with Him shall reign!<br/>With a glorious body, ever with the Lord,<br/>Singing all His praise with glad accord.<br/>',NULL,4999,4999);
INSERT INTO stanza VALUES('E956','2','Soon our Lord will come, the Morning Star appear;<br/>Night is deep, and soon will dawn the day.<br/>Never with the current of the age we go,<br/>That from trials we''ll be kept away.<br/>',NULL,5000,5000);
INSERT INTO stanza VALUES('E956','3','Soon our Lord will come His servants to reward;<br/>Those who love Him then the crown will share.<br/>Watchful we must be and treasure not the world,<br/>Love and serve the Lord, His burden bear.<br/>',NULL,5001,5001);
INSERT INTO stanza VALUES('E956','4','Soon our Lord will come and in His kingdom reign;<br/>Satan will be bound, the world subdued.<br/>We must fight the battle, overcome the foe,<br/>On His throne He then will us include.<br/>',NULL,5002,5002);
INSERT INTO stanza VALUES('E957','1','Watch! For the morning is breaking,<br/>A moment, and He will be here!<br/>The mists and the shadows are fleeing,<br/>The darkness will soon disappear;<br/>And He, for whom ages have waited,<br/>The Lord Who has tarried so long,<br/>Will come in an outburst of glory,<br/>A moment, and we shall be gone.<br/>',NULL,5003,5003);
INSERT INTO stanza VALUES('E957','2','Watch! For the morning is breaking,<br/>A moment, the crown will be won!<br/>A moment, and we shall be with Him,<br/>A moment, the journey is done!<br/>Lord, keep us each moment unsleeping,<br/>And count us all worthy to be<br/>In that noble band of Thy watchers,<br/>Whose life is a vigil with Thee.<br/>',NULL,5004,5004);
INSERT INTO stanza VALUES('E958','1','Since long ago at Bethany we parted,<br/>Within my heart there is a ceaseless void;<br/>How can I take my harp down from the willow?<br/>How can my songs without Thee be enjoyed?<br/>And when at night I''m keeping lonely vigil-<br/>Grown numb alike to sorrow and to cheer-<br/>Then I recall the promise of Thy coming,<br/>But sigh: O Lord, why, why Thou dost not yet appear?<br/>',NULL,5005,5005);
INSERT INTO stanza VALUES('E958','2','Thy manger wakes the thought: I too am homeless;<br/>Thy cross strips earthly pleasures from my soul;<br/>Thy coming bids me seek a better country,<br/>For Thou Thyself art now my final goal.<br/>Since Thou art gone my joy has lost its flavor,<br/>My song the sweetness I would fain convey.<br/>Since Thou art gone the sense of void o''erwhelms me.<br/>Oh, how I long that Thou wilt come and not delay.<br/>',NULL,5006,5006);
INSERT INTO stanza VALUES('E958','3','Though even now I know Thy loving presence,<br/>Yet in my heart there''s still a sense of lack.<br/>Enlightening and tenderest sustaining<br/>Can no more satisfy: I want Thee back.<br/>Despite Thy peace within, I still feel lonely;<br/>Despite Thy joy there still remains a sigh;<br/>When I feel most content, the silent yearning<br/>To see Thee face to face becomes an uttered cry.<br/>',NULL,5007,5007);
INSERT INTO stanza VALUES('E958','4','What exile cannot but desire his homeland<br/>And long his people once again to greet?<br/>What soul on alien soil forgets his kindred?<br/>What parted lovers never yearn to meet?<br/>O Lord, how can these earthly loves and pleasures<br/>With all the joy of Thy return compare?<br/>Then, if I cannot here behold Thy countenance,<br/>What can I do but sigh till Thou, my Lord, appear?<br/>',NULL,5008,5008);
INSERT INTO stanza VALUES('E958','5','Could''st Thou, O Lord, forget Thy word of promise<br/>Soon to return and take me unto Thee?<br/>Yet day by day and year by year I''ve waited<br/>And still I wait, and no return I see!<br/>Remember, Lord, the years I have been waiting<br/>While Thy dear footsteps linger far away.<br/>How long? How long? Oh! Must I wait still longer<br/>Till Thou shalt come again in glorious array?<br/>',NULL,5009,5009);
INSERT INTO stanza VALUES('E958','6','From generation unto generation<br/>Thy saints have come and gone, but have not seen<br/>Thy glorious promise pass into fulfilment.<br/>How long, how very long the time has been!<br/>Why cannot we, dear Lord, discern Thy footsteps?<br/>Why are the heavens still so closely sealed?<br/>Oh! Must our waiting be prolonged still further<br/>Before Thou in Thy matchless splendor art revealed?<br/>',NULL,5010,5010);
INSERT INTO stanza VALUES('E958','7','Lord, I recall the many years I''ve waited<br/>For Thy return-yet, Lord, not I alone,<br/>But Thy dear saints through many generations-<br/>Beseeching Thee to come back for Thine own.<br/>To countless tears and countless fervent pleadings,<br/>By Thine appearing haste to make reply.<br/>Oh, may Thou come, the echo of the ages,<br/>Come, come and answer now this mighty corp''rate cry!<br/>',NULL,5011,5011);
INSERT INTO stanza VALUES('E959','1','Since Thy departure from Olivet''s Mountain,<br/>Why is Thy coming again so delayed?<br/>Thru the long years we have longed for Thy coming;<br/>Hast Thou not heard all the prayers that we''ve prayed?<br/>',NULL,5012,5012);
INSERT INTO stanza VALUES('E959','chorus','Come Thou, come now:<br/>Lord, for Thy coming we yearn;<br/>All our desire is Thy promised returning,<br/>Oh, may Thou quickly return.<br/>',NULL,5013,5013);
INSERT INTO stanza VALUES('E959','2','Beloved Lord, since the year Thou ascended<br/>Everything here has been tasteless and dry;<br/>Often in praying and often in watching,<br/>In every movement, for Thee, Lord, we sigh.<br/>',NULL,5014,5014);
INSERT INTO stanza VALUES('E959','3','Scenes although lovely, yet when will we meet Thee?<br/>Birds and the flowers fair beauty embrace;<br/>All are delightsome, but none satisfy me,<br/>For I am longing for Thy loving face.<br/>',NULL,5015,5015);
INSERT INTO stanza VALUES('E959','4','Lord, we''re impatient awaiting Thy coming,<br/>We do not know how much longer ''twill be;<br/>From every sunrise to every bright sunset<br/>Hope we each moment Thy coming to see.<br/>',NULL,5016,5016);
INSERT INTO stanza VALUES('E959','5','Whene''er ''tis raining or strong winds are blowing,<br/>Whene''er the moon shines, or rises the sea,<br/>We ever hope to discover Thy coming;<br/>How disappointed when no sign of Thee!<br/>',NULL,5017,5017);
INSERT INTO stanza VALUES('E959','6','If it were not for the bidding Thou gav''st us,<br/>We''d be discouraged, Thy service we''d shirk;<br/>But Thou dost want us while waiting Thy coming,<br/>For Thee to live and in diligence work.<br/>',NULL,5018,5018);
INSERT INTO stanza VALUES('E959','7','Oh Lord, remember the days have been lengthened<br/>Since Thou hast promised ere going away;<br/>We hope and hope and are endlessly hoping,<br/>That Thou wilt come. Canst Thou come e''en today?<br/>',NULL,5019,5019);
INSERT INTO stanza VALUES('E960','1','My King will soon come back again,<br/>The sky be filled with Him;<br/>The universe to be redeemed<br/>Will see His light therein.<br/>The Lord will soon fulfill His plan,<br/>His footsteps now I hear;<br/>His glorious frame I faintly see<br/>Beginning to appear.<br/>',NULL,5020,5020);
INSERT INTO stanza VALUES('E960','2','I''m longing for His presence blest<br/>And dare not slothful be<br/>While waiting for my Lord''s return,<br/>His own dear self to see.<br/>My only hope-that He may come<br/>And change my faith to sight;<br/>There is no other joy on earth<br/>Which gives my heart delight.<br/>',NULL,5021,5021);
INSERT INTO stanza VALUES('E960','3','My heart is always with Himself,<br/>My eyes are heavenward,<br/>My lips would utter nothing else<br/>Than meeting with my Lord.<br/>The coming of the Lord draws nigh,<br/>His coming is for me;<br/>His promise ever standeth firm<br/>And soon fulfilled I''ll see.<br/>',NULL,5022,5022);
INSERT INTO stanza VALUES('E960','4','My Savior, all Thy holy words<br/>Can never doubted be;<br/>With them encouraged day by day,<br/>I''m faithful unto Thee.<br/>Oh, may Thy glory soon appear,<br/>The foe be overthrown;<br/>Thy promises be realized,<br/>And we brought to Thy throne.<br/>',NULL,5023,5023);
INSERT INTO stanza VALUES('E960','5','Thy saving arm a refuge is,<br/>My Savior God, to me;<br/>Thou as the father keepeth them;<br/>Who put their trust in Thee.<br/>The sheep and shepherd are of one,<br/>The head and body same;<br/>None e''er can pluck from out Thy hand<br/>The child who trusts Thy Name.<br/>',NULL,5024,5024);
INSERT INTO stanza VALUES('E960','6','A thousand hands won''t hinder me,<br/>Nor will ten thousand eyes;<br/>The thorns upon the road but help<br/>Me onward to the prize.<br/>Arise, my spirit and my heart,<br/>And let the world go by;<br/>The Lord of life will take me soon<br/>To be with Him on high.<br/>',NULL,5025,5025);
INSERT INTO stanza VALUES('E960','7','Thou healing sun! Thou hope of man!<br/>I really love Thy ray.<br/>Oh, righteous Lord! Oh, glorious King!<br/>I bow to Thee and pray:<br/>Oh, may Thou soon ascend Thy throne<br/>And quickly show Thy face;<br/>Thy heav''nly kingdom may Thou found<br/>And grant all men Thy grace.<br/>',NULL,5026,5026);
INSERT INTO stanza VALUES('E960','8','The truth should triumph and be king,<br/>And freedom should be queen;<br/>But falsehood, which has rampant run,<br/>Head of the world is seen.<br/>We ask Thee, Truth, to quickly come<br/>And bring Thy light from heav''n;<br/>The foe be crushed and all Thy sons<br/>Into Thy bosom giv''n.<br/>',NULL,5027,5027);
INSERT INTO stanza VALUES('E961','1','The Church has waited long,<br/>Her absent Lord to see,<br/>And still in loneliness she waits,<br/>A friendless stranger she.<br/>Age after age had gone,<br/>Sun after sun has set,<br/>And still in weeds of widowhood,<br/>She weeps a mourner yet.<br/>',NULL,5028,5028);
INSERT INTO stanza VALUES('E961','2','Saint after saint on earth<br/>Has lived, and loved, and died;<br/>And as they left us one by one,<br/>We laid them side by side;<br/>We laid them down to sleep,<br/>But not in hope forlorn;<br/>We laid them but to ripen there,<br/>Till the last glorious morn.<br/>',NULL,5029,5029);
INSERT INTO stanza VALUES('E961','3','The serpent''s brood increase,<br/>The powers of hell grow bold,<br/>The conflict thickens, faith is low,<br/>And love is waxing cold.<br/>How long, O Lord our God,<br/>Holy, and true, and good,<br/>Wilt Thou not judge Thy suffering Church,<br/>Her sighs, and tears, and blood?<br/>',NULL,5030,5030);
INSERT INTO stanza VALUES('E961','4','We long to hear Thy voice,<br/>To see Thee face to face,<br/>To share Thy crown and glory then,<br/>As now we share Thy grace.<br/>Should not the loving bride<br/>Her absent bridegroom mourn?<br/>Should she not wear the signs of grief<br/>Until her Lord return?<br/>',NULL,5031,5031);
INSERT INTO stanza VALUES('E961','5','The whole creation groans,<br/>And waits to hear that voice<br/>That shall her beauteousness restore,<br/>And make her wastes rejoice.<br/>Come, Lord, and wipe away<br/>The curse, the sin, the stain,<br/>And make this blighted world of ours<br/>Thine own fair world again.<br/>',NULL,5032,5032);
INSERT INTO stanza VALUES('E962','1','Oh, how long before my Lord comes back,<br/>My heart desires to see Thy face,<br/>That the song of triumph I may sing<br/>And behold my Beloved, full of grace.<br/>Come quickly, Lord, and tarry not!<br/>Oh, when wilt Thou return to comfort me;<br/>Come quickly, Lord and tarry not!<br/>My heart desires to be with Thee.<br/>',NULL,5033,5033);
INSERT INTO stanza VALUES('E963','1','Face to face with Christ, my Savior,<br/>Face to face-what will it be?<br/>When with rapture I behold Him,<br/>Jesus Christ who died for me.<br/>',NULL,5034,5034);
INSERT INTO stanza VALUES('E963','chorus','Face to face I shall behold Him,<br/>Far beyond the starry sky;<br/>Face to face in all His glory,<br/>I shall see Him by and by!<br/>',NULL,5035,5035);
INSERT INTO stanza VALUES('E963','2','Only faintly now, I see Him,<br/>With the darkling veil between,<br/>But a blessed day is coming,<br/>When His glory shall be seen.<br/>',NULL,5036,5036);
INSERT INTO stanza VALUES('E963','3','What rejoicing in His presence,<br/>When are banished grief and pain;<br/>When the crooked ways are straightened,<br/>And the dark things shall be plain.<br/>',NULL,5037,5037);
INSERT INTO stanza VALUES('E963','4','Face to face! O blissful moment!<br/>Face to face-to see and know;<br/>Face to face with my Redeemer,<br/>Jesus Christ who loves me so.<br/>',NULL,5038,5038);
INSERT INTO stanza VALUES('E964','1','''Midst the darkness, storm, and sorrow,<br/>One bright gleam I see''<br/>Well I know the blessed morrow<br/>Christ will come for me.<br/>''Midst the peace, the joy, the glory<br/>And the light, God''s own,<br/>Christ for me is watching, waiting,<br/>Waiting ''til I come.<br/>',NULL,5039,5039);
INSERT INTO stanza VALUES('E964','2','Long the blessed Guide has led me,<br/>By the desert road;<br/>Now I see the coming splendor,<br/>Splendor of my God.<br/>There amidst the love and glory<br/>He is waiting yet;<br/>On His hands a name is graven<br/>He can ne''er forget.<br/>',NULL,5040,5040);
INSERT INTO stanza VALUES('E964','3','Who is this, who come to meet me,<br/>On the desert way,<br/>As the Morning Star foretelling<br/>God''s unclouded day?<br/>He it is who came to win me,<br/>On the cross of shame;<br/>In His glory well I know Him,<br/>Evermore the same.<br/>',NULL,5041,5041);
INSERT INTO stanza VALUES('E964','4','O the blessed joy of meeting,<br/>All the desert past;<br/>O the wondrous words of greeting,<br/>He shall speak at last!<br/>He and I together ent''ring<br/>The fair realm above;<br/>He and I together sharing<br/>All the Father''s love.<br/>',NULL,5042,5042);
INSERT INTO stanza VALUES('E964','5','Where no shade nor stain can enter,<br/>Nor the gold be dim,<br/>In His holiness unsullied,<br/>I shall walk with Him.<br/>Meet companion then for Jesus,<br/>From Him, for Him, made-<br/>Glory of God''s grace forever<br/>There in me displayed.<br/>6. He who in His hour of sorrow<br/>Bore the curse alone;<br/>I who through the lonely desert<br/>Trod where He had gone;<br/>He and I, in that bright glory,<br/>One deep joy shall share-<br/>Mine, to be forever with Him;<br/>His, that I am there.<br/>',NULL,5043,5043);
INSERT INTO stanza VALUES('E965','1','When my blest Lord will come again,<br/>I will be saved from all my pain,<br/>With all the saints I''ll follow Him,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>With all the saints I''ll follow Him,<br/>O praise the Lord!<br/>',NULL,5044,5044);
INSERT INTO stanza VALUES('E965','2','When I shall see Him face to face,<br/>And dwell with Him thru endless days,<br/>I will rejoice and sing His grace,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>I will rejoice and sing His grace,<br/>O praise the Lord!<br/>',NULL,5045,5045);
INSERT INTO stanza VALUES('E965','3','When I meet Him before the Throne,<br/>My suff''rings then will all be gone,<br/>The joy of vict''ry will be won,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>The joy of vict''ry will be won,<br/>O praise the Lord!<br/>',NULL,5046,5046);
INSERT INTO stanza VALUES('E965','4','In that day I will testify<br/>That nothing with Christ''s life can vie,<br/>What glorious rapture to the sky,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>What glorious rapture to the sky,<br/>O praise the Lord!<br/>',NULL,5047,5047);
INSERT INTO stanza VALUES('E965','5','May we in our Lord''s side e''er hide,<br/>Be always one and ne''er divide,<br/>That His heart may be satisfied,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>That His heart may be satisfied,<br/>O praise the Lord!<br/>',NULL,5048,5048);
INSERT INTO stanza VALUES('E965','6','O come, our King, O come, dear Lord!<br/>Receive us by Thy promised word,<br/>And give the victors Thy reward,<br/>O praise the Lord!<br/>O praise the Lord! O praise the Lord!<br/>And give the victors Thy reward,<br/>O praise the Lord!<br/>',NULL,5049,5049);
INSERT INTO stanza VALUES('E966','1','O hope of glory, our Christ will return!<br/>We will be raptured, with glory transformed;<br/>Glorified with Him, Himself to enjoy,<br/>In His full likeness we then will be formed.<br/>',NULL,5050,5050);
INSERT INTO stanza VALUES('E966','chorus','Glorious hope! Christ will return!<br/>Glorious hope! Christ will return!<br/>We will be raptured, with glory transformed;<br/>O hope of glory, our Christ will return!<br/>',NULL,5051,5051);
INSERT INTO stanza VALUES('E966','2','O hope of glory, our Christ will return!<br/>The old creation will vanish away,<br/>No more we''ll groan, but have full liberty,<br/>Enjoy salvation in its utmost way.<br/>',NULL,5052,5052);
INSERT INTO stanza VALUES('E966','3','O hope of glory, our Christ will return!<br/>Over the nations with Him we will reign,<br/>Priests we will be in His presence to serve,<br/>Thus His salvation in fulness we''ll gain.<br/>',NULL,5053,5053);
INSERT INTO stanza VALUES('E966','4','O hope of glory, our Christ will return!<br/>Waiting and watching, we faithfully serve,<br/>Running the race, pressing on toward the goal<br/>That we the Kingdom''s reward might deserve.<br/>',NULL,5054,5054);
INSERT INTO stanza VALUES('E967','1','Thou art coming, O my Savior,<br/>Thou art coming, O my King,<br/>In Thy beauty all resplendent,<br/>In thy glory all transcendent;<br/>Well may we rejoice and sing;<br/>Coming! In the opening east,<br/>Herald brightness slowly swells:<br/>Coming! O my glorious Priest,<br/>Hear we not Thy golden bells?<br/>',NULL,5055,5055);
INSERT INTO stanza VALUES('E967','2','Thou art coming, Thou art coming;<br/>We shall meet Thee on Thy way;<br/>We shall see Thee, we shall know Thee,<br/>We shall bless Thee, we shall show Thee<br/>All our hearts could never say:<br/>What an anthem that will be,<br/>Ringing out our love to Thee,<br/>Pouring out our rapture sweet<br/>At Thine own all-glorious feet.<br/>',NULL,5056,5056);
INSERT INTO stanza VALUES('E967','3','Thou art coming, at Thy table<br/>We are witnesses for this;<br/>While rememb''ring hearts Thou meetest<br/>In communion clearest, sweetest,<br/>Earnest of our coming bliss,<br/>Showing not Thy death alone,<br/>And Thy love exceeding great,<br/>But Thy coming and Thy throne,<br/>All for which we long and wait.<br/>',NULL,5057,5057);
INSERT INTO stanza VALUES('E967','4','Oh, the joy to see Thee reigning,<br/>Thee, my own beloved Lord!<br/>Every tongue Thy Name confessing,<br/>Worship, honor, glory, blessing,<br/>Brought to Thee with one accord;<br/>Thee, my Master and my Friend,<br/>Vindicated and enthroned,<br/>Unto earth''s remotest end<br/>Glorified, adored, and owned!<br/>',NULL,5058,5058);
INSERT INTO stanza VALUES('E968','1','Hail to the Lord''s Anointed,<br/>Great David''s greater Son!<br/>Hail, in the time appointed,<br/>His reign on earth began!<br/>He comes to break oppression,<br/>To set the captive free;<br/>To take away transgression,<br/>And rule in equity.<br/>',NULL,5059,5059);
INSERT INTO stanza VALUES('E968','2','He shall come down like showers<br/>Upon the fruitful earth;<br/>And love, joy, hope, like flowers,<br/>Spring in His path to birth:<br/>Before Him on the mountains<br/>Shall peace, the herald, go;<br/>And righteousness, in fountains,<br/>From hill to valley flow.<br/>',NULL,5060,5060);
INSERT INTO stanza VALUES('E968','3','Kings shall fall down before Him,<br/>And gold and incense bring;<br/>All nations shall adore Him,<br/>His praise all people sing;<br/>For He shall have dominion<br/>O''er river, sea, and shore,<br/>Far as the eagle''s pinion,<br/>Or dove''s light wing can soar.<br/>',NULL,5061,5061);
INSERT INTO stanza VALUES('E968','4','To Him shall prayer unceasing<br/>And daily vows ascend;<br/>His kingdom still increasing,<br/>A kingdom without end.<br/>The mountain dews shall nourish<br/>A seed in weakness sown,<br/>Whose fruit shall spread and flourish,<br/>And shake like Lebanon.<br/>',NULL,5062,5062);
INSERT INTO stanza VALUES('E968','5','O''er every foe victorious<br/>He on His throne shall rest,<br/>From age to age more glorious,<br/>All-blessing and all-blest.<br/>The tide of time shall never<br/>His covenant remove;<br/>His Name shall stand forever,<br/>His changeless Name of Love.<br/>',NULL,5063,5063);
INSERT INTO stanza VALUES('E969','1','Hark what a sound, and too divine for hearing,<br/>Stirs on the earth and trembles in the air;<br/>Is it the thunder of the Lord''s appearing?<br/>Is it the music of His people''s prayer?<br/>',NULL,5064,5064);
INSERT INTO stanza VALUES('E969','2','Surely He cometh, and a thousand voices<br/>Shout to the saints, and to the deaf and dumb;<br/>Surely He cometh, and the earth rejoices,<br/>Glad in His coming who hath sworn: I come!<br/>',NULL,5065,5065);
INSERT INTO stanza VALUES('E969','3','This hath He done, and shall we not adore Him?<br/>This shall He do, and can we still despair?<br/>Come, let us quickly fling ourselves before Him,<br/>Cast at His feet the burden of our care.<br/>',NULL,5066,5066);
INSERT INTO stanza VALUES('E969','4','Thru life and death, thru sorrow and thru sinning<br/>He shall suffice me, for He hath sufficed:<br/>Christ is the end, for Christ was the beginning,<br/>Christ the beginning, for the end is Christ.<br/>',NULL,5067,5067);
INSERT INTO stanza VALUES('E970','1','For the glorious revelation<br/>Of the sons of God to come,<br/>All the creatures wait, expecting,<br/>That they all may free become.<br/>',NULL,5068,5068);
INSERT INTO stanza VALUES('E970','2','All creation groans together,<br/>Subject now to vanity,<br/>Looking for their full deliv''rance<br/>From corruption''s slavery.<br/>',NULL,5069,5069);
INSERT INTO stanza VALUES('E970','3','Even we ourselves are groaning,<br/>Till we reach maturity;<br/>We are growing to adoption,<br/>With Christ in conformity.<br/>',NULL,5070,5070);
INSERT INTO stanza VALUES('E970','4','''Tis for this the Spirit groaneth,<br/>That to Christ we be conformed;<br/>All things also work together,<br/>That in life we be transformed.<br/>',NULL,5071,5071);
INSERT INTO stanza VALUES('E970','5','God will bring us into glory,<br/>We will then be glorified;<br/>Fully saturated with Him,<br/>We''ll be wholly sanctified.<br/>',NULL,5072,5072);
INSERT INTO stanza VALUES('E970','6','To the freedom of this glory,<br/>All creation will be freed;<br/>With the kid shall lie the leopard,<br/>And the cow with bear shall feed.<br/>',NULL,5073,5073);
INSERT INTO stanza VALUES('E970','7','Heirs with Christ in full adoption,<br/>We''ll His heritage possess,<br/>Glorified with Him as brethren,<br/>God''s full glory we''ll express.<br/>',NULL,5074,5074);
INSERT INTO stanza VALUES('E971','1','God''s eternal purpose<br/>Is to join with man,<br/>Causing man, His vessel,<br/>To be born again,<br/>His own life imparting,<br/>Filling to the brim;<br/>Man may thus express Him,<br/>And be one with Him.<br/>',NULL,5075,5075);
INSERT INTO stanza VALUES('E971','2','God in His own image<br/>Hath created man,<br/>That he may be able<br/>To fulfill His plan;<br/>That he may receive Him<br/>As the tree of life<br/>To become His fulness<br/>As to man the wife.<br/>',NULL,5076,5076);
INSERT INTO stanza VALUES('E971','3','In His life''s rich flowing<br/>Man will be transformed<br/>Into precious substance<br/>And to Him conformed.<br/>Thus will man be builded<br/>As His counterpart,<br/>Thus to be His dwelling,<br/>Satisfy His heart.<br/>',NULL,5077,5077);
INSERT INTO stanza VALUES('E971','4','''Tis the holy city,<br/>New Jerusalem;<br/>With His saints God mingles,<br/>Makes His home with them.<br/>He becomes their content,<br/>His expression they;<br/>They shall share His glory,<br/>One with Him for aye.<br/>',NULL,5078,5078);
INSERT INTO stanza VALUES('E971','5','He''s the very center,<br/>Ruling on the throne;<br/>By His life the power,<br/>Saints are kept in one.<br/>By His light of glory,<br/>They are kept in light,<br/>Harmony enjoying<br/>In divine delight.<br/>',NULL,5079,5079);
INSERT INTO stanza VALUES('E971','6','He''s their living water,<br/>And their food supply;<br/>All their thirst and hunger<br/>He doth satisfy.<br/>He''s for them the temple,<br/>In Himself they live,<br/>In His constant presence<br/>Worship ever give.<br/>',NULL,5080,5080);
INSERT INTO stanza VALUES('E972','1','Lo, the central thought of God<br/>Is that He be one with man;<br/>He to man is everything<br/>That He might fulfill His plan.<br/>',NULL,5081,5081);
INSERT INTO stanza VALUES('E972','2','Earthen vessel man was made-<br/>Body, soul, and spirit too,<br/>God as life that he may take<br/>And with Him have oneness true.<br/>',NULL,5082,5082);
INSERT INTO stanza VALUES('E972','3','By the flow of life divine,<br/>Man becomes a precious stone<br/>Fit for building God''s abode,<br/>That His glory might be known.<br/>',NULL,5083,5083);
INSERT INTO stanza VALUES('E972','4','''Tis the city God hath built,<br/>''Tis the dwelling God requires,<br/>''Tis the new Jerusalem<br/>Which fulfills His heart''s desires.<br/>',NULL,5084,5084);
INSERT INTO stanza VALUES('E972','5','''Tis the building of the saints,<br/>''Tis the blend of God and man,<br/>Purposed by the Father''s will<br/>Long before the world began.<br/>',NULL,5085,5085);
INSERT INTO stanza VALUES('E972','6','In its center, as its pow''r,<br/>Is the throne of Christ and God,<br/>Whence doth flow the stream of life<br/>As the Spirit''s living flood.<br/>',NULL,5086,5086);
INSERT INTO stanza VALUES('E972','7','Christ, the tree of life, is there<br/>In the flowing of the stream,<br/>Yielding fruit of life divine<br/>As the food of life supreme.<br/>',NULL,5087,5087);
INSERT INTO stanza VALUES('E972','8','God in Christ, the glorious light,<br/>Thru the city brightly shines,<br/>Scattering all the deathly night<br/>With its light of life divine.<br/>',NULL,5088,5088);
INSERT INTO stanza VALUES('E972','9','God in man and man in God<br/>Mutual dwelling thus possess;<br/>God the content is to man,<br/>And the man doth God express.<br/>',NULL,5089,5089);
INSERT INTO stanza VALUES('E973','1','Our goal-the holy city with the Lord,<br/>It is our portion, ''tis where He''s adored;<br/>Although our bodies still are living here,<br/>Our spirits with our glorious Lord are there;<br/>Our spirits with our glorious Lord are there.<br/>',NULL,5090,5090);
INSERT INTO stanza VALUES('E973','2','Our goal divine-the new Jerusalem-<br/>That holy city made for God with men;<br/>For all redeemed, who have Thy pathway trod,<br/>Shall have the right to share the bliss with God,<br/>Shall have the right to share the bliss with God.<br/>',NULL,5091,5091);
INSERT INTO stanza VALUES('E973','3','And every time we toward that city gaze,<br/>Then every time we long to see Thy face;<br/>We long to hear the shout that calls to Thee,<br/>With Thee to share Thy God eternally,<br/>With Thee to share Thy God eternally.<br/>',NULL,5092,5092);
INSERT INTO stanza VALUES('E973','4','Our heart''s desire is not the peace so sweet,<br/>Our longed for hope is not the joy we''ll meet;<br/>But Thou Thyself, Thou art "our hope," O Lord,<br/>For ''tis Thyself that will be our reward,<br/>For ''tis Thyself that will be our reward,<br/>',NULL,5093,5093);
INSERT INTO stanza VALUES('E973','5','O Jesus, Lord, we pray Thee hear our cry,<br/>Come! Bring us to that city from on high!<br/>That in that glory we may share with Thee,<br/>Thy loving Self partake eternally,<br/>Thy loving Self partake eternally,<br/>',NULL,5094,5094);
INSERT INTO stanza VALUES('E973','6','O Lord, Thou sayest, "I make all things new,"<br/>New heav''ns, new earth, and all within them too!<br/>Our God Himself our portion then shall be;<br/>O Lord, come quickly! Take us up with Thee,<br/>O Lord, come quickly! Take us up with Thee,<br/>',NULL,5095,5095);
INSERT INTO stanza VALUES('E974','1','He looked for a city and lived in a tent,<br/>A pilgrim to glory right onward he went;<br/>God''s promise his solace, so royal his birth,<br/>No wonder he sought not the glories of earth.<br/>',NULL,5096,5096);
INSERT INTO stanza VALUES('E974','chorus','City! O City fair!<br/>God''s dwelling with man to eternity is there.<br/>',NULL,5097,5097);
INSERT INTO stanza VALUES('E974','2','He looked for a city, his God should prepare;<br/>No mansion on earth, could he covet or share,<br/>For had not God told him, that royal abode<br/>Awaited His pilgrims on ending the road.<br/>',NULL,5098,5098);
INSERT INTO stanza VALUES('E974','3','He looked for a city; if sometimes he sighed<br/>To be trudging the road, all earth''s glory denied,<br/>The thought of that city changed sighing to song,<br/>For the road might be rough, but it could not be long.<br/>',NULL,5099,5099);
INSERT INTO stanza VALUES('E974','4','He looked for a city, his goal, Lord, we share<br/>And know that bright city, which Thou dost prepare<br/>Is ever our portion, since willing to be<br/>Just pilgrims with Jesus, our roof a tent tree.<br/>',NULL,5100,5100);
INSERT INTO stanza VALUES('E975','1','It was a garden in the primal age,<br/>But at the end it is a city square;<br/>Creation''s center in the garden was,<br/>God''s building issues in the city fair.<br/>',NULL,5101,5101);
INSERT INTO stanza VALUES('E975','2','Both in the garden and the city fair<br/>A river and the tree of life are seen,<br/>Christ typifying as the life supply,<br/>The Spirit showing as the living stream.<br/>',NULL,5102,5102);
INSERT INTO stanza VALUES('E975','3','Both in the garden and the city bright<br/>Three kinds of precious substances are found;<br/>There are the gold, the pearls, and precious stones<br/>Which for the building work of God abound.<br/>',NULL,5103,5103);
INSERT INTO stanza VALUES('E975','4','But in the garden all these precious things<br/>Are just materials lying in the earth,<br/>Yet in the city all are builded up<br/>And form that dwelling of transcendent worth.<br/>',NULL,5104,5104);
INSERT INTO stanza VALUES('E975','5','Man in the garden of the clay was formed,<br/>In nature as the Lord created him<br/>The tree of life was then without the man,<br/>Not having yet become his life within.<br/>',NULL,5105,5105);
INSERT INTO stanza VALUES('E975','6','But in the city glorious the tree<br/>Within the corporate "man" doth grow, thereby<br/>Revealing Christ Himself as life divine<br/>Being to man his inward life supply.<br/>',NULL,5106,5106);
INSERT INTO stanza VALUES('E976','1','O Lord Jesus, Thy redeemed ones<br/>Are Thy Body and Thy Bride;<br/>As Thy fulness, Thine expression,<br/>In her Thou art glorified.<br/>Thou, her all in all forever,<br/>She Thy riches doth declare;<br/>Thou dost fully saturate her<br/>And Thy glory with her share.<br/>',NULL,5107,5107);
INSERT INTO stanza VALUES('E976','chorus','Lo, the holy city,<br/>Full of God''s bright glory!<br/>It is God''s complete expression<br/>In humanity.<br/>',NULL,5108,5108);
INSERT INTO stanza VALUES('E976','2','God with man completely blended,<br/>Mystery of godliness,<br/>God in glory, full, resplendent,<br/>Man, His dwelling, doth express.<br/>''Tis a vessel universal<br/>All God''s fulness to express.<br/>All His beauty manifesting,<br/>Mingled with His holiness.<br/>',NULL,5109,5109);
INSERT INTO stanza VALUES('E976','3','''Tis a living composition<br/>Of the saints He hath transformed;<br/>As the pearls and stones most precious,<br/>To His image they''re conformed:<br/>From the throne of God, its center,<br/>Flows the living water free;<br/>Christ the tree of life doth flourish,<br/>Bearing fruit abundantly.<br/>',NULL,5110,5110);
INSERT INTO stanza VALUES('E976','4','''Tis th'' eternal golden lampstand,<br/>Holding Christ, the lamp of light;<br/>God in Christ the light of glory<br/>As the Spirit shineth bright!<br/>''Tis the ultimate expression-<br/>Man in God and God in man;<br/>''Tis their mutual habitation,<br/>Goal of God''s eternal plan.<br/>',NULL,5111,5111);
INSERT INTO stanza VALUES('E977','1','Glorious things of thee are spoken,<br/>Holy city of our God;<br/>He whose word cannot be broken<br/>Formed thee for His own abode;<br/>On the Rock of Ages founded,<br/>What can shake thy sure repose?<br/>With salvation''s walls surrounded,<br/>Thou may''st smile at all thy foes.<br/>',NULL,5112,5112);
INSERT INTO stanza VALUES('E977','2','See the streams of living waters,<br/>Springing from eternal love,<br/>Well supply thy blessed members,<br/>And all fear of want remove;<br/>Who can faint, when such a river<br/>Ever flows their thirst t'' assuage?<br/>Grace which, like the Lord, the giver, Never fails from age to age.<br/>',NULL,5113,5113);
INSERT INTO stanza VALUES('E977','3','Blest constituents of Zion,<br/>Washed in the Redeemer''s blood;<br/>Jesus, whom their souls rely on,<br/>Makes them kings and priest to God.<br/>''Tis His love His people raises<br/>Over self to reign as kings:<br/>And as priests, His worthy praises,<br/>Each his thankful offering brings.<br/>',NULL,5114,5114);
INSERT INTO stanza VALUES('E977','4','Savior, if of Zion''s city<br/>I, through grace, a member am,<br/>Let the world deride or pity-<br/>I will glory in Thy name.<br/>Fading is the worldlings'' pleasure,<br/>All his boasted pomp and show;<br/>Solid joys and lasting treasure<br/>None but Zion''s members know.<br/>',NULL,5115,5115);
INSERT INTO stanza VALUES('E978','1','In new heaven and new earth<br/>New Jerusalem lies;<br/>Out of God it has its birth,<br/>With God''s radiance thrice.<br/>',NULL,5116,5116);
INSERT INTO stanza VALUES('E978','chorus','Lo, God''s image it doth bear,<br/>And God''s glory it doth share!<br/>And the Lord Himself is there<br/>In that city of God.<br/>',NULL,5117,5117);
INSERT INTO stanza VALUES('E978','2','All the gates are pearls assigned<br/>In the city of gold,<br/>And the street is gold refined<br/>With foundations twelve fold.<br/>',NULL,5118,5118);
INSERT INTO stanza VALUES('E978','3','There life''s crystal river flows<br/>With abundant supplies,<br/>And the tree of life there grows<br/>And all need satisfies.<br/>',NULL,5119,5119);
INSERT INTO stanza VALUES('E978','4','God is there the great I AM<br/>In that city of light;<br/>God''s the light within the Lamb,<br/>And there never is night.<br/>',NULL,5120,5120);
INSERT INTO stanza VALUES('E979','1','How glorious, how bright it shines,<br/>The holy, new Jerusalem;<br/>It is God''s dwelling place with man,<br/>The spotless bride of Christ, the Lamb.<br/>',NULL,5121,1);
INSERT INTO stanza VALUES('E979','2','Saints of the Old and of the New,<br/>Heirs of the promise God bestowed,<br/>Components of the city are,<br/>Together built for God''s abode.<br/>',NULL,5122,2);
INSERT INTO stanza VALUES('E979','3','Perfectly square the city lies,<br/>All sides are equal-length, width, height;<br/>No measurement more long or short,<br/>No part oblique, it stands upright.<br/>',NULL,5123,3);
INSERT INTO stanza VALUES('E979','4','The city with its streets pure gold<br/>As clear as glass transparent is,<br/>Showing that God''s transcendent life<br/>Its quality and nature is.<br/>',NULL,5124,4);
INSERT INTO stanza VALUES('E979','5','Twelve city gates are each one pearl;<br/>Thus man is through redemption shown<br/>Reborn and as a pearl transformed,<br/>Entering to a realm God''s own.<br/>',NULL,5125,5);
INSERT INTO stanza VALUES('E979','6','The twelve foundations of its wall<br/>Are with twelve precious stones adorned;<br/>Through fire and pressure recomposed<br/>And with eternal value formed.<br/>',NULL,5126,6);
INSERT INTO stanza VALUES('E979','7','The wall of jasper, crystal clear,<br/>God''s glory by it fully shown;<br/>His glorious light through it does shine,<br/>And He appears as jasper stone.<br/>',NULL,5127,7);
INSERT INTO stanza VALUES('E979','8','The wall a separation makes,<br/>Excluding all that is unclean;<br/>Gold, pearls, and precious stones alone<br/>The holy city has within.<br/>',NULL,5128,8);
INSERT INTO stanza VALUES('E979','9','God and the Lamb the Temple are!<br/>We shall behold His glorious face;<br/>His presence never will depart,<br/>We''ll worship Him thru endless days.<br/>',NULL,5129,9);
INSERT INTO stanza VALUES('E980','1','Throughout the whole of Holy Writ<br/>The saints in type are manifest<br/>As like a bride, God''s heart to please,<br/>And as a building for His rest.<br/>',NULL,5130,5130);
INSERT INTO stanza VALUES('E980','2','The types and figures of the Church<br/>In the Old Testament are these:<br/>A building meet for life and rule,<br/>A bride the man to match and please.<br/>',NULL,5131,5131);
INSERT INTO stanza VALUES('E980','3','God''s people in the ancient times<br/>Were called by God His very spouse;<br/>Among them and with them were built<br/>God''s ruling city and God''s house.<br/>',NULL,5132,5132);
INSERT INTO stanza VALUES('E980','4','Incarnate God, the God-man, Christ,<br/>As Bridegroom for the Bride has come;<br/>With His own life He quickened her,<br/>That she His counterpart become.<br/>',NULL,5133,5133);
INSERT INTO stanza VALUES('E980','5','In resurrection Christ doth now,<br/>As David''s Son, God''s temple build,<br/>That God may have a resting place<br/>And there accomplish all He willed.<br/>',NULL,5134,5134);
INSERT INTO stanza VALUES('E980','6','The Church is thus the Bride of Christ,<br/>In whom His full delight doth rest;<br/>It is a dwelling place to God<br/>Where He may live and be expressed.<br/>',NULL,5135,5135);
INSERT INTO stanza VALUES('E980','7','The new Jerusalem will be<br/>The full perfection ultimate<br/>Of all the types of house and bride,<br/>Th'' eternal plan to consummate.<br/>',NULL,5136,5136);
INSERT INTO stanza VALUES('E980','8','It is the Bride which matches Christ,<br/>Thru whom He may Himself express;<br/>It is God''s tabernacle too<br/>In which our God can rule and rest.<br/>',NULL,5137,5137);
INSERT INTO stanza VALUES('E980','9','The ultimate completion ''tis<br/>Of God''s work in humanity,<br/>His full expression glorious<br/>Thru His redeemed eternally.<br/>',NULL,5138,5138);
INSERT INTO stanza VALUES('E981','1','In His Christ to head up all things<br/>Is our God''s economy;<br/>Taking Christ as Head and Center,<br/>All is one in harmony.<br/>',NULL,5139,5139);
INSERT INTO stanza VALUES('E981','2','Christ as Head will be the Center;<br/>God within will be the Light;<br/>Christ enthroned, with God, His substance,<br/>Will fulfill His heart''s delight.<br/>',NULL,5140,5140);
INSERT INTO stanza VALUES('E981','3','Christ as life will be the content,<br/>Heading up all things in light;<br/>All the saints will be the vessel,<br/>To express His glory bright.<br/>',NULL,5141,5141);
INSERT INTO stanza VALUES('E981','4','Satan hath himself injected<br/>Into man all things to spoil,<br/>Bringing darkness and corruption<br/>God''s eternal plan to foil.<br/>',NULL,5142,5142);
INSERT INTO stanza VALUES('E981','5','Christ has come, Himself imparting<br/>Into man as life to save,<br/>That the pow''r of death and darkness<br/>May no more all things enslave.<br/>',NULL,5143,5143);
INSERT INTO stanza VALUES('E981','6','Thru the Church which is His Body<br/>Christ as Head will sum up all;<br/>All will fitly join together,<br/>All things either great or small.<br/>',NULL,5144,5144);
INSERT INTO stanza VALUES('E981','7','Under Christ, by His full headship,<br/>All in union will subsist;<br/>In the light the Church expresses<br/>All in oneness will exist.<br/>',NULL,5145,5145);
INSERT INTO stanza VALUES('E981','8','Owning Christ as Head and Center,<br/>All will be in harmony;<br/>Thru the shining of His Body<br/>All will share His liberty.<br/>',NULL,5146,5146);
INSERT INTO stanza VALUES('E981','9','No more darkness and corruption,<br/>No more death and vanity;<br/>All will be released from bondage<br/>Throughout all eternity.<br/>',NULL,5147,5147);
INSERT INTO stanza VALUES('E982','1','How true it is not heart may comprehend<br/>The glory God prepareth for His own,<br/>And what will happen when this age shall end;<br/>But yet in vision Jesus hath made known<br/>How fair and holy shall the Church descend,<br/>Lit up with light of precious jasper stone.<br/>',NULL,5148,5148);
INSERT INTO stanza VALUES('E982','2','And He shall make His Church all heavenly fair,<br/>With gold and pearls, and every radiant stone,<br/>And reign in holiness and glory there,<br/>And shine as suns and stars have never shone;<br/>And He shall lead His Bride, His joy and care,<br/>With blissful singing to His Father''s throne.<br/>',NULL,5149,5149);
INSERT INTO stanza VALUES('E982','3','And then the blest communion shall have come,<br/>Of God''s dear children meeting from afar;<br/>Within His burning love they blend as one,<br/>Yet each, according as His counsels are,<br/>Shall have peculiar glory of his own,<br/>As on star differeth from another star.<br/>',NULL,5150,5150);
INSERT INTO stanza VALUES('E982','4','And God is all in all in that great day,<br/>And He is their exceeding great Reward;<br/>Their stream of life, their beautiful array,<br/>Their food, their joy, their radiance, Christ the Lord;<br/>The music of their wondrous song shall say,<br/>How great the joy that passeth thought or word.<br/>',NULL,5151,5151);
INSERT INTO stanza VALUES('E982','5','And this is that eternal life of heaven,<br/>Laid up with Christ in God, the mystery<br/>Of resurrection life which He hath given:<br/>A fount of living waters full and free;<br/>A life by which the gates of death are riven,<br/>A life which on the throne of Christ shall be.<br/>',NULL,5152,5152);
INSERT INTO stanza VALUES('E982','6','And here in this waste wilderness began,<br/>So soon as we believe in Christ aright,<br/>And quickened by the Spirit of the Son,<br/>Receive Him as our only life and light,<br/>As all the branches in the vine are one,<br/>So we are one forever in His sight.<br/>',NULL,5153,5153);
INSERT INTO stanza VALUES('E982','7','Now come, Lord Jesus, quickly from above,<br/>Do Thou sustain us on the desert road,<br/>And draw us after Thee by might of love,<br/>Our Fatherland art Thou, O love of God;<br/>Once safe in Thee, no more shall we remove,<br/>O Thou our everlasting sure abode.<br/>',NULL,5154,5154);
INSERT INTO stanza VALUES('E983','1','There is a stream which issues forth<br/>From God''s eternal throne<br/>And from the Lamb, a living stream,<br/>Clear as the crystal stone.<br/>In it doth grow the tree of life,<br/>It makes the ransomed sing:<br/>Its living draught revives the heart;<br/>Hence all the joys do spring.<br/>',NULL,5155,5155);
INSERT INTO stanza VALUES('E983','2','Such joys as are unspeakable,<br/>And full of glory too;<br/>Such splendid riches, meat and drink,<br/>As worldings do not know.<br/>Eye hath not seen, nor ear hath heard,<br/>For fancy ''tis concealed,<br/>What Thou, Lord, hast laid up for Thine<br/>And hast to me revealed.<br/>',NULL,5156,5156);
INSERT INTO stanza VALUES('E983','3','I feel Thy touch, I hear Thy voice,<br/>I taste Thy sweetest grace;<br/>My soul doth leap: but, oh, that I<br/>May see Thee face to face!<br/>Then with the saints my soul shall feast<br/>On joys that always last:<br/>Blest be my God, the God of joy,<br/>That gives here such a taste!<br/>',NULL,5157,5157);
INSERT INTO stanza VALUES('E984','1','River of living water,<br/>River that flows from the throne,<br/>Fellowship giving and making<br/>God''s own authority known.<br/>',NULL,5158,5158);
INSERT INTO stanza VALUES('E984','chorus','River of living water,<br/>Fellowship freely bestows;<br/>Bringing authority with it,<br/>Through every place where it flows.<br/>',NULL,5159,5159);
INSERT INTO stanza VALUES('E984','2','Water of life is the Spirit,<br/>God as the life in it flows;<br/>Carrying with it His Lordship,<br/>Through every place where it goes.<br/>',NULL,5160,5160);
INSERT INTO stanza VALUES('E984','3','Midst the gold street it floweth,<br/>Thus showing to us the way;<br/>As in God''s nature it floweth,<br/>So in His way we will stay.<br/>',NULL,5161,5161);
INSERT INTO stanza VALUES('E984','4','The tree of life by the river,<br/>Shows to us God as our food;<br/>We by the river''s full flowing<br/>Take of the tree''s plenitude.<br/>',NULL,5162,5162);
INSERT INTO stanza VALUES('E985','1','No more in earthen vessels<br/>God''s treasure then shall be,<br/>But in unclouded beauty<br/>Thou, Lord, wilt shine thru me.<br/>',NULL,5163,5163);
INSERT INTO stanza VALUES('E985','2','Afar thru that gold vessel<br/>God'' glory shineth bright;<br/>There''ll be no need of sunshine,<br/>For God will be the light.<br/>',NULL,5164,5164);
INSERT INTO stanza VALUES('E985','3','With Christ, the Stone most precious,<br/>God''s city shall be fair;<br/>And He shall shine as jasper<br/>In cloudless glory there:<br/>',NULL,5165,5165);
INSERT INTO stanza VALUES('E985','4','Undimmed in that great vessel,<br/>The glory of that light,<br/>Illum''ning with its fulness<br/>The earth in radiance bright.<br/>',NULL,5166,5166);
INSERT INTO stanza VALUES('E985','5','All in His new creation<br/>God''s glory there shall see;<br/>The vessel for that shining<br/>The Lamb''s own Bride shall be:<br/>',NULL,5167,5167);
INSERT INTO stanza VALUES('E985','6','A golden vessel glorious,<br/>That all who see adore<br/>God in the Lamb in glory<br/>Expressed forevermore.<br/>',NULL,5168,5168);
INSERT INTO stanza VALUES('E986','1','Christ has a full redemption made:<br/>What wonderful Savior!<br/>We are redeemed! The price is paid:<br/>What a wonderful Savior!<br/>',NULL,5169,5169);
INSERT INTO stanza VALUES('E986','chorus','What a wonderful Savior is Jesus, my Savior;<br/>What a wonderful Savior is Jesus, my Lord!<br/>',NULL,5170,5170);
INSERT INTO stanza VALUES('E986','2','I praise Him for the cleansing blood,<br/>What a wonderful Savior!<br/>That reconciled my soul to God,<br/>What a wonderful Savior!<br/>',NULL,5171,5171);
INSERT INTO stanza VALUES('E986','3','He cleanses me from all my sin:<br/>What a wonderful Savior!<br/>And now He reigns and rules within;<br/>What a wonderful Savior!<br/>',NULL,5172,5172);
INSERT INTO stanza VALUES('E986','4','He dwells within me day by day,<br/>What a wonderful Savior!<br/>And keeps me faithful all the way,<br/>What a wonderful Savior!<br/>',NULL,5173,5173);
INSERT INTO stanza VALUES('E986','5','He gives me overcoming power,<br/>What a wonderful Savior!<br/>And triumph in each conflict hour,<br/>What a wonderful Savior!<br/>',NULL,5174,5174);
INSERT INTO stanza VALUES('E986','6','To Him I''ve given all my heart,<br/>What a wonderful Savior!<br/>The world shall never share a part,<br/>What a wonderful Savior!<br/>',NULL,5175,5175);
INSERT INTO stanza VALUES('E987','1','One day when heaven was filled with His praises,<br/>One day when sin was black as could be,<br/>Jesus came forth to be born of a virgin-<br/>Dwelt among men, my example is He!<br/>',NULL,5176,5176);
INSERT INTO stanza VALUES('E987','chorus','Living, He loved me; dying, He saved me;<br/>Buried, He carried my sins far away;<br/>Rising, He justified freely forever:<br/>One day He''s coming-O glorious day!<br/>',NULL,5177,5177);
INSERT INTO stanza VALUES('E987','2','One day they led Him up Calvary''s mountain,<br/>One day they nailed Him to die on the tree;<br/>Suffering anguish, despised and rejected;<br/>Bearing our sins, my Redeemer is He.<br/>',NULL,5178,5178);
INSERT INTO stanza VALUES('E987','3','One day they left Him alone in the garden,<br/>One day He rested, from suffering free;<br/>Angels came down o''er His tomb to keep vigil;<br/>Hope of the hopeless, my Savior is He.<br/>',NULL,5179,5179);
INSERT INTO stanza VALUES('E987','4','One day the grave could conceal Him no longer,<br/>One day the stone rolled away from the door;<br/>Then He arose, over death He had conquered;<br/>Now is ascended, my Lord evermore.<br/>',NULL,5180,5180);
INSERT INTO stanza VALUES('E987','5','One day the trumpet will sound for His coming,<br/>One day the skies with His glory will shine;<br/>Wonderful day, my beloved ones bringing;<br/>Glorious Savior, this Jesus is mine!<br/>',NULL,5181,5181);
INSERT INTO stanza VALUES('E988','1','Merciful and loving,<br/>Suff''ring pain and loss,<br/>All for us, the sinners,<br/>Going to the cross;<br/>Tasting death for all men,<br/>Dying for our sins;<br/>This is Christ the Savior,<br/>What will you do with Him?<br/>',NULL,5182,5182);
INSERT INTO stanza VALUES('E989','1','Jesus, my Savior, to Bethlehem came,<br/>Laid in a manger to sorrow and shame;<br/>O it was wonderful, blest be His name,<br/>Seeking for me, for me:<br/>Seeking for me, for me,<br/>Seeking for me, for me;<br/>O it was wonderful, blest be His name,<br/>Seeking for me, for me.<br/>',NULL,5183,5183);
INSERT INTO stanza VALUES('E989','2','Jesus, my Savior, on Calvary''s tree<br/>Paid the great debt, and my soul He set free;<br/>O it was wonderful-how could it be?<br/>Dying for me, for me!<br/>Dying for me, for me,<br/>Dying for me, for me;<br/>O it was wonderful-how could it be?<br/>Dying for me, for me!<br/>',NULL,5184,5184);
INSERT INTO stanza VALUES('E989','3','Jesus, my Savior, the same as of old,<br/>While I was wand''ring in darkness and cold,<br/>Gently and long did He plead with my soul,<br/>Calling for me, for me!<br/>Calling for me, for me,<br/>Calling for me, for me;<br/>Gently and long did He plead with my soul,<br/>Calling for me, for me!<br/>',NULL,5185,5185);
INSERT INTO stanza VALUES('E989','4','Jesus, my Savior, shall come from on high.<br/>Sweet is the promise as weary years fly:<br/>O I shall see Him descend from the sky,<br/>Coming for me, for me!<br/>Coming for me, for me,<br/>Coming for me, for me;<br/>O I shall see Him descend from the sky,<br/>Coming for me, for me!<br/>',NULL,5186,5186);
INSERT INTO stanza VALUES('E990','1','The Great Physician now is near,<br/>The sympathizing Jesus;<br/>He speaks the drooping heart to cheer,<br/>Oh, hear the voice of Jesus!<br/>',NULL,5187,5187);
INSERT INTO stanza VALUES('E990','chorus','Sweetest note in seraph song;<br/>Sweetest name on mortal tongue;<br/>Sweetest carol ever sung:<br/>Jesus, blessed Jesus!<br/>',NULL,5188,5188);
INSERT INTO stanza VALUES('E990','2','Your many sins are all forgiv''n,<br/>Oh, hear the voice of Jesus;<br/>The veil ''twixt you and God is riven,<br/>Redemption wrought by Jesus.<br/>',NULL,5189,5189);
INSERT INTO stanza VALUES('E990','3','All glory to the dying Lamb!<br/>I now believe in Jesus;<br/>I love the blessed Savior''s name,<br/>I love the name of Jesus.<br/>',NULL,5190,5190);
INSERT INTO stanza VALUES('E990','4','His name dispels my guilt and fear,<br/>No other name but Jesus;<br/>Oh, how my soul delights to hear<br/>The precious name of Jesus!<br/>',NULL,5191,5191);
INSERT INTO stanza VALUES('E991','1','We have heard the joyful sound:<br/>Jesus saves! Jesus saves!<br/>Spread the tidings all around:<br/>Jesus saves! Jesus saves!<br/>Bear the news to every land,<br/>Climb the steeps and cross the waves;<br/>Onward! - ''tis our Lord''s command;<br/>Jesus saves! Jesus saves!<br/>',NULL,5192,5192);
INSERT INTO stanza VALUES('E991','2','Waft it on the rolling tide,<br/>Jesus saves, Jesus saves;<br/>Tell to sinners far and wide,<br/>Jesus saves, Jesus saves;<br/>Sing, ye islands of the sea,<br/>Echo back, ye ocean caves;<br/>Earth shall keep her jubilee,<br/>Jesus saves, Jesus saves.<br/>',NULL,5193,5193);
INSERT INTO stanza VALUES('E991','3','Sing above the battle''s strife,<br/>Jesus saves, Jesus saves;<br/>By His death and endless life,<br/>Jesus saves, Jesus saves;<br/>Sing it softly thru the gloom,<br/>When the heart for mercy craves,<br/>Sing in triumph o''er the tomb,<br/>Jesus saves, Jesus saves.<br/>',NULL,5194,5194);
INSERT INTO stanza VALUES('E991','4','Give the winds a mighty voice,<br/>Jesus saves, Jesus saves;<br/>Let the nations now rejoice.<br/>Jesus saves, Jesus saves;<br/>Shout salvation full and free,<br/>Highest hills and deepest caves,<br/>This our song of victory,<br/>Jesus saves, Jesus saves.<br/>',NULL,5195,5195);
INSERT INTO stanza VALUES('E992','1','There''s not a Friend like the lowly Jesus:<br/>No, not one! No, not one!<br/>None else could heal all our souls'' diseases:<br/>No, not one! No, not one!<br/>',NULL,5196,5196);
INSERT INTO stanza VALUES('E992','chorus','Jesus knows all about our struggles;<br/>He will guide till the day is done:<br/>There''s not a Friend like the lowly Jesus:<br/>No, not one! No, not one!<br/>',NULL,5197,5197);
INSERT INTO stanza VALUES('E992','2','No friend like Him is so high and holy,<br/>No, not one! No, not one!<br/>And yet no friend is so meek and lowly,<br/>No, not one! No, not one!<br/>',NULL,5198,5198);
INSERT INTO stanza VALUES('E992','3','There''s not an hour that He is not near us,<br/>No, not one! No, not one!<br/>No night so dark, but His love can cheer us,<br/>No, not one! No, not one!<br/>',NULL,5199,5199);
INSERT INTO stanza VALUES('E992','4','Did ever saint find this Friend forsake him?<br/>No, not one! No, not one!<br/>Or sinner find that He would not take him?<br/>No, not one! No, not one!<br/>',NULL,5200,5200);
INSERT INTO stanza VALUES('E992','5','Was e''er a gift like the Savior given?<br/>No, not one! No, not one!<br/>Will He refuse us the bliss of heaven?<br/>No, not one! No, not one!<br/>',NULL,5201,5201);
INSERT INTO stanza VALUES('E993','1','O how sweet the glorious message,<br/>Simple faith my claim;<br/>Yesterday, today, forever,<br/>Jesus is the same.<br/>Still He loves to save the sinful,<br/>Heal the sick and lame;<br/>Cheer the mourner, still the tempest;<br/>Glory to His name!<br/>',NULL,5202,5202);
INSERT INTO stanza VALUES('E993','chorus','Yesterday, today, forever,<br/>Jesus is the same,<br/>All may change, but Jesus never!<br/>Glory to His name,<br/>Glory to His name,<br/>Glory to His name,<br/>All may change, but Jesus never!<br/>Glory to His name.<br/>',NULL,5203,5203);
INSERT INTO stanza VALUES('E993','2','He who was the friend of sinners,<br/>Seeks thee, lost one, now;<br/>Sinner, come, and at His footstool,<br/>Penitently bow.<br/>He who said, "I''ll not condemn thee,<br/>Go and sin no more,"<br/>Speaks to thee that word of pardon,<br/>As in days of yore.<br/>',NULL,5204,5204);
INSERT INTO stanza VALUES('E993','3','Oft on earth He healed the suff''rer,<br/>By His mighty hand;<br/>Still our sicknesses and sorrows,<br/>Go at His command.<br/>He who gave His healing virtue,<br/>To a woman''s touch;<br/>To the faith that claims His fulness,<br/>Still will give as much.<br/>',NULL,5205,5205);
INSERT INTO stanza VALUES('E993','4','As of old He walked to Emmaus,<br/>With them to abide;<br/>So through all life''s way He walketh,<br/>Ever near our side.<br/>Soon again we shall behold Him,<br/>Hasten, Lord, the day!<br/>But ''twill still be "this same Jesus,"<br/>As he went away.<br/>',NULL,5206,5206);
INSERT INTO stanza VALUES('E994','1','Oh, how dark the night that wrapt my spirit round!<br/>Oh, how deep the woe my Savior found<br/>When He walked across the waters of my soul,<br/>Bade my night disperse and made me whole!<br/>',NULL,5207,5207);
INSERT INTO stanza VALUES('E994','chorus','All the way to Calvary He went for me,<br/>He went for me, He went for me;<br/>All the way to Calvary He went for me,<br/>He died to set me free.<br/>',NULL,5208,5208);
INSERT INTO stanza VALUES('E994','2','Tremblingly a sinner bowed before His face,<br/>Naught I knew of pardon, God''s free grace;<br/>Heard a voice so melting, "Cease they wild regret,<br/>Jesus bought thy pardon, paid thy debt."<br/>',NULL,5209,5209);
INSERT INTO stanza VALUES('E994','3','O ''twas wondrous love the Savior showed for me!<br/>When He left His throne for Calvary,<br/>When He bore my trespass, bore it all alone;<br/>Praise His name forever, make it known.<br/>',NULL,5210,5210);
INSERT INTO stanza VALUES('E995','1','There is a green hill far away,<br/>Without a city wall,<br/>Where the dear Lord was crucified,<br/>Who died to save us all.<br/>',NULL,5211,5211);
INSERT INTO stanza VALUES('E995','chorus','Oh, dearly, dearly has He loved,<br/>And died our sins to bear;<br/>We trust in His redeeming blood,<br/>And life eternal share.<br/>',NULL,5212,5212);
INSERT INTO stanza VALUES('E995','2','We may not know, we cannot tell,<br/>What pains He had to bear;<br/>But we believe it was for us,<br/>He hung and suffered there.<br/>',NULL,5213,5213);
INSERT INTO stanza VALUES('E995','3','He died that we might be forgiven,<br/>He died to make us good,<br/>That we might from our sins be freed,<br/>Saved by His precious blood.<br/>',NULL,5214,5214);
INSERT INTO stanza VALUES('E995','4','There was no other good enough<br/>To pay the price of sin,<br/>He only could divine life give<br/>And dwell Himself within.<br/>',NULL,5215,5215);
INSERT INTO stanza VALUES('E996','1','Jesus, Savior, Son of God,<br/>Bearer of the sinner''s load,<br/>Breaker of the captive''s chain,<br/>Cleanser of the guilty''s stain.<br/>',NULL,5216,5216);
INSERT INTO stanza VALUES('E996','2','Thou the sinner''s death hast died,<br/>Thou for us wast crucified;<br/>For our sins Thy flesh was torn,<br/>Thou our penalty hast borne.<br/>',NULL,5217,5217);
INSERT INTO stanza VALUES('E996','3','Savior, Surety, Lamb of God,<br/>Thou hast bought us with Thy blood;<br/>Thou hast wiped the debt away,<br/>Nothing left for us to pay;<br/>',NULL,5218,5218);
INSERT INTO stanza VALUES('E996','4','Nothing left for us to bear,<br/>Nothing left for us to share<br/>But the pardon and the bliss,<br/>But the love, the light, the peace.<br/>',NULL,5219,5219);
INSERT INTO stanza VALUES('E996','5','I to Thee will look and live,<br/>And, in looking, praises give;<br/>Looking lightens, looking heals,<br/>Looking all the gladness seals.<br/>',NULL,5220,5220);
INSERT INTO stanza VALUES('E996','6','Jesus, Savior, Son of God,<br/>Bearer of the sinner''s load,<br/>I would rise to Thee above,<br/>I would look, and praise, and love.<br/>',NULL,5221,5221);
INSERT INTO stanza VALUES('E997','1','I hear the Savior say,<br/>"Thy strength indeed is small,<br/>Child of weakness, watch and pray,<br/>Find in Me thine all in all."<br/>',NULL,5222,5222);
INSERT INTO stanza VALUES('E997','chorus','Jesus paid it all,<br/>All to Him I owe;<br/>Sin had left a crimson stain,<br/>He washed it white as snow.<br/>',NULL,5223,5223);
INSERT INTO stanza VALUES('E997','2','Lord, now indeed I find<br/>Thy pow''r, and Thine alone,<br/>Can change the leper''s spots,<br/>And melt the heart of stone.<br/>',NULL,5224,5224);
INSERT INTO stanza VALUES('E997','3','For nothing good have I<br/>Whereby Thy grace to claim-<br/>I''ll wash my garments white<br/>In the blood of Calv''ry''s Lamb.<br/>',NULL,5225,5225);
INSERT INTO stanza VALUES('E997','4','And when, before the throne,<br/>I stand in Him complete,<br/>"Jesus died my soul to save,"<br/>My lips shall still repeat.<br/>',NULL,5226,5226);
INSERT INTO stanza VALUES('E998','1','Christ has become one with sinners,<br/>Sharing in all of our living;<br/>Crucified even for sinners,<br/>Glorious life to us giving.<br/>',NULL,5227,5227);
INSERT INTO stanza VALUES('E998','2','Christ Jesus came for us,<br/>Christ Jesus died for us;<br/>O yes, for us, for us, for us.<br/>Christ came and died for us.<br/>',NULL,5228,5228);
INSERT INTO stanza VALUES('E999','1','Alas, and did my Savior bleed?<br/>And did my Sovereign die?<br/>Would He devote that sacred head<br/>For such a worm as I?<br/>',NULL,5229,5229);
INSERT INTO stanza VALUES('E999','chorus','At the cross, at the cross where<br/>I first saw the light,<br/>And the burden of my heart rolled away,<br/>It was there by faith I received my sight,<br/>And now I am happy all the day!<br/>',NULL,5230,5230);
INSERT INTO stanza VALUES('E999','2','Was it for sins that I had done<br/>He groaned upon the tree?<br/>Amazing pity! Grace unknown!<br/>And love beyond degree!<br/>',NULL,5231,5231);
INSERT INTO stanza VALUES('E999','3','Well might the sun in darkness hide,<br/>And shut His glories in,<br/>When Christ, the mighty Maker, died<br/>For man, His creature''s sin.<br/>',NULL,5232,5232);
INSERT INTO stanza VALUES('E999','4','Thus might I hide my blushing face<br/>While His dear cross appears.<br/>Dissolve my heart in thankfulness,<br/>And melt mine eyes to tears.<br/>',NULL,5233,5233);
INSERT INTO stanza VALUES('E999','5','But drops of grief can ne''er repay<br/>The debt of love I owe;<br/>Here, Lord I give myself away,<br/>''Tis all that I can do.<br/>',NULL,5234,5234);
INSERT INTO stanza VALUES('E1000','1','Working will not save me;<br/>Purest deeds that I can do,<br/>Holiest thoughts and feelings too,<br/>Cannot form my soul anew;<br/>Working will not save me.<br/>',NULL,5235,5235);
INSERT INTO stanza VALUES('E1000','chorus','Jesus wept and died for me;<br/>Jesus suffered on the tree;<br/>Jesus waits to make me free,<br/>He alone can save me.<br/>',NULL,5236,5236);
INSERT INTO stanza VALUES('E1000','2','Weeping will not save me;<br/>Though my face were bathed in tears,<br/>That could not allay my fears,<br/>Could not wash the sins of years;<br/>Weeping will not save me.<br/>',NULL,5237,5237);
INSERT INTO stanza VALUES('E1000','3','Waiting will not save me;<br/>Helpless, guilty, lost I lie,<br/>In my ear is mercy''s cry;<br/>If I wait I can but die:<br/>Waiting will not save me.<br/>',NULL,5238,5238);
INSERT INTO stanza VALUES('E1000','4','Praying will not save me;<br/>All the prayers that I could say<br/>Could not wash my sins away,<br/>All I owe could never pay:<br/>Praying will not save me.<br/>',NULL,5239,5239);
INSERT INTO stanza VALUES('E1000','5','Faith in Christ will save me;<br/>Let me trust Thy gracious Son,<br/>Trust the work that He has done,<br/>To His arms, Lord, help me run;<br/>Faith in Christ will save me.<br/>',NULL,5240,5240);
INSERT INTO stanza VALUES('E1001','1','Free from the law-oh, happy condition!<br/>Jesus hath bled, and there is remission;<br/>Cursed by the law and bruised by the fall,<br/>Christ hath redeemed us once for all.<br/>',NULL,5241,5241);
INSERT INTO stanza VALUES('E1001','chorus','Once for all-oh, sinner, receive it;<br/>Once for all-oh, doubter, believe it;<br/>Cling to the cross, the burden will fall,<br/>Christ hath redeemed us once for all.<br/>',NULL,5242,5242);
INSERT INTO stanza VALUES('E1001','2','There on the cross your burden upbearing,<br/>Thorns on His brow your Savior is wearing;<br/>Never again your sin need appall,<br/>You have been pardoned once for all.<br/>',NULL,5243,5243);
INSERT INTO stanza VALUES('E1001','3','Now we are free-there''s no condemnation;<br/>Jesus provides a perfect salvation:<br/>"Come unto Me," oh, hear His sweet call,<br/>Come, and He saves us once for all.<br/>',NULL,5244,5244);
INSERT INTO stanza VALUES('E1001','4','Children of man-oh, glorious calling,<br/>Surely His grace will keep us from falling;<br/>Passing from death to life at His call,<br/>Blessed salvation once for all.<br/>',NULL,5245,5245);
INSERT INTO stanza VALUES('E1002','1','Nothing either great or small -<br/>Nothing, sinner, no;<br/>Jesus did it, did it all,<br/>Long, long ago.<br/>',NULL,5246,5246);
INSERT INTO stanza VALUES('E1002','chorus','"It is finished!" yes, indeed,<br/>Finished every jot:<br/>Sinner, this is all you need -<br/>Tell me, is it not?<br/>',NULL,5247,5247);
INSERT INTO stanza VALUES('E1002','2','When He, from His lofty throne,<br/>Stooped to do and die,<br/>Everything was fully done;<br/>Hearken to His cry:<br/>',NULL,5248,5248);
INSERT INTO stanza VALUES('E1002','3','Weary, working, burdened one,<br/>Wherefore toil you so?<br/>Cease your doing; all was done<br/>Long, long ago.<br/>',NULL,5249,5249);
INSERT INTO stanza VALUES('E1002','4','Till to Jesus'' work you cling<br/>By a simple faith,<br/>"Doing" is a deadly thing -<br/>"Doing" ends in death.<br/>',NULL,5250,5250);
INSERT INTO stanza VALUES('E1002','5','Cast your deadly "doing" down -<br/>Down at Jesus'' feet;<br/>Stand in Him, in Him alone,<br/>Gloriously complete.<br/>',NULL,5251,5251);
INSERT INTO stanza VALUES('E1003','1','Why should I worry, doubt and fear?<br/>Has God not caused His Son to bear<br/>My sins upon the tree?<br/>The debt that Christ for me has paid,<br/>Would God another mind have made<br/>To claim again from me?<br/>',NULL,5252,5252);
INSERT INTO stanza VALUES('E1003','2','Redemption full the Lord has made,<br/>And all my debts has fully paid,<br/>From law to set me free.<br/>I fear not for the wrath of God,<br/>For I''ve been sprinkled with His blood,<br/>It wholly covers me.<br/>',NULL,5253,5253);
INSERT INTO stanza VALUES('E1003','3','For me forgiveness He has gained,<br/>And full acquittal was obtained,<br/>All debts of sin are paid;<br/>God would not have His claim on two,<br/>First on His Son, my Surety true,<br/>And then upon me laid.<br/>',NULL,5254,5254);
INSERT INTO stanza VALUES('E1003','4','So now I have full peace and rest,<br/>My Savior Christ hath done the best<br/>And set me wholly free;<br/>By His all-efficacious blood<br/>I ne''er could be condemned by God,<br/>For He has died for me!<br/>',NULL,5255,5255);
INSERT INTO stanza VALUES('E1004','1','Precious, precious blood of Jesus,<br/>Shed on Calvary;<br/>Shed for rebels, shed for sinners,<br/>Shed for thee.<br/>',NULL,5256,5256);
INSERT INTO stanza VALUES('E1004','chorus','Precious, precious blood of Jesus<br/>Ever flowing free;<br/>Oh, believe it; oh, receive it,<br/>''Tis for thee.<br/>',NULL,5257,5257);
INSERT INTO stanza VALUES('E1004','2','Precious, precious blood of Jesus,<br/>Let it make thee whole;<br/>Let it flow in mighty cleansing,<br/>O''er thy soul.<br/>',NULL,5258,5258);
INSERT INTO stanza VALUES('E1004','3','Though thy sins are red like crimson,<br/>Deep in scarlet glow,<br/>Jesus'' precious blood shall wash thee,<br/>White as snow.<br/>',NULL,5259,5259);
INSERT INTO stanza VALUES('E1004','4','Precious blood that hath redeemed us!<br/>All the price is paid;<br/>Perfect pardon now is offered,<br/>Peace is made.<br/>',NULL,5260,5260);
INSERT INTO stanza VALUES('E1004','5','Now the holiest with boldness<br/>We may enter in;<br/>For the open fountain cleanseth<br/>From all sin.<br/>',NULL,5261,5261);
INSERT INTO stanza VALUES('E1004','6','Precious blood, by this we conquer<br/>In the fiercest fight,<br/>Sin and Satan overcoming<br/>By its might.<br/>',NULL,5262,5262);
INSERT INTO stanza VALUES('E1004','7','Precious blood whose full redemption<br/>Makes us nigh to God;<br/>Precious blood, our way of glory,<br/>Praise and laud.<br/>',NULL,5263,5263);
INSERT INTO stanza VALUES('E1005','1','Christ our Redeemer died on the cross,<br/>Died for the sinner, paid all his due;<br/>Sprinkle your soul with the blood of<br/>the Lamb,<br/>"And I will pass, will pass over your."<br/>',NULL,5264,5264);
INSERT INTO stanza VALUES('E1005','chorus','"When I see the blood,<br/>When I see the blood,<br/>When I see the blood,<br/>I will pass, I will pass over you."<br/>',NULL,5265,5265);
INSERT INTO stanza VALUES('E1005','2','Chiefest of sinners, Jesus will save;<br/>All He has promised, that will He do;<br/>Wash in the fountain opened for sin,<br/>"And I will pass, will pass over you."<br/>',NULL,5266,5266);
INSERT INTO stanza VALUES('E1005','3','Judgment is coming, all will be there,<br/>Each one receiving justly his due;<br/>Hide in the saving, sin-cleansing blood,<br/>"And I will pass, will pass over you."<br/>',NULL,5267,5267);
INSERT INTO stanza VALUES('E1005','4','O great compassion! O boundless love!<br/>O loving kindness, faithful and true!<br/>Find peace and shelter under the blood,<br/>"And I will pass, will pass over you."<br/>',NULL,5268,5268);
INSERT INTO stanza VALUES('E1006','1','There is a fountain filled with blood<br/>Drawn from Immanuel''s veins;<br/>And sinners, plunged beneath that flood,<br/>Lose all their guilty stains:<br/>Lose all their guilty stains,<br/>Lose all their guilty stains;<br/>And sinners, plunged beneath that flood,<br/>Lose all their guilty stains.<br/>',NULL,5269,5269);
INSERT INTO stanza VALUES('E1006','2','The dying thief rejoiced to see<br/>That fountain in his day;<br/>And there may I, though vile as he,<br/>Wash all my sins away:<br/>Wash all my sins away,<br/>Wash all my sins away;<br/>And there may I, though vile as he,<br/>Wash all my sins away.<br/>',NULL,5270,5270);
INSERT INTO stanza VALUES('E1006','3','Dear dying Lamb, Thy precious blood<br/>Shall never lose its power,<br/>Till all the ransomed ones of God<br/>Be saved, to sin no more:<br/>Be saved, to sin no more,<br/>Be saved, to sin no more;<br/>Till all the ransomed ones of God<br/>Be saved, to sin no more.<br/>',NULL,5271,5271);
INSERT INTO stanza VALUES('E1006','4','E''er since by faith I saw the stream<br/>Thy flowing wounds supply,<br/>Redeeming love has been my theme,<br/>And shall be till I die:<br/>And shall be till I die,<br/>And shall be till I die;<br/>Redeeming love has been my theme,<br/>And shall be till I die.<br/>',NULL,5272,5272);
INSERT INTO stanza VALUES('E1006','5','When this poor lisping, stammering tongue<br/>Lies silent in the grave,<br/>Then in a nobler, sweeter song,<br/>I''ll sing Thy power to save:<br/>I''ll sing Thy power to save,<br/>I''ll sing Thy power to save;<br/>Then in a nobler, sweeter song,<br/>I''ll sing Thy power to save.<br/>',NULL,5273,5273);
INSERT INTO stanza VALUES('E1007','1','Have you been to Jesus for the<br/>cleansing pow''r?<br/>Are you washed in the blood of the Lamb?<br/>Are you fully trusting in His grace this hour?<br/>Are you washed in the blood of the Lamb?<br/>',NULL,5274,5274);
INSERT INTO stanza VALUES('E1007','chorus','Are you washed in the blood,<br/>In the soul-cleansing blood of the Lamb?<br/>Are your garments spotless?<br/>Are they white as snow?<br/>Are you washed in the blood of the Lamb?<br/>',NULL,5275,5275);
INSERT INTO stanza VALUES('E1007','2','Are you walking daily by the Savior''s side?<br/>Are you washed in the blood of the Lamb?<br/>Do you rest each moment in the Crucified?<br/>Are you washed in the blood of the Lamb?<br/>',NULL,5276,5276);
INSERT INTO stanza VALUES('E1007','3','When the Bridegroom cometh will<br/>your robes be white?<br/>Are you washed in the blood of the Lamb?<br/>Will your soul be ready for His presence bright,<br/>And be washed in the blood of the Lamb?<br/>',NULL,5277,5277);
INSERT INTO stanza VALUES('E1007','4','Lay aside the garments that are stained with sin,<br/>And be washed in the blood of the Lamb;<br/>There''s a fountain flowing for the soul unclean,<br/>O be washed in the blood of the Lamb.<br/>',NULL,5278,5278);
INSERT INTO stanza VALUES('E1008','1','What can wash away my sin?<br/>Nothing but the blood of Jesus;<br/>What can make me whole again?<br/>Nothing but the blood of Jesus.<br/>',NULL,5279,5279);
INSERT INTO stanza VALUES('E1008','chorus','Oh! Precious is the flow<br/>That makes me white as snow;<br/>No other fount I know,<br/>Nothing but the blood of Jesus.<br/>',NULL,5280,5280);
INSERT INTO stanza VALUES('E1008','2','For my cleansing this I see-<br/>Nothing but the blood of Jesus!<br/>For my pardon this my plea-<br/>Nothing but the blood of Jesus!<br/>',NULL,5281,5281);
INSERT INTO stanza VALUES('E1008','3','Nothing can my sin erase-<br/>Nothing but the blood of Jesus!<br/>Naught of works, ''tis all of grace-<br/>Nothing but the blood of Jesus!<br/>',NULL,5282,5282);
INSERT INTO stanza VALUES('E1008','4','This is all my hope and peace-<br/>Nothing but the blood of Jesus!<br/>This is all my righteousness-<br/>Nothing but the blood of Jesus!<br/>',NULL,5283,5283);
INSERT INTO stanza VALUES('E1009','1','Would you be free from your burden of<br/>sin?<br/>There''s power in the blood, power in<br/>the blood;<br/>Would you o''er evil a victory win?<br/>There''s wonderful power in the blood.<br/>',NULL,5284,5284);
INSERT INTO stanza VALUES('E1009','chorus','There is power, power, wonder-<br/>working power,<br/>In the blood of the Lamb;<br/>There is power, power, wonder-<br/>working power,<br/>In the precious blood of the Lamb.<br/>',NULL,5285,5285);
INSERT INTO stanza VALUES('E1009','2','Would you be free from your passion and pride?<br/>There''s power in the blood, power in<br/>the blood;<br/>Come for a cleansing to Calvary''s tide,<br/>There''s wonderful power in the blood.<br/>',NULL,5286,5286);
INSERT INTO stanza VALUES('E1009','3','Would you be whiter, much whiter<br/>than snow?<br/>There''s power in the blood, power in<br/>the blood;<br/>Sin-stains are lost in its life-giving<br/>flow,<br/>There''s wonderful power in the blood.<br/>',NULL,5287,5287);
INSERT INTO stanza VALUES('E1009','4','Would you do service for Jesus your<br/>King?<br/>There''s power in the blood, power in<br/>the blood;<br/>Would you live daily His praises to<br/>sing?<br/>There''s wonderful power in the blood.<br/>',NULL,5288,5288);
INSERT INTO stanza VALUES('E1010','1','O now I see the cleansing wave!<br/>The fountain deep and wide;<br/>Jesus, my Lord, mighty to save,<br/>Points to His wounded side.<br/>',NULL,5289,5289);
INSERT INTO stanza VALUES('E1010','chorus','The cleansing stream I see, I see;<br/>I plunge, and O it cleanseth me!<br/>O praise the Lord it cleanseth me!<br/>It cleanseth me, yes, cleanseth me.<br/>',NULL,5290,5290);
INSERT INTO stanza VALUES('E1010','2','I see the dear Redeemer raised,<br/>I hear the speaking blood;<br/>It speaks! My spirit is amazed!<br/>And quickened by its flood.<br/>',NULL,5291,5291);
INSERT INTO stanza VALUES('E1010','3','I rise to walk in God''s own light<br/>Above the world and sin,<br/>With heart renewed and garments<br/>white<br/>And Christ enthroned within.<br/>',NULL,5292,5292);
INSERT INTO stanza VALUES('E1011','1','One there is above all others,<br/>Oh, how He loves!<br/>His is love beyond a brother''s,<br/>Oh, how He loves!<br/>Earthly friends may fail or leave us,<br/>One day soothe, the next day grieve us;<br/>But this Friend will ne''er deceive us:<br/>Oh, how He loves!<br/>',NULL,5293,5293);
INSERT INTO stanza VALUES('E1011','2','''Tis eternal life to know Him,<br/>Oh, how He loves!<br/>Think, oh, think how much we owe Him,<br/>Oh, how He loves!<br/>With His precious blood He bought us,<br/>In the wilderness He sought us,<br/>To His flock He safely brought us:<br/>Oh, how He loves!<br/>',NULL,5294,5294);
INSERT INTO stanza VALUES('E1011','3','Blessed Jesus! Would you know Him?<br/>Oh, how He loves!<br/>Give yourselves entirely to Him,<br/>Oh, how He loves!<br/>Think no longer of the morrow,<br/>From the past new courage borrow,<br/>Jesus carries all your sorrow:<br/>Oh, how He loves!<br/>',NULL,5295,5295);
INSERT INTO stanza VALUES('E1011','4','All your sins shall be forgiven,<br/>Oh, how He loves!<br/>Backward shall your foes be driven,<br/>Oh, how He loves!<br/>Best of blessings He''ll provide you,<br/>Nought but good shall e''er betide you,<br/>Safe to glory He will guide you:<br/>Oh, how He loves!<br/>',NULL,5296,5296);
INSERT INTO stanza VALUES('E1012','1','There is no love like the love of Jesus,<br/>Never to fade or fall,<br/>Till into the rest of the house of God<br/>He has gathered us all.<br/>',NULL,5297,5297);
INSERT INTO stanza VALUES('E1012','chorus','Jesus'' love, precious love,<br/>Boundless, and pure, and free;<br/>Oh, turn to that love, weary<br/>wand''ring soul;<br/>Jesus pleadeth for thee.<br/>',NULL,5298,5298);
INSERT INTO stanza VALUES('E1012','2','There is no heart like the heart of Jesus,<br/>Filled with a tender love;<br/>No throb nor throe that our hearts can know,<br/>But He feels it above.<br/>',NULL,5299,5299);
INSERT INTO stanza VALUES('E1012','3','There is no eye like the eye of Jesus,<br/>Piercing so far away;<br/>Ne''er out of the sight of its tender light<br/>Can the wanderer stray.<br/>',NULL,5300,5300);
INSERT INTO stanza VALUES('E1012','4','There is no voice like the voice of Jesus,<br/>Tender and sweet its chime;<br/>Like musical ring of a flowing spring<br/>In the bright summertime.<br/>',NULL,5301,5301);
INSERT INTO stanza VALUES('E1012','5','Oh, let us hark to the voice of Jesus!<br/>Then we shall never roam;<br/>And we shall rest on His loving breast,<br/>And with Him we''ll be one!<br/>',NULL,5302,5302);
INSERT INTO stanza VALUES('E1013','1','What can keep the wanderers from going<br/>all astray?<br/>Nothing but the love of Jesus!<br/>What can turn the fallen people from<br/>their sinful way?<br/>Nothing but the love of Jesus!<br/>',NULL,5303,5303);
INSERT INTO stanza VALUES('E1013','chorus','Nothing but the love of Jesus<br/>can constrain!<br/>Nothing but the love of Jesus<br/>can sustain!<br/>Nothing both in heav''n and earth can<br/>sinners gain,<br/>Nothing but the love of Jesus!<br/>',NULL,5304,5304);
INSERT INTO stanza VALUES('E1013','2','What can chase the bitterness from all<br/>the suffering ones?<br/>Nothing but the love of Jesus!<br/>What can wipe away the tears of all<br/>the weeping ones?<br/>Nothing but the love of Jesus!<br/>',NULL,5305,5305);
INSERT INTO stanza VALUES('E1013','3','What as ointment to the wound can<br/>heal the wounded hearts?<br/>Nothing but the love of Jesus!<br/>What as showers to the drought can<br/>cheer despairing hears?<br/>Nothing but the love of Jesus!<br/>',NULL,5306,5306);
INSERT INTO stanza VALUES('E1013','4','What can satisfy the human life<br/>of vanity?<br/>Nothing but the love of Jesus!<br/>What can swallow up the taste of<br/>all mortality?<br/>Nothing but the love of Jesus!<br/>',NULL,5307,5307);
INSERT INTO stanza VALUES('E1014','1','Oh, what a Savior that He died for me!<br/>From condemnation He hath made me free;<br/>"He that believeth on the Son" saith He,<br/>"Hath everlasting life."<br/>',NULL,5308,5308);
INSERT INTO stanza VALUES('E1014','chorus','"Verily, verily, I say unto you;"<br/>"Verily, verily," message ever new!<br/>"He that believeth on the Son"-''tis true!-<br/>"Hath everlasting life!"<br/>',NULL,5309,5309);
INSERT INTO stanza VALUES('E1014','2','All my iniquities on Him were laid,<br/>All my indebtedness by Him was paid;<br/>All who believe on Him, the Lord hath said,<br/>"Hath everlasting life."<br/>',NULL,5310,5310);
INSERT INTO stanza VALUES('E1014','3','Though poor and needy, I can trust my Lord;<br/>Though weak and sinful, I believe His word;<br/>Oh, glad message; every child of God<br/>"Hath everlasting life."<br/>',NULL,5311,5311);
INSERT INTO stanza VALUES('E1014','4','Though all unworthy, yet I will not doubt;<br/>For him that cometh He will not cast out:<br/>"He that believeth"-oh, the good news shout!<br/>"Hath everlasting life."<br/>',NULL,5312,5312);
INSERT INTO stanza VALUES('E1015','1','O glory, glory, what a life<br/>I have received today!<br/>All darkness, death and pow''r of sin<br/>Have now been chased away!<br/>Have now been chased away!<br/>Have now, have now been chased away!<br/>',NULL,5313,5313);
INSERT INTO stanza VALUES('E1016','1','Under the burdens of guilt and care,<br/>Many a spirit is grieving,<br/>Who in the joy of the Lord might share,<br/>Life everlasting receiving.<br/>',NULL,5314,5314);
INSERT INTO stanza VALUES('E1016','chorus','Life! Life! Eternal life!<br/>Jesus alone is the Giver:<br/>Life! Life! Abundant life!<br/>Glory to Jesus forever!<br/>',NULL,5315,5315);
INSERT INTO stanza VALUES('E1016','2','Burdened one, why will you longer bear<br/>Sorrows from which He releases?<br/>Open your heart, and rejoicing, share<br/>Life more abundant in Jesus.<br/>',NULL,5316,5316);
INSERT INTO stanza VALUES('E1016','3','Leaving the mountain, the streamlet grows,<br/>Flooding the vale with a river;<br/>So, from the hill of the Cross, there flows<br/>Life more abundant forever.<br/>',NULL,5317,5317);
INSERT INTO stanza VALUES('E1016','4','Oh, for the flood on the thirsty land!<br/>Oh, for a mighty revival!<br/>Oh, for a sanctified, fearless band,<br/>Ready to hail its arrival!<br/>',NULL,5318,5318);
INSERT INTO stanza VALUES('E1017','1','Christ has put on human nature<br/>and become a man like me,<br/>He has died upon the cross that I<br/>from Adam might be free,<br/>He has risen and as Spirit<br/>He has come to live in me<br/>That He might be my life.<br/>',NULL,5319,5319);
INSERT INTO stanza VALUES('E1017','chorus','Glory! Glory! Hallelujah!<br/>Glory! Glory! Hallelujah!<br/>Glory! Glory! Hallelujah!<br/>For Christ is now my life!<br/>',NULL,5320,5320);
INSERT INTO stanza VALUES('E1017','chorus','Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>For Christ is now my all!<br/>',NULL,5321,5321);
INSERT INTO stanza VALUES('E1018','1','The whole world was lost in the darkness of sin;<br/>The light of the world is Jesus;<br/>Like sunshine at noonday His glory shone in,<br/>The light of the world is Jesus.<br/>',NULL,5322,5322);
INSERT INTO stanza VALUES('E1018','chorus','Come to the light, ''tis shining for thee;<br/>Sweetly the light has dawned upon me;<br/>Once I was blind, but now I can see;<br/>The light of the world is Jesus.<br/>',NULL,5323,5323);
INSERT INTO stanza VALUES('E1018','2','No darkness have we who in Jesus abide,<br/>The light of the world is Jesus;<br/>We walk in the light when we follow our Guide,<br/>The light of the world is Jesus.<br/>',NULL,5324,5324);
INSERT INTO stanza VALUES('E1018','3','Ye dwellers in darkness with sin-blinded eyes,<br/>The light of the world is Jesus;<br/>Go, wash, at His bidding, and light will arise;<br/>The light of the world is Jesus.<br/>',NULL,5325,5325);
INSERT INTO stanza VALUES('E1019','1','A ruler once came to Jesus by night,<br/>To ask Him the way of salvation and light;<br/>The Master made answer in words true and plain,<br/>"Ye must be born again!"<br/>',NULL,5326,5326);
INSERT INTO stanza VALUES('E1019','chorus','"Ye must be born again!"<br/>"Ye must be born again!"<br/>"I verily, verily say unto thee,<br/>Ye must be born again!"<br/>',NULL,5327,5327);
INSERT INTO stanza VALUES('E1019','2','Ye children of men, attend to the word<br/>So solemnly uttered by Jesus, the Lord,<br/>And let not this message to you be in vain,<br/>"Ye must be born again."<br/>',NULL,5328,5328);
INSERT INTO stanza VALUES('E1019','3','Oh, ye who would enter that glorious rest,<br/>And sing with the ransomed the song<br/>of the blest;<br/>The life everlasting if ye would obtain,<br/>"Ye must be born again."<br/>',NULL,5329,5329);
INSERT INTO stanza VALUES('E1020','1','Who can set us free from sin?<br/>Only Christ! Only Christ!<br/>Who can be our life within?<br/>Only Christ!<br/>Only Christ! Only Christ!<br/>Only Christ can set us free,<br/>Only Christ!<br/>',NULL,5330,5330);
INSERT INTO stanza VALUES('E1021','1','All sinners are the slaves of sin,<br/>All poisoned by death''s sting;<br/>Christ only can from sin and death<br/>A full deliverance bring.<br/>He is the Everlasting One,<br/>Who longs to set us free;<br/>If we do not believe in Him,<br/>We''ll die in misery.<br/>',NULL,5331,5331);
INSERT INTO stanza VALUES('E1022','1','I''ve tried in vain a thousand ways<br/>My fears to quell, my hopes to raise;<br/>But what I need, the Bible says,<br/>Is ever, only Jesus.<br/>',NULL,5332,5332);
INSERT INTO stanza VALUES('E1022','2','My soul is night, my heart is steel -<br/>I cannot see, I cannot feel;<br/>For light, for life I must appeal<br/>In simple faith to Jesus.<br/>',NULL,5333,5333);
INSERT INTO stanza VALUES('E1022','3','He died, He lives, He reigns, He pleads;<br/>There''s love in all His words and deeds;<br/>There''s all a guilty sinner needs<br/>Forevermore in Jesus.<br/>',NULL,5334,5334);
INSERT INTO stanza VALUES('E1022','4','Though some should sneer, and some<br/>should blame,<br/>I''ll go with all my guilt and shame;<br/>I''ll go to Him because His name,<br/>Above all names, is Jesus.<br/>',NULL,5335,5335);
INSERT INTO stanza VALUES('E1023','1','I need Thee, precious Jesus!<br/>For I am full of sin;<br/>My soul is dark and guilty,<br/>My spirit dead within:<br/>I need the cleansing fountain,<br/>Where I can always flee:<br/>The blood of Christ most precious,<br/>The sinner''s perfect plea.<br/>',NULL,5336,5336);
INSERT INTO stanza VALUES('E1023','2','I need Thee, precious Jesus!<br/>For I am very poor;<br/>A stranger and a pilgrim,<br/>I have no earthly store:<br/>I need the love of Jesus,<br/>To cheer me on my way,<br/>To guide my doubting footsteps,<br/>To be my strength and stay.<br/>',NULL,5337,5337);
INSERT INTO stanza VALUES('E1023','3','I need Thee, precious Jesus!<br/>I need a friend like Thee;<br/>A friend to soothe and comfort,<br/>A friend to care for me:<br/>I need the heart of Jesus,<br/>To feel each anxious care,<br/>To bear my every burden,<br/>And all my sorrow share.<br/>',NULL,5338,5338);
INSERT INTO stanza VALUES('E1023','4','I need Thee, precious Jesus!<br/>I need Thee day by day,<br/>To fill me with Thy fulness,<br/>To lead me on my way;<br/>I need Thy Holy Spirit,<br/>To teach me what I am;<br/>To show me more of Jesus,<br/>To point me to the Lamb.<br/>',NULL,5339,5339);
INSERT INTO stanza VALUES('E1023','5','I need Thee, precious Jesus!<br/>And hope to see Thee soon,<br/>Encircled with Thy glory,<br/>And seated on Thy throne;<br/>There with Thy blood-bought people,<br/>My joy shall ever be<br/>To praise Thee, precious Jesus,<br/>To gaze, my Lord, on Thee.<br/>',NULL,5340,5340);
INSERT INTO stanza VALUES('E1024','1','Christ the Savior is just the One you need,<br/>He''s God incarnate, as a man indeed;<br/>In His body He suffered every pain<br/>And died to cleanse your every stain,<br/>So you need Jesus!<br/>',NULL,5341,5341);
INSERT INTO stanza VALUES('E1024','chorus','You need Jesus! You need Jesus!<br/>Men and women all need Him!<br/>For redemption you need Him!<br/>For salvation you need Him!<br/>And for everlasting life,<br/>Yes, you need Jesus!<br/>',NULL,5342,5342);
INSERT INTO stanza VALUES('E1024','2','He has risen and gone up into heav''n,<br/>That life eternal might be fully giv''n;<br/>Just receive Him, believing in your heart,<br/>Then all you need He will impart,<br/>So you need Jesus!<br/>',NULL,5343,5343);
INSERT INTO stanza VALUES('E1024','3','He''ll enlighten your darkened heart with light,<br/>Forgive your sins and rescue you with might;<br/>He will cleanse you from all stains with His blood,<br/>And give to you the life of God,<br/>So you need Jesus!<br/>',NULL,5344,5344);
INSERT INTO stanza VALUES('E1024','4','In your living there is a lack you sense,<br/>And thru the years it grows the more intense;<br/>Only Jesus this need can satisfy;<br/>All vanity He will defy,<br/>So you need Jesus!<br/>',NULL,5345,5345);
INSERT INTO stanza VALUES('E1024','chorus','You need Jesus! You need Jesus!<br/>Men and women all need Him!<br/>To escape from vanity,<br/>To obtain reality,<br/>To make life significant,<br/>Yes, you need Jesus!<br/>',NULL,5346,5346);
INSERT INTO stanza VALUES('E1024','5','All this world now is rife with toil and pain,<br/>In troubled times there''s nothing to sustain;<br/>All is empty, on what can you rely?<br/>All things reveal and testify,<br/>That you need Jesus!<br/>',NULL,5347,5347);
INSERT INTO stanza VALUES('E1025','1','Give up the world, Christ to obtain,<br/>He is your heart''s very need;<br/>What else can you desire or seek?<br/>All things are empty indeed!<br/>',NULL,5348,5348);
INSERT INTO stanza VALUES('E1025','chorus','He is so rich, He is so full,<br/>He can fulfill all your needs!<br/>He is so good, He is so sweet,<br/>All your desire He exceeds!<br/>',NULL,5349,5349);
INSERT INTO stanza VALUES('E1025','2','Give up the world, Christ to obtain,<br/>He is the One you require;<br/>Once you receive this glorious Christ,<br/>Never the rest you''ll desire.<br/>',NULL,5350,5350);
INSERT INTO stanza VALUES('E1025','3','Though very great is all the world,<br/>And very small is your heart,<br/>Yet the great world with all its wealth<br/>Never can fill your small heart.<br/>',NULL,5351,5351);
INSERT INTO stanza VALUES('E1025','4','If you have Christ, you have all joys;<br/>Without this Christ, only pains;<br/>Where there is Christ there morning is;<br/>Where He is not, night remains.<br/>',NULL,5352,5352);
INSERT INTO stanza VALUES('E1026','1','Today the Savior calls;<br/>Ye wand''rers come:<br/>O ye benighted souls!<br/>Why longer roam?<br/>',NULL,5353,5353);
INSERT INTO stanza VALUES('E1026','2','Today the Savior calls;<br/>O hear Him now!<br/>Before your day is gone,<br/>To Jesus bow.<br/>',NULL,5354,5354);
INSERT INTO stanza VALUES('E1026','3','Today the Savior calls;<br/>For refuge fly;<br/>The storm of vengeance falls,<br/>And death is nigh.<br/>',NULL,5355,5355);
INSERT INTO stanza VALUES('E1026','4','The Spirit calls today;<br/>Yield to His pow''r;<br/>O grieve Him not away,<br/>"Tis mercy''s hour!<br/>',NULL,5356,5356);
INSERT INTO stanza VALUES('E1027','1','Softly and tenderly Jesus is calling-<br/>Calling for you and for me;<br/>Patiently Jesus is waiting and watching-<br/>Watching for you and for me!<br/>',NULL,5357,5357);
INSERT INTO stanza VALUES('E1027','chorus','Come home! Come home!<br/>Ye who are weary, come home!<br/>Earnestly, tenderly, Jesus is calling,<br/>Calling, O sinner, come home!<br/>',NULL,5358,5358);
INSERT INTO stanza VALUES('E1027','2','Why should we tarry when Jesus is pleading-<br/>Pleading for you and for me?<br/>Why should we linger and heed not His mercies-<br/>Mercies for you and for me?<br/>',NULL,5359,5359);
INSERT INTO stanza VALUES('E1027','3','Time is now fleeting, the moments are passing-<br/>Passing from you and from me;<br/>Shadows are gathering, death-beds are coming-<br/>Coming for you and for me!<br/>',NULL,5360,5360);
INSERT INTO stanza VALUES('E1027','4','Oh, for the wonderful love He has promised-<br/>Promised for you and for me!<br/>Though we have sinned, He has mercy and pardon-<br/>Pardon for you and for me!<br/>',NULL,5361,5361);
INSERT INTO stanza VALUES('E1028','1','Jesus is tenderly calling thee home -<br/>Calling today, calling today!<br/>Why from the sunshine of love wilt<br/>thou roam,<br/>Farther and farther away?<br/>',NULL,5362,5362);
INSERT INTO stanza VALUES('E1028','chorus','Calling today! Calling today!<br/>Jesus is calling, is tenderly calling<br/>today!<br/>',NULL,5363,5363);
INSERT INTO stanza VALUES('E1028','2','Jesus is calling the weary to rest,<br/>Calling today! Calling today!<br/>Bring Him thy burden and thou shalt be blest:<br/>He will not turn thee away.<br/>',NULL,5364,5364);
INSERT INTO stanza VALUES('E1028','3','Jesus is waiting, O come to Him now!<br/>Waiting today! Waiting today!<br/>Come with thy sins, at His feet lowly bow;<br/>Come, and no longer delay.<br/>',NULL,5365,5365);
INSERT INTO stanza VALUES('E1028','4','Jesus is pleading, O list to His voice!<br/>Hear Him today! Hear Him today!<br/>They who believe on His name shall rejoice:<br/>Quickly arise, come away!<br/>',NULL,5366,5366);
INSERT INTO stanza VALUES('E1029','1','Christ calling yet! Shall I not hear?<br/>Earth''s pleasures shall I still hold dear?<br/>Shall life''s swift passing years all fly,<br/>And still my soul in slumber lie?<br/>',NULL,5367,5367);
INSERT INTO stanza VALUES('E1029','chorus','Calling yet, oh, hear Him!<br/>Calling yet, oh, hear Him!<br/>Christ is calling yet; oh! Hear<br/>Him calling, calling!<br/>Calling yet, oh, hear Him!<br/>Calling yet, oh, hear Him!<br/>Christ is calling yet; oh, hear<br/>Him calling yet!<br/>',NULL,5368,5368);
INSERT INTO stanza VALUES('E1029','2','Christ calling yet! Shall I not rise?<br/>Can I His loving voice despise,<br/>And basely His kind care repay?<br/>He calls me still; can I delay?<br/>',NULL,5369,5369);
INSERT INTO stanza VALUES('E1029','3','Christ calling yet! And shall He knock,<br/>And I my heart the closer lock?<br/>He still is waiting to receive;<br/>And shall I dare His Spirit grieve?<br/>',NULL,5370,5370);
INSERT INTO stanza VALUES('E1029','4','Christ calling yet! And shall I give<br/>No heed, but still in bondage live?<br/>I wait, but He does not forsake:<br/>He calls me still; my heart, awake!<br/>',NULL,5371,5371);
INSERT INTO stanza VALUES('E1029','5','Christ calling yet! I cannot stay;<br/>My heart I yield without delay;<br/>Vain world, farewell! From thee I part;<br/>The voice of Christ has reached my heart.<br/>',NULL,5372,5372);
INSERT INTO stanza VALUES('E1030','1','I hear my risen Savior say:<br/>"Follow me, follow me, follow me";<br/>His voice is calling all the day,<br/>"Follow me, follow me, follow me;<br/>For thee I trod the bitter way,<br/>For thee I gave my life away,<br/>And drank the gall thy debt to pay,<br/>Follow me, follow me, follow me."<br/>',NULL,5373,5373);
INSERT INTO stanza VALUES('E1030','2','"I know thy life of guilt and pain;<br/>Follow me, follow me, follow me!<br/>I know each ache of heart and brain;<br/>Follow me, follow me, follow me!<br/>How often I have called in vain,<br/>And offered pardon in my name,<br/>And now I plead yet once again!<br/>Follow me, follow me, follow me!"<br/>',NULL,5374,5374);
INSERT INTO stanza VALUES('E1030','3','"Though thou hast sinned I''ll pardon thee;<br/>Follow me, follow me, follow me!<br/>From every sin I''ll set thee free;<br/>Follow me, follow me, follow me!<br/>In all thy changing life I''ll be<br/>Thy God, thy guide on land and sea,<br/>Thy bliss through all eternity,<br/>Follow me, follow me, follow me!"<br/>',NULL,5375,5375);
INSERT INTO stanza VALUES('E1030','4','"Come, cast on Me thine every care;<br/>Follow me, follow me, follow me!<br/>Thy heavy load I will upbear;<br/>Follow me, follow me, follow me!<br/>Come, look to Me - dismiss thy fears;<br/>And trust Me through eternal years;<br/>My hand shall wipe away thy tears;<br/>Follow me, follow me, follow me!<br/>',NULL,5376,5376);
INSERT INTO stanza VALUES('E1030','5','Dear Lord, I yield to Thee my will;<br/>I''ll follow Thee, follow thee, follow thee!<br/>Oh, bid my struggling soul be still;<br/>I''ll follow Thee, follow Thee, follow Thee!<br/>Lord, cleanse me, with Thy Spirit fill,<br/>And keep me safe from every ill;<br/>And all Thy Word in me fulfill;<br/>I''ll follow Thee, follow Thee, follow Thee!<br/>',NULL,5377,5377);
INSERT INTO stanza VALUES('E1031','1','Come, every soul by sin oppressed,<br/>There''s mercy with the Lord;<br/>And He will surely give you rest<br/>By trusting in His Word.<br/>',NULL,5378,5378);
INSERT INTO stanza VALUES('E1031','chorus','Only trust Him! Only trust Him!<br/>Only trust Him now!<br/>He will save you! He will save you!<br/>He will save you now!<br/>',NULL,5379,5379);
INSERT INTO stanza VALUES('E1031','2','For Jesus shed His precious blood<br/>Rich blessings to bestow;<br/>Plunge now into the crimson flood<br/>That washeth white as snow.<br/>',NULL,5380,5380);
INSERT INTO stanza VALUES('E1031','3','Yes, Jesus is the Truth, the Way,<br/>That leads you into rest;<br/>Believe in Him without delay,<br/>And you are fully blest.<br/>',NULL,5381,5381);
INSERT INTO stanza VALUES('E1031','4','Come then, and join the holy band,<br/>And on to glory go;<br/>In Christ''s redemption take your stand,<br/>And all His goodness know.<br/>',NULL,5382,5382);
INSERT INTO stanza VALUES('E1032','1','Come, ye sinners, poor and wretched,<br/>Weak and wounded, sick and sore;<br/>Jesus ready waits to save you,<br/>Full of pity, love and pow''r:<br/>He is able, He is able,<br/>He is willing, doubt no more.<br/>',NULL,5383,5383);
INSERT INTO stanza VALUES('E1032','2','Come, ye needy, come and welcome;<br/>God''s free bounty glorify;<br/>True belief and true repentance,<br/>Every grace that brings us nigh,<br/>Without money, without money,<br/>Come to Jesus Christ and buy.<br/>',NULL,5384,5384);
INSERT INTO stanza VALUES('E1032','3','Let not conscience make you linger,<br/>Nor of fitness fondly dream;<br/>All the fitness He requireth<br/>Is to feel your need of Him:<br/>This He gives you, this He gives you,<br/>''Tis the Spirit''s rising beam.<br/>',NULL,5385,5385);
INSERT INTO stanza VALUES('E1032','4','Come, ye weary, heavy-laden,<br/>Lost and ruined by the fall;<br/>If you tarry till you''re better,<br/>You will never come at all:<br/>Not the righteous, not the righteous,<br/>Sinners Jesus came to call.<br/>',NULL,5386,5386);
INSERT INTO stanza VALUES('E1032','5','Agonizing in the garden,<br/>Your Redeemer prostrate lies;<br/>On the bloody tree behold Him!<br/>Hear Him cry, before He dies,<br/>"It is finished!" "It is finished!"<br/>Sinner, will not this suffice?<br/>',NULL,5387,5387);
INSERT INTO stanza VALUES('E1032','6','Lo! Th'' incarnate God, ascended,<br/>Pleads the merit of His blood;<br/>Venture on Him, venture wholly;<br/>Let no other trust intrude:<br/>None but Jesus, none but Jesus,<br/>Can do helpless sinners good.<br/>',NULL,5388,5388);
INSERT INTO stanza VALUES('E1033','1','Ye who are troubled and burdened by sin,<br/>Come just as you are;<br/>Come to the Savior, a new life begin,<br/>Oh, come just as you are.<br/>',NULL,5389,5389);
INSERT INTO stanza VALUES('E1033','chorus','Come just as you are,<br/>Oh, come just as you are;<br/>Give up your sin, let the Savior come in,<br/>And come just as you are.<br/>',NULL,5390,5390);
INSERT INTO stanza VALUES('E1033','2','Deep in your heart sin has written its scar,<br/>Come just as you are;<br/>Though from the Father you''ve wandered afar,<br/>Oh, come just as you are.<br/>',NULL,5391,5391);
INSERT INTO stanza VALUES('E1033','3','Sinful and guilty, heart broken and lost,<br/>Come just as you are;<br/>Think what your ransom on Calvary cost!<br/>Oh, come just as you are.<br/>',NULL,5392,5392);
INSERT INTO stanza VALUES('E1033','4','Naught of your goodness God''s favor can win,<br/>Come just as you are;<br/>Trust in the blood which was shed for your sin,<br/>And come just as you are.<br/>',NULL,5393,5393);
INSERT INTO stanza VALUES('E1033','5','Come with your heartache, your sorrow and pain,<br/>Come just as you are;<br/>No one has come to the Savior in vain,<br/>Oh, come just as you are.<br/>',NULL,5394,5394);
INSERT INTO stanza VALUES('E1034','1','"Whosoever heareth!" shout, shout the sound!<br/>Send the blessed tidings all the world around;<br/>Spread the joyful news wherever man is found:<br/>"Whosoever will may come!"<br/>',NULL,5395,5395);
INSERT INTO stanza VALUES('E1034','chorus','"Whosoever will! Whosoever will!"<br/>Send the proclamation over vale and hill;<br/>''Tis a loving Father calls the wand''rer home:<br/>"Whosoever will may come!"<br/>',NULL,5396,5396);
INSERT INTO stanza VALUES('E1034','2','"Whosoever cometh" need not delay,<br/>Now the door is open, enter while you may;<br/>Jesus is the true, the only Living Way:<br/>"Whosoever will may come!"<br/>',NULL,5397,5397);
INSERT INTO stanza VALUES('E1034','3','"Whosoever will! The promise is secure;<br/>"Whosoever will," forever must endure;<br/>"Whosoever will!" ''tis life forevermore;<br/>"Whosoever will may come."<br/>',NULL,5398,5398);
INSERT INTO stanza VALUES('E1035','1','There is life for a look at the Crucified One,<br/>There is life at this moment for thee;<br/>Then look, sinner, look unto Him and be saved,<br/>Unto Him who was nailed to the tree.<br/>',NULL,5399,5399);
INSERT INTO stanza VALUES('E1035','chorus','Look! Look! Look and live!<br/>There is life for a look at the<br/>Crucified One,<br/>There is life at this moment for thee.<br/>',NULL,5400,5400);
INSERT INTO stanza VALUES('E1035','2','Oh, why was He there as the Bearer of sin,<br/>If on Jesus thy guilt was not laid?<br/>Oh, why from His side flowed the sin-<br/>cleansing blood,<br/>If His dying thy debt has not paid?<br/>',NULL,5401,5401);
INSERT INTO stanza VALUES('E1035','3','It is not thy tears of repentance or prayers,<br/>But the blood, that redeemeth the soul;<br/>On Him, then, who shed it, thou mayest at once<br/>Thy weight of iniquities roll.<br/>',NULL,5402,5402);
INSERT INTO stanza VALUES('E1035','4','Then doubt not thy welcome, since<br/>God has declared<br/>There remaineth no more to be done;<br/>That once in the end of the world He appeared,<br/>And completed the work He begun.<br/>',NULL,5403,5403);
INSERT INTO stanza VALUES('E1035','5','Then take with rejoicing from Jesus at once<br/>The life everlasting He gives;<br/>And know with assurance, thou never canst die<br/>Since Jesus, thy Righteousness, lives.<br/>',NULL,5404,5404);
INSERT INTO stanza VALUES('E1036','1','Look to Jesus, weary one,<br/>Look and live! Look and live!<br/>Look at what the Lord has done,<br/>Look and live!<br/>See Him lifted on the tree,<br/>Look and live! Look and live!<br/>Hear Him say, "Look unto Me!"<br/>Look and live!<br/>',NULL,5405,5405);
INSERT INTO stanza VALUES('E1036','chorus','Look! The Lord is lifted high,<br/>Look to Him, He''s ever nigh<br/>Look and live! Why will ye die?<br/>Look and live!<br/>',NULL,5406,5406);
INSERT INTO stanza VALUES('E1036','2','Though unworthy, vile, unclean,<br/>Look and live! Look and live!<br/>Look away from self and sin,<br/>Look and live!<br/>Long by Satan''s power enslaved,<br/>Look and live! Look and live!<br/>Look to Me, ye shall be saved,<br/>Look and live!<br/>',NULL,5407,5407);
INSERT INTO stanza VALUES('E1036','3','Though you''ve wandered far away,<br/>Look and live! Look and live!<br/>Harden not your heart today,<br/>Look and live!<br/>''Tis thy Father calls thee home,<br/>Look and live! Look and live!<br/>Whosoever will may come,<br/>Look and live!<br/>',NULL,5408,5408);
INSERT INTO stanza VALUES('E1037','1','"Though your sins be as scarlet,<br/>They shall be as white as snow;<br/>Though your sins be as scarlet,<br/>They shall be as white as snow;<br/>Though they be red as crimson,<br/>They shall be as wool;"<br/>"Though your sins be as scarlet,<br/>Though your sins be as scarlet,<br/>They shall be as white as snow,<br/>They shall be as white as snow."<br/>',NULL,5409,5409);
INSERT INTO stanza VALUES('E1037','2','Hear the voice that entreats you,<br/>O return ye unto God!<br/>Hear the voice that entreats you,<br/>O return ye unto God!<br/>He is of great compassion,<br/>And of wondrous love;<br/>Hear the voice that entreats you,<br/>Hear the voice that entreats you,<br/>O return ye unto God!<br/>O return ye unto God!<br/>',NULL,5410,5410);
INSERT INTO stanza VALUES('E1037','3','He''ll forgive your transgressions,<br/>And remember them no more;<br/>He''ll forgive your transgressions,<br/>And remember them no more;<br/>"Look unto Me, ye people,"<br/>Saith the Lord your God!<br/>He''ll forgive your transgressions,<br/>He''ll forgive your transgressions,<br/>And remember them no more,<br/>And remember them no more.<br/>',NULL,5411,5411);
INSERT INTO stanza VALUES('E1038','1','If you are tired of the load of your sin,<br/>Let Jesus come into your heart;<br/>If you desire a new life to begin,<br/>Let Jesus come into your heart.<br/>',NULL,5412,5412);
INSERT INTO stanza VALUES('E1038','chorus','Just now, your doubtings give o''er;<br/>Just now, reject Him no more;<br/>Just now, throw open the door;<br/>Let Jesus come into your heart.<br/>',NULL,5413,5413);
INSERT INTO stanza VALUES('E1038','2','If ''tis for purity now that you sigh,<br/>Let Jesus come into your heart;<br/>Fountains for cleansing are flowing near by,<br/>Let Jesus come into your heart.<br/>',NULL,5414,5414);
INSERT INTO stanza VALUES('E1038','3','If there''s a tempest your voice cannot still,<br/>Let Jesus come into your heart;<br/>If there''s a void this world never can fill,<br/>Let Jesus come into your heart.<br/>',NULL,5415,5415);
INSERT INTO stanza VALUES('E1039','1','There''s a Stranger at the door,<br/>Let Him in;<br/>He has been there oft before,<br/>Let Him in;<br/>Let Him in, ere He is gone,<br/>Let Him in, the Holy One,<br/>Jesus Christ, the Father''s Son,<br/>Let Him in.<br/>',NULL,5416,5416);
INSERT INTO stanza VALUES('E1039','2','Open now to Him your heart,<br/>Let Him in;<br/>If you wait He will depart,<br/>Let Him in;<br/>Let Him in, He is your Friend,<br/>He your soul will sure defend,<br/>He will keep you to the end,<br/>Let Him in.<br/>',NULL,5417,5417);
INSERT INTO stanza VALUES('E1039','3','Hear you now His loving voice?<br/>Let Him in;<br/>Now, oh, now make Him your choice,<br/>Let Him in;<br/>He is standing at your door,<br/>Joy to you He will restore,<br/>And His name you will adore,<br/>Let Him in.<br/>',NULL,5418,5418);
INSERT INTO stanza VALUES('E1039','4','Now admit the heav''nly Guest,<br/>Let Him in;<br/>He will make for you a feast,<br/>Let Him in;<br/>He will speak your sins forgiv''n.<br/>And when earth ties all are riv''n,<br/>Comfort, rest, you will be giv''n,<br/>Let Him in.<br/>',NULL,5419,5419);
INSERT INTO stanza VALUES('E1040','1','Hark, the Savior''s knocking, knocking,<br/>Knocking at your heart!<br/>Oh, do not be hardened, hardened,<br/>Lest He should depart.<br/>Rise and open up your heart,<br/>Quickly let Him in;<br/>Life divine He''ll give you, give you,<br/>And forgive your sin.<br/>',NULL,5420,5420);
INSERT INTO stanza VALUES('E1040','chorus','Let Him in! Let Him in!<br/>He''s knocking at your heart;<br/>Let Him in! Oh, let Him in!<br/>Let Him in your heart.<br/>',NULL,5421,5421);
INSERT INTO stanza VALUES('E1040','2','Why should you still tarry, tarry,<br/>Keep Him waiting there?<br/>He is kind and gracious, gracious,<br/>Merciful and dear.<br/>Listen to His tender voice,<br/>Do not grieve His heart;<br/>Won''t you let Him enter, enter,<br/>And His grace impart.<br/>',NULL,5422,5422);
INSERT INTO stanza VALUES('E1041','1','Jesus is standing in Pilate''s hall -<br/>Friendless, forsaken, betrayed by all:<br/>Hearken! What meaneth the sudden call?<br/>What will you do with Jesus?<br/>',NULL,5423,5423);
INSERT INTO stanza VALUES('E1041','chorus','What will you do with Jesus?<br/>Neutral you cannot be;<br/>Some day your heart will be asking,<br/>"What will He do with me?"<br/>',NULL,5424,5424);
INSERT INTO stanza VALUES('E1041','2','Jesus is standing on trial still,<br/>You can be false to Him if you will,<br/>You can be faithful through good or ill:<br/>What will you do with Jesus?<br/>',NULL,5425,5425);
INSERT INTO stanza VALUES('E1041','3','Will you evade Him as Pilate tried?<br/>Or will you choose Him, whate''er betide?<br/>Vainly you struggle from Him to hide:<br/>What will you do with Jesus?<br/>',NULL,5426,5426);
INSERT INTO stanza VALUES('E1041','4','Will you, like Peter, your Lord deny?<br/>Or will you scorn from His foes to fly,<br/>Daring for Jesus to live or die?<br/>What will you do with Jesus?<br/>',NULL,5427,5427);
INSERT INTO stanza VALUES('E1041','5','"Jesus, I give Thee my heart today!<br/>Jesus, I''ll follow Thee all the way,<br/>Gladly obeying Thee!" will you say:<br/>"This will I do with Jesus!"<br/>',NULL,5428,5428);
INSERT INTO stanza VALUES('E1042','1','While we pray and while we plead,<br/>While you see your soul''s deep need,<br/>While our Father calls you home,<br/>Will you not to Jesus come?<br/>',NULL,5429,5429);
INSERT INTO stanza VALUES('E1042','chorus','Why not now? Why not now?<br/>Why not come to Jesus now?<br/>Why not now? Why not now?<br/>Why not come to Jesus now?<br/>',NULL,5430,5430);
INSERT INTO stanza VALUES('E1042','2','You have wandered far away;<br/>Do not risk another day;<br/>Do not turn from God thy face,<br/>But today accept His grace.<br/>',NULL,5431,5431);
INSERT INTO stanza VALUES('E1042','3','In the world you''ve failed to find<br/>Aught of peace for troubled mind;<br/>Come to Christ, on Him believe,<br/>Peace and Joy you shall receive.<br/>',NULL,5432,5432);
INSERT INTO stanza VALUES('E1042','4','Come to Christ, confession make;<br/>Come to Christ, and pardon take;<br/>Trust in Him from day to day,<br/>He will keep you all the way.<br/>',NULL,5433,5433);
INSERT INTO stanza VALUES('E1043','1','Life at best is very brief,<br/>Like the falling of a leaf,<br/>Like the binding of a sheaf,<br/>Be in time!<br/>Fleeting days are telling fast,<br/>That the die will soon be cast,<br/>And the fatal line be passed,<br/>Be in time!<br/>',NULL,5434,5434);
INSERT INTO stanza VALUES('E1043','chorus','Be in time! Be in time!<br/>While the voice of Jesus calls you,<br/>Be in time!<br/>If in sin you longer wait,<br/>You may find no open gate,<br/>And your cry be just too late:<br/>Be in time!<br/>',NULL,5435,5435);
INSERT INTO stanza VALUES('E1043','2','Fairest flowers soon decay,<br/>Youth and beauty pass away;<br/>O you have not long to stay,<br/>Be in time!<br/>While God''s Spirit bids you come,<br/>Sinner, do not longer roam,<br/>Lest you seal your hopeless doom,<br/>Be in time!<br/>',NULL,5436,5436);
INSERT INTO stanza VALUES('E1043','3','Time is gliding swiftly by,<br/>Death and judgment draweth nigh,<br/>To the arms of Jesus fly,<br/>Be in time!<br/>O I pray you count the cost!<br/>Ere the fatal line be crossed,<br/>And your soul in hell be lost,<br/>Be in time!<br/>',NULL,5437,5437);
INSERT INTO stanza VALUES('E1043','4','Sinner, heed the warning voice,<br/>Make the Lord your final choice,<br/>Then all heaven will rejoice,<br/>Be in time!<br/>Come from darkness into light;<br/>Come, let Jesus make you right;<br/>Come, receive His life tonight,<br/>Be in time!<br/>',NULL,5438,5438);
INSERT INTO stanza VALUES('E1044','1','Are you ready God to meet?<br/>Are you ready God to meet?<br/>Are you ready God to meet?<br/>Ready God to meet?<br/>Are you ready, are you ready,<br/>Ready God to meet?<br/>',NULL,5439,5439);
INSERT INTO stanza VALUES('E1045','1','O do not let the Word depart,<br/>And close thine eyes against the light:<br/>Poor sinner, harden not your heart,<br/>Be saved, O tonight.<br/>',NULL,5440,5440);
INSERT INTO stanza VALUES('E1045','chorus','O why not tonight?<br/>O why not tonight?<br/>Wilt thou be saved?<br/>Then why not tonight?<br/>',NULL,5441,5441);
INSERT INTO stanza VALUES('E1045','2','Tomorrow''s sun may never rise<br/>To bless thy long-deluded sight;<br/>This is the time, O then be wise,<br/>Be saved, O tonight.<br/>',NULL,5442,5442);
INSERT INTO stanza VALUES('E1045','3','Our Lord in pity lingers still,<br/>And wilt thou thus His love requite?<br/>Renounce at once thy stubborn will,<br/>Be saved, O tonight.<br/>',NULL,5443,5443);
INSERT INTO stanza VALUES('E1045','4','Our blessed Lord refuses none<br/>Who would to Him their souls unite;<br/>Believe on Him, the work is done.<br/>Be saved, O tonight.<br/>',NULL,5444,5444);
INSERT INTO stanza VALUES('E1046','1','"Almost persuaded" now to believe;<br/>"Almost persuaded" Christ to receive;<br/>Seems now some soul to say,<br/>"Go, Spirit, go Thy way,<br/>Some more convenient day<br/>On Thee I''ll call."<br/>',NULL,5445,5445);
INSERT INTO stanza VALUES('E1046','2','"Almost persuaded" come, come today;<br/>"Almost persuaded", turn not away;<br/>Jesus invites you here,<br/>Angels are ling''ring near,<br/>Prayers rise from hearts so dear;<br/>O wand''rer come!<br/>',NULL,5446,5446);
INSERT INTO stanza VALUES('E1046','3','Oh, be persuaded! Christ never fails -<br/>Oh, be persuaded! His blood avails -<br/>Can save from every sin,<br/>Cleanse you without, within -<br/>Will you not let Him in?<br/>',NULL,5447,5447);
INSERT INTO stanza VALUES('E1046','4','"Almost persuaded," harvest is past!<br/>"Almost persuaded," His blood avails -<br/>"Almost" cannot avail;<br/>"Almost" is but to fail!<br/>Sad, sad that bitter wail -<br/>"Almost - but lost!"<br/>',NULL,5448,5448);
INSERT INTO stanza VALUES('E1046','5','Be now persuaded, oh, sinner, hear!<br/>Be now persuaded, Jesus is near;<br/>His voice is pleading still,<br/>Turn now with heart and will,<br/>Peace will your spirit fill -<br/>Oh, turn today!<br/>',NULL,5449,5449);
INSERT INTO stanza VALUES('E1047','1','Eternity! Eternity!<br/>How will you spend Eternity?<br/>This question comes to you and me!<br/>How will you spend Eternity?<br/>Tell me, what shall your answer be -<br/>How will you spend Eternity?<br/>',NULL,5450,5450);
INSERT INTO stanza VALUES('E1047','2','Eternity! Eternity!<br/>How will you spend Eternity?<br/>Many are choosing Christ today,<br/>Turning from all their sins away;<br/>Christ shall their blessed portion be:<br/>How will you spend Eternity?<br/>',NULL,5451,5451);
INSERT INTO stanza VALUES('E1047','3','Eternity! Eternity!<br/>How will you spend Eternity?<br/>Turn, and believe this very hour,<br/>Trust in the Savior''s grace and power:<br/>Then shall you joyous answer be,<br/>Saved through a long Eternity!<br/>',NULL,5452,5452);
INSERT INTO stanza VALUES('E1048','1','Just as I am, without one plea,<br/>But that Thy blood was shed for me,<br/>And that Thou bid''st me come to Thee,<br/>O Lamb of God, I come! I come!<br/>',NULL,5453,5453);
INSERT INTO stanza VALUES('E1048','2','Just as I am, and waiting not<br/>To rid my soul of one dark blot;<br/>To Thee whose blood can cleanse each spot,<br/>O Lamb of God, I come, I come!<br/>',NULL,5454,5454);
INSERT INTO stanza VALUES('E1048','3','Just as I am, though tossed about<br/>With many a conflict, many a doubt;<br/>Fightings within, and fears without,<br/>O Lamb of God, I come, I come!<br/>',NULL,5455,5455);
INSERT INTO stanza VALUES('E1048','4','Just as I am, poor, wretched, blind;<br/>Sight, riches, healing of the mind;<br/>Yes, all I need, in Thee to find,<br/>O Lamb of God, I come, I come!<br/>',NULL,5456,5456);
INSERT INTO stanza VALUES('E1048','5','Just as I am, Thou wilt receive,<br/>Wilt welcome, pardon, cleanse, relieve;<br/>Because Thy promise I believe,<br/>O Lamb of God, I come, I come!<br/>',NULL,5457,5457);
INSERT INTO stanza VALUES('E1048','6','Just as I am, Thy love unknown<br/>Has broken every barrier down;<br/>Now, to be Thine, yea, Thine alone,<br/>O Lamb of God, I come, I come!<br/>',NULL,5458,5458);
INSERT INTO stanza VALUES('E1049','1','Drawn to the Cross which Thou hast blest,<br/>With healing gifts for souls distrest,<br/>To find in Thee my Life, my Rest,<br/>Christ crucified, I come.<br/>',NULL,5459,5459);
INSERT INTO stanza VALUES('E1049','2','Stained with the sins which I have wrought<br/>In word and deed and secret thought;<br/>For pardon which Thy Blood hath bought,<br/>Christ crucified, I come.<br/>',NULL,5460,5460);
INSERT INTO stanza VALUES('E1049','3','Weary of selfishness and pride,<br/>False pleasures gone, vain hopes denied,<br/>Deep in Thy wounds my shame to hide,<br/>Christ crucified, I come.<br/>',NULL,5461,5461);
INSERT INTO stanza VALUES('E1049','4','Thou knowest all my griefs and fears,<br/>Thy grace abused, my misspent years;<br/>Yet now to Thee, for cleansing tears,<br/>Christ crucified, I come.<br/>',NULL,5462,5462);
INSERT INTO stanza VALUES('E1049','5','I would not, if I could, conceal<br/>The ills which only Thou canst heal;<br/>So to the Cross, where sinners kneel,<br/>Christ crucified, I come<br/>',NULL,5463,5463);
INSERT INTO stanza VALUES('E1049','6','Wash me, and take away each stain,<br/>Let nothing of my sin remain;<br/>For cleansing, though it be through pain,<br/>Christ crucified, I come<br/>',NULL,5464,5464);
INSERT INTO stanza VALUES('E1049','7','To share with Thee Thy life divine,<br/>Thy very likeness to be mine,<br/>Since Thou hast made my nature Thine,<br/>Christ crucified, I come<br/>',NULL,5465,5465);
INSERT INTO stanza VALUES('E1049','8','To be what Thou wouldst have me be,<br/>Accepted, sanctified in Thee,<br/>Through what Thy grace shall work in me,<br/>Christ crucified, I come<br/>',NULL,5466,5466);
INSERT INTO stanza VALUES('E1050','1','Out of my bondage, sorrow, and night,<br/>Jesus, I come! Jesus, I come!<br/>Into Thy freedom, gladness, and light,<br/>Jesus, I come to Thee!<br/>Out of my sickness into Thy health,<br/>Out of my want and into Thy wealth,<br/>Out of my sin and into Thyself,<br/>Jesus, I come to Thee!<br/>',NULL,5467,5467);
INSERT INTO stanza VALUES('E1050','2','Out of my shameful failure and loss,<br/>Jesus, I come! Jesus, I come!<br/>Into the glorious gain of Thy cross,<br/>Jesus, I come to Thee!<br/>Out of earth''s sorrows into Thy balm,<br/>Out of life''s storm and into Thy calm,<br/>Out of distress to jubilant psalm,<br/>Jesus, I come to Thee!<br/>',NULL,5468,5468);
INSERT INTO stanza VALUES('E1050','3','Out of unrest and arrogant pride,<br/>Jesus, I come! Jesus, I come!<br/>Into Thy blessed will to abide,<br/>Jesus I come to Thee!<br/>Out of myself to dwell in Thy love,<br/>Out of despair into raptures above,<br/>Upward for aye on wings like a dove,<br/>Jesus, I come to Thee!<br/>',NULL,5469,5469);
INSERT INTO stanza VALUES('E1050','4','Out of the fear and dread of the tomb,<br/>Jesus, I come! Jesus, I come!<br/>Into the joy and pleasure, Thine own,<br/>Jesus, I come to Thee!<br/>Out of the depths of ruin untold,<br/>Into the flock Thy love doth enfold,<br/>Ever Thy glorious face to behold,<br/>Jesus, I come to Thee!<br/>',NULL,5470,5470);
INSERT INTO stanza VALUES('E1051','1','I hear Thy welcome voice,<br/>That calls me, Lord, to Thee,<br/>For cleansing in Thy precious blood<br/>That flowed on Calvary.<br/>',NULL,5471,5471);
INSERT INTO stanza VALUES('E1051','chorus','I am coming, Lord,<br/>Coming now to Thee:<br/>Wash me, cleanse me in the blood<br/>That flowed on Calvary.<br/>',NULL,5472,5472);
INSERT INTO stanza VALUES('E1051','2','Though coming weak and vile,<br/>Thou dost my strength assure;<br/>Thou dost my vileness fully cleanse,<br/>Till spotless all, and pure.<br/>',NULL,5473,5473);
INSERT INTO stanza VALUES('E1051','3','''Tis Jesus who confirms<br/>The blessed work within,<br/>By adding grace to welcomed grace,<br/>Where reigned the power of sin.<br/>',NULL,5474,5474);
INSERT INTO stanza VALUES('E1051','4','And He the witness gives<br/>To loyal hearts and free,<br/>That every promise is fulfilled,<br/>If faith but brings the plea.<br/>',NULL,5475,5475);
INSERT INTO stanza VALUES('E1051','5','All hail, redeeming blood!<br/>All hail, life-giving grace!<br/>All hail, the gift of Christ our Lord,<br/>Our strength and righteousness.<br/>',NULL,5476,5476);
INSERT INTO stanza VALUES('E1052','1','I''ve wandered far away from God,<br/>Now I''m coming home;<br/>The paths of sin too long I''ve trod,<br/>Lord, I''m coming home.<br/>',NULL,5477,5477);
INSERT INTO stanza VALUES('E1052','chorus','Coming home, coming home,<br/>Nevermore to roam;<br/>Open wide Thine arms of love;<br/>Lord, I''m coming home.<br/>',NULL,5478,5478);
INSERT INTO stanza VALUES('E1052','2','I''ve wasted many precious years,<br/>Now I''m coming home;<br/>I now repent with bitter tears,<br/>Lord, I''m coming home.<br/>',NULL,5479,5479);
INSERT INTO stanza VALUES('E1052','3','I''m tired of sin and straying, Lord,<br/>Now I''m coming home;<br/>I''ll trust Thy love, believe Thy word;<br/>Lord, I''m coming home.<br/>',NULL,5480,5480);
INSERT INTO stanza VALUES('E1052','4','My soul is sick, my heart is sore,<br/>Now I''m coming home;<br/>My strength renew, my hope restore:<br/>Lord, I''m coming home.<br/>',NULL,5481,5481);
INSERT INTO stanza VALUES('E1052','5','My only hope, my only plea,<br/>Now I''m coming home;<br/>That Jesus died, and died for me;<br/>Lord, I''m coming home.<br/>',NULL,5482,5482);
INSERT INTO stanza VALUES('E1052','6','I need His cleansing blood, I know,<br/>Now I''m coming home;<br/>O wash me whiter than the snow;<br/>Lord, I''m coming home.<br/>',NULL,5483,5483);
INSERT INTO stanza VALUES('E1053','1','With broken heart and contrite sigh,<br/>A trembling sinner, Lord, I cry;<br/>Thy pard''ning grace is rich and free:<br/>O God, be merciful to me!<br/>',NULL,5484,5484);
INSERT INTO stanza VALUES('E1053','2','I smite upon my troubled breast,<br/>With deep and conscious guilt<br/>oppressed;<br/>Christ and His cross my only plea:<br/>O God, be merciful to me!<br/>',NULL,5485,5485);
INSERT INTO stanza VALUES('E1053','3','Far off I stand with tearful eyes,<br/>Nor dare uplift them to the skies;<br/>But Thou dost all my anguish see,<br/>O God, be merciful to me!<br/>',NULL,5486,5486);
INSERT INTO stanza VALUES('E1053','4','With alms, or deeds that I have done,<br/>Not one sin''s pardon can be won;<br/>To Calvary alone I flee;<br/>O God, be merciful to me!<br/>',NULL,5487,5487);
INSERT INTO stanza VALUES('E1053','5','And when redeemed from sin and hell,<br/>With all the ransomed throng I dwell,<br/>My raptured song shall ever be,<br/>God has been merciful to me!<br/>',NULL,5488,5488);
INSERT INTO stanza VALUES('E1054','1','Pass me not, O gently Savior,<br/>Hear my humble cry;<br/>While on others Thou art calling,<br/>Do not pass me by.<br/>',NULL,5489,5489);
INSERT INTO stanza VALUES('E1054','chorus','Savior, Savior,<br/>Hear my humble cry;<br/>While on others Thou art calling,<br/>Do not pass me by.<br/>',NULL,5490,5490);
INSERT INTO stanza VALUES('E1054','2','Let me at Thy throne of mercy<br/>Find a sweet relief;<br/>Kneeling there in deep contrition,<br/>Help my unbelief.<br/>',NULL,5491,5491);
INSERT INTO stanza VALUES('E1054','3','Trusting only in Thy merit,<br/>Would I seek Thy face;<br/>Heal my wounded, broken spirit,<br/>Save me by Thy grace.<br/>',NULL,5492,5492);
INSERT INTO stanza VALUES('E1054','4','Thou the spring of all my comfort,<br/>More than life to me;<br/>Whom have I on earth beside Thee?<br/>Whom in heaven but Thee?<br/>',NULL,5493,5493);
INSERT INTO stanza VALUES('E1055','1','I am sinful, I am helpless,<br/>Humbly at Thy feet I bow;<br/>Full of problems, I am hopeless,<br/>Oh, dear Savior, save me now!<br/>Save me now! Save me now!<br/>Oh, dear Savior, save me now!<br/>Save me now from all my problems,<br/>Oh, dear Savior, save me now!<br/>',NULL,5494,5494);
INSERT INTO stanza VALUES('E1056','1','Jesus, my Lord, to Thee I cry;<br/>Unless Thou save me, I must die:<br/>Oh, bring Thy free salvation nigh,<br/>And take me as I am!<br/>',NULL,5495,5495);
INSERT INTO stanza VALUES('E1056','chorus','And take me as I am!<br/>And take me as I am!<br/>My only plea-Christ died for me!<br/>Oh, take me as I am!<br/>',NULL,5496,5496);
INSERT INTO stanza VALUES('E1056','2','Helpless I am, and full of guilt;<br/>But yet for me Thy blood was spilt,<br/>And Thou canst make me what Thou wilt,<br/>And take me as I am.<br/>',NULL,5497,5497);
INSERT INTO stanza VALUES('E1056','3','No preparation can I make,<br/>My best resolves I only break,<br/>Yet save me for Thine own Name''s sake,<br/>And take me as I am.<br/>',NULL,5498,5498);
INSERT INTO stanza VALUES('E1056','4','Behold me, Savior, at Thy feet,<br/>Deal with me as Thou seest meet;<br/>Thy work begin, Thy work complete,<br/>But take me as I am.<br/>',NULL,5499,5499);
INSERT INTO stanza VALUES('E1057','1','Jesus, lover of my soul,<br/>Let me to Thy bosom fly,<br/>While the nearer waters roll,<br/>While the tempest still is high:<br/>Hide me, O my Savior, hide,<br/>Till the storm of life is past;<br/>Safe into the haven guide;<br/>O receive my soul at last.<br/>',NULL,5500,5500);
INSERT INTO stanza VALUES('E1057','2','Other refuge have I none,<br/>Hangs my helpless soul on Thee;<br/>Leave, oh, leave me not alone,<br/>Still support and comfort me.<br/>All my trust on Thee is stayed,<br/>All my help from Thee I bring;<br/>Cover my defenseless head<br/>With the shadow of Thy wing.<br/>',NULL,5501,5501);
INSERT INTO stanza VALUES('E1057','3','Thou, O Christ, art all I want;<br/>More than all in Thee I find;<br/>Raise the fallen, cheer the faint,<br/>Heal the sick and lead the blind.<br/>Just and holy is Thy name,<br/>I am all unrighteousness;<br/>Vile and full of sin I am,<br/>Thou art full of truth and grace.<br/>',NULL,5502,5502);
INSERT INTO stanza VALUES('E1057','4','Plenteous grace with Thee is found,<br/>Grace to cover all my sin;<br/>Let the healing streams abound;<br/>Make and keep me pure within.<br/>Thou of life the fountain art,<br/>Freely let me take of Thee;<br/>Spring Thou up within my heart,<br/>Rise to all eternity.<br/>',NULL,5503,5503);
INSERT INTO stanza VALUES('E1058','1','Rock of Ages, cleft for me,<br/>Let me hide myself in Thee;<br/>Let the water and the blood,<br/>From Thy riven side which flowed,<br/>Be of sin the double cure,<br/>Save me from its guilt and power.<br/>',NULL,5504,5504);
INSERT INTO stanza VALUES('E1058','2','Not the labor of my hands<br/>Can fulfill Thy law''s demands;<br/>Could my zeal no respite know,<br/>Could my tears forever flow,<br/>All could never sin erase,<br/>Thou must save, and save by grace.<br/>',NULL,5505,5505);
INSERT INTO stanza VALUES('E1058','3','Nothing in my hands I bring,<br/>Simply to Thy cross I cling;<br/>Naked, come to Thee for dress,<br/>Helpless, look to Thee for grace:<br/>Foul, I to the fountain fly,<br/>Wash me, Savior, or I die.<br/>',NULL,5506,5506);
INSERT INTO stanza VALUES('E1058','4','While I draw this fleeting breath,<br/>When mine eyes shall close in death,<br/>When I soar to worlds unknown,<br/>See Thee on Thy judgment throne,<br/>Rock of Ages, cleft for me,<br/>Let me hide myself in Thee.<br/>',NULL,5507,5507);
INSERT INTO stanza VALUES('E1059','1','Jesus, keep me near the cross,<br/>There a precious fountain,<br/>Free to all-a healing stream,<br/>Flows from Calv''ry mountain.<br/>',NULL,5508,5508);
INSERT INTO stanza VALUES('E1059','chorus','In the cross, in the cross,<br/>Be my glory ever;<br/>From the cross my ransomed soul<br/>Nothing then shall sever.<br/>',NULL,5509,5509);
INSERT INTO stanza VALUES('E1059','2','Near the cross, a trembling soul,<br/>Love and mercy found me;<br/>There the Bright and Morning Star<br/>Sheds its beams around me.<br/>',NULL,5510,5510);
INSERT INTO stanza VALUES('E1059','3','Near the cross! O Lamb of God,<br/>Bring its scenes before me;<br/>Help me walk from day to day,<br/>With its shadows o''er me.<br/>',NULL,5511,5511);
INSERT INTO stanza VALUES('E1059','4','Near the cross I''ll watch and wait,<br/>Hoping, trusting ever,<br/>Till I see my Savior''s face,<br/>Leave His presence never.<br/>',NULL,5512,5512);
INSERT INTO stanza VALUES('E1060','1','Thou didst leave Thy throne and Thy kingly crown,<br/>When Thou camest to earth for me;<br/>But in Bethlehem''s home was there found no room<br/>For Thy holy nativity:<br/>',NULL,5513,5513);
INSERT INTO stanza VALUES('E1060','chorus','Oh, come to my heart, Lord Jesus!<br/>There is room in my heart for Thee;<br/>Oh, come to my heart, Lord Jesus, come,<br/>There is room in my heart for Thee.<br/>',NULL,5514,5514);
INSERT INTO stanza VALUES('E1060','2','Heaven''s arches rang when the angels sang,<br/>Proclaiming Thy royal degree;<br/>But of lowly birth cam''st Thou, Lord, on earth,<br/>And in great humility:<br/>',NULL,5515,5515);
INSERT INTO stanza VALUES('E1060','3','The foxes found rest, and the birds had their nest<br/>In the shade of the forest tree;<br/>But Thy couch was the sod, O Thou Son of God,<br/>In the deserts of Galilee:<br/>',NULL,5516,5516);
INSERT INTO stanza VALUES('E1060','4','Thou camest, O Lord, with the living Word<br/>That should set Thy people free;<br/>But with mocking scorn, and with crown of thorn,<br/>They bore Thee to Calvary:<br/>',NULL,5517,5517);
INSERT INTO stanza VALUES('E1060','chorus','Oh, come to my heart, Lord Jesus!<br/>Thy cross is my only plea;<br/>Oh, come to my heart, Lord Jesus, come,<br/>Thy cross is my only plea.<br/>',NULL,5518,5518);
INSERT INTO stanza VALUES('E1060','5','When heaven''s arches shall ring, and<br/>her choirs shall sing<br/>At Thy coming to victory,<br/>Let Thy voice call me up, saying, "Yet<br/>there is room,<br/>There is room at My side for thee!"<br/>',NULL,5519,5519);
INSERT INTO stanza VALUES('E1060','chorus','And my heart shall rejoice, Lord Jesus!<br/>When Thou comest and callest for me;<br/>And my heart shall rejoice, Lord Jesus!<br/>When Thou comest and callest for me.<br/>',NULL,5520,5520);
INSERT INTO stanza VALUES('E1061','1','Come into my heart, O Lord Jesus,<br/>Come into my heart, I pray;<br/>My soul is so troubled and weary,<br/>Come into my heart, today.<br/>',NULL,5521,5521);
INSERT INTO stanza VALUES('E1061','chorus','Into my heart, into my heart,<br/>Come into my heart, Lord Jesus;<br/>Come in today, come in to stay,<br/>Come into my heart, Lord Jesus.<br/>',NULL,5522,5522);
INSERT INTO stanza VALUES('E1061','2','Come into my heart, O Lord Jesus,<br/>I need Thee through life''s dreary way;<br/>The burden of sin is so heavy,<br/>Come into my heart to stay.<br/>',NULL,5523,5523);
INSERT INTO stanza VALUES('E1061','3','Come into my heart, O Lord Jesus,<br/>Now cleanse and illumine my soul;<br/>Fill me with Thy wonderful Spirit,<br/>Come in and take full control.<br/>',NULL,5524,5524);
INSERT INTO stanza VALUES('E1062','1','I am coming to the cross;<br/>I am poor, and weak, and blind;<br/>I am counting all but dross;<br/>I shall full salvation find.<br/>',NULL,5525,5525);
INSERT INTO stanza VALUES('E1062','chorus','I am trusting, Lord, in Thee,<br/>Blessed Lamb of Calvary;<br/>Humbly at Thy cross I bow,<br/>Save me, Jesus, save me now.<br/>',NULL,5526,5526);
INSERT INTO stanza VALUES('E1062','2','Long my heart has sighed for Thee;<br/>Long has evil dwelt within;<br/>Jesus sweetly speaks to me,<br/>"I will cleanse you from all sin."<br/>',NULL,5527,5527);
INSERT INTO stanza VALUES('E1062','3','Here I give my all to Thee-<br/>Friends and time and earthly store,<br/>Soul and body Thine to be-<br/>Wholly Thine forevermore.<br/>',NULL,5528,5528);
INSERT INTO stanza VALUES('E1062','4','In the promises I trust;<br/>Now I feel the blood applied;<br/>I am prostrate in the dust;<br/>I with Christ am crucified.<br/>',NULL,5529,5529);
INSERT INTO stanza VALUES('E1063','1','Jesus, I will trust Thee,<br/>Trust Thee with my soul,<br/>Guilty, lost and helpless,<br/>Thou canst make me whole:<br/>There is none in heaven<br/>Or on earth like Thee:<br/>Thou hast died for sinners,<br/>Therefore, Lord, for me.<br/>',NULL,5530,5530);
INSERT INTO stanza VALUES('E1063','chorus','Jesus, I will trust Thee,<br/>Trust Thee with my soul,<br/>Guilty, lost and helpless,<br/>Thou canst make me whole.<br/>',NULL,5531,5531);
INSERT INTO stanza VALUES('E1063','2','Jesus, I must trust Thee,<br/>Pondering Thy ways;<br/>Full of love and mercy<br/>All Thine earthly days:<br/>Sinners, gathered round Thee,<br/>Lepers sought Thy face:<br/>None too vile or loathsome<br/>For a Savior''s grace.<br/>',NULL,5532,5532);
INSERT INTO stanza VALUES('E1063','3','Jesus, I can trust Thee,<br/>Trust Thy written Word,<br/>Though Thy voice of pity<br/>I have never heard:<br/>When Thy Spirit teacheth,<br/>To my taste how sweet!<br/>Only may I hearken,<br/>Sitting at Thy feet.<br/>',NULL,5533,5533);
INSERT INTO stanza VALUES('E1063','4','Jesus, I do trust Thee,<br/>Trust without a doubt;<br/>Whosever cometh<br/>Thou wilt not cast out:<br/>Faithful is Thy promise,<br/>Precious is Thy blood:<br/>These my soul''s salvation,<br/>Thou my Savior God!<br/>',NULL,5534,5534);
INSERT INTO stanza VALUES('E1064','1','I love to tell the story<br/>Of unseen things above,<br/>Of Jesus and His glory,<br/>Of Jesus and His love.<br/>I love to tell the story,<br/>Because I know ''tis true;<br/>It satisfies my longings<br/>As nothing else can do.<br/>',NULL,5535,5535);
INSERT INTO stanza VALUES('E1064','chorus','I love to tell the story<br/>''Twill be my theme in glory<br/>To tell the old, old story<br/>Of Jesus and His love.<br/>',NULL,5536,5536);
INSERT INTO stanza VALUES('E1064','2','I love to tell the story;<br/>More wonderful it seems<br/>Than all the golden fancies<br/>Of all my golden dreams,<br/>I love to tell the story,<br/>It did so much for me;<br/>And that is just the reason<br/>I tell it now to thee.<br/>',NULL,5537,5537);
INSERT INTO stanza VALUES('E1064','3','I love to tell the story;<br/>''Tis pleasant to repeat<br/>What seems each time I tell it,<br/>More wonderfully sweet.<br/>I love to tell the story;<br/>For some have never heard<br/>The message of salvation<br/>From God''s own holy Word.<br/>',NULL,5538,5538);
INSERT INTO stanza VALUES('E1064','4','I love to tell the story;<br/>For those who know it best<br/>Seem hungering and thirsting<br/>To hear it like the rest.<br/>And when, in scenes of glory,<br/>I sing the new, new song,<br/>''Twill be the old, old story,<br/>That I have loved so long.<br/>',NULL,5539,5539);
INSERT INTO stanza VALUES('E1065','1','O how great His salvation!<br/>O how great His salvation!<br/>O how great His salvation!<br/>Jesus saves me now!<br/>',NULL,5540,5540);
INSERT INTO stanza VALUES('E1065','chorus','Jesus breaks every fetter!<br/>Jesus breaks every fetter!<br/>Jesus breaks every fetter!<br/>Jesus sets me free!<br/>',NULL,5541,5541);
INSERT INTO stanza VALUES('E1065','2','All my sins are forgiven!<br/>All my fetters are riven!<br/>I enjoy peace of heaven!<br/>Jesus saves me now!<br/>',NULL,5542,5542);
INSERT INTO stanza VALUES('E1065','3','Neither sin nor temptation,<br/>Neither Satan''s vexation,<br/>Nor the world''s best elation<br/>Can enslave me now!<br/>',NULL,5543,5543);
INSERT INTO stanza VALUES('E1065','4','I will sing Hallelujah!<br/>I will sing Hallelujah!<br/>I will sing Hallelujah!<br/>Jesus saves me now!<br/>',NULL,5544,5544);
INSERT INTO stanza VALUES('E1066','1','Down at the cross where my Savior died,<br/>Down where for cleansing from sin I cried,<br/>There to my sin was the blood applied;<br/>Glory to His name!<br/>',NULL,5545,5545);
INSERT INTO stanza VALUES('E1066','chorus','Glory to His name,<br/>Glory to His name;<br/>There to my sin was the blood applied;<br/>Glory to His name!<br/>',NULL,5546,5546);
INSERT INTO stanza VALUES('E1066','2','I am so wondrously saved from sin,<br/>Jesus so sweetly abides within;<br/>There at the cross where He took me in;<br/>Glory to His name.<br/>',NULL,5547,5547);
INSERT INTO stanza VALUES('E1066','3','Oh, precious fountain that saves from sin,<br/>I am so glad I have entered in;<br/>There Jesus saves me and keeps me clean;<br/>Glory to His name.<br/>',NULL,5548,5548);
INSERT INTO stanza VALUES('E1066','4','Come to this fountain so rich and sweet;<br/>Cast thy poor soul at the Savior''s feet;<br/>Plunge in today, and be made complete;<br/>Glory to His name.<br/>',NULL,5549,5549);
INSERT INTO stanza VALUES('E1067','1','There was One who was willing to die<br/>in my stead,<br/>That a soul so unworthy might live,<br/>And the path to the cross He was<br/>willing to tread,<br/>All the sins of my life to forgive.<br/>',NULL,5550,5550);
INSERT INTO stanza VALUES('E1067','chorus','They were borne on the cross,<br/>They were borne on the cross,<br/>O how much He was willing to bear!<br/>With what anguish and loss,<br/>Jesus went to the cross!<br/>But He carried my sins with Him there.<br/>',NULL,5551,5551);
INSERT INTO stanza VALUES('E1067','2','He is tender and loving and patient<br/>with me,<br/>While He cleanses my heart of its dross;<br/>But "there''s no condemnation," I know<br/>I am free,<br/>For my sins were all borne on the cross.<br/>',NULL,5552,5552);
INSERT INTO stanza VALUES('E1067','3','I will cling to my Savior and never depart-<br/>I will joyfully journey each day,<br/>With a song on my lips and a song in my heart,<br/>That my sins have been taken away.<br/>',NULL,5553,5553);
INSERT INTO stanza VALUES('E1068','1','In tenderness He sought me,<br/>Weary and sick with sin,<br/>And on His shoulders brought me<br/>Into His flock again,<br/>While angels in His presence sang<br/>Until the courts of heaven rang.<br/>',NULL,5554,5554);
INSERT INTO stanza VALUES('E1068','chorus','Oh, the love that sought me!<br/>Oh, the blood that bought me!<br/>Oh, the grace that brought me to the flock,<br/>Wondrous grace that brought me to the flock!<br/>',NULL,5555,5555);
INSERT INTO stanza VALUES('E1068','2','He washed the bleeding sin-wounds,<br/>And poured in oil and wine;<br/>He whispered to assure me,<br/>"I''ve found thee, thou art Mine:"<br/>I never heard a sweeter voice,<br/>It made my aching heart rejoice.<br/>',NULL,5556,5556);
INSERT INTO stanza VALUES('E1068','3','He pointed to the nail-prints,<br/>For me His blood was shed;<br/>A mocking crown so thorny,<br/>Was placed upon His head:<br/>I wondered what He saw in me,<br/>To suffer such deep agony.<br/>',NULL,5557,5557);
INSERT INTO stanza VALUES('E1068','4','I''m sitting in His presence,<br/>The sunshine of His face,<br/>While with adoring wonder<br/>His blessings I retrace.<br/>It seems as if eternal days<br/>Are far too short to sound His praise.<br/>',NULL,5558,5558);
INSERT INTO stanza VALUES('E1068','5','So while the hours are passing,<br/>All now is perfect rest;<br/>I''m waiting for the morning,<br/>The brightest and the best,<br/>When He will call us to His side,<br/>To be with Him, His spotless Bride.<br/>',NULL,5559,5559);
INSERT INTO stanza VALUES('E1069','1','We''re feeding on the living Bread,<br/>We''re drinking at the fountainhead;<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again.<br/>',NULL,5560,5560);
INSERT INTO stanza VALUES('E1069','2','What! Never thirst again?<br/>No, never thirst again!<br/>What! Never thirst again?<br/>No, never thirst again!<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again!<br/>',NULL,5561,5561);
INSERT INTO stanza VALUES('E1070','1','I was sinking deep in sin,<br/>Far from the peaceful shore,<br/>Very deeply stained within,<br/>Sinking to rise no more;<br/>But the Master of the sea<br/>Heard my despairing cry,<br/>From the waters lifted me,<br/>Now safe am I.<br/>',NULL,5562,5562);
INSERT INTO stanza VALUES('E1070','chorus','Love lifted me!<br/>Love lifted me!<br/>When nothing else could help,<br/>Love lifted me.<br/>',NULL,5563,5563);
INSERT INTO stanza VALUES('E1070','2','All my heart to Him I give,<br/>Ever to Him I''ll cling,<br/>In His blessed presence live,<br/>Ever His praises sing.<br/>Love so mighty and so true<br/>Merits my soul''s best songs;<br/>Faithful, loving service, too,<br/>To Him belongs.<br/>',NULL,5564,5564);
INSERT INTO stanza VALUES('E1070','3','Souls in danger, look above,<br/>Jesus completely saves;<br/>He will lift you by His love<br/>Out of the angry waves.<br/>He''s the Master of the sea,<br/>Billows His will obey;<br/>He your Savior want to be-<br/>Be saved today.<br/>',NULL,5565,5565);
INSERT INTO stanza VALUES('E1071','1','Sinner Jesus will receive;<br/>Sound this word of grace to all<br/>Who the heavenly pathway leave,<br/>All who linger, all who fall.<br/>',NULL,5566,5566);
INSERT INTO stanza VALUES('E1071','chorus','Sing it o''er and o''er again;<br/>Christ receiveth sinful men;<br/>Make the message clear and plain:<br/>Christ receiveth sinful men.<br/>',NULL,5567,5567);
INSERT INTO stanza VALUES('E1071','2','Come, and He will give you rest;<br/>Trust Him for His word is plain;<br/>He will take the sinfulest;<br/>Christ receiveth sinful men.<br/>',NULL,5568,5568);
INSERT INTO stanza VALUES('E1071','3','Now my heart condemns me not,<br/>Pure before the law I stand;<br/>He who cleansed me from all spot,<br/>Satisfied its last demand.<br/>',NULL,5569,5569);
INSERT INTO stanza VALUES('E1071','4','Christ receiveth sinful men,<br/>Even me with all my sin;<br/>Purged from every spot and stain,<br/>Glory I shall enter in.<br/>',NULL,5570,5570);
INSERT INTO stanza VALUES('E1072','1','She only touched the hem of His garment<br/>As to His side she stole,<br/>Amid the crowd that gathered around Him;<br/>And straightway she was whole.<br/>',NULL,5571,5571);
INSERT INTO stanza VALUES('E1072','chorus','Oh, touch the hem of His garment!<br/>And thou, too, shalt be free!<br/>His saving power this very hour<br/>Shall give new life to thee!<br/>',NULL,5572,5572);
INSERT INTO stanza VALUES('E1072','2','He''s pow''rful, present, real and gracious;<br/>Thou to canst touch Him now!<br/>Just come and touch while His is still passing,<br/>His power thou shalt know.<br/>',NULL,5573,5573);
INSERT INTO stanza VALUES('E1072','3','Just touch in faith and touch Him in spirit,<br/>And He will make thee whole;<br/>And peace that passeth all understanding<br/>With joy will fill thy soul.<br/>',NULL,5574,5574);
INSERT INTO stanza VALUES('E1073','1','Hark, here is a hidden myst''ry,<br/>Hidden from the human hist''ry!<br/>Hark and take this glorious myst''ry,<br/>Christ will be one with you!<br/>Glory, glory, hallelujah!<br/>Glory, glory, hallelujah!<br/>Hark and take this glorious myst''ry,<br/>Christ will be one with you!<br/>',NULL,5575,5575);
INSERT INTO stanza VALUES('E1074','1','O what mystery, the Savior<br/>With me is one!<br/>O what a marvelous salvation<br/>God gives me in His Son!<br/>Hallelujah! Hallelujah!<br/>Glorious mystery!<br/>Nothing in heav''n or earth can sever<br/>Jesus my Lord from me!<br/>',NULL,5576,5576);
INSERT INTO stanza VALUES('E1075','1','Tell me the old, old story,<br/>Of unseen things above,<br/>Of Jesus and His glory,<br/>Of Jesus and His love;<br/>Tell me the story simply,<br/>As to a little child,<br/>For I am weak and weary,<br/>And helpless and defiled.<br/>',NULL,5577,5577);
INSERT INTO stanza VALUES('E1075','chorus','Tell me the old, old story,<br/>Tell me the old, old story,<br/>Tell me the old, old story,<br/>Of Jesus and His love.<br/>',NULL,5578,5578);
INSERT INTO stanza VALUES('E1075','2','Tell me the story slowly,<br/>That I may take it in-<br/>That wonderful redemption,<br/>God''s remedy for sin;<br/>Tell me the story often,<br/>For I forget so soon,<br/>The "early dew" of morning<br/>Has passed away at noon.<br/>',NULL,5579,5579);
INSERT INTO stanza VALUES('E1075','3','Tell me the story softly,<br/>With earnest tones and grave;<br/>Remember I''m the sinner<br/>Whom Jesus came to save;<br/>Tell me the story always,<br/>If you would really be,<br/>In any time of trouble,<br/>A comforter to me.<br/>',NULL,5580,5580);
INSERT INTO stanza VALUES('E1075','4','Tell me the same old story,<br/>When you have cause to fear<br/>That this world''s empty glory<br/>Is costing me to dear;<br/>And when the Lord''s bright glory<br/>Is dawning on my soul,<br/>Tell me the old, old story:<br/>"Christ Jesus make thee whole."<br/>',NULL,5581,5581);
INSERT INTO stanza VALUES('E1076','1','O teach me what it meaneth:<br/>That Cross uplifted high,<br/>With One, the Man of Sorrows,<br/>Condemned to bleed and die.<br/>O teach me what it cost Thee<br/>To make a sinner whole;<br/>And teach me, Savior, teach me<br/>The value of a soul.<br/>',NULL,5582,5582);
INSERT INTO stanza VALUES('E1076','2','O teach me what it meaneth:<br/>That sacred crimson tide,<br/>The blood and water flowing<br/>From Thine own wounded side.<br/>Teach me that if non other<br/>Had sinned but only I,<br/>Yet still, O blessed Savior,<br/>Thou on the cross must die.<br/>',NULL,5583,5583);
INSERT INTO stanza VALUES('E1076','3','O teach me what it meaneth:<br/>Thy love beyond compare,<br/>The love that reacheth deeper<br/>Than depth of self-despair!<br/>Yea, teach me, till there gloweth<br/>In this cold heart of mine<br/>Some feeble, pale reflection<br/>Of that pure love of Thine.<br/>',NULL,5584,5584);
INSERT INTO stanza VALUES('E1076','4','O teach me what it meaneth,<br/>For I am full of sin;<br/>And grace alone can reach me,<br/>And love alone can win.<br/>O teach me, for I need Thee,<br/>I have no hope beside,<br/>The chief of all the sinners<br/>For whom the Savior died.<br/>',NULL,5585,5585);
INSERT INTO stanza VALUES('E1076','5','O teach me what it meaneth:<br/>The rest which Thou dost give<br/>To all the heavy-laden<br/>Who look to Thee and live.<br/>Because I am a rebel<br/>Thy pardon I receive:<br/>Because Thou dost command me,<br/>I can, I do believe.<br/>',NULL,5586,5586);
INSERT INTO stanza VALUES('E1076','6','O infinite Redeemer,<br/>I bring no other plea;<br/>Because Thou dost invite me<br/>I cast myself on Thee.<br/>Because Thou dost accept me<br/>I love and I adore;<br/>Because Thy love constraineth,<br/>I''ll praise Thee evermore.<br/>',NULL,5587,5587);
INSERT INTO stanza VALUES('E1077','1','There were ninety and nine that safely lay<br/>In the shelter of the flock,<br/>But one was on the hills away,<br/>Far off in the cold and dark;<br/>Away on the mountains wild and bare,<br/>Away from the tender Shepherd''s care.<br/>Away on the mountains wild and bare,<br/>Away from the tender Shepherd''s care.<br/>',NULL,5588,5588);
INSERT INTO stanza VALUES('E1077','2','"Lord, Thou hast here Thy ninety and nine;<br/>Are they not enough for Thee?"<br/>But the Shepherd made answer: "This of Mine<br/>Has wandered away from Me;<br/>And although the road be rough and steep,<br/>I go to the desert to find My sheep."<br/>And although the road be rough and steep,<br/>I go to the desert to find My sheep."<br/>',NULL,5589,5589);
INSERT INTO stanza VALUES('E1077','3','But none of the ransomed ever knew<br/>How deep were the waters crossed;<br/>Nor how dark was the night which the<br/>Lord passed though<br/>Ere He found His sheep that was lost.<br/>Out in the bleak desert He heard its cry-<br/>All bleeding and helpless, and ready to die.<br/>Out in the bleak desert He heard its cry-<br/>All bleeding and helpless, and ready to die.<br/>',NULL,5590,5590);
INSERT INTO stanza VALUES('E1077','4','"Lord, whence are those blood-drops all the way<br/>That mark out the mountain''s track?"<br/>"They were shed for one who had gone astray<br/>Ere the Shepherd could bring him back."<br/>"Lord, whence are Thy hands so rent and torn?"<br/>"They''re pierced tonight by many a thorn."<br/>"Lord, whence are Thy hands so rent and torn?"<br/>"They''re pierced tonight by many a thorn."<br/>',NULL,5591,5591);
INSERT INTO stanza VALUES('E1077','5','And all through the mountains, thunder-riven,<br/>And up from the rocky steep,<br/>There arose a cry to the gate of heaven,<br/>"Rejoice! I have found My sheep!"<br/>And the angels echoed around the throne,<br/>"Rejoice, for the Lord bring back His own!"<br/>And the angels echoed around the throne,<br/>"Rejoice, for the Lord bring back His own!"<br/>',NULL,5592,5592);
INSERT INTO stanza VALUES('E1078','1','One sat alone beside the highway begging,<br/>His eyes were blind, the light he could not see;<br/>He clutched his rags and shivered in the shadows,<br/>Then Jesus came and bade his darkness flee.<br/>',NULL,5593,5593);
INSERT INTO stanza VALUES('E1078','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,5594,5594);
INSERT INTO stanza VALUES('E1078','2','From home and friends the evil spirits drove him,<br/>Among the tombs he dwelt in misery;<br/>He cut himself as demon pow''rs possessed him,<br/>Then Jesus came and set the captive free.<br/>',NULL,5595,5595);
INSERT INTO stanza VALUES('E1078','3','"Unclean! Unclean!" the leper cried in torment,<br/>The deaf, the dumb, in helplessness stood near;<br/>The fever raged, disease had gripped its victim,<br/>Then Jesus came and cast out every fear.<br/>',NULL,5596,5596);
INSERT INTO stanza VALUES('E1078','4','Their hearts were sad as in the tomb they laid him,<br/>For death had come and taken him away;<br/>Their night was dark and bitter tears were falling,<br/>Then Jesus came and night was turned to day.<br/>',NULL,5597,5597);
INSERT INTO stanza VALUES('E1078','5','So men today have found the Savior able,<br/>They could not conquer passion, lust and sin;<br/>Their broken hearts had left them sad and lonely,<br/>Then Jesus came and dwelt, Himself, within.<br/>',NULL,5598,5598);
INSERT INTO stanza VALUES('E1079','1','If I gained the world, but lost the Savior,<br/>Were my life worth living for a day?<br/>Could my yearning heart find rest and comfort<br/>In the things that soon must pass away?<br/>If I gained the world, but lost the Savior,<br/>Would my gain be worth the lifelong strife?<br/>Are all earthly pleasures worth comparing<br/>For a moment with a Christ-filled life?<br/>',NULL,5599,5599);
INSERT INTO stanza VALUES('E1079','2','Had I wealth and love in fullest measure,<br/>And a name revered both far and near,<br/>Yet no hope beyond, no harbor waiting,<br/>Where my storm-tossed vessel I could steer;<br/>If I gained the world, but lost the Savior,<br/>Who endured the cross and died for me,<br/>Could then all the world afford a refuge,<br/>Whither, in my anguish, I might flee?<br/>',NULL,5600,5600);
INSERT INTO stanza VALUES('E1079','3','O what emptiness!-without the Savior<br/>''Mid the sins and sorrows here below!<br/>And eternity, how dark without Him!<br/>Only night and tears and endless woe!<br/>What, though I might live without the Savior,<br/>When I come to die, how would it be?<br/>O to face the valley''s gloom without Him!<br/>And without Him all eternity!<br/>',NULL,5601,5601);
INSERT INTO stanza VALUES('E1079','4','O the joy of having all in Jesus!<br/>What a balm the broken heart to heal!<br/>Ne''er a sin so great, but He''ll forgive it,<br/>Nor a sorrow that He does not feel!<br/>If I have but Jesus, only Jesus,<br/>Nothing else in all the world beside-<br/>O then everything is mine in Jesus;<br/>For my needs and more He will provide.<br/>',NULL,5602,5602);
INSERT INTO stanza VALUES('E1080','1','What profit all the labor here?<br/>There''s nothing new for you and me!<br/>Remember not the former things,<br/>They''re all vanity!<br/>',NULL,5603,5603);
INSERT INTO stanza VALUES('E1080','chorus','Vanity! Vanity!<br/>Vanity! Vanity!<br/>''Tis chasing the wind,<br/>It''s all vanity!<br/>',NULL,5604,5604);
INSERT INTO stanza VALUES('E1080','2','Man''s life is full of grief and pain:<br/>Much wisdom bringeth misery!<br/>Increasing knowledge addeth woe!<br/>It''s all vanity!<br/>',NULL,5605,5605);
INSERT INTO stanza VALUES('E1080','3','What good our pleasure and our wealth?<br/>Though joys we have and family,<br/>We''ll have our worries just the same!<br/>It''s all vanity!<br/>',NULL,5606,5606);
INSERT INTO stanza VALUES('E1080','4','Days of toil to gain and restless nights:<br/>Though gained without calamity,<br/>When death comes it is gone for aye!<br/>It''s all vanity!<br/>',NULL,5607,5607);
INSERT INTO stanza VALUES('E1080','5','Remember God in days of youth!<br/>Fear Him, and such will be your gain!<br/>With Him you will be satisfied,<br/>For He is not vain!<br/>',NULL,5608,5608);
INSERT INTO stanza VALUES('E1080','chorus','Christ without, all is vain!<br/>Christ within all is gain!<br/>All things are vain,<br/>Christ only is gain!<br/>',NULL,5609,5609);
INSERT INTO stanza VALUES('E1081','1','Father God, Thou are the source of life.<br/>We, Thy sons, are Thine expression;<br/>In Thy name, our dear possession.<br/>Father God, Thou art the source of life.<br/>',NULL,5610,5610);
INSERT INTO stanza VALUES('E1081','chorus','In Thy life, in Thy life,<br/>We have oneness in Thy life.<br/>In Thy life, in Thy life,<br/>In Thy life, O Father, we are one.<br/>',NULL,5611,5611);
INSERT INTO stanza VALUES('E1081','2','How we thank Thee that Thy holy Word<br/>With Thy nature, saturates us;<br/>From the world it separates us.<br/>Thank Thee, Father, for Thy holy Word.<br/>',NULL,5612,5612);
INSERT INTO stanza VALUES('E1081','chorus','Through Thy Word, through Thy Word,<br/>We have oneness through Thy Word.<br/>Through Thy Word, through Thy Word,<br/>Through Thy holy Word we''re all made one.<br/>',NULL,5613,5613);
INSERT INTO stanza VALUES('E1081','3','Oh, the glory of the Triune God!<br/>We''re His sons, oh, what a blessing!<br/>We His glory are expressing-<br/>Oh, the glory of the Triune God!<br/>',NULL,5614,5614);
INSERT INTO stanza VALUES('E1081','chorus','In Thy glory, in Thy glory,<br/>In Thy glory we are one.<br/>In Thy glory, in Thy glory,<br/>In Thy glory we are all made one!<br/>',NULL,5615,5615);
INSERT INTO stanza VALUES('E1082','1','The living of Christ when He sojourned on earth,<br/>The sixteenth Psalm show us, was wholly of worth.<br/>His attitudes, choices, and interests all tell<br/>The man who in God''s tabernacle may dwell.<br/>',NULL,5616,5616);
INSERT INTO stanza VALUES('E1082','2','"Preserve me, O God, for in Thee I confide"-<br/>In God He took refuge whate''er did betide.<br/>"O Thou art my Lord, I''ve no good beyond Thee"-<br/>He spoke in Himself unto God constantly.<br/>',NULL,5617,5617);
INSERT INTO stanza VALUES('E1082','3','"As for all the saints who are dwelling on earth,"<br/>To Him they''re the people of excellent worth.<br/>Of them He has said He has all His delight-<br/>In proving this all the four Gospels unite.<br/>',NULL,5618,5618);
INSERT INTO stanza VALUES('E1082','4','"The Lord is my portion, the Lord is my cup"-<br/>For everything He to the Father looked up.<br/>"The Lord I will bless who my counsel doth give"-<br/>Himself He denied and by God''s word did live.<br/>',NULL,5619,5619);
INSERT INTO stanza VALUES('E1082','5','His heart thus was glad and His spirit rejoiced,<br/>And e''en in His death praise to God could be voiced;<br/>His soul God would never abandon to hell,<br/>But in resurrection His body would dwell.<br/>',NULL,5620,5620);
INSERT INTO stanza VALUES('E1082','6','God raised Him, and He with God''s glory was crowned;<br/>Then fulness of joy in God''s presence He found.<br/>E''en now at the Father''s right hand is His seat,<br/>Where flowing forever are pleasures complete.<br/>',NULL,5621,5621);
INSERT INTO stanza VALUES('E1083','1','O how nigh the Lord is unto all who call on Him!<br/>When we call, His very presence strengthens us within.<br/>Seeking Jesus, He is found, and calling, He is near;<br/>O what a comfort to our hearts to call His name so dear!<br/>',NULL,5622,5622);
INSERT INTO stanza VALUES('E1083','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted-O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere;<br/>"O Lord Jesus!" O what a name!<br/>',NULL,5623,5623);
INSERT INTO stanza VALUES('E1083','2','Call upon the name of Jesus, and you will be saved,<br/>O Lord Jesus, hallelujah, nevermore enslaved!<br/>We may take salvation''s cup by calling on the Lord;<br/>Salvation from a host of things does His dear name afford.<br/>',NULL,5624,5624);
INSERT INTO stanza VALUES('E1083','3','To the Lord, the Jew, the Greek and everyone''s the same;<br/>He is rich unto all men that call upon His name.<br/>O Lord Jesus, what a joy to call and really live;<br/>When breathing in Thy name, what<br/>pleasure Thou to us dost give.<br/>',NULL,5625,5625);
INSERT INTO stanza VALUES('E1083','4','In the God of our salvation we may take delight,<br/>Calling on His name at all times, though in bliss or blight.<br/>I will call upon His name as long as I shall live,<br/>Because He has inclined His ear, and grace so full does give.<br/>',NULL,5626,5626);
INSERT INTO stanza VALUES('E1083','5','We will call upon the Lord,<br/>who''s worthy of our praise;<br/>Thus our grateful hearts in worship<br/>we to Him may raise.<br/>We are those who call upon<br/>His name in every place<br/>With all the saints who from<br/>a pure heart call and taste His grace.<br/>',NULL,5627,5627);
INSERT INTO stanza VALUES('E1084','1','Thy name is as ointment poured forth:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Thy name is as ointment poured forth,<br/>Thy name is as ointment poured forth.<br/>',NULL,5628,5628);
INSERT INTO stanza VALUES('E1084','2','Therefore do the virgins love Thee:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Therefore do the virgins love Thee,<br/>Therefore do the virgins love Thee.<br/>',NULL,5629,5629);
INSERT INTO stanza VALUES('E1084','3','Thy love is much better than wine:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Thy love is much better than wine,<br/>Thy love is much better than wine.<br/>',NULL,5630,5630);
INSERT INTO stanza VALUES('E1084','4','Draw me, we will run after Thee:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Draw me, we will run after Thee,<br/>Draw me, we will run after Thee.<br/>',NULL,5631,5631);
INSERT INTO stanza VALUES('E1084','5','Behold, Thou are fair, my Beloved:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Behold, Thou are fair, my Beloved:<br/>Behold, Thou are fair, my Beloved:<br/>',NULL,5632,5632);
INSERT INTO stanza VALUES('E1084','6','I found Him whom my soul doth love:<br/>Jesus, Jesus, Jesus, Jesus!<br/>I found Him whom my soul doth love:<br/>I found Him whom my soul doth love:<br/>',NULL,5633,5633);
INSERT INTO stanza VALUES('E1084','7','I held Him and would not let go:<br/>Jesus, Jesus, Jesus, Jesus!<br/>I held Him and would not let go,<br/>I held Him and would not let go.<br/>',NULL,5634,5634);
INSERT INTO stanza VALUES('E1084','8','Make haste, my Beloved, to come:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Make haste, my Beloved, to come:<br/>Make haste, my Beloved, to come:<br/>',NULL,5635,5635);
INSERT INTO stanza VALUES('E1084','9','We love Thee with all of our heart:<br/>Jesus, Jesus, Jesus, Jesus!<br/>We love Thee with all of our heart:<br/>We love Thee with all of our heart:<br/>',NULL,5636,5636);
INSERT INTO stanza VALUES('E1085','1','His Name is Wonderful;<br/>His Name is Counselor;<br/>His name the Mighty God,<br/>Jesus my Lord.<br/>',NULL,5637,5637);
INSERT INTO stanza VALUES('E1085','2','A Child and Son is He;<br/>Eternal Father He;<br/>The Prince of Peace to me,<br/>Jesus my Lord.<br/>',NULL,5638,5638);
INSERT INTO stanza VALUES('E1085','3','Praise the Creator,<br/>Jesus my Savior,<br/>Life-giving Spirit now.<br/>In spirit worship Him.<br/>Love and adore Him;<br/>His Name is Wonderful,<br/>Jesus my Lord.<br/>',NULL,5639,5639);
INSERT INTO stanza VALUES('E1086','1','How we love the glorious name,<br/>The name of Jesus!<br/>''Tis the name above all names-<br/>On earth or in heav''n.<br/>As we breathe this precious name,<br/>Darkness and death cannot remain;<br/>For we call and get the Person of that name!<br/>',NULL,5640,5640);
INSERT INTO stanza VALUES('E1086','2','Dear Lord Jesus, with our tongues;<br/>We gladly confess Thy name,<br/>To the glory of the Father God above.<br/>For to us to speak Thy praise,<br/>Is the enjoyment of our days;<br/>Calling JESUS is to call the One we love!<br/>',NULL,5641,5641);
INSERT INTO stanza VALUES('E1087','1','Oh, hallelujah, what a death<br/>Christ died upon the cross!<br/>Not only was He dying there<br/>But everything that death did share:<br/>God was included too,<br/>All men with me and you-<br/>Oh, hallelujah, for such a cross!<br/>',NULL,5642,5642);
INSERT INTO stanza VALUES('E1087','2','Oh, praise the Lord, man died in God<br/>And to an end was brought!<br/>Now from this man I''m wholly free<br/>For God has terminated me!<br/>Oh, what a wondrous death,<br/>Oh, what a wondrous death;<br/>Oh, hallelujah, for such a death!<br/>',NULL,5643,5643);
INSERT INTO stanza VALUES('E1087','3','Oh, praise the Lord, God died in man,<br/>In man to be released.<br/>The grain of wheat fell to the ground,<br/>And now a multitude is found<br/>Filled with the life of God,<br/>Filled with the life of God;<br/>Oh, hallelujah, for such a life!<br/>',NULL,5644,5644);
INSERT INTO stanza VALUES('E1087','4','Lord, how we praise You for Your cross,<br/>Your all-inclusive death!<br/>The center of the universe,<br/>It has untold, eternal worth!<br/>Lord, how we love Your cross,<br/>Lord, how we love Your cross;<br/>Oh, hallelujah, for such a cross!<br/>',NULL,5645,5645);
INSERT INTO stanza VALUES('E1088','1','God was born a human being<br/>As the Babe of Bethlehem,<br/>Passed He then through human living,<br/>Perfect blend of God with men.<br/>God, according to His plan,<br/>Lived a mingled life with man.<br/>Hallelujah, Hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5646,5646);
INSERT INTO stanza VALUES('E1088','2','Then with God this man was blended<br/>On the altar as He died;<br/>God and man and all creation<br/>On the cross were crucified.<br/>Man and all of God''s creation,<br/>Sunk in total termination.<br/>Hallelujah, Hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5647,5647);
INSERT INTO stanza VALUES('E1088','3','Everything we are was ended,<br/>Terminated on the cross,<br/>Only man in God ascended,<br/>Man in Adam suffered loss.<br/>Hallelujah, we''re elated,<br/>Our old man was terminated.<br/>Hallelujah, Hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5648,5648);
INSERT INTO stanza VALUES('E1088','4','Like the grain of wheat that''s buried<br/>In the earth to be increased,<br/>God''s own life the death must suffer,<br/>Thus in man to be released.<br/>Oh, the Lord of all be praised;<br/>God released in man is raised!<br/>Hallelujah, Hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5649,5649);
INSERT INTO stanza VALUES('E1089','1','Lamb of God so pure and spotless,<br/>Lamb of God for sinners slain.<br/>Thy shed blood has wrought redemption.<br/>Cleansing us from every stain.<br/>Lamb redeeming, Lamb redeeming.<br/>Bearing all our sins away,<br/>Bearing all our sins away!<br/>',NULL,5650,5650);
INSERT INTO stanza VALUES('E1089','2','Brazen serpent, to Thee looking,<br/>Son of Man, uplifted high.<br/>Thou didst bear the flesh of sin in<br/>Likeness on the cross to die.<br/>Old creation''s termination;<br/>Finished, Satan and the world,<br/>Finished, Satan and the world!<br/>',NULL,5651,5651);
INSERT INTO stanza VALUES('E1089','3','Grain of wheat, so small and lowly,<br/>Without death abides alone;<br/>Life divine enclosed within it,<br/>Into death it must be sown.<br/>Life releasing, Christ increasing,<br/>Many grains to birth to bring,<br/>Many grains to birth to bring!<br/>',NULL,5652,5652);
INSERT INTO stanza VALUES('E1089','4','Lamb of God—our sin''s redemption,<br/>Brazen serpent—Satan''s end,<br/>Grain of wheat—life’s reproduction,<br/>Now with many grains we blend.<br/>Hallelujah! Hallelujah!<br/>What an all-inclusive death,<br/>What an all-inclusive death!<br/>',NULL,5653,5653);
INSERT INTO stanza VALUES('E1090','1','Dear Lord, how precious is Thy blood,<br/>Of the New Testament!<br/>By it God''s blessings we receive,<br/>And we with Him are blent.<br/>',NULL,5654,5654);
INSERT INTO stanza VALUES('E1090','2','''Tis by Thy blood we''ve been redeemed,<br/>And by it sanctified.<br/>Now is our conscience free from sin,<br/>From dead works purified.<br/>',NULL,5655,5655);
INSERT INTO stanza VALUES('E1090','3','Better than Abel''s, now Thy blood<br/>Speaks unto God for us.<br/>Perfect redemption it provides,<br/>Meeting God''s righteousness.<br/>',NULL,5656,5656);
INSERT INTO stanza VALUES('E1090','4','Through the eternal Spirit, Thou<br/>Offeredst Thyself to God,<br/>This sacrifice can ne''er grow old;<br/>Timeless is Thy dear blood.<br/>',NULL,5657,5657);
INSERT INTO stanza VALUES('E1090','5','''Tis by Thy blood we boldly come<br/>Unto the throne of grace,<br/>Unto our God, the cov''nant new,<br/>And to the Holiest Place.<br/>',NULL,5658,5658);
INSERT INTO stanza VALUES('E1090','6','Lord, by Thy blood, God is obliged<br/>His very Self to give;<br/>He must receive us to Himself,<br/>And He in us must live.<br/>',NULL,5659,5659);
INSERT INTO stanza VALUES('E1090','7','Dear Lord, how precious is Thy blood<br/>Of the New Testament!<br/>By it God''s blessings we receive,<br/>And we with Him are blent.<br/>',NULL,5660,5660);
INSERT INTO stanza VALUES('E1091','1','We praise Thee, O Lord Jesus, Thou didst come,<br/>The way into God''s presence to reveal.<br/>We worship Thee that Thou didst leave Thy throne,<br/>To come as our High Priest with sin to deal.<br/>Lord Jesus, Thou hast offered Thine own blood,<br/>And settled once for all our peace with God.<br/>',NULL,5661,5661);
INSERT INTO stanza VALUES('E1091','2','Thy blood has now been sprinkled on the throne<br/>In full redemption for Thy people''s sin.<br/>The sweetness of the love that Thou hast shown<br/>Has ris''n to fill the holiest place within.<br/>And by the blood once offered in that place<br/>God flows to us in mercy and in grace.<br/>',NULL,5662,5662);
INSERT INTO stanza VALUES('E1091','3','Yet, Lord, Thou camest not just to atone,<br/>But Thou didst come and bear our sins away.<br/>We, with a conscience purged, approach the throne,<br/>For all our sins were laid on Thee that day.<br/>Thou, separated from the Father''s face,<br/>Didst pay the awful price for us in grace.<br/>',NULL,5663,5663);
INSERT INTO stanza VALUES('E1091','4','The way into God''s presence thus is cleared,<br/>For ransomed sinners who have heard Thy call.<br/>Thou, Lord, hast taken all that we had feared<br/>When Thou didst shed Thy blood and give Thine all;<br/>Our heart in grateful praise to Thee we bind,<br/>And now our life in Thee alone we find.<br/>',NULL,5664,5664);
INSERT INTO stanza VALUES('E1092','1','The saints throughout the centuries<br/>Have praised the Lord that He,<br/>The Lamb of God, has saved us,<br/>From sin has set us free;<br/>Yet scarcely for the Lion<br/>Have we yet sounded praise,<br/>Though oft for our redemption<br/>We''ve all our voices raised.<br/>',NULL,5665,5665);
INSERT INTO stanza VALUES('E1092','2','John wept as he considered<br/>That none the right did own<br/>The scroll to take and open,<br/>God''s myst''ry to make known;<br/>No, none on earth nor heaven,<br/>Nor universe around-<br/>And we, too, would be weeping<br/>If none were worthy found.<br/>',NULL,5666,5666);
INSERT INTO stanza VALUES('E1092','3','The universe, mysterious,<br/>Would be in darkness still,<br/>Could none break through to open<br/>The scroll, to show God''s will;<br/>But, lo, the worth Lion<br/>Of Judah hath prevailed<br/>The seven seals to open,<br/>And have the scroll unveiled.<br/>',NULL,5667,5667);
INSERT INTO stanza VALUES('E1092','4','No longer now in darkness<br/>God''s secret is enclosed,<br/>But to our inner vision<br/>It''s open, full, disclosed;<br/>Our hearts are for this purpose,<br/>Our lives are for His plan;<br/>And for this revelation<br/>We praise the Lion-Lamb!<br/>',NULL,5668,5668);
INSERT INTO stanza VALUES('E1092','5','The four-and-twenty elders<br/>All fall before that sight.<br/>The living creatures praise Him,<br/>Who rest not, day nor night.<br/>So let us join their praises<br/>To Him who loosed God''s plan;<br/>We''ll lift with theirs our voices<br/>To praise the Lion-Lamb!<br/>',NULL,5669,5669);
INSERT INTO stanza VALUES('E1093','1','Though countless ages, many men<br/>Have longed and sought and tried to see<br/>The secret of the universe,<br/>So vast, so great a mystery.<br/>',NULL,5670,5670);
INSERT INTO stanza VALUES('E1093','2','Yet not through struggling could frail man<br/>The secret for this myst''ry find;<br/>Nor change, by stumbling, come upon<br/>Such hidden things-to these he''s blind.<br/>',NULL,5671,5671);
INSERT INTO stanza VALUES('E1093','3','Behold in heav''n a throne is set,<br/>And One upon the throne revealed;<br/>And held in His right hand a scroll-<br/>The mystery is tightly sealed.<br/>',NULL,5672,5672);
INSERT INTO stanza VALUES('E1093','4','Through all the universe, a cry-<br/>''Can one be found of such great worth<br/>The scroll to take? Yet no reply,<br/>From heav''n, below, or on the earth.<br/>',NULL,5673,5673);
INSERT INTO stanza VALUES('E1093','5','Were it a matter now for man<br/>By chance, or some ability,<br/>Then surely one would now step forth<br/>To open God''s economy.<br/>',NULL,5674,5674);
INSERT INTO stanza VALUES('E1093','6','Yet sad and solemn was that sight.<br/>John wept as then he looked around;<br/>And we, too, still might weeping be<br/>If none at all were worthy found.<br/>',NULL,5675,5675);
INSERT INTO stanza VALUES('E1093','7','But then the angel said, ''Weep not!<br/>Behold, the Lion has prevailed<br/>To take the scroll and loose its seals;<br/>He has the mystery now unveiled!''<br/>',NULL,5676,5676);
INSERT INTO stanza VALUES('E1093','8','So, John looked up the Lion to see,<br/>But, lo, he then beheld a Lamb;<br/>Christ both o''ercame the enemy,<br/>And wrought redemption''s work for man.<br/>',NULL,5677,5677);
INSERT INTO stanza VALUES('E1093','9','The angels fall before His throne,<br/>Four living creatures offer praise,<br/>All glory to the Lion-Lamb;<br/>Let us with theirs our voices raise!<br/>',NULL,5678,5678);
INSERT INTO stanza VALUES('E1094','1','Lo, the nations all assemble<br/>And imagine vanity,<br/>Kings and princes plot together<br/>''Gainst the Lord in unity.<br/>"Let us break their bonds asunder,<br/>Cast away their cords from us."<br/>''Gainst the Lord and His Anointed<br/>Worldly rulers counsel thus.<br/>',NULL,5679,5679);
INSERT INTO stanza VALUES('E1094','2','He who sitteth in the heavens<br/>In contempt will laugh at them,<br/>Vex them in His fierce displeasure,<br/>Terrifying all such men.<br/>Yet upon the hill of Zion<br/>God has His anointed King-<br/>This is God’s own declaration,<br/>All the kings admonishing.<br/>',NULL,5680,5680);
INSERT INTO stanza VALUES('E1094','3','Now ''tis Christ, ''tis God''s Anointed,<br/>Who declares the Lord''s decree:<br/>"Thou''rt my Son (in resurrection),<br/>This day I''ve begotten Thee.<br/>All the nations I will give Thee<br/>For Thine own inheritance.<br/>Thou shalt dash them into pieces<br/>In Thy kingly excellence."<br/>',NULL,5681,5681);
INSERT INTO stanza VALUES('E1094','4','Now be wise, O be instructed,<br/>All ye rulers of the earth,<br/>Fear the Lord, rejoice with trembling,<br/>Serve the only One of worth.<br/>Kiss the Son, lest He be angry<br/>And ye perish in the way.<br/>"All who trust in Him are blessed,"<br/>All who trust in Him will say.<br/>',NULL,5682,5682);
INSERT INTO stanza VALUES('E1094','5','Lord, we praise Thee, we have seen Him-<br/>Thy unique Anointed One-<br/>And from vanity repenting,<br/>We in love have kissed Thy Son.<br/>"All who trust in Him are blessed"-<br/>Not "all those who keep the law."<br/>In that risen One believing,<br/>We are blest forevermore.<br/>',NULL,5683,5683);
INSERT INTO stanza VALUES('E1095','1','The Lord shall get the glory<br/>If we will sing His praise,<br/>And angel hosts will listen<br/>When we our voices raise;<br/>The world around will hear us<br/>Give glory unto God,<br/>And Satan''s hosts will tremble<br/>And flee our conqu''ring rod.<br/>',NULL,5684,5684);
INSERT INTO stanza VALUES('E1095','2','Our mouth shut up defeats us<br/>And wins the Devil''s smile;<br/>So why not open battle<br/>And chase him all the while.<br/>By "sacrifice of praises"<br/>And shouts of victory-<br/>''Twill cost us but our faces<br/>God''s chosen fools to be!<br/>',NULL,5685,5685);
INSERT INTO stanza VALUES('E1095','3','The world has never helped us<br/>To shout our Savior''s praise,<br/>Nor given Him the glory<br/>Nor lent one thankful phrase;<br/>So need we ask permission<br/>To praise th'' ascended Lord?<br/>Cry out! Release your spirit!<br/>Much grace He does afford!<br/>',NULL,5686,5686);
INSERT INTO stanza VALUES('E1095','4','O brothers, be not silent!<br/>O sisters, cry aloud!<br/>The sound shall tell God''s triumph<br/>And blessings far abroad.<br/>Now is the time to praise Him,<br/>Yes now, at any cost!<br/>O joy in your salvation,<br/>And in His mercy boast!<br/>',NULL,5687,5687);
INSERT INTO stanza VALUES('E1096','1','''Tis the local church proclaiming,<br/>Jesus is Lord!<br/>All the saints with joy are naming<br/>Jesus as Lord.<br/>All His work He has completed,<br/>Satan and his host defeated;<br/>On the throne of glory seated,<br/>Jesus is Lord!<br/>',NULL,5688,5688);
INSERT INTO stanza VALUES('E1096','2','Jesus is the living Spirit,<br/>Jesus is Lord!<br/>He is here, all people, hear it:<br/>Jesus is Lord!<br/>Be no more a poor lamenter;<br/>Call on Him, and He will enter<br/>And become your glorious center-<br/>Jesus is Lord!<br/>',NULL,5689,5689);
INSERT INTO stanza VALUES('E1096','3','He will transform all your living,<br/>Jesus, the Lord!<br/>All His riches to you giving,<br/>Jesus, the Lord!<br/>He''ll forever satisfy you,<br/>Everyday real life supply you,<br/>And with God will unify you,<br/>Jesus the Lord!<br/>',NULL,5690,5690);
INSERT INTO stanza VALUES('E1096','4','In His mercy He received us,<br/>Jesus, the Lord!<br/>He will never, never leave us,<br/>Jesus, the Lord!<br/>All the fullness of His being<br/>In His Body we are seeing,<br/>And the enemy is fleeing-<br/>Jesus is Lord!<br/>',NULL,5691,5691);
INSERT INTO stanza VALUES('E1097','1','O Lord, our Lord, how excellent<br/>Thy name in all the earth!<br/>Let every people, tribe, and tongue<br/>Proclaim its boundless worth.<br/>Out of the mouth of little ones<br/>Thou hast established praise,<br/>That Thou may still Thine enemy<br/>And swiftly end his days.<br/>',NULL,5692,5692);
INSERT INTO stanza VALUES('E1097','2','When we the universe behold,<br/>The work of Thy great hand-<br/>The sun, the moon, and all the stars<br/>By lofty wisdom planned;<br/>O what is man that Thou should''st care<br/>That Thou should''st mindful be?<br/>The son of man Thou visitest<br/>In Thine economy.<br/>',NULL,5693,5693);
INSERT INTO stanza VALUES('E1097','3','O Jesus Lord, Thou art that man,<br/>The One who joined our race,<br/>Who put upon Himself the flesh<br/>And took a lower place.<br/>But now with glory Thou art crowned,<br/>With sovereignty complete.<br/>Now through Thy Body Thou dost rule<br/>With all beneath Thy feet.<br/>',NULL,5694,5694);
INSERT INTO stanza VALUES('E1097','4','Thine incarnation, rising too,<br/>And Thy transcendency,<br/>Thy Lordship, Headship, kingdom full,<br/>And Body here we see.<br/>By all these steps of work divine<br/>Thou hast established praise.<br/>With overflowing hearts to Thee<br/>Our joyful voice we raise.<br/>',NULL,5695,5695);
INSERT INTO stanza VALUES('E1097','5','Oh, soon that blessed day shall come-<br/>All tongues these words shall peal!<br/>But in the local churches now<br/>We have a foretaste real.<br/>O Lord, our Lord, how excellent<br/>Thy name in all the earth!<br/>Let every people, tribe, and tongue<br/>Proclaim its boundless worth.<br/>',NULL,5696,5696);
INSERT INTO stanza VALUES('E1098','1','Our hearts are overflowing<br/>To speak a goodly thing-<br/>To tell what we''re experienced<br/>Of our exalted King.<br/>Our tongues as pens are ready,<br/>We''ve volumes here to ''write"-<br/>The glories of our Bridegroom,<br/>Our Lord and our delight.<br/>',NULL,5697,5697);
INSERT INTO stanza VALUES('E1098','2','Lord Jesus, Thou art fairer<br/>Than all the sons of men;<br/>Thy goodness is transcendent-<br/>Hallelujah! Amen!<br/>Upon Thy lips most holy<br/>Abundant grace is poured;<br/>Forever God has blessed Thee,<br/>Our gracious, glorious Lord!<br/>',NULL,5698,5698);
INSERT INTO stanza VALUES('E1098','3','Thou art the mighty Warrior<br/>Who rides to victory;<br/>In Thy majestic glory<br/>Ride on triumphantly!<br/>The peoples fall beneath Thee-<br/>The conquering One Thou art.<br/>Thine arrows in their sharpness<br/>Have entered Satan''s heart!<br/>',NULL,5699,5699);
INSERT INTO stanza VALUES('E1098','4','Thy throne, O God, forever<br/>And ever shall endure;<br/>The scepter of Thy kingdom<br/>Upon the earth is sure.<br/>''Tis with the oil of gladness<br/>God has anointed Thee<br/>Above all Thy companions-<br/>How worthy there to be!<br/>',NULL,5700,5700);
INSERT INTO stanza VALUES('E1098','5','Of aloes, myrrh, and cassia<br/>Do all Thy garments smell:<br/>Thy death and resurrection<br/>Do all Thy deeds forthtell.<br/>Out of the local churches<br/>Shall praises make Thee glad,<br/>And praises upon praises<br/>Thy joyful saints shall add.<br/>',NULL,5701,5701);
INSERT INTO stanza VALUES('E1099','1','The queen in gold of Ophir<br/>At Thy right hand doth stand;<br/>King''s daughters are the women<br/>Who fill Thy honored band.<br/>The church in all her glory<br/>Shall match her glorious King,<br/>And all the saints, the women,<br/>Thy likeness there shall bring.<br/>',NULL,5702,5702);
INSERT INTO stanza VALUES('E1099','2','O daughter, now consider,<br/>E''en now incline thine ear:<br/>Remember not thy people<br/>And all thine own things here.<br/>Thy beauty then shall blossom-<br/>''Twill be the King''s desire;<br/>For He thy worthy Lord is,<br/>Thy worship to inspire.<br/>',NULL,5703,5703);
INSERT INTO stanza VALUES('E1099','3','The daughter''s glorious garments<br/>Are made of inwrought gold-<br/>Within the inner palace,<br/>How wondrous to behold!<br/>The glory of God''s nature<br/>Is given her to wear,<br/>That all His holy being<br/>She may in life declare.<br/>',NULL,5704,5704);
INSERT INTO stanza VALUES('E1099','4','In clothing too embroidered<br/>She''ll to the King be led,<br/>In that fine linen garment<br/>To be exhibited.<br/>''Tis by the Spirit''s stitching<br/>That Christ in us is wrought,<br/>And with this glorious garment<br/>We''ll to the King be brought.<br/>',NULL,5705,5705);
INSERT INTO stanza VALUES('E1099','5','What gladness and rejoicing<br/>When we the King shall see!<br/>We''ll shout His worthy praises<br/>Through all eternity.<br/>And though the King we worship<br/>Or glory in the Queen,<br/>In all this blest enjoyment<br/>The glory goes to Him.<br/>',NULL,5706,5706);
INSERT INTO stanza VALUES('E1100','1','God shall rise, His foes be scattered,<br/>All that hate Him flee away.<br/>As the wax before the fire,<br/>All the wicked He shall slay.<br/>But the righteous shall rejoice<br/>With a loud, triumphant voice,<br/>Singing praises, singing praises,<br/>Singing praises unto God!<br/>',NULL,5707,5707);
INSERT INTO stanza VALUES('E1100','2','He is riding through the deserts,<br/>Bringing in His saints in need.<br/>He''s a Father to the orphans<br/>And a refuge tried indeed<br/>In His holy habitation —<br/>What a wonderful salvation!<br/>Hallelujah, hallelujah!<br/>Hallelujah, Amen!<br/>',NULL,5708,5708);
INSERT INTO stanza VALUES('E1100','3','Here the lone have found a family,<br/>Here the desolate a home;<br/>Prisoners are brought from bondage<br/>To prosperity unknown.<br/>For the flock — what wondrous grace —<br/>God prepared this dwelling place:<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5709,5709);
INSERT INTO stanza VALUES('E1100','4','Now the Lord in mighty triumph<br/>Sends the news of victory;<br/>We the "women" spread the tidings —<br/>"Kings of armies flee, they flee!"<br/>No more sweat and dreary toil;<br/>We at home divide the spoil!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5710,5710);
INSERT INTO stanza VALUES('E1100','5','Lo, on high Christ hath ascended,<br/>Leading captives in His train;<br/>These as gifts He has perfected<br/>That the Lord may dwell with them.<br/>Brothers, sisters, we are those,<br/>We''re those transformed, vanquished foes!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5711,5711);
INSERT INTO stanza VALUES('E1100','6','Blessed be the Lord forever:<br/>Day by day He loads with good,<br/>E''en the God of our salvation —<br/>Spread His worthy praise abroad.<br/>His the goings forth from death,<br/>Every foe He conquereth!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,5712,5712);
INSERT INTO stanza VALUES('E1100','7','They have seen O God, Thy goings<br/>In Thy holy dwelling place,<br/>Thy triumphal, high processions<br/>Midst a mighty voice of praise.<br/>See the singers go before,<br/>Praising, praising o''er and o''er:<br/>Hallelujah, hallelujah!<br/>Hallelujah! Amen!<br/>',NULL,5713,5713);
INSERT INTO stanza VALUES('E1100','8','Little Benjamin is leading,<br/>Then great Judah''s company:<br/>Son of sorrow at God''s right hand,<br/>Lion with the scepter see.<br/>Zebulun and Naphtali<br/>Make the joyful tidings fly:<br/>Hallelujah, hallelujah!<br/>Hallelujah! Amen!<br/>',NULL,5714,5714);
INSERT INTO stanza VALUES('E1100','9','Saints, thy strength has been commanded<br/>From the temple glorious;<br/>Still we pray that God may strengthen<br/>All that He has wrought for us.<br/>Higher yet our praises shall rise<br/>Till the utmost earth replies:<br/>Hallelujah, hallelujah!<br/>Hallelujah! Amen!<br/>',NULL,5715,5715);
INSERT INTO stanza VALUES('E1101','1','Lo, the kingdom of the world is now<br/>the kingdom of the Lord!<br/>O what joy to all the saints does<br/>His eternal reign afford!<br/>Let us swell the mighty chorus of<br/>His praise in one accord —<br/>The victory is won!<br/>',NULL,5716,5716);
INSERT INTO stanza VALUES('E1101','chorus','Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>The victory is won!<br/>',NULL,5717,5717);
INSERT INTO stanza VALUES('E1101','2','That great dragon, the old serpent called the<br/>devil, down is cast;<br/>Satan and his fallen angels'' long deceiving<br/>days are past!<br/>Now our praises like a thunder through the<br/>universe shall blast —<br/>The victory is won!<br/>',NULL,5718,5718);
INSERT INTO stanza VALUES('E1101','3','Now is come salvation, power, and the<br/>kingdom of our God;<br/>The accuser of the brethren underneath our feet is trod!<br/>The authority of Christ is now the church''s<br/>ruling rod —<br/>The victory is won!<br/>',NULL,5719,5719);
INSERT INTO stanza VALUES('E1101','4','By the Lamb''s redeeming blood th'' accuser<br/>we have overcome;<br/>By our word of testimony, all declaring,<br/>"It is done!"<br/>Unto death, our souls not loving — all the<br/>glory to the Son!<br/>The victory is won!<br/>',NULL,5720,5720);
INSERT INTO stanza VALUES('E1101','5','Oh, but brothers, sisters, listen to another<br/>mighty voice,<br/>"Babylon is fallen, fallen" — what a reason to<br/>rejoice!<br/>O how blest that coming out from her was<br/>our eternal choice —<br/>The victory is won!<br/>',NULL,5721,5721);
INSERT INTO stanza VALUES('E1101','6','She''s the mother of the harlots, Myst''ry,<br/>Babylon the Great!<br/>O how all her evil fornication we have<br/>learned to hate!<br/>But our God has doubly judged her — this<br/>our spirits doth elate.<br/>The victory is won!<br/>',NULL,5722,5722);
INSERT INTO stanza VALUES('E1101','7','Hallelujah! Glory, power to the Lord our<br/>God belong!<br/>True and righteous are His judgments on the<br/>harlot for her wrong!<br/>See, her smoke is rising! Echo hallelujah in<br/>your song —<br/>The victory is won!<br/>',NULL,5723,5723);
INSERT INTO stanza VALUES('E1101','8','"Praise our God now, all ye servants, small<br/>and great," His voice constrains.<br/>As the sound of many waters, we will<br/>thunder our refrains:<br/>Hallelujah, hallelujah, for the Lord Almighty<br/>reigns!<br/>The victory is won!<br/>',NULL,5724,5724);
INSERT INTO stanza VALUES('E1101','9','Now rejoice and be exceeding glad! What<br/>glory is displayed!<br/>For the marriage of the Lamb, the wife all<br/>ready now is made!<br/>In fine linen, bright and pure, ''twas granted<br/>her to be arrayed —<br/>The victory is won!<br/>',NULL,5725,5725);
INSERT INTO stanza VALUES('E1101','10','Now the devil''s in the lake of fire, for John<br/>has seen him there;<br/>Hallelujah, never more need we his<br/>provocations bear!<br/>What a triumph for the saints his judgment<br/>boldly to declare —<br/>The victory is won!<br/>',NULL,5726,5726);
INSERT INTO stanza VALUES('E1101','11','Now behold the greatest wonder — New<br/>Jerusalem descend!<br/>She''s the building of the Triune God with<br/>man — a perfect blend!<br/>She''s the Bride, prepared, adorned for<br/>Christ — of all God''s work, the end!<br/>The victory is won!<br/>',NULL,5727,5727);
INSERT INTO stanza VALUES('E1101','12','It''s the tabernacle of our God, His dwelling<br/>place with men;<br/>In His holiness and glory He''s expressed<br/>through all of them.<br/>"It is done!" O brothers, see it! See the New<br/>Jerusalem!<br/>The victory is won!<br/>',NULL,5728,5728);
INSERT INTO stanza VALUES('E1101','chorus','Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>The victory is won!<br/>',NULL,5729,5729);
INSERT INTO stanza VALUES('E1102','1','The Lord said unto my Lord,<br/>"Sit Thou at My right hand;<br/>Thy foes shall be Thy footstool,<br/>Upon them Thou shalt stand."<br/>The scepter of Thy strength shall<br/>The Lord from Zion send<br/>To rule o''er all the nations<br/>Forever ''til the end.<br/>',NULL,5730,5730);
INSERT INTO stanza VALUES('E1102','2','A voluntary offering,<br/>The young ones are to Thee;<br/>In consecration''s splendor<br/>How beautiful to see!<br/>For as the dew of morning<br/>Refreshes all the land —<br/>The young ones given to Thee<br/>Are precious in Thy hand.<br/>',NULL,5731,5731);
INSERT INTO stanza VALUES('E1102','3','The Lord hath sworn forever<br/>And never will turn back,<br/>"Thou art a priest forever,<br/>As was Melchizedek."<br/>Oh, Thou hast no beginning<br/>Of days; of life: no end!<br/>And on Thine intercession<br/>We ever do depend.<br/>',NULL,5732,5732);
INSERT INTO stanza VALUES('E1102','4','The Lord is at Thy right hand<br/>And in His day of wrath<br/>He''ll strike through rulers, judging<br/>The nations in His path.<br/>While riding on to triumph<br/>He''ll drink of us, the stream,<br/>His head uplifted, strengthened,<br/>The whole earth to redeem.<br/>',NULL,5733,5733);
INSERT INTO stanza VALUES('E1102','5','Oh Lord, Thou art ascended<br/>To God''s right hand to sit;<br/>As Head o''er all things, to Thee<br/>God doth Thy foes commit.<br/>Our King — for us Thou reignest,<br/>Our Priest — we are supplied,<br/>Our all we give unto Thee,<br/>Thou Conqueror glorified.<br/>',NULL,5734,5734);
INSERT INTO stanza VALUES('E1103','1','What He is: He''s the Father.<br/>He''s the everlasting Father.<br/>He''s the firstborn of creation.<br/>He''s the One who lives inside of me.<br/>He''s the Father! Wonderful!<br/>',NULL,5735,5735);
INSERT INTO stanza VALUES('E1103','2','What He is: He''s the river.<br/>He is the mighty flowing river.<br/>He waters me in a desert land.<br/>He''s my hiding place; He is our man.<br/>He''s the river! Wonderful!<br/>',NULL,5736,5736);
INSERT INTO stanza VALUES('E1103','3','What He is: He''s the vine tree.<br/>He''s the branch, the root of Jesse.<br/>He''s the tree of life: we have the right<br/>To eat of Him and have His life.<br/>He''s the vine tree! Wonderful!<br/>',NULL,5737,5737);
INSERT INTO stanza VALUES('E1103','4','What He is: He''s the shepherd.<br/>He''s the lamb of God, the he-goat.<br/>We rest and feed in the pasture land.<br/>We strike the blood and eat the lamb.<br/>He''s the shepherd! Wonderful!<br/>',NULL,5738,5738);
INSERT INTO stanza VALUES('E1103','5','What He is: He''s the Spirit.<br/>He''s the all-inclusive Spirit.<br/>He''s our everything; He''s our all in all.<br/>He gives life to us whene''er we call.<br/>He''s the Spirit! Wonderful!<br/>',NULL,5739,5739);
INSERT INTO stanza VALUES('E1103','6','What He is: He''s a Person.<br/>He''s a real and living person.<br/>He is living now inside of us.<br/>This Person is so glorious.<br/>He''s a Person! Wonderful!<br/>',NULL,5740,5740);
INSERT INTO stanza VALUES('E1103','7','What He is: He''s the Body;<br/>He''s the fulness of the Godhead,<br/>He''s the center of the Father''s plan,<br/>Christ and the church, the one new man.<br/>He is wonderful, wonderful.<br/>',NULL,5741,5741);
INSERT INTO stanza VALUES('E1103','chorus','He is wonderful, wonderful.<br/>He is wonderful, wonderful.<br/>',NULL,5742,5742);
INSERT INTO stanza VALUES('E1104','1','Lord, Thou art our peace offering;<br/>We lay our hands on Thee.<br/>We''re one with Thee, Lord Jesus,<br/>In fact and practically.<br/>Here in the tent of meeting<br/>We offer Thee to God<br/>And with the Father feasting<br/>Enjoy Thee as our food.<br/>',NULL,5743,5743);
INSERT INTO stanza VALUES('E1104','chorus','Christ is our peace! Christ is our peace!<br/>We praise Thee, blessed Lord!<br/>Our peace with God, our peace with man<br/>Have fully been restored.<br/>',NULL,5744,5744);
INSERT INTO stanza VALUES('E1104','2','O what a peace it gives us<br/>To see the sprinkled blood.<br/>The blood of our peace offering<br/>Has brought us peace with God.<br/>With boldness we''re proclaiming —<br/>Now hear this, enemy —<br/>"Peace by the blood of Jesus!"<br/>This is our victory.<br/>',NULL,5745,5745);
INSERT INTO stanza VALUES('E1104','3','Based on the burnt oblation<br/>And the meal offering too,<br/>We now may offer Jesus<br/>As our peace offering true.<br/>The more we eat and drink Him<br/>In His humanity,<br/>The more we may enjoy Him<br/>While feasting corporately.<br/>',NULL,5746,5746);
INSERT INTO stanza VALUES('E1104','chorus','What fellowship, what fellowship<br/>With God and man we share!<br/>O what a joy, O what a feast<br/>With all God''s people here.<br/>',NULL,5747,5747);
INSERT INTO stanza VALUES('E1104','4','Here God enjoys His portion —<br/>''Tis inward, hidden, sweet —<br/>And all the priestly family<br/>May here the wave breast eat.<br/>The offering priest-how precious —<br/>May of the best partake:<br/>He gets the right heave shoulder<br/>And one unleavened cake.<br/>',NULL,5748,5748);
INSERT INTO stanza VALUES('E1104','5','How sweet to eat the wave breast,<br/>The all-embracing love<br/>Of Christ in resurrection!<br/>It sets us all above.<br/>What strength to eat the shoulder<br/>Of the ascended One<br/>And with the cake be nourished<br/>To walk as He has done.<br/>',NULL,5749,5749);
INSERT INTO stanza VALUES('E1104','6','With all the cleansed ones feasting,<br/>How rich the Christ we eat!<br/>Oh, this is true communion,<br/>The only way to meet.<br/>We bring our full thanksgiving<br/>And e''en would make a vow —<br/>We''re for the Lord''s recovery<br/>As He is for us now.<br/>',NULL,5750,5750);
INSERT INTO stanza VALUES('E1105','1','Lo, the table spread before us<br/>With the bread and with the wine:<br/>Lo, the Savior waiting for us,<br/>Bidding us to come and dine.<br/>"Come and dine," the Lord is calling,<br/>"Sup with Me and I with thee";<br/>He''s prepared for us this table —<br/>Let us feast abundantly.<br/>',NULL,5751,5751);
INSERT INTO stanza VALUES('E1105','2','We are feasting with our Savior,<br/>He with us and we with Him;<br/>Hallelujah, hallelujah!<br/>Feast of feasts that ne''er will end!<br/>Eating, drinking with Thyself, Lord,<br/>We are wholly satisfied.<br/>Taste we of that glorious banquet<br/>Thou wilt share with us, Thy Bride.<br/>',NULL,5752,5752);
INSERT INTO stanza VALUES('E1106','1','We gather together to eat the Lord''s supper:<br/>By eating and drinking, our oneness we show.<br/>His presence possessing, our oneness confessing,<br/>''Tis thus we eat and drink, and His blessing we know.<br/>',NULL,5753,5753);
INSERT INTO stanza VALUES('E1106','2','We''re eating the bread of His body once broken<br/>As now we''re enjoying His Body made one:<br/>One loaf on the table — one Body, we''re able<br/>To testify to all that the Lord''s made us one.<br/>',NULL,5754,5754);
INSERT INTO stanza VALUES('E1106','3','We also are drinking the cup of His blessing,<br/>The church''s true fellowship of the Lord''s blood;<br/>Redeemed by believing, all saints we''re receiving,<br/>All those who through redemption have come unto God.<br/>',NULL,5755,5755);
INSERT INTO stanza VALUES('E1106','4','Oh, what can we say now except "Hallelujah!"<br/>For such a reality given to us.<br/>Thy blood we''re employing, Thy Body enjoying;<br/>Thus Thou wilt have the church for Thyself glorious.<br/>',NULL,5756,5756);
INSERT INTO stanza VALUES('E1107','1','We''re gathered here, O Lord, as Thy one Body:<br/>Though we be many, yet we all are one.<br/>We share Thy life and own that we are members,<br/>And thus within, in life we all are one.<br/>',NULL,5757,5757);
INSERT INTO stanza VALUES('E1107','chorus','There is one Body in this universe,<br/>And we express it here on earth;<br/>We stand as one in each locality<br/>For all to see, for all to see.<br/>',NULL,5758,5758);
INSERT INTO stanza VALUES('E1107','2','There is one loaf, the symbol of Thy body:<br/>''Twas broken so that all the saints may share.<br/>We eat this bread and, as we are partaking,<br/>Our actual oneness with all saints declare.<br/>',NULL,5759,5759);
INSERT INTO stanza VALUES('E1107','3','One bread, one cup are now upon the table,<br/>Showing that we can be naught else but one.<br/>Christ has redeemed us, made us His own Body:<br/>What can we say but, "Amen, Lord, we''re one!"<br/>',NULL,5760,5760);
INSERT INTO stanza VALUES('E1107','4','We stand as one, and cannot be divided,<br/>Because our oneness is of Christ alone.<br/>We eat as one: one loaf, one cup partaking,<br/>And thus our oneness visibly is shown.<br/>',NULL,5761,5761);
INSERT INTO stanza VALUES('E1107','5','Oh, what a joy to have this blessed oneness!<br/>We sense that Thou, O Lord, art satisfied;<br/>And we too share this blissful satisfaction —<br/>Sweet foretaste of the Bridegroom with His Bride.<br/>',NULL,5762,5762);
INSERT INTO stanza VALUES('E1108','1','Eat the bread, ye people of the Lord:<br/>Praise His name, for He has made us one.<br/>Now we come to eat in one accord<br/>As the church which He has made His own.<br/>',NULL,5763,5763);
INSERT INTO stanza VALUES('E1108','chorus','Eat the bread and drink the wine, ye saints!<br/>We are one in Him fore''er.<br/>Stand in oneness on the local ground,<br/>Eat and drink in oneness there!<br/>',NULL,5764,5764);
INSERT INTO stanza VALUES('E1108','2','Drink the wine, ye people of the Lord:<br/>We''re the church His precious blood has bought.<br/>We''re redeemed to be in one accord —<br/>This the goal for which He long has sought.<br/>',NULL,5765,5765);
INSERT INTO stanza VALUES('E1108','3','Stand as one, ye people of the Lord:<br/>Not as individual grains are we —<br/>We are one, we''re blent in one accord<br/>As a loaf in each locality.<br/>',NULL,5766,5766);
INSERT INTO stanza VALUES('E1108','4','We are one as people of the Lord;<br/>We declare that we are really one!<br/>Not just word, but life in one accord<br/>Testify what God in us hath done.<br/>',NULL,5767,5767);
INSERT INTO stanza VALUES('E1108','5','Eat the bread, ye people of the Lord:<br/>Praise His name, for He has made us one.<br/>Now we come to eat in one accord<br/>As the church which He has made His own.<br/>',NULL,5768,5768);
INSERT INTO stanza VALUES('E1108','end-note','(Do not repeat the chorus after last verse)<br/>',NULL,5769,5769);
INSERT INTO stanza VALUES('E1109','1','Take, drink this cup, His blood,<br/>Redemption of our God.<br/>The peace which Christ has made,<br/>Is in this cup displayed.<br/>We fellowship now with the Son:<br/>On Calvary the work was done:<br/>The way is clear, now all can come!<br/>',NULL,5770,5770);
INSERT INTO stanza VALUES('E1109','2','Take, drink this cup, each one,<br/>His death show till He come.<br/>Eat, drink, display this feast:<br/>God in the Lamb released!<br/>Around the table, sup and dine;<br/>We eat the bread and drink the wine.<br/>All blessing in this cup we find.<br/>',NULL,5771,5771);
INSERT INTO stanza VALUES('E1109','3','No blood of cow or goat<br/>Could give us any hope.<br/>Our sins would all remain<br/>Still year by year the same.<br/>A God-man, sinless, He must find —<br/>No other offering of His kind,<br/>A spotless lamb for all mankind.<br/>',NULL,5772,5772);
INSERT INTO stanza VALUES('E1109','4','Come! Now enjoy His blood.<br/>What access this to God!<br/>Here wondrous cleansing power<br/>Flows to us, hour by hour.<br/>One sacrifice for all was made,<br/>And peace our conscience does pervade.<br/>Redemption''s price is fully paid!<br/>',NULL,5773,5773);
INSERT INTO stanza VALUES('E1109','5','Redeemer! Savior! King!<br/>Of Thy dear blood we sing,<br/>For in it now we see<br/>Thy mercy, boundless, free.<br/>This cup, our portion blessed of God,<br/>Is of the cov''nant in Thy blood —<br/>Dear, precious, precious, priceless blood!<br/>',NULL,5774,5774);
INSERT INTO stanza VALUES('E1110','1','O Jesus Lord, when present at Thy table,<br/>And on the bread and on the wine we gaze;<br/>We praise Thee, Lord, that Thou as food art able<br/>To be enjoyed by man in many ways.<br/>',NULL,5775,5775);
INSERT INTO stanza VALUES('E1110','chorus','So all our being sings in praise to Thee,<br/>How small Thou art, how small Thou art!<br/>And Thee we''ll eat through all eternity;<br/>How small Thou art, how small Thou art!<br/>',NULL,5776,5776);
INSERT INTO stanza VALUES('E1110','2','O what a shame — when Christ with all His riches,<br/>Has come into the world, life to supply —<br/>That man would live, not by Him, but by teachings,<br/>So powerless these riches to apply.<br/>',NULL,5777,5777);
INSERT INTO stanza VALUES('E1110','chorus','But all we need to do is eat the Lord;<br/>He''s marvelous, He''s wonderful!<br/>And as we eat, we''re inwardly restored;<br/>Christ grows in us, grows to the full.<br/>',NULL,5778,5778);
INSERT INTO stanza VALUES('E1110','3','O Jesus Christ, Thou camest not to mankind<br/>To be a king, to rule us outwardly.<br/>But Thou hast come as food to satisfy us,<br/>And by Thy life to guide us inwardly.<br/>(1st Chorus)<br/>',NULL,5779,5779);
INSERT INTO stanza VALUES('E1110','4','We praise Thee, Lord, for all Thy glorious grandeur,<br/>For all Thy strength and majesty replete;<br/>And yet, O Lord, what special thanks we give Thee,<br/>That all Thou art is small enough to eat.<br/>(1st Chorus)<br/>',NULL,5780,5780);
INSERT INTO stanza VALUES('E1111','1','Gathered at Thy table, Lord;<br/>Here the bread and wine are spread.<br/>Thou, our High Priest, present here;<br/>We, by Thee, are richly fed.<br/>Thou, Lord, our Melchisedec —<br/>We, the ones You come to feed;<br/>God to us to minister,<br/>Rich supply to us indeed.<br/>',NULL,5781,5781);
INSERT INTO stanza VALUES('E1111','2','From the slaughter of the kings<br/>Abram did return one night,<br/>O''er the foe victorious,<br/>With the spoils of the fight.<br/>On the way this One he met,<br/>Who for him did intercede;<br/>King of Righteousness and Peace<br/>Meeting Abram in his need.<br/>',NULL,5782,5782);
INSERT INTO stanza VALUES('E1111','3','We too, Lord, the kings have fought<br/>In the battle all day long;<br/>By Thine intercession, Lord,<br/>We are now victorious, strong.<br/>Round this table here we meet,<br/>We Thy church victorious,<br/>To enjoy the ministering<br/>Of the processed God to us.<br/>',NULL,5783,5783);
INSERT INTO stanza VALUES('E1111','4','We''re not sinners, miserable;<br/>All our sins are history!<br/>Now to us, the fighters true,<br/>Is Thy priestly ministry.<br/>Gathered in thanksgiving, Lord,<br/>Now our hearts to Thee we raise;<br/>To our great Melchisedec,<br/>Render we our highest praise!<br/>',NULL,5784,5784);
INSERT INTO stanza VALUES('E1112','1','Oh, how glorious is Thy table, Lord,<br/>Thou, the man, our Host, presiding,<br/>In Thy house, Thy home, abiding;<br/>Oh, how glorious is Thy table, Lord!<br/>',NULL,5785,5785);
INSERT INTO stanza VALUES('E1112','chorus','Hallelujah! Hallelujah!<br/>Hallelujah for this feast!<br/>Hallelujah! Hallelujah!<br/>Oh, how glorious is Thy table, Lord!<br/>',NULL,5786,5786);
INSERT INTO stanza VALUES('E1112','2','How enjoyable Thy table, Lord,<br/>As we fellowship around it,<br/>Hallelujah, we have found it,<br/>How enjoyable Thy table, Lord!<br/>',NULL,5787,5787);
INSERT INTO stanza VALUES('E1112','3','Oh, how precious is Thy table, Lord —<br/>Bread and wine Thy death announcing;<br/>Here our soul-life we''re renouncing,<br/>By partaking of Thy table, Lord.<br/>',NULL,5788,5788);
INSERT INTO stanza VALUES('E1112','4','How significant Thy table, Lord —<br/>We Thy Body in the loaf seen,<br/>Object of Thy love bespeaking;<br/>How significant Thy table, Lord!<br/>',NULL,5789,5789);
INSERT INTO stanza VALUES('E1112','5','How refreshing is Thy table, Lord —<br/>So completely satisfying,<br/>Day by day our need supplying;<br/>How refreshing is Thy table, Lord.<br/>',NULL,5790,5790);
INSERT INTO stanza VALUES('E1112','6','How encouraging Thy table, Lord —<br/>"Till He come," its promise giving<br/>Hope, to fill our daily living;<br/>How encouraging Thy table, Lord!<br/>',NULL,5791,5791);
INSERT INTO stanza VALUES('E1113','1','Now the Triune God has come to dwell within<br/>As the wonderful Spirit in us.<br/>We are mingled with the Lord, we''re one with Him<br/>As the life-giving Spirit in us.<br/>',NULL,5792,5792);
INSERT INTO stanza VALUES('E1113','chorus','Oh, He''s the wonderful Spirit in us,<br/>He''s the wonderful Spirit in us!<br/>God, is in the Son, the Son''s the Spirit now —<br/>He''s the wonderful Spirit in us!<br/>',NULL,5793,5793);
INSERT INTO stanza VALUES('E1113','2','"Abba Father" is the cry from deep within<br/>From the wonderful Spirit in us.<br/>''Tis the Spirit of the Son who cries to Him<br/>As the life-giving Spirit in us.<br/>',NULL,5794,5794);
INSERT INTO stanza VALUES('E1113','3','Jesus Christ the Lord is living now in us<br/>As the wonderful Spirit within.<br/>He has been transfigured, we enjoy Him thus,<br/>As the life-giving Spirit within.<br/>',NULL,5795,5795);
INSERT INTO stanza VALUES('E1113','4','Now the Spirit of reality is here<br/>As the wonderful Spirit within.<br/>Now the things of Christ are all so real and clear<br/>By the life-giving Spirit within.<br/>',NULL,5796,5796);
INSERT INTO stanza VALUES('E1113','5','We will all stir up this gift that''s deep within<br/>As the wonderful Spirit in us.<br/>When we call "Lord Jesus" how our spirits spring<br/>With this life-giving Spirit in us!<br/>',NULL,5797,5797);
INSERT INTO stanza VALUES('E1114','1','The Spirit today is the air that we breathe;<br/>Our spirits rejoice in this living inflow.<br/>For just as our body the breath does receive,<br/>So also in spirit to live it is so.<br/>',NULL,5798,5798);
INSERT INTO stanza VALUES('E1114','2','The Spirit today is the air that we breathe;<br/>What thing more important than breathing to do?<br/>For breathing each moment, new life we receive,<br/>And God''s living freshness is constant and new.<br/>',NULL,5799,5799);
INSERT INTO stanza VALUES('E1114','3','For God has been processed, as air now, He''s free;<br/>This life-giving pneuma is all that we need.<br/>He''s rich and abundant, so plentiful, He,<br/>In spirit to walk is to breath Him indeed.<br/>',NULL,5800,5800);
INSERT INTO stanza VALUES('E1114','4','O, say, aren''t you glad that the Spirit''s outpoured<br/>And God, fully processed, is flowing in us?<br/>So freely we''re breathing this life-giving Lord,<br/>And breathing, receiving His life, glorious!<br/>',NULL,5801,5801);
INSERT INTO stanza VALUES('E1115','1','We have come, we have come to the house of God;<br/>We have come to the house, whence outflows the flood.<br/>On the right, day and night, constant is its flow,<br/>Watering us and causing fruits of life to grow.<br/>',NULL,5802,5802);
INSERT INTO stanza VALUES('E1115','2','From the house, from the house flows this living stream,<br/>From the house, to the earth, with the life supreme.<br/>Yet more deep, Lord, we seek that the flow may be;<br/>Thus we must be measured and possessed by Thee.<br/>',NULL,5803,5803);
INSERT INTO stanza VALUES('E1115','3','Measure us, measure us, measure every day;<br/>Measure us, measure us, measure all the way,<br/>Till we know that the flow is a mighty flood,<br/>Sweeping over all the earth for Christ the Lord.<br/>',NULL,5804,5804);
INSERT INTO stanza VALUES('E1115','4','Take us through, take us through, take us through the flow;<br/>Take us through, through and through, everywhere we go.<br/>Flow increase, never cease, till we swim in Thee,<br/>Till we are immersed in God eternally.<br/>',NULL,5805,5805);
INSERT INTO stanza VALUES('E1115','5','All shall live, all shall live where the river comes;<br/>All shall live, really live, everywhere it runs.<br/>Let the fount from this mount life abundant bring,<br/>Till the deserts of the earth with churches spring!<br/>',NULL,5806,5806);
INSERT INTO stanza VALUES('E1116','1','Pure myrrh and cinnamon,<br/>Calamus and cassia —<br/>These are Thy elements,<br/>Jesus my Lord!<br/>In olive oil they''re blent<br/>In wondrous measurement —<br/>O what an ointment this,<br/>Anointing us!<br/>',NULL,5807,5807);
INSERT INTO stanza VALUES('E1116','chorus','Four-in-one mingled,<br/>Compounded Spirit,<br/>Sweet with Christ''s suffering death,<br/>Full of the fragrance<br/>Of resurrection —<br/>O what an ointment flows<br/>In spirit, Lord!<br/>',NULL,5808,5808);
INSERT INTO stanza VALUES('E1116','2','Stacte and onycha,<br/>Galbanum and frankincense —<br/>These are Thy elements,<br/>Jesus my Lord!<br/>Stacte doth sons produce,<br/>Onycha from sin doth loose,<br/>Galbanum all death repels,<br/>In spirit, Lord.<br/>',NULL,5809,5809);
INSERT INTO stanza VALUES('E1116','chorus','Equal proportion,<br/>In resurrection;<br/>Seasoned with salt are they.<br/>Ground into powder fine,<br/>Consumed with fire divine —<br/>O what an incense this,<br/>Jesus my Lord!<br/>',NULL,5810,5810);
INSERT INTO stanza VALUES('E1116','3','Ointment is Christ for us,<br/>Exceeding glorious!<br/>Incense is Christ for God,<br/>Wholly for Him,<br/>Ointment flows down to us,<br/>Christ is our portion thus;<br/>Incense ascends to God,<br/>Fragrant to Him.<br/>',NULL,5811,5811);
INSERT INTO stanza VALUES('E1116','chorus','''Tis by th'' anointing<br/>Christ we experience<br/>And then the incense burn.<br/>Christ in our prayer and praise —<br/>O what a Christ we raise<br/>From our experience,<br/>Precious to God.<br/>',NULL,5812,5812);
INSERT INTO stanza VALUES('E1117','1','We praise Thee, O God,<br/>For the Spirit of Christ<br/>Who has come to indwell us<br/>And be all our life.<br/>Hallelujah! What a Spirit!<br/>Hallelujah! Within!<br/>Hallelujah! Life abundant<br/>That never shall end!<br/>',NULL,5813,5813);
INSERT INTO stanza VALUES('E1117','2','In spirit we sing<br/>Of the One who has come<br/>As the life-giving Spirit<br/>With us to be one.<br/>Hallelujah! This is Jesus,<br/>Hallelujah! Still more,<br/>Hallelujah! He''s the Spirit,<br/>Our life evermore.<br/>',NULL,5814,5814);
INSERT INTO stanza VALUES('E1117','3','In spirit reborn,<br/>We''re being transformed,<br/>And to God''s Son completely<br/>We''ll soon be conformed.<br/>Hallelujah! Life imparting,<br/>Hallelujah! Transformed,<br/>Hallelujah! Soon transfigured<br/>And to Him conformed!<br/>',NULL,5815,5815);
INSERT INTO stanza VALUES('E1117','4','Conformed we will be<br/>As in spirit we feed<br/>On the life of the One<br/>Who knows all that we need.<br/>Hallelujah! Full salvation!<br/>Hallelujah! Our prize!<br/>Hallelujah! So sufficient<br/>For all of our lives.<br/>',NULL,5816,5816);
INSERT INTO stanza VALUES('E1118','1','Th'' anointing''s here! The Lord is moving now in us;<br/>The ointment dear to us has been applied.<br/>His blood prevails! It gives to us the fellowship,<br/>And now we have the living flow of life.<br/>',NULL,5817,5817);
INSERT INTO stanza VALUES('E1118','chorus','Th'' anointing''s here! O Christian brothers<br/>Th'' anointing''s here! We have believed.<br/>Within our spirit, the Spirit''s moving,<br/>And this from Him we have received.<br/>','Sisters sing',5818,5818);
INSERT INTO stanza VALUES('E1118','chorus','Th'' anointing''s here! O Christian sisters,<br/>The flow within will never cease.<br/>As He anoints us, we are abiding —<br/>O Hallelujah! Life and peace!<br/>','Brothers sing',5819,5819);
INSERT INTO stanza VALUES('E1118','2','Th'' anointing''s here! ''Tis God Himself that<br/>blends with us,<br/>And now the two are mingled into one.<br/>And hour by hour we live, and move, and<br/>have our life<br/>In God Himself — the Spirit through the Son.<br/>',NULL,5820,5820);
INSERT INTO stanza VALUES('E1118','3','Th'' anointing''s here! It teaches us in everything;<br/>The sense of life we always have within.<br/>Obey this sense, and you will know what you must do,<br/>And live by Life — Yes, clear in everything.<br/>',NULL,5821,5821);
INSERT INTO stanza VALUES('E1119','1','In the Word of God I found it,<br/>Wonderful this Word to me;<br/>I need not man''s natural teaching,<br/>The anointing lives in me!<br/>',NULL,5822,5822);
INSERT INTO stanza VALUES('E1119','chorus','Yes, in my spirit now He is moving!<br/>Yes I have the anointing!<br/>God in me is flowing!<br/>Thank God, I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,5823,5823);
INSERT INTO stanza VALUES('E1119','2','Making Christ experiential,<br/>God at His pure Word I take;<br/>As the Spirit joined unto me,<br/>He cannot His promise break.<br/>',NULL,5824,5824);
INSERT INTO stanza VALUES('E1119','3','Based upon the blood that cleanses<br/>So that nothing stands between,<br/>Christ, the ointment, moves within me!<br/>For His move I''m made so clean.<br/>',NULL,5825,5825);
INSERT INTO stanza VALUES('E1119','4','God in Christ as life in Spirit<br/>Into my own spirit came!<br/>He the Holy One anoints me<br/>Till in spirit we''re the same.<br/>',NULL,5826,5826);
INSERT INTO stanza VALUES('E1119','5','God in Spirit; I can touch Him;<br/>In my spirit He''s the flow.<br/>Deeper, wider, richer, fuller —<br/>Oh, the very God I know!<br/>',NULL,5827,5827);
INSERT INTO stanza VALUES('E1119','6','As I heed "that same anointing"<br/>Ever to "abide in Him,"<br/>He is teaching, He is reaching,<br/>Even all my heart to win.<br/>',NULL,5828,5828);
INSERT INTO stanza VALUES('E1120','1','The Holy Spirit is the seal,<br/>The foretaste, earnest, and the pledge.<br/>He designates us as God''s own<br/>And guarantees our heritage.<br/>',NULL,5829,5829);
INSERT INTO stanza VALUES('E1120','2','''Twas after we believed in Christ,<br/>The word of truth, the gospel, heard,<br/>The Holy Spirit us did seal<br/>To show that we belong to God.<br/>',NULL,5830,5830);
INSERT INTO stanza VALUES('E1120','3','This Spirit as the living seal,<br/>To us God''s image now imparts;<br/>Conforming us unto the Son,<br/>He stamps His image in our hearts.<br/>',NULL,5831,5831);
INSERT INTO stanza VALUES('E1120','4','This Spirit also is the pledge,<br/>Our earnest and our foretaste true.<br/>He witnesses that we are sons,<br/>With God''s inheritance in view.<br/>',NULL,5832,5832);
INSERT INTO stanza VALUES('E1120','5','''Tis by this Spirit God does spread<br/>Into our mind, emotion, will;<br/>By sealing every inward part,<br/>He will our very being fill.<br/>',NULL,5833,5833);
INSERT INTO stanza VALUES('E1120','6','Oh, Lord, we would cooperate<br/>With all Thy Spirit''s inward move;<br/>That we''d become Thy masterpiece,<br/>Th'' eternal purpose thus to prove.<br/>',NULL,5834,5834);
INSERT INTO stanza VALUES('E1121','1','Praise the Lord, who firmly joined us<br/>Unto the Anointed One.<br/>Thus we all have been anointed<br/>With th'' anointing of the Son.<br/>',NULL,5835,5835);
INSERT INTO stanza VALUES('E1121','2','Now in Christ, in the anointing,<br/>We are the anointed ones.<br/>Oh, how blessed is this ointment<br/>Poured upon the many sons!<br/>',NULL,5836,5836);
INSERT INTO stanza VALUES('E1121','3','Hallelujah, the anointing<br/>Unto us God''s essence brings;<br/>It is now abiding in us,<br/>And it teaches us all things.<br/>',NULL,5837,5837);
INSERT INTO stanza VALUES('E1121','4','We''re the Lord''s peculiar treasure,<br/>Purchased by His precious blood.<br/>He has put His seal upon us,<br/>We are those marked out by God.<br/>',NULL,5838,5838);
INSERT INTO stanza VALUES('E1121','5','Day by day we''re under sealing,<br/>That we may His likeness share.<br/>By the impress of His Person<br/>We will Jesus'' image bear.<br/>',NULL,5839,5839);
INSERT INTO stanza VALUES('E1121','6','Now we have the pledge, the foretaste,<br/>Of the Christ we soon will see.<br/>We are longing for the full taste —<br/>God, our feast eternally.<br/>',NULL,5840,5840);
INSERT INTO stanza VALUES('E1121','7','God has wrought us for this purpose,<br/>Giving us the earnest here,<br/>Guarantee of full enjoyment<br/>Of our Lord Himself, so dear.<br/>',NULL,5841,5841);
INSERT INTO stanza VALUES('E1121','8','The anointing, seal, and earnest —<br/>In our spirit are all three.<br/>Such a wondrous, blest deposit<br/>God has given you and me.<br/>',NULL,5842,5842);
INSERT INTO stanza VALUES('E1122','1','"Seven Spirits" of our God —<br/>Lo, the age has now been turned<br/>To the Spirit with the Son.<br/>For the churches He''s concerned.<br/>',NULL,5843,5843);
INSERT INTO stanza VALUES('E1122','chorus','Come, O seven Spirits, come,<br/>Thy recovery work be done!<br/>Burn and search us thoroughly,<br/>All the churches are for Thee.<br/>Burn us, search us,<br/>All the churches are for Thee!<br/>',NULL,5844,5844);
INSERT INTO stanza VALUES('E1122','2','Sevenfold the Spirit is<br/>For the deadness of the church,<br/>That the saints may turn and live,<br/>That the Lord may burn and search.<br/>',NULL,5845,5845);
INSERT INTO stanza VALUES('E1122','3','Now the Spirit of our God<br/>Has become intensified:<br/>''Tis not one but sevenfold<br/>That the church may be supplied!<br/>',NULL,5846,5846);
INSERT INTO stanza VALUES('E1122','4','Now the seven Spirits are<br/>Seven lamps of burning fire,<br/>Not to teach us, but to burn,<br/>Satisfying God''s desire.<br/>',NULL,5847,5847);
INSERT INTO stanza VALUES('E1122','5','See the seven Spirits now —<br/>Seven piercing, searching eyes.<br/>In the church exposing us,<br/>All the church He purifies.<br/>',NULL,5848,5848);
INSERT INTO stanza VALUES('E1122','6','Seven Spirits doth the Lord<br/>For the churches now employ;<br/>All those in the local church<br/>May this Spirit now enjoy.<br/>',NULL,5849,5849);
INSERT INTO stanza VALUES('E1123','1','Of the Spirit, born of Spirit —<br/>This the source of Jesus is;<br/>Filled with Spirit, all of Spirit —<br/>This the essence truly His.<br/>In the Spirit, with the Spirit,<br/>As the Spirit Jesus came;<br/>Now the Lord is just that Spirit<br/>And in spirit we''re the same.<br/>',NULL,5850,5850);
INSERT INTO stanza VALUES('E1123','2','Baptized in the Holy Spirit,<br/>In the Spirit we''re immersed;<br/>All the church is born of Spirit,<br/>All religion is dispersed.<br/>In the Spirit, in the Spirit —<br/>Brothers, this is all we need,<br/>Now the church must be in Spirit,<br/>Not in teaching, form, or creed.<br/>',NULL,5851,5851);
INSERT INTO stanza VALUES('E1123','3','The communion of the Spirit<br/>Is the fellowship we share;<br/>All the brothers, all the sisters<br/>Only for the Spirit care.<br/>Now the Spirit in the churches<br/>Speaks to those who have an ear.<br/>Seven Spirits for the churches<br/>Are our blessed portion here.<br/>',NULL,5852,5852);
INSERT INTO stanza VALUES('E1123','4','"Come and drink the living water,"<br/>Say the Spirit and the Bride —<br/>Church and Spirit speak together,<br/>Utterly identified.<br/>Just according to the Spirit<br/>Must be our reality;<br/>Just the Spirit in the churches<br/>Is the Lord''s recovery.<br/>',NULL,5853,5853);
INSERT INTO stanza VALUES('E1124','1','What! Not sing of blood divine?<br/>What! Not tell to all mankind?<br/>What! Not speak to hearts unclean<br/>Of the precious living stream.<br/>',NULL,5854,5854);
INSERT INTO stanza VALUES('E1124','2','By this blood, God''s life released,<br/>Blood surpassing any beast''s;<br/>Perfect, spotless Lamb of God,<br/>Incorruptible His blood.<br/>',NULL,5855,5855);
INSERT INTO stanza VALUES('E1124','3','Voice it has, this holy blood;<br/>Pow''r possessed to speak with God;<br/>Speaks it for us at the throne<br/>With its glorious virtue shown.<br/>',NULL,5856,5856);
INSERT INTO stanza VALUES('E1124','4','Failure on our conscience is —<br/>Conscience means a "knowing this" —<br/>Causing us much grief and pain,<br/>Telling us of every stain.<br/>',NULL,5857,5857);
INSERT INTO stanza VALUES('E1124','5','All the while we''re unaware<br/>Of the blood''s effectual prayer.<br/>Jesus'' blood speaks of our case,<br/>That we might receive His grace!<br/>',NULL,5858,5858);
INSERT INTO stanza VALUES('E1124','6','We need not dead works to bring,<br/>Nor another offering.<br/>Nothing else could please our God,<br/>Heav''n is listening for His blood.<br/>',NULL,5859,5859);
INSERT INTO stanza VALUES('E1124','7','In His blood forgiveness shines;<br/>Oh, ''tis glorious to find!<br/>Israel just atonement knew,<br/>We have that and cleansing too.<br/>',NULL,5860,5860);
INSERT INTO stanza VALUES('E1124','8','Heart and mind are now at peace<br/>Rest! Our conscience has been reached.<br/>Never more we blush in shame,<br/>We are washed from every stain.<br/>',NULL,5861,5861);
INSERT INTO stanza VALUES('E1124','9','Hallelujah! Fathomless!<br/>All that''s in His blood for us!<br/>Sing we will, and sing we must;<br/>In His blood is all our trust!<br/>',NULL,5862,5862);
INSERT INTO stanza VALUES('E1125','1','Down at the cross where my Savior died,<br/>God''s righteous nature was satisfied;<br/>There to my sin was the blood applied,<br/>Glory to His name!<br/>',NULL,5863,5863);
INSERT INTO stanza VALUES('E1125','chorus','Glory to His name,<br/>Glory to His name;<br/>There to my sin was the blood applied,<br/>Glory to His name!<br/>',NULL,5864,5864);
INSERT INTO stanza VALUES('E1125','2','Saved from our sin at this fountain, we<br/>Fully enjoy our redemption free;<br/>This we''ll enjoy for eternity,<br/>Glory to His name!<br/>',NULL,5865,5865);
INSERT INTO stanza VALUES('E1125','3','Oh, precious fact, when my Savior died,<br/>Not only sin''s debt was satisfied;<br/>Life''s flowing fountain was opened wide!<br/>Glory to His name!<br/>',NULL,5866,5866);
INSERT INTO stanza VALUES('E1125','chorus','Glory to His name,<br/>Glory to His name;<br/>Life''s flowing fountain was opened wide!<br/>Glory to His name!<br/>',NULL,5867,5867);
INSERT INTO stanza VALUES('E1125','4','Now both redemption and life we share,<br/>Cleansed in His blood, we''re abiding there<br/>Drinking the water of life fore''er;<br/>Glory to His name!<br/>',NULL,5868,5868);
INSERT INTO stanza VALUES('E1126','1','O Jesus Lord, we come to Thee,<br/>Thy presence to enjoy;<br/>Our entrance now with boldness is,<br/>As we Thy blood employ.<br/>Not by our merit do we stand,<br/>Nor in our righteousness,<br/>Thy blood and righteousness we need;<br/>Their worth we now confess.<br/>',NULL,5869,5869);
INSERT INTO stanza VALUES('E1126','2','Thy judgments, Lord, we must admit,<br/>Are holy, righteous, fair.<br/>We own our sins as crimson are,<br/>We''ve no excuse to bear.<br/>We have no argument, no plea;<br/>No veil our sin can hide.<br/>But, praise Thee, Lord, Thy precious blood<br/>Is to our sin applied!<br/>',NULL,5870,5870);
INSERT INTO stanza VALUES('E1126','3','God has not overlooked our sin,<br/>But judged it once for all;<br/>His righteous fury, not on us,<br/>But on His Lamb did fall.<br/>A new and living way is made —<br/>We stand on legal ground;<br/>Our Surety and our Substitute<br/>Has pardon for us found.<br/>',NULL,5871,5871);
INSERT INTO stanza VALUES('E1126','4','O Jesus Lord, we worship Thee,<br/>Redemption now enjoy;<br/>Thy precious blood again we see,<br/>Its virtue now employ.<br/>Dear Lord, Thy mercy is so vast,<br/>Unlimited and free.<br/>Oh, Lamb of God, we''ll sing Thy praise,<br/>Through all eternity!<br/>',NULL,5872,5872);
INSERT INTO stanza VALUES('E1127','1','God has saved me from the world;<br/>I''ll never go back anymore.<br/>God has saved me from the world;<br/>I''ll never go back anymore.<br/>',NULL,5873,5873);
INSERT INTO stanza VALUES('E1127','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore;<br/>',NULL,5874,5874);
INSERT INTO stanza VALUES('E1127','2','I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>',NULL,5875,5875);
INSERT INTO stanza VALUES('E1127','3','Since I found the local church,<br/>I''ll never go back anymore.<br/>Since I found the local church,<br/>I''ll never go back anymore.<br/>',NULL,5876,5876);
INSERT INTO stanza VALUES('E1127','4','Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>',NULL,5877,5877);
INSERT INTO stanza VALUES('E1127','5','Christ is everything to me;<br/>I''ll never go back anymore.<br/>Christ is everything to me;<br/>I''ll never go back anymore.<br/>',NULL,5878,5878);
INSERT INTO stanza VALUES('E1127','6','Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>',NULL,5879,5879);
INSERT INTO stanza VALUES('E1127','7','I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>',NULL,5880,5880);
INSERT INTO stanza VALUES('E1128','1','We were held in bondage, toiling down in Egypt land,<br/>Glory to God, Hallelujah!<br/>But the God of Hebrews rescued us from Pharaoh''s hand,<br/>Glory to God, Hallelujah!<br/>',NULL,5881,5881);
INSERT INTO stanza VALUES('E1128','chorus','We will sing unto the Lord for His mighty victory,<br/>For the rider and the horse<br/>He has cast into the sea.<br/>Now the dwelling place of God on the<br/>earth will builded be,<br/>Glory to God, Hallelujah!<br/>',NULL,5882,5882);
INSERT INTO stanza VALUES('E1128','2','Now we''re on the other side, we''ll go back nevermore!<br/>Glory to God, Hallelujah!<br/>Look! Th'' Egyptians all are lying dead upon the shore!<br/>Glory to God, Hallelujah!<br/>',NULL,5883,5883);
INSERT INTO stanza VALUES('E1128','3','Brothers, sisters-Hallelujah! Through the sea we''ve crossed,<br/>Glory to God, Hallelujah!<br/>All the things that used to hold us are forever lost!<br/>Glory to God, Hallelujah!<br/>',NULL,5884,5884);
INSERT INTO stanza VALUES('E1128','4','We''re the Hebrews, now we''re standing on the sea of glass,<br/>Glory to God, Hallelujah!<br/>And we sing the song of Moses, everything we''ve passed,<br/>Glory to God, Hallelujah!<br/>',NULL,5885,5885);
INSERT INTO stanza VALUES('E1129','1','"So great a salvation," ye saints of the Lord,<br/>To us is revealed in His marvelous Word!<br/>Since all that He is and has done is for us,<br/>We''ll give earnest heed to this word glorious.<br/>',NULL,5886,5886);
INSERT INTO stanza VALUES('E1129','2','What He is of God and of Man as the Son,<br/>We now may enjoy since with Him we are one;<br/>Our High Priest and Captain — salvation is He!<br/>He''ll cause us to grow in His glory to be.<br/>',NULL,5887,5887);
INSERT INTO stanza VALUES('E1129','3','He''s washed all our sins, purified them fore''er;<br/>Tasted death on the cross, ended slavery there.<br/>He took on our nature, the devil has slain,<br/>And put you and I in His glorious train.<br/>',NULL,5888,5888);
INSERT INTO stanza VALUES('E1129','4','So great the extent of salvation to us —<br/>We''re partners of Christ in His plan glorious.<br/>He''ll bring us to glory and we''ll rule with Him,<br/>To the uttermost saved by His working within.<br/>',NULL,5889,5889);
INSERT INTO stanza VALUES('E1129','5','To such a salvation our heed we must give,<br/>Lest drifting away or neglecting we live,<br/>Christ now as our life, future ruling with Him,<br/>We''ll miss if we miss this salvation within.<br/>',NULL,5890,5890);
INSERT INTO stanza VALUES('E1129','6','"So great a salvation" is given to us<br/>That we may be made like our Lord glorious!<br/>By all that He is and by all He has done<br/>We''re brought into glory with God''s firstborn Son.<br/>',NULL,5891,5891);
INSERT INTO stanza VALUES('E1130','1','Sing praise to Christ Who lives in us,<br/>The God of our salvation;<br/>Who saves us by His life divine,<br/>And not by regulation;<br/>After we''ve worked — done all we can,<br/>His life has power to change a man:<br/>His life divine can change us.<br/>',NULL,5892,5892);
INSERT INTO stanza VALUES('E1130','2','He saves us to the uttermost<br/>By His life-giving power;<br/>Transfusing Himself into us,<br/>He saves us hour by hour.<br/>He saved the lost by coming in,<br/>He''s saving now from more than sin:<br/>He''s saving us to glory!<br/>',NULL,5893,5893);
INSERT INTO stanza VALUES('E1130','3','Our Lord was constituted priest<br/>To be a real life-giver;<br/>Life is the nature of this One<br/>Who can from self deliver:<br/>His life is indestructible,<br/>By it He saves us to the full:<br/>Praise God, He''s fully able!<br/>',NULL,5894,5894);
INSERT INTO stanza VALUES('E1130','4','His life is fully qualified<br/>To bring us through to glory;<br/>Were it not for His tested life,<br/>''Twould be another story:<br/>His life was fully tried on earth,<br/>To crucifixion from His birth:<br/>He passed through death and Hades.<br/>',NULL,5895,5895);
INSERT INTO stanza VALUES('E1130','5','He''s pledged to save us to the full,<br/>His life is operating;<br/>He''s doing everything for us<br/>''Tis all for our perfecting;<br/>Our life''s a failure at its best,<br/>Only His life can stand the test:<br/>His life brings full salvation!<br/>',NULL,5896,5896);
INSERT INTO stanza VALUES('E1130','6','He''s living now to intercede,<br/>Continuing forever;<br/>He undertakes into the age,<br/>His priesthood changes never;<br/>He always lives to intercede,<br/>Such a High Priest is what we need:<br/>He''s higher than the heavens.<br/>',NULL,5897,5897);
INSERT INTO stanza VALUES('E1130','7','Come forward now to God through Him,<br/>Ne''er shrink back to destruction;<br/>Come forward now to get the life,<br/>Which brings the proper function;<br/>Come forward now the life to take,<br/>By life His people us He''ll make,<br/>And swallow death forever.<br/>',NULL,5898,5898);
INSERT INTO stanza VALUES('E1131','1','In a low dungeon, hope we had none;<br/>Tried to believe, but faith didn''t come;<br/>God, our sky clearing, Jesus appearing,<br/>We by God were transfused!<br/>We by God were transfused!<br/>',NULL,5899,5899);
INSERT INTO stanza VALUES('E1131','chorus','Propitiation made by the blood,<br/>Jesus'' redemption bought us for God!<br/>No condemnation, justification!<br/>We have peace toward God!<br/>We have peace toward God!<br/>',NULL,5900,5900);
INSERT INTO stanza VALUES('E1131','2','Born into Adam, dying we were;<br/>We had a sickness no one could cure.<br/>God, His Son sending, old Adam ending;<br/>He is dead, we are free!<br/>He is dead, we are free!<br/>',NULL,5901,5901);
INSERT INTO stanza VALUES('E1131','3','Now we''re rejoicing, standing in grace,<br/>Oh hallelujah! Sin is erased!<br/>God, in us flowing, in our hearts growing,<br/>We are saved in His life!<br/>We are saved in His life!<br/>',NULL,5902,5902);
INSERT INTO stanza VALUES('E1132','1','Lord, teach us how to pray,<br/>Not as the nations do in vain,<br/>But turn us from our way,<br/>And cause us, Lord, to call on You each day —<br/>Lord Jesus, grow in us.<br/>',NULL,5903,5903);
INSERT INTO stanza VALUES('E1132','2','Lord, You''re the seed of life;<br/>You''ve sown Yourself into our heart,<br/>And now You have a start;<br/>So day by day more life to us impart —<br/>Lord Jesus, grow in us.<br/>',NULL,5904,5904);
INSERT INTO stanza VALUES('E1132','3','Lord Jesus, soften us;<br/>You know the source from which we came.<br/>By calling on Your name,<br/>Lord, let no earth unturned nor rocks remain —<br/>Lord Jesus, grow in us.<br/>',NULL,5905,5905);
INSERT INTO stanza VALUES('E1132','4','Lord, how Your light makes clear<br/>That we could not but e''er fail You;<br/>Yet there''s a message true,<br/>The seed of life within us will break through —<br/>Lord Jesus, grow in us.<br/>',NULL,5906,5906);
INSERT INTO stanza VALUES('E1132','5','Make us in spirit poor;<br/>Lord, take whate''er we think we know.<br/>We''ll open to life''s flow,<br/>And thus take in the life that makes us grow —<br/>Lord Jesus, grow in us.<br/>',NULL,5907,5907);
INSERT INTO stanza VALUES('E1132','6','Lord, make us pure in heart;<br/>For we''ll be not content until<br/>You all our being fill,<br/>O Lord, renew our mind, emotion, will —<br/>Lord Jesus, grow in us.<br/>',NULL,5908,5908);
INSERT INTO stanza VALUES('E1132','7','Yes, Lord, impress our heart,<br/>That we must take You in each day;<br/>The seed will have its way;<br/>Your growing brings the kingdom here to stay —<br/>Lord Jesus, grow in us.<br/>',NULL,5909,5909);
INSERT INTO stanza VALUES('E1132','8','Amen — The growth in life!<br/>There''s nothing that Your life can''t do;<br/>Our every part renew.<br/>We''ll make it, we''ll make it just by You.<br/>Lord Jesus, grow in us.<br/>Lord Jesus, grow in us.<br/>',NULL,5910,5910);
INSERT INTO stanza VALUES('E1133','1','O Father of glory, now grant unto me<br/>A spirit of wisdom, a spirit to see;<br/>O give unto me the full knowledge of Him,<br/>Enlight''ning the eyes of my heart deep within.<br/>',NULL,5911,5911);
INSERT INTO stanza VALUES('E1133','2','O show me that Christ is the hope of Thy call —<br/>O glorious hope, Christ will fill all in all!<br/>Reveal Him-the riches of glory in us —<br/>As God''s own inheritance. How glorious!<br/>',NULL,5912,5912);
INSERT INTO stanza VALUES('E1133','3','O God of our Lord Jesus, let me perceive<br/>Th'' exceeding great pow''r unto us who believe,<br/>The power that raised Christ, Thy Son, from the dead<br/>And made Him o''er all, to His Body, the Head.<br/>',NULL,5913,5913);
INSERT INTO stanza VALUES('E1133','4','O God, Thou hast wrought all this pow''r into Christ,<br/>Who now lives in me as my Person, my life.<br/>O grant revelation, dear Father, to see<br/>This transcending pow''r is a Person in me.<br/>',NULL,5914,5914);
INSERT INTO stanza VALUES('E1133','5','O Christ is the hope, He''s the glory and power;<br/>So Christ I must take as my Person each hour.<br/>Then in me such power will be exercised,<br/>My hope and God''s glory will be realized.<br/>',NULL,5915,5915);
INSERT INTO stanza VALUES('E1134','1','Oh, strengthen my spirit, Lord Jesus,<br/>Oh, strengthen my spirit, I pray;<br/>Oh, strengthen my spirit with power<br/>And spread to my heart today.<br/>',NULL,5916,5916);
INSERT INTO stanza VALUES('E1134','chorus','Into my heart, into my heart,<br/>Spread into my heart, Lord Jesus;<br/>Make home today and have Your way<br/>In all of my heart, Lord Jesus.<br/>',NULL,5917,5917);
INSERT INTO stanza VALUES('E1134','2','Spread into my heart, O Lord Jesus,<br/>Spread into my heart, I pray;<br/>Spread into my heart from my spirit,<br/>Spread into my heart today.<br/>',NULL,5918,5918);
INSERT INTO stanza VALUES('E1134','3','Make home in my heart, O Lord Jesus,<br/>Make home in my heart, I pray;<br/>That we may be filled with Your fullness,<br/>Make home in my heart today.<br/>',NULL,5919,5919);
INSERT INTO stanza VALUES('E1134','4','To Him who is able to do it<br/>Above all we think or say,<br/>We open our hearts wide and welcome<br/>Him into our heart today.<br/>',NULL,5920,5920);
INSERT INTO stanza VALUES('E1135','1','Oh, sanctify us, Lord; now add Thyself to us,<br/>In our experience, Thy Person spread in us,<br/>That in reality the church be glorious,<br/>O Lord, do add Thyself, we pray.<br/>',NULL,5921,5921);
INSERT INTO stanza VALUES('E1135','chorus','Oh, sanctify us, Lord, today;<br/>Lord Jesus, You''re the only way.<br/>We take Your Person, Lord;<br/>Oh, spread Yourself abroad.<br/>Oh, sanctify us, Lord, today.<br/>',NULL,5922,5922);
INSERT INTO stanza VALUES('E1135','2','Oh, purify us, Lord, by speaking in our heart;<br/>Thy living, spoken word this washing will impart.<br/>Increase Thy speaking, Lord, and cleanse<br/>our every part.<br/>Oh, purify us, Lord, we pray.<br/>',NULL,5923,5923);
INSERT INTO stanza VALUES('E1135','chorus','Oh, purify us, Lord, today;<br/>Wash all our natural life away.<br/>Speak now Thy words in us,<br/>And make us glorious.<br/>O Lord, do speak in us today.<br/>',NULL,5924,5924);
INSERT INTO stanza VALUES('E1135','3','O Lord, do nourish us; You are the food we need;<br/>As we are eating You, we''ll be transformed indeed;<br/>We''re fully satisfied as on Yourself we feed,<br/>So nourish us, O Lord, we pray.<br/>',NULL,5925,5925);
INSERT INTO stanza VALUES('E1135','chorus','O Lord, do nourish us today<br/>As all our self You wash away.<br/>Not only purify,<br/>But fill and satisfy;<br/>O Lord, do nourish us today.<br/>',NULL,5926,5926);
INSERT INTO stanza VALUES('E1135','4','O Lord, do cherish us, as on Thyself we feed;<br/>Warm us so tenderly and meet our every need.<br/>Our hardness soften, Lord, till we are Yours indeed;<br/>Oh, cherish us, dear Lord, we pray.<br/>',NULL,5927,5927);
INSERT INTO stanza VALUES('E1135','chorus','O Lord, do cherish us today,<br/>Until our coldness flees away.<br/>Oh, hold us close to Thee<br/>And cherish tenderly;<br/>O Lord, do cherish us today.<br/>',NULL,5928,5928);
INSERT INTO stanza VALUES('E1135','5','Lord, make us glorious, by all Your inner work,<br/>Not glory for ourselves, but glory for the church;<br/>That You may have Your Bride, thus ending<br/>all Your search.<br/>O Lord, do work on us, we pray.<br/>',NULL,5929,5929);
INSERT INTO stanza VALUES('E1135','chorus','O Lord, do work on us today!<br/>To form the church Your glorious way.<br/>Oh, spread Yourself in us<br/>Till we are glorious;<br/>Oh, make us glorious, Lord, today.<br/>',NULL,5930,5930);
INSERT INTO stanza VALUES('E1136','1','Oh, Lord grant us revelation,<br/>Grant us light and sight to see<br/>That as life, within our spirit,<br/>Thou art our reality;<br/>And that from within our spirit,<br/>Now You must possess each part<br/>Spreading out to all our being,<br/>Making home in all our heart.<br/>',NULL,5931,5931);
INSERT INTO stanza VALUES('E1136','2','It is not the outward action —<br/>Pure behavior, conduct good,<br/>Proper poise and perfect manners,<br/>Doing what we think we should;<br/>But it''s Christ, a living Person,<br/>Mingled thus with us within,<br/>Spreading into all our being,<br/>So that we might live by Him.<br/>',NULL,5932,5932);
INSERT INTO stanza VALUES('E1136','3','Oh, Lord, let our every action,<br/>Everything we do and say,<br/>Come from Thee alone, experienced<br/>In a real and inner way.<br/>We reject the empty teachings,<br/>Leave the methods and the strife.<br/>Let our only way of living<br/>Be the overflow of life!<br/>',NULL,5933,5933);
INSERT INTO stanza VALUES('E1136','4','Following the inner feeling,<br/>Living in the overflow,<br/>Moving in the rich anointing,<br/>Not by what we think or know,<br/>Nothing through intent or motive,<br/>Or with purpose duly done,<br/>But just following this feeling,<br/>Living by the living One!<br/>',NULL,5934,5934);
INSERT INTO stanza VALUES('E1136','5','Thus we''re sanctified completely,<br/>Saturated thoroughly;<br/>Not the old religious concept:<br/>Separated doctrinally.<br/>But ''tis Christ Himself within us,<br/>Added to our every part,<br/>All supplying, satisfying,<br/>Making home in all our heart.<br/>',NULL,5935,5935);
INSERT INTO stanza VALUES('E1137','1','His countenance angels can often behold,<br/>But ne''er taste His love in His grace;<br/>His saints, though they know of His pure boundless love,<br/>Have never yet once seen His face.<br/>His saints will before long His visage behold,<br/>E''en in His bright glory will share;<br/>But Mary, beholding His tears as He wept.<br/>Could touch His heart''s agony there.<br/>Could touch His heart''s agony there.<br/>',NULL,5936,5936);
INSERT INTO stanza VALUES('E1137','2','We''ll soon see the Lord, as He is, face to face,<br/>We''ll know Him as never before;<br/>But that touch today, healing our broken heart,<br/>In that day will be felt no more.<br/>That day, though our lips offer unceasing praise,<br/>No tears, then, nor prayers fervent burn;<br/>Nor is there the comfort received through much pain,<br/>Nor trust gained through trials to learn,<br/>Nor trust gained through trials to learn.<br/>',NULL,5937,5937);
INSERT INTO stanza VALUES('E1137','3','Exceeding in glory, that day we''ll be crowned,<br/>Yet there''ll be no cross to obey;<br/>The sweet fellowship of His suff''rings for us<br/>We only can share in today.<br/>Once we''ve that rest entered, no weariness then,<br/>Nor chance will remain to partake<br/>The trials nor the hardships, nor happiness lost,<br/>Nor suffering borne for His sake,<br/>Nor suffering borne for His sake.<br/>',NULL,5938,5938);
INSERT INTO stanza VALUES('E1137','4','Oh, chances to suffer for Him are so few,<br/>His shame and derision to bear;<br/>Such blest opportunity soon pass away,<br/>That He in our trouble may share.<br/>All loneliness, misunderstandings and scorn<br/>Despisings and sorrows will flee;<br/>I treasure these blessings, for through them, O Lord,<br/>I enter sweet oneness with Thee.<br/>I enter sweet oneness with Thee.<br/>',NULL,5939,5939);
INSERT INTO stanza VALUES('E1137','5','I long to behold, Lord, Thy countenance soon,<br/>What rapture with Thee, Lord, to meet.<br/>But neither seek I all these trials to avoid;<br/>Such times, Lord, are too rare and sweet.<br/>Have mercy on me, fill me with Thy great love,<br/>For Thee, Lord, to live at all cost;<br/>Lest Thy servant, hoping for that blessed day,<br/>That day, regret chances were lost,<br/>That day, regret chances were lost.<br/>',NULL,5940,5940);
INSERT INTO stanza VALUES('E1138','1','Lord, Thou art our consecration,<br/>Thou the consecrated One;<br/>Thou has satisfied the Father —<br/>Consecration thus was done.<br/>When on earth Thou hadst no pleasure,<br/>Save to do the Father''s will;<br/>Now Thou livest here within us,<br/>Consecration to fulfill.<br/>',NULL,5941,5941);
INSERT INTO stanza VALUES('E1138','2','Lord, we praise Thee for the picture:<br/>Consecration''s ram we see,<br/>Burnt for God''s full satisfaction,<br/>Eaten and enjoyed to be.<br/>Thou art now our ram, Lord Jesus,<br/>Offered for the will of God;<br/>By Thy consecration, faultless,<br/>We may walk where Thou hast trod.<br/>',NULL,5942,5942);
INSERT INTO stanza VALUES('E1138','3','As we eat Thyself, Lord Jesus,<br/>Consecrated we become;<br/>By Thy wondrous life within us,<br/>Thy obedience is our own.<br/>No more need we strive and struggle,<br/>Consecrated try to be;<br/>Consecration dwells within us —<br/>Now our part to eat of Thee.<br/>',NULL,5943,5943);
INSERT INTO stanza VALUES('E1138','4','Lord, we praise Thee, consecration<br/>Is nought else but Thee as food:<br/>As we eat Thee and enjoy Thee,<br/>We are all made one with God;<br/>One in will and one in purpose<br/>We become by eating Thee:<br/>As we take and eat Thyself, Lord,<br/>Consecrated we will be.<br/>',NULL,5944,5944);
INSERT INTO stanza VALUES('E1139','1','I will get me to the mountain,<br/>I will get me to the hill;<br/>In Thy death and resurrection,<br/>Jesus, take me deeper still.<br/>',NULL,5945,5945);
INSERT INTO stanza VALUES('E1139','chorus','I will get me to the mountain,<br/>Willingly would get me there.<br/>All my self fore''er forsaking,<br/>One with Thee, O Lord,<br/>Thy death to share.<br/>',NULL,5946,5946);
INSERT INTO stanza VALUES('E1139','2','Still at times I sense the shadows<br/>Of my nature, untransformed;<br/>Lord, I''ll go unto the mountain,<br/>To Thy death to be conformed.<br/>',NULL,5947,5947);
INSERT INTO stanza VALUES('E1139','3','On the mountain till the daybreak,<br/>Linger I, Lord, thus with Thee,<br/>May Thy all-transforming Spirit<br/>Saturate me thoroughly.<br/>',NULL,5948,5948);
INSERT INTO stanza VALUES('E1139','4','Mingled with Thee on the mountain,<br/>Soon my sun begins to shine;<br/>Death has worked her deep impression,<br/>Now my nature''s one with Thine.<br/>',NULL,5949,5949);
INSERT INTO stanza VALUES('E1140','1','Our old man has been crucified with Christ;<br/>Yes, all we are in oldness He sufficed<br/>To bring to naught upon the cross that He<br/>Himself as our new Husband fully be<br/>Enjoyed by us.<br/>',NULL,5950,5950);
INSERT INTO stanza VALUES('E1140','2','Yes, all our strength of independence died,<br/>For we with Christ were fully crucified.<br/>Now we''re so glad to be His proper wife,<br/>Dependently enjoying Him as life<br/>Forevermore.<br/>',NULL,5951,5951);
INSERT INTO stanza VALUES('E1140','3','Our dying was not such a sad affair,<br/>The new man was rejoicing to be there;<br/>The old man dead and buried, we were free<br/>To marry Christ, and live eternally,<br/>His wife, fore''er.<br/>',NULL,5952,5952);
INSERT INTO stanza VALUES('E1140','4','Now as the new, regenerated man,<br/>We do two things, according to God''s plan:<br/>Bear fruit to God and serve in spirit new<br/>So God becomes the fruit of all we do,<br/>And all we are.<br/>',NULL,5953,5953);
INSERT INTO stanza VALUES('E1140','5','There are three laws in Romans seven, see —<br/>The law of God; the mind, the good old me;<br/>The sinful law indwelling bodily;<br/>Yet from these all the Lord has set us free,<br/>To live by Him.<br/>',NULL,5954,5954);
INSERT INTO stanza VALUES('E1140','6','In Romans eight the law of Spirit is,<br/>Where we''re in Christ, and we are fully His,<br/>The law of life has set us wholly free<br/>And Christ becomes our life eternally,<br/>Hallelujah!<br/>',NULL,5955,5955);
INSERT INTO stanza VALUES('E1141','1','We will sing to the Lord with our spirit,<br/>We will sing to the Lord from within,<br/>We will sing hallelujah to Jesus;<br/>And be blent into oneness with Him.<br/>',NULL,5956,5956);
INSERT INTO stanza VALUES('E1141','2','We have been many years in religion,<br/>We have been many years in our mind,<br/>We have been many years in emotions,<br/>Always seeking, but never to find.<br/>',NULL,5957,5957);
INSERT INTO stanza VALUES('E1141','3','Now we''re learning to turn to our spirit,<br/>Now we''re learning to take Christ as life;<br/>Now we''re learning to feed upon Jesus<br/>And be freed from all struggling and strife.<br/>',NULL,5958,5958);
INSERT INTO stanza VALUES('E1141','4','Hallelujah for life in the Spirit,<br/>Hallelujah for newness within.<br/>When we turn from our mind to our spirit,<br/>We enjoy all the riches of Him.<br/>',NULL,5959,5959);
INSERT INTO stanza VALUES('E1142','1','Jesus is the living Spirit,<br/>Our reality;<br/>We enjoy Him just by calling<br/>In simplicity.<br/>',NULL,5960,5960);
INSERT INTO stanza VALUES('E1142','chorus','Jesus is the living Spirit,<br/>We must now proclaim;<br/>He is rich unto all men<br/>That call upon His name.<br/>',NULL,5961,5961);
INSERT INTO stanza VALUES('E1142','2','He is living now within us,<br/>Giving liberty;<br/>He is good and He is gracious<br/>As we taste and see.<br/>',NULL,5962,5962);
INSERT INTO stanza VALUES('E1142','3','Jesus is the living Spirit<br/>And the living Word;<br/>When we touch Him by pray-reading<br/>We receive this Lord.<br/>',NULL,5963,5963);
INSERT INTO stanza VALUES('E1142','4','Jesus is the living Spirit<br/>Who among us flows;<br/>Fellowship of life in spirit<br/>Unity bestows.<br/>',NULL,5964,5964);
INSERT INTO stanza VALUES('E1142','5','Jesus is the living Spirit,<br/>He is our rich feast;<br/>As the Body now enjoys Him,<br/>Praises are released.<br/>',NULL,5965,5965);
INSERT INTO stanza VALUES('E1143','1','The tree of life, how sweet the fruit,<br/>With God as life complete.<br/>I once was dead, but now I live,<br/>Was starved, but now I eat.<br/>',NULL,5966,5966);
INSERT INTO stanza VALUES('E1143','2','''Twas God that brought me to the tree,<br/>With Christ Himself as meat;<br/>How precious did that tree become<br/>When I began to eat.<br/>',NULL,5967,5967);
INSERT INTO stanza VALUES('E1143','3','The Lord Himself is food to me,<br/>He is my life supply;<br/>He will my pure enjoyment be,<br/>None else can satisfy.<br/>',NULL,5968,5968);
INSERT INTO stanza VALUES('E1143','4','I freely eat this living tree,<br/>For eating is the way<br/>To put God''s life inside of me,<br/>To live by Him today.<br/>',NULL,5969,5969);
INSERT INTO stanza VALUES('E1144','1','In the Word of old, we are clearly told,<br/>In His image God created man.<br/>To express His worth, to subdue the earth,<br/>Have dominion and fulfill His plan.<br/>',NULL,5970,5970);
INSERT INTO stanza VALUES('E1144','chorus','Image, image,<br/>In His image He created man.<br/>Image, image,<br/>For dominion, to fulfill His plan.<br/>',NULL,5971,5971);
INSERT INTO stanza VALUES('E1144','2','Yet no rules He gave, no instructions, save:<br/>"Every tree shall be to thee for meat."<br/>But on tree, He said, surely makes you dead;<br/>Fruit of knowledge isn''t good to eat.<br/>',NULL,5972,5972);
INSERT INTO stanza VALUES('E1144','chorus','Knowledge, knowledge,<br/>Fruit of knowledge wasn''t meant for meat.<br/>Knowledge, knowledge,<br/>Fruit of knowledge isn''t good to eat.<br/>',NULL,5973,5973);
INSERT INTO stanza VALUES('E1144','3','Midst the garden fair, see the life tree there —<br/>God Himself the tree of life does show.<br/>But the enemy, somehow subtly<br/>Tempted man the other tree to know.<br/>',NULL,5974,5974);
INSERT INTO stanza VALUES('E1144','chorus','Fallen, fallen,<br/>Man has eaten of the deadly tree.<br/>Fallen, fallen,<br/>Man requires a full recovery.<br/>',NULL,5975,5975);
INSERT INTO stanza VALUES('E1144','4','Then came Jesus Christ as the tree of life,<br/>Satisfying all that God required.<br/>He redeemed the earth, giving man new birth,<br/>And became the food that man desired.<br/>',NULL,5976,5976);
INSERT INTO stanza VALUES('E1144','chorus','Jesus, Jesus,<br/>Jesus Christ is really good to eat.<br/>Jesus, Jesus,<br/>He is real drink and real meat.<br/>',NULL,5977,5977);
INSERT INTO stanza VALUES('E1144','5','Jesus ne''er designed e''er to feed our mind;<br/>All good knowledge only puffeth up.<br/>But He came, He said, as a feast instead,<br/>Not to analyze, but only sup.<br/>',NULL,5978,5978);
INSERT INTO stanza VALUES('E1144','chorus','Take Him, take Him,<br/>Wholly satisfying, glorious.<br/>Take Him, take Him,<br/>Jesus is the tree of life to us.<br/>',NULL,5979,5979);
INSERT INTO stanza VALUES('E1144','6','As we eat the Lord, growth He does afford,<br/>Life and numbers soon will be increased.<br/>We must clearly see God''s recovery —<br/>Christ is not religion, but a feast.<br/>',NULL,5980,5980);
INSERT INTO stanza VALUES('E1144','chorus','Eat Him, eat Him,<br/>Christ as life is all the food we need.<br/>Eat Him, eat Him,<br/>He who eateth Him shall live indeed.<br/>',NULL,5981,5981);
INSERT INTO stanza VALUES('E1144','7','Eating is the way to live Christ today,<br/>Of the eating there should be no lack.<br/>As the churches eat, they become complete,<br/>Eating Christ will bring the Bridegroom back.<br/>',NULL,5982,5982);
INSERT INTO stanza VALUES('E1144','chorus','Eating, eating,<br/>Of our eating there must be no lack.<br/>Eating, eating,<br/>Eating Christ will bring the Bridegroom back.<br/>',NULL,5983,5983);
INSERT INTO stanza VALUES('E1145','1','God gave His Son to man to be<br/>The tree of life so rich and free,<br/>That every man may taste and see<br/>That God is good for food.<br/>Yes, God is good for food!<br/>Yes, God is good for food!<br/>We''ve tasted and we testify<br/>That God is good for food!<br/>',NULL,5984,5984);
INSERT INTO stanza VALUES('E1145','2','We eat this feast and take God in,<br/>And as we eat we live by Him,<br/>For all the elements within<br/>This feast are God Himself.<br/>Yes, Jesus is our feast!<br/>Yes, Jesus is our feast!<br/>We eat this feast and live by Him,<br/>For Jesus is our feast!<br/>',NULL,5985,5985);
INSERT INTO stanza VALUES('E1145','3','Christ Jesus is the food we eat;<br/>He is our bread, He is our meat;<br/>He is our life-supply complete;<br/>We daily eat of Him.<br/>We daily eat of Him,<br/>We daily eat of Him.<br/>He is our life-supply complete;<br/>We daily eat of Him.<br/>',NULL,5986,5986);
INSERT INTO stanza VALUES('E1145','4','This feast is so enjoyable;<br/>To men it''s so available,<br/>For God said whosoever will<br/>May come and freely eat;<br/>Yes, come and freely eat;<br/>Yes, come and freely eat.<br/>For God said whosoever will<br/>May come and freely eat.<br/>',NULL,5987,5987);
INSERT INTO stanza VALUES('E1146','1','Let us eat Jesus every day,<br/>Eating His flesh in such a way<br/>That in the trials great or small<br/>He as a Man will be our all.<br/>',NULL,5988,5988);
INSERT INTO stanza VALUES('E1146','chorus','Eat, eat more of Jesus!<br/>Eat, eat more of Jesus!<br/>Why should we undernourished be<br/>When we have His humanity?<br/>',NULL,5989,5989);
INSERT INTO stanza VALUES('E1146','2','Let us drink Jesus till we see<br/>That we are human, Jesusly!<br/>Till rivers flood the barren ground<br/>And quench the thirst of all around.<br/>',NULL,5990,5990);
INSERT INTO stanza VALUES('E1146','chorus','Drink, drink more of Jesus!<br/>Drink, drink more of Jesus!<br/>Why should we ever thirsty be<br/>When we have His humanity?<br/>',NULL,5991,5991);
INSERT INTO stanza VALUES('E1146','3','We must eat Jesus till God can<br/>Have the fulfillment of His plan —<br/>One man expressed for all to see,<br/>One church in each locality.<br/>',NULL,5992,5992);
INSERT INTO stanza VALUES('E1146','chorus','We''ll masticate Jesus!<br/>We''ll masticate Jesus!<br/>Then to the tent of meeting bring<br/>Jesus, our real meal offering.<br/>',NULL,5993,5993);
INSERT INTO stanza VALUES('E1147','1','Christ is our manna true,<br/>Our bread of life indeed;<br/>He''s our supply of nourishment,<br/>As on Him now we feed.<br/>',NULL,5994,5994);
INSERT INTO stanza VALUES('E1147','2','From Egypt Israel fled<br/>Into a desert land;<br/>Egyptian food they left behind,<br/>And wandering began.<br/>',NULL,5995,5995);
INSERT INTO stanza VALUES('E1147','3','One day, the manna fell,<br/>Oh, what a wondrous feat;<br/>This was the bread the Lord had giv''n<br/>For Israel to eat.<br/>',NULL,5996,5996);
INSERT INTO stanza VALUES('E1147','4','Unique this manna is,<br/>It comes with morning dew;<br/>The visit of God''s grace it is,<br/>Forever fresh and new.<br/>',NULL,5997,5997);
INSERT INTO stanza VALUES('E1147','5','God is majestic, high,<br/>And greater than us all;<br/>But that we may partake of Him,<br/>In Christ, He''s fine and small.<br/>',NULL,5998,5998);
INSERT INTO stanza VALUES('E1147','6','Though ground, or beat, or baked,<br/>He''s so available;<br/>As bread and cakes and wafers fresh,<br/>We eat Him to the full.<br/>',NULL,5999,5999);
INSERT INTO stanza VALUES('E1147','7','Manna shows Him to be<br/>The germ of life, the seed;<br/>''Tis God Himself sown into us,<br/>The source of all we need.<br/>',NULL,6000,6000);
INSERT INTO stanza VALUES('E1147','8','Between the morning dew<br/>And cold winter snow,<br/>This manna too is frost which kills<br/>Things negative below.<br/>',NULL,6001,6001);
INSERT INTO stanza VALUES('E1147','9','How pure and white and clean;<br/>In type our Christ we see;<br/>As we digest His element,<br/>He washes inwardly.<br/>',NULL,6002,6002);
INSERT INTO stanza VALUES('E1147','10','Manna with honey is;<br/>Two lives this type does show;<br/>One for the Lord''s redemptive work,<br/>And one His life to grow.<br/>',NULL,6003,6003);
INSERT INTO stanza VALUES('E1147','11','By eating more of Christ<br/>We''ll be the less opaque;<br/>We''ll then appear as bdellium,<br/>Transparent us to make.<br/>',NULL,6004,6004);
INSERT INTO stanza VALUES('E1147','12','Lord, as we''re eating here<br/>And in the manna see<br/>The riches of this glorious Christ,<br/>We''re filled with praise to Thee.<br/>',NULL,6005,6005);
INSERT INTO stanza VALUES('E1148','1','"Come and dine," the Lord is calling,<br/>"Come and dine" —<br/>We can eat and drink of Jesus all the time!<br/>He''s our daily food supply,<br/>Only He can satisfy.<br/>"Come and dine," the Lord is calling,<br/>"Come and dine."<br/>',NULL,6006,6006);
INSERT INTO stanza VALUES('E1148','2','"Come and dine," the Lord is calling,<br/>"Come and dine."<br/>When we eat and drink of Jesus all the time,<br/>He becomes our life within,<br/>And He fills us to the brim.<br/>"Come and dine," the Lord is calling,<br/>"Come and dine."<br/>',NULL,6007,6007);
INSERT INTO stanza VALUES('E1149','1','Of Him whence grace and truth did spring,<br/>We''re at the fountain drinking;<br/>This Christ we''ll ever praise and sing,<br/>Here in the church, His home!<br/>',NULL,6008,6008);
INSERT INTO stanza VALUES('E1149','chorus','Glory to God! We''re at the fountain drinking!<br/>Glory to God! We''re in the church, our home!<br/>',NULL,6009,6009);
INSERT INTO stanza VALUES('E1149','2','Ask but His grace, and lo, ''tis giv''n,<br/>We''re at the fountain drinking;<br/>Seek but Himself, the heaven of heaven,<br/>And find Him here at home!<br/>',NULL,6010,6010);
INSERT INTO stanza VALUES('E1149','3','Though Satan fights with all His power,<br/>We''re at the fountain drinking;<br/>He''ll not prevail, not one short hour,<br/>Against the church, our home!<br/>',NULL,6011,6011);
INSERT INTO stanza VALUES('E1149','4','Athirst we to this spring do fly,<br/>We''re at the fountain drinking;<br/>Drink deep, this well will not run dry!<br/>It''s in the church, our home!<br/>',NULL,6012,6012);
INSERT INTO stanza VALUES('E1150','1','We''re feeding on the living bread,<br/>We''re drinking at the fountainhead;<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again.<br/>What, never thirst again? No, never thirst again!<br/>What, never thirst again? No, never thirst again!<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again!<br/>',NULL,6013,6013);
INSERT INTO stanza VALUES('E1150','2','We are feeding on the living bread,<br/>Eating of the feast our Lord has spread,<br/>And whoso eateth, Jesus said,<br/>Shall hunger nevermore.<br/>What, hunger nevermore? Yes, hunger nevermore!<br/>What, hunger nevermore? Yes, hunger nevermore!<br/>And whoso eateth, Jesus said,<br/>Shall hunger never more.<br/>',NULL,6014,6014);
INSERT INTO stanza VALUES('E1150','3','We are breathing in the living air,<br/>Breathing in the One whose life we share,<br/>And whoso breatheth — now, fore''er —<br/>Shall have the life of God<br/>What have the life of God? Yes, have the life of God!<br/>What have the life of God? Yes, have the life of God!<br/>And whoso breatheth — now, fore''er —<br/>Shall have the life of God<br/>',NULL,6015,6015);
INSERT INTO stanza VALUES('E1150','4','We are tasting of the living wine,<br/>In spirit tasting life divine,<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>What, have the joy of God? Yes, have the joy of God!<br/>What, have the joy of God? Yes, have the joy of God!<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>',NULL,6016,6016);
INSERT INTO stanza VALUES('E1150','5','Christ is the resurrected King,<br/>Who died and rose, our life to bring,<br/>If you receive Him you will sing,<br/>And live forevermore.<br/>What, live forevermore? Yes, live forevermore!<br/>What, live forevermore? Yes, live forevermore!<br/>If you receive Him you will sing,<br/>And live forevermore.<br/>',NULL,6017,6017);
INSERT INTO stanza VALUES('E1151','1','Drink! A river pure and clear that''s flowing from the throne;<br/>Eat! The tree of Life with fruits abundant, richly grown;<br/>Look! No need of lamp nor sun nor moon to keep it bright, for<br/>Here there is no night!<br/>',NULL,6018,6018);
INSERT INTO stanza VALUES('E1151','chorus','Do come, oh, do come,<br/>Says Spirit and the Bride:<br/>Do come, oh, do come,<br/>Let him that heareth cry.<br/>Do come, oh, do come,<br/>Let him who thirsts and will<br/>Take freely the water of Life!<br/>',NULL,6019,6019);
INSERT INTO stanza VALUES('E1151','2','Christ, our river, Christ, our water, springing from within;<br/>Christ, our tree, and Christ, the fruits, to be enjoyed therein,<br/>Christ, our day, and Christ, our light, and Christ, our morning star:<br/>Christ our everything!<br/>',NULL,6020,6020);
INSERT INTO stanza VALUES('E1151','3','We are washing all our robes the tree of life to eat;<br/>"O Lord, Amen, Hallelujah!" — Jesus is so sweet!<br/>We our spirits exercise, and thus experience Christ.<br/>What a Christ have we!<br/>',NULL,6021,6021);
INSERT INTO stanza VALUES('E1151','4','Now we have a home so bright that outshines the sun,<br/>Where the brothers all unite and truly are one.<br/>Jesus gets us all together, Him we now display<br/>In the local church.<br/>',NULL,6022,6022);
INSERT INTO stanza VALUES('E1152','1','To Jesus every day we find our hearts are closer drawn;<br/>He''s fairer than the sons of men and fresher than the morn;<br/>He''s all that we can say of Him in fairest words and more,<br/>And every day He''s dearer than He was the day before!<br/>',NULL,6023,6023);
INSERT INTO stanza VALUES('E1152','chorus','The half cannot be fancied of such a treasure-store,<br/>And every day He''s dearer than He ever was before!<br/>',NULL,6024,6024);
INSERT INTO stanza VALUES('E1152','2','His glory broke upon us when we saw Him in the church,<br/>For here are all His riches, here we''ve given up our search;<br/>''Tis here He satisfies our longing spirits o''er and o''er,<br/>And every day He''s dearer than He was the day before.<br/>',NULL,6025,6025);
INSERT INTO stanza VALUES('E1152','3','Now He''s the living Spirit who within our spirit dwells,<br/>And by His sweet anointing, how His life within us swells!<br/>As with the saints we''re meeting, full released our spirits soar,<br/>For now our Lord is dearer than He ever was before.<br/>',NULL,6026,6026);
INSERT INTO stanza VALUES('E1152','4','The Lord has made us one with Him for His recovery;<br/>The riches of this Christ, the church His fullness, men must see.<br/>Yes, all we have and all we are, we every day outpour<br/>For His tremendous purpose, ever dearer than before.<br/>',NULL,6027,6027);
INSERT INTO stanza VALUES('E1153','1','We have found the Christ who''s all in all;<br/>He is everything to us;<br/>O how blest upon His name to call,<br/>How divine, how glorious!<br/>',NULL,6028,6028);
INSERT INTO stanza VALUES('E1153','chorus','It is joy unspeakable and full of glory,<br/>Full of glory, full of glory;<br/>It is joy unspeakable and full of glory,<br/>And the half has never yet been told!<br/>',NULL,6029,6029);
INSERT INTO stanza VALUES('E1153','2','We have found that Christ the Spirit is<br/>Who within our spirit dwells;<br/>How available, how near He is,<br/>And His sweetness all excels.<br/>',NULL,6030,6030);
INSERT INTO stanza VALUES('E1153','3','We have found the way to live by Christ —<br/>Pray His Word and call His name!<br/>This-the eating, drinking — has sufficed<br/>And its worth we now proclaim.<br/>',NULL,6031,6031);
INSERT INTO stanza VALUES('E1153','4','We have found the local church, our home;<br/>We are home and home indeed!<br/>Nevermore in Babylon we roam;<br/>In the church is all we need.<br/>',NULL,6032,6032);
INSERT INTO stanza VALUES('E1153','5','We have found that meeting with the saints<br/>Is the greatest joy on earth;<br/>''Tis by this our spirit never faints<br/>And our lives are filled with worth.<br/>',NULL,6033,6033);
INSERT INTO stanza VALUES('E1154','1','I love Thee, Jesus,<br/>And Thy love to me<br/>Draws me, ever to seek Thee<br/>And run after Thee,<br/>Draws me, ever to seek Thee<br/>And run after Thee.<br/>Thou art beloved,<br/>Yea! Altogether lovely,<br/>The One in whom my heart delighteth.<br/>',NULL,6034,6034);
INSERT INTO stanza VALUES('E1154','2','Thy love, Lord Jesus,<br/>Is sweeter than wine,<br/>And Thy fragrance of ointments<br/>My heart doth entwine,<br/>And Thy fragrance of ointments<br/>My heart doth entwine.<br/>A fount in gardens,<br/>A well of living waters,<br/>Which streams and flows from Lebanon''s mountains.<br/>',NULL,6035,6035);
INSERT INTO stanza VALUES('E1154','3','O come Beloved,<br/>On my garden blow,<br/>That the odor of spices<br/>May break forth and flow,<br/>That the odor of spices<br/>May break forth and flow.<br/>My spouse, My sister,<br/>I''m come into My garden<br/>To feast upon wine, milk and honey.<br/>',NULL,6036,6036);
INSERT INTO stanza VALUES('E1154','4','Set me Lord Jesus,<br/>As seal on Thine heart;<br/>Jealousy''s cruel as Sheol,<br/>And love''s strong as death.<br/>Jealousy''s cruel as Sheol,<br/>And love''s strong as death.<br/>Much water cannot<br/>Quench love, nor do floods drown it.<br/>All man could give for love is contemned.<br/>',NULL,6037,6037);
INSERT INTO stanza VALUES('E1154','end-note','(Repeat the last three lines of each stanza)<br/>',NULL,6038,6038);
INSERT INTO stanza VALUES('E1155','1','How I love Thee, precious Jesus,<br/>That Thy love laid hold of me;<br/>Thou hast drawn and wooed and kissed me<br/>That a lover I may be!<br/>',NULL,6039,6039);
INSERT INTO stanza VALUES('E1155','chorus','Our Beloved, how we love Him,<br/>So attractive, our delight.<br/>We are captivated wholly<br/>And are comely in His sight.<br/>',NULL,6040,6040);
INSERT INTO stanza VALUES('E1155','2','As a company of horses,<br/>Thou, O Lord, has likened me,<br/>Strong and swift, with Pharaoh''s chariots,<br/>Full of natural energy.<br/>',NULL,6041,6041);
INSERT INTO stanza VALUES('E1155','3','Just a lover with the dove''s eyes<br/>Fixed on Him and Him alone;<br/>Changed are all my natural concepts,<br/>Oh, the Lord in me has grown!<br/>',NULL,6042,6042);
INSERT INTO stanza VALUES('E1155','4','Now a lily of the valley,<br/>Standing out among the thorns,<br/>In the Lord alone I''m trusting,<br/>Of my self-strength I''ve been shorn.<br/>',NULL,6043,6043);
INSERT INTO stanza VALUES('E1155','5','Make us doves that hide in Thee, Lord;<br/>Bring us to the secret place.<br/>There You find our voices sweet, Lord,<br/>And desire to see our face.<br/>',NULL,6044,6044);
INSERT INTO stanza VALUES('E1155','6','Make us then, Lord, smoking pillars,<br/>Coming from the wilderness.<br/>By Thy death and resurrection<br/>All our natural will suppress.<br/>',NULL,6045,6045);
INSERT INTO stanza VALUES('E1155','7','You desire a couch to rest on —<br/>We become a rest to Thee;<br/>Thou the Person in our being,<br/>Gone our personality.<br/>',NULL,6046,6046);
INSERT INTO stanza VALUES('E1155','8','Now a palanquin You''re making —<br/>Nothing natural You''ll allow.<br/>For Your move and Your expression<br/>Start this work within us now!<br/>',NULL,6047,6047);
INSERT INTO stanza VALUES('E1155','9','You supply the wood and pillars<br/>For the structure and support,<br/>Bottom gold and seat of purple<br/>For our King of royal court.<br/>',NULL,6048,6048);
INSERT INTO stanza VALUES('E1155','10','Only this, O Lord, we offer<br/>For Thy palanquin so fine:<br/>Just our love, so pure and fitted,<br/>The interior design.<br/>',NULL,6049,6049);
INSERT INTO stanza VALUES('E1155','11','What a sight when our Beloved<br/>Wears a crown upon His brow;<br/>Christ, the Church, are now united —<br/>Boast and glory to Him now!<br/>',NULL,6050,6050);
INSERT INTO stanza VALUES('E1156','1','To the Lord we''re as a garden,<br/>Out from which the spices flow;<br/>All the precious fruits of Jesus<br/>Freely in this garden grow.<br/>',NULL,6051,6051);
INSERT INTO stanza VALUES('E1156','chorus','Spikenard, saffron, henna flower,<br/>Cinnamon and calamus,<br/>Frankincense and myrrh and aloes;<br/>O Lord, we would ever grow Thee thus.<br/>',NULL,6052,6052);
INSERT INTO stanza VALUES('E1156','2','O Lord, come into Thy garden,<br/>Come, Beloved, come and eat<br/>Freely for Thy satisfaction<br/>Of Thy fruit, abundant, sweet.<br/>',NULL,6053,6053);
INSERT INTO stanza VALUES('E1156','chorus','"Yea," Thou answerest, "I am eating<br/>Honeycomb with honey pure."<br/>All sweet spices from Thy garden,<br/>Doth Thy satisfaction, Lord, secure.<br/>',NULL,6054,6054);
INSERT INTO stanza VALUES('E1156','3','All the produce of the garden<br/>Is with resurrection filled<br/>That the Lord may have a city,<br/>Fruits of resurrection build.<br/>',NULL,6055,6055);
INSERT INTO stanza VALUES('E1156','chorus','From the garden to the city,<br/>Growth transformed to precious stone;<br/>Christ is thus expressed, reflected —<br/>God in all His glory fully shown.<br/>',NULL,6056,6056);
INSERT INTO stanza VALUES('E1156','4','Now the city, fair and comely,<br/>As the dawn, triumphantly,<br/>Is an army strong and mighty<br/>Marching forth in victory.<br/>',NULL,6057,6057);
INSERT INTO stanza VALUES('E1156','chorus','Lo, the city and the army —<br/>Saints transformed in one accord.<br/>What a terror to the devil,<br/>And so beautiful unto the Lord!<br/>',NULL,6058,6058);
INSERT INTO stanza VALUES('E1157','1','His banner over me is love,<br/>His banner over me is love;<br/>He brought me into his banqueting house,<br/>And His banner over me is love.<br/>',NULL,6059,6059);
INSERT INTO stanza VALUES('E1157','chorus','Is love! Is love!<br/>His banner over me is love;<br/>He brought me into His banqueting house,<br/>And His banner over me is love.<br/>',NULL,6060,6060);
INSERT INTO stanza VALUES('E1157','2','His fruit is sweet unto my taste,<br/>His fruit is sweet unto my taste;<br/>I''m feasting here in His banqueting house,<br/>And His fruit is sweet unto my taste.<br/>',NULL,6061,6061);
INSERT INTO stanza VALUES('E1157','chorus','How sweet! How sweet!<br/>His fruit is sweet unto my taste;<br/>I''m feasting here in His banqueting house,<br/>And His fruit is sweet unto my taste.<br/>',NULL,6062,6062);
INSERT INTO stanza VALUES('E1158','1','Dear Lord Jesus, precious Jesus,<br/>Thou hast won each love from me;<br/>Who like Thee — so fair and comely?<br/>Who like Thee — so sweet and lovely?<br/>Matchless One, unrivaled beauty,<br/>None can e''er compete with Thee!<br/>',NULL,6063,6063);
INSERT INTO stanza VALUES('E1158','2','Dear Lord Jesus, precious Jesus,<br/>Gladly will I hear Thy call;<br/>Since Thy voice my heart hath entered,<br/>I from all things could but sever;<br/>Void are all my other seekings,<br/>Every pride hath disappeared.<br/>',NULL,6064,6064);
INSERT INTO stanza VALUES('E1158','3','Dear Lord Jesus, precious Jesus,<br/>How can I still stubborn be?<br/>At Thy feet cast all my hard''nings,<br/>And return with songs and singings;<br/>''Tis my love to be Thy bondslave,<br/>''Tis my joy to Thee obey.<br/>',NULL,6065,6065);
INSERT INTO stanza VALUES('E1158','4','Dear Lord Jesus, precious Jesus,<br/>Thy way only will I choose;<br/>Though in tears while I''m obeying,<br/>Yet I would not change my standing;<br/>All I long for is Thy pleasure,<br/>And the peace Thy love would bring.<br/>',NULL,6066,6066);
INSERT INTO stanza VALUES('E1158','5','Dear Lord Jesus, precious Jesus,<br/>When Thy presence does depart,<br/>Seems the dawn has lost its traces,<br/>Hidden are my smiling faces;<br/>All I yearn for is Thy coming<br/>And Thy presence'' sweet embrace.<br/>',NULL,6067,6067);
INSERT INTO stanza VALUES('E1158','6','Dear Lord Jesus, precious Jesus,<br/>Can I tell it all to Thee?<br/>Thou my love and satisfaction,<br/>Thou my everlasting portion;<br/>Thou art all that I desire,<br/>Nothing else I would pursue.<br/>',NULL,6068,6068);
INSERT INTO stanza VALUES('E1158','7','Dear Lord Jesus, precious Jesus,<br/>All I have I give to Thee;<br/>Who like Thee — so fair and comely?<br/>Who like Thee — so sweet and lovely?<br/>Matchless One, unrivaled beauty,<br/>None can e''er compete with Thee!<br/>',NULL,6069,6069);
INSERT INTO stanza VALUES('E1159','1','Jesus Lord, I''m captured by Thy beauty.<br/>All my heart to Thee I open wide;<br/>Now set free from all religious duty,<br/>Only let me in Thyself abide.<br/>As I''m gazing here upon Thy glory,<br/>Fill my heart with radiancy divine;<br/>Saturate me, Lord, I now implore Thee,<br/>Mingle now Thy Spirit, Lord, with mine.<br/>',NULL,6070,6070);
INSERT INTO stanza VALUES('E1159','2','Shining One — how clear the sky above me!<br/>Son of Man, I see Thee on the throne!<br/>Holy One, the flames of God consume me,<br/>Till my being glows with Thee alone.<br/>Lord, when first I saw Thee in Thy splendor,<br/>All self-love and glory sank in shame;<br/>Now my heart its love and praises render,<br/>Tasting all the sweetness of Thy name.<br/>',NULL,6071,6071);
INSERT INTO stanza VALUES('E1159','3','Precious Lord, my flask of alabaster<br/>Gladly now I break in love for Thee;<br/>I anoint Thy head, Beloved Master;<br/>Lord, behold, I''ve saved the best for Thee.<br/>Dearest Lord, I waste myself upon Thee;<br/>Loving Thee, I''m deeply satisfied.<br/>Love outpoured from hidden depths within me,<br/>Costly oil, dear Lord, I would provide.<br/>',NULL,6072,6072);
INSERT INTO stanza VALUES('E1159','4','My Beloved, come on spices'' mountain;<br/>How I yearn to see Thee face to face.<br/>Drink, dear Lord, from my heart''s flowing fountain,<br/>Till I rest fore''er in Thine embrace.<br/>Not alone, O Lord, do I adore Thee,<br/>But with all the saints as Thy dear Bride;<br/>Quickly come, our love is waiting for Thee;<br/>Jesus Lord, Thou wilt be satisfied.<br/>',NULL,6073,6073);
INSERT INTO stanza VALUES('E1160','1','Jesus is our lovely Bridegroom,<br/>And our Bridegroom is with us!<br/>Now our praying''s turned to praising<br/>In His presence glorious.<br/>',NULL,6074,6074);
INSERT INTO stanza VALUES('E1160','chorus','O our Bridegroom! O our Bridegroom!<br/>Lord, Thou art our Bridegroom sweet!<br/>How we treasure Thy dear presence —<br/>O what bliss and joy complete!<br/>',NULL,6075,6075);
INSERT INTO stanza VALUES('E1160','2','We are fellows of the Bridegroom<br/>And our fasting days have ceased.<br/>With the Bridegroom in His chamber,<br/>Joyfully we keep the feast.<br/>',NULL,6076,6076);
INSERT INTO stanza VALUES('E1160','3','We as virgins may enjoy Him,<br/>Virgins simple, single, chaste.<br/>Going forth to meet the Bridegroom,<br/>Out from all the world we haste.<br/>',NULL,6077,6077);
INSERT INTO stanza VALUES('E1160','4','We are guests by God invited<br/>To His Son''s great wedding feast.<br/>Brothers, sisters, hallelujah,<br/>From religion we''re released!<br/>',NULL,6078,6078);
INSERT INTO stanza VALUES('E1160','5','Now rejoice with joy excelling,<br/>Joy of joys, all else beside —<br/>Not just fellows, guests, or virgins,<br/>Hallelujah, we''re the Bride!<br/>',NULL,6079,6079);
INSERT INTO stanza VALUES('E1160','chorus','Hallelujah! Hallelujah!<br/>Lord, Thou art our Bridegroom sweet!<br/>Hallelujah! Hallelujah!<br/>O what bliss and joy complete!<br/>',NULL,6080,6080);
INSERT INTO stanza VALUES('E1161','1','Christ will make His seeking lover<br/>Pillar, couch, and palanquin,<br/>E''en a crown, His boast and glory;<br/>He will do it all! Amen!<br/>',NULL,6081,6081);
INSERT INTO stanza VALUES('E1161','chorus','His beloved - how He loves her,<br/>So attractive, His delight.<br/>He is captivated wholly;<br/>She is comely in His sight.<br/>',NULL,6082,6082);
INSERT INTO stanza VALUES('E1161','2','But there still remains a shadow;<br/>Christ is still not satisfied.<br/>He must have a growing garden<br/>To become His loving Bride!<br/>',NULL,6083,6083);
INSERT INTO stanza VALUES('E1161','3','Paradise of pomegranates,<br/>Pleasant fruits, and henna flowers,<br/>Spikenard, saffron, myrrh, and aloes:<br/>His enjoyment now — not ours.<br/>',NULL,6084,6084);
INSERT INTO stanza VALUES('E1161','4','He has come into His garden,<br/>Gathered myrrh and spices there,<br/>Eaten honeycomb and honey;<br/>Wine and milk He''ll drink fore''er.<br/>',NULL,6085,6085);
INSERT INTO stanza VALUES('E1161','5','From the garden comes the city.<br/>All materials thus supplied;<br/>God is satisfied completely,<br/>And the foe is terrified.<br/>',NULL,6086,6086);
INSERT INTO stanza VALUES('E1161','6','"Thou art fair, my love, as Tirzah,<br/>Comely as Jerusalem."<br/>O Lord Jesus, Hallelujah,<br/>Thou wilt do it all! Amen!<br/>',NULL,6087,6087);
INSERT INTO stanza VALUES('E1162','1','We''ve found the secret of living,<br/>We''ve seen the vision divine.<br/>We are of God in Christ Jesus,<br/>We''re abiding, abiding in the vine.<br/>',NULL,6088,6088);
INSERT INTO stanza VALUES('E1162','chorus','Abiding in the vine,<br/>Abiding in the vine,<br/>All the riches of God''s life are mine!<br/>Praise God, He put us here,<br/>Never to leave; oh, we''re —<br/>Abiding, abiding in the vine.<br/>',NULL,6089,6089);
INSERT INTO stanza VALUES('E1162','2','No more in vain need we struggle,<br/>Trying the way in to find.<br/>Praise God — we''re in Him already,<br/>Hallelujah, abiding in the vine.<br/>',NULL,6090,6090);
INSERT INTO stanza VALUES('E1162','3','In us, the ointment is moving,<br/>''Tis the anointing divine;<br/>God''s precious essence bestowing,<br/>While abiding, abiding in the vine.<br/>',NULL,6091,6091);
INSERT INTO stanza VALUES('E1162','4','Now in the life-flow we''re living,<br/>O how the light in us shines!<br/>Both God and man are at home now<br/>By the mutual abiding in the vine.<br/>',NULL,6092,6092);
INSERT INTO stanza VALUES('E1163','1','He''s the vine and we''re the branches,<br/>We should e''er abide in Him,<br/>And let Him abide within us<br/>As the flow of life within.<br/>',NULL,6093,6093);
INSERT INTO stanza VALUES('E1163','chorus','In the vine, in the vine,<br/>In the vine, in the vine,<br/>We would know Thee, Lord, more deeply,<br/>E''er abiding in the vine.<br/>',NULL,6094,6094);
INSERT INTO stanza VALUES('E1163','2','As we hear His instant speaking,<br/>He''s the rich indwelling Word;<br/>To abide we must be faithful<br/>To the speaking that we''ve heard.<br/>',NULL,6095,6095);
INSERT INTO stanza VALUES('E1163','3','For ''tis here we know abiding<br/>In the real and deepest way;<br/>If we love our Lord completely,<br/>We would do whate''er He''d say.<br/>',NULL,6096,6096);
INSERT INTO stanza VALUES('E1163','4','Then His love abides within us,<br/>And in love abiding, we<br/>Know the joy of life-communion,<br/>Full and perfect harmony.<br/>',NULL,6097,6097);
INSERT INTO stanza VALUES('E1163','5','Oh, how precious this abiding,<br/>Oh, how intimate and sweet;<br/>As the fruit of life is added,<br/>And our joy is made complete.<br/>',NULL,6098,6098);
INSERT INTO stanza VALUES('E1164','1','Jesus, the all-inclusive land,<br/>Is everything to me:<br/>A Christ of brooks, of depths and streams,<br/>And fountains bubbling free.<br/>Springing from valleys and from hills,<br/>Flowing till every part He fills,<br/>He waters us — how glorious —<br/>By His life!<br/>',NULL,6099,6099);
INSERT INTO stanza VALUES('E1164','2','Jesus is now the land of wheat —<br/>Incarnate, crucified.<br/>But resurrection life is He<br/>By barley signified.<br/>He is a land of figs and vines —<br/>Blood of the grape, and cheering wine.<br/>With such supplies He satisfies —<br/>Christ our land!<br/>',NULL,6100,6100);
INSERT INTO stanza VALUES('E1164','3','O what a rich, abundant Christ:<br/>Our pomegranate true,<br/>The olive tree whose oil is now<br/>Anointing us anew,<br/>Rich milk and honey He doth bring,<br/>Sweet, satisfying, nourishing.<br/>Our Christ is such; He is so much!<br/>What a Christ!<br/>',NULL,6101,6101);
INSERT INTO stanza VALUES('E1164','4','In our good land we eat the bread —<br/>There is no scarcity.<br/>We never lack one thing in Him,<br/>So rich, so full is He.<br/>He is a land so vast, immense;<br/>He is complete in every sense.<br/>How He expands — land of all lands —<br/>In our heart!<br/>',NULL,6102,6102);
INSERT INTO stanza VALUES('E1164','5','Christ is a land of iron stones,<br/>Whence comes authority.<br/>We must dig out this solid Christ<br/>To bind His enemy.<br/>Then we must through the sufferings pass<br/>To be refined as burnished brass.<br/>With iron bind, as brass refined,<br/>Is our need.<br/>',NULL,6103,6103);
INSERT INTO stanza VALUES('E1164','6','Lord, how we bless Thee for this land,<br/>The all-inclusive Christ!<br/>We''ve eaten Him, we''re filled with Him,<br/>O how He has sufficed!<br/>Teach us to labor constantly<br/>Upon this vast reality;<br/>This is our joy, this our employ —<br/>Christ our land!<br/>',NULL,6104,6104);
INSERT INTO stanza VALUES('E1165','1','We''re in the land, we''re in the land!<br/>O Hallelujah! In the land!<br/>Christ is the land, Christ is the land,<br/>O praise the Lord, He is the land!<br/>',NULL,6105,6105);
INSERT INTO stanza VALUES('E1165','chorus','He is the milk and honey, too;<br/>The grain, the oil, the wine so new.<br/>We''re in the land! We''re in the land!<br/>O Hallelujah! In the land!<br/>',NULL,6106,6106);
INSERT INTO stanza VALUES('E1165','2','This land includes so many things:<br/>Wheat, barley, vines, deep-flowing springs,<br/>Fig trees, and never-failing bread —<br/>O what a land before us spread!<br/>',NULL,6107,6107);
INSERT INTO stanza VALUES('E1165','chorus','To have the produce and abound<br/>We daily labor on the ground;<br/>Then to the meetings we will bring<br/>The topmost Christ, our offering!<br/>',NULL,6108,6108);
INSERT INTO stanza VALUES('E1166','1','God has set the land before us,<br/>And the land we will possess.<br/>God has finally found a people<br/>Tired of the wilderness.<br/>Down with every weight and sin;<br/>Let''s go up and enter in.<br/>',NULL,6109,6109);
INSERT INTO stanza VALUES('E1166','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Amen.<br/>',NULL,6110,6110);
INSERT INTO stanza VALUES('E1166','2','God has cleared the way before us<br/>Through the victory of His Son;<br/>Raised the Victor''s banner o''er us,<br/>All the battles He has won.<br/>All that''s left for us to do<br/>Is by faith to follow through.<br/>',NULL,6111,6111);
INSERT INTO stanza VALUES('E1166','3','It''s a land of hills and valleys,<br/>Brooks of water flowing free;<br/>Fountains rich with living water,<br/>Streams that flow abundantly.<br/>Brothers, joyfully we stand<br/>In His promise, Christ the land.<br/>',NULL,6112,6112);
INSERT INTO stanza VALUES('E1166','4','God has made the fruit to grow here,<br/>Filled the land with produce sweet:<br/>Olive oil and pomegranates,<br/>Fig trees, honey, vines and wheat.<br/>We need nothing else besides,<br/>All we need the land provides.<br/>',NULL,6113,6113);
INSERT INTO stanza VALUES('E1166','5','We have eaten unto fullness,<br/>And with joy we bless the Lord,<br/>For the good land He has given;<br/>Faithful to His promised Word.<br/>Here we find there is no lack —<br/>Never, never we''ll go back!<br/>',NULL,6114,6114);
INSERT INTO stanza VALUES('E1166','6','All we need to do is labor,<br/>Working on the land each day;<br/>Not expecting ''manna'' blessing,<br/>Working in a normal way.<br/>God and man cooperating<br/>While for harvest we are waiting.<br/>',NULL,6115,6115);
INSERT INTO stanza VALUES('E1166','7','Labor thus will bring the increase<br/>Of the land with all its worth,<br/>And the Lord will have the harvest,<br/>When He comes to reap the earth.<br/>To provide the Lord the way,<br/>We must labor day by day.<br/>',NULL,6116,6116);
INSERT INTO stanza VALUES('E1167','1','Laboring on the good land, laboring in the morning,<br/>Laboring through the noontime to the early eve,<br/>Laboring for a harvest, reaping all the produce,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,6117,6117);
INSERT INTO stanza VALUES('E1167','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>',NULL,6118,6118);
INSERT INTO stanza VALUES('E1167','2','Reaping wheat and barley, death and resurrection,<br/>Though the loss sustained our old man often grieves;<br/>But in life abundant, life in resurrection,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,6119,6119);
INSERT INTO stanza VALUES('E1167','3','Grain and wine and oil — bringing in the surplus<br/>Of the wheat and barley, vine and olive trees:<br/>Wine to cause rejoicing, oil to give anointing,<br/>Bringing in the top tenth, bringing in the sheaves.<br/>',NULL,6120,6120);
INSERT INTO stanza VALUES('E1168','1','Laboring on Jesus, the good land so real,<br/>Plowing and planting and watering the field.<br/>He yields the produce of reality,<br/>God reaps the harvest of Jesus in me.<br/>',NULL,6121,6121);
INSERT INTO stanza VALUES('E1168','chorus','O Jesus! You''re God''s good land<br/>For me to labor on!<br/>I''ll bit by bit possess You<br/>Until the whole is won!<br/>With Canaan is God''s purpose,<br/>The labor He will bless;<br/>Lord Jesus, here I gain Yourself,<br/>Your Person to possess.<br/>',NULL,6122,6122);
INSERT INTO stanza VALUES('E1168','2','Laboring on Jesus! My heart has been set,<br/>Labor''s begun, and I have no regret,<br/>For with my labor God''s sending the rain,<br/>And all my labor on Christ yields much gain.<br/>',NULL,6123,6123);
INSERT INTO stanza VALUES('E1168','3','Laboring on Jesus this practical way —<br/>Praying His Word in the spirit each day,<br/>Foll''wing His living anointing within,<br/>Built up with others, the church life to win.<br/>',NULL,6124,6124);
INSERT INTO stanza VALUES('E1168','4','Laboring on Jesus yields reality,<br/>Meetings of fullness for all men to see;<br/>There God and man are indeed satisfied,<br/>And there God''s presence cannot be denied.<br/>',NULL,6125,6125);
INSERT INTO stanza VALUES('E1168','5','Labor on Jesus to have Him increased!<br/>Then seek God''s dwelling and come to the feast!<br/>There bring and offer your surplus to God,<br/>There eat the riches, rejoice in the Lord!<br/>',NULL,6126,6126);
INSERT INTO stanza VALUES('E1169','1','Our worship in reality<br/>Is typified in Moses'' law:<br/>With Canaan''s produce, rich and sweet,<br/>All Israel came and worshipped God.<br/>',NULL,6127,6127);
INSERT INTO stanza VALUES('E1169','2','''Tis thus that we must come today<br/>To worship in reality:<br/>When we bring Christ as produce sweet<br/>God fully satisfied will be.<br/>',NULL,6128,6128);
INSERT INTO stanza VALUES('E1169','3','The worship that God so desired<br/>Was not with manna sent from heav''n,<br/>But from their labor on the land<br/>The people''s gifts to God were giv''n.<br/>',NULL,6129,6129);
INSERT INTO stanza VALUES('E1169','4','Thus, what God go desires today.<br/>Are not the miracles so grand,<br/>But daily, normal life in Christ,<br/>As worship, produce of the land.<br/>',NULL,6130,6130);
INSERT INTO stanza VALUES('E1169','5','The manna came from God alone;<br/>The produce, from man''s work on Him.<br/>So all our worship now must come<br/>From mingling with the Lord within.<br/>',NULL,6131,6131);
INSERT INTO stanza VALUES('E1169','6','As day by day we live in Christ,<br/>And take Him as our everything,<br/>The produce of the land comes forth<br/>And worship true to God we''ll bring.<br/>',NULL,6132,6132);
INSERT INTO stanza VALUES('E1169','7','The manna, Lord, no more we''ll seek,<br/>But Christ in all we will apply;<br/>Then we will have some produce sweet,<br/>Thine own dear heart to satisfy.<br/>',NULL,6133,6133);
INSERT INTO stanza VALUES('E1170','1','The Lord is my Shepherd forever,<br/>He maketh me down to lie,<br/>He leads me beside the still waters<br/>O how He does satisfy!<br/>',NULL,6134,6134);
INSERT INTO stanza VALUES('E1170','chorus','Surely goodness and mercy shall follow me<br/>All the days, all the days of my life;<br/>Surely goodness and mercy shall follow me<br/>All the days, all the days of my life;<br/>And I shall dwell in the house of the Lord forever,<br/>And I shall feast at the table spread for me;<br/>Surely goodness and mercy shall follow me<br/>All the days, all the days of my life;<br/>',NULL,6135,6135);
INSERT INTO stanza VALUES('E1170','2','My Shepherd Himself is my pasture,<br/>My Shepherd, the waters of rest;<br/>I eat of His riches in spirit,<br/>I drink, and O how I am blest!<br/>',NULL,6136,6136);
INSERT INTO stanza VALUES('E1170','3','My Shepherd my soul is restoring,<br/>My will, and emotion, and mind;<br/>And though through the valley I''m walking,<br/>O what a Companion I find!<br/>',NULL,6137,6137);
INSERT INTO stanza VALUES('E1170','4','A table prepared by my Shepherd<br/>I feast on and Satan destroy;<br/>My head is anointed with oil,<br/>My cup runneth over with joy!<br/>',NULL,6138,6138);
INSERT INTO stanza VALUES('E1170','5','And now in His house I am dwelling<br/>Enjoying the goodness of God;<br/>My pleasure is far beyond telling,<br/>My pleasure is Jesus my Lord!<br/>',NULL,6139,6139);
INSERT INTO stanza VALUES('E1171','1','In the Testament of old<br/>See th'' acacia wood with gold;<br/>Such humanity behold!<br/>Praise the Lord, praise the Lord,<br/>praise the Lord!<br/>',NULL,6140,6140);
INSERT INTO stanza VALUES('E1171','2','Jesus is th'' acacia wood —<br/>What a man, so fine and good!<br/>All corruption, He withstood —<br/>Praise the Lord, praise the Lord,<br/>praise the Lord!<br/>',NULL,6141,6141);
INSERT INTO stanza VALUES('E1171','3','Jesus, wisdom of God''s plan,<br/>Son of God and Son of Man;<br/>A new manhood He began —<br/>Praise the Lord, praise the Lord,<br/>praise the Lord!<br/>',NULL,6142,6142);
INSERT INTO stanza VALUES('E1171','4','For since by the one came death,<br/>By this man came living breath;<br/>Man the Lord recovereth —<br/>Praise the Lord, praise the Lord,<br/>praise the Lord!<br/>',NULL,6143,6143);
INSERT INTO stanza VALUES('E1171','5','Types and shadows to us show<br/>Jesus is the man to know.<br/>Now this man in us must grow —<br/>Amen Lord! Amen Lord! Amen, Lord!<br/>',NULL,6144,6144);
INSERT INTO stanza VALUES('E1171','6','Lord, may Thy humanity<br/>Permeate us thoroughly,<br/>Drawing many men to Thee —<br/>Amen Lord! Amen Lord! Amen, Lord!<br/>',NULL,6145,6145);
INSERT INTO stanza VALUES('E1172','1','Lo, the conflict of the ages<br/>Is upon us today,<br/>And the forces of rebellion<br/>Are in total array.<br/>The humanity of Jesus<br/>Now the saints must possess,<br/>His true image and dominion<br/>On the earth to express.<br/>',NULL,6146,6146);
INSERT INTO stanza VALUES('E1172','chorus','Let us stand up in Jesus<br/>In His full human life,<br/>Human virtues prevailing<br/>''Gainst corruption so rife;<br/>In this wickedness concerted,<br/>In this age perverse, perverted,<br/>The humanity of Jesus<br/>Must the church now display.<br/>',NULL,6147,6147);
INSERT INTO stanza VALUES('E1172','2','Lo, how Satan came to damage<br/>Human life on the earth;<br/>But the Lord in all this ruin<br/>Raised a man full of worth!<br/>From the seed of the woman<br/>God incarnated became<br/>The man Jesus-the last Adam —<br/>To destroy Satan''s aim!<br/>',NULL,6148,6148);
INSERT INTO stanza VALUES('E1172','3','It''s by calling, drinking, eating<br/>The man Jesus today,<br/>His humanity enjoying<br/>Bruises Satan each day.<br/>To the Lord we must be turning,<br/>All our soul life deny,<br/>To destroy all Satan''s working<br/>And the new man supply.<br/>',NULL,6149,6149);
INSERT INTO stanza VALUES('E1172','4','See the ruin of a nation<br/>Going downward in sin;<br/>All humanity is fallen<br/>And corrupted within.<br/>But as children of the kingdom<br/>We are salting the earth;<br/>His humanity preserves us<br/>In the midst of such dearth.<br/>',NULL,6150,6150);
INSERT INTO stanza VALUES('E1173','1','Grant us a vision clear to see<br/>We need a new humanity;<br/>From all our nature, we must be free;<br/>Eating of Jesus is the key!<br/>',NULL,6151,6151);
INSERT INTO stanza VALUES('E1173','chorus','Breathing this man within the Word,<br/>Calling with them who call "O Lord";<br/>Eating this man in one accord —<br/>Breathe, call and eat!<br/>',NULL,6152,6152);
INSERT INTO stanza VALUES('E1173','2','Our flesh for building is no good;<br/>God''s house must have acacia wood!<br/>Christ''s human life is balanced and fine,<br/>And it''s adorned with gold divine.<br/>',NULL,6153,6153);
INSERT INTO stanza VALUES('E1173','chorus','We want to stand as boards so strong,<br/>Held by the bars where we belong;<br/>To be the church for which You long —<br/>One full-grown man!<br/>',NULL,6154,6154);
INSERT INTO stanza VALUES('E1173','3','Satan''s one aim: to ruin man,<br/>Man, who''s the center of God''s plan!<br/>But man will rule the earth utterly,<br/>Conquering every enemy.<br/>',NULL,6155,6155);
INSERT INTO stanza VALUES('E1173','chorus','Each time we turn and eat this man<br/>We put an end to Satan''s plan.<br/>Jesus through His humanity<br/>Has conquered all!<br/>',NULL,6156,6156);
INSERT INTO stanza VALUES('E1174','1','What a victory! What a triumph!<br/>God Himself became a man,<br/>Clothed Himself in human nature<br/>To fulfill His mighty plan.<br/>He through death destroyed the devil;<br/>Risen now, the Son of Man!<br/>',NULL,6157,6157);
INSERT INTO stanza VALUES('E1174','2','Jesus by His human virtues<br/>Did the subtle one arrest;<br/>He as man withstood the tempter,<br/>Fully passed through every test.<br/>Now in spirit I can take Him,<br/>All His virtues to possess.<br/>',NULL,6158,6158);
INSERT INTO stanza VALUES('E1174','3','In the Spirit of this Jesus<br/>Is His human life so fine.<br/>Human virtues have been added<br/>To the Spirit all divine.<br/>What abundance in this Spirit,<br/>Rich supply for all mankind!<br/>',NULL,6159,6159);
INSERT INTO stanza VALUES('E1174','4','How mysterious! Yet how real!<br/>Such a man now lives in me.<br/>Into all my heart He''s spreading —<br/>He, my human life, to be.<br/>Hallelujah! Hallelujah!<br/>I will praise unceasingly.<br/>',NULL,6160,6160);
INSERT INTO stanza VALUES('E1174','5','Oh, what wonder! Oh, how glorious!<br/>God in flesh is manifest.<br/>We the members of His Body<br/>His humanity express.<br/>For the building of God''s dwelling<br/>We His human life possess.<br/>',NULL,6161,6161);
INSERT INTO stanza VALUES('E1175','1','Power, exceeding great pow''r is to us,<br/>To us who believe, us who receive!<br/>Power that raised Christ, yes, pow''r glorious<br/>Is giv''n to His Body, the church!<br/>',NULL,6162,6162);
INSERT INTO stanza VALUES('E1175','chorus','There is pow''r, pow''r, resurrection pow''r,<br/>To the church, to the church!<br/>There is pow''r, pow''r, resurrection pow''r,<br/>Given to His Body, the church!<br/>',NULL,6163,6163);
INSERT INTO stanza VALUES('E1175','2','Power that set Christ at God''s own right hand,<br/>This pow''r is to us — yes, even us!<br/>Power above every name that is named<br/>Is giv''n to His Body, the church!<br/>',NULL,6164,6164);
INSERT INTO stanza VALUES('E1175','chorus','There is pow''r, pow''r, all-transcending pow''r,<br/>To the church, to the church!<br/>There is pow''r, pow''r, all-transcending pow''r,<br/>Given to His Body, the church!<br/>',NULL,6165,6165);
INSERT INTO stanza VALUES('E1175','3','Power that put all things under His feet<br/>Is ours here and now — right here and now!<br/>Power subjecting all, power complete,<br/>Is giv''n to His Body, the church!<br/>',NULL,6166,6166);
INSERT INTO stanza VALUES('E1175','chorus','There is pow''r, pow''r, all-subduing pow''r,<br/>To the church, to the church!<br/>There is pow''r, pow''r, all-subduing pow''r,<br/>Given to His Body, the church!<br/>',NULL,6167,6167);
INSERT INTO stanza VALUES('E1175','4','Power that made Him o''er all things the Head<br/>Is now to the church, now to the church!<br/>Power, such pow''r, will be exhibited<br/>O''er all through His Body, the church!<br/>',NULL,6168,6168);
INSERT INTO stanza VALUES('E1175','chorus','There is pow''r, pow''r, overruling pow''r,<br/>To the church, to the church!<br/>There is pow''r, pow''r, overruling pow''r,<br/>Given to His Body, the church!<br/>',NULL,6169,6169);
INSERT INTO stanza VALUES('E1176','1','Pow''r exceeding great God did demonstrate<br/>When He raised His Son from the dead.<br/>May this pow''r we see, with it strengthened be,<br/>And in resurrection life be led.<br/>',NULL,6170,6170);
INSERT INTO stanza VALUES('E1176','chorus','Power, power, resurrection power,<br/>Energize us mightily within!<br/>Power, power, resurrection power,<br/>Energize us in the inner man!<br/>',NULL,6171,6171);
INSERT INTO stanza VALUES('E1176','2','Pow''r exceeding high God did magnify<br/>When He raised His Son far above all.<br/>Principalities, pow''rs, and majesties<br/>At the name of Jesus Christ must fall.<br/>',NULL,6172,6172);
INSERT INTO stanza VALUES('E1176','chorus','Power, power, all-transcending power,<br/>Elevate us mightily within!<br/>Power, power, all-transcending power,<br/>Elevate us in the inner man!<br/>',NULL,6173,6173);
INSERT INTO stanza VALUES('E1176','3','Pow''r surpassing too, all things to subdue<br/>Has been given to Christ, pow''r complete.<br/>We His Body are; so, hallelujah,<br/>Everything must be beneath our feet!<br/>',NULL,6174,6174);
INSERT INTO stanza VALUES('E1176','chorus','Power, power, all-subduing power,<br/>All-subjecting mightily within!<br/>Power, power, all-subduing power,<br/>All-subjecting to the inner man!<br/>',NULL,6175,6175);
INSERT INTO stanza VALUES('E1176','4','And the best of all, overruling all,<br/>O''er all to the church Christ is Head.<br/>Pow''r so glorious over all''s to us;<br/>To the highest place the church is led.<br/>',NULL,6176,6176);
INSERT INTO stanza VALUES('E1176','chorus','Power, power, overruling power,<br/>Ruling over all, without, within!<br/>Power, power, overruling power,<br/>Ruling, reigning, through the inner man!<br/>',NULL,6177,6177);
INSERT INTO stanza VALUES('E1177','1','Oh, Christ in all His glory put on humanity<br/>So He could be my Person, and live instead of me.<br/>A man in life and being, He fully fits my case,<br/>So all His glorious Person can me replace.<br/>',NULL,6178,6178);
INSERT INTO stanza VALUES('E1177','chorus','O Lord, O Lord, You are the man for me!<br/>I take You as my Person, as my full identity.<br/>O Lord, O Lord, subdue my every part,<br/>And every moment, every place, make<br/>home in all my heart.<br/>',NULL,6179,6179);
INSERT INTO stanza VALUES('E1177','2','Oh, Christ became the Spirit to speak inside of me,<br/>And as the speaking Spirit He speaks unceasingly.<br/>His speaking is the water that washes me within,<br/>Discharging all my oldness, imparting Him.<br/>',NULL,6180,6180);
INSERT INTO stanza VALUES('E1177','chorus','O Lord, O Lord, speak all You want to me.<br/>Your speaking is Your presence — I must<br/>have it constantly.<br/>O Lord, O Lord, speak-wash my every part<br/>And by this metabolic change, make<br/>home in all my heart.<br/>',NULL,6181,6181);
INSERT INTO stanza VALUES('E1177','3','Oh, Christ will come, the Bridegroom, for<br/>us, His glorious Bride,<br/>By coming from within us the church is glorified.<br/>His Person is the glory expanding now in us;<br/>This glory is our Person — how glorious!<br/>',NULL,6182,6182);
INSERT INTO stanza VALUES('E1177','chorus','O Lord, O Lord, by Your economy<br/>So flood us with Your glory, saturate us thoroughly.<br/>Come out, come out, break forth in glory here,<br/>And for the church, O glorious One, in<br/>glory soon appear.<br/>',NULL,6183,6183);
INSERT INTO stanza VALUES('E1178','1','We have seen Christ is reality:<br/>But it''s not sufficient just to see:<br/>He in our experience must be<br/>Everything to us.<br/>We in prayer behold Him face to face,<br/>In the Word and meetings know His grace;<br/>But in daily life, in every place,<br/>What is He to us?<br/>',NULL,6184,6184);
INSERT INTO stanza VALUES('E1178','chorus','Hallelujah! By His light we see<br/>Oh, how real, how full our Lord will be<br/>If we''ll only turn to Him at every time, in every day,<br/>Every thing, in every way and —<br/>Be specific for reality!<br/>And be done with generality!<br/>If we''ll just apply Him, we will see<br/>He''s everything to us.<br/>',NULL,6185,6185);
INSERT INTO stanza VALUES('E1178','2','Life is full of opportunities<br/>Ordered by our Father''s hand: we see<br/>Everything''s the best that it could be,<br/>So let''s gain Christ!<br/>Christ our content and reality<br/>To shine out from us unceasingly:<br/>He must have a way in you and me,<br/>He must have a way.<br/>',NULL,6186,6186);
INSERT INTO stanza VALUES('E1178','chorus','Hallelujah! In the body we<br/>Bear the death of Christ continually:<br/>Thus His life comes forth for all to see as<br/>The outer man is broken down,<br/>The inner man is shining so that —<br/>In these earthen vessels men can see<br/>There''s the treasure of reality!<br/>Thus the gospel''s glorious light will be<br/>Shining out from us.<br/>Not just doctrines and theology,<br/>But the content of reality:<br/>Christ as everything in you and me<br/>He''s everything to us!<br/>',NULL,6187,6187);
INSERT INTO stanza VALUES('E1179','1','My old man has been crucified with Him,<br/>With all its foul corruption deep within;<br/>And buried too its nature serpentine,<br/>Completely finished — this great fact is mine,<br/>I hold it fast.<br/>',NULL,6188,6188);
INSERT INTO stanza VALUES('E1179','2','But there''s a Person in my spirit now,<br/>Born as a babe so small, so weak, so low;<br/>Who by the Word''s pure milk will grow to be<br/>The overcoming inner man in me<br/>To gain my heart.<br/>',NULL,6189,6189);
INSERT INTO stanza VALUES('E1179','3','Christ as my Person must posses my heart<br/>And be preeminent in every part.<br/>The former owner died but haunts it still.<br/>O Lord, move in; my mind, emotion, will<br/>Now welcome Thee.<br/>',NULL,6190,6190);
INSERT INTO stanza VALUES('E1179','4','In spirit mingled, we are one, O Lord,<br/>The human and divine in one accord;<br/>Yet Thou must have a proper faculty<br/>That all Thy glorious personality<br/>May be expressed.<br/>',NULL,6191,6191);
INSERT INTO stanza VALUES('E1179','5','So, Lord, I give my heart to Thee today,<br/>That it may be Thy home in every way,<br/>A place for Thee to come and settle down,<br/>And all Thy grand recovery work to crown<br/>In one new man.<br/>',NULL,6192,6192);
INSERT INTO stanza VALUES('E1180','1','My old person has been nullified;<br/>With my Lord upon the cross he died;<br/>Now in nothing shall he be applied;<br/>He''s dead to me.<br/>My new Person in my spirit dwells;<br/>Springing in me as a bubbling well;<br/>Flowing out until each part He fills<br/>With abundant life.<br/>',NULL,6193,6193);
INSERT INTO stanza VALUES('E1180','chorus','Christ, my Person, in my spirit lives;<br/>And my heart to Him I''d daily give;<br/>That my inner man could have a home<br/>And a place to settle down, yes,<br/>A place to call His own, and —<br/>There be my complete reality,<br/>There expressing all He is to me,<br/>Living in my heart abundantly<br/>As my Person real.<br/>',NULL,6194,6194);
INSERT INTO stanza VALUES('E1180','2','By this Person being formed in me,<br/>I''ll a member of His Body be,<br/>No more acting individually,<br/>But with the saints.<br/>More and more our Person He must be;<br/>That our natural personality<br/>Be eliminated thoroughly<br/>Till Christ is all.<br/>',NULL,6195,6195);
INSERT INTO stanza VALUES('E1180','chorus','Only Christ, our Person, must remain;<br/>From our aims, our goals we must refrain,<br/>Till the church be only Christ Himself<br/>Built up as the one new man,<br/>Thus fulfilling God''s great plan of —<br/>Mingling fully with the human race<br/>To obtain a proper dwelling place,<br/>''Stablishing His kingdom''s rule and grace;<br/>Over all the earth.<br/>Not Himself just individually,<br/>But the church together corporately,<br/>Taking Christ as all in all, to be<br/>The full-grown, perfect man.<br/>',NULL,6196,6196);
INSERT INTO stanza VALUES('E1181','1','Lord, to know Thee as our Person,<br/>Earnestly we seek and pray;<br/>To experience Thy fulness<br/>In a constant inner way.<br/>Never longer only outward<br/>Or with soulish thoughts obsessed,<br/>But, O Lord, in realest contact<br/>We by Thee would be possessed.<br/>',NULL,6197,6197);
INSERT INTO stanza VALUES('E1181','chorus','Lord, Thou art our Person,<br/>In our inmost being,<br/>May we constantly experience<br/>This reality.<br/>',NULL,6198,6198);
INSERT INTO stanza VALUES('E1181','2','All the world is under darkness,<br/>Driven by the fallen soul,<br/>And the enemy designing<br/>Does the soulish life control.<br/>Such we were till God, through mercy,<br/>Caused His Son to dwell in us;<br/>Now we fully come to know Him<br/>In His church so glorious.<br/>',NULL,6199,6199);
INSERT INTO stanza VALUES('E1181','3','Once we walked a soulish person,<br/>Wandering in the wilderness,<br/>Never knowing that our spirit<br/>Craved God''s fullness to express;<br/>At the moment Jesus entered<br/>Instantly the whole was changed.<br/>Now we''re people spirit-centered!<br/>Hallelujah! Rearranged!<br/>',NULL,6200,6200);
INSERT INTO stanza VALUES('E1181','4','Now our spirit is our person —<br/>What a glorious fact is this!<br/>Christ Himself in us expressing<br/>God''s intent and holiness.<br/>Not the soul-life''s vain delusion,<br/>But the spirit strengthened is;<br/>Christ Himself is now our Person —<br/>He is ours and we are His.<br/>',NULL,6201,6201);
INSERT INTO stanza VALUES('E1182','1','In spirit and reality<br/>We meet to worship Thee,<br/>And every principality<br/>Must fall down or must flee.<br/>Reality, reality,<br/>O what a joy to see,<br/>That Christ may be enjoyed by us<br/>As our reality.<br/>',NULL,6202,6202);
INSERT INTO stanza VALUES('E1182','2','A Person, Thou hast come in us,<br/>Into our spirit now,<br/>And quickened us until we know<br/>Our inner man art Thou.<br/>O praise Thee, Lord, we sense Thee thus,<br/>Forever inwardly;<br/>Thy Person in each one of us<br/>Is our reality.<br/>',NULL,6203,6203);
INSERT INTO stanza VALUES('E1182','3','And now the corporate life we live —<br/>Christ in His Body known;<br/>Where every portion adds more Christ,<br/>Until the whole is shown.<br/>O Hallelujah, one new man!<br/>Our portions blend as one;<br/>In one accord, express the Lord,<br/>And He will quickly come.<br/>',NULL,6204,6204);
INSERT INTO stanza VALUES('E1183','1','On the Lord''s day, John, in spirit,<br/>Heard a voice and turned and saw<br/>Seven lampstands brightly shining;<br/>Of pure gold, divine, they were.<br/>In the midst of them, appearing,<br/>He beheld the Son of Man,<br/>Ever for the churches caring,<br/>Tending God''s eternal plan.<br/>',NULL,6205,6205);
INSERT INTO stanza VALUES('E1183','2','His appearance, lo, how different<br/>From the One John knew before.<br/>Now He''s girt in golden raiment,<br/>Not the robe which then He wore.<br/>Girt about the breasts and serving,<br/>He the priesthood fully bears;<br/>Cherishing the lampstands dearly,<br/>He for all the churches cares.<br/>',NULL,6206,6206);
INSERT INTO stanza VALUES('E1183','3','Ancient One He is, yet fresher<br/>Than the newly driven snow;<br/>Eyes are as a flaming fire,<br/>Feet as burnished brass aglow.<br/>Tender eyes that gazed at Peter,<br/>Now are as a burning flame;<br/>And the voice that whispered, "Mary,"<br/>Many waters now became.<br/>',NULL,6207,6207);
INSERT INTO stanza VALUES('E1183','4','John, once formerly reclining<br/>On His breast, now fell as dead,<br/>When he saw Him thus in spirit,<br/>As He is, exhibited.<br/>Lo, the Christ of Revelation!<br/>See Him, thus intensified,<br/>That the lampstands, His expression,<br/>May be strengthened and supplied.<br/>',NULL,6208,6208);
INSERT INTO stanza VALUES('E1184','1','In Revelation chapter one<br/>God gives a vision of the Son,<br/>Of Him who was and is to come;<br/>Oh, let us to this One now come.<br/>',NULL,6209,6209);
INSERT INTO stanza VALUES('E1184','2','In spirit hear His trumpet voice;<br/>We must be turned to see His choice —<br/>The seven lampstands golden fair;<br/>The Son of Man is walking there.<br/>',NULL,6210,6210);
INSERT INTO stanza VALUES('E1184','3','The great high priestly robe He wears,<br/>For every church He fully cares:<br/>He trims the lamp, the oil supplies;<br/>He makes them burn, flames in His eyes.<br/>',NULL,6211,6211);
INSERT INTO stanza VALUES('E1184','4','A golden girdle on His breast —<br/>His work is done, and from His rest<br/>He unto all the churches pours<br/>Himself in love, the treasure store.<br/>',NULL,6212,6212);
INSERT INTO stanza VALUES('E1184','5','His head, His hair is white as wool —<br/>The ancient One with youth is full.<br/>His face is shining as the sun<br/>To burn and lighten every one.<br/>',NULL,6213,6213);
INSERT INTO stanza VALUES('E1184','6','Oh, when this living One we see,<br/>We''ll fall as dead, we''ll finished be.<br/>But then the Lord His comfort gives —<br/>He once was dead, but now He lives.<br/>',NULL,6214,6214);
INSERT INTO stanza VALUES('E1184','7','Let every church just love Him more —<br/>His riches then He will outpour.<br/>All other loves now lay aside;<br/>Let''s take this Jesus, none beside.<br/>',NULL,6215,6215);
INSERT INTO stanza VALUES('E1185','1','In the multitude he lay there<br/>With a sickness many years;<br/>Impotent and lying helpless,<br/>Every fraught with many fears.<br/>Waiting for the water''s moving,<br/>Waiting for the angel''s stir;<br/>Powerless to move, however,<br/>Helpless, hopeless, lying there.<br/>',NULL,6216,6216);
INSERT INTO stanza VALUES('E1185','2','At this pool how clear the picture<br/>Of the hopeless case of all<br/>Who are seeking self-perfection<br/>To recover from the fall.<br/>Though the law is good and holy,<br/>Flesh, to keep the law, is dead;<br/>What we need is not religion,<br/>But the Word of life instead.<br/>',NULL,6217,6217);
INSERT INTO stanza VALUES('E1185','3','Though it''s feast day, he''s not happy,<br/>Though the Sabbath, there''s no rest;<br/>Lying in his poor condition,<br/>Miserable and sore depressed.<br/>At that moment Jesus saw him,<br/>Knowing he was thus so long.<br/>"Will you be made whole?" He asked him,<br/>"Healed and walking, well and strong?''<br/>',NULL,6218,6218);
INSERT INTO stanza VALUES('E1185','4','Though he told his hopeless story,<br/>Scarce believing what he''d heard,<br/>Yet, soon to his feet arising,<br/>He received the living word.<br/>This is all our situation,<br/>We — like him — were lying there<br/>In the sheep-fold of religion,<br/>Under law''s prevailing care.<br/>',NULL,6219,6219);
INSERT INTO stanza VALUES('E1185','5','While we yet were weak and helpless,<br/>Christ the Son of God did come.<br/>By His word we''re now enlivened;<br/>He''s the life-imparting One!<br/>Hallelujah for this Jesus,<br/>He''s the Word of life to men;<br/>For law''s bondage He releases,<br/>Death is turned to life again!<br/>',NULL,6220,6220);
INSERT INTO stanza VALUES('E1186','1','The scribes and Pharisees all thought<br/>A leader great would come.<br/>So they to John the Baptist came<br/>To ask if he''s the One.<br/>"Art Thou the coming One?'' they asked,<br/>To which he made reply:<br/>"I''m not the Christ — I am not He —<br/>A voice, that''s all, am I."<br/>',NULL,6221,6221);
INSERT INTO stanza VALUES('E1186','2','And on the morrow, John stood there<br/>And spoke to two or three.<br/>And as he lifted up his eyes,<br/>He then did Jesus see.<br/>He said, "Behold the Lamb of God,<br/>''Tis He Who walks this way.<br/>He''s here to take the sins of all<br/>And bear them all away!"<br/>',NULL,6222,6222);
INSERT INTO stanza VALUES('E1186','3','Yet poor religion counted not<br/>These things of any worth,<br/>But seeking for a leader great<br/>It lingered on in dearth;<br/>And looking for a movement strong,<br/>Continued in its strife.<br/>Preoccupied with these things,<br/>They missed the Lord of LIFE!<br/>',NULL,6223,6223);
INSERT INTO stanza VALUES('E1186','4','Religion is Christ''s enemy,<br/>It''s even so today.<br/>For though they name Him, should He come,<br/>They''d put the Lord away.<br/>They did it then, they''d do it now,<br/>They''d miss the Lord again.<br/>So let us seek the Lord Himself,<br/>The lamb, the dove obtain.<br/>',NULL,6224,6224);
INSERT INTO stanza VALUES('E1186','5','Now in the Lord''s recovery<br/>We''re drawn to Christ alone.<br/>The Spirit as the gentle dove<br/>Has found in us a home.<br/>Let all religion turn away<br/>To movements wide and great;<br/>This testimony of Himself<br/>Our Lord will vindicate!<br/>',NULL,6225,6225);
INSERT INTO stanza VALUES('E1187','1','Your ministry, O Lord,<br/>How excellent it is;<br/>A better covenant,<br/>And better promises;<br/>Enacted on a better law.<br/>Of such You are Executor.<br/>',NULL,6226,6226);
INSERT INTO stanza VALUES('E1187','2','A better covenant,<br/>And better promises;<br/>A better law of life<br/>And sacrifice this is.<br/>Redemption''s work, done long ago,<br/>A better blood has made it so.<br/>',NULL,6227,6227);
INSERT INTO stanza VALUES('E1187','3','In Hebrews eight we see<br/>The way to make us whole;<br/>Life planted deep within,<br/>Which spreads into the soul.<br/>The law of life, imparted, still<br/>Inscribed in mind, emotion, will.<br/>',NULL,6228,6228);
INSERT INTO stanza VALUES('E1187','4','The law of letters leave,<br/>The law of life pursue;<br/>The one is old and dead,<br/>The other fresh and new.<br/>Dead teachings cannot help the seed;<br/>The law of life is what we need.<br/>',NULL,6229,6229);
INSERT INTO stanza VALUES('E1187','5','The law of life in us,<br/>In function now we see,<br/>Works not by will and thought<br/>But automatically.<br/>It saturates, conforms to Him;<br/>The standard model spreads within.<br/>',NULL,6230,6230);
INSERT INTO stanza VALUES('E1187','6','Our sins are all forgiv''n,<br/>His life imparted too;<br/>God is our God today,<br/>And we''re His people true.<br/>We know Him in an inward way:<br/>These blessings four have come to stay.<br/>',NULL,6231,6231);
INSERT INTO stanza VALUES('E1187','7','We''re being sonized now;<br/>The life within will do<br/>The deep transforming work<br/>Of making us anew.<br/>In ages past, the work was done —<br/>Now prayer is over — praise the Son!<br/>',NULL,6232,6232);
INSERT INTO stanza VALUES('E1188','1','Upon the throne of Jesus Christ<br/>We''ve taken up our seat.<br/>The world and Satan, sin and self<br/>Are all beneath our feet!<br/>Christ''s finished work did put us here.<br/>When once for all He died;<br/>No more are we the sinners poor,<br/>We''re fully glorified.<br/>',NULL,6233,6233);
INSERT INTO stanza VALUES('E1188','2','We''re dwelling in the house of God,<br/>The church life glorious.<br/>The shrinking-back, low Christian life,<br/>Is not the life for us!<br/>We''re passing through the Holy Place<br/>Of mind, emotion, will;<br/>We''re dwelling in the Holiest<br/>Where God our being fills.<br/>',NULL,6234,6234);
INSERT INTO stanza VALUES('E1188','3','We''re under the New Covenant,<br/>With glorious items, three:<br/>The law of life, spontaneous,<br/>Transforming utterly;<br/>We are His people, He''s our God —<br/>Oh, bless''d reality;<br/>We all are fully able now<br/>To know God inwardly.<br/>',NULL,6235,6235);
INSERT INTO stanza VALUES('E1188','4','A supplement God added then;<br/>This item we must know:<br/>Christ Jesus did put sin away<br/>Two thousand years ago.<br/>No memory of sin at all,<br/>It''s hist''ry, done and gone;<br/>In spirit now the law of life<br/>Will take us swiftly one.<br/>',NULL,6236,6236);
INSERT INTO stanza VALUES('E1188','5','Two things accomplished by our Lord<br/>On Calvary''s cross, we see:<br/>The law of life, the end of sin!<br/>Our God''s economy.<br/>Since all His work was finished there,<br/>He entered into rest;<br/>Now on the throne He prays that we<br/>Will take our full bequest.<br/>',NULL,6237,6237);
INSERT INTO stanza VALUES('E1188','6','We''ll drop our former concepts, Lord,<br/>To take this finished way;<br/>Appropriating each bequest,<br/>We''ll praise You more each day.<br/>We''ll heed our High Priest''s inward call —<br/>"Come forward!" to the end —<br/>Until we reach the final goal;<br/>The New Jerusalem!<br/>',NULL,6238,6238);
INSERT INTO stanza VALUES('E1189','1','Son of Man, Son of Man on the throne today;<br/>Son of Man, Pioneer, He has led the way;<br/>Following, how we sing, Jesus leads us on;<br/>We are marching with the Victor to the throne.<br/>',NULL,6239,6239);
INSERT INTO stanza VALUES('E1189','2','On we go, on we go to the throne with Him;<br/>On we go, through this age, age so dark and grim;<br/>Then shall we-formerly, Satan''s captured ones —<br/>Be exalted with the Lord upon His throne.<br/>',NULL,6240,6240);
INSERT INTO stanza VALUES('E1189','3','Called as sons, called as sons, destined to be kings;<br/>Called as sons, we''ve no time for the worldly things:<br/>Yet we know, it is so — we don''t qualify!<br/>Thus the Lord must search and burn and purify.<br/>',NULL,6241,6241);
INSERT INTO stanza VALUES('E1189','4','Search and burn, search and burn all our inward parts;<br/>Search and burn, thoroughly, to refine our hearts;<br/>We''ll not fear, but be clear — burning, searching thus<br/>Is the gracious visit of the Lord to us.<br/>',NULL,6242,6242);
INSERT INTO stanza VALUES('E1189','5','With the Man, with the Man is a rainbow fair;<br/>Glorious bow, ''round the throne, faithfulness declares:<br/>We deserved to be served with God''s judgment sore.<br/>But we have been spared to praise Him more and more.<br/>',NULL,6243,6243);
INSERT INTO stanza VALUES('E1190','1','O Lord, You''ve called to us, and Canaan we would win,<br/>To be Your corporate man and dwell with You therein;<br/>But how the darkness of this world does hold us in —<br/>O Lord, appear to us, we pray.<br/>',NULL,6244,6244);
INSERT INTO stanza VALUES('E1190','chorus','O Lord, appear to us today;<br/>We see this is the only way.<br/>The idols to forsake<br/>And Canaan land partake,<br/>O Lord, appear to us today.<br/>',NULL,6245,6245);
INSERT INTO stanza VALUES('E1190','2','O God of glory, shine; draw and we''ll follow You.<br/>Our strength and motive be, it''s nothing we could do.<br/>Your light attracts us, Lord, ''til all else fades from view —<br/>O Lord, do shine on us, we pray.<br/>',NULL,6246,6246);
INSERT INTO stanza VALUES('E1190','chorus','O Lord, do shine on us today;<br/>Till all our background fades away,<br/>Till You alone we see,<br/>Shining so gloriously —<br/>O Lord, so shine on us today.<br/>',NULL,6247,6247);
INSERT INTO stanza VALUES('E1190','3','In Your appearing, Lord, we have Your speaking clear;<br/>Your word empowers us and drives away all fear.<br/>So, Lord, keep calling us, Your voice we need to hear.<br/>O Lord, do speak to us, we pray.<br/>',NULL,6248,6248);
INSERT INTO stanza VALUES('E1190','chorus','O Lord, do speak in us today;<br/>You know the words You need to say.<br/>To open all our heart, Your very Self impart.<br/>O Lord, do speak in us today.<br/>',NULL,6249,6249);
INSERT INTO stanza VALUES('E1190','4','O Lord, it''s not of us, we''ve seen it''s all of You;<br/>You are the calling One, Originator too!<br/>We can receive this call by our beholding You —<br/>O God of glory, come, we pray.<br/>',NULL,6250,6250);
INSERT INTO stanza VALUES('E1190','chorus','O God of glory, come today;<br/>We''ve seen this is the only way<br/>To answer Your dear call<br/>That You might be our all —<br/>O God of glory, come today.<br/>',NULL,6251,6251);
INSERT INTO stanza VALUES('E1191','1','From my spirit within flows a fountain of life —<br/>The Triune God flowing in me;<br/>God the Father''s the source,<br/>Christ the Son is the course,<br/>And the Spirit imparts life to me.<br/>',NULL,6252,6252);
INSERT INTO stanza VALUES('E1191','chorus','Lord, I treasure the sweet flow of life,<br/>And my soul-life at last I lay down;<br/>O Lord, deepen the pure flow of life;<br/>At Your coming may life be my crown.<br/>',NULL,6253,6253);
INSERT INTO stanza VALUES('E1191','2','In the fresh, tender grass Jesus makes me lie down;<br/>He leads me by waters of rest;<br/>No more struggle and strain; all self-effort is vain;<br/>In the flow I am perfectly blessed.<br/>',NULL,6254,6254);
INSERT INTO stanza VALUES('E1191','3','Jesus called me one day to the Holiest Place,<br/>To live in His presence divine;<br/>Hallelujah, I''ve heard an encouraging word:<br/>"Abide — you''re a branch in the vine."<br/>',NULL,6255,6255);
INSERT INTO stanza VALUES('E1192','1','Chapter one of Genesis:<br/>Life is God''s one emphasis,<br/>Showing Christ subjectively,<br/>Step by step He grows in me.<br/>',NULL,6256,6256);
INSERT INTO stanza VALUES('E1192','2','Just as earth became a waste,<br/>Death and darkness once I faced.<br/>God had judged, no light did shine;<br/>Hollowness and void were mine.<br/>',NULL,6257,6257);
INSERT INTO stanza VALUES('E1192','3','Satan''s fall had filled the seas<br/>With corruption, sin, disease.<br/>Yet the Spirit brooded o''er<br/>The abyss: chaos no more!<br/>',NULL,6258,6258);
INSERT INTO stanza VALUES('E1192','4','God then spoke: the air was cleared!<br/>Darkness which I once had feared<br/>Was dispelled by God''s own light.<br/>A new day! No longer night!<br/>',NULL,6259,6259);
INSERT INTO stanza VALUES('E1192','5','As the light began to shine<br/>His discernment became mine.<br/>I began to see aright;<br/>God divided dark from light.<br/>',NULL,6260,6260);
INSERT INTO stanza VALUES('E1192','6','Then the waters He did split;<br/>An expanse between them fit,<br/>Earthly things from heavenly,<br/>Separated hence they''d be.<br/>',NULL,6261,6261);
INSERT INTO stanza VALUES('E1192','7','One the third day God designed<br/>That the waters be confined.<br/>In our lives dry land must be;<br/>No more death and no more sea!<br/>',NULL,6262,6262);
INSERT INTO stanza VALUES('E1192','8','God commands: death''s water halt!<br/>Christ, the good land, we exalt!<br/>Separated from all strife<br/>We enjoy Christ as our life.<br/>',NULL,6263,6263);
INSERT INTO stanza VALUES('E1192','9','Growing in us inwardly;<br/>Grass, then herb, then fruitful tree.<br/>We begin as but a blade;<br/>Soon our being He''ll pervade.<br/>',NULL,6264,6264);
INSERT INTO stanza VALUES('E1192','10','Then the fourth day lights He set;<br/>Bearers these, more definite.<br/>Richer light to radiate,<br/>Higher life to generate.<br/>',NULL,6265,6265);
INSERT INTO stanza VALUES('E1192','11','Sun, the greater light we see<br/>Ruling day triumphantly;<br/>Yet when darkness fills the skies,<br/>Waxing moon is on the rise!<br/>',NULL,6266,6266);
INSERT INTO stanza VALUES('E1192','12','''Tis the Church she typifies;<br/>For her light on Christ relies.<br/>In His image meant to be,<br/>She reflects Christ perfectly.<br/>',NULL,6267,6267);
INSERT INTO stanza VALUES('E1192','13','Lastly, precious stars He placed,<br/>Strong in spirit, full of grace;<br/>Shining when the moon seems faint,<br/>These are overcoming saints.<br/>',NULL,6268,6268);
INSERT INTO stanza VALUES('E1192','14','What a glorious picture here:<br/>Sun and moon and stars appear!<br/>Lord, our prayer is that we''d be<br/>Full of light and life in Thee.<br/>',NULL,6269,6269);
INSERT INTO stanza VALUES('E1193','1','Life is God the Father in Christ Jesus<br/>As the Spirit flowing into us.<br/>How enjoyable, this Person wonderful!<br/>He''s our life so rich and bountiful.<br/>',NULL,6270,6270);
INSERT INTO stanza VALUES('E1193','2','We experienced regeneration<br/>When we opened to this living One.<br/>We were born again; another life came in.<br/>Now it floods us till we''re full of Him.<br/>',NULL,6271,6271);
INSERT INTO stanza VALUES('E1193','3','He within us is the living Spirit<br/>In our spirit, flowing out of it<br/>Into all our heart, transforming every part<br/>By the life which He Himself imparts.<br/>',NULL,6272,6272);
INSERT INTO stanza VALUES('E1193','4','Now He must have our cooperation.<br/>We must set our mind upon the Son.<br/>We must turn away from all that leads astray,<br/>Till our mind is set on Him each day.<br/>',NULL,6273,6273);
INSERT INTO stanza VALUES('E1193','5','Lord, our human spirit now contains You.<br/>Still Your purpose in us You would do;<br/>If our wandering mind would leave old thoughts behind,<br/>Then Your life and peace in it we''ll find.<br/>',NULL,6274,6274);
INSERT INTO stanza VALUES('E1193','6','Lord, we would our every thought be captured<br/>By the rich enjoyment in Your Word.<br/>In it we''re supplied, our mind there will abide,<br/>Till our thoughts are wholly sanctified.<br/>',NULL,6275,6275);
INSERT INTO stanza VALUES('E1193','7','Let''s keep practicing the application<br/>Of this life by minding just the Son.<br/>Praise Him for the way to live by Him today!<br/>Lord, on You our minds will ever stay.<br/>',NULL,6276,6276);
INSERT INTO stanza VALUES('E1194','1','There are two lines to live by in our living today —<br/>One the life line to bring us into Christ all the way.<br/>But the other is knowledge which will make us die;<br/>We must be very careful on which line we abide.<br/>',NULL,6277,6277);
INSERT INTO stanza VALUES('E1194','chorus','Oh, we''ll stay on God''s life line, never turning aside.<br/>We don''t care for vain knowledge, which will cause us to die.<br/>Lord, we''ll touch You by calling on Your name each day;<br/>Living in Your appearing, in Your presence we''ll stay.<br/>',NULL,6278,6278);
INSERT INTO stanza VALUES('E1194','2','Lord, we would be as Abel, fully contacting You;<br/>Not by knowledge or concept, but by life fresh and new.<br/>Just as Enosh began to call upon Your name,<br/>And as Enoch who walked with You, we''ll do just the same.<br/>',NULL,6279,6279);
INSERT INTO stanza VALUES('E1194','3','Keep us living and walking as did old Abraham;<br/>In Your holy appearing to be transfused like him.<br/>As did Isaac and Jacob, Moses lived this way —<br/>So dependent upon Your presence with him each day.<br/>',NULL,6280,6280);
INSERT INTO stanza VALUES('E1194','4','Full enjoyment had David, ate the life-giving tree.<br/>Daniel prayed to his God and lived by Him constantly.<br/>Jesus lived by the Father to be life complete;<br/>Now as His living Body of the life tree we''ll eat.<br/>',NULL,6281,6281);
INSERT INTO stanza VALUES('E1195','1','Life is mysterious, life is God Himself,<br/>Whose whole intention focuses on man.<br/>God made him to take in the tree of life,<br/>To have a man of life for His own plan.<br/>',NULL,6282,6282);
INSERT INTO stanza VALUES('E1195','2','But man was tempted and seduced to sin,<br/>By taking knowledge from the other source.<br/>This man then fell as knowledge entered in<br/>And dominated him with all its force.<br/>',NULL,6283,6283);
INSERT INTO stanza VALUES('E1195','3','This knowledge has developed in the man<br/>Into the human culture on the earth.<br/>So man, created to fulfill God''s plan,<br/>Became a failure full of Satan''s dearth.<br/>',NULL,6284,6284);
INSERT INTO stanza VALUES('E1195','4','Then God came in the Person of the Son;<br/>Lived He on earth, Christ Jesus was His name —<br/>A living model so that everyone<br/>Could live by life, God''s fullness to obtain.<br/>',NULL,6285,6285);
INSERT INTO stanza VALUES('E1195','5','This God-man, Christ, went to the cross and died,<br/>By death He ended knowledge, the old man.<br/>Things negative forever crucified,<br/>Death He subdued, a new life He began!<br/>',NULL,6286,6286);
INSERT INTO stanza VALUES('E1195','6','From death He resurrected and became<br/>The living Spirit to give life to us.<br/>When we believe and call upon His name;<br/>This living Spirit comes to dwell in us.<br/>',NULL,6287,6287);
INSERT INTO stanza VALUES('E1195','7','By this the very Triune God is now<br/>The living Spirit mingling deep within.<br/>Our spirit joins in oneness; this is how<br/>We are one spirit evermore with Him.<br/>',NULL,6288,6288);
INSERT INTO stanza VALUES('E1195','8','''Tis by this Spirit that we walk and act,<br/>We have our being, think, and see all things;<br/>We''re now within the Spirit! What a fact!<br/>This Spirit to us all God''s fullness brings!<br/>',NULL,6289,6289);
INSERT INTO stanza VALUES('E1195','9','So now we have to set our mind on Him;<br/>Each day, each hour, our mind on Him must be;<br/>That by this Spirit we''d be saved within<br/>By life and reign in life eternally.<br/>',NULL,6290,6290);
INSERT INTO stanza VALUES('E1195','10','''Tis by this Spirit we shall be freed<br/>From Sin whose law inside us death would bring.<br/>Our mortal bodies will have life indeed;<br/>Thus sanctified we''ll be in everything.<br/>',NULL,6291,6291);
INSERT INTO stanza VALUES('E1195','11','This Spirit shall transform our natural life,<br/>Save us from self, build us in one new man,<br/>Till we''re conformed to be like Jesus Christ,<br/>Thus finishing our God''s eternal plan.<br/>',NULL,6292,6292);
INSERT INTO stanza VALUES('E1195','12','Life is our God and life is Christ our Lord.<br/>Life is the Spirit. Life''s the only way —<br/>Till we''re transfigured and redeemed to God.<br/>We''re waiting, looking forward to that day!<br/>',NULL,6293,6293);
INSERT INTO stanza VALUES('E1196','1','Our God is living — say, Hallelujah!<br/>He''s living in us — say, Hallelujah!<br/>We taste His riches,<br/>He is our portion.<br/>Just say ''O Lord'' to taste and see.<br/>',NULL,6294,6294);
INSERT INTO stanza VALUES('E1196','2','We come together — there''s nothing better —<br/>For in the Spirit we are His family;<br/>His living Body!<br/>We just express Him.<br/>Jesus is our reality.<br/>',NULL,6295,6295);
INSERT INTO stanza VALUES('E1196','3','In all the churches we''re being filled now<br/>For the saturation throughout the nation,<br/>To spread our Jesus<br/>To every city —<br/>This land will see the living Christ.<br/>',NULL,6296,6296);
INSERT INTO stanza VALUES('E1197','1','God is light, and in Him there is no darkness at all!<br/>Oh, how we love within His presence to dwell!<br/>In this light we enjoy a constant cleansing within —<br/>From every sin!<br/>',NULL,6297,6297);
INSERT INTO stanza VALUES('E1197','2','Sisters: In the light,<br/>Brothers: We are walking —<br/>Sisters: Fellowship,<br/>Brothers: We''re enjoying;<br/>Sisters: And the blood<br/>Brothers: Of God''s Son<br/>Everyone: Is cleansing us from sin.<br/>',NULL,6298,6298);
INSERT INTO stanza VALUES('E1197','3','Sisters: We confess,<br/>Brothers: He is faithful<br/>Sisters: To forgive —<br/>Brothers: He is righteous.<br/>Sisters: What a joy!<br/>Brothers: We are cleansed<br/>Everyone: From every sin!<br/>',NULL,6299,6299);
INSERT INTO stanza VALUES('E1198','1','A mighty flowing-out is God,<br/>He flows throughout the ages.<br/>And so to flow Himself to man<br/>He is in many stages;<br/>Yet still one God is He,<br/>One flow eternally;<br/>His stages pave the way<br/>To flow through man today,<br/>And now He flows within us!<br/>',NULL,6300,6300);
INSERT INTO stanza VALUES('E1198','2','In the beginning we can see,<br/>God as a flowing river,<br/>The river to convey the tree,<br/>Himself as life deliver.<br/>And at the end the same,<br/>The river doth remain,<br/>God in the Lamb doth flow,<br/>The tree prevails to grow,<br/>And God flows on forever.<br/>',NULL,6301,6301);
INSERT INTO stanza VALUES('E1198','3','God flowed Himself into a man,<br/>The man we call Christ Jesus.<br/>He gave up His own life for man<br/>And God''s own life releases.<br/>Though Satan did his best<br/>To put God''s flow to rest —<br/>He had Him crucified<br/>And cruelly pierced His side —<br/>But out came blood and water!<br/>',NULL,6302,6302);
INSERT INTO stanza VALUES('E1198','4','The blood and water flowed from Him,<br/>In streams of pure salvation.<br/>The blood brings cleansing from all sin;<br/>Water, regeneration.<br/>And now the Spirit flows,<br/>Brings God where''er He goes.<br/>All he could do, the foe,<br/>Was just release the flow.<br/>And God just keeps on flowing.<br/>',NULL,6303,6303);
INSERT INTO stanza VALUES('E1199','1','God''s intention in this universe is with humanity,<br/>So the Lord became the Spirit just with man to mingled be.<br/>We rejoice that we can all partake of His economy.<br/>Yes, mingling is the way.<br/>',NULL,6304,6304);
INSERT INTO stanza VALUES('E1199','chorus','Mingle, mingle, hallelujah,<br/>Mingle, mingle, hallelujah,<br/>Mingle, mingle, hallelujah,<br/>Yes, mingling is the way!<br/>',NULL,6305,6305);
INSERT INTO stanza VALUES('E1199','2','In the center of our being, past our mind, emotion, will,<br/>Is a certain spot created to contain the Lord until<br/>By His flowing and His flooding He will all our being fill;<br/>Yes, mingling is the way.<br/>',NULL,6306,6306);
INSERT INTO stanza VALUES('E1199','3','Now within the Lord''s recov''ry, we''re so glad to find the way<br/>To experience the Triune God and live by Him today —<br/>Get into the mingled spirit, and within the spirit stay;<br/>Yes, mingling is the way.<br/>',NULL,6307,6307);
INSERT INTO stanza VALUES('E1199','4','In the midst of seven lampstands, now the Son of Man we see;<br/>Eyes ablaze and feet a’ burning, He''s for God''s recovery.<br/>God''s intention He''s accomplishing — a corporate entity;<br/>Yes, mingling is the way.<br/>',NULL,6308,6308);
INSERT INTO stanza VALUES('E1199','5','In our daily life and all we are and do and think and say,<br/>How we need a deeper mingling just to gain the Lord each day;<br/>Lord, we give ourselves completely just to take the mingled way.<br/>Yes, mingling is the way.<br/>',NULL,6309,6309);
INSERT INTO stanza VALUES('E1199','6','From the fruit of daily living, New Jerusalem we''ll see,<br/>It''s the ultimate in mingling — it''s divine humanity.<br/>And what joy that we can share it all, and share it corporately.<br/>Yes, mingling is the way.<br/>',NULL,6310,6310);
INSERT INTO stanza VALUES('E1200','1','There''s a stormy wind a-blowing from the north;<br/>Let it blow! Let it blow!<br/>God as our exp''rience will the wind bring forth;<br/>Let it blow! Let it blow!<br/>',NULL,6311,6311);
INSERT INTO stanza VALUES('E1200','chorus','Let it blow! The rushing mighty wind;<br/>Let it blow us into life!<br/>Let it blow! The gracious wind of God;<br/>Let it blow us into Christ!<br/>',NULL,6312,6312);
INSERT INTO stanza VALUES('E1200','2','There''s a hov''ring cloud a-following the wind,<br/>Covering us! Covering us!<br/>And the presence of the Lord the cloud does bring,<br/>Covering us! Covering us!<br/>',NULL,6313,6313);
INSERT INTO stanza VALUES('E1200','chorus','Covering us, God''s overshadowing cloud —<br/>God has come to stay with us.<br/>Covering us, the gracious cloud of God —<br/>Strength and comfort glorious!<br/>',NULL,6314,6314);
INSERT INTO stanza VALUES('E1200','3','With the cloud continually a fire does flash<br/>Burning us! Burning us!<br/>It exposes sin, the soul life, and the flesh,<br/>Burning us! Burning us!<br/>',NULL,6315,6315);
INSERT INTO stanza VALUES('E1200','chorus','Let it burn! The jealous flame of God;<br/>Let it burn continually!<br/>Let it burn! This all-consuming flame;<br/>Let it burn us thoroughly!<br/>',NULL,6316,6316);
INSERT INTO stanza VALUES('E1200','4','Then from out the fire does the electrum glow,<br/>Shining forth! Shining forth!<br/>The redeeming God does our experience show,<br/>Shining forth! Shining forth!<br/>',NULL,6317,6317);
INSERT INTO stanza VALUES('E1200','chorus','Let Him shine! This gold and silver One;<br/>Let Him shine for all to see!<br/>''Tis the Lamb-God who has now become<br/>Our enjoyment inwardly.<br/>',NULL,6318,6318);
INSERT INTO stanza VALUES('E1200','5','Let the wind, cloud, fire and th'' electrum be<br/>Wrought in us, o''er and o''er;<br/>Let this cycle be repeated constantly<br/>More and more, more and more!<br/>',NULL,6319,6319);
INSERT INTO stanza VALUES('E1200','chorus','Blow and hover, burn and shine forth, Lord,<br/>All our being to possess,<br/>That we all may gain Thee constantly<br/>All Thy likeness to express.<br/>',NULL,6320,6320);
INSERT INTO stanza VALUES('E1201','1','From the north where God is dwelling<br/>Comes a rushing, stormy gale.<br/>Now the mighty Spirit blowing<br/>All our being does assail.<br/>We are stirred to our foundations —<br/>How this wind awakens us!<br/>Thus we''re open for God''s dealings,<br/>And the cloud descends on us.<br/>',NULL,6321,6321);
INSERT INTO stanza VALUES('E1201','2','With the cloud we have His presence<br/>Sweetly hov''ring over us;<br/>So enveloped by His nearness;<br/>In the Lord we put our trust.<br/>But the clouds bring with it fire<br/>To consume our selfish lusts;<br/>That as ashes something higher<br/>May be added into us.<br/>',NULL,6322,6322);
INSERT INTO stanza VALUES('E1201','3','Then from out the flashing fire<br/>Come th'' electrum glowing bright.<br/>God as gold and man as silver<br/>Now are mingled. What a sight!<br/>This bright metal, O Lord Jesus,<br/>Is Thyself, Lamb-God sublime.<br/>O Lord, work Thyself within us<br/>Till th'' electrum in us shines.<br/>',NULL,6323,6323);
INSERT INTO stanza VALUES('E1201','4','By our passing through this cycle,<br/>Living creatures we become<br/>To express the life of Jesus;<br/>He with whom we''ve been made one.<br/>We express Him as a human,<br/>As a man so good and fine;<br/>Balanced, normal, never striving;<br/>Fully human, yet divine.<br/>',NULL,6324,6324);
INSERT INTO stanza VALUES('E1201','5','We express Him as a lion<br/>Conquering every enemy;<br/>As an ox obedient, lowly,<br/>Faithful in His ministry.<br/>We express Him as an eagle,<br/>So transcendent, soaring high;<br/>Never held by fear or flatter,<br/>He above it all does fly.<br/>',NULL,6325,6325);
INSERT INTO stanza VALUES('E1201','6','Hallelujah! What a figure<br/>Of the way God deals with us!<br/>From the wind, cloud, fire, electrum,<br/>To the creatures glorious:<br/>As the man, the ox and lion,<br/>As the eagle — all the four<br/>Will be our complete expression<br/>As we eat Him more and more.<br/>',NULL,6326,6326);
INSERT INTO stanza VALUES('E1202','1','God in His justifying has a plan,<br/>A deeper purpose for a corporate man.<br/>When we were called, this mighty Lord of all<br/>Appeared to us to save us from the fall.<br/>',NULL,6327,6327);
INSERT INTO stanza VALUES('E1202','2','We walked as strangers unaware of Him,<br/>But in His glory God shined deep within,<br/>Infusing His own element in us;<br/>This precious essence was our Lord Jesus.<br/>',NULL,6328,6328);
INSERT INTO stanza VALUES('E1202','3','What glory! How attractive was this light!<br/>How we appreciated such a sight!<br/>Our first reaction was belief in Him —<br/>This precious God has placed Himself within.<br/>',NULL,6329,6329);
INSERT INTO stanza VALUES('E1202','4','Our first reflection of this element<br/>Reflected Jesus back to God, Who sent<br/>His own response to count as righteousness<br/>Our faith in Him Who was infused in us.<br/>',NULL,6330,6330);
INSERT INTO stanza VALUES('E1202','5','But we would hold to this reality,<br/>Our Jesus Christ in us our all to be,<br/>Enjoying all He is abundantly,<br/>Content to have this One eternally.<br/>',NULL,6331,6331);
INSERT INTO stanza VALUES('E1202','6','Thus God could never be so satisfied;<br/>Knowing that we cared only to abide<br/>In our experiences of His Son,<br/>Not caring for His goal to make us one.<br/>',NULL,6332,6332);
INSERT INTO stanza VALUES('E1202','7','Still He would seek those faithful saints who''d hear<br/>His call to give up everything so dear,<br/>To offer up their individual Christ;<br/>To come together for the Body life.<br/>',NULL,6333,6333);
INSERT INTO stanza VALUES('E1203','1','God is righteous in His doings,<br/>He is perfect in His ways;<br/>Just is He in all His actions,<br/>And He well deserves our praise.<br/>Righteous was His condemnation,<br/>Righteous His requirement;<br/>For the law had deemed us sinners,<br/>And for judgment we were meant.<br/>',NULL,6334,6334);
INSERT INTO stanza VALUES('E1203','2','Oh, how blest the love that spared us,<br/>For the law had judged us dead.<br/>God, to meet the righteous judgment,<br/>Passed it on His Son instead.<br/>Hallelujah! Our Redeemer,<br/>Christ, to God has purchased us:<br/>Now enjoying His redemption,<br/>We become God''s righteousness.<br/>',NULL,6335,6335);
INSERT INTO stanza VALUES('E1203','3','God is holy in His nature,<br/>Holiness is what He is.<br/>In this way He sanctified us,<br/>Makes our nature one with His.<br/>Spreading from our quickened spirit,<br/>He renews each inward part,<br/>Moving into all our being,<br/>Making home in all our heart.<br/>',NULL,6336,6336);
INSERT INTO stanza VALUES('E1203','4','Oh, how blessed is this process!<br/>It''s the Lord''s life-saving way.<br/>It''s our constant, real experience;<br/>It''s our life from day to day.<br/>As we''re minding just the spirit,<br/>Then the mind is life to us,<br/>And the Lord in us is gaining<br/>Transformation marvelous!<br/>',NULL,6337,6337);
INSERT INTO stanza VALUES('E1203','5','Glory is God''s true expression,<br/>All He is, in full, expressed;<br/>Final stage of our redemption,<br/>Bodily made manifest.<br/>Glory is the consummation<br/>Of this life which sanctifies;<br/>Our complete transfiguration<br/>Is the goal which life supplies.<br/>',NULL,6338,6338);
INSERT INTO stanza VALUES('E1203','6','''Tis for this we wait, expecting<br/>To be raptured, glorified.<br/>Then the earth will see God''s fullness;<br/>Christ completely testified.<br/>We fore''er will just express Him,<br/>Nature will rejoice to see<br/>All the sons of God in glory<br/>Manifested finally.<br/>',NULL,6339,6339);
INSERT INTO stanza VALUES('E1203','7','By His mercy, we''re selected,<br/>Ours a glorious destiny.<br/>Not by running, nor by willing,<br/>But through God''s own sovereignty.<br/>Once we were wild olive branches,<br/>Now the root and fat partake,<br/>Grafted in, rejoice together,<br/>Growing for the kingdom''s sake.<br/>',NULL,6340,6340);
INSERT INTO stanza VALUES('E1203','8','As we''re daily in this process<br/>And by life are sanctified,<br/>How we thank Him for the blessing<br/>Of the church life He''s supplied.<br/>Here God is our full enjoyment,<br/>Practical and real to us;<br/>Sons we are, and heirs together,<br/>In the church life, glorious!<br/>',NULL,6341,6341);
INSERT INTO stanza VALUES('E1204','1','The cross — we all were there,<br/>Hallelujah! Hallelujah!<br/>For all that death did share!<br/>Hallelujah! Hallelujah!<br/>God there upon it died,<br/>And man and all beside<br/>Were wholly crucified —<br/>Hallelujah for the cross!<br/>',NULL,6342,6342);
INSERT INTO stanza VALUES('E1204','chorus','Hallelujah! Hallelujah!<br/>Hallelujah for the cross!<br/>Hallelujah! Hallelujah!<br/>It shall never suffer loss!<br/>',NULL,6343,6343);
INSERT INTO stanza VALUES('E1204','2','The cross, it holdeth fast,<br/>Hallelujah! Hallelujah!<br/>All things upon it cast,<br/>Hallelujah! Hallelujah!<br/>Two arms extended strong<br/>Hold those who there belong;<br/>We''re through with self — our song:<br/>Hallelujah for the cross!<br/>',NULL,6344,6344);
INSERT INTO stanza VALUES('E1204','3','''Tis there man died in God,<br/>Hallelujah! Hallelujah!<br/>There ceased this human clod,<br/>Hallelujah! Hallelujah!<br/>With joy we all declare,<br/>We''re terminated there!<br/>We''ll sing now and fore''er,<br/>Hallelujah for the cross!<br/>',NULL,6345,6345);
INSERT INTO stanza VALUES('E1204','4','''Tis there man died in God,<br/>Hallelujah! Hallelujah!<br/>Fulfilling thus His plan,<br/>Hallelujah! Hallelujah!<br/>Through death He was released<br/>And now He has increased;<br/>His life is our rich feast —<br/>Hallelujah for the cross!<br/>',NULL,6346,6346);
INSERT INTO stanza VALUES('E1204','chorus','Hallelujah! Hallelujah!<br/>God has been released in us!<br/>Hallelujah! Hallelujah!<br/>Hallelujah for the cross!<br/>',NULL,6347,6347);
INSERT INTO stanza VALUES('E1205','1','Press on, press on toward the goal —<br/>The all-inclusive Christ.<br/>To gain the prize of God''s high call,<br/>Press on, press on to Christ!<br/>',NULL,6348,6348);
INSERT INTO stanza VALUES('E1205','chorus','Pressing on! Pressing on!<br/>Pressing on! Hallelujah for the prize<br/>We''re pressing on! On and on!<br/>To gain the Christ of God!<br/>',NULL,6349,6349);
INSERT INTO stanza VALUES('E1205','2','Press on, press on, count all things loss,<br/>All that is gain to us,<br/>To win the prize, the Christ of God.<br/>Is far more glorious!<br/>',NULL,6350,6350);
INSERT INTO stanza VALUES('E1205','3','Press on, press on to know the Lord<br/>And resurrection power —<br/>Oh, this is our supreme reward,<br/>E''en in the suffering hour!<br/>',NULL,6351,6351);
INSERT INTO stanza VALUES('E1205','4','Press on, press on, this one thing do,<br/>Forget the things behind;<br/>Press onward to the Christ before,<br/>Press onward with this mind!<br/>',NULL,6352,6352);
INSERT INTO stanza VALUES('E1206','1','There''s a race for us to run — Hallelujah,<br/>And a way for us the race to win.<br/>To all those who have begun — Hallelujah,<br/>God has spoken, "Look away to Him!"<br/>',NULL,6353,6353);
INSERT INTO stanza VALUES('E1206','chorus','Look away! O look away!<br/>Look to Jesus now today!<br/>Look away from everything unto Jesus,<br/>Look away from everything to Him!<br/>',NULL,6354,6354);
INSERT INTO stanza VALUES('E1206','2','Look away from all around — Hallelujah,<br/>Look away from all the strife and din;<br/>Look away where peace is found — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,6355,6355);
INSERT INTO stanza VALUES('E1206','3','Look away from fickle soul — Hallelujah,<br/>Look away from failing self within;<br/>Look away toward the goal — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,6356,6356);
INSERT INTO stanza VALUES('E1206','4','Look away from all the past — Hallelujah,<br/>Look away from both the good and sin;<br/>To the living One hold fast — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,6357,6357);
INSERT INTO stanza VALUES('E1206','5','Look away into His face — Hallelujah,<br/>He who''ll finish what He did begin.<br/>O what grace to run the race — Hallelujah —<br/>We obtain by looking off to Him!<br/>',NULL,6358,6358);
INSERT INTO stanza VALUES('E1207','1','There''s a way before us and a race to run —<br/>Christ our way, Christ our way!<br/>Turn away from everything distracting us —<br/>Run the race, run the race!<br/>From the altar through the Holy Place,<br/>Through the veil into our God,<br/>To the law of life within the ark;<br/>''Tis the goal, our great reward.<br/>',NULL,6359,6359);
INSERT INTO stanza VALUES('E1207','2','There''s a cloud of witnesses surrounding us,<br/>Urging us, forward come!<br/>There is Abel, Enoch, Jacob, Abraham,<br/>Moses, David, Solomon.<br/>John the Baptist greater than them all,<br/>Even he bids forward come!<br/>These all died in faith, receiving not<br/>Promises that were to come.<br/>',NULL,6360,6360);
INSERT INTO stanza VALUES('E1207','3','The Old Testament believers give the call,<br/>"Forward come, forward come!"<br/>For complete perfection they depend on us<br/>Going on! Going on!<br/>We are at the consummation now<br/>Of our God''s economy;<br/>Better things we are experiencing.<br/>Praise the Lord — reality!<br/>',NULL,6361,6361);
INSERT INTO stanza VALUES('E1207','4','E''en the least of us is greater than their great.<br/>We''re not small, we''re not small!<br/>They are waiting, watching, and expecting us.<br/>"Forward come!" hear their call!<br/>They have run the race and for their sakes<br/>We''ll obey the law of life.<br/>Till the day we''ll all be joined in one<br/>To express God''s glorious Christ.<br/>',NULL,6362,6362);
INSERT INTO stanza VALUES('E1208','1','Years I spent in sorrow ''round the cross,<br/>Still repenting over sins and dross.<br/>Then at last the river I did cross,<br/>To touch the throne.<br/>',NULL,6363,6363);
INSERT INTO stanza VALUES('E1208','chorus','Mercy now is flowing, oh, the grace —<br/>That I find of Him to run the race!<br/>Boldly now I come again to taste<br/>My glorious Lord.<br/>',NULL,6364,6364);
INSERT INTO stanza VALUES('E1208','2','In my Christian life I''d daily fall,<br/>So I answered every altar-call,<br/>Till I left the altar, left it all,<br/>To touch the throne.<br/>',NULL,6365,6365);
INSERT INTO stanza VALUES('E1208','3','Brothers, to the Holiest forward come;<br/>Leave your sins behind, the race now run.<br/>Hallelujah! All the work is done —<br/>The veil is gone!<br/>',NULL,6366,6366);
INSERT INTO stanza VALUES('E1208','4','Now within the veil, enjoying God,<br/>Manna, law of life, and budding rod;<br/>Christ Himself, the ark, is our abode —<br/>Hallelujah!<br/>',NULL,6367,6367);
INSERT INTO stanza VALUES('E1209','1','Praise God for tidings glad —<br/>We''re at the throne of grace;<br/>Our gospel''s not so low,<br/>We''re in the highest place.<br/>We''re meeting here around the throne,<br/>Enjoying God with all His own.<br/>',NULL,6368,6368);
INSERT INTO stanza VALUES('E1209','2','Start in the outer court,<br/>But aim to get inside;<br/>The Holy Place is good,<br/>But do not there abide.<br/>Leave sin behind — it''s put away;<br/>We''re in the veil with God to stay.<br/>',NULL,6369,6369);
INSERT INTO stanza VALUES('E1209','3','To rise from earth to heav''n,<br/>A deeper turn we need;<br/>To be where Christ is now<br/>Upon the throne indeed.<br/>We''re gathered at the throne of grace,<br/>Beholding Jesus face to face.<br/>',NULL,6370,6370);
INSERT INTO stanza VALUES('E1209','4','We''re being turned as one,<br/>Not individually;<br/>Not private Christians now.<br/>But Body Christians we.<br/>As members here in one accord,<br/>We are the Body of the Lord.<br/>',NULL,6371,6371);
INSERT INTO stanza VALUES('E1209','5','As Body Christians now<br/>We have a higher word.<br/>Foundation''s word we see,<br/>''Tis altar, cross, and blood.<br/>Perfection''s word is little known,<br/>''Tis fellowship around the throne.<br/>',NULL,6372,6372);
INSERT INTO stanza VALUES('E1209','6','Christ is objective too,<br/>But subjective are we<br/>In our experience;<br/>Our spirit is the key.<br/>God, throne, and holiest — we see<br/>Our spirit now contains all three.<br/>',NULL,6373,6373);
INSERT INTO stanza VALUES('E1209','7','Leviticus is past,<br/>And Aaron''s work is o''er;<br/>Melchisedec is here,<br/>High Priest forevermore;<br/>His ministry is now so fine:<br/>He comes to feed us bread and wine.<br/>',NULL,6374,6374);
INSERT INTO stanza VALUES('E1210','1','Through God''s word, my hope at His returning<br/>Is that all my being be redeemed;<br/>Yet in times of grief and tribulation,<br/>Doubt and fear arise, no hope is seen.<br/>In those hours, when prayer cannot be uttered,<br/>Only groaning from my breast is heard.<br/>Then the Spirit, in like manner, helps me,<br/>Praying in my weakness unto God.<br/>',NULL,6375,6375);
INSERT INTO stanza VALUES('E1210','2','Lord, my prayer is not for deeper suffering,<br/>But that from each trial I''d be free.<br/>Let the cup of bitterness be taken;<br/>Yet, Thy will, not mine, dear Lord, must be.<br/>Even now, though trials sore surround me,<br/>Still within my heart there is a peace,<br/>For the love of God outpoured within me<br/>Floods my heart and bids my doubting cease.<br/>',NULL,6376,6376);
INSERT INTO stanza VALUES('E1210','3','Blest assurance! God has fully ordered<br/>Every matter by His sovereign hand;<br/>Every person (though we see so dimly),<br/>Every thing''s according to His plan.<br/>Every trial is but the Father''s answer<br/>To the groaning of the Spirit''s prayer;<br/>May He gain in every tribulation,<br/>Until we Christ''s glory fully share.<br/>',NULL,6377,6377);
INSERT INTO stanza VALUES('E1210','4','How could God from all His dealings spare us,<br/>After He spared not His only Son?<br/>Could the Potter''s hand upon the vessel<br/>Ever leave the shaping work undone?<br/>For the center of God''s heart''s desire<br/>Is that many brethren we will be<br/>Unto Christ, His precious First-begotten,<br/>And to Him, conformed we''ll fully be.<br/>',NULL,6378,6378);
INSERT INTO stanza VALUES('E1210','5','Heirs of God! Joint-heirs with our Lord Jesus!<br/>What a hope of glory this for us!<br/>Though the suff''rings presently seem grievous,<br/>Greater far the glory then for us!<br/>Yea, in all these things we more than conquer,<br/>Through the One whose love has us possessed;<br/>Soon the day for which waits all creation,<br/>When the sons of God are manifest!<br/>',NULL,6379,6379);
INSERT INTO stanza VALUES('E1211','1','Given us, given us, God has given us<br/>Precious faith, power divine, greatest promises.<br/>We believed, we received, now we have all three;<br/>By these we may grow unto maturity.<br/>',NULL,6380,6380);
INSERT INTO stanza VALUES('E1211','2','Precious faith in each saint, precious equally,<br/>Precious faith holding us, holding ceaselessly.<br/>Disagree or agree, still it holds us fast,<br/>Day by day, eternally this faith shall last.<br/>',NULL,6381,6381);
INSERT INTO stanza VALUES('E1211','3','Power divine wrought in us is the source so great;<br/>Power divine is in us now to operate.<br/>Hence will spring everything for our life within<br/>And for godliness without, expressing Him.<br/>',NULL,6382,6382);
INSERT INTO stanza VALUES('E1211','4','Promises, promises, all God''s called ones share;<br/>Promises, given us, great and precious are.<br/>These we take to partake of God''s nature true,<br/>Having thus escaped the world''s corruption too.<br/>',NULL,6383,6383);
INSERT INTO stanza VALUES('E1211','5','Christ within, as the pow''r, in our spirit lives;<br/>Christ without is the Word — all God''s promises.<br/>Now the key is that we daily contact both,<br/>Calling, praying, reading to produce the growth.<br/>',NULL,6384,6384);
INSERT INTO stanza VALUES('E1211','6','Faith and pow''r, promises — these our full supply.<br/>Diligence, diligence, let us now apply;<br/>For if we, to these three, full attention show<br/>From the seed of faith the fruit of love will grow.<br/>',NULL,6385,6385);
INSERT INTO stanza VALUES('E1211','7','In the growth from the seed many items come;<br/>By this growth in the Lord fruitful we become.<br/>For this we need to see what the Lord''s begun,<br/>Ne''er forgetful be nor blind to what He''s done.<br/>',NULL,6386,6386);
INSERT INTO stanza VALUES('E1211','8','Diligence day by day will this growth insure;<br/>Diligence thus will make our election sure.<br/>When indeed with this seed we cooperate,<br/>We''re supplied the kingdom''s entrance, rich and great.<br/>',NULL,6387,6387);
INSERT INTO stanza VALUES('E1211','9','For this growth, for this growth, Lord, ourselves we give,<br/>By the faith, promises, and the pow''r to live.<br/>Nothing more, nothing less, will our basis be<br/>By Thy grace we will cooperate with Thee.<br/>',NULL,6388,6388);
INSERT INTO stanza VALUES('E1212','1','The Lord of all has shown His plan<br/>Unto each faithful one,<br/>Who leaves behind the worldly things<br/>As virgins for His Son.<br/>To be His Bride we must match Him,<br/>Within and outwardly;<br/>To be this one who matches Him,<br/>Enjoy Him constantly.<br/>',NULL,6389,6389);
INSERT INTO stanza VALUES('E1212','2','Like virgins who so single are,<br/>They love the Groom so much,<br/>They in His presence ever stay —<br/>Lord Jesus, make us such.<br/>Lord, make us those who are so wise,<br/>Who gain You every day,<br/>The wise ones who enjoy the feast,<br/>Who all the price will pay.<br/>',NULL,6390,6390);
INSERT INTO stanza VALUES('E1212','3','The virgins are mature in life,<br/>They grow so normally.<br/>They daily eat and drink the Lord,<br/>Their lot eternally.<br/>Our need today is growth in life,<br/>Christ''s inward work indeed;<br/>Not knowledge, teachings, gifts, nor pow''r —<br/>But life is all we need.<br/>',NULL,6391,6391);
INSERT INTO stanza VALUES('E1212','4','Lord, as the seed of life within,<br/>Grow more in us each day;<br/>By spreading from our deepest part,<br/>Gain us in every way.<br/>Lord, strengthen Thou our inner man;<br/>Make home in all our heart.<br/>Fill us completely with Thyself<br/>In every inward part.<br/>',NULL,6392,6392);
INSERT INTO stanza VALUES('E1213','1','If from your nat''ral man you would be free,<br/>Amen the law of life!<br/>This law works in us automatically,<br/>Amen the law of life!<br/>Amen the law of life!<br/>Amen the law of life!<br/>This law transforms us, to Christ conforms us —<br/>Amen the law of life!<br/>',NULL,6393,6393);
INSERT INTO stanza VALUES('E1213','2','From life divine it does originate,<br/>Amen the law of life!<br/>Its function, working, power are innate,<br/>Amen the law of life!<br/>Amen the law of life!<br/>Amen the law of life!<br/>Stop all your trying, on life relying,<br/>Amen the law of life!<br/>',NULL,6394,6394);
INSERT INTO stanza VALUES('E1213','3','The law of life fulfills our God''s desire,<br/>Amen the law of life!<br/>Our self-improvement He does not require,<br/>Amen the law of life!<br/>Amen the law of life!<br/>Amen the law of life!<br/>God'' plan fulfilling; Yes, Lord, we''re willing,<br/>Amen the law of life!<br/>',NULL,6395,6395);
INSERT INTO stanza VALUES('E1213','4','This law transforms us metabolically,<br/>Amen the law of life!<br/>''Til we are permeated corporately,<br/>Amen the law of life!<br/>Amen the law of life!<br/>Amen the law of life!<br/>Old man denying, God''s life supplying,<br/>Amen the law of life!<br/>',NULL,6396,6396);
INSERT INTO stanza VALUES('E1213','5','This law''s inscribing Christ upon our hearts,<br/>Amen the law of life!<br/>''Til He is written in our inward parts,<br/>Amen the law of life!<br/>Amen the law of life!<br/>Amen the law of life!<br/>Christ''s form engraving, not mere behaving,<br/>Amen the law of life!<br/>',NULL,6397,6397);
INSERT INTO stanza VALUES('E1214','1','Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>',NULL,6398,6398);
INSERT INTO stanza VALUES('E1214','chorus','All the guilt has to go<br/>That His life may flow... Hallelujah!<br/>Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>',NULL,6399,6399);
INSERT INTO stanza VALUES('E1214','2','Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>',NULL,6400,6400);
INSERT INTO stanza VALUES('E1214','chorus','All my dreams have to go<br/>That His life may flow... Hallelujah!<br/>Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>',NULL,6401,6401);
INSERT INTO stanza VALUES('E1214','3','Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>',NULL,6402,6402);
INSERT INTO stanza VALUES('E1214','chorus','All self love has to go<br/>That His life may flow... Hallelujah!<br/>Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>',NULL,6403,6403);
INSERT INTO stanza VALUES('E1214','4','Dig away, dig away, dig away,<br/>All resistance in my will dig away!<br/>Dig away, dig away, dig away,<br/>All resistance in my will dig away!<br/>',NULL,6404,6404);
INSERT INTO stanza VALUES('E1214','chorus','All self will has to go<br/>That His life may flow... Hallelujah!<br/>Dig away, dig away, dig away,<br/>All resistance in my will dig away!<br/>',NULL,6405,6405);
INSERT INTO stanza VALUES('E1214','5','Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>',NULL,6406,6406);
INSERT INTO stanza VALUES('E1214','chorus','All my hopes have to go<br/>That His life may flow... Hallelujah!<br/>Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>',NULL,6407,6407);
INSERT INTO stanza VALUES('E1214','6','Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>',NULL,6408,6408);
INSERT INTO stanza VALUES('E1214','chorus','When my heart''s wholly free,<br/>Christ can flow through me... Hallelujah!<br/>Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>',NULL,6409,6409);
INSERT INTO stanza VALUES('E1215','1','God had not giv''n us a spirit of fear —<br/>There''s pow''r deep within, pow''r deep within!<br/>We have His Word-brothers, sisters, let''s hear —<br/>That pow''r deep within may flow out.<br/>',NULL,6410,6410);
INSERT INTO stanza VALUES('E1215','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r<br/>In the spirit God''s given us!<br/>',NULL,6411,6411);
INSERT INTO stanza VALUES('E1215','2','God has not giv''n us a wavering will —<br/>There''s pow''r deep within, pow''r deep within!<br/>But one our spirit will strengthen and fill —<br/>There''s wonderful pow''r deep within!<br/>',NULL,6412,6412);
INSERT INTO stanza VALUES('E1215','3','God has not giv''n us emotions so weak —<br/>There''s pow''r deep within, pow''r deep within!<br/>Open our hearts and in love let us speak —<br/>There''s wonderful pow''r deep within!<br/>',NULL,6413,6413);
INSERT INTO stanza VALUES('E1215','4','God has not giv''n us a mind that is bound —<br/>There''s pow''r deep within, pow''r deep within!<br/>But one that''s healthy and perfectly sound —<br/>There''s wonderful pow''r deep within!<br/>',NULL,6414,6414);
INSERT INTO stanza VALUES('E1216','1','We have an inner life; that''s for our daily life;<br/>That''s for the meeting life — just Christ!<br/>We''ll live the inner life; we''ll have the daily life;<br/>We''ll see the meeting life — that''s just the church.<br/>',NULL,6415,6415);
INSERT INTO stanza VALUES('E1216','2','Christ is our inner life; He''s in our spirit now;<br/>Not far away from us — He''s right inside!<br/>And as we turn to Him and take Him as our all<br/>He will become in us our inner life.<br/>',NULL,6416,6416);
INSERT INTO stanza VALUES('E1216','3','Out from our inner life will come our daily life,<br/>And all our living be filled up with Christ.<br/>Then as we live by Him, He lives His life in us,<br/>And He becomes to us our daily life.<br/>',NULL,6417,6417);
INSERT INTO stanza VALUES('E1216','4','The real experience of Christ in daily life,<br/>Will fill the meeting life with Christ Himself.<br/>Not empty forms and such, but Christ will be so much;<br/>And we will see Him here as the meeting life.<br/>',NULL,6418,6418);
INSERT INTO stanza VALUES('E1216','5','Without the inner life there is no daily life,<br/>There is no meeting life, there is no church!<br/>Christ as our inner life, Christ in our daily life<br/>Will make the meeting life new and glorious!<br/>',NULL,6419,6419);
INSERT INTO stanza VALUES('E1217','1','Lord, we''ve heard the call, "Come forward,"<br/>Unto the most Holy Place,<br/>To behold shekinah glory<br/>Shining from Your blessed face.<br/>',NULL,6420,6420);
INSERT INTO stanza VALUES('E1217','chorus','Come forward to the Holiest,<br/>Through the incense altar''s prayer;<br/>No more veil of separation,<br/>We may boldly enter there.<br/>',NULL,6421,6421);
INSERT INTO stanza VALUES('E1217','2','We come forward by a new way,<br/>Freshly cut and freshly slain,<br/>To the Holiest of Holies;<br/>Glorious access we obtain.<br/>',NULL,6422,6422);
INSERT INTO stanza VALUES('E1217','3','We come forward unto our God,<br/>Who is sitting on the throne;<br/>He has paved the way to glory<br/>By His blood and cross alone.<br/>',NULL,6423,6423);
INSERT INTO stanza VALUES('E1217','4','We come forward to the new age,<br/>With assured heart, true and bold.<br/>To enjoy th'' eternal purpose,<br/>Ne''re to shrink back to the old.<br/>',NULL,6424,6424);
INSERT INTO stanza VALUES('E1217','5','Praise You, Lord, we''ve all come forward.<br/>Now within the Holiest,<br/>You''re our God, and we''re Your people;<br/>Here we dwell forever blest.<br/>',NULL,6425,6425);
INSERT INTO stanza VALUES('E1218','1','If from the world you''re longing to be free,<br/>Amen the Word of God!<br/>If you would live in all reality,<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>His Word receiving, His Word believing,<br/>Amen the Word of God!<br/>',NULL,6426,6426);
INSERT INTO stanza VALUES('E1218','2','If with your sin and self you would be through,<br/>Amen the Word of God!<br/>If you would let the Lord your mind renew,<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>His Word is living, life-power giving —<br/>Amen the Word of God!<br/>',NULL,6427,6427);
INSERT INTO stanza VALUES('E1218','3','Christ as the land of Canaan is our lot —<br/>Amen the Word of God!<br/>If you would enter, harden not your heart —<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>His Word discerns us, all that concerns us —<br/>Amen the Word of God!<br/>',NULL,6428,6428);
INSERT INTO stanza VALUES('E1218','4','Jesus is coming, now He''s on His way —<br/>Amen the Word of God!<br/>Would you be ready if He comes today —<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>Amen the Word of God!<br/>His Word prepares us, to Jesus bears us —<br/>Amen the Word of God!<br/>',NULL,6429,6429);
INSERT INTO stanza VALUES('E1219','1','What a wonderful change in my living is wrought<br/>By saying Amen to God''s Word.<br/>More of Christ into me at each instance is brought<br/>By saying Amen to His Word.<br/>',NULL,6430,6430);
INSERT INTO stanza VALUES('E1219','chorus','By saying Amen to His Word,<br/>By saying Amen to His Word,<br/>Thus the Lord takes my heart, and transforms every part,<br/>By saying Amen to His Word.<br/>',NULL,6431,6431);
INSERT INTO stanza VALUES('E1219','2','What I never could do God is doing in me,<br/>By saying Amen to His Word.<br/>And the change is so real all the brothers can see,<br/>By saying Amen to God''s Word.<br/>',NULL,6432,6432);
INSERT INTO stanza VALUES('E1219','3','I have ceased from my wandering and going astray<br/>By saying Amen to God''s Word.<br/>And my old inclinations are passing away<br/>By saying Amen to His Word.<br/>',NULL,6433,6433);
INSERT INTO stanza VALUES('E1219','4','Now the secret of faith in the Lord I can see —<br/>It''s saying Amen to His Word.<br/>He is more real and precious than all things to me<br/>By saying Amen to His Word.<br/>',NULL,6434,6434);
INSERT INTO stanza VALUES('E1219','5','Now my love for the brothers abounds more and more<br/>By saying Amen to God''s Word.<br/>And I''m being related as never before<br/>By saying Amen to His Word.<br/>',NULL,6435,6435);
INSERT INTO stanza VALUES('E1219','6','Now my hope in the Lord''s soon return groweth bright<br/>By saying Amen to His Word.<br/>I am ready to see Him, my Lord, my delight,<br/>By saying Amen to His Word.<br/>',NULL,6436,6436);
INSERT INTO stanza VALUES('E1219','chorus','Lord Jesus, Amen to Your Word,<br/>Lord Jesus, Amen to Your Word,<br/>You are coming again-all my heart says<br/>Amen!<br/>Lord Jesus, Amen to Your Word,<br/>',NULL,6437,6437);
INSERT INTO stanza VALUES('E1220','1','Remove the veils, Lord, from my heart;<br/>True revelation grant to me;<br/>A vision clear, O Lord, impart<br/>Of Thy recovery.<br/>A vision clear, O Lord, impart<br/>Of Thy recovery.<br/>',NULL,6438,6438);
INSERT INTO stanza VALUES('E1220','2','By revelation I perceive<br/>The power that raised Christ from the dead;<br/>When I by faith this power receive,<br/>I to the church am led.<br/>When I by faith this power receive,<br/>I to the church am led.<br/>',NULL,6439,6439);
INSERT INTO stanza VALUES('E1220','3','Thy mighty power has set me free<br/>From all the world''s distracting things;<br/>An entrance to the local church<br/>This mighty power brings.<br/>An entrance to the local church<br/>This mighty power brings.<br/>',NULL,6440,6440);
INSERT INTO stanza VALUES('E1220','4','Once in the local church, I need<br/>To take Thee as my person, Lord;<br/>My outward man each day recede,<br/>My heart is for the Lord.<br/>My outward man each day recede,<br/>My heart is for the Lord.<br/>',NULL,6441,6441);
INSERT INTO stanza VALUES('E1220','5','I take Thee as my person, Lord;<br/>I have been crucified with Thee.<br/>My inner man has been restored;<br/>I''m now indwelt by Thee.<br/>My inner man has been restored;<br/>I''m now indwelt by Thee.<br/>',NULL,6442,6442);
INSERT INTO stanza VALUES('E1220','6','When all Thy members self forsake,<br/>Thy glorious Body, Lord, is known;<br/>When of Thy Person we partake,<br/>The one new man is shown.<br/>When of Thy Person we partake,<br/>The one new man is shown.<br/>',NULL,6443,6443);
INSERT INTO stanza VALUES('E1220','7','The church life is the one new man<br/>In every local church expressed;<br/>Thy Body is a corporate man,<br/>One person manifest.<br/>Thy Body is a corporate man,<br/>One person manifest.<br/>',NULL,6444,6444);
INSERT INTO stanza VALUES('E1221','1','Jesus, our wonderful Shepherd<br/>Brought us right out of the fold<br/>Into His pasture so plenteous,<br/>Into His riches untold.<br/>',NULL,6445,6445);
INSERT INTO stanza VALUES('E1221','chorus','Glorious church life,<br/>Feasting from such a rich store!<br/>Here where we''re dwelling in oneness<br/>God commands life evermore.<br/>',NULL,6446,6446);
INSERT INTO stanza VALUES('E1221','2','In the divisions He sought us,<br/>Weary and famished for food;<br/>Into the good land He brought us,<br/>Oh, to our spirit how good!<br/>',NULL,6447,6447);
INSERT INTO stanza VALUES('E1221','3','Jesus Himself is our pasture,<br/>He is the food that we eat;<br/>We as His sheep are fed richly<br/>Each time, whenever we meet.<br/>',NULL,6448,6448);
INSERT INTO stanza VALUES('E1221','4','Dwell we here on a high mountain,<br/>Wet with the morning-fresh dew,<br/>Slaking our thirst at the fountain,<br/>Water so living and new.<br/>',NULL,6449,6449);
INSERT INTO stanza VALUES('E1221','5','Christ is our rest and enjoyment,<br/>Here we have nothing to fear;<br/>Here all the sheep dwell securely,<br/>Kept by His presence so dear.<br/>',NULL,6450,6450);
INSERT INTO stanza VALUES('E1222','1','Sing aloud your praises to the Lord of all,<br/>Now He is dwelling in Jerusalem.<br/>Tell among us all His doings great and small,<br/>His throne, the heavens, yet He walks with men.<br/>Oh, the salvation out of Zion comes;<br/>He brought us back from our captivity.<br/>Now we rejoice and are exceeding glad;<br/>Now we rejoice and are exceeding glad!<br/>',NULL,6451,6451);
INSERT INTO stanza VALUES('E1222','2','In the Holy City with His own He dwells;<br/>O Lord, our Lord how excellent Thy name!<br/>He''s enthroned upon the praises of His saints;<br/>All His delight in Zion does remain.<br/>The local churches are His move today —<br/>He is our portion, we are satisfied.<br/>Oh, what a goodly heritage have we;<br/>Oh, what a goodly heritage have we!<br/>',NULL,6452,6452);
INSERT INTO stanza VALUES('E1222','3','Who shall in His holy tabernacle dwell,<br/>Who shall ascend to His most holy hill?<br/>Those who seek for Him and purify their heart;<br/>This generation now that seeks His face.<br/>Oh, seek His face, ye children of the earth,<br/>Open your heart, and let the King come in.<br/>He will come in, and He shall live and reign;<br/>He will come in, and He shall live and reign!<br/>',NULL,6453,6453);
INSERT INTO stanza VALUES('E1222','4','Look! God''s tabernacle now is with the saints;<br/>Emmanuel — God with us, we proclaim.<br/>Everything is done, so let His children come;<br/>Christ and the church — where God and man are one!<br/>Lift up your heads, ye cities of the earth;<br/>Open your gates, and let the King come in.<br/>Shout to His praise — He''s coming in to reign!<br/>Shout to His praise — He''s coming in to reign!<br/>',NULL,6454,6454);
INSERT INTO stanza VALUES('E1223','1','O walk about, walk about Zion,<br/>Go round about her in love.<br/>O walk about, walk about Zion<br/>And count the towers thereof.<br/>',NULL,6455,6455);
INSERT INTO stanza VALUES('E1223','2','O set your heart on her bulwarks,<br/>O set your heart on her walls,<br/>O set your heart on her bulwarks,<br/>Consider her palaces.<br/>',NULL,6456,6456);
INSERT INTO stanza VALUES('E1223','3','In elevation how beauteous,<br/>The joy of all the earth!<br/>In elevation how beauteous<br/>Is Zion, that city of worth!<br/>',NULL,6457,6457);
INSERT INTO stanza VALUES('E1223','4','O there is a river in Zion<br/>That flows so deep and so broad.<br/>O how the streams of that river<br/>Make glad the city of God!<br/>',NULL,6458,6458);
INSERT INTO stanza VALUES('E1223','5','Praise waiteth for Thee, Lord, in Zion,<br/>Praise waiteth, O God, for Thee,<br/>Praise waiteth for Thee, Lord, in Zion,<br/>For Zion is filled with Thee.<br/>',NULL,6459,6459);
INSERT INTO stanza VALUES('E1223','6','How great the Lord is in Zion,<br/>How greatly to be praised,<br/>How great He is in that city<br/>Which over the earth is raised.<br/>',NULL,6460,6460);
INSERT INTO stanza VALUES('E1223','7','O bless the Lord out of Zion,<br/>O let His praises swell,<br/>O bless the Lord out of Zion,<br/>Ye who in Jerusalem dwell.<br/>',NULL,6461,6461);
INSERT INTO stanza VALUES('E1223','8','The Lord bless thee out of Zion,<br/>The Lord bless thee o''er and o''er!<br/>The Lord bless thee out of Zion<br/>With life for evermore!<br/>',NULL,6462,6462);
INSERT INTO stanza VALUES('E1223','9','Behold how good and how pleasant<br/>With all the brethren to be!<br/>Behold how good and how pleasant<br/>To dwell in unity!<br/>',NULL,6463,6463);
INSERT INTO stanza VALUES('E1223','10','O tell it to all generations,<br/>O tell it to all who will come,<br/>O tell it to all generations,<br/>The Spirit and Bride say, "Come!"<br/>',NULL,6464,6464);
INSERT INTO stanza VALUES('E1224','1','We from the law to Christ have turned;<br/>To trust in Him by grace we''ve learned.<br/>And since His glory we''ve discerned<br/>We only care for Christ!<br/>',NULL,6465,6465);
INSERT INTO stanza VALUES('E1224','chorus','We only care for Christ!<br/>We only care for Christ!<br/>And since His glory we''ve discerned<br/>We only care for Christ!<br/>',NULL,6466,6466);
INSERT INTO stanza VALUES('E1224','2','Christ brings us to God''s house to dwell,<br/>Where all day long His praises swell,<br/>O hallelujah! None can tell<br/>How lovely is God''s house!<br/>',NULL,6467,6467);
INSERT INTO stanza VALUES('E1224','chorus','How lovely is God''s house!<br/>How lovely is God''s house!<br/>O hallelujah! None can tell<br/>How lovely is God''s house!<br/>',NULL,6468,6468);
INSERT INTO stanza VALUES('E1224','3','The house enlarged the city is;<br/>The joy of all the nations ''tis,<br/>The place for God to rule is this<br/>On Zion''s holy hill.<br/>',NULL,6469,6469);
INSERT INTO stanza VALUES('E1224','chorus','On Zion''s holy hill.<br/>On Zion''s holy hill.<br/>The place for God to rule is this<br/>On Zion''s holy hill.<br/>',NULL,6470,6470);
INSERT INTO stanza VALUES('E1224','4','From Zion Christ will take the earth<br/>And reign and fill its souls with mirth.<br/>All nations will proclaim His worth,<br/>Break forth and sing for joy.<br/>',NULL,6471,6471);
INSERT INTO stanza VALUES('E1224','chorus','Break forth and sing for joy.<br/>Break forth and sing for joy.<br/>All nations will proclaim His worth,<br/>Break forth and sing for joy.<br/>',NULL,6472,6472);
INSERT INTO stanza VALUES('E1224','5','Christ — house — the city — earth, we see;<br/>Thus God''s great plan fulfilled will be.<br/>O brothers, let us utterly<br/>Be one with Him for this.<br/>',NULL,6473,6473);
INSERT INTO stanza VALUES('E1224','chorus','Be one with Him for this.<br/>Be one with Him for this.<br/>O brothers, let us utterly<br/>Be one with Him for this.<br/>',NULL,6474,6474);
INSERT INTO stanza VALUES('E1225','1','Lord, to know Thee as the Body,<br/>Is my desperate need today,<br/>Oh, to see Thee in Thy members,<br/>''Tis for this I long and pray.<br/>No more just to know Thy headship,<br/>In an individual way,<br/>But to see Thee incarnated,<br/>As the Body-Christ, I pray.<br/>',NULL,6475,6475);
INSERT INTO stanza VALUES('E1225','2','Through the years, Thy saints have sought Thee,<br/>Longing for reality;<br/>Gazing upward, searching inward,<br/>Thirsting for the sight of Thee.<br/>Now reveal that Christ in heaven,<br/>Is the Body manifest;<br/>And the Christ who dwells within us<br/>As the Body is expressed.<br/>',NULL,6476,6476);
INSERT INTO stanza VALUES('E1225','3','Prone to be misled, I know it,<br/>By my lofty thoughts of Thee,<br/>Easy ''tis for self to seek Thee,<br/>Yet not touch reality,<br/>Oh, how much I need to find Thee,<br/>In Thy members here below.<br/>God eternal dwells among us,<br/>Manifest in flesh to know.<br/>',NULL,6477,6477);
INSERT INTO stanza VALUES('E1225','4','Limit, Lord, my independence,<br/>Let me to Thy Body turn;<br/>Not just seeking light from heaven,<br/>But the church''s sense to learn.<br/>May we be the stones for building,<br/>Not the formless, useless clay,<br/>Gain in us Thy heart''s desire,<br/>Corporately Thyself display.<br/>',NULL,6478,6478);
INSERT INTO stanza VALUES('E1226','1','Oh, the church of Christ is glorious, and we are part of it —<br/>We''re so happy that the Lord has made us one!<br/>There''s a Body in the universe and we belong to it —<br/>Hallelujah, for the Lord has made us one!<br/>',NULL,6479,6479);
INSERT INTO stanza VALUES('E1226','chorus','Hallelujah for the Body!<br/>We are members of the Body!<br/>We are wholly for the Body!<br/>Hallelujah, for the Lord has made us one!<br/>',NULL,6480,6480);
INSERT INTO stanza VALUES('E1226','2','Not just individual Christians, but a corporate entity —<br/>God must have it for His full expression now;<br/>Not just individual churches but the Body corporately —<br/>Hallelujah, we are in the Body now!<br/>',NULL,6481,6481);
INSERT INTO stanza VALUES('E1226','chorus','Hallelujah for the Body!<br/>Satan trembles at the Body!<br/>We''re victorious in the Body!<br/>Hallelujah, we are in the Body now!<br/>',NULL,6482,6482);
INSERT INTO stanza VALUES('E1226','3','There are seven golden lampstands in the nature all divine —<br/>Nothing natural does the Body life allow.<br/>When we''re one and share God''s nature, how the lampstand then does shine —<br/>Hallelujah, it is brightly shining now!<br/>',NULL,6483,6483);
INSERT INTO stanza VALUES('E1226','chorus','Hallelujah for the Body!<br/>For the lampstands of the Body!<br/>For the golden, shining Body!<br/>Hallelujah, it is brightly shining now!<br/>',NULL,6484,6484);
INSERT INTO stanza VALUES('E1226','4','How may we express such oneness, be divine and shining too?<br/>Hallelujah, eating Jesus is the way!<br/>He''s the tree of life, the manna, and the feast that''s ever new —<br/>Hallelujah, we may eat Him every day!<br/>',NULL,6485,6485);
INSERT INTO stanza VALUES('E1226','chorus','We are one by eating Jesus!<br/>We''re divine by eating Jesus!<br/>How we shine by eating Jesus!<br/>Hallelujah, eating Jesus is the way!<br/>',NULL,6486,6486);
INSERT INTO stanza VALUES('E1227','1','Our Lord, that One of peerless worth<br/>Came first to die to give new birth;<br/>He comes again to have on earth<br/>A glorious Bride forever.<br/>',NULL,6487,6487);
INSERT INTO stanza VALUES('E1227','chorus','Jesus! Oh, You''re coming soon,<br/>Jesus! As our dear Bridegroom;<br/>Jesus! May our hearts make room<br/>To be Your Bride forever.<br/>',NULL,6488,6488);
INSERT INTO stanza VALUES('E1227','2','What our dear Lord desires the most,<br/>Is not to just redeem the lost;<br/>But that some saints would pay the cost,<br/>To be His Bride forever.<br/>',NULL,6489,6489);
INSERT INTO stanza VALUES('E1227','3','As virgins we must single be,<br/>No other husband could have we,<br/>That when He comes we''ll then be free<br/>To be His Bride forever.<br/>',NULL,6490,6490);
INSERT INTO stanza VALUES('E1227','4','How could we love this fading world,<br/>When Christ desires the one great pearl;<br/>To Him we must our love unfurl<br/>To bring Him back forever.<br/>',NULL,6491,6491);
INSERT INTO stanza VALUES('E1228','1','The Bible is the Word of God,<br/>Its message is but one —<br/>Christ and the church, His holy Bride,<br/>The two becoming one.<br/>',NULL,6492,6492);
INSERT INTO stanza VALUES('E1228','chorus','Oh, what a miracle that we could be His Bride!<br/>Oh, what a miracle! All else we lay aside<br/>That we may now prepare to meet Him in the air<br/>And ever in our Bridegroom''s love abide.<br/>',NULL,6493,6493);
INSERT INTO stanza VALUES('E1228','2','The Father is the mighty God,<br/>His purpose is but one —<br/>To find a Bride for Christ the Lord<br/>And give her to His Son.<br/>',NULL,6494,6494);
INSERT INTO stanza VALUES('E1228','3','The Son is Jesus Christ the Lord,<br/>His heart desire''s but one —<br/>To have a loving counterpart,<br/>A Bride He''s wooed and won.<br/>',NULL,6495,6495);
INSERT INTO stanza VALUES('E1228','4','The Spirit is but Christ Himself,<br/>He is the Lord applied<br/>To generate the men of earth,<br/>Transform them as His Bride.<br/>',NULL,6496,6496);
INSERT INTO stanza VALUES('E1228','5','The living Word is Jesus too,<br/>God-breathed as life to us,<br/>That we be wholly sanctified,<br/>A Bride all-glorious.<br/>',NULL,6497,6497);
INSERT INTO stanza VALUES('E1229','1','The church is Christ''s deep longing<br/>And His good pleasure too.<br/>His every word and action<br/>Is made with her in view.<br/>His heart''s love is established,<br/>And nought can Him deter;<br/>Before the earth''s foundation<br/>His thoughts were filled with her.<br/>',NULL,6498,6498);
INSERT INTO stanza VALUES('E1229','2','The eve of all creation<br/>He mused on His delight,<br/>And pondered every feature,<br/>Well-pleasing in His sight.<br/>Creation sprang to being,<br/>But deep in Him did hide<br/>A heart of depth unfathomed<br/>Fixed on a glorious Bride.<br/>',NULL,6499,6499);
INSERT INTO stanza VALUES('E1229','3','And thus His will was ''stablished<br/>His counterpart to gain;<br/>This blessed, firm intention,<br/>Eternally the same,<br/>Though sin should e''en beguile man,<br/>Then mock his helpless state,<br/>He never could forsake her,<br/>His yearning ne''er abate.<br/>',NULL,6500,6500);
INSERT INTO stanza VALUES('E1229','4','Then mercy richly flourished,<br/>And love was, oh, so vast,<br/>As graciously He sought her<br/>With wisdom unsurpassed.<br/>The love He gave to win her<br/>God only comprehends!<br/>His life laid down, an offering<br/>Whose fragrance yet ascends.<br/>',NULL,6501,6501);
INSERT INTO stanza VALUES('E1229','5','And now in resurrection<br/>To her He draws most near,<br/>And with untold affection<br/>In glory does appear.<br/>As she beholds her Bridegroom,<br/>His glory floods her heart,<br/>''Til she, His Bride, is raptured,<br/>His longed-for counterpart.<br/>',NULL,6502,6502);
INSERT INTO stanza VALUES('E1230','1','One new man is the Father''s plan;<br/>He redeemed us from the sons of men.<br/>Every kindred, tribe and tongue,<br/>In Himself He called us to be one.<br/>God''s expression on the earth<br/>Now reveals His glorious worth.<br/>One new man is the Father''s plan;<br/>He redeemed us from the sons of men.<br/>',NULL,6503,6503);
INSERT INTO stanza VALUES('E1230','2','On the cross ordinances slain,<br/>That He might form just one of twain.<br/>Reconciling us to God,<br/>Thus on the serpent''s head He trod.<br/>He breaks down the middle wall<br/>As upon His name we call;<br/>On the cross ordinances slain,<br/>That He might form just one of twain.<br/>',NULL,6504,6504);
INSERT INTO stanza VALUES('E1230','3','For this cause Your Person, Lord,<br/>We take and stand in one accord;<br/>All the members self forsake,<br/>And of the Body-Christ partake.<br/>We in Christ as one new man<br/>Now come forth to take this land.<br/>For this cause Your Person, Lord,<br/>We take and stand in one accord.<br/>',NULL,6505,6505);
INSERT INTO stanza VALUES('E1231','1','O praise the Lord, God has a plan —<br/>That''s why He formed a man;<br/>To exercise authority,<br/>Subdue the earth entirely.<br/>O what a joy to be<br/>In His recovery,<br/>O praise God He made me a V.I.P.<br/>',NULL,6506,6506);
INSERT INTO stanza VALUES('E1231','2','O hallelujah, Christ became<br/>A man to die for me.<br/>And dying once my life to be,<br/>In spirit now He lives in me.<br/>The man supreme is He,<br/>My all He came to be;<br/>O hallelujah, He lives in me!<br/>',NULL,6507,6507);
INSERT INTO stanza VALUES('E1231','3','O hallelujah, I''m a man,<br/>The center of God''s plan.<br/>I''m God''s own image made to be,<br/>Expressing His authority.<br/>It''s great to be a man,<br/>O praise God, I''m a man,<br/>O hallelujah, I am a man!<br/>',NULL,6508,6508);
INSERT INTO stanza VALUES('E1231','4','O hallelujah, one new man,<br/>The building for God''s plan!<br/>God''s plan throughout eternity —<br/>Not man, but men built corporately.<br/>This man cannot be beat,<br/>All things beneath his feet,<br/>Christ and the church one man complete.<br/>',NULL,6509,6509);
INSERT INTO stanza VALUES('E1232','1','Once by nature we were dead in sin,<br/>In a world of utter discord;<br/>But together God has quickened us,<br/>Raised us up to sit together with the Lord.<br/>',NULL,6510,6510);
INSERT INTO stanza VALUES('E1232','chorus','Jesus is getting us together,<br/>Come and see the saints in one accord.<br/>His love is knitting us together,<br/>To the stature of the fullness of the Lord.<br/>',NULL,6511,6511);
INSERT INTO stanza VALUES('E1232','2','Thus with all saints we can apprehend,<br/>All the vast dimensions of God.<br/>Knowing Christ''s love passes all we know.<br/>We''re together filled to fullness with our God.<br/>',NULL,6512,6512);
INSERT INTO stanza VALUES('E1232','3','Now we know the purpose of our God,<br/>Visible the mystery became;<br/>Christ, the church, together now we see,<br/>And together put the enemy to shame.<br/>',NULL,6513,6513);
INSERT INTO stanza VALUES('E1232','4','For this cause we pray the Father God —<br/>Strengthen Thou with might our inner man;<br/>Make Yourself at home in all our hearts,<br/>Root us, ground us in Your love and for Your plan.<br/>',NULL,6514,6514);
INSERT INTO stanza VALUES('E1232','5','In the Body we''ll be fitly framed<br/>As the many members Christ supply;<br/>Working in the measure of each part,<br/>All by growth in love the Body edify.<br/>',NULL,6515,6515);
INSERT INTO stanza VALUES('E1232','6','Now we''re one His purpose to fulfill,<br/>As the one new man of His plan.<br/>Unto Him be glory in the church,<br/>And in Jesus Christ forevermore — Amen!<br/>',NULL,6516,6516);
INSERT INTO stanza VALUES('E1233','1','O home in the church,<br/>Where we''ve ended our search<br/>With the brothers rejoicing all day;<br/>Where Christ is our life,<br/>And we''re through with all strife,<br/>Now we''re home, hallelujah, to stay!<br/>',NULL,6517,6517);
INSERT INTO stanza VALUES('E1233','chorus','Home, home in the church;<br/>Yes, it''s here that we''ve ended our search;<br/>And through all our days<br/>We will shout to His praise,<br/>"Hallelujah for Christ and the church!"<br/>',NULL,6518,6518);
INSERT INTO stanza VALUES('E1233','2','Here God is at rest,<br/>Of His treasures the best —<br/>How His heart is rejoicing all day!<br/>His home is our heart,<br/>Ne''er for Satan a part,<br/>Here His glory He''ll fully display.<br/>',NULL,6519,6519);
INSERT INTO stanza VALUES('E1233','chorus','God''s home is the church;<br/>Yes, it''s here that He ended His search;<br/>And through all our days<br/>We will shout to His praise,<br/>"Hallelujah for Christ and the church!"<br/>',NULL,6520,6520);
INSERT INTO stanza VALUES('E1234','1','I thirsted in the barren land of Babylon<br/>And nothing satisfying there I found;<br/>But to the blessed local church one day I came,<br/>Where springs of living water do abound.<br/>',NULL,6521,6521);
INSERT INTO stanza VALUES('E1234','chorus','Drinking at the springs of living water,<br/>Happy now am I,<br/>My heart they satisfy;<br/>Drinking at the springs of living water,<br/>O wonderful and bountiful supply!<br/>',NULL,6522,6522);
INSERT INTO stanza VALUES('E1234','2','How sweet the living water from the hills of God,<br/>It''s flowing in and flowing out of me;<br/>O now I''ve found the place for which I long had sought,<br/>Where there is life and life abundantly.<br/>',NULL,6523,6523);
INSERT INTO stanza VALUES('E1234','3','O brother, won''t you gather in the local church?<br/>A fountain here is flowing deep and wide.<br/>The Shepherd now would bring you to the local church,<br/>Where thirsty spirits can be satisfied.<br/>',NULL,6524,6524);
INSERT INTO stanza VALUES('E1235','1','Oh, listen to the wanderer<br/>In whom there was a lack;<br/>Then hearken to the song he sings<br/>And follow in his track.<br/>',NULL,6525,6525);
INSERT INTO stanza VALUES('E1235','chorus','Praise the Lord, praise the Lord,<br/>Praise the Lord, Hallelujah! Hallelujah!<br/>Praise the Lord, praise the Lord,<br/>I''ll never be the same!<br/>',NULL,6526,6526);
INSERT INTO stanza VALUES('E1235','2','A wanderer within the world<br/>For pleasure ever seeks;<br/>Be it in body or in mind,<br/>With vanity it reeks.<br/>',NULL,6527,6527);
INSERT INTO stanza VALUES('E1235','3','For self I labored day and night,<br/>My castles build in sand;<br/>But, praise the Lord, He wrecked them all —<br/>Much better things He planned.<br/>',NULL,6528,6528);
INSERT INTO stanza VALUES('E1235','4','Once all for self — confused, alone,<br/>How could I bear the shame?<br/>But now within the local church<br/>I''ll never be the same.<br/>',NULL,6529,6529);
INSERT INTO stanza VALUES('E1235','5','I am a happy member now<br/>Within the local church.<br/>A wanderer has found his home<br/>And ended all his search.<br/>',NULL,6530,6530);
INSERT INTO stanza VALUES('E1235','6','I was an individualist,<br/>An island in myself;<br/>But now the Lord is building me<br/>With others in Himself<br/>',NULL,6531,6531);
INSERT INTO stanza VALUES('E1235','7','I''m drawn together with His own<br/>In fellowship so sweet.<br/>I''ve learned from others to receive<br/>Of Christ whene''er we meet.<br/>',NULL,6532,6532);
INSERT INTO stanza VALUES('E1235','8','My wanderings have really ceased —<br/>I''ve found the church, God''s best!<br/>The secret of my happiness —<br/>Enjoying God''s own rest!<br/>',NULL,6533,6533);
INSERT INTO stanza VALUES('E1236','1','In the church the sound of life upon our ear is falling,<br/>Then we see the joy of Christ expressed on every hand;<br/>Babylon and things of earth in vain to us are calling.<br/>We are home forever in Christ our land.<br/>',NULL,6534,6534);
INSERT INTO stanza VALUES('E1236','chorus','We''re churching in the Spirit<br/>On the church''s local ground;<br/>We''re churching with our brothers,<br/>Our family we have found.<br/>Oh, yes, we''re churching with the churches,<br/>and we''ll make the earth resound<br/>With hallelujahs for Christ our land!<br/>',NULL,6535,6535);
INSERT INTO stanza VALUES('E1236','2','Far away our background seems with all its gifts and teaching,<br/>Farther still, the worldly things with all their foul demand;<br/>As the love of Jesus Christ our inmost heart is reaching,<br/>Not a thing can move us from Christ our land.<br/>',NULL,6536,6536);
INSERT INTO stanza VALUES('E1236','3','"I will build My church upon this rock," said the Lord Jesus,<br/>And we see the building of His purpose and His plan;<br/>Setting members in the Body as Himself it pleases,<br/>Building us together in Christ our land.<br/>',NULL,6537,6537);
INSERT INTO stanza VALUES('E1236','4','Now the Lord''s recovery is everywhere proceeding,<br/>All the churches join in one to give the Lord command:<br/>"Speed the day when all the earth will echo with pray-reading<br/>And with hallelujahs for Christ our land."<br/>',NULL,6538,6538);
INSERT INTO stanza VALUES('E1237','1','Splendid church life! His green garden!<br/>He has brought us, praise the Lord!<br/>To experience the Christ Who''s growing here!<br/>He is full of rich enjoyment to His saints in one accord;<br/>He is new and fresh, available and dear!<br/>',NULL,6539,6539);
INSERT INTO stanza VALUES('E1237','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,6540,6540);
INSERT INTO stanza VALUES('E1237','2','It is not a school or factory or a chapel in the air;<br/>But a garden where our Lord can plant and sow.<br/>So He''s placed us all here corporately to be His garden fair,<br/>Where He''s free to cultivate and make us grow.<br/>',NULL,6541,6541);
INSERT INTO stanza VALUES('E1237','3','Thus within the church-life garden there''s a fruit-producing tree<br/>Full of life and so available to eat.<br/>So be simple, don''t be hardened, drop your concepts — eat that tree!<br/>Take in Jesus every moment — He''s so sweet!<br/>',NULL,6542,6542);
INSERT INTO stanza VALUES('E1237','4','With the tree there is the water, flowing God in Christ to us,<br/>Quenching all our dryness, ending all our strife.<br/>Hallelujah! In His garden Jesus flows Himself to us,<br/>As the full supply for us to grow in life.<br/>',NULL,6543,6543);
INSERT INTO stanza VALUES('E1237','5','Aren''t you satisfied and thankful that our Lord has brought you in<br/>Where His pleasures and His riches flow so free?<br/>So be happy and be joyful, in the spirit feast on Him,<br/>So God''s garden can bear fruit abundantly.<br/>',NULL,6544,6544);
INSERT INTO stanza VALUES('E1238','1','Never did I dream before,<br/>Such a place could e''er be found,<br/>Where the tears of sorrow cease,<br/>Songs of endless joy abound.<br/>One who seldom ever sang,<br/>Now delights his voice to raise;<br/>Singing hymns with all the saints,<br/>Echoing the ceaseless praise.<br/>',NULL,6545,6545);
INSERT INTO stanza VALUES('E1238','2','Day by day the world goes on,<br/>Just as it has gone before.<br/>Millions grasp and clutch at life,<br/>Wond''ring if there could be more;<br/>Such was I and would be, yet<br/>Mercy found me out somehow;<br/>With what gratefulness I say,<br/>"I''m in God''s own family now."<br/>',NULL,6546,6546);
INSERT INTO stanza VALUES('E1238','3','How delightful ''tis to know;<br/>How subjective, real, and sweet<br/>Is this inward joy of grace<br/>We experience when we meet;<br/>Life abundant Jesus gives<br/>As my full reality;<br/>Praise You, Lord, it''s really true,<br/>I''m in Your own family.<br/>',NULL,6547,6547);
INSERT INTO stanza VALUES('E1238','4','At the closing of this age,<br/>Just before Your kingdom''s dawn,<br/>May You gain a people, Lord,<br/>For Your dwelling place, Your home.<br/>Since for me You gave Your all,<br/>Everything I lay aside;<br/>For Your church my all I''d give,<br/>That You would be satisfied.<br/>',NULL,6548,6548);
INSERT INTO stanza VALUES('E1239','1','In this age we''re being turned<br/>To the Spirit to be burned;<br/>Now in spirit we can see<br/>Christ, the church, our unity!<br/>',NULL,6549,6549);
INSERT INTO stanza VALUES('E1239','2','In the spirit we can taste<br/>All the riches of Thy grace;<br/>All Thy fullness, blessed Lord<br/>Is for those in one accord!<br/>',NULL,6550,6550);
INSERT INTO stanza VALUES('E1239','3','In the spirit, on the ground —<br/>Here is where Thy life is found.<br/>Dwelling thus in unity,<br/>We enjoy reality!<br/>',NULL,6551,6551);
INSERT INTO stanza VALUES('E1239','4','Out of death and into life,<br/>Done with all divisive strife!<br/>Free indeed to love but Thee,<br/>Growing to maturity!<br/>',NULL,6552,6552);
INSERT INTO stanza VALUES('E1239','5','"Amen, Jesus," is our prayer<br/>To the purging work, whate''er;<br/>Now Thy church must desperate be<br/>More the growth in life to see.<br/>',NULL,6553,6553);
INSERT INTO stanza VALUES('E1239','6','O Lord, make Thy home our heart,<br/>Our true inner man Thou art;<br/>God and man are mingled thus —<br/>Christ, the church, all glorious!<br/>',NULL,6554,6554);
INSERT INTO stanza VALUES('E1240','1','Deeper, deeper, in the cross of Jesus;<br/>Deeper let me go;<br/>Death and life, they always go together;<br/>Deepen, Lord, the flow.<br/>Oh, deeper yet we pray,<br/>Do work in us each day;<br/>Go deeper, through and through,<br/>Till in Thee we''re wholly new.<br/>',NULL,6555,6555);
INSERT INTO stanza VALUES('E1240','2','Higher, higher, in the life of Jesus;<br/>Lord, we are so low.<br/>By Thy life we all can go much higher —<br/>Higher let us go.<br/>Oh, higher yet we pray —<br/>Transform us every day —<br/>And richer in the flow;<br/>May Thy life be all we know.<br/>',NULL,6556,6556);
INSERT INTO stanza VALUES('E1240','3','Growing, growing, in us He is growing,<br/>More and more each day.<br/>Into all our living He is flowing —<br/>This is now His way.<br/>For growth, O Lord, we pray;<br/>Increase in us each day.<br/>It''s not enough to know;<br/>Now Thy life in us must grow.<br/>',NULL,6557,6557);
INSERT INTO stanza VALUES('E1240','4','Living, living, Christ is all our living,<br/>He''s so practical:<br/>Small things, big things, anything and all things —<br/>He''s involved in all.<br/>Live Christ in every way;<br/>Oh, live Him out today.<br/>His name you now must call,<br/>And give Him your all for all.<br/>',NULL,6558,6558);
INSERT INTO stanza VALUES('E1240','5','Person, Person, Jesus is our Person,<br/>Living now in us.<br/>He''s our tastes, our attitudes and actions;<br/>Oh, how glorious!<br/>Our Person, Lord, Thou art;<br/>Make home in all our heart.<br/>As life in every way<br/>Be our Person, Lord, each day.<br/>',NULL,6559,6559);
INSERT INTO stanza VALUES('E1240','6','Churches, churches, in the local churches<br/>We all find the flow:<br/>Deeper, higher, Christ as all our living,<br/>For the church we grow.<br/>The churches are today<br/>Just Christ in every way.<br/>For this, from self we cease,<br/>For Thy Body, Thine increase.<br/>',NULL,6560,6560);
INSERT INTO stanza VALUES('E1240','7','Building, building, we will see the building<br/>Of the church this way;<br/>Christ experienced will produce the building —<br/>He''s the only way.<br/>Oh, build us, Lord, we pray,<br/>By growth of life each day.<br/>Oh, make us now such men<br/>For the new Jerusalem.<br/>',NULL,6561,6561);
INSERT INTO stanza VALUES('E1240','8','Coming, coming, Jesus soon is coming<br/>For His chosen Bride.<br/>In the churches we are all preparing<br/>To be glorified.<br/>Lord Jesus, come again —<br/>This cry is deep within.<br/>We''ll praise Thee to the end,<br/>Oh, come back! Come back! Amen!<br/>',NULL,6562,6562);
INSERT INTO stanza VALUES('E1241','1','God''s life and building can be seen<br/>Within the Song of Songs;<br/>He shows by types His seeking ones,<br/>The Bride for whom Christ longs!<br/>',NULL,6563,6563);
INSERT INTO stanza VALUES('E1241','2','She, as a team of horses shows<br/>A love, so swift and strong!<br/>But this is love that''s natural —<br/>It pulls the world along!<br/>',NULL,6564,6564);
INSERT INTO stanza VALUES('E1241','3','As time goes by, her concepts change,<br/>With dove''s eyes she can see<br/>That naught can with her love compare —<br/>There''s none so dear as He!<br/>',NULL,6565,6565);
INSERT INTO stanza VALUES('E1241','4','A lily she is now to Him<br/>(For still the Lord draws on),<br/>Her faith is not in earthly toil,<br/>But in the wondrous Son.<br/>',NULL,6566,6566);
INSERT INTO stanza VALUES('E1241','5','She''s next a dove who hides herself<br/>Within a cloven rock;<br/>Now in her Lord''s ascended life<br/>Is love which knows no shock!<br/>',NULL,6567,6567);
INSERT INTO stanza VALUES('E1241','6','Of smoke, a pillar she''s become,<br/>And now, as wand''ring ends,<br/>Her wills to His will are subdued,<br/>What fragrance sweet ascends!<br/>',NULL,6568,6568);
INSERT INTO stanza VALUES('E1241','7','Behold His couch... (O, can this be?)<br/>E''en midst the fearsome night.<br/>She now affords her Lord such rest,<br/>The foe is put to flight!<br/>',NULL,6569,6569);
INSERT INTO stanza VALUES('E1241','8','A vessel to contain the King!<br/>(This type is full of worth.)<br/>A palanquin He''s made Himself<br/>For His move on the earth!<br/>',NULL,6570,6570);
INSERT INTO stanza VALUES('E1241','9','Of wood this vessel is composed:<br/>Christ''s ris''n humanity.<br/>Its silver pillars for support<br/>And floor of gold we see!<br/>',NULL,6571,6571);
INSERT INTO stanza VALUES('E1241','10','The seat of purple signifies<br/>Christ is of kings the King.<br/>To Him, as fittings for within,<br/>Their love His dear ones bring!<br/>',NULL,6572,6572);
INSERT INTO stanza VALUES('E1241','11','The day will come — (''tis surely soon)<br/>And glad will be Thy heart —<br/>What boast and glory to Thyself;<br/>Thy crown, Thy counterpart!<br/>',NULL,6573,6573);
INSERT INTO stanza VALUES('E1241','12','A garden fair, enclose is she<br/>With spices, fragrant, sweet.<br/>She now brings forth materials<br/>The building to complete!<br/>',NULL,6574,6574);
INSERT INTO stanza VALUES('E1241','13','A city pleasant, comely, too;<br/>No greater building, this!<br/>So beautiful, yet to the foe<br/>A conq''ring army ''tis!<br/>',NULL,6575,6575);
INSERT INTO stanza VALUES('E1241','14','As we eat Jesus, praise the Lord,<br/>The transformation''s done,<br/>Until at last, the work''s complete —<br/>Christ and His Bride are one!<br/>',NULL,6576,6576);
INSERT INTO stanza VALUES('E1242','1','The Lord, the seed of life, has sown Himself into our heart<br/>To grow up into fullness and become His counterpart.<br/>The seed requires no rules or forms, for water is its need —<br/>By this the all-inclusive seed will grow in us indeed!<br/>',NULL,6577,6577);
INSERT INTO stanza VALUES('E1242','chorus','The seed is simply Jesus! Oh, Jesus lives in me!<br/>And by His growth this seed in us will reach maturity.<br/>',NULL,6578,6578);
INSERT INTO stanza VALUES('E1242','2','The growth of Christ, the seed, in us will soon produce the wheat,<br/>The life within break forth-yet work divine is not complete;<br/>For wheat alone can never be the seed''s expression true;<br/>So all the grains must blend together into something new.<br/>',NULL,6579,6579);
INSERT INTO stanza VALUES('E1242','chorus','The seed is simply Jesus; now wheat is Jesus too!<br/>The grains of wheat must blend together into something new.<br/>',NULL,6580,6580);
INSERT INTO stanza VALUES('E1242','3','The individual grains of wheat no longer must be free,<br/>But crushed together, ground to powder, every grain must be,<br/>Until the wheat becomes the meal from which the loaf is formed<br/>Till all the saints will blend and to His Body be conformed.<br/>',NULL,6581,6581);
INSERT INTO stanza VALUES('E1242','chorus','We all must take the grinding until the Christ within<br/>Can mold into His Body all the individual grains.<br/>',NULL,6582,6582);
INSERT INTO stanza VALUES('E1242','4','The seed is planted, wheat is grown and meal is the sum<br/>Of all the growth upon God''s farm, where Christians grow as one;<br/>But all the growth in life is for the building of the church,<br/>That God and man may have a home and both may end their search.<br/>',NULL,6583,6583);
INSERT INTO stanza VALUES('E1242','chorus','The farm is for the building, for God and man a home,<br/>Where both may dwell among His people gathered into one.<br/>',NULL,6584,6584);
INSERT INTO stanza VALUES('E1242','5','God''s building is produced by silver, precious stones, and gold —<br/>From meal through transformation, pressure, heat, and pain untold.<br/>The meal must not be satisfied to stay as meal alone,<br/>But must submit to transformation into precious stone.<br/>',NULL,6585,6585);
INSERT INTO stanza VALUES('E1242','chorus','The meal must pass through suffering that precious stones be formed;<br/>Then built into God''s building, to His purpose full conformed.<br/>',NULL,6586,6586);
INSERT INTO stanza VALUES('E1242','6','From fullest growth and transformation comes a pearl of worth;<br/>This simple, precious, all-inclusive gem will then come forth.<br/>Conceived in death and formed in life by that all-glorious One,<br/>The church, the Bride, the fruit of all the work that He has done.<br/>',NULL,6587,6587);
INSERT INTO stanza VALUES('E1242','chorus','The pearl is what He''s after, the Bride to please His heart,<br/>So single, pure and precious, and His very counterpart.<br/>',NULL,6588,6588);
INSERT INTO stanza VALUES('E1242','7','The growth in life begins when planted on God''s farm we''re found;<br/>The growing seed becomes the wheat from which the meal is ground.<br/>But building work proceeds when meal submits to be transformed;<br/>Then gold and silver, precious stone for building will be formed.<br/>',NULL,6589,6589);
INSERT INTO stanza VALUES('E1242','chorus','The farm is for the building, built up by precious stones,<br/>From which the priceless pearl comes forth to be His Bride, His own.<br/>',NULL,6590,6590);
INSERT INTO stanza VALUES('E1242','8','Lord, keep us poor in spirit, pure in heart that we may be<br/>Good ground in which the seed of life may grow abundantly,<br/>Until the final stage is reached and You are satisfied<br/>And have Your priceless, chosen pearl, Your joy complete, Your Bride.<br/>',NULL,6591,6591);
INSERT INTO stanza VALUES('E1242','chorus','Lord, keep us poor in spirit and purified in heart,<br/>That growing up in us You may bring forth Your counterpart.<br/>',NULL,6592,6592);
INSERT INTO stanza VALUES('E1243','1','We are one in the spirit, by His life we are one,<br/>We have left all divisions, Body-life has begun,<br/>For the Lord broke all barriers, proclaiming,<br/>"It is done."<br/>',NULL,6593,6593);
INSERT INTO stanza VALUES('E1243','chorus','Brothers:<br/>In the church we are brothers,<br/>Praise the Lord, praise the Lord!<br/>',NULL,6594,6594);
INSERT INTO stanza VALUES('E1243','chorus','Sisters:<br/>In the church we are sisters,<br/>Praise the Lord, praise the Lord!<br/>(Praise the Lord!)<br/>',NULL,6595,6595);
INSERT INTO stanza VALUES('E1243','chorus','Everyone:<br/>And we praise Him that our unity<br/>has now been restored.<br/>',NULL,6596,6596);
INSERT INTO stanza VALUES('E1243','2','We are one in the spirit, yet it goes deeper still,<br/>For this oneness is spreading to our mind, emotion, will,<br/>As we all stand together that His purpose He fulfill.<br/>',NULL,6597,6597);
INSERT INTO stanza VALUES('E1243','3','We are one in the spirit, we are one actually,<br/>Not in talk nor in theory, but in fact, practically,<br/>In the churches we''re all enjoying this reality.<br/>',NULL,6598,6598);
INSERT INTO stanza VALUES('E1243','4','We are one in the spirit in each locality,<br/>For the Lord''s own intention we would consecrated be,<br/>That the oneness He''s given us the whole world may see.<br/>',NULL,6599,6599);
INSERT INTO stanza VALUES('E1244','1','Behold how good a thing<br/>It is to dwell in peace;<br/>How pleasing to our King,<br/>This fruit of righteousness;<br/>When brethren all in one agree,<br/>They know the joy of unity!<br/>',NULL,6600,6600);
INSERT INTO stanza VALUES('E1244','2','When all are sweetly joined<br/>(True followers of the Lamb),<br/>They''re one in heart and mind,<br/>They think and speak the same;<br/>When all in love together dwell;<br/>The comfort is unspeakable!<br/>',NULL,6601,6601);
INSERT INTO stanza VALUES('E1244','3','Where unity takes place,<br/>The joys of heav''n we prove;<br/>This is the gospel grace,<br/>The unction from above;<br/>The Spirit on all saints is shed,<br/>Descending swift from Christ the Head.<br/>',NULL,6602,6602);
INSERT INTO stanza VALUES('E1244','4','Where unity is found,<br/>The sweet anointing grace<br/>Extends to all around,<br/>And shines from every face;<br/>To every praising saint it comes,<br/>And fills him with divine perfumes.<br/>',NULL,6603,6603);
INSERT INTO stanza VALUES('E1244','5','On all His chosen ones<br/>The precious oil comes down:<br/>Anointing as it runs,<br/>Anointing on and on.<br/>E''en to His skirts (the meanest name<br/>That longs to love the bleeding Lamb).<br/>',NULL,6604,6604);
INSERT INTO stanza VALUES('E1244','6','From Aaron''s beard it rolls,<br/>(Those nearest to His face),<br/>The humble, trembling souls<br/>Who know abundant grace;<br/>The grace, the grace for all is free,<br/>For, lo, it reaches now to me!<br/>',NULL,6605,6605);
INSERT INTO stanza VALUES('E1245','1','Thessalonians 1:6; Philippians 3:17<br/>1. When the brothers are in order,<br/>And you sense Christ is their life,<br/>Follow them and watch for Jesus,<br/>Ending thus your thought and strife.<br/>',NULL,6606,6606);
INSERT INTO stanza VALUES('E1245','2','Follow brothers, follow sisters,<br/>When you sense Christ is their life,<br/>Follow brothers, follow sisters,<br/>Help prepare the Bride for Christ.<br/>',NULL,6607,6607);
INSERT INTO stanza VALUES('E1245','3','When you follow, as you follow,<br/>Take the blood, and call His name;<br/>Much assurance He will give you,<br/>And the enemy you''ll shame.<br/>',NULL,6608,6608);
INSERT INTO stanza VALUES('E1245','4','Follow brothers, follow sisters,<br/>When you sense Christ is their life,<br/>Follow brothers, follow sisters,<br/>Help prepare the Bride for Christ.<br/>',NULL,6609,6609);
INSERT INTO stanza VALUES('E1245','5','When they speak, as they are speaking,<br/>Open wide your heart to them,<br/>Thus the Word of God receiving,<br/>Word of God, and not of men.<br/>',NULL,6610,6610);
INSERT INTO stanza VALUES('E1245','6','Follow brothers, follow sisters,<br/>When you sense Christ is their life,<br/>Follow brothers, follow sisters,<br/>Help prepare the Bride for Christ.<br/>',NULL,6611,6611);
INSERT INTO stanza VALUES('E1245','7','Now the Word of God is running,<br/>Running fast, and running free.<br/>This is how the Lord is moving,<br/>In His own recovery.<br/>',NULL,6612,6612);
INSERT INTO stanza VALUES('E1245','8','Follow brothers, follow sisters,<br/>When you sense Christ is their life,<br/>Follow brothers, follow sisters,<br/>Help prepare the Bride for Christ.<br/>',NULL,6613,6613);
INSERT INTO stanza VALUES('E1245','9','O be glad, rejoice, dear brothers,<br/>For the coming wedding day.<br/>Then the Bride will be made ready —<br/>Those who followed all the way.<br/>',NULL,6614,6614);
INSERT INTO stanza VALUES('E1245','10','Follow brothers, follow sisters,<br/>When you sense Christ is their life,<br/>Follow brothers, follow sisters,<br/>Help prepare the Bride for Christ.<br/>',NULL,6615,6615);
INSERT INTO stanza VALUES('E1246','1','We give ourselves to follow the churches,<br/>Oneness in Christ display;<br/>Follow His move in all of the churches,<br/>Stand fast as one this way.<br/>',NULL,6616,6616);
INSERT INTO stanza VALUES('E1246','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus —<br/>He follows perfectly!<br/>',NULL,6617,6617);
INSERT INTO stanza VALUES('E1246','2','We give ourselves to follow the followers,<br/>By this we truly learn;<br/>Never desiring to be the leaders,<br/>But to the Spirit turn.<br/>',NULL,6618,6618);
INSERT INTO stanza VALUES('E1246','3','We give ourselves the flock''s steps to follow,<br/>Knowing the Shepherd''s care.<br/>Now in the churches Jesus is leading<br/>And He is speaking there.<br/>',NULL,6619,6619);
INSERT INTO stanza VALUES('E1246','4','We give ourselves to Thee, O Lord Jesus,<br/>Never to turn aside;<br/>Where''er the Lamb goes, there we would follow,<br/>Follow whate''er betide.<br/>',NULL,6620,6620);
INSERT INTO stanza VALUES('E1246','5','We give ourselves to enter the kingdom,<br/>That marriage feast, with Him;<br/>Come persecution, suffering, and trials,<br/>Still we will enter in.<br/>',NULL,6621,6621);
INSERT INTO stanza VALUES('E1246','6','Christ want some followers here in the churches,<br/>Followers of whom to say:<br/>"These saw My purpose, followed Me wholly" —<br/>May we be those today!<br/>',NULL,6622,6622);
INSERT INTO stanza VALUES('E1247','1','If our hearts would be established;<br/>If in spirit we would be;<br/>If we would be overcomers;<br/>Follow Jesus constantly.<br/>',NULL,6623,6623);
INSERT INTO stanza VALUES('E1247','chorus','Follow Jesus in the spirit;<br/>Be the overcomers true;<br/>Follow Jesus every moment —<br/>Jesus, help us follow You.<br/>',NULL,6624,6624);
INSERT INTO stanza VALUES('E1247','2','If we would be built together;<br/>If related we would be;<br/>To be fitly framed together;<br/>Follow brothers constantly.<br/>',NULL,6625,6625);
INSERT INTO stanza VALUES('E1247','chorus','Follow brothers for the building;<br/>Never independent be;<br/>Follow brothers, be in order,<br/>Functioning in harmony.<br/>',NULL,6626,6626);
INSERT INTO stanza VALUES('E1247','3','If we''re for the Lord''s recovery;<br/>If the earth the Lord''s would be;<br/>If we would bring in the kingdom;<br/>Follow churches constantly.<br/>',NULL,6627,6627);
INSERT INTO stanza VALUES('E1247','chorus','Follow all the local churches;<br/>Thus, the kingdom we will see.<br/>Follow in the churches'' flowing<br/>For the Lord''s recovery.<br/>',NULL,6628,6628);
INSERT INTO stanza VALUES('E1247','4','We would all be better followers,<br/>Taking in with joy the Word;<br/>It enables us to follow<br/>Brothers, churches, and our Lord.<br/>',NULL,6629,6629);
INSERT INTO stanza VALUES('E1247','chorus','Follow Jesus; follow brothers;<br/>Follow churches in the flow;<br/>By the Word of God amening<br/>We can all attain this goal.<br/>',NULL,6630,6630);
INSERT INTO stanza VALUES('E1248','1','Recall how David swore,<br/>"I''ll not come into my house,<br/>Nor go up to my bed,<br/>Give slumber to mine eyelids,<br/>Until I find a place for Thee,<br/>A place, O Lord, for Thee."<br/>Our mighty God desires a home<br/>Where all His own may come.<br/>',NULL,6631,6631);
INSERT INTO stanza VALUES('E1248','2','How blinded we have been,<br/>Shut in with what concerns us;<br/>While God''s house lieth waste —<br/>Lord, break through, overturn us;<br/>We''ll go up to the mountain,<br/>Bring wood and build the house;<br/>We''ll never say, "Another day!"<br/>It''s time! We''ll come and build!<br/>',NULL,6632,6632);
INSERT INTO stanza VALUES('E1248','3','O Lord, against these days,<br/>Inspire some for Your building,<br/>Just as in David''s day —<br/>A remnant who are willing<br/>To come and work in Your house,<br/>Oh, what a blessed charge!<br/>Your heart''s desire, is our desire —<br/>We come, O Lord, to build.<br/>',NULL,6633,6633);
INSERT INTO stanza VALUES('E1248','4','Within those whom You''d call<br/>Put such a restless caring<br/>For building to give all —<br/>These times are for preparing;<br/>The gates of hell cannot prevail<br/>Against the builded Church!<br/>The hours are few, the builders too —<br/>Lord, build, O build in us!<br/>(Repeat last four lines)<br/>',NULL,6634,6634);
INSERT INTO stanza VALUES('E1249','1','How oft believers through the years<br/>Have sought the will of Jesus,<br/>And would have offered everything<br/>To walk as Him it pleases.<br/>If you should seek the will of God,<br/>Don''t waste another minute;<br/>The church life is His glorious will,<br/>And you too must get in it.<br/>',NULL,6635,6635);
INSERT INTO stanza VALUES('E1249','2','"What is the will of God for me?"<br/>How oft you''ve asked this question.<br/>It is the church life, corporately,<br/>Where God finds His expression.<br/>Don''t watch the church life from afar,<br/>Or erringly construe it;<br/>Come gaze upon it from within —<br/>You''ll give your whole life to it.<br/>',NULL,6636,6636);
INSERT INTO stanza VALUES('E1249','3','The church life here is realized,<br/>''Tis all the Lord intended;<br/>And in this rich experience<br/>All further seeking''s ended.<br/>The church life is His glorious will —<br/>Now for yourself begin it.<br/>The surest way to know His will<br/>Is simply to get in it.<br/>',NULL,6637,6637);
INSERT INTO stanza VALUES('E1249','4','So let us give our all for this,<br/>And hold ourselves not dearly;<br/>The church life is the will of God,<br/>Let''s take our standing clearly.<br/>Oh, we have found the will of God;<br/>Christ died and rose to win it.<br/>The church life is His glorious will,<br/>And, praise the Lord, we''re in it!<br/>',NULL,6638,6638);
INSERT INTO stanza VALUES('E1250','1','O surely I will not come in<br/>Within my house to stay,<br/>Nor yet give sleep unto my eyes,<br/>Till Jesus has His way.<br/>Upon the earth, the Lord desires<br/>A place where He may live;<br/>For this, Thy habitation, Lord,<br/>Myself I fully give.<br/>',NULL,6639,6639);
INSERT INTO stanza VALUES('E1250','2','We heard of it while yet far off,<br/>We found it in the way;<br/>We then came up into her courts,<br/>And here we''ll ever stay.<br/>Arise, O Lord, into Thy rest,<br/>Thou and Thy ark so strong.<br/>Thy priests are clothed with righteousness;<br/>Thy saints with joy and song.<br/>',NULL,6640,6640);
INSERT INTO stanza VALUES('E1250','3','The Lord has sworn in truth to us,<br/>He will not turn away —<br/>His Seed shall sit with Him enthroned,<br/>And reign with Him for aye.<br/>The Lord hath found a place to dwell,<br/>Hath chosen Zion fair;<br/>His habitation it will be,<br/>It is His rest fore''er.<br/>',NULL,6641,6641);
INSERT INTO stanza VALUES('E1250','4','Her food abundant He will bless,<br/>Her needy, satisfy;<br/>And with salvation clothe her priests,<br/>And all her want supply.<br/>The horn of David''s budding here,<br/>A lamp for earth''s dark night.<br/>His enemies are clothed with shame,<br/>His saints with crowns of light.<br/>',NULL,6642,6642);
INSERT INTO stanza VALUES('E1250','5','And now within these latter days,<br/>Amidst earth''s dark unrest,<br/>God''s house is being built again<br/>And all His people blessed.<br/>Secure within the local church,<br/>With saints in one accord<br/>We meet to just release our praise,<br/>And thus enjoy the Lord.<br/>',NULL,6643,6643);
INSERT INTO stanza VALUES('E1251','1','To Jerusalem we''ve come,<br/>We are through with Babylon,<br/>We have gathered to be one,<br/>O glory be to God!<br/>Of the teachings we''re bereft,<br/>All opinions we have left,<br/>Spirit from the soul is cleft,<br/>In the local churches now.<br/>',NULL,6644,6644);
INSERT INTO stanza VALUES('E1251','chorus','Hallelujah! Hallelujah!<br/>We are all in one accord<br/>For the building of the Lord,<br/>Hallelujah! Hallelujah!<br/>We are living in the local churches now!<br/>',NULL,6645,6645);
INSERT INTO stanza VALUES('E1251','2','That recovery may proceed<br/>Real priests are what we need —<br/>Those who live in Christ indeed,<br/>O glory be to God!<br/>Saturated with the Lord,<br/>They have Christ as their reward.<br/>These the building work afford<br/>In the local churches now.<br/>',NULL,6646,6646);
INSERT INTO stanza VALUES('E1251','3','And the kingship we must see<br/>With divine authority —<br/>To this rule we''ll all agree,<br/>O glory be to God!<br/>To the Spirit we''ll submit<br/>For the church''s benefit —<br/>This is His prerequisite<br/>In the local churches now.<br/>',NULL,6647,6647);
INSERT INTO stanza VALUES('E1251','4','We the altar must obtain,<br/>Have our all upon it lain.<br/>The burnt-offering must be slain,<br/>O glory be to God!<br/>This we never should dispute,<br/>For the church be absolute,<br/>All that''s otherwise uproot<br/>In the local churches now.<br/>',NULL,6648,6648);
INSERT INTO stanza VALUES('E1251','5','The foundation now is laid —<br/>O what glory doth pervade!<br/>We are all with joy arrayed,<br/>O glory be to God!<br/>Let us raise a mighty shout —<br/>They will hear us far without,<br/>And the enemy we''ll rout<br/>In the local churches now.<br/>',NULL,6649,6649);
INSERT INTO stanza VALUES('E1252','1','Down in Babylon, in captivity,<br/>Oh, the Lord has stirred our spirit up!<br/>Scattered everywhere, without unity,<br/>Oh, the Lord has stirred out spirit up!<br/>Stirred up! Stirred up!<br/>Oh, the Lord has stirred our spirit up!<br/>',NULL,6650,6650);
INSERT INTO stanza VALUES('E1252','2','Up from Babylon, where the sects abound,<br/>From division we must all rise up!<br/>Brothers, Babylon''s not the proper ground;<br/>From division we must all rise up!<br/>Rise up! Rise up!<br/>From division we must all rise up!<br/>',NULL,6651,6651);
INSERT INTO stanza VALUES('E1252','3','To Jerusalem, from captivity,<br/>God is with us, let us all go up!<br/>To the one unique ground of unity,<br/>God is with us, let us all go up!<br/>Go up! Go up!<br/>God is with us, let us all go up!<br/>',NULL,6652,6652);
INSERT INTO stanza VALUES('E1252','4','Platters full of Christ, bowls with Spirit filled —<br/>All the vessels of the Lord bring up!<br/>Bring them to the church as the Lord has willed —<br/>All the vessels of the Lord bring up!<br/>Bring up! Bring up!<br/>All the vessels of the Lord bring up!<br/>',NULL,6653,6653);
INSERT INTO stanza VALUES('E1252','5','In Jerusalem, chosen of the Lord,<br/>Now the temple of the Lord build up!<br/>Serve with all the saints, share in one accord,<br/>Now the temple of the Lord build up!<br/>Build up! Build up!<br/>Now the temple of the Lord build up!<br/>',NULL,6654,6654);
INSERT INTO stanza VALUES('E1253','1','Lord, Thy word of old to David<br/>We have heard and hear it now:<br/>"On Thy throne will sit forever<br/>Thine own seed — this is My vow."<br/>This has been fulfilled in Jesus<br/>Seated on the throne on high,<br/>Sitting on the throne of David<br/>Resurrected, ne''er die.<br/>',NULL,6655,6655);
INSERT INTO stanza VALUES('E1253','2','Then another promise followed<br/>David''s seed upon the throne:<br/>"I''ll rebuild His tabernacle<br/>And by this I will be known."<br/>Lord, we thank Thee, Thou art faithful<br/>To perform Thy promised word.<br/>David''s tabernacle, ruined,<br/>Soon by Thee will be restored.<br/>',NULL,6656,6656);
INSERT INTO stanza VALUES('E1253','3','Lord, we are that tabernacle,<br/>Thy rebuilding work on earth;<br/>Lord, restore Thyself a dwelling<br/>Where is seen Thy boundless worth.<br/>Thus shall all of mankind seek Thee,<br/>And the Gentiles call Thy name.<br/>From Thy holy tabernacle<br/>All the earth shall know Thy fame.<br/>',NULL,6657,6657);
INSERT INTO stanza VALUES('E1253','4','Hasten, Lord, Thy work upon us<br/>To restore and build us now.<br/>For this work we give ourselves, Lord;<br/>Here to Thee we make a vow:<br/>"Though our strength is weak and feeble,<br/>Yet our hearts would ever be<br/>From this day, Lord, for Thy building,<br/>Now and for eternity."<br/>',NULL,6658,6658);
INSERT INTO stanza VALUES('E1254','1','This is the time for building the temple of the Lord<br/>That all the local churches may fully be restored.<br/>''Tis not the time for our house while God''s house lieth waste —<br/>O brothers, for God''s building, rise up, make haste!<br/>',NULL,6659,6659);
INSERT INTO stanza VALUES('E1254','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,6660,6660);
INSERT INTO stanza VALUES('E1254','2','O hear, the Lord is speaking: Consider now your ways,<br/>Ye sow and bring in little, for lacking is My praise.<br/>Go up into the mountain, material to provide,<br/>And build My house that I may be glorified.<br/>',NULL,6661,6661);
INSERT INTO stanza VALUES('E1254','3','Ye who are priests, ye remnant of Christians now obey —<br/>The Lord Himself is with us, whatever men may say,<br/>With spirits stirred and burning, now let us come to work;<br/>May none his part with others in building shirk.<br/>',NULL,6662,6662);
INSERT INTO stanza VALUES('E1254','4','I''ll fill this house with glory, the Lord of hosts has said,<br/>And the desire of nations will be exhibited.<br/>Its glory will be greater than all that''s gone before,<br/>And we will share this glory forevermore.<br/>',NULL,6663,6663);
INSERT INTO stanza VALUES('E1255','1','We are for the Lord''s recovery<br/>Of the local church;<br/>We are for the Lord''s recovery<br/>Of the city and the earth.<br/>Standing on the ground of oneness,<br/>Oneness in the Lord,<br/>We are building up the temple<br/>Of our glorious Lord.<br/>',NULL,6664,6664);
INSERT INTO stanza VALUES('E1255','2','We are for the Lord''s,<br/>We are for the Lord''s,<br/>We are for the Lord''s recovery!<br/>We are for the Lord''s,<br/>We are for the Lord''s,<br/>We are for the Lord''s recovery!<br/>',NULL,6665,6665);
INSERT INTO stanza VALUES('E1255','3','We are for the Lord''s recovery!<br/>To our hearts so dear;<br/>When we exercise our spirit,<br/>Our vision is so clear.<br/>Babylon the Great is fallen,<br/>Satan is cast down,<br/>And the local church is builded<br/>On the local ground.<br/>',NULL,6666,6666);
INSERT INTO stanza VALUES('E1256','1','Praise the Lord, we''re in the Lord''s recovery —<br/>Home at last, here in the church.<br/>Praise the Lord, we''re in the new creation —<br/>One new man, the end of our search.<br/>With the saints, builded, coordinated;<br/>No more I, forever "we".<br/>We are one in the Son, standing here till He comes;<br/>Yes, nothing can stop our God till He''s done!<br/>',NULL,6667,6667);
INSERT INTO stanza VALUES('E1257','1','Do you see them in the cities,<br/>Meeting on the local ground?<br/>They''re the local, golden lampstands,<br/>Where the Lord His home has found.<br/>',NULL,6668,6668);
INSERT INTO stanza VALUES('E1257','chorus','''Tis the local church, the church God has chosen,<br/>Where all the saints dwell as one!<br/>''Tis the local church, the church God has chosen,<br/>Where all the saints dwell as one!<br/>',NULL,6669,6669);
INSERT INTO stanza VALUES('E1257','2','Do you see them in the meetings,<br/>Lifting up their voice on high,<br/>Every brother, sister sharing,<br/>Christ the Lord to magnify?<br/>',NULL,6670,6670);
INSERT INTO stanza VALUES('E1257','3','Do you hear them all pray-reading,<br/>Breathing in the living Word?<br/>Praying, praising, drinking, feeding,<br/>How they all enjoy the Lord!<br/>',NULL,6671,6671);
INSERT INTO stanza VALUES('E1257','4','Do you hear them call, "Lord Jesus"?<br/>How they love that blessed name!<br/>All the more their joy increases<br/>As His Lordship they proclaim.<br/>',NULL,6672,6672);
INSERT INTO stanza VALUES('E1257','5','Have you heard their hallelujahs,<br/>Like a mighty thunder blast?<br/>Hallelujah! Hallelujah!<br/>Down the enemy is cast!<br/>',NULL,6673,6673);
INSERT INTO stanza VALUES('E1257','6','Do you see the saints migrating?<br/>Praise the Lord the move is on<br/>For the church in every city<br/>That our blessed Lord may come!<br/>',NULL,6674,6674);
INSERT INTO stanza VALUES('E1257','7','Do you see the Lord is coming<br/>For the church for whom He died?<br/>In the churches He''s preparing<br/>Now His holy, chosen Bride.<br/>',NULL,6675,6675);
INSERT INTO stanza VALUES('E1257','chorus','''Tis a glorious church without spot or wrinkle,<br/>Filled with the glory of the Lord!<br/>''Tis a glorious church without spot or wrinkle,<br/>Filled with the glory of the Lord!<br/>',NULL,6676,6676);
INSERT INTO stanza VALUES('E1258','1','Oh, how lovable, how precious<br/>Are Thy local churches, Lord!<br/>My soul longeth, even fainteth<br/>For the courts of Thine abode;<br/>''Tis my heart''s deep thirst and longing<br/>And my spirit deeply sighs;<br/>Fellowship among the churches —<br/>For this my whole being cries.<br/>',NULL,6677,6677);
INSERT INTO stanza VALUES('E1258','2','Blessed is the man whose heart, to<br/>Zion, is an open way;<br/>He''s the one whose strength is in Thee;<br/>He will praise Thee all the day.<br/>In communion with the churches,<br/>Trusting Thee, Thy praise he sings;<br/>Passing through the weeping valley,<br/>It becomes a place of springs.<br/>',NULL,6678,6678);
INSERT INTO stanza VALUES('E1258','3','One day spent among Thy churches,<br/>Better than a thousand is!<br/>Even to the lowest member,<br/>Sun and shield Jehovah is.<br/>Grace and glory, every good thing,<br/>On us now He doth outpour;<br/>Blessed is that man who dwelleth<br/>In the churches evermore.<br/>',NULL,6679,6679);
INSERT INTO stanza VALUES('E1259','1','See the local churches,<br/>''Midst the earth''s dark night;<br/>Jesus'' testimony,<br/>Bearing Him as light.<br/>Form by Him, unmeasured,<br/>In the Spirit''s mold —<br/>All are one in nature.<br/>One pure work of gold.<br/>',NULL,6680,6680);
INSERT INTO stanza VALUES('E1259','chorus','See the local churches,<br/>''Midst the earth''s dark night;<br/>Burning in the Spirit,<br/>Shining forth with Christ.<br/>',NULL,6681,6681);
INSERT INTO stanza VALUES('E1259','2','God in Christ, embodied,<br/>As God''s lampstand, He<br/>Has become the Spirit,<br/>The reality.<br/>Spirit as the lampstand<br/>Has been multiplied;<br/>Many local churches,<br/>Now are realized!<br/>',NULL,6682,6682);
INSERT INTO stanza VALUES('E1259','3','Caring for the churches<br/>Is the Son of Man:<br/>Voice of many waters,<br/>Stars in His right hand;<br/>Eyes aflame; His face is<br/>Shining as the sun;<br/>Churches — fear no trial,<br/>He''s the living One!<br/>',NULL,6683,6683);
INSERT INTO stanza VALUES('E1259','4','What can quench the lampstands?<br/>Who can them defy?<br/>More the opposition —<br/>More they multiply!<br/>Deeper darkness ''round them,<br/>Brighter do they shine.<br/>They are constituted<br/>With the life divine.<br/>',NULL,6684,6684);
INSERT INTO stanza VALUES('E1259','5','Soon the local churches<br/>Shall the Bride become,<br/>Bringing in that city —<br/>New Jerusalem.<br/>Then the many lampstands<br/>Shall one lampstand be;<br/>Triune God expressing,<br/>Universally.<br/>',NULL,6685,6685);
INSERT INTO stanza VALUES('E1259','chorus','Lo, from heav''n descending,<br/>All the earth shall see<br/>God''s complete expression,<br/>For eternity.<br/>',NULL,6686,6686);
INSERT INTO stanza VALUES('E1260','1','We''re in the local church,<br/>God''s chosen ground;<br/>Here we have Christ as life<br/>And blessings all abound.<br/>"In spirit, on the ground" —<br/>Our battle cry;<br/>And we will overcome the enemy<br/>To bring the kingdom nigh.<br/>',NULL,6687,6687);
INSERT INTO stanza VALUES('E1261','1','In Chicago land we must take our stand<br/>To meet Thy demand in these days.<br/>Lord, Thy purpose great doth our heart elate,<br/>As Thy name we now exalt and praise.<br/>',NULL,6688,6688);
INSERT INTO stanza VALUES('E1261','chorus','Purpose, purpose, Thine eternal purpose;<br/>Show forth Christ and shame the enemy;<br/>Purpose, purpose, Thine eternal purpose;<br/>In Chicago realized must be.<br/>',NULL,6689,6689);
INSERT INTO stanza VALUES('E1261','2','All things we forsake for Thy Body''s sake,<br/>Soul-life for us break in Thy way.<br/>We''ve been wrecked by Thee, since Thy plan we see;<br/>On Thine altar everything we lay.<br/>',NULL,6690,6690);
INSERT INTO stanza VALUES('E1261','chorus','Break us! Break us! For Thy purpose break us.<br/>Grant our spirits, Lord, a full release;<br/>Break us! Break us! For Thy purpose break us;<br/>In Chicago, Jesus must increase.<br/>',NULL,6691,6691);
INSERT INTO stanza VALUES('E1261','3','With this vision clear and Thy presence dear,<br/>Our hearts have no fear — forth we go.<br/>Lord, Thy heart''s desire has set us afire;<br/>To Thy chosen ones this vision show:<br/>',NULL,6692,6692);
INSERT INTO stanza VALUES('E1261','chorus','Lampstand, lampstand, see the golden lampstand,<br/>Shining with the glory of the Lord.<br/>Lampstand, lampstand, see the golden lampstand,<br/>In Chicago, Jesus Christ is Lord.<br/>',NULL,6693,6693);
INSERT INTO stanza VALUES('E1262','1','It''s by our mingled spirit, Lord,<br/>That we can shine with Thee,<br/>And be a golden lampstand now<br/>For all the world to see.<br/>It''s not by forms or rituals,<br/>Mere Christianity;<br/>It''s by our Christ enjoyed as life<br/>We all can shine with Thee.<br/>',NULL,6694,6694);
INSERT INTO stanza VALUES('E1262','2','The burning Christ has feet as brass<br/>Which in the furnace burns,<br/>His eyes are as a flame of fire —<br/>''Tis to this Christ we turn!<br/>How could we ever lukewarm be<br/>When on His face we gaze?<br/>O Lord, we give ourselves to You<br/>To set us all ablaze!<br/>',NULL,6695,6695);
INSERT INTO stanza VALUES('E1262','3','The seven golden lampstands in<br/>The seven cities see,<br/>So burning, shining with this Christ,<br/>It''s God''s economy!<br/>We''re absolute that this become<br/>Our full reality<br/>Upon the earth, within the church<br/>In each locality.<br/>',NULL,6696,6696);
INSERT INTO stanza VALUES('E1263','1','There''s a church in New York City,<br/>Standing on the local ground;<br/>There''s a lampstand brightly beaming,<br/>Shining out to millions ''round.<br/>We were raised from every nation,<br/>Every people, tribe, and tongue —<br/>With us God has gained a dwelling,<br/>''Tis where all His own may come,<br/>',NULL,6697,6697);
INSERT INTO stanza VALUES('E1263','2','In our midst, O New York City,<br/>Little do you realize —<br/>Fallen is a seed within you,<br/>''Midst corruption it shall rise;<br/>Rising up in resurrection,<br/>With an increase many fold,<br/>It shall blossom, manifesting<br/>Riches of God''s life untold.<br/>',NULL,6698,6698);
INSERT INTO stanza VALUES('E1263','3','For the church in New York City<br/>Faithfully the saints have prayed.<br/>''Gainst the church in New York City<br/>How the devil is enraged!<br/>For behold, within the center<br/>Of his kingdom, dark and grim,<br/>God has gained a testimony,<br/>Moving, fighting on for Him.<br/>',NULL,6699,6699);
INSERT INTO stanza VALUES('E1263','4','There''s a church in New York City<br/>Who the gospel does proclaim,<br/>To the hungry, poor, and weary,<br/>Sick, imprisoned, and the lame.<br/>Now this gospel of the kingdom<br/>Shall be preached until the end;<br/>Till the Lord who with the kingdom<br/>Of the heavens does descend.<br/>',NULL,6700,6700);
INSERT INTO stanza VALUES('E1263','5','There''s a church in New York City,<br/>Honoring the risen Christ;<br/>Caring for the other churches —<br/>Following in truth and light;<br/>With them in coordination,<br/>We the kingdom will possess;<br/>Fighting as one mighty army,<br/>Till the kingdom''s manifest.<br/>',NULL,6701,6701);
INSERT INTO stanza VALUES('E1264','1','In the age of Revelation,<br/>Out from all denomination,<br/>We are in the local churches,<br/>In spirit one.<br/>Nothing old or religious binds,<br/>Everyone''s a star that shines;<br/>Every church a golden lampstand,<br/>Burning with Christ.<br/>',NULL,6702,6702);
INSERT INTO stanza VALUES('E1264','2','Christ and a burning church,<br/>Christ and a burning church,<br/>Christ and the church with the saints<br/>all shining stars!<br/>Hallelujah! Hallelujah!<br/>Lord, we''ve given our all to Thee<br/>To be burning in the spirit, to be<br/>shining forth with Christ.<br/>',NULL,6703,6703);
INSERT INTO stanza VALUES('E1265','1','The churches are the Body<br/>Of Christ one earth today.<br/>They are His testimony,<br/>That He may have a way.<br/>They are the golden lampstands<br/>In cities far and wide.<br/>They are His fighting army,<br/>And His beloved Bride.<br/>',NULL,6704,6704);
INSERT INTO stanza VALUES('E1265','chorus','The churches, the churches,<br/>Upon the earth today;<br/>Lord, stir our hearts for Thy desire,<br/>And build us, oh, build us, Lord, we pray.<br/>',NULL,6705,6705);
INSERT INTO stanza VALUES('E1265','2','Oh, how we need the churches,<br/>All of them, great and small!<br/>We need their many portions<br/>To profit us withal.<br/>Yes, Lord, enlarge the churches;<br/>We love their needs to bear.<br/>Enlarge our hearts, Lord Jesus,<br/>In fellowship and prayer.<br/>',NULL,6706,6706);
INSERT INTO stanza VALUES('E1265','3','The Lord''s eyes o''er the whole earth<br/>Are running to and fro;<br/>Those seven, burning, searching,<br/>Our heart''s desire to know.<br/>His purpose — many churches,<br/>Built up in one accord;<br/>This golden testimony<br/>Will thus express the Lord.<br/>',NULL,6707,6707);
INSERT INTO stanza VALUES('E1265','4','And soon will be the coming<br/>Of our triumphant King!<br/>He''s coming for the churches<br/>Where His sweet praises ring.<br/>Come, Lord, come reap the firstfruits,<br/>As draws the harvest nigh,<br/>And to Thy throne do take us,<br/>To reign with Thee on high.<br/>',NULL,6708,6708);
INSERT INTO stanza VALUES('E1266','1','Burning, burning, we are burning,<br/>Ever to our spirits turning,<br/>One for Thine eternal purpose, in spirit one.<br/>On the ground of locality,<br/>We express our unity —<br/>Many members, but one Body,<br/>Christ as our Head.<br/>',NULL,6709,6709);
INSERT INTO stanza VALUES('E1266','chorus','Christ and the local church,<br/>Christ and the local church,<br/>Christ and the church, our reality and life,<br/>Hallelujah! Hallelujah!<br/>Lord, we''ve given our lives to You,<br/>For the building of Your Body,<br/>For our building up in love.<br/>',NULL,6710,6710);
INSERT INTO stanza VALUES('E1266','2','Breathing, breathing, we are breathing,<br/>With each breath new life receiving,<br/>What a transformation from the old to the new;<br/>Breathing out the old life from us,<br/>Breathing in new life and oneness,<br/>We are breathing in of Jesus, we are breathing in of life.<br/>',NULL,6711,6711);
INSERT INTO stanza VALUES('E1267','1','We are for the great migration,<br/>And, O Lord, we seek Thy face.<br/>Who? And when? And where? Lord Jesus,<br/>Grant us now Thy blessed grace.<br/>',NULL,6712,6712);
INSERT INTO stanza VALUES('E1267','2','This is for Thy house and city,<br/>This is for Thy kingdom, Lord;<br/>To subdue the earth before us<br/>We are all in one accord.<br/>',NULL,6713,6713);
INSERT INTO stanza VALUES('E1267','3','Of the Father, through Christ Jesus,<br/>By the Spirit''s flowing free;<br/>In our spirit, on the church-ground —<br/>This the way of victory.<br/>',NULL,6714,6714);
INSERT INTO stanza VALUES('E1267','4','Burden us with Thy great plan, Lord;<br/>Consecrated we would be.<br/>To fulfill Thy holy purpose<br/>Saturate us thoroughly.<br/>',NULL,6715,6715);
INSERT INTO stanza VALUES('E1267','5','Build, O build us all together,<br/>Let us here our lessons learn,<br/>Send us forth to many cities<br/>For the church-life there to burn.<br/>',NULL,6716,6716);
INSERT INTO stanza VALUES('E1267','6','Many places need a beachhead<br/>To bring in Thy reign and rule.<br/>Lord, build up the local churches<br/>That Thy kingdom come in full!<br/>',NULL,6717,6717);
INSERT INTO stanza VALUES('E1267','7','Then the earth will give Thee glory<br/>And the devil get the shame.<br/>For Thy kingdom''s rule and reigning<br/>All will praise Thy glorious name.<br/>',NULL,6718,6718);
INSERT INTO stanza VALUES('E1267','8','Blessed days are quickly coming;<br/>We rejoice and give Thee praise<br/>For the glorious consummation<br/>And Thy royal ruling days.<br/>',NULL,6719,6719);
INSERT INTO stanza VALUES('E1267','9','Hallelujah to the Father,<br/>Hallelujah to the Son,<br/>Hallelujah to the Spirit —<br/>Hallelujah, it is done!<br/>',NULL,6720,6720);
INSERT INTO stanza VALUES('E1267','10','Hallelujah for the churches,<br/>Hallelujah for the saints,<br/>Hallelujah for the meetings<br/>And their holy, sweet constraints!<br/>',NULL,6721,6721);
INSERT INTO stanza VALUES('E1267','11','Hallelujah, hallelujah,<br/>Hallelujah we will sing;<br/>Hallelujah, hallelujah,<br/>Hallelujah to our King!<br/>',NULL,6722,6722);
INSERT INTO stanza VALUES('E1268','1','When Noah worked upon the ark as God to him decreed,<br/>So many others watched, yet to his words they gave no heed.<br/>But Noah heard the voice of God and did His word obey;<br/>His business was to build the ark; he couldn''t waste a day.<br/>',NULL,6723,6723);
INSERT INTO stanza VALUES('E1268','chorus','Now Jesus'' testimony, we in the churches see,<br/>The ark of testimony built in each locality.<br/>',NULL,6724,6724);
INSERT INTO stanza VALUES('E1268','2','The generation at that time was evil and perverse;<br/>The wickedness upon the earth was waxing worse and worse.<br/>But Noah stood against the age and ne''er the vision lost.<br/>The ark of testimony must be built at any cost.<br/>',NULL,6725,6725);
INSERT INTO stanza VALUES('E1268','3','There were at that time many men who said they worshipped God;<br/>They served Him and they sacrificed and yet ''twas very odd,<br/>The very thing that God desired they mocked and ridiculed.<br/>Their heart was set upon this age and by the devil ruled.<br/>',NULL,6726,6726);
INSERT INTO stanza VALUES('E1268','4','One day the ark was finished and eight souls were led aboard.<br/>God shut the door and then the heavens opened and outpoured.<br/>It rained, but Noah took no thought for he was safe inside.<br/>When all the earth was flooded, he above it all did ride.<br/>',NULL,6727,6727);
INSERT INTO stanza VALUES('E1268','5','The ark was just God''s testimony on the earth that time.<br/>For God had found a corporate man through<br/>whom His light could shine.<br/>He needed something built through which<br/>He''d fully be expressed,<br/>And now it is the local church where God is manifest.<br/>',NULL,6728,6728);
INSERT INTO stanza VALUES('E1268','6','Be careful lest this age would lead you from<br/>God''s heart''s desire.<br/>For Jesus'' testimony must set all our hearts afire.<br/>The local churches are the ark, God''s testimony true.<br/>For this we leave the age behind and give our hearts anew.<br/>',NULL,6729,6729);
INSERT INTO stanza VALUES('E1269','1','There in old Chaldea, product of man''s fall,<br/>God appeared to Abram — called him from it all.<br/>"Get thee from thy country, from thy father''s clan,<br/>Get thee from thy kindred to another land."<br/>',NULL,6730,6730);
INSERT INTO stanza VALUES('E1269','chorus','Our Lord God Jehovah called a corporate man,<br/>One that would express Him and fulfill His plan.<br/>',NULL,6731,6731);
INSERT INTO stanza VALUES('E1269','2','Through the Lord''s infusion, Abraham became<br/>Father of the faithful — life had changed His name.<br/>Though the Lord''s appearing, brought him to the land,<br/>Still he needed Isaac to fulfill God''s plan.<br/>',NULL,6732,6732);
INSERT INTO stanza VALUES('E1269','3','Isaac from his father did inherit all:<br/>Sonship''s full enjoyment, blessing of God''s call.<br/>Though all things receiving, incomplete was he;<br/>Lacking transformation and maturity.<br/>',NULL,6733,6733);
INSERT INTO stanza VALUES('E1269','4','In his father''s footsteps, Jacob then became<br/>Prince of God, a wrestler, Israel his name;<br/>By the Spirit''s dealing, fully grown, he reigned;<br/>O''er the earth, through Joseph, ruling pow''r obtained.<br/>',NULL,6734,6734);
INSERT INTO stanza VALUES('E1269','5','Thus do Jacob, Isaac, Abraham portray<br/>Path that we, God''s called ones, must walk in today:<br/>Members of the Body, as a corporate man,<br/>We complete His calling and fulfill His plan.<br/>',NULL,6735,6735);
INSERT INTO stanza VALUES('E1270','1','We are the Hebrews! Praise the Lord!<br/>We''re from the other side.<br/>Throughout our hist''ry we have passed<br/>Through rivers deep and wide.<br/>',NULL,6736,6736);
INSERT INTO stanza VALUES('E1270','chorus','Praise the Lord! Praise the Lord!<br/>He has brought<br/>All us river-crossing Hebrews<br/>To the land, to build up<br/>The temple of our God.<br/>',NULL,6737,6737);
INSERT INTO stanza VALUES('E1270','2','Old Noah''s age was so corrupt,<br/>In deep depravity;<br/>So Noah passed across the flood —<br/>That separating sea.<br/>',NULL,6738,6738);
INSERT INTO stanza VALUES('E1270','chorus','Praise the Lord! He has brought<br/>From the old<br/>To a new recovered region<br/>Where he built in this land<br/>An altar for his God.<br/>',NULL,6739,6739);
INSERT INTO stanza VALUES('E1270','3','Then Abraham was called apart,<br/>For God to take a stand;<br/>So through the river he was led<br/>Into a new, good land.<br/>',NULL,6740,6740);
INSERT INTO stanza VALUES('E1270','chorus','Step by step he was led<br/>From Chaldee<br/>Through the river into Canaan,<br/>That good land, there to be<br/>The servant of his God.<br/>',NULL,6741,6741);
INSERT INTO stanza VALUES('E1270','4','The Israelites in bondage were<br/>To Pharaoh''s choking hand.<br/>The God of Hebrews made a way<br/>For them to leave that land.<br/>',NULL,6742,6742);
INSERT INTO stanza VALUES('E1270','chorus','Through the sea, they all passed;<br/>Egypt fell,<br/>Hallelujah! In the good land<br/>They built up God''s own house<br/>To satisfy His heart.<br/>',NULL,6743,6743);
INSERT INTO stanza VALUES('E1270','5','Then wand''ring through the wilderness,<br/>The land they could not find;<br/>Till through the Jordan they did pass<br/>To leave themselves behind.<br/>',NULL,6744,6744);
INSERT INTO stanza VALUES('E1270','chorus','Praise the Lord! In the land<br/>They built up<br/>God''s own temple. Hallelujah!<br/>Praise the Lord! There they dwelt,<br/>His people and their God.<br/>',NULL,6745,6745);
INSERT INTO stanza VALUES('E1270','6','But then religion conquered all,<br/>So John the Baptist came<br/>And buried all beneath that flood.<br/>The Jews were not the same.<br/>',NULL,6746,6746);
INSERT INTO stanza VALUES('E1270','chorus','Buried all! Buried all!<br/>Buried all!<br/>Underneath the Jordan River<br/>Buried all to become<br/>The Hebrews passing through.<br/>',NULL,6747,6747);
INSERT INTO stanza VALUES('E1270','7','Now in the church life, we have left<br/>The world, religion too;<br/>Now we''re the river-crossing ones,<br/>Enjoying Christ so new!<br/>',NULL,6748,6748);
INSERT INTO stanza VALUES('E1270','chorus','Praise the Lord! Praise the Lord!<br/>We have passed<br/>From the oldness, Hallelujah,<br/>Into Christ — one new man.<br/>And now we''re one with Him!<br/>',NULL,6749,6749);
INSERT INTO stanza VALUES('E1270','8','O Lord, You''ve taken us across<br/>The fiery sea of glass,<br/>With all the worldly things beneath;<br/>Across the sea we''ve passed.<br/>',NULL,6750,6750);
INSERT INTO stanza VALUES('E1270','chorus','Praise the Lord! Praise the Lord!<br/>Now we stand<br/>As the Hebrews, Hallelujah,<br/>On the sea! Praise the Lord!<br/>We''ve passed through everything!<br/>',NULL,6751,6751);
INSERT INTO stanza VALUES('E1271','1','We''re the river-crossers, Hebrews is our name;<br/>Crossed the Euphrates, idols all are slain.<br/>Entered into Canaan, left the other side;<br/>Seeking a city, which shall e''er abide.<br/>We are the Hebrews, that''s our real name;<br/>We''ve crossed the river, we are not the same.<br/>Building God''s house that He may dwell on earth,<br/>Building God''s house that He may dwell on earth.<br/>',NULL,6752,6752);
INSERT INTO stanza VALUES('E1271','2','We were bound in Egypt, building for the foe;<br/>God of the Hebrews said, "Let My people go!"<br/>We have crossed the Red Sea, reached the other side;<br/>Pharaoh, his army, perished in the tide.<br/>God of the Hebrews, speak again today;<br/>God of the Hebrews, lead us all the way.<br/>Save all Your people from this crooked age,<br/>Save all Your people from this crooked age<br/>',NULL,6753,6753);
INSERT INTO stanza VALUES('E1271','3','We''re released, and now we build the house of God;<br/>His tabernacle is our true abode.<br/>Forty years of oldness left in Jordan''s tide,<br/>Fight we for Canaan on the kingdom side.<br/>Salvation''s Captain sounds the trump of war;<br/>City by city, take we more and more,<br/>To gain His kingdom, enter into rest,<br/>To gain His kingdom, enter into rest.<br/>',NULL,6754,6754);
INSERT INTO stanza VALUES('E1271','4','What was once God-given soon a form became;<br/>Then John the Baptist did God''s word proclaim —<br/>Make another crossing, God is going on;<br/>Judaism''s over; listen to My Son!<br/>Turn from the prophets, turn unto the Son;<br/>He''s My Beloved, He and I are one;<br/>His Word will save you to the uttermost,<br/>His Word will save you to the uttermost.<br/>',NULL,6755,6755);
INSERT INTO stanza VALUES('E1271','5','Now we''re overcomers on the sea of glass;<br/>This final crossing will forever last.<br/>Sing the song of Moses, make the praise complete,<br/>Look! All our enemies beneath our feet.<br/>We''re overcomers, that''s our real name.<br/>God has His city; Satan gets the shame.<br/>God is our portion for eternity,<br/>God is our portion for eternity.<br/>',NULL,6756,6756);
INSERT INTO stanza VALUES('E1272','1','The birthright God has giv''n to us<br/>Must be our goal, our highest prize,<br/>For we''re the church of the first-born —<br/>Let us our portion realize!<br/>',NULL,6757,6757);
INSERT INTO stanza VALUES('E1272','2','A double portion of the land<br/>Was Joseph''s birthright — and ''tis ours<br/>If we our garments keep from sin,<br/>And stay pure in temptation''s hour.<br/>',NULL,6758,6758);
INSERT INTO stanza VALUES('E1272','3','The priesthood was to Levi giv''n<br/>As his inheritance — for he<br/>Did count his family ties but loss<br/>And owned God''s things supreme to be.<br/>',NULL,6759,6759);
INSERT INTO stanza VALUES('E1272','4','The kingship, Judah did receive<br/>For tending to young Joseph''s need;<br/>Through Benjamin''s adversity,<br/>He was his comforter indeed.<br/>',NULL,6760,6760);
INSERT INTO stanza VALUES('E1272','5','The double portion we would seek,<br/>The priesthood and the kingship too;<br/>Make us so desperate, Lord, for Thee<br/>That Thee, our birthright, we''d pursue.<br/>',NULL,6761,6761);
INSERT INTO stanza VALUES('E1272','6','We would be those who pay the price,<br/>Deny the soul, reject the self;<br/>Ambitious for the birthright thus<br/>We''d gain Thee, Lord, above all else.<br/>',NULL,6762,6762);
INSERT INTO stanza VALUES('E1272','7','The promise, Lord, ''twas giv''n to us,<br/>Oh, let us ne''er this right despise;<br/>Enflame us, Lord, to gain Thyself,<br/>And Thee, our birthright realize.<br/>',NULL,6763,6763);
INSERT INTO stanza VALUES('E1273','1','Christ has called us once to Him,<br/>But He calls us once again.<br/>To His call we say Amen!<br/>Overcome!<br/>For the church has fallen low,<br/>Thinking everything they know,<br/>But the life is missing; so,<br/>Overcome!<br/>',NULL,6764,6764);
INSERT INTO stanza VALUES('E1273','chorus','Overcome! Overcome!<br/>Overcome degraded Christianity!<br/>All your working lay aside,<br/>All the teachings that divide;<br/>Eat the Lord whate''er betide —<br/>Overcome!<br/>',NULL,6765,6765);
INSERT INTO stanza VALUES('E1273','2','Eating is man''s destiny<br/>And the Lord''s recovery;<br/>This defeats the enemy —<br/>Overcome!<br/>Come enjoy the tree of life,<br/>Leave the doctrines, leave the strife!<br/>Overcome by eating Christ —<br/>Overcome!<br/>',NULL,6766,6766);
INSERT INTO stanza VALUES('E1273','3','Teachings ne''er transform the soul,<br/>Teachings never reach God''s goal,<br/>Eating Christ will do it all —<br/>Overcome!<br/>We must overcome to eat,<br/>By ourselves and when we meet,<br/>Eat Him as the feast complete —<br/>Overcome!<br/>',NULL,6767,6767);
INSERT INTO stanza VALUES('E1273','4','Eating gives the manchild birth,<br/>Eating brings the Lord to earth;<br/>Eat Him now midst all the dearth —<br/>Overcome!<br/>Be the manchild Christ requires,<br/>Thus the church that He desires,<br/>Then the Bride that He admires —<br/>Overcome!<br/>',NULL,6768,6768);
INSERT INTO stanza VALUES('E1274','1','In Revelation two and three,<br/>The seven local churches see:<br/>The lessons there for you and me<br/>Are for the Lord''s recovery.<br/>',NULL,6769,6769);
INSERT INTO stanza VALUES('E1274','2','The words to them are words to us,<br/>So that the church be glorious,<br/>And all their warnings we must heed<br/>So that the Lord can meet His need.<br/>',NULL,6770,6770);
INSERT INTO stanza VALUES('E1274','3','To Ephesus, the word is clear:<br/>"To your first love you''re not so near;<br/>You''ve left to work so far away;<br/>Repent, return to Him today."<br/>',NULL,6771,6771);
INSERT INTO stanza VALUES('E1274','4','Thus, we must all turn back to Him,<br/>Leave other loves, for these are sin.<br/>Oh, let us hearken to His call —<br/>If we miss this, we''ve missed it all!<br/>',NULL,6772,6772);
INSERT INTO stanza VALUES('E1274','5','Then unto Smyrna, suffering, sore —<br/>"You have been tried, but something more —<br/>Be faithful unto death," we''re told<br/>(Not just of body but of soul).<br/>',NULL,6773,6773);
INSERT INTO stanza VALUES('E1274','6','Be faithful ''til what''s natural dies;<br/>Your circumstances don''t despise;<br/>The Lord has sent them all to you<br/>To prove that your first love is true.<br/>',NULL,6774,6774);
INSERT INTO stanza VALUES('E1274','7','From Pergamos we clearly see<br/>The world has wed Christianity!<br/>And faithful Antipas did fall —<br/>He dared to stand against it all.<br/>',NULL,6775,6775);
INSERT INTO stanza VALUES('E1274','8','To wed the world we all must fear:<br/>His spoken word will save us here —<br/>If to His speaking we give heed,<br/>We''ll separated be indeed.<br/>',NULL,6776,6776);
INSERT INTO stanza VALUES('E1274','9','Then Thyatira comes at length:<br/>Her mixture with the world her strength.<br/>Fine flour leavened by the yeast,<br/>A harlot riding on a beast.<br/>',NULL,6777,6777);
INSERT INTO stanza VALUES('E1274','10','Lord, we are mixed but hardly know;<br/>To us this mixture fully show.<br/>Each added thing we will refute<br/>Until we''re wholly absolute.<br/>',NULL,6778,6778);
INSERT INTO stanza VALUES('E1274','11','And then from Sardis, we can know<br/>Life is the way that we must go!<br/>She says she''s living, but she''s dead;<br/>She needs to touch the Lord instead.<br/>',NULL,6779,6779);
INSERT INTO stanza VALUES('E1274','12','Lord, take us all the way to life<br/>To overcome the deadness rife.<br/>Away from deadness we would flee<br/>That full of life we''ll always be.<br/>',NULL,6780,6780);
INSERT INTO stanza VALUES('E1274','13','Now Philadelphia comes at last;<br/>That which she has she should hold fast —<br/>The brothers'' love, the name, the word;<br/>This church has satisfied the Lord.<br/>',NULL,6781,6781);
INSERT INTO stanza VALUES('E1274','14','We as the brothers all are one;<br/>We''re one by life, and life alone.<br/>If we His word and name do keep<br/>A glorious building God will reap.<br/>',NULL,6782,6782);
INSERT INTO stanza VALUES('E1274','15','Laodicea warns us all:<br/>From Philadelphia some will fall.<br/>By saying, "I am rich," it''s then<br/>The Lord is outside wanting in.<br/>',NULL,6783,6783);
INSERT INTO stanza VALUES('E1274','16','Lukewarmness we must ever spurn<br/>And in the spirit always burn,<br/>The inward life experience gain,<br/>And pay the price with Him to reign.<br/>',NULL,6784,6784);
INSERT INTO stanza VALUES('E1274','17','Lord, shine Your light on us today<br/>That we may fully go Your way;<br/>Anoint our eyes and let us see<br/>So You can have recovery.<br/>',NULL,6785,6785);
INSERT INTO stanza VALUES('E1275','1','Glorious things of thee are spoken,<br/>Philadelphia, church of love.<br/>These things saith the One who''s holy,<br/>He who''s real speaks from above;<br/>He that has the key of David,<br/>Who the kingdom''s entrance won,<br/>"I will open, no man shutteth" —<br/>He has spoken; it is done.<br/>',NULL,6786,6786);
INSERT INTO stanza VALUES('E1275','2','Hallelujah, Philadelphia,<br/>Thine are works that please the Lord.<br/>Strength thou hast, though just a little<br/>And hast kept His living Word.<br/>Thou His holy name denied not,<br/>But confessed it here below —<br/>Lo, a door is set before thee,<br/>Through which none but thee can go.<br/>',NULL,6787,6787);
INSERT INTO stanza VALUES('E1275','3','Thou, beloved Philadelphia,<br/>Dost His Word of patience keep.<br/>From the hour of trial He''ll save thee,<br/>Which o''er all the world shall sweep.<br/>Troublers too shall know He loves thee;<br/>They to thee must then bow down.<br/>"Hold thou fast, for I come quickly,<br/>That no man may take thy crown."<br/>',NULL,6788,6788);
INSERT INTO stanza VALUES('E1275','4','Hallelujah, overcomers,<br/>"In the temple of My God,<br/>I will build them in as pillars,<br/>Nevermore to go abroad."<br/>God''s own name is written on them<br/>And the new name of the Lord.<br/>With the triune God they''re blended;<br/>They''re the city of our God.<br/>',NULL,6789,6789);
INSERT INTO stanza VALUES('E1275','5','Hallelujah, out of heaven,<br/>Comes the New Jerusalem:<br/>Gates of pearl and walls of jasper,<br/>Mingled with each precious gem.<br/>Philadelphia, Philadelphia,<br/>Has become His Bride so dear.<br/>Now the Spirit in the churches<br/>Speaks to all who have an ear.<br/>',NULL,6790,6790);
INSERT INTO stanza VALUES('E1276','1','Oh, the Lord is quickly coming,<br/>He has spoken in His Word;<br/>And confirmed it by the churches,<br/>For His Spirit we have heard.<br/>',NULL,6791,6791);
INSERT INTO stanza VALUES('E1276','2','Not to all the seven churches<br/>Did the Lord speak in this way;<br/>To the church in Philadelphia<br/>Did He choose these words to say.<br/>',NULL,6792,6792);
INSERT INTO stanza VALUES('E1276','3','Philadelphia, Philadelphia,<br/>Church so full of brotherly love,<br/>You''re the church to bring the Bridegroom<br/>Back to earth from heav''n above.<br/>',NULL,6793,6793);
INSERT INTO stanza VALUES('E1276','4','He that hath the key of David,<br/>He that shuts and opens too,<br/>Knows thy works, O Philadelphia;<br/>That''s why you''re His Bride so true.<br/>',NULL,6794,6794);
INSERT INTO stanza VALUES('E1276','5','Not so strong by worldly standards,<br/>Hidden from religion''s fame;<br/>Jesus loves you, Philadelphia,<br/>For you''re faithful to His name.<br/>',NULL,6795,6795);
INSERT INTO stanza VALUES('E1276','6','By His Word you''re overcoming —<br/>How the Amen does resound!<br/>Just hold fast to what you''ve gotten,<br/>That no man may take your crown.<br/>',NULL,6796,6796);
INSERT INTO stanza VALUES('E1276','7','You have kept His Word of patience;<br/>He will keep you from that hour<br/>Which upon the whole world cometh<br/>When the Lord comes in His power.<br/>',NULL,6797,6797);
INSERT INTO stanza VALUES('E1276','8','"I come quickly," Philadelphia,<br/>Speaks the Lord to none but you;<br/>"Amen! Quickly come, Lord Jesus,"<br/>Answer back His faithful few.<br/>',NULL,6798,6798);
INSERT INTO stanza VALUES('E1277','1','Now in all the churches flowing,<br/>Brotherly love.<br/>Light and life and love bestowing,<br/>Brotherly love.<br/>In the oneness all believing,<br/>Fellowship with all receiving,<br/>Nevermore the Spirit grieving,<br/>Brotherly love.<br/>',NULL,6799,6799);
INSERT INTO stanza VALUES('E1277','2','To maintain the sweet communion,<br/>Brotherly love;<br/>Fellowship and healing union,<br/>Brotherly love.<br/>Love believing for the brothers,<br/>Hoping all things for the others,<br/>Suffering all with one another,<br/>Brotherly love.<br/>',NULL,6800,6800);
INSERT INTO stanza VALUES('E1277','3','For the issue of fruit bearing,<br/>Brotherly love.<br/>Fellowship in oneness sharing,<br/>Brotherly love.<br/>Here our soul life we''re forsaking,<br/>And the Spirit''s way we''re taking,<br/>Now from death to life we''re breaking,<br/>Brotherly love.<br/>',NULL,6801,6801);
INSERT INTO stanza VALUES('E1277','4','Oh, this perfect way of gladness,<br/>Brotherly love!<br/>No more fear, imparting sadness,<br/>Brotherly love!<br/>Now is our sure affirmation,<br/>Life and Spirit our foundation,<br/>Building up, the consummation —<br/>Brotherly love.<br/>',NULL,6802,6802);
INSERT INTO stanza VALUES('E1277','5','Seed of life within us growing,<br/>Brotherly love.<br/>Philadelphia now is flowing,<br/>Brotherly love.<br/>To this love God has restored us;<br/>Everything will fall before us;<br/>Love is over all victorious,<br/>Brotherly love!<br/>',NULL,6803,6803);
INSERT INTO stanza VALUES('E1278','1','In the church of Jesus there is love for you,<br/>Love most pure and tender, love most deep and true;<br/>Why should you be lonely, why for friendship sigh,<br/>When the church of Jesus has a full supply?<br/>',NULL,6804,6804);
INSERT INTO stanza VALUES('E1278','2','In the church of Jesus there is life for you,<br/>Warm as summer sunshine, sweet as morning dew;<br/>Why should you be fearful, why take anxious thought,<br/>Since the church of Jesus cares for those He bought?<br/>',NULL,6805,6805);
INSERT INTO stanza VALUES('E1278','3','In the church of Jesus there is work for you;<br/>Such as even angels might rejoice to do;<br/>Why stand idly sighing for some life work grand,<br/>While the church of Jesus seeks your reaping hand?<br/>',NULL,6806,6806);
INSERT INTO stanza VALUES('E1278','4','In the church of Jesus there''s a place for you;<br/>Glorious, bright, and joyous, right and peaceful too;<br/>Why then like a wand''rer, roam with weary pace,<br/>If the church of Jesus holds for you a place.<br/>',NULL,6807,6807);
INSERT INTO stanza VALUES('E1279','1','What we are, we''re His image;<br/>We''re created in His image,<br/>To express the Christ, subdue the earth,<br/>The purpose of our second birth,<br/>We''re His image, glorious!<br/>',NULL,6808,6808);
INSERT INTO stanza VALUES('E1279','2','What we are, we''re the called ones,<br/>We''ve been called into the purpose.<br/>No longer low in Adam''s fall,<br/>God''s glory is our holy call.<br/>We''re the called ones, glorious!<br/>',NULL,6809,6809);
INSERT INTO stanza VALUES('E1279','3','What we are, we''re the joint-heirs;<br/>We inherit full salvation.<br/>We overcome and share His throne.<br/>All things today we fully own.<br/>We''re the joint-heirs, glorious!<br/>',NULL,6810,6810);
INSERT INTO stanza VALUES('E1279','4','What we are, we''re Christ''s partners:<br/>We share the same anointing.<br/>No longer we''re just serving Him;<br/>His riches we may all share in.<br/>We''re His partners glorious!<br/>',NULL,6811,6811);
INSERT INTO stanza VALUES('E1279','5','What we are, we''re the brothers.<br/>We are all the holy brothers.<br/>The life of Christ we did obtain,<br/>For holiness the gold we gain.<br/>Holy brothers, glorious!<br/>',NULL,6812,6812);
INSERT INTO stanza VALUES('E1279','6','What we are, we''re the lampstand;<br/>We''re the shining forth of Jesus.<br/>In this world''s darkness, sin, and strife,<br/>We''re holding Christ, the light of life.<br/>We''re the lampstand, glorious.<br/>',NULL,6813,6813);
INSERT INTO stanza VALUES('E1280','1','We''ve become the Lord''s dear brothers<br/>Through His resurrection pow''r;<br/>He desires many brothers<br/>Sharing in His triumph hour!<br/>',NULL,6814,6814);
INSERT INTO stanza VALUES('E1280','chorus','Jesus is our Elder Brother,<br/>First-born of God''s sons is He;<br/>He came forth in resurrection,<br/>From religion He is free!<br/>As His church we come together;<br/>Oldness, form, and self deny;<br/>Just to meet with our Big Brother,<br/>Him alone to glorify!<br/>',NULL,6815,6815);
INSERT INTO stanza VALUES('E1280','2','In our Brother''s resurrection<br/>Resurrected we must meet,<br/>Never in our natural standing —<br/>This will make His joy complete!<br/>',NULL,6816,6816);
INSERT INTO stanza VALUES('E1280','3','Every day we must see Jesus<br/>As we''re eating of the Word;<br/>Then we''ll run to all the meetings<br/>Burning, bubbling with the Lord!<br/>',NULL,6817,6817);
INSERT INTO stanza VALUES('E1280','4','In the meetings we are feasting<br/>On the food unlimited.<br/>Jesus always satisfies us,<br/>Feeding us the living bread!<br/>',NULL,6818,6818);
INSERT INTO stanza VALUES('E1280','5','We would satisfy our Brother,<br/>Even though our portion''s small.<br/>Every one must share his "new dish"<br/>For the benefit of all!<br/>',NULL,6819,6819);
INSERT INTO stanza VALUES('E1280','6','Not for message or for speaker,<br/>But to meet the Lord we''re here;<br/>Caring only for His presence,<br/>We would see our Brother dear!<br/>',NULL,6820,6820);
INSERT INTO stanza VALUES('E1281','1','All the meetings Christ appointed<br/>And attended here on earth<br/>Were apart from all religion,<br/>All its rituals, forms, and dearth.<br/>Resurrection, not religion,<br/>Must be our reality;<br/>Let us meet in resurrection,<br/>From all dead religion free.<br/>',NULL,6821,6821);
INSERT INTO stanza VALUES('E1281','2','When the Lord was resurrected,<br/>All religious things were through;<br/>Christ is now our living temple,<br/>Christ is all our offerings too.<br/>With our Lord in resurrection,<br/>Hallelujah, we''re released!<br/>Pity all the old religion —<br/>All our meetings are a feast!<br/>',NULL,6822,6822);
INSERT INTO stanza VALUES('E1281','3','Yet religion-oh, how subtle —<br/>In our blood is hiding out;<br/>God must give us revelation,<br/>All that unseen monster rout.<br/>Lord, we still are too religious —<br/>Down with our religious soul!<br/>We would all release our spirit,<br/>Let each meeting reach the goal.<br/>',NULL,6823,6823);
INSERT INTO stanza VALUES('E1281','4','In the meetings, in the meetings,<br/>On the mountain, at the shore,<br/>Jesus, Jesus, living Jesus,<br/>He is here — what want we more?<br/>Bury all the old religion,<br/>Even Christianity —<br/>Jesus, Jesus, we have Jesus,<br/>He is our reality!<br/>',NULL,6824,6824);
INSERT INTO stanza VALUES('E1282','1','Marching on, marching on, in the Spirit<br/>marching on;<br/>Hallelujah! The churches march on.<br/>Marching on, marching on, in the Spirit<br/>marching on;<br/>Hallelujah! The churches march on.<br/>In the church we see<br/>The Lord''s recovery<br/>And for it the Spirit seven-strong.<br/>The world will know,<br/>Wherever we shall go,<br/>That in our age the Lord''s marching on!<br/>',NULL,6825,6825);
INSERT INTO stanza VALUES('E1283','1','Fight, saints, for Jesus our Lord!<br/>Take in His life, stand in one accord!<br/>Never fear God''s enemy;<br/>Tread on his head triumphantly!<br/>Pray that the daily church life be strong,<br/>That all the saints in spirit press on,<br/>Fighting as the one new man,<br/>Fulfilling our Lord''s great plan!<br/>(Glory! Hallelujah!)<br/>',NULL,6826,6826);
INSERT INTO stanza VALUES('E1284','1','Our eyes have seen the vision:<br/>The goal is now in view,<br/>Christ has defeated Satan,<br/>And sin and death are through.<br/>The way is cut and open,<br/>The paths are all made straight;<br/>We''ve heard the call: Come forward!<br/>We''ve laid aside each weight.<br/>',NULL,6827,6827);
INSERT INTO stanza VALUES('E1284','chorus','Come forward! Come forward!<br/>Our Christ is on the throne.<br/>His ministry, so heavenly,<br/>Brings all — brings all the fighters home.<br/>',NULL,6828,6828);
INSERT INTO stanza VALUES('E1284','2','Our eyes have seen the vision<br/>Since Christ our conquering King<br/>Has called us to the battle,<br/>Which He did surely win.<br/>The vict''ry He bequested<br/>Two thousand years ago<br/>To all the glorious fighters<br/>Who''ll forward with Him go.<br/>',NULL,6829,6829);
INSERT INTO stanza VALUES('E1284','3','Our eyes have seen the vision.<br/>Our Captain leads us on.<br/>To press into our spirit,<br/>To share with Him the throne.<br/>Lord, Thou hast giv''n Thy soldiers<br/>The pow''r to wield the sword,<br/>And made us glorious fighters<br/>Through Spirit, church, and Word.<br/>',NULL,6830,6830);
INSERT INTO stanza VALUES('E1285','1','The faith which once for all was giv''n<br/>Unto the saints of old,<br/>Has been committed unto us<br/>To guard, defend, and hold.<br/>',NULL,6831,6831);
INSERT INTO stanza VALUES('E1285','chorus','And we know whom we have believed<br/>And are persuaded that He is able<br/>To guard, through the Holy Spirit,<br/>Our deposit to that day.<br/>',NULL,6832,6832);
INSERT INTO stanza VALUES('E1285','2','This good deposit is the mark<br/>Of God''s economy,<br/>Without it we will miss the aim<br/>Of His recovery.<br/>',NULL,6833,6833);
INSERT INTO stanza VALUES('E1285','3','The myst''ry of the common faith,<br/>A conscience pure requires;<br/>A holy, separated life<br/>For us the Lord desires.<br/>',NULL,6834,6834);
INSERT INTO stanza VALUES('E1285','4','This outline of the healthy words,<br/>In faith and love we''ll hold;<br/>All different teaching, fruitless talk,<br/>Reject with spirit bold.<br/>',NULL,6835,6835);
INSERT INTO stanza VALUES('E1285','5','Oh, healthful teaching, wholesome words:<br/>The truth of godliness!<br/>Oh, good deposit, common faith,<br/>And life of holiness!<br/>',NULL,6836,6836);
INSERT INTO stanza VALUES('E1285','6','Lord, make us now those faithful men<br/>Who pass on what we''ve heard;<br/>Make us examples of the saints<br/>In spirit, faith, and word.<br/>',NULL,6837,6837);
INSERT INTO stanza VALUES('E1286','1','The Lord has shown the way<br/>Within the church today —<br/>It''s laboring, laboring, laboring on Christ.<br/>Christ is the Canaan land;<br/>In Him we boldly stand,<br/>While laboring, laboring, laboring on Christ.<br/>',NULL,6838,6838);
INSERT INTO stanza VALUES('E1286','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>Through laboring, laboring, laboring on Christ.<br/>',NULL,6839,6839);
INSERT INTO stanza VALUES('E1286','2','The way that God has planned<br/>To labor on the land<br/>Is "Amen, Lord! Amen, Lord! Amen to Your<br/>Word!"<br/>Whene''er He speaks today,<br/>Whatever He may say,<br/>It''s "Amen, Lord! Amen, Lord! Amen to Your Word!"<br/>',NULL,6840,6840);
INSERT INTO stanza VALUES('E1286','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>By "Amen, Lord! Amen, Lord! Amen to Your Word!"<br/>',NULL,6841,6841);
INSERT INTO stanza VALUES('E1286','3','The Lord has also shown<br/>The land we''ll fully own<br/>By following, following, following the church.<br/>Where''er the Body goes,<br/>Howe''er the Spirit flows,<br/>It''s following, following, following the church.<br/>',NULL,6842,6842);
INSERT INTO stanza VALUES('E1286','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>By following, following, following the church.<br/>',NULL,6843,6843);
INSERT INTO stanza VALUES('E1287','1','Let''s take the land! The land that God has given us;<br/>In all our living, Christ can be so much;<br/>To take this land, we have th'' equipment that we need —<br/>The blood, the Word, the Spirit, and the church.<br/>',NULL,6844,6844);
INSERT INTO stanza VALUES('E1287','chorus','Let''s take the land! O Christian brothers,<br/>The land that God has given us.<br/>Be strong and take it, for we can make it<br/>And gain this land so glorious!<br/>','Sisters sing',6845,6845);
INSERT INTO stanza VALUES('E1287','chorus','Let''s take the land! O Christian sisters,<br/>And to these things give earnest heed.<br/>The Lord implores us; He''s gone before us<br/>And given everything we need!<br/>','Brothers sing',6846,6846);
INSERT INTO stanza VALUES('E1287','2','We have the blood! Christ is our spotless offering,<br/>Who gave Himself, our God to satisfy;<br/>And so we come with boldness to the throne of grace,<br/>And all day long, the precious blood apply.<br/>',NULL,6847,6847);
INSERT INTO stanza VALUES('E1287','3','We have the Word! The written Word''s our daily food;<br/>We mix this Word with faith and say "Amen!"<br/>Then thro'' the day, the spoken Word will speak to us<br/>And regulate our living from within.<br/>',NULL,6848,6848);
INSERT INTO stanza VALUES('E1287','4','The Spirit''s ours! The Spirit of reality,<br/>He''s independent of the way we feel;<br/>He dwells in us, and teaches us to dwell in Him,<br/>And guides us into everything that''s real.<br/>',NULL,6849,6849);
INSERT INTO stanza VALUES('E1287','5','We have the church! All saints are needed to possess<br/>The fullness of this vast reality;<br/>Together we will gain this all-inclusive Christ,<br/>And He to us our everything will be.<br/>',NULL,6850,6850);
INSERT INTO stanza VALUES('E1288','1','In Eden''s garden, Satan thought<br/>He''d wreck the Lord''s intention.<br/>And so, conspiring, then, he wrought<br/>His subtle intervention.<br/>To man he entered in,<br/>Became indwelling sin,<br/>And by this deed so bad<br/>He really thought he had<br/>Undone the Lord completely.<br/>',NULL,6851,6851);
INSERT INTO stanza VALUES('E1288','2','''Twas all according to God''s plan<br/>To trap the Devil, Satan.<br/>His sphere of moving narrowed now,<br/>Man''s flesh his habitation;<br/>Though brilliant was his plan<br/>To enter into man,<br/>This man became instead<br/>The means to bruise his head,<br/>And finish him forever.<br/>',NULL,6852,6852);
INSERT INTO stanza VALUES('E1288','3','So Christ put on human flesh —<br/>An act of wisdom purely.<br/>And on the cross did thus enmesh<br/>His foe held so securely.<br/>Though desperate Satan''s plight —<br/>He fought with all his might;<br/>But when the morning came<br/>Christ was alive again,<br/>And Satan crushed forever.<br/>',NULL,6853,6853);
INSERT INTO stanza VALUES('E1289','1','The vict''ry''s won! The Lord has triumphed<br/>o''er the foe!<br/>The vict''ry shout is heard afar and near!<br/>His blood prevails! It giveth us the victory!<br/>And soon the mighty Victor will appear.<br/>',NULL,6854,6854);
INSERT INTO stanza VALUES('E1289','chorus','The vict''ry''s won! O Christian brothers,<br/>The vict''ry''s won! This shout we raise!<br/>In Zion''s city, proclaim His vict''ry<br/>Till all the earth is filled with praise.<br/>','Sisters sing',6855,6855);
INSERT INTO stanza VALUES('E1289','chorus','The vict''ry''s won! O Christian sisters,<br/>The mighty work of Christ is done!<br/>The Lord victorious has conquered for us —<br/>Eternal joys have now begun.<br/>','Brothers sing',6856,6856);
INSERT INTO stanza VALUES('E1289','2','The vict''ry''s won! We''ve overcome the enemy,<br/>The Word of God we boldly testify.<br/>God speaks His Word — in it there''s life and liberty —<br/>And by the Word the devil we defy.<br/>',NULL,6857,6857);
INSERT INTO stanza VALUES('E1289','3','The vict''ry''s won! Beneath our feet the enemy,<br/>For we love not our soul life unto death;<br/>And so we shout, "O Lord, You are our victory!"<br/>And praise our God with all our spirit''s breath.<br/>',NULL,6858,6858);
INSERT INTO stanza VALUES('E1290','1','O Lord, we''ve seen Your purpose to bring the many sons,<br/>To share in Your full glory and see Your kingdom come.<br/>We praise You, Lord, this glory is You, Yourself within,<br/>Spread out in all Your people to shine in all of them.<br/>',NULL,6859,6859);
INSERT INTO stanza VALUES('E1290','2','Since we received Your life, Lord, a seed''s been growing there:<br/>The seed of inward glory, the glory we will share!<br/>By growing ''til the blossom of glory blooms in full,<br/>We''ll thus enjoy Your increase and glory bountiful.<br/>',NULL,6860,6860);
INSERT INTO stanza VALUES('E1290','3','Hail! Captain of Salvation! Our heav''nly Pioneer!<br/>Our praises, midst the battle and tumult, You will hear.<br/>We''re following our Captain all through the mighty fray.<br/>Our glorious, faithful Captain sustains us all the way.<br/>',NULL,6861,6861);
INSERT INTO stanza VALUES('E1290','4','Lord, fighting on to glory, You now have gone before;<br/>Now fighting in Your footsteps we''ll conquer o''er and o''er.<br/>From glory unto glory, we''ll fight until we see<br/>The glory from within us shall manifested be.<br/>',NULL,6862,6862);
INSERT INTO stanza VALUES('E1290','5','Then, Lord, at last the fighting and battle cry will cease,<br/>And we''ll appear in glory, Your kingdom and increase.<br/>That day we''ll be completed, that day Your face we''ll see,<br/>For in that blessed day, Lord, we''ll in the glory be!<br/>',NULL,6863,6863);
INSERT INTO stanza VALUES('E1291','1','At the end of Luke''s gospel, chapter twenty and two,<br/>The Lord says to Peter, "Satan wants to sift you,"<br/>But the Lord''s interceding and His prayer is true,<br/>Hallelujah! He''s prayed for us, we''ll never sift through!<br/>',NULL,6864,6864);
INSERT INTO stanza VALUES('E1291','chorus','Though there''s all kinds of battles in our living each day,<br/>And we always face trials, life is ordered that way,<br/>Still, in all situations, as He intercedes,<br/>He in all things supplies us and meets all of our needs.<br/>',NULL,6865,6865);
INSERT INTO stanza VALUES('E1291','2','Just a Christian alone, however strong he may be<br/>Cannot withstand the sifting of the Lord''s enemy;<br/>Though he might sift one only, yet he''ll ne''er sift two!<br/>Hallelujah! Together we''re too big to sift through!<br/>',NULL,6866,6866);
INSERT INTO stanza VALUES('E1291','3','What wonderful purpose God has purposed for us,<br/>To be transformed and reigning with His Son, glorious;<br/>So it just doesn''t matter what the foe might do —<br/>Hallelujah! The church is much too big to sift through!<br/>',NULL,6867,6867);
INSERT INTO stanza VALUES('E1292','1','An uplifted gospel have we,<br/>One we''re not ashamed to proclaim.<br/>Our gospel''s the highest of all,<br/>For it is God''s goal and God''s aim.<br/>No longer so lowly and poor,<br/>We''ve found that we''re God''s holy sons.<br/>No more will we preach as before;<br/>Now each man on earth can be won.<br/>',NULL,6868,6868);
INSERT INTO stanza VALUES('E1292','2','Our Brother''s inherited all<br/>God made Him to rule His affairs<br/>Appointed — this office He fills<br/>And shares it with us, His joint-heirs.<br/>Elected before earth was formed,<br/>We''ve found that we are qualified<br/>To share all His glory and worth.<br/>How could men but for Christ decide?<br/>',NULL,6869,6869);
INSERT INTO stanza VALUES('E1292','3','Yes, we''re holy brothers with Christ,<br/>No higher could any man be.<br/>This highest of all gospels is;<br/>This gospel each human must see.<br/>Partakers of this heavenly call,<br/>Could any this gospel reject?<br/>With Christ sitting far above all —<br/>This highest of all gospels yet!<br/>',NULL,6870,6870);
INSERT INTO stanza VALUES('E1293','1','O I''m a man —<br/>I''m the meaning of the universe;<br/>Yes, I''m a man —<br/>I''m the meaning of the universe.<br/>God made me such,<br/>I am so much;<br/>I''m the center and the meaning of the universe.<br/>',NULL,6871,6871);
INSERT INTO stanza VALUES('E1293','2','Christ lives in me —<br/>He''s the meaning of my human life.<br/>Christ lives in me —<br/>He''s the meaning of my human life.<br/>Yes, He''s in me<br/>My all to be;<br/>He''s the meaning and reality of my human life.<br/>',NULL,6872,6872);
INSERT INTO stanza VALUES('E1293','3','The church is Christ —<br/>His expression on the earth today.<br/>The church is Christ —<br/>His expression on the earth today.<br/>This corporate man,<br/>Fulfills God''s plan;<br/>That this man may have dominion over all the earth.<br/>',NULL,6873,6873);
INSERT INTO stanza VALUES('E1293','4','The local church —<br/>It''s the new and real family life.<br/>The local church —<br/>It''s the new and real family life.<br/>We have the way<br/>To live today —<br/>Eating, drinking Christ we''re built up as the<br/>local church.<br/>',NULL,6874,6874);
INSERT INTO stanza VALUES('E1293','5','What shall we do?<br/>We should go and tell the world of this.<br/>What shall we do?<br/>We should go and tell the world of this.<br/>Disciple all —<br/>This is our call.<br/>Let us go and spread the news abroad to every land.<br/>',NULL,6875,6875);
INSERT INTO stanza VALUES('E1294','1','Come let us speak till the kingdom of the Lord comes down.<br/>Yes, let us speak till the kingdom of the Lord comes down.<br/>Why hold your peace?<br/>The Word release.<br/>Let us speak until the kingdom of the Lord comes down.<br/>',NULL,6876,6876);
INSERT INTO stanza VALUES('E1294','2','Oh, loose the Word! It shall not return unto<br/>Him void.<br/>Yes, loose the Word! It shall not return unto<br/>Him void!<br/>Let''s sow the seed,<br/>This is our need;<br/>Loose the Word, and it shall not return unto<br/>Him void!<br/>',NULL,6877,6877);
INSERT INTO stanza VALUES('E1294','3','It''s gospel time! Let us spread the gospel all around.<br/>Yes, gospel time! We will never fear the people''s frown!<br/>God''s done His work;<br/>Let us not shirk;<br/>We''re but pilgrims here, and we''ll not fear the<br/>people''s frown!<br/>',NULL,6878,6878);
INSERT INTO stanza VALUES('E1294','4','If we will speak, Christ will witness in the<br/>hearts of men.<br/>If we will speak, Christ will witness in the<br/>hearts of men.<br/>Tell every man,<br/>Win all we can.<br/>Through our speaking, Christ is speaking in<br/>the hearts of men!<br/>',NULL,6879,6879);
INSERT INTO stanza VALUES('E1294','5','The harvest''s ripe! We are preaching the full<br/>gospel now!<br/>The fields are white! We are preaching the full<br/>gospel now!<br/>For this men search —<br/>Christ and the church!<br/>Let us reap the harvest, preaching the full gospel now!<br/>',NULL,6880,6880);
INSERT INTO stanza VALUES('E1295','1','Ours is a fellowship in the gospel<br/>Since we received the Lord;<br/>We''re for the furtherance of the gospel,<br/>Spreading to all His Word.<br/>For its defense and strong confirmation<br/>We all partake of grace —<br/>He who began this work will perfect it<br/>Till we shall see His face.<br/>',NULL,6881,6881);
INSERT INTO stanza VALUES('E1295','2','May all the things that come to us daily<br/>Unto the gospel turn,<br/>That all may see we''re bound for the gospel<br/>And of the Lord may learn.<br/>May we be bold and fearless in spirit,<br/>Speaking the Word of God,<br/>Do it in love and do it in power,<br/>While living in the Lord.<br/>',NULL,6882,6882);
INSERT INTO stanza VALUES('E1295','3','Lord, we''re expecting that we''ll be given<br/>Boldness with every breath.<br/>Christ must be magnified in our body<br/>Whether by life or death.<br/>We hope in nothing to be ashamed,<br/>For us to live is Christ —<br/>He is the Person in all our living,<br/>Our everything, our life.<br/>',NULL,6883,6883);
INSERT INTO stanza VALUES('E1295','4','May all our lives be worthy the gospel<br/>Whatever may betide,<br/>All standing fast in oneness of spirit,<br/>All striving side by side.<br/>Let us proclaim the gospel in fullness<br/>To satisfy the Lord:<br/>Christ is the life, the church His expression,<br/>Sound everywhere abroad.<br/>',NULL,6884,6884);
INSERT INTO stanza VALUES('E1296','1','The universe of God consists<br/>Of heaven, earth and air.<br/>The enemy of God resists<br/>His purpose everywhere.<br/>At first the mighty rebel one<br/>The earth from God obtained;<br/>Then from the Lord the air had won,<br/>Establishing his reign.<br/>',NULL,6885,6885);
INSERT INTO stanza VALUES('E1296','2','So God''s intention was to gain<br/>His kingdom on the earth,<br/>The place where He could fully reign<br/>And show to all His worth.<br/>Thus He began in Genesis<br/>To forward His great plan.<br/>Out of this darkened, lost abyss<br/>Our God created man.<br/>',NULL,6886,6886);
INSERT INTO stanza VALUES('E1296','3','But Satan caused the man to fall<br/>From God''s eternal grace.<br/>Then Abraham received the call<br/>To head the chosen race.<br/>The Jews were led from Pharaoh''s hand<br/>Through sea and wilderness<br/>Into the promised Canaan land,<br/>God''s kingdom to express.<br/>',NULL,6887,6887);
INSERT INTO stanza VALUES('E1296','4','The Israelites refused God''s reign,<br/>Desired an earthly king;<br/>The kingdom then was lost again<br/>Till David was to bring<br/>God''s kingdom back to earth once more<br/>For God to rule through him;<br/>But Israel failed as once before<br/>God''s kingdom to bring in.<br/>',NULL,6888,6888);
INSERT INTO stanza VALUES('E1296','5','Such was the situation when<br/>Our God became a man,<br/>Declaring to all men, "Repent!<br/>The kingdom is at hand."<br/>A perfect model of God''s rule,<br/>The King, full qualified!<br/>But Satan as a desperate fool<br/>Had Jesus crucified.<br/>',NULL,6889,6889);
INSERT INTO stanza VALUES('E1296','6','This Jesus went into the grave<br/>And death He overcame.<br/>Now resurrected He will save<br/>The earth from Satan''s reign.<br/>He as the Spirit enters man<br/>To fill him with His life.<br/>These men, the church, fulfill His plan<br/>To save the earth from strife.<br/>',NULL,6890,6890);
INSERT INTO stanza VALUES('E1296','7','Now on the earth the church we see,<br/>God''s kingdom here expressed,<br/>Where He has full authority<br/>His rule to manifest.<br/>The place where Satan has to flee<br/>Our mighty conquering rod,<br/>The kingdom through the church will be<br/>Brought to the earth for God.<br/>',NULL,6891,6891);
INSERT INTO stanza VALUES('E1297','1','From the beachhead in our spirit<br/>To our mind, emotion, will.<br/>Christ will spread through all our being<br/>And our vessel wholly fill.<br/>He will cast out all rebellion,<br/>Change our darkness into light.<br/>Satan''s kingdom will be swallowed,<br/>And Christ will reign with might.<br/>This is the Lord''s recovery,<br/>This is His very best!<br/>Brothers, give the Lord the ground in you<br/>Till His kingdom''s manifest.<br/>',NULL,6892,6892);
INSERT INTO stanza VALUES('E1298','1','Chosen by God in ages past,<br/>Our God will never let us go;<br/>Salvation is assured fore''er;<br/>''Tis such security we know.<br/>',NULL,6893,6893);
INSERT INTO stanza VALUES('E1298','2','"I give to them eternal life,<br/>They shall not perish," is His word;<br/>"No one shall snatch them from Our hands,"<br/>This is the promise of the Lord.<br/>',NULL,6894,6894);
INSERT INTO stanza VALUES('E1298','3','Yet there''s a word for God''s own sons,<br/>Which is a warning from the Lord:<br/>For those not ready when He comes,<br/>"Worse punishment" and not "reward."<br/>',NULL,6895,6895);
INSERT INTO stanza VALUES('E1298','4','Reward is not eternal life,<br/>It''s based on how we run the race;<br/>It all depends on what we build,<br/>It''s not a matter, here, of grace.<br/>',NULL,6896,6896);
INSERT INTO stanza VALUES('E1298','5','''Tis for God''s kingdom we press on,<br/>Like Moses, we are for the Lord;<br/>We suffer with God''s people here<br/>And look away to the reward.<br/>',NULL,6897,6897);
INSERT INTO stanza VALUES('E1298','6','Richer by far, reproach of Christ,<br/>Than Egypt''s treasures, which are sin;<br/>By faith we leave Egyptian land,<br/>Avoiding next age discipline.<br/>',NULL,6898,6898);
INSERT INTO stanza VALUES('E1298','7','Our soul gained for the kingdom''s age —<br/>For this we lose our soul life here;<br/>If we lay down our soul life now,<br/>We''ll save it for Christ''s kingdom there.<br/>',NULL,6899,6899);
INSERT INTO stanza VALUES('E1298','8','We all must learn to pay the price,<br/>Christ must be worked into our soul;<br/>''Tis thus our soul is gained by Him,<br/>This is our aim and this our goal.<br/>',NULL,6900,6900);
INSERT INTO stanza VALUES('E1299','1','Man''s Creator has a purpose<br/>For our being here on earth.<br/>In His image we''re created,<br/>To express His rule on earth.<br/>But man fell to Satan''s tempting;<br/>Thus God''s goal was hid from view.<br/>Still our God will have His Kingdom,<br/>For His Son will see it through.<br/>',NULL,6901,6901);
INSERT INTO stanza VALUES('E1299','2','Jesus Christ will get His Kingdom<br/>Notwithstanding Satan''s plans;<br/>He''s obtaining something real by<br/>Growing in the hearts of man.<br/>Nothing like religion teaches:<br/>"You must wait until you die" —<br/>For the Kingdom Christ is building,<br/>Is on earth before our eyes.<br/>',NULL,6902,6902);
INSERT INTO stanza VALUES('E1299','3','His Son, Jesus, is our Savior.<br/>Once in human form He came.<br/>Now as Spirit He can enter<br/>As the breath of life to man.<br/>As a seed within our spirit<br/>Christ takes root and starts to grow,<br/>Spreading in our inmost being<br/>Till His life we come to know.<br/>',NULL,6903,6903);
INSERT INTO stanza VALUES('E1299','4','Time is short, oh, brothers, hear it,<br/>Christ is longing for His Bride.<br/>We can hasten His returning,<br/>Simply by the growth in life.<br/>No more struggling, no more striving,<br/>Simply turn to Christ within.<br/>See the seed begin to blossom,<br/>Growing fully into Him.<br/>',NULL,6904,6904);
INSERT INTO stanza VALUES('E1299','5','Jesus Christ will get His Kingdom<br/>Just by growth — the normal way.<br/>Not an instant transformation;<br/>Growth goes on from day to day,<br/>This life-seed is all-inclusive —<br/>Everything we''ll ever need;<br/>Yes, our God''s eternal purpose<br/>Is within this precious seed.<br/>',NULL,6905,6905);
INSERT INTO stanza VALUES('E1300','1','The Lord has been revealed in us,<br/>The kingdom-seed so glorious;<br/>He''s planted deeper than our heart,<br/>And from us He will ne''er depart.<br/>This seed is never satisfied<br/>Just in our spirits to abide;<br/>He wants to grow and spread today<br/>To live in us in every way.<br/>',NULL,6906,6906);
INSERT INTO stanza VALUES('E1300','2','We''re like a glove, an empty man,<br/>So meaningless without a hand;<br/>Lord, saturate each inward part<br/>And form Yourself in all our heart.<br/>The Lord must spread into our mind,<br/>Our natural thoughts and concepts bind;<br/>Imaginations, dreams be gone,<br/>The kingdom-seed in us is sown!<br/>',NULL,6907,6907);
INSERT INTO stanza VALUES('E1300','3','In our emotions He must grow;<br/>Raw, fragile feelings overthrow;<br/>Our love, our hatred, must be His —<br/>Lord, we agree with You for this.<br/>Another part the Lord must fill —<br/>Our hard, unbending, stubborn will;<br/>Lord, our resistance quickly break,<br/>Subdue us for Thy kingdom''s sake.<br/>',NULL,6908,6908);
INSERT INTO stanza VALUES('E1300','4','Our conscience too the Lord must clear,<br/>That we may walk in godly fear;<br/>Our conscience must be keen today,<br/>Else we cannot the Lord obey.<br/>''Tis by His growing, spreading thus,<br/>The Lord will have His home in us;<br/>A place on earth where He is Lord,<br/>Full rights to Him we will afford.<br/>',NULL,6909,6909);
INSERT INTO stanza VALUES('E1301','1','Jesus the kingdom has come into us,<br/>Reigning and shining He''s all glorious,<br/>Christ as the seed is the King who has come,<br/>Into our spirit His kingdom He''s sown.<br/>',NULL,6910,6910);
INSERT INTO stanza VALUES('E1301','chorus','O let Him grow, O let Him grow;<br/>His kingdom life be all we know.<br/>Jesus, the kingdom is sown into us;<br/>Jesus, the kingdom, O how glorious!<br/>',NULL,6911,6911);
INSERT INTO stanza VALUES('E1301','2','We must repent for the kingdom''s at hand;<br/>All that we do, think, or feel, or have planned<br/>Must be abandoned and changed in our mind;<br/>Leave all the world and self-seeking behind.<br/>',NULL,6912,6912);
INSERT INTO stanza VALUES('E1301','3','All of religion has missed it again,<br/>Teaching for doctrines the concepts of men;<br/>They vainly wait for the kingdom to be,<br/>A dispensation they''re hoping to see.<br/>',NULL,6913,6913);
INSERT INTO stanza VALUES('E1301','4','But now the kingdom to us has been shown,<br/>It is no less than our Jesus alone.<br/>It is the Person of Christ in us all,<br/>And it begins as a seed when we call.<br/>',NULL,6914,6914);
INSERT INTO stanza VALUES('E1302','1','All the signs point to the end,<br/>Christ soon will be here again;<br/>We must be ready for Him-<br/>Jesus is coming again!<br/>',NULL,6915,6915);
INSERT INTO stanza VALUES('E1302','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,6916,6916);
INSERT INTO stanza VALUES('E1302','2','From soul and self turn away,<br/>Look unto Jesus today;<br/>There is no time to delay-<br/>Jesus is coming again!<br/>',NULL,6917,6917);
INSERT INTO stanza VALUES('E1302','3','Foolish ones never will turn;<br/>When the Lord comes they will learn<br/>There is no oil left to burn —<br/>Jesus is coming again!<br/>',NULL,6918,6918);
INSERT INTO stanza VALUES('E1302','4','Wise virgins buy up the time;<br/>Never drunk with the world''s wine,<br/>Filled in the spirit they shine-<br/>Jesus is coming again!<br/>',NULL,6919,6919);
INSERT INTO stanza VALUES('E1302','5','Let us go forth unto Him,<br/>Not only with our lamps trimmed,<br/>Buy the oil now lest they dim-<br/>Jesus is coming again!<br/>',NULL,6920,6920);
INSERT INTO stanza VALUES('E1302','6','Jesus is now on His way,<br/>Watch, for you know not the day;<br/>Ever in His presence stay-<br/>Jesus is coming again!<br/>',NULL,6921,6921);
INSERT INTO stanza VALUES('E1303','1','The kingdom of God is at hand:<br/>Ten virgins with lamps lit arise<br/>To go forth to meet the Bridegroom,<br/>But only five virgins are wise.<br/>The wise have abundance of oil,<br/>The foolish are empty instead;<br/>The wise used their time to buy oil,<br/>The others their chance forfeited.<br/>',NULL,6922,6922);
INSERT INTO stanza VALUES('E1303','2','Lord Jesus, Thy message is clear:<br/>You''re coming for those who are wise,<br/>Who buy up their oil today,<br/>Who deal with all hindering ties.<br/>Those virgins whose souls are transformed,<br/>Whose vessels much oil contain,<br/>Who love not their lives unto death —<br/>They in Thy great kingdom shall reign.<br/>',NULL,6923,6923);
INSERT INTO stanza VALUES('E1303','3','Our lamps to shine forth must be trimmed<br/>By calling on Thee every day.<br/>In spirit we much exercise<br/>To burn all the oldness away.<br/>But there is a much deeper need:<br/>Reality in us must grow,<br/>Until it make homes in our hearts,<br/>Till oil in our vessels o''erflows.<br/>',NULL,6924,6924);
INSERT INTO stanza VALUES('E1303','4','We see how this age is so dark,<br/>We know that blest hour is near.<br/>Our Lord may return anytime-<br/>Lord, strike in us this holy fear,<br/>That we may each moment redeem<br/>By taking Thy Word in by prayer,<br/>By learning each lesson You give,<br/>And thus for that hour prepare.<br/>',NULL,6925,6925);
INSERT INTO stanza VALUES('E1303','5','Lord Jesus, how blest to be those<br/>Who bring in Thy kingdom to earth,<br/>Affording Thee rule over all<br/>And showing to all Thy great worth!<br/>How blest to be those at the feast,<br/>Where Thou wilt be one with Thy Bride!<br/>Lord, make us wise virgins for Thee,<br/>Who e''er in Thy presence abide.<br/>',NULL,6926,6926);
INSERT INTO stanza VALUES('E1304','1','Christ comes quickly for His Bride,<br/>Wedding feast He will provide,<br/>Garments bright and pure supplied —<br/>Dress in time!<br/>Taking Christ as life she''s dressed,<br/>By much suffering stitched and pressed;<br/>Righteous acts are thus possessed —<br/>Dress in time!<br/>',NULL,6927,6927);
INSERT INTO stanza VALUES('E1304','chorus','Be in time! Be in time!<br/>For the marriage feast of Jesus<br/>Be in time!<br/>If your soul life you deny<br/>And the Spirit you apply,<br/>Then you''ll fully qualify —<br/>Be in time!<br/>',NULL,6928,6928);
INSERT INTO stanza VALUES('E1304','2','Virgins Christ comes quickly for,<br/>Those with oil an extra store,<br/>Not the fools who oil ignore —<br/>Buy in time!<br/>For the oil a price we pay,<br/>Deal with self without delay,<br/>Fill your vessels every day —<br/>Buy in time!<br/>',NULL,6929,6929);
INSERT INTO stanza VALUES('E1304','3','For His servants Christ will come<br/>And reward each faithful one;<br/>Slothful ones will be undone —<br/>Serve in time!<br/>Make your single talent count,<br/>All self''s problems now surmount,<br/>Serve with Christ, the living fount —<br/>Serve in time!<br/>',NULL,6930,6930);
INSERT INTO stanza VALUES('E1304','4','Christ comes quickly for His grain,<br/>Ripened firstfruits to obtain;<br/>Unripe harvest will remain —<br/>Ripen now!<br/>From earth''s water grain must dry,<br/>From the world your soul deny;<br/>To mature the self must die —<br/>Ripen now!<br/>',NULL,6931,6931);
INSERT INTO stanza VALUES('E1304','5','Overcomers Christ will take,<br/>Those who all for Him forsake,<br/>Those who of first love partake —<br/>Win in time!<br/>All the deadness overcome,<br/>With the living Christ be one,<br/>Toward the goal now swiftly run —<br/>Win in time!<br/>',NULL,6932,6932);
INSERT INTO stanza VALUES('E1304','6','Christ comes for His kingdom too;<br/>Heav''nly reign we must pursue,<br/>Let His rule our self subdue —<br/>Yield in time!<br/>Rebel self must be dethroned,<br/>Lessons must not be postponed,<br/>Quickly yield to Christ enthroned —<br/>Yield in time!<br/>',NULL,6933,6933);
INSERT INTO stanza VALUES('E1305','1','Our faith to God-ward must in these days spread abroad.<br/>To show we''ve turned from idols to the living God.<br/>We''ll mix His Word with faith by answering "Amen!"<br/>And to Christ in the Word turn again and again.<br/>',NULL,6934,6934);
INSERT INTO stanza VALUES('E1305','chorus','Our work of faith must grow exceedingly,<br/>The labor of our love increase abundantly;<br/>His sanctifying work in us go on and on,<br/>While in patience of hope we will watch till<br/>He come.<br/>',NULL,6935,6935);
INSERT INTO stanza VALUES('E1305','2','The love for all the brothers, in our midst is found,<br/>But in these days our love must increase and abound.<br/>The Lord direct our hearts into the love of God<br/>And prepare us in full for the day of the Lord.<br/>',NULL,6936,6936);
INSERT INTO stanza VALUES('E1305','3','Our spirit, soul, and body wholly sanctified-<br/>Our faithful Lord will do it to prepare His Bride,<br/>While we amen His voice in matters great or small,<br/>That we all may be ready to hear Jesus'' call.<br/>',NULL,6937,6937);
INSERT INTO stanza VALUES('E1305','4','The Lord Himself shall come, and we shall be with Him-<br/>Oh, what a glorious hope! Come quickly, Lord, Amen.<br/>We''d ever watchful be to see Thee in the air<br/>And as sons of the day for that meeting prepare.<br/>',NULL,6938,6938);
INSERT INTO stanza VALUES('E1306','1','We love Thy coming, Lord!<br/>We know not when ''twill be,<br/>But turn from all distracting things<br/>Thine own dear face to see.<br/>',NULL,6939,6939);
INSERT INTO stanza VALUES('E1306','2','We serve the living God<br/>And wait His son to see;<br/>For this we need faith, love, and hope,<br/>Increasing constantly.<br/>',NULL,6940,6940);
INSERT INTO stanza VALUES('E1306','3','In Thy dear presence, Lord,<br/>We hope we all may be<br/>A crown of glory and a joy<br/>To those we then shall see.<br/>',NULL,6941,6941);
INSERT INTO stanza VALUES('E1306','4','We love Thy coming, Lord;<br/>The time is very nigh.<br/>Our hearts unblameable must be<br/>To greet Thee from on high.<br/>',NULL,6942,6942);
INSERT INTO stanza VALUES('E1306','5','The Lord Himself shall come<br/>With loud assembling word,<br/>And all the saints in Christ shall be<br/>Forever with the Lord.<br/>',NULL,6943,6943);
INSERT INTO stanza VALUES('E1306','6','We''re children of the day,<br/>We''re children of the light;<br/>That day should never come to us<br/>As does a thief at night.<br/>',NULL,6944,6944);
INSERT INTO stanza VALUES('E1306','7','Lord, wholly sanctify<br/>And blameless let us be<br/>In spirit, soul, and body too<br/>For that blest day with Thee.<br/>',NULL,6945,6945);
INSERT INTO stanza VALUES('E1307','1','The day approaches; Jesus soon is coming.<br/>Redeem the time; it must not slip away.<br/>Lord, make us ready for the cry: "Behold Him!"<br/>By using every moment of each day.<br/>',NULL,6946,6946);
INSERT INTO stanza VALUES('E1307','chorus','When Jesus comes, will we go in to meet Him?<br/>When Jesus comes, will we from self have ceased?<br/>He''s coming soon to take the wise ones with Him.<br/>Oh, let us not be left outside the feast.<br/>',NULL,6947,6947);
INSERT INTO stanza VALUES('E1307','2','Lord, help us to redeem these golden moments;<br/>Our vessels fill with ointment from above;<br/>Help us amen each trial and tribulation;<br/>Increase in us; make us abound in love.<br/>',NULL,6948,6948);
INSERT INTO stanza VALUES('E1307','chorus','He''s coming soon — these moments are so precious.<br/>The oil is here — Oh, let us buy the more.<br/>Amen the trials and welcome tribulations-<br/>The kingdom''s ours through these afflictions sore.<br/>',NULL,6949,6949);
INSERT INTO stanza VALUES('E1307','3','Lord, ever turn us from our soulish pleasures<br/>To gaze upon Thy tender, loving face.<br/>Oh, keep us running forth to meet the Bridegroom<br/>And patiently attending to the race.<br/>',NULL,6950,6950);
INSERT INTO stanza VALUES('E1307','chorus','When Jesus comes, will we be in His presence?<br/>When Jesus comes, will we His face behold?<br/>Oh, let us not return to sloth and folly,<br/>But jealously His loving presence hold.<br/>',NULL,6951,6951);
INSERT INTO stanza VALUES('E1307','4','As His dear Bride, let us go forth to meet Him,<br/>Our lamps well-trimmed, our fires burning bright,<br/>Our vessels filled, our eyes set on His glory,<br/>To be with Him completely satisfied.<br/>',NULL,6952,6952);
INSERT INTO stanza VALUES('E1307','chorus','Yes, satisfied — Christ and His Bride together,<br/>Yes, satisfied — throughout eternity.<br/>Oh, what a rest, what joy, what love, what favor<br/>To be His Bride when He comes to His feast!<br/>',NULL,6953,6953);
INSERT INTO stanza VALUES('E1308','1','We have oil in our lamps — we are burning!<br/>We have oil in our lamps today!<br/>To the spirit, O Lord, keep us turning,<br/>Keep us turning, turning all the way!<br/>',NULL,6954,6954);
INSERT INTO stanza VALUES('E1308','chorus','O Lord! Amen! Hallelujah!<br/>We are burning, burning every day!<br/>O Lord! Amen! Hallelujah!<br/>Turning, turning all the way!<br/>',NULL,6955,6955);
INSERT INTO stanza VALUES('E1308','2','But our vessels need oil for Thy coming;<br/>We must gain a reserve supply.<br/>So our vessels we give for the filling<br/>That our lamps may never, never die.<br/>',NULL,6956,6956);
INSERT INTO stanza VALUES('E1308','chorus','Fill us, Jesus! Fill us, Jesus!<br/>Every moment give us more of Thee!<br/>Fill us, Jesus! Fill us, Jesus!<br/>Fill us with reality!<br/>',NULL,6957,6957);
INSERT INTO stanza VALUES('E1308','3','Then we''ll burn till the Lord comes to meet us,<br/>Then we''ll burn till He comes that day.<br/>Then we''ll go in with Him to the wedding<br/>And be brightly burning all the way.<br/>',NULL,6958,6958);
INSERT INTO stanza VALUES('E1308','chorus','Come, Lord Jesus! Come, Lord Jesus!<br/>Come and find us filled and burning bright!<br/>Come, Lord Jesus! Come, Lord Jesus!<br/>Come and in Thy Bride delight.<br/>',NULL,6959,6959);
INSERT INTO stanza VALUES('E1309','1','Who can tell how soon the Bride may hear the cry,<br/>"Behold, the Bridegroom cometh!"<br/>Hear the shout of triumph ringing in the sky,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6960,6960);
INSERT INTO stanza VALUES('E1309','chorus','We can almost see His glory in the sky;<br/>It must be the dawning of that day is nigh.<br/>How our hearts would leap if we should hear the cry,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6961,6961);
INSERT INTO stanza VALUES('E1309','2','Who will have their lamps trimmed and burning bright?<br/>"Behold, the Bridegroom cometh!"<br/>Extra oil have ready should you hear tonight,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6962,6962);
INSERT INTO stanza VALUES('E1309','3','Who will now be washed by water in the Word?<br/>"Behold, the Bridegroom cometh!"<br/>Spots and wrinkles cleanse before the shout is heard,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6963,6963);
INSERT INTO stanza VALUES('E1309','4','Who will be the counterpart to Christ today?<br/>"Behold, the Bridegroom cometh!"<br/>Ready be to match Him now without delay,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6964,6964);
INSERT INTO stanza VALUES('E1309','5','Who will now be clothed in linen bright and pure?<br/>"Behold, the Bridegroom cometh!"<br/>Act of righteousness will make her rapture sure,<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6965,6965);
INSERT INTO stanza VALUES('E1309','6','Hark! As one the Spirit and the Bride doth say,<br/>"Behold, the Bridegroom cometh!"<br/>Brothers, sisters, this may be the wedding day!<br/>"Behold, the Bridegroom cometh!"<br/>',NULL,6966,6966);
INSERT INTO stanza VALUES('E1310','1','The Lord is longing for His Bride,<br/>All glorious within.<br/>His heart will then be satisfied<br/>When she is fit for Him.<br/>',NULL,6967,6967);
INSERT INTO stanza VALUES('E1310','2','''Tis by the Word the church is made<br/>Holy and pure as He;<br/>All spots and wrinkles it removes<br/>That she His Bride may be.<br/>',NULL,6968,6968);
INSERT INTO stanza VALUES('E1310','3','We must redeem these golden days,<br/>Eating the Word in prayer,<br/>Amening every line and phrase,<br/>And thus for Him prepare.<br/>',NULL,6969,6969);
INSERT INTO stanza VALUES('E1310','4','Oh, how the Word doth penetrate,<br/>Spirit and soul divide,<br/>Revealing every hidden weight<br/>For us to lay aside.<br/>',NULL,6970,6970);
INSERT INTO stanza VALUES('E1310','5','Lord, how we thank Thee for Thy Word,<br/>Living and operative.<br/>Oh, for Thy coming, we are stirred<br/>Ever by it to live!<br/>',NULL,6971,6971);
INSERT INTO stanza VALUES('E1310','6','Lord, make us those who bring Thee back,<br/>Who satisfy Thy heart.<br/>Now by Thy Word supply our lack,<br/>Make us Thy counterpart.<br/>',NULL,6972,6972);
INSERT INTO stanza VALUES('E1311','1','The local churches are preparing for the Lord''s return-<br/>We know the time is near for our Bridegroom so dear.<br/>He''s coming back to claim the Bride for which His heart doth yearn,<br/>That with Him we may be through all eternity.<br/>',NULL,6973,6973);
INSERT INTO stanza VALUES('E1311','chorus','The Christ we love is coming soon,<br/>And He will come as our Bridegroom.<br/>We''ll wait for Him, we''ll watch and pray-<br/>It may be today, it may be today!<br/>',NULL,6974,6974);
INSERT INTO stanza VALUES('E1311','2','How we must give Him all our heart and from all idols turn!<br/>Oh, who else could there be who loves so tenderly?<br/>Lord Jesus, You''re the only One who makes our heart to burn-<br/>O please do not delay! Come quickly, e''en today!<br/>',NULL,6975,6975);
INSERT INTO stanza VALUES('E1311','3','A glorious Bride He is preparing for His wedding day;<br/>She''ll be so bright and pure, fine linen covering her.<br/>O Lord, work in Thy righteousness, this is the only way;<br/>And blessed we will be to join that feast with Thee.<br/>',NULL,6976,6976);
INSERT INTO stanza VALUES('E1312','1','It may be at morn as the day we are greeting;<br/>It may be the time when the saints all are meeting;<br/>But one thing we know, for the Spirit bears witness,<br/>That Jesus will come very soon!<br/>',NULL,6977,6977);
INSERT INTO stanza VALUES('E1312','chorus','O Lord Jesus, Amen!<br/>The church soon will see Thee again!<br/>"Thou art coming! Hallelujah!<br/>Hallelujah, Amen!<br/>Hallelujah, Amen!"<br/>',NULL,6978,6978);
INSERT INTO stanza VALUES('E1312','2','The days hasten by — there''s no time for delaying;<br/>So grasping each moment by watching and praying<br/>And in everything giving thanks and rejoicing,<br/>We''ll welcome our Lord''s return.<br/>',NULL,6979,6979);
INSERT INTO stanza VALUES('E1312','3','An instant, a twinkling, and Jesus descending<br/>Will come for His saints in His glory transcending.<br/>He''ll come as the Bridegroom — as such we''ll behold Him-<br/>To take to Himself His Bride!<br/>',NULL,6980,6980);
INSERT INTO stanza VALUES('E1312','4','What joy, what delight, when we finally meet Him!<br/>The One whom we love — O what rapture to greet Him!<br/>Our Lord and our life, our Beloved, our Bridegroom<br/>Will take to Himself His Bride!<br/>',NULL,6981,6981);
INSERT INTO stanza VALUES('E1313','1','In that bright and golden moment when the<br/>Christ we love shall come,<br/>And the radiance of His glory we shall see;<br/>When the Bride shall meet the Bridegroom and<br/>His loving wife become,<br/>What a meeting, what a meeting that will be!<br/>',NULL,6982,6982);
INSERT INTO stanza VALUES('E1313','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover, with our<br/>Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,6983,6983);
INSERT INTO stanza VALUES('E1313','2','When to all who love His coming He shall<br/>speak the word, "Arise!"<br/>Oh, how blessed for that summons to be free!<br/>With what rapture we shall greet Him as we<br/>join Him in the skies-<br/>What a meeting, what a meeting that will be!<br/>',NULL,6984,6984);
INSERT INTO stanza VALUES('E1313','3','Now in all the local churches we are meeting<br/>day by day<br/>And expecting any moment Christ to see,<br/>But when Jesus comes the meeting starts that<br/>ne''er will pass away-<br/>What a meeting, what a meeting that will be!<br/>',NULL,6985,6985);
INSERT INTO stanza VALUES('E1313','4','Even now while we are meeting, Lord, we<br/>hope to see Thy face<br/>And forever without ceasing be with Thee.<br/>Then we''ll just go right on meeting in another<br/>meeting place-<br/>What a meeting, what a meeting this will be!<br/>',NULL,6986,6986);
INSERT INTO stanza VALUES('E1314','1','Lord, Thou wilt soon appear,<br/>Thy day is almost here.<br/>Oh, how we love Thy coming soon!<br/>We have no other<br/>Lord, life, or lover<br/>Than Thou, Lord Jesus, our Bridegroom!<br/>',NULL,6987,6987);
INSERT INTO stanza VALUES('E1314','2','The hour is drawing nigh,<br/>Soon we shall hear Thy cry<br/>And see Thee in the clouds descend.<br/>Oh what an hour sweet<br/>When Bride and Bridegroom meet<br/>And love surpassing comprehend.<br/>',NULL,6988,6988);
INSERT INTO stanza VALUES('E1314','3','The moments fly apace,<br/>Soon we shall see Thy face!<br/>Amen, Lord Jesus! Quickly come!<br/>We long Thyself to see<br/>And with Thee ever be,<br/>Thou who our inmost heart hath won.<br/>',NULL,6989,6989);
INSERT INTO stanza VALUES('E1314','4','''Tis but a moment now;<br/>Thou our Lord Bridegroom, Thou<br/>Soon wilt return to claim Thy Bride.<br/>O Hallelujah!<br/>''Tis this we long for,<br/>And Thou too wilt be satisfied.<br/>',NULL,6990,6990);
INSERT INTO stanza VALUES('E1315','1','Rejoice! Rejoice! Our Bridegroom''s coming,<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,6991,6991);
INSERT INTO stanza VALUES('E1315','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come;<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,6992,6992);
INSERT INTO stanza VALUES('E1315','2','Oh, let us now redeem each moment,<br/>More the precious oil to buy,<br/>And have our vessels filled with ointment<br/>Ere we hear the midnight cry.<br/>',NULL,6993,6993);
INSERT INTO stanza VALUES('E1315','3','Oh, what a joy it is preparing<br/>For our wedding with the Lord,<br/>E''en in the tribulations sharing<br/>For the bliss of such reward!<br/>',NULL,6994,6994);
INSERT INTO stanza VALUES('E1315','4','Oh, with what rapture and rejoicing<br/>Shall the wedding day begin;<br/>And then a thousand years of dining<br/>At the marriage feast with Him!<br/>',NULL,6995,6995);
INSERT INTO stanza VALUES('E1316','1','Our Bridegroom soon is coming<br/>To claim His holy Bride,<br/>The ones whom He has wooed, won,<br/>And wholly sanctified.<br/>O Lord, we would be ready<br/>And get our hearts in tune<br/>For the wedding day that''s coming<br/>Very soon.<br/>',NULL,6996,6996);
INSERT INTO stanza VALUES('E1316','chorus','Oh, the wedding day is coming,<br/>Is coming very soon,<br/>When the Bride shall be prepared<br/>And shall marry her Bridegroom.<br/>Oh, what love and consecration<br/>Should all our hearts attune<br/>For that wedding day that''s coming<br/>Very soon.<br/>',NULL,6997,6997);
INSERT INTO stanza VALUES('E1316','2','Oh, that fine linen garment<br/>Which on that day we''ll wear<br/>E''en now, Lord, work within us<br/>And stitch by stitch prepare.<br/>For this we would redeem<br/>Every moment opportune<br/>For the wedding day that''s coming<br/>Very soon.<br/>',NULL,6998,6998);
INSERT INTO stanza VALUES('E1316','3','Lord, may Your portion in us<br/>Continually increase<br/>That we may be invited<br/>Unto that wedding feast.<br/>And keep us always watching —<br/>At morning, night, or noon —<br/>For the wedding day that''s coming<br/>Very soon.<br/>',NULL,6999,6999);
INSERT INTO stanza VALUES('E1317','1','When our Lord comes in glory and we''re raptured to His side,<br/>When that bright and glorious moment we shall see,<br/>We shall know our dear Bridegroom as He comes to take His Bride,<br/>And He''ll know the Bride He''s loved so tenderly.<br/>',NULL,7000,7000);
INSERT INTO stanza VALUES('E1317','chorus','We shall know Him! We shall know Him!<br/>When we see Him, our Bridegroom glorified!<br/>He shall know us! He shall know us!<br/>We''re His church, His beloved, and His Bride!<br/>',NULL,7001,7001);
INSERT INTO stanza VALUES('E1317','2','Even now in the Spirit He reveals Himself to us,<br/>And His Person dear we''ve learned to recognize.<br/>But our eyes shall behold Him — O what rapture glorious<br/>When we gaze on Him unveiled in the skies!<br/>',NULL,7002,7002);
INSERT INTO stanza VALUES('E1317','3','In the Word we have seen Him shining forth in truth and grace,<br/>O how blessed to behold His features thus!<br/>But the day soon is coming when we''ll see Him face to face,<br/>He, the living Word, in full revealed to us.<br/>',NULL,7003,7003);
INSERT INTO stanza VALUES('E1317','4','In the brothers and sisters, O how blest to see the Lord,<br/>In their attitudes and actions Christ expressed!<br/>But the day soon is coming when in rapturous accord<br/>We shall see His Person fully manifest.<br/>',NULL,7004,7004);
INSERT INTO stanza VALUES('E1317','5','In the meetings of the churches He''s unveiled increasingly-<br/>O the joy unspeakable and glory too!<br/>As the meetings grow higher we''re expecting soon to see<br/>The full glory of our Lord come into view.<br/>',NULL,7005,7005);
INSERT INTO stanza VALUES('E1318','1','''Twas a day in early springtime,<br/>By an ancient wayside well,<br/>Eliezer paused to rest his camel train.<br/>He had found a bride for Isaac<br/>Ere the evening shadows fell,<br/>For his weary journey had not been in vain.<br/>',NULL,7006,7006);
INSERT INTO stanza VALUES('E1318','chorus','Oh, get ready! Evening shadows fall,<br/>Don''t you hear the Eliezer call?<br/>There''s going to be a wedding,<br/>And our joy will soon begin,<br/>In the evening when the camel train comes in.<br/>',NULL,7007,7007);
INSERT INTO stanza VALUES('E1318','2','So he took the fair Rebekah,<br/>Dressed in jewels rich and rare,<br/>Quickly to her waiting bridegroom far away.<br/>Where Rebekah loved her Isaac,<br/>And he loved Rebekah fair;<br/>Oh, it must have been a happy wedding day.<br/>',NULL,7008,7008);
INSERT INTO stanza VALUES('E1318','3','Now the blessed Holy Spirit,<br/>From our Father God above,<br/>Has come down to earth to find a worthy Bride.<br/>For our Isaac over yonder<br/>Has prepared His tents of love,<br/>And He wants His fair Rebekah by His side.<br/>',NULL,7009,7009);
INSERT INTO stanza VALUES('E1318','4','We have left our kinfolk gladly;<br/>We have bade the world goodbye.<br/>We''ve been called to be His pure and spotless Bride;<br/>Where we''ll soon behold our Jesus<br/>In that blest eternity-<br/>What a happy, happy wedding that will be!<br/>',NULL,7010,7010);
INSERT INTO stanza VALUES('E1319','1','That which for long the prophets sought,<br/>The righteous yearned to see,<br/>Has in these last of days appeared<br/>In its reality.<br/>',NULL,7011,7011);
INSERT INTO stanza VALUES('E1319','chorus','And we''re now in the final stages,<br/>''Tis the completion of all the ages.<br/>All those who believed the promise<br/>Are perfected now in us.<br/>',NULL,7012,7012);
INSERT INTO stanza VALUES('E1319','2','Oh, blessed are our eyes that see,<br/>Our ears, how blessed to hear;<br/>Things angels ne''er could look into<br/>Are now to us made clear.<br/>',NULL,7013,7013);
INSERT INTO stanza VALUES('E1319','3','Our sense is corporate, bold and strong,<br/>His grace, how free to take;<br/>Encouraging the others on,<br/>Run for the kingdom''s sake.<br/>',NULL,7014,7014);
INSERT INTO stanza VALUES('E1319','4','We''re weary not this race to run,<br/>It makes our joy complete;<br/>For this we know, around the bend,<br/>The Lord we''ll surely meet.<br/>',NULL,7015,7015);
INSERT INTO stanza VALUES('E1320','1','We have seen the Lord is coming<br/>For the church for whom He died;<br/>We are in the age of ages,<br/>When the Lord will take His Bride!<br/>',NULL,7016,7016);
INSERT INTO stanza VALUES('E1320','chorus','''Tis a glorious age, the age of the ages,<br/>Now, in this age, Christ will come!<br/>So prepare ye now the church for the marriage,<br/>Christ and the church will be one!<br/>',NULL,7017,7017);
INSERT INTO stanza VALUES('E1320','2','Praise God, in this age we''re living,<br/>Age of God''s recovery.<br/>We are in the local churches,<br/>Where the Bride prepared may be.<br/>',NULL,7018,7018);
INSERT INTO stanza VALUES('E1320','3','Unreservedly we''re giving<br/>All, that He be satisfied;<br/>For the life and for the building<br/>Of His holy, chosen Bride.<br/>',NULL,7019,7019);
INSERT INTO stanza VALUES('E1320','chorus','''Tis a glorious age, the age of the ages,<br/>Now in this age Christ will come!<br/>We''re preparing now the church for the marriage,<br/>Christ and the church will be one!<br/>',NULL,7020,7020);
INSERT INTO stanza VALUES('E1321','1','The grace which God bestows on us<br/>Is just His Son in full;<br/>The rich enjoyment of this Christ<br/>Is plenteous, bountiful.<br/>''Tis far too great to comprehend,<br/>Too wondrous to contain:<br/>How we, once children of despair,<br/>God''s masterpiece became.<br/>',NULL,7021,7021);
INSERT INTO stanza VALUES('E1321','2','The whole creation now beneath<br/>The weight of bondage sore,<br/>In seeing God''s sons manifest<br/>Is freed forevermore.<br/>Th'' eternal purpose of our God<br/>Will be full manifest;<br/>The hope of glory now concealed<br/>Is then to all expressed.<br/>',NULL,7022,7022);
INSERT INTO stanza VALUES('E1321','3','The briars will be myrtle trees,<br/>The thorn will be no more,<br/>And peace will reign where war did rage,<br/>The curse will then be o''er.<br/>''Tis then the trees shall clap their hands,<br/>And all the hills shall sing;<br/>This glorious freedom shall God''s sons<br/>Thus manifested bring.<br/>',NULL,7023,7023);
INSERT INTO stanza VALUES('E1321','4','God''s deepest work of grace goes on<br/>Each day, though hidden, small,<br/>Until that day, when manifest,<br/>It is revealed to all.<br/>By then God''s wrought His finished work:<br/>Himself dispensed to us;<br/>And all creation ''round admires<br/>His product, glorious.<br/>',NULL,7024,7024);
INSERT INTO stanza VALUES('E1321','5','The angels that before our God<br/>In brightest splendor stand,<br/>Will join the universal praise<br/>To Him for all He''s planned.<br/>And for the devil, of His end . . . ?<br/>We''ll praise the Lord for how<br/>Just distant smoke is all that''s left<br/>Of all that troubles now.<br/>',NULL,7025,7025);
INSERT INTO stanza VALUES('E1321','6','So shall we not delight to give<br/>Ourselves in every way,<br/>And let the Lord dispense Himself<br/>Into us more each day;<br/>The grace that we receive each day,<br/>Though hidden oft, and small,<br/>Is God Himself wrought into us,<br/>That day to shine o''er all.<br/>',NULL,7026,7026);
INSERT INTO stanza VALUES('E1322','1','In spirit, in the church we see<br/>The high estate we''re destined for.<br/>It''s higher, vaster, more profound<br/>Than anything we''ve seen before.<br/>',NULL,7027,7027);
INSERT INTO stanza VALUES('E1322','2','It''s not a view in doctrine bare<br/>But an unveiling of the Christ.<br/>He''s marvelous and far beyond<br/>Our mental thought or power to share.<br/>',NULL,7028,7028);
INSERT INTO stanza VALUES('E1322','3','He''s rich, unlimited, profound,<br/>Immeasurable, and marvelous.<br/>Yet ''tis a greater wonder still<br/>He needs heirs of salvation — us.<br/>',NULL,7029,7029);
INSERT INTO stanza VALUES('E1322','4','God has accomplished many things —<br/>He''s planned, created, and brought forth.<br/>The Son is now appointed Heir,<br/>Administrator of God''s worth.<br/>',NULL,7030,7030);
INSERT INTO stanza VALUES('E1322','5','But in th'' economy of God<br/>There is not one, but many sons.<br/>One is the firstborn Son of God<br/>With many other living ones.<br/>',NULL,7031,7031);
INSERT INTO stanza VALUES('E1322','6','Christ will inherit all God''s things,<br/>And we''re heirs of God with Christ.<br/>We''re growing now to be matured;<br/>As heirs we''ll soon be legalized.<br/>',NULL,7032,7032);
INSERT INTO stanza VALUES('E1322','7','We''re joint-heirs with the firstborn Son,<br/>Inheriting the universe.<br/>We''re in this corporation vast —<br/>All partners of Christ and the church.<br/>',NULL,7033,7033);
INSERT INTO stanza VALUES('E1322','8','In spirit, in the church, we see<br/>Our calling of unrivaled worth.<br/>We''re destined, not to go to heaven.<br/>We''re destined to be kings on earth.<br/>',NULL,7034,7034);
INSERT INTO stanza VALUES('E1322','9','We''re paupers, yet we''re glorious kings.<br/>Inheriting the kingdom vast,<br/>The earth, God''s throne, and e''en all things<br/>And all the Father is and has.<br/>',NULL,7035,7035);
INSERT INTO stanza VALUES('E1323','1','The voice of my Beloved,<br/>Behold, He quickly comes;<br/>He leaps upon the mountains,<br/>And o''er the hills He runs.<br/>The signs of His appearing<br/>Are seen on every side;<br/>The Bridegroom soon is coming<br/>To claim His loving Bride.<br/>',NULL,7036,7036);
INSERT INTO stanza VALUES('E1323','2','How real that He is coming —<br/>Come quickly, Lord, again!<br/>We watch for His appearing,<br/>His precious Word amen.<br/>Oh, don''t delay His coming,<br/>Pray without ceasing, pray;<br/>He''s eagerly awaiting<br/>That coming wedding day.<br/>',NULL,7037,7037);
INSERT INTO stanza VALUES('E1323','3','He longs to hear our voices,<br/>He longs to see our face —<br/>Our voices filled with sweetness,<br/>Our countenance with grace.<br/>"Arise, My love, My fair one,"<br/>We long to hear Him say.<br/>The voice of our Beloved —<br/>"Arise and come away!"<br/>',NULL,7038,7038);
INSERT INTO stanza VALUES('E1323','4','The winter rain is over,<br/>The flowers appear on earth;<br/>The rising sun of Jesus<br/>Fills all our hearts with mirth.<br/>It is the time of singing,<br/>The turtle dove is heard;<br/>For our Beloved''s coming<br/>The sweetest chords are stirred.<br/>',NULL,7039,7039);
INSERT INTO stanza VALUES('E1323','5','Oh, let us take the foxes<br/>That spoil the blooming vine;<br/>Our vineyards are in blossom,<br/>And all, Beloved, is Thine.<br/>The day is quickly dawning,<br/>The shadows flee away;<br/>Upon the mount of spices<br/>Our Lord may come today.<br/>',NULL,7040,7040);
INSERT INTO stanza VALUES('E1324','1','Our God is a God of purpose,<br/>What He plans, He will fulfill!<br/>Genesis to Revelation<br/>Shows His full and glorious will.<br/>What He''s after is a building.<br/>In creation He began<br/>With a simple garden planted —<br/>This, the setting for His plan.<br/>',NULL,7041,7041);
INSERT INTO stanza VALUES('E1324','2','Man was made, the first step God took<br/>To achieve His final goal,<br/>As a vessel, a container,<br/>Three parts — body, spirit, soul.<br/>God, of dust, a body formed him,<br/>Breath of life into him breathed —<br/>This part is man''s human spirit<br/>By which God may be received.<br/>',NULL,7042,7042);
INSERT INTO stanza VALUES('E1324','3','In the garden God had planted<br/>Every tree He made to grow,<br/>Good for food, to sight most pleasing,<br/>And the tree of life also!<br/>Second, then, in God''s intention<br/>Was that man should freely eat<br/>Of the life-tree in the center<br/>To obtain His life complete.<br/>',NULL,7043,7043);
INSERT INTO stanza VALUES('E1324','4','Third, we see a river flowing,<br/>Out of Eden coming forth,<br/>With its flow in four directions —<br/>East and west and south and north.<br/>As on Christ our life we''re feeding,<br/>Living water in us flows.<br/>Hallelujah for this river<br/>And the watering it bestows!<br/>',NULL,7044,7044);
INSERT INTO stanza VALUES('E1324','5','In the flowing of the river<br/>Gold, pearl, onyx stone we see;<br/>Three materials, raw yet precious,<br/>For God''s building meant to be.<br/>Look, these elements are shining!<br/>How can we, then, shine as they?<br/>Simply by the Lord, the Spirit,<br/>Us transforming every day.<br/>',NULL,7045,7045);
INSERT INTO stanza VALUES('E1324','6','God the Father (in this fourth step),<br/>Source of life, is gold divine;<br/>Christ the Son was wounded by us<br/>To produce the pearl so fine.<br/>God the Spirit brings the stones forth —<br/>Transformation of the clay.<br/>By the flowing of the Spirit<br/>Changed we''ll be from day to day.<br/>',NULL,7046,7046);
INSERT INTO stanza VALUES('E1324','7','Insufficient are materials<br/>Precious though they be and best;<br/>These must be built up together<br/>That God''s house they may express.<br/>Fifth step: We ourselves hand over<br/>To the building that we be<br/>Built into God''s house, His dwelling,<br/>One in each locality.<br/>',NULL,7047,7047);
INSERT INTO stanza VALUES('E1324','8','Finally, in Revelation,<br/>Is the picture of Christ''s Bride —<br/>Consummation of God''s purpose;<br/>He is fully satisfied.<br/>New Jerusalem, a city,<br/>Is the Bridegroom''s counterpart —<br/>So the church built up together<br/>Forms the Bride for Christ''s own heart.<br/>',NULL,7048,7048);
INSERT INTO stanza VALUES('E1324','9','How can we, as those who truly<br/>Long to see God reach His goal,<br/>Be united and related?<br/>By denial of our soul!<br/>As we contact Christ in spirit,<br/>Feed on Him as life to us,<br/>Then His life will flow, transform us<br/>To His Bride, all glorious!<br/>',NULL,7049,7049);
INSERT INTO stanza VALUES('E1325','1','God eternal has a purpose,<br/>Formed in His eternal past,<br/>Spreading to eternal future;<br/>''Twixt these ends all time is cast.<br/>For with time there is the process,<br/>Time for His accomplishment;<br/>And in time we''re merely travelers —<br/>For eternity we''re meant.<br/>',NULL,7050,7050);
INSERT INTO stanza VALUES('E1325','2','God would have a group of people<br/>Built together in His plan,<br/>Blended, knit, coordinated<br/>As His vessel — one new man.<br/>God would come into this vessel<br/>With His nature, life and ways,<br/>Mingling Spirit with our spirits<br/>For His joy and to His praise.<br/>',NULL,7051,7051);
INSERT INTO stanza VALUES('E1325','3','God has worked in three directions<br/>For His plan so marvelous:<br/>As the Father, Son, and Spirit<br/>To dispense Himself to us!<br/>All the creation gives the setting —<br/>Heav''n and earth are for this plan;<br/>''Tis for this God made a body,<br/>Soul and spirit — three-part man.<br/>',NULL,7052,7052);
INSERT INTO stanza VALUES('E1325','4','As the center, as the kernel,<br/>Of God''s plan our spirit is;<br/>Calling on the name of Jesus<br/>Makes our spirit one with His.<br/>From the center to circumference<br/>God would saturate each part;<br/>Feeling, mind, and will renewing,<br/>Making home in all our heart.<br/>',NULL,7053,7053);
INSERT INTO stanza VALUES('E1325','5','Thus in life we''re built together,<br/>Then in love we''re knit as one;<br/>God is now His plan fulfilling,<br/>Finishing what He''s begun.<br/>Lord, increase Thyself within us<br/>That we might be built by Thee<br/>Into that great corporate vessel<br/>Filled with God exclusively.<br/>',NULL,7054,7054);
INSERT INTO stanza VALUES('E1325','6','As the product, the fulfillment,<br/>Will the church in glory stand,<br/>Consummation of the purpose<br/>In eternal ages planned.<br/>God will have His corporate vessel,<br/>All His glory to contain;<br/>Lord, we''re wholly for Thy purpose<br/>All Thy goal in us attain.<br/>',NULL,7055,7055);
INSERT INTO stanza VALUES('E1326','1','What is living all about,<br/>Where''s the answer? Let''s find out!<br/>',NULL,7056,7056);
INSERT INTO stanza VALUES('E1326','2','Call, "Lord Jesus!" Taste and see!<br/>Christ becomes reality,<br/>Life He gives abundantly<br/>As a river flowing free.<br/>With a new life we begin,<br/>Joy is springing from within,<br/>Love — He fills us to the brim!<br/>And it''s all because of Him! (Hallelujah)<br/>',NULL,7057,7057);
INSERT INTO stanza VALUES('E1327','1','Once I thirsted for a fountain,<br/>Something deep that would satisfy,<br/>But the fountain that I''d drink from,<br/>Left me searching and still so dry.<br/>Then one day I found Him,<br/>He satisfied my thirst,<br/>Became in me a deeper source<br/>Whence living waters burst.<br/>Now I drink Him!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,7058,7058);
INSERT INTO stanza VALUES('E1327','2','After tasting such a fountain,<br/>Longed my heart for a place of springs;<br/>Caught a vision on a mountain,<br/>In Jerusalem''s a gathering.<br/>Then one day He found me,<br/>He brought me to the church,<br/>Pleasures here abound fore''er<br/>I''ve given up my search.<br/>Hallelujah!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,7059,7059);
INSERT INTO stanza VALUES('E1327','3','Empty wanderer drop the striving —<br/>Isn''t worth all the troublin'';<br/>Open up your heart believing,<br/>Call "Lord Jesus" and He''ll come in!<br/>Then today you''ll find Him,<br/>And calling on His name,<br/>You''re joined to Him, you''re one with Him —<br/>You''ll never be the same.<br/>You won''t want to!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,7060,7060);
INSERT INTO stanza VALUES('E1328','1','My wandering days grew increasingly empty<br/>As I searched for the way,<br/>Just to fill this gap inside me —<br/>Found my seeking vain.<br/>',NULL,7061,7061);
INSERT INTO stanza VALUES('E1328','2','Though all this dark earth would convince me life''s worthwhile,<br/>Inside all my mirth<br/>Was a cry for something real.<br/>Don''t you lie to me, world!<br/>',NULL,7062,7062);
INSERT INTO stanza VALUES('E1328','3','For my heart tells me different<br/>When I hear of contentment<br/>Deep within a lack knew better<br/>Why not be honest, world!<br/>',NULL,7063,7063);
INSERT INTO stanza VALUES('E1328','4','A flood of strong doubt as I heard the old story<br/>Of a man they called Lord;<br/>Yet my heart ne''er ceased to wonder,<br/>Is He really Lord?<br/>',NULL,7064,7064);
INSERT INTO stanza VALUES('E1328','5','A search in His Word found my hardened heart softened,<br/>And earth''s vanities faded.<br/>In the brightness of His presence<br/>Jesus came into me.<br/>',NULL,7065,7065);
INSERT INTO stanza VALUES('E1328','6','Now we''re always together<br/>Growing into God''s fullness.<br/>O Lord Jesus, how I love You!<br/>You brought life into me.<br/>',NULL,7066,7066);
INSERT INTO stanza VALUES('E1329','1','The wedding feast, the peak of man''s enjoyment<br/>Was full of pleasure till the wine ran dry.<br/>The human life, like wine, is soon exhausted,<br/>Till Jesus comes, divine life to supply.<br/>',NULL,7067,7067);
INSERT INTO stanza VALUES('E1329','chorus','When Jesus comes, new wine is made from water,<br/>When Jesus comes, the darkness turns to light.<br/>He touches death — it''s turned to life eternal,<br/>Weakness to strength and blindness into sight.<br/>',NULL,7068,7068);
INSERT INTO stanza VALUES('E1329','2','One night a moral righteous man, a ruler<br/>To Jesus came, more teaching to pursue;<br/>But teachings ne''er could change the fallen nature,<br/>So Jesus said, "You must be born anew."<br/>',NULL,7069,7069);
INSERT INTO stanza VALUES('E1329','3','"I have no husband," sighed the thirsty sinner.<br/>Indeed her many husbands left her dry.<br/>Daily she came to draw the failing water<br/>Till Jesus came, her thirst to satisfy.<br/>',NULL,7070,7070);
INSERT INTO stanza VALUES('E1329','4','A man among the multitude lay helpless,<br/>So weak while waiting till the water stirred.<br/>Religion of the law could never heal him;<br/>Then Jesus came and spoke the living word.<br/>',NULL,7071,7071);
INSERT INTO stanza VALUES('E1329','5','Within the tomb, four days and nights he lay there,<br/>Death''s grip had come; they ''round the grave did weep.<br/>Silent he lay, all bound and wrapped in grave clothes;<br/>Then Jesus came, and woke him from his sleep.<br/>',NULL,7072,7072);
INSERT INTO stanza VALUES('E1329','6','And still today, this Jesus is so living,<br/>Able to save from death in any form.<br/>Now open up your heart and call upon Him;<br/>To you He''ll come, in spirit you''ll be born<br/>',NULL,7073,7073);
INSERT INTO stanza VALUES('E1330','1','"All things are ready," come to the feast!<br/>Come for the table now is spread;<br/>Ye famishing, ye weary, come,<br/>And thou shalt be richly fed.<br/>',NULL,7074,7074);
INSERT INTO stanza VALUES('E1330','chorus','Hear the invitation,<br/>Come, whosoever will;<br/>Praise God for full salvation<br/>For whosoever will.<br/>',NULL,7075,7075);
INSERT INTO stanza VALUES('E1330','2','"All things are ready," come to the feast!<br/>Come, for the door is open wide;<br/>A place of honor is reserved<br/>For you at the Master''s side.<br/>',NULL,7076,7076);
INSERT INTO stanza VALUES('E1330','3','"All things are ready," come to the feast!<br/>Come, while He waits to welcome thee;<br/>Delay not while this day is thine,<br/>Tomorrow may never be.<br/>',NULL,7077,7077);
INSERT INTO stanza VALUES('E1330','4','"All things are ready," come to the feast!<br/>Leave every care and worldly strife;<br/>Come, feast upon the Christ of God<br/>And drink everlasting life.<br/>',NULL,7078,7078);
INSERT INTO stanza VALUES('E1331','1','Just taste and see that the Lord is good;<br/>Just taste and see that the Lord is good.<br/>He''s good for you, as He is for me;<br/>So whatever you do, just taste and see.<br/>',NULL,7079,7079);
INSERT INTO stanza VALUES('E1331','2','Just call O Lord — He''ll change your life;<br/>Just call O Lord — He''ll change your life.<br/>Amazing grace He will afford<br/>If in every place you call O Lord.<br/>',NULL,7080,7080);
INSERT INTO stanza VALUES('E1331','3','You''ll feel real love coming into your heart;<br/>You''ll feel real love coming into your heart.<br/>You''ll sense a flow from God above;<br/>And you will know you''ve found real love.<br/>',NULL,7081,7081);
INSERT INTO stanza VALUES('E1331','4','So praise the Lord for His life in you;<br/>Yes, praise the Lord for His life in you.<br/>Something of Christ He has outpoured<br/>Into your life; so praise the Lord!<br/>',NULL,7082,7082);
INSERT INTO stanza VALUES('E1332','1','Do you know that you were chosen<br/>Long before the world began;<br/>That by God you were selected<br/>And appointed for His plan?<br/>Something in your inmost being<br/>Tells you this is surely true;<br/>That''s why you are in this meeting,<br/>And you feel the way you do.<br/>',NULL,7083,7083);
INSERT INTO stanza VALUES('E1332','2','All the sins you''ve e''er committed,<br/>Everything you''ve ever done,<br/>All by God has been forgiven,<br/>Taken care of by God''s Son.<br/>Struggle not, no; just believe this,<br/>For His word assures it''s true;<br/>All you need to do is thank Him<br/>For all that He''s done for you.<br/>',NULL,7084,7084);
INSERT INTO stanza VALUES('E1332','3','Did you know that all the Bible<br/>Is a will, a testament?<br/>Everything that Christ accomplished<br/>Is for all God''s children meant.<br/>As His child you are included,<br/>For His word stands fast and true;<br/>So by faith you now inherit<br/>All that He has done for you.<br/>',NULL,7085,7085);
INSERT INTO stanza VALUES('E1332','4','Did you know God has a family?<br/>Yes, He does, in fact, it''s us.<br/>That''s why we are here enjoying<br/>All He is, so marvelous.<br/>He''s our God and we''re His people,<br/>Day by day we love Him more;<br/>We''re so happy and so thankful,<br/>We just praise Him o''er and o''er.<br/>',NULL,7086,7086);
INSERT INTO stanza VALUES('E1332','5','All we know is that we love Him,<br/>We''re so glad for what He''s done;<br/>We are brought to Him, and we all<br/>Know the joy of being one.<br/>We''re so glad that we''re included,<br/>What a fellowship have we!<br/>So we''d like to welcome you, friend,<br/>Into God''s own family.<br/>',NULL,7087,7087);
INSERT INTO stanza VALUES('E1333','1','What a happy day<br/>When I no more could turn away,<br/>When Jesus took my heart from the black of night<br/>Into the kingdom of His light.<br/>',NULL,7088,7088);
INSERT INTO stanza VALUES('E1333','2','Now my life''s begun,<br/>The "really life" that''s in the Son.<br/>No more am I enthralled by earth''s empty dreams;<br/>Deep in me flows a living stream.<br/>',NULL,7089,7089);
INSERT INTO stanza VALUES('E1333','3','As I turn to Him<br/>He fills me with His life within.<br/>His life becomes my life in reality;<br/>Oh, hallelujah, He''s in me!<br/>',NULL,7090,7090);
INSERT INTO stanza VALUES('E1333','4','I just love You, Lord,<br/>With other loves, You break the cord.<br/>You''ll be my life for all eternity;<br/>You are the only One for me.<br/>',NULL,7091,7091);
INSERT INTO stanza VALUES('E1334','1','Thou hast turned my mourning into dancing for me;<br/>Thou hast put off my sackcloth;<br/>Thou hast turned my mourning into dancing for me;<br/>And girded me with gladness;<br/>To the end my glory may sing praise unto Thee,<br/>And not be silent.<br/>O Lord my God, I will give thanks unto Thee forever.<br/>',NULL,7092,7092);
INSERT INTO stanza VALUES('E1335','1','Great is the Lord, and greatly to be praised,<br/>In the city of our God,<br/>In the mountain of His holiness.<br/>Beautiful in elevation, the joy of the whole earth,<br/>Is Mount Zion, on the sides of the north,<br/>The city of the great King.<br/>Is Mount Zion, on the sides of the north,<br/>The city of the great King.<br/>',NULL,7093,7093);
INSERT INTO stanza VALUES('E1336','1','What shall I give unto the Lord<br/>For all, for all, for all He''s done for me?<br/>I''ll take the cup of salvation,<br/>And call, and call, and call upon the name of the Lord.<br/>',NULL,7094,7094);
INSERT INTO stanza VALUES('E1337','1','When the Lord turned again the captivity of Zion,<br/>We were like them that dream,<br/>We were like them that dream.<br/>',NULL,7095,7095);
INSERT INTO stanza VALUES('E1337','2','Then was our mouth filled with laughter,<br/>And our tongue with singing:<br/>Then said they among the nations,<br/>The Lord hath done great things,<br/>The Lord hath done great things for them.<br/>',NULL,7096,7096);
INSERT INTO stanza VALUES('E1337','chorus','The Lord hath done great things for us;<br/>Whereof we are glad.<br/>The Lord hath done great things for us;<br/>Whereof we are glad.<br/>',NULL,7097,7097);
INSERT INTO stanza VALUES('E1337','3','Turn again our captivity, O Lord, as the streams,<br/>As the streams in the south,<br/>As the streams in the south.<br/>',NULL,7098,7098);
INSERT INTO stanza VALUES('E1337','4','They that sow in tears shall reap in joy,<br/>They that sow in tears shall reap in joy.<br/>',NULL,7099,7099);
INSERT INTO stanza VALUES('E1337','5','He that goeth forth and weepeth,<br/>Bearing precious seed, shall doubtless,<br/>Come again with rejoicing,<br/>Come again with rejoicing,<br/>Bringing his sheaves with him.<br/>',NULL,7100,7100);
INSERT INTO stanza VALUES('E1337','6','When the Lord turned again the captivity of Zion,<br/>We were like them that dream,<br/>We were like them that dream.<br/>',NULL,7101,7101);
INSERT INTO stanza VALUES('E1338','1','This is My rest forever;<br/>Here will I dwell,<br/>For the Lord hath chosen Zion,<br/>He hath desired it for His habitation.<br/>',NULL,7102,7102);
INSERT INTO stanza VALUES('E1338','2','He will abundantly bless her provision:<br/>He will satisfy her poor with bread.<br/>He will clothe her priests with salvation,<br/>And her saints shall shout aloud for joy.<br/>',NULL,7103,7103);
INSERT INTO stanza VALUES('E1339','1','Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>',NULL,7104,7104);
INSERT INTO stanza VALUES('E1339','-','It is like the precious ointment upon the head,<br/>That ran down upon the beard,<br/>Even Aaron''s beard:<br/>That went down to the skirts of his garments.<br/>',NULL,7105,7105);
INSERT INTO stanza VALUES('E1339','2','Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>',NULL,7106,7106);
INSERT INTO stanza VALUES('E1339','3','As the dew of Hermon,<br/>And as the dew that descended<br/>Upon the mountains of Zion:<br/>For there the Lord commanded the blessing,<br/>Even life for evermore.<br/>',NULL,7107,7107);
INSERT INTO stanza VALUES('E1340','1','Therefore with joy shall ye draw water<br/>Out of the wells of salvation.<br/>And in that day shall ye say,<br/>Praise the Lord.<br/>',NULL,7108,7108);
INSERT INTO stanza VALUES('E1340','2','Therefore with joy shall ye draw water<br/>Out of the wells of salvation.<br/>And in that day shall ye say,<br/>Praise the Lord.<br/>',NULL,7109,7109);
INSERT INTO stanza VALUES('E1340','3','Call upon His name, declare His doings<br/>among the people,<br/>Make mention that His name is exalted.<br/>Cry out and shout, thou inhabitant of Zion:<br/>For great is the Holy One of Israel in the<br/>midst of thee.<br/>',NULL,7110,7110);
INSERT INTO stanza VALUES('E1341','1','Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>',NULL,7111,7111);
INSERT INTO stanza VALUES('E1341','2','They shall obtain gladness and joy;<br/>And sorrow and mourning shall flee away.<br/>(Repeat the first three lines)<br/>',NULL,7112,7112);
INSERT INTO stanza VALUES('E1342','1','Therefore, they shall come and sing in the height of Zion,<br/>And shall flow together to the goodness of the Lord,<br/>For wheat, and for wine, and for oil, and for the young,<br/>for the young of the flock and of the herd:<br/>And their soul shall be as a watered garden;<br/>And they shall not sorrow any more at all.<br/>',NULL,7113,7113);
INSERT INTO stanza VALUES('E1343','1','A new commandment<br/>I give unto you<br/>That you love one another<br/>As I have loved you,<br/>That you love one another<br/>As I have loved you.<br/>',NULL,7114,7114);
INSERT INTO stanza VALUES('E1343','2','By this shall all men<br/>Know you are My disciples<br/>If you have love one to another.<br/>',NULL,7115,7115);
INSERT INTO stanza VALUES('E1343','3','By this shall all men<br/>Know you are My disciples<br/>If you have love one to another.<br/>',NULL,7116,7116);
INSERT INTO stanza VALUES('E1344','1','Oh, the depth of the riches and the<br/>wisdom and knowledge of God;<br/>How unsearchable are His judgments;<br/>How untraceable are His paths.<br/>For who has known the mind of the Lord,<br/>Or who has been His counselor?<br/>Or who has first given to Him,<br/>And it will be repaid to Him?<br/>Because out of Him and through Him<br/>And to Him are all things.<br/>To Him be the glory forever. Amen.<br/>',NULL,7117,7117);
INSERT INTO stanza VALUES('E1345','1','Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>So turn your heart to the Lord all the day,<br/>And the veil shall be taken away.<br/>Now the Lord is that Spirit,<br/>And where the Spirit of the Lord is,<br/>There is liberty — such liberty!<br/>Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>',NULL,7118,7118);
INSERT INTO stanza VALUES('E1346','1','Now unto the King eternal, immortal, invisible,<br/>The only wise God, the only wise God,<br/>Be honor and glory forever and ever. Amen.<br/>Amen.<br/>Be honor and glory forever and ever.<br/>Amen.<br/>',NULL,7119,7119);
INSERT INTO stanza VALUES('E1347','1','Now is come salvation and strength<br/>And the kingdom of our God<br/>And the authority of His Christ:<br/>For the accuser of our brethren is cast down<br/>Which accused them before our God day and night.<br/>',NULL,7120,7120);
INSERT INTO stanza VALUES('E1347','2','And they overcame him by the blood of the Lamb,<br/>And by the word of their testimony<br/>And they loved not their soul lives unto death.<br/>Therefore rejoice, rejoice, rejoice!<br/>',NULL,7121,7121);
INSERT INTO stanza VALUES('E1348','1','Behold, the tabernacle of God is with men,<br/>And He will dwell with them, and they shall be His people,<br/>And God Himself shall be with them and be their God.<br/>Behold, the tabernacle of God is with men,<br/>And God shall wipe away all tears from their eyes;<br/>And there shall be no more death, neither sorrow,<br/>nor crying, neither shall there be any more pain,<br/>For the former things are passed away.<br/>Behold, I make all things new.<br/>',NULL,7122,7122);
INSERT INTO stanza VALUES('C1','1','但願榮耀歸於聖父，<br/>並聖子基督，<br/>且願榮耀歸於聖靈<br/>到永古。<br/>',NULL,7123,7123);
INSERT INTO stanza VALUES('C1','2','當我觀賞廣大創造－神智所制訂，<br/>我靈受感，立獻敬拜，<br/>並肅靜。<br/>',NULL,7124,7124);
INSERT INTO stanza VALUES('C1','3','但是我神，你是深願：<br/>能得有眾子，<br/>今在子裡對你讚美，<br/>並賞識。<br/>',NULL,7125,7125);
INSERT INTO stanza VALUES('C1','4','你話已向我們啟示，<br/>你情愛祕密，<br/>為要我們領略接受，<br/>以愛你。<br/>',NULL,7126,7126);
INSERT INTO stanza VALUES('C1','5','因此藉著基督救贖，<br/>既將敵全克，<br/>在新造裡你就帶來<br/>敬拜者。<br/>',NULL,7127,7127);
INSERT INTO stanza VALUES('C1','6','但願榮耀歸於聖父，<br/>並聖子基督，<br/>且願榮耀歸於聖靈<br/>到永古。<br/>',NULL,7128,7128);
INSERT INTO stanza VALUES('C2','1','榮耀、榮耀、榮耀、<br/>讚美、崇敬、愛戴！<br/>聽哪，頌讚聲浪，<br/>從永世一直澎湃！<br/>聖父、聖子、聖靈－神，<br/>已啟示出來，<br/>人人都當向祂俯伏敬拜！<br/>',NULL,7129,7129);
INSERT INTO stanza VALUES('C2','2','聖父乃是源頭，<br/>榮耀、無限、豐厚；<br/>聖子藉著權能，<br/>以命令托住萬有；<br/>聖靈充滿全景，<br/>榮耀、無往不透，<br/>哦，這榮耀豐滿<br/>配得歌謳！<br/>',NULL,7130,7130);
INSERT INTO stanza VALUES('C2','3','尊高、偉大真神，<br/>萬有有福元首，<br/>我們今以聖潔<br/>作裝飾向你拜叩！<br/>威嚴、尊大、權能、<br/>榮耀、高超、優秀，<br/>全屬你這萬有永遠源頭！<br/>',NULL,7131,7131);
INSERT INTO stanza VALUES('C3','1','榮耀、榮耀歸於聖父，<br/>榮耀、榮耀歸聖子，<br/>榮耀、榮耀歸於聖靈，<br/>榮耀歸神永無止。<br/>',NULL,7132,7132);
INSERT INTO stanza VALUES('C3','chorus','高聲讚美！<br/>高聲讚美！<br/>高聲讚美三一神！<br/>榮耀歸祂！<br/>榮耀歸祂！<br/>榮耀、榮耀，<br/>神來施救恩。<br/>',NULL,7133,7133);
INSERT INTO stanza VALUES('C3','2','讚美聖父定意、計畫，<br/>讚美聖子來完成，<br/>讚美聖靈運行、實施，<br/>讚美三一作生命。<br/>',NULL,7134,7134);
INSERT INTO stanza VALUES('C3','3','榮耀、榮耀歸於聖父，<br/>榮耀、榮耀歸聖子，<br/>榮耀、榮耀歸於聖靈，<br/>榮耀歸神永無止。<br/>',NULL,7135,7135);
INSERT INTO stanza VALUES('C4','1','聖哉、聖哉、聖哉，<br/>全能的主神！<br/>我們向你揚聲，<br/>頌讚直到永遠；<br/>聖哉、聖哉、聖哉，<br/>全能而又慈憐！<br/>一神別三位，<br/>三位是一身！<br/>',NULL,7136,7136);
INSERT INTO stanza VALUES('C4','2','聖哉、聖哉、聖哉，<br/>眾聖都俯伏；<br/>天上長老在你<br/>座前金冠拋開；<br/>基路伯、撒拉弗，<br/>也都一同敬拜<br/>你昔在、今在、<br/>永遠常在主。<br/>',NULL,7137,7137);
INSERT INTO stanza VALUES('C4','3','聖哉、聖哉、聖哉，<br/>你藏身黑暗，<br/>罪人也都不能<br/>看見你的榮光，<br/>惟你乃是至聖，<br/>無人與你相像，<br/>愛心並純潔、<br/>能力都完全。<br/>',NULL,7138,7138);
INSERT INTO stanza VALUES('C4','4','聖哉、聖哉、聖哉，<br/>全能的主神！<br/>天、地、滄海之間，<br/>造物無不頌讚：<br/>聖哉、聖哉、聖哉，<br/>全能而又慈憐！<br/>一神別三位，<br/>三位是一身！<br/>',NULL,7139,7139);
INSERT INTO stanza VALUES('C5','1','讚美父乃祝福之源，<br/>讚美子將救贖成全，<br/>讚美靈來實施、運行，<br/>讚美聖父、聖子、聖靈！<br/>',NULL,7140,7140);
INSERT INTO stanza VALUES('C5','2','讚美父是永活源頭，<br/>讚美子作生命湧流，<br/>讚美靈已流入我心，<br/>讚美三一神是我分。<br/>',NULL,7141,7141);
INSERT INTO stanza VALUES('C6','1','神，你是愛，你也是光，<br/>且在子裡作生命；<br/>愛已顯明，光已照亮，<br/>我們因此而得生。<br/>',NULL,7142,7142);
INSERT INTO stanza VALUES('C6','chorus','你是愛！你是光！<br/>且在子裡作生命；<br/>愛已顯明，光已照亮，<br/>我們因此而得生。<br/>',NULL,7143,7143);
INSERT INTO stanza VALUES('C6','2','愛重所是，光重所為，<br/>愛是藉光而釋放；<br/>光顯於外，愛在於內，<br/>光是帶愛而照亮。<br/>',NULL,7144,7144);
INSERT INTO stanza VALUES('C6','3','愛的顯明就是恩典，<br/>光的照亮是真理；<br/>愛叫我們享你肥甘，<br/>光叫我們認識你。<br/>',NULL,7145,7145);
INSERT INTO stanza VALUES('C6','4','愛叫你在子裡來死，<br/>使我藉祂得生命；<br/>光叫我能有所認識，<br/>使我藉血得潔淨。<br/>',NULL,7146,7146);
INSERT INTO stanza VALUES('C6','5','愛叫我們得著生命，<br/>有分於你的交通；<br/>光叫我們得著潔淨，<br/>能以活在交通中。<br/>',NULL,7147,7147);
INSERT INTO stanza VALUES('C6','6','光的照亮、血的洗淨，<br/>帶來膏油的塗抹，<br/>你的成分、愛的生命，<br/>在我裡面就加多。<br/>',NULL,7148,7148);
INSERT INTO stanza VALUES('C6','7','愛叫我們成為兒女，<br/>時常稱你作阿爸；<br/>光叫我們不潔全去，<br/>直到見主得像祂。<br/>',NULL,7149,7149);
INSERT INTO stanza VALUES('C6','chorus','何榮耀！何福氣！<br/>愛已顯明，光已亮！<br/>感謝不盡，讚美不已！<br/>父，你是愛又是光！<br/>',NULL,7150,7150);
INSERT INTO stanza VALUES('C7','1','哦神，你是永遠父，<br/>也是自有永有主！<br/>你比古者還要古，<br/>你比初者還要初！<br/>',NULL,7151,7151);
INSERT INTO stanza VALUES('C7','2','你是永遠到永遠，<br/>超過時間和空間！<br/>永永遠遠的完滿，<br/>無始無終的無限！<br/>',NULL,7152,7152);
INSERT INTO stanza VALUES('C7','3','你是萬有的根源，<br/>早過大地並諸天！<br/>你比先者還要先，<br/>你比前者還要前！<br/>',NULL,7153,7153);
INSERT INTO stanza VALUES('C7','4','你是生命永存留，<br/>世世代代無盡休！<br/>你比久者還要久，<br/>你比後者還要後！<br/>',NULL,7154,7154);
INSERT INTO stanza VALUES('C7','5','首先，你是阿拉法，<br/>末後，你是俄梅嘎！<br/>自始至終無所差，<br/>完全豐滿無可加！<br/>',NULL,7155,7155);
INSERT INTO stanza VALUES('C7','6','我們讚美你永遠，<br/>我們稱頌你無限！<br/>讚美你是何豐滿，<br/>稱頌你是何完全！<br/>',NULL,7156,7156);
INSERT INTO stanza VALUES('C8','1','父阿，你是萬靈之靈，<br/>神聖遠超萬眾；<br/>我們敬拜以靈、在靈，<br/>同靈向你稱頌。<br/>',NULL,7157,7157);
INSERT INTO stanza VALUES('C8','2','為要我們以靈拜靈，<br/>你為我們造靈；<br/>且將我們靈裡重生，<br/>為叫靈靈響應。<br/>',NULL,7158,7158);
INSERT INTO stanza VALUES('C8','3','父來作子，子又作靈，<br/>為要進入我靈；<br/>父、子、聖靈來作生命，<br/>這是何等恩情。<br/>',NULL,7159,7159);
INSERT INTO stanza VALUES('C8','4','你在子裡，子是你話，<br/>這話也就是靈；<br/>靈進我靈，將我感化，<br/>也就作我生命。<br/>',NULL,7160,7160);
INSERT INTO stanza VALUES('C8','5','你靈現今住在我靈，<br/>你我聯成一靈；<br/>你靈我靈同作見證，<br/>我是由你而生。<br/>',NULL,7161,7161);
INSERT INTO stanza VALUES('C8','6','你靈凡事將我引領，<br/>使我隨靈而行，<br/>使我得享平安、生命，<br/>使我全人屬靈。<br/>',NULL,7162,7162);
INSERT INTO stanza VALUES('C8','7','靈裡禱告、靈裡敬拜、<br/>靈裡將你瞻仰，<br/>直到靈能完全出來，<br/>滿有榮耀形狀。<br/>',NULL,7163,7163);
INSERT INTO stanza VALUES('C8','8','父阿，我們讚美你靈，<br/>讚美你就是靈！<br/>我們敬拜以靈、在靈，<br/>同靈稱頌你名！<br/>',NULL,7164,7164);
INSERT INTO stanza VALUES('C9','1','哦神，你是生命源頭，<br/>神聖、甘美、豐滿！<br/>你如活水向外湧流，<br/>一直流到永遠！<br/>',NULL,7165,7165);
INSERT INTO stanza VALUES('C9','2','你在子裡因愛流出，<br/>流到人類中間；<br/>且成那靈帶愛流入，<br/>流進我們裡面。<br/>',NULL,7166,7166);
INSERT INTO stanza VALUES('C9','3','我們雖都偏行己路，<br/>滿了邪惡罪愆，<br/>你在子裡仍來救贖，<br/>賜以生命恩典。<br/>',NULL,7167,7167);
INSERT INTO stanza VALUES('C9','4','我們甚且將你欺侮，<br/>時常抗拒聖靈，<br/>但你這靈仍然眷顧，<br/>來作我們生命。<br/>',NULL,7168,7168);
INSERT INTO stanza VALUES('C9','5','你在子裡、藉成那靈，<br/>已與我們調和；<br/>你的成分藉祂運行，<br/>還要塗抹加多。<br/>',NULL,7169,7169);
INSERT INTO stanza VALUES('C9','6','你的慈愛、子的恩典、<br/>加上靈的交通，<br/>使我得享神的豐滿，<br/>直到永世無終！<br/>',NULL,7170,7170);
INSERT INTO stanza VALUES('C9','7','三一之神，<br/>父、子、聖靈，<br/>如此厚待我們，<br/>配得我們和聲響應，<br/>讚美你愛不盡！<br/>',NULL,7171,7171);
INSERT INTO stanza VALUES('C10','1','哦神，你是何超越，<br/>你是何等聖別！<br/>無何能與你並列，<br/>你的一切超絕！<br/>你是宇宙的至聖，<br/>你是聖中之聖！<br/>你的永能和神性，<br/>遠超萬有、眾生！<br/>',NULL,7172,7172);
INSERT INTO stanza VALUES('C10','2','你是聖而有分別，<br/>非僅無罪聖潔；<br/>非僅絲毫無殘缺，<br/>且與完全有別。<br/>無何能與你比擬，<br/>無何能與你攀；<br/>無論以何代替你，<br/>都是對你褻慢！<br/>',NULL,7173,7173);
INSERT INTO stanza VALUES('C10','3','你在優者之外優，<br/>你與優者有別；<br/>你在秀者之外秀，<br/>秀者與你難列。<br/>你與善者也有別，<br/>你善乃是超絕；<br/>美者與你也難列，<br/>你美也是超越。<br/>',NULL,7174,7174);
INSERT INTO stanza VALUES('C10','4','聖別乃是你特性，<br/>你已賜給我們；<br/>你那分別的性情，<br/>我們已經有分。<br/>我們與你同超越，<br/>因已與你同性；<br/>我們追隨你聖別，<br/>就得分別為聖。<br/>',NULL,7175,7175);
INSERT INTO stanza VALUES('C10','5','我們讚美你超越，<br/>讚美你的聖別！<br/>無何能與你並列，<br/>你的一切超絕！<br/>我們讚美你特性，<br/>已經賜給我們；<br/>你那分別的性情，<br/>我們已經有分。<br/>',NULL,7176,7176);
INSERT INTO stanza VALUES('C11','1','父神，你如青翠松樹，<br/>永遠常新不衰！<br/>你是永活長存的主，<br/>直到永遠不敗！<br/>',NULL,7177,7177);
INSERT INTO stanza VALUES('C11','chorus','哦父，你是常新的神，<br/>永遠不知陳舊！<br/>千萬億載仍是鮮新！<br/>儘管年日悠久。<br/>',NULL,7178,7178);
INSERT INTO stanza VALUES('C11','2','父，你是神<br/>也就是『新，』<br/>無你就是陳舊；<br/>有你，雖然代遠年湮，<br/>仍是常新不朽。<br/>',NULL,7179,7179);
INSERT INTO stanza VALUES('C11','3','你向我們所賜之福，<br/>都是新而不舊；<br/>約是新約、路是新路，<br/>都要永遠存留。<br/>',NULL,7180,7180);
INSERT INTO stanza VALUES('C11','4','我們乃是你的新造，<br/>新人、新心、新靈；<br/>日日更新，永不衰老，<br/>滿有新樣、新生。<br/>',NULL,7181,7181);
INSERT INTO stanza VALUES('C11','5','最終新天、新地、新城，<br/>一切全都更新；<br/>月月都有新果供應，<br/>永遠不再變陳。<br/>',NULL,7182,7182);
INSERT INTO stanza VALUES('C11','6','父神，你是常新不舊，<br/>我們讚美不休！<br/>永遠讚美、永遠歌謳：<br/>你是常新不舊！<br/>',NULL,7183,7183);
INSERT INTO stanza VALUES('C12','1','當我觀賞，<br/>父，你廣大的創造，<br/>天空、地面、<br/>萬有無數無邊，<br/>形形色色，<br/>壯麗、奇觀又微妙，<br/>大大小小說出你的無限；<br/>',NULL,7184,7184);
INSERT INTO stanza VALUES('C12','chorus','我心、我靈<br/>立即興起讚美：<br/>你何希奇！你何偉大！<br/>讚美之聲永世還要宏偉；<br/>你何希奇！你何偉大！<br/>',NULL,7185,7185);
INSERT INTO stanza VALUES('C12','2','當我嘗到<br/>奇妙救恩的深高，<br/>想到你曾如何差遣愛子，<br/>為我來死，<br/>使我成為你新造，<br/>將你生命顯得完全盡致；<br/>',NULL,7186,7186);
INSERT INTO stanza VALUES('C12','3','當在會中，<br/>享受有福的交通，<br/>得見眾聖如何有你生命，<br/>同被建造，<br/>作你安居的靈宮，<br/>你的豐滿因此就得顯明；<br/>',NULL,7187,7187);
INSERT INTO stanza VALUES('C12','4','到我所望<br/>日期滿足的時候，<br/>我得有分於新耶路撒冷，<br/>天地更新，<br/>舊造一無再存留，<br/>你的所是得到完全顯明；<br/>',NULL,7188,7188);
INSERT INTO stanza VALUES('C13','1','父阿，<br/>在你並無轉動的影兒，<br/>你的信實極其廣大無邊。<br/>你是昔在、今在、<br/>以後永在者；<br/>你的憐憫像你永遠不變。<br/>',NULL,7189,7189);
INSERT INTO stanza VALUES('C13','chorus','你的信實廣大！<br/>你的信實無邊！<br/>你的憐憫每晨都是新鮮！<br/>我所需要<br/>一切全由你供給，<br/>你的信實極其廣大無邊！<br/>',NULL,7190,7190);
INSERT INTO stanza VALUES('C13','2','冬夏、寒暑、稼穡<br/>及時的供應，<br/>日、月、星辰<br/>晝夜所有循環，<br/>並大自然，<br/>多方全都在見證：<br/>你的信實<br/>極其廣大、無邊！<br/>',NULL,7191,7191);
INSERT INTO stanza VALUES('C13','3','你的赦免所帶<br/>平安與喜樂，<br/>你的同在所賜<br/>安撫、引導，<br/>今日力量、明日<br/>光明的盼望，<br/>全都屬我，<br/>福分一無缺少。<br/>',NULL,7192,7192);
INSERT INTO stanza VALUES('C14','1','父神，<br/>你是何等信實、<br/>何等可信、可靠；<br/>宇宙萬有都在見證，<br/>將你信實宣告。<br/>',NULL,7193,7193);
INSERT INTO stanza VALUES('C14','chorus','你的信實何等堅定！<br/>為此我獻敬拜；<br/>堅定在天，如日之恆，<br/>永遠為我存在！<br/>',NULL,7194,7194);
INSERT INTO stanza VALUES('C14','2','在你並無轉動影兒，<br/>並無任何改遷；<br/>昔在、今在、以後常在，<br/>直到永遠不變。<br/>',NULL,7195,7195);
INSERT INTO stanza VALUES('C14','3','你話像你自己可靠，<br/>永遠不能廢去；<br/>天地雖然都要滅沒，<br/>你話永存不渝。<br/>',NULL,7196,7196);
INSERT INTO stanza VALUES('C14','4','你的恩賜和你選召，<br/>永遠沒有後悔；<br/>你的恩惠和你憐憫，<br/>又如你名不頹。<br/>',NULL,7197,7197);
INSERT INTO stanza VALUES('C14','5','你話加上你的信實，<br/>對我乃是保證；<br/>藉此對你可靠救恩，<br/>我是萬分確定。<br/>',NULL,7198,7198);
INSERT INTO stanza VALUES('C14','6','縱然因罪我能失信，<br/>你仍可信不變；<br/>你絕不能背乎自己，<br/>你話必定成全。<br/>',NULL,7199,7199);
INSERT INTO stanza VALUES('C14','7','你因信實必定成就<br/>你所應許恩言；<br/>我今以你信實為糧，<br/>藉享你的甘甜。<br/>',NULL,7200,7200);
INSERT INTO stanza VALUES('C14','8','彩虹圍繞你的寶座，<br/>宣告你的信實；<br/>聖城根基猶似彩虹，<br/>見證直到永世。<br/>',NULL,7201,7201);
INSERT INTO stanza VALUES('C15','1','若無流血就有赦罪，<br/>如何對付公義？<br/>若已流血仍然責備，<br/>仍然不能合理。<br/>',NULL,7202,7202);
INSERT INTO stanza VALUES('C15','2','神，你今已不能追究，<br/>我主已經獻祭；<br/>我已得著完全自由，<br/>我罪像東離西。<br/>',NULL,7203,7203);
INSERT INTO stanza VALUES('C15','3','你義所有每一要求，<br/>我主都付代價；<br/>現今你只能加寬宥，<br/>因無審判可加。<br/>',NULL,7204,7204);
INSERT INTO stanza VALUES('C15','4','前是愛叫祂來救贖，<br/>滿足你義要求；<br/>滿足你義，今叫我主<br/>釋放所有罪囚。<br/>',NULL,7205,7205);
INSERT INTO stanza VALUES('C15','5','奇妙、奇妙，在十字架，<br/>我遇愛和公義；<br/>愛和公義如此交加，<br/>使我歌唱不已。<br/>',NULL,7206,7206);
INSERT INTO stanza VALUES('C16','1','我們讚美你的公義，<br/>你的正義我們稱奇，<br/>永遠見證不已。<br/>你是審判全地的主，<br/>在你不義誰能尋出？<br/>你是全然公義！<br/>',NULL,7207,7207);
INSERT INTO stanza VALUES('C16','2','公義是你寶座根基，<br/>和平藉此得以建立，<br/>像你信實堅定！<br/>藉著你這無比公義，<br/>基督恩典作王管理，<br/>使我得享和平。<br/>',NULL,7208,7208);
INSERT INTO stanza VALUES('C16','3','你的公義使你兒子<br/>去到十架為我受死，<br/>救贖藉此成就；<br/>當這救贖人肯信倚，<br/>你的公義立刻稱義，<br/>使人得蒙拯救。<br/>',NULL,7209,7209);
INSERT INTO stanza VALUES('C16','4','為著顯明你的公義，<br/>你曾寬容前一時期<br/>眾人所有過犯；<br/>並為顯明你的公義，<br/>你也赦免這一時期<br/>罪人所有罪愆。<br/>',NULL,7210,7210);
INSERT INTO stanza VALUES('C16','5','一日你要審判萬民，<br/>將你公義顯得完盡，<br/>藉著我主基督；<br/>我們要靠你義站立，<br/>無何能將我們搖移，<br/>恩典因義顯著。<br/>',NULL,7211,7211);
INSERT INTO stanza VALUES('C16','6','將來國度充滿公義，<br/>和平得在其上建立，<br/>萬物和諧、同居；<br/>在那永世新天新地，<br/>更要充滿你的公義，<br/>照著你所應許。<br/>',NULL,7212,7212);
INSERT INTO stanza VALUES('C17','1','當我有罪充滿痛苦，<br/>公義要求我受審判；<br/>當主流血為我救贖，<br/>公義要求賜我平安。<br/>',NULL,7213,7213);
INSERT INTO stanza VALUES('C17','2','神，是你義將我救主<br/>帶上十架忍受審判；<br/>也是你義將眾罪徒<br/>赦免、稱義並賜平安。<br/>',NULL,7214,7214);
INSERT INTO stanza VALUES('C17','3','公義要求賬須清償；<br/>當賬已經清償之後，<br/>公義又要已償的賬，<br/>不得再償，不得再收。<br/>',NULL,7215,7215);
INSERT INTO stanza VALUES('C17','4','自從我主一次流血，<br/>你不能再要祂受釘，<br/>也不能再要我解決，<br/>只能將我赦免、潔淨。<br/>',NULL,7216,7216);
INSERT INTO stanza VALUES('C17','5','從前我聽你是公義，<br/>我便害怕、逃匿不迨；<br/>現今你義一被品題，<br/>我反感覺寶貝可愛。<br/>',NULL,7217,7217);
INSERT INTO stanza VALUES('C17','6','自從我識你的公義，<br/>我更明白你的恩惠；<br/>前者使我何等安息，<br/>後者使我充滿安慰。<br/>',NULL,7218,7218);
INSERT INTO stanza VALUES('C18','1','父神，為著你的公義，<br/>我們俯伏敬拜你；<br/>你既因主稱我為義，<br/>誰能將我良心抑？<br/>你既公義，你又信實，<br/>靠你公義我站立；<br/>在你永無半點不義，<br/>誰能轉動你義臂？<br/>',NULL,7219,7219);
INSERT INTO stanza VALUES('C18','2','你將我罪已歸耶穌，<br/>你的公義將祂誅；<br/>你的律法所有要求，<br/>祂照你義全滿足。<br/>從祂你已得到贖價，<br/>因此我已得釋放；<br/>你這極公至義的神，<br/>怎能向我再討償？<br/>',NULL,7220,7220);
INSERT INTO stanza VALUES('C18','3','公義父神，你已接受<br/>耶穌作我的代替；<br/>祂是義的受你審判，<br/>代替我這不義的。<br/>祂今坐在你的右邊，<br/>作你公義的明證；<br/>祂已使你完全滿足，<br/>你義使你難變更。<br/>',NULL,7221,7221);
INSERT INTO stanza VALUES('C18','4','藉著基督贖罪寶血，<br/>我已得著你的義；<br/>在你這義遮護之下，<br/>無何能將我搖移。<br/>你且使我成為你義，<br/>何人能再定我罪？<br/>將來在那聖城撒冷，<br/>我這見證永不頹！<br/>',NULL,7222,7222);
INSERT INTO stanza VALUES('C19','1','聖父，我們向你下拜，<br/>獻上同聲的歌頌；<br/>你何聖別、你何超凡，<br/>配得永遠的尊崇。<br/>',NULL,7223,7223);
INSERT INTO stanza VALUES('C19','2','親愛父神，你心是愛，<br/>你的作為是公義，<br/>但你性情卻是聖別，<br/>使我有分你自己。<br/>',NULL,7224,7224);
INSERT INTO stanza VALUES('C19','3','你已藉著基督寶血，<br/>使我永遠成聖潔；<br/>你也藉著你的真理，<br/>使我全人被分別。<br/>',NULL,7225,7225);
INSERT INTO stanza VALUES('C19','4','你曾藉著你的聖靈，<br/>將我聖別歸於你；<br/>叫我完全得以成聖，<br/>全人，靈、魂與身體。<br/>',NULL,7226,7226);
INSERT INTO stanza VALUES('C19','5','藉著你恩，我已得到<br/>基督聖潔的生命；<br/>因此使我得以有分<br/>你那聖別的性情。<br/>',NULL,7227,7227);
INSERT INTO stanza VALUES('C19','6','將來在那聖城之中，<br/>完全有分你聖別，<br/>永遠要作極峰見證：<br/>你是如何的聖潔！<br/>',NULL,7228,7228);
INSERT INTO stanza VALUES('C20','1','父神，你曾憑你智慧，<br/>照你所愛心願，<br/>為子制定永遠計畫：<br/>萬有由祂充滿。<br/>',NULL,7229,7229);
INSERT INTO stanza VALUES('C20','chorus','深哉、富哉，你的智慧，<br/>誰能測度、追尋？<br/>然而父神，因這智慧，<br/>我蒙恩惠、憐憫！<br/>',NULL,7230,7230);
INSERT INTO stanza VALUES('C20','2','你造萬有，何其奇妙，<br/>你心誰能洞鑒？<br/>一切由你、靠你、歸你，<br/>在此你智我見。<br/>',NULL,7231,7231);
INSERT INTO stanza VALUES('C20','3','你智讓人全圈罪中，<br/>為顯憐憫之大；<br/>使人無不心服、口服，<br/>除你別無可誇。<br/>',NULL,7232,7232);
INSERT INTO stanza VALUES('C20','4','你憑智慧、藉十字架，<br/>救贖為我作成；<br/>好叫你的寶貝自己，<br/>得以置於我靈。<br/>',NULL,7233,7233);
INSERT INTO stanza VALUES('C20','5','空中執政，藉你召會，<br/>得知你智豐富；<br/>藉她，你的萬般智慧，<br/>在天給彼領悟。<br/>',NULL,7234,7234);
INSERT INTO stanza VALUES('C20','6','將來在新耶路撒冷，<br/>憐憫是我所誇；<br/>你的智慧全得顯明，<br/>顯得永無復加。<br/>',NULL,7235,7235);
INSERT INTO stanza VALUES('C21','1','父，你智慧同你恩典，<br/>全在基督集中；<br/>你使祂作我們智慧，<br/>因祂我蒙恩寵。<br/>你使祂作我們智慧，<br/>因祂我蒙恩寵。<br/>',NULL,7236,7236);
INSERT INTO stanza VALUES('C21','2','你的計畫全在於祂，<br/>祂是你恩之路；<br/>在祂－你這智慧－裡面，<br/>我得享你豐富。<br/>',NULL,7237,7237);
INSERT INTO stanza VALUES('C21','3','因祂，我們得蒙稱義，<br/>祂是我們公義；<br/>我們藉祂也得成聖，<br/>我們聖潔是彼。<br/>',NULL,7238,7238);
INSERT INTO stanza VALUES('C21','4','照著你的永遠計畫，<br/>祂也是我救贖；<br/>最終將我身體救贖，<br/>使我全人成熟。<br/>',NULL,7239,7239);
INSERT INTO stanza VALUES('C21','5','在你神聖經營之中，<br/>祂是你的智慧；<br/>為祂，我們俯伏敬拜，<br/>向你獻上讚美。<br/>',NULL,7240,7240);
INSERT INTO stanza VALUES('C21','6','在祂，我們已經看見<br/>你智豐富深廣；<br/>但是還要加富、加深，<br/>全在我們身上。<br/>',NULL,7241,7241);
INSERT INTO stanza VALUES('C22','1','父，我讚美你的憐憫，<br/>如此高大並深闊；<br/>因著我的軟弱、失敗，<br/>你的憐憫時加多。<br/>我今敬拜、我今敬拜，<br/>你這憐憫抬舉我！<br/>你這憐憫抬舉我！<br/>',NULL,7242,7242);
INSERT INTO stanza VALUES('C22','2','對你憐憫我們驚奇，<br/>如此低就且不移，<br/>竟然臨及我這罪人，<br/>且要維持永無已。<br/>何能使我、何能使我<br/>從這憐憫被遺棄？<br/>',NULL,7243,7243);
INSERT INTO stanza VALUES('C22','3','我們感激你的憐憫，<br/>如此豐富且充足！<br/>因這憐憫、藉著救贖，<br/>你曾豐厚賜眷顧。<br/>捨此何能、捨此何能<br/>使我如此蒙愛護？<br/>',NULL,7244,7244);
INSERT INTO stanza VALUES('C22','4','哦，你憐憫富有感召，<br/>柔細、可愛又甘甜！<br/>藉你忍耐和你恩慈，<br/>正合我需賜恩典。<br/>我們寶貴、我們寶貴<br/>你這憐憫的完全。<br/>',NULL,7245,7245);
INSERT INTO stanza VALUES('C22','5','我今享受你的憐憫，<br/>永遠不舊、永遠新；<br/>每日早晨臨到我身，<br/>猶如甘露施滋潤。<br/>何等甜美、何等甜美，<br/>滿心讚美你憐憫。<br/>',NULL,7246,7246);
INSERT INTO stanza VALUES('C22','6','對你讚美何能止息，<br/>因你憐憫永持久；<br/>你的恩惠、你的眷顧，<br/>全都為我永保守。<br/>可靠憐憫、可靠憐憫，<br/>永不能叫我蒙羞。<br/>',NULL,7247,7247);
INSERT INTO stanza VALUES('C23','1','父，你憐憫<br/>已向我們顯明，<br/>照你啟示；<br/>罪人如我竟能有你生命，<br/>作你兒子。<br/>憐憫器皿乃是你所豫定，<br/>貴重器皿永為你作見證。<br/>',NULL,7248,7248);
INSERT INTO stanza VALUES('C23','2','『喜愛憐憫，<br/>並不喜愛祭祀，』<br/>你曾宣告；<br/>因這憐憫，<br/>我們受你恩賜，<br/>並得榮耀。<br/>不在定意或是奔跑的人，<br/>乃在你這願發憐憫的神。<br/>',NULL,7249,7249);
INSERT INTO stanza VALUES('C23','3','父，你憐憫<br/>並你恩惠、慈愛，<br/>我已得嘗；<br/>你這憐憫帶來你的同在，<br/>並你面光。<br/>因你憐憫，<br/>我今向你下拜，<br/>讚你憐憫，<br/>歌頌直到萬代。<br/>',NULL,7250,7250);
INSERT INTO stanza VALUES('C24','1','神的大愛真是遠超<br/>筆所能描、口所能陳；<br/>牠比最高星宿還高，<br/>牠比最深地獄還深。<br/>始祖犯罪，驚恐自危，<br/>神賜愛子來救；<br/>當人痛悔，神就迎歸，<br/>所有罪案全勾。<br/>',NULL,7251,7251);
INSERT INTO stanza VALUES('C24','chorus','哦，神的愛，何其豐富、<br/>何其無法測量！<br/>牠是堅強，存到永古，<br/>天使、聖徒同唱。<br/>',NULL,7252,7252);
INSERT INTO stanza VALUES('C24','2','歲月消逝，榮華衰敗，<br/>天地廢去，事物更變，<br/>人今拒絕神的大愛，<br/>那日惟有求助山巖；<br/>神的大愛不會稍改，<br/>何其無法測量；<br/>大施恩貸，對人罪債，<br/>聖徒、天使同唱。<br/>',NULL,7253,7253);
INSERT INTO stanza VALUES('C24','3','縱令洋海盡是墨汁，<br/>無邊穹蒼都成白紙，<br/>田間草桿根根筆枝，<br/>世上眾人個個文士；<br/>若寫神的大愛無極，<br/>一切猶感缺欠；<br/>墨乾、筆棄、紙罄、人敝，<br/>未能寫出半點。<br/>',NULL,7254,7254);
INSERT INTO stanza VALUES('C25','1','父阿，你賜何等慈愛，<br/>我們衷心感銘；<br/>因此我們前來敬拜，<br/>稱頌你的聖名。<br/>',NULL,7256,7256);
INSERT INTO stanza VALUES('C25','2','你已敞開你的胸懷，<br/>將你心意顯明；<br/>且在子裡已經出來，<br/>將這心意完成。<br/>',NULL,7257,7257);
INSERT INTO stanza VALUES('C25','3','為愛我們你捨愛子，<br/>叫祂來此受死，<br/>好叫我們成為眾子，<br/>與祂同作後嗣。<br/>',NULL,7258,7258);
INSERT INTO stanza VALUES('C25','4','我們因祂有你生命，<br/>永遠得你為父，<br/>有分於你神聖性情，<br/>得享你的豐富。<br/>',NULL,7259,7259);
INSERT INTO stanza VALUES('C25','5','你差子靈進入我靈，<br/>使我稱呼阿爸；<br/>靈裡重生、靈裡印證、<br/>靈裡使我變化。<br/>',NULL,7260,7260);
INSERT INTO stanza VALUES('C25','6','帶領眾子進入榮耀，<br/>乃是你的目標；<br/>與你兒子畢像畢肖，<br/>必使我們達到。<br/>',NULL,7261,7261);
INSERT INTO stanza VALUES('C25','7','在這變化過程之中，<br/>凡事有你引領；<br/>力上加力、榮上加榮，<br/>直到變化完成。<br/>',NULL,7262,7262);
INSERT INTO stanza VALUES('C25','8','父阿，你賜何等慈愛，<br/>我們永遠感銘！<br/>永遠俯伏、永遠敬拜、<br/>永遠稱頌你名！<br/>',NULL,7263,7263);
INSERT INTO stanza VALUES('C26','1','你愛所給雖然甚多，<br/>恩賜眾善者哪！<br/>但在天上，還未見過<br/>甚麼比血更大。<br/>',NULL,7264,7264);
INSERT INTO stanza VALUES('C26','2','就是我的信心對血，<br/>也是你愛所給；<br/>不然，恩賜雖合所缺，<br/>也是虛空無益。<br/>',NULL,7265,7265);
INSERT INTO stanza VALUES('C26','3','哦，神的愛，你是深海，<br/>我罪都埋裡面；<br/>我的不義，你都遮蓋，<br/>虧欠，你都赦免。<br/>',NULL,7266,7266);
INSERT INTO stanza VALUES('C26','4','在寶血裡，我已尋出<br/>你愛心的蹤跡；<br/>由此我知你的寬恕，<br/>並知你的公義。<br/>',NULL,7267,7267);
INSERT INTO stanza VALUES('C26','5','心會軟弱，身會衰頹，<br/>我總安然相信；<br/>天地雖然都要銷毀，<br/>我錨已經拋穩。<br/>',NULL,7268,7268);
INSERT INTO stanza VALUES('C26','6','到了那時，我要證明<br/>你愛有何價值；<br/>但在今日我的生命<br/>就先靠牠扶持。<br/>',NULL,7269,7269);
INSERT INTO stanza VALUES('C26','7','當讚美你！再讚美你！<br/>有何不是你給：<br/>寶貴救主，和那使彼<br/>顯為寶貴的力。<br/>',NULL,7270,7270);
INSERT INTO stanza VALUES('C27','1','神阿，你為何故<br/>賜下耶穌基督，<br/>你的親愛兒子，<br/>來為罪人受死？<br/>無他，乃是你的大愛，<br/>叫你這樣捨去心愛。<br/>',NULL,7271,7271);
INSERT INTO stanza VALUES('C27','2','神，你兒子為何<br/>離開天上寶座，<br/>受苦直到命絕，<br/>流出祂的寶血？<br/>無他，乃是祂的大愛，<br/>叫祂這樣為我受害。<br/>',NULL,7272,7272);
INSERT INTO stanza VALUES('C27','3','甚麼感動你心，<br/>叫你賜下聖靈，<br/>將天上的平安，<br/>充滿我們心坎？<br/>無他，乃是你的大愛，<br/>叫你這樣差遣祂來。<br/>',NULL,7273,7273);
INSERT INTO stanza VALUES('C27','4','神阿，你恩這大！<br/>我愛實在太差！<br/>我心應當湧出<br/>感謝、讚美、歡呼，<br/>求主使我因你大愛，<br/>向你歌頌直到萬代。<br/>',NULL,7274,7274);
INSERT INTO stanza VALUES('C28','1','神哪，你在聖所之內，<br/>接受我們敬拜讚美，<br/>因你的愛何其真。<br/>我們死在罪惡之中，<br/>好像囚犯早已途窮，<br/>你就來釋放我們。<br/>你那無限豐富的愛，<br/>感動你以憐憫為懷，<br/>你就來拯救我們。<br/>',NULL,7275,7275);
INSERT INTO stanza VALUES('C28','2','你並不願罪人沉淪，<br/>你願他們回轉求懇<br/>你作他們的救主。<br/>你在子裡揀選我們<br/>脫離罪和死亡圍困，<br/>又使我們蒙永福。<br/>我們今可來喊『阿爸，』<br/>乃因你子，不再懼怕，<br/>坦然親近我們父。<br/>',NULL,7276,7276);
INSERT INTO stanza VALUES('C28','3','不久祂接屬祂的人，<br/>圍你寶座，帶著他們<br/>前來敬拜並讚美。<br/>那時歌唱甜美聲浪，<br/>要達天地最遠邊疆，<br/>發自蒙贖的大會。<br/>但是今日我們渴慕，<br/>父阿，向你敬拜俯伏，<br/>同心歌唱你恩惠。<br/>',NULL,7277,7277);
INSERT INTO stanza VALUES('C29','1','我們從前所有，<br/>不過就是死亡、罪惡；<br/>我們現今所有福分，<br/>都是來自我神。<br/>',NULL,7278,7278);
INSERT INTO stanza VALUES('C29','2','我在罪中，你愛來尋，<br/>感動我心相信；<br/>叫我因信得著安樂，<br/>因你基督得活。<br/>',NULL,7279,7279);
INSERT INTO stanza VALUES('C29','3','我為聖徒，現在所享，<br/>和我將來盼望，<br/>無一是我自己配得，<br/>都是因你恩澤。<br/>',NULL,7280,7280);
INSERT INTO stanza VALUES('C29','4','神，你這樣豐富的愛，<br/>誰能報答得來？<br/>你愛真是遠超人意，<br/>神聖！不可思議！<br/>',NULL,7281,7281);
INSERT INTO stanza VALUES('C29','5','哦父，但願你今使我<br/>時刻明白更多：<br/>像你這樣慈愛的神，<br/>當得我命、我心！<br/>',NULL,7282,7282);
INSERT INTO stanza VALUES('C29','6','我心若說要報你愛，<br/>聊以表明感戴，<br/>我就還是不知你愛<br/>深闊遠超洋海！<br/>',NULL,7283,7283);
INSERT INTO stanza VALUES('C29','7','但願我們對你大愛，<br/>不致當作買賣；<br/>你向我們所有愛心，<br/>我們怎能報盡！<br/>',NULL,7284,7284);
INSERT INTO stanza VALUES('C29','8','因此我們不再說報，<br/>－你愛實是太高－我們惟有滿心感戴，<br/>向你永遠敬拜。<br/>',NULL,7285,7285);
INSERT INTO stanza VALUES('C29','9','慈愛父神，我們欠你，<br/>一切都欠了你，<br/>我們只好一面感激，<br/>一面因子安息。<br/>',NULL,7286,7286);
INSERT INTO stanza VALUES('C30','1','父阿，我們向你下拜，<br/>滿心希奇你的大愛！<br/>人算甚麼，你竟眷念？<br/>輕微如我你也揀選！<br/>',NULL,7287,7287);
INSERT INTO stanza VALUES('C30','2','我們讚美你的心意，<br/>原是計畫要人像你，<br/>有你生命，給你充滿，<br/>有你形像，將你彰顯。<br/>',NULL,7288,7288);
INSERT INTO stanza VALUES('C30','3','你來造人照你形像，<br/>並將權柄交人執掌，<br/>且作生命給人接受，<br/>要人享受你的所有。<br/>',NULL,7289,7289);
INSERT INTO stanza VALUES('C30','4','你要進入人的裡面，<br/>與人調和，將人成全，<br/>使人變質，同被建造，<br/>作你居所，顯你榮耀。<br/>',NULL,7290,7290);
INSERT INTO stanza VALUES('C30','5','人雖墮落，你未放棄，<br/>仍要在人成全你意；<br/>藉著救贖將人帶回，<br/>顯出萬般愛心、智慧。<br/>',NULL,7291,7291);
INSERT INTO stanza VALUES('C30','6','你在子裡已經顯出，<br/>死而復活成功救贖；<br/>藉成那靈也已進入，<br/>在我裡面施恩、眷顧。<br/>',NULL,7292,7292);
INSERT INTO stanza VALUES('C30','7','你以我靈為至聖所，<br/>其中設你施恩寶座；<br/>要我靈裡與你相交，<br/>如同祭司燒香、禱告。<br/>',NULL,7293,7293);
INSERT INTO stanza VALUES('C30','8','在此恩惠如同江河，<br/>流自你的施恩寶座，<br/>將我流過、將我變化、<br/>將我建造成為你家。<br/>',NULL,7294,7294);
INSERT INTO stanza VALUES('C30','9','我們如此受寵、受惠，<br/>萬分希奇你的聖垂；<br/>心中感激你的大愛，<br/>靈裡向你獻上敬拜。<br/>',NULL,7295,7295);
INSERT INTO stanza VALUES('C31','1','父阿，久在創世之前，<br/>你選我們，愛無限！<br/>這愛甘美、激勵、深厚，<br/>吸引我們親耶穌。<br/>還要保守，還要保守，<br/>我們今後永穩固。<br/>我們今後永穩固。<br/>',NULL,7296,7296);
INSERT INTO stanza VALUES('C31','2','雖然宇宙逐漸改遷，<br/>但是我神總不變；<br/>祂的愛心，同祂話語，<br/>向著我們永堅定；<br/>神的兒女，神的兒女，<br/>我們應當讚祂名。<br/>我們應當讚祂名。<br/>',NULL,7297,7297);
INSERT INTO stanza VALUES('C31','3','神的憐憫是我詩歌，<br/>我口所誇心所樂；<br/>從始至終，惟有白恩，<br/>能得我命感我心。<br/>神愛我們！神愛我們！<br/>連祂愛子都不吝！<br/>連祂愛子都不吝！<br/>',NULL,7298,7298);
INSERT INTO stanza VALUES('C31','4','愛的神阿，我們現在<br/>同心歌頌你奇愛，<br/>直到天上，遠離塵囂，<br/>我們仍是要稱揚；<br/>但願榮耀，但願榮耀，<br/>永遠歸神和羔羊。<br/>永遠歸神和羔羊。<br/>',NULL,7299,7299);
INSERT INTO stanza VALUES('C32','1','榮耀父神，讚美你，<br/>我是你恩對象；<br/>今為使你心歡喜，<br/>前來向你頌揚：<br/>永世標出的眾子，<br/>豫定都進榮光，<br/>同著基督你愛子，<br/>作你至高對象。<br/>',NULL,7300,7300);
INSERT INTO stanza VALUES('C32','2','創世之前你揀選，<br/>要我成為聖潔；<br/>豫定我們蒙恩典，<br/>作你榮耀基業。<br/>為著兒子的名分，<br/>你早將我標出；<br/>等到長大得成人，<br/>必得豫定之福。<br/>',NULL,7301,7301);
INSERT INTO stanza VALUES('C32','3','照著永世的豫定，<br/>賜我以你恩召；<br/>叫我得著你生命，<br/>將我罪過去掉。<br/>聖靈作質、作印記，<br/>並作一切供應，<br/>我得永遠屬於你，<br/>享受你的豐盛。<br/>',NULL,7302,7302);
INSERT INTO stanza VALUES('C32','4','哦！父，除你有誰能<br/>如此祝福我們：<br/>使我有分你的靈，<br/>蒙你生命之恩？<br/>不久我們要永遠<br/>與祂同得榮耀；<br/>永遠與祂活你前，<br/>將你榮形返照！<br/>',NULL,7303,7303);
INSERT INTO stanza VALUES('C33','1','父神阿，你在羔羊裡<br/>是我的希望和安息，<br/>你名所表一切慈仁，<br/>都是為著賜福我們。<br/>',NULL,7304,7304);
INSERT INTO stanza VALUES('C33','2','你大而智、你公而仁，<br/>你是我父、又是我神；<br/>我們屬你，是藉寶血，<br/>作你兒女，永遠聯結。<br/>',NULL,7305,7305);
INSERT INTO stanza VALUES('C33','3','我們今帶疲倦的靈，<br/>來到你前仰望你名；<br/>煩悶艱苦，尋求恩惠，<br/>如同困鹿渴慕溪水。<br/>',NULL,7306,7306);
INSERT INTO stanza VALUES('C33','4','既是這樣，願你施恩，<br/>好叫我們親近你身；<br/>你的同在作我居所，<br/>你的大愛作我喜樂。<br/>',NULL,7307,7307);
INSERT INTO stanza VALUES('C33','5','這叫我們永遠歡騰，<br/>這叫黑夜變為光明；<br/>若有微息尚能稱頌，<br/>必引弱聲向你歌誦。<br/>',NULL,7308,7308);
INSERT INTO stanza VALUES('C34','1','榮耀歸於父神，<br/>祂已作大事；<br/>祂愛世人，<br/>甚至差遣祂兒子，<br/>來為我們捨命，<br/>成功了救贖，<br/>打開生命恩門，<br/>人人可進入。<br/>',NULL,7309,7309);
INSERT INTO stanza VALUES('C34','chorus','讚美神！讚美神！<br/>全地都當稱祝！<br/>讚美神！讚美神！<br/>眾人都要歡呼！<br/>哦，來就近父神，<br/>藉著祂兒子，<br/>並將榮耀歸祂，<br/>祂已作大事！<br/>',NULL,7310,7310);
INSERT INTO stanza VALUES('C34','2','何等完全救贖，<br/>寶血將我買；<br/>這是神的應許，<br/>信者可倚賴；<br/>就是極大罪人，<br/>若真肯相信，<br/>在他相信之時，<br/>必得赦罪恩。<br/>',NULL,7311,7311);
INSERT INTO stanza VALUES('C34','3','神已曉諭大事，<br/>神已作大事，<br/>我們也要大樂，<br/>藉著祂兒子；<br/>但當看見主時，<br/>我們的驚喜必要更純、<br/>更高、更大得無比。<br/>',NULL,7312,7312);
INSERT INTO stanza VALUES('C35','1','神，我讚美你，<br/>差遣你的愛子，<br/>釘死，復活，又升天，<br/>作我大祭司。<br/>',NULL,7313,7313);
INSERT INTO stanza VALUES('C35','chorus','阿利路亞，榮耀歸你；<br/>阿利路亞，阿們！<br/>阿利路亞，榮耀歸你，<br/>感謝你大恩。<br/>',NULL,7314,7314);
INSERT INTO stanza VALUES('C35','2','神，我讚美你，<br/>賜下亮光之靈，<br/>啟示我的救贖主，<br/>開明我眼睛。<br/>',NULL,7315,7315);
INSERT INTO stanza VALUES('C35','3','榮耀和讚美，<br/>歸給慈愛父神；<br/>藉你愛子的救贖，<br/>得蒙你救恩。<br/>',NULL,7316,7316);
INSERT INTO stanza VALUES('C35','4','讚美再讚美，<br/>感激你的大愛，<br/>心被你愛再焚燒，<br/>向你獻敬拜。<br/>',NULL,7317,7317);
INSERT INTO stanza VALUES('C36','1','我們不會疲倦<br/>不唱這首舊詩章，<br/>榮耀歸神，阿利路亞！<br/>我們聲浪依舊，<br/>靈裡比前更堅強；<br/>榮耀歸神，阿利路亞！<br/>',NULL,7318,7318);
INSERT INTO stanza VALUES('C36','chorus','神的兒女有權利，<br/>可以大喊並大唱，<br/>因為前途更光明，<br/>我們魂樂似飛翔，<br/>不久我們進榮耀，<br/>就要朝見我君王，<br/>榮耀歸神，阿利路亞！<br/>',NULL,7319,7319);
INSERT INTO stanza VALUES('C36','2','我們浸沉在那<br/>救贖大愛，極樂中；<br/>榮耀歸神，阿利路亞！<br/>我們心中樂極<br/>有如插翅上高空；<br/>榮耀歸神，阿利路亞！<br/>',NULL,7320,7320);
INSERT INTO stanza VALUES('C36','3','我們要去之城<br/>乃是父神所建造；<br/>榮耀歸神，阿利路亞！<br/>那裡，我可面見<br/>我王所有的光耀；<br/>榮耀歸神，阿利路亞！<br/>',NULL,7321,7321);
INSERT INTO stanza VALUES('C36','4','那裡，我們要藉新詩<br/>喊出救贖恩；<br/>榮耀歸神，阿利路亞！<br/>那裡，我們要同<br/>眾聖擁擠耶穌身；<br/>榮耀歸神，阿利路亞！<br/>',NULL,7322,7322);
INSERT INTO stanza VALUES('C37','1','阿爸，父阿，我們現在<br/>因主到你面前來；<br/>你的兒女到此聚集，<br/>願得應許的福氣。<br/>祂的寶血已洗我們，<br/>我們藉祂來得恩；<br/>你靈也已指教我們<br/>呼喊阿爸，近你身。<br/>',NULL,7323,7323);
INSERT INTO stanza VALUES('C37','2','我們從前好像浪子，<br/>離你流蕩真無知；<br/>但你的恩比罪更多，<br/>拯救我們脫災禍。<br/>給我們穿救恩衣裳，<br/>給我們坐你席上；<br/>我們快樂，你也快樂，<br/>因你恩典真溥博！<br/>',NULL,7324,7324);
INSERT INTO stanza VALUES('C37','3','你用為父的愛親嘴，<br/>表明你赦浪子罪；<br/>你宰肥犢，你使我們<br/>永遠與你不再分。<br/>『我們理當歡喜快樂，』<br/>我們聽你如此說：<br/>『因我兒子死而復活，<br/>曾經失去又得著。』<br/>',NULL,7325,7325);
INSERT INTO stanza VALUES('C37','4','阿爸，父阿，我稱頌你，<br/>因你慈愛真希奇！<br/>天上天軍因著我們，<br/>也要希奇你大恩。<br/>不久我們都要聚集，<br/>在你座前來溫習：<br/>阿爸的愛何等豐富！<br/>阿爸的名何寬恕！<br/>',NULL,7326,7326);
INSERT INTO stanza VALUES('C38','1','阿爸，我們來頌讚你！<br/>我們謙卑敬拜你！<br/>我們現今得認識你，<br/>真是我們的福氣。<br/>我們得著這樣權柄，<br/>是因耶穌的尊名；<br/>你靈也和我們的靈，<br/>證明我們有生命。<br/>',NULL,7327,7327);
INSERT INTO stanza VALUES('C38','2','世界還未起首時候，<br/>你就在基督裡頭，<br/>豫定我們作你兒子，<br/>得你生命的恩賜。<br/>哦父，你是何等慈愛，<br/>竟使我們蒙恩待！<br/>叫我們這凡俗罪人，<br/>得與你性情有分！<br/>',NULL,7328,7328);
INSERT INTO stanza VALUES('C38','3','我們天性在亞當裡，<br/>真是敗壞無可比；<br/>但是你的永遠旨意，<br/>豫定我們歸於你；<br/>靠著救主我們得贖，<br/>因重生稱你為父；<br/>救主、天父、教會合一，<br/>哦，這恩典何希奇！<br/>',NULL,7329,7329);
INSERT INTO stanza VALUES('C38','4','因此，境遇雖然轉遷，<br/>雖有患難和試煉，<br/>你的慈愛總是不變，<br/>要領我們直到天。<br/>不久，你所贖的兒女，<br/>要在寶座前相聚，<br/>述說他們得救故事，<br/>並向你讚美不置。<br/>',NULL,7330,7330);
INSERT INTO stanza VALUES('C39','1','阿爸父神，我們前來<br/>低頭、屈膝、全心敬拜；<br/>你既不需牛羊之祭，<br/>我們靈中獻上『實際。』<br/>',NULL,7331,7331);
INSERT INTO stanza VALUES('C39','2','阿爸，你是自有永有，<br/>亙古常在，存到永久；<br/>你的寶座安定在天，<br/>榮耀、聖潔、權能無限。<br/>',NULL,7332,7332);
INSERT INTO stanza VALUES('C39','3','無望、無救，世上罪黎，<br/>獲罪於你，何敢禱祈？<br/>只看見你無私公義，<br/>未認識你慈愛心意。<br/>',NULL,7333,7333);
INSERT INTO stanza VALUES('C39','4','但你藉著懷中獨子，<br/>將你自己完全啟示；<br/>罪人一日未經救贖，<br/>你在寶座無從滿足。<br/>',NULL,7334,7334);
INSERT INTO stanza VALUES('C39','5','獨生兒子可暫離棄，<br/>為要得著我們罪黎；<br/>十字架上任其受苦，<br/>為使我們親你有路。<br/>',NULL,7335,7335);
INSERT INTO stanza VALUES('C39','6','我們因你愛子受死，<br/>歸你名下作你眾子；<br/>從前你是何等可怕，<br/>今日你是親愛阿爸。<br/>',NULL,7336,7336);
INSERT INTO stanza VALUES('C39','7','阿爸父神，愛深、恩高，<br/>你的兒女無法圖報；<br/>我們惟有永遠感戴，<br/>向你讚美、向你敬拜。<br/>第一節的『實際』<br/>指基督。<br/>',NULL,7337,7337);
INSERT INTO stanza VALUES('C40','1','沒有血、沒有壇，<br/>祭祀已成過去；<br/>沒有煙冒、沒有火燃，<br/>犧牲再無必需；<br/>更美的血流自更貴的脈，<br/>洗淨人的污穢，<br/>清償人的罪債。<br/>',NULL,7338,7338);
INSERT INTO stanza VALUES('C40','2','神，我們感謝你，<br/>為你兒子的血，<br/>靠牠我們被稱為義，<br/>靠牠我們得捷；<br/>大勝地獄、死亡、<br/>黑暗勢力，<br/>毋需兩次爭戰，<br/>不留一個仇敵。<br/>',NULL,7339,7339);
INSERT INTO stanza VALUES('C40','3','神，我們感謝你，<br/>因有天來恩典，<br/>漫過我們最闊不義，<br/>赦免最深罪愆。<br/>我們要讚美你所有的愛，<br/>像你榮耀、權柄、能力，<br/>存到萬代。<br/>',NULL,7340,7340);
INSERT INTO stanza VALUES('C40','4','神，我們感謝你，<br/>因為盼望堅定，<br/>下沉的靈藉以再起，<br/>直至晨曦顯明；<br/>有福的盼望、<br/>何等的鼓舞、<br/>最疲倦的曠野、<br/>最艱難的道路。<br/>',NULL,7341,7341);
INSERT INTO stanza VALUES('C40','5','神，我們感謝你，<br/>為那榮耀之冠，<br/>並非只有一時美麗，<br/>轉眼即已枯殘，<br/>乃是像寶座不朽到永遠，<br/>樂哉，能向寶座<br/>投下所有冠冕。<br/>',NULL,7342,7342);
INSERT INTO stanza VALUES('C41','1','哦，神，是你召我們<br/>來看你的兒子，<br/>祂是你心的奇珍，<br/>祂行完你意思；<br/>我們因你肯白捨，<br/>你的獨一心愛，<br/>纔知你心是真切，<br/>要救我們脫害。<br/>',NULL,7343,7343);
INSERT INTO stanza VALUES('C41','2','哦，聖父，憐憫的神，<br/>我們因子的名，<br/>纔敢向你常求恩，<br/>纔有永遠生命。<br/>你耳所常愛聽聞－，<br/>悠揚如音樂的，<br/>已叫我們的靈魂，<br/>脫盡所有猜疑。<br/>',NULL,7344,7344);
INSERT INTO stanza VALUES('C41','3','戰兢罪人心常怕，<br/>你永不忘先前，<br/>但祂一次的受罰，<br/>使你不再記念。<br/>當無甚麼可以使，<br/>我們得自由時，<br/>父，你愛子的受死，<br/>還了我們罪值。<br/>',NULL,7345,7345);
INSERT INTO stanza VALUES('C41','4','你對我們(信祂的)<br/>心中已無忿怒；<br/>我們現今也無忌，<br/>因知你已眷顧；<br/>回家兒女你親嘴，<br/>並賜光明衣袍，<br/>你的慈愛已安慰，<br/>我們心中苦惱。<br/>',NULL,7346,7346);
INSERT INTO stanza VALUES('C41','5','哦，你怎麼能喜歡，<br/>我們這樣的人？<br/>我們豈非使你難，<br/>豈非見你就恨？<br/>哦，真希奇，最希奇！<br/>這是神聖奧祕！<br/>從前發聲如雷的，<br/>說：『罪人，我屬你！』<br/>',NULL,7347,7347);
INSERT INTO stanza VALUES('C42','1','父神，我今敬拜你，<br/>恭敬向你來頂禮，<br/>藉著基督作我祭：<br/>父阿，我敬拜你。<br/>',NULL,7348,7348);
INSERT INTO stanza VALUES('C42','2','你愛浩大，何深闊，<br/>藉著祂死臨及我，<br/>恩、義，因此我全得：<br/>父阿，我敬拜你。<br/>',NULL,7349,7349);
INSERT INTO stanza VALUES('C42','3','原是罪人何污穢，<br/>今成神子何尊貴！<br/>何等豐厚的恩惠：<br/>父阿，我敬拜你。<br/>',NULL,7350,7350);
INSERT INTO stanza VALUES('C42','4','今在靈中敬拜你，<br/>並以基督為實際，<br/>對你，祂是馨香祭：<br/>父阿，我敬拜你。<br/>',NULL,7351,7351);
INSERT INTO stanza VALUES('C42','5','我願向你再獻上，<br/>深處感戴的頌揚，<br/>頌揚你愛永無疆：<br/>父阿，我敬拜你。<br/>',NULL,7352,7352);
INSERT INTO stanza VALUES('C43','1','父阿，你是愛大無極，<br/>我們要來讚美你；<br/>我們是受恩典教益，<br/>你前不能不歡喜。<br/>你從世前就已定意，<br/>豫備我們的地位；<br/>你在時來就顯能力，<br/>就向我們施恩惠。<br/>',NULL,7353,7353);
INSERT INTO stanza VALUES('C43','2','你使祂從死裡復活，<br/>你使祂成你首生，<br/>祂已完成祂的工作，<br/>我們已信祂得勝。<br/>我們現今已成眾子，<br/>我們不能不快樂；<br/>面向長子所有佈置，<br/>日夜時常有詩歌。<br/>',NULL,7354,7354);
INSERT INTO stanza VALUES('C43','3','祂的神是我們的神，<br/>祂父也是我們父，<br/>我們與祂無法割分，<br/>祂與我們同骨肉。<br/>祂領我們回去見你，<br/>今日會中同唱詩；<br/>像祂，我們與祂合一，<br/>因子，我們作眾子。<br/>',NULL,7355,7355);
INSERT INTO stanza VALUES('C43','4','神聖的愛！神聖的恩！<br/>子和眾子永聯合；<br/>這個就是我們永分！<br/>這個就是父喜樂！<br/>我們現今等在這裡，<br/>等你兒子從天臨；<br/>求使我們所有心意，<br/>是到祂前鼓樂琴。<br/>',NULL,7356,7356);
INSERT INTO stanza VALUES('C44','1','父阿，兒女稱頌你名，<br/>是受恩典的教訓；<br/>我們歡樂，因你生命，<br/>已使我們歸羊群。<br/>',NULL,7357,7357);
INSERT INTO stanza VALUES('C44','2','你所給的得救證實，<br/>遠超我們的讚美；<br/>我們的心現在直指，<br/>你在天上的座位。<br/>',NULL,7358,7358);
INSERT INTO stanza VALUES('C44','3','因在那裡，祂作我們，<br/>永遠不變的寄託。<br/>你將生命分給罪人，<br/>祂為罪人謀解脫。<br/>',NULL,7359,7359);
INSERT INTO stanza VALUES('C44','4','永世雖久，不過就是：<br/>顯明你恩的豐富，<br/>好叫那些因你兒子，<br/>為兒女者，來稱祝。<br/>',NULL,7360,7360);
INSERT INTO stanza VALUES('C44','5','我們現雖未見早晨，<br/>卻仍安心歷世途，<br/>等候祂來提接我們，<br/>脫離死亡和墳墓。<br/>',NULL,7361,7361);
INSERT INTO stanza VALUES('C44','6','我們歡樂，因你自己，<br/>就是我們的『永分，』<br/>像你兒子！同祂一起！<br/>享受光明的早晨！<br/>',NULL,7362,7362);
INSERT INTO stanza VALUES('C44','7','哦，求聖父因祂慈名，<br/>保守我們在這裡，<br/>無憂無慮，隨祂而行，<br/>直到同樂在那地。<br/>',NULL,7363,7363);
INSERT INTO stanza VALUES('C45','1','父神，我們稱頌你，<br/>你前我們歡喜；<br/>永遠脫開了死亡，<br/>與你兒子一起。<br/>祂是一『人』活你前，<br/>在那清明光中，<br/>在你無限的愛裡，<br/>永遠蒙你恩寵。<br/>',NULL,7364,7364);
INSERT INTO stanza VALUES('C45','2','祂父就是我們父，<br/>祂神就是我神；<br/>祂是你愛的兒子，<br/>你心所喜所珍。<br/>祂帶我們親近你，<br/>有分於祂地位，<br/>享受你愛的恩寵，<br/>並你臉上光輝。<br/>',NULL,7365,7365);
INSERT INTO stanza VALUES('C45','3','你愛已將我擁抱，<br/>這愛永不消沉；<br/>這愛全都集中，<br/>在你的愛子一身。<br/>在祂裡面，<br/>你眾子－祂的許多弟兄－與祂同享你這愛，<br/>同受你的恩寵。<br/>',NULL,7366,7366);
INSERT INTO stanza VALUES('C46','1','慈愛父神，<br/>對於你的大愛，<br/>眾子響應；<br/>我們今能自由坦然前來，<br/>是靠子名。<br/>何等希奇，<br/>我們都能像祂，<br/>作你喜悅，<br/>永遠與祂無差。<br/>',NULL,7367,7367);
INSERT INTO stanza VALUES('C46','2','祂作喜悅，<br/>我們掛祂身上，<br/>藉著你恩；<br/>祂是你愛所有獨一對象，<br/>我竟有分。<br/>我們同祂享受你愛無限，<br/>祂的榮耀你前我們得見。<br/>',NULL,7368,7368);
INSERT INTO stanza VALUES('C46','3','正當眾子你前<br/>口唱、心和，<br/>同聲頌揚；<br/>祂在率領，<br/>心中何等喜樂，<br/>向你歌唱。<br/>父神，<br/>在那愛的經營之中，<br/>你是最高源頭，<br/>配得稱頌。<br/>',NULL,7369,7369);
INSERT INTO stanza VALUES('C47','1','阿爸，我們進前來，<br/>由你愛子領率，<br/>獻上讚美和敬拜，<br/>並享父親慈愛。<br/>你在寶座心歡樂，<br/>永世計畫成功－死而復活、失又得，<br/>我們已成聖眾。<br/>',NULL,7370,7370);
INSERT INTO stanza VALUES('C47','2','桌上陳設杯和餅，<br/>我們已同領過；<br/>這個表記是說明<br/>你的愛子工作。<br/>祂的身體被擘開，<br/>闢成新活道路，<br/>我們藉此得前來，<br/>稱你作阿爸父。<br/>',NULL,7371,7371);
INSERT INTO stanza VALUES('C47','3','祂的寶血已流出，<br/>塗抹我們罪愆；<br/>你的公義和忿怒，<br/>不再追我虧欠。<br/>祂血永在你面前，<br/>為我說出美言，<br/>撒但控告無效驗，<br/>我們不再自譴。<br/>',NULL,7372,7372);
INSERT INTO stanza VALUES('C47','4','人比天使更微小，<br/>你前算得甚麼？<br/>你竟眷顧如珍寶，<br/>尋他與你復和。<br/>天使墮落你不尋，<br/>惟人蒙你赦免！<br/>讚美，哦父，讚不盡<br/>你這逾格恩典。<br/>',NULL,7373,7373);
INSERT INTO stanza VALUES('C48','1','宴筵方過，<br/>我們尚感甜美，<br/>父，<br/>你愛子率領我們讚美；<br/>祂領詩歌，<br/>於你何親、何甜，<br/>我們與祂一致，<br/>和聲頌讚。<br/>',NULL,7374,7374);
INSERT INTO stanza VALUES('C48','2','哦父，<br/>你外我們不需別惠，<br/>有何比你恩愛更為寶貴！<br/>我們敬拜，因為我們嘗到<br/>你那無窮生命豐美味道。<br/>',NULL,7375,7375);
INSERT INTO stanza VALUES('C48','3','在你愛中我愛對你增長，<br/>勝過所有人情、<br/>屬地捆綁；<br/>你愛藉著大能，帶領我心<br/>享受你的同在與日俱深。<br/>',NULL,7376,7376);
INSERT INTO stanza VALUES('C48','4','父阿，<br/>我們跟隨你的愛子，<br/>在此向你讚美頌揚不止；<br/>飽享你的聖愛，<br/>心滿意足，<br/>眾子嘗到你名所有豐富。<br/>',NULL,7377,7377);
INSERT INTO stanza VALUES('C49','1','父阿，<br/>我們在你面前拜禮，<br/>尊敬鄭重；<br/>現在我們這些兒女聚集，<br/>是要稱頌：<br/>奇恩如何帶領我們回家，<br/>與你兒子一同親近阿爸！<br/>',NULL,7378,7378);
INSERT INTO stanza VALUES('C49','2','知愛的人都知這裡的愛，<br/>何等的深；<br/>從祂身上你愛已經佈開，<br/>我父我神！<br/>現今祂在你的面前帶同<br/>所有稱頌你愛的人稱頌。<br/>',NULL,7379,7379);
INSERT INTO stanza VALUES('C49','3','祂領詩歌，<br/>你耳何等樂聽祂的頌稱；<br/>但你豈不也是一樣愛聆<br/>我們和聲；<br/>你心愛祂遠在創世之前，<br/>你也定規我們作祂同伴。<br/>',NULL,7380,7380);
INSERT INTO stanza VALUES('C50','1','我父、我神，<br/>你愛在子顯明，<br/>對此我們再來你前響應。<br/>祂作燔祭，<br/>滿足你的心意；<br/>忍受十架，<br/>使我得你歡喜。<br/>',NULL,7381,7381);
INSERT INTO stanza VALUES('C50','2','祂今率領許多弟兄歌唱，<br/>我們和聲，<br/>從心響應頌揚。<br/>當祂在此引聲向你讚美，<br/>我們靈裡共鳴，<br/>歡然跟隨。<br/>',NULL,7382,7382);
INSERT INTO stanza VALUES('C50','3','在你愛子裡面蒙了揀選，<br/>今得有分你前歡呼、<br/>頌讚；<br/>創世之前已經蒙你豫定，<br/>要我有分於你兒子生命。<br/>',NULL,7383,7383);
INSERT INTO stanza VALUES('C50','4','蒙愛眾子，<br/>全由你靈更新，<br/>有你愛子作那無窮之分；<br/>每個都有祂的一分特點，<br/>供你喜悅欣賞，<br/>直到永遠。<br/>',NULL,7384,7384);
INSERT INTO stanza VALUES('C51','1','親愛父神，<br/>我們向你歌唱，<br/>有誰比你更配我們頌揚。<br/>你今要人<br/>以靈以『真』敬拜，<br/>我們照此向你獻上感戴。<br/>',NULL,7385,7385);
INSERT INTO stanza VALUES('C51','2','所有世界是你藉子造成，<br/>萬有也都由祂大能托撐；<br/>但我卻是在你愛子裡面，<br/>與你親近，<br/>敬拜何其甘甜。<br/>',NULL,7386,7386);
INSERT INTO stanza VALUES('C51','3','祂今在這蒙福範圍領唱，<br/>在你召會唱詩向你頌揚；<br/>何等歡樂，<br/>祂有弟兄隨同，<br/>與祂同享自由，<br/>向你歌頌。<br/>',NULL,7387,7387);
INSERT INTO stanza VALUES('C51','4','我們和祂在此同聲歌唱，<br/>哦父，<br/>使你滿足、供你欣賞；<br/>在你愛子所領讚美之中，<br/>你可安居，<br/>永遠享受稱頌。<br/>『真』指基督。<br/>',NULL,7388,7388);
INSERT INTO stanza VALUES('C52','1','靠著我們救主流血作祭，<br/>父阿，<br/>我們前來一同就你；<br/>距離已去，<br/>藉恩已得自由，<br/>前來敬拜向你讚美、<br/>歌謳。<br/>',NULL,7389,7389);
INSERT INTO stanza VALUES('C52','2','哦父，<br/>我們願在你前獻上<br/>你的愛子之名所有馨香；<br/>藉著祂死為我所得恩典，<br/>在此憑信我們將祂觀瞻。<br/>',NULL,7390,7390);
INSERT INTO stanza VALUES('C52','3','你的喜樂我今與祂同享，<br/>在祂裡面我心因你歡暢；<br/>萬人之上，<br/>祂比美者更美，<br/>祂的榮耀永不衰落敗褪。<br/>',NULL,7391,7391);
INSERT INTO stanza VALUES('C52','4','在你座前我們俯伏仰望，<br/>憑信看見你愛所有對象；<br/>祂今在此率領許多弟兄－你的眾子，<br/>同聲向你歌頌。<br/>',NULL,7392,7392);
INSERT INTO stanza VALUES('C53','1','哦主，你是神的活道，<br/>太初與神同在；<br/>你是神的榮耀發表，<br/>將神表明出來。<br/>',NULL,7393,7393);
INSERT INTO stanza VALUES('C53','chorus','讚美你是神的活道，<br/>將神完全發表！<br/>神的本性、神的榮耀，<br/>藉你全都揭曉！<br/>',NULL,7394,7394);
INSERT INTO stanza VALUES('C53','2','諸天述說神的榮耀，<br/>萬有也在發聲；<br/>神能、神性，原難知曉，<br/>藉你創造顯明。<br/>',NULL,7395,7395);
INSERT INTO stanza VALUES('C53','3','神的話語豐富、奧妙，<br/>全是你的見證；<br/>你在其中得著發表，<br/>為要將神說明。<br/>',NULL,7396,7396);
INSERT INTO stanza VALUES('C53','4','你這活道成為肉身，<br/>住在人的中間；<br/>你的一切行事、為人，<br/>就是神的彰顯。<br/>',NULL,7397,7397);
INSERT INTO stanza VALUES('C53','5','你這活道乃是生命，<br/>也是生命之光；<br/>你作生命發光照明，<br/>使神得著顯彰。<br/>',NULL,7398,7398);
INSERT INTO stanza VALUES('C53','6','將來你要施行審判，<br/>表明神的公義；<br/>也是叫神得著彰顯，<br/>將神表明無遺。<br/>',NULL,7399,7399);
INSERT INTO stanza VALUES('C53','7','哦主，你是神的顯出，<br/>你是顯出的神；<br/>你已將神向人宣佈，<br/>使神不再自隱。<br/>',NULL,7400,7400);
INSERT INTO stanza VALUES('C54','1','哦主，你是永遠之道，<br/>父的獨生愛子，<br/>是神給人看見聽到，<br/>天的可愛之子。<br/>哦，神兒子，你何神聖，<br/>在你我見神的豐盛。<br/>',NULL,7401,7401);
INSERT INTO stanza VALUES('C54','2','在你，父的榮耀照明，<br/>顯得無比完全；<br/>你有神的豐滿神性，<br/>神聖直到永遠。<br/>哦，神兒子，你何神聖，<br/>在你我見神的豐盛。<br/>',NULL,7402,7402);
INSERT INTO stanza VALUES('C54','3','你是無限之神的像，<br/>神的本質包藏；<br/>你是非造之光的亮，<br/>神的心情顯彰。<br/>哦，神兒子，你何神聖，<br/>在你我見神的豐盛。<br/>',NULL,7403,7403);
INSERT INTO stanza VALUES('C54','4','但你名的最高奧祕，<br/>即使天使難曉；<br/>你的奧妙神聖自己，<br/>惟有父神知道。<br/>哦，神兒子，你何神聖，<br/>在你我見神的豐盛。<br/>',NULL,7404,7404);
INSERT INTO stanza VALUES('C54','5','在那蒙福宇宙之中，<br/>中心在你所是；<br/>永遠都要如此稱頌<br/>天的可愛之子：<br/>哦， 神兒子，你何神聖，<br/>在你我見神的豐盛。<br/>',NULL,7405,7405);
INSERT INTO stanza VALUES('C55','1','哦主，你是神的活話，<br/>又是神的兒子；<br/>你是神的真實形像，<br/>有神榮耀樣式。<br/>',NULL,7406,7406);
INSERT INTO stanza VALUES('C55','2','神的本性一切豐滿，<br/>全都住你裡面；<br/>你是神的具體化身，<br/>藉你神得彰顯。<br/>',NULL,7407,7407);
INSERT INTO stanza VALUES('C55','3','是神榮耀所發光輝，<br/>與神原本是一；<br/>是神本體所有真像，<br/>在你神成實際。<br/>',NULL,7408,7408);
INSERT INTO stanza VALUES('C55','4','在你神是我們生命，<br/>在你神是亮光；<br/>在你我們有神性情，<br/>在你因神增長。<br/>',NULL,7409,7409);
INSERT INTO stanza VALUES('C55','5','在你神的恩典常存，<br/>在你我得著神；<br/>在你神的實際可尋，<br/>在你我看見神。<br/>',NULL,7410,7410);
INSERT INTO stanza VALUES('C55','6','在你領受神的豐滿，<br/>而且恩上加恩；<br/>在你我們與神調和，<br/>與神一切有分。<br/>',NULL,7411,7411);
INSERT INTO stanza VALUES('C55','7','哦主，我神，我敬拜你，<br/>我的一切在你；<br/>我心珍愛你的自己，<br/>永遠欣賞不已！<br/>',NULL,7412,7412);
INSERT INTO stanza VALUES('C56','1','恩主耶穌，我敬拜你，<br/>你曾成為『女人裔；』<br/>為一貞潔童女所生，<br/>使神與人成為一。<br/>有了我們人的性情，<br/>以人身分毀古蛇；<br/>藉著十架擊傷他頭，<br/>為神計畫勝利得。<br/>',NULL,7413,7413);
INSERT INTO stanza VALUES('C56','chorus','主，我見你榮耀，<br/>在人美麗顯照，<br/>神性榮美顯於人性，<br/>配永遠稱道！<br/>',NULL,7414,7414);
INSERT INTO stanza VALUES('C56','2','道成肉身，來成為人，<br/>穿上血肉的身體；<br/>為要毀壞魔鬼、撒但，<br/>作了我們的代替。<br/>神命為你起名『耶穌，』<br/>『以馬內利』人竟稱；<br/>如此成為寶貴救主，<br/>救恩為我全作成。<br/>',NULL,7415,7415);
INSERT INTO stanza VALUES('C56','3','你被稱為『末後亞當，』<br/>也被稱為『第二人；』<br/>作新造的萬有元首，<br/>勝過舊造第一人。<br/>在這地上生活、行動，<br/>確是人子人共見；<br/>今在天上帶著人性，<br/>仍是一人顯神前。<br/>',NULL,7416,7416);
INSERT INTO stanza VALUES('C56','4','在神所定榮耀日子，<br/>恩主，你要再降臨；<br/>帶著父神豐滿榮耀，<br/>顯於人前仍是人。<br/>甚至在那審判寶座，<br/>你仍是人行審判；<br/>並且你要將這人性<br/>一直帶著到永遠。<br/>',NULL,7417,7417);
INSERT INTO stanza VALUES('C57','1','哦主，你曾成為人子，<br/>有了我們人的性情，<br/>穿上我們血肉之體，<br/>為一貞潔童女所生。<br/>',NULL,7418,7418);
INSERT INTO stanza VALUES('C57','2','虛己取了奴僕形像，<br/>行走在這艱苦塵世；<br/>嘗盡人生所有苦味，<br/>忍受苦難從無所辭。<br/>',NULL,7419,7419);
INSERT INTO stanza VALUES('C57','3','生在馬槽，作一嬰孩，<br/>長在乾地，出身寒門；<br/>勞苦工作如一木匠，<br/>終被處死像一犯人。<br/>',NULL,7420,7420);
INSERT INTO stanza VALUES('C57','4','神雖使你從死復活，<br/>你仍帶著我們人性；<br/>你雖穿上神聖形狀，<br/>仍是一人上升天庭。<br/>',NULL,7421,7421);
INSERT INTO stanza VALUES('C57','5','今在寶座掌管一切，<br/>榮耀之中仍是一人；<br/>神聖光中與神同在，<br/>以人身位滿足神心。<br/>',NULL,7422,7422);
INSERT INTO stanza VALUES('C57','6','帶著榮耀，你要回來，<br/>仍是一人顯於眾目；<br/>萬王之王、萬主之主，<br/>仍帶人性為人所睹。<br/>',NULL,7423,7423);
INSERT INTO stanza VALUES('C57','7','將來你在新天、新地，<br/>要作萬有一切中心；<br/>雖然你是神聖之主，<br/>仍帶人性永遠長存。<br/>',NULL,7424,7424);
INSERT INTO stanza VALUES('C58','1','哦，我神那施愛智慧！<br/>罪惡正盛時候，<br/>末後亞當就來爭戰，<br/>並來施行拯救。<br/>',NULL,7425,7425);
INSERT INTO stanza VALUES('C58','2','哦，我神那最智之愛！<br/>亞當雖然失敗，<br/>但祂仍要血肉之人，<br/>重新爭戰奏凱。<br/>',NULL,7426,7426);
INSERT INTO stanza VALUES('C58','3','要一比恩更高恩賜，<br/>就是神的出現，<br/>和神自己，並神本質，<br/>來將血肉提煉。<br/>',NULL,7427,7427);
INSERT INTO stanza VALUES('C58','4','哦，我神那慷慨之愛！<br/>祂來在人裡面，<br/>為人擊殺掌死仇敵，<br/>並且忍死受難。<br/>',NULL,7428,7428);
INSERT INTO stanza VALUES('C58','5','暗中在那園裡哀哭，<br/>明處十架受死，<br/>都是教導祂的弟兄，<br/>如何苦死不辭。<br/>',NULL,7429,7429);
INSERT INTO stanza VALUES('C58','6','哦主，你這神而人者，<br/>在我人性裡面，<br/>為我所作何多、何妙，<br/>配我永遠稱讚！<br/>',NULL,7430,7430);
INSERT INTO stanza VALUES('C59','1','哦，何感人的故事：<br/>神的『尊嚴、』恩典，<br/>帶著榮光的啟示，<br/>深刻耶穌面間！<br/>當我注目來觀審<br/>神這光明形像，<br/>我心驚喜又歡欣，<br/>滿了崇敬、欣賞！<br/>',NULL,7431,7431);
INSERT INTO stanza VALUES('C59','2','你有完全的人性，<br/>神性在你也顯；<br/>神的愛與人的情，<br/>神性、人性俱全；<br/>生、死、復活與升天，<br/>顯明是神而人，<br/>在地卑微人出現，<br/>在天萬有之神。<br/>',NULL,7432,7432);
INSERT INTO stanza VALUES('C59','3','榮耀無玷的光輝！<br/>永遠放光的臉！<br/>豐富難測的作為<br/>藉恩將我改變！<br/>不久與你全相像，<br/>眼睛被愛點亮，<br/>在你人子的身上，<br/>見神敞開面光。<br/>',NULL,7433,7433);
INSERT INTO stanza VALUES('C60','1','耶穌！我愛這名，<br/>耶穌我主！<br/>耶穌！遠超萬名，<br/>耶穌我主！<br/>主，你作我一切，<br/>你外我無基業，<br/>有你我無所缺，<br/>耶穌我主！<br/>',NULL,7434,7434);
INSERT INTO stanza VALUES('C60','2','你曾成為人子，<br/>耶穌我主！<br/>你曾替我受死，<br/>耶穌我主！<br/>你愛真是殊優，<br/>遠超人世所有，<br/>救恩因你成就，<br/>耶穌我主！<br/>',NULL,7435,7435);
INSERT INTO stanza VALUES('C60','3','我惟因你得生，<br/>耶穌我主！<br/>我惟靠你得勝，<br/>耶穌我主！<br/>我們還怕甚麼<br/>憂慮、苦難、鬼魔！<br/>因為有你相佐，<br/>耶穌我主！<br/>',NULL,7436,7436);
INSERT INTO stanza VALUES('C60','4','不久你要再臨，<br/>耶穌我主！<br/>我們快要歡欣，<br/>耶穌我主！<br/>那時我們見你，<br/>我們就要像你，<br/>並要永遠偕你，<br/>耶穌我主！<br/>',NULL,7437,7437);
INSERT INTO stanza VALUES('C61','1','恩主耶穌，<br/>你名『我是，』<br/>寶貴聖名，豐美、真實！<br/>我所需要全都在此－全在你所是！<br/>',NULL,7438,7438);
INSERT INTO stanza VALUES('C61','2','你是聖子、又是聖父，<br/>是神隱藏、是神顯出，<br/>且成那靈與我同處，<br/>使我享豐富。<br/>',NULL,7439,7439);
INSERT INTO stanza VALUES('C61','3','你是帳幕、你是聖殿，<br/>給神安居，將神彰顯，<br/>使我在你與神相見，<br/>得享神肥甘。<br/>',NULL,7440,7440);
INSERT INTO stanza VALUES('C61','4','你是羔羊、你是新郎，<br/>為娶新婦，將罪擔當，<br/>為我捨己、為我受傷，<br/>使我得安康。<br/>',NULL,7441,7441);
INSERT INTO stanza VALUES('C61','5','你是智慧、你是道路，<br/>照神旨意，為我部署，<br/>使我蒙恩，使我受福，<br/>納我入正途。<br/>',NULL,7442,7442);
INSERT INTO stanza VALUES('C61','6','你是公義、你是聖潔，<br/>與神相合，為神所悅，<br/>使我稱義，使我聖別，<br/>能與神和諧。<br/>',NULL,7443,7443);
INSERT INTO stanza VALUES('C61','7','你是生命、你是亮光，<br/>消除黑暗，吞滅死亡，<br/>使我復生，使我明亮，<br/>使我得釋放。<br/>',NULL,7444,7444);
INSERT INTO stanza VALUES('C61','8','你是復活、你是大能，<br/>衝破墳墓，勝過幽冥，<br/>使我剛強，使我得勝，<br/>使我占上風。<br/>',NULL,7445,7445);
INSERT INTO stanza VALUES('C61','9','你是靈糧、你是活水，<br/>為作供應，甘願降卑，<br/>解我飢渴，甦我困憊，<br/>作了我美味。<br/>',NULL,7446,7446);
INSERT INTO stanza VALUES('C61','10','你是牧人、你是醫生，<br/>為我捨命，醫我疾病，<br/>保養、顧惜、<br/>安慰、引領，<br/>凡事都照應。<br/>',NULL,7447,7447);
INSERT INTO stanza VALUES('C61','11','你是祭司、你是君王，<br/>將我帶進神的面光；<br/>你的權柄我得分享，<br/>地位何高尚！<br/>',NULL,7448,7448);
INSERT INTO stanza VALUES('C61','12','你是救贖、你是盼望，<br/>還要將我改變形狀，<br/>使我完全與你相像，<br/>將你來顯彰。<br/>',NULL,7449,7449);
INSERT INTO stanza VALUES('C61','13','還是榮耀、喜樂、平安、<br/>真理、恩典、<br/>活道、靈磐、<br/>日頭、盾牌、<br/>居所、靠山，<br/>何人能盡言！<br/>',NULL,7450,7450);
INSERT INTO stanza VALUES('C61','14','你的所是永遠、無限、<br/>長、闊、高、深、<br/>豐滿、完全！<br/>豈只應付我的缺欠！<br/>且從我溢漫！<br/>',NULL,7451,7451);
INSERT INTO stanza VALUES('C62','1','主耶穌，我愛你名！<br/>謙卑俯伏在你前；<br/>榮耀、權柄、<br/>頌讚、尊敬，<br/>我活時必向你獻；<br/>向你高歌歌聲沛，<br/>心口同聲來歌唱，<br/>我魂感佩，因你是配，<br/>你的美麗真非常！<br/>',NULL,7452,7452);
INSERT INTO stanza VALUES('C62','2','主耶穌，我愛你名！<br/>未有天地未有時，<br/>神愛無境，就已顯明，<br/>要施恩典救亡世；<br/>這愛真是永遠愛！<br/>墮落如我也眷顧！<br/>愛叫你來，為我負債，<br/>使我成為你珍物。<br/>',NULL,7453,7453);
INSERT INTO stanza VALUES('C62','3','主耶穌，我愛你名！<br/>你的降生何寒微！<br/>你的慈心滿有恩情，<br/>你的道路孤且卑；<br/>我的痛苦你替背，<br/>我的荊冕你替戴，<br/>我的禍杯你替嘗備，<br/>常經憂患是為愛。<br/>',NULL,7454,7454);
INSERT INTO stanza VALUES('C62','4','主耶穌，我愛你名！<br/>『神的羔羊』何清潔！<br/>你被豫定為我受刑，<br/>流出寶血洗罪孽；<br/>現在你坐高天上，<br/>尊貴、榮耀為冠冕；<br/>你打勝仗，我得釋放；<br/>阿利路亞主名甜！<br/>',NULL,7455,7455);
INSERT INTO stanza VALUES('C63','1','耶穌！你名何等芬芳，<br/>在蒙恩人身上！<br/>得救罪人，心裡所念，<br/>無一像你這甜。<br/>',NULL,7456,7456);
INSERT INTO stanza VALUES('C63','2','神來為人，所表恩義，<br/>你名包含無遺，<br/>天上生命、世間生活，<br/>神在你身顯著！<br/>',NULL,7457,7457);
INSERT INTO stanza VALUES('C63','3','『耶穌』這名表明大愛，<br/>如何忍受禍害，<br/>這名說出我們零丁，<br/>天上如何同情。<br/>',NULL,7458,7458);
INSERT INTO stanza VALUES('C63','4','耶穌無罪，為我成罪，<br/>使我蒙恩受惠；<br/>你捨你身，來得我心，<br/>今後你重我輕。<br/>',NULL,7459,7459);
INSERT INTO stanza VALUES('C63','5','題起你名，我心即伏，<br/>敬拜救主我主；<br/>你愛救我，我今歸你－這超萬人的你！<br/>',NULL,7460,7460);
INSERT INTO stanza VALUES('C64','1','我主，你名<br/>稱為『耶穌，』<br/>可愛之名何奇妙；<br/>你由聖潔童女而生，<br/>取了人性與人貌。<br/>你是我『耶和華救主，』<br/>拯救我們脫罪惡；<br/>當我接受你作救主，<br/>神聖生命我得著。<br/>',NULL,7461,7461);
INSERT INTO stanza VALUES('C64','2','你名也被稱為『基督，』<br/>榮耀職事的名稱；<br/>你確是神的受膏者，<br/>神從永遠所選定。<br/>主，你是神的彌賽亞，<br/>神已因愛立了你，<br/>要你彰顯祂的榮耀，<br/>並且完成祂心意。<br/>',NULL,7462,7462);
INSERT INTO stanza VALUES('C64','3','你也稱為『以馬內利，』<br/>你是『神與人同在；』<br/>藉恩神與人性調和，<br/>永遠不能再分開。<br/>神在肉身得著彰顯，<br/>滿有真理和恩典；<br/>在你我見神的榮耀，<br/>並且得著神豐滿。<br/>',NULL,7463,7463);
INSERT INTO stanza VALUES('C64','4','哦主，我們珍愛你名，<br/>你名所示何豐富；<br/>你名價值和其甘美，<br/>因愛永遠要守住。<br/>寶貴救主，榮耀基督，<br/>敬拜、愛戴全歸你；<br/>親愛救主、以馬內利，<br/>我要高舉永無已！<br/>',NULL,7464,7464);
INSERT INTO stanza VALUES('C65','1','耶穌大名，榮耀、有能，<br/>是我投靠、是我倚；<br/>『坐在天上，』<br/>我今讚美，<br/>你名就是我勝利。<br/>',NULL,7465,7465);
INSERT INTO stanza VALUES('C65','2','可頌耶穌、大能救主，<br/>我所需要在你名；<br/>只要呼吸耶穌這名，<br/>就是飲於你生命。<br/>',NULL,7466,7466);
INSERT INTO stanza VALUES('C65','3','耶穌大名，榮耀、有能，<br/>天地宣告牠大能；<br/>然而只有蒙恩罪人，<br/>知道這名的豐盛！<br/>',NULL,7467,7467);
INSERT INTO stanza VALUES('C65','4','耶穌！耶穌！最貴之名，<br/>戰時兵器、病時膏；<br/>在你名裡生活爭戰，<br/>就有喜樂和榮耀。<br/>',NULL,7468,7468);
INSERT INTO stanza VALUES('C66','1','耶穌，這名甜美、芬芳，<br/>慰我痛苦心情；<br/>我心歡樂，我口歌唱<br/>這個寶貴的名。<br/>',NULL,7469,7469);
INSERT INTO stanza VALUES('C66','chorus','美哉、妙哉，神的愛子<br/>作我寶貴救主；<br/>為我降生，為我受死，<br/>流血將我救贖。<br/>',NULL,7470,7470);
INSERT INTO stanza VALUES('C66','2','耶穌原有神的形像，<br/>竟來成為人子，<br/>虛己取了奴僕形狀，<br/>使我作神後嗣。<br/>',NULL,7471,7471);
INSERT INTO stanza VALUES('C66','3','耶穌乃是生命、亮光，<br/>乃是真理、道路；<br/>今在我心作主、作王，<br/>將我引導、安撫。<br/>',NULL,7472,7472);
INSERT INTO stanza VALUES('C66','4','寶貴救主遠勝奇珍，<br/>時刻滿足我心，<br/>解我愁苦、消我煩悶，<br/>永遠與我相親。<br/>',NULL,7473,7473);
INSERT INTO stanza VALUES('C66','5','寶貴救主不久再臨，<br/>接我與祂同在，<br/>使我賤體變成榮身，<br/>安息直到萬代。<br/>',NULL,7474,7474);
INSERT INTO stanza VALUES('C66','chorus','榮哉、樂哉，耶穌我主，<br/>永是我的榮耀；<br/>榮耀之名乃是耶穌，<br/>我要永遠稱道。<br/>',NULL,7475,7475);
INSERT INTO stanza VALUES('C67','1','大地無名甜至如此！<br/>名甜至此高天無！<br/>祂離榮耀來世界時，<br/>神將這名賜救主。<br/>',NULL,7476,7476);
INSERT INTO stanza VALUES('C67','chorus','我們愛唱：基督神子，<br/>並且稱祂為耶穌；<br/>因為從來未有文字，<br/>這寶、這甜，<br/>如『耶穌。』<br/>',NULL,7477,7477);
INSERT INTO stanza VALUES('C67','2','當人將祂掛在木上，<br/>他們同時掛這名，<br/>好叫天下都能欣賞<br/>我們愛祂的究竟。<br/>',NULL,7478,7478);
INSERT INTO stanza VALUES('C67','3','當祂上升高坐寶座，<br/>神將這名賞賜祂，<br/>萬膝跪拜、萬口唱和，<br/>天上地下都迎駕！<br/>',NULL,7479,7479);
INSERT INTO stanza VALUES('C67','4','主，藉你這名的無比，<br/>恩典不至漸疲倦；<br/>今日、昨天，你不更易，<br/>你是一樣到永遠！<br/>',NULL,7480,7480);
INSERT INTO stanza VALUES('C68','1','被殺羔羊，耶穌基督，<br/>被神高舉天上；<br/>罪人朋友，榮耀救主，<br/>配得永遠頌揚。<br/>',NULL,7481,7481);
INSERT INTO stanza VALUES('C68','chorus','頌讚主尊名，<br/>頌讚主尊名，<br/>頌讚、榮耀，歸主尊名。<br/>阿利路亞！阿利路亞！<br/>頌讚、榮耀，歸主尊名。<br/>阿利路亞！阿利路亞！<br/>頌讚、榮耀，歸主尊名。<br/>',NULL,7482,7482);
INSERT INTO stanza VALUES('C68','2','超乎萬名之上的名，<br/>已經賜給耶穌；<br/>天上、地上一切眾生，<br/>無不稱祂為主。<br/>',NULL,7483,7483);
INSERT INTO stanza VALUES('C68','3','天使下拜，天軍俯伏，<br/>萬有也都屈膝，<br/>敬拜救主，高舉基督，<br/>頌讚羔羊不已。<br/>',NULL,7484,7484);
INSERT INTO stanza VALUES('C68','4','蒙恩罪人也要歡呼，<br/>同聲頌讚救主：<br/>為我流血，將我救贖，<br/>使我永遠得福。<br/>',NULL,7485,7485);
INSERT INTO stanza VALUES('C68','5','但願權柄、智慧、豐富、<br/>尊貴、榮耀、王權，<br/>歸給羔羊，救主基督，<br/>直到永永遠遠！<br/>',NULL,7486,7486);
INSERT INTO stanza VALUES('C69','1','耶穌這名超乎萬名，<br/>天上、地上、陰間：<br/>天使和人無不尊敬，<br/>魔鬼懼怕、逃竄。<br/>',NULL,7487,7487);
INSERT INTO stanza VALUES('C69','2','耶穌這名可親、可愛，<br/>賜給罪人之名；<br/>定罪、懼怕，為我趕開，<br/>帶來天上安寧。<br/>',NULL,7488,7488);
INSERT INTO stanza VALUES('C69','3','耶穌打碎罪囚枷鎖，<br/>打傷撒但的頭；<br/>祂用大能吞滅軟弱，<br/>祂用生命拯救。<br/>',NULL,7489,7489);
INSERT INTO stanza VALUES('C69','4','但願世人都能嘗到<br/>祂的豐富恩典！<br/>都能享受祂的懷抱，<br/>投在祂的胸間。<br/>',NULL,7490,7490);
INSERT INTO stanza VALUES('C69','5','耶穌這名永遠可靠，<br/>彀我度過今生；<br/>直到永世可愛、可寶，<br/>永遠是我見證。<br/>',NULL,7491,7491);
INSERT INTO stanza VALUES('C70','1','耶穌這名何其甘甜，<br/>猶如音樂我愛稱讚，<br/>牠使我樂豐滿完全，<br/>耶穌寶貴之名。<br/>',NULL,7492,7492);
INSERT INTO stanza VALUES('C70','chorus','耶穌！這名何甘甜，<br/>耶穌！天天不改變；<br/>耶穌！聖徒當稱讚<br/>牠的價值到永遠。<br/>',NULL,7493,7493);
INSERT INTO stanza VALUES('C70','2','我愛那愛我者之名，<br/>祂知我苦，分擔、同情，<br/>命令憂懼從我隱形，<br/>我愛耶穌之名。<br/>',NULL,7494,7494);
INSERT INTO stanza VALUES('C70','3','這名迷人，我愛聽見，<br/>一聽我心不禁狂歡，<br/>其樂將我眼淚擦乾；<br/>高舉耶穌之名。<br/>',NULL,7495,7495);
INSERT INTO stanza VALUES('C70','4','無人話語能以盡言<br/>我愛之名何其甘甜；<br/>願人將牠永遠稱讚，<br/>稱讚耶穌之名。<br/>',NULL,7496,7496);
INSERT INTO stanza VALUES('C71','1','我們知你已復起，<br/>死亡中的初熟；<br/>我們見你已被提，<br/>榮耀元首基督。<br/>蒙恩得與你相交，<br/>心、思都能無忌<br/>來想你的眾榮耀，<br/>因已與你合一。<br/>',NULL,7497,7497);
INSERT INTO stanza VALUES('C71','2','你是萬有的元首，<br/>你有最大權柄；<br/>你是以『人』升父右，<br/>你有最高的名！<br/>加略已顯最高能，<br/>也顯你最高愛；<br/>你愛已完全得勝，<br/>痛苦最暗殘害。<br/>',NULL,7498,7498);
INSERT INTO stanza VALUES('C71','3','不久萬有寶珍你，<br/>萬有讚美你名；<br/>不久萬有承認你，<br/>向你表示歡迎。<br/>現今只有我們能<br/>認識你的大愛；<br/>能嘗你愛滿衷情，<br/>向你讚美不迨。<br/>',NULL,7499,7499);
INSERT INTO stanza VALUES('C71','4','你名更比萬名彰，<br/>你賜越乎眾賜，<br/>你愛高於萬愛上，<br/>永不、永不中止。<br/>我們歡樂來稱道，<br/>因已合一不改；<br/>永遠乃是你榮耀，<br/>永遠乃是你愛。<br/>',NULL,7500,7500);
INSERT INTO stanza VALUES('C72','1','主，你根源在亙古，<br/>在那無始的太初！<br/>因你就是永遠父，<br/>就是自有永有主！<br/>',NULL,7501,7501);
INSERT INTO stanza VALUES('C72','2','你雖出生人世間，<br/>卻是與神同永遠！<br/>與神同樣的完滿，<br/>與神同樣的無限！<br/>',NULL,7502,7502);
INSERT INTO stanza VALUES('C72','3','你乃與神同根源，<br/>早過萬有並地天！<br/>沒有先者比你先，<br/>沒有前者比你前！<br/>',NULL,7503,7503);
INSERT INTO stanza VALUES('C72','4','永不改變永不舊，<br/>你的年數無盡休！<br/>沒有久者比你久，<br/>沒有後者比你後！<br/>',NULL,7504,7504);
INSERT INTO stanza VALUES('C72','5','你與父神無所差，<br/>與神一樣無可加！<br/>所以也是阿拉法，<br/>並且也是俄梅嘎！<br/>',NULL,7505,7505);
INSERT INTO stanza VALUES('C72','6','我們讚美你永遠，<br/>我們稱頌你完全！<br/>賞識你是何豐滿，<br/>希奇你是何無限！<br/>',NULL,7506,7506);
INSERT INTO stanza VALUES('C73','1','主，接納我們的詩歌，<br/>雖然聲音頂柔弱；<br/>我們述說你的恩篤，<br/>因你是我們救主。<br/>',NULL,7507,7507);
INSERT INTO stanza VALUES('C73','2','因你捨去榮耀、豐富，<br/>你的信徒纔得福；<br/>你變貧窮，叫你信徒<br/>因你享榮耀、豐富。<br/>',NULL,7508,7508);
INSERT INTO stanza VALUES('C73','3','天上有何使你心厭？<br/>世界有何使你羨？<br/>因而你就離天臨世，<br/>孤單、淒涼直到死？<br/>',NULL,7509,7509);
INSERT INTO stanza VALUES('C73','4','你在天上何等榮耀！<br/>你在世上何蕭條！<br/>你早已知此行艱難，<br/>只因愛我竟甘願。<br/>',NULL,7510,7510);
INSERT INTO stanza VALUES('C73','5','當我想到你的良善，<br/>就不禁又喜又慚！<br/>喜，因你能這樣愛好；<br/>慚，因我這樣還報。<br/>',NULL,7511,7511);
INSERT INTO stanza VALUES('C73','6','但我們望那日快到，<br/>脫盡所有的阻撓；<br/>那時我們進榮耀裡，<br/>要照本分服事你。<br/>',NULL,7512,7512);
INSERT INTO stanza VALUES('C73','7','現今我們等在這裡，<br/>因這盼望受策勵；<br/>主，使我們活著為你，<br/>直到你前同聚集。<br/>',NULL,7513,7513);
INSERT INTO stanza VALUES('C74','1','聽阿，天使讚高聲，<br/>頌揚救主今誕生！<br/>『榮耀在天歸與神，<br/>平安在地臨及人。』<br/>興起！地上眾生靈，<br/>響應天上讚美聲；<br/>天唱地和樂歡騰，<br/>基督誕生大衛城。<br/>天唱地和樂歡騰，<br/>基督誕生大衛城。<br/>',NULL,7514,7514);
INSERT INTO stanza VALUES('C74','2','基督本有神形像，<br/>基督原居神榮光，<br/>竟在末世從天降，<br/>生於童女成人狀；<br/>神性穿上血肉體，<br/>道成肉身何奧祕，<br/>甘願作人同人住，<br/>以馬內利是耶穌。<br/>甘願作人同人住，<br/>以馬內利是耶穌。<br/>',NULL,7515,7515);
INSERT INTO stanza VALUES('C74','3','歡迎，天來和平王！<br/>歡迎，公義的太陽！<br/>帶來生命與亮光，<br/>使人復活，醫人傷；<br/>虛己，撇下祂榮光，<br/>降生救人免死亡，<br/>降生使人得重生，<br/>降生使人能高升。<br/>降生使人得重生，<br/>降生使人能高升。<br/>',NULL,7516,7516);
INSERT INTO stanza VALUES('C74','4','萬國『羨慕，』<br/>萬民『望，』<br/>願你安家我心房；<br/>女人後裔－得勝者，<br/>在我裡面毀古蛇；<br/>亞當舊樣全除盡，<br/>你的形像將我印；<br/>末後亞當的豐盛，<br/>使我變成你榮形。<br/>末後亞當的豐盛，<br/>使我變成你榮形。<br/>『羨慕』意即所羨慕的那位，指基督，引自哈該書二章七節小字。<br/>『望』指基督是萬民的盼望。<br/>',NULL,7517,7517);
INSERT INTO stanza VALUES('C75','1','永活的故事，<br/>撇下榮耀降世，<br/>神來作我救主，<br/>成人，名叫耶穌。<br/>生在馬槽裡，<br/>像根出於乾地，<br/>成為憂患的人，<br/>常受痛苦。<br/>',NULL,7518,7518);
INSERT INTO stanza VALUES('C75','chorus','我何等愛祂！<br/>何等敬拜祂！<br/>我氣，我日光，<br/>我的一切！<br/>偉大創造主，<br/>作了我救主，<br/>帶來神豐滿，取用不竭。<br/>',NULL,7519,7519);
INSERT INTO stanza VALUES('C75','2','何等的低就，<br/>為要使我得救；<br/>使那蔭中喪亡，<br/>無一至於失望；<br/>神何柔而愛，<br/>撇開祂的光彩，<br/>降卑來苦、來愛、<br/>來救喪亡。<br/>',NULL,7520,7520);
INSERT INTO stanza VALUES('C75','3','絲毫不勉強，<br/>祂將血肉穿上，<br/>取了人的形狀，<br/>將神計畫顯彰。<br/>榮耀的奧祕，<br/>神人竟成為一；<br/>在你，神的一切<br/>我全得享。<br/>',NULL,7521,7521);
INSERT INTO stanza VALUES('C76','1','主，你溫柔所留印記，<br/>照耀神聖，何其美麗！<br/>在你所行孤單路中，<br/>你愛留下希奇行蹤。<br/>',NULL,7522,7522);
INSERT INTO stanza VALUES('C76','2','你這人子，光中之光，<br/>有誰像你柔細、明亮？<br/>有誰像你如此忍耐，<br/>經過這一艱苦塵埃？<br/>',NULL,7523,7523);
INSERT INTO stanza VALUES('C76','3','被人辱罵向不還口，<br/>遭受苦害從無怨尤；<br/>何其和善、何其謙卑，<br/>謙和之中又何榮美！<br/>',NULL,7524,7524);
INSERT INTO stanza VALUES('C76','4','為使罪囚得著自由，<br/>囚犯之死甘願忍受；<br/>藉此你愛顯明無留，<br/>憐憫隨著你血湧流。<br/>',NULL,7525,7525);
INSERT INTO stanza VALUES('C76','5','希奇的主，我何願望：<br/>更多模成你的形像，<br/>學你式微，像你謙卑，<br/>你的腳蹤終生跟隨。<br/>',NULL,7526,7526);
INSERT INTO stanza VALUES('C77','1','你是至高、榮耀的神，<br/>竟肯降卑成為肉身，<br/>作了一個式微的人，<br/>主阿，我記念你！<br/>',NULL,7527,7527);
INSERT INTO stanza VALUES('C77','2','你將一切神性榮耀，<br/>全用肉身幔子遮罩，<br/>顯於外者不過枯槁，<br/>主阿，我記念你！<br/>',NULL,7528,7528);
INSERT INTO stanza VALUES('C77','3','你乃像根出於乾地，<br/>多受痛苦，常經憂悒，<br/>被人藐視，受人厭棄，<br/>主阿，我記念你！<br/>',NULL,7529,7529);
INSERT INTO stanza VALUES('C77','4','你的心裡謙卑、溫柔，<br/>任何遭遇都肯接受，<br/>對神、對人從無怨尤，<br/>主阿，我記念你！<br/>',NULL,7530,7530);
INSERT INTO stanza VALUES('C77','5','你的為人甜美、柔細、<br/>各方均平、不偏不倚，<br/>在神眼中猶如素祭，<br/>主阿，我記念你！<br/>',NULL,7531,7531);
INSERT INTO stanza VALUES('C77','6','神的旨意你所顧念，<br/>從未接受撒但欺騙，<br/>無人像你忠誠、完全，<br/>主阿，我記念你！<br/>',NULL,7532,7532);
INSERT INTO stanza VALUES('C77','7','為著順服神的旨意，<br/>你竟甘願走到死地，<br/>且在十架捨了自己，<br/>主阿，我記念你！<br/>',NULL,7533,7533);
INSERT INTO stanza VALUES('C77','8','父神因此將你升高，<br/>使你得著尊貴、榮耀，<br/>天地一切無不拜朝，<br/>主阿，我敬拜你！<br/>',NULL,7534,7534);
INSERT INTO stanza VALUES('C78','1','你在地上所有行徑，<br/>何其仁慈、美麗！<br/>你在人性不凡生平，<br/>令人歎賞、驚奇！<br/>',NULL,7535,7535);
INSERT INTO stanza VALUES('C78','2','你在艱苦歷程顯出<br/>何等忍耐的愛！<br/>艱苦至死亦所不顧，<br/>忍、愛，誰能比賽！<br/>',NULL,7536,7536);
INSERT INTO stanza VALUES('C78','3','你心受創，重負難減，<br/>常是憂患重重，<br/>然而從無不美怨言，<br/>出你緘默口中。<br/>',NULL,7537,7537);
INSERT INTO stanza VALUES('C78','4','敵者妒恨，拒者辱罵，<br/>從者顯為不忠，<br/>你仍不煩，寬赦有加，<br/>你心惟愛是從。<br/>',NULL,7538,7538);
INSERT INTO stanza VALUES('C78','5','哦！主，在地你的生平，<br/>各方真如素祭：<br/>柔細、香甜、<br/>完全、均衡，<br/>神、人共賞不已！<br/>',NULL,7539,7539);
INSERT INTO stanza VALUES('C79','1','哦主，當我們想到你<br/>在世所歷路程：<br/>（你以恩愛對待群黎，<br/>你以忠誠對神。<br/>',NULL,7540,7540);
INSERT INTO stanza VALUES('C79','2','你愛雖然被人辜負，<br/>顯為比死更強；<br/>刺你的槍，不過引出<br/>血水，洗人天良。<br/>',NULL,7541,7541);
INSERT INTO stanza VALUES('C79','3','你雖自己常經憂患，<br/>你卻到處行善；<br/>雖然你的路途艱難，<br/>你卻不想怨歎。<br/>',NULL,7542,7542);
INSERT INTO stanza VALUES('C79','4','四圍不忠，你卻赤忠；<br/>黑暗，你卻光明。<br/>父的喜樂，你心所重，<br/>從未違祂命令。<br/>',NULL,7543,7543);
INSERT INTO stanza VALUES('C79','5','不因撒但詭計搖動，<br/>不顧苦難、損失；<br/>你的行徑，無人同情，<br/>孤單一直到死。）<br/>',NULL,7544,7544);
INSERT INTO stanza VALUES('C79','6','我們不禁奇你謙卑，<br/>盼望能以像你；<br/>主，我們願學你式微，<br/>因這裡有安息。<br/>',NULL,7545,7545);
INSERT INTO stanza VALUES('C80','1','我今俯伏，生命的王，<br/>奉獻榮耀於你；<br/>惟恐我忘你的受創，<br/>領我去髑髏地。<br/>',NULL,7546,7546);
INSERT INTO stanza VALUES('C80','chorus','惟恐我忘客西馬尼，<br/>惟恐我忘你心憂急，<br/>惟恐我忘你愛無極，<br/>領我去髑髏地。<br/>',NULL,7547,7547);
INSERT INTO stanza VALUES('C80','2','何處是你被埋墳墓？<br/>讓我前去哀悼；<br/>天使是在何處守護？<br/>當你息勞睡倒。<br/>',NULL,7548,7548);
INSERT INTO stanza VALUES('C80','3','讓我效法馬利亞女，<br/>前來向你獻禮；<br/>請示空墓是在何許，<br/>領我去髑髏地。<br/>',NULL,7549,7549);
INSERT INTO stanza VALUES('C80','4','使我甘心天天為你<br/>背起我十字架，<br/>嘗你苦杯，我也願意，<br/>因你為我被殺。<br/>',NULL,7550,7550);
INSERT INTO stanza VALUES('C80','5','你願得著所有的人，<br/>我求同此心意，<br/>求用聖火潔我嘴脣，<br/>來說你髑髏地。<br/>',NULL,7551,7551);
INSERT INTO stanza VALUES('C81','1','耶穌！永遠生命之源！<br/>耶穌！我氣息之始！<br/>你已勝過陰府黑暗，<br/>藉著忍辱與受死。<br/>你曾經過火熱、水深，<br/>屈尊為我成功救恩：<br/>千千萬萬的讚美，<br/>榮耀救主，惟你配！<br/>千千萬萬的讚美，<br/>榮耀救主，惟你配！<br/>',NULL,7552,7552);
INSERT INTO stanza VALUES('C81','2','神的兒子，你曾忍受<br/>譏誚、妒恨與苦害！<br/>榮耀的王，為我愆尤，<br/>荊棘冠冕你竟戴；<br/>受死為要將我救援，<br/>使我脫離罪的鎖鍊：<br/>千千萬萬的讚美，<br/>寶貴救主，惟你配！<br/>',NULL,7553,7553);
INSERT INTO stanza VALUES('C81','3','人所堆在你身羞辱，<br/>你全無聲的忍受；<br/>甚至忍受死的痛苦，<br/>為使救贖得成就。<br/>你的降卑令人驚奇，<br/>竟肯來到受死之地：<br/>千千萬萬的讚美，<br/>寶貴救主，惟你配！<br/>',NULL,7554,7554);
INSERT INTO stanza VALUES('C81','4','因著你曾降卑塵埃，<br/>因著你死使我生，<br/>心中讚美、靈裡敬拜，<br/>救主，全都向你呈。<br/>所有憂患你已擔當，<br/>所有祝福我今得享：<br/>這要成為我詩題，<br/>永遠讚美你不已。<br/>',NULL,7555,7555);
INSERT INTO stanza VALUES('C82','1','哦，滿了傷痕的頭，<br/>滿了痛苦、誶詬，<br/>受盡萬般的試煉，<br/>又戴荊棘冠冕；<br/>這頭今日已得榮，<br/>已得聖徒歌誦，<br/>可憐當日受死傷，<br/>在加略木頭上。<br/>',NULL,7556,7556);
INSERT INTO stanza VALUES('C82','2','你的面容原超凡，<br/>如同光明太陽，<br/>父神一見就悅納，<br/>竟受罪人唾打。<br/>主，你所受的一切，<br/>都為我們罪孽；<br/>我們債務得清付，<br/>你卻被人剪除。<br/>',NULL,7557,7557);
INSERT INTO stanza VALUES('C82','3','我們想到你痛苦，<br/>又想到你無辜，<br/>我們又滿心歡喜，<br/>又是感激無既！<br/>阿，當我們正如此<br/>念你十字架時，<br/>就是生命全捨棄，<br/>損失還算利益。<br/>',NULL,7558,7558);
INSERT INTO stanza VALUES('C82','4','我們救主－危難友，<br/>我們報恩無由！<br/>當你為我流血時，<br/>你的痛苦誰知？<br/>求你使我從今後，<br/>天天記念髑髏，<br/>直到被提進榮耀，<br/>永遠與你相交。<br/>',NULL,7559,7559);
INSERT INTO stanza VALUES('C83','1','時已夜半，晚星久沉，<br/>救主身臨橄欖山岑；<br/>客西馬尼，深夜寂靜，<br/>救主在內祈禱、儆醒。<br/>',NULL,7560,7560);
INSERT INTO stanza VALUES('C83','2','時已夜半，無人陪同，<br/>救主獨自祈禱、傷痛；<br/>雖是愛徒也都沉睡，<br/>不顧救主傷心、流淚。<br/>',NULL,7561,7561);
INSERT INTO stanza VALUES('C83','3','時已夜半，憂傷至極，<br/>救主祈禱汗如血滴；<br/>天使來臨加祂身力，<br/>證明神未將祂撇棄。<br/>',NULL,7562,7562);
INSERT INTO stanza VALUES('C83','4','時已夜半，祈禱已盡，<br/>深知苦杯不能不飲，<br/>甘願成就父神旨意，<br/>去替罪人擔罪捨己。<br/>',NULL,7563,7563);
INSERT INTO stanza VALUES('C84','1','哦主，甚麼使你頭垂？<br/>我罪壓你身上！<br/>你是站在罪人地位，<br/>將我罪孽擔當。<br/>作我祭牲，流血贖罪，<br/>使我得著釋放。<br/>',NULL,7564,7564);
INSERT INTO stanza VALUES('C84','2','我杯滿了咒詛、死亡，<br/>是我應得之分，<br/>然而其中每滴苦湯，<br/>你都為我喝盡。<br/>苦杯你愛為我盡嘗，<br/>福杯我今得飲。<br/>',NULL,7565,7565);
INSERT INTO stanza VALUES('C84','3','耶和華曾舉起祂杖，<br/>哦主，向你打下！<br/>你被你神痛苦擊傷，<br/>使我免受刑罰；<br/>你的寶血因此流淌，<br/>作了我的贖價。<br/>',NULL,7566,7566);
INSERT INTO stanza VALUES('C84','4','狂風大起，怒濤駭浪，<br/>哦主，向你進迫！<br/>你的胸懷為我抵擋，<br/>作我安息之所。<br/>因你為我受死受傷，<br/>平安我今得著。<br/>',NULL,7567,7567);
INSERT INTO stanza VALUES('C84','5','耶和華曾吩咐祂刀，<br/>哦主，向你興起！<br/>牠的殘酷火刃閃耀，<br/>須將你血飲吸；<br/>既已滿足神之所要，<br/>牠的要求遂息。<br/>',NULL,7568,7568);
INSERT INTO stanza VALUES('C84','6','哦主，你曾為我受死，<br/>我也在你死了；<br/>你已復活，將我開釋，<br/>今在我裡活著。<br/>經過煉淨、純潔、無疵，<br/>就得進你榮耀。<br/>',NULL,7569,7569);
INSERT INTO stanza VALUES('C85','1','我每靜念那十字架，<br/>並主如何在上受熬，<br/>我就不禁渾忘身家，<br/>鄙視從前所有倨傲。<br/>',NULL,7570,7570);
INSERT INTO stanza VALUES('C85','2','願主禁我別有所誇，<br/>除了基督的十字架；<br/>前所珍愛虛空榮華，<br/>今為祂血情願丟下。<br/>',NULL,7571,7571);
INSERT INTO stanza VALUES('C85','3','看從祂頭！祂腳！祂手！<br/>憂情、慈愛和血而流！<br/>那有愛憂如此相遘？<br/>荊棘編成如此冕旒？<br/>',NULL,7572,7572);
INSERT INTO stanza VALUES('C85','4','看祂全身滿被水血，<br/>如同穿上朱紅衣飾！<br/>因此，我與世界斷絕，<br/>世界向我也像已死。<br/>',NULL,7573,7573);
INSERT INTO stanza VALUES('C85','5','假若宇宙都歸我手，<br/>盡以奉主仍覺可羞；<br/>愛既如此奇妙、深厚，<br/>當得我心、我命－所有。<br/>',NULL,7574,7574);
INSERT INTO stanza VALUES('C86','1','屈身，低首，強暴壓逼，<br/>背著十架向前行；<br/>如羊牽到宰殺之地，<br/>忍辱、忍怨，無反應。<br/>',NULL,7575,7575);
INSERT INTO stanza VALUES('C86','chorus','哦主，你是無辜，竟肯<br/>為我罪愆受委屈！<br/>愛既如此長闊高深，<br/>餘生屬你永不渝。<br/>',NULL,7576,7576);
INSERT INTO stanza VALUES('C86','2','頭戴荊冕，身懸木上，<br/>手足被釘，肋中槍，<br/>父神離棄，敵魔猖狂，<br/>身靈受創痛難當。<br/>',NULL,7577,7577);
INSERT INTO stanza VALUES('C86','3','未肯從你十架跳下，<br/>未求天使來營救；<br/>任人擺佈，甘受傾軋，<br/>正為滿足神要求。<br/>',NULL,7578,7578);
INSERT INTO stanza VALUES('C86','4','太陽掩面不忍再睹，<br/>無疵羔羊慘喪身。<br/>殿幔裂出新活的路，<br/>罪人坦然親近神。<br/>',NULL,7579,7579);
INSERT INTO stanza VALUES('C87','1','主，我寶貴你的行徑，<br/>如何在此受苦害；<br/>那些最終悲痛情形，<br/>使我更覺你可愛。<br/>',NULL,7580,7580);
INSERT INTO stanza VALUES('C87','chorus','讚美救主，讚美救主，<br/>讚美主為罪人死；<br/>榮耀救主，榮耀救主，<br/>榮耀、榮耀，<br/>主為死人活。<br/>',NULL,7581,7581);
INSERT INTO stanza VALUES('C87','2','主，你當時艱難何大，<br/>大到無人會究推；<br/>無道摧殘、無理蹧蹋，<br/>痛苦有誰能微窺！<br/>',NULL,7582,7582);
INSERT INTO stanza VALUES('C87','3','可愛的主，當你救贖，<br/>沒有一人能跟隨；<br/>因為許多定罪囚奴，<br/>需要你獨受鞭錘。<br/>',NULL,7583,7583);
INSERT INTO stanza VALUES('C87','4','那時你量罪的距離－忿怒、咒詛和悲哀，<br/>為人所賣，為神所棄，<br/>我們纔識你可愛。<br/>',NULL,7584,7584);
INSERT INTO stanza VALUES('C88','1','耶穌獨自為我祈禱，<br/>在那客西馬尼，<br/>極其傷痛，大聲哀告，<br/>流汗猶如血滴。<br/>',NULL,7585,7585);
INSERT INTO stanza VALUES('C88','chorus','為我！為我！<br/>為我祂釘十架，<br/>捨命流血作我贖價；<br/>祂心如蠟鎔化，<br/>為我！為我！<br/>',NULL,7586,7586);
INSERT INTO stanza VALUES('C88','2','耶穌獨自為我被捆，<br/>在祂被賣晚間；<br/>並且獨自為我受審，<br/>在彼拉多面前。<br/>',NULL,7587,7587);
INSERT INTO stanza VALUES('C88','3','耶穌獨自為我被鞭，<br/>鞭得皮破肉爛；<br/>獨自為我頭戴荊冕，<br/>被人羞辱侮慢。<br/>',NULL,7588,7588);
INSERT INTO stanza VALUES('C88','4','耶穌獨自為我受死，<br/>在各各他山巔，<br/>手足被釘，肋旁被刺，<br/>流血贖我罪愆。<br/>',NULL,7589,7589);
INSERT INTO stanza VALUES('C88','5','耶穌獨自為我喝盡<br/>忿怒咒詛苦杯，<br/>好使我能得蒙救恩，<br/>永遠不嘗死味。<br/>',NULL,7590,7590);
INSERT INTO stanza VALUES('C88','6','聽祂臨死喊說：<br/>『成了！』<br/>我心能無感慨？<br/>切莫硬把感動滅消，<br/>不理祂這大愛！<br/>',NULL,7591,7591);
INSERT INTO stanza VALUES('C89','1','主，你的愛竟然不辭<br/>為我忍辱受死！<br/>好叫我們勝過罪世，<br/>並那壯士權勢。<br/>',NULL,7592,7592);
INSERT INTO stanza VALUES('C89','2','哦，你的擔何等的重！<br/>何等難於背負！<br/>人的罪惡、鬼的譏諷、<br/>加上神的忿怒。<br/>',NULL,7593,7593);
INSERT INTO stanza VALUES('C89','3','圍困你的狂怒風波，<br/>今已永遠平靜；<br/>因之我們得著歡樂，<br/>你得超絕的名。<br/>',NULL,7594,7594);
INSERT INTO stanza VALUES('C89','4','我們不久你前被提，<br/>要唱新歌讚你；<br/>但在這裡－你死的地，<br/>我們要先唱起。<br/>',NULL,7595,7595);
INSERT INTO stanza VALUES('C90','1','讚美不盡讚美，<br/>讚美救主恩深；<br/>感佩無限感佩，<br/>感佩救主捨身；<br/>看哪，神子在各各他，<br/>為你和我釘十字架。<br/>',NULL,7596,7596);
INSERT INTO stanza VALUES('C90','2','主愛遠勝爺娘，<br/>遠勝最好朋友；<br/>蒙恩罪人頌揚<br/>主愛，直到永久；<br/>看哪，神子在各各他，<br/>為你和我釘十字架。<br/>',NULL,7597,7597);
INSERT INTO stanza VALUES('C90','3','罪人今已蒙恩，<br/>魔鬼今已失敗；<br/>誰能再使我們<br/>離開基督的愛？<br/>看哪，神子在各各他，<br/>為你和我釘十字架。<br/>',NULL,7598,7598);
INSERT INTO stanza VALUES('C91','1','祂不能救自己，<br/>必須死髑髏地；<br/>不然，恩典無門，<br/>來救荒涼罪人；<br/>真的，神兒子當流血，<br/>罪人纔能洗得清潔，<br/>罪人纔能洗得清潔。<br/>',NULL,7599,7599);
INSERT INTO stanza VALUES('C91','2','祂不能救自己，<br/>必須成全公義；<br/>我罪當有刑罰，<br/>需要祂來被殺；<br/>律法非此不算還債，<br/>非此，罪惡不能寬貸。<br/>',NULL,7600,7600);
INSERT INTO stanza VALUES('C91','3','祂不能救自己，<br/>因為祂是代替<br/>信祂的人站立<br/>在罪人的死地。<br/>祂在十字架上流血，<br/>擔當信徒一切罪孽。<br/>',NULL,7601,7601);
INSERT INTO stanza VALUES('C91','4','祂不能救自己，<br/>這愛怎麼樣呢！<br/>祂不能救自己，<br/>這愛那有止極！<br/>我們的心雖然冷淡，<br/>這愛叫牠發出感讚。<br/>',NULL,7602,7602);
INSERT INTO stanza VALUES('C92','1','此時何時！孤單之時！<br/>四圍都是黑暗！<br/>天上神的獨生之子，<br/>以人血肉代人受死，<br/>這是何等悲慘！<br/>榮耀的主釘十字架！<br/>生命的王受人傾軋！<br/>',NULL,7603,7603);
INSERT INTO stanza VALUES('C92','2','哦，這樣的神、人，<br/>生、死，<br/>真是奇中之奇！<br/>這是中心！兩個永世<br/>莫不舉目而顧、而視<br/>你這當受讚的！<br/>哦，主耶穌，你十字架<br/>乃是我的永遠美家！<br/>',NULL,7604,7604);
INSERT INTO stanza VALUES('C92','3','哦，當我們看那木頭，<br/>心中何等感動；<br/>愛的化身死在髑髏！<br/>哦，怎能不又喜又愁，<br/>看你這樣苦痛！<br/>我們心裂聽你呼祈：<br/>『以利，<br/>拉馬撒巴大尼！』<br/>',NULL,7605,7605);
INSERT INTO stanza VALUES('C92','4','哦主，我們真是該死，<br/>該受神的忿怒，<br/>但神使你－祂的愛子－為我受苦、擔罪、忍恥；<br/>公義殺我救主；<br/>我已與你同被釘釘，<br/>我已與你在彼喪命。<br/>',NULL,7606,7606);
INSERT INTO stanza VALUES('C92','5','我們與你一同得生，<br/>與你從死同甦，<br/>因你是頭，我們是身，<br/>我們同你都是屬神，<br/>一同蒙神賜福；<br/>我們原來只配受罰，<br/>今卻同你呼喊阿爸。<br/>',NULL,7607,7607);
INSERT INTO stanza VALUES('C93','1','哎喲！救主真曾流血？<br/>真曾捨命亡躬？<br/>祂肯犧牲祂的超越，<br/>為我這個小蟲？<br/>',NULL,7608,7608);
INSERT INTO stanza VALUES('C93','2','祂在木上那樣哀歎，<br/>可是為我罪愆？<br/>憐憫何滿！慈愛何汎！<br/>恩典何其無邊！<br/>',NULL,7609,7609);
INSERT INTO stanza VALUES('C93','3','難怪太陽立變暗烏，<br/>隱藏一切榮光；<br/>當神基督造物的主，<br/>為人擔罪而亡。<br/>',NULL,7610,7610);
INSERT INTO stanza VALUES('C93','4','當我看見祂十字架，<br/>也當隱藏羞臉，<br/>心當鎔化，感激不暇，<br/>眼當流淚自貶。<br/>',NULL,7611,7611);
INSERT INTO stanza VALUES('C93','5','但這滿腔憂傷，<br/>不能稍還主愛的債；<br/>主，我在此奉上一生，<br/>聊表此心感戴。<br/>',NULL,7612,7612);
INSERT INTO stanza VALUES('C94','1','你的救贖何等奇妙，<br/>我的恩主耶穌！<br/>未見、未聞、也未想到，<br/>你竟為我作出！<br/>你的身位奧祕、神聖，<br/>遠超我所能言！<br/>你的救贖奇妙、有能，<br/>過於我所能讚！<br/>',NULL,7613,7613);
INSERT INTO stanza VALUES('C94','chorus','哦，你救贖何奇妙！<br/>新造故事，何榮耀！<br/>永遠豐滿有功效！<br/>配得我們稱道！<br/>',NULL,7614,7614);
INSERT INTO stanza VALUES('C94','2','你在十架為我裂破，<br/>流出你水和血，<br/>為將生命分賜與我，<br/>並為贖我罪孽。<br/>你的寶血將我洗淨，<br/>使我蒙神喜悅；<br/>你的生命使我重生，<br/>叫我與你聯結。<br/>',NULL,7615,7615);
INSERT INTO stanza VALUES('C94','3','你是一粒神聖麥子，<br/>結出許多子粒；<br/>我們與你同性、同質，<br/>成為你的身體。<br/>你是我們生命、內容，<br/>我們是你豐滿；<br/>你藉我們生活、行動，<br/>我們把你彰顯。<br/>',NULL,7616,7616);
INSERT INTO stanza VALUES('C94','4','既是身體你可定居，<br/>就是你的居所；<br/>你在我們得到倚據，<br/>我們作你寄託。<br/>滿足你心、怡悅你意，<br/>也是你的配偶；<br/>同你生活、與你一體，<br/>享受你的所有。<br/>',NULL,7617,7617);
INSERT INTO stanza VALUES('C94','5','我們在此擘餅記念，<br/>看到表記之物，<br/>心、靈不禁充滿感讚，<br/>希奇你的救贖！<br/>你使我們作你身體，<br/>並你居所、配偶，<br/>我們只有一面感激，<br/>一面敬拜、歌謳！<br/>',NULL,7618,7618);
INSERT INTO stanza VALUES('C95','1','這個真是何等<br/>甘美的故事，<br/>神用無限的愛<br/>差遣祂兒子，<br/>來自天上榮耀，<br/>死於十字架，<br/>成功救贖，<br/>好使我們進神家。<br/>',NULL,7619,7619);
INSERT INTO stanza VALUES('C95','chorus','讚美祂！讚美祂！<br/>工作已經成功！<br/>感謝祂！感謝祂！<br/>恩典真寬宏！<br/>我們榮耀耶穌，<br/>我們的救主，<br/>我們歌唱耶穌，<br/>永遠不止住。<br/>',NULL,7620,7620);
INSERT INTO stanza VALUES('C95','2','這個真是何等<br/>奇妙的故事，<br/>寶座要求，<br/>因著寶血就停止，<br/>公義審判，<br/>竟被神兒子擔負，<br/>因此神就心滿，<br/>罪人也意足。<br/>',NULL,7621,7621);
INSERT INTO stanza VALUES('C95','3','基督已登寶座，<br/>榮耀何光輝！<br/>耶穌已被高舉，<br/>名字何尊貴！<br/>是的，我們救主，<br/>得華冠的主，<br/>配得所有聖徒<br/>永遠的稱祝。<br/>',NULL,7622,7622);
INSERT INTO stanza VALUES('C96','1','神的基督從天至，<br/>拯救罪人脫罪、死，<br/>竟然稱為『憂患子！』<br/>阿利路亞！何等救主！<br/>',NULL,7623,7623);
INSERT INTO stanza VALUES('C96','2','被人侮慢被人譏，<br/>代替我站罪人地，<br/>賜我生命賜我力，<br/>阿利路亞！何等救主！<br/>',NULL,7624,7624);
INSERT INTO stanza VALUES('C96','3','我們又弱又不好，<br/>祂是聖潔的羊羔，<br/>救贖竟然作得到！<br/>阿利路亞！何等救主！<br/>',NULL,7625,7625);
INSERT INTO stanza VALUES('C96','4','祂被舉起，我免死；<br/>祂說成了，鬼失勢；<br/>祂登寶座給恩賜。<br/>阿利路亞！何等救主！<br/>',NULL,7626,7626);
INSERT INTO stanza VALUES('C96','5','當祂復臨遣天使，<br/>提接聖徒見祂時，<br/>我們還要唱此詩：<br/>阿利路亞！何等救主！<br/>',NULL,7627,7627);
INSERT INTO stanza VALUES('C97','1','加略山巔救主喪命，<br/>在彼受辱、在彼被釘；<br/>為我贖罪、為我流血，<br/>買來赦免、立了新約。<br/>',NULL,7628,7628);
INSERT INTO stanza VALUES('C97','chorus','慘哉加略！痛哉加略！<br/>在彼耶穌為我流血；<br/>大哉加略！福哉加略！<br/>在彼救主為我命絕。<br/>',NULL,7629,7629);
INSERT INTO stanza VALUES('C97','2','磐石崩裂，天地昏暗，<br/>主喊成了，垂首氣斷；<br/>殿幔中裂，活路開通，<br/>我得近神，蒙恩無窮。<br/>',NULL,7630,7630);
INSERT INTO stanza VALUES('C97','3','哦主耶穌，怎會這樣－為我你竟甘心受戕？<br/>身懸木架受神責譴！<br/>在那慘痛加略山巔！<br/>',NULL,7631,7631);
INSERT INTO stanza VALUES('C98','1','頌讚聲音何等難得！<br/>所以應當無間時刻；<br/>如果我們自甘緘默，<br/>石頭也要說話相責。<br/>',NULL,7632,7632);
INSERT INTO stanza VALUES('C98','2','我們應當高聲頌美<br/>那用己血買我們的；<br/>祂替我們備嘗死味，<br/>祂為我們費盡心力。<br/>',NULL,7633,7633);
INSERT INTO stanza VALUES('C98','3','此世有一特別詩歌，<br/>惟獨蒙恩罪人會唱；<br/>此外無人懂那音樂，<br/>因不知其意義之綱。<br/>',NULL,7634,7634);
INSERT INTO stanza VALUES('C98','4','天使雖能歡然承認<br/>憐憫如何由血洞曉，<br/>但是他們不像我們，<br/>能以證明這血功效。<br/>',NULL,7635,7635);
INSERT INTO stanza VALUES('C98','5','天使雖能讚美拜朝，<br/>說神是神，向神恭敬；<br/>我們卻能歡樂唱道：<br/>祂在寶座還帶人性！<br/>',NULL,7636,7636);
INSERT INTO stanza VALUES('C98','6','哦主，我們讚美那使<br/>你來流血受死的愛；<br/>但願不久在天相值，<br/>向你讚美、向你敬拜。<br/>',NULL,7637,7637);
INSERT INTO stanza VALUES('C99','1','祂躺臥在墳墓，<br/>耶穌我救主！<br/>靜待晨光重睹。<br/>耶穌我主！<br/>',NULL,7638,7638);
INSERT INTO stanza VALUES('C99','chorus','祂從墳墓已起來，<br/>勝過仇敵，大大的奏凱，<br/>祂從黑域起來，<br/>祂是得勝者，活著掌權，<br/>同祂眾聖徒聯合。<br/>祂起來！祂起來！<br/>阿利路亞！主起來！<br/>',NULL,7639,7639);
INSERT INTO stanza VALUES('C99','2','兵丁徒然看守，<br/>耶穌我救主！<br/>石頭徒然封口，<br/>耶穌我主！<br/>',NULL,7640,7640);
INSERT INTO stanza VALUES('C99','3','死亡無法鎖關，<br/>耶穌我救主！<br/>祂已打斷柵欄，<br/>耶穌我主！<br/>',NULL,7641,7641);
INSERT INTO stanza VALUES('C100','1','主已復活，<br/>死的審判已過；<br/>在祂裡面，<br/>死亡難再淹沒。<br/>主已復活，<br/>我今不再定罪；<br/>祂的空墓作證最具權威。<br/>',NULL,7642,7642);
INSERT INTO stanza VALUES('C100','2','主已復活，<br/>我也同祂復活；<br/>在祂墓中，<br/>仇敵全都埋沒。<br/>主已復活，<br/>我得脫離死寨；<br/>在祂裡面，<br/>復活生命倚賴。<br/>',NULL,7643,7643);
INSERT INTO stanza VALUES('C100','3','主已復活，<br/>我已得蒙拯救，<br/>今在曠野跟祂腳蹤行走。<br/>主已復活，<br/>我得進至聖所，<br/>與祂一同在神面光生活。<br/>',NULL,7644,7644);
INSERT INTO stanza VALUES('C100','4','主已復活，<br/>作了幔內先鋒，<br/>使我營外來作祂的見證。<br/>主已復活，<br/>我要高唱凱歌：<br/>『你已得勝！<br/>你民已脫捆索！』<br/>',NULL,7645,7645);
INSERT INTO stanza VALUES('C101','1','基督復活！阿利路亞！<br/>得勝的主已復活；<br/>向祂高歌，阿利路亞！<br/>基督死過又活著。<br/>我心感戴，向祂敬拜，<br/>因祂面光又重顯；<br/>祂前俯伏，歡樂奏凱，<br/>勝過痛苦與憂患。<br/>',NULL,7646,7646);
INSERT INTO stanza VALUES('C101','chorus','基督復活！阿利路亞！<br/>得勝的主已復活；<br/>向祂高歌，阿利路亞！<br/>基督死過又活著。<br/>',NULL,7647,7647);
INSERT INTO stanza VALUES('C101','2','基督復活！何等歡欣！<br/>地上艱苦都過去；<br/>經過歡樂敞開之門，<br/>祂又回到生命域；<br/>死亡陰間全都征服，<br/>復活作了得勝者；<br/>天使觀看祂的步武，<br/>榮冕戴祂傷過額。<br/>',NULL,7648,7648);
INSERT INTO stanza VALUES('C101','3','基督復活，何等超脫！<br/>死亡、陰間難困我；<br/>我屬基督，憑祂活著，<br/>一切就都全勝過；<br/>所有疑惑、一切頹喪，<br/>從我慄心全止息；<br/>復活之日應該歡暢，<br/>興起來赴這筵席。<br/>',NULL,7649,7649);
INSERT INTO stanza VALUES('C102','1','救主基督已復活，<br/>阿利路亞！<br/>死亡捆索全解脫，<br/>阿利路亞！<br/>天使讚美樂歡騰，<br/>阿利路亞！<br/>罪人蒙恩也響應，<br/>阿利路亞！<br/>',NULL,7650,7650);
INSERT INTO stanza VALUES('C102','2','祂從陰間已脫出，<br/>阿利路亞！<br/>死阿！你鉤在何處？<br/>阿利路亞！<br/>祂曾死過又復生，<br/>阿利路亞！<br/>墳墓！你今有何能？<br/>阿利路亞！<br/>',NULL,7651,7651);
INSERT INTO stanza VALUES('C102','3','祂曾死過救贖成，<br/>阿利路亞！<br/>毀滅仇敵勝利贏，<br/>阿利路亞！<br/>死亡不能拘禁祂，<br/>阿利路亞！<br/>祂升高天仇敵踏，<br/>阿利路亞！<br/>',NULL,7652,7652);
INSERT INTO stanza VALUES('C102','4','我們與祂同復活，<br/>阿利路亞！<br/>與祂高升天上坐，<br/>阿利路亞！<br/>與祂一樣的高昂，<br/>阿利路亞！<br/>脫開地上諸捆綁，<br/>阿利路亞！<br/>',NULL,7653,7653);
INSERT INTO stanza VALUES('C103','1','我的代替未見歸回，<br/>我怎能彀放心無慮；<br/>會否我罪將祂連累，<br/>未能救我，祂倒被拘？<br/>',NULL,7654,7654);
INSERT INTO stanza VALUES('C103','2','能否是因我的罪孽，<br/>太大、過多、無法赦免？<br/>能否是因祂的寶血，<br/>能力有限、包括不全？<br/>',NULL,7655,7655);
INSERT INTO stanza VALUES('C103','3','歡呼！耶穌已經復活，<br/>未損毫髮，只增榮耀；<br/>祂雖進入黑暗處所，<br/>黑暗未曾留下功效。<br/>',NULL,7656,7656);
INSERT INTO stanza VALUES('C103','4','主得歸回，就是憑據，<br/>神的公義已得滿足，<br/>神的大愛仍施憐恤，<br/>主是已經完成救贖。<br/>',NULL,7657,7657);
INSERT INTO stanza VALUES('C103','5','神用復活答覆流血，<br/>承認流血所成救贖；<br/>阿利路亞，我已清潔！<br/>阿利路亞，我得饒恕！<br/>',NULL,7658,7658);
INSERT INTO stanza VALUES('C104','1','哦主，死的領土<br/>你曾去走；<br/>非因罪將你毒，<br/>死有要求。<br/>掌死權的魔鬼，<br/>你已完全摧毀，<br/>使他不再作祟，<br/>將人監囚。<br/>',NULL,7659,7659);
INSERT INTO stanza VALUES('C104','2','你已衝破墳墓，<br/>從死復活；<br/>死難將你拘束，<br/>反被勝過！<br/>你已得勝走出<br/>幽冥、黑暗之墓，<br/>死蔭全都破除，<br/>從死超脫。<br/>',NULL,7660,7660);
INSERT INTO stanza VALUES('C104','3','何等大能得勝<br/>你已得到！<br/>結果何其豐盛，<br/>將神榮耀！<br/>從你死中生出<br/>無數活的信徒，<br/>給你安家居住，<br/>憑你活著。<br/>',NULL,7661,7661);
INSERT INTO stanza VALUES('C104','4','你是初熟果子，<br/>我們愛戴；<br/>作神心愛長子，<br/>將我領率。<br/>凡事你居首位，<br/>是我永遠所歸，<br/>配得榮耀、尊貴，<br/>配得敬拜。<br/>',NULL,7662,7662);
INSERT INTO stanza VALUES('C105','1','阿利路亞，<br/>『祂已復活！』<br/>基督已經高天升！<br/>死的門閂已經斷開，<br/>天使歡呼，人響應；<br/>祂已復活，祂已復活，<br/>祂今活著作生命。<br/>祂已復活，祂已復活，<br/>祂今活著作生命。<br/>',NULL,7663,7663);
INSERT INTO stanza VALUES('C105','2','阿利路亞，祂已復活！<br/>作我高舉的元首！<br/>賜下聖靈來作見證，<br/>將祂一切向我授；<br/>祂已復活，祂已復活，<br/>使我稱義蒙拯救。<br/>',NULL,7664,7664);
INSERT INTO stanza VALUES('C105','3','阿利路亞，祂已復活！<br/>死亡永遠失權勢！<br/>基督自己就是復活，<br/>要救我們脫離死；<br/>祂已復活，祂已復活，<br/>一直活著作恩賜。<br/>',NULL,7665,7665);
INSERT INTO stanza VALUES('C106','1','榮耀歸於你，<br/>復活得勝子，<br/>你已永遠得勝，<br/>你已勝過死；<br/>天使身穿白衣，<br/>輥開墳墓石，<br/>憑著你的空墓，<br/>你復活啟示。<br/>',NULL,7666,7666);
INSERT INTO stanza VALUES('C106','chorus','榮耀歸於你，<br/>復活得勝子，<br/>你已永遠得勝，<br/>你已勝過死。<br/>',NULL,7667,7667);
INSERT INTO stanza VALUES('C106','2','看！復活基督，<br/>與我們相見；<br/>祂那可愛問安，<br/>驅盡懼與暗；<br/>但願召會歡樂，<br/>高唱得勝詩，<br/>因主現在活著，<br/>死已失權勢。<br/>',NULL,7668,7668);
INSERT INTO stanza VALUES('C106','3','不再懷疑你，<br/>榮耀生命王；<br/>無你就無生命，<br/>有你勝死亡。<br/>使我得勝有餘，<br/>靠復活大能，<br/>直到進入國度，<br/>不再有戰爭。<br/>',NULL,7669,7669);
INSERT INTO stanza VALUES('C107','1','耶穌已經出墓來，<br/>死亡對祂毫無害；<br/>我們應當相安慰，<br/>將祂的名同讚美。<br/>救贖工作今作成，<br/>與敵交戰已得勝。<br/>贖罪一次就清楚，<br/>祂並不用多受苦。<br/>',NULL,7670,7670);
INSERT INTO stanza VALUES('C107','2','封墓、設兵、空畫策，<br/>陰府對祂無奈何；<br/>我主暫時雖受苦，<br/>但祂使我得永福。<br/>祂已死過不再死，<br/>撒但計窮無可施；<br/>我既看見一墓空，<br/>就知萬墓必相同。<br/>',NULL,7671,7671);
INSERT INTO stanza VALUES('C107','3','一粒麥子已死了，<br/>今日萬粒都生苗；<br/>當日不過只一位，<br/>今日已變全召會。<br/>我們是祂的身體，<br/>頭既上升肢繼起；<br/>與祂同葬、同升天，<br/>讚美祂名億萬年。<br/>',NULL,7672,7672);
INSERT INTO stanza VALUES('C108','1','神的基督、親愛救主，<br/>我們向你歌唱；<br/>你曾流血、成功救贖，<br/>福杯我們得嘗。<br/>你用大能已將敵剿，<br/>今登天上寶座；<br/>還要將我帶進榮耀，<br/>進入你的天國。<br/>',NULL,7673,7673);
INSERT INTO stanza VALUES('C108','2','神的基督、親愛救主，<br/>我們向你歌唱；<br/>你已進攻死的領土，<br/>擄掠死的君王。<br/>塵下之屋難再困擾，<br/>死的權勢已黜；<br/>你手拿著死亡鎖鑰，<br/>掌管陰府、墳墓。<br/>',NULL,7674,7674);
INSERT INTO stanza VALUES('C108','3','神的基督、親愛救主，<br/>我們向你歌唱；<br/>你藉十架已經剪除<br/>今世背叛君王，<br/>並藉你的生命大能，<br/>投入黑暗陰府，<br/>掃蕩黑暗，勝過幽冥，<br/>釋放死的囚奴。<br/>',NULL,7675,7675);
INSERT INTO stanza VALUES('C108','4','神的基督、親愛救主，<br/>永遠向你歌唱；<br/>你是永遠得勝的主，<br/>將我永遠釋放。<br/>你是神的拯救能力，<br/>使我完全自由；<br/>榮耀歸神並你自己，<br/>從今直到永久。<br/>',NULL,7676,7676);
INSERT INTO stanza VALUES('C109','1','讚美、讚美基督得勝！<br/>讚美基督已得勝！<br/>罪孽贖清，舊人同釘，<br/>救贖大功已完成！<br/>毀壞撒但，擄掠邪靈，<br/>仗著十架而誇勝！<br/>',NULL,7677,7677);
INSERT INTO stanza VALUES('C109','2','讚美、讚美基督復生！<br/>讚美基督已復生！<br/>吞滅死亡頑強權能，<br/>使人出死而入生！<br/>衝破陰府殘忍幽冥，<br/>顯出復活的大能！<br/>',NULL,7678,7678);
INSERT INTO stanza VALUES('C109','3','讚美、讚美基督高升！<br/>讚美基督已高升！<br/>遠超宇宙一切首領，<br/>得著至高的尊名！<br/>領得天地所有權柄，<br/>等候仇敵作腳凳！<br/>',NULL,7679,7679);
INSERT INTO stanza VALUES('C109','4','阿利路亞，基督得勝！<br/>阿利路亞，已得勝！<br/>阿利路亞，基督復生！<br/>阿利路亞，已復生！<br/>阿利路亞，基督高升！<br/>阿利路亞，已高升！<br/>',NULL,7680,7680);
INSERT INTO stanza VALUES('C110','1','聽哪，千萬聲音雷鳴，<br/>同聲高舉神羔羊；<br/>萬萬千千立即響應，<br/>和聲爆發同頌揚。<br/>',NULL,7681,7681);
INSERT INTO stanza VALUES('C110','2','『讚美羔羊！』<br/>聲音四合，<br/>全天會集來歌誦，<br/>萬口莫不響亮協和，<br/>宇宙充滿救主頌。<br/>',NULL,7682,7682);
INSERT INTO stanza VALUES('C110','3','這樣感激心香如縷，<br/>永向父的寶座去；<br/>萬膝莫不向子屈曲，<br/>天上心意真一律。<br/>',NULL,7683,7683);
INSERT INTO stanza VALUES('C110','4','子所有的一切光輝，<br/>使父榮耀得發揮；<br/>父所有的一切智慧，<br/>宣告子是同尊貴。<br/>',NULL,7684,7684);
INSERT INTO stanza VALUES('C110','5','藉著聖靈無往不透，<br/>天人無數都無求，<br/>圍著羔羊，<br/>俯伏拜叩，<br/>稱頌祂作『自永有。』<br/>',NULL,7685,7685);
INSERT INTO stanza VALUES('C110','6','現今新造何等滿足、<br/>安息、喜樂並穩固，<br/>因著祂的救恩受福，<br/>不再受縛，不再苦。<br/>',NULL,7686,7686);
INSERT INTO stanza VALUES('C110','7','聽哪，天上又發歌聲，<br/>讚美聲音又四震，<br/>穹蒼之中滿了阿們！<br/>『阿們』因是同蒙恩。<br/>',NULL,7687,7687);
INSERT INTO stanza VALUES('C111','1','神的兒子、親愛救主，<br/>你曾用你寶血救贖<br/>我們脫死和罪；<br/>你的聖徒歡樂看見：<br/>現今你戴榮耀冠冕，<br/>並登天上座位。<br/>並登天上座位。<br/>',NULL,7688,7688);
INSERT INTO stanza VALUES('C111','2','父的愛心將你高升，<br/>賜你榮耀、尊貴、權能。<br/>使你坐祂右邊；<br/>現今頌讚、智慧、豐富，<br/>完全屬你，親愛救主！<br/>你的年日無限。<br/>',NULL,7689,7689);
INSERT INTO stanza VALUES('C111','3','召會的頭，你坐那裡，<br/>賜福給你所有肢體，<br/>你的是我們的：<br/>你是我們生命、能力，<br/>你使我們堅定站立，<br/>勝過一切仇敵。<br/>',NULL,7690,7690);
INSERT INTO stanza VALUES('C111','4','榮耀日子不久來臨，<br/>你的新婦就要上升，<br/>鑑賞你的美麗。<br/>何等可樂！看見了你，<br/>聽見你認我們屬你，<br/>並永同你安息。<br/>',NULL,7691,7691);
INSERT INTO stanza VALUES('C112','1','看那勝者奏凱上升，<br/>帶著君王的尊榮，<br/>乘駕彩雲當祂車輦，<br/>歸回天上的王宮；<br/>聽阿，天使合聲歌唱<br/>阿利路亞的頌揚，<br/>天上城門頭全抬起，<br/>歡迎祂，歡迎祂，<br/>歡迎他們天國王。<br/>',NULL,7692,7692);
INSERT INTO stanza VALUES('C112','2','是誰帶著榮耀而來，<br/>配上禧年的號聲？<br/>爭戰之主、萬軍之神，<br/>祂在戰場已得勝。<br/>祂已忍受十架苦難，<br/>且從墳墓已復起；<br/>祂已除滅罪與撒但，<br/>藉著死，藉著死，<br/>藉著祂死毀仇敵。<br/>',NULL,7693,7693);
INSERT INTO stanza VALUES('C112','3','正在舉手祝福之時，<br/>祂就離地往上升；<br/>當祂門徒正在看祂，<br/>祂就被接去天庭。<br/>與神同行，使神喜悅，<br/>傳過真理與審判；<br/>我的以諾被神取去，<br/>得進到，得進到，<br/>得以進到神面前。<br/>',NULL,7694,7694);
INSERT INTO stanza VALUES('C112','4','我的亞倫進入聖所，<br/>帶著祂血進幔內；<br/>我約書亞進入迦南，<br/>眾王祂前都敗退；<br/>祂將我們神的選民，<br/>栽植應許的美地；<br/>我以利亞現今賜下<br/>雙倍福，雙倍福，<br/>雙倍屬天的福氣。<br/>',NULL,7695,7695);
INSERT INTO stanza VALUES('C112','5','祂已提高我們人性，<br/>將人帶到神右邊；<br/>我們與祂同坐天上，<br/>與祂同在榮耀間。<br/>耶穌作王，天使敬拜，<br/>人竟與神同寶座；<br/>大能的主，憑你升天，<br/>我相信，我相信，<br/>相信升天必得著。<br/>',NULL,7696,7696);
INSERT INTO stanza VALUES('C113','1','何等權能！耶穌尊名！<br/>天使全都俯伏，<br/>獻上冠冕，同心尊敬<br/>祂作萬有之主，<br/>獻上冠冕，同心尊敬<br/>祂作萬有之主。<br/>',NULL,7697,7697);
INSERT INTO stanza VALUES('C113','2','你們歷代殉道眾聖，<br/>要從祭壇歡呼，<br/>同聲高舉耶西的根，<br/>祂是萬有之主。<br/>',NULL,7698,7698);
INSERT INTO stanza VALUES('C113','3','你們被贖亞當後代，<br/>出身『墮落』聖徒，<br/>蒙恩得救，應當敬拜<br/>祂作萬有之主。<br/>',NULL,7699,7699);
INSERT INTO stanza VALUES('C113','4','罪人，你心永不能忘<br/>祂的苦膽、酸醋，<br/>今當到祂面前瞻望<br/>祂這萬有之主<br/>',NULL,7700,7700);
INSERT INTO stanza VALUES('C113','5','但願地上萬族萬民<br/>都向救主歡呼，<br/>榮耀、尊貴，都歸祂名，<br/>祂是萬有之主。<br/>',NULL,7701,7701);
INSERT INTO stanza VALUES('C113','6','億萬群眾歌聲雷動，<br/>我也一同俯伏，<br/>直到永遠敬拜稱頌<br/>祂作萬有之主。<br/>',NULL,7702,7702);
INSERT INTO stanza VALUES('C114','1','看哪，冠冕已給羊羔！<br/>榮耀、尊貴已歸祂！<br/>為祂無處算是太高，<br/>天上無處是太大。<br/>天上無處是太大。<br/>',NULL,7703,7703);
INSERT INTO stanza VALUES('C114','2','祂登寶座－天上寶座，<br/>祂登寶座何豪邁！<br/>祂是題目，聖徒所歌，<br/>祂是珍物，父所愛。<br/>',NULL,7704,7704);
INSERT INTO stanza VALUES('C114','3','祂雖高大，卻肯接受<br/>我們在此的殷勤；<br/>我們所有微聲弱謳，<br/>無一不入救主心。<br/>',NULL,7705,7705);
INSERT INTO stanza VALUES('C114','4','我的詩歌，惟獨就是<br/>高舉被殺的羔羊，<br/>並那坐在寶座上的，<br/>如何應當受頌揚。<br/>',NULL,7706,7706);
INSERT INTO stanza VALUES('C114','5','從前那受人藐視的，<br/>今得榮耀和尊貴；<br/>冠冕、高位，原是祂的，<br/>祂得這些真無愧！<br/>',NULL,7707,7707);
INSERT INTO stanza VALUES('C115','1','看哪，耶穌天上坐著！<br/>我主基督登寶座！<br/>祂是那人神所高舉，<br/>榮耀、尊貴已得著。<br/>',NULL,7708,7708);
INSERT INTO stanza VALUES('C115','2','祂曾穿上人的性情，<br/>照神計畫且死過，<br/>帶著身體從死復活，<br/>仍然是人升天坐。<br/>',NULL,7709,7709);
INSERT INTO stanza VALUES('C115','3','在祂裡面神降為卑，<br/>神來地上同人處；<br/>在祂裡面人升為高，<br/>人到天上同神住。<br/>',NULL,7710,7710);
INSERT INTO stanza VALUES('C115','4','祂是真神與人調和，<br/>神在人裡被宣告；<br/>祂是真人與神聯合，<br/>人在神裡得榮耀。<br/>',NULL,7711,7711);
INSERT INTO stanza VALUES('C115','5','從那升天得榮耶穌，<br/>降下包羅萬有靈；<br/>耶穌身位和祂工作，<br/>全由這靈來證明。<br/>',NULL,7712,7712);
INSERT INTO stanza VALUES('C115','6','和那升天得榮耶穌，<br/>今天召會能聯合；<br/>藉著這位耶穌的靈，<br/>基督肢體能同活。<br/>',NULL,7713,7713);
INSERT INTO stanza VALUES('C115','7','看哪，一人天上坐著！<br/>萬有之主在寶座！<br/>這是救主耶穌基督，<br/>榮耀、尊貴永得著！<br/>',NULL,7714,7714);
INSERT INTO stanza VALUES('C116','1','哦主耶穌，我心喜樂，<br/>因你為我所歷坎坷，<br/>現今已經過去；<br/>你的工作都已得勝，<br/>你今就是坐享其成，<br/>被神榮耀高舉。<br/>',NULL,7715,7715);
INSERT INTO stanza VALUES('C116','2','你的聖首曾被芒刺，<br/>現今已得榮冕裝飾，<br/>並坐父的座位。<br/>哦主，我們真讚美你，<br/>我們永要虔誠拜禮，<br/>並說：惟你是配！<br/>',NULL,7716,7716);
INSERT INTO stanza VALUES('C116','3','你在那裡是作元首，<br/>等你肢體也同接受<br/>你所有的一切－你的榮耀和你寶座、<br/>你的權柄和你天國，<br/>因為你我聯結。<br/>',NULL,7717,7717);
INSERT INTO stanza VALUES('C116','4','主，你快樂，我們也樂，<br/>因你得勝我們唱歌，<br/>因為你我合一；<br/>現今在此受苦任勞，<br/>何等歡欣，當我想到<br/>寶座是屬於你。<br/>',NULL,7718,7718);
INSERT INTO stanza VALUES('C117','1','救主已登寶座，<br/>遠超一切；<br/>羔羊已得冠冕，<br/>榮耀超絕。<br/>祂要永遠活著，<br/>永遠超越；<br/>神已將祂高舉，<br/>遠超一切。<br/>',NULL,7719,7719);
INSERT INTO stanza VALUES('C117','chorus','遠超一切！遠超一切！<br/>那被釘的耶穌遠超一切！<br/>在祂腳凳之前，<br/>敬拜不歇，<br/>神已將祂高舉，<br/>遠超一切！<br/>',NULL,7720,7720);
INSERT INTO stanza VALUES('C117','2','當那狂風大作，<br/>洪濤翻騰，<br/>想要將我淹沒，<br/>逞兇肆能，<br/>我向救主仰望，<br/>祂就拯救，<br/>踏著風波行走，<br/>平安無憂。<br/>',NULL,7721,7721);
INSERT INTO stanza VALUES('C117','3','我要進攻之城<br/>雖然高大，<br/>障礙雖也有力，<br/>要我停下，<br/>仍要無懼向前，<br/>一一解決，<br/>堅定相信祂是<br/>遠超一切。<br/>',NULL,7722,7722);
INSERT INTO stanza VALUES('C117','4','看哪！全地都是<br/>祂的國度，<br/>遠超一切，<br/>萬有無不歸服；<br/>所有的得勝者，<br/>無一或缺，<br/>都要與祂一同<br/>遠超一切。<br/>',NULL,7723,7723);
INSERT INTO stanza VALUES('C118','1','從前那戴荊棘的頭，<br/>今戴榮耀冠冕；<br/>救主耶穌，我們元首，<br/>你今已升高天。<br/>',NULL,7724,7724);
INSERT INTO stanza VALUES('C118','2','你是地上聖徒之樂，<br/>你是天上之光；<br/>你今領我飲於愛河，<br/>使我知其深廣。<br/>',NULL,7725,7725);
INSERT INTO stanza VALUES('C118','3','主，將你的羞辱、權柄，<br/>一並賜給我們；<br/>地雖否認你的微名，<br/>神卻使你高升。<br/>',NULL,7726,7726);
INSERT INTO stanza VALUES('C118','4','凡肯與你在世同苦，<br/>也要同榮在天，<br/>所以求主使我堅固，<br/>鄙視世界恩典。<br/>',NULL,7727,7727);
INSERT INTO stanza VALUES('C118','5','十架於你雖是辱、死，<br/>在我卻是生命！<br/>也是我的榮耀、權勢！<br/>我的永遠安寧！<br/>',NULL,7728,7728);
INSERT INTO stanza VALUES('C119','1','榮耀、榮耀、永遠榮耀，<br/>歸給登極的基督；<br/>榮耀、榮耀、永遠榮耀，<br/>歸給高舉的救主。<br/>祂已得著至高尊名，<br/>天上地下都頌稱；<br/>榮耀、榮耀、永遠榮耀，<br/>歸給祂這至尊名。<br/>',NULL,7729,7729);
INSERT INTO stanza VALUES('C119','2','原在天上榮耀寶座，<br/>與神同等、居天庭；<br/>竟然卑取奴僕形狀，<br/>歷盡地上苦人生：<br/>順服父旨從不偏離，<br/>甚至順服到死地；<br/>十字架上死的羞辱，<br/>甘願受盡無所遺。<br/>',NULL,7730,7730);
INSERT INTO stanza VALUES('C119','3','天上冠冕，光明、榮耀，<br/>今已歸那降卑人；<br/>天上佳袍，華麗、燦爛，<br/>今已穿在祂榮身。<br/>因祂尊名無不屈膝，<br/>無不口稱祂為主；<br/>天地之主、普世之王，<br/>億兆都將祂稱祝。<br/>',NULL,7731,7731);
INSERT INTO stanza VALUES('C119','4','榮耀、榮耀、永遠榮耀，<br/>歸那無價的至寶；<br/>榮耀在天、榮耀在地，<br/>全都歸祂作榮耀。<br/>榮耀歸神、歸給我神、<br/>歸給至大的『我是；』<br/>榮耀、榮耀、永遠榮耀，<br/>一直歸祂到永世。<br/>',NULL,7732,7732);
INSERT INTO stanza VALUES('C120','1','哦主，你是萬有的主，<br/>已得榮耀冠冕；<br/>因你權柄和你威嚴，<br/>萬眾將你稱讚。<br/>',NULL,7733,7733);
INSERT INTO stanza VALUES('C120','2','神在人裡活在地上，<br/>曾經成為奴僕；<br/>人在神裡住在天上，<br/>尊為萬有之主。<br/>',NULL,7734,7734);
INSERT INTO stanza VALUES('C120','3','你是那人在榮耀裡，<br/>與神同坐寶座；<br/>天上地上所有權柄，<br/>全都歸你得著。<br/>',NULL,7735,7735);
INSERT INTO stanza VALUES('C120','4','升上高天，得被高舉，<br/>且得至高尊名；<br/>萬口無不稱你為主，<br/>萬膝無不跪敬。<br/>',NULL,7736,7736);
INSERT INTO stanza VALUES('C120','5','神已使你作主基督，<br/>聖靈如此證明；<br/>在榮耀裡，並在天上，<br/>得著寶座、權柄。<br/>',NULL,7737,7737);
INSERT INTO stanza VALUES('C120','6','榮耀之主，我們敬拜，<br/>高聲向你讚美；<br/>萬有之主，我們高舉，<br/>讚美惟你是配！<br/>',NULL,7738,7738);
INSERT INTO stanza VALUES('C121','1','看哪，何等榮耀情景，<br/>憂患之子得榮耀！<br/>祂從戰場凱旋乘勝，<br/>榮耀之中登大寶！<br/>加冠於祂、加冠於祂、<br/>加冠王中的至高。<br/>',NULL,7739,7739);
INSERT INTO stanza VALUES('C121','2','人曾戲弄，給祂加冠，<br/>荊棘冠冕給祂戴；<br/>祂今得著榮耀冠冕，<br/>天使、聖徒都敬拜。<br/>加冠於祂、加冠於祂、<br/>加冠神心所寶愛。<br/>',NULL,7740,7740);
INSERT INTO stanza VALUES('C121','3','加冠救主、罪人加冠，<br/>你是祂的勝利品；<br/>當著穹蒼正在騰歡，<br/>讓祂登極在你心。<br/>加冠於祂、加冠於祂、<br/>加冠罪魁的恩人。<br/>',NULL,7741,7741);
INSERT INTO stanza VALUES('C121','4','聽哪！群眾喝采、歡呼！<br/>聽哪！勝利的高歌！<br/>耶穌升到最高之處，<br/>此景令人何歡樂！<br/>加冠於祂、加冠於祂、<br/>加冠於那至高者！<br/>',NULL,7742,7742);
INSERT INTO stanza VALUES('C122','1','我們的靈伏著注視<br/>在榮耀裡的耶穌，<br/>我們在彼讀祂故事，<br/>如何在世受羞辱。<br/>',NULL,7743,7743);
INSERT INTO stanza VALUES('C122','2','你的聖首滿了羞辱，<br/>世人竟然大歡暢；<br/>今日榮耀反面說出：<br/>當日你心的憂傷。<br/>',NULL,7744,7744);
INSERT INTO stanza VALUES('C122','3','當你掛在十字架時，<br/>孤單被棄無人憐；<br/>眾聖今則向你唱詩，<br/>你則高升到父前。<br/>',NULL,7745,7745);
INSERT INTO stanza VALUES('C122','4','神曾不顧你的無告！<br/>神曾離棄你不瞧！<br/>我們從你憔悴面貌，<br/>現今看見父榮耀。<br/>',NULL,7746,7746);
INSERT INTO stanza VALUES('C122','5','寶貴的主！注視這個，<br/>我們不禁要讚美；<br/>但願天地同心唱和：<br/>『神的羔羊，你是配。』<br/>',NULL,7747,7747);
INSERT INTO stanza VALUES('C122','6','我們的心應當起來，<br/>即今起來讚美父；<br/>但願歌頌、歡呼、愛戴，<br/>歸給父子到永古。<br/>',NULL,7748,7748);
INSERT INTO stanza VALUES('C123','1','神的基督、榮耀的主，<br/>你的心慈、你恩溥！<br/>我們現在全魂、全心，<br/>到你面前來朝覲；<br/>我敬拜你、讚美你，<br/>你的道路無可比！<br/>',NULL,7749,7749);
INSERT INTO stanza VALUES('C123','2','受膏的王、一切的主，<br/>進入榮耀得萬福！<br/>前曾被人譏笑、厭棄，<br/>你欲救人，人絕你；<br/>我敬愛你、稱頌你，<br/>今得尊榮至無極。<br/>',NULL,7750,7750);
INSERT INTO stanza VALUES('C123','3','你曾死過，生命的主，<br/>祝福人者竟受詛！<br/>你是父神所愛所重，<br/>竟受苦難學順從；<br/>我仰望你、記念你，<br/>為我親歷憂患地。<br/>',NULL,7751,7751);
INSERT INTO stanza VALUES('C123','4','不久華冠將加你首，<br/>不久鐵杖操你手！<br/>神的基督，我們現今<br/>等候你從天降臨；<br/>我敬愛你、順服你，<br/>永遠認你為基督。<br/>',NULL,7752,7752);
INSERT INTO stanza VALUES('C124','1','主，你乃是王中王，<br/>我們何人不歸向？<br/>神的受膏我敬拜，<br/>衷心敬畏又愛戴！<br/>對你這位王中王，<br/>千萬聖徒在頌揚<br/>',NULL,7753,7753);
INSERT INTO stanza VALUES('C124','2','全地這國到那國，<br/>無不由你來掌握！<br/>萬民都要來歸依，<br/>尊你為王，事奉你。<br/>對你這位王中王，<br/>萬民有誰不頌揚！<br/>',NULL,7754,7754);
INSERT INTO stanza VALUES('C124','3','你的國度到永遠，<br/>你的寶座永穩堅！<br/>對你榮耀和國權，<br/>我們永遠要頌讚！<br/>對你這位王中王，<br/>千萬聖徒要頌揚！<br/>',NULL,7755,7755);
INSERT INTO stanza VALUES('C124','4','親愛救主、至高王，<br/>你的尊名我愛唱！<br/>你的統治何可親，<br/>願你國度早降臨！<br/>但對你這王中王，<br/>在此我們就頌揚！<br/>',NULL,7756,7756);
INSERT INTO stanza VALUES('C125','1','主，你是神受膏者，<br/>你是萬王之王！<br/>在此俯伏並敬拜，<br/>向你高聲頌揚！<br/>你的國度無窮盡，<br/>你的寶座堅定！<br/>你的治理公而仁，<br/>榮耀無可抗衡。<br/>',NULL,7757,7757);
INSERT INTO stanza VALUES('C125','2','在那錫安聖山上，<br/>神已將你立定，<br/>並將列國賜給你，<br/>作你基業永恆。<br/>祂已將祂的權柄，<br/>完全委託於你，<br/>要你列國全管治，<br/>直到永世無已。<br/>',NULL,7758,7758);
INSERT INTO stanza VALUES('C125','3','日期尚未滿足時，<br/>黑暗尚在掌權，<br/>仍有千萬的群眾，<br/>向你忠貞頌讚！<br/>大洋這岸到那岸，<br/>你民向你歌唱；<br/>敬拜、愛戴、事奉你，<br/>作彼救主－君王！<br/>',NULL,7759,7759);
INSERT INTO stanza VALUES('C125','4','等到豫定的日子，<br/>你要榮中降臨，<br/>地和其上的列國，<br/>都要向你歸順。<br/>滿了光輝和威嚴，<br/>你要被尊為王，<br/>各族、各民和各國，<br/>都要將你頌揚！<br/>',NULL,7760,7760);
INSERT INTO stanza VALUES('C126','1','我的救主，你愛為何<br/>這摯！這寬！這博！<br/>不然，<br/>我心、我命、我力，<br/>那肯完全歸你！<br/>',NULL,7761,7761);
INSERT INTO stanza VALUES('C126','2','我們愛你，因你自己<br/>上下千秋無匹；<br/>我們愛你，因你忍受<br/>十字架的恥羞。<br/>',NULL,7762,7762);
INSERT INTO stanza VALUES('C126','3','人愛所誇，不過就是<br/>代友受死的事；<br/>但你卻為仇敵被殺！<br/>誰曾如此愛法？<br/>',NULL,7763,7763);
INSERT INTO stanza VALUES('C126','4','雖然你有神的形像，<br/>安居榮耀天鄉；<br/>但你卻來成為奴僕，<br/>親歷憂患、痛苦。<br/>',NULL,7764,7764);
INSERT INTO stanza VALUES('C126','5','你願凡事都像世人，<br/>（除了罪惡無分，）<br/>好叫我們完全像你，<br/>雖然前此不一。<br/>',NULL,7765,7765);
INSERT INTO stanza VALUES('C126','6','像你溫柔、像你堅剛<br/>、像你在凡事上！<br/>榮上加榮，天天更變，<br/>直到與你相見。<br/>',NULL,7766,7766);
INSERT INTO stanza VALUES('C126','7','我們的主，我們的心<br/>珍藏你的愛情；<br/>今後我們對你尊名，<br/>永要感激、恭敬。<br/>',NULL,7767,7767);
INSERT INTO stanza VALUES('C127','1','耶穌我主榮耀王，<br/>你愛何等寬廣！<br/>甘離寶座，<br/>親來世界尋迷羊，<br/>誕生馬槽謙卑樣，<br/>又向埃及逃亡，<br/>回加利利，居拿撒勒，<br/>歷風霜；<br/>三十三載役於人，<br/>藐視、厭棄難當；<br/>廣傳福音，報告禧年，<br/>走四方；<br/>殷勤服事忍飢腸，<br/>困乏休息無床；<br/>美哉、善哉、主愛奇哉，<br/>深且長！<br/>',NULL,7768,7768);
INSERT INTO stanza VALUES('C127','2','耶穌我主救世王，<br/>你愛感我衷腸！<br/>客西馬尼備極傷痛，<br/>意愴惶；<br/>汗如血點滴地上，<br/>順從父旨不忘；<br/>捨身救世，面如堅石，<br/>前行壯；<br/>輕看羞辱和苦難，<br/>忍受罪人頂撞；<br/>背負十架，往各各他，<br/>不延宕；<br/>手足被釘，肋受傷，<br/>血、水流出命喪；<br/>美哉、善哉、主愛奇哉，<br/>深且長！<br/>',NULL,7769,7769);
INSERT INTO stanza VALUES('C127','3','耶穌我主得勝王，<br/>你愛何等無量！<br/>十架祈禱，憐憫為懷，<br/>心何廣；<br/>同釘一賊得生望，<br/>可知救恩無疆；<br/>身負重罪，為神離棄，<br/>倍淒涼；<br/>痛徹肺腑，心焦渴，<br/>苦膽、酸醋親嘗；<br/>救贖功成，將靈交神，<br/>打勝仗；<br/>由死復活升天上，<br/>代禱猶如馨香；<br/>美哉、善哉、主愛奇哉，<br/>深且長！<br/>',NULL,7770,7770);
INSERT INTO stanza VALUES('C127','4','耶穌我主平安王，<br/>你愛豈能測量！<br/>我猶罪人，你已代死，<br/>愛明彰；<br/>洗我罪孽，醫我傷，<br/>安慰、憐恤多方；<br/>責備、管教、定我步履、<br/>賜我光，<br/>敵雖兇惡不足懼，<br/>救恩為我城牆；<br/>疲乏、軟弱，你加我力，<br/>使剛強；<br/>仰望我主在天上，<br/>心被恩感歌唱；<br/>美哉、善哉、主愛奇哉，<br/>深且長！<br/>',NULL,7771,7771);
INSERT INTO stanza VALUES('C128','1','我今俯伏主面前，<br/>我希奇主恩典！<br/>像我這樣的罪魁，<br/>主竟拯救歸回！<br/>我本罪人貪世福，<br/>那裡想到要主；<br/>為何無端來尋我，<br/>用愛把我圍著。<br/>',NULL,7772,7772);
INSERT INTO stanza VALUES('C128','2','當時我心因罪惡，<br/>糾纏得真難過，<br/>但我並未求解脫，<br/>你卻前來尋我！<br/>當時我雖聽見你，<br/>但我總是不理，<br/>並且多次反對你，<br/>實是你的仇敵。<br/>',NULL,7773,7773);
INSERT INTO stanza VALUES('C128','3','我實不知為何故，<br/>你竟為我罪辜，<br/>釘死在十字架上，<br/>使我得著平康！<br/>我的罪惡比人多，<br/>我為肉體活著，<br/>我的性情比人壞，<br/>你為甚麼要愛？<br/>',NULL,7774,7774);
INSERT INTO stanza VALUES('C128','4','你生馬槽何寒微！<br/>你的生活何卑！<br/>你到加略受折磨！<br/>你的全是為我！<br/>你在何處看上我？<br/>為何又愛上我？<br/>所以纔如此受苦，<br/>為要使我得福？<br/>',NULL,7775,7775);
INSERT INTO stanza VALUES('C128','5','我比別人有何長？<br/>有何比人高尚？<br/>因此使你離天上，<br/>為我十架命喪？<br/>主阿，當我想自己，<br/>實在無一可以<br/>邀你青眼，使你喜，<br/>我就只得希奇！<br/>',NULL,7776,7776);
INSERT INTO stanza VALUES('C128','6','無他，我今只能說：<br/>你是無故愛我！<br/>哦，你是無故愛我！<br/>哦，這恩真難說！<br/>哦，不是因自己好，<br/>不是因自己高，<br/>乃是你要愛罪魁，<br/>無故的愛罪魁！<br/>',NULL,7777,7777);
INSERT INTO stanza VALUES('C128','7','我既如此的蒙恩，<br/>自然應當認真<br/>愛你、念你、順服你，<br/>纔可對得住你；<br/>但是，可憐到如今<br/>我心仍冷如冰！<br/>雖然明知你恩、愛，<br/>仍是對你懈怠！<br/>',NULL,7778,7778);
INSERT INTO stanza VALUES('C128','8','你雖為我捨性命，<br/>我對你仍無情；<br/>你雖為我離天庭，<br/>我對你只半心。<br/>隱藏世界離不得，<br/>你道路嫌太窄！<br/>微小自己捨不得，<br/>你生命苦太默！<br/>',NULL,7779,7779);
INSERT INTO stanza VALUES('C128','9','當我想到這裡時，<br/>我心若有所失，<br/>自恨性情太敗壞，<br/>自恨生活太歹。<br/>但是，主，你豈不知<br/>我心將要如此！<br/>你既豫知我冷淡，<br/>當初何必恩湛？<br/>',NULL,7780,7780);
INSERT INTO stanza VALUES('C128','10','難道你為我捨命，<br/>擔當痛苦、罪、病，<br/>受盡人世的艱辛，<br/>就是為此冷心！<br/>你既知道我如此，<br/>何苦為我受死？<br/>你既知道我無良，<br/>何竟為我受傷？<br/>',NULL,7781,7781);
INSERT INTO stanza VALUES('C128','11','你雖豫知我冷淡，<br/>對你刻變時翻，<br/>但你仍然要愛我，<br/>為我死，為我活。<br/>當我想到這樣愛，<br/>不知淚從何來，<br/>滿心感激我救主，<br/>希奇你的無故！<br/>',NULL,7782,7782);
INSERT INTO stanza VALUES('C128','12','主阿，對於你大愛，<br/>我真明白不來，<br/>一面我希奇不迨，<br/>一面我要敬拜；<br/>天上福樂雖無比，<br/>我心並不在彼，<br/>我愛作個唱詩人，<br/>讚美我主我神。<br/>',NULL,7783,7783);
INSERT INTO stanza VALUES('C128','13','在那光明榮耀中，<br/>我要不住稱頌，<br/>我要感謝你恩、愛，<br/>我要永遠敬拜。<br/>我望我能在天城，<br/>作主恩、愛標本，<br/>愛雖難答，恩難報，<br/>惟願讚美得好！<br/>',NULL,7784,7784);
INSERT INTO stanza VALUES('C129','1','我有一位奇妙救主，<br/>祂的愛情舉世莫如，<br/>深海雖深，牠還要深，<br/>高天雖高，牠還要高；<br/>亦新、亦陳、<br/>又摯、又真，<br/>不分境地、不理晚早；<br/>祂愛我，讚美祂的名！<br/>',NULL,7785,7785);
INSERT INTO stanza VALUES('C129','2','祂在天上位分至尊，<br/>天使、天軍無不拜頓，<br/>卻因情愛非常堅強，<br/>以至願意撇棄穹蒼，<br/>來尋迷羊，<br/>並且受戕，<br/>捨了天福，又失世賞，<br/>祂尋我，讚美祂的名！<br/>',NULL,7786,7786);
INSERT INTO stanza VALUES('C129','3','祂的道路實在孤單，<br/>沒有同心、沒有同伴；<br/>祂的所有患難、憂愁，<br/>惟祂自己和神知道；<br/>但祂前走，<br/>不稍退後，<br/>直等祂到我的囚牢，<br/>祂見我，讚美祂的名！<br/>',NULL,7787,7787);
INSERT INTO stanza VALUES('C129','4','不久，悲慘日子就到：<br/>祂被人賣，祂被人告，<br/>祂就如此－零丁孤苦，<br/>頭戴荊冕，身受鞭傷，<br/>為我之故，<br/>來髑髏處，<br/>忍辱、受死，疼痛獨當，<br/>祂救我，讚美祂的名！<br/>',NULL,7788,7788);
INSERT INTO stanza VALUES('C129','5','一生一世，我要述說，<br/>祂的愛情超人能度，<br/>當我至終被提祂前，<br/>住在祂所豫備的城，<br/>我心所羨，<br/>是見祂面，<br/>並要敬拜，高聲頌稱，<br/>我愛祂，讚美祂的名！<br/>',NULL,7789,7789);
INSERT INTO stanza VALUES('C130','1','哦主，你愛何等深廣！<br/>過於我所能測度！<br/>你愛深廣，遠超海洋！<br/>這愛竟然臨及我！<br/>你愛叫你捨了自己，<br/>為要叫我得著你，<br/>你愛叫你與我合一，<br/>叫我成為你肢體。<br/>',NULL,7790,7790);
INSERT INTO stanza VALUES('C130','2','你愛所給、所作太多！<br/>過於我所能述說！<br/>最大乃是與我聯合，<br/>並且與我相調和。<br/>你愛叫你成為我的，<br/>作我一切的供應；<br/>叫我享受你的自己，<br/>時時以你為生命。<br/>',NULL,7791,7791);
INSERT INTO stanza VALUES('C130','3','你愛就是你的自己－你那神聖的自己，<br/>作了我的人生意義，<br/>使我活著就是你。<br/>你是我的生命、力量，<br/>你愛給我所經歷；<br/>我是你的恩、愛對象，<br/>所經、所歷全是你。<br/>',NULL,7792,7792);
INSERT INTO stanza VALUES('C130','4','甚麼能使你我分離？<br/>你愛就必愛到底！<br/>你必與我永遠合一，<br/>你愛剛強無可比！<br/>這愛使我感激不已，<br/>是我讚美的目的！<br/>你成為我，<br/>我成為你，<br/>這是你愛的至極！<br/>',NULL,7793,7793);
INSERT INTO stanza VALUES('C131','1','主，當我們飄流曠野，<br/>你愛前來尋我們：<br/>你用恩手逐步提挈，<br/>至終十架捨己身。<br/>唱罷，我魂，祂愛你；<br/>耶穌為我捨自己。<br/>',NULL,7794,7794);
INSERT INTO stanza VALUES('C131','2','聽哪，這是誰的哭聲，<br/>來自溪邊的荒園？<br/>這是我主儆醒守更，<br/>雖然門徒已疲倦。<br/>阿，我魂，祂真愛你；<br/>是的，祂為我捨己。<br/>',NULL,7795,7795);
INSERT INTO stanza VALUES('C131','3','此時祂正對父求懇，<br/>深嘗義怒的滋味，<br/>但祂為著我們罪人，<br/>情願喝乾這苦杯。<br/>阿，愛！我魂，祂愛你！<br/>所以為你捨自己。<br/>',NULL,7796,7796);
INSERT INTO stanza VALUES('C131','4','再後就是慘案末幕：<br/>神的波浪和洪濤，<br/>漫過祂身，使祂痛苦，<br/>纔好使我成新造。<br/>這愛無比又無極！<br/>耶穌為我捨自己。<br/>',NULL,7797,7797);
INSERT INTO stanza VALUES('C131','5','請再聽哪！祂正呼喊：<br/>－當祂見父與己分－神哪、神哪，你竟摧殘<br/>那常順服你的人？<br/>阿，我魂，這是為你；<br/>是的，祂為我捨己。<br/>',NULL,7798,7798);
INSERT INTO stanza VALUES('C131','6','主，我心樂，因你苦難，<br/>現今都已成往事，<br/>你已升天坐父右邊，<br/>永遠活著不再死。<br/>那為我們捨己的，<br/>我魂今活著為你。<br/>',NULL,7799,7799);
INSERT INTO stanza VALUES('C131','7','主，我們因你的奇恩，<br/>現在敬拜、頌讚你；<br/>不久你要成全我們，<br/>與你相見同歡喜。<br/>然而我們今唱說：<br/>耶穌捨己為著我。<br/>',NULL,7800,7800);
INSERT INTO stanza VALUES('C132','1','長似東西無終點，<br/>闊似宇宙無邊岸，<br/>高似高天無限量，<br/>深似深海無底疆，<br/>基督大愛！<br/>',NULL,7801,7801);
INSERT INTO stanza VALUES('C132','chorus','大哉，大哉，大哉，<br/>基督大愛！<br/>長、闊、高、深不能度，<br/>豐滿、優厚臨及我，<br/>直到萬代！<br/>',NULL,7802,7802);
INSERT INTO stanza VALUES('C132','2','長得使祂來捨身，<br/>闊得使祂成救恩，<br/>高得使祂將我升，<br/>深得使祂臨我生，<br/>基督大愛！<br/>',NULL,7803,7803);
INSERT INTO stanza VALUES('C132','3','長得使我得赦免，<br/>闊得使我蒙恩典，<br/>高得使我天上坐，<br/>深得在我裡面活，<br/>基督大愛！<br/>',NULL,7804,7804);
INSERT INTO stanza VALUES('C132','4','長、闊，並非何尺度，<br/>高、深，也非何事物；<br/>『長、』『闊，』<br/>二形乃是指，<br/>『高、』『深，』<br/>二者也都是，<br/>基督大愛！<br/>',NULL,7805,7805);
INSERT INTO stanza VALUES('C133','1','祂是超乎萬人之上，<br/>哦，祂的愛！<br/>比諸兄弟更密、更強，<br/>哦，祂的愛！<br/>地上朋友時常離我，<br/>今日慰我，明日忌我，<br/>但這朋友從不欺我，<br/>哦，祂的愛！<br/>',NULL,7806,7806);
INSERT INTO stanza VALUES('C133','2','我今享受喜樂、安康，<br/>哦，祂的愛！<br/>都虧我主罪債代償，<br/>哦，祂的愛！<br/>祂流寶血，祂買了我，<br/>祂來曠野，祂尋找我，<br/>同歸羊群，祂領導我，<br/>哦，祂的愛！<br/>',NULL,7807,7807);
INSERT INTO stanza VALUES('C133','3','耶穌乃是我們朋友，<br/>哦，祂的愛！<br/>祂賜福氣，祂賜恩祐，<br/>哦，祂的愛！<br/>我心欣幸能瞻仰祂，<br/>叫我安居常倚傍祂，<br/>我怎可以再頂撞祂，<br/>哦，祂的愛！<br/>',NULL,7808,7808);
INSERT INTO stanza VALUES('C133','4','因祂的名我得赦免，<br/>哦，祂的愛！<br/>在仇敵前為我設筵，<br/>哦，祂的愛！<br/>祂使最好福分臨我，<br/>祂禁旨外禍害侵我，<br/>直到榮耀祂在引我，<br/>哦，祂的愛！<br/>',NULL,7809,7809);
INSERT INTO stanza VALUES('C134','1','你的大愛，<br/>過於人所能度，<br/>我救主耶穌！<br/>但不堪的我，<br/>真要知道牠的<br/>高、深、長、闊，<br/>好叫牠的能力越顯越多<br/>在我身上！<br/>',NULL,7810,7810);
INSERT INTO stanza VALUES('C134','2','你的慈愛，<br/>過於人所能論，<br/>我救主耶穌！<br/>但我的嘴脣<br/>要向遠近罪人<br/>勸誨諄諄，<br/>告訴他們，<br/>你愛能解憂困，<br/>並賜喜樂。<br/>',NULL,7811,7811);
INSERT INTO stanza VALUES('C134','3','你的奇愛，<br/>過於人所能讚，<br/>我救主耶穌！<br/>但我的心坎<br/>總要歌唱那愛，<br/>這大！這滿！<br/>因為惡性如我，<br/>也得恩湛，<br/>來親近神！<br/>',NULL,7812,7812);
INSERT INTO stanza VALUES('C134','4','我今雖然不能在這地方<br/>測度、講論、<br/>頌讚愛的泱漭，<br/>但我要帶我的虛空心房，<br/>來到你這愛的泉源良港，<br/>求你充滿！<br/>',NULL,7813,7813);
INSERT INTO stanza VALUES('C134','5','我真是一個虛空的器皿，<br/>對你從無一次戀慕深情，<br/>但我卻能一再來你面前，<br/>求你憐恤、幫助，<br/>得你恩典，<br/>因你愛我！<br/>',NULL,7814,7814);
INSERT INTO stanza VALUES('C134','6','哦我主，<br/>求你用愛充滿我，<br/>領我到天上永活的江河，<br/>讓我用簡單的信到那裡，<br/>倚靠、鑑賞、稱羨<br/>並享受你，<br/>不再他求。<br/>',NULL,7815,7815);
INSERT INTO stanza VALUES('C134','7','當我面對面看見我救主，<br/>當我在祂的寶座前俯伏，<br/>那時，我就要希奇<br/>並歌唱祂的大愛如何<br/>深、高、闊、長，<br/>並要敬拜。<br/>',NULL,7816,7816);
INSERT INTO stanza VALUES('C135','1','哦，願我有千萬舌頭，<br/>前來讚美救主，<br/>說祂恩典何等深厚，<br/>榮耀何等豐富。<br/>',NULL,7817,7817);
INSERT INTO stanza VALUES('C135','2','耶穌這名，慰我苦情，<br/>驅盡我的驚怯，<br/>是我安息、是我生命，<br/>成為我的音樂。<br/>',NULL,7818,7818);
INSERT INTO stanza VALUES('C135','3','祂因愛我，竟願經歷<br/>人世所有苦楚；<br/>祂已消滅罪的能力，<br/>釋放罪的囚徒。<br/>',NULL,7819,7819);
INSERT INTO stanza VALUES('C135','4','我每靜念救我的愛，<br/>立即感覺不配；<br/>不知祂為甚麼恩待<br/>我這人中罪魁。<br/>',NULL,7820,7820);
INSERT INTO stanza VALUES('C135','5','我今作祂愛的俘虜，<br/>甘心作到永久；<br/>因祂為我受死、忍辱，<br/>使我得以自由。<br/>',NULL,7821,7821);
INSERT INTO stanza VALUES('C135','6','我既從你可愛的名，<br/>知你待我美意；<br/>假若我有千萬的心，<br/>也當一一歸你。<br/>',NULL,7822,7822);
INSERT INTO stanza VALUES('C136','1','愛主的人都來，<br/>將你喜樂敞開，<br/>甘甜唱著主的奇愛，<br/>同到寶座前來。<br/>',NULL,7823,7823);
INSERT INTO stanza VALUES('C136','chorus','樂哉，白白恩典！<br/>樂哉，白白恩典！<br/>白白恩典，完全赦免，<br/>樂哉，白白恩典！<br/>',NULL,7824,7824);
INSERT INTO stanza VALUES('C136','2','未識主名的人，<br/>讓他緘默無聲；<br/>主的子民既蒙深恩，<br/>應當喜樂歡騰。<br/>',NULL,7825,7825);
INSERT INTO stanza VALUES('C136','3','未入榮耀之城，<br/>未履精金之街，<br/>郇山佳果甜美豐盈，<br/>豫嘗何等喜悅。<br/>',NULL,7826,7826);
INSERT INTO stanza VALUES('C136','4','故當高聲歌唱，<br/>忘記所有憂傷；<br/>我們昂首向前直往，<br/>屬天、更美家鄉。<br/>',NULL,7827,7827);
INSERT INTO stanza VALUES('C137','1','恩主為我捨棄尊貴，<br/>為我降世處卑微，<br/>為我飽嘗十架苦味，<br/>為我擔當所有罪。<br/>',NULL,7828,7828);
INSERT INTO stanza VALUES('C137','chorus','恩深逾洋海，<br/>真報答不來！<br/>惟有把我全般的愛，<br/>永獻我主宰。<br/>',NULL,7829,7829);
INSERT INTO stanza VALUES('C138','1','主阿，你是神所寶，<br/>是神所悅、所選！<br/>神用樂油將你膏，<br/>勝過膏你同伴。<br/>',NULL,7830,7830);
INSERT INTO stanza VALUES('C138','chorus','我們心中在珍賞，<br/>珍賞你的美善，<br/>珍賞你是何馨香，<br/>珍賞你的甘甜。<br/>',NULL,7831,7831);
INSERT INTO stanza VALUES('C138','2','你比世人更秀美，<br/>你是全然可愛；<br/>你的口中有恩惠，<br/>我們滿心愛戴。<br/>',NULL,7832,7832);
INSERT INTO stanza VALUES('C138','3','你生，博士來獻寶，<br/>自始人就愛戴；<br/>你死，貴人裹香料，<br/>至終仍然可愛。<br/>',NULL,7833,7833);
INSERT INTO stanza VALUES('C138','4','你頭曾為膏所澆，<br/>人所最為愛戴；<br/>你腳也為人所膏，<br/>你是處處可愛。<br/>',NULL,7834,7834);
INSERT INTO stanza VALUES('C138','5','你的受死如沒藥，<br/>安慰人的心靈；<br/>你的復活似香料，<br/>滿足神的心情。<br/>',NULL,7835,7835);
INSERT INTO stanza VALUES('C138','6','在我你香似沒藥，<br/>你美猶如鳳仙，<br/>還像柑樹盛而茂，<br/>果實豐美、香甜。<br/>',NULL,7836,7836);
INSERT INTO stanza VALUES('C138','7','美酒不如你愛美，<br/>你名卻似膏香！<br/>我們以你為寶貴，<br/>怎能忘而不想？<br/>',NULL,7837,7837);
INSERT INTO stanza VALUES('C138','8','我們非僅在默想，<br/>默想你的美善；<br/>我們更是在飽嘗，<br/>飽嘗你的甘甜！<br/>',NULL,7838,7838);
INSERT INTO stanza VALUES('C138','chorus','我們心中在珍賞，<br/>珍賞你的美善，<br/>珍賞你是何馨香，<br/>珍賞你的甘甜。<br/>第六節的『柑樹』是雅歌二章三節『蘋果樹』的另一譯法。<br/>',NULL,7839,7839);
INSERT INTO stanza VALUES('C139','1','『甜美』登極救主額上，<br/>神聖、尊貴、莊嚴；<br/>祂頭披戴榮耀之光，<br/>祂口溢出恩典。<br/>祂口溢出恩典。<br/>',NULL,7840,7840);
INSERT INTO stanza VALUES('C139','2','地上所有必死之人，<br/>與祂相比，誰配？<br/>天上所有天使天軍，<br/>有誰比祂更美？<br/>',NULL,7841,7841);
INSERT INTO stanza VALUES('C139','3','祂是我的生命、氣息、<br/>我的所有喜樂；<br/>使我勝過死的能力，<br/>脫離墳墓幽所。<br/>',NULL,7842,7842);
INSERT INTO stanza VALUES('C139','4','向著父神－我的居所，<br/>祂帶我的腳步；<br/>將神榮耀指示與我，<br/>使我喜樂滿足。<br/>',NULL,7843,7843);
INSERT INTO stanza VALUES('C139','5','我從祂的神聖厚恩，<br/>得知祂愛之大；<br/>倘若我有千萬的心，<br/>也必全都歸祂。<br/>',NULL,7844,7844);
INSERT INTO stanza VALUES('C140','1','主，你是那可愛新郎，<br/>神所選立，我所愛；<br/>你的自己富有吸引，<br/>我心怎能不愛戴！<br/>',NULL,7845,7845);
INSERT INTO stanza VALUES('C140','2','親愛良人，我愛慕你，<br/>你的寶貴誰能言！<br/>你的愛情，我深珍愛，<br/>你的可愛何無限！<br/>',NULL,7846,7846);
INSERT INTO stanza VALUES('C140','3','你比美者還要更美，<br/>你比甜者還更甜！<br/>你既柔細、你又親切，<br/>你是何等的完全！<br/>',NULL,7847,7847);
INSERT INTO stanza VALUES('C140','4','你的衣服滿了沒藥，<br/>你的口中滿恩惠！<br/>在你受苦馨香氣中，<br/>憑愛珍藏你寶貴。<br/>',NULL,7848,7848);
INSERT INTO stanza VALUES('C140','5','神曾用那喜樂的油，<br/>膏你勝過你同伴；<br/>從你那些『象牙宮』中，<br/>發出對你的稱讚。<br/>',NULL,7849,7849);
INSERT INTO stanza VALUES('C140','6','神已永遠賜福與你，<br/>你已勝過眾仇敵；<br/>我今見你加冕、登極，<br/>權柄、威嚴，無可比。<br/>',NULL,7850,7850);
INSERT INTO stanza VALUES('C140','7','你是『萬國所羨慕的，』<br/>他們必知你價值；<br/>你乃『超乎萬人之上，』<br/>永遠配得我賞識！<br/>第五節的『象牙宮』指各地召會。<br/>',NULL,7851,7851);
INSERT INTO stanza VALUES('C141','1','哦主耶穌，每想到你，<br/>我心便覺甘甜；<br/>深願我能立刻被提，<br/>到你可愛身邊！<br/>',NULL,7852,7852);
INSERT INTO stanza VALUES('C141','chorus','主，你如一棵美麗鳳仙，<br/>顯在山野葡萄園間，<br/>殊姿超群、秀色獨豔，<br/>我心依依戀戀。<br/>',NULL,7853,7853);
INSERT INTO stanza VALUES('C141','2','世上並無一個妙音，<br/>能把你恩盡唱；<br/>人間也無一顆情心，<br/>能把你愛全享。<br/>',NULL,7854,7854);
INSERT INTO stanza VALUES('C141','3','但那最使我心歡喜，<br/>尚非你愛、你恩；<br/>乃是你的可愛自己，<br/>最滿我情、我心。<br/>',NULL,7855,7855);
INSERT INTO stanza VALUES('C141','4','你比美者還要更美，<br/>你比甜者更甜；<br/>你外，在天我心何歸？<br/>在地我心何戀？<br/>',NULL,7856,7856);
INSERT INTO stanza VALUES('C142','1','涼爽，你像柔和微風，<br/>怎能將你吸彀！<br/>芬芳勝過所有花叢，<br/>如同沒藥在我懷中，<br/>又像天上膏油！<br/>又像天上膏油！<br/>',NULL,7857,7857);
INSERT INTO stanza VALUES('C142','2','滋潤，你像清晨甘露，<br/>怎能被你浸彀！<br/>新鮮、清涼、<br/>消乾、解枯、<br/>滋我心情、潤我深處；<br/>願你將我浸透，<br/>願你將我浸透。<br/>',NULL,7858,7858);
INSERT INTO stanza VALUES('C142','3','你是美麗中的至美，<br/>怎能將你賞彀！<br/>你的面容所發光輝，<br/>使我更感你美可貴：<br/>你是美中之首！<br/>你是美中之首！<br/>',NULL,7859,7859);
INSERT INTO stanza VALUES('C142','4','你名香甜遠超眾名，<br/>怎能將你唱彀！<br/>我心充滿甜美感應，<br/>深願向你不住頌稱！<br/>喜樂湧自心頭，<br/>喜樂湧自心頭。<br/>',NULL,7860,7860);
INSERT INTO stanza VALUES('C142','5','你的自己可愛、饒優，<br/>怎能將你說彀！<br/>你心柔細，同情、俯就，<br/>吸引我心向你倚投，<br/>細語：『有你就彀！』<br/>細語：『有你就彀！』<br/>',NULL,7861,7861);
INSERT INTO stanza VALUES('C143','1','最美的耶穌！<br/>管理『自然』的主！<br/>神子、人子！永活的道，<br/>你是我所愛，<br/>我所永感戴，<br/>我的喜樂、我的誇耀！<br/>',NULL,7862,7862);
INSERT INTO stanza VALUES('C143','2','草地何青綠！<br/>樹木更加悅目！<br/>披著春花，盛開爭豔！<br/>耶穌更鮮豔！<br/>耶穌更香甜！<br/>傷痛之心因祂歡讚。<br/>',NULL,7863,7863);
INSERT INTO stanza VALUES('C143','3','日光何晴美！<br/>月光更加明媚！<br/>群星閃爍，光輝奪目！<br/>耶穌更明亮！<br/>耶穌更晴朗！<br/>勝過天上一切景物！<br/>',NULL,7864,7864);
INSERT INTO stanza VALUES('C143','4','所有的美麗，<br/>在天或是在地，<br/>在你身上全都見到；<br/>無何更光彩，<br/>無何更可愛！<br/>惟我救主，你最高超！<br/>',NULL,7865,7865);
INSERT INTO stanza VALUES('C144','1','我們要從那裡說起，<br/>主，你所賜一切福氣？<br/>既然脫罪不作奴隸，<br/>既然免死不作仇敵；<br/>我當如何向你拜禮，<br/>把你高舉纔算適宜？<br/>',NULL,7866,7866);
INSERT INTO stanza VALUES('C144','2','你向我們所施安撫，<br/>我們怎能用口傾吐？<br/>可怒之子當下火湖，<br/>竟然得救，以神為父！<br/>在地我知罪已抹塗，<br/>真是豫享屬天美福。<br/>',NULL,7867,7867);
INSERT INTO stanza VALUES('C144','3','我們的心滿是基督，<br/>切望傾倒此中豐富；<br/>你是我們詩歌題目，<br/>你是我們心愛救主；<br/>我們舌頭急要唱出：<br/>天上君王榮耀萬古！<br/>',NULL,7868,7868);
INSERT INTO stanza VALUES('C144','4','你比世上一切眾生，<br/>都更美麗、都更成聖；<br/>你心有愛，你口有恩；<br/>你既受苦、你又捨身；<br/>你這永受頌讚的神！<br/>我們敬拜以靈以真。<br/>',NULL,7869,7869);
INSERT INTO stanza VALUES('C145','1','耶穌，奇妙救主！<br/>基督，王中王！<br/>天使敬拜俯伏，<br/>我們也頌揚；<br/>他們在天承認<br/>你乃美至極；<br/>我們也在愛吟<br/>你是最美麗。<br/>',NULL,7870,7870);
INSERT INTO stanza VALUES('C145','2','地上所有安逸，<br/>盡都是空穴；<br/>天上缺少了你，<br/>也變成黑夜。<br/>基督，你的榮耀<br/>乃是天上光；<br/>耶穌，你的榮耀<br/>使地也明亮。<br/>',NULL,7871,7871);
INSERT INTO stanza VALUES('C145','3','如果與你分開，<br/>生命變死亡；<br/>若是有你同在，<br/>死中生仍旺。<br/>宇宙、人類、天使，<br/>全由你造成，<br/>然而你肯降世，<br/>穿上人性情。<br/>',NULL,7872,7872);
INSERT INTO stanza VALUES('C145','4','耶穌！一切美善，<br/>始終全在你；<br/>神的榮耀光線，<br/>乃是你自己。<br/>人若得見你面，<br/>是蒙了奇恩；<br/>但願你這恩典，<br/>我也滿有分。<br/>',NULL,7873,7873);
INSERT INTO stanza VALUES('C146','1','我們當來同聲歡呼，<br/>稱頌神的基督；<br/>我們若有千萬舌頭，<br/>詩歌只有一首。<br/>',NULL,7874,7874);
INSERT INTO stanza VALUES('C146','2','『升天羔羊，你真是配，<br/>來得這樣讚美！』<br/>我們喊說：『你真是配，<br/>因你為我降卑！』<br/>',NULL,7875,7875);
INSERT INTO stanza VALUES('C146','3','救主耶穌配得尊貴、<br/>權柄、榮耀、智慧；<br/>還有許多獻上不及，<br/>主阿，永都歸你！<br/>',NULL,7876,7876);
INSERT INTO stanza VALUES('C146','4','不久聖徒快要上升，<br/>同發讚美之聲；<br/>一切住在青天之下，<br/>都要頌揚不暇！<br/>',NULL,7877,7877);
INSERT INTO stanza VALUES('C146','5','待贖宇宙合而為一，<br/>頌讚羔羊不已；<br/>因祂降世，親臨死地，<br/>現今榮耀無比。<br/>',NULL,7878,7878);
INSERT INTO stanza VALUES('C147','1','榮耀歸於我主，<br/>天地齊來歡呼，<br/>向祂讚美；<br/>祂的恩典、慈愛，<br/>除我死亡、悲哀；<br/>高唱直到萬代，<br/>『羔羊是配。』<br/>',NULL,7879,7879);
INSERT INTO stanza VALUES('C147','2','蒙恩人們都來，<br/>環繞寶座敬拜，<br/>向祂讚美；<br/>為我寶血流出，<br/>與神和好無阻；<br/>讚頌之聲四佈，<br/>『羔羊是配。』<br/>',NULL,7880,7880);
INSERT INTO stanza VALUES('C147','3','被贖族類都來，<br/>同心向主敬拜，<br/>向祂讚美；<br/>因祂我得歡樂，<br/>發出感恩詩歌，<br/>起來，口唱心和，<br/>『羔羊是配。』<br/>',NULL,7881,7881);
INSERT INTO stanza VALUES('C147','4','事物雖然改遷，<br/>但我依舊不變，<br/>向祂讚美；<br/>詩歌不絕頌揚，<br/>尊祂我主我王，<br/>歡聲上達穹蒼，<br/>『羔羊是配。』<br/>',NULL,7882,7882);
INSERT INTO stanza VALUES('C148','1','哦主耶穌，<br/>我的心向著寶座，<br/>何等喜樂，<br/>向你獻上讚美！<br/>因著蒙福，<br/>我敬拜，我也述說，<br/>承認你配，<br/>惟有你真是配。<br/>',NULL,7883,7883);
INSERT INTO stanza VALUES('C148','chorus','主，你真是配！<br/>主，你真是配！<br/>讚美，因為惟有你<br/>真是配！<br/>因著蒙福，我敬拜，<br/>我也述說你的榮耀，<br/>因為你真是配。<br/>',NULL,7884,7884);
INSERT INTO stanza VALUES('C148','2','你這神人，是真神，<br/>又是真人，<br/>低於天使，<br/>為我們作犧牲；<br/>女人後裔，<br/>曾如何親臨囂塵，<br/>敗壞古蛇，<br/>傷其頭，踏其身！<br/>',NULL,7885,7885);
INSERT INTO stanza VALUES('C148','3','創造的主，竟然被<br/>受造的人釘十字架，<br/>你是如何降卑！<br/>你不自救，<br/>被神棄又被人恨！<br/>你不退縮，<br/>經黑暗，喝苦杯！<br/>',NULL,7886,7886);
INSERT INTO stanza VALUES('C148','4','接戰死亡，<br/>你如何退其狂瀾，<br/>榮耀得勝，<br/>全得勝，大得勝！<br/>思念及此，<br/>怎能不歌頌彌漫！<br/>陰府的門，<br/>到如今全潰崩。<br/>',NULL,7887,7887);
INSERT INTO stanza VALUES('C149','1','我主耶穌，惟你是配，<br/>來得永遠的讚美，<br/>因你愛心、恩典、慈良，<br/>遠超我們所能想。<br/>',NULL,7888,7888);
INSERT INTO stanza VALUES('C149','2','我們滿心感激不盡，<br/>前來稱頌你尊名；<br/>一生一世滿被恩惠，<br/>到處述說你寶貴。<br/>',NULL,7889,7889);
INSERT INTO stanza VALUES('C149','3','我們所拜的主耶穌，<br/>你是何等的寬恕；<br/>你的愛心像你能力，<br/>永無限量永無已。<br/>',NULL,7890,7890);
INSERT INTO stanza VALUES('C149','4','耶穌，你是首先、末後，<br/>你要領我到盡頭；<br/>因著已往我讚美你，<br/>為著將來我靠你。<br/>',NULL,7891,7891);
INSERT INTO stanza VALUES('C149','5','讚祂！讚祂！讚我恩人！<br/>聖徒們哪，當高聲！<br/>讚祂！讚祂！直到天上，<br/>讚得完全讚得長。<br/>',NULL,7892,7892);
INSERT INTO stanza VALUES('C150','1','哦主，你是何等包羅，<br/>我竟得在你裡！<br/>神要你作我們永分，<br/>我的一切是你。<br/>',NULL,7893,7893);
INSERT INTO stanza VALUES('C150','2','神使你作我們智慧，<br/>我們因你得救；<br/>你是惟一得救之路，<br/>惟一蒙恩之由。<br/>',NULL,7894,7894);
INSERT INTO stanza VALUES('C150','3','神使你作我們公義，<br/>滿足神的要求；<br/>在你裡面我得稱義，<br/>再無何罪可究。<br/>',NULL,7895,7895);
INSERT INTO stanza VALUES('C150','4','神使你作我們聖潔，<br/>為將我們變化；<br/>在你裡面我被聖別，<br/>直到與你無差。<br/>',NULL,7896,7896);
INSERT INTO stanza VALUES('C150','5','神使你作我們救贖，<br/>為要我們像你；<br/>你要改變我們身體，<br/>我就與你無異。<br/>',NULL,7897,7897);
INSERT INTO stanza VALUES('C150','6','主，當我們在此記念，<br/>享受你的所是；<br/>真願催促你快回來，<br/>不再有所延遲。<br/>',NULL,7898,7898);
INSERT INTO stanza VALUES('C150','7','這個豫嘗何等甘甜，<br/>已足令人滿意；<br/>但我仍望與你同在，<br/>滿享你的自己。<br/>',NULL,7899,7899);
INSERT INTO stanza VALUES('C151','1','主，你是那永久磐石，<br/>屬靈磐石為我裂；<br/>靈中飲於你流活水，<br/>就得與你永聯結。<br/>你是磐石，永遠穩固，<br/>我在其上被建造；<br/>藉著救贖，與你聯合，<br/>無何能將我動搖。<br/>',NULL,7900,7900);
INSERT INTO stanza VALUES('C151','chorus','我們珍貴你的價值，<br/>你之所是全為我；<br/>我們在此因愛記念，<br/>滿享你富的廣闊。<br/>',NULL,7901,7901);
INSERT INTO stanza VALUES('C151','2','你是石頭，多人試過，<br/>神所寶貴，我所愛；<br/>極其穩固、極其可靠，<br/>你的力量永不衰。<br/>你也是那永生活石，<br/>神所揀選，歸我們；<br/>何其堅強、何其有力，<br/>無窮生命是我分。<br/>',NULL,7902,7902);
INSERT INTO stanza VALUES('C151','3','你又是那神聖基石，<br/>神所安放，穩而堅；<br/>藉著你這穩固根基，<br/>我們永遠享安全。<br/>對於我們，在你之外，<br/>無人能立別根基；<br/>你是我們惟一基礎，<br/>直到永遠不更移。<br/>',NULL,7903,7903);
INSERT INTO stanza VALUES('C151','4','為著神的屬靈建造，<br/>你是房角的首石；<br/>猶太、外邦，成為一體，<br/>建造全靠你所是。<br/>主，你也是那塊頂石，<br/>無限恩典所搬出；<br/>你是我們遮蓋、榮耀，<br/>我們心中滿歌賦。<br/>',NULL,7904,7904);
INSERT INTO stanza VALUES('C152','1','主，你於我何其豐富，<br/>你愛說出其度量！<br/>你的自己無限富有，<br/>今在我靈給我享。<br/>',NULL,7905,7905);
INSERT INTO stanza VALUES('C152','2','你乃是話，也就是神，<br/>太初就與神同在；<br/>成為肉身，與人同處，<br/>將神向人說出來。<br/>',NULL,7906,7906);
INSERT INTO stanza VALUES('C152','3','你乃是神真的帳幕，<br/>在你我見神榮耀；<br/>你也是神真的聖殿，<br/>在你裡面神住著。<br/>',NULL,7907,7907);
INSERT INTO stanza VALUES('C152','4','你乃是神獨生愛子，<br/>永遠將父來表明，<br/>使我能有神的生命，<br/>並且有分神性情。<br/>',NULL,7908,7908);
INSERT INTO stanza VALUES('C152','5','你是人子，與我一樣，<br/>確有我們的性情，<br/>使我能作神的兒子，<br/>直到滿有你榮形。<br/>',NULL,7909,7909);
INSERT INTO stanza VALUES('C152','6','你是基督，有的主，<br/>是神所膏彌賽亞；<br/>你是萬有，又在萬有，<br/>神人所賴，無限大！<br/>',NULL,7910,7910);
INSERT INTO stanza VALUES('C152','7','你是救主，釘死十架，<br/>從你流出血和水，<br/>使我得蒙神的救贖，<br/>有神生命，成寶貴！<br/>',NULL,7911,7911);
INSERT INTO stanza VALUES('C152','8','你今是那得榮耶穌，<br/>從你降下生命靈；<br/>祂是包羅萬有的靈，<br/>來使我享你豐盛。<br/>',NULL,7912,7912);
INSERT INTO stanza VALUES('C152','9','你是神聖生命之光，<br/>黑暗之中來照亮；<br/>在我心中，帶神照亮，<br/>直到充滿我心房。<br/>',NULL,7913,7913);
INSERT INTO stanza VALUES('C152','10','你是神聖永遠生命，<br/>點活我們死的靈；<br/>你使我們脫離死亡，<br/>享受生命的豐盛。<br/>',NULL,7914,7914);
INSERT INTO stanza VALUES('C152','11','主，你乃是神的實際，<br/>惟你能使神喜悅；<br/>你這實際使我知道<br/>你是如何用不竭。<br/>',NULL,7915,7915);
INSERT INTO stanza VALUES('C152','12','主，你也是惟一道路，<br/>使我進入神自己；<br/>生命之道，實際之路，<br/>將我帶進榮耀裡。<br/>',NULL,7916,7916);
INSERT INTO stanza VALUES('C152','13','主，你又是奇妙復活，<br/>所有死亡全勝過；<br/>使我藉你復活大能，<br/>與你同死並同活。<br/>',NULL,7917,7917);
INSERT INTO stanza VALUES('C152','14','你是神的無瑕羔羊，<br/>救贖為我來作成；<br/>你也是那賜聖靈者，<br/>為著使我得生命。<br/>',NULL,7918,7918);
INSERT INTO stanza VALUES('C152','15','你是杆上所掛銅蛇，<br/>救我脫離致死罪；<br/>你在十架被人舉起，<br/>掌死魔鬼為我毀。<br/>',NULL,7919,7919);
INSERT INTO stanza VALUES('C152','16','你是牧人，又是羊門，<br/>使我脫離律法圈，<br/>藉你我今已得自由，<br/>青草地上嘗甘甜。<br/>',NULL,7920,7920);
INSERT INTO stanza VALUES('C152','17','你的洗滌使我潔淨，<br/>功能如同洗濯盆；<br/>將我保守在你交通，<br/>享你恩愛無窮盡。<br/>',NULL,7921,7921);
INSERT INTO stanza VALUES('C152','18','你是磐石為我裂開，<br/>流出生命的活水；<br/>飲於你這常新水流，<br/>得脫一切的困憊。<br/>',NULL,7922,7922);
INSERT INTO stanza VALUES('C152','19','你是屬天永生泉源，<br/>活水藏在你裡面；<br/>喝了你這永生活水，<br/>不再乾渴到永遠。<br/>',NULL,7923,7923);
INSERT INTO stanza VALUES('C152','20','你是天降生命的糧，<br/>神聖、豐富又盛旺，<br/>帶著你的無限豐富，<br/>時將我靈來餧養。<br/>',NULL,7924,7924);
INSERT INTO stanza VALUES('C152','21','你是我們生命之氣，<br/>給我靈中來呼吸；<br/>靠你生活，憑你行動，<br/>就得享受你自己。<br/>',NULL,7925,7925);
INSERT INTO stanza VALUES('C152','22','你是一粒神聖麥子，<br/>甘願落到死地裡，<br/>結出我們許多子粒，<br/>作你奧祕的身體。<br/>',NULL,7926,7926);
INSERT INTO stanza VALUES('C152','23','你是屬天真葡萄樹，<br/>我們是你的枝子；<br/>住在你裡，與你聯結，<br/>享受一切你所是。<br/>',NULL,7927,7927);
INSERT INTO stanza VALUES('C152','24','你是宇宙真的新郎，<br/>我們是你的新婦；<br/>靈裡與你成為一體，<br/>得享你愛的豐富。<br/>',NULL,7928,7928);
INSERT INTO stanza VALUES('C152','25','你是雅各所見天梯，<br/>藉你天向地而開；<br/>靠你我們作神聖殿，<br/>地聯於天無阻礙。<br/>',NULL,7929,7929);
INSERT INTO stanza VALUES('C152','26','哦主，你是那<br/>『我是』的，<br/>應付我們所需要；<br/>享受你作一切一切，<br/>神就因你得榮耀。<br/>',NULL,7930,7930);
INSERT INTO stanza VALUES('C153','1','主，你是我照護侍從，<br/>也是我保惠師；<br/>你又是我誠信中保，<br/>神前為我辦事。<br/>',NULL,7931,7931);
INSERT INTO stanza VALUES('C153','2','你是我的辯護顧問，<br/>也是我辯護者；<br/>是我凡事的代禱者，<br/>也是我幫助者。<br/>',NULL,7932,7932);
INSERT INTO stanza VALUES('C153','3','主，你照著神所喜悅，<br/>為我辦理一切；<br/>你在天上，又在我裡，<br/>凡事為我解決。<br/>',NULL,7933,7933);
INSERT INTO stanza VALUES('C153','4','你乃是那內住之靈，<br/>時常為我代禱；<br/>天上辯護，我裡歎息，<br/>代我向神求告。<br/>',NULL,7934,7934);
INSERT INTO stanza VALUES('C153','5','永遠活著，照神旨意，<br/>施恩、幫助惟殷；<br/>藉著復活生命大能，<br/>加強裡面的人。<br/>',NULL,7935,7935);
INSERT INTO stanza VALUES('C153','6','你是那賜生命之靈，<br/>時常顧我軟弱；<br/>在我靈中，用你大能，<br/>使我憑你活著。<br/>',NULL,7936,7936);
INSERT INTO stanza VALUES('C153','7','藉你愛憐，以你自己，<br/>永遠服事、眷念；<br/>好使你作我們一切，<br/>我們作你豐滿。<br/>',NULL,7937,7937);
INSERT INTO stanza VALUES('C154','1','遠在時間尚未起首，<br/>萬有尚都未開始，<br/>在父懷中並榮耀裡，<br/>你是神的獨生子。<br/>當父將你賜給我們，<br/>你的身位仍一樣，<br/>為將父的所有豐滿，<br/>藉著聖靈來表揚。<br/>',NULL,7938,7938);
INSERT INTO stanza VALUES('C154','2','藉著你死並你復活，<br/>你就成為神長子；<br/>藉著重生分賜生命，<br/>我們成為神眾子。<br/>我們是你生命繁殖，<br/>是你許多的弟兄，<br/>我們是你榮耀複本，<br/>是你神聖的擴充。<br/>',NULL,7939,7939);
INSERT INTO stanza VALUES('C154','3','你曾是那惟一麥粒，<br/>落到地裡而死了；<br/>藉著死亡，並藉復活，<br/>顯出繁殖的榮耀。<br/>你使我們由你得生，<br/>變成許多的子粒；<br/>眾人調和成為一餅，<br/>作你豐滿的身體。<br/>',NULL,7940,7940);
INSERT INTO stanza VALUES('C154','4','我們是你的複製品、<br/>是你身體並新婦、<br/>是你表現、是你豐滿，<br/>永遠讓你來居住。<br/>我們是你普及、繼續、<br/>是你生命的開展、<br/>是你長成、是你富餘，<br/>與你合一永無間。<br/>',NULL,7941,7941);
INSERT INTO stanza VALUES('C155','1','古時一切豫表、影像，<br/>全都是你的描繪；<br/>正如這些所表所徵，<br/>你今於我何寶貴！<br/>當我注視這幅圖畫，<br/>欣賞各方的優越，<br/>我就驚奇你的豐美，<br/>敬拜你是我一切！<br/>',NULL,7942,7942);
INSERT INTO stanza VALUES('C155','2','恩主，你是我逾越節，<br/>因你神將我逾越；<br/>藉你自己和你救贖，<br/>我們得與神和諧。<br/>主，你也是神的羔羊，<br/>被殺、流血、救贖我；<br/>應用你血作我贖價，<br/>並靠喫你而活著。<br/>',NULL,7943,7943);
INSERT INTO stanza VALUES('C155','3','你是天降生命的糧，<br/>就是無酵生命餅；<br/>我們喫你，與你調和，<br/>就得有分你功能。<br/>羔羊和餅都是豫表，<br/>象徵你是我生命；<br/>筵席之上喫你、喝你，<br/>我們享受你豐盛。<br/>',NULL,7944,7944);
INSERT INTO stanza VALUES('C155','4','主，你也是屬天嗎哪，<br/>我們每日的食物；<br/>餧養、飽足、剛強、<br/>加力，<br/>所有需要全應付。<br/>主，你又是活的磐石，<br/>為我裂開，生命流；<br/>飲於你這生命活水，<br/>不再乾渴到永久。<br/>',NULL,7945,7945);
INSERT INTO stanza VALUES('C155','5','主，你更是迦南美地，<br/>超越、豐富又佳美，<br/>流奶與蜜，各物豐收，<br/>凡我需要無不備。<br/>憑你豐餘向神敬拜，<br/>並且藉此相交通，<br/>如此愛中彼此聯結，<br/>神的建造得成功。<br/>',NULL,7946,7946);
INSERT INTO stanza VALUES('C156','1','恩主，你是公義太陽，<br/>富有醫治光線；<br/>你的榮耀面光照臨，<br/>帶來生命、平安。<br/>',NULL,7947,7947);
INSERT INTO stanza VALUES('C156','2','慈愛神的憐憫心腸，<br/>叫你臨到我們，<br/>為要照亮坐在黑暗<br/>死蔭之中的人。<br/>',NULL,7948,7948);
INSERT INTO stanza VALUES('C156','3','對我你像無雲清晨，<br/>又如日出晨光；<br/>我們乃像地上嫩草，<br/>靠你光線生長。<br/>',NULL,7949,7949);
INSERT INTO stanza VALUES('C156','4','恩光帶著可愛光線，<br/>擴增猶如天曙；<br/>在我裡面越照越明，<br/>直至中天日午。<br/>',NULL,7950,7950);
INSERT INTO stanza VALUES('C156','5','清明光線照透苦難，<br/>猶如雨後晴光；<br/>帶著你的憐憫、慈愛，<br/>永不停止照亮。<br/>',NULL,7951,7951);
INSERT INTO stanza VALUES('C156','6','主，你也是明亮晨星，<br/>作我儆醒賞賜；<br/>照亮那些愛你之人，<br/>正當黑暗深時。<br/>',NULL,7952,7952);
INSERT INTO stanza VALUES('C156','7','求主使我愛慕你光，<br/>使我眼光清明；<br/>儆醒、禱告、等候你來，<br/>猶如等候晨星。<br/>',NULL,7953,7953);
INSERT INTO stanza VALUES('C157','1','主，當我們把你思念，<br/>因你所是我們敬拜；<br/>你是如此豐富、奇妙，<br/>何其可寶、何其可愛！<br/>',NULL,7954,7954);
INSERT INTO stanza VALUES('C157','chorus','你之所是正合我需！<br/>我心對你讚美洋溢！<br/>我之所願你全滿足，<br/>綽綽有餘，應付不已！<br/>',NULL,7955,7955);
INSERT INTO stanza VALUES('C157','2','實實在在你真是神，<br/>是那是光是愛之神；<br/>是神，你作我們生命，<br/>是神，你向我們賜恩。<br/>',NULL,7956,7956);
INSERT INTO stanza VALUES('C157','3','實實在在你也是人，<br/>是一柔細、純良的人；<br/>是人，你使神心喜悅，<br/>是人，你能得著我心。<br/>',NULL,7957,7957);
INSERT INTO stanza VALUES('C157','4','你竟也是卑微奴僕，<br/>為著我們作神奴僕；<br/>甘心順服以至於死，<br/>為使我們得救、蒙福。<br/>',NULL,7958,7958);
INSERT INTO stanza VALUES('C157','5','此外，恩主，你還是王，<br/>為神所膏、是神所立；<br/>藉著生命和愛掌權，<br/>帶著我們一同治理。<br/>',NULL,7959,7959);
INSERT INTO stanza VALUES('C157','6','主，當我們在此記念，<br/>我們分享你之所是；<br/>愛中享受你的自己，<br/>如此享受直到永世！<br/>',NULL,7960,7960);
INSERT INTO stanza VALUES('C158','1','哦主，你是阿拉法，<br/>你也是俄梅嘎；<br/>你前並無更前者，<br/>你後也無可加。<br/>你是惟一的元始，<br/>也是萬事之終；<br/>萬有包括在你裡，<br/>你是萬有之總。<br/>',NULL,7961,7961);
INSERT INTO stanza VALUES('C158','2','主，因你是阿拉法，<br/>萬有由你開始；<br/>因你也是俄梅嘎，<br/>萬有在你而止。<br/>又是全部的字母，<br/>一切由你組成；<br/>既是所有的字母，<br/>一切為你托撐。<br/>',NULL,7962,7962);
INSERT INTO stanza VALUES('C158','3','你是受造首先者，<br/>你是萬有之首；<br/>你是一切末後者，<br/>你來結束萬有。<br/>你是受造首先者，<br/>萬有由你而來；<br/>你是一切末後者，<br/>萬有靠你存在。<br/>',NULL,7963,7963);
INSERT INTO stanza VALUES('C158','4','你是一切的元始，<br/>你在萬有之前；<br/>你是一切的終結，<br/>萬有歸你承攬。<br/>你是獨一的元始，<br/>萬有由你創始；<br/>你是無二的終結，<br/>萬有歸你終止。<br/>',NULL,7964,7964);
INSERT INTO stanza VALUES('C158','5','哦主，我們敬拜你，<br/>以愛將你珍賞；<br/>阿拉法及俄梅嘎，<br/>乃在萬有之上。<br/>讚美你是元始者，<br/>你在一切之先；<br/>敬拜你是終結者，<br/>你後何可加添？<br/>',NULL,7965,7965);
INSERT INTO stanza VALUES('C159','1','主，你乃是那生命樹，<br/>生命惟一出處；<br/>你的果子富有生命，<br/>作我最美食物。<br/>',NULL,7966,7966);
INSERT INTO stanza VALUES('C159','2','你是屬天真葡萄樹，<br/>生命供應源頭；<br/>住在你裡，靠你生活，<br/>得享你的富有。<br/>',NULL,7967,7967);
INSERT INTO stanza VALUES('C159','3','主，你也是那蘋果樹，<br/>給我享受欣賞；<br/>你的果子滋味甘甜，<br/>在你蔭下得嘗。<br/>',NULL,7968,7968);
INSERT INTO stanza VALUES('C159','4','主，你更是醫治之樹，<br/>曾經為我受死；<br/>掛在木上為我被殺，<br/>使我得到醫治。<br/>',NULL,7969,7969);
INSERT INTO stanza VALUES('C159','5','你是神的獨一枝子，<br/>藏著神的豐滿；<br/>在你我們得享神作<br/>無限實際、恩典。<br/>',NULL,7970,7970);
INSERT INTO stanza VALUES('C159','6','主，你也是大衛之枝，<br/>藉成肉身而成；<br/>在你我們得以領略<br/>何為真實人性。<br/>',NULL,7971,7971);
INSERT INTO stanza VALUES('C159','7','你是神的發芽之杖，<br/>含有無窮生命；<br/>死亡永遠不能勝過<br/>你那復活大能。<br/>',NULL,7972,7972);
INSERT INTO stanza VALUES('C159','8','你是那根漂起之木，<br/>我是沉水『斧頭；』<br/>藉你生命超越大能，<br/>得從死水起浮。<br/>',NULL,7973,7973);
INSERT INTO stanza VALUES('C159','9','你是如此『有名植物，』<br/>我得豐富分享；<br/>主，當我們在此記念，<br/>我願將你頌揚。<br/>『有名植物』見以西結三十四章二十九節。<br/>',NULL,7974,7974);
INSERT INTO stanza VALUES('C160','1','哦主，你是神的見證，<br/>遠非律法能比；<br/>律法不過是你小影，<br/>你是律法實際。<br/>律法僅是神的說明，<br/>描述神是如何；<br/>而你乃是神的實際，<br/>神在你裡住著。<br/>',NULL,7975,7975);
INSERT INTO stanza VALUES('C160','2','約櫃也是你的豫表，<br/>其中僅有律法；<br/>但你裡面有神自己，<br/>帶著一切安家。<br/>約櫃乃用堅實木料，<br/>上面包金而造；<br/>豫表你有正確人性，<br/>並有神性相調。<br/>',NULL,7976,7976);
INSERT INTO stanza VALUES('C160','3','你也是那真實帳幕，<br/>有神住你裡面；<br/>你成肉身，與人同住，<br/>滿有真理、恩典。<br/>在你人見神的榮耀，<br/>你是神的活話；<br/>你憑光、愛所有言行，<br/>是神活的圖畫。<br/>',NULL,7977,7977);
INSERT INTO stanza VALUES('C160','4','聖殿也是你的豫表，<br/>你是神的真殿；<br/>神帶一切居住於你，<br/>藉你得著彰顯。<br/>撒但雖盡其力拆毀，<br/>將你置於死地，<br/>但你卻在復活裡面，<br/>更大之殿建起。<br/>',NULL,7978,7978);
INSERT INTO stanza VALUES('C160','5','聖城象徵你的豐滿，<br/>是你新婦小影；<br/>這是你的豐滿擴充，<br/>出於你的豐盛。<br/>神在你裡作城的光，<br/>你是城中明燈；<br/>帶神經她照亮眾人，<br/>將神榮耀顯明。<br/>',NULL,7979,7979);
INSERT INTO stanza VALUES('C160','6','哦主，<br/>帳幕、約櫃、律法，<br/>以及聖殿、聖城，<br/>全都是你寶貴自己，<br/>說出你的豐盛。<br/>中心是你，圓周是你、<br/>一切全都是你！<br/>神、人全都在你一身，<br/>我心寶愛、稱奇。<br/>',NULL,7980,7980);
INSERT INTO stanza VALUES('C161','1','哦主，於我你是何豐，<br/>是我一切一切；<br/>我的需要無論多多，<br/>你全應付無缺。<br/>我心欣賞你之所是，<br/>我靈向你敬拜；<br/>因著享受你的豐富，<br/>對你滿了感戴。<br/>',NULL,7981,7981);
INSERT INTO stanza VALUES('C161','2','你是先知，神所興起，<br/>富有神的權能；<br/>如同摩西，指明神意，<br/>我們得以照行。<br/>又像約拿，被神差遣，<br/>經過死而復活；<br/>藉這死與生的表記，<br/>使我相信悔過。<br/>',NULL,7982,7982);
INSERT INTO stanza VALUES('C161','3','你是先知，人間興起，<br/>滿有亮光、能力；<br/>像以利沙，充滿愛心，<br/>對人廣行神蹟。<br/>像以賽亞，滿有恩惠，<br/>啟示神的基督，<br/>使我得享祂作一切，<br/>實際而又豐富。<br/>',NULL,7983,7983);
INSERT INTO stanza VALUES('C161','4','你是祭司，人間選出，<br/>作我聖潔祭司；<br/>好像亞倫，蒙神所召，<br/>代人神前服事。<br/>憑愛將我帶到神前，<br/>像大祭司一般；<br/>因愛在彼為我代禱，<br/>我的軟弱承擔。<br/>',NULL,7984,7984);
INSERT INTO stanza VALUES('C161','5','你是祭司，神所差來，<br/>作神君尊祭司；<br/>像撒冷王，麥基洗德，<br/>為神前來服事。<br/>帶餅和酒從神而來，<br/>作我應時供應；<br/>將神帶來，使我得享<br/>祂的所有豐盛。<br/>',NULL,7985,7985);
INSERT INTO stanza VALUES('C161','6','你是君王，如同大衛，<br/>體貼神的心願；<br/>為神爭戰，征服仇敵，<br/>神的心願成全。<br/>得著權柄，登上寶座，<br/>非憑人手掌管；<br/>乃是運用神聖權柄，<br/>為神作王掌權。<br/>',NULL,7986,7986);
INSERT INTO stanza VALUES('C161','7','你是君王，像所羅門，<br/>帶著和平執政；<br/>憑著智慧作王治理，<br/>為建神殿經營。<br/>現今在你聖徒中間，<br/>憑愛隱著掌權；<br/>將來要同我們作王，<br/>王權顯於眾前。<br/>',NULL,7987,7987);
INSERT INTO stanza VALUES('C161','8','你是祭司、先知、君王，<br/>所是何其豐美；<br/>對神、對人，你的價值，<br/>我們憑愛寶貴。<br/>我們珍愛你之所是，<br/>全人受你吸引；<br/>對你獻上敬拜、讚美，<br/>永遠感激不盡。<br/>',NULL,7988,7988);
INSERT INTO stanza VALUES('C162','1','我主，你是<br/>『女人後裔，』<br/>誕生為毀那仇敵；<br/>你曾取了人的性情，<br/>為藉受死得勝利。<br/>你乃是神成了肉身，<br/>穿上血肉的身體；<br/>你已藉死毀壞魔鬼，<br/>消除死亡的勢力。<br/>',NULL,7989,7989);
INSERT INTO stanza VALUES('C162','2','照神應許，你已來作<br/>『亞伯拉罕的後裔，』<br/>為使萬人都能得到<br/>神所應許的福氣。<br/>你在亞伯拉罕之先，<br/>因你是那『我是』的，<br/>但為成就神的應許，<br/>你竟作了他後裔。<br/>',NULL,7990,7990);
INSERT INTO stanza VALUES('C162','3','主，你也是<br/>『大衛後裔，』<br/>為神國度被興起；<br/>為神榮耀和神建造，<br/>寶座已經歸於你。<br/>雖然你是『大衛後裔，』<br/>他卻稱你為『我主，』<br/>因你原是『大衛的根、』<br/>『萬有之主』到永古。<br/>',NULL,7991,7991);
INSERT INTO stanza VALUES('C162','4','雖『一嬰孩』生有人性，<br/>『全能之神』被稱呼；<br/>雖是『一子』賜給我們，<br/>卻被稱為『永遠父。』<br/>神所應許一切福氣，<br/>全在我們相信你；<br/>應許在你都是是的，<br/>你是應許的實際！<br/>',NULL,7992,7992);
INSERT INTO stanza VALUES('C163','1','主，你是神的愛子，<br/>是神榮耀形像；<br/>你是聖徒的永分，<br/>我們都得分享。<br/>你是受造首生者，<br/>一切造物之首；<br/>萬有靠你而被造，<br/>也都歸你承受。<br/>',NULL,7993,7993);
INSERT INTO stanza VALUES('C163','2','你是萬有的由來，<br/>萬有存在之祕；<br/>你是萬有的中心，<br/>萬有靠你而立。<br/>你是從死首生者，<br/>一切元始是你；<br/>你是召會榮耀頭，<br/>召會是你身體。<br/>',NULL,7994,7994);
INSERT INTO stanza VALUES('C163','3','父願一切的豐滿，<br/>全都住你裡面；<br/>使你凡事居首位，<br/>凡事得著彰顯。<br/>你已藉死使萬有<br/>全都與神和好，<br/>好將我們呈神前，<br/>聖潔合神所要。<br/>',NULL,7995,7995);
INSERT INTO stanza VALUES('C163','4','神之所是全在你，<br/>你是神的奧祕；<br/>所積智慧與知識<br/>全都居住於你。<br/>你是榮耀的盼望，<br/>現今住我裡面；<br/>在你我們被成全，<br/>使神意足心滿。<br/>',NULL,7996,7996);
INSERT INTO stanza VALUES('C163','5','一切全都是影兒，<br/>惟有你是實際；<br/>我們在你已生根，<br/>現在正被建立。<br/>享受所有你豐富，<br/>成為你的豐滿；<br/>作你身體持守你，<br/>長大因神增添。<br/>',NULL,7997,7997);
INSERT INTO stanza VALUES('C163','6','我們同你藏神內，<br/>你是我們生命；<br/>將來同顯榮耀裡，<br/>盡享你的豐盛。<br/>在你身體－新人裡，<br/>你是一切一切；<br/>包羅萬有的基督，<br/>你何豐富、超越！<br/>',NULL,7998,7998);
INSERT INTO stanza VALUES('C164','1','☆恩主，你是神的兒子，<br/>是神完滿的表現；<br/>藉你，神向我們說話，<br/>將祂說得詳而全。<br/>',NULL,7999,7999);
INSERT INTO stanza VALUES('C164','2','☆你是神的本體真像，<br/>是神榮耀的光輝；<br/>你也就是神的自己，<br/>是神自己的發揮。<br/>',NULL,8000,8000);
INSERT INTO stanza VALUES('C164','3','宇宙萬有藉你而造，<br/>也是由你來托住，<br/>將來且都歸你承受，<br/>你是神立的基督。<br/>',NULL,8001,8001);
INSERT INTO stanza VALUES('C164','4','你已洗淨我們的罪，<br/>今坐高天神右邊；<br/>等候仇敵作你腳凳，<br/>神的旨意得成全。<br/>',NULL,8002,8002);
INSERT INTO stanza VALUES('C164','5','更尊之名你已承受，<br/>遠超所有的天使；<br/>神已叫你從死復活，<br/>顯明你是祂兒子。<br/>',NULL,8003,8003);
INSERT INTO stanza VALUES('C164','6','你的國權公義、正直，<br/>你的寶座到永遠。<br/>喜樂的油神曾膏你，<br/>勝過膏你的同伴。<br/>',NULL,8004,8004);
INSERT INTO stanza VALUES('C164','7','☆你也真是一個人子，<br/>具有我們的人性；<br/>藉恩為我嘗了死味，<br/>使我能有你生命。<br/>',NULL,8005,8005);
INSERT INTO stanza VALUES('C164','8','你已得了尊貴、榮耀，<br/>萬有向你全降服，<br/>你這神的救恩元帥，<br/>得以完全，因受苦。<br/>',NULL,8006,8006);
INSERT INTO stanza VALUES('C164','9','☆你已藉死毀壞魔鬼，<br/>使我從死得釋放；<br/>今藉生命使我成聖，<br/>還要帶我進榮光。<br/>',NULL,8007,8007);
INSERT INTO stanza VALUES('C164','10','今向我們－你的弟兄，<br/>在此傳揚父的名；<br/>你在會中頌揚父神，<br/>我們和聲同響應。<br/>',NULL,8008,8008);
INSERT INTO stanza VALUES('C164','11','☆好像造者之於房屋，<br/>你比摩西更尊榮；<br/>你是使徒，神所差來，<br/>配得更多的敬重。<br/>',NULL,8009,8009);
INSERT INTO stanza VALUES('C164','12','你是我們真約書亞，<br/>帶領我們進安息；<br/>你是我們完滿救恩，<br/>我們信心全在你。<br/>',NULL,8010,8010);
INSERT INTO stanza VALUES('C164','13','你是我們屬天安息，<br/>現今住在我靈裡；<br/>給我進入，享你豐富，<br/>猶如進入那美地。<br/>',NULL,8011,8011);
INSERT INTO stanza VALUES('C164','14','☆蒙神選召作大祭司，<br/>你比亞倫更尊榮；<br/>聖潔、無疵，高過諸天，<br/>體恤、代禱聖所中。<br/>',NULL,8012,8012);
INSERT INTO stanza VALUES('C164','15','你是那真麥基洗德，<br/>藉著生命的大能，<br/>正在我們需要時候，<br/>以『餅和酒』來供應。<br/>',NULL,8013,8013);
INSERT INTO stanza VALUES('C164','16','你是我們更美祭物，<br/>藉著永遠的聖靈，<br/>曾經為我向神獻上，<br/>使我今享其功能。<br/>',NULL,8014,8014);
INSERT INTO stanza VALUES('C164','17','☆更美之約你為我立，<br/>藉著你的更美血；<br/>藉你我今得有分於<br/>這個可靠的新約。<br/>',NULL,8015,8015);
INSERT INTO stanza VALUES('C164','18','你是這約合法立者，<br/>如此資格惟你有；<br/>你也是其勝任賜者，<br/>使我一切能承受。<br/>',NULL,8016,8016);
INSERT INTO stanza VALUES('C164','19','你今更是其執行者，<br/>藉著復活的生命；<br/>你也是其有力中保，<br/>為我成全神命定。<br/>',NULL,8017,8017);
INSERT INTO stanza VALUES('C164','20','哦主，你今已在幔內，<br/>作我惟一的先鋒，<br/>使我靠你出到營外，<br/>忠誠跟隨你腳蹤。<br/>',NULL,8018,8018);
INSERT INTO stanza VALUES('C164','21','☆你是我信的創始者，<br/>也是我信成終主；<br/>藉信與愛，隨你前行，<br/>向你我要永降服。<br/>',NULL,8019,8019);
INSERT INTO stanza VALUES('C164','22','☆你的價值無可比擬，<br/>我們珍愛你所是；<br/>你是如此完美、全備，<br/>遠超人所能賞識。<br/>',NULL,8020,8020);
INSERT INTO stanza VALUES('C165','1','你是一切的祭物，<br/>為我神所豫備；<br/>哦，其意義何豐富、<br/>何其榮耀、甘美！<br/>成全父神的旨意，<br/>滿足祂心所願；<br/>應付我們的需要，<br/>所缺全都補滿！<br/>',NULL,8021,8021);
INSERT INTO stanza VALUES('C165','2','你是馨香的燔祭，<br/>焚於神聖火焰；<br/>作神甜美的香氣，<br/>滿足神的心願。<br/>你曾行在神面前，<br/>神旨是你所顧；<br/>獻上無瑕的自己，<br/>為我作神食物。<br/>',NULL,8022,8022);
INSERT INTO stanza VALUES('C165','3','你是甜美的素祭，<br/>調油加上乳香；<br/>純淨、柔細又完全，<br/>甘美供神欣賞。<br/>你是完全平安祭，<br/>和平為我成就；<br/>且作食物何豐富，<br/>供我同神享受。<br/>',NULL,8023,8023);
INSERT INTO stanza VALUES('C165','4','你是我的贖罪祭，<br/>為我你曾成罪；<br/>藉死成功了救贖，<br/>為要將我贖回。<br/>你也是我贖愆祭，<br/>擔當我眾罪愆，<br/>滿足我神的公義，<br/>使我得蒙赦免。<br/>',NULL,8024,8024);
INSERT INTO stanza VALUES('C165','5','你也是我的搖祭，<br/>已經從死復活，<br/>陰府、死亡並黑暗，<br/>全都為我勝過。<br/>你更是我的舉祭，<br/>為我升到神前，<br/>作我天界的食物，<br/>使我得到飽滿。<br/>',NULL,8025,8025);
INSERT INTO stanza VALUES('C166','1','哦主，在你名裡聚集，<br/>任何不見惟見你，<br/>你的同在使我歡喜，<br/>呼召我心來歸依。<br/>',NULL,8026,8026);
INSERT INTO stanza VALUES('C166','2','愛我之愛無知其限，<br/>除了父對你的愛；<br/>父神對你所有意念，<br/>我心寶貴又感戴。<br/>',NULL,8027,8027);
INSERT INTO stanza VALUES('C166','3','父的喜悅、安息、喜樂，<br/>一切全都在於你；<br/>惟有你心能彀測度，<br/>父在你身之珍惜。<br/>',NULL,8028,8028);
INSERT INTO stanza VALUES('C166','4','父將祂愛全置於你，<br/>稱你作祂的愛子；<br/>然而為我未曾愛惜，<br/>為我得生要你死。<br/>',NULL,8029,8029);
INSERT INTO stanza VALUES('C166','5','將來見你如你所是，<br/>我要如何的歡唱！<br/>哦，主耶穌，你的名字，<br/>在神心中永馨香！<br/>',NULL,8030,8030);
INSERT INTO stanza VALUES('C166','6','喜樂音調、不息歌唱、<br/>永遠讚美的頌辭、<br/>榮耀詩章、永增歡暢，<br/>一直繼續到永世。<br/>',NULL,8031,8031);
INSERT INTO stanza VALUES('C167','1','恩主，你是生命源，<br/>深而且甜之泉：<br/>你的活水我已嘗，<br/>永不再渴再乾。<br/>你的憐憫時擴展，<br/>豐滿如同海洋；<br/>你的恩典彀我用，<br/>是你智慧所量。<br/>',NULL,8032,8032);
INSERT INTO stanza VALUES('C167','2','我乃屬我的良人，<br/>我的良人屬我；<br/>你將污穢的罪人，<br/>帶進你宴筵所。<br/>你的功績我所倚，<br/>你外別無可投；<br/>隱藏在你面光中，<br/>享受你的保守。<br/>',NULL,8033,8033);
INSERT INTO stanza VALUES('C167','3','新婦所愛非妝飾，<br/>乃是良人自己；<br/>我所注視非榮耀，<br/>乃是你的美麗：<br/>非你所賜的冠冕，<br/>乃你被釘之手；<br/>恩主，你是我榮耀，<br/>我的永遠倚投。<br/>',NULL,8034,8034);
INSERT INTO stanza VALUES('C168','1','主耶穌，當我們想到<br/>你的一切恩愛，<br/>我們的靈盼望最好<br/>當面見你丰采。<br/>',NULL,8035,8035);
INSERT INTO stanza VALUES('C168','2','雖然我們行在野地，<br/>寂寞、乾渴、駭驚，<br/>左右荊棘，前後蒺藜，<br/>四圍仇敵陷阱。<br/>',NULL,8036,8036);
INSERT INTO stanza VALUES('C168','3','我們卻從深處著想，<br/>知道你愛價值；<br/>我們因此心裡明亮，<br/>讚美你恩不置。<br/>',NULL,8037,8037);
INSERT INTO stanza VALUES('C168','4','你是我們生命、力量、<br/>盾牌、磐石、詩歌，<br/>無論怎樣把你思想，<br/>總叫我們快樂。<br/>',NULL,8038,8038);
INSERT INTO stanza VALUES('C168','5','可愛的主，保守我們<br/>緊緊跟隨你行，<br/>直到我們進入天門，<br/>面見你的榮形。<br/>',NULL,8039,8039);
INSERT INTO stanza VALUES('C169','1','耶穌，耶穌，我的性命，<br/>因為愛的緣故，<br/>求原諒我，將你聖名，<br/>日念千遍不住。<br/>',NULL,8040,8040);
INSERT INTO stanza VALUES('C169','chorus','耶穌，耶穌，最愛救主，<br/>無人無物與你比擬，<br/>你的笑容是我歡喜，<br/>我愛，…愛你，<br/>…你，…主。<br/>',NULL,8041,8041);
INSERT INTO stanza VALUES('C169','2','我心愛你，不知如何<br/>約束我的奇樂；<br/>你愛有如一團熱火，<br/>使我心中火熱。<br/>',NULL,8042,8042);
INSERT INTO stanza VALUES('C169','3','因你是我一切一切、<br/>我的倚靠、食糧、<br/>我心『羨慕、』<br/>我身醫藥、<br/>我魂永遠力量。<br/>',NULL,8043,8043);
INSERT INTO stanza VALUES('C169','4','燒、燒，哦愛，<br/>在我心懷，<br/>日夜厲害的燒，<br/>直至所有其他的愛<br/>燒到無處可找。<br/>',NULL,8044,8044);
INSERT INTO stanza VALUES('C169','5','暗中之光、憂中之樂、<br/>天在地上開始；<br/>耶穌，你是我愛、我歌，<br/>有誰知你價值！<br/>',NULL,8045,8045);
INSERT INTO stanza VALUES('C169','6','這愛將受甚麼限制？<br/>要到那裡停止？<br/>進、進，我主，<br/>甘甜價值<br/>今日遠勝昨日。<br/>',NULL,8046,8046);
INSERT INTO stanza VALUES('C169','chorus','耶穌，耶穌，最愛救主，<br/>無人無物與你比擬，<br/>你的笑容是我歡喜，<br/>我愛，…愛你，<br/>…你，…主。<br/>第三節的『羨慕』作名詞用。<br/>',NULL,8047,8047);
INSERT INTO stanza VALUES('C170','1','恩主，<br/>我心對你所愛、所寶，<br/>在此，<br/>我口都要歡樂發表；<br/>你這復活，<br/>作我福分的主，<br/>現今我要向你獻上稱祝。<br/>',NULL,8048,8048);
INSERT INTO stanza VALUES('C170','2','在此，<br/>你給我們再次嘗到<br/>你的同在何其<br/>可愛、可寶；<br/>在你蔭下<br/>我們歡樂、安息，<br/>你的美果我們飽嘗不已。<br/>',NULL,8049,8049);
INSERT INTO stanza VALUES('C170','3','你曾孤單，<br/>直至落到死地，<br/>像粒麥子結出許多子粒；<br/>藉著復活生出許多弟兄，<br/>使你一切我們都能與共。<br/>',NULL,8050,8050);
INSERT INTO stanza VALUES('C170','4','哦主，<br/>你今作了<br/>我們一切，<br/>在你裡面我們一無所缺；<br/>你已滿足我們所有需要，<br/>我心感銘，<br/>我口永要稱道。<br/>',NULL,8051,8051);
INSERT INTO stanza VALUES('C171','1','耶穌，只要一想到你，<br/>我心就滿甘甜；<br/>但這甘甜還遠不及<br/>親眼看見你面。<br/>',NULL,8052,8052);
INSERT INTO stanza VALUES('C171','2','無口能唱，無心能思，<br/>也無記性能憶<br/>一種聲音比你名字<br/>更為甘甜、可喜。<br/>',NULL,8053,8053);
INSERT INTO stanza VALUES('C171','3','你是痛悔者的希望，<br/>溫柔者的喜樂；<br/>你對尋求者何善良，<br/>跌倒者何仁德。<br/>',NULL,8054,8054);
INSERT INTO stanza VALUES('C171','4','但對尋得你者如何？<br/>無口無筆能述；<br/>耶穌的愛，其深、其闊，<br/>惟被愛者略熟。<br/>',NULL,8055,8055);
INSERT INTO stanza VALUES('C171','5','耶穌！你是世人之光，<br/>你是生命之源！<br/>遠超一切我之所享、<br/>一切我所能羨。<br/>',NULL,8056,8056);
INSERT INTO stanza VALUES('C171','6','你外我無別的源頭<br/>能解我心乾渴；<br/>無窮寶泉！活水湧流！<br/>別流全都乾涸。<br/>',NULL,8057,8057);
INSERT INTO stanza VALUES('C171','7','耶穌，你今是我喜樂，<br/>將來是我賞賜；<br/>你是我的榮耀、詩歌，<br/>從今直到永世。<br/>',NULL,8058,8058);
INSERT INTO stanza VALUES('C172','1','哦主，你是人心之樂，<br/>生命之源，人們之光，<br/>從地所給最佳福樂，<br/>空心轉來向你仰望。<br/>',NULL,8059,8059);
INSERT INTO stanza VALUES('C172','2','你的真實永存不變，<br/>凡求你者，你都提挈：<br/>對尋求者，你是慈善，<br/>對尋得者，你是一切。<br/>',NULL,8060,8060);
INSERT INTO stanza VALUES('C172','3','生命的糧，我已嘗過，<br/>仍是切慕嘗食不已；<br/>活水的泉，我飲雖多，<br/>仍是渴望更多飲你。<br/>',NULL,8061,8061);
INSERT INTO stanza VALUES('C172','4','當那易變之福改變，<br/>不安的靈對你渴慕；<br/>歡喜，因見你的笑臉，<br/>有福，憑信將你抓住。<br/>',NULL,8062,8062);
INSERT INTO stanza VALUES('C172','5','願你作我力量、維持！<br/>使我時時寧靜、明亮，<br/>驅盡黑暗罪惡之思，<br/>向我倒下你的聖光。<br/>',NULL,8063,8063);
INSERT INTO stanza VALUES('C173','1','我們照你恩惠話語，<br/>帶著謙卑心意，<br/>受死的主，我們會聚，<br/>現今來記念你。<br/>',NULL,8064,8064);
INSERT INTO stanza VALUES('C173','2','你的身體為我裂開，<br/>要成我的供給；<br/>我今舉起立約杯來，<br/>為的是記念你。<br/>',NULL,8065,8065);
INSERT INTO stanza VALUES('C173','3','能否我忘客西馬尼，<br/>或看你的孤寂、<br/>你的血汗和你哭泣，<br/>而不來記念你？<br/>',NULL,8066,8066);
INSERT INTO stanza VALUES('C173','4','當我轉眼看十字架，<br/>看你在髑髏地，<br/>神的羔羊，我的救法，<br/>我必須記念你。<br/>',NULL,8067,8067);
INSERT INTO stanza VALUES('C173','5','記念你和你的苦痛、<br/>和你對我愛意，<br/>一息尚存、一脈尚動，<br/>我必定記念你。<br/>',NULL,8068,8068);
INSERT INTO stanza VALUES('C173','6','當我漸衰，嘴脣無音，<br/>思想、記憶軟弱，<br/>當你在你國度降臨，<br/>主，求你記念我。<br/>',NULL,8069,8069);
INSERT INTO stanza VALUES('C174','1','主舉愛旗遮蓋我們<br/>同來享受祂愛筵；<br/>我們感激救贖大恩，<br/>全心虔誠來記念。<br/>桌上陳設這餅和杯，<br/>都是表明你的愛；<br/>我們一同領你恩惠，<br/>我們一同來敬拜。<br/>',NULL,8070,8070);
INSERT INTO stanza VALUES('C174','2','我們記念你曾臨世，<br/>成了奴僕歷艱苦；<br/>你受試探，你常禁食，<br/>勞碌並無枕首處。<br/>我們記念你尋罪人，<br/>常受頂撞和飢渴；<br/>如有一人悔改歸神，<br/>你認流血也值得。<br/>',NULL,8071,8071);
INSERT INTO stanza VALUES('C174','3','我們記念你釘十架，<br/>被人定罪、被神棄，<br/>獨自支付我們贖價，<br/>你顯你愛的無極；<br/>我們記念你今在天，<br/>在神右邊常代求；<br/>你曾應許還要顯現，<br/>主阿，求你快成就。<br/>',NULL,8072,8072);
INSERT INTO stanza VALUES('C175','1','在此分享這福杯，<br/>怎能閉口不讚美？<br/>你為我流的寶血，<br/>價值誰能盡領會！<br/>哦主，你血何寶貴！<br/>我的問題全應付；<br/>因你有效的寶血，<br/>一切憂懼都消除。<br/>',NULL,8073,8073);
INSERT INTO stanza VALUES('C175','2','藉這有效的寶血，<br/>新約為我得成立；<br/>為著這個更美約，<br/>牠是穩固的根基。<br/>我們已蒙神救贖，<br/>並非憑著金或銀，<br/>乃是憑著你寶血，<br/>就是在此我所飲。<br/>',NULL,8074,8074);
INSERT INTO stanza VALUES('C175','3','為使我罪得洗淨，<br/>洗罪之血你已流；<br/>這血為我滿足神<br/>一切公義的要求。<br/>用你有力潔淨血，<br/>你將我罪已洗盡；<br/>並且洗淨我良心，<br/>使我事奉永活神。<br/>',NULL,8075,8075);
INSERT INTO stanza VALUES('C175','4','藉你分別的寶血，<br/>我們都已得成聖；<br/>藉你保守的寶血，<br/>聖別成為我見證。<br/>藉你贖罪的寶血，<br/>我們都已得稱義；<br/>藉你救贖的寶血，<br/>我得與神無距離。<br/>',NULL,8076,8076);
INSERT INTO stanza VALUES('C175','5','藉你十架所流血，<br/>我們已與神和好；<br/>使我能以接觸神，<br/>與神平安的相交。<br/>藉著有分你的血，<br/>我已得著你生命；<br/>憑你寶血和生命，<br/>享受自由和安寧。<br/>',NULL,8077,8077);
INSERT INTO stanza VALUES('C175','6','在天你所灑的血，<br/>為我說出更美事；<br/>在這血的護庇下，<br/>我脫撒但的攻勢。<br/>靠你得勝的寶血，<br/>我們勝過那仇敵；<br/>如此對那控告者，<br/>我們就能得勝利。<br/>',NULL,8078,8078);
INSERT INTO stanza VALUES('C175','7','我們藉著你的血，<br/>與眾聖徒同交通；<br/>在你這血遮蓋下，<br/>我靈自由無驚恐。<br/>我們何能用話語，<br/>說盡你血的故事，<br/>我們需要那永世，<br/>來說你血的價值。<br/>',NULL,8079,8079);
INSERT INTO stanza VALUES('C176','1','在你愛的筵席上，<br/>有杯陪餅同陳列；<br/>這些表記我分享，<br/>就得飽嘗你超越。<br/>為著這杯我感謝，<br/>就是你賜的福杯，<br/>也是豐滿救恩杯，<br/>你藉你血所豫備。<br/>',NULL,8080,8080);
INSERT INTO stanza VALUES('C176','2','這是你流的寶血，<br/>使我罪惡得清洗；<br/>這是你立的新約，<br/>使我得著神福氣。<br/>你已喝了忿怒杯，<br/>為我嘗盡了死味；<br/>如此買了這福杯，<br/>永作我分，福全備。<br/>',NULL,8081,8081);
INSERT INTO stanza VALUES('C176','3','亞當墮落失去神，<br/>在這分內我得回；<br/>藉著你所流的血，<br/>神就成為我恩惠。<br/>救贖、生命並一切，<br/>在這分內都包括；<br/>凡神所願並所籌，<br/>在這分內全歸我。<br/>',NULL,8082,8082);
INSERT INTO stanza VALUES('C176','4','這是我們的永分，<br/>神聖、滿溢的福杯；<br/>在神設計的杯裡，<br/>嘗到屬天的滋味。<br/>在此因愛飲這杯，<br/>恩主，為著記念你；<br/>靈中如此的飲領，<br/>滿享加略的功績。<br/>',NULL,8083,8083);
INSERT INTO stanza VALUES('C177','1','哦主，這是何等神蹟，<br/>你我竟然聯合為一！<br/>我在你內，你在我裡，<br/>真是希奇，真是奧祕！<br/>',NULL,8084,8084);
INSERT INTO stanza VALUES('C177','2','為使我能有分於你，<br/>你竟為我捨了身體；<br/>並為使我脫離罪孽，<br/>你也為我流了寶血。<br/>',NULL,8085,8085);
INSERT INTO stanza VALUES('C177','3','你且復活化身聖靈，<br/>進入我靈作我生命，<br/>要我時常將你接領，<br/>享受你的一切豐盛。<br/>',NULL,8086,8086);
INSERT INTO stanza VALUES('C177','4','我們面對桌上表記，<br/>思念你的可愛自己！<br/>一面感激你的心意，<br/>一面重溫你的經歷。<br/>',NULL,8087,8087);
INSERT INTO stanza VALUES('C177','5','藉著喫餅，藉著喝杯，<br/>再來享受你的甘美；<br/>靈裡吸取，靈裡接受，<br/>靈裡飽嘗生命珍饈。<br/>',NULL,8088,8088);
INSERT INTO stanza VALUES('C177','6','深願如此喫你、喝你，<br/>用靈接受你的自己，<br/>直到全人被你充滿，<br/>讓你得到真正記念！<br/>',NULL,8089,8089);
INSERT INTO stanza VALUES('C178','1','為這筵席我獻感謝，<br/>餅、杯在此同陳列；<br/>藉此享受你的自己，<br/>神聖愛筵何超絕。<br/>這餅是你所捨身體，<br/>我們在此同分享；<br/>這杯是你所流寶血，<br/>我們在此同飲嘗。<br/>',NULL,8090,8090);
INSERT INTO stanza VALUES('C178','chorus','看，這神聖筵席！<br/>其上何等表記！<br/>意義深厚，永垂不朽，<br/>人知何能及！<br/>',NULL,8091,8091);
INSERT INTO stanza VALUES('C178','2','藉著你的救贖之死，<br/>你將生命來分賜；<br/>你將自己給了我們，<br/>要我有分你所是。<br/>藉著分享這餅、這杯，<br/>我們陳列你的死；<br/>在此喫喝你的自己，<br/>如此記念到永世。<br/>',NULL,8092,8092);
INSERT INTO stanza VALUES('C178','3','這餅在此也是指明<br/>你那奧祕的身體；<br/>藉此與眾肢體交通，<br/>見證身體的合一。<br/>這杯也是神聖福杯，<br/>我們現在所祝福；<br/>藉著你血我們交通，<br/>與你所有的聖徒。<br/>',NULL,8093,8093);
INSERT INTO stanza VALUES('C178','4','你是我們永遠的分，<br/>在此豫嘗何有福；<br/>我們等候你的國度，<br/>你的顯現我催促。<br/>當你顯現在你國度，<br/>同著得勝的聖徒，<br/>重新享受你的自己，<br/>作你心愛的新婦。<br/>',NULL,8094,8094);
INSERT INTO stanza VALUES('C179','1','當我注視你這桌子，<br/>表記使我驚奇；<br/>一餅一杯分別陳列，<br/>照神所愛心意。<br/>',NULL,8095,8095);
INSERT INTO stanza VALUES('C179','2','這餅表明生命之糧，<br/>作我屬天食物，<br/>藉著你死給我分享，<br/>使我嘗你豐富。<br/>',NULL,8096,8096);
INSERT INTO stanza VALUES('C179','3','這杯乃是神聖之分，<br/>你血為我成就；<br/>我們接受這一福杯，<br/>就得享神所有。<br/>',NULL,8097,8097);
INSERT INTO stanza VALUES('C179','4','在此藉著分享這餅，<br/>喫你生命之糧；<br/>因愛如此將你記念，<br/>就得將你飽嘗。<br/>',NULL,8098,8098);
INSERT INTO stanza VALUES('C179','5','藉著同喝這一福杯，<br/>得享神的福氣；<br/>如此歡樂將你記念，<br/>直到我們被提。<br/>',NULL,8099,8099);
INSERT INTO stanza VALUES('C179','6','藉喫這餅，並喝這杯，<br/>你死我們陳列；<br/>見證你是我們生命，<br/>每日取用不竭。<br/>',NULL,8100,8100);
INSERT INTO stanza VALUES('C179','7','我們等候那日來到，<br/>與你一同坐席，<br/>更多享受你的自己，<br/>並要敬拜不已。<br/>',NULL,8101,8101);
INSERT INTO stanza VALUES('C180','1','在此我要，<br/>主，與你面對面，<br/>在此我要用信把握不見，<br/>在此我要更深認識恩典，<br/>將我疲勞都息在主腳前。<br/>',NULL,8102,8102);
INSERT INTO stanza VALUES('C180','2','在此我要喫主所賜美物，<br/>在此我要飲主所遞福杯，<br/>在此我要忘記一切難處，<br/>再嘗一次赦罪平安滋味。<br/>',NULL,8103,8103);
INSERT INTO stanza VALUES('C180','3','我雖有罪，<br/>但你卻有公義，<br/>我雖污穢，<br/>但你卻有寶血；<br/>哦主，<br/>你的寶血將我清洗，<br/>你的公義對付我的罪孽。<br/>',NULL,8104,8104);
INSERT INTO stanza VALUES('C180','4','除你之外，<br/>我無別的幫助；<br/>有你賜恩，<br/>我就不求人惠；<br/>有你的愛，<br/>我已心意滿足；<br/>靠你能力，<br/>我要站住地位。<br/>以下三節在擘餅後唱<br/>',NULL,8105,8105);
INSERT INTO stanza VALUES('C180','5','席撤何速，<br/>表記的物已盡！<br/>酒餅雖無，<br/>拯救的愛未亡！<br/>宴筵已過，<br/>你仍在此親近，<br/>親近有加，<br/>作我萬有君王！<br/>',NULL,8106,8106);
INSERT INTO stanza VALUES('C180','6','看哪，<br/>雲柱今又離地上升，<br/>在這野地又要乘夜前征；<br/>你正招呼，<br/>我們緊緊隨行，<br/>不久我們就到光明天城。<br/>',NULL,8107,8107);
INSERT INTO stanza VALUES('C180','7','上席罷席，<br/>次次我們聚散，<br/>如此聚散，<br/>搖指天上佳筵；<br/>時雖未至，<br/>我們卻已豫嘗<br/>他日天上羔羊婚娶喜宴。<br/>',NULL,8108,8108);
INSERT INTO stanza VALUES('C181','1','哦主耶穌，藉著餅杯，<br/>我們陳列你的死；<br/>溫習你愛所作所為，<br/>珍賞你死的價值。<br/>餅杯分列，身血分開，<br/>表明你死已成就；<br/>我心感戴，我靈敬拜，<br/>我口向你獻歌謳。<br/>',NULL,8109,8109);
INSERT INTO stanza VALUES('C181','chorus','你嘗死亡苦味，<br/>我飲救恩福杯！<br/>你愛所作所為，<br/>配得永遠讚美！<br/>',NULL,8110,8110);
INSERT INTO stanza VALUES('C181','2','你愛叫你為我流血，<br/>為要引我到神前；<br/>使我與神不再隔絕，<br/>隨時得見神聖面。<br/>神的榮耀、聖潔、公義，<br/>所有要求已滿足；<br/>我能藉著你死功績，<br/>坦然與神來接觸。<br/>',NULL,8111,8111);
INSERT INTO stanza VALUES('C181','3','你死已將幔子裂開，<br/>為我打通至聖所，<br/>除去我與神的阻礙，<br/>使我能到施恩座，<br/>得神憐恤，蒙神恩惠，<br/>作我應時的幫助，<br/>如同飲到生命活水，<br/>飽嘗神性的豐富。<br/>',NULL,8112,8112);
INSERT INTO stanza VALUES('C181','4','你既如此將我贖回，<br/>就使我能作祭司，<br/>得享神的一切甘美，<br/>常在神前供聖職。<br/>如此福氣、如此恩典，<br/>全都由於你受死；<br/>我願不斷如此記念，<br/>直到喝新的日子。<br/>',NULL,8113,8113);
INSERT INTO stanza VALUES('C182','1','在你首次要顯你死之時，<br/>你曾禱告要你子民合一；<br/>求使我們每次顯你的死，<br/>我們都能成功你的旨意。<br/>只有一餅，<br/>我們只成一體，<br/>藉著這個擘餅來作表記。<br/>',NULL,8114,8114);
INSERT INTO stanza VALUES('C182','2','我們為你所有召會禱告，<br/>求使我們不再分裂排逼，<br/>求你吸引我們彼此緊靠，<br/>藉你吸引我們都緊靠你。<br/>我們就能<br/>只有一餅、一體，<br/>藉著這個擘餅來作表記。<br/>',NULL,8115,8115);
INSERT INTO stanza VALUES('C182','3','我們也為離群的羊祈求，<br/>良好牧人，<br/>求帶他們回來，<br/>回到真理，<br/>當初門徒所有，<br/>回到召會，<br/>當初真理所在；<br/>不久，<br/>我們只有一餅、一體，<br/>藉著這個擘餅來作表記。<br/>',NULL,8116,8116);
INSERT INTO stanza VALUES('C182','4','主阿，<br/>不久所有表記過去，<br/>我們要在天上錫安合一，<br/>與眾聖徒享受平安不渝，<br/>與眾聖徒彼此相愛無極；<br/>更為可樂，<br/>能同神的兒子<br/>同享愛與平安，<br/>永遠不止。<br/>',NULL,8117,8117);
INSERT INTO stanza VALUES('C183','1','咒詛祂受，祝福我享；<br/>苦杯祂飲，愛筵我嘗；<br/>恩愛高深，誰能測量？<br/>我的心哪，應當歌唱！<br/>',NULL,8118,8118);
INSERT INTO stanza VALUES('C184','1','主耶穌，當那晚間，<br/>世人在你旁邊，<br/>用盡黑暗的工夫，<br/>叫你聖心受苦；<br/>那時，你對我們說：<br/>『如此行，記念我；』<br/>我們聽話今聚集，<br/>為的來記念你。<br/>',NULL,8119,8119);
INSERT INTO stanza VALUES('C184','2','怒氣的杯何等苦！<br/>但你為我們茹；<br/>死亡的浸何等深！<br/>但你為我們沉；<br/>可憐你在髑髏地，<br/>竟被父神離棄；<br/>主，我們滿心感激，<br/>不能不記念你。<br/>',NULL,8120,8120);
INSERT INTO stanza VALUES('C184','3','我想當日的幽冥，<br/>怎樣攻逼你靈；<br/>又想洪濤和波瀾，<br/>怎樣將你沖漫；<br/>但在那裡，我看見<br/>你的恩愛無限；<br/>主，我們憂喜交集，<br/>現在來記念你。<br/>',NULL,8121,8121);
INSERT INTO stanza VALUES('C184','4','我們知你已復活，<br/>作死人初熟果；<br/>我們見你坐父右，<br/>作召會榮耀頭。<br/>我們因你蒙悅納，<br/>身、心都得救拔；<br/>不然怎會想慕你，<br/>這樣來記念你？<br/>',NULL,8122,8122);
INSERT INTO stanza VALUES('C184','5','你若尚未得榮來，<br/>接我免去大災，<br/>叫我與你永同在，<br/>安息直到萬代；<br/>我還要效法你死，<br/>還要表明你死，<br/>還要竭力敬愛你，<br/>還要來記念你。<br/>',NULL,8123,8123);
INSERT INTO stanza VALUES('C185','1','為著這餅我感謝你，<br/>這是神聖表記；<br/>藉此，恩主，我得看見<br/>神計畫的奧祕。<br/>',NULL,8124,8124);
INSERT INTO stanza VALUES('C185','2','這餅指明你的身體，<br/>你為我們捨棄，<br/>使我有分你的生命，<br/>並得你的自己。<br/>',NULL,8125,8125);
INSERT INTO stanza VALUES('C185','3','你的身體為我裂開，<br/>為將自己分授，<br/>使我能得你作生命，<br/>成為你的配偶。<br/>',NULL,8126,8126);
INSERT INTO stanza VALUES('C185','4','如此，這餅也是指明<br/>你那奧祕身體；<br/>我們是祂活的肢體，<br/>與你完全合一。<br/>',NULL,8127,8127);
INSERT INTO stanza VALUES('C185','5','我們雖是許多子粒，<br/>卻都成為一餅；<br/>在此這樣將你記念，<br/>從你得到供應。<br/>',NULL,8128,8128);
INSERT INTO stanza VALUES('C185','6','藉著這餅我們交通，<br/>使你心滿意足；<br/>同眾聖徒如此交通，<br/>見證你的豐富。<br/>',NULL,8129,8129);
INSERT INTO stanza VALUES('C186','1','神聖、愛的珍饈，<br/>乃是出於恩典；<br/>藉著享受這餅與酒，<br/>我們將你記念。<br/>',NULL,8130,8130);
INSERT INTO stanza VALUES('C186','2','在此我們都願<br/>從你得以看見：<br/>你父對你所有心願，<br/>並你所賜恩典。<br/>',NULL,8131,8131);
INSERT INTO stanza VALUES('C186','3','我靈今已滿足，<br/>我心今作見證：<br/>生命之餅，甜美、豐富，<br/>作我生命供應。<br/>',NULL,8132,8132);
INSERT INTO stanza VALUES('C186','4','良心不再定罪，<br/>信心歡樂宣告：<br/>贖罪之血何其寶貴，<br/>滿足神之所要。<br/>',NULL,8133,8133);
INSERT INTO stanza VALUES('C186','5','今享這個筵席，<br/>如此神聖、甜美，<br/>等到那日與你再席，<br/>甜美豈只萬倍！<br/>',NULL,8134,8134);
INSERT INTO stanza VALUES('C186','6','那時得見你面，<br/>穿上你的榮形；<br/>所有你的奇妙恩典，<br/>我要永遠見證。<br/>',NULL,8135,8135);
INSERT INTO stanza VALUES('C187','1','為著這餅和這杯，<br/>為著神子曾降卑，<br/>為著神恩如雨沛，<br/>主，我們感謝你。<br/>',NULL,8136,8136);
INSERT INTO stanza VALUES('C187','2','依然是酒、依然餅，<br/>藉此信心卻看明<br/>愛心神聖的小影，<br/>主，我們感謝你。<br/>',NULL,8137,8137);
INSERT INTO stanza VALUES('C187','3','為著你曾召我們，<br/>舉目仰望你救恩，<br/>藉著信心近你身，<br/>主，我們感謝你。<br/>',NULL,8138,8138);
INSERT INTO stanza VALUES('C187','4','為著你曾發命令，<br/>要我記念你行徑－何等溫柔、何等貧，<br/>主，我們感謝你。<br/>',NULL,8139,8139);
INSERT INTO stanza VALUES('C187','5','為著你曾用慈愛，<br/>引我想家在天外－『行此直等到我來，』<br/>主，我們感謝你。<br/>',NULL,8140,8140);
INSERT INTO stanza VALUES('C187','6','直到祂來，我擘餅，<br/>表明祂作我生命，<br/>為我睡了、為我醒，<br/>主，我們感謝你。<br/>',NULL,8141,8141);
INSERT INTO stanza VALUES('C187','7','直到祂來，我飲杯，<br/>表明祂賜福全備，<br/>使我站在新地位，<br/>主，我們感謝你。<br/>',NULL,8142,8142);
INSERT INTO stanza VALUES('C187','8','為著再來的囑咐，<br/>為著那日的緊速，<br/>為著榮耀和國度，<br/>主，我們感謝你。<br/>',NULL,8143,8143);
INSERT INTO stanza VALUES('C188','1','榮耀基督，太初就有，<br/>祂的根源在亙古！<br/>全能的神，早過宇宙，<br/>自有永有永遠父；<br/>無生之始，無命之終，<br/>無父、無母、無族譜；<br/>永不改變，年數無窮，<br/>昔在、今在、永在主。<br/>',NULL,8144,8144);
INSERT INTO stanza VALUES('C188','2','榮耀基督，創造萬有，<br/>萬有獨一的根源；<br/>萬有主宰、萬有元首，<br/>萬有之間祂居先；<br/>用祂命令托住萬有，<br/>萬有靠祂而團結；<br/>神早立祂承受萬有，<br/>萬有歸祂為基業。<br/>',NULL,8145,8145);
INSERT INTO stanza VALUES('C188','3','榮耀基督，道成肉身，<br/>支搭帳幕在人間；<br/>童女所生正式的人，<br/>神在肉身的顯現。<br/>神而人者自甘卑微，<br/>取了奴僕的形狀，<br/>是神榮耀所發光輝，<br/>是神本體的真像。<br/>',NULL,8146,8146);
INSERT INTO stanza VALUES('C188','4','榮耀基督，釘死十架，<br/>替我擔罪並成罪，<br/>受神審判，被神所殺，<br/>嘗盡死亡的苦味。<br/>將我舊人一同釘死，<br/>毀壞撒但和鬼魔，<br/>使我脫離罪的權勢，<br/>脫離一切的網羅。<br/>',NULL,8147,8147);
INSERT INTO stanza VALUES('C188','5','榮耀基督，從死復活，<br/>成為復活初熟果；<br/>祂也使我同祂復活，<br/>將祂生命分給我。<br/>祂是一粒生命麥種，<br/>生出我們許多粒，<br/>成為祂的許多弟兄，<br/>與祂同是出於一。<br/>',NULL,8148,8148);
INSERT INTO stanza VALUES('C188','6','榮耀基督，化成聖靈，<br/>到我靈裡作生命，<br/>使我有分神的性情，<br/>與祂同樣的神聖。<br/>在我裡面長大成形，<br/>將我變成祂形狀；<br/>使我享受神的豐盛，<br/>有祂豐滿的身量。<br/>',NULL,8149,8149);
INSERT INTO stanza VALUES('C188','7','榮耀基督，升上高天，<br/>遠超一切的首領，<br/>得著尊貴、榮耀冠冕，<br/>並得至高的尊名。<br/>祂也帶我與祂同升，<br/>與祂一同坐天上，<br/>使我分享祂的權柄，<br/>同祂一樣的高強。<br/>',NULL,8150,8150);
INSERT INTO stanza VALUES('C188','8','榮耀基督，賜下聖靈，<br/>召會因此得成立；<br/>並賜恩賜，各盡功能，<br/>建造召會作身體。<br/>祂愛召會，保養、顧惜，<br/>藉著召會得彰顯；<br/>召會將祂延長、普及，<br/>延長、普及宇宙間。<br/>',NULL,8151,8151);
INSERT INTO stanza VALUES('C188','9','榮耀基督，得國再臨，<br/>提接、救贖祂聖徒，<br/>踐踏仇敵，審判萬民，<br/>憑祂權柄設國度。<br/>帶著聖徒一同作王，<br/>執政掌權到地極，<br/>萬國和平，萬有歌唱，<br/>全地都得享安息。<br/>',NULL,8152,8152);
INSERT INTO stanza VALUES('C188','10','榮耀基督，永世中心，<br/>得著聖城為配偶；<br/>天地一切全都更新，<br/>脫盡一切的陳舊。<br/>神是榮光，祂是明燈，<br/>神在祂內得彰顯；<br/>聖城又是祂的顯明，<br/>由祂充滿到永遠！<br/>',NULL,8153,8153);
INSERT INTO stanza VALUES('C189','1','美哉、善哉，<br/>羔羊的新歌；<br/>榮耀歸主！榮耀歸主！<br/>這個福音賜無比快樂，<br/>榮耀至高的主！<br/>耶穌基督降生下土，<br/>離去尊榮是為救贖，<br/>如此奇恩舉世皆無，<br/>愚人也會感驚愕。<br/>',NULL,8154,8154);
INSERT INTO stanza VALUES('C189','chorus','大聲讚美，口唱連心和，<br/>榮耀歸主！榮耀歸主！<br/>自古以來無此詩歌，<br/>榮耀至高的主！<br/>',NULL,8155,8155);
INSERT INTO stanza VALUES('C189','2','聽哪，歌聲由天飄揚來，<br/>榮耀歸主！榮耀歸主！<br/>祂就是光，祂也就是愛，<br/>榮耀至高的主！<br/>世界所有悲傷淚人，<br/>地上一切不安罪人，<br/>完全不管你是誰人，<br/>耶穌都已為還債。<br/>',NULL,8156,8156);
INSERT INTO stanza VALUES('C189','3','應當高歌，因審判已過，<br/>榮耀歸主！榮耀歸主！<br/>與主聯合，我們已復活，<br/>榮耀至高的主！<br/>我們已在墳墓那邊，<br/>立在死亡不到地點，<br/>仇敵浮沉紅海中間，<br/>主賜稱義的把握。<br/>',NULL,8157,8157);
INSERT INTO stanza VALUES('C189','4','唱哪，祂再降臨接聖徒，<br/>榮耀歸主！榮耀歸主！<br/>不再耽延，召會已成熟，<br/>榮耀至高的主！<br/>今能看見前所求呼，<br/>也能領受久所羨慕，<br/>永能傾吐此心情愫，<br/>與祂只有一前途。<br/>',NULL,8158,8158);
INSERT INTO stanza VALUES('C189','5','此歌再唱聲音應明朗，<br/>榮耀歸主！榮耀歸主！<br/>此歌題目應當一直唱，<br/>榮耀至高的主！<br/>唱至內心歡喜會跳，<br/>唱至天下佈滿此調，<br/>唱至所有蒙愛新造，<br/>都唱此歌不肯放。<br/>',NULL,8159,8159);
INSERT INTO stanza VALUES('C190','1','讚美！讚美！讚美耶穌，<br/>我救贖主！<br/>聖徒歌唱，<br/>將祂奇愛宣明；<br/>稱頌！稱頌！稱頌基督！<br/>天使俯伏，<br/>能力、尊貴，<br/>歸於祂的聖名！<br/>有如牧者，<br/>主將祂的人餧養，<br/>祂的膀臂懷抱他們安康。<br/>',NULL,8160,8160);
INSERT INTO stanza VALUES('C190','chorus','讚美！讚美！<br/>讚美祂的奇妙愛情！<br/>稱頌！稱頌！<br/>稱頌祂的聖名。<br/>',NULL,8161,8161);
INSERT INTO stanza VALUES('C190','2','讚美！讚美！讚美耶穌，<br/>我救贖主！<br/>祂為我罪<br/>受苦、流血、受刑；<br/>稱頌！稱頌！稱頌<br/>祂是磐石穩固，<br/>為成永遠救恩，<br/>十架被釘！<br/>高聲讚祂！<br/>主擔當我的痛苦！<br/>此愛奇妙，<br/>貞堅、絕頂、豐富。<br/>',NULL,8162,8162);
INSERT INTO stanza VALUES('C190','3','讚美！讚美！讚美耶穌，<br/>我救贖主！<br/>響徹天門，<br/>『和散那』聲飛揚！<br/>加冠！加冠！加冠<br/>祂作萬有之主，<br/>復興萬物，<br/>永作祭司，君王！<br/>神的基督，<br/>得勝一切，立國度，<br/>榮耀、權柄，<br/>永歸我主耶穌！<br/>',NULL,8163,8163);
INSERT INTO stanza VALUES('C191','1','那愛我們，憐憫我們，<br/>在凡事恩待我們，<br/>白白流血拯救我們，<br/>捨命，活我們的主，<br/>但願權能、榮耀、國度，<br/>歸給祂直到永古！<br/>',NULL,8164,8164);
INSERT INTO stanza VALUES('C192','1','主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要敬拜你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要敬拜你！<br/>',NULL,8165,8165);
INSERT INTO stanza VALUES('C192','2','主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要讚美你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要讚美你！<br/>',NULL,8166,8166);
INSERT INTO stanza VALUES('C192','3','主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要感謝你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要感謝你！<br/>',NULL,8167,8167);
INSERT INTO stanza VALUES('C192','4','主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要高舉你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶穌我救主，<br/>我要高舉你！<br/>',NULL,8168,8168);
INSERT INTO stanza VALUES('C193','1','但願尊貴、榮耀、豐富，<br/>歸給羔羊直到永古！<br/>耶穌基督是我救主！<br/>阿利路亞！阿利路亞！<br/>阿利路亞！讚美主！<br/>',NULL,8169,8169);
INSERT INTO stanza VALUES('C194','1','神靈今是基督的靈，<br/>如此來作實際的靈。<br/>祂乃基督住在我靈，<br/>使祂作我實際供應。<br/>',NULL,8170,8170);
INSERT INTO stanza VALUES('C194','2','基督乃是神的化身，<br/>顯明神的聖別性情；<br/>這靈也是基督化身，<br/>啟示基督作我生命。<br/>',NULL,8171,8171);
INSERT INTO stanza VALUES('C194','3','神的本性一切豐滿，<br/>全在基督有形有體；<br/>基督帶著一切豐富，<br/>成為這靈來作實際。<br/>',NULL,8172,8172);
INSERT INTO stanza VALUES('C194','4','父在子裡得著彰顯，<br/>子今成為實際的靈；<br/>父是源頭，子是流出，<br/>靈是流入作我供應。<br/>',NULL,8173,8173);
INSERT INTO stanza VALUES('C194','5','當靈剛強我裡面人，<br/>基督安家在我心間，<br/>父所有的一切豐滿，<br/>就將我人全都充滿。<br/>',NULL,8174,8174);
INSERT INTO stanza VALUES('C194','6','在子裡面我得著父，<br/>接受祂來應付所缺；<br/>在靈裡面我經歷子<br/>作我生命和我一切。<br/>',NULL,8175,8175);
INSERT INTO stanza VALUES('C194','7','求主用你神聖實際，<br/>藉著你靈將我充滿，<br/>使我得以充滿了你，<br/>將你豐富享得完全。<br/>',NULL,8176,8176);
INSERT INTO stanza VALUES('C195','1','我在主前等候，<br/>並且專心祈禱，<br/>盼望能以從罪得釋放；<br/>一日主施憐憫，<br/>答應我的求告，<br/>聖靈顯在我心房。<br/>',NULL,8177,8177);
INSERT INTO stanza VALUES('C195','chorus','聖靈顯在我心房，<br/>聖靈解開我捆綁，<br/>我就從罪得釋放，<br/>我就心口滿頌揚，<br/>聖靈顯在我心房。<br/>',NULL,8178,8178);
INSERT INTO stanza VALUES('C195','2','我是多年軟弱、<br/>殘廢、無用器皿，<br/>而又明知自己當剛強；<br/>主是忽然施恩，<br/>使我喜樂滿心，<br/>聖靈顯在我心房。<br/>',NULL,8179,8179);
INSERT INTO stanza VALUES('C195','3','我今能以見證<br/>聖靈奇妙能力，<br/>因為我心已經被開廣；<br/>我已脫離驕傲，<br/>我已洗淨罪習，<br/>聖靈顯在我心房。<br/>',NULL,8180,8180);
INSERT INTO stanza VALUES('C195','4','我今已有把握，<br/>我能看見神面，<br/>因主已經將我洗透亮；<br/>主今住在我靈，<br/>作我彀用恩典，<br/>聖靈顯在我心房。<br/>',NULL,8181,8181);
INSERT INTO stanza VALUES('C196','1','今日我們神的靈，<br/>成了耶穌基督靈；<br/>死而復活的神人，<br/>得榮升天，此靈成。<br/>',NULL,8182,8182);
INSERT INTO stanza VALUES('C196','2','從那升天的耶穌，<br/>這靈降到我靈裡，<br/>使祂一切的實際，<br/>都成我們的經歷。<br/>',NULL,8183,8183);
INSERT INTO stanza VALUES('C196','3','這個耶穌基督靈，<br/>包含一切的成分；<br/>神、人二性其中存，<br/>人生、神榮也藏隱。<br/>',NULL,8184,8184);
INSERT INTO stanza VALUES('C196','4','死的功能及受苦、<br/>復活大能並升天、<br/>寶座、權柄和國度，<br/>全都在這靈中含。<br/>',NULL,8185,8185);
INSERT INTO stanza VALUES('C196','5','憑這一切的成分，<br/>這靈運行在我靈；<br/>藉祂膏油的塗抹，<br/>我得享受主豐盛。<br/>',NULL,8186,8186);
INSERT INTO stanza VALUES('C196','6','這個包羅萬有靈，<br/>是我一切的祕訣；<br/>多方作工在我裡，<br/>使神作我的一切。<br/>',NULL,8187,8187);
INSERT INTO stanza VALUES('C197','1','應當將此消息，<br/>遍傳有人之地；<br/>只要有人有心，<br/>只要有人飲泣；<br/>信徒就當殷勤，<br/>傳此喜樂信息：<br/>保惠師已經來！<br/>',NULL,8188,8188);
INSERT INTO stanza VALUES('C197','chorus','保惠師已經來！<br/>保惠師已經來！<br/>主所應許已賜，<br/>聖靈從天來此；<br/>應當將此消息，<br/>遍傳有人之地，<br/>保惠師已經來！<br/>',NULL,8189,8189);
INSERT INTO stanza VALUES('C197','2','漫漫黑夜已過，<br/>最終晨曉已破，<br/>悲哭聲音停止，<br/>哀求聲音不作，<br/>遠山現出金絲，<br/>晨曦已在炳爍：<br/>保惠師已經來！<br/>',NULL,8190,8190);
INSERT INTO stanza VALUES('C197','3','請看萬王之王，<br/>帶著醫治之光，<br/>來使屬靈囚犯，<br/>都得完全釋放；<br/>現今空虛牢監，<br/>到處凱歌高唱：<br/>保惠師已經來！<br/>',NULL,8191,8191);
INSERT INTO stanza VALUES('C197','4','無限神聖的愛！<br/>我的拙口缺才，<br/>向著流浪的人，<br/>說你無比恩愛－我怎是個罪身，<br/>你竟肯來同在：<br/>保惠師已經來！<br/>',NULL,8192,8192);
INSERT INTO stanza VALUES('C197','5','唱阿，直到回響<br/>飛射上下碧蒼；<br/>所有使者在上<br/>響應在下聲浪，<br/>無窮的愛頌揚，<br/>我來引吭歌唱：<br/>保惠師已經來！<br/>',NULL,8193,8193);
INSERT INTO stanza VALUES('C198','1','世人看你不過仍是<br/>平常的拿撒勒人，<br/>活在地上常受輕視，<br/>十字架上終捨身。<br/>從人眼光你的歷史<br/>到此已經無下文。<br/>',NULL,8194,8194);
INSERT INTO stanza VALUES('C198','2','天上情形何等不同！<br/>當你升天的時候，<br/>榮耀的神因你順從，<br/>已命宇宙在等候，<br/>準備迎接、準備歌頌<br/>你作宇宙的元首。<br/>',NULL,8195,8195);
INSERT INTO stanza VALUES('C198','3','神已設立你為基督，<br/>神已設立你為主，<br/>天上地下已經無處<br/>不知你今的特獨，<br/>沒有一個能不俯伏，<br/>沒有一個不順服。<br/>',NULL,8196,8196);
INSERT INTO stanza VALUES('C198','4','遠在天上發生的事，<br/>我今如何能知情？<br/>因神要證此事屬實，<br/>祂就從天降聖靈，<br/>在我身上成為恩賜，<br/>來證耶穌得權柄。<br/>',NULL,8197,8197);
INSERT INTO stanza VALUES('C198','5','我身所顯聖靈停駐，<br/>證明耶穌是基督，<br/>神立基督若是耶穌，<br/>我身必有聖靈注；<br/>永遠真實、永遠堅固，<br/>拿撒勒人已是主。<br/>',NULL,8198,8198);
INSERT INTO stanza VALUES('C198','6','耶穌是主！耶穌是主！<br/>永不改變的事實！<br/>我被聖靈已經灌注，<br/>也是事實的恩賜；<br/>我今只能讚美稱祝，<br/>聖靈恩賜已開始。<br/>',NULL,8199,8199);
INSERT INTO stanza VALUES('C199','1','榮耀的主，你曾經<br/>從天賜下你聖靈；<br/>將祂各種的恩惠，<br/>賜你在下的召會；<br/>求你憑你的信實，<br/>再次賜下你恩賜。<br/>',NULL,8200,8200);
INSERT INTO stanza VALUES('C199','2','我今已經奉你名，<br/>受浸歸你成一靈；<br/>你的身體已得有<br/>所有恩賜和成就；<br/>因我也是一肢體，<br/>不能不也得能力。<br/>',NULL,8201,8201);
INSERT INTO stanza VALUES('C199','3','賜我能力來證明<br/>你是已得最高名；<br/>賜我恩賜來傳說<br/>你救罪人的工作；<br/>賜我知識來事奉，<br/>使你子民能得勝。<br/>',NULL,8202,8202);
INSERT INTO stanza VALUES('C199','4','當我在此受按手、<br/>在此許願的時候，<br/>在此嚴肅望恩賜，<br/>求你按你的事實，<br/>傾下無窮的能力，<br/>來使每人作用器。<br/>',NULL,8203,8203);
INSERT INTO stanza VALUES('C200','1','現今神的聖別之靈，<br/>乃是神的生命之靈；<br/>將我點活，賜我生命，<br/>使我適合神所命定。<br/>',NULL,8204,8204);
INSERT INTO stanza VALUES('C200','2','祂作活水，解我乾渴，<br/>永遠供我生命水流；<br/>供應基督作我生命，<br/>我心願望祂全成就。<br/>',NULL,8205,8205);
INSERT INTO stanza VALUES('C200','3','照亮我以生命之光，<br/>從我全人驅盡黑暗；<br/>供應基督作我亮光，<br/>使我黑夜變成中天。<br/>',NULL,8206,8206);
INSERT INTO stanza VALUES('C200','4','剛強我以生命大能，<br/>加力給我裡面的人；<br/>供應基督作我能力，<br/>為神計畫運行施恩。<br/>',NULL,8207,8207);
INSERT INTO stanza VALUES('C200','5','藉著神聖生命的律，<br/>釋放我脫罪惡的律；<br/>藉著神的聖別性情，<br/>在我裡面將我規律。<br/>',NULL,8208,8208);
INSERT INTO stanza VALUES('C200','6','祂作神的生命之靈，<br/>豐盛果子藉我結出；<br/>顯出神的各種美德，<br/>藉著生命供人基督。<br/>',NULL,8209,8209);
INSERT INTO stanza VALUES('C200','7','生命之靈供應生命，<br/>用神生命將我變化；<br/>更新我的裡面部分，<br/>使與基督相像無差。<br/>',NULL,8210,8210);
INSERT INTO stanza VALUES('C200','8','求主用你生命的靈，<br/>將我各部全都充滿，<br/>直到全人盡都浸透，<br/>使你生命在我彰顯。<br/>',NULL,8211,8211);
INSERT INTO stanza VALUES('C201','1','井阿，湧上水來！<br/>我願被挖透！<br/>挖去一切障礙，<br/>活水好湧流！<br/>',NULL,8212,8212);
INSERT INTO stanza VALUES('C201','2','磐石已經裂開，<br/>活水已流出；<br/>流到我的心懷，<br/>竟然被堵住。<br/>',NULL,8213,8213);
INSERT INTO stanza VALUES('C201','3','我要禱告挖井，<br/>挖去我泥土；<br/>直到挖出聖靈，<br/>活水能流出。<br/>',NULL,8214,8214);
INSERT INTO stanza VALUES('C201','4','禱告還要禱告，<br/>挖了還要挖！<br/>直到挖得透了，<br/>禱告得練達。<br/>',NULL,8215,8215);
INSERT INTO stanza VALUES('C201','5','不需磐石再開，<br/>只要我挖透；<br/>不需活水再來，<br/>只要我湧流。<br/>',NULL,8216,8216);
INSERT INTO stanza VALUES('C201','6','聖靈降在我身，<br/>不過是澆灌；<br/>聖靈住在我心，<br/>纔是活水泉。<br/>',NULL,8217,8217);
INSERT INTO stanza VALUES('C201','7','我所急切需要，<br/>非僅求澆灌，<br/>更是透徹禱告，<br/>挖通活水泉。<br/>',NULL,8218,8218);
INSERT INTO stanza VALUES('C201','8','挖到再無事物<br/>能將靈阻隔；<br/>挖到泉源湧出<br/>活水的江河！<br/>',NULL,8219,8219);
INSERT INTO stanza VALUES('C201','9','井阿，湧上水來！<br/>我願被挖透！<br/>挖去一切障礙，<br/>活水好湧流！<br/>',NULL,8220,8220);
INSERT INTO stanza VALUES('C202','1','在曠野加低斯，<br/>以色列百姓，<br/>因乾渴快要死，<br/>神就發命令：<br/>吩咐磐石發出活水來！<br/>擊打勿再施，<br/>因早已裂開；<br/>只要吩咐，活水就流開。<br/>',NULL,8221,8221);
INSERT INTO stanza VALUES('C202','chorus','吩咐磐石發出活水來！<br/>聖靈早已賜，<br/>早與你同在；<br/>一切的豐富，<br/>等著你接受；<br/>你若肯信服，<br/>必享祂富有。<br/>',NULL,8222,8222);
INSERT INTO stanza VALUES('C202','2','那永久的磐石，<br/>今仍是裂開，<br/>神聖靈的恩賜，<br/>今仍在等待；<br/>祂仍在說，掙扎果為何？<br/>只與主死合，<br/>立刻解乾渴；<br/>一經約但，就必得聖鴿。<br/>',NULL,8223,8223);
INSERT INTO stanza VALUES('C202','3','但願心肯簡單，<br/>完全的相信！<br/>但願心能平安，<br/>不再苦求尋！<br/>如同嬰孩，靜臥主懷間，<br/>向世界斷奶，<br/>飽嘗祂愛甜，<br/>靈得安息，全由祂充滿。<br/>',NULL,8224,8224);
INSERT INTO stanza VALUES('C203','1','生命活水的江河，<br/>流自天上的寶座，<br/>滿帶祝福而流著，<br/>從神基督流到我。<br/>',NULL,8225,8225);
INSERT INTO stanza VALUES('C203','chorus','生命活水的江河，<br/>人人可以白喝；<br/>願這活水通過我，<br/>流到眾人，解乾渴。<br/>',NULL,8226,8226);
INSERT INTO stanza VALUES('C203','2','活水明亮如水晶，<br/>帶著豐盛的供應，<br/>渴者喝了得生命，<br/>不需代價，乃白奉。<br/>',NULL,8227,8227);
INSERT INTO stanza VALUES('C203','3','哦主，修理、潔淨我，<br/>使我成為你運河；<br/>倒空、充滿、使用我，<br/>使我順服無阻隔。<br/>',NULL,8228,8228);
INSERT INTO stanza VALUES('C203','4','這時，也惟有這時，<br/>水流纔能無阻止；<br/>如此，也惟有如此，<br/>你的豐盛人纔知。<br/>',NULL,8229,8229);
INSERT INTO stanza VALUES('C203','5','今將一切全奉獻，<br/>全都帶到主腳前；<br/>凡事只有一心願，<br/>活水從我能溢漫。<br/>',NULL,8230,8230);
INSERT INTO stanza VALUES('C204','1','生命活水水晶河，<br/>流自天上的寶座，<br/>帶著權柄施交通，<br/>無處不能流得通。<br/>',NULL,8231,8231);
INSERT INTO stanza VALUES('C204','chorus','生命活水在流通，<br/>處處都要流得通，<br/>帶著權柄施交通，<br/>處處都要流得通。<br/>',NULL,8232,8232);
INSERT INTO stanza VALUES('C204','2','生命活水是聖靈，<br/>是神流出作生命，<br/>帶著權柄而流通，<br/>處處都要流得通。<br/>',NULL,8233,8233);
INSERT INTO stanza VALUES('C204','3','河在精金街中流，<br/>表明路在何處有；<br/>活水若在神性流，<br/>在此就有路可走。<br/>',NULL,8234,8234);
INSERT INTO stanza VALUES('C204','4','河的兩岸生命樹，<br/>表明神來作食物，<br/>必須活水能流通，<br/>纔能供應得無窮。<br/>',NULL,8235,8235);
INSERT INTO stanza VALUES('C204','5','主阿，你曾被裂開，<br/>為將活水流出來；<br/>求你也將我打破，<br/>讓你活水能通過。<br/>',NULL,8236,8236);
INSERT INTO stanza VALUES('C205','1','活水湧流，活水湧流，<br/>湧自榮耀的聖殿，<br/>經過聖殿出入之口，<br/>並牠分別的界限。<br/>',NULL,8237,8237);
INSERT INTO stanza VALUES('C205','chorus','神的活水湧流，<br/>帶來新鮮的供應，<br/>吞滅死亡，不稍存留，<br/>顯出生命的豐盛。<br/>',NULL,8238,8238);
INSERT INTO stanza VALUES('C205','2','活水湧流，湧流通暢，<br/>為著神聖的榮耀，<br/>一切全獻祭壇之上，<br/>凡事以此為首要。<br/>',NULL,8239,8239);
INSERT INTO stanza VALUES('C205','3','活水湧流，湧流無限，<br/>凡事都由神量過，<br/>經過神的量度審判，<br/>一切全歸神得著。<br/>',NULL,8240,8240);
INSERT INTO stanza VALUES('C205','4','活水湧流，越流越盛，<br/>成為洶湧的江河，<br/>人就無法再有所行，<br/>只能靠恩而生活。<br/>',NULL,8241,8241);
INSERT INTO stanza VALUES('C206','1','主，我曾否叫聖靈憂愁，<br/>流蕩、隨便並冷落？<br/>然而我的犯罪和退後，<br/>未曾叫祂厭倦過。<br/>',NULL,8242,8242);
INSERT INTO stanza VALUES('C206','chorus','求你多賜我們以聖靈，<br/>讓祂光照並焚燒，<br/>將『你』供給我們<br/>作生命，<br/>使我不住的禱告。<br/>',NULL,8243,8243);
INSERT INTO stanza VALUES('C206','2','你的聖靈曾如何忍耐，<br/>等我慢慢心轉變；<br/>我曾如何棄絕你熱愛，<br/>當祂為我憂心煎。<br/>',NULL,8244,8244);
INSERT INTO stanza VALUES('C206','3','你的聖靈今在我心內，<br/>我要以祂為我主；<br/>因為愛你使我能敬畏<br/>你的最小的宣佈。<br/>',NULL,8245,8245);
INSERT INTO stanza VALUES('C206','4','我們現今雖不能愛你，<br/>如你那樣愛我們；<br/>你在我心若將火點起，<br/>牠就不會終冷沉。<br/>',NULL,8246,8246);
INSERT INTO stanza VALUES('C207','1','神賜祂的能力<br/>在我窮苦心內，<br/>時刻保守提挈，<br/>灌以必需恩惠，<br/>藉靈住我裡面，<br/>掌管我的全人，<br/>用愛發出火焰，<br/>在我心內直焚。<br/>',NULL,8247,8247);
INSERT INTO stanza VALUES('C207','chorus','焚燒在我心內，<br/>焚燒在我心內；<br/>愛焰自天傾下，<br/>焚燒在我心內！<br/>聖靈已來保惠，<br/>主名應當讚美，<br/>愛焰自天傾下，<br/>焚燒在我心內！<br/>',NULL,8248,8248);
INSERT INTO stanza VALUES('C207','2','我在架下低頭，<br/>我在壇上奉獻，<br/>此生一切所有，<br/>都呈我主腳前；<br/>祂為我付贖價，<br/>祂召我得安息，<br/>祂使天火降下，<br/>悅納我的活祭。<br/>',NULL,8249,8249);
INSERT INTO stanza VALUES('C207','3','我無任何功行，<br/>惟有神的應許；<br/>我藉愛子受刑，<br/>蒙恩作神兒女。<br/>榮耀歸於我神，<br/>阿利路亞，阿們；<br/>這愛激勵至深，<br/>如火內心在焚。<br/>',NULL,8250,8250);
INSERT INTO stanza VALUES('C208','1','我今舉手向你請，<br/>要你賜下焚燒靈，<br/>焚燒一切所歡喜，<br/>不留一點為自己。<br/>',NULL,8251,8251);
INSERT INTO stanza VALUES('C208','chorus','求你賜下焚燒靈，<br/>成我畢生大事情；<br/>滿足我心的要求，<br/>用火焚燒到無有；<br/>等候，等候，<br/>我們等候焚燒靈。<br/>',NULL,8252,8252);
INSERT INTO stanza VALUES('C208','2','我今壇上來獻祭，<br/>擺上全人靈、魂、體；<br/>求將情慾都解脫，<br/>並來充滿每角落。<br/>',NULL,8253,8253);
INSERT INTO stanza VALUES('C208','3','我今真切已犧牲<br/>我所寶貝的一生，<br/>完全為著寶貝主，<br/>因祂流血來救贖。<br/>',NULL,8254,8254);
INSERT INTO stanza VALUES('C208','4','我今以信來領取<br/>血下權利的給予；<br/>靠你得勝的名字，<br/>所有應許成現實。<br/>',NULL,8255,8255);
INSERT INTO stanza VALUES('C209','1','耶穌，你的全勝的愛，<br/>已經澆灌我心，<br/>我心就不再會搖擺，<br/>就能生根於神，<br/>就能生根於神。<br/>',NULL,8256,8256);
INSERT INTO stanza VALUES('C209','2','但願聖火今在我心，<br/>就已發旺不休；<br/>燒掉所有卑情下品，<br/>並使高山鎔流。<br/>',NULL,8257,8257);
INSERT INTO stanza VALUES('C209','3','你曾賜下祭壇火炭，<br/>求你燒掉我罪；<br/>我向焚燒的靈呼喊，<br/>主靈，滿我心內。<br/>',NULL,8258,8258);
INSERT INTO stanza VALUES('C209','4','我心要接鍛鍊的火，<br/>將我舊造燒絕；<br/>散佈生命在每角落，<br/>並使全人聖潔。<br/>',NULL,8259,8259);
INSERT INTO stanza VALUES('C209','5','搖動的心求你扶掖，<br/>使牠變成堅崖；<br/>基督成為我的世界，<br/>我的全心成愛。<br/>',NULL,8260,8260);
INSERT INTO stanza VALUES('C210','1','主，求你向我吹聖靈，<br/>教我如何吸入你；<br/>助我向你胸懷一傾<br/>我的犯罪與自己。<br/>',NULL,8261,8261);
INSERT INTO stanza VALUES('C210','chorus','我是呼出我的愁苦，<br/>呼出我罪污；<br/>我是吸入，一直吸入，<br/>你所有豐富。<br/>',NULL,8262,8262);
INSERT INTO stanza VALUES('C210','2','我是呼出我的生命，<br/>我纔可能被充滿；<br/>放棄軟弱或是力勁，<br/>吸入憐憫和恩湛。<br/>',NULL,8263,8263);
INSERT INTO stanza VALUES('C210','3','呼出我的罪律桎梏，<br/>你已為我全除摒；<br/>吸入你的聖潔豐富，<br/>發現惟你是生命。<br/>',NULL,8264,8264);
INSERT INTO stanza VALUES('C210','4','我正呼出我的憂愁<br/>在你慈愛的胸臆；<br/>吸入你的喜樂、保守，<br/>吸入你的甜安息。<br/>',NULL,8265,8265);
INSERT INTO stanza VALUES('C210','5','我正呼出我的病勢，<br/>你早已為我負擔；<br/>我正吸入你的醫治，<br/>因你早已賜平安。<br/>',NULL,8266,8266);
INSERT INTO stanza VALUES('C210','6','我今呼出我的羨慕，<br/>入你慈愛的耳中；<br/>我今吸入你的答覆，<br/>平靜疑惑和驚恐。<br/>',NULL,8267,8267);
INSERT INTO stanza VALUES('C210','7','我今每刻都在呼吸<br/>你的生命作生命；<br/>一呼一吸都在乎你，<br/>求你由我來顯明。<br/>',NULL,8268,8268);
INSERT INTO stanza VALUES('C211','1','生命之主，向我吹氣，<br/>將你活泉從我開啟；<br/>在我裡面將我推動，<br/>生命之光照我心中。<br/>',NULL,8269,8269);
INSERT INTO stanza VALUES('C211','2','主，何希奇，你在我裡，<br/>不必天上、陰間尋你，<br/>一回靈裡，就得見你，<br/>靈靈接觸，毫無距離。<br/>',NULL,8270,8270);
INSERT INTO stanza VALUES('C211','3','你是我的在天中保，<br/>又是我的靈中恩膏；<br/>凡你神前為我所作，<br/>都在我靈給我摸著。<br/>',NULL,8271,8271);
INSERT INTO stanza VALUES('C211','4','但是我心何等不忠，<br/>常雖深感，仍不順從；<br/>求主眷憐，吹氣、推動，<br/>使我全人都盡功用。<br/>',NULL,8272,8272);
INSERT INTO stanza VALUES('C211','5','當我靈裡癟氣、下沉，<br/>難將你恩向人言陳，<br/>求你從我裡面吹氣，<br/>使我完全充滿了你。<br/>',NULL,8273,8273);
INSERT INTO stanza VALUES('C212','1','聖靈的大風，<br/>從天來吹動，<br/>吹到我群眾，如在五旬；<br/>吹軟我硬心，<br/>吹活我全人，<br/>吹得我更新，罪孽脫盡。<br/>',NULL,8274,8274);
INSERT INTO stanza VALUES('C212','chorus','吹到！吹到！<br/>聖靈大風吹到！<br/>覆罩！覆罩！<br/>靈恩大雲覆罩！<br/>焚燒！焚燒！<br/>聖別烈火焚燒！<br/>顯耀！顯耀！<br/>神精金顯耀！<br/>',NULL,8275,8275);
INSERT INTO stanza VALUES('C212','2','靈恩的大雲，<br/>滿帶神洪恩，<br/>覆罩我眾人，如覆帳幕；<br/>覆得我得生，<br/>覆得我成聖，<br/>覆到我屬靈，神可居住。<br/>',NULL,8276,8276);
INSERT INTO stanza VALUES('C212','3','聖別的烈火，<br/>來從我燒著，<br/>燒到每角落，將人純潔；<br/>燒盡了邪污，<br/>燒盡了俗物，<br/>使人、神相符，<br/>全聖無劣。<br/>',NULL,8277,8277);
INSERT INTO stanza VALUES('C212','4','光耀的精金，<br/>照進我內心，<br/>使我得有分神的性情；<br/>神性調人性，<br/>人靈聯神靈，<br/>使神的生命顯於人形。<br/>',NULL,8278,8278);
INSERT INTO stanza VALUES('C213','1','主阿，願你屬天之風，<br/>現在吹到我身！<br/>用那感人、復興大能，<br/>吹動我的心魂。<br/>',NULL,8279,8279);
INSERT INTO stanza VALUES('C213','chorus','大能主阿，求你降臨，<br/>用你聖靈來吹！<br/>用你大能將我吹過，<br/>帶來湧流活水！<br/>',NULL,8280,8280);
INSERT INTO stanza VALUES('C213','2','用你能力之靈來吹，<br/>吹去所有障礙；<br/>用你生命之靈來呼，<br/>呼進你的大愛。<br/>',NULL,8281,8281);
INSERT INTO stanza VALUES('C213','3','你靈具有七倍豐富，<br/>為使我享你分；<br/>求你叫我有分這靈，<br/>經歷三一之神。<br/>',NULL,8282,8282);
INSERT INTO stanza VALUES('C214','1','哦主，向我吹風，<br/>我們在此等候；<br/>用你大風來吹，<br/>帶給我們自由；<br/>吹到我們眾人<br/>無不復興得透；<br/>哦主，求你向我吹風！<br/>',NULL,8283,8283);
INSERT INTO stanza VALUES('C214','chorus','哦主，現在將我來吹！<br/>吹去所有鬆懶沉睡！<br/>願你大風來臨，<br/>將我退落吹盡！<br/>哦主，求你向我吹風。<br/>',NULL,8284,8284);
INSERT INTO stanza VALUES('C214','2','哦主，用愛來吹，<br/>吹熱冰冷的心；<br/>將那屬天之氣，<br/>吹到我的全魂；<br/>吹到我們眾人<br/>毫無冷淡留存；<br/>哦主，求你向我吹風！<br/>',NULL,8285,8285);
INSERT INTO stanza VALUES('C214','3','哦主，用力來吹，<br/>吹起死沉的靈；<br/>吹到我們復甦，<br/>充滿復活生命；<br/>吹到我們眾人<br/>無不剛強有能；<br/>哦主，求你向我吹風！<br/>',NULL,8286,8286);
INSERT INTO stanza VALUES('C215','1','奇妙的恩膏住我裡面，<br/>凡事都將我教導；<br/>將神的同在時常帶給我，<br/>使我得與神相交。<br/>',NULL,8287,8287);
INSERT INTO stanza VALUES('C215','chorus','在我裡面有一奇妙恩膏，<br/>有一奇妙恩膏，<br/>凡事都教導；<br/>在我裡面有一奇妙恩膏，<br/>凡事都將我教導。<br/>',NULL,8288,8288);
INSERT INTO stanza VALUES('C215','2','聖靈的運行在我裡面，<br/>柔細如同純膏油；<br/>這乃是根據主血的洗淨，<br/>並要存在到永久。<br/>',NULL,8289,8289);
INSERT INTO stanza VALUES('C215','3','祂用神本質將我塗抹，<br/>我得主觀認識神；<br/>使我能得著神所有成分，<br/>浸透我的整個人。<br/>',NULL,8290,8290);
INSERT INTO stanza VALUES('C215','4','憑著這裡面生命塗抹，<br/>我今行在交通中；<br/>憑真理之光，<br/>活在神裡面，<br/>恩典之愛貫我衷。<br/>',NULL,8291,8291);
INSERT INTO stanza VALUES('C216','1','何處灑了贖罪之血，<br/>何處就抹聖膏油；<br/>藉此人得與神接觸，<br/>交通也得蒙保守。<br/>',NULL,8292,8292);
INSERT INTO stanza VALUES('C216','2','血是救贖所有表記，<br/>洗淨所有的罪惡；<br/>膏油是靈所有表號，<br/>將神帶給人得著。<br/>',NULL,8293,8293);
INSERT INTO stanza VALUES('C216','3','血是說出神之所作，<br/>膏油說出神所是；<br/>藉祂所作並祂所是，<br/>神就與人調無弛。<br/>',NULL,8294,8294);
INSERT INTO stanza VALUES('C216','4','藉著基督血的洗淨，<br/>我得脫去眾罪惡；<br/>藉著靈的運行塗抹，<br/>神的成分我得著。<br/>',NULL,8295,8295);
INSERT INTO stanza VALUES('C216','5','藉這洗淨和這塗抹，<br/>我得與神合為一；<br/>藉著這血和這膏油，<br/>我得享受神自己。<br/>',NULL,8296,8296);
INSERT INTO stanza VALUES('C216','6','當我真是需要主血，<br/>就要憑信求洗淨；<br/>永遠順從膏油塗抹，<br/>與神同活並同行。<br/>',NULL,8297,8297);
INSERT INTO stanza VALUES('C216','7','如此，認識神就是光，<br/>並且經歷神是愛，<br/>享受神作我的一切，<br/>與神合一毫無礙。<br/>',NULL,8298,8298);
INSERT INTO stanza VALUES('C217','1','何等榮耀，何等福氣，<br/>真理聖靈在我心，<br/>見證救主，啟示真理，<br/>光照、安慰並指引。<br/>',NULL,8299,8299);
INSERT INTO stanza VALUES('C217','chorus','充滿我！充滿我！<br/>願主聖靈充滿我；<br/>將我倒空，將我剝奪，<br/>願主聖靈充滿我。<br/>',NULL,8300,8300);
INSERT INTO stanza VALUES('C217','2','願主所說在我證實，<br/>生命聖靈將我釋，<br/>使我脫離罪律轄制，<br/>脫離死亡的權勢。<br/>',NULL,8301,8301);
INSERT INTO stanza VALUES('C217','3','我如困鹿切慕溪水，<br/>深願聖靈解我渴，<br/>使我嘗到豐滿滋味，<br/>流出活水的江河。<br/>',NULL,8302,8302);
INSERT INTO stanza VALUES('C217','4','願我自己被置死地，<br/>使我充滿主聖靈；<br/>願我全人歸主管理，<br/>使我變成主榮形。<br/>',NULL,8303,8303);
INSERT INTO stanza VALUES('C218','1','我已得蒙寶血洗淨，<br/>充滿天上的喜樂；<br/>我已得著永遠生命，<br/>成為活水的運河。<br/>',NULL,8304,8304);
INSERT INTO stanza VALUES('C218','chorus','我願作主活水運河，<br/>充滿生命的聖靈，<br/>灌輸生命，解人乾渴，<br/>湧流活水無止境。<br/>',NULL,8305,8305);
INSERT INTO stanza VALUES('C218','2','奇妙救恩，甜美、豐盛，<br/>滿足我心如我意；<br/>我願天天作此見證，<br/>吸引多人來歸依。<br/>',NULL,8306,8306);
INSERT INTO stanza VALUES('C218','3','主，你使我完全成聖，<br/>作你貴重的器皿，<br/>充滿恩典，充滿生命，<br/>供應飢渴的人群。<br/>',NULL,8307,8307);
INSERT INTO stanza VALUES('C218','4','將我倒空，將我充滿，<br/>願我全人你佔有；<br/>活水江河洋溢、氾濫，<br/>湧流生命到永久。<br/>',NULL,8308,8308);
INSERT INTO stanza VALUES('C219','1','主，你知道所有乾渴，<br/>在這不足尋求心；<br/>我心羨慕何等深刻，<br/>惟你能使不饑饉。<br/>',NULL,8309,8309);
INSERT INTO stanza VALUES('C219','chorus','今尋求，今尋求，<br/>賜你聖靈的富有。<br/>',NULL,8310,8310);
INSERT INTO stanza VALUES('C219','2','行為失敗，見證失敗，<br/>工作失敗已明顯，<br/>無果之勞、非主之態，<br/>對你沒有讚美獻。<br/>',NULL,8311,8311);
INSERT INTO stanza VALUES('C219','3','我今向你承認我的<br/>所有失敗和邪惡，<br/>所有自滿，所有剛愎，<br/>所有心裡的隱慝。<br/>',NULL,8312,8312);
INSERT INTO stanza VALUES('C219','4','父阿，救我脫離自己，<br/>脫離化裝的驕傲；<br/>帶我與主同到死地，<br/>知道同釘的奇道。<br/>',NULL,8313,8313);
INSERT INTO stanza VALUES('C219','5','從今不再是我工作，<br/>我想，我愛，或我說；<br/>惟獨乃是基督生活，<br/>時時刻刻通過我。<br/>',NULL,8314,8314);
INSERT INTO stanza VALUES('C219','6','但願你的滿有聖靈，<br/>流通在我的衷表，<br/>好叫對人我是證明，<br/>對你乃是歸榮耀。<br/>',NULL,8315,8315);
INSERT INTO stanza VALUES('C219','7','父阿，我奉子名禱告，<br/>我信禱告已答應，<br/>我今讚美答應可靠，<br/>安息只因話足憑。<br/>',NULL,8316,8316);
INSERT INTO stanza VALUES('C219','chorus','就讚美，就讚美，<br/>因你已聽我禱告。<br/>第三節的『隱慝，』意思是隱藏的惡念。<br/>',NULL,8317,8317);
INSERT INTO stanza VALUES('C220','1','我在靈中從靈而生，<br/>已得成為神兒子，<br/>我已得著神的聖靈，<br/>住在我靈作印、質。<br/>但主，我需得祂更多，<br/>使我得享你豐盛；<br/>願你用祂將我充滿，<br/>賜我豐盛的生命。<br/>',NULL,8318,8318);
INSERT INTO stanza VALUES('C220','2','你的聖靈在我裡面，<br/>不過是你生命靈，<br/>使我藉著祂之所是，<br/>可得有分你豐盛。<br/>但我仍需你的聖靈，<br/>作那上頭的能力，<br/>使我藉祂得著裝備，<br/>為你作工，事奉你。<br/>',NULL,8319,8319);
INSERT INTO stanza VALUES('C220','3','求主使我經歷靈浸，<br/>穿上上頭的能力；<br/>藉著你這能力『外衣，』<br/>我可進攻你仇敵。<br/>願你大風今向我吹，<br/>賜我火焰的舌頭，<br/>使我作你受膏證人，<br/>將你心願來成就。<br/>',NULL,8320,8320);
INSERT INTO stanza VALUES('C220','4','即使已得聖靈能力，<br/>我仍需要你恩賜，<br/>使我能盡肢體功用，<br/>與眾肢體同服事。<br/>主，藉你靈豐滿澆灌，<br/>所需恩賜分給我，<br/>使你身體得著建造，<br/>作你祝福的結果。<br/>',NULL,8321,8321);
INSERT INTO stanza VALUES('C220','5','為你榮耀並你國度，<br/>聽你身體這呼求！<br/>滿足我們所有需要，<br/>使你聖旨得成就。<br/>願我豐滿有分你靈，<br/>多方將祂來應用；<br/>裡面充滿、外面澆灌、<br/>以及恩賜，全貫通。<br/>',NULL,8322,8322);
INSERT INTO stanza VALUES('C221','1','當主基督降生為人，<br/>乃由聖靈而成孕；<br/>在祂工作開始之先，<br/>聖靈充滿也有分。<br/>但在開始作工之時，<br/>祂仍受了聖靈浸；<br/>藉此穿上上頭能力，<br/>為盡神聖的職分。<br/>',NULL,8323,8323);
INSERT INTO stanza VALUES('C221','2','彼得和主其他門徒，<br/>都已由靈所重生；<br/>主向他們吹氣之時，<br/>早已吸入了聖靈。<br/>但是後來又都受了<br/>主在聖靈裡的浸，<br/>穿上能力，得著裝備，<br/>神聖職分纔能盡。<br/>',NULL,8324,8324);
INSERT INTO stanza VALUES('C221','3','大數掃羅，以弗所人，<br/>撒瑪利亞的信徒，<br/>都已得著聖靈重生，<br/>且有聖靈在內住。<br/>但當有人為其按手，<br/>又都經歷聖靈浸，<br/>穿上上頭來的能力，<br/>見證基督，事奉神。<br/>',NULL,8325,8325);
INSERT INTO stanza VALUES('C221','4','我們也在相信之時，<br/>都已由靈而重生，<br/>並且現今得飲於祂，<br/>天天享受祂豐盛。<br/>然而我們仍需經歷<br/>聖靈裡面的受浸，<br/>藉此穿上上頭能力，<br/>得著裝備，盡職分。<br/>',NULL,8326,8326);
INSERT INTO stanza VALUES('C221','5','求主使我經歷靈浸，<br/>這是我的真需要；<br/>上頭能力給我穿上，<br/>為著召會的建造。<br/>願主現在給我經歷，<br/>我今如此迫切求；<br/>使我豐滿經歷靈浸，<br/>上頭能力澆我透。<br/>',NULL,8327,8327);
INSERT INTO stanza VALUES('C222','1','有福的事實，<br/>主話已啟示，<br/>我在聖靈裡面已受浸；<br/>接受這事實，<br/>毋須再延遲，<br/>我在聖靈裡面已受浸。<br/>',NULL,8328,8328);
INSERT INTO stanza VALUES('C222','chorus','接受！接受！<br/>憑信接受勿再延遲；<br/>接受！接受！<br/>憑信接受這已成事實。<br/>',NULL,8329,8329);
INSERT INTO stanza VALUES('C222','2','新約的話語，<br/>清楚已言明，<br/>我在聖靈裡面已受浸；<br/>只需我持守，<br/>不需我何行，<br/>我在聖靈裡面已受浸。<br/>',NULL,8330,8330);
INSERT INTO stanza VALUES('C222','chorus','持守！持守！<br/>憑信持守不稍鬆弛；<br/>持守！持守！<br/>憑信持守這已成事實。<br/>',NULL,8331,8331);
INSERT INTO stanza VALUES('C222','3','基督向召會，<br/>已澆下聖靈，<br/>我在聖靈裡面已受浸；<br/>分享這福分，<br/>分享得豐盛，<br/>我在聖靈裡面已受浸。<br/>',NULL,8332,8332);
INSERT INTO stanza VALUES('C222','chorus','分享！分享！<br/>憑信分享已得恩賜；<br/>分享！分享！<br/>憑信分享這已成事實。<br/>',NULL,8333,8333);
INSERT INTO stanza VALUES('C222','4','在身體裡面，<br/>與身體和諧，<br/>憑這已成事實而行動；<br/>罪惡都認清，<br/>疑惑全拒絕，<br/>因信憑這事實就行動。<br/>',NULL,8334,8334);
INSERT INTO stanza VALUES('C222','chorus','行動！行動！<br/>因信行動在身體中；<br/>行動！行動！<br/>因信憑這事實而行動。<br/>',NULL,8335,8335);
INSERT INTO stanza VALUES('C223','1','主，我來就你，<br/>自由的懇祈，<br/>求你賜我以你能力；<br/>為著你國度，<br/>能力歸我屬，<br/>坐在天上進攻你仇敵。<br/>能力！能力！<br/>給我穿上能力！<br/>穿上上頭來的大能力！<br/>能力！能力！<br/>給我穿上能力！<br/>你的身體今向你懇祈！<br/>',NULL,8336,8336);
INSERT INTO stanza VALUES('C223','2','主，我仰望你，<br/>肯定的懇祈，<br/>求你賜我以你甘雨；<br/>為著你身體，<br/>甘雨你供給，<br/>使我適合你工作所需。<br/>甘雨！甘雨！<br/>向我澆下甘雨！<br/>澆下上頭來的聖甘雨！<br/>甘雨！甘雨！<br/>向我澆下甘雨！<br/>你的身體今向你呼籲！<br/>',NULL,8337,8337);
INSERT INTO stanza VALUES('C223','3','主，我等候你，<br/>確信的懇祈，<br/>求你賜我以你聖火！<br/>為著你福音，<br/>聖火將我焚，<br/>使人悔改、相信、<br/>進神國。<br/>聖火！聖火！<br/>焚我以你聖火！<br/>帶著你的熱愛焚燒我！<br/>聖火！聖火！<br/>焚我以你聖火！<br/>你的身體如此在求著！<br/>',NULL,8338,8338);
INSERT INTO stanza VALUES('C224','1','救主基督已經高升，<br/>坐在諸天的上面，<br/>從祂父神也已得著<br/>尊貴、榮耀為冠冕；<br/>神要祂作萬有元首，<br/>使祂尊高得彰顯。<br/>',NULL,8339,8339);
INSERT INTO stanza VALUES('C224','2','從這升到神前基督，<br/>聖靈已經澆下來，<br/>澆在祂的身體上面，<br/>給祂肢體都穿戴，<br/>使那在天萬有之主，<br/>藉祂召會得敬拜。<br/>',NULL,8340,8340);
INSERT INTO stanza VALUES('C224','3','基督藉著成為肉身，<br/>將神帶到人裡面；<br/>祂也藉著死而復活，<br/>將人帶進神中間；<br/>神與人的完全調和，<br/>在祂裡面得成全。<br/>',NULL,8341,8341);
INSERT INTO stanza VALUES('C224','4','祂今已升高天之上，<br/>登上榮耀的寶座；<br/>萬主之主，萬王之王，<br/>所有主權全得著；<br/>藉著澆下祂的聖靈，<br/>已將這事證確鑿。<br/>',NULL,8342,8342);
INSERT INTO stanza VALUES('C224','5','藉將祂靈澆灌下來，<br/>祂在召會又降臨；<br/>在祂這位聖靈裡面，<br/>給全召會來施浸；<br/>如此完成的這靈浸，<br/>所有信徒都有分。<br/>',NULL,8343,8343);
INSERT INTO stanza VALUES('C224','6','阿利路亞，已經完成，<br/>一次永遠的完成！<br/>阿利路亞，此浸我承，<br/>大小信徒都得承！<br/>祂已將祂所有肢體，<br/>早都浸在祂的靈！<br/>',NULL,8344,8344);
INSERT INTO stanza VALUES('C225','1','主，你能力我今在尋求，<br/>對你工作我無所成就，<br/>懦弱、無能，<br/>實在已彀久，<br/>給我穿上能力！<br/>',NULL,8345,8345);
INSERT INTO stanza VALUES('C225','chorus','謙卑俯伏，我在此等候，<br/>誠懇迫切，我向你呼求，<br/>給我能力，給我毫不留，<br/>給我穿上能力！<br/>',NULL,8346,8346);
INSERT INTO stanza VALUES('C225','2','施恩眷顧，我今在此催，<br/>將你恩賜分給你召會，<br/>使我工作，永不再氣餒，<br/>給我穿上能力！<br/>',NULL,8347,8347);
INSERT INTO stanza VALUES('C225','3','賜上能力，帶著你權柄，<br/>如同你在五旬節所行，<br/>答應所求，答應不稍等，<br/>給我穿上能力！<br/>',NULL,8348,8348);
INSERT INTO stanza VALUES('C225','4','你的身體，如此在請願，<br/>靠著你名，因信求成全，<br/>降下甘雨，並賜下火焰，<br/>給我穿上能力！<br/>',NULL,8349,8349);
INSERT INTO stanza VALUES('C226','1','主的生命之靈，<br/>進到我裡面，<br/>如同活水解渴，<br/>作我活水泉；<br/>我可飲於這靈，<br/>且被祂充滿，<br/>直到如同江河，<br/>湧流到永遠。<br/>',NULL,8350,8350);
INSERT INTO stanza VALUES('C226','2','主的能力之靈，<br/>降到我身上，<br/>猶如外衣遮身，<br/>作我的力量；<br/>在祂裡面受浸，<br/>就將祂穿上，<br/>為著工作裝備，<br/>使我人剛強。<br/>',NULL,8351,8351);
INSERT INTO stanza VALUES('C226','3','主的生命之靈，<br/>猶如同空氣，<br/>作了生命實際，<br/>呼吸到我裡；<br/>主的能力之靈，<br/>乃像似大風，<br/>從上用力而吹，<br/>使我能行動。<br/>',NULL,8352,8352);
INSERT INTO stanza VALUES('C226','4','向著祂的門徒，<br/>復活主吹氣，<br/>將祂生命之靈，<br/>吹到他們裡；<br/>在五旬節時候，<br/>升天主澆下<br/>祂的能力之靈，<br/>如同大風颳。<br/>',NULL,8353,8353);
INSERT INTO stanza VALUES('C226','5','生命之靈乃是<br/>作裡面生命，<br/>能力之靈乃是<br/>為著這生命；<br/>如同風吹帶來<br/>新鮮的空氣，<br/>能力之靈帶來<br/>生命給人吸。<br/>',NULL,8354,8354);
INSERT INTO stanza VALUES('C226','6','並非二位分開、<br/>不同的聖靈，<br/>乃是一位聖靈<br/>不同的功能；<br/>在內充滿了神，<br/>在外穿上神，<br/>使我與神相調，<br/>永遠不再分。<br/>',NULL,8355,8355);
INSERT INTO stanza VALUES('C226','7','主，用生命之靈，<br/>充滿我裡面，<br/>使我生命長大，<br/>如同你完全；<br/>在外給我穿上<br/>能力的聖靈，<br/>使我有力工作，<br/>完成你使命。<br/>',NULL,8356,8356);
INSERT INTO stanza VALUES('C227','1','後是膏油先是血，<br/>要得滋潤先得潔；<br/>若非經過各各他，<br/>必不能到五旬節。<br/>我們若未蒙洗淨，<br/>能力必不從上傾；<br/>我們若要作見證，<br/>必須釘死己生命。<br/>',NULL,8357,8357);
INSERT INTO stanza VALUES('C227','chorus','因此求主藉十字架，<br/>治死我的魂生命；<br/>使我願出重大代價，<br/>來滿受主的聖靈。<br/>',NULL,8358,8358);
INSERT INTO stanza VALUES('C227','2','先是用杖擊石磐，<br/>後來活水纔溢漫；<br/>死亡若未作過工，<br/>聖靈必定不充滿。<br/>我們若真同主死，<br/>願意萬有都損失，<br/>主的能力要降臨，<br/>使用我們救亡世。<br/>',NULL,8359,8359);
INSERT INTO stanza VALUES('C227','3','先是祭壇後是火，<br/>若沒喪失就沒果；<br/>若非所有先奉獻，<br/>必定不能登寶座。<br/>我們若真肯犧牲，<br/>捨棄萬事降服神，<br/>我們必定得能力，<br/>因主信託順從人。<br/>',NULL,8360,8360);
INSERT INTO stanza VALUES('C227','4','先是豫備瓶子空，<br/>後是膏油盛其中；<br/>先是山谷挖成溝，<br/>後來活水纔深泓；<br/>先是經過約但河，<br/>後是靈感加倍多；<br/>先受死亡的浸洗，<br/>後得榮耀的聖鴿。<br/>',NULL,8361,8361);
INSERT INTO stanza VALUES('C227','5','當你舉目望禾田，<br/>金穀豐盈你稱羨；<br/>當念果實未生時，<br/>就有麥種死在先。<br/>若要生命的子粒，<br/>須有死亡的經歷；<br/>凡人未到髑髏地，<br/>就無聖靈的能力。<br/>',NULL,8362,8362);
INSERT INTO stanza VALUES('C227','6','既是這樣，求我主，<br/>使我忠誠走窄路，<br/>除去雄心和大志，<br/>只願順服並受苦；<br/>更大能力我不取，<br/>更深的死我所需；<br/>但願加略的意義，<br/>完全成功在我軀。<br/>',NULL,8363,8363);
INSERT INTO stanza VALUES('C228','1','求主寶血潔淨我，<br/>洗盡所有罪過，<br/>將你聖潔的膏油，<br/>重新為我塗抹。<br/>我認自己的生活，<br/>真是失敗、軟弱，<br/>我望充滿你的靈，<br/>完全為你而活。<br/>',NULL,8364,8364);
INSERT INTO stanza VALUES('C228','chorus','哦，求主救我脫離<br/>這個可憐的自己！<br/>求主使我從今後，<br/>完全充滿了你。<br/>',NULL,8365,8365);
INSERT INTO stanza VALUES('C228','2','我心何等的乾旱，<br/>常為軟弱悲歎；<br/>我是何等的盼望，<br/>能被聖靈充滿。<br/>求主讓我今隱藏<br/>在你擊傷石磐；<br/>求主今聽我呼求，<br/>讓你活水氾濫。<br/>',NULL,8366,8366);
INSERT INTO stanza VALUES('C228','3','我心何等的冷淡，<br/>順服何等遲慢；<br/>願主聖靈充滿我，<br/>使我不再背叛。<br/>我今躺臥在祭壇，<br/>不敢稍為動彈；<br/>求主烈火從天降，<br/>把我所有燒乾。<br/>',NULL,8367,8367);
INSERT INTO stanza VALUES('C228','4','求主十架在我身，<br/>天天作工更深，<br/>把我度量擴充大，<br/>使我化為灰塵；<br/>好叫聖靈充滿我，<br/>天天比前更多，<br/>你的活水到處流，<br/>解除眾人乾渴。<br/>',NULL,8368,8368);
INSERT INTO stanza VALUES('C229','1','我今在基督裡面，<br/>脫離了亞當界限；<br/>凡舊事都變新鮮，<br/>屬地變為屬天！<br/>讚美主，在此得享恩典，<br/>飽嘗生命與平安！<br/>讚美主，我今在主裡面！<br/>',NULL,8369,8369);
INSERT INTO stanza VALUES('C230','1','我真歡樂，<br/>因為天上父神，<br/>在祂話中明說祂愛世人；<br/>聖經所載奇妙之事甚多，<br/>其最甜者，<br/>就是耶穌愛我。<br/>',NULL,8370,8370);
INSERT INTO stanza VALUES('C230','chorus','我真歡樂，因耶穌愛我！<br/>耶穌愛我，耶穌愛我；<br/>我真歡樂，因耶穌愛我！<br/>耶穌竟然愛我！<br/>',NULL,8371,8371);
INSERT INTO stanza VALUES('C230','2','我雖忘祂，<br/>一直流蕩遠離，<br/>祂仍愛我，<br/>無論流蕩何地；<br/>祂來尋我，<br/>直到將我尋著，<br/>並且帶回，<br/>因為耶穌愛我。<br/>',NULL,8372,8372);
INSERT INTO stanza VALUES('C230','3','耶穌愛我，<br/>我也要愛耶穌；<br/>愛叫祂來將我靈魂救贖，<br/>愛叫祂來受死擔我罪過，<br/>因此我就確信耶穌愛我。<br/>',NULL,8373,8373);
INSERT INTO stanza VALUES('C230','4','這愛奇妙，<br/>雖然我不會說，<br/>我卻知道，<br/>並且滿有把握！<br/>在我靈中聖靈蓋上印戳，<br/>不斷向我印證耶穌愛我。<br/>',NULL,8374,8374);
INSERT INTO stanza VALUES('C230','5','因有此證，<br/>我靈充滿安息，<br/>因有主話，<br/>我心不再懷疑。<br/>撒但驚慌，<br/>離我遠遠逃躲，<br/>當我告訴他說，<br/>耶穌愛我。<br/>',NULL,8375,8375);
INSERT INTO stanza VALUES('C230','6','等進榮耀親眼看見我王，<br/>若有詩歌是我口舌愛唱，<br/>那就必是我所永要唱說：『何等奇妙之事，<br/>耶穌愛我！』<br/>',NULL,8376,8376);
INSERT INTO stanza VALUES('C231','1','主愛新鮮又甘甜，<br/>我要引聲頌揚：<br/>主既為我受苦難，<br/>又來住我心房；<br/>賜我生命與平安，<br/>扶持、照護無間；<br/>主愛越久越新鮮，<br/>主愛越久越甜。<br/>',NULL,8377,8377);
INSERT INTO stanza VALUES('C231','chorus','主的愛越久越甜，<br/>主的愛越久越甜；<br/>甜過美酒甘蜜，<br/>我要頌揚不已，<br/>主的愛越久越甜。<br/>',NULL,8378,8378);
INSERT INTO stanza VALUES('C231','2','主愛長闊又高深，<br/>我要高聲頌揚：<br/>主比親者還要親，<br/>永不離我身旁；<br/>待我情深如密友，<br/>與我心心相印；<br/>主愛越久越豐厚，<br/>主愛越久越深。<br/>',NULL,8379,8379);
INSERT INTO stanza VALUES('C231','chorus','主的愛越久越深，<br/>主的愛越久越深；<br/>深逾大海汪洋，<br/>我要時時頌揚，<br/>主的愛越久越深。<br/>',NULL,8380,8380);
INSERT INTO stanza VALUES('C231','3','主愛溫柔又堅剛，<br/>我要永遠頌揚：<br/>主比強者還要強，<br/>主愛也是這樣；<br/>雖然天地會改遷，<br/>雖然海枯石爛；<br/>主愛至終不消減，<br/>主愛歷久不變。<br/>',NULL,8381,8381);
INSERT INTO stanza VALUES('C231','chorus','主的愛歷久不變，<br/>主的愛歷久不變；<br/>堅定遠勝日月，<br/>我要頌揚不絕。<br/>主的愛歷久不變。<br/>',NULL,8382,8382);
INSERT INTO stanza VALUES('C232','1','永遠的愛已愛我，<br/>這愛藉恩我賞識；<br/>聖靈從上來吹著，<br/>為要如此來指示。<br/>哦，這豐滿的平安！<br/>哦，這神聖的歡樂！<br/>在這不息愛裡面，<br/>我是屬祂，祂屬我。<br/>',NULL,8383,8383);
INSERT INTO stanza VALUES('C232','2','頭上之天何蔚藍，<br/>四周之地也青綠；<br/>有一景色更鮮豔，<br/>無主之目從未睹：<br/>鳥鳴變為更音樂，<br/>花美使我更快活，<br/>自從我心能領略：<br/>我是屬祂，祂屬我。<br/>',NULL,8384,8384);
INSERT INTO stanza VALUES('C232','3','有事曾使我驚恐，<br/>今不再擾我安息；<br/>靠在永久膀臂中，<br/>枕在愛的胸懷裡。<br/>哦，願永遠臥於此，<br/>憂疑、自己，全逃脫，<br/>當祂柔聲的指示：<br/>我是屬祂，祂屬我。<br/>',NULL,8385,8385);
INSERT INTO stanza VALUES('C232','4','我是永遠只屬祂，<br/>誰能使祂與我分？<br/>祂在我心來安家，<br/>有福、安息滿我心。<br/>天地可以都廢去，<br/>亮光也可全衰落，<br/>但主與我永同居，<br/>我是屬祂，祂屬我。<br/>',NULL,8386,8386);
INSERT INTO stanza VALUES('C233','1','神將我罪丟在背後，<br/>不再記念，不再追究；<br/>神將我罪踏在腳下，<br/>不再看見，不再鑒察。<br/>',NULL,8387,8387);
INSERT INTO stanza VALUES('C233','chorus','我的過犯神全赦免，<br/>好似厚雲完全消散；<br/>我的罪惡神都塗抹，<br/>猶如薄雲盡都滅沒。<br/>',NULL,8388,8388);
INSERT INTO stanza VALUES('C233','2','神將我罪投於深海，<br/>如石下沉全被淹埋；<br/>神叫我罪離開我身，<br/>如東離西同樣遠甚。<br/>',NULL,8389,8389);
INSERT INTO stanza VALUES('C234','1','救主流血所成救恩，<br/>我是何人竟也有分？<br/>罪是我犯，死歸祂受，<br/>祂替我死，為將我救！<br/>驚人之愛，何竟如此？<br/>我主我神為我受死！<br/>驚人之愛，何竟如此？<br/>我主我神為我受死！<br/>',NULL,8390,8390);
INSERT INTO stanza VALUES('C234','2','不能死者，竟然受死！<br/>全是奧祕，誰能盡知？<br/>神聖之愛，高深長闊，<br/>最高天使也難測度！<br/>所有天使不必臆猜，<br/>全是憐憫，當得敬拜！<br/>所有天使不必臆猜，<br/>全是憐憫，當得敬拜！<br/>',NULL,8391,8391);
INSERT INTO stanza VALUES('C234','3','離開天上父的寶座，<br/>降世為人，恩何廣闊；<br/>虛己、捨身，<br/>流血、贖罪，<br/>為救亞當無望族類；<br/>全是憐憫，無量、白給，<br/>竟然臨及我這罪魁！<br/>全是憐憫，無量、白給，<br/>竟然臨及我這罪魁！<br/>',NULL,8392,8392);
INSERT INTO stanza VALUES('C234','4','天性黑暗，邪惡滿心，<br/>我靈久為罪惡監禁；<br/>你眼垂顧，帶來恩光，<br/>我立甦醒，囚牢明亮，<br/>鎖鍊盡脫，全人釋放，<br/>起來隨主，心中歡暢。<br/>鎖鍊盡脫，全人釋放，<br/>起來隨主，心中歡暢。<br/>',NULL,8393,8393);
INSERT INTO stanza VALUES('C234','5','不再定罪，尚何懼憂？<br/>主和一切盡歸我有！<br/>活在元首基督裡面，<br/>神聖之義將我遮掩；<br/>坦然來到施恩座前，<br/>有主基督作我冠冕。<br/>坦然來到施恩座前，<br/>有主基督作我冠冕。<br/>',NULL,8394,8394);
INSERT INTO stanza VALUES('C235','1','我為甚麼憂懼疑惑？<br/>神豈未曾將我罪過<br/>歸祂兒子身上？<br/>主所為我還清的債，<br/>公義的神能否再來<br/>要我重新清償？<br/>',NULL,8395,8395);
INSERT INTO stanza VALUES('C235','2','你的救贖永遠完全，<br/>你已還清每一文錢－我們所有罪戾；<br/>神的忿怒不能威脅，<br/>因我已經灑上寶血，<br/>靠恩已經稱義。<br/>',NULL,8396,8396);
INSERT INTO stanza VALUES('C235','3','你既為我領得赦免，<br/>你既給我白白恩典－罪債一起清算；<br/>神就不會兩面討償：<br/>先在我的中保身上…<br/>後又要我歸還。<br/>',NULL,8397,8397);
INSERT INTO stanza VALUES('C235','4','所以我心，你當安息，<br/>你的救主所有功績，<br/>已使你得開釋；<br/>當信祂的有效寶血，<br/>不怕神再將你棄絕，<br/>因主已為你死。<br/>',NULL,8398,8398);
INSERT INTO stanza VALUES('C236','1','『不再定罪！』<br/>何等希奇！<br/>我魂，應當歡喜！<br/>你罪已經都歸耶穌，<br/>祂死使你得甦。<br/>',NULL,8399,8399);
INSERT INTO stanza VALUES('C236','2','寶血為我永遠在天，<br/>對神說出美言；<br/>主看聖徒如同奇珍，<br/>天天照顧惟殷。<br/>',NULL,8400,8400);
INSERT INTO stanza VALUES('C236','3','『不再定罪！』<br/>我的魂哪，<br/>這是神說的話；<br/>你在基督復活主裡，<br/>已是完全美麗。<br/>',NULL,8401,8401);
INSERT INTO stanza VALUES('C236','4','神阿，教我注目仰望<br/>救主基督，我王；<br/>我纔會愛你的心情，<br/>纔會榮耀祂名。<br/>',NULL,8402,8402);
INSERT INTO stanza VALUES('C237','1','神的基督是我的義，<br/>我的美麗，我的錦衣，<br/>在寶座前服此盛裝，<br/>我能抬頭歡樂歌唱。<br/>',NULL,8403,8403);
INSERT INTO stanza VALUES('C237','2','主阿，我信你的寶血，<br/>已將我罪全都解決，<br/>為我灑在神施恩座，<br/>永遠為我向神求赦。<br/>',NULL,8404,8404);
INSERT INTO stanza VALUES('C237','3','藉你救贖，我已脫去<br/>我罪、我過、<br/>我恥、我懼；<br/>審判大日我敢站立，<br/>誰能控告你所稱義？<br/>',NULL,8405,8405);
INSERT INTO stanza VALUES('C237','4','亞伯拉罕就是如此，<br/>蒙贖聖徒也都一式，<br/>宣佈你為罪人救星，<br/>他們所誇只在你名。<br/>',NULL,8406,8406);
INSERT INTO stanza VALUES('C237','5','這件白衣永遠不變，<br/>盡管舊造沉沒多年；<br/>時代不能改其美豔，<br/>牠的榮美永遠新鮮。<br/>',NULL,8407,8407);
INSERT INTO stanza VALUES('C237','6','直到天上見你榮耀，<br/>我們仍要以你自驕：<br/>我的美麗、我的錦衣，<br/>我主耶穌是我的義。<br/>',NULL,8408,8408);
INSERT INTO stanza VALUES('C238','1','我的所有希望根基，<br/>並不少於基督我義；<br/>最好的義也不敢倚，<br/>只敢倚靠祂的自己。<br/>',NULL,8409,8409);
INSERT INTO stanza VALUES('C238','chorus','基督磐石，我所穩踏，<br/>其他地位都是流沙！<br/>其他地位都是流沙！<br/>',NULL,8410,8410);
INSERT INTO stanza VALUES('C238','2','即有黑雲掩祂愛臉，<br/>祂心不變，祂恩不移；<br/>每次風浪雖欲漫淹，<br/>信心的錨拋牢幔裡。<br/>',NULL,8411,8411);
INSERT INTO stanza VALUES('C238','3','祂血、祂約何等可靠，<br/>我名已經刻在祂手；<br/>四圍雖然都能傾倒，<br/>祂仍存在永不棄守。<br/>',NULL,8412,8412);
INSERT INTO stanza VALUES('C238','4','當祂再來，號筒吹響，<br/>那時我在祂內出現；<br/>只穿著祂作我義裳，<br/>無可指責被獻座前。<br/>',NULL,8413,8413);
INSERT INTO stanza VALUES('C239','1','神將我罪歸耶穌，<br/>神的聖潔羔羊；<br/>使祂替我受咒詛，<br/>將我全人釋放。<br/>神將我愆歸耶穌，<br/>神的無疵羔羊；<br/>使祂替我受痛苦，<br/>將我罪債清償。<br/>',NULL,8414,8414);
INSERT INTO stanza VALUES('C239','2','我的疾病歸耶穌，<br/>為我祂受鞭傷；<br/>我的軟弱祂背負，<br/>我得醫治、健康。<br/>我的憂患歸耶穌，<br/>為我祂全擔當；<br/>我的愁苦祂消除，<br/>我得平安、歡暢。<br/>',NULL,8415,8415);
INSERT INTO stanza VALUES('C239','3','我今安息於耶穌，<br/>祂是我的義皇；<br/>祂死已使神滿足，<br/>祂血洗我天良。<br/>我今所靠惟耶穌，<br/>祂是我的力量；<br/>祂活彰顯神豐富，<br/>祂生使我剛強。<br/>',NULL,8416,8416);
INSERT INTO stanza VALUES('C239','4','我將我心歸耶穌，<br/>惟願祂來為王，<br/>作我生命，為我主，<br/>永遠居我心房。<br/>我願我能像耶穌，<br/>活出祂的模樣；<br/>在我態度和步武，<br/>永遠將祂顯揚。<br/>',NULL,8417,8417);
INSERT INTO stanza VALUES('C240','1','『坦然無懼來到神前，』<br/>這真是從何說起！<br/>一個罪人因著恩典，<br/>竟可不再作仇敵！<br/>',NULL,8418,8418);
INSERT INTO stanza VALUES('C240','2','我性、我行，都遠離神！<br/>哎喲，離神何等遠！<br/>現今因我信血受恩，<br/>不再兩下隔天淵。<br/>',NULL,8419,8419);
INSERT INTO stanza VALUES('C240','3','我極近神，近到如此，<br/>已經不能再相近；<br/>我因藉著祂的兒子，<br/>就得像子那麼親。<br/>',NULL,8420,8420);
INSERT INTO stanza VALUES('C240','4','神極愛我，愛到如此，<br/>已經不能再珍愛；<br/>祂是如何愛祂兒子，<br/>照樣愛我不稍改。<br/>',NULL,8421,8421);
INSERT INTO stanza VALUES('C240','5','我既得著這樣的神，<br/>我心為何仍畏避？<br/>祂之於我一往情深，<br/>祂對我說：『我屬你！』<br/>',NULL,8422,8422);
INSERT INTO stanza VALUES('C241','1','我生命有何等<br/>奇妙的大改變，<br/>自基督來住在我心；<br/>神榮耀的光輝，<br/>照耀在我魂間，<br/>自基督來住在我心。<br/>',NULL,8423,8423);
INSERT INTO stanza VALUES('C241','chorus','自基督來住在我心，<br/>自基督來住在我心；<br/>喜樂潮溢我魂，<br/>如海濤之滾滾，<br/>自基督來住在我心。<br/>',NULL,8424,8424);
INSERT INTO stanza VALUES('C241','2','我罪惡的捆綁，<br/>從裡外全脫落，<br/>自基督來住在我心；<br/>我肉體的情慾，<br/>也不能再迷惑，<br/>自基督來住在我心。<br/>',NULL,8425,8425);
INSERT INTO stanza VALUES('C241','3','這世界的福樂，<br/>既變色，又失味，<br/>自基督來住在我心；<br/>我今生的憂慮，<br/>也不能再纏累，<br/>自基督來住在我心。<br/>',NULL,8426,8426);
INSERT INTO stanza VALUES('C241','4','我流蕩已止息，<br/>不再感人生空，<br/>自基督來住在我心；<br/>主甜美的安息，<br/>時滿足我情衷，<br/>自基督來住在我心。<br/>',NULL,8427,8427);
INSERT INTO stanza VALUES('C241','5','往日事都已過，<br/>永不再戀舊途，<br/>自基督來住在我心；<br/>那有福的盼望，<br/>吸引我奔義路，<br/>自基督來住在我心。<br/>',NULL,8428,8428);
INSERT INTO stanza VALUES('C242','1','喜樂滿我心！<br/>滿我心！滿我心！<br/>喜樂滿我心！<br/>主將我石心，<br/>換成了肉心；<br/>聖靈來更新，<br/>使我成為新人：<br/>喜樂滿我心！<br/>滿我心！滿我心！<br/>',NULL,8429,8429);
INSERT INTO stanza VALUES('C242','2','聖靈充滿我！<br/>充滿我！充滿我！<br/>聖靈充滿我！<br/>除去我罪過，<br/>消滅我軟弱，<br/>使我結義果，<br/>並過聖潔生活：<br/>聖靈充滿我！<br/>充滿我！充滿我！<br/>',NULL,8430,8430);
INSERT INTO stanza VALUES('C243','1','我知何時<br/>我的罪擔全脫落：<br/>多年晝夜將罪擔苦背著，<br/>等我相信主的話，<br/>按祂所說接受祂，<br/>霎時間，<br/>我的罪擔全脫落！<br/>',NULL,8431,8431);
INSERT INTO stanza VALUES('C243','chorus','全脫落！全脫落！<br/>我今快樂，<br/>因我罪擔全脫落；<br/>全脫落！全脫落！<br/>我今快樂，<br/>因我罪擔全脫落。<br/>',NULL,8432,8432);
INSERT INTO stanza VALUES('C243','2','我知何處<br/>我的罪擔全脫落：<br/>當我晝夜怕罪擔不能脫，<br/>聖靈示我脫罪法，<br/>帶著罪擔就十架；<br/>一到彼，<br/>我的罪擔全脫落。<br/>',NULL,8433,8433);
INSERT INTO stanza VALUES('C243','3','我知何故<br/>我的罪擔全脫落：<br/>罪擔多年曾晝夜纏累我，<br/>等我來到恩座前，<br/>主的榮顏僅一顯，<br/>就因此，<br/>我的罪擔全脫落。<br/>',NULL,8434,8434);
INSERT INTO stanza VALUES('C243','4','我今歌唱，<br/>因我罪擔全脫落，<br/>心裡晝夜湧美辭、<br/>頌不輟；<br/>我今活著為我主，<br/>日日高唱樂歡呼－阿利路！<br/>我的罪擔全脫落。<br/>',NULL,8435,8435);
INSERT INTO stanza VALUES('C244','1','我因歸耶穌，<br/>全人得著釋放；<br/>耶穌我救主，<br/>今在我心作王；<br/>聖靈充滿我，<br/>使我終日歡唱；<br/>主耶穌已把我釋放！<br/>',NULL,8436,8436);
INSERT INTO stanza VALUES('C244','chorus','釋放！釋放！榮耀釋放！<br/>我不再被罪惡捆綁；<br/>寶血洗淨我，<br/>全人明亮、清爽；<br/>主耶穌已把我釋放！<br/>',NULL,8437,8437);
INSERT INTO stanza VALUES('C244','2','罪惡失權勢，<br/>情慾不能羈絆，<br/>今生的憂慮<br/>也難再將我纏，<br/>屬地的捆索<br/>也都已被斬斷；<br/>主耶穌已把我釋放！<br/>',NULL,8438,8438);
INSERT INTO stanza VALUES('C244','3','救主已為我<br/>衝破世界重圍，<br/>霸佔的魔鬼<br/>祂也替我擊退；<br/>恩光今照我，<br/>榮耀何其煌輝！<br/>主耶穌已把我釋放！<br/>',NULL,8439,8439);
INSERT INTO stanza VALUES('C245','1','前在罪中為罪奴僕，<br/>受盡罪中痛苦；<br/>罪作我主，將我制伏，<br/>又將我捆縛；<br/>我雖掙扎，不能逃出，<br/>時常歎息、喊苦；<br/>從未知道基督釋放罪奴。<br/>',NULL,8440,8440);
INSERT INTO stanza VALUES('C245','chorus','我今已蒙主恩湛，<br/>脫離了罪惡霸權，<br/>暢飲於生命活泉，<br/>飽嘗救恩盛筵；<br/>阿利路，<br/>何等豐富、甘甜，<br/>帶來喜樂和頌讚！<br/>阿利路，<br/>我今已蒙恩湛！<br/>',NULL,8441,8441);
INSERT INTO stanza VALUES('C246','1','罪惡的鎖鍊，<br/>曾使我難當，<br/>我如同囚奴，掙扎枉然；<br/>但我今得著奇妙的釋放，<br/>就是主耶穌打碎鎖鍊。<br/>',NULL,8442,8442);
INSERT INTO stanza VALUES('C246','chorus','榮耀的釋放！<br/>奇妙的釋放！<br/>主耶穌是我榮耀救主。<br/>我今已脫離罪惡的捆綁，<br/>從今到永遠不再痛苦。<br/>',NULL,8443,8443);
INSERT INTO stanza VALUES('C246','2','脫離了肉體、<br/>邪情和私慾，<br/>脫離了嫉妒、<br/>忌恨、爭競，<br/>脫離了世界、<br/>虛榮並美譽，<br/>脫離了一切無謂人生。<br/>',NULL,8444,8444);
INSERT INTO stanza VALUES('C246','3','脫離了金錢<br/>閃耀的吸力，<br/>脫離了剛硬、<br/>雄心、己意，<br/>脫離了律法字句的絆羈；<br/>希奇的釋放，<br/>哦，何希奇！<br/>',NULL,8445,8445);
INSERT INTO stanza VALUES('C247','1','驚人恩典！何等甘甜，<br/>來救無賴如我！<br/>前曾失落，今被尋見！<br/>前盲，今不摸索！<br/>',NULL,8446,8446);
INSERT INTO stanza VALUES('C247','2','恩典教導我心懼怕，<br/>又將懼怕除掉；<br/>恩典在我初信剎那，<br/>顯為何等可寶。<br/>',NULL,8447,8447);
INSERT INTO stanza VALUES('C247','3','主已應許向我施恩，<br/>祂話就是保證；<br/>祂要作我盾牌、永分，<br/>帶我經過此生。<br/>',NULL,8448,8448);
INSERT INTO stanza VALUES('C247','4','當我見主萬年之後，<br/>仍像太陽照耀，<br/>比我開始讚美時候，<br/>讚美仍不減少。<br/>',NULL,8449,8449);
INSERT INTO stanza VALUES('C248','1','恩典代罪而興，<br/>在我靈中執政，<br/>使我脫離罪的權能，<br/>脫離敗壞天性。<br/>',NULL,8450,8450);
INSERT INTO stanza VALUES('C248','chorus','恩典彀我用！<br/>永不感力窮；<br/>基督活在我靈中，<br/>使我受恩重重。<br/>',NULL,8451,8451);
INSERT INTO stanza VALUES('C248','2','恩典使我腳步<br/>行在屬天路途，<br/>祂的恩典，應時、豐富，<br/>從未將我遲誤。<br/>',NULL,8452,8452);
INSERT INTO stanza VALUES('C248','3','何能大於恩典！<br/>祂是神來人間，<br/>祂是神在肉身顯現，<br/>是神在我裡面。<br/>',NULL,8453,8453);
INSERT INTO stanza VALUES('C248','chorus','我成何等人！<br/>是因蒙神恩；<br/>神恩今顯在我身，<br/>作我神人永分。<br/>',NULL,8454,8454);
INSERT INTO stanza VALUES('C249','1','有日銀鍊將要折斷，<br/>我就不再如此歌唱；<br/>但我醒來何等喜歡，<br/>竟然得以面見我王。<br/>',NULL,8455,8455);
INSERT INTO stanza VALUES('C249','chorus','我要看見祂面對面，<br/>我要述說救我恩典；<br/>我要看見祂面對面，<br/>我要述說救我恩典。<br/>',NULL,8456,8456);
INSERT INTO stanza VALUES('C249','2','有日地上帳棚傾覆，<br/>我也不知何日何載；<br/>但我確知有個去處，<br/>使我能以與主同在。<br/>',NULL,8457,8457);
INSERT INTO stanza VALUES('C249','3','或者有日救主再臨，<br/>那時工作即將完畢；<br/>得主稱許『忠心僕人，』<br/>我要進入祂的安息。<br/>',NULL,8458,8458);
INSERT INTO stanza VALUES('C249','4','有日；所以我要準備，<br/>把燈剔亮，儆醒守待；<br/>那日我得與主相會，<br/>永遠享受祂的同在。<br/>',NULL,8459,8459);
INSERT INTO stanza VALUES('C250','1','來阿，你這萬福泉源！<br/>調整我心來歌唱；<br/>憐憫江河湧流不斷，<br/>召我高聲來頌揚。<br/>我本外人離神流浪，<br/>基督親來尋找我；<br/>因要救我脫離死亡，<br/>祂竟為我被釘戳。<br/>',NULL,8460,8460);
INSERT INTO stanza VALUES('C250','2','我今天天被你激勵，<br/>對你恩典來負債；<br/>我主，讓此恩典維繫<br/>我這流浪的心懷。<br/>我認我是趨向流浪，<br/>趨向離開愛的神；<br/>求你用你靈的力量，<br/>將我蕩心來吸引。<br/>',NULL,8461,8461);
INSERT INTO stanza VALUES('C250','3','我已得著你的救恩，<br/>脫離罪惡和死亡；<br/>但願能作脫俗的人，<br/>顯出神子的景況。<br/>我今建立以便以謝，<br/>因你一直賜幫助；<br/>因你喜悅，我望永得<br/>你的帶領和眷顧。<br/>',NULL,8462,8462);
INSERT INTO stanza VALUES('C251','1','一切我所有，<br/>無非是接受；<br/>全是恩所賜，<br/>在我信之後；<br/>所以不自誇，也不自尊，<br/>我是一個罪人蒙主恩！<br/>',NULL,8463,8463);
INSERT INTO stanza VALUES('C251','chorus','我是個罪人蒙主恩！<br/>我是個罪人蒙主恩！<br/>這是我身分，<br/>榮耀歸給神，<br/>我是個罪人蒙主恩！<br/>',NULL,8464,8464);
INSERT INTO stanza VALUES('C251','2','從前我愚昧，<br/>罪惡轄我心，<br/>使我的腳步完全遠離神；<br/>今被主尋回，能不歡欣？<br/>現今是個罪人蒙主恩！<br/>',NULL,8465,8465);
INSERT INTO stanza VALUES('C251','3','流淚有何用，<br/>功行有何效？<br/>若非神憐憫，<br/>滅亡怎能逃？<br/>前我因有罪，不敢近神，<br/>現今是個罪人蒙主恩！<br/>',NULL,8466,8466);
INSERT INTO stanza VALUES('C251','4','我愛我救主，<br/>心中樂歡騰，<br/>我這蒙恩人不能不說明；<br/>讓我再說明－用盡聲音－我是一個罪人蒙主恩！<br/>',NULL,8467,8467);
INSERT INTO stanza VALUES('C252','1','前在埃及為罪奴僕，<br/>不知何為平安，<br/>良心常有罪的重負，<br/>晝夜無安息；<br/>欲求自由，少燒磚土，<br/>反而增加負擔，<br/>可憐，從未聽見<br/>榮美之地。<br/>',NULL,8468,8468);
INSERT INTO stanza VALUES('C252','chorus','今我登巍巍高山，<br/>在光天化日之中，<br/>今我飲滾滾活泉，<br/>長年湧流無終，<br/>今我得豐富，地滿乳蜜，<br/>路滴脂油，恩重重，<br/>樂哉！今我居榮美之地。<br/>',NULL,8469,8469);
INSERT INTO stanza VALUES('C252','2','幸得神賜逾越羔羊，<br/>因血得著救贖，<br/>經過受浸，進入野疆，<br/>完全脫埃及，<br/>時有試探，時有力量，<br/>常走彎曲道路，<br/>沒有信心去進榮美之地。<br/>',NULL,8470,8470);
INSERT INTO stanza VALUES('C252','3','我主基督將我高升，<br/>與祂同坐天上，<br/>空中權勢無不潰崩，<br/>撒但不安席，<br/>奉主名字，陰府無能，<br/>今都向我退讓，<br/>完全得勝，<br/>在於榮美之地。<br/>',NULL,8471,8471);
INSERT INTO stanza VALUES('C252','4','在此乃是無邊平安，<br/>乃是無比喜樂，<br/>不再憂愁，不覺孤單，<br/>完全是安息，<br/>愛何甘甜，交通何歡，<br/>處處都是詩歌，<br/>阿利路亞，<br/>這是榮美之地。<br/>',NULL,8472,8472);
INSERT INTO stanza VALUES('C253','1','在我心中歡奏一音樂，<br/>乃是恩主柔聲說：<br/>『我必永遠不將你棄絕，<br/>你必永遠屬於我。』<br/>',NULL,8473,8473);
INSERT INTO stanza VALUES('C253','chorus','耶穌，耶穌，耶穌！<br/>最甜美之名，<br/>滿足我的衷情，<br/>使我唱著往前行。<br/>',NULL,8474,8474);
INSERT INTO stanza VALUES('C253','2','我的人生原被罪所害，<br/>心情痛苦無和諧；<br/>等到恩主進入我心懷，<br/>心絃歡奏永不歇。<br/>',NULL,8475,8475);
INSERT INTO stanza VALUES('C253','3','我今享受祂恩與祂愛，<br/>安息在祂胸懷間，<br/>時常見祂笑臉向我開，<br/>因此歡樂又頌讚。<br/>',NULL,8476,8476);
INSERT INTO stanza VALUES('C253','4','有時雖遇苦難如火燒，<br/>苦中有祂作我伴；<br/>有時雖有重擔似難挑，<br/>重量有祂替我擔。<br/>',NULL,8477,8477);
INSERT INTO stanza VALUES('C253','5','不久祂來接我到天上，<br/>遠離今生的捆綁，<br/>那時我必變成祂形狀，<br/>並要與祂同作王。<br/>',NULL,8478,8478);
INSERT INTO stanza VALUES('C254','1','多年疲憊，<br/>未能尋到一泉源－永不乾涸的活泉；<br/>地上一切全都<br/>未能如我願－無何能使我心滿。<br/>',NULL,8479,8479);
INSERT INTO stanza VALUES('C254','chorus','我今飲於<br/>永不乾涸的活泉，<br/>我今飲於生命活水泉源；<br/>甜美、喜樂、歡暢，<br/>何其無限無量，<br/>我今飲於生命活水泉源。<br/>',NULL,8480,8480);
INSERT INTO stanza VALUES('C254','2','永遠不在<br/>罪的野地再流蕩，<br/>我已尋到活水泉；<br/>我的喜樂之杯<br/>滿溢而流淌，<br/>基督已使我心滿。<br/>',NULL,8481,8481);
INSERT INTO stanza VALUES('C254','3','在此所得<br/>滿足越過越甜美，<br/>在此得主的安息；<br/>在此所受安慰<br/>越過越加倍，<br/>在此受主的福氣。<br/>',NULL,8482,8482);
INSERT INTO stanza VALUES('C254','4','在此得到<br/>永無止境的供應，<br/>在此恩中永沐浴；<br/>向這醫治活泉，<br/>我心必全傾，<br/>直到永世不稍渝。<br/>',NULL,8483,8483);
INSERT INTO stanza VALUES('C255','1','我心中奏一甜美音樂，<br/>恩主耶穌是我歌；<br/>從無一音樂如此妙絕，<br/>使我嘗到天上樂。<br/>',NULL,8484,8484);
INSERT INTO stanza VALUES('C255','chorus','在我心中唱一甜美詩歌，<br/>唱一甜美詩歌，<br/>唱天上樂歌；<br/>在我心中唱一甜美詩歌，<br/>唱那奇妙愛之歌。<br/>',NULL,8485,8485);
INSERT INTO stanza VALUES('C255','2','奇妙愛！耶穌將我救活，<br/>使我得著救恩樂；<br/>何大恩！基督替我活著，<br/>使我歡唱恩愛歌。<br/>',NULL,8486,8486);
INSERT INTO stanza VALUES('C255','3','何光明！耶穌領我行路，<br/>步步唱著上行詩；<br/>何平安！基督與我同住，<br/>時時湧出讚美辭。<br/>',NULL,8487,8487);
INSERT INTO stanza VALUES('C255','4','何超脫！我要被提上升，<br/>聖徒必唱凱旋歌；<br/>何尊榮！我要同主執政，<br/>天使必奏同聲賀。<br/>',NULL,8488,8488);
INSERT INTO stanza VALUES('C255','5','何福氣！還要進到聖城，<br/>永飲生命的樂河；<br/>何快樂！且要享主豐盛，<br/>飽嘗生命的美果。<br/>',NULL,8489,8489);
INSERT INTO stanza VALUES('C256','1','基督使我心中喜樂，<br/>基督使我口中高歌；<br/>有祂同在，就能歡暢，<br/>有祂同在，就能歌唱！<br/>',NULL,8490,8490);
INSERT INTO stanza VALUES('C256','chorus','阿利路亞，真能歌唱！<br/>阿利路亞，真能歡暢！<br/>有祂同在，就能歡暢，<br/>有祂同在，就能歌唱！<br/>',NULL,8491,8491);
INSERT INTO stanza VALUES('C256','2','從前心身全是重擔，<br/>今日裡外都是平安；<br/>祂已赦我一切罪愆，<br/>祂已擔我一切為難。<br/>',NULL,8492,8492);
INSERT INTO stanza VALUES('C256','3','從前瞎眼，暗如夜半，<br/>今日看見，明如中天；<br/>祂已救我脫離迷途，<br/>祂今領我行走正路。<br/>',NULL,8493,8493);
INSERT INTO stanza VALUES('C256','4','從前一人寂寞、孤單，<br/>今日有祂作我同伴，<br/>天天相隨，時時相偕，<br/>處處體諒，事事體貼。<br/>',NULL,8494,8494);
INSERT INTO stanza VALUES('C256','5','祂愛甘甜，激我走路，<br/>祂恩豐滿，使我順服；<br/>祂的愛心將我拯救，<br/>祂的恩手將我保守。<br/>',NULL,8495,8495);
INSERT INTO stanza VALUES('C256','6','除祂以外，在天有誰？<br/>除祂以外，在地無歸！<br/>祂之愛我，直到萬代！<br/>我之愛祂，豈只現在？<br/>',NULL,8496,8496);
INSERT INTO stanza VALUES('C257','1','一生渴慕我能飲於<br/>一個清涼的泉源，<br/>得以解除裡面所感<br/>火燒一般的渴乾。<br/>',NULL,8497,8497);
INSERT INTO stanza VALUES('C257','chorus','阿利路亞！<br/>我已得到<br/>我心久所渴慕者！<br/>基督滿足我的願望，<br/>藉祂生命救了我。<br/>',NULL,8498,8498);
INSERT INTO stanza VALUES('C257','2','前喫豆莢勉以充飢，<br/>直到力量幾消沒；<br/>雖然想喫較佳之物，<br/>但仍只有忍飢餓。<br/>',NULL,8499,8499);
INSERT INTO stanza VALUES('C257','3','我前貧窮，尋求豐富，<br/>使我飢餓得滿足，<br/>但我所得一切糞土，<br/>只使我求受侮辱。<br/>',NULL,8500,8500);
INSERT INTO stanza VALUES('C257','4','活水之泉湧流不息，<br/>生命的糧可白得；<br/>難言豐富，永無不足，<br/>我的救主之於我。<br/>',NULL,8501,8501);
INSERT INTO stanza VALUES('C258','1','以前我心苦楚悲傷，<br/>永生之福無望；<br/>惟有基督今為我王，<br/>我心充滿歡暢。<br/>',NULL,8502,8502);
INSERT INTO stanza VALUES('C258','chorus','今主耶穌滿足我心，<br/>並無別人如祂；<br/>歷久愛情、生命、歡欣，<br/>都由耶穌賜下。<br/>',NULL,8503,8503);
INSERT INTO stanza VALUES('C258','2','我嘗世間許多好味，<br/>乾渴仍然極深；<br/>普天之下萬般全備，<br/>仍不滿足我心。<br/>',NULL,8504,8504);
INSERT INTO stanza VALUES('C258','3','以前我心思慕祝福，<br/>並不來尋基督；<br/>我雖忽略我的救主，<br/>祂愛卻來尋吾。<br/>',NULL,8505,8505);
INSERT INTO stanza VALUES('C258','4','我曾試過破裂水池，<br/>希望痛快而喝；<br/>哎喲，水卻完全漏失，<br/>譏諷我的乾渴。<br/>',NULL,8506,8506);
INSERT INTO stanza VALUES('C258','5','祝福喪失，我心悲哀，<br/>仍未想到祂來；<br/>蒙昧心目，祂為我開，<br/>始知祂是可愛。<br/>',NULL,8507,8507);
INSERT INTO stanza VALUES('C259','1','我真不知神的奇恩<br/>為何臨到我身；<br/>我也不知不堪如我，<br/>救來有何足多。<br/>',NULL,8508,8508);
INSERT INTO stanza VALUES('C259','chorus','惟知道我所信的是誰，<br/>並且也深信祂實在是能<br/>保守我所信託祂的，<br/>都全備直到那日！<br/>',NULL,8509,8509);
INSERT INTO stanza VALUES('C259','2','我真不知救我的信<br/>如何進入我心，<br/>我也不知何以一信，<br/>便得一個新心。<br/>',NULL,8510,8510);
INSERT INTO stanza VALUES('C259','3','我真不知聖靈如何<br/>引人知道己過，<br/>並由聖經顯明耶穌，<br/>使人接祂為主。<br/>',NULL,8511,8511);
INSERT INTO stanza VALUES('C259','4','我真不知我的前途<br/>到底是甘是苦；<br/>我也不知未見主前<br/>還有甚麼試煉。<br/>',NULL,8512,8512);
INSERT INTO stanza VALUES('C259','5','我真不知何時主來，<br/>那時我是何在－到底我當經過死谷？<br/>或將空中遇主？<br/>',NULL,8513,8513);
INSERT INTO stanza VALUES('C260','1','穩固的根基，<br/>為信徒已建立，<br/>在神話語中，<br/>其穩固勝天地。<br/>你既投靠主，<br/>如投到避難所，<br/>神話就保證你<br/>永遠是穩妥。<br/>神話就保證你<br/>永遠是穩妥。<br/>',NULL,8514,8514);
INSERT INTO stanza VALUES('C260','2','主說信祂者，<br/>必永遠不滅亡；<br/>無誰從祂手，<br/>能奪去祂的羊。<br/>父比萬有大，<br/>主與父原為一；<br/>凡父賜祂的，<br/>祂一個不失遺。<br/>',NULL,8515,8515);
INSERT INTO stanza VALUES('C260','3','神所稱義者，<br/>有誰能再控告？<br/>主所替死者，<br/>有誰能再追討？<br/>神義既賜你，<br/>有誰能來除滅？<br/>主愛既屬你，<br/>有誰能來隔絕？<br/>',NULL,8516,8516);
INSERT INTO stanza VALUES('C260','4','凡是就主者，<br/>主永遠不丟棄；<br/>凡是靠主者，<br/>主都能救到底。<br/>祂是你生命，<br/>你又是祂肢體，<br/>與祂合為一，<br/>何能使再分離？<br/>',NULL,8517,8517);
INSERT INTO stanza VALUES('C260','5','當你遇試探，<br/>那惡者來迷惑，<br/>使你心疑慮，<br/>如海中起風波，<br/>抓住主的話，<br/>速拋出信心錨，<br/>堅固又牢靠，<br/>必永遠不動搖。<br/>',NULL,8518,8518);
INSERT INTO stanza VALUES('C261','1','哦來，蒙恩群眾，<br/>釋放而歡騰，<br/>同來稱謝主，<br/>歌祂恩何豐盛！<br/>祂贖你罪過，<br/>又賜你神生命。<br/>同來稱謝耶穌，<br/>同來稱謝耶穌，<br/>同來稱謝耶穌，<br/>我救主基督。<br/>',NULL,8519,8519);
INSERT INTO stanza VALUES('C261','2','哦來，蒙愛群眾，<br/>穩固不搖動，<br/>同來頌揚主，<br/>唱祂愛何深泓！<br/>祂已拯救你，<br/>又永住你心中。<br/>同來頌揚耶穌，<br/>同來頌揚耶穌，<br/>同來頌揚耶穌，<br/>我救主基督。<br/>',NULL,8520,8520);
INSERT INTO stanza VALUES('C261','3','哦來，蒙召群眾，<br/>聖潔又光榮，<br/>同來敬拜主，<br/>讚祂名何超眾！<br/>祂是萬有主，<br/>又是王至高聳。<br/>同來敬拜耶穌，<br/>同來敬拜耶穌，<br/>同來敬拜耶穌，<br/>我救主基督。<br/>',NULL,8521,8521);
INSERT INTO stanza VALUES('C262','1','今有榮光照耀我魂間，<br/>勝於星月太陽；<br/>光線清新，輝煌又燦爛，<br/>因主就是這光。<br/>',NULL,8522,8522);
INSERT INTO stanza VALUES('C262','chorus','榮耀之光！福樂之光！<br/>帶來平安喜樂滾滾浪；<br/>當主耶穌笑臉欣欣放，<br/>榮耀之光照明亮。<br/>',NULL,8523,8523);
INSERT INTO stanza VALUES('C262','2','今有音樂洋溢我魂間，<br/>頌讚我主我王；<br/>恩主在聽，且也會聽見，<br/>儘管我拙於唱。<br/>',NULL,8524,8524);
INSERT INTO stanza VALUES('C262','3','今有平安彌漫我魂間，<br/>因主在我心房；<br/>平安之鴿吟於我心坎，<br/>恩典之花開放。<br/>',NULL,8525,8525);
INSERT INTO stanza VALUES('C262','4','今有喜樂充滿我魂間，<br/>且有頌讚盼望；<br/>因主向我既已施恩典，<br/>為我又儲天賞。<br/>',NULL,8526,8526);
INSERT INTO stanza VALUES('C263','1','今日何日！我意立定，<br/>揀選耶穌作我救主！<br/>我心歡樂如火熒熒，<br/>將此歡樂到處傳述。<br/>',NULL,8527,8527);
INSERT INTO stanza VALUES('C263','chorus','快樂日！快樂日！<br/>耶穌救我，使我歡樂！<br/>贖罪寶血洗我罪惡！<br/>生命活水解我乾渴！<br/>快樂日！快樂日！<br/>耶穌救我，使我歡樂！<br/>',NULL,8528,8528);
INSERT INTO stanza VALUES('C263','2','此意一定，永不反悔，<br/>主今屬我，我也屬主；<br/>祂既吸引，我必跟隨，<br/>歡然答應祂的招呼。<br/>',NULL,8529,8529);
INSERT INTO stanza VALUES('C263','3','前我二意，今可安定，<br/>讓主作我惟一中心：<br/>注定於祂，永不別傾，<br/>有祂就有一切福分。<br/>',NULL,8530,8530);
INSERT INTO stanza VALUES('C263','4','今在主前立定此意，<br/>更願此意與日俱新，<br/>直到臨終雙目垂閉，<br/>進入永遠與祂更親。<br/>',NULL,8531,8531);
INSERT INTO stanza VALUES('C264','1','真奧祕！真奧祕！<br/>主基督與罪人合為一。<br/>或人事、或時地，<br/>不能使主與我再分離。<br/>阿利路亞！阿利路亞！<br/>榮耀的奧祕！<br/>真奧祕！真奧祕！<br/>在主裡我與神永合一。<br/>',NULL,8532,8532);
INSERT INTO stanza VALUES('C264','2','真超脫！真超脫！<br/>我已經與基督同復活；<br/>是罪惡、是鬼魔，<br/>從今後都不能再纏我；<br/>阿利路亞！阿利路亞！<br/>榮耀的超脫！<br/>真超脫！真超脫！<br/>我現今與基督同活著。<br/>',NULL,8533,8533);
INSERT INTO stanza VALUES('C265','1','有福的確據，基督屬我！<br/>豫嘗神榮耀，何等快活！<br/>蒙寶血贖回，領受恩賜；<br/>由聖靈重生，作神後嗣。<br/>',NULL,8534,8534);
INSERT INTO stanza VALUES('C265','chorus','這是我見證，是我詩歌，<br/>讚美我救主，口唱心和！<br/>這是我見證，是我詩歌，<br/>讚美我救主，終日歡樂！<br/>',NULL,8535,8535);
INSERT INTO stanza VALUES('C265','2','完全的順服，完全甘甜，<br/>被提的景象，顯在眼前；<br/>似乎有聲音，從天而來，<br/>細說主憐憫，柔述主愛。<br/>',NULL,8536,8536);
INSERT INTO stanza VALUES('C265','3','完全的順服，完全安息，<br/>與主時交通，何等福氣；<br/>儆醒且等候，仰望主來，<br/>充滿主甘甜，浸透主愛。<br/>',NULL,8537,8537);
INSERT INTO stanza VALUES('C266','1','我無技巧前來領會<br/>神的旨意、神的定規；<br/>但我只知有了一位，<br/>在祂右邊是救主。<br/>',NULL,8538,8538);
INSERT INTO stanza VALUES('C266','2','『基督已為罪人死了，』<br/>我讀話語，我信功效，<br/>因在我心我有需要：<br/>祂來作我的救主。<br/>',NULL,8539,8539);
INSERT INTO stanza VALUES('C266','3','是否沒有別的法子<br/>給神去作？我是不知；<br/>但我只能連唱美詩，<br/>因祂救我藉救主。<br/>',NULL,8540,8540);
INSERT INTO stanza VALUES('C266','4','祂竟離開榮耀天畔，<br/>竟來地上為人受難；<br/>你說奇怪，我無同感，<br/>因我已經識救主。<br/>',NULL,8541,8541);
INSERT INTO stanza VALUES('C266','5','但願祂能在我心裡，<br/>完全看見勞苦功績，<br/>使祂對祂工作滿意，<br/>如同我對我救主。<br/>',NULL,8542,8542);
INSERT INTO stanza VALUES('C266','6','讓我無論生存、死亡，<br/>得力、得慰從這寶礦；<br/>祂今活著永遠為王，<br/>卻曾死過為救主。<br/>',NULL,8543,8543);
INSERT INTO stanza VALUES('C267','1','多年過著虛妄的生活，<br/>不理我主如何被釘戳，<br/>不知祂死原是為著我，<br/>在加略山。<br/>',NULL,8544,8544);
INSERT INTO stanza VALUES('C267','chorus','廣大憐憫，白白的恩典；<br/>眾多罪愆我全得赦免，<br/>得著釋放脫去了重擔，<br/>在加略山。<br/>',NULL,8545,8545);
INSERT INTO stanza VALUES('C267','2','蒙神光照，得知我罪愆，<br/>恐懼戰兢，在律法跟前，<br/>直到我心完全的回轉，<br/>向加略山。<br/>',NULL,8546,8546);
INSERT INTO stanza VALUES('C267','3','今將一切，全都獻給主，<br/>甘心樂意作祂的奴僕，<br/>永遠不忘祂所受的苦，<br/>在加略山。<br/>',NULL,8547,8547);
INSERT INTO stanza VALUES('C267','4','哦！愛何大，<br/>計畫了救恩！<br/>哦！恩何豐，<br/>將此帶給人！<br/>哦！力何強，<br/>帶我歸向神，<br/>在加略山。<br/>',NULL,8548,8548);
INSERT INTO stanza VALUES('C268','1','平安正如水流，<br/>一路跟隨我；<br/>憂慮卻如怒濤橫湧；<br/>任何的遭遇，<br/>你已教我能說：<br/>我魂，你應安息，<br/>無所恐！<br/>',NULL,8549,8549);
INSERT INTO stanza VALUES('C268','chorus','哦，我魂，可無恐！<br/>哦，我魂，<br/>可安樂、可無恐！<br/>',NULL,8550,8550);
INSERT INTO stanza VALUES('C268','2','撒但雖來肆虐，<br/>試煉雖如火，<br/>我心應當充滿把握；<br/>因主明瞭<br/>我是何等的軟弱，<br/>祂已為我流血成工作。<br/>',NULL,8551,8551);
INSERT INTO stanza VALUES('C268','3','我罪－這是何等<br/>榮耀的思想，<br/>我罪－非局部乃攏總，<br/>全釘在祂十架，<br/>不壓我身上，<br/>我魂，你要稱頌、<br/>要稱頌！<br/>',NULL,8552,8552);
INSERT INTO stanza VALUES('C268','4','活著乃是基督，<br/>是基督執政，<br/>就是死河興起波瀾，<br/>我也沒有苦痛，<br/>因死要如生，<br/>聽祂低聲對我賜平安。<br/>',NULL,8553,8553);
INSERT INTO stanza VALUES('C268','5','哦，我主、我救主，<br/>我等你再臨，<br/>我是望你不是望墓；<br/>哦，天使的號筒！<br/>哦，主的聲音！<br/>何等的希望，永遠的福！<br/>',NULL,8554,8554);
INSERT INTO stanza VALUES('C269','1','我如困鹿切慕溪水，<br/>裡面乾渴難言；<br/>哦神，我心惟你是追，<br/>並你復甦恩典。<br/>',NULL,8555,8555);
INSERT INTO stanza VALUES('C269','2','活的神阿，你是我神，<br/>我心飢渴要你；<br/>深願全人與你相親，<br/>盡享你的自己。<br/>',NULL,8556,8556);
INSERT INTO stanza VALUES('C269','3','你是我的生命、力量，<br/>也是我的居所；<br/>你在基督給我飽嘗，<br/>在祂給我得著。<br/>',NULL,8557,8557);
INSERT INTO stanza VALUES('C269','4','你的笑臉是我拯救，<br/>我今向你仰望；<br/>你的同在是我所求，<br/>願你多多恩賞。<br/>',NULL,8558,8558);
INSERT INTO stanza VALUES('C269','5','我如困鹿切慕溪水，<br/>願你賞我所欲；<br/>哦神，除你何能施惠？<br/>惟你是我所需。<br/>',NULL,8559,8559);
INSERT INTO stanza VALUES('C270','1','我心所追求乃是神自己，<br/>不是樂與安，<br/>也不是福氣；<br/>我能出代價，<br/>達到這聖地，<br/>不是我自己，<br/>乃是祂恩力。<br/>',NULL,8560,8560);
INSERT INTO stanza VALUES('C270','2','因信而向前，<br/>要得神自己，<br/>憑愛而跟隨，<br/>永遠不他依；<br/>願主拯救我脫離我自己，<br/>直到神一切充滿在我裡。<br/>',NULL,8561,8561);
INSERT INTO stanza VALUES('C270','3','雖然這道路有時真可怕，<br/>雖然這代價常是非常大，<br/>但是神知道何者是我需，<br/>得著神的路永不能彎曲。<br/>',NULL,8562,8562);
INSERT INTO stanza VALUES('C270','4','一事我所知，<br/>祂永不會錯，<br/>一事我所作，<br/>要將祂得著；<br/>一天過一天神是我所要，<br/>至終的賞賜，<br/>神作我榮耀。<br/>',NULL,8563,8563);
INSERT INTO stanza VALUES('C271','1','全能的神，<br/>非受造的生命，<br/>聽我呼求，<br/>允我在此所請；<br/>無限榮耀，<br/>在你周身圍繞，<br/>生命賜者，<br/>求你給我所要。<br/>',NULL,8564,8564);
INSERT INTO stanza VALUES('C271','2','藉著基督所經歷的十架，<br/>藉著祂死所成功的擊殺，<br/>黑暗權勢，<br/>救我全然脫離，<br/>遷我到你愛子光明國裡。<br/>',NULL,8565,8565);
INSERT INTO stanza VALUES('C271','3','從我中心，<br/>將我絕對充滿，<br/>滿到圓周，<br/>滿達四周邊緣；<br/>在我周身，<br/>直到極邊之上，<br/>射出你的榮耀所有光芒。<br/>',NULL,8566,8566);
INSERT INTO stanza VALUES('C271','4','非造生命，<br/>你是至聖的神，<br/>生命之靈，<br/>求你今在我心，<br/>有所創作，<br/>使我顯你榮耀，<br/>並且逼我除你別無所要。<br/>',NULL,8567,8567);
INSERT INTO stanza VALUES('C271','5','感謝父神，<br/>我已得你恩賞，<br/>同著基督，<br/>今在生命作王；<br/>我已滿足，<br/>且因基督誇勝，<br/>藉祂十架，<br/>得享豐盛生命。<br/>',NULL,8568,8568);
INSERT INTO stanza VALUES('C272','1','曠野之中為著神！<br/>一叢荊棘在火焚！<br/>願我如此蒙你恩，<br/>使你榮耀顯我身。<br/>',NULL,8569,8569);
INSERT INTO stanza VALUES('C272','2','僅是平常的荊棘，<br/>神能在牠顯為奇，<br/>神能憑牠顯能力，<br/>神能藉牠行神蹟。<br/>',NULL,8570,8570);
INSERT INTO stanza VALUES('C272','3','不是用牠作燃料，<br/>乃神自己來燃燒；<br/>神在牠身無所要，<br/>僅要藉牠顯榮耀。<br/>',NULL,8571,8571);
INSERT INTO stanza VALUES('C272','4','神藉荊棘來顯現，<br/>無他只見神火焰；<br/>願我如此，藉恩典<br/>使你榮耀顯完全！<br/>',NULL,8572,8572);
INSERT INTO stanza VALUES('C273','1','神，<br/>你正在重排我的前途，<br/>你也正在拆毀我的建築，<br/>忠心事奉的人日少一日，<br/>誤會增加，<br/>清白逐漸消失。<br/>',NULL,8573,8573);
INSERT INTO stanza VALUES('C273','chorus','我眼有淚珠，<br/>看不清你臉面，<br/>好像你話語真實不如前；<br/>你使我減少，<br/>好叫你更加添，<br/>好叫你旨意比前更甘甜。<br/>',NULL,8574,8574);
INSERT INTO stanza VALUES('C273','2','我幾乎要求你停止你手，<br/>當我覺得我已無力再受；<br/>但你是神，<br/>你怎可以讓步？<br/>求你不要讓步，<br/>等我順服。<br/>',NULL,8575,8575);
INSERT INTO stanza VALUES('C273','3','如果你的旨意和你喜樂<br/>乃是在乎我負痛苦之軛，<br/>就願我的喜樂乃是在乎<br/>順服你的旨意來受痛苦。<br/>',NULL,8576,8576);
INSERT INTO stanza VALUES('C273','4','好像你的喜樂所需代價<br/>乃是需我受你阻扼倒下，<br/>所以我就歡迎你的阻扼，<br/>好叫我能使你的心喜樂。<br/>',NULL,8577,8577);
INSERT INTO stanza VALUES('C273','5','你將車輛賜與別人乘坐，<br/>你使他們從我頭上軋過；<br/>我的所有你正下手剝奪，<br/>求你留下剝奪的手給我。<br/>',NULL,8578,8578);
INSERT INTO stanza VALUES('C274','1','神聖之愛，遠超眾愛，<br/>天上之樂臨地上，<br/>竟來住我卑微胸懷，<br/>作我相信的恩賞。<br/>恩主，你是所有憐憫，<br/>你是純潔無限愛；<br/>眷顧我們，帶來救恩，<br/>進入相信的胸懷。<br/>',NULL,8579,8579);
INSERT INTO stanza VALUES('C274','2','哦主，向我吹你聖靈，<br/>吹進煩擾的心裡；<br/>使我有分你的豐盛，<br/>享受應許的安息。<br/>從我除去罪的愛好，<br/>除去一切的捆綁；<br/>使我認識生命之道，<br/>使我完全得釋放。<br/>',NULL,8580,8580);
INSERT INTO stanza VALUES('C274','3','大能的主，前來拯救，<br/>豐盛生命賜給我；<br/>願你同在直到永久，<br/>在你殿中永住著。<br/>我要時常頌讚你名，<br/>照你喜悅事奉你，<br/>不住禱告，不住頌稱，<br/>誇耀你愛永無已。<br/>',NULL,8581,8581);
INSERT INTO stanza VALUES('C274','4','求你完成你的新造，<br/>使我純潔無瑕疵；<br/>你大救恩我全享到，<br/>得以和你全相似；<br/>更新變化、榮上加榮，<br/>直到滿有你身量，<br/>直到進入榮耀之中，<br/>永遠將你愛頌揚。<br/>',NULL,8582,8582);
INSERT INTO stanza VALUES('C275','1','親愛主！寶貝主！<br/>我輕視我事物；<br/>有誰像你如此美麗？<br/>如此甘甜？如此柔細？<br/>你是人中無比，<br/>誰能與你相匹？<br/>',NULL,8583,8583);
INSERT INTO stanza VALUES('C275','2','親愛主！寶貝主！<br/>我聽見你招呼；<br/>你的聲音入我心內，<br/>我就脫離所有纏累，<br/>驕傲都歸虛無，<br/>追求都變庸俗。<br/>',NULL,8584,8584);
INSERT INTO stanza VALUES('C275','3','親愛主！寶貝主！<br/>我怎能再頑固？<br/>我將剛硬投你腳旁，<br/>領首詩歌回家去唱，<br/>歡喜作你奴僕，<br/>歡喜向你屈服。<br/>',NULL,8585,8585);
INSERT INTO stanza VALUES('C275','4','親愛主！寶貝主！<br/>我揀選你道路；<br/>一面順服，一面流淚，<br/>但我不肯改變地位，<br/>我要討你喜悅，<br/>羨慕愛的暴虐。<br/>',NULL,8586,8586);
INSERT INTO stanza VALUES('C275','5','親愛主！寶貝主！<br/>自從你去天府，<br/>我臉好像不能再笑，<br/>我天好像不能再曉，<br/>我只想你回來，<br/>我只想你同在。<br/>',NULL,8587,8587);
INSERT INTO stanza VALUES('C275','6','親愛主！寶貝主！<br/>讓我來向你訴，<br/>你是我所朝夕思慕，<br/>只有你能使我滿足，<br/>得你甚麼都有，<br/>你外無所要求。<br/>',NULL,8588,8588);
INSERT INTO stanza VALUES('C275','7','親愛主！寶貝主！<br/>我奉獻我事物；<br/>有誰像你如此美麗，<br/>如此甘甜，如此柔細？<br/>你是人中無比，<br/>誰能與你相匹？<br/>',NULL,8589,8589);
INSERT INTO stanza VALUES('C276','1','你若取去我的心愛，<br/>求以自己給我；<br/>你若仍定我受疑猜，<br/>求以自己給我。<br/>',NULL,8590,8590);
INSERT INTO stanza VALUES('C276','chorus','主耶穌，親愛救主，<br/>多以自己給我；<br/>我向你完全順服，<br/>多以自己給我。<br/>',NULL,8591,8591);
INSERT INTO stanza VALUES('C276','2','你使我的望星迷糊，<br/>求以自己給我；<br/>你許我的心緒起伏，<br/>求以自己給我。<br/>',NULL,8592,8592);
INSERT INTO stanza VALUES('C276','3','你既拆毀我所倚靠，<br/>求以自己給我，<br/>你既拒絕我的禱告，<br/>求以自己給我。<br/>',NULL,8593,8593);
INSERT INTO stanza VALUES('C276','4','我若需要仍舊忍耐，<br/>仍以自己給我；<br/>你若尚未立即再來，<br/>再加自己給我。<br/>',NULL,8594,8594);
INSERT INTO stanza VALUES('C277','1','請進，哦請進！<br/>大門現已開；<br/>這是你聲音，<br/>我能認出來。<br/>夕陽早西沉，<br/>風暴已來臨；<br/>這是你時候，<br/>哦救主，請進！<br/>',NULL,8595,8595);
INSERT INTO stanza VALUES('C277','2','唉，這個零亂<br/>淒涼的房間：<br/>家中的用具亂堆於幽暗，<br/>座椅未整理，<br/>飯桌空站著，<br/>呀，豈可如此<br/>待永世佳客！<br/>',NULL,8596,8596);
INSERT INTO stanza VALUES('C277','3','但就此歡迎；這情景慘甚<br/>就是我請你進來的原因；<br/>這黑暗混亂且即刻要求<br/>你光明同在，<br/>並整理的手。<br/>',NULL,8597,8597);
INSERT INTO stanza VALUES('C277','4','在你這佳客光顧的跟前，<br/>我不再尋求修補或改善；<br/>一切全不像，<br/>且比人更壞，<br/>使你仍等候，<br/>不能就進來。<br/>',NULL,8598,8598);
INSERT INTO stanza VALUES('C277','5','請進，非來尋，<br/>乃是使這心<br/>配作你居所，<br/>適合你留存；<br/>將黑暗、罪惡，<br/>驅逐得淨盡：<br/>請進，主耶穌，<br/>現在就請進！<br/>',NULL,8599,8599);
INSERT INTO stanza VALUES('C278','1','光中之光，照進！<br/>罪惡之夜驅盡，<br/>白日顯於內心，<br/>光中之光，照進！<br/>',NULL,8600,8600);
INSERT INTO stanza VALUES('C278','chorus','哦，超過眾光之光，<br/>請來住我心房；<br/>哦，驅散憂苦之樂，<br/>請來我心住著。<br/>',NULL,8601,8601);
INSERT INTO stanza VALUES('C278','2','樂中之樂，請進！<br/>罪惡之苦去盡，<br/>平安滿我內心，<br/>樂中之樂，請進！<br/>',NULL,8602,8602);
INSERT INTO stanza VALUES('C278','3','命中之命，傾進！<br/>罪惡之死吞盡，<br/>復甦我的內心，<br/>命中之命，傾進！<br/>',NULL,8603,8603);
INSERT INTO stanza VALUES('C278','4','愛中之愛，流進！<br/>罪惡之恨除根，<br/>更新我的內心，<br/>愛中之愛，流進！<br/>',NULL,8604,8604);
INSERT INTO stanza VALUES('C278','5','天上之天，降臨！<br/>破除雲幔遮隱，<br/>地上擾亂除盡，<br/>天上之天，降臨！<br/>',NULL,8605,8605);
INSERT INTO stanza VALUES('C278','6','我神我主，請來！<br/>安家在我心懷，<br/>賜我豐滿同在，<br/>我神我主，請來。<br/>',NULL,8606,8606);
INSERT INTO stanza VALUES('C279','1','哦主，帶著豐富請進，<br/>眷顧我這復甦之心，<br/>良心血已洗淨；<br/>將你自己向我供應，<br/>使我享受你的豐盛，<br/>因我是神所生。<br/>',NULL,8607,8607);
INSERT INTO stanza VALUES('C279','2','不讓甚麼分我心情，<br/>因我與你已經同釘，<br/>現今向神活著。<br/>我向世界和牠妖姿，<br/>並牠偶像、娛樂已死，<br/>讓你作我榮耀。<br/>',NULL,8608,8608);
INSERT INTO stanza VALUES('C279','3','不滅之渴向我惠顧，<br/>賜我無限渴望羨慕，<br/>你是我心所愛。<br/>少於你者，請勿賜給，<br/>必須你來作我恩惠；<br/>帶你所是而來！<br/>',NULL,8609,8609);
INSERT INTO stanza VALUES('C279','4','從前一切失喪於你，<br/>今後一切是你自己，<br/>你是我們永分。<br/>蒙召有分於你交通，<br/>你外不再有所愛鍾，<br/>哦來，恩上加恩！<br/>',NULL,8610,8610);
INSERT INTO stanza VALUES('C280','1','哦主，你是我的生命，<br/>也是生命供應；<br/>求在靈中眷顧我靈，<br/>使我生命豐盛。<br/>',NULL,8611,8611);
INSERT INTO stanza VALUES('C280','2','將你自己於我應用，<br/>向我吹你聖靈；<br/>使我經歷與你同釘，<br/>模成你死之形。<br/>',NULL,8612,8612);
INSERT INTO stanza VALUES('C280','3','你已勝過陰府、撒但，<br/>但仍與我相爭；<br/>願你工作在我裡面，<br/>殺死並且供應。<br/>',NULL,8613,8613);
INSERT INTO stanza VALUES('C280','4','當我天然被你治死，<br/>你就應用於我；<br/>將我埋葬，永不再世，<br/>使我同你活著。<br/>',NULL,8614,8614);
INSERT INTO stanza VALUES('C280','5','在我裡面掌權作王，<br/>征服倔強仇敵；<br/>從我顯出你的形像，<br/>活出你的自己。<br/>',NULL,8615,8615);
INSERT INTO stanza VALUES('C280','6','從我除去罪的餘燼，<br/>使我作你居所；<br/>願你榮耀浸透全人，<br/>神在我身顯著。<br/>',NULL,8616,8616);
INSERT INTO stanza VALUES('C281','1','願我愛你更深！<br/>愛你更深！<br/>哦主，聽此求懇，<br/>成全此心。<br/>我心真是切慕：<br/>愛你更深，我主，<br/>愛你更深，<br/>愛你更深！<br/>',NULL,8617,8617);
INSERT INTO stanza VALUES('C281','2','前我追求世福、<br/>貪享安樂，<br/>今只尋求基督，<br/>解我乾渴；<br/>我今惟獨切慕：<br/>愛你更深，我主，<br/>愛你更深，<br/>愛你更深！<br/>',NULL,8618,8618);
INSERT INTO stanza VALUES('C281','3','哦，讓痛苦、傷悲，<br/>將我試煉；<br/>你的使者何美！<br/>其歌何甜！<br/>我同他們唱出：<br/>愛你更深，我主，<br/>愛你更深，<br/>愛你更深！<br/>',NULL,8619,8619);
INSERT INTO stanza VALUES('C281','4','直到呼吸漸促，<br/>歌聲漸收，<br/>我心仍要發出<br/>臨別節奏，<br/>且要永遠渴慕：<br/>愛你更深，我主，<br/>愛你更深，<br/>愛你更深！<br/>',NULL,8620,8620);
INSERT INTO stanza VALUES('C282','1','如果我的道路<br/>引我去受苦，<br/>如果你是命定<br/>要我歷艱辛，<br/>就願你我從茲<br/>交通益親摯，<br/>時也刻也無間，<br/>彌久彌香甜。<br/>',NULL,8621,8621);
INSERT INTO stanza VALUES('C282','2','如果地樂消減，<br/>求你多給天；<br/>雖然心可傷痛，<br/>願靈仍讚頌；<br/>地的香甜聯結，<br/>若因你分裂，<br/>就願你我之間，<br/>聯結更香甜。<br/>',NULL,8622,8622);
INSERT INTO stanza VALUES('C282','3','這路雖然孤單，<br/>求你作我伴，<br/>用你笑容鼓舞<br/>我來盡前途；<br/>主，我靠你恩力，<br/>盼望能無己，<br/>作一潔淨器皿，<br/>流出你生命。<br/>',NULL,8623,8623);
INSERT INTO stanza VALUES('C283','1','北風阿，求速興起！<br/>南風阿，快吹來！<br/>吹在我心的園地，<br/>滿園芬芳播開。<br/>北風阿，求速興起！<br/>南風阿，快吹來！<br/>吹在我心的園地，<br/>滿園芬芳播開。<br/>',NULL,8624,8624);
INSERT INTO stanza VALUES('C283','chorus','願我的所愛到這裡來，<br/>與我永同在，<br/>嘗我純潔愛。<br/>願我的所愛到這裡來，<br/>與我永同在，<br/>嘗我純潔愛。<br/>',NULL,8625,8625);
INSERT INTO stanza VALUES('C283','2','哪噠香膏澆祂頭，<br/>秀麗髮擦祂腳；<br/>正當王坐席時候，<br/>滿屋馨香四飄。<br/>',NULL,8626,8626);
INSERT INTO stanza VALUES('C283','3','祂像林中蘋果樹，<br/>我喜歇祂柔蔭；<br/>果實甘甜又成熟，<br/>增我力、暢我心。<br/>',NULL,8627,8627);
INSERT INTO stanza VALUES('C283','4','我心所愛者，來阿，<br/>－我屬你，你屬我，<br/>－我們同往田間罷，<br/>享受各樣佳果。<br/>',NULL,8628,8628);
INSERT INTO stanza VALUES('C283','5','願我在祂的心上，<br/>銘刻如同印戳；<br/>祂愛比死更堅強，<br/>眾水不能淹沒。<br/>',NULL,8629,8629);
INSERT INTO stanza VALUES('C283','6','除你以外，在高天<br/>我還可以有誰？<br/>除你以外，在人間<br/>我也別無所歸。<br/>',NULL,8630,8630);
INSERT INTO stanza VALUES('C284','1','沒有間隔，<br/>主，沒有間隔；<br/>讓我見你榮面，<br/>引我近你身邊，<br/>然後聽你慈言；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8631,8631);
INSERT INTO stanza VALUES('C284','2','沒有間隔，<br/>主，沒有間隔；<br/>但願地上翻騰<br/>不亂你的微聲；<br/>我願向你忠誠；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8632,8632);
INSERT INTO stanza VALUES('C284','3','沒有間隔，<br/>主，沒有間隔；<br/>沒有世上罣慮，<br/>沒有屬己興趣，<br/>沒有掩飾空虛；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8633,8633);
INSERT INTO stanza VALUES('C284','4','沒有間隔，<br/>主，沒有間隔；<br/>當你親近我時，<br/>疑惑完全消失，<br/>恐懼也都停止；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8634,8634);
INSERT INTO stanza VALUES('C284','5','沒有間隔，<br/>主，沒有間隔；<br/>求你照耀輝煌，<br/>消滅一切邪光，<br/>作我無限心王；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8635,8635);
INSERT INTO stanza VALUES('C284','6','沒有間隔，<br/>主，沒有間隔；<br/>願我如此隨你，<br/>願我所見惟你，<br/>願我所歸惟你；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8636,8636);
INSERT INTO stanza VALUES('C284','7','沒有間隔，<br/>主，沒有間隔；<br/>直到我眼看見<br/>你的永光顯現，<br/>再無任何黑暗；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8637,8637);
INSERT INTO stanza VALUES('C284','8','沒有間隔，<br/>主，沒有間隔；<br/>直到此生過去，<br/>脫離地上寄廬，<br/>永遠與你同居；<br/>沒有間隔，<br/>沒有間隔。<br/>',NULL,8638,8638);
INSERT INTO stanza VALUES('C285','1','求主帶我上到高山，<br/>給我只見你自己，<br/>天上聲音給我聽見，<br/>新鮮空氣給我吸。<br/>',NULL,8639,8639);
INSERT INTO stanza VALUES('C285','chorus','帶我上到更高之山，<br/>與你交通更親密；<br/>更在靈中飲於活泉，<br/>更得享受你自己。<br/>',NULL,8640,8640);
INSERT INTO stanza VALUES('C285','2','更高山上，更高亮光，<br/>遠超屬地的遮蔽；<br/>生命之中與你同王，<br/>脫開掙扎的自己。<br/>',NULL,8641,8641);
INSERT INTO stanza VALUES('C285','3','保守我在更高山上，<br/>向著標竿直往前；<br/>直到模成你的形像，<br/>流露你愛和恩典。<br/>',NULL,8642,8642);
INSERT INTO stanza VALUES('C286','1','我每時刻需你，<br/>可愛恩主；<br/>無人柔聲似你，<br/>能施安撫。<br/>',NULL,8643,8643);
INSERT INTO stanza VALUES('C286','chorus','我需你，主，我需你，<br/>每時刻我需你；<br/>哦主，現在賜恩力，<br/>我來就你。<br/>',NULL,8644,8644);
INSERT INTO stanza VALUES('C286','2','我每時刻需你，<br/>求你來臨；<br/>試探失去能力，<br/>當你親近。<br/>',NULL,8645,8645);
INSERT INTO stanza VALUES('C286','3','我每時刻需你，<br/>或樂或苦；<br/>速來住留不離，<br/>免我虛度。<br/>',NULL,8646,8646);
INSERT INTO stanza VALUES('C286','4','我每時刻需你，<br/>求你指引；<br/>使你所許福氣，<br/>應於我身。<br/>',NULL,8647,8647);
INSERT INTO stanza VALUES('C286','5','我每時刻需你，<br/>至聖恩主；<br/>使我完全屬你，<br/>永偕無阻。<br/>',NULL,8648,8648);
INSERT INTO stanza VALUES('C287','1','主，我是屬你，<br/>我聽你宣告，<br/>知你愛我的無匹；<br/>但我是渴望能因信升高，<br/>能以和你更親密。<br/>',NULL,8649,8649);
INSERT INTO stanza VALUES('C287','chorus','吸引我近，更近，<br/>親愛主，<br/>直至你流血身邊；<br/>吸引我近，更近，更近，<br/>親愛主，<br/>直至你同在中間。<br/>',NULL,8650,8650);
INSERT INTO stanza VALUES('C287','2','靠著你恩典，<br/>求你分別我，<br/>從此專一事奉你；<br/>讓我靈望你，<br/>有堅定把握，<br/>我志消失你旨裡。<br/>',NULL,8651,8651);
INSERT INTO stanza VALUES('C287','3','費時雖不多，<br/>喜樂已難言，<br/>當我座前小逗遛；<br/>俯伏你腳前，<br/>和你面對面，<br/>交通有如人間友。<br/>',NULL,8652,8652);
INSERT INTO stanza VALUES('C287','4','愛有其深處，<br/>我不能通曉，<br/>除非有日到那邊；<br/>樂有其高處，<br/>我無法達到，<br/>除非安息你面前。<br/>',NULL,8653,8653);
INSERT INTO stanza VALUES('C288','1','與我同住，<br/>夕陽西沉迅速；<br/>黑暗漸深，<br/>求主與我同住；<br/>安慰消逝，<br/>且無何人能助；<br/>無助之助，<br/>求你與我同住。<br/>',NULL,8654,8654);
INSERT INTO stanza VALUES('C288','2','人生短日，<br/>轉瞬就已入暮，<br/>地樂燈殘，<br/>世榮花謝草枯；<br/>四境所見，<br/>盡是變遷朽腐；<br/>你，不變者，<br/>求來與我同住。<br/>',NULL,8655,8655);
INSERT INTO stanza VALUES('C288','3','莫帶威嚴，<br/>有如王中之王，<br/>只帶慈良，<br/>並你施醫翅膀，<br/>淚來洗憂，<br/>心來聽我求訴；<br/>來，罪人友，<br/>如此與我同住。<br/>',NULL,8656,8656);
INSERT INTO stanza VALUES('C288','4','你的同在，<br/>時時我都需要；<br/>除你恩典，<br/>何能使魔敗逃；<br/>有誰像你，<br/>將我引導扶助；<br/>或陰或晴，<br/>求你與我同住。<br/>',NULL,8657,8657);
INSERT INTO stanza VALUES('C288','5','有你賜福，<br/>我就不怕敵兇；<br/>病而不苦，<br/>流淚也不酸痛；<br/>甚麼毒鉤！<br/>甚麼死亡、墳墓！<br/>我都勝過，<br/>若你與我同住。<br/>',NULL,8658,8658);
INSERT INTO stanza VALUES('C288','6','若我臨終，<br/>願你在我身邊，<br/>照明幽谷，<br/>指我仰望你面；<br/>或到你來，<br/>天曉，地影盡無；<br/>無論如何，<br/>求你與我同住。<br/>',NULL,8659,8659);
INSERT INTO stanza VALUES('C289','1','願你為大，哦主耶穌！<br/>信條、話語、虛儀、<br/>屬人的會、屬世的愛，<br/>不能與你相比。<br/>',NULL,8660,8660);
INSERT INTO stanza VALUES('C289','2','願你為大，哦主耶穌！<br/>你愛征服了我；<br/>靠你十架我向己死，<br/>完全為你而活。<br/>',NULL,8661,8661);
INSERT INTO stanza VALUES('C289','3','願你為大，哦主耶穌！<br/>全人被你充滿，<br/>使我思想像你思想，<br/>喜歡像你喜歡。<br/>',NULL,8662,8662);
INSERT INTO stanza VALUES('C289','4','願你為大，哦主耶穌！<br/>把我改變全備；<br/>從這幔子(軟弱肉體)<br/>顯出你的榮美。<br/>',NULL,8663,8663);
INSERT INTO stanza VALUES('C289','5','願你為大，哦主耶穌！<br/>我心真是要求：<br/>作你奴隸，行你旨意，<br/>一生不再自由。<br/>',NULL,8664,8664);
INSERT INTO stanza VALUES('C290','1','主耶穌，<br/>我羨慕活在你面前，<br/>在早晨，在晚上，<br/>只有一世間；<br/>不讓我心快樂，<br/>若我在愛慕、在感覺、<br/>或思想無你的事物。<br/>每一刻，每一天，<br/>不論何痛苦，<br/>當世上正沒有<br/>甚麼可鼓舞，<br/>當歎息正不禁，<br/>眼淚流滴滴，<br/>主，擦乾我眼淚，<br/>平靜我歎息。<br/>',NULL,8665,8665);
INSERT INTO stanza VALUES('C290','2','我每次如夢想<br/>人生的善美，<br/>親愛主，我求你，<br/>必須也在內！<br/>不讓我離開你<br/>去尋求快樂，<br/>不讓我憑自己<br/>去單獨選擇！<br/>當每夜萬籟靜，<br/>孤單自處時，<br/>主耶穌，我求你，<br/>仍與我同止；<br/>當每晨未破曉，<br/>我仍蒙昧中，<br/>求你來低聲喚，<br/>將我耳開通。<br/>',NULL,8666,8666);
INSERT INTO stanza VALUES('C290','3','當每次我虔讀<br/>你聖潔話語，<br/>求你用你榮耀<br/>照亮每一句；<br/>讓我能明看見：<br/>這寶貴救主，<br/>和祂的大救恩，<br/>無一不我屬。<br/>當我正無倚靠<br/>跪到你座前，<br/>求垂聽我禱告，<br/>賜彀用恩典；<br/>有時候因有錯，<br/>禱告你不聽，<br/>別收回你同在，<br/>使我感不寧。<br/>',NULL,8667,8667);
INSERT INTO stanza VALUES('C290','4','當每次我想到<br/>屬天的福氣，<br/>讓我心切羨慕<br/>早日會見你；<br/>我今日所希望<br/>只有你再來，<br/>我那日所快樂<br/>只有你同在。<br/>主，求你教訓我<br/>活在你面前，<br/>在早晨，在晚上，<br/>只有一世間；<br/>不讓我心快樂，<br/>若我在愛慕、<br/>在感覺、或思想<br/>無你的事物。<br/>',NULL,8668,8668);
INSERT INTO stanza VALUES('C291','1','救主，求你引領我，<br/>靈中引我過生活；<br/>行在生命的光中，<br/>不再掙扎或妄動。<br/>',NULL,8669,8669);
INSERT INTO stanza VALUES('C291','chorus','引我，引我，<br/>救主，這是我所求；<br/>藉你生命的水流，<br/>引我你路來行走。<br/>',NULL,8670,8670);
INSERT INTO stanza VALUES('C291','2','你在我裡作生命，<br/>藉你活律來引領；<br/>在我身上你執政，<br/>所有黑暗變光明。<br/>',NULL,8671,8671);
INSERT INTO stanza VALUES('C291','3','你是釋放人的靈，<br/>求你全將我規正；<br/>我的心思得更新，<br/>就能滿足你聖心。<br/>',NULL,8672,8672);
INSERT INTO stanza VALUES('C292','1','救主，領我免迷途，<br/>溫柔領我完世路；<br/>在你身邊我穩固，<br/>在你愛裡我居住。<br/>',NULL,8673,8673);
INSERT INTO stanza VALUES('C292','chorus','領我，領我，<br/>救主，領我免迷途；<br/>我的前面無把握，<br/>救主，領我完世路。<br/>',NULL,8674,8674);
INSERT INTO stanza VALUES('C292','2','你是我魂避難所，<br/>何怕人生起風波！<br/>有你親近我安全，<br/>有你憐憫我無怨。<br/>',NULL,8675,8675);
INSERT INTO stanza VALUES('C292','3','救主，領我到盡頭，<br/>直到你來的時候，<br/>我要與你永同在，<br/>同享安息到萬代。<br/>',NULL,8676,8676);
INSERT INTO stanza VALUES('C293','1','求你揀選我道路，<br/>我主，為我揀選，<br/>我無自己的羨慕，<br/>我要你的意念；<br/>你所命定的前途，<br/>無論何等困難，<br/>我要甘心的順服，<br/>來尋你的喜歡。<br/>',NULL,8677,8677);
INSERT INTO stanza VALUES('C293','chorus','求你握住我的手，<br/>你知我的軟弱；<br/>否則我只能憂愁，<br/>不知如何生活。<br/>你若握住我的手，<br/>不問你是揀選<br/>何種道路和時候，<br/>我心都覺甘甜。<br/>',NULL,8678,8678);
INSERT INTO stanza VALUES('C293','2','不問平坦與崎嶇，<br/>只要是你揀選，<br/>就是我所最心許，<br/>別的不合意願；<br/>我是不敢自作主，<br/>你許，我也不要，<br/>求你揀選我道路，<br/>我要聽你遣調。<br/>',NULL,8679,8679);
INSERT INTO stanza VALUES('C293','3','我的時候在你手，<br/>不論或快或慢，<br/>照你喜悅來畫籌，<br/>我無自己喜歡；<br/>你若定我須忍耐<br/>許多日日年年，<br/>我就不願早無礙，<br/>一切就早改變。<br/>',NULL,8680,8680);
INSERT INTO stanza VALUES('C293','4','主，我餘生的小杯，<br/>求你隨意傾注，<br/>或是喜樂或傷悲，<br/>求你隨意作主；<br/>一切痛苦都甘甜，<br/>若知是你意思，<br/>一切享受成可厭，<br/>若非你所恩賜。<br/>',NULL,8681,8681);
INSERT INTO stanza VALUES('C293','5','求你為我來揀選，<br/>健康或是疾病，<br/>或是笑容或淚眼，<br/>美名或是惡名；<br/>不論事情大或小，<br/>揀選？我是不要，<br/>不要自己的感覺，<br/>只要你的榮耀。<br/>',NULL,8682,8682);
INSERT INTO stanza VALUES('C294','1','緊握我手，<br/>我是這樣的無倚，<br/>沒有扶助，<br/>一步我不敢走；<br/>緊握我手！<br/>親愛救主，求提攜，<br/>禍害、恐嚇<br/>纔不使我戰抖。<br/>',NULL,8683,8683);
INSERT INTO stanza VALUES('C294','2','緊握我手！<br/>求你更緊的拉我，<br/>近你自己，<br/>我一切中一切；<br/>緊握我手！<br/>免得偶然我流落，<br/>迷失了你，<br/>我腳發軟滑跌。<br/>',NULL,8684,8684);
INSERT INTO stanza VALUES('C294','3','緊握我手！<br/>前面道路不豫曉，<br/>因為沒有你臉上的亮光；<br/>但是，當我藉信<br/>瞥見你榮耀，<br/>我的喜樂立即發音成唱。<br/>',NULL,8685,8685);
INSERT INTO stanza VALUES('C294','4','緊握我手！<br/>當我走到你為我<br/>所經過的黑河孤單邊界，<br/>屬天的光纔會<br/>照射到此河，<br/>其中黑水纔會不像黑夜。<br/>',NULL,8686,8686);
INSERT INTO stanza VALUES('C295','1','只要是你道路，<br/>不論如何黑暗，<br/>不管怎樣艱苦，<br/>求你為我揀選。<br/>',NULL,8687,8687);
INSERT INTO stanza VALUES('C295','2','平坦或是崎嶇，<br/>必定都是上好；<br/>筆直或是彎曲，<br/>安息都必引到。<br/>',NULL,8688,8688);
INSERT INTO stanza VALUES('C295','3','不敢自作選擇，<br/>即可，我也不願；<br/>求你為我定奪，<br/>使我腳步不偏。<br/>',NULL,8689,8689);
INSERT INTO stanza VALUES('C295','4','以苦或是以樂，<br/>我杯由你充滿；<br/>照你看為最妥，<br/>禍福為我揀選。<br/>',NULL,8690,8690);
INSERT INTO stanza VALUES('C295','5','為我選擇友人，<br/>選擇疾病、健康；<br/>為我選擇責任，<br/>選擇衰貧、隆昌。<br/>',NULL,8691,8691);
INSERT INTO stanza VALUES('C295','6','事情不論大小，<br/>不隨我的愛好；<br/>你是我的引導，<br/>是我智慧、至寶。<br/>',NULL,8692,8692);
INSERT INTO stanza VALUES('C296','1','我願更多認識基督，<br/>更多追蹤祂的道路；<br/>更多認識祂的救贖，<br/>更多享受祂的豐富。<br/>',NULL,8693,8693);
INSERT INTO stanza VALUES('C296','chorus','更多認識基督，<br/>更多認識基督。<br/>更多認識祂的救贖，<br/>更多享受祂的豐富。<br/>',NULL,8694,8694);
INSERT INTO stanza VALUES('C296','2','更多認識復活大能，<br/>更多經歷無窮生命；<br/>更多取用升天權柄，<br/>更多有分榮耀得勝。<br/>',NULL,8695,8695);
INSERT INTO stanza VALUES('C296','3','更多得著聖靈啟示，<br/>更多知道父神意思；<br/>更多看見幔內的事，<br/>更多效法基督的死。<br/>',NULL,8696,8696);
INSERT INTO stanza VALUES('C296','4','更多相信主的聖言，<br/>更多倚靠祂的恩典；<br/>更多愛慕祂的顯現，<br/>更多盼望祂的王權。<br/>',NULL,8697,8697);
INSERT INTO stanza VALUES('C297','1','主！使我更愛你，<br/>和你更親密，<br/>為你名更熱心，<br/>向你話更信，<br/>對你憂更關心，<br/>因你苦更貧，<br/>更覺得你看顧，<br/>更完全順服。<br/>',NULL,8698,8698);
INSERT INTO stanza VALUES('C297','chorus','求主天天扶持我，<br/>給我力量保守我，<br/>使我一生走窄路，<br/>使主心滿意足。<br/>',NULL,8699,8699);
INSERT INTO stanza VALUES('C297','2','主！使我更得勝，<br/>向你更忠誠，<br/>在你手更有用，<br/>對你仇更勇，<br/>受苦更為忍耐，<br/>犯罪更悲哀，<br/>更喜樂任怨勞，<br/>更完全倚靠。<br/>',NULL,8700,8700);
INSERT INTO stanza VALUES('C297','3','主！使我更屬天，<br/>更常見你面，<br/>更愛慕你再來，<br/>更想你『同在，』<br/>更願意處卑微，<br/>更輕看高貴，<br/>更為不顧自己，<br/>凡事更像你。<br/>',NULL,8701,8701);
INSERT INTO stanza VALUES('C298','1','哦主，求你長在我心，<br/>你外再無他求！<br/>使我逐日與你更親，<br/>逐日向罪自由。<br/>',NULL,8702,8702);
INSERT INTO stanza VALUES('C298','chorus','願你逐日維持的力，<br/>仍然顧我軟弱，<br/>你的亮光除我陰翳，<br/>生命吞我死涸。<br/>',NULL,8703,8703);
INSERT INTO stanza VALUES('C298','2','當你榮光照我心頭，<br/>所有惡念都消；<br/>『我是無有，<br/>你是萬有，』<br/>我願常受此教。<br/>',NULL,8704,8704);
INSERT INTO stanza VALUES('C298','3','你這聖潔、榮耀的主，<br/>讓我更多瞻仰；<br/>無論快樂或是艱苦，<br/>我願作你活像。<br/>',NULL,8705,8705);
INSERT INTO stanza VALUES('C298','4','天上喜樂，求你膏我，<br/>靈力，求你助我；<br/>但願你的熱切愛火，<br/>從我全人射過。<br/>',NULL,8706,8706);
INSERT INTO stanza VALUES('C298','5','可憐的己，願其消沉，<br/>惟你作我目標，<br/>使我逐日藉著你恩，<br/>更配與你相交。<br/>',NULL,8707,8707);
INSERT INTO stanza VALUES('C298','chorus','願你逐日維持的力，<br/>仍然顧我軟弱，<br/>你的亮光除我陰翳，<br/>生命吞我死涸。<br/>第一節的『長，』意思是生長、長大。<br/>',NULL,8708,8708);
INSERT INTO stanza VALUES('C299','1','天程旅客的糧食，<br/>聖徒可食之餅，<br/>每日嗎哪天所賜，<br/>適合屬天性情；<br/>長久渴慕享受你，<br/>飽嘗你的豐富，<br/>直到地樂全滅跡，<br/>所有心願滿足。<br/>',NULL,8709,8709);
INSERT INTO stanza VALUES('C299','2','湧流生命的活水，<br/>流自裂開靈磐，<br/>明晶活泉何甘美，<br/>你是愛的泉源。<br/>讓我白白來暢飲，<br/>消除我的乾渴；<br/>你外，別水不再尋，<br/>永遠將你來喝。<br/>',NULL,8710,8710);
INSERT INTO stanza VALUES('C299','3','喫你、喝你、享受你，<br/>我們敬拜感戴；<br/>在你話並你靈裡，<br/>飽嘗你的大愛。<br/>使我從你得餧養，<br/>憑你活在地上，<br/>滿有長成的身量，<br/>叫你得著顯彰。<br/>',NULL,8711,8711);
INSERT INTO stanza VALUES('C300','1','變成主的形狀！<br/>這是我心願！<br/>我今深切仰望，<br/>願主就成全！<br/>',NULL,8712,8712);
INSERT INTO stanza VALUES('C300','2','變成主的形狀！<br/>主就是那靈；<br/>肯讓主靈通暢，<br/>此願就完成。<br/>',NULL,8713,8713);
INSERT INTO stanza VALUES('C300','3','敞著我臉觀瞧，<br/>瞧見主榮光；<br/>如同鏡子返照，<br/>照出主形狀。<br/>',NULL,8714,8714);
INSERT INTO stanza VALUES('C300','4','但願再無遮蔽，<br/>常將主返照；<br/>更願心能純一，<br/>返照無攪擾。<br/>',NULL,8715,8715);
INSERT INTO stanza VALUES('C300','5','觀看主的榮光，<br/>與主面對面；<br/>一直將主瞻仰，<br/>心不再他轉。<br/>',NULL,8716,8716);
INSERT INTO stanza VALUES('C300','6','變成主的形狀，<br/>乃是我目標！<br/>將主印在心上，<br/>反映主榮耀。<br/>',NULL,8717,8717);
INSERT INTO stanza VALUES('C300','7','變成主的形狀，<br/>榮上又加榮！<br/>顯出主的榮光，<br/>無窮又無終！<br/>',NULL,8718,8718);
INSERT INTO stanza VALUES('C301','1','哦，我要像你，<br/>可愛的救主！<br/>這是我所求，是我所慕；<br/>我歡喜丟棄一切的富足，<br/>盼望能和你形像合符。<br/>',NULL,8719,8719);
INSERT INTO stanza VALUES('C301','chorus','哦，我要像你！<br/>哦，我要像你！<br/>可愛的救主，像你模樣；<br/>像你的甘甜，<br/>像你的貞堅，<br/>在我的衷心，刻你形像。<br/>',NULL,8720,8720);
INSERT INTO stanza VALUES('C301','2','哦，我要像你：<br/>那樣的柔細，<br/>寬恕又憐憫、<br/>仁愛、良善，<br/>幫助孤單的，<br/>勉勵灰心的，<br/>尋找犯罪人，<br/>不辭危難。<br/>',NULL,8721,8721);
INSERT INTO stanza VALUES('C301','3','哦，我要像你：<br/>那樣的忍耐，<br/>聖潔而謙卑，於人無傷，<br/>溫和的接受無理的苦待，<br/>寧可救別人，自己死亡。<br/>',NULL,8722,8722);
INSERT INTO stanza VALUES('C301','4','哦，我要像你！<br/>我今迫切求：<br/>我願出代價跟隨你行，<br/>將我的所是和我的所有，<br/>完全獻給你，不自經營。<br/>',NULL,8723,8723);
INSERT INTO stanza VALUES('C301','5','哦，我要像你！<br/>正當我祈求，<br/>倒下你的愛充滿我心，<br/>使我作個殿，<br/>配給你居留，<br/>使我的生命與你相印。<br/>',NULL,8724,8724);
INSERT INTO stanza VALUES('C302','1','主阿，何等奧祕，<br/>你靈在我靈！<br/>也是何等實際，<br/>二靈成一靈！<br/>',NULL,8725,8725);
INSERT INTO stanza VALUES('C302','2','我能靠靈行動，<br/>因靈而屬靈；<br/>也能憑靈事奉，<br/>以靈敬拜靈。<br/>',NULL,8726,8726);
INSERT INTO stanza VALUES('C302','3','靈裡接觸相交，<br/>我靈就剛強；<br/>靈裡讀經、禱告，<br/>我靈就高昂。<br/>',NULL,8727,8727);
INSERT INTO stanza VALUES('C302','4','求你使我靈強，<br/>點活別人靈！<br/>使我靈能高昂，<br/>釋放別人靈！<br/>',NULL,8728,8728);
INSERT INTO stanza VALUES('C302','5','使我每一出聲，<br/>就能推動靈！<br/>無論有何動靜，<br/>都能供應靈！<br/>',NULL,8729,8729);
INSERT INTO stanza VALUES('C302','6','但願我靈一動，<br/>人靈就開啟！<br/>但願我靈一衝，<br/>人靈就提起！<br/>',NULL,8730,8730);
INSERT INTO stanza VALUES('C302','7','主阿，求你垂顧，<br/>多用靈來吹！<br/>人人靈都豐富，<br/>人人靈加倍！<br/>',NULL,8731,8731);
INSERT INTO stanza VALUES('C303','1','祂的臉面，<br/>祂的天使常看見，<br/>但不認識祂的大愛；<br/>祂的聖徒<br/>雖然認識愛無限，<br/>卻未看見祂的丰采。<br/>他們不久<br/>也要看見祂臉面，<br/>認識祂的榮耀光明；<br/>但馬利亞<br/>曾看見祂的淚眼，<br/>知道祂心痛的情形。<br/>知道祂心痛的情形。<br/>',NULL,8732,8732);
INSERT INTO stanza VALUES('C303','2','我們快要<br/>完全知道我們主，<br/>已往從未如此知道；<br/>但是今日<br/>醫治傷心的摸撫，<br/>不是那日感覺得到。<br/>那日雖有<br/>無窮無盡的讚美，<br/>卻無流淚迫切禱告，<br/>卻無傷心痛苦<br/>所得的安慰，<br/>也無困難所生倚靠。<br/>也無困難所生倚靠。<br/>',NULL,8733,8733);
INSERT INTO stanza VALUES('C303','3','那日雖有<br/>無比榮耀的冠冕，<br/>但無十架可以順從；<br/>祂為我們<br/>所受一切的磨碾，<br/>今日纔能與祂交通。<br/>進入安息，<br/>就再尋不到疲倦，<br/>再無機會為祂受苦；<br/>再也不能<br/>為祂經過何試煉，<br/>再為祂捨棄何幸福。<br/>再為祂捨棄何幸福。<br/>',NULL,8734,8734);
INSERT INTO stanza VALUES('C303','4','哎阿，為祂，<br/>機會已是何等少，<br/>所有機會快要過去，<br/>機會無多，<br/>為祂，蒙羞和受嘲，<br/>為祂，再來分心、分慮。<br/>不久就無<br/>誤會、怒罵與凌辱，<br/>就無孤單、寂寞、離別；<br/>我當寶貝<br/>這些不久的祝福，<br/>我藉這些與你聯結。<br/>我藉這些與你聯結。<br/>',NULL,8735,8735);
INSERT INTO stanza VALUES('C303','5','主，我羨慕<br/>早日看見你臉面，<br/>那是實在好得無比；<br/>但是，我也不願<br/>免去你試煉，<br/>失去如此交通甜蜜。<br/>求你憐憫，<br/>使我充滿你大愛，<br/>不顧一切為你生活；<br/>免你僕人<br/>今天急切望將來，<br/>將來又悔今天錯過。<br/>將來又悔今天錯過。<br/>',NULL,8736,8736);
INSERT INTO stanza VALUES('C304','1','從我活出你的自己，<br/>耶穌，你是我生命；<br/>對於我的所有問題，<br/>求你以你為答應。<br/>從我活出你的自己，<br/>一切事上能隨意，<br/>我不過是透明用器，<br/>為著彰顯你祕密。<br/>',NULL,8737,8737);
INSERT INTO stanza VALUES('C304','2','殿宇今已完全奉獻，<br/>已除所有的不潔，<br/>但願你的榮耀火焰，<br/>今從裡面就露襭。<br/>全地現在都當肅穆，<br/>我的身體今進供，<br/>作你順服、安靜奴僕，<br/>只有被你來推動。<br/>',NULL,8738,8738);
INSERT INTO stanza VALUES('C304','3','所有肢體每個時刻，<br/>約束、等候你發言，<br/>準備為你前來負軛，<br/>或是不用放一邊。<br/>約束，沒有不安追求，<br/>沒有緊張與受壓，<br/>沒有因受對付怨尤，<br/>沒有因懊悔倒下。<br/>',NULL,8739,8739);
INSERT INTO stanza VALUES('C304','4','乃是柔軟、安靜、安息，<br/>脫離傾向與成見，<br/>讓你能彀自由定意，<br/>當你對我有指點。<br/>從我活出你的自己，<br/>耶穌你是我生命；<br/>對於我的所有問題，<br/>求你以你為答應。<br/>第二節的『露襭，』意思是露出所包藏之物。<br/>',NULL,8740,8740);
INSERT INTO stanza VALUES('C305','1','父，我知道我的一生，<br/>你已替我分好；<br/>所有必須發生變更，<br/>我不害怕看到；<br/>我求你賜長久忠誠，<br/>存心討你歡笑。<br/>',NULL,8741,8741);
INSERT INTO stanza VALUES('C305','2','我求要得『有意』的愛，<br/>時常儆醒的慧，<br/>常以笑容歡迎事態，<br/>擦乾不禁眼淚，<br/>心能與牠自己合拍，<br/>好來同情、安慰。<br/>',NULL,8742,8742);
INSERT INTO stanza VALUES('C305','3','我不要有不安意志，<br/>急忙到東到西，<br/>要求要作幾件大事，<br/>或要明白祕密；<br/>我要被待如同孩子，<br/>所往都是受意。<br/>',NULL,8743,8743);
INSERT INTO stanza VALUES('C305','4','無論我在世界何地，<br/>是有何種景況，<br/>我與人心有個交契，<br/>我要保守發旺，<br/>我要為愛出我微力，<br/>為著事奉我王。<br/>',NULL,8744,8744);
INSERT INTO stanza VALUES('C305','5','我求你賜每日恩澤，<br/>使我能常受教；<br/>心能從裡與外調和，<br/>當我與你契交；<br/>滿意只佔微小旁側，<br/>若你能得榮耀。<br/>',NULL,8745,8745);
INSERT INTO stanza VALUES('C305','6','每條路上都有虛假，<br/>是你要我忍耐；<br/>每種境遇都有十架，<br/>是你引我倚賴；<br/>但心靠你若是卑下，<br/>無論那裡可愛。<br/>',NULL,8746,8746);
INSERT INTO stanza VALUES('C305','7','如果在我幸福之中，<br/>有何尚未求祈，<br/>我是渴慕我的內衷，<br/>向你能滿愛意；<br/>寧願不多為你作工，<br/>完全使你歡喜。<br/>',NULL,8747,8747);
INSERT INTO stanza VALUES('C305','8','你愛所定我的選擇，<br/>不是我的捆繩；<br/>我在暗中受你領帥，<br/>已識你的見證：<br/>一生充滿捨己的愛，<br/>就是自由一生。<br/>',NULL,8748,8748);
INSERT INTO stanza VALUES('C306','1','祂為我死，我纔能活；<br/>我今為祂活著，<br/>我命、我愛，我都獻給<br/>那為我釘死的。<br/>',NULL,8749,8749);
INSERT INTO stanza VALUES('C306','chorus','哦耶穌我主，我救主！<br/>使我能專心跟從主；<br/>你怎樣為我而死而活，<br/>讓我照樣為你死活。<br/>',NULL,8750,8750);
INSERT INTO stanza VALUES('C306','2','祂為我死，我纔能死，<br/>脫離罪、己、俗世。<br/>哦，死何奧！<br/>哦，生何高！<br/>願我聯合倚靠！<br/>',NULL,8751,8751);
INSERT INTO stanza VALUES('C306','3','祂為我活，我纔能活，<br/>像祂那樣『無我；』<br/>求主從我顯你性情，<br/>活出你的生命。<br/>',NULL,8752,8752);
INSERT INTO stanza VALUES('C306','4','祂為我活，我願一生<br/>把祂分給眾人；<br/>讓我像主為人而活，<br/>跟隨主的領率。<br/>',NULL,8753,8753);
INSERT INTO stanza VALUES('C307','1','主耶穌，<br/>我真羨慕能得完全，<br/>我要你時刻<br/>活在我的魂間，<br/>粉碎眾偶像，<br/>驅逐所有失敗，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8754,8754);
INSERT INTO stanza VALUES('C307','chorus','比雪更白，<br/>是比雪更白，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8755,8755);
INSERT INTO stanza VALUES('C307','2','主耶穌，<br/>不要讓有『不聖』遺留，<br/>求用你寶血<br/>除去所有污垢，<br/>我為得聖潔，<br/>一切都願割愛，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8756,8756);
INSERT INTO stanza VALUES('C307','3','主耶穌，<br/>求從天上寶座垂憐，<br/>助我獻完全的祭<br/>在你面前；<br/>我放下自己<br/>和我所有障礙，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8757,8757);
INSERT INTO stanza VALUES('C307','4','主耶穌，<br/>為此，我今謙卑祈求，<br/>在十字架下，<br/>我已等候很久，<br/>你所流寶血，<br/>我今完全信賴，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8758,8758);
INSERT INTO stanza VALUES('C307','5','主耶穌，<br/>你已看見我在求尋，<br/>求你今就來，<br/>賜給一個清心；<br/>凡向你求的，<br/>你永不會不睬，<br/>求主洗淨我，<br/>使我比雪更白。<br/>',NULL,8759,8759);
INSERT INTO stanza VALUES('C308','1','世上景色我已一閱，<br/>願你使我目復盲；<br/>不然，我怕祂的喜悅，<br/>不如從前的顯彰。<br/>',NULL,8760,8760);
INSERT INTO stanza VALUES('C308','chorus','世上景色我已一閱，<br/>願你使我目復盲；<br/>不然，我怕祂的喜悅，<br/>不如從前的顯彰。<br/>',NULL,8761,8761);
INSERT INTO stanza VALUES('C308','2','晨曦、晚霞、<br/>星光、雲錦，<br/>留等樂園再接觸；<br/>今天在此有祂憐憫，<br/>即使盲目亦滿足。<br/>',NULL,8762,8762);
INSERT INTO stanza VALUES('C308','3','我今不望離開苦刺，<br/>甘心軟弱望加恩；<br/>座上榮耀、幔內啟示，<br/>依然照亮無眼人。<br/>',NULL,8763,8763);
INSERT INTO stanza VALUES('C308','4','黑夜沉沉何等美麗，<br/>摸索用信不用眼；<br/>祂受人欺，祂被人譏，<br/>我見祂的發光臉。<br/>',NULL,8764,8764);
INSERT INTO stanza VALUES('C308','5','超過月亮，超過日頭，<br/>超過星河並雲霄，<br/>乃是那戴荊冕聖首<br/>所顯無比的榮耀。<br/>',NULL,8765,8765);
INSERT INTO stanza VALUES('C308','chorus','世上景色我已一閱，<br/>願你使我目復盲；<br/>不然，我怕祂的喜悅，<br/>不如從前的顯彰。<br/>這首詩歌是一位姊妹寫的。<br/>她原來雙目失明，當另一位姊妹為<br/>她按手禱告之後，她的眼睛得了醫治，<br/>她就寫了這首詩歌。<br/>第一節『你』就是指為她按手的姊妹。<br/>',NULL,8766,8766);
INSERT INTO stanza VALUES('C309','1','求主啟示主自己，<br/>使我認識我肉體；<br/>願主恩典大作工，<br/>使我俯伏灰塵中。<br/>逐時逐日我求勝，<br/>一生一世終無能，<br/>善雖願意作不來，<br/>惡雖恨惡脫不開。<br/>',NULL,8767,8767);
INSERT INTO stanza VALUES('C309','2','裡面意思雖要神，<br/>外頭行為總可恨；<br/>愛莫能助將奈何！<br/>事與願違真束縛！<br/>神律纔顯罪便在，<br/>善念一動惡也來；<br/>肢體的律擄了我，<br/>掙扎奮鬥終難脫。<br/>',NULL,8768,8768);
INSERT INTO stanza VALUES('C309','3','多次跌倒多次起，<br/>時而立志時而遺，<br/>要求得勝反退潰，<br/>願意成聖倒污穢。<br/>我實已是賣給罪，<br/>我真已經無能為，<br/>我的肉體沒良善，<br/>我的自己乃黑暗。<br/>',NULL,8769,8769);
INSERT INTO stanza VALUES('C309','4','我今已略識自己，<br/>實在沒有一點力，<br/>我的性情真古怪，<br/>我的生命全敗壞；<br/>自己詭詐不可靠，<br/>肉體軟弱不能保，<br/>我今所有的盼望，<br/>都在耶穌我的王。<br/>',NULL,8770,8770);
INSERT INTO stanza VALUES('C309','5','求主十架治死我，<br/>使我靠主而生活；<br/>求主聖靈充滿我，<br/>使我憑主而工作；<br/>願主的死在我身，<br/>天天作工比前深，<br/>讓我自己全消滅，<br/>讓主生命來提挈。<br/>',NULL,8771,8771);
INSERT INTO stanza VALUES('C309','6','我的光景真是苦，<br/>誰能使我不為奴，<br/>救我脫離取死身，<br/>使我能彀常得勝？<br/>耶穌為我流寶血，<br/>基督作我的聖潔，<br/>我今接祂為生命，<br/>我今服祂的號令。<br/>',NULL,8772,8772);
INSERT INTO stanza VALUES('C309','7','完全聖潔無惡意！<br/>完全順服無自己－不再覺羞到父前！<br/>不再難過見主面！<br/>哦，這生命何等高！<br/>一信主恩即臨到！<br/>感謝主今聽呼求，<br/>使我完全得自由。<br/>',NULL,8773,8773);
INSERT INTO stanza VALUES('C310','1','一生聰明未遇敵手，<br/>以掃、以撒均成往事；<br/>我今到了生死關頭，<br/>雖然絕望仍然自恃；<br/>束手就縛我不能受，<br/>我要用力，我要用謀。<br/>',NULL,8774,8774);
INSERT INTO stanza VALUES('C310','2','彷彿我見有人偷營，<br/>我心害怕但我倔強：<br/>惟恐我的末日已定，<br/>用盡全身所有力量；<br/>祂來摔跤，我要招架，<br/>未到死地還要掙扎。<br/>',NULL,8775,8775);
INSERT INTO stanza VALUES('C310','3','奇哉！我用已往經驗，<br/>摔跤一夜祂仍不倒；<br/>我的力量眼見將減，<br/>但是祂像無意回報；<br/>奇哉！又像無法脫身，<br/>我的膽量又復加甚。<br/>',NULL,8776,8776);
INSERT INTO stanza VALUES('C310','4','如此對手從未得會，<br/>祂雖告我祂的名字，<br/>我仍不知所戰為誰，<br/>只知祂有很大賞賜；<br/>我就迫祂向我賜福，<br/>迫祂向我賜福、屈服。<br/>',NULL,8777,8777);
INSERT INTO stanza VALUES('C310','5','天已黎明難分勝負：<br/>好像無法、好像無能，<br/>祂就被迫向我賜福，<br/>並且稱許，說我得勝，<br/>說我新名是以色列；<br/>當我起來，我腿已瘸！<br/>',NULL,8778,8778);
INSERT INTO stanza VALUES('C310','6','有了微光進我暗心，<br/>開始照亮使我領會：<br/>若我有能，為何扭筋？<br/>若我得勝，為何瘸腿？<br/>是祂得勝留下記號，<br/>使我愚昧受了警告。<br/>',NULL,8779,8779);
INSERT INTO stanza VALUES('C310','7','瞬息之間，光滿我心，<br/>如同洪流沖破堤防，<br/>我就看見榮耀無盡，<br/>迫我敬拜、迫我隱藏；<br/>我纔知道我的大罪、<br/>我的不軌、我的污穢。<br/>',NULL,8780,8780);
INSERT INTO stanza VALUES('C310','8','哎阿，想到：我曾勝過<br/>造物的主、全能的神！<br/>荒謬之極，該當有禍！<br/>該死之至，該死無恩！<br/>我這雙手竟然背叛，<br/>強迫主神不得動彈！<br/>',NULL,8781,8781);
INSERT INTO stanza VALUES('C310','9','你是何等榮耀的神，<br/>萬軍之主何等顯赫；<br/>我一認識你是誰人，<br/>並一看見你是如何，<br/>我要長號，我要流淚，<br/>我要懊悔，我要下跪。<br/>',NULL,8782,8782);
INSERT INTO stanza VALUES('C310','10','怎麼可能！怎麼可以！<br/>見神的面，與神相持！<br/>我恨不得有縫入地，<br/>纔可稍微掩我羞恥：<br/>為何我不在此以先，<br/>即已毀滅，離世長眠？<br/>',NULL,8783,8783);
INSERT INTO stanza VALUES('C310','11','我恨自己過於昏沉，<br/>因為驕傲瞎了眼睛；<br/>想到我是得勝了神，<br/>我就不禁膽戰心驚：<br/>渾身無力，何只一腿？<br/>百節俱脫，全人崩潰！<br/>',NULL,8784,8784);
INSERT INTO stanza VALUES('C310','12','我今回顧我的一生，<br/>全是充滿敗壞事體：<br/>保全自己，將神犧牲，<br/>愚昧的心只知快意，<br/>我還以為祝福在於<br/>強神來聽我的所欲。<br/>',NULL,8785,8785);
INSERT INTO stanza VALUES('C310','13','我有欲望天來順服，<br/>我出主張天來安排，<br/>我有喜好望神讓步，<br/>我有工作望神領帥，<br/>我若急切天須趕快，<br/>那有一次神不失敗！<br/>',NULL,8786,8786);
INSERT INTO stanza VALUES('C310','14','世界竟有如此邪惡、<br/>驕傲、頑固、詭詐的人！<br/>主，你知道我是雅各，<br/>充滿敗壞，充滿可恨；<br/>我無可望，只望憐憫，<br/>你來憐憫敗壞這心。<br/>',NULL,8787,8787);
INSERT INTO stanza VALUES('C310','15','我今已蒙憐憫一摸，<br/>舉步蹣跚，恩典遺跡；<br/>我若忘記，新的腿窩<br/>要使我感何等無倚；<br/>你雖許我作以色列，<br/>但是雅各永遠病瘸。<br/>',NULL,8788,8788);
INSERT INTO stanza VALUES('C310','16','主，我服了，是你得勝：<br/>因你失敗我求失敗，<br/>因我得勝我來投誠，<br/>你的軟弱領我下拜；<br/>我願一生戰戰兢兢，<br/>行你旨意，榮耀你名。<br/>',NULL,8789,8789);
INSERT INTO stanza VALUES('C311','1','主阿，求你將我看，<br/>賜我甜美的簡單；<br/>靈中貧窮，心卑微，<br/>尋求猶如向日葵。<br/>',NULL,8790,8790);
INSERT INTO stanza VALUES('C311','2','脫離作威的自己，<br/>脫離財奴之所倚，<br/>脫離顯揚的興趣，<br/>脫離受誇的私慾。<br/>',NULL,8791,8791);
INSERT INTO stanza VALUES('C311','3','所有供我驕傲的，<br/>求你為我全拋棄；<br/>使我意志服你的，<br/>謙卑順服到死地。<br/>',NULL,8792,8792);
INSERT INTO stanza VALUES('C311','4','使我回轉像嬰孩，<br/>將我智、力、全毀壞；<br/>只在你的光中行，<br/>只靠你的能力動。<br/>',NULL,8793,8793);
INSERT INTO stanza VALUES('C311','5','倚在你愛的胸膛，<br/>好像斷奶的仰望；<br/>感到神賜的平安，<br/>充滿在我全人間。<br/>',NULL,8794,8794);
INSERT INTO stanza VALUES('C311','6','讓我活在這姿態，<br/>天天滿出讚美來，<br/>如此到死也不變，<br/>但我等候你顯現。<br/>',NULL,8795,8795);
INSERT INTO stanza VALUES('C312','1','恩主，你是我的安息，<br/>深願我能全享；<br/>停下自己所有活動，<br/>完全將你飽嘗。<br/>',NULL,8796,8796);
INSERT INTO stanza VALUES('C312','2','哦，這詭詐、殘酷自己，<br/>總是掙扎努力，<br/>將你與我的靈隔開，<br/>使我不得安息。<br/>',NULL,8797,8797);
INSERT INTO stanza VALUES('C312','3','『己』取許多狡猾形狀，<br/>好像都是必要，<br/>給我覺得安息於你，<br/>並不一定可靠。<br/>',NULL,8798,8798);
INSERT INTO stanza VALUES('C312','4','我今尋求神聖安息，<br/>完全脫離自己；<br/>惟獨讓你作王掌權，<br/>裡外全都管理。<br/>',NULL,8799,8799);
INSERT INTO stanza VALUES('C312','5','我今躺臥在你手下，<br/>求你著手工作；<br/>願你恩典使我不再<br/>憑自己活著。<br/>',NULL,8800,8800);
INSERT INTO stanza VALUES('C312','6','恩主，作工直到這己<br/>完全被你破碎，<br/>我能完全有你形像，<br/>顯出你的光輝。<br/>',NULL,8801,8801);
INSERT INTO stanza VALUES('C313','1','求主倒空我脫自己，<br/>我心滿詭詐；<br/>這個重大聖潔成績，<br/>只你有辦法。<br/>',NULL,8802,8802);
INSERT INTO stanza VALUES('C313','chorus','求主倒空我脫自己，<br/>裡面無良善；<br/>我的一生全是受欺，<br/>驕傲因黑暗；<br/>求主倒空我脫自己，<br/>裡面真黑暗。<br/>',NULL,8803,8803);
INSERT INTO stanza VALUES('C313','2','求你聽我向你呼祈，<br/>罪過何難除！<br/>自己越看越不滿意，<br/>何況你聖目？<br/>',NULL,8804,8804);
INSERT INTO stanza VALUES('C313','3','我的不安是為甚麼，<br/>求你來揭露；<br/>良心時常控告不默，<br/>我注重何垢？<br/>',NULL,8805,8805);
INSERT INTO stanza VALUES('C313','4','你我之間有重幔子，<br/>交通常間斷；<br/>到底是在那裡有失，<br/>信心不坦然？<br/>',NULL,8806,8806);
INSERT INTO stanza VALUES('C314','1','有一仇敵，其力潛伏，<br/>信徒無不懼怕，<br/>奸狡遠超生來之罪，<br/>與心更為融洽。<br/>就是那個倔強的己，<br/>那個任性的我；<br/>這個自己必須釘死，<br/>在我主纔能活。<br/>',NULL,8807,8807);
INSERT INTO stanza VALUES('C314','2','在我老舊天性裡面，<br/>己是強而有力：<br/>自信、自愛、<br/>自誇、自耀，<br/>全都隨著己意。<br/>己的各面必須拒絕，<br/>必須置於死地，<br/>我纔能進靈中迦南，<br/>得享主作安息。<br/>',NULL,8808,8808);
INSERT INTO stanza VALUES('C314','3','那篡奪你寶座的己，<br/>主阿，救我脫離！<br/>願『我』失去在你裡面，<br/>永遠不得復辟。<br/>哦主，使我脫離自信，<br/>脫離自滿、自足；<br/>完全以你作我能力，<br/>並作我的住處。<br/>',NULL,8809,8809);
INSERT INTO stanza VALUES('C314','4','救我脫離己的尋求，<br/>不再為著自己；<br/>使我總是躺在祭壇，<br/>獻上作你活祭。<br/>脫離驕傲、誇耀、顯揚，<br/>脫離虛榮、美譽，<br/>只以基督為我誇耀，<br/>惟獨將祂高舉。<br/>',NULL,8810,8810);
INSERT INTO stanza VALUES('C314','5','求主向我猛烈吹氣，<br/>燒殺我的自己；<br/>所有己的各方各面，<br/>永遠不再復起。<br/>當你榮光充滿帳幕，<br/>摩西也難站立；<br/>願你榮耀將我充滿，<br/>永遠殺死這己。<br/>',NULL,8811,8811);
INSERT INTO stanza VALUES('C315','1','嘴脣不潔、心意不潔，<br/>都是失敗、都是污穢；<br/>前所希望今已銷滅，<br/>主，你是否仍有恩惠？<br/>',NULL,8812,8812);
INSERT INTO stanza VALUES('C315','2','聖潔裡面仍有行為，<br/>謙卑時候仍憑自己；<br/>連我流淚為罪懊悔，<br/>都需你血把牠洗滌。<br/>',NULL,8813,8813);
INSERT INTO stanza VALUES('C315','3','最好存心仍存自己，<br/>最大捨己仍有動機，<br/>我心就是我的仇敵，<br/>主，我希望可否在你？<br/>',NULL,8814,8814);
INSERT INTO stanza VALUES('C315','4','事奉神中，有己意思，<br/>愛別人中，有己興趣；<br/>我不能動，我不敢止，<br/>事事處處有己寄寓。<br/>',NULL,8815,8815);
INSERT INTO stanza VALUES('C315','5','我的所有難脫舊造，<br/>只要一動就有自己；<br/>何等羨慕你的榮耀<br/>完全充滿蒙福心地。<br/>',NULL,8816,8816);
INSERT INTO stanza VALUES('C315','6','不敢祈求、不敢應許，<br/>主，我只能向你注視；<br/>可否差遣你的話語，<br/>將你榮耀向我啟示。<br/>',NULL,8817,8817);
INSERT INTO stanza VALUES('C316','1','當我蒙恩能彀施恩，<br/>可憐！我竟自己知道！<br/>我是如何超越本分，<br/>自己覺得、自己記牢！<br/>我想我是活在神前，<br/>但我暗許自己敬虔！<br/>',NULL,8818,8818);
INSERT INTO stanza VALUES('C316','2','我的一生充滿試煉，<br/>大至不是常人可忍；<br/>人雖不知我的苦艱，<br/>我卻知道自己堅韌；<br/>我想我是丟棄自己，<br/>但我不忘自己經歷！<br/>',NULL,8819,8819);
INSERT INTO stanza VALUES('C316','3','我知我是滿受恩惠，<br/>已至地上無人似我！<br/>在我身上，在我心內，<br/>我能尋出神的工作！<br/>神的工作在我身上，<br/>我全知道如何欣賞！<br/>',NULL,8820,8820);
INSERT INTO stanza VALUES('C316','4','我知我的所有登造，<br/>我知我的一切善義，<br/>不知不覺我覺自豪，<br/>中心從神移到自己；<br/>我的手中隔夜嗎哪，<br/>已變臭壞，已被蹧蹋。<br/>',NULL,8821,8821);
INSERT INTO stanza VALUES('C316','5','當有朋友向我慰問，<br/>向我苦情表示同情，<br/>我的驕傲不再隱悶，<br/>我的忍耐立即空罄；<br/>我就失敗如同常人，<br/>咒詛生日顯出根本。<br/>',NULL,8822,8822);
INSERT INTO stanza VALUES('C316','6','神阿，我是風聞有你，<br/>講你論你，我是都能；<br/>但是我的敗壞自己，<br/>從未因你有何變更；<br/>我用你賜固我驕傲，<br/>我因你恩加我自高。<br/>',NULL,8823,8823);
INSERT INTO stanza VALUES('C316','7','但我現今親眼見你，<br/>你的聖潔顯我污穢，<br/>你的亮光使我傾圮，<br/>你的榮耀使我痛悔，<br/>使我痛悔我怎能以<br/>對我自己如此著迷？<br/>',NULL,8824,8824);
INSERT INTO stanza VALUES('C316','8','何等慚愧，何等慚愧，<br/>將你恩典裝飾自己，<br/>高抬自己用你作為，<br/>無一動機不是可鄙；<br/>我的失敗不可收拾，<br/>我的得勝更為羞恥。<br/>',NULL,8825,8825);
INSERT INTO stanza VALUES('C316','9','何等羞恥我能驕傲！<br/>何等瞎眼我能愚昧！<br/>污穢竟會以為潔好，<br/>肉體竟會以為佳美；<br/>我是何等無知自義！<br/>我偷多少榮耀歸己！<br/>',NULL,8826,8826);
INSERT INTO stanza VALUES('C316','10','你早知我何等敗壞，<br/>但我竟然一無所知，<br/>竟然以為自己可賴，<br/>豈知乃是十分可恥；<br/>主阿，可否求你救我，<br/>今天為我開此捆鎖。<br/>',NULL,8827,8827);
INSERT INTO stanza VALUES('C316','11','主阿，我心是在希望<br/>能有塵土給我躺臥，<br/>能有爐灰撒我身上，<br/>讓我懊悔我的墮落；<br/>我是羞恥，羞恥無盡，<br/>我有如此敗壞的心。<br/>',NULL,8828,8828);
INSERT INTO stanza VALUES('C316','12','我的言語何等不準，<br/>我的生命何等膚淺，<br/>我的存心無不濁溷，<br/>我的一切無不可厭；<br/>我今恨惡我的自己，<br/>主阿，我的希望在你。<br/>第七節的『傾圮』意思是毀壞。<br/>第十二節的『濁溷』意思是污穢不潔。<br/>',NULL,8829,8829);
INSERT INTO stanza VALUES('C317','1','從那求你將我遮蔽<br/>免去擊你風浪之祈，<br/>從那怕有大志之懼，<br/>從那不敢上進之虛，<br/>從這自嬌的己與性，<br/>釋放你這從軍小兵！<br/>',NULL,8830,8830);
INSERT INTO stanza VALUES('C317','2','從那避難就易之愛，<br/>從那使人怯懦之態，<br/>（這些不能使靈剛強，<br/>也都未釘十字架上，）<br/>從那遮蔽十架事物，<br/>神的羔羊，將我救出。<br/>',NULL,8831,8831);
INSERT INTO stanza VALUES('C317','3','賜我愛心帶我向前，<br/>賜我信心永不喪膽，<br/>賜我盼望永不受挫，<br/>賜我熱情焚燒如火，<br/>使我不像沉海沙土，<br/>卻能上騰衝出雲霧。<br/>',NULL,8832,8832);
INSERT INTO stanza VALUES('C318','1','我以信心仰望<br/>你在十字架上，<br/>我的救主！<br/>求你聽我禱告，<br/>將我罪過寬饒，<br/>使我從今到老，<br/>全屬救主。<br/>',NULL,8833,8833);
INSERT INTO stanza VALUES('C318','2','主，賜能力恩惠，<br/>在這軟弱心內，<br/>熱情鼓舞！<br/>你既為我流血，<br/>我要愛你深切、<br/>真摯、長久、純潔，<br/>如火如荼。<br/>',NULL,8834,8834);
INSERT INTO stanza VALUES('C318','3','我今行走世路，<br/>不時遇見憂苦；<br/>求你引領！<br/>擦乾我的眼淚，<br/>保守我不懊悔，<br/>拯救我不犯罪，<br/>而隨你行。<br/>',NULL,8835,8835);
INSERT INTO stanza VALUES('C318','4','人生短夢一過，<br/>死河要起寒波，<br/>將我淹沒；<br/>那時求主恩惠，<br/>除我疑惑、驚畏，<br/>賜我盼望、安慰，<br/>安然度過。<br/>',NULL,8836,8836);
INSERT INTO stanza VALUES('C319','1','我無能力，我的主，<br/>無法孤獨、孤獨的站立；<br/>我的軟弱成祝福，<br/>如果完全、完全倚靠你。<br/>',NULL,8837,8837);
INSERT INTO stanza VALUES('C319','chorus','每一點，每一天，<br/>我是一樣需恩典，<br/>我仍一樣是無倚，<br/>求你更多、更多顯自己。<br/>',NULL,8838,8838);
INSERT INTO stanza VALUES('C319','2','我的路途真孤苦，<br/>時常疲倦、疲倦不唱詩；<br/>我不認識我路途，<br/>你能使我、使我不迷失。<br/>',NULL,8839,8839);
INSERT INTO stanza VALUES('C319','3','我的感覺常改變，<br/>一切可厭、可厭無價值；<br/>當我眼睛看不見，<br/>正是我主、我主最近時。<br/>',NULL,8840,8840);
INSERT INTO stanza VALUES('C319','4','我是孤單，我的主，<br/>不易喜樂、喜樂並忍耐；<br/>若無甘甜的眷顧，<br/>和你祕密、祕密的同在。<br/>',NULL,8841,8841);
INSERT INTO stanza VALUES('C319','5','時日飛逝河水高，<br/>不久我要、我要橫度過；<br/>四圍冷靜我獨禱，<br/>求你記念、記念我軟弱。<br/>',NULL,8842,8842);
INSERT INTO stanza VALUES('C320','1','哦神，一棵沒有祝福、<br/>枯乾而無安息的樹，<br/>一個無用的障礙物，<br/>在你工場我被顯出。<br/>但我求主：<br/>『勿將我廢棄，<br/>要用你手將我來拿起。<br/>',NULL,8843,8843);
INSERT INTO stanza VALUES('C320','2','好像婦取未劈之麻，<br/>塑者取未成形之蠟，<br/>鐵匠取那粗生之鐵，<br/>作成用具，蒙人喜悅；<br/>照樣，你手要將我拿起，<br/>勿讓你愛將我來廢棄。』<br/>',NULL,8844,8844);
INSERT INTO stanza VALUES('C320','3','頑固意志，如石未碎，<br/>雖含金質難顯寶貴；<br/>天然之心，無用廢物，<br/>像大理石尚未刻出；<br/>因此求主：<br/>『不要廢棄我，<br/>要在你手將我來攻破。<br/>',NULL,8845,8845);
INSERT INTO stanza VALUES('C320','4','好像炸藥攻破堅石，<br/>好像鐵鎚打碎石子，<br/>好像磨石壓碎麥子，<br/>也像乾果破殼供食；<br/>照樣，用你聖手破碎我，<br/>永遠勿讓你愛廢棄我。』<br/>',NULL,8846,8846);
INSERT INTO stanza VALUES('C320','5','雖已破碎，仍不中用，<br/>碎渣還須放到爐中；<br/>雖已壓碎，我仍不能<br/>將那將亡群眾供應；<br/>因此求主：<br/>『不要廢棄我，<br/>為你事工要將我製作。<br/>',NULL,8847,8847);
INSERT INTO stanza VALUES('C320','6','好像金塊經過模製，<br/>就成各種有用樣式；<br/>也像麥粉經過泡製，<br/>水調火烤，可供人食；<br/>照樣用火將我來製作，<br/>永遠勿讓你愛廢棄我。』<br/>',NULL,8848,8848);
INSERT INTO stanza VALUES('C321','1','你這神的隱藏的愛！<br/>長闊高深無人知悉，<br/>遠遠我見你的光彩，<br/>我就歎息望得安息，<br/>我心痛苦，不能安息，<br/>除非我心安息於你。<br/>',NULL,8849,8849);
INSERT INTO stanza VALUES('C321','2','你的聲音，仍然隱招<br/>我來負你甜美的軛；<br/>我雖幾乎前來應召，<br/>但是懼怕前途阻隔；<br/>我志雖定，我情卻離，<br/>我欲向你，反而背你。<br/>',NULL,8850,8850);
INSERT INTO stanza VALUES('C321','3','全是恩典！使你吸引<br/>我心向你追求安息；<br/>我雖追求，不能親近，<br/>流蕩的我無所憑倚；<br/>哦，要何時不再流蕩，<br/>所有腳蹤向你而往？<br/>',NULL,8851,8851);
INSERT INTO stanza VALUES('C321','4','日下有無甚麼東西，<br/>與你相爭來分我心？<br/>呀，我求你把牠割棄，<br/>讓你作王無人與競；<br/>我心纔會不再拘泥，<br/>當牠藉你得了安息。<br/>',NULL,8852,8852);
INSERT INTO stanza VALUES('C321','5','哦，我求你埋藏這己，<br/>使主(非我)從我而活！<br/>惡欲邪情釘死絕跡，<br/>不私留一寶貝罪惡；<br/>除你之外，在凡事上，<br/>使我無求，使我無望！<br/>',NULL,8853,8853);
INSERT INTO stanza VALUES('C321','6','哦主，給我無上之助，<br/>救我脫離無用之慮；<br/>趕出己意離我心府，<br/>離我全人隱密之域；<br/>使我作個順命的人，<br/>不斷稱頌，時常感恩。<br/>',NULL,8854,8854);
INSERT INTO stanza VALUES('C321','7','求你使我時刻離地，<br/>謙卑等候聽你吩咐；<br/>求你對我時常題起：<br/>『我是你愛、你命、<br/>你主；』<br/>來聽你聲，來覺你力，<br/>來嘗你愛，是我所期。<br/>',NULL,8855,8855);
INSERT INTO stanza VALUES('C322','1','求主把我捆綁，<br/>我纔得著釋放；<br/>願主迫我向主繳械，<br/>我纔得勝奏捷；<br/>當我倚靠自己，<br/>我就失敗危亟；<br/>當主膀臂將我監禁，<br/>我手就更有勁。<br/>',NULL,8856,8856);
INSERT INTO stanza VALUES('C322','2','我心未交主時，<br/>真是軟弱愚癡，<br/>自己所願自己不行，<br/>萬事漂流無定；<br/>主若未加鎖鍊，<br/>就難自由進前，<br/>求主慈愛將牠奴隸，<br/>牠纔會得能力。<br/>',NULL,8857,8857);
INSERT INTO stanza VALUES('C322','3','我的生命未死，<br/>終身總是喪失：<br/>勝少敗多，實無能力，<br/>時為肉體歎息。<br/>我若沒有死過，<br/>我就難以活著，<br/>求主使我脫離自己，<br/>纔會完全得你。<br/>',NULL,8858,8858);
INSERT INTO stanza VALUES('C322','4','我今認識了你，<br/>也略知道自己，<br/>所以今後真不願意<br/>再藉天然能力。<br/>求主永遠的靈，<br/>使我生命全釘，<br/>使我治死肉體行為，<br/>主興盛，我衰微。<br/>',NULL,8859,8859);
INSERT INTO stanza VALUES('C323','1','願光今天照亮，主，<br/>在我最黑路上，主，<br/>我求你的大光，主，<br/>照進我的心內。<br/>',NULL,8860,8860);
INSERT INTO stanza VALUES('C323','2','光來明顯一切，主，<br/>光來除去自藉，主，<br/>光來，當光正缺，主，<br/>賜你自己的光。<br/>',NULL,8861,8861);
INSERT INTO stanza VALUES('C323','3','甚麼我都看不見，<br/>撒但正在施欺騙，<br/>求你對準你光線<br/>在我身上，我主！<br/>',NULL,8862,8862);
INSERT INTO stanza VALUES('C323','4','光照我的生命，主，<br/>使得自知之明，主，<br/>沒有絲毫黑影，主，<br/>光照使知軟弱。<br/>',NULL,8863,8863);
INSERT INTO stanza VALUES('C323','5','集中我心對你，主，<br/>使牠自由無羈，主，<br/>照牠使知你意，主，<br/>將你的光，照我！<br/>',NULL,8864,8864);
INSERT INTO stanza VALUES('C323','6','使我永遠能行動<br/>在你無影亮光中，<br/>不離同在的交通，<br/>認識光的拆毀。<br/>',NULL,8865,8865);
INSERT INTO stanza VALUES('C324','1','除去我的遮蔽，<br/>使我得見亮光！<br/>任何不再受欺，<br/>一切認識真像。<br/>',NULL,8866,8866);
INSERT INTO stanza VALUES('C324','chorus','主阿，願你這真光，<br/>你這生命之光，<br/>現在就肯來照亮，<br/>使我一切明朗。<br/>',NULL,8867,8867);
INSERT INTO stanza VALUES('C324','2','對於我的自己，<br/>我真不彀認識；<br/>因受驕傲所欺，<br/>常是自滿、自是。<br/>',NULL,8868,8868);
INSERT INTO stanza VALUES('C324','3','對於你的自己，<br/>我更缺少認識；<br/>所知多是道理，<br/>缺少真實啟示。<br/>',NULL,8869,8869);
INSERT INTO stanza VALUES('C324','4','對於你的生命，<br/>我也缺乏認識；<br/>肉體或是聖靈，<br/>常是以彼為此。<br/>',NULL,8870,8870);
INSERT INTO stanza VALUES('C324','5','對於你的道路，<br/>我也常是迷糊；<br/>因著偏於單獨，<br/>就難認識正路。<br/>',NULL,8871,8871);
INSERT INTO stanza VALUES('C324','6','對於你的旨意，<br/>我也不彀認識；<br/>多是己意充替，<br/>常是用腳踢刺。<br/>',NULL,8872,8872);
INSERT INTO stanza VALUES('C324','7','對於你的召會，<br/>我更需要啟示；<br/>使我知所向背，<br/>以你智慧為是。<br/>',NULL,8873,8873);
INSERT INTO stanza VALUES('C324','8','真願脫去遮蔽，<br/>各方都蒙光照；<br/>任何不再受欺，<br/>一切不再驕傲。<br/>',NULL,8874,8874);
INSERT INTO stanza VALUES('C325','1','當我憑著自己思想，<br/>我覺自己很是剛強，<br/>不知自己卻是怎樣<br/>沒有力量。<br/>',NULL,8875,8875);
INSERT INTO stanza VALUES('C325','2','當我生活世人中間，<br/>我就不覺自己虧欠，<br/>只覺自己如何奮勉，<br/>如何上前。<br/>',NULL,8876,8876);
INSERT INTO stanza VALUES('C325','3','當我住在黑暗裡面，<br/>我就不知自己膚淺，<br/>以為自己何等無限，<br/>不必虛謙。<br/>',NULL,8877,8877);
INSERT INTO stanza VALUES('C325','4','當我來到你的面前，<br/>亮光刺破遮蔽幕簾，<br/>我就看見前所未見，<br/>完全露現。<br/>',NULL,8878,8878);
INSERT INTO stanza VALUES('C325','5','在你面前我只萎縮，<br/>一切萎縮、一切消沒，<br/>所有驕傲都變軟弱，<br/>都變赤裸。<br/>',NULL,8879,8879);
INSERT INTO stanza VALUES('C325','6','沒有可驕，沒有可傲，<br/>沒有可倚，沒有可靠，<br/>只有自慚，只有自懊，<br/>能否禱告？<br/>',NULL,8880,8880);
INSERT INTO stanza VALUES('C325','7','幸有你血免我定罪，<br/>你的生命免我銷毀，<br/>但我真是何等污穢、<br/>何等慚愧。<br/>',NULL,8881,8881);
INSERT INTO stanza VALUES('C325','8','所有驕傲都是愚昧，<br/>看見實在何必謙卑，<br/>所有自恃都是因為<br/>心中墨黑。<br/>',NULL,8882,8882);
INSERT INTO stanza VALUES('C325','9','靜我也錯，動我也錯，<br/>不說不安，說又太過，<br/>都是失敗、都是軟弱、<br/>都是不妥。<br/>',NULL,8883,8883);
INSERT INTO stanza VALUES('C325','10','我要禱告，沒有信心；<br/>我要倚靠，如何求尋？<br/>不知如何方能重新…<br/>主阿，憐憫！<br/>',NULL,8884,8884);
INSERT INTO stanza VALUES('C326','1','求主光照、光照我，<br/>阿們！<br/>顯明、顯明我罪過，<br/>阿利路亞！<br/>用血洗濯，用血洗濯，<br/>使我污穢全消沒，<br/>阿們！<br/>',NULL,8885,8885);
INSERT INTO stanza VALUES('C326','2','求主釋放、釋放我，<br/>阿們！<br/>斷開、斷開我捆索，<br/>阿利路亞！<br/>敗壞鬼魔，敗壞鬼魔，<br/>使我自由而超脫，<br/>阿們！<br/>',NULL,8886,8886);
INSERT INTO stanza VALUES('C326','3','求主復興、復興我，<br/>阿們！<br/>消除、消除我軟弱，<br/>阿利路亞！<br/>挑旺愛火，挑旺愛火，<br/>使我完全為主活，<br/>阿們！<br/>',NULL,8887,8887);
INSERT INTO stanza VALUES('C327','1','求主潔淨我的靈，<br/>求主潔淨我的靈，<br/>求主潔淨我的靈，<br/>污穢除淨；<br/>潔淨我靈，污穢除淨，<br/>完全除淨。<br/>',NULL,8888,8888);
INSERT INTO stanza VALUES('C327','2','使我倒空我器皿，<br/>使我倒空我器皿，<br/>使我倒空我器皿，<br/>罪惡認清；<br/>倒空器皿，罪惡認清，<br/>徹底認清。<br/>',NULL,8889,8889);
INSERT INTO stanza VALUES('C327','3','求主充滿我的靈，<br/>求主充滿我的靈，<br/>求主充滿我的靈，<br/>使我復興；<br/>充滿我靈，使我復興，<br/>全人復興。<br/>',NULL,8890,8890);
INSERT INTO stanza VALUES('C328','1','主，你榮面是我所羨，<br/>開啟我眼使我看見；<br/>願你榮光照我眼前，<br/>消除我的一切黑暗。<br/>恩主，我今尋求你面，<br/>願你不再向我隱瞞；<br/>開啟我眼，使我看見<br/>你的榮面！<br/>',NULL,8891,8891);
INSERT INTO stanza VALUES('C328','2','主，你慈聲是我所羨，<br/>開啟我耳使我聽見；<br/>願你聲音繞我耳邊，<br/>消除惡者一切謊言。<br/>恩主，我今尋求你面，<br/>願你不再向我隱瞞；<br/>開啟我耳，使我聽見<br/>你的聖言！<br/>',NULL,8892,8892);
INSERT INTO stanza VALUES('C328','3','主，你自己是我所羨，<br/>開啟我心使我充滿；<br/>願你豐滿溢我心間，<br/>使我失去在你裡面。<br/>恩主，我今尋求你面，<br/>願你不再向我隱瞞；<br/>開啟我心，使我充滿<br/>你的恩典！<br/>',NULL,8893,8893);
INSERT INTO stanza VALUES('C329','1','有人已離主，別行他途，<br/>有人已溜出羊群保護，<br/>有人已動心貪愛世俗，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8894,8894);
INSERT INTO stanza VALUES('C329','chorus','主，是我否？<br/>此言猶如利刃刺入我心，<br/>刺入何等的深！<br/>若有一人要失去主的分，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8895,8895);
INSERT INTO stanza VALUES('C329','2','有人竟把主撇在背後，<br/>有人竟隨從惡人計謀，<br/>有人竟作到聖靈擔憂，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8896,8896);
INSERT INTO stanza VALUES('C329','3','有人竟甘心辜負主恩，<br/>有人竟甘心事奉瑪門，<br/>有人竟甘心罪中下沉，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8897,8897);
INSERT INTO stanza VALUES('C329','4','有人已否認救主耶穌，<br/>有人已使祂蒙受羞辱，<br/>有人已背叛，<br/>賣友、賣主，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8898,8898);
INSERT INTO stanza VALUES('C329','5','有人將被提到主面前，<br/>有人將享受安息甘甜，<br/>有人將得著生命冠冕，<br/>主，是我否？<br/>主，是我否？<br/>',NULL,8899,8899);
INSERT INTO stanza VALUES('C330','1','主愛長闊高深，<br/>實在不能推測；<br/>不然，像我這樣罪人，<br/>怎能滿被恩澤。<br/>',NULL,8900,8900);
INSERT INTO stanza VALUES('C330','2','我主出了重價，<br/>買我回來歸祂；<br/>我今願意背十字架，<br/>忠心一路跟祂。<br/>',NULL,8901,8901);
INSERT INTO stanza VALUES('C330','3','我今撇下一切，<br/>為要得著基督；<br/>生也、死也，想都不屑，<br/>有何使我回顧？<br/>',NULL,8902,8902);
INSERT INTO stanza VALUES('C330','4','親友、欲好、利名，<br/>於我夫復何用？<br/>恩主為我變作苦貧，<br/>我今為主亦窮。<br/>',NULL,8903,8903);
INSERT INTO stanza VALUES('C330','5','我愛我的救主，<br/>我求祂的稱是；<br/>為祂之故，安逸變苦，<br/>利益變為損失！<br/>',NULL,8904,8904);
INSERT INTO stanza VALUES('C330','6','你是我的安慰，<br/>我的恩主耶穌！<br/>除你之外，在天何歸？<br/>在地何所愛慕？<br/>',NULL,8905,8905);
INSERT INTO stanza VALUES('C330','7','艱苦、反對、飄零，<br/>我今一起不理；<br/>只求我主用你愛情，<br/>繞我靈、魂、身體。<br/>',NULL,8906,8906);
INSERT INTO stanza VALUES('C330','8','主阿，我今求你，<br/>施恩引導小子，<br/>立在我旁，常加我力，<br/>過此黑暗罪世。<br/>',NULL,8907,8907);
INSERT INTO stanza VALUES('C330','9','撒但、世界、肉體，<br/>時常試探、欺凌；<br/>你若不加小子能力，<br/>恐將貽羞你名！<br/>',NULL,8908,8908);
INSERT INTO stanza VALUES('C330','10','現今時候不多，<br/>求主使我脫塵；<br/>你一再來，我即唱說：<br/>阿利路亞！阿們！<br/>',NULL,8909,8909);
INSERT INTO stanza VALUES('C331','1','『為你，我流寶血，<br/>為你，我捨生命，<br/>將你洗得清潔，<br/>使你從死復生。<br/>為你，為你，捨生命，<br/>為我，你捨何情？<br/>',NULL,8910,8910);
INSERT INTO stanza VALUES('C331','2','為你，我費多年，<br/>來受勞苦災殃，<br/>好使歡樂永遠，<br/>你也得以安享。<br/>為你，為你，我費多年，<br/>為我，你費幾天？<br/>',NULL,8911,8911);
INSERT INTO stanza VALUES('C331','3','我父光明之家，<br/>我的榮耀寶座，<br/>為你，我都撇下，<br/>來到苦地飄泊。<br/>為你，為你，我撇這些，<br/>為我你何所撇？<br/>',NULL,8912,8912);
INSERT INTO stanza VALUES('C331','4','為你，我受多苦，<br/>過於你口能述，<br/>受了極大痛楚，<br/>救你脫離陰府。<br/>為你，為你，我受多苦，<br/>為我，你肯何負？<br/>',NULL,8913,8913);
INSERT INTO stanza VALUES('C331','5','從我天上之家，<br/>為你，我已帶來：<br/>救恩無以復加，<br/>赦免陪同慈愛。<br/>為你，為你，我帶許多，<br/>為我，你帶甚麼？』<br/>',NULL,8914,8914);
INSERT INTO stanza VALUES('C331','6','『主，我獻上生命，<br/>並獻所有時光，<br/>完全聽你使令，<br/>脫離地上捆綁。<br/>為我，為我，你的全捨，<br/>為你，我撇一切！』<br/>',NULL,8915,8915);
INSERT INTO stanza VALUES('C332','1','哦，那不肯放我之愛，<br/>我將疲魂安息於你；<br/>我把所欠餘生歸來，<br/>好使牠在你這深海，<br/>得更豐滿洋溢。<br/>',NULL,8916,8916);
INSERT INTO stanza VALUES('C332','2','哦，那照耀我路之光，<br/>我將殘燈帶來交你；<br/>我心因得你光復亮，<br/>牠的日子藉你太陽，<br/>得更光明美麗。<br/>',NULL,8917,8917);
INSERT INTO stanza VALUES('C332','3','哦，那苦中尋我之樂，<br/>我心不能向你關閉；<br/>我在雨中彩虹尋得，<br/>知你應許不會空說，<br/>天亮便無淚涕。<br/>',NULL,8918,8918);
INSERT INTO stanza VALUES('C332','4','哦，那使我抬頭十架，<br/>我不敢求與你稍離；<br/>今生虛榮死葬土下，<br/>那土長出生命紅花，<br/>永遠開放不已。<br/>',NULL,8919,8919);
INSERT INTO stanza VALUES('C333','1','你的靈豈非已見祂過？<br/>你的心曾否被祂所奪？<br/>你當認祂為人中第一人，<br/>歡喜選那上好的福分。<br/>',NULL,8920,8920);
INSERT INTO stanza VALUES('C333','chorus','你是千萬人中之第一人！<br/>哦，求你開我眼，<br/>並奪我心，<br/>摔碎眾偶像，<br/>並歡然加冠<br/>你為千萬人中之第一人！<br/>',NULL,8921,8921);
INSERT INTO stanza VALUES('C333','2','世界的一切虛榮、珍寶，<br/>盡都是偶像，使人顛倒；<br/>鍍過金，<br/>使人不容易淡泊，<br/>浸過蜜，使人真難超脫。<br/>',NULL,8922,8922);
INSERT INTO stanza VALUES('C333','3','甚麼會使地上的偶像，<br/>失去牠那美麗的模樣，<br/>並不是灰心、<br/>失望或勸勉，<br/>乃是『無價之寶』<br/>的一現！<br/>',NULL,8923,8923);
INSERT INTO stanza VALUES('C333','4','並不是甚麼本分催促，<br/>就會使偶像化成灰土；<br/>乃是祂榮耀美麗的傾投，<br/>並祂心裡柔愛的流露。<br/>',NULL,8924,8924);
INSERT INTO stanza VALUES('C333','5','有誰願熄滅他的燈光，<br/>若非早晨的日已在望？<br/>又有誰願意收藏他寒衣，<br/>若非炎夏的風已興起？<br/>',NULL,8925,8925);
INSERT INTO stanza VALUES('C333','6','惟有彼得所見的淚眼，<br/>司提反所仰望的榮臉，<br/>陪著馬利亞同哭的慈心，<br/>會使我脫離地的吸引。<br/>',NULL,8926,8926);
INSERT INTO stanza VALUES('C333','7','哦，求你來施情並吸引，<br/>直等到你充滿了這心；<br/>我們蒙救贖，<br/>是你的同伴，<br/>與偶像還有甚麼相干？<br/>',NULL,8927,8927);
INSERT INTO stanza VALUES('C334','1','絕對分別出來，<br/>歸於主聖靈！<br/>不惜任何代價，<br/>尋求祂豐盛；<br/>割斷所有岸索，<br/>開到水深處，<br/>得著祂的大能，<br/>帶進祂祝福。<br/>',NULL,8928,8928);
INSERT INTO stanza VALUES('C334','chorus','絕對分別出來，<br/>歸於萬有主，<br/>答應祂的呼召，<br/>尋求祂豐富。<br/>',NULL,8929,8929);
INSERT INTO stanza VALUES('C334','2','絕對分別出來，<br/>歸於主聖靈！<br/>沉沒還要沉沒，<br/>直到己去淨！<br/>直到器皿倒空，<br/>祂腳前破碎；<br/>等候直到充滿，<br/>流出主恩惠。<br/>',NULL,8930,8930);
INSERT INTO stanza VALUES('C334','3','絕對分別出來，<br/>歸於神旨意！<br/>走主所走道路，<br/>靠著祂恩力；<br/>撇棄安逸、享樂，<br/>隨主向前進；<br/>等候祂的引導，<br/>靜聽祂聲音。<br/>',NULL,8931,8931);
INSERT INTO stanza VALUES('C334','4','絕對分別出來！<br/>一直到永世；<br/>不要我的心意，<br/>乃要祂意旨；<br/>我的計畫、願望，<br/>在祂全滅沒；<br/>似乎一無所有，<br/>萬有實屬我。<br/>',NULL,8932,8932);
INSERT INTO stanza VALUES('C334','5','絕對分別出來！<br/>何等的甜美，<br/>作祂愛的俘虜，<br/>自由何寶貴；<br/>脫離罪的轄制、<br/>疑惑與恐懼，<br/>脫離所有重擔、<br/>憂愁和罣慮。<br/>',NULL,8933,8933);
INSERT INTO stanza VALUES('C334','6','絕對分別出來！<br/>何等的安息，<br/>在祂面前等候，<br/>照祂的心意；<br/>等候得著充滿，<br/>滿有祂聖靈，<br/>將我裡面各部<br/>完全都煉淨。<br/>',NULL,8934,8934);
INSERT INTO stanza VALUES('C334','7','祂靈將我充滿，<br/>帶著祂同在！<br/>在祂我蒙祝福，<br/>在祂我蒙愛！<br/>今後裡面亮光<br/>永不再變暗，<br/>如此向祂活著，<br/>分別到永遠。<br/>',NULL,8935,8935);
INSERT INTO stanza VALUES('C335','1','我已轉身背向俗世，<br/>和牠一切的歡娛；<br/>我已心向更美的事，<br/>就是天上的儲蓄；<br/>一切虛榮、一切揚顯，<br/>不能使我再逗遛；<br/>我已越過分別界線，<br/>世界已丟在背後。<br/>',NULL,8936,8936);
INSERT INTO stanza VALUES('C335','chorus','遠遠丟背後，<br/>遠遠丟背後，<br/>我已越過分別界線，<br/>世界已丟在背後。<br/>',NULL,8937,8937);
INSERT INTO stanza VALUES('C335','2','我已脫離罪的生活，<br/>棄絕所有的愚行；<br/>我已接受主的領率，<br/>願意聽祂的命令；<br/>我既靠主免為死囚，<br/>有主作我的元首；<br/>就願為祂捨去所有，<br/>世界已丟在背後。<br/>',NULL,8938,8938);
INSERT INTO stanza VALUES('C335','chorus','遠遠丟背後，<br/>遠遠丟背後，<br/>就願為祂捨去所有，<br/>世界已丟在背後。<br/>',NULL,8939,8939);
INSERT INTO stanza VALUES('C335','3','我今永遠不再返回<br/>舊日愚昧的境地；<br/>惟獨在此纔不定罪，<br/>在此纔會有安息；<br/>我今已經更換主人，<br/>對祂我要永伺候；<br/>地的捆綁就此脫盡，<br/>世界已丟在背後。<br/>',NULL,8940,8940);
INSERT INTO stanza VALUES('C335','chorus','遠遠丟背後，<br/>遠遠丟背後，<br/>地的捆綁就此脫盡，<br/>世界已丟在背後。<br/>',NULL,8941,8941);
INSERT INTO stanza VALUES('C335','4','我的前途，一定永定，<br/>我並不要別救主；<br/>我也不求更好福音，<br/>過於祂賜的寬恕；<br/>我心已經決定事神，<br/>無論如何不回頭；<br/>已往一切實為可恨，<br/>世界已丟在背後。<br/>',NULL,8942,8942);
INSERT INTO stanza VALUES('C335','chorus','遠遠丟背後，<br/>遠遠丟背後，<br/>已往一切實為可恨，<br/>世界已丟在背後。<br/>',NULL,8943,8943);
INSERT INTO stanza VALUES('C336','1','聖潔、歡樂，何等分別！<br/>惟有如此能蒙福；<br/>脫開主外一切事物，<br/>惟主是我所愛所慕，<br/>單單安息在基督，<br/>單單安息在基督。<br/>',NULL,8944,8944);
INSERT INTO stanza VALUES('C336','2','基督呼召，要我分別，<br/>祂已帶路如此行；<br/>祂的生活將此說明，<br/>祂的生活也是例證，<br/>誰願隨從祂帶領？<br/>誰願隨從祂帶領？<br/>',NULL,8945,8945);
INSERT INTO stanza VALUES('C336','3','恩主，求你使我願意<br/>出到營外歸於你，<br/>完全歸你，歡樂降服，<br/>忍受你所受的羞辱，<br/>完全歸你無所遺，<br/>完全歸你無所遺。<br/>',NULL,8946,8946);
INSERT INTO stanza VALUES('C336','4','分別！脫離憂你之事，<br/>分別！罪人也脫離；<br/>然而，像你關心罪人，<br/>並且像你擔負他們，<br/>跟隨你愛的蹤跡，<br/>跟隨你愛的蹤跡。<br/>',NULL,8947,8947);
INSERT INTO stanza VALUES('C336','5','完全歸你！心愛救主，<br/>願我與你無居間；<br/>完全歸你！奉獻徹底，<br/>完全歸你！分別至極，<br/>完全歸你到永遠！<br/>完全歸你到永遠！<br/>',NULL,8948,8948);
INSERT INTO stanza VALUES('C337','1','我將一切全獻基督，<br/>全獻恩主心甘願；<br/>我要永遠愛主，隨主，<br/>天天活在主面前。<br/>',NULL,8949,8949);
INSERT INTO stanza VALUES('C337','chorus','一切全奉獻！<br/>一切全奉獻！<br/>我的恩主，<br/>向你我願一切全奉獻！<br/>',NULL,8950,8950);
INSERT INTO stanza VALUES('C337','2','我將一切全獻基督，<br/>我今俯伏主腳前；<br/>今世福樂永不我屬，<br/>恩主，收我在今天。<br/>',NULL,8951,8951);
INSERT INTO stanza VALUES('C337','3','我將一切全獻基督，<br/>恩主，將我全得著。<br/>惟願聖靈從我證出：<br/>我是屬主，主屬我。<br/>',NULL,8952,8952);
INSERT INTO stanza VALUES('C337','4','我將一切全獻基督，<br/>主，我願作你器皿；<br/>恩惠、能力充我如注，<br/>顯明你生在我身。<br/>',NULL,8953,8953);
INSERT INTO stanza VALUES('C337','5','我將一切全獻基督，<br/>聖火已焚我心情；<br/>哦，這救恩甜美豐富，<br/>榮耀、榮耀歸主名。<br/>',NULL,8954,8954);
INSERT INTO stanza VALUES('C338','1','都歸基督，都歸基督，<br/>都歸基督理當然；<br/>我既是主寶血所贖，<br/>主就當得所有權。<br/>',NULL,8955,8955);
INSERT INTO stanza VALUES('C338','chorus','都歸基督，都歸基督，<br/>都歸基督我救主！<br/>都歸基督，都歸基督，<br/>都歸基督我救主！<br/>',NULL,8956,8956);
INSERT INTO stanza VALUES('C338','2','都歸基督，都歸基督，<br/>都歸基督心所慕；<br/>主愛激勵，主愛催促，<br/>怎能不都歸救主？<br/>',NULL,8957,8957);
INSERT INTO stanza VALUES('C338','3','都歸基督，都歸基督，<br/>都歸基督成為聖：<br/>身體、靈、魂、<br/>時間、財物、<br/>所是、所有並所能。<br/>',NULL,8958,8958);
INSERT INTO stanza VALUES('C338','4','願我雙手歸主使用，<br/>願我兩腳跟主行，<br/>願我雙目瞻主聖容，<br/>願我兩脣頌主名。<br/>',NULL,8959,8959);
INSERT INTO stanza VALUES('C338','5','自從我眼注視基督，<br/>所有事物全變色；<br/>一望主在十架受苦，<br/>我就甘願負主軛。<br/>',NULL,8960,8960);
INSERT INTO stanza VALUES('C338','6','奇妙恩典，深高闊長！<br/>我口歌頌，心感戴；<br/>榮耀救主，王中之王，<br/>竟然看我可寶愛！<br/>',NULL,8961,8961);
INSERT INTO stanza VALUES('C339','1','主，你得著我一生，<br/>使牠歸你成為聖；<br/>得著我日與我時，<br/>歸你使用永無止。<br/>',NULL,8962,8962);
INSERT INTO stanza VALUES('C339','chorus','為我荊棘冠冕你肯戴，<br/>為我釘死苦架你受害；<br/>為你我願獻上<br/>我命與我愛，<br/>事你、愛你到萬代。<br/>',NULL,8963,8963);
INSERT INTO stanza VALUES('C339','2','得著我手與我足，<br/>勤作你工，奔你路；<br/>得著我口與我舌，<br/>傳揚你話，頌你德。<br/>',NULL,8964,8964);
INSERT INTO stanza VALUES('C339','3','得著我金與我銀，<br/>分文不由我留存；<br/>得著我才與我智，<br/>運用全照你指示。<br/>',NULL,8965,8965);
INSERT INTO stanza VALUES('C339','4','得著我心與我意，<br/>全歸於你不他依；<br/>得著我愛與我情，<br/>全注於你不別傾。<br/>',NULL,8966,8966);
INSERT INTO stanza VALUES('C339','5','主，你得著我一切，<br/>我願與你永聯結，<br/>愛你、念你、事奉你，<br/>永遠失去在你裡。<br/>',NULL,8967,8967);
INSERT INTO stanza VALUES('C340','1','完全的交出，主，<br/>我今願完全的交出，<br/>交在你前。<br/>所有擺在祭壇，<br/>所有全都奉獻，<br/>你已贖我罪愆，<br/>我今歸你。<br/>',NULL,8968,8968);
INSERT INTO stanza VALUES('C340','2','完全的交出－生命、一切，<br/>凡你賜我的，全都不缺。<br/>求你向我發言，<br/>我願跟隨不偏，<br/>從今直到永遠，<br/>順服我主。<br/>',NULL,8969,8969);
INSERT INTO stanza VALUES('C340','3','完全的交出－金、銀、財物；<br/>你所賜我的，何其豐富。<br/>全願向你交出，<br/>因你是我買主，<br/>理當全都你屬，<br/>耶穌我主。<br/>',NULL,8970,8970);
INSERT INTO stanza VALUES('C340','4','完全的交出－我屬基督；<br/>完全的交出，我的救主；<br/>從我活出你命，<br/>在你有神豐盛，<br/>非我，惟你得勝，<br/>一切的主。<br/>',NULL,8971,8971);
INSERT INTO stanza VALUES('C341','1','勿對我談屬地享樂，<br/>勿用鄙利引誘我；<br/>勿愚我以地上幻影，<br/>勿用虛榮煩擾我。<br/>我已棄絕化裝偶像，<br/>今後不再屬自己；<br/>我已將心獻給基督，<br/>我願屬祂無所遺。<br/>',NULL,8972,8972);
INSERT INTO stanza VALUES('C341','chorus','我不屬自己，<br/>我不屬自己，<br/>我今屬於基督，<br/>不再屬於自己。<br/>',NULL,8973,8973);
INSERT INTO stanza VALUES('C341','2','哦，只屬於我主基督，<br/>帶來何等的安息！<br/>當我所有全都不留，<br/>祂的豐盛我能倚。<br/>榮耀恩主，將我接收，<br/>使我完全屬於你，<br/>適合享受你作我分，<br/>當我喜歡成你的。<br/>',NULL,8974,8974);
INSERT INTO stanza VALUES('C341','3','疲倦人哪，放棄掙扎，<br/>永勿再屬你自己；<br/>將你自己全給基督，<br/>全然屬祂無所遺。<br/>祂曾捨己為要得你，<br/>今來要你全歸祂；<br/>凡祂所有都已給你，<br/>你就不該不給祂。<br/>',NULL,8975,8975);
INSERT INTO stanza VALUES('C342','1','活著為耶穌，<br/>只望能單純，<br/>所有的一切都求祂喜悅，<br/>自動並樂意來向祂投順，<br/>這是我蒙神賜福的祕訣。<br/>',NULL,8976,8976);
INSERT INTO stanza VALUES('C342','chorus','耶穌我主，我救主，<br/>我將自己給你，<br/>因你為我代死時，<br/>給的是你自己；<br/>從此，我無別的主，<br/>我心是你寶座，<br/>我的一生一世，基督，<br/>只要為你生活。<br/>',NULL,8977,8977);
INSERT INTO stanza VALUES('C342','2','活著為耶穌，<br/>祂為我緣故，<br/>在十字架上擔當罪與羞；<br/>這愛激勵我答應祂招呼，<br/>恭敬向著祂奉獻我所有。<br/>',NULL,8978,8978);
INSERT INTO stanza VALUES('C342','3','活著為耶穌，<br/>無論在何處，<br/>我為祂緣故，<br/>作成祂事務，<br/>甘願來承受損失或痛苦，<br/>看每個試煉是十架一部。<br/>',NULL,8979,8979);
INSERT INTO stanza VALUES('C342','4','活著為耶穌，<br/>時間已短促，<br/>祂的笑臉是我寶貴祕密，<br/>尋找失喪者，<br/>祂死所救贖，<br/>帶領疲倦者，<br/>享受祂安息。<br/>',NULL,8980,8980);
INSERT INTO stanza VALUES('C343','1','不是掙扎，乃是歸依，<br/>會使我得力；<br/>掙扎不會使我得益，<br/>歸依纔安息。<br/>',NULL,8981,8981);
INSERT INTO stanza VALUES('C343','2','我若不作無謂奮勉，<br/>並不再努力，<br/>沒有條件完全奉獻，<br/>會得神安息。<br/>',NULL,8982,8982);
INSERT INTO stanza VALUES('C343','3','我的全量都靠耶穌，<br/>惟祂能拯救；<br/>因祂的愛，我樂為奴，<br/>不願再自由。<br/>',NULL,8983,8983);
INSERT INTO stanza VALUES('C343','4','順服，我就真能得勢，<br/>死，我就得生；<br/>『不是我意，<br/>乃是你旨，』<br/>會使我得勝。<br/>',NULL,8984,8984);
INSERT INTO stanza VALUES('C344','1','照你企圖，主，<br/>照你企圖，<br/>因你是陶人，我是泥土：<br/>製造又甄陶，照你美意；<br/>降服且等候，使我歸依。<br/>',NULL,8985,8985);
INSERT INTO stanza VALUES('C344','2','照你企圖，主，<br/>照你企圖，<br/>我在你面前謙卑俯伏：<br/>鑒察又試煉，顯我真情；<br/>修理且洗滌，使我純淨。<br/>',NULL,8986,8986);
INSERT INTO stanza VALUES('C344','3','照你企圖，主，<br/>照你企圖，<br/>完全脫自己，是我所慕：<br/>破碎又剝奪，使我成零；<br/>挖透且倒空，使我無剩。<br/>',NULL,8987,8987);
INSERT INTO stanza VALUES('C344','4','照你企圖，主，<br/>照你企圖，<br/>深願我全人向你降服：<br/>聖靈充滿我，流露你命；<br/>基督活於我，彰顯你形。<br/>',NULL,8988,8988);
INSERT INTO stanza VALUES('C345','1','我當如何愛我的主？<br/>如何奉獻使祂歡喜？<br/>不稍離開祂的道路，<br/>學習如何與祂親密？<br/>',NULL,8989,8989);
INSERT INTO stanza VALUES('C345','2','我的途徑若是痛苦，<br/>主，我求你，禁我退縮，<br/>使我仍然向你順服，<br/>追憶你的十架重負。<br/>',NULL,8990,8990);
INSERT INTO stanza VALUES('C345','3','讓我思念，你曾如何<br/>離開許多純潔樂事，<br/>來憂、來餓、<br/>來倦、來渴，<br/>無家之夜，不息之日。<br/>',NULL,8991,8991);
INSERT INTO stanza VALUES('C345','4','為我來憂、來倦、來死，<br/>你來不求自己喜悅；<br/>地上安逸雖難恝置，<br/>我豈愛你不勝這些？<br/>',NULL,8992,8992);
INSERT INTO stanza VALUES('C345','5','是的，我算萬事為損，<br/>為要來得你的注意；<br/>丟棄萬事雖如土糞，<br/>為著愛你有何可惜？<br/>第四節的『恝置，』意思是淡然置之。<br/>',NULL,8993,8993);
INSERT INTO stanza VALUES('C346','1','我今願跟隨耶穌，<br/>不論走何路：<br/>或是平坦大路，<br/>或是崎嶇窄途；<br/>既有救主親自相輔，<br/>我就不躊躇，<br/>一路跟隨耶穌，<br/>直到進國度。<br/>',NULL,8994,8994);
INSERT INTO stanza VALUES('C346','chorus','跟隨！跟隨！<br/>我願跟隨耶穌！<br/>不論福，不論苦，<br/>我必跟隨主！<br/>跟隨！跟隨！<br/>我願跟隨耶穌！<br/>不論領我何處，<br/>我必跟隨主！<br/>',NULL,8995,8995);
INSERT INTO stanza VALUES('C346','2','我今願跟隨耶穌，<br/>不論在何處：<br/>或在明媚樂土，<br/>或在死蔭幽谷；<br/>既有救主親自照護，<br/>我就不感苦；<br/>處處跟隨耶穌，<br/>直到末一步。<br/>',NULL,8996,8996);
INSERT INTO stanza VALUES('C346','3','我今願跟隨耶穌，<br/>不論時何如：<br/>或是陽光滿目，<br/>或是黑雲密佈；<br/>既有救主親自部署，<br/>我就無所顧；<br/>時時跟隨耶穌，<br/>一直到天曙。<br/>',NULL,8997,8997);
INSERT INTO stanza VALUES('C347','1','主，我今背十架，<br/>前來跟隨你；<br/>浮名利、虛榮華，<br/>一概都捨棄；<br/>人譏笑，人辱罵，<br/>我全不在意；<br/>雖受苦，雖受壓，<br/>窄路不稍離；<br/>靠主恩，遵主話，<br/>忠心直到底；<br/>到那日，蒙主誇，<br/>冠冕榮無比；<br/>冠冕榮無比，<br/>冠冕榮無比。<br/>',NULL,8998,8998);
INSERT INTO stanza VALUES('C348','1','我今撇下一切事物，<br/>背起十架跟耶穌；<br/>甘受藐視、厭棄、貧苦，<br/>一心跟主走窄路。<br/>前我所愛、所慕、所求，<br/>今與雄心同歸盡；<br/>但我又是何等饒優，<br/>神與基督是我分。<br/>',NULL,8999,8999);
INSERT INTO stanza VALUES('C348','2','讓這世界棄我、嫌我，<br/>恩主也曾被棄嫌；<br/>人面、人心，<br/>欺我、騙我，<br/>惟你永遠不欺騙。<br/>當你向我顯出笑臉，<br/>友雖生疏敵雖險，<br/>但我心安，處之泰然，<br/>因我得見你歡顏。<br/>',NULL,9000,9000);
INSERT INTO stanza VALUES('C348','3','去罷！今世名利福樂，<br/>來罷！痛苦和嘲譏；<br/>為主活著苦是喜樂，<br/>有主喜悅損是益。<br/>我既稱祂阿爸父親，<br/>我既將心注於你；<br/>怒吼暴風、密集厚雲，<br/>都該效力成我益。<br/>',NULL,9001,9001);
INSERT INTO stanza VALUES('C348','4','人雖逼我使我苦痛，<br/>不過驅我到你前；<br/>世間苦難壓我越重，<br/>天上平安越甘甜。<br/>有何憂苦能將我襲，<br/>當你榮面向我顯？<br/>有何快樂能將我迷，<br/>若你不在牠裡面？<br/>',NULL,9002,9002);
INSERT INTO stanza VALUES('C348','5','向前！由恩進入榮耀，<br/>信當籐牌，求當翼；<br/>永世日子就要破曉，<br/>主必領我直到底。<br/>地上職事就要停止，<br/>作客旅程就要完，<br/>盼望就要變成事實，<br/>信變眼見，求變讚。<br/>',NULL,9003,9003);
INSERT INTO stanza VALUES('C349','1','眾人湧進主的國度，<br/>十架少人負；<br/>眾人爭奪主的賞賜，<br/>世界有誰辭？<br/>人雖無心走主道路，<br/>仍想主祝福！<br/>人雖無心走主道路，<br/>仍想主祝福！<br/>',NULL,9004,9004);
INSERT INTO stanza VALUES('C349','2','眾人都慕得主榮耀，<br/>羞辱少人要；<br/>眾人都愛同主掌權，<br/>損失有誰願？<br/>幾乎無人因主緣故，<br/>看萬事如土！<br/>',NULL,9005,9005);
INSERT INTO stanza VALUES('C349','3','多人都貪享主甘旨，<br/>少有願禁食！<br/>多人都喜登主寶座，<br/>少有願飄泊！<br/>同祂唱詩雖然有人，<br/>儆醒卻不能。<br/>',NULL,9006,9006);
INSERT INTO stanza VALUES('C349','4','眾人都想同主高貴，<br/>卑賤卻都畏。<br/>當主凡事為他豫備，<br/>他就大讚美；<br/>當主稍微求他一點，<br/>就立發怨言。<br/>',NULL,9007,9007);
INSERT INTO stanza VALUES('C349','5','但那誠實愛主的人，<br/>禍福都不問，<br/>就是他們寶貴心血，<br/>也願為主捨；<br/>求主給我這樣心志，<br/>赤忠忘生死。<br/>',NULL,9008,9008);
INSERT INTO stanza VALUES('C350','1','誰是在主這邊？<br/>誰要跟隨主？<br/>誰要為主活著，<br/>走祂的道路？<br/>誰要撇開世界，<br/>去為主爭戰？<br/>誰是在主這邊，<br/>跟隨主向前？<br/>',NULL,9009,9009);
INSERT INTO stanza VALUES('C350','chorus','藉著你的救贖，<br/>並藉你恩典，<br/>可愛、榮耀救主，<br/>我在你這邊。<br/>',NULL,9010,9010);
INSERT INTO stanza VALUES('C350','2','參加主的軍隊，<br/>歡樂去爭戰，<br/>不是為著榮耀，<br/>不是為冠冕；<br/>乃是因著主愛<br/>激勵我向前；<br/>我既蒙祂恩待，<br/>該在祂這邊。<br/>',NULL,9011,9011);
INSERT INTO stanza VALUES('C350','3','你已將我救贖，<br/>作你的子民，<br/>乃是用你寶血，<br/>不是用金銀；<br/>凡來跟從你者，<br/>得福都無限；<br/>你使我們甘願<br/>且自由向前。<br/>',NULL,9012,9012);
INSERT INTO stanza VALUES('C350','4','戰爭雖會兇猛，<br/>仇敵也強悍；<br/>但是主的軍隊，<br/>無人能擊散。<br/>在祂大纛之下，<br/>必定能得勝，<br/>因祂真實、不變，<br/>奏凱已確定。<br/>',NULL,9013,9013);
INSERT INTO stanza VALUES('C350','5','蒙主選為兵丁，<br/>在今世爭戰，<br/>我當完全忠心，<br/>隨元帥向前；<br/>如此服事我王，<br/>切勿變冷淡，<br/>守住高貴身位，<br/>忠貞又勇敢。<br/>',NULL,9014,9014);
INSERT INTO stanza VALUES('C351','1','我是否要背負十架，<br/>跟從神的羔羊？<br/>我豈可以怕出代價，<br/>要得世界原諒？<br/>',NULL,9015,9015);
INSERT INTO stanza VALUES('C351','chorus','因你名，寶貴的名，<br/>因你為我捨命，<br/>靠恩，無論如何艱難，<br/>我要求你喜歡。<br/>',NULL,9016,9016);
INSERT INTO stanza VALUES('C351','2','別人苦戰要得榮耀，<br/>血汗滿被沙場；<br/>我豈可以安坐花轎，<br/>盼望抬到天上？<br/>',NULL,9017,9017);
INSERT INTO stanza VALUES('C351','3','難道我無仇敵當拒？<br/>我無破口當堵？<br/>難道俗世也可相與？<br/>也可作我幫助？<br/>',NULL,9018,9018);
INSERT INTO stanza VALUES('C351','4','我要掌權，就得爭戰，<br/>哦主，加我力量；<br/>我願受辱，我不畏難，<br/>靠你話語剛強。<br/>',NULL,9019,9019);
INSERT INTO stanza VALUES('C352','1','我們雖然時常搖動，<br/>但祂依然歷久不變；<br/>祂的應許無一落空，<br/>天地沒有那樣貞堅。<br/>',NULL,9020,9020);
INSERT INTO stanza VALUES('C352','2','我們雖然二三其心，<br/>但祂不肯撇棄我們；<br/>雖受冷落，仍要親近，<br/>地上朋友無祂這真！<br/>',NULL,9021,9021);
INSERT INTO stanza VALUES('C352','3','祂永不肯辜負我們，<br/>所有信託祂都盡力；<br/>因為祂既愛了我們，<br/>就愛我們一直到底。<br/>',NULL,9022,9022);
INSERT INTO stanza VALUES('C352','4','到底！我們對祂無良，<br/>忘祂，傷祂，暗中心變；<br/>祂外，我們另事偶像，<br/>心裡也不抱歉半點！<br/>',NULL,9023,9023);
INSERT INTO stanza VALUES('C352','5','到這偶像傾倒絕跡，<br/>不禁悲傷，又來尋求<br/>我們從前所辜負的，<br/>這位始終如一的友！<br/>',NULL,9024,9024);
INSERT INTO stanza VALUES('C352','6','祂又收留安慰我們，<br/>並引我們親近自己，<br/>一若毫無其事發生，<br/>並愛我們一直到底。<br/>',NULL,9025,9025);
INSERT INTO stanza VALUES('C352','7','哦主，我們對著這愛，<br/>不能不發高聲讚美；<br/>比死堅強，比水忍耐，<br/>我們心融，只有感佩。<br/>',NULL,9026,9026);
INSERT INTO stanza VALUES('C353','1','從前我亦曾熱心，<br/>多努力，求上進，<br/>可憐現在已改變，<br/>不與救主親近；<br/>追想昔日殷勤景，<br/>深夜寐，清晨興，<br/>如何辛苦不自顧，<br/>而今卻冷如冰！<br/>',NULL,9027,9027);
INSERT INTO stanza VALUES('C353','chorus','我豈能忘救主？<br/>我豈可離天父？<br/>祂心為我憂傷，<br/>我心安忍不顧？<br/>',NULL,9028,9028);
INSERT INTO stanza VALUES('C353','2','從前我已獻全身，<br/>雖勞碌，不為金，<br/>而今卻為世俗用，<br/>卻隨世界浮沉！<br/>從前守節今流連，<br/>是放縱，說消遣！<br/>多年流浪不懊悔，<br/>何日纔會生厭？<br/>',NULL,9029,9029);
INSERT INTO stanza VALUES('C353','3','從前我心專愛主，<br/>在祂外，無所慕，<br/>時常想念熱如火，<br/>無論夢寐醒蘇，<br/>世俗、人情皆無意，<br/>一切事都丟棄，<br/>今則追求屬地物，<br/>與俗復有何異？<br/>',NULL,9030,9030);
INSERT INTO stanza VALUES('C353','4','追想昔日跪主前，<br/>何滿足，何甘甜，<br/>應許你說：『從今後，<br/>我只聽你差遣，<br/>願意順服失自由，<br/>在你外，無他求；』<br/>至今為時並不久，<br/>此心已歸烏有！<br/>',NULL,9031,9031);
INSERT INTO stanza VALUES('C353','5','你外勞碌總是空，<br/>如捉影，如捕風，<br/>多年流落羊群外，<br/>無你怎能亨通；<br/>世界情慾快過去，<br/>豈可再受駕御？<br/>愛主多年在等候，<br/>豈可依然猶豫？<br/>',NULL,9032,9032);
INSERT INTO stanza VALUES('C353','6','晨星將現夜已闌，<br/>生越過，時越暫，<br/>立即脫離墮落處，<br/>重來求你喜歡；<br/>拒絕世俗和魔鬼，<br/>再來嘗天滋味，<br/>愛心已失今再得，<br/>仍站從前地位。<br/>',NULL,9033,9033);
INSERT INTO stanza VALUES('C353','chorus','我今再行窄路，<br/>虛空世界不顧；<br/>前面榮耀快現，<br/>我願忠心受苦。<br/>',NULL,9034,9034);
INSERT INTO stanza VALUES('C354','1','我豈可再冷淡退後，<br/>使神聖靈終日擔憂，<br/>恩主也在等候！<br/>我今願意轉身回頭，<br/>不再留戀，不再逗遛，<br/>就此跟主而走！<br/>',NULL,9035,9035);
INSERT INTO stanza VALUES('C354','2','我今將我所是所有，<br/>完全奉獻，一無保留，<br/>從今直到永久；<br/>惟願恩主悅納、保守，<br/>使我今後無望、無求，<br/>惟願父旨成就。<br/>',NULL,9036,9036);
INSERT INTO stanza VALUES('C354','3','回顧已往，又慚、又羞，<br/>無一靈魂是我所救－救恩被我全扣；<br/>今求恩主用祂膏油，<br/>將我全人厚厚澆透，<br/>使成救恩出口。<br/>',NULL,9037,9037);
INSERT INTO stanza VALUES('C354','4','恩主一向施恩深厚，<br/>待我遠勝知己愛友，<br/>竟以我作配偶。<br/>祂的生命我當倚投，<br/>祂的苦難我該接受，<br/>將祂生命流露。<br/>',NULL,9038,9038);
INSERT INTO stanza VALUES('C355','1','當人棄絕地的賄賂，<br/>前來為神而活，<br/>他所得的無限富有，<br/>口舌難以述說。<br/>因為萬有全是他的，<br/>生、死、或是事、物；<br/>基督是他生命、呼吸，<br/>也是他的住處。<br/>',NULL,9039,9039);
INSERT INTO stanza VALUES('C355','2','像我這人，王肯選上，<br/>有分祂的寶座，<br/>而我竟然不肯應選，<br/>這是何其奇特！<br/>永遠勿說這是犧牲！<br/>無論代價若干，<br/>只要能入加略聖軍，<br/>權利都是難言。<br/>',NULL,9040,9040);
INSERT INTO stanza VALUES('C355','3','起來！將這交易算看：<br/>零碎換來整個－萬事、萬物、加上萬人，<br/>竟都歸你得著。<br/>當你屬祂，萬有屬你，<br/>並且祂你合一；<br/>你還得享無限生命，<br/>權益有何能比！<br/>',NULL,9041,9041);
INSERT INTO stanza VALUES('C356','1','與你合一，永遠之子，<br/>因信與你成一靈，<br/>得你包羅萬有的死，<br/>和非受造的生命。<br/>與你合一，蒙愛之子，<br/>藉恩成為你一部，<br/>與你同為父的後嗣，<br/>並作聖靈的房屋。<br/>',NULL,9042,9042);
INSERT INTO stanza VALUES('C356','2','與你合一，化身之子，<br/>作你奧祕的肢體，<br/>因你誕生與你連枝，<br/>與你一同客此地。<br/>與你合一，受膏之子，<br/>同得聖靈的能力，<br/>日復一日，時復一時，<br/>與你合作不稍離。<br/>',NULL,9043,9043);
INSERT INTO stanza VALUES('C356','3','與你合一，被棄之子，<br/>經過審判和咒詛，<br/>永遠同你向罪而死，<br/>並勝兇惡的陰府。<br/>與你合一，復活之子，<br/>脫離墳墓的埋沒，<br/>因你更生，同你更始，<br/>靠你逐日結義果。<br/>',NULL,9044,9044);
INSERT INTO stanza VALUES('C356','4','與你合一，升天之子，<br/>同登寶座來管治，<br/>你的權柄我也掌執，<br/>因我和你同位置。<br/>與你合一，再來之子，<br/>同得榮耀同臨世，<br/>那時都要顯你殊姿，<br/>與你合一無已時。<br/>',NULL,9045,9045);
INSERT INTO stanza VALUES('C357','1','聯於基督得勝的主，<br/>並祂十架工夫；<br/>我處艱難仍覺穩固，<br/>因祂必定扶助。<br/>',NULL,9046,9046);
INSERT INTO stanza VALUES('C357','2','聯於基督復活的主，<br/>現今居於天府，<br/>十架光榮，立時彰顯<br/>無限希奇恩典。<br/>',NULL,9047,9047);
INSERT INTO stanza VALUES('C357','3','聯於基督完全得勝，<br/>我靈立即飛騰；<br/>靠主聖名我一宣告，<br/>黑暗權勢即逃。<br/>',NULL,9048,9048);
INSERT INTO stanza VALUES('C357','4','復活基督，你真莊嚴！<br/>願我與你相聯；<br/>你十字架時常得勝，<br/>敗壞撒但兇橫。<br/>',NULL,9049,9049);
INSERT INTO stanza VALUES('C357','5','聯於基督何等尊大！<br/>這是神的救法，<br/>這叫我們永遠讚美，<br/>因為羔羊真配。<br/>',NULL,9050,9050);
INSERT INTO stanza VALUES('C358','1','今在基督何奇妙，<br/>所得地位真高尚！<br/>藉恩得救何榮耀，<br/>竟然能與祂一樣。<br/>將來同祂顯現時，<br/>我必與祂全相像；<br/>但今與祂行於此，<br/>我就能與祂一樣。<br/>',NULL,9051,9051);
INSERT INTO stanza VALUES('C358','chorus','與祂一樣，與祂一樣，<br/>何等奇妙，與祂一樣；<br/>主的奇恩臨到我身上，<br/>使我與祂合一且一樣。<br/>',NULL,9052,9052);
INSERT INTO stanza VALUES('C358','2','合一與祂同釘死，<br/>合一與祂同復活；<br/>咒詛之下得開釋，<br/>現今與祂同活著。<br/>合一與祂同升天，<br/>合一與祂同名分；<br/>如妻與夫之相聯，<br/>像枝與樹同一身。<br/>',NULL,9053,9053);
INSERT INTO stanza VALUES('C358','3','合一與祂同功績，<br/>合一與祂同祈求，<br/>凡祂價值的效力，<br/>因信全歸我享受。<br/>合一與祂同信、愛，<br/>合一與祂同生命，<br/>有祂聖靈常同在，<br/>與祂一樣成為聖。<br/>',NULL,9054,9054);
INSERT INTO stanza VALUES('C359','1','與你合一，恩主耶穌，<br/>與你合一在靈裡；<br/>凡你所是都活我裡，<br/>我今得享你自己。<br/>',NULL,9055,9055);
INSERT INTO stanza VALUES('C359','chorus','合為一，合為一，<br/>我與你合為一；<br/>你的豐富是我供給，<br/>我的一切全是你。<br/>',NULL,9056,9056);
INSERT INTO stanza VALUES('C359','2','今享你的屬人生命，<br/>豐滿有你的人性，<br/>所有你的為人生活，<br/>都能用於我人生。<br/>',NULL,9057,9057);
INSERT INTO stanza VALUES('C359','3','與你合一，在十架上，<br/>在你裡面我已死；<br/>我向世界已經死了，<br/>世界向我也如此。<br/>',NULL,9058,9058);
INSERT INTO stanza VALUES('C359','4','與你合一，在復活裡，<br/>現今與你同活著；<br/>復活生命－你的自己－在我裡面供應我。<br/>',NULL,9059,9059);
INSERT INTO stanza VALUES('C359','5','與你合一，在升天裡，<br/>現今同你坐天上；<br/>在這地上乃是旅客，<br/>我的真命在你藏。<br/>',NULL,9060,9060);
INSERT INTO stanza VALUES('C359','6','與你合一，在寶座上，<br/>有分於你的權柄，<br/>如同有分於你生命，<br/>同一性情，同一靈。<br/>',NULL,9061,9061);
INSERT INTO stanza VALUES('C360','1','哦，各各他！<br/>好，各各他！<br/>我主在此受死；<br/>祂流寶血，祂釘苦架，<br/>使我從罪得釋。<br/>',NULL,9062,9062);
INSERT INTO stanza VALUES('C360','chorus','因此，切求我主，<br/>啟示各各他的奧祕，<br/>使我知道，<br/>現在我是與祂合而為一。<br/>',NULL,9063,9063);
INSERT INTO stanza VALUES('C360','2','哦，各各他！<br/>好，各各他！<br/>在此我同主死：<br/>藉著與主同釘十架，<br/>我的重負得釋。<br/>',NULL,9064,9064);
INSERT INTO stanza VALUES('C360','3','哦，各各他！<br/>主的空墳<br/>也曾把我埋過；<br/>主的復甦我也有分，<br/>因此我能生活。<br/>',NULL,9065,9065);
INSERT INTO stanza VALUES('C360','4','哦，各各他！<br/>撒但全軍<br/>在此被主羞辱；<br/>奉著主名，邪靈、魔君，<br/>向我也當俯伏。<br/>',NULL,9066,9066);
INSERT INTO stanza VALUES('C360','5','哦，各各他！<br/>我有主名，<br/>在爭戰時已足；<br/>仇敵一聽，立即亡命，<br/>不能抵擋我主。<br/>',NULL,9067,9067);
INSERT INTO stanza VALUES('C360','6','哦，各各他！<br/>我讚美主！<br/>因祂在此受死，<br/>捨了祂命，贖我罪辜，<br/>使我捆綁全失。<br/>',NULL,9068,9068);
INSERT INTO stanza VALUES('C360','7','哦，各各他！<br/>我願學習<br/>你的所有意義！<br/>我今因信，在得勝地，<br/>與主一同站立。<br/>',NULL,9069,9069);
INSERT INTO stanza VALUES('C361','1','主，你啟示一個奧祕，<br/>就是我同你死的理，<br/>不用別法，不用別能，<br/>我就看見完全得勝。<br/>',NULL,9070,9070);
INSERT INTO stanza VALUES('C361','2','你的十架就是我的，<br/>其光照耀我生命裡；<br/>一信與你同釘那裡，<br/>世界失去牠的能力。<br/>',NULL,9071,9071);
INSERT INTO stanza VALUES('C361','3','我既與你十架同釘，<br/>勝過罪惡、自己、人情，<br/>就怎能尚追求地物？<br/>就怎能再盼望世福？<br/>',NULL,9072,9072);
INSERT INTO stanza VALUES('C361','4','因此，我便到你那裡，<br/>與你同站十架死地，<br/>你命、你權，全是我的，<br/>因我與你合而為一。<br/>',NULL,9073,9073);
INSERT INTO stanza VALUES('C361','5','你既是來敗壞撒但<br/>一切作為、勢力、死權，<br/>我自然可和你同勝，<br/>天天經歷你的大能。<br/>',NULL,9074,9074);
INSERT INTO stanza VALUES('C361','6','但是我主，我們只能<br/>靠著你的十架得勝；<br/>你走的路，我們當走，<br/>直到與你見面時候。<br/>',NULL,9075,9075);
INSERT INTO stanza VALUES('C361','7','我今接受你的同釘，<br/>求你所賜永遠的靈<br/>使我更懂你死意義，<br/>使我脫離罪、己、肉體。<br/>',NULL,9076,9076);
INSERT INTO stanza VALUES('C361','8','我願得勝像你得勝！<br/>與你同王，同得權能！<br/>背負十架，我們若肯，<br/>這些榮耀必定有分！<br/>',NULL,9077,9077);
INSERT INTO stanza VALUES('C362','1','我已與基督同釘死，<br/>脫自己、罪惡、俗世；<br/>所以我能平安接領<br/>主從死得生的命。<br/>我甘願和祂同受苦，<br/>效法祂至死順服；<br/>我願跟主耶穌基督<br/>直走十字架的路。<br/>',NULL,9078,9078);
INSERT INTO stanza VALUES('C362','chorus','一直走十架窄路！<br/>主是受死在那裡！<br/>求主使我能同你<br/>一直走十架窄路！<br/>',NULL,9079,9079);
INSERT INTO stanza VALUES('C362','2','我何難與基督同死，<br/>因復活我已認識；<br/>我何難與耶穌同苦，<br/>因神旨我願順服。<br/>主藉著復活的能力，<br/>今生在我的靈裡，<br/>因此我歡樂著舉足，<br/>直走十字架的路。<br/>',NULL,9080,9080);
INSERT INTO stanza VALUES('C362','3','同主死，就必同主生，<br/>同受苦，必同高升；<br/>得勝者惟獨照這樣，<br/>纔能蒙基督獎賞。<br/>真可樂！若在那早晨，<br/>你聽主對你發聲，<br/>以為你曾忠心順服，<br/>直走十字架的路！<br/>',NULL,9081,9081);
INSERT INTO stanza VALUES('C363','1','與基督同死，<br/>祂死算我死；<br/>與基督同起，<br/>我有祂生命；<br/>與基督同升，<br/>我超過此世；<br/>主，時時刻刻，<br/>我歸於你名。<br/>',NULL,9082,9082);
INSERT INTO stanza VALUES('C363','chorus','我時時刻刻蒙祂愛保守，<br/>我時時刻刻從祂得生命，<br/>我時時刻刻在祂前等候，<br/>我時時刻刻歸於祂的名。<br/>',NULL,9083,9083);
INSERT INTO stanza VALUES('C363','2','沒有一試煉，<br/>祂是不同在；<br/>沒有一重擔，<br/>祂是不與共；<br/>沒有一痛苦，<br/>祂是不擔代；<br/>我時時刻刻在祂眷顧中。<br/>',NULL,9084,9084);
INSERT INTO stanza VALUES('C363','3','沒有一寂寞、<br/>沒有一感傷、<br/>沒有一歎息、<br/>沒有一鬱悶、<br/>沒有一艱難，<br/>－但在寶座上，<br/>祂時時刻刻思念祂的人。<br/>',NULL,9085,9085);
INSERT INTO stanza VALUES('C363','4','沒有一軟弱，<br/>祂不曾扶助；<br/>沒有一疾病，<br/>祂不能醫治；<br/>哦，時時刻刻，<br/>無論樂或苦，<br/>耶穌我救主，<br/>與我同行止。<br/>',NULL,9086,9086);
INSERT INTO stanza VALUES('C364','1','與主同葬，也一同復活，<br/>還有甚麼留給我去作？<br/>只要我不再奮鬥擊空，<br/>只要我照新生而舉動。<br/>榮耀歸於神！<br/>',NULL,9087,9087);
INSERT INTO stanza VALUES('C364','2','與主我的元首同復活，<br/>我今在聖潔路上走著；<br/>當我向前時，我就想到：<br/>『死的人脫罪』<br/>是何其好！<br/>榮耀歸於神！<br/>',NULL,9088,9088);
INSERT INTO stanza VALUES('C364','3','與主同活，祂永不再死；<br/>與主同行，祂永不會遲；<br/>我天天算自己已經死，<br/>所以我就從捆綁得釋。<br/>榮耀歸於神！<br/>',NULL,9089,9089);
INSERT INTO stanza VALUES('C364','4','為主活著，我獻上肢體，<br/>永遠歸神，作祂的奴隸。<br/>我今在恩下，不在法下，<br/>罪已失勢，主代興管轄。<br/>榮耀歸於神！<br/>',NULL,9090,9090);
INSERT INTO stanza VALUES('C364','5','靠主長大，我今真慚愧<br/>再題到我的已往寶貴；<br/>我願意結出成聖果子，<br/>滿足神心意，遵行神旨。<br/>榮耀歸於神！<br/>',NULL,9091,9091);
INSERT INTO stanza VALUES('C365','1','我與基督已同釘死，<br/>十架已將我解釋；<br/>我與基督已同復活，<br/>祂生我裡，供應我。<br/>',NULL,9092,9092);
INSERT INTO stanza VALUES('C365','chorus','與基督同死，<br/>何等的安適！<br/>脫世界、自己、罪惡！<br/>與基督同活，<br/>何等的超脫！<br/>祂生我裡，供應我。<br/>',NULL,9093,9093);
INSERT INTO stanza VALUES('C365','2','歷世歷代所藏奧祕，<br/>今藉信心可知悉：<br/>榮耀盼望－基督居衷，<br/>應當無時不歌頌。<br/>',NULL,9094,9094);
INSERT INTO stanza VALUES('C365','3','天然景物都有隱徵：<br/>麥種死了子粒生；<br/>賤木接在珍樹上面，<br/>小則變大，苦變甜。<br/>',NULL,9095,9095);
INSERT INTO stanza VALUES('C365','4','這個就是聖潔祕訣－不是自己無殘缺；<br/>主阿，求你虛我、滿我，<br/>擴我度量給我多。<br/>',NULL,9096,9096);
INSERT INTO stanza VALUES('C365','5','這個會使病痛得治－只要你向自己死，<br/>並以主的生命能力<br/>作為全人的供給。<br/>',NULL,9097,9097);
INSERT INTO stanza VALUES('C365','6','經過十架，達到寶座，<br/>主是這樣的領率，<br/>先是死亡，後是榮耀，<br/>主既如此我倣效。<br/>',NULL,9098,9098);
INSERT INTO stanza VALUES('C366','1','基督雖能千回<br/>降生於伯利恆，<br/>若未活你心內，<br/>救恩仍是無成。<br/>各各他的十架，<br/>還不會拯救你；<br/>在你裡的十架，<br/>纔有能醫治你。<br/>',NULL,9099,9099);
INSERT INTO stanza VALUES('C366','chorus','哦！基督的十字架，<br/>我接你進我心，<br/>使我脫自己管轄，<br/>完全憑主而生存。<br/>',NULL,9100,9100);
INSERT INTO stanza VALUES('C366','2','人哪！你愛何物，<br/>你就變成該物：<br/>成神，你若愛神；<br/>成塵，你若愛塵；<br/>你出，神就進入；<br/>你死，神就生甦；<br/>無你，就有基督；<br/>無物，就得萬物。<br/>',NULL,9101,9101);
INSERT INTO stanza VALUES('C366','3','你若要得著神，<br/>切勿跟從智慧；<br/>『愛』是最短路徑，<br/>使你免去紆迴。<br/>你若不為自己<br/>尋求甚麼利益，<br/>神的榮耀自己，<br/>就要充滿了你。<br/>',NULL,9102,9102);
INSERT INTO stanza VALUES('C367','1','主，你所有一切工作，<br/>並非到了十架為止；<br/>你今乃是仍舊生活，<br/>從你另一形態表示。<br/>',NULL,9103,9103);
INSERT INTO stanza VALUES('C367','2','你今仍舊施行拯救，<br/>仍舊說話，仍舊引導；<br/>你今成靈，仍在湧流，<br/>仍舊光照，使人仆倒。<br/>',NULL,9104,9104);
INSERT INTO stanza VALUES('C367','3','你成那靈，不停能力，<br/>你成那靈，不停運行，<br/>你的感動、你的鼓勵；<br/>你仍安慰，你仍命令。<br/>',NULL,9105,9105);
INSERT INTO stanza VALUES('C367','4','因為你已成為那靈，<br/>祂來就是你又來地，<br/>祂的內住是你充盈，<br/>祂是你靈，祂又是你。<br/>',NULL,9106,9106);
INSERT INTO stanza VALUES('C367','5','祂今在我的心執行<br/>你的一切命令、希冀；<br/>有如從前你在世境，<br/>執行父的所有旨意。<br/>',NULL,9107,9107);
INSERT INTO stanza VALUES('C367','6','我們識祂就是識你，<br/>服祂就是服你旨意；<br/>我們被祂滲透、洋溢，<br/>就是充滿你的自己。<br/>',NULL,9108,9108);
INSERT INTO stanza VALUES('C367','7','你今不是遠在高天，<br/>不是一去就不復返，<br/>乃是仍舊在這世間，<br/>奇哉！並住在我心坎。<br/>',NULL,9109,9109);
INSERT INTO stanza VALUES('C368','1','主，當無人認識父時，<br/>父在你裡藉你來地，<br/>好叫我們雖然無知，<br/>如要識父只要認你。<br/>',NULL,9110,9110);
INSERT INTO stanza VALUES('C368','2','但是，當你在世時候，<br/>識你的人何等的少！<br/>與你好像間隔很厚，<br/>雖在擠你，摸你不到。<br/>',NULL,9111,9111);
INSERT INTO stanza VALUES('C368','3','你今成為那靈再來，<br/>有如當初父顯於你，<br/>我要識父是看父懷，<br/>我要識你在於靈力。<br/>',NULL,9112,9112);
INSERT INTO stanza VALUES('C368','4','你今不是披前肉體，<br/>四處奔波勞碌不息，<br/>你今乃是住我靈裡，<br/>時刻用靈供應自己。<br/>',NULL,9113,9113);
INSERT INTO stanza VALUES('C368','5','曾有一次你就是父，<br/>現今的你就是聖靈，<br/>祂是你的另一態度，<br/>祂是你的第二情形。<br/>',NULL,9114,9114);
INSERT INTO stanza VALUES('C368','6','我今因為認識聖靈，<br/>我就認識你的榮耀、<br/>你的性情和你生命，<br/>認識你的本質奇妙。<br/>',NULL,9115,9115);
INSERT INTO stanza VALUES('C368','7','讚美你名，我們的心<br/>認識你是何等實在；<br/>沒有親的比你可親，<br/>沒有愛的比你可愛。<br/>',NULL,9116,9116);
INSERT INTO stanza VALUES('C369','1','當你住在肉身生命，<br/>知我識你至不深刻，<br/>你就定規成為那靈，<br/>要在我靈啟示明白。<br/>',NULL,9117,9117);
INSERT INTO stanza VALUES('C369','2','從前你是我救贖主，<br/>現今你是我保惠師，<br/>不再是那外面接觸，<br/>乃是裡面合一不弛。<br/>',NULL,9118,9118);
INSERT INTO stanza VALUES('C369','3','我今因你所成聖靈，<br/>住在靈裡不斷啟示<br/>你的自己、你的性情，<br/>覺你同在，感你真實。<br/>',NULL,9119,9119);
INSERT INTO stanza VALUES('C369','4','我能認識你的生命，<br/>遠超當日門徒經歷；<br/>雖然他們與你同行、<br/>同食、同住、<br/>同勞、同息。<br/>',NULL,9120,9120);
INSERT INTO stanza VALUES('C369','5','哦主，成為內住聖靈，<br/>你是何等實在、實在！<br/>不摸，比摸更為可憑；<br/>不見，但已心中深愛。<br/>',NULL,9121,9121);
INSERT INTO stanza VALUES('C369','6','聖靈現今是從衷裡，<br/>時刻將你供應給我，<br/>作我救贖、聖潔、公義，<br/>作我智慧和我結果。<br/>',NULL,9122,9122);
INSERT INTO stanza VALUES('C369','7','因你成靈，住我靈裡，<br/>將你供應，與我合一，<br/>時時刻刻是我自己，<br/>時時刻刻也都是你。<br/>',NULL,9123,9123);
INSERT INTO stanza VALUES('C370','1','哦，主耶穌，當你在地，<br/>他們與你多年同處；<br/>但是他們對你自己，<br/>似識不識，似悟不悟。<br/>',NULL,9124,9124);
INSERT INTO stanza VALUES('C370','2','他們聽過你的聲音，<br/>他們見過你的丰姿，<br/>他們擠過你的肉身，<br/>但你是誰，似知不知。<br/>',NULL,9125,9125);
INSERT INTO stanza VALUES('C370','3','我們好像蓋重幔子，<br/>彷彿知道，又不透明，<br/>說不認識，早已認識，<br/>說已認識，認識不清。<br/>',NULL,9126,9126);
INSERT INTO stanza VALUES('C370','4','但你今已化身那靈，<br/>成為另一位保惠師，<br/>帶著你的所有豐盛，<br/>在我裡面將你啟示。<br/>',NULL,9127,9127);
INSERT INTO stanza VALUES('C370','5','願你這靈浸透充滿<br/>在我全人每一角落，<br/>沒有一處不受你感，<br/>沒有一處不被你摸。<br/>',NULL,9128,9128);
INSERT INTO stanza VALUES('C370','6','求你這靈向我顯現，<br/>加倍實在，在我心懷；<br/>無耳所聽，無目所見，<br/>無手所摸，如此實在。<br/>',NULL,9129,9129);
INSERT INTO stanza VALUES('C370','7','當你憐憫，肯來啟示，<br/>將你自己給了我們，<br/>世上有誰比你更實？<br/>世上有何比你更真？<br/>',NULL,9130,9130);
INSERT INTO stanza VALUES('C370','8','求你這靈從我的靈，<br/>如同洪水漫溢全人：<br/>到處榮耀，到處光明，<br/>到處是你，到處是神。<br/>',NULL,9131,9131);
INSERT INTO stanza VALUES('C370','9','這個生活何等親近！<br/>你使我已在地若天：<br/>讚美滿口，喜樂滿心，<br/>同在滿魂，一切甘甜。<br/>',NULL,9132,9132);
INSERT INTO stanza VALUES('C371','1','哦主，你今乃是那靈，<br/>將我點活、賜我生命；<br/>用你豐富將我供應，<br/>何其榮耀、何其神聖！<br/>',NULL,9133,9133);
INSERT INTO stanza VALUES('C371','2','哦主，你今乃是那靈，<br/>用你大能將我釋放；<br/>生命之律，規律、節制，<br/>使我自由、使我剛強。<br/>',NULL,9134,9134);
INSERT INTO stanza VALUES('C371','3','哦主，你今乃是那靈，<br/>將我變化、使我透亮；<br/>將我模成你的形像，<br/>使我返照你的榮光。<br/>',NULL,9135,9135);
INSERT INTO stanza VALUES('C371','4','哦主，你今乃是那靈，<br/>居住、生活在我靈裡；<br/>你靈藉著我靈行動，<br/>二靈相調，化合為一。<br/>',NULL,9136,9136);
INSERT INTO stanza VALUES('C371','5','求主教我如何操練、<br/>運用我靈與你接觸；<br/>使我活在你的靈裡，<br/>憑你實際將你活出。<br/>',NULL,9137,9137);
INSERT INTO stanza VALUES('C372','1','基督是神的中心，<br/>祂也是神的普及；<br/>祂從永遠到永遠，<br/>是神心愛與歡喜。<br/>',NULL,9138,9138);
INSERT INTO stanza VALUES('C372','2','基督是神的化身，<br/>神的豐滿住祂裡；<br/>祂的尊高與神性，<br/>無人能與祂比擬。<br/>',NULL,9139,9139);
INSERT INTO stanza VALUES('C372','3','神所計畫是為祂，<br/>要祂充滿萬有中；<br/>天地宇宙的一切，<br/>都是為祂得尊榮。<br/>',NULL,9140,9140);
INSERT INTO stanza VALUES('C372','4','一切創造全為祂，<br/>萬有藉著祂而有；<br/>萬有也靠祂而立，<br/>祂是中心並圓周。<br/>',NULL,9141,9141);
INSERT INTO stanza VALUES('C372','5','祂是救贖的一切，<br/>萬有藉祂得復交；<br/>藉祂有效的寶血，<br/>萬有得與神和好。<br/>',NULL,9142,9142);
INSERT INTO stanza VALUES('C372','6','祂是一切的元始，<br/>也是召會永活頭，<br/>召會生命及內容，<br/>從死首生的元首。<br/>',NULL,9143,9143);
INSERT INTO stanza VALUES('C372','7','祂是神國的君王，<br/>執掌所有的權柄；<br/>藉祂榮耀來管治，<br/>天地萬有全從命。<br/>',NULL,9144,9144);
INSERT INTO stanza VALUES('C372','8','祂在新天新地裡，<br/>要作萬有的中心；<br/>為著神性、為著人，<br/>直到永遠無窮盡。<br/>',NULL,9145,9145);
INSERT INTO stanza VALUES('C372','9','神的心意是要祂<br/>能在萬有居首位；<br/>這一萬有的基督，<br/>現今竟作我美味！<br/>',NULL,9146,9146);
INSERT INTO stanza VALUES('C373','1','基督是神真實見證，<br/>或在本質、或在言行；<br/>完滿顯出神的榮耀，<br/>使人看見神的性情。<br/>',NULL,9147,9147);
INSERT INTO stanza VALUES('C373','2','基督作神完滿見證，<br/>遠勝律法為神所作；<br/>律法不過只用字句，<br/>非用生命，將神述說。<br/>',NULL,9148,9148);
INSERT INTO stanza VALUES('C373','3','神性豐滿住在基督，<br/>作了祂的內容成分；<br/>祂是神的具體化身，<br/>神的住處、神的器皿。<br/>',NULL,9149,9149);
INSERT INTO stanza VALUES('C373','4','神的榮耀、神的形像，<br/>基督全都彰顯展覽；<br/>神的心意、神的道路，<br/>也都在祂給人看見。<br/>',NULL,9150,9150);
INSERT INTO stanza VALUES('C373','5','基督現今住在我靈，<br/>為作我分直到永久；<br/>我在靈中將祂分享，<br/>神性一切全歸我有。<br/>',NULL,9151,9151);
INSERT INTO stanza VALUES('C374','1','基督是萬有惟一的實際，<br/>在神或在人一切同此理；<br/>人在祂以外，<br/>無法尋到神，<br/>除非有祂在，<br/>萬有全不真。<br/>',NULL,9152,9152);
INSERT INTO stanza VALUES('C374','2','一切的形像、<br/>所有的豫表，<br/>並人之所需，<br/>無論大或小，<br/>全都是影兒，<br/>象徵神基督，<br/>表明祂是我一切的事物。<br/>',NULL,9153,9153);
INSERT INTO stanza VALUES('C374','3','萬事與萬物盡都是虛空，<br/>除非有基督充滿在其中；<br/>縱然能得到並享盡一切，<br/>若沒有基督，<br/>我仍是空缺。<br/>',NULL,9154,9154);
INSERT INTO stanza VALUES('C374','4','基督是真神，<br/>基督是真主，<br/>祂是我真光、<br/>是我真事物、<br/>是我真衣食<br/>、是我真活水、<br/>是我真生命、<br/>是我真美味。<br/>',NULL,9155,9155);
INSERT INTO stanza VALUES('C374','5','所有的神學、<br/>一切的道理，<br/>也都應該有基督作實際；<br/>聖經的知識若缺少基督，<br/>不過是字句，<br/>盡都是虛無。<br/>',NULL,9156,9156);
INSERT INTO stanza VALUES('C374','6','時間或空間，<br/>基督是實際，<br/>一切的事物，<br/>盡都同此理；<br/>基督是萬有惟一的實際，<br/>一直到永遠，<br/>此理不更易。<br/>',NULL,9157,9157);
INSERT INTO stanza VALUES('C375','1','主，你已使你的自己，<br/>成為我們活的實際；<br/>榮耀實際對於信心，<br/>比諸地上任何都真；<br/>可愛實際，其親其密，<br/>地上最近親人難比。<br/>',NULL,9158,9158);
INSERT INTO stanza VALUES('C375','2','有福異象我已看見：<br/>惟有你是我的完全；<br/>你已純潔我的意願，<br/>最聖愛火其中點燃；<br/>你已提高我的性情，<br/>充滿你的榮耀豐盛。<br/>',NULL,9159,9159);
INSERT INTO stanza VALUES('C375','3','永活救主，可愛恩人，<br/>對我你要更親更近；<br/>你的榮面要更光明，<br/>你的恩言要更有能；<br/>愛中要將我全變化，<br/>憐憫、恩典要更增加。<br/>',NULL,9160,9160);
INSERT INTO stanza VALUES('C376','1','神所賜恩典，<br/>最高的定義，<br/>是神在子裡<br/>所給的自己；<br/>不重在事物，<br/>賜於古或今，<br/>乃是神自己<br/>作我的永分。<br/>',NULL,9161,9161);
INSERT INTO stanza VALUES('C376','2','神成為肉身，<br/>來與人調和，<br/>為給人接受，<br/>而將祂得著；<br/>人藉主從神<br/>所得的恩典，<br/>就是主自己<br/>來住我心間。<br/>',NULL,9162,9162);
INSERT INTO stanza VALUES('C376','3','在使徒保羅，<br/>萬事如糞土，<br/>恩典之於他，<br/>只是神基督；<br/>乃藉這恩典－他所經歷主，<br/>他為主勞苦，<br/>超過眾使徒。<br/>',NULL,9163,9163);
INSERT INTO stanza VALUES('C376','4','基督在我裡，<br/>作我的能力，<br/>乃是真恩典，<br/>彀為我賴倚；<br/>這彀用恩典<br/>在我的靈裡，<br/>時常加我力，<br/>完成神旨意。<br/>',NULL,9164,9164);
INSERT INTO stanza VALUES('C376','5','這恩典就是<br/>那活的基督<br/>作我的一切，<br/>時將我眷顧。<br/>主，願我認識<br/>你這真恩典，<br/>享你作恩典，<br/>一直的增添。<br/>',NULL,9165,9165);
INSERT INTO stanza VALUES('C377','1','榮耀！榮耀！<br/>基督作生命，<br/>榮耀！榮耀！<br/>聖靈來引領，<br/>無力變為有能，<br/>黑暗變光明，<br/>榮耀！榮耀！<br/>基督作生命。<br/>',NULL,9166,9166);
INSERT INTO stanza VALUES('C377','2','榮耀！榮耀！<br/>靠著主而生，<br/>榮耀！榮耀！<br/>隨從靈而行，<br/>失敗變為得勝，<br/>歎息變頌稱，<br/>榮耀！榮耀！<br/>靠著主而生。<br/>',NULL,9167,9167);
INSERT INTO stanza VALUES('C378','1','何等生命！何等平安！<br/>基督活在我的裡面！<br/>我已與祂同釘十架，<br/>榮耀事實、奇妙救法！<br/>現在活著不再是我，<br/>乃是基督在我活著！<br/>現在活著不再是我，<br/>乃是基督在我活著！<br/>',NULL,9168,9168);
INSERT INTO stanza VALUES('C378','2','何等快樂！何等安息！<br/>基督成形在我心裡！<br/>祂的生命、祂的性情，<br/>在我全人都已組成；<br/>我的一切全都了結，<br/>祂的成分作我一切！<br/>我的一切全都了結，<br/>祂的成分作我一切！<br/>',NULL,9169,9169);
INSERT INTO stanza VALUES('C378','3','何等榮耀！何等可誇！<br/>總叫基督照常顯大！<br/>無論禍、福，<br/>無論生、死，<br/>並無一事叫我羞恥；<br/>任何境遇、一切事故，<br/>都是叫我彰顯基督！<br/>任何境遇、一切事故，<br/>都是叫我彰顯基督！<br/>',NULL,9170,9170);
INSERT INTO stanza VALUES('C378','4','何等結果！何等有福！<br/>我能活著就是基督！<br/>祂的心意是我愛好，<br/>祂的榮耀是我發表；<br/>無何可要、無何可寶，<br/>惟有基督是我目標！<br/>無何可要、無何可寶，<br/>惟有基督是我目標！<br/>',NULL,9171,9171);
INSERT INTO stanza VALUES('C379','1','何等大能！何等大力！<br/>神使基督從死復起，<br/>遠超一切，坐在神右，<br/>為我今作萬有之首。<br/>浩大能力全為召會，<br/>好使萬有盡都來歸。<br/>浩大能力全為召會，<br/>好使萬有盡都來歸。<br/>',NULL,9172,9172);
INSERT INTO stanza VALUES('C379','2','何等事實！何等奧祕！<br/>我今乃是基督肢體；<br/>與眾聖徒彼此相調，<br/>新人裡面同被建造；<br/>聯於我們升天元首，<br/>作祂身體，照神所籌。<br/>聯於我們升天元首，<br/>作祂身體，照神所籌。<br/>',NULL,9173,9173);
INSERT INTO stanza VALUES('C379','3','何等高、深！<br/>何等長、闊！<br/>其度、其量無法測度！<br/>神的基督無限、無量，<br/>廣大無邊，超人所想。<br/>凡祂所是和祂所有，<br/>都是為將召會成就。<br/>凡祂所是和祂所有，<br/>都是為將召會成就。<br/>',NULL,9174,9174);
INSERT INTO stanza VALUES('C380','1','榮耀！榮耀！榮耀生命！<br/>榮耀生命是基督！<br/>聖潔、公義、<br/>良善、光明！<br/>哦，這生命何豐富！<br/>神性一切榮耀、豐盛，<br/>在祂裡面全藏著；<br/>祂今竟是我的生命，<br/>在我裡面供應我。<br/>',NULL,9175,9175);
INSERT INTO stanza VALUES('C380','2','神聖！神聖！神聖生命！<br/>神聖生命是基督！<br/>祂已化身成為聖靈，<br/>到我裡面來居住。<br/>感動、運行、<br/>光照、教訓，<br/>如同膏油在塗抹，<br/>充滿、澆灌、<br/>加力、滋潤，<br/>在我裡面供應我。<br/>',NULL,9176,9176);
INSERT INTO stanza VALUES('C380','3','大能！大能！大能生命！<br/>大能生命是基督！<br/>祂已帶我與祂同釘，<br/>使我不再作罪奴。<br/>祂也帶我同祂復生，<br/>使我和祂同活著，<br/>經歷祂的復活大能，<br/>在我裡面供應我。<br/>',NULL,9177,9177);
INSERT INTO stanza VALUES('C380','4','得勝！得勝！得勝生命！<br/>得勝生命是基督！<br/>祂在十架已經得勝，<br/>使我不再作俘虜。<br/>撒但、鬼魔、<br/>世界、人情，<br/>祂都為我全勝過；<br/>今來作我得勝生命，<br/>在我裡面供應我。<br/>',NULL,9178,9178);
INSERT INTO stanza VALUES('C380','5','榮耀！神聖！大能生命！<br/>得勝生命是基督！<br/>使我剛強，使我得勝，<br/>使我長大並成熟；<br/>使我變質，使我像祂，<br/>使我自由且超脫；<br/>直到那日被提變化，<br/>在我裡面供應我。<br/>',NULL,9179,9179);
INSERT INTO stanza VALUES('C381','1','主，你是我生命，<br/>活在我裡面；<br/>帶著神的豐盛，<br/>來將我充滿。<br/>你的聖別性情，<br/>使我能成聖；<br/>你的復活大能，<br/>使我能得勝。<br/>',NULL,9180,9180);
INSERT INTO stanza VALUES('C381','2','你這生命流通，<br/>我就蒙光照，<br/>使我活在光中，<br/>與你能相交；<br/>帶來各種供應，<br/>也有所要求，<br/>使我得蒙潔淨，<br/>享受你所有。<br/>',NULL,9181,9181);
INSERT INTO stanza VALUES('C381','3','你是那靈運行，<br/>像膏油塗抹，<br/>將我心思、心、靈，<br/>全都浸潤過，<br/>使我全人變化，<br/>成為你形狀，<br/>直到成熟長大，<br/>滿有你身量。<br/>',NULL,9182,9182);
INSERT INTO stanza VALUES('C381','4','你的生命成分，<br/>成為我豐富，<br/>時常將我滋潤，<br/>使我得復甦。<br/>生命吞滅死亡，<br/>軟弱變剛強；<br/>釋放消除捆綁，<br/>下沉變高昂。<br/>',NULL,9183,9183);
INSERT INTO stanza VALUES('C381','5','因此我將自己，<br/>完全獻給你，<br/>照著你的心意，<br/>活在交通裡；<br/>不再立志掙扎，<br/>不再改自己，<br/>使你受到打岔，<br/>毫不能為力。<br/>',NULL,9184,9184);
INSERT INTO stanza VALUES('C381','6','乃是完全停下<br/>自己的努力，<br/>讓你運行、變化，<br/>使我脫自己；<br/>與眾聖徒配搭，<br/>成為你身體，<br/>讓你定居、安家，<br/>彰顯你自己。<br/>',NULL,9185,9185);
INSERT INTO stanza VALUES('C382','1','榮耀基督，親愛救主，<br/>你是神的榮耀顯出！<br/>原是永遠無限的神，<br/>竟作時間有限的人。<br/>',NULL,9186,9186);
INSERT INTO stanza VALUES('C382','chorus','榮耀基督，大神化身，<br/>奧妙、豐富，享受不盡！<br/>聖中之聖，人中之人，<br/>在我靈裡作我福分！<br/>',NULL,9187,9187);
INSERT INTO stanza VALUES('C382','2','神的豐盛藏你裡面，<br/>神的榮耀從你彰顯；<br/>前在肉身成功救贖，<br/>今成那靈與我聯屬。<br/>',NULL,9188,9188);
INSERT INTO stanza VALUES('C382','3','凡父所有全由你承，<br/>凡你所是都歸於靈；<br/>靈進我靈作你實際，<br/>使你成為我的經歷。<br/>',NULL,9189,9189);
INSERT INTO stanza VALUES('C382','4','靈今藉你生命活話，<br/>在我裡面將你實化；<br/>接受這話，接觸這靈，<br/>你就作了我的供應。<br/>',NULL,9190,9190);
INSERT INTO stanza VALUES('C382','5','靈裡敬拜，靈裡瞻仰，<br/>如鏡返照你的榮光，<br/>我就變成你的形狀，<br/>使你從我得著顯彰。<br/>',NULL,9191,9191);
INSERT INTO stanza VALUES('C382','6','惟有如此纔能成聖，<br/>必須如此纔能得勝；<br/>捨此無法摸著生命，<br/>捨此無路可以屬靈。<br/>',NULL,9192,9192);
INSERT INTO stanza VALUES('C382','7','藉此你靈浸透全人，<br/>到處是你，到處是神！<br/>我就脫離天然自我，<br/>與眾聖徒作神居所。<br/>',NULL,9193,9193);
INSERT INTO stanza VALUES('C383','1','榮耀之中有一位，<br/>乃是神而人；<br/>聖潔、公義又智慧，<br/>光明且慈仁；<br/>祂曾為我捨生命，<br/>成功神救法，<br/>使我能有祂性情，<br/>使我能像祂。<br/>',NULL,9194,9194);
INSERT INTO stanza VALUES('C383','2','榮耀之中有一位，<br/>乃是得勝王；<br/>黑暗權勢祂摧毀，<br/>撒但祂擊傷，<br/>衝破陰府升天庭，<br/>遠超諸執政，<br/>使我與祂同高升，<br/>與祂同誇勝。<br/>',NULL,9195,9195);
INSERT INTO stanza VALUES('C383','3','榮耀之中有一位，<br/>祂是我生命；<br/>時刻住在我心內，<br/>管理並引領，<br/>使祂聖潔的性情，<br/>成形在我心，<br/>使祂榮耀的生命，<br/>彰顯於我身。<br/>',NULL,9196,9196);
INSERT INTO stanza VALUES('C383','4','榮耀之中有一位，<br/>祂是我盼望；<br/>不久從天必歸回，<br/>接我到天上，<br/>用祂榮耀的大能，<br/>改變我形狀，<br/>使我變成祂榮形，<br/>與祂永相像。<br/>',NULL,9197,9197);
INSERT INTO stanza VALUES('C384','1','一棵果樹、一道水河，<br/>二者乃是樂園特色，<br/>供人飲食、解人飢渴，<br/>使人神前活著。<br/>',NULL,9198,9198);
INSERT INTO stanza VALUES('C384','chorus','神在基督裡作人食糧，<br/>基督成為靈供人營養；<br/>這無限之靈給我飽嘗，<br/>我就將神全享。<br/>',NULL,9199,9199);
INSERT INTO stanza VALUES('C384','2','果樹乃指榮耀基督，<br/>來作人的生命食物，<br/>使人享受神的豐富，<br/>人就得到滿足。<br/>',NULL,9200,9200);
INSERT INTO stanza VALUES('C384','3','水河乃指無限之靈，<br/>來作人的靈性供應，<br/>使人飽嘗神的豐盛，<br/>人就成為神聖。<br/>',NULL,9201,9201);
INSERT INTO stanza VALUES('C384','4','榮耀基督作我生命，<br/>成為那靈活在我靈，<br/>使我調進神的性情，<br/>有分神的榮形。<br/>',NULL,9202,9202);
INSERT INTO stanza VALUES('C384','5','榮耀基督我肯尊崇，<br/>無限之靈我肯順從，<br/>我就顯出神的光榮，<br/>恩榮世世無窮！<br/>',NULL,9203,9203);
INSERT INTO stanza VALUES('C385','1','主阿，你是嗎哪，<br/>已經從天降下；<br/>來作我的食物，<br/>使我得著飽足。<br/>',NULL,9204,1);
INSERT INTO stanza VALUES('C385','2','你是磐石裂破，<br/>流出活水為我；<br/>隨時我都可喝，<br/>使我免去乾渴。<br/>',NULL,9205,2);
INSERT INTO stanza VALUES('C385','3','現在我來就你，<br/>因我又渴又飢；<br/>用你自己餧我，<br/>給我活水解渴。<br/>',NULL,9206,3);
INSERT INTO stanza VALUES('C385','4','我願喫你、喝你，<br/>吸取你的自己；<br/>飽嘗你的生命，<br/>暢飲你的聖靈。<br/>若非如此吸取，<br/>就難免去空虛；<br/>如此喫你、喝你，<br/>纔能生活有力。<br/>',NULL,9207,4);
INSERT INTO stanza VALUES('C386','1','基督就是我的世界：<br/>生命、喜樂、一切！<br/>祂是我力，時時提挈，<br/>離祂我就仆跌。<br/>當我愁苦我來就祂，<br/>無人如此安撫接納；<br/>使我心樂，解我心憂，<br/>祂是我友！<br/>',NULL,9208,9208);
INSERT INTO stanza VALUES('C386','2','基督就是我的世界：<br/>百般試煉之助，<br/>處處照護，事事體貼，<br/>一再向我賜福。<br/>祂賜日光，又賜甘霖，<br/>祂賜收穫，金穀豐稔；<br/>日光甘霖，金穀豐收，<br/>祂是我友！<br/>',NULL,9209,9209);
INSERT INTO stanza VALUES('C386','3','基督就是我的世界，<br/>對祂我必效忠！<br/>我怎能彀將祂棄絕，<br/>當祂施恩重重？<br/>隨祂行走，必不會錯，<br/>有祂引領，晝夜無輟；<br/>隨祂行走，夜以繼晝，<br/>祂是我友！<br/>',NULL,9210,9210);
INSERT INTO stanza VALUES('C386','4','基督就是我的世界，<br/>更好朋友無需；<br/>我願與祂完全聯結，<br/>直到永世不渝。<br/>美麗生命，配此良友，<br/>美麗生命，直到永久；<br/>永久生命，永久逍遊，<br/>祂是我友！<br/>',NULL,9211,9211);
INSERT INTO stanza VALUES('C387','1','無論罪惡如何深劇，<br/>無論道路如何崎嶇，<br/>無論境遇如何可慮，<br/>主，你總是彀用！<br/>',NULL,9212,9212);
INSERT INTO stanza VALUES('C387','2','遇到試煉，無論大小，<br/>有了罣慮，無論多少，<br/>即使腳步盡都跌倒，<br/>主，你總是彀用！<br/>',NULL,9213,9213);
INSERT INTO stanza VALUES('C387','3','屬地事物悅意稱心，<br/>光天化日路途平順，<br/>安逸竟成遮光之雲，<br/>主，你當然彀用！<br/>',NULL,9214,9214);
INSERT INTO stanza VALUES('C387','4','即使憂苦終日為患，<br/>失望、灰心、前途黑暗，<br/>心麻、靈木、欲禱無言，<br/>主，你仍是彀用！<br/>',NULL,9215,9215);
INSERT INTO stanza VALUES('C387','5','不論我的環境如何，<br/>你手都在將我托著，<br/>使我經歷你之於我，<br/>乃是全足之主！<br/>',NULL,9216,9216);
INSERT INTO stanza VALUES('C388','1','我已得到宇宙至寶，<br/>我心因此歡呼；<br/>歡呼基督給我得到，<br/>何等一位基督！<br/>',NULL,9217,9217);
INSERT INTO stanza VALUES('C388','2','我這基督是神羔羊，<br/>擔當我的罪愆；<br/>又是神的公義太陽，<br/>發出醫治光線。<br/>',NULL,9218,9218);
INSERT INTO stanza VALUES('C388','3','我這基督是生命樹，<br/>長在神的樂園；<br/>祂的美果作我食物，<br/>供應豐富、甘甜。<br/>',NULL,9219,9219);
INSERT INTO stanza VALUES('C388','4','我這基督是生命泉，<br/>流出活水江河；<br/>在我裡面流到永遠，<br/>解除一切乾渴。<br/>',NULL,9220,9220);
INSERT INTO stanza VALUES('C388','5','我這基督是我祭司，<br/>為我顯在神前，<br/>也是先知滿有啟示，<br/>且是君王掌權。<br/>',NULL,9221,9221);
INSERT INTO stanza VALUES('C388','6','是我救主、中保、大夫、<br/>牧人、策士、元首、<br/>我兄、我父、<br/>我神、我主、<br/>師尊、良人、密友。<br/>',NULL,9222,9222);
INSERT INTO stanza VALUES('C388','7','是我生命、能力、智慧：<br/>公義、聖潔、救贖；<br/>平安、喜樂、<br/>盼望、安慰、<br/>榮耀、亮光、道路。<br/>',NULL,9223,9223);
INSERT INTO stanza VALUES('C388','8','我這基督充滿萬有，<br/>怎能述盡說竭？<br/>祂是首先、祂是末後、<br/>祂是一切一切！<br/>',NULL,9224,9224);
INSERT INTO stanza VALUES('C388','9','我既得到這樣至寶，<br/>我心怎不歡呼！<br/>歡呼基督給我得到，<br/>何等一位基督！<br/>',NULL,9225,9225);
INSERT INTO stanza VALUES('C389','1','今世福樂沒滅，<br/>基督屬我！<br/>地上愛情斷絕，<br/>基督屬我！<br/>在此幽暗野地，<br/>無處可以安息，<br/>惟有基督可倚，<br/>基督屬我！<br/>',NULL,9226,9226);
INSERT INTO stanza VALUES('C389','2','莫誘我心離開，<br/>基督屬我！<br/>我願與主同在，<br/>基督屬我！<br/>你這今世歡娛，<br/>一時騙人之局，<br/>從我心中離去，<br/>基督屬我！<br/>',NULL,9227,9227);
INSERT INTO stanza VALUES('C389','3','去罷，今世幻夢，<br/>基督屬我！<br/>我今已經清醒，<br/>基督屬我！<br/>凡我從前所慕，<br/>不過使我痛苦；<br/>惟主使我滿足，<br/>基督屬我！<br/>',NULL,9228,9228);
INSERT INTO stanza VALUES('C389','4','去罷，短暫今時，<br/>基督屬我！<br/>來罷，長久永世，<br/>基督屬我！<br/>來罷，可愛福氣！<br/>來罷，甜美安息！<br/>來罷，恩主自己！<br/>基督屬我！<br/>',NULL,9229,9229);
INSERT INTO stanza VALUES('C390','1','耶穌，我救主，<br/>祂是我一切！<br/>奇妙的救主，<br/>何等的可悅！<br/>引導和保護，<br/>所有安度過，<br/>大能的救主－耶穌為我。<br/>',NULL,9230,9230);
INSERT INTO stanza VALUES('C390','chorus','耶穌為我！耶穌為我！<br/>每時候，每處所，<br/>耶穌為我！<br/>',NULL,9231,9231);
INSERT INTO stanza VALUES('C390','2','耶穌於康健，<br/>耶穌於病痛，<br/>耶穌於富裕，<br/>或是於貧窮，<br/>無論是日光，<br/>無論是風波，<br/>祂是我平安－耶穌為我。<br/>',NULL,9232,9232);
INSERT INTO stanza VALUES('C390','3','祂是我磐石、<br/>堡壘和盾牌，<br/>祂是我生命、<br/>亮光和高臺，<br/>我的保護者、<br/>我的避難所、<br/>我的救贖主－耶穌為我。<br/>',NULL,9233,9233);
INSERT INTO stanza VALUES('C390','4','祂是我先知、<br/>祭司和君王、<br/>我的生命泉、<br/>我的生命糧；<br/>祂是我信實和我的寄託、<br/>我的拯救角－耶穌為我。<br/>',NULL,9234,9234);
INSERT INTO stanza VALUES('C390','5','耶穌於喜樂、<br/>或是於痛苦，<br/>損失或利益，<br/>祂是我寶庫；<br/>無論在何處，<br/>祂顧我軟弱，<br/>留世或離世－耶穌為我。<br/>',NULL,9235,9235);
INSERT INTO stanza VALUES('C391','1','你這『恬靜』隱密之源，<br/>你這神聖全足的愛；<br/>是我幫助，是我靠山，<br/>我的安全是你同在；<br/>我從一切憂困、罪纏，<br/>前來藏身在你裡面。<br/>',NULL,9236,9236);
INSERT INTO stanza VALUES('C391','2','你是我的一切需要，<br/>勞中之息，苦中之逸；<br/>你是敷我傷心之膏，<br/>亂時之安，損時之益；<br/>受虐之時，是我笑臉；<br/>蒙羞之時，是我冠冕。<br/>',NULL,9237,9237);
INSERT INTO stanza VALUES('C391','3','缺乏之時，是我供給；<br/>受困之時，是我釋放；<br/>軟弱之時，是我能力；<br/>黑暗之時，是我亮光；<br/>愁苦之時，是我喜樂；<br/>死亡之中，是我復活。<br/>',NULL,9238,9238);
INSERT INTO stanza VALUES('C391','4','你這『恬靜』隱密之源，<br/>你這神聖全足的愛，<br/>我願藏身在你裡面，<br/>享受你的甜美同在：<br/>你是我的一切一切，<br/>享受不盡、取用不竭！<br/>',NULL,9239,9239);
INSERT INTO stanza VALUES('C392','1','祂是一切最親－我所一切最愛；<br/>人生平常所尋，<br/>人生終久所賴。<br/>',NULL,9240,9240);
INSERT INTO stanza VALUES('C392','2','缺乏之時豫備，<br/>無倚之時扶持，<br/>所有美時，最美，<br/>無論何時，信實。<br/>',NULL,9241,9241);
INSERT INTO stanza VALUES('C392','3','無窮喜樂，原因，<br/>年日移換，不改；<br/>祂是一切最親－我所一切最愛。<br/>',NULL,9242,9242);
INSERT INTO stanza VALUES('C393','1','祂是樂中之樂，<br/>祂已解我乾渴；<br/>祂是歌中之歌，<br/>祂今消我寂寞。<br/>',NULL,9243,9243);
INSERT INTO stanza VALUES('C393','2','祂是美中之美，<br/>合我人生口味；<br/>祂是貴中之貴，<br/>是我無上寶貝。<br/>',NULL,9244,9244);
INSERT INTO stanza VALUES('C393','3','祂是命中之命，<br/>使我從死復生；<br/>祂是聖中之聖，<br/>使我與世不並。<br/>',NULL,9245,9245);
INSERT INTO stanza VALUES('C393','4','祂是義中之義，<br/>使我神前站立；<br/>祂是力中之力，<br/>使我路中不疲。<br/>',NULL,9246,9246);
INSERT INTO stanza VALUES('C393','5','祂是能中之能，<br/>使我如鷹上騰；<br/>祂是勝中之勝，<br/>使我得佔上風。<br/>',NULL,9247,9247);
INSERT INTO stanza VALUES('C393','6','祂是強中之強，<br/>將我全人釋放；<br/>祂是壯中之壯，<br/>使我心靈堅剛。<br/>',NULL,9248,9248);
INSERT INTO stanza VALUES('C393','7','祂是王中之王，<br/>祂今作我心皇；<br/>祂是光中之光，<br/>時時使我明亮。<br/>',NULL,9249,9249);
INSERT INTO stanza VALUES('C393','8','祂是主中之主，<br/>祂今住我心府；<br/>祂是路中之路，<br/>處處引我腳步。<br/>',NULL,9250,9250);
INSERT INTO stanza VALUES('C393','9','祂是醫中之醫，<br/>醫我靈、魂、身體；<br/>祂是奇中之奇，<br/>使我榮耀無比。<br/>',NULL,9251,9251);
INSERT INTO stanza VALUES('C393','10','祂是望中之望，<br/>吸我心情向上；<br/>祂是賞中之賞，<br/>引我腳步前往。<br/>',NULL,9252,9252);
INSERT INTO stanza VALUES('C393','11','祂是愛中之愛，<br/>配我全心感戴；<br/>祂是耐中之耐，<br/>配我永遠敬拜。<br/>',NULL,9253,9253);
INSERT INTO stanza VALUES('C393','12','祂是雄中之雄，<br/>惟祂配我尊崇；<br/>祂是榮中之榮，<br/>惟祂配我稱頌。<br/>',NULL,9254,9254);
INSERT INTO stanza VALUES('C394','1','前要的是祝福，<br/>今要主自己；<br/>前要的是醫治，<br/>今要主而已；<br/>前我貪求恩賜，<br/>今要賜恩者；<br/>前我尋求能力，<br/>今要全能者。<br/>',NULL,9255,9255);
INSERT INTO stanza VALUES('C394','chorus','永遠舉起耶穌，<br/>讚美主不歇；<br/>一切在於基督，<br/>主是我一切。<br/>',NULL,9256,9256);
INSERT INTO stanza VALUES('C394','2','前常用手抓主，<br/>今主手牽我；<br/>前常無所適從，<br/>今拋錨穩妥；<br/>前是寶貴感覺，<br/>今憑主口說；<br/>前是頻頻苦試，<br/>今完全信託。<br/>',NULL,9257,9257);
INSERT INTO stanza VALUES('C394','3','前是忙於打算，<br/>今則靠祈求；<br/>前是懸切罣慮，<br/>今則主擔憂；<br/>前隨我之所欲，<br/>今聽主支配；<br/>前不住的討問，<br/>今不斷讚美。<br/>',NULL,9258,9258);
INSERT INTO stanza VALUES('C394','4','前我欲利用主，<br/>今則主用我；<br/>前是我的事業，<br/>今為主工作；<br/>前欲得人稱讚，<br/>今求主歡喜；<br/>前不過半得救，<br/>今被救到底。<br/>',NULL,9259,9259);
INSERT INTO stanza VALUES('C394','5','前羨慕得著主，<br/>今知主屬我；<br/>前我燈將熄滅，<br/>今則光炳爍；<br/>前所望的是死，<br/>今等候被提；<br/>我所有的一切，<br/>都在主自己。<br/>',NULL,9260,9260);
INSERT INTO stanza VALUES('C395','1','惟有耶穌是我題目，<br/>我的信息是耶穌；<br/>惟有耶穌是我歌賦，<br/>我所仰望是耶穌。<br/>',NULL,9261,9261);
INSERT INTO stanza VALUES('C395','chorus','惟有耶穌，永是耶穌，<br/>我們歌頌這耶穌，<br/>祂是救主、生命、大夫，<br/>祂是君王建國度。<br/>',NULL,9262,9262);
INSERT INTO stanza VALUES('C395','2','惟有耶穌是我救主，<br/>擔當我的所有罪，<br/>一次成功永遠救贖，<br/>使我得以蒙恩惠。<br/>',NULL,9263,9263);
INSERT INTO stanza VALUES('C395','3','惟有耶穌是我生命，<br/>救我脫離罪與己；<br/>惟有耶穌用祂聖靈，<br/>充滿我心作我力。<br/>',NULL,9264,9264);
INSERT INTO stanza VALUES('C395','4','惟有耶穌是我大夫，<br/>擔當我的病與疾；<br/>復活生命、升天豐富，<br/>祂都分賜祂肢體。<br/>',NULL,9265,9265);
INSERT INTO stanza VALUES('C395','5','惟有耶穌是我能力，<br/>是祂賜下五旬節；<br/>哦主，求你使我得以<br/>充滿聖靈常勝捷。<br/>',NULL,9266,9266);
INSERT INTO stanza VALUES('C395','6','我們現在等候耶穌，<br/>要聽祂來的招呼；<br/>但是始終惟有耶穌，<br/>惟有耶穌萬有主。<br/>',NULL,9267,9267);
INSERT INTO stanza VALUES('C396','1','當我不見基督容華，<br/>時間何等無味、可厭！<br/>甘甜的鳥、甘甜的花，<br/>對我就不再是甘甜；<br/>可愛太陽如失光線，<br/>田野枉欲表現歡喜；<br/>當我快樂在祂裡面，<br/>陰霾也如晴空美麗。<br/>',NULL,9268,9268);
INSERT INTO stanza VALUES('C396','2','祂名發出最美香味，<br/>祂聲成為最甜音樂，<br/>祂的同在展我愁眉，<br/>使我裡面盡都歡悅；<br/>祂若如此不斷親密，<br/>我就無何可怕、可求，<br/>無人快樂與我可比，<br/>我的春日長年常有。<br/>',NULL,9269,9269);
INSERT INTO stanza VALUES('C396','3','看見祂面我就甘甜，<br/>我就只求祂的歡喜，<br/>不論時地有何改變，<br/>不能改變我的心意；<br/>只要感覺祂的愛戀，<br/>宮殿也成可笑玩具，<br/>監獄可成榮耀宮殿，<br/>如果基督和我同居。<br/>',NULL,9270,9270);
INSERT INTO stanza VALUES('C396','4','我主，若我真是屬你，<br/>你若是我詩歌、太陽，<br/>請問為何我仍憂悒？<br/>為何嚴冬這樣久長？<br/>或將黑雲趕離我天，<br/>恢復你的歡樂同在；<br/>或接我到你的面前，<br/>無冬昏昧，無雲靉靆。<br/>',NULL,9271,9271);
INSERT INTO stanza VALUES('C397','1','基督是我主觀經歷，<br/>住於我靈作生命；<br/>基督是我一切一切，<br/>我得與祂成一靈。<br/>',NULL,9272,9272);
INSERT INTO stanza VALUES('C397','chorus','哦，基督是我<br/>主觀的經歷，<br/>實際、甘甜又豐富！<br/>哦，基督是我<br/>一切的一切，<br/>我的需要全應付！<br/>',NULL,9273,9273);
INSERT INTO stanza VALUES('C397','2','基督是我主觀經歷，<br/>時時供我以生命；<br/>生命之靈使我復甦，<br/>天天使我靈高升。<br/>',NULL,9274,9274);
INSERT INTO stanza VALUES('C397','3','基督是我主觀經歷，<br/>變化我的魂生命；<br/>更新我的心思、意志，<br/>將我模成祂榮形。<br/>',NULL,9275,9275);
INSERT INTO stanza VALUES('C397','4','基督是我主觀經歷，<br/>使我全人都超脫；<br/>藉祂生命律的大能，<br/>在我靈中釋放我。<br/>',NULL,9276,9276);
INSERT INTO stanza VALUES('C397','5','基督是我主觀經歷，<br/>事事作我的準繩，<br/>管理、改正、<br/>規律、引導，<br/>處處予我以調整。<br/>',NULL,9277,9277);
INSERT INTO stanza VALUES('C397','6','基督是我主觀經歷，<br/>使我所需無缺欠；<br/>用祂豐富將我供應，<br/>使我得享神豐滿。<br/>',NULL,9278,9278);
INSERT INTO stanza VALUES('C398','1','基督今日於我，<br/>客觀也主觀；<br/>客觀，<br/>祂在天上為我在代辯；<br/>主觀，<br/>祂在我裡作我的生命，<br/>時刻將祂自己<br/>由衷來供應。<br/>',NULL,9279,9279);
INSERT INTO stanza VALUES('C398','2','祂在天上<br/>坐在父神的右邊，<br/>為我作大祭司<br/>將血獻神前；<br/>在天作我中保，<br/>擔負我重擔，<br/>憑祂愛心、忠誠，<br/>辦理我案件。<br/>',NULL,9280,9280);
INSERT INTO stanza VALUES('C398','3','祂是生命之靈，<br/>住在我靈中，<br/>在此作我生命，<br/>萬有且帶同；<br/>作我內心力量，<br/>恩惠時供應；<br/>作我裡面侍從，<br/>維持以大能。<br/>',NULL,9281,9281);
INSERT INTO stanza VALUES('C398','4','祂在天上<br/>為我作一得榮人，<br/>作我開路先鋒，<br/>幔內顯榮身；<br/>在那屬天境地，<br/>以祂的自己，<br/>將人帶到神裡，<br/>人、神得成一。<br/>',NULL,9282,9282);
INSERT INTO stanza VALUES('C398','5','祂在我裡<br/>使我有分神豐滿，<br/>祂乃那靈<br/>將神帶到我裡面；<br/>藉著啟示，<br/>使神成為我實際，<br/>生命之中，<br/>神、人相調成為一。<br/>',NULL,9283,9283);
INSERT INTO stanza VALUES('C398','6','升天客觀救主，<br/>今住高天上，<br/>不久祂要歸回，<br/>眾目得觀賞；<br/>內住主觀基督，<br/>今活我靈裡，<br/>不久祂要顯出，<br/>改變我賤體。<br/>',NULL,9284,9284);
INSERT INTO stanza VALUES('C398','7','日子不久要到，<br/>天地要結聯，<br/>在新聖城撒冷，<br/>神、人再無間；<br/>在那榮耀時日，<br/>客觀與主觀<br/>在我相調為一，<br/>完全又永遠。<br/>',NULL,9285,9285);
INSERT INTO stanza VALUES('C399','1','神的心意所喜所愛：<br/>基督啟示我靈中；<br/>不是接受外面宗教，<br/>乃讓基督來居衷。<br/>',NULL,9286,9286);
INSERT INTO stanza VALUES('C399','chorus','神的心意所喜所愛：<br/>基督作到我裡面；<br/>不是有何外面成就，<br/>乃讓基督來擴展。<br/>',NULL,9287,9287);
INSERT INTO stanza VALUES('C399','2','神的心意所喜所愛：<br/>基督活在我裡面；<br/>不是注意外面事工，<br/>乃享基督作恩典。<br/>',NULL,9288,9288);
INSERT INTO stanza VALUES('C399','3','神的心意所喜所愛：<br/>基督成形我魂間；<br/>不是跟隨外面儀式，<br/>乃讓基督時加添。<br/>',NULL,9289,9289);
INSERT INTO stanza VALUES('C399','4','神的心意所喜所愛：<br/>基督安家在心頭；<br/>不僅外面對祂事奉，<br/>更讓基督全佔有。<br/>',NULL,9290,9290);
INSERT INTO stanza VALUES('C399','5','神的心意所喜所愛：<br/>基督成為我盼望；<br/>不是外面客觀榮耀，<br/>乃是基督作榮光。<br/>',NULL,9291,9291);
INSERT INTO stanza VALUES('C399','6','神的心意所喜所愛：<br/>基督居衷作一切；<br/>不是外面有何得著，<br/>乃有基督作祕訣。<br/>',NULL,9292,9292);
INSERT INTO stanza VALUES('C400','1','哦主，在我你是生命，<br/>對我也是一切；<br/>何其親切、何其便利，<br/>永遠取用不竭！<br/>',NULL,9293,9293);
INSERT INTO stanza VALUES('C400','chorus','哦主，你是生命之靈，<br/>對我何親何近！<br/>親切、便利，令人讚賞，<br/>又是甜美、常新。<br/>',NULL,9294,9294);
INSERT INTO stanza VALUES('C400','2','對於我的大小需要，<br/>你是豐富供應；<br/>何其全備、何其充足，<br/>我得應用於靈。<br/>',NULL,9295,9295);
INSERT INTO stanza VALUES('C400','3','你作膏油塗抹、運行，<br/>時常顧我軟弱；<br/>藉你能力無限供應，<br/>使我剛強、靈活。<br/>',NULL,9296,9296);
INSERT INTO stanza VALUES('C400','4','生命之律靈中規律，<br/>使我得享自由；<br/>你的實際所有豐富，<br/>將我全人浸透。<br/>',NULL,9297,9297);
INSERT INTO stanza VALUES('C400','5','你是與我永遠成一，<br/>無比神聖聯結；<br/>永遠與我成為一靈，<br/>永遠不再隔絕。<br/>',NULL,9298,9298);
INSERT INTO stanza VALUES('C400','6','願你在我全人居衷，<br/>在我心中安家；<br/>一部一部、榮上加榮，<br/>將我全人變化。<br/>',NULL,9299,9299);
INSERT INTO stanza VALUES('C401','1','我今得著何等自由，<br/>基督已經釋放我！<br/>罪的權勢、死的毒鉤，<br/>從我身上全脫落！<br/>',NULL,9300,9300);
INSERT INTO stanza VALUES('C401','chorus','基督使我得勝有餘，<br/>仗祂十架我誇勝！<br/>生命大能、聖靈的律，<br/>使我剛強而有能！<br/>',NULL,9301,9301);
INSERT INTO stanza VALUES('C401','2','基督使我脫離律法，<br/>永遠向著律法死；<br/>完全活在恩典之下，<br/>不受律法的挾制。<br/>',NULL,9302,9302);
INSERT INTO stanza VALUES('C401','3','基督已經定罪了罪，<br/>除掉罪惡的權勢；<br/>罪在我身再無地位，<br/>我從罪裡得開釋。<br/>',NULL,9303,9303);
INSERT INTO stanza VALUES('C401','4','基督已經將死廢去，<br/>顯出不壞的生命；<br/>勝過死亡頑強禁拘，<br/>彰顯復活的大能。<br/>',NULL,9304,9304);
INSERT INTO stanza VALUES('C401','5','基督已經毀壞撒但，<br/>審判世界和邪靈；<br/>使我脫離黑暗、死權，<br/>進入光明與生命。<br/>',NULL,9305,9305);
INSERT INTO stanza VALUES('C401','6','基督賜我彀用恩典，<br/>用祂能力覆庇我；<br/>在我軟弱顯得完全，<br/>使我喜歡誇軟弱。<br/>',NULL,9306,9306);
INSERT INTO stanza VALUES('C402','1','不是字句律法，<br/>乃是生命主，<br/>神願賜給我們，<br/>救我脫重負；<br/>不是任何道理，<br/>乃是主基督，<br/>使我脫離自己，<br/>不再作罪奴。<br/>',NULL,9307,9307);
INSERT INTO stanza VALUES('C402','2','任何一種儀式，<br/>任何的教訓，<br/>不能點活我靈，<br/>不能變化魂；<br/>乃是活的基督，<br/>賜給我生命，<br/>使我活出神命，<br/>照神所命定。<br/>',NULL,9308,9308);
INSERT INTO stanza VALUES('C402','3','不是任何哲學，<br/>任何的倫理，<br/>能照基督模出<br/>祂的眾肢體；<br/>乃是基督自己，<br/>在我人性裡，<br/>藉祂復活大能，<br/>作成祂身體。<br/>',NULL,9309,9309);
INSERT INTO stanza VALUES('C402','4','不是任何宗教，<br/>也非基督教，<br/>能將神旨成就，<br/>彀上神所要；<br/>乃是內住基督，<br/>作我的一切，<br/>成全神的心意，<br/>問題全解決。<br/>',NULL,9310,9310);
INSERT INTO stanza VALUES('C402','5','我們從主所得<br/>恩賜與功用，<br/>全都不能頂替<br/>基督的內容；<br/>必須基督自己<br/>作我的一切，<br/>惟有基督自己<br/>是我之所缺。<br/>',NULL,9311,9311);
INSERT INTO stanza VALUES('C403','1','哦，我主的神聖豐富，<br/>深闊無人能測透；<br/>神性所有一切豐富，<br/>在祂全歸我享受。<br/>',NULL,9312,9312);
INSERT INTO stanza VALUES('C403','chorus','神聖豐富！榮耀豐富！<br/>基督豐富全為我！<br/>深廣無限，人難測度，<br/>卻成實際我得著！<br/>',NULL,9313,9313);
INSERT INTO stanza VALUES('C403','2','哦，我主的神聖豐富，<br/>一切一切全包括：<br/>生命、亮光、<br/>智慧、能力、<br/>醫治、平安和喜樂。<br/>',NULL,9314,9314);
INSERT INTO stanza VALUES('C403','3','完全救贖、豐滿救恩、<br/>稱義、成聖並釋放、<br/>復活大能、升天超越，<br/>神所喜愛的寶藏！<br/>',NULL,9315,9315);
INSERT INTO stanza VALUES('C403','4','哦，我主的神聖豐富，<br/>乃是神來作一切！<br/>凡神所是並祂所有，<br/>全在我靈被領略。<br/>',NULL,9316,9316);
INSERT INTO stanza VALUES('C403','5','哦，我主的神聖豐富，<br/>誰能窮知其所有！<br/>長、闊、高、深，<br/>無法測量，<br/>卻都作了我享受！<br/>',NULL,9317,9317);
INSERT INTO stanza VALUES('C403','6','願我認識我主豐富，<br/>豐滿經歷神基督；<br/>並與別人共同分享，<br/>使神心滿、我意足。<br/>',NULL,9318,9318);
INSERT INTO stanza VALUES('C404','1','祂帶領我，此意何美！<br/>此言充滿天上安慰！<br/>處處、事事、<br/>所是、所作，<br/>都有主手來帶領我。<br/>',NULL,9319,9319);
INSERT INTO stanza VALUES('C404','chorus','祂帶領我，祂帶領我，<br/>祂是親手在帶領我；<br/>不分時地，我都隨著，<br/>因祂親手在帶領我。<br/>',NULL,9320,9320);
INSERT INTO stanza VALUES('C404','2','有時似墮痛苦深淵，<br/>有時似在快樂伊甸；<br/>或遇平順，或遭風波，<br/>都有主手來帶領我。<br/>',NULL,9321,9321);
INSERT INTO stanza VALUES('C404','3','主阿，願你緊握我手，<br/>領我一生隨你而走；<br/>是福是苦由你定奪，<br/>只要你手來帶領我。<br/>',NULL,9322,9322);
INSERT INTO stanza VALUES('C404','4','等我行完今生路程，<br/>靠你恩典完全得勝；<br/>死河寒波我亦不躲，<br/>因你至終親手領我。<br/>',NULL,9323,9323);
INSERT INTO stanza VALUES('C405','1','恩主，我愛你，<br/>我深知你屬我；<br/>一切罪中樂，<br/>我為你全擺脫。<br/>你是我救主，<br/>曾流血將我買；<br/>如果我愛你，<br/>主耶穌，是現在！<br/>',NULL,9324,9324);
INSERT INTO stanza VALUES('C405','2','恩主，我愛你，<br/>因為你先愛我，<br/>為我在加略<br/>將贖價已付妥。<br/>愛你，是因為<br/>荊棘冕你肯戴；<br/>如果我愛你，<br/>主耶穌，是現在！<br/>',NULL,9325,9325);
INSERT INTO stanza VALUES('C405','3','活著我愛你，<br/>到死了也愛你；<br/>並要讚美你，<br/>只要你給氣息。<br/>即是死臨到，<br/>我仍然要表白：<br/>如果我愛你，<br/>主耶穌，是現在！<br/>',NULL,9326,9326);
INSERT INTO stanza VALUES('C405','4','在那無止境<br/>喜樂的榮耀裡，<br/>我要在光中<br/>到永遠敬拜你；<br/>頭戴榮耀冕，<br/>我還要唱出來：<br/>如果我愛你，<br/>主耶穌，是現在。<br/>',NULL,9327,9327);
INSERT INTO stanza VALUES('C406','1','交通何甜美，<br/>喜樂何豐盈，<br/>安息在那永久膀臂中；<br/>福氣何全備，<br/>平安何神聖，<br/>安息在那永久膀臂中。<br/>',NULL,9328,9328);
INSERT INTO stanza VALUES('C406','chorus','安息！安息！<br/>平安穩妥，一無驚恐；<br/>安息！安息！<br/>安息在那永久膀臂中。<br/>',NULL,9329,9329);
INSERT INTO stanza VALUES('C406','2','今行這旅程，<br/>心中滿平安，<br/>安息在那永久膀臂中；<br/>越行越光明，<br/>恩光照燦爛，<br/>安息在那永久膀臂中。<br/>',NULL,9330,9330);
INSERT INTO stanza VALUES('C406','3','有何我所懼？<br/>有何我所怕？<br/>安息在那永久膀臂中；<br/>與主永同居，<br/>平安無復加，<br/>安息在那永久膀臂中。<br/>',NULL,9331,9331);
INSERT INTO stanza VALUES('C407','1','救主耶穌，我的太陽，<br/>有你同在夜也明亮，<br/>勿讓人世有雲遮掩<br/>僕人心眼不見慈顏。<br/>',NULL,9332,9332);
INSERT INTO stanza VALUES('C407','2','倦眼欲合，頻頻催眠，<br/>睡如甘露，潤我夕薦，<br/>深願今晚最後思念，<br/>乃是永世息你胸前。<br/>',NULL,9333,9333);
INSERT INTO stanza VALUES('C407','3','與我同在自晨至夕，<br/>離你我覺生無意義，<br/>無你我懼死蔭臨到，<br/>求你相偕自晚至朝。<br/>',NULL,9334,9334);
INSERT INTO stanza VALUES('C407','4','當我睡醒，求主賜福，<br/>扶我行走人生路途，<br/>直至那日被提你旁，<br/>溶化在你愛的海洋。<br/>',NULL,9335,9335);
INSERT INTO stanza VALUES('C408','1','你名似膏香，<br/>你愛比酒美，<br/>你若來吸引，<br/>有誰不跟隨？<br/>我們若跟隨<br/>羊群的腳蹤，<br/>我們必進入<br/>你愛的交通。<br/>',NULL,9336,9336);
INSERT INTO stanza VALUES('C408','2','祂是我良人，<br/>我是祂佳偶，<br/>祂將我吸引，<br/>我將祂追求；<br/>祂香如沒藥，<br/>我願藏心房，<br/>祂美似鳳仙，<br/>我願戴身上。<br/>',NULL,9337,9337);
INSERT INTO stanza VALUES('C408','3','進入祂愛裡，<br/>享受祂肥甘，<br/>躺在祂懷中，<br/>飽嘗祂香甜；<br/>祂愛為旌旗，<br/>將我身遮藏，<br/>祂情似美物，<br/>使我心舒暢。<br/>',NULL,9338,9338);
INSERT INTO stanza VALUES('C408','4','良人屬於我，<br/>我也屬於祂，<br/>祂是牧養者，<br/>我是百合花。<br/>惟願天快曙，<br/>黑影全飛散，<br/>見祂如朝鹿，<br/>顯在比特山。<br/>',NULL,9339,9339);
INSERT INTO stanza VALUES('C408','5','同死的沒藥，<br/>復活的乳香，<br/>來將我薰透，<br/>好給祂欣賞；<br/>北風阿，興起，<br/>南風阿，吹來，<br/>來使我心園，<br/>成為祂心愛。<br/>',NULL,9340,9340);
INSERT INTO stanza VALUES('C408','6','願在祂眼中，<br/>美麗如良鴿，<br/>願在祂面前，<br/>皎潔似百合；<br/>願我全屬祂，<br/>作祂樂中樂，<br/>像祂全屬我，<br/>是我歌中歌。<br/>',NULL,9341,9341);
INSERT INTO stanza VALUES('C408','7','美麗如月亮，<br/>得有祂形像，<br/>皎潔似太陽，<br/>得有祂身量；<br/>全屬我良人，<br/>使祂命顯彰，<br/>全為我良人，<br/>使祂心舒暢。<br/>',NULL,9342,9342);
INSERT INTO stanza VALUES('C408','8','你是我生命，<br/>我是你活像，<br/>愛情的聯結，<br/>如死之堅強，<br/>無何能消滅，<br/>無何能替換，<br/>直到你顯現，<br/>在那香草山。<br/>',NULL,9343,9343);
INSERT INTO stanza VALUES('C409','1','我有一位好朋友，<br/>我是非常寶貴；<br/>祂是愛我如此溫柔，<br/>祂愛非常甜美；<br/>我不能活無祂之處，<br/>我愛祂的提握；<br/>所以我們就同住，<br/>我主與我。<br/>',NULL,9344,9344);
INSERT INTO stanza VALUES('C409','2','有時我幾乎臥倒，<br/>祂知我的軟弱，<br/>當祂叫我向祂倚靠，<br/>我樂受祂扶托；<br/>祂帶我走光明途徑，<br/>日過光明生活；<br/>所以我們就同行，<br/>我主與我。<br/>',NULL,9345,9345);
INSERT INTO stanza VALUES('C409','3','祂知我愛祂幾多，<br/>祂知我愛淺深；<br/>但祂是用何愛愛我，<br/>我永不能說清；<br/>乃是一愛永遠不衰，<br/>越過越像熱火；<br/>所以彼此就相愛，<br/>我主與我。<br/>',NULL,9346,9346);
INSERT INTO stanza VALUES('C409','4','我告祂以我痛苦，<br/>告祂以我歡喜；<br/>我告祂以我所羨慕，<br/>告祂以我刺激；<br/>祂告我以所當策勵，<br/>告我以所當作；<br/>我們彼此吐心意，<br/>我主與我。<br/>',NULL,9347,9347);
INSERT INTO stanza VALUES('C409','5','祂知我心真羨慕<br/>能救一個靈魂，<br/>祂就叫我為祂外出，<br/>去報愛的新聞；<br/>祂叫我說祂的奇愛，<br/>並祂受死經過；<br/>我們如此常同在，<br/>我主與我。<br/>',NULL,9348,9348);
INSERT INTO stanza VALUES('C409','6','祂告我以祂國度<br/>離此並不太遠；<br/>祂心切望能彀儘速<br/>把我帶到那邊；<br/>無終幸福，喜樂在望，<br/>還有榮耀寶座，<br/>不久我們同作王，<br/>我主與我。<br/>',NULL,9349,9349);
INSERT INTO stanza VALUES('C410','1','哦，在榮耀裡的基督，<br/>已將我心全照亮；<br/>非像微星暗中光顧，<br/>乃是明光勝太陽。<br/>地上全是黑暗、陰影，<br/>無何能以得我心，<br/>惟祂所行艱苦途徑，<br/>值得我心來寶珍。<br/>',NULL,9350,9350);
INSERT INTO stanza VALUES('C410','2','世人乃靠屬地之光，<br/>艱苦疲困度人生；<br/>我見之光來自天上，<br/>遠勝午日放光明：<br/>毫無遮蔽，永不衰虧，<br/>使我得見祂榮面，<br/>和祂愛的無限寶貴，<br/>並祂恩典的豐滿。<br/>',NULL,9351,9351);
INSERT INTO stanza VALUES('C410','3','得見祂的奇妙榮耀，<br/>並祂更妙的奇愛，<br/>如何為我已經得到<br/>高超地位到萬代。<br/>幔子已撤，非僅一瞥，<br/>乃是幔內來安居；<br/>注視祂面無間無歇，<br/>得聽隱密的話語。<br/>',NULL,9352,9352);
INSERT INTO stanza VALUES('C410','4','我已看見基督榮面，<br/>別事請勿向我題；<br/>我已聽見祂的恩言，<br/>這已彀使我滿意。<br/>藉祂榮耀所發光輝，<br/>有福榮面我已見，<br/>這個榮耀且要成為<br/>我的住處到永遠。<br/>',NULL,9353,9353);
INSERT INTO stanza VALUES('C411','1','夕陽西沉大地靜，<br/>蝟務完畢我心定，<br/>晚星高照暗中明，<br/>幽夜近主靈裡清，<br/>靜候俯伏。<br/>',NULL,9354,9354);
INSERT INTO stanza VALUES('C411','chorus','近乎，近乎，近乎，<br/>可近之主！<br/>我心所羨靈所慕，<br/>是你可愛的面目，<br/>可親之主！<br/>',NULL,9355,9355);
INSERT INTO stanza VALUES('C411','2','在這宇宙廣廈中，<br/>我心尋求你面容，<br/>深願能在我四圍，<br/>所見全是你光輝，<br/>使我滿足。<br/>',NULL,9356,9356);
INSERT INTO stanza VALUES('C411','3','當這夜影越幽深，<br/>我心切慕越殷勤，<br/>願能衝過眾星辰，<br/>得見你面近你身，<br/>永不孤苦。<br/>',NULL,9357,9357);
INSERT INTO stanza VALUES('C411','4','到這黑夜與星辰，<br/>從我眼前全逝遜，<br/>願那永遠的早晨，<br/>為我帶來你榮身，<br/>夜影俱無。<br/>',NULL,9358,9358);
INSERT INTO stanza VALUES('C412','1','恩主，我今憑信摸你，<br/>你是供給的源頭；<br/>憑信取用你的能力，<br/>藉你寶血來領受。<br/>',NULL,9359,9359);
INSERT INTO stanza VALUES('C412','chorus','摸你，就得生命供應，<br/>藉著你靈的運行；<br/>你靈將我純潔、充盈，<br/>使我得享你豐盛。<br/>',NULL,9360,9360);
INSERT INTO stanza VALUES('C412','2','憑信取用，憑信摸你，<br/>憑信應用你豐富；<br/>我的全人向你開啟，<br/>你之所是向我注。<br/>',NULL,9361,9361);
INSERT INTO stanza VALUES('C412','3','摸你，恩主，摸你更深，<br/>摸而取用你豐盛；<br/>從你接受，恩上加恩，<br/>我就流露你生命。<br/>',NULL,9362,9362);
INSERT INTO stanza VALUES('C412','4','能力、智慧、<br/>慈愛、恩寵，<br/>凡我需要你供應；<br/>使我摸你，使我取用，<br/>摸你、取用，不稍停。<br/>',NULL,9363,9363);
INSERT INTO stanza VALUES('C413','1','無別聲音破此靜寂，<br/>無別蹤跡侵擾此光景，<br/>只有祂美麗、<br/>寶貝的自己，<br/>和祂可愛的柔聲。<br/>',NULL,9364,9364);
INSERT INTO stanza VALUES('C413','chorus','寶貝的救主、<br/>親愛的耶穌，<br/>可否求你向我說出：<br/>你曾為何故，<br/>你究是何如，<br/>在這安靜屬天處？<br/>',NULL,9365,9365);
INSERT INTO stanza VALUES('C413','2','安靜之中有祂蒞止，<br/>祂向我密語，深入我心，<br/>帶我進內室，<br/>向我表意思，<br/>說祂是我的愛人。<br/>',NULL,9366,9366);
INSERT INTO stanza VALUES('C413','3','在此就是屬天聖境，<br/>不許有聲音，<br/>一切安靜；<br/>我喜樂來近，<br/>我渴求來飲<br/>你肯表露的愛情。<br/>',NULL,9367,9367);
INSERT INTO stanza VALUES('C413','4','在這俯伏安靜之中，<br/>主耶穌，我不敢稍動彈；<br/>恐有音失蹤，<br/>恐有語落空，<br/>我失你愛的片段。<br/>',NULL,9368,9368);
INSERT INTO stanza VALUES('C413','5','我魂，當息！<br/>我心，當足！<br/>你已達到最高快樂間：<br/>安臥你救主親愛的胸府，<br/>注視祂的可愛面。<br/>',NULL,9369,9369);
INSERT INTO stanza VALUES('C414','1','進入幔內，<br/>就必出到營外，<br/>嘗到天美，<br/>就必丟棄地愛；<br/>聖中之聖如果滿足我心，<br/>空中之空豈能欺騙我魂？<br/>',NULL,9370,9370);
INSERT INTO stanza VALUES('C414','2','進入幔內，<br/>就必出到營外，<br/>天一同在，<br/>就必使地離開；<br/>天上榮耀如果吸引我靈，<br/>地上福樂豈能霸佔我情？<br/>',NULL,9371,9371);
INSERT INTO stanza VALUES('C414','3','進入幔內，<br/>瞻仰榮耀基督，<br/>出到營外，<br/>跟隨卑微耶穌；<br/>寶座、冠冕，<br/>如果將我鼓舞，<br/>馬槽、十架，<br/>豈能使我裹足？<br/>',NULL,9372,9372);
INSERT INTO stanza VALUES('C414','4','進入幔內，<br/>吸取復活大能，<br/>出到營外，<br/>奔跑十架路程；<br/>我若看見祂在天上面容，<br/>就必步武祂在地上腳蹤。<br/>',NULL,9373,9373);
INSERT INTO stanza VALUES('C414','5','進入幔內，<br/>飽嘗天上肥甘，<br/>出到營外，<br/>忍受地上艱難；<br/>地上經歷雖使我心酸痛，<br/>天上交通卻叫我靈讚頌。<br/>',NULL,9374,9374);
INSERT INTO stanza VALUES('C414','6','進入幔內，<br/>享受主的上好，<br/>出到營外，<br/>供應人的需要；<br/>天上生命如果從我活出，<br/>地上靈魂就必因我得福。<br/>',NULL,9375,9375);
INSERT INTO stanza VALUES('C414','7','進入幔內，<br/>直到幔子不存，<br/>出到營外，<br/>直到營都滅盡；<br/>直到天地所有同歸於一，<br/>直到神、人永遠<br/>不再分離。<br/>',NULL,9376,9376);
INSERT INTO stanza VALUES('C415','1','在祂同在的祕密處，<br/>我得安居何甘美！<br/>在祂面前時常俯伏，<br/>所學功課何寶貴！<br/>憂慮不能將我攪擾，<br/>試煉也不能壓住；<br/>每逢撒但引誘吼叫，<br/>我就到祂隱密處，<br/>我就到祂隱密處。<br/>',NULL,9377,9377);
INSERT INTO stanza VALUES('C415','2','當我帶著疲倦、乾渴，<br/>來到祂的翅膀間，<br/>就得蔭庇、涼爽、快樂，<br/>活泉清澈而新鮮；<br/>在此投身救主胸懷，<br/>彼此交通滿香甜；<br/>我雖嘗試，也說不來<br/>祂那祕密的語言。<br/>',NULL,9378,9378);
INSERT INTO stanza VALUES('C415','3','但有一事是我所知：<br/>當我向祂訴苦情，<br/>祂就耐心聽我心事，<br/>並且鼓舞我萎靈。<br/>你想從來祂不責備？<br/>那祂就是很虛偽，<br/>如果祂是從來也未<br/>責備祂所見的罪。<br/>',NULL,9379,9379);
INSERT INTO stanza VALUES('C415','4','這隱密處如何美佳，<br/>如果你也願知曉，<br/>請去住在祂的蔭下，<br/>就必嘗到這味道；<br/>若你的靈與祂相交，<br/>安靜住於祂榮光，<br/>你的臉面就必返照<br/>祂那榮美的形像。<br/>',NULL,9380,9380);
INSERT INTO stanza VALUES('C416','1','我已相信真事實，<br/>我已接受主的死，<br/>我已經過外院子，<br/>阿利路亞，讚美主！<br/>藉主贖罪的寶血，<br/>我得歸神成聖潔，<br/>不再有分於罪孽，<br/>阿利路亞，讚美主！<br/>',NULL,9381,9381);
INSERT INTO stanza VALUES('C416','chorus','阿利路亞！阿利路亞！<br/>裂開幔子我已過，<br/>這裡榮耀不敗落！<br/>阿利路亞！阿利路亞！<br/>我今在我王的面前<br/>過生活！<br/>',NULL,9382,9382);
INSERT INTO stanza VALUES('C416','2','外層幔子我已過，<br/>進入頭層的聖所，<br/>神聖供應全得著，<br/>阿利路亞，讚美主！<br/>我今與神已和諧，<br/>經過祭壇全聖別，<br/>神外世界永棄絕，<br/>阿利路亞，讚美主！<br/>',NULL,9383,9383);
INSERT INTO stanza VALUES('C416','3','內層幔子我也過，<br/>進入二層至聖所，<br/>來到神的施恩座，<br/>阿利路亞，讚美主！<br/>今在神前過生活，<br/>以神作我的居所，<br/>不再有己的間隔，<br/>阿利路亞，讚美主！<br/>',NULL,9384,9384);
INSERT INTO stanza VALUES('C416','4','我今是神的祭司，<br/>經過救贖纔如此，<br/>身分地位何確實，<br/>阿利路亞，讚美主！<br/>我今是在靈裡面，<br/>活在神的榮耀前，<br/>夜以繼晝不間斷，<br/>阿利路亞，讚美主！<br/>',NULL,9385,9385);
INSERT INTO stanza VALUES('C417','1','夜影尚存，晨光未現，<br/>重新來到恩主面前；<br/>祂在裡面放明、照耀，<br/>我得看見祂的榮顏。<br/>向我發言、給我看見：<br/>祂的豐富是為今天；<br/>甜美、歡樂，將祂享受，<br/>所有飢餓全變飽滿。<br/>',NULL,9386,9386);
INSERT INTO stanza VALUES('C417','2','主靈藉話與我交談，<br/>直到我心發出頌讚，<br/>生命活泉，帶著恩力，<br/>在我裡面湧流潺潺。<br/>向我發言、給我看見：<br/>祂的豐富是為今天；<br/>清爽、暢快，將祂歡飲，<br/>所有乾渴全都消減。<br/>',NULL,9387,9387);
INSERT INTO stanza VALUES('C417','3','當我歡留於祂面光，<br/>祂以溫情對付、指點；<br/>用祂神聖、寶貴成分，<br/>浸透全人、供應無限。<br/>向我發言、給我看見：<br/>祂的豐富是為今天；<br/>多方、豐滿將祂享受，<br/>所有問題全都逃竄！<br/>',NULL,9388,9388);
INSERT INTO stanza VALUES('C418','1','住在主裡面，<br/>無上的福氣，<br/>常與主交通，<br/>甜美的經歷；<br/>住在主裡面，<br/>主與我聯合，<br/>常與主交通，<br/>我與主無隔。<br/>',NULL,9389,9389);
INSERT INTO stanza VALUES('C418','2','住在主裡面，<br/>恩膏必運行，<br/>常與主交通，<br/>聖靈必引領；<br/>順服主恩膏，<br/>得享主肥甘，<br/>跟隨主聖靈，<br/>必作主同伴。<br/>',NULL,9390,9390);
INSERT INTO stanza VALUES('C418','3','住在主裡面，<br/>恩光必照明，<br/>常與主交通，<br/>黑影必除淨；<br/>恩光一順從，<br/>生命必增長，<br/>黑影全脫離，<br/>心、靈纔舒暢。<br/>',NULL,9391,9391);
INSERT INTO stanza VALUES('C418','4','住在主裡面，<br/>軟弱變剛強，<br/>常與主交通，<br/>生命吞死亡；<br/>住在主裡面，<br/>歎息變歌唱，<br/>常與主交通，<br/>喜樂代憂傷。<br/>',NULL,9392,9392);
INSERT INTO stanza VALUES('C418','5','住在主裡面，<br/>撒但難攻擊，<br/>常與主交通，<br/>世界失吸力；<br/>住在主裡面，<br/>罪惡無權勢，<br/>常與主交通，<br/>自己必消逝。<br/>',NULL,9393,9393);
INSERT INTO stanza VALUES('C418','6','住在主裡面，<br/>模成主榮形，<br/>常與主交通，<br/>充滿主生命；<br/>住在主裡面，<br/>經歷主大能，<br/>常與主交通，<br/>吸取主豐盛。<br/>',NULL,9394,9394);
INSERT INTO stanza VALUES('C418','7','住在主裡面，<br/>心、靈在渴慕，<br/>常與主交通，<br/>聖靈在催促；<br/>惟願我全人<br/>浸在主裡面，<br/>與主溶為一，<br/>從今到永遠。<br/>',NULL,9395,9395);
INSERT INTO stanza VALUES('C419','1','我主，你說你是真樹，<br/>我是你的真枝子；<br/>但我不知為何緣故，<br/>我是如此不結實。<br/>',NULL,9396,9396);
INSERT INTO stanza VALUES('C419','2','我心羨慕結果更多，<br/>更能彰顯你生命；<br/>更能榮耀歸與寶座，<br/>更能禱告得答應。<br/>',NULL,9397,9397);
INSERT INTO stanza VALUES('C419','3','但是，主阿，我不明白<br/>『常在裡面』的聖言；<br/>我越追求要去『常在，』<br/>我越發現在外邊。<br/>',NULL,9398,9398);
INSERT INTO stanza VALUES('C419','4','我不覺得我在裡面，<br/>我也禱告並立志！<br/>但你都像隔開很遠，<br/>生命仍然無果子。<br/>',NULL,9399,9399);
INSERT INTO stanza VALUES('C419','5','但你是說，你已是樹，<br/>我也已是你枝子；<br/>當我信你作我救主，<br/>聖靈已成此事實。<br/>',NULL,9400,9400);
INSERT INTO stanza VALUES('C419','6','我今已是在你裡面，<br/>再也不必求加入；<br/>我是已經與你結聯，<br/>完全合一的骨肉。<br/>',NULL,9401,9401);
INSERT INTO stanza VALUES('C419','7','祕訣不是要我『去在，』<br/>事實是我『已在』內；<br/>所求乃是不要離開，<br/>不是如何得地位。<br/>',NULL,9402,9402);
INSERT INTO stanza VALUES('C419','8','我已在內，已在你內！<br/>這是神作的事實！<br/>不必禱告，不必行為，<br/>乃是神手的設施。<br/>',NULL,9403,9403);
INSERT INTO stanza VALUES('C419','9','我已在內怎求入內，<br/>我是何等的愚昧，<br/>現今我只歡樂讚美，<br/>相信聖言的無偽。<br/>',NULL,9404,9404);
INSERT INTO stanza VALUES('C419','10','我今只有完全安息，<br/>知道你是我一切，<br/>你是生命、你是能力，<br/>而我一切都了結。<br/>',NULL,9405,9405);
INSERT INTO stanza VALUES('C420','1','住在你裡面，<br/>這是我心願，<br/>住在你裡面，<br/>時刻不間斷；<br/>枝子如何與葡萄樹相聯，<br/>我也深願，<br/>主，住在你裡面。<br/>',NULL,9406,9406);
INSERT INTO stanza VALUES('C420','2','住在你裡面，<br/>你富我享受，<br/>你所是一切，<br/>得藉我流露；<br/>願作你身上常新的枝子，<br/>彰顯你生命，<br/>結果永不止。<br/>',NULL,9407,9407);
INSERT INTO stanza VALUES('C420','3','住在你裡面，<br/>罪、己失權能，<br/>再無法勝過你內住生命；<br/>與你相結聯，<br/>深處互交通，<br/>靈就能管治魂一切活動。<br/>',NULL,9408,9408);
INSERT INTO stanza VALUES('C420','4','住在你裡面，<br/>得知你心意，<br/>摸著你同在，<br/>進入你祕密；<br/>喜樂與平安要將我充溢，<br/>你話的供應也作我能力。<br/>',NULL,9409,9409);
INSERT INTO stanza VALUES('C421','1','無你，我就無法想，<br/>不能立定地位，<br/>我無力量和善良，<br/>我無自己智慧；<br/>但你，親愛的救主，<br/>一切中的一切，<br/>軟弱要變成祝福，<br/>如果我被提挈。<br/>',NULL,9410,9410);
INSERT INTO stanza VALUES('C421','2','無你，我就無法想，<br/>這路何等的長，<br/>我是疲倦身不強，<br/>歎息代替詩章；<br/>我怎可以能無你？<br/>我並不能識路；<br/>但你識路直到底，<br/>不肯讓我迷途。<br/>',NULL,9411,9411);
INSERT INTO stanza VALUES('C421','3','無你，我就無法想，<br/>耶穌，親愛救主；<br/>就是我眼無印象，<br/>你仍親近無誤；<br/>何等孤單何等痛，<br/>在這生疏人地，<br/>若無甘甜的交通，<br/>若無你的安息。<br/>',NULL,9412,9412);
INSERT INTO stanza VALUES('C421','4','無你，我就無法想，<br/>無人能彀認識<br/>我靈奇深的意向，<br/>將牠需要解釋；<br/>我心祕密的角落，<br/>無人能彀進入，<br/>來慰、來靜並來託，<br/>只有你能，我主。<br/>',NULL,9413,9413);
INSERT INTO stanza VALUES('C421','5','無你，我就無法想，<br/>年日已經不多，<br/>我是須與人同樣<br/>孤獨渡河而過；<br/>但你永遠不離開，<br/>不管浪有幾多，<br/>我知你仍要施愛，<br/>並低聲說：『是我。』<br/>',NULL,9414,9414);
INSERT INTO stanza VALUES('C422','1','主，我還有誰在天上？<br/>惟有你！惟有你！<br/>我的一生只此可唱：<br/>主為我！主為我！<br/>祂已為我流血辛勞，<br/>祂作我的贖罪羊羔，<br/>使我這人與神和好，<br/>主為我！主為我！<br/>',NULL,9415,9415);
INSERT INTO stanza VALUES('C422','2','我不追求自私福氣，<br/>我要主！我要主！<br/>我不羨慕鍍金玩意，<br/>我要主！我要主！<br/>自私福氣不能長久，<br/>性質規定瞬息罷休，<br/>我的喜樂永遠存留，<br/>我要主！我要主！<br/>',NULL,9416,9416);
INSERT INTO stanza VALUES('C422','3','我今棄絕為富思想，<br/>主為我！主為我！<br/>我不盼望自己安享，<br/>主為我！主為我！<br/>無花果樹雖不發旺，<br/>葡萄、橄欖無一可享，<br/>棚內無牛、圈中無羊，<br/>主為我！主為我！<br/>',NULL,9417,9417);
INSERT INTO stanza VALUES('C422','4','我心現今完全安息，<br/>主為我！主為我！<br/>不怕試煉常來攻擊，<br/>主為我！主為我！<br/>任憑引誘力量洶湧，<br/>我們靠主能彀強勇，<br/>能彀冷笑牠們無用，<br/>主為我！主為我！<br/>',NULL,9418,9418);
INSERT INTO stanza VALUES('C422','5','當我人生路程將畢，<br/>我要主！我要主！<br/>安全倚靠祂的手臂，<br/>我要主！我要主！<br/>我的軀殼雖有痛苦，<br/>所有自然力量都無，<br/>我仍高聲歌唱歡呼，<br/>我要主！我要主！<br/>',NULL,9419,9419);
INSERT INTO stanza VALUES('C423','1','意志薄弱，能力軟弱，<br/>盼望已經全都消滅；<br/>只有信託你的工作<br/>將我這人溫柔提挈。<br/>',NULL,9420,9420);
INSERT INTO stanza VALUES('C423','2','盡我所有，所有失敗，<br/>失敗至今，失敗頻仍；<br/>無何可信，信你能耐，<br/>能彀抓我聽你命令。<br/>',NULL,9421,9421);
INSERT INTO stanza VALUES('C423','3','當我的心稍微高仰，<br/>我就近乎跌倒危地；<br/>我不敢作，我不敢想，<br/>事事處處，我需要你。<br/>',NULL,9422,9422);
INSERT INTO stanza VALUES('C423','4','你是救主…剛強…體貼，<br/>哦主，我今尋求你面；<br/>雖然我是弱中弱者，<br/>我的能力是你恩典。<br/>',NULL,9423,9423);
INSERT INTO stanza VALUES('C424','1','我心安息在於主！<br/>這纔真是安息！<br/>除此，全能的耶穌，<br/>罪人有何希冀？<br/>你光是我的智慧，<br/>你愛是我奮勉；<br/>你在榮耀的地位，<br/>天天引我進前。<br/>',NULL,9424,9424);
INSERT INTO stanza VALUES('C424','2','我罪雖大無法比，<br/>你賜恩典更大；<br/>你是羔羊來獻祭，<br/>你死我免受罰；<br/>我從罪中得釋放，<br/>就從灰塵重回；<br/>你話是我的亮光，<br/>你血是我寶貝。<br/>',NULL,9425,9425);
INSERT INTO stanza VALUES('C424','3','溫柔的主，你目的，<br/>惟願從我得成；<br/>為著遵行你旨意，<br/>我今奉獻此生。<br/>我雖是真的軟弱，<br/>可是你是能力；<br/>你的子民萬事綽，<br/>只要他們有你。<br/>',NULL,9426,9426);
INSERT INTO stanza VALUES('C424','4','黑雲罩我最黑時，<br/>正是你最近我，<br/>來使我信能堅持，<br/>來教我靈不懦。<br/>在你懷裡我安臥，<br/>注視你的榮顏；<br/>你是我的安息所，<br/>撒但徒然離間。<br/>',NULL,9427,9427);
INSERT INTO stanza VALUES('C424','5','是你使我能喜樂，<br/>是你使我釋放；<br/>因此我要獻詩歌，<br/>向你永遠稱揚。<br/>地上福樂和愛情，<br/>來源縱然全涸，<br/>只須你恩有供應，<br/>或生或死都可。<br/>',NULL,9428,9428);
INSERT INTO stanza VALUES('C425','1','我是受造的瓦器，<br/>寶貝基督放我裡；<br/>我須作祂的器皿，<br/>祂作內容來藏隱。<br/>',NULL,9429,9429);
INSERT INTO stanza VALUES('C425','2','照祂形像我被造，<br/>適合基督來住著；<br/>神使器皿的形狀，<br/>與其內容能相像。<br/>',NULL,9430,9430);
INSERT INTO stanza VALUES('C425','3','祂今居留在我靈，<br/>用祂大能來支撐；<br/>我得與祂成一靈，<br/>受祂實際的供應。<br/>',NULL,9431,9431);
INSERT INTO stanza VALUES('C425','4','天天居衷在感動，<br/>時時調和相交通；<br/>所有腳步祂保守，<br/>每一部分祂浸透。<br/>',NULL,9432,9432);
INSERT INTO stanza VALUES('C425','5','讓祂由衷得表現，<br/>使祂在我被人見；<br/>我須透明又透亮，<br/>祂可藉我得顯彰。<br/>',NULL,9433,9433);
INSERT INTO stanza VALUES('C425','6','變化乃是我所需，<br/>全人破碎無所餘；<br/>泥土得改原形狀，<br/>變成寶貝的模樣。<br/>',NULL,9434,9434);
INSERT INTO stanza VALUES('C426','1','當我同主行動，<br/>在祂話的光中，<br/>何等榮耀照在我全身；<br/>當我肯聽命令，<br/>祂就充滿我靈，<br/>祂充滿信而順從的人。<br/>',NULL,9435,9435);
INSERT INTO stanza VALUES('C426','chorus','信而順從！<br/>因為除此以外，<br/>不能得主的喜愛－惟有信而順從！<br/>',NULL,9436,9436);
INSERT INTO stanza VALUES('C426','2','地無一點黑影、<br/>天無一片暗景<br/>能迷漫，當祂顯露笑容；<br/>沒有疑惑畏懼、<br/>沒有流淚憂慮<br/>能存在，若我信而順從。<br/>',NULL,9437,9437);
INSERT INTO stanza VALUES('C426','3','沒有一個重擔、<br/>沒有一點為難，<br/>祂是不顧，讓我們苦痛；<br/>所有傷心損失、<br/>所有厭棄羞恥<br/>都成祝福，若信而順從。<br/>',NULL,9438,9438);
INSERT INTO stanza VALUES('C426','4','但我不能領會<br/>祂愛何等的美，<br/>若我不放一切於壇社；<br/>因祂所給詩歌、<br/>因祂所賜喜樂<br/>乃是為肯信而順從者。<br/>',NULL,9439,9439);
INSERT INTO stanza VALUES('C426','5','然後在祂光中，<br/>纔有甜美交通，<br/>我就前行，與祂同腳蹤；<br/>祂要求，我就許；<br/>祂差遣，我就去；<br/>不要怕，只要信而順從。<br/>',NULL,9440,9440);
INSERT INTO stanza VALUES('C427','1','我今聽見救主招呼，<br/>我今聽見救主招呼，<br/>我今聽見救主招呼，<br/>要我跟祂，跟祂走窄路。<br/>',NULL,9441,9441);
INSERT INTO stanza VALUES('C427','chorus','無論何處要我跟隨，<br/>無論何時要我跟隨，<br/>無論禍福，無論安危，<br/>要我跟隨，<br/>跟隨，不稍退。<br/>',NULL,9442,9442);
INSERT INTO stanza VALUES('C427','2','我今答應救主招呼，<br/>我今答應救主招呼，<br/>我今答應救主招呼，<br/>甘願一生，<br/>一生，跟隨主。<br/>',NULL,9443,9443);
INSERT INTO stanza VALUES('C427','chorus','無論何處我必跟隨，<br/>無論何時我必跟隨，<br/>無論禍福，無論安危，<br/>我必跟隨，<br/>跟隨，不稍退。<br/>',NULL,9444,9444);
INSERT INTO stanza VALUES('C427','3','撇下親人，捨棄世福，<br/>撇下親人，捨棄世福，<br/>撇下親人，捨棄世福，<br/>甘願一生，<br/>一生，跟隨主。<br/>',NULL,9445,9445);
INSERT INTO stanza VALUES('C427','4','背起十架，行走窄路，<br/>背起十架，行走窄路，<br/>背起十架，行走窄路，<br/>甘願一生，<br/>一生，跟隨主。<br/>',NULL,9446,9446);
INSERT INTO stanza VALUES('C427','5','一直向前，必不回顧，<br/>一直向前，必不回顧，<br/>一直向前，必不回顧，<br/>甘願一生，<br/>一生，跟隨主。<br/>',NULL,9447,9447);
INSERT INTO stanza VALUES('C428','1','跟主行走，心中甜美，<br/>雖然身外有苦楚；<br/>主的腳蹤步步追隨，<br/>天天跟主走窄路。<br/>',NULL,9448,9448);
INSERT INTO stanza VALUES('C428','chorus','步步追，步步隨，<br/>步步跟隨耶穌；<br/>天天追，天天隨，<br/>天天行走窄路。<br/>',NULL,9449,9449);
INSERT INTO stanza VALUES('C428','2','跟主行走，必得光輝，<br/>必見晨光到日午；<br/>主的聲音步步追隨，<br/>時時跟主走窄路。<br/>',NULL,9450,9450);
INSERT INTO stanza VALUES('C428','chorus','步步追，步步隨，<br/>步步跟隨耶穌；<br/>時時追，時時隨，<br/>時時行走窄路。<br/>',NULL,9451,9451);
INSERT INTO stanza VALUES('C428','3','跟主行走，無何可畏，<br/>雖然艱難常四伏；<br/>主的引領步步追隨，<br/>處處跟主走窄路。<br/>',NULL,9452,9452);
INSERT INTO stanza VALUES('C428','chorus','步步追，步步隨，<br/>步步跟隨耶穌；<br/>處處追，處處隨，<br/>處處行走窄路。<br/>',NULL,9453,9453);
INSERT INTO stanza VALUES('C428','4','跟主行走，前途可貴，<br/>必要同主得國度；<br/>主的標竿步步追隨，<br/>一直跟主走窄路。<br/>',NULL,9454,9454);
INSERT INTO stanza VALUES('C428','chorus','步步追，步步隨，<br/>步步跟隨耶穌；<br/>一直追，一直隨，<br/>一直行走窄路。<br/>',NULL,9455,9455);
INSERT INTO stanza VALUES('C429','1','『出到營外』就耶穌，<br/>忍受祂受的凌辱；<br/>祂在城外受苦楚，<br/>我豈可以貪舒服。<br/>',NULL,9456,9456);
INSERT INTO stanza VALUES('C429','2','『出到營外』就耶穌，<br/>十字苦架甘背負；<br/>祂曾走過這窄路，<br/>我今跟隨祂腳步。<br/>',NULL,9457,9457);
INSERT INTO stanza VALUES('C429','3','『出到營外』就耶穌，<br/>撇下親人和家族；<br/>父神旨意祂所顧，<br/>人情豈能將我阻？<br/>',NULL,9458,9458);
INSERT INTO stanza VALUES('C429','4','『出到營外』就耶穌，<br/>除非與祂不為伍；<br/>世界團體、宗教組，<br/>就此永遠不再屬。<br/>',NULL,9459,9459);
INSERT INTO stanza VALUES('C429','5','『出到營外』就耶穌，<br/>任憑人都與我疏；<br/>這路雖然苦且孤，<br/>有祂作伴心已足。<br/>',NULL,9460,9460);
INSERT INTO stanza VALUES('C429','6','『出到營外』就耶穌，<br/>與祂同行樂何如；<br/>因祂笑容受鼓舞，<br/>以祂同在作寄廬。<br/>',NULL,9461,9461);
INSERT INTO stanza VALUES('C429','7','『出到營外』就耶穌，<br/>直到路盡天已曙；<br/>那時見祂必歡呼，<br/>得祂稱許進國度。<br/>',NULL,9462,9462);
INSERT INTO stanza VALUES('C430','1','神照祂所豫知豫定，<br/>要祂所召的人模成<br/>祂兒子的形像。<br/>',NULL,9463,9463);
INSERT INTO stanza VALUES('C430','chorus','模成，模成神子形像！<br/>模成神兒子的形像！<br/>模成神子形像。<br/>',NULL,9464,9464);
INSERT INTO stanza VALUES('C430','2','聖靈照著神的自己，<br/>常為我們禱告歎息：<br/>模成神子形像。<br/>',NULL,9465,9465);
INSERT INTO stanza VALUES('C430','3','聖靈在我裡面運行，<br/>也在外面管治模成<br/>神兒子的形像。<br/>',NULL,9466,9466);
INSERT INTO stanza VALUES('C430','4','聖靈管治、禱告、運行，<br/>都是為將我們模成<br/>神兒子的形像。<br/>',NULL,9467,9467);
INSERT INTO stanza VALUES('C430','5','萬事萬物互相效力，<br/>為叫愛神的人得益：<br/>模成神子形像。<br/>',NULL,9468,9468);
INSERT INTO stanza VALUES('C430','6','為要得著許多兒子，<br/>神就必須完成這事：<br/>模成神子形像。<br/>',NULL,9469,9469);
INSERT INTO stanza VALUES('C430','7','為叫我們得著榮耀，<br/>神也必須完全作到：<br/>模成神子形像。<br/>',NULL,9470,9470);
INSERT INTO stanza VALUES('C430','8','基督的愛不能隔絕，<br/>為將這事作得確切：<br/>模成祂的形像。<br/>',NULL,9471,9471);
INSERT INTO stanza VALUES('C431','1','看！從那些卑賤瓦器，<br/>無盡恩典在照亮，<br/>照到疲困、孤苦心裡，<br/>照出基督的面光。<br/>',NULL,9472,9472);
INSERT INTO stanza VALUES('C431','2','基督，充滿天上之光，<br/>今在地上來照亮，<br/>生命之靈住人心房，<br/>死蔭照進生命光。<br/>',NULL,9473,9473);
INSERT INTO stanza VALUES('C431','3','從那天上清明榮光，<br/>瓦器將神帶下來，<br/>如此將神給人欣賞，<br/>更加甜美、更可愛。<br/>',NULL,9474,9474);
INSERT INTO stanza VALUES('C431','4','瓦器並無佳形、美容，<br/>內藏寶貝卻榮美；<br/>榮耀煥發，常新、光榮，<br/>屬天不變的寶貝。<br/>',NULL,9475,9475);
INSERT INTO stanza VALUES('C431','5','經過許多飢渴世代，<br/>瓦器雖然弱又脆，<br/>卻總將神兒子裝載，<br/>顯出無價的寶貝。<br/>',NULL,9476,9476);
INSERT INTO stanza VALUES('C432','1','神的自己照在我心，<br/>我就得以脫舊更新。<br/>寶貝放在瓦器裡面，<br/>莫大能力藉此彰顯！<br/>',NULL,9477,9477);
INSERT INTO stanza VALUES('C432','chorus','寶貝放在瓦器裡面，<br/>莫大能力藉此彰顯！<br/>莫大能力藉此彰顯！<br/>',NULL,9478,9478);
INSERT INTO stanza VALUES('C432','2','四面受敵，不被困住；<br/>遭受逼迫，不被輕忽；<br/>心裡作難，不至失望；<br/>被人打倒，不至死亡。<br/>',NULL,9479,9479);
INSERT INTO stanza VALUES('C432','3','耶穌的死帶在身上，<br/>耶穌的生就得顯彰；<br/>死在我身發動運行，<br/>生在我身就得顯明。<br/>',NULL,9480,9480);
INSERT INTO stanza VALUES('C432','4','神既叫主從死復活，<br/>也必叫我同祂活著。<br/>外面的人雖然毀壞，<br/>裡面的人卻新起來！<br/>',NULL,9481,9481);
INSERT INTO stanza VALUES('C432','chorus','外面的人雖然毀壞，<br/>裡面的人卻新起來！<br/>裡面的人卻新起來！<br/>',NULL,9482,9482);
INSERT INTO stanza VALUES('C432','5','至暫至輕苦楚忍受，<br/>極大無比榮耀成就；<br/>眼所能見並不顧念，<br/>惟有顧念眼所不見。<br/>',NULL,9483,9483);
INSERT INTO stanza VALUES('C433','1','非我惟主，<br/>被人高舉並愛敬；<br/>非我惟主，<br/>被人傳揚相信；<br/>非我惟主，<br/>顯在言語和步武；<br/>非我惟主，<br/>顯在思想態度。<br/>',NULL,9484,9484);
INSERT INTO stanza VALUES('C433','chorus','哦，求主救我脫離自己！<br/>失去在你裡面！<br/>哦，但願不再是自己，<br/>惟主活我裡面！<br/>',NULL,9485,9485);
INSERT INTO stanza VALUES('C433','2','非我惟主，<br/>是我一切的起首；<br/>非我惟主，<br/>是供給的源頭；<br/>非我惟主，<br/>是我所為而工作；<br/>非我惟主，<br/>是我所為生活。<br/>',NULL,9486,9486);
INSERT INTO stanza VALUES('C433','3','主，惟有主，<br/>所以不再有閒言；<br/>主，惟有主，<br/>所以不再自憐；<br/>主，惟有主，<br/>所以不再謀自存；<br/>主，惟有主，<br/>所以不再自尊。<br/>',NULL,9487,9487);
INSERT INTO stanza VALUES('C433','4','非我惟主，<br/>故無一可以自傲；<br/>非我惟主，<br/>故無一可自暴；<br/>非我惟主，<br/>因此不再有重擔；<br/>非我惟主，<br/>因此不怕危難。<br/>',NULL,9488,9488);
INSERT INTO stanza VALUES('C433','5','主，惟有主，<br/>不久充滿我眼睛，<br/>榮耀無比，<br/>不久就要顯明；<br/>主，惟有主，<br/>要永受我的感謝，<br/>耶穌基督，<br/>要永是我一切。<br/>',NULL,9489,9489);
INSERT INTO stanza VALUES('C434','1','神在天上有一寶貝，<br/>豐富無人能言述；<br/>永遠心愛祂所寶貴，<br/>就是祂子主基督。<br/>神在地上有一寶貝，<br/>價值惟有神知悉；<br/>極深心愛人難測窺－基督啟示我心裡。<br/>',NULL,9490,9490);
INSERT INTO stanza VALUES('C434','2','神藉火焰舌頭臨到，<br/>用這永遠無窮盡、<br/>取用不竭的無價寶，<br/>充滿所選的器皿。<br/>神從天上榮耀裡頭，<br/>親來充滿這器皿，<br/>用祂愛的無限富有，<br/>滿足所有渴慕心。<br/>',NULL,9491,9491);
INSERT INTO stanza VALUES('C434','3','雖受折磨、試煉、試探，<br/>榮耀呼召仍屬你；<br/>葡萄樹枝與樹相聯，<br/>向主倒空你自己。<br/>泥土器皿世人鄙視，<br/>軟弱、貧窮又卑賤，<br/>裝著寶貝神心賞識，<br/>將主榮耀來彰顯。<br/>',NULL,9492,9492);
INSERT INTO stanza VALUES('C434','4','願我更加倒空、謙卑，<br/>不為人知、不顯揚，<br/>作神器皿，更聖、更貴，<br/>充滿基督的榮光！<br/>無何地物遮此榮光，<br/>也無自己的遮蔽，<br/>將這奇妙故事宣揚，<br/>倒空、充滿祂自己。<br/>',NULL,9493,9493);
INSERT INTO stanza VALUES('C435','1','在亞當裡面，<br/>罪、死是我所有，<br/>在基督裡面，<br/>義、生是我所受；<br/>在肉體裡面，<br/>顯出亞當性情，<br/>在那靈裡面，<br/>活出基督生命。<br/>',NULL,9494,9494);
INSERT INTO stanza VALUES('C435','2','在亞當裡面，<br/>不必再有罪行，<br/>我就是罪人，<br/>已被定罪死刑；<br/>在基督裡面，<br/>不須再有義行，<br/>我就是義人，<br/>已被稱義得生。<br/>',NULL,9495,9495);
INSERT INTO stanza VALUES('C435','3','在肉體裡面，<br/>不必特意用力，<br/>我就能顯出<br/>亞當敗壞形跡；<br/>在那靈裡面，<br/>不必專一立志，<br/>我就能活出<br/>基督榮耀樣式。<br/>',NULL,9496,9496);
INSERT INTO stanza VALUES('C435','4','與基督同死，<br/>脫離亞當舊性，<br/>與基督同活，<br/>得著基督新生；<br/>不體貼肉體，<br/>舊性就難逞能，<br/>只體貼那靈，<br/>新生就能顯聖。<br/>',NULL,9497,9497);
INSERT INTO stanza VALUES('C435','5','只體貼那靈，<br/>乃是神的救法，<br/>只體貼那靈，<br/>除此別無救拔；<br/>只體貼那靈，<br/>就能勝過情慾，<br/>只體貼那靈，<br/>就必脫離罪律。<br/>',NULL,9498,9498);
INSERT INTO stanza VALUES('C435','6','只體貼那靈，<br/>就有十架經歷，<br/>只體貼那靈，<br/>就得復活能力；<br/>只體貼那靈，<br/>基督就能活出，<br/>只體貼那靈，<br/>生命就必成熟。<br/>',NULL,9499,9499);
INSERT INTO stanza VALUES('C435','7','在那靈裡面，<br/>基督纔是生命，<br/>在那靈裡面，<br/>生命纔是大能；<br/>在那靈裡面，<br/>成聖纔是經歷，<br/>在那靈裡面，<br/>經歷纔能實際。<br/>',NULL,9500,9500);
INSERT INTO stanza VALUES('C436','1','基督是我生命，<br/>也是我平安；<br/>使我有分那靈，<br/>與祂相結聯。<br/>',NULL,9501,9501);
INSERT INTO stanza VALUES('C436','chorus','隨從那靈而行，<br/>活在主裡面，<br/>就得飽嘗生命，<br/>並得享平安。<br/>',NULL,9502,9502);
INSERT INTO stanza VALUES('C436','2','基督我已屬於，<br/>不再受捆綁；<br/>生命之靈的律<br/>已將我釋放。<br/>',NULL,9503,9503);
INSERT INTO stanza VALUES('C436','3','不再體貼肉體，<br/>凡事體貼靈；<br/>不再隨從己意，<br/>只隨靈而行。<br/>',NULL,9504,9504);
INSERT INTO stanza VALUES('C436','4','不再與神為敵，<br/>不服神律法；<br/>乃有超凡之義，<br/>遠勝守律法。<br/>',NULL,9505,9505);
INSERT INTO stanza VALUES('C436','5','那靈住在我裡，<br/>不只能屬靈；<br/>就是必死身體，<br/>也必得復生。<br/>那靈在我靈裡，<br/>二靈成一靈，<br/>見證我是神裔，<br/>凡事也引領。<br/>',NULL,9506,9506);
INSERT INTO stanza VALUES('C437','1','寧捨世界而要基督，<br/>因祂滿足我情衷；<br/>除祂以外，何所愛慕？<br/>何況世福盡虛空！<br/>',NULL,9507,9507);
INSERT INTO stanza VALUES('C437','chorus','哦，祂豐滿我不能言！<br/>但這豐滿我知道；<br/>哦，祂甘甜真是超凡！<br/>但這甘甜我嘗到。<br/>',NULL,9508,9508);
INSERT INTO stanza VALUES('C437','2','寧捨世界而要基督，<br/>有祂我就別無需；<br/>得著世界仍是缺如，<br/>得著基督就有餘。<br/>',NULL,9509,9509);
INSERT INTO stanza VALUES('C437','3','世界雖大，我心雖小，<br/>大者難使小者足；<br/>小小之心所需所要，<br/>惟有基督能滿足。<br/>',NULL,9510,9510);
INSERT INTO stanza VALUES('C437','4','有了基督就能歡唱，<br/>沒有基督必憂鬱；<br/>基督是我一切寶藏，<br/>在祂裡面我定居！<br/>',NULL,9511,9511);
INSERT INTO stanza VALUES('C438','1','我已揀選主耶穌，<br/>揀選祂作世界；<br/>祂愛實在是充足，<br/>滿足我的一切；<br/>主，我是你的器皿，<br/>只有你能充盈；<br/>敘加的水飲千井，<br/>渴仍不停。<br/>',NULL,9512,9512);
INSERT INTO stanza VALUES('C438','chorus','耶穌，耶穌，<br/>我揀選主耶穌，<br/>我心今正住在所有甘甜事物之源；<br/>耶穌，耶穌，<br/>祂乃是我滿足，<br/>是祂消除我的要求，<br/>平靜我的意願。<br/>',NULL,9513,9513);
INSERT INTO stanza VALUES('C438','2','我已揀選主耶穌，<br/>揀選祂作喜樂；<br/>有祂，我心雖痛苦，<br/>依然會唱詩歌；<br/>有祂，我無別原因，<br/>也發喜樂聲音；<br/>因我所有的歡欣，<br/>是在祂心。<br/>',NULL,9514,9514);
INSERT INTO stanza VALUES('C438','3','我已揀選主耶穌，<br/>揀選祂作希望；<br/>祂賜基業甚豐富，<br/>使我不住思量；<br/>將牠賜我的救主<br/>乃是我的至寶；<br/>今天我心有催促：<br/>得祂最好。<br/>',NULL,9515,9515);
INSERT INTO stanza VALUES('C438','4','我已揀選主耶穌，<br/>揀選祂作我主；<br/>祂愛實在是難述，<br/>嘗到就會屈服；<br/>我已奉獻我一切，<br/>向祂我無要求；<br/>我心只求祂喜悅，<br/>怕祂心憂。<br/>',NULL,9516,9516);
INSERT INTO stanza VALUES('C439','1','今日我心因歡樂而歌唱，<br/>我主，<br/>因你是我生命、安康；<br/>親愛的主，<br/>前途我全藉你，<br/>我也知道父神是為我的。<br/>',NULL,9517,1);
INSERT INTO stanza VALUES('C439','chorus','都因著你！<br/>都因著你！<br/>都因著各各他！<br/>都因著你！<br/>',NULL,9518,2);
INSERT INTO stanza VALUES('C439','2','前有一日，<br/>我因懼怕永死，<br/>就用行為將我自己裝飾，<br/>盼望能彀避免神的刑罰，<br/>但我今知你是惟一救法。<br/>',NULL,9519,3);
INSERT INTO stanza VALUES('C439','3','將來罪人雖然都要痛哭，<br/>但你召會卻要被提得福，<br/>因為藉你所灑幔裡寶血，<br/>她能勝過陰府所有猖獗。<br/>',NULL,9520,4);
INSERT INTO stanza VALUES('C439','4','神的羔羊為我擔當罪惡，<br/>使我得救，<br/>今後永遠生活，<br/>你為我喝公義忿怒的杯，<br/>審判已過，<br/>現今再無死味。<br/>',NULL,9521,5);
INSERT INTO stanza VALUES('C439','5','你使我在青草地場躺臥，<br/>平安的神將祂最好給我，<br/>因我現今倚在你的胸懷，<br/>與你交通，<br/>並嘗你的大愛。<br/>',NULL,9522,6);
INSERT INTO stanza VALUES('C439','6','願你保守我的生命佳美，<br/>使我雖然遇見<br/>譏嘲、謗毀，<br/>也能因信時常仰望父神，<br/>學習交託，<br/>受苦仍能歡欣。<br/>',NULL,9523,7);
INSERT INTO stanza VALUES('C439','7','求主教我拒絕人世名聲，<br/>面如堅石，<br/>經過火熱水深，<br/>願意與主同受<br/>羞辱、挫折，<br/>為主的名作一個殉道者！<br/>當我被提，<br/>在人子前站立，<br/>釘十架者要成我的詩題；<br/>你從天來經歷人生苦楚，<br/>又在加略捨去生命血肉。<br/>',NULL,9524,8);
INSERT INTO stanza VALUES('C439','chorus','都因著我！<br/>都因著我！<br/>都因著我一人！<br/>都因著我！<br/>',NULL,9525,10);
INSERT INTO stanza VALUES('C440','1','外面雖被曠野太陽曬黑，<br/>光明之子裡面卻都秀美；<br/>奧祕之樂遠非人所能知，<br/>榮耀之王每個都已賞賜；<br/>人心從來未曾想到，<br/>人手也永不能摸著；<br/>聖徒住在神的光中，<br/>得到神的隱藏光榮。<br/>',NULL,9526,9526);
INSERT INTO stanza VALUES('C440','2','在人看來，<br/>乃是亞當族類，<br/>帶著屬地形狀，<br/>病、苦纏累，<br/>和那墮落罪人完全相像，<br/>外面需要也和他們一樣，<br/>屬地生活所有方式、<br/>睡眠起居也都相似。<br/>這是為使他們藐視<br/>人眼所重虛容美姿。<br/>',NULL,9527,9527);
INSERT INTO stanza VALUES('C440','3','他們裡面卻有神的生命，<br/>主的話語已將他們重生；<br/>他們已被神聖愛火所焚，<br/>成為屬新耶路撒冷的人；<br/>他們都是光中聖徒，<br/>常將甜美詩辭歌賦，<br/>彼此頌揚最高之神，<br/>發出深處最妙之音。<br/>',NULL,9528,9528);
INSERT INTO stanza VALUES('C440','4','他們行在地上，<br/>住在天上；<br/>無力，<br/>卻能暗中將地執掌；<br/>為難，<br/>深處卻有神賜平安；<br/>貧窮，<br/>卻有萬有效力成全；<br/>雖被打倒，不至死亡，<br/>心裡作難，不至失望；<br/>好像行在死蔭之中，<br/>卻是活著生命無窮。<br/>',NULL,9529,9529);
INSERT INTO stanza VALUES('C440','5','將來基督－他們生命－顯現，<br/>帶著榮耀前來作王掌權，<br/>他們久藏榮耀也要顯出，<br/>同著基督要被眾目所睹。<br/>哦！光明者，興起發光，<br/>你同基督要升天上，<br/>隱藏之光要照遠方，<br/>每一聖徒都像太陽。<br/>',NULL,9530,9530);
INSERT INTO stanza VALUES('C441','1','我神、我愛、我的永分，<br/>你永是我一切；<br/>你外，在天我有何人，<br/>在地有你無缺！<br/>在地有你無缺！<br/>',NULL,9531,9531);
INSERT INTO stanza VALUES('C441','2','天上一切盡都空虛，<br/>地上更是如此！<br/>並無一物值得歡娛，<br/>能與我神相似。<br/>',NULL,9532,9532);
INSERT INTO stanza VALUES('C441','3','你是我的財富、生命，<br/>我的安穩住處；<br/>其他事物，我也感領，<br/>但非我神、我主。<br/>',NULL,9533,9533);
INSERT INTO stanza VALUES('C441','4','閃耀財富，與你相比，<br/>不過虛空玩具！<br/>何況其他人之所倚，<br/>豈不更將人愚？<br/>',NULL,9534,9534);
INSERT INTO stanza VALUES('C441','5','即使全地歸我為業，<br/>群星也是我的，<br/>若無你作我的一切，<br/>我仍可憐至極！<br/>',NULL,9535,9535);
INSERT INTO stanza VALUES('C441','6','讓人伸臂如同大海，<br/>籠羅一切財富；<br/>但我只要你的同在，<br/>此外無所愛慕。<br/>',NULL,9536,9536);
INSERT INTO stanza VALUES('C442','1','當我已為撒但所擄，<br/>正在死地作罪囚奴；<br/>神因愛憐前來眷顧，<br/>將我帶回歸向基督。<br/>',NULL,9537,9537);
INSERT INTO stanza VALUES('C442','chorus','神的宏恩將我重生，<br/>賜我新心，又賜新靈，<br/>且將祂靈放在我靈，<br/>使我有分祂的性情。<br/>',NULL,9538,9538);
INSERT INTO stanza VALUES('C442','2','神用清水灑在我身，<br/>污穢、偶像我全脫盡；<br/>除掉石心，賜我肉心，<br/>使我成為新造新人。<br/>',NULL,9539,9539);
INSERT INTO stanza VALUES('C442','3','神的自己作我生命，<br/>祂的神性是我性情；<br/>我就合於祂的神聖，<br/>能以活出祂所命令。<br/>',NULL,9540,9540);
INSERT INTO stanza VALUES('C442','4','我作祂民，祂作我神，<br/>彼此交通相近相親；<br/>祂是我福，祂是我分，<br/>不再他投，不再他奔。<br/>',NULL,9541,9541);
INSERT INTO stanza VALUES('C442','5','祂的基督作我住處，<br/>我享祂的一切豐富；<br/>祂作我的生命食物，<br/>我就永遠得到飽足。 (副)<br/>神的宏恩將我重生，<br/>賜我新心，又賜新靈，<br/>且將祂靈放在我靈，<br/>使我有分祂的性情。<br/>',NULL,9542,9542);
INSERT INTO stanza VALUES('C443','1','何等榮耀！何等神聖！<br/>神是永遠的生命！<br/>豐富、無限、<br/>堅強、有能、<br/>聖潔、慈仁又光明！<br/>祂的本性、祂的豐盛，<br/>全都在於這生命。<br/>',NULL,9543,9543);
INSERT INTO stanza VALUES('C443','2','何等慈愛！何等恩典！<br/>神之於人是生命！<br/>祂要進入人的裡面，<br/>所以為人創造靈。<br/>祂心對人所喜所願，<br/>乃在接祂作生命。<br/>',NULL,9544,9544);
INSERT INTO stanza VALUES('C443','3','何等大愛！何等大恩！<br/>神已流出作生命！<br/>不再自藏，不再自隱，<br/>已經向人來顯明；<br/>後成那靈，先在肉身，<br/>給人接受作生命。<br/>',NULL,9545,9545);
INSERT INTO stanza VALUES('C443','4','何等可親！何等可近！<br/>神在基督作生命！<br/>基督乃是祂的化身，<br/>祂在肉身的顯明；<br/>死而復活，給人相信，<br/>到人裡面作生命。<br/>',NULL,9546,9546);
INSERT INTO stanza VALUES('C443','5','何等奇妙！何等可信！<br/>神成那靈作生命！<br/>那靈是祂又一化身，<br/>是祂實際的顯明；<br/>感動人信，進入人心，<br/>到人靈裡作生命。<br/>',NULL,9547,9547);
INSERT INTO stanza VALUES('C443','6','何等寶貴！何等真實！<br/>三一之神作生命！<br/>父先流出就是一子，<br/>子再流出就是靈；<br/>靈一流入就是恩賜，<br/>在人裡面作生命。<br/>',NULL,9548,9548);
INSERT INTO stanza VALUES('C443','7','何等奧祕！何等實際！<br/>神已流入作生命！<br/>流入我心，與我合一，<br/>在我靈裡作生命。<br/>阿利路亞，讚美不已，<br/>神竟作了我生命！<br/>',NULL,9549,9549);
INSERT INTO stanza VALUES('C444','1','是愛的神作我牧人，<br/>祂常餧養，祂常施恩；<br/>祂是屬我，我是屬祂，<br/>何來需要？何來缺乏？<br/>',NULL,9550,9550);
INSERT INTO stanza VALUES('C444','2','祂帶我到嫩草地場，<br/>使我感覺滿足歡暢；<br/>又帶我到平靜溪流，<br/>交通不斷，安息無憂。<br/>',NULL,9551,9551);
INSERT INTO stanza VALUES('C444','3','我時迷路，祂來截回，<br/>再側我心受祂支配；<br/>我常搖動，不甚堅定，<br/>但祂引導，是為己名。<br/>',NULL,9552,9552);
INSERT INTO stanza VALUES('C444','4','何等不明，何等可疑，<br/>怎能行走無所顧忌？<br/>你竿扶持，你杖引領，<br/>你的同在滿我途徑。<br/>',NULL,9553,9553);
INSERT INTO stanza VALUES('C444','5','你使我能大膽誇勝，<br/>敵雖四佈，享恩如恆：<br/>我頭油潤，我杯酒溢，<br/>我神從來不曾吝惜。<br/>',NULL,9554,9554);
INSERT INTO stanza VALUES('C444','6','你的甘甜、奇妙的愛，<br/>測量我的一生年代；<br/>你愛既然永不改變，<br/>我的讚美還要加添。<br/>',NULL,9555,9555);
INSERT INTO stanza VALUES('C445','1','一想到神，就受吸引，<br/>吸引我心離地，<br/>對於幻景立生厭心，<br/>抵消地的吸力。<br/>',NULL,9556,9556);
INSERT INTO stanza VALUES('C445','2','僅僅得救，免去沉淪，<br/>難彀神之所想；<br/>對神之念激動我心，<br/>使有更高願望。<br/>',NULL,9557,9557);
INSERT INTO stanza VALUES('C445','3','惟有神是人的住處，<br/>路雖窄而崎嶇；<br/>除神，無何能彀滿足<br/>我心深處所欲。<br/>',NULL,9558,9558);
INSERT INTO stanza VALUES('C445','4','只要從你心的深處，<br/>將神尊名稱頌，<br/>一切引誘你的邪術，<br/>都要立即消蹤。<br/>',NULL,9559,9559);
INSERT INTO stanza VALUES('C445','5','信靠之心、仰望之眼，<br/>必得神的引導；<br/>如果信心能彀移山，<br/>愛心之力豈小？<br/>',NULL,9560,9560);
INSERT INTO stanza VALUES('C445','6','哦，那追求神的道路，<br/>你僅走了一點！<br/>向神之心，對神之顧，<br/>必能帶你向前。<br/>',NULL,9561,9561);
INSERT INTO stanza VALUES('C445','7','從罪權下得著自由，<br/>生活不失檢點；<br/>這些比那愛心所求，<br/>仍是較低恩典。<br/>',NULL,9562,9562);
INSERT INTO stanza VALUES('C445','8','完全之路，肉體感難，<br/>但在愛心不然；<br/>如果你因要神而前，<br/>必勝一切糾纏。<br/>',NULL,9563,9563);
INSERT INTO stanza VALUES('C445','9','然後保守良心敏銳，<br/>顧到裡面感覺；<br/>膏油塗抹，時時跟隨，<br/>這是成熟祕訣。<br/>',NULL,9564,9564);
INSERT INTO stanza VALUES('C446','1','我的居所乃是神的自己，<br/>我主基督將我帶到這裡；<br/>祂帶我走祂所走過的路，<br/>到這至聖所裡與神同住。<br/>聖別所在！<br/>神聖榮美之家，<br/>在此與神同住，<br/>至美絕佳！<br/>',NULL,9565,9565);
INSERT INTO stanza VALUES('C446','2','夜以繼日走過漫長的路，<br/>自己裡面想要找到一途；<br/>一無所成，<br/>也無任何進步，<br/>自己努力不過全是失誤，<br/>而後得知主是惟一道路，<br/>我當藉祂到神裡面居住。<br/>',NULL,9566,9566);
INSERT INTO stanza VALUES('C446','3','奇妙住處，<br/>神聖榮美之家！<br/>與神同住，<br/>安穩無以復加。<br/>哦神，<br/>你我既是互為居所，<br/>求你使我只是向你活著；<br/>在這最美之家，<br/>得享安康，<br/>隨事隨在將你與人分享。<br/>',NULL,9567,9567);
INSERT INTO stanza VALUES('C447','1','何等奧妙，<br/>父、子、靈乃是一神！<br/>身位雖三，<br/>本質卻是一靈；<br/>何等榮耀，<br/>這位神進入我心，<br/>在我裡面，<br/>作我一切供應。<br/>',NULL,9568,9568);
INSERT INTO stanza VALUES('C447','chorus','三一之神，<br/>作了我的一切！<br/>何等奇妙！<br/>何等榮耀！<br/>神聖成分，<br/>我能取用不竭！<br/>何等高超！<br/>何等逍遙！<br/>',NULL,9569,9569);
INSERT INTO stanza VALUES('C447','2','何等豐富，<br/>父乃是一切源頭，<br/>祂的一切全為供人享受；<br/>何等有福，<br/>這一切竟歸我有，<br/>不盡不竭，<br/>取用直到永久！<br/>',NULL,9570,9570);
INSERT INTO stanza VALUES('C447','3','何等奇妙，<br/>子乃是父的顯出，<br/>藉著肉身來與人類同處；<br/>何等有效，<br/>在十架成功救贖，<br/>使我罪人竟能與神聯屬！<br/>',NULL,9571,9571);
INSERT INTO stanza VALUES('C447','4','何等美妙，<br/>靈乃是子的進入，<br/>進入我靈，<br/>作我生命供應；<br/>何等逍遙，<br/>我今能與靈接觸，<br/>靈靈響應，<br/>二靈竟成一靈。<br/>',NULL,9572,9572);
INSERT INTO stanza VALUES('C447','5','何等實際，<br/>神一切全在靈裡，<br/>是靈在靈<br/>給我接觸、經歷；<br/>何等希奇，<br/>我與神聯合為一，<br/>生命、性情<br/>不再彼此各異。<br/>',NULL,9573,9573);
INSERT INTO stanza VALUES('C448','1','哦神，讚美你的奧妙，<br/>竟然能給我們摸到；<br/>原在光中人難靠近，<br/>今在靈裡與我相親。<br/>',NULL,9574,9574);
INSERT INTO stanza VALUES('C448','2','你是聖父、聖子、聖靈，<br/>三一之神作我生命；<br/>在我裡面將我供應，<br/>使我有你神聖性情。<br/>',NULL,9575,9575);
INSERT INTO stanza VALUES('C448','3','父在子裡，子成為靈，<br/>靈臨到我如氣似風；<br/>父、子、聖靈，<br/>神聖、奧祕，<br/>成為我的實際經歷。<br/>',NULL,9576,9576);
INSERT INTO stanza VALUES('C448','4','父的一切全歸子有，<br/>子的豐富全由靈受；<br/>靈降我身並進我心，<br/>使你成為我的福分。<br/>',NULL,9577,9577);
INSERT INTO stanza VALUES('C448','5','父是源頭，子是顯出，<br/>靈是你對我的進入；<br/>父在子裡顯在人間，<br/>子成為靈進我裡面。<br/>',NULL,9578,9578);
INSERT INTO stanza VALUES('C448','6','父願子能凡事居首，<br/>子願凡事以父為頭；<br/>靈願使子得著榮耀，<br/>在我心中向我啟曉。<br/>',NULL,9579,9579);
INSERT INTO stanza VALUES('C448','7','靈是你的最終形態，<br/>進入我靈受我敬拜；<br/>我要享受你的豐富，<br/>必須靈裡與靈接觸。<br/>',NULL,9580,9580);
INSERT INTO stanza VALUES('C448','8','靈裡敬拜，靈裡交通，<br/>靈裡禱告、讚美、稱頌，<br/>我就摸著靈裡聖靈，<br/>享受你作一切供應。<br/>',NULL,9581,9581);
INSERT INTO stanza VALUES('C449','1','靈是神的榮耀本質，<br/>也是神的神聖所是；<br/>與神接觸，享神豐富，<br/>必須藉靈，捨此無路。<br/>',NULL,9582,9582);
INSERT INTO stanza VALUES('C449','2','靈也是人最深部分，<br/>全人裡面靈是最真；<br/>要作真人，要摸著神，<br/>必須從靈，纔能入門。<br/>',NULL,9583,9583);
INSERT INTO stanza VALUES('C449','3','神是要人以靈拜靈，<br/>享受祂作一切供應；<br/>祂靈要進人靈裡面，<br/>使人與祂靈裡相聯。<br/>',NULL,9584,9584);
INSERT INTO stanza VALUES('C449','4','靈靈相交，靈靈響應，<br/>二靈調和成為一靈；<br/>人靈作了神靈居所，<br/>神靈成為人靈生活。<br/>',NULL,9585,9585);
INSERT INTO stanza VALUES('C449','5','須憑人靈接觸神靈，<br/>纔能得享神的豐盛；<br/>在人靈裡神靈同在，<br/>纔能向神獻上敬拜。<br/>',NULL,9586,9586);
INSERT INTO stanza VALUES('C449','6','福音、造就、<br/>聚會、交通，<br/>都該將人帶進靈中；<br/>讀經、聽道或聽見證，<br/>都該化禱，靈中響應。<br/>',NULL,9587,9587);
INSERT INTO stanza VALUES('C449','7','靈裡禱告，靈裡事奉，<br/>靈裡摸著神聖生命；<br/>靈裡長進，靈裡建造，<br/>靈裡顯出基督榮耀。<br/>',NULL,9588,9588);
INSERT INTO stanza VALUES('C449','8','主阿，我願回到靈裡，<br/>學習摸著你的自己；<br/>你靈、我靈不斷交流，<br/>湧流生命直到永久！<br/>',NULL,9589,9589);
INSERT INTO stanza VALUES('C450','1','神之於人一切正常故事，<br/>全都在於靈裡；<br/>人須靈裡摸著神靈本質，<br/>對神纔有經歷。<br/>',NULL,9590,9590);
INSERT INTO stanza VALUES('C450','chorus','靈生靈，<br/>靈拜靈，<br/>以至靈充滿我；<br/>靈且成話，<br/>帶著豐盛生命，<br/>流出活水江河。<br/>',NULL,9591,9591);
INSERT INTO stanza VALUES('C450','2','神乃是靈，<br/>並且為人造靈，<br/>要人以靈拜靈；<br/>藉此人能得著祂作生命，<br/>以祂為人供應。<br/>',NULL,9592,9592);
INSERT INTO stanza VALUES('C450','3','神乃是靈<br/>進入人的靈中，<br/>叫人得著重生；<br/>人就能在靈裡與祂交通，<br/>得享祂的豐盛。<br/>',NULL,9593,9593);
INSERT INTO stanza VALUES('C450','4','神乃是靈<br/>充滿、澆灌、滋潤，<br/>將我變化、更新；<br/>直到能從我靈遍及全身，<br/>浸透我的全人。<br/>',NULL,9594,9594);
INSERT INTO stanza VALUES('C450','5','神乃是靈<br/>與我融洽、調和，<br/>使我改變形狀；<br/>祂的成分在我一再加多，<br/>直到能得顯彰。<br/>',NULL,9595,9595);
INSERT INTO stanza VALUES('C450','6','神的一切豐盛全在靈裡，<br/>給我經歷、享受；<br/>我須靈裡時常將神呼吸，<br/>纔得享神所有。 (副)<br/>靈生靈，<br/>靈拜靈，<br/>以至靈充滿我；<br/>靈且成話，<br/>帶著豐盛生命，<br/>流出活水江河。<br/>',NULL,9596,9596);
INSERT INTO stanza VALUES('C451','1','神的心意要祂一切<br/>全作我供應；<br/>需要我能與祂聯結，<br/>聯於祂靈。<br/>',NULL,9597,9597);
INSERT INTO stanza VALUES('C451','chorus','父的一切、子的豐富，<br/>全都歸於靈；<br/>我要與神這靈接觸，<br/>必須用靈。<br/>',NULL,9598,9598);
INSERT INTO stanza VALUES('C451','2','神已將祂本性豐富，<br/>全都賜給我；<br/>但須靈裡與祂接觸，<br/>纔能摸著。<br/>',NULL,9599,9599);
INSERT INTO stanza VALUES('C451','3','神需心思明白、認識，<br/>也需靈接觸；<br/>若不動靈，只憑理智，<br/>難得滿足。<br/>',NULL,9600,9600);
INSERT INTO stanza VALUES('C451','4','不能聽道而不禱告，<br/>用腦不用靈；<br/>不能讀經而不靈交，<br/>靈不響應。<br/>',NULL,9601,9601);
INSERT INTO stanza VALUES('C451','5','何等豐富，何等榮耀，<br/>靈裡接觸神！<br/>神的一切，神的上好，<br/>全是我分。<br/>',NULL,9602,9602);
INSERT INTO stanza VALUES('C452','1','神的聖靈是神傳達，<br/>藉祂，神得進入我裡；<br/>藉祂，神在基督裡面，<br/>給我得著，作我經歷。<br/>',NULL,9603,9603);
INSERT INTO stanza VALUES('C452','2','神之為父是作源頭，<br/>神之為子是為表現，<br/>神之為靈是為進入，<br/>使我得著神的豐滿。<br/>',NULL,9604,9604);
INSERT INTO stanza VALUES('C452','3','父原住在難近光中，<br/>子來將祂向人顯明；<br/>靈又將祂向人傳達，<br/>人可靈中將祂接領。<br/>',NULL,9605,9605);
INSERT INTO stanza VALUES('C452','4','父在子裡來人中間，<br/>子又成靈進人裡面；<br/>父、子、聖靈，<br/>三一之神，<br/>現今住在我們靈間。<br/>',NULL,9606,9606);
INSERT INTO stanza VALUES('C452','5','父神乃在子神裡面，<br/>得著化身而得彰顯；<br/>靈神乃是子神實際，<br/>給我得著作我恩典。<br/>',NULL,9607,9607);
INSERT INTO stanza VALUES('C452','6','但願父神對我之愛，<br/>在子神裡成我恩典，<br/>藉著靈神交通傳達，<br/>使我得享神的豐滿。<br/>',NULL,9608,9608);
INSERT INTO stanza VALUES('C453','1','與你更親，我神，<br/>與你更親；<br/>雖然十架在身，<br/>使我前進，<br/>我仍發此歌音：<br/>與你更親，我神，<br/>與你更親，我神，<br/>與你更親。<br/>',NULL,9609,9609);
INSERT INTO stanza VALUES('C453','2','雖作旅客飄泊，<br/>日已西墜，<br/>驚人黑暗罩我，<br/>枕石而睡，<br/>夢中我仍不禁，<br/>願我與你更親，<br/>願我與你更親，<br/>與你更親。<br/>',NULL,9610,9610);
INSERT INTO stanza VALUES('C453','3','夢中有路顯明，<br/>如梯通天；<br/>凡你所許事情，<br/>全出恩憐；<br/>又有天使顯身，<br/>招我與你更親，<br/>招我與你更親，<br/>與你更親。<br/>',NULL,9611,9611);
INSERT INTO stanza VALUES('C453','4','醒來心情安適，<br/>充滿感讚；<br/>所枕艱苦硬石，<br/>必作你殿；<br/>原來所遇艱辛，<br/>使我與你更親，<br/>使我與你更親，<br/>與你更親。<br/>',NULL,9612,9612);
INSERT INTO stanza VALUES('C453','5','假若喜樂生翼，<br/>向天飛騰，<br/>日月星辰盡歷，<br/>翱翔不停，<br/>我仍發此歌音：<br/>與你更親，我神，<br/>與你更親，我神，<br/>與你更親。<br/>',NULL,9613,9613);
INSERT INTO stanza VALUES('C454','1','在遠山聳立著古老的十字架，<br/>作為羞辱、痛苦標誌；<br/>我愛這十字架，<br/>因主離榮耀家，<br/>來在上面替人受死。<br/>',NULL,9614,9614);
INSERT INTO stanza VALUES('C454','chorus','我寶貴古老的十字架，<br/>一直到我俯伏主腳前；<br/>我堅持古老的十字架，<br/>等有天，<br/>我將牠換冠冕。<br/>',NULL,9615,9615);
INSERT INTO stanza VALUES('C454','2','古老的十字架，<br/>不少人很輕視，<br/>對我卻有奇妙吸力；<br/>神聖潔的羔羊曾降臨到此世，<br/>將牠背至髑髏死地。<br/>',NULL,9616,9616);
INSERT INTO stanza VALUES('C454','3','古老的十字架，<br/>染斑斑的血跡，<br/>從我眼光何等可悅！<br/>就在這十字架，<br/>主受苦到至極，<br/>為要賜我赦免、聖潔。<br/>',NULL,9617,9617);
INSERT INTO stanza VALUES('C454','4','我永遠要效忠古老的十字架，<br/>歡喜受牠所受譏誚；<br/>有一天主再來，<br/>面對面看見祂，<br/>永遠享受祂的榮耀。<br/>',NULL,9618,9618);
INSERT INTO stanza VALUES('C455','1','基督十架是我誇耀，<br/>年代滅沒牠獨存；<br/>神聖事蹟光輝環繞，<br/>十架巍然是中心。<br/>',NULL,9619,9619);
INSERT INTO stanza VALUES('C455','2','當我遭遇患難、折磨，<br/>希望成空，憂懼纏，<br/>基督十架永不棄我，<br/>看哪！喜樂與平安。<br/>',NULL,9620,9620);
INSERT INTO stanza VALUES('C455','3','有福太陽，以光以愛，<br/>照耀在我路程上，<br/>基督十架放射光彩，<br/>使我人生更光亮。<br/>',NULL,9621,9621);
INSERT INTO stanza VALUES('C455','4','是禍是福，是苦是樂，<br/>十架使我全成聖，<br/>在此平安深廣莫測，<br/>喜樂永遠不變更。<br/>',NULL,9622,9622);
INSERT INTO stanza VALUES('C455','5','基督十架是我誇耀，<br/>年代滅沒牠獨存；<br/>神聖事蹟光輝環繞，<br/>十架巍然是中心。<br/>',NULL,9623,9623);
INSERT INTO stanza VALUES('C456','1','求主使我近十架！<br/>在此有一寶泉，<br/>醫治活水，無代價，<br/>流自加略山巔。<br/>',NULL,9624,9624);
INSERT INTO stanza VALUES('C456','chorus','十字架！十字架！<br/>永是我的誇耀！<br/>在此主付的贖價，<br/>是我永遠倚靠！<br/>',NULL,9625,9625);
INSERT INTO stanza VALUES('C456','2','前我戰兢就十架，<br/>得蒙愛憐、寬饒；<br/>明亮晨星的光華，<br/>在此仍將我照。<br/>',NULL,9626,9626);
INSERT INTO stanza VALUES('C456','3','哦主，當我近十架，<br/>示我以其情景；<br/>在你十架蔭庇下，<br/>天天助我前行。<br/>',NULL,9627,9627);
INSERT INTO stanza VALUES('C456','4','就近十架而儆醒，<br/>時時信靠、瞻仰，<br/>直到被提得上升，<br/>永遠見主面光。<br/>',NULL,9628,9628);
INSERT INTO stanza VALUES('C456','chorus','十字架！十字架！<br/>永是我的誇耀！<br/>在此主付的贖價，<br/>是我永遠倚靠！<br/>第二節的『明亮晨星』指主基督。<br/>',NULL,9629,9629);
INSERT INTO stanza VALUES('C457','1','十架永遠得勝，<br/>阿利路亞！阿利路亞！<br/>十架將敵除淨，<br/>阿利路亞！阿利路亞！<br/>陰府雖極兇猛，<br/>世界雖在翻騰，<br/>肉體雖也逞能，<br/>十架使我仍誇勝！<br/>',NULL,9630,9630);
INSERT INTO stanza VALUES('C457','chorus','阿利路亞！阿利路亞！<br/>基督十架永得勝！<br/>阿利路亞！阿利路亞！<br/>仗這十架我誇勝！<br/>',NULL,9631,9631);
INSERT INTO stanza VALUES('C457','2','十架是我生命，<br/>阿利路亞！阿利路亞！<br/>十架賜我權柄，<br/>阿利路亞！阿利路亞！<br/>勝過人情、自己，<br/>勝過世界勢力，<br/>勝過一切仇敵，<br/>十架使我勝無已！<br/>',NULL,9632,9632);
INSERT INTO stanza VALUES('C457','3','十架是我旌旗，<br/>阿路利亞！阿利路亞！<br/>我要永遠舉起，<br/>阿路利亞！阿利路亞！<br/>軟弱變為剛強，<br/>下沉變為高昂，<br/>黑暗變為明亮，<br/>十架使我得釋放！<br/>',NULL,9633,9633);
INSERT INTO stanza VALUES('C458','1','你若不壓橄欖成渣，<br/>牠就不能成油；<br/>你若不投葡萄入醡，<br/>牠就不能變成酒；<br/>你若不煉哪噠成膏，<br/>牠就不流芬芳；<br/>主，我這人是否也要<br/>受你許可的創傷？<br/>',NULL,9634,9634);
INSERT INTO stanza VALUES('C458','chorus','每次的打擊，<br/>都是真利益，<br/>如果你收去的東西，<br/>你以自己來代替。<br/>',NULL,9635,9635);
INSERT INTO stanza VALUES('C458','2','你是否要鼓我心弦，<br/>發出你的音樂？<br/>是否要使音樂甘甜，<br/>須有你愛來苦虐？<br/>是否當我下倒之時，<br/>纔能識『愛』的心？<br/>我是不怕任何損失，<br/>若你讓我來相親。<br/>',NULL,9636,9636);
INSERT INTO stanza VALUES('C458','3','主，我慚愧，因我感覺<br/>總是保留自己，<br/>雖我也曾受你雕削，<br/>我卻感覺受強逼！<br/>主，你能否照你喜樂，<br/>沒有顧忌去行，<br/>不顧我的感覺如何，<br/>只是要求你歡欣？<br/>',NULL,9637,9637);
INSERT INTO stanza VALUES('C458','4','如果你我所有苦樂<br/>不能完全相同，<br/>要你喜樂，須我負軛，<br/>我就願意多苦痛；<br/>主，我全心要你所要，<br/>不惜任何代價；<br/>你若喜悅，並得榮耀，<br/>我背任何十字架。<br/>',NULL,9638,9638);
INSERT INTO stanza VALUES('C458','5','我要讚美，再要讚美，<br/>讚美何等甘甜；<br/>雖我邊讚美邊流淚，<br/>甘甜比前更加添；<br/>能有甚麼比你更好？<br/>比你喜悅可寶？<br/>主，我只有一個禱告：<br/>你能加增，我減少。<br/>',NULL,9639,9639);
INSERT INTO stanza VALUES('C459','1','十架越重，神越親近；<br/>外無十架，內即無神！<br/>黑暗君王必被踐踏，<br/>如果我肯背負十架。<br/>神所置於十架之人，<br/>雖受損失，也是歡欣。<br/>',NULL,9640,9640);
INSERT INTO stanza VALUES('C459','2','十架越重，聖徒越佳，<br/>這是神的試金估價。<br/>若無眼睛流淚澆灌，<br/>園中花木多必枯乾！<br/>金子經火纔得煉淨，<br/>聖徒藉苦纔能成聖。<br/>',NULL,9641,9641);
INSERT INTO stanza VALUES('C459','3','十架越重，信心越強；<br/>樹越負重，根越深長；<br/>葡萄美果經過壓榨，<br/>甜美汁水纔能流下；<br/>苦難來臨，膽量增長，<br/>珍珠長成，是藉蚌傷。<br/>',NULL,9642,9642);
INSERT INTO stanza VALUES('C460','1','若無損失，就無得著；<br/>非經十架，不能生活；<br/>一粒麥子不落死地，<br/>就難結出許多子粒；<br/>如果我要結果百倍，<br/>怎能完整，不被破碎？<br/>如果我要結果百倍，<br/>怎能完整，不被破碎？<br/>',NULL,9643,9643);
INSERT INTO stanza VALUES('C460','2','魂所抓者將魂抓住，<br/>金鍊之中無不為奴；<br/>我們無論傾向何物，<br/>何物就必將魂鎖住；<br/>無論生命或是財產，<br/>只要心愛，必成鎖鍊。<br/>無論生命或是財產，<br/>只要心愛，必成鎖鍊。<br/>',NULL,9644,9644);
INSERT INTO stanza VALUES('C460','3','每當看見成熟禾田，<br/>金穀豐盈向神呈獻，<br/>當知必有子粒死過，<br/>必有聖徒犧牲自我；<br/>必定有人受苦、流淚，<br/>爭戰至死並不心灰。<br/>必定有人受苦、流淚，<br/>爭戰至死並不心灰。<br/>',NULL,9645,9645);
INSERT INTO stanza VALUES('C461','1','十架人若背起，<br/>豈只受苦而已！<br/>十架人若不離，<br/>終必被置死地！<br/>因為十架用意，<br/>就是使人絕氣；<br/>所以十架經歷，<br/>總是結束自己。<br/>',NULL,9646,9646);
INSERT INTO stanza VALUES('C461','2','這是神的救法，<br/>將人十架治殺；<br/>像是殘酷刑罰，<br/>實是榮耀救拔；<br/>非讓十架剪除，<br/>不能經歷基督；<br/>十架將我結束，<br/>基督纔能活出。<br/>',NULL,9647,9647);
INSERT INTO stanza VALUES('C461','3','十架最終目的，<br/>乃是成功神意；<br/>神意最大仇敵，<br/>乃是人的自己；<br/>治死魂的生命，<br/>自己纔能除淨；<br/>除去己的性情，<br/>神意纔得通行。<br/>',NULL,9648,9648);
INSERT INTO stanza VALUES('C462','1','十字架的道路要犧牲，<br/>要將一切獻於神，<br/>將一切放在<br/>死的祭壇上面，<br/>火纔在這裡顯現。<br/>',NULL,9649,9649);
INSERT INTO stanza VALUES('C462','chorus','這是十架道路！<br/>你願否走這個？<br/>你曾否背十架為你主？<br/>你這奉獻一切給神的人！<br/>對神你是否全貞？<br/>',NULL,9650,9650);
INSERT INTO stanza VALUES('C462','2','當我們唱詩禱告時候，<br/>何等願說『獻所有！』<br/>但前面有更沉重的<br/>十字架！<br/>有更艱難的生涯！<br/>',NULL,9651,9651);
INSERT INTO stanza VALUES('C462','3','你要變節；<br/>或忠心到死，<br/>讓一切完全損失，<br/>直等到<br/>永活主的豐盛生命，<br/>天天充滿在你靈？<br/>',NULL,9652,9652);
INSERT INTO stanza VALUES('C462','4','神的救法是由死得生<br/>－你與主合為一人－在十架你因信<br/>已與祂同釘，<br/>從你身活出祂命。<br/>',NULL,9653,9653);
INSERT INTO stanza VALUES('C462','5','我們的得失並不要緊，<br/>神的旨意當留心，<br/>我們若將萬事<br/>都看如糞土，<br/>主纔不會受攔阻。<br/>',NULL,9654,9654);
INSERT INTO stanza VALUES('C463','1','十架樂接受，<br/>窄路肯行走，<br/>流露生命，不再將主扣；<br/>世界丟背後，<br/>主外無所求，<br/>流露生命，不再將主扣。<br/>',NULL,9655,9655);
INSERT INTO stanza VALUES('C463','chorus','流露！流露！<br/>流露生命，不再扣留；<br/>流露！流露！<br/>流露生命，不再將主扣。<br/>',NULL,9656,9656);
INSERT INTO stanza VALUES('C464','1','我若認識復活大能，<br/>必愛十架的模型；<br/>惟死能使生命長成，<br/>若不死了，就不生。<br/>',NULL,9657,9657);
INSERT INTO stanza VALUES('C464','chorus','不死就不生，<br/>不死就不生，<br/>惟死能使生命長成，<br/>不死就不生。<br/>',NULL,9658,9658);
INSERT INTO stanza VALUES('C464','2','基督要在我心成形，<br/>我就必須死乾淨，<br/>天天活在十架陰影，<br/>時時治死魂生命。<br/>',NULL,9659,9659);
INSERT INTO stanza VALUES('C464','3','惟願神藉永遠的靈，<br/>使我與主永同釘；<br/>死在我身發動運行，<br/>生在我身就顯明。<br/>',NULL,9660,9660);
INSERT INTO stanza VALUES('C465','1','我們現在默思<br/>葡萄一生的事：<br/>其路並不容易，<br/>其境也不安逸；<br/>生長不像野地野花，<br/>隨地隨意自由吐華；<br/>生成曲徑迷堂，<br/>生成款式百樣。<br/>',NULL,9661,9661);
INSERT INTO stanza VALUES('C465','2','反之，葡萄開花，<br/>非常渺小無華；<br/>人幾不能辨省，<br/>牠竟也曾有英；<br/>花尚未曾開得一日，<br/>即已迅速結為果實，<br/>不得成為驕葩，<br/>自感豐姿可誇。<br/>',NULL,9662,9662);
INSERT INTO stanza VALUES('C465','3','牠是拴在樁上，<br/>不能隨意生長；<br/>牠如伸肢展臂，<br/>也是架上被繫；<br/>牠就如此從了礫土，<br/>吸取牠的養生食物；<br/>不能自由揀選，<br/>不能遇難思遷。<br/>',NULL,9663,9663);
INSERT INTO stanza VALUES('C465','4','是的，綠衣秀美，<br/>春地披上明媚；<br/>因著生命豐裕，<br/>自然生長有餘；<br/>直至滿身嫩枝細苗，<br/>開始四向飄浮盤繞；<br/>在於青藍空中，<br/>嘗其甘美無窮。<br/>',NULL,9664,9664);
INSERT INTO stanza VALUES('C465','5','但是園主、園工，<br/>對牠並不放鬆；<br/>帶來刈剪、修刀，<br/>要剝牠的驕傲；<br/>毫不顧惜牠的細嫩，<br/>將牠割得又深又準，<br/>所有多餘美穗，<br/>盡都斷折破碎。<br/>',NULL,9665,9665);
INSERT INTO stanza VALUES('C465','6','在牠損失期間，<br/>牠並不敢自憐，<br/>乃是反將自己，<br/>更為完全徹底<br/>交付給那剝奪所有，<br/>使牠成為虛空的手；<br/>牠不浪費生活，<br/>一切都為結果。<br/>',NULL,9666,9666);
INSERT INTO stanza VALUES('C465','7','那些流血的枝，<br/>漸變堅硬木質；<br/>那些存留的穗，<br/>也漸結果纍纍；<br/>太陽又來迫牠枯乾，<br/>牠葉開始敗落四散，<br/>使牠果子盛紫，<br/>直至收成之日。<br/>',NULL,9667,9667);
INSERT INTO stanza VALUES('C465','8','牠因負重過甚，<br/>以致無枝不沉；<br/>這是長期努力，<br/>受盡琢磨來的；<br/>現今果實已經全美，<br/>自然牠可欣喜自慰；<br/>但是收成就到，<br/>欣慰日子何少！<br/>',NULL,9668,9668);
INSERT INTO stanza VALUES('C465','9','有手要來摘下，<br/>有腳要來踐踏，<br/>葡萄所有寶藏，<br/>在於酒醡之上，<br/>直到豐富、血紅的酒，<br/>浩蕩有如長江大流，<br/>終日湧溢不息，<br/>喜樂充滿大地。<br/>',NULL,9669,9669);
INSERT INTO stanza VALUES('C465','10','但是葡萄形狀，<br/>乃是剝光淒涼：<br/>已經給了一切，<br/>又將進入黑夜，<br/>卻無誰人向牠償還<br/>牠所給人酣醉之歡，<br/>反而將牠再砍，<br/>使成無枝禿榦。<br/>',NULL,9670,9670);
INSERT INTO stanza VALUES('C465','11','然而全冬之間，<br/>牠酒卻賜甘甜，<br/>給那寒冷之中，<br/>憂鬱愁苦之眾；<br/>但是葡萄卻在外面，<br/>孤獨經歷雪地冰天，<br/>堅定忍受一切，<br/>一切可疑、難解！<br/>',NULL,9671,9671);
INSERT INTO stanza VALUES('C465','12','直到寒冬已過，<br/>牠又豫備結果，<br/>重新萌芽生枝，<br/>再來放綠成姿；<br/>不因已往所受磨難，<br/>心中有了埋怨不甘；<br/>不因所失無限，<br/>而欲減少奉獻。<br/>',NULL,9672,9672);
INSERT INTO stanza VALUES('C465','13','牠的所有呼吸，<br/>盡是高天清氣，<br/>並不半點沾染<br/>不潔屬地情感；<br/>面向犧牲，依然含笑，<br/>再來接受愛的剝削，<br/>有如從未遇過<br/>損失、痛苦、折磨。<br/>',NULL,9673,9673);
INSERT INTO stanza VALUES('C465','14','葡萄從牠肢枝，<br/>流酒、流血、流汁，<br/>是否因已捨盡，<br/>牠就變為更貧？<br/>世上醉人、人間浪者，<br/>從牠暢飲，因牠作樂，<br/>是否因了享福，<br/>他們就變更富？<br/>',NULL,9674,9674);
INSERT INTO stanza VALUES('C465','15','估量生命原則，<br/>以失不是以得；<br/>不視酒飲幾多，<br/>乃視酒傾幾何；<br/>因為愛的最大能力，<br/>乃是在於愛的捨棄，<br/>誰苦受得最深，<br/>最有，可以給人。<br/>',NULL,9675,9675);
INSERT INTO stanza VALUES('C465','16','誰待自己最苛，<br/>最易為神選擇；<br/>誰傷自己最狠，<br/>最能擦人淚痕；<br/>誰不熟練損失、剝奪，<br/>誰就僅是響鈸、鳴鑼；<br/>誰能拯救自己，<br/>誰就不能樂極。<br/>',NULL,9676,9676);
INSERT INTO stanza VALUES('C466','1','『若是死了！』<br/>哦，這是主親口的信息！<br/>『若是死了，<br/>就必結出許多的子粒。』<br/>',NULL,9677,9677);
INSERT INTO stanza VALUES('C466','2','人得生命，你若真要，<br/>你就必須死；<br/>落在地裡死了，葬了，<br/>就必能結實。<br/>',NULL,9678,9678);
INSERT INTO stanza VALUES('C466','3','但主不會死中留你，<br/>祂命必逞能；<br/>祂必使你從死復起，<br/>充滿了新生。<br/>',NULL,9679,9679);
INSERT INTO stanza VALUES('C466','4','你願走主生命道路，<br/>釋放祂生命？<br/>當你經過死的路途，<br/>生命纔供應。<br/>',NULL,9680,9680);
INSERT INTO stanza VALUES('C466','5','你要學這有福祕訣：<br/>不死就不生；<br/>倒出生命，直到死絕，<br/>收穫必豐盈。<br/>',NULL,9681,9681);
INSERT INTO stanza VALUES('C467','1','你怎沒有傷痕？<br/>沒有傷痕<br/>在你身上、肋旁？<br/>你的名聲反而遠播四方，<br/>他們反而讚美你的光芒？<br/>你怎沒有傷痕？<br/>',NULL,9682,9682);
INSERT INTO stanza VALUES('C467','2','你怎沒有傷痕？<br/>我是受迫、孤獨、<br/>掛在樹上，<br/>四圍無情，<br/>都是殘忍、狂妄，<br/>我是受了鞭傷、<br/>刺傷、釘傷，<br/>你怎沒有傷痕？<br/>',NULL,9683,9683);
INSERT INTO stanza VALUES('C467','3','怎能你無傷痕？<br/>僕人不比主人更有希望，<br/>先生蒙羞，<br/>學生何能堂皇？<br/>而你卻是容易、<br/>完整、無恙！<br/>怎能你無傷痕？<br/>',NULL,9684,9684);
INSERT INTO stanza VALUES('C467','4','怎能你無傷痕？<br/>他們為我緣故<br/>受人捆綁、<br/>枷鎖、監禁、<br/>焚燒或是流放，<br/>或是捨身，<br/>餧獅在於廣場，<br/>怎能你無傷痕？<br/>',NULL,9685,9685);
INSERT INTO stanza VALUES('C467','5','你是沒有傷痕！<br/>我是被人摧殘，<br/>飲人鋒鋩，<br/>他們忍受忌恨，<br/>忍受刀棒，<br/>你卻平安無事，<br/>不缺寧康，<br/>你卻沒有傷痕！<br/>',NULL,9686,9686);
INSERT INTO stanza VALUES('C467','6','你卻沒有傷痕！<br/>能否是因你向世俗依傍，<br/>是因你怕自己利益失喪，<br/>因你遠遠跟隨，<br/>不甚明朗，<br/>所以沒有傷痕？<br/>',NULL,9687,9687);
INSERT INTO stanza VALUES('C467','7','你怎沒有傷痕？<br/>沒有疲倦，<br/>只有安然受享？<br/>能否有人忠心，<br/>受人獎賞？<br/>能否有人徹底跟隨羔羊，<br/>而他沒有傷痕？<br/>',NULL,9688,9688);
INSERT INTO stanza VALUES('C468','1','我若稍微偏離正路，<br/>我要立刻舒服；<br/>但我記念我主基督，<br/>如何忠心受苦。<br/>',NULL,9689,9689);
INSERT INTO stanza VALUES('C468','2','我今已經撇棄世界，<br/>所有關係都解；<br/>雖然道路越走越窄，<br/>但我在此是客。<br/>',NULL,9690,9690);
INSERT INTO stanza VALUES('C468','3','管他世人怒目白眼，<br/>我只求主笑臉；<br/>群眾雖然喜歡外貌，<br/>但我要主的『好。』<br/>',NULL,9691,9691);
INSERT INTO stanza VALUES('C468','4','我心所望不是偉大，<br/>不是今生通達；<br/>我願現在卑微事主，<br/>那日得祂稱許。<br/>',NULL,9692,9692);
INSERT INTO stanza VALUES('C468','5','我今每日舉目細望<br/>審判臺前亮光；<br/>願我所有生活、工作，<br/>那日都能耐火。<br/>',NULL,9693,9693);
INSERT INTO stanza VALUES('C468','6','讓你們去得著名聲、<br/>富足、榮耀、友朋，<br/>讓你們去得著成功、<br/>讚美、從者、興隆。<br/>',NULL,9694,9694);
INSERT INTO stanza VALUES('C468','7','但我只願孤單、貧窮，<br/>在此不求亨通；<br/>我心切望忠誠跟從<br/>我主到了路終。<br/>',NULL,9695,9695);
INSERT INTO stanza VALUES('C468','8','因我知道，主在此世<br/>不過得著一死，<br/>所以現在我無他望，<br/>只望因祂失喪。<br/>',NULL,9696,9696);
INSERT INTO stanza VALUES('C468','9','我的榮耀還在將來，<br/>今日只得忍耐；<br/>我決不肯先我的主，<br/>在此世界得福。<br/>',NULL,9697,9697);
INSERT INTO stanza VALUES('C468','10','那日我要得著冠冕，<br/>主要拭我淚眼！<br/>今日主既仍舊遲延，<br/>我要忠心進前。<br/>',NULL,9698,9698);
INSERT INTO stanza VALUES('C469','1','從伯利恆我們動身，<br/>學習耶穌的忠貞，<br/>跟著祂要完全歸神，<br/>但是臉上滿淚痕；<br/>因為馬槽那樣寒陋，<br/>並非我們所愛視；<br/>但是腳須與祂同走，<br/>如果手要接賞賜。<br/>',NULL,9699,9699);
INSERT INTO stanza VALUES('C469','2','經拿撒勒，這條道路，<br/>我們越走越窄小，<br/>多年勞碌無人領悟，<br/>常受羞辱，常無聊。<br/>但神藉此教訓我們：<br/>如此苦難，是因為<br/>僕人不能大於主人，<br/>所以當同祂流淚。<br/>',NULL,9700,9700);
INSERT INTO stanza VALUES('C469','3','經加利利，我們見祂<br/>被人厭棄，被人詛；<br/>祂路豈非走錯了麼？<br/>不然那有許多苦？<br/>不！不！這段雖然崎嶇，<br/>祂仍前進平安過；<br/>我們若要同祂高舉，<br/>也得前進不畏禍。<br/>',NULL,9701,9701);
INSERT INTO stanza VALUES('C469','4','隨後就在客西馬尼，<br/>園中孤單受磨煉，<br/>撒但全軍都來攻逼，<br/>這樣光景真難遣！<br/>但是我們並不失敗，<br/>因有天使來服事，<br/>並說：『應當注目賞賚，<br/>爭戰不過此一時。』<br/>',NULL,9702,9702);
INSERT INTO stanza VALUES('C469','5','十架到了！因為所有<br/>忠魂都當經加略；<br/>我們在此同祂蒙羞，<br/>不肯自憐，不退卻；<br/>因為不過一點時候，<br/>我們如此感苦痛；<br/>將來見祂，一切憂愁，<br/>要消在祂笑容中。<br/>',NULL,9703,9703);
INSERT INTO stanza VALUES('C469','6','隨到墳墓，親友環泣，<br/>知道已經無希望；<br/>（親愛旅伴！世人對你，<br/>是否算為已經亡？）<br/>我們從此與祂同升，<br/>遠離屬地的追求，<br/>心裡歡然失去世人<br/>所謂生命和富有。<br/>',NULL,9704,9704);
INSERT INTO stanza VALUES('C469','7','我們努力向竿而前，<br/>日近一日仍追隨；<br/>我們已經彷彿能見<br/>天城四射的光輝；<br/>我們已經隱約可聞<br/>天樂悠揚的清音；<br/>耶穌在彼迎接我們，<br/>要慰百創的這心。<br/>',NULL,9705,9705);
INSERT INTO stanza VALUES('C469','8','不過，再過幾里，朋友！<br/>腿要不酸，身不累，<br/>不再有罪，不再有憂，<br/>主要擦乾你眼淚；<br/>聽祂正用柔聲說道：<br/>『勿恐，勿餒，仍力前，<br/>因為也許明朝未到，<br/>旅程就已到終點。』<br/>',NULL,9706,9706);
INSERT INTO stanza VALUES('C470','1','惟有常出代價，<br/>願背十字架，<br/>我們纔會得勝，<br/>纔會得權能。<br/>不是自己力量，<br/>不是人思想，<br/>乃是耶穌尊名，<br/>使我們得贏。<br/>',NULL,9707,9707);
INSERT INTO stanza VALUES('C470','chorus','惟有常出代價，<br/>願背十字架，<br/>我們纔會得勝，<br/>纔會得權能。<br/>',NULL,9708,9708);
INSERT INTO stanza VALUES('C470','2','應當除去誇耀，<br/>絕一切機巧；<br/>我們應當爭戰，<br/>像耶穌一般：<br/>藉死亡得權能，<br/>藉失敗得勝，<br/>因十字架苦難，<br/>毀壞了撒但。<br/>',NULL,9709,9709);
INSERT INTO stanza VALUES('C470','3','既勇敢，又溫柔，<br/>慈仁且奮鬥；<br/>雖工作，亦安息，<br/>剛強卻無力；<br/>欲得反倒賜給，<br/>有能卻無倚；<br/>雖與救主同釘，<br/>卻滿有生命。<br/>',NULL,9710,9710);
INSERT INTO stanza VALUES('C470','4','我們若隨救主，<br/>走祂的道路，<br/>必須背十字架，<br/>與祂纔融洽。<br/>應當忍耐到底，<br/>雖死亦不避，<br/>直到救主顯現，<br/>得血染冠冕。<br/>',NULL,9711,9711);
INSERT INTO stanza VALUES('C471','1','『破毀帶我到主懷！』<br/>毀後如此唱出來！<br/>小船若是緊靠岸，<br/>深怕風浪的為患，<br/>難知在主的懷裡，<br/>毀後所享的安息。<br/>',NULL,9712,9712);
INSERT INTO stanza VALUES('C471','2','我們哀歎：『被破毀！』<br/>豈知『破毀』當讚美！<br/>風浪無情的損傷，<br/>使我主懷享餧養。<br/>在此安息主懷中，<br/>何能再將我搖動？<br/>',NULL,9713,9713);
INSERT INTO stanza VALUES('C471','3','『破毀』之後，不需要<br/>任何航行的技巧；<br/>雖然仍舊在航行，<br/>卻是拋錨在天庭；<br/>再不需要作或慮，<br/>只要我和主同居。<br/>',NULL,9714,9714);
INSERT INTO stanza VALUES('C471','4','『破毀！』成為我純益，<br/>其他航者要驚奇：<br/>像似殘忍的摧毀，<br/>實是化裝的恩惠！<br/>毀後乃是在主手，<br/>有主自己來看守。<br/>',NULL,9715,9715);
INSERT INTO stanza VALUES('C472','1','死亡不能拘禁復活生命－神那非受造的永遠生命；<br/>剛強、得勝、<br/>無何能以毀壞，<br/>就是基督自己，<br/>已經顯明。<br/>',NULL,9716,9716);
INSERT INTO stanza VALUES('C472','2','死亡不能拘禁復活生命，<br/>雖然死亡集中全力以赴；<br/>死亡不過使這神聖生命<br/>得機顯牠能力無量豐富。<br/>',NULL,9717,9717);
INSERT INTO stanza VALUES('C472','3','死亡不能拘禁復活生命，<br/>治死、埋葬，<br/>不過叫牠繁殖；<br/>所有苦難都是叫牠增長，<br/>並且結出豐盛生命果實。<br/>',NULL,9718,9718);
INSERT INTO stanza VALUES('C472','4','死亡不能拘禁復活生命，<br/>牠能衝破<br/>所有障礙、阻擋；<br/>勝過黑暗、<br/>陰府所有權勢，<br/>吞滅死亡，<br/>並將生命釋放。<br/>',NULL,9719,9719);
INSERT INTO stanza VALUES('C472','5','死亡不能拘禁復活生命，<br/>牠能顯出神性所有豐滿；<br/>神的公義、聖潔，<br/>牠都產生，<br/>神的榮耀形像牠全彰顯。<br/>',NULL,9720,9720);
INSERT INTO stanza VALUES('C472','6','願我認識這個復活生命，<br/>每遇死亡，<br/>都讓牠力傾出；<br/>使我藉著經歷永遠賞識：復活生命就是活的基督。<br/>',NULL,9721,9721);
INSERT INTO stanza VALUES('C473','1','由死而生－恩主，這乃是說明，<br/>生命在此，<br/>或是在於來世？<br/>不必等候！<br/>毀壞破碎的器皿，<br/>即今可在陶人手中陶製。<br/>',NULL,9722,9722);
INSERT INTO stanza VALUES('C473','2','由死而生－何等奇妙的復活！<br/>種時明感軟弱，<br/>起時強壯；<br/>你的生命<br/>顯於勞碌和折磨；<br/>時刻非我，<br/>乃是基督我王。<br/>',NULL,9723,9723);
INSERT INTO stanza VALUES('C473','3','由死而生－客旅道路何孤單，<br/>認識十架者卻都願同行，<br/>效法祂死，<br/>他們與祂同苦難，<br/>因祂，<br/>就將萬事當作有損。<br/>',NULL,9724,9724);
INSERT INTO stanza VALUES('C473','4','由死而生－何等有福的使命！<br/>從天上的潔清白明江河，<br/>帶著活泉，<br/>生命洋溢又豐盛，<br/>告訴渴人，<br/>從茲無需再渴。<br/>',NULL,9725,9725);
INSERT INTO stanza VALUES('C474','1','你這因著奔正路，<br/>手垂腿酸之人，<br/>望斷以及於耶穌，<br/>免得疲倦灰心；<br/>祂的面光照燦爛，<br/>驅盡困人黑暗，<br/>你若仰望祂榮面，<br/>就必明如中天。<br/>',NULL,9726,9726);
INSERT INTO stanza VALUES('C474','2','望斷以及於耶穌，<br/>你就必不看見<br/>逼迫、艱難與貧苦，<br/>如何四圍為患；<br/>沒有憂傷的眼淚，<br/>能使你眼失明，<br/>沒有驚險的可畏，<br/>能使你心迷蒙。<br/>',NULL,9727,9727);
INSERT INTO stanza VALUES('C474','3','望斷以及於耶穌，<br/>你靈必蒙恩湛，<br/>在這世上有苦楚，<br/>在祂裡面平安；<br/>雖在人生苦海中，<br/>時有波浪澎湃，<br/>你若仰望祂面容，<br/>你心必不驚駭。<br/>',NULL,9728,9728);
INSERT INTO stanza VALUES('C474','4','望斷以及於耶穌，<br/>你就不會迷糊，<br/>你若向祂常舉目，<br/>祂必指你正路；<br/>當祂領你向前走，<br/>即使遇到雲霧，<br/>你若向祂常仰首，<br/>也必不會錯誤。<br/>',NULL,9729,9729);
INSERT INTO stanza VALUES('C474','5','望斷以及於耶穌，<br/>直到被提上天，<br/>直到榮耀的面目，<br/>完全顯你眼前；<br/>今日仰望之榮面，<br/>使你路中得力，<br/>那日變作你頌讚，<br/>使你永遠歡喜。<br/>',NULL,9730,9730);
INSERT INTO stanza VALUES('C475','1','暗中摸索，無一線光明！<br/>何等疲乏！何等勞形！<br/>但一仰望基督你的王，<br/>甚麼都必照耀輝煌。<br/>',NULL,9731,9731);
INSERT INTO stanza VALUES('C475','chorus','轉眼將耶穌觀看！<br/>注目仰望祂的榮面！<br/>所有事物在祂榮耀光中，<br/>都要次第變色成曚曨。<br/>',NULL,9732,9732);
INSERT INTO stanza VALUES('C475','2','經過死亡就必得生命，<br/>祂已前去，我們隨行；<br/>罪的權勢今已經過去，<br/>我們已經得勝有餘。<br/>',NULL,9733,9733);
INSERT INTO stanza VALUES('C475','3','祂的應許終不至落空，<br/>若信靠祂，事事亨通；<br/>所以應當堅定不灰心，<br/>你必經歷祂的救恩。<br/>',NULL,9734,9734);
INSERT INTO stanza VALUES('C476','1','活在生命光中，<br/>不斷與主交通，<br/>瞻仰恩主慈容，<br/>順從聖靈感動，<br/>天天榮上加榮，<br/>時時讚美稱頌，<br/>活在生命光中。<br/>',NULL,9735,9735);
INSERT INTO stanza VALUES('C477','1','用功朝見主面，<br/>多和主對講，<br/>常住在祂裡面，<br/>以祂話為糧。<br/>等候在祂面前，<br/>柔順且降服，<br/>每件事上不忘<br/>尋求祂祝福。<br/>',NULL,9736,9736);
INSERT INTO stanza VALUES('C477','2','用功朝見主面，<br/>事務雖忙碌；<br/>多花時間單獨<br/>和主在密處。<br/>藉著仰望耶穌，<br/>你變祂形像；<br/>在你行為之上，<br/>人見祂模樣。<br/>',NULL,9737,9737);
INSERT INTO stanza VALUES('C477','3','用功朝見主面，<br/>讓祂作領導；<br/>任何事情發生，<br/>不在祂前跑；<br/>無論是樂是苦，<br/>始終跟隨主，<br/>始終相信祂話，<br/>常仰望耶穌。<br/>',NULL,9738,9738);
INSERT INTO stanza VALUES('C477','4','用功朝見主面，<br/>內心須寧靜；<br/>讓祂前來管理<br/>意念和性情。<br/>祂靈把你帶到<br/>愛的發源所，<br/>如此你纔配作<br/>屬天的工作。<br/>',NULL,9739,9739);
INSERT INTO stanza VALUES('C478','1','親愛基督精兵，<br/>戰場在衝鋒，<br/>前曾倚賴自己，<br/>爭戰難得勝；<br/>勿再倚靠自己，<br/>單靠基督大力；<br/>在那加力基督裡，<br/>凡事我都能作。<br/>',NULL,9740,9740);
INSERT INTO stanza VALUES('C478','2','在你日常分內，<br/>站住為正義，<br/>是否有時厭倦，<br/>感到不容易？<br/>務要投靠救主，<br/>你擔祂肯背負：<br/>在那加力基督裡，<br/>凡事我都能作。<br/>',NULL,9741,9741);
INSERT INTO stanza VALUES('C478','3','路中若感疲乏，<br/>祂必願扶助，<br/>無論你是喜樂，<br/>或者是痛苦；<br/>雖經水深火熱，<br/>也必安然渡過：<br/>在那加力基督裡，<br/>凡事我都能作。<br/>',NULL,9742,9742);
INSERT INTO stanza VALUES('C478','4','在這邪惡世界，<br/>試探實頻繁，<br/>但你不需跌倒，<br/>撒但必逃竄；<br/>他必全然徒勞，<br/>只要你肯宣告：<br/>在那加力基督裡，<br/>凡事我都能作。<br/>',NULL,9743,9743);
INSERT INTO stanza VALUES('C478','5','基督能力無量，<br/>深廣如海洋；<br/>祂能拯救到底，<br/>凡事都擔當；<br/>祂的彀用恩力，<br/>將我軟弱覆庇：<br/>在那加力基督裡，<br/>凡事我都能作。<br/>',NULL,9744,9744);
INSERT INTO stanza VALUES('C479','1','要思想耶穌，<br/>以祂作模型，<br/>好在你身上顯出祂榮形：祂已經賜你永遠的生命，<br/>並使你享受復活的大能。<br/>',NULL,9745,9745);
INSERT INTO stanza VALUES('C479','2','要思想耶穌，<br/>天天都如此，<br/>要自甘卑微，<br/>不再有大志；<br/>那無窮生命也要多認識，<br/>靠復活大能經歷主的死。<br/>',NULL,9746,9746);
INSERT INTO stanza VALUES('C479','3','要思想耶穌，<br/>一生當這樣，<br/>要活在幔內常見主榮光；<br/>若棄掉自己，<br/>必知主心意，<br/>一脫離自己，<br/>純潔又安息。<br/>',NULL,9747,9747);
INSERT INTO stanza VALUES('C479','4','要思想耶穌，<br/>當你在向前，<br/>要一直向上瞻仰祂榮面，<br/>必榮上加榮，<br/>變成祂形狀，<br/>使祂的形像顯在你身上。<br/>',NULL,9748,9748);
INSERT INTO stanza VALUES('C480','1','你們能否順從<br/>你一切的主，<br/>如果地要震動，<br/>天象要翻覆？<br/>你們能否相信，<br/>神與你同在，<br/>就是災禍忽臨，<br/>必定不見害？<br/>',NULL,9749,9749);
INSERT INTO stanza VALUES('C480','2','你們能否順從<br/>所事奉的主，<br/>不稍軟弱、驚恐，<br/>也不稍讓步？<br/>雖然你的前途<br/>好像是死路，<br/>此時能否順服，<br/>而不一自顧？<br/>',NULL,9750,9750);
INSERT INTO stanza VALUES('C480','3','你真能否順從，<br/>如果主召你<br/>加入前線進攻，<br/>抵禦兇仇敵？<br/>你真能否立前，<br/>歡喜受差遣？<br/>你真能否爭戰，<br/>直到晚色遍？<br/>',NULL,9751,9751);
INSERT INTO stanza VALUES('C480','4','能否？我的弟兄，<br/>你神已久等，<br/>應當服祂權柄，<br/>遵行祂命令。<br/>你若作主精兵，<br/>當祂再降臨，<br/>祂要題起你名，<br/>並說你『忠心！』<br/>',NULL,9752,9752);
INSERT INTO stanza VALUES('C481','1','應當一無罣慮，<br/>主已經近了；<br/>應當信神應許，<br/>平安不動搖；<br/>你切不可失敗，<br/>也不可失檢，<br/>因耶穌快要來，<br/>也許是今天。<br/>',NULL,9753,9753);
INSERT INTO stanza VALUES('C481','2','應當一無罣慮，<br/>凡事交託主；<br/>祂替你罪受鞫，<br/>必替你擔苦。<br/>你當自由進前，<br/>尋機會證明：<br/>祂愛心的甘甜，<br/>祂手的堅定。<br/>',NULL,9754,9754);
INSERT INTO stanza VALUES('C481','3','應當一無罣慮；<br/>即云主遲延，<br/>祂能力要扶勗<br/>你終身無間；<br/>你可相信祂心，<br/>你可靠祂手，<br/>這樣有何可驚，<br/>當力前勿愁。<br/>',NULL,9755,9755);
INSERT INTO stanza VALUES('C482','1','神的應許不能廢去，<br/>句句都是堅定；<br/>信心從來不用憑據，<br/>因神言出必行。<br/>',NULL,9756,9756);
INSERT INTO stanza VALUES('C482','chorus','天地雖能被焚燒，<br/>小山大山雖傾倒，<br/>但那相信主的人，<br/>必見主話得成。<br/>',NULL,9757,9757);
INSERT INTO stanza VALUES('C482','2','你心應該像亞伯蘭，<br/>那樣舉目望天，<br/>數算眾星，輕看艱難，<br/>信心越久越堅。<br/>',NULL,9758,9758);
INSERT INTO stanza VALUES('C482','3','即使黑雲暫時濃厚，<br/>雲上太陽未變，<br/>只要再過一點時候，<br/>陽光就要顯現。<br/>',NULL,9759,9759);
INSERT INTO stanza VALUES('C482','4','雖遇試煉，仍要鎮定，<br/>因為在火窯中，<br/>有榮耀的神子同行，<br/>仇敵終要擊空。<br/>',NULL,9760,9760);
INSERT INTO stanza VALUES('C482','5','縱然朋友都辜負你，<br/>但你還當信神，<br/>因為耶穌你的能力，<br/>仍然親近施恩。<br/>',NULL,9761,9761);
INSERT INTO stanza VALUES('C482','6','凡事倚賴神的大力，<br/>直到被提上天；<br/>現在所望所深信的，<br/>將來都必實現。<br/>',NULL,9762,9762);
INSERT INTO stanza VALUES('C483','1','前進！是我口號，<br/>步聲相接聯；<br/>向著標竿直跑，<br/>永不回頭看。<br/>軍前火柱燦爛，<br/>照明我路程；<br/>誰還畏縮不前，<br/>基督在率領。<br/>前進！經過曠野，<br/>經過苦戰爭；<br/>迦南不再隱約，<br/>錫安放光明。<br/>',NULL,9763,9763);
INSERT INTO stanza VALUES('C483','2','榮耀又加榮耀，<br/>父神已豫備；<br/>凡愛神者必要<br/>有分於此內：<br/>眼睛未曾看見，<br/>耳朵未曾聽，<br/>榮耀達到極點，<br/>心想也未曾。<br/>前進！一直前進！<br/>直到國度顯，<br/>直到幔子不存，<br/>信心變眼見。<br/>',NULL,9764,9764);
INSERT INTO stanza VALUES('C483','3','前進！天就要明，<br/>聖城在眼前；<br/>天上耶路撒冷，<br/>等你嘗新鮮。<br/>進入自由榮光，<br/>得戴榮耀冕。<br/>與主基督同王，<br/>掌權到永遠。<br/>向彼，前進！向彼，<br/>奔完你程途，<br/>靠主大能大力，<br/>前進！入國度。<br/>',NULL,9765,9765);
INSERT INTO stanza VALUES('C484','1','當向標竿力前！<br/>雖然孤單，不變；<br/>那開路者現在召你，<br/>所以當前勿延。<br/>',NULL,9766,9766);
INSERT INTO stanza VALUES('C484','2','當向標竿力前！<br/>主眼睛像火焰，<br/>正在看你；人算甚麼？<br/>何必管他喜厭！<br/>',NULL,9767,9767);
INSERT INTO stanza VALUES('C484','3','當向標竿力前！<br/>不要再望後面，<br/>因為前頭就是獎賞，<br/>主要賜給冠冕。<br/>',NULL,9768,9768);
INSERT INTO stanza VALUES('C484','4','當向標竿力前！<br/>塞耳、啞口、閉眼，<br/>在崎嶇的血跡路上，<br/>緊隨基督向前！<br/>',NULL,9769,9769);
INSERT INTO stanza VALUES('C485','1','靠著恩主全能神，<br/>往前走！往前走！<br/>抓住應許憑信心，<br/>往前走！<br/>含地永不再逗遛，<br/>埃及從此丟背後，<br/>就此一去不回頭，<br/>往前走！<br/>',NULL,9770,9770);
INSERT INTO stanza VALUES('C485','2','雖然後面仇敵追，<br/>往前走！往前走！<br/>雖然前面是深水，<br/>往前走！<br/>深水為你必分開，<br/>仇敵全都必淹埋，<br/>救恩使你必奏凱，<br/>往前走！<br/>',NULL,9771,9771);
INSERT INTO stanza VALUES('C485','3','白晝雲柱來引導，<br/>往前走！往前走！<br/>黑夜火柱來光照，<br/>往前走！<br/>飢餓，嗎哪必降來，<br/>乾渴，磐石必裂開，<br/>遇敵，尼西必擊敗，<br/>往前走！<br/>',NULL,9772,9772);
INSERT INTO stanza VALUES('C485','4','曠野道路雖艱險，<br/>往前走！往前走！<br/>跟隨約櫃直往前，<br/>往前走！<br/>往前！直到過約但，<br/>往前！直到進迦南！<br/>往前！n直到在錫安，<br/>往前走！<br/>',NULL,9773,9773);
INSERT INTO stanza VALUES('C487','1','靈要操練運用，<br/>魂卻要拒絕；<br/>無論生活行動，<br/>以此為祕訣。<br/>',NULL,9777,9777);
INSERT INTO stanza VALUES('C487','2','靈要操練運用，<br/>規條要棄絕；<br/>恩膏塗抹順從，<br/>時刻無間歇。<br/>',NULL,9778,9778);
INSERT INTO stanza VALUES('C487','3','靈要操練運用，<br/>己意要拒絕；<br/>活在生命光中，<br/>讓主作一切。<br/>',NULL,9779,9779);
INSERT INTO stanza VALUES('C487','4','靈肯操練運用，<br/>魂肯全拒絕，<br/>就能讚美、稱頌，<br/>問題全解決。<br/>',NULL,9780,9780);
INSERT INTO stanza VALUES('C487','5','靈肯操練運用，<br/>主就有出路；<br/>靈肯操練運用，<br/>我就享豐富。<br/>',NULL,9781,9781);
INSERT INTO stanza VALUES('C487','6','靈肯操練運用，<br/>主就能摸到；<br/>靈肯操練運用，<br/>我就被建造。<br/>',NULL,9782,9782);
INSERT INTO stanza VALUES('C487','7','靈要操練運用，<br/>這是主所要；<br/>靈肯操練運用，<br/>主就得榮耀。<br/>',NULL,9783,9783);
INSERT INTO stanza VALUES('C488','1','何必擔心一握不釋？<br/>且讓先知先果腹；<br/>若是神管你的度支，<br/>你的來源何患枯？<br/>每天都有新的需要，<br/>每天必有新供給；<br/>你既然是祂所創造，<br/>祂豈不為你設計？<br/>',NULL,9784,9784);
INSERT INTO stanza VALUES('C488','chorus','仍然當愛，仍然當給，<br/>照舊你還餘一握；<br/>所有的愛，所有的給，<br/>要使神賜加倍多。<br/>',NULL,9785,9785);
INSERT INTO stanza VALUES('C488','2','相信！時候不至耽擱，<br/>雖是不快，總不慢；<br/>相信！瓶子不至乾涸，<br/>永遠不空，也不滿。<br/>縱使百合缺了衣衫，<br/>縱使小鳥無食啄，<br/>但是寡婦微小麵罈，<br/>必定依然有一握。<br/>',NULL,9786,9786);
INSERT INTO stanza VALUES('C488','3','何必豫料明天境遇，<br/>目前彀了就可樂；<br/>何必先借明天憂慮，<br/>手裡豈非還有著！<br/>愛是生活，給反存留，<br/>種得多的收也多；<br/>好像你已罄你所有，<br/>看哪！你還有一握！<br/>',NULL,9787,9787);
INSERT INTO stanza VALUES('C489','1','你曾覺得父愛心？<br/>不只這麼一點；<br/>你曾嘗到祂憐憫？<br/>不只這麼一點。<br/>父的慈愛何等大，<br/>不只這麼一點；<br/>平白賜給無代價，<br/>不只這麼一點。<br/>',NULL,9788,9788);
INSERT INTO stanza VALUES('C489','chorus','多又多，多又多，<br/>不只這麼一點，<br/>神的大愛難盡說，<br/>不只這麼一點。<br/>',NULL,9789,9789);
INSERT INTO stanza VALUES('C489','2','你曾覺得主親近？<br/>不只這麼一點；<br/>祂的同在樂你心？<br/>不只這麼一點；<br/>主的恩典何等大，<br/>不只這麼一點；<br/>平白賜給無代價，<br/>不只這麼一點。<br/>',NULL,9790,9790);
INSERT INTO stanza VALUES('C489','3','你覺聖靈的能力？<br/>不只這麼一點；<br/>猶如甘雨臨及你？<br/>不只這麼一點。<br/>聖靈能力何等大，<br/>不只這麼一點；<br/>平白賜給無代價，<br/>不只這麼一點。<br/>',NULL,9791,9791);
INSERT INTO stanza VALUES('C490','1','我常居住天愛中，<br/>不怕改變一點；<br/>如此把握不落空，<br/>在此沒有改變。<br/>也許狂風四面起，<br/>也許無多希望；<br/>但神四面來護庇，<br/>我怎能彀徬徨？<br/>',NULL,9792,9792);
INSERT INTO stanza VALUES('C490','2','窮困難迫我回頭，<br/>任主領我何方；<br/>我不至有何不彀，<br/>我的牧人在旁。<br/>祂的慧心常清醒，<br/>祂的明眼不眛，<br/>祂知祂行的路徑，<br/>我要始終跟隨。<br/>',NULL,9793,9793);
INSERT INTO stanza VALUES('C490','3','青草地場尚在前，<br/>是我從所未見；<br/>再過就是清朗天，<br/>今雖稠雲綿綿。<br/>我的希望真久長，<br/>我的途徑光明，<br/>救主掌握我寶藏，<br/>祂要和我同行。<br/>',NULL,9794,9794);
INSERT INTO stanza VALUES('C490','4','或許明朝天未曉，<br/>我靈不及等待，<br/>就脫肉體全不要，<br/>主，就與你同在。<br/>安息！睡眠！何寶貴，<br/>有你保護照顧；<br/>或許你忽榮耀歸，<br/>召我座前相晤！<br/>',NULL,9795,9795);
INSERT INTO stanza VALUES('C490','5','那時看見你自己，<br/>被眾選民擁擠，<br/>又是榮耀又美麗，<br/>又是歌唱無已。<br/>奇妙應許的日期，<br/>我們能彀同你<br/>永遠享受神安息，<br/>永遠喜樂滿意。<br/>',NULL,9796,9796);
INSERT INTO stanza VALUES('C491','1','『我必與你同在，』<br/>甜美的應許，<br/>安慰我的心懷，<br/>消除我驚懼；<br/>在此幽暗長夜，<br/>主是我盾牌，<br/>永不將我棄絕，<br/>必與我同在。<br/>',NULL,9797,9797);
INSERT INTO stanza VALUES('C491','chorus','主與我同在，<br/>主與我同在，<br/>主曾應許與我同在，<br/>直到永遠不離開；<br/>主與我同在，<br/>主與我同在，<br/>主曾應許與我同在，<br/>直到永遠不離開。<br/>',NULL,9798,9798);
INSERT INTO stanza VALUES('C491','2','四圍鮮花敗落，<br/>主愛不凋殘，<br/>地上日光滅沒，<br/>天光仍燦爛；<br/>主如一袋沒藥，<br/>整夜在我懷，<br/>直到晨曦破曉，<br/>必與我同在。<br/>',NULL,9799,9799);
INSERT INTO stanza VALUES('C491','3','前途雖然艱困，<br/>試煉要來臨，<br/>但主必更親近，<br/>必說『可放心；』<br/>喜樂猶如春鳥，<br/>飛入我心懷，<br/>使我甜美唱道：<br/>『主與我同在！』<br/>',NULL,9800,9800);
INSERT INTO stanza VALUES('C492','1','在祂翼下，<br/>平安穩妥我居住，<br/>不管夜色多深，<br/>且有風雨；<br/>但我能信靠，<br/>我知祂必眷顧，<br/>因祂已救我，<br/>我是祂兒女。<br/>',NULL,9801,9801);
INSERT INTO stanza VALUES('C492','chorus','在祂翼下，<br/>在祂翼下，<br/>誰能使我離祂愛！<br/>在祂翼下，<br/>這是我的家，<br/>我必與主永同在。<br/>',NULL,9802,9802);
INSERT INTO stanza VALUES('C492','2','在祂翼下，<br/>我能躲過我憂傷，<br/>我心滿足，<br/>我能在此安歇，<br/>世上並無膏油<br/>可治我病創，<br/>在此我得祝福，<br/>我得慰藉。<br/>',NULL,9803,9803);
INSERT INTO stanza VALUES('C492','3','在祂翼下，<br/>何等寶貴的享受！<br/>一生在此，<br/>直到試煉過去；<br/>有主保護蔭庇，<br/>無何再添愁，<br/>安息於主，<br/>我是永遠無虞。<br/>',NULL,9804,9804);
INSERT INTO stanza VALUES('C493','1','應當住在神的翅下，<br/>神必定顧念你；<br/>任何遭遇不要驚怕，<br/>神必定顧念你。<br/>',NULL,9805,9805);
INSERT INTO stanza VALUES('C493','chorus','神必定顧念你，<br/>時時顧念，處處顧念，<br/>祂必定顧念你，<br/>神必定顧念你。<br/>',NULL,9806,9806);
INSERT INTO stanza VALUES('C493','2','時因困難心中失望，<br/>神必定顧念你；<br/>時遇險惡無處隱藏，<br/>神必定顧念你。<br/>',NULL,9807,9807);
INSERT INTO stanza VALUES('C493','3','無一祈求祂會推諉，<br/>神必定顧念你；<br/>所有需要祂必豫備，<br/>神必定顧念你。<br/>',NULL,9808,9808);
INSERT INTO stanza VALUES('C493','4','無論你遇何種試煉，<br/>神必定顧念你；<br/>疲倦的人，靠祂胸前，<br/>神必定顧念你。<br/>',NULL,9809,9809);
INSERT INTO stanza VALUES('C494','1','當你經過試煉，<br/>茫然無所從，<br/>你心絕望，<br/>以為甚麼都失蹤；<br/>就當數主祝福，<br/>當一一的數，<br/>你就要希奇<br/>祂曾如何眷顧。<br/>',NULL,9810,9810);
INSERT INTO stanza VALUES('C494','chorus','數主祝福！<br/>要一一的數！<br/>記看祂曾如何眷顧你！<br/>數主祝福！<br/>要一一的數！<br/>你就要希奇<br/>祂曾如何愛你。<br/>',NULL,9811,9811);
INSERT INTO stanza VALUES('C494','2','當你有所罣慮，<br/>如同挑重擔，<br/>覺得所要負的<br/>十架苦難堪，<br/>你若數主祝福，<br/>疑惑要消散，<br/>並要不止住的<br/>歡樂和頌讚。<br/>',NULL,9812,9812);
INSERT INTO stanza VALUES('C494','3','當你看見別人<br/>屬世的亨通，<br/>你若念主應許，<br/>心就不會動；<br/>你所受的祝福，<br/>原來無處買，<br/>你有了父的家，<br/>又有主的愛。<br/>',NULL,9813,9813);
INSERT INTO stanza VALUES('C494','4','所以，無論遇見<br/>大小的試探，<br/>不必灰心，<br/>萬事總有主承擔，<br/>你若數主祝福，<br/>天使要來臨，<br/>伺候你，服侍你，<br/>直到你路盡。<br/>',NULL,9814,9814);
INSERT INTO stanza VALUES('C495','1','路途遙遠，負擔沉著，<br/>力盡身疲要倒下；<br/>請聽主聲，柔然輕說：<br/>重擔當託耶和華。<br/>',NULL,9815,9815);
INSERT INTO stanza VALUES('C495','chorus','重擔當託耶和華，<br/>重擔當託耶和華，<br/>主會安慰你，<br/>又會堅固你，<br/>重擔當託耶和華。<br/>',NULL,9816,9816);
INSERT INTO stanza VALUES('C495','2','雙腳已軟，雙手已酸，<br/>燈火將滅目又花，<br/>眼見就要心灰氣短，<br/>重擔當託耶和華。<br/>',NULL,9817,9817);
INSERT INTO stanza VALUES('C495','3','親友離散，遭遇淒涼，<br/>憂心難解常懸罣，<br/>一身難受如此創傷，<br/>重擔當託耶和華。<br/>',NULL,9818,9818);
INSERT INTO stanza VALUES('C495','4','孤單軟弱，無所傍倚，<br/>心緒起落亂如麻，<br/>都是因為我們忘記<br/>重擔當託耶和華。<br/>',NULL,9819,9819);
INSERT INTO stanza VALUES('C495','5','祂會安慰，祂會堅固，<br/>祂要使你力有加，<br/>祂要使你心境安舒，<br/>重擔當託耶和華。<br/>',NULL,9820,9820);
INSERT INTO stanza VALUES('C496','1','當我遇見試煉災殃，<br/>經過荊棘豺狼之疆，<br/>我有一個甘美思想，<br/>就是主懷念我。<br/>',NULL,9821,9821);
INSERT INTO stanza VALUES('C496','chorus','主，你正懷念我！<br/>主，你正懷念我！<br/>我怕甚麼？<br/>有你親近，<br/>並且還懷念我！<br/>',NULL,9822,9822);
INSERT INTO stanza VALUES('C496','2','今生憂慮、苦難、折磨，<br/>使我心思都變昏黑，<br/>但是苦境使我記得：<br/>主，你正懷念我！<br/>',NULL,9823,9823);
INSERT INTO stanza VALUES('C496','3','所以，無論愁雲多少，<br/>無論安樂，或是苦惱，<br/>我已滿足，因我知道：<br/>主還是懷念我。<br/>',NULL,9824,9824);
INSERT INTO stanza VALUES('C497','1','神阿，<br/>你名何等廣大泱漭！<br/>我今投身其中，<br/>心頂安然；<br/>有你彀了，<br/>無論日有多長；<br/>有你彀了，<br/>無論夜有多暗。<br/>',NULL,9825,9825);
INSERT INTO stanza VALUES('C497','2','有你彀了，<br/>無論事多紛煩；<br/>有你彀了，<br/>無論境多寂寞；<br/>有你，<br/>我就已經能彀盡歡，<br/>有你，<br/>我就已經能彀唱歌。<br/>',NULL,9826,9826);
INSERT INTO stanza VALUES('C497','3','你是我神！<br/>全有！全足！全豐！<br/>你能為我創造我所缺乏；<br/>有你自己，<br/>在我回家途中，<br/>無論有何需要，<br/>都必無差。<br/>',NULL,9827,9827);
INSERT INTO stanza VALUES('C497','4','我的神阿，<br/>你在已過路上，<br/>曾用愛的神蹟多方眷顧；<br/>故我敢再投入你的胸膛，<br/>因信心安，<br/>讚美你的道路。<br/>',NULL,9828,9828);
INSERT INTO stanza VALUES('C498','1','時常攜帶耶穌的名，<br/>你們憂愁困苦人，<br/>祂能賜你安慰、安寧，<br/>除去所有的煩悶。<br/>',NULL,9829,9829);
INSERT INTO stanza VALUES('C498','chorus','寶貝名，何甘甜！<br/>世之望和天之樂！<br/>寶貝名，何甘甜！<br/>世之望和天之樂。<br/>',NULL,9830,9830);
INSERT INTO stanza VALUES('C498','2','時常攜帶耶穌的名，<br/>當作籐牌敵火箭；<br/>每逢誘惑攪擾你靈，<br/>呼吸這名在心間。<br/>',NULL,9831,9831);
INSERT INTO stanza VALUES('C498','3','當祂愛手撫摩、安慰，<br/>當我舌頭在歌唱，<br/>耶穌的名何等寶貝，<br/>使我心頭滿歡暢。<br/>',NULL,9832,9832);
INSERT INTO stanza VALUES('C498','4','等到被提、面見救主，<br/>耶穌的名仍頌揚，<br/>在祂腳前歡然俯伏，<br/>尊敬祂為王中王。<br/>',NULL,9833,9833);
INSERT INTO stanza VALUES('C499','1','非我所是，<br/>主阿，乃你所是，<br/>只有這個會叫我心安寧；<br/>你(非我)愛<br/>會叫疑惑消失，<br/>會叫起伏心懷<br/>風平、波靜。<br/>',NULL,9834,9834);
INSERT INTO stanza VALUES('C499','2','祂今賜福，<br/>並要永遠賜福，<br/>祂今救我，<br/>並要永遠救我，<br/>祂要扶我，<br/>在此無倚中途，<br/>祂要領我危關<br/>平安度過。<br/>',NULL,9835,9835);
INSERT INTO stanza VALUES('C499','3','我主、我神！<br/>我的對你認識，<br/>使我心滿平安，<br/>口滿歌唱；<br/>你是我的生命、<br/>喜樂、杖子，<br/>倚身於你，<br/>使我軟弱變強。<br/>',NULL,9836,9836);
INSERT INTO stanza VALUES('C499','4','我是缺乏、飢渴，<br/>我這心懷<br/>焦慕這裡所難尋的甘甜：<br/>戀人逐漸離開，<br/>他們離開<br/>留下空隙<br/>為著更為可戀。<br/>',NULL,9837,9837);
INSERT INTO stanza VALUES('C499','5','更多的你，<br/>求你時刻啟迪，<br/>更多你的榮耀，<br/>我主、我神！<br/>更多的你，<br/>在於恩典、能力，<br/>更多你的憐憫<br/>賜給我身。<br/>',NULL,9838,9838);
INSERT INTO stanza VALUES('C500','1','神操未知事件之鑰，<br/>我覺歡喜；<br/>若是祂託別人代勞，<br/>或是授權叫我照料，<br/>我就歎息。<br/>我就歎息。<br/>',NULL,9839,9839);
INSERT INTO stanza VALUES('C500','2','若是我的明天煩惱，<br/>今天臨到，<br/>而又沒有明天關照，<br/>我就不知怎樣是好！<br/>無法禱告。<br/>',NULL,9840,9840);
INSERT INTO stanza VALUES('C500','3','就因我的眼目不明，<br/>我反安全；<br/>我在暗中摸索失憑，<br/>祂手能覺，祂聲能聽，<br/>祂並不遠。<br/>',NULL,9841,9841);
INSERT INTO stanza VALUES('C500','4','祂的計畫我是不曉，<br/>但我能知：<br/>祂的笑臉如光照耀，<br/>祂的恩典不斷領導，<br/>在於此世。<br/>',NULL,9842,9842);
INSERT INTO stanza VALUES('C500','5','彀了，這已包羅萬有，<br/>我可安息！<br/>我所不能，祂都能救，<br/>有祂替我事事講究，<br/>我不著急。<br/>',NULL,9843,9843);
INSERT INTO stanza VALUES('C501','1','安穩在基督手臂，<br/>安穩在主懷裡；<br/>在此祂愛常覆翼，<br/>我魂滿得安息。<br/>這是天來的佳音，<br/>慰我驚恐心情，<br/>這是眾聖的謳吟，<br/>我要和聲頌稱。<br/>',NULL,9844,9844);
INSERT INTO stanza VALUES('C501','chorus','安穩在基督手臂，<br/>安穩在主懷裡；<br/>在此祂愛常覆翼，<br/>我魂滿得安息。<br/>',NULL,9845,9845);
INSERT INTO stanza VALUES('C501','2','安穩在基督手臂，<br/>安穩在主懷裡；<br/>在此祂恩時臨及，<br/>猶如甘露滴瀝。<br/>雖然試煉未全歷，<br/>眼淚尚餘幾滴，<br/>危難、驚懼或憂疑，<br/>在此莫能我襲。<br/>',NULL,9846,9846);
INSERT INTO stanza VALUES('C501','3','安穩在基督手臂，<br/>安穩在主懷裡；<br/>永久磐石之聖翼，<br/>將我全人遮蔽。<br/>在此我耐候依依，<br/>直到夜影飛散，<br/>直到那可愛晨曦，<br/>破曉在我眼前。<br/>',NULL,9847,9847);
INSERT INTO stanza VALUES('C502','1','來罷，憂傷的人，<br/>隨帶你煩惱，<br/>向著施恩寶座虔誠屈膝；<br/>來陳你心創痕，<br/>來訴你困擾，<br/>地無一個憂傷天不能醫。<br/>',NULL,9848,9848);
INSERT INTO stanza VALUES('C502','2','孤單中的喜樂，<br/>迷途的光照，<br/>痛悔者的希望－祂永不變；<br/>保惠師正在此<br/>柔聲的說道：<br/>地無一個憂傷天不能遣。<br/>',NULL,9849,9849);
INSERT INTO stanza VALUES('C502','3','這是生命的餅，<br/>滋養又甘甜，<br/>這是生命的水，<br/>流自寶座；<br/>來赴主的愛筵，<br/>心中常思念：<br/>地無一個憂傷天不能脫。<br/>',NULL,9850,9850);
INSERT INTO stanza VALUES('C503','1','聽哪，天上有聲喊說：<br/>『已成了；』<br/>信心立即回聲答說：<br/>『已成了。』<br/>',NULL,9851,9851);
INSERT INTO stanza VALUES('C503','chorus','請聽寶座的話語，<br/>你可來領神應許；<br/>神口曾說：<br/>『已成了，』<br/>信心也說：<br/>『已成了；』<br/>祈禱已過讚美始，<br/>阿利路亞，<br/>『已成了。』<br/>',NULL,9852,9852);
INSERT INTO stanza VALUES('C503','2','接受主的完全救恩，<br/>『已成了；』<br/>應當絕對奉獻全身，<br/>『已成了。』<br/>',NULL,9853,9853);
INSERT INTO stanza VALUES('C503','3','領取神的醫治恩約，<br/>『已成了；』<br/>只要相信，不要感覺，<br/>『已成了。』<br/>',NULL,9854,9854);
INSERT INTO stanza VALUES('C503','4','對神應許應當說道：<br/>『已成了；』<br/>對神話語應當認道：<br/>『已成了。』<br/>',NULL,9855,9855);
INSERT INTO stanza VALUES('C503','5','按祂所說來相信祂，<br/>『已成了；』<br/>這個就是接受祕法，<br/>『已成了。』<br/>',NULL,9856,9856);
INSERT INTO stanza VALUES('C504','1','你這奮鬥的信徒，<br/>你不當再奮鬥，<br/>主有更好的道路，<br/>何必這樣苦籌。<br/>',NULL,9857,9857);
INSERT INTO stanza VALUES('C504','chorus','我主的話可算得數，<br/>哦，主的話算得數；<br/>我不必這樣疑惑，<br/>不必苦求不輟，<br/>我當安息，不當奔波，<br/>因主的話算得數。<br/>',NULL,9858,9858);
INSERT INTO stanza VALUES('C504','2','你當服降主旨意，<br/>被殺仍要相信；<br/>停止所有的問題，<br/>今天就此決定。<br/>',NULL,9859,9859);
INSERT INTO stanza VALUES('C504','3','為何這樣的起倒！<br/>應當靠祂應許，<br/>拋出信心當鐵錨，<br/>今天就此定局。<br/>',NULL,9860,9860);
INSERT INTO stanza VALUES('C504','4','主，我今不再掙扎，<br/>一切向你交託，<br/>永遠相信你的話，<br/>今天就此著落。<br/>',NULL,9861,9861);
INSERT INTO stanza VALUES('C505','1','主阿，即或盡是黑暗，<br/>盡是坎坷憂悒，<br/>但我仍要鎮定安然，<br/>尋求你的心意。<br/>',NULL,9862,9862);
INSERT INTO stanza VALUES('C505','2','你有憐憫，你有恩慈，<br/>你有寶貴應許；<br/>你不會錯，你不會遲，<br/>你不翻雲覆雨。<br/>',NULL,9863,9863);
INSERT INTO stanza VALUES('C505','3','大能的主，說有就有，<br/>命立沒有不立；<br/>有主就可無罣無憂，<br/>就可不焦不急。<br/>',NULL,9864,9864);
INSERT INTO stanza VALUES('C505','4','主阿，因你我心定了，<br/>因你我魂安歇；<br/>我讚美說：有主彀了！<br/>主是包括一切！<br/>',NULL,9865,9865);
INSERT INTO stanza VALUES('C505','5','主，我還要求你的靈，<br/>使我信心充足，<br/>領我更深認識你名，<br/>進入你的豐富。<br/>',NULL,9866,9866);
INSERT INTO stanza VALUES('C506','1','祂不誤事，因祂是神！<br/>祂不誤事，祂樂施恩！<br/>祂不誤事，祂已許過！<br/>我們有神，還怕誰何？<br/>',NULL,9867,9867);
INSERT INTO stanza VALUES('C506','2','有何高山你不能鋤？<br/>有何深水你不能渡？<br/>我們的神專門處置<br/>人所以為不能的事。<br/>',NULL,9868,9868);
INSERT INTO stanza VALUES('C506','3','是祂使鐵浮水而起，<br/>是祂使海分成乾地，<br/>是祂使日半空停止，<br/>我們的神並無難事！<br/>',NULL,9869,9869);
INSERT INTO stanza VALUES('C506','4','祂使軟沙作海界限，<br/>波浪雖狂，不能再前；<br/>祂是你神，還有甚麼<br/>祂是不能為你工作？<br/>',NULL,9870,9870);
INSERT INTO stanza VALUES('C506','5','祂心愛你，知你難處，<br/>所以應許祂要照顧；<br/>我們的神充滿憐憫，<br/>對待祂的無告子民。<br/>',NULL,9871,9871);
INSERT INTO stanza VALUES('C506','6','我們的神不能不義，<br/>不能將祂應許忘記；<br/>祂的應許在基督裡，<br/>都是阿們，都是是的。<br/>',NULL,9872,9872);
INSERT INTO stanza VALUES('C506','7','我們的神不能失信，<br/>祂的恩約永遠堅定，<br/>祂要照祂應許，答應<br/>我們因信所發呼聲。<br/>',NULL,9873,9873);
INSERT INTO stanza VALUES('C506','8','我們因信歡樂唱說：<br/>祂不誤我，祂已許過！<br/>祂不誤我，祂樂施恩！<br/>祂不誤我，因祂是神！<br/>',NULL,9874,9874);
INSERT INTO stanza VALUES('C507','1','主，你作我的領港，<br/>來過此人生風浪；<br/>前面是未識水道，<br/>浮沙外加上暗礁；<br/>你當賜南針圖狀，<br/>主，你作我的領港。<br/>',NULL,9875,9875);
INSERT INTO stanza VALUES('C507','2','慈母能平定嬰孩，<br/>你也能鎮靜狂海；<br/>當你說應當安靜，<br/>風和浪立聽命令；<br/>你真是奇妙的王，<br/>主，你作我的領港。<br/>',NULL,9876,9876);
INSERT INTO stanza VALUES('C507','3','到至終我近彼岸，<br/>可怕的激浪搖撼；<br/>在我與平安之間，<br/>當我正倚你身邊，<br/>讓我聽你對我講：<br/>不要怕，是我領港。<br/>',NULL,9877,9877);
INSERT INTO stanza VALUES('C508','1','一路我蒙救主引領，<br/>陳腐事物何必求？<br/>難道我還疑祂愛情，<br/>畢生既由祂拯救？<br/>神聖安慰、屬天生活，<br/>憑信我可從祂得；<br/>我深知道凡事臨我，<br/>祂有美意不必測。<br/>我深知道凡事臨我，<br/>祂有美意不必測。<br/>',NULL,9878,9878);
INSERT INTO stanza VALUES('C508','2','一路我蒙救主引領，<br/>鼓勵我走每步路；<br/>供我靈糧，長我生命，<br/>幫助我歷每次苦。<br/>旅程雖然力不能支，<br/>心、靈雖然渴難當，<br/>看哪，面前就是磐石，<br/>喜樂活泉可來嘗。<br/>',NULL,9879,9879);
INSERT INTO stanza VALUES('C508','3','一路我蒙救主引領，<br/>哦，主大愛何豐滿，<br/>不久我到父的懷中，<br/>得享應許的平安。<br/>我靈披上榮耀身軀，<br/>飛入無夜光明處，<br/>我要永遠唱此佳句，<br/>蒙祂引領我一路。<br/>',NULL,9880,9880);
INSERT INTO stanza VALUES('C509','1','你這奔向榮耀客旅，<br/>疲倦困乏心迷離；<br/>神已賜你寶貴應許：<br/>『我必用眼引導你。』<br/>',NULL,9881,9881);
INSERT INTO stanza VALUES('C509','chorus','『我必引導，我必引導，<br/>我必用眼引導你；<br/>你這奔向榮耀客旅，<br/>我必用眼引導你。』<br/>',NULL,9882,9882);
INSERT INTO stanza VALUES('C509','2','雖然心中常是紛亂，<br/>情緒擾人欲昏迷，<br/>但這應許排解萬難：<br/>『我必用眼引導你。』<br/>',NULL,9883,9883);
INSERT INTO stanza VALUES('C509','3','雖然試探幾乎得勝，<br/>可靠親友也遠離，<br/>但這應許發出微聲：<br/>『我必用眼引導你。』<br/>',NULL,9884,9884);
INSERT INTO stanza VALUES('C509','4','你的隱祕盼望消逝，<br/>埋在年日墳墓裡，<br/>讓這應許將你支持：<br/>『我必用眼引導你。』<br/>',NULL,9885,9885);
INSERT INTO stanza VALUES('C509','5','生命陰影逐漸加深，<br/>要穿榮耀的身體，<br/>神這應許顯為更真：<br/>『我必用眼引導你。』<br/>',NULL,9886,9886);
INSERT INTO stanza VALUES('C509','6','但願我靈以神為樂，<br/>我心以祂為至寶，<br/>與祂交通一無間隔，<br/>接受祂眼的引導。<br/>',NULL,9887,9887);
INSERT INTO stanza VALUES('C510','1','當我信心失效能，<br/>主必扶持我；<br/>當試探者將得勝，<br/>祂必扶持我。<br/>',NULL,9888,9888);
INSERT INTO stanza VALUES('C510','chorus','祂必扶持我，<br/>祂必扶持我，<br/>因為救主愛我甚，<br/>祂必扶持我。<br/>',NULL,9889,9889);
INSERT INTO stanza VALUES('C510','2','我向不能站得穩，<br/>須祂扶持我；<br/>因為愛心冷且鈍，<br/>須祂扶持我。<br/>',NULL,9890,9890);
INSERT INTO stanza VALUES('C510','3','祂看我是祂珍寶，<br/>祂必扶持我；<br/>祂所救的祂喜好，<br/>祂必扶持我。<br/>',NULL,9891,9891);
INSERT INTO stanza VALUES('C510','4','祂不讓我終失喪，<br/>祂必扶持我；<br/>如此代價既肯償，<br/>祂必扶持我。<br/>',NULL,9892,9892);
INSERT INTO stanza VALUES('C511','1','主已知道你的挫折！<br/>主已知道你的軟弱！<br/>主全知道你的無告！<br/>主的話說：我已知道。<br/>',NULL,9893,9893);
INSERT INTO stanza VALUES('C511','2','祂知你能受甚試煉，<br/>祂知你是需何恩典，<br/>祂早知你所有遭遇，<br/>祂是你主，何必疑懼。<br/>',NULL,9894,9894);
INSERT INTO stanza VALUES('C511','3','雖然多人譏諷、反對，<br/>親友離棄，旅伴誤會；<br/>但祂深知你的一切；<br/>有主知道你可安歇。<br/>',NULL,9895,9895);
INSERT INTO stanza VALUES('C511','4','重擔只要交託給主，<br/>歎息只要向祂傾吐；<br/>祂心愛你，知你憂苦，<br/>祂必施恩，祂必看顧。<br/>',NULL,9896,9896);
INSERT INTO stanza VALUES('C511','5','主既知道，足慰我心，<br/>主既知道，我便歡欣！<br/>主既知道，祂必搭救！<br/>主既知道，我還何求？<br/>',NULL,9897,9897);
INSERT INTO stanza VALUES('C512','1','我是一個異鄉旅客，<br/>跋涉遙遠的道路；<br/>雖然有時遇見阻隔，<br/>引我親天父。<br/>途中雖有烏雲籠罩，<br/>也有意外的打擾，<br/>思慮、煩惱把我壓倒，<br/>但我父知道。<br/>',NULL,9898,9898);
INSERT INTO stanza VALUES('C512','2','父是知道，何等保證！<br/>沿途試煉有何害？<br/>縱然牠們隨我一生，<br/>不容易忍耐。<br/>主已在望，莫大鼓勵，<br/>使我安息不動搖！<br/>祂的同在何其甜蜜，<br/>我天父知道。<br/>',NULL,9899,9899);
INSERT INTO stanza VALUES('C512','3','我父每日都知道我，<br/>看守我在愛裡面；<br/>艱難來襲，祂來助我，<br/>叫我往上看。<br/>不久旅程到達止境，<br/>今生就要告終了，<br/>我將如何進入光明，<br/>這事父知道。<br/>',NULL,9900,9900);
INSERT INTO stanza VALUES('C512','4','那時我在主的面前，<br/>親眼看見祂慈顏，<br/>滿心歡喜，俯伏朝見，<br/>感謝祂恩典。<br/>在祂甜美同在之前，<br/>再無今生的攪擾，<br/>祂的應許全得應驗，<br/>這事父知道。<br/>',NULL,9901,9901);
INSERT INTO stanza VALUES('C513','1','或這樣，或那樣，<br/>主總必豫備：<br/>雖不照我方法，<br/>也不照你方法，<br/>主要照祂方法，<br/>為我們豫備。<br/>',NULL,9902,9902);
INSERT INTO stanza VALUES('C513','chorus','我安心靠主，<br/>因主必豫備；<br/>我完全望主，<br/>因主要豫備。<br/>',NULL,9903,9903);
INSERT INTO stanza VALUES('C513','2','或這時，或那時，<br/>主總必豫備：<br/>雖不照我時候，<br/>也不照你時候，<br/>在主所定時候，<br/>主總必豫備。<br/>',NULL,9904,9904);
INSERT INTO stanza VALUES('C513','3','所以不要懷疑，<br/>因主必豫備：<br/>我主所有應許，<br/>那裡曾有一句<br/>變作烏有空虛？<br/>主總必豫備。<br/>',NULL,9905,9905);
INSERT INTO stanza VALUES('C513','4','因此，應當進前，<br/>進前不疲憊；<br/>海水必定分開，<br/>嗎哪要從天來，<br/>仇敵都要失敗，<br/>主總必豫備。<br/>',NULL,9906,9906);
INSERT INTO stanza VALUES('C514','1','我要歌唱那奇妙應許，<br/>就是耶穌親口所說：<br/>『我的恩典是彀你使用，<br/>我的能力顯於軟弱。』<br/>惟恐我這惡心會忘記，<br/>忘記這應許的光榮，<br/>所以祂一直一直的說：<br/>『我的恩典彀你使用。』<br/>',NULL,9907,9907);
INSERT INTO stanza VALUES('C514','chorus','是的，救主一直對我說，<br/>一直，一直，一直的說：<br/>『我的恩典是彀你使用，<br/>我的能力顯於軟弱。』<br/>',NULL,9908,9908);
INSERT INTO stanza VALUES('C514','2','祂的恩典彀使我得救，<br/>脫離罪惡，得著新心；<br/>彀使我靈、魂、體<br/>都聖潔，<br/>並且滿有主的聖靈。<br/>祂的恩典彀助我經過<br/>各種試煉，無論多兇；<br/>祂的應許抵擋了牠們，<br/>『我的恩典彀你使用。』<br/>',NULL,9909,9909);
INSERT INTO stanza VALUES('C514','3','祂的恩典彀為我疾病：<br/>一面扶持，一面施醫。<br/>祂的恩典彀助我經過<br/>一切苦楚、一切攻擊。<br/>祂的恩典是彀我工作，<br/>使我能彀幫助弟兄，<br/>並使他們與我同知道，<br/>祂的恩典足彀使用。<br/>',NULL,9910,9910);
INSERT INTO stanza VALUES('C514','4','祂的恩典是彀我生活，<br/>彀來引領，彀來扶助；<br/>將來被提或經過死谷，<br/>祂的恩典都彀眷顧。<br/>到那時當我看見救主－祂的美麗、祂的光榮，<br/>我就要俯伏並承認說：<br/>你的恩典彀我使用。<br/>',NULL,9911,9911);
INSERT INTO stanza VALUES('C514','5','我們的恩典並不彀用，<br/>彀用惟有祂的恩典。<br/>我們的常是曇花一現，<br/>但是祂的永不改變。<br/>因此我就不斷的背誦<br/>祂曾對我親口所說：<br/>『我的恩典是彀你使用，<br/>我的能力顯在軟弱。』<br/>',NULL,9912,9912);
INSERT INTO stanza VALUES('C515','1','不在此時，許待主回，<br/>不在此地，許到那裡；<br/>我們纔能完全領會，<br/>歎息眼淚所有意義。<br/>',NULL,9913,9913);
INSERT INTO stanza VALUES('C515','chorus','你當一生信靠救主，<br/>路雖陰暗，仍當讚美，<br/>不必懼怕，主在攙扶，<br/>有日、有日都要領會。<br/>',NULL,9914,9914);
INSERT INTO stanza VALUES('C515','2','中斷線索，都將接上，<br/>一生經過，必有路軌，<br/>天能解釋各樣祕藏，<br/>那日、那日都必領會。<br/>',NULL,9915,9915);
INSERT INTO stanza VALUES('C515','3','何故厚雲遮蔽太陽？<br/>何故寂寞代替安慰？<br/>何故歎息多過歌唱？<br/>有日我們就要領會。<br/>',NULL,9916,9916);
INSERT INTO stanza VALUES('C515','4','何以祈求未見答應？<br/>何以將成終又不遂？<br/>何以盼望終成泡影？<br/>那日那裡，我必領會。<br/>',NULL,9917,9917);
INSERT INTO stanza VALUES('C515','5','神知我路，手拿牠鑰，<br/>祂的帶領充滿智慧；<br/>有日我眼看見一切，<br/>祂在那裡，我必領會。<br/>',NULL,9918,9918);
INSERT INTO stanza VALUES('C516','1','信靠耶穌何其甘甜，<br/>抓祂話語作把握，<br/>安息在祂應許上面，<br/>只知主曾如此說。<br/>',NULL,9919,9919);
INSERT INTO stanza VALUES('C516','chorus','耶穌、耶穌，何等可靠，<br/>我曾試祂多少次；<br/>耶穌、耶穌，我的至寶，<br/>祂是活神不誤事。<br/>',NULL,9920,9920);
INSERT INTO stanza VALUES('C516','2','信靠耶穌，何其甘甜，<br/>信祂寶血能洗淨；<br/>信心簡單，血有效驗，<br/>疾病醫治，罪洗清。<br/>',NULL,9921,9921);
INSERT INTO stanza VALUES('C516','3','信靠耶穌，真是甘甜，<br/>救我遠離罪與己；<br/>從祂接受無限恩典：<br/>生命、喜樂和安息。<br/>',NULL,9922,9922);
INSERT INTO stanza VALUES('C516','4','何等喜樂，我能信你，<br/>至寶耶穌，我救主！<br/>信你與我是在一起，<br/>一直一起到永古。<br/>',NULL,9923,9923);
INSERT INTO stanza VALUES('C517','1','前途如何我不知，<br/>神將我眼遮蔽；<br/>在我向前每步路上，<br/>都有新的境地；<br/>祂所賜的每一喜樂，<br/>也都令人驚奇。<br/>',NULL,9924,9924);
INSERT INTO stanza VALUES('C517','chorus','我願跟隨祂帶領，<br/>對祂完全信靠；<br/>隨時隨在安然唱道：<br/>『祂知道，祂知道；』<br/>隨時隨在安然唱道：<br/>『祂知道，祂知道。』<br/>',NULL,9925,9925);
INSERT INTO stanza VALUES('C517','2','眼前一步我看見，<br/>已彀應付需要；<br/>屬地幻想若肯去掉，<br/>天光就必照耀；<br/>靜中也必甜然聽見：<br/>『你要將我信靠。』<br/>',NULL,9926,9926);
INSERT INTO stanza VALUES('C517','3','哦，那有福的『無智，』<br/>『不知』真是福氣！<br/>祂用右手將我握住，<br/>不肯讓我稍離，<br/>並使我的受驚心魂<br/>在祂愛中安息。<br/>',NULL,9927,9927);
INSERT INTO stanza VALUES('C517','4','如此不知而向前；<br/>能知，我也不願；<br/>寧願暗中與神同行，<br/>不願光中孤單；<br/>寧願憑信與神同行，<br/>不願憑著眼見。<br/>',NULL,9928,9928);
INSERT INTO stanza VALUES('C518','1','人若倚靠耶和華，<br/>真有福，<br/>必得著應時的幫助；<br/>你若處處緊緊的跟隨主，<br/>必承受應許的好處。<br/>',NULL,9929,9929);
INSERT INTO stanza VALUES('C518','chorus','務要靠主，專心靠主，<br/>凡你所行，都要認定主，<br/>祂必指引你的路。<br/>務要靠主，專心靠主，<br/>凡你所行，都要認定主，<br/>祂必指引你的路。<br/>',NULL,9930,9930);
INSERT INTO stanza VALUES('C518','2','人若倚靠耶和華，<br/>真有福，<br/>必定走屬天的道路；<br/>你若時時不斷的仰望主，<br/>必能有穩健的腳步。<br/>',NULL,9931,9931);
INSERT INTO stanza VALUES('C518','3','真是有福，<br/>有天父來扶助，<br/>並且有救主來照顧；<br/>你若得著主與父來同住，<br/>就永遠不再感孤苦。<br/>',NULL,9932,9932);
INSERT INTO stanza VALUES('C518','4','真是有福，<br/>得不斷走正路，<br/>且天天向前不受阻；<br/>你若得著主同在的豐富，<br/>就必得應時的幫助。<br/>',NULL,9933,9933);
INSERT INTO stanza VALUES('C519','1','當我在我路上<br/>遇見試探時，<br/>撒但就在耳語<br/>叫我可放弛；<br/>但是負擔雖重<br/>我已不發愁，<br/>只要一點相信<br/>就趕難處走。<br/>',NULL,9934,9934);
INSERT INTO stanza VALUES('C519','chorus','主，我相信！<br/>主，我相信！<br/>求提高我信你的心，<br/>使我能以移山；<br/>主，我相信！<br/>主，我相信！<br/>我的疑慮全投在你身畔。<br/>',NULL,9935,9935);
INSERT INTO stanza VALUES('C519','2','當我航行海上<br/>順風的時候，<br/>何等容易相信<br/>耶和華的手，<br/>但我發現正當<br/>波浪漫船來，<br/>需要好多相信<br/>纔能不沉埋。<br/>',NULL,9936,9936);
INSERT INTO stanza VALUES('C519','3','我常聽人說：<br/>『我要堅持到底，<br/>我要忠心至死，<br/>我絕不逃避，』<br/>但當試探<br/>來得特別兇猛時，<br/>他就停止相信，<br/>甚麼都喪失。<br/>',NULL,9937,9937);
INSERT INTO stanza VALUES('C519','4','還有別人滿有<br/>勇敢與熱心，<br/>他們參加事奉<br/>如同鋼鐵人，<br/>但是正當<br/>與罪摔跤最熱時，<br/>他們不是相信，<br/>乃是怕損失。<br/>',NULL,9938,9938);
INSERT INTO stanza VALUES('C519','5','但願我們記得，<br/>在屬靈生活，<br/>信心不是感覺，<br/>信靠非撫摸；<br/>正當一切<br/>好像最看不見時，<br/>我們仍要相信，<br/>因而仍堅持。<br/>',NULL,9939,9939);
INSERT INTO stanza VALUES('C520','1','新鮮如同清晨甘露，<br/>帶來暢爽的甘美，<br/>基督藉祂溫情恩膏，<br/>柔聲細語的安慰：<br/>站住，直到試煉過去，<br/>站住，直到風波平，<br/>站住，為著神的榮耀，<br/>站住，與主同得勝。<br/>',NULL,9940,9940);
INSERT INTO stanza VALUES('C520','chorus','盼望之主，<br/>你的聲音何甜！<br/>在你面前我心因此暢歡！<br/>',NULL,9941,9941);
INSERT INTO stanza VALUES('C520','2','如果在我苦煉之中，<br/>我靈、我心皆衰弱，<br/>信心和那盼望之星，<br/>也都退落不閃爍，<br/>願你信心和你能力，<br/>盡其全力抓住我，<br/>使你所有榮耀豐富，<br/>我可無間的嘗著。<br/>',NULL,9942,9942);
INSERT INTO stanza VALUES('C520','3','主，像清晨放明日光，<br/>驅盡所有的黑暗，<br/>並且用你醫治光線，<br/>使我黑暗變中天。<br/>安慰之主，求你就來，<br/>來到憂苦、疲倦心，<br/>你這有福、榮耀盼望，<br/>哦，來與我永親近。<br/>',NULL,9943,9943);
INSERT INTO stanza VALUES('C521','1','哦，<br/>讓我們在主裡面常喜樂，<br/>雖然四圍充滿了兇惡，<br/>雖然患難如同波濤<br/>在衝擊，<br/>但是歌唱總勝似歎息。<br/>',NULL,9944,9944);
INSERT INTO stanza VALUES('C521','chorus','應當時常喜樂，<br/>當時常喜樂，<br/>無論如何，<br/>歌唱總勝歎息，<br/>無論如何，<br/>生存總勝死寂，<br/>所以應當時常喜樂！<br/>',NULL,9945,9945);
INSERT INTO stanza VALUES('C521','2','哦，<br/>讓我們在主裡面常喜樂，<br/>雖然火箭暗中頻頻戳，<br/>因為撒但還是像從前那樣<br/>懼怕讚美遠過於悲傷。<br/>',NULL,9946,9946);
INSERT INTO stanza VALUES('C521','3','哦，<br/>讓我們在主裡面常喜樂，<br/>雖然精神在病中消磨；<br/>因主的喜樂<br/>就是你的力量，<br/>若靠主喜樂就必剛強。<br/>',NULL,9947,9947);
INSERT INTO stanza VALUES('C521','4','哦，<br/>讓我們在主裡面常喜樂，<br/>因這地上帳幕快要脫，<br/>我們要被提，<br/>得與主在一起，<br/>不再有何憂愁與歎息。<br/>',NULL,9948,9948);
INSERT INTO stanza VALUES('C522','1','長久陷入憂患、苦痛，<br/>我就退到你的手中；<br/>絲毫再無保留；<br/>你手擦乾我的眼淚，<br/>使我哭臉滿了光輝，<br/>再無苦淚可流。<br/>',NULL,9949,9949);
INSERT INTO stanza VALUES('C522','2','再會！你這虛空歡娛：<br/>無味消遣，兒戲樂趣，<br/>對你我失口味。<br/>真實快樂乃在十架，<br/>其他娛樂盡是虛假－主是如此定規。<br/>',NULL,9950,9950);
INSERT INTO stanza VALUES('C522','3','哦，十字架纔是福氣：<br/>牠的損失乃是利益；<br/>其苦也是甘甜！<br/>所有心思、心志、心情，<br/>在此全都得以煉淨，<br/>嘗到真樂之滿。<br/>',NULL,9951,9951);
INSERT INTO stanza VALUES('C522','4','苦中自愛難能得益，<br/>因牠總求自己安逸：<br/>除此，牠無福氣；<br/>真實之愛，目的高尚，<br/>捨己乃是牠所欣賞，<br/>受苦是牠所喜。<br/>',NULL,9952,9952);
INSERT INTO stanza VALUES('C522','5','我的選擇和你一樣，<br/>哦，將聖火前來挑旺，<br/>使之永焚無燼！<br/>背起十架將你跟隨，<br/>因著你愛時常讚美，<br/>乃是我的福分。<br/>',NULL,9953,9953);
INSERT INTO stanza VALUES('C523','1','祂賜的十架雖然沉重，<br/>不會重逾祂恩典；<br/>我怕的風波雖然洶湧，<br/>不至掩蔽祂榮臉。<br/>',NULL,9954,9954);
INSERT INTO stanza VALUES('C523','chorus','十架不會重逾祂恩典，<br/>風波不會掩蔽祂榮臉；<br/>我心歡樂，<br/>因我知有主耶穌同在此，<br/>我就勝過敵權勢。<br/>',NULL,9955,9955);
INSERT INTO stanza VALUES('C523','2','我路上荊棘，並不會比<br/>祂頭上的荊冕利；<br/>我喝的苦杯，還遠不及<br/>祂的在客西馬尼。<br/>',NULL,9956,9956);
INSERT INTO stanza VALUES('C523','3','祂光照耀得更加昭明，<br/>在危難的道路中；<br/>我擔子變得更為省輕，<br/>當我為人來任重。<br/>',NULL,9957,9957);
INSERT INTO stanza VALUES('C523','4','我今生活在祂的面前，<br/>歡然順服祂旨意；<br/>我知我所受各種試煉，<br/>都是化裝的福庇。<br/>',NULL,9958,9958);
INSERT INTO stanza VALUES('C524','1','我是一隻籠中小鳥，<br/>遠離天空、曠闊野地；<br/>是祂將我安置於此，<br/>我願向祂歌頌不已；<br/>如此被囚，我甚歡欣，<br/>因這，我神，使你稱心。<br/>',NULL,9959,9959);
INSERT INTO stanza VALUES('C524','2','禁中我無他事可作，<br/>終日就是靜中歌唱；<br/>我所使之稱心的神，<br/>也在傾聽我的頌揚；<br/>祂捆綁了我的翅膀，<br/>卻愛俯首聽我歌唱。<br/>',NULL,9960,9960);
INSERT INTO stanza VALUES('C524','3','哦神，你是有耳能聽，<br/>你也有心施愛賜福；<br/>我的音調雖然粗陋，<br/>你卻毫不鄙棄厭惡；<br/>因你知這音調之弦，<br/>乃是甜美之愛所彈。<br/>',NULL,9961,9961);
INSERT INTO stanza VALUES('C524','4','這籠將我四面禁錮，<br/>我難外飛任意遨遊；<br/>我的翅膀雖被捆住，<br/>我心我靈仍是自由；<br/>監牢牆垣，不能阻擋<br/>心靈所有釋放、翱翔。<br/>',NULL,9962,9962);
INSERT INTO stanza VALUES('C524','5','我心超越監牢之閂，<br/>我靈騰飛何其自在！<br/>向著心愛之主騰飛，<br/>祂的旨意我所敬拜；<br/>在你堅定旨意之中，<br/>我靈得到自由、歡騰。<br/>',NULL,9963,9963);
INSERT INTO stanza VALUES('C525','1','四圍牆垣堅而固，<br/>終日將我禁閉；<br/>但那關閉我的人，<br/>不能使神遠離：<br/>監牢牆垣全變可愛，<br/>因為我神在此同在。<br/>',NULL,9964,9964);
INSERT INTO stanza VALUES('C525','2','關閉我者都知道，<br/>甚難使我孤單；<br/>但是他們卻不知<br/>是祂來獄慰安；<br/>祂使牢中黑暗變明，<br/>並用喜樂充滿我靈。<br/>',NULL,9965,9965);
INSERT INTO stanza VALUES('C525','3','哦神，你愛激動我，<br/>悲歎轉為頌讚；<br/>我從深處敬拜你，<br/>不管時間地點；<br/>或順或逆，都無所要，<br/>只要和你旨意相調。<br/>',NULL,9966,9966);
INSERT INTO stanza VALUES('C525','4','這個成為我寶貝，<br/>這個使我得益；<br/>為我將禍變祝福，<br/>使我苦中歡喜。<br/>不論何事都可臨到，<br/>只要有神我就彀了。<br/>',NULL,9967,9967);
INSERT INTO stanza VALUES('C526','1','神未曾應許：天色常藍，<br/>人生的路途花香常漫；<br/>神未曾應許：常晴無雨，<br/>常樂無痛苦，常安無虞。<br/>',NULL,9968,9968);
INSERT INTO stanza VALUES('C526','chorus','神卻曾應許：生活有力，<br/>行路有光亮，作工得息，<br/>試煉得恩勗，危難有賴，<br/>無限的體諒，不死的愛。<br/>',NULL,9969,9969);
INSERT INTO stanza VALUES('C526','2','神未曾應許：我們不遇<br/>苦難和試探、<br/>懊惱、憂慮；<br/>神未曾應許：我們不負<br/>許多的重擔、許多事務。<br/>',NULL,9970,9970);
INSERT INTO stanza VALUES('C526','3','神未曾應許：前途盡是<br/>平坦的大路，任意驅馳；<br/>沒有深水拒，汪洋一片，<br/>沒有大山阻，高薄雲天。<br/>',NULL,9971,9971);
INSERT INTO stanza VALUES('C527','1','迫得太緊，<br/>迫得無處可逃生；<br/>迫到極點，<br/>好像力不能勝；<br/>迫到四顧茫然，<br/>惟有獨流淚；<br/>迫得無可奈何，<br/>望絕心灰。<br/>',NULL,9972,9972);
INSERT INTO stanza VALUES('C527','chorus','神是我盼望，<br/>是我喜樂；<br/>是祂叫無變有，<br/>叫死人復活！<br/>',NULL,9973,9973);
INSERT INTO stanza VALUES('C527','2','壓迫在身，<br/>無處可算是平安；<br/>壓迫在心，<br/>四圍都是黑暗；<br/>迫於仇敵，<br/>有時也迫於朋友；<br/>迫上加迫，<br/>性命幾歸烏有。<br/>',NULL,9974,9974);
INSERT INTO stanza VALUES('C527','3','迫到除神之外，<br/>別無人幫助；<br/>迫到喜歡貧窮如同豐富；<br/>迫到接受鞭杖<br/>如同蒙雨露；<br/>迫到除主之外，<br/>別無愛慕。<br/>',NULL,9975,9975);
INSERT INTO stanza VALUES('C527','4','迫到脫塵，<br/>現今就登天逍遊；<br/>迫到無一纏累，<br/>完全自由；<br/>迫到信神來作<br/>不可能的事；<br/>迫到必須靠主而生而死。<br/>',NULL,9976,9976);
INSERT INTO stanza VALUES('C527','5','『迫得太緊！』<br/>我們如此的哭泣；<br/>迫到如此，<br/>壓迫已竭其力；<br/>壓迫餘生已非<br/>壓迫所能及；<br/>迫過之後，<br/>已得永遠安息。<br/>',NULL,9977,9977);
INSERT INTO stanza VALUES('C527','6','『迫得太緊！』<br/>實在乃是大利益；<br/>壓迫不過顯明神的手臂；<br/>迫過之後，<br/>旁觀者都要看見：<br/>迫上加迫，<br/>不會搖動一點。<br/>',NULL,9978,9978);
INSERT INTO stanza VALUES('C527','7','『壓迫雖緊，』<br/>我們仍舊的進前；<br/>壓迫續來，<br/>我們的望在天；<br/>壓迫續來，<br/>已經無可再壓迫；<br/>壓迫續來，<br/>心仍因神自得。<br/>',NULL,9979,9979);
INSERT INTO stanza VALUES('C528','1','暗過必明亮，<br/>苦過必甜；<br/>弱過必剛強，<br/>難過必安；<br/>損過必有益，<br/>風過必靜；<br/>勞過必安息，<br/>雨過必晴。<br/>',NULL,9980,9980);
INSERT INTO stanza VALUES('C528','2','壓過必高升，<br/>憂過必樂；<br/>死過必復生，<br/>失過必得；<br/>累過必輕鬆，<br/>困過必蘇；<br/>迫過必從容，<br/>貧過必富。<br/>',NULL,9981,9981);
INSERT INTO stanza VALUES('C528','3','蕩過必安居，<br/>孤過有伴，<br/>與主再無距，<br/>直到相見，<br/>十架變冠冕，<br/>歎息變讚，<br/>信望變眼見，<br/>再無疑難。<br/>',NULL,9982,9982);
INSERT INTO stanza VALUES('C529','1','當日神在伊甸園中，<br/>將人置於二樹之前：<br/>藉生命樹指明自己，<br/>以知識樹表明撒但。<br/>',NULL,9983,9983);
INSERT INTO stanza VALUES('C529','2','生命樹乃神的中心，<br/>照神永遠計畫所定，<br/>神是要在基督裡面，<br/>給人接受，作人生命。<br/>',NULL,9984,9984);
INSERT INTO stanza VALUES('C529','3','知識樹是神的警告，<br/>題示神外另有源頭：<br/>惡者撒但，死亡淵藪，<br/>人若接觸，死亡必受。<br/>',NULL,9985,9985);
INSERT INTO stanza VALUES('C529','4','生命之樹人肯接受，<br/>人必得著神作生命，<br/>且必變成珍貴寶石，<br/>神的心願藉此完成。<br/>',NULL,9986,9986);
INSERT INTO stanza VALUES('C529','5','知識一樹人若接觸，<br/>撒但必得進人裡面，<br/>成為罪惡，帶進死亡，<br/>使神計畫難得成全。<br/>',NULL,9987,9987);
INSERT INTO stanza VALUES('C529','6','這是表明只有神是<br/>我們生命惟一源頭；<br/>摸著神外一切事物，<br/>就是摸著死亡之由。<br/>',NULL,9988,9988);
INSERT INTO stanza VALUES('C529','7','知識不過帶來死亡，<br/>儘管外觀是善非惡；<br/>在神之外任何事物，<br/>都是撒但施計之所。<br/>',NULL,9989,9989);
INSERT INTO stanza VALUES('C529','8','不只惡與基督相對，<br/>就是善也與祂相抵；<br/>凡屬知識不拘善惡，<br/>都與生命相反不一。<br/>',NULL,9990,9990);
INSERT INTO stanza VALUES('C529','9','主，教我們惟獨摸你，<br/>好叫我們被你充滿；<br/>你外事物概不接觸，<br/>對惡如此，對善亦然。<br/>',NULL,9991,9991);
INSERT INTO stanza VALUES('C530','1','神的律法在人身外，<br/>聖潔、良善，要人遵行；<br/>為要向人確切證明，<br/>神所要求人難完成。<br/>',NULL,9992,9992);
INSERT INTO stanza VALUES('C530','2','在人心思存有一律，<br/>使人立志願意為善；<br/>但肢體中另有一律，<br/>與其爭戰，使其難堪。<br/>',NULL,9993,9993);
INSERT INTO stanza VALUES('C530','3','心思之律乃是良善，<br/>原是人在受造之時，<br/>得自人的受造生命，<br/>使人善行得以維持。<br/>',NULL,9994,9994);
INSERT INTO stanza VALUES('C530','4','肢體之律乃是邪惡，<br/>當人墮落，聯於撒但，<br/>來自撒但邪惡生命，<br/>進入人體，藉死掌權。<br/>',NULL,9995,9995);
INSERT INTO stanza VALUES('C530','5','這個肢體犯罪之律<br/>強過心思為善之律，<br/>藉著撒但邪惡能力，<br/>征服善律將人擄去。<br/>',NULL,9996,9996);
INSERT INTO stanza VALUES('C530','6','在我靈中更有一律，<br/>乃是生命之靈的律，<br/>來自神的大能生命，<br/>當我重生即為我具。<br/>',NULL,9997,9997);
INSERT INTO stanza VALUES('C530','7','這個靈中生命之律，<br/>乃是最強，強過所有；<br/>使我脫離犯罪之律，<br/>成全神律一切要求。<br/>',NULL,9998,9998);
INSERT INTO stanza VALUES('C530','8','因此，我們要將心思<br/>時常置於靈的上面，<br/>永不再放肉體之上，<br/>我們便脫罪的霸權。<br/>',NULL,9999,9999);
INSERT INTO stanza VALUES('C530','9','心思放在肉體之上，<br/>就是可怕死亡、黑暗；<br/>心思置於靈的上面，<br/>乃是有福生命、平安。<br/>',NULL,10000,10000);
INSERT INTO stanza VALUES('C530','10','這是得著釋放之路，<br/>這是最妙成聖途徑！<br/>主，使我們活在靈中，<br/>憑著此靈與你同行。<br/>',NULL,10001,10001);
INSERT INTO stanza VALUES('C531','1','字句律法是神見證，<br/>說明神是如何的神，<br/>如何聖潔，如何公義，<br/>如何光明，如何慈仁。<br/>',NULL,10002,10002);
INSERT INTO stanza VALUES('C531','2','神的律法是要我們<br/>照神所是行事為人，<br/>使神可來稱義、悅納，<br/>並按公義賜以福分。<br/>',NULL,10003,10003);
INSERT INTO stanza VALUES('C531','3','律法不能賜人生命，<br/>任何能力不能供應，<br/>只向我們有所要求，<br/>顯明我們軟弱無能。<br/>',NULL,10004,10004);
INSERT INTO stanza VALUES('C531','4','律法並非神的心願，<br/>乃為顯明罪過而添，<br/>給人干犯，向人證明<br/>人是滿了罪惡過犯。<br/>',NULL,10005,10005);
INSERT INTO stanza VALUES('C531','5','律法塞住眾人之口，<br/>並將眾人圈在罪中；<br/>為將我們帶到基督，<br/>在祂裡面蒙神恩寵。<br/>',NULL,10006,10006);
INSERT INTO stanza VALUES('C531','6','律法乃是基督小影，<br/>基督是神實際見證，<br/>豐滿表明神是如何<br/>聖潔、公義、<br/>仁愛、光明。<br/>',NULL,10007,10007);
INSERT INTO stanza VALUES('C531','7','乃是神的這位基督，<br/>供應我們以神生命，<br/>好使律法所有要求，<br/>都在我們得以完成。<br/>',NULL,10008,10008);
INSERT INTO stanza VALUES('C531','8','基督，神這活的見證，<br/>使我有分大能生命；<br/>藉祂我向律法已死，<br/>在祂靈中得以成聖。<br/>',NULL,10009,10009);
INSERT INTO stanza VALUES('C532','1','舊約時代神的律法，<br/>乃用字句寫在石版；<br/>但是現今生命的律，<br/>是由聖靈寫在心坎。<br/>',NULL,10010,10010);
INSERT INTO stanza VALUES('C532','2','字句律法要人為善，<br/>人的軟弱藉此顯明；<br/>生命的律乃是供應，<br/>使人享受神的大能。<br/>',NULL,10011,10011);
INSERT INTO stanza VALUES('C532','3','字句律法乃在外面，<br/>使我對神有所認識；<br/>生命的律是在裡面，<br/>供我以神更深啟示。<br/>',NULL,10012,10012);
INSERT INTO stanza VALUES('C532','4','字句律法乃在外面，<br/>藉著死的誡命管治；<br/>生命的律是在裡面，<br/>藉著活的知識節制。<br/>',NULL,10013,10013);
INSERT INTO stanza VALUES('C532','5','這個活的生命之律，<br/>在我裡面多方運行，<br/>照著裡面生命感覺，<br/>從我裡面管治、規正。<br/>',NULL,10014,10014);
INSERT INTO stanza VALUES('C532','6','這個管治極細、極深，<br/>在我全人最深之處，<br/>帶來活的生命感覺，<br/>將神自己向我供輸。<br/>',NULL,10015,10015);
INSERT INTO stanza VALUES('C532','7','因這活的生命之律，<br/>外面教導，就不需要；<br/>對神一切活的認識，<br/>從我裡面，這律教導。<br/>',NULL,10016,10016);
INSERT INTO stanza VALUES('C532','8','主，教我憑這律行動，<br/>順服牠的裡面管理，<br/>對你我有活的認識，<br/>並得享受你的自己。<br/>',NULL,10017,10017);
INSERT INTO stanza VALUES('C533','1','永遠生命帶來<br/>生命的交通；<br/>在靈裡的交通，<br/>使靈來推動。<br/>',NULL,10018,10018);
INSERT INTO stanza VALUES('C533','2','永遠生命賜給<br/>神聖的交通；<br/>如此主靈與我，<br/>靈裡同行動。<br/>',NULL,10019,10019);
INSERT INTO stanza VALUES('C533','3','乃是靈裡生命，<br/>帶來這交通；<br/>在靈裡的交通，<br/>使我蒙恩寵。<br/>',NULL,10020,10020);
INSERT INTO stanza VALUES('C533','4','藉著生命大能，<br/>能正確交通；<br/>在靈裡的交通，<br/>帶我到光中。<br/>',NULL,10021,10021);
INSERT INTO stanza VALUES('C533','5','藉血外面洗淨，<br/>交通得維持；<br/>藉膏裡面塗抹，<br/>交通能充實。<br/>',NULL,10022,10022);
INSERT INTO stanza VALUES('C533','6','藉著十架工作，<br/>交通得加深；<br/>藉著聖靈運行，<br/>交通得更新。<br/>',NULL,10023,10023);
INSERT INTO stanza VALUES('C533','7','這一生命交通，<br/>使我脫自己；<br/>這一生命交通，<br/>帶我進神裡。<br/>',NULL,10024,10024);
INSERT INTO stanza VALUES('C534','1','任何生命具有意識，<br/>都有生命感覺；<br/>在我裡的神聖生命，<br/>感覺更為超越。<br/>',NULL,10025,10025);
INSERT INTO stanza VALUES('C534','2','生命性質越是高超，<br/>生命感覺越好；<br/>神的生命最為超特，<br/>牠的感覺最高。<br/>',NULL,10026,10026);
INSERT INTO stanza VALUES('C534','3','這個神的生命感覺，<br/>就是神的感覺，<br/>乃是在我重生靈裡，<br/>遠勝善的感覺。<br/>',NULL,10027,10027);
INSERT INTO stanza VALUES('C534','4','這一裡面生命感覺，<br/>是我最深感覺，<br/>從我裡面分辨一切，<br/>指明神之所悅。<br/>',NULL,10028,10028);
INSERT INTO stanza VALUES('C534','5','藉這裡面生命感覺，<br/>對神我有認識；<br/>不是外面掙扎所得，<br/>乃是自發啟示。<br/>',NULL,10029,10029);
INSERT INTO stanza VALUES('C534','6','我們越在生命長大，<br/>生命感覺越敏；<br/>我們越憑生命行動，<br/>生命感覺越緊。<br/>',NULL,10030,10030);
INSERT INTO stanza VALUES('C534','7','生命感覺若肯操練，<br/>就能使靈剛強；<br/>藉這裡面神的感覺，<br/>交通得以增長。<br/>',NULL,10031,10031);
INSERT INTO stanza VALUES('C535','1','在神所重生聖徒的靈中，<br/>裡面的認識實際又豐富；<br/>所以不需要外面的教導，<br/>乃是在裡面對神有領悟。<br/>',NULL,10032,10032);
INSERT INTO stanza VALUES('C535','2','永遠的生命，<br/>最好也最高，<br/>具有各種樣神聖的功能；<br/>藉著這生命對神的認識，<br/>遠超過外面知識的供應。<br/>',NULL,10033,10033);
INSERT INTO stanza VALUES('C535','3','生命的律法放在我心裡，<br/>由神的聖靈寫在我心上；<br/>裡面的管治，<br/>使我認識神，<br/>遠超過外面教導的影響。<br/>',NULL,10034,10034);
INSERT INTO stanza VALUES('C535','4','恩膏的塗抹住在我靈中，<br/>將神的事情向我心顯明；<br/>藉著這塗抹我能認識神，<br/>超過藉外面教導之所能。<br/>',NULL,10035,10035);
INSERT INTO stanza VALUES('C535','5','三而一的神住在我裡面，<br/>時刻在運行、<br/>生活並行動；<br/>藉神在裡面運行的感覺，<br/>對神的認識高超且深宏。<br/>',NULL,10036,10036);
INSERT INTO stanza VALUES('C535','6','我今既有這裡面的認識，<br/>我就不需要外面的知識；<br/>只需要時刻活在靈裡面，<br/>行事與為人全照靈指示。<br/>',NULL,10037,10037);
INSERT INTO stanza VALUES('C535','7','我們越活在基督的裡面，<br/>越憑著裡面感覺而行動，<br/>我們就越有裡面的認識，<br/>神越將基督銘刻我心中。<br/>',NULL,10038,10038);
INSERT INTO stanza VALUES('C535','8','藉著這裡面生命的認識，<br/>我們能維持與神的交通；<br/>藉著這裡面隱藏的認識，<br/>神性的豐滿要輸供無窮。<br/>',NULL,10039,10039);
INSERT INTO stanza VALUES('C536','1','神成肉身神聖的原則，<br/>乃是神人互相調和；<br/>二者調成一個奧祕人，<br/>照神計畫，共同生活。<br/>',NULL,10040,10040);
INSERT INTO stanza VALUES('C536','2','人是神在外面的表現，<br/>神是人裡面的生命；<br/>人是完全為神所佔有，<br/>神是藉人得著顯明。<br/>',NULL,10041,10041);
INSERT INTO stanza VALUES('C536','3','救贖乃是在人得完成，<br/>為要顯明神的智慧；<br/>救恩乃是藉人來傳揚，<br/>為使造物全都領會。<br/>',NULL,10042,10042);
INSERT INTO stanza VALUES('C536','4','在這時代屬靈的事工，<br/>都該是人與神合作，<br/>使神與人緊密的聯結，<br/>彼此倚賴，互相調和。<br/>',NULL,10043,10043);
INSERT INTO stanza VALUES('C536','5','並非是神單獨的工作，<br/>也非是人單獨事奉；<br/>乃是神、人絕對的合作，<br/>使神計畫得以完成。<br/>',NULL,10044,10044);
INSERT INTO stanza VALUES('C536','6','這個神成肉身的原則，<br/>須應用於一切事工，<br/>也須用於恩賜和功用，<br/>我們就能共同事奉。<br/>',NULL,10045,10045);
INSERT INTO stanza VALUES('C537','1','受造之人是三部分，<br/>有體、有魂並且有靈，<br/>為著成全神的計畫，<br/>並得享受神作供應。<br/>',NULL,10046,10046);
INSERT INTO stanza VALUES('C537','2','身體乃是外面部分，<br/>藉此人有物覺功能；<br/>使人接觸物質世界，<br/>將人自己顯於體形。<br/>',NULL,10047,10047);
INSERT INTO stanza VALUES('C537','3','魂乃是人裡面部分，<br/>是人自己，給人自覺；<br/>藉此人在心理方面，<br/>能以接觸精神世界。<br/>',NULL,10048,10048);
INSERT INTO stanza VALUES('C537','4','靈乃是人最深部分，<br/>在人深處給人神覺；<br/>使人藉此能接受神，<br/>且能接觸屬靈世界。<br/>',NULL,10049,10049);
INSERT INTO stanza VALUES('C537','5','在人魂中有三部分：<br/>心思、意志以及情感；<br/>這是人的各種功能，<br/>用以成全人的意願。<br/>',NULL,10050,10050);
INSERT INTO stanza VALUES('C537','6','在人靈裡也有三部：<br/>交通、直覺以及良心；<br/>藉此人能與神交通，<br/>也能敬拜並接受神。<br/>',NULL,10051,10051);
INSERT INTO stanza VALUES('C537','7','人須運用魂的各部，<br/>將神所是全都揀選；<br/>並用靈來將神接受，<br/>且藉身體將神彰顯。<br/>',NULL,10052,10052);
INSERT INTO stanza VALUES('C537','8','人靈需要神來重生，<br/>得著神的非造生命；<br/>人魂需要神的變化，<br/>體需變成基督榮形。<br/>',NULL,10053,10053);
INSERT INTO stanza VALUES('C537','9','藉著這些神聖工作，<br/>人在他的每一部分，<br/>都得與主完全調和，<br/>並能完全彰顯主神。<br/>',NULL,10054,10054);
INSERT INTO stanza VALUES('C538','1','創世之前神已豫定<br/>兒子名分歸我享，<br/>藉著祂靈將我模成<br/>祂那兒子的形像；<br/>好使祂的獨生愛子，<br/>在眾子中作長子，<br/>藉祂兒子和其弟兄，<br/>滿得彰顯祂榮姿。<br/>',NULL,10055,10055);
INSERT INTO stanza VALUES('C538','2','藉著靈中神聖重生，<br/>我們得作神眾子；<br/>但是我們必須成熟，<br/>纔能作神的後嗣。<br/>藉著完全長大成人，<br/>兒子名分我得享；<br/>藉著長成豐滿身量，<br/>後嗣福分我飽嘗。<br/>',NULL,10056,10056);
INSERT INTO stanza VALUES('C538','3','我們的靈、魂與身體，<br/>都需模成主形狀；<br/>這要完滿完成於我，<br/>當我進入祂榮光。<br/>藉著身體得蒙救贖，<br/>兒子名分得成全；<br/>藉著最終一步變化，<br/>就能滿足神心願。<br/>',NULL,10057,10057);
INSERT INTO stanza VALUES('C538','4','藉那最終一步變化，<br/>我們完全被聖別；<br/>神將我們帶進榮耀，<br/>像祂兒子無虧缺。<br/>造物都在切望等候<br/>神的眾子顯出來；<br/>牠們得進『榮耀』自由，<br/>脫離轄制與敗壞。<br/>',NULL,10058,10058);
INSERT INTO stanza VALUES('C539','1','神造我們作祂器皿，<br/>乃為彰顯祂豐盛；<br/>要我愛祂，為我造心；<br/>要我接受，且造靈。<br/>',NULL,10059,10059);
INSERT INTO stanza VALUES('C539','2','我們應該用心愛神，<br/>也該用靈接受神；<br/>要得神作我們生命，<br/>非此無法能入門。<br/>',NULL,10060,10060);
INSERT INTO stanza VALUES('C539','3','撒但敗壞我們的心，<br/>也弄死了我們靈；<br/>使我不能與神接觸，<br/>反倒靠賴己生命。<br/>',NULL,10061,10061);
INSERT INTO stanza VALUES('C539','4','因此，主在祂救恩裡，<br/>更新我的心與靈；<br/>恢復了我愛的心情，<br/>並我接受的本能。<br/>',NULL,10062,10062);
INSERT INTO stanza VALUES('C539','5','乃是藉著更新的心，<br/>我們愛神，渴慕神；<br/>且是藉著更新的靈，<br/>我們拜神，接受神。<br/>',NULL,10063,10063);
INSERT INTO stanza VALUES('C539','6','對神，我們的心應當<br/>誠實、清潔又單純；<br/>並且我們的靈該是<br/>貧窮、尋求且溫順。<br/>',NULL,10064,10064);
INSERT INTO stanza VALUES('C539','7','神阿，保守我心愛你，<br/>常是新鮮、無陳跡；<br/>並使我靈剛強、活潑，<br/>永以新樣接觸你。<br/>',NULL,10065,10065);
INSERT INTO stanza VALUES('C540','1','與主來往，享主生命，<br/>需一正確的心，<br/>使主一切，藉祂恩典，<br/>我們全都有分。<br/>',NULL,10066,10066);
INSERT INTO stanza VALUES('C540','2','需要一心，凡事純潔，<br/>心思純正、清明，<br/>使我明白主的心意，<br/>常存恐懼、戰兢。<br/>',NULL,10067,10067);
INSERT INTO stanza VALUES('C540','3','需要一心，富有愛情，<br/>情感滿了愛火，<br/>對主熱切，愛慕追求，<br/>不為其他所奪。<br/>',NULL,10068,10068);
INSERT INTO stanza VALUES('C540','4','需要一心，誠實、順服，<br/>意志降服歸順，<br/>要剛則剛，要柔則柔，<br/>神旨惟從、惟遵。<br/>',NULL,10069,10069);
INSERT INTO stanza VALUES('C540','5','需要一心，毫無責備，<br/>良心清潔、無虧，<br/>凡事與神和諧相安，<br/>藉血脫盡定罪。<br/>',NULL,10070,10070);
INSERT INTO stanza VALUES('C540','6','主，賜我們這樣的心，<br/>時刻將你思戀，<br/>使我得享你的豐富，<br/>成為你的豐滿。<br/>',NULL,10071,10071);
INSERT INTO stanza VALUES('C541','1','哦主，你今乃是那靈，<br/>住在我們靈裡；<br/>二靈現今成為一靈，<br/>你我得成為一。<br/>',NULL,10072,10072);
INSERT INTO stanza VALUES('C541','2','你的靈與我們的靈，<br/>永遠同證不弛：<br/>我們乃是神的兒女，<br/>且是神的後嗣。<br/>',NULL,10073,10073);
INSERT INTO stanza VALUES('C541','3','你已成為生命之靈，<br/>來將自己賜賦；<br/>我們今在我們靈中，<br/>享受你的豐富。<br/>',NULL,10074,10074);
INSERT INTO stanza VALUES('C541','4','你今是那生命之靈，<br/>引導、光照、流通；<br/>我們今在我們靈中，<br/>隨你生活、行動。<br/>',NULL,10075,10075);
INSERT INTO stanza VALUES('C541','5','你是那靈，在我靈裡，<br/>時常加強、供應；<br/>在我靈中，藉著你靈，<br/>我們敬拜、事奉。<br/>',NULL,10076,10076);
INSERT INTO stanza VALUES('C541','6','你是那靈，經過我靈，<br/>時以歎息代禱；<br/>在我靈裡，同著你靈，<br/>我們向你禱告。<br/>',NULL,10077,10077);
INSERT INTO stanza VALUES('C541','7','我願回到我們靈中，<br/>在此接觸你靈；<br/>在這靈中我們得享<br/>你的神聖供應。<br/>',NULL,10078,10078);
INSERT INTO stanza VALUES('C541','8','哦主，這是何等聯結，<br/>二靈竟成一靈！<br/>你靈活在我的靈中，<br/>我靈住於你靈！<br/>',NULL,10079,10079);
INSERT INTO stanza VALUES('C542','1','藉著十架將靈分辨，<br/>時常將魂置死地；<br/>背著十架，拒絕自己，<br/>終日活在你靈裡。<br/>',NULL,10080,10080);
INSERT INTO stanza VALUES('C542','2','藉著十架將靈分辨，<br/>靠神生命的活話；<br/>將魂全然從靈分開，<br/>行在靈中不稍差。<br/>',NULL,10081,10081);
INSERT INTO stanza VALUES('C542','3','藉著十架將靈分辨，<br/>心思藉光得更新，<br/>感情全都奉獻給主，<br/>意志因愛也歸順。<br/>',NULL,10082,10082);
INSERT INTO stanza VALUES('C542','4','藉著十架將靈分辨，<br/>經過裂開的幔子；<br/>肉體與魂全被破碎，<br/>靈在凡事佔優勢。<br/>',NULL,10083,10083);
INSERT INTO stanza VALUES('C542','5','藉著十架將靈分辨，<br/>靈是神的至聖所；<br/>在此靈中與神交通，<br/>神的同在必得著。<br/>',NULL,10084,10084);
INSERT INTO stanza VALUES('C542','6','藉著十架將靈分辨，<br/>如同經過約但河；<br/>因此進入迦南美地，<br/>藉享基督而生活。<br/>',NULL,10085,10085);
INSERT INTO stanza VALUES('C542','7','藉著十架將靈分辨，<br/>行動總要在靈裡；<br/>經營基督猶如美地，<br/>祂的豐富必歸你。<br/>',NULL,10086,10086);
INSERT INTO stanza VALUES('C543','1','聖殿深處是至聖所，<br/>內有約櫃並施恩座，<br/>其上有神榮耀同在，<br/>在此神給祭司遇著。<br/>',NULL,10087,10087);
INSERT INTO stanza VALUES('C543','2','我今乃是神的聖殿，<br/>靈是其中的至聖所，<br/>神和基督在此居住，<br/>那靈在此與我同活。<br/>',NULL,10088,10088);
INSERT INTO stanza VALUES('C543','3','在此，在我最深之處，<br/>神在主裡作我一切；<br/>在此，那靈使主基督<br/>作我實際，取用不竭。<br/>',NULL,10089,10089);
INSERT INTO stanza VALUES('C543','4','在此，我在我靈裡面，<br/>和主接觸，與主同在；<br/>在此，我也藉著我靈，<br/>與神交通，向神敬拜。<br/>',NULL,10090,10090);
INSERT INTO stanza VALUES('C543','5','在此，基督如同美地，<br/>我居其中，享其豐富；<br/>也當在此進攻仇敵，<br/>運用權柄對付陰府。<br/>',NULL,10091,10091);
INSERT INTO stanza VALUES('C543','6','我當追求對靈認識，<br/>永遠將靈從魂分開，<br/>並且活在這至聖所，<br/>享受神與主的同在。<br/>',NULL,10092,10092);
INSERT INTO stanza VALUES('C543','7','我當永遠拒絕我魂，<br/>努力進入神的安息，<br/>使我豐滿得著基督，<br/>成全神的永遠旨意。<br/>',NULL,10093,10093);
INSERT INTO stanza VALUES('C544','1','求主教我分辨靈與魂，<br/>好叫我能真認識你；<br/>你今是靈，住在我靈中，<br/>二靈聯合相調為一。<br/>',NULL,10094,10094);
INSERT INTO stanza VALUES('C544','2','求主教我分辨靈與魂，<br/>永遠拒絕魂的生命；<br/>並在靈中永遠跟隨你，<br/>隨時應用你這活靈。<br/>',NULL,10095,10095);
INSERT INTO stanza VALUES('C544','3','求主教我分辨靈與魂，<br/>心思永不置於肉體；<br/>乃是隨時放在靈上面，<br/>使我脫離罪與自己。<br/>',NULL,10096,10096);
INSERT INTO stanza VALUES('C544','4','求主教我分辨靈與魂，<br/>使我永遠不再屬魂，<br/>乃是完全真實的屬靈，<br/>時在靈中行動、生存。<br/>',NULL,10097,10097);
INSERT INTO stanza VALUES('C544','5','求主教我分辨靈與魂，<br/>詭詐的己可被點出；<br/>凡事應用你的十字架，<br/>活著非我，乃是基督。<br/>',NULL,10098,10098);
INSERT INTO stanza VALUES('C544','6','求主教我分辨靈與魂，<br/>使我魂中得以變化，<br/>直到我被模成你形像，<br/>直到成熟，目的得達。<br/>',NULL,10099,10099);
INSERT INTO stanza VALUES('C544','7','求主教我分辨靈與魂，<br/>賜我以你活的話語，<br/>叫我將靈從魂全分開，<br/>而在其中與你同居。<br/>',NULL,10100,10100);
INSERT INTO stanza VALUES('C545','1','三一之神榮耀的靈，<br/>現今住在我靈裡面；<br/>一直想要從我流出，<br/>使神可以得著彰顯。<br/>',NULL,10101,10101);
INSERT INTO stanza VALUES('C545','2','但我外面天然的人，<br/>常將那靈關閉禁拘；<br/>未能讓祂得家安居，<br/>反倒成了祂的監獄。<br/>',NULL,10102,10102);
INSERT INTO stanza VALUES('C545','3','祂像寶貝放在瓦器，<br/>受了遮藏，人難看見；<br/>瓦器必須毀壞、破碎，<br/>寶貝纔能得著彰顯。<br/>',NULL,10103,10103);
INSERT INTO stanza VALUES('C545','4','我們的己必須拆毀，<br/>魂的生命實是捆綁！<br/>天然的人必須破碎，<br/>那靈纔能得著釋放。<br/>',NULL,10104,10104);
INSERT INTO stanza VALUES('C545','5','這個說明何以主許<br/>苦難環境臨到我們；<br/>為要藉著一些折磨，<br/>破碎我們外面的人。<br/>',NULL,10105,10105);
INSERT INTO stanza VALUES('C545','6','外面的人－就是舊魂－必須毀壞、必須受傷；<br/>裡面的人－就是新靈－纔與那靈同得釋放。<br/>',NULL,10106,10106);
INSERT INTO stanza VALUES('C545','7','求主給我這種破碎，<br/>不許我再保全自己；<br/>使我接受一切傷損，<br/>甘願接受，再無異議。<br/>',NULL,10107,10107);
INSERT INTO stanza VALUES('C545','8','使我寶貴你的破碎，<br/>永不再有怨言、怨意；<br/>使我看重一切損失，<br/>過於任何一種利益。<br/>',NULL,10108,10108);
INSERT INTO stanza VALUES('C546','1','神的心意是要我們<br/>模成祂兒子形像；<br/>因此祂靈變化工作，<br/>必須完成我身上。<br/>',NULL,10109,10109);
INSERT INTO stanza VALUES('C546','chorus','求主將我魂的各部，<br/>全都變成你形像；<br/>用你那靈將我浸透，<br/>使我全像你模樣。<br/>',NULL,10110,10110);
INSERT INTO stanza VALUES('C546','2','神已用祂神聖生命，<br/>在我靈中重生我；<br/>但祂還須在我魂中，<br/>作那變化的工作。<br/>',NULL,10111,10111);
INSERT INTO stanza VALUES('C546','3','從我靈中向外開展，<br/>祂就變化我全魂；<br/>更新裡面每一部分，<br/>直到全人都歸順。<br/>',NULL,10112,10112);
INSERT INTO stanza VALUES('C546','4','藉祂那靈生命大能，<br/>照祂形狀變化我；<br/>一部一部，榮上加榮，<br/>模成祂形，新而活。<br/>',NULL,10113,10113);
INSERT INTO stanza VALUES('C546','5','一直變化，全人聖別，<br/>直到像祂，得成熟；<br/>一直變化，魂全佔有，<br/>直到賤體蒙救贖。<br/>',NULL,10114,10114);
INSERT INTO stanza VALUES('C547','1','不是掙扎努力，<br/>乃是全歸依，<br/>使我能得安息，<br/>使我能得力。<br/>不是立志為善，<br/>乃是隨從靈，<br/>使我能脫罪纏，<br/>使我能得勝。<br/>',NULL,10115,10115);
INSERT INTO stanza VALUES('C547','2','不是憑著字句，<br/>乃是憑著靈，<br/>使我能蒙稱許，<br/>使我能得生。<br/>不是人的教導，<br/>乃是神恩膏，<br/>使我能蒙光照，<br/>使我能靈交。<br/>',NULL,10116,10116);
INSERT INTO stanza VALUES('C547','3','不是定意、奔跑，<br/>乃是神憐憫，<br/>使我得神上好，<br/>使我蒙神恩。<br/>不是智慧、聰明，<br/>乃是神恩典，<br/>使我經過苦境，<br/>使我歷艱難。<br/>',NULL,10117,10117);
INSERT INTO stanza VALUES('C547','4','不是高言、大智，<br/>乃是神權能，<br/>使我拯救罪世，<br/>引領人得生。<br/>不是才能、勢力，<br/>乃是神聖靈，<br/>使我成功神意，<br/>完成主使命。<br/>',NULL,10118,10118);
INSERT INTO stanza VALUES('C548','1','神的福音，何等有福！<br/>來救痛苦的人世；<br/>耶穌已為疾病救贖，<br/>祂的鞭傷有醫治。<br/>',NULL,10119,10119);
INSERT INTO stanza VALUES('C548','chorus','讚美救主完全救贖，<br/>來救痛苦的人世；<br/>讚美救主作我大夫，<br/>祂受鞭傷我得治。<br/>',NULL,10120,10120);
INSERT INTO stanza VALUES('C548','2','無論是誰求祂設法，<br/>祂都歡迎不推辭；<br/>祂叫我帶疾病尋祂，<br/>因祂鞭傷能醫治。<br/>',NULL,10121,10121);
INSERT INTO stanza VALUES('C548','3','讚美祂的神聖膏油，<br/>就是聖靈來恩賜；<br/>求你來為我們按手，<br/>因你鞭傷能醫治。<br/>',NULL,10122,10122);
INSERT INTO stanza VALUES('C548','4','當那撒但火箭環攻，<br/>求作盾牌來抵制；<br/>我們必定安全到終，<br/>因你鞭傷有醫治。<br/>',NULL,10123,10123);
INSERT INTO stanza VALUES('C548','5','主，我奉獻所有肢體，<br/>我要榮耀你不止；<br/>使我不至有日忘記<br/>你的鞭傷有醫治。<br/>',NULL,10124,10124);
INSERT INTO stanza VALUES('C549','1','祂醫治我，讚美祂名！<br/>我要歌頌祂的救贖；<br/>祂釋放我脫離疾病，<br/>大能的主是我大夫。<br/>',NULL,10125,10125);
INSERT INTO stanza VALUES('C549','chorus','祂醫治我，祂醫治我，<br/>祂有權柄來醫治我，<br/>許多的人祂已救活，<br/>我今相信祂醫治我。<br/>',NULL,10126,10126);
INSERT INTO stanza VALUES('C549','2','祂醫治我，我用信心<br/>簡單相信祂說的話；<br/>滿有希望，滿有安寧，<br/>信祂必使我離病榻。<br/>',NULL,10127,10127);
INSERT INTO stanza VALUES('C549','3','祂醫治我，我心相信，<br/>來摸祂的衣裳繸子，<br/>祂的能力流通我身，<br/>沉疔霍然得了醫治。<br/>',NULL,10128,10128);
INSERT INTO stanza VALUES('C549','4','祂醫治我，有如當初<br/>祂來擔當疾病、罪過；<br/>祂的大能依然如故，<br/>我的救主永遠活著。<br/>',NULL,10129,10129);
INSERT INTO stanza VALUES('C549','5','祂醫治我，我已求尋<br/>許多次數，但未得著；<br/>如今我是全心相信，<br/>因信，祂今使我再活。<br/>',NULL,10130,10130);
INSERT INTO stanza VALUES('C550','1','當主正從那裡經過，<br/>眾人擁塞將祂擠著，<br/>她從背後將主一摸，<br/>立刻得著了痊愈。<br/>',NULL,10131,10131);
INSERT INTO stanza VALUES('C550','chorus','只是一摸，就得痊愈！<br/>主仍在此，尚未離去，<br/>前來摸祂，不必再疑慮，<br/>一摸就必得痊愈。<br/>',NULL,10132,10132);
INSERT INTO stanza VALUES('C550','2','只是一摸，就得痊愈，<br/>祂使我心平安無懼，<br/>在祂腳前，重擔全去，<br/>我已得著了痊愈。<br/>',NULL,10133,10133);
INSERT INTO stanza VALUES('C550','3','只是一摸，一切完成，<br/>我得脫去所有疾病，<br/>直到永遠我要頌稱，<br/>因我得著了痊愈。<br/>',NULL,10134,10134);
INSERT INTO stanza VALUES('C550','4','只是一摸，祂就轉來，<br/>哦，祂眼中希奇之愛！<br/>撫慰我心，使我感戴，<br/>我已得著了痊愈。<br/>',NULL,10135,10135);
INSERT INTO stanza VALUES('C550','5','只要一摸，必得醫治，<br/>祂能醫你，就在此時，<br/>只是一摸，不管病勢，<br/>就必得著了痊愈。<br/>',NULL,10136,10136);
INSERT INTO stanza VALUES('C551','1','主是禱告的阿拉法，<br/>祂靈教自我靈；<br/>我們不知如何禱告，<br/>除非祂在帶領。<br/>',NULL,10137,10137);
INSERT INTO stanza VALUES('C551','2','主是禱告的俄梅嘎，<br/>神的最大『阿們，』<br/>在我禱告停息之時，<br/>發出同感聲音。<br/>',NULL,10138,10138);
INSERT INTO stanza VALUES('C551','3','但在首尾兩端之間，<br/>祂讓我們接聯，<br/>用那不清似吃話語，<br/>譯出祂所欲言。<br/>',NULL,10139,10139);
INSERT INTO stanza VALUES('C551','4','哦主，你這首先、末後，<br/>使我所有禱告<br/>與你心願完全結合，<br/>說出你之所要。<br/>',NULL,10140,10140);
INSERT INTO stanza VALUES('C551','5','我們不能道出之祈，<br/>全有你作其始；<br/>我們簡短不清之禱，<br/>其終願你也是！<br/>',NULL,10141,10141);
INSERT INTO stanza VALUES('C552','1','禱告乃是靈中所燒聖香，<br/>經過破碎之人向神獻上：<br/>乃是聖靈焚燒之氣所點，<br/>再由信心呼求帶到神前。<br/>',NULL,10142,10142);
INSERT INTO stanza VALUES('C552','2','禱告乃是恩典所產香料，<br/>信心、愛心、<br/>苦難之花所調，<br/>藏在滿了香氣的話裡面，<br/>給神吸入，<br/>欣賞其味之甜。<br/>',NULL,10143,10143);
INSERT INTO stanza VALUES('C552','3','禱告乃是上升含水之氣，<br/>供給甘雨，<br/>並使河流不息，<br/>灌溉乾地，<br/>直到地的四方<br/>所有沙漠都像玫瑰開放。<br/>',NULL,10144,10144);
INSERT INTO stanza VALUES('C552','4','禱告乃是聖靈所滿金管，<br/>用神的油供給神的燈盞；<br/>正當我們<br/>同心等候、禱告，<br/>靈就充滿，<br/>燈就發光照耀。<br/>',NULL,10145,10145);
INSERT INTO stanza VALUES('C552','5','禱告乃是宇宙最大力量，<br/>乃是神的炸藥，<br/>無何能擋；<br/>推動那隻推動一切之手，<br/>轉動大輪，<br/>掠過全地無留。<br/>',NULL,10146,10146);
INSERT INTO stanza VALUES('C552','6','教我禱告！<br/>運行在我靈中，<br/>直到全人被你感覺推動！<br/>在我裡面禱告，<br/>直到顯出：我裡基督禱告天上基督。<br/>',NULL,10147,10147);
INSERT INTO stanza VALUES('C553','1','主阿，<br/>我要安靜在你面前，<br/>將我全人收回到我裡面；<br/>不再僅是外面隨意禱告，<br/>乃是照著靈裡感覺發表。<br/>',NULL,10148,10148);
INSERT INTO stanza VALUES('C553','2','主，<br/>你好像是在天上聽我，<br/>實在你是在我裡面住著；<br/>好像是我向你<br/>呼求、禱告，<br/>實在是你在我裡面發表。<br/>',NULL,10149,10149);
INSERT INTO stanza VALUES('C553','3','有時我雖沒有話語達意，<br/>但我能隨那靈深深歎息；<br/>不是我在外面向你求討，<br/>乃是你在裡面藉我發表。<br/>',NULL,10150,10150);
INSERT INTO stanza VALUES('C553','4','我願在此吸取你的自己，<br/>喫你喝你，<br/>享受你的供給；<br/>好叫我能真實與你相交，<br/>讓你從我裡面得著發表。<br/>',NULL,10151,10151);
INSERT INTO stanza VALUES('C553','5','在這交通裡面，<br/>你光照亮，<br/>你血也要將我洗得清爽；<br/>不僅使我能得徹底光照，<br/>並且使你能有清楚發表。<br/>',NULL,10152,10152);
INSERT INTO stanza VALUES('C553','6','在此你的膏油多方塗抹，<br/>將你塗我裡面越過越多；<br/>你的成分加多，<br/>我的減少，<br/>你就從我得著更多發表。<br/>',NULL,10153,10153);
INSERT INTO stanza VALUES('C553','7','在此向你開啟，<br/>讓你注入，<br/>也要向人敞開，<br/>讓你流出；<br/>在你活水流中與人相交，<br/>好叫你能得著豐滿發表！<br/>',NULL,10154,10154);
INSERT INTO stanza VALUES('C554','1','求主教我如何禱告！<br/>如何使敵遁逃，<br/>如何捆綁滅其權勢，<br/>使眾罪囚得釋。<br/>',NULL,10155,10155);
INSERT INTO stanza VALUES('C554','2','求主教我如何禱告！<br/>如何陣地站牢，<br/>如何奮進攻破營壘，<br/>立使仇敵潰退。<br/>',NULL,10156,10156);
INSERT INTO stanza VALUES('C554','3','求主教我如何禱告！<br/>明白神的最好；<br/>如何禱告搖動天地，<br/>得著血下權利。<br/>',NULL,10157,10157);
INSERT INTO stanza VALUES('C554','4','因著信心，藉著禱告，<br/>學習與主同勞；<br/>學知萬有全屬我們，<br/>運用得勝權柄。<br/>',NULL,10158,10158);
INSERT INTO stanza VALUES('C555','1','主阿，我們今聚集，<br/>同心禱告尋求你；<br/>我們乃是祭司體，<br/>要在你前同侍立。<br/>',NULL,10159,10159);
INSERT INTO stanza VALUES('C555','chorus','在此我們同禱告，<br/>學習摸著你上好，<br/>直到靈裡能相調，<br/>使你召會得建造。<br/>',NULL,10160,10160);
INSERT INTO stanza VALUES('C555','2','切願前來作祭司，<br/>在你面前供聖職，<br/>用靈來摸你意旨，<br/>讓你完成你設施。<br/>',NULL,10161,10161);
INSERT INTO stanza VALUES('C555','3','我們進到至聖所，<br/>摸你施恩的寶座，<br/>隨著靈感向你說，<br/>讓你靈裡多經過。<br/>',NULL,10162,10162);
INSERT INTO stanza VALUES('C555','4','從你施恩的寶座，<br/>流出恩惠的江河，<br/>流到我靈滋潤我，<br/>應時幫助我得著。<br/>',NULL,10163,10163);
INSERT INTO stanza VALUES('C555','5','但願我們的禱告，<br/>就是你靈的發表；<br/>不隨己意來求討，<br/>只照你意向你要。<br/>',NULL,10164,10164);
INSERT INTO stanza VALUES('C555','6','雖有許多的事務，<br/>需要向你來求訴，<br/>卻願你能有出路，<br/>過於我們蒙眷顧。<br/>',NULL,10165,10165);
INSERT INTO stanza VALUES('C555','7','我們仰望你聖垂，<br/>多賜生命的活水；<br/>我們飽嘗你恩惠，<br/>就能讓你有作為。<br/>',NULL,10166,10166);
INSERT INTO stanza VALUES('C556','1','我要進入至聖所，<br/>幔子裡面過生活，<br/>摸主施恩的寶座，<br/>讓主活水來流過。<br/>',NULL,10167,10167);
INSERT INTO stanza VALUES('C556','2','我靈就是至聖所，<br/>主在裡面今住著；<br/>只要回到靈裡面，<br/>我就與主得相見。<br/>',NULL,10168,10168);
INSERT INTO stanza VALUES('C556','3','復活基督的馨香，<br/>調在靈裡來發放；<br/>在靈裡面我禱告，<br/>祂就藉此得發表。<br/>',NULL,10169,10169);
INSERT INTO stanza VALUES('C556','4','摸著靈裡的基督，<br/>就必飽嘗祂豐富：<br/>生命亮光、生命糧，<br/>加上復活的馨香。<br/>',NULL,10170,10170);
INSERT INTO stanza VALUES('C556','5','越摸越深越豐富，<br/>摸著深處的基督：<br/>摸著生命的律法，<br/>摸著隱藏的嗎哪。<br/>',NULL,10171,10171);
INSERT INTO stanza VALUES('C556','6','摸著復活蒙悅納，<br/>如同枯杖發了芽；<br/>在此纔有施恩座，<br/>恩惠流出如江河。<br/>',NULL,10172,10172);
INSERT INTO stanza VALUES('C556','7','我們聚集同禱告，<br/>靈得釋放並相調，<br/>也是進入至聖所，<br/>在此能將主摸著。<br/>',NULL,10173,10173);
INSERT INTO stanza VALUES('C556','8','我們在這至聖所，<br/>同過祭司的生活，<br/>多方摸主施恩座，<br/>直到活水全流過。<br/>',NULL,10174,10174);
INSERT INTO stanza VALUES('C557','1','進入至聖所，<br/>摸主施恩座，<br/>恩惠臨到如同江河；<br/>進入至聖所，<br/>摸主施恩座，<br/>恩惠臨到如同江河。<br/>',NULL,10175,1);
INSERT INTO stanza VALUES('C557','2','進入至聖所，<br/>幔內過生活，<br/>榮光照耀將我射過；<br/>進入至聖所，<br/>幔內過生活，<br/>榮光照耀將我射過。<br/>',NULL,10176,3);
INSERT INTO stanza VALUES('C557','3','回到靈裡面，<br/>禱告在主前，<br/>摸著生命活水泉源；<br/>回到靈裡面，<br/>禱告在主前，<br/>摸著生命活水泉源。<br/>',NULL,10177,5);
INSERT INTO stanza VALUES('C558','1','哦主，幔子已經裂開，<br/>新活之路已通；<br/>我能藉血坦然前來，<br/>到你面光之中。<br/>',NULL,10178,10178);
INSERT INTO stanza VALUES('C558','2','藉著你血贖罪功效，<br/>進入你至聖所；<br/>隨著你靈塗抹、引導，<br/>來摸你施恩座。<br/>',NULL,10179,10179);
INSERT INTO stanza VALUES('C558','3','只隨那靈，不憑自己，<br/>在此燒香禱告，<br/>讓主基督從我靈裡，<br/>如香得著發表。<br/>',NULL,10180,10180);
INSERT INTO stanza VALUES('C558','4','憐恤、恩惠猶如活水，<br/>流自施恩寶座，<br/>應時幫助豐盛、甘美，<br/>將我全人流過。<br/>',NULL,10181,10181);
INSERT INTO stanza VALUES('C558','5','雖然不為事物求討，<br/>只隨那靈禱告，<br/>你卻知道一切需要，<br/>必為我們照料。<br/>',NULL,10182,10182);
INSERT INTO stanza VALUES('C558','6','縱然有何憂苦、罣慮，<br/>也能不受攪擾；<br/>一切全都交你擔去，<br/>我靈就得逍遙。<br/>',NULL,10183,10183);
INSERT INTO stanza VALUES('C558','7','切願如此專清靜，<br/>靈裡與你相交；<br/>隨著你靈轉動、運行，<br/>你前燒香禱告。<br/>',NULL,10184,10184);
INSERT INTO stanza VALUES('C559','1','我奉耶穌全能的名，<br/>跪在施恩寶座前，<br/>打敗許多黑暗軍兵，<br/>滅熄許多的火箭。<br/>',NULL,10185,10185);
INSERT INTO stanza VALUES('C559','chorus','全能名！全能名！<br/>我奉此名就得勝！<br/>全能名！全能名！<br/>撒但、罪、死，都無能！<br/>',NULL,10186,10186);
INSERT INTO stanza VALUES('C559','2','當我求告全能耶穌，<br/>撒但全軍都敗陣；<br/>耶穌，耶穌，全能耶穌！<br/>你的大名是得勝！<br/>',NULL,10187,10187);
INSERT INTO stanza VALUES('C559','3','不久主頒有福命令，<br/>召我進入祂天國，<br/>那時全能耶穌的名，<br/>使我得登祂寶座！<br/>',NULL,10188,10188);
INSERT INTO stanza VALUES('C560','1','要對這山說：『去，<br/>離此，投在海裡！』<br/>心中若不疑惑，<br/>就必成就於你。<br/>相信主話，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10189,10189);
INSERT INTO stanza VALUES('C560','2','取用救贖權利，<br/>主的寶血所買；<br/>使這權利有效，<br/>三一之神同來。<br/>順服主話，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10190,10190);
INSERT INTO stanza VALUES('C560','3','自己、罪惡、病痛，<br/>主已全部擔當，<br/>神的要求滿足，<br/>你已得著釋放。<br/>倚靠主話，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10191,10191);
INSERT INTO stanza VALUES('C560','4','圍繞高大牆垣，<br/>憑信禱告放膽；<br/>在牆未倒之先，<br/>喊出得勝頌讚。<br/>安心相信，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10192,10192);
INSERT INTO stanza VALUES('C560','5','所有銅門鐵閂，<br/>全都仆倒降服，<br/>讓那相信戰士，<br/>高唱凱歌進入。<br/>不睬仇敵，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10193,10193);
INSERT INTO stanza VALUES('C560','6','取用神的信心，<br/>脫去不信恥辱；<br/>廣行神蹟之杖，<br/>要將理由盡逐。<br/>站在主話，必要成全，<br/>在主裡面吩咐你山！<br/>',NULL,10194,10194);
INSERT INTO stanza VALUES('C561','1','『憑信心求，』<br/>奉主的名，<br/>施恩座前來禱告；<br/>你若相信，聽主答應：<br/>看哪，小子，已成了。<br/>',NULL,10195,10195);
INSERT INTO stanza VALUES('C561','2','『憑信心求，』<br/>神要成就<br/>聖靈組織的禱告；<br/>祂必施行奇妙拯救，<br/>遠超過你所意料。<br/>',NULL,10196,10196);
INSERT INTO stanza VALUES('C561','3','『憑信心求，』<br/>纔是禱告，<br/>因信你就敢站牢，<br/>滿有平安、盼望、歡笑，<br/>高張兩手向神要。<br/>',NULL,10197,10197);
INSERT INTO stanza VALUES('C561','4','『憑信心求，』<br/>神正等你<br/>能憑信心來求懇；<br/>因為信心隨時隨地<br/>得神喜悅摸著神。<br/>',NULL,10198,10198);
INSERT INTO stanza VALUES('C562','1','再唱信心的歌！<br/>無論夜如何黑；<br/>你若讚美，神要工作，<br/>使你所信能得。<br/>使你所信能得。<br/>',NULL,10199,10199);
INSERT INTO stanza VALUES('C562','2','再唱信心的歌！<br/>你魂應當讚頌；<br/>因神喜悅信心唱歌，<br/>於漫漫長夜中。<br/>',NULL,10200,10200);
INSERT INTO stanza VALUES('C562','3','再唱信心的歌！<br/>仇敵聽見要抖；<br/>讚美原來會勝鬼魔，<br/>何致被他箝口。<br/>',NULL,10201,10201);
INSERT INTO stanza VALUES('C562','4','再唱信心的歌！<br/>不久天就要曙，<br/>我們要唱無終的歌，<br/>我們要去見主。<br/>',NULL,10202,10202);
INSERT INTO stanza VALUES('C563','1','要在靈裡同心禱告，<br/>不照你心所思想，<br/>只照深處恩膏塗抹，<br/>成全主心所願望。<br/>',NULL,10203,10203);
INSERT INTO stanza VALUES('C563','chorus','要在靈裡同心禱告，<br/>不照你心所思想，<br/>只照深處恩膏塗抹，<br/>成全主心所願望。<br/>',NULL,10204,10204);
INSERT INTO stanza VALUES('C563','2','要在靈裡同心禱告，<br/>藉著十架否認己；<br/>一切願望、所有心意，<br/>都要讓靈來管理。<br/>',NULL,10205,10205);
INSERT INTO stanza VALUES('C563','3','要在靈裡同心禱告，<br/>坐在天上用權柄；<br/>屬地利益全踏腳下，<br/>進攻空中的首領。<br/>',NULL,10206,10206);
INSERT INTO stanza VALUES('C563','4','要在靈裡同心禱告，<br/>與眾聖徒同祈求；<br/>尋求主的心意、帶領，<br/>靈中和諧永保守。<br/>',NULL,10207,10207);
INSERT INTO stanza VALUES('C563','5','要在靈裡同心禱告，<br/>儆醒、禱告要持久；<br/>為神國度和神榮耀，<br/>儆醒、禱告到成就。<br/>',NULL,10208,10208);
INSERT INTO stanza VALUES('C563','6','要在靈裡同心禱告，<br/>和諧一致尋求神；<br/>在主身體的靈裡面，<br/>永遠禱告憑同心。<br/>',NULL,10209,10209);
INSERT INTO stanza VALUES('C564','1','永遠要在靈裡禱告，<br/>不憑肉體或頭腦！<br/>這個祕訣若肯實行，<br/>神的同在必得到。<br/>',NULL,10210,10210);
INSERT INTO stanza VALUES('C564','chorus','永遠要在靈裡禱告，<br/>這個祕訣主所示；<br/>在靈裡面與神接觸，<br/>這個祕訣要保持。<br/>',NULL,10211,10211);
INSERT INTO stanza VALUES('C564','2','永遠要在靈裡禱告，<br/>絕不憑著人思想；<br/>與神這靈交通來往，<br/>惟有如此能得嘗。<br/>',NULL,10212,10212);
INSERT INTO stanza VALUES('C564','3','永遠要在靈裡禱告，<br/>藉此發表神心願；<br/>靈裡與主一直相處，<br/>全人必被主火燃。<br/>',NULL,10213,10213);
INSERT INTO stanza VALUES('C564','4','永遠要在靈裡禱告，<br/>甚至由衷來歎息！<br/>藉著那靈管治、帶領，<br/>如此發表神心意。<br/>',NULL,10214,10214);
INSERT INTO stanza VALUES('C564','5','永遠要在靈裡禱告，<br/>就是在神至聖所；<br/>惟有如此在這靈裡，<br/>纔能與神相調和。<br/>',NULL,10215,10215);
INSERT INTO stanza VALUES('C564','6','永遠要在靈裡禱告，<br/>這是惟一的途徑；<br/>神性所有一切豐滿，<br/>藉這祕訣能受領。<br/>',NULL,10216,10216);
INSERT INTO stanza VALUES('C565','1','禱告摸神的寶座，<br/>摸神施恩的寶座，<br/>蒙到憐恤和恩惠，<br/>應時幫助必得著。<br/>',NULL,10217,10217);
INSERT INTO stanza VALUES('C565','2','禱告摸神的寶座，<br/>深感需要神恩典，<br/>靈裡與神同停留，<br/>面面交通毫無間。<br/>',NULL,10218,10218);
INSERT INTO stanza VALUES('C565','3','禱告摸神的寶座，<br/>認識恩典的富有；<br/>一直支取並享受，<br/>向神感讚勝祈求。<br/>',NULL,10219,10219);
INSERT INTO stanza VALUES('C565','4','禱告摸神的寶座，<br/>摸神掌權的寶座；<br/>在主基督的名裡，<br/>對付陰府與鬼魔。<br/>',NULL,10220,10220);
INSERT INTO stanza VALUES('C565','5','禱告摸神的寶座，<br/>藉著活信主所賜；<br/>運用屬天的權柄，<br/>對付死亡的權勢。<br/>',NULL,10221,10221);
INSERT INTO stanza VALUES('C565','6','禱告摸神的寶座，<br/>震動陰府的權勢；<br/>寶座之上用王權，<br/>同主禱告在此時。<br/>',NULL,10222,10222);
INSERT INTO stanza VALUES('C566','1','我願多方禱告，<br/>隨時操練靈！<br/>已往禱告太少，<br/>所以靈不明；<br/>即使有些禱告，<br/>也是少用靈；<br/>多為事物求討，<br/>不隨靈運行。<br/>',NULL,10223,10223);
INSERT INTO stanza VALUES('C566','2','今願靈裡禱告，<br/>隨從靈歎息；<br/>照著靈感發表，<br/>不照所記憶。<br/>不再憑著頭腦，<br/>只是憑著靈；<br/>無論讚美求告，<br/>都隨靈引領。<br/>',NULL,10224,10224);
INSERT INTO stanza VALUES('C566','3','不但自己禱告，<br/>我要操練靈；<br/>就是同人禱告，<br/>也要如此行。<br/>絕不外面應付，<br/>禱告不動靈；<br/>乃是裡面深處，<br/>靈與靈響應。<br/>',NULL,10225,10225);
INSERT INTO stanza VALUES('C566','4','不再一同事奉，<br/>卻不同禱告，<br/>光用脣舌交通，<br/>靈不動絲毫。<br/>不再一同禱告，<br/>靈卻不相交；<br/>外面儘管喊叫，<br/>裡面摸不著。<br/>',NULL,10226,10226);
INSERT INTO stanza VALUES('C566','5','隨處都能禱告，<br/>隨處操練靈；<br/>無論人多人少，<br/>都能運用靈。<br/>不分時、地、人位，<br/>總不受影響；<br/>任何一種聚會，<br/>靈都能釋放。<br/>',NULL,10227,10227);
INSERT INTO stanza VALUES('C566','6','靈一如此高昂，<br/>主就能亨通。<br/>靈是如此剛強，<br/>我就能有用。<br/>靈裡活水流通，<br/>聖徒纔相調；<br/>在這流通之中，<br/>召會得建造。<br/>',NULL,10228,10228);
INSERT INTO stanza VALUES('C567','1','禱告要將主發表，<br/>不可發表我自己；<br/>讓主啟示祂自己，<br/>藉我發表祂心意。<br/>',NULL,10229,10229);
INSERT INTO stanza VALUES('C567','2','禱告要將主發表，<br/>必須說出祂所要，<br/>靜下自己的思想，<br/>與主心思得協調。<br/>',NULL,10230,10230);
INSERT INTO stanza VALUES('C567','3','禱告要將主發表，<br/>總要將祂來瞻仰，<br/>如同鏡子在觀看，<br/>從衷返照祂榮光。<br/>',NULL,10231,10231);
INSERT INTO stanza VALUES('C567','4','禱告要將主發表，<br/>讓祂藉我來求訴；<br/>住在我裡的基督，<br/>禱告天上的基督。<br/>',NULL,10232,10232);
INSERT INTO stanza VALUES('C567','5','禱告要將主發表，<br/>學習不憑自己求，<br/>完全向著主禱告，<br/>只憑祂求到永久。<br/>',NULL,10233,10233);
INSERT INTO stanza VALUES('C568','1','禱告與主來往交通，<br/>祂面靈裡來尋求；<br/>祂前求問並且靜聽，<br/>隱密之處來等候。<br/>',NULL,10234,10234);
INSERT INTO stanza VALUES('C568','chorus','禱告與主來往交通，<br/>祂面靈裡來尋求；<br/>祂前求問並且靜聽，<br/>隱密之處來等候。<br/>',NULL,10235,10235);
INSERT INTO stanza VALUES('C568','2','禱告與主來往交通，<br/>從你裡面全敞開；<br/>敞著臉面將祂瞻仰，<br/>單一、純潔又實在。<br/>',NULL,10236,10236);
INSERT INTO stanza VALUES('C568','3','禱告與主來往交通，<br/>憑信將祂來尋求；<br/>學習來摸祂這活靈，<br/>恭敬、仰望並等候。<br/>',NULL,10237,10237);
INSERT INTO stanza VALUES('C568','4','禱告與主來往交通，<br/>以靈、以真為祕訣；<br/>總要憑靈禱告、求問，<br/>照著裡面的感覺。<br/>',NULL,10238,10238);
INSERT INTO stanza VALUES('C568','5','禱告與主來往交通，<br/>誠懇靜聽祂所言；<br/>讓祂心意印刻於你，<br/>使你成全祂心願。<br/>',NULL,10239,10239);
INSERT INTO stanza VALUES('C568','6','禱告與主來往交通，<br/>沐浴在祂面光中；<br/>讓祂榮美將你浸透，<br/>使你返照祂面容。<br/>',NULL,10240,10240);
INSERT INTO stanza VALUES('C569','1','禱告與主同勞苦，<br/>禱告為主將路鋪，<br/>禱告把主來推動，<br/>也被推動走主路。<br/>',NULL,10241,10241);
INSERT INTO stanza VALUES('C569','2','禱告與主同勞苦，<br/>照主心意和目的；<br/>與主完全的聯合，<br/>直到祝福能滿溢。<br/>',NULL,10242,10242);
INSERT INTO stanza VALUES('C569','3','禱告與主同勞苦，<br/>自己雄心要拋棄；<br/>己意也要全拒絕，<br/>惟獨顧到主旨意。<br/>',NULL,10243,10243);
INSERT INTO stanza VALUES('C569','4','禱告與主同勞苦，<br/>讓主發起並推行；<br/>所有計畫和工作，<br/>都是主藉我完成。<br/>',NULL,10244,10244);
INSERT INTO stanza VALUES('C569','5','禱告與主同勞苦，<br/>直到大輪已轉動；<br/>與主一同來禱告，<br/>直到召會能跟從。<br/>',NULL,10245,10245);
INSERT INTO stanza VALUES('C570','1','我今如此為主爭戰，<br/>撒但真是不甘；<br/>他用他的所有權勢，<br/>要我中途停止；<br/>我卻不住禱告，<br/>轉使仇敵遁逃；<br/>因為與主說一聲，<br/>甚麼就都好。<br/>',NULL,10246,10246);
INSERT INTO stanza VALUES('C570','chorus','只要與主說一聲，<br/>甚麼就都好；<br/>只要與主說一聲，<br/>甚麼就都好。<br/>讚美主，<br/>我每次受試煉的時候，<br/>只要與主說一聲，<br/>甚麼就都好。<br/>',NULL,10247,10247);
INSERT INTO stanza VALUES('C570','2','我雖經歷黑暗、崎嶇，<br/>雖遇疾風、暴雨，<br/>雖然試煉不斷繼續，<br/>前途真是可慮，<br/>轉瞬我就得勝，<br/>因我靠主大能，<br/>因我與主說一聲，<br/>甚麼必都好。<br/>',NULL,10248,10248);
INSERT INTO stanza VALUES('C570','3','當我親友向我攻擊，<br/>愛人渺無信息，<br/>當我軟弱、孤單、無倚，<br/>被人誤會、撇棄，<br/>我將傷心告主，<br/>祂就立刻安撫；<br/>真的，與主說一聲，<br/>甚麼就都好。<br/>',NULL,10249,10249);
INSERT INTO stanza VALUES('C570','4','因我與主常是密語，<br/>我心就無煩慮，<br/>逐日都是歡呼歌唱，<br/>穩靠救主胸膛；<br/>我今倚主手臂，<br/>我要證明到底：<br/>只要與主說一聲，<br/>甚麼就都好。<br/>',NULL,10250,10250);
INSERT INTO stanza VALUES('C571','1','何等朋友，我主耶穌！<br/>擔我罪孽負我憂；<br/>何等權利，能將難處<br/>到主面前去祈求。<br/>多少平安屢屢喪失，<br/>多少痛苦無須受；<br/>無非我們未將萬事<br/>到主面前去祈求。<br/>',NULL,10251,10251);
INSERT INTO stanza VALUES('C571','2','我們有否苦難、艱辛？<br/>有否試探和引誘？<br/>不能因此失望、灰心，<br/>應當向主去祈求。<br/>誰能像祂忠實、穩妥，<br/>背我重擔分我愁？<br/>惟祂知我每一軟弱，<br/>故當向主去祈求。<br/>',NULL,10252,10252);
INSERT INTO stanza VALUES('C571','3','我們是否疲倦，苦楚、<br/>思慮、重擔壓心頭？<br/>救主仍舊是避難處，<br/>應當向祂去祈求。<br/>朋友有否賣你、棄你？<br/>應當向主去祈求；<br/>祂的懷抱是你護庇，<br/>經祂撫慰必無憂。<br/>',NULL,10253,10253);
INSERT INTO stanza VALUES('C572','1','我所有苦況，<br/>必須告訴主，<br/>我不能獨自擔此憂鬱；<br/>我在患難中，<br/>惟主能安撫，<br/>擦去我眼淚，<br/>將我體恤。<br/>',NULL,10254,10254);
INSERT INTO stanza VALUES('C572','chorus','我必須告訴，<br/>必須告訴主，<br/>將我的心事向主傾吐；<br/>我必須告訴，<br/>必須告訴主，<br/>惟主知我心，<br/>樂於安撫。<br/>',NULL,10255,10255);
INSERT INTO stanza VALUES('C572','2','我所有困難，<br/>必須告訴主，<br/>我不能獨自對付遭遇；<br/>我一切事務，<br/>惟主能擔負，<br/>使我得安息，<br/>慰我情緒。<br/>',NULL,10256,10256);
INSERT INTO stanza VALUES('C572','3','我所有缺乏，<br/>必須告訴主，<br/>我不能獨自卸去憂慮；<br/>我所有需要，<br/>惟主能滿足，<br/>使我享豐富，<br/>綽綽有餘。<br/>',NULL,10257,10257);
INSERT INTO stanza VALUES('C572','4','我所有軟弱，<br/>必須告訴主，<br/>我不能獨自勝過私慾；<br/>我所有捆綁，<br/>惟主能幫助，<br/>使我得釋放，<br/>脫離罪律。<br/>',NULL,10258,10258);
INSERT INTO stanza VALUES('C572','5','我所有試探，<br/>必須告訴主，<br/>我不能獨自抵擋鬼魔；<br/>主所受試探，<br/>與我毫無殊，<br/>惟主能救我脫離兇惡。<br/>',NULL,10259,10259);
INSERT INTO stanza VALUES('C573','1','祭司職分神聖高尚！<br/>常將祭物向神獻上，<br/>常在聖所向神仰望，<br/>常在神前燒香！<br/>',NULL,10260,10260);
INSERT INTO stanza VALUES('C573','chorus','常在神前燒香！<br/>常在神前燒香！<br/>常在神前將燈點亮，<br/>也常向神歌唱！<br/>',NULL,10261,10261);
INSERT INTO stanza VALUES('C573','2','聖所並無天然之光，<br/>需要燈臺發光照亮；<br/>祭司每逢進內燒香，<br/>都要將燈點亮！<br/>',NULL,10262,10262);
INSERT INTO stanza VALUES('C573','3','為要將神美德頌揚，<br/>激動人心起來共賞，<br/>祭司除了點燈、燒香，<br/>也要向神歌唱！<br/>',NULL,10263,10263);
INSERT INTO stanza VALUES('C573','4','我要禱告如同燒香，<br/>獻上基督復活馨香，<br/>照神心願，供神欣賞，<br/>我得與神同享。<br/>',NULL,10264,10264);
INSERT INTO stanza VALUES('C573','5','我要讀經接受亮光，<br/>如同神前將燈點亮；<br/>神聖之光照耀輝煌，<br/>在我心中射放。<br/>',NULL,10265,10265);
INSERT INTO stanza VALUES('C573','6','我要唱詩向主頌揚，<br/>猶如祭司向神歌唱，<br/>頌揚主恩、主愛無疆，<br/>我就將主飽嘗。<br/>',NULL,10266,10266);
INSERT INTO stanza VALUES('C573','7','禱告獻上主的馨香，<br/>讀經接受主的亮光，<br/>唱詩頌揚主的恩賞，<br/>主靈就得通暢！<br/>',NULL,10267,10267);
INSERT INTO stanza VALUES('C574','1','我今等候，<br/>主，我今等候；<br/>讓我安息於你，<br/>使我清楚你意，<br/>這是我所懇祈－我今等候，我今等候。<br/>',NULL,10268,10268);
INSERT INTO stanza VALUES('C574','2','我今等候，<br/>主，我今等候；<br/>當我在此停留，<br/>向我施行拯救，<br/>教我藉你祈求－我今等候，我今等候。<br/>',NULL,10269,10269);
INSERT INTO stanza VALUES('C574','3','我今等候，<br/>主，我今等候；<br/>完全與我調和，<br/>直到安家於我，<br/>你像在我顯著－我今等候，我今等候。<br/>',NULL,10270,10270);
INSERT INTO stanza VALUES('C574','4','我今等候，<br/>主，我今等候；<br/>你旨向我明授，<br/>你路助我肯走，<br/>你命藉我湧流－我今等候，我今等候。<br/>',NULL,10271,10271);
INSERT INTO stanza VALUES('C574','5','我今等候，<br/>主，我今等候；<br/>願我所有禱告，<br/>都是你的發表，<br/>使神得著榮耀－我今等候，我今等候。<br/>',NULL,10272,10272);
INSERT INTO stanza VALUES('C575','1','我魂要肅靜，<br/>等候你的主！<br/>先讓祂說話，<br/>然後向祂訴。<br/>真實的禱告，<br/>乃是主發起；<br/>你僅是器皿，<br/>發表祂自己。<br/>',NULL,10273,10273);
INSERT INTO stanza VALUES('C575','2','我魂要肅靜，<br/>等候你的主！<br/>你所有意念，<br/>全都要不顧。<br/>讓神用自己，<br/>來將你塗抹，<br/>並藉你禱告，<br/>且藉你活著。<br/>',NULL,10274,10274);
INSERT INTO stanza VALUES('C575','3','我魂要肅靜，<br/>等候你的主！<br/>停下你心願，<br/>不再操己路。<br/>今生的憂慮、<br/>地上的呼召，<br/>全都丟一邊，<br/>只顧神所要。<br/>',NULL,10275,10275);
INSERT INTO stanza VALUES('C575','4','我魂要肅靜，<br/>等候你的主！<br/>將你的心意<br/>向靈全降服。<br/>並且要讓靈<br/>指明神所示，<br/>如此你就作<br/>順服的執事。<br/>',NULL,10276,10276);
INSERT INTO stanza VALUES('C575','5','我魂要肅靜，<br/>等候你的主！<br/>學習更讓靈<br/>經過你求訴。<br/>你整個的人<br/>都與靈相調，<br/>使你的禱告<br/>作神的發表。<br/>',NULL,10277,10277);
INSERT INTO stanza VALUES('C575','6','我魂要肅靜，<br/>等候你的主！<br/>直等在靈裡<br/>你與神相符。<br/>並且藉著靈<br/>一切全歸服，<br/>如此每部分<br/>都變得像主。<br/>',NULL,10278,10278);
INSERT INTO stanza VALUES('C575','7','我魂要肅靜，<br/>等候你的主！<br/>使神能藉你<br/>自由的流出，<br/>直到每時刻<br/>你言與你行，<br/>都使神心意<br/>藉你得完成。<br/>',NULL,10279,10279);
INSERT INTO stanza VALUES('C576','1','復興你工作，主！<br/>向你聖徒顯現；<br/>求你用權發命監督，<br/>讓你兒女檢點。<br/>',NULL,10280,10280);
INSERT INTO stanza VALUES('C576','chorus','復興你工作，主！<br/>我們現今等候；<br/>但願正當我們俯伏，<br/>你就顯現能手。<br/>',NULL,10281,10281);
INSERT INTO stanza VALUES('C576','2','復興你工作，主！<br/>求你感動召會，<br/>為著罪惡，憂傷痛悔，<br/>好讓你顯作為。<br/>',NULL,10282,10282);
INSERT INTO stanza VALUES('C576','3','復興你工作，主！<br/>啟示你的寶貴；<br/>但願你愛在人心內，<br/>好像復燃死灰。<br/>',NULL,10283,10283);
INSERT INTO stanza VALUES('C576','4','復興你工作，主！<br/>祝福你的話語；<br/>但願你道所有真理，<br/>到處被人高舉。<br/>',NULL,10284,10284);
INSERT INTO stanza VALUES('C576','5','復興你工作，主！<br/>證明你的得勝；<br/>但願你民起來戰爭，<br/>使敵權勢潰崩。<br/>',NULL,10285,10285);
INSERT INTO stanza VALUES('C576','6','復興你工作，主！<br/>賜下當初權能；<br/>願其榮耀全歸你名，<br/>祝福則歸我們。<br/>',NULL,10286,10286);
INSERT INTO stanza VALUES('C577','1','主給這個地方，<br/>給這個地方，<br/>將一個大復興，<br/>給這個地方。<br/>除去所有阻擋，<br/>使我靈高昂，<br/>好叫我運生命<br/>來醫治人傷。<br/>',NULL,10287,10287);
INSERT INTO stanza VALUES('C578','1','禱告之時、甘甜之時！<br/>使我離開煩惱之事，<br/>來到神的座前發表<br/>所有意願、所有需要；<br/>當我遇到重壓、憂愁，<br/>我靈卻常得著自由，<br/>不陷惡者所有佈置，<br/>因為有你－禱告之時！<br/>',NULL,10288,10288);
INSERT INTO stanza VALUES('C578','2','禱告之時、甘甜之時！<br/>如有雙翼載我願辭，<br/>到祂寶座向神求懇，<br/>祂是信實，祂是全真。<br/>祂既命我尋求祂面，<br/>信祂話語，靠祂恩典，<br/>我要將我重擔卸釋<br/>在於你前－甘甜之時！<br/>',NULL,10289,10289);
INSERT INTO stanza VALUES('C578','3','禱告之時、甘甜之時！<br/>每次相逢慰我心思，<br/>直到我在毗斯迦山，<br/>發現美地極目一看，<br/>脫下帳棚，安靜等候，<br/>信心變見，盼望成就；<br/>臨行我必大聲告辭：<br/>平安、平安，禱告之時！<br/>',NULL,10290,10290);
INSERT INTO stanza VALUES('C579','1','全部的聖經<br/>都是神呼出，<br/>由神的聖靈<br/>用字來撰述；<br/>再藉眾神人<br/>將撰述記錄，<br/>帶著神豐富，<br/>給人來吸入。<br/>',NULL,10291,10291);
INSERT INTO stanza VALUES('C579','2','這是神呼出，<br/>作人的亮光，<br/>用神聖光線<br/>將人來照亮；<br/>照在黑暗中，<br/>使人能看明<br/>自己的需要、<br/>並真實光景。<br/>',NULL,10292,10292);
INSERT INTO stanza VALUES('C579','3','這是神呼出，<br/>作人的生命，<br/>使人能得著<br/>神聖的性情；<br/>點活死的人，<br/>且將人重生，<br/>更新人心思、<br/>變化魂生命。<br/>',NULL,10293,10293);
INSERT INTO stanza VALUES('C579','4','這是神呼出，<br/>作人的智慧，<br/>神聖的知識，<br/>教導人領會；<br/>向人來啟示<br/>神永遠旨意，<br/>領導人達到<br/>神終極目的。<br/>',NULL,10294,10294);
INSERT INTO stanza VALUES('C579','5','這是神呼出，<br/>作人的能力，<br/>神聖的能力，<br/>向人來供給；<br/>軟弱者剛強，<br/>疲倦者加力，<br/>使人有力量<br/>完成神旨意。<br/>',NULL,10295,10295);
INSERT INTO stanza VALUES('C579','6','這是神呼出，<br/>為給我呼吸，<br/>好叫我享受<br/>神作我福氣；<br/>藉著運用靈，<br/>吸入神所呼，<br/>應付我需要，<br/>享受神豐富。<br/>',NULL,10296,10296);
INSERT INTO stanza VALUES('C580','1','主神已經說話，<br/>自己已啟曉；<br/>祂的性格、身位，<br/>全給人知道；<br/>向著亞當子孫，<br/>啟示祂心意，<br/>明言、豫表、豫言，<br/>描繪幾無遺。<br/>',NULL,10297,10297);
INSERT INTO stanza VALUES('C580','2','主神已經說話，<br/>表明所欲為：<br/>要叫祂的兒子，<br/>凡事居首位，<br/>使祂在子裡面，<br/>榮耀得完全，<br/>而在萬有中間，<br/>得著了彰顯。<br/>',NULL,10298,10298);
INSERT INTO stanza VALUES('C580','3','主神已經說話，<br/>基督已啟示：<br/>雖然祂是真神，<br/>但人祂也是；<br/>祂是一切一切，<br/>充滿了萬有；<br/>是神計畫裡的<br/>中心與圓周。<br/>',NULL,10299,10299);
INSERT INTO stanza VALUES('C580','4','主神已經說話，<br/>天不再緘默：<br/>三一之神願意<br/>來與人調和；<br/>父在子的裡面，<br/>子又成為靈，<br/>住進基督身體，<br/>計畫得完成。<br/>',NULL,10300,10300);
INSERT INTO stanza VALUES('C580','5','主神已經說話，<br/>啟示祂奧祕：<br/>基督與祂召會，<br/>二者成為一；<br/>基督帶神豐滿，<br/>來作榮耀頭；<br/>召會是祂身體，<br/>享受祂所有。<br/>',NULL,10301,10301);
INSERT INTO stanza VALUES('C580','6','主神已經說話，<br/>一切已啟示：<br/>說到祂的創造，<br/>並說祂降世，<br/>說到祂的救贖，<br/>並說祂救恩；<br/>但願地上萬有，<br/>讚美祂不盡。<br/>',NULL,10302,10302);
INSERT INTO stanza VALUES('C581','1','哦主，<br/>神的活話，<br/>神的真像，<br/>你是神話內容，<br/>神聖寶藏；<br/>在你我們看見神的豐滿，<br/>你又藉著聖經向我顯現。<br/>',NULL,10303,10303);
INSERT INTO stanza VALUES('C581','2','從未有人見神，<br/>在你之外，<br/>若無聖經你難啟示出來；<br/>你已將神向人清楚表明，<br/>然而對你認識是藉聖經。<br/>',NULL,10304,10304);
INSERT INTO stanza VALUES('C581','3','你是神的化身，<br/>具體、完全，<br/>聖經是你描述，<br/>真實、豐滿；<br/>在你我們領略神的真像，<br/>但藉聖經纔能將你欣賞。<br/>',NULL,10305,10305);
INSERT INTO stanza VALUES('C581','4','你是生命之靈，<br/>你又是話，<br/>這話因靈豐盛，<br/>無以復加；<br/>藉你內住之靈摸著這話，<br/>你就將你豐盛向我賜下。<br/>',NULL,10306,10306);
INSERT INTO stanza VALUES('C581','5','在你裡面我可與神交通，<br/>藉著聖經我能享你無窮；<br/>每憑經中話語向你讀禱，<br/>你的豐富就顧我的需要。<br/>',NULL,10307,10307);
INSERT INTO stanza VALUES('C581','6','求主教我如何運用我靈，<br/>禱讀你話，<br/>藉以受你供應；<br/>你和經中話語相調為一，<br/>就作生命嗎哪，<br/>每日供給。<br/>',NULL,10308,10308);
INSERT INTO stanza VALUES('C582','1','主，你是話，你也是靈，<br/>我們讚美同靈和聲！<br/>讚美你話使我知曉，<br/>敬拜你靈使我觸到。<br/>',NULL,10309,10309);
INSERT INTO stanza VALUES('C582','2','恩主，你是我的一切，<br/>全在你能與我聯結；<br/>所以是話，且又是靈，<br/>為能來作我的供應。<br/>',NULL,10310,10310);
INSERT INTO stanza VALUES('C582','3','你若是主，而不是話，<br/>我要知你，有何辦法？<br/>你若是神，而不是靈，<br/>我要觸你，又怎可能？<br/>',NULL,10311,10311);
INSERT INTO stanza VALUES('C582','4','話是你的明確啟示，<br/>使我對你能有認識；<br/>靈是你的本身本質，<br/>使我接觸你的所是。<br/>',NULL,10312,10312);
INSERT INTO stanza VALUES('C582','5','你是我的生命、亮光、<br/>道路、真理、<br/>活水、靈糧；<br/>全藉你話向我傳遞，<br/>並憑你靈使我經歷。<br/>',NULL,10313,10313);
INSERT INTO stanza VALUES('C582','6','你話在於所寫聖經，<br/>你靈就是內住聖靈；<br/>你話進入我心我靈，<br/>也就是靈，且是生命。<br/>',NULL,10314,10314);
INSERT INTO stanza VALUES('C582','7','我要明白你的聖經，<br/>也要接觸你的聖靈；<br/>不僅憑著頭腦明瞭，<br/>且要用靈敬拜禱告。<br/>',NULL,10315,10315);
INSERT INTO stanza VALUES('C582','8','你話乃是我心所愛，<br/>你靈更是我靈所拜；<br/>在你話中我心歡暢，<br/>在你靈裡我靈歌唱。<br/>',NULL,10316,10316);
INSERT INTO stanza VALUES('C583','1','願主為我擘開生命的餅，<br/>就像當日旁海對眾所行。<br/>靠這聖書引導，<br/>我尋求你；<br/>我主，神的活道，<br/>我渴慕你！<br/>',NULL,10317,10317);
INSERT INTO stanza VALUES('C583','2','願主為我擘開生命的餅，<br/>使我充滿主愛，<br/>記念主名！<br/>釋放我的思想脫離自己，<br/>好叫我的傾向都在乎你。<br/>',NULL,10318,10318);
INSERT INTO stanza VALUES('C583','3','惟主解開真理，我纔明白<br/>你的一切信息如何警策；<br/>使我與你同情，<br/>與你同行，<br/>使我逐日變化，<br/>像你榮形。<br/>',NULL,10319,10319);
INSERT INTO stanza VALUES('C583','4','愛主，求你祝福<br/>你的真理，<br/>像你為餅祝福在加利利；<br/>叫我捆綁都脫，<br/>鎖鍊都落，<br/>自由為你生活，<br/>為你工作。<br/>',NULL,10320,10320);
INSERT INTO stanza VALUES('C584','1','主，你沒有一句為我？<br/>使我更能向你信託，<br/>使我更能離開喜欲，<br/>一句，我主，求賜一句。<br/>',NULL,10321,10321);
INSERT INTO stanza VALUES('C584','2','一句來顯我的軟弱，<br/>當我欣賞自己工作；<br/>我空勞碌，我空歎吁，<br/>一句，我主，求賜一句。<br/>',NULL,10322,10322);
INSERT INTO stanza VALUES('C584','3','一句來示你的相親，<br/>因你乃是住在我心，<br/>你的生命我也同豫，<br/>一句，我主，求賜一句。<br/>',NULL,10323,10323);
INSERT INTO stanza VALUES('C584','4','一句，求將有力應許<br/>顯在許多畏懼、罣慮，<br/>你微而清所說話語，<br/>一句，我主，求賜一句。<br/>',NULL,10324,10324);
INSERT INTO stanza VALUES('C584','5','一句最終得勝呼喊，<br/>得你應許甘甜盤桓，<br/>與你永遠快樂同居，<br/>一句，我主，求賜一句。<br/>',NULL,10325,10325);
INSERT INTO stanza VALUES('C585','1','求主靜中發言，<br/>當我在等候；<br/>我心在此靜聽，<br/>望允我所求。<br/>',NULL,10326,10326);
INSERT INTO stanza VALUES('C585','2','恩主，求來發言，<br/>在這安靜時；<br/>讓我見你榮面，<br/>感到你所指。<br/>',NULL,10327,10327);
INSERT INTO stanza VALUES('C585','3','你所說的話語，<br/>是靈、是生命；<br/>天上來的活糧，<br/>將我靈供應。<br/>',NULL,10328,10328);
INSERT INTO stanza VALUES('C585','4','一切全都歸你，<br/>不再屬自己；<br/>甘心樂意降服，<br/>我只屬於你。<br/>',NULL,10329,10329);
INSERT INTO stanza VALUES('C585','5','請說，僕人敬聽，<br/>哦主，勿靜默；<br/>我靈向你仰望，<br/>活話願得著。<br/>',NULL,10330,10330);
INSERT INTO stanza VALUES('C585','6','用你豐富話語，<br/>將我心充滿；<br/>使你一切心願，<br/>在我得成全。<br/>',NULL,10331,10331);
INSERT INTO stanza VALUES('C585','7','像一灌溉花園，<br/>充滿了香氣，<br/>給你進來欣賞，<br/>滿足你心意。<br/>',NULL,10332,10332);
INSERT INTO stanza VALUES('C586','1','主阿，我心我靈<br/>又渴又飢，<br/>今來就你，<br/>求你給我供給；<br/>我所需要乃是你的自己，<br/>作我生命供應，<br/>作我能力。<br/>',NULL,10333,10333);
INSERT INTO stanza VALUES('C586','chorus','餧我飲我，主，<br/>餧我飲我！<br/>充我飢餓，主，<br/>解我乾渴！<br/>使我快樂，<br/>並且有力生活，<br/>餧我飲我，主，<br/>餧我飲我！<br/>',NULL,10334,10334);
INSERT INTO stanza VALUES('C586','2','你是我的食物、<br/>我的活水，<br/>你能解我飢渴，<br/>甦我困憊。<br/>我今願在這裡喫你喝你，<br/>藉著讀禱享受你的自己。<br/>',NULL,10335,10335);
INSERT INTO stanza VALUES('C586','3','你乃是話，<br/>藏著神的豐盛；<br/>你又是靈，<br/>就是神作生命。<br/>你今是話，<br/>作我食物可享；<br/>你今是靈，<br/>作我活水可嘗。<br/>',NULL,10336,10336);
INSERT INTO stanza VALUES('C586','4','為作食物，<br/>你已從天降下；<br/>為流活水，<br/>你也受了擊打。<br/>食物是你作了我的供應；<br/>活水是你為我所流之靈。<br/>',NULL,10337,10337);
INSERT INTO stanza VALUES('C586','5','你今是話，<br/>是靈也是生命，<br/>在這話裡，<br/>我能得你供應；<br/>你今是靈，<br/>住在我的靈裡，<br/>在這靈中，<br/>我能飲你自己。<br/>',NULL,10338,10338);
INSERT INTO stanza VALUES('C586','6','我今到這話裡來享受你；<br/>也要在這靈中來吸取你。<br/>願將你話喫飽，<br/>免得飢餓；<br/>願將你靈喝足，<br/>免得乾渴。<br/>',NULL,10339,10339);
INSERT INTO stanza VALUES('C586','7','但願我的讀經乃是喫你；<br/>也願我的禱告就是喝你。<br/>讀讀禱禱，<br/>我就將你喫飽；<br/>禱禱讀讀，<br/>也就將你喝了。<br/>',NULL,10340,10340);
INSERT INTO stanza VALUES('C586','8','但願你的自己作我筵席；<br/>你話你靈為我解渴充飢，<br/>使我得在這裡喫你喝你，<br/>豐豐滿滿享受你的自己。<br/>',NULL,10341,10341);
INSERT INTO stanza VALUES('C587','1','我今來到施恩座前，<br/>得你憐恤，蒙你恩典，<br/>作我所需應時幫助，<br/>使我心、靈得到安舒。<br/>',NULL,10342,10342);
INSERT INTO stanza VALUES('C587','2','在此瞻仰你的榮面，<br/>你的面光照我心間，<br/>放出你的醫治光線，<br/>消殺我的軟弱、缺點。<br/>',NULL,10343,10343);
INSERT INTO stanza VALUES('C587','3','在此你的亮光照明，<br/>顯示我的真實情形；<br/>你血也就顯出功能，<br/>將我罪污全都洗淨。<br/>',NULL,10344,10344);
INSERT INTO stanza VALUES('C587','4','你的膏油也在塗抹，<br/>你的成分給我得著；<br/>我就享受你的自己，<br/>也就摸著你的心意。<br/>',NULL,10345,10345);
INSERT INTO stanza VALUES('C587','5','我願在你面前讀經，<br/>猶如祭司聖所點燈；<br/>需要你靈像油一樣，<br/>使你話語放明發光。<br/>',NULL,10346,10346);
INSERT INTO stanza VALUES('C587','6','也願在此向你禱告，<br/>好像祭司將香焚燒；<br/>靈裡基督如香一般，<br/>調著禱告向神呈獻。<br/>',NULL,10347,10347);
INSERT INTO stanza VALUES('C587','7','你話是燈，也是食物，<br/>我蒙光照，也得飽足；<br/>深願在此多讀多喫，<br/>受到啟示，得著糧食。<br/>',NULL,10348,10348);
INSERT INTO stanza VALUES('C587','8','基督是香，也是活水，<br/>我蒙悅納，也脫困憊；<br/>也願在此多禱多喝，<br/>獻上香氣，流出江河。<br/>',NULL,10349,10349);
INSERT INTO stanza VALUES('C587','9','讀經使我明亮、不餓，<br/>禱告使我馨香、不渴；<br/>讀讀禱禱你就注入，<br/>禱禱讀讀你就流出。<br/>',NULL,10350,10350);
INSERT INTO stanza VALUES('C587','10','我願如此與你相交，<br/>讀禱、禱讀與你相調；<br/>也願如此給你浸透，<br/>直到你能從我湧流！<br/>',NULL,10351,10351);
INSERT INTO stanza VALUES('C588','1','主阿，我來就你，<br/>我心飢渴要你！<br/>深願在此喫你喝你，<br/>享受你的自己。<br/>',NULL,10352,10352);
INSERT INTO stanza VALUES('C588','2','得見你的面目，<br/>乃是我心所慕！<br/>甚願在此與你接觸，<br/>靈裡得著飽足。<br/>',NULL,10353,10353);
INSERT INTO stanza VALUES('C588','3','你的榮耀面光，<br/>我心何等欣賞！<br/>真願留此不再他往，<br/>一直向你瞻仰。<br/>',NULL,10354,10354);
INSERT INTO stanza VALUES('C588','4','在這交通裡面，<br/>你是我的恩典！<br/>使我心歡，使我靈滿，<br/>全人進入平安。<br/>',NULL,10355,10355);
INSERT INTO stanza VALUES('C588','5','還要在此等候，<br/>還要向你尋求！<br/>讀經、禱告交替不休，<br/>直到被你浸透！<br/>',NULL,10356,10356);
INSERT INTO stanza VALUES('C589','1','『活著不是單靠食物，<br/>乃靠神口所出的話；』<br/>因此須將神話當作<br/>生命之糧，時常喫下。<br/>',NULL,10357,10357);
INSERT INTO stanza VALUES('C589','2','我們受造非僅身體，<br/>乃是身體與魂與靈；<br/>靈是裡面最深部分，<br/>為著接受神作供應。<br/>',NULL,10358,10358);
INSERT INTO stanza VALUES('C589','3','正如我們身體需要<br/>屬地物質食物營養，<br/>靈也需要神的話語，<br/>作牠屬天生命食糧。<br/>',NULL,10359,10359);
INSERT INTO stanza VALUES('C589','4','主，你是靈，且藉你話<br/>將你自己完全表明；<br/>我今需要運用我靈，<br/>藉著你話接受你靈。<br/>',NULL,10360,10360);
INSERT INTO stanza VALUES('C589','5','因此，我們接受你話，<br/>非僅用眼讀其字句，<br/>並用心思領會其意，<br/>更須用靈將其吸取。<br/>',NULL,10361,10361);
INSERT INTO stanza VALUES('C589','6','須在靈裡喫你的話，<br/>將其接到最深部分；<br/>運用我靈禱讀你話，<br/>你就供應，浸透全人。<br/>',NULL,10362,10362);
INSERT INTO stanza VALUES('C589','7','你話留在我的心思，<br/>僅是知識，變作重擔；<br/>若被接受到我靈裡，<br/>就變靈與生命、平安。<br/>',NULL,10363,10363);
INSERT INTO stanza VALUES('C589','8','當我真肯運用我靈，<br/>接受你話並接觸你，<br/>我就得著你話餧養，<br/>深處摸著你的自己。<br/>',NULL,10364,10364);
INSERT INTO stanza VALUES('C589','9','哦主，教我每讀你話，<br/>就肯操練運用我靈，<br/>好使我靈得到餧養，<br/>你就作我生命供應。<br/>',NULL,10365,10365);
INSERT INTO stanza VALUES('C590','1','基督是話，祂也是靈，<br/>且是祂話裡面的靈；<br/>祂對我們所說的話，<br/>都是靈，也都是生命。<br/>',NULL,10366,10366);
INSERT INTO stanza VALUES('C590','2','神在外面賜我聖經，<br/>也在裡面賜我聖靈；<br/>二者是神極大禮物，<br/>使我享受神作供應。<br/>',NULL,10367,10367);
INSERT INTO stanza VALUES('C590','3','聖經乃藉聖靈表明，<br/>聖靈乃是聖經實際；<br/>二者乃是一物兩面，<br/>永遠不可彼此分離。<br/>',NULL,10368,10368);
INSERT INTO stanza VALUES('C590','4','聖經一經聖靈照亮，<br/>到我靈中就是生命；<br/>聖經若與聖靈分開，<br/>立變虛空，毫無供應。<br/>',NULL,10369,10369);
INSERT INTO stanza VALUES('C590','5','當我用靈接觸聖經，<br/>牠就變成靈作生命；<br/>當靈從我發表出去，<br/>又成為話將人供應。<br/>',NULL,10370,10370);
INSERT INTO stanza VALUES('C590','6','必須運用我們的靈，<br/>深處接受神的聖經；<br/>然後當靈釋放出去，<br/>靈、經乃一，在我證明。<br/>',NULL,10371,10371);
INSERT INTO stanza VALUES('C590','7','主，願你話在我裡面，<br/>能成為靈作我生命；<br/>並願你靈在你話裡，<br/>成為我的真實表明。<br/>',NULL,10372,10372);
INSERT INTO stanza VALUES('C591','1','神的話語非僅知識，<br/>更是生命賜給人；<br/>非僅傳遞神的思想，<br/>更是使人得著神；<br/>非僅啟示神的心意，<br/>更是帶來生命主；<br/>非僅供給一些教訓，<br/>更是供應主基督。<br/>',NULL,10373,10373);
INSERT INTO stanza VALUES('C591','2','我們若僅讀其字句，<br/>神話不過是知識；<br/>但若用靈將其禱讀，<br/>就是生命，真又實。<br/>所有字句、各種知識，<br/>只將死亡帶給我；<br/>惟有靈裡接受的話，<br/>供給生命使我活。<br/>',NULL,10374,10374);
INSERT INTO stanza VALUES('C591','3','只讀聖經，而不觸主，<br/>僅得虛空的知識；<br/>若在靈裡摸著基督，<br/>就得生命的美食。<br/>只讀字句，而不摸主，<br/>僅叫心思得供應；<br/>若用禱讀接觸基督，<br/>靈得豐盛的生命。<br/>',NULL,10375,10375);
INSERT INTO stanza VALUES('C591','4','聖經所有各種知識，<br/>都須變化成生命；<br/>頭腦所有各種領會，<br/>都須靈中再成形。<br/>對於聖經所有明白，<br/>都須生命的流通；<br/>對於字句所有認識，<br/>都須接受到靈中。<br/>',NULL,10376,10376);
INSERT INTO stanza VALUES('C591','5','接觸聖經為得知識，<br/>乃效夏娃之所為；<br/>撒但就是藉著知識，<br/>引誘女祖去犯罪。<br/>若當生命接受聖經，<br/>就是來喫生命樹；<br/>因此必須將主話語，<br/>接到靈裡作食物。<br/>',NULL,10377,10377);
INSERT INTO stanza VALUES('C592','1','我們享受基督豐富，<br/>就得成為祂的豐滿；<br/>分享一切祂之所是，<br/>就能使祂得著彰顯。<br/>',NULL,10378,10378);
INSERT INTO stanza VALUES('C592','2','基督豐富是祂所是，<br/>來作我們一切享受；<br/>基督豐滿乃是召會，<br/>因享基督而得成就。<br/>',NULL,10379,10379);
INSERT INTO stanza VALUES('C592','3','迦南美地豐富出產，<br/>乃是豫表基督豐富；<br/>藉這出產聖殿得成，<br/>象徵召會出於基督。<br/>',NULL,10380,10380);
INSERT INTO stanza VALUES('C592','4','夏娃乃是亞當豐滿，<br/>豫表召會之於基督；<br/>夏娃原是出於亞當，<br/>基督也是召會出處。<br/>',NULL,10381,10381);
INSERT INTO stanza VALUES('C592','5','豐富是我裡面基督，<br/>豐滿是我外面召會；<br/>充滿基督，作祂表現，<br/>得與基督同樣寶貴。<br/>',NULL,10382,10382);
INSERT INTO stanza VALUES('C593','1','神是人所不能見者，<br/>從未有人見過祂形；<br/>但有基督作祂奧祕，<br/>將祂向人全然表明。<br/>',NULL,10383,10383);
INSERT INTO stanza VALUES('C593','2','基督乃是神的活話，<br/>是神惟一真實說明；<br/>祂是神的具體化身，<br/>在祂得見神的本性。<br/>',NULL,10384,10384);
INSERT INTO stanza VALUES('C593','3','基督是神本體真像，<br/>是神榮耀所發光輝；<br/>神的豐滿住祂裡面，<br/>神之所是由祂發揮。<br/>',NULL,10385,10385);
INSERT INTO stanza VALUES('C593','4','基督現今也是隱瞞，<br/>地上今日無人能見；<br/>但有召會作祂奧祕，<br/>到處將祂顯於人前。<br/>',NULL,10386,10386);
INSERT INTO stanza VALUES('C593','5','召會是祂豐滿表現，<br/>祂是召會內容生命；<br/>召會是祂真實複本，<br/>祂藉召會向人顯明。<br/>',NULL,10387,10387);
INSERT INTO stanza VALUES('C593','6','召會具有基督形像，<br/>是祂擴增，是祂普及；<br/>祂之所是全在召會，<br/>召會乃是祂的身體。<br/>',NULL,10388,10388);
INSERT INTO stanza VALUES('C593','7','父神乃在子神裡面，<br/>子神且已成為那靈；<br/>現今這位三一神靈，<br/>是與召會合一同性。<br/>',NULL,10389,10389);
INSERT INTO stanza VALUES('C594','1','身體乃是人的豐滿，<br/>表現人生命；<br/>照樣，召會是主身體，<br/>使祂得顯明。<br/>',NULL,10390,10390);
INSERT INTO stanza VALUES('C594','2','夏娃乃是亞當一部，<br/>出自於亞當；<br/>召會也是基督擴增，<br/>出於祂肋旁。<br/>',NULL,10391,10391);
INSERT INTO stanza VALUES('C594','3','一粒麥子落地死了，<br/>結出許多粒；<br/>許多子粒磨粉相調，<br/>就成為一體。<br/>',NULL,10392,10392);
INSERT INTO stanza VALUES('C594','4','照樣基督死而復活，<br/>也得了繁生；<br/>許多信徒成為一身，<br/>來將祂表明。<br/>',NULL,10393,10393);
INSERT INTO stanza VALUES('C594','5','葡萄樹的許多枝子，<br/>乃是樹開展，<br/>與樹合一，住樹裡面，<br/>結果顯豐滿。<br/>',NULL,10394,10394);
INSERT INTO stanza VALUES('C594','6','照樣，基督許多肢體<br/>也是祂擴大，<br/>與祂成一，活在祂裡，<br/>使祂得發達。<br/>',NULL,10395,10395);
INSERT INTO stanza VALUES('C594','7','繁殖、擴增、<br/>開展、普及、<br/>長大與表現、<br/>複本、再世、<br/>繼續、富餘、<br/>擴大與豐滿：<br/>',NULL,10396,10396);
INSERT INTO stanza VALUES('C594','8','這是召會之於基督，<br/>使神得榮耀；<br/>藉著祂所救贖的人，<br/>永遠來顯照。<br/>',NULL,10397,10397);
INSERT INTO stanza VALUES('C594','9','乃是基督與祂召會－神的大奧祕；<br/>乃是神性與我人性，<br/>相調成為一。<br/>',NULL,10398,10398);
INSERT INTO stanza VALUES('C595','1','召會乃是基督器皿，<br/>將祂盛裝，將祂彰顯；<br/>猶如人的血肉身體，<br/>人在其中得著表現。<br/>',NULL,10399,10399);
INSERT INTO stanza VALUES('C595','2','如同聖殿之於約櫃，<br/>是其容器、安息之所；<br/>召會乃是基督住處，<br/>內容基督在她住著。<br/>',NULL,10400,10400);
INSERT INTO stanza VALUES('C595','3','基督乃是神的奧祕，<br/>將神解說，將神表現；<br/>召會也是基督奧祕，<br/>將祂言明，將祂彰顯。<br/>',NULL,10401,10401);
INSERT INTO stanza VALUES('C595','4','基督召會所有肢體，<br/>原都屬於泥土之類；<br/>所以需要重生變化，<br/>變為透明，成為寶貴。<br/>',NULL,10402,10402);
INSERT INTO stanza VALUES('C595','5','藉著變化同被建造，<br/>來作基督透明器皿；<br/>盛裝基督所有豐盛，<br/>將祂一切顯於人群。<br/>',NULL,10403,10403);
INSERT INTO stanza VALUES('C595','6','三一之神合作同工，<br/>完成所有變化工作；<br/>召會得成團體器皿，<br/>如同聖城作神居所。<br/>',NULL,10404,10404);
INSERT INTO stanza VALUES('C595','7','如此召會何其寶貴，<br/>各方都是透明、透亮；<br/>盛裝基督和神豐滿，<br/>照出基督和神榮光。<br/>',NULL,10405,10405);
INSERT INTO stanza VALUES('C595','8','神作亮光，主作生命，<br/>靈作活的生命水流；<br/>三一之神由她彰顯，<br/>顯於萬有直到永久！<br/>',NULL,10406,10406);
INSERT INTO stanza VALUES('C596','1','召會乃是精金燈臺，<br/>基督是燈，神是其光；<br/>神聖之光由主照出，<br/>召會托住，榮耀輝煌。<br/>',NULL,10407,10407);
INSERT INTO stanza VALUES('C596','2','燈中照出神聖之光，<br/>乃是神作生命照亮；<br/>因此燈臺須屬精金，<br/>配合神的聖別榮光。<br/>',NULL,10408,10408);
INSERT INTO stanza VALUES('C596','3','在這黑暗時代之中，<br/>神聖生命之光照亮，<br/>照在許多人群中心，<br/>將主見證向人釋放。<br/>',NULL,10409,10409);
INSERT INTO stanza VALUES('C596','4','要作這個純潔見證，<br/>『起初的愛』必須保守；<br/>如此，那得勝者之分－『生命樹果，』<br/>必得享受。<br/>',NULL,10410,10410);
INSERT INTO stanza VALUES('C596','5','必須忍受苦難、逼迫，<br/>纔能得著『生命冠冕；』<br/>屬靈淫亂也要勝過，<br/>『隱藏嗎哪』始得飽餐。<br/>',NULL,10411,10411);
INSERT INTO stanza VALUES('C596','6','棄絕『耶洗別』之所為，<br/>就能得著轄管之權；<br/>死的玷污要全勝過，<br/>潔義『白衣』就必得穿。<br/>',NULL,10412,10412);
INSERT INTO stanza VALUES('C596','7','必須如同『非拉鐵非，』<br/>遵守主話，不棄主名；<br/>『溫水』自滿，<br/>盡都勝過，<br/>與主同筵，享祂豐盛。<br/>',NULL,10413,10413);
INSERT INTO stanza VALUES('C596','8','召會必須如此純潔，<br/>成為明淨精金燈臺，<br/>配合主的純潔見證，<br/>照明基督，榮光滿載。<br/>',NULL,10414,10414);
INSERT INTO stanza VALUES('C596','9','地上各處地方召會，<br/>在這時代作這燈臺；<br/>將來聖城耶路撒冷，<br/>作這燈臺直到萬代。<br/>',NULL,10415,10415);
INSERT INTO stanza VALUES('C596','10','聖城寶貴如同精金，<br/>作主燈臺最終出現；<br/>永遠托著基督作燈，<br/>使神聖光照耀燦爛。<br/>',NULL,10416,10416);
INSERT INTO stanza VALUES('C597','1','神在永遠創世之前，<br/>喜悅、揀選並豫定，<br/>要叫召會在子裡面，<br/>得子名分成為聖；<br/>得蒙救贖，作祂產業，<br/>受祂聖靈為印記，<br/>保證必得祂的基業，<br/>並得先享祂自己。<br/>',NULL,10417,10417);
INSERT INTO stanza VALUES('C597','2','基督升天坐在神右，<br/>遠超一切的勢力；<br/>神使祂作萬有元首，<br/>召會是祂的身體。<br/>萬有一切祂全充滿，<br/>召會乃是祂豐滿，<br/>祂藉召會普及、曼延，<br/>召會彰顯祂完全。<br/>',NULL,10418,10418);
INSERT INTO stanza VALUES('C597','3','原是死在罪惡之中，<br/>隨從今世的風俗，<br/>撒但、邪靈竟也順從，<br/>放縱肉體真可怒。<br/>今與基督一同復活，<br/>一同坐在高天上，<br/>成為神的榮耀傑作，<br/>基督裡面所獨創。<br/>',NULL,10419,10419);
INSERT INTO stanza VALUES('C597','4','基督作了房角首石，<br/>使徒、先知為根基，<br/>照著神的奧祕啟示，<br/>猶太、外邦歸一體；<br/>在祂裡面同被建造，<br/>作神靈裡的居所；<br/>在靈裡面彼此相調，<br/>給神定居享安樂。<br/>',NULL,10420,10420);
INSERT INTO stanza VALUES('C597','5','神的奧祕乃是召會，<br/>神在永遠所計畫，<br/>為著彰顯祂的智慧，<br/>基督也可來安家。<br/>給眾聖徒明白基督，<br/>賞識基督的無限，<br/>知道祂愛超人領悟，<br/>充滿神性的豐滿。<br/>',NULL,10421,10421);
INSERT INTO stanza VALUES('C597','6','一身、一靈、同一指望，<br/>一主、一信並一洗，<br/>一位父神，眾人之上，<br/>召會因此當合一。<br/>認識基督，長大成人，<br/>有祂豐滿的身量；<br/>不再受到誘騙、牽引，<br/>不再隨風而飄蕩。<br/>',NULL,10422,10422);
INSERT INTO stanza VALUES('C597','7','基督賜下各樣恩賜，<br/>為要建造祂身體，<br/>成全聖徒各盡其職，<br/>愛中建造她自己。<br/>脫去舊人，穿上新人，<br/>再無從前的舊樣；<br/>心思靈裡得以更新，<br/>滿有主神的形像。<br/>',NULL,10423,10423);
INSERT INTO stanza VALUES('C597','8','基督捨己為愛召會，<br/>要使召會脫斑皺，<br/>聖潔，毫無瑕疵、污穢，<br/>作祂榮耀的配偶。<br/>祂愛召會，保養、顧惜，<br/>如待自己的身體；<br/>祂與召會成為一體，<br/>乃是極大的奧祕。<br/>',NULL,10424,10424);
INSERT INTO stanza VALUES('C597','9','身體、居所、<br/>新人、配偶，<br/>召會不僅是這些；<br/>也是戰士，為神爭鬥，<br/>將神仇敵全除滅。<br/>穿戴神的全副軍裝，<br/>賴主大能而剛強；<br/>靠主站住，靠靈抵擋，<br/>禱告隨時又多方。<br/>第七節的『心思靈裡，』意思是在心思的靈裡。<br/>',NULL,10425,10425);
INSERT INTO stanza VALUES('C598','1','召會是主的身體，<br/>也是神的居所；<br/>是眾聖徒的結集，<br/>也是神人調和；<br/>創世以前神所選，<br/>十架主死所贖；<br/>性質、地位全屬天，<br/>地上任何不屬。<br/>',NULL,10426,10426);
INSERT INTO stanza VALUES('C598','2','她是新造的新人，<br/>基督復活所生；<br/>聖靈裡面受了浸，<br/>藉道之洗成聖。<br/>基督是她的生命，<br/>又是她的元首；<br/>她與基督同性情，<br/>高升遠超萬有。<br/>',NULL,10427,10427);
INSERT INTO stanza VALUES('C598','3','她的根基已立定，<br/>乃是耶穌基督；<br/>能與基督同神聖，<br/>纔是她的事物。<br/>凡屬她者都需要<br/>經過十架妙死，<br/>在復活裡被建造，<br/>全是金、銀、寶石。<br/>',NULL,10428,10428);
INSERT INTO stanza VALUES('C598','4','她的元素全是一：<br/>一神、一主、一靈、<br/>一身、一信並一洗，<br/>一望，神所命定。<br/>三一之神在裡面，<br/>眾人成為一身，<br/>藉信聯結，因洗斷，<br/>憑望等候主臨。<br/>',NULL,10429,10429);
INSERT INTO stanza VALUES('C598','5','她的所有眾肢體，<br/>出自各方、各民，<br/>全都結合成為一，<br/>不分任何身分；<br/>沒有猶太或外邦，<br/>沒有自主、為奴，<br/>沒有卑下或高尚，<br/>只有新人『基督。』<br/>',NULL,10430,10430);
INSERT INTO stanza VALUES('C598','6','宇宙之中獨一個，<br/>分在各地出現；<br/>一地一會為原則，<br/>地方立場為限。<br/>地方行政雖獨立，<br/>各向元首負責，<br/>宇宙交通卻一體，<br/>無何離異間隔。<br/>',NULL,10431,10431);
INSERT INTO stanza VALUES('C598','7','她在各地的出現，<br/>都是撒冷雛形；<br/>為作基督的豐滿，<br/>先有聖城情景：<br/>基督是燈，神是光，<br/>她是燈臺照明，<br/>顯出榮耀的形像，<br/>直到撒冷完成。<br/>',NULL,10432,10432);
INSERT INTO stanza VALUES('C599','1','召會的種子，<br/>乃基督自己<br/>作生命子粒，<br/>撒在人心裡，<br/>要長成麥子，<br/>細麵能產出，<br/>作食物使<br/>神與人得滿足。<br/>',NULL,10433,10433);
INSERT INTO stanza VALUES('C599','2','但魔鬼卻來，<br/>把虛假信徒<br/>撒在聖徒中，<br/>使聖徒迷糊，<br/>像稗子阻礙<br/>麥子的生長，<br/>使麥子不能<br/>供神、人飽享。<br/>',NULL,10434,10434);
INSERT INTO stanza VALUES('C599','3','召會的生命<br/>應該像嫩菜，<br/>從那芥菜種<br/>－基督－長出來；<br/>暫時長地上，<br/>式微且不顯，<br/>卻可作食物，<br/>供飢者飽餐。<br/>',NULL,10435,10435);
INSERT INTO stanza VALUES('C599','4','但魔鬼卻來，<br/>使式微之菜<br/>改變了性質，<br/>也改了形態，<br/>而長成一棵<br/>顯耀的大樹，<br/>給許多惡者<br/>作棲身之處。<br/>',NULL,10436,10436);
INSERT INTO stanza VALUES('C599','5','魔鬼且利用<br/>變質的『召會，』<br/>帶進來外邦<br/>邪惡的俗規，<br/>如同將麵酵<br/>攙在細麵裡，<br/>敗壞其純潔，<br/>破壞神目的。<br/>',NULL,10437,10437);
INSERT INTO stanza VALUES('C599','6','但主作生命，<br/>要變化聖徒，<br/>使他們成為<br/>寶石和珍珠，<br/>作貴重材料，<br/>建造成召會，<br/>有國度之實，<br/>光榮又寶貴。<br/>',NULL,10438,10438);
INSERT INTO stanza VALUES('C599','7','靠主作生命，<br/>召會得生長，<br/>與基督調和，<br/>變成祂形像；<br/>像藏地寶貝<br/>和貴重珍珠，<br/>適合主建造，<br/>帶進神國度。<br/>',NULL,10439,10439);
INSERT INTO stanza VALUES('C599','8','求主從『稗子』<br/>將我們分出，<br/>救我們脫離<br/>那宗教『大樹，』<br/>從我們除去<br/>所有的『麵酵，』<br/>使得作食物，<br/>供神人需要。<br/>',NULL,10440,10440);
INSERT INTO stanza VALUES('C599','9','使我們生長<br/>在你生命裡，<br/>得以被變化<br/>建造成一體，<br/>作你的召會，<br/>彰顯你自己，<br/>叫你能得著<br/>國度的實際。<br/>',NULL,10441,10441);
INSERT INTO stanza VALUES('C600','1','聖徒實際活在一起，<br/>纔是召會的合一；<br/>內住聖靈將這合一<br/>放在所有聖徒裡。<br/>因是出於聖靈自己，<br/>故稱聖靈的合一；<br/>乃是根據所有聖徒<br/>同得之信而有的。<br/>',NULL,10442,10442);
INSERT INTO stanza VALUES('C600','2','所有聖徒共同所得<br/>一樣寶貴的信心，<br/>組成是以基督和祂<br/>救贖工作為成分。<br/>在此聖徒真是合一，<br/>信仰全同，無異議；<br/>由於這個同得之信，<br/>始有召會的存立。<br/>',NULL,10443,10443);
INSERT INTO stanza VALUES('C600','3','宇宙召會既然是一，<br/>作主基督的產業；<br/>各地召會也該是一，<br/>作主表現無分別。<br/>召會元素原都是一：<br/>一神、一主並一靈，<br/>一信、一洗並一身體，<br/>一望由於神命定。<br/>',NULL,10444,10444);
INSERT INTO stanza VALUES('C600','4','這『一』就是召會立場，<br/>聖徒共同的立場，<br/>就是合一獨一立場，<br/>聖靈在我所願望。<br/>藉此，召會就能實行<br/>真正實際的合一，<br/>她在各地所有出現<br/>也就因此得建立。<br/>',NULL,10445,10445);
INSERT INTO stanza VALUES('C600','5','主，使我們竭力保守<br/>這個聖靈的合一，<br/>站在召會合一立場，<br/>身體生活來經歷。<br/>使你心中偉大願望，<br/>因此就可得實現，<br/>使神心愛永遠計畫，<br/>也可完滿得成全。<br/>',NULL,10446,10446);
INSERT INTO stanza VALUES('C601','1','神子基督和<br/>祂救贖的工作，<br/>是我得救信仰，<br/>聖徒同守著；<br/>其他一切道理，<br/>不在信仰內，<br/>惟有基督工作，<br/>和祂的身位。<br/>',NULL,10447,10447);
INSERT INTO stanza VALUES('C601','2','此外一切教訓，<br/>若用之不當，<br/>就成『教訓之風』，<br/>使合一受傷；<br/>能從元首基督，<br/>將聖徒吹開，<br/>並不建造身體，<br/>反倒是毀壞。<br/>',NULL,10448,10448);
INSERT INTO stanza VALUES('C601','3','因此必須清除<br/>各種的道理，<br/>只是守住信仰，<br/>來實行合一。<br/>在基督那靈裡，<br/>我們確是一；<br/>只要保守這一，<br/>其他可放棄。<br/>',NULL,10449,10449);
INSERT INTO stanza VALUES('C601','4','真理－基督自己－我們須持守，<br/>如此就從宗派<br/>得蒙主拯救，<br/>並在凡事<br/>長到基督的裡面，<br/>身體就得建造，<br/>作主的豐滿。<br/>',NULL,10450,10450);
INSERT INTO stanza VALUES('C601','5','我們必須達到<br/>『信仰的合一』，<br/>所有『教訓之風』，<br/>永遠都離棄；<br/>靈中持守基督，<br/>作我們實際，<br/>好使身體增長，<br/>藉著這合一。<br/>',NULL,10451,10451);
INSERT INTO stanza VALUES('C602','1','主阿，你是房角首石，<br/>猶太匠人所輕棄；<br/>但你卻為神所珍視，<br/>從死復活所設立。<br/>我們靠你得蒙救恩，<br/>也得一同被建造；<br/>猶太、外邦成一新人，<br/>作神居所永和好。<br/>',NULL,10452,10452);
INSERT INTO stanza VALUES('C602','2','主，你也是屬靈磐石，<br/>非僅為解人乾渴，<br/>也非僅為給人倚恃，<br/>更是為造神居所。<br/>你是錫安所放基石，<br/>試過、穩固，神所立；<br/>也是召會所靠磐石，<br/>召會惟一的根基。<br/>',NULL,10453,10453);
INSERT INTO stanza VALUES('C602','3','召會建造在你身上，<br/>陰間之門難勝過；<br/>雖經各種風雨衝撞，<br/>仍然屹立不滅沒。<br/>召會在此有你權柄，<br/>捆綁你所要捆綁；<br/>帶進天國，驅逐邪靈，<br/>釋放你所要釋放。<br/>',NULL,10454,10454);
INSERT INTO stanza VALUES('C602','4','主，你更是生命活石，<br/>神所揀選、所寶貴，<br/>也使我們成為活石，<br/>與你同性、同地位；<br/>同被建造成為靈宮，<br/>就是祭司的體系，<br/>給神居住，對神事奉，<br/>獻上可悅的靈祭。<br/>',NULL,10455,10455);
INSERT INTO stanza VALUES('C602','5','主，你又是大衛苗裔，<br/>為要建造神聖殿；<br/>君王、祭司兩職合一，<br/>你就得盡你職權。<br/>你作君王為神掌權，<br/>權柄人就肯順服；<br/>你作祭司顯在神前，<br/>交通人就能進入。<br/>',NULL,10456,10456);
INSERT INTO stanza VALUES('C602','6','權柄出於神的寶座，<br/>使神子民能平定；<br/>交通來自生命水河，<br/>叫神子民得供應。<br/>權柄、交通平衡並行，<br/>建造進行纔可能；<br/>君王、祭司在你合併，<br/>神的建造得完成。<br/>',NULL,10457,10457);
INSERT INTO stanza VALUES('C602','7','你是神成肉身帳幕，<br/>是神榮耀的聖殿；<br/>神在你裡人間居住，<br/>在你裡面得彰顯。<br/>又是召會，神、人聯屬，<br/>充滿一切神豐滿；<br/>且是我們每個聖徒，<br/>為著建造神聖殿。<br/>',NULL,10458,10458);
INSERT INTO stanza VALUES('C602','8','哦，你還是永久居所，<br/>我們歷代的住處，<br/>在你裡面我們生活，<br/>得蒙永遠的遮護。<br/>你對我們也是聖所，<br/>神與我們的同在，<br/>我們和神共同生活，<br/>向神不斷的敬拜。<br/>',NULL,10459,10459);
INSERT INTO stanza VALUES('C602','9','角石、基石、磐石、<br/>活石、聖殿、召會、<br/>建造者、居所、聖所，<br/>你全都是，<br/>你是建造的一切！<br/>我們讚美你的所是，<br/>讚美你是何奇妙！<br/>但願我們這些活石，<br/>因你所是被建造！<br/>',NULL,10460,10460);
INSERT INTO stanza VALUES('C603','1','神，我讚美你的計畫，<br/>要使我們成為你家，<br/>給你安居，由你充滿，<br/>你在子裡好得彰顯。<br/>',NULL,10461,10461);
INSERT INTO stanza VALUES('C603','2','我們雖是你所創造，<br/>有你形像，作你代表，<br/>不過僅是土造陋器，<br/>裡面有靈，外面是體。<br/>',NULL,10462,10462);
INSERT INTO stanza VALUES('C603','3','惟有接受你作生命，<br/>纔能有你精金性情；<br/>你與我們調和為一，<br/>我們與你成為一體。<br/>',NULL,10463,10463);
INSERT INTO stanza VALUES('C603','4','當你生命流通、滋潤，<br/>浸透我的全心、全魂，<br/>我就變成珍珠、寶石，<br/>與你榮形一樣一式。<br/>',NULL,10464,10464);
INSERT INTO stanza VALUES('C603','5','但是，恩主，我們深知，<br/>這些並非為供賞識，<br/>乃是全為建造、配搭，<br/>成為你的榮耀之家。<br/>',NULL,10465,10465);
INSERT INTO stanza VALUES('C603','6','主，我在此獻上自己，<br/>求你接在建造手裡，<br/>將我折服，將我聯絡，<br/>造成你能安居之所。<br/>',NULL,10466,10466);
INSERT INTO stanza VALUES('C603','7','天然生命、孤僻性格，<br/>求你全都為我攻破，<br/>不再單獨，不再自善，<br/>與眾聖徒調成一團。<br/>',NULL,10467,10467);
INSERT INTO stanza VALUES('C603','8','如此纔能作你配偶，<br/>享受你愛所是所有，<br/>共同生活，互相安居，<br/>滿足你心，得你稱許。<br/>',NULL,10468,10468);
INSERT INTO stanza VALUES('C604','1','主，你不僅是陶人，<br/>更是榮耀建造主；<br/>不僅要把我陶甄，<br/>更是要把我建築。<br/>我也不僅是土人，<br/>更是新造的活石；<br/>不僅為作你器皿，<br/>更是為作你宮室。<br/>不僅為作你器皿，<br/>更是為作你宮室。<br/>',NULL,10469,10469);
INSERT INTO stanza VALUES('C604','2','你雖用土造我們，<br/>卻要我們能變質，<br/>有你生命的精金，<br/>變成珍珠與寶石。<br/>再經建造在一起，<br/>作你心愛的配偶，<br/>與你聯合成一體，<br/>給你佔有並享受。<br/>',NULL,10470,10470);
INSERT INTO stanza VALUES('C604','3','你心所愛並所要，<br/>非僅珍貴的材料，<br/>更要材料被建造，<br/>給你安居顯榮耀。<br/>你這萬有的基督，<br/>需要建造的召會，<br/>使你榮耀的豐富，<br/>顯出完全的光輝。<br/>',NULL,10471,10471);
INSERT INTO stanza VALUES('C604','4','並非單獨的屬靈，<br/>就能博得你稱羨；<br/>乃是團體的生命，<br/>纔能成全你心願。<br/>並非脫節的肢體，<br/>就能彰顯你完全；<br/>乃是配搭的身體，<br/>纔能成為你豐滿。<br/>',NULL,10472,10472);
INSERT INTO stanza VALUES('C604','5','求不再容我單獨，<br/>立即來把我建造；<br/>一切全照你藍圖，<br/>聯絡、結合，精而牢。<br/>屬靈不再為自高，<br/>恩賜不再為自傲；<br/>全都為供你建造，<br/>全都為顯你榮耀。<br/>',NULL,10473,10473);
INSERT INTO stanza VALUES('C605','1','求主向我吹氣，<br/>使我沉靈復起！<br/>脫離憂悒，勝過死寂，<br/>進入復興境地。<br/>',NULL,10474,10474);
INSERT INTO stanza VALUES('C605','2','求主向我吹氣，<br/>使我從新得力！<br/>作工不乏，行路不疲，<br/>展騰如駕雙翼。<br/>',NULL,10475,10475);
INSERT INTO stanza VALUES('C605','3','求主向我吹氣，<br/>使我進入安息！<br/>靈有所賴，心有所倚，<br/>因你充滿歡喜。<br/>',NULL,10476,10476);
INSERT INTO stanza VALUES('C605','4','求主向我吹氣，<br/>使我充滿了你！<br/>無論行動，或是起意，<br/>不再是我自己。<br/>',NULL,10477,10477);
INSERT INTO stanza VALUES('C605','5','求主向我吹氣，<br/>使我活在身體！<br/>同眾聖徒建造一起，<br/>永遠不再獨立。<br/>',NULL,10478,10478);
INSERT INTO stanza VALUES('C606','1','救我脫離自己、天然，<br/>主阿，我願被建造，<br/>同眾聖徒作你聖殿，<br/>為著充滿你榮耀。<br/>救我脫離乖僻個性，<br/>脫離驕傲與單獨；<br/>使我甘願服你權柄，<br/>讓你有家可居住。<br/>',NULL,10479,10479);
INSERT INTO stanza VALUES('C606','2','生命供應，活水流通，<br/>長進、變化又配搭；<br/>守住等次，盡我功用，<br/>成全別人，不踐踏。<br/>自己所經，自己所見，<br/>所是、所有並所能，<br/>不再高估，不再稍偏，<br/>接受一切的平衡。<br/>',NULL,10480,10480);
INSERT INTO stanza VALUES('C606','3','持定元首，聯絡供應，<br/>享受基督的豐富；<br/>充滿神的一切豐盛，<br/>因神增加得成熟，<br/>同嘗基督莫測大愛，<br/>賞識基督的闊長；<br/>長大成人，不作嬰孩，<br/>滿有基督的身量。<br/>',NULL,10481,10481);
INSERT INTO stanza VALUES('C606','4','作神居所，作你身體，<br/>主阿，我願被建造，<br/>成為你的團體大器，<br/>讓你來顯你榮耀。<br/>聖城景色、新婦榮美，<br/>今在此地就彰顯，<br/>透出你的榮耀光輝，<br/>將你照耀在人間。<br/>',NULL,10482,10482);
INSERT INTO stanza VALUES('C607','1','主阿，發言！<br/>主阿，吹氣！<br/>請看，枯骨遍滿全地！<br/>埋在墓中，離散死寂，<br/>求主發言並吹氣！<br/>',NULL,10483,10483);
INSERT INTO stanza VALUES('C607','2','主阿，發言，<br/>主阿，吹氣！<br/>吹進枯骨，使之復起，<br/>出離墳墓，脫開死地，<br/>求主發言並吹氣！<br/>',NULL,10484,10484);
INSERT INTO stanza VALUES('C607','3','主阿，發言，<br/>主阿，吹氣！<br/>使你子民活到一起，<br/>成為大軍，向敵攻擊，<br/>求主發言並吹氣！<br/>',NULL,10485,10485);
INSERT INTO stanza VALUES('C607','4','主阿，發言，<br/>主阿，吹氣！<br/>使你子民合而為一，<br/>權柄、帶領，不再互異，<br/>求主發言並吹氣！<br/>',NULL,10486,10486);
INSERT INTO stanza VALUES('C607','5','主阿，發言，<br/>主阿，吹氣！<br/>使你子民搭成一體，<br/>作你居所，使你安息，<br/>求主發言並吹氣！<br/>',NULL,10487,10487);
INSERT INTO stanza VALUES('C607','6','向我發言，向我吹氣！<br/>使我復甦，歸回身體，<br/>不再死寂，不再孤僻，<br/>主阿，現在就吹氣！<br/>',NULL,10488,10488);
INSERT INTO stanza VALUES('C607','7','向我發言，向我吹氣！<br/>願與眾聖進攻仇敵，<br/>使你居所早得建立，<br/>主阿，現在就吹氣！<br/>',NULL,10489,10489);
INSERT INTO stanza VALUES('C608','1','哦主，生命之氣向我吹！<br/>我如枯骨，脫節離散，<br/>需要你來復甦並帶回，<br/>使我活在身體裡面。<br/>',NULL,10490,10490);
INSERT INTO stanza VALUES('C608','2','哦主，生命之氣向我吹！<br/>我靈關閉，禁錮重重，<br/>需要你來釋放並解圍，<br/>使我調進身體靈中。<br/>',NULL,10491,10491);
INSERT INTO stanza VALUES('C608','3','哦主，生命之氣向我吹！<br/>我靈沉悶，不能展騰，<br/>需要你來復興並撫慰，<br/>使我得到身體供應。<br/>',NULL,10492,10492);
INSERT INTO stanza VALUES('C608','4','哦主，生命之氣向我吹！<br/>我靈虛空，無法飽足，<br/>需要你來充實並施惠，<br/>使我享受身體豐富。<br/>',NULL,10493,10493);
INSERT INTO stanza VALUES('C608','5','哦主，生命之氣向我吹！<br/>使我脫盡死枯、離散；<br/>死、散因素全給你摧毀，<br/>完全活在身體裡面。<br/>',NULL,10494,10494);
INSERT INTO stanza VALUES('C609','1','主，我寶貴你的藍圖，<br/>就是你所造的帳幕；<br/>說出你是如何建造，<br/>如何顯出你的榮耀。<br/>',NULL,10495,10495);
INSERT INTO stanza VALUES('C609','2','約櫃乃是帳幕中心，<br/>帳幕是給約櫃藏身；<br/>十條誡命放在約櫃，<br/>約櫃住在帳幕以內。<br/>',NULL,10496,10496);
INSERT INTO stanza VALUES('C609','3','約櫃豫表神人基督，<br/>神、人相調如金包木；<br/>十誡指神具體表現，<br/>完全住在基督裡面。<br/>',NULL,10497,10497);
INSERT INTO stanza VALUES('C609','4','基督也是召會中心，<br/>召會是給基督安身；<br/>神是住在基督裡面，<br/>基督住在召會中間。<br/>',NULL,10498,10498);
INSERT INTO stanza VALUES('C609','5','帳幕乃是約櫃擴大，<br/>金包木頭，同樣造法；<br/>召會也是基督擴充，<br/>神、人調和，完全相同。<br/>',NULL,10499,10499);
INSERT INTO stanza VALUES('C609','6','豎板相聯，搭成帳幕，<br/>立在銀座，基礎穩固；<br/>精金包裹，上帶金環，<br/>環內套閂，眾板相聯。<br/>',NULL,10500,10500);
INSERT INTO stanza VALUES('C609','7','召會也是聖徒集成，<br/>基督救贖上面立定；<br/>神性裡面聖靈聯繫，<br/>彼此配搭，建造一起。<br/>',NULL,10501,10501);
INSERT INTO stanza VALUES('C609','8','帳幕上蓋四層罩棚，<br/>豫表基督各種情形；<br/>這位基督顯神榮耀，<br/>將神居所完全遮罩。<br/>',NULL,10502,10502);
INSERT INTO stanza VALUES('C609','9','在這基督遮護之下，<br/>聖徒纔能彼此配搭；<br/>享受祂的一切功效，<br/>披祂戴祂，同被建造。<br/>',NULL,10503,10503);
INSERT INTO stanza VALUES('C609','10','十誡在櫃，櫃在帳幕，<br/>使神榮耀來此居住；<br/>神在主裡，主在召會，<br/>你這藍圖何其寶貴！<br/>',NULL,10504,10504);
INSERT INTO stanza VALUES('C610','1','釋放我靈！<br/>這是我心所要：<br/>使我能和眾人靈裡相調，<br/>不再單獨追求，<br/>不再假冒，<br/>完全脫離自己，<br/>適合建造。<br/>',NULL,10505,10505);
INSERT INTO stanza VALUES('C610','2','釋放我靈！<br/>這是我心所求：<br/>使我不再關閉，<br/>不再自囚；<br/>我在自己裡面，<br/>又深又久，<br/>現在非脫自己，<br/>不能自由！<br/>',NULL,10506,10506);
INSERT INTO stanza VALUES('C610','3','釋放我靈！<br/>這是我心所愛：<br/>從我自己裡面完全出來，<br/>好叫你的聖靈通行無礙，<br/>你就豐滿顯出你的同在！<br/>',NULL,10507,10507);
INSERT INTO stanza VALUES('C610','4','釋放我靈！<br/>這是我心所慕：<br/>使我脫離孤獨，<br/>脫離乾枯；<br/>已往自己追求，<br/>不過貧苦，<br/>今願脫離自己，<br/>得享豐富。<br/>',NULL,10508,10508);
INSERT INTO stanza VALUES('C610','5','釋放我靈！<br/>這是我心所願：<br/>使我識破詭計，<br/>不再受騙；<br/>不再自己為牢，<br/>坐井觀天，<br/>脫離狹小自己，<br/>進入無限！<br/>',NULL,10509,10509);
INSERT INTO stanza VALUES('C610','6','釋放我靈！<br/>這是我心所望：<br/>使我脫離自己，<br/>不受捆綁；<br/>與眾聖徒相調，<br/>剛強、明亮，<br/>享受你的一切，<br/>無量無疆！<br/>',NULL,10510,10510);
INSERT INTO stanza VALUES('C611','1','我今渴慕靈裡的交通！<br/>渴慕靈裡彼此相調，<br/>渴慕脫離單獨的作風，<br/>渴慕靈裡同被建造。<br/>',NULL,10511,10511);
INSERT INTO stanza VALUES('C611','2','我真渴慕靈裡的交通！<br/>渴慕靈能向人敞開，<br/>渴慕脫離孤僻的自封，<br/>渴慕靈能同人敬拜。<br/>',NULL,10512,10512);
INSERT INTO stanza VALUES('C611','3','我實渴慕靈裡的交通！<br/>渴慕靈能完全出來，<br/>渴慕脫離作怪的自崇，<br/>渴慕靈能勝過阻礙。<br/>',NULL,10513,10513);
INSERT INTO stanza VALUES('C611','4','我甚渴慕靈裡的交通！<br/>渴慕靈能同人禱告，<br/>渴慕脫離虛飾的兩層，<br/>渴慕靈能真實相交。<br/>',NULL,10514,10514);
INSERT INTO stanza VALUES('C611','5','我極渴慕靈裡的交通！<br/>渴慕交通平衡權柄，<br/>渴慕脫離事工的偏重，<br/>渴慕交通配合事奉。<br/>',NULL,10515,10515);
INSERT INTO stanza VALUES('C611','6','主阿，成全我們這心願！<br/>激動聖徒響應交通，<br/>使你建造快快的實現，<br/>你的計畫早日成功！<br/>',NULL,10516,10516);
INSERT INTO stanza VALUES('C612','1','何等福氣，何等權利，<br/>我是君尊的祭司！<br/>由神所選，為神所立，<br/>承擔尊榮的聖職。<br/>',NULL,10517,10517);
INSERT INTO stanza VALUES('C612','chorus','祭司職分何等尊榮，<br/>召會建造所倚恃；<br/>靈裡禱告，神前事奉，<br/>我願如此供聖職。<br/>',NULL,10518,10518);
INSERT INTO stanza VALUES('C612','2','我若守住君尊身分，<br/>權柄、等次不顛倒，<br/>並且肯盡祭司職分，<br/>召會纔能被建造。<br/>',NULL,10519,10519);
INSERT INTO stanza VALUES('C612','3','召會乃是祭司團體，<br/>祭司職分不可少；<br/>且須編成祭司體系，<br/>纔是真正被建造。<br/>',NULL,10520,10520);
INSERT INTO stanza VALUES('C612','4','因著召會墮落荒涼，<br/>祭司職分被忽視；<br/>因著聖徒靈不剛強，<br/>話語職事獨得勢。<br/>',NULL,10521,10521);
INSERT INTO stanza VALUES('C612','5','人多偏重先知講道，<br/>單靠話語的供應；<br/>很少倚重祭司禱告，<br/>在神面前運用靈。<br/>',NULL,10522,10522);
INSERT INTO stanza VALUES('C612','6','主阿，給我厲害平衡，<br/>倚重禱告如講道；<br/>對人常用禱告帶領，<br/>配同話語的教導。<br/>',NULL,10523,10523);
INSERT INTO stanza VALUES('C612','7','惟有如此事奉、禱告，<br/>叫人靈裡得相調，<br/>看重禱告猶如聽道，<br/>召會纔能被建造。<br/>',NULL,10524,10524);
INSERT INTO stanza VALUES('C613','1','建造召會的活石，<br/>乃是聖潔的祭司；<br/>若要活石被建造，<br/>必須祭司能禱告。<br/>',NULL,10525,10525);
INSERT INTO stanza VALUES('C613','chorus','必須常進至聖所，<br/>用靈摸神施恩座，<br/>禱告讓神能通過，<br/>纔有建造的工作。<br/>',NULL,10526,10526);
INSERT INTO stanza VALUES('C613','2','聖徒必須作祭司，<br/>纔能真正作活石；<br/>須有祭司的事奉，<br/>纔有活石的功能。<br/>',NULL,10527,10527);
INSERT INTO stanza VALUES('C613','3','舊約祭司與帳幕，<br/>總是相調在一處；<br/>祭司調在帳幕裡，<br/>帳幕、祭司成一體。<br/>',NULL,10528,10528);
INSERT INTO stanza VALUES('C613','4','新約祭司的團體，<br/>與神靈宮原是一；<br/>靈宮建造的實際，<br/>就是祭司的體系。<br/>',NULL,10529,10529);
INSERT INTO stanza VALUES('C613','5','召會建造的本質，<br/>就是祭司的聖職；<br/>祭司盡職常事奉，<br/>召會建造就完成。<br/>',NULL,10530,10530);
INSERT INTO stanza VALUES('C613','6','祭司神前的事奉，<br/>使人進入神交通；<br/>在神這一交通裡，<br/>聖徒建造在一起。<br/>',NULL,10531,10531);
INSERT INTO stanza VALUES('C613','7','惟有如此被建造，<br/>靈裡相調同禱告，<br/>成為祭司的體系，<br/>纔能向神獻靈祭。<br/>',NULL,10532,10532);
INSERT INTO stanza VALUES('C613','8','主阿，求你施恩惠，<br/>祭司聖職我寶貴！<br/>用靈事奉，多禱告，<br/>好叫召會被建造。<br/>',NULL,10533,10533);
INSERT INTO stanza VALUES('C614','1','靈能交流，恩主，<br/>靈能交流！<br/>我今切求，恩主，<br/>靈能交流！<br/>甚願一反已往，<br/>推倒鐵壁銅牆，<br/>靈能交流通暢，<br/>靈能交流！<br/>',NULL,10534,10534);
INSERT INTO stanza VALUES('C614','2','靈能交流，恩主，<br/>靈能交流！<br/>我今懇求，恩主，<br/>靈能交流！<br/>不再自滿自負，<br/>不再作繭自縛，<br/>靈能交流無阻，<br/>靈能交流！<br/>',NULL,10535,10535);
INSERT INTO stanza VALUES('C614','3','靈能交流，恩主，<br/>靈能交流！<br/>我今祈求，恩主，<br/>靈能交流！<br/>不再不凡自命，<br/>不再自覺聰明，<br/>靈能交流不停，<br/>靈能交流！<br/>',NULL,10536,10536);
INSERT INTO stanza VALUES('C614','4','靈能交流，恩主，<br/>靈能交流！<br/>我今尋求，恩主，<br/>靈能交流！<br/>不再自藏自隱，<br/>不再獨善己身，<br/>靈能交流日深，<br/>靈能交流！<br/>',NULL,10537,10537);
INSERT INTO stanza VALUES('C614','5','靈能交流，恩主，<br/>靈能交流！<br/>我今要求，恩主，<br/>靈能交流！<br/>打倒自持架格，<br/>走下作人寶座，<br/>流出活水江河，<br/>靈能交流！<br/>',NULL,10538,10538);
INSERT INTO stanza VALUES('C614','6','靈能交流，恩主，<br/>靈能交流！<br/>允我所求，恩主，<br/>靈能交流！<br/>切願能被建造，<br/>不但與你相交，<br/>且能與人相調，<br/>靈能交流！<br/>',NULL,10539,10539);
INSERT INTO stanza VALUES('C615','1','主，你居所何等可愛！<br/>我心渴慕你的院宇！<br/>切望得到你的同在，<br/>我的心腸向你呼籲。<br/>',NULL,10540,10540);
INSERT INTO stanza VALUES('C615','2','在你祭壇所在之處，<br/>並你香壇所在之所，<br/>麻雀找著可居房屋，<br/>燕子找著菢雛之窩。<br/>',NULL,10541,10541);
INSERT INTO stanza VALUES('C615','3','微弱雖如麻雀、燕子，<br/>住在你殿，便為有福！<br/>憑著祭壇贖罪價值，<br/>享受香壇所有好處。<br/>',NULL,10542,10542);
INSERT INTO stanza VALUES('C615','4','因著靠你而有力量，<br/>前途險阻毫不思顧，<br/>錫安大道心中想往，<br/>如此之人，便為有福。<br/>',NULL,10543,10543);
INSERT INTO stanza VALUES('C615','5','雖經巴迦，流淚之谷，<br/>亦使變成泉源之地，<br/>並且蓋滿秋雨之福，<br/>成為路中福分之一。<br/>',NULL,10544,10544);
INSERT INTO stanza VALUES('C615','6','他們行走，力上加力，<br/>要到錫安朝見主神；<br/>如此尋求你的自己，<br/>也需你來垂顧賜恩。<br/>',NULL,10545,10545);
INSERT INTO stanza VALUES('C615','7','在你院宇一日之留，<br/>勝住別處千日之久，<br/>寧在你殿看門守候，<br/>不在惡人帳棚住留。<br/>',NULL,10546,10546);
INSERT INTO stanza VALUES('C615','8','你是日頭，你是盾牌，<br/>你要賜下恩惠、榮耀，<br/>以你自己和你同在，<br/>滿足我的一切需要。<br/>',NULL,10547,10547);
INSERT INTO stanza VALUES('C615','9','你未留下一樣好處，<br/>不給行動正直的人；<br/>倚靠你的，便為有福，<br/>必得恩惠、榮耀無盡。<br/>',NULL,10548,10548);
INSERT INTO stanza VALUES('C616','1','主阿，我愛你的居所，<br/>就是你的召會！<br/>她是你心所喜所樂，<br/>也是我心所歸。<br/>',NULL,10549,10549);
INSERT INTO stanza VALUES('C616','2','你曾為她捨了自己，<br/>為要叫她歸你；<br/>我也為她獻上身體，<br/>成全你的心意。<br/>',NULL,10550,10550);
INSERT INTO stanza VALUES('C616','3','為她你作我的生命，<br/>叫她作我生活；<br/>為她我願脫去個性，<br/>讓她作你寄託。<br/>',NULL,10551,10551);
INSERT INTO stanza VALUES('C616','4','她是你的心愛配偶，<br/>也是你的身體；<br/>她是我的心情所投，<br/>也是我的憑倚。<br/>',NULL,10552,10552);
INSERT INTO stanza VALUES('C616','5','在她你是我所享受，<br/>成為我所見證；<br/>在她我給你所佔有，<br/>滿足你的心情。<br/>',NULL,10553,10553);
INSERT INTO stanza VALUES('C616','6','主阿，我愛你的居所，<br/>就是你的召會！<br/>我願永在其中生活，<br/>不再別有所歸。<br/>',NULL,10554,10554);
INSERT INTO stanza VALUES('C617','1','生命活物出於基督，<br/>同一生命，無法單獨；<br/>各方接受十架對付，<br/>就能活出團體基督。<br/>',NULL,10555,10555);
INSERT INTO stanza VALUES('C617','chorus','互相聯絡，彼此配搭，<br/>作主榮耀寄託；<br/>共同行動，同一步伐，<br/>帶進神的寶座。<br/>',NULL,10556,10556);
INSERT INTO stanza VALUES('C617','2','生活行動靠神恩力，<br/>不再自恃，不再自倚；<br/>以主誇口，以神為蔽，<br/>彰顯主神而非自己。<br/>',NULL,10557,10557);
INSERT INTO stanza VALUES('C617','3','單純無雜，正直不曲，<br/>靈中柔和，心裡謙虛；<br/>隨靈而行，無論何去，<br/>不從自己所好所欲。<br/>',NULL,10558,10558);
INSERT INTO stanza VALUES('C617','4','結得堅固，聯得合式，<br/>彼此成全，各盡各職；<br/>功用雖異，行動一致，<br/>成全神的榮耀啟示。<br/>',NULL,10559,10559);
INSERT INTO stanza VALUES('C617','5','如此配搭，聖火焚燒，<br/>污穢、雜質全都燒掉；<br/>聖火且成聖別光照，<br/>一舉一動亮光閃耀。<br/>',NULL,10560,10560);
INSERT INTO stanza VALUES('C617','6','神的大輪隨此而轉，<br/>活物得有清明之天；<br/>神的寶座藉此掌權，<br/>主的榮形在此彰顯。<br/>',NULL,10561,10561);
INSERT INTO stanza VALUES('C618','1','聖徒在基督裡，<br/>互相作肢體，<br/>成為一個身體，<br/>配搭在一起。<br/>',NULL,10562,10562);
INSERT INTO stanza VALUES('C618','2','恩賜雖有不同，<br/>聖靈是一位；<br/>職事雖有多種，<br/>主也是一位。<br/>',NULL,10563,10563);
INSERT INTO stanza VALUES('C618','3','誰也不能無誰，<br/>不可輕或重；<br/>各有各的地位，<br/>各有各功用。<br/>',NULL,10564,10564);
INSERT INTO stanza VALUES('C618','4','蒙恩有多有少，<br/>恩賜分大小；<br/>看得合乎中道，<br/>謙卑不自高。<br/>',NULL,10565,10565);
INSERT INTO stanza VALUES('C618','5','各盡各的職事，<br/>各顯各功用；<br/>個個都不鬆弛，<br/>個個都盡忠。<br/>',NULL,10566,10566);
INSERT INTO stanza VALUES('C618','6','互相供應聯繫，<br/>彼此多包容；<br/>毫無不諧嫌隙，<br/>凡事主為重。<br/>',NULL,10567,10567);
INSERT INTO stanza VALUES('C618','7','基督乃是元首，<br/>召會是身體；<br/>聖靈又是膏油，<br/>我們該是一。<br/>',NULL,10568,10568);
INSERT INTO stanza VALUES('C619','1','出於神性的活物，<br/>彰顯榮耀的基督；<br/>聯絡配搭成一體，<br/>完成神聖的旨意；<br/>隨從聖靈而行動，<br/>神的舉動就隨同。<br/>',NULL,10569,10569);
INSERT INTO stanza VALUES('C619','chorus','隨著活物的行蹤，<br/>神的大輪在轉動，<br/>動得可畏高而明，<br/>顯出恩主的榮形，<br/>神聖的計畫藉此完成。<br/>',NULL,10570,10570);
INSERT INTO stanza VALUES('C619','2','聖別烈火在焚燒，<br/>不潔、不聖全燒掉；<br/>聖火燒成聖別光，<br/>上下四方照明亮；<br/>一切行動在光中，<br/>神的舉動就隨同。<br/>',NULL,10571,10571);
INSERT INTO stanza VALUES('C619','3','隨從聖靈光中行，<br/>天就清明如水晶；<br/>能從無虧的良心，<br/>發出見證的聲音；<br/>如此發聲並靜聽，<br/>神的舉動得推行。<br/>',NULL,10572,10572);
INSERT INTO stanza VALUES('C619','4','在此纔有神居所，<br/>在此也有神寶座；<br/>神的權柄得施展，<br/>神的榮耀得彰顯；<br/>主在寶座像人形，<br/>周圍光輝如聖城。<br/>',NULL,10573,10573);
INSERT INTO stanza VALUES('C620','1','聖靈的大雲，<br/>聖別的烈火，<br/>顯出光耀精金神性；<br/>藉此，<br/>受造者得生而活著，<br/>神的生命顯於人形。<br/>',NULL,10574,10574);
INSERT INTO stanza VALUES('C620','2','生活如常人，<br/>雄壯似猛獅，<br/>勞役如牛，超脫似鷹；<br/>如此就活出基督的樣式，<br/>各方顯出祂的榮形。<br/>',NULL,10575,10575);
INSERT INTO stanza VALUES('C620','3','腳步無彎曲，<br/>行動有分別，<br/>新鮮、活潑、<br/>光明、燦爛；<br/>經過神鍛鍊，<br/>受過神純潔，<br/>成為人的亮光、審判。<br/>',NULL,10576,10576);
INSERT INTO stanza VALUES('C620','4','靠神能騰空，<br/>不為地拘留，<br/>作事仍具人形、人跡；<br/>以神為遮蔽，<br/>以主為誇口，<br/>彰顯主神，而非自己。<br/>',NULL,10577,10577);
INSERT INTO stanza VALUES('C620','5','靠著主恩力，<br/>接聯而配搭，<br/>各盡其職，不需轉調。<br/>焚燒如火炭，<br/>照明似火把，<br/>一舉一動亮光閃耀。<br/>',NULL,10578,10578);
INSERT INTO stanza VALUES('C620','6','隨從靈而行，<br/>就有神舉動，<br/>動得可畏，眼光豐盛；<br/>動中有主動，<br/>顯出主聖容，行動一致，<br/>動中有靈。<br/>',NULL,10579,10579);
INSERT INTO stanza VALUES('C620','7','天明如水晶，<br/>良心無攪擾，<br/>能以發聲，也能靜聽；<br/>發聲由配搭，<br/>使神得發表，<br/>也像軍隊將敵克征。<br/>',NULL,10580,10580);
INSERT INTO stanza VALUES('C620','8','天上的寶座，<br/>滿呈天景色，<br/>主在其上顯如人形：<br/>光耀如精金，<br/>聖別似烈火，<br/>周圍虹輝狀如聖城。<br/>',NULL,10581,10581);
INSERT INTO stanza VALUES('C621','1','福哉以愛聯繫，<br/>聖徒心心相契；<br/>彼此交通一情一意，<br/>真如在天無異。<br/>',NULL,10582,10582);
INSERT INTO stanza VALUES('C621','2','在父恩座之前，<br/>同心尋求眷憐；<br/>有望同盼，有苦同難，<br/>同憂、同樂、同安。<br/>',NULL,10583,10583);
INSERT INTO stanza VALUES('C621','3','軟弱彼此體諒，<br/>重擔互相擔當；<br/>人心傷，眾人淚淌，<br/>充滿同情心腸。<br/>',NULL,10584,10584);
INSERT INTO stanza VALUES('C621','4','每逢彼此分離，<br/>總是難免依依，<br/>但身雖離，靈仍一起，<br/>且有再會之期。<br/>',NULL,10585,10585);
INSERT INTO stanza VALUES('C621','5','盼望那日快顯，<br/>再無離別辛酸；<br/>相愛更親，相交更甜，<br/>同樂直到永遠。<br/>',NULL,10586,10586);
INSERT INTO stanza VALUES('C622','1','弟兄和睦同居，<br/>何等美善：<br/>像油從亞倫頭，<br/>流到衣衫；<br/>又像露從黑門，<br/>降在錫安；<br/>在此有生命福，<br/>直到永遠！<br/>',NULL,10587,10587);
INSERT INTO stanza VALUES('C622','2','心存歡喜誠實，<br/>來赴愛筵；<br/>藉此飽嘗主恩，<br/>滿心感讚！<br/>弟兄彼此交通，<br/>何等甘甜；<br/>盼望那日快到，<br/>不再離散。<br/>',NULL,10588,10588);
INSERT INTO stanza VALUES('C623','1','我們呼吸天上空氣，<br/>香味從天而來；<br/>但願每魂脫離肉體，<br/>每靈都充滿愛。<br/>',NULL,10589,10589);
INSERT INTO stanza VALUES('C623','2','主，使我們心心相聯，<br/>滿有聖潔情意，<br/>不至有日彼此改變，<br/>不愛你或你的。<br/>',NULL,10590,10590);
INSERT INTO stanza VALUES('C623','3','只受你的十架指引，<br/>服你所有旨意，<br/>能以彼此更為親近，<br/>能以更親近你。<br/>',NULL,10591,10591);
INSERT INTO stanza VALUES('C624','1','每逢聚集帶來基督，<br/>將祂所賜有餘豐富，<br/>同來獻上作神食物，<br/>如此展覽基督。<br/>',NULL,10592,10592);
INSERT INTO stanza VALUES('C624','chorus','前來展覽基督，<br/>前來展覽基督；<br/>共同帶來祂的豐富，<br/>前來展覽基督。<br/>',NULL,10593,10593);
INSERT INTO stanza VALUES('C624','2','憑祂生活，靠祂爭戰，<br/>在祂身上經營無間；<br/>藉祂豐富彼此結聯，<br/>為要展覽基督。<br/>',NULL,10594,10594);
INSERT INTO stanza VALUES('C624','3','凡我所是、所行、所歷，<br/>都是基督作我實際，<br/>好使我們每逢聚集，<br/>都能展覽基督。<br/>',NULL,10595,10595);
INSERT INTO stanza VALUES('C624','4','聚會為神帶來基督，<br/>彼此享受祂的豐富，<br/>且得與神同享基督，<br/>如此展覽基督。<br/>',NULL,10596,10596);
INSERT INTO stanza VALUES('C624','5','復活基督作神馨香，<br/>升天基督向神舉上，<br/>使神滿足供神欣賞，<br/>如此展覽基督。<br/>',NULL,10597,10597);
INSERT INTO stanza VALUES('C624','6','聚會中心、聚會實際、<br/>所有服事、所有空氣，<br/>除此之外別無目的，<br/>全為展覽基督。<br/>',NULL,10598,10598);
INSERT INTO stanza VALUES('C624','7','所有見證、所有禱告、<br/>所有靈中彼此相交、<br/>恩賜運用、一切教導，<br/>都為展覽基督。<br/>',NULL,10599,10599);
INSERT INTO stanza VALUES('C624','8','為使父神得榮稱許，<br/>為使基督得到高舉，<br/>並使聚會應付所需，<br/>必須展覽基督。<br/>',NULL,10600,10600);
INSERT INTO stanza VALUES('C625','1','主阿，我們聚集你前，<br/>求你賜給更深恩典，<br/>使我得著更豐生命，<br/>使我能作更美見證；<br/>恩主，這是我靈所求，<br/>我心所慕願你成就。<br/>',NULL,10601,10601);
INSERT INTO stanza VALUES('C625','2','在此多人靈裡乾燥，<br/>多人心裡需要光照；<br/>願你賜下恩膏滋潤，<br/>賜下恩光照亮人心，<br/>使人復興，愛你更深，<br/>使人自審，追求上進。<br/>',NULL,10602,10602);
INSERT INTO stanza VALUES('C625','3','願你使我裡面剛強，<br/>使我脫離外面捆綁；<br/>使我靈裡更有能力，<br/>使我心裡更脫自己；<br/>使你生命在我成形，<br/>使你旨意藉我通行。<br/>',NULL,10603,10603);
INSERT INTO stanza VALUES('C625','4','親愛的主，還要求你，<br/>賜下當初五旬能力，<br/>使人痛悔，覺得扎心，<br/>使人回轉，尋求你恩：<br/>病者得醫，暗者見光，<br/>受縛囚奴得著釋放。<br/>',NULL,10604,10604);
INSERT INTO stanza VALUES('C626','1','哦神，憑靈並憑實際，<br/>我們在此敬拜；<br/>照著你子基督所說，<br/>你前我們今來。<br/>',NULL,10605,10605);
INSERT INTO stanza VALUES('C626','2','感謝父神，你乃是靈，<br/>對我何親何近！<br/>使我憑靈與你接觸，<br/>並憑實際敬尊。<br/>',NULL,10606,10606);
INSERT INTO stanza VALUES('C626','3','你曾為我創造一靈，<br/>為使我能拜你；<br/>不需外面掙扎事奉，<br/>只需回到靈裡。<br/>',NULL,10607,10607);
INSERT INTO stanza VALUES('C626','4','你已用靈重生我靈，<br/>且作我的生命，<br/>還在將我心思更新，<br/>使我真能事奉。<br/>',NULL,10608,10608);
INSERT INTO stanza VALUES('C626','5','我們照著裡面感覺，<br/>在此向你敬拜；<br/>藉著你靈塗抹、運行，<br/>將你表明出來。<br/>',NULL,10609,10609);
INSERT INTO stanza VALUES('C626','6','憑著實際事奉敬拜，<br/>不再憑著影像；<br/>憑著基督，惟一實際，<br/>我們敬拜頌揚。<br/>',NULL,10610,10610);
INSERT INTO stanza VALUES('C626','7','我們向你獻上基督，<br/>就是我所經歷；<br/>與你同嘗祂的甘甜，<br/>欣賞祂的美麗。<br/>',NULL,10611,10611);
INSERT INTO stanza VALUES('C626','8','哦神，憑靈並憑實際，<br/>我們在此聚集，<br/>圍繞你的施恩寶座，<br/>敬拜、感讚不已。<br/>',NULL,10612,10612);
INSERT INTO stanza VALUES('C627','1','在日常生活或在聚會中，<br/>基督是中心，<br/>基督是內容；<br/>並非為儀式，<br/>也非為道理，<br/>純是為基督，<br/>我們相聚集。<br/>',NULL,10613,10613);
INSERT INTO stanza VALUES('C627','2','基督是道路，<br/>基督是亮光，<br/>憑祂而行動，<br/>由祂來照亮；<br/>基督是活水，<br/>基督是靈糧，<br/>喝祂並喫祂，<br/>從祂得餧養。<br/>',NULL,10614,10614);
INSERT INTO stanza VALUES('C627','3','基督是真理，<br/>我們所見證，<br/>基督是生命，<br/>我們所供應，<br/>基督是恩主，<br/>我們所稱譽，<br/>基督是元首，<br/>我們所高舉。<br/>',NULL,10615,10615);
INSERT INTO stanza VALUES('C627','4','對神或對人，<br/>基督是一切，<br/>神、人的需要<br/>全由祂解決；<br/>祂是召會的實際與內容，<br/>生命與人數都藉祂而增。<br/>',NULL,10616,10616);
INSERT INTO stanza VALUES('C627','5','所獻上一切詩歌和禱告，<br/>都要叫基督藉靈得發表；<br/>所有靈中的交通和事奉，<br/>都該是基督彰顯的運行。<br/>',NULL,10617,10617);
INSERT INTO stanza VALUES('C627','6','奉祂名聚集，<br/>隨祂靈活動，<br/>藉著祂恩膏禱告並讚頌；<br/>不是動頭腦，<br/>儀式得成全，<br/>乃是運用靈，<br/>使祂得彰顯。<br/>',NULL,10618,10618);
INSERT INTO stanza VALUES('C627','7','一切全忘掉，<br/>只忠於基督，<br/>凡事應用祂，<br/>一直到成熟；<br/>因祂將萬事都當作損失，<br/>讓祂作一切，<br/>一直到永世。<br/>',NULL,10619,10619);
INSERT INTO stanza VALUES('C628','1','靈要操練、運用，<br/>頭腦要拒絕，<br/>每逢我們聚集，<br/>以此為祕訣。<br/>',NULL,10620,10620);
INSERT INTO stanza VALUES('C628','2','靈要操練、運用，<br/>儀式全棄絕；<br/>彼此交通、分享，<br/>基督作一切。<br/>',NULL,10621,10621);
INSERT INTO stanza VALUES('C628','3','靈要操練、運用，<br/>情感要拋棄；<br/>彼此事奉、供應，<br/>基督是實際。<br/>',NULL,10622,10622);
INSERT INTO stanza VALUES('C628','4','靈要操練、運用，<br/>魂要全捨棄；<br/>彼此相助、聯絡，<br/>以主為憑倚。<br/>',NULL,10623,10623);
INSERT INTO stanza VALUES('C628','5','靈中得著釋放，<br/>脫開了自義；<br/>脫開自覺、自責，<br/>不再理自己。<br/>',NULL,10624,10624);
INSERT INTO stanza VALUES('C628','6','靈中得著釋放，<br/>脫開了己意；<br/>自愛、自驕、自榮，<br/>全都被貶抑。<br/>',NULL,10625,10625);
INSERT INTO stanza VALUES('C628','7','靈要操練、運用，<br/>取用主得勝；<br/>藉著洗罪寶血，<br/>並主大能名。<br/>',NULL,10626,10626);
INSERT INTO stanza VALUES('C628','8','靈要操練、運用，<br/>如此摸著主；<br/>用靈接觸主話，<br/>飽嘗主豐富。<br/>',NULL,10627,10627);
INSERT INTO stanza VALUES('C628','9','乃是藉著用靈，<br/>基督被見證；<br/>乃是藉著用靈，<br/>人們得供應。<br/>',NULL,10628,10628);
INSERT INTO stanza VALUES('C628','10','靈要操練、運用，<br/>這是我需要；<br/>靈要操練、運用，<br/>如此主引導。<br/>',NULL,10629,10629);
INSERT INTO stanza VALUES('C629','1','既是基督的肢體，<br/>就當彰顯基督；<br/>各都學習盡功用，<br/>顯出祂的豐富。<br/>不該作一旁觀者，<br/>該像肢體行動，<br/>不帶死亡或損傷，<br/>只帶有益交通。<br/>',NULL,10630,10630);
INSERT INTO stanza VALUES('C629','2','眾人乃是成一隊，<br/>永不單獨行動，<br/>乃是彼此相配搭，<br/>互相倚賴聽從；<br/>不照我們所揀選，<br/>乃隨生命水流，<br/>永不帶進分離來，<br/>只供聖靈所授。<br/>',NULL,10631,10631);
INSERT INTO stanza VALUES('C629','3','全都集中在基督，<br/>別無任何中心，<br/>共同交通於基督，<br/>分享祂的宏恩。<br/>祂是元首並內容，<br/>我們是祂豐滿；<br/>會中任何的活動，<br/>都當將祂彰顯。<br/>',NULL,10632,10632);
INSERT INTO stanza VALUES('C629','4','愛中一同被建造，<br/>無人隨意批評；<br/>彼此成全互擔就，<br/>都願照此而行。<br/>全蒙拯救脫自己，<br/>拒絕天然生命；<br/>藉恩靈中受過訓，<br/>活出身體事奉。<br/>',NULL,10633,10633);
INSERT INTO stanza VALUES('C630','1','為著你同在並你活的話，<br/>離去前，<br/>讚美還要向你發；<br/>我們已為你寶貴所吸引，<br/>你有力信息已抓住我心。<br/>',NULL,10634,10634);
INSERT INTO stanza VALUES('C630','2','你話對於我，<br/>是靈、是生命，<br/>使我得餧養，<br/>時將我供應；<br/>要將我變化，<br/>模成你形像，<br/>直到我成熟，<br/>滿有你身量。<br/>',NULL,10635,10635);
INSERT INTO stanza VALUES('C630','3','求將你自己，<br/>更多供應我，<br/>使我在靈裡行動並生活，<br/>並將我保守在你交通裡，<br/>直到藉你恩，<br/>我們再聚集。<br/>',NULL,10636,10636);
INSERT INTO stanza VALUES('C631','1','恩主，<br/>在我們尚未散會前，<br/>為著你榮耀、<br/>豐厚的顯現，<br/>並為你所賜新鮮的恩典，<br/>我們從心中再向你感讚。<br/>',NULL,10637,10637);
INSERT INTO stanza VALUES('C631','2','在你的恩中，<br/>聚會雖將完，<br/>但你的同在永遠不間斷；<br/>那在你靈裡維持的能力，<br/>因愛你必要不停的供給。<br/>',NULL,10638,10638);
INSERT INTO stanza VALUES('C631','3','願你的同在與我們同去，<br/>分擔我心中一切的罣慮，<br/>使我能時刻享受你自己，<br/>直到我有分再一次聚集。<br/>',NULL,10639,10639);
INSERT INTO stanza VALUES('C632','1','興起，興起，為基督，<br/>興起，十架精兵；<br/>舉起主旗揚威武，<br/>永遠將牠高撐。<br/>主必率領祂大軍，<br/>得勝而又得勝，<br/>直到仇敵全滅盡，<br/>人尊主名為聖。<br/>',NULL,10640,10640);
INSERT INTO stanza VALUES('C632','2','興起，興起，為基督，<br/>興起，聽主號令；<br/>走上疆場齊步武，<br/>靠主得勝大名。<br/>仇敵雖多，又兇險，<br/>也必向其進攻；<br/>越險，越攻，越勇敢，<br/>攻到仇敵消蹤。<br/>',NULL,10641,10641);
INSERT INTO stanza VALUES('C632','3','興起，興起，為基督，<br/>興起，靠主大力；<br/>莫靠自己而貽誤，<br/>莫用血氣兵器。<br/>穿上屬靈的軍裝，<br/>禱告隨時多方；<br/>無論何處需抵擋，<br/>都能隨靈前往。<br/>',NULL,10642,10642);
INSERT INTO stanza VALUES('C632','4','興起，興起，為基督，<br/>戰爭必不會長；<br/>今日殺聲雖高呼，<br/>明日凱歌必唱。<br/>凡是靠主得勝者，<br/>必得榮耀冠冕，<br/>必與基督同快樂，<br/>同王直到永遠。<br/>',NULL,10643,10643);
INSERT INTO stanza VALUES('C633','1','前進！基督精兵，<br/>前進！如出征；<br/>十架旌旗高撐，<br/>隨主向前行。<br/>前進！走上疆場，<br/>進攻諸幽冥；<br/>必將仇敵掃蕩，<br/>若聽主號令。<br/>',NULL,10644,10644);
INSERT INTO stanza VALUES('C633','chorus','前進！基督精兵，<br/>前進！如出征；<br/>十架旌旗高撐，<br/>隨主向前行。<br/>',NULL,10645,10645);
INSERT INTO stanza VALUES('C633','2','一聞耶穌大名，<br/>魔軍必竄逃；<br/>所以基督精兵，<br/>向前將敵剿。<br/>若肯高聲讚頌，<br/>陰間必動搖；<br/>所以親愛弟兄，<br/>讚頌聲要高。<br/>',NULL,10646,10646);
INSERT INTO stanza VALUES('C633','3','基督召會出征，<br/>勢如大軍隊：<br/>古聖在前先行，<br/>我們在後隨；<br/>並非分成兩起，<br/>古聖與我們；<br/>乃是一靈、一體、<br/>一望並一信。<br/>',NULL,10647,10647);
INSERT INTO stanza VALUES('C633','4','王位終必摧毀，<br/>邦國興而衰；<br/>惟有基督召會，<br/>永遠必存在。<br/>陰間權勢雖兇，<br/>不能勝召會；<br/>召會隨主進攻，<br/>必能毀魔鬼。<br/>',NULL,10648,10648);
INSERT INTO stanza VALUES('C633','5','前進！蒙恩聖徒，<br/>響應主召會；<br/>跟隨召會步武，<br/>必奏凱歌歸。<br/>榮耀、尊貴、頌揚，<br/>歸給得勝王；<br/>聖徒天使合唱，<br/>頌揚永無疆。<br/>',NULL,10649,10649);
INSERT INTO stanza VALUES('C634','1','衝過！戰士哪，衝過！<br/>前線正在開火；<br/>但各各他已得勝，<br/>請你常唱此歌。<br/>黑暗權勢應當退，<br/>撒但陰府已危！<br/>萬軍之主的元帥，<br/>快要奏凱歸回。<br/>',NULL,10650,10650);
INSERT INTO stanza VALUES('C634','2','『衝過！戰士哪，衝過！<br/>仰起你頭看我；<br/>你若為我打勝仗，<br/>必得登我寶座。』<br/>這是屬靈的交戰，<br/>不在屬世地場；<br/>主已知道仇敵迫，<br/>前後四圍佈滿！<br/>',NULL,10651,10651);
INSERT INTO stanza VALUES('C634','3','『衝過！戰士哪，衝過！<br/>你要登我寶座；<br/>使我復活的能力，<br/>會使你靈超脫。<br/>藉我你要得權能，<br/>藉我你要得勝，<br/>藉我你要唱凱歌，<br/>藉我你要高升。』<br/>',NULL,10652,10652);
INSERT INTO stanza VALUES('C634','4','『衝過！戰士哪，衝過！<br/>你要登我寶座；<br/>我已為你留一席，<br/>你要歡喜快樂。』<br/>我們與祂同復活，<br/>同升天上坐著，<br/>遠離戰場的喊聲，<br/>遠離綁人罪惡。<br/>',NULL,10653,10653);
INSERT INTO stanza VALUES('C634','5','衝過！戰士哪，衝過！<br/>你要登主寶座；<br/>主從灰塵揀選你，<br/>要你同祂得國。<br/>你的將來乃光明，<br/>不是黑暗灰心，<br/>永與耶穌在一起，<br/>永得祂的愛情。<br/>',NULL,10654,10654);
INSERT INTO stanza VALUES('C634','6','衝過！歡呼著衝過！<br/>前面就是寶座！<br/>你從郇山的高峰，<br/>可唱得勝新歌。<br/>被殺羔羊已得勝！<br/>登基羔羊已勝！<br/>我們歡呼讚美祂，<br/>因祂必定得勝。<br/>',NULL,10655,10655);
INSERT INTO stanza VALUES('C635','1','當你苦受撒但試探，<br/>四圍無處不黑暗，<br/>邪靈勸你稍為自循，<br/>將來冠冕聽命運；<br/>',NULL,10656,10656);
INSERT INTO stanza VALUES('C635','chorus','戰士哪，你就當站住！<br/>思念你的得勝主！<br/>耶穌已經勝過撒但，<br/>故當奮勇去爭戰。<br/>',NULL,10657,10657);
INSERT INTO stanza VALUES('C635','2','當你同伴逡巡、搖動，<br/>向你懷貳和敵通；<br/>你的鄉鄰譏你、欺你，<br/>竟然同敵聯一氣；<br/>',NULL,10658,10658);
INSERT INTO stanza VALUES('C635','3','當這世界用牠福樂，<br/>暗中為你張網羅，<br/>要藉虛榮、世俗、人情，<br/>使你狂放失信心；<br/>',NULL,10659,10659);
INSERT INTO stanza VALUES('C635','4','當你困於煩瑣事務，<br/>雖然勞碌無所補，<br/>損失、病痛，使你艱苦，<br/>身靈疲憊難擔負；<br/>',NULL,10660,10660);
INSERT INTO stanza VALUES('C635','5','不久，爭戰就要過去，<br/>撒但、邪靈要受拘；<br/>不久，召會要聽號聲，<br/>要得榮耀，要得勝。<br/>',NULL,10661,10661);
INSERT INTO stanza VALUES('C635','chorus','戰士哪，故你當站住！<br/>思念你的得勝主！<br/>耶穌已經勝過撒但，<br/>故當奮勇去爭戰。<br/>',NULL,10662,10662);
INSERT INTO stanza VALUES('C635','6','此後，我王就要凱旋，<br/>在這世界掌王權；<br/>此後，萬國都要歸順，<br/>頌揚耶穌並敬尊。<br/>',NULL,10663,10663);
INSERT INTO stanza VALUES('C636','1','邪惡之日要站住，<br/>人說甚麼不必顧，<br/>泥土之臉何必睹，<br/>站住，主精兵。<br/>',NULL,10664,10664);
INSERT INTO stanza VALUES('C636','2','站住因有神的話，<br/>站住，甘願出代價，<br/>追隨眾聖的步法，<br/>站住，主精兵。<br/>',NULL,10665,10665);
INSERT INTO stanza VALUES('C636','3','站住，勝過敵詭計，<br/>站住，不被樂所迷，<br/>站住，不為人所欺，<br/>站住，主精兵。<br/>',NULL,10666,10666);
INSERT INTO stanza VALUES('C636','4','站住，直到那日到，<br/>站住，因主，無所要，<br/>站住，儆醒且禱告，<br/>站住，主精兵。<br/>',NULL,10667,10667);
INSERT INTO stanza VALUES('C637','1','爭戰要在身體裡面，<br/>永勿單獨去迎敵；<br/>同著身體聯於元首，<br/>寶座之上將敵襲。<br/>',NULL,10668,10668);
INSERT INTO stanza VALUES('C637','chorus','爭戰要在身體裡面，<br/>藉著元首的功績；<br/>同著身體站得穩堅，<br/>你就必定得勝利。<br/>',NULL,10669,10669);
INSERT INTO stanza VALUES('C637','2','神的軍裝乃為身體，<br/>非為任何的個人；<br/>當你憑著身體爭戰，<br/>所有益處是你分。<br/>',NULL,10670,10670);
INSERT INTO stanza VALUES('C637','3','召會建在基督身上，<br/>陰府權勢難勝過；<br/>乃是身體得被建造，<br/>纔能抵擋眾惡魔。<br/>',NULL,10671,10671);
INSERT INTO stanza VALUES('C637','4','憑著身體，靠著元首，<br/>坐在諸天的境界，<br/>與執政者並眾惡魔，<br/>摔跤奮鬥不鬆懈。<br/>',NULL,10672,10672);
INSERT INTO stanza VALUES('C637','5','同眾弟兄為神站住，<br/>作主身上一肢體；<br/>靈中隨時多方禱告，<br/>靠著寶血取勝利。<br/>',NULL,10673,10673);
INSERT INTO stanza VALUES('C637','6','坐在天上得勝有餘，<br/>藉主力量的大能，<br/>在主裡面，同眾作戰，<br/>如同軍隊一兵丁。<br/>',NULL,10674,10674);
INSERT INTO stanza VALUES('C637','7','憑著身體向前進攻，<br/>惡者必由你征服；<br/>照神旨意捆綁、釋放，<br/>仇敵必作你食物。<br/>',NULL,10675,10675);
INSERT INTO stanza VALUES('C638','1','我神是我大能堡壘，<br/>堅固保障永不頹；<br/>致命兇惡雖在包圍，<br/>祂作幫助我何畏。<br/>我們老舊仇敵<br/>仍在尋隙攻擊，<br/>詭計、能力都大，<br/>又加狠心、毒辣，<br/>地上無人能抵他。<br/>',NULL,10676,10676);
INSERT INTO stanza VALUES('C638','2','我們若靠自己力量，<br/>奮鬥爭戰必失敗；<br/>神選之人豈非在旁？<br/>為何不將祂倚賴？<br/>這位適當之人，<br/>乃是基督本身；<br/>祂是萬軍之主，<br/>萬世萬代無殊，<br/>勝利永遠惟祂屬。<br/>',NULL,10677,10677);
INSERT INTO stanza VALUES('C638','3','世界雖然充滿鬼魔，<br/>常施驚嚇謀毀壞，<br/>但是我神定規藉我<br/>使祂真理得奏凱。<br/>名利都可遠離，<br/>生死我也不計；<br/>即使殺我身體，<br/>真理仍然屹立，<br/>神的國度永無已。<br/>',NULL,10678,10678);
INSERT INTO stanza VALUES('C639','1','如果爭戰兇猛，<br/>仇敵強盛，<br/>你當堅信主話，<br/>並發歌聲。<br/>',NULL,10679,10679);
INSERT INTO stanza VALUES('C639','2','只要呼喊一聲，<br/>就要得勝，<br/>不要啞口不作<br/>反抗見證。<br/>',NULL,10680,10680);
INSERT INTO stanza VALUES('C639','3','你靈現在鬱悶，<br/>好像無能，<br/>你若藉血禱告，<br/>就要高升。<br/>',NULL,10681,10681);
INSERT INTO stanza VALUES('C639','4','仇敵雖然蠻橫，<br/>你可與爭，<br/>如果堅守地位，<br/>不久就勝。<br/>',NULL,10682,10682);
INSERT INTO stanza VALUES('C639','5','所以應當發聲，<br/>證明主勝，<br/>光景雖然黑暗，<br/>但必變更。<br/>',NULL,10683,10683);
INSERT INTO stanza VALUES('C640','1','我對撒但總是說：<br/>『不，』<br/>我對父神就說：『是！』<br/>好叫我主所有部署，<br/>全得成功不受阻。<br/>當我這樣聽主號令，<br/>求主賜給我權柄，<br/>使我滿有能力聖靈，<br/>成功主永遠定命。<br/>',NULL,10684,10684);
INSERT INTO stanza VALUES('C640','2','我對撒但總是說：<br/>『不，』<br/>我對父神就說：『是！』<br/>這個是我永遠態度，<br/>求神施恩加保護。<br/>不然當我實行順服，<br/>撒但就要攔去路；<br/>當我正在聽你吩咐，<br/>主耶穌，求你看顧！<br/>',NULL,10685,10685);
INSERT INTO stanza VALUES('C640','3','我對撒但總是說：<br/>『不，』<br/>我對父神就說：『是！』<br/>我願完全絕對順服，<br/>不論將受如何苦。<br/>當我與主同前時候，<br/>主若肯拯救保守，<br/>無論甚麼威脅、引誘，<br/>不會使我一回頭。<br/>',NULL,10686,10686);
INSERT INTO stanza VALUES('C641','1','今日戰爭兇猛，<br/>仇敵更強；<br/>戰場呼喊之聲<br/>比前響亮！<br/>陰府反抗之聲<br/>比前厲害！<br/>卻有半夜呼聲：<br/>『我必快來！』<br/>',NULL,10687,10687);
INSERT INTO stanza VALUES('C641','2','今日試煉更苦，<br/>交戰益烈；<br/>陰府一齊鼓舞，<br/>集隊來劫；<br/>我在此處守等，<br/>更難得勝；<br/>卻聽喜樂之聲：<br/>『耶穌已近！』<br/>',NULL,10688,10688);
INSERT INTO stanza VALUES('C641','3','更難證實主話，<br/>在此末世，<br/>因為撒但攻打，<br/>竭其權勢；<br/>我需更大靈力，<br/>纔會敗敵；<br/>主來不再歎息，<br/>何等樂呢！<br/>',NULL,10689,10689);
INSERT INTO stanza VALUES('C641','4','誰願一直前進，<br/>藉主大能？<br/>誰要堅定相信，<br/>以至得勝？<br/>誰要靠主壯心，<br/>以至奏凱？<br/>如此之人樂聽：<br/>『我必快來！』<br/>',NULL,10690,10690);
INSERT INTO stanza VALUES('C641','5','誰選神的最好－十架窄路，<br/>歷盡百般苦惱，<br/>並不回顧？<br/>誰敢奮勇直前，<br/>忍苦、受驚？<br/>因在此時可見：<br/>『耶穌已近！』<br/>',NULL,10691,10691);
INSERT INTO stanza VALUES('C641','6','現今黑暗深厚，<br/>我們當前，<br/>直至被提時候，<br/>光明纔現！<br/>在彼我們見主，<br/>仇敵已敗，<br/>得勝者同歡呼：<br/>『耶穌已來！』<br/>',NULL,10692,10692);
INSERT INTO stanza VALUES('C642','1','當奉耶穌這名站住，<br/>信祂得勝站住；<br/>不靠自己力量站住，<br/>不靠才能站住；<br/>不要使用血氣兵器，<br/>只用聖靈寶劍；<br/>穿上神的軍裝服役，<br/>滅盡仇敵火箭。<br/>',NULL,10693,10693);
INSERT INTO stanza VALUES('C642','2','看哪，仇敵正在聚集，<br/>故當守你地場！<br/>四面黑暗，爭戰緊急，<br/>故當靠主抵擋！<br/>你若退後，怕仇敵兇，<br/>一人牽動全軍；<br/>請你不要使你弟兄，<br/>因你緣故受窘。<br/>',NULL,10694,10694);
INSERT INTO stanza VALUES('C642','3','撒但已知其時不久，<br/>所以其氣忿忿，<br/>要在爭戰尚未起首，<br/>就使你靈鬱悶。<br/>誘惑、試探比前更多，<br/>苦難比前更大，<br/>陰府權勢攻逼你我，<br/>比前更為可怕。<br/>',NULL,10695,10695);
INSERT INTO stanza VALUES('C642','4','對此情形，我們當有<br/>何種態度纔可？<br/>我們可否因貪優游，<br/>便讓仇敵宰割？<br/>或者因著苦難加倍，<br/>更加忍耐、奮勇？<br/>生死關頭在此定規！<br/>誰要得主稱榮？<br/>',NULL,10696,10696);
INSERT INTO stanza VALUES('C642','5','因此，你當為主站住；<br/>耶穌是得勝者！<br/>你當忍受一切痛苦，<br/>直到那日方捨。<br/>耶穌不久快要再臨，<br/>戰事不久要停；<br/>你今為主受難、受驚，<br/>那日必得權柄。<br/>',NULL,10697,10697);
INSERT INTO stanza VALUES('C643','1','得勝、得勝，阿利路亞！<br/>得勝、得勝，阿利路亞！<br/>得勝、得勝，阿利路亞！<br/>基督已經得勝！<br/>',NULL,10698,10698);
INSERT INTO stanza VALUES('C643','2','得勝、得勝，阿利路亞！<br/>得勝、得勝，阿利路亞！<br/>得勝、得勝，阿利路亞！<br/>基督使我得勝！<br/>',NULL,10699,10699);
INSERT INTO stanza VALUES('C643','3','榮耀、榮耀，阿利路亞！<br/>榮耀、榮耀，阿利路亞！<br/>榮耀、榮耀，阿利路亞！<br/>榮耀歸於主名！<br/>',NULL,10700,10700);
INSERT INTO stanza VALUES('C644','1','阿利路亞，耶穌得勝！<br/>大聲唱凱歌！<br/>耶穌得勝，仍舊得勝，<br/>勝過罪、死、魔！<br/>',NULL,10701,10701);
INSERT INTO stanza VALUES('C644','chorus','阿利路亞，耶穌得勝！<br/>榮耀的消息！<br/>耶穌得勝，仍舊得勝，<br/>勝過眾仇敵！<br/>',NULL,10702,10702);
INSERT INTO stanza VALUES('C644','2','阿利路亞，耶穌得勝！<br/>寶血有能力！<br/>仗祂十架，時時誇勝，<br/>魔鬼就逃匿。<br/>',NULL,10703,10703);
INSERT INTO stanza VALUES('C644','3','阿利路亞，耶穌得勝！<br/>疾病也消殺！<br/>因藉耶穌，完全得勝，<br/>成於各各他。<br/>',NULL,10704,10704);
INSERT INTO stanza VALUES('C644','4','阿利路亞，耶穌得勝！<br/>故剛強有為！<br/>無論何處，祂有遣徵，<br/>當應命勿畏。<br/>',NULL,10705,10705);
INSERT INTO stanza VALUES('C644','5','阿利路亞，耶穌得勝！<br/>勿懼，勿讓步！<br/>前途縱有黑暗權能，<br/>耶穌必開路。<br/>',NULL,10706,10706);
INSERT INTO stanza VALUES('C644','6','阿利路亞，耶穌得勝！<br/>耶穌快再臨！<br/>所有同祂得勝的人，<br/>前來同歡欣！<br/>',NULL,10707,10707);
INSERT INTO stanza VALUES('C645','1','天上地下所有權柄，<br/>都已賜給復活基督；<br/>與祂聯合，靠祂生命，<br/>所有仇敵都要屈服。<br/>',NULL,10708,10708);
INSERT INTO stanza VALUES('C645','2','你當藉主說你必定<br/>勝過魔鬼一切能力！<br/>應當從主支取權柄，<br/>踐踏地上蛇頭、龍體。<br/>',NULL,10709,10709);
INSERT INTO stanza VALUES('C645','3','管你甚麼，你這高山！<br/>管你那裡，或天或地！<br/>無論如何我總要剷，<br/>奉主的名，你當快離！<br/>',NULL,10710,10710);
INSERT INTO stanza VALUES('C645','4','信心命你離開此地，<br/>你當順服投在海裡！<br/>我當、我要、我能、<br/>我必成功我神所有目的。<br/>',NULL,10711,10711);
INSERT INTO stanza VALUES('C646','1','要藉基督得勝寶血，<br/>勝過兇惡的仇敵；<br/>藉其功效和其能力，<br/>你就必定得勝利。<br/>',NULL,10712,10712);
INSERT INTO stanza VALUES('C646','chorus','要藉基督得勝寶血，<br/>勝過兇惡的仇敵；<br/>藉其功效和其能力，<br/>你就必定得勝利。<br/>',NULL,10713,10713);
INSERT INTO stanza VALUES('C646','2','要藉基督得勝寶血，<br/>抵擋狡詐控告者；<br/>藉這為你辯護之血，<br/>拒絕讒者的指責。<br/>',NULL,10714,10714);
INSERT INTO stanza VALUES('C646','3','要藉基督得勝寶血，<br/>信神可靠的信實；<br/>因這為你贖罪之血，<br/>神的赦免早已賜。<br/>',NULL,10715,10715);
INSERT INTO stanza VALUES('C646','4','要藉基督得勝寶血，<br/>現今宣告你地位；<br/>藉這永遠得勝之血，<br/>迫使仇敵全敗退。<br/>',NULL,10716,10716);
INSERT INTO stanza VALUES('C646','5','要藉基督得勝寶血，<br/>完全取用祂權柄；<br/>只要應用耶穌之血，<br/>你就必定能得勝。<br/>',NULL,10717,10717);
INSERT INTO stanza VALUES('C646','6','要藉基督得勝寶血，<br/>坐在屬天的境界；<br/>藉著升天基督權能，<br/>將你仇敵全繳械。<br/>',NULL,10718,10718);
INSERT INTO stanza VALUES('C647','1','你願否作主得勝者？<br/>主正在呼召！<br/>願否作主忠心從者，<br/>路雖不盡曉？<br/>',NULL,10719,10719);
INSERT INTO stanza VALUES('C647','chorus','你願否作主得勝者，<br/>滿足主心願？<br/>主在呼召，主在呼召，<br/>要你得冠冕！<br/>',NULL,10720,10720);
INSERT INTO stanza VALUES('C647','2','你願否作主得勝者？<br/>要受主吸引；<br/>『起初的愛』總不離棄，<br/>直到那早晨。<br/>',NULL,10721,10721);
INSERT INTO stanza VALUES('C647','3','你願否作主得勝者？<br/>倚靠主『生命』；<br/>敢為主受逼迫、苦難，<br/>至死不變更。<br/>',NULL,10722,10722);
INSERT INTO stanza VALUES('C647','4','你願否作主得勝者？<br/>要作主見證；<br/>若肯如此，『隱藏嗎哪』<br/>必作你供應。<br/>',NULL,10723,10723);
INSERT INTO stanza VALUES('C647','5','你願否作主得勝者，<br/>單純又真誠？<br/>勝過所有邪惡混雜，<br/>必得主『權柄』。<br/>',NULL,10724,10724);
INSERT INTO stanza VALUES('C647','6','你願否作主得勝者？<br/>信賴活的主；<br/>使你『衣服』不沾死污，<br/>得生命祝福。<br/>',NULL,10725,10725);
INSERT INTO stanza VALUES('C647','7','你願否作主得勝者？<br/>切勿棄主名！<br/>遵守『主的忍耐之道』，<br/>盡上你所能。<br/>',NULL,10726,10726);
INSERT INTO stanza VALUES('C647','8','你願否作主得勝者？<br/>勿『不冷不熱』；<br/>切勿滿意於你所有，<br/>需更有所得。<br/>',NULL,10727,10727);
INSERT INTO stanza VALUES('C647','9','你願否作主得勝者？<br/>主仍在呼召！<br/>願否立即對祂赤誠，<br/>成全祂所要？<br/>',NULL,10728,10728);
INSERT INTO stanza VALUES('C648','1','我不敢稍微失敗，<br/>因有加略在望，<br/>耶穌在彼曾奏凱，<br/>勝過黑暗君王；<br/>求主賜給我異象，<br/>我纔臨陣奮興，<br/>使我作個得勝者，<br/>靠著你的大能。<br/>',NULL,10729,10729);
INSERT INTO stanza VALUES('C648','chorus','得勝，得勝者，<br/>都因著髑髏地。<br/>使我作個得勝者，<br/>因著你，因著你能得勝。<br/>',NULL,10730,10730);
INSERT INTO stanza VALUES('C648','2','我不敢稍微失敗，<br/>因為基督我主，<br/>召我進到前線來，<br/>與祂一同追逐。<br/>求主賜給我膽量，<br/>使我剛強有力，<br/>使我作個得勝者，<br/>裡面充滿了你。<br/>',NULL,10731,10731);
INSERT INTO stanza VALUES('C648','3','我不敢稍微失敗，<br/>因為耶穌領我<br/>來衝陰府的境界，<br/>與祂同登寶座。<br/>求主賜給你戰士，<br/>有力能以揮劍，<br/>使我作個得勝者，<br/>藉著你的聖言。<br/>',NULL,10732,10732);
INSERT INTO stanza VALUES('C648','4','我不敢稍微失敗，<br/>當此日西時辰，<br/>因為我主正等待，<br/>要說『好！我僕人。』<br/>求主今日從天上，<br/>從新賜我能力，<br/>使我作個得勝者，<br/>得勝一直到底。<br/>',NULL,10733,10733);
INSERT INTO stanza VALUES('C649','1','撒但早已定規抵敵<br/>我神的後裔；<br/>從軍的召會，當注意！<br/>你已得消息！<br/>',NULL,10734,10734);
INSERT INTO stanza VALUES('C649','chorus','主留我們今日在世，<br/>原是為爭戰；<br/>所以若要成功神旨，<br/>就須上疆場。<br/>',NULL,10735,10735);
INSERT INTO stanza VALUES('C649','2','黑暗軍兵已經聚集，<br/>他們已逼近；<br/>從軍的召會，當奮起！<br/>你是主親兵！<br/>',NULL,10736,10736);
INSERT INTO stanza VALUES('C649','3','奈何主營也有背叛？<br/>是誰愛世俗？<br/>從軍的召會不爭戰，<br/>怎能跟從主？<br/>',NULL,10737,10737);
INSERT INTO stanza VALUES('C649','4','怎樣竟有懦夫<br/>不敢向仇敵挑戰？<br/>從軍的召會何羞慚，<br/>竟畏勢偷安！<br/>',NULL,10738,10738);
INSERT INTO stanza VALUES('C649','5','若非為我，便是助敵，<br/>此間無兩可；<br/>從軍的召會，你到底<br/>是與誰聯合？<br/>',NULL,10739,10739);
INSERT INTO stanza VALUES('C649','6','那得勝者仍然得勝，<br/>當享祂功績；<br/>從軍的召會，當承認<br/>加略是為你。<br/>',NULL,10740,10740);
INSERT INTO stanza VALUES('C649','7','我們的主原是戰士，<br/>故當不避危，<br/>否則那裡還能算是<br/>從軍的召會！<br/>',NULL,10741,10741);
INSERT INTO stanza VALUES('C649','8','主今呼召，要得勝者，<br/>誰站主一邊？<br/>從軍的召會，勿耽擱，<br/>甲冑上前線。<br/>',NULL,10742,10742);
INSERT INTO stanza VALUES('C650','1','不是我們隨意走，<br/>乃是隨主的引領；<br/>那裡活水方湧流，<br/>那裡心中方光明。<br/>',NULL,10743,10743);
INSERT INTO stanza VALUES('C650','2','不是自擇的工作，<br/>就能博得祂嘉許；<br/>乃是完成祂委託，<br/>纔可領受祂稱譽。<br/>',NULL,10744,10744);
INSERT INTO stanza VALUES('C650','3','不是我們隨自己，<br/>就能座前獻禱告；<br/>乃是那靈的歎息，<br/>摸著更深的需要。<br/>',NULL,10745,10745);
INSERT INTO stanza VALUES('C650','4','如果我們答應『不』，<br/>當祂輕說『我需要』，<br/>就是壇上有禮物，<br/>也不能使祂稱好。<br/>',NULL,10746,10746);
INSERT INTO stanza VALUES('C650','5','我們如此向己死，<br/>與祂一同活天上，<br/>如此奉獻而服事，<br/>祂將自己作恩賞。<br/>',NULL,10747,10747);
INSERT INTO stanza VALUES('C651','1','主要我事奉祂的所在，<br/>未必是遠隔重洋，<br/>未必是在高山的巉崖，<br/>或在危險的異鄉；<br/>但是祂若微聲召我去<br/>我不知道的地區，<br/>愛主，我必欣然<br/>答應不猶豫，<br/>要我何去，我就去。<br/>',NULL,10748,10748);
INSERT INTO stanza VALUES('C651','chorus','愛主，要我何去，<br/>我就去，<br/>無論平地或山河；<br/>要我去說何語，<br/>我就說何語，<br/>要我如何，就如何。<br/>',NULL,10749,10749);
INSERT INTO stanza VALUES('C651','2','也許今天就有神恩言，<br/>是主要我去呼喊；<br/>也許現在罪惡途徑間，<br/>有人要我去追還；<br/>救主，你若親自來帶領，<br/>道路雖然暗無光，<br/>我的聲音要<br/>響應你的佳音，<br/>要我怎講，我就講。<br/>',NULL,10750,10750);
INSERT INTO stanza VALUES('C651','3','在這世界廣大禾田間，<br/>總有我的一寸土，<br/>我能彀花費此生餘年，<br/>為著我的受死主；<br/>我將自己交託你手裡，<br/>知道你愛我深刻，<br/>我要從我心裡<br/>順服你旨意，<br/>要我如何，就如何。<br/>',NULL,10751,10751);
INSERT INTO stanza VALUES('C652','1','不可等候，<br/>一直夢想將來成大業，<br/>不可等候，要光被遠方，<br/>你有諸般目前本分，<br/>今日當解決，<br/>你的一隅，你當照亮。<br/>',NULL,10752,10752);
INSERT INTO stanza VALUES('C652','chorus','你的一隅，你當照亮！<br/>你的一隅，你當照亮！<br/>情形越難，<br/>聖徒之光越當照得亮，<br/>你的一隅，你當照亮。<br/>',NULL,10753,10753);
INSERT INTO stanza VALUES('C652','2','『你們的光當照人前，』<br/>乃是主命令，<br/>你們應當遵從莫掩藏；<br/>一個罪人棄暗就光，<br/>也需人引領，<br/>你的一隅，你當照亮。<br/>',NULL,10754,10754);
INSERT INTO stanza VALUES('C652','3','請看在你旁邊<br/>就有信徒在流浪，<br/>何必到處尋找失迷羊，<br/>應當勸勉、挽回、安慰，<br/>體貼主心腸，<br/>你的一隅，你當照亮。<br/>',NULL,10755,10755);
INSERT INTO stanza VALUES('C652','4','應當時時與主交通，<br/>瞻仰主聖容，<br/>纔能返照榮耀的明光；<br/>你若熱誠愛主事主，<br/>人必受感動，<br/>你的一隅，你當照亮。<br/>',NULL,10756,10756);
INSERT INTO stanza VALUES('C652','5','現今，救主已近，<br/>天上晨星要出現，<br/>主人要來，僕人要得獎；<br/>拯救罪人，挽回信徒，<br/>當趁有今天，<br/>你的一隅，你當照亮。<br/>',NULL,10757,10757);
INSERT INTO stanza VALUES('C653','1','在流中！在流中！<br/>來為主同作工；<br/>遵主旨，行主路，<br/>照主話來事奉。<br/>在生命水流中，<br/>靠主能而作工；<br/>為召會，為國度，<br/>在此時同事奉。<br/>',NULL,10758,10758);
INSERT INTO stanza VALUES('C653','chorus','在流中！在流中！<br/>同作工在流中！<br/>在流中！在流中！<br/>與聖徒配搭而事奉。<br/>',NULL,10759,10759);
INSERT INTO stanza VALUES('C653','2','在流中！在流中！<br/>來為主同作工；<br/>在聖靈水流中，<br/>主的話肯遵從。<br/>永不靠自己力，<br/>不單獨，不任意，<br/>乃是與眾肢體，<br/>同事奉，互相倚。<br/>',NULL,10760,10760);
INSERT INTO stanza VALUES('C653','3','在流中！在流中！<br/>來為主同作工，<br/>同召會，同聖徒，<br/>在主話亮光中。<br/>向需要的群眾，<br/>傳主話，供生命，<br/>為成功神計畫，<br/>在流中向前行。<br/>',NULL,10761,10761);
INSERT INTO stanza VALUES('C654','1','新約之下所有事奉，<br/>不在字句只在靈；<br/>字句乃是將人殺死，<br/>惟有靈是叫人生。<br/>外面作的全都不算，<br/>裡面作的纔算是；<br/>不是按著舊的儀文，<br/>乃是照靈新樣式。<br/>',NULL,10762,10762);
INSERT INTO stanza VALUES('C654','2','不是僅藉外面教導，<br/>乃靠裡面的恩膏；<br/>不是僅藉外面樣式，<br/>乃藉裡面的光照。<br/>不是憑著人的規條，<br/>乃憑屬天的管治；<br/>不是照著人的決定，<br/>乃照神賜的啟示。<br/>',NULL,10763,10763);
INSERT INTO stanza VALUES('C654','3','不是給人死的宗教，<br/>乃是供應活基督；<br/>不是傳遞虛空神學，<br/>乃是活出主豐富。<br/>不是道理、字句、知識，<br/>乃是基督作信息；<br/>不是恩賜、儀式、作法，<br/>乃是基督為實際。<br/>',NULL,10764,10764);
INSERT INTO stanza VALUES('C654','4','不是客觀對神敬拜，<br/>乃是主觀事奉神；<br/>不是傳揚客觀基督，<br/>乃讓基督顯我身。<br/>不是僅憑聖經作工，<br/>乃是藉靈和生命；<br/>不是靠著肉體、自己，<br/>乃靠大能的聖靈。<br/>',NULL,10765,10765);
INSERT INTO stanza VALUES('C655','1','生命流露纔是工作，<br/>工作必須是生活；<br/>生活、工作成為一體，<br/>工作纔會有結果。<br/>經驗說出纔是信息，<br/>信息必須是經歷；<br/>經歷、信息能彀一致，<br/>信息纔會有能力。<br/>',NULL,10766,10766);
INSERT INTO stanza VALUES('C655','2','工作須是生命果子，<br/>藉著那靈所結出；<br/>猶如葡萄樹枝結實，<br/>彰顯生命的豐富。<br/>乃是基督藉我工作，<br/>將祂生命來表現，<br/>使祂生命所有豐富，<br/>藉我顯在眾人前。<br/>',NULL,10767,10767);
INSERT INTO stanza VALUES('C655','3','不是人所推行運動，<br/>乃是聖靈的感動；<br/>不是外面有所作為，<br/>乃是裡面在作工。<br/>不是人的一種事業，<br/>乃是神命的活出；<br/>不是勞苦為著成功，<br/>乃是表現主基督。<br/>',NULL,10768,10768);
INSERT INTO stanza VALUES('C655','4','我的計畫、目的、努力，<br/>一切必須全放棄，<br/>使主可以藉我工作，<br/>全為完成祂心意。<br/>我之所是與我所有，<br/>全都必須置死地，<br/>使主可以藉我活著，<br/>顯祂豐富和美麗。<br/>',NULL,10769,10769);
INSERT INTO stanza VALUES('C656','1','要在身體事奉、工作，<br/>這是主旨所著重；<br/>身體乃是主所要者，<br/>當與身體同行動。<br/>',NULL,10770,10770);
INSERT INTO stanza VALUES('C656','chorus','要在身體事奉、工作，<br/>永遠不要再單獨；<br/>既是身體上的肢體，<br/>就當配搭事奉主。<br/>',NULL,10771,10771);
INSERT INTO stanza VALUES('C656','2','重生是作主的肢體，<br/>非作單獨的個人；<br/>總是應該與眾聖徒<br/>互相配搭事奉神。<br/>',NULL,10772,10772);
INSERT INTO stanza VALUES('C656','3','乃是活石同被建造，<br/>必須作神的靈宮，<br/>成為聖潔祭司體系，<br/>和諧一致的事奉。<br/>',NULL,10773,10773);
INSERT INTO stanza VALUES('C656','4','因此必須同被建造，<br/>各守地位盡職事；<br/>我們事奉所有根據，<br/>乃是身體的性質。<br/>',NULL,10774,10774);
INSERT INTO stanza VALUES('C656','5','我們工作，盡職事奉，<br/>須從身體得供應；<br/>若與身體脫節、孤立，<br/>必失功用與功能。<br/>',NULL,10775,10775);
INSERT INTO stanza VALUES('C656','6','我們若在身體事奉，<br/>元首豐富必得享；<br/>盡上肢體所有功用，<br/>必有基督的身量。<br/>',NULL,10776,10776);
INSERT INTO stanza VALUES('C656','7','永遠持定元首基督，<br/>藉祂一同得長進；<br/>從祂得到豐滿供應，<br/>分給身體各部分。<br/>',NULL,10777,10777);
INSERT INTO stanza VALUES('C656','8','主，我重新獻上身體，<br/>求你變化我心思，<br/>使我明白你的旨意，<br/>藉你身體而服事。<br/>',NULL,10778,10778);
INSERT INTO stanza VALUES('C657','1','祭司生活何等有福，<br/>得享基督作一切！<br/>衣、食、住處，<br/>全是基督，<br/>並有基督為產業。<br/>',NULL,10779,10779);
INSERT INTO stanza VALUES('C657','chorus','祭司生活何等有福，<br/>得享基督作一切！<br/>衣、食、住處，<br/>全是基督，<br/>並有基督為產業。<br/>',NULL,10780,10780);
INSERT INTO stanza VALUES('C657','2','祭司供職所披所戴，<br/>全是基督的榮美；<br/>聖服、聖冠、面牌、<br/>胸牌，<br/>榮耀、華美又尊貴。<br/>',NULL,10781,10781);
INSERT INTO stanza VALUES('C657','3','祭司向神獻上基督，<br/>作神悅納的祭物，<br/>就得享受祂作食物，<br/>飽嘗基督的豐富。<br/>',NULL,10782,10782);
INSERT INTO stanza VALUES('C657','4','披戴基督，與祂聯合，<br/>外面有祂作彰顯；<br/>喫喝基督，與祂調和，<br/>裡面有祂來充滿。<br/>',NULL,10783,10783);
INSERT INTO stanza VALUES('C657','5','祭司所住，神聖、榮耀，<br/>乃是擴大的基督；<br/>祭司在此同被建造，<br/>就有屬靈的住處。<br/>',NULL,10784,10784);
INSERT INTO stanza VALUES('C657','6','祭司所有也是基督－祭司惟一的產業；<br/>祭司生活所有事物，<br/>全是基督的一切！<br/>',NULL,10785,10785);
INSERT INTO stanza VALUES('C658','1','我們事奉須為召會，<br/>神的美意如此定；<br/>這是工作惟一途徑，<br/>使徒都曾如此行。<br/>',NULL,10786,10786);
INSERT INTO stanza VALUES('C658','chorus','我們事奉須為召會，<br/>不該為著別事情；<br/>這是神的完全旨意，<br/>我們必須如此行。<br/>',NULL,10787,10787);
INSERT INTO stanza VALUES('C658','2','召會要作神的器皿，<br/>是神永遠的計畫；<br/>神要我們所有事奉，<br/>都為建造祂的家。<br/>',NULL,10788,10788);
INSERT INTO stanza VALUES('C658','3','元首所賜恩賜的人，<br/>全都為著祂身體；<br/>他們都該建造召會，<br/>使主豐滿得建起。<br/>',NULL,10789,10789);
INSERT INTO stanza VALUES('C658','4','所有恩賜、一切功用、<br/>聖靈所顯的能力，<br/>以及所有不同職事，<br/>都該只為主身體。<br/>',NULL,10790,10790);
INSERT INTO stanza VALUES('C658','5','傳揚福音、拯救罪人、<br/>教導、牧養並治理，<br/>以及各樣別的工作，<br/>也該只為主身體。<br/>',NULL,10791,10791);
INSERT INTO stanza VALUES('C658','6','職事乃是為著召會，<br/>召會不是為職事；<br/>所有燈臺都是召會，<br/>任何職事都不是。<br/>',NULL,10792,10792);
INSERT INTO stanza VALUES('C658','7','這能保守召會合一，<br/>拯救我們脫宗派；<br/>這將試驗我的動機，<br/>予我目的以更改。<br/>',NULL,10793,10793);
INSERT INTO stanza VALUES('C658','8','求主救我脫離工作，<br/>脫離宗派的工作；<br/>使我只為召會勞苦，<br/>只為召會而活著。<br/>',NULL,10794,10794);
INSERT INTO stanza VALUES('C659','1','事奉乃是供應基督，<br/>無論對神或對人；<br/>總是供應基督富餘，<br/>以祂為祭事奉神。<br/>',NULL,10795,10795);
INSERT INTO stanza VALUES('C659','chorus','事奉乃是供應基督，<br/>無論對神或對人；<br/>總是供應基督富餘，<br/>以祂為祭事奉神。<br/>',NULL,10796,10796);
INSERT INTO stanza VALUES('C659','2','古時選民以色列人，<br/>獻上美地的豐盛；<br/>照樣我們應當獻上<br/>從主所有的收成。<br/>',NULL,10797,10797);
INSERT INTO stanza VALUES('C659','3','基督乃是我們美地，<br/>在祂身上須經營；<br/>從祂收穫，豐富有餘，<br/>與人分享祂豐盛。<br/>',NULL,10798,10798);
INSERT INTO stanza VALUES('C659','4','持定基督，藉祂長大，<br/>每一肢體盡功用；<br/>接受基督，分給基督，<br/>對祂身體來事奉。<br/>',NULL,10799,10799);
INSERT INTO stanza VALUES('C659','5','交通、見證、話語職事、<br/>各種事奉及幫助，<br/>都該是將基督擺出，<br/>供應基督的豐富。<br/>',NULL,10800,10800);
INSERT INTO stanza VALUES('C660','1','現今時候已不多，<br/>旅世程途快要過，<br/>被提鐘點已在望，<br/>我們快要見天王；<br/>但願我們常殷勤，<br/>直到救主再降臨。<br/>',NULL,10801,10801);
INSERT INTO stanza VALUES('C660','2','殷勤服事不冷淡，<br/>竭力作工不畏難，<br/>背負十架不自憐，<br/>願意為主歷苦艱，<br/>一直『買賣』到主來，<br/>若未被提終不改。<br/>',NULL,10802,10802);
INSERT INTO stanza VALUES('C660','3','殷勤討伐眾惡靈，<br/>竭力進攻諸幽冥，<br/>雖遇危難仍得勝，<br/>未見平安不收陣，<br/>晝夜不斷靠祈禱，<br/>在戰場上站得牢。<br/>',NULL,10803,10803);
INSERT INTO stanza VALUES('C660','4','現今光陰如箭飛，<br/>我們盼望快得慰；<br/>願主保守靈、魂、體，<br/>完全順服主管理；<br/>但願我們常豫備，<br/>直到主來不疲憊。<br/>',NULL,10804,10804);
INSERT INTO stanza VALUES('C660','5','豫備，雖然受試煉；<br/>豫備，雖然無臉面；<br/>豫備，直到我生活，<br/>不能不向主求說：<br/>求主快來不遲延！<br/>求主快來在今天！<br/>',NULL,10805,10805);
INSERT INTO stanza VALUES('C661','1','趕緊工作，夜快臨，<br/>工作在於清晨；<br/>工作，正當朝色新，<br/>工作，花正芬；<br/>工作，當日光無蔭，<br/>工作在於驕陽；<br/>趕緊工作，夜快臨，<br/>必須離工場。<br/>',NULL,10806,10806);
INSERT INTO stanza VALUES('C661','2','趕緊工作，夜快臨，<br/>工作在於正午；<br/>最亮時辰宜辛勤，<br/>不久不辛苦。<br/>每一飛逝的光陰，<br/>都當裝滿成績；<br/>趕緊工作，夜快臨，<br/>那時人安息。<br/>',NULL,10807,10807);
INSERT INTO stanza VALUES('C661','3','趕緊工作，夜快臨，<br/>趁此加深暮景；<br/>夕陽西移彩霞新，<br/>再過成灰影；<br/>最後一線的光陰，<br/>不久就要沒落；<br/>趕緊作工，夜正臨，<br/>轉瞬工作過。<br/>',NULL,10808,10808);
INSERT INTO stanza VALUES('C662','1','榮耀福音向外推廣，<br/>乃是生命的湧流；<br/>藉著我們活的見證，<br/>失喪罪人蒙拯救。<br/>',NULL,10809,10809);
INSERT INTO stanza VALUES('C662','chorus','求主使我湧流生命，<br/>使你生命顯於我；<br/>藉我作你活的器皿，<br/>將人靈裡來點活。<br/>',NULL,10810,10810);
INSERT INTO stanza VALUES('C662','2','生命見證，使人心服，<br/>人纔肯來相信主；<br/>藉我生命湧流供應，<br/>人纔接主進心府。<br/>',NULL,10811,10811);
INSERT INTO stanza VALUES('C662','3','永遠要像葡萄樹枝，<br/>住在主裡結果子；<br/>藉著裡面生命湧流，<br/>將主向人來分賜。<br/>',NULL,10812,10812);
INSERT INTO stanza VALUES('C662','4','願我生活就是傳揚，<br/>使人在我看見祂；<br/>不僅用話宣傳道理，<br/>更將生命來種下。<br/>',NULL,10813,10813);
INSERT INTO stanza VALUES('C663','1','信徒趕快<br/>遵命出去普天下，<br/>通知他們神是如何慈愛，<br/>使之深曉<br/>神已成功祂救法，<br/>並不願意一人滅亡悲哀。<br/>',NULL,10814,10814);
INSERT INTO stanza VALUES('C663','chorus','傳揚好信息，和平福音，<br/>傳揚主耶穌<br/>已經救贖罪人。<br/>',NULL,10815,10815);
INSERT INTO stanza VALUES('C663','2','請看，<br/>何止千萬的人在罪中，<br/>受了捆綁，<br/>一直事奉鬼魔，<br/>無人前去通知：<br/>救贖已成功，<br/>救主已經得勝，<br/>死而復活。<br/>',NULL,10816,10816);
INSERT INTO stanza VALUES('C663','3','主能救人脫離<br/>罪惡的捆綁，<br/>亞當種類，<br/>因祂捨命結束；<br/>我們應當不畏<br/>赴火與蹈湯，<br/>庶免攔阻一人來信耶穌。<br/>',NULL,10817,10817);
INSERT INTO stanza VALUES('C663','4','世界各民、各國、<br/>各方並各人，<br/>我們都當前往傳揚恩典，<br/>叫人知道：<br/>神是如何成肉身，<br/>受死在地，<br/>使人重生屬天。<br/>',NULL,10818,10818);
INSERT INTO stanza VALUES('C663','5','不該攔阻兒女<br/>獻身往邊荒，<br/>應當奉獻財物幫助福音，<br/>並且禱告，<br/>求神祝福並推廣；<br/>你的犧牲，<br/>主必記念在心。<br/>',NULL,10819,10819);
INSERT INTO stanza VALUES('C663','6','應當記得，<br/>救主已將快再臨，<br/>機會一過，<br/>就難再盡本分；<br/>只怕有人<br/>是因你我不熱心，<br/>不能得救，<br/>也不能親近神。<br/>',NULL,10820,10820);
INSERT INTO stanza VALUES('C664','1','速興起傳福音！<br/>速搶救靈魂！<br/>請你看千萬人天天沉淪！<br/>莫塞住憐憫心，<br/>莫看重金銀，<br/>鬆開手，傳福音，<br/>趁著現今。<br/>',NULL,10821,10821);
INSERT INTO stanza VALUES('C664','chorus','速興起傳福音！<br/>速搶救靈魂！<br/>你為何仍忍心，<br/>看人沉淪？<br/>',NULL,10822,10822);
INSERT INTO stanza VALUES('C665','1','去向亡世供應基督，<br/>非僅藉話之所云。<br/>更藉生活分出基督，<br/>供應可憐的人群。<br/>',NULL,10823,10823);
INSERT INTO stanza VALUES('C665','chorus','去向亡世供應基督，<br/>使祂顯於你生活；<br/>憑祂活著，將祂分出，<br/>使人與你同得著。<br/>',NULL,10824,10824);
INSERT INTO stanza VALUES('C665','2','去向亡世供應基督－你所有的寶貴主；<br/>將你基督分給親人，<br/>作其成功與財富。<br/>',NULL,10825,10825);
INSERT INTO stanza VALUES('C665','3','去向亡世供應基督－你所享受的基督；<br/>將你基督分給朋友，<br/>作其誇耀與鴻福。<br/>',NULL,10826,10826);
INSERT INTO stanza VALUES('C665','4','去向亡世供應基督，<br/>祂是你命並一切；<br/>將你基督分給眾人，<br/>帶人來嘗祂超越。<br/>',NULL,10827,10827);
INSERT INTO stanza VALUES('C666','1','去採集材料，<br/>為著神的殿，<br/>去勸告親友向神來回轉；<br/>去帶領罪人脫罪免沉淪，<br/>去尋找迷羊來歸主羊群。<br/>',NULL,10828,10828);
INSERT INTO stanza VALUES('C666','2','去採集材料，<br/>為著神的殿，<br/>去拯救世人脫世界糾纏；<br/>脫離撒但的黑暗與欺騙，<br/>脫離他一切誘惑的手段。<br/>',NULL,10829,10829);
INSERT INTO stanza VALUES('C666','3','去採集材料，<br/>為著神的殿，<br/>去引導浪者，<br/>來投主懷間；<br/>去打敗魔鬼－害人的仇敵，<br/>去釋放俘囚，<br/>來向主歸依。<br/>',NULL,10830,10830);
INSERT INTO stanza VALUES('C666','4','去採集材料，<br/>為著神的殿，<br/>在身體立場，<br/>將基督宣傳；<br/>與主眾聖徒靈同魂也同，<br/>到處去吹響福音的號筒。<br/>',NULL,10831,10831);
INSERT INTO stanza VALUES('C667','1','早晨我們播種，<br/>晌午我們播種，<br/>傍晚我們播種，<br/>播出神慈愛；<br/>等候成熟日子，<br/>等候收割點鐘，<br/>我們喜樂滿懷，<br/>禾捆帶回來。<br/>',NULL,10832,10832);
INSERT INTO stanza VALUES('C667','chorus','禾捆帶回來，<br/>禾捆帶回來，<br/>我們喜樂滿懷，<br/>禾捆帶回來。<br/>禾捆帶回來，<br/>禾捆帶回來，<br/>我們喜樂滿懷，<br/>禾捆帶回來。<br/>',NULL,10833,10833);
INSERT INTO stanza VALUES('C667','2','炎日我們播種，<br/>陰天我們播種，<br/>不怕朔風怒號，<br/>不怕烏雲蓋；<br/>不久莊稼成熟，<br/>不久一切完工，<br/>我們喜樂滿懷，<br/>禾捆帶回來。<br/>',NULL,10834,10834);
INSERT INTO stanza VALUES('C667','3','起來，前去播種，<br/>為主流淚播種，<br/>雖然時遭損失，<br/>雖然當忍耐，<br/>哭泣就會過去，<br/>歡迎就在路終，<br/>我們喜樂滿懷，<br/>禾捆帶回來。<br/>',NULL,10835,10835);
INSERT INTO stanza VALUES('C668','1','我豈可去，雙手空空？<br/>豈可如此見主面？<br/>從無一日為主作工，<br/>未有虜物獻主前。<br/>',NULL,10836,10836);
INSERT INTO stanza VALUES('C668','chorus','我豈可以空手見主？<br/>豈可雙手空空去？<br/>未領一人來歸基督！<br/>豈可雙手空空去？<br/>',NULL,10837,10837);
INSERT INTO stanza VALUES('C668','2','今日去世復有何恐？<br/>因為恩主已救我；<br/>但一想到雙手空空，<br/>愁雲立即覆我額！<br/>',NULL,10838,10838);
INSERT INTO stanza VALUES('C668','3','從前犯罪所廢歲月，<br/>假若現在能贖回，<br/>我必完全奉獻無缺，<br/>樂行主旨不再違。<br/>',NULL,10839,10839);
INSERT INTO stanza VALUES('C668','4','哦，願信徒速起熱心，<br/>殷勤作工趁白晝；<br/>死夜尚未臨到你身，<br/>努力救人不稍休。<br/>',NULL,10840,10840);
INSERT INTO stanza VALUES('C669','1','我有一救主，<br/>在天為我祈求，<br/>可親又可愛，<br/>雖朋友與我疏；<br/>現今祂時時看顧我，<br/>情愛深厚：<br/>哦，願我救主<br/>也成為你救主！<br/>',NULL,10841,10841);
INSERT INTO stanza VALUES('C669','chorus','為你，我今祈求！<br/>為你，我今祈求！<br/>但願我救主<br/>也向你施拯救！<br/>',NULL,10842,10842);
INSERT INTO stanza VALUES('C669','2','我有一天父，<br/>住在光明之家，<br/>許我一盼望，<br/>既永遠，又有據；<br/>不久要接我<br/>到天上去會見祂：<br/>哦，願祂施恩，<br/>你也能同我去！<br/>',NULL,10843,10843);
INSERT INTO stanza VALUES('C669','3','我有一喜樂，<br/>這樂湧如海波，<br/>因為我救主<br/>已擔去我罪惡，<br/>並且祂現今<br/>還在我裡面活著：<br/>哦，願我救主<br/>也賜你這喜樂！<br/>',NULL,10844,10844);
INSERT INTO stanza VALUES('C669','4','我有一平安，<br/>靜如湖水一般，<br/>奇妙的平安，<br/>世上友未知曉；<br/>惟有主耶穌，<br/>祂是這平安根源：<br/>哦，願這平安，<br/>你也能親嘗到！<br/>',NULL,10845,10845);
INSERT INTO stanza VALUES('C669','5','等主救了你，<br/>請也告訴別人：<br/>我主曾如何<br/>也把你來拯救；<br/>並且要祈求，<br/>求你主也救他們：<br/>主聽我祈求，<br/>也必聽你祈求！<br/>',NULL,10846,10846);
INSERT INTO stanza VALUES('C669','chorus','為他，你要祈求！<br/>為他，你要祈求！<br/>但願你救主<br/>也把他來拯救！<br/>',NULL,10847,10847);
INSERT INTO stanza VALUES('C670','1','你當豫備迎見神，<br/>你當豫備迎見神，<br/>你當豫備迎見神，<br/>悔改相信；豫備見神，<br/>悔改相信，接受救恩。<br/>',NULL,10848,10848);
INSERT INTO stanza VALUES('C670','2','你當豫備迎見神，<br/>你當豫備迎見神，<br/>你當豫備迎見神，<br/>罪惡脫盡；豫備見神，<br/>罪惡脫盡，改換一新。<br/>',NULL,10849,10849);
INSERT INTO stanza VALUES('C670','3','你當豫備迎見神，<br/>你當豫備迎見神，<br/>你當豫備迎見神，<br/>奉獻心身；豫備見神，<br/>奉獻心身，完全歸神。<br/>',NULL,10850,10850);
INSERT INTO stanza VALUES('C671','1','基督已經完成贖罪，<br/>何等奇妙的救主！<br/>重價已付，我被贖回！<br/>何等奇妙的救主！<br/>',NULL,10851,10851);
INSERT INTO stanza VALUES('C671','chorus','何等奇妙的救主，<br/>是耶穌，我耶穌！<br/>何等奇妙的救主，<br/>是耶穌，我主！<br/>',NULL,10852,10852);
INSERT INTO stanza VALUES('C671','2','讚美祂血洗罪有效，<br/>何等奇妙的救主！<br/>使我這人與神和好，<br/>何等奇妙的救主！<br/>',NULL,10853,10853);
INSERT INTO stanza VALUES('C671','3','祂已洗淨我的罪愆，<br/>何等奇妙的救主！<br/>今在我心作王掌權，<br/>何等奇妙的救主！<br/>',NULL,10854,10854);
INSERT INTO stanza VALUES('C671','4','時時刻刻與我親近，<br/>何等奇妙的救主！<br/>天天保守使我忠心，<br/>何等奇妙的救主！<br/>',NULL,10855,10855);
INSERT INTO stanza VALUES('C671','5','得勝能力隨時賜與，<br/>何等奇妙的救主！<br/>使我爭戰奏凱有餘，<br/>何等奇妙的救主！<br/>',NULL,10856,10856);
INSERT INTO stanza VALUES('C671','6','我已向祂獻上心身，<br/>何等奇妙的救主！<br/>世界不能再把我分，<br/>何等奇妙的救主！<br/>',NULL,10857,10857);
INSERT INTO stanza VALUES('C672','1','一日，<br/>當天上充滿讚美之聲，<br/>一日，<br/>當罪惡深染全人類，<br/>耶穌就降世，<br/>為一童女所生，<br/>住在人中間，<br/>顯出神光輝！<br/>',NULL,10858,10858);
INSERT INTO stanza VALUES('C672','chorus','降生，為愛我；<br/>受死，為救我；<br/>埋葬，為帶去<br/>我一切罪過；<br/>復活，為白白的<br/>永遠稱義我；<br/>一日，祂要來，<br/>哦，榮日接我！<br/>',NULL,10859,10859);
INSERT INTO stanza VALUES('C672','2','一日，<br/>人將祂帶到加略山上，<br/>一日，<br/>人把祂釘木上剪除；<br/>祂備嘗痛苦，<br/>被神擊打、壓傷，<br/>擔當我罪過，<br/>作我救贖主！<br/>',NULL,10860,10860);
INSERT INTO stanza VALUES('C672','3','一日，<br/>人撇祂獨自在那園中，<br/>一日，<br/>祂安息，息了諸痛苦；<br/>天使從天來，<br/>夜間守祂墓洞；<br/>無望者之望，<br/>乃是我救主！<br/>',NULL,10861,10861);
INSERT INTO stanza VALUES('C672','4','一日，<br/>那墳墓不能將祂留藏，<br/>一日，<br/>那大石輥開不封堵；<br/>祂已復活了，<br/>祂已勝過死亡，<br/>升到高天上，<br/>永遠作我主！<br/>',NULL,10862,10862);
INSERT INTO stanza VALUES('C672','5','一日，號筒響，<br/>傳報祂從天來，<br/>一日，<br/>祂榮光滿天都照出；<br/>奇妙的日子，<br/>帶來我的心愛；<br/>榮耀的救主，<br/>就是我耶穌！<br/>',NULL,10863,10863);
INSERT INTO stanza VALUES('C673','1','耶穌，我救主，<br/>降生馬槽中，<br/>成為『憂患人』，<br/>來經歷苦痛；<br/>哦，這真希奇，<br/>值得我稱頌！<br/>祂來尋我，尋我！<br/>',NULL,10864,10864);
INSERT INTO stanza VALUES('C673','chorus','祂來尋我，尋我！<br/>祂來尋我，尋我！<br/>哦，這真希奇，<br/>值得我稱頌！<br/>祂來尋我，尋我！<br/>',NULL,10865,10865);
INSERT INTO stanza VALUES('C673','2','耶穌，我救主，<br/>在加略木上，<br/>還我眾罪債，<br/>將我人釋放；<br/>哦，這真希奇，<br/>怎麼會這樣？<br/>祂死為我，為我！<br/>',NULL,10866,10866);
INSERT INTO stanza VALUES('C673','chorus','祂死為我，為我！<br/>祂死為我，為我！<br/>哦，這真希奇，<br/>怎麼會這樣？<br/>祂死為我，為我！<br/>',NULL,10867,10867);
INSERT INTO stanza VALUES('C673','3','耶穌，我救主，<br/>永活不改變，<br/>當我在流蕩，<br/>將我來召喚；<br/>雖遭我拒絕，<br/>仍召不間斷，<br/>祂來召我，召我！<br/>',NULL,10868,10868);
INSERT INTO stanza VALUES('C673','chorus','祂來召我，召我！<br/>祂來召我，召我！<br/>雖遭我拒絕，<br/>仍召不間斷，<br/>祂來召我，召我！<br/>',NULL,10869,10869);
INSERT INTO stanza VALUES('C673','4','耶穌，我救主，<br/>要來接選民，<br/>這應許甜美，<br/>當年日飛奔：<br/>哦，我要見祂<br/>從天上降臨，<br/>祂來接我，接我！<br/>',NULL,10870,10870);
INSERT INTO stanza VALUES('C673','chorus','祂來接我，接我！<br/>祂來接我，接我！<br/>哦，我要見祂<br/>從天上降臨，<br/>祂來接我，接我！<br/>',NULL,10871,10871);
INSERT INTO stanza VALUES('C674','1','至大醫生可親可近，<br/>就是同情的耶穌，<br/>能醫罪傷，能解憂困，<br/>請你速來就耶穌。<br/>',NULL,10872,10872);
INSERT INTO stanza VALUES('C674','chorus','祂為你受死木上，<br/>祂將你眾罪擔當，<br/>祂尋你前來醫傷，<br/>速來就這耶穌。<br/>',NULL,10873,10873);
INSERT INTO stanza VALUES('C674','2','罪孽雖多，必蒙赦免，<br/>只要肯來就耶穌！<br/>良心雖虧，必得平安，<br/>若你肯來就耶穌！<br/>',NULL,10874,10874);
INSERT INTO stanza VALUES('C674','3','性情敗壞，罪惡染心，<br/>要得救治，就耶穌；<br/>軟弱、歎息、疾病纏身，<br/>要蒙醫治，就耶穌！<br/>',NULL,10875,10875);
INSERT INTO stanza VALUES('C674','4','鬱悶、痛苦、人生乏味，<br/>何不前來就耶穌？<br/>祂能賜你醫治活水，<br/>請來一試就耶穌！<br/>',NULL,10876,10876);
INSERT INTO stanza VALUES('C674','5','我已得著醫治、釋放，<br/>因我接受主耶穌；<br/>榮耀歸給被殺羔羊，<br/>我今相信主耶穌。<br/>',NULL,10877,10877);
INSERT INTO stanza VALUES('C674','chorus','我得釋，因祂被綁；<br/>我得醫，因祂受傷；<br/>我得生，因祂命亡；<br/>我已得著耶穌。<br/>',NULL,10878,10878);
INSERT INTO stanza VALUES('C674','6','我愛救我恩主之名，<br/>我愛之名是耶穌！<br/>這名驅盡我的苦情，<br/>寶貝之名惟耶穌！<br/>',NULL,10879,10879);
INSERT INTO stanza VALUES('C674','chorus','馨香名，聖徒愛唱！<br/>尊貴名，天使頌揚！<br/>高超名，萬名之上！<br/>耶穌！寶貝耶穌！<br/>',NULL,10880,10880);
INSERT INTO stanza VALUES('C674','7','等我被提到祂面前，<br/>親眼得見我耶穌，<br/>榮耀之中更要頌讚<br/>耶穌！寶貝的耶穌！<br/>',NULL,10881,10881);
INSERT INTO stanza VALUES('C675','1','這個榮耀信息何甜，<br/>相信要簡單：<br/>昨日、今日、直到永遠，<br/>耶穌不改變。<br/>祂仍喜愛拯救罪人，<br/>醫治人疾病，<br/>平靜風浪，安撫驚魂；<br/>榮耀歸祂名！<br/>',NULL,10882,10882);
INSERT INTO stanza VALUES('C675','chorus','昨日、今日、直到永遠，<br/>耶穌不改變！<br/>萬事萬物都在遞遷，<br/>耶穌不改變！<br/>耶穌不改變，<br/>耶穌不改變；<br/>萬事萬物都在遞遷，<br/>耶穌不改變！<br/>',NULL,10883,10883);
INSERT INTO stanza VALUES('C675','2','耶穌乃是罪人之友，<br/>祂今尋找你；<br/>來祂腳前認罪、祈求，<br/>祂必不丟棄；<br/>祂必對你說出恩言，<br/>像祂在當年<br/>曾對人說：『你罪赦免，<br/>可平安向前。』<br/>',NULL,10884,10884);
INSERT INTO stanza VALUES('C675','3','當祂在世，曾醫病痛，<br/>用祂大能手；<br/>今仍施醫與昔相同，<br/>祂話要接受。<br/>醫治之能曾經顯在<br/>一婦的一摸；<br/>今向信心此能不改，<br/>要顯同樣多。<br/>',NULL,10885,10885);
INSERT INTO stanza VALUES('C675','4','像祂前曾與人同行，<br/>去以馬忤斯；<br/>照樣祂在我的一生，<br/>與我永偕止。<br/>不久我就要再見祂，<br/>因祂必快來！<br/>但祂必定一點不差，<br/>像祂在離開。<br/>',NULL,10886,10886);
INSERT INTO stanza VALUES('C676','1','大喜信我已聽見：<br/>主救人！主救人！<br/>這佳音務要傳遍：<br/>主救人！主救人！<br/>去天下中外人間，<br/>不要顧路途艱險，<br/>遵主命到處宣傳：<br/>主救人！主救人！<br/>',NULL,10887,10887);
INSERT INTO stanza VALUES('C676','2','去通知貧富家門：<br/>主救人！主救人！<br/>去告訴大小罪人：<br/>主救人！主救人！<br/>眾海島應當歌唱，<br/>深海洋也當應響，<br/>全地上都當宣揚：<br/>主救人！主救人！<br/>',NULL,10888,10888);
INSERT INTO stanza VALUES('C676','3','十字架已經宣告：<br/>主救人！主救人！<br/>寶貴血仍在說道：<br/>主救人！主救人！<br/>主受死使人免懲，<br/>主復活使人得生，<br/>主升天使人高升：<br/>主救人！主救人！<br/>',NULL,10889,10889);
INSERT INTO stanza VALUES('C676','4','這個是真正福音：<br/>主救人！主救人！<br/>這個能安慰人心：<br/>主救人！主救人！<br/>疲困人可得安息，<br/>憂傷人也能歡喜，<br/>有罪人不必遲疑：<br/>主救人！主救人！<br/>',NULL,10890,10890);
INSERT INTO stanza VALUES('C676','5','這福音仍要傳報：<br/>主救人！主救人！<br/>世上人都該知曉：<br/>主救人！主救人！<br/>神恩豐，廣賜眾人；<br/>人罪深，也能蒙恩；<br/>我聲微，仍要誦吟：<br/>主救人！主救人！<br/>',NULL,10891,10891);
INSERT INTO stanza VALUES('C677','1','憐憫、慈愛、寬恕、<br/>溫柔又謙和；<br/>為了罪人忍辱，<br/>甘負十架軛；<br/>捨命、流血、受苦，<br/>為救失喪者：<br/>這是基督耶穌，<br/>對祂你如何？<br/>',NULL,10892,10892);
INSERT INTO stanza VALUES('C678','1','除了耶穌以外，<br/>除了耶穌以外，<br/>沒有別的拯救，<br/>沒有別的拯救；<br/>因為在天下人間，<br/>因為在天下人間，<br/>沒有賜下別名，<br/>人可靠著得生。<br/>',NULL,10893,10893);
INSERT INTO stanza VALUES('C679','1','行善不能救我！<br/>我雖謹慎我行徑，<br/>不過使我得美名，<br/>不能改變我惡性；<br/>行善不能救我！<br/>',NULL,10894,10894);
INSERT INTO stanza VALUES('C679','chorus','耶穌為我曾流淚！<br/>耶穌為我曾贖罪！<br/>耶穌現今施恩惠！<br/>耶穌纔能救我！<br/>',NULL,10895,10895);
INSERT INTO stanza VALUES('C679','2','哀哭不能救我！<br/>我眼雖然常流淚，<br/>不能洗淨我的罪，<br/>不能使我得安慰；<br/>哀哭不能救我！<br/>',NULL,10896,10896);
INSERT INTO stanza VALUES('C679','3','等候不能救我！<br/>罪惡害我到如此，<br/>越過惟有越放肆，<br/>若再等候是等死；<br/>等候不能救我！<br/>',NULL,10897,10897);
INSERT INTO stanza VALUES('C679','4','信主纔能救我！<br/>因主為我流寶血，<br/>要將我洗白如雪，<br/>我若信祂必清潔；<br/>信主纔能救我！<br/>',NULL,10898,10898);
INSERT INTO stanza VALUES('C680','1','哦，愛！奇妙之愛，<br/>救主去加略！<br/>為去那地，祂竟離寶座，<br/>來受貧窮、苦楚，<br/>遭患從未卻，<br/>一路艱難全是為著我！<br/>',NULL,10899,10899);
INSERT INTO stanza VALUES('C680','chorus','祂去加略，<br/>一路全是為著我，<br/>是為著我，是為著我；<br/>祂去加略，<br/>一路全是為著我，<br/>祂去將我救活！<br/>',NULL,10900,10900);
INSERT INTO stanza VALUES('C680','2','哦，慘！慘不忍睹，<br/>救主掛木上！<br/>頭戴荊冕，手腳被釘著，<br/>身帶鞭打創傷，<br/>全人血成行，<br/>備嘗痛苦，是因愛憐我！<br/>',NULL,10901,10901);
INSERT INTO stanza VALUES('C680','chorus','祂釘木上受苦，<br/>是因愛憐我，<br/>因愛憐我，因愛憐我；<br/>祂釘木上受苦，<br/>是因愛憐我，<br/>祂釘解我捆索！<br/>',NULL,10902,10902);
INSERT INTO stanza VALUES('C680','3','阿呀！遍地黑暗，<br/>神來審判祂！<br/>聖潔怒氣焚燒如烈火；<br/>因祂替我擔罪，<br/>公義將祂殺，<br/>祂受刑罰，乃是代替我！<br/>',NULL,10903,10903);
INSERT INTO stanza VALUES('C680','chorus','祂在十架受死，<br/>乃是代替我，<br/>是代替我，是代替我；<br/>祂在十架受死，<br/>乃是代替我，<br/>祂死擔我罪過！<br/>',NULL,10904,10904);
INSERT INTO stanza VALUES('C680','4','可憐！<br/>戰兢罪人原不懂恩典！<br/>今在加略見祂肋被戳，<br/>並聞：『我血流出，<br/>為你買赦免，』<br/>纔知祂死已經救贖我！<br/>',NULL,10905,10905);
INSERT INTO stanza VALUES('C680','chorus','祂在十架流血，<br/>已經救贖我，已救贖我，<br/>已救贖我；<br/>祂在十架流血，<br/>已經救贖我，<br/>流血免我災禍！<br/>',NULL,10906,10906);
INSERT INTO stanza VALUES('C681','1','阿呀！救主身懸木架，<br/>手足被釘難忍，<br/>頭戴荊冕，利刺痛扎，<br/>身有鞭打傷痕。<br/>',NULL,10907,10907);
INSERT INTO stanza VALUES('C681','chorus','在十架，在十架，<br/>我看見主恩光，<br/>罪重擔從我身全卸脫！<br/>在十架，我因信，<br/>眼明亮，心平康，<br/>從今後，我終日能歡樂！<br/>',NULL,10908,10908);
INSERT INTO stanza VALUES('C681','2','祂在十架這樣被難，<br/>乃是替我受譴；<br/>憐憫驚人，恩難測算，<br/>慈愛何其超凡！<br/>',NULL,10909,10909);
INSERT INTO stanza VALUES('C681','3','神將人罪歸祂身上，<br/>要祂為人擔當，<br/>難怪太陽全然隱藏，<br/>關閉一切榮光。<br/>',NULL,10910,10910);
INSERT INTO stanza VALUES('C681','4','看哪！祂死，殿幔即裂，<br/>神、人間隔已去；<br/>聖徒墳墓亦多崩決，<br/>死亡不能再拘。<br/>',NULL,10911,10911);
INSERT INTO stanza VALUES('C681','5','哦，祂肋旁還被扎傷，<br/>有血和水流出，<br/>賜我生命，免我死亡，<br/>將我罪孽潔除。<br/>',NULL,10912,10912);
INSERT INTO stanza VALUES('C681','6','臨死之前，祂喊，<br/>『成了！』<br/>宣告救工已完；<br/>我聞此言，憂懼頓消，<br/>哀歎立變感讚！<br/>',NULL,10913,10913);
INSERT INTO stanza VALUES('C682','1','我聽救主聲音，<br/>說我能力薄弱，<br/>若非誠心相信，<br/>不能免去罪過。<br/>',NULL,10914,10914);
INSERT INTO stanza VALUES('C682','chorus','我欠千萬金，<br/>主替我還盡；<br/>一生犯罪真苦辛，<br/>主今赦免、憐憫。<br/>',NULL,10915,10915);
INSERT INTO stanza VALUES('C682','2','主，我今纔看明，<br/>惟你有這力量，<br/>能洗污穢潔淨，<br/>能使軟弱剛強。<br/>',NULL,10916,10916);
INSERT INTO stanza VALUES('C682','3','我真沒有善良，<br/>可以得主救恩；<br/>但主特別體諒，<br/>用愛救我罪人。<br/>',NULL,10917,10917);
INSERT INTO stanza VALUES('C682','4','即云我要離世，<br/>我仍不至戰兢；<br/>因我所欠罪值，<br/>主早替我還清。<br/>',NULL,10918,10918);
INSERT INTO stanza VALUES('C682','5','將來立在神前，<br/>神必不再追問；<br/>因主為我缺欠，<br/>已經流血受審。<br/>',NULL,10919,10919);
INSERT INTO stanza VALUES('C683','1','耶穌愛我，從天降臨，<br/>甘心虛己，成為肉身。<br/>受盡譏誚、鞭打、辱罵，<br/>至終被釘十字苦架。<br/>',NULL,10920,10920);
INSERT INTO stanza VALUES('C683','chorus','耶穌死是為我，<br/>耶穌死是為我，<br/>為我，為我，為我，<br/>為我，耶穌死是為我。<br/>',NULL,10921,10921);
INSERT INTO stanza VALUES('C684','1','何能洗去我污點？<br/>無他，惟有耶穌寶血！<br/>何能恢復我完全？<br/>無他，惟有耶穌寶血！<br/>',NULL,10922,10922);
INSERT INTO stanza VALUES('C684','chorus','哦，這血泉何妙！<br/>洗我如雪白皎！<br/>別泉無此功效：<br/>無他，惟有耶穌寶血！<br/>',NULL,10923,10923);
INSERT INTO stanza VALUES('C684','2','要得清潔，我認定，<br/>無他，惟有耶穌寶血！<br/>要得赦免，我能憑，<br/>無他，惟有耶穌寶血！<br/>',NULL,10924,10924);
INSERT INTO stanza VALUES('C684','3','無何能贖我罪愆，<br/>無他，惟有耶穌寶血！<br/>無何能算我義善，<br/>無他，惟有耶穌寶血！<br/>',NULL,10925,10925);
INSERT INTO stanza VALUES('C684','4','我的聖潔和公義，<br/>無他，惟有耶穌寶血！<br/>我的盼望和安息，<br/>無他，惟有耶穌寶血！<br/>',NULL,10926,10926);
INSERT INTO stanza VALUES('C685','1','耶穌我救主作神羔羊，<br/>為罪人受死，罪債清償；<br/>將祂的寶血灑你身上，<br/>神必越過你，你免滅亡。<br/>',NULL,10927,10927);
INSERT INTO stanza VALUES('C685','chorus','我一見這血，<br/>我一見這血，<br/>我一見這血，<br/>我就必越過你，不毀滅！<br/>',NULL,10928,10928);
INSERT INTO stanza VALUES('C685','2','罪中的罪魁，耶穌肯救，<br/>凡祂所應許，祂必成就，<br/>在祂這血下，雖有愆尤，<br/>神必越過你，你得寬宥。<br/>',NULL,10929,10929);
INSERT INTO stanza VALUES('C685','3','審判要來到，無人免除；<br/>在神公義前，誰能立足？<br/>惟有讓祂血將你掩護，<br/>神必越過你，你免對簿。<br/>',NULL,10930,10930);
INSERT INTO stanza VALUES('C685','4','哦，憐憫何大！<br/>哦，愛無邊！<br/>哦，神聖恩典，<br/>豐盛、甘甜！<br/>在血蔭蔽下享受平安，<br/>神必越過你，你要頌讚！<br/>',NULL,10931,10931);
INSERT INTO stanza VALUES('C685','chorus','奇妙羔羊血，<br/>榮耀羔羊血，<br/>寶貴羔羊血，<br/>神一見羔羊血便逾越。<br/>',NULL,10932,10932);
INSERT INTO stanza VALUES('C686','1','今有一泉，血流盈滿，<br/>湧自耶穌肋邊；<br/>罪人只要一投此泉，<br/>立去全身罪愆。<br/>立去全身罪愆，<br/>立去全身罪愆，<br/>罪人只要一投此泉，<br/>立去全身罪愆。<br/>',NULL,10933,10933);
INSERT INTO stanza VALUES('C686','2','當日與主同釘一盜，<br/>曾見此泉功效；<br/>我罪即使不比他少，<br/>在此必能除掉。<br/>在此必能除掉，<br/>在此必能除掉，<br/>我罪即使不比他少，<br/>在此必能除掉。<br/>',NULL,10934,10934);
INSERT INTO stanza VALUES('C686','3','被殺羔羊，你的寶血，<br/>權能永不消滅，<br/>要將選民都洗清潔，<br/>永遠與罪隔絕。<br/>永遠與罪隔絕，<br/>永遠與罪隔絕，<br/>要將選民都洗清潔，<br/>永遠與罪隔絕。<br/>',NULL,10935,10935);
INSERT INTO stanza VALUES('C686','4','自從我見此泉之開，<br/>乃因你身受害，<br/>我便頌揚救贖大愛，<br/>頌揚至死不迨。<br/>頌揚至死不迨，<br/>頌揚至死不迨，<br/>我便頌揚救贖大愛，<br/>頌揚至死不迨。<br/>',NULL,10936,10936);
INSERT INTO stanza VALUES('C686','5','等到離世，拙口閉封，<br/>笨舌墓中寂靜，<br/>我要發出復活歌聲，<br/>讚你救贖大能。<br/>讚你救贖大能，<br/>讚你救贖大能，<br/>我要發出復活歌聲，<br/>讚你救贖大能。<br/>',NULL,10937,10937);
INSERT INTO stanza VALUES('C687','1','你願脫離良心的重擔麼？<br/>權能是在血，權能在血；<br/>你願免去公義的審判麼？<br/>奇妙的權能是在血。<br/>',NULL,10938,10938);
INSERT INTO stanza VALUES('C687','chorus','有權能！能！<br/>奇妙大權能，<br/>在羔羊之寶血！<br/>有權能！能！<br/>奇妙大權能，<br/>在聖潔羔羊之寶血！<br/>',NULL,10939,10939);
INSERT INTO stanza VALUES('C687','2','你願脫掉罪惡的羞愧麼？<br/>權能是在血，權能在血；<br/>你願去掉情慾的污穢麼？<br/>奇妙的權能是在血。<br/>',NULL,10940,10940);
INSERT INTO stanza VALUES('C687','3','你願潔淨猶如雪一般麼？<br/>權能是在血，權能在血；<br/>你願成聖好像主完全麼？<br/>奇妙的權能是在血。<br/>',NULL,10941,10941);
INSERT INTO stanza VALUES('C687','4','你願得著完全的救恩麼？<br/>權能是在血，權能在血；<br/>你願享受永生的福分麼？<br/>奇妙的權能是在血。<br/>',NULL,10942,10942);
INSERT INTO stanza VALUES('C687','5','惟有這泉能將罪全抹殺，<br/>權能是在血，權能在血；<br/>速投這泉，<br/>你眾罪必脫下，<br/>奇妙的權能是在血。<br/>',NULL,10943,10943);
INSERT INTO stanza VALUES('C688','1','曾否就主，<br/>求祂洗淨你罪愆？<br/>曾否在羔羊血洗清潔？<br/>曾否信主，<br/>接祂進入你心間？<br/>曾否在羔羊血洗清潔？<br/>',NULL,10944,10944);
INSERT INTO stanza VALUES('C688','chorus','曾否在羔羊血，<br/>在羔羊有能血洗清潔？<br/>你的衣裳<br/>是否潔白猶如雪？<br/>曾否在羔羊血洗清潔？<br/>',NULL,10945,10945);
INSERT INTO stanza VALUES('C688','2','曾否蒙主賜你<br/>赦罪的恩典？<br/>曾否在羔羊血洗清潔？<br/>曾否因主<br/>替你受死而心安？<br/>曾否在羔羊血洗清潔？<br/>',NULL,10946,10946);
INSERT INTO stanza VALUES('C688','3','救主來時，<br/>你的衣裳是否白？<br/>曾否在羔羊血洗清潔？<br/>榮耀冠冕，<br/>你的頭額配否戴？<br/>曾否在羔羊血洗清潔？<br/>',NULL,10947,10947);
INSERT INTO stanza VALUES('C688','4','加略泉源<br/>為著罪人正流淌，<br/>曾否在羔羊血洗清潔？<br/>污穢衣裳，<br/>不該還留在身上！<br/>曾否在羔羊血洗清潔？<br/>',NULL,10948,10948);
INSERT INTO stanza VALUES('C689','1','奇妙的愛，耶穌從天來，<br/>竟肯為我罪人十架受害；<br/>奇妙的愛，耶穌被裂開，<br/>白白為我罪人流血還債。<br/>',NULL,10949,10949);
INSERT INTO stanza VALUES('C690','1','愛何奇妙，恩何深廣，<br/>神差愛子來此；<br/>罪的審判歸祂身上，<br/>祂為你我代死。<br/>愛路，恩門，今正齊開，<br/>無別拯救捨此以外，<br/>神心依依等待你來，<br/>切莫拒祂恩愛。<br/>',NULL,10950,10950);
INSERT INTO stanza VALUES('C691','1','恩典！美妙聲音，<br/>悅耳，又慰人心，<br/>天上充滿祂的回音，<br/>地上也都聽聞。<br/>',NULL,10951,10951);
INSERT INTO stanza VALUES('C691','chorus','得救本乎恩！<br/>這是真福音；<br/>耶穌死為救罪人，<br/>為救我這罪人。<br/>',NULL,10952,10952);
INSERT INTO stanza VALUES('C691','2','恩典藏於基督，<br/>豐富口舌難述；<br/>恩典為我成功救贖，<br/>釋放我這罪奴。<br/>',NULL,10953,10953);
INSERT INTO stanza VALUES('C691','3','恩典贖我罪愆，<br/>使我得著赦免；<br/>恩典使我得見神面，<br/>得享天上平安。<br/>',NULL,10954,10954);
INSERT INTO stanza VALUES('C691','4','恩典賜我生命，<br/>使我有神性情；<br/>恩典使我永屬主名，<br/>脫離陰府幽冥。<br/>',NULL,10955,10955);
INSERT INTO stanza VALUES('C692','1','前有一官<br/>因見耶穌的神能，<br/>就在夜間<br/>來問作人的途徑；<br/>救主實實在在的<br/>對他說明：<br/>『你們必須重生！』<br/>',NULL,10956,10956);
INSERT INTO stanza VALUES('C692','chorus','『你們必須重生！<br/>你們必須重生！』<br/>救主實實在在的<br/>對他說明：<br/>『你們必須重生！』<br/>',NULL,10957,10957);
INSERT INTO stanza VALUES('C692','2','這話，<br/>世人務要鄭重而敬聽，<br/>這是救主所說，<br/>嚴肅而肯定，<br/>切莫輕忽<br/>祂這神聖的叮嚀：<br/>『你們必須重生！』<br/>',NULL,10958,10958);
INSERT INTO stanza VALUES('C692','3','哦，<br/>誰想要進那光明的天城，<br/>並同贖民<br/>享那榮耀的安寧，<br/>他就需要<br/>得那永遠的生命：<br/>『你們必須重生！』<br/>',NULL,10959,10959);
INSERT INTO stanza VALUES('C692','4','救主已被舉起，<br/>信者就得生；<br/>聖靈今在感動，<br/>順者必成聖；<br/>只要你肯悔改，<br/>相信主的名，<br/>你就必能重生！<br/>',NULL,10960,10960);
INSERT INTO stanza VALUES('C692','chorus','你就必能重生！<br/>你就必能重生！<br/>只要你肯悔改，<br/>相信主的名，<br/>你就必能重生！<br/>',NULL,10961,10961);
INSERT INTO stanza VALUES('C693','1','基督已經穿上人性，<br/>成為一人好像我；<br/>祂已釘死十字架上，<br/>亞當生命我得脫；<br/>祂且復活，化身聖靈，<br/>到我裡面來活著，<br/>為要作我生命。<br/>',NULL,10962,10962);
INSERT INTO stanza VALUES('C693','chorus','榮耀！榮耀！阿利路亞！<br/>榮耀！榮耀！阿利路亞！<br/>榮耀！榮耀！阿利路亞！<br/>基督是我生命！<br/>',NULL,10963,10963);
INSERT INTO stanza VALUES('C694','1','主是生命，主是復活，<br/>生命是祂掌握；<br/>祂已藉死毀壞死、魔，<br/>現今永遠活著；<br/>現今永遠活著，<br/>現今永遠、永遠活著。<br/>',NULL,10964,10964);
INSERT INTO stanza VALUES('C694','2','榮耀、榮耀，何等生命，<br/>我今已經得著！<br/>黑暗、死亡、罪的權勢，<br/>現今都已消沒！<br/>現今都已消沒！<br/>現今都已、都已消沒！<br/>',NULL,10965,10965);
INSERT INTO stanza VALUES('C695','1','救主為我死，<br/>何等的奇妙！<br/>我本該定罪，<br/>祂使我逍遙；<br/>祂再三的說：<br/>人若是信靠，<br/>已經出死入生！<br/>',NULL,10966,10966);
INSERT INTO stanza VALUES('C695','chorus','真福音，真福音，<br/>你們快來聽！<br/>真福音，真福音，<br/>基督已講明：<br/>人若肯相信神兒子的名，<br/>已經出死入生！<br/>',NULL,10967,10967);
INSERT INTO stanza VALUES('C695','2','一切的虧欠，<br/>祂替我還清；<br/>一切的污穢，<br/>祂替我洗淨；<br/>祂特意的說：<br/>人若信祂名，<br/>已經出死入生！<br/>',NULL,10968,10968);
INSERT INTO stanza VALUES('C695','3','我雖滿罪惡，<br/>我能信祂名；<br/>我雖極軟弱，<br/>我能受祂靈；<br/>朋友，<br/>這真是何等的榮幸！<br/>已經出死入生！<br/>',NULL,10969,10969);
INSERT INTO stanza VALUES('C695','4','我雖頂不堪，<br/>我不肯生疑；<br/>到祂那裡的，<br/>祂永不絕棄；<br/>凡是信祂的，<br/>都當時常記：<br/>已經出死入生！<br/>',NULL,10970,10970);
INSERT INTO stanza VALUES('C696','1','聽阿，有一隱藏奧祕，<br/>歷世歷代人未知悉！<br/>若肯接受這一奧祕，<br/>就與基督成一！<br/>榮耀、榮耀，阿利路亞！<br/>榮耀、榮耀，阿利路亞！<br/>若肯接受這一奧祕，<br/>就與基督成一！<br/>',NULL,10971,10971);
INSERT INTO stanza VALUES('C697','1','大喜信息！驚天動地！<br/>神願與人住在一起！<br/>人雖卑鄙，祂仍屬意；<br/>人雖不堪，祂仍不棄。<br/>',NULL,10972,10972);
INSERT INTO stanza VALUES('C697','chorus','大信息！真奧祕！<br/>神願與人住在一起！<br/>永遠合一，永遠安息，<br/>永遠享受神的自己。<br/>大信息！真奧祕！<br/>神願與人住在一起！<br/>',NULL,10973,10973);
INSERT INTO stanza VALUES('C698','1','我主耶穌是生命源，<br/>我主耶穌是活水泉；<br/>喝了這水，主曾明說，<br/>就永遠永遠不再渴。<br/>難道永遠不再渴？<br/>是！永遠不再渴！<br/>難道永遠不再渴？<br/>是！永遠不再渴！<br/>喝了這水，主曾明說，<br/>就永遠永遠不再渴。<br/>',NULL,10974,10974);
INSERT INTO stanza VALUES('C698','2','我主耶穌是永生倉，<br/>我主耶穌是生命糧；<br/>喫了這糧，主曾明說，<br/>就永遠永遠不再餓。<br/>難道永遠不再餓？<br/>是！永遠不再餓！<br/>難道永遠不再餓？<br/>是！永遠不再餓！<br/>喫了這糧，主曾明說，<br/>就永遠永遠不再餓。<br/>',NULL,10975,10975);
INSERT INTO stanza VALUES('C698','3','我主耶穌是復活王，<br/>我主耶穌是生命皇；<br/>凡信祂的，主曾明示，<br/>就永遠永遠不再死。<br/>難道永遠不再死？<br/>是！永遠不再死！<br/>難道永遠不再死？<br/>是！永遠不再死！<br/>凡信祂的，主曾明示，<br/>就永遠永遠不再死。<br/>',NULL,10976,10976);
INSERT INTO stanza VALUES('C699','1','你的罪雖像硃紅，<br/>主必使變成雪白。<br/>你的罪雖像硃紅，<br/>主必使變成雪白。<br/>你罪雖紅如丹顏，<br/>必白羊毛般。<br/>你的罪雖像硃紅，<br/>你的罪雖像硃紅，<br/>主必使變成雪白，<br/>主必使變成雪白。<br/>',NULL,10977,10977);
INSERT INTO stanza VALUES('C699','2','你要聽主的呼聲，<br/>當回轉歸向救主！<br/>你要聽主的呼聲，<br/>當回轉歸向救主！<br/>愛主招呼耐等待，<br/>你何不歸來？<br/>你要聽主的呼聲，<br/>你要聽主的呼聲，<br/>當回轉歸向救主！<br/>當回轉歸向救主！<br/>',NULL,10978,10978);
INSERT INTO stanza VALUES('C699','3','你的罪，主必赦免，<br/>必永遠不再記念。<br/>你的罪，主必赦免，<br/>必永遠不再記念。<br/>你罪，主必全塗抹，<br/>如厚雲滅沒。<br/>你的罪，主必赦免，<br/>你的罪，主必赦免，<br/>必永遠不再記念，<br/>必永遠不再記念。<br/>',NULL,10979,10979);
INSERT INTO stanza VALUES('C700','1','若盡得世界，<br/>而失去救主，<br/>豈值得一日在此活著？<br/>在這些就要過去之物中，<br/>安息與安慰豈能尋得？<br/>若盡得世界，<br/>而失去救主，<br/>所得的一切彀用一生？<br/>地上所有的快樂，<br/>也不能比<br/>那充滿了主的生命！<br/>',NULL,10980,10980);
INSERT INTO stanza VALUES('C700','2','縱令你滿得財富和愛情，<br/>無論遠或近也都知名，<br/>前面仍無望，<br/>仍無一港口<br/>讓你這驚船可以靠停。<br/>若盡得世界，<br/>而失去救主，<br/>就是那為你受死的主，<br/>是否這世界能供一避所，<br/>給你逃進去永遠居住？<br/>',NULL,10981,10981);
INSERT INTO stanza VALUES('C700','3','何等的虛空！<br/>若沒有救主：<br/>地上盡都是罪惡、苦難！<br/>永世何黑暗！<br/>若沒有救主：<br/>黑夜與眼淚，<br/>痛苦無邊！<br/>若沒有救主，<br/>雖暫能活著，<br/>但到要死時，<br/>將要怎辦？哦，<br/>必要面對那無主幽谷！<br/>且一直無主，<br/>直到永遠！<br/>',NULL,10982,10982);
INSERT INTO stanza VALUES('C700','4','在主得一切，<br/>何等的快樂！<br/>何等能安撫傷痛心田！<br/>並無一罪過祂不肯赦免，<br/>也無一憂患祂不承擔！<br/>若你只有主，<br/>只有主基督，<br/>全地除了祂，你無他物，<br/>那，在祂裡面，<br/>你就有一切，<br/>應付你需要，無限豐富。<br/>',NULL,10983,10983);
INSERT INTO stanza VALUES('C701','1','日光下勞碌，有何益？<br/>令人厭，萬事無新奇！<br/>一過去，無人再記憶！<br/>虛空的虛空！<br/>',NULL,10984,10984);
INSERT INTO stanza VALUES('C701','chorus','空空空！空空空！<br/>空空空！空空空！<br/>凡事都虛空，<br/>如捉影，如捕風。<br/>',NULL,10985,10985);
INSERT INTO stanza VALUES('C701','2','人生的經驗是苦難：<br/>多有了智慧，多愁煩！<br/>增加了知識，增悲歎！<br/>虛空的虛空！<br/>',NULL,10986,10986);
INSERT INTO stanza VALUES('C701','3','富有與享受，有何效？<br/>縱你有妻子與財寶，<br/>也一樣連累你煩惱！<br/>虛空的虛空！<br/>',NULL,10987,10987);
INSERT INTO stanza VALUES('C701','4','勞苦成愁苦，夜不安：<br/>你所得，即使不遭患，<br/>死來了，一切也是完！<br/>虛空的虛空！<br/>',NULL,10988,10988);
INSERT INTO stanza VALUES('C701','5','趁幼年，當念造你主！<br/>敬愛祂，纔是樂與福！<br/>有了祂，心滿意也足！<br/>惟祂不虛空！<br/>',NULL,10989,10989);
INSERT INTO stanza VALUES('C701','chorus','沒有主，就虛空，<br/>有了主，就不空！<br/>凡事都虛空！<br/>惟有主，不虛空。<br/>',NULL,10990,10990);
INSERT INTO stanza VALUES('C702','1','多患難，常愁煩，<br/>勞苦負重擔；<br/>人生充滿悲傷、悽慘，<br/>歎息無平安。<br/>',NULL,10991,10991);
INSERT INTO stanza VALUES('C702','2','惟有主，惟有主，<br/>能解你愁苦；<br/>不要遲誤，不要躊躇，<br/>來此得安撫。<br/>',NULL,10992,10992);
INSERT INTO stanza VALUES('C703','1','永遠永遠，永永遠遠！<br/>你要如何過此永遠？<br/>當先解決這個問題，<br/>免得將來痛悔無及！<br/>得救、沉淪都是永遠，<br/>你要如何過此永遠？<br/>',NULL,10993,10993);
INSERT INTO stanza VALUES('C703','2','永遠永遠，永永遠遠！<br/>你要如何過此永遠？<br/>多人現在揀選耶穌，<br/>離開他們一切罪途，<br/>相信救主，接受救恩，<br/>得了重生，親近父神。<br/>',NULL,10994,10994);
INSERT INTO stanza VALUES('C703','3','永遠永遠，永永遠遠！<br/>你要如何過此永遠？<br/>你若不入得救恩門，<br/>滅亡道上仍然馳奔，<br/>現在請你仔細思量，<br/>至終結局將要怎樣？<br/>',NULL,10995,10995);
INSERT INTO stanza VALUES('C703','4','永遠永遠，永永遠遠！<br/>你要如何過此永遠？<br/>是在天城看見主面？<br/>是在地獄受苦中間？<br/>極其嚴肅，極其要緊，<br/>一次定規，永遠定準。<br/>',NULL,10996,10996);
INSERT INTO stanza VALUES('C703','5','永遠永遠，永永遠遠！<br/>你要如何過此永遠？<br/>回頭信主趁有光明，<br/>不被定罪，出死入生，<br/>你就可以歡然應說：<br/>我要永遠住在神國。<br/>',NULL,10997,10997);
INSERT INTO stanza VALUES('C704','1','誰能免我死亡兇路？<br/>惟耶穌！惟耶穌！<br/>誰能除我地獄永苦？<br/>惟耶穌！<br/>不滅火，無期禍！<br/>誰能去我如此痛楚？<br/>惟耶穌！<br/>',NULL,10998,10998);
INSERT INTO stanza VALUES('C704','2','誰能引我生命榮途？<br/>惟耶穌！惟耶穌！<br/>誰能給我屬天永福？<br/>惟耶穌！<br/>無死亡，無悲傷！<br/>誰能賜我如此豐富？<br/>惟耶穌！<br/>',NULL,10999,10999);
INSERT INTO stanza VALUES('C705','1','所有罪人都是罪囚，<br/>已中死亡毒鉤；<br/>除信主是自有永有，<br/>必在罪中死休。<br/>神的兒子自有永有，<br/>惟祂能釋罪囚，<br/>能使罪囚得著自由，<br/>自由直到永久。<br/>',NULL,11000,11000);
INSERT INTO stanza VALUES('C706','1','何等柔細慈愛，<br/>耶穌在呼召，<br/>呼召他，也呼召你！<br/>祂在天上等待，<br/>也來地尋找，<br/>尋找他，也尋找你！<br/>',NULL,11001,11001);
INSERT INTO stanza VALUES('C706','chorus','來家！來家！<br/>你這疲乏人，來家！<br/>何等懇切慈愛，<br/>耶穌在呼召，<br/>呼召你，罪人，來家！<br/>',NULL,11002,11002);
INSERT INTO stanza VALUES('C706','2','為何糊塗遲延，<br/>不聽祂懇勸，<br/>懇勸他，也懇勸你？<br/>為何躊躇留戀，<br/>不理祂恩眷，<br/>恩眷他，也恩眷你？<br/>',NULL,11003,11003);
INSERT INTO stanza VALUES('C706','3','時間急急在逝，<br/>機會要越過，<br/>越過他，也越過你；<br/>陰影漸漸在集，<br/>死亡要來捉，<br/>來捉他，也來捉你。<br/>',NULL,11004,11004);
INSERT INTO stanza VALUES('C706','4','哦，那奇妙之愛，<br/>祂已經應許，<br/>應許他，也應許你；<br/>雖然污穢敗壞，<br/>祂仍必憐恤，<br/>憐恤他，也憐恤你。<br/>',NULL,11005,11005);
INSERT INTO stanza VALUES('C707','1','我聽我的救主吩咐：<br/>『跟從我，跟從我，<br/>跟從我；』<br/>祂的聲音終日招呼：<br/>『跟從我，跟從我，<br/>跟從我；<br/>為你，我走艱辛路途，<br/>為你，我曾性命不顧，<br/>並嘗苦膽免你重負，<br/>跟從我，跟從我，<br/>跟從我。<br/>',NULL,11006,11006);
INSERT INTO stanza VALUES('C707','2','你雖有罪，我必寬宥，<br/>跟從我，跟從我，<br/>跟從我；<br/>脫離捆綁，你必自由，<br/>跟從我，跟從我，<br/>跟從我；<br/>人事變動不甚長久，<br/>我作你神引導無休，<br/>作你喜樂直至千秋，<br/>跟從我，跟從我，<br/>跟從我。<br/>',NULL,11007,11007);
INSERT INTO stanza VALUES('C707','3','帶你罣慮到我這裡，<br/>跟從我，跟從我，<br/>跟從我；<br/>你的重擔放我手臂，<br/>跟從我，跟從我，<br/>跟從我；<br/>你的疑懼息我胸臆，<br/>你的將來向我依倚，<br/>我必親手拭你淚滴，<br/>跟從我，跟從我，<br/>跟從我。』<br/>',NULL,11008,11008);
INSERT INTO stanza VALUES('C708','1','耶穌發慈聲要召你回來，<br/>今日召你，今日召你！<br/>為何仍迷蒙，<br/>遠離主慈懷，<br/>終日流蕩在苦地？<br/>',NULL,11009,11009);
INSERT INTO stanza VALUES('C708','chorus','今日召你！今日召你！<br/>耶穌今召你，<br/>今日發慈聲呼召你！<br/>',NULL,11010,11010);
INSERT INTO stanza VALUES('C708','2','耶穌在呼召勞者來得息，<br/>今日召你，今日召你！<br/>重擔卸給祂，<br/>無倚成有倚，<br/>祂要歡迎不絕棄。<br/>',NULL,11011,11011);
INSERT INTO stanza VALUES('C708','3','耶穌在等待你來得赦免，<br/>今日等你，今日等你！<br/>可帶你罪來，<br/>俯伏主腳前；<br/>現在就來莫遲疑！<br/>',NULL,11012,11012);
INSERT INTO stanza VALUES('C708','4','耶穌仍呼召，<br/>何不就聽從？今日聽祂，今日聽祂！<br/>來求告祂名，<br/>蒙恩必無窮；<br/>祂要賜福無復加。<br/>',NULL,11013,11013);
INSERT INTO stanza VALUES('C709','1','無論何人願意，<br/>就可得救恩，<br/>這是天上來的佳音<br/>給罪人；<br/>趕快將這信息<br/>向萬人宣陳：<br/>無論何人都可來。<br/>',NULL,11014,11014);
INSERT INTO stanza VALUES('C709','chorus','『無論甚麼人，<br/>無論甚麼人，』<br/>這是慈愛天父<br/>喚浪子回家；<br/>『無論老幼、男婦，<br/>都不必代價，<br/>無論甚麼人可來。』<br/>',NULL,11015,11015);
INSERT INTO stanza VALUES('C709','2','無論何人想來，<br/>不必稍遲延；<br/>恩門已經大開，<br/>進者可隨便；<br/>耶穌真是救主，<br/>祂已發恩言：<br/>無論何人都可來。<br/>',NULL,11016,11016);
INSERT INTO stanza VALUES('C709','3','無論何人願意，<br/>就可得永生；<br/>無論何人願意，<br/>這話語有徵；<br/>無論何人願意，<br/>這應許無更，<br/>無論何人都可來。<br/>',NULL,11017,11017);
INSERT INTO stanza VALUES('C710','1','叩門，叩門，誰在外？<br/>等著，等著，何忍耐！<br/>遠來佳客君尊氣概，<br/>生平未見這丰采；<br/>我的心阿，既感奇哉，<br/>何不立即把門開？<br/>',NULL,11018,11018);
INSERT INTO stanza VALUES('C710','2','叩門，叩門，還在外！<br/>等著，等著，真忍耐！<br/>但是這門還是難開，<br/>因有蔓草和藤艾，<br/>重重纏塞，層層阻礙，<br/>金已生銹，木已壞。<br/>',NULL,11019,11019);
INSERT INTO stanza VALUES('C710','3','叩門，叩門，仍在外！<br/>等著，等著，太忍耐！<br/>被釘之手連叩不怠，<br/>荊棘冠冕似仍戴，<br/>目中仍露請求之愛，<br/>原是救主等門開。<br/>',NULL,11020,11020);
INSERT INTO stanza VALUES('C711','1','聽阿，救主叩門，叩門，<br/>不住叩心門！<br/>為何你仍硬心，硬心，<br/>不理這聲音？<br/>火速起來開心門，<br/>火速請祂進；<br/>祂要進入你心，你心，<br/>賜給你救恩。<br/>',NULL,11021,11021);
INSERT INTO stanza VALUES('C711','chorus','請主進！請主進！<br/>祂在心外叩門；<br/>請主進！哦，請主進！<br/>祂必進你心。<br/>',NULL,11022,11022);
INSERT INTO stanza VALUES('C711','2','請聽祂說：<br/>『罪人，罪人，<br/>就我得安息；<br/>我曾為你捨身，捨身，<br/>死在髑髏地；<br/>為要使你蒙恩寵，<br/>流血將你買；<br/>你罪雖像硃紅，硃紅，<br/>也能變雪白。』<br/>',NULL,11023,11023);
INSERT INTO stanza VALUES('C711','3','為何你仍猶豫，猶豫，<br/>讓主等門外？<br/>要知機會一去，一去，<br/>永遠不再來！<br/>祂既對你滿恩情，<br/>莫把祂心傷；<br/>祂願賜你生命，生命，<br/>何必等死亡？<br/>',NULL,11024,11024);
INSERT INTO stanza VALUES('C711','4','如果你仍遲延，遲延，<br/>終必有一天，<br/>懊悔為時已晚，已晚，<br/>哀呼主眷憐；<br/>那時恩門已經關，<br/>哀呼必徒然！<br/>為何不趁今天，今天，<br/>請主進心間？<br/>',NULL,11025,11025);
INSERT INTO stanza VALUES('C712','1','一百隻羊，少了一口，<br/>良牧耶穌悲愁，<br/>不顧山路崎嶇難走，<br/>冒險前往尋救。<br/>迷羊回頭！迷羊回頭！<br/>前面盡是陷阱、猛獸；<br/>火速回來，勿再逗遛！<br/>',NULL,11026,11026);
INSERT INTO stanza VALUES('C713','1','失迷的羊，你今在那裏？<br/>救主今天正在尋找你！<br/>一百隻羊內中缺一隻，<br/>莫非就是你？<br/>',NULL,11027,11027);
INSERT INTO stanza VALUES('C713','chorus','莫非就是你？<br/>莫非就是你？<br/>一百隻羊內中缺一隻，<br/>莫非就是你？<br/>',NULL,11028,11028);
INSERT INTO stanza VALUES('C713','2','失落的人，你今在那裏？<br/>聖靈今天正在尋找你！<br/>十塊銀錢內中缺一塊，<br/>莫非就是你？<br/>',NULL,11029,11029);
INSERT INTO stanza VALUES('C713','chorus','莫非就是你？<br/>莫非就是你？<br/>十塊銀錢內中缺一塊，<br/>莫非就是你？<br/>',NULL,11030,11030);
INSERT INTO stanza VALUES('C713','3','浪蕩的人，你有無安息？<br/>家中快樂正在需要你！<br/>天父在家整天巴望的，<br/>莫非就是你？<br/>',NULL,11031,11031);
INSERT INTO stanza VALUES('C713','chorus','莫非就是你？<br/>莫非就是你？<br/>天父在家整天巴望的，<br/>莫非就是你？<br/>',NULL,11032,11032);
INSERT INTO stanza VALUES('C714','1','此時當就耶穌，<br/>耶穌在此；<br/>不可再行死路，<br/>耶穌在此；<br/>眾人攏總當來，<br/>時日機會不再，<br/>不可遲延等待，<br/>耶穌在此。<br/>',NULL,11033,11033);
INSERT INTO stanza VALUES('C714','2','此時當就耶穌，<br/>耶穌在此；<br/>不可因循自誤，<br/>耶穌在此；<br/>救主歡喜施恩，<br/>救你免得淪沉；<br/>不可再戀紅塵，<br/>耶穌在此。<br/>',NULL,11034,11034);
INSERT INTO stanza VALUES('C714','3','此時當就耶穌，<br/>耶穌在此；<br/>不可疑惑躊躇，<br/>耶穌在此；<br/>罪惡雖然極重，<br/>救主仍然愛鍾；<br/>不必絕望惶恐，<br/>耶穌在此。<br/>',NULL,11035,11035);
INSERT INTO stanza VALUES('C714','4','此時當就耶穌，<br/>耶穌在此；<br/>天下再無別路，<br/>耶穌在此；<br/>救主成功救贖，<br/>救主尚在招呼；<br/>你當火速就主，<br/>耶穌在此。<br/>',NULL,11036,11036);
INSERT INTO stanza VALUES('C715','1','你墮落罪惡境，<br/>歷盡了苦情，<br/>為何不立悔改，<br/>脫此苦境？<br/>邪路上你在行，<br/>前面多陷阱，<br/>不回頭，勢難免，<br/>墮入深坑！<br/>',NULL,11037,11037);
INSERT INTO stanza VALUES('C715','chorus','主渴望拯救你！<br/>主等候救你！<br/>為何不趁今天讓主救你？<br/>',NULL,11038,11038);
INSERT INTO stanza VALUES('C715','2','惡者手你安臥，<br/>被任意加禍，<br/>你雖想，卻不能<br/>脫他掌握；<br/>他擺佈，他弄捉，<br/>使你受困惑，<br/>如魚鳥被圈捕，<br/>難逃網羅！<br/>',NULL,11039,11039);
INSERT INTO stanza VALUES('C715','3','殘歲月，增卻減！<br/>人生像雲煙！<br/>怎能知，朝夕間<br/>不會消散？<br/>死亡後，有審判！<br/>地獄又緊聯！<br/>你如何能逃避<br/>永火烈焰？<br/>',NULL,11040,11040);
INSERT INTO stanza VALUES('C715','4','主受死，把魔傷，<br/>並將罪擔當，<br/>又復活，升天上，<br/>作主作王；<br/>死亡廢，生命彰，<br/>你可得釋放，<br/>何必再受捆綁，<br/>等待淪亡？<br/>',NULL,11041,11041);
INSERT INTO stanza VALUES('C715','5','你雖然使主憂，<br/>祂仍願拯救，<br/>祂忍耐，祂渴望，<br/>等你回頭；<br/>你雖然拒不受，<br/>祂仍在等候，<br/>祂等候你悔改，<br/>相信得救。<br/>',NULL,11042,11042);
INSERT INTO stanza VALUES('C716','1','耶穌今留步，<br/>要等候你來，<br/>祂已等候好久長；<br/>祂這樣等候，<br/>是望你悔改，<br/>得享永生免滅亡。<br/>',NULL,11043,11043);
INSERT INTO stanza VALUES('C716','chorus','歡迎你來，你來，<br/>無論甚麼人，<br/>這是救主的呼召；<br/>祂能、祂肯、祂等，<br/>等著施救恩，<br/>不過只要你信靠。<br/>',NULL,11044,11044);
INSERT INTO stanza VALUES('C716','2','你雖然不羈，<br/>流蕩已經遠，<br/>沉溺罪中已經深，<br/>祂仍然等候，<br/>忍耐著申勸，<br/>要得你這疲倦人。<br/>',NULL,11045,11045);
INSERT INTO stanza VALUES('C716','3','你雖已多次拒祂的恩召，<br/>多次使祂空眷顧，<br/>祂的愛不因你冷落生惱，<br/>今又向你來催促。<br/>',NULL,11046,11046);
INSERT INTO stanza VALUES('C716','4','你應當服降，<br/>服降這個愛，<br/>耶穌現在等候你；<br/>祂既仍招呼：<br/>『請你就我來！』<br/>你當回應：『我願意。』<br/>',NULL,11047,11047);
INSERT INTO stanza VALUES('C717','1','被罪壓害人人請來，<br/>被罪壓害人人要來，<br/>救主在此等待；<br/>祂要救你，安你心懷，<br/>只要你肯信祂。<br/>',NULL,11048,8);
INSERT INTO stanza VALUES('C717','chorus','只要信祂！只要信祂！<br/>現在要信祂！<br/>祂要救你！祂要救你！<br/>現在要救你！<br/>',NULL,11049,9);
INSERT INTO stanza VALUES('C717','2','耶穌替你釘死十架，<br/>流血作你贖價；<br/>救贖已成不用代價，<br/>只要你肯信祂。<br/>',NULL,11050,10);
INSERT INTO stanza VALUES('C717','3','耶穌對你滿有慈愛，<br/>恩門為你大開；<br/>機會一過未必再來，<br/>請你快來信祂。<br/>',NULL,11051,11);
INSERT INTO stanza VALUES('C717','chorus','快來信祂！快來信祂！<br/>現在快信祂！<br/>祂能救你！祂能救你！<br/>現在能救你！<br/>',NULL,11052,12);
INSERT INTO stanza VALUES('C717','4','不久離世，結局怎樣，<br/>得救或是滅亡？<br/>永生何樂！永死難當！<br/>請你快來信祂。<br/>',NULL,11053,13);
INSERT INTO stanza VALUES('C718','1','哦，不要棄絕主恩道，<br/>也不要閉目拒光照；<br/>親愛的，切莫心硬著！<br/>得救當趁早！<br/>',NULL,11054,11054);
INSERT INTO stanza VALUES('C718','chorus','何必再遲延？<br/>何必再遲延？<br/>你要得救援，<br/>何必再遲延？<br/>',NULL,11055,11055);
INSERT INTO stanza VALUES('C718','2','明天的太陽不一定<br/>還照你受欺的眼睛；<br/>今夜是時機！該聰明！<br/>要信，何必等！<br/>',NULL,11056,11056);
INSERT INTO stanza VALUES('C718','chorus','何不趁今夜？<br/>何不趁今夜？<br/>你要免罪孽，<br/>何不趁今夜？<br/>',NULL,11057,11057);
INSERT INTO stanza VALUES('C718','3','這世界有何可留戀？<br/>不會有新事，純又甜；<br/>請你來嘗嘗主恩典！<br/>要來，趁今天！<br/>副)<br/>何不趁今天？<br/>何不趁今天？<br/>你要蒙恩典，<br/>何不趁今天？<br/>',NULL,11058,11058);
INSERT INTO stanza VALUES('C718','4','我們的恩主滿慈仁，<br/>從未曾拒絕人來信；<br/>祂總是立刻施救恩！<br/>信罷，請放心！<br/>',NULL,11059,11059);
INSERT INTO stanza VALUES('C718','chorus','信罷，趁現在！<br/>時過，不再來！<br/>要信，何須待？<br/>時過，不再來！<br/>',NULL,11060,11060);
INSERT INTO stanza VALUES('C719','1','你若願意脫離罪的苦情，<br/>讓基督來進入你心；<br/>你若渴慕得著新的人生，<br/>讓基督來進入你心。<br/>',NULL,11061,11061);
INSERT INTO stanza VALUES('C719','chorus','現在，將疑惑拋棄；<br/>現在，將救主投倚；<br/>現在，將心門開啟；<br/>讓基督來進入你心。<br/>',NULL,11062,11062);
INSERT INTO stanza VALUES('C719','2','若覺惡性，<br/>自己不能治服，<br/>讓基督來進入你心；<br/>若感虛空，<br/>世界不能滿足，<br/>讓基督來進入你心。<br/>',NULL,11063,11063);
INSERT INTO stanza VALUES('C719','3','若要黑暗變成無上光明，<br/>讓基督來進入你心；<br/>若要病痛轉為永久康寧，<br/>讓基督來進入你心。<br/>',NULL,11064,11064);
INSERT INTO stanza VALUES('C719','4','若要心中充滿快樂歡喜，<br/>讓基督來進入你心；<br/>若要全人進入平靜安息，<br/>讓基督來進入你心。<br/>',NULL,11065,11065);
INSERT INTO stanza VALUES('C720','1','仰望耶穌，將亡人！<br/>望就活！望就活！<br/>仰望救主已捨身，<br/>望就活！<br/>看祂木上被舉著，<br/>望就活！望就活！<br/>聽祂在說：『仰望我！』<br/>望就活！<br/>',NULL,11066,11066);
INSERT INTO stanza VALUES('C720','chorus','看哪！救主舉木上，<br/>仰望救主醫死傷；<br/>望就活了！何必亡？<br/>望就活！<br/>',NULL,11067,11067);
INSERT INTO stanza VALUES('C720','2','你雖邪惡又污穢，<br/>望就活！望就活！<br/>如望，就必脫眾罪，<br/>望就活！<br/>久受撒但的捆綁，<br/>望就活！望就活！<br/>一望，就必得釋放，<br/>望就活！<br/>',NULL,11068,11068);
INSERT INTO stanza VALUES('C720','3','你雖流蕩已久遠，<br/>望就活！望就活！<br/>卻莫硬心在今天，<br/>望就活！<br/>救主巴望你回轉！<br/>望就活！望就活！<br/>為何忍心仍遲延？<br/>望就活！<br/>',NULL,11069,11069);
INSERT INTO stanza VALUES('C721','1','貧窮、軟弱、悲傷、<br/>憂愁，<br/>親愛罪人請你來！<br/>耶穌等著要施拯救，<br/>滿了能力和憐愛；<br/>祂能救你！祂能救你！<br/>祂肯救你，莫疑猜。<br/>',NULL,11070,11070);
INSERT INTO stanza VALUES('C721','2','祂要歡迎，來罷，放心，<br/>祂不棄絕任何人；<br/>實在懊悔，實在相信，<br/>你就必定能蒙恩；<br/>不用代價！不用代價！<br/>就可進入得救門。<br/>',NULL,11071,11071);
INSERT INTO stanza VALUES('C721','3','莫讓良心使你徘徊，<br/>或想怎樣纔配來；<br/>你已『配來』，<br/>若你理會：<br/>你是需要祂的愛；<br/>無別條件！無別條件！<br/>恩門是為罪人開。<br/>',NULL,11072,11072);
INSERT INTO stanza VALUES('C721','4','你心煩悶，你心悒怏，<br/>疲倦、痛苦、常失敗；<br/>如果你要等到改良，<br/>你就永遠不會來；<br/>耶穌釘死，耶穌釘死，<br/>是為罪人贖罪債。<br/>',NULL,11073,11073);
INSERT INTO stanza VALUES('C721','5','請你想起客西馬尼，<br/>救主如何流血汗！<br/>請你聽祂在髑髏地，<br/>如何臨死大聲喊：<br/>『已經成了！』<br/>『已經成了！』<br/>罪人你今能無感？<br/>',NULL,11074,11074);
INSERT INTO stanza VALUES('C721','6','祂的流血已經滿足<br/>你神公義的要求；<br/>應當信服，完全信服，<br/>罪過就都得免宥；<br/>惟有耶穌，惟有耶穌，<br/>能作罪人的朋友。<br/>',NULL,11075,11075);
INSERT INTO stanza VALUES('C722','1','飄渺人生何短暫，<br/>好似浮雲現即散，<br/>又似幻夢醒就完：<br/>要及時！<br/>時日飛逝在宣言：<br/>轉瞬就到死亡線，<br/>再遲必在地獄間：<br/>要及時！<br/>',NULL,11076,11076);
INSERT INTO stanza VALUES('C722','chorus','要及時！要及時！<br/>當今耶穌在召喚：<br/>要及時！<br/>若在罪中仍流連，<br/>只怕恩門向你關，<br/>那時呼救已太晚：<br/>要及時！<br/>',NULL,11077,11077);
INSERT INTO stanza VALUES('C722','2','誰是智者，該想看：<br/>鮮花朝豔暮凋殘，<br/>英年要去何能挽？<br/>要及時！<br/>哦，我求你早打算，<br/>免得過了死亡線，<br/>全人喪在地獄間：<br/>要及時！<br/>',NULL,11078,11078);
INSERT INTO stanza VALUES('C722','3','聖靈仍在把你感，<br/>時常與你來爭戰，<br/>何不降服得平安？<br/>要及時！<br/>救主等候賜恩典，<br/>願意救你免悲慘；<br/>你若躊躇何愚頑！<br/>要及時！<br/>',NULL,11079,11079);
INSERT INTO stanza VALUES('C722','4','罪人，請聽我忠言，<br/>莫把救恩視等閒，<br/>速把救主來揀選：<br/>要及時！<br/>來投耶穌懷裏面，<br/>來接基督進心間，<br/>來就救主趁今天：<br/>要及時！<br/>',NULL,11080,11080);
INSERT INTO stanza VALUES('C723','1','耶穌恩主是人惟一需要：<br/>祂是神成肉身生於馬槽，<br/>在世為人歷盡萬般苦惱，<br/>末了被釘木架，<br/>為救你將命傾倒。<br/>',NULL,11081,11081);
INSERT INTO stanza VALUES('C723','chorus','需要耶穌！需要耶穌！<br/>人人都需要耶穌！<br/>要脫罪擔需要主，<br/>要得平安需要主，<br/>要免沉淪得永生，<br/>你需要耶穌！<br/>',NULL,11082,11082);
INSERT INTO stanza VALUES('C723','2','祂已復活，<br/>升天永作中保，<br/>差遣聖靈下來將你尋找；<br/>你若來信，<br/>將祂尊名求告，<br/>祂必賜你恩典，<br/>滿足你一切需要。<br/>',NULL,11083,11083);
INSERT INTO stanza VALUES('C723','3','你心雖暗，<br/>祂能徹底光照；<br/>你罪雖多，<br/>祂必全都寬饒；<br/>祂血能將你的污穢除掉；<br/>祂靈必賜生命，<br/>來將你軟弱盡消。<br/>',NULL,11084,11084);
INSERT INTO stanza VALUES('C723','4','你的人生常感有所缺少；<br/>有一需要，<br/>你尚莫名其妙；<br/>你這需要，<br/>惟從耶穌得到：<br/>祂能滿足你心，<br/>除去你虛空無聊。<br/>',NULL,11085,11085);
INSERT INTO stanza VALUES('C723','chorus','需要耶穌！需要耶穌！<br/>人人都需要耶穌！<br/>要免虛空需要主，<br/>要得滿足需要主！<br/>要使人生有意義，<br/>你需要耶穌！<br/>',NULL,11086,11086);
INSERT INTO stanza VALUES('C723','5','人在世上，<br/>盡是勞苦煩惱；<br/>遭遇困苦，<br/>又是無求無告；<br/>世事虛謊，<br/>還有甚麼可靠？<br/>這些都是說出：<br/>耶穌是人的需要！<br/>',NULL,11087,11087);
INSERT INTO stanza VALUES('C723','6','世人不分智愚、<br/>男女、老少，<br/>都已犯罪，<br/>虧缺神的榮耀；<br/>除信耶穌，<br/>別無得救之道，<br/>因為惟有耶穌<br/>能滿足神、人需要。<br/>',NULL,11088,11088);
INSERT INTO stanza VALUES('C724','1','照我本相，無善足稱，<br/>惟你流血，替我受懲，<br/>並且召我就你得生；<br/>救主耶穌，我來！我來！<br/>',NULL,11089,11089);
INSERT INTO stanza VALUES('C724','2','照我本相，不必等到<br/>自己改變比前更好，<br/>因你寶血除罪可靠；<br/>救主耶穌，我來！我來！<br/>',NULL,11090,11090);
INSERT INTO stanza VALUES('C724','3','照我本相，反覆不定，<br/>疑信參半，如浪不平，<br/>內有罣慮，外有惡行；<br/>救主耶穌，我來！我來！<br/>',NULL,11091,11091);
INSERT INTO stanza VALUES('C724','4','照我本相，<br/>貧、瞎、可憐；<br/>我真需要你的恩典，<br/>感我惡心，開我盲眼；<br/>救主耶穌，我來！我來！<br/>',NULL,11092,11092);
INSERT INTO stanza VALUES('C724','5','照我本相，你肯收留，<br/>賜我生命，赦我愆尤，<br/>你既應許，必定成就；<br/>救主耶穌，我來！我來！<br/>',NULL,11093,11093);
INSERT INTO stanza VALUES('C725','1','脫離捆綁、憂愁與黑影，<br/>耶穌，我來！<br/>耶穌，我來！<br/>進入自由、喜樂與光明，<br/>耶穌，我來就你！<br/>脫離疾病，進入你健全；<br/>脫離貧乏，進入你富源；<br/>脫離罪惡，進入你救援，<br/>耶穌，我來就你！<br/>',NULL,11094,11094);
INSERT INTO stanza VALUES('C725','2','脫離失敗羞恥的結果，<br/>耶穌，我來！<br/>耶穌，我來！<br/>進入十架榮耀的收穫，<br/>耶穌，我來就你！<br/>脫離痛苦，進入你安寧；<br/>脫離風波，進入你平靜；<br/>脫離怨歎，進入你誦稱，<br/>耶穌，我來就你！<br/>',NULL,11095,11095);
INSERT INTO stanza VALUES('C725','3','脫離狂傲不平的血氣，<br/>耶穌，我來！<br/>耶穌，我來！<br/>進入完全有福的旨意，<br/>耶穌，我來就你！<br/>脫離自己，住在你愛裏；<br/>脫離絕望，等候你來提，<br/>離地上騰，如鷹展雙翼，<br/>耶穌，我來就你！<br/>',NULL,11096,11096);
INSERT INTO stanza VALUES('C725','4','脫離撒但死亡的權勢，<br/>耶穌，我來！<br/>耶穌，我來！<br/>進入基督生命的恩賜，<br/>耶穌，我來就你！<br/>脫離敗壞無底的深淵，<br/>進入護庇安歇的家園，<br/>永永遠遠瞻仰你榮顏，<br/>耶穌，我來就你！<br/>',NULL,11097,11097);
INSERT INTO stanza VALUES('C726','1','你的歡迎聲音，<br/>召我前來相信，<br/>因你為我已流寶血，<br/>特要洗我良心。<br/>',NULL,11098,11098);
INSERT INTO stanza VALUES('C726','chorus','主，我來就你！<br/>我今來就你！<br/>求主用血將我洗，<br/>使我乾淨無比。<br/>',NULL,11099,11099);
INSERT INTO stanza VALUES('C726','2','我真污穢可鄙，<br/>行善一無能力；<br/>但你歡喜賜恩幫助，<br/>並除一切惡跡。<br/>',NULL,11100,11100);
INSERT INTO stanza VALUES('C726','3','你今鄭重吩咐，<br/>要我遠離罪俗，<br/>虛心悔改，實心相信，<br/>接受你作救主。<br/>',NULL,11101,11101);
INSERT INTO stanza VALUES('C726','4','神用恩言呼召，<br/>又用聖靈光照，<br/>使我知道自己不堪，<br/>知道救主可靠。<br/>',NULL,11102,11102);
INSERT INTO stanza VALUES('C726','5','聖靈今在我靈，<br/>證明我有生命；<br/>神的應許已經應驗，<br/>若我已信祂名。<br/>',NULL,11103,11103);
INSERT INTO stanza VALUES('C726','6','奇哉！神愛罪人！<br/>妙哉！神有救恩！<br/>美哉！耶穌流血贖罪！<br/>我願獻上全身。<br/>',NULL,11104,11104);
INSERT INTO stanza VALUES('C727','1','我今來就主十架，<br/>既軟弱而又貧、瞎；<br/>世上事盡都空虛，<br/>惟主恩是我所需。<br/>',NULL,11105,11105);
INSERT INTO stanza VALUES('C727','chorus','我今來投靠救主，<br/>十架下謙卑俯伏，<br/>求耶穌，神的羔羊，<br/>拯救我脫離滅亡。<br/>',NULL,11106,11106);
INSERT INTO stanza VALUES('C727','2','我久慕救主恩典，<br/>罪卻在我心掌權；<br/>今聞主柔聲說道：<br/>『你罪孽，我必除掉。』<br/>',NULL,11107,11107);
INSERT INTO stanza VALUES('C727','3','主已來充滿我心，<br/>並將我一切更新；<br/>祂寶血洗我罪愆，<br/>祂救贖使我完全。<br/>',NULL,11108,11108);
INSERT INTO stanza VALUES('C727','chorus','感謝主，我已蒙恩，<br/>罪得赦，喜樂滿心；<br/>讚美主，我已得救，<br/>眼明亮，願跟主走。<br/>',NULL,11109,11109);
INSERT INTO stanza VALUES('C727','4','我在此獻上所有：<br/>靈、魂、體、<br/>親人、摯友，<br/>智與力、財物、時間，<br/>全歸主直到永遠。<br/>',NULL,11110,11110);
INSERT INTO stanza VALUES('C728','1','誰在流蕩遠離天父？<br/>為何不回家？<br/>活在罪中，終日痛苦，<br/>何不就回家？<br/>',NULL,11111,11111);
INSERT INTO stanza VALUES('C728','chorus','回家罷！回家罷！<br/>不要再流蕩！<br/>慈愛天父等你回家，<br/>整天在巴望！<br/>',NULL,11112,11112);
INSERT INTO stanza VALUES('C728','2','我已流蕩，遠離天父，<br/>現在要回家；<br/>走過好長罪惡道路，<br/>主，我要回家。<br/>',NULL,11113,11113);
INSERT INTO stanza VALUES('C728','chorus','要回家！要回家！<br/>不願再流蕩！<br/>現在我要回到父家，<br/>永住父身旁！<br/>',NULL,11114,11114);
INSERT INTO stanza VALUES('C728','3','多年浪費寶貴歲月，<br/>現在要回家；<br/>今天懊悔，流淚、悲切，<br/>主，我要回家。<br/>',NULL,11115,11115);
INSERT INTO stanza VALUES('C728','4','流蕩、犯罪，我已疲乏，<br/>現在要回家；<br/>投靠你愛，相信你話，<br/>主，我要回家。<br/>',NULL,11116,11116);
INSERT INTO stanza VALUES('C728','5','我魂衰殘，我心悲傷，<br/>現在要回家；<br/>加我力量，復我盼望，<br/>主，我要回家。<br/>',NULL,11117,11117);
INSERT INTO stanza VALUES('C729','1','耶穌，我人的愛人，<br/>你懷讓我來藏身；<br/>驚波，駭濤滾滾近！<br/>狂風暴雨陣陣緊！<br/>藏我！哦，主，求藏我！<br/>直到今生風波過！<br/>引我安全到路盡，<br/>至終求接我靈魂！<br/>',NULL,11118,11118);
INSERT INTO stanza VALUES('C729','2','別無避所能藏隱，<br/>無助之人托你身；<br/>不！哦，不要丟棄我！<br/>扶持、安慰，望無輟：<br/>所有倚靠寄你身，<br/>所有救助由你臨；<br/>頭無遮護身無蔽，<br/>求你聖翼來覆庇。<br/>',NULL,11119,11119);
INSERT INTO stanza VALUES('C729','3','主阿，你是我所需，<br/>彀我一切還有餘：<br/>仆，你扶起；弱，你保；<br/>病，你醫治；瞽，你導；<br/>你名至義至聖潔，<br/>我全不義滿罪孽；<br/>我是邪惡沒良善，<br/>恩典、真理你充滿。<br/>',NULL,11120,11120);
INSERT INTO stanza VALUES('C729','4','你前我遇恩浩瀚，<br/>赦我眾罪之恩典；<br/>醫治活水望湧流，<br/>潔我衷裏並保守；<br/>你是永遠生命源，<br/>望在我心成活泉，<br/>從我裏頭來湧流，<br/>一直湧流到永久。<br/>',NULL,11121,11121);
INSERT INTO stanza VALUES('C730','1','聽阿！罪人，慈聲何高！<br/>救主在呼召；<br/>當祂正把多人尋找，<br/>莫讓祂漏掉！<br/>',NULL,11122,11122);
INSERT INTO stanza VALUES('C730','chorus','罪人！罪人！<br/>聽主在呼召；<br/>當祂正把多人尋找，<br/>莫讓祂漏掉！<br/>',NULL,11123,11123);
INSERT INTO stanza VALUES('C730','2','莫我，救主，莫我漏掉！<br/>聽我恭求告！<br/>當你正把別人呼召，<br/>莫把我漏掉！<br/>',NULL,11124,11124);
INSERT INTO stanza VALUES('C730','chorus','救主！救主！<br/>聽我恭求告！<br/>當你正把別人呼召，<br/>莫把我漏掉！<br/>',NULL,11125,11125);
INSERT INTO stanza VALUES('C730','3','讓我在你施恩座前，<br/>從你得救恩；<br/>俯伏痛悔，承認罪愆，<br/>求你助我信。<br/>',NULL,11126,11126);
INSERT INTO stanza VALUES('C730','4','單單靠賴十架功能，<br/>我尋求你面；<br/>醫我傷痛、破碎心、靈，<br/>救我用恩典。<br/>',NULL,11127,11127);
INSERT INTO stanza VALUES('C730','5','你是我的安慰源頭，<br/>於我比命貴；<br/>除你之外，在地何投？<br/>在天何所歸？<br/>',NULL,11128,11128);
INSERT INTO stanza VALUES('C731','1','永久磐石為我開，<br/>讓我藏身在你懷；<br/>願你所流血與水，<br/>解決我的雙重罪：<br/>贖我免去牠永刑，<br/>救我脫離牠權能。<br/>',NULL,11129,11129);
INSERT INTO stanza VALUES('C731','2','縱我雙手不罷休，<br/>不能滿足你要求；<br/>縱我熱心能持久，<br/>縱我眼淚永遠流，<br/>仍不足以贖愆尤；<br/>必須你來施拯救。<br/>',NULL,11130,11130);
INSERT INTO stanza VALUES('C731','3','空空兩手無代價，<br/>單單投靠你十架！<br/>赤身，就你求衣衫；<br/>無助，望你賜恩典；<br/>污穢，飛奔你泉旁，<br/>主阿，洗我，否則亡。<br/>',NULL,11131,11131);
INSERT INTO stanza VALUES('C731','4','當我此生年日逝，<br/>當我臨終閉目時，<br/>當我飛進永世間，<br/>當我到你寶座前，<br/>永久磐石為我開，<br/>讓我藏身在你懷。<br/>',NULL,11132,11132);
INSERT INTO stanza VALUES('C732','1','你曾離天庭，<br/>撇棄寶座和榮冕，<br/>為救我竟甘願來世間；<br/>但在伯利恆，<br/>並無一家房空閒，<br/>備接你降生到裏面。<br/>',NULL,11133,11133);
INSERT INTO stanza VALUES('C732','chorus','哦，來我心中，主耶穌！<br/>在我心有空房為著你；<br/>哦，來我心中，<br/>主耶穌！來！<br/>在我心有空房為你。<br/>',NULL,11134,11134);
INSERT INTO stanza VALUES('C732','2','天使讚高聲，<br/>天上眾軍也響應，<br/>樂宣告你身位，君尊榮；<br/>但你來地上，<br/>出生寒門，無佳形，<br/>陋城中生長，無人重。<br/>',NULL,11135,11135);
INSERT INTO stanza VALUES('C732','3','狐狸尚有洞，<br/>飛鳥亦有其窩巢，<br/>山谷中，樹林內，<br/>任逍遙；<br/>你無枕頭地，<br/>終日飄泊猶太郊，<br/>加利利野地宿荒草。<br/>',NULL,11136,11136);
INSERT INTO stanza VALUES('C732','4','哦，主，你來此，<br/>帶生命之恩言，<br/>好釋放你子民脫苦難；<br/>他們卻侮慢，<br/>戲弄且加荊棘冕，<br/>終將你置於受難山。<br/>',NULL,11137,11137);
INSERT INTO stanza VALUES('C732','5','天上還要響，<br/>天使更要讚高聲，<br/>歡頌你來得勝，至威榮；<br/>願你那時候，<br/>將我提接並說明：<br/>『我身邊有房備你用！』<br/>',NULL,11138,11138);
INSERT INTO stanza VALUES('C732','chorus','我心要歡暢，<br/>主耶穌！<br/>你來時要召我到身邊；<br/>哦，願你快來！<br/>主耶穌！來！<br/>快將我接到你身邊。<br/>',NULL,11139,11139);
INSERT INTO stanza VALUES('C733','1','來進入我心，主耶穌！<br/>我今願悔改相信；<br/>我心感覺虛空、孤獨，<br/>現在來進入我心！<br/>',NULL,11140,11140);
INSERT INTO stanza VALUES('C733','chorus','進入我心！進入我心！<br/>來進入我心，主耶穌！<br/>求你現今進來施恩，<br/>來進入我心，主耶穌！<br/>',NULL,11141,11141);
INSERT INTO stanza VALUES('C733','2','來進入我心，主耶穌，<br/>向我施行你救恩；<br/>救我脫離罪的痛苦，<br/>現在來進入我心！<br/>',NULL,11142,11142);
INSERT INTO stanza VALUES('C733','3','來進入我心，主耶穌！<br/>將我全人都更新；<br/>生命之靈進來居住，<br/>現在就進入我心。<br/>',NULL,11143,11143);
INSERT INTO stanza VALUES('C734','1','罪惡全洗淨，<br/>肉體都脫清，<br/>接受基督作我的救主；<br/>撒但已無能，<br/>世界也失形，<br/>接受基督作我的救主。<br/>',NULL,11144,11144);
INSERT INTO stanza VALUES('C734','chorus','接受！接受！<br/>相信接受，不再延誤；<br/>接受！接受！<br/>接受基督作我的救主。<br/>',NULL,11145,11145);
INSERT INTO stanza VALUES('C734','2','生命大改變，<br/>靈裏極有能，<br/>接受基督作我的生命！<br/>心中滿平安，<br/>前途盡光明，<br/>接受基督作我的生命。<br/>',NULL,11146,11146);
INSERT INTO stanza VALUES('C734','chorus','接受！接受！<br/>虛心接受，一無剛硬；<br/>接受！接受！<br/>接受基督作我的生命。<br/>',NULL,11147,11147);
INSERT INTO stanza VALUES('C734','3','疾病得醫治，<br/>軟弱也退卻，<br/>接受基督作我的醫生；<br/>痛苦已息止，<br/>死亡被吞滅，<br/>接受基督作我的醫生。<br/>',NULL,11148,11148);
INSERT INTO stanza VALUES('C734','chorus','接受！接受！<br/>滿心接受，疑懼除淨；<br/>接受！接受！<br/>接受基督作我的醫生。<br/>',NULL,11149,11149);
INSERT INTO stanza VALUES('C734','4','歎息變歌唱，<br/>喜樂代憂傷，<br/>接受基督作我的君王；<br/>天國我所享，<br/>榮耀也在望，<br/>接受基督作我的君王。<br/>',NULL,11150,11150);
INSERT INTO stanza VALUES('C734','chorus','接受！接受！<br/>完全接受，情往意降；<br/>接受！接受！<br/>接受基督作我的君王。<br/>',NULL,11151,11151);
INSERT INTO stanza VALUES('C735','1','前我墮入罪海中，<br/>遠離平安之岸，<br/>受盡摧殘深感痛，<br/>欲拔不能，徒歎！<br/>但主聽見我呼喊，<br/>立前來拯救，<br/>甘冒風險施救援，<br/>愛何深厚！<br/>',NULL,11152,11152);
INSERT INTO stanza VALUES('C735','chorus','愛救了我！愛救了我！<br/>當我在罪中落泊，<br/>愛救了我！愛救了我！<br/>愛救了我！<br/>當我在世界活著，<br/>愛救了我！<br/>',NULL,11153,11153);
INSERT INTO stanza VALUES('C735','2','現今我在平安地，<br/>脫離罪惡痛苦，<br/>滿了喜樂和安息，<br/>完全屬於耶穌。<br/>愛是如此強而真，<br/>配得我的歌謳；<br/>我心、我命、我全人，<br/>永歸祂有！<br/>',NULL,11154,11154);
INSERT INTO stanza VALUES('C735','3','苦中罪人，請聽信，<br/>耶穌能施拯救；<br/>祂愛奇妙的救恩，<br/>現在就要接受。<br/>祂心渴望拯救你，<br/>等候已經彀久；<br/>立即相信，勿猶疑，<br/>就來得救！<br/>',NULL,11155,11155);
INSERT INTO stanza VALUES('C736','1','罪惡途中多年流蕩，<br/>我魂被罪摧殘，<br/>等到基督來我心房，<br/>祂愛將我裹纏。<br/>',NULL,11156,11156);
INSERT INTO stanza VALUES('C736','chorus','我救主，何榮耀！<br/>從前瞎眼，<br/>阿利路亞，今看見！<br/>我救主，何榮耀！<br/>從前瞎眼，今看見！<br/>',NULL,11157,11157);
INSERT INTO stanza VALUES('C736','2','因我盲眼被主開啟，<br/>我得見祂榮顏；<br/>祂愛向我所顯美麗，<br/>我口難述半點。<br/>',NULL,11158,11158);
INSERT INTO stanza VALUES('C736','3','寶貝救主是我所倚，<br/>使我凡事得勝；<br/>我的救主無人能比，<br/>祂是我愛、我命。<br/>',NULL,11159,11159);
INSERT INTO stanza VALUES('C737','1','當我疲困罪惡境，<br/>祂以柔愛來尋，<br/>懷我、肩我滿溫情，<br/>帶我歸祂羊群；<br/>千萬天使因此歡騰，<br/>甚至歌聲滿天響應。<br/>',NULL,11160,11160);
INSERT INTO stanza VALUES('C737','chorus','愛何大，尋回我！<br/>血何寶，贖回我！<br/>恩何豐，帶回我歸羊群！<br/>奇妙恩，帶回我歸羊群！<br/>',NULL,11161,11161);
INSERT INTO stanza VALUES('C737','2','傷重待斃祂見我，<br/>便以油酒敷裹；<br/>柔聲細語許我說；<br/>『你要永遠屬我！』<br/>從無聲音如此甜美，<br/>傷痛之心頓覺欣慰！<br/>',NULL,11162,11162);
INSERT INTO stanza VALUES('C737','3','釘痕槍傷祂示我，<br/>血也水也流出，<br/>頭戴荊冕利刺戳，<br/>羞辱加上痛楚：<br/>我真不知我有何長，<br/>使祂為我這樣受戕。<br/>',NULL,11163,11163);
INSERT INTO stanza VALUES('C737','4','我今安坐祂面前，<br/>瞻仰祂的榮顏，<br/>心覺希奇靈感讚，<br/>追憶祂的恩眷；<br/>似乎永世所有時間，<br/>用來讚祂尚嫌太短。<br/>',NULL,11164,11164);
INSERT INTO stanza VALUES('C737','5','當今時日在逝遜，<br/>一切皆能安心；<br/>惟獨切盼那早晨－無上光明時辰：<br/>那時召我到祂身邊，<br/>與祂同在，作祂聖伴。<br/>',NULL,11165,11165);
INSERT INTO stanza VALUES('C738','1','救我恩何等豐滿，<br/>救我恩何等豐滿，<br/>救我恩何等豐滿，<br/>救我恩無量！<br/>',NULL,11166,11166);
INSERT INTO stanza VALUES('C738','chorus','主斷開一切鎖鍊，<br/>主斷開一切鎖鍊，<br/>主斷開一切鎖鍊，<br/>主把我釋放！<br/>',NULL,11167,11167);
INSERT INTO stanza VALUES('C738','2','我罪過都蒙赦免，<br/>我心中充滿平安，<br/>我全人脫離羈絆，<br/>我今得釋放！<br/>',NULL,11168,11168);
INSERT INTO stanza VALUES('C738','3','無論是罪惡、試探，<br/>無論是世界、撒但，<br/>無論是疾病、憂患，<br/>都不能捆綁！<br/>',NULL,11169,11169);
INSERT INTO stanza VALUES('C738','4','阿利路！主名香甜，<br/>阿利路！主名香甜，<br/>阿利路！主名香甜，<br/>我永要頌揚！<br/>',NULL,11170,11170);
INSERT INTO stanza VALUES('C738','5','還要唱阿利路亞，<br/>還要唱阿利路亞，<br/>還要唱阿利路亞，<br/>主把我釋放！<br/>',NULL,11171,11171);
INSERT INTO stanza VALUES('C739','1','在十字架我救主捨命，<br/>所流寶血洗罪有權能；<br/>這寶貝血已將我洗清；<br/>榮耀歸主名！<br/>',NULL,11172,11172);
INSERT INTO stanza VALUES('C739','chorus','榮耀歸主名！<br/>榮耀歸主名！<br/>主寶貝血已將我洗清；<br/>榮耀歸主名！<br/>',NULL,11173,11173);
INSERT INTO stanza VALUES('C739','2','十字架下救主施恩典，<br/>用祂寶血洗淨我罪愆；<br/>哦，這洗淨奇妙而甘甜；<br/>榮耀歸主名！<br/>',NULL,11174,11174);
INSERT INTO stanza VALUES('C739','3','這寶貝血洗我何清潔，<br/>我真快樂，我今白如雪！<br/>這血還要使我常超越；<br/>榮耀歸主名！<br/>',NULL,11175,11175);
INSERT INTO stanza VALUES('C739','4','請你速來投入這泉源，<br/>將你全人拋在主腳前；<br/>今天來投，今天得完全；<br/>榮耀歸主名！<br/>',NULL,11176,11176);
INSERT INTO stanza VALUES('C740','1','主耶穌，我們聚集<br/>在你墓的四圍，<br/>口中歌唱心歡喜，<br/>見證你的作為。<br/>我們用信來跟隨，<br/>追蹤你的道路，<br/>藉這莊嚴、奧妙水，<br/>進入你的工夫。<br/>',NULL,11177,11177);
INSERT INTO stanza VALUES('C740','2','主耶穌，我們記念<br/>你魂中的苦難，<br/>因你向我施恩典，<br/>曾被波浪沖漫；<br/>為我你浸死水中，<br/>為我你曾流血，<br/>為我你曾離天庭，<br/>為我你曾命絕。<br/>',NULL,11178,11178);
INSERT INTO stanza VALUES('C740','3','哦，主，你今已復活，<br/>黑暗已成往事，<br/>現今你已登寶座，<br/>活著，永不再死；<br/>罪、死、陰府你毀盡，<br/>我也同你得勝，<br/>因你是我的生命，<br/>我是坐享其成。<br/>',NULL,11179,11179);
INSERT INTO stanza VALUES('C740','4','我今受浸歸你死！<br/>承認與你同盡，<br/>我也與你同復活，<br/>與你榮耀有分。<br/>撒但、世界和罪惡，<br/>今都不能摸我；<br/>我今同你作旅客，<br/>同你為神生活。<br/>',NULL,11180,11180);
INSERT INTO stanza VALUES('C741','1','基督死葬我隨同，<br/>走進死水中，<br/>與祂同歸終；<br/>世界、撒但勢雖兇，<br/>到此便消蹤，<br/>不能再追攻。<br/>基督復活我與共，<br/>走出死水中，<br/>與祂同行動；<br/>生命聖靈力無窮，<br/>使我蒙恩寵，<br/>榮上又加榮。<br/>',NULL,11181,11181);
INSERT INTO stanza VALUES('C742','1','主當我們藉著這水，<br/>承認同死事實，<br/>求你在此憐憫施惠，<br/>啟示牠的價值。<br/>',NULL,11182,11182);
INSERT INTO stanza VALUES('C742','2','藉著這水歸入你死，<br/>與你一同埋葬，<br/>我們永遠離罪若失，<br/>脫離罪的捆綁。<br/>',NULL,11183,11183);
INSERT INTO stanza VALUES('C742','3','藉著這水歸入你死，<br/>與你一同埋葬，<br/>我們就此與世長辭，<br/>脫離今世君王。<br/>',NULL,11184,11184);
INSERT INTO stanza VALUES('C742','4','在此與你一同復活，<br/>脫離死亡權勢；<br/>靠你結出成聖美果，<br/>活出新生樣式。<br/>',NULL,11185,11185);
INSERT INTO stanza VALUES('C742','5','在此受浸歸於你名，<br/>不再屬於自己；<br/>為你而活，隨你而行，<br/>永遠與你合一。<br/>',NULL,11186,11186);
INSERT INTO stanza VALUES('C743','1','已經死了！已經葬了！<br/>從今以後我完全了了！<br/>已經死了！已經葬了！<br/>從今以後我完全了了！<br/>',NULL,11187,11187);
INSERT INTO stanza VALUES('C743','2','完全了了！完全了了！<br/>從今以後我完全了了！<br/>完全了了！完全了了！<br/>從今以後我完全了了！<br/>',NULL,11188,11188);
INSERT INTO stanza VALUES('C743','3','不再是我！不再是我！<br/>乃是基督在我裏面活！<br/>不再是我！不再是我！<br/>乃是基督在我裏面活！<br/>',NULL,11189,11189);
INSERT INTO stanza VALUES('C744','1','『藉水得救』，<br/>此言奧妙，<br/>哦，主，啟示其意，<br/>使我知道救恩何高，<br/>救我到何境地。<br/>',NULL,11190,11190);
INSERT INTO stanza VALUES('C744','2','『藉水得救』，<br/>脫離世界，<br/>進入新生境地；<br/>已往一切都已完結，<br/>全埋奧妙水裏。<br/>',NULL,11191,11191);
INSERT INTO stanza VALUES('C744','3','洪水如何拯救挪亞，<br/>脫離當日世代；<br/>浸水照樣因著十架，<br/>使我與世分開。<br/>',NULL,11192,11192);
INSERT INTO stanza VALUES('C744','4','海水曾救以色列人，<br/>脫離埃及權勢；<br/>浸水照樣也救我們，<br/>脫離世界轄制。<br/>',NULL,11193,11193);
INSERT INTO stanza VALUES('C744','5','『藉水得救』，<br/>何等釋放，<br/>何等自由超脫：<br/>脫離世界一切捆綁，<br/>脫離病、苦、罪、魔。<br/>',NULL,11194,11194);
INSERT INTO stanza VALUES('C744','6','『藉水得救』，<br/>永遠歸神，<br/>不再屬於世界；<br/>敬拜、事奉，<br/>是我福分，<br/>歸神成為聖潔。<br/>',NULL,11195,11195);
INSERT INTO stanza VALUES('C745','1','國度是神的掌權，<br/>維持神的榮耀；<br/>是神主宰的管治，<br/>將祂秩序建造。<br/>神在祂的國度裏，<br/>施行祂的王權，<br/>照祂自己來治理，<br/>直到永永遠遠。<br/>',NULL,11196,11196);
INSERT INTO stanza VALUES('C745','2','國度中心是寶座，<br/>神在其上掌權；<br/>一切帶上祂正規，<br/>照著祂心所願。<br/>國度之中祂作王，<br/>一切歸祂管治；<br/>為首為主的身分，<br/>如此始能維持。<br/>',NULL,11197,11197);
INSERT INTO stanza VALUES('C745','3','神藉掌權國度中，<br/>通行祂的旨意；<br/>在祂統治的權下，<br/>成全祂的心意。<br/>惟有在神國度中，<br/>祝福始能得著；<br/>乃是從神的寶座，<br/>流出生命水河。<br/>',NULL,11198,11198);
INSERT INTO stanza VALUES('C745','4','服在神的管治下，<br/>乃是蒙福之本；<br/>背叛神聖的主權，<br/>乃是罪惡之根。<br/>撒但邪惡的目的，<br/>乃在翻神寶座；<br/>我們該有的目標，<br/>在神權下活著。<br/>',NULL,11199,11199);
INSERT INTO stanza VALUES('C745','5','在神至高國度中，<br/>基督得顯為大；<br/>基督掌權生命中，<br/>神就能有可誇。<br/>當神施行祂統治，<br/>一切全都蒙福；<br/>基督若為神掌權，<br/>神的榮耀顯出。<br/>',NULL,11200,11200);
INSERT INTO stanza VALUES('C745','6','日期滿足的時候，<br/>主要歸一萬有，<br/>萬有要認祂王權，<br/>將祂統治領受。<br/>生命榮耀的管治，<br/>召會現已豫嘗，<br/>並催國度速實現，<br/>萬有都得分享。<br/>',NULL,11201,11201);
INSERT INTO stanza VALUES('C746','1','神的國度今在地上，<br/>是神掌權在我心裏；<br/>乃是基督活我裏面，<br/>作主作王統治管理。<br/>',NULL,11202,11202);
INSERT INTO stanza VALUES('C746','2','基督生命同祂權柄，<br/>使祂登極在我心中，<br/>管理全人每一部分，<br/>規律一切言語行動。<br/>',NULL,11203,11203);
INSERT INTO stanza VALUES('C746','3','基督在我心中登極，<br/>就在我心建祂國度，<br/>穩定祂的全權統治，<br/>為著神旨各方鋪路。<br/>',NULL,11204,11204);
INSERT INTO stanza VALUES('C746','4','藉著祂在我心執政，<br/>祂將生命向我供應；<br/>當我讓祂作主作王，<br/>我就得享祂的豐盛。<br/>',NULL,11205,11205);
INSERT INTO stanza VALUES('C746','5','藉著祂在裏面管治，<br/>祂的豐滿在我建起；<br/>當祂裏面國度掌權，<br/>祂的身體就得建立。<br/>',NULL,11206,11206);
INSERT INTO stanza VALUES('C746','6','藉祂裏面屬天管治，<br/>我像天上國民活著；<br/>藉著我肯服祂權柄，<br/>祂的國度實現於我。<br/>',NULL,11207,11207);
INSERT INTO stanza VALUES('C746','7','在這屬天範圍活著，<br/>帶著祂這屬天王權，<br/>屬天光中行動、爭戰，<br/>直到國度在地實現。<br/>',NULL,11208,11208);
INSERT INTO stanza VALUES('C747','1','國度要求，標準嚴格，<br/>遠超律法所有要求；<br/>神的要求無論大小，<br/>無一比這高而難就。<br/>',NULL,11209,11209);
INSERT INTO stanza VALUES('C747','2','天國近了，<br/>『應當悔改』，<br/>這是國度首一要求；<br/>我們心思必須轉變，<br/>向神一邊全面轉投。<br/>',NULL,11210,11210);
INSERT INTO stanza VALUES('C747','3','我們要進諸天國度，<br/>必須有那超凡的義；<br/>乃是出乎大能生命，<br/>遠非律法所能為力。<br/>',NULL,11211,11211);
INSERT INTO stanza VALUES('C747','4','我們要進諸天國度，<br/>天父旨意必須遵行；<br/>不是照我心願所選，<br/>乃是照祂心意所定。<br/>',NULL,11212,11212);
INSERT INTO stanza VALUES('C747','5','我們要進諸天國度，<br/>必須變成孩童樣式；<br/>謙卑、簡單、順服、<br/>易改，<br/>毫無自滿、自恃、自是。<br/>',NULL,11213,11213);
INSERT INTO stanza VALUES('C747','6','諸天國度甚至要求<br/>我們與神一樣完全；<br/>必須完全合這標準，<br/>國度實際纔能實踐。<br/>',NULL,11214,11214);
INSERT INTO stanza VALUES('C747','7','國度乃是神的掌權，<br/>需要與神性質相合；<br/>只有藉著神的生命，<br/>纔能進這神聖之國。<br/>',NULL,11215,11215);
INSERT INTO stanza VALUES('C747','8','國度乃是屬天管治，<br/>必須合於屬天情形；<br/>若要與主有分這國，<br/>惟有藉著屬天生命。<br/>',NULL,11216,11216);
INSERT INTO stanza VALUES('C748','1','諸天國度，牠的實際，<br/>在於受天管治生活；<br/>這種生活，性質神聖，<br/>全讓基督居衷活著。<br/>',NULL,11217,11217);
INSERT INTO stanza VALUES('C748','2','這種生活：靈裏貧窮，<br/>心裏飢渴、哀慟、溫柔；<br/>對人總是滿了憐恤，<br/>對神又是清心尋求。<br/>',NULL,11218,11218);
INSERT INTO stanza VALUES('C748','3','作神兒子，製造和睦；<br/>為著公義，忍受逼迫；<br/>為主受人辱罵、毀謗；<br/>無怨無恨，歡喜快樂。<br/>',NULL,11219,11219);
INSERT INTO stanza VALUES('C748','4','作鹽消殺地上敗壞；<br/>作光照亮世上黑暗；<br/>存心行動，正直真誠，<br/>只愛不恨，像父完全。<br/>',NULL,11220,11220);
INSERT INTO stanza VALUES('C748','5','自榮自耀全都拋棄，<br/>永遠為著神國禱告；<br/>先求神國和神的義，<br/>一切需要惟神是靠。<br/>',NULL,11221,11221);
INSERT INTO stanza VALUES('C748','6','對己嚴格，對人有恩，<br/>對神，又是殷勤求尋；<br/>永遠遵行天父旨意，<br/>照主話語行事為人。<br/>',NULL,11222,11222);
INSERT INTO stanza VALUES('C748','7','對待撒但，不留地步，<br/>同樣拒絕世界人情；<br/>只願順服諸天管治，<br/>接受神的完全權柄。<br/>',NULL,11223,11223);
INSERT INTO stanza VALUES('C748','8','這種生活征服一切，<br/>藉神大能遵神吩咐；<br/>促進主的再來日子，<br/>帶進國度實現之福。<br/>',NULL,11224,11224);
INSERT INTO stanza VALUES('C749','1','看，何榮耀！<br/>看，何光彩！<br/>諸天國度今實現！<br/>榮耀之王，神的基督，<br/>為神所立來掌權。<br/>曾在肉身卑微來過，<br/>被人藐視並厭惡；<br/>今帶榮耀威嚴再來，<br/>成全國度的意圖。<br/>',NULL,11225,11225);
INSERT INTO stanza VALUES('C749','2','去從祂神，亙古存者，<br/>領得權柄和國度；<br/>現今帶著國度回來，<br/>榮耀顯之於眾目。<br/>這『非人手所鑿石頭』<br/>已將列國砸粉碎；<br/>變成『大山』充滿天下，<br/>顯出國度的光輝。<br/>',NULL,11226,11226);
INSERT INTO stanza VALUES('C749','3','看哪，地和其上列國，<br/>都歸基督為基業；<br/>在祂至高統治之下，<br/>滿了平安與和諧。<br/>列國之間再無爭戰，<br/>再無殘殺的戰場；<br/>神的知識充滿遍地，<br/>好像大水滿海洋。<br/>',NULL,11227,11227);
INSERT INTO stanza VALUES('C749','4','所有得勝的基督徒，<br/>榮中與主同管治；<br/>以色列的得救遺民，<br/>也要作神的祭司。<br/>在這管治教導之下，<br/>列國要作神百姓；<br/>所有萬物都要得到<br/>榮耀無比的復興。<br/>',NULL,11228,11228);
INSERT INTO stanza VALUES('C749','5','撒但被捆丟於深坑，<br/>全地脫離他霸權；<br/>由主基督為首統治，<br/>全地蒙福真空前。<br/>萬有全都降服基督，<br/>服祂統治與管理；<br/>祂作元首，萬有中心，<br/>成全祂神的旨意。<br/>',NULL,11229,11229);
INSERT INTO stanza VALUES('C750','1','神子來作生命種子，<br/>將祂自己種人心裏，<br/>如此從祂長出國度，<br/>完成神的永遠旨意。<br/>',NULL,11230,11230);
INSERT INTO stanza VALUES('C750','2','祂是惟一生命麥種，<br/>從祂生出許多子粒，<br/>配作諸天國度之子，<br/>帶進神的掌權治理。<br/>',NULL,11231,11231);
INSERT INTO stanza VALUES('C750','3','但是撒但，神的仇敵，<br/>卻將稗子撒在麥裏，<br/>為要擾亂國度之子，<br/>造出可怕敗壞事跡。<br/>',NULL,11232,11232);
INSERT INTO stanza VALUES('C750','4','藉著他這奸狡工作，<br/>稗子、麥子混雜一起，<br/>國度外表變為反常，<br/>龐大驚人，醜形離奇。<br/>',NULL,11233,11233);
INSERT INTO stanza VALUES('C750','5','諸天國度該像芥菜，<br/>青嫩、微小，可供人食，<br/>但卻變成一棵大『樹』，<br/>不倫不類、龐大組織。<br/>',NULL,11234,11234);
INSERT INTO stanza VALUES('C750','6','不再能作神、人食物，<br/>反成『飛鳥』棲身之所；<br/>惡人、惡事以及惡靈，<br/>都能在此得到寄託。<br/>',NULL,11235,11235);
INSERT INTO stanza VALUES('C750','7','牠這外表給人看見<br/>一個屬世偉大宗教；<br/>容納外邦邪惡事物，<br/>猶如細麵攙上麵酵。<br/>',NULL,11236,11236);
INSERT INTO stanza VALUES('C750','8','既成這種屬世組織，<br/>外表遂即改變形狀；<br/>藉其所容邪惡事物，<br/>裏面充滿敗壞、淫蕩。<br/>',NULL,11237,11237);
INSERT INTO stanza VALUES('C750','9','但神尋找隱藏珍物，<br/>『珍珠』和那『藏地<br/>寶貝；』<br/>主要將我全然變化，<br/>如同珠寶一樣寶貴。<br/>',NULL,11238,11238);
INSERT INTO stanza VALUES('C750','10','隱自龐大基督教國，<br/>隱自國度屬世外表；<br/>卻有國度豐滿實際，<br/>具有基督和神相貌。<br/>',NULL,11239,11239);
INSERT INTO stanza VALUES('C750','11','求主使我脫離『稗子』，<br/>救我脫離宗教大『樹』；<br/>從我除去所有麵酵，<br/>使我像你純潔不俗。<br/>',NULL,11240,11240);
INSERT INTO stanza VALUES('C750','12','求藉生命變化我魂，<br/>使我變成寶貴材料，<br/>帶著你的國度實際，<br/>適合於你靈宮建造。<br/>',NULL,11241,11241);
INSERT INTO stanza VALUES('C751','1','今天神的國度，<br/>對我是操練，<br/>將來卻是獎賞，<br/>與主一同掌權。<br/>這是神的智慧，<br/>現今將我訓練，<br/>使祂計畫完成，<br/>將祂公義彰顯。<br/>',NULL,11242,11242);
INSERT INTO stanza VALUES('C751','2','我們為神所生，<br/>好為祂作王，<br/>但是還需訓練，<br/>纔能像王一樣，<br/>好在祂的國中，<br/>勝任作王掌權，<br/>使祂神聖王權，<br/>藉我得著彰顯。<br/>',NULL,11243,11243);
INSERT INTO stanza VALUES('C751','3','今天我需學習<br/>服神的權柄，<br/>甘願受祂管治，<br/>嚴格對付言行。<br/>如此祂的權柄，<br/>我就得以分享，<br/>將來管理列國，<br/>與祂兒子同王。<br/>',NULL,11244,11244);
INSERT INTO stanza VALUES('C751','4','嚴格對待自己，<br/>持守著公義，<br/>對人寬大有恩，<br/>對神靈中歡喜；<br/>一直都要活在<br/>國度實際裏面，<br/>為著國度實現，<br/>能得進入掌權。<br/>',NULL,11245,11245);
INSERT INTO stanza VALUES('C751','5','如此，<br/>基督帶著國度降臨時，<br/>要將祂的王權<br/>賜我作為賞賜；<br/>如此，<br/>主要藉我使祂公義彰顯，<br/>並將祂的智慧<br/>給眾天使看見。<br/>',NULL,11246,11246);
INSERT INTO stanza VALUES('C751','6','為著這個，<br/>使徒曾努力向前，<br/>願出任何代價，<br/>不甘落在後面；<br/>也為這個，<br/>他勸我們忠誠向上，<br/>好在將來<br/>得著國度作為獎賞。<br/>',NULL,11247,11247);
INSERT INTO stanza VALUES('C751','7','求主賜我恩典，<br/>為國度活著，<br/>今天受你訓練，<br/>將來你肯賞我；<br/>求使國度實際，<br/>今天作我操練，<br/>將來我的獎賞，<br/>乃是國度實現。<br/>',NULL,11248,11248);
INSERT INTO stanza VALUES('C752','1','耶穌要來獎賞祂的僕人，<br/>或早或晚時不定；<br/>會否祂來正逢我們堅忍，<br/>我們的燈修光明？<br/>',NULL,11249,11249);
INSERT INTO stanza VALUES('C752','chorus','我能否說，<br/>我是已經準備，<br/>準備坦然見主面？<br/>會否祂來正逢我仍不睡，<br/>仍然等候，直至祂顯現？<br/>',NULL,11250,11250);
INSERT INTO stanza VALUES('C752','2','若祂在一清晨回來結算，<br/>一一指名傳我們，<br/>我們各人要將銀子交還，<br/>祂能否說『好，僕人？』<br/>',NULL,11251,11251);
INSERT INTO stanza VALUES('C752','3','主的委託，<br/>我們是否忠心？<br/>我們是否盡所能？<br/>我們裏面若無指責聲音，<br/>我們就必得高升。<br/>',NULL,11252,11252);
INSERT INTO stanza VALUES('C752','4','福哉人也！<br/>主來正逢儆醒，<br/>就必與祂同作王；<br/>當祂再臨，<br/>或夜半或天明，<br/>是否正逢我瞭望？<br/>',NULL,11253,11253);
INSERT INTO stanza VALUES('C753','1','主耶穌，我正等待<br/>被提到你面前，<br/>除了你的快再來，<br/>無別如此甘甜。<br/>我今盼望你再來，<br/>我知道你已近，<br/>我覺得你的同在，<br/>已經包圍我心。<br/>',NULL,11254,11254);
INSERT INTO stanza VALUES('C753','2','在我全人最深處，<br/>我已聽見你話；<br/>感謝你，因你清楚<br/>語我以你計畫。<br/>你的再臨何等近！<br/>你的顯現已快！<br/>恩典餘日何等緊！<br/>仇敵就要敗壞！<br/>',NULL,11255,11255);
INSERT INTO stanza VALUES('C753','3','求你斬斷眾籐蔓，<br/>使我完全自由，<br/>完全脫去諸累纏，<br/>緊緊跟隨你走。<br/>我願放下『合理事』，<br/>免得我心受拘，<br/>免得當你再來時，<br/>我不能自由去。<br/>',NULL,11256,11256);
INSERT INTO stanza VALUES('C753','4','時刻等候並儆醒，<br/>這是我的心意；<br/>願我完全隨從靈，<br/>免得錯過被提；<br/>免得因我未豫備，<br/>因我打盹睡覺，<br/>你就以為我不配，<br/>留我在地受熬。<br/>',NULL,11257,11257);
INSERT INTO stanza VALUES('C753','5','我的心哪，這真是<br/>極莊嚴的儆戒，<br/>因此，你所愛的事，<br/>應當完全脫解。<br/>應當完全戀慕主，<br/>完全想念見祂；<br/>無論何時主招呼，<br/>能將一切撇下。<br/>',NULL,11258,11258);
INSERT INTO stanza VALUES('C753','6','雖然今日爭戰猛，<br/>多有撒但折磨，<br/>但是不久要高升，<br/>所以還怕甚麼！<br/>現今黑暗雖加增，<br/>救贖日子也近，<br/>所以你可昂首等，<br/>因不久主必臨。<br/>',NULL,11259,11259);
INSERT INTO stanza VALUES('C753','7','願我所愛惟有主，<br/>願我所想惟主，<br/>拒絕世界的賄賂，<br/>心已與主同處。<br/>地上束縛已經鬆；<br/>我主，求你就來，<br/>我心盼望到天中，<br/>看見我主我愛！<br/>',NULL,11260,11260);
INSERT INTO stanza VALUES('C754','1','主必親自從天降臨，<br/>神的號筒要吹響，<br/>聖徒死者復活，<br/>生命吞死亡，<br/>主必親自從天降臨，<br/>天上使者要宣揚，<br/>聖徒活者被提，<br/>身體變形狀。<br/>',NULL,11261,11261);
INSERT INTO stanza VALUES('C754','chorus','主必親自從天降臨，<br/>我必面見祂的榮身；<br/>主必親自從天降臨，<br/>聖徒身體得贖，<br/>我也必有分。<br/>',NULL,11262,11262);
INSERT INTO stanza VALUES('C754','2','主必親自從天降臨，<br/>光明早晨要破曉，<br/>黑夜必要過去，<br/>哭泣必終了；<br/>主必親自從天降臨，<br/>榮耀日子要來到，<br/>敗壞不再轄制，<br/>歎息必遁逃。<br/>',NULL,11263,11263);
INSERT INTO stanza VALUES('C754','3','主必親自從天降臨，<br/>明亮晨星要出現，<br/>醒者免去災難，<br/>忠者得冠冕；<br/>主必親自從天降臨，<br/>公義太陽要掌權，<br/>萬物得著復興，<br/>大地蒙眷憐。<br/>',NULL,11264,11264);
INSERT INTO stanza VALUES('C754','4','主必親自從天降臨，<br/>聖徒等候要儆醒，<br/>腰帶時時束緊，<br/>燈光要剔亮；<br/>主必親自從天降臨，<br/>你我事奉要忠誠，<br/>職事處處盡到，<br/>恩賜莫埋藏。<br/>',NULL,11265,11265);
INSERT INTO stanza VALUES('C755','1','基督快要再臨，<br/>日子已緊近；<br/>有福腳聲隱約可聽聞。<br/>醒哉！醒哉！<br/>聖民，等候要儆心；<br/>被提見主喜樂無窮盡。<br/>',NULL,11266,11266);
INSERT INTO stanza VALUES('C755','chorus','榮耀！榮耀！<br/>基督快再臨，<br/>榮耀！榮耀！<br/>聖者要歡欣，<br/>賤體變成榮身，<br/>與主永相親，<br/>自由，榮耀，<br/>同主享福分。<br/>',NULL,11267,11267);
INSERT INTO stanza VALUES('C755','2','基督快要再臨，<br/>晨星要顯身；<br/>黑夜已深，白晝將臨近。<br/>醒哉！醒哉！<br/>聖民，與俗莫浮沉；<br/>得蒙保守免去大災辰。<br/>',NULL,11268,11268);
INSERT INTO stanza VALUES('C755','3','基督快要再臨，<br/>賞賜祂僕人；<br/>凡愛祂者，冠冕必有分。<br/>醒哉！醒哉！<br/>聖民，莫把世界珍；<br/>愛主，事主，<br/>盡性又盡心。<br/>',NULL,11269,11269);
INSERT INTO stanza VALUES('C755','chorus','榮耀！榮耀！<br/>基督快再臨，<br/>榮耀！榮耀！<br/>勝者要歡欣，<br/>聽主稱讚聲音，<br/>說：『好！我僕人，<br/>你可進來享受我福分。』<br/>',NULL,11270,11270);
INSERT INTO stanza VALUES('C755','4','基督快要再臨，<br/>得國作大君；<br/>撒但被擒，萬民來歸順。<br/>醒哉！醒哉！<br/>聖民，努力向前奔，<br/>進入天國作王何榮尊。<br/>',NULL,11271,11271);
INSERT INTO stanza VALUES('C756','1','我王必定快要再臨，<br/>天空都滿了祂！<br/>待贖宇宙快得復興，<br/>主要完成救法！<br/>我已聽見祂的腳聲，<br/>在那彩雲中間；<br/>我已看見祂的榮身，<br/>隱約顯露在天。<br/>',NULL,11272,11272);
INSERT INTO stanza VALUES('C756','2','我今仰望我主『同在』，<br/>不敢懈怠一點；<br/>我今等候我主再來，<br/>使我得著所天。<br/>除了我主此刻就來，<br/>接我與祂同在，<br/>除了這件美事以外，<br/>我心別無所愛。<br/>',NULL,11273,11273);
INSERT INTO stanza VALUES('C756','3','我眼專看我的救主，<br/>我心已經在天，<br/>我口不說別的題目，<br/>只說與主相見。<br/>主的再臨已經緊近，<br/>主來原是為我；<br/>主的應許永遠堅定，<br/>從來沒有空說。<br/>',NULL,11274,11274);
INSERT INTO stanza VALUES('C756','4','我的救主，你的聖言<br/>無可惑，無可減；<br/>我今忠誠不顧臉面，<br/>因你聖言自勉。<br/>願你榮耀早日顯現，<br/>仇敵敗，陰府陷；<br/>願你應許早日應驗，<br/>接我們到那邊。<br/>',NULL,11275,11275);
INSERT INTO stanza VALUES('C756','5','你的膀臂是逃避所，<br/>耶穌救主我神！<br/>你像天父一樣保妥<br/>一切靠你的人；<br/>羊和牧者同樣輕重，<br/>身和頭同境遇！<br/>誰也不能從你手中，<br/>奪去你的兒女。<br/>',NULL,11276,11276);
INSERT INTO stanza VALUES('C756','6','千人的手不能阻我，<br/>萬人的眼也不；<br/>路上荊棘，不過助我<br/>忠勇進前得福。<br/>我心！我靈！今當復興，<br/>讓這世界過去；<br/>生命的主！求你快臨，<br/>接我進入天域。<br/>',NULL,11277,11277);
INSERT INTO stanza VALUES('C756','7','醫治的日！人的盼望！<br/>我真愛你光線；<br/>公義的主！榮耀的王！<br/>我今伏你面前；<br/>求你自己快登寶座！<br/>求你臉面快顯！<br/>求你伸手建立天國，<br/>向萬民賜恩典！<br/>',NULL,11278,11278);
INSERT INTO stanza VALUES('C756','8','真理本當得勝為王！<br/>自由本當為后！<br/>但是謊言竟然猖狂，<br/>為這世界元首！<br/>所以真理求你快來！<br/>帶著天光而來！<br/>好使仇敵遇見失敗，<br/>眾子投入你懷。<br/>',NULL,11279,11279);
INSERT INTO stanza VALUES('C757','1','我能否忘快來的主？<br/>否，否，我心不斷想慕：<br/>我為祂向父神求索，<br/>我為祂唱早晨詩歌。<br/>',NULL,11280,11280);
INSERT INTO stanza VALUES('C757','chorus','來罷！親愛主！<br/>來罷！主！<br/>來罷！我王！<br/>',NULL,11281,11281);
INSERT INTO stanza VALUES('C757','2','我今能否忘了儆醒？<br/>否，否，我心早晚深省！<br/>惟恐錯過被提機會，<br/>容讓世事使我聾瞶。<br/>',NULL,11282,11282);
INSERT INTO stanza VALUES('C757','3','我能否與世界結聯？<br/>否，否，祂召我往上面！<br/>願我捨棄屬地事物，<br/>愛祂，念祂，我的救主。<br/>',NULL,11283,11283);
INSERT INTO stanza VALUES('C757','4','願我逐日行在靈裏，<br/>吸取祂的生命能力，<br/>儆醒，等候，直到祂來，<br/>時刻豫備，不敢稍怠。<br/>',NULL,11284,11284);
INSERT INTO stanza VALUES('C757','5','願我不怕撒但權勢，<br/>一日在此，一日堅持，<br/>陰府的門必不得勝，<br/>神的基督已經執政。<br/>',NULL,11285,11285);
INSERT INTO stanza VALUES('C757','6','我能否忘這個信息？<br/>我要呼喊使地戰慄！<br/>求主成全所賜信心，<br/>將你的話早日證明。<br/>',NULL,11286,11286);
INSERT INTO stanza VALUES('C758','1','自伯大尼<br/>你與我們分手後，<br/>我心有個真空無可補滿，<br/>我坐河濱，<br/>將琴掛在柳枝頭，<br/>你不在此，<br/>我怎有心鼓彈？<br/>當我深夜孤獨<br/>安靜的時候，<br/>（此時我無忍受，<br/>我也無享受，）<br/>不禁歎息，<br/>我想著你是多遠，<br/>我想著你<br/>應許已久的歸旋。<br/>',NULL,11287,11287);
INSERT INTO stanza VALUES('C758','2','你的馬槽<br/>使我生無家之想，<br/>你的苦架使我無所欲喜，<br/>你的再來<br/>使我懷未見之鄉，<br/>你的自己<br/>成我追求目的。<br/>你不在此，<br/>喜樂已減牠滋味，<br/>詩歌也缺<br/>牠所應有的甜美；<br/>你不在此，<br/>終日我若有所失，<br/>主阿，我要你來，<br/>我不要你遲。<br/>',NULL,11288,11288);
INSERT INTO stanza VALUES('C758','3','雖我在此<br/>也能享受你同在，<br/>但我深處依然有個缺憾；<br/>雖然有你光照，<br/>也有你撫愛，<br/>有個甚麼我不知仍不滿！<br/>平安裏面，<br/>我卻仍感覺孤單，<br/>喜樂時候，<br/>我仍不免有吁歎，<br/>最是足意中間，<br/>也有不足意，<br/>就是我還不能<br/>當面看見你。<br/>',NULL,11289,11289);
INSERT INTO stanza VALUES('C758','4','亡人怎不想見<br/>生長的鄉邑？<br/>俘虜怎不想見故國故人？<br/>情人分離，<br/>怎不一心羈兩地？<br/>兒女遠遊，<br/>怎不思家思親？<br/>主阿，<br/>我想看見你面的心意，<br/>還非這些<br/>人間情形可比擬；<br/>現今在此，<br/>我無法見你丰采，<br/>是否只好歎息<br/>等到你回來！<br/>',NULL,11290,11290);
INSERT INTO stanza VALUES('C758','5','主你能否忘記<br/>你曾經應許，你要回來，<br/>接我與你同在？<br/>但一天天<br/>又一年年的過去，<br/>我仍等候，<br/>你卻仍未回來！<br/>求你記念，<br/>我已等得好疲倦，<br/>而你蹤跡<br/>好像當初一樣遠！<br/>多久？多久？<br/>還有多久的時候，<br/>纔應驗應許<br/>來把我提走？<br/>',NULL,11291,11291);
INSERT INTO stanza VALUES('C758','6','日出日落，<br/>一世過去又一代，<br/>你的聖徒生活、<br/>等候、安睡，<br/>一位一位，<br/>他們已逐漸離開，<br/>一次一次，<br/>我們望你快回。<br/>我主，<br/>為何你仍沒有顯動靜，<br/>天仍閉住，<br/>我們觀看仍對鏡，<br/>我們在此<br/>依然等候再等候，<br/>哎呀，<br/>是否我們等候還不彀？<br/>',NULL,11292,11292);
INSERT INTO stanza VALUES('C758','7','當我回想，<br/>我已等候多長久，<br/>不禁歎息，<br/>低頭獨自流淚，<br/>求你別再遲延<br/>不聽我要求，<br/>現今就來接我與你相會；<br/>來罷，我主，<br/>這是召會的求呼！<br/>來罷，我主，<br/>請聽聖徒的催促！<br/>來罷，<br/>歷世歷代累積的共鳴，<br/>我主，<br/>能否求你今天一起聽！<br/>',NULL,11293,11293);
INSERT INTO stanza VALUES('C759','1','等到何日恩主纔回來？<br/>我心渴望見祂丰采！<br/>等到何日恩主纔回來，<br/>好使我得奏凱，見心愛？<br/>恩主快來！恩主何待？<br/>到何日你纔肯來<br/>慰我心懷？<br/>恩主快來！恩主何待？<br/>我心切慕你同在！<br/>',NULL,11294,11294);
INSERT INTO stanza VALUES('C760','1','自從當年<br/>橄欖山前一別離，<br/>至今你仍未向我們呼召；<br/>歷世歷代<br/>我們都求看見你，<br/>但你好像不聽我們禱告。<br/>',NULL,11295,11295);
INSERT INTO stanza VALUES('C760','chorus','你來！就來！<br/>我們呼求你快來！<br/>我們的心所有盼望<br/>是你來！<br/>我們等候你快來！<br/>',NULL,11296,11296);
INSERT INTO stanza VALUES('C760','2','愛主，<br/>自從當年你上升之後，<br/>這裏都變何等枯燥無味；<br/>我們時在祈求，<br/>又時在看守，<br/>每一動靜，<br/>都疑是你已回。<br/>',NULL,11297,11297);
INSERT INTO stanza VALUES('C760','3','景色雖美，<br/>你我何日纔相聚？<br/>山水雖佳，<br/>你今在天何方？<br/>花香鳥語<br/>不能使我有情緒，<br/>因我正在思念你的容光。<br/>',NULL,11298,11298);
INSERT INTO stanza VALUES('C760','4','主阿，<br/>我們等待已久真焦灼，<br/>不知還要多少時候等待；<br/>從每次日出<br/>直到每次日落，<br/>我們都是望你能就回來。<br/>',NULL,11299,11299);
INSERT INTO stanza VALUES('C760','5','當雨每次滴瀝，<br/>海每次澎湃，<br/>風每次吹動，<br/>月每次照明，<br/>我們都望<br/>就是你已經回來，<br/>何等失望，<br/>至今尚無動靜！<br/>',NULL,11300,11300);
INSERT INTO stanza VALUES('C760','6','若非記念你臨行<br/>所賜命令，<br/>我們就要灰心，<br/>無意工作；<br/>但你要我們<br/>一面等你來迎，<br/>一面努力工作為你生活。<br/>',NULL,11301,11301);
INSERT INTO stanza VALUES('C760','7','主阿，<br/>求你記念日子已長久，<br/>應許已過多年尚未應驗；<br/>希望又希望，<br/>一直希望不休，<br/>要來未來，<br/>可否來在今天？<br/>',NULL,11302,11302);
INSERT INTO stanza VALUES('C761','1','主耶穌，主耶穌！<br/>為何你不來！<br/>主耶穌，主耶穌！<br/>為何你不來？<br/>受造物都納悶，<br/>天地與深海，<br/>有牠們與我們，<br/>同望你回來；<br/>現宇宙年漸老，<br/>一切在等待，<br/>我們正同禱告，<br/>求你快回來，<br/>求你快回來，<br/>求你快回來。<br/>',NULL,11303,11303);
INSERT INTO stanza VALUES('C761','2','主耶穌，主耶穌！<br/>為何不回來？<br/>為何故你耽延，<br/>至今不回來？<br/>看他們是已經<br/>等候多少代，<br/>看我們也已經<br/>等候多少載，<br/>你為何不縮短<br/>久望的日子，<br/>因我們頻呼喊，<br/>就來不再遲？<br/>',NULL,11304,11304);
INSERT INTO stanza VALUES('C761','3','主耶穌，主耶穌！<br/>為何不回來？<br/>自從你去天府，<br/>我心無可愛，<br/>我的天就好像<br/>不會再破曉，<br/>我的面就好像<br/>不能再歡笑；<br/>所有的雄心志，<br/>我都失興采，<br/>主耶穌，主耶穌！<br/>為何不回來！<br/>',NULL,11305,11305);
INSERT INTO stanza VALUES('C761','4','求你來，求你來！<br/>四圍所看見，<br/>是退後，是懈怠，<br/>逐一在改變：<br/>愛心是漸冷淡，<br/>受苦漸計算，<br/>信心漸發吁歎，<br/>舉步漸遲緩，<br/>盼望如燈漸滅，<br/>像要不等待，<br/>主耶穌！看這些，<br/>為何不回來？<br/>',NULL,11306,11306);
INSERT INTO stanza VALUES('C761','5','主耶穌，主耶穌！<br/>為何你不來？<br/>主耶穌，主耶穌！<br/>為何你不來？<br/>你是要我等候<br/>到何日何年？<br/>我禱告，我看守，<br/>已難再遲延；<br/>主耶穌，主耶穌！<br/>我求你快來，<br/>主耶穌，主耶穌！<br/>我求你快來！<br/>',NULL,11307,11307);
INSERT INTO stanza VALUES('C762','1','我主，我正等候你再臨，<br/>等候已久，<br/>好像這個等候無窮盡，<br/>一直等候不休；<br/>我是羨慕看見你面容，<br/>聽你聲音；<br/>我是希望能同你交通，<br/>比今更為相親。<br/>',NULL,11308,11308);
INSERT INTO stanza VALUES('C762','chorus','是否須再等幾年，<br/>再有幾度徘徊，<br/>再有幾次流淚、幾思念，<br/>然後，主，你纔回來？<br/>',NULL,11309,11309);
INSERT INTO stanza VALUES('C762','2','寡婦怎能在此不披素，<br/>回想已往；<br/>欲見不得，怎能不哀哭，<br/>怎不念念不忘？<br/>新婦怎能不因愛成病，<br/>切望婚期；<br/>如果久延無日徒引領，<br/>怎不連連歎息？<br/>',NULL,11310,11310);
INSERT INTO stanza VALUES('C762','3','召會等候你許多年代，<br/>從古到今，<br/>一世又一世一直忍耐，<br/>但你仍未降臨；<br/>我也等候你許多歲月，<br/>從少而老，<br/>同時少年次第都永訣，<br/>但是你仍未到。<br/>',NULL,11311,11311);
INSERT INTO stanza VALUES('C762','4','我是已經等待好疲倦，<br/>求你記念；<br/>試煉使我漸易生埋怨，<br/>漸易忘記奉獻。<br/>所以求你不要再遲延，<br/>求你快來；<br/>我已忍耐等候到今天，<br/>實在不易再捱。<br/>',NULL,11312,11312);
INSERT INTO stanza VALUES('C762','5','求你記念我的長等待，<br/>實難繼續；<br/>你若不能及時早回來，<br/>只好讓我前去。<br/>這久、這久，<br/>你不顯榮耀，<br/>留在那邊，<br/>無心的人已經在譏笑，<br/>說你不是遲延。<br/>',NULL,11313,11313);
INSERT INTO stanza VALUES('C762','6','我心所有憂傷與痛楚，<br/>無法平息，<br/>任何的人不能有幫助，<br/>因你不在這裏。<br/>只有你來帶我進永業，<br/>我纔滿願；<br/>我要忘記路上這一切，<br/>當我看見你面。<br/>',NULL,11314,11314);
INSERT INTO stanza VALUES('C763','1','榮耀盼望是基督，<br/>我的生命是祂；<br/>祂已將我靈重生，<br/>現將我魂變化；<br/>還要改變我身體，<br/>用祂歸服大能，<br/>使之和祂身體同，<br/>有祂榮形。<br/>',NULL,11315,11315);
INSERT INTO stanza VALUES('C763','chorus','祂來，祂來，<br/>祂來將我榮耀！<br/>將我身體改變形狀，<br/>和祂身體相肖。<br/>祂來，祂來，<br/>為我身體需要！<br/>祂是我們榮耀盼望<br/>來將我們榮耀。<br/>',NULL,11316,11316);
INSERT INTO stanza VALUES('C763','2','榮耀盼望是基督，<br/>祂是神的奧祕；<br/>使我有分神豐滿，<br/>將神帶到我裏。<br/>祂來使我能與神<br/>在各方面相調，<br/>使我有分祂榮耀，<br/>將祂返照。<br/>',NULL,11317,11317);
INSERT INTO stanza VALUES('C763','3','榮耀盼望是基督，<br/>祂是我的救贖：<br/>將我身體來救贖，<br/>脫離死的痛苦。<br/>祂來使我的身體<br/>變成榮耀形狀；<br/>永遠吞滅了死亡，<br/>將我釋放。<br/>',NULL,11318,11318);
INSERT INTO stanza VALUES('C763','4','榮耀盼望是基督，<br/>祂是我的履歷：<br/>祂的生命我經歷，<br/>祂乃與我合一；<br/>祂來要將我帶進<br/>祂的榮耀、自由，<br/>完全與祂成為一，<br/>直到永久。<br/>',NULL,11319,11319);
INSERT INTO stanza VALUES('C764','1','歷代隱藏奧祕，<br/>向我已顯明，<br/>就是榮耀基督－神實際。<br/>祂是神的化身，<br/>也是我生命，<br/>更是我的榮耀，我所期。<br/>',NULL,11320,11320);
INSERT INTO stanza VALUES('C764','chorus','榮耀！榮耀！<br/>基督在心房！<br/>榮耀！榮耀！<br/>祂是我盼望！<br/>現今在我裏面，<br/>乃是一奧祕！<br/>將來是我榮耀，我所期。<br/>',NULL,11321,11321);
INSERT INTO stanza VALUES('C764','2','祂已將我重生，<br/>在我的靈中；<br/>現今在我魂裏變化我；<br/>還要改變我體，<br/>和祂體相同，<br/>使我完全與祂像符合。<br/>',NULL,11322,11322);
INSERT INTO stanza VALUES('C764','3','今在生命、性情，<br/>祂與我合一；<br/>將來我要在祂榮耀裏；<br/>與祂完全合一，<br/>享受祂自己，<br/>和祂全然相像，毫無異！<br/>',NULL,11323,11323);
INSERT INTO stanza VALUES('C765','1','當我恩主降臨時候，<br/>我要脫盡所有憂愁，<br/>同眾聖徒跟祂而走，<br/>哦！讚美主！<br/>哦！讚美主！<br/>哦！讚美主！<br/>同眾聖徒跟祂而走，<br/>哦！讚美主！<br/>',NULL,11324,11324);
INSERT INTO stanza VALUES('C765','2','當我親眼見我救主，<br/>與祂榮中永遠同住，<br/>我心快樂，我口歡呼，<br/>哦！讚美主！<br/>',NULL,11325,11325);
INSERT INTO stanza VALUES('C765','3','當我見主在那空中，<br/>我十字架就不苦重，<br/>何等暢樂與主相逢！<br/>哦！讚美主！<br/>',NULL,11326,11326);
INSERT INTO stanza VALUES('C765','4','當那時候，<br/>我要證明<br/>無何能勝主的生命，<br/>離地上升何等歡騰！<br/>哦！讚美主！<br/>',NULL,11327,11327);
INSERT INTO stanza VALUES('C765','5','但願我們隱主肋畔！<br/>合而為一不再離散，<br/>好叫耶穌意足心滿，<br/>在祂來時！<br/>',NULL,11328,11328);
INSERT INTO stanza VALUES('C765','6','來罷我王，願你就來！<br/>接等你者與你同在，<br/>使愛你者得你賞賚，<br/>主阿，快來！<br/>',NULL,11329,11329);
INSERT INTO stanza VALUES('C766','1','榮耀的盼望，<br/>基督要再臨！<br/>我們要被提，<br/>賤體變榮身，<br/>與祂同榮耀，<br/>享受祂至寶，<br/>那時纔知道救恩有多高。<br/>',NULL,11330,11330);
INSERT INTO stanza VALUES('C766','chorus','榮耀盼望，基督再臨！<br/>榮耀盼望，基督再臨！<br/>我們要被提，<br/>賤體變榮身，<br/>榮耀的盼望，<br/>基督要再臨！<br/>',NULL,11331,11331);
INSERT INTO stanza VALUES('C766','2','榮耀的盼望，<br/>基督要再臨！<br/>舊造全脫去，<br/>一切都更新，<br/>不再有歎息，<br/>盡都是逍遙，<br/>那時纔嘗到救恩的上好。<br/>',NULL,11332,11332);
INSERT INTO stanza VALUES('C766','3','榮耀的盼望，<br/>基督要再臨！<br/>與祂同作王轄管列國民，<br/>且要作祭司事奉永活神，<br/>那時纔享受至高的救恩。<br/>',NULL,11333,11333);
INSERT INTO stanza VALUES('C766','4','榮耀的盼望，<br/>基督要再臨！<br/>等候當儆醒，<br/>事奉當忠心，<br/>燈油常豫備，<br/>前程努力奔；<br/>不然，<br/>怎配得上好的救恩？<br/>',NULL,11334,11334);
INSERT INTO stanza VALUES('C767','1','受造之物切望等候<br/>神的眾子顯出來，<br/>指望進入神子自由，<br/>脫離虛空與敗壞。<br/>',NULL,11335,11335);
INSERT INTO stanza VALUES('C767','2','一切受造都在歎息，<br/>勞苦服在虛空下，<br/>指望得著完全釋放，<br/>脫離敗壞的管轄。<br/>',NULL,11336,11336);
INSERT INTO stanza VALUES('C767','3','甚至我們也在歎息，<br/>等候兒子的名分；<br/>我們須有基督身量，<br/>成為長大成熟人。<br/>',NULL,11337,11337);
INSERT INTO stanza VALUES('C767','4','為此聖靈替我歎息，<br/>願我變成神子像；<br/>祂使萬事互相效力，<br/>將我模成主模樣。<br/>',NULL,11338,11338);
INSERT INTO stanza VALUES('C767','5','神要將我帶進榮耀，<br/>那時我要被榮耀；<br/>用祂自己將我浸透，<br/>全然聖別成新造。<br/>',NULL,11339,11339);
INSERT INTO stanza VALUES('C767','6','所有受造要被釋放，<br/>得進『榮耀』的自由；<br/>豹子與山羊羔同臥，<br/>獅子喫草好像牛。<br/>',NULL,11340,11340);
INSERT INTO stanza VALUES('C767','7','長大與主同作後嗣，<br/>承受兒子的名分；<br/>作祂弟兄與祂同榮，<br/>神的榮耀顯我身。<br/>',NULL,11341,11341);
INSERT INTO stanza VALUES('C768','1','阿，神中心的觀念，<br/>乃是與人相結聯，<br/>祂來作人的一切，<br/>使祂計畫得成全。<br/>',NULL,11342,11342);
INSERT INTO stanza VALUES('C768','2','人是被造的瓦器，<br/>有靈、有魂也有體；<br/>人可取神作生命，<br/>藉此與神成為一。<br/>',NULL,11343,11343);
INSERT INTO stanza VALUES('C768','3','藉著生命的流通，<br/>人變寶石為神用；<br/>適合為神造居所，<br/>讓神彰顯祂光榮。<br/>',NULL,11344,11344);
INSERT INTO stanza VALUES('C768','4','這是聖城神所建，<br/>這是居所神所羨；<br/>這是新耶路撒冷，<br/>完滿成全神心願。<br/>',NULL,11345,11345);
INSERT INTO stanza VALUES('C768','5','這是眾聖的建造，<br/>這是神、人的相調；<br/>原是父神所籌畫，<br/>滿足神、人的需要。<br/>',NULL,11346,11346);
INSERT INTO stanza VALUES('C768','6','神和羔羊的寶座，<br/>在這榮耀的居所；<br/>從這掌權的中心，<br/>流出聖靈生命河。<br/>',NULL,11347,11347);
INSERT INTO stanza VALUES('C768','7','基督乃是生命樹，<br/>長在河的兩岸處；<br/>結出神聖生命果，<br/>供應眾聖作食物。<br/>',NULL,11348,11348);
INSERT INTO stanza VALUES('C768','8','神在基督裏作光，<br/>透過全城來照亮；<br/>死亡之夜全驅盡，<br/>神聖之光照輝煌。<br/>',NULL,11349,11349);
INSERT INTO stanza VALUES('C768','9','神在人裏，人在神，<br/>互為居所來藏身；<br/>人的內容乃是神，<br/>神的表現乃是人。<br/>',NULL,11350,11350);
INSERT INTO stanza VALUES('C769','1','神的永遠心意，<br/>是與人聯合，<br/>要人作祂器皿，<br/>來將祂盛著；<br/>祂作人的生命，<br/>將人全充滿，<br/>使人與祂合一，<br/>將祂來彰顯。<br/>',NULL,11351,11351);
INSERT INTO stanza VALUES('C769','2','神照自己形像，<br/>將人造完全，<br/>使人能有資格，<br/>成全祂心願；<br/>要人將祂接受<br/>作人生命樹，<br/>成為祂的豐滿，<br/>如妻之於夫。<br/>',NULL,11352,11352);
INSERT INTO stanza VALUES('C769','3','藉祂生命流通，<br/>要將人變化，<br/>變成寶貴材料，<br/>與祂像無差。<br/>如此同被建造，<br/>作祂的配偶，<br/>也作祂的居所，<br/>給祂來享受。<br/>',NULL,11353,11353);
INSERT INTO stanza VALUES('C769','4','這是榮耀聖城，<br/>新耶路撒冷；<br/>神與聖徒相調，<br/>互居之所成。<br/>祂作他們內容，<br/>她作祂彰顯，<br/>與祂同享榮耀，<br/>合一到永遠。<br/>',NULL,11354,11354);
INSERT INTO stanza VALUES('C769','5','神是惟一中心，<br/>在寶座掌權；<br/>藉祂生命權柄，<br/>聖徒全結聯。<br/>因祂榮耀光照，<br/>都活在光中，<br/>彼此和諧一致，<br/>彰顯祂光榮。<br/>',NULL,11355,11355);
INSERT INTO stanza VALUES('C769','6','神是生命活水，<br/>也是生命糧，<br/>充解聖徒飢渴，<br/>供他們飽享。<br/>祂是他們聖殿，<br/>他們活其間；<br/>在祂面光之中，<br/>敬拜到永遠。<br/>',NULL,11356,11356);
INSERT INTO stanza VALUES('C770','1','哦，主，<br/>撒冷是你所建設，<br/>來賜給世上<br/>所有蒙恩的罪人；<br/>一切蒙血救贖，<br/>洗得潔淨者，<br/>你都賜給權柄<br/>可入她的門。<br/>光是她榮耀<br/>已足使我羨慕，<br/>何況我主<br/>你是住在她中間，<br/>怎不叫我<br/>被吸引注目遠處，<br/>就是無意想時<br/>也是在想念。<br/>',NULL,11357,11357);
INSERT INTO stanza VALUES('C770','2','哦，主，<br/>當我每想到撒冷，<br/>我就切切想要<br/>看見你的容顏，<br/>我心盼望<br/>我能早日被提升，<br/>好使我能早日<br/>倚傍你身邊。<br/>我心真羨慕<br/>能早日到新地，<br/>能同所有愛你的人<br/>來愛你，<br/>時常歌頌<br/>你的愛無邊無極，<br/>時常記念你愛<br/>捨己的蹤跡。<br/>',NULL,11358,11358);
INSERT INTO stanza VALUES('C770','3','哦，主，<br/>我所歡喜和羨慕，<br/>不是紅石綠寶，<br/>也非碧玉精金，<br/>我所想念乃是你，<br/>愛我的主！<br/>你是何等可愛，<br/>何等傾我心！<br/>我求你早日<br/>成全我的心願，<br/>提接我到你前，<br/>不再有別離，<br/>好叫我與你<br/>同住直到永遠，<br/>常能看見你，<br/>也常能聽見你。<br/>',NULL,11359,11359);
INSERT INTO stanza VALUES('C770','4','撒冷是愛，是光，<br/>又是詩，<br/>因為有你在內作中心，<br/>並獎賞；<br/>因為有你自己<br/>和你的丰姿，<br/>纔使撒冷對我<br/>能成為盼望！<br/>因為有了你，<br/>萬物纔得更新，<br/>歎息纔成過去，<br/>眼淚纔會乾，<br/>我心纔會滿了<br/>安息與歡欣，<br/>主阿，<br/>為何你不早日快顯現？<br/>',NULL,11360,11360);
INSERT INTO stanza VALUES('C771','1','他等候一座城，<br/>卻住在帳棚，<br/>這天城的旅客，<br/>一直奔前程；<br/>他有美好證據，<br/>前途實堪誇，<br/>難怪他不尋求<br/>地上的榮華。<br/>',NULL,11361,11361);
INSERT INTO stanza VALUES('C771','chorus','城！城！榮美城！<br/>神與人的住處，<br/>新耶路撒冷！<br/>',NULL,11362,11362);
INSERT INTO stanza VALUES('C771','2','他等候一座城，<br/>他神的住處，<br/>他沒有，<br/>也不求地上的房屋；<br/>因神豈非說過，<br/>屬天的家鄉，<br/>是那不離正道旅客<br/>所安享。<br/>',NULL,11363,11363);
INSERT INTO stanza VALUES('C771','3','他等候一座城，<br/>雖然有時因跋涉苦，<br/>喪失多，有歎息聲音，<br/>但一想到那城，<br/>就引聲歌唱，<br/>因為路雖崎嶇，<br/>必定不會長。<br/>',NULL,11364,11364);
INSERT INTO stanza VALUES('C771','4','他等候一座城，<br/>我們今亦然：<br/>望能在你城中，<br/>同你永為伴，<br/>享受你的豫備；<br/>因此也願意<br/>以帳棚為寄廬，<br/>同你客此地。<br/>',NULL,11365,11365);
INSERT INTO stanza VALUES('C772','1','聖城同救主是我們目標，<br/>我們的永分，<br/>燦爛又榮耀；<br/>我身雖在此，<br/>靈卻已在彼，<br/>深望與恩主立在一起，<br/>深望與恩主立在一起。<br/>',NULL,11366,11366);
INSERT INTO stanza VALUES('C772','2','神聖的目標，<br/>新耶路撒冷，<br/>乃是神為人豫備的聖城；<br/>所有蒙寶血救贖的聖人，<br/>都能有權利享受這福分。<br/>',NULL,11367,11367);
INSERT INTO stanza VALUES('C772','3','哦，那座聖城，<br/>我每一瞻仰，<br/>就渴想見我恩主的面光；<br/>巴不得早日聽見祂呼聲，<br/>得進入那城，<br/>永享祂豐盛。<br/>',NULL,11368,11368);
INSERT INTO stanza VALUES('C772','4','我心所渴慕，<br/>並非甜安息，<br/>我久所盼望，<br/>也非何福氣；<br/>乃是主自己－我榮耀盼望，<br/>就是我永分，<br/>作我的獎賞。<br/>',NULL,11369,11369);
INSERT INTO stanza VALUES('C772','5','哦，求主耶穌，<br/>快照我心願，<br/>來接愛你者到你的面前！<br/>在那聖城中享受你自己，<br/>同住並同榮，<br/>永不再分離。<br/>',NULL,11370,11370);
INSERT INTO stanza VALUES('C772','6','那時的一切都因你更新，<br/>新天並新地，<br/>陪新城、新人！<br/>神榮耀自己要作我永分；<br/>哦，榮耀時辰，<br/>主阿，快顯身！<br/>',NULL,11371,11371);
INSERT INTO stanza VALUES('C773','1','當我跑盡應跑道路，<br/>打過當打的美仗，<br/>我必被提升天<br/>進入主榮光；<br/>當我守住所信真道，<br/>甚至殉道毫不爽，<br/>必得聖城為獎賞。<br/>',NULL,11372,11372);
INSERT INTO stanza VALUES('C773','chorus','我必被提進入榮光，<br/>同主住在那聖城，<br/>新耶路撒冷，<br/>新耶路撒冷！<br/>同眾勝者歡呼歌唱，<br/>讚美主恩頌主名，<br/>在那新耶路撒冷！<br/>',NULL,11373,11373);
INSERT INTO stanza VALUES('C773','2','今在異地作客飄泊，<br/>雖受窘困仍歡暢，<br/>因我不久必到<br/>更美的家鄉；<br/>親朋雖以世福為上，<br/>但我天天所仰望，<br/>乃是聖城在天上。<br/>',NULL,11374,11374);
INSERT INTO stanza VALUES('C773','3','雖然道路崎嶇難行，<br/>使我腿酸手下垂，<br/>但一想到那城，<br/>全身力即回；<br/>雖然我眼難免流淚，<br/>但是我心永不灰，<br/>因有聖城為我備。<br/>',NULL,11375,11375);
INSERT INTO stanza VALUES('C773','4','我今鬥拳，不是打空，<br/>奔跑不是無目標，<br/>乃是照神心意，<br/>追求那上好；<br/>忘記背後，努力面前，<br/>向著標竿一直跑，<br/>要得聖城的榮耀。<br/>',NULL,11376,11376);
INSERT INTO stanza VALUES('C773','chorus','主愛何豐，主恩何盛，<br/>使我得住那聖城，<br/>新耶路撒冷，<br/>新耶路撒冷！<br/>眾聖歡騰，眾聖和聲，<br/>讚美主恩頌主名，<br/>在那新耶路撒冷！<br/>',NULL,11377,11377);
INSERT INTO stanza VALUES('C774','1','在起初時候，<br/>原是一園子，<br/>但到了末後，<br/>卻是一城池；<br/>在園子那裏，<br/>乃是神創造，<br/>在城池這裏，<br/>成了神建造。<br/>',NULL,11378,11378);
INSERT INTO stanza VALUES('C774','2','無論在園裏，<br/>或是在城中，<br/>河與生命樹，<br/>都是神所重；<br/>河是指聖靈，<br/>作湧流生命，<br/>樹是指基督，<br/>作生命供應。<br/>',NULL,11379,11379);
INSERT INTO stanza VALUES('C774','3','無論在園子，<br/>或是在城池，<br/>都有同三種貴重的物質：<br/>精金和珍珠、<br/>並貴重寶石，<br/>為著神建造，<br/>彰顯神所是。<br/>',NULL,11380,11380);
INSERT INTO stanza VALUES('C774','4','但是在園裏，<br/>這三種東西，<br/>不過是材料，<br/>散佈在那裏；<br/>乃是在城中，<br/>全都被建造，<br/>成為神居所，<br/>彰顯神榮耀。<br/>',NULL,11381,11381);
INSERT INTO stanza VALUES('C774','5','人在園子裏，<br/>乃是土所造，<br/>性質屬於土，<br/>無屬天榮耀；<br/>那時生命樹，<br/>也在人外面，<br/>未作人生命，<br/>將人來改變。<br/>',NULL,11382,11382);
INSERT INTO stanza VALUES('C774','6','但是在城中，<br/>神聖生命樹，<br/>長在人裏面，<br/>團體人中住；<br/>指明神基督是神聖生命，<br/>在人的裏面將生命供應。<br/>',NULL,11383,11383);
INSERT INTO stanza VALUES('C774','7','人之被創造，<br/>乃是為這城，<br/>所以須重生，<br/>變化質與形，<br/>能成為精金、<br/>珍珠和寶石，<br/>作主的身體，<br/>與主像相似。<br/>',NULL,11384,11384);
INSERT INTO stanza VALUES('C774','8','在那園子裏，<br/>也有一新婦，<br/>作亞當配偶，<br/>出於他肋骨；<br/>這聖城本身，<br/>就是一新婦，<br/>作基督豐滿，<br/>出於祂豐富。<br/>',NULL,11385,11385);
INSERT INTO stanza VALUES('C774','9','這聖城乃是神完滿建造，<br/>眾聖的組合，<br/>在靈裏相調；<br/>作神的居所，<br/>給神來居住，<br/>作基督新婦，<br/>使祂心滿足。<br/>',NULL,11386,11386);
INSERT INTO stanza VALUES('C774','10','是神的表現，<br/>終極且豐滿，<br/>是宇宙團體，<br/>神聖又完全；<br/>三一神榮耀，<br/>她全然彰顯，<br/>作基督配偶，<br/>榮耀達極點。<br/>',NULL,11387,11387);
INSERT INTO stanza VALUES('C775','1','哦主耶穌，你的贖民<br/>是你身體並新婦，<br/>作你豐滿、作你表現，<br/>使你彰顯你豐富。<br/>你永是她一切一切，<br/>她是你恩的宣告；<br/>你要將她完全浸透，<br/>要她有分你榮耀。<br/>',NULL,11388,11388);
INSERT INTO stanza VALUES('C775','chorus','看哪，神的聖城！<br/>滿了神的光明！<br/>這是神完滿的表現，<br/>永顯於人性。<br/>',NULL,11389,11389);
INSERT INTO stanza VALUES('C775','2','是神與人完全相調，<br/>大哉，敬虔的奧祕；<br/>神的榮耀，豐滿、燦爛，<br/>人作神居，榮無比。<br/>是一宇宙偉大器皿，<br/>全然表現神豐滿；<br/>完全調著神的聖潔，<br/>使神榮美得彰顯。<br/>',NULL,11390,11390);
INSERT INTO stanza VALUES('C775','3','乃是神所變化的人，<br/>一個永活的組合；<br/>如同珍珠、寶石珍貴，<br/>與神榮形相符合。<br/>從神寶座－她的中心，<br/>流出生命的活水；<br/>基督在此作生命樹，<br/>結出鮮果，豐而美。<br/>',NULL,11391,11391);
INSERT INTO stanza VALUES('C775','4','是一永遠精金燈臺，<br/>托著基督作明燈；<br/>神在基督作她榮光，<br/>藉著聖靈來照明。<br/>乃是終極、完滿表現，<br/>是神調人的建造；<br/>乃是神、人互作居所，<br/>是神計畫的目標。<br/>',NULL,11392,11392);
INSERT INTO stanza VALUES('C776','1','何等榮耀，何等光明，<br/>何等神聖耶路撒冷！<br/>乃是神在人間帳幕，<br/>又是羔羊所娶新婦。<br/>',NULL,11393,11393);
INSERT INTO stanza VALUES('C776','2','新約聖徒，舊約選民，<br/>都是聖城組成成分；<br/>同蒙救贖，同承應許，<br/>同被建造，給神安居。<br/>',NULL,11394,11394);
INSERT INTO stanza VALUES('C776','3','聖城四方，完美、方正，<br/>長寬高度全都相等，<br/>無何多餘，無何不及，<br/>無何偏斜，無何不齊。<br/>',NULL,11395,11395);
INSERT INTO stanza VALUES('C776','4','精金城身、精金街道，<br/>如同玻璃明淨、透照；<br/>象徵神的尊貴生命，<br/>就是聖城本質本性。<br/>',NULL,11396,11396);
INSERT INTO stanza VALUES('C776','5','十二城門全是珍珠，<br/>因蒙基督奧妙救贖；<br/>重生使其變質成珍，<br/>神聖事物由此入門。<br/>',NULL,11397,11397);
INSERT INTO stanza VALUES('C776','6','十二牆基十二寶石，<br/>石石都是珍貴裝飾；<br/>經過燒壓，經過組織，<br/>方有如此永遠價值。<br/>',NULL,11398,11398);
INSERT INTO stanza VALUES('C776','7','碧玉城牆明如水晶，<br/>神的光輝在此照明；<br/>射出神的榮耀光芒，<br/>照出神的碧玉形像。<br/>',NULL,11399,11399);
INSERT INTO stanza VALUES('C776','8','城牆為界，裏外分別，<br/>摒除一切不聖、不潔；<br/>惟有精金、珍珠、寶石，<br/>能合聖城榮耀性質。<br/>',NULL,11400,11400);
INSERT INTO stanza VALUES('C776','9','神和羔羊為城的殿，<br/>人得時常見祂榮面；<br/>祂的同在永不離開，<br/>人在祂前事奉、敬拜。<br/>',NULL,11401,11401);
INSERT INTO stanza VALUES('C776','10','城不需要日、月、燈光，<br/>有神榮耀晝夜照亮；<br/>羔羊是燈，城是燈臺，<br/>將神榮光四射城外。<br/>',NULL,11402,11402);
INSERT INTO stanza VALUES('C776','11','城中神和羔羊寶座，<br/>流出生命活水明河；<br/>流在城內街道中間，<br/>生命果樹長在兩岸。<br/>',NULL,11403,11403);
INSERT INTO stanza VALUES('C776','12','這是表明神的生命，<br/>不僅流出、滋潤、供應，<br/>並且帶著神的權柄，<br/>全城盤旋流通、運行。<br/>',NULL,11404,11404);
INSERT INTO stanza VALUES('C776','13','所以神性成為街道，<br/>滿城盡是精金、珠寶；<br/>有道可行，有水可飲，<br/>生命糧食豐富、鮮新。<br/>',NULL,11405,11405);
INSERT INTO stanza VALUES('C776','14','十二數目表明政權，<br/>也是表明永遠完全；<br/>更是表明神、人調和，<br/>三四相乘，融洽無隔。<br/>',NULL,11406,11406);
INSERT INTO stanza VALUES('C776','15','再無死亡，再無黑夜，<br/>咒詛、痛苦也都根絕；<br/>舊事全過，一切更新，<br/>神、人互居，相安相親。<br/>',NULL,11407,11407);
INSERT INTO stanza VALUES('C776','16','聖城非但有神形像，<br/>並且為神掌權作王；<br/>成全神的永遠心願，<br/>滿足神心，直到永遠！<br/>',NULL,11408,11408);
INSERT INTO stanza VALUES('C777','1','在那新天與新地，<br/>有新耶路撒冷；<br/>她有神聖的光輝，<br/>因是由神而生。<br/>',NULL,11409,11409);
INSERT INTO stanza VALUES('C777','chorus','看，她有神的形像，<br/>也有分神的榮光，<br/>且與主一同作王，<br/>哦，神的聖城！<br/>',NULL,11410,11410);
INSERT INTO stanza VALUES('C777','2','城與其中的街道，<br/>都是透明精金，<br/>牆和根基是寶石，<br/>珍珠是作城門。<br/>',NULL,11411,11411);
INSERT INTO stanza VALUES('C777','3','生命水河如水晶，<br/>流在城內街道；<br/>河的兩岸生命樹，<br/>滿足所有需要。<br/>',NULL,11412,11412);
INSERT INTO stanza VALUES('C777','4','在那光明的城中，<br/>神是一切一切；<br/>祂在羔羊裏作光，<br/>城就永無黑夜。<br/>',NULL,11413,11413);
INSERT INTO stanza VALUES('C778','1','全部聖經新舊兩約，<br/>都將聖民比作二物：<br/>新婦作神心愛佳偶，<br/>建築作神安居之處。<br/>',NULL,11414,11414);
INSERT INTO stanza VALUES('C778','2','舊約所有召會豫表，<br/>不外婦女以及建築；<br/>婦女作人稱心配偶，<br/>建築給人安居作主。<br/>',NULL,11415,11415);
INSERT INTO stanza VALUES('C778','3','古時神的以色列民，<br/>被神稱作祂的妻子；<br/>其中有殿給神居住，<br/>也有聖城給神管治。<br/>',NULL,11416,11416);
INSERT INTO stanza VALUES('C778','4','為人之神，神人基督，<br/>作了新郎來娶新婦；<br/>祂用己命將她重生，<br/>可作配偶使祂滿足。<br/>',NULL,11417,11417);
INSERT INTO stanza VALUES('C778','5','基督今在復活裏面，<br/>像所羅門為神建殿，<br/>使神可有安息之所，<br/>成全祂的所有心願。<br/>',NULL,11418,11418);
INSERT INTO stanza VALUES('C778','6','召會乃是基督新婦，<br/>使祂稱心，作祂豐滿；<br/>召會也是神的居所，<br/>給神安居，將神彰顯。<br/>',NULL,11419,11419);
INSERT INTO stanza VALUES('C778','7','將來的新耶路撒冷，<br/>乃是所有新婦、建築，<br/>一切豫表終極成全，<br/>使神得以心滿意足。<br/>',NULL,11420,11420);
INSERT INTO stanza VALUES('C778','8','她是新婦作主配偶，<br/>使主稱心，作主豐滿；<br/>也是帳幕作神居所，<br/>給神安居，作王掌權。<br/>',NULL,11421,11421);
INSERT INTO stanza VALUES('C778','9','她是神在人裏工作<br/>終極完滿的集大成，<br/>作神人性裏的表現，<br/>豐滿、永遠、而且神聖。<br/>',NULL,11422,11422);
INSERT INTO stanza VALUES('C779','1','在基督裏歸一萬有，<br/>乃是我神的經營；<br/>基督作頭並作中心，<br/>萬有和諧而安寧。<br/>',NULL,11423,11423);
INSERT INTO stanza VALUES('C779','2','基督元首要作中心，<br/>神在其中作亮光；<br/>基督和神同坐寶座，<br/>使其心願全得賞。<br/>',NULL,11424,11424);
INSERT INTO stanza VALUES('C779','3','基督要作生命、內容，<br/>歸一萬有於光中；<br/>眾聖要作祂的器皿，<br/>永遠彰顯祂光榮。<br/>',NULL,11425,11425);
INSERT INTO stanza VALUES('C779','4','撒但已將他的自己<br/>注到人裏，毀萬有，<br/>帶進黑暗、敗壞、紊亂，<br/>使神計畫難成就。<br/>',NULL,11426,11426);
INSERT INTO stanza VALUES('C779','5','基督來將祂的自己<br/>分賜與人作生命，<br/>拯救人脫黑暗權勢，<br/>黑暗、死亡，再無能。<br/>',NULL,11427,11427);
INSERT INTO stanza VALUES('C779','6','藉召會－祂的身體，<br/>要將萬有歸於一；<br/>萬有都要聯得合式，<br/>無論大小成一系。<br/>',NULL,11428,11428);
INSERT INTO stanza VALUES('C779','7','在這元首基督之下，<br/>萬有聯結而存立；<br/>在祂召會所照光中，<br/>萬有全都歸於一。<br/>',NULL,11429,11429);
INSERT INTO stanza VALUES('C779','8','有祂作頭並作中心，<br/>萬有全都能和諧；<br/>藉祂身體所有光照，<br/>萬有相安無間歇。<br/>',NULL,11430,11430);
INSERT INTO stanza VALUES('C779','9','再無黑暗，再無死亡，<br/>再無敗壞與虛空；<br/>萬有都要脫離轄制，<br/>永遠居於自由中。<br/>',NULL,11431,11431);
INSERT INTO stanza VALUES('C780','1','那日我神的寶貝，<br/>不再藏於瓦器，<br/>乃從變化的人中，<br/>顯出無遮美麗。<br/>',NULL,11432,11432);
INSERT INTO stanza VALUES('C780','2','藉那偉大的金器，<br/>神的榮耀照亮；<br/>不用日、月來光照，<br/>因神自己作光。<br/>',NULL,11433,11433);
INSERT INTO stanza VALUES('C780','3','全城珍珠和寶石，<br/>滿了神的美麗；<br/>光輝照耀如碧玉，<br/>榮耀燦爛無比。<br/>',NULL,11434,11434);
INSERT INTO stanza VALUES('C780','4','在那偉大器皿中，<br/>榮光永不暗淡，<br/>明光豐滿照四方，<br/>驅盡地上黑暗。<br/>',NULL,11435,11435);
INSERT INTO stanza VALUES('C780','5','所有新造要看見，<br/>在彼神光四佈；<br/>那個照耀的器皿，<br/>乃是羔羊新婦。<br/>',NULL,11436,11436);
INSERT INTO stanza VALUES('C780','6','那個榮耀的金器，<br/>令人向神敬拜，<br/>神在榮中羔羊裏，<br/>顯現直到萬代。<br/>',NULL,11437,11437);
INSERT INTO stanza VALUES('CF1','1','頌讚與尊貴與榮耀歸你，<br/>與榮耀歸你，<br/>與榮耀歸你。<br/>頌讚與尊貴與榮耀歸你，<br/>直到永永遠遠。<br/>讚祂！讚祂！<br/>聖徒都要拜祂！<br/>讚祂！讚祂！<br/>直到永永遠遠。<br/>阿利路亞！<br/>',NULL,11438,11438);
INSERT INTO stanza VALUES('CF2','1','阿利路、阿利路、<br/>阿利路、阿利路亞，<br/>讚美我主！<br/>阿利路、阿利路、<br/>阿利路、阿利路亞，<br/>讚美我主！<br/>讚美我主，阿利路亞，<br/>讚美我主！阿利路亞，<br/>讚美我主！阿利路亞，<br/>讚美我主！<br/>',NULL,11439,11439);
INSERT INTO stanza VALUES('CF3','1','諸天述說神的榮耀；<br/>穹蒼傳揚祂的巧妙。<br/>日夜發言，曉諭不已，<br/>通遍天下，傳到地極。<br/>神的永能，和祂特徵，<br/>藉祂創造全都顯明；<br/>雖非人眼所能見到，<br/>但觀造物即可洞曉。<br/>',NULL,11440,11440);
INSERT INTO stanza VALUES('CF3','2','創造天地、萬物活神，<br/>為證自己存在可信：<br/>常施恩惠，賞賜豐稔，<br/>使人飽足，喜樂滿心。<br/>天降甘霖，地生五穀，<br/>永活真神所賜之福；<br/>豐衣足食，享受天恩，<br/>理當念及造物之神。<br/>',NULL,11441,11441);
INSERT INTO stanza VALUES('CF3','3','天地之主，萬物之神，<br/>生命、氣息，賜給萬人；<br/>年限、疆界，由祂定準，<br/>要人揣摩，將祂求尋。<br/>自隱之神，人間之謎；<br/>不見之神，宇宙之祕。<br/>此一真理，人人當知，<br/>宇宙意義始能賞識。<br/>',NULL,11442,11442);
INSERT INTO stanza VALUES('CF3','4','不見之神顯於所見，<br/>神聖啟示尚非完全；<br/>神的身位，神的形像，<br/>還需一人前來表彰。<br/>耶穌基督，神的愛子，<br/>降世成為人的樣式；<br/>神的特性，神的所是，<br/>全由這人彰顯盡致。<br/>',NULL,11443,11443);
INSERT INTO stanza VALUES('CF3','5','奧祕基督，奇妙救主，<br/>乃是神在人間顯出。<br/>原是永遠無限的神，<br/>竟作時間有限的人。<br/>奧妙基督，神的化身，<br/>神人調和，驚人佳音。<br/>祂是真神，又是真人，<br/>要進你心，作你福分。<br/>',NULL,11444,11444);
INSERT INTO stanza VALUES('CF3','6','神的神性藏祂裏面，<br/>神的榮形從祂彰顯。<br/>前在肉身成功救贖，<br/>今成那靈與人聯屬。<br/>神人基督，道成肉身，<br/>捨命流血，救贖罪人；<br/>從死復活，化身那靈，<br/>為進你靈，作你生命。<br/>',NULL,11445,11445);
INSERT INTO stanza VALUES('CF4','1','人是神造的容器，<br/>有靈有魂又有體。<br/>神要作人的內容，<br/>從人顯出祂光榮。<br/>',NULL,11446,11446);
INSERT INTO stanza VALUES('CF4','2','人原有神的形像，<br/>身分地位何高尚；<br/>還須有神的生命，<br/>得以分享祂性情。<br/>',NULL,11447,11447);
INSERT INTO stanza VALUES('CF4','3','基督乃是神顯出，<br/>為人受死，將人贖；<br/>復活成為生命靈，<br/>進入人靈作生命。<br/>',NULL,11448,11448);
INSERT INTO stanza VALUES('CF4','4','人的生存無基督，<br/>一切盡都感虛無：<br/>失缺人生的意義，<br/>無指無望，無目的。<br/>',NULL,11449,11449);
INSERT INTO stanza VALUES('CF4','5','接受基督作生命，<br/>人就靈裏得重生；<br/>時時憑祂而生活，<br/>虛空人生變詩歌。<br/>',NULL,11450,11450);
INSERT INTO stanza VALUES('CF4','6','如此便能彰顯神，<br/>也能造福於人群，<br/>流出活水的江河，<br/>解除群眾的乾渴。<br/>',NULL,11451,11451);
INSERT INTO stanza VALUES('CF4','7','基督凱歸榮耀中，<br/>你的身體必得榮，<br/>變得與祂形狀同，<br/>同榮共存永無終。<br/>',NULL,11452,11452);
INSERT INTO stanza VALUES('CF5','1','何大神蹟！何深奧祕！<br/>神竟與人聯調為一！<br/>神成為人，人成為神，<br/>天使、世人莫測經綸；<br/>出自神的心愛美意，<br/>達到神的最高目的。<br/>出自神的心愛美意，<br/>達到神的最高目的。<br/>',NULL,11453,11453);
INSERT INTO stanza VALUES('CF5','2','神成肉身，來作神人，<br/>為要使我能成為神，<br/>生命、性情與祂同類，<br/>惟我無分祂的神位；<br/>祂的屬性變我美德，<br/>祂的榮形在我顯活。<br/>祂的屬性變我美德，<br/>祂的榮形在我顯活。<br/>',NULL,11454,11454);
INSERT INTO stanza VALUES('CF5','3','不再是我單獨活著，<br/>乃是神我共同生活；<br/>並與眾聖神裏配搭，<br/>建成三一宇宙之家，<br/>且成基督生機身體，<br/>作祂顯身團體大器。<br/>且成基督生機身體，<br/>作祂顯身團體大器。<br/>',NULL,11455,11455);
INSERT INTO stanza VALUES('CF5','4','最終聖城耶路撒冷，<br/>異象、啟示集其大成。<br/>三一之神，三部分人，<br/>永世對耦是人又神；<br/>神性人性互為居所，<br/>神的榮耀在人顯赫。<br/>神性人性互為居所，<br/>神的榮耀在人顯赫。<br/>',NULL,11456,11456);
INSERT INTO stanza VALUES('CF6','1','神，你生命所施拯救，<br/>全都照你公義要求；<br/>你的救恩完整無弊，<br/>既合法理，又富生機。<br/>',NULL,11457,11457);
INSERT INTO stanza VALUES('CF6','2','救贖是照法理完成，<br/>拯救是由生機施行；<br/>法理滿足你的公義，<br/>生機成就你的美意。<br/>',NULL,11458,11458);
INSERT INTO stanza VALUES('CF6','3','法理使我得你稱義，<br/>生機使我與你合一：<br/>將我重生成為神人，<br/>將我聖化全人更新。<br/>',NULL,11459,11459);
INSERT INTO stanza VALUES('CF6','4','將我變化模成榮形，<br/>新陳代謝顯於生命；<br/>生命成熟長大成人，<br/>同人配搭建成一身。<br/>',NULL,11460,11460);
INSERT INTO stanza VALUES('CF6','5','身體得贖，進入榮耀，<br/>兒子名分達到至高；<br/>與你相調，互為居所，<br/>聖城撒冷成我詩歌。<br/>',NULL,11461,11461);
INSERT INTO stanza VALUES('CS1','1','當我們開口讚美，<br/>主就得著榮耀；<br/>當歡聲響徹雲霄，<br/>天使拍手叫好！<br/>我們是活神見證，<br/>該讓世人知道；<br/>撒但全軍必潰散，<br/>聞聲四處竄逃。<br/>',NULL,11462,11462);
INSERT INTO stanza VALUES('CS1','2','我們閉口就失敗，<br/>換來魔鬼嘲笑；<br/>因此為何不開火，<br/>直到把他趕跑？<br/>以『讚美為祭』獻上，<br/>大大歡呼釋放，<br/>怎能說這是丟臉？<br/>為神應該發狂！<br/>',NULL,11463,11463);
INSERT INTO stanza VALUES('CS1','3','世界從未助我們<br/>向主獻讚美祭，<br/>從未向祂歸榮耀，<br/>從未向祂感激。<br/>因此我們豈需要，<br/>得允許而讚美？<br/>喊出！釋放你的靈！<br/>祂賜無限恩惠。<br/>',NULL,11464,11464);
INSERT INTO stanza VALUES('CS1','4','弟兄們，不要靜默！<br/>姊妹們，大聲喊！<br/>將神的得勝祝福，<br/>傳遍遠近四方。<br/>現在是讚美之時，<br/>任何代價不顧！<br/>因祂救恩而喜樂，<br/>因祂憐憫歡呼！<br/>',NULL,11465,11465);
INSERT INTO stanza VALUES('CS2','1','看哪，地上萬民聚集，<br/>一同謀算虛妄事；<br/>君王臣宰起來商議，<br/>同聲一氣抵擋主。<br/>『我們掙開一切捆綁，<br/>脫去他們的繩索，』<br/>世上君王如此設謀，<br/>抵擋神並受膏者。<br/>',NULL,11466,11466);
INSERT INTO stanza VALUES('CS2','2','那坐天上的必發笑，<br/>主必定嗤笑他們；<br/>那時祂在怒中責備，<br/>烈怒中驚嚇他們。<br/>在祂的錫安聖山上，<br/>神已膏祂的君王─<br/>這是神自己的宣告，<br/>警戒地上的諸王。<br/>',NULL,11467,11467);
INSERT INTO stanza VALUES('CS2','3','現今基督，神所膏者，<br/>傳揚主神的旨意：<br/>『你是我子<br/>（在復活裡），<br/>我在今日生了你。<br/>我將列國都賜給你，<br/>使你承受為基業，<br/>你顯王權，手拿鐵杖，<br/>將他們打破摔裂。』<br/>',NULL,11468,11468);
INSERT INTO stanza VALUES('CS2','4','你們君王應當省悟，<br/>審判官該受管教；<br/>當存畏懼事奉我主，<br/>又存戰兢而歡躍。<br/>當以嘴親子，消祂怒，<br/>免得你道中滅亡；<br/>『投靠祂的是有福的，』<br/>讓我們同來歡唱！<br/>',NULL,11469,11469);
INSERT INTO stanza VALUES('CS2','5','哦，讚美神，我們看見<br/>你獨一受膏之子；<br/>從虛妄中我們悔改，<br/>在愛裡親你愛子。<br/>『投靠祂的是有福的』─<br/>非那『遵守律法的；』<br/>只要信靠那復活者，<br/>就必蒙福永無已。<br/>',NULL,11470,11470);
INSERT INTO stanza VALUES('CS3','1','主耶和華，<br/>你的聖名在全地何其美！<br/>但願各民、各族、各方，<br/>宣揚你名寶貝。<br/>從嬰孩，喫奶者口中，<br/>你建立了讚美，<br/>使你仇敵閉口無言，<br/>敵權速速崩潰。<br/>',NULL,11471,11471);
INSERT INTO stanza VALUES('CS3','2','當我夜間觀看諸天，<br/>你指頭的工作─<br/>月亮、星宿暗中放明，<br/>憑你智慧述說。<br/>不禁要說：人算甚麼，<br/>你竟如此顧念？<br/>在你神聖經營裡面，<br/>叫人特蒙恩眷！<br/>',NULL,11472,11472);
INSERT INTO stanza VALUES('CS3','3','哦，主耶穌，你是那人─<br/>神來聯於人類；<br/>你穿上了血肉之體，<br/>取了卑微地位。<br/>如今你得主宰權柄，<br/>榮耀為你冠冕，<br/>你將萬有服你腳下，<br/>藉你『身體』掌權。<br/>',NULL,11473,11473);
INSERT INTO stanza VALUES('CS3','4','你經過了道成肉身、<br/>受死、復活、升天，<br/>主權、元首、<br/>國度、身體，<br/>一一你都成全。<br/>藉著這些神聖工作，<br/>你建立了讚美，<br/>我們的心喜樂滿溢，<br/>讚美惟你是配。<br/>',NULL,11474,11474);
INSERT INTO stanza VALUES('CS3','5','有福之日不久將到，<br/>萬口莫不同唱，<br/>但在地方召會之中，<br/>我們先有豫嘗！<br/>哦，主耶和華，你的名<br/>在全地何其美！<br/>但願各民、各族、各方，<br/>宣揚你名寶貝。<br/>',NULL,11475,11475);
INSERT INTO stanza VALUES('CS4','1','你的怒氣，<br/>不過是轉眼之間；<br/>你的恩典，<br/>乃是一生之久。<br/>一宿雖然有哭泣，<br/>早晨便必歡呼。<br/>',NULL,11476,11476);
INSERT INTO stanza VALUES('CS5','1','你已經將我的哀哭<br/>變為跳舞，<br/>將我的麻衣脫去，<br/>你已經將我的哀哭<br/>變為跳舞，<br/>給我披上了喜樂；<br/>好使我靈來歌頌你，<br/>並不住聲。<br/>哦，主耶和華，<br/>我的神阿，我要稱謝你，<br/>直到永遠！<br/>',NULL,11477,11477);
INSERT INTO stanza VALUES('CS6','1','從我們心的深處，<br/>不斷湧出美辭─<br/>論到我們至高王，<br/>論到祂的所是。<br/>我們舌如快手筆，<br/>篇篇見證待寫─<br/>我們新郎的榮美，<br/>我們所愛所悅。<br/>',NULL,11478,11478);
INSERT INTO stanza VALUES('CS6','2','主耶穌，你的美麗<br/>超過所有世人；<br/>你的良善真無比─<br/>你是人中之人。<br/>從你聖潔的嘴裡，<br/>流出豐盛恩惠；<br/>所以神賜福給你，<br/>賜福直到永遠。<br/>',NULL,11479,11479);
INSERT INTO stanza VALUES('CS6','3','你是大能的勇士，<br/>赫然坐車前往；<br/>大有榮耀和得勝，<br/>所向顯你雄威！<br/>萬民倒在你以下，<br/>誰能阻你前進？<br/>你的箭極其鋒利，<br/>射中撒但之心。<br/>',NULL,11480,11480);
INSERT INTO stanza VALUES('CS6','4','神阿，你坐的寶座，<br/>是永永遠遠的；<br/>你的國度與王權，<br/>是完全正直的。<br/>所以神，就是你神，<br/>用喜樂油膏你，<br/>勝過膏你的同伴─<br/>你是何等的配！<br/>',NULL,11481,11481);
INSERT INTO stanza VALUES('CS6','5','沒藥、沉香和肉桂，<br/>是你衣服香氣；<br/>你的受死與復活，<br/>表明你的功績。<br/>從眾地方召會中，<br/>讚美之聲四起，<br/>讚美再加上讚美，<br/>使你稱心如意。<br/>',NULL,11482,11482);
INSERT INTO stanza VALUES('CS7','1','王后戴俄斐金飾，<br/>站在你右手邊；<br/>有君王女兒，<br/>列在你尊貴婦女間。<br/>榮耀的召會<br/>將與她榮耀王相配，<br/>所有婦女（聖徒們）<br/>，彰顯你的榮美。<br/>',NULL,11483,11483);
INSERT INTO stanza VALUES('CS7','2','女子阿，你當思想，<br/>你當側耳而聽；<br/>不要記念你的民，<br/>和父家的事情。<br/>你的美麗就顯出，<br/>必為王所羨慕；<br/>你當親近敬拜祂，<br/>因祂是你的主。<br/>',NULL,11484,11484);
INSERT INTO stanza VALUES('CS7','3','王女的華貴衣服，<br/>是用金線繡的，<br/>她在王的內宮裡，<br/>實是榮華無比！<br/>神本性一切榮耀，<br/>賜給她為穿戴，<br/>她所有生活行為，<br/>將神發表出來。<br/>',NULL,11485,11485);
INSERT INTO stanza VALUES('CS7','4','她要被引到王前，<br/>身穿刺繡衣服，<br/>潔白美麗細麻衣，<br/>將她義行顯出。<br/>藉聖靈針針刺繡，<br/>基督作到身上，<br/>穿上這榮耀衣服，<br/>得蒙君王稱賞！<br/>',NULL,11486,11486);
INSERT INTO stanza VALUES('CS7','5','當我們見王丰采，<br/>將是何等喜樂！<br/>我們要大聲讚美，<br/>高唱永遠樂歌。<br/>我們在此敬拜王，<br/>也因王后而誇，<br/>在這一切享受中，<br/>榮耀完全歸祂。<br/>',NULL,11487,11487);
INSERT INTO stanza VALUES('CS8','1','主本為大！<br/>在我們神城內，<br/>在祂的聖山上，<br/>理當受大大的讚美！<br/>錫安山座落在北面，<br/>居高華美勝一切，<br/>乃是我們大君的京城，<br/>為全地所喜悅，<br/>乃是我們大君的京城，<br/>為全地所喜悅。<br/>',NULL,11488,11488);
INSERT INTO stanza VALUES('CS9','1','神興起，使仇敵四散，<br/>叫恨祂的人逃跑；<br/>惡人見神面就消滅，<br/>如同蠟被火熔掉。<br/>惟有義人必歡喜，<br/>大聲誇勝永不已，<br/>唱詩歌頌，唱詩歌頌，<br/>唱詩歌頌祂名。<br/>',NULL,11489,11489);
INSERT INTO stanza VALUES('CS9','2','祂坐車行過曠野地，<br/>將缺乏之民帶回，<br/>祂是一切孤兒的父，<br/>也是寡婦的護衛─<br/>乃是在祂聖所裡，<br/>哦，這救恩何希奇！<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11490,11490);
INSERT INTO stanza VALUES('CS9','3','孤獨者在此可安家，<br/>寂寞者尋得住處；<br/>被囚者從捆綁得釋，<br/>並且享受無窮福。<br/>為祂羊群神豫備，<br/>這個住處─何恩惠！<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11491,11491);
INSERT INTO stanza VALUES('CS9','4','現今主以大能誇勝，<br/>發出勝利的捷報，<br/>我們『婦女們』報喜信：<br/>『統兵君王逃跑了！』<br/>不用流汗不勞苦，<br/>我們在家分掠物！<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11492,11492);
INSERT INTO stanza VALUES('CS9','5','看，基督已升上高天，<br/>領著長串的俘虜！<br/>祂將這些作成恩賜，<br/>為著神與人同住。<br/>弟兄姊妹，<br/>我們是那變化了的俘虜！<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11493,11493);
INSERT INTO stanza VALUES('CS9','6','願頌讚歸神到永遠，<br/>祂天天滿載美物；<br/>祂是拯救我們的神，<br/>頌讚之聲當遠佈。<br/>曾在陰間裡漫游，<br/>祂打破仇敵的頭！<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11494,11494);
INSERT INTO stanza VALUES('CS9','7','神阿，我們看見了你，<br/>在你聖所中行走，<br/>你凱旋的隊伍遊行，<br/>作樂的跟隨在後。<br/>看，歌唱的行在前，<br/>讚美一遍又一遍，<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11495,11495);
INSERT INTO stanza VALUES('CS9','8','領先的是小便雅憫，<br/>接著是猶大支隊，<br/>憂患之子在神右邊，<br/>獅子掌權執王圭。<br/>西布倫，拿弗他利，<br/>傳揚大喜的信息：<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11496,11496);
INSERT INTO stanza VALUES('CS9','9','聖民哪，你們的能力，<br/>出自榮耀的聖殿；<br/>神阿，求你剛強我們，<br/>直到我們被成全。<br/>我們要讚美不停，<br/>直到地極都響應：<br/>阿利路亞，阿利路亞，<br/>阿利路亞，阿們！<br/>',NULL,11497,11497);
INSERT INTO stanza VALUES('CS10','1','普天之下當向耶和華<br/>大聲喧嚷歡呼！<br/>應當樂意事奉耶和華，<br/>當來向祂歌頌。<br/>你們當曉得祂是神，<br/>我們乃是祂造的，<br/>也是屬祂的；<br/>我們是祂民，<br/>也是祂草場的羊。<br/>應當稱謝進入祂的門，<br/>讚美進入祂的院。<br/>應當同聲感謝耶和華，<br/>稱頌祂的名。<br/>因祂本為善；<br/>祂的慈愛是存到永遠，<br/>祂的信實向我們<br/>一直到萬代。<br/>',NULL,11498,11498);
INSERT INTO stanza VALUES('CS11','1','主，你若究察<br/>我們的眾罪，<br/>誰還能站得住？<br/>主，你若究察<br/>我們的眾罪，<br/>誰能站得住？<br/>但在你有赦免之恩，<br/>但在你有赦免之恩，<br/>但在你有赦免之恩，<br/>要人敬畏你。<br/>',NULL,11499,11499);
INSERT INTO stanza VALUES('CS12','1','看哪，耶和華僕人，<br/>夜間站在祂的殿中的，<br/>你們當稱頌耶和華！<br/>當稱頌祂名。<br/>你們當向聖所舉手，<br/>稱頌耶和華！<br/>願造天地的耶和華，<br/>從錫安賜福給你。<br/>',NULL,11500,11500);
INSERT INTO stanza VALUES('CS13','1','我要永遠的歌唱<br/>主耶穌的慈愛，<br/>我要唱，我要唱；<br/>何等的慈愛，<br/>我今活在召會之中，<br/>我要歌唱主耶穌的慈愛。<br/>用我口，我要傳揚<br/>祂的信實，祂的信實。<br/>用我口，<br/>我要傳揚祂的信實，<br/>直到世世代代。<br/>我要永遠的歌唱<br/>主耶穌的慈愛，<br/>我要唱，我要唱；<br/>何等的慈愛，<br/>我今活在召會之中，<br/>我要歌唱主耶穌的慈愛。<br/>',NULL,11501,11501);
INSERT INTO stanza VALUES('CS14','1','你們要向主稱頌，<br/>祂的名已被尊崇。<br/>你們要向主稱頌，<br/>祂的名已被尊崇。<br/>因為祂所行的真是美好，<br/>但願這事普傳天下。<br/>你們要向主稱頌，<br/>祂的名已被尊崇。<br/>',NULL,11502,11502);
INSERT INTO stanza VALUES('CS15','1','我要不住讚美稱頌神，<br/>因祂活在我裡，<br/>祂是我的一切，<br/>不斷供應生命。<br/>我要不住讚美稱頌神，<br/>因祂活在我裡，<br/>與我永不分離。<br/>',NULL,11503,11503);
INSERT INTO stanza VALUES('CS15','chorus','今在靈裡我能享受<br/>基督作我的一切<br/>呼求祂名<br/>祂就成了我實際。<br/>敞開你口就能嘗到<br/>主是何等的豐富，<br/>祂是奇妙全備<br/>生命的供應。<br/>',NULL,11504,11504);
INSERT INTO stanza VALUES('CS15','2','現今我因生命樹而活，<br/>其美果餧養我，<br/>其生命剛強我，<br/>我要永遠活著。<br/>現今我因生命樹而活，<br/>我天天取用祂，<br/>祂是我生命糧。<br/>',NULL,11505,11505);
INSERT INTO stanza VALUES('CS15','3','在我裡面有生命水流，<br/>時刻都在湧流，<br/>處處都要流通，<br/>把我全人浸透。<br/>在我裡面有生命水流，<br/>祂是生命泉源，<br/>一直湧到永生。<br/>',NULL,11506,11506);
INSERT INTO stanza VALUES('CS16','1','我們同聲讚美<br/>來將祂頌揚，<br/>我們蒙神恩同住聖山上；<br/>見證祂的作為<br/>無論大或小，<br/>掌權的基督是我們君王。<br/>召會的生活實際又豐富，<br/>罪與世界都日漸的消逝；<br/>我們今跳躍盡情的歡唱，<br/>我們今跳躍盡情的歡唱。<br/>',NULL,11507,11507);
INSERT INTO stanza VALUES('CS16','2','讚祂與神同等<br/>原坐在天上，<br/>竟成為人子為我們受創；<br/>讚祂從死復活<br/>寶座上為王，<br/>復活的豐富我們能盡嘗。<br/>讚祂何豐富充滿了一切，<br/>我們竟成祂豐富的顯彰；<br/>哦，阿利路亞！<br/>豐富的顯彰，<br/>哦，阿利路亞！<br/>豐富的顯彰。<br/>',NULL,11508,11508);
INSERT INTO stanza VALUES('CS16','3','讚祂今是那靈<br/>活在我靈裡，<br/>宗教的儀文我不再憑依；<br/>我可時刻享受，<br/>享受祂自己，<br/>祂一切豐盛都成我經歷。<br/>在地方召會我們齊歡暢，<br/>剛強的靈中將祂來頌揚；<br/>頌揚祂是靈，<br/>在召會作王，<br/>頌揚祂是靈，<br/>在召會中作王。<br/>',NULL,11509,11509);
INSERT INTO stanza VALUES('CS16','4','當祂榮耀自己<br/>充滿在召會，<br/>召會的見證得勝又明亮；<br/>滿得靈中豐富<br/>我們同頌揚，<br/>讓世人都知這萬王之王。<br/>丟棄自己那窄小的天地，<br/>自由的靈引我們到地極；<br/>榮耀歡樂的流出祂自己，<br/>榮耀歡樂的流出祂自己。<br/>',NULL,11510,11510);
INSERT INTO stanza VALUES('CS17','1','樂，樂，樂，<br/>我心充滿喜樂；<br/>樂，樂，樂，<br/>耶穌使我唱歌；<br/>唱祂奇妙大愛為著我，<br/>說祂如何受死釋放我，<br/>使我全人自由且超脫，<br/>我心樂，樂，樂！<br/>',NULL,11511,11511);
INSERT INTO stanza VALUES('CS17','2','主，主，主，<br/>在我靈中流通；<br/>主，主，主，<br/>在我魂中擴充；<br/>將我裡面陳舊全燒盡，<br/>將我全人變化且更新，<br/>使我成熟迎接祂再臨，<br/>是我主，主，主！<br/>',NULL,11512,11512);
INSERT INTO stanza VALUES('CS17','3','讚，讚，讚，<br/>將神心意發表，<br/>讚，讚，讚，<br/>使我靈裡發燒，<br/>讚美滿心滿口滿全人，<br/>將神計畫到處告訴人，<br/>將流蕩者帶回歸向神，<br/>高聲讚，讚，讚！<br/>',NULL,11513,11513);
INSERT INTO stanza VALUES('CS17','4','召會，一地一個出現，<br/>召會，分裂何等可憐，<br/>大巴比倫今正在傾倒，<br/>主在耶路撒冷為至高；<br/>我們站住立場同建造，<br/>地方的召會。<br/>',NULL,11514,11514);
INSERT INTO stanza VALUES('CS17','5','地方召會，<br/>我們已經看見；<br/>地方召會，<br/>我們已在裡面。<br/>光明的城造在聖山上，<br/>基督、召會同得著顯彰；<br/>終於完成了神的願望，<br/>在地方召會！<br/>',NULL,11515,11515);
INSERT INTO stanza VALUES('CS18','1','我有一詩歌我愛唱，<br/>自從我被贖回，<br/>唱我救贖主，救主，王，<br/>自從我被贖回。<br/>',NULL,11516,11516);
INSERT INTO stanza VALUES('CS18','chorus','自從我被贖回，<br/>自從我被贖回，<br/>我要靠主名誇耀；<br/>自從我被贖回，<br/>我要靠救主的名誇耀。<br/>',NULL,11517,11517);
INSERT INTO stanza VALUES('CS18','2','我有一基督能滿足，<br/>自從我被贖回；<br/>行祂旨意是我所慕，<br/>自從我被贖回。<br/>',NULL,11518,11518);
INSERT INTO stanza VALUES('CS18','3','我有一中保神前立，<br/>自從我被贖回，<br/>消除一切憂懼、懷疑，<br/>自從我被贖回。<br/>',NULL,11519,11519);
INSERT INTO stanza VALUES('CS18','4','我有一喜樂說不出，<br/>自從我被贖回，<br/>都因我的義─我的主，<br/>自從我被贖回。<br/>',NULL,11520,11520);
INSERT INTO stanza VALUES('CS18','5','我有一位神我所屬，<br/>自從我被贖回，<br/>與祂我要永遠同住，<br/>自從我被贖回。<br/>',NULL,11521,11521);
INSERT INTO stanza VALUES('CS19','1','我在拿撒勒人耶穌面前<br/>驚異的站立，<br/>希奇，不潔罪人如我，<br/>祂愛竟然能臨及。<br/>',NULL,11522,11522);
INSERT INTO stanza VALUES('CS19','chorus','何等希奇！何等奇妙！<br/>我要歌唱到萬代，<br/>何等希奇！何等奇妙！<br/>是我救主的大愛！<br/>',NULL,11523,11523);
INSERT INTO stanza VALUES('CS19','2','為我祂在園中禱告：<br/>『只要照你的旨意；』<br/>祂無眼淚為己憂傷，<br/>為我流汗如血滴。<br/>',NULL,11524,11524);
INSERT INTO stanza VALUES('CS19','3','天使看見就憐恤祂，<br/>從光明之中顯現；<br/>在那極其傷痛晚上，<br/>使祂力量得加添。<br/>',NULL,11525,11525);
INSERT INTO stanza VALUES('CS19','4','祂除去我罪與我憂，<br/>將其全歸祂自己；<br/>祂負重擔到各各他，<br/>獨自受苦並受死。<br/>',NULL,11526,11526);
INSERT INTO stanza VALUES('CS19','5','當那日與蒙贖的人，<br/>在榮耀裡見祂面，<br/>何等歡樂歌唱祂愛，<br/>一直到千萬億年。<br/>',NULL,11527,11527);
INSERT INTO stanza VALUES('CS20','1','何等權能！耶穌尊名！<br/>天使全都俯伏，<br/>天使全都俯伏，<br/>獻上冠冕，同心尊敬。<br/>',NULL,11528,11528);
INSERT INTO stanza VALUES('CS20','chorus','加冠祂，加冠，加冠，<br/>加冠，加冠祂萬有主！<br/>',NULL,11529,11529);
INSERT INTO stanza VALUES('CS20','2','你們墮落亞當後代，<br/>今成被贖聖徒，<br/>今成被贖聖徒，<br/>靠恩得救，<br/>應當敬拜。<br/>',NULL,11530,11530);
INSERT INTO stanza VALUES('CS20','3','罪人，你心永不可忘，<br/>祂的苦膽、酸醋，<br/>祂的苦膽、酸醋，<br/>今當到祂面前瞻望。<br/>',NULL,11531,11531);
INSERT INTO stanza VALUES('CS20','4','但願地上萬族萬民，<br/>都向救主俯伏。<br/>都向救主俯伏，<br/>榮耀、尊貴都歸祂名。<br/>',NULL,11532,11532);
INSERT INTO stanza VALUES('CS20','5','億萬群眾歌聲雷動，<br/>我也一同歡呼，<br/>我也一同歡呼，<br/>直到永遠敬拜稱頌。<br/>',NULL,11533,11533);
INSERT INTO stanza VALUES('CS21','1','祂是主，祂是主，<br/>祂已從死復活，<br/>如今祂是主！<br/>萬膝莫不屈服，<br/>萬口莫不稱呼，<br/>耶穌基督為主。<br/>',NULL,11534,11534);
INSERT INTO stanza VALUES('CS22','1','我們歌唱要來掌權的王，<br/>榮耀歸耶穌，<br/>被殺的羔羊；<br/>祂的國度帶來公義平安，<br/>喜樂遍全地，<br/>當耶穌為王。<br/>',NULL,11535,11535);
INSERT INTO stanza VALUES('CS22','chorus','同心讚美，大聲歌唱；<br/>耶穌為王，耶穌為王。<br/>這首詩章屬主的人愛唱：<br/>榮耀歸耶穌，<br/>我們的君王。<br/>',NULL,11536,11536);
INSERT INTO stanza VALUES('CS22','2','萬民要住在祂奇妙光中，<br/>萬族要因祂愛<br/>歸於『大同』。<br/>公平與真實出自祂王杖，<br/>不法必終止，<br/>當耶穌為王。<br/>',NULL,11537,11537);
INSERT INTO stanza VALUES('CS22','3','在祂國度裡完全是和睦，<br/>自由必旺盛，<br/>強暴被剪除，<br/>敵化為友，<br/>當祂凱歌同唱；<br/>劍變成鐮刀，<br/>當耶穌為王。<br/>',NULL,11538,11538);
INSERT INTO stanza VALUES('CS22','4','認識神的知識充滿全地，<br/>好像深水般將海洋淹蔽；<br/>地上萬物都必如春發旺，<br/>一切全和諧，<br/>當耶穌為王。<br/>',NULL,11539,11539);
INSERT INTO stanza VALUES('CS22','5','願基督的國度早日來臨，<br/>晨光速露出，<br/>我們同歡欣。<br/>當受造之物新歌同聲唱，<br/>撒但被摧毀而耶穌為王！<br/>',NULL,11540,11540);
INSERT INTO stanza VALUES('CS23','1','這是召會得勝歌聲，<br/>羔羊是配；<br/>天上充滿讚美歡騰，<br/>羔羊是配。<br/>王位政權向祂屈服，<br/>馨香氣味升上高處，<br/>歌唱聲音永不止住，<br/>羔羊是配。<br/>',NULL,11541,11541);
INSERT INTO stanza VALUES('CS23','2','各類各族各國人們，<br/>羔羊是配；<br/>一同歌唱這大救恩，<br/>羔羊是配。<br/>響聲如同大雷轟隆，<br/>又如眾水澎湃激沖。<br/>在祂腳前屈膝歌頌，<br/>羔羊是配。<br/>',NULL,11542,11542);
INSERT INTO stanza VALUES('CS23','3','琴聲歌聲永遠不輟，<br/>羔羊是配；<br/>洪恩比罪更加顯多，<br/>羔羊是配。<br/>藉祂寶血，祂買我們；<br/>離群失落，祂尋我們；<br/>進入榮耀，祂領我們；<br/>羔羊是配。<br/>',NULL,11543,11543);
INSERT INTO stanza VALUES('CS23','4','這是何等有福盼望，<br/>羔羊是配；<br/>雖經試煉仍能歌唱，<br/>羔羊是配。<br/>甘甜超過最甜歌賦，<br/>只有一首詩歌題目，<br/>一直述說仍未說出，<br/>羔羊是配。<br/>',NULL,11544,11544);
INSERT INTO stanza VALUES('CS24','1','恩主，我們阿利路亞<br/>向你高聲唱，<br/>永遠讚美你的價值<br/>超萬人之上。<br/>',NULL,11545,11545);
INSERT INTO stanza VALUES('CS24','chorus','讚美羔羊！你真是配！<br/>永遠的歌聲。<br/>阿利路亞！阿利路亞！<br/>讚美主！阿們！<br/>',NULL,11546,11546);
INSERT INTO stanza VALUES('CS24','2','讚美羔羊！你真是配！<br/>你寶血流出，<br/>贖回我們歸神<br/>作王並祭司國度。<br/>',NULL,11547,11547);
INSERT INTO stanza VALUES('CS24','3','阿利路亞！恩主耶穌，<br/>你愛不止息；<br/>我們屬你，永遠屬你，<br/>與你永合一。<br/>',NULL,11548,11548);
INSERT INTO stanza VALUES('CS24','4','讚美主！哦，阿利路亞！<br/>誰不唱此歌？<br/>來自各族各方各國<br/>眾聖同唱和。<br/>',NULL,11549,11549);
INSERT INTO stanza VALUES('CS25','1','所以你們從救恩泉源<br/>歡然取水，歡然取水。<br/>就在那日，<br/>你們說：讚美主！<br/>所以你們從救恩泉源<br/>歡然取水，歡然取水。<br/>就在那日，<br/>你們說：讚美主！<br/>呼求祂的名，<br/>將祂所行傳揚在萬民中，<br/>題說祂的名已經被尊崇。<br/>揚聲歡呼！<br/>你們錫安的居民哪！<br/>因你們中間的<br/>以色列的聖者為至大！<br/>',NULL,11550,11550);
INSERT INTO stanza VALUES('CS26','1','你們要嘗嘗主恩的滋味，<br/>便知道祂是美善；<br/>主耶穌是信實的，<br/>信靠祂的人有福了。<br/>敬畏祂的一無所缺，<br/>少壯獅子還缺食忍餓；<br/>但尋求主耶穌的人，<br/>甚麼好處都不缺。<br/>',NULL,11551,11551);
INSERT INTO stanza VALUES('CS27','1','在榮耀裡有一人，<br/>祂的生命是為我。<br/>祂是完全聖潔，<br/>自由且超脫，<br/>祂是全智、仁慈，<br/>祂是何溫柔！<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>',NULL,11552,11552);
INSERT INTO stanza VALUES('CS27','2','在榮耀裡有一人，<br/>祂的生命是為我。<br/>在祂全無疾病，<br/>祂毫無軟弱，<br/>祂是剛強、有力，<br/>且能往上浮！<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>',NULL,11553,11553);
INSERT INTO stanza VALUES('CS27','3','在榮耀裡有一人，<br/>祂的生命是為我。<br/>祂勝過了死亡，<br/>拘禁全脫落，<br/>在復活裡作王，<br/>權柄手中握！<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>祂榮耀裡的生命<br/>乃是為著我。<br/>',NULL,11554,11554);
INSERT INTO stanza VALUES('CS27','4','在榮耀裡有一人，<br/>祂的生命是為我。<br/>祂的平安長存，<br/>不怕何風波，<br/>祂喜樂，發光輝，<br/>盼望而等著，<br/>祂榮耀裡的生命<br/>從我裡透過。<br/>祂榮耀裡的生命<br/>從我裡透過。<br/>',NULL,11555,11555);
INSERT INTO stanza VALUES('CS101','1','神，我讚美你，<br/>賜下基督的靈，<br/>祂今來住我裡面，<br/>作我的生命。<br/>阿利路亞，基督的靈！<br/>阿利路亞，內住！<br/>阿利路亞，豐盛生命！<br/>永遠不止住！<br/>',NULL,11556,11556);
INSERT INTO stanza VALUES('CS101','2','在靈裡歌唱，<br/>末後亞當已經<br/>成為賜生命的靈，<br/>與我合為一。<br/>阿利路亞，這是耶穌！<br/>阿利路亞，那靈！<br/>阿利路亞，與祂聯合！<br/>二靈成一靈！<br/>',NULL,11557,11557);
INSERT INTO stanza VALUES('CS101','3','在靈裡重生，<br/>我們今被變化，<br/>模成神兒子形像，<br/>成熟並長大。<br/>阿利路亞，分賜生命！<br/>阿利路亞，變化！<br/>阿利路亞，改變形狀！<br/>模成祂形像！<br/>',NULL,11558,11558);
INSERT INTO stanza VALUES('CS101','4','模成祂形像，<br/>乃藉靈得餧養，<br/>時刻喫喝生命主，<br/>祂供應無量。<br/>阿利路亞，完全救恩！<br/>阿利路亞，屬我！<br/>阿利路亞，彀我應用！<br/>生活何超脫！<br/>',NULL,11559,11559);
INSERT INTO stanza VALUES('CS102','1','看哪，時代已轉移，<br/>隨主轉入聖靈裡，<br/>神寶座前的七靈，<br/>奉差遣到全地去。<br/>',NULL,11560,11560);
INSERT INTO stanza VALUES('CS102','chorus','哦，神七靈，我懇求，<br/>願你工作得成就！<br/>將我鑒察並焚燒，<br/>為著召會的建造，<br/>鑒察，焚燒，<br/>為著召會的建造。<br/>',NULL,11561,11561);
INSERT INTO stanza VALUES('CS102','2','聖靈乃是七倍靈，<br/>應付召會死光景，<br/>聖徒轉回得復甦，<br/>使主召會得恢復。<br/>',NULL,11562,11562);
INSERT INTO stanza VALUES('CS102','3','現今我們神的靈，<br/>成為召會的供應，<br/>而且加強成七倍，<br/>何等豐富又全備！<br/>',NULL,11563,11563);
INSERT INTO stanza VALUES('CS102','4','神的七靈是七燈，<br/>七盞燒著的火燈，<br/>並不是為著教導，<br/>乃是為將我焚燒。<br/>',NULL,11564,11564);
INSERT INTO stanza VALUES('CS102','5','看哪！現在神七靈，<br/>七眼如火焰照明，<br/>潔淨召會每角落，<br/>肉體情慾都脫落。<br/>',NULL,11565,11565);
INSERT INTO stanza VALUES('CS102','6','主今賜下祂七靈，<br/>帶著豐盛的生命，<br/>今在地方召會裡，<br/>供我享受並經歷。<br/>',NULL,11566,11566);
INSERT INTO stanza VALUES('CS103','1','哦主，以審判的靈，<br/>審判我一切惡行！<br/>我不憑自己搜尋，<br/>只等你靈來顯明。<br/>',NULL,11567,11567);
INSERT INTO stanza VALUES('CS103','2','哦主，以焚燒的靈，<br/>燒去我所有污穢；<br/>把世界一燒而空，<br/>直到我爆炸發瘋。<br/>',NULL,11568,11568);
INSERT INTO stanza VALUES('CS103','3','哦主，以智慧的靈，<br/>啟示你一切奧祕；<br/>你是根、枝子、果實，<br/>你是內容和豐富。<br/>',NULL,11569,11569);
INSERT INTO stanza VALUES('CS103','4','哦主，以謀略的靈，<br/>顯出你奇妙帶領；<br/>新舊辦法都無用，<br/>有靈能力纔成功。<br/>',NULL,11570,11570);
INSERT INTO stanza VALUES('CS103','5','哦主，以知識的靈，<br/>非憑眼見或耳聞；<br/>使我明白你心意，<br/>戰兢活出你救恩。<br/>',NULL,11571,11571);
INSERT INTO stanza VALUES('CS103','6','哦主，以公正的靈，<br/>帶我學習走正路；<br/>不因人情而退卻，<br/>不因艱難而變節。<br/>',NULL,11572,11572);
INSERT INTO stanza VALUES('CS103','7','主，去我沉睡的靈，<br/>開我眼使我儆醒；<br/>你來的日子近了，<br/>讓我隨時準備好。<br/>',NULL,11573,11573);
INSERT INTO stanza VALUES('CS104','1','我主基督是賜生命的靈，<br/>賜生命的靈，<br/>賜生命的靈。<br/>我主基督是賜生命的靈，<br/>祂活在我裡面。<br/>祂活！祂活！<br/>祂在裡面成形！<br/>我活！我活！<br/>我將祂來彰顯！<br/>阿利路亞！<br/>我主基督是賜生命的靈，<br/>賜生命的靈，<br/>賜生命的靈。<br/>我主基督是賜生命的靈，<br/>祂活在我裡面。<br/>',NULL,11574,11574);
INSERT INTO stanza VALUES('CS105','1','基督是那賜生命的靈，<br/>進入我靈賜我生命；<br/>基督是那賜生命的靈，<br/>在我靈裡引導供應。<br/>',NULL,11575,11575);
INSERT INTO stanza VALUES('CS105','chorus','哦，主！阿們！<br/>哦，主！阿們！<br/>阿利路亞！<br/>哦，主！阿們！<br/>哦，主！阿們！<br/>阿利路亞！<br/>',NULL,11576,11576);
INSERT INTO stanza VALUES('CS105','2','如今主基督就是那靈，<br/>主靈，我靈聯成一靈；<br/>如今主基督就是那靈，<br/>將我變化成主榮形。<br/>',NULL,11577,11577);
INSERT INTO stanza VALUES('CS106','1','我愛我的主耶穌，<br/>祂是賜生命的靈；<br/>我已與祂合為一，<br/>二靈成為一靈！<br/>',NULL,11578,11578);
INSERT INTO stanza VALUES('CS107','1','人人都應該知道，<br/>人人都應該知道，<br/>人人都應該知道，<br/>主住那裡？<br/>祂是住在我們靈裡，<br/>作我們生命、氣息；<br/>我們與祂聯合為一，<br/>這是何等的奧祕！<br/>',NULL,11579,11579);
INSERT INTO stanza VALUES('CS107','2','人人都應該知道，<br/>人人都應該知道，<br/>人人都應該知道，<br/>活的基督。<br/>基督是賜生命的靈，<br/>包含神一切豐富；<br/>取之不竭，用之不盡，<br/>只要呼喊主耶穌。<br/>',NULL,11580,11580);
INSERT INTO stanza VALUES('CS108','1','如今三一神<br/>已住在我裡面，<br/>祂是奇妙之靈在我裡。<br/>我已與主調和<br/>聯成為一靈，<br/>祂是生命之靈在我裡。<br/>',NULL,11581,11581);
INSERT INTO stanza VALUES('CS108','chorus','哦，祂是<br/>奇妙之靈住我裡，<br/>祂是奇妙之靈住我裡。<br/>如今神在子裡，<br/>子就是那靈─<br/>祂是奇妙之靈住我裡。<br/>',NULL,11582,11582);
INSERT INTO stanza VALUES('CS108','2','『阿爸父』我今<br/>從深處呼喊你，<br/>喊自奇妙之靈在我裡；<br/>也就是子之靈<br/>向父神呼喊，<br/>祂是生命之靈在我裡。<br/>',NULL,11583,11583);
INSERT INTO stanza VALUES('CS108','3','如今主耶穌基督<br/>住在我裡，<br/>祂是奇妙之靈住我裡；<br/>祂已經過變化，<br/>我可享受祂，<br/>祂是生命之靈住我裡。<br/>',NULL,11584,11584);
INSERT INTO stanza VALUES('CS108','4','如今那實際之靈<br/>已經來到，<br/>祂是奇妙之靈住我裡；<br/>今基督的一切，<br/>明亮又實際，<br/>藉著生命之靈住我裡。<br/>',NULL,11585,11585);
INSERT INTO stanza VALUES('CS108','5','我願常挑旺<br/>這深處的恩賜，<br/>這是奇妙之靈住我裡；<br/>喊『哦！主耶穌，』<br/>這使我靈跳躍，<br/>因著生命之靈在我裡。<br/>',NULL,11586,11586);
INSERT INTO stanza VALUES('CS109','1','膏油在此！<br/>主在我們裡面運行，<br/>寶貝膏油一直塗抹不停。<br/>寶血有能！<br/>牠為我們帶進交通，<br/>如今我們活在生命流中。<br/>',NULL,11587,11587);
INSERT INTO stanza VALUES('CS109','chorus','（姊妹)<br/>膏油在此！<br/>哦，弟兄們哪！<br/>膏油在此我們相信！<br/>我們已從主得著這膏油，<br/>聖靈在靈裡面運行！<br/>（弟兄）<br/>膏油在此！<br/>哦，姊妹們哪！<br/>膏油塗抹永遠不停，<br/>藉祂的塗抹住在祂裡面，<br/>哦，阿利路亞，何豐盛！<br/>',NULL,11588,11588);
INSERT INTO stanza VALUES('CS109','2','膏油在此！<br/>是神自己與人調和，<br/>如今二者相調成為一個！<br/>時時刻刻，<br/>我們生活、動作、存留<br/>都在乎祂─<br/>神在我們裡頭。<br/>',NULL,11589,11589);
INSERT INTO stanza VALUES('CS109','3','膏油在此！<br/>膏油教導我們一切，<br/>我們經常有這生命感覺；<br/>順這感覺，<br/>我們知道如何行事，<br/>憑祂而活，<br/>凡事無不清楚。<br/>',NULL,11590,11590);
INSERT INTO stanza VALUES('CS110','1','在神話裡我看見，<br/>膏油已住在我裡面！<br/>不需人為的教訓，<br/>膏油自然有引領！<br/>',NULL,11591,11591);
INSERT INTO stanza VALUES('CS110','chorus','哦！在我的靈裡<br/>祂是在運行！<br/>膏油塗抹常引領，<br/>神在我裡湧流！<br/>哦，感謝讚美主，<br/>祂話已說出，<br/>我要不斷的順服，<br/>靠膏油塗抹而活。<br/>',NULL,11592,11592);
INSERT INTO stanza VALUES('CS110','2','為要將基督經歷，<br/>藉取用純淨話語；<br/>主靈與我聯為一，<br/>永遠不會再離去！<br/>',NULL,11593,11593);
INSERT INTO stanza VALUES('CS110','3','先有寶血的潔淨，<br/>沒有間隔沒距離；<br/>接著膏油來塗抹，<br/>使我得著神自己。<br/>',NULL,11594,11594);
INSERT INTO stanza VALUES('CS110','4','基督是生命的靈，<br/>進入我的靈裡頭；<br/>神，那聖者塗抹我，<br/>直到神人全調和。<br/>',NULL,11595,11595);
INSERT INTO stanza VALUES('CS110','5','神是靈，我可摸著；<br/>祂是在我靈裡流；<br/>更深、更廣、更豐盛；<br/>膏油叫我認識神！<br/>',NULL,11596,11596);
INSERT INTO stanza VALUES('CS110','6','按照膏油的教導，<br/>經常住在主裡面；<br/>祂邊教導邊展伸，<br/>直到佔有我全人。<br/>',NULL,11597,11597);
INSERT INTO stanza VALUES('CS111','1','你找著你的靈沒有？<br/>靈與口原分不開！<br/>『哦主，阿們，<br/>阿利路亞，』<br/>你的靈就能出來！<br/>',NULL,11598,11598);
INSERT INTO stanza VALUES('CS111','chorus','從聖靈生的<br/>乃是我們的靈，<br/>這工作已經完成；<br/>從聖靈生的<br/>乃是我們的靈，<br/>二靈相調成一靈。<br/>',NULL,11599,11599);
INSERT INTO stanza VALUES('CS111','2','不要苦等所謂『感動，』<br/>不要上撒但的當；<br/>要開口釋放你的靈，<br/>見證你得了釋放。<br/>',NULL,11600,11600);
INSERT INTO stanza VALUES('CS112','1','轉入靈裡，<br/>轉入實際靈裡！<br/>轉入靈裡，<br/>轉入實際靈裡！<br/>從外面字句、道理，<br/>轉入靈裡；<br/>哦，轉入、轉入，<br/>要轉入靈裡！<br/>轉罷，弟兄！<br/>轉罷，姊妹！<br/>實際是在靈裡！<br/>（榮耀，阿利路亞！）<br/>轉入實際靈裡，<br/>直到轉得徹底；<br/>轉罷，隨靈轉罷！<br/>',NULL,11601,11601);
INSERT INTO stanza VALUES('CS112','2','隨主往前，<br/>靈裡隨主往前！<br/>隨主往前，<br/>靈裡隨主往前！<br/>看！時代已經轉了，<br/>主已往前！<br/>哦，往前、往前，<br/>要隨主往前！<br/>往前，弟兄！<br/>往前，姊妹！<br/>靈裡隨主往前！<br/>（榮耀，阿利路亞！）<br/>靈裡一直往前，<br/>直到榮耀顯現！<br/>往前，一直往前！<br/>',NULL,11602,11602);
INSERT INTO stanza VALUES('CS113','1','回到你靈裡，<br/>在靈中與主相通！<br/>回到你靈裡，<br/>得著生命供應；<br/>回到你靈裡，<br/>時刻來呼喊主名！<br/>回到你靈裡，活在靈中。<br/>',NULL,11603,11603);
INSERT INTO stanza VALUES('CS113','2','回到你靈裡，<br/>在靈中與主相通！<br/>回到你靈裡，<br/>這會使你歌唱；<br/>回到你靈裡，<br/>正當事情在繁忙；<br/>回到你靈裡，活在靈中。<br/>',NULL,11604,11604);
INSERT INTO stanza VALUES('CS113','3','回到你靈裡，<br/>在靈中與主相通！<br/>回到你靈裡，<br/>不管下沉、高昂；<br/>今日到永遠，<br/>主對你總是一樣！<br/>回到你靈裡，活在靈中。<br/>',NULL,11605,11605);
INSERT INTO stanza VALUES('CS114','1','我們已得著釋放，<br/>讚美主！（讚美主）<br/>我們已得著釋放，<br/>讚美主！（讚美主）<br/>脫離了老舊宗教，<br/>脫離了死的規條，<br/>我們已得著釋放，<br/>讚美主！（讚美主）<br/>',NULL,11606,11606);
INSERT INTO stanza VALUES('CS114','2','我們已得著釋放，<br/>在靈裡！（在靈裡）<br/>我們已得著釋放，<br/>在靈裡！（在靈裡）<br/>享受了生命自由，<br/>享受了完全拯救，<br/>我們已得著釋放，<br/>在靈裡！（在靈裡）<br/>',NULL,11607,11607);
INSERT INTO stanza VALUES('CS115','1','飽嘗我基督在靈裡，<br/>喫喝祂，享受祂，<br/>甜無比！<br/>祂豐富都成為我實際，<br/>安息又飽足不止息。<br/>在靈裡，在靈裡，<br/>飽嘗我基督在靈裡；<br/>在靈裡，在靈裡，<br/>在靈裡，<br/>享受主基督，在靈裡！<br/>',NULL,11608,11608);
INSERT INTO stanza VALUES('CS116','1','我們要在靈裡向主歌唱，<br/>我們要從裡面向主唱，<br/>我們要阿利路亞向主唱，<br/>我們相調為一向主唱！<br/>',NULL,11609,11609);
INSERT INTO stanza VALUES('CS116','2','我們曾多年在宗教裡面，<br/>我們曾多年在心思裡，<br/>我們曾多年在情感裡面，<br/>一直追求卻在黑暗裡。<br/>',NULL,11610,11610);
INSERT INTO stanza VALUES('CS116','3','今我們操練靈裡接觸主<br/>今我們操練取用基督，<br/>今我們操練喫喝主耶穌，<br/>脫離掙扎奮鬥的痛苦。<br/>',NULL,11611,11611);
INSERT INTO stanza VALUES('CS116','4','阿利路亞！<br/>聖靈裡的生命，<br/>阿利路亞！<br/>裡面的新樣。<br/>當我們從心思中轉入靈，<br/>祂一切豐富我們全享。<br/>',NULL,11612,11612);
INSERT INTO stanza VALUES('CS117','1','我們已定意在靈裡行事，<br/>我們已定意在靈裡行事，<br/>我們已定意在靈裡行事，<br/>在靈裡，阿利路亞！<br/>',NULL,11613,11613);
INSERT INTO stanza VALUES('CS117','2','在靈裡行事，<br/>喊『哦，主耶穌！』<br/>在靈裡行事，<br/>喊『哦，主耶穌！』<br/>在靈裡行事，<br/>喊『哦，主耶穌！』<br/>祂何豐富，阿利路亞！<br/>',NULL,11614,11614);
INSERT INTO stanza VALUES('CS117','3','要跟隨耶穌，<br/>就需要『身體，』<br/>要跟隨耶穌，<br/>就需要『身體，』<br/>要跟隨耶穌，<br/>就需要『身體，』<br/>何等實際，阿利路亞！<br/>',NULL,11615,11615);
INSERT INTO stanza VALUES('CS117','4','建造在一起，<br/>其樂真無比，<br/>建造在一起，<br/>其樂真無比，<br/>建造在一起，<br/>其樂真無比，<br/>何等榮耀，地方召會！<br/>',NULL,11616,11616);
INSERT INTO stanza VALUES('CS117','5','神正在恢復召會的生活，<br/>神正在恢復召會的生活，<br/>神正在恢復召會的生活，<br/>我們在內，阿利路亞！<br/>',NULL,11617,11617);
INSERT INTO stanza VALUES('CS118','1','哦我神，在你裡，<br/>有永遠的生命，<br/>這生命在子裡得顯明。<br/>如今主復活裡<br/>已成為生命靈，<br/>在我裡點活我，賜生命。<br/>',NULL,11618,11618);
INSERT INTO stanza VALUES('CS118','2','哦看哪！<br/>從神和羔羊的寶座間，<br/>已流出這一道生命河；<br/>神乃是生命源，<br/>主乃是生命泉，<br/>三一神湧流成生命河。<br/>',NULL,11619,11619);
INSERT INTO stanza VALUES('CS118','3','主耶穌，主耶穌，<br/>我向你敞開靈，<br/>從深處呼你名將你飲；<br/>主耶穌，主耶穌，<br/>向這河我全傾，<br/>三一神漫全人作生命。<br/>',NULL,11620,11620);
INSERT INTO stanza VALUES('CS119','1','主是賜生命者，<br/>賜我生命；<br/>當每一次我呼喊祂，<br/>祂就釋放我靈。<br/>主是賜生命者，<br/>住在我裡；<br/>祂不僅是一個名字，<br/>乃是我的實際。<br/>',NULL,11621,11621);
INSERT INTO stanza VALUES('CS120','1','前遠離神死在罪中，<br/>黑暗蒙蔽心眼；<br/>今蒙主話照明得知，<br/>主活在我裡面。<br/>',NULL,11622,11622);
INSERT INTO stanza VALUES('CS120','chorus','主活我裡面，<br/>主活我裡面，<br/>哦，這是何等救恩，<br/>主竟活我裡面。<br/>',NULL,11623,11623);
INSERT INTO stanza VALUES('CS120','2','如同陽光照射大地，<br/>百花盛開爭艷；<br/>生命，光，愛從主而來，<br/>祂活在我裡面。<br/>',NULL,11624,11624);
INSERT INTO stanza VALUES('CS120','3','正如花朵隱於花籽，<br/>樹木孕於種子，<br/>同樣，滿帶實際、恩典，<br/>主活在我裡面。<br/>',NULL,11625,11625);
INSERT INTO stanza VALUES('CS120','4','我心不禁羨慕像祂，<br/>完全將祂彰顯；<br/>我被吸引不斷思量，<br/>主活在我裡面。<br/>',NULL,11626,11626);
INSERT INTO stanza VALUES('CS121','1','耶穌是我主，<br/>祂活在我裡；<br/>現今我真是快樂無比。<br/>哦，阿利路亞！<br/>哦，阿利路亞！<br/>祂活在我裡！<br/>',NULL,11627,11627);
INSERT INTO stanza VALUES('CS121','2','世界盡都是充滿了空虛，<br/>基督纔是惟一的實際。<br/>哦，阿利路亞！<br/>哦，阿利路亞！<br/>祂活在我裡！<br/>',NULL,11628,11628);
INSERT INTO stanza VALUES('CS122','1','我們看見基督是實際，<br/>但是不能只看見而已，<br/>祂在我們所有的經歷，<br/>必須是一切。<br/>禱告之時瞻仰祂榮面，<br/>讀經聚會認識祂恩典，<br/>但在日常生活的細節，<br/>祂是否一切？阿利路亞！<br/>在光中看見，<br/>主是何等真實又完全，<br/>只要我們在每一時間，<br/>在每一天，<br/>並在每一事件，<br/>隨處多方回到祂前─經歷祂的實際須具體！<br/>不再籠統，摸不著邊際！<br/>只要應用祂就必經歷─<br/>祂乃是一切！<br/>',NULL,11629,11629);
INSERT INTO stanza VALUES('CS122','2','我們一生充滿了機會，<br/>父所安排，為顯祂智慧。<br/>一切遭遇是最好最美，<br/>使我得基督─<br/>祂是內容，祂也是實際，<br/>我們將祂來照耀不已，<br/>你我身上祂必須有路，<br/>祂必須有路。<br/>阿利路亞！我們的身體，<br/>常帶著主的被置死地，<br/>祂的生命得顯明無比。<br/>外面的人雖然漸漸毀壞，<br/>裡面的人卻新起來─<br/>周圍的人就都能看見，<br/>寶貝實際在瓦器裡面，<br/>福音榮光全得著彰顯─<br/>是藉著我們。<br/>不是道理也不是神學，<br/>乃是實際內容毫不缺，<br/>基督作了我的一切，<br/>祂乃是一切！<br/>',NULL,11630,11630);
INSERT INTO stanza VALUES('CS123','1','阿利路亞！阿利路亞！<br/>耶穌如今活在我的裡面。<br/>阿利路亞！阿利路亞！<br/>耶穌活在我裡面。<br/>?<br/>附註：『活在』可改唱為<br/>『運行、』『成長、』<br/>『成形、』『塗抹、』<br/>『啟示、』『安家』<br/>等等。<br/>',NULL,11631,11631);
INSERT INTO stanza VALUES('CS124','1','是生命，生命<br/>使我們高聲喊，<br/>阿利路亞！讚美主！<br/>是生命，生命，<br/>使我們高聲喊，<br/>阿利路亞！讚美主！<br/>我們心中充滿喜樂，<br/>主在我們裡面活著，<br/>主在我們裡面活著！<br/>',NULL,11632,11632);
INSERT INTO stanza VALUES('CS125','1','主是生命種子，<br/>已經撒在我們心裡，<br/>祂要發苗漸漸長大，<br/>長成祂的身量。<br/>祂不需要規條，儀文，<br/>只需活水澆灌；<br/>藉此，包羅萬有生命<br/>就要逐漸成長。<br/>何等奇妙的種子，<br/>就是耶穌我主，<br/>祂撒在我的裡面，<br/>長大並達到成熟。<br/>',NULL,11633,11633);
INSERT INTO stanza VALUES('CS125','2','我們許多個別麥粒<br/>不能沾沾自喜，<br/>所有麥粒必須<br/>一起接受搗碎磨細；<br/>直到麥子磨成細麵<br/>並作成一個餅，<br/>所有聖徒相調為一，<br/>模成主的身體。<br/>我們都須被磨細，<br/>直到失去自己，<br/>所有個別麥粒<br/>都模成祂一個身體。<br/>',NULL,11634,11634);
INSERT INTO stanza VALUES('CS125','3','種子已種，麥子長成，<br/>細麵是那成品，<br/>我們乃是神的田地<br/>在合一裡長進。<br/>所有生命的長大<br/>是為著建造召會，<br/>讓神和人得一居所<br/>不再無家可歸。<br/>生命是為著建造，<br/>神與人可安息，<br/>在此神與祂子民<br/>大家都和睦同居。<br/>',NULL,11635,11635);
INSERT INTO stanza VALUES('CS125','4','神的建造乃在於<br/>精金、寶石和銀子，<br/>為著變化，<br/>細麵需經多少壓榨苦楚！<br/>麥子不能停在細麵階段<br/>自滿自足，<br/>必須經過生命變化<br/>成為金銀寶石。<br/>細麵須經歷痛苦，<br/>纔能變成寶石；<br/>然後建造在一起，<br/>完全達到祂旨意。<br/>',NULL,11636,11636);
INSERT INTO stanza VALUES('CS125','5','生命變化完全成熟，<br/>結出一顆珍珠，<br/>簡單、珍貴、包羅萬有、<br/>且是滿有價值。<br/>榮耀之主死而復活，<br/>經過生產之苦，<br/>終於得著召會─新婦，<br/>叫祂心滿意足。<br/>珍珠是祂心所要，<br/>新婦是祂所悅；<br/>這是祂心愛配偶，<br/>單純淨、又寶貝。<br/>',NULL,11637,11637);
INSERT INTO stanza VALUES('CS125','6','願主保守我們靈裡貧窮，<br/>清心向主；<br/>使我們作好土，<br/>生命種子長大，豐富。<br/>直到目標達到，<br/>同被建造，你能滿足，<br/>得著無價至寶─珍珠，<br/>就是你的新婦。<br/>主，倒空我們的靈，<br/>使我們心純淨，<br/>叫我們生命成熟<br/>成為你心愛新婦。<br/>',NULL,11638,11638);
INSERT INTO stanza VALUES('CS126','1','生命的種子撒我裡，<br/>我要讓祂長大；<br/>生命的種子撒我裡，<br/>我要讓祂長大，祂長大，<br/>祂長大，祂長大！<br/>',NULL,11639,11639);
INSERT INTO stanza VALUES('CS126','2','不讓魂生命擠住祂，<br/>我要讓祂長大；…<br/>',NULL,11640,11640);
INSERT INTO stanza VALUES('CS126','3','藉著禱讀來澆灌祂，…<br/>',NULL,11641,11641);
INSERT INTO stanza VALUES('CS126','4','天天呼喊<br/>『哦，主耶穌，』…<br/>',NULL,11642,11642);
INSERT INTO stanza VALUES('CS126','5','同眾聖徒一起交通，…<br/>',NULL,11643,11643);
INSERT INTO stanza VALUES('CS126','6','要站起來為神說話，…<br/>',NULL,11644,11644);
INSERT INTO stanza VALUES('CS126','7','當主說話我就阿們，…<br/>',NULL,11645,11645);
INSERT INTO stanza VALUES('CS126','8','與眾聖徒一起長大，…<br/>',NULL,11646,11646);
INSERT INTO stanza VALUES('CS126','9','直到長成基督身量，…<br/>',NULL,11647,11647);
INSERT INTO stanza VALUES('CS126','10','直到國度完全實現，…<br/>',NULL,11648,11648);
INSERT INTO stanza VALUES('CS127','1','主，給我們看見你心意，<br/>在於你的國度。<br/>不需我們愚昧的努力，<br/>卻需你的恩典。<br/>不必等候那日顯明，<br/>你把我們已遷國裡；<br/>只要讓你在裡面長大，<br/>國度就得彰顯。<br/>',NULL,11649,11649);
INSERT INTO stanza VALUES('CS127','2','神的國度是基督擴展：<br/>種子已撒我裡；<br/>耶穌就是那生命種子─<br/>生長須加留意。<br/>石頭地乃是魂生命，<br/>荊棘是思慮和財富；<br/>我們不能作路旁硬地，<br/>願祂落在好土。<br/>',NULL,11650,11650);
INSERT INTO stanza VALUES('CS127','3','在好土裡麥苗快生長，<br/>果實麥子結出；<br/>然而麥子須成為細麵，<br/>好作神人食物。<br/>若要成就神這心意，<br/>就得接受一切磨煉，<br/>成為一個聖潔的素祭，<br/>主裡緊緊相聯。<br/>',NULL,11651,11651);
INSERT INTO stanza VALUES('CS127','4','從磨煉中變化成活石，<br/>個個為著建造！<br/>在聖靈裡變質而長成─<br/>金銀、寶石、珍珠。<br/>我們接受主作人位，<br/>佔有我們全人生活；<br/>藉此生命長大而變化，<br/>國度就能顯現。<br/>',NULL,11652,11652);
INSERT INTO stanza VALUES('CS127','5','珍珠性質純潔又完美，<br/>達到最高境界；<br/>雖然經歷百般的痛苦，<br/>生命卻更長成。<br/>主作我們生命、人位─<br/>國度原是主的自己；<br/>祂在裡面不斷的增長，<br/>直到神人合一。<br/>',NULL,11653,11653);
INSERT INTO stanza VALUES('CS128','1','國度就是基督作生命，<br/>滿帶著豐富在我裡，<br/>復活裡成長運行不息，<br/>基督能成為我新人。<br/>哦，願你無限豐富，<br/>成我的供應能力，<br/>使我得天天享受你的，<br/>享受你的，<br/>享受你的一切的豐富。<br/>哦，願你榮耀權能，<br/>在我裡運行不息，<br/>好叫我天天變化成長，<br/>變化成長，變化成長，<br/>長成你形像。<br/>願我有國度的實際，<br/>有召會生活的經歷，<br/>與眾聖徒<br/>同被建造在一起。<br/>哦，願你國度權柄<br/>使我住屬天境地，<br/>你能彀天天自由運行，<br/>自由運行，自由運行，<br/>我住榮耀裡。<br/>',NULL,11654,11654);
INSERT INTO stanza VALUES('CS129','1','耶穌我太陽，<br/>惟一的太陽，<br/>照亮我路途，燦爛明亮；<br/>不管是陰霾抑或是天晴，<br/>耶穌，耶穌，<br/>我惟一太陽。<br/>',NULL,11655,11655);
INSERT INTO stanza VALUES('CS129','2','耶穌我生命，<br/>美妙的生命，<br/>與我永聯結，扶持供應；<br/>昨日今日到永遠是一樣，<br/>耶穌，耶穌，<br/>我惟一生命。<br/>',NULL,11656,11656);
INSERT INTO stanza VALUES('CS130','1','主耶穌，作了我人位；<br/>主耶穌，作了我人位。<br/>哦，我接受<br/>基督作我人位。<br/>基督安家在我心裡，<br/>神的豐滿充滿了我。<br/>哦，我接受<br/>基督作我人位。<br/>',NULL,11657,11657);
INSERT INTO stanza VALUES('CS131','1','我的舊人已經被廢除，<br/>在十架上已與主同死；<br/>現在他再無任何用處，<br/>對我他已故。<br/>我的新人在我靈裡住，<br/>在我裡面如活井湧出，<br/>以祂豐盛生命<br/>來充滿我的每一部。<br/>基督在我靈裡作人位，<br/>我心天天向祂不別歸，<br/>好讓裡面的人有個家：<br/>一個地方可以安息，<br/>一個地方成為祂的─<br/>那裡是我完全的實際，<br/>將祂所是向我全開啟，<br/>豐豐富富居住我心裡，<br/>作我真人位。<br/>',NULL,11658,11658);
INSERT INTO stanza VALUES('CS131','2','藉這人位成形在我裡，<br/>我成祂身上的一肢體，<br/>所有行動都不再單獨，<br/>全在配搭裡。<br/>基督必須是我們人位，<br/>我們天然個性須拆毀，<br/>天天拆毀直到拆乾淨，<br/>基督作一切！<br/>惟有基督是我們人位，<br/>再無自己的願望目的，<br/>直到召會是基督自己，<br/>建造成為一個新人，<br/>實現神的永遠旨意─<br/>神人完完全全的調和，<br/>得到一個合式的居所，<br/>建立起祂國度的權柄，<br/>在這全地上。<br/>不是單單基督的自己，<br/>還有召會同配合為一，<br/>取用基督自己作一切，<br/>成一個新人。<br/>',NULL,11659,11659);
INSERT INTO stanza VALUES('CS132','1','何等得勝，何等誇勝，<br/>神自己來成為人！<br/>親自穿上人的性情，<br/>叫神的計畫成全；<br/>藉著十架敗壞魔鬼，<br/>以『人子』復活升天！<br/>',NULL,11660,11660);
INSERT INTO stanza VALUES('CS132','2','耶穌憑著人的美德，<br/>逮捕了那詭詐者；<br/>以『人』身分抵擋試探，<br/>所有考驗全通過！<br/>如今我在靈的裡頭，<br/>擁有祂一切美德。<br/>',NULL,11661,11661);
INSERT INTO stanza VALUES('CS132','3','祂作人的勻細生命，<br/>乃是在耶穌靈裡，<br/>人的美德已經『子化』，<br/>與神的靈調為一。<br/>如今這靈豐富無比，<br/>足供我全人所需。<br/>',NULL,11662,11662);
INSERT INTO stanza VALUES('CS132','4','何等奧祕，卻極真實，<br/>人子在我裡面住！<br/>祂正伸展到我全人，<br/>要從我裡面活出。<br/>阿利路亞，阿利路亞，<br/>我要讚美永不止。<br/>',NULL,11663,11663);
INSERT INTO stanza VALUES('CS132','5','何等奇妙，何等榮耀，<br/>神是在肉身顯現！<br/>我們乃是祂的肢體，<br/>為將祂人性彰顯。<br/>我們現在憑祂而活，<br/>讓神居所早得建。<br/>',NULL,11664,11664);
INSERT INTO stanza VALUES('CS133','1','看哪！時代已經轉移，<br/>爭戰已經開始！<br/>那背叛者撒但一夥，<br/>現在傾巢而出。<br/>所以聖徒必須<br/>具備耶穌完美人性，<br/>為著彰顯神的形像，<br/>執行神的權柄。<br/>',NULL,11665,11665);
INSERT INTO stanza VALUES('CS133','chorus','讓我們憑著<br/>耶穌的人性而站住，<br/>洋溢出人性美德，<br/>成為中流砥柱。<br/>在這世代，罪惡猖獗，<br/>彎曲敗壞，悖逆剛硬，<br/>召會必須強烈見證<br/>耶穌完美人性！<br/>',NULL,11666,11666);
INSERT INTO stanza VALUES('CS133','2','看哪！撒但來到地上，<br/>破壞人類生命；<br/>但神從中興起一人，<br/>祂的價值無比！<br/>從這一個女人後裔，<br/>神來成為肉身，<br/>這人耶穌─末後亞當─<br/>摧毀撒但詭計。<br/>',NULL,11667,11667);
INSERT INTO stanza VALUES('CS133','3','觸目驚心，全地污染，<br/>罪中滾向下坡；<br/>每況愈下，幾無藥救，<br/>人性何其墮落！<br/>我們卻是天國子民，<br/>顯為世上的鹽，<br/>在這不法世代裡面，<br/>蒙祂人性保全。<br/>',NULL,11668,11668);
INSERT INTO stanza VALUES('CS133','4','今日惟有藉著喫喝，<br/>主名不斷呼喊；<br/>享受祂的人性所有，<br/>天天踐踏撒但。<br/>哦，讓我們回轉向主，<br/>棄絕魂的生命；<br/>毀壞撒但所有計謀，<br/>供應新人生命。<br/>',NULL,11669,11669);
INSERT INTO stanza VALUES('CS134','1','神子耶穌為我離寶座，<br/>降世為人，歷盡憂苦；<br/>捨了自己，流血救贖我，<br/>從死復活，化身那靈，<br/>作我拯救主。<br/>',NULL,11670,11670);
INSERT INTO stanza VALUES('CS134','chorus','永活救主，<br/>是我榮耀盼望，<br/>點活我靈，聖化我情；<br/>安家我心房，<br/>使我有力量，<br/>同眾聖享主大愛，<br/>神豐滿顯明。<br/>',NULL,11671,11671);
INSERT INTO stanza VALUES('CS134','2','在主裡面我獲得新生，<br/>舊事已過，全都更新；<br/>愛中生活，新造何光明；<br/>生機拯救來自那靈，<br/>救恩何豐盛。<br/>',NULL,11672,11672);
INSERT INTO stanza VALUES('CS134','3','主，我愛你，<br/>願跟隨你行，<br/>奔跑賽程，討你歡心；<br/>使我忠誠，緊聯於你靈，<br/>直到路終，完全得勝，<br/>與你永相親。<br/>',NULL,11673,11673);
INSERT INTO stanza VALUES('CS135','1','真葡萄樹，<br/>生命何等豐美，<br/>繁生枝子無數，<br/>結出果實纍纍；<br/>主，你是樹，<br/>我們是你枝子，<br/>愛中互相內住，<br/>生命湧流不止；<br/>生機結聯，<br/>彼此合一無間，<br/>享受父神栽培、照護，<br/>生命充滿，<br/>不斷洋溢、擴展，<br/>彰顯父神一切豐富。<br/>',NULL,11674,11674);
INSERT INTO stanza VALUES('CS136','1','在我靈中，<br/>祂的生命在流通，<br/>流通不停，<br/>光照、運行又感動，<br/>使我潔淨，<br/>享受神聖的供應，<br/>我得復興<br/>在祂生命滋潤中；<br/>滋潤我，滋潤我，<br/>祂的生命時時滋潤我，<br/>使我靈中新又活，<br/>得著基督多又多，<br/>何等甘甜，<br/>祂以生命滋潤我。<br/>',NULL,11675,11675);
INSERT INTO stanza VALUES('CS136','2','在我魂間，<br/>祂的生命在溢漫，<br/>不斷擴展，<br/>帶來生命和平安，<br/>進入我心，<br/>祂要浸透並充填，<br/>更新、變化，<br/>使我屬土成屬天；<br/>浸透我，浸透我，<br/>祂的生命深深浸透我，<br/>將我全魂更新過，<br/>自己、天然都消沒，<br/>何等釋放，<br/>祂以生命浸透我。<br/>',NULL,11676,11676);
INSERT INTO stanza VALUES('CS136','3','我心盼望<br/>祂的生命得顯彰，<br/>我臉瞻仰，<br/>返照基督的榮光，<br/>生命作王，<br/>我得模成主形像，<br/>有日身體改變，<br/>完全像祂樣；<br/>變化我，變化我，<br/>祂的生命逐部變化我，<br/>在我建造神居所，<br/>完成神中心工作，<br/>何等榮耀，<br/>祂以生命變化我。<br/>',NULL,11677,11677);
INSERT INTO stanza VALUES('CS137','1','如今主，你就是那靈，<br/>是那賜人生命的活靈，<br/>為進我靈，作我生命，<br/>你已完成必經的過程：<br/>你從天降下成肉體，<br/>從陰間上來又復起；<br/>今猶如空氣在我口裡，<br/>一喊你名，我就將你吸。<br/>對我，你豐富無比；<br/>對我，你何等實際；<br/>豐富無比，何等實際，<br/>你今就在我心裡！<br/>（重複一至四行）<br/>',NULL,11678,11678);
INSERT INTO stanza VALUES('CS137','2','願主多賜我以那靈，<br/>以你新鮮生命來供應，<br/>從我心中浸透、充盈，<br/>直達圓周，處處都光明；<br/>你多方運行並工作，<br/>像神聖膏油在塗抹，<br/>將我的心、靈全浸潤過，<br/>且來挑旺我深處愛火。<br/>有你，我靈會飛揚；<br/>有你，我心會歌唱；<br/>靈會飛揚，心會歌唱，<br/>生活如同在天上！<br/>（重複一至四行）<br/>',NULL,11679,11679);
INSERT INTO stanza VALUES('CS201','1','我們的心天天被吸引，<br/>更親近耶穌；<br/>祂比世人更美，<br/>新鮮勝過清晨甘露。<br/>世上最美言辭<br/>還不能盡說祂價值，<br/>祂是天天更加寶貝，<br/>今日遠勝昨日。<br/>',NULL,11680,11680);
INSERT INTO stanza VALUES('CS201','chorus','如此豐富的寶庫，<br/>一半都難領會；<br/>昨日，今日，到永遠，<br/>祂是天天更寶貝。<br/>',NULL,11681,11681);
INSERT INTO stanza VALUES('CS201','2','我們是在召會裡面<br/>看見祂的榮耀，<br/>祂的豐富全都在此，<br/>我們不再他找，<br/>祂使我們渴慕的靈<br/>一再得著飽足，<br/>祂是天天更加寶貝，<br/>現在遠勝當初。<br/>',NULL,11682,11682);
INSERT INTO stanza VALUES('CS201','3','如今祂是活靈，<br/>住在我們的靈裡面，<br/>藉祂甜美的塗抹，<br/>靈裡生命更充滿！<br/>當與聖徒一同聚集，<br/>我靈如插翅飛，<br/>因為如今我們的主<br/>比從前更寶貝。<br/>',NULL,11683,11683);
INSERT INTO stanza VALUES('CS201','4','主已使我們合而為一<br/>為著祂恢復，<br/>基督的豐富並祂豐滿─<br/>召會─全顯出，<br/>我們所有、所是，<br/>全傾於祂而不別歸，<br/>為著祂的偉大計畫<br/>比從前更寶貝。<br/>',NULL,11684,11684);
INSERT INTO stanza VALUES('CS202','1','我們已得到萬有基督，<br/>祂是我們的一切；<br/>呼喊祂的名，何等有福，<br/>何等神聖，何超越！<br/>',NULL,11685,11685);
INSERT INTO stanza VALUES('CS202','chorus','哦，說不出的喜樂，<br/>且滿了榮耀，<br/>滿了榮耀，滿了榮耀，<br/>說不出的喜樂，<br/>且滿了榮耀，<br/>甚至一半都未能說出。<br/>',NULL,11686,11686);
INSERT INTO stanza VALUES('CS202','2','我們已知道那靈基督，<br/>住在我們的靈裡，<br/>何等便利又親近的主，<br/>祂的甘甜無可比。<br/>',NULL,11687,11687);
INSERT INTO stanza VALUES('CS202','3','我們已得到生活祕訣，<br/>讀祂話並喊祂名！<br/>藉此喫喝主，必無所缺，<br/>牠的價值真顯明。<br/>',NULL,11688,11688);
INSERT INTO stanza VALUES('CS202','4','我們已尋到地方召會，<br/>我們已經回到家！<br/>永不再在巴比倫徘徊，<br/>在召會裡美而佳。<br/>',NULL,11689,11689);
INSERT INTO stanza VALUES('CS202','5','我們已經歷聖徒同聚，<br/>是地上最樂的事；<br/>藉此我們的靈不憂鬱，<br/>且使生活有價值。<br/>',NULL,11690,11690);
INSERT INTO stanza VALUES('CS203','1','我們來享受這<br/>新鮮活潑的耶穌，<br/>我們盡情喫喝吸入主。<br/>我們來享受這<br/>新鮮活潑的耶穌，<br/>真是實際，<br/>我們盡情喫喝吸入主。<br/>我們來享受這<br/>新鮮活潑的耶穌，<br/>真是實際，在召會中，<br/>我們盡情喫喝吸入主。<br/>我們來享受這<br/>新鮮活潑的耶穌，<br/>真是實際，在召會中，<br/>愛與合一，<br/>我們盡情喫喝吸入主。<br/>我們來享受這<br/>新鮮活潑的耶穌，<br/>耶穌是主！真是實際，<br/>在召會中，愛與合一，<br/>我們盡情喫喝吸入主。<br/>',NULL,11691,11691);
INSERT INTO stanza VALUES('CS204','1','享受主，享受主，<br/>享受祂的豐富。<br/>（四遍）<br/>享受，何必天天愁苦，<br/>失去見證。<br/>（二遍）<br/>享受主，享受主，<br/>享受祂的豐富。<br/>（二遍）<br/>?<br/>可換唱：釋放主！<br/>釋放主！<br/>…釋放，<br/>何必將主豐富盡都扣住。<br/>或：見證主！<br/>讚美主！<br/>分享主！<br/>喫喝主！<br/>吸入主！…<br/>',NULL,11692,11692);
INSERT INTO stanza VALUES('CS205','1','更多得著基督，<br/>多又多又多！<br/>更多得著基督，<br/>多過從前所得著。<br/>更多得祂作生命，<br/>豐富無可加；<br/>更多得著基督，<br/>我將自己多給祂。<br/>',NULL,11693,11693);
INSERT INTO stanza VALUES('CS205','2','更多喫主耶穌，<br/>多又多又多！<br/>更多喫主耶穌，<br/>喫得比前還要多。<br/>更多喫祂作食物，<br/>豐富又美佳。<br/>更多喫主耶穌，<br/>我們時刻都喫祂。<br/>',NULL,11694,11694);
INSERT INTO stanza VALUES('CS206','1','我們同站在守望臺，<br/>更上層樓向前觀測；<br/>主在裡面向我們說，<br/>祂的日子不再耽擱！<br/>',NULL,11695,11695);
INSERT INTO stanza VALUES('CS206','chorus','趁著今天多享受主，<br/>不要等到那日受苦，<br/>等到那日已經太遲！<br/>',NULL,11696,11696);
INSERT INTO stanza VALUES('CS206','2','蒙昧的人忙著搭窩，<br/>堆積財寶，據如己有；<br/>我們不等烈火來烤，<br/>今天憑信，先行焚燒。<br/>',NULL,11697,11697);
INSERT INTO stanza VALUES('CS206','3','無花果樹要不發枝，<br/>葡萄樹要不結果子，<br/>橄欖樹要不再效力，<br/>田地也要不出糧食。<br/>',NULL,11698,11698);
INSERT INTO stanza VALUES('CS206','4','只要享受基督豐富，<br/>地上有無就可不顧；<br/>棚內缺牛，圈中絕羊，<br/>對於我們沒有兩樣！<br/>',NULL,11699,11699);
INSERT INTO stanza VALUES('CS206','5','有祂就彀我們歡喜，<br/>天天加力，成為勁旅！<br/>有祂就彀我們快跑，<br/>與祂同奔，步步登高！<br/>',NULL,11700,11700);
INSERT INTO stanza VALUES('CS207','1','我們同來享受主的豐富，<br/>因主耶穌是賜生命的靈，<br/>又住在我們靈裡，<br/>賜我們生命供應，<br/>運行調和又變化。<br/>哦，何等奇妙的主，<br/>和我聯合為一，<br/>我要高聲歌唱。<br/>阿利路亞，讚美我主！<br/>我們同來享受<br/>主的一切豐富，<br/>飽嘗這包羅萬有的主。<br/>',NULL,11701,11701);
INSERT INTO stanza VALUES('CS208','1','靠耶和華得的喜樂<br/>是你的力量。<br/>靠耶和華得的喜樂<br/>是你的力量。<br/>喫肥美的，喝甘甜的，<br/>今日是我們主的聖日。<br/>靠耶和華得的喜樂<br/>是你的力量。<br/>',NULL,11702,11702);
INSERT INTO stanza VALUES('CS209','1','生命樹果，甘甜之至，<br/>生命全豐全足。<br/>前我死枯，如今活著；<br/>前餓，如今喫喝。<br/>',NULL,11703,11703);
INSERT INTO stanza VALUES('CS209','2','是神領我到生命樹，<br/>享受基督自己。<br/>其中滋味，開口一喫，<br/>就覺甘甜無比！<br/>',NULL,11704,11704);
INSERT INTO stanza VALUES('CS209','3','基督是我生命供應，<br/>祂作我的食物；<br/>祂是惟一純淨享受，<br/>祂外再無滿足。<br/>',NULL,11705,11705);
INSERT INTO stanza VALUES('CS209','4','我今盡情喫生命樹，<br/>因為喫就是路！<br/>生命藉喫加我裡頭，<br/>使我憑祂而活。<br/>',NULL,11706,11706);
INSERT INTO stanza VALUES('CS210','1','神已將祂兒子賜下，<br/>作生命樹無比豐富；<br/>要叫人人一嘗便知，<br/>神是我們食物。<br/>神是我們食物！<br/>神是我們食物！<br/>我們嘗過就作見證，<br/>神是我們食物！<br/>',NULL,11707,11707);
INSERT INTO stanza VALUES('CS210','2','藉喫把主接受進去；<br/>憑主而活，並不喫力，<br/>因為我們所喫筵席<br/>全是主的自己。<br/>主是我們筵席！<br/>主是我們筵席！<br/>我們喫主，因主活著，<br/>主是我們筵席！<br/>',NULL,11708,11708);
INSERT INTO stanza VALUES('CS210','3','我們所喫乃是基督─<br/>是糧，是肉，屬天食物；<br/>生命供應，營養充足，<br/>我們天天喫主！<br/>我們天天喫主，<br/>我們天天喫主，<br/>生命供應，營養充足，<br/>我們天天喫主！<br/>',NULL,11709,11709);
INSERT INTO stanza VALUES('CS210','4','喫這筵席，真是享福！<br/>應有盡有，極其豐富！<br/>無論何人，凡是願意，<br/>都可白白來喫。<br/>都可白白來喫，<br/>都可白白來喫，<br/>無論何人，凡是願意，<br/>都可白白來喫。<br/>',NULL,11710,11710);
INSERT INTO stanza VALUES('CS211','1','經上記著：<br/>人活著不是單靠食物，<br/>乃是靠著神口裡<br/>所出的一切話。<br/>（太四4）<br/>',NULL,11711,11711);
INSERT INTO stanza VALUES('CS211','chorus','阿利路亞！阿利路亞！<br/>阿利路亞！阿們，<br/>阿利路亞！<br/>',NULL,11712,11712);
INSERT INTO stanza VALUES('CS211','2','叫人活著的是靈，<br/>肉體是無益的；<br/>我對你們說的話，<br/>就是靈、是生命。<br/>（約六63）<br/>',NULL,11713,11713);
INSERT INTO stanza VALUES('CS211','3','我得著你的言語，<br/>就當食物喫了。<br/>你的話在我心中，<br/>是我歡喜快樂。<br/>（耶十五16）<br/>',NULL,11714,11714);
INSERT INTO stanza VALUES('CS211','4','要拿著靈的寶劍，<br/>這靈是神的話─<br/>藉著多方的禱告，<br/>每次都在靈裡。<br/>（弗六17～18）<br/>',NULL,11715,11715);
INSERT INTO stanza VALUES('CS211','5','要藉著話裡的水，<br/>來把召會洗淨，<br/>成為聖潔，獻給主，<br/>作榮耀的召會。<br/>（弗五26～27）<br/>',NULL,11716,11716);
INSERT INTO stanza VALUES('CS212','1','哦，主耶穌，<br/>我們在你前稱頌，<br/>為著杯餅我們感激不已；<br/>同心讚美，<br/>你竟然成為食物，<br/>叫人多方享受你的自己。<br/>',NULL,11717,11717);
INSERT INTO stanza VALUES('CS212','chorus','我心我靈立即興起讚美，<br/>你何微小，你何微小。<br/>直至永世還要喫喝不已，<br/>你何微小，你何微小。<br/>',NULL,11718,11718);
INSERT INTO stanza VALUES('CS212','2','何等可憐─<br/>當基督來到人群，<br/>滿帶豐盛，<br/>來作生命供應，<br/>人竟拒絕，<br/>反倚靠道理教訓，<br/>不懂如何取用祂的豐盛。<br/>',NULL,11719,11719);
INSERT INTO stanza VALUES('CS212','chorus','我們所需乃是把你喫了，<br/>何等奇妙，何等逍遙！<br/>我們喫主，<br/>裡面就被復甦。<br/>長大成人，活出基督。<br/>',NULL,11720,11720);
INSERT INTO stanza VALUES('CS212','3','哦主耶穌，<br/>你降卑來到世上，<br/>並非為著在外面作君王；<br/>乃作食物<br/>供我們享受飽足，<br/>裡面生命引導我們成熟。<br/>',NULL,11721,11721);
INSERT INTO stanza VALUES('CS212','4','主，讚美你，<br/>你實在偉大榮耀，<br/>能力無窮，<br/>威嚴、豐富無限，<br/>但你竟成<br/>微小食物真奇妙，<br/>我們更要高唱直到永遠。<br/>',NULL,11722,11722);
INSERT INTO stanza VALUES('CS213','1','勝哉、勝哉、勝哉，<br/>完全回到起初！<br/>神今在基督裡，<br/>成為我們食物。<br/>喫喝、喫喝、喫喝，<br/>我們盡情喫喝；<br/>在神恢復裡，<br/>我不知太多。<br/>',NULL,11723,11723);
INSERT INTO stanza VALUES('CS213','2','大聲呼喊耶穌，<br/>哦，我們真飽足！<br/>主在我們口中，<br/>只等我們來喫。<br/>用靈大聲呼喊，<br/>遠勝默默點頭；<br/>在神恢復裡，<br/>我不知太多。<br/>',NULL,11724,11724);
INSERT INTO stanza VALUES('CS213','3','細嚼、細嚼、細嚼，<br/>不是外面工作；<br/>放下你的重擔，<br/>再來坐下喫喝。<br/>坐席、坐席、坐席，<br/>教訓束之高閣！<br/>在神恢復裡，<br/>我只知喫喝。<br/>',NULL,11725,11725);
INSERT INTO stanza VALUES('CS214','1','主曾召你我得救，<br/>祂再召你我得勝。<br/>對主呼召說『阿們』─<br/>要得勝！<br/>召會光景墮落了，<br/>許多道理都知道，<br/>生命卻是摸不著─<br/>要得勝！<br/>',NULL,11726,11726);
INSERT INTO stanza VALUES('CS214','chorus','要得勝！要得勝！<br/>勝過死沉的宗教，<br/>要得勝！<br/>放下所有的辛勞，<br/>脫離一切的老套，<br/>只管單單來喫主─<br/>要得勝！<br/>',NULL,11727,11727);
INSERT INTO stanza VALUES('CS214','2','神原命定人來喫，<br/>喫是今日的恢復，<br/>喫是得勝的道路─<br/>要得勝！<br/>快來享受生命樹，<br/>脫去道理的束縛，<br/>得勝藉著喫基督─<br/>要得勝！<br/>',NULL,11728,11728);
INSERT INTO stanza VALUES('CS214','3','教訓不能變化魂，<br/>叫神旨意受虧損，<br/>喫主搆上神標準─<br/>要得勝！<br/>若要得勝就要喫，<br/>無論聚集或獨處，<br/>喫到全人得飽足─<br/>要得勝！<br/>',NULL,11729,11729);
INSERT INTO stanza VALUES('CS214','4','速速催促主再來，<br/>藉著喫喝產男孩，<br/>現在喫祂，<br/>一直喫─要得勝！<br/>為著主的金燈臺，<br/>為著得勝的男孩，<br/>為著新婦祂所愛─<br/>要得勝！<br/>',NULL,11730,11730);
INSERT INTO stanza VALUES('CS215','1','『你們來喫，』<br/>主正在呼召，<br/>『你們來喫。』<br/>我們可以隨時隨刻<br/>喫喝主！<br/>祂是『日用的飲食，』<br/>祂纔能叫人滿足。<br/>『你們來喫，』<br/>主正在呼召，<br/>『你們來喫。』<br/>',NULL,11731,11731);
INSERT INTO stanza VALUES('CS215','2','『你們來喫，』<br/>主正在呼召，<br/>『你們來喫。』<br/>我們若是隨時隨刻<br/>喫喝主，<br/>祂就作我們生命，<br/>一直到生命滿出！<br/>『你們來喫，』<br/>主正在呼召，<br/>『你們來喫。』<br/>',NULL,11732,11732);
INSERT INTO stanza VALUES('CS216','1','喝！從寶座流出<br/>純淨生命河的水！<br/>喫！生命樹果子，<br/>豐碩又纍纍垂垂！<br/>看！那滿城光輝，<br/>不需燈光或日、月，<br/>她沒有黑夜！<br/>',NULL,11733,11733);
INSERT INTO stanza VALUES('CS216','chorus','來罷！哦，來罷！<br/>聖靈與新婦說；<br/>來罷！哦，來罷！<br/>聽見的人也說；<br/>來罷！哦，來罷！<br/>口渴又願意的<br/>可白白來喝！<br/>',NULL,11734,11734);
INSERT INTO stanza VALUES('CS216','2','基督乃是我們河水，<br/>在裡面湧流；<br/>基督乃是生命樹果，<br/>供我們享受；<br/>基督乃是我們的光、<br/>晨星與白晝；<br/>祂乃是萬有！<br/>',NULL,11735,11735);
INSERT INTO stanza VALUES('CS216','3','我們洗淨袍子，<br/>有權來喫生命樹，<br/>『哦主，阿們，<br/>阿利路亞，』<br/>我們真有福！<br/>我們操練我們的靈，<br/>來經歷基督─<br/>何等的基督！<br/>',NULL,11736,11736);
INSERT INTO stanza VALUES('CS216','4','現在我們有一個家，<br/>輝煌勝太陽，<br/>弟兄姊妹同心站住<br/>合一的立場；<br/>地方召會乃是<br/>新耶路撒冷豫嘗─<br/>何等的豫嘗！<br/>',NULL,11737,11737);
INSERT INTO stanza VALUES('CS217','1','我們來，我們來，<br/>到神殿裡來；我們來，<br/>從神殿有水流出來。<br/>這水流，在殿右，<br/>晝夜湧流著，滋潤我們，<br/>結出生命的美果。<br/>',NULL,11738,11738);
INSERT INTO stanza VALUES('CS217','2','從這殿，從這殿，<br/>湧出這水流，<br/>從這殿到全地，<br/>生命在湧流，<br/>願這水流加深，<br/>主，聽我們求，我們就必<br/>被你量過並佔有。<br/>',NULL,11739,11739);
INSERT INTO stanza VALUES('CS217','3','量我們，量我們，<br/>天天量又量，<br/>量我們，量更多，<br/>一直量又量，<br/>直到我們看見<br/>水流成江河，流通全地，<br/>使人全被主點活。<br/>',NULL,11740,11740);
INSERT INTO stanza VALUES('CS217','4','領我們，領我們，<br/>從水流經過，<br/>領我們從水流，<br/>經過再經過，<br/>水流一直漲高，<br/>成可洑的水，<br/>我們被浸透，<br/>永遠享神恩惠。<br/>',NULL,11741,11741);
INSERT INTO stanza VALUES('CS217','5','都必活，都必活，<br/>隨流都必活，<br/>都必活，真正活，<br/>百物隨流活，<br/>願這水流帶來<br/>豐盛的生命，<br/>直到眾召會<br/>在全地都顯明。<br/>',NULL,11742,11742);
INSERT INTO stanza VALUES('CS218','1','我們在喝生命的水，<br/>活水湧出如同江河！<br/>喝了這水，主曾明說，<br/>就永遠永遠不再渴！<br/>難道永遠不再渴？是！<br/>永遠不再渴！<br/>難道永遠不再渴？是！<br/>永遠不再渴！<br/>喝了這水，主曾明說，<br/>就永遠永遠不再渴。<br/>',NULL,11743,11743);
INSERT INTO stanza VALUES('CS218','2','我們在喫生命的糧─<br/>神的筵席為人擺設；<br/>喫了這糧，主曾明說，<br/>就永遠永遠不再餓。<br/>難道永遠不再餓？是！<br/>永遠不再餓！<br/>難道永遠不再餓？是！<br/>永遠不再餓！<br/>喫了這糧，主曾明說，<br/>就永遠永遠不再餓。<br/>',NULL,11744,11744);
INSERT INTO stanza VALUES('CS218','3','我們在吸生命之氣，<br/>就是那賜生命的靈；<br/>吸了這氣─直到永遠，<br/>就必定有神的生命。<br/>難道有神的生命？是！<br/>有神的生命！<br/>難道有神的生命？是！<br/>有神的生命！<br/>吸了這氣─直到永遠，<br/>都必定有神的生命。<br/>',NULL,11745,11745);
INSERT INTO stanza VALUES('CS218','4','我們在嘗生命之酒，<br/>神聖芬芳絕無僅有；<br/>嘗了這酒─每時每刻，<br/>都必定有神的喜樂。<br/>難道有神的喜樂？是！<br/>有神的喜樂！<br/>難道有神的喜樂？是！<br/>有神的喜樂！<br/>嘗了這酒─每時每刻，<br/>都必定有神的喜樂。<br/>',NULL,11746,11746);
INSERT INTO stanza VALUES('CS218','5','基督是王死而復活，<br/>賜人生命豐盛闊綽；<br/>你接受祂，也必高歌，<br/>並且要永遠的活著。<br/>難道永遠的活著？是！<br/>永遠的活著！<br/>難道永遠的活著？是！<br/>永遠的活著！<br/>你接受祂，也必高歌，<br/>並且要永遠的活著！<br/>',NULL,11747,11747);
INSERT INTO stanza VALUES('CS219','1','活水湧流，<br/>（湧流！湧流！）<br/>生命水湧流，<br/>（湧流！湧流！）<br/>滿帶神生命，<br/>（生命！生命！）<br/>生命的供應，<br/>（供應！供應！）<br/>使我們成形，<br/>（成形！成形！）<br/>成為祂榮形，<br/>（榮形！榮形！）<br/>流成祂模樣，<br/>神和人都在此得著滿足。<br/>生命何豐富，<br/>喜樂何滿足，<br/>奇妙甘甜，越過越富，<br/>主是何深厚，<br/>永不能測透，<br/>卻流經我身給我享受。<br/>享受，享受不盡，<br/>成長，成長不停，<br/>流出寶石、精金，<br/>成為神居所榮耀見證。<br/>',NULL,11748,11748);
INSERT INTO stanza VALUES('CS220','1','我曾經在巴比倫地<br/>乾渴度日；<br/>始終無何能使我心滿足。<br/>但有一天<br/>我來到蒙福的召會，<br/>我纔找著那洋溢的活水。<br/>',NULL,11749,11749);
INSERT INTO stanza VALUES('CS220','chorus','我今飲於生命活水泉源，<br/>我喜出望外，<br/>滿足溢於全人！<br/>我今飲於生命活水泉源，<br/>奇妙豐富的供應到永遠。<br/>',NULL,11750,11750);
INSERT INTO stanza VALUES('CS220','2','從寶座流出的水<br/>何等的甘甜，<br/>經常流進、流出，<br/>在我裡面。<br/>如今我找著<br/>長久渴慕的泉源，<br/>在此生命極豐盛又新鮮。<br/>',NULL,11751,11751);
INSERT INTO stanza VALUES('CS220','3','親愛的弟兄，<br/>為何不同來聚集？<br/>又深又廣的泉源等著你！<br/>好牧人巴望<br/>領你到地方召會，<br/>祂要使你多年心願得遂！<br/>',NULL,11752,11752);
INSERT INTO stanza VALUES('CS221','1','恩典實際湧自基督，<br/>儘管暢飲於活泉！<br/>我們讚美，歌唱不倦，<br/>在召會（家）裡面。<br/>',NULL,11753,11753);
INSERT INTO stanza VALUES('CS221','chorus','榮耀歸神！<br/>我們暢飲於活泉！<br/>榮耀歸神！<br/>我們在家裡面。<br/>',NULL,11754,11754);
INSERT INTO stanza VALUES('CS221','2','主是何等樂意施恩，<br/>儘管暢飲於活泉！<br/>不必天涯海角去找，<br/>祂是在家裡面。<br/>',NULL,11755,11755);
INSERT INTO stanza VALUES('CS221','3','任憑撒但多方打岔，<br/>儘管暢飲於活泉！<br/>無論何時，撒但不能<br/>絲毫勝過我們。<br/>',NULL,11756,11756);
INSERT INTO stanza VALUES('CS221','4','你若渴了，火速趕來，<br/>儘管暢飲於活泉！<br/>只管暢飲，不用擔心，<br/>你是在家裡面。<br/>',NULL,11757,11757);
INSERT INTO stanza VALUES('CS222','1','阿利路亞，主是生命，<br/>如氣給人呼吸！<br/>祂向門徒吹一口氣，<br/>並說，<br/>『你們接受聖氣。』<br/>現在我們呼吸，<br/>現在我們呼吸，<br/>呼吸我主生命氣息。<br/>',NULL,11758,11758);
INSERT INTO stanza VALUES('CS223','1','基督是那賜生命的靈，<br/>基督也是生命的話；<br/>生命的靈供應我的靈，<br/>基督的話變成生命─<br/>藉著天天喫祂、<br/>喝祂、並呼吸祂！<br/>藉著天天喫祂、喝祂、<br/>並呼吸祂！<br/>',NULL,11759,11759);
INSERT INTO stanza VALUES('CS223','2','基督是那賜生命的靈，<br/>基督也是生命的話；<br/>生命的靈供應我的靈，<br/>基督的話變成生命─<br/>藉著用靈禱讀、<br/>讚美、呼喊主名！<br/>藉著用靈禱讀、讚美、<br/>呼喊主名！<br/>',NULL,11760,11760);
INSERT INTO stanza VALUES('CS224','1','一呼一吸我吸主，<br/>阿們！阿們！<br/>一呼一吸我就活，<br/>阿們！阿們！<br/>哦，祂呼出而我吸入，<br/>祂生命從我裡流出，<br/>因為我已學會<br/>深深吸入主。<br/>',NULL,11761,11761);
INSERT INTO stanza VALUES('CS224','2','約翰第三章<br/>是指外面空氣，<br/>風在外面吹呀吹，<br/>隨意而吹。<br/>並不知牠來自何方，<br/>並不知牠吹往何處，<br/>凡從聖靈生的，<br/>也都是如此。<br/>',NULL,11762,11762);
INSERT INTO stanza VALUES('CS224','3','約翰二十章<br/>是指裡面空氣，<br/>主耶穌所呼出的<br/>生命之氣，<br/>只要我們接受這氣─<br/>不必思慮，只要呼吸；<br/>我們經歷生命<br/>是藉著這氣。<br/>',NULL,11763,11763);
INSERT INTO stanza VALUES('CS224','4','無論在那裡都有<br/>空氣，空氣！<br/>牠包圍籠罩我們，<br/>隨時、隨地！<br/>白白賜給，豐富便利，<br/>我們生活豐盛無比；<br/>所以弟兄姊妹，<br/>同來吸這氣。<br/>',NULL,11764,11764);
INSERT INTO stanza VALUES('CS224','5','只要來呼喊祂名，<br/>哦主！哦主！<br/>祂就成我們氣息，<br/>哦主！哦主！<br/>從最深處吸入祂名，<br/>直到我們充滿生命，<br/>這位耶穌是<br/>何等生命供應！<br/>',NULL,11765,11765);
INSERT INTO stanza VALUES('CS225','1','主對呼喊祂名的人<br/>何等的相近！每次呼喊，<br/>祂的同在就剛強我們！<br/>尋找耶穌，就必尋見；<br/>喊祂，就相近；<br/>我們深得安慰，<br/>因為祂可愛可親！<br/>',NULL,11766,11766);
INSERT INTO stanza VALUES('CS225','chorus','耶穌，何等的名！<br/>哦，主耶穌，賜生命名！<br/>得勝的名，榮耀的名，<br/>超越的名─何等的名！<br/>耶穌，剛強的名！<br/>哦，主耶穌，安慰的名！<br/>名可常吸入，<br/>可隨處喊出；<br/>哦，主耶穌，何等的名！<br/>',NULL,11767,11767);
INSERT INTO stanza VALUES('CS225','2','只要呼喊耶穌的名，<br/>你就必得救。<br/>哦！主耶穌，阿利路亞，<br/>從此不被囚！<br/>我們舉起救恩之杯，<br/>呼喊祂的名，<br/>祂便拯救我們<br/>脫離多少的事情！<br/>',NULL,11768,11768);
INSERT INTO stanza VALUES('CS225','3','猶太人或希利尼人，<br/>並沒有差異，<br/>主對呼喊祂名的人<br/>都是豐富的。<br/>哦主耶穌，呼喊你名，<br/>活著真喜樂！<br/>每當把你的名吸入，<br/>我們就快活！<br/>',NULL,11769,11769);
INSERT INTO stanza VALUES('CS225','4','我們欣然享受<br/>經常施恩的救主，<br/>無論禍福，無論樂苦，<br/>都呼喊如故！<br/>只要我有氣息活著，<br/>我就必喊主，<br/>因祂樂意側耳傾聽，<br/>恩典常傾注！<br/>',NULL,11770,11770);
INSERT INTO stanza VALUES('CS225','5','我們如此樂而不疲<br/>呼喊主的名，<br/>對主讚美感激之情<br/>便油然而生。<br/>我們乃是那些<br/>隨處呼喊主的人，<br/>與那清心愛主的人<br/>同呼喊蒙恩。<br/>',NULL,11771,11771);
INSERT INTO stanza VALUES('CS226','1','有一嬰孩，<br/>祂是全能的神；<br/>有一兒子，<br/>祂是永在的父。<br/>哦，何奇妙！<br/>神人相調在祂身；<br/>來作策士，<br/>完成永遠救贖。<br/>國度政權，<br/>必擔在祂肩頭上！<br/>和平的君，<br/>平安加增無窮！<br/>',NULL,11772,11772);
INSERT INTO stanza VALUES('CS227','1','祂的名是奇妙，<br/>祂的名是策士，<br/>祂是全能的神，<br/>永在的父；<br/>有一嬰孩降生，<br/>一子賜給我們，<br/>祂是和平的君，<br/>耶穌我主。<br/>讚美創造主，<br/>耶穌我救主，<br/>生命的靈內住；<br/>在靈裡敬拜祂，<br/>愛祂並事奉祂，<br/>祂的名是奇妙，<br/>耶穌我主。<br/>',NULL,11773,11773);
INSERT INTO stanza VALUES('CS228','1','我們今活著<br/>是靠著吸入主，<br/>並非靠思想活著，<br/>惟呼吸纔是路。<br/>我們從裡面最深處喊<br/>『哦主！』<br/>滿心喜樂作見證，<br/>我們在吸入主。<br/>',NULL,11774,11774);
INSERT INTO stanza VALUES('CS228','chorus','吸入主，吸入主，<br/>吸入主生命；<br/>祂是生命的供應，<br/>吸入主不稍停！<br/>吸入主，吸入主，<br/>吸入主生命；<br/>祂是生命的供應，<br/>吸入主不稍停！<br/>',NULL,11775,11775);
INSERT INTO stanza VALUES('CS228','2','祂真是奇妙，<br/>祂是生命的氣，<br/>原來祂在肉身裡，<br/>如今作我氣息；<br/>祂改變形狀，<br/>如今乃是那靈─<br/>神所呼出是基督，<br/>我所吸入是靈。<br/>',NULL,11776,11776);
INSERT INTO stanza VALUES('CS228','chorus','基督是我生命，<br/>無論在那裡，<br/>我呼喊祂的名，<br/>就得著祂氣息！<br/>',NULL,11777,11777);
INSERT INTO stanza VALUES('CS229','1','哦，主耶穌！<br/>哦，主耶穌！<br/>呼喊你名何甘甜！<br/>比酒更美，比蜜更甜；<br/>哦，主耶穌！阿們。<br/>',NULL,11778,11778);
INSERT INTO stanza VALUES('CS230','1','我們已經找到<br/>摸著主的最簡單的路，<br/>主曾應許凡呼喊祂的人<br/>必蒙祂垂顧，<br/>因此只要我們<br/>從靈裡面來向主呼喊，<br/>就可以摸著主。<br/>哦！主，阿們，<br/>阿利路亞！<br/>哦！主，阿們，<br/>阿利路亞！<br/>哦！主，阿們，<br/>阿利路亞！<br/>如此就摸著主。<br/>',NULL,11779,11779);
INSERT INTO stanza VALUES('CS231','1','每當我喊主耶穌，<br/>我深處總覺發燙；<br/>祂生命冉冉而升上，<br/>在我裡面成長。<br/>請來同喊主耶穌，<br/>這喜樂地上無雙；<br/>主且要進入你裡面，<br/>作你生命供你享。<br/>',NULL,11780,11780);
INSERT INTO stanza VALUES('CS231','2','請來同喊主耶穌，<br/>祂必使你得釋放─<br/>不管你的心多疏遠，<br/>或如野馬脫韁。<br/>只要簡單的喊主，<br/>不管你在何地方；<br/>一呼喊立刻祂就來，<br/>祂原近在你口旁。<br/>',NULL,11781,11781);
INSERT INTO stanza VALUES('CS231','3','呼喊我們的救主，<br/>每次祂都必垂聽。<br/>何不來投靠祂胸懷，<br/>重擔立變輕盈！<br/>祂是我們的山寨，<br/>是喜樂、安息、力量；<br/>只要你嘗嘗便知道，<br/>祂恩典真是無量。<br/>',NULL,11782,11782);
INSERT INTO stanza VALUES('CS231','4','上好乃是主自己，<br/>等著你白白接受。<br/>讓我們向祂全敞開，<br/>讓祂生命拯救！<br/>當祂再來的時候，<br/>我們不驚惶失措，<br/>並且要面見祂榮耀，<br/>若一直讓祂成熟。<br/>',NULL,11783,11783);
INSERT INTO stanza VALUES('CS232','1','當你說『主』，你是把<br/>難以形容的一語道出；<br/>當你說『主』，<br/>你宣告你所要的<br/>只是那『萬主之主』。<br/>除祂再無愛慕，<br/>萬事盡是虛無；<br/>祂是一切一切，<br/>在祂一無所缺。<br/>當你說『主耶穌』，<br/>你說出一切。<br/>',NULL,11784,11784);
INSERT INTO stanza VALUES('CS233','1','呼喊『哦，主耶穌！』<br/>這使我們靈剛強！<br/>在靈裡摸著主，<br/>憂鬱就變成頌揚！<br/>切勿聽從撒但，<br/>切勿受他的打岔，<br/>只要回到靈裡行動，<br/>毫不懼怕！<br/>呼喊『哦，主耶穌，』<br/>就必終日將祂享！<br/>',NULL,11785,11785);
INSERT INTO stanza VALUES('CS234','1','『哦，主耶穌！』<br/>喊祂名，<br/>使我終日運用靈；<br/>不斷呼喊祂的名，<br/>祂就來充滿我靈。<br/>',NULL,11786,11786);
INSERT INTO stanza VALUES('CS234','chorus','喊：『哦，主耶穌！』<br/>喊：『哦，主耶穌！』<br/>喊：『哦，主耶穌！』<br/>終日喊主耶穌！<br/>',NULL,11787,11787);
INSERT INTO stanza VALUES('CS234','2','『哦，主耶穌！』<br/>就是路，<br/>使我不至走迷途。<br/>不分晝夜常呼求，<br/>祂必向我施拯救。<br/>',NULL,11788,11788);
INSERT INTO stanza VALUES('CS234','3','現在從魂轉入靈，<br/>『哦，主耶穌！』<br/>喊祂名。<br/>從我自己轉向主，<br/>終日呼喊『主耶穌！』<br/>',NULL,11789,11789);
INSERT INTO stanza VALUES('CS234','4','如此呼喊充滿主，<br/>祂是聖靈，生命主。<br/>呼喊向祂來表示，<br/>我之愛祂永不止。<br/>',NULL,11790,11790);
INSERT INTO stanza VALUES('CS235','1','我時刻呼喊主名，<br/>當我往前行，<br/>我時刻呼喊主名，<br/>祂使我歡騰；<br/>雖然黑雲籠罩天空，<br/>遮蔽我路程，<br/>我只要呼喊主名，<br/>祂必顯權能。<br/>祂是我朋友，<br/>最信實忠誠，<br/>我可倚靠祂，<br/>直走完路程。<br/>我時刻呼喊主名，<br/>當我往前行，<br/>我時刻呼喊主名，<br/>祂使我歡騰；<br/>雖然黑雲籠罩天空，<br/>遮蔽我路程，<br/>我只要呼喊主名，<br/>祂必顯權能。<br/>',NULL,11791,11791);
INSERT INTO stanza VALUES('CS236','1','自從基督釋放我，<br/>我心充滿了喜樂。<br/>自從基督釋放我，<br/>我口高聲唱新歌。<br/>終日將祂名呼喊，<br/>我過天上的生活，<br/>何等的平安！<br/>何等的豐滿！<br/>自從基督釋放我！<br/>',NULL,11792,11792);
INSERT INTO stanza VALUES('CS237','1','在早晨我們呼喊：<br/>『哦，主耶穌！』<br/>午間我們呼喊：<br/>『哦，主耶穌！』<br/>在晚上我們呼喊：<br/>『哦，主耶穌！』<br/>終日我們呼喊：<br/>『哦，主耶穌！』<br/>祂就住在靈裡面；<br/>勿別處浪費時間。<br/>讚美主！讚美主！哦…<br/>',NULL,11793,11793);
INSERT INTO stanza VALUES('CS237','2','在靈裡呼喊，<br/>享受祂的豐富；<br/>在靈裡歎息，<br/>必能摸著主；<br/>在靈裡禱告，<br/>直到焚燒，高昂；<br/>住在靈裡面，<br/>必像祂剛強。<br/>有分祂豐盛生命，<br/>漸漸變成主榮形。<br/>榮耀，阿利路亞！<br/>榮耀歸主名！<br/>榮耀，阿利路亞！<br/>榮耀歸主名！<br/>',NULL,11794,11794);
INSERT INTO stanza VALUES('CS238','1','在主耶穌名下，<br/>在主耶穌名下，<br/>我們就必得勝！<br/>在主耶穌名下，<br/>在主耶穌名下，<br/>撒但懼怕無能。<br/>在我們主耶穌名下，<br/>無人能彀抵擋；<br/>在主耶穌名下，<br/>我們就必得勝！<br/>',NULL,11795,11795);
INSERT INTO stanza VALUES('CS239','1','『金銀財寶我沒有，<br/>只把我所有的給你；<br/>我奉耶穌基督的名，<br/>叫你現在起來行走！』<br/>他就走著，又跳著，<br/>又讚美神；走著，<br/>又跳著，又讚美神。<br/>阿利路亞，讚美我主！<br/>榮耀，榮耀歸於主名！<br/>',NULL,11796,11796);
INSERT INTO stanza VALUES('CS239','2','金銀財寶我沒有，<br/>卻有七倍加強的靈；<br/>我奉耶穌基督的名，<br/>剛強站起作祂見證！<br/>我在召會中<br/>又讚美又見證，<br/>召會中又讚美又見證。<br/>阿利路亞，讚美我主！<br/>榮耀，榮耀歸於主名！<br/>',NULL,11797,11797);
INSERT INTO stanza VALUES('CS240','1','基督美地，豐富之地，<br/>神已賜給我們了！<br/>山、谷、泉、源，<br/>流水潺潺，<br/>阿利路亞何榮耀！<br/>',NULL,11798,11798);
INSERT INTO stanza VALUES('CS240','2','基督美地，豐富之地，<br/>神已賜給我們了！<br/>有奶有蜜，分文不要，<br/>白白恩典，何榮耀！<br/>',NULL,11799,11799);
INSERT INTO stanza VALUES('CS240','3','基督美地，豐富之地，<br/>神已賜給我們了！<br/>有葡萄樹，無花果樹，<br/>豐富供應給我們！<br/>',NULL,11800,11800);
INSERT INTO stanza VALUES('CS240','4','基督美地，豐富之地，<br/>神已賜給我們了！<br/>五穀和油，我們享受，<br/>無限無量，何榮耀！<br/>',NULL,11801,11801);
INSERT INTO stanza VALUES('CS240','5','同來經營，同來經營，<br/>在美地上同經營！<br/>晝夜不息，帶著能力，<br/>收穫豐富，何榮耀！<br/>',NULL,11802,11802);
INSERT INTO stanza VALUES('CS240','6','在聚會中，在聚會中，<br/>榮耀筵席將主嘗！<br/>美地出產，上好肥甘，<br/>帶來獻上同分享！<br/>',NULL,11803,11803);
INSERT INTO stanza VALUES('CS240','7','阿利路亞，阿利路亞，<br/>美地神給我們了！<br/>經營不息，享受不已，<br/>阿利路亞，何榮耀！<br/>',NULL,11804,11804);
INSERT INTO stanza VALUES('CS241','1','基督是神所應許的美地，<br/>靠祂而爭戰，<br/>必趕出仇敵；<br/>跟隨主元帥，<br/>進入得安息，<br/>這地是為著我和你。<br/>',NULL,11805,11805);
INSERT INTO stanza VALUES('CS241','2','高大的城邑，<br/>非你建造的；<br/>房屋滿美物，<br/>非你裝滿的；<br/>鑿成的水井，<br/>非你鑿成的；<br/>葡萄，橄欖非你栽的。<br/>',NULL,11806,11806);
INSERT INTO stanza VALUES('CS241','3','有河有泉源，<br/>谷中有水溪，<br/>有小麥、大麥、<br/>果樹、油和蜜，<br/>居住在這地，<br/>必永不缺食；<br/>山可挖銅，地有鐵石。<br/>',NULL,11807,11807);
INSERT INTO stanza VALUES('CS241','4','我們同歡樂，<br/>歌唱於錫安；<br/>我們同向前，<br/>進入祂美善；<br/>新酒和五穀，<br/>出產肥而甘；<br/>這地實在又豐又滿。<br/>',NULL,11808,11808);
INSERT INTO stanza VALUES('CS241','5','基督是我的，<br/>基督是你的，<br/>我們分享祂，<br/>並不分彼此，<br/>哦，我們產業，<br/>廣大達四極；<br/>全地是為著我們的。<br/>',NULL,11809,11809);
INSERT INTO stanza VALUES('CS241','6','這廣大享受，<br/>這豐盈之地，<br/>路上滴脂油，<br/>到處是乳蜜，<br/>恩重重四溢！<br/>哦，嘗嘗便知，<br/>基督是我們的美地。<br/>',NULL,11810,11810);
INSERT INTO stanza VALUES('CS241','7','祂道成肉身，<br/>受盡人欺厭，<br/>由死而復活，<br/>升上了高天，<br/>得榮耀尊貴，<br/>作祂的冠冕；<br/>美地今在我們裡面。<br/>',NULL,11811,11811);
INSERT INTO stanza VALUES('CS241','8','我們同經營內住的基督；<br/>將豐餘收穫獻上作食物；<br/>如此獻基督，<br/>神、人得飽足；<br/>我們歌頌永不止住。<br/>',NULL,11812,11812);
INSERT INTO stanza VALUES('CS241','9','讚美神使祂成為我美地；<br/>讚美神使祂成為你美地；<br/>哦，阿利路亞！<br/>榮耀的美地；<br/>我們今住基督美地！<br/>',NULL,11813,11813);
INSERT INTO stanza VALUES('CS242','1','美地，美地，<br/>神已賜給我們；<br/>基督是神所賜美地。<br/>這是召會合一，<br/>大家來在一起，<br/>脫離彎曲世代，<br/>世界完全丟棄！<br/>',NULL,11814,11814);
INSERT INTO stanza VALUES('CS242','2','來罷！來罷！<br/>我們來得這地，<br/>今日行走在基督裡。<br/>我們站住立場，<br/>一同經營這地，<br/>生命長進成熟，<br/>迎接主的再臨。<br/>',NULL,11815,11815);
INSERT INTO stanza VALUES('CS242','3','基督，基督，<br/>無比豐富肥甘！<br/>召會是基督的豐滿！<br/>我們經歷實際，<br/>顯出敬拜真意，<br/>見證那位奇妙者，<br/>使萬人歸依。<br/>',NULL,11816,11816);
INSERT INTO stanza VALUES('CS243','1','來得這地，<br/>神已將這地賜我們；<br/>平日生活，<br/>可滿基督豐富。<br/>來得這地，所需裝備，<br/>一樣不缺─寶血、<br/>見證的話、靈與召會。<br/>',NULL,11817,11817);
INSERT INTO stanza VALUES('CS243','chorus','（女聲）<br/>來得這地，<br/>哦，弟兄們哪！<br/>神賜這地給我們了。<br/>剛強去爭戰，<br/>我們必得勝！<br/>來得這地，何等榮耀！<br/>（男聲）<br/>來得這地，<br/>哦，姊妹們哪！<br/>投身其中，緊緊跟隨；<br/>祂正在呼召，<br/>祂走在前頭，<br/>所需一切祂已賜給！<br/>',NULL,11818,11818);
INSERT INTO stanza VALUES('CS243','2','我們有血，<br/>基督是無瑕疵的祭，<br/>祂捨自己，<br/>使神完全滿意；<br/>所以我們到神面前，<br/>坦然無懼，<br/>只要我們寶血不斷支取。<br/>',NULL,11819,11819);
INSERT INTO stanza VALUES('CS243','3','我們有話，<br/>神話乃是我們食物，<br/>我們用信調話並說<br/>『阿們，』在每日中，<br/>聖靈再向我們說話，<br/>祂從裡面規律調整我們。<br/>',NULL,11820,11820);
INSERT INTO stanza VALUES('CS243','4','我們有靈，<br/>這靈乃是實際的靈，<br/>不以我們的感覺作根據。<br/>內住的靈，<br/>教導我們住在祂裡，<br/>引導我們進入一切實際。<br/>',NULL,11821,11821);
INSERT INTO stanza VALUES('CS243','5','我們還有召會，<br/>她是何等寶貝！<br/>經歷豐滿，<br/>聖徒不可或缺！<br/>我們同聚必得<br/>這包羅萬有主，<br/>祂是我們一切中的一切！<br/>',NULL,11822,11822);
INSERT INTO stanza VALUES('CS244','1','行走在這美地，<br/>這使我們靈剛強！<br/>經營在這美地，<br/>享受基督無限量！<br/>祂的豐富，豐滿，<br/>並祂一切的能力，<br/>每時每刻<br/>成為我們所經所歷！<br/>祂是一切一切，<br/>我們今住在美地。<br/>',NULL,11823,11823);
INSERT INTO stanza VALUES('CS245','1','我們在美地，<br/>我們在美地！<br/>哦，阿利路亞！在美地！<br/>基督是美地，<br/>基督是美地！<br/>哦，讚美主，祂是美地！<br/>祂就是奶，祂也是蜜；<br/>五穀和油、新酒無比。<br/>我們在美地，<br/>我們在美地！<br/>哦，阿利路亞！在美地！<br/>',NULL,11824,11824);
INSERT INTO stanza VALUES('CS245','2','美地之上有許多的豐富：小麥、大麥、各種果樹；<br/>有泉、源、水流，<br/>湧流到永遠，<br/>何等美地擺在眼前！<br/>為要得著地裡出產，<br/>我們天天經營無間；<br/>每逢同聚集都帶來基督─<br/>『上好』基督作為供物！<br/>',NULL,11825,11825);
INSERT INTO stanza VALUES('CS246','1','主，你是那寬闊<br/>與高超的美地，<br/>讓我們來享受，<br/>天天經營行走！<br/>活水泉源湧流，<br/>經歷釘死復活，<br/>產生新酒美果，<br/>牛羊奶蜜和油。<br/>',NULL,11826,11826);
INSERT INTO stanza VALUES('CS246','2','我們乃是活石，<br/>成為建造材料，<br/>鑿成七根柱子，<br/>完成神的目標！<br/>取用得勝基督，<br/>奮勇與敵爭戰，<br/>帶進神的國度，<br/>掌權直到永遠。<br/>',NULL,11827,11827);
INSERT INTO stanza VALUES('CS247','1','早晨我們經營，<br/>晌午我們經營，<br/>傍晚我們經營，<br/>經營不稍怠；<br/>美地出產成熟，<br/>一同歡樂收割，<br/>每逢我們聚集，<br/>禾捆都帶來。<br/>',NULL,11828,11828);
INSERT INTO stanza VALUES('CS247','chorus','禾捆都帶來，<br/>禾捆都帶來，<br/>我們喜樂滿懷，<br/>禾捆都帶來。<br/>禾捆都帶來，<br/>禾捆都帶來，<br/>我們喜樂滿懷，<br/>禾捆都帶來。<br/>',NULL,11829,11829);
INSERT INTO stanza VALUES('CS247','2','收割小麥、大麥，<br/>經歷死與復活，<br/>雖然遭受損失，<br/>舊人也被埋；<br/>但在復活裡面，<br/>經歷豐盛生命。<br/>每逢我們聚集，<br/>禾捆都帶來。<br/>',NULL,11830,11830);
INSERT INTO stanza VALUES('CS247','3','葡萄酒、無花果、<br/>石榴與橄欖油，<br/>舒暢、甘美、<br/>豐盛、高貴又可愛；<br/>公牛、羔羊贖罪，<br/>奶蜜豐富甘甜─<br/>上好十分之一，<br/>禾捆都帶來。<br/>',NULL,11831,11831);
INSERT INTO stanza VALUES('CS301','1','耶穌！我愛你，<br/>你愛來吸引，<br/>使我渴慕親近你，<br/>快跑跟隨你。<br/>使我渴慕親近你，<br/>快跑跟隨你。<br/>你是我良人，<br/>哦，全然美麗可愛，<br/>我心朝夕依依戀戀的。<br/>你是我良人，<br/>哦，全然美麗可愛，<br/>我心中所依依戀戀的。<br/>',NULL,11832,11832);
INSERT INTO stanza VALUES('CS301','2','你愛，主耶穌，<br/>比酒更甜美，<br/>你膏油所發香氣，<br/>使我心歡喜。<br/>你膏油所發香氣，<br/>使我心歡喜。<br/>你是園中泉，<br/>你又是活水的井，<br/>流自利巴嫩山的溪澗。<br/>你是園中泉，<br/>你又是活水的井，<br/>流自利巴嫩山的溪澗。<br/>',NULL,11833,11833);
INSERT INTO stanza VALUES('CS301','3','來罷，我良人，<br/>同到園子裡，<br/>使其中各種香氣，<br/>發出並漫溢。<br/>使其中各種香氣，<br/>發出並漫溢。<br/>『我新婦妹子，<br/>我到了我的園子，<br/>盡情享受酒奶和蜂蜜。<br/>我新婦妹子，<br/>我到了我的園子，<br/>盡情享受酒奶和蜂蜜。』<br/>',NULL,11834,11834);
INSERT INTO stanza VALUES('CS301','4','把我，主耶穌，<br/>銘刻你心上，<br/>嫉恨殘忍如陰間，<br/>愛如死堅強。<br/>嫉恨殘忍如陰間，<br/>愛如死堅強。<br/>眾水不能滅，<br/>大水也不能淹沒，<br/>你的愛情無何能替換。<br/>眾水不能滅，<br/>大水也不能淹沒，<br/>你的愛情無何能替換。<br/>',NULL,11835,11835);
INSERT INTO stanza VALUES('CS302','1','你名如同倒出香膏，<br/>耶穌，耶穌，<br/>耶穌，耶穌，<br/>你名如同倒出香膏，<br/>你名如同倒出香膏。<br/>',NULL,11836,11836);
INSERT INTO stanza VALUES('CS302','2','你的愛情比酒更美<br/>………<br/>',NULL,11837,11837);
INSERT INTO stanza VALUES('CS302','3','所以眾童女都愛你<br/>………<br/>',NULL,11838,11838);
INSERT INTO stanza VALUES('CS302','4','我的良人你甚可愛<br/>………<br/>',NULL,11839,11839);
INSERT INTO stanza VALUES('CS302','5','我已尋見我心所慕<br/>………<br/>',NULL,11840,11840);
INSERT INTO stanza VALUES('CS302','6','我拉住祂不容祂走<br/>………<br/>',NULL,11841,11841);
INSERT INTO stanza VALUES('CS302','7','我的良人願你快來<br/>………<br/>',NULL,11842,11842);
INSERT INTO stanza VALUES('CS303','1','多次我曾床上躺臥，<br/>尋找我多年心所至愛，<br/>我尋找祂，卻尋不著，<br/>迫我各處遊行。<br/>弟兄們哪，請你告訴我，<br/>我心所愛現今在何處，<br/>我好前去把祂帶回，<br/>再讓我享受祂的愛情。<br/>是你們來將我引領，<br/>我纔能得著真實交通；<br/>原來我愛就在身邊，<br/>從來不曾遠離。<br/>',NULL,11843,11843);
INSERT INTO stanza VALUES('CS303','2','為何我能成你心愛，<br/>滿帶著聖靈猶如煙柱，<br/>能效法你的死，復活，<br/>沒藥乳香顯出。<br/>為何我能成為你華轎，<br/>讓你能藉我行動安息，<br/>我怎能如勇士持刀，<br/>為你防備夜間的襲擊。<br/>是因多人巡邏殷勤，<br/>我能在其中得以安穩；<br/>是因你那無量愛情，<br/>琢磨使我成形。<br/>',NULL,11844,11844);
INSERT INTO stanza VALUES('CS303','3','哦，我渴慕往沒藥山，<br/>好讓我一切全置死地，<br/>可否帶我往乳香崗，<br/>直至黑影飛去。<br/>你既稱我是全然美麗，<br/>你既享受我至美愛情，<br/>我的眼目奪取你心，<br/>我膏油勝過一切香品。<br/>我就願意從利巴嫩，<br/>經歷你那升天的超越，<br/>我也願意常住黑門，<br/>誇耀十架得勝。<br/>',NULL,11845,11845);
INSERT INTO stanza VALUES('CS303','4','哦，願我唇中常滴蜜，<br/>叫你享受愛情的甜蜜，<br/>哦，願我生活滿香氣，<br/>芬芳如利巴嫩。<br/>哦主，我願你快快前來，<br/>我的全人都歸你佔有，<br/>關鎖的園，禁閉的井，<br/>完全封閉給你的泉源。<br/>北風南風快快興起，<br/>使我心園能發出香氣，<br/>引我良人進祂園內，<br/>享受祂的所有。<br/>',NULL,11846,11846);
INSERT INTO stanza VALUES('CS304','1','我屬我的良人，<br/>祂也是戀慕我。<br/>來罷，我們同往田間去；<br/>我們要在愛裡，<br/>同在村莊住宿，<br/>享受你我之間愛情。<br/>',NULL,11847,11847);
INSERT INTO stanza VALUES('CS304','2','我們早晨起來，<br/>同往葡萄園去，<br/>同享受我們勞苦果實；<br/>葡萄是否開花，<br/>石榴是否放蕊，<br/>我在那裡將愛給你。<br/>',NULL,11848,11848);
INSERT INTO stanza VALUES('CS304','3','風茄是在放香，<br/>新陳果子佳美，<br/>良人哪！這是為你存留；<br/>我的愛都歸你，<br/>也把你全享受，<br/>因愛情是如死堅強。<br/>',NULL,11849,11849);
INSERT INTO stanza VALUES('CS305','1','主耶穌，<br/>你美麗奪了我心，<br/>我全心向你完全敞開；<br/>釋放我，<br/>脫離宗教的義務，<br/>只讓我永遠享你同在。<br/>當我在此注視你的榮耀，<br/>我的心充滿了你榮耀；<br/>浸透我，主，<br/>我今懇切求禱，<br/>以你靈與我靈永相調。<br/>',NULL,11850,11850);
INSERT INTO stanza VALUES('CS305','2','光照者─<br/>我的天何等明亮，<br/>我看見人子在寶座上；<br/>聖別者，<br/>以神的火焰燒我，<br/>直等我因你灼灼發亮！<br/>主，當我初次<br/>看見你榮耀，<br/>自愛與誇耀同歸羞慚；<br/>今我心湧出愛戴與頌讚，<br/>品嚐你名裡一切肥甘。<br/>',NULL,11851,11851);
INSERT INTO stanza VALUES('CS305','3','寶貝主，<br/>我將真哪噠香膏，<br/>為你愛，欣然打破傾倒，<br/>我的主，<br/>我前來膏你的頭，<br/>看哪，主，<br/>為你我獻上好。<br/>親愛主，<br/>我甘願為你枉費，<br/>愛著你，我深處就滿足。<br/>為著你，<br/>貴重油我早豫備，<br/>要將愛從心深處倒出。<br/>',NULL,11852,11852);
INSERT INTO stanza VALUES('CS305','4','良人哪，<br/>快來到香草山上，<br/>我切慕與你早面對面。<br/>主，請喝<br/>我心所流出之泉，<br/>我巴望永遠在你身邊。<br/>我並非單獨的來愛你，<br/>主，乃是與<br/>眾聖作你新婦；<br/>快來罷，<br/>我們愛已經久等，<br/>主耶穌，願意你得滿足。<br/>',NULL,11853,11853);
INSERT INTO stanza VALUES('CS306','1','耶穌，耶穌，<br/>可否容我向你訴，<br/>你名對我如此豐富，<br/>我愛耶穌。<br/>',NULL,11854,11854);
INSERT INTO stanza VALUES('CS307','1','有一個名我愛聽見，<br/>我愛唱牠價值；<br/>猶如音樂美妙甘甜，<br/>地上無名如此。<br/>',NULL,11855,11855);
INSERT INTO stanza VALUES('CS307','chorus','我何等愛耶穌，<br/>我何等愛耶穌，<br/>我何等愛耶穌，<br/>因為祂先愛我。<br/>',NULL,11856,11856);
INSERT INTO stanza VALUES('CS307','2','這名說出救主的愛，<br/>祂死使我自由；<br/>祂的寶血已流出來，<br/>神前說出美言。<br/>',NULL,11857,11857);
INSERT INTO stanza VALUES('CS307','3','這名說出我父為我，<br/>每日所有部署；<br/>眼前道路雖然陰暗，<br/>陽光終必照出！<br/>',NULL,11858,11858);
INSERT INTO stanza VALUES('CS307','4','這名說出祂心有愛，<br/>知我深處愁苦；<br/>每一憂傷祂都擔代，<br/>地上無人同負。<br/>',NULL,11859,11859);
INSERT INTO stanza VALUES('CS308','1','主，每代你有一人：<br/>如朋友，亞伯拉罕；<br/>呼喊者，如撒母耳；<br/>又如大衛，滿了頌讚，<br/>但你要得一班。<br/>',NULL,11860,11860);
INSERT INTO stanza VALUES('CS308','2','主，我們巴望就是<br/>服事你的那一班；<br/>洗你腳，合你需要，<br/>使你舒暢，令你心歡，<br/>作你密友良伴，<br/>無所不談…<br/>',NULL,11861,11861);
INSERT INTO stanza VALUES('CS308','chorus','我們要頌讚，<br/>我們要呼喊，<br/>一心轉向你，<br/>讓你來掌管，<br/>專一的愛你，<br/>一直愛到底，<br/>願此情不移。<br/>',NULL,11862,11862);
INSERT INTO stanza VALUES('CS308','3','主，你的豐盛憐憫，<br/>向我們毫不吝惜！<br/>我們是團體新人，<br/>為著你的永遠旨意，<br/>只望能愛到底，<br/>堅定不移……<br/>',NULL,11863,11863);
INSERT INTO stanza VALUES('CS309','1','哦，我主！<br/>我將自己給你，<br/>你外我無出路，<br/>世界已經消逝。<br/>這世代都臥惡者手中，<br/>但我屬我的父，<br/>祂愛供我所需。<br/>',NULL,11864,11864);
INSERT INTO stanza VALUES('CS309','chorus','主，我今將自己<br/>完全給你，<br/>生命的流我願時刻經歷；<br/>耶穌，耶穌，<br/>耶穌，耶穌，耶穌，<br/>我全心愛你，<br/>真正的愛你。<br/>',NULL,11865,11865);
INSERT INTO stanza VALUES('CS309','2','我羨慕你從我心流出，<br/>我心永遠不能<br/>裝你之外事物。<br/>我深處時刻向你呼求，<br/>滿帶飢渴羨慕，<br/>從我甜美流出。<br/>',NULL,11866,11866);
INSERT INTO stanza VALUES('CS309','3','你的光天天照在我身，<br/>參透虛假屬靈，<br/>使我不再受欺。<br/>我深知我需你的光照，<br/>若無你光照亮，<br/>我怎能屬於你。<br/>',NULL,11867,11867);
INSERT INTO stanza VALUES('CS309','4','潔淨我，不讓一罪存留，<br/>願我天天改變，<br/>讓你生命有路；<br/>我求你赦免我罪軟弱，<br/>使我裡外清潔，<br/>活水湧流無阻。<br/>',NULL,11868,11868);
INSERT INTO stanza VALUES('CS309','5','何喜樂，享受生命平安，<br/>有主甜美同在，<br/>死亡毫無蹤跡；<br/>何喜樂，生命交通甜蜜，<br/>我覺即使在天，<br/>也不能彀相匹。<br/>',NULL,11869,11869);
INSERT INTO stanza VALUES('CS309','chorus','主，我今將自己<br/>完全給你，<br/>生命的流使我讚美不已；<br/>耶穌，耶穌，<br/>耶穌，耶穌，耶穌，<br/>我全心愛你，<br/>真正的愛你。<br/>',NULL,11870,11870);
INSERT INTO stanza VALUES('CS310','1','何等快樂日，<br/>當我已經別無他途，<br/>當主奪取我心，<br/>從無邊黑暗<br/>進入祂光明的國度。<br/>',NULL,11871,11871);
INSERT INTO stanza VALUES('CS310','2','我新生開始，<br/>這新生命是神愛子，<br/>我不再為幻夢<br/>而如醉如癡；<br/>因活泉湧流我深處！<br/>',NULL,11872,11872);
INSERT INTO stanza VALUES('CS310','3','當我轉向祂，<br/>祂就供應祂的生命，<br/>祂生命成為<br/>我人生的實際，<br/>哦，阿利路亞在我裡！<br/>',NULL,11873,11873);
INSERT INTO stanza VALUES('CS310','4','我單單愛你，<br/>其他的愛求你燒去，<br/>從現今到永遠，<br/>你是我生命，<br/>你是我一切的一切。<br/>',NULL,11874,11874);
INSERT INTO stanza VALUES('CS311','1','沉醉在你愛裡，<br/>滋潤新鮮，<br/>讓你愛來浸透，<br/>遠比蜂蜜甘甜！<br/>你愛緊握我手，<br/>引我前行，<br/>我時依你胸臆，<br/>飽嘗你愛情。<br/>我切慕，哦主，<br/>筵宴你愛裡，<br/>讓你愛將我遮蔽。<br/>你以愛為旌旗─<br/>你的自己，<br/>你的愛原與你為一。<br/>',NULL,11875,11875);
INSERT INTO stanza VALUES('CS311','2','你是我至寶愛，<br/>獨一的你；<br/>你是我愛對象，<br/>是的，是你自己。<br/>若你僅賜救贖，<br/>和你愛情；<br/>你知這都不能<br/>滿足我心靈。<br/>我切慕，哦主！<br/>得著你自己；<br/>我深知一切是你。<br/>滿帶愛情的你，<br/>我所追求；<br/>我惟一的至寶是你。<br/>',NULL,11876,11876);
INSERT INTO stanza VALUES('CS312','1','當我浸透在祂愛裡，<br/>追求思慮盡消失；<br/>祂愛四圍把我覆庇，<br/>引我失去在祂裡。<br/>當我瞻仰祂的榮美，<br/>發光的臉何可親；<br/>我就不禁湧出愛情，<br/>與祂聯結再不分。<br/>當我浸透在祂愛裡，<br/>追求思慮盡消失；<br/>祂愛四圍把我覆庇，<br/>引我失去在祂裡。<br/>',NULL,11877,11877);
INSERT INTO stanza VALUES('CS312','2','當我們同活祂愛裡，<br/>彼此交通又相依；<br/>祂愛是我們的聯繫，<br/>『愛』使我們永不離。<br/>當祂愛圍繞著我們，<br/>相親相惜何甜蜜；<br/>我們就同活在愛裡，<br/>心心相聯在一起。<br/>當我們同活在祂愛裡，<br/>彼此交通又相依；<br/>祂愛是我們的聯繫，<br/>『愛』使我們永不離。<br/>',NULL,11878,11878);
INSERT INTO stanza VALUES('CS313','1','前我曾多次呼求主耶穌，<br/>但是從未這樣<br/>實際的摸著我主，<br/>不知為何故忽見祂丰采，<br/>哦我的主耶穌，我愛你！<br/>',NULL,11879,11879);
INSERT INTO stanza VALUES('CS313','2','世上的事物我已不再屬，<br/>我已得著這位<br/>可愛的生命救主，<br/>讓萬事逝去，只要我能彀<br/>天天在召會中來愛你。<br/>耶穌！奇妙的耶穌！<br/>是我何等的救主。<br/>哦主，願我愛全歸你，<br/>天天歡喜快樂地<br/>享受你實際！<br/>（重複）<br/>',NULL,11880,11880);
INSERT INTO stanza VALUES('CS314','1','我們與愛的耶穌<br/>彼此享受何快樂，<br/>我們湧起愛意<br/>向著愛主唱歌，<br/>向著愛主唱新歌。<br/>從祂我們得平安，<br/>因祂我們享自由；<br/>祂是我們救主，<br/>又是我們生命，<br/>與我們永遠合一！<br/>（一至三行重覆一次）<br/>耶穌，耶穌，<br/>你名何富有！<br/>我們捆綁全脫落，<br/>靈裡釋放唱新歌，<br/>阿利路亞向你唱新歌。<br/>',NULL,11881,11881);
INSERT INTO stanza VALUES('CS315','1','每日單單地愛主，<br/>愛祂經過風暴路，<br/>愛祂雖然信微弱，<br/>一切在於愛耶穌！<br/>',NULL,11882,11882);
INSERT INTO stanza VALUES('CS315','chorus','愛祂當時辰飛逝，<br/>愛祂當日子流去；<br/>愛祂無論何事臨，<br/>一切在於愛耶穌！<br/>',NULL,11883,11883);
INSERT INTO stanza VALUES('CS315','2','主靈照耀何明亮，<br/>進我微小的這心，<br/>當祂引導我穩固，<br/>一切在於愛耶穌！<br/>',NULL,11884,11884);
INSERT INTO stanza VALUES('CS315','3','歌唱當我景晴朗，<br/>禱告當我路崎嶇，<br/>驚險臨到我呼求，<br/>一切在於愛耶穌！<br/>',NULL,11885,11885);
INSERT INTO stanza VALUES('CS315','4','愛祂直到今生過，<br/>愛祂直到地消逝，<br/>愛祂直到祂回來，<br/>一切在於愛耶穌！<br/>',NULL,11886,11886);
INSERT INTO stanza VALUES('CS316','1','恩主，你是我至愛，<br/>我的愛情都歸你，<br/>當你愛充滿我心，<br/>我在愛裡得安息。<br/>主，我愛你的自己，<br/>不是你所作所賜，<br/>無一能與你相匹，<br/>我今歡樂的愛你。<br/>',NULL,11887,11887);
INSERT INTO stanza VALUES('CS316','chorus','主，我曾享受許多事物，<br/>但我現今歡然全丟棄；<br/>我不再愛戀別的事物，<br/>我將上好愛情歸你。<br/>',NULL,11888,11888);
INSERT INTO stanza VALUES('CS316','2','有何能使我眷戀，<br/>若非你作牠實際；<br/>我心單純的祈求，<br/>只望全人充滿你。<br/>恩主，你是我至愛，<br/>我的愛情都歸你，<br/>當你愛充滿我心，<br/>我在愛裡得安息。<br/>',NULL,11889,11889);
INSERT INTO stanza VALUES('CS317','chorus','直等到<br/>我進了神的聖所裡面，<br/>纔看出他們的結局。<br/>直等到<br/>我進了神的聖所裡面，<br/>纔看出他們的結局。<br/>惡人和狂傲人<br/>反倒享平安；<br/>至於我，我腳幾乎失閃；<br/>我思索不明白，<br/>眼看實為難！<br/>（接上面副歌）<br/>',NULL,11890,11890);
INSERT INTO stanza VALUES('CS317','1','你實在把他們<br/>安置在滑地，<br/>使他們掉在沉淪之中，<br/>他們所誇口的<br/>轉眼便成空。<br/>',NULL,11891,11891);
INSERT INTO stanza VALUES('CS317','chorus','因而我的心裡發酸，<br/>肺腑被刺，<br/>我竟這樣愚昧無知。<br/>（重複最後兩行，下同）<br/>',NULL,11892,11892);
INSERT INTO stanza VALUES('CS317','2','除你外，<br/>在天上我豈有誰呢？<br/>在地上我也無所愛慕；<br/>你是我的力量<br/>和永遠之福！<br/>',NULL,11893,11893);
INSERT INTO stanza VALUES('CS317','chorus','你攙著我右手，<br/>以你訓言引導，<br/>以後必接我到榮耀。<br/>',NULL,11894,11894);
INSERT INTO stanza VALUES('CS318','1','當頭一次遇見了你，<br/>我的心充滿歡喜。<br/>阿利路亞，喜樂滿溢，<br/>主耶穌充滿在我裡。<br/>頭一次的愛，<br/>最甘甜的愛，<br/>耶穌，耶穌，我的愛。<br/>超過一切真實的愛，<br/>竟然臨及我；<br/>甘甜的愛，最真實的愛，<br/>耶穌，耶穌，我的愛。<br/>',NULL,11895,11895);
INSERT INTO stanza VALUES('CS319','1','你，你，你常在我心中，<br/>夢，夢，夢裡縈繞；<br/>你，你，你愛情何其甜，<br/>你是比一切都好。<br/>耶穌！耶穌！<br/>你是比一切都好。<br/>耶穌！耶穌！<br/>你是比一切都好。<br/>',NULL,11896,11896);
INSERT INTO stanza VALUES('CS319','2','愛，愛，愛是豐盛無邊，<br/>甜，甜，甜過蜂蜜；<br/>流，流，流遍我的心田，<br/>飽嘗你愛情新鮮。<br/>耶穌！耶穌！<br/>飽嚐你愛情新鮮。<br/>耶穌！耶穌！<br/>飽嚐你愛情新鮮。<br/>',NULL,11897,11897);
INSERT INTO stanza VALUES('CS320','1','因著你將我吸引，<br/>我纔能跟隨緊緊，<br/>知你是包容無限，<br/>我一生經歷不盡。<br/>你好似美麗鳳仙，<br/>顯在荒野的世間，<br/>又好像馨香沒藥，<br/>珍藏在我的胸懷。<br/>哦，願你聽我輕訴，<br/>從此後我無別主，<br/>你豐富給我享受，<br/>你生命使我成熟。<br/>',NULL,11898,11898);
INSERT INTO stanza VALUES('CS321','1','我怎能離開主，<br/>怎能將主忘記，<br/>當主愛情依依，<br/>在我胸臆；<br/>萬事都要逝去，<br/>只有愛永不移，<br/>除了主還有誰，<br/>使我歸依。<br/>',NULL,11899,11899);
INSERT INTO stanza VALUES('CS321','2','我怎能離開主，<br/>怎能將主忘記，<br/>當祂愛的泉源，<br/>湧流我裡；<br/>將我全人浸透，<br/>使我全人復甦，<br/>除了主還有誰，<br/>使我歸依。<br/>',NULL,11900,11900);
INSERT INTO stanza VALUES('CS322','1','我今是單純敞開我心，<br/>主耶穌來進入，<br/>我今是單純敞開我心，<br/>主耶穌來進入。<br/>',NULL,11901,11901);
INSERT INTO stanza VALUES('CS322','2','我只望單單純純愛你，<br/>求你住我心內。<br/>我只望單單純純愛你，<br/>求你住我心內。<br/>',NULL,11902,11902);
INSERT INTO stanza VALUES('CS322','3','主你是活活潑潑人位，<br/>時刻活在我裡。<br/>主你是活活潑潑人位，<br/>時刻活在我裡。<br/>',NULL,11903,11903);
INSERT INTO stanza VALUES('CS322','4','現在我在靈中享受你，<br/>藉你生命而活。<br/>現在我在靈中享受你，<br/>藉你生命而活。<br/>',NULL,11904,11904);
INSERT INTO stanza VALUES('CS322','5','安息的『阿們』你，<br/>主耶穌，你佔有我全人。<br/>安息的『阿們』你，<br/>主耶穌，你佔有我全人。<br/>',NULL,11905,11905);
INSERT INTO stanza VALUES('CS323','1','轉，轉，我轉向你，<br/>主，我承認我空虛無比；<br/>轉，轉，流浪的心，<br/>只能滿足於你愛情！<br/>',NULL,11906,11906);
INSERT INTO stanza VALUES('CS323','chorus','主耶穌！我呼求你，<br/>你是我惟一所需。<br/>',NULL,11907,11907);
INSERT INTO stanza VALUES('CS323','2','厚，厚，祂賜恩典，<br/>呼求祂的，必嘗祂甘甜；<br/>厚，厚，祂恩待你，<br/>從今到永遠，主不變。<br/>',NULL,11908,11908);
INSERT INTO stanza VALUES('CS323','3','愛，愛，基督的愛，<br/>如同江河，滿至湧出來；<br/>愛，愛，我充滿愛，<br/>瘋狂的充滿主的愛。<br/>',NULL,11909,11909);
INSERT INTO stanza VALUES('CS324','1','每當你向我敞開胸襟，<br/>我的心立刻起共鳴。<br/>你慈手撫我身，<br/>我就立刻能對你訴衷情，<br/>如何能傾訴得盡，<br/>如何能傾訴得盡。<br/>',NULL,11910,11910);
INSERT INTO stanza VALUES('CS324','2','但我卻知道我的心聲，<br/>你又是何等的愛聽，<br/>我的愛語，嘆息，<br/>都能在你裡震動你情心，<br/>卻不能震動得盡，<br/>卻不能震動得盡。<br/>',NULL,11911,11911);
INSERT INTO stanza VALUES('CS324','3','主，願我向你所表情心，<br/>都能經你手的煉淨，<br/>使我全人全心，<br/>全都注於你，<br/>經歷你愛情，<br/>至終能經歷得盡，<br/>至終能經歷得盡。<br/>',NULL,11912,11912);
INSERT INTO stanza VALUES('CS325','1','從我心湧出了音樂，<br/>流向我愛，<br/>祂曾為我捨己。<br/>我怎能轉臉不向你，<br/>當我浸潤在你不移愛裡。<br/>享受何豐富，<br/>生命何實際，<br/>喜樂何洋溢，<br/>哦主，得我全心！<br/>得我心，也得我全人，<br/>恩主，<br/>我不得不將我給你。<br/>',NULL,11913,11913);
INSERT INTO stanza VALUES('CS325','2','從那日，當我遇見你，<br/>我怎能不深深墜入愛裡；<br/>我曾是虛空又憂鬱，<br/>世上無一情愛能使我依。<br/>直至有一日，<br/>我敞開我心，<br/>你愛得流入，<br/>充滿我心深處！<br/>我今知，主！你我合一，<br/>這使我不得不將我給你。<br/>恩主！<br/>我不得不將我給你！<br/>',NULL,11914,11914);
INSERT INTO stanza VALUES('CS326','1','哦，是你愛來遇見我們，<br/>當我們正墮落罪惡境；<br/>哦，是你愛將我們吸引，<br/>使我們能得著新生命。<br/>何奇妙，是你的愛<br/>賜給我們更新的一生。<br/>哦，是你愛改變我石心，<br/>當我對你冷酷又堅硬；<br/>哦，是你愛賜給我新心，<br/>使我向你依依不再分。<br/>',NULL,11915,11915);
INSERT INTO stanza VALUES('CS326','2','是你的愛，天天來扶持，<br/>使我們能不斷向前行；<br/>是你的愛，時刻來供應，<br/>使我們能脫離幻夢境。<br/>何奇妙，是你的愛，<br/>成為我們行走的能力。<br/>是你的愛，使你將自己，<br/>化成為靈，住在我靈裡；<br/>是你的愛，在我心運行，<br/>我纔能彀渴慕來經營。<br/>',NULL,11916,11916);
INSERT INTO stanza VALUES('CS326','3','是你的愛，作工在我身，<br/>琢磨不斷好使我成形；<br/>是你的愛，量給我處境，<br/>好使我能破碎流生命。<br/>何奇妙，是你的愛，<br/>在我心裡多面的作為；<br/>為何我能安家在召會？<br/>無非因你愛裡的花費！<br/>為何我能享受在家裡？<br/>無非因你愛手的實際！<br/>',NULL,11917,11917);
INSERT INTO stanza VALUES('CS326','4','是你的愛，使我能變化，<br/>藉著瓦器彰顯你榮華；<br/>是你的愛，賜給我盼望，<br/>立刻被提變成你形像。<br/>何奇妙，是你的愛，<br/>使我改變，催促你歸回。<br/>主，我實在不知、也不會<br/>細細述說你愛的寶貴；<br/>求你澆我，浸透你愛裡，<br/>使我餘生失去在你裡。<br/>',NULL,11918,11918);
INSERT INTO stanza VALUES('CS327','1','主阿！我愛你，<br/>我實在深愛你，<br/>無你活著枉然、失意。<br/>你是富有吸引，<br/>極其引人著迷，<br/>你的豐富追測不盡。<br/>我主名何甜蜜，<br/>呼求叫人滿意，<br/>主，你屬我；<br/>主，我也屬你。<br/>聯結調和於你，<br/>神人合併為一，<br/>豫嘗新耶路撒冷實際。<br/>註：此首詩辭採自李常受弟兄一九九七年離世前不久的禱告。<br/>',NULL,11919,11919);
INSERT INTO stanza VALUES('CS328','1','怎能鄉村女子如我，<br/>成為你的新婦、配偶？<br/>你是如此聖潔、神聖，<br/>我卻墮落、屬人。<br/>若非是你，我怎得以<br/>在這羅曼史裡像你？<br/>在創世前，我蒙揀選，<br/>你計畫永不變！<br/>（副一）<br/>神聖羅曼史，<br/>神心計畫之；<br/>神成為卑微人子，<br/>追求鄉村女子！<br/>神永遠的愛，<br/>無何能妨礙，<br/>亦無何能以更改，<br/>神終得心所愛！<br/>',NULL,11920,11920);
INSERT INTO stanza VALUES('CS328','2','世人、天使未曾知悉，<br/>隱藏在你心中祕密；<br/>創世之前，你已定意：<br/>與人聯調為一！<br/>因那惡者陰謀、詭計，<br/>我被罪惡敗壞至極；<br/>但無何能斷絕你愛，<br/>我終投入你懷！<br/>（回副一）<br/>',NULL,11921,11921);
INSERT INTO stanza VALUES('CS328','3','萬王之王，你竟成人，<br/>為我受死，將我拯救；<br/>在復活裡，我成童女，<br/>許配給你─我王！<br/>死而復活，你進我靈，<br/>使我得有你的神性；<br/>你我今同生命、性情，<br/>神人二性合併！<br/>（副二）<br/>因你愛吸引，<br/>我得屬於你；<br/>主，我不屬於自己，<br/>我只屬你而已。<br/>被你愛吸引，<br/>為你名所迷，<br/>我為你人位所奪；<br/>願你親嘴與我。<br/>',NULL,11922,11922);
INSERT INTO stanza VALUES('CS328','4','主，在這親密交通裡，<br/>我得與你傾心吐意；<br/>與你個人情深關係，<br/>是何等的甜蜜！<br/>逐日改變我之所是，<br/>主，佔有我全心、全志；<br/>將我全人變化、浸透，<br/>成你新婦、佳偶！<br/>（回副二）<br/>',NULL,11923,11923);
INSERT INTO stanza VALUES('CS329','1','何等喜樂，何等喜樂，<br/>我們能彀一無所有，<br/>一無所是，一無所見，<br/>惟見榮耀裡的基督；<br/>何等喜樂，何等喜樂，<br/>我們能彀一無所有，<br/>一無所是，一無所顧，<br/>惟顧祂在地權益。<br/>註：本首詩辭編譯自達祕（J. N. Darby）的話。<br/>',NULL,11924,11924);
INSERT INTO stanza VALUES('CS401','1','生命之主向我吹氣，<br/>將你活泉向我開啟，<br/>從我裡面將我推動，<br/>生命之光照我心中。<br/>',NULL,11925,11925);
INSERT INTO stanza VALUES('CS401','2','主，何希奇，你在我裡，<br/>不必天上陰間尋你，<br/>一回靈裡就得見你，<br/>靈靈接觸毫無距離。<br/>',NULL,11926,11926);
INSERT INTO stanza VALUES('CS401','3','你是我的在天中保，<br/>又是我的靈中恩膏；<br/>凡你神前為我所作，<br/>都在我靈給我摸著。<br/>',NULL,11927,11927);
INSERT INTO stanza VALUES('CS401','4','但是我心何等不忠，<br/>常雖深感仍不順從；<br/>求主眷憐、吹氣、推動，<br/>使我全人都盡功用。<br/>',NULL,11928,11928);
INSERT INTO stanza VALUES('CS401','5','當我靈裡憋氣，下沉，<br/>難將你恩向人言陳，<br/>求你從我裡面吹氣，<br/>使我完全充滿了你。<br/>',NULL,11929,11929);
INSERT INTO stanza VALUES('CS402','1','吸引、吸引，<br/>我們被吸引轉向主，<br/>再好的前途<br/>我們也不屑一顧。<br/>情願趁著現在，<br/>把上好的年歲，<br/>全然奉獻給基督與召會！<br/>',NULL,11930,11930);
INSERT INTO stanza VALUES('CS402','2','吸引、吸引，<br/>召會生活滿了豐富；<br/>從歲首到年終，<br/>神眼目常看顧，<br/>百花開放，百鳥鳴叫，<br/>滿了生命，<br/>蔭下嘗甘甜顯出祂秀美。<br/>',NULL,11931,11931);
INSERT INTO stanza VALUES('CS402','3','吸引、吸引，<br/>可愛新郎步步臨近；<br/>祂正在側身傾聽，<br/>要題我的名。<br/>有天祂要回到半空中，<br/>悄悄的，一剎那之間<br/>把我吸上去！<br/>',NULL,11932,11932);
INSERT INTO stanza VALUES('CS403','1','主耶穌！主耶穌！<br/>我渴慕摸著你！<br/>多又多，多又多，<br/>你長大在我裡。<br/>願你的生命不斷成長，<br/>『榮耀之花』盛放！<br/>叫世人看見你<br/>顯在我的身上。<br/>',NULL,11933,11933);
INSERT INTO stanza VALUES('CS404','1','可惡世界一直騙我，<br/>我還以為是好友；<br/>甚麼都還沒有到手，<br/>我心就先被騙走。<br/>害得我主苦苦巴望，<br/>想要愛我愛不著！<br/>主，我今天向你悔改，<br/>你已等得彀長久……<br/>',NULL,11934,11934);
INSERT INTO stanza VALUES('CS404','2','主，感謝你嫉妒的靈<br/>保守我單為你活。<br/>你的恩典多而又多，<br/>足彀我歡喜快樂。<br/>現在我要瘋狂愛主，<br/>愛到全心只有主！<br/>哦主、阿們，世界斷開，<br/>阿利路亞，主同在！<br/>',NULL,11935,11935);
INSERT INTO stanza VALUES('CS405','1','但他們的心幾時歸向主，<br/>帕子就幾時除去了。<br/>所以你的心終日歸向主，<br/>你的帕子就除去了。<br/>如今主就是那靈，<br/>主的靈若是在那裡，<br/>那裡就得以釋放自由。<br/>所以你的心終日歸向主，<br/>你的帕子就除去了。<br/>',NULL,11936,11936);
INSERT INTO stanza VALUES('CS406','1','更深，更深，<br/>藉著主的十架，<br/>讓我更深入；死與生命，<br/>二者連在一起，<br/>使流加深，主。<br/>哦主，我求更深，<br/>天天作工我身；<br/>遍我全人各部，<br/>直到全新於我主。<br/>',NULL,11937,11937);
INSERT INTO stanza VALUES('CS406','2','更高，更高，<br/>在主生命裡面；<br/>主，我何低淺！<br/>藉你生命我能更高，<br/>更高─更高往上面。<br/>哦主，我求更高，<br/>變化乃我需要─<br/>流中更加豐盛，<br/>惟願認識你生命。<br/>',NULL,11938,11938);
INSERT INTO stanza VALUES('CS406','3','長大，長大，<br/>主在我裡長大，<br/>一天過一天。<br/>祂今流入我的一切生活─<br/>這是祂所願。<br/>哦主，長在我裡，<br/>逐日增加不已；<br/>知識不足應付，<br/>必須長大並成熟。<br/>',NULL,11939,11939);
INSERT INTO stanza VALUES('CS406','4','生活，生活，<br/>基督是我生活，<br/>祂實際無限！<br/>小事，大事，任何事，<br/>一切事─祂都在裡面。<br/>每日活出基督，<br/>時刻將祂流露，<br/>祂名你當呼求，<br/>為得基督獻所有。<br/>',NULL,11940,11940);
INSERT INTO stanza VALUES('CS406','5','人位，人位，<br/>主是我的人位，<br/>今住在我裡。<br/>祂是我的口味，<br/>態度，動作，<br/>哦，何等希奇！<br/>主，你是我人位，<br/>安家在我心內；<br/>作我生命一切，<br/>這是何等的聯結！<br/>',NULL,11941,11941);
INSERT INTO stanza VALUES('CS406','6','召會，召會，<br/>在眾地方召會，<br/>有聖靈的流；<br/>更深，更高，<br/>基督是我生活，<br/>我被祂佔有。<br/>召會乃是基督<br/>各方面的顯出；<br/>主，我願脫自己，<br/>為著建造你身體。<br/>',NULL,11942,11942);
INSERT INTO stanza VALUES('CS406','7','建造，建造，<br/>召會得著建造，<br/>靠經歷基督；<br/>惟有如此纔會產生建造，<br/>除祂無別路。<br/>哦主，我今求告，<br/>我願被你建造，<br/>生命逐日加增，<br/>為著新耶路撒冷。<br/>',NULL,11943,11943);
INSERT INTO stanza VALUES('CS406','8','快來，快來，<br/>基督必要快來，<br/>娶祂的新婦；<br/>在召會中我們準備等候，<br/>身體得救贖。<br/>哦主，願你快來─<br/>此聲出自心懷；<br/>我們讚美不住，<br/>願你快來，主耶穌！<br/>',NULL,11944,11944);
INSERT INTO stanza VALUES('CS407','1','哦，讓我們將<br/>昨日的事丟背後，<br/>努力面前<br/>向著標竿一直跑！<br/>讓我們在流中<br/>跟隨主行動，<br/>為著主的恢復<br/>答應主呼召。<br/>',NULL,11945,11945);
INSERT INTO stanza VALUES('CS408','1','挖透我，挖透我，<br/>挖透我，<br/>挖去我心裡所有硬石頭！<br/>所有罪，皆脫落，<br/>讓生命湧流！阿利路亞！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我心裡所有硬石頭！<br/>',NULL,11946,11946);
INSERT INTO stanza VALUES('CS408','2','挖透我，挖透我，<br/>挖透我，<br/>挖去我所有虛空的幻想！<br/>所有夢，須清醒，<br/>讓生命湧流…阿利路亞！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我所有虛空的幻想！<br/>',NULL,11947,11947);
INSERT INTO stanza VALUES('CS408','3','挖透我，挖透我，<br/>挖透我，<br/>挖去所有困擾我的感情！<br/>己所愛，須撇棄，<br/>讓生命湧流…阿利路亞！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去所有困擾我的感情！<br/>',NULL,11948,11948);
INSERT INTO stanza VALUES('CS408','4','挖透我，挖透我，<br/>挖透我，<br/>挖去所有意志裡的悖逆！<br/>己所願，須平息，<br/>讓生命湧流…阿利路亞！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去所有意志裡的背逆！<br/>',NULL,11949,11949);
INSERT INTO stanza VALUES('CS408','5','挖透我，挖透我，<br/>挖透我，<br/>挖去我所有自己的追求！<br/>己所望，須撲滅，<br/>讓生命湧流…阿利路亞！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我所有自己的追求！<br/>',NULL,11950,11950);
INSERT INTO stanza VALUES('CS408','6','湧流出！讚美主！<br/>湧流出！<br/>生命從心中活泉湧流出！<br/>我的心全釋放，<br/>靈就能『讚美』…<br/>阿利路亞！湧流出！<br/>讚美主！湧流出！<br/>生命從心中活泉湧流出！<br/>?<br/>註：第六節『讚美』可換唱『禱告、』『唱詩、』『長大』…等。<br/>',NULL,11951,11951);
INSERT INTO stanza VALUES('CS409','1','有一生命比心思更深，<br/>在我靈裡可經歷，<br/>何等神聖！<br/>無限無量何奇妙，<br/>充滿了神榮耀，闊長深高<br/>過於人所能測度。<br/>這一生命乃是永活神，<br/>曾從人子耶穌身上<br/>顯出來，<br/>今成賜生命的靈，<br/>在我靈祂成長，長大成為<br/>祂所喜悅的召會。<br/>',NULL,11952,11952);
INSERT INTO stanza VALUES('CS409','chorus','哦主阿！更多來湧流！<br/>我們生活意義，<br/>你進我們裡面用意，<br/>都是為這流！<br/>主轉我，轉更多，<br/>藉著生命你纔能得著召會<br/>你心所渴慕的家。<br/>',NULL,11953,11953);
INSERT INTO stanza VALUES('CS409','2','在祂召會我們同明白，<br/>祂那豐盛生命<br/>在我們裡面；<br/>不是外面的掙扎，<br/>乃深處的平安，漫溢全人<br/>並流出活水江河。<br/>同眾聖徒我就能放膽，<br/>追求享用持定<br/>這豐盛生命；<br/>主外一切的事物，<br/>丟背後全棄絕，<br/>直到召會<br/>完全充滿神生命。<br/>',NULL,11954,11954);
INSERT INTO stanza VALUES('CS409','3','主阿！使我更深轉向你，<br/>生活行動說話<br/>工作全憑你；<br/>放棄所有老觀念，<br/>絕對照你生命，給我恩典<br/>每時每刻轉更多。<br/>當我轉到靈裡享安息，<br/>裡面的人<br/>一天比一天更新；<br/>在我全人最深處，<br/>來安家，主耶穌！<br/>深願你的同在<br/>包圍我全人。<br/>',NULL,11955,11955);
INSERT INTO stanza VALUES('CS410','1','從我靈裡深處，<br/>有生命水湧流，<br/>是三一神在我裡面流。<br/>父神乃是源頭，<br/>主基督乃是河，<br/>靈是流，分賜生命給我。<br/>',NULL,11956,11956);
INSERT INTO stanza VALUES('CS410','chorus','主，我寶貝這生命的流，<br/>我的魂生命不再保留；<br/>哦主，加深這生命的流，<br/>願你來時我生命成熟。<br/>',NULL,11957,11957);
INSERT INTO stanza VALUES('CS410','2','在鮮嫩草地上，<br/>在可安歇水邊，<br/>跟羊群的腳蹤享受主。<br/>不用勉強掙扎，<br/>徒然自討苦喫，<br/>在流裡我就全然蒙福！<br/>',NULL,11958,11958);
INSERT INTO stanza VALUES('CS410','3','藉著血我坦然<br/>進前到至聖所，<br/>活在祂面前─聯於源頭。<br/>阿利路亞，祂說，<br/>切不可離開我，<br/>當住我裡頭─一直交流。<br/>',NULL,11959,11959);
INSERT INTO stanza VALUES('CS411','1','我們可以立刻勝過仇敵，<br/>立刻勝過仇敵，<br/>立刻勝過仇敵；<br/>我們可以立刻勝過仇敵，<br/>若取用寶血。<br/>若取用寶血，<br/>若取用寶血。<br/>我們可以立刻勝過仇敵，<br/>若取用寶血。<br/>',NULL,11960,11960);
INSERT INTO stanza VALUES('CS411','2','得勝原來不在乎多屬靈，<br/>不在乎多屬靈，<br/>不在乎多屬靈；<br/>得勝原來不在乎多屬靈，<br/>乃在乎寶血。<br/>乃在乎寶血，<br/>乃在乎寶血。<br/>得勝原來不在乎屬靈，<br/>乃在乎寶血。<br/>',NULL,11961,11961);
INSERT INTO stanza VALUES('CS411','3','我們容易作正常基督徒，<br/>作正常基督徒，<br/>作正常基督徒；<br/>我們容易作正常基督徒，<br/>只要用寶血。<br/>只要用寶血，<br/>只要用寶血，<br/>我們容易作正常基督徒，<br/>只要用寶血。<br/>',NULL,11962,11962);
INSERT INTO stanza VALUES('CS411','4','靠著寶血我們恢復交通，<br/>我們恢復交通，<br/>我們恢復交通；<br/>靠著寶血我們恢復交通，<br/>不必等時間。<br/>不必等時間，<br/>不必等時間，<br/>靠著寶血我們恢復交通，<br/>不必等時間。<br/>',NULL,11963,11963);
INSERT INTO stanza VALUES('CS412','1','喫喝主的話就不萎縮，<br/>歡喜阿們，不是受強迫！<br/>在話的水裡泡，<br/>泡到全人快活；<br/>無論我們時間多難得！<br/>經常來禱讀就不退後，<br/>歡喜禱讀，不是受強迫！<br/>大家一起焚燒，<br/>燒到全人發熱；<br/>無論我們環境多難受，<br/>不退後！<br/>',NULL,11964,11964);
INSERT INTO stanza VALUES('CS413','1','『阿們』，主耶穌！<br/>『阿們』，主！<br/>是的『阿們』不停，<br/>我『阿們』你寫出的話，<br/>『阿們』整本聖經，<br/>也『阿們』你隨時的話，<br/>你知我所需要，<br/>因此我仍說：<br/>『阿們』主！<br/>無論甚麼都好。<br/>',NULL,11965,11965);
INSERT INTO stanza VALUES('CS414','1','你若要脫離世界的轄制，<br/>阿們神的話語！<br/>你若要經歷屬靈的實際，<br/>阿們神的話語！<br/>阿們神的話語！<br/>阿們神的話語！<br/>接受祂話語，<br/>一點不懷疑，<br/>阿們神的話語！<br/>',NULL,11966,11966);
INSERT INTO stanza VALUES('CS414','2','你若要脫離罪惡與自己，<br/>阿們神的話語！<br/>你若要主來更新你心意，<br/>阿們神的話語！<br/>阿們神的話語！<br/>阿們神的話語！<br/>祂話點活你，<br/>賜生命給你，<br/>阿們神的話語！<br/>',NULL,11967,11967);
INSERT INTO stanza VALUES('CS414','3','基督是美地，<br/>我們的永分，<br/>阿們神的話語！<br/>今天聽祂話，<br/>不可硬著心，<br/>阿們神的話語！<br/>阿們神的話語！<br/>阿們神的話語！<br/>祂話語分辨，<br/>如兩刃利劍，<br/>阿們神的話語！<br/>',NULL,11968,11968);
INSERT INTO stanza VALUES('CS414','4','耶穌快再來，<br/>時間已短少，<br/>阿們神的話語！<br/>你能否說你已經豫備好，<br/>阿們神的話語！<br/>阿們神的話語！<br/>阿們神的話語！<br/>不要再愚昧，<br/>以祂話裝備，<br/>阿們神的話語！<br/>',NULL,11969,11969);
INSERT INTO stanza VALUES('CS415','1','我們坦然來到施恩座，<br/>得著憐恤恩惠作幫助；<br/>不再環繞十字架敬拜，<br/>因為我主已不在彼。<br/>祂已衝破了死亡捆綁，<br/>復活升天得榮耀！<br/>現今祂從施恩寶座，<br/>用祂生命供應我。<br/>',NULL,11970,11970);
INSERT INTO stanza VALUES('CS415','2','施恩寶座雖然在天上，<br/>藉祂天梯通到我靈裡；<br/>所以我不在魂裡游蕩，<br/>時時全人轉回靈裡。<br/>耶穌是我尊榮大祭司，<br/>喜歡體恤我軟弱！<br/>我靠著祂進到神前，<br/>祂必將我救到底。<br/>',NULL,11971,11971);
INSERT INTO stanza VALUES('CS415','3','讚美耶穌是我大祭司，<br/>按著麥基洗德的等次；<br/>我今為著神利益爭戰，<br/>祂就代求供我能力。<br/>等我得勝殺敗眾仇敵，<br/>祂用餅酒供應我！<br/>何等釋放得享自由，<br/>經歷祂完全救恩！<br/>',NULL,11972,11972);
INSERT INTO stanza VALUES('CS416','1','同環繞施恩座，<br/>這是天來佳音。<br/>我們在至聖所，<br/>享受完全救恩。<br/>在靈裡面一同相聚，<br/>享受基督直到永遠，<br/>享受基督直到永遠。<br/>',NULL,11973,11973);
INSERT INTO stanza VALUES('CS416','2','同奔入至聖所，<br/>直達施恩寶座；<br/>開始於外院子，<br/>也經過了聖所。<br/>世界丟棄，罪惡消除，<br/>進入幔內，與神同住。<br/>（重複末句，下同）<br/>',NULL,11974,11974);
INSERT INTO stanza VALUES('CS416','3','贖罪祭已成了，<br/>亞倫早已過時；<br/>照著麥基洗德，<br/>基督作大祭司。<br/>更美之約，更美職事，<br/>以餅和酒，供應扶持。<br/>',NULL,11975,11975);
INSERT INTO stanza VALUES('CS416','4','基督遠在天上，<br/>我今地上居住；<br/>如何能接觸神？<br/>靈是惟一通路。<br/>在我靈裡聯著三者─<br/>神與寶座並至聖所。<br/>',NULL,11976,11976);
INSERT INTO stanza VALUES('CS416','5','我們是團體人，<br/>非流蕩基督徒；<br/>只要投入身體，<br/>勿再單獨思慮。<br/>每逢聚集，一同敞開，<br/>環繞寶座，讚美敬拜。<br/>',NULL,11977,11977);
INSERT INTO stanza VALUES('CS417','1','四周滿艱辛，<br/>無一處可安息，<br/>我心似乎消化如水；<br/>但是在深處<br/>有微聲輕輕訴，<br/>你是否真知道<br/>『祂是主』？<br/>',NULL,11978,11978);
INSERT INTO stanza VALUES('CS417','chorus','哦我心，當肅穆！<br/>祂是主，祂是主，<br/>祂是主！<br/>',NULL,11979,11979);
INSERT INTO stanza VALUES('CS417','2','試探常臨及，<br/>如花在夢中現，<br/>花容既美麗又鮮艷，<br/>生姿的微笑，<br/>招我回世界中，<br/>深處卻有聲說：<br/>『祂是主！』<br/>',NULL,11980,11980);
INSERT INTO stanza VALUES('CS417','3','全人已破碎，<br/>無一處是完整，<br/>但是黑影籠罩愈深；<br/>雙手盡伸出，<br/>卻不見何依傾，<br/>在深處卻湧出：<br/>『祂是主！』<br/>',NULL,11981,11981);
INSERT INTO stanza VALUES('CS417','4','雄心和壯志，<br/>皆已隨風而去，<br/>祂所給苦刺似過重；<br/>輕聲問我主，<br/>是否已被你棄，<br/>卻聽祂愛中說：<br/>『我是主！』<br/>',NULL,11982,11982);
INSERT INTO stanza VALUES('CS417','5','心頭滿羞慚，<br/>淚眼向心所愛─<br/>多年來祂一再賞賚，<br/>頑梗又不貞，<br/>似不能顯祂榮，<br/>釘痕手卻見證：<br/>『祂是主！』<br/>',NULL,11983,11983);
INSERT INTO stanza VALUES('CS418','1','我是小花一朵，<br/>敞開我臉；<br/>我完全轉向神，<br/>接受恩典。<br/>不知如何往前，<br/>就是這樣；<br/>一朵小百合信靠神。<br/>',NULL,11984,11984);
INSERT INTO stanza VALUES('CS418','2','地上並無一物使我羨慕；<br/>也無任何經歷讓我滿足。<br/>然而有一件事是我所求─<br/>作朵小百合，信靠神。<br/>',NULL,11985,11985);
INSERT INTO stanza VALUES('CS418','3','若當我信靠神，<br/>我卻蒙羞；<br/>若當與神同行，<br/>失去自由；<br/>這都不攪擾我，<br/>不算甚麼。<br/>我是小百合，信靠神。<br/>',NULL,11986,11986);
INSERT INTO stanza VALUES('CS418','4','看你煩惱終日，<br/>愁衣憂食；<br/>常常昧著良心，<br/>只為淘金；<br/>看你髮蒼胃潰，<br/>金銀何補？<br/>不如小百合，信靠神。<br/>',NULL,11987,11987);
INSERT INTO stanza VALUES('CS418','5','你雖知道許多，<br/>失敗如故；<br/>你雖長篇大道，<br/>不肯喊主；<br/>所以，歸根究底，<br/>有何益處？<br/>不如小百合，信靠神。<br/>',NULL,11988,11988);
INSERT INTO stanza VALUES('CS418','6','請勿以恐懼來攪擾我，<br/>何必掙扎努力，<br/>汗淚交流？<br/>簡單的信靠主，<br/>祂常相近！<br/>作朵小百合，信靠神。<br/>',NULL,11989,11989);
INSERT INTO stanza VALUES('CS418','7','我長進得不錯，<br/>別打攪我；<br/>你若滿腹牢騷，<br/>請勿嫁禍；<br/>我是寧願發光，<br/>知道不多。<br/>我是小百合，信靠神。<br/>',NULL,11990,11990);
INSERT INTO stanza VALUES('CS418','8','請勿以你罣慮，<br/>擾我清興；<br/>請勿以你苦情，<br/>強迫我聽；<br/>我們的神真大，<br/>祂甚關心！<br/>作朵小百合，信靠神。<br/>',NULL,11991,11991);
INSERT INTO stanza VALUES('CS418','9','好像我不理人，<br/>毫不在乎，<br/>其實我心深處，<br/>關懷備注！<br/>只是百合不慣悶悶不樂；<br/>我是小百合，你如何？<br/>',NULL,11992,11992);
INSERT INTO stanza VALUES('CS419','1','求主不要向我掩面，<br/>使我得以走正路；<br/>求主不斷向我顯現，<br/>使我能以盡旅途。<br/>惟有你的面光指引，<br/>我纔能放膽不畏懼；<br/>所以求主你的面光，<br/>照耀我裡常明亮。<br/>',NULL,11993,11993);
INSERT INTO stanza VALUES('CS419','2','每一舉步都是猶豫，<br/>四圍荊棘與蒺藜；<br/>每一定意都是可疑，<br/>不知你隱藏何地。<br/>惟有你的親切同在，<br/>使我能放膽往前去；<br/>所以求主：你的同在<br/>顯在我身不稍離。<br/>',NULL,11994,11994);
INSERT INTO stanza VALUES('CS419','3','當我要求你的上好，<br/>我纔認識我邪僻；<br/>當我要行你的旨意，<br/>我纔經歷無能力。<br/>惟有你的榮耀自己，<br/>使我能消失在你裡；<br/>所以求主：你的榮耀<br/>時刻吸引我離地。<br/>',NULL,11995,11995);
INSERT INTO stanza VALUES('CS419','4','求主賜我一個心志，<br/>只要得著你自己；<br/>求主賜我一個盼望，<br/>不再讓你心憂戚。<br/>哦我的主，我今求你，<br/>緊緊擁我在你懷裡；<br/>好叫你的甜美自己，<br/>成我力量我安息。<br/>',NULL,11996,11996);
INSERT INTO stanza VALUES('CS420','1','我們奔那前面的路，<br/>脫去纏累，放下重負，<br/>來望斷，來望斷，<br/>來望斷及於主。<br/>榮耀在望，歡然衝刺，<br/>主必加力，主必扶持；<br/>當望斷，當望斷，<br/>當望斷及於主。<br/>祂已經領先跑到，<br/>贏了！贏了！<br/>祂如今坐在神右邊，<br/>要帶我們進榮耀！<br/>望斷，望斷，<br/>望斷以及於耶穌，<br/>望斷，望斷，<br/>望斷以及於耶穌。<br/>',NULL,11997,11997);
INSERT INTO stanza VALUES('CS421','1','我只有一個心志，<br/>向著標竿一直跑，<br/>要得上面獎賞；<br/>背後一切都忘記，<br/>萬事也當作有損，<br/>惟有祂纔是至寶。<br/>丟棄萬事如糞土，<br/>竭力追求不稍弛，<br/>為要認識<br/>這位復活的基督。<br/>雖然四圍是艱難，<br/>要使我灰心喪膽，<br/>我知所信是誰；<br/>無論是生或是死，<br/>凡事我都能放膽，<br/>祂要在我身顯大。<br/>',NULL,11998,11998);
INSERT INTO stanza VALUES('CS422','1','向標竿，豫備，<br/>奔跑生命路；<br/>上頭獎賞來接受。<br/>放下各樣重擔<br/>和纏累的罪，<br/>屬天異象不違背，<br/>見證人圍繞著<br/>觀看我奔跑，<br/>永不退後永不倒！<br/>向標竿，豫備，<br/>奔跑生命路；<br/>上頭獎賞來接受。<br/>',NULL,11999,11999);
INSERT INTO stanza VALUES('CS423','1','向前直跑，向前直跑！<br/>標竿是萬有主；<br/>為得獎賞，別無旁顧，<br/>一直跑向基督。<br/>',NULL,12000,12000);
INSERT INTO stanza VALUES('CS423','chorus','向前跑，向前跑，<br/>向前跑！阿利路亞，<br/>要得獎賞向前跑，<br/>一直跑！為要得著基督。<br/>',NULL,12001,12001);
INSERT INTO stanza VALUES('CS423','2','向前直跑！丟棄萬事，<br/>看萬物如糞土！<br/>神的基督，榮耀獎賞，<br/>吸引我的腳步！<br/>',NULL,12002,12002);
INSERT INTO stanza VALUES('CS423','3','向前直跑！認識基督，<br/>經歷復活高超，<br/>哦，這乃是上好獎賞─<br/>若先進入榮耀！<br/>',NULL,12003,12003);
INSERT INTO stanza VALUES('CS423','4','向前直跑！只有一事：<br/>就是忘記背後，<br/>向著前頭基督直跑，<br/>向前永不回頭！<br/>',NULL,12004,12004);
INSERT INTO stanza VALUES('CS424','1','我們有當跑的路，<br/>阿利路亞！<br/>當一路跑盡，莫停下！<br/>對所有在跑的人，<br/>阿利路亞！<br/>神說：<br/>『當望斷及於祂！』<br/>',NULL,12005,12005);
INSERT INTO stanza VALUES('CS424','chorus','當望斷以及於祂！<br/>一路跑盡，莫停下！<br/>望斷一切身外物，<br/>注視耶穌，<br/>當望斷一切及於祂！<br/>',NULL,12006,12006);
INSERT INTO stanza VALUES('CS424','2','望斷周遭的事物，<br/>阿利路亞！<br/>當望斷擾嚷與掙扎；<br/>專一注視安息主，<br/>阿利路亞！<br/>當望斷一切及於祂！<br/>',NULL,12007,12007);
INSERT INTO stanza VALUES('CS424','3','望斷起伏的心緒，<br/>阿利路亞！<br/>別管你自己好或差；<br/>專一注視那標竿，<br/>阿利路亞！<br/>當望斷一切及於祂！<br/>',NULL,12008,12008);
INSERT INTO stanza VALUES('CS424','4','望斷背後的一切，<br/>阿利路亞！<br/>好或壞完全不管它；<br/>持守那位活的主，<br/>阿利路亞！<br/>當望斷一切及於祂！<br/>',NULL,12009,12009);
INSERT INTO stanza VALUES('CS424','5','專一注視祂榮臉，<br/>阿利路亞！<br/>祂是阿拉法、俄梅嘎；<br/>領受恩典向前跑，<br/>阿利路亞！<br/>當望斷一切及於祂！<br/>',NULL,12010,12010);
INSERT INTO stanza VALUES('CS425','1','曙光初現，心清靈明，<br/>與主相見在清晨，<br/>回到靈中，進入交通，<br/>何等甘甜，何等親近；<br/>祂聖名，祂恩言，<br/>是我每晨新供應；<br/>飢渴盡除，全人明亮，<br/>讚美主，恩典彀我用！<br/>',NULL,12011,12011);
INSERT INTO stanza VALUES('CS425','2','黎明即起，受主餧養，<br/>我得復興在清晨，<br/>新的照耀，新的加力，<br/>得享基督作我福分；<br/>祂慈愛，祂憐憫，<br/>每個早晨都新鮮，<br/>我全人再次得更新，<br/>憑信、愛跟隨主向前！<br/>',NULL,12012,12012);
INSERT INTO stanza VALUES('CS426','1','我們是一粒粒『麥子』，<br/>裡面含有大能的生命，<br/>經過死的破碎、限制，<br/>就要顯出復活的榮景；<br/>只要埋下，<br/>置魂生命於十架，<br/>就要結實，<br/>神的生命繁殖。<br/>我們是一粒粒『麥子』，<br/>裡面含有大能的生命，<br/>經過死的破碎、限制，<br/>就要顯出復活的榮景。<br/>',NULL,12013,12013);
INSERT INTO stanza VALUES('CS426','2','我聽主一次次招呼，<br/>今願跟隨我主的腳步，<br/>使我不再完整如故，<br/>惟願生命在我有出路；<br/>將我種下，<br/>直到復活的萌芽，<br/>結成滿穗，<br/>一粒擴增百倍。<br/>我聽主一次次招呼，<br/>今願跟隨我主的腳步，<br/>使我不再完整如故，<br/>惟願生命在我有出路。<br/>',NULL,12014,12014);
INSERT INTO stanza VALUES('CS427','1','主呼召我們在這裡，<br/>是為神永遠的經綸，<br/>這是我人生的目的，<br/>是我生活的中心！<br/>三一神化身成為人，<br/>為使人變化成為神，<br/>祂釘死、復活成為那靈，<br/>今在我靈裡作我分。<br/>',NULL,12015,12015);
INSERT INTO stanza VALUES('CS427','chorus','願神這永遠經綸異象，<br/>定住我心中每個方向，<br/>光照我，<br/>使我靈裡發旺，更剛強，<br/>好模成基督榮耀形像，<br/>在生命中作王，<br/>將聖城撒冷帶到地上。<br/>',NULL,12016,12016);
INSERT INTO stanza VALUES('CS427','2','哦，在這蒙福的境地，<br/>神與人聯調成為一，<br/>留在基督這美地裡，<br/>享受基督作實際；<br/>珍惜這無上的權利，<br/>建造主生機的身體，<br/>作基督顯身團體大器，<br/>將見證普及在各地。<br/>',NULL,12017,12017);
INSERT INTO stanza VALUES('CS427','3','站在這異象的高峰，<br/>心裡真歡欣，靈卻重：<br/>我需要復活的大能，<br/>需要真實的復興；<br/>時時照著那靈而行動，<br/>處處為那靈來撒種，<br/>成為神在地團體模型，<br/>如同主當日所實行。<br/>',NULL,12018,12018);
INSERT INTO stanza VALUES('CS427','4','我向自己死，向神活，<br/>憑調和的靈而活著，<br/>舊生命從此全擺脫，<br/>罪、肉體、世界消沒；<br/>主，我願作個得勝者，<br/>以此為目標、為警策，<br/>與眾聖徒過神人生活，<br/>同基督顯於神的國。<br/>',NULL,12019,12019);
INSERT INTO stanza VALUES('CS428','1','讓我愛而不受感戴，<br/>讓我事而不受賞賜；<br/>讓我盡力而不被人記，<br/>讓我受苦而不被人睹。<br/>只知傾酒不知飲酒，<br/>只想擘餅不想留餅；<br/>倒出生命來使人得幸福，<br/>捨棄安寧來使人得舒服。<br/>不受體恤，不受眷顧；<br/>不受推崇，不受安撫；<br/>寧可淒涼，寧可孤苦；<br/>寧可無告，寧可被負。<br/>願意以血淚<br/>作為冠冕的代價，<br/>願意受虧損<br/>來度旅客的生涯；<br/>因為當你活在這裡時，<br/>你也是如此過日子。<br/>欣然忍受一切的損失，<br/>好使近你的人得安適。<br/>我今不知前途究有多遠，<br/>這條道路<br/>一去就不再還原；<br/>所以讓我學習<br/>你那樣的完全，<br/>時常被人辜負心不生怨。<br/>求你在這慘淡時期之內，<br/>擦乾我一切暗中的眼淚；<br/>學習知道你是我的安慰，<br/>並求別人喜悅以度此歲。<br/>',NULL,12020,12020);
INSERT INTO stanza VALUES('CS429','1','主阿，在那清晨， 你去海邊等待彼得；<br/>主阿，在那正午， 你在路上等待保羅；<br/>在我的日子裡， 你忽來到我的生命。<br/>你來臨如強光， 那片光明不能抵擋；<br/>我真無法解釋， 天天疑惑，天天相信，<br/>我真無法解釋， 天天疑惑，天天相信。<br/>',NULL,12021,1);
INSERT INTO stanza VALUES('CS429','2','時走在大草原， 聽見親愛牧者柔聲；<br/>時走在山谷間， 智慧領路暫時離開；<br/>時被帶到海上， 愛我的主竟然睡著。<br/>往前的每一步， 常在冒險、驚喜之中；<br/>從來沒見過祂， 天天糢糊，天天清明，<br/>從來沒見過祂， 天天糢糊，天天清明。<br/>',NULL,12022,2);
INSERT INTO stanza VALUES('CS429','3','每天非我所願， 日子多麼富於挑戰，<br/>不許安逸、自憐， 與人同情，與人同行；<br/>祂供應生命糧、 生命活水、一切動力。<br/>帶人走出黑暗， 多少生命因此轉換；<br/>祂能力來覆庇， 天天怯場，天天強壯，<br/>祂能力來覆庇， 天天怯場，天天強壯。<br/>',NULL,12023,3);
INSERT INTO stanza VALUES('CS429','4','你許凡愛你者， 一生充滿多少矛盾，<br/>似乎不為人知， 卻是誠實，人所共知，<br/>似乎即將喪命， 卻是復活，歡呼得生。<br/>在己裡有痛楚， 在你裡面無量豐富；<br/>瓦器裡有寶貝， 天天羞辱，天天榮耀，<br/>瓦器裡有寶貝， 天天羞辱，天天榮耀。<br/>',NULL,12024,4);
INSERT INTO stanza VALUES('CS501','1','今從律法轉向基督，<br/>投靠於祂何等有福；<br/>我們既已見祂榮耀，<br/>我們只要基督！<br/>我們只要基督，<br/>我們只要基督，<br/>我們既已見祂榮耀，<br/>我們只要基督！<br/>',NULL,12025,12025);
INSERT INTO stanza VALUES('CS501','2','基督領我住神殿中，<br/>在此終日向祂歌頌；<br/>哦，阿利路亞，主同在！<br/>神殿何等可愛！<br/>神殿何等可愛，<br/>神殿何等可愛，<br/>哦，阿利路亞，主同在！<br/>神殿何等可愛！<br/>',NULL,12026,12026);
INSERT INTO stanza VALUES('CS501','3','殿再擴大就變為城，<br/>萬國所慕萬民所稱；<br/>神施行權柄的地方，<br/>在錫安聖山上。<br/>在錫安聖山上，<br/>在錫安聖山上，<br/>神施行權柄的地方，<br/>在錫安聖山上。<br/>',NULL,12027,12027);
INSERT INTO stanza VALUES('CS501','4','主從錫安要得全地，<br/>掌權並使萬民欣喜；<br/>列國要來同聲頌揚，<br/>向祂歡呼歌唱！<br/>向祂歡呼歌唱，<br/>向祂歡呼歌唱，<br/>列國要來同聲頌揚，<br/>向祂歡呼歌唱！<br/>',NULL,12028,12028);
INSERT INTO stanza VALUES('CS501','5','基督乃是殿，城，與地，<br/>成全神的永遠旨意；<br/>哦，弟兄們，為這目的，<br/>必須完全合一！<br/>必須完全合一，<br/>必須完全合一，<br/>哦，弟兄們，為這目的，<br/>必須完全合一！<br/>',NULL,12029,12029);
INSERT INTO stanza VALUES('CS502','1','當神將那被擄的帶回錫安，<br/>我們像作夢的人，<br/>滿懷感讚！<br/>我們滿口的喜笑，<br/>滿舌歡呼，<br/>神果然為我們行大事！<br/>主阿，使歸回的增多，<br/>像南地河水復流！<br/>看哪！父老們在號哭，<br/>聽哪，少年們在歡呼！<br/>如今我們<br/>一同經營並唱歌；<br/>流淚撒種的必歡呼收割。<br/>阿利路亞！<br/>將禾捆都帶回家；<br/>在錫安榮耀歸耶和華！<br/>',NULL,12030,12030);
INSERT INTO stanza VALUES('CS503','1','落到巴比倫，<br/>在被擄之地，<br/>哦主，將我們的靈激起！<br/>分散在各處，<br/>失去了合一，<br/>哦主，將我們的靈激起！<br/>激起！激起！哦主，<br/>將我們的靈激起！<br/>激起！激起！哦主，<br/>將我們的靈激起！<br/>',NULL,12031,12031);
INSERT INTO stanza VALUES('CS503','2','離開巴比倫，<br/>各宗各派之地，<br/>從分裂中我們都起來！<br/>因為巴比倫，<br/>並非神所立，<br/>從分裂中我們都起來！<br/>起來！起來！<br/>從分裂中我們都起來！<br/>（重複最後一行，下同）<br/>',NULL,12032,12032);
INSERT INTO stanza VALUES('CS503','3','從被擄之地，<br/>回耶路撒冷，<br/>有神同在，我們都上來！<br/>在獨一立場，<br/>作合一見證，<br/>有神同在，我們都上來！<br/>上來！上來！有神同在，<br/>我們都上來！<br/>',NULL,12033,12033);
INSERT INTO stanza VALUES('CS503','4','盤裡滿基督，<br/>碗裡滿聖靈，<br/>將所有的器皿都帶來！<br/>帶到召會裡，<br/>照神所命定，<br/>將所有的器皿都帶來！<br/>帶來！帶來！<br/>將所有的器皿都帶來！<br/>',NULL,12034,12034);
INSERT INTO stanza VALUES('CS503','5','在耶路撒冷，<br/>神所選之地，<br/>神的聖殿我們同建立！<br/>眾聖同事奉，<br/>都一心一意，<br/>神的聖殿我們同建立！<br/>建立！建立！<br/>神的聖殿我們同建立！<br/>註：原文裡共有五個<br/>up:Stir up<br/>',NULL,12035,12035);
INSERT INTO stanza VALUES('CS504','1','我已揀選了錫安，<br/>作我的居所。<br/>這是我永遠安息之所，<br/>我要住這裡，<br/>這是我願意的。<br/>我要使其中的糧食豐滿，<br/>使其中的窮人飽足。<br/>我要使祭司披上救恩，<br/>使聖民大聲讚美歡呼。<br/>',NULL,12036,12036);
INSERT INTO stanza VALUES('CS505','1','耶和華所救贖的民<br/>必歸回，<br/>他們要歌唱來到錫安；<br/>永遠之樂<br/>必歸到他們的頭上。<br/>他們必得歡喜快樂；<br/>或憂愁，或嘆息，<br/>盡都逃避！<br/>耶和華所救贖的民<br/>必歸回，<br/>他們要歌唱來到錫安；<br/>永遠之樂<br/>必歸到他們的頭上。<br/>',NULL,12037,12037);
INSERT INTO stanza VALUES('CS506','1','當周遊，當周遊錫安，<br/>在她的四圍旋繞；<br/>當周遊，當周遊錫安，<br/>數點她城樓多少。<br/>',NULL,12038,12038);
INSERT INTO stanza VALUES('CS506','2','哦，你心當想她堡壘，<br/>哦，你當想她牆垣，<br/>哦，你心當想她堡壘，<br/>仔細察看她宮殿。<br/>',NULL,12039,12039);
INSERT INTO stanza VALUES('CS506','3','她在北面居高華美，<br/>乃為全地所喜悅！<br/>她在北面居高華美，<br/>錫安─價值何超越！<br/>',NULL,12040,12040);
INSERT INTO stanza VALUES('CS506','4','在錫安有一道河流，<br/>具有無數的分汊，<br/>在錫安有一道河流，<br/>使這城喜樂增加。<br/>',NULL,12041,12041);
INSERT INTO stanza VALUES('CS506','5','主，錫安等候讚美你，<br/>主，錫安等候讚你，<br/>主，錫安等候讚美你，<br/>因錫安充滿了你。<br/>',NULL,12042,12042);
INSERT INTO stanza VALUES('CS506','6','耶和華在錫安為大，<br/>該受何等大讚美，<br/>祂在這城中本為大，<br/>這城地位何高貴。<br/>',NULL,12043,12043);
INSERT INTO stanza VALUES('CS506','7','哦，當從錫安稱頌神，<br/>讚美聲音不止息；<br/>哦，當從錫安稱頌神，<br/>你們凡敬畏神的。<br/>',NULL,12044,12044);
INSERT INTO stanza VALUES('CS506','8','神從錫安賜福給你，<br/>神賜福無量無限；<br/>神從錫安賜福給你，<br/>賜生命福到永遠！<br/>',NULL,12045,12045);
INSERT INTO stanza VALUES('CS506','9','看哪！何等善，何等美，<br/>弟兄們都在一起！<br/>看哪！何等善，何等美，<br/>和睦同居真合一！<br/>',NULL,12046,12046);
INSERT INTO stanza VALUES('CS506','10','當傳說給所有後代，<br/>凡願意的都可來；<br/>當傳說給所有後代，<br/>靈與新婦都說『來！』<br/>',NULL,12047,12047);
INSERT INTO stanza VALUES('CS507','1','聚集在耶路撒冷，<br/>完全脫離巴比倫，<br/>我們作合一見證，<br/>哦，願榮耀歸給神！<br/>摒棄各樣的教訓，<br/>放下一切的異議，<br/>竭力保守靈合一，<br/>在眾地方召會裡。<br/>',NULL,12048,12048);
INSERT INTO stanza VALUES('CS507','chorus','阿利路亞！阿利路亞！<br/>我們都同心合意，<br/>建造基督的身體。<br/>阿利路亞！阿利路亞！<br/>我們如今<br/>活在地方召會裡。<br/>',NULL,12049,12049);
INSERT INTO stanza VALUES('CS507','2','為使恢復能繼續，<br/>祭司體系乃所需，<br/>惟此纔蒙神稱許，<br/>哦，願榮耀歸給神！<br/>祭司神前過生活，<br/>完全被主浸透過，<br/>如此建造神居所，<br/>在眾地方召會裡。<br/>',NULL,12050,12050);
INSERT INTO stanza VALUES('CS507','3','我們眼睛須開啟，<br/>看見君王的治理，<br/>神聖權柄得建立，<br/>哦，願榮耀歸給神！<br/>為使召會得益處，<br/>先決條件要守住─<br/>完全向聖靈順服，<br/>在眾地方召會裡。<br/>',NULL,12051,12051);
INSERT INTO stanza VALUES('CS507','4','我們須就近祭壇，<br/>將一切全都奉獻，<br/>如此事奉理當然，<br/>哦，願榮耀歸給神！<br/>對此我們無爭辯，<br/>絕對擺上心甘願，<br/>召會合一得實現，<br/>在眾地方召會裡。<br/>',NULL,12052,12052);
INSERT INTO stanza VALUES('CS507','5','現今根基已立定！<br/>哦，何等榮耀顯明！<br/>我們都快樂高興，<br/>哦，願榮耀歸給神！<br/>讓我們大聲歡呼，<br/>將聲音傳到遠處，<br/>並將仇敵全滅除，<br/>在眾地方召會裡。<br/>',NULL,12053,12053);
INSERT INTO stanza VALUES('CS508','1','哦，基督有一榮耀召會，<br/>我們有分於她─<br/>何等喜樂，<br/>主使我們合為一！<br/>看哪，<br/>在宇宙中有一身體，<br/>我們屬於她─阿利路亞，<br/>主使我們合為一！<br/>阿利路亞，榮耀身體！<br/>我們是身體的肢體！<br/>一切完全為這身體！<br/>阿利路亞，<br/>主使我們合為一！<br/>',NULL,12054,12054);
INSERT INTO stanza VALUES('CS508','2','不是單獨孤立基督徒，<br/>乃是團體新人─<br/>神需要她<br/>完全彰顯祂自己！<br/>不僅是一個地方召會，<br/>乃是整個身體─<br/>阿利路亞，<br/>我們在這身體裡！<br/>阿利路亞，榮耀身體！<br/>使撒但戰抖的身體！<br/>在身體裡我們得勝！<br/>阿利路亞，<br/>我們在這身體裡！<br/>',NULL,12055,12055);
INSERT INTO stanza VALUES('CS508','3','神那完全聖別的性情，<br/>顯在七金燈臺─<br/>身體生活不容<br/>天然的存在。<br/>我們合一且有分神性，<br/>金燈臺就照耀─<br/>阿利路亞，<br/>她正發光且照耀！<br/>阿利路亞，榮耀身體！<br/>這個身體是金燈臺！<br/>處處發光，精光照耀！<br/>阿利路亞，<br/>她正發光且照耀！<br/>',NULL,12056,12056);
INSERT INTO stanza VALUES('CS508','4','我們如何彰顯這合一，<br/>聖別並且照耀？<br/>阿利路亞，<br/>喫主耶穌就是路！<br/>祂是生命樹，是嗎哪，<br/>又是常新的筵席─<br/>阿利路亞，<br/>我們天天都喫主！<br/>我們合一藉著喫主！<br/>我們聖別藉著喫主！<br/>我們發光藉著喫主！<br/>阿利路亞，<br/>喫主耶穌就是路！<br/>?<br/>註：『身體』可改唱<br/>『國度，』副歌改唱<br/>『我們是國度的子民。』<br/>',NULL,12057,12057);
INSERT INTO stanza VALUES('CS509','1','在靈裡，在靈裡，<br/>在靈裡，在靈裡，<br/>主啟示給我們<br/>何等大的奧祕！<br/>在靈裡看召會，<br/>在靈裡看世界，<br/>在靈裡看宗教，<br/>在靈裡看聖城。<br/>',NULL,12058,12058);
INSERT INTO stanza VALUES('CS509','chorus','在靈裡，在靈裡，<br/>在靈裡，在靈裡！<br/>撇世界，脫宗教，<br/>豫備新婦，主快來了！<br/>',NULL,12059,12059);
INSERT INTO stanza VALUES('CS509','2','在靈裡，<br/>我看見主眼目如火焰，<br/>我所有的隱密，<br/>完全顯露無遺。<br/>哦，主阿，我悔改！<br/>當焚燒，就焚燒；<br/>撇世界，撇乾淨，<br/>使我腳，全光明。<br/>',NULL,12060,12060);
INSERT INTO stanza VALUES('CS509','3','在靈裡，<br/>我認定那七靈和七星，<br/>七靈強，七星亮，<br/>死沉沉怎麼行？<br/>我不要搞道理，<br/>只要靈和能力；<br/>脫宗教，靈發燒，<br/>燒到強，燒到亮！<br/>',NULL,12061,12061);
INSERT INTO stanza VALUES('CS509','4','在靈裡，<br/>我保持進天國的鑰匙，<br/>藉禱讀守你話，<br/>藉呼喊尊你名，<br/>以相愛裹傷痕，<br/>以新鮮去皺紋，<br/>守冠冕，作柱子，<br/>得新名，住新城！<br/>',NULL,12062,12062);
INSERT INTO stanza VALUES('CS509','5','在靈裡說阿們，<br/>在靈裡匯一流，<br/>聖靈有新起頭，<br/>我不願再守舊；<br/>主，使我能絕對，<br/>出代價，不妥協；<br/>操練靈，釋放靈，<br/>順從靈，充滿靈！<br/>',NULL,12063,12063);
INSERT INTO stanza VALUES('CS510','1','在這啟示錄的時代，<br/>看見人子的異象；<br/>在七個金燈臺中間，<br/>祂與召會同動向。<br/>祂是神的獨一發表，<br/>是神真實的見證，<br/>召會又是祂的發表，<br/>祂的性質是精金。<br/>',NULL,12064,12064);
INSERT INTO stanza VALUES('CS510','2','主阿，你曾呼召召會，<br/>發光為你作見證；<br/>我們願意成就你意，<br/>除去所有的瑕疵。<br/>世代雖然彎曲悖謬，<br/>極其黑暗無生命，<br/>召會卻是照耀明亮，<br/>將你自己全表明。<br/>',NULL,12065,12065);
INSERT INTO stanza VALUES('CS510','3','主阿，我們喜樂讚美，<br/>召會也是你新婦；<br/>從她你能得男孩子，<br/>藉以打敗你仇敵。<br/>主，我們要作得勝者，<br/>使你權柄得恢復，<br/>世界罪惡一掃而空，<br/>地上建立你國度！<br/>',NULL,12066,12066);
INSERT INTO stanza VALUES('CS510','4','主阿，你的所是所作，<br/>全在地方召會中，<br/>自從看見召會異象，<br/>我們此心再不移，<br/>因得啟示心被吸引，<br/>渴慕奔跑到路終。<br/>為著啟示錄的異象，<br/>主阿，榮耀全歸你！<br/>',NULL,12067,12067);
INSERT INTO stanza VALUES('CS511','1','看哪，在這黑夜，<br/>眾地方召會<br/>作耶穌的見證，<br/>發出祂光輝。<br/>因基督而形成，<br/>以靈為模子，<br/>性質完全相同，<br/>彰顯出基督。<br/>',NULL,12068,12068);
INSERT INTO stanza VALUES('CS511','chorus','看哪，在這黑夜，<br/>眾地方召會<br/>憑聖靈而焚燒，<br/>發出主光輝。<br/>',NULL,12069,12069);
INSERT INTO stanza VALUES('CS511','2','神有形有體的<br/>住在基督裡；<br/>基督如今是靈，<br/>是一切實際。<br/>個個金燈臺<br/>是這靈的複製，<br/>召會在各地方<br/>一一的顯出。<br/>',NULL,12070,12070);
INSERT INTO stanza VALUES('CS511','3','行走眾召會中，<br/>是一位人子。<br/>祂穿著細麻衣，<br/>乃是大祭司！<br/>胸前束著金帶，<br/>在愛裡照顧；<br/>七星在祂手中，<br/>眾召會有路！<br/>',NULL,12071,12071);
INSERT INTO stanza VALUES('CS511','4','誰能困金燈臺？<br/>誰能來破壞？<br/>反對越發增多，<br/>牠擴展越快！<br/>環境越是黑暗，<br/>牠就越光明；<br/>因為召會乃是<br/>神生命構成。<br/>',NULL,12072,12072);
INSERT INTO stanza VALUES('CS511','5','從眾地方召會，<br/>新婦要產生，<br/>帶進榮耀聖城，<br/>新耶路撒冷。<br/>許多的金燈臺，<br/>至終成一座，<br/>彰顯三一之神，<br/>遍及全宇宙。<br/>',NULL,12073,12073);
INSERT INTO stanza VALUES('CS511','chorus','看哪，從天而降，<br/>全地都看見<br/>神的完全彰顯，<br/>到永永遠遠！<br/>',NULL,12074,12074);
INSERT INTO stanza VALUES('CS512','1','在啟示錄第二、三章，<br/>顯出七個召會真相；<br/>其中教訓為著你我，<br/>在恢復中切莫錯過。<br/>',NULL,12075,12075);
INSERT INTO stanza VALUES('CS512','2','不但她們需要細聽，<br/>我們更有留心必要；<br/>為祂旨意，主發警告，<br/>使祂召會聖潔榮耀。<br/>',NULL,12076,12076);
INSERT INTO stanza VALUES('CS512','3','對以弗所，主有呼召：<br/>起初的愛你已失去；<br/>只顧工作，卻忘了主；<br/>快快悔改，恢復當初。<br/>',NULL,12077,12077);
INSERT INTO stanza VALUES('CS512','4','必須轉向主的自己，<br/>其他的愛都要丟拋；<br/>哦讓我們聽祂呼召，<br/>切勿失去宇宙至寶。<br/>',NULL,12078,12078);
INSERT INTO stanza VALUES('CS512','5','對士每拿，受苦之子：<br/>你曾被試，但不僅此；<br/>至死忠心，不可怕死，<br/>甘願犧牲魂與身子。<br/>',NULL,12079,12079);
INSERT INTO stanza VALUES('CS512','6','忠心直到天然除淨，<br/>不能看輕一切環境；<br/>主讓牠們臨到你身，<br/>有祂美意，試你愛情。<br/>',NULL,12080,12080);
INSERT INTO stanza VALUES('CS512','7','到別迦摩，墮落更深，<br/>基督教與世界通婚；<br/>忠心的安提帕殉道，<br/>惟有他纔敢反宗教。<br/>',NULL,12081,12081);
INSERT INTO stanza VALUES('CS512','8','我們必須恐懼戰兢，<br/>小心勿與世界行淫；<br/>惟有主話，能救我們，<br/>只要對牠不斷經營。<br/>',NULL,12082,12082);
INSERT INTO stanza VALUES('CS512','9','推雅推喇跟在後面，<br/>她的能力並非屬天；<br/>細麵與酵混成一片，<br/>淫婦和獸聯成一線。<br/>',NULL,12083,12083);
INSERT INTO stanza VALUES('CS512','10','我們攙雜，求主光照，<br/>主來顯明所有假冒；<br/>除去一切或壞或好，<br/>直至絕對被你得著。<br/>',NULL,12084,12084);
INSERT INTO stanza VALUES('CS512','11','從撒狄中看得清楚，<br/>生命乃是惟一道路；<br/>她說她活，其實是死，<br/>撒狄必須接觸活主。<br/>',NULL,12085,12085);
INSERT INTO stanza VALUES('CS512','12','主，引我們摸著生命，<br/>勝過所有死的情形；<br/>脫離一切宗教背景，<br/>滿足你心，充滿生命。<br/>',NULL,12086,12086);
INSERT INTO stanza VALUES('CS512','13','非拉鐵非最終出現：<br/>應當守住她的冠冕；<br/>主名主話，弟兄相愛，<br/>如此召會，為主所愛。<br/>',NULL,12087,12087);
INSERT INTO stanza VALUES('CS512','14','弟兄姊妹完全是一，<br/>藉著生命纔有實際；<br/>單單持守祂的自己，<br/>如此通行神的旨意。<br/>',NULL,12088,12088);
INSERT INTO stanza VALUES('CS512','15','對老底嘉應當留心，<br/>她的墮落大有原因；<br/>皆因她說我富足了，<br/>卻不知道主離開了。<br/>',NULL,12089,12089);
INSERT INTO stanza VALUES('CS512','16','我們不能再像溫水，<br/>靈要火熱，一直跟隨；<br/>豐富進入生命經歷，<br/>得主稱許同祂坐席。<br/>',NULL,12090,12090);
INSERT INTO stanza VALUES('CS512','17','主阿，今天求你光照，<br/>使你道路給我看見；<br/>擦我眼睛使我富足，<br/>你的恢復快快實現。<br/>',NULL,12091,12091);
INSERT INTO stanza VALUES('CS513','1','看哪！<br/>各國各族各民各方人，<br/>身穿白衣，<br/>站在寶座和羔羊面前，<br/>大聲歡呼，<br/>救恩歸與神和羔羊，<br/>頌讚榮耀歸祂，<br/>一直到永遠！<br/>',NULL,12092,12092);
INSERT INTO stanza VALUES('CS513','2','坐寶的用帳幕覆庇我們，<br/>不再飢渴，<br/>日頭炎熱也必不傷害，<br/>因羔羊必領我們<br/>到生命水泉，神也必擦去<br/>我們一切的眼淚。<br/>',NULL,12093,12093);
INSERT INTO stanza VALUES('CS514','1','看哪！他們在各城裡，<br/>站住立場同聚集，<br/>是金燈臺照亮各地，<br/>使神有家可安息。<br/>',NULL,12094,12094);
INSERT INTO stanza VALUES('CS514','chorus','這是地方召會，<br/>是神所揀選，<br/>所有聖徒合為一；<br/>這是地方召會，<br/>是神所揀選，<br/>所有聖徒合為一。<br/>',NULL,12095,12095);
INSERT INTO stanza VALUES('CS514','2','看哪！他們正在聚會，<br/>他們聲音何響亮！<br/>弟兄姊妹踴躍分享，<br/>將主基督來顯揚。<br/>',NULL,12096,12096);
INSERT INTO stanza VALUES('CS514','3','聽哪！他們都在禱讀，<br/>將生命的話吸入，<br/>禱告，讚美，<br/>喝主，喫主，<br/>他們何等享受主！<br/>',NULL,12097,12097);
INSERT INTO stanza VALUES('CS514','4','聽哪！<br/>他們喊『主耶穌，』<br/>他們何等愛這名！<br/>當他們宣告祂是主，<br/>喜樂就越發加增。<br/>',NULL,12098,12098);
INSERT INTO stanza VALUES('CS514','5','聽哪！他們阿利路亞，<br/>聲音如大雷爆炸！<br/>阿利路亞！阿利路亞！<br/>仇敵已經被摔下！<br/>',NULL,12099,12099);
INSERT INTO stanza VALUES('CS514','6','看哪！聖徒們在移民，<br/>讚美主行動開始，<br/>召會在各城市顯明，<br/>使主快來不延遲。<br/>',NULL,12100,12100);
INSERT INTO stanza VALUES('CS514','7','看哪！主基督將要來，<br/>為祂曾捨命召會；<br/>祂今妝飾祂的心愛，<br/>作祂新婦與祂配。<br/>',NULL,12101,12101);
INSERT INTO stanza VALUES('CS514','chorus','榮耀的召會，<br/>毫無斑點皺紋，<br/>充滿了主的榮耀。<br/>榮耀的召會，<br/>毫無斑點皺紋，<br/>充滿了主的榮耀。<br/>',NULL,12102,12102);
INSERT INTO stanza VALUES('CS515','1','這是地方召會宣告：<br/>耶穌是主！<br/>所有聖徒歡樂稱呼：<br/>耶穌是主！<br/>祂已完成一切工作，<br/>撒但全軍已被征服，<br/>祂已登上榮耀寶座，<br/>耶穌是主。<br/>',NULL,12103,12103);
INSERT INTO stanza VALUES('CS515','2','如今祂是那位活靈，<br/>耶穌是主！<br/>祂今在此眾民要聽：<br/>耶穌是主！<br/>不須再有哀慟祈求，<br/>呼求祂名，祂就進入，<br/>成為你的榮耀人位，<br/>耶穌是主！<br/>',NULL,12104,12104);
INSERT INTO stanza VALUES('CS515','3','祂要變化你的生活，<br/>耶穌是主！<br/>將祂一切豐富賜你，<br/>耶穌是主！<br/>祂要不斷滿足你心，<br/>天天供應真實生命，<br/>使你與神完全結聯，<br/>耶穌是主！<br/>',NULL,12105,12105);
INSERT INTO stanza VALUES('CS515','4','因祂憐憫接納我們，<br/>耶穌是主！<br/>祂必永不撇下我們，<br/>耶穌是主！<br/>在身體中我們看見，<br/>祂的本性一切豐盛，<br/>仇敵魔鬼遠遠逃避，<br/>耶穌是主！<br/>',NULL,12106,12106);
INSERT INTO stanza VALUES('CS516','1','在地方召會中─<br/>神所揀選；<br/>在此基督作生命，<br/>聖靈有主權。<br/>（阿利路亞）<br/>在靈中，站立場，<br/>為主爭戰！<br/>我們必勝過仇敵，<br/>帶進神國度─基督作王。<br/>',NULL,12107,12107);
INSERT INTO stanza VALUES('CS517','1','基督是元首，<br/>在地方召會，<br/>在地方召會，<br/>在地方召會；<br/>基督是元首，<br/>在地方召會，<br/>基督是元首。<br/>',NULL,12108,12108);
INSERT INTO stanza VALUES('CS517','2','基督是實際，<br/>在地方召會，<br/>在地方召會，<br/>在地方召會；<br/>基督是實際，<br/>在地方召會，<br/>基督是實際。<br/>',NULL,12109,12109);
INSERT INTO stanza VALUES('CS517','3','有豐富供應，<br/>在地方召會，<br/>在地方召會，<br/>在地方召會；<br/>有豐富供應，<br/>在地方召會，<br/>有豐富供應。<br/>',NULL,12110,12110);
INSERT INTO stanza VALUES('CS517','4','我們能安家，<br/>在地方召會，<br/>在地方召會，<br/>在地方召會；<br/>我們能安家，<br/>在地方召會，<br/>家，家，甜美家。<br/>',NULL,12111,12111);
INSERT INTO stanza VALUES('CS518','1','地方召會，可愛的召會，<br/>我靈所慕，我命所歸。<br/>在祂我嘗基督的豐富，<br/>何等享受！何等滿足！<br/>當眾聖徒在愛中被建造，<br/>作神靈裡的居所，<br/>何等的美麗，<br/>何等的榮耀！<br/>地方召會，可愛的召會，<br/>我靈所慕，我命所歸。<br/>',NULL,12112,12112);
INSERT INTO stanza VALUES('CS519','1','看哪，萬民流歸這山，<br/>她被高舉超諸山。<br/>來罷，我們奔主的殿，<br/>訓誨必出於錫安！<br/>',NULL,12113,12113);
INSERT INTO stanza VALUES('CS519','chorus','哦，地方召會，<br/>主何等祝福你，<br/>恩典榮耀總不離；<br/>哦，地方召會，<br/>我何等寶愛你，<br/>我心我命全歸你！<br/>',NULL,12114,12114);
INSERT INTO stanza VALUES('CS519','2','看哪！貴重的油流淌，<br/>流到鬍鬚和衣裳。<br/>因有弟兄和睦同居，<br/>這是何等的美善！<br/>',NULL,12115,12115);
INSERT INTO stanza VALUES('CS519','3','看哪！榮耀主顯威榮，<br/>手拿七星賜七靈。<br/>使金燈臺焚燒照明，<br/>結束時代將祂迎！<br/>',NULL,12116,12116);
INSERT INTO stanza VALUES('CS520','1','老宗教敬拜和虛名，<br/>儀文和其他活動。<br/>作法、規則、無數教條，<br/>老基督教的光景！<br/>如今看見主的旨意，<br/>在地方召會彰顯，<br/>合一立場我們聚集，<br/>現今我們都活了。<br/>我們都活了！<br/>我們都活了！<br/>宗教觀念全都丟棄，<br/>活的基督尋見了。<br/>',NULL,12117,12117);
INSERT INTO stanza VALUES('CS520','2','從前願望是上天堂，<br/>天空中的『象牙塔』。<br/>雖然知道這是虛妄，<br/>我們仍是受矇蔽。<br/>在召會立場上聚集，<br/>我們已尋到實際，<br/>神的國度就是基督，<br/>今天顯在召會中。<br/>顯在召會中！<br/>顯在召會中！<br/>父神旨意不再落空，<br/>完全顯在召會中。<br/>',NULL,12118,12118);
INSERT INTO stanza VALUES('CS521','1','離開，離開老舊的背景，<br/>你若肯轉身，<br/>祂光必照耀；<br/>離開，離開死沉基督教，<br/>活的基督纔是你所需要。<br/>',NULL,12119,12119);
INSERT INTO stanza VALUES('CS521','chorus','來，來這美妙地方，<br/>是神所揀選，<br/>實現祂意旨。<br/>來，來這美妙住處，<br/>不再流蕩，<br/>可享安息、滿足。<br/>',NULL,12120,12120);
INSERT INTO stanza VALUES('CS521','2','召會，召會，<br/>在地方立場，<br/>作主金燈臺，<br/>照耀何輝煌。<br/>召會，召會，<br/>神永遠計畫，<br/>使基督安家，<br/>彰顯祂智慧。<br/>',NULL,12121,12121);
INSERT INTO stanza VALUES('CS521','3','來罷，來罷，<br/>我們來一起，<br/>作合一見證，<br/>召會得建造。<br/>來罷，來罷，<br/>一切都成了，<br/>我們元首基督在此呼召。<br/>',NULL,12122,12122);
INSERT INTO stanza VALUES('CS522','1','我們看見一道河流，<br/>就投身流中，<br/>站住地方的立場。<br/>我們看見一道河流，<br/>就投身流中，<br/>站住地方的立場。<br/>',NULL,12123,12123);
INSERT INTO stanza VALUES('CS522','chorus','我們，我們，哦主，<br/>站住地方的立場。<br/>我們，我們，哦主，<br/>站住地方的立場。<br/>',NULL,12124,12124);
INSERT INTO stanza VALUES('CS522','2','我們已經看見<br/>召會恢復的異象……<br/>',NULL,12125,12125);
INSERT INTO stanza VALUES('CS522','3','這裡乃是地方召會，<br/>非宗派公會……<br/>',NULL,12126,12126);
INSERT INTO stanza VALUES('CS522','4','我們愛所有的<br/>弟兄姊妹們，哦主……<br/>',NULL,12127,12127);
INSERT INTO stanza VALUES('CS522','5','我們蒙主呼召在此<br/>一同受訓練……<br/>',NULL,12128,12128);
INSERT INTO stanza VALUES('CS522','6','我們已被編入軍隊<br/>去為主爭戰……<br/>',NULL,12129,12129);
INSERT INTO stanza VALUES('CS522','7','我們忠心站在這裡<br/>直到主再來……<br/>',NULL,12130,12130);
INSERT INTO stanza VALUES('CS523','1','神已救我脫世界，<br/>我絕對不能再回頭；<br/>神已救我脫世界，<br/>我絕對不能再回頭！<br/>',NULL,12131,12131);
INSERT INTO stanza VALUES('CS523','chorus','不能，絕不能，<br/>我絕對不能再回頭；<br/>不能，絕不能，<br/>我絕對不能再回頭！<br/>',NULL,12132,12132);
INSERT INTO stanza VALUES('CS523','2','我已走出巴比倫……<br/>',NULL,12133,12133);
INSERT INTO stanza VALUES('CS523','3','我既找到了召會……<br/>',NULL,12134,12134);
INSERT INTO stanza VALUES('CS523','4','讚美主，我已回家……<br/>',NULL,12135,12135);
INSERT INTO stanza VALUES('CS523','5','我既摸著我的主……<br/>',NULL,12136,12136);
INSERT INTO stanza VALUES('CS523','6','基督是我的一切……<br/>',NULL,12137,12137);
INSERT INTO stanza VALUES('CS523','7','我是為神的恢復……<br/>',NULL,12138,12138);
INSERT INTO stanza VALUES('CS524','1','我們一生一定永定，<br/>阿利路亞！阿利路亞！<br/>基督召會是我永分。<br/>阿利路亞！阿利路亞！<br/>不在世界流蕩飄泊，<br/>安家在召會，<br/>享受祂豐富。<br/>阿利路亞！阿利路亞！<br/>',NULL,12139,12139);
INSERT INTO stanza VALUES('CS525','1','我們乃是為著<br/>主的召會的恢復；<br/>乃是為著地方召會<br/>在各地顯出。<br/>站住地方合一立場，<br/>在主裡合一；<br/>我們建造神的居所，<br/>完成神旨意。<br/>',NULL,12140,12140);
INSERT INTO stanza VALUES('CS525','chorus','我們為著主，<br/>我們為著主，<br/>我們為著主的恢復！<br/>我們為著主，<br/>我們為著主，<br/>為著主的恢復！<br/>',NULL,12141,12141);
INSERT INTO stanza VALUES('CS525','2','我們乃是為著<br/>主的召會的恢復；<br/>見證基督，高舉基督，<br/>帶進神國度！<br/>活在靈中，站住立場，<br/>並廣傳福音。<br/>哦，主，阿們，<br/>阿利路亞！<br/>主必快再臨！<br/>',NULL,12142,12142);
INSERT INTO stanza VALUES('CS525','3','我們乃是為著<br/>主的召會的恢復；<br/>時刻操練我們的靈，<br/>異象更清楚！<br/>大巴比倫已經傾倒，<br/>撒但被摧毀；<br/>聖城撒冷從天而降，<br/>榮耀何光輝！<br/>',NULL,12143,12143);
INSERT INTO stanza VALUES('CS526','1','神救我們<br/>脫離邪惡的世代，<br/>聚集一起為祂永遠旨意；<br/>神的兒女<br/>都該看見這異象，<br/>阿利路亞！<br/>這是神的恢復。<br/>',NULL,12144,12144);
INSERT INTO stanza VALUES('CS526','chorus','我們在各城<br/>站住地方的立場，<br/>永不倚靠自己天然力量。<br/>不再是一個信徒<br/>單獨的追求，<br/>乃是一直跟召會的水流，<br/>迎主再臨。<br/>',NULL,12145,12145);
INSERT INTO stanza VALUES('CS526','2','在流中，忘記背後，<br/>隨靈向前；棄絕宗教，<br/>將世界丟乾淨。<br/>現今主在全地<br/>不斷作新事，阿利路亞！<br/>這是神的恢復。<br/>',NULL,12146,12146);
INSERT INTO stanza VALUES('CS526','3','七倍靈─<br/>眾召會是純金燈臺，<br/>地方召會，<br/>人子顯出丰采。<br/>七燈臺在各地<br/>焚燒並照耀，阿利路亞！<br/>這是神的恢復。<br/>',NULL,12147,12147);
INSERT INTO stanza VALUES('CS526','4','主得勝，<br/>用大能建造祂召會，<br/>我們同站在祂的得勝裡。<br/>都成了！<br/>仇敵已在祂的腳下，<br/>阿利路亞！<br/>這是神的恢復。<br/>',NULL,12148,12148);
INSERT INTO stanza VALUES('CS526','5','祂生命在召會中<br/>供應無限，阿利路亞！<br/>眾召會同向前。<br/>這水流乃基督<br/>作我們實際，阿利路亞！<br/>這是神的恢復。<br/>',NULL,12149,12149);
INSERT INTO stanza VALUES('CS526','6','在召會中<br/>我們同見這異象，<br/>永不單獨，<br/>我們建造一起。<br/>同往前，<br/>在這時代作主見證，<br/>阿利路亞！<br/>這是神的恢復。<br/>',NULL,12150,12150);
INSERT INTO stanza VALUES('CS527','1','我們都是為著神的恢復，<br/>神的恢復，神的恢復。<br/>我們都是為著神的見證，<br/>神的見證，神的見證。<br/>剛強火熱的靈<br/>在焚燒我們，<br/>焚燒我們，焚燒我們。<br/>單一純潔的心，<br/>時時親近神，<br/>時時近神，時時近神。<br/>事業！前途！何屑一顧。<br/>活著只為祂的恢復。<br/>祂的恢復，祂的恢復，<br/>祂的恢復！<br/>我們是為神的恢復，<br/>神的見證！<br/>事業！前途！何屑一顧。<br/>活著只為著祂的恢復。<br/>恢復，恢復，恢復，<br/>恢復，恢復，恢復！<br/>我們是為神的恢復，<br/>神的見證！<br/>',NULL,12151,12151);
INSERT INTO stanza VALUES('CS528','1','這是時候，朋友，<br/>日子已經不多；<br/>要事奉誰，<br/>必須趁早選擇！<br/>願否同一陣線，<br/>為主奮勇爭戰，<br/>擊潰仇敵─<br/>那狡猾的撒但？<br/>',NULL,12152,12152);
INSERT INTO stanza VALUES('CS528','2','這是時候，聖徒，<br/>到處人心惶惶，<br/>撒但猖狂，<br/>遍地興風作浪。<br/>所以我們必須<br/>看萬事如糞土，<br/>不計代價，<br/>奉獻為主恢復！<br/>',NULL,12153,12153);
INSERT INTO stanza VALUES('CS528','3','這是時候，聖徒，<br/>聖靈正在運行，<br/>加速恢復，<br/>拔高純潔人性，<br/>照著祂的計畫，<br/>產生『一個新人，』<br/>藉此吸引這一代歸向神。<br/>',NULL,12154,12154);
INSERT INTO stanza VALUES('CS528','4','這是末了時日，<br/>應當出去宣告，<br/>讓人聽見國度即將來到！<br/>神的軍隊所至，<br/>仇敵一一趕出，<br/>好使全地重新歸服基督。<br/>',NULL,12155,12155);
INSERT INTO stanza VALUES('CS529','1','進入啟示錄的時代，<br/>從各宗派完全脫離；<br/>我們在眾地方召會，<br/>靈裡合一。<br/>沒有老舊宗教捆綁，<br/>個個都是發光亮星；<br/>各地召會是金燈臺，<br/>因主焚燒。<br/>主與焚燒召會，<br/>主與焚燒召會，<br/>在召會中，<br/>聖徒都是發光星！<br/>阿利路亞！阿利路亞！<br/>主，我們將命獻給你，<br/>為著在靈裡焚燒，<br/>將基督來照明。<br/>',NULL,12156,12156);
INSERT INTO stanza VALUES('CS530','1','焚燒，焚燒，<br/>日夜焚燒，<br/>不斷回到我們靈裡；<br/>為著你永遠的旨意，<br/>靈裡合一。<br/>我們站住地方立場，<br/>召會合一在此顯彰；<br/>肢體雖多，仍是一身，<br/>基督為首。<br/>',NULL,12157,12157);
INSERT INTO stanza VALUES('CS530','chorus','基督與祂召會，<br/>基督與祂召會，<br/>乃是我們<br/>一切實際和生活。<br/>阿利路亞，阿利路亞，<br/>主，我們將命獻給你，<br/>為建造你的身體，<br/>並在愛中被建立。<br/>',NULL,12158,12158);
INSERT INTO stanza VALUES('CS530','2','呼吸，呼吸，<br/>我們呼吸，<br/>每一呼吸得新氣息，<br/>何等的變化，<br/>一切陳舊全更新。<br/>呼出我們老舊自己，<br/>吸入新生命與合一，<br/>我們今吸入主耶穌，<br/>吸入生命。<br/>',NULL,12159,12159);
INSERT INTO stanza VALUES('CS531','1','我們在流中，<br/>我們在流中！<br/>哦，阿利路亞，在流中！<br/>（二遍）<br/>哦，讚美主，<br/>我們在流中！<br/>哦，阿利路亞，在流中！<br/>哦，讚美主，<br/>我們在流中！<br/>哦，阿利路亞，在流中。<br/>',NULL,12160,12160);
INSERT INTO stanza VALUES('CS532','1','何等奇妙的事實，<br/>我竟成為你基業，<br/>你的豐富原無比，<br/>無我卻仍有所缺。<br/>',NULL,12161,12161);
INSERT INTO stanza VALUES('CS532','chorus','哦！我們竟成為<br/>你愛的對象，<br/>將你豐富來彰顯，<br/>你榮耀得稱讚。<br/>哦！我們竟成為<br/>你愛的對象，<br/>將你豐富來彰顯，<br/>叫你榮耀得稱讚。<br/>',NULL,12162,12162);
INSERT INTO stanza VALUES('CS532','2','照你所定的美意，<br/>我得各樣的福氣，<br/>創世以前蒙揀選，<br/>今得救贖成聖潔。<br/>',NULL,12163,12163);
INSERT INTO stanza VALUES('CS532','3','藉你聖靈作憑質，<br/>我得被贖的確據，<br/>滿得智慧和啟示，<br/>對你完全有認識。<br/>',NULL,12164,12164);
INSERT INTO stanza VALUES('CS532','4','當我心眼被照明，<br/>知你恩召滿指望，<br/>你復活大能大力，<br/>也顯在我們身上。<br/>',NULL,12165,12165);
INSERT INTO stanza VALUES('CS532','5','主，我們滿心讚美<br/>我們乃是你基業，<br/>是你召會你身體，<br/>你今是一無所缺。<br/>',NULL,12166,12166);
INSERT INTO stanza VALUES('CS533','1','我們在曠野流落，<br/>日子已經彀久；<br/>誰說要進入迦南，<br/>現在不是時候？看哪，<br/>榮耀在望，<br/>應當剛強膽壯！<br/>我們是新的一代，<br/>一定要過去承受！<br/>快，快，快！為主恢復，<br/>我們不能再落後。<br/>',NULL,12167,12167);
INSERT INTO stanza VALUES('CS533','2','我們有主的約櫃，<br/>走在我們前頭，<br/>要領我們走新路，<br/>向來沒有走過。<br/>看哪，約但河水，<br/>已經立起如壘；<br/>我們這一代<br/>應該打斷世界的潮流！<br/>走，走，走！我們大夥兒<br/>浩浩蕩蕩往前走！<br/>',NULL,12168,12168);
INSERT INTO stanza VALUES('CS533','3','讚美主，阿利路亞，<br/>我們到了吉甲；<br/>老舊已經埋葬了，<br/>肉體也被割下。<br/>喫了迦南土產，<br/>嗎哪不再稀罕；<br/>我們不再像從前<br/>完全靠神蹟度日。<br/>喫，喫，喫！為著爭戰<br/>天天喫迦南產物！<br/>',NULL,12169,12169);
INSERT INTO stanza VALUES('CS533','4','與主同站在一邊，<br/>不怕沒主同在；<br/>照著主吩咐去行，<br/>因為主是元帥！<br/>無論關得多緊，<br/>你這城耶利哥，<br/>等我們大聲呼喊，<br/>你就非倒塌不可！<br/>去，去，去！我們出去，<br/>把各城一一奪取。<br/>',NULL,12170,12170);
INSERT INTO stanza VALUES('CS533','5','這全地不為別的，<br/>乃是為著召會！<br/>主，我們奉獻一切，<br/>讓你能早歸回。<br/>你若還不滿意，<br/>我們也不滿意，<br/>瘋，瘋，瘋！為著全島<br/>我們要繼續發瘋，<br/>直到神所應許的，<br/>沒有一句話落空。<br/>',NULL,12171,12171);
INSERT INTO stanza VALUES('CS601','1','神的生命，是人需要；<br/>神的建造是神的目標。<br/>基督得勝，魔鬼蒙羞；<br/>神的計畫不久要成就！<br/>',NULL,12172,12172);
INSERT INTO stanza VALUES('CS601','chorus','建造我，主耶穌！<br/>我不願再我行我素。<br/>『活在靈中，經常禱讀，<br/>多禱告。』阿們，主！<br/>',NULL,12173,12173);
INSERT INTO stanza VALUES('CS601','2','生命的主，滿有個性；<br/>祂的豐富是我們供應。<br/>為著建造，需要生命；<br/>生命、建造，<br/>原相輔相成。<br/>',NULL,12174,12174);
INSERT INTO stanza VALUES('CS601','3','我們起來，獻上自己，<br/>一手建造，一手拿兵器。<br/>除去紛爭，消殺己意，<br/>兩刃利劍，刺身內仇敵。<br/>',NULL,12175,12175);
INSERT INTO stanza VALUES('CS601','4','有一條路<br/>是通到主豐盛的生命，<br/>藉這生命長進，<br/>建造自然產生；<br/>只要全人敞開，<br/>心轉向主，在靈裡<br/>天天都來禱讀，來禱讀。<br/>（接到副歌）<br/>',NULL,12176,12176);
INSERT INTO stanza VALUES('CS602','1','我們看見你榮耀計畫，<br/>要在地上建造你家；<br/>不禁禱告：『主，<br/>得著我們，建造我們─<br/>照你辦法！』<br/>你的回答迅速又肯定：<br/>『為建我家，你當知道：<br/>你魂生命必須要了了，<br/>你必須在壇上仆倒。』<br/>',NULL,12177,12177);
INSERT INTO stanza VALUES('CS602','2','乍聽之下，審判太嚴厲，<br/>難免令人不寒而慄；<br/>但是我們天天親近你，<br/>任何代價就可不計。<br/>為你的家我們願受死，<br/>好讓你作我們一切；<br/>你是我們完全的供應，<br/>你是我們建造憑藉。<br/>',NULL,12178,12178);
INSERT INTO stanza VALUES('CS602','3','為你計畫我們獻自己，<br/>雖不盡知其中深意；<br/>生命一切，如今全獻上，<br/>作為活祭，倒出、失去。<br/>在你壇上，<br/>主，燒燬我們，<br/>直到成灰，完全徹底，<br/>讓你馨香，裊裊不絕的，<br/>在讚美中永遠歸你。<br/>',NULL,12179,12179);
INSERT INTO stanza VALUES('CS603','1','記得大衛起誓：<br/>『我不進我的帳幕，<br/>不上我的床榻，<br/>不容我打盹閉目，<br/>直等到我為耶和華，<br/>尋得安息之處。』<br/>全能的神<br/>巴望有家使屬祂者可住。<br/>',NULL,12180,12180);
INSERT INTO stanza VALUES('CS603','2','我們何等眼瞎，<br/>只顧自己的事務，<br/>任憑神殿荒涼─<br/>哦主，你必須有路！<br/>我們情願上山取木，<br/>為建你殿勞碌；<br/>絕不再說：<br/>『且等明日，』<br/>建造當趁今日！<br/>',NULL,12181,12181);
INSERT INTO stanza VALUES('CS603','3','哦主，此時此境，<br/>激動人起來建造，<br/>正如大衛之日，<br/>自動答應你呼召。<br/>同心合意，配搭一起，<br/>受此託付，多好！<br/>我們所喜，是你心意，<br/>主，我們來建造。<br/>',NULL,12182,12182);
INSERT INTO stanza VALUES('CS603','4','主，為著你召會，<br/>叫我們廢寢忘食，<br/>為建造獻一切─<br/>專心豫備你居所！<br/>陰間的門不能勝過<br/>已建成的召會。<br/>時候不多，建造我們，<br/>讓你能早歸回！<br/>（重複最後兩行）<br/>',NULL,12183,12183);
INSERT INTO stanza VALUES('CS604','1','全地平靜安息，<br/>神卻為著祂的見證，<br/>心裡火熱著急，<br/>祂是何等著急！<br/>弟兄姊妹，<br/>我們不能只顧自己，<br/>依舊貪享安逸，<br/>安逸會被撇棄。<br/>',NULL,12190,12190);
INSERT INTO stanza VALUES('CS604','2','定期已經到了，<br/>神要來再揀選我們，<br/>復興全地召會，<br/>現在正是時候！<br/>弟兄姊妹，<br/>我們應當趁這關頭，<br/>起來與主配合，<br/>不容機會錯過。<br/>',NULL,12191,12191);
INSERT INTO stanza VALUES('CS604','3','請聽主的應許：<br/>我要回到耶路撒冷，<br/>仍舊與你同住，<br/>使你豐盛發達。<br/>我的城邑，<br/>要像無城牆的鄉村，<br/>因為生養眾多，<br/>甚至容納不下。<br/>',NULL,12192,12192);
INSERT INTO stanza VALUES('CS604','4','神已開始作工，<br/>看哪，祂正興起環境，<br/>要來震動列國，<br/>好使召會抬頭。<br/>我們宣告：<br/>這個大地，乃至宇宙，<br/>都是屬於主的，<br/>撒但休要伸手，<br/>',NULL,12193,12193);
INSERT INTO stanza VALUES('CS604','5','我們有主的話，<br/>我們不是依靠勢力，<br/>不是倚靠才能，<br/>乃是靠主的靈。<br/>哦，大山哪，<br/>別在我們面前作祟，<br/>你算不得甚麼，<br/>遲早要被剷平。<br/>',NULL,12194,12194);
INSERT INTO stanza VALUES('CS604','6','七眼遍察全地，<br/>看見我們手拿線鉈，<br/>神是何等歡喜！<br/>別的祂不在意！<br/>榮耀！榮耀！<br/>殿的根基既然立了，<br/>聖殿也必完成，<br/>成在我們手裡。<br/>',NULL,12195,12195);
INSERT INTO stanza VALUES('CS605','1','萬世之前主選我，<br/>到了今世我蒙召，<br/>分別為聖歸於祂─<br/>為建造！<br/>藉著愛子的寶血，<br/>兒子名分我得到，<br/>生在神的甜美家，<br/>為建造！<br/>',NULL,12196,12196);
INSERT INTO stanza VALUES('CS605','chorus','為建造！為建造！<br/>放下成見與愛好，<br/>為建造！<br/>阿們聖靈與召會，<br/>阿們職事的引導，<br/>完全投身主經營，<br/>為建造！<br/>',NULL,12197,12197);
INSERT INTO stanza VALUES('CS605','2','我們既然蒙主召，<br/>行事為人照恩膏，<br/>凡事謙卑並溫柔─<br/>為建造！<br/>相互寬容過得去，<br/>存心忍耐喫得消，<br/>竭力保守那靈一─<br/>為建造！<br/>',NULL,12198,12198);
INSERT INTO stanza VALUES('CS605','3','使徒、先知祂設立，<br/>建造根基所憑靠，<br/>成全聖徒各盡職─<br/>為建造！<br/>凡事長進聯元首，<br/>百節相助功用調，<br/>各站地位盡本分─<br/>為建造！<br/>',NULL,12199,12199);
INSERT INTO stanza VALUES('CS605','4','我們不再作小孩，<br/>中了詭計隨風飄，<br/>惟在愛中持真實─<br/>為建造！<br/>全房靠祂得聯絡，<br/>同歸於一在真道，<br/>天衣無縫配搭好─<br/>為建造！<br/>',NULL,12200,12200);
INSERT INTO stanza VALUES('CS606','1','建造神的聖殿的時候<br/>已經來到，<br/>所有的地方召會<br/>要完全被建造。<br/>不該專顧你的家，<br/>而神家卻荒廢；<br/>弟兄們，快快興起，<br/>建造召會！<br/>',NULL,12201,12201);
INSERT INTO stanza VALUES('CS606','chorus','剛強！剛強！<br/>全體起來建造！<br/>神必定與我們同在，<br/>使殿滿了榮耀。<br/>剛強！剛強！<br/>同心合意工作；地上萬國<br/>都要看見神榮耀的居所！<br/>',NULL,12202,12202);
INSERT INTO stanza VALUES('CS606','2','聽阿，神說：<br/>你們要省察自己行為，<br/>撒種雖多，收卻少，<br/>因對我缺讚美；<br/>你們要上到山上<br/>去為我取木料，<br/>同心建造我居所，<br/>我得榮耀。<br/>',NULL,12203,12203);
INSERT INTO stanza VALUES('CS606','3','你們蒙召的祭司<br/>當向神全順服，<br/>神既與我們同在，<br/>管他世人怒目，<br/>靈裡激動並火熱，<br/>我們同來作工，<br/>但願在其中<br/>沒有一人放鬆。<br/>',NULL,12204,12204);
INSERT INTO stanza VALUES('CS606','4','萬軍之耶和華說：<br/>我殿要滿榮耀，<br/>地上萬國羨慕的<br/>必定快要來到，<br/>這殿後來的榮耀<br/>必大過先前的，<br/>我們同享這榮耀，<br/>喜樂無比。<br/>',NULL,12205,12205);
INSERT INTO stanza VALUES('CS607','1','阿利路亞，我是活石，<br/>為被基督建造！<br/>我對祂說：<br/>『你是基督，』<br/>祂立刻對我說，<br/>『你是一塊石頭。』<br/>阿利路亞，我是活石！<br/>',NULL,12206,12206);
INSERT INTO stanza VALUES('CS608','1','來罷！活石同來建造<br/>耶路撒冷的城牆，<br/>我們不再受到凌辱，<br/>聖城已聯絡整齊。<br/>',NULL,12207,12207);
INSERT INTO stanza VALUES('CS608','chorus','阿利路亞！<br/>我們都在祂裡面<br/>同被建造，<br/>成為神在靈裡居所，<br/>藉她彰顯神榮耀。<br/>',NULL,12208,12208);
INSERT INTO stanza VALUES('CS608','2','為著恢復投身流中，<br/>產生寶石與珍珠，<br/>不再單獨追求屬靈，<br/>願和聖徒同建造。<br/>',NULL,12209,12209);
INSERT INTO stanza VALUES('CS608','3','我們的靈相調一起，<br/>纔有建造的實際，<br/>不談關係情感興趣，<br/>乃是靈與靈相繫。<br/>',NULL,12210,12210);
INSERT INTO stanza VALUES('CS608','4','不是儘喊口號道理，<br/>乃是實際擺上去，<br/>一同享受配搭事奉，<br/>天天經營不鬆弛。<br/>',NULL,12211,12211);
INSERT INTO stanza VALUES('CS608','5','建造實際靈中顯露，<br/>生命活水就流出，<br/>輪中套輪行動快速，<br/>配搭猶如四活物。<br/>',NULL,12212,12212);
INSERT INTO stanza VALUES('CS608','6','阿利路亞我真歡喜，<br/>我是快樂的肢體，<br/>我願脫離關閉自己，<br/>投身榮耀經營裡。<br/>',NULL,12213,12213);
INSERT INTO stanza VALUES('CS608','chorus','求主使我心思改變，<br/>有這屬天的觀念，<br/>凡我生活所作所言，<br/>都為讓神得彰顯。<br/>',NULL,12214,12214);
INSERT INTO stanza VALUES('CS609','1','相調為一，<br/>靈裡相調為一！<br/>相調為一，<br/>靈裡相調為一！<br/>從個人、關閉出來，<br/>調入靈裡，<br/>哦，靈裡相調，<br/>直到調為一。<br/>調罷，弟兄！<br/>調罷，姊妹！<br/>靈裡相調為一。<br/>（榮耀，阿利路亞！）<br/>追求、交通、事奉，<br/>眾靈調為一靈。<br/>調罷，靈裡調罷！<br/>',NULL,12215,12215);
INSERT INTO stanza VALUES('CS609','2','同被建造，<br/>愛中同被建造。<br/>同被建造，<br/>愛中同被建造。<br/>要脫離驕傲、不服，<br/>同被建造。<br/>哦！彼此配搭，<br/>一同被建造。<br/>建造，弟兄！<br/>建造，姊妹！<br/>愛中同被建造。<br/>（榮耀，阿利路亞！）<br/>肢體彼此相顧，<br/>長幼互相順服，<br/>愛中同被建造。<br/>',NULL,12216,12216);
INSERT INTO stanza VALUES('CS610','1','藉主寶血，<br/>我們已被贖回。<br/>藉主寶血，<br/>我們已被贖回。<br/>藉主寶血，<br/>我們已被贖回。<br/>榮耀，榮耀，今看見！<br/>我們罪惡全得赦免，<br/>全得赦免。<br/>',NULL,12217,12217);
INSERT INTO stanza VALUES('CS610','2','蒙主揀選，<br/>我們都是祭司。<br/>蒙主揀選，<br/>我們都是祭司。<br/>蒙主揀選，<br/>我們都是祭司。<br/>榮耀，榮耀，今看見！<br/>我們侍立在神面前，<br/>在神面前。<br/>',NULL,12218,12218);
INSERT INTO stanza VALUES('CS610','3','在基督裡，<br/>我們都是弟兄。<br/>在基督裡，<br/>我們都是弟兄。<br/>在基督裡，<br/>我們都是弟兄。<br/>榮耀，榮耀，今看見！<br/>在主愛裡一同向前，<br/>一同向前。<br/>',NULL,12219,12219);
INSERT INTO stanza VALUES('CS610','4','在基督裡，<br/>我們都是姊妹。<br/>在基督裡，<br/>我們都是姊妹。<br/>在基督裡，<br/>我們都是姊妹。<br/>榮耀，榮耀，今看見！<br/>在主愛裡一同向前，<br/>一同向前。<br/>',NULL,12220,12220);
INSERT INTO stanza VALUES('CS610','5','弟兄姊妹，<br/>我們彼此相愛。<br/>弟兄姊妹，<br/>我們彼此相愛。<br/>弟兄姊妹，<br/>我們彼此相愛。<br/>榮耀，榮耀，今看見！<br/>『非拉鐵非』在此出現，<br/>在此出現。<br/>',NULL,12221,12221);
INSERT INTO stanza VALUES('CS610','6','我們站住地方一的立場。<br/>我們站住地方一的立場。<br/>我們站住地方一的立場。<br/>榮耀，榮耀，今看見！<br/>主的恢復完全實現，<br/>完全實現。<br/>',NULL,12222,12222);
INSERT INTO stanza VALUES('CS611','1','主，我們是你身體<br/>在此聚集，人數雖多，<br/>我們仍然是一。<br/>你的生命<br/>使我們成為肢體，<br/>在生命裡，<br/>我們完全是一。<br/>',NULL,12223,12223);
INSERT INTO stanza VALUES('CS611','chorus','在宇宙中只有一個身體，<br/>我們將她彰顯於地；<br/>我們站住地方一的立場，<br/>讓所有人同來觀賞。<br/>',NULL,12224,12224);
INSERT INTO stanza VALUES('CS611','2','這一個餅乃是<br/>表明你身體，曾被擘開，<br/>好使眾聖分享；<br/>我們喫餅，<br/>如此一同領受你，<br/>藉此見證我們真正是一。<br/>',NULL,12225,12225);
INSERT INTO stanza VALUES('CS611','3','現在桌上陳列著<br/>一餅一杯，說出我們<br/>不能分門別類；<br/>同蒙主恩，<br/>還有甚麼話可說，<br/>惟有喊說：『阿們，<br/>我們是一！』<br/>',NULL,12226,12226);
INSERT INTO stanza VALUES('CS611','4','我們是一，<br/>不能再被誰分離，<br/>因為這『一』<br/>出自基督自己。<br/>同一餅杯，<br/>我們在這一裡喫，<br/>有目共睹這個一的事實。<br/>',NULL,12227,12227);
INSERT INTO stanza VALUES('CS611','5','何等喜樂，<br/>能有分於這個一！<br/>我們深覺，<br/>主，這使你滿意！<br/>滿足之中，<br/>我們豫嘗了那日，<br/>新郎新婦那最甜美的一。<br/>',NULL,12228,12228);
INSERT INTO stanza VALUES('CS612','1','我們已經看見<br/>召會是在合一裡面，<br/>在和諧中我們聯結，<br/>見證唱詩讚美。地方召會<br/>纔是祂惟一所愛的新婦，<br/>藉呼喊主<br/>我們能彀更多得著基督。<br/>',NULL,12229,12229);
INSERT INTO stanza VALUES('CS612','chorus','惟有祂是愛，<br/>我們天天享受，<br/>我們天天享受，<br/>真實的愛。<br/>',NULL,12230,12230);
INSERT INTO stanza VALUES('CS612','2','安家召會，享受基督，<br/>使我們得飽足；<br/>靈和召會，<br/>纔是我們今日真正恢復。<br/>藉呼喊主，<br/>我們吸入祂所有的豐富，<br/>當我們被浸透佔有，<br/>靈就得著自由。<br/>',NULL,12231,12231);
INSERT INTO stanza VALUES('CS612','3','愛的水流，來自寶座，<br/>使我清新明透，<br/>何等甘甜，何等榮耀，<br/>讓我們全享受。<br/>愛的聯結，如此深厚，<br/>使我們得造就，<br/>哦，讓我們在召會中，<br/>一同長大成熟！<br/>',NULL,12232,12232);
INSERT INTO stanza VALUES('CS613','1','我們在主裡是一，<br/>在聖靈裡是一；<br/>我們在主裡是一，<br/>在聖靈裡是一；<br/>我們讚美祂，<br/>因祂使我們永遠合一。<br/>',NULL,12233,12233);
INSERT INTO stanza VALUES('CS613','chorus','在主的愛裡我們永合一，<br/>永合一；<br/>在主的愛裡我們永合一，<br/>永合一；<br/>我們讚美祂，<br/>因祂使我們永遠合一。<br/>',NULL,12234,12234);
INSERT INTO stanza VALUES('CS613','2','我們眾人被建造，<br/>在愛裡被建造；<br/>我們眾人被建造，<br/>在愛裡被建造；<br/>便叫身體漸漸長大，<br/>顯出神的榮耀。<br/>',NULL,12235,12235);
INSERT INTO stanza VALUES('CS613','3','如今主就是那靈，<br/>主靈在我靈裡；<br/>如今主就是那靈，<br/>主靈在我靈裡；<br/>在主靈裡我們<br/>同被建造合而為一。<br/>',NULL,12236,12236);
INSERT INTO stanza VALUES('CS613','4','願頌讚歸於聖父，<br/>祂是一切源頭；<br/>願頌讚歸於聖子，<br/>祂將一切承受；<br/>又願頌讚歸於聖靈，<br/>祂將一切滲透。<br/>',NULL,12237,12237);
INSERT INTO stanza VALUES('CS614','chorus','當我們信入神兒子，<br/>藉祂的靈我們合一；<br/>當我們信入神兒子，<br/>藉祂的靈我們合一。<br/>合為一，我們合為一；<br/>合為一，我們合為一；<br/>合為一，我們合為一；<br/>合為一！<br/>世界一直尋求和平，<br/>戰爭風聲卻總不停；<br/>憂心忡忡，無法消除；<br/>多少恨，多少淚，<br/>多少苦！主纔是路！<br/>（接副歌，下同）<br/>',NULL,12238,12238);
INSERT INTO stanza VALUES('CS614','1','我們在主愛裡同住，<br/>真正合一已經恢復；<br/>弟兄姊妹不分彼此，<br/>父與子如何是永合一，<br/>我們也是！<br/>',NULL,12239,12239);
INSERT INTO stanza VALUES('CS614','2','眾聖徒們和睦同居，<br/>何等的好，何等美麗！<br/>滿了膏油，滿了甘露，<br/>神永遠的生命<br/>彀你我永遠享受！<br/>',NULL,12240,12240);
INSERT INTO stanza VALUES('CS615','1','知否神有一需要，<br/>弟兄姊妹們？<br/>神需要有一居所，<br/>讓祂安家！<br/>我們若合而為一，<br/>就被建造成神家，<br/>這家使神安息，<br/>我們也得安息。<br/>',NULL,12241,12241);
INSERT INTO stanza VALUES('CS615','2','我們若分裂四散，<br/>居所怎出現？<br/>主心所喜愛乃是<br/>同心合意。<br/>故我們必須放下，<br/>攔阻合一的異議，<br/>如此帶進合一，<br/>如此帶進合一。<br/>',NULL,12242,12242);
INSERT INTO stanza VALUES('CS615','3','當我們活在『一』裡，<br/>這相愛顯出。<br/>這愛是在神家裡，<br/>實際真摯。<br/>在這家我們嘗盡，<br/>歷代聖徒的豐富。<br/>神家滿了肥甘！<br/>神家滿了肥甘！<br/>',NULL,12243,12243);
INSERT INTO stanza VALUES('CS615','4','你是否真為召會？<br/>在主前顯出？<br/>願否把自己擺上，<br/>加強恢復？<br/>願否接受這挑戰，<br/>承擔召會的託付？<br/>絕對為神花費，<br/>絕對為神花費！<br/>',NULL,12244,12244);
INSERT INTO stanza VALUES('CS615','5','從過去所有時代，<br/>主揀選我們<br/>這榮耀有福一代，<br/>帶進國度！<br/>但我們不能停頓，<br/>因目前所有滿足。<br/>我們努力向前！<br/>我們努力向前！<br/>',NULL,12245,12245);
INSERT INTO stanza VALUES('CS616','1','從前我們在罪中死了，<br/>這世界全然一團糟；<br/>但神使我們一起復活，<br/>一起與基督升天，<br/>同坐寶座。<br/>',NULL,12246,12246);
INSERT INTO stanza VALUES('CS616','chorus','耶穌聚集我們在一起，<br/>請看看聖徒同心合意！<br/>主愛使得我們都一致，<br/>達到基督<br/>豐滿身量的地步。<br/>',NULL,12247,12247);
INSERT INTO stanza VALUES('CS616','2','因此我們能和眾聖徒，<br/>一起明白基督的愛；<br/>長闊高深雖然無法測度，<br/>但神的豐滿<br/>我們一再得著。<br/>',NULL,12248,12248);
INSERT INTO stanza VALUES('CS616','3','神在歷代隱藏的旨意，<br/>已成了顯明的奧祕；<br/>基督，召會，<br/>我們今看見，<br/>這真叫撒但受辱，<br/>羞慚滿面！<br/>',NULL,12249,12249);
INSERT INTO stanza VALUES('CS616','4','我們為此來禱告父神─<br/>剛強我們裡面的人，<br/>讓你安家在我們心裡，<br/>使我們<br/>在你愛中生根立基。<br/>',NULL,12250,12250);
INSERT INTO stanza VALUES('CS616','5','在身體裡聯絡得合式，<br/>各筋節都供應基督，<br/>各個肢體功用都擺上，<br/>使身體得著建造，<br/>不斷增長！<br/>',NULL,12251,12251);
INSERT INTO stanza VALUES('CS616','6','如今我們已合而為一，<br/>成為神所要的新人；<br/>在基督裡，在召會中間，<br/>願榮耀歸神，<br/>直到永永遠遠！<br/>',NULL,12252,12252);
INSERT INTO stanza VALUES('CS617','1','我們聚在一起<br/>來喫主的晚餐；<br/>藉著這喫喝，<br/>來把合一展覽。<br/>越發宣告合一，<br/>越發有主同在，<br/>深知如此喫喝，<br/>蒙主祝福眷愛。<br/>',NULL,12253,12253);
INSERT INTO stanza VALUES('CS617','2','我們所喫的餅<br/>乃是主的身體，<br/>擘開喫進去，<br/>加起來仍是一。<br/>桌上只有一餅─<br/>只有一個身體，<br/>為著向人表明，<br/>我們主裡是一。<br/>',NULL,12254,12254);
INSERT INTO stanza VALUES('CS617','3','我們所喝的杯<br/>乃是主的新約，<br/>我們今一同<br/>交通於主的血。<br/>接納所有聖徒─<br/>只要因血得贖，<br/>在神面前稱謝<br/>我們如何蒙福。<br/>',NULL,12255,12255);
INSERT INTO stanza VALUES('CS617','4','我們別無可說，<br/>除說，『阿利路亞，』<br/>因主給我們<br/>經歷了這實際。<br/>取用主的寶血，<br/>享受主的身體，<br/>主就得著召會，<br/>榮耀歸祂自己。<br/>',NULL,12256,12256);
INSERT INTO stanza VALUES('CS618','1','我們在神家裡，<br/>蒙召在一起，<br/>因寶血洗淨，<br/>得成為聖潔；<br/>藉聖靈重生，<br/>並與神聯結，<br/>作了神後嗣，<br/>成了祂基業。<br/>自由飽足安息，<br/>讚美歌頌不絕。<br/>哦阿利路亞，<br/>蒙召在一起。<br/>',NULL,12257,12257);
INSERT INTO stanza VALUES('CS618','2','我們在聖靈裡，<br/>交通在一起，<br/>丟棄了道理，<br/>拋掉了虛儀；<br/>不拘在形式，<br/>不泥於字句，<br/>生命的新樣，<br/>活水的洋溢。<br/>不再屬於宗教，<br/>凡事追求實際，<br/>哦阿利路亞，<br/>交通在一起。<br/>',NULL,12258,12258);
INSERT INTO stanza VALUES('CS618','3','我們在召會裡，<br/>事奉在一起，<br/>除盡了惡毒，<br/>喫飽了靈食；<br/>來到主面前，<br/>個個像活石，<br/>建造為靈宮，<br/>祭司的體系。<br/>藉著耶穌基督，<br/>奉獻神喜靈祭，<br/>哦阿利路亞，<br/>事奉在一起。<br/>',NULL,12259,12259);
INSERT INTO stanza VALUES('CS618','4','我們在主愛裡，<br/>結合在一起，<br/>用愛心包容，<br/>用和平聯繫；<br/>一人有心歡樂，<br/>大家都欣喜，<br/>一人有心傷，<br/>眾人都流淚。<br/>彼此相助相顧，<br/>全體同心合意，<br/>哦阿利路亞，<br/>結合在一起。<br/>',NULL,12260,12260);
INSERT INTO stanza VALUES('CS618','5','我們在主營裡，<br/>爭戰在一起，<br/>守住了立場，<br/>站穩了等次；<br/>穿戴神軍裝，<br/>手執主兵器，<br/>奉耶穌大名，<br/>靠元首功績。<br/>隨時多方禱告，<br/>滅盡仇敵詭計，<br/>哦阿利路亞，<br/>爭戰在一起。<br/>',NULL,12261,12261);
INSERT INTO stanza VALUES('CS618','6','我們在榮耀裡，<br/>與主在一起，<br/>咒詛成往事，<br/>天地俱和煦；<br/>生命水解渴，<br/>生命果充飢，<br/>新郎偕新婦，<br/>相愛永同居。<br/>神人永遠合一，<br/>光明喜樂無比，<br/>哦阿利路亞，<br/>與主在一起。<br/>',NULL,12262,12262);
INSERT INTO stanza VALUES('CS701','1','聽這流浪者的歌聲，<br/>把他經歷道出：<br/>在他已過的年日裡，<br/>他總常感不足。<br/>',NULL,12263,12263);
INSERT INTO stanza VALUES('CS701','chorus','讚美主！讚美主！<br/>讚美主！<br/>阿利路亞，阿利路亞，<br/>讚美主！讚美主！<br/>我永不再那樣！<br/>（一至三節）<br/>',NULL,12264,12264);
INSERT INTO stanza VALUES('CS701','2','流浪奔波在世界裡，<br/>尋求快樂滿足；<br/>但是我的肉體心靈，<br/>仍然虛空痛苦。<br/>',NULL,12265,12265);
INSERT INTO stanza VALUES('CS701','3','晝夜勞苦為著自己，<br/>我房建在沙地；<br/>但讚美主！祂來拆毀，<br/>給我更好豫備。<br/>',NULL,12266,12266);
INSERT INTO stanza VALUES('CS701','4','如今找到地方召會，<br/>作一喜樂肢體；<br/>結束流浪者的生活，<br/>安居在神家裡。<br/>',NULL,12267,12267);
INSERT INTO stanza VALUES('CS701','chorus','讚美主！讚美主！<br/>讚美主！<br/>阿利路亞，阿利路亞，<br/>讚美主！讚美主！<br/>我永活在召會！<br/>（四至七節）<br/>',NULL,12268,12268);
INSERT INTO stanza VALUES('CS701','5','從前的我乖僻孤獨，<br/>活在自己裡面；<br/>但如今我與眾聖徒，<br/>在主裡同被建。<br/>',NULL,12269,12269);
INSERT INTO stanza VALUES('CS701','6','我被吸引到召會中，<br/>享受甜蜜交通；<br/>並學習在任何場合，<br/>從別人接受主。<br/>',NULL,12270,12270);
INSERT INTO stanza VALUES('CS701','7','流蕩止息，安家召會，<br/>活在祂心意裡；<br/>這是我的喜樂祕訣：<br/>享受神的安息。<br/>',NULL,12271,12271);
INSERT INTO stanza VALUES('CS702','1','（一）摸索<br/>為何你常是沒有喜樂，<br/>天天都平淡缺少音樂？<br/>是否你自己把你捆綁，<br/>生活的圈子窄小無望，<br/>所以纔這樣惆悵？<br/>（哎阿！）<br/>抑或你正是另有追求，<br/>忘記了你的寶貴的主？<br/>所以你纔是經常失望，<br/>但卻又不肯歸回群羊，<br/>纔感到如此迷惘？<br/>（哎阿！）<br/>',NULL,12272,12272);
INSERT INTO stanza VALUES('CS702','chorus','我心所愛，我心所愛，<br/>快快前來！<br/>享受我們，享受我們，<br/>就是現在！<br/>神的需要，你的需要，<br/>都得著滿足。<br/>當你投流中，<br/>只為著召會，<br/>必得著榮耀冠冕。<br/>阿利路亞！<br/>',NULL,12273,12273);
INSERT INTO stanza VALUES('CS702','2','你常對別人訴說愁苦：<br/>為何我常是走投無路，<br/>總不能衝破愁雲慘霧，<br/>奮鬥又掙扎卻不明朗。<br/>哦！何日方能剛強！<br/>（哎阿！）<br/>是因你不知何為自由，<br/>常常把自己陷在泥淖！<br/>是因你不知寶貴生命，<br/>是因你不肯把祂釋放！<br/>所以纔淒淒涼涼！<br/>（哎阿！）<br/>',NULL,12274,12274);
INSERT INTO stanza VALUES('CS702','chorus','（二）追尋<br/>我心所愛，我心所愛，<br/>快快前來！<br/>享受我們，享受我們，<br/>就是現在！<br/>神的需要，你的需要，<br/>都得著滿足。<br/>當你投流中，<br/>只為著召會，<br/>必得著榮耀冠冕。<br/>阿利路亞！<br/>',NULL,12275,12275);
INSERT INTO stanza VALUES('CS702','1','你常在那裡尋尋覓覓，<br/>也曾覺主是那樣甜蜜，<br/>你卻不讓主佔你心房，<br/>總要留一點為你著想。<br/>所以纔時變刻翻！<br/>（哎阿！）<br/>你也在主前立定心志，<br/>除了祂之外別無所知，<br/>但當祂向你有所要求，<br/>你就覺為難畏縮退後，<br/>擔不起損失剝奪！<br/>（哎阿！）<br/>',NULL,12276,12276);
INSERT INTO stanza VALUES('CS702','2','你也是常常感到困惑，<br/>為何你自己這樣軟弱，<br/>是因你羨慕<br/>得些『權能，』<br/>還是你只望<br/>為祂『工作，』<br/>失去了單純生活！<br/>（哎阿！）<br/>你或有『得勝』<br/>你就驕傲，<br/>不然就滿了灰心嘆息，<br/>只因你仍要自己屬靈，<br/>忘卻了<br/>來向『他們』投依，<br/>失去了供應能力！<br/>（哎阿！）<br/>',NULL,12277,12277);
INSERT INTO stanza VALUES('CS702','1','（三）生活<br/>你也曾多次向主說過，<br/>不來是不安，來又不妥，<br/>盼望在會中得點甚麼，<br/>補滿自己的貧窮軟弱，<br/>卻不知如何得著！<br/>（哎阿！）<br/>也許你卻是逢會必到，<br/>也跟著別人<br/>『阿們』喊叫，<br/>但你確又是虛空無聊，<br/>只因你是在<br/>履行『宗教，』<br/>不知道生命逍遙！<br/>（哎阿！）<br/>',NULL,12278,12278);
INSERT INTO stanza VALUES('CS702','2','當你見別人投身流中，<br/>你也曾多次隔岸觀望，<br/>見主在祝福你就拍掌，<br/>見別人失敗你也失望，<br/>但你卻總是這樣！<br/>（哎阿！）<br/>你私下盼望多些責任，<br/>好叫你名聲遠播四方，<br/>常給人『幫助』<br/>得著『讚賞，』<br/>常流出『關切』<br/>得著『頌揚，』<br/>你的主卻不這樣！<br/>（哎阿！）<br/>',NULL,12279,12279);
INSERT INTO stanza VALUES('CS703','1','前我曾是個孤單的人，<br/>追求自己的屬靈，<br/>盼望我能在主前侍立，<br/>使祂能歡喜滿意。<br/>多年來雖屢覺得甜美，<br/>卻又是時常淒涼，<br/>我是已有彀多的失望，<br/>知道不能再這樣。<br/>',NULL,12280,12280);
INSERT INTO stanza VALUES('CS703','2','在主裡我尋見了你們，<br/>如尋見所愛的主，<br/>我就知我已得著歸宿，<br/>在家中享受豐富。<br/>藉你們我能得著力量，<br/>不知不覺的向前，<br/>我何願與你們永結聯，<br/>只望為你們而活。<br/>',NULL,12281,12281);
INSERT INTO stanza VALUES('CS704','1','你如今活在召會裡，<br/>豈不令你歡天喜地!?<br/>讚美主，實在是榮耀，<br/>我們終於找著目標。<br/>',NULL,12282,12282);
INSERT INTO stanza VALUES('CS704','2','從此不再尋尋覓覓，<br/>我們已經回到家裡。<br/>弟兄們和睦的同居，<br/>真正天倫之樂無比！<br/>',NULL,12283,12283);
INSERT INTO stanza VALUES('CS704','3','這是神揀選的地方，<br/>神榮臉得以常瞻仰；<br/>神的名是擺在這裡，<br/>你住些時，就不一樣。<br/>',NULL,12284,12284);
INSERT INTO stanza VALUES('CS704','4','阿利路亞，別無揀選─<br/>從聽見祂聲音那天。<br/>自深處我們說：『阿們，<br/>我們樂意，投身其間。』<br/>',NULL,12285,12285);
INSERT INTO stanza VALUES('CS705','1','恩主是我所至愛，<br/>我心我命所歸。<br/>是我時刻扶持，<br/>也是我體恤安慰。<br/>前捨命成救贖，<br/>今是生命泉源，<br/>成為我安息，<br/>是我的喜樂。<br/>恩主阿！我愛你，<br/>我愛你，你，到永遠！<br/>',NULL,12286,12286);
INSERT INTO stanza VALUES('CS705','2','召會是我甜美家，<br/>滿足我的心懷。<br/>是主心愛配偶，<br/>也是我終生所投。<br/>在這家中有愛，<br/>扶持供應無限，<br/>使我有力量，<br/>引領我前往。<br/>召會阿！我愛你，<br/>我愛你，你，甜美家！<br/>',NULL,12287,12287);
INSERT INTO stanza VALUES('CS706','1','快樂日，我們回家來，<br/>同飽嘗父神慈愛；<br/>地方召會中過生活，<br/>基督豐富我們全享。<br/>',NULL,12288,12288);
INSERT INTO stanza VALUES('CS706','chorus','為著主今日恢復，<br/>操練靈，立場站住，<br/>合一中同配搭事奉，<br/>基督身體在此顯出。<br/>',NULL,12289,12289);
INSERT INTO stanza VALUES('CS706','2','神七靈，乃是焚燒靈，<br/>召會中把我煉淨；<br/>光照耀，倒空並充盈，<br/>使我變化成主榮形。<br/>',NULL,12290,12290);
INSERT INTO stanza VALUES('CS707','1','何喜樂，神的眾兒女，<br/>在家裡主面前同歡聚，<br/>同述說蒙主奇恩的故事，<br/>靈裡高昂<br/>引聲頌揚永不止。<br/>',NULL,12291,12291);
INSERT INTO stanza VALUES('CS708','1','我們同聲歌唱歡呼，<br/>我們與王一同居住！<br/>異象清楚，向主絕對，<br/>我們是祂揀選的召會。<br/>',NULL,12292,12292);
INSERT INTO stanza VALUES('CS708','2','我們聽見大雷聲響，<br/>眾聖站住地方立場，<br/>阿利路亞！我們歡呼，<br/>聚會中讚美主不止住。<br/>',NULL,12293,12293);
INSERT INTO stanza VALUES('CS708','3','我們不再流蕩不定，<br/>摸索尋找天上的星；<br/>阿利路亞，明光照亮，<br/>我們今已在家，已在家！<br/>',NULL,12294,12294);
INSERT INTO stanza VALUES('CS709','1','安家在召會，<br/>不再無家可歸，<br/>我心終日喜樂又滿足；<br/>基督作生命，<br/>一切掙扎全停，<br/>阿利路亞！我在家居住！<br/>我有家─召會，<br/>我今不再感無家可歸；<br/>我一生一世<br/>高聲頌讚不止，<br/>阿利路亞！基督與召會！<br/>',NULL,12295,12295);
INSERT INTO stanza VALUES('CS709','2','神已得安息，<br/>這是祂的住處，<br/>祂心終日喜樂又滿足；<br/>祂家已恢復，<br/>撒但別想來侵，<br/>在此祂的榮耀全顯出。<br/>神有家─召會，<br/>神今不再感無家可歸；<br/>我一生一世<br/>高聲頌讚不止，<br/>阿利路亞！基督與召會！<br/>',NULL,12296,12296);
INSERT INTO stanza VALUES('CS710','1','人人要出所多瑪，<br/>人人要出所多瑪，<br/>人人要出所多瑪，<br/>主必快來！<br/>世界都快要過去了，<br/>你還在留戀甚麼？<br/>我們被提日子近了，<br/>你要被提或留下？<br/>',NULL,12297,12297);
INSERT INTO stanza VALUES('CS710','2','在主被釘死地方，<br/>在主被釘死地方，<br/>在主被釘死地方，<br/>你要死透！<br/>我們已經與主同釘，<br/>世界對我是空白；<br/>我們如今活在地上，<br/>只為迎接祂再來！<br/>',NULL,12298,12298);
INSERT INTO stanza VALUES('CS710','3','人人都要進方舟，<br/>人人都要進方舟，<br/>人人都要進方舟，<br/>同過召會！<br/>方舟裡頭，我們享受<br/>主作我們的一切；<br/>多多經歷，多多分享，<br/>不知枯燥不覺累！<br/>',NULL,12299,12299);
INSERT INTO stanza VALUES('CS711','1','耶穌是那奇妙牧人，<br/>帶領我們出羊圈。<br/>肥沃草地，廣闊無邊，<br/>我們處身在其間！<br/>',NULL,12300,12300);
INSERT INTO stanza VALUES('CS711','chorus','哦，召會生活，<br/>無比榮耀又豐富！<br/>在此我們合一相處，<br/>享受生命的祝福。<br/>',NULL,12301,12301);
INSERT INTO stanza VALUES('CS711','2','身處異地，飢寒交迫，<br/>是祂來把我找著；<br/>祂帶我們進入美地，<br/>靈裡舒適真無比！<br/>',NULL,12302,12302);
INSERT INTO stanza VALUES('CS711','3','耶穌自己乃是草場，<br/>祂是我們的食物；<br/>我們都是屬祂的羊，<br/>每次聚集真飽足。<br/>',NULL,12303,12303);
INSERT INTO stanza VALUES('CS711','4','我們今正住於高山，<br/>新鮮甘露何舒適！<br/>所有乾渴一去不回，<br/>祂是常新的活水。<br/>',NULL,12304,12304);
INSERT INTO stanza VALUES('CS711','5','基督是我們的享受，<br/>可以高枕而無憂；<br/>我們在此平安穩妥，<br/>蒙祂同在的保守。<br/>',NULL,12305,12305);
INSERT INTO stanza VALUES('CS712','1','召會生活，輝煌之至！<br/>這是神美麗園子，<br/>在此經歷基督成長，<br/>讚美主！<br/>神在基督裡的豐富，<br/>不斷的供應我們，<br/>祂是何等新鮮、便利、<br/>又親近！<br/>',NULL,12306,12306);
INSERT INTO stanza VALUES('CS712','chorus','我真歡喜！在神的園裡，<br/>這園實在可愛又美麗！<br/>天天飽嘗生命美果，<br/>暢飲生命的樂河；<br/>世上沒有比這<br/>更好的生活！<br/>',NULL,12307,12307);
INSERT INTO stanza VALUES('CS712','2','召會不是學校、工廠，<br/>召會不是禮拜堂，<br/>乃是生命園子，<br/>讓基督成長；<br/>主把我們栽於其中，<br/>時時澆灌又培養，<br/>我們是神親手<br/>經營的農場！<br/>',NULL,12308,12308);
INSERT INTO stanza VALUES('CS712','3','在這『召會生活』園子，<br/>我們有棵生命樹，<br/>結滿生命美果，<br/>為作人食物；<br/>放下成見，不搞心思，<br/>只要簡單喫這樹，<br/>時時刻刻享受<br/>甜美的基督。<br/>',NULL,12309,12309);
INSERT INTO stanza VALUES('CS712','4','看哪！還有生命樂河，<br/>不斷流自神寶座，<br/>消除人間一切<br/>疲倦與乾渴。<br/>阿利路亞，在這園中，<br/>基督流入我裡頭，<br/>不斷滋潤、澆灌，<br/>直到我成熟。<br/>',NULL,12310,12310);
INSERT INTO stanza VALUES('CS712','5','主已把我帶進這裡，<br/>享受基督的自己，<br/>真是稱心如意，<br/>又滿心感激！<br/>我們常在靈裡喫喝，<br/>心裡大大的喜樂，<br/>且在樂園之中<br/>月月結新果。<br/>',NULL,12311,12311);
INSERT INTO stanza VALUES('CS713','1','阿！可愛的召會生活！<br/>我們在這裡，<br/>天天有喫喝；<br/>何必挨餓？何必乾渴？<br/>讓我們一同來享受！<br/>',NULL,12312,12312);
INSERT INTO stanza VALUES('CS713','chorus','快快進入方舟，<br/>同過召會生活，<br/>天天喫喝享受，<br/>日子已經不多！<br/>快快進入方舟，<br/>同過召會生活，<br/>迎接新郎回來，<br/>最是值得！<br/>',NULL,12313,12313);
INSERT INTO stanza VALUES('CS713','2','阿！可愛的召會生活！<br/>為這個奉獻，<br/>實在是值得！<br/>我們愛基督與召會，<br/>除此以外，別無所求。<br/>',NULL,12314,12314);
INSERT INTO stanza VALUES('CS713','3','阿！可愛的召會生活！<br/>在神的家中，<br/>個個都富有！<br/>可以在會中盡功用，<br/>可以到處帶人得救！<br/>',NULL,12315,12315);
INSERT INTO stanza VALUES('CS713','4','阿！可愛的召會生活！<br/>我們有美地，<br/>無比的肥沃！<br/>殷勤耕種，時刻澆灌，<br/>我們都是全時間的！<br/>',NULL,12316,12316);
INSERT INTO stanza VALUES('CS713','5','阿！可愛的召會生活！<br/>建造在一起，<br/>我們是一個！<br/>哈！老撒但，該你蒙羞，<br/>新婦到底被主得著！<br/>',NULL,12317,12317);
INSERT INTO stanza VALUES('CS714','1','有些宗教人士會說：<br/>『耶穌不可喫；<br/>我們只要明白道理，<br/>努力作好事。』<br/>親愛弟兄，請聽主說：<br/>『我是生命糧。』<br/>喫主的人憑祂活著，<br/>天天喜洋洋。<br/>',NULL,12318,12318);
INSERT INTO stanza VALUES('CS714','chorus','我愛召會生活，<br/>喫主，喝主，並呼吸主；<br/>我愛召會生活，<br/>接受神的話。<br/>我愛聽見呼喊：<br/>哦主，阿們，阿利路亞！<br/>我愛召會生活，<br/>與主同坐席。<br/>',NULL,12319,12319);
INSERT INTO stanza VALUES('CS714','2','我們時常呼喊主名，<br/>享用祂豐富，<br/>祂就充滿我們<br/>全人裡面每一部。<br/>天天聚會，交通，歌頌，<br/>與聖徒一起，<br/>如此生活直到主來，<br/>活著同被提。<br/>',NULL,12320,12320);
INSERT INTO stanza VALUES('CS714','3','末後日子，<br/>社會生活處處是邪惡，<br/>使你覺得<br/>好像跌落危險的漩渦；<br/>速速投入召會生活，<br/>傾聽聖靈說：『這是今日<br/>地上惟一有福的生活。』<br/>',NULL,12321,12321);
INSERT INTO stanza VALUES('CS715','1','清早起來就先把主喫飽，<br/>大家一同來過召會生活；<br/>守晨更，天天來，<br/>多阿們，靈就開，<br/>整天享受主同在。<br/>阿利路亞，主同在！<br/>阿利路亞，主同在！<br/>無論何處唱樂歌，<br/>過召會生活。<br/>',NULL,12322,12322);
INSERT INTO stanza VALUES('CS715','2','不講蒙恩先後，<br/>不談新舊，<br/>大家一同來見證主基督；<br/>同是身上肢體，<br/>互相聯結供應，<br/>愛裡扶持作肢體。<br/>阿利路亞，作肢體！<br/>阿利路亞，作肢體！<br/>顯出功用不畏縮，<br/>過召會生活！<br/>',NULL,12323,12323);
INSERT INTO stanza VALUES('CS715','3','基督是我的，<br/>也是你們的，<br/>大家一同來分享祂自己，<br/>在召會，在家裡，<br/>同享祂的福氣，<br/>阿利路亞，樂無比！<br/>阿利路亞，樂無比！<br/>阿利路亞，樂無比！<br/>身體豐富我全享，<br/>過召會生活！<br/>',NULL,12324,12324);
INSERT INTO stanza VALUES('CS715','4','稱耶穌是主，<br/>喊阿利路亞，<br/>大家一同來展覽主基督，<br/>你唱詩，我讚美，<br/>他見證，同阿們，<br/>聚起會來真有味！<br/>阿利路亞，真有味！<br/>阿利路亞，真有味！<br/>新鮮豐富又活潑，<br/>過召會生活！<br/>',NULL,12325,12325);
INSERT INTO stanza VALUES('CS716','1','生命歌聲在召會中，<br/>處處可以聽聞，<br/>基督是我們的喜樂，<br/>彰顯在四方。<br/>巴比倫和世俗的事<br/>與我無關無分，<br/>我們已經回家，<br/>在美地上。<br/>',NULL,12326,12326);
INSERT INTO stanza VALUES('CS716','chorus','在靈中同過召會，<br/>在召會地方立場；<br/>弟兄們同過召會，<br/>我們已經回家；<br/>跟隨眾召會同過召會，<br/>直到全地都同唱，<br/>哦阿利路亞！基督美地！<br/>',NULL,12327,12327);
INSERT INTO stanza VALUES('CS716','2','一切背景，所有道理，<br/>已經遠遠拋棄；<br/>世俗人情，罪中之樂，<br/>更是全絕離。<br/>耶穌基督大愛<br/>正在我們心中洋溢，<br/>我們決不離開基督美地。<br/>',NULL,12328,12328);
INSERT INTO stanza VALUES('CS716','3','『我要把我的召會<br/>建造在這磐石上！』<br/>主既如此豫言，<br/>祂也必如此成就。<br/>將各肢體按祂意思，<br/>配搭在身體上，<br/>建造一起，<br/>在基督美地上！<br/>',NULL,12329,12329);
INSERT INTO stanza VALUES('CS716','4','現今主正全地<br/>快速開展祂的恢復，<br/>所有地方召會，<br/>同心向著主求禱，<br/>速速降臨結束時代，<br/>迎娶祂的新婦。<br/>阿利路亞歡呼：<br/>基督美地！<br/>',NULL,12330,12330);
INSERT INTO stanza VALUES('CS716','chorus','在靈中同過召會，<br/>在召會地方立場；<br/>弟兄們同過召會，<br/>我們已經回家；<br/>跟隨眾召會同過召會，<br/>直到全地都同唱，<br/>哦阿利路亞！基督美地！<br/>註：『過召會』係譯自英詩新辭『Churching。』<br/>',NULL,12331,12331);
INSERT INTO stanza VALUES('CS717','1','自從『過召會』，<br/>生活何美麗，豫嘗那日；<br/>新耶路撒冷，<br/>新耶路撒冷，<br/>安息的滿足。<br/>',NULL,12332,12332);
INSERT INTO stanza VALUES('CS717','2','今日的召會就是那美地<br/>─流奶與蜜。<br/>盡情的享受，<br/>盡情的享受，<br/>豐盛的生命。<br/>',NULL,12333,12333);
INSERT INTO stanza VALUES('CS717','3','建造的召會就是神居所，<br/>讓祂安息；為祂掌王權，<br/>為祂掌王權，<br/>完成神旨意。<br/>',NULL,12334,12334);
INSERT INTO stanza VALUES('CS718','1','我們一心巴望著<br/>同去過節；<br/>有人說『去』，<br/>我們就興高采烈！<br/>悲哀禁食的日子<br/>已經過去，<br/>現在我們在一起，<br/>是為著享受歡喜。<br/>哦！阿利路亞，<br/>一同過節，<br/>哦！這是我們的聚會！<br/>凡嘗到的人都能述說，<br/>這甘甜無比的滋味！<br/>難怪一心巴望著<br/>同去過節；<br/>有人說『去』，<br/>我們就興高采烈！<br/>悲哀禁食的日子<br/>已經過去，<br/>現在我們在一起，<br/>是為著享受歡喜。<br/>',NULL,12335,12335);
INSERT INTO stanza VALUES('CS718','2','我們過節，<br/>要來到耶路撒冷；<br/>耶路撒冷<br/>是我們合一見證！<br/>我們的腳<br/>一站在你的門內，<br/>我們就情不自禁，<br/>讚美主榮耀的名！<br/>看！耶路撒冷聯絡整齊，<br/>看！真正合一多美麗！<br/>凡愛你的人必然興旺，<br/>因神的榮耀在這裡！<br/>難怪過節<br/>要來到耶路撒冷；<br/>耶路撒冷<br/>是我們合一見證！<br/>我們的腳<br/>一站在你的門內，<br/>我們就情不自禁，<br/>讚美主榮耀的名！<br/>',NULL,12336,12336);
INSERT INTO stanza VALUES('CS718','3','我們前來朝見神，<br/>不能空手；<br/>牛、羊、鴿子或斑鳩，<br/>大小皆可，<br/>無酵薄餅、新穗子、<br/>細麵調油…<br/>當獻上你的禮物，<br/>神與人纔得飽足。<br/>看！琳瑯滿目，<br/>盡是基督；<br/>看！美不勝收，好豐富！<br/>若我們想要得著飽足，<br/>須首先讓神得飽足。<br/>難怪前來朝見神，<br/>不能空手；<br/>牛、羊、鴿子或斑鳩，<br/>大小皆可，<br/>無酵薄餅、新穗子、<br/>細麵調油…<br/>當獻上你的禮物，<br/>神與人纔得飽足。<br/>',NULL,12337,12337);
INSERT INTO stanza VALUES('CS719','1','我們與偶像，<br/>不再有關涉，<br/>基督是我們惟一的享受！<br/>我們不再受世界的迷惑，<br/>召會是我們實際的生活。<br/>',NULL,12338,12338);
INSERT INTO stanza VALUES('CS719','chorus','哦，對付以後，<br/>何等的享受！<br/>高山上滴酒、滴酒、<br/>滴酒、滴甜酒！<br/>哦！當讚美主，<br/>何等的豐富，<br/>小山上流奶、<br/>流奶、流奶子！<br/>',NULL,12339,12339);
INSERT INTO stanza VALUES('CS719','2','不再有形式，<br/>不再有老套，<br/>新酒灌滿了，<br/>自然有高潮！<br/>老年作異夢，<br/>少年見異象，<br/>有何比聚集，<br/>更令人嚮往？<br/>',NULL,12340,12340);
INSERT INTO stanza VALUES('CS719','3','活在靈裡面，<br/>恢復真是快，<br/>多年被喫去，<br/>統統補回來！<br/>人人都活躍，<br/>來供應基督─<br/>我們的聚集，<br/>越過越豐富。<br/>',NULL,12341,12341);
INSERT INTO stanza VALUES('CS720','1','基督是活神，<br/>說：阿利路亞！<br/>祂活我裡面，<br/>說：阿利路亞！<br/>祂是我永分，<br/>豐富又美佳；<br/>只要喊『哦，主』<br/>就嘗祂。<br/>',NULL,12342,12342);
INSERT INTO stanza VALUES('CS720','2','我們同聚集<br/>是好得無比；<br/>因為在靈裡<br/>一同作肢體，<br/>成為主身體<br/>彰顯祂自己；<br/>基督是我們的實際。<br/>',NULL,12343,12343);
INSERT INTO stanza VALUES('CS720','3','在地方召會<br/>我們被充滿，<br/>為使主豐富<br/>向全地擴展！<br/>一地又一地，<br/>一直到地極，<br/>把活的基督傳出去！<br/>',NULL,12344,12344);
INSERT INTO stanza VALUES('CS721','1','在主的召會中，<br/>有愛為著你；<br/>愛是純潔溫柔，<br/>深摯又真切。<br/>何必常感孤單，<br/>嘆息無友伴？<br/>在主召會之中<br/>有豐富供應！<br/>',NULL,12345,12345);
INSERT INTO stanza VALUES('CS721','2','在主的召會中，<br/>有生命為你；<br/>溫熱如同太陽，<br/>新鮮像甘露。<br/>何必感到懼怕，<br/>煩惱又焦慮？<br/>召會必定看顧，<br/>主所贖的人！<br/>',NULL,12346,12346);
INSERT INTO stanza VALUES('CS721','3','在主的召會中，<br/>有事工為你；<br/>甚至天使也會<br/>樂意來有分。<br/>何必閒站等候，<br/>要作更大事？<br/>召會正在需要<br/>你來盡功用！<br/>',NULL,12347,12347);
INSERT INTO stanza VALUES('CS721','4','在主的召會中，<br/>有住處為你；<br/>榮耀、光明、喜樂、<br/>公義又安息。<br/>何必像浪蕩者；<br/>疲倦而流落？<br/>在主召會之中<br/>有你的住處。<br/>',NULL,12348,12348);
INSERT INTO stanza VALUES('CS722','1','何等的享受，<br/>我活在祂家中，<br/>召會生活何等甘甜。<br/>呼吸祂的聖名，<br/>喫喝祂話語，<br/>為著祂的榮耀恢復。<br/>行走，我們今行走<br/>在生命的光中，<br/>生活，我們是生活在<br/>神的召會中。<br/>祂愛保守我，<br/>祂光照亮我，<br/>肢體相愛一同被建造。<br/>',NULL,12349,12349);
INSERT INTO stanza VALUES('CS723','1','我們今日的聚會<br/>乃是又新又活，<br/>靈裡聚集並敬拜，<br/>完全自由超脫。<br/>我們享受基督<br/>作一切的實際，<br/>呼喊主名時，<br/>儀文『影兒』全都撇棄。<br/>',NULL,12350,12350);
INSERT INTO stanza VALUES('CS723','chorus','又新又活的聚集，<br/>又新又活樣式，<br/>學校、公園、或海邊，<br/>那裡都不在乎！<br/>我們棄絕一切的規條、<br/>死宗教，阿利路亞！<br/>主的靈衝破一切限制！<br/>',NULL,12351,12351);
INSERT INTO stanza VALUES('CS723','2','不要任何死宗教，<br/>不要任何形式，<br/>不要任何的規條，<br/>不要人的意思，<br/>不要那殺死人的字句<br/>與道理，阿利路亞！<br/>在靈裡我們自由無比！<br/>',NULL,12352,12352);
INSERT INTO stanza VALUES('CS723','3','又新又活的聚集，<br/>一切老舊全除；<br/>唱詩禱讀的時候<br/>我們分享基督。<br/>老而又老的光景<br/>已無處可找，阿利路亞！<br/>主今日乃是在作新事！<br/>',NULL,12353,12353);
INSERT INTO stanza VALUES('CS724','1','我們是一群有雄心的人，<br/>在聚會中我們是祝福。<br/>我們不再作宗教的禮拜，<br/>乃要讓功用活潑顯出。<br/>阿利路亞！<br/>擘餅、禱告、交通，<br/>所有聚會我們都有分！<br/>不容任何聚會<br/>發死、空洞；<br/>攪活、充實是我們心志。<br/>',NULL,12354,12354);
INSERT INTO stanza VALUES('CS724','2','我們是一群有雄心的人，<br/>出口者的靈在我們裡；<br/>前不應用，<br/>將牠束縛關閉，<br/>今我們願意釋放這靈。<br/>阿利路亞！<br/>眾人釋放這靈，<br/>所有聚會再也不沉寂；<br/>我們要在會中為主說話，<br/>使眾聖徒都得著建造。<br/>',NULL,12355,12355);
INSERT INTO stanza VALUES('CS725','1','聽主吹笛，就歡欣鼓舞，<br/>見主舉哀，就捶胸哀哭；<br/>我們是小孩子，<br/>不受老套拘束，<br/>主有帶領就快快順服！<br/>聰明的人，考慮得太多，<br/>聖靈流到，還慢慢研究；<br/>難怪主向他們就封住，<br/>向嬰孩祂就樂意顯出來。<br/>',NULL,12356,12356);
INSERT INTO stanza VALUES('CS725','2','負祂的軛，一步一步走，<br/>學祂樣式，跟隨祂舉止；<br/>我們是小牛犢，<br/>自己不會作主，<br/>每一步都聽憑祂指示！<br/>祂要向東，我們就向東，<br/>祂要向西，我們就向西；<br/>又容易、又輕省、<br/>又喜樂，<br/>因為軛其實是由祂負著。<br/>',NULL,12357,12357);
INSERT INTO stanza VALUES('CS726','1','我們同聲阿們，<br/>召會實際是靈；<br/>不是儀文、教訓、辦法，<br/>一切都在乎靈。<br/>這靈浸透我們，<br/>何等輕省便利！<br/>純潔自己，脫舊更新，<br/>成為神要的人。<br/>',NULL,12358,12358);
INSERT INTO stanza VALUES('CS726','2','新酒裝新皮袋，<br/>一切老舊消除；<br/>衝破自己所有束縛，<br/>聖靈就有出路！<br/>弟兄姊妹，釋放！<br/>召會就必剛強！<br/>我們的靈如火挑旺，<br/>召會常青發旺。<br/>',NULL,12359,12359);
INSERT INTO stanza VALUES('CS727','1','基督已經將我釋放，<br/>我也釋放靈中基督；<br/>藉祂生命我脫罪律，<br/>藉我見證祂得顯彰。<br/>',NULL,12360,12360);
INSERT INTO stanza VALUES('CS727','chorus','阿利路亞！榮耀釋放！<br/>神人同工，成祂旨意。<br/>',NULL,12361,12361);
INSERT INTO stanza VALUES('CS727','2','在基督裡我得釋放，<br/>脫離今世所有轄制；<br/>前途事業盡都撇棄，<br/>為祂見證活在靈裡。<br/>',NULL,12362,12362);
INSERT INTO stanza VALUES('CS727','3','豐富基督住在靈裡，<br/>等候我來把祂經歷；<br/>每當釋放靈中基督，<br/>能力智慧無不我屬。<br/>',NULL,12363,12363);
INSERT INTO stanza VALUES('CS727','4','哦主！求你救我脫離<br/>所有老舊空洞道理；<br/>天天經營靈中豐富，<br/>時時釋放榮耀基督。<br/>',NULL,12364,12364);
INSERT INTO stanza VALUES('CS727','5','基督藉我得以彰顯，<br/>祂的榮美為人所見；<br/>每當我把祂來釋放，<br/>祂的喜樂滿我心房。<br/>',NULL,12365,12365);
INSERT INTO stanza VALUES('CS727','6','主！我今在你前拋棄，<br/>已往自大<br/>『屬靈』、『經歷』；<br/>今後不再自是自覺，<br/>運用我靈將你釋放。<br/>',NULL,12366,12366);
INSERT INTO stanza VALUES('CS728','1','阿利路亞！何等奧祕，<br/>神在肉身顯現，<br/>榮耀神的一切豐富，<br/>從我完全顯出，<br/>從我完全顯出。<br/>阿利路亞！完全顯出。<br/>',NULL,12367,12367);
INSERT INTO stanza VALUES('CS728','2','我雖不知是何肢體，<br/>卻知神住我裡，<br/>是何功用我今不問，<br/>只求讓靈自由，<br/>只求讓靈自由，<br/>阿利路亞！讓靈自由。<br/>',NULL,12368,12368);
INSERT INTO stanza VALUES('CS728','3','召會『地位』我全不顧，<br/>只顧裡面的主。<br/>我若自居把持帶領，<br/>不過捆綁聚會；<br/>我願讓神顯出。<br/>阿利路亞！讓神顯出。<br/>',NULL,12369,12369);
INSERT INTO stanza VALUES('CS728','4','榮耀！榮耀！何等奧祕，<br/>我們都在靈裡，<br/>配搭合式，結合堅固，<br/>顯出榮耀召會，<br/>顯出榮耀召會。<br/>阿利路亞！榮耀召會。<br/>',NULL,12370,12370);
INSERT INTO stanza VALUES('CS729','1','阿利路亞，自由！<br/>阿利路亞，自由！<br/>我不再受罪的捆綁。<br/>因主耶穌，<br/>將我罪辜釘在十架，<br/>阿利路亞！我自由！<br/>',NULL,12371,12371);
INSERT INTO stanza VALUES('CS729','2','阿利路亞，自由！<br/>阿利路亞，自由！<br/>我不再隨儀文擺佈，<br/>脫離宗教，<br/>完全聖別成為新人，<br/>阿利路亞！我自由！<br/>',NULL,12372,12372);
INSERT INTO stanza VALUES('CS729','3','阿利路亞，自由！<br/>阿利路亞，自由！<br/>祂的生命，變化了我，<br/>天天更新，<br/>直到長成基督身量，<br/>阿利路亞！我自由！<br/>',NULL,12373,12373);
INSERT INTO stanza VALUES('CS729','4','阿利路亞，自由！<br/>阿利路亞，自由！<br/>我們是為主的見證，<br/>在身體裡，<br/>同被模成神的形像。<br/>阿利路亞！全自由！<br/>',NULL,12374,12374);
INSERT INTO stanza VALUES('CS729','5','阿利路亞，自由！<br/>阿利路亞，自由！<br/>交給召會，配搭一起，<br/>經營建造，<br/>成為神的榮耀身體。<br/>阿利路亞！全自由！<br/>',NULL,12375,12375);
INSERT INTO stanza VALUES('CS729','6','阿利路亞，自由！<br/>阿利路亞，自由！<br/>我們經歷真實建造，<br/>終於尋到─<br/>地方召會，乃是神家。<br/>阿利路亞！全自由！<br/>',NULL,12376,12376);
INSERT INTO stanza VALUES('CS730','1','大戶人家器皿眾多，<br/>你是屬那一流？<br/>金器、銀器、<br/>木器、瓦器，<br/>貴重卑賤都有！<br/>',NULL,12377,12377);
INSERT INTO stanza VALUES('CS730','chorus','純潔自己並脫離卑賤，<br/>必作貴重器皿；<br/>成為聖別，合乎主用，<br/>使我顯主榮美！<br/>',NULL,12378,12378);
INSERT INTO stanza VALUES('CS730','2','木器─憋氣，<br/>瓦器─洩氣，<br/>你看多麼難過！<br/>金器─神氣，<br/>銀器─爭氣，<br/>你看多麼榮耀！<br/>',NULL,12379,12379);
INSERT INTO stanza VALUES('CS730','3','活在心思，考慮分析，<br/>就成木器、瓦器。<br/>順從膏油，釋放我靈，<br/>就是金器、銀器。<br/>',NULL,12380,12380);
INSERT INTO stanza VALUES('CS731','1','不走宗教儀文錯路，<br/>不搞字句道理；<br/>轉到靈中纔是正路，<br/>快快投進流裡！<br/>活在靈裡我們合一，<br/>同心而合意。<br/>呼喊：『哦主，阿們，<br/>阿利路亞！』耶穌是主！<br/>',NULL,12381,12381);
INSERT INTO stanza VALUES('CS732','1','流露、流露、<br/>流露祂的豐富，<br/>讓生命豐富<br/>從我裡面盡流出；<br/>流露、流露、<br/>流露祂的生命，<br/>讓生命豐富<br/>成為眾人的供應。<br/>當我知道在我裡的豐富，<br/>當我知道這豐富的滿足，<br/>我就願意將牠盡都流出，<br/>好叫眾人<br/>都因這流露得飽足。<br/>',NULL,12382,12382);
INSERT INTO stanza VALUES('CS732','2','釋放、釋放、<br/>釋放祂的生命，<br/>讓祂生命的<br/>一切豐富都流出；<br/>能力、智慧<br/>都在這生命裡，<br/>無時無刻<br/>不豫備從我裡顯出。<br/>不需盡力喊叫纔能釋放，<br/>不需維持宗教裡的安靜；<br/>祂的一切都在這生命裡，<br/>我若自由<br/>祂就能從我身流出。<br/>',NULL,12383,12383);
INSERT INTO stanza VALUES('CS733','1','我們現今一同前來享受<br/>眾聖徒裡面的基督。<br/>脫離自己窄小天地，<br/>以為基督僅僅是屬我的。<br/>祂的豐富已經住在<br/>我們的他們裡。<br/>所以我們一同前來享受<br/>眾聖徒裡面的基督。<br/>',NULL,12384,12384);
INSERT INTO stanza VALUES('CS733','chorus','弟兄們哪，快快前來！<br/>盡情享受你的所有；<br/>當我們能讓祂自由，<br/>我們就能同得享受。<br/>我的經歷是你豐富，<br/>你的經營是我供應；<br/>我們一同彼此享受，<br/>神人在此同得滿足。<br/>',NULL,12385,12385);
INSERT INTO stanza VALUES('CS733','2','我享受你，你享受我，<br/>纔知道基督是何等豐富。<br/>我供應你，你供應我，<br/>纔得著生命一切的實際。<br/>祂賜我的豐富產業<br/>在我的他們裡。<br/>現今我們彼此享受，<br/>就經歷生活是何等甜美。<br/>',NULL,12386,12386);
INSERT INTO stanza VALUES('CS734','1','弟兄們哪！讓我問問你，<br/>可否作一個見證，<br/>餧養我靈滿足我的心，<br/>使我能向前行。<br/>我的靈裡何等飢渴，<br/>要得供應，<br/>若是你們都閉口無言，<br/>我豈能得飽足。<br/>多次我是切切盼望<br/>這時刻來到，<br/>與你們能相聚在一起，<br/>得著供應。<br/>',NULL,12387,12387);
INSERT INTO stanza VALUES('CS734','2','親愛弟兄，讓我對你說，<br/>我不僅有一見證，<br/>裡面豐富我時刻經營，<br/>我也述說不盡。<br/>豈是僅有一個見證，<br/>滿足你心？<br/>我們一同釋放這豐富，<br/>彼此一同享受。<br/>不是我們比你剛強，<br/>是藉祂的靈，<br/>我們就能相聚在一起，<br/>彼此供應。<br/>',NULL,12388,12388);
INSERT INTO stanza VALUES('CS735','1','當我經歷這位可愛、<br/>奇妙、豐富的救主，<br/>當祂的靈充滿我靈，<br/>猶如焚燒的烈火，<br/>當祂將祂榮耀旨意<br/>啟示照亮我心中，<br/>我就為祂說話。<br/>',NULL,12389,12389);
INSERT INTO stanza VALUES('CS735','chorus','說話，說話，阿利路亞！<br/>說話，說話，阿利路亞！<br/>說話，說話，阿利路亞！<br/>我們都能說話。<br/>',NULL,12390,12390);
INSERT INTO stanza VALUES('CS735','2','每逢操練運用我靈，<br/>享受祂一切豐富，<br/>無論會中，或在人前，<br/>或是單獨過生活，<br/>我都不禁湧出美辭，<br/>述說祂一切眷顧，<br/>我就為祂說話。<br/>',NULL,12391,12391);
INSERT INTO stanza VALUES('CS735','3','主，我今願時時刻刻<br/>經營內在的豐富，<br/>讓你生命大能運行<br/>將我裡面全點活，<br/>與你交通，禱讀你話，<br/>呼喊你名不止住，<br/>我就為你說話。<br/>',NULL,12392,12392);
INSERT INTO stanza VALUES('CS735','4','主，願我們的靈<br/>時時活潑自由的流出，<br/>每次會中我們都能<br/>讓你隨意的運行，<br/>不再作老宗教禮拜，<br/>持守儀文或遺傳，<br/>我們都能說話。<br/>',NULL,12393,12393);
INSERT INTO stanza VALUES('CS736','1','在召會中鑑賞，<br/>你的可愛，<br/>你美麗吸引我們，<br/>一同追隨。<br/>哦，阿利路亞！<br/>哦，阿利路亞！<br/>是你吸引我們一同追隨。<br/>',NULL,12394,12394);
INSERT INTO stanza VALUES('CS736','2','在召會中尋到甜美的家，<br/>在安息裡<br/>喜樂的享受豐富。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>安息裡喜樂的享受豐富。<br/>',NULL,12395,12395);
INSERT INTO stanza VALUES('CS736','3','在召會中同心來跟隨主，<br/>直到祂能因我們<br/>心滿意足。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>直到祂因我們心滿意足。<br/>',NULL,12396,12396);
INSERT INTO stanza VALUES('CS736','4','在召會中我們同是肢體，<br/>個個都能活潑的<br/>來盡功用。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>個個都活潑的來盡功用。<br/>',NULL,12397,12397);
INSERT INTO stanza VALUES('CS736','5','在召會中我們彼此相愛，<br/>個個供應生命<br/>在愛中建造。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>個個供應生命愛中建造。<br/>',NULL,12398,12398);
INSERT INTO stanza VALUES('CS736','6','在召會中我們天天長大，<br/>直到長成<br/>我主豐滿的身量。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>直到長成我主豐滿身量。<br/>',NULL,12399,12399);
INSERT INTO stanza VALUES('CS736','7','我們所有一切都為召會，<br/>直到榮耀的召會<br/>完全顯出。<br/>哦阿利路亞！<br/>哦阿利路亞！<br/>直到榮耀召會完全顯出。<br/>',NULL,12400,12400);
INSERT INTO stanza VALUES('CS737','1','萬軍之耶和華神說，<br/>你們要將當納供物，<br/>十分之一全送倉庫，<br/>使我有糧，以此試我，<br/>是否為你敞開天窗，<br/>傾福於你無處可容。<br/>我必為你斥責蝗蟲，<br/>不容牠毀壞你土產，<br/>你們田間的葡萄樹，<br/>未熟之先不掉果子；<br/>萬國必稱你們有福，<br/>你地必成喜樂之地。<br/>',NULL,12401,12401);
INSERT INTO stanza VALUES('CS738','1','你要給人神必給你，<br/>並且要用十足升斗，<br/>連搖帶按，上尖下流，<br/>倒在你懷，倒在你懷。<br/>',NULL,12402,12402);
INSERT INTO stanza VALUES('CS739','1','真歡喜！我們接待聖徒；<br/>真歡喜！我們接待聖徒。<br/>真歡喜！享受美好交通。<br/>高唱榮耀阿利路亞！<br/>這是何等祝福！<br/>',NULL,12403,12403);
INSERT INTO stanza VALUES('CS739','2','真歡喜！我們接待聖徒；<br/>真歡喜！藉此服事恩主。<br/>真歡喜！召會生活豐富。<br/>高唱榮耀阿利路亞！<br/>神的家得恢復！<br/>',NULL,12404,12404);
INSERT INTO stanza VALUES('CS740','1','誰是在主這邊？<br/>誰要迎接王？<br/>誰要在新樣中，<br/>常青而發旺？<br/>誰要脫離宗教，<br/>活在靈裡面，<br/>為主斷送前途，<br/>站在主這邊？<br/>我們在主這邊！<br/>切勿變冷淡；<br/>靈裡時常火熱，<br/>在靈裡壯膽！<br/>',NULL,12405,12405);
INSERT INTO stanza VALUES('CS741','1','為著祂！為著祂！<br/>為著祂！為著祂！<br/>為著祂召會恢復！<br/>讓我們！讓我們！<br/>讓我們！<br/>讓我們齊心努力的<br/>爭戰在一起！<br/>祂既是有一需要，<br/>你我何能不顧，<br/>祂既是有一呼召，<br/>你我何能再躊躇。<br/>',NULL,12406,12406);
INSERT INTO stanza VALUES('CS741','2','為著祂！為著祂！<br/>為著祂！為著祂！<br/>為著祂榮耀見證！<br/>讓我們！讓我們！<br/>讓我們！<br/>讓我們同心合意的<br/>建造在一起！<br/>我們看見這需要，<br/>我們都在這裡，<br/>我們一同在經營，<br/>直到祂全心滿意。<br/>',NULL,12407,12407);
INSERT INTO stanza VALUES('CS742','1','今日的基督教，<br/>死沉，分裂，無望，<br/>牠的一切光景，<br/>不過證實指明：<br/>只有基督自己，<br/>顯在真實合一，<br/>能使我們生活充實<br/>而有意義。<br/>',NULL,12408,12408);
INSERT INTO stanza VALUES('CS742','2','我們清楚看見：<br/>思想，情感，意志，<br/>一切從魂東西，<br/>不能事奉基督。<br/>我們被神創造，<br/>為作神的器皿，<br/>不斷靈被充滿，<br/>今活著是基督。<br/>',NULL,12409,12409);
INSERT INTO stanza VALUES('CS742','3','主，我們在老舊宗教裡<br/>已彀久，<br/>生活好像『屬靈』，<br/>起初愛心卻失，<br/>但主仍許悔改，<br/>活在生命裡面，<br/>成為『瘋狂愛人』，<br/>只為著你召會。<br/>',NULL,12410,12410);
INSERT INTO stanza VALUES('CS742','4','為著主的恢復，<br/>我們須被分別，<br/>脫離世界迷惑，<br/>棄絕今生驕傲；<br/>我們須為基督，<br/>作透亮的器皿，<br/>使全地上的人，<br/>都看見神榮耀！<br/>',NULL,12411,12411);
INSERT INTO stanza VALUES('CS742','5','巴比倫已傾倒，<br/>這是無可置疑，<br/>快快從她出來，<br/>弟兄們，留心聽！<br/>守住地方立場，<br/>為著基督站住；<br/>我們綁在一起，<br/>為著祂的見證。<br/>',NULL,12412,12412);
INSERT INTO stanza VALUES('CS742','6','在混亂的今日，<br/>層雲依舊密佈，<br/>哦主！求賜晴天，<br/>帶進你的國度；<br/>耶穌，惟一太陽；<br/>召會，惟一月亮，<br/>哦！新耶路撒冷，<br/>今顯出她榮耀。<br/>',NULL,12413,12413);
INSERT INTO stanza VALUES('CS743','1','絕對分別出來，<br/>活在召會中！<br/>不惜任何代價，<br/>經歷祂豐富；<br/>割斷所有岸索，<br/>投進她流中，<br/>滿有生命供應，<br/>成為她祝福。<br/>',NULL,12414,12414);
INSERT INTO stanza VALUES('CS743','chorus','絕對分別出來，<br/>歸於主召會，<br/>答應主的呼召，<br/>開展主國度。<br/>',NULL,12415,12415);
INSERT INTO stanza VALUES('CS743','2','絕對分別出來，<br/>活在召會中！<br/>治死還要治死，<br/>直到己去淨！<br/>直到器皿倒空，<br/>祂腳前破碎，<br/>直到靈裡充滿<br/>基督的生命。<br/>',NULL,12416,12416);
INSERT INTO stanza VALUES('CS743','3','絕對分別出來，<br/>歸於神旨意，<br/>走主所走道路，<br/>力上復加力。<br/>滿了榮耀喜樂，<br/>不斷向前行，<br/>同在主引導中，<br/>見證祂行動。<br/>',NULL,12417,12417);
INSERT INTO stanza VALUES('CS743','4','絕對分別出來，<br/>一直到永世；<br/>不再是我心意，<br/>全是主意旨；<br/>我的計畫願望，<br/>為她全滅沒，<br/>在世一無所有，<br/>萬有實屬我。<br/>',NULL,12418,12418);
INSERT INTO stanza VALUES('CS743','5','絕對分別出來，<br/>活在召會中！<br/>靈裡何等安息，<br/>因見主心意。<br/>天天經營基督，<br/>呼喊主聖名，<br/>時刻靈裡火熱，<br/>彰顯這新人。<br/>',NULL,12419,12419);
INSERT INTO stanza VALUES('CS743','6','我靈滿了基督，<br/>過召會生活，<br/>在她我蒙祝福，<br/>在她我長成！<br/>裡面所得異象，<br/>越過越明亮，<br/>活著是為召會，<br/>赤忠迎主歸！<br/>',NULL,12420,12420);
INSERT INTO stanza VALUES('CS744','1','我只要神旨意藉我成就，<br/>這是我惟一心志；<br/>除此外我確是一無所知，<br/>只願祂心滿意足。<br/>讓事業前途的光明火花<br/>在我身都成損失，<br/>我的生活每點每滴，<br/>完完全全都是為著主。<br/>',NULL,12421,12421);
INSERT INTO stanza VALUES('CS744','2','讓你們去努力建造城池，<br/>叫你們生活安逸；<br/>讓你們去盡情吹簫彈琴，<br/>去享受人間情趣。<br/>讓你們去打造銅鐵利器，<br/>為自己創造事業；<br/>我是一心為神旨意，<br/>絕不向世界屈就妥協。<br/>',NULL,12422,12422);
INSERT INTO stanza VALUES('CS744','3','我今見復活的榮耀基督，<br/>藉我身得以顯出；<br/>我今見祂那升天的大能，<br/>在我裡發動運行；<br/>我今見寶座的權能超越，<br/>顯我身把我提挈；<br/>我已看見祂是一切，<br/>也就是我生命的一切。<br/>',NULL,12423,12423);
INSERT INTO stanza VALUES('CS745','1','我若僅為個人『屬靈』，<br/>我就不屑再追求；<br/>所有我的屬靈經歷，<br/>都該為召會建造。<br/>',NULL,12424,12424);
INSERT INTO stanza VALUES('CS745','chorus','一切為召會，<br/>一切為召會，<br/>我的一切所有所是，<br/>全都為召會。<br/>',NULL,12425,12425);
INSERT INTO stanza VALUES('CS745','2','我若專求<br/>『亮光』『啟示』，<br/>求主就向我掩面；<br/>願我從你每一認識，<br/>都是為召會建造。<br/>',NULL,12426,12426);
INSERT INTO stanza VALUES('CS745','3','我若誇耀『聖靈恩賜』，<br/>求主收去你印證；<br/>願我的靈天天滿溢，<br/>好叫召會得建造。<br/>',NULL,12427,12427);
INSERT INTO stanza VALUES('CS745','4','我若只求『工作果效』，<br/>就願主親手拆毀；<br/>願我所有勞苦工作，<br/>全都為召會建造。<br/>',NULL,12428,12428);
INSERT INTO stanza VALUES('CS745','5','我若追求召會『地位』，<br/>求主使我感羞恥；<br/>求主時刻光照顯明，<br/>單純為召會建造。<br/>',NULL,12429,12429);
INSERT INTO stanza VALUES('CS746','1','主，我今將自己<br/>交在你恩手中，<br/>我只望能為著召會花費，<br/>雖不知我前途<br/>有何患難或痛苦，<br/>若是為著你召會，<br/>何來懊悔！<br/>',NULL,12430,12430);
INSERT INTO stanza VALUES('CS747','1','哦主！我願花費自己，<br/>為著建造你的召會；<br/>無奈對你認識浮淺，<br/>扎實經歷實在欠缺。<br/>',NULL,12431,12431);
INSERT INTO stanza VALUES('CS747','chorus','我今立下一個心志，<br/>願意完全認識基督；<br/>更要天天享受經歷，<br/>得著基督供應召會。<br/>',NULL,12432,12432);
INSERT INTO stanza VALUES('CS747','2','萬有基督在我裡頭，<br/>祂是源泉，祂也是流；<br/>惟有更多認識經歷，<br/>纔能成流點活別人。<br/>',NULL,12433,12433);
INSERT INTO stanza VALUES('CS747','3','『認識基督』只說不彀，<br/>須在經歷享用實際，<br/>享用越多，越有花費，<br/>經歷越深，越有擺出。<br/>',NULL,12434,12434);
INSERT INTO stanza VALUES('CS747','4','雖未坐在三層天上，<br/>聖靈充滿，亦感被提；<br/>雖在肉身仍然活著，<br/>卻有死而復活經歷。<br/>',NULL,12435,12435);
INSERT INTO stanza VALUES('CS747','5','當我享祂，祂亦享我，<br/>當我得祂，祂亦得我；<br/>惟有如此相互享用，<br/>結實經歷，越過越豐。<br/>',NULL,12436,12436);
INSERT INTO stanza VALUES('CS747','6','若要花費，需有本錢，<br/>認識基督是我至寶；<br/>萬事在我，都如糞土，<br/>我要實際得著基督。<br/>',NULL,12437,12437);
INSERT INTO stanza VALUES('CS748','1','這世界非我家，<br/>我的家是召會，<br/>我的生命財物，<br/>全為召會花費；<br/>這世界一切事務<br/>盡都是虛空，<br/>我若不為召會，<br/>必浪費世界中。<br/>哦主！<br/>你的心意乃是召會，<br/>開展你的國度，<br/>執行你的權柄。<br/>我的所是所有<br/>從世界全收回，<br/>從今起我活著<br/>完全是為召會。<br/>',NULL,12438,12438);
INSERT INTO stanza VALUES('CS749','1','恩主我們同在這裡，<br/>來向你表明心意，<br/>為著你召會的恢復，<br/>我們願侍立一起。<br/>讓我們能同死同苦，<br/>同承擔你的託付，<br/>讓我們能一同花費，<br/>直到你得勝歸回。<br/>哦主，願你成全此意，<br/>使我們終身相依，<br/>藉著我們你得滿足，<br/>並且成全你旨意。<br/>',NULL,12439,12439);
INSERT INTO stanza VALUES('CS750','1','我今撇下一切事物，<br/>背起十架為召會；<br/>甘受藐視厭棄貧苦，<br/>一心跟主走窄路。<br/>前我所愛所慕所求，<br/>今與雄心同歸盡；<br/>但我又是何等饒優，<br/>基督召會是我分。<br/>',NULL,12440,12440);
INSERT INTO stanza VALUES('CS750','2','讓這世界棄我嫌我，<br/>召會原不屬塵世；<br/>人面人心欺我騙我，<br/>召會卻是我實際。<br/>當我生活在召會中，<br/>友雖生疏敵雖險，<br/>但我心安處之泰然，<br/>榮耀召會我看見。<br/>',NULL,12441,12441);
INSERT INTO stanza VALUES('CS750','3','去罷！今世名利福樂，<br/>來罷！痛苦和嘲譏。<br/>為主旨意苦是喜樂，<br/>與主同工損是益。<br/>我既稱祂阿爸父親，<br/>我既將心注於你，<br/>怒吼暴風密集厚雲，<br/>都該效力成我益。<br/>',NULL,12442,12442);
INSERT INTO stanza VALUES('CS750','4','人雖逼我使我苦痛，<br/>不能改變我心願，<br/>世間苦難壓我越重，<br/>召會生活越甘甜。<br/>有何憂苦能將我襲，<br/>當你榮耀向我顯；<br/>有何快樂能將我迷，<br/>若牠不在召會裡。<br/>',NULL,12443,12443);
INSERT INTO stanza VALUES('CS750','5','向前！由恩進入榮耀，<br/>經歷身體是能力，<br/>她的豐滿是我實際，<br/>為她活著直到底。<br/>直到地上職事停止，<br/>直到奔跑到路終；<br/>直到盼望成為事實，<br/>圍繞寶座同讚頌。<br/>',NULL,12444,12444);
INSERT INTO stanza VALUES('CS751','1','遇見耶穌，我纔相信，<br/>有一種愛果真沒有條件；<br/>愛使祂來救我並住我心，<br/>背負我的軟弱，<br/>醫治甘甜。<br/>遇見你們，我纔知道，<br/>我的產業竟是如此豐盛；<br/>弟兄姊妹如同雲彩圍繞，<br/>我真滿足活在幸福之中。<br/>祂的愛情不會毀損，<br/>祂的信實從不短缺，<br/>生命供應全備、常新，<br/>帶我與祂身體聯結；<br/>為祂我願撇下世界，<br/>因我有更榮耀基業；<br/>主已應許我得生命，<br/>換來百倍，就在今生。<br/>',NULL,12445,12445);
INSERT INTO stanza VALUES('CS751','2','奔跑路上，主恩豐滿，<br/>應時、多方，<br/>你們供應無限；<br/>你們愛主，<br/>常激勵我向前，<br/>也用這愛愛我，<br/>何其深遠；<br/>軟弱，<br/>陪我同哭主前；<br/>失敗，<br/>也要跌在你們中間。<br/>走過日子，<br/>我心只有感恩，<br/>我的成長、喜悅<br/>都在你們。<br/>我心讚美，為著你們；<br/>弟兄姊妹最愛最親。<br/>我靈、我魂、我整個人，<br/>樂意全然信託你們；<br/>我們成為一個活祭，<br/>主前侍立，討主歡喜，<br/>無論何往，放膽舉步，<br/>有弟兄處，就有活路。<br/>',NULL,12446,12446);
INSERT INTO stanza VALUES('CS752','1','因著愛，<br/>我們又再次相聚，<br/>訴說恩典、安慰和鼓勵；<br/>享受靈的交通、<br/>慈心、憐恤，<br/>我們喜樂、滿足且洋溢。<br/>愛裡沒有懼怕，<br/>完全的愛把懼怕驅除。<br/>同作肢體，<br/>相互提攜、接納，<br/>同蒙天召，奔跑生命路。<br/>愛使我們相聚一起，<br/>彼此相愛，心心相繫，<br/>有聖潔情意，<br/>讓世人都知道：<br/>這愛是在基督耶穌裡！<br/>愛使我們建造一起，<br/>持守真實，聯調為一，<br/>有生命實際，<br/>讓世人都看見：<br/>永遠的愛就是神自己！<br/>',NULL,12447,12447);
INSERT INTO stanza VALUES('CS801','chorus','我們投入恢復流裡，<br/>有分於祂榮耀經營；<br/>我們進入身體事奉，<br/>被建造完成神旨意。<br/>被建造，完成神旨意；<br/>被建造，完成神旨意；<br/>被建造，完成神旨意；<br/>真歡喜！<br/>世界情慾，即將過去，<br/>神的旨意永不止息。<br/>我們不甘隨流失去，<br/>我們願被建造在一起，<br/>永不分離。<br/>（接副歌，下同。）<br/>',NULL,12448,12448);
INSERT INTO stanza VALUES('CS801','1','從前浪費在世界中，<br/>全不關心神的行動，<br/>終日追求不過幻夢，<br/>盡都是如捉影、如捕風，<br/>凡事虛空。<br/>',NULL,12449,12449);
INSERT INTO stanza VALUES('CS801','2','今蒙憐憫，未被撇棄，<br/>祂愛尋我回伯特利，<br/>投身在這榮耀經營，<br/>我此生有意義，有目的，<br/>滿了實際。<br/>',NULL,12450,12450);
INSERT INTO stanza VALUES('CS802','1','我們有位榮耀君王，<br/>天上之天是祂寶座，<br/>全地都在祂的腳下，<br/>萬國都要歸祂管治。<br/>祂和祂的百姓同住，<br/>祂也分擔一切苦楚，<br/>我們與這位王同工，<br/>無比榮耀，那裡羞恥？<br/>',NULL,12451,12451);
INSERT INTO stanza VALUES('CS802','2','我們與王同工同作，<br/>工作全歸祂不歸我，<br/>祂先用榮耀來搞我，<br/>我們再把別人搞活。<br/>我們能彀與王同工，<br/>全憑王的能力托著，<br/>所以責任變成喜樂，<br/>禱告變成讚美頌歌。<br/>',NULL,12452,12452);
INSERT INTO stanza VALUES('CS802','3','我們與王同工同享，<br/>高品福音不斷傳揚，<br/>領成千成萬人得救，<br/>把國度帶到這地上。<br/>世界無論甚麼酬勞，<br/>我們連一樣也不要，<br/>我們的職業是搞人，<br/>直到把新婦豫備好。<br/>',NULL,12453,12453);
INSERT INTO stanza VALUES('CS802','4','我們一直與王同工，<br/>天天搞人，天天發瘋，<br/>也許冬天還沒有到，<br/>榮耀的王就要來了。<br/>那時我們要圍繞祂，<br/>讚美快樂，歡呼跳躍，<br/>阿利路亞！同掌王權，<br/>阿利路亞！直到永遠。<br/>',NULL,12454,12454);
INSERT INTO stanza VALUES('CS803','1','我從來不後悔<br/>答應神呼召，<br/>我從來不後悔<br/>完全獻給主;<br/>我與恩主同行，<br/>天天在登高，<br/>我從來不後悔<br/>所走每步路。<br/>',NULL,12455,12455);
INSERT INTO stanza VALUES('CS804','1','早上有人作工，<br/>晌午有人作工，<br/>但我整天閒站，<br/>五點纔被召。<br/>我虛度了早上，<br/>枉費晌午時光，<br/>仍舊被你選上，<br/>怎能不感激？<br/>',NULL,12456,12456);
INSERT INTO stanza VALUES('CS804','chorus','愛，作得最快，<br/>愛，作得最好！<br/>我們格外蒙愛，<br/>並不覺辛苦！<br/>加緊罷，姊妹！<br/>加緊罷，弟兄！<br/>只剩一個鐘頭，<br/>讓我們趕工！<br/>',NULL,12457,12457);
INSERT INTO stanza VALUES('CS804','2','我原來是在後，<br/>沒甚麼好誇口；<br/>若論忠心追求，<br/>我不敢抬頭。<br/>但你滿有憐恤，<br/>叫我從新起頭；<br/>『愛』實在摸著我，<br/>怎能再保守？<br/>',NULL,12458,12458);
INSERT INTO stanza VALUES('CS804','3','不用我們流汗，<br/>別人已經耕好；<br/>不必我們流淚，<br/>聖靈已動工。<br/>時間這麼短暫，<br/>工作這麼輕鬆，<br/>別人種我們收，<br/>加緊來趕工！<br/>',NULL,12459,12459);
INSERT INTO stanza VALUES('CS805','1','基督我王正驅前，<br/>地方召會出現！<br/>今後在許多城市，<br/>召會必成你殿。<br/>藉著在靈裡的日子，<br/>生命使我們剛強。<br/>基督我王正驅前，<br/>得勝之歌高唱！<br/>',NULL,12460,12460);
INSERT INTO stanza VALUES('CS806','1','向前進，向前進，<br/>在聖靈裡向前進，<br/>阿利路亞，隨召會前進。<br/>我們今看見<br/>主召會的恢復，<br/>隨著七倍之靈前進。<br/>無論往那裡，<br/>使世人都知道，<br/>在這時代主一直前進！<br/>在這時代主一直前進！<br/>',NULL,12461,12461);
INSERT INTO stanza VALUES('CS807','1','新局面出現，<br/>眾聖徒正往前，看！<br/>神的榮耀在地上彰顯！<br/>召會復興的徵象，<br/>前後左右皆可見，<br/>阿利路亞，新局面出現。<br/>',NULL,12462,12462);
INSERT INTO stanza VALUES('CS808','1','從臺北市地方召會，<br/>到南部高雄海岸；<br/>我們在靈的新樣中，<br/>為主的召會爭戰。<br/>將地方召會的見證，<br/>在全臺灣島播散；<br/>我們不斷向前移動，<br/>到各城市去開展！<br/>這是主今日的恢復，<br/>這乃是祂的行動；<br/>我們必須同心合意，<br/>靠主剛強向前衝。<br/>',NULL,12463,12463);
INSERT INTO stanza VALUES('CS809','1','在主裡剛強！<br/>倚靠主大能大力，<br/>作剛強的人！<br/>在主裡剛強！<br/>倚靠主大能大力，<br/>作剛強的人！<br/>在主裡剛強，<br/>倚靠主大能大力；<br/>穿戴神軍裝，<br/>抵擋魔鬼的詭計；<br/>在主裡剛強，<br/>在主裡剛強，<br/>倚靠主大能大力，剛強！<br/>',NULL,12464,12464);
INSERT INTO stanza VALUES('CS810','1','為主打美好勝仗，<br/>憑主而活著，<br/>站住立場！<br/>不怕仇敵的攻擊，<br/>靠主踐踏在牠的頭上！<br/>為強的召會生活禱告，<br/>聖徒個個在靈裡焚燒，<br/>在新人裡面爭戰，<br/>達到神的目標！<br/>（榮耀，阿利路亞！）<br/>',NULL,12465,12465);
INSERT INTO stanza VALUES('CS811','1','我不敢稍微失敗，<br/>榮耀召會在望，<br/>基督是她的元首，<br/>坐在三層天上。<br/>我今活在異象中，<br/>我能時刻剛強；<br/>今我是個得勝者，<br/>為著召會恢復。<br/>',NULL,12466,12466);
INSERT INTO stanza VALUES('CS811','chorus','得勝，得勝者！<br/>都因榮耀召會。<br/>今我是個得勝者，<br/>因召會，因召會能得勝。<br/>',NULL,12467,12467);
INSERT INTO stanza VALUES('CS811','2','我不敢稍微失敗，<br/>因有榮耀基督，<br/>召我進到前線來，<br/>享受祂的得勝。<br/>我今是滿了膽量，<br/>靈中剛強有力；<br/>今我是個得勝者，<br/>完全充滿了你。<br/>',NULL,12468,12468);
INSERT INTO stanza VALUES('CS811','3','我不敢稍微失敗，<br/>因為從軍召會<br/>在衝陰府的境界，<br/>成就神的旨意。<br/>我們個個是戰士，<br/>剛強能以揮劍；<br/>我們同是得勝者，<br/>見證主的聖言。<br/>',NULL,12469,12469);
INSERT INTO stanza VALUES('CS811','4','我不敢稍微失敗，<br/>當此得勝時辰，<br/>榮耀我王正歸回，<br/>要說好！我僕人。<br/>我們同活在天上，<br/>取用祂的能力；<br/>天天作個得勝者，<br/>得勝一直到底。<br/>',NULL,12470,12470);
INSERT INTO stanza VALUES('CS812','1','已經得勝！<br/>基督已經勝過仇敵，<br/>得勝之聲遠近都可聽見！<br/>寶血有能，<br/>藉牠我們必得勝利，<br/>不久全能得勝主必顯現！<br/>',NULL,12471,12471);
INSERT INTO stanza VALUES('CS812','chorus','（女聲）<br/>已經得勝！<br/>哦，弟兄們哪，<br/>已經得勝，當高聲喊！<br/>在錫安聖城宣告祂得勝，<br/>直到全地充滿頌讚。<br/>（男聲）<br/>已經得勝！<br/>哦，姊妹們哪，<br/>基督已經完成神旨！<br/>祂是得勝主，<br/>將仇敵征服，<br/>永遠之樂從今開始。<br/>',NULL,12472,12472);
INSERT INTO stanza VALUES('CS812','2','已經得勝！<br/>我們已經勝過仇敵，<br/>因為我們放膽見證主話；<br/>神的話語<br/>帶給我們生命、能力；<br/>藉著這話我們必向敵誇。<br/>',NULL,12473,12473);
INSERT INTO stanza VALUES('CS812','3','已經得勝！<br/>仇敵已在我們腳底，<br/>因我們雖至死不愛性命；<br/>我們高喊：『主阿，<br/>你使我們勝利！』<br/>榮耀歸神！<br/>讚頌之聲不停。<br/>',NULL,12474,12474);
INSERT INTO stanza VALUES('CS813','1','讚美主，我們都在基督裡<br/>得勝有餘！<br/>萬事萬物都互相效力，<br/>使我們得益。<br/>召會是蒙主揀選，<br/>完全合乎神旨意，<br/>原是得勝，全是得勝，<br/>本質就是得勝！<br/>仇敵雖然不甘，<br/>多次多方攻擊，<br/>患難、困苦、逼迫、<br/>飢餓、赤身露體，<br/>靠我們主<br/>在凡事上都得勝有餘。<br/>得勝！已經完全的得勝！<br/>已經完全的得勝！<br/>已經完全的得勝！<br/>（重複頭四句。）<br/>',NULL,12475,12475);
INSERT INTO stanza VALUES('CS814','1','我們現在就是<br/>在主的得勝裡，<br/>不需要我們再來<br/>掙扎與努力；<br/>我們只要享受，<br/>在靈裡來支取，<br/>就經歷得勝實際。<br/>為何不齊誇勝！<br/>齊誇勝齊誇勝！<br/>我們已經與主<br/>同高升！同高升！<br/>三層天，在靈裡，<br/>要得勝，多容易！<br/>撒但在我們腳底！<br/>在主得勝裡面<br/>我們一同有分，<br/>這得勝的聯結<br/>是永遠不可分。<br/>我豈能再失敗、灰心，<br/>軟弱無能？<br/>我現在享受得勝！<br/>',NULL,12476,12476);
INSERT INTO stanza VALUES('CS815','1','瞧！我是人，<br/>我是這個宇宙的意義，<br/>對，我是人，<br/>我是這個宇宙的意義！<br/>神造了我，神造了我，<br/>身分崇高，身分崇高，<br/>使我成為<br/>這個宇宙中心和意義。<br/>',NULL,12477,12477);
INSERT INTO stanza VALUES('CS815','2','我有基督─<br/>祂乃是我人生的意義！<br/>（重複）<br/>這位基督，是我一切，<br/>祂乃是我人生內容、<br/>實際和意義。<br/>',NULL,12478,12478);
INSERT INTO stanza VALUES('CS815','3','召會乃是─<br/>基督在這地上的彰顯！<br/>（重複）<br/>這團體人，能代表神，<br/>管理、征服全地，<br/>使神的計畫實現。<br/>',NULL,12479,12479);
INSERT INTO stanza VALUES('CS815','4','地方召會─<br/>纔是真正的團體生活！<br/>（重複）<br/>我們今天生活有路，<br/>藉著喫喝<br/>同被建造成地方召會。<br/>',NULL,12480,12480);
INSERT INTO stanza VALUES('CS815','5','當怎麼辦？<br/>應當趕快去告訴別人！<br/>（重複）<br/>使萬民作主的門徒。<br/>我們都去把這消息<br/>傳揚到各地。<br/>',NULL,12481,12481);
INSERT INTO stanza VALUES('CS816','1','你知道你為何被造？<br/>有否想過這問題？<br/>你的生存有何目的？<br/>你今活著何意義！<br/>你知道神願作你生命？<br/>祂願作你生命，<br/>祂願作你生命！<br/>你乃是祂所造的器皿，<br/>為了裝祂，將祂表明。<br/>',NULL,12482,12482);
INSERT INTO stanza VALUES('CS816','2','你有靈，在你最深處，<br/>比你的心更深入；<br/>你的心裝許多事物，<br/>但你的靈仍缺如！<br/>多少年來，你虛空度日；<br/>雖然到處嘗試，<br/>總是不得滿足。<br/>你的深處豈不覺渴慕；<br/>願意敞開，嘗嘗耶穌？<br/>',NULL,12483,12483);
INSERT INTO stanza VALUES('CS816','3','不管你的看法如何，<br/>在神面前誰無過？<br/>主耶穌已為你流血，<br/>使你過錯得解決。<br/>救主耶穌已成全一切，<br/>不需你再努力─<br/>功過全無差別；<br/>祂乃是靈，你接受就行，<br/>祂願進來作你生命。<br/>',NULL,12484,12484);
INSERT INTO stanza VALUES('CS816','4','猶如你外面的身子，<br/>容納自己正合式，<br/>你的靈─在你的深處，<br/>乃是專為容納主。<br/>何不現在從深處敞開，<br/>現在讓主進來，<br/>充滿你的心懷；<br/>何不現在從深處敞開，<br/>呼喊主名，祂必進來。<br/>',NULL,12485,12485);
INSERT INTO stanza VALUES('CS817','1','你知道你為何得救，<br/>有否想過這問題？<br/>究竟神有甚麼計畫？<br/>基督為何拯救你？<br/>直到如今，我們只知道<br/>基督活在我裡，<br/>這實在是美好；<br/>但是神有更深的啟示，<br/>神的旨意必須達到。<br/>',NULL,12486,12486);
INSERT INTO stanza VALUES('CS817','2','伊甸河流有一目的，<br/>供應生命滋潤地。<br/>神的拯救如同水流，<br/>經過幾段的經歷。<br/>我們先脫撒但的轄制，<br/>以後再進一步，<br/>脫開那基督教。<br/>神的恢復一直往前流，<br/>永不會在中途停往。<br/>',NULL,12487,12487);
INSERT INTO stanza VALUES('CS817','3','不是僅僅一個信徒，<br/>單單獨獨到處蕩；<br/>乃是活石同被建造，<br/>團體基督得顯彰。<br/>我們重生為著得更新，<br/>但基督進你心，<br/>還有另一緣故；<br/>祂作我們生命的緣故，<br/>為要得著祂的新婦。<br/>',NULL,12488,12488);
INSERT INTO stanza VALUES('CS817','4','不是零星散亂寶石，<br/>個別屬靈的造詣;<br/>乃是實際在生命裡，<br/>同被建造在一起。<br/>你永遠不會完全滿足，<br/>除非耶穌基督<br/>得著祂的新婦。<br/>有否想過，<br/>今天主正在等待<br/>把你建造起來！<br/>',NULL,12489,12489);
INSERT INTO stanza VALUES('CS818','1','人生意義是何在？<br/>答案今已找出來！<br/>喊主耶穌嘗嘗看！<br/>祂是實際真無限！<br/>祂賜豐盛的生命─<br/>活水江河流不停，<br/>新的生命今開始，<br/>喜樂湧出永無止；<br/>愛在裡面時增加。<br/>這全都是因著祂！<br/>阿利路亞！<br/>（重複二至五行）<br/>',NULL,12490,12490);
INSERT INTO stanza VALUES('CS819','1','我們曾遍尋<br/>各處的山嶺高崗，<br/>盼望得知人生的真相，<br/>但是一次一次<br/>我們換得失望，<br/>知道世事不過是這樣。<br/>直到一天你來<br/>途中遇見我們，<br/>將你可愛的胸懷敞露，<br/>我們就被吸引<br/>歸入甜美的你，<br/>得著人生的真諦實意。<br/>',NULL,12491,12491);
INSERT INTO stanza VALUES('CS819','2','我們看見你那<br/>復活裡的榮臉，<br/>知道你曾戴荊棘冠冕；<br/>你那可親的手<br/>是我所依所傾，<br/>因手上釘痕依然顯明。<br/>我們現今在此<br/>享受可愛的你，<br/>日復一日更覺你實際，<br/>猶如潺潺流水<br/>歸回無垠大海，<br/>不知不覺失去在你裡。<br/>',NULL,12492,12492);
INSERT INTO stanza VALUES('CS820','1','哦！你今在何處，<br/>天天奔波又忙碌，<br/>卻是虛空、虛空、<br/>虛空的生活！<br/>你曾追求過萬物，<br/>卻是不能得飽足，<br/>總覺得裡面缺少、<br/>缺少些甚麼！<br/>',NULL,12493,12493);
INSERT INTO stanza VALUES('CS820','chorus','你需要耶穌！宇宙之主！<br/>你需要享受祂的豐富！<br/>你的心雖比萬物都大，<br/>祂卻能彀、<br/>能彀使你得著滿足！<br/>',NULL,12494,12494);
INSERT INTO stanza VALUES('CS820','2','哦！你確是自足，<br/>世上一切你都有，<br/>還是不覺、不覺、<br/>不覺得滿足！<br/>你的工作有成就，<br/>學業也可以自負，<br/>但是在你的深處、<br/>深處仍缺如！<br/>',NULL,12495,12495);
INSERT INTO stanza VALUES('CS821','1','（問）<br/>朋友！朋友！告訴我說：<br/>甚麼使你這樣快活？<br/>為何喜樂常顯你面，<br/>似有活泉湧自你懷。<br/>（答）<br/>你怎不知耶穌我主，<br/>祂曾捨命擔我罪辜，<br/>藉祂十架，我蒙救贖；<br/>所有罪過祂血盡除。<br/>（同啍）<br/>啦…………（一遍）<br/>',NULL,12496,12496);
INSERT INTO stanza VALUES('CS821','2','（問）<br/>我的朋友，再告訴我，<br/>是否你的就是這些？<br/>即或我罪都洗清潔，<br/>我的生活仍有所需。<br/>（答）<br/>哦，這恩主何其豐厚，<br/>豈是數語就能說盡，<br/>祂已復活作我生命，<br/>成為我的能力，供應。<br/>（同啍）<br/>啦…………（一遍）<br/>',NULL,12497,12497);
INSERT INTO stanza VALUES('CS821','3','（問）<br/>我是希奇你所得著，<br/>罪已赦免，生命裡活，<br/>但我不知像我這樣，<br/>祂的救恩能否得著？<br/>（答）<br/>哦，願你能知祂大愛，<br/>祂需要你，祂手伸出，<br/>祂巴不得賜你救贖，<br/>作你生命，作你救主。<br/>（同啍）<br/>啦…………（一遍）<br/>',NULL,12498,12498);
INSERT INTO stanza VALUES('CS821','4','（問）<br/>朋友，朋友，<br/>我今敞開我的心門<br/>讓祂進來，<br/>但願赦罪、生命、能力、<br/>喜樂活水湧自我懷。<br/>（答）<br/>弟兄，弟兄，我們同來，<br/>享受救主，就是現在，<br/>我們同是蒙恩罪人，<br/>讚祂恩惠，頌祂大愛。<br/>（同啍）<br/>啦…………（一遍）<br/>',NULL,12499,12499);
INSERT INTO stanza VALUES('CS822','1','我曾虛空又痛苦，<br/>不明白活著為何故，<br/>常今朝有酒就今朝醉，<br/>雖強作歡顏，裡面流淚，<br/>這辛酸滋味無人能領會；<br/>把牠麻醉，<br/>曾幾何時，又歸回。<br/>',NULL,12500,12500);
INSERT INTO stanza VALUES('CS822','2','雖然我並不知道，<br/>當如何解決或禱告，<br/>但是我深處總是渴慕，<br/>想要把生命意義找出。<br/>直到有一天呼喊主耶穌，<br/>讓祂進入，<br/>虛空痛苦纔消除。<br/>',NULL,12501,12501);
INSERT INTO stanza VALUES('CS822','3','耶穌活在我裡面，<br/>作我主、生命，真甘甜！<br/>因藉著呼喊耶穌的名，<br/>我生命、平安與日俱增，<br/>這世上無何使我心羨慕，<br/>我已滿足，<br/>因我得著主耶穌。<br/>',NULL,12502,12502);
INSERT INTO stanza VALUES('CS823','1','你若感覺孤單，<br/>日子難挨，<br/>耶穌，耶穌，與你同在；<br/>你若覺人生黑暗，<br/>前途茫茫，<br/>耶穌，耶穌，是你的光。<br/>你若從深處轉向祂，<br/>重擔卸下，<br/>祂必定替你擔代─<br/>祂與你同在。<br/>不要四處尋求答案，<br/>空等待，<br/>耶穌，耶穌，<br/>祂是『現在』；<br/>你若從深處呼求祂，<br/>祂不失誤！<br/>當你多方受磨煉，<br/>請務必記住：無論此世<br/>有多少景況遭遇，<br/>耶穌，耶穌，耶穌是主。<br/>',NULL,12503,12503);
INSERT INTO stanza VALUES('CS824','1','有所得─<br/>多少東西你夢寐以求，<br/>衣食住行育樂樣樣有；<br/>等到得手，不過如此。<br/>',NULL,12504,12504);
INSERT INTO stanza VALUES('CS824','2','有所事─<br/>興高采烈不過一陣子，<br/>喜新厭舊又再絞腦汁；<br/>日光之下，並無新事。<br/>',NULL,12505,12505);
INSERT INTO stanza VALUES('CS824','3','人生宛如走馬看花，<br/>來去匆匆，<br/>天天忙西忙東，<br/>到頭來是虛空的虛空。<br/>你尋求─<br/>要看有何能叫你滿足，<br/>扎扎實實非敷衍了事，<br/>能解決你心中苦楚。<br/>',NULL,12506,12506);
INSERT INTO stanza VALUES('CS824','4','不錯，<br/>是有一樣你從來沒有過，<br/>你所可能企求的<br/>都可在祂身上得著。<br/>祂是主─<br/>祂是何等的豐富實際，<br/>我的無聊已消蹤匿跡。<br/>祂填滿了我的空虛。<br/>（結尾）<br/>哦主耶穌，你是實際！<br/>',NULL,12507,12507);
INSERT INTO stanza VALUES('CS825','1','我曾尋找一道泉水，<br/>能解我裡面的乾渴，<br/>但我飲盡所有水泉，<br/>仍不滿足，一無所獲。<br/>有一天我尋到，<br/>我尋到我的主，<br/>祂在我深處成為泉源，<br/>一直到永遠。阿利路亞！<br/>耶穌！耶穌！耶穌！<br/>耶穌！耶穌解了我乾渴。<br/>耶穌！耶穌！耶穌！<br/>耶穌！耶穌作了我生命。<br/>',NULL,12508,12508);
INSERT INTO stanza VALUES('CS825','2','奇妙活泉住我裡面，<br/>天天湧流從不止息，<br/>流向祂的永遠心意，<br/>就是祂榮耀的召會。<br/>那一天祂尋回，<br/>祂尋我回祂家，<br/>我就安家在召會裡面，<br/>讓祂得滿足。阿利路亞！<br/>召會！召會！召會！<br/>召會！召會就是祂滿足。<br/>召會！召會！召會！<br/>召會！召會就是我生活。<br/>',NULL,12509,12509);
INSERT INTO stanza VALUES('CS826','1','前我生活，滿了愁苦，<br/>我的奮鬥，都歸虛無。<br/>自從耶穌，進我心府，<br/>祂作了我喜樂滿足。<br/>哦，何等奇妙，<br/>是我主耶穌！<br/>請你接受耶穌作救主，<br/>呼求祂的名，<br/>你就必得救！<br/>',NULL,12510,12510);
INSERT INTO stanza VALUES('CS827','1','這是在你，朋友，<br/>你的被造<br/>是為裝神的生命，<br/>當你敞開你心懷的剎那，<br/>祂將要進來，<br/>在你深處安家。<br/>呼喊祂名耶穌，<br/>祂是又真<br/>又活的可愛救主，<br/>祂的靈正如同生命之氣，<br/>哦，向祂敞開，<br/>就能將祂支取。<br/>不要將祂不顧，<br/>你若虛空，<br/>惟有祂愛能滿足，<br/>何不速來呼求，<br/>讓祂進入，你必無所失，<br/>卻充滿祂豐富。<br/>主！耶穌！阿利路亞！<br/>阿利路亞！耶穌。<br/>主！耶穌！阿利路亞！<br/>阿利路亞！耶穌。<br/>',NULL,12511,12511);
INSERT INTO stanza VALUES('CS828','1','你若渴慕得著主，<br/>切莫尋祂世界中，<br/>因這世界<br/>並非祂居住之所。<br/>非祂居所，非祂居所，<br/>非祂居所，非祂居所，<br/>因這世界<br/>並非祂居住之所。<br/>',NULL,12512,12512);
INSERT INTO stanza VALUES('CS828','2','你若渴慕得著主，<br/>切莫尋祂心思中，<br/>心思只使你明白，<br/>卻不能嘗。<br/>它不能嘗，（四次）<br/>心思只使你明白，<br/>卻不能嘗。<br/>',NULL,12513,12513);
INSERT INTO stanza VALUES('CS828','3','你若渴慕得著主，<br/>只要敞開你的心，<br/>只要敞開你的心，<br/>讓祂進來。<br/>讓祂進來，（四次）<br/>只要敞開你的心，<br/>讓祂進來。<br/>',NULL,12514,12514);
INSERT INTO stanza VALUES('CS828','4','你若想讓祂進來，<br/>只要呼喊祂的名，<br/>只要呼喊祂的名，<br/>祂就進來。<br/>哦！主耶穌！（四次）<br/>只要呼喊祂的名，<br/>祂必進來。<br/>',NULL,12515,12515);
INSERT INTO stanza VALUES('CS829','1','你若虛空，<br/>常覺得若有所失，<br/>你的答案乃是─耶穌！<br/>你若是有一飢渴<br/>在你深處，<br/>你可得著滿足─耶穌！<br/>你不需要再受捆綁，<br/>感覺前途茫茫；<br/>你不需要再作罪奴，<br/>或者成天幻想。<br/>耶穌甚近，在你心上，<br/>你口旁，<br/>祂正在等待你敞開，<br/>一呼喊，祂就進來。<br/>耶穌─黑暗變成光明；<br/>耶穌─平安難以形容；<br/>耶穌─從此開始新生命！<br/>',NULL,12516,12516);
INSERT INTO stanza VALUES('CS830','1','呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>哦，主耶穌！<br/>哦，主耶穌！<br/>呼喊主的名必得救！<br/>哦，主耶穌！<br/>哦，主耶穌！<br/>呼喊主的名必得救！<br/>',NULL,12517,12517);
INSERT INTO stanza VALUES('CS830','2','呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>哦，主耶穌！<br/>哦，主耶穌！<br/>阿利路亞我已得救！<br/>哦，主耶穌！<br/>哦，主耶穌！<br/>阿利路亞我已得救！<br/>',NULL,12518,12518);
INSERT INTO stanza VALUES('CS831','1','朋友，朋友，<br/>且聽這呼召，<br/>不住地臨及你心內；<br/>祂的聲音是何等柔細，<br/>卻又何其實際。<br/>祂請你分享祂的愛情，<br/>來經歷祂超越的豐富，<br/>祂請你活著為祂旨意，<br/>讓祂能藉你得滿足。<br/>',NULL,12519,12519);
INSERT INTO stanza VALUES('CS831','2','我愛，我愛，<br/>這是何奇妙，<br/>你慈愛柔聲的細語，<br/>使我的心熔化在你裡，<br/>使我忘卻自己。<br/>不僅是一個蒙愛兒女，<br/>也能跟隨你堅定腳蹤，<br/>能作你朋友同你心意，<br/>讓你能藉我得滿足。<br/>',NULL,12520,12520);
INSERT INTO stanza VALUES('CS832','1','我聽見了主耶穌說：<br/>『來，就我得安息！<br/>疲倦的人，來這裡躺臥，<br/>你可歇我胸臆。』<br/>照我本相，來就耶穌，<br/>疲憊、困倦又憂鬱。<br/>祂是我的安息之所，<br/>祂使我心暢歡。<br/>',NULL,12521,12521);
INSERT INTO stanza VALUES('CS832','2','我聽見了主耶穌說：<br/>『看！我白白賜給。<br/>乾渴的人，來暢飲活水，<br/>你可歡然取水。』<br/>我敞開心懷就耶穌，<br/>並喝那生命活泉，<br/>乾渴立消，我魂復甦，<br/>現今活在祂前。<br/>',NULL,12522,12522);
INSERT INTO stanza VALUES('CS832','3','我聽見了主耶穌說：<br/>『我是世界的光，<br/>轉眼看我，晨星必出現，<br/>照耀你的途徑。』<br/>我從自己轉向耶穌，<br/>祂是我晨星、太陽。<br/>生命光中，歡樂行走，<br/>行盡客旅路程。<br/>',NULL,12523,12523);
INSERT INTO stanza VALUES('CS833','1','有一新生命，<br/>美妙、喜樂、光明；<br/>你能彀得到，<br/>只要你決意。<br/>耶穌能滿足<br/>你的虛空心靈，<br/>祂使你心中無比的喜樂。<br/>你能彀經歷<br/>人生奇妙大改變，<br/>你能彀進入偉大的情境；<br/>你能彀經歷<br/>超越榮耀的事情，<br/>如果你讓救主<br/>進入你的心。<br/>',NULL,12524,12524);
INSERT INTO stanza VALUES('CS833','2','現在你心思<br/>不需完全明白，<br/>不必知道為甚麼，<br/>或怎樣；<br/>因祂要給<br/>你遠超你心所望，<br/>遠超你頭腦所領會得來。<br/>',NULL,12525,12525);
INSERT INTO stanza VALUES('CS834','1','『各樣都齊備』，<br/>請來赴席！<br/>來，桌上已擺滿美物；<br/>哦，飢餓者，疲倦者，<br/>來，你們就必得飽足。<br/>',NULL,12526,12526);
INSERT INTO stanza VALUES('CS834','chorus','聽，主正在邀請，<br/>無論何人願意，<br/>來得神完全救恩，<br/>無論何人願意。<br/>',NULL,12527,12527);
INSERT INTO stanza VALUES('CS834','2','『各樣都齊備』，<br/>請來赴席！<br/>來，恩門現在正大開；<br/>尊貴之位為你保留，<br/>靠近主人的胸懷。<br/>',NULL,12528,12528);
INSERT INTO stanza VALUES('CS834','3','『各樣都齊備』，<br/>請來赴席！<br/>來，祂等著你嘗恩典；<br/>今天是時候，莫遲延，<br/>因不一定有明天。<br/>',NULL,12529,12529);
INSERT INTO stanza VALUES('CS834','4','『各樣都齊備』，<br/>請來赴席！<br/>脫去罣慮，屬世爭競，<br/>來，喫神所賜的基督，<br/>並喝永遠的生命。<br/>',NULL,12530,12530);
INSERT INTO stanza VALUES('CS835','1','何大憐憫，<br/>我眼得開識真神，<br/>喜脫黑暗，<br/>得享光明自由！<br/>何奇恩典，<br/>我能白白得救恩，<br/>不需善行，<br/>也不需我苦修！<br/>',NULL,12531,12531);
INSERT INTO stanza VALUES('CS835','2','主已救我；<br/>求也記念我家人，<br/>你已擔當他們罪過愆尤；<br/>我今切求，<br/>求你應許成為真：<br/>『信主耶穌，<br/>全家都必得救。』<br/>',NULL,12532,12532);
INSERT INTO stanza VALUES('CS835','3','主，你聽我：<br/>切要得著我全家！<br/>也要垂顧，<br/>我心為此如焚：<br/>『我和我家，<br/>都要事奉耶和華！』<br/>世世代代敬拜我真活神！<br/>',NULL,12533,12533);
INSERT INTO stanza VALUES('CS836','1','雖經漫漫長夜，<br/>晚星也都已消滅，<br/>神卻末曾忘記<br/>祂所定的永約；<br/>當我們正徘徊在<br/>死蔭之地離不開，<br/>有一清晨的日光<br/>從天而來。<br/>是神憐憫的心腸，<br/>眷顧罪人的憂傷，<br/>把我們的腳<br/>引到平安路上，<br/>所有黑暗盡驅走，<br/>天來救主施拯救，<br/>使我們的黑夜變為白晝！<br/>',NULL,12534,12534);
INSERT INTO stanza VALUES('CS836','2','你來尋找失喪者，<br/>你肯赦免犯罪的，<br/>你使卑賤無望人<br/>得享天上樂；<br/>從你活出神自己，<br/>在神拯救恩典裡，<br/>你給萬民帶來<br/>大喜的信息。<br/>你是神人的調和，<br/>你是人中的聖者，<br/>我們從你看見<br/>人性的美德；<br/>如此救主我愛戴，<br/>向你我心獻敬拜，<br/>讚美你，<br/>今住我卑微胸懷！<br/>',NULL,12535,12535);
INSERT INTO stanza VALUES('CS837','1','初次來這裡，<br/>聽他們在說耶穌的事蹟，<br/>未曾聞過，<br/>但在我心坎有新的感受，<br/>莫名的平安像股暖流；<br/>我幾乎忘記來前的苦惱，<br/>不覺已脫離俗世的囚牢。<br/>從他們臉上表露的純真，<br/>我心暗想：真的有神！<br/>',NULL,12536,12536);
INSERT INTO stanza VALUES('CS837','2','他們且告訴，<br/>神要進我裡，<br/>作生命、救主，<br/>若我願意；我眼未看到，<br/>對祂又不知，<br/>只覺得需要，不妨一試；<br/>我就從深處真心轉向祂，<br/>喊『哦，主耶穌！』<br/>求祂來救拔。<br/>從無一名字如此甘又美，<br/>我享真實，今仍回味！<br/>',NULL,12537,12537);
INSERT INTO stanza VALUES('CS837','3','脫一身纏累，<br/>進入真安息，<br/>不再有定罪，蒙神稱義，<br/>我與主聯合，<br/>祂是我生命，<br/>今向神活著，因信得生；<br/>我在基督裡榮耀又逍遙，<br/>我與祂是一，<br/>成為神新造。哦，<br/>這個就是我信的故事，<br/>美妙之至，是愛是詩！<br/>',NULL,12538,12538);
INSERT INTO stanza VALUES('CS838','1','讓我滿懷喜樂告訴你，<br/>朋友，<br/>我已得到真正自由，<br/>痛苦、壓制、憂愁<br/>全都不留，<br/>就在我信主之後。<br/>祂不是信條，<br/>要我來遵守，<br/>也非誡命對我只要求；<br/>祂是神兒子，<br/>人心靈拯救，<br/>愛和生命從祂湧流，<br/>祂來解開深牢中<br/>苦惱罪囚，<br/>出死入生帶我行走。<br/>',NULL,12539,12539);
INSERT INTO stanza VALUES('CS838','2','我今在蔚藍天空<br/>展翅遨遊，<br/>耶穌是我真正自由，<br/>日復一日在這無邊享受，<br/>我心說：『有祂就彀！』<br/>朋友，<br/>這樣一位何處能有，<br/>祂愛你，已等得好長久，<br/>願否趁祂胸懷向你敞露，<br/>前來向祂完全倚投，<br/>當你進入<br/>神兒女榮耀自由，<br/>你心就不會不歌謳。<br/>',NULL,12540,12540);
INSERT INTO stanza VALUES('CS839','1','我的生命不再揮霍，<br/>自從我看見雲彩，<br/>越過一片死寂荒漠，<br/>遠遠的顯現出來；<br/>牠像光明火柱，<br/>照亮黑暗道路，<br/>燃起人生新希望，<br/>定住我的腳步。<br/>',NULL,12541,12541);
INSERT INTO stanza VALUES('CS839','2','我的人生變得充實，<br/>正當我迎向雲彩，<br/>宇宙萬物真理柱石，<br/>千百年歷久不衰；<br/>牠是神所經營，<br/>活神顯於肉身，<br/>給我無比信心，<br/>給我無比溫馨。<br/>',NULL,12542,12542);
INSERT INTO stanza VALUES('CS839','3','我的生活何等豪邁，<br/>因我已擁有雲彩，<br/>弟兄姊妹堅強的愛，<br/>圍繞我不至搖擺；<br/>真理照亮我的靈，<br/>恩典無窮無盡，<br/>從此我心有所歸，<br/>不再歎息徘徊。<br/>',NULL,12543,12543);
INSERT INTO stanza VALUES('CS839','4','我與你們已經融合，<br/>也化為這朵雲彩，<br/>天空多麼燦爛明亮，<br/>不怕那彎曲世代；<br/>讓我大步向前去，<br/>將這見證高舉，<br/>願牠光采更壯麗，<br/>直到永世不渝。<br/>（尾聲）<br/>主，噢！主，噢！<br/>讓我放下各樣重擔，<br/>生活在光明的雲彩。<br/>（註）『雲彩』一辭<br/>採自希伯來十二章一節，<br/>指許多見證人。<br/>',NULL,12544,12544);
INSERT INTO stanza VALUES('CS840','1','聽！大好信息，<br/>驚天又動地，<br/>你是神容器，<br/>為裝祂自己，<br/>祂不僅造了你，<br/>更要來充滿你，<br/>作你生命住你裡；<br/>使你享受祂實際，<br/>使你人生變美麗，<br/>使你活著滿意義，<br/>只要你願意。<br/>',NULL,12545,12545);
INSERT INTO stanza VALUES('CS840','2','過去永遠裡祂早揀選你，<br/>因愛的催逼為你親來地，<br/>十架上被舉起，<br/>經死亡祂復起，<br/>今特地來尋找你；<br/>要將活神帶給你，<br/>要將生命分給你，<br/>要將恩典賜給你，<br/>使你心滿意！<br/>',NULL,12546,12546);
INSERT INTO stanza VALUES('CS840','3','當你有了祂─<br/>三一神自己，<br/>你全人會有生命的奇蹟：<br/>你靈會有活力，<br/>你魂會真歡喜，<br/>你身安居指望裡；<br/>只要將心全開啟，<br/>只要主名一呼吸，<br/>只要一剎那而已，<br/>祂、你就是一！<br/>',NULL,12547,12547);
INSERT INTO stanza VALUES('CS841','1','生命如此好，<br/>生存價值如此高，<br/>我熱愛生命，<br/>舉手叩求真理之門；<br/>第一聲呼求，<br/>衝出我心靈，<br/>哦，主耶穌！<br/>亮光之名，自由之名，<br/>我生命終於破曉，<br/>哦，主耶穌！<br/>亮光之名，自由之名，<br/>我生命開始有了日出。<br/>',NULL,12548,12548);
INSERT INTO stanza VALUES('CS841','2','生命如此好，<br/>本來就是神創造，<br/>我熱愛生命，<br/>迫切投入生命泉源；<br/>第一聲呼求，<br/>衝出我心靈，<br/>哦，主耶穌！<br/>活水之源，甘甜之泉，<br/>我生命得到滋潤，<br/>哦，主耶穌！<br/>活水之源，甘甜之泉，<br/>我生命湧流著活的泉水。<br/>',NULL,12549,12549);
INSERT INTO stanza VALUES('CS841','3','生命如此好，<br/>追求真理要趁早，<br/>我熱愛生命，<br/>我熱愛生命之主；<br/>第一聲呼求，<br/>衝出我心靈，<br/>哦，主耶穌！<br/>進入我心，進入我靈，<br/>我生命因你成新人，<br/>哦，主耶穌！<br/>進入我心，進入我靈，<br/>我生命有了你境界全新。<br/>',NULL,12550,12550);
INSERT INTO stanza VALUES('CS842','1','在那迷失年代，<br/>我曾尋訪愛的天地，<br/>明知多人愛我，<br/>但我仍是寂寞不樂；<br/>直到我有耶穌─<br/>神賜給人愛的名字，<br/>響亮在我心靈，<br/>我的年代因祂常青。<br/>',NULL,12551,12551);
INSERT INTO stanza VALUES('CS842','2','祂是愛又是靈，<br/>進入我靈，與我結盟，<br/>我享受祂生命，<br/>祂享受我愛的順從；<br/>我們融在一起，<br/>日夜作伴，苦樂不離；<br/>愛是最大財富，<br/>世間最愛我的是主。<br/>（重複第四行）<br/>',NULL,12552,12552);
INSERT INTO stanza VALUES('CS843','1','天起了涼風，<br/>人陷罪惡中；<br/>神在天地間，聲聲呼喚：<br/>你在那裏？人哪，<br/>你在何地？<br/>神的愛情，祂的安息，<br/>全都在於你。<br/>',NULL,12553,12553);
INSERT INTO stanza VALUES('CS843','2','享受主救恩，<br/>滿足人和神，<br/>神、人同建造，<br/>居所何榮耀；<br/>團體新人，大哉！<br/>神顯於肉身，<br/>天使看見，世人信服，<br/>活神住人間。<br/>',NULL,12554,12554);
INSERT INTO stanza VALUES('CS843','3','暢飲生命河，<br/>歡唱恩愛歌，<br/>同享主肥甘，榮光溢漫；<br/>天地相繫，<br/>神、人永遠合一，<br/>人的住處，神的安息，<br/>顯在榮耀裡！<br/>',NULL,12555,12555);
INSERT INTO stanza VALUES('CS844','1','我是個新約福音祭司，<br/>帶罪人歸神是我天職，<br/>挨家去尋訪平安之子，<br/>神生命湧流不止；<br/>傳揚福音救罪人，<br/>當作祭物獻給神，<br/>天上都因此喜樂歡欣，<br/>我神也喜悅滿心。<br/>',NULL,12556,12556);
INSERT INTO stanza VALUES('CS844','chorus','何榮耀！這樣的工作，<br/>使我天天新又活，<br/>何美妙！這樣的生活，<br/>使我常常結新果。<br/>',NULL,12557,12557);
INSERT INTO stanza VALUES('CS844','2','我是個新約福音祭司，<br/>帶領人歸神，勞苦不辭，<br/>使人能甘心獻上自己，<br/>作活祭滿足神心意；<br/>宣揚基督供應人，<br/>警戒、教導，成全人，<br/>直等到將人在基督裡，<br/>成熟的獻上給神。<br/>',NULL,12558,12558);
INSERT INTO stanza VALUES('CS845','1','那些愁苦、憂慮的日子，<br/>已經一去不再回，<br/>喜樂活泉潺潺流不止，<br/>平安在心間，不消退；<br/>哦，主耶穌，我感謝你，<br/>這都是因你的憐憫，<br/>使我全家完全屬你，<br/>滿享神的救恩。<br/>',NULL,12559,12559);
INSERT INTO stanza VALUES('CS845','2','我要宣告：<br/>至於我和我家，<br/>必定事奉耶和華，<br/>從大到小個個尊主為大，<br/>一心成全神計畫；<br/>哦，主耶穌，我讚美你，<br/>我的家作你的住處，<br/>惟願這家聖別歸你，<br/>多人因此蒙福。<br/>',NULL,12560,12560);
INSERT INTO stanza VALUES('CS846','1','跟隨我主走一程，<br/>向上去得獎賞，<br/>正直愛主過一生，<br/>如同黎明的光；<br/>揮別世途和都城，<br/>選這光明一程，<br/>投身開展行列中，<br/>作主爭戰弟兄。<br/>一步邁開又一步，<br/>走出主恢復前途，<br/>見牠日日更輝煌，<br/>直到普照四方。<br/>',NULL,12561,12561);
INSERT INTO stanza VALUES('CS846','2','跟隨耶穌的腳蹤，<br/>一路洋溢歌聲，<br/>各處宣揚主得勝，<br/>美好微曦上升；<br/>輕舉腳步向前行，<br/>肩負我主使命，<br/>福音遍傳，主擴增，<br/>光芒越照越明。<br/>今日勝過了昨日，<br/>開創主恢復歷史，<br/>寫下嶄新的一頁，<br/>至終光輝烈烈。<br/>',NULL,12562,12562);
INSERT INTO stanza VALUES('CS847','1','若世間真有一種愛，<br/>能滿足人最深情懷，<br/>無限量像洋海，<br/>不改變比堅崖，<br/>救主耶穌祂就不必來；<br/>黑暗裡，祂聽見<br/>我歎息，我悲哀，<br/>一路上，祂看見<br/>我徘徊，我無奈。<br/>',NULL,12563,12563);
INSERT INTO stanza VALUES('CS847','2','因著愛，祂不能再等待，<br/>從天來，走在人世塵埃，<br/>尋找我，不懈怠；<br/>忍飢渴，受苦害；<br/>被掛木上，清償我罪債；<br/>經死亡，祂復活，<br/>進我靈，作主宰，<br/>與我聯合，使我心滿愛。<br/>',NULL,12564,12564);
INSERT INTO stanza VALUES('CS847','3','這世間我得到真愛，<br/>是耶穌，那全勝的愛，<br/>無限量像洋海，<br/>不改變比堅崖，<br/>真摯、無價、<br/>恆久且不衰；<br/>我日子祂同在，<br/>我道路祂領帥；<br/>我的主，我的愛，<br/>我愛你到萬代。<br/>',NULL,12565,12565);
INSERT INTO stanza VALUES('CS848','1','聽我唱，奇妙愛：<br/>是耶穌，從天來，<br/>十架上，祂裂開，<br/>將神聖生命釋放出來；<br/>真喜樂，罪全赦，<br/>進我靈，解乾渴，<br/>住我心，永聯合，<br/>且從我湧出如江河。<br/>',NULL,12566,12566);
INSERT INTO stanza VALUES('CS848','2','祂離你並不遠，<br/>就在你口裡面；<br/>主的名一呼喊，<br/>祂立刻進入你的心間；<br/>我嘗過，我訴說，<br/>主的愛深難測，<br/>凡願意，誰都可<br/>從救恩水泉來白喝。<br/>',NULL,12567,12567);
INSERT INTO stanza VALUES('CS849','1','哦，讓我們揚聲歡呼，<br/>角聲遍地發出，<br/>同宣告神救贖之日，<br/>人生從今開始；<br/>出黑暗，脫捆綁，<br/>我這罪囚大得釋放。<br/>哦，讓我們揚聲歡呼，<br/>角聲遍地發出。<br/>',NULL,12568,12568);
INSERT INTO stanza VALUES('CS849','2','哦，讓我們擊鼓跳舞，<br/>踏著喜悅腳步，<br/>同進入神恩典禧年，<br/>前途美好無限；<br/>我權益都恢復，<br/>重歸自由，產業豐富。<br/>哦，讓我們擊鼓跳舞，<br/>踏著喜悅腳步。<br/>',NULL,12569,12569);
INSERT INTO stanza VALUES('CS849','3','哦，讓我們盡情享受，<br/>去罷，煩惱、憂愁，<br/>將你喜樂快快敞開，<br/>神自己必進來；<br/>祂豐富充滿我，<br/>如同大水，全人漫過。<br/>哦，讓我們盡情享受，<br/>去罷，煩惱、憂愁。<br/>',NULL,12570,12570);
INSERT INTO stanza VALUES('CS849','4','哦，讓我們喫喝快樂，<br/>父家滿了詩歌，<br/>祂是我們完全的愛，<br/>我們一生年代；<br/>來安家神居所，<br/>天天過著禧年生活。<br/>哦，讓我們喫喝快樂，<br/>父家滿了詩歌。<br/>',NULL,12571,12571);
INSERT INTO stanza VALUES('CS901','1','末期豫兆在指明，<br/>基督快要再降臨，<br/>我們豫備當儆醒─<br/>恩主耶穌要再臨！<br/>',NULL,12572,12572);
INSERT INTO stanza VALUES('CS901','chorus','主要再臨，主要再臨，<br/>時間飛逝不稍等，<br/>不久即聞半夜喊聲！<br/>主要再臨，主要再臨，<br/>我們須豫備像聰明童女，<br/>恩主耶穌要再臨！<br/>',NULL,12573,12573);
INSERT INTO stanza VALUES('CS901','2','當從魂和你自己，<br/>轉眼望主不稍離，<br/>沒有時間再遲疑─<br/>恩主耶穌要再臨！<br/>',NULL,12574,12574);
INSERT INTO stanza VALUES('CS901','3','愚拙童女戀世界，<br/>到主來時纔發覺，<br/>器皿裡面油空缺─<br/>恩主耶穌要再臨！<br/>',NULL,12575,12575);
INSERT INTO stanza VALUES('CS901','4','聰明童女常殷勤，<br/>世界的酒不醉飲，<br/>她們發光，靈充盈─<br/>恩主耶穌要再臨！<br/>',NULL,12576,12576);
INSERT INTO stanza VALUES('CS901','5','我們出去迎新郎，<br/>必須將燈修明亮，<br/>也須買油免燈暗─<br/>恩主耶穌要再臨！<br/>',NULL,12577,12577);
INSERT INTO stanza VALUES('CS901','6','聰明童女都進去，<br/>作祂新婦同坐席，<br/>門向她們不關閉─<br/>恩主耶穌要再臨！<br/>',NULL,12578,12578);
INSERT INTO stanza VALUES('CS901','7','主今就在歸途中，<br/>無人知道那點鐘，<br/>儆醒與主時交通─<br/>恩主耶穌要再臨！<br/>',NULL,12579,12579);
INSERT INTO stanza VALUES('CS902','1','主必要快來─<br/>今與世界斷開；<br/>脫去一切的纏累，<br/>快跑不懈怠。<br/>',NULL,12580,12580);
INSERT INTO stanza VALUES('CS902','chorus','主就要來！主就要來！<br/>哦，主就要回來！<br/>主就要來！主就要來！<br/>阿們，主快來！<br/>',NULL,12581,12581);
INSERT INTO stanza VALUES('CS902','2','也許是今天─<br/>向主注目不變，<br/>轉眼仰望主耶穌，<br/>雖時遭驚險。<br/>',NULL,12582,12582);
INSERT INTO stanza VALUES('CS902','3','從自己、罪、世，<br/>轉眼向主注視，<br/>祂必為你來完成，<br/>祂所已創始。<br/>',NULL,12583,12583);
INSERT INTO stanza VALUES('CS902','4','注視祂榮面<br/>滿受祂的恩典，<br/>將來在祂國度裡，<br/>與祂同顯現。<br/>',NULL,12584,12584);
INSERT INTO stanza VALUES('CS902','5','阿們祂的話─<br/>所讀所聽的話，<br/>我們靈裡被激動；<br/>準備迎接祂。<br/>',NULL,12585,12585);
INSERT INTO stanza VALUES('CS903','1','主隨時隨刻都可能回來，<br/>主隨時隨刻都可能回來，<br/>主隨時隨刻都可能回來，<br/>哦，讓我們儆醒等待！<br/>',NULL,12586,12586);
INSERT INTO stanza VALUES('CS903','2','基督是我們可愛的新郎，<br/>（重複三次，下同）<br/>我們乃是祂的新婦！<br/>',NULL,12587,12587);
INSERT INTO stanza VALUES('CS903','3','我們已定意轉眼注視主，<br/>永不回頭，永不回頭！<br/>',NULL,12588,12588);
INSERT INTO stanza VALUES('CS903','4','路程在前頭，<br/>纏累丟背後，<br/>加速向前！加速向前！<br/>',NULL,12589,12589);
INSERT INTO stanza VALUES('CS903','5','我們正快跑，<br/>迎接主來到，<br/>不久就要與主相遇！<br/>',NULL,12590,12590);
INSERT INTO stanza VALUES('CS904','1','醒罷，弟兄！<br/>醒罷，姊妹！<br/>黑夜已深，<br/>白晝現正臨近。<br/>我們的主快再來，<br/>快再來，快再來。<br/>我們的主快再來，<br/>掌權直到萬代。<br/>',NULL,12591,12591);
INSERT INTO stanza VALUES('CS904','2','時候不多！不可懶惰！<br/>在祂面前必須多花時間，<br/>我們就必充滿主，<br/>充滿主，充滿主，<br/>我們就必充滿主，<br/>並要將主溢出。<br/>',NULL,12592,12592);
INSERT INTO stanza VALUES('CS904','3','應當喜樂！憑信唱歌！<br/>任何試煉，<br/>只要住主裡面！<br/>我們快樂往前走，<br/>往前走，往前走；<br/>無論夜是多麼暗，<br/>有主就可安然。<br/>',NULL,12593,12593);
INSERT INTO stanza VALUES('CS904','4','站穩，弟兄！<br/>站穩，姊妹！<br/>爭戰快停，<br/>靈裡剛強前行，<br/>一直等到主再來，<br/>主再來，主再來。<br/>一直等到主再來，<br/>同作王到萬代。<br/>',NULL,12594,12594);
INSERT INTO stanza VALUES('CS905','1','喜樂，喜樂，<br/>新郎快來到，<br/>時候必不再耽擱。<br/>不久那婚娶之晨臨到，<br/>我們歡唱新詩歌。<br/>',NULL,12595,12595);
INSERT INTO stanza VALUES('CS905','chorus','哦，美妙日！<br/>哦，榮耀之晨！<br/>當基督我愛來臨，<br/>我們器皿充滿，<br/>燈都發光，<br/>出去迎接祂回來。<br/>喜樂，喜樂，<br/>新郎快來到，<br/>時候必不再耽擱；<br/>不久那婚娶之晨臨到，<br/>我們歡唱新詩歌。<br/>',NULL,12596,12596);
INSERT INTO stanza VALUES('CS905','2','讓我們贖回每寸光陰，<br/>買更多貴重的油；<br/>當夜半呼聲響起時候，<br/>全人已被主浸透。<br/>',NULL,12597,12597);
INSERT INTO stanza VALUES('CS905','3','哦，何等歡樂！<br/>我們豫備，<br/>等候基督來迎娶；<br/>為著這樣榮耀的獎賞，<br/>痛苦試煉不介意！<br/>',NULL,12598,12598);
INSERT INTO stanza VALUES('CS905','4','哦，當那婚娶之日臨到，<br/>將是何等大歡樂。<br/>與主一同作王一千年，<br/>飽享羔羊的婚筵。<br/>',NULL,12599,12599);
INSERT INTO stanza VALUES('CS906','1','恩主，我心所愛，<br/>求你快回來，<br/>與我永同在，<br/>讓我緊貼你胸前，<br/>瞻仰你光榮慈顏，<br/>得以面對面吐意傾心，<br/>述說你我闊別思念。<br/>恩主，我愛你，<br/>愛主！我親你，我戀你，<br/>猶如朝鹿慕溪，<br/>乾旱久候雲霓，<br/>望眼欲穿，此心欲碎，<br/>相思之苦，何日得慰，<br/>此情垂聽。<br/>',NULL,12600,12600);
INSERT INTO stanza VALUES('CS906','2','愛主！我心所好，<br/>你是我至寶；<br/>圍你魂繚繞。<br/>我真愛你，真慕你，<br/>深願時刻在一起，<br/>形影不分離，雖在睡夢，<br/>仍然切切把你掛記。<br/>此情和此境，愛主！<br/>人間語怎表明？<br/>我心被你溶化，<br/>一切為你丟下，<br/>因宇宙間誰能比你<br/>慈愛無涯，憐憫無底？<br/>主阿！來罷！<br/>',NULL,12601,12601);
INSERT INTO stanza VALUES('CS906','3','榮主！我心所屬，<br/>你是我良牧，<br/>有你心滿足。<br/>十架上，你命捐棄，<br/>流寶血買我歸你，<br/>我今把自己，一切，<br/>今後永遠專一奉獻作祭，<br/>主阿！快回來<br/>享受我所有和情愛，<br/>我的愛如膏傾，<br/>遠超屬世人情，<br/>天長地久，與你連理；<br/>海枯石爛，此志不移。<br/>心懇！阿們！<br/>',NULL,12602,12602);
INSERT INTO stanza VALUES('CS906','4','甜主！我心所繫，<br/>恨不插雙翼，<br/>飛投你懷裡，<br/>多少次舉目望天，<br/>等候你駕雲顯現；<br/>提接你面前，<br/>誰知榮影無蹤，<br/>雲彩依然翩翩。<br/>天哪！別留祂！<br/>看我傷心，淚哭無涯！<br/>主！你豈能安息，<br/>任我思愛成疾？<br/>愛主，你何忍再延待？<br/>無論如何，求你快來，<br/>此願成全！<br/>',NULL,12603,12603);
INSERT INTO stanza VALUES('CS907','1','別了！世界，<br/>別了！世界，<br/>讓這世界過去！<br/>主快來了，主快來了！<br/>我還留戀甚麼？<br/>別了！安逸，<br/>別了！糜爛，<br/>別了！屬地享受；<br/>別了！所有纏累重量！<br/>從此不再回頭！<br/>『安逸、』『糜爛，』可以自行更改，如『錢財、』『地位、』『電視』等。<br/>',NULL,12604,12604);
INSERT INTO stanza VALUES('CS908','1','看！無花果樹早已發枝，<br/>聖城被踐踏，日期滿足；<br/>哦，阿利路亞，<br/>我們真有福，<br/>要親眼看見得贖之日！<br/>我們這一代，<br/>末了的一代，<br/>一定要把主迎接回來！<br/>',NULL,12605,12605);
INSERT INTO stanza VALUES('CS908','2','不要被今生思慮累住，<br/>不要像世人貪戀前途；<br/>快出所多瑪，<br/>快進入方舟，<br/>天天都過著召會生活。<br/>趁這個時候，<br/>當挺身昂首，<br/>多搶救靈魂，帶人得救！<br/>',NULL,12606,12606);
INSERT INTO stanza VALUES('CS908','3','願主保守<br/>你的靈、魂、體，<br/>所有的聚集你都能去。<br/>也許那一次，<br/>我們正聚集，<br/>讚美到高潮，主突然到！<br/>不知不覺中，<br/>立刻就被提，<br/>唱阿利路亞，在榮耀裡。<br/>',NULL,12607,12607);
INSERT INTO stanza VALUES('CS909','1','看哪！世上的國已成了<br/>我主基督的國！<br/>眾聖歡呼因祂作王，<br/>永永遠遠坐寶座！<br/>千千萬萬立即響應，<br/>和聲爆發同歌謳！<br/>基督已經得勝！<br/>',NULL,12608,12608);
INSERT INTO stanza VALUES('CS909','chorus','得勝！得勝！阿利路亞！<br/>得勝！得勝！阿利路亞！<br/>得勝！得勝！阿利路亞！<br/>基督已經得勝！<br/>',NULL,12609,12609);
INSERT INTO stanza VALUES('CS909','2','那古蛇，大龍，<br/>就是魔鬼已經被摔下去，<br/>撒但和他的使者<br/>不能再迷惑設騙局，<br/>我們頌讚之聲<br/>如同雷鳴將主永高舉。<br/>基督已經得勝！<br/>',NULL,12610,12610);
INSERT INTO stanza VALUES('CS909','3','『救恩、能力、國度，<br/>並祂基督的權柄到了！<br/>因那晝夜控告我們弟兄的<br/>已被摔倒，』<br/>如今召會正在地上<br/>執行天上的宣告，<br/>基督已經得勝！<br/>',NULL,12611,12611);
INSERT INTO stanza VALUES('CS909','4','我們勝過那控告者，<br/>因為寶血有功效，<br/>藉著口中的話，<br/>我們宣告：<br/>『一切都成了！』<br/>我們雖至於死，<br/>魂生命也不愛惜計較。<br/>基督已經得勝！<br/>',NULL,12612,12612);
INSERT INTO stanza VALUES('CS909','5','哦！弟兄們，姊妹們，<br/>請聽天上又發聲音：<br/>『巴比倫傾倒，<br/>傾倒了！』<br/>─怎能不令人歡欣。<br/>我們已從她出來，<br/>何等有福又可慶幸！<br/>基督已經得勝！<br/>',NULL,12613,12613);
INSERT INTO stanza VALUES('CS909','6','奧祕大巴比倫，<br/>她乃是眾淫婦的母親，<br/>我們極其憎惡<br/>她所裝滿的污穢邪淫；<br/>但神已加倍罰她，<br/>因此我們靈歡欣，<br/>基督已經得勝！<br/>',NULL,12614,12614);
INSERT INTO stanza VALUES('CS909','7','救恩、榮耀、權能，<br/>都屬我們的神，<br/>讚美主！祂憑真實公義，<br/>討罪伸冤，審判了淫婦。<br/>看！<br/>那燒她的煙直往上冒，<br/>讓我們歡呼！<br/>基督已經得勝！<br/>',NULL,12615,12615);
INSERT INTO stanza VALUES('CS909','8','『神的眾僕，無論大小，<br/>當讚美神，』祂囑咐；<br/>如同眾水的聲音，<br/>又如雷鳴，群眾同歡呼：<br/>『阿利路亞！<br/>我們的神全能者<br/>作王作主！』<br/>基督已經得勝！<br/>',NULL,12616,12616);
INSERT INTO stanza VALUES('CS909','9','現在我們應當歡喜<br/>快樂向神歸榮耀；<br/>羔羊婚娶時候到了，<br/>新婦也已豫備好，<br/>蒙了救恩穿上<br/>光明潔白的細麻義袍，<br/>基督已經得勝！<br/>',NULL,12617,12617);
INSERT INTO stanza VALUES('CS909','10','魔鬼身在火湖，<br/>這是約翰目睹的事實，<br/>今後不要怕他信口雌黃，<br/>或造謠生事，<br/>大膽宣告他的判辭，<br/>是聖徒得勝之路！<br/>基督已經得勝！<br/>',NULL,12618,12618);
INSERT INTO stanza VALUES('CS909','11','看哪！最大的奇景─<br/>新耶路撒冷由天降！<br/>基督新婦妝飾整齊<br/>模成基督的模樣；<br/>神人調和建造一起<br/>顯出神榮耀形像，<br/>基督已經得勝！<br/>',NULL,12619,12619);
INSERT INTO stanza VALUES('CS909','12','這是神在人間支搭帳幕，<br/>神人永同住，<br/>神的聖潔、榮耀，<br/>從人身上完全的顯出！<br/>聽哪！主在宣告：<br/>『都成了！』<br/>神已心滿意足，<br/>基督已經得勝！<br/>',NULL,12620,12620);
INSERT INTO stanza VALUES('CS909','chorus','阿利路亞！阿利路亞！<br/>阿利路亞！阿利路亞！<br/>阿利路亞！阿利路亞！<br/>基督已經得勝！<br/>',NULL,12621,12621);
INSERT INTO stanza VALUES('CS910','1','我們曾頂羨慕<br/>門徒在高山上，<br/>親眼看見你改變形像，<br/>你面貌像日頭<br/>顯出何等榮光，<br/>你衣裳潔白何等明亮！<br/>現在我們<br/>每當想到你快回來，<br/>我們就立刻喜樂滿懷，<br/>因為在還沒有<br/>嘗到死味之先，<br/>同樣要看見你的顯現！<br/>',NULL,12622,12622);
INSERT INTO stanza VALUES('CS910','2','那一次門徒們<br/>看見你的改變，<br/>雖然是真好，卻是有限，<br/>因為你那時候，<br/>還沒有經過死，<br/>不過是父懷中的愛子。<br/>如今你再來到，<br/>要得完全榮耀；<br/>千萬的聖徒，讚賞不置！<br/>你是萬王之王，<br/>你是萬主之主，<br/>你要與你的百姓同住。<br/>',NULL,12623,12623);
INSERT INTO stanza VALUES('CS910','3','主，我們讚美你，<br/>不只你得榮耀，<br/>也要把眾子帶進榮耀！<br/>我們原是罪人，<br/>在你眼中蒙恩，<br/>為要變成你愛的標本。<br/>我們原是泥土，<br/>竟然要變寶石，<br/>等候著在榮耀裡顯出。<br/>即使在永世裡，<br/>我們也唱不盡，<br/>愛戴之情與感激之心！<br/>',NULL,12624,12624);
INSERT INTO stanza VALUES('CS911','1','時候快要到了，<br/>主要醡葡萄！<br/>吸滿地汁，<br/>滴滴都要醡出！<br/>主是一無所有，<br/>如根出乾地，你怎能彀<br/>與『地』這麼親密？<br/>',NULL,12625,12625);
INSERT INTO stanza VALUES('CS911','chorus','快起來脫離『地』，<br/>快搶救自己，<br/>作初熟的果子，<br/>歸神與主。<br/>',NULL,12626,12626);
INSERT INTO stanza VALUES('CS911','2','時候快要滿足，<br/>主要收麥子！<br/>麥子要熟，<br/>需斷『地』的享受；<br/>牠的裡頭飽滿，<br/>外面卻枯乾；主作一切，<br/>就不需要世界。<br/>',NULL,12627,12627);
INSERT INTO stanza VALUES('CS911','3','作初熟的果子，<br/>是何等有福！<br/>得享婚筵，<br/>又得同掌王權！<br/>不要等待世界<br/>來把你對付，趁有今日，<br/>自動丟棄糞土。<br/>',NULL,12628,12628);
INSERT INTO stanza VALUES('CS912','1','我們燈裡有油，<br/>靈裡焚燒，<br/>我們燈裡有油，今朝！<br/>主，不斷使我們<br/>轉到靈裡，<br/>使油源源不絕，燈不熄。<br/>哦主！阿們！阿利路亞！<br/>我們晝夜焚燒，燈不熄！<br/>哦主！阿們！阿利路亞！<br/>不斷轉回到靈裡！<br/>',NULL,12629,12629);
INSERT INTO stanza VALUES('CS912','2','但我們的器皿必須有油，<br/>你來時纔不致蒙羞。主，<br/>浸透我們魂每一角落，<br/>好叫我們全人滿了油。<br/>哦！主耶穌，充滿我們，<br/>每時每刻賜下你自己！<br/>哦！主耶穌，浸透我們，<br/>使我們滿了實際。<br/>',NULL,12630,12630);
INSERT INTO stanza VALUES('CS912','3','滿了油纔能彀不斷焚燒，<br/>直到主那一日來到。<br/>我們要與新郎一同坐席，<br/>光明燦爛歡然渡佳期。<br/>主阿，快來！<br/>主阿，快來！<br/>來看我們充滿且發光；<br/>主阿，快來！<br/>主阿，快來！<br/>接你佳偶永同享！<br/>',NULL,12631,12631);
INSERT INTO stanza VALUES('CS913','1','十個童女迎接新郎，<br/>為何結局不一樣？<br/>聰明愚拙都將燈點，<br/>器皿的油是關鍵。<br/>趁著今日趕緊豫備，<br/>讓靈充滿魂浸透；<br/>儆醒等候直到主來，<br/>可以同祂享愛筵。<br/>',NULL,12632,12632);
INSERT INTO stanza VALUES('CS913','2','三個僕人都有銀子，<br/>為何結局不一樣？<br/>因那忠僕隨即買賣，<br/>惡僕卻將銀子埋。<br/>快將一千銀子擺出，<br/>在召會裡同經營；<br/>忠心事奉，直到主來，<br/>可以從祂得賞賜。<br/>',NULL,12633,12633);
INSERT INTO stanza VALUES('CS913','3','不多時候，要來就來，<br/>我們儆醒齊等待，<br/>不可辜負主的委派，<br/>忠心良善得賞賚。<br/>基督臺前，審判鐘點，<br/>主的公義威榮顯，<br/>金銀寶石能耐火焰，<br/>千年國度掌王權。<br/>',NULL,12634,12634);
INSERT INTO stanza VALUES('CS914','1','這個世代已將結束，<br/>十個童女手拿著燈，<br/>出去迎接可愛新郎，<br/>五個愚拙，五個聰明。<br/>那聰明的油是充滿，<br/>那愚拙的油卻將盡；<br/>及時買油纔是聰明，<br/>勿成愚拙，到時飲恨。<br/>',NULL,12635,12635);
INSERT INTO stanza VALUES('CS914','2','主耶穌，你話彀清楚，<br/>你為聰明童女而來。<br/>他們趁著今天買油，<br/>對付所有捆綁阻礙；<br/>他們的全魂已被變化，<br/>靈充滿了他們全人，<br/>他們在此儆醒等候，<br/>就必得享你的婚筵。<br/>',NULL,12636,12636);
INSERT INTO stanza VALUES('CS914','3','燈是我靈須修明亮，<br/>藉著每日呼喊你名。<br/>天天操練活在靈中，<br/>燒去所有老舊光景。<br/>哦主，求你扎根生長，<br/>擴展到我的魂裡去；<br/>直到你安家在我心，<br/>油自器皿充滿洋溢。<br/>',NULL,12637,12637);
INSERT INTO stanza VALUES('CS914','4','看！這世代何等黑暗，<br/>有福日子已經接近。<br/>我們新郎隨時會來，<br/>須快豫備為那時辰。<br/>何等蒙福，得享婚筵，<br/>看見新婦與主合一！<br/>主，使我們活你面前，<br/>如同那些聰明童女！<br/>',NULL,12638,12638);
INSERT INTO stanza VALUES('CS915','1','一天，約在黃昏時分，<br/>亞伯拉罕的僕人，<br/>為著尋找新婦，<br/>在井旁駐足。<br/>那利百加適時而至，<br/>所行印證出乎主；<br/>僕人不虛此行，<br/>因為神賜福。<br/>',NULL,12639,12639);
INSERT INTO stanza VALUES('CS915','chorus','哦，快快豫備，<br/>夜幕將低垂，<br/>且聽那老僕人頻頻催！<br/>喜事已經近在眼前，<br/>不久我們要歡祝；<br/>駝隊帶新婦到以撒帳幕。<br/>',NULL,12640,12640);
INSERT INTO stanza VALUES('CS915','2','如今聖靈受父差遣，<br/>帶來基督的豐富，<br/>同樣為要尋找<br/>聖潔的新婦。<br/>我們以撒在父家裡，<br/>已經豫備好帳幕，<br/>巴望接利百加<br/>到他身旁住。<br/>',NULL,12641,12641);
INSERT INTO stanza VALUES('CS915','3','我們欣然離開親友，<br/>向這世界說再見；<br/>我們已蒙呼召，<br/>完全歸給主。<br/>不久脫盡斑點皺紋，<br/>面見我們主耶穌，<br/>何等喜樂<br/>我們是榮耀新婦！<br/>',NULL,12642,12642);
INSERT INTO stanza VALUES('CS1001','1','神完整的救恩<br/>是本於祂的義，<br/>並藉著我們的信。<br/>憑兩個神聖的遷移：<br/>從亞當裡遷到基督裡；<br/>並從肉體裡遷到那靈裡。<br/>在一個屬靈的聯結裡：<br/>生命的靈與我們的靈，<br/>聯結成為一個調和的靈。<br/>使我們藉著洋溢之恩<br/>並洋溢之義的恩賜，<br/>在生命中作王。<br/>',NULL,12643,12643);
INSERT INTO stanza VALUES('CS1002','1','神重生我們，<br/>使我們得有<br/>祂的神聖生命；<br/>更新我們，使我們成為<br/>祂的神聖新造；<br/>聖別我們，使我們得有<br/>祂的聖別性情；<br/>變化我們，使我們得有<br/>祂的神聖形像。<br/>模成我們，使我們得有<br/>祂的神聖成分；<br/>榮化我們，使我們全有<br/>祂的神聖形像。<br/>我們憑神生機的救恩，<br/>在祂的生命中作王，<br/>成功祂永遠的經綸，<br/>達到祂神聖的目的。<br/>',NULL,12644,12644);
INSERT INTO stanza VALUES('CS1003','1','經過過程<br/>終極完成的三一神，<br/>照著祂的心愛美意，<br/>為著祂經綸最高的目的，<br/>正將祂自己<br/>和祂所揀選的人，<br/>相互建造到彼此裡面，<br/>好使祂在基督裡<br/>得著神性調和<br/>人性的一個構成，<br/>作祂的生機體，<br/>就是基督的身體，<br/>成為祂永遠的彰顯，<br/>並救贖之神與蒙救贖之人<br/>相互的居所。<br/>這個奇妙珍寶構成的<br/>終極完成，<br/>乃是新耶路撒冷，<br/>直存到永遠。<br/>註：此首詩辭編譯自李常受弟兄墓前碑文。<br/>',NULL,12645,12645);
INSERT INTO stanza VALUES('CS1004','1','神永遠的經綸，<br/>乃是要使人在生命、<br/>性情上，<br/>但不在神格上，<br/>與祂一模一樣，<br/>並使祂自己與人成為一，<br/>使人與祂成為一，<br/>因而使祂在彰顯上<br/>得以擴大並擴展，<br/>使祂一切神聖的屬性<br/>得以彰顯在人性美德裡。<br/>',NULL,12646,12646);
INSERT INTO stanza VALUES('CS1005','1','神在宇宙中歷世歷代<br/>獨一中心的工作，<br/>乃是要在基督裡<br/>將祂自己建造到<br/>祂揀選的人裡面，<br/>使祂自己與他們成為一。<br/>在神這中心的<br/>建造工作中，<br/>神將祂神聖的元素<br/>構造到人的元素裡，<br/>並將人的元素<br/>構造到神的元素裡。<br/>神這中心的工作<br/>有一個奇妙的過程，<br/>就是神成了人，<br/>為要使人在生命、<br/>性情上，<br/>但不在神格上成為神。<br/>神這中心工作的<br/>終極完成，<br/>乃是新耶路撒冷，<br/>就是經過過程<br/>並終極完成的三一神，<br/>與蒙祂重生、變化<br/>並榮化之三部分選民，<br/>相調和的生機構成。<br/>',NULL,12647,12647);
INSERT INTO stanza VALUES('BF1','1','Dearest Lord, You''ve called us here,<br/>And opened up Your heart.<br/>O the joy to hear Your call<br/>And enter in the Ark.<br/>Saving us from day to day<br/>O Lord this is Your way.<br/>In Yourself we stay afloat,<br/>Above this wicked age today.<br/>',NULL,13834,13834);
INSERT INTO stanza VALUES('BF1','chorus','Thank You Lord, in Your eyes we find grace,<br/>And with open hearts we come to You.<br/>Regardless what our friends<br/>Might say to us or do,<br/>O Lord Jesus, we love You.<br/>',NULL,13835,13835);
INSERT INTO stanza VALUES('BF1','2','Seeking of this age to taste,<br/>And of it have a part<br/>If we only knew dear Lord,<br/>The way we grieve Your heart.<br/>We would come and turn to You<br/>With a repenting heart.<br/>And would give ourselves to be<br/>With You O Lord, inside the Ark.<br/>',NULL,13836,13836);
INSERT INTO stanza VALUES('BF1','3','Praise You Lord, we''re safe in You;<br/>Outside death-waters pour.<br/>Many things that I once loved<br/>Are on the ocean floor.<br/>Keep us open to You, Lord,<br/>Don''t let us miss the mark.<br/>Hallelujah, Praise the Lord,<br/>We''re here within the church, the Ark.<br/>',NULL,13837,13837);
INSERT INTO stanza VALUES('BF2','chorus','Draw me dear Lord;<br/>Draw me today<br/>From everything else dear Lord<br/>Draw me away. (today.)<br/>',NULL,13838,13838);
INSERT INTO stanza VALUES('BF2','1','O Lord this whole world<br/>Seems to weigh me down<br/>All the cares, the strife, the sin<br/>Within me and all around.<br/>',NULL,13839,13839);
INSERT INTO stanza VALUES('BF2','2','But Lord I want to set my heart;<br/>And Lord I want to stay with You;<br/>''Cause only when<br/>You''re near to me is everything okay.<br/>',NULL,13840,13840);
INSERT INTO stanza VALUES('BF2','3','And though everything may fall apart<br/>Or everything go my way;<br/>It doesn''t really matter, Lord<br/>As long as I gain You today!<br/>',NULL,13841,13841);
INSERT INTO stanza VALUES('BF3','1','He giveth more grace when the burdens grow greater,<br/>He sendeth more strength when the labors increase,<br/>To added affliction He addeth His mercy,<br/>To multiplied trials, His multiplied peace.<br/>',NULL,13842,13842);
INSERT INTO stanza VALUES('BF3','chorus','His love has no limit, His grace has no measure,<br/>His power no boundary known unto men,<br/>For out of His infinite riches in Jesus,<br/>He giveth and giveth and giveth again.<br/>',NULL,13843,13843);
INSERT INTO stanza VALUES('BF3','2','When we have exhausted our store of endurance,<br/>When our strength has failed ere the day is half-done,<br/>When we reach the end of our hoarded resources,<br/>Our Father''s full giving is only begun.<br/>',NULL,13844,13844);
INSERT INTO stanza VALUES('BF4','1','I once was dead — dead in my sins;<br/>Behaved myself in lust of flesh.<br/>By nature, such a child of wrath,<br/>Even as the rest.<br/>',NULL,13845,13845);
INSERT INTO stanza VALUES('BF4','2','But God being so merciful<br/>Because of His great love to me<br/>Enlivened me, I''m now with Christ<br/>Seated in the heavenlies.<br/>',NULL,13846,13846);
INSERT INTO stanza VALUES('BF4','3','But that''s not all! I''m with the saints.<br/>Together we''re his workmanship,<br/>His masterpiece, expressing Him<br/>In the heavens and on earth.<br/>',NULL,13847,13847);
INSERT INTO stanza VALUES('BF4','4','I was once apart from Christ, you know.<br/>Alien from the wealth of Israel.<br/>Not a hope, not even one to tell.<br/>Without God in the world.<br/>',NULL,13848,13848);
INSERT INTO stanza VALUES('BF4','5','Now in Christ He has become my peace.<br/>By the blood of Christ I am released.<br/>I am one with all the saints, since He''s<br/>Broken down the middle wall.<br/>',NULL,13849,13849);
INSERT INTO stanza VALUES('BF4','6','He has died creating one new man<br/>Thus fulfilling God''s eternal plan.<br/>With all saints together let us stand;<br/>Shout and sing and praise the Lord!<br/>',NULL,13850,13850);
INSERT INTO stanza VALUES('BF5','1','Lord, You are beloved, fairest of the fair;<br/>Altogether lovely, unrivaled beauty;<br/>It''s You! Your presence, I long for and seek;<br/>You''re the One in whom my heart delights,<br/>So, I just love to tell You...<br/>',NULL,13851,13851);
INSERT INTO stanza VALUES('BF5','chorus','Jesus, I love You,<br/>My treasure You are;<br/>How could I choose anything less than You?<br/>Dear Lord, my inmost heart<br/>You''ve captured and won.<br/>',NULL,13852,13852);
INSERT INTO stanza VALUES('BF5','2','Dead I was in sin Lord, so lost without You;<br/>Helpless, wounded, weary, rebellious, too;<br/>But Lord, You came! You would not let me go;<br/>The blood and water flowed from Your side,<br/>Constraining me to tell You...<br/>',NULL,13853,13853);
INSERT INTO stanza VALUES('BF5','3','Thank You Lord, You opened my blind eyes to see;<br/>I was lame, but now I can walk: You healed me!<br/>My leprosy, Lord, You cleansed all away;<br/>My ears were opened to hear Your voice,<br/>And now I follow You ''cause...<br/>',NULL,13854,13854);
INSERT INTO stanza VALUES('BF5','4','Sometimes Lord, I''m drawn off by my selfish cares;<br/>And the world it draws me with glitter and glare.<br/>O Lord, You''ve trapped me, don''t let me go!<br/>Kiss me and woo me, and win my heart,<br/>So, I will always tell You...<br/>',NULL,13855,13855);
INSERT INTO stanza VALUES('BF5','5','Keep my heart so soft, Lord, so open to You;<br/>It would be the good ground to bear fruit for You;<br/>Capture my friends Lord, and build us, I pray;<br/>Your bride, we''d match You in every way,<br/>And, corporately we tell You:<br/>',NULL,13856,13856);
INSERT INTO stanza VALUES('BF5','chorus','Jesus, Come quickly, we''re waiting for You;<br/>We''re the virgins to You, Lord,<br/>So single and true;<br/>Forever and ever Your counterpart true.<br/>',NULL,13857,13857);
INSERT INTO stanza VALUES('BF6','1','Mary poured out her love offering.<br/>To many such love was a waste.<br/>Throughout all of the centuries<br/>Such lovers Your sweetness do taste.<br/>Precious lives and heart treasures, too<br/>Positions and golden futures<br/>Have been "wasted" on You, Lord,<br/>Your sweetness — a fragrance so sure.<br/>She took opportunity to love You, Lord, with her best.<br/>Like her, Lord, I too would pour my love and all that I have.<br/>',NULL,13858,13858);
INSERT INTO stanza VALUES('BF6','2','As I love You I set my being —<br/>My spirit, my soul and body —<br/>With my heart, my mind and my strength<br/>Absolutely on Thee.<br/>Lord, I let my entire being<br/>Be occupied by Thee.<br/>As I enter in Your heart<br/>I sense a fellowship sweet.<br/>Occupied and lost in You, my Lord, You''re my everything.<br/>Fellowship so intimate; in spirit, Lord, I enjoy Thee.<br/>',NULL,13859,13859);
INSERT INTO stanza VALUES('BF6','3','Lord, there''s none in heav''n nor on earth<br/>That I desire but Thee.<br/>Though my heart and flesh faileth, Lord,<br/>Thou ever my portion will be.<br/>All is vanity, all is dung —<br/>I count all other things loss.<br/>Everything else drains my love,<br/>But You have captured my heart.<br/>Lord I''ve seen Thy preciousness, Thy worth, Thy reality.<br/>Now, my Lord, I must confess, my heart is only for Thee.<br/>',NULL,13860,13860);
INSERT INTO stanza VALUES('BF7','1','Morning dawn had arisen,<br/>Abraham saddled his donkey,<br/>Took his two young men with him<br/>And Isaac, his beloved son.<br/>Lord You''re God''s only Son<br/>And of God begotten<br/>"This is My beloved Son, in whom<br/>I am well-pleased."<br/>',NULL,13861,13861);
INSERT INTO stanza VALUES('BF7','2','To his young men he said then<br/>"Stay and we''ll return to you"<br/>To Moriah he led him,<br/>His son Isaac — just them two.<br/>Just the son and the father<br/>Speaking with one another<br/>Isaac said, "My father!"<br/>Abraham said, "Here I am,"<br/>',NULL,13862,13862);
INSERT INTO stanza VALUES('BF7','3','As You spoke with Your Father<br/>You bore the wood God laid on You;<br/>As a lamb to the slaughter<br/>Obedient to the death were You.<br/>Precious blood of a lamb,<br/>Slain before earth began,<br/>Laid Your life down for your sheep, in love<br/>That I might live.<br/>',NULL,13863,13863);
INSERT INTO stanza VALUES('BF7','4','Man of sorrows, I love You.<br/>From You men did hide their face.<br/>With no majesty to You,<br/>Despised, forsaken, and disgraced,<br/>For my sins You were crushed,<br/>Lord, I love You so much,<br/>Chastened, scourged and then pierced through,<br/>My griefs and sorrows bore.<br/>',NULL,13864,13864);
INSERT INTO stanza VALUES('BF7','5','Dead in sins and offenses,<br/>I''m a bruised reed — smoking flax<br/>Yet to death You were given<br/>For of Your sheep, You''d not lose one.<br/>Like the woman, I''d weep<br/>Flow my tears at Your feet<br/>Jesus Lord, I just love You — dear Lord<br/>Jesus my Lord.<br/>',NULL,13865,13865);
INSERT INTO stanza VALUES('BF8','chorus','O that Christ may make His home in my heart,<br/>Spread Himself in every part!<br/>Saturate and life impart!<br/>That with all saints, I may apprehend<br/>All the vast dimensions of my loving Christ.<br/>',NULL,13866,13866);
INSERT INTO stanza VALUES('BF8','1','Father God, forgive me if I groan;<br/>For so long I''ve been on a plateau.<br/>Now with tears, I bow my knees and pray<br/>By Your Spirit make my spirit strong today.<br/>',NULL,13867,13867);
INSERT INTO stanza VALUES('BF8','2','As I came this morning to Your word<br/>With no strength to even read a verse;<br/>Yet my plea, is "Lord, I do need You!"<br/>How You strengthen me, Your power within to prove.<br/>',NULL,13868,13868);
INSERT INTO stanza VALUES('BF8','3','I myself was losing heart each day;<br/>Then the Lord brought some saints my own way;<br/>I alone could not Thee apprehend<br/>But with all the saints You now my joy have been.<br/>',NULL,13869,13869);
INSERT INTO stanza VALUES('BF8','4','All these years I''ve come the church to know,<br/>Yet O Lord, there''re things I can''t let go;<br/>Yet within me there is an "Amen";<br/>O now joy I never knew in me''s flowin''.<br/>',NULL,13870,13870);
INSERT INTO stanza VALUES('BF9','1','What shall I give unto the Lord<br/>For all, for all, for all He''s done for me?<br/>I''ll take the cup of salvation,<br/>And call, and call, and call upon the name of the Lord.<br/>',NULL,13871,13871);
INSERT INTO stanza VALUES('BF10','1','Dearest Lord, I come;<br/>This is now my pray''r,<br/>Keep me open to You,<br/>May I always love You.<br/>',NULL,13872,13872);
INSERT INTO stanza VALUES('BF10','chorus','Lord, I love You more today,<br/>So much more than yesterday;<br/>Lord, I need You<br/>Lord, I love You.<br/>',NULL,13873,13873);
INSERT INTO stanza VALUES('BF10','2','Now that the choice is mine,<br/>Lord, I still choose You;<br/>''Though the paths be not marked,<br/>I''m still trusting in You.<br/>',NULL,13874,13874);
INSERT INTO stanza VALUES('BF10','3','And if the way is hard,<br/>If things don''t go my way,<br/>Keep my heart soft to You,<br/>Keep me open to You.<br/>',NULL,13875,13875);
INSERT INTO stanza VALUES('BF10','4','Dearest Lord, I pray,<br/>Lead me ev''ry day;<br/>Don''t let things come between,<br/>Keep my eyes fixed on You.<br/>',NULL,13876,13876);
INSERT INTO stanza VALUES('BF10','5','When many years have gone,<br/>And many things have passed,<br/>I will still be for You,<br/>I will still say to You:<br/>',NULL,13877,13877);
INSERT INTO stanza VALUES('BF11','1','Press on,  Press on, toward the goal —<br/>The all inclusive Christ.<br/>To gain the prize of God''s high call;<br/>Press on, Press on to Christ.<br/>',NULL,13878,13878);
INSERT INTO stanza VALUES('BF11','chorus','Pressing on! Pressing on!<br/>Pressing on! Hallelujah for the prize!<br/>We''re pressing on! On and on!<br/>To gain the Christ of God.<br/>',NULL,13879,13879);
INSERT INTO stanza VALUES('BF11','2','Press on, Press on, count all things loss,<br/>All that is gain to us;<br/>To win the prize, The Christ of God,<br/>Is far more glorious!<br/>',NULL,13880,13880);
INSERT INTO stanza VALUES('BF11','3','Press on, Press on, to know the Lord,<br/>And resurrection power —<br/>Oh! This is our supreme reward,<br/>E''en in the suffering hour.<br/>',NULL,13881,13881);
INSERT INTO stanza VALUES('BF11','4','Press on, Press on, This one thing do,<br/>Forget the things behind;<br/>Press onward to the Christ before,<br/>Press onward with this mind.<br/>',NULL,13882,13882);
INSERT INTO stanza VALUES('BF12','1','Man''s Creator has a purpose for our being here on earth.<br/>In His image we''re created to express His rule on earth.<br/>But man fell to Satan''s tempting; thus God''s goal was hid from view.<br/>Still our God will have His kingdom, for His Son will see it through.<br/>',NULL,13883,13883);
INSERT INTO stanza VALUES('BF12','chorus','Jesus Christ will get His kingdom<br/>In spite of Satan and his plans.<br/>He''s getting something real and solid<br/>By growing in the hearts of man.<br/>It''s nothing like religion teaches:<br/>"You''ll have to wait until you die."<br/>For the kingdom Christ is building<br/>Is here on earth before our eyes.<br/>',NULL,13884,13884);
INSERT INTO stanza VALUES('BF12','2','His Son, Jesus, is our Savior. Once in human form He came.<br/>Now as the Spirit He can enter as the breath of life to man.<br/>As a seed within our spirit Christ takes root and starts to grow,<br/>Spreading in our inmost being till His life we come to know.<br/>',NULL,13885,13885);
INSERT INTO stanza VALUES('BF12','3','Time is short, oh, brothers, hear it! Christ is longing for His bride.<br/>We can hasten His returning simply by the growth in life.<br/>No more struggling, no more striving, simply turn to Christ within.<br/>See the seed begin to blossom, growing fully into Him.<br/>',NULL,13886,13886);
INSERT INTO stanza VALUES('BF12','chorus','Jesus Christ will get His kingdom<br/>By growing in a normal way.<br/>It''s not an instant transformation.<br/>This growth goes on from day to day.<br/>The seed of life is all-inclusive.<br/>It''s got everything we''ll ever need.<br/>Yes, our God''s eternal purpose<br/>Is all within this precious seed.<br/>',NULL,13887,13887);
INSERT INTO stanza VALUES('BF13','1','Jesus, oh living Word of God,<br/>Wash me and cleanse me with Your blood<br/>So You can speak to me.<br/>Just let me hear Your words of grace,<br/>Just let me see Your radiant face,<br/>Beholding constantly.<br/>',NULL,13888,13888);
INSERT INTO stanza VALUES('BF13','chorus','Jesus, living Word,<br/>My heart thirsts for Thee;<br/>Of Thee I''d eat and drink,<br/>Enjoy Thee thoroughly.<br/>',NULL,13889,13889);
INSERT INTO stanza VALUES('BF13','2','Jesus, most precious One to me,<br/>I want to seek You constantly<br/>So You can spread through me.<br/>I would just call upon Your name,<br/>Open to You; I have no shame<br/>Loving You, Jesus Lord.<br/>',NULL,13890,13890);
INSERT INTO stanza VALUES('BF13','chorus','Jesus, precious One,<br/>Be so real to me.<br/>You are all I want;<br/>I open wide to Thee.<br/>',NULL,13891,13891);
INSERT INTO stanza VALUES('BF13','3','Jesus, oh living One in me,<br/>Open my eyes that I might see<br/>All that You are to me.<br/>Just let me enter in Your heart,<br/>Never from You would I depart;<br/>Loving You constantly.<br/>',NULL,13892,13892);
INSERT INTO stanza VALUES('BF13','chorus','Jesus, living One,<br/>Flood me thoroughly;<br/>Take my willing heart<br/>And overcome in me.<br/>',NULL,13893,13893);
INSERT INTO stanza VALUES('BF13','4','Lord, I want You to have Your way,<br/>Save me from being Satan''s prey,<br/>I am believing You.<br/>All I can give to You, my Lord,<br/>Is my whole being, love outpoured;<br/>Lord, I belong to You.<br/>',NULL,13894,13894);
INSERT INTO stanza VALUES('BF13','chorus','Jesus, faithful God,<br/>Gain us through and through;<br/>Use us thoroughly<br/>To see Your purpose through.<br/>',NULL,13895,13895);
INSERT INTO stanza VALUES('BF14','1','Splendid church life! His green garden! He has brought us,<br/>praise the Lord,<br/>To experience the Christ Who''s growing here!<br/>He is full of rich enjoyment to His saints in one accord;<br/>He is new and fresh, available and dear.<br/>',NULL,13896,13896);
INSERT INTO stanza VALUES('BF14','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,13897,13897);
INSERT INTO stanza VALUES('BF14','2','It is not a school or fact''ry or a chapel in the air;<br/>But a garden where our Lord can plant and sow.<br/>So He''s placed us all here corporately to be His garden fair,<br/>Where He''s free to cultivate and make us grow.<br/>',NULL,13898,13898);
INSERT INTO stanza VALUES('BF14','3','Thus within the church-life garden there''s a fruit-producing tree<br/>Full of life and so available to eat.<br/>So be simple, don''t be hardened, drop your concepts - eat that tree!<br/>Take in Jesus every moment - He''s so sweet!<br/>',NULL,13899,13899);
INSERT INTO stanza VALUES('BF14','4','With the tree there is the water, flowing God in Christ to us,<br/>Quenching all our dryness, ending all our strife.<br/>Hallelujah! In His garden Jesus flows Himself to us,<br/>As the full supply for us to grow in life.<br/>',NULL,13900,13900);
INSERT INTO stanza VALUES('BF14','5','Aren''t you satisfied and thankful that our Lord has brought you in<br/>Where His pleasures and His riches flow so free?<br/>So be happy and be joyful, in the spirit feast on Him,<br/>So God''s garden can bear fruit abundantly.<br/>',NULL,13901,13901);
INSERT INTO stanza VALUES('BF15','1','The love of Christ is now constraining me<br/>That I would love and love Him utterly.<br/>His mighty love has touched me deep within<br/>To consecrate my life and all to Him.<br/>',NULL,13902,13902);
INSERT INTO stanza VALUES('BF15','chorus','This charming One so excelling;<br/>To His touch I''m now responding;<br/>To surrender, to surrender to Him.<br/>',NULL,13903,13903);
INSERT INTO stanza VALUES('BF15','2','This tide of love has flowed to me from Him;<br/>Unchanging love that keeps on rushing in.<br/>Now I''m for Him beyond my own control;<br/>He is now my love and my only goal.<br/>',NULL,13904,13904);
INSERT INTO stanza VALUES('BF15','chorus','His dying love so compelling,<br/>And this tide has made me willing<br/>To love Him, I can''t help but love Him.<br/>',NULL,13905,13905);
INSERT INTO stanza VALUES('BF15','3','The love of Christ<br/>Is now constraining me to love Him utterly.<br/>His mighty love<br/>Has touched me deep within to consecrate to Him.<br/>',NULL,13906,13906);
INSERT INTO stanza VALUES('BF15','4','This tide of love<br/>Has flowed to me from Him that keeps on rushing in.<br/>Now I''m for Him<br/>Beyond my own control; He''s now my final goal.<br/>',NULL,13907,13907);
INSERT INTO stanza VALUES('BF16','1','There is a great mystery,<br/>A wonderful story;<br/>For ages ''twas hidden,<br/>Now shown in His wisdom;<br/>''Tis a divine romance<br/>Of God and man in time;<br/>Beyond understanding,<br/>Yet seen in God''s speaking.<br/>',NULL,13908,13908);
INSERT INTO stanza VALUES('BF16','chorus','God fell in love with man;<br/>For only God''s love can<br/>Make man just the same as He<br/>In life and in nature.<br/>We are His expression,<br/>His bride, His enlargement;<br/>Forever, together,<br/>As living, insep''rable as one couple<br/>Eternally.<br/>',NULL,13909,13909);
INSERT INTO stanza VALUES('BF16','2','Though He was rejected<br/>By men who were blinded;<br/>His love is constraining,<br/>His heart still unchanging;<br/>Thus in incarnation<br/>Came He as salvation;<br/>His name is called Jesus,<br/>And He came to seek us.<br/>',NULL,13910,13910);
INSERT INTO stanza VALUES('BF16','3','Though I''ve been a sinner,<br/>I now have been redeemed<br/>By Christ who died for me,<br/>Who was raised in glory.<br/>I am joined to Him now,<br/>Together we''re living;<br/>I love to enjoy Him,<br/>For I''ve been forgiven.<br/>',NULL,13911,13911);
INSERT INTO stanza VALUES('BF16','4','His love is so tender,<br/>To Him I''ll surrender;<br/>His name is so precious,<br/>I gladly call, "Jesus!"<br/>His Person''s so charming,<br/>My heart ever winning;<br/>I''ll hold back no longer,<br/>I''ll love Him forever.<br/>',NULL,13912,13912);
INSERT INTO stanza VALUES('BF17','1','Christ the Spirit has set me free,<br/>I, in spirit will set Him free;<br/>His life freed me from sins'' d''pression,<br/>My speaking is His expression.<br/>',NULL,13913,13913);
INSERT INTO stanza VALUES('BF17','chorus','Hallelujah, glorious freedom!<br/>God, man co-work mingle in one.<br/>',NULL,13914,13914);
INSERT INTO stanza VALUES('BF17','2','I in Christ''s life He liberates,<br/>Freed from sin and worldly bondage;<br/>With my future all forsaken,<br/>In the spirit thus I''ve taken.<br/>',NULL,13915,13915);
INSERT INTO stanza VALUES('BF17','3','In the spirit Christ is so rich,<br/>I may now experience and reach;<br/>Christ I release with spirit high,<br/>Power and wisdom will be mine.<br/>',NULL,13916,13916);
INSERT INTO stanza VALUES('BF17','4','O Lord, from all doctrines free me,<br/>From old teachings, Lord, set me free;<br/>Daily in the spirit labor,<br/>Thus, the glorious Christ to savor.<br/>',NULL,13917,13917);
INSERT INTO stanza VALUES('BF17','5','Christ is manifested through me,<br/>Men behold His beauty in me;<br/>My heart filled with His joy will be,<br/>When I set Him at liberty.<br/>',NULL,13918,13918);
INSERT INTO stanza VALUES('BF17','6','Lord, I''m dropping here before Thee,<br/>All self-seeking that''s found in me;<br/>Dropping my own feeling and pride,<br/>Let my spirit be exercised.<br/>',NULL,13919,13919);
INSERT INTO stanza VALUES('BF18','1','From the time I spoke Your name,<br/>Lord, my life''s not been the same<br/>Since I called on the only One who''d save me.<br/>When forsaken, in despair<br/>Who''d have thought that You''d be there!<br/>Now I’ve found out, Jesus, You''re alive!<br/>',NULL,13920,13920);
INSERT INTO stanza VALUES('BF18','chorus','Now my eyes begin to see<br/>I''m living as I ought to be,<br/>As this turning, burning God<br/>Moves in my heart<br/>I don''t care now how I feel;<br/>I just know that this is real,<br/>And I know, oh Jesus, You''re alive!<br/>',NULL,13921,13921);
INSERT INTO stanza VALUES('BF18','2','It''s no statue that I call,<br/>Not a picture on the wall,<br/>But a Person who lives His life within me.<br/>Wish they''d told me long before,<br/>All You want is an open door<br/>And that really, Jesus, You''re alive!<br/>',NULL,13922,13922);
INSERT INTO stanza VALUES('BF19','1','Lord, You love me so immensely;<br/>I would love You more intensely.<br/>Every day and every moment,<br/>O Lord, capture me.<br/>Let my goal and my life''s theme be,<br/>Lord, to love You more supremely;<br/>With all my heart, Lord Jesus,<br/>Keep me faithful unto Thee.<br/>',NULL,13923,13923);
INSERT INTO stanza VALUES('BF19','2','Draw me, Lord, each day.<br/>Take my veils away.<br/>With a pure heart will I seek You;<br/>Lord I just love You.<br/>Nothing else I seek;<br/>No one else for me.<br/>I would fully and absolutely<br/>Give my whole being unto Thee.<br/>',NULL,13924,13924);
INSERT INTO stanza VALUES('BF20','1','The Bible is God''s breath,<br/>The essence of His Person;		(2 Timothy 3:16)<br/>God''s speaking out through men<br/>Borne by the Holy Spirit.			(2 Pet. 1:21)<br/>The Bible is God''s speaking<br/>In the prophets, in the Son.		(Heb. 1:1-2)<br/>The Bible is the Holy Spirit''s revelation.	(John 16:13)<br/>',NULL,13925,13925);
INSERT INTO stanza VALUES('BF20','2','The Bible testifies<br/>Concerning the Lord Jesus.		(John 5:39)<br/>The Bible makes men wise,<br/>Wise unto salvation.			(2 Timothy 3:15)<br/>The Bible causes men<br/>To be regenerated.			(1 Pet. 1:23)<br/>Our spiritual milk 			(1 Pet. 2:2)<br/>Our bread of life 			(Matt. 4:4)<br/>It makes us all complete.			(2 Timothy 3:17)<br/>',NULL,13926,13926);
INSERT INTO stanza VALUES('BF21','1','We have found the Christ Who''s all in all<br/>He is everything to us;<br/>O how blest upon His name to call,<br/>How divine, how glorious.<br/>',NULL,13927,13927);
INSERT INTO stanza VALUES('BF21','chorus','It is joy unspeakable and full of glory,<br/>Full of glory, full of glory;<br/>It is joy unspeakable and full of glory,<br/>And the half has never yet been told!<br/>',NULL,13928,13928);
INSERT INTO stanza VALUES('BF21','2','We have found that Christ the Spirit is<br/>Who within our spirit dwells;<br/>How available, how near He is,<br/>And His sweetness all excels.<br/>',NULL,13929,13929);
INSERT INTO stanza VALUES('BF21','3','We have found the way to live by Christ —<br/>Pray His Word and call His name,<br/>This — the eating, drinking — has sufficed<br/>And its worth we now proclaim.<br/>',NULL,13930,13930);
INSERT INTO stanza VALUES('BF21','4','We have found the local church our home;<br/>We are home and home indeed!<br/>Nevermore in Babylon we roam;<br/>In the church is all we need.<br/>',NULL,13931,13931);
INSERT INTO stanza VALUES('BF21','5','We have found that meeting with the saints<br/>Is the greatest joy on earth;<br/>''Tis by this our spirit never faints<br/>And our lives are filled with worth.<br/>',NULL,13932,13932);
INSERT INTO stanza VALUES('BF22','1','Lord take my heart it is for You<br/>To live and move as You would do.<br/>I cease to hide; no more to roam.<br/>Come claim my being for Your home.<br/>',NULL,13933,13933);
INSERT INTO stanza VALUES('BF22','2','So many things remain therein,<br/>Self blocks You out much more than sin<br/>Lord have Your way, Thy washing through<br/>That every part You would renew.<br/>',NULL,13934,13934);
INSERT INTO stanza VALUES('BF22','3','My need is for Your living word,<br/>Becoming real and not just heard<br/>Lord work Yourself into each part<br/>Mine will and feeling of my heart.<br/>',NULL,13935,13935);
INSERT INTO stanza VALUES('BF22','4','I want Your word to dwell in me<br/>In songs and hymns sweet melody.<br/>My spirit filled to overflow,<br/>Thy Word as Spirit I would know.<br/>',NULL,13936,13936);
INSERT INTO stanza VALUES('BF22','5','Thy flowing in my being Lord<br/>As Spirit and the living Word,<br/>All natural things You will replace,<br/>And old creation thus erase.<br/>',NULL,13937,13937);
INSERT INTO stanza VALUES('BF22','6','My heart is full of praise to You<br/>You''re sanctifying making new.<br/>Thy holy Word now makes me clean<br/>Your new creation will be seen.<br/>',NULL,13938,13938);
INSERT INTO stanza VALUES('BF23','1','Now is come salvation and strength<br/>And the kingdom of our God<br/>And the authority of His Christ:<br/>For the accuser of our brethren is cast down<br/>Which accused them before our God day and night.<br/>',NULL,13939,13939);
INSERT INTO stanza VALUES('BF23','2','And they overcame him by the blood of the Lamb,<br/>And by the word of their testimony<br/>And they loved not their soul lives unto death.<br/>Therefore rejoice, rejoice, rejoice!<br/>',NULL,13940,13940);
INSERT INTO stanza VALUES('BF24','1','What He is: He''s the Father.<br/>He''s the everlasting Father.<br/>He''s the firstborn of creation.<br/>He''s the One who lives inside of me.<br/>He''s the Father! Wonderful!<br/>',NULL,13941,13941);
INSERT INTO stanza VALUES('BF24','2','What He is: He''s the river.<br/>He''s the mighty flowing river.<br/>He waters me in a desert land.<br/>He''s my hiding place; He is our man.<br/>He''s the river! Wonderful!<br/>',NULL,13942,13942);
INSERT INTO stanza VALUES('BF24','3','What He is: He''s the vine tree.<br/>He''s the branch, the root of Jesse.<br/>He''s the tree of life: we have the right<br/>To eat of Him and have His life.<br/>He''s the vine tree! Wonderful!<br/>',NULL,13943,13943);
INSERT INTO stanza VALUES('BF24','4','What He is: He''s the Shepherd.<br/>He''s the lamb of God, the he-goat.<br/>We rest and feed in the pasture land.<br/>We strike the blood and eat the lamb.<br/>He''s the Shepherd! Wonderful!<br/>',NULL,13944,13944);
INSERT INTO stanza VALUES('BF24','5','What He is: He''s the Spirit.<br/>He''s the all-inclusive Spirit.<br/>He''s our everything; He''s our all in all.<br/>He gives life to us whene''er we call.<br/>He''s the Spirit! Wonderful!<br/>',NULL,13945,13945);
INSERT INTO stanza VALUES('BF24','6','What He is: He''s a Person.<br/>He''s a real and living Person.<br/>He is living now inside of us.<br/>This Person is so glorious.<br/>He''s a Person! Wonderful!<br/>',NULL,13946,13946);
INSERT INTO stanza VALUES('BF24','7','What He is: He''s the Body;<br/>He''s the fullness of the Godhead;<br/>He''s the center of the Father''s plan,<br/>Christ and the church, the one new man.<br/>He is wonderful, wonderful.<br/>',NULL,13947,13947);
INSERT INTO stanza VALUES('BF24','chorus','He is wonderful, wonderful,<br/>He is wonderful, wonderful.<br/>',NULL,13948,13948);
INSERT INTO stanza VALUES('BF25','1','The Lord shall get the glory<br/>If we will sing His praise,<br/>And angel hosts will listen<br/>When we our voices raise;<br/>The world around will hear us<br/>Give glory unto God,<br/>And Satan''s hosts will tremble<br/>And flee our conqu''ring rod.<br/>',NULL,13949,13949);
INSERT INTO stanza VALUES('BF25','2','Our mouth shut up defeats us<br/>And wins the Devil''s smile;<br/>So why not open battle<br/>And chase him all the while.<br/>By "sacrifice of praises"<br/>And shouts of victory—<br/>''Twill cost us but our faces<br/>God''s chosen fools to be!<br/>',NULL,13950,13950);
INSERT INTO stanza VALUES('BF25','3','The world has never helped us<br/>To shout our Savior''s praise,<br/>Nor given Him the glory<br/>Nor lent one thankful phrase;<br/>So need we ask permission<br/>To praise th'' ascended Lord?<br/>Cry out! Release your spirit!<br/>Much grace He does afford!<br/>',NULL,13951,13951);
INSERT INTO stanza VALUES('BF25','4','O brothers, be not silent!<br/>O sisters, cry aloud!<br/>The sound shall tell God''s triumph<br/>And blessings far abroad.<br/>Now is the time to praise Him,<br/>Yes now, at any cost!<br/>O joy in your salvation,<br/>And in His mercy boast.<br/>',NULL,13952,13952);
INSERT INTO stanza VALUES('BF26','1','Lord, Thou hast won, at length I yield;<br/>My heart by mighty grace compelled<br/>Surrenders all to Thee;<br/>Against Thy terrors long I strove,<br/>But who can stand against Thy love?<br/>Love conquers even me.<br/>',NULL,13953,13953);
INSERT INTO stanza VALUES('BF26','2','If Thou hadst bid Thy thunders roll,<br/>And light''nings flash, to blast my soul,<br/>I still had stubborn been;<br/>But mercy has my heart subdued,<br/>A bleeding Savior I have viewed,<br/>And now I hate my sin.<br/>',NULL,13954,13954);
INSERT INTO stanza VALUES('BF26','3','Now, Lord, I would be Thine alone,<br/>Come, take possession of Thine own,<br/>For Thou hast set me free;<br/>Released from Satan''s hard command,<br/>See all my powers waiting stand,<br/>To be employed by Thee.<br/>',NULL,13955,13955);
INSERT INTO stanza VALUES('BF27','1','From my spirit within flows a fountain of life —<br/>The Triune God flowing in me;<br/>God the Father''s the source, Christ the Son is the course,<br/>And the Spirit imparts life to me.<br/>',NULL,13956,13956);
INSERT INTO stanza VALUES('BF27','chorus','Lord, I treasure the sweet flow of life,<br/>And my soul-life at last I lay down;<br/>O Lord, deepen the pure flow of life;<br/>At Your coming may life be my crown.<br/>',NULL,13957,13957);
INSERT INTO stanza VALUES('BF27','2','In the fresh, tender grass Jesus makes me lie down;<br/>He leads me by waters of rest;<br/>No more struggle and strain; all self-effort is vain;<br/>In the flow I am perfectly blessed.<br/>',NULL,13958,13958);
INSERT INTO stanza VALUES('BF27','3','Jesus called me one day to the Holiest Place,<br/>To live in His presence divine;<br/>Hallelujah, I''ve heard an encouraging word:<br/>"Abide — you''re a branch in the vine."<br/>',NULL,13959,13959);
INSERT INTO stanza VALUES('BF28','1','Oh! the joy of having nothing,<br/>Being nothing, seeing nothing<br/>But a living Christ in glory<br/>And being careful for nothing.<br/>Oh! the joy of having nothing,<br/>Being nothing, seeing nothing<br/>But a living Christ in glory<br/>And His interest here on earth!<br/>',NULL,13960,13960);
INSERT INTO stanza VALUES('BF29','1','Known of my Father before time began,<br/>Washed in the sprinkling blood of the Lamb,<br/>Now in the spirit I am a God-man,<br/>Hallelujah, Hallelujah!<br/>',NULL,13961,13961);
INSERT INTO stanza VALUES('BF29','chorus','Hallelujah, Hallelujah, Hallelujah,<br/>Hallelujah, Hallelujah, Hallelujah.<br/>',NULL,13962,13962);
INSERT INTO stanza VALUES('BF29','2','Father, You knew me a long time ago.<br/>In Your foreknowledge, Your mercy to show,<br/>You foreordained me Your glory to know,<br/>Hallelujah, Hallelujah!<br/>',NULL,13963,13963);
INSERT INTO stanza VALUES('BF29','3','Son, in Your blood, the most precious of all,<br/>I have been purchased and saved from the fall.<br/>Your resurrection''s my reason to call,<br/>Hallelujah, Hallelujah!<br/>',NULL,13964,13964);
INSERT INTO stanza VALUES('BF29','4','Spirit, You came and You sanctified me.<br/>You gave me faith when my eyes couldn''t see.<br/>Now You''re the Spirit of life within me,<br/>Hallelujah, Hallelujah!<br/>',NULL,13965,13965);
INSERT INTO stanza VALUES('BF29','5','You are my Father and I have Your seed!<br/>I have been purchased and I am redeemed!<br/>I have the Spirit within me indeed!<br/>Hallelujah, Hallelujah!<br/>',NULL,13966,13966);
INSERT INTO stanza VALUES('BF30','1','O Lord, I love You,<br/>I really love You,<br/>Without You life''s really nothing.<br/>You are so attracting,<br/>And You are so charming;<br/>Your riches are unsearchable.<br/>Your name''s so dear and sweet,<br/>Calling makes one satisfied,<br/>Now You are mine and I am Thine, Lord;<br/>Joined and mingled with You,<br/>God-man incorporation,<br/>Foretaste of the New Jerusalem.<br/>',NULL,13967,13967);
INSERT INTO stanza VALUES('BF31','1','Never did I dream before,<br/>Such a place could e''er be found,<br/>Where the tears of sorrow cease,<br/>Songs of endless joy abound.<br/>One who seldom ever sang,<br/>Now delights his voice to raise;<br/>Singing hymns with all the saints,<br/>Echoing the ceaseless praise.<br/>',NULL,13968,13968);
INSERT INTO stanza VALUES('BF31','2','Day by day the world goes on,<br/>Just as it has gone before.<br/>Millions grasp and clutch at life,<br/>Wond''ring if there could be more;<br/>Such was I and would be, yet<br/>Mercy found me out somehow;<br/>With what gratefulness I say,<br/>"I''m in God''s own family now."<br/>',NULL,13969,13969);
INSERT INTO stanza VALUES('BF31','3','How delightful ''tis to know;<br/>How subjective, real, and sweet<br/>Is this inward joy of grace<br/>We experience when we meet;<br/>Life abundant Jesus gives<br/>As my full reality;<br/>Praise You, Lord, it''s really true,<br/>I''m in Your own family.<br/>',NULL,13970,13970);
INSERT INTO stanza VALUES('BF31','4','At the closing of this age,<br/>Just before Your kingdom''s dawn,<br/>May You gain a people, Lord,<br/>For Your dwelling place, Your home<br/>Since for me You gave Your all,<br/>Everything I lay aside;<br/>For your church my all I''d give,<br/>That You would be satisfied.<br/>',NULL,13971,13971);
INSERT INTO stanza VALUES('BF32','1','I know not what awaits me,<br/>God kindly veils my eyes,<br/>And o''er each step of my onward way<br/>He makes new scenes to rise;<br/>And every joy He sends me comes<br/>A sweet and glad surprise.<br/>',NULL,13972,13972);
INSERT INTO stanza VALUES('BF32','chorus','Where He may lead me I''ll follow,<br/>My trust in Him repose;<br/>And every hour in perfect peace,<br/>I''ll sing, "He knows, He knows";<br/>I''ll sing, "He knows, He knows."<br/>',NULL,13973,13973);
INSERT INTO stanza VALUES('BF32','2','One step I see before me,<br/>''Tis all I need to see,<br/>The light of heaven more brightly shines<br/>When earth''s illusions flee;<br/>And sweetly through the silence comes,<br/>His loving, "Trust in Me!"<br/>',NULL,13974,13974);
INSERT INTO stanza VALUES('BF32','3','Oh blissful lack of wisdom,<br/>''Tis blessed not to know;<br/>He holds me with His own right hand,<br/>And will not let me go,<br/>And lulls my troubled soul to rest<br/>In Him who loves me so.<br/>',NULL,13975,13975);
INSERT INTO stanza VALUES('BF32','4','So on I go not knowing;<br/>I would not if I might;<br/>I''d rather walk in the dark with God<br/>Than go alone in the light;<br/>I''d rather walk by faith with Him<br/>Than go alone by sight.<br/>',NULL,13976,13976);
INSERT INTO stanza VALUES('BF33','1','Lord, You are my only goal!<br/>You''re my only hope!<br/>I only care for You!<br/>I never could replace You,<br/>And I would never want to.<br/>I have everything, Lord — I have You!<br/>',NULL,13977,13977);
INSERT INTO stanza VALUES('BF33','2','Lord, I only live for You —<br/>Not anything else!<br/>In everything You''re my source;<br/>No more good intentions,<br/>No more right or wrong!<br/>I don''t want a "good" life — I want You.<br/>',NULL,13978,13978);
INSERT INTO stanza VALUES('BF34','1','Take time to behold Him,<br/>Speak oft with Thy Lord,<br/>Abide in Him always,<br/>And feed on His Word.<br/>Wait thou in His presence,<br/>Submissive and meek,<br/>Forgetting in nothing<br/>His blessing to seek.<br/>',NULL,13979,13979);
INSERT INTO stanza VALUES('BF34','2','Take time to behold Him,<br/>The world rushes on;<br/>Spend much time in secret<br/>With Jesus alone.<br/>By looking to Jesus<br/>Like Him thou shalt be;<br/>Thy friends, in thy conduct,<br/>His likeness shall see.<br/>',NULL,13980,13980);
INSERT INTO stanza VALUES('BF34','3','Take time to behold Him,<br/>Let Him be thy guide;<br/>And run not before Him<br/>Whatever betide;<br/>In joy or in sorrow<br/>Still follow thy Lord,<br/>And, looking to Jesus,<br/>Still trust in His Word.<br/>',NULL,13981,13981);
INSERT INTO stanza VALUES('BF34','4','Take time to behold Him,<br/>Be calm in thy soul,<br/>Each thought and each temper<br/>Beneath His control.<br/>Thus led by His Spirit<br/>To fountains of love,<br/>Thou then shalt be fitted<br/>His mercy to prove.<br/>',NULL,13982,13982);
INSERT INTO stanza VALUES('BF35','1','Unto him that hath Thou givest<br/>Ever more abundantly<br/>Lord, I live because Thou livest,<br/>Therefore give more life to me,<br/>Therefore speed me in the race,<br/>Therefore let me grow in grace.<br/>(repeat last two lines of each stanza)<br/>',NULL,13983,13983);
INSERT INTO stanza VALUES('BF35','2','Deepen all Thy work, O Master,<br/>Strengthen every downward root;<br/>Only do Thou ripen faster,<br/>More and more Thy pleasant fruit;<br/>Purge me, prune me, self abase;<br/>Only let me grow in grace.<br/>',NULL,13984,13984);
INSERT INTO stanza VALUES('BF35','3','Let me grow by sun and shower,<br/>Every moment water me;<br/>Make me really, hour by hour,<br/>More and more conformed to Thee,<br/>That Thy loving eye may trace<br/>Day by day my growth in grace.<br/>',NULL,13985,13985);
INSERT INTO stanza VALUES('BF35','4','From Thy fullness grace outpouring,<br/>Show me ever greater things;<br/>Raise me higher, sunward soaring,<br/>Mounting as on eagle-wings.<br/>By the brightness of Thy face,<br/>Ever let me grow in grace.<br/>',NULL,13986,13986);
INSERT INTO stanza VALUES('BF35','5','Let me, then, be always growing,<br/>Never, never standing still,<br/>Listening, learning, better knowing<br/>Thee and Thy most blessed will.<br/>Till I win the glorious race,<br/>Daily let me grow in grace.<br/>',NULL,13987,13987);
INSERT INTO stanza VALUES('BF36','1','I thank Thee, Lord, that Thou hast shown,<br/>And I begin to see,<br/>What Thou canst be to all Thine own,<br/>What they may be to Thee;<br/>If only they will yield Thee all,<br/>And trustingly obey Thy call.<br/>',NULL,13988,13988);
INSERT INTO stanza VALUES('BF36','2','How wonderful! I never knew<br/>That I might trust Thee so;<br/>That Thou wouldst be so much to me.<br/>In all the way I go,<br/>That every need Thou wouldst supply.<br/>And all my longings satisfy.<br/>',NULL,13989,13989);
INSERT INTO stanza VALUES('BF36','3','I take Thee as my keeper now<br/>And I commit to Thee<br/>My soul, my way, my works, my cause.<br/>In Thy sole charge to be;<br/>And my deposit, Thou, I know<br/>Wilt guard secure from every foe.<br/>',NULL,13990,13990);
INSERT INTO stanza VALUES('BF36','4','I take Thee for my peace, O Lord.<br/>My heart to keep and fill<br/>Thine own great calm, amid earth''s storms<br/>Shall keep me always still;<br/>And as Thy kingdom doth increase,<br/>So shall Thine ever-deep''ning peace<br/>',NULL,13991,13991);
INSERT INTO stanza VALUES('BF36','5','I take Thee, Lord, to be my all.<br/>Since all Thou art is mine;<br/>I nothing have, and nothing am;<br/>That nothing, Lord, is Thine.<br/>Thou shalt be everything to me<br/>In all things my sufficiency.<br/>',NULL,13992,13992);
INSERT INTO stanza VALUES('BF37','1','Loved with everlasting love,<br/>Led by grace that love to know;<br/>Spirit, breathing from above,<br/>Thou hast taught me it is so.<br/>Oh, this full and perfect peace!<br/>Oh, this transport all divine!<br/>In a love which cannot cease,<br/>I am His, and He is mine.<br/>',NULL,13993,13993);
INSERT INTO stanza VALUES('BF37','2','Heaven above is softer blue,<br/>Earth around is sweeter green;<br/>Something lives in every hue<br/>Christless eyes have never seen:<br/>Birds with gladder songs o''erflow,<br/>Flow''rs with deeper beauties shine,<br/>Since I know, as now I know,<br/>I am His, and He is mine.<br/>',NULL,13994,13994);
INSERT INTO stanza VALUES('BF37','3','Things that once were wild alarms<br/>Cannot now disturb my rest;<br/>Closed in everlasting arms,<br/>Pillowed on the loving breast.<br/>Oh, to lie forever here,<br/>Doubt and care and self resign,<br/>While He whispers in my ear,<br/>I am His, and He is mine.<br/>',NULL,13995,13995);
INSERT INTO stanza VALUES('BF37','4','His forever, only His:<br/>Who the Lord and me shall part?<br/>Ah, with what a rest of bliss<br/>Christ can fill the loving heart.<br/>Heaven and earth may fade and flee,<br/>Firstborn light in gloom decline;<br/>But, while God and I shall be,<br/>I am His, and He is mine.<br/>',NULL,13996,13996);
INSERT INTO stanza VALUES('BF38','1','I''ve given up the world because<br/>I''ve found something more.<br/>He''s better than anything<br/>I''ve ever found before.<br/>Yes, I have found the Living One —<br/>Oh, how my spirit soars!<br/>I called His name, I''m not the same,<br/>I am for the Lord!<br/>',NULL,13997,13997);
INSERT INTO stanza VALUES('BF38','chorus','I''m for the Lord,<br/>I''m loving Jesus.<br/>I''m for the Lord,<br/>I''m calling, O Lord Jesus!<br/>',NULL,13998,13998);
INSERT INTO stanza VALUES('BF38','2','I''ve given up the world because<br/>I''ve found something better.<br/>I have found the Living One<br/>And He breaks ev''ry fetter.<br/>Yes, He''s the One who set me free —<br/>Oh, how my spirit soars!<br/>I called His name, I''m not the same,<br/>I am for the Lord!<br/>',NULL,13999,13999);
INSERT INTO stanza VALUES('BF38','3','And now I''m really happy —<br/>Yes, I''m fully satisfied.<br/>I have found the Living One<br/>And He lives right inside<br/>Of you and me. So come and see<br/>Now our spirit soar.<br/>We called His name, we''re not the same,<br/>We are for the Lord!<br/>',NULL,14000,14000);
INSERT INTO stanza VALUES('BF38','chorus','We''re for the Lord.<br/>We''re loving Jesus!<br/>We''re for the Lord.<br/>We''re calling, O Lord Jesus!<br/>',NULL,14001,14001);
INSERT INTO stanza VALUES('BF39','1','God has called us for His purpose,<br/>His economy so glorious,<br/>For which He was fully processed;<br/>Consummated now is He.<br/>As the Spirit, He indwells us<br/>As our God-allotted portion,<br/>Working out His full salvation<br/>Making us the same as He is.<br/>',NULL,14002,14002);
INSERT INTO stanza VALUES('BF39','chorus','Oh, may a clear, controlling vision of<br/>The Lord''s economy direct my heart,<br/>And burn in me until my spirit''s wholly set afire!<br/>With spirit strong and active we''ll press on<br/>To consummate God''s goal —<br/>New Jerusalem, Hallelujah!<br/>',NULL,14003,14003);
INSERT INTO stanza VALUES('BF39','2','Jesus lived the God-man pattern<br/>Set the way for us to follow,<br/>He denied the natural man and<br/>Was obedient unto death.<br/>Once He was the only God-man;<br/>Now we are His duplication.<br/>As the many grains we''re blended<br/>As His corporate reproduction.<br/>',NULL,14004,14004);
INSERT INTO stanza VALUES('BF39','3','Living out His resurrection,<br/>Dying to the flesh and soul-life.<br/>Living by the mingled spirit,<br/>Natural man we will deny.<br/>Now we''re living in the Body,<br/>Every day we''re overcoming,<br/>Striving for the peak of Zion,<br/>Watching for our Lord''s appearing.<br/>',NULL,14005,14005);
INSERT INTO stanza VALUES('BF39','4','God and man will have one living,<br/>Always in the mingled spirit;<br/>We two are incorporated —<br/>One organic entity!<br/>This the vision of the ages<br/>Will control our daily living<br/>That the Lord may have His Body,<br/>Shining as the holy city.<br/>',NULL,14006,14006);
INSERT INTO stanza VALUES('BF40','1','My Beloved says to me rise up<br/>My love, my beauty,<br/>And come away for now the winter''s past<br/>Rain is over and gone<br/>Flowers appear on the earth<br/>The time is of singing<br/>And the voice of the turtledove is heard in our land<br/>The fig tree has ripened its figs<br/>And the vines are in blossom<br/>They give forth their fragrance<br/>Rise up, my love, my beauty<br/>And come away.<br/>',NULL,14007,14007);
INSERT INTO stanza VALUES('BF41','1','I am the Lord''s! O joy beyond expression,<br/>O sweet response to voice of love Divine;<br/>Faith''s joyous "Yes" to the assuring whisper,<br/>"Fear not! I have redeemed thee; thou art Mine."<br/>',NULL,14008,14008);
INSERT INTO stanza VALUES('BF41','2','I am the Lord''s! It is the glad confession<br/>Wherewith the Bride recalls the happy day,<br/>When love''s "I will" accepted Him forever,<br/>"The Lord''s," to love, to honor and obey.<br/>',NULL,14009,14009);
INSERT INTO stanza VALUES('BF41','3','I am the Lord''s! Yet teach me all it meaneth,<br/>All it involves of love and loyalty,<br/>Of holy service, absolute surrender,<br/>And unreserved obedience unto Thee.<br/>',NULL,14010,14010);
INSERT INTO stanza VALUES('BF41','4','I am the Lord''s! Yes; body, soul, and spirit,<br/>O seal them irrecoverably Thine;<br/>As Thou, Beloved, in Thy grace and fullness<br/>Forever and forevermore art mine.<br/>',NULL,14011,14011);
INSERT INTO stanza VALUES('BF42','1','It is Jehovah''s loving kindness<br/>That we are not consumed,<br/>For His compassions do not fail;<br/>They are new every morning;<br/>Jehovah is my portion;<br/>Therefore I hope in Him.<br/>He is good to those who wait on Him,<br/>Who wait on Him.<br/>',NULL,14012,14012);
INSERT INTO stanza VALUES('BF43','1','What a victory! What a triumph!<br/>God Himself became a man,<br/>Clothed Himself in human nature<br/>To fulfill His mighty plan.<br/>He through death destroyed the devil;<br/>Risen now, the Son of Man!<br/>(Repeat the last two lines of each stanza)<br/>',NULL,14013,14013);
INSERT INTO stanza VALUES('BF43','2','Jesus by His human virtues<br/>Did the subtle one arrest;<br/>He as man withstood the tempter,<br/>Fully passed through every test.<br/>Now in spirit I can take Him,<br/>All His virtues to possess.<br/>',NULL,14014,14014);
INSERT INTO stanza VALUES('BF43','3','In the Spirit of this Jesus<br/>Is His human life so fine.<br/>Human virtues have been added<br/>To the Spirit all divine.<br/>What abundance in this Spirit,<br/>Rich supply for all mankind!<br/>',NULL,14015,14015);
INSERT INTO stanza VALUES('BF43','4','How mysterious! Yet how real!<br/>Such a man now lives in me.<br/>Into all my heart He''s spreading —<br/>He, my human life, to be.<br/>Hallelujah! Hallelujah!<br/>I will praise unceasingly.<br/>',NULL,14016,14016);
INSERT INTO stanza VALUES('BF44','1','Lord Jesus, draw me one step further;<br/>Draw me, Lord from where I am.<br/>I''ve been here too long already<br/>Move me, Lord, I know You can.<br/>',NULL,14017,14017);
INSERT INTO stanza VALUES('BF44','2','Your whisper, Lord, so softly sounding,<br/>Deep within my heart does burn.<br/>Let Your stillness now subdue me<br/>That Your feeling I discern<br/>',NULL,14018,14018);
INSERT INTO stanza VALUES('BF44','3','All idle thoughts and impure feelings,<br/>Lord, remove from my dead heart.<br/>Wash me in the crystal water<br/>And more life to me impart<br/>',NULL,14019,14019);
INSERT INTO stanza VALUES('BF44','4','All hidden things that block my vision,<br/>Rocks of self-ambition, pride;<br/>Now expose and burn away, Lord<br/>By Your look intensified.<br/>',NULL,14020,14020);
INSERT INTO stanza VALUES('BF44','5','Increase the weight of glory in me,<br/>Let Your Spirit now transform,<br/>That all things would not be wasted<br/>But would work to save me more.<br/>',NULL,14021,14021);
INSERT INTO stanza VALUES('BF44','6','Lord Jesus, oh how much I need You!<br/>Thank You, Lord, that You are here,<br/>Ever present as the Body.<br/>I would always seek You there.<br/>',NULL,14022,14022);
INSERT INTO stanza VALUES('BF45','1','Let the Glory of the Lord endure forever<br/>Let the Lord be glad in His works<br/>I will sing unto the Lord as long as I live<br/>I will sing praise to my God while I have my being.<br/>',NULL,14023,14023);
INSERT INTO stanza VALUES('BF46','1','My song shall be of Jesus;<br/>His mercy crowns my days,<br/>He fills my cup with blessings;<br/>And tunes my heart to praise.<br/>My song shall be of Jesus,<br/>The precious Lamb of God,<br/>Who gave Himself my ransom,<br/>And bought me with His blood.<br/>',NULL,14024,14024);
INSERT INTO stanza VALUES('BF46','chorus','My song shall be of Jesus<br/>When, sitting at His feet,<br/>I call to mind His goodness<br/>In meditation sweet:<br/>My song shall be of Jesus,<br/>Whatever ill betide;<br/>I''ll sing the grace that saves me,<br/>And keeps me at His side.<br/>I''ll sing the grace that saves me,<br/>And keeps me at His side.<br/>',NULL,14025,14025);
INSERT INTO stanza VALUES('BF46','2','My song shall be of Jesus<br/>While pressing on my way<br/>To reach the blissful kingdom<br/>Of pure and perfect day:<br/>And when my soul shall enter<br/>That realm of splendor fair,<br/>A song of praise to Jesus<br/>I''ll sing forever there.<br/>',NULL,14026,14026);
INSERT INTO stanza VALUES('BF47','chorus','Lord, grant me today''s supply of grace;<br/>May Your divine life grow apace;<br/>Little by little, day by day, to grow<br/>More and more, into You.<br/>',NULL,14027,14027);
INSERT INTO stanza VALUES('BF47','1','Day by day, bit by bit, life will grow as is fit,<br/>Increasing gradually until,<br/>However imperceptibly,<br/>Your life matures within me.<br/>',NULL,14028,14028);
INSERT INTO stanza VALUES('BF47','2','I would be desperately, constantly, patiently,<br/>Drawing each breath of life from You, Lord;<br/>Knowing that every day while I breathe,<br/>Your life will permeate me.<br/>',NULL,14029,14029);
INSERT INTO stanza VALUES('BF47','3','Every day, may I rest, knowing that each bequest,<br/>Matches my daily need exactly;<br/>Jesus Christ intercedes for me, a member of His body.<br/>',NULL,14030,14030);
INSERT INTO stanza VALUES('BF47','chorus','Lord, grant me a heavenly, corporate view;<br/>That all of my growth and prayers to You,<br/>Little by little, day by day, would cause<br/>Building up into You.<br/>',NULL,14031,14031);
INSERT INTO stanza VALUES('BF47','4','I would be corporately, growing up steadily<br/>Till we reach the stature of Your fullness;<br/>Transforming and conforming us,<br/>Your manifested people.<br/>',NULL,14032,14032);
INSERT INTO stanza VALUES('BF47','chorus','Lord, grant me a heavenly, corporate view;<br/>That all of my growth and prayers to You,<br/>Little by little, day by day, would cause<br/>Building up into the New Jerusalem.<br/>',NULL,14033,14033);
INSERT INTO stanza VALUES('BF48','1','Your sweetness is just a taste of enjoyment.<br/>Your beauty is simply my heart''s attraction.<br/>Your radiance has captured me.<br/>Your eyes draw things out of me.<br/>I want to daily kiss You<br/>And hold on to You.<br/>',NULL,14034,14034);
INSERT INTO stanza VALUES('BF48','chorus','O Jesus, I''m crazy loving You,<br/>O Jesus, I''m crazy loving You<br/>O Jesus, I''m crazy loving You<br/>Until myself is no more.<br/>O Jesus, I''m crazy loving You.<br/>O Jesus, I''m crazy loving You<br/>O Jesus, I''m crazy loving You<br/>''Till I''m lost in You.<br/>',NULL,14035,14035);
INSERT INTO stanza VALUES('BF48','2','Forgetting all that I''m outwardly doing.<br/>Forgetting all of my thoughts of improving.<br/>You only want to be loved,<br/>I give my love unto You;<br/>A crazy lover of Christ, I''m jumping for joy.<br/>',NULL,14036,14036);
INSERT INTO stanza VALUES('BF48','3','Yes, my life''s just to love You with my whole being.<br/>Yes, my work''s just to love You with my whole being.<br/>Loving You is my pleasure,<br/>Loving You is my service,<br/>Loving You is my motive and also my will.<br/>',NULL,14037,14037);
INSERT INTO stanza VALUES('BF48','4','O my Love, You''ve blinded me towards all things.<br/>O my Love, You make the world simply nothing.<br/>Just let me see You alone,<br/>Just make me need You alone;<br/>None other is there for me, it''s Jesus alone!<br/>',NULL,14038,14038);
INSERT INTO stanza VALUES('BF49','1','God wants someone to love Him,<br/>Not just someone to serve Him;<br/>He wants someone to love Him<br/>As His bride.<br/>God wants someone to match Him,<br/>Not just to imitate Him;<br/>He wants a counterpart,<br/>One from His side.<br/>',NULL,14039,14039);
INSERT INTO stanza VALUES('BF49','chorus','For this He came down to us;<br/>He came to court, to woo us,<br/>Away from everything, and unto Him.<br/>Now we''re espoused unto Him,<br/>Pledged and betrothed unto Him;<br/>Yes, we are bound unto Him<br/>By His love.<br/>',NULL,14040,14040);
INSERT INTO stanza VALUES('BF49','2','God wants someone to love Him,<br/>Not just someone to fear Him;<br/>He wants a sweetheart who will<br/>Be His bride.<br/>God wants someone to know Him,<br/>Not just to know about Him;<br/>He wants someone who''ll look Him<br/>In the eye.<br/>',NULL,14041,14041);
INSERT INTO stanza VALUES('BF50','1','Love covers all things and believes all things,<br/>Love hopes in all things and endures all things.<br/>Love never falls away and won''t be rendered useless.<br/>But other things will pass away.<br/>',NULL,14042,14042);
INSERT INTO stanza VALUES('BF50','2','Life is the element of God, who''s love;<br/>Hence God as life is shown by love, through you.<br/>Don''t neglect love, but pursue it first;<br/>Love makes a person spiritual.<br/>',NULL,14043,14043);
INSERT INTO stanza VALUES('BF50','3','Love suffers long and love is kind, so kind,<br/>Love does not brag, is not puffed up,<br/>Love rejoices when God''s truth is manifest,<br/>Love is the element of God.<br/>',NULL,14044,14044);
INSERT INTO stanza VALUES('BF50','4','If I speak in tongues, but do not love, I am<br/>Like sounding brass giving lifeless sounds, not life.<br/>If I know all mysteries but do not love my brother,<br/>I have no love and am nothing.<br/>',NULL,14045,14045);
INSERT INTO stanza VALUES('BF51','1','I love God with all my heart<br/>And with all my soul;<br/>He is the One I love so much.<br/>I love the Lord with all my heart<br/>And every part of my soul.<br/>',NULL,14046,14046);
INSERT INTO stanza VALUES('BF51','2','I love You, Lord Jesus,<br/>With all my heart and with all my soul;<br/>You are the only One in the universe<br/>For me, dear Lord.<br/>',NULL,14047,14047);
INSERT INTO stanza VALUES('BF51','3','I love the Lord and He loves me this I know.<br/>I love the Bible oh how it makes me grow.<br/>I love the church life with all the saints I go<br/>Singing, praising, calling on the Lord.<br/>I love God.<br/>',NULL,14048,14048);
INSERT INTO stanza VALUES('BF52','1','The law of the Lord is perfect, converting the soul;<br/>The testimony of the Lord is sure, making wise the simple.<br/>',NULL,14049,14049);
INSERT INTO stanza VALUES('BF52','chorus','More to be desired are they than gold,<br/>Yea, than much fine gold,<br/>Sweeter also than honey, and the honeycomb.<br/>',NULL,14050,14050);
INSERT INTO stanza VALUES('BF52','2','The statutes of the Lord are right, rejoicing the heart;<br/>The commandment of the Lord is pure, enlightening the eyes.<br/>',NULL,14051,14051);
INSERT INTO stanza VALUES('BF52','3','The fear of the Lord is clean, enduring forever;<br/>The judgment of the Lord are true, and righteous altogether.<br/>',NULL,14052,14052);
INSERT INTO stanza VALUES('BF52','4','Let the words of my mouth, and the meditation of my heart;<br/>Be acceptable in Thy sight, O Lord, my strength and my redeemer.<br/>',NULL,14053,14053);
INSERT INTO stanza VALUES('BF52','chorus','Moreover by them is Thy servant warned,<br/>Is Thy servant warned,<br/>And in keeping of them there is great reward.<br/>',NULL,14054,14054);
INSERT INTO stanza VALUES('BF53','1','My goal is God Himself, not joy, nor peace,<br/>Nor even blessing, but Himself, my God;<br/>''Tis His to lead me there — not mine, but His—<br/>At any cost, dear Lord, by any road.<br/>',NULL,14055,14055);
INSERT INTO stanza VALUES('BF53','2','So faith bounds forward to its goal in God,<br/>And love can trust her Lord to lead her there;<br/>Upheld by Him, my soul is following hard<br/>Till God hath full fulfilled my deepest prayer.<br/>',NULL,14056,14056);
INSERT INTO stanza VALUES('BF53','3','No matter if the way be sometimes dark,<br/>No matter though the cost be oft-times great,<br/>He knoweth how I best shall reach the mark,<br/>The way that leads to Him must needs be strait.<br/>',NULL,14057,14057);
INSERT INTO stanza VALUES('BF53','4','One thing I know, I cannot say Him nay;<br/>One thing I do, I press towards my Lord;<br/>My God my glory here, from day to day,<br/>And in the glory there my great Reward.<br/>',NULL,14058,14058);
INSERT INTO stanza VALUES('BF54','1','Search me, O God, and know my heart;<br/>Try me and know my thoughts;<br/>And see if there be any wicked way in me;<br/>And lead me in the way, lead me in the way,<br/>Lead me in the way everlasting.<br/>',NULL,14059,14059);
INSERT INTO stanza VALUES('BF54','2','You have searched me;<br/>You have known me;<br/>My downsitting, my uprising;<br/>You understand my thoughts from afar;<br/>You know all my ways,<br/>You know all my ways.<br/>',NULL,14060,14060);
INSERT INTO stanza VALUES('BF55','1','Lord, I love You.<br/>Lord, I need You.<br/>Lord, without You<br/>Nothing would be the same.<br/>Without You knowing,<br/>Without You flowing,<br/>Without You growing,<br/>In me my life is vain.<br/>Lord, I love You more and more;<br/>I just want You.<br/>Fill me with Your life and virtues.<br/>Fill me ''til I''m only living You.<br/>Fill me every minute, every hour, every day<br/>Until I am expressing You always.<br/>Fill this earthen vessel, Lord, I pray.<br/>',NULL,14061,14061);
INSERT INTO stanza VALUES('BF55','2','Lord, You''re moving,<br/>Operating.<br/>In my being<br/>Saturate every part.<br/>You''re infusing,<br/>Permeating.<br/>You''re indwelling,<br/>Making home in my heart.<br/>Lord, I love You more and more;<br/>I just want You.<br/>Fill me with Your life and virtues.<br/>Fill me ''til I''m only living You.<br/>Fill me every minute, every hour, every day<br/>Until I am expressing You always.<br/>Fill this earthen vessel, Lord, I pray.<br/>',NULL,14062,14062);
INSERT INTO stanza VALUES('BF55','3','Lord, You''re building<br/>Your expression;<br/>Lord, by mingling<br/>All that You are in me.<br/>I''m responding,<br/>Cooperating,<br/>Consecrating<br/>Myself to You totally.<br/>Lord, for Your expression<br/>I would now outpour,<br/>Partaking of Your Person more and more,<br/>Partaking of Your Person more and more.<br/>Lord, for Your expression<br/>I would now outpour,<br/>This is what I was created for,<br/>This is what I was created for.<br/>',NULL,14063,14063);
INSERT INTO stanza VALUES('BF56','1','Though I love You, Lord,<br/>My life seems all deformed.<br/>I give my life to You —<br/>Then drift away.<br/>Lord, may I ask You that You''d draw me Yet again,<br/>And keep me running after You.<br/>',NULL,14064,14064);
INSERT INTO stanza VALUES('BF56','chorus','Lord, I''ve seen Your purpose.<br/>Your heart''s unveiled to me.<br/>Now I''d just like to see You gain me fully.<br/>Though You I often limit<br/>And fail by compromise,<br/>Keep me in the index of Your eyes.<br/>',NULL,14065,14065);
INSERT INTO stanza VALUES('BF56','2','Lord, I want Your best.<br/>I want Your full blessing.<br/>I don''t want any less,<br/>Though good it be.<br/>Have mercy, Lord, to push, to pull, lay hold of me.<br/>Keep me still running toward the prize.<br/>',NULL,14066,14066);
INSERT INTO stanza VALUES('BF56','3','Mold me, shape me, Lord.<br/>Be my reality.<br/>Even break my heart,<br/>If it has to be.<br/>I''m desperate, Lord, that You would have Your<br/>way with me.<br/>Others could touch You then through me.<br/>',NULL,14067,14067);
INSERT INTO stanza VALUES('BF56','4','Set my heart aflame.<br/>Don''t let me stay the same.<br/>Don''t let things remain<br/>Which now grieve You.<br/>My life I give to You and all I''ve claimed as mine.<br/>May I just hold, Lord, unto You.<br/>',NULL,14068,14068);
INSERT INTO stanza VALUES('BF57','1','When all around my sky is falling<br/>And fear and doubt run deep in my heart,<br/>It''s in these times I''m on You calling,<br/>Op''ning to You, Lord, my deepest part.<br/>',NULL,14069,14069);
INSERT INTO stanza VALUES('BF57','chorus','Oh, Lord Jesus!<br/>How I love You!<br/>And I need You<br/>All the time.<br/>Ahh, to touch You<br/>In my weakness,<br/>And to hold You,<br/>Savior mine.<br/>',NULL,14070,14070);
INSERT INTO stanza VALUES('BF57','2','Lord, by Your mercy You consume me.<br/>It''s all according to God''s plan.<br/>By resurrection life renew me,<br/>Day by day, my inner man.<br/>',NULL,14071,14071);
INSERT INTO stanza VALUES('BF58','1','With the kisses of Your mouth,<br/>Have You kissed me Lord<br/>From your kisses flows a fountain,<br/>From a depth unknown.<br/>Gently tempered by Your touching<br/>Of my deepest chords,<br/>My heart''s renewed with gladness,<br/>And my love o''erflows.<br/>',NULL,14072,14072);
INSERT INTO stanza VALUES('BF58','2','Let me kiss You, drink You deeper,<br/>Fully satisfy.<br/>All the longings deep within me,<br/>For Your presence nigh,<br/>And a deeper, sweeter union,<br/>Of Your life with mine<br/>That our natures fully mingled,<br/>Would our hearts entwine.<br/>',NULL,14073,14073);
INSERT INTO stanza VALUES('BF58','3','Ever increase, Lord within me,<br/>My desire for You.<br/>Let Your kisses ever kiss me,<br/>And that I''d kiss You.<br/>Dear Lord Jesus, may I ever be,<br/>So betrothed to You.<br/>May I love You always love You,<br/>And respond to You.<br/>',NULL,14074,14074);
INSERT INTO stanza VALUES('BF59','1','I heard the voice of Jesus say,<br/>"Come unto Me, and rest;<br/>Lay down thou weary one, lay down<br/>Thy head upon My breast."<br/>I came to Jesus as I was,<br/>Weary, and worn, and sad;<br/>I found in Him a resting-place,<br/>And He has made me glad.<br/>',NULL,14075,14075);
INSERT INTO stanza VALUES('BF59','2','I heard the voice of Jesus say,<br/>"Behold, I freely give<br/>The living water: thirsty one,<br/>Stoop down, and drink, and live."<br/>I came to Jesus, and I drank<br/>Of that life-giving stream;<br/>My thirst was quenched, my soul revived,<br/>And now I live in Him.<br/>',NULL,14076,14076);
INSERT INTO stanza VALUES('BF59','3','I heard the voice of Jesus say,<br/>"I am this dark world''s Light;<br/>Look unto Me, thy morn shall rise,<br/>And all thy day be bright."<br/>I looked to Jesus, and I found<br/>In Him my Star, my Sun;<br/>And in that Light of life I''ll walk<br/>Till trav''lling days are done.<br/>',NULL,14077,14077);
INSERT INTO stanza VALUES('BF60','1','Christ has come to be life — the processed Divine Trinity.<br/>God the Father''s the source — a fountain emerging to be.<br/>God the Son as a gushing-up spring<br/>In the Spirit, a river, for life-imparting.<br/>Oh! How can this miracle be?<br/>The Triune God flowing in me!<br/>Oh, I''ve got rivers of life flowing out of my innermost being!<br/>I''ve got rivers of life flowing out of my innermost being!<br/>',NULL,14078,14078);
INSERT INTO stanza VALUES('BF60','chorus','As this life flows through me,<br/>I''m supplied abundantly.<br/>His life nullifies sin,<br/>Pow''r springs now from within<br/>To be free — overcoming spontaneously!<br/>',NULL,14079,14079);
INSERT INTO stanza VALUES('BF60','2','Yet this life, though it frees, is not meant for mere victory.<br/>God is full of intent, and never could flow aimlessly.<br/>So this life has a totality,<br/>A consummate issue encompassing me.<br/>Life moves and life grows,<br/>Life shapes as it flows,<br/>Now I share in this life''s destiny!<br/>Oh, I''ve got rivers of life flowing out of my innermost being!<br/>I''ve got rivers of life flowing out of my innermost being!<br/>',NULL,14080,14080);
INSERT INTO stanza VALUES('BF60','chorus','We''ll abide, mutually,<br/>God and man revealed to be<br/>Lamb, Wife, Spirit and Bride,<br/>Come, drink! And riverside<br/>Grows the tree — our enjoyment for eternity!<br/>',NULL,14081,14081);
INSERT INTO stanza VALUES('BF60','3','So I''ve no cause to frown, as one who received this zoe,<br/>I know life runs its course, and triumphs inevitably.<br/>I''m required just to stay in the flow.<br/>If I do the drinking, then God gives the growth.<br/>So there''s joy in my heart,<br/>And a spring in my step,<br/>And a smile on my face as I sing:<br/>Oh, I''ve got rivers of life flowing out of my innermost being!<br/>I''ve got rivers of life flowing out of my innermost being!<br/>',NULL,14082,14082);
INSERT INTO stanza VALUES('BF61','1','O Love, that wilt not let me go,<br/>I rest my weary soul in Thee;<br/>I give Thee back the life I owe,<br/>That in Thine ocean depths its flow<br/>May richer, fuller be.<br/>',NULL,14083,14083);
INSERT INTO stanza VALUES('BF61','2','O Light, that followest all my way,<br/>I yield my flickering torch to Thee;<br/>My heart restores its borrowed ray,<br/>That in Thy sunshine''s blaze its day<br/>May brighter, fairer be.<br/>',NULL,14084,14084);
INSERT INTO stanza VALUES('BF61','3','O Joy, that seekest me through pain,<br/>I cannot close my heart to Thee;<br/>I trace the rainbow through the rain,<br/>And feel the promise is not vain<br/>That morn shall tearless be.<br/>',NULL,14085,14085);
INSERT INTO stanza VALUES('BF61','4','O Cross, that liftest up my head,<br/>I dare not ask to fly from Thee;<br/>I lay in dust life''s glory dead,<br/>And from the ground there blossoms red<br/>Life that shall endless be.<br/>',NULL,14086,14086);
INSERT INTO stanza VALUES('BF62','1','Loving You Lord''s all I''m living for,<br/>Loving You Lord to the uttermost.<br/>Lord forgive me if I''ve left my first love<br/>That''s the bridal love for You.<br/>You are more than anyone I love;<br/>You are more than anything I have,<br/>Even my dear self,<br/>Nothing can compare to my beloved Bridegroom.<br/>',NULL,14087,14087);
INSERT INTO stanza VALUES('BF62','chorus','I give You the first place in all things by faith;<br/>Let nothing take Your place in all my heart.<br/>Infuse me with Yourself abundantly.<br/>Till we meet dear Lord,<br/>I''ll love You with my best love.<br/>',NULL,14088,14088);
INSERT INTO stanza VALUES('BF62','2','You''ve the right to take all that I love,<br/>But replace it with Yourself much more.<br/>You are what I need;<br/>Give Yourself to me,<br/>Do not give all that I want.<br/>Everything is sure to pass away,<br/>Everyone is going their own way.<br/>But I still have You and You have me too,<br/>Loving one another''s sweet.<br/>',NULL,14089,14089);
INSERT INTO stanza VALUES('BF62','3','I treasure my time alone with You,<br/>Just to gain the best love You long for.<br/>My dearest Husband,<br/>Draw me with Yourself into Your chambers right now.<br/>Be the first in all my work and life,<br/>Be the first in all my service too.<br/>In relationships, You must be the first,<br/>Have preeminence in me.<br/>',NULL,14090,14090);
INSERT INTO stanza VALUES('BF63','1','I have a friend so precious,<br/>So very dear to me;<br/>He loves me with such tender love,<br/>His love''s so fair and sweet;<br/>I could not live apart from Him,<br/>I love to feel Him nigh;<br/>And so we dwell together,<br/>My Lord and I.<br/>',NULL,14091,14091);
INSERT INTO stanza VALUES('BF63','2','Sometimes I''m faint and weary,<br/>He knows that I am weak;<br/>And as He bids me lean on Him,<br/>His help I gladly seek;<br/>He leads me in the paths of light,<br/>Beneath a sunny sky;<br/>And so we walk together,<br/>My Lord and I.<br/>',NULL,14092,14092);
INSERT INTO stanza VALUES('BF63','3','He knows how much I love Him,<br/>And if I love Him well;<br/>But with what love He loveth me,<br/>My tongue can never tell;<br/>It is an everlasting love,<br/>Much more as days go by;<br/>And so we love each other,<br/>My Lord and I.<br/>',NULL,14093,14093);
INSERT INTO stanza VALUES('BF63','4','I tell Him all my sorrows,<br/>I tell Him all my joys;<br/>I tell Him all that pleases me,<br/>I tell Him what annoys;<br/>He tells me what I ought to do,<br/>He tells me how to try;<br/>And so we walk together,<br/>My Lord and I.<br/>',NULL,14094,14094);
INSERT INTO stanza VALUES('BF63','5','He knows my heart''s such longing,<br/>Some weary soul to win;<br/>And so He bids me go and speak,<br/>The loving word for Him;<br/>He bids me tell His wondrous love,<br/>And why He came to die;<br/>And so we work together,<br/>My Lord and I.<br/>',NULL,14095,14095);
INSERT INTO stanza VALUES('BF64','1','God has a dream, this is what He''s wanting;<br/>God has a dream, and we are part of it.<br/>God has a dream, that we may be one with Him;<br/>God has a dream, realized in you and me!<br/>God, you and me, a dwelling place to be —<br/>God in man, and man in God: one entity.<br/>Now, it''s my dream, my vision and life to be!<br/>God has a dream, realized in you and me!<br/>',NULL,14096,14096);
INSERT INTO stanza VALUES('BF65','1','To You, dear Lord, I give myself afresh again.<br/>Unsparingly for Your desire, Your economy.<br/>O fire from above, come and consume me thoroughly<br/>That You may be my all, my life, my everything.<br/>',NULL,14097,14097);
INSERT INTO stanza VALUES('BF65','2','It''s Your mercy and Your love that I can give myself to You,<br/>Since it''s in the like manner that You gave Yourself up for me.<br/>Set Your throne in my heart, from now on until the very end.<br/>It takes eternity to know its worth<br/>To You, to me.<br/>',NULL,14098,14098);
INSERT INTO stanza VALUES('BF66','1','My song is love unknown,<br/>My Savior''s love to me;<br/>Love to the loveless shown,<br/>That they might lovely be.<br/>O who am I,<br/>That for my sake<br/>My Lord should take<br/>Frail flesh, and die?<br/>',NULL,14099,14099);
INSERT INTO stanza VALUES('BF66','2','He came from His blest throne<br/>Salvation to bestow;<br/>But men made strange, and none<br/>The longed-for Christ would know;<br/>But oh, my Friend,<br/>My Friend indeed,<br/>Who at my need<br/>His life did spend.<br/>',NULL,14100,14100);
INSERT INTO stanza VALUES('BF66','3','Sometimes they strew His way,<br/>And His sweet praises sing;<br/>Resounding all the day<br/>Hosannas to their King:<br/>Then "Crucify!"<br/>Is all their breath,<br/>And for His death<br/>They thirst and cry.<br/>',NULL,14101,14101);
INSERT INTO stanza VALUES('BF66','4','They rise and needs will have<br/>My dear Lord made away;<br/>A murderer they save,<br/>The Prince of life they slay.<br/>Yet cheerful He<br/>To suffering goes,<br/>That He His foes<br/>From thence might free.<br/>',NULL,14102,14102);
INSERT INTO stanza VALUES('BF66','5','In life, no house, no home<br/>My Lord on earth might have;<br/>In death, no friendly tomb,<br/>But what a stranger gave.<br/>What may I say?<br/>Heaven was His home;<br/>But mine the tomb<br/>Wherein He lay.<br/>',NULL,14103,14103);
INSERT INTO stanza VALUES('BF66','6','Here might I stay and sing,<br/>No story so divine;<br/>Never was love, dear King,<br/>Never was grief like Thine.<br/>This is my Friend,<br/>In whose sweet praise<br/>I all my days<br/>Could gladly spend.<br/>',NULL,14104,14104);
INSERT INTO stanza VALUES('BF67','1','There''s a life that''s deeper than our mind,<br/>With experience of man, yet so divine.<br/>It''s a Life that knows no bounds;<br/>And with glory is crowned;<br/>It''s of depth and height and breadth unsearchable.<br/>Now this life is just the Living One<br/>Manifested in the person of the Son.<br/>As the Spirit, He flows;<br/>In our spirit He grows,<br/>Growing up to be the church that He desires.<br/>',NULL,14105,14105);
INSERT INTO stanza VALUES('BF67','chorus','O Lord, we''re just for Your flowing;<br/>How we need a deeper knowing!<br/>Life is why we''re here<br/>And why You''ve come in us.<br/>Turn us, Lord, turn us now;<br/>Turn us deeply — Life is how<br/>You will get the church,<br/>The home You''re longing for.<br/>',NULL,14106,14106);
INSERT INTO stanza VALUES('BF67','2','In the church, we all can apprehend<br/>All the riches of this life that is within.<br/>Not just shallowness with strife,<br/>But a deep and peaceful life<br/>Is just waiting to flow out, a living spring.<br/>With the saints it''s easy to be bold,<br/>To pursue this life, to gain it, to lay hold.<br/>All the other things we find,<br/>Must be quickly left behind,<br/>So that only life remains for us to see.<br/>',NULL,14107,14107);
INSERT INTO stanza VALUES('BF67','3','Deeper, Lord, our turn must be to You;<br/>We would move by life in everything we do:<br/>All our concept refute,<br/>For Your life be absolute —<br/>Grant us grace to turn much deeper day by day.<br/>When we touch our spirit — such a thrill!<br/>This is far beyond emotion, mind, and will —<br/>It''s within our hidden part —<br/>Come, make home in all our heart;<br/>Let Your presence flow as rivers deep within.<br/>',NULL,14108,14108);
INSERT INTO stanza VALUES('BF68','1','Oh, the church of Christ is glorious, and we are part of it—<br/>We''re so happy that the Lord has made us one!<br/>There''s a Body in the universe and we belong to it—<br/>Hallelujah, for the Lord has made us one!<br/>',NULL,14109,14109);
INSERT INTO stanza VALUES('BF68','chorus','Hallelujah for the Body!<br/>We are members of the Body!<br/>We are wholly for the Body!<br/>Hallelujah, for the Lord has made us one!<br/>',NULL,14110,14110);
INSERT INTO stanza VALUES('BF68','2','Not the individual Christians, but a corporate entity—<br/>God must have it for His full expression now;<br/>Not just individual churches but the Body corporately—<br/>Hallelujah, we are in the Body now!<br/>',NULL,14111,14111);
INSERT INTO stanza VALUES('BF68','chorus','Hallelujah for the Body<br/>Satan trembles at the Body!<br/>We''re victorious in the Body!<br/>Hallelujah, we are in the Body now!<br/>',NULL,14112,14112);
INSERT INTO stanza VALUES('BF68','3','There are seven golden lampstands in the nature all divine—<br/>Nothing natural does the Body life allow.<br/>When we''re one and share God''s nature, how the lampstand<br/>then does shine—<br/>Hallelujah, it is brightly shining now!<br/>',NULL,14113,14113);
INSERT INTO stanza VALUES('BF68','chorus','Hallelujah for the Body!<br/>For the lampstands of the Body!<br/>For the golden, shining Body!<br/>Hallelujah, it is brightly shining now!<br/>',NULL,14114,14114);
INSERT INTO stanza VALUES('BF68','4','How may we express such oneness, be divine and shining too?<br/>Hallelujah, eating Jesus is the way!<br/>He''s the tree of life, the manna, and the feast that''s ever new—<br/>Hallelujah, we may eat Him every day!<br/>',NULL,14115,14115);
INSERT INTO stanza VALUES('BF68','chorus','We are one by eating Jesus!<br/>We''re divine by eating Jesus!<br/>How we shine by eating Jesus!<br/>Hallelujah, eating Jesus is the way!<br/>',NULL,14116,14116);
INSERT INTO stanza VALUES('BF69','1','When I''ve run the race before me<br/>And have fought to victory,<br/>I''ll be raptured to the glory of the Lord,<br/>When I''ve kept the faith at any cost,<br/>The Holy City then<br/>I''ll receive as my reward.<br/>',NULL,14117,14117);
INSERT INTO stanza VALUES('BF69','chorus','I''ll be raptured into glory,<br/>In the Holy City dwell —<br/>New Jerusalem, New Jerusalem;<br/>With the overcomers shouting,<br/>How our praises then will swell,<br/>In the New Jerusalem.<br/>',NULL,14118,14118);
INSERT INTO stanza VALUES('BF69','2','As a pilgrim here I wander;<br/>While afflicted, I rejoice,<br/>For a better land I soon expect to see;<br/>Though all others seek for earthly gain,<br/>The Holy City e''er<br/>Will my aspiration be.<br/>',NULL,14119,14119);
INSERT INTO stanza VALUES('BF69','3','Though my feet are often wearied<br/>On the rough and rugged path,<br/>Just by thinking of that city, I''m restored;<br/>Though my eyes be filled with tears,<br/>My heart will evermore be fixed<br/>On that City, my reward.<br/>',NULL,14120,14120);
INSERT INTO stanza VALUES('BF69','4','With strong purpose I now wrestle;<br/>And I run toward the goal;<br/>I pursue the prize, God''s highest to obtain;<br/>Pressing forward toward the mark,<br/>I run forgetting all behind,<br/>Thus the Holy City gain.<br/>',NULL,14121,14121);
INSERT INTO stanza VALUES('BF69','chorus','By His love and through His grace I''ll<br/>In the Holy City live —<br/>New Jerusalem, New Jerusalem;<br/>All the saints leaping, singing, shouting,<br/>To the Lord their praises give,<br/>In the New Jerusalem.<br/>',NULL,14122,14122);
INSERT INTO stanza VALUES('BF70','1','Drink! A river pure and clear that''s flowing from the throne;<br/>Eat! The tree of life with fruits abundant, richly grown;<br/>Look! No need of lamp nor sun nor moon to keep it bright, for<br/>Here there is no night!<br/>',NULL,14123,14123);
INSERT INTO stanza VALUES('BF70','chorus','Do come, oh, do come,<br/>Says Spirit and the Bride:<br/>Do come, oh, do come,<br/>Let him that heareth, cry.<br/>Do come, oh, do come,<br/>Let him who thirsts and will<br/>Take freely the water of life!<br/>',NULL,14124,14124);
INSERT INTO stanza VALUES('BF70','2','Christ, our river, Christ, our water, springing from within;<br/>Christ, our tree, and Christ, the fruits, to be enjoyed therein,<br/>Christ, our day, and Christ, our light, and Christ, our morning star:<br/>Christ, our everything!<br/>',NULL,14125,14125);
INSERT INTO stanza VALUES('BF70','3','We are washing all our robes the tree of life to eat;<br/>"O Lord, Amen, Hallelujah!"—Jesus is so sweet!<br/>We our spirits exercise, and thus experience Christ.<br/>What a Christ have we!<br/>',NULL,14126,14126);
INSERT INTO stanza VALUES('BF70','4','Now we have a home so bright that outshines the sun,<br/>Where the brothers all unite and truly are one.<br/>Jesus gets us all together, Him we now display<br/>In the local church.<br/>',NULL,14127,14127);
INSERT INTO stanza VALUES('BF71','1','How could a country girl like me<br/>Become Your match — Your bride to be?<br/>You''re holy and You are divine<br/>But I''m fallen and human.<br/>Without You, Lord, I have no chance<br/>To be like You in this romance.<br/>But You chose me ere the world began<br/>Nothing could change Your plan.<br/>',NULL,14128,14128);
INSERT INTO stanza VALUES('BF71','chorus','This divine romance<br/>Is My heart''s deep plan.<br/>I became a lowly man<br/>To court My country girl.<br/>Nothing could deter.<br/>Nothing can alter<br/>My eternal love for her I''ll gain<br/>My country girl.<br/>',NULL,14129,14129);
INSERT INTO stanza VALUES('BF71','2','No man or angel ever knew<br/>This secret hidden deep in You<br/>That You desired to be one with man<br/>Before the world began.<br/>Though sin came in to ruin me<br/>Through Satan''s scheme and subtlety<br/>Nothing could break Your love for me<br/>To gain me totally.<br/>',NULL,14130,14130);
INSERT INTO stanza VALUES('BF71','3','As King of kings You became a man,<br/>You died for me — I''ve been redeemed,<br/>In resurrection made us queen<br/>To marry You, my King.<br/>From death You rose and entered me,<br/>I now possess Your divinity;<br/>In life and nature we''re the same:<br/>Both human and divine.<br/>',NULL,14131,14131);
INSERT INTO stanza VALUES('BF71','chorus','In Your love I''m drawn,<br/>To You I belong;<br/>I am not my own, Lord,<br/>I''m Yours alone.<br/>By Your love I''m drawn,<br/>In Your name I''m charmed,<br/>And Your person captured me,<br/>For I''ve been kissed by Thee.<br/>',NULL,14132,14132);
INSERT INTO stanza VALUES('BF71','4','Lord, in this close sweet fellowship,<br/>Lord, be with me so intimate,<br/>So personal and affectionate;<br/>A sweet relationship.<br/>Lord, daily change my inward being<br/>Lord, all my heart possessing<br/>In all my being — transforming<br/>To be Your bride and queen.<br/>(Chorus 2)<br/>',NULL,14133,14133);
INSERT INTO stanza VALUES('BF72','1','He''s the Spirit of Reality<br/>Pneumatic Christ, the Firstborn Son in me.<br/>The consummation of the Triune God<br/>Life-giving Spirit, all-inclusive Christ<br/>Intensified sevenfold<br/>',NULL,14134,14134);
INSERT INTO stanza VALUES('BF72','2','He''s the Spirit of Reality.<br/>He''s the secret. He is one with me;<br/>He''s in my spirit. God dispensed in me<br/>From my spirit, soul and then, body,<br/>Producing reality.<br/>',NULL,14135,14135);
INSERT INTO stanza VALUES('BF72','3','Don''t be fooled by outward circumstance.<br/>Lord, do grant us visions and a trance:<br/>The New Jerusalem, a mingling<br/>A mutual dwelling place of God and man.<br/>Lord, You''re reality!<br/>',NULL,14136,14136);
INSERT INTO stanza VALUES('BF72','4','Seven Spirits and the seven eyes,<br/>Organic salvation He intensifies.<br/>Producing overcomers in this age,<br/>To build His Body and to consummate<br/>The New Jerusalem.<br/>',NULL,14137,14137);
INSERT INTO stanza VALUES('BF73','1','Marvelous, marvelous,<br/>Marvelous, marvelous,<br/>Things, Praise the Lord.<br/>(Repeat)<br/>',NULL,14138,14138);
INSERT INTO stanza VALUES('BF73','2','He has done marvelous,<br/>He has done marvelous,<br/>Things, Praise the Lord.<br/>(Repeat)<br/>',NULL,14139,14139);
INSERT INTO stanza VALUES('BF73','3','He''s done marvelous things;<br/>He''s done marvelous things,<br/>Praise the Lord.<br/>(Repeat)<br/>',NULL,14140,14140);
INSERT INTO stanza VALUES('BF73','4','Vitality, vitality,<br/>Vitality, vitality,<br/>Recovery.<br/>(Repeat)<br/>',NULL,14141,14141);
INSERT INTO stanza VALUES('BF73','5','Personal vitality,<br/>Companionship, vital groups<br/>Body of Christ.<br/>(Repeat)<br/>',NULL,14142,14142);
INSERT INTO stanza VALUES('BF73','6','Gospel, shepherding<br/>Prophesying,<br/>God''s ordained way.<br/>(Repeat)<br/>',NULL,14143,14143);
INSERT INTO stanza VALUES('BF74','1','Christ is the complete God<br/>Manifested in the flesh;<br/>God infinite, man finite.<br/>Christ is the Word<br/>Who was God becoming flesh<br/>Conceived with<br/>The Spirit''s divine essence<br/>',NULL,14144,14144);
INSERT INTO stanza VALUES('BF74','chorus','For the union, mingling<br/>And incorporation<br/>Of the Triune God<br/>With the tripartite man.<br/>',NULL,14145,14145);
INSERT INTO stanza VALUES('BF74','chorus','God''s eternal economy is to make man<br/>The same as He is<br/>In life, expression, nature and function;<br/>Thus to be enlarged, expanded<br/>That His divine attributes<br/>May be expressed in human virtues.<br/>Issuing the universal, divine human incorporation<br/>To consummate the New Jerusalem.<br/>',NULL,14146,14146);
INSERT INTO stanza VALUES('BF74','2','His name the mighty God,<br/>Eternal Father;<br/>He''s Jehovah, our Savior,<br/>And He was called God with us, Emmanuel.<br/>In Him dwells the fullness of the Godhead.<br/>He is the great I AM, the myst''ry of God;<br/>The only begotten Son who declares God.<br/>',NULL,14147,14147);
INSERT INTO stanza VALUES('BF74','chorus','O can you see His living Body?<br/>Lord, show me more each day.<br/>I cannot live without the Body!<br/>My prayer today is to love You.<br/>Make my love fresh and new.<br/>May love prevail and build your church today!<br/>',NULL,14148,14148);
INSERT INTO stanza VALUES('BF75','1','Abide in Thee! In that deep love of Thine,<br/>My Jesus, Lord, Thou Lamb of God divine,<br/>Down, closely down, as living branch with tree,<br/>I would abide, my Lord, my Christ, in Thee.<br/>',NULL,14149,14149);
INSERT INTO stanza VALUES('BF75','2','Abide in Thee! My Savior God, I know<br/>How love of Thine so vast in me may flow,<br/>My empty vessel, running o''er with joy,<br/>Must overflow to Thee without alloy.<br/>',NULL,14150,14150);
INSERT INTO stanza VALUES('BF75','3','Abide in Thee! Nor doubt, nor self, nor sin,<br/>Can e''er prevail with Thy blest life within;<br/>Joined to Thyself, communing deep, my soul<br/>Knows naught besides its motions to control.<br/>',NULL,14151,14151);
INSERT INTO stanza VALUES('BF75','4','Abide in Thee! ''tis thus I only know<br/>The secrets of Thy mind e''en while below —<br/>All joy and peace, and knowledge of Thy word,<br/>All pow''r and fruit, and service for the Lord.<br/>',NULL,14152,14152);
INSERT INTO stanza VALUES('BF76','1','What miracle! What mystery!<br/>That God and man should blended be!<br/>God became man to make man God —<br/>Untraceable economy!<br/>From His good pleasure, heart''s desire,<br/>His highest goal attained will be.<br/>(Repeat last two lines of each stanza)<br/>',NULL,14153,14153);
INSERT INTO stanza VALUES('BF76','2','Flesh He became, the first God-man,<br/>His pleasure that I God may be.<br/>In life and nature I''m God''s kind,<br/>Though Godhead''s His exclusively.<br/>His attributes my virtues are;<br/>His glorious image shines through me.<br/>',NULL,14154,14154);
INSERT INTO stanza VALUES('BF76','3','No longer I alone that live,<br/>But God together lives with me.<br/>Built with the saints in the Triune God,<br/>His universal house we''ll be,<br/>And His organic Body we<br/>For His expression corp''rately.<br/>',NULL,14155,14155);
INSERT INTO stanza VALUES('BF76','4','Jerusalem, the ultimate,<br/>Of visions the totality;<br/>The Triune God, tripartite man —<br/>A loving pair eternally-<br/>As man yet God they coinhere,<br/>A mutual dwelling place to be;<br/>God''s glory in humanity<br/>Shines forth in splendor radiantly!<br/>',NULL,14156,14156);
INSERT INTO stanza VALUES('BF77','1','The spirit of the prophet is subject to the prophet:<br/>The word declares it so.<br/>I don''t have to wait for an inspiration,<br/>My spirit is ready to go.<br/>',NULL,14157,14157);
INSERT INTO stanza VALUES('BF77','2','I don''t have to live according to my feelings,<br/>Or wait for a better day.<br/>I can turn, I can call, "Lord Jesus!"<br/>',NULL,14158,14158);
INSERT INTO stanza VALUES('BF78','1','My God, my Portion, and my Love,<br/>My everlasting All,<br/>I''ve none but Thee in heav''n above,<br/>Or on this earthly ball,<br/>What empty things are all the skies,<br/>And this inferior clod!<br/>There''s nothing here deserves my joys,<br/>There''s nothing like my God.<br/>',NULL,14159,14159);
INSERT INTO stanza VALUES('BF78','2','To Thee I owe my wealth, and friends,<br/>And health, and safe abode;<br/>Thanks to Thy name for meaner things,<br/>But they are not my God.<br/>How vain a toy is glittering wealth,<br/>If once compared to Thee!<br/>Or what''s my safety, or my health,<br/>Or all my friends to me,<br/>',NULL,14160,14160);
INSERT INTO stanza VALUES('BF78','3','Were I possessor of the earth,<br/>And called the stars my own,<br/>Without Thy graces and Thyself,<br/>I were a wretch undone.<br/>Let others stretch their arms like seas,<br/>And grasp in all the shore;<br/>Grant me the visits of Thy grace,<br/>And I desire no more.<br/>',NULL,14161,14161);
INSERT INTO stanza VALUES('BF79','1','God eternal has a purpose,<br/>Formed in His eternal past,<br/>Spreading to eternal future;<br/>''Twixt these ends all time is cast.<br/>For with time there is the process,<br/>Time for His accomplishment;<br/>And in time we''re merely travelers —<br/>For eternity we''re meant.<br/>',NULL,14162,14162);
INSERT INTO stanza VALUES('BF79','2','God would have a group of people<br/>Built together in His plan,<br/>Blended, knit, coordinated<br/>As His vessel — one new man.<br/>God would come into this vessel<br/>With His nature, life and ways,<br/>Mingling Spirit with our spirits<br/>For His joy and to His praise.<br/>',NULL,14163,14163);
INSERT INTO stanza VALUES('BF79','3','God has worked in three directions<br/>For His plan so marvelous:<br/>As the Father, Son, and Spirit<br/>To dispense Himself to us!<br/>All creation gives the setting —<br/>Heav''n and earth are for this plan;<br/>''Tis for this God made a body,<br/>Soul and spirit — three-part man.<br/>',NULL,14164,14164);
INSERT INTO stanza VALUES('BF79','4','As the center, as the kernel,<br/>Of God''s plan our spirit is;<br/>Calling on the name of Jesus<br/>Makes our spirit one with His.<br/>From the center to circumference<br/>God would saturate each part;<br/>Feeling, mind, and will renewing,<br/>Making home in all our heart.<br/>',NULL,14165,14165);
INSERT INTO stanza VALUES('BF79','5','Thus in life we''re built together,<br/>Then in love we''re knit as one;<br/>God is now His plan fulfilling,<br/>Finishing what He''s begun.<br/>Lord, increase Thyself within us<br/>That we might be built by Thee<br/>Into that great corporate vessel<br/>Filled with God exclusively.<br/>',NULL,14166,14166);
INSERT INTO stanza VALUES('BF79','6','As the product, the fulfillment,<br/>Will the church in glory stand,<br/>Consummation of the purpose<br/>In eternal ages planned.<br/>God will have His corporate vessel,<br/>All His glory to contain;<br/>Lord, we''re wholly for Thy purpose<br/>All Thy goal in us attain.<br/>',NULL,14167,14167);
INSERT INTO stanza VALUES('BF80','1','When the Lord turned again the captivity of Zion,<br/>We were like them that dream,<br/>We were like them that dream.<br/>',NULL,14168,14168);
INSERT INTO stanza VALUES('BF80','2','Then was our mouth filled with laughter,<br/>And our tongue with singing:<br/>Then said they among the nations,<br/>The Lord hath done great things,<br/>The Lord hath done great things for them.<br/>',NULL,14169,14169);
INSERT INTO stanza VALUES('BF80','chorus','The Lord hath done great things for us;<br/>Whereof we are glad.<br/>The Lord hath done great things for us;<br/>Whereof we are glad.<br/>',NULL,14170,14170);
INSERT INTO stanza VALUES('BF80','3','Turn again our captivity, O Lord, as the streams,<br/>As the streams in the south,<br/>As the streams in the south.<br/>',NULL,14171,14171);
INSERT INTO stanza VALUES('BF80','4','They that sow in tears shall reap in joy,<br/>They that sow in tears shall reap in joy.<br/>',NULL,14172,14172);
INSERT INTO stanza VALUES('BF80','5','He that goeth forth and weepeth,<br/>Bearing precious seed, shall doubtless,<br/>Come again with rejoicing,<br/>Come again with rejoicing,<br/>Bringing his sheaves with him.<br/>',NULL,14173,14173);
INSERT INTO stanza VALUES('BF80','chorus','The Lord hath done great things for us;<br/>Whereof we are glad.<br/>The Lord hath done great things for us;<br/>Whereof we are glad.<br/>',NULL,14174,14174);
INSERT INTO stanza VALUES('BF80','6','When the Lord turned again the captivity of Zion,<br/>We were like them that dream,<br/>We were like them that dream.<br/>',NULL,14175,14175);
INSERT INTO stanza VALUES('BF81','1','We have oil in our lamps we are burning!<br/>We have oil in our lamps today!<br/>To our spirit, O Lord, keep us turning,<br/>Keep us turning, turning all the way<br/>',NULL,14176,14176);
INSERT INTO stanza VALUES('BF81','chorus','O Lord! Amen! Hallelujah!<br/>We are burning, burning every day!<br/>O Lord! Amen! Hallelujah!<br/>Turning, turning all the way!<br/>',NULL,14177,14177);
INSERT INTO stanza VALUES('BF81','2','But our vessels need oil for Thy coming;<br/>We must gain a reserve supply.<br/>So our vessels we give for Thy filling<br/>That our lamps may never, never die.<br/>',NULL,14178,14178);
INSERT INTO stanza VALUES('BF81','chorus','Fill us, Jesus! Fill us, Jesus!<br/>Every moment give us more of Thee!<br/>Fill us, Jesus! Fill us, Jesus!<br/>Fill us with reality!<br/>',NULL,14179,14179);
INSERT INTO stanza VALUES('BF81','3','Then we''ll burn till the Lord comes to meet us;<br/>Then we''ll burn till He comes that day.<br/>Then we''ll go in with Him to the wedding<br/>And be brightly burning all the way.<br/>',NULL,14180,14180);
INSERT INTO stanza VALUES('BF81','chorus','Come, Lord Jesus! Come, Lord Jesus!<br/>Come and find us filled and burning bright!<br/>Come, Lord Jesus! Come, Lord Jesus!<br/>Come and in Thy Bride delight.<br/>',NULL,14181,14181);
INSERT INTO stanza VALUES('BF82','1','A new commandment<br/>I give unto you<br/>That you love one another<br/>As I have loved you,<br/>That you love one another<br/>As I have loved you.<br/>By this shall all men<br/>Know you are My disciples<br/>If you have love one to another.<br/>(Repeat the last three lines)<br/>',NULL,14182,14182);
INSERT INTO stanza VALUES('BF83','1','Come let us speak till the kingdom of the Lord comes down.<br/>Yes, let us speak till the kingdom of the Lord comes down.<br/>Why hold your peace?<br/>The Word release.<br/>Let us speak until the kingdom of the Lord comes down.<br/>',NULL,14183,14183);
INSERT INTO stanza VALUES('BF83','2','Oh, loose the Word! It shall not return unto Him void.<br/>Yes, loose the Word! It shall not return unto Him void.<br/>Let''s sow the seed,<br/>This is our need;<br/>Loose the Word, and it shall not return unto Him void!<br/>',NULL,14184,14184);
INSERT INTO stanza VALUES('BF83','3','It''s gospel time! Let us spread the gospel all around.<br/>Yes, gospel time! We will never fear the people''s frown!<br/>God''s done His work;<br/>Let us not shirk;<br/>We''re but pilgrims here, and we''ll not fear the people''s frown!<br/>',NULL,14185,14185);
INSERT INTO stanza VALUES('BF83','4','If we will speak, Christ will witness in the hearts of men.<br/>If we will speak, Christ will witness in the hearts of men.<br/>Tell every man,<br/>Win all we can.<br/>Through our speaking, Christ is speaking in the hearts of men!<br/>',NULL,14186,14186);
INSERT INTO stanza VALUES('BF83','5','The harvest''s ripe! We are preaching the full gospel now!<br/>The fields are white! We are preaching the full gospel now!<br/>For this men search —<br/>Christ and the church!<br/>Let us reap the harvest, preaching the full gospel now!<br/>',NULL,14187,14187);
INSERT INTO stanza VALUES('BF84','1','Jesus Lord, I''m captured by Thy beauty,<br/>All my heart to Thee I open wide;<br/>Now set free from all religious duty,<br/>Only let me in Thyself abide.<br/>As I''m gazing here upon Thy glory,<br/>Fill my heart with radiancy divine;<br/>Saturate me, Lord, I now implore Thee,<br/>Mingle now Thy Spirit, Lord, with mine.<br/>',NULL,14188,14188);
INSERT INTO stanza VALUES('BF84','2','Shining One—how clear the sky above me!<br/>Son of Man, I see Thee on the throne!<br/>Holy One, the flames of God consume me,<br/>Till my being glows with Thee alone.<br/>Lord, when first I saw Thee in Thy splendor,<br/>All self-love and glory sank in shame;<br/>Now my heart its love and praises render,<br/>Tasting all the sweetness of Thy name.<br/>',NULL,14189,14189);
INSERT INTO stanza VALUES('BF84','3','Precious Lord, my flask of alabaster<br/>Gladly now I break in love for Thee;<br/>I anoint Thy head, beloved Master;<br/>Lord, behold, I''ve saved the best for Thee.<br/>Dearest Lord, I waste myself upon Thee;<br/>Loving Thee, I''m deeply satisfied.<br/>Love outpoured from hidden depths within me,<br/>Costly oil, dear Lord, I would provide.<br/>',NULL,14190,14190);
INSERT INTO stanza VALUES('BF84','4','My Beloved, come on spices'' mountain;<br/>How I yearn to see Thee face to face.<br/>Drink, dear Lord, from my heart''s flowing fountain,<br/>Till I rest fore''er in Thine embrace.<br/>Not alone, O Lord, do I adore Thee,<br/>But with all the saints as Thy dear Bride;<br/>Quickly come, our love is waiting for Thee;<br/>Jesus Lord, Thou wilt be satisfied.<br/>',NULL,14191,14191);
INSERT INTO stanza VALUES('BF85','1','The love of God and the grace of Christ,<br/>And fellowship of the Holy Spirit<br/>Be with you, be with you all,<br/>Be with you all, be with you all.<br/>',NULL,14192,14192);
INSERT INTO stanza VALUES('BF85','2','From the throne of our God and the Lamb,<br/>Flows a river of water of life,<br/>Bright as crystal, reaching man.<br/>',NULL,14193,14193);
INSERT INTO stanza VALUES('BF86','1','Christ has put on human nature and become a man like me,<br/>He has died upon the cross that I from Adam might be free,<br/>He has risen and as Spirit He has come to live in me<br/>That He might be my life.<br/>',NULL,14194,14194);
INSERT INTO stanza VALUES('BF86','2','First chorus:<br/>Glory! glory! Hallelujah!<br/>Glory! glory! Hallelujah!<br/>Glory! glory! Hallelujah!<br/>For Christ is now my life!<br/>',NULL,14195,14195);
INSERT INTO stanza VALUES('BF86','3','Second chorus:<br/>Vict''ry! vict''ry! Hallelujah!<br/>Vict''ry! vict''ry! Hallelujah!<br/>Vict''ry! vict''ry! Hallelujah!<br/>For Christ is now my all!<br/>',NULL,14196,14196);
INSERT INTO stanza VALUES('BF87','1','Is there someone who''s a friend<br/>that I can open to?<br/>A someone who understands<br/>all that I''m going through?<br/>A someone when there''s no one<br/>I can always come to?<br/>There is no someone like this One.<br/>',NULL,14197,14197);
INSERT INTO stanza VALUES('BF87','2','Is there someone who can care<br/>through all may hardest times?<br/>A someone always there<br/>though it may rain or shine?<br/>A someone I can lean on<br/>when the stormy times come?<br/>There is no someone like this One.<br/>',NULL,14198,14198);
INSERT INTO stanza VALUES('BF87','3','Is there someone who will take<br/>take me just as I am?<br/>A someone who''ll not forsake<br/>one I can trust to the end?<br/>A someone who know me<br/>yet He still wants me?<br/>There is no someone like this One.<br/>',NULL,14199,14199);
INSERT INTO stanza VALUES('BF87','4','Is there someone who can reach<br/>down to the depths of my being?<br/>A someone who can fix<br/>all of my broken heart strings?<br/>A someone who can love in me<br/>when there''s no love in me?<br/>There is no someone like this one.<br/>',NULL,14200,14200);
INSERT INTO stanza VALUES('BF87','chorus','Echo:<br/>There is a Someone,<br/>Someone you can open to.<br/>There is a Someone,<br/>Someone who will take you through.<br/>There is a Someone,<br/>when there is no one.<br/>There is a Someone, a wonderful One.<br/>',NULL,14201,14201);
INSERT INTO stanza VALUES('BF87','chorus','There is a Someone,<br/>Someone in my hardest times.<br/>There is a Someone,<br/>always there through rain or shine.<br/>There is a Someone,<br/>when there is no one.<br/>There is a Someone, a special One.<br/>',NULL,14202,14202);
INSERT INTO stanza VALUES('BF87','chorus','There is a Someone,<br/>who will take you as you are.<br/>There is a Someone,<br/>He will reach you near or far.<br/>There is a Someone,<br/>He''s the most lovely One.<br/>Just take this Someone,<br/>the loveliest One.<br/>',NULL,14203,14203);
INSERT INTO stanza VALUES('BF87','chorus','There is a Someone,<br/>Who can touch your inmost being.<br/>There is a Someone,<br/>He can make your heart to sing.<br/>There is a Someone,<br/>Love is this precious One.<br/>Just love this Someone,<br/>the wonderful One.<br/>',NULL,14204,14204);
INSERT INTO stanza VALUES('BF87','chorus','Finish:<br/>Christ is this Someone,<br/>Who can touch your inmost being.<br/>Christ is this Someone,<br/>He can make your heart to sing.<br/>Christ is this Someone,<br/>Christ is this precious One.<br/>Just love this Someone,<br/>the wonderful One.<br/>',NULL,14205,14205);
INSERT INTO stanza VALUES('BF88','1','Just one touch of You, dear Lord,<br/>Just one look into Your eyes,<br/>Just one kiss from You.<br/>You''re all I need, my Love.<br/>',NULL,14206,14206);
INSERT INTO stanza VALUES('BF88','2','Let me hear again Your voice.<br/>You are now my final choice.<br/>Speak in love to me.<br/>I''ll waste myself on Thee.<br/>',NULL,14207,14207);
INSERT INTO stanza VALUES('BF88','chorus','Nothing and no one can satisfy me but You anymore.<br/>Jesus, I love You, my only desire,<br/>O Lord, I just love You.<br/>',NULL,14208,14208);
INSERT INTO stanza VALUES('BF88','3','Let me touch You as before,<br/>Craving for You more and more,<br/>You''re the very best!<br/>I''ll drop the rest for You.<br/>',NULL,14209,14209);
INSERT INTO stanza VALUES('BF88','4','Oh, the kisses of Your mouth<br/>Make my lips to praise and shout.<br/>Lord, You''re full of grace<br/>Oh, what a taste, my Love!<br/>',NULL,14210,14210);
INSERT INTO stanza VALUES('BF88','chorus','Nothing and no one can satisfy me but You anymore.<br/>Jesus, my first Love,<br/>Oh, set me on fire<br/>For You, my only desire.<br/>',NULL,14211,14211);
INSERT INTO stanza VALUES('BF88','5','Just infuse me with Your eyes.<br/>Oh! This union satisfies!<br/>As I gaze on You,<br/>I''m filled with You, my Love.<br/>',NULL,14212,14212);
INSERT INTO stanza VALUES('BF88','6','Only You alone will do.<br/>I can''t make it without You.<br/>Keep me close to You,<br/>Just joined to You as one.<br/>',NULL,14213,14213);
INSERT INTO stanza VALUES('BF88','chorus','Nothing and no one can satisfy me but You anymore.<br/>Jesus, I love You, my only desire.<br/>Oh, set my heart on fire.<br/>',NULL,14214,14214);
INSERT INTO stanza VALUES('BF88','7','I repent and now return,<br/>Grant my heart for You to burn.<br/>Flame in me this zeal.<br/>Lord, be in me so real!<br/>(Repeat)<br/>',NULL,14215,14215);
INSERT INTO stanza VALUES('BF88','chorus','Jesus, my first Love! O Jesus, my best Love,<br/>I now return to You.<br/>Jesus, my first Love! O Jesus, my best Love,<br/>I love You, I just love You!<br/>',NULL,14216,14216);
INSERT INTO stanza VALUES('BF89','1','Life is God the Father<br/>In Christ Jesus as the Spirit<br/>Flowing out and coming into us.<br/>He''s not just a teaching,<br/>Or a creed or a dead doctrine,<br/>But the processed Triune God, glorious!<br/>',NULL,14217,14217);
INSERT INTO stanza VALUES('BF89','2','Life is not created<br/>As man''s body, soul, and spirit —<br/>That''s man''s life that''s weak and temporal.<br/>Life is uncreated,<br/>It''s divine and it''s eternal.<br/>And this Life is the life that''s indestructible.<br/>',NULL,14218,14218);
INSERT INTO stanza VALUES('BF89','3','And this Life came in us<br/>In our spirit through the Spirit;<br/>This is where we were made alive!<br/>Now this Life is spreading.<br/>Lord don''t stop — just keep invading;<br/>For this Lord, we must be daily revived.<br/>',NULL,14219,14219);
INSERT INTO stanza VALUES('BF89','4','Life needs our maintaining,<br/>Otherwise we''re suffocating.<br/>Calling on His name we breathe Him in.<br/>Everywhere we breathe Him,<br/>Makes us fresh and makes us living.<br/>O, this Life is full of hope and meaning.<br/>',NULL,14220,14220);
INSERT INTO stanza VALUES('BF89','5','In our daily living<br/>It''s this Life that we are sensing.<br/>Are we in the flesh or in the Lord?<br/>If you''re dead and empty<br/>And troubles you have plenty,<br/>Saints, get out of there and flee back to the Lord!<br/>',NULL,14221,14221);
INSERT INTO stanza VALUES('BF89','6','Then you''ll sense life flowing.<br/>It''s this Life that''s overcoming<br/>Satan, flesh, and the world, and sin.<br/>What a life we''re having.<br/>Lord, Your virtues manifesting,<br/>Thus, we''re branches bearing fruit in John 15.<br/>',NULL,14222,14222);
INSERT INTO stanza VALUES('BF90','1','Every new day''s a new start<br/>Lord, again we''re coming to You.<br/>Lord, could You ever break through within us<br/>If, Lord, we gave You a part?<br/>',NULL,14223,14223);
INSERT INTO stanza VALUES('BF90','chorus','O Lord, we can''t do it on our own.<br/>O Lord Jesus, how we need You!<br/>Win us, woo us, to Thyself, Lord<br/>That we''d ever stay Lord with You.<br/>',NULL,14224,14224);
INSERT INTO stanza VALUES('BF90','2','Lord, before time had begun,<br/>We were marked and called out by You.<br/>We had no choice, we were trapped by You, Lord;<br/>We had no place we could run.<br/>',NULL,14225,14225);
INSERT INTO stanza VALUES('BF90','3','Some of my friends are so free.<br/>Who could I blame, Lord, but Thee?<br/>I cannot do all the things that they do<br/>Because You set me apart.<br/>',NULL,14226,14226);
INSERT INTO stanza VALUES('BF90','4','Lord, I''m realizing that<br/>Loving You''s a tender trap.<br/>Since You have touched me, my heart has melted;<br/>All my resistance has cracked.<br/>',NULL,14227,14227);
INSERT INTO stanza VALUES('BF91','1','What made You, Lord, to die for me?<br/>Why would You die for me, Your enemy?<br/>You took my place to hang on a tree,<br/>To be a curse, a curse for me.<br/>',NULL,14228,14228);
INSERT INTO stanza VALUES('BF91','chorus','What made You die for me?<br/>I was Your enemy.<br/>Lord, You became a curse for me.<br/>Oh, what a mystery,<br/>My God You died for me!<br/>You died for me, Your enemy.<br/>',NULL,14229,14229);
INSERT INTO stanza VALUES('BF91','2','I never thought that You would be<br/>So full of love and tender mercy.<br/>How could You love a person like me?<br/>You loved me, dear Jesus, Your enemy.<br/>',NULL,14230,14230);
INSERT INTO stanza VALUES('BF91','3','You loved me, Lord, so very long;<br/>And with a love enduring and strong.<br/>Although I mocked and cursed You so long,<br/>You waited and prayed for me all along.<br/>',NULL,14231,14231);
INSERT INTO stanza VALUES('BF91','4','I was a man who was just sin,<br/>Which issued in a life full of sins.<br/>My heart toward You was in rebellion,<br/>But, Lord, You touched me with Your compassion.<br/>',NULL,14232,14232);
INSERT INTO stanza VALUES('BF91','chorus','Your love has conquered me,<br/>Even Your enemy.<br/>In love, dear Lord, You came to me.<br/>Nothing could change me<br/>But love and mercy.<br/>Your love, dear Lord, has conquered me.<br/>',NULL,14233,14233);
INSERT INTO stanza VALUES('BF91','5','One little turn and You were there,<br/>Waiting for me with Your loving care.<br/>How could I still remain Your enemy?<br/>Your love, dear Jesus, disarmed me.<br/>',NULL,14234,14234);
INSERT INTO stanza VALUES('BF92','1','Throughout the past twenty centuries,<br/>Thousands of precious lives, heart treasures,<br/>All their high positions<br/>And all their golden futures<br/>Have been "wasted" upon the Lord,<br/>Upon the Lord Jesus.<br/>',NULL,14235,14235);
INSERT INTO stanza VALUES('BF92','2','To us, who love Him in this way,<br/>He''s altogether lovely,<br/>He''s altogether lovely,<br/>And worthy of our offering.<br/>',NULL,14236,14236);
INSERT INTO stanza VALUES('BF92','3','What we have poured upon Him now<br/>Is not wasted,<br/>But a fragrant testimony<br/>Of His own sweetness.<br/>',NULL,14237,14237);
INSERT INTO stanza VALUES('BF92','4','What we have poured upon Him now<br/>Is not wasted,<br/>But a fragrant testimony<br/>Of His own sweetness.<br/>',NULL,14238,14238);
INSERT INTO stanza VALUES('BF93','1','Thy mighty love, O God, constraineth me,<br/>As some strong tide it presseth on its way,<br/>Seeking a channel in my self-bound soul,<br/>Yearning to sweep all barriers away.<br/>',NULL,14239,14239);
INSERT INTO stanza VALUES('BF93','2','Shall I not yield to that constraining power?<br/>Shall I not say, O tide of love, flow in?<br/>My God, Thy gentleness hath conquered me,<br/>Life cannot be as it hath hither been.<br/>',NULL,14240,14240);
INSERT INTO stanza VALUES('BF93','3','Break through my nature, mighty, heavenly love,<br/>Clear every avenue of thought and brain,<br/>Flood my affections, purify my will,<br/>Let nothing but Thine own pure life remain.<br/>',NULL,14241,14241);
INSERT INTO stanza VALUES('BF93','4','Thus wholly mastered and possessed by God,<br/>Forth from my life, spontaneous and free,<br/>Shall flow a stream of tenderness and grace,<br/>Loving, because God loved, eternally.<br/>',NULL,14242,14242);
INSERT INTO stanza VALUES('BF94','1','If I gained the world, but lost the Savior,<br/>Were my life worth living for a day?<br/>Could my yearning heart find rest and comfort<br/>In the things that soon must pass away?<br/>If I gained the world, but lost the Savior,<br/>Would my gain be worth the lifelong strife?<br/>Are all earthly pleasures worth comparing<br/>For a moment with a Christ-filled life?<br/>',NULL,14243,14243);
INSERT INTO stanza VALUES('BF94','2','Had I wealth and love in fullest measure,<br/>And a name revered both far and near,<br/>Yet no hope beyond, no harbor waiting,<br/>Where my storm-tossed vessel I could steer;<br/>If I gained the world, but lost the Savior,<br/>Who endured the cross and died for me,<br/>Could then all the world afford a refuge,<br/>Whither, in my anguish, I might flee?<br/>',NULL,14244,14244);
INSERT INTO stanza VALUES('BF94','3','O what emptiness! — without the Savior<br/>''Mid the sins and sorrows here below!<br/>And eternity, how dark without Him!<br/>Only night and tears and endless woe!<br/>What, though I might live without the Savior,<br/>When I come to die, how would it be?<br/>O to face the valley''s gloom without Him!<br/>And without Him all eternity!<br/>',NULL,14245,14245);
INSERT INTO stanza VALUES('BF94','4','O the joy of having all in Jesus!<br/>What a balm the broken heart to heal!<br/>Ne''er a sin so great, but He''ll forgive it,<br/>Nor a sorrow that He does not feel!<br/>If I have but Jesus, only Jesus,<br/>Nothing else in all the world beside —<br/>O then everything is mine in Jesus;<br/>For my needs and more He will provide.<br/>',NULL,14246,14246);
INSERT INTO stanza VALUES('BF95','1','My wandering days grew increasingly empty<br/>As I searched for the way,<br/>Just to fill this gap inside me —<br/>Found my seeking vain.<br/>',NULL,14247,14247);
INSERT INTO stanza VALUES('BF95','chorus','Though all this dark earth would convince me<br/>life''s worthwhile,<br/>Inside all my mirth<br/>Was a cry for something real.<br/>Don''t you lie to me, world!<br/>',NULL,14248,14248);
INSERT INTO stanza VALUES('BF95','chorus','For my heart tells me different<br/>When I hear of contentment<br/>Deep within a lack knew better<br/>Why not be honest, world.<br/>',NULL,14249,14249);
INSERT INTO stanza VALUES('BF95','2','A flood of strong doubt as I heard the old story<br/>Of a man they called Lord;<br/>Yet my heart ne''er ceased to wonder,<br/>Is He really Lord?<br/>',NULL,14250,14250);
INSERT INTO stanza VALUES('BF95','chorus','A search in His Word found my hardened<br/>heart softened,<br/>And earth''s vanities faded.<br/>In the brightness of His presence<br/>Jesus came into me.<br/>',NULL,14251,14251);
INSERT INTO stanza VALUES('BF95','chorus','Now we''re always together<br/>Growing into God''s fullness.<br/>O Lord Jesus, how I love You!<br/>You brought life into me.<br/>',NULL,14252,14252);
INSERT INTO stanza VALUES('BF96','1','There''s a gospel of today<br/>That says believe and you''ll be saved — and then<br/>You can go to heaven and see the pearly gates<br/>And walk the golden streets<br/>Words like these — fail to treat<br/>All the vanity — that is hidden in me.<br/>',NULL,14253,14253);
INSERT INTO stanza VALUES('BF96','2','But the gospel is to me<br/>The Triune God within humanity<br/>As the Spirit reaching me to be in me<br/>The One reality<br/>Love untold — Gospel Thee<br/>Never getting old — story told eternally.<br/>',NULL,14254,14254);
INSERT INTO stanza VALUES('BF96','3','Left the ninety-nine behind —<br/>You searched until the lost sheep You did find<br/>Laid me on Your shoulders there, You bore me in<br/>Your tender loving care<br/>Rejoicing — You found me<br/>Though a small lost sheep — You gave all to come find me.<br/>',NULL,14255,14255);
INSERT INTO stanza VALUES('BF96','4','Sweeping in my deepest parts,<br/>You lit a lamp and searched my inward heart<br/>Sanctifying deep within You shined in me,<br/>Exposed me of my sin<br/>Repenting — now I see<br/>Lord, You''re sprinkling me — with the blood You shed for me.<br/>',NULL,14256,14256);
INSERT INTO stanza VALUES('BF96','5','Eagerly awaiting me<br/>That I the slightest turn to Thee would make<br/>Though my life had been a wreck, You ran to me<br/>And fell upon my neck<br/>Kissing me, affectionately,<br/>Killing the calf for me — "Let us eat and be merry."<br/>',NULL,14257,14257);
INSERT INTO stanza VALUES('BF97','1','What things were gains to me,<br/>These I now count as loss.<br/>Jesus has set me free<br/>From what I was!<br/>All of the things I had;<br/>Everything, good or bad,<br/>I count as refuse<br/>That I may gain Christ!<br/>',NULL,14258,14258);
INSERT INTO stanza VALUES('BF97','chorus','I won''t give up!<br/>I will keep running until I have attained<br/>The goal of my calling!<br/>I will press on!<br/>I will pursue until I lay hold of Him<br/>Who laid hold of me!<br/>',NULL,14259,14259);
INSERT INTO stanza VALUES('BF97','2','Forget the things behind!<br/>Stretch for the things before!<br/>Press onward with this mind:<br/>Always want more!<br/>Seeking in Him to grow,<br/>Increasingly to know<br/>Him that I daily might<br/>Be found in Christ.<br/>',NULL,14260,14260);
INSERT INTO stanza VALUES('BF98','1','Rejoice! Rejoice! Our Bridegroom''s coming,<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,14261,14261);
INSERT INTO stanza VALUES('BF98','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come;<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,14262,14262);
INSERT INTO stanza VALUES('BF98','2','Oh, let us now redeem each moment,<br/>More the precious oil to buy,<br/>And have our vessels filled with ointment<br/>Ere we hear the midnight cry.<br/>',NULL,14263,14263);
INSERT INTO stanza VALUES('BF98','3','Oh, what a joy it is preparing<br/>For our wedding with the Lord,<br/>E''en in the tribulations sharing<br/>For the bliss of such reward!<br/>',NULL,14264,14264);
INSERT INTO stanza VALUES('BF98','4','Oh, with what rapture and rejoicing<br/>Shall the wedding day begin;<br/>And then a thousand years of dining<br/>At the marriage feast with Him!<br/>',NULL,14265,14265);
INSERT INTO stanza VALUES('BF99','1','Just as I am, without one plea,<br/>But that Thy blood was shed for me,<br/>And that Thou bid''st me come to Thee,<br/>O Lamb of God, I come! I come!<br/>',NULL,14266,14266);
INSERT INTO stanza VALUES('BF99','2','Just as I am, and waiting not<br/>To rid my soul of one dark blot;<br/>To Thee whose blood can cleanse each spot,<br/>O Lamb of God, I come, I come!<br/>',NULL,14267,14267);
INSERT INTO stanza VALUES('BF99','3','Just as I am, though tossed about<br/>With many a conflict, many a doubt;<br/>Fightings within, and fears without,<br/>O Lamb of God, I come, I come!<br/>',NULL,14268,14268);
INSERT INTO stanza VALUES('BF99','4','Just as I am, poor, wretched, blind;<br/>Sight, riches, healing of the mind;<br/>Yes, all I need, in Thee to find,<br/>O Lamb of God, I come, I come!<br/>',NULL,14269,14269);
INSERT INTO stanza VALUES('BF99','5','Just as I am, Thou wilt receive,<br/>Wilt welcome, pardon, cleanse, relieve;<br/>Because Thy promise I believe,<br/>O Lamb of God, I come, I come!<br/>',NULL,14270,14270);
INSERT INTO stanza VALUES('BF99','6','Just as I am, Thy love unknown<br/>Has broken every barrier down;<br/>Now, to be Thine, yea, Thine alone,<br/>O Lamb of God, I come, I come!<br/>',NULL,14271,14271);
INSERT INTO stanza VALUES('BF100','1','Give yourself to love the Lord.<br/>No other way is so prevailing<br/>And no other way, no other way is so safe.<br/>',NULL,14272,14272);
INSERT INTO stanza VALUES('BF100','2','Give yourself to love the Lord.<br/>No other way is so rich,<br/>And so full, oh so full, of enjoyment.<br/>',NULL,14273,14273);
INSERT INTO stanza VALUES('BF100','chorus','Each morning we must rise up and say to Him,<br/>"Lord Jesus, I love You."<br/>',NULL,14274,14274);
INSERT INTO stanza VALUES('BF100','3','Give yourself to love the Lord.<br/>Do not care for anything else;<br/>Just love Him! Do not care!<br/>Give yourself to love the Lord!<br/>',NULL,14275,14275);
INSERT INTO stanza VALUES('BF100','chorus','We are not our own, Lord; all we have we give to You.<br/>Lord Jesus! Lord Jesus!<br/>Lord Jesus, we love You!<br/>',NULL,14276,14276);
INSERT INTO stanza VALUES('BF101','1','My stubborn will at last hath yielded;<br/>I would be Thine, and Thine alone,<br/>And this the prayer my lips are bringing,<br/>"Lord, let in me Thy will be done."<br/>',NULL,14277,14277);
INSERT INTO stanza VALUES('BF101','chorus','Sweet will of God, still fold me closer,<br/>Till I am wholly lost in Thee;<br/>Sweet will of God, still fold me closer,<br/>Till I am wholly lost in Thee.<br/>',NULL,14278,14278);
INSERT INTO stanza VALUES('BF101','2','I''m tired of sin, footsore and weary,<br/>The darksome path hath dreary grown,<br/>But now a light has ris''n to cheer me;<br/>I find in Thee my Star, my Sun.<br/>',NULL,14279,14279);
INSERT INTO stanza VALUES('BF101','3','Thy precious will, O conqu''ring Savior,<br/>Doth now embrace and compass me;<br/>All discords hushed, my peace a river,<br/>My soul a prisoned bird set free.<br/>',NULL,14280,14280);
INSERT INTO stanza VALUES('BF101','4','Shut in with Thee, O Lord, forever,<br/>My wayward feet no more to roam;<br/>What pow''r from Thee my soul can sever?<br/>The center of God''s will my home.<br/>',NULL,14281,14281);
INSERT INTO stanza VALUES('BF102','1','Rise up, my love, my beautiful one,<br/>And come away, for behold,<br/>The winter is past<br/>The rain is over and gone.<br/>',NULL,14282,14282);
INSERT INTO stanza VALUES('BF102','2','Flow''rs appear on the earth,<br/>The time of singing has come,<br/>And the voice of the turtle dove,<br/>Is heard in our land.<br/>',NULL,14283,14283);
INSERT INTO stanza VALUES('BF102','chorus','My beloved is mine,<br/>And I am His,<br/>He who feeds the flocks among the lilies,<br/>''Til the day breaks,<br/>And the shadows flee away,<br/>Come my beloved,<br/>Come my beloved!<br/>',NULL,14284,14284);
INSERT INTO stanza VALUES('BF102','3','Rise up, my love, my beautiful one<br/>And come away, for behold,<br/>The winter is past,<br/>The rain is over and gone.<br/>',NULL,14285,14285);
INSERT INTO stanza VALUES('BF103','1','The Triune God: a mystery —<br/>God is one and He''s three.<br/>Oh, Triune God, You''re wonderful!<br/>You''re wonder-wonderful!<br/>(repeat)<br/>',NULL,14286,14286);
INSERT INTO stanza VALUES('BF103','chorus','(Brothers)                   (Sisters)<br/>A child is born to us,	The mighty God is He,<br/>A son is giv''n to us,	Eternal Father, He,<br/>The child, the mighty God,	His name is Wonderful,<br/>The Son and Father one.	A wonderful Person.<br/>',NULL,14287,14287);
INSERT INTO stanza VALUES('BF103','2','The Lord is now the Spirit,<br/>A wondrous mystery!<br/>Christ, the life-giving Spirit,<br/>Has entered into me!<br/>The Lord is now the Spirit,<br/>Oh this is glorious!<br/>Christ, the life-giving Spirit,<br/>Has entered into us!<br/>',NULL,14288,14288);
INSERT INTO stanza VALUES('BF103','chorus','The last Adam became	The life-giving Spirit!<br/>The Lord is the Spirit,	The all-inclusive Christ<br/>The last Adam became	The life-giving Spirit!<br/>Christ is the Lord Spirit.	He''s now indwelling us!<br/>',NULL,14289,14289);
INSERT INTO stanza VALUES('BF103','3','Our Father God, the source;<br/>God, the Son, has reached me.<br/>God as the Spirit entered me!<br/>''Tis the greatest mystery.<br/>Our Father God, the source;<br/>God, the Son, is the course.<br/>God as the Spirit''s flowing free.<br/>He flowed God into me!<br/>',NULL,14290,14290);
INSERT INTO stanza VALUES('BF103','chorus','The Triune God in me:	The greatest mystery!<br/>Oh this is glorious! 	The Triune God in us!<br/>The Triune God in me:	The greatest mystery!<br/>Oh this is marvelous!	The Triune God in us!<br/>',NULL,14291,14291);
INSERT INTO stanza VALUES('BF104','1','We love You, Lord, we love You.<br/>You are altogether lovely.<br/>We''ve seen Your beauty<br/>Here in the church, in all Your saints.<br/>',NULL,14292,14292);
INSERT INTO stanza VALUES('BF105','1','Lord Jesus, You''re lovely.<br/>You''re more to be desired,<br/>Than any earthly pleasure.<br/>You''re fine, beyond compare.<br/>Lord Jesus, Your beauty<br/>Does far exceed all others.<br/>You''re comely and You''re tender.<br/>You''re radiant and You''re fair.<br/>',NULL,14293,14293);
INSERT INTO stanza VALUES('BF105','2','When I behold You Jesus,<br/>You draw my heart completely.<br/>I cannot turn away Lord,<br/>I rest in Your embrace;<br/>And time is gone there''s only<br/>Your holy, matchless presence<br/>Abiding in You, gazing<br/>Upon Your glorious face.<br/>',NULL,14294,14294);
INSERT INTO stanza VALUES('BF105','3','I give my life to You Lord,<br/>For You alone are worthy.<br/>There''s nothing and there''s no one<br/>That I desire but You.<br/>May all my days be Yours, Lord,<br/>My heart be given to love You,<br/>To treasure and to serve You<br/>By Your sufficient grace.<br/>',NULL,14295,14295);
INSERT INTO stanza VALUES('BF106','1','Lord, I was blind; I could not see<br/>In Thy marred visage any grace,<br/>But now the beauty of Thy face<br/>In radiant vision dawns on me.<br/>',NULL,14296,14296);
INSERT INTO stanza VALUES('BF106','2','Lord, I was deaf; I could not hear<br/>The thrilling music of Thy voice;<br/>But now I hear Thee and rejoice,<br/>And all Thine uttered words are dear!<br/>',NULL,14297,14297);
INSERT INTO stanza VALUES('BF106','3','Lord, I was dumb; I could not speak<br/>The grace and glory of Thy name;<br/>But now, as touched with living flame,<br/>My lips Thine eager praises wake.<br/>',NULL,14298,14298);
INSERT INTO stanza VALUES('BF106','4','Lord, I was dead; I could not stir<br/>My lifeless soul to come to Thee;<br/>But now, since Thou hast quickened me,<br/>I rise from sin''s dark sepulcher.<br/>',NULL,14299,14299);
INSERT INTO stanza VALUES('BF106','5','For Thou hast made the blind to see,<br/>The deaf to hear, the dumb to speak,<br/>The dead to live; and, lo, I break<br/>The chains of my captivity.<br/>',NULL,14300,14300);
INSERT INTO stanza VALUES('BF107','1','Let''s take the land! The land that God has given us;<br/>In all our living, Christ can be so much:<br/>To take this land, we have th'' equipment that we need —<br/>The blood, the Word, the Spirit, and the church.<br/>',NULL,14301,14301);
INSERT INTO stanza VALUES('BF107','chorus','(Sisters sing)<br/>Let''s take the land! O Christian brothers,<br/>The land that God has given us.<br/>Be strong and take it, for we can make it<br/>And gain this land so glorious!<br/>',NULL,14302,14302);
INSERT INTO stanza VALUES('BF107','chorus','(Brothers sing)<br/>Let''s take the land! O Christian sisters,<br/>And to these things give earnest heed.<br/>The Lord implores us; He''s gone before us<br/>And given everything we need!<br/>',NULL,14303,14303);
INSERT INTO stanza VALUES('BF107','2','We have the blood! Christ is our spotless offering,<br/>Who gave Himself, our God to satisfy;<br/>And so we come with boldness to the throne of grace,<br/>And all day long, the precious blood apply.<br/>',NULL,14304,14304);
INSERT INTO stanza VALUES('BF107','3','We have the Word! The written Word''s our daily food;<br/>We mix this Word with faith and say "Amen!"<br/>Then thro'' the day, the spoken Word will speak to us<br/>And regulate our living from within.<br/>',NULL,14305,14305);
INSERT INTO stanza VALUES('BF107','4','The Spirit''s ours! The Spirit of reality,<br/>He''s independent of the way we feel;<br/>He dwells in us, and teaches us to dwell in Him,<br/>And guides us into everything that''s real.<br/>',NULL,14306,14306);
INSERT INTO stanza VALUES('BF107','5','We have the church! All saints are needed to possess<br/>The fullness of this vast reality;<br/>Together we will gain this all-inclusive Christ,<br/>And He to us our everything will be.<br/>',NULL,14307,14307);
INSERT INTO stanza VALUES('BF108','1','Lord, how I thank You that<br/>You died on the cross for me.<br/>Your mercy, my Savior, reached me.<br/>And Lord, You paid the highest price;<br/>My life bought with Your shed blood.<br/>My life now belongs, Lord, to You.<br/>',NULL,14308,14308);
INSERT INTO stanza VALUES('BF108','chorus','And Lord, how can I turn away from Your love?<br/>The eternal life which You bought for me?<br/>I give You my heart;<br/>Lord, spread to ev''ry part<br/>Till my whole heart belongs to You.<br/>',NULL,14309,14309);
INSERT INTO stanza VALUES('BF108','2','Lord, gain my heart so that<br/>It is single and pure for You.<br/>No other love, Lord, would I know.<br/>Lord, I am so in love with You,<br/>For You are so lovely.<br/>My everything, my all in all.<br/>',NULL,14310,14310);
INSERT INTO stanza VALUES('BF108','chorus','And Lord, I really want to know<br/>This Person inside of me.<br/>Lord, keep my heart open to You.<br/>Keep flowing Your life,<br/>Into me that I would grow,<br/>And be saturated with You.<br/>',NULL,14311,14311);
INSERT INTO stanza VALUES('BF109','1','My will is weak, my strength is frail,<br/>And all my hope is nearly gone;<br/>I can but trust Thy working true<br/>To gently hold and lead me on,<br/>To gently hold and lead me on.<br/>',NULL,14312,14312);
INSERT INTO stanza VALUES('BF109','2','I’ve tried my best, but still have failed,<br/>E’en as before I’ve failed and erred;<br/>Thy patience is my only trust<br/>To hold and keep me to Thy word.<br/>To hold and keep me to Thy word.<br/>',NULL,14313,14313);
INSERT INTO stanza VALUES('BF109','3','Whene’er my heart is lifted up,<br/>How very near I am to fall;<br/>I dare not do, I dare not think,<br/>I need Thyself in great or small,<br/>I need Thyself in great or small.<br/>',NULL,14314,14314);
INSERT INTO stanza VALUES('BF109','4','Thou art my Savior, strength and stay,<br/>O Lord, I come to seek Thy face;<br/>Though I’m the weakest of the weak,<br/>My strength is nothing but Thy grace,<br/>My strength is nothing but Thy grace.<br/>',NULL,14315,14315);
INSERT INTO stanza VALUES('BF110','1','I need You, Jesus,<br/>More and more each day.<br/>I can''t live without You,<br/>Most wonderful One!<br/>I need You, Lord,<br/>More and more every day.<br/>I can''t live without You,<br/>Oh, most wonderful One!<br/>',NULL,14316,14316);
INSERT INTO stanza VALUES('BF110','2','My lovely Bridegroom,<br/>Oh, most pleasant One,<br/>Take me in Your chambers,<br/>Sustain me with love!<br/>I need You, Lord,<br/>More and more every day.<br/>I can''t live without You,<br/>Oh, most lovely Bridegroom!<br/>',NULL,14317,14317);
INSERT INTO stanza VALUES('BF110','3','Jesus, just kiss me,<br/>Kisses of Your mouth.<br/>Grace upon Thy lips is<br/>So sweet to my taste.<br/>I need You, Lord,<br/>More and more every day.<br/>I can''t live without You;<br/>I need Your sweet taste.<br/>',NULL,14318,14318);
INSERT INTO stanza VALUES('BF110','4','I''m sick with love.<br/>Thy banner over me is love.<br/>You have ravished my heart,<br/>None other for me.<br/>I need You, Lord,<br/>More and more every day.<br/>I can''t live without You.<br/>I''ve been ravished by Thee.<br/>',NULL,14319,14319);
INSERT INTO stanza VALUES('BF110','5','I love my Master.<br/>I''ll not go out free.<br/>Take my ear to the door post<br/>And bore it for Thee.<br/>I need You, Lord,<br/>More and more every day.<br/>I can''t live without You,<br/>Oh, most wonderful One!<br/>',NULL,14320,14320);
INSERT INTO stanza VALUES('BF110','6','Make haste, Beloved!<br/>Come quickly soon!<br/>Jesus, our desire.<br/>Thy Bride calls for Thee.<br/>Come quickly, Lord,<br/>We can''t wait anymore.<br/>Please make haste, dear Beloved!<br/>Your Bride calls for Thee.<br/>Come quickly, Lord, Amen.<br/>',NULL,14321,14321);
INSERT INTO stanza VALUES('BF111','1','Therefore with joy shall ye draw water<br/>Out of the wells of salvation.<br/>And in that day shall ye say,<br/>Praise the Lord.<br/>(Repeat the above four lines)<br/>',NULL,14322,14322);
INSERT INTO stanza VALUES('BF111','2','Call upon His name, declare His doings<br/>among the people,<br/>Make mention that His name is exalted.<br/>Cry out and shout, thou inhabitant of Zion:<br/>For great is the Holy One of Israel in the<br/>midst of thee.<br/>',NULL,14323,14323);
INSERT INTO stanza VALUES('BF112','1','Lord, when I''m bad I get so sad;<br/>It seems the Lamb I never knew,<br/>But blood was shed, depression fled<br/>So now I hide in You.<br/>It''s in the Son I have begun,<br/>It''s in the Son I''ll onward go<br/>In Him I''ll walk, in Him I''ll talk,<br/>In Him I''ll surely grow.<br/>',NULL,14324,14324);
INSERT INTO stanza VALUES('BF112','chorus','Oh Jesus now grow in me;<br/>I want for You to be<br/>Pleased to be in me what You want to be<br/>And when it gets too hard feel free<br/>To grow some more in me.<br/>',NULL,14325,14325);
INSERT INTO stanza VALUES('BF112','2','Lord, I''m not strange, I just can''t change<br/>It''s not from lack of effort though<br/>The more I try, the more I find<br/>I need for You to grow.<br/>Where I have failed, Lord You''ve prevailed<br/>The secret of success I know:<br/>That all I need is life indeed,<br/>I pray for You to grow.<br/>',NULL,14326,14326);
INSERT INTO stanza VALUES('BF112','3','With flags unfurled here comes the world<br/>It''s beauty does my heart embrace<br/>But it grows pale whene''er that veil<br/>Removed displays Your face.<br/>As my heart turns, with love it burns<br/>Your face is all I want to see<br/>Your image Lord which I adore<br/>My image soon will be.<br/>',NULL,14327,14327);
INSERT INTO stanza VALUES('BF113','1','From the morning to the evening,<br/>His faithfulness I see;<br/>His mercy reaching sinners,<br/>Reaching even me;<br/>And I know, now I know.<br/>Brighter than the brightest sunlight,<br/>All doubts and fears must cease;<br/>Sweeter than the sweetest delight,<br/>His living Word in me;<br/>And I know, now I know.<br/>',NULL,14328,14328);
INSERT INTO stanza VALUES('BF113','chorus','That God is there for me tomorrow,<br/>As He is for me today;<br/>That He''ll take my cares and sorrow,<br/>And He''ll wipe them all away;<br/>There''s no crisis that He can''t bear,<br/>There''s no storm He can''t abate;<br/>He''s my God, He''s my God.<br/>',NULL,14329,14329);
INSERT INTO stanza VALUES('BF113','2','Day by day His grace grows dearer;<br/>His love has conquered me,<br/>Never leaving, never ceasing,<br/>His Spirit constantly<br/>Flooding me, rich and free;<br/>Higher than the highest heaven,<br/>He lifts me up to see<br/>New Jerusalem descending,<br/>His Bride, His love to be<br/>Eternally, it shall be.<br/>',NULL,14330,14330);
INSERT INTO stanza VALUES('BF114','1','Sometimes it seems like<br/>I have no room in my heart for You.<br/>But then You touched me<br/>And soften me to turn to You.<br/>',NULL,14331,14331);
INSERT INTO stanza VALUES('BF114','chorus','Recover my heart,<br/>Rekindle my love for You.<br/>Fill me with love<br/>Eternally, ever new.<br/>Make me wholly Thine.<br/>',NULL,14332,14332);
INSERT INTO stanza VALUES('BF114','2','Lord, I long to<br/>Empty myself of all but You;<br/>Give You my best love,<br/>Preeminence in all I do.<br/>',NULL,14333,14333);
INSERT INTO stanza VALUES('BF114','3','I want to love You<br/>With all my heart and all my soul.<br/>I want no other,<br/>I give myself to be Yours alone.<br/>',NULL,14334,14334);
INSERT INTO stanza VALUES('BF115','1','Lord, keep my heart always true to You,<br/>Never backsliding, always viewing You,<br/>A heart that is pure that sees only You,<br/>A heart that loves You and treasures only You.<br/>',NULL,14335,14335);
INSERT INTO stanza VALUES('BF115','chorus','Your love constrains me to give my all to You.<br/>Lord, I can''t help it; my heart is drawn to You.<br/>Oh what a privilege! I give myself to You!<br/>I love You, Lord, dearest Lord.<br/>I love You! I just love You!<br/>',NULL,14336,14336);
INSERT INTO stanza VALUES('BF115','2','Lord, keep my love burning brightly for You,<br/>A love never dwindling always hot for You,<br/>A love, shining brighter all the way for You,<br/>A love, so fresh like the day I first touched You.<br/>',NULL,14337,14337);
INSERT INTO stanza VALUES('BF115','3','Lord, take my life, I present it to You!<br/>If I had a thousand, I''d pour all on You!<br/>Nothing withholding, my all is for You.<br/>My life and my future, dear Lord, is all for You.<br/>',NULL,14338,14338);
INSERT INTO stanza VALUES('BF116','1','I do not know where they have laid Him.<br/>The stone is taken away from the tomb.<br/>Oh! They have taken Him away!<br/>Oh! Where is He?<br/>',NULL,14339,14339);
INSERT INTO stanza VALUES('BF116','2','Disciples came and saw the empty tomb<br/>But went away so soon to their own homes.<br/>They''re satisfied with just the facts.<br/>But where''s my Lord?<br/>',NULL,14340,14340);
INSERT INTO stanza VALUES('BF116','chorus','Where is He, my Jesus?<br/>Where is He, my Beloved?<br/>Where is He Whom my soul doth love?<br/>Jesus, my Love, I just want You.<br/>',NULL,14341,14341);
INSERT INTO stanza VALUES('BF116','3','My heart is broken from my deepest need.<br/>Don''t ask me, angels, why I''m weeping.<br/>Nothing but Jesus fills my inner being.<br/>Oh! Where''s my Love?<br/>',NULL,14342,14342);
INSERT INTO stanza VALUES('BF116','4','Someone is standing right behind me.<br/>It''s just the gardener I can barely see.<br/>Sir, if you carried Him away...<br/>Oh! Where is He?<br/>',NULL,14343,14343);
INSERT INTO stanza VALUES('BF116','chorus','Where is He my Jesus?<br/>Where is He my Beloved?<br/>Tell me where you have laid Him<br/>And I''ll carry Him away, I''ll carry Him away.<br/>',NULL,14344,14344);
INSERT INTO stanza VALUES('BF116','5','And then I heard a voice say, "Mary."<br/>That sweetest voice that penetrated me.<br/>It is the voice of my Beloved,<br/>Jesus, my Love.<br/>',NULL,14345,14345);
INSERT INTO stanza VALUES('BF116','chorus','I have found my Jesus!<br/>I have found my Beloved!<br/>I have found whom my soul doth love,<br/>Jesus, my Love, I just love You.<br/>',NULL,14346,14346);
INSERT INTO stanza VALUES('BF116','6','But Jesus told me not to touch Him yet.<br/>He must ascend first to the Father<br/>And to My Father and your Father<br/>To My God and your God.<br/>',NULL,14347,14347);
INSERT INTO stanza VALUES('BF116','chorus','Go and tell My brothers,<br/>I ascend to the Father<br/>To My Father and your Father,<br/>And My God and your God, go tell My brothers.<br/>',NULL,14348,14348);
INSERT INTO stanza VALUES('BF117','1','Abba, Father, hear our cry,<br/>Mingled spirit deep within.<br/>',NULL,14349,14349);
INSERT INTO stanza VALUES('BF117','chorus','Abba, Father,<br/>Abba, Father.<br/>',NULL,14350,14350);
INSERT INTO stanza VALUES('BF117','2','Thank You, Father, for sending Him;<br/>The Spirit of Your Son Who cries within.<br/>',NULL,14351,14351);
INSERT INTO stanza VALUES('BF117','3','Oh! How sweet is Abba''s Name<br/>From our spirit through our heart.<br/>',NULL,14352,14352);
INSERT INTO stanza VALUES('BF117','4','Every moment this mingled cry;<br/>To Your Beloved we''re joined thereby.<br/>',NULL,14353,14353);
INSERT INTO stanza VALUES('BF117','5','Day by day, this cry so new;<br/>In Your Son we come back to You.<br/>',NULL,14354,14354);
INSERT INTO stanza VALUES('BF117','6','In Your bosom here we''ll stay,<br/>In Your Son and never stray.<br/>',NULL,14355,14355);
INSERT INTO stanza VALUES('BF118','1','God is love, Who sent His beloved Son.<br/>Man is fallen with corruption,<br/>But You sent Your dear Son.<br/>God commends His kindness and love toward us,<br/>In that while we were yet sinners<br/>Christ died for us.<br/>',NULL,14356,14356);
INSERT INTO stanza VALUES('BF118','chorus','God You did not spare Him,<br/>Your beloved Son.<br/>Father, how we praise You<br/>For this precious One!<br/>',NULL,14357,14357);
INSERT INTO stanza VALUES('BF118','2','Who can know the love from our Father''s being?<br/>Ears have never heard, eyes have never seen,<br/>But Lord, I''ve been redeemed.<br/>God is love. O God, a man You became;<br/>A cursed man to be, God, You died for me.<br/>Lord, You hung from a tree.<br/>',NULL,14358,14358);
INSERT INTO stanza VALUES('BF118','chorus','Father, You have sent Him,<br/>Your beloved Son.<br/>He shed His blood on Calvary.<br/>Your love reached me.<br/>',NULL,14359,14359);
INSERT INTO stanza VALUES('BF118','3','God so loved the world that He gave us His Son.<br/>Just believe in Him. Be not perishing,<br/>But have eternal life.<br/>Just believe in Him. Be not perishing,<br/>But have eternal life.<br/>',NULL,14360,14360);
INSERT INTO stanza VALUES('BF119','1','Lord, how long, dear Bridegroom,<br/>''Til You come, Lord, how soon?<br/>Don''t delay for that coming day, coming day.<br/>Grant me, Lord, to be filled<br/>With You, Lord, every day.<br/>Dearest Lord, take me all the way.<br/>',NULL,14361,14361);
INSERT INTO stanza VALUES('BF119','chorus','Come, Lord Jesus,<br/>Please come, dear Bridegroom;<br/>Precious One, come soon, come soon.<br/>Lord, consume me!<br/>Oh Lord, don''t let me stray,<br/>Faithful to You all the way.<br/>',NULL,14362,14362);
INSERT INTO stanza VALUES('BF119','2','Lord, make home in all my heart<br/>In my secret, deepest parts,<br/>Hidden, Lord, and reserved for You, for You.<br/>You would be preeminent<br/>In all things and all events,<br/>Possessed by Thee to that extent.<br/>',NULL,14363,14363);
INSERT INTO stanza VALUES('BF119','3','In my prayer and deepest plea<br/>In my spirit always be<br/>Saturated and soaked with Thee, with Thee.<br/>This would be my life daily.<br/>Every hour expecting Thee,<br/>This I pray, Lord, desperately!<br/>',NULL,14364,14364);
INSERT INTO stanza VALUES('BF119','4','The universe, in it we see,<br/>In the sweetest touch of Thee,<br/>You''re my choice and my destiny, destiny.<br/>Lord, whate''er the price may be,<br/>Lord, Amen, let it be!<br/>Oh, my Love, please come back quickly!<br/>',NULL,14365,14365);
INSERT INTO stanza VALUES('BF119','5','In Your love I am constrained.<br/>What''s within, I can''t contain.<br/>Lord, I can''t any more restrain, restrain.<br/>In Your love, I''ll pour on Thee.<br/>And the church, Your Bride to be,<br/>This my choice voluntarily.<br/>',NULL,14366,14366);
INSERT INTO stanza VALUES('BF120','1','What about my sinful past?<br/>And my conscience has no rest.<br/>Deep within I feel the pain.<br/>I''m condemned from all my guilty stains.<br/>',NULL,14367,14367);
INSERT INTO stanza VALUES('BF120','2','O my life of misery,<br/>In this world of vanity,<br/>As I searched for happiness,<br/>My reward I received just emptiness.<br/>',NULL,14368,14368);
INSERT INTO stanza VALUES('BF120','3','God was far away from me,<br/>Great and highest One is He.<br/>Yet You took on humanity.<br/>You came for me,<br/>Hung on a tree,<br/>Bled there to die for me.<br/>',NULL,14369,14369);
INSERT INTO stanza VALUES('BF120','4','That''s why I love Him.<br/>That''s why I treasure Him.<br/>That''s why I give my life and all to Him.<br/>That''s why I loveHim.<br/>That''s why I treasure Him.<br/>That''s why I give my life and all to Him.<br/>',NULL,14370,14370);
INSERT INTO stanza VALUES('BF121','1','I love You, Lord Jesus!<br/>I love You, Lord, precious One!<br/>No other one compares to You!<br/>I love You, Lord Jesus!<br/>I love You, Lord, precious One!<br/>No other one compares to You!<br/>Jesus, Lord Jesus,<br/>Dear Lord, most lovely One,<br/>Nothing compares to You!<br/>',NULL,14371,14371);
INSERT INTO stanza VALUES('BF122','1','Zion is God''s habitation.<br/>Sing praises in Zion,<br/>The city of our King.<br/>Zion, the place of His choosing<br/>Where saints are rejoicing.<br/>Here God is their salvation.<br/>Beautiful Zion,<br/>In elevation,<br/>The joy of our King,<br/>His satisfaction,<br/>The joy of the whole earth.<br/>',NULL,14372,14372);
INSERT INTO stanza VALUES('BF122','2','Zion: how good and how pleasant,<br/>The greatest enjoyment!<br/>It''s like the precious ointment.<br/>Zion, how good and how pleasant,<br/>In oneness we''re dwelling.<br/>The dew, oh how refreshing!<br/>Beautiful Zion, in elevation.<br/>How good and how pleasant,<br/>The best enjoyment!<br/>Our oneness is just Him.<br/>',NULL,14373,14373);
INSERT INTO stanza VALUES('BF122','3','Zion: our oneness a Person,<br/>As ointment, He''s moving,<br/>As dew He is descending,<br/>Zion: our God is our dwelling,<br/>As ointment, He''s strengthening,<br/>As dew, He''s so supplying.<br/>Beautiful Zion, in elevation.<br/>How good and how pleasant,<br/>Man''s satisfaction,<br/>Our dwelling is this One.<br/>',NULL,14374,14374);
INSERT INTO stanza VALUES('BF122','4','Zion: in God we''re abiding,<br/>Our oneness and living,<br/>The processed God, our all.<br/>Zion, the ultimate blessing,<br/>Of God with man mingling,<br/>The Triune God dispensing.<br/>Beautiful churches, the golden lampstands.<br/>God mingling with man;<br/>His satisfaction,<br/>The ultimate consummation!<br/>',NULL,14375,14375);
INSERT INTO stanza VALUES('BF123','1','Lord, I love You more and more each day.<br/>Lord, I love You more this very day.<br/>I can''t live without You anymore.<br/>I can''t make it like I did before.<br/>Oh, those years when I was void of You.<br/>Lord, You rescued me when I was through.<br/>When I reminisce those other years,<br/>Emptiness, heartaches, and many tears.<br/>',NULL,14376,14376);
INSERT INTO stanza VALUES('BF123','chorus','Lord, I do love You more everyday.<br/>Lord, I do love You much more this very day.<br/>',NULL,14377,14377);
INSERT INTO stanza VALUES('BF123','2','Oh, that thirst that gnawed me deep within:<br/>Drove me looking for satisfaction.<br/>Oh, the many things that I have tried:<br/>Left me thirsting and dissatisfied.<br/>In this endless search for something new,<br/>All the time this cry was just for You.<br/>I was blind in trying many things<br/>''Til I drank You as my living Spring.<br/>',NULL,14378,14378);
INSERT INTO stanza VALUES('BF123','3','Lord, You came and filled my inmost being.<br/>You''re the sweetest satisfaction.<br/>You''re the Spirit as my everything,<br/>Spirit in my spirit bubbling.<br/>Thank You, Lord, for coming into me.<br/>Now You''re spreading in me constantly.<br/>Lord, You''re making home in all my heart,<br/>As my treasure filling every part.<br/>',NULL,14379,14379);
INSERT INTO stanza VALUES('BF124','1','Just to be in You as You''re in me.<br/>Just abide in You, Lord, constantly.<br/>Here I''m one with You, as You''re with me.<br/>Here we''re joined as one, Lord, mutually<br/>',NULL,14380,14380);
INSERT INTO stanza VALUES('BF124','chorus','God''s dispensing, His economy,<br/>In His Trinity,<br/>He''s transfusing, and He''s mingling<br/>All He is to me.<br/>',NULL,14381,14381);
INSERT INTO stanza VALUES('BF124','2','I am just a branch, and You''re the vine.<br/>As I dwell in You, everything is fine.<br/>Here I''d like to be, Lord, all the time.<br/>Here I''m Yours, dear Lord, and You are mine.<br/>',NULL,14382,14382);
INSERT INTO stanza VALUES('BF124','3','I''m a branch that''s been, Lord, grafted in.<br/>I''m supplied in You in this life union.<br/>Here Your riches, Lord, in this sweet life flow.<br/>As I dwell in You, I will surely grow.<br/>',NULL,14383,14383);
INSERT INTO stanza VALUES('BF124','4','As I dwell in You, and You in me,<br/>Here I''m joined to You, Lord, practically.<br/>As I stay with You, as You''re with me,<br/>We will mingle, Lord, subjectively.<br/>',NULL,14384,14384);
INSERT INTO stanza VALUES('BF124','5','As I''m loving You and enjoying You, Lord,<br/>You become in me the rhema word.<br/>Here I''ll pray in You as You pray in me.<br/>You''ll bear fruit in me, Lord, abundantly.<br/>',NULL,14385,14385);
INSERT INTO stanza VALUES('BF124','6','As I dwell in You, Lord You''re flowing through,<br/>Lord, You''re filling me, overflowing too.<br/>Here we all are one and expressing You.<br/>Here our joy is full as we dwell in You.<br/>',NULL,14386,14386);
INSERT INTO stanza VALUES('BF125','1','Shepherd, receive man,<br/>Come near and eat with them,<br/>Publicans and sinners.<br/>Go out to carry them home<br/>On Your shoulders, rejoicing.<br/>Lord, carry them home.<br/>',NULL,14387,14387);
INSERT INTO stanza VALUES('BF125','2','Spirit, dear Spirit,<br/>Where is the one lost coin?<br/>Yes, You have the nine,<br/>But the one You must find.<br/>Dear Spirit, You''re sweeping<br/>All over the earth.<br/>',NULL,14388,14388);
INSERT INTO stanza VALUES('BF125','3','Father, dear Father,<br/>Have mercy on mankind!<br/>He''s fallen to the pigs'' pen.<br/>When will he return?<br/>Dear Father, just kiss them,<br/>Your sons coming home.<br/>',NULL,14389,14389);
INSERT INTO stanza VALUES('BF125','4','Father of mercy,<br/>Clothe him with the best robe<br/>And kill the fatted calf<br/>And eat and be merry —<br/>He was lost, but found,<br/>Was dead, but now he lives.<br/>',NULL,14390,14390);
INSERT INTO stanza VALUES('BF126','1','The Son with the Father by the Spirit —<br/>O what a mystery!<br/>The fullness of all the Godhead<br/>Dwells in Him bodily.<br/>Wonderful One, Son with the Father,<br/>Wonderful One, Son by the Spirit,<br/>Wonderful Jesus Christ,<br/>Wonderful Triune, Wonderful Triune God.<br/>',NULL,14391,14391);
INSERT INTO stanza VALUES('BF126','2','The Son with the Father by the Spirit,<br/>Conceived in a virgin''s womb<br/>The issue: a God-man, a wonderful Person,<br/>Jesus divine and human.<br/>Wonderful One, Son with the Father,<br/>Wonderful One, Son by the Spirit,<br/>Wonderful Jesus Christ,<br/>Wonderful Triune, Wonderful Triune God.<br/>',NULL,14392,14392);
INSERT INTO stanza VALUES('BF126','3','This man in perfection chose God as His living;<br/>He lived the life of God.<br/>The sin, world, and Satan could not penetrate Him;<br/>Jesus had sinless blood.<br/>Humanity, His blood has cleansed me.<br/>Divinity, my guarantee.<br/>His sinless blood cleansed me.<br/>God''s now my guaran—, God''s now my guarantee.<br/>',NULL,14393,14393);
INSERT INTO stanza VALUES('BF126','4','His flesh without sin joined man''s flesh full of sin<br/>And this trapped Satan.<br/>Man''s flesh, sin and Satan were hanging upon Him<br/>O what a termination!<br/>Terminating, the old creation,<br/>Penetrating, flesh, sin and Satan.<br/>O what a promised seed!<br/>He crushed the Devil''s, He crushed the Devil''s head.<br/>',NULL,14394,14394);
INSERT INTO stanza VALUES('BF126','5','And in resurrection, this wonderful Person<br/>The Spirit He became.<br/>The Spirit right now is the Son with the Father<br/>To be the consummation.<br/>Wonderful One, life-giving Spirit!<br/>Son has become the consummation.<br/>Son with the Father, He<br/>As Spirit dwells in, as Spirit dwells in me.<br/>',NULL,14395,14395);
INSERT INTO stanza VALUES('BF126','6','And in His ascension, this wonderful Person,<br/>This man is on God''s throne.<br/>The highest position, to Him it was given,<br/>He''s ruling and reigning.<br/>As Lord of lords and King of kings,<br/>The highest name to Jesus given.<br/>This man is on God''s throne.<br/>Most wonderful, most wonderful Person!<br/>',NULL,14396,14396);
INSERT INTO stanza VALUES('BF126','7','And in His enthronement as Head over all things<br/>The processed God is He,<br/>Dispensing Himself as the life-giving Spirit,<br/>Producing His Body.<br/>The Triune God is not for doctrine.<br/>The Trinity is for dispensing.<br/>He''s now dispensing<br/>And we''re enjoying, and we''re enjoying Him.<br/>',NULL,14397,14397);
INSERT INTO stanza VALUES('BF127','1','And He showed me a river<br/>Of water of life,<br/>Bright as crystal,<br/>Proceeding out<br/>Of the throne of God<br/>And of the Lamb.<br/>And Thou shalt make them to drink<br/>Of the river of Thy pleasures.<br/>',NULL,14398,14398);
INSERT INTO stanza VALUES('BF127','2','There is a river,<br/>The streams whereof make glad.<br/>The city of God.<br/>She shall not be moved.<br/>God shall help her.<br/>God''s in her midst.<br/>They shall be abundantly satisfied<br/>With the fatness of Thy house.<br/>',NULL,14399,14399);
INSERT INTO stanza VALUES('BF128','1','O God of Glory,<br/>You''ve changed my destiny.<br/>O Lord, Your mercy<br/>In love appeared to me.<br/>O God of Glory,<br/>You have attracted me!<br/>My heart responds to Thee<br/>And turns spontaneously.<br/>',NULL,14400,14400);
INSERT INTO stanza VALUES('BF128','chorus','O God of Glory,<br/>You have appeared to me.<br/>Dear Lord, Your beauty,<br/>My God, has captured me!<br/>',NULL,14401,14401);
INSERT INTO stanza VALUES('BF128','2','In darkness once I groped,<br/>A person with no hope.<br/>But light in darkness shined,<br/>My heart enlightened.<br/>You came to me as light<br/>And shattered all my night.<br/>Your glory, what a sight!<br/>You made me, Lord, so bright.<br/>',NULL,14402,14402);
INSERT INTO stanza VALUES('BF128','3','To You my heart was drawn,<br/>It wasn''t on my own.<br/>Your beauty made me turn<br/>And caused my heart to burn.<br/>You touched my hardened heart<br/>And softened every part.<br/>I saw Your shining face.<br/>Now nothing can erase.<br/>',NULL,14403,14403);
INSERT INTO stanza VALUES('BF128','4','Lord, I could not believe,<br/>But, Lord, You still appeared.<br/>Your life in me conceived,<br/>Dear Lord, I now believe.<br/>You called not being as being<br/>In me conceiving.<br/>Your life transfusing,<br/>I''m now reacting.<br/>',NULL,14404,14404);
INSERT INTO stanza VALUES('BF128','chorus','O God of Glory,<br/>You''re now my story.<br/>Dear One, I can''t refuse!<br/>By You, I''ve been transfused.<br/>',NULL,14405,14405);
INSERT INTO stanza VALUES('BF128','5','Like father Abraham,<br/>To You, dear Lord, he ran.<br/>With glory we''re infused,<br/>Dear Lord, we can''t refuse.<br/>You came to fallen man<br/>As, Lord, the Great I Am<br/>In us dispensing<br/>The blessing to mankind.<br/>',NULL,14406,14406);
INSERT INTO stanza VALUES('BF129','1','Lord, Your return...<br/>How long must it be, dear Lord?<br/>The ages have come,<br/>The centuries have gone,<br/>The years have passed us by.<br/>Lovely One, come soon.<br/>Precious Lord, return!<br/>Lord, do not delay.<br/>We''ll redeem everyday<br/>For Your coming soon.<br/>',NULL,14407,14407);
INSERT INTO stanza VALUES('BF129','2','A generation...<br/>Lord, of them that seek Your face;<br/>A remnant for You<br/>Whose hearts are so true.<br/>They''re those who just love You.<br/>King of glory come in!<br/>Saints, open wide to Him.<br/>O, lift up Your gate,<br/>It''s not too late.<br/>Let the King come in.<br/>',NULL,14408,14408);
INSERT INTO stanza VALUES('BF129','3','A generation...<br/>With a goal to bring You back.<br/>Their treasure is You,<br/>You''re their future too.<br/>They care for only You.<br/>This goal is deep within,<br/>A fire that''s burning in them.<br/>They''re consumed by this zeal,<br/>This only is real,<br/>Lord, to bring You back.<br/>',NULL,14409,14409);
INSERT INTO stanza VALUES('BF129','4','A generation...<br/>Lord, by You they are possessed.<br/>You have captured their heart,<br/>The world has no part,<br/>Their joy is only You.<br/>They''re virgins pure and wise.<br/>Just You are in their eyes.<br/>Their hearts make full room<br/>For You, dear Bridegroom,<br/>For Your coming soon.<br/>',NULL,14410,14410);
INSERT INTO stanza VALUES('BF129','5','Oh, generation...<br/>The Spirit and Bride say come —<br/>The Spirit''s calling you.<br/>The Bride is calling too!<br/>Take heed to this mingled cry!<br/>Come, oh seekers, come<br/>To our Groom, most pleasant Person.<br/>God''s eternal plan<br/>Is to mingle with man.<br/>This His satisfaction.<br/>',NULL,14411,14411);
INSERT INTO stanza VALUES('BF129','6','Oh come, Lord Jesus...<br/>For this cause, Lord, strengthen us.<br/>Keep us faithful to stand<br/>All the way to the end.<br/>Uphold us in Your hands.<br/>Come, Lord Jesus, come<br/>For Your Bride, New Jerusalem.<br/>Till we meet face to face,<br/>Fill us daily with grace.<br/>For that day make haste.<br/>',NULL,14412,14412);
INSERT INTO stanza VALUES('BF130','1','Lord, I just love You.<br/>And there''s no one like You.<br/>In the whole universe<br/>I have no other one like You.<br/>Lord Jesus, I love You.<br/>',NULL,14413,14413);
INSERT INTO stanza VALUES('BF131','1','Let''s go on!<br/>Forward come!<br/>A heart that is loving Him,<br/>A heart that is willing,<br/>A heart that''s uplifted,<br/>No, not defeated!<br/>Let''s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,14414,14414);
INSERT INTO stanza VALUES('BF131','chorus','We are Your vessels,<br/>Created to be<br/>Man in Your image<br/>To be filled up with Thee.<br/>You''re my enjoyment<br/>Overflowing me!<br/>I''m a man in Your image,<br/>Thus expressing Thee!<br/>',NULL,14415,14415);
INSERT INTO stanza VALUES('BF131','2','Let''s go on!<br/>Forward come!<br/>A spirit that''s burning,<br/>A heart that is bubbling,<br/>Saints that are eating<br/>And always drinking!<br/>Let''s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,14416,14416);
INSERT INTO stanza VALUES('BF131','3','Let''s go on!<br/>Forward come!<br/>Spirit releasing,<br/>Saints that are feasting,<br/>Not analyzing,<br/>Or criticizing.<br/>Let''s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,14417,14417);
INSERT INTO stanza VALUES('BF131','4','Let''s go on!<br/>Forward come!<br/>Life so enjoyable,<br/>Else it be terrible,<br/>But He''s so wonderful,<br/>And so available!<br/>Let''s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,14418,14418);
INSERT INTO stanza VALUES('BF132','1','Let me stand behind You, Lord.<br/>Let me wash Your feet with my tears.<br/>Let me wipe them with my hair.<br/>Let me kiss them and anoint them<br/>With the ointment.<br/><br/>I love You!<br/>Jesus, I love You!<br/>May I waste my all and life on You.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One<br/>Because I love You.<br/>',NULL,14419,14419);
INSERT INTO stanza VALUES('BF132','2','Let me take a pound of ointment pure<br/>Of great value to anoint Your feet<br/>And wipe them with my hair<br/>That the house be filled with the fragrance<br/>Of the ointment.<br/><br/>I love You!<br/>Jesus, I love You!<br/>May I waste my all and life on You.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One<br/>Because I love You.<br/>',NULL,14420,14420);
INSERT INTO stanza VALUES('BF132','3','Lord, they said if You were a prophet,<br/>You should know who and what I am.<br/>I''m a sinner that toucheth You,<br/>A woman not worthy to anoint You.<br/><br/>But I love You!<br/>Jesus, I love You!<br/>You forgave me the most<br/>Now I love You, Lord, the most.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One,<br/>Because You love me.<br/>',NULL,14421,14421);
INSERT INTO stanza VALUES('BF132','4','Let my love from my being wash Your feet<br/>And my glory without wipe them too<br/>Let me kiss them where the nails would pierce.<br/>All my love, Lord, and glory I''ll waste on You.<br/><br/>I love You!<br/>Jesus, I love You!<br/>All my glory and love I pour<br/>And waste on You.<br/>Receive my ointment, Lord.<br/>It''s all I have, dear Lord.<br/>For You, most precious One,<br/>Because I love You.<br/>',NULL,14422,14422);
INSERT INTO stanza VALUES('BF133','1','Gathered in Thy name, Lord Jesus,<br/>Losing sight of all but Thee,<br/>O what joy Thy presence gives us,<br/>Calling up our hearts to Thee!<br/>',NULL,14423,14423);
INSERT INTO stanza VALUES('BF133','2','Loved with love which knows no measure,<br/>Save the Father''s love to Thee,<br/>Blessed Lord, our hearts would treasure<br/>All the Father''s thoughts of Thee.<br/>',NULL,14424,14424);
INSERT INTO stanza VALUES('BF133','3','All His joy, His rest, His pleasure—<br/>All His deep delight in Thee—<br/>Lord, Thy heart alone can measure<br/>What Thy Father found in Thee.<br/>',NULL,14425,14425);
INSERT INTO stanza VALUES('BF133','4','How He set His love upon Thee—<br/>Called Thee His beloved Son;<br/>Yet for us He did not spare Thee,<br/>By Thy death our life was won.<br/>',NULL,14426,14426);
INSERT INTO stanza VALUES('BF133','5','O the joy, the wondrous singing,<br/>When we see Thee as Thou art!<br/>Thy blest name, Lord Jesus, bringing<br/>Sweetest music to God''s heart.<br/>',NULL,14427,14427);
INSERT INTO stanza VALUES('BF133','6','Notes of gladness, songs unceasing,<br/>Hymns of everlasting praise,<br/>Psalms of glory, joy increasing,<br/>Through God''s endless day of days.<br/>',NULL,14428,14428);
INSERT INTO stanza VALUES('BF134','1','Father, long before creation,<br/>Thou hadst chosen us in love;<br/>And that love, so deep, so moving,<br/>Draws us close to Christ above,<br/>And will keep us, and will keep us,<br/>Firmly fixed in Christ alone,<br/>Firmly fixed in Christ alone.<br/>',NULL,14429,14429);
INSERT INTO stanza VALUES('BF134','2','Though the world may change its fashion,<br/>Yet our God is e''er the same;<br/>His compassion and His cov''nant<br/>Through all ages will remain.<br/>God''s own children, God''s own children,<br/>Must forever praise His name,<br/>Must forever praise His name.<br/>',NULL,14430,14430);
INSERT INTO stanza VALUES('BF134','3','God''s compassion is my story,<br/>Is my boasting all the day;<br/>Mercy free and never failing<br/>Moves my will, directs my way.<br/>God so loved us, God so loved us,<br/>That His only Son He gave,<br/>That His only Son He gave.<br/>',NULL,14431,14431);
INSERT INTO stanza VALUES('BF134','4','Loving Father, now before Thee<br/>We will ever praise Thy love;<br/>And our song will sound unceasing<br/>Till we meet Thy Son above,<br/>Giving glory, giving glory,<br/>To our God and to the Lamb,<br/>To our God and to the Lamb.<br/>',NULL,14432,14432);
INSERT INTO stanza VALUES('BF135','1','Dear Lord Jesus, precious Jesus,<br/>Thou hast won each love from me;<br/>Who like Thee — so fair and comely?<br/>Who like Thee — so sweet and lovely?<br/>Matchless One, unrivaled beauty,<br/>None can e''er compete with Thee!<br/>',NULL,14433,14433);
INSERT INTO stanza VALUES('BF135','2','Dear Lord Jesus, precious Jesus,<br/>Gladly will I hear Thy call;<br/>Since Thy voice my heart hath entered,<br/>I from all things could but sever;<br/>Void are all my other seekings,<br/>Every pride hath disappeared.<br/>',NULL,14434,14434);
INSERT INTO stanza VALUES('BF135','3','Dear Lord Jesus, precious Jesus,<br/>How can I still stubborn be?<br/>At Thy feet cast all my hard''nings,<br/>And return with songs and singings;<br/>''Tis my love to be Thy bondslave,<br/>''Tis my joy to Thee obey.<br/>',NULL,14435,14435);
INSERT INTO stanza VALUES('BF135','4','Dear Lord Jesus, precious Jesus,<br/>Thy way only will I choose;<br/>Though in tears while I''m obeying,<br/>Yet I would not change my standing;<br/>All I long for is Thy pleasure,<br/>And the peace Thy love would bring.<br/>',NULL,14436,14436);
INSERT INTO stanza VALUES('BF135','5','Dear Lord Jesus, precious Jesus,<br/>When Thy presence does depart,<br/>Seems the dawn has lost its traces,<br/>Hidden are my smiling faces;<br/>All I yearn for is Thy coming<br/>And Thy presence'' sweet embrace.<br/>',NULL,14437,14437);
INSERT INTO stanza VALUES('BF135','6','Dear Lord Jesus, precious Jesus,<br/>Can I tell it all to Thee?<br/>Thou my love and satisfaction,<br/>Thou my everlasting portion;<br/>Thou art all that I desire,<br/>Nothing else I would pursue.<br/>',NULL,14438,14438);
INSERT INTO stanza VALUES('BF135','7','Dear Lord Jesus, precious Jesus,<br/>All I have I give to Thee;<br/>Who like Thee — so fair and comely?<br/>Who like Thee — so sweet and lovely?<br/>Matchless One, unrivaled beauty,<br/>None can e''er compete with Thee!<br/>',NULL,14439,14439);
INSERT INTO stanza VALUES('BF136','1','I take Thy promise, Lord, in all its length,<br/>And breadth and fullness, as my daily strength;<br/>Into life''s future fearless I may gaze,<br/>For, Savior, Thou art with me all the days.<br/>',NULL,14440,14440);
INSERT INTO stanza VALUES('BF136','2','Days may be coming fraught with loss and change,<br/>New scenes surround my life and fancies strange;<br/>I thank Thee that no day can ever break,<br/>Savior, when Thou wilt leave me or forsake.<br/>',NULL,14441,14441);
INSERT INTO stanza VALUES('BF136','3','There may be days of darkness and distress,<br/>When sin has power to tempt, and care to press,<br/>Yet in the darkest day I will not fear,<br/>For, ''mid the shadows, Thou wilt still be near.<br/>',NULL,14442,14442);
INSERT INTO stanza VALUES('BF136','4','Days there may be of joy and deep delight,<br/>When earth seems fairest, and her skies most bright,<br/>Then draw me closer to Thee, lest I rest<br/>Elsewhere, my Savior, than upon Thy breast.<br/>',NULL,14443,14443);
INSERT INTO stanza VALUES('BF136','5','And all the other days that make my life,<br/>Marked by no special joy or grief or strife,<br/>Days filled with quiet duties, trivial care,<br/>Burdens too small for other hearts to share;<br/>',NULL,14444,14444);
INSERT INTO stanza VALUES('BF136','6','Spend Thou these days with me, all shall be Thine,<br/>So shall the darkest hour with glory shine.<br/>Then when these earthly years have passed away,<br/>Let me be with Thee in the perfect day.<br/>',NULL,14445,14445);
INSERT INTO stanza VALUES('BF137','1','Always rejoice, unceasingly pray,<br/>In everything give thanks;<br/>Always rejoice, unceasingly pray,<br/>In everything give thanks;<br/>For this is the will of God in Christ Jesus<br/>The will of God in Christ for you.<br/>Therefore always rejoice, unceasingly pray,<br/>In everything give thanks.<br/>(repeat stanza)<br/>',NULL,14446,14446);
INSERT INTO stanza VALUES('BF137','2','Do not quench the Spirit;<br/>Do not despise prophecies,<br/>But prove all things, hold fast to what is good;<br/>Abstain from every kind of evil.<br/>(repeat stanza 1)<br/>',NULL,14447,14447);
INSERT INTO stanza VALUES('BF138','1','Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>So turn your heart to the Lord all the day,<br/>And the veil shall be taken away.<br/>',NULL,14448,14448);
INSERT INTO stanza VALUES('BF138','2','Now the Lord is the Spirit and where the Spirit of the Lord is,<br/>There is liberty, such liberty.<br/>Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>',NULL,14449,14449);
INSERT INTO stanza VALUES('BF138','3','Now the Lord is the Spirit and where the Spirit of the Lord is,<br/>There is Liberty, such liberty.<br/>Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>',NULL,14450,14450);
INSERT INTO stanza VALUES('BF139','1','Lord, now I see,<br/>You only want me to believe<br/>Not to dwell,<br/>In all my failures and defeats<br/>To believe what You have done,<br/>And not in what I see.<br/>',NULL,14451,14451);
INSERT INTO stanza VALUES('BF139','2','Lord, I believe,<br/>When all around me is defeat<br/>And it seems that nothing''s changing outwardly.<br/>No! I''m not discouraged.<br/>I''m believing You.<br/>',NULL,14452,14452);
INSERT INTO stanza VALUES('BF139','3','Yes, I believe,<br/>And there is no demand on me.<br/>Simple faith, yes, that is all You want from me.<br/>Freed from anxious doubting —<br/>I''m free to just believe!<br/>',NULL,14453,14453);
INSERT INTO stanza VALUES('BF139','4','Believing You,<br/>Because, Lord, You are my success!<br/>When I fail, all I must do is just confess.<br/>And go on enjoying You —<br/>I love believing You!<br/>',NULL,14454,14454);
INSERT INTO stanza VALUES('BF140','1','Jesus Lord, I long<br/>For Your embrace<br/>To taste Your kisses sweeter than wine,<br/>To know the love that surpasses all time,<br/>To feel the joy when I am in Your arms,<br/>Precious One.<br/>',NULL,14455,14455);
INSERT INTO stanza VALUES('BF140','2','Jesus Lord, You died<br/>To set me free.<br/>Now You''re my all and my everything;<br/>I am so lost when I''m not near Thee;<br/>Sick with love for You I''ll ever be,<br/>Treasured One.<br/>',NULL,14456,14456);
INSERT INTO stanza VALUES('BF140','3','Jesus Lord, I''m charmed<br/>By Your mercy<br/>And I rejoice that You''ve chosen me<br/>To be with You in eternity<br/>But until then keep me close to Thee,<br/>Lovely One.<br/>',NULL,14457,14457);
INSERT INTO stanza VALUES('BF141','1','Arise, my soul, arise.<br/>My Lord is calling me;<br/>He waits to fill my heart,<br/>He longs to set me free.<br/>',NULL,14458,14458);
INSERT INTO stanza VALUES('BF141','chorus','Dear Lord, Your own blood<br/>Was shed for me,<br/>That I might live for eternity.<br/>So lost in Your love;<br/>So close to Your heart,<br/>Oh Lord draw me nearer now.<br/>',NULL,14459,14459);
INSERT INTO stanza VALUES('BF141','2','O Lord I open now.<br/>I just received Your life;<br/>Your joy now fills my heart,<br/>Your peace has freed my soul.<br/>',NULL,14460,14460);
INSERT INTO stanza VALUES('BF141','3','Dear Lord, You''ve won our hearts.<br/>We now surrender all;<br/>Our life belongs to You,<br/>Dear Jesus, seek us close.<br/>',NULL,14461,14461);
INSERT INTO stanza VALUES('BF141','chorus','Oh Lord, since Your blood<br/>Has set us free,<br/>We will live for eternity.<br/>So lost in Your love;<br/>So close to Your heart,<br/>Dear Lord, ever draw us near.<br/>',NULL,14462,14462);
INSERT INTO stanza VALUES('BF142','1','He washed away my sins<br/>Gave me a brand new heart<br/>Now I do love Him, trust Him,<br/>See Him in His Word.<br/>',NULL,14463,14463);
INSERT INTO stanza VALUES('BF142','chorus','He tells me guard thy heart<br/>Above all that thou guardest<br/>For out of it flows the streams,<br/>the streams of life.<br/>',NULL,14464,14464);
INSERT INTO stanza VALUES('BF142','2','And sometimes when I fail<br/>Forgot that He is there<br/>He''s just there waiting, watching,<br/>And He draws me near.<br/>',NULL,14465,14465);
INSERT INTO stanza VALUES('BF142','3','He walks with me each day<br/>I open up to Him<br/>He is my life, my stay,<br/>And everything I need.<br/>',NULL,14466,14466);
INSERT INTO stanza VALUES('BF143','1','God is man''s treasure,<br/>He is man''s joy and pleasure.<br/>God is man''s treasure,<br/>He is man''s joy and pleasure.<br/>God placed man in paradise,<br/>Right in front of the tree of life.<br/>If man would eat the tree of life,<br/>He surely would be so satisfied.<br/>',NULL,14467,14467);
INSERT INTO stanza VALUES('BF143','2','Saints, beware the knowledge tree<br/>Appearing so good; it''s even pretty.<br/>Its evil and good will open your eyes;<br/>Its issue, my friend: you''ll surely die.<br/>The serpent, he crept in,<br/>Injected in man his death and sin.<br/>Man was seduced this knowledge to take.<br/>My friend, that was the greatest mistake.<br/>',NULL,14468,14468);
INSERT INTO stanza VALUES('BF143','3','Look, dear saints, in eternity!<br/>There''s just a river and a tree!<br/>It''s life, life abundantly —<br/>Eating and drinking our destiny.<br/>God''s growing and flowing.<br/>We''re eating and drinking.<br/>God is our treasure.<br/>He is our joy and pleasure.<br/>',NULL,14469,14469);
INSERT INTO stanza VALUES('BF143','4','Christ is the tree of life<br/>Eating Him always satisfies.<br/>Christ is the river<br/>Drink Him, our joy and pleasure.<br/>Eat Him and drink Him,<br/>Christ our enjoyment.<br/>God is our treasure.<br/>He is our joy and pleasure.<br/>',NULL,14470,14470);
INSERT INTO stanza VALUES('BF143','5','Dear saints, just love Him.<br/>Surely you will enjoy Him.<br/>He is so enjoyable,<br/>So precious and so available.<br/>Our God is dispensing<br/>His life into us, so refreshing.<br/>He is so enjoyable,<br/>So precious and so available.<br/>',NULL,14471,14471);
INSERT INTO stanza VALUES('BF144','1','Jesus won''t You come, won''t You come, won''t You come?<br/>We say to our Bridegroom come.<br/>Jesus won''t You come, won''t You come, won''t You come?<br/>We say to our Bridegroom come.<br/>',NULL,14472,14472);
INSERT INTO stanza VALUES('BF144','2','Blend us all as one, all as one, that we will be<br/>A bride that matches You perfectly;<br/>Make us all to be, all to be, all to be<br/>The expression of Your glory.<br/>',NULL,14473,14473);
INSERT INTO stanza VALUES('BF144','3','Oh, our Love, we know You are longing for Your Bride<br/>Lord, we long, that Your heart desire would be satisfied.<br/>',NULL,14474,14474);
INSERT INTO stanza VALUES('BF145','1','Nothing''s quite so precious<br/>As Jesus in my spirit.<br/>He takes away the care<br/>And fills me with His peace.<br/>He never leaves me,<br/>E''en as the days grow weary.<br/>His presence goes with me.<br/>My soul delights to hide in His arms.<br/>',NULL,14475,14475);
INSERT INTO stanza VALUES('BF145','chorus','I call His name, "Lord Jesus,<br/>Help me in my weakness."<br/>So faithfully each day in me<br/>He proves His life is so sufficient.<br/>',NULL,14476,14476);
INSERT INTO stanza VALUES('BF145','2','Nothing''s quite so precious<br/>As Jesus in my spirit.<br/>He turns my heart to Him,<br/>To feast upon His life.<br/>It''s nothing I do—<br/>His mercy''s just upon me.<br/>And God''s free gift of grace<br/>Becomes an endless joy to me.<br/>',NULL,14477,14477);
INSERT INTO stanza VALUES('BF146','1','What a happy day<br/>When I no more could turn away,<br/>When Jesus took my heart<br/>from the black of night<br/>Into the kingdom of His light.<br/>',NULL,14478,14478);
INSERT INTO stanza VALUES('BF146','2','Now my life''s begun,<br/>The "really life" that''s in the Son.<br/>No more enthralled by<br/>earth''s empty dreams;<br/>Deep in me flows a living stream.<br/>',NULL,14479,14479);
INSERT INTO stanza VALUES('BF146','3','As I turn to Him<br/>He fills me with His life within.<br/>His life becomes my life in reality<br/>Oh, hallelujah, He''s in me!<br/>',NULL,14480,14480);
INSERT INTO stanza VALUES('BF146','4','I just love You, Lord,<br/>With other loves, You break the cord.<br/>You''ll be my life for all eternity;<br/>You are the only One for me.<br/>',NULL,14481,14481);
INSERT INTO stanza VALUES('BF147','1','Our spirit is our organ to receive God.<br/>So every day, all the time, we must exercise,<br/>Exercise this organ to take the word.<br/>In this way, we receive life.<br/>This is the experience of life.<br/>The experience of life is just to exercise,<br/>',NULL,14482,14482);
INSERT INTO stanza VALUES('BF147','2','Exercise our spirit<br/>To eat the word that we may receive life.<br/>After being received by us<br/>This life will live out all kinds of<br/>Divine, spiritual, and heavenly things<br/>In an unlimited way.<br/><br/>',NULL,14483,14483);
INSERT INTO stanza VALUES('BF148','1','As a lily growing out of a bramble bush;<br/>As a bright star shining forth in the darkest night;<br/>Is a story excellent, bright and fragrant<br/>Of Boaz and Ruth in a divine romance.<br/>',NULL,14484,14484);
INSERT INTO stanza VALUES('BF148','2','Ruth the Moabitess joined to God''s holy elect;<br/>Boaz took care of her and redeemed all her debt.<br/>First she gleaned from his land,<br/>Then got married to him.<br/>This is how she was joined to God''s eternal plan.<br/>',NULL,14485,14485);
INSERT INTO stanza VALUES('BF148','chorus','Lord, I love You and treasure You.<br/>Lord, I choose You and respond to You.<br/>You''re my everything, You''re above all,<br/>You''re my Husband, and my rest,<br/>And my all in all.<br/>',NULL,14486,14486);
INSERT INTO stanza VALUES('BF148','3','The eternal God entered and stepped into time;<br/>For this He needed persons to carry the line —<br/>Those who fulfilled His plan, to bring God into man<br/>Bringing divinity into humanity.<br/>',NULL,14487,14487);
INSERT INTO stanza VALUES('BF148','4','In the universe this is the greatest event,<br/>That is Christ''s incarnation — in His first advent.<br/>Ruth became an ancestor in this mystery —<br/>God and man to be mingled as one entity.<br/>',NULL,14488,14488);
INSERT INTO stanza VALUES('BF148','5','God had promised the seed of a woman for man<br/>That would crush Satan''s head and redeem fallen man;<br/>To make God and man one, what a glory to Him!<br/>We are qualified now to partake of Him.<br/>',NULL,14489,14489);
INSERT INTO stanza VALUES('BF148','6','We are Moabites too, constituted with sin;<br/>We are under God''s wrath and His condemnation.<br/>But through Christ''s redemption, He''s our portion we claim;<br/>In this organic union, we''re married to Him.<br/>',NULL,14490,14490);
INSERT INTO stanza VALUES('BF149','1','Call, call, won''t you call Jesus'' name —<br/>He''s everything that''s real, and He''s always the same.<br/>Get out of your mind, get your spirit in gear,<br/>That''s the way to get to Jesus from here.<br/>That''s the way to get to Jesus from here.<br/>',NULL,14491,14491);
INSERT INTO stanza VALUES('BF149','2','Life, Life, O the issue is Life.<br/>Living isn''t worth it if you haven''t got Life.<br/>So drop all your concepts, they''re killing you dead,<br/>And touch the living Jesus instead.<br/>And touch the living Jesus instead.<br/>',NULL,14492,14492);
INSERT INTO stanza VALUES('BF149','3','God, God, O You gave us Your Son,<br/>He died for us and rose again; the victory He won!<br/>And now He lives within us, new life has begun.<br/>O we praise You, Lord, it all has been done.<br/>O we praise You, Lord, it all has been done.<br/>',NULL,14493,14493);
INSERT INTO stanza VALUES('BF150','1','Fallen, that''s the way we all begin;<br/>Imprisoned by this evil fate we''re in.<br/>How can we from this hard world of sin be saved?<br/>',NULL,14494,14494);
INSERT INTO stanza VALUES('BF150','chorus','It''s by calling Jesus, Jesus, Jesus,<br/>Every moment each day!<br/>Calling on the name of Jesus —<br/>You''ll find this is the way.<br/>It''s Jesus, Lord Jesus!<br/>',NULL,14495,14495);
INSERT INTO stanza VALUES('BF150','2','Still times, though we love the Lord so much,<br/>Somehow, it seems that we get out of touch.<br/>With Jesus, how can we be freed from such distress?<br/>',NULL,14496,14496);
INSERT INTO stanza VALUES('BF150','3','Sometimes we know we aren''t being real.<br/>Then times, we just live by how we feel.<br/>Is there some way we could ever deal with self?<br/>',NULL,14497,14497);
INSERT INTO stanza VALUES('BF150','4','Christians, scattered throughout all the earth<br/>Are wandering, where is the pearl of great worth?<br/>How can all those of the second birth be one?<br/>',NULL,14498,14498);
INSERT INTO stanza VALUES('BF150','5','Calling, you''ll find this will fill your lack,<br/>And calling is going to bring our Bridegroom back.<br/>Why not stand upon this glorious fact today?<br/>',NULL,14499,14499);
INSERT INTO stanza VALUES('BF151','1','God the Creator became a God-man.<br/>His death redeemed us for His glorious plan.<br/>Now in resurrection the Spirit''s released<br/>Producing the church.<br/>This is God''s masterpiece.<br/>',NULL,14500,14500);
INSERT INTO stanza VALUES('BF151','2','Lord, You are my choice.<br/>I have seen Your beauty.<br/>I belong to You<br/>Now and evermore.<br/>You''re my only choice<br/>Lord, You are so lovely.<br/>Lord, I give all for Your masterpiece.<br/>',NULL,14501,14501);
INSERT INTO stanza VALUES('BF151','3','Lord, I love You.<br/>There is no other.<br/>I''ll love You always.<br/>Lord, I love You.<br/>My heart is recovered.<br/>Lord, I give all for Your masterpiece.<br/>',NULL,14502,14502);
INSERT INTO stanza VALUES('BF151','4','Thank You, Lord Jesus, for capturing me.<br/>Thank You, Lord, I now experience Thee.<br/>By feasting! Enjoying!<br/>Your Life would increase.<br/>Thank You, Lord, I''m part of God''s masterpiece.<br/>',NULL,14503,14503);
INSERT INTO stanza VALUES('BF152','1','Hast thou heard Him, seen Him, known Him?<br/>Is not thine a captured heart?<br/>Chief among ten thousand own Him;<br/>Joyful choose the better part.<br/>',NULL,14504,14504);
INSERT INTO stanza VALUES('BF152','chorus','Captivated by His beauty,<br/>Worthy tribute haste to bring;<br/>Let His peerless worth constrain thee,<br/>Crown Him now unrivaled King.<br/>',NULL,14505,14505);
INSERT INTO stanza VALUES('BF152','2','Idols once they won thee, charmed thee,<br/>Lovely things of time and sense;<br/>Gilded thus does sin disarm thee,<br/>Honeyed lest thou turn thee thence.<br/>',NULL,14506,14506);
INSERT INTO stanza VALUES('BF152','3','What has stripped the seeming beauty<br/>From the idols of the earth?<br/>Not a sense of right or duty,<br/>But the sight of peerless worth.<br/>',NULL,14507,14507);
INSERT INTO stanza VALUES('BF152','4','Not the crushing of those idols,<br/>With its bitter void and smart;<br/>But the beaming of His beauty,<br/>The unveiling of His heart.<br/>',NULL,14508,14508);
INSERT INTO stanza VALUES('BF152','5','Who extinguishes their taper<br/>Till they hail the rising sun?<br/>Who discards the garb of winter<br/>Till the summer has begun?<br/>',NULL,14509,14509);
INSERT INTO stanza VALUES('BF152','6','''Tis that look that melted Peter,<br/>''Tis that face that Stephen saw,<br/>''Tis that heart that wept with Mary,<br/>Can alone from idols draw:<br/>',NULL,14510,14510);
INSERT INTO stanza VALUES('BF152','7','Draw and win and fill completely,<br/>Till the cup o''erflow the brim;<br/>What have we to do with idols<br/>Who have companied with Him?<br/>',NULL,14511,14511);
INSERT INTO stanza VALUES('BF153','1','Attracted by Your love, Lord<br/>And charmed by Your sweet name,<br/>I''m captivated by Your person too.<br/>Into your inner chambers,<br/>For fellowship so sweet<br/>My King You''ve brought me in my spirit as...<br/>My Pneumatic Christ<br/>You''re so personal, affectionate to me,<br/>Pursuing You I''m to the church life led<br/>So that I''m transformed from mare to lily with...<br/>',NULL,14512,14512);
INSERT INTO stanza VALUES('BF153','chorus','A single eye		(with plaits of gold,<br/>Live by trusting You	silver studs and jew''ls)<br/>I gain You		(Christ — I enjoy<br/>And You gain me	Spikenard — You enjoy)<br/>Feast... Banquet — filled!<br/>Mutual satisfaction and mutual rest.<br/>',NULL,14513,14513);
INSERT INTO stanza VALUES('BF153','2','But Lord through my attainments, my introspective self<br/>Arises as excluding wall to build<br/>I long for my perfection, my little foxes loose.<br/>Lord free me from the self, fulfill Your plan.<br/>Take me to the cross<br/>In the rough clefts of the rock I would remain<br/>By Your resurrection pow''r empowers me<br/>And encourage me to rise and come away,<br/>',NULL,14514,14514);
INSERT INTO stanza VALUES('BF153','chorus','Then I''m conformed	(in union, I''m<br/>To the death of Christ	Your bed, palanquin,<br/>Experience		espoused to be<br/>Resurrection life		one with Solomon)<br/>Move with God,<br/>As a steady pillar of smoke, like God!<br/>',NULL,14515,14515);
INSERT INTO stanza VALUES('BF153','3','Continue, Lord, to call me that I would be in You<br/>To live in Your ascension, high above.<br/>As God''s new creation in resurrection that<br/>My Christ in many aspects I''ll enjoy.<br/>Looking from the top of Amana, Senir, Hermon<br/>While we fight the enemy<br/>Enjoy Christ in His death, resurrection and ascension, Spirit, too.<br/>',NULL,14516,14516);
INSERT INTO stanza VALUES('BF153','chorus','I then become		(with a spring shut up<br/>A rich garden, full	and with fountain sealed)<br/>Of choicest fruits,	(the north wind wakes,<br/>And chief spices flow	and the south wind blows)<br/>Exuding Christ —<br/>Fragrant garden for the Triune God<br/>',NULL,14517,14517);
INSERT INTO stanza VALUES('BF153','4','A sanctuary — Tirzah, Jerusalem its guard<br/>Still has a separating veil, the flesh.<br/>So deeper still You call me to live within the veil<br/>That stronger cross I would experience now.<br/>For Your grace to me is sufficient, it supplies abundantly<br/>To enter into the Holiest place of all<br/>Hidden manna, budding rod and inner law<br/>',NULL,14518,14518);
INSERT INTO stanza VALUES('BF153','chorus','I then become		(so spiritual,<br/>Heaven''s moon and sun	and so heavenly)<br/>God''s army — fight	(we terrify<br/>Overcome as one;	our enemy.)<br/>The Shulammite,<br/>As the ultimate, New Jerusalem<br/>',NULL,14519,14519);
INSERT INTO stanza VALUES('BF154','1','Kissed with the kisses of Your mouth, so intimate and sweet<br/>Your love has drawn, Your name has charmed, You''ve captivated me<br/>No other love can cheer me so, no other name as ointment flows.<br/>Heart''s deepest cry, You satisfy, I pursue.<br/>',NULL,14520,14520);
INSERT INTO stanza VALUES('BF154','2','Here in the inner chambers, Lord, the Holiest within<br/>With mingled spirit, I enjoy the Spirit consummate<br/>Though I am black from Adam''s sin, now I am lovely I''m in Him<br/>For food and rest, follow the steps of the flock.<br/>',NULL,14521,14521);
INSERT INTO stanza VALUES('BF154','3','As by the Spirit I''m transformed, I''m transferred and renewed,<br/>A self-reliant mare becomes a lily so subdued<br/>Plaited with gold, with silver studs, necklace of jewels - the Triune God<br/>Perfected by, Joints of supply, for your plan!<br/>',NULL,14522,14522);
INSERT INTO stanza VALUES('BF154','4','Here in the church the table''s spread; the Triune God''s my feast!<br/>My spikenard''s fragrance over all to Christ has been released.<br/>Apple tree, shade and raisin cakes, banner of love and sweet embrace.<br/>Mutual rest, and mutual peace — satisfied!<br/>',NULL,14523,14523);
INSERT INTO stanza VALUES('BF154','5','Now from my introspective self, You''re calling me away<br/>You are my resurrection pow''r, upon the cross to stay<br/>Spring has begun, the winter''s past, heaven and earth are joined at last<br/>You''re our gazelle, we''re your Bethel, God and man!<br/>',NULL,14524,14524);
INSERT INTO stanza VALUES('BF155','1','O Tide of love<br/>Constrain me<br/>With Your love<br/>Like a mighty<br/>Rushing water<br/>Carry me away.<br/>',NULL,14525,14525);
INSERT INTO stanza VALUES('BF155','chorus','You''re so attracting<br/>Can''t help but asking<br/>"Lord, make me one<br/>Who loves You<br/>To the uttermost<br/>That I would live and die to You.<br/>Grant me the grace and<br/>Mercy to be<br/>Faithful to the end."<br/>',NULL,14526,14526);
INSERT INTO stanza VALUES('BF155','2','I want true love<br/>Write Your name upon me<br/>Fully occupy me<br/>Fully saturate<br/>And permeate me<br/>Until I''m one with You<br/>',NULL,14527,14527);
INSERT INTO stanza VALUES('BF155','3','O faithful One<br/>Put Yourself into my heart<br/>Open every, every part<br/>And make Your heart''s desire<br/>The desire of my heart.<br/>',NULL,14528,14528);
INSERT INTO stanza VALUES('BF155','chorus','You''re so attracting<br/>Can''t help but asking<br/>"Make me a part<br/>Of the firstfruits<br/>To satisfy Your heart."<br/>',NULL,14529,14529);
INSERT INTO stanza VALUES('BF156','1','A lover of Christ should be one<br/>Who''s attracted by His love<br/>And drawn by His sweetness<br/>To pursue after Him, pursue after Him,<br/>Pursue Him for full satisfaction.<br/>',NULL,14530,14530);
INSERT INTO stanza VALUES('BF156','2','A lover of Christ should be one<br/>Who is called by Him<br/>To be delivered<br/>From the self through His oneness<br/>With the cross, with the cross of Christ.<br/>',NULL,14531,14531);
INSERT INTO stanza VALUES('BF156','3','A lover of Christ should be one<br/>Who is called by Him to live in ascension<br/>As the new creation, creation of God,<br/>In the resurrection of Christ.<br/>',NULL,14532,14532);
INSERT INTO stanza VALUES('BF156','4','A lover of Christ should be one<br/>Who''s called by Him more strongly to live within<br/>The veil, thru His cross after the lover''s<br/>Experience of His resurrection.<br/>',NULL,14533,14533);
INSERT INTO stanza VALUES('BF157','1','How vast, immense, and measureless<br/>The love of Christ to me!<br/>How else could such a wretch as I<br/>Be blessed so graciously?<br/>To bring me back unto Himself,<br/>My Lord His all did spend;<br/>So I would gladly bear the cross<br/>And follow to the end.<br/>',NULL,14534,14534);
INSERT INTO stanza VALUES('BF157','2','My all I have forsaken now,<br/>This blessed Christ to gain;<br/>Now life or death is no concern —<br/>What else can me restrain?<br/>To bring me wealth, ambition, fame —<br/>What can they offer me?<br/>My gracious Lord for me was poor,<br/>For Him I poor would be.<br/>',NULL,14535,14535);
INSERT INTO stanza VALUES('BF157','3','My precious Savior now I love,<br/>Him only would I please.<br/>For Him all gain a loss becomes,<br/>And comfort holds no ease.<br/>Thou art my comfort, gracious Lord!<br/>I''ve none in heav''n but Thee.<br/>And who but Thee is there on earth<br/>With whom I love to be?<br/>',NULL,14536,14536);
INSERT INTO stanza VALUES('BF157','4','Though loneliness and trials come,<br/>My grief''s I''d rise above,<br/>This only would I ask Thee, Lord;<br/>Surround me with Thy love!<br/>O gracious Lord, I now beseech,<br/>Guide me through every stage;<br/>Stand by and strengthen me to go<br/>Through this dark, evil age.<br/>',NULL,14537,14537);
INSERT INTO stanza VALUES('BF157','5','The world, the flesh, and Satan too,<br/>Do tempt my soul apace;<br/>Without Thy love and strength''ning power<br/>I may Thy name disgrace.<br/>The time, dear Lord, is running short;<br/>From earth my soul set free.<br/>When Thou dost come, I''ll sing with joy,<br/>Hallelujah to Thee!<br/>',NULL,14538,14538);
INSERT INTO stanza VALUES('BF158','1','In the church of Jesus there is love for you,<br/>Love most pure and tender, love most deep and true;<br/>Why should you be lonely, why for friendship sigh,<br/>When the church of Jesus has a full supply?<br/>',NULL,14539,14539);
INSERT INTO stanza VALUES('BF158','2','In the church of Jesus there is life for you,<br/>Warm as summer sunshine, sweet as morning dew;<br/>Why should you be fearful, why take anxious thought,<br/>Since the church of Jesus cares for those He bought?<br/>',NULL,14540,14540);
INSERT INTO stanza VALUES('BF158','3','In the church of Jesus there is work for you;<br/>Such as even angels might rejoice to do;<br/>Why stand idly sighing for some life work grand,<br/>While the church of Jesus seeks your reaping hand?<br/>',NULL,14541,14541);
INSERT INTO stanza VALUES('BF158','4','In the church of Jesus there is a place for you;<br/>Glorious, bright, and joyous, right and peaceful too;<br/>Why then like a wand''rer, roam with weary pace,<br/>If the church of Jesus holds for you a place.<br/>',NULL,14542,14542);
INSERT INTO stanza VALUES('BF159','1','Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>',NULL,14543,14543);
INSERT INTO stanza VALUES('BF159','2','They shall obtain gladness and joy;<br/>And sorrow and mourning shall flee away.<br/>(Repeat the first three lines)<br/>',NULL,14544,14544);
INSERT INTO stanza VALUES('BF160','1','Come arise early to feast on the Lord,<br/>Let''s come together to enjoy church life.<br/>Morning watch, come daily, say amen, spirit free.<br/>Whole day in His presence sweet.<br/>',NULL,14545,14545);
INSERT INTO stanza VALUES('BF160','chorus','Hallelujah! Lord''s with us.<br/>Hallelujah! Lord''s with us.<br/>Anywhere with joyful song,<br/>We enjoy church life.<br/>',NULL,14546,14546);
INSERT INTO stanza VALUES('BF160','2','Speak not of person, position or age,<br/>Let''s come together, Christ we testify.<br/>Share one to another, in love join together,<br/>As members of His Body.<br/>',NULL,14547,14547);
INSERT INTO stanza VALUES('BF160','chorus','Hallelujah! as members,<br/>Hallelujah! as members,<br/>Function loyally render,<br/>Glorious church life.<br/>',NULL,14548,14548);
INSERT INTO stanza VALUES('BF160','3','Jesus Christ is ours, He is also yours,<br/>Let''s come together to enjoy the Lord,<br/>In the church or at home, blessings we all enjoy.<br/>Hallelujah! O what joy!<br/>',NULL,14549,14549);
INSERT INTO stanza VALUES('BF160','chorus','Hallelujah! O what joy!<br/>Hallelujah! O what joy!<br/>Body''s riches I enjoy.<br/>Glorious church life.<br/>',NULL,14550,14550);
INSERT INTO stanza VALUES('BF160','4','Say, "Jesus is Lord" shout, "Hallelujah"<br/>Let''s come together to exhibit Christ.<br/>You sing hymn, I give praise, testify, all amen,<br/>How refreshing as we meet.<br/>',NULL,14551,14551);
INSERT INTO stanza VALUES('BF160','chorus','Hallelujah! ''tis so sweet,<br/>Hallelujah! ''tis so sweet,<br/>''Tis so living fresh, and rich,<br/>Glorious church life.<br/>',NULL,14552,14552);
INSERT INTO stanza VALUES('BF161','1','There are times and times again,<br/>When my love seems far away;<br/>The hours would stretch, the days turn gray;<br/>All the while, I know not how,<br/>In my darkest hour, He prays<br/>In the saints, oh, for my sake.<br/>',NULL,14553,14553);
INSERT INTO stanza VALUES('BF161','chorus','By a touch of His dear love,<br/>By the sound of His sweet voice,<br/>Whispers from above,<br/>Spoken through men of clay.<br/>And this world just fades away.<br/>(Let this world just fade away.)<br/>',NULL,14554,14554);
INSERT INTO stanza VALUES('BF161','2','Blinded soul, I cannot see<br/>What this world has done to me;<br/>My heart grows cold and life would bleed;<br/>Then He comes, knocks on my door,<br/>Through the saints—and there they stand<br/>With the Lord, oh, for my need!<br/>',NULL,14555,14555);
INSERT INTO stanza VALUES('BF162','1','Fade, fade each earthly joy;<br/>Jesus is mine.<br/>Break every tender tie;<br/>Jesus is mine.<br/>Dark is the wilderness,<br/>Earth has no resting place,<br/>Jesus alone can bless;<br/>Jesus is mine.<br/>',NULL,14556,14556);
INSERT INTO stanza VALUES('BF162','2','Tempt not my soul away;<br/>Jesus is mine.<br/>Here would I ever stay;<br/>Jesus is mine.<br/>Perishing things of clay,<br/>Born but for one brief day,<br/>Pass from my heart away;<br/>Jesus is mine.<br/>',NULL,14557,14557);
INSERT INTO stanza VALUES('BF162','3','Farewell, ye dreams of night;<br/>Jesus is mine.<br/>Lost in this dawning bright;<br/>Jesus is mine.<br/>All that my soul has tried<br/>Left but a dismal void;<br/>Jesus has satisfied;<br/>Jesus is mine.<br/>',NULL,14558,14558);
INSERT INTO stanza VALUES('BF162','4','Farewell, mortality;<br/>Jesus is mine.<br/>Welcome eternity;<br/>Jesus is mine.<br/>Welcome, O Loved and Blest,<br/>Welcome, sweet scenes of rest,<br/>Welcome, my Savior''s breast;<br/>Jesus is mine.<br/>',NULL,14559,14559);
INSERT INTO stanza VALUES('BF163','1','Has the wine run dry so soon?<br/>I have barely tasted it;<br/>Long before my tongue has quenched its thirst,<br/>Has the wine run dry?<br/>',NULL,14560,14560);
INSERT INTO stanza VALUES('BF163','2','I Have spent my final dime<br/>On the thing I thought would last,<br/>But as soon as I held it, it slipped away,<br/>Now I''m still so dry.<br/>',NULL,14561,14561);
INSERT INTO stanza VALUES('BF163','3','I Have climbed the highest peak;<br/>Took me twenty years to train;<br/>As I reached the top, I looked around and all I saw:<br/>Vanity, that''s all.<br/>',NULL,14562,14562);
INSERT INTO stanza VALUES('BF163','4','I Have probed the greatest minds,<br/>I''ve believed in ev''ry cause,<br/>But my heart won''t hear philosophy or reasonings,<br/>Left again dissatisfied.<br/>',NULL,14563,14563);
INSERT INTO stanza VALUES('BF163','5','Took me too, too long to see<br/>That this world''s all vanity;<br/>I''ve been through too much to just pretend it''s all okay;<br/>Give me reality.<br/>',NULL,14564,14564);
INSERT INTO stanza VALUES('BF163','6','In my deepest, darkest night,<br/>On my knees I cried aloud,<br/>Someone came to me, He changed my death to eternal life,<br/>Gave me meaning, reason to live.<br/>',NULL,14565,14565);
INSERT INTO stanza VALUES('BF163','7','I will call upon His name,<br/>I will draw this well and drink;<br/>When I call His name, Jesus Lord, the waters flow;<br/>That''s the name I love.<br/>',NULL,14566,14566);
INSERT INTO stanza VALUES('BF163','8','All this time it was just Him,<br/>He has saved the best for last;<br/>Now I''ve finally found the wine that won''t run dry,<br/>And He''s the sweetest wine of all.<br/>',NULL,14567,14567);
INSERT INTO stanza VALUES('BF164','1','Out of my bondage, sorrow, and night,<br/>Jesus, I come!  Jesus, I come!<br/>Into Thy freedom, gladness, and light,<br/>Jesus, I come to Thee!<br/>Out of my sickness into Thy health,<br/>Out of my want and into Thy wealth,<br/>Out of my sin and into Thyself,<br/>Jesus, I come to Thee!<br/>',NULL,14568,14568);
INSERT INTO stanza VALUES('BF164','2','Out of my shameful failure and loss,<br/>Jesus, I come!  Jesus, I come!<br/>Into the glorious gain of Thy cross,<br/>Jesus, I come to Thee!<br/>Out of earth''s sorrows into Thy balm,<br/>Out of life''s storm and into Thy calm,<br/>Out of distress to jubilant psalm,<br/>Jesus, I come to Thee!<br/>',NULL,14569,14569);
INSERT INTO stanza VALUES('BF164','3','Out of unrest and arrogant pride,<br/>Jesus, I come!  Jesus, I come!<br/>Into Thy blessed will to abide,<br/>Jesus, I come to Thee!<br/>Out of myself to dwell in Thy love,<br/>Out of despair into raptures above,<br/>Upward for aye on wings like a dove,<br/>Jesus, I come to Thee!<br/>',NULL,14570,14570);
INSERT INTO stanza VALUES('BF164','4','Out of the fear and dread of the tomb,<br/>Jesus, I come!  Jesus, I come!<br/>Into the joy and pleasure, Thine own,<br/>Jesus, I come to Thee!<br/>Out of the depths of ruin untold,<br/>Into the flock Thy love doth enfold,<br/>Ever Thy glorious face to behold,<br/>Jesus, I come to Thee!<br/>',NULL,14571,14571);
INSERT INTO stanza VALUES('BF165','1','Art thou hungering for the fullness<br/>Of the blessing Christ doth give?<br/>Longing now to learn the secret<br/>Of the life He bids thee live?<br/>In His word thine answer standeth,<br/>"Christ who is our Life" it saith;<br/>Open now thy heart, and trust Him,<br/>There to dwell, henceforth, by faith.<br/>',NULL,14572,14572);
INSERT INTO stanza VALUES('BF165','2','Christ, the Lord''s Anointed, reigning<br/>O''er the life He died to win,<br/>Daily shall reveal more fully<br/>His great power, without, within.<br/>What thou never could''st accomplish<br/>Shall His Spirit work through thee,<br/>While thy soul this witness beareth,<br/>''Tis not I, but Christ in me.<br/>',NULL,14573,14573);
INSERT INTO stanza VALUES('BF165','3','In Him dwelleth all God''s fullness,<br/>In Him thou art made complete;<br/>Rise, and claim thy heavenly birthright,<br/>Kneeling at thy Father''s feet.<br/>He will never disappoint thee,<br/>Praise Him that the gift is thine;<br/>Then go forth to live each moment<br/>On sufficiency divine.<br/>',NULL,14574,14574);
INSERT INTO stanza VALUES('BF165','4','Lord, I come, and simply resting<br/>On Thy faithful, changeless word,<br/>I believe the blood doth cleanse me,<br/>And that Christ is crowned Lord.<br/>Grant henceforth a ceaseless outflow<br/>Of Thy life and love through me;<br/>Reaching those who sit in darkness,<br/>Winning priceless souls to Thee.<br/>',NULL,14575,14575);
INSERT INTO stanza VALUES('BF166','1','Are You the One who came from heaven?<br/>The mighty God who suffered the curse of sin and died<br/>And they pierced Your side<br/>Rose, from the grave, You''re ever new<br/>You''ve sown in me the seed of life that grew<br/>From sinner, poor and blind<br/>To New Jerusalem!<br/>',NULL,14576,14576);
INSERT INTO stanza VALUES('BF166','chorus','I love You more<br/>With all my heart, with all my soul<br/>(Oh, Love divine)<br/>With all my strength, with all my mind<br/>Sweet, sweet repose<br/>',NULL,14577,14577);
INSERT INTO stanza VALUES('BF166','2','Are You the One my heart has known?<br/>Are You the One, my spirit has richly grown to love?<br/>Oh come, Beloved<br/>And with my lips, shall I confess<br/>That deep in You my heart found rest<br/>And peace as ocean''s depth?<br/>Oh, fill me with Your breath!<br/>',NULL,14578,14578);
INSERT INTO stanza VALUES('BF167','1','If the path I travel<br/>Lead me to the cross,<br/>If the way Thou choosest<br/>Lead to pain and loss,<br/>Let the compensation<br/>Daily, hourly, be<br/>Shadowless communion,<br/>Blessed Lord, with Thee.<br/>(repeat last two lines)<br/>',NULL,14579,14579);
INSERT INTO stanza VALUES('BF167','2','If there''s less of earth joy,<br/>Give, Lord, more of heaven.<br/>Let the spirit praise Thee,<br/>Though the heart be riven;<br/>If sweet earthly ties, Lord,<br/>Break at Thy decree,<br/>Let the tie that binds us,<br/>Closer, sweeter, be.<br/>',NULL,14580,14580);
INSERT INTO stanza VALUES('BF167','3','Lonely though the pathway,<br/>Cheer it with Thy smile;<br/>Be Thou my companion<br/>Through earth''s little while;<br/>Selfless may I live, Lord,<br/>By Thy grace to be<br/>Just a cleansed channel<br/>For Thy life through me.<br/>',NULL,14581,14581);
INSERT INTO stanza VALUES('BF168','1','Lord, I''m willing to spend myself,<br/>For the building of Thy Church now;<br/>My knowledge of Thee is shallow,<br/>So do my labor in Thee now.<br/>',NULL,14582,14582);
INSERT INTO stanza VALUES('BF168','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the Church''s supply.<br/>',NULL,14583,14583);
INSERT INTO stanza VALUES('BF168','2','The all-inclusive Christ''s in me,<br/>He is the source, He is the flow,<br/>Only by experiencing Him,<br/>There is quickening in the flow.<br/>',NULL,14584,14584);
INSERT INTO stanza VALUES('BF168','3','"To know Christ'''' is not a slogan,<br/>But in experience we will live,<br/>Enjoyment more, for Him give all,<br/>Experience deep, more to Him give.<br/>',NULL,14585,14585);
INSERT INTO stanza VALUES('BF168','4','Though not sitting in third heaven,<br/>I feel I''m raptured in spirit!<br/>Though I''m still living in the flesh,<br/>But to resurrection life heed.<br/>',NULL,14586,14586);
INSERT INTO stanza VALUES('BF168','5','I enjoy Him, He enjoys me,<br/>When I gain Him, He gains me too;<br/>We then have mutual enjoyment,<br/>And experiences enriched too.<br/>',NULL,14587,14587);
INSERT INTO stanza VALUES('BF168','6','To spend all, I need capital,<br/>Knowing that my treasure is Christ;<br/>All things to me, are all but dung,<br/>I want to gain more of this Christ.<br/>',NULL,14588,14588);
INSERT INTO stanza VALUES('BF169','1','God hath not promised skies always blue.<br/>Flower-strewn pathways all our lives through;<br/>God hath not promised sun without rain,<br/>Joy without sorrow, peace without pain.<br/>',NULL,14589,14589);
INSERT INTO stanza VALUES('BF169','chorus','But God hath promised strength for the day,<br/>Rest for the labor, light for the way,<br/>Grace for the trials, help from above,<br/>Unfailing sympathy, undying love.<br/>',NULL,14590,14590);
INSERT INTO stanza VALUES('BF169','2','God hath not promised we shall not know<br/>Toil and temptation, trouble and woe;<br/>He hath not told us we shall not bear<br/>Many a burden, many a care.<br/>',NULL,14591,14591);
INSERT INTO stanza VALUES('BF169','3','God hath not promised smooth roads and wide,<br/>Swift, easy travel, needing no guide;<br/>Never a mountain, rocky and steep,<br/>Never a river, turbid and deep.<br/>',NULL,14592,14592);
INSERT INTO stanza VALUES('BF170','1','Come and rejoice with me!<br/>For once my heart was poor,<br/>And I have found a treasury<br/>Of love, a boundless store.<br/>',NULL,14593,14593);
INSERT INTO stanza VALUES('BF170','2','Come and rejoice with me!<br/>I, once so sick at heart,<br/>Have met with One who knows my case,<br/>And knows the healing art.<br/>',NULL,14594,14594);
INSERT INTO stanza VALUES('BF170','3','Come and rejoice with me!<br/>For I was wearied sore,<br/>And I have found a mighty arm<br/>Which holds me evermore.<br/>',NULL,14595,14595);
INSERT INTO stanza VALUES('BF170','4','Come and rejoice with me!<br/>My feet so wide did roam,<br/>And One has brought me from afar,<br/>To find in Him my home.<br/>',NULL,14596,14596);
INSERT INTO stanza VALUES('BF170','5','Come and rejoice with me!<br/>For I have found a Friend<br/>Who knows my heart''s most secret depths,<br/>Yet loves me without end.<br/>',NULL,14597,14597);
INSERT INTO stanza VALUES('BF170','6','I knew not of His love;<br/>And He had loved so long,<br/>With love so faithful and so deep,<br/>So tender and so strong.<br/>',NULL,14598,14598);
INSERT INTO stanza VALUES('BF170','7','And now I know it all,<br/>Have heard and known His voice,<br/>And hear it still from day to day.<br/>Can I enough rejoice?<br/><br/>',NULL,14599,14599);
INSERT INTO stanza VALUES('BF171','1','O God, Thou art the source of life,<br/>Divine, and rich and free!<br/>As living water flowing out<br/>Unto eternity!<br/>In love Thou in the Son didst flow<br/>Among the human race;<br/>Thou dost as Spirit also flow<br/>Within us thru Thy grace.<br/>',NULL,14600,14600);
INSERT INTO stanza VALUES('BF171','2','Though we in sin and wickedness<br/>Went far from Thee apace,<br/>Yet in the Son Thou didst redeem,<br/>Bestowing life and grace.<br/>Though we have often slighted Thee,<br/>Thy Spirit often grieved,<br/>Yet Thou dost still as Spirit come<br/>As life to be received.<br/>',NULL,14601,14601);
INSERT INTO stanza VALUES('BF171','3','Thou as the Spirit in the Son<br/>Hast mingled heretofore;<br/>Thou wilt thru fellowship anoint<br/>And increase more and more.<br/>The love of God, the grace of Christ,<br/>The Spirit’s flowing free,<br/>Enable us God’s wealth to share<br/>Thru all eternity.<br/>',NULL,14602,14602);
INSERT INTO stanza VALUES('BF171','chorus','The Father, Son, and Spirit-one,<br/>So richly care for us;<br/>Thy love with one accord we sing<br/>And e’er would praise Thee thus.<br/>',NULL,14603,14603);
INSERT INTO stanza VALUES('BF172','1','O Jesus, Jesus, dearest Lord!<br/>Forgive me if I say,<br/>For very love, Thy sacred name<br/>A thousand times a day.<br/>',NULL,14604,14604);
INSERT INTO stanza VALUES('BF172','chorus','O Jesus, Lord, with me abide;<br/>I rest in Thee, whate''er betide;<br/>Thy gracious smile is my reward;<br/>I love, I love Thee, Lord!<br/>',NULL,14605,14605);
INSERT INTO stanza VALUES('BF172','2','I love Thee so I know not how<br/>My transports to control;<br/>Thy love is like a burning fire<br/>Within my very soul.<br/>',NULL,14606,14606);
INSERT INTO stanza VALUES('BF172','3','For Thou to me art all in all;<br/>My honor and my wealth;<br/>My heart''s desire, my body''s strength,<br/>My soul''s eternal health.<br/>',NULL,14607,14607);
INSERT INTO stanza VALUES('BF172','4','Burn, burn, O love, within my heart,<br/>Burn fiercely night and day,<br/>Till all the dross of earthly loves<br/>Is burned, and burned away.<br/>',NULL,14608,14608);
INSERT INTO stanza VALUES('BF172','5','O light in darkness, joy in grief,<br/>O heaven''s life on earth;<br/>Jesus, my love, my treasure, who<br/>Can tell what Thou art worth?<br/>',NULL,14609,14609);
INSERT INTO stanza VALUES('BF172','6','What limit is there to this love?<br/>Thy flight, where wilt Thou stay?<br/>On, on! our Lord is sweeter far<br/>Today than yesterday.<br/>',NULL,14610,14610);
INSERT INTO stanza VALUES('BF173','1','O what joy and rest — in His home I''m dwelling,<br/>Glorious church life — O how sweet.<br/>Breathing His Holy name, eat and drink His Word,<br/>For His glorious recovery.<br/>Walking, in His Light of life now we are all walking.<br/>Living, in the church of God now we are all living.<br/>His love preserves me,<br/>His light shines on me.<br/>In love all the members built in one.<br/>',NULL,14611,14611);
INSERT INTO stanza VALUES('BF174','1','It passeth knowledge, that dear love of Thine,<br/>My Savior, Jesus; yet this soul of mine<br/>Would of Thy love in all its breadth and length,<br/>Its height and depth, its everlasting strength,<br/>Know more and more.<br/>',NULL,14612,14612);
INSERT INTO stanza VALUES('BF174','2','It passeth telling, that dear love of Thine,<br/>My Savior, Jesus; yet these lips of mine<br/>Would fain proclaim to sinners, far and near,<br/>A love which can remove all guilty fear,<br/>And love beget.<br/>',NULL,14613,14613);
INSERT INTO stanza VALUES('BF174','3','It passeth praises, that dear love of Thine,<br/>My Savior, Jesus; yet this heart of mine<br/>Would sing that love, so full, so rich, so free,<br/>Which brings a rebel sinner, such as me,<br/>Nigh unto God.<br/>',NULL,14614,14614);
INSERT INTO stanza VALUES('BF174','4','But though I cannot sing, or tell, or know<br/>The fulness of Thy love, while here below,<br/>My empty vessel I may freely bring;<br/>O Thou, who art of love the living spring,<br/>My vessel fill.<br/>',NULL,14615,14615);
INSERT INTO stanza VALUES('BF174','5','I am an empty vessel—not one thought<br/>Or look of love to Thee I''ve ever brought;<br/>Yet I may come, and come again to Thee,<br/>With this the empty sinner''s only plea,<br/>Thou lovest me.<br/>',NULL,14616,14616);
INSERT INTO stanza VALUES('BF174','6','Oh, fill me, Jesus, Savior, with Thy love!<br/>Lead, lead me to the living fount above;<br/>Thither may I, in simple faith draw nigh,<br/>And never to another fountain fly,<br/>But unto Thee.<br/>',NULL,14617,14617);
INSERT INTO stanza VALUES('BF174','7','Lord Jesus, when Thee face to face I see,<br/>When on Thy lofty throne I sit with Thee,<br/>Then of Thy love, in all its breadth and length,<br/>Its height and depth, its everlasting strength,<br/>My soul shall sing.<br/>',NULL,14618,14618);
INSERT INTO stanza VALUES('BF175','1','Drawn to the Cross which Thou hast blest,<br/>With healing gifts for souls distrest,<br/>To find in Thee my Life, my Rest,<br/>Christ crucified, I come.<br/>Stained with the sins which I have wrought<br/>In word and deed and secret thought;<br/>For pardon which Thy Blood hath bought,<br/>Christ crucified, I come.<br/>',NULL,14619,14619);
INSERT INTO stanza VALUES('BF175','2','Weary of selfishness and pride,<br/>False pleasures gone, vain hopes denied,<br/>Deep in Thy wounds my shame to hide,<br/>Christ crucified, I come.<br/>Thou knowest all my griefs and fears,<br/>Thy grace abused, my misspent years;<br/>Yet now to Thee, for cleansing tears,<br/>Christ crucified, I come.<br/>',NULL,14620,14620);
INSERT INTO stanza VALUES('BF175','3','I would not, if I could, conceal<br/>The ills which only Thou canst heal;<br/>So to the Cross, where sinners kneel,<br/>Christ crucified, I come.<br/>Wash me, and take away each stain,<br/>Let nothing of my sin remain;<br/>For cleansing, though it be through pain,<br/>Christ crucified, I come.<br/>',NULL,14621,14621);
INSERT INTO stanza VALUES('BF175','4','To share with Thee Thy life divine,<br/>Thy very likeness to be mine,<br/>Since Thou hast made my nature Thine,<br/>Christ crucified, I come.<br/>To be what Thou wouldst have me be,<br/>Accepted, sanctified in Thee,<br/>Through what Thy grace shall work in me,<br/>Christ crucified, I come.<br/>',NULL,14622,14622);
INSERT INTO stanza VALUES('BF176','1','I cannot breathe enough of Thee,<br/>O gentle breeze of love;<br/>More fragrant than the myrtle tree<br/>The Henna-flower is to me,<br/>The Balm of Heaven above.<br/>',NULL,14623,14623);
INSERT INTO stanza VALUES('BF176','chorus','I cannot yield enough to Thee,<br/>My Savior, Master, Friend;<br/>I do not wish to go out free,<br/>But ever, always, willingly,<br/>To serve Thee to the end.<br/>',NULL,14624,14624);
INSERT INTO stanza VALUES('BF176','2','I cannot gaze enough on Thee,<br/>Thou Fairest of the Fair;<br/>My heart is filled with ecstasy,<br/>As in Thy face of radiancy<br/>I see such beauty there.<br/>',NULL,14625,14625);
INSERT INTO stanza VALUES('BF176','3','I cannot sing enough of Thee,<br/>The sweetest name on earth;<br/>A note so full of melody<br/>Comes from my heart so joyously,<br/>And fills my soul with mirth.<br/>',NULL,14626,14626);
INSERT INTO stanza VALUES('BF176','4','I cannot speak enough of Thee,<br/>I have so much to tell;<br/>Thy heart it beats so tenderly<br/>As Thou dost draw me close to Thee,<br/>And whisper, "All is well."<br/>',NULL,14627,14627);
INSERT INTO stanza VALUES('BF177','1','Something every heart is loving:<br/>If not Jesus, none can rest;<br/>Lord, my heart to Thee is given;<br/>Take it, for it loves Thee best.<br/>',NULL,14628,14628);
INSERT INTO stanza VALUES('BF177','2','Thus I cast the world behind me;<br/>Jesus most beloved shall be;<br/>Beauteous more than all things beauteous,<br/>He alone is joy to me.<br/>',NULL,14629,14629);
INSERT INTO stanza VALUES('BF177','3','Bright with all eternal radiance<br/>Is the glory of Thy face;<br/>Thou art loving, sweet, and tender,<br/>Full of pity, full of grace.<br/>',NULL,14630,14630);
INSERT INTO stanza VALUES('BF177','4','When I hated, Thou didst love me,<br/>Shedd''st for me Thy precious blood;<br/>Still Thou lovest, lovest ever,<br/>Shall I not love Thee, my God?<br/>',NULL,14631,14631);
INSERT INTO stanza VALUES('BF177','5','Keep my heart still faithful to Thee,<br/>That my earthly life may be<br/>But a shadow to that glory<br/>of my hidden life in Thee.<br/>',NULL,14632,14632);
INSERT INTO stanza VALUES('BF178','1','Lovers of Christ in His ascension<br/>Enjoy the riches of His life.<br/>She becomes His private garden<br/>With its fountain, fruit and spice.<br/>Christ is hers and she is Christ''s dear love.<br/>',NULL,14633,14633);
INSERT INTO stanza VALUES('BF178','2','She is as beautiful as Tirzah<br/>As lovely as Jerusalem.<br/>Through her living in Christ''s ascension<br/>Her dear heart is now His home.<br/>She''s become the sanctuary of God.<br/>',NULL,14634,14634);
INSERT INTO stanza VALUES('BF178','3','Who is this woman I am seeing?<br/>Shining forth as the moon and sun.<br/>She is absolutely heavenly,<br/>From the old creation free;<br/>Overcoming all to live within the veil.<br/>',NULL,14635,14635);
INSERT INTO stanza VALUES('BF178','4','An army terrible with banners<br/>Christ''s lovers overcome to be.<br/>Those attracted by His beauty,<br/>Fully trusting in His power.<br/>Her romance is now the dances of two camps.<br/>',NULL,14636,14636);
INSERT INTO stanza VALUES('BF178','5','The Shulammite, His duplication,<br/>His counterpart has now become.<br/>She''s the same in life and nature,<br/>His expression to the full;<br/>Consummated as the New Jerusalem.<br/>',NULL,14637,14637);
INSERT INTO stanza VALUES('BF179','1','I have fought the good fight;<br/>I have finished the course;<br/>I have fought the good fight;<br/>I have kept the faith.<br/>',NULL,14638,14638);
INSERT INTO stanza VALUES('BF179','2','Henceforth there is laid up for me<br/>The crown of righteousness,<br/>Which the Lord, the righteous Judge,<br/>Will recompense me in that day,<br/>And not only me, but also all those<br/>Who have loved His appearing.<br/>',NULL,14639,14639);
INSERT INTO stanza VALUES('BF180','1','I love God because He loved me long before the world began.<br/>I love God because He knew my destiny.<br/>I love God because He made me part of His eternal plan.<br/>I love God because He first loved me.<br/>',NULL,14640,14640);
INSERT INTO stanza VALUES('BF180','chorus','I love Him for all the things He''s done for me.<br/>I love Him for all that He is, all that He is to me.<br/>But, most of all, I love Him as the Spirit<br/>Who deep within my spirit lives.<br/>',NULL,14641,14641);
INSERT INTO stanza VALUES('BF180','2','I love God because He came in time to be the Son of Man.<br/>I love God because He gave Himself for me.<br/>I love God because He conquered death that I might live in Him.<br/>I love God because He first loved me.<br/>',NULL,14642,14642);
INSERT INTO stanza VALUES('BF180','3','I love God because He''s processed now to be my life within.<br/>I love God because He is transforming me.<br/>I love God because He''s building up the New Jerusalem.<br/>I love God because He still loves me.<br/>',NULL,14643,14643);
INSERT INTO stanza VALUES('BF181','1','Wherever you go I will go;<br/>Wherever you dwell I will dwell;<br/>Your people will be my people;<br/>And your God will be my God.<br/>(repeat)<br/>',NULL,14644,14644);
INSERT INTO stanza VALUES('BF181','2','Wherever you die, I will die,<br/>And there will I be buried.<br/>Jehovah do to me and more as well<br/>If anything but death parts me from you;<br/>Jehovah do to me and more as well<br/>If anything but death parts me from you.<br/>',NULL,14645,14645);
INSERT INTO stanza VALUES('BF182','1','I''m so attracted by Your love,<br/>And I''m drawn by You in Your sweetness<br/>To pursue after You for my full satisfaction.<br/>',NULL,14646,14646);
INSERT INTO stanza VALUES('BF182','chorus','I''m in Love, I''m in love, I''m in love<br/>with the most beautiful One.<br/>(Repeat Chorus)<br/>',NULL,14647,14647);
INSERT INTO stanza VALUES('BF182','2','I''m captivated by Your name, and I''m charmed by You<br/>With You fragrance covering me; I was gained<br/>As You kissed me with Your kisses.<br/>',NULL,14648,14648);
INSERT INTO stanza VALUES('BF182','chorus','I''m in love, I''m in love, I''m in love<br/>With the most affectionate One.<br/>',NULL,14649,14649);
INSERT INTO stanza VALUES('BF182','3','I''m fellowshipping in Your love, and rejoicing in You<br/>In Your chambers I enjoy our sweet love<br/>For the Church, Your satisfaction.<br/>',NULL,14650,14650);
INSERT INTO stanza VALUES('BF182','chorus','I''m in love, I''m in love, I''m in love<br/>with the most intimate One.<br/>I''m in love!<br/>',NULL,14651,14651);
INSERT INTO stanza VALUES('BF183','1','Oh Lord, break through.<br/>Lord, gain in me.<br/>Lord, I want You my all to be.<br/>Oh Lord, break through.<br/>Lord, gain in me.<br/>Oh Lord, replace me totally.<br/>',NULL,14652,14652);
INSERT INTO stanza VALUES('BF183','chorus','Lord, I surrender my all to You<br/>Right now I open to let You flow through.<br/>',NULL,14653,14653);
INSERT INTO stanza VALUES('BF183','2','I open now,<br/>With all my heart.<br/>Lord, more and more possess each part.<br/>Oh Lord, I pray<br/>Subdue my soul.<br/>Until You have the full control.<br/>',NULL,14654,14654);
INSERT INTO stanza VALUES('BF183','3','Oh Lord, make home<br/>In all my heart.<br/>Lord, saturate and fill each part.<br/>Oh Lord, make home<br/>In all our heart.<br/>Lord, constitute Your counterpart.<br/>',NULL,14655,14655);
INSERT INTO stanza VALUES('BF183','4','Lord, I believe<br/>You can get through.<br/>I give myself again to You.<br/>Together we lay hold of You.<br/>''Til we are Your expression true.<br/>',NULL,14656,14656);
INSERT INTO stanza VALUES('BF184','1','Pursue Him and know Him; be found in Him.<br/>Count all things loss for Him.<br/>Just gain Him, obtain Him; lay hold of Him.<br/>It''s Christ the central vision.<br/>',NULL,14657,14657);
INSERT INTO stanza VALUES('BF184','chorus','Forgetting the things which are behind,<br/>Press on, pursue with this mind.<br/>By any means each hour now redeem;<br/>Stretch forth, lay hold of Him.<br/>',NULL,14658,14658);
INSERT INTO stanza VALUES('BF184','2','Pursue Him and seize Him, Christ the supreme.<br/>Just love this precious Person.<br/>Forgetting and leaving all other things,<br/>Love Him with your whole being.<br/>',NULL,14659,14659);
INSERT INTO stanza VALUES('BF184','3','Christ now is my center and reality,<br/>My life for eternity.<br/>All things are just dung compared to Him,<br/>So love and just gain Him!<br/>',NULL,14660,14660);
INSERT INTO stanza VALUES('BF185','1','"Within the Veil": be this, belov''d, thy portion,<br/>Within the secret of thy Lord to dwell;<br/>Beholding Him, until thy face His glory,<br/>Thy life His love, thy lips His praise shall tell.<br/>',NULL,14661,14661);
INSERT INTO stanza VALUES('BF185','chorus','"Within the Veil," for only as thou gazest<br/>Upon the matchless beauty of His face,<br/>Canst thou become a living revelation<br/>Of His great heart of love, His untold grace.<br/>',NULL,14662,14662);
INSERT INTO stanza VALUES('BF185','chorus','Sisters:		Brothers:<br/>Lord I come	Open me<br/>Seeking You	Turn my heart<br/>bring me in	Speak to me<br/>to Your light	In Your word<br/>You''re so rich	Lord You are<br/>You''re so full	All I need<br/>Wonderful	I love You<br/>My delight	Precious Lord<br/>',NULL,14663,14663);
INSERT INTO stanza VALUES('BF185','2','"Within the Veil," His fragrance poured upon thee,<br/>Without the Veil, that fragrance shed abroad;<br/>"Within the Veil," His hand shall tune the music<br/>Which sounds on earth the praises of Thy Lord.<br/>',NULL,14664,14664);
INSERT INTO stanza VALUES('BF185','chorus','"Within the Veil," thy spirit deeply anchored,<br/>Thou walkest calm above a world of strife;<br/>"Within the Veil," thy soul with Him united,<br/>Shall live on earth His resurrection life.<br/>',NULL,14665,14665);
INSERT INTO stanza VALUES('BF186','1','The full ministry of Christ is carried out in three stages<br/>For the fulfillment of God''s eternal economy.<br/>',NULL,14666,14666);
INSERT INTO stanza VALUES('BF186','2','In the first stage of incarnation, to bring God into man,<br/>To express God in humanity and to accomplish<br/>His judicial redemption.<br/>',NULL,14667,14667);
INSERT INTO stanza VALUES('BF186','3','In the second stage of inclusion,<br/>To be begotten as God''s firstborn Son,<br/>To become the life-giving Spirit, and<br/>To regenerate the believers for His Body.<br/>',NULL,14668,14668);
INSERT INTO stanza VALUES('BF186','4','In the third stage of intensification,<br/>To intensify His organic salvation,<br/>To produce the overcomers, and<br/>To consummate the New Jerusalem.<br/>',NULL,14669,14669);
INSERT INTO stanza VALUES('BF186','5','Incarnation, inclusion, intensification...<br/>',NULL,14670,14670);
INSERT INTO stanza VALUES('BF187','1','I want to be filled with the Triune God<br/>He makes me vital<br/>I want to be filled with Him.<br/>I want to be filled with the Triune God<br/>He makes me vital<br/>I want to be filled with Him.<br/>',NULL,14671,14671);
INSERT INTO stanza VALUES('BF187','2','So I will drink, drink, drink, drink, drink,<br/>The living water<br/>And I will eat, eat, eat, eat, eat,<br/>The tree of life.<br/>And I will call upon His name —<br/>O Lord Jesus!<br/>I want to be filled up, up, up —<br/>With Him!<br/>',NULL,14672,14672);
INSERT INTO stanza VALUES('BF188','1','All Scripture is God-breathed and profitable for teaching;<br/>For reproof for correction, for instruction in righteousness.<br/>That the man of God may be complete<br/>Fully equipped for every good work.<br/>',NULL,14673,14673);
INSERT INTO stanza VALUES('BF189','1','There''s a race for us to run — Hallelujah,<br/>And a way for us the race to win.<br/>To all those who have begun — Hallelujah,<br/>God has spoken, "Look away to HIm."<br/>',NULL,14674,14674);
INSERT INTO stanza VALUES('BF189','chorus','Look away! O look away!<br/>Look to Jesus now today!<br/>Look away from everything unto Jesus,<br/>Look away from everything to Him!<br/>',NULL,14675,14675);
INSERT INTO stanza VALUES('BF189','2','Look away from all around — Hallelujah,<br/>Look away from all the strifes and dins;<br/>Look away where peace is found — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,14676,14676);
INSERT INTO stanza VALUES('BF189','3','Look away from fickle soul — Hallelujah,<br/>Look away from failing self within;<br/>Look away toward the goal — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,14677,14677);
INSERT INTO stanza VALUES('BF189','4','Look away from all the past — Hallelujah,<br/>Look away from both the good and sin;<br/>To the living One hold fast — Hallelujah,<br/>Look away from everything to Him.<br/>',NULL,14678,14678);
INSERT INTO stanza VALUES('BF189','5','Look away into His face — Hallelujah,<br/>He Who''ll finish what He did begin.<br/>O what grace to run the race — Hallelujah —<br/>We obtain by looking off to Him.<br/>',NULL,14679,14679);
INSERT INTO stanza VALUES('BF190','1','The Bible is a romance<br/>In the most holy sense:<br/>God and His chosen people<br/>In love it so presents.<br/>This universal couple<br/>Through it is displayed;<br/>God in Christ is the Bridegroom,<br/>His saints, the Bride, portrayed.<br/>',NULL,14680,14680);
INSERT INTO stanza VALUES('BF190','2','Through shadows, types, and figures<br/>God''s deepest thought is known;<br/>As typified by Adam,<br/>The Husband, Christ is shown.<br/>A rib brought forth from Adam<br/>Reveals the source of life<br/>By which God built a woman<br/>Eve, as the church, His wife.<br/>',NULL,14681,14681);
INSERT INTO stanza VALUES('BF190','3','To be His people''s Husband,<br/>To take them as His wife.<br/>This is what God desires<br/>To live in a marriage life.<br/>Their sacrifice and worship<br/>Alone could not content;<br/>But with them to be married<br/>Was God''s foremost intent.<br/>',NULL,14682,14682);
INSERT INTO stanza VALUES('BF190','4','This romance is the finest<br/>As seen in Song of Songs;<br/>For her Beloved''s kisses<br/>His seeking lover longs.<br/>Love''s work in her produces<br/>No person of her own,<br/>But she becomes the City,<br/>Her Person, Christ alone.<br/>',NULL,14683,14683);
INSERT INTO stanza VALUES('BF190','5','Christ is our coming Bridegroom;<br/>We are the Church, His Bride,<br/>Redeemed, regenerated,<br/>The issue of His side,<br/>In source, in life, in nature<br/>And person fully one,<br/>His counterpart forever<br/>The New Jerusalem.<br/>',NULL,14684,14684);
INSERT INTO stanza VALUES('BF191','1','O there''s One in me who<br/>Is the most lovely One<br/>In the whole universe<br/>I just love Him.<br/>He has made me fall in love<br/>With Him more and more each day;<br/>And for now that I''m in love<br/>I''ll always stay.<br/>',NULL,14685,14685);
INSERT INTO stanza VALUES('BF191','chorus','For my Jesus<br/>Has captured my heart.<br/>He has wrecked me with all He can impart.<br/>He drew me to Himself,<br/>Now I love nothing else.<br/>His beauty, love and charm won my heart.<br/>',NULL,14686,14686);
INSERT INTO stanza VALUES('BF191','2','As the days go on and on<br/>There''s a hold that is so strong.<br/>A tide floods all my being —<br/>For I''m in love.<br/>There''s a face I long to see<br/>Whose arms will embrace me.<br/>As I rest in this sweet place<br/>I love Him more and more.<br/>',NULL,14687,14687);
INSERT INTO stanza VALUES('BF192','1','Lord, I give myself to You right now.<br/>I want to be occupied with You.<br/>I leave all else behind<br/>And concentrate my being on You alone.<br/>Lord, You are my focus, You are my goal.<br/>Lord, I give myself to You right now.<br/>',NULL,14688,14688);
INSERT INTO stanza VALUES('BF193','1','In the Lord''s recovery,<br/>God has chosen us to be<br/>Faithful stewards in His sight,<br/>Who know His heart''s delight.<br/>',NULL,14689,14689);
INSERT INTO stanza VALUES('BF193','chorus','We''re the servants of the Lord,<br/>To His purpose we are called;<br/>In His house as stewards we<br/>Caring for His economy.<br/>',NULL,14690,14690);
INSERT INTO stanza VALUES('BF193','2','"Lord, reveal Thyself to me,<br/>Knowing Thee subjectively;<br/>Thy desires, Thy will and goal,<br/>To Thee I give my all."<br/>',NULL,14691,14691);
INSERT INTO stanza VALUES('BF193','3','In our spirit we abide,<br/>All our needs He would provide;<br/>In the church life we apply<br/>The Christ Who satisfies.<br/>',NULL,14692,14692);
INSERT INTO stanza VALUES('BF193','4','Now His riches we supply<br/>To the saints we''d edify;<br/>At His purpose we''d arrive,<br/>To build up His dear Bride.<br/>',NULL,14693,14693);
INSERT INTO stanza VALUES('BF194','1','It is God''s commandment,<br/>And it is His desire,<br/>That His people call,<br/>Call upon His name.<br/>It''s the joyful way,<br/>The joyful way to drink<br/>From the fountain of<br/>God''s rich salvation.<br/>',NULL,14694,14694);
INSERT INTO stanza VALUES('BF194','2','Calling is the way to<br/>Delight oneself in God.<br/>That is to enjoy Him,<br/>Enjoy the Lord our God.<br/>Hence, we, as God''s people,<br/>Must daily call on Him.<br/>This must be our practice<br/>For God''s jubilee.<br/>',NULL,14695,14695);
INSERT INTO stanza VALUES('BF195','1','Great is the Lord, and greatly to be praised,<br/>In the city of our God,<br/>In the mountain of His holiness.<br/>Beautiful in elevation, the joy of the whole earth,<br/>Is mount Zion, on the sides of the north,<br/>The city of the great King.<br/>Is mount Zion, on the sides of the north,<br/>The city of the great King.<br/>',NULL,14696,14696);
INSERT INTO stanza VALUES('BF196','1','Now the Lord is the Spirit — that''s how<br/>He can get inside of you right now.<br/>It''s so easy to be filled with Him.<br/>He''s made it really simple.<br/>One, two, three —<br/>That''s how easy it can be.<br/>',NULL,14697,14697);
INSERT INTO stanza VALUES('BF196','chorus','O Lord! Amen!<br/>That''s the way to let Him in.<br/>Hallelujah! I love to hear it.<br/>He who is joined to the Lord is one spirit.<br/>',NULL,14698,14698);
INSERT INTO stanza VALUES('BF196','2','Now the Lord is the living air;<br/>You can breathe Him in anywhere —<br/>Anytime of day, whenever you please.<br/>He''s made it really easy.<br/>O Lord! Amen!<br/>Let''s sing it again.<br/>',NULL,14699,14699);
INSERT INTO stanza VALUES('BF196','3','Now the Lord lives inside of me.<br/>And He''s filling me constantly.<br/>Yes, He''s filling up every gap.<br/>He makes me really happy.<br/>I''m so happy!<br/>Hallelujah! Taste and see!<br/>',NULL,14700,14700);
INSERT INTO stanza VALUES('BF197','chorus','Whither shall I go from Thy Spirit?<br/>And whither shall I flee from Thy presence?<br/>',NULL,14701,14701);
INSERT INTO stanza VALUES('BF197','1','If I ascend up into the heavens<br/>Thou art there;<br/>Or if I make my bed in Sheol, behold<br/>Thou art there;<br/>',NULL,14702,14702);
INSERT INTO stanza VALUES('BF197','2','If I take the wings of the dawn and dwell<br/>In the uttermost parts of the sea, behold<br/>Thou art there;<br/>',NULL,14703,14703);
INSERT INTO stanza VALUES('BF197','3','Even there shall Thy hand lead me,<br/>And even there Thy right hand shall hold me,<br/>Behold, Thou art there.<br/>',NULL,14704,14704);
INSERT INTO stanza VALUES('BF198','chorus','We work together with God by a life;<br/>We work together with God by a life:<br/>All-sufficient,<br/>All-mature;<br/>',NULL,14705,14705);
INSERT INTO stanza VALUES('BF198','1','(Brothers)	  Able to fit<br/>(Sisters)	  All situations,<br/>(Brothers)	  Able to endure<br/>(Sisters) 	  Any kind of treatment,<br/>(All)	  To accept any kind of environment<br/>(Brothers)	  All-fitting life!<br/>',NULL,14706,14706);
INSERT INTO stanza VALUES('BF198','2','Able to work<br/>In any condition,<br/>To take any kind<br/>Of opportunity<br/>For the carrying out of our ministry<br/>All-fitting life!<br/>',NULL,14707,14707);
INSERT INTO stanza VALUES('BF198','chorus','We work together with God by a life,<br/>We work together with God by a life,<br/>All-sufficient,<br/>All-mature;<br/>All-sufficient<br/>All-fitting life.<br/>',NULL,14708,14708);
INSERT INTO stanza VALUES('BF199','1','The gift of righteousness<br/>Is measured in abundance.<br/>The depth of His love I''ll never understand.<br/>His love reaches me and you<br/>His mercy goes farther too.<br/>The one on the throne of God<br/>Is called the Lamb.<br/>',NULL,14709,14709);
INSERT INTO stanza VALUES('BF199','chorus','So why not open up<br/>And call his name "O Lord!"<br/>Find your spirit<br/>Where His grace has been outpoured<br/>Call His name; taste His grace<br/>Exercise before His face<br/>He''s longing and yearning,<br/>He''s hoping and waiting,<br/>He''s ever desiring for you to turn to Him.<br/>',NULL,14710,14710);
INSERT INTO stanza VALUES('BF199','2','He knows your deepest thought<br/>Your every situation<br/>He understands your heart<br/>He knows your history<br/>There''s nothing in His way<br/>He''s just waiting for you to say,<br/>"Lord Jesus, my wandering heart<br/>I give to Thee."<br/>',NULL,14711,14711);
INSERT INTO stanza VALUES('BF200','1','Since I open my heart to You,<br/>From the first time until now;<br/>I''m realizing more how small I am,<br/>How little I know how much I need<br/>In You to grow.<br/>',NULL,14712,14712);
INSERT INTO stanza VALUES('BF200','chorus','And Jesus how great You are.<br/>O Jesus most excellent by far,<br/>Only You can satisfy;<br/>Lord Your name be magnified,<br/>O Jesus how excellent You are.<br/>',NULL,14713,14713);
INSERT INTO stanza VALUES('BF200','2','So day by day help me open more,<br/>Lord, dig away all that blocks You.<br/>Drop by drop may Your life in me increase;<br/>Till just You are in view,<br/>I pursue.<br/>',NULL,14714,14714);
INSERT INTO stanza VALUES('BF201','1','Praise the Lord! The God of Glory<br/>Who appeared to Abraham<br/>Has appeared to us in spirit<br/>For His purpose and His plan!<br/>God of Glory, God of Glory.<br/>Do appear to us today.<br/>Saturate and permeate us<br/>Till You fully have Your way.<br/>',NULL,14715,14715);
INSERT INTO stanza VALUES('BF201','2','Once we were in old Chaldea.<br/>Worshipping the idols there;<br/>But the God of Glory called us,<br/>Saved us all from Satan''s snare.<br/>Get out, get out, from Chaldea.<br/>From that evil foreign land.<br/>Come in, come in, to the good land.<br/>Christ, the church, the one new man.<br/>',NULL,14716,14716);
INSERT INTO stanza VALUES('BF201','3','With the calling comes the promise<br/>Of the kingdom life on earth.<br/>This becomes our strength and motive<br/>To get out of all the dearth!<br/>Lord, we''re crossing every river —<br/>For this You must call on us,<br/>Till Your kingdom and expression<br/>On this earth are fully come.<br/>',NULL,14717,14717);
INSERT INTO stanza VALUES('BF201','4','This is now the highest gospel<br/>To those still in Chaldea''s land —<br/>Leave the fallen situation,<br/>You''ve been chosen for God''s plan,<br/>God of Glory, God of Glory,<br/>Do appear to us each day,<br/>Call us out into Your building,<br/>Your desire on earth today.<br/>',NULL,14718,14718);
INSERT INTO stanza VALUES('BF202','1','Oh, the life that dwells within me<br/>Is the Spirit of my Lord.<br/>As the Spirit He''s the water<br/>And my strength comes from His Word.<br/>Like a spring of living water<br/>My whole being saturates.<br/>Then the fruit of lips confess His Name,<br/>A sacrifice of praise.<br/>',NULL,14719,14719);
INSERT INTO stanza VALUES('BF202','chorus','To express the Lord, this is His desire;<br/>To express the Lord, all the He requires;<br/>To express the Lord, Who abides in me;<br/>To express the Lord, so the world can see.<br/>',NULL,14720,14720);
INSERT INTO stanza VALUES('BF202','2','Like a spring of living water<br/>My whole being saturates.<br/>Then, the fruit of lips confess His Name,<br/>A sacrifice of praise.<br/>Oh, what freshness we experience<br/>Of this Living One each day.<br/>We contain Him and express Him,<br/>And through us He is displayed.<br/>',NULL,14721,14721);
INSERT INTO stanza VALUES('BF203','1','Oh tell me, what''s the key<br/>To build the Body?<br/>How to be deified,<br/>The Body realize?<br/>',NULL,14722,14722);
INSERT INTO stanza VALUES('BF203','chorus','Eat the hidden manna —<br/>Get God into you,<br/>''Cause when God gets into you,<br/>You get into God!<br/>',NULL,14723,14723);
INSERT INTO stanza VALUES('BF203','2','Our God is ent''rable,<br/>And He''s enjoyable,<br/>Our Christ — He is the way,<br/>We eat Him ev''ry day.<br/>',NULL,14724,14724);
INSERT INTO stanza VALUES('BF203','3','Center of centers ''tis,<br/>The hidden manna is<br/>Our deepest life supply;<br/>How He does satisfy!<br/>',NULL,14725,14725);
INSERT INTO stanza VALUES('BF203','4','Don''t trust the circumstance,<br/>For it is just the chance.<br/>To get more God in you,<br/>Become Him through and through!<br/>',NULL,14726,14726);
INSERT INTO stanza VALUES('BF203','5','Spend time alone with Him,<br/>Just love Him, talk to Him;<br/>By this we''re deified<br/>And we become His Bride!<br/>',NULL,14727,14727);
INSERT INTO stanza VALUES('BF204','1','Nothing can content me more,<br/>Than Jesus in the morning.<br/>Echoing the hallways of my heart.<br/>My eyes from darkness clearly see,<br/>The love within His smile, for me.<br/>It''s then I know the reason for my life.<br/>',NULL,14728,14728);
INSERT INTO stanza VALUES('BF204','chorus','Jesus, You''re my reason for being here.<br/>Oh, it''s so clear; so I sing.<br/>',NULL,14729,14729);
INSERT INTO stanza VALUES('BF204','2','No greater joy can be for me,<br/>Than turning to Jesus.<br/>When the shadows of the day<br/>Begin to haunt me,<br/>His soft, warm Spirit spreads throughout,<br/>Quenching all my fear and doubt.<br/>Jesus is the All-inclusive Love.<br/>',NULL,14730,14730);
INSERT INTO stanza VALUES('BF205','1','Love suffers long. Love is kind; it is not jealous.<br/>Love does not brag and is not puffed up.<br/>Love suffers long. Love is kind; it is not jealous.<br/>Love does not brag and is not puffed up.<br/>',NULL,14731,14731);
INSERT INTO stanza VALUES('BF205','2','It does not behave unbecomingly;<br/>And does not seek its own things;<br/>It is not provoked and does not take account of evil;<br/>It does not rejoice because of unrighteousness,<br/>But rejoices with the truth.<br/>',NULL,14732,14732);
INSERT INTO stanza VALUES('BF205','3','It covers all things, believes all things,<br/>Hopes all things, endures all things.<br/>Love never falls away, Love never falls away,<br/>Love never falls away, Love never falls away.<br/>',NULL,14733,14733);
INSERT INTO stanza VALUES('BF206','chorus','Lord You revealed Yourself to me,<br/>And showed me Your purpose.<br/>To have a church as Your house,<br/>So You can mingle all that You are.<br/>',NULL,14734,14734);
INSERT INTO stanza VALUES('BF206','1','Though I''m blinded by self and flesh<br/>But You, dear Lord, has chosen me,<br/>As a vessel to contain You<br/>And express You till You come back.<br/>',NULL,14735,14735);
INSERT INTO stanza VALUES('BF206','2','Forgive me Lord, I''m open to You<br/>Fill me more and more each day,<br/>Fill me with the saints in love<br/>And keep us running towards the prize.<br/>',NULL,14736,14736);
INSERT INTO stanza VALUES('BF206','3','Lord keep me growing and functioning<br/>Don''t ever let me be out of Your sight.<br/>Grant me a spirit of boldness<br/>To open my mouth Lord, to prophesy.<br/>',NULL,14737,14737);
INSERT INTO stanza VALUES('BF207','1','Lord Jesus, I love You.<br/>You''re my all —<br/>You''re my all in all.<br/>You gave me life indeed;<br/>You''re all I need,<br/>You''re all I need.<br/>Real peace and joy I never knew,<br/>Until in spirit I touched You, so —<br/>',NULL,14738,14738);
INSERT INTO stanza VALUES('BF207','chorus','Lord, I just open up to You;<br/>I let You do what You want to do.<br/>Lord, I just give myself to You.<br/>''Cause I love You — Lord, I do.<br/>',NULL,14739,14739);
INSERT INTO stanza VALUES('BF207','2','You save me all day long;<br/>Though I''m weak,<br/>You''re so strong.<br/>The flow of life and peace<br/>Within me shows the way,<br/>Hour by hour, day by day;<br/>And if through weakness I should fall,<br/>You always save me when I call.<br/>',NULL,14740,14740);
INSERT INTO stanza VALUES('BF207','3','O Lord, one touch with Thee<br/>Brought life into me.<br/>And now I can''t live without You.<br/>You''re my only delight —<br/>You''ve made everything right<br/>With a love that constrains me<br/>Till I say that —<br/>',NULL,14741,14741);
INSERT INTO stanza VALUES('BF208','1','Touching Jesus is all that really matters.<br/>And your life will never be the same.<br/>But there''s only one way to really touch Him.<br/>Just believe when you call on His name.<br/>',NULL,14742,14742);
INSERT INTO stanza VALUES('BF209','1','Lord, I am continually with Thee,<br/>Thou hast holden me by my right hand,<br/>Thou shalt guide me,<br/>Thou shalt guide me with Thy counsel,<br/>And afterward receive me,<br/>Receive me to glory.<br/>',NULL,14743,14743);
INSERT INTO stanza VALUES('BF209','2','Whom have I in heaven but Thee?<br/>And there is none upon the earth<br/>That I desire beside Thee.<br/>My flesh and my heart faileth,<br/>But God is the strength of my heart,<br/>And my portion forever.<br/>',NULL,14744,14744);
INSERT INTO stanza VALUES('BF210','1','Jesus beloved<br/>You are the Prize<br/>You are my treasure,<br/>Everything my heart likes<br/>Jesus beloved<br/>Within me You dwell<br/>We are woven together<br/>And inseparable<br/>',NULL,14745,14745);
INSERT INTO stanza VALUES('BF210','2','Jesus beloved<br/>I surrender my being<br/>Transform every part<br/>And fill me completely<br/>Jesus beloved<br/>With Your nature, so glorious<br/>How can I not love Someone<br/>So marvelous<br/>',NULL,14746,14746);
INSERT INTO stanza VALUES('BF211','1','I am the vine you are the branches<br/>He who abides in Me and I in him<br/>He bears much fruit, for apart from Me<br/>Apart from Me you can do nothing<br/>Abide in Me and I in you<br/>For the branch cannot bear fruit of itself<br/>Unless it abides in the vine<br/>So, neither can you unless you abide in Me.<br/>',NULL,14747,14747);
INSERT INTO stanza VALUES('BF212','1','Now from my heart comes<br/>A happy song<br/>It''s just for You, Lord,<br/>There''s only One;<br/>Jesus, I love You.<br/>',NULL,14748,14748);
INSERT INTO stanza VALUES('BF212','chorus','How I love to sing<br/>With my spirit unto You<br/>Jesus, You''re so rich<br/>In who You are and what You do.<br/>Every time I turn and open up<br/>I drink of You.<br/>''Cause I love You.<br/>',NULL,14749,14749);
INSERT INTO stanza VALUES('BF212','2','I''ve seen how they<br/>Pierced Your side,<br/>You gave Your all<br/>To win Your Bride.<br/>J-E-S-U-S, I love You.<br/>',NULL,14750,14750);
INSERT INTO stanza VALUES('BF212','3','Without Your love, Lord,<br/>I''m so empty<br/>Life has no meaning;<br/>Just vanity,<br/>Jesus — reality.<br/>',NULL,14751,14751);
INSERT INTO stanza VALUES('BF212','4','Jesus in me,<br/>What a wonder;<br/>Bubbling over,<br/>Living water,<br/>Jesus, what a joy.<br/>',NULL,14752,14752);
INSERT INTO stanza VALUES('BF213','1','How glorious is Thy church, oh Lord<br/>No trace of sin in her.<br/>What myst''ry this: God died as man,<br/>For, oh, He loves her so!<br/>',NULL,14753,14753);
INSERT INTO stanza VALUES('BF213','chorus','Glorious, Glorious church,<br/>She is Thy dear Bride;<br/>She was built from Thine own side<br/>She is the same as Thee.<br/>',NULL,14754,14754);
INSERT INTO stanza VALUES('BF213','2','How precious is Thy Body, Lord;<br/>How costly in Thy sight.<br/>I''d ne''er bring anything of self,<br/>For she is out from Thee.<br/>',NULL,14755,14755);
INSERT INTO stanza VALUES('BF213','3','How faithful is Thyself, dear Lord<br/>Eternally the same.<br/>Though man may fail to reach Thy will,<br/>Thou shalt obtain Thy Bride.<br/>',NULL,14756,14756);
INSERT INTO stanza VALUES('BF213','4','How subtle is my self, Oh Lord;<br/>Yet I wilt be transformed.<br/>Through Spirit''s work — become a stone<br/>To build up Thine own Bride.<br/>',NULL,14757,14757);
INSERT INTO stanza VALUES('BF213','5','How precious is Thy Body, Lord;<br/>How costly in my sight.<br/>I would decrease, and Thee increase<br/>At any cost for her.<br/>',NULL,14758,14758);
INSERT INTO stanza VALUES('BF214','1','Draw me this morning, open my eyes,<br/>Draw me this morning, ''cause I realize,<br/>All this time I''ve been resting in Your sweet embrace.<br/>You''ve been longing to speak to me, for me to awake.<br/>Draw me out of my slumber.<br/>Supply me with grace.<br/>''Cause there''s no place I''d rather be than with You.<br/>Face to face.<br/>',NULL,14759,14759);
INSERT INTO stanza VALUES('BF214','2','Draw me this morning, straight to Your Word,<br/>Draw me this morning, speak ''till I''ve heard.<br/>Lord, release what''s within You, what You want to say.<br/>Speak a word to supply me, to get through this day.<br/>You''re the Word that''s within me supplying me grace.<br/>For the rest of this day, Lord, speak with me,<br/>Face to face.<br/>',NULL,14760,14760);
INSERT INTO stanza VALUES('BF215','1','God''s eternal economy,<br/>Is to make man the same as He is<br/>In life and nature, but not in the Godhead.<br/>And to make Himself one with man,<br/>And man one with Him.<br/>Thus to be enlarged,<br/>And expanded in His expression.<br/>That all His divine,<br/>That all His divine attributes<br/>May be expressed in human virtues.<br/>',NULL,14761,14761);
INSERT INTO stanza VALUES('BF216','1','But holding to truth in love<br/>We may grow up in all things<br/>into Him who is the Head,<br/>Christ is the Head,<br/>Out from whom all the Body,<br/>being joined together and being knit together<br/>through every joint of the rich supply<br/>and through the operation in the measure<br/>of each one part, of each one part.<br/>Causes the growth of the Body unto<br/>the building up of itself in love, in love, in love.<br/>',NULL,14762,14762);
INSERT INTO stanza VALUES('BF217','1','Blessed are those who wash their robes,<br/>That they may have right to the tree of life.<br/>Blessed are those who wash their robes,<br/>That they may have right to the tree of life.<br/>And may enter, and may enter, and may enter by the gates,<br/>And may enter, and may enter, and may enter by the gates,<br/>Into the city<br/>Blessed are those.<br/>',NULL,14763,14763);
INSERT INTO stanza VALUES('BF217','2','I am the Alpha and the Omega,<br/>The First and the Last, the First and the Last,<br/>The First and the Last, the Beginning and the End,<br/>Blessed are those who wash their robes,<br/>Blessed are those who wash their robes,<br/>Who wash their robes.<br/>',NULL,14764,14764);
INSERT INTO stanza VALUES('BF218','1','Lo, the kingdom of the world is now the kingdom of the Lord!<br/>O what joy to all the saints does His eternal reign afford!<br/>Let us swell the mighty chorus of His praise in one accord —<br/>The victory is won!<br/>',NULL,14765,14765);
INSERT INTO stanza VALUES('BF218','chorus','Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>Vict''ry, vict''ry, Hallelujah!<br/>The victory is won!<br/>',NULL,14766,14766);
INSERT INTO stanza VALUES('BF218','2','That great dragon, the old serpent called the devil, down is cast;<br/>Satan and his fallen angels'' long deceiving days are past!<br/>Now our praises like a thunder through the universe shall blast —<br/>The victory is won!<br/>',NULL,14767,14767);
INSERT INTO stanza VALUES('BF218','3','Now is come salvation, power, and the kingdom of our God;<br/>The accuser of the brethren underneath our feet is trod!<br/>The authority of Christ is now the church''s ruling rod —<br/>The victory is won!<br/>',NULL,14768,14768);
INSERT INTO stanza VALUES('BF218','4','By the Lamb''s redeeming blood th'' accuser we have overcome;<br/>By our word of testimony, all declaring, "It is done!"<br/>Unto death, our souls not loving — all the glory to the Son!<br/>The victory is won!<br/>',NULL,14769,14769);
INSERT INTO stanza VALUES('BF218','5','Oh, but brothers, sisters, listen to another mighty voice,<br/>"Babylon is fallen, fallen" — what a reason to rejoice!<br/>O how blest that coming out from her was our eternal choice —<br/>The victory is won!<br/>',NULL,14770,14770);
INSERT INTO stanza VALUES('BF218','6','She''s the mother of the harlots, Myst''ry, Babylon the Great!<br/>O how all her evil fornication we have learned to hate!<br/>But our God has doubly judged her — this our spirits doth elate.<br/>The victory is won!<br/>',NULL,14771,14771);
INSERT INTO stanza VALUES('BF218','7','Hallelujah! Glory, power to the Lord our God belong!<br/>True and righteous are His judgments on the harlot for her wrong!<br/>See, her smoke is rising! Echo hallelujah in your song —<br/>The victory is won!<br/>',NULL,14772,14772);
INSERT INTO stanza VALUES('BF218','8','"Praise our God now, all ye servants, small and great,"<br/>His voice constrains.<br/>As the sound of many waters, we will thunder our refrains:<br/>Hallelujah, hallelujah, for the Lord Almighty reigns!<br/>The victory is won!<br/>',NULL,14773,14773);
INSERT INTO stanza VALUES('BF218','9','Now rejoice and be exceeding glad! What glory is displayed!<br/>For the marriage of the Lamb, the wife all ready now is made!<br/>In fine linen, bright and pure, ''twas granted her to be arrayed<br/>The victory is won!<br/>',NULL,14774,14774);
INSERT INTO stanza VALUES('BF218','10','Now the devil''s in the lake of fire, for John has seen him there;<br/>Hallelujah, never more need we his provocations bear!<br/>What a triumph for the saints his judgment boldly to declare —<br/>The victory is won!<br/>',NULL,14775,14775);
INSERT INTO stanza VALUES('BF218','11','Now behold the greatest wonder — New Jerusalem descend!<br/>She''s the building of the Triune God with man — a perfect blend!<br/>She''s the Bride, prepared, adorned for Christ —<br/>of all God''s work, the end!<br/>The victory is won!<br/>',NULL,14776,14776);
INSERT INTO stanza VALUES('BF218','12','It''s the tabernacle of our God, His dwelling place with men;<br/>In His holiness and glory He''s expressed through all of them.<br/>"It is done!" O brothers, see it! See the New Jerusalem!<br/>The victory is won!<br/>',NULL,14777,14777);
INSERT INTO stanza VALUES('BF218','chorus','Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>The victory is won!<br/>',NULL,14778,14778);
INSERT INTO stanza VALUES('BF219','chorus','Christ is our light, our food, our air;<br/>He''s everything we''ll ever need.<br/>Christ is our drink, our life, our way,<br/>If in our being, He''d be freed.<br/>',NULL,14779,14779);
INSERT INTO stanza VALUES('BF219','1','You say He''s mighty God<br/>I say He''s man.<br/>Son, Spirit, Father all,<br/>He''s rich, O so rich, when we call.<br/>',NULL,14780,14780);
INSERT INTO stanza VALUES('BF219','2','He''s Sun of righteousness<br/>Hope, peace, and faith.<br/>The Lamb of God is He<br/>So call on Him now, don''t you wait.<br/>',NULL,14781,14781);
INSERT INTO stanza VALUES('BF219','3','You say He''s Son of God;<br/>And Son of Man<br/>Firstborn among the dead<br/>Firstborn of creation, AMEN!<br/>',NULL,14782,14782);
INSERT INTO stanza VALUES('BF219','4','Our Lord''s the great I AM;<br/>The start, the end,<br/>Alpha, Omega,<br/>Lord Jesus, come quickly, AMEN!<br/>',NULL,14783,14783);
INSERT INTO stanza VALUES('BF220','1','The Triune God and the Person<br/>And the work of Christ,<br/>The Triune God is a mystery,<br/>The mystery of life.<br/>The Father, Son, and Spirit<br/>Three-One now to be,<br/>Not for comprehending,<br/>But to flow into me.<br/>',NULL,14784,14784);
INSERT INTO stanza VALUES('BF220','2','The Triune God is forever,<br/>Forever to be<br/>The life supply in my spirit;<br/>He''s dwelling in me!<br/>The Father in the Son came<br/>Displayed for all to see;<br/>The Son as Spirit flow now<br/>To flow God into me.<br/>',NULL,14785,14785);
INSERT INTO stanza VALUES('BF220','3','I''m calling His name "Lord Jesus";<br/>He''s coming in my heart.<br/>He''s spreading out from my spirit<br/>To all my inward parts.<br/>The more I contact daily,<br/>The more my heart Christ''s home,<br/>And with the saints I''m built up<br/>Into the Church, Christ''s home!<br/>',NULL,14786,14786);
INSERT INTO stanza VALUES('BF221','1','The Spirit today is the air that we breathe;<br/>Our spirits rejoice in this living inflow.<br/>For just as our body the breath does receive,<br/>So also in spirit to live it is so.<br/>',NULL,14787,14787);
INSERT INTO stanza VALUES('BF221','2','The Spirit today is the air that we breathe;<br/>What thing more important than breathing to do?<br/>For breathing each moment, new life we receive,<br/>And God''s living freshness is constant and new.<br/>',NULL,14788,14788);
INSERT INTO stanza VALUES('BF221','3','For God has been processed, as air now, He''s free;<br/>This life-giving pneuma is all that we need.<br/>He''s rich and abundant, so plentiful, He,<br/>In spirit to walk is to breathe Him indeed.<br/>',NULL,14789,14789);
INSERT INTO stanza VALUES('BF221','4','O, say, aren''t you glad that the Spirit''s outpoured<br/>And God, fully processed, is flowing in us?<br/>So freely we''re breathing this life-giving Lord,<br/>And breathing, receiving His life, glorious!<br/>',NULL,14790,14790);
INSERT INTO stanza VALUES('BF222','1','Th'' anointing''s here! The Lord is moving now in us;<br/>The ointment dear to us has been applied.<br/>His blood prevails! It gives to us the fellowship,<br/>And now we have the living flow of life.<br/>',NULL,14791,14791);
INSERT INTO stanza VALUES('BF222','chorus','(Sisters:)<br/>Th'' anointing''s here! O Christian brothers,<br/>Th'' anointing''s here! We have believed.<br/>Within our spirit, the Spirit''s moving,<br/>And this from Him we have received.<br/>',NULL,14792,14792);
INSERT INTO stanza VALUES('BF222','chorus','(Brothers:)<br/>Th'' anointing''s here! O Christian sisters,<br/>The flow within will never cease.<br/>As He anoints us, we are abiding —<br/>O Hallelujah! Life and peace!<br/>',NULL,14793,14793);
INSERT INTO stanza VALUES('BF222','2','Th'' anointing''s here! ''Tis God Himself that blends with us,<br/>And now the two are mingled into one.<br/>And hour by hour we live, and move, and have our life<br/>In God Himself — the Spirit through the Son.<br/>',NULL,14794,14794);
INSERT INTO stanza VALUES('BF222','3','Th'' anointing''s here! It teaches us in everything;<br/>The sense of life we always have within.<br/>Obey this sense, and you will know what you must do,<br/>And live by Life — Yes, clear in everything.<br/>',NULL,14795,14795);
INSERT INTO stanza VALUES('BF223','1','O my God, within Thee, there is eternal life,<br/>And this life is expressed in the Son,<br/>The risen Lord today, as the Spirit of Life,<br/>Within us, quickens us, gives us life.<br/>',NULL,14796,14796);
INSERT INTO stanza VALUES('BF223','2','O behold, from the throne of God and of the Lamb,<br/>Flows a river of water of life,<br/>God as the source of life, Christ, the fountain of life,<br/>Triune God as the river of life.<br/>',NULL,14797,14797);
INSERT INTO stanza VALUES('BF223','3','Jesus Lord, unto Thee, my spirit open wide,<br/>Calling Thee, from within, drinking Thee,<br/>Jesus Lord, now I turn, to the river of life,<br/>Triune God, saturate me as life.<br/>',NULL,14798,14798);
INSERT INTO stanza VALUES('BF224','1','Jesus my Lord will love me forever,<br/>From Him no pow''r of evil can sever,<br/>He gave His life to ransom my soul,<br/>Now I belong to Him.<br/>',NULL,14799,14799);
INSERT INTO stanza VALUES('BF224','chorus','Now I belong to Jesus,<br/>Jesus belongs to me;<br/>Not for the years of time alone,<br/>But for eternity.<br/>',NULL,14800,14800);
INSERT INTO stanza VALUES('BF224','2','Once I was lost in sin''s degradation,<br/>Jesus came down to bring me salvation,<br/>Lifted me up from sorrow and shame,<br/>Now I belong to Him.<br/>',NULL,14801,14801);
INSERT INTO stanza VALUES('BF224','3','Joy floods my spirit — Jesus has saved me,<br/>Freed me from sin that long had enslaved me,<br/>His precious blood He gave to redeem,<br/>Now I belong to Him.<br/>',NULL,14802,14802);
INSERT INTO stanza VALUES('BF225','1','There are two lines to live by in our living today —<br/>One the life line to bring us into Christ all the way.<br/>But the other is knowledge which will make us die;<br/>We must be very careful on which line we abide.<br/>',NULL,14803,14803);
INSERT INTO stanza VALUES('BF225','chorus','Oh, we''ll stay on God''s life line, never turning aside.<br/>We don''t care for vain knowledge, which will cause us to die.<br/>Lord, we''ll touch You by calling on Your name each day;<br/>Living in Your appearing, in Your presence we''ll stay.<br/>',NULL,14804,14804);
INSERT INTO stanza VALUES('BF225','2','Lord, we would be as Abel, fully contacting You;<br/>Not by knowledge or concept, but by life fresh and new.<br/>Just as Enosh began to call upon Your name,<br/>And as Enoch who walked with You, we''ll do just the same.<br/>',NULL,14805,14805);
INSERT INTO stanza VALUES('BF225','3','Keep us living and walking as did old Abraham;<br/>In Your holy appearing to be transfused like him.<br/>As did Isaac and Jacob, Moses lived this way —<br/>So dependent upon Your presence with him each day.<br/>',NULL,14806,14806);
INSERT INTO stanza VALUES('BF225','4','Full enjoyment had David, ate the life-giving tree.<br/>Daniel prayed to his God and lived by Him constantly.<br/>Jesus lived by the Father to be life complete;<br/>Now as His living Body of the life tree we''ll eat.<br/>',NULL,14807,14807);
INSERT INTO stanza VALUES('BF226','1','We have found a simple way for us to really touch the Lord:<br/>All we do is pray four words, O what a grace He does afford!<br/>From our spirit now we say them, and we spread the news abroad.<br/>It''s easy to touch the Lord!<br/>',NULL,14808,14808);
INSERT INTO stanza VALUES('BF226','2','Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>It''s easy to touch the Lord!<br/>',NULL,14809,14809);
INSERT INTO stanza VALUES('BF227','1','I just keep calling O Lord as I walk along,<br/>I just keep calling O Lord and He gives a song;<br/>Though the storm-clouds darken the sky o''er the heav''nly trail,<br/>I just keep calling O Lord, He will never fail!<br/>',NULL,14810,14810);
INSERT INTO stanza VALUES('BF227','2','He''s a faithful Friend, such a faithful Friend,<br/>I can count on Him to the very end;<br/>Though the storm clouds darken the sky o''er the heav''nly trail,<br/>I just keep calling O Lord, He will never fail!<br/>',NULL,14811,14811);
INSERT INTO stanza VALUES('BF228','1','Jesus Lord, You''re our first love;<br/>You''re the One we love the best.<br/>When our heart is loving You,<br/>How we''re filled with Your sweet rest!<br/>Lord, we love You for Yourself,<br/>Not for what You give or do.<br/>Nothing else could e''er compare<br/>With the joy of loving You.<br/>',NULL,14812,14812);
INSERT INTO stanza VALUES('BF228','chorus','Lord, we''ve been drawn off by many things;<br/>Now we turn our heart back — how it sings!<br/>We repent of loving other things —<br/>Jesus, Lord, You are our first love.<br/>',NULL,14813,14813);
INSERT INTO stanza VALUES('BF228','2','Never more could we desire<br/>Anything that''s less than You,<br/>And to this we will aspire —<br/>Simply to be filled with You.<br/>Jesus, Lord, You''re our first love;<br/>You''re the One we love the best.<br/>When our heart is loving You,<br/>How we''re filled with Your sweet rest!<br/>',NULL,14814,14814);
INSERT INTO stanza VALUES('BF229','1','Jesus, we love You that You are the vine tree,<br/>Our rich supply of life outflowing;<br/>Scarce can we fathom that we are Your branches<br/>To bear Your fruit, Your fullness showing.<br/>You are our Father, our faithful vine dresser,<br/>Our source, our water, our life, our sunshine;<br/>O Lord, we pour out our being before You,<br/>We love You.<br/>',NULL,14815,14815);
INSERT INTO stanza VALUES('BF229','2','Joyful fulfillment, in You we''re abiding,<br/>We find in You sweet rest and oneness;<br/>And even more, in Your love we are dwelling,<br/>Responding to Your voice within us.<br/>While in Your presence, Your person enjoying,<br/>So near, so dear, so satisfying;<br/>Nothing we long for, no other desire,<br/>We love You....love You......<br/>',NULL,14816,14816);
INSERT INTO stanza VALUES('BF229','3','Father, O Father, You''ve loved Your Son, Jesus,<br/>In Him, Your glory manifested;<br/>Jesus, our Jesus, You also have loved us<br/>With love that death supremely tested.<br/>No greater love could a man have than this —<br/>That You laid down Your life<br/>For Your friends, Your loved ones;<br/>What can we say? We can only adore You,<br/>We love You....love You....We love You.<br/>',NULL,14817,14817);
INSERT INTO stanza VALUES('BF230','1','I am weak but Thou art strong,<br/>Jesus, keep me from all wrong;<br/>I''ll be satisfied as long<br/>As I walk let me walk close to Thee.<br/>',NULL,14818,14818);
INSERT INTO stanza VALUES('BF230','chorus','Just a closer walk with Thee,<br/>Grant it, Jesus, ''tis my plea;<br/>Daily walking close with Thee,<br/>Let it be, dear Lord, let it be.<br/>',NULL,14819,14819);
INSERT INTO stanza VALUES('BF230','2','Thru this world of toil and snares,<br/>If I falter, Lord, who cares?<br/>Who with me my burden shares?<br/>None but Thee, dear Lord, none but Thee.<br/>',NULL,14820,14820);
INSERT INTO stanza VALUES('BF231','1','If Thou wouldst take what I desire,<br/>Lord, give Thyself to me;<br/>If Thou wouldst keep me to inquire,<br/>Lord, give Thyself to me.<br/>',NULL,14821,14821);
INSERT INTO stanza VALUES('BF231','chorus','Lord Jesus, precious Savior,<br/>More of Thyself give me;<br/>Subject I wholly to Thee,<br/>More of Thyself for me.<br/>',NULL,14822,14822);
INSERT INTO stanza VALUES('BF231','2','My hopes are blurred and gone away,<br/>Lord, give Thyself to me;<br/>My heart keeps wav''ring all the way,<br/>Lord, give Thyself to me.<br/>',NULL,14823,14823);
INSERT INTO stanza VALUES('BF231','3','Since Thou took all that I depend,<br/>Lord, give Thyself to me;<br/>Since Thou reject my pray''rs again,<br/>Lord, give Thyself to me.<br/>',NULL,14824,14824);
INSERT INTO stanza VALUES('BF231','4','If patience''s what I truly lack,<br/>Still give Thyself to me;<br/>If Thou delay Thy coming back,<br/>Give more Thyself to me.<br/>',NULL,14825,14825);
INSERT INTO stanza VALUES('BF232','1','Thank You, Lord Jesus, for dying for me.<br/>It''s Your precious blood cleansing all iniquities.<br/>It''s there on the cross where You bled and died for me.<br/>Lord Jesus, I thank You, I''m fully justified in Thee.<br/>',NULL,14826,14826);
INSERT INTO stanza VALUES('BF232','chorus','Lord Jesus, I love You,<br/>You''re precious to me.<br/>It''s here in Your presence,<br/>I''ve seen Your beauty.<br/>You''re matchless, You''re priceless,<br/>You''re everything to me.<br/>I''ll love You forever —<br/>You are the only One for me.<br/>',NULL,14827,14827);
INSERT INTO stanza VALUES('BF232','2','Daily I come to be supplied by Your word.<br/>It''s by this supply that I''m richly satisfied.<br/>It''s here that I''m strengthened to live the Christian life.<br/>It''s nothing I do, but Your overflowing grace to me.<br/>',NULL,14828,14828);
INSERT INTO stanza VALUES('BF232','3','Each day as I wake up I come to You, Lord.<br/>Our fellowship sweet must be daily restored.<br/>Void of offense, keep my conscience so pure.<br/>Soften me, Lord, so that You alone may have my heart.<br/>',NULL,14829,14829);
INSERT INTO stanza VALUES('BF233','1','Lord, I love You.<br/>Thank You, for opening my eyes.<br/>Lord, I''ve seen Who You are,<br/>And I can''t help falling in love.<br/>',NULL,14830,14830);
INSERT INTO stanza VALUES('BF233','2','One day, so desperate for You,<br/>Praying earnestly to You.<br/>Lord, I''m not satisfied.<br/>Show me, Lord, how lovely You are.<br/>',NULL,14831,14831);
INSERT INTO stanza VALUES('BF233','3','Thank You, for Your faithfulness.<br/>I have seen Thy preciousness.<br/>Now, Lord, I can''t deny<br/>Your beauty has captured my heart.<br/>',NULL,14832,14832);
INSERT INTO stanza VALUES('BF233','4','Now, Lord, You''re all I want.<br/>I waste all that I have.<br/>No one compares to You.<br/>Here in love, Lord, I will remain<br/>',NULL,14833,14833);
INSERT INTO stanza VALUES('BF234','1','Nearer each day to me,<br/>Dearer each day to me,<br/>This Person inside me is<br/>Becoming reality.<br/>Saving me, loving me<br/>Faith and hope giving me.<br/>You''re all the world to me<br/>Jesus my Lord.<br/>',NULL,14834,14834);
INSERT INTO stanza VALUES('BF234','2','Even when faith is small<br/>When there''s no hope at all;<br/>I hear Him say to me,<br/>"Trust in Me and you''ll see<br/>That I''ll supply all your needs<br/>If only you will believe.<br/>All anxious doubts will cease<br/>While trusting in Me."<br/>',NULL,14835,14835);
INSERT INTO stanza VALUES('BF235','chorus','Lord, there''s nothing in this world like You —<br/>You fill me up completely.<br/>And I would never give You up for anything,<br/>Because nothing else could satisfy me so.<br/>',NULL,14836,14836);
INSERT INTO stanza VALUES('BF235','1','People think that they can find<br/>Satisfaction, peace of mind.<br/>Everything leads to another,<br/>But I found the best.<br/>',NULL,14837,14837);
INSERT INTO stanza VALUES('BF235','2','No more trying something else,<br/>Or thinking that there''s something more;<br/>No more hoping "someday,"<br/>''Cause today I have the best.<br/>',NULL,14838,14838);
INSERT INTO stanza VALUES('BF235','3','Looking not at failures past,<br/>Hoping not in future dreams;<br/>Not wishing I were different<br/>Knowing everything''s the best.<br/>',NULL,14839,14839);
INSERT INTO stanza VALUES('BF236','1','Lord, I love You:<br/>Lord, take my heart.<br/>Lord, saturate me.<br/>Fill every part with Your life divine.<br/>Lord, I now surrender all to You.<br/>',NULL,14840,14840);
INSERT INTO stanza VALUES('BF236','2','Keep me turning to You every day.<br/>Until I''m expressing only You always,<br/>Until I''m expressing only You.<br/>',NULL,14841,14841);
INSERT INTO stanza VALUES('BF237','1','Lord, do unveil<br/>The more we strive the more we fail<br/>All the strife — they all come out to no avail.<br/>Lord, they''re just not for Your need<br/>By "self," we won''t succeed.<br/>',NULL,14842,14842);
INSERT INTO stanza VALUES('BF237','2','Lord, we confess<br/>We are not able, Lord, unless<br/>We have You; You''re all in all — You''re our success!<br/>All we need, O Lord, is You<br/>''Cause nothing else will do.<br/>',NULL,14843,14843);
INSERT INTO stanza VALUES('BF237','3','O Lord, we pray<br/>Increase Thyself in us each day<br/>And the "self" — decrease ''til it''s done away.<br/>Lord, we want the growth in life<br/>We don''t want all the strife.<br/>',NULL,14844,14844);
INSERT INTO stanza VALUES('BF237','4','Lord, life''s begun<br/>Two spirits mingled into one<br/>Day by day, walk in the spirit and we''ve won!<br/>Then the "self" will be decreased<br/>And Christ in us increased.<br/>',NULL,14845,14845);
INSERT INTO stanza VALUES('BF238','chorus','Lord, take my life, I give it, Lord, to You.<br/>You have opened my eyes, Lord, and turned me to You.<br/>You are my Creator, O Lord, how I love You.<br/>You are also my Savior and everything that''s true.<br/>',NULL,14846,14846);
INSERT INTO stanza VALUES('BF238','1','Lord, so often I''m like Thomas<br/>Who would not receive:<br/>"Unless I see Your face, Lord, I would not believe..."<br/>But then You would appear... "My Lord and my God"<br/>Saying, Blessed are they who see not, yet believed.<br/>',NULL,14847,14847);
INSERT INTO stanza VALUES('BF238','2','I have someone deep in me welling up in me each day.<br/>Even though I have not see Him in such an outward way —<br/>Whom having not seen, I love, I love, oh so much.<br/>And my having His life, yes, I believe."<br/>',NULL,14848,14848);
INSERT INTO stanza VALUES('BF238','3','Day by day I look forward to the time I spend with You.<br/>Just as Mary poured her love out, O Lord, I would too.<br/>Grant me, Lord, a heart that is single and true.<br/>And a daily life that''s living just by You.<br/>',NULL,14849,14849);
INSERT INTO stanza VALUES('BF238','4','So when daily I see trials and tribulations sore,<br/>May I put my trust in You, Lord,<br/>"For Christ has gone before"<br/>And open to Your living Word, receiving faith —<br/>Reach me, Lord, with Your mercy and Your grace.<br/>',NULL,14850,14850);
INSERT INTO stanza VALUES('BF239','1','I have a seed of life in me<br/>This seed of life is growing free.<br/>This seed of life is just Christ.<br/>Alive in me.<br/>',NULL,14851,14851);
INSERT INTO stanza VALUES('BF239','chorus','Thank You, Lord, for opening my eyes!<br/>Thank You, Lord, I''m forever satisfied!<br/>',NULL,14852,14852);
INSERT INTO stanza VALUES('BF239','2','And now He''s growing inwardly.<br/>He saturates me thoroughly.<br/>The fellowship is so sweet;<br/>He fills me to the brim.<br/>',NULL,14853,14853);
INSERT INTO stanza VALUES('BF239','chorus','Lord, You are my life and my guide!<br/>Lord, to You my heart is open wide!<br/>',NULL,14854,14854);
INSERT INTO stanza VALUES('BF239','3','Lord, I give my life to You<br/>That I''d forever grow in You.<br/>And You in me, so I''ll always be<br/>One with You.<br/>',NULL,14855,14855);
INSERT INTO stanza VALUES('BF240','chorus','Reading the Bible,<br/>I love the Word of God!<br/>Reading the Bible,<br/>I love the Word of God!<br/>',NULL,14856,14856);
INSERT INTO stanza VALUES('BF240','1','Every verse reveals Yourself to me,<br/>Every line conveys reality.<br/>When I pray the words that You breathed out<br/>You become so real to me.<br/>',NULL,14857,14857);
INSERT INTO stanza VALUES('BF240','2','As I read, I pray, as I pray, I read,<br/>Mingling both as one spontaneously.<br/>You respond within with words so sweet,<br/>I repeat these words to Thee.<br/>',NULL,14858,14858);
INSERT INTO stanza VALUES('BF240','3','I''m a newborn babe — it''s the milk I need,<br/>Not the knowledge of the dead teaching.<br/>When I eat Your Word, it becomes to me<br/>My heart''s joy and rejoicing.<br/>',NULL,14859,14859);
INSERT INTO stanza VALUES('BF240','4','Sweeter than honey, precious more than gold;<br/>It will not be void, but as the rain and snow<br/>It will do Your will — bear the life divine,<br/>Bearing fruit a hundred fold.<br/>',NULL,14860,14860);
INSERT INTO stanza VALUES('BF240','5','When my heart is like a rock so cold<br/>It''s Your word so strong that hammers stone,<br/>That the grain of life may come to me<br/>And supply me inwardly.<br/>',NULL,14861,14861);
INSERT INTO stanza VALUES('BF240','6','It''s my food, my drink, and my life supply;<br/>I love to eat it every day and night.<br/>I just turn and open up to Him<br/>And the rivers flow right in.<br/>',NULL,14862,14862);
INSERT INTO stanza VALUES('BF241','1','God''s economy and His eternal plan,<br/>His heart''s desire and intention is to be one with man.<br/>Yet man has failed completely thoughout all history.<br/>But Hallelujah! Praise the Lord!<br/>God''s life is now in me.<br/>',NULL,14863,14863);
INSERT INTO stanza VALUES('BF241','2','Now this life in me is flowing as the river of water of life,<br/>Washing away all my sins, my cares, and all my strife.<br/>This life is overcoming situations in my day.<br/>Hallelujah! Praise the Lord! For this is what I pray:<br/>',NULL,14864,14864);
INSERT INTO stanza VALUES('BF241','chorus','Lord Jesus, I love You!<br/>I give You the preeminence in what I do.<br/>Enjoying You is the overcoming way.<br/>Thank You for Your recovery.<br/>Your Word we will obey.<br/>',NULL,14865,14865);
INSERT INTO stanza VALUES('BF241','3','Thank You for our situations and the environments we are in,<br/>That we''d turn to You in all things, and turn away from sin.<br/>We''d drop all our anxieties and put our trust in You.<br/>And experience this living Christ because He''s ever new.<br/>',NULL,14866,14866);
INSERT INTO stanza VALUES('BF241','4','Now the church life is so precious with all the saints so dear.<br/>Enjoying all Your riches, our vision is so clear.<br/>That all would prophesy of Christ from what they''ve seen,<br/>According to Your scripture in first Corinthians 14.<br/>',NULL,14867,14867);
INSERT INTO stanza VALUES('BF242','1','Life''s too short to waste a single day<br/>The kingdom life is closer every day<br/>In the midst of time, the kingdom''s mine<br/>Just by calling on His name each day.<br/>',NULL,14868,14868);
INSERT INTO stanza VALUES('BF242','2','The sweetest taste of life is deep within<br/>Its flowing out is primed by calling Him<br/>In the midst of time, the kingdom''s mine<br/>Just by calling on His name each day.<br/>',NULL,14869,14869);
INSERT INTO stanza VALUES('BF242','3','Time is quickly running out each day<br/>The Lord will come and swiftly end this age<br/>At the end of time, the goal we see<br/>The millenium is our entry.<br/>At the end of time, the goal we see<br/>The New Jerusalem will be.<br/>',NULL,14870,14870);
INSERT INTO stanza VALUES('BF243','1','Jesus — God''s Son He left the heavens to die<br/>for men, to suffer pain,<br/>He gave Himself as ransom for all;<br/>And He died and rose again,<br/>As Spirit — Lord of all.<br/>',NULL,14871,14871);
INSERT INTO stanza VALUES('BF243','chorus','Ever living Lord is my hope of glory,<br/>He wipes away my tears and griefs;<br/>Makes home in my heart,<br/>Gives life and power,<br/>Leads me to life eternal,<br/>Oh, how bright and clear.<br/>',NULL,14872,14872);
INSERT INTO stanza VALUES('BF243','2','In the Lord, I''ve obtained a new life,<br/>Behold, all things have become new;<br/>Living in love, my life grows brighter.<br/>Having life and standing firm,<br/>God''s salvation enjoy.<br/>',NULL,14873,14873);
INSERT INTO stanza VALUES('BF243','3','I love You Lord, Your footsteps follow,<br/>For You I''ll fight, make me faithful;<br/>To please You, Lord Your command hold fast;<br/>Be victorious until forever with You I''ll be.<br/>',NULL,14874,14874);
INSERT INTO stanza VALUES('BF244','1','Lord, we thank You for the history that our fathers made;<br/>Such a wonderful recovery in their day!<br/>Now our fathers'' dead and buried —<br/>It is up to us to carry;<br/>The baton of Your recovery''s in our hands.<br/>',NULL,14875,14875);
INSERT INTO stanza VALUES('BF244','2','We are the new generation in the Philippines<br/>We have left all forms and methods — we are NEW!<br/>Not depending on our history —<br/>But speaking forth the mystery;<br/>We are the new generation, WE ARE NEW!<br/>',NULL,14876,14876);
INSERT INTO stanza VALUES('BF244','3','We''re the praying Galileans,<br/>Fill our spirits, Lord!<br/>Standing outside of religion, WE ARE BOLD!<br/>As we exercise our spirit, we become pestilent fellows;<br/>And become the useful members in the church.<br/>',NULL,14877,14877);
INSERT INTO stanza VALUES('BF244','4','Now we give ourselves completely to this ministry;<br/>By our burning be perfected into one.<br/>Turning upside down the system of the current Judaism;<br/>Christianity''s wrong standing''s falling down.<br/>',NULL,14878,14878);
INSERT INTO stanza VALUES('BF244','5','Crazy lovers of our Jesus, we will disappear;<br/>Many firstfruits you are ripening every year!<br/>To the throne we will be speeded<br/>To the place where we are needed;<br/>To satisfy our Jesus is our goal!<br/>',NULL,14879,14879);
INSERT INTO stanza VALUES('BF245','1','I love Thee, Jesus,<br/>And Thy love to me<br/>Draws me, ever to seek Thee<br/>And run after Thee,<br/>Draws me, ever to seek Thee<br/>And run after Thee.<br/>Thou art beloved,<br/>Yea! Altogether lovely,<br/>The One in whom my heart delighteth.<br/>(Repeat the last three lines of each stanza)<br/>',NULL,14880,14880);
INSERT INTO stanza VALUES('BF245','2','Thy love, Lord Jesus,<br/>Is sweeter than wine,<br/>And Thy fragrance of ointments<br/>My heart doth entwine,<br/>And Thy fragrance of ointments<br/>My heart doth entwine.<br/>A fount in gardens,<br/>A well of living waters,<br/>Which streams and flows from<br/>Lebanon''s mountains.<br/>',NULL,14881,14881);
INSERT INTO stanza VALUES('BF245','3','O come Beloved,<br/>On my garden blow,<br/>That the odor of spices<br/>May break forth and flow,<br/>That the odor of spices<br/>May break forth and flow.<br/>My spouse, My sister,<br/>I''m come into My garden<br/>To feast upon wine, milk and honey.<br/>',NULL,14882,14882);
INSERT INTO stanza VALUES('BF245','4','Set me, Lord Jesus,<br/>As seal on Thine heart;<br/>Jealousy''s cruel as Sheol,<br/>And love''s strong as death<br/>Jealousy''s cruel as Sheol,<br/>And love''s strong as death.<br/>Such water cannot<br/>Quench love, nor do floods drown it.<br/>All man could give for love is contemned.<br/>',NULL,14883,14883);
INSERT INTO stanza VALUES('BF246','1','Let us eat Jesus every day,<br/>Eating His flesh in such a way<br/>That in the trials great or small<br/>He as a Man will be our all.<br/>',NULL,14884,14884);
INSERT INTO stanza VALUES('BF246','chorus','Eat, eat more of Jesus!<br/>Eat, eat more of Jesus!<br/>Why should we undernourished be<br/>When we have His humanity?<br/>',NULL,14885,14885);
INSERT INTO stanza VALUES('BF246','2','Let us drink Jesus till we see<br/>That we are human, Jesusly!<br/>Till rivers flood the barren ground<br/>And quench the thirst of all around.<br/>',NULL,14886,14886);
INSERT INTO stanza VALUES('BF246','chorus','Drink, drink more of Jesus!<br/>Drink, drink more of Jesus!<br/>Why should we ever thirsty be<br/>When we have His humanity?<br/>',NULL,14887,14887);
INSERT INTO stanza VALUES('BF246','3','We must eat Jesus till God can<br/>Have the fulfillment of His plan —<br/>One man expressed for all to see,<br/>One church in each locality.<br/>',NULL,14888,14888);
INSERT INTO stanza VALUES('BF246','chorus','We''ll masticate Jesus!<br/>We''ll masticate Jesus!<br/>Then to the tent of meeting bring<br/>Jesus, our real meal offering.<br/>',NULL,14889,14889);
INSERT INTO stanza VALUES('BF247','1','At the house in Bethany, Jesus appears.<br/>His presence is so sweet, His voice is so near.<br/>Our hands can handle Him, our eyes do behold,<br/>Our hearts have experienced the love of the Lord.<br/>',NULL,14890,14890);
INSERT INTO stanza VALUES('BF247','chorus','Oh, Lord, how we love Thee,<br/>We love Thee so.<br/>We pour ourselves out on Thee,<br/>We let the ointment flow.<br/>',NULL,14891,14891);
INSERT INTO stanza VALUES('BF247','2','We don''t care if others say that this is all a waste.<br/>For the poor we have always, but now we see Thy face.<br/>Oh, Lord, it''s not a waste, when we give our love to Thee<br/>Our whole being longs to be with Thee eternally.<br/>',NULL,14892,14892);
INSERT INTO stanza VALUES('BF247','3','As we pour it on the head, it flows down to the feet.<br/>Every member''s fully met, with such an ointment sweet.<br/>With the ointment over all, such fragrance fills the room.<br/>Tasting sweetness such as this, we know You''re coming soon<br/>',NULL,14893,14893);
INSERT INTO stanza VALUES('BF248','1','How I love Thee, precious Jesus,<br/>That Thy love laid hold of me;<br/>Thou hast drawn and wooed and kissed me<br/>That a lover I may be!<br/>',NULL,14894,14894);
INSERT INTO stanza VALUES('BF248','chorus','Our Beloved, how we love Him,<br/>So attractive, our delight.<br/>We are captivated wholly<br/>And are comely in His sight.<br/>',NULL,14895,14895);
INSERT INTO stanza VALUES('BF248','2','As a company of horses,<br/>Thou, O Lord, has likened me,<br/>Strong and swift, with Pharaoh''s chariots,<br/>Full of natural energy.<br/>',NULL,14896,14896);
INSERT INTO stanza VALUES('BF248','3','Just a lover with the dove''s eyes<br/>Fixed on Him and Him alone;<br/>Changed are all my natural concepts,<br/>Oh, the Lord in me has grown!<br/>',NULL,14897,14897);
INSERT INTO stanza VALUES('BF248','4','Now a lily of the valley,<br/>Standing out among the thorns,<br/>In the Lord alone I''m trusting,<br/>Of my self-strength I''ve been shorn.<br/>',NULL,14898,14898);
INSERT INTO stanza VALUES('BF248','5','Make us doves that hide in Thee, Lord;<br/>Bring us to the secret place.<br/>There You find our voices sweet, Lord,<br/>And desire to see our face.<br/>',NULL,14899,14899);
INSERT INTO stanza VALUES('BF248','6','Make us then, Lord, smoking pillars,<br/>Coming from the wilderness.<br/>By Thy death and resurrection<br/>All our natural will suppress.<br/>',NULL,14900,14900);
INSERT INTO stanza VALUES('BF248','7','You desire a couch to rest on —<br/>We become a rest to Thee;<br/>Thou the Person in our being;<br/>Gone our personality.<br/>',NULL,14901,14901);
INSERT INTO stanza VALUES('BF248','8','Now a palanquin You''re making —<br/>Nothing natural You''ll allow.<br/>For Your move and Your expression<br/>Start this work within us now!<br/>',NULL,14902,14902);
INSERT INTO stanza VALUES('BF248','9','You supply the wood and pillars<br/>For the structure and support,<br/>Bottom gold and seat of purple<br/>For our King of royal court.<br/>',NULL,14903,14903);
INSERT INTO stanza VALUES('BF248','10','Only this, O Lord, we offer<br/>For Thy palanquin so fine:<br/>Just our love, so pure and fitted,<br/>The interior design.<br/>',NULL,14904,14904);
INSERT INTO stanza VALUES('BF248','11','What a sight when our Beloved<br/>Wears a crown upon His brow;<br/>Christ, the Church, are now united —<br/>Boast and glory to Him now.<br/>',NULL,14905,14905);
INSERT INTO stanza VALUES('BF249','1','We''ve found the secret of living,<br/>We''ve seen the vision divine:<br/>We are of God in Christ Jesus,<br/>We''re abiding, abiding in the vine.<br/>',NULL,14906,14906);
INSERT INTO stanza VALUES('BF249','chorus','Abiding in the vine,<br/>Abiding in the vine,<br/>All the riches of God''s life are mine!<br/>Praise God, He put us here,<br/>Never to leave; oh, we''re —<br/>Abiding, abiding in the vine.<br/>',NULL,14907,14907);
INSERT INTO stanza VALUES('BF249','2','No more in vain need we struggle,<br/>Trying the way in to find.<br/>Praise God — we''re in Him already,<br/>Hallelujah, abiding in the vine.<br/>',NULL,14908,14908);
INSERT INTO stanza VALUES('BF249','3','In us, the ointment is moving,<br/>''Tis the anointing divine;<br/>God''s precious essence bestowing,<br/>While abiding, abiding in the vine.<br/>',NULL,14909,14909);
INSERT INTO stanza VALUES('BF249','4','Now in the life-flow we''re living,<br/>O how the light in us shines!<br/>Both God and man are at home now<br/>By the mutual abiding in the vine.<br/>',NULL,14910,14910);
INSERT INTO stanza VALUES('BF250','1','Laboring on the good land, laboring in the morning,<br/>Laboring through the noontime to the early eve,<br/>Laboring for the harvest, reaping all the produce,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,14911,14911);
INSERT INTO stanza VALUES('BF250','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>',NULL,14912,14912);
INSERT INTO stanza VALUES('BF250','2','Reaping wheat and barley, death and resurrection,<br/>Though the loss sustained our old man often grieves;<br/>But in life abundant, life in resurrection,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,14913,14913);
INSERT INTO stanza VALUES('BF250','3','Grain and wine and oil — bringing in the surplus<br/>Of the wheat and barley, vine and olive trees:<br/>Wine to cause rejoicing, oil to give anointing,<br/>Bringing in the top tenth, bringing in the sheaves.<br/>',NULL,14914,14914);
INSERT INTO stanza VALUES('BF251','1','I''m gonna praise God unceasingly<br/>Because He lives in me,<br/>He''s everything to me,<br/>Gives life continually.<br/>I''m gonna praise God unceasingly<br/>Because He lives in me,<br/>And He will never leave.<br/>',NULL,14915,14915);
INSERT INTO stanza VALUES('BF251','chorus','Now in our spirit we can feed,<br/>Jesus Christ is all we need,<br/>Call His name and He becomes reality.<br/>Open up your mouth and you will see,<br/>Just how rich our Lord can be.<br/>He''s the very life supply, complete is He.<br/>',NULL,14916,14916);
INSERT INTO stanza VALUES('BF251','2','Now I live by the tree of life,<br/>His fruit does nourish me,<br/>O how it strengthens me,<br/>I''ll live eternally.<br/>Now I live by the tree of life,<br/>Him daily I apply,<br/>He is my food supply.<br/>',NULL,14917,14917);
INSERT INTO stanza VALUES('BF251','3','There''s the river of life in me,<br/>Flowing so livingly,<br/>Moving continually,<br/>He just keeps flooding me.<br/>There''s a river of life in me,<br/>He''s always filling me,<br/>His name is Jesus Christ!<br/>',NULL,14918,14918);
INSERT INTO stanza VALUES('BF252','1','God is light, and in Him there is no darkness at all!<br/>Oh, how we love within His presence to dwell!<br/>In this light we enjoy a constant cleansing within —<br/>From every sin!<br/>',NULL,14919,14919);
INSERT INTO stanza VALUES('BF252','2','Sisters:	In the light,<br/>Brothers:	We are walking —<br/>Sisters:	Fellowship,<br/>Brothers:	We''re enjoying;<br/>Sisters:	And the blood<br/>Brothers:	Of God''s Son<br/>Everyone:	Is cleansing us from sin.<br/>',NULL,14920,14920);
INSERT INTO stanza VALUES('BF252','3','Sisters:	We confess,<br/>Brothers:	He is faithful —<br/>Sisters:	To forgive —<br/>Brothers:	He is righteous.<br/>Sisters:	What a joy!<br/>Brothers:	We are cleansed<br/>Everyone:	From every sin!<br/>',NULL,14921,14921);
INSERT INTO stanza VALUES('BF253','chorus','Go on, go on, go on in the Lord,<br/>Be strengthened, go on in the Lord.<br/>Your labor is not in vain in the Lord.<br/>You must go on, go on in the Lord.<br/>',NULL,14922,14922);
INSERT INTO stanza VALUES('BF253','1','Trials may come and discouragement, too.<br/>You must go on, go on in the Lord.<br/>Yesterday''s gone and His mercies are new.<br/>You must go on, go on in the Lord.<br/>(use "press on" in chorus)<br/>',NULL,14923,14923);
INSERT INTO stanza VALUES('BF253','2','To worry is vain — He will care for Your needs.<br/>You must go on, go on in the Lord.<br/>Tomorrow''s not here and it never may be.<br/>You must go on, go on in the Lord.<br/>(use "sail on" in chorus)<br/>',NULL,14924,14924);
INSERT INTO stanza VALUES('BF254','1','My old person has been nullified;<br/>With my Lord upon the cross he died;<br/>Now in nothing shall he be applied;<br/>He''s dead to me.<br/>My new Person in my spirit dwells;<br/>Springing in me as a bubbling well;<br/>Flowing out until each part He fills<br/>With abundant life.<br/>',NULL,14925,14925);
INSERT INTO stanza VALUES('BF254','chorus','Christ, my Person, in my spirit lives;<br/>And my heart to Him I''d daily give;<br/>That my inner man could have a home<br/>And a place to settle down, yes,<br/>A place to call His own, and —<br/>There be my complete reality,<br/>There expressing all He is to me,<br/>Living in my heart abundantly<br/>As my Person real.<br/>',NULL,14926,14926);
INSERT INTO stanza VALUES('BF254','2','By this Person being formed in me,<br/>I''ll a member of His Body be,<br/>No more acting individually,<br/>But with the saints.<br/>More and more our Person He must be;<br/>That our natural personality<br/>Be eliminated thoroughly<br/>''Till Christ is all.<br/>',NULL,14927,14927);
INSERT INTO stanza VALUES('BF254','chorus','Only Christ, our Person, must remain;<br/>From our aims, our goals we must refrain,<br/>''Till the church be only Christ Himself<br/>Built up as the one new man,<br/>Thus fulfilling God''s great plan of —<br/>Mingling fully with the human race<br/>To obtain a proper dwelling place,<br/>''Stablishing His kingdom''s rule and grace;<br/>Over all the earth.<br/>',NULL,14928,14928);
INSERT INTO stanza VALUES('BF254','chorus','Not Himself just individually,<br/>But the church together corporately,<br/>Taking Christ as all in all, to be<br/>The full-grown, perfect man.<br/>',NULL,14929,14929);
INSERT INTO stanza VALUES('BF255','1','Count it all joy, brethren,<br/>When ye enter into,<br/>Into temptation,<br/>Count it all joy.<br/>',NULL,14930,14930);
INSERT INTO stanza VALUES('BF255','2','Count it all joy, Hallelujah,<br/>Count it all joy, Hallelujah,<br/>Count it all joy, Hallelujah.<br/>',NULL,14931,14931);
INSERT INTO stanza VALUES('BF255','3','Hallelujah, Hosanna, Hallelujah,<br/>Hallelujah, Hosanna, Hallelujah,<br/>Hallelujah, Hosanna, Hallelujah,<br/>',NULL,14932,14932);
INSERT INTO stanza VALUES('BF255','4','We are troubled on every side,<br/>Yet not distressed;<br/>We are perplexed but not in despair<br/>Persecuted, but not forsaken,<br/>We are cast down, but not destroyed.<br/>',NULL,14933,14933);
INSERT INTO stanza VALUES('BF256','1','If from your nat''ral man you would be free,<br/>Amen the law of life!<br/>This law works in us automatically,<br/>Amen the law of life!<br/>',NULL,14934,14934);
INSERT INTO stanza VALUES('BF256','chorus','Amen the law of life!<br/>Amen the law of life!<br/>This law transforms us, to Christ conforms us —<br/>Amen the law of life!<br/>',NULL,14935,14935);
INSERT INTO stanza VALUES('BF256','2','From life divine it does originate,<br/>Amen the law of life!<br/>Its function, working, power are innate,<br/>Amen the law of life!<br/>',NULL,14936,14936);
INSERT INTO stanza VALUES('BF256','chorus','Amen the law of life!<br/>Amen the law of life!<br/>Stop all your trying, on life relying,<br/>Amen the law of life!<br/>',NULL,14937,14937);
INSERT INTO stanza VALUES('BF256','3','The law of life fulfills our God''s desire,<br/>Amen the law of life!<br/>Our self-improvement He does not require,<br/>Amen the law of life!<br/>',NULL,14938,14938);
INSERT INTO stanza VALUES('BF256','chorus','Amen the law of life!<br/>Amen the law of life!<br/>God''s plan fulfilling; Yes, Lord, we''re willing,<br/>Amen the law of life!<br/>',NULL,14939,14939);
INSERT INTO stanza VALUES('BF256','4','This law transforms us metabolically,<br/>Amen the law of life!<br/>''Til we are permeated corporately,<br/>Amen the law of life!<br/>',NULL,14940,14940);
INSERT INTO stanza VALUES('BF256','chorus','Amen the law of life!<br/>Amen the law of life!<br/>Old man denying, God''s life supplying,<br/>Amen the law of life!<br/>',NULL,14941,14941);
INSERT INTO stanza VALUES('BF256','5','This law''s inscribing Christ upon our hearts,<br/>Amen the law of life!<br/>''Til He is written in our inward parts,<br/>Amen the law of life!<br/>',NULL,14942,14942);
INSERT INTO stanza VALUES('BF256','chorus','Amen the law of life!<br/>Amen the law of life!<br/>Christ''s form engraving, not mere behaving,<br/>Amen the law of life!<br/>',NULL,14943,14943);
INSERT INTO stanza VALUES('BF257','1','God has not giv''n us a spirit of fear —<br/>There''s pow''r deep within, pow''r deep within!<br/>We have His Word — brothers, sisters, let''s hear —<br/>That pow''r deep within may flow out.<br/>',NULL,14944,14944);
INSERT INTO stanza VALUES('BF257','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r<br/>In the spirit God''s given us!<br/>',NULL,14945,14945);
INSERT INTO stanza VALUES('BF257','2','God has not giv''n us a wavering will —<br/>There''s pow''r deep within, pow''r deep within!<br/>But one our spirit will strengthen and fill —<br/>There''s wonderful pow''r deep within!<br/>',NULL,14946,14946);
INSERT INTO stanza VALUES('BF257','3','God has not giv''n us emotions so weak —<br/>There''s pow''r deep within, pow''r deep within!<br/>Open our hearts and in love let us speak —<br/>There''s wonderful pow''r deep within!<br/>',NULL,14947,14947);
INSERT INTO stanza VALUES('BF257','4','God has not giv''n us a mind that is bound —<br/>There''s pow''r deep within, pow''r deep within!<br/>But one that''s healthy and perfectly sound —<br/>There''s wonderful pow''r deep within!<br/>',NULL,14948,14948);
INSERT INTO stanza VALUES('BF258','1','We have an inner life; that''s for our daily life;<br/>That''s for the meeting life — just Christ!<br/>We''ll live the inner life; we''ll have the daily life;<br/>We''ll see the meeting life — that''s just the church.<br/>',NULL,14949,14949);
INSERT INTO stanza VALUES('BF258','2','Christ is our inner life; He''s in our spirit now;<br/>Not far away from us — He''s right inside!<br/>And as we turn to Him and take Him as our all<br/>He will become in us our inner life.<br/>',NULL,14950,14950);
INSERT INTO stanza VALUES('BF258','3','Out from our inner life will come our daily life,<br/>And all our living be filled up with Christ.<br/>Then as we live by Him, He lives His life in us,<br/>And He becomes to us our daily life.<br/>',NULL,14951,14951);
INSERT INTO stanza VALUES('BF258','4','The real experience of Christ in daily life,<br/>Will fill the meeting life with Christ Himself.<br/>Not empty forms and such, but Christ will be so much;<br/>And we will see Him here as the meeting life.<br/>',NULL,14952,14952);
INSERT INTO stanza VALUES('BF258','5','Without the inner life there is no daily life,<br/>There is no meeting life, there is no church!<br/>Christ as our inner life, Christ in our daily life<br/>Will make the meeting life new and glorious!<br/>',NULL,14953,14953);
INSERT INTO stanza VALUES('BF259','1','If from the world you''re longing to be free,<br/>Amen the Word of God!<br/>If you would live in all reality,<br/>Amen the Word of God!<br/>',NULL,14954,14954);
INSERT INTO stanza VALUES('BF259','chorus','Amen the Word of God!<br/>Amen the Word of God!<br/>His Word receiving, His Word believing,<br/>Amen the Word of God!<br/>',NULL,14955,14955);
INSERT INTO stanza VALUES('BF259','2','If with your sin and self you would be through,<br/>Amen the Word of God!<br/>If you would let the Lord your mind renew,<br/>Amen the Word of God!<br/>',NULL,14956,14956);
INSERT INTO stanza VALUES('BF259','chorus','Amen the Word of God!<br/>Amen the Word of God!<br/>His Word is living, life-power giving —<br/>Amen the Word of God!<br/>',NULL,14957,14957);
INSERT INTO stanza VALUES('BF259','3','Christ as the land of Canaan is our lot —<br/>Amen the Word of God!<br/>If you would enter, harden not your heart —<br/>Amen the Word of God!<br/>',NULL,14958,14958);
INSERT INTO stanza VALUES('BF259','chorus','Amen the Word of God!<br/>Amen the Word of God!<br/>His Word discerns us, all that concerns us —<br/>Amen the Word of God!<br/>',NULL,14959,14959);
INSERT INTO stanza VALUES('BF259','4','Jesus is coming, now He''s on His way —<br/>Amen the Word of God!<br/>Would you be ready if He comes today —<br/>Amen the Word of God!<br/>',NULL,14960,14960);
INSERT INTO stanza VALUES('BF259','chorus','Amen the Word of God!<br/>Amen the Word of God!<br/>His Word prepares us, to Jesus bears us —<br/>Amen the Word of God!<br/>',NULL,14961,14961);
INSERT INTO stanza VALUES('BF260','1','What a wonderful change in my living is wrought<br/>By saying Amen to God''s Word.<br/>More of Christ into me at each instance is brought<br/>By saying Amen to His Word.<br/>',NULL,14962,14962);
INSERT INTO stanza VALUES('BF260','chorus','By saying Amen to His Word,<br/>By saying Amen to His Word,<br/>Thus the Lord takes my heart,<br/>And transforms every part,<br/>By saying Amen to His Word.<br/>',NULL,14963,14963);
INSERT INTO stanza VALUES('BF260','2','What I never could do God is doing in me,<br/>By saying Amen to His Word.<br/>And the change is so real all the brothers can see,<br/>By saying Amen to God''s Word.<br/>',NULL,14964,14964);
INSERT INTO stanza VALUES('BF260','3','I have ceased from my wandering and going astray<br/>By saying Amen to God''s Word.<br/>And my old inclinations are passing away<br/>By saying Amen to His Word.<br/>',NULL,14965,14965);
INSERT INTO stanza VALUES('BF260','4','Now the secret of faith in the Lord I can see —<br/>It''s saying Amen to His Word.<br/>He is more real and precious than all things to me<br/>By saying Amen to His Word.<br/>',NULL,14966,14966);
INSERT INTO stanza VALUES('BF260','5','Now my love for the brothers abounds more and more<br/>By saying Amen to God''s Word.<br/>And I''m being related as never before<br/>By saying Amen to His Word.<br/>',NULL,14967,14967);
INSERT INTO stanza VALUES('BF260','6','Now my hope in the Lord''s soon return groweth bright<br/>By saying Amen to His Word.<br/>I am ready to see Him, my Lord, my delight,<br/>By saying Amen to His Word.<br/>',NULL,14968,14968);
INSERT INTO stanza VALUES('BF260','chorus','Lord Jesus, Amen to Your Word,<br/>Lord Jesus, Amen to Your Word.<br/>You are coming again — all my heart says Amen!<br/>Lord Jesus, Amen to Your Word!<br/>',NULL,14969,14969);
INSERT INTO stanza VALUES('BF261','1','I thirsted in the barren land of Babylon,<br/>And nothing satisfying there I found;<br/>But to the blessed local church one day I came,<br/>Where springs of living water do abound.<br/>',NULL,14970,14970);
INSERT INTO stanza VALUES('BF261','chorus','Drinking at the springs of living water,<br/>Happy now am I,<br/>My heart they satisfy;<br/>Drinking at the springs of living water,<br/>O wonderful and bountiful supply!<br/>',NULL,14971,14971);
INSERT INTO stanza VALUES('BF261','2','How sweet the living water from the hills of God,<br/>It''s flowing in and flowing out of me;<br/>O now I''ve found the place for which I long had sought,<br/>Where there is life and life abundantly.<br/>',NULL,14972,14972);
INSERT INTO stanza VALUES('BF261','3','O brothers, won''t you gather in the local church?<br/>A fountain here is flowing deep and wide.<br/>The Shepherd now would bring you to the local church,<br/>Where thirsty spirits can be satisfied.<br/>',NULL,14973,14973);
INSERT INTO stanza VALUES('BF262','1','The Lord, the seed of life, has sown Himself into our heart<br/>To grow up into fullness and become His counterpart.<br/>The seed requires no rules or forms, for water is its need —<br/>By this the all-inclusive seed will grow in us indeed!<br/>',NULL,14974,14974);
INSERT INTO stanza VALUES('BF262','chorus','The seed is simply Jesus!<br/>Oh, Jesus lives in me!<br/>And by His growth this seed<br/>In us will reach maturity.<br/>',NULL,14975,14975);
INSERT INTO stanza VALUES('BF262','2','The growth of Christ, the seed, in us will soon produce the wheat,<br/>The life within breaks forth — yet work divine is not complete;<br/>For wheat alone can never be the seed''s expression true;<br/>So all the grains must blend together into something new.<br/>',NULL,14976,14976);
INSERT INTO stanza VALUES('BF262','chorus','The seed is simply Jesus;<br/>Now wheat is Jesus too!<br/>The grains of wheat must blend<br/>Together into something new.<br/>',NULL,14977,14977);
INSERT INTO stanza VALUES('BF262','3','The individual grains of wheat no longer must be free,<br/>But crushed together, ground to powder, every grain must be,<br/>Until the wheat becomes the meal from which the loaf is formed<br/>Till all the saints will blend and to His Body be conformed.<br/>',NULL,14978,14978);
INSERT INTO stanza VALUES('BF262','chorus','We all must take the grinding<br/>Until the Christ within<br/>Can mold into His Body all the<br/>Individual grains.<br/>',NULL,14979,14979);
INSERT INTO stanza VALUES('BF262','4','The seed is planted, wheat is grown and meal is the sum<br/>Of all the growth upon God''s farm, where Christians grow as one;<br/>But all the growth in life is for the building of the church,<br/>That God and man may have a home and both may end their search.<br/>',NULL,14980,14980);
INSERT INTO stanza VALUES('BF262','chorus','The farm is for the building,<br/>For God and man a home,<br/>Where both may dwell among<br/>His people gathered into one.<br/>',NULL,14981,14981);
INSERT INTO stanza VALUES('BF262','5','God''s building is produced by silver, precious stones, and gold —<br/>From meal through transformation, pressure, heat, and pain untold.<br/>The meal must not be satisfied to stay as meal alone,<br/>But must submit to transformation into precious stone.<br/>',NULL,14982,14982);
INSERT INTO stanza VALUES('BF262','chorus','The meal must pass through suffering<br/>That precious stones be formed;<br/>Then built into God''s building, to His<br/>Purpose full conformed.<br/>',NULL,14983,14983);
INSERT INTO stanza VALUES('BF262','6','From fullest growth and transformation comes a pearl of worth;<br/>This simple, precious, all-inclusive gem will then come forth.<br/>Conceived in death and formed in life by that all-glorious One,<br/>The church, His Bride, the fruit of all the work that He has done.<br/>',NULL,14984,14984);
INSERT INTO stanza VALUES('BF262','chorus','The pearl is what He''s after,<br/>The Bride to please His heart,<br/>So single, pure and precious,<br/>And His very counterpart.<br/>',NULL,14985,14985);
INSERT INTO stanza VALUES('BF262','7','The growth in life begins when planted on God''s farm we''re found;<br/>The growing seed becomes the wheat from which the meal is ground.<br/>But building work proceeds when meal submits to be transformed;<br/>Then gold and silver, precious stones for building will be formed.<br/>',NULL,14986,14986);
INSERT INTO stanza VALUES('BF262','chorus','The farm is for the building,<br/>Built up by precious stones,<br/>From which the priceless pearl comes<br/>Forth to be His Bride, His own.<br/>',NULL,14987,14987);
INSERT INTO stanza VALUES('BF262','8','Lord, keep us poor in spirit, pure in heart that we may be<br/>Good ground in which the seed of life may grow abundantly,<br/>Until the final stage is reached and You are satisfied<br/>And have Your priceless, chosen pearl, Your joy complete, Your Bride.<br/>',NULL,14988,14988);
INSERT INTO stanza VALUES('BF262','chorus','Lord, keep us poor in spirit<br/>And purified in heart,<br/>That growing up in us You may<br/>Bring forth Your counterpart.<br/>',NULL,14989,14989);
INSERT INTO stanza VALUES('BF263','1','We are for the Lord''s recovery<br/>Of the local church;<br/>We are for the Lord''s recovery<br/>Of the city and the earth.<br/>Standing on the ground of oneness,<br/>Oneness in the Lord,<br/>We are building up the temple<br/>Of our glorious Lord.<br/>',NULL,14990,14990);
INSERT INTO stanza VALUES('BF263','chorus','We are for the Lord''s,<br/>We are for the Lord''s,<br/>We are for the Lord''s recovery!<br/>We are for the Lord''s,<br/>We are for the Lord''s,<br/>We are for the Lord''s recovery!<br/>',NULL,14991,14991);
INSERT INTO stanza VALUES('BF263','2','We are for the Lord''s recovery!<br/>To our hearts so dear;<br/>When we exercise our spirit,<br/>Our vision is so clear.<br/>Babylon the Great is fallen,<br/>Satan is cast down,<br/>And the local church is builded<br/>On the local ground.<br/>',NULL,14992,14992);
INSERT INTO stanza VALUES('BF264','1','What we are, we''re His image;<br/>We''re created in His image,<br/>To express the Christ, subdue the earth,<br/>The purpose of our second birth,<br/>We''re His image, glorious!<br/>',NULL,14993,14993);
INSERT INTO stanza VALUES('BF264','2','What we are, we''re the called ones,<br/>We''ve been called into the purpose.<br/>No longer low in Adam''s fall,<br/>God''s glory is our holy call.<br/>We''re the called ones, glorious!<br/>',NULL,14994,14994);
INSERT INTO stanza VALUES('BF264','3','What we are, we''re the joint-heirs;<br/>We inherit full salvation.<br/>We overcome and share His throne.<br/>All things today we fully own.<br/>We''re the joint-heirs, glorious!<br/>',NULL,14995,14995);
INSERT INTO stanza VALUES('BF264','4','What we are, we''re Christ''s partners:<br/>We share the same anointing.<br/>No longer we''re just serving Him;<br/>His riches we may all share in.<br/>We''re His partners, glorious!<br/>',NULL,14996,14996);
INSERT INTO stanza VALUES('BF264','5','What we are, we''re the brothers.<br/>We are all the holy brothers.<br/>The life of Christ we did obtain,<br/>For holiness the gold we gain.<br/>Holy brothers, glorious!<br/>',NULL,14997,14997);
INSERT INTO stanza VALUES('BF264','6','What we are, we''re the lampstand;<br/>We''re the shining forth of Jesus.<br/>In this world''s darkness, sin, and strife,<br/>We''re holding Christ, the light of life.<br/>We''re the lampstand, glorious.<br/>',NULL,14998,14998);
INSERT INTO stanza VALUES('BF265','1','Come ye! All the living stones now,<br/>Build up New Jerusalem,<br/>We shall never be molested,<br/>For the City''s fitly framed.<br/>',NULL,14999,14999);
INSERT INTO stanza VALUES('BF265','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,15000,15000);
INSERT INTO stanza VALUES('BF265','2','In recov''ry''s flow we plunge in,<br/>Pearls and precious stones produce,<br/>Build up with all saints in oneness,<br/>All self-seekings thus reduce.<br/>',NULL,15001,15001);
INSERT INTO stanza VALUES('BF265','3','All our spirit are in oneness,<br/>Will the building realize,<br/>Not of kinship, taste, and feeling,<br/>But one spirit unifies!<br/>',NULL,15002,15002);
INSERT INTO stanza VALUES('BF265','4','Not to shout void, empty slogans,<br/>But move in reality,<br/>We enjoy and serve together,<br/>Daily lab''ring faithfully.<br/>',NULL,15003,15003);
INSERT INTO stanza VALUES('BF265','5','The true building in spirit is,<br/>Living waters flow so free,<br/>With wheel in wheels moving swiftly,<br/>The four living creatures be.<br/>',NULL,15004,15004);
INSERT INTO stanza VALUES('BF265','6','Hallelujah! I''m so happy!<br/>Happy member now I''ll be,<br/>Set free from self-reservation,<br/>Into His economy<br/>',NULL,15005,15005);
INSERT INTO stanza VALUES('BF265','chorus','May the Lord my mind to transform,<br/>Heav''nly concept be impressed,<br/>That my speech and way of living,<br/>All for God alone express.<br/>',NULL,15006,15006);
INSERT INTO stanza VALUES('BF266','1','Oh, we have seen the church as one in perfect harmony;<br/>We sing and pray and testify of Christ''s reality.<br/>The local churches are His move for His recovery;<br/>And in the church, how rich He is!<br/>Oh, how we taste and see!<br/>',NULL,15007,15007);
INSERT INTO stanza VALUES('BF266','chorus','He''s the Real Love!<br/>That''s what Christ is to us,<br/>That''s what Christ is to us,<br/>The Real Love!<br/>',NULL,15008,15008);
INSERT INTO stanza VALUES('BF266','2','We eat and drink of Christ our King, oh, what a way to feed!<br/>The proper food, the local church, is really all we need.<br/>Digest the Word, and call "O Lord," and to our spirit heed;<br/>Meet with the saints in one accord —<br/>Oh, Christ is rich indeed!<br/>',NULL,15009,15009);
INSERT INTO stanza VALUES('BF266','3','The flow of love flows out from God through Jesus into us;<br/>The flow of love between the saints is sweet and glorious.<br/>The fellowship is so divine, it makes us really one;<br/>And in the flow the saints all grow<br/>Up into Christ the Son.<br/>',NULL,15010,15010);
INSERT INTO stanza VALUES('BF267','1','Since God is living, His true worshippers<br/>Will surely open up their mouths<br/>To speak forth Jesus in the Spirit since<br/>That''s what the gifts are all about.<br/>',NULL,15011,15011);
INSERT INTO stanza VALUES('BF267','chorus','Our speaking brings in the Spirit<br/>By which we''re ushered<br/>Into the Body.<br/>In the Body, the Lord preserves us<br/>In the Spirit for His work.<br/>',NULL,15012,15012);
INSERT INTO stanza VALUES('BF267','2','The speaking members manifest the Spirit.<br/>Thus, their gifts are exercised.<br/>These gifts, however are not for themselves<br/>But for the Body of Christ.<br/>',NULL,15013,15013);
INSERT INTO stanza VALUES('BF267','3','Let us forget our spirituality<br/>And only for the Body care.<br/>''Tis then the Lord will multipy our gifts<br/>And through us gain His heart''s desire.<br/>',NULL,15014,15014);
INSERT INTO stanza VALUES('BF268','1','The faith which once for all was giv''n<br/>Unto the saints of old,<br/>Has been committed unto us<br/>To guard, defend, and hold.<br/>',NULL,15015,15015);
INSERT INTO stanza VALUES('BF268','chorus','And we know whom we have believed<br/>And are persuaded that He is able<br/>To guard, through the Holy Spirit,<br/>Our deposit to that day.<br/>',NULL,15016,15016);
INSERT INTO stanza VALUES('BF268','2','This good deposit is the mark<br/>Of God''s economy,<br/>Without it we will miss the aim<br/>Of His recovery.<br/>',NULL,15017,15017);
INSERT INTO stanza VALUES('BF268','3','The myst''ry of the common faith,<br/>A conscience pure requires;<br/>A holy, separated life<br/>For us the Lord desires.<br/>',NULL,15018,15018);
INSERT INTO stanza VALUES('BF268','4','This outline of the healthy words,<br/>In faith and love we''ll hold;<br/>All different teaching, fruitless talk,<br/>Reject with spirit bold.<br/>',NULL,15019,15019);
INSERT INTO stanza VALUES('BF268','5','Oh, healthful teaching, wholesome words:<br/>The truth of godliness!<br/>Oh, good deposit, common faith,<br/>And life of holiness!<br/>',NULL,15020,15020);
INSERT INTO stanza VALUES('BF268','6','Lord, make us now those faithful men<br/>Who pass on what we''ve heard;<br/>Make us examples of the saints<br/>In spirit, faith, and word.<br/>',NULL,15021,15021);
INSERT INTO stanza VALUES('BF269','1','Christ comes quickly for His Bride,<br/>Wedding feast He will provide,<br/>Garments bright and pure supplied —<br/>Dress in time!<br/>Taking Christ as life she''s dressed,<br/>By much suffering stitched and pressed;<br/>Righteous acts are thus possessed —<br/>Dress in time!<br/>',NULL,15022,15022);
INSERT INTO stanza VALUES('BF269','chorus','Be in time! Be in time!<br/>For the marriage feast of Jesus<br/>Be in time!<br/>If your soul life you deny<br/>And the Spirit you apply,<br/>Then you''ll fully qualify —<br/>Be in time!<br/>',NULL,15023,15023);
INSERT INTO stanza VALUES('BF269','2','Virgins Christ comes quickly for,<br/>Those with oil an extra store,<br/>Not the fools who oil ignore —<br/>Buy in time!<br/>For the oil a price we pay,<br/>Deal with self without delay,<br/>Fill your vessels every day —<br/>Buy in time!<br/>',NULL,15024,15024);
INSERT INTO stanza VALUES('BF269','3','For His servants Christ will come<br/>And reward each faithful one;<br/>Slothful ones will be undone —<br/>Serve in time!<br/>Make your single talent count,<br/>All self''s problems now surmount,<br/>Serve with Christ, the living fount —<br/>Serve in time!<br/>',NULL,15025,15025);
INSERT INTO stanza VALUES('BF269','4','Christ comes quickly for His grain,<br/>Ripened firstfruits to obtain;<br/>Unripe harvest will remain —<br/>Ripen now!<br/>From earth''s water grain must dry,<br/>From the world your soul deny;<br/>To mature the self must die —<br/>Ripen now!<br/>',NULL,15026,15026);
INSERT INTO stanza VALUES('BF269','5','Overcomers Christ will take,<br/>Those who all for Him forsake,<br/>Those who of first love partake —<br/>Win in time!<br/>All the deadness overcome,<br/>With the living Christ be one,<br/>Toward the goal now swiftly run —<br/>Win in time!<br/>',NULL,15027,15027);
INSERT INTO stanza VALUES('BF269','6','Christ comes for His kingdom too;<br/>Heav''nly reign we must pursue,<br/>Let His rule our self subdue —<br/>Yield in time!<br/>Rebel self must be dethroned,<br/>Lessons must not be postponed,<br/>Quickly yield to Christ enthroned —<br/>Yield in time!<br/>',NULL,15028,15028);
INSERT INTO stanza VALUES('BF270','1','We love Thy coming, Lord!<br/>We know not when ''twill be,<br/>But turn from all distracting things<br/>Thine own dear face to see.<br/>',NULL,15029,15029);
INSERT INTO stanza VALUES('BF270','2','We serve the living God<br/>And wait His Son to see;<br/>For this we need faith, love, and hope,<br/>Increasing constantly.<br/>',NULL,15030,15030);
INSERT INTO stanza VALUES('BF270','3','In Thy dear presence, Lord,<br/>We hope we all may be<br/>A crown of glory and a joy<br/>To those we then shall see.<br/>',NULL,15031,15031);
INSERT INTO stanza VALUES('BF270','4','We love Thy coming, Lord;<br/>The time is very nigh.<br/>Our hearts unblameable must be<br/>To greet Thee from on high.<br/>',NULL,15032,15032);
INSERT INTO stanza VALUES('BF270','5','The Lord Himself shall come<br/>With loud assembling word,<br/>And all the saints in Christ shall be<br/>Forever with the Lord.<br/>',NULL,15033,15033);
INSERT INTO stanza VALUES('BF270','6','We''re children of the day,<br/>We''re children of the light;<br/>That day should never come to us<br/>As does a thief at night.<br/>',NULL,15034,15034);
INSERT INTO stanza VALUES('BF270','7','Lord, wholly sanctify<br/>And blameless let us be<br/>In spirit, soul, and body too<br/>For that blest day with Thee.<br/>',NULL,15035,15035);
INSERT INTO stanza VALUES('BF271','1','The day approaches; Jesus soon is coming.<br/>Redeem the time; it must not slip away.<br/>Lord, make us ready for the cry: "Behold Him!"<br/>By using every moment of each day.<br/>',NULL,15036,15036);
INSERT INTO stanza VALUES('BF271','chorus','When Jesus comes, will we go in to meet Him?<br/>When Jesus comes, will we from self have ceased?<br/>He''s coming soon to take the wise ones with Him.<br/>Oh, let us not be left outside the feast.<br/>',NULL,15037,15037);
INSERT INTO stanza VALUES('BF271','2','Lord, help us to redeem these golden moments;<br/>Our vessels fill with ointment from above;<br/>Help us amen each trial and tribulation;<br/>Increase in us; make us abound in love.<br/>',NULL,15038,15038);
INSERT INTO stanza VALUES('BF271','chorus','He''s coming soon — these moments are so precious.<br/>The oil is here — Oh, let us buy the more.<br/>Amen the trials and welcome tribulations —<br/>The kingdom''s ours through these afflictions sore.<br/>',NULL,15039,15039);
INSERT INTO stanza VALUES('BF271','3','Lord, ever turn us from our soulish pleasures<br/>To gaze upon Thy tender, loving face.<br/>Oh, keep us running forth to meet the Bridegroom<br/>And patiently attending to the race.<br/>',NULL,15040,15040);
INSERT INTO stanza VALUES('BF271','chorus','When Jesus comes, will we be in His presence?<br/>When Jesus comes, will we His face behold?<br/>Oh, let us not return to sloth and folly,<br/>But jealously His loving presence hold.<br/>',NULL,15041,15041);
INSERT INTO stanza VALUES('BF271','4','As His dear Bride, let us go forth to meet Him,<br/>Our lamps well-trimmed, our fires burning bright,<br/>Our vessels filled, our eyes set on His glory,<br/>To be with Him completely satisfied.<br/>',NULL,15042,15042);
INSERT INTO stanza VALUES('BF271','chorus','Yes, satisfied — Christ and His Bride together.<br/>Yes, satisfied — throughtout eternity.<br/>Oh, what a rest, what joy, what love, what favor<br/>To be His Bride when He comes to His feast!<br/>',NULL,15043,15043);
INSERT INTO stanza VALUES('BF272','1','In that bright and golden moment when the<br/>Christ we love shall come,<br/>And the radiance of His glory we shall see;<br/>When the Bride shall meet the Bridegroom and<br/>His loving wife become,<br/>What a meeting, what a meeting that will be!<br/>',NULL,15044,15044);
INSERT INTO stanza VALUES('BF272','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover,<br/>with our Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,15045,15045);
INSERT INTO stanza VALUES('BF272','2','When to all who love His coming He shall speak the word, "Arise!"<br/>Oh, how blessed for that summons to be free!<br/>With what rapture we shall greet Him as we<br/>join Him in the skies —<br/>What a meeting, what a meeting that will be!<br/>',NULL,15046,15046);
INSERT INTO stanza VALUES('BF272','3','Now in all the local churches we are meeting day by day<br/>And expecting any moment Christ to see,<br/>But when Jesus comes the meeting starts that ne''er will pass away —<br/>What a meeting, what a meeting that will be!<br/>',NULL,15047,15047);
INSERT INTO stanza VALUES('BF272','4','Even now while we are meeting, Lord, we hope to see Thy face<br/>And forever without ceasing be with Thee.<br/>Then we''ll just go right on meeting in another meeting place<br/>What a meeting, what a meeting this will be!<br/>',NULL,15048,15048);
INSERT INTO stanza VALUES('BF273','1','That which for long the prophets sought,<br/>The righteous yearned to see,<br/>Has in these last of days appeared<br/>In its reality.<br/>',NULL,15049,15049);
INSERT INTO stanza VALUES('BF273','chorus','And we''re now in the final stages,<br/>''Tis the completion of all the ages.<br/>All those who believed the promise<br/>Are perfected now in us.<br/>',NULL,15050,15050);
INSERT INTO stanza VALUES('BF273','2','Oh, blessed are our eyes that see,<br/>Our ears, how blessed to hear;<br/>Things angels ne''er could look into<br/>Are now to us made clear.<br/>',NULL,15051,15051);
INSERT INTO stanza VALUES('BF273','3','Our sense is corporate, bold and strong,<br/>His grace, how free to take;<br/>Encouraging the others on,<br/>Run for the kingdom''s sake.<br/>',NULL,15052,15052);
INSERT INTO stanza VALUES('BF273','4','We''re weary not this race to run,<br/>It makes our joy complete;<br/>For this we know, around the bend,<br/>The Lord we''ll surely meet.<br/>',NULL,15053,15053);
INSERT INTO stanza VALUES('BF274','1','Do you know that you were chosen<br/>Long before the world began;<br/>That by God you were selected<br/>And appointed for His plan?<br/>Something in your inmost being<br/>Tells you this is surely true;<br/>That''s why you are in this meeting,<br/>And you feel the way you do.<br/>',NULL,15054,15054);
INSERT INTO stanza VALUES('BF274','2','All the sins you''ve e''er committed,<br/>Everything you''ve ever done,<br/>All by God has been forgiven,<br/>Taken care of by God''s Son.<br/>Struggle not, no; just believe this,<br/>For His word assures it''s true;<br/>All you need to do is thank Him<br/>For all that He''s done for you.<br/>',NULL,15055,15055);
INSERT INTO stanza VALUES('BF274','3','Did you know that all the Bible<br/>Is a will, a testament?<br/>Everything that Christ accomplished<br/>Is for all God''s children meant.<br/>As His child you are included,<br/>For His word stands fast and true;<br/>So by faith you now inherit<br/>All that He has done for you.<br/>',NULL,15056,15056);
INSERT INTO stanza VALUES('BF274','4','Did you know God has a family?<br/>Yes, He does, in fact, it''s us.<br/>That''s why we are here enjoying<br/>All He is, so marvelous.<br/>He''s our God and we''re His people,<br/>Day by day we love Him more;<br/>We''re so happy and so thankful<br/>We just praise Him o''er and o''er.<br/>',NULL,15057,15057);
INSERT INTO stanza VALUES('BF274','5','All we know is that we love Him,<br/>We''re so glad for what He''s done;<br/>We are brought to Him, and we all<br/>Know the joy of being one.<br/>We''re so glad that we''re included,<br/>What a fellowship have we!<br/>So we''d like to welcome you, friend,<br/>Into God''s own family.<br/>',NULL,15058,15058);
INSERT INTO stanza VALUES('BF275','1','There''s a man Who died to set us free,<br/>Everybody knows it''s Jesus;<br/>He came down from heaven just to live in me,<br/>Everybody knows it''s Jesus!<br/>',NULL,15059,15059);
INSERT INTO stanza VALUES('BF275','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,15060,15060);
INSERT INTO stanza VALUES('BF275','2','There''s no other name on which to call,<br/>So open up and call on Jesus;<br/>Stop your doubting and start to call,<br/>Just open up and call on Jesus!<br/>',NULL,15061,15061);
INSERT INTO stanza VALUES('BF275','3','Religion never made it and it never will,<br/>All the people need is Jesus!<br/>Knowledge won''t help either, all it does is kill!<br/>The only need you have is Jesus!<br/>',NULL,15062,15062);
INSERT INTO stanza VALUES('BF275','4','Jesus fills the empty places with Himself,<br/>Come along and call, "Lord Jesus!"<br/>Listen closely while we tell you ''bout His wealth,<br/>Come along and call, "Lord Jesus!"<br/>',NULL,15063,15063);
INSERT INTO stanza VALUES('BF275','5','God''s been waiting just to get inside of you,<br/>So turn to Him and call, "Lord Jesus!"<br/>Open up your heart and let Him into you<br/>By calling on the name of Jesus!<br/>',NULL,15064,15064);
INSERT INTO stanza VALUES('BF276','1','I always knew deep down in me<br/>There was a longing to be free,<br/>A kind of hunger deep inside —<br/>To fill it up, I tried and tried<br/>There were a lot of things I had;<br/>Some things were good,<br/>Some things were bad,<br/>But all those things of mine before<br/>Don''t satisfy me any more.<br/>',NULL,15065,15065);
INSERT INTO stanza VALUES('BF276','chorus','Now life affords a real reward<br/>Whenever I just call, "O Lord!"<br/>The Triune God the Spirit is,<br/>And He can fill mine up with His.<br/>(repeat the last four lines)<br/>',NULL,15066,15066);
INSERT INTO stanza VALUES('BF276','2','I always knew deep down in me<br/>There was a longing to be free,<br/>A kind of hunger deep inside —<br/>But now it can be satisfied...<br/>Christ in my heart — the only way<br/>To spread within me day by day.<br/>Lord Jesus! Lord, I have to say<br/>You''re home in me and home to stay!<br/>',NULL,15067,15067);
INSERT INTO stanza VALUES('BF276','chorus','O Lord, I know now You will grow<br/>And from my spirit overflow!<br/>Now saturate me through and through!<br/>O Lord Jesus, I love You!<br/>(repeat the last four lines)<br/>',NULL,15068,15068);
INSERT INTO stanza VALUES('BF276','chorus','O Lord Jesus, I love You!<br/>O Lord Jesus, I love You!<br/>',NULL,15069,15069);
INSERT INTO stanza VALUES('BF277','1','Therefore being justified by faith,<br/>We have peace with God<br/>Through our Lord, Jesus Christ.<br/>',NULL,15070,15070);
INSERT INTO stanza VALUES('BF277','chorus','Because the love of God is shed abroad<br/>In our hearts by the Holy Spirit<br/>Which is given, which is given<br/>Unto us, to us, to us.<br/>',NULL,15071,15071);
INSERT INTO stanza VALUES('BF277','2','God had commandeth His love toward us,<br/>In that, while we were yet sinners,<br/>Christ died for us.<br/>',NULL,15072,15072);
INSERT INTO stanza VALUES('BF278','1','Praise the Lord, God sent His Son, Hallelujah!<br/>And salvation''s work was done, Glory to God!<br/>God Himself became a man,<br/>So that we might live in Him.<br/>',NULL,15073,15073);
INSERT INTO stanza VALUES('BF278','chorus','That''s why I call on Him,<br/>I give my all to Him.<br/>',NULL,15074,15074);
INSERT INTO stanza VALUES('BF278','2','For us He was crucified, Hallelujah!<br/>For the many, one Man died, Glory to God!<br/>One grain fell into the earth,<br/>Many grains to bring to birth.<br/>',NULL,15075,15075);
INSERT INTO stanza VALUES('BF278','3','He arose in victory, Hallelujah!<br/>From the grave, triumphantly, Glory to God!<br/>Now in resurrection He<br/>As the Spirit lives in me.<br/>',NULL,15076,15076);
INSERT INTO stanza VALUES('BF278','4','Call on Him from deep within, Hallelujah!<br/>Just by calling, He comes in, Glory to God!<br/>Once you call upon His name,<br/>Nevermore you''ll be the same.<br/>',NULL,15077,15077);
INSERT INTO stanza VALUES('BF278','chorus','We all must call on Him,<br/>We give our all to Him.<br/>',NULL,15078,15078);
INSERT INTO stanza VALUES('BF279','1','Lord, You were in the temple, teaching all the people<br/>Of Yourself as the Life.<br/>Meanwhile I was elsewhere, committing<br/>The biggest sin of my life.<br/>The Pharisees they found me,<br/>Dragged me through the street<br/>There midst the people I sat.<br/>"Teacher, we found this woman committing adultery<br/>We found her there in the act."<br/>',NULL,15079,15079);
INSERT INTO stanza VALUES('BF279','chorus','Great I Am, stooping down.<br/>To the ground so low where I was found.<br/>Where are they who say that you must die today?<br/>Woman, go and sin no more.<br/>',NULL,15080,15080);
INSERT INTO stanza VALUES('BF279','2','Down from the mountain You came,<br/>I approached You in shame<br/>I''m a leper You see.<br/>Sin and rebellion''s in me and I long to be free,<br/>If You''re willing, cleanse me.<br/>My destiny is to die, can You help me survive,<br/>Lord I know that You can.<br/>All others Lord run away,<br/>When they come see my face,<br/>Helpless, hopeless I am.<br/>',NULL,15081,15081);
INSERT INTO stanza VALUES('BF279','chorus','Stretching out Your hand unto me,<br/>How my heart was warmed when You touched me.<br/>With compassion moved, with love I never knew.<br/>By Your touch to me I''m healed.<br/>',NULL,15082,15082);
INSERT INTO stanza VALUES('BF279','3','I down to Jericho went,<br/>Met my robbers who stripped me<br/>And left me half dead.<br/>The priests and Levites ''cause<br/>They also travelled my way,<br/>Couldn''t help me a bit.<br/>But Lord You came to the earth,<br/>Despised and slandered,<br/>A Samaritan low.<br/>With divinity there and humanity''s care,<br/>Tender and merciful.<br/>',NULL,15083,15083);
INSERT INTO stanza VALUES('BF279','chorus','Bound my wounds and poured in oil and wine,<br/>Gave Your Spirit to me and life divine,<br/>To the church brought me where care I could receive,<br/>Jesus, You''re my Savior true.<br/>',NULL,15084,15084);
INSERT INTO stanza VALUES('BF280','1','The story of the gospel is that the Lord loved us<br/>The story of Mary is that she loved the Lord<br/>The Lord loving us and we loving Him.<br/>This the fragrance of our love offering.<br/>',NULL,15085,15085);
INSERT INTO stanza VALUES('BF280','2','We must preach both: The Lord loving us<br/>And we like Mary, loving Him to the uttermost<br/>One is salvation, the other consecration<br/>Lord, we pour out all our love offering.<br/>',NULL,15086,15086);
INSERT INTO stanza VALUES('BF280','3','As we pour upon Him, this is not just a waste<br/>But a fragrant testimony of the sweetness of the Lord.<br/>The Lord loving us and we loving Him.<br/>This the fragrance of our love offering.<br/>',NULL,15087,15087);
INSERT INTO stanza VALUES('BF280','4','Throughout all the centuries, tens of thousands precious lives<br/>Heart treasures, golden futures have been wasted upon the Lord.<br/>To such lovers He''s altogether lovely<br/>And ultimately worthy of their costly ointment.<br/>',NULL,15088,15088);
INSERT INTO stanza VALUES('BF280','5','We must love the Lord and grasp the opportunity<br/>Yes, love Him to the uttermost, fragrant sweet to God and man<br/>The Lord loving us and we loving Him:<br/>This the fragrance of our love offering.<br/>',NULL,15089,15089);
INSERT INTO stanza VALUES('BF280','6','Lord Jesus, we just love You.<br/>Our life and all we pour on You.<br/>We waste ourselves upon You.<br/>In this universe we just love You.<br/>We can''t help but love You, You''re the greatest value.<br/>Our love is just an issue of our seeing You.<br/>',NULL,15090,15090);
INSERT INTO stanza VALUES('BF281','1','I once denied the love of God and walked away.<br/>I turned my back on Him;<br/>I thought that I could live my life and leave Him there,<br/>Denying Him within.<br/>',NULL,15091,15091);
INSERT INTO stanza VALUES('BF281','chorus','But the Lord turned within my spirit<br/>And He kissed me with kisses of love.<br/>Now I''ll shout to all who can hear it,<br/>"I love Him, Jesus Christ my Lord."<br/>',NULL,15092,15092);
INSERT INTO stanza VALUES('BF281','2','My heart was hard, my eyes were closed, I didn''t see<br/>The hold He had on me.<br/>So trying the world and other things to find myself,<br/>I just found misery.<br/>',NULL,15093,15093);
INSERT INTO stanza VALUES('BF281','chorus','Then the Lord turned within my spirit<br/>And He kissed me with kisses of love.<br/>Now I''ll shout to all who can hear it,<br/>"I love Him, Jesus Christ my Lord."<br/>',NULL,15094,15094);
INSERT INTO stanza VALUES('BF281','3','His conquering love was stronger than my stubborn will,<br/>Yet gentle like a dove.<br/>Like a wax before a glowing fire He melts the heart;<br/>I could not fight His love.<br/>',NULL,15095,15095);
INSERT INTO stanza VALUES('BF281','chorus','When the Lord turned within my spirit<br/>And He kisses with kisses of love.<br/>Then my songs and my praises are flowing,<br/>"I love Thee, Jesus Christ my Lord."<br/>',NULL,15096,15096);
INSERT INTO stanza VALUES('BF282','1','Create in me a clean heart, O God,<br/>And renew a right spirit within me.<br/>Create in me a clean heart, O God,<br/>And renew a right spirit within me.<br/>',NULL,15097,15097);
INSERT INTO stanza VALUES('BF282','2','Cast me not away from Thy presence;<br/>Take not Thy holy Spirit from me.<br/>Restore unto me the joy of Thy salvation;<br/>And renew a right spirit within me.<br/>',NULL,15098,15098);
INSERT INTO stanza VALUES('BF283','chorus','Lord, Thou hast been our dwelling place<br/>In all generations.<br/>Before the mountains were brought forth,<br/>Or ever Thou hadst formed the earth and the world,<br/>Even from eternity to eternity, Thou art God.<br/>',NULL,15099,15099);
INSERT INTO stanza VALUES('BF283','1','For a thousand years in Thy sight are as yesterday,<br/>When it is past, and as a watch in the night.<br/>So teach us to number our days<br/>That we may apply our hearts unto wisdom.<br/>',NULL,15100,15100);
INSERT INTO stanza VALUES('BF283','2','O satisfy us early with Thy mercy;<br/>That we may rejoice and be glad all our days.<br/>Make us glad according to the days<br/>And the years wherein we have seen evil.<br/>',NULL,15101,15101);
INSERT INTO stanza VALUES('BF283','3','Let Thy work appear unto Thy servants,<br/>And Thy glory unto their children.<br/>And let the beauty of the Lord,<br/>The beauty of the Lord our God be upon us.<br/>',NULL,15102,15102);
INSERT INTO stanza VALUES('BF284','1','Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>',NULL,15103,15103);
INSERT INTO stanza VALUES('BF284','chorus','It is like the precious ointment upon the head,<br/>That ran down upon the beard,<br/>Even Aaron''s beard:<br/>That went down to the skirts of his garments.<br/>',NULL,15104,15104);
INSERT INTO stanza VALUES('BF284','2','Behold how good and how pleasant it is,<br/>For brethren to dwell together in unity!<br/>It is like the precious ointment upon the head,<br/>That ran down upon the beard,<br/>Even Aaron''s beard:<br/>That went down to the skirts of his garments.<br/>',NULL,15105,15105);
INSERT INTO stanza VALUES('BF284','3','As the dew of Hermon,<br/>And as the dew that descended<br/>Upon the mountains of Zion:<br/>For there the Lord commanded the blessing,<br/>Even life for evermore.<br/>',NULL,15106,15106);
INSERT INTO stanza VALUES('BF285','1','Seek the Lord while He may be found,<br/>Call upon Him while He is near:<br/>Let the wicked forsake his way,<br/>And the unrighteous man his thoughts:<br/>And let him return to the Lord,<br/>Unto our God,<br/>',NULL,15107,15107);
INSERT INTO stanza VALUES('BF285','2','And He will abundantly pardon,<br/>He will abundantly pardon you —<br/>Return to the Lord<br/>',NULL,15108,15108);
INSERT INTO stanza VALUES('BF286','1','Set your mind on the things that are above,<br/>Not on the things that are on earth.<br/>For you have died and your life,<br/>Is hid with Christ in God.<br/>When Christ who is our life,<br/>Shall appear then we also shall appear<br/>With Him in Glory!<br/>',NULL,15109,15109);
INSERT INTO stanza VALUES('BF287','chorus','O let us rejoice! O let us rejoice!<br/>Praise Him the Lord of all,<br/>Yes we now rejoice! Yes we now rejoice!<br/>Glory to Him for evermore.<br/>',NULL,15110,15110);
INSERT INTO stanza VALUES('BF287','1','O brothers, sisters, rise up,<br/>Sing to Him with spirit strong;<br/>Give to Him all glory, praises,<br/>For He is worthy indeed.<br/>',NULL,15111,15111);
INSERT INTO stanza VALUES('BF287','2','Our Lord has resurrected,<br/>He has risen from the dead.<br/>Seated in the heav''nly places,<br/>Far above all pow''r and might.<br/>',NULL,15112,15112);
INSERT INTO stanza VALUES('BF287','3','All things are under His feet,<br/>To the church He is the head.<br/>The church, the fullness of Him,<br/>Who filleth all in all.<br/>',NULL,15113,15113);
INSERT INTO stanza VALUES('BF287','4','Jesus, the name of all names<br/>Every knee to Him shall bow,<br/>Every tongue His name must confess,<br/>Glory to God the Father.<br/>',NULL,15114,15114);
INSERT INTO stanza VALUES('BF287','chorus','O, Hallelujah! O, Hallelujah!<br/>Sing praise, sing praise unto Him.<br/>O, Hallelujah! O, Hallelujah!<br/>The King of kings, the Lord of lords.<br/>',NULL,15115,15115);
INSERT INTO stanza VALUES('BF288','1','From my spirit, when I''m sensing the supply<br/>Of God''s speaking, from a fount that ne''er runs dry,<br/>And within me comes a fresh and sweet supply,<br/>Then I''ve got to open up and water you.<br/>',NULL,15116,15116);
INSERT INTO stanza VALUES('BF288','chorus','Water you, water you<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I''ll surely testify,<br/>I''ll stand up, release my Christ and water you!<br/>',NULL,15117,15117);
INSERT INTO stanza VALUES('BF288','2','In the meeting, when the spirit''s rising high,<br/>And it seems like we will go beyond the sky —<br/>I can''t help it, I must speak or else I''ll die,<br/>For my Christ is rising up to water you.<br/>',NULL,15118,15118);
INSERT INTO stanza VALUES('BF288','3','Should a pause come, or the meeting ebb real low,<br/>While within me there''s a rich and living flow,<br/>Then I''ll stand up, so that all the saints will know,<br/>That I''m here to share my Christ and water you.<br/>',NULL,15119,15119);
INSERT INTO stanza VALUES('BF288','4','In the church life, in our daily living too,<br/>In the meeting, and in everything we do,<br/>Christ is speaking and the Spirit''s breaking through,<br/>That is why there''s the supply to water you.<br/>',NULL,15120,15120);
INSERT INTO stanza VALUES('BF289','1','Have you found your human spirit?<br/>It''s connected to your mouth!<br/>"Hallelujah — O Lord Jesus,"<br/>That''s the way to let it out!<br/>',NULL,15121,15121);
INSERT INTO stanza VALUES('BF289','chorus','What is born of Spirit is just the spirit,<br/>And the two spirits are one.<br/>What is born of Spirit is just the spirit,<br/>And the two spirits are one.<br/>',NULL,15122,15122);
INSERT INTO stanza VALUES('BF289','2','Don''t wait for the inspiration —<br/>Don''t be trapped by Satan''s trick.<br/>Open up! Release your spirit,<br/>Testifying you''re so free.<br/>',NULL,15123,15123);
INSERT INTO stanza VALUES('BF290','1','Now Christ is the Life-giving Spirit,<br/>Now Christ is the Spirit today,<br/>Now Christ is the Life-giving Spirit,<br/>So turn to your spirit and say;<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>',NULL,15124,15124);
INSERT INTO stanza VALUES('BF290','2','Now Christ is the Life-giving Spirit,<br/>That Spirit dwells within me too;<br/>Now Christ is the Life-giving Spirit,<br/>Transforms me to His image true.<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>',NULL,15125,15125);
INSERT INTO stanza VALUES('BF291','1','O let''s enjoy Christ''s richness together,<br/>For our Lord is the Spirit, life-giver.<br/>In our spirit He dwelleth, His life He giveth<br/>To supply, anoint and transform us.<br/>Wonder of wonders is that our Lord is one with us.<br/>We will shout and we''ll sing:<br/>"Hallelujah, Praise the Lord!"<br/>O let''s enjoy altogether Christ''s riches,<br/>Fully feast on His all-inclusiveness.<br/>',NULL,15126,15126);
INSERT INTO stanza VALUES('BF292','1','Whene''er I call Lord Jesus<br/>Sure it sets my heart aglow;<br/>Just to feel His life arising<br/>That Christ in me may grow.<br/>Just call with us, "Lord Jesus,"<br/>It''s the greatest joy on earth.<br/>And then Christ will come into you,<br/>You will have another birth.<br/>',NULL,15127,15127);
INSERT INTO stanza VALUES('BF292','2','Just call with us, "Lord Jesus,"<br/>He will surely set you free,<br/>If your heart is far, far from Him,<br/>Wherever you may be.<br/>We simply call upon Him,<br/>No matter where you are.<br/>And calling — this, He enters,<br/>Oh, He''s never very far.<br/>',NULL,15128,15128);
INSERT INTO stanza VALUES('BF292','3','Just call upon our Savior,<br/>Sure He''ll hear you everytime.<br/>Lean your weary head upon Him<br/>And rest in sweet recline.<br/>For He is our strong fortress.<br/>Our peace, our joy, our rest.<br/>When we taste the grace of Jesus,<br/>Sure we''re tasting the very best.<br/>',NULL,15129,15129);
INSERT INTO stanza VALUES('BF292','4','The best is just Himself now,<br/>And Himself He freely gave.<br/>So let''s open up to Him now,<br/>And by His life be saved.<br/>And when He comes to meet us,<br/>As His bride we''ll ready be.<br/>If today He grows within us,<br/>We shall then His glory see.<br/>',NULL,15130,15130);
INSERT INTO stanza VALUES('BF293','1','Jesus Lord, Jesus Lord<br/>How we long to touch Thee.<br/>More and more, more and more.<br/>That You may grow within us,<br/>"Blossom of Gold" may You bloom and grow,<br/>Bloom and grow forever...<br/>All will see, all will know<br/>You are the Lord within us.<br/>',NULL,15131,15131);
INSERT INTO stanza VALUES('BF294','1','On your mark, get set, run the race of life;<br/>There''s a prize awaiting you.<br/>Lay aside ev''ry weight, each besetting sin,<br/>Keep the heav''nly goal in view.<br/>Witnesses all around watching as you run,<br/>Never falter, Never fall;<br/>On your mark, get set, run the race of life,<br/>There''s a prize awaiting you.<br/>',NULL,15132,15132);
INSERT INTO stanza VALUES('BF295','1','I don''t know about tomorrow,<br/>I just live from day to day.<br/>I don''t borrow from its sunshine,<br/>For its skies may turn to gray.<br/>I don''t worry o''er the future,<br/>For I know what Jesus said,<br/>And today I''ll walk beside Him,<br/>For He knows what is ahead.<br/>',NULL,15133,15133);
INSERT INTO stanza VALUES('BF295','chorus','Many things about tomorrow,<br/>I don''t seem to understand;<br/>But I know who holds tomorrow,<br/>And I know who holds my hand.<br/>',NULL,15134,15134);
INSERT INTO stanza VALUES('BF295','2','I don''t know about tomorrow,<br/>It may bring me poverty;<br/>But the One who feeds the sparrow,<br/>Is the One who lives in me.<br/>And the path that be my portion,<br/>May be through the flame or flood,<br/>But His presence goes before me,<br/>Bravely His path I will trod.<br/>',NULL,15135,15135);
INSERT INTO stanza VALUES('BF296','1','It''s a new, living meeting that we''re having today.<br/>We are meeting in spirit and we worship this way,<br/>We enjoy the reality of Christ as all,<br/>And leave all of the shadows when on Jesus we call!<br/>',NULL,15136,15136);
INSERT INTO stanza VALUES('BF296','chorus','It''s a new, living meeting in a new, living way.<br/>At the beaches, the schools, the parks —<br/>wherever we may.<br/>We are slaying the ord''nances, religion too.<br/>Hallelujah! The Spirit of the Lord''s breaking through.<br/>',NULL,15137,15137);
INSERT INTO stanza VALUES('BF296','2','We don''t care for religion, we don''t care for the form,<br/>We don''t care for opinions, regulations or norms.<br/>We don''t care for the doctrines that will kill us dead —<br/>Hallelujah! We''re free in our spirit instead!<br/>',NULL,15138,15138);
INSERT INTO stanza VALUES('BF296','3','It''s a new, living meeting, no more oldness we''ll bear,<br/>In the singing, pray-reading it is Christ that we share.<br/>No more old-fashioned meeting in the old, old way.<br/>Hallelujah! The Lord is doing new things today.<br/>',NULL,15139,15139);
INSERT INTO stanza VALUES('BF297','1','When Jesus comes to reward His servants,<br/>Whether it be noon or night;<br/>Faithful to Him will He find us watching,<br/>With our lamps all trimmed and bright?<br/>',NULL,15140,15140);
INSERT INTO stanza VALUES('BF297','chorus','Oh, can we say we are ready, brothers?<br/>Ready for the soul''s bright home?<br/>Say, will He find you and me still watching,<br/>Waiting, waiting when the Lord shall come?<br/>',NULL,15141,15141);
INSERT INTO stanza VALUES('BF297','2','If at the dawn of the early morning,<br/>He shall call us one by one;<br/>When to the Lord we restore our talents,<br/>Will He answer thee, "Well done!"?<br/>',NULL,15142,15142);
INSERT INTO stanza VALUES('BF297','3','Have we been true to the trust He left us?<br/>Do we seek to do our best?<br/>If in our hearts there is naught condemns us,<br/>We shall have a glorious rest.<br/>',NULL,15143,15143);
INSERT INTO stanza VALUES('BF297','4','Blessed are those whom the Lord finds watching,<br/>In His glory they shall share;<br/>If He shall come at the dawn or midnight,<br/>Will He find us watching there?<br/>',NULL,15144,15144);
INSERT INTO stanza VALUES('BF298','1','There is a bright new life that''s so exciting<br/>And you can have this life if you decide.<br/>The Lord can fill that lonely empty feeling<br/>He''ll give you joy and happiness inside.<br/>Now you don''t have to fully understand it,<br/>Or try to comprehend the hows and whys;<br/>But He will give you more than you could hope for,<br/>Much more than you could ever realize.<br/>',NULL,15145,15145);
INSERT INTO stanza VALUES('BF298','2','You can experience something that is wonderful.<br/>You can experience something that is grand.<br/>You can experience something that is marvelous;<br/>If you let the Savior take you by the hand;<br/>There is a bright new life that''s so exciting<br/>And you can have this life if you decide.<br/>The Lord can fill that lonely empty feeling<br/>He''ll give you joy and happiness inside.<br/>',NULL,15146,15146);
INSERT INTO stanza VALUES('BF299','1','Now the Triune God has come to dwell within<br/>As the wonderful Spirit in us.<br/>We are mingled with the Lord, we''re one with Him<br/>As the life-giving Spirit in us.<br/>',NULL,15147,15147);
INSERT INTO stanza VALUES('BF299','chorus','Oh, He''s the wonderful Spirit in us!<br/>He''s the wonderful Spirit in us!<br/>God is in the Son, the Son''s the Spirit now —<br/>He''s the wonderful Spirit in us!<br/>',NULL,15148,15148);
INSERT INTO stanza VALUES('BF299','2','"Abba Father" is the cry from deep within<br/>From the wonderful Spirit in us.<br/>''Tis the Spirit of the Son who cries to Him<br/>As the life-giving Spirit in us.<br/>',NULL,15149,15149);
INSERT INTO stanza VALUES('BF299','3','Jesus Christ the Lord is living now in us<br/>As the wonderful Spirit within.<br/>He has been transfigured, we enjoy Him thus,<br/>As the life-giving Spirit within.<br/>',NULL,15150,15150);
INSERT INTO stanza VALUES('BF299','4','Now the Spirit of reality is here<br/>As the wonderful Spirit within.<br/>Now the things of Christ are all so real and clear<br/>By the life-giving Spirit within.<br/>',NULL,15151,15151);
INSERT INTO stanza VALUES('BF299','5','We will all stir up this gift that''s deep within<br/>As the wonderful Spirit in us.<br/>When we call "Lord Jesus" how our spirits spring<br/>With this life-giving Spirit in us!<br/>',NULL,15152,15152);
INSERT INTO stanza VALUES('BF300','1','God has saved me from the world;<br/>I''ll never go back anymore.<br/>God has saved me from the world;<br/>I''ll never go back anymore.<br/>',NULL,15153,15153);
INSERT INTO stanza VALUES('BF300','chorus','No, no, no, no, no,<br/>I''ll never go back anymore.<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,15154,15154);
INSERT INTO stanza VALUES('BF300','2','I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>',NULL,15155,15155);
INSERT INTO stanza VALUES('BF300','3','Since I found the local church,<br/>I''ll never go back anymore.<br/>Since I found the local church,<br/>I''ll never go back anymore.<br/>',NULL,15156,15156);
INSERT INTO stanza VALUES('BF300','4','Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>',NULL,15157,15157);
INSERT INTO stanza VALUES('BF300','5','Christ is everything to me;<br/>I''ll never go back anymore.<br/>Christ is everything to me;<br/>I''ll never go back anymore.<br/>',NULL,15158,15158);
INSERT INTO stanza VALUES('BF300','6','Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>',NULL,15159,15159);
INSERT INTO stanza VALUES('BF300','7','I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>',NULL,15160,15160);
INSERT INTO stanza VALUES('BF301','1','We''re feeding on the living bread,<br/>We''re drinking at the fountainhead;<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again.<br/>What, never thirst again? No, never thirst again!<br/>What, never thirst again? No, never thirst again!<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again!<br/>',NULL,15161,15161);
INSERT INTO stanza VALUES('BF301','2','We are feeding on the living bread,<br/>Eating of the feast our Lord has spread,<br/>And whoso eateth, Jesus said,<br/>Shall hunger nevermore.<br/>What, hunger nevermore? Yes, hunger nevermore!<br/>What, hunger nevermore? Yes, hunger nevermore!<br/>And whoso eateth, Jesus said,<br/>Shall hunger nevermore.<br/>',NULL,15162,15162);
INSERT INTO stanza VALUES('BF301','3','We are breathing in the living air,<br/>Breathing in the One whose life we share,<br/>And whoso breatheth — now, fore''er —<br/>Shall have the life of God.<br/>What, have the life of God? Yes, have the life of God!<br/>What, have the life of God? Yes, have the life of God!<br/>And whoso breatheth — now, fore''er —<br/>Shall have the life of God.<br/>',NULL,15163,15163);
INSERT INTO stanza VALUES('BF301','4','We are tasting of the living wine,<br/>In spirit tasting life divine,<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>What, have the joy of God? Yes, have the joy of God!<br/>What, have the joy of God? Yes, have the joy of God!<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>',NULL,15164,15164);
INSERT INTO stanza VALUES('BF301','5','Christ is the resurrected King,<br/>Who died and rose, our life to bring,<br/>If you receive Him you will sing,<br/>And live forevermore.<br/>What, live forevermore? Yes, live forevermore!<br/>What, live forevermore? Yes, live forevermore!<br/>If you receive Him you will sing,<br/>And live forevermore.<br/>',NULL,15165,15165);
INSERT INTO stanza VALUES('BF302','1','To Jesus every day we find our hearts are closer drawn;<br/>He''s fairer than the sons of men and fresher than the morn;<br/>He''s all that we can say of Him in fairest words and more,<br/>And every day He''s dearer than He was the day before.<br/>',NULL,15166,15166);
INSERT INTO stanza VALUES('BF302','chorus','The half cannot be fancied of such a treasure-store,<br/>And every day He''s dearer than He ever was before!<br/>',NULL,15167,15167);
INSERT INTO stanza VALUES('BF302','2','His glory broke upon us when we saw Him in the church,<br/>For here are all His riches, here we''ve given up our search;<br/>''Tis here He satisfies our longing spirits o''er and o''er,<br/>And every day He''s dearer than He was the day before.<br/>',NULL,15168,15168);
INSERT INTO stanza VALUES('BF302','3','Now He''s the living Spirit who within our spirit dwells,<br/>And by His sweet anointing, how His life within us swells!<br/>As with the saints we''re meeting, full released our spirits soar,<br/>For now our Lord is dearer than He ever was before.<br/>',NULL,15169,15169);
INSERT INTO stanza VALUES('BF302','4','The Lord has made us one with Him for His recovery:<br/>The riches of this Christ, the church His fullness, men must see.<br/>Yes, all we have and all we are, we every day outpour<br/>For His tremendous purpose, ever dearer than before.<br/>',NULL,15170,15170);
INSERT INTO stanza VALUES('BF303','1','God''s intention in this universe is with humanity,<br/>So the Lord became the Spirit just with man to mingled be.<br/>We rejoice that we can all partake of His economy.<br/>Yes, mingling is the way.<br/>',NULL,15171,15171);
INSERT INTO stanza VALUES('BF303','chorus','Mingle, mingle, hallelujah,<br/>Mingle, mingle, hallelujah,<br/>Mingle, mingle, hallelujah,<br/>Yes, mingling is the way!<br/>',NULL,15172,15172);
INSERT INTO stanza VALUES('BF303','2','In the center of our being, past our mind, emotion, will,<br/>Is a certain spot created to contain the Lord until<br/>By His flowing and His flooding He will all our being fill;<br/>Yes, mingling is the way.<br/>',NULL,15173,15173);
INSERT INTO stanza VALUES('BF303','3','Now within the Lord''s recov''ry, we''re so glad to find the way<br/>To experience the Triune God and live by Him today —<br/>Get into the mingled spirit, and within the spirit stay;<br/>Yes, mingling is the way.<br/>',NULL,15174,15174);
INSERT INTO stanza VALUES('BF303','4','In the midst of seven lampstands, now the Son of Man we see;<br/>Eyes ablaze and feet a''burning, He''s for God''s recovery.<br/>God''s intention He''s accomplishing — a corporate entity;<br/>Yes, mingling is the way.<br/>',NULL,15175,15175);
INSERT INTO stanza VALUES('BF303','5','In our daily life and all we are and do and think and say,<br/>How we need a deeper mingling just to gain the Lord each day;<br/>Lord, we give ourselves completely just to take the mingled way.<br/>Yes, mingling is the way.<br/>',NULL,15176,15176);
INSERT INTO stanza VALUES('BF303','6','From the fruit of daily living, New Jerusalem we''ll see,<br/>It''s the ultimate in mingling — it''s divine humanity<br/>And what joy that we can share it all, and share it corporately.<br/>Yes, mingling is the way.<br/>',NULL,15177,15177);
INSERT INTO stanza VALUES('BF304','1','Our God is living — say, Hallelujah!<br/>He''s living in us — say, Hallelujah!<br/>We taste His riches,<br/>He is our portion —<br/>Just say “O Lord” to taste and see.<br/>',NULL,15178,15178);
INSERT INTO stanza VALUES('BF304','2','We come together — there''s nothing better<br/>For in the Spirit we are His family.<br/>His living Body!<br/>We just express Him.<br/>Jesus is our reality.<br/>',NULL,15179,15179);
INSERT INTO stanza VALUES('BF304','3','In all the churches we''re being filled now<br/>For the saturation throughout the nation,<br/>To spread our Jesus<br/>To every city —<br/>This land will see the living Christ.<br/>',NULL,15180,15180);
INSERT INTO stanza VALUES('BF305','1','Jesus, our wonderful Shepherd<br/>Brought us right out of the fold<br/>Into His pasture so plenteous,<br/>Into His riches untold.<br/>',NULL,15181,15181);
INSERT INTO stanza VALUES('BF305','chorus','Glorious church life,<br/>Feasting from such a rich store!<br/>Here where we''re dwelling in oneness<br/>God commands life evermore.<br/>',NULL,15182,15182);
INSERT INTO stanza VALUES('BF305','2','In the divisions He sought us,<br/>Weary and famished for food;<br/>Into the good land He brought us,<br/>Oh, to our spirit how good!<br/>',NULL,15183,15183);
INSERT INTO stanza VALUES('BF305','3','Jesus Himself is our pasture,<br/>He is the food that we eat;<br/>We as His sheep are fed richly<br/>Each time, whenever we meet.<br/>',NULL,15184,15184);
INSERT INTO stanza VALUES('BF305','4','Dwell we here on a high mountain,<br/>Wet with the morning-fresh dew,<br/>Slaking our thirst at the fountain,<br/>Water so living and new.<br/>',NULL,15185,15185);
INSERT INTO stanza VALUES('BF305','5','Christ is our rest and enjoyment,<br/>Here we have nothing to fear;<br/>Here all the sheep dwell securely,<br/>Kept by His presence so dear.<br/>',NULL,15186,15186);
INSERT INTO stanza VALUES('BF306','1','O home in the church,<br/>Where we''ve ended our search<br/>With the brothers rejoicing all day;<br/>Where Christ is our life,<br/>And we''re through with all strife,<br/>Now we''re home, hallelujah, to stay!<br/>',NULL,15187,15187);
INSERT INTO stanza VALUES('BF306','chorus','Home, home in the church;<br/>Yes, it''s here that we''ve ended our search;<br/>And through all our days<br/>We will shout to His praise,<br/>"Hallelujah for Christ and the Church!"<br/>',NULL,15188,15188);
INSERT INTO stanza VALUES('BF306','2','Here God is at rest,<br/>Of His treasures the best —<br/>How His heart is rejoicing all day!<br/>His home is our heart,<br/>Ne''er for Satan a part,<br/>Here His glory He''ll fully display.<br/>',NULL,15189,15189);
INSERT INTO stanza VALUES('BF306','chorus','God''s home is the church;<br/>Yes, it''s here that He ended His search;<br/>And through all our days<br/>We will shout to His praise,<br/>“Hallelujah for Christ and the church!”<br/>',NULL,15190,15190);
INSERT INTO stanza VALUES('BF307','1','Once by nature we were dead in sin,<br/>In a world of utter discord;<br/>But together God has quickened us,<br/>Raised us up to sit together with the Lord.<br/>',NULL,15191,15191);
INSERT INTO stanza VALUES('BF307','chorus','Jesus is getting us together,<br/>Come and see the saints in one accord.<br/>His love is knitting us together,<br/>To the stature of the fullness of the Lord.<br/>',NULL,15192,15192);
INSERT INTO stanza VALUES('BF307','2','Thus with all saints we can apprehend,<br/>All the vast dimensions of God.<br/>Knowing Christ''s love passes all we know,<br/>We''re together filled to fullness with our God.<br/>',NULL,15193,15193);
INSERT INTO stanza VALUES('BF307','3','Now we know the purpose of our God,<br/>Visible the mystery became:<br/>Christ, the church, together now we see,<br/>And together put the enemy to shame.<br/>',NULL,15194,15194);
INSERT INTO stanza VALUES('BF307','4','For this cause we pray the Father God —<br/>Strengthen Thou with might our inner man;<br/>Make Yourself at home in all our hearts,<br/>Root us, ground us in Your love and for Your plan.<br/>',NULL,15195,15195);
INSERT INTO stanza VALUES('BF307','5','In the Body we''ll be fitly framed<br/>As the many members Christ supply;<br/>Working in the measure of each part,<br/>All by growth in love the Body edify.<br/>',NULL,15196,15196);
INSERT INTO stanza VALUES('BF307','6','Now we''re one His purpose to fulfill,<br/>As the one new man of His plan.<br/>Unto Him be glory in the church,<br/>And in Jesus Christ forevermore — Amen!<br/>',NULL,15197,15197);
INSERT INTO stanza VALUES('BF308','1','Deeper, deeper, in the cross of Jesus;<br/>Deeper let me go;<br/>Death and life, they always go together;<br/>Deepen, Lord, the flow.<br/>Oh, deeper yet we pray,<br/>Do work in us each day;<br/>Go deeper, through and through,<br/>Till in Thee we''re wholly new.<br/>',NULL,15198,15198);
INSERT INTO stanza VALUES('BF308','2','Higher, higher, in the life of Jesus;<br/>Lord, we are so low.<br/>By Thy life we all can go much higher —<br/>Higher let us go.<br/>Oh, higher yet we pray —<br/>Transform us every day —<br/>And richer in the flow;<br/>May Thy life be all we know.<br/>',NULL,15199,15199);
INSERT INTO stanza VALUES('BF308','3','Growing, growing, in us He is growing,<br/>More and more each day.<br/>Into all our living He is flowing —<br/>This is now His way.<br/>For growth, O Lord, we pray;<br/>Increase in us each day.<br/>It''s not enough to know;<br/>Now Thy life in us must grow.<br/>',NULL,15200,15200);
INSERT INTO stanza VALUES('BF308','4','Living, living, Christ is all our living,<br/>He''s so practical:<br/>Small things, big things, anything and all things —<br/>He''s involved in all.<br/>Live Christ in every way;<br/>Oh, live Him out today.<br/>His name you now must call,<br/>And give Him your all for all.<br/>',NULL,15201,15201);
INSERT INTO stanza VALUES('BF308','5','Person, Person, Jesus is our Person,<br/>Living now in us.<br/>He''s our tastes, our attitudes and actions;<br/>Oh, how glorious!<br/>Our Person, Lord, Thou art;<br/>Make home in all our heart.<br/>As life in every way<br/>Be our Person, Lord, each day.<br/>',NULL,15202,15202);
INSERT INTO stanza VALUES('BF308','6','Churches, churches, in the local churches<br/>We all find the flow:<br/>Deeper, higher, Christ as all our living,<br/>For the church we grow.<br/>The churches are today<br/>Just Christ in every way.<br/>For this, from self we cease,<br/>For Thy Body, Thine increase.<br/>',NULL,15203,15203);
INSERT INTO stanza VALUES('BF308','7','Building, building, we will see the building<br/>Of the church this way:<br/>Christ experienced will produce the building —<br/>He''s the only way.<br/>Oh, build us, Lord, we pray,<br/>By growth of life each day.<br/>Oh, make us now such men<br/>For the new Jerusalem.<br/>',NULL,15204,15204);
INSERT INTO stanza VALUES('BF308','8','Coming, coming, Jesus soon is coming<br/>For His chosen Bride.<br/>In the churches we are all preparing<br/>To be glorified.<br/>Lord Jesus, come again —<br/>This cry is deep within.<br/>We''ll praise Thee to the end,<br/>Oh, come back! Come back! Amen!<br/>',NULL,15205,15205);
INSERT INTO stanza VALUES('BF309','1','Recall how David swore,<br/>"I''ll not come into my house,<br/>Nor go up to my bed,<br/>Give slumber to mine eyelids,<br/>Until I find a place for Thee,<br/>A place, O Lord, for Thee."<br/>Our mighty God desires a home<br/>Where all His own may come.<br/>',NULL,15206,15206);
INSERT INTO stanza VALUES('BF309','2','How blinded we have been,<br/>Shut in with what concerns us;<br/>While God''s house lieth waste —<br/>Lord, break through, overturn us;<br/>We''ll go up to the mountain,<br/>Bring wood and build the house;<br/>We''ll never say, "Another day!"<br/>It''s time! We''ll come and build!<br/>',NULL,15207,15207);
INSERT INTO stanza VALUES('BF309','3','O Lord, against these days,<br/>Inspire some for Your building,<br/>Just as in David''s day —<br/>A remnant who are willing<br/>To come and work in Your house,<br/>Oh, what a blessed charge!<br/>Your heart''s desire, is our desire —<br/>We come, O Lord, to build.<br/>',NULL,15208,15208);
INSERT INTO stanza VALUES('BF309','4','Within those whom You''d call<br/>Put such a restless caring<br/>For building to give all —<br/>These times are for preparing;<br/>The gates of hell cannot prevail<br/>Against the builded Church!<br/>The hours are few, the builders too —<br/>Lord, build, O build in us!<br/>(Repeat the last four lines)<br/>',NULL,15209,15209);
INSERT INTO stanza VALUES('BF310','1','To Jerusalem we''ve come,<br/>We are through with Babylon,<br/>We have gathered to be one,<br/>O glory be to God!<br/>Of the teachings we''re bereft,<br/>All opinions we have left,<br/>Spirit from the soul is cleft,<br/>In the local churches now.<br/>',NULL,15210,15210);
INSERT INTO stanza VALUES('BF310','chorus','Hallelujah! Hallelujah!<br/>We are all in one accord<br/>For the building of the Lord,<br/>Hallelujah! Hallelujah!<br/>We are living in the local churches now!<br/>',NULL,15211,15211);
INSERT INTO stanza VALUES('BF310','2','That recovery may proceed<br/>Real priests are what we need —<br/>Those who live in Christ indeed,<br/>O glory be to God!<br/>Saturated with the Lord,<br/>They have Christ as their reward.<br/>These the building work afford<br/>In the local churches now.<br/>',NULL,15212,15212);
INSERT INTO stanza VALUES('BF310','3','And the kingship we must see<br/>With divine authority —<br/>To this rule we''ll all agree,<br/>O glory be to God!<br/>To the Spirit we''ll submit<br/>For the church''s benefit —<br/>This is His prerequisite<br/>In the local churches now.<br/>',NULL,15213,15213);
INSERT INTO stanza VALUES('BF310','4','We the altar must obtain,<br/>Have our all upon it lain.<br/>The burnt-offering must be slain,<br/>O glory be to God!<br/>This we never should dispute,<br/>For the church be absolute,<br/>All that''s otherwise uproot<br/>In the local churches now.<br/>',NULL,15214,15214);
INSERT INTO stanza VALUES('BF310','5','The foundation now is laid —<br/>O what glory doth pervade!<br/>We are all with joy arrayed,<br/>O glory be to God!<br/>Let us raise a mighty shout —<br/>They will hear us far without,<br/>And the enemy we''ll rout<br/>In the local churches now.<br/>',NULL,15215,15215);
INSERT INTO stanza VALUES('BF311','1','This is the time for building the temple of the Lord<br/>That all the local churches may fully be restored.<br/>''Tis not the time for our house while God''s house lieth waste —<br/>O brothers, for God''s building, rise up, make haste!<br/>',NULL,15216,15216);
INSERT INTO stanza VALUES('BF311','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,15217,15217);
INSERT INTO stanza VALUES('BF311','2','O hear, the Lord is speaking: Consider now your ways,<br/>Ye sow and bring in little, for lacking is My praise.<br/>Go up into the mountain, material to provide,<br/>And build My house that I may be glorified.<br/>',NULL,15218,15218);
INSERT INTO stanza VALUES('BF311','3','Ye who are priests, ye remnant of Christians now obey —<br/>The Lord Himself is with us, whatever men may say,<br/>With spirits stirred and burning, now let us come to work;<br/>May none his part with others in building shirk.<br/>',NULL,15219,15219);
INSERT INTO stanza VALUES('BF311','4','I''ll fill this house with glory, the Lord of hosts has said,<br/>And the desire of nations will be exhibited.<br/>Its glory will be greater than all that''s gone before,<br/>And we will share this glory forevermore.<br/>',NULL,15220,15220);
INSERT INTO stanza VALUES('BF312','1','Christ has called us once to Him,<br/>But He calls us once again.<br/>To His call we say Amen!<br/>Overcome!<br/>For the church has fallen low,<br/>Thinking everything they know,<br/>But the life is missing; so,<br/>Overcome!<br/>',NULL,15221,15221);
INSERT INTO stanza VALUES('BF312','chorus','Overcome! Overcome!<br/>Overcome degraded Christianity!<br/>All your working lay aside,<br/>All the teachings that divide;<br/>Eat the Lord whate''er betide —<br/>Overcome!<br/>',NULL,15222,15222);
INSERT INTO stanza VALUES('BF312','2','Eating is man''s destiny<br/>And the Lord''s recovery;<br/>This defeats the enemy —<br/>Overcome!<br/>Come enjoy the tree of life,<br/>Leave the doctrines, leave the strife!<br/>Overcome by eating Christ —<br/>Overcome!<br/>',NULL,15223,15223);
INSERT INTO stanza VALUES('BF312','3','Teachings ne''er transform the soul,<br/>Teachings never reach God''s goal,<br/>Eating Christ will do it all —<br/>Overcome!<br/>We must overcome to eat,<br/>By ourselves and when we meet,<br/>Eat Him as the feast complete —<br/>Overcome!<br/>',NULL,15224,15224);
INSERT INTO stanza VALUES('BF312','4','Eating gives the manchild birth,<br/>Eating brings the Lord to earth;<br/>Eat Him now midst all the dearth —<br/>Overcome!<br/>Be the manchild Christ requires,<br/>Thus the church that He desires,<br/>Then the Bride that He admires —<br/>Overcome!<br/>',NULL,15225,15225);
INSERT INTO stanza VALUES('BF313','1','God''s complete salvation<br/>Is based upon His righteousness<br/>And through our faith.<br/>By the two divine transfers:<br/>Out of Adam into Christ<br/>And out of the flesh into the Spirit.<br/>In the one spiritual union<br/>Of the Spirit of life in our spirit,<br/>Forming a mingled spirit.<br/>For us to reign in life by the abundance of grace<br/>And of the gift of righteousness.<br/>For us to reign in life by the abundance of grace<br/>And of the gift of righteousness.<br/>',NULL,15226,15226);
INSERT INTO stanza VALUES('BF314','1','Though the world may promise me more,<br/>I''m just made to be filled with the Lord.<br/>Nor its life worth living a day,<br/>For the things that will soon pass away.<br/>Doesn''t matter how rich or successful I''d be;<br/>Or how many pleasures be offered to me.<br/>There''s nothing that compares to my destiny —<br/>To be thoroughly filled with the Lord.<br/>',NULL,15227,15227);
INSERT INTO stanza VALUES('BF314','2','Now although I''m still kind of small,<br/>And the future is in front of me.<br/>In my heart I heard the Lord''s call,<br/>Just to follow Him absolutely.<br/>Though the path may be holding much joy or much pain;<br/>What matters is that more of Him I would gain.<br/>Regardless what happens I never would change —<br/>Cause I''m made to be filled with the Lord.<br/>',NULL,15228,15228);
INSERT INTO stanza VALUES('BF315','1','From all corners of earth we''re called,<br/>Blent in Christ in one accord;<br/>Tearing down the dividing wall,<br/>He has firmly joined us all.<br/>With one soul, bear enduringly,<br/>In one spirit, stand steadfastly;<br/>Trust and care given mutually,<br/>In Christ we all are just one fam''ly.<br/>',NULL,15229,15229);
INSERT INTO stanza VALUES('BF315','chorus','Let icy hearts have warm reprieve,<br/>Let weary souls find sweet relief,<br/>Let blessings be always new as we live;<br/>Let brothers take action, be strong,<br/>Let sisters sing with joyful song,<br/>Let God''s fam''ly be ours all life long.<br/>',NULL,15230,15230);
INSERT INTO stanza VALUES('BF315','2','We are called out, no more to roam,<br/>But to live as one at home;<br/>Love of God in our hearts has grown,<br/>Joy of Spirit we have known.<br/>Grow in life, we to Him are drawn,<br/>Building in service we have shown;<br/>When one grieves, everybody mourns,<br/>In one''s glory, each spirit''s airborne.<br/>',NULL,15231,15231);
INSERT INTO stanza VALUES('BF315','chorus','Let the name of Christ be sanctified,<br/>Let the word of Christ be multiplied,<br/>Let the flow of life be intensified;<br/>Let the heart of God rest finally,<br/>Let the house of God thrive endlessly,<br/>Let us live as one eternally.<br/>',NULL,15232,15232);
INSERT INTO stanza VALUES('BF316','1','If I would only stray a bit<br/>Then ease my lot would be;<br/>But I recall how Christ my Lord<br/>Did suffer faithfully.<br/>',NULL,15233,15233);
INSERT INTO stanza VALUES('BF316','2','The world I have forever left<br/>And severed all its ties;<br/>The way may yet more narrow grow<br/>And all against me rise.<br/>',NULL,15234,15234);
INSERT INTO stanza VALUES('BF316','3','But though the worldings glare in rage;<br/>I seek His smiling face.<br/>Though outward glory others choose-<br/>I, His "well done" through grace.<br/>',NULL,15235,15235);
INSERT INTO stanza VALUES('BF316','4','My heart''s desire is not for fame<br/>Nor profit in these days;<br/>I humbly wish to serve my Lord<br/>And gain that day His praise.<br/>',NULL,15236,15236);
INSERT INTO stanza VALUES('BF316','5','Unto the judgement seat of Christ<br/>I daily look away;<br/>May all my living and my work<br/>Abide the fire that day.<br/>',NULL,15237,15237);
INSERT INTO stanza VALUES('BF316','6','You may your reputation hold,<br/>Wealth, friends, and glory gain;<br/>You may win all success and praise,<br/>A following great obtain.<br/>',NULL,15238,15238);
INSERT INTO stanza VALUES('BF316','7','But I would be but lonely, poor,<br/>With no prosperity;<br/>My heart desires to follow Him<br/>And finish faithfully.<br/>',NULL,15239,15239);
INSERT INTO stanza VALUES('BF316','8','My Lord, when here on earth, I know,<br/>Gained nothing but the cross.<br/>I only hope to be like Him<br/>And for Him suffer loss.<br/>',NULL,15240,15240);
INSERT INTO stanza VALUES('BF316','9','My glory''s in the coming age,<br/>Today I''ll patient be.<br/>I''d ne''er enjoy ahead of Him<br/>This world''s prosperity.<br/>',NULL,15241,15241);
INSERT INTO stanza VALUES('BF316','10','That day I shall receive the crown,<br/>He''ll wipe away my tears.<br/>So faithfully I''ll journey on<br/>Till He at length appears.<br/>',NULL,15242,15242);
INSERT INTO stanza VALUES('BF317','1','Let me love and not be requited,<br/>Let me serve and not be rewarded,<br/>Let me labor and not be remembered,<br/>Let me suffer and not be regarded.<br/>',NULL,15243,15243);
INSERT INTO stanza VALUES('BF317','2','Let me pour wine, while I drink not,<br/>Let me break bread, while I eat not,<br/>Pour our my life that others be blessed,<br/>Lose my self life that they be comforted.<br/>',NULL,15244,15244);
INSERT INTO stanza VALUES('BF317','3','I do not seek pity or wishes,<br/>I do not seek glory or riches,<br/>But I''d rather be lonely, wretched<br/>Be discarded, be wrongly treated.<br/>',NULL,15245,15245);
INSERT INTO stanza VALUES('BF317','4','With my blood and tears<br/>pay the price to gain the crown<br/>On this pilgrims'' ground<br/>bear all sorrows that abound<br/>For this way You did tread when You lived<br/>on this earth which is of Your own<br/>Gladly bore all loss as You purposed,<br/>That the people around you be composed.<br/>',NULL,15246,15246);
INSERT INTO stanza VALUES('BF317','5','I know not how far the future lies ahead,<br/>On this path of no retreating I am led.<br/>So let me, Lord, now learn<br/>of Your perfect pattern,<br/>Suffered wrong, no resentment in return.<br/>',NULL,15247,15247);
INSERT INTO stanza VALUES('BF317','6','May you in this tedious, dark interim<br/>Wipe away all my tears, somber and dim.<br/>For You are my solace I learn to know,<br/>Let my life be a pleasing fountain flow.<br/>',NULL,15248,15248);
INSERT INTO stanza VALUES('BF318','1','Let me love and not be respected;<br/>Let me serve and not be rewarded;<br/>Let me labor and not be remembered;<br/>Let me suffer and not be regarded.<br/>',NULL,15249,15249);
INSERT INTO stanza VALUES('BF318','2','‘Tis the pouring, not the drinking;<br/>‘Tis the breaking, not the keeping —<br/>A life suffering to seek others’ blessing.<br/>A life loving and true comfort giving.<br/>',NULL,15250,15250);
INSERT INTO stanza VALUES('BF318','3','Not expecting, pity and concern,<br/>Not accepting, solace and applause;<br/>Even lonely, even forgotten.<br/>Even wordless, even forsaken.<br/>',NULL,15251,15251);
INSERT INTO stanza VALUES('BF318','4','Tears and blood my price<br/>For the righteous crown shall be;<br/>Losing all, my cost for a faithful pilgrim’s life.<br/>‘Twas the life, O Lord, that You chose to live<br/>In those days when on earth You walked.<br/>Gladly suffering all injuries and loss<br/>So that all might draw near and repose.<br/>',NULL,15252,15252);
INSERT INTO stanza VALUES('BF318','5','I cannot see how much farther I shall go;<br/>Still I press on,<br/>Knowing there is no return.<br/>Let me follow Your pattern, so perfect and true,<br/>Bearing ingratitudes without complaint.<br/>In this time of trial, oh my Lord, I pray<br/>That You’d wipe all my hidden tears away;<br/>Let me learn, O Lord, You are my reward,<br/>Let me be other’s blessing all my days.<br/>',NULL,15253,15253);
INSERT INTO stanza VALUES('BF319','1','Lord, write your law, inscribe on our hearts,<br/>That this law of life, would of us be part,<br/>We are so hopeless, yet we hope in Him,<br/>Preparing a way for Christ to come in.<br/>',NULL,15254,15254);
INSERT INTO stanza VALUES('BF319','chorus','Lord, in these days I want to set my heart,<br/>Ever and only, always on you,<br/>That I would not defiled be,<br/>Keeping my heart so single and pure for Thee.<br/>',NULL,15255,15255);
INSERT INTO stanza VALUES('BF319','2','Lord as the fountain You''d want us to drink,<br/>Always supplying, it''s my only link,<br/>Staying connected to this precious flow,<br/>Planting my roots here that they would grow.<br/>',NULL,15256,15256);
INSERT INTO stanza VALUES('BF319','3','You are the Potter, we are the clay,<br/>Form now the church, your expression today,<br/>In Christ there''s nothing that we may lack,<br/>As now your Body, we''d bring you back.<br/>',NULL,15257,15257);
INSERT INTO stanza VALUES('BF320','1','I wake up this morning, Lord;<br/>The sun shines through my windowsill.<br/>How can I help but praise Your name!<br/>You''re my Lord and King!<br/>',NULL,15258,15258);
INSERT INTO stanza VALUES('BF320','chorus','Because You...gave Your life up for me.<br/>The Spirit...You were raised to be.<br/>Now You are...living deep in me,<br/>As my hope of glory.<br/>',NULL,15259,15259);
INSERT INTO stanza VALUES('BF320','2','Each day Your mercies they are new,<br/>To me refreshing as the dew;<br/>You are my bountiful supply.<br/>Every morning You''re nigh!<br/>',NULL,15260,15260);
INSERT INTO stanza VALUES('BF320','3','For me You came from up above,<br/>Because You are the God of love;<br/>Your love will never let me go;<br/>Everyday it flows.<br/>',NULL,15261,15261);
INSERT INTO stanza VALUES('BF320','4','Your love flows out to me as grace,<br/>Enabling me to run the race;<br/>As truth You''re my reality,<br/>As my all to be.<br/>',NULL,15262,15262);
INSERT INTO stanza VALUES('BF320','5','As I walk on this pilgrim road,<br/>My flesh and self You will erode;<br/>In my heart, You will have Your way;<br/>Take more room each day.<br/>',NULL,15263,15263);
INSERT INTO stanza VALUES('BF320','6','Each day the world I leave behind;<br/>You write Your laws upon my mind,<br/>Inscribing on my softened heart,<br/>Filling every part.<br/>',NULL,15264,15264);
INSERT INTO stanza VALUES('BF320','7','O Lord, I''m just a tree in You,<br/>Rooted and being built in You,<br/>Absorbing all You are to me,<br/>What a place to be!<br/>',NULL,15265,15265);
INSERT INTO stanza VALUES('BF321','1','I called upon Thy name, O Lord,<br/>out of a low dungeon.<br/>Thou hast heard my voice, O Lord,<br/>Thou hast heard my voice:<br/>',NULL,15266,15266);
INSERT INTO stanza VALUES('BF321','2','Hide not Thine ear<br/>at my breathing, at my cry.<br/>Hide not Thine ear<br/>at my breathing, at my cry.<br/>',NULL,15267,15267);
INSERT INTO stanza VALUES('BF322','1','Thy word is sweet unto my taste,<br/>Yea, sweeter more than honey.<br/>It says to watch and pray that you<br/>May not enter into temptation.<br/>',NULL,15268,15268);
INSERT INTO stanza VALUES('BF322','2','Flee youthful lust and pursue<br/>Righteousness, faith, love, and peace.<br/>Whatever you do, do in the name<br/>of the Lord Jesus Christ.<br/>And pursue with those,<br/>Those who call on the Lord out<br/>of a pure heart.  (2 Tim 2:22)<br/>',NULL,15269,15269);
INSERT INTO stanza VALUES('BF323','1','Meeting Jesus, I then believed:<br/>There''s a love that''s so great, so rich, so free;<br/>Causing Him to save me and indwell me,<br/>Bearing weakness and bringing sweet relief.<br/>Meeting you saints, I then perceived:<br/>My life''s portion He gave abundantly;<br/>All the saints are like the clouds around me,<br/>I rejoice as I live bountifully.<br/>',NULL,15270,15270);
INSERT INTO stanza VALUES('BF323','chorus','Love of God can''t ne''er wear away,<br/>He is faithful, true every day;<br/>Life''s new supply is perfect always,<br/>We, His Body, joined in every way.<br/>All the world I willingly let go,<br/>I have Christ, my glorious lot untold;<br/>His promise of life I would lay hold,<br/>With returns in this life hundredfold.<br/>',NULL,15271,15271);
INSERT INTO stanza VALUES('BF323','2','As I run, on God''s grace I rely,<br/>In need, grace came through you<br/>As my supply;<br/>''Twas your love for Him that I am urged by,<br/>This same love deeply on me you apply.<br/>In distress, you''re there to be my guide,<br/>In defeat, you stayed on whate''ver betide;<br/>I am grateful daily we go side by side,<br/>I owe to you my growth and joy inside.<br/>',NULL,15272,15272);
INSERT INTO stanza VALUES('BF323','chorus','My heart praises, that you''re my mates,<br/>As His brethren so intimate;<br/>My soul, my spirit, my whole being,<br/>Gladly, wholly, to you delegate.<br/>Now a living sacrifice are we,<br/>Serving, pleasing God — our destiny;<br/>Where''er we go we tread on boldly,<br/>We shall live with all vitality.<br/>',NULL,15273,15273);
INSERT INTO stanza VALUES('BF324','1','Lord, I love You,<br/>I desire You;<br/>No pleasure, prospects on this earth compare to You.<br/>Lord, I love You,<br/>I treasure You;<br/>No fame nor riches of this world compete with You.<br/>Lord, who have I<br/>In heaven but You,<br/>There''s none on earth<br/>I desire but You;<br/>You are my all,<br/>My All in all;<br/>Lord Jesus, I just love You,<br/>I love only You.<br/>',NULL,15274,15274);
INSERT INTO stanza VALUES('BF324','2','Lord, I love You,<br/>I now choose You;<br/>No love, nor praises of men can e''er replace You.<br/>Lord, I love You,<br/>I lay hold of You;<br/>No hope, no expectation I have ''part from You.<br/>Lord, who have I<br/>In heaven but You;<br/>There''s none on earth<br/>I desire but You;<br/>You''re my first love,<br/>My final love;<br/>I give my life and all<br/>To love and follow You.<br/>',NULL,15275,15275);
INSERT INTO stanza VALUES('BF324','3','Lord, I love You,<br/>I pursue You;<br/>No person, object in this life can e''er match You.<br/>Lord, I love You,<br/>I run after You;<br/>You are my life, my aim, my goal and future too.<br/>Lord, who have I<br/>In heaven but You;<br/>There''s none on earth<br/>I desire but You;<br/>I give my heart,<br/>Lord, now to You;<br/>Lord make me a drink off''ring here<br/>To satisfy You.<br/>',NULL,15276,15276);
INSERT INTO stanza VALUES('BF325','1','Remove my covering, Lord,<br/>That I may see Thy light,<br/>And be deceived no more,<br/>But all things see aright.<br/>But all things see aright.<br/>',NULL,15277,15277);
INSERT INTO stanza VALUES('BF325','chorus','Oh, may Thy living light, Lord,<br/>Scatter all my night, Lord,<br/>And ev''rything make bright, Lord,<br/>For this I pray to Thee.<br/>',NULL,15278,15278);
INSERT INTO stanza VALUES('BF325','2','I hardly know myself;<br/>Deceived so much by pride,<br/>I often think I''m right<br/>And am self-satisfied.<br/>',NULL,15279,15279);
INSERT INTO stanza VALUES('BF325','3','I know Thee even less;<br/>In doctrine, shallowly;<br/>True revelation lack<br/>Of Thy reality.<br/>',NULL,15280,15280);
INSERT INTO stanza VALUES('BF325','4','As for Thy life within,<br/>In darkness I mistake —<br/>If spirit or the flesh,<br/>One for the other take.<br/>',NULL,15281,15281);
INSERT INTO stanza VALUES('BF325','5','As for Thy way, O Lord,<br/>I often am not clear;<br/>I toward seclusion tend<br/>And from the pathway veer.<br/>',NULL,15282,15282);
INSERT INTO stanza VALUES('BF325','6','As for Thy will for me,<br/>I do not know it well;<br/>I substitute my own<br/>And often would rebel.<br/>',NULL,15283,15283);
INSERT INTO stanza VALUES('BF325','7','As for the church, I need<br/>Thy revelation more,<br/>The Body-life to know,<br/>Thy wisdom to explore.<br/>',NULL,15284,15284);
INSERT INTO stanza VALUES('BF325','8','I long to be unveiled,<br/>In everything made clear,<br/>No more to be deceived<br/>Or to my pride adhere.<br/>',NULL,15285,15285);
INSERT INTO stanza VALUES('BF326','1','Lord, I open to Your light<br/>That I’d vanquished be.<br/>Mend with balm anointing life;<br/>Build Yourself in me,<br/>And adorn my being.<br/>',NULL,15286,15286);
INSERT INTO stanza VALUES('BF326','2','I would walk as if one blind,<br/>Faith my only guide,<br/>Understanding cast behind,<br/>As a veil of night,<br/>That I’d know real sight.<br/>',NULL,15287,15287);
INSERT INTO stanza VALUES('BF326','3','Sun of revelation, rise!<br/>Gush, O vital stream!<br/>That by light and flowing life,<br/>Living I would be,<br/>Fully one with Thee.<br/>',NULL,15288,15288);
INSERT INTO stanza VALUES('BF326','4','Fruit most fragrant may You find,<br/>Bursting with Your life,<br/>Fully ready, wholly ripe,<br/>Pleasing in Your sight;<br/>You I would delight.<br/>',NULL,15289,15289);
INSERT INTO stanza VALUES('BF326','5','Come, dear hand of mercy, bring<br/>Grace’s full supply!<br/>For a love-filled out-pouring<br/>Of my very life<br/>On Your Body, Christ.<br/>',NULL,15290,15290);
INSERT INTO stanza VALUES('BF327','1','On the cross You gave Your life for me,<br/>That I might live again<br/>In resurrection You have lifted me<br/>To newness born within<br/>Through the blood I repent of all my sins<br/>Precious Lord, I now give in.<br/>Fill me Lord Jesus<br/>Lord, I ask You to come in.<br/>',NULL,15291,15291);
INSERT INTO stanza VALUES('BF327','2','Upon my heart Lord write Your law,<br/>So the Christ in me may grow<br/>Renew me in my mind too, Lord<br/>That Your light through me may show<br/>Calling, “Oh Lord Jesus”<br/>Wherever I may be<br/>Thank You sweet, sweet Jesus<br/>For today You set me free<br/>',NULL,15292,15292);
INSERT INTO stanza VALUES('BF327','3','Lord, I really love You,<br/>You’re everything I need<br/>Make Your home within my heart<br/>Only You I will believe<br/>Loving You and living You,<br/>With a heart that’s pure and true<br/>O dear Lord Jesus, I trust my life to You<br/>O dear Lord Jesus, I trust my life to You<br/>',NULL,15293,15293);
INSERT INTO stanza VALUES('BF328','1','Good morning Lord Jesus<br/>Thank You for today<br/>Thank You for my spirit<br/>Thank You I can pray<br/>I love You, Lord Jesus,<br/>To You I love to sing.<br/>Thank You, Lord, for everything.<br/>',NULL,15294,15294);
INSERT INTO stanza VALUES('BF329','1','Good morning to You, Lord Jesus.<br/>I consecrate myself to You to today.<br/>Lord Jesus! I love You!<br/>Oh, fill me with Your Spirit<br/>And saturate me, Lord, I pray.<br/>',NULL,15295,15295);
INSERT INTO stanza VALUES('BF329','2','Good morning, dear Lord. Hallelujah!<br/>My spirit is alive and bold today.<br/>Come forward is Your call<br/>To the holiest of all;<br/>Your blood has cleared a new and living way.<br/>',NULL,15296,15296);
INSERT INTO stanza VALUES('BF329','3','Good morning! Amen! Oh, praise the Lord!<br/>I live this day one spirit with You.<br/>To your word I say, "Amen."<br/>Give me fresh experience again.<br/>My heart, my mind, Lord, soften and renew.<br/>',NULL,15297,15297);
INSERT INTO stanza VALUES('BF329','4','O Lord, this is the day of my salvation.<br/>Your living Word will operate in me.<br/>Today You are my choice.<br/>I''ll exercise to hear Your voice.<br/>Then let You live and move and speak in me.<br/>',NULL,15298,15298);
INSERT INTO stanza VALUES('BF330','1','New day, new start — Oh, I love the Lord.<br/>His way, my heart — Yes, I love the Lord.<br/>Rise up spirit, soul, body so the day can start!<br/>God is moving on today and I have a heart.<br/>',NULL,15299,15299);
INSERT INTO stanza VALUES('BF331','1','Everybody ought to know,<br/>Everybody ought to know,<br/>Everybody ought to know,<br/>Where Jesus dwells.<br/>(repeat)<br/>',NULL,15300,15300);
INSERT INTO stanza VALUES('BF331','chorus','He is dwelling in our spirit;<br/>He is breath and life to us;<br/>We are one with Him in spirit.<br/>Everybody ought to know.<br/>',NULL,15301,15301);
INSERT INTO stanza VALUES('BF331','2','Everybody ought to know,<br/>Everybody ought to know,<br/>Everybody ought to know,<br/>The living Christ.<br/>(repeat)<br/>',NULL,15302,15302);
INSERT INTO stanza VALUES('BF331','chorus','Christ is the life-giving Spirit,<br/>All God’s fullness He contains.<br/>We partake of all His riches,<br/>Just by calling on His name.<br/>',NULL,15303,15303);
INSERT INTO stanza VALUES('BF332','1','Behold, the New Jerusalem descends from God —<br/>The Triune God Himself in His intrinsic essence<br/>Now consummately dwells in man and they in Him.<br/>Behold, the New Jerusalem descends from God.<br/>Illumined by the light of life, they walk the way<br/>Of life and eat the tree of life and drink the river.<br/>And thus enjoying God fore''er, they''re one with Him<br/>As the very processed Triune God<br/>Dispenses Himself to them!<br/>',NULL,15304,15304);
INSERT INTO stanza VALUES('BF333','1','Sometimes there are situations<br/>And many frustrations,<br/>That stumble you in subtle ways,<br/>And nothing seems okay.<br/>',NULL,15305,15305);
INSERT INTO stanza VALUES('BF333','chorus','The church life is not perfect<br/>But it is genuine,<br/>This is where our God dwells,<br/>This is where I''ll be.<br/>',NULL,15306,15306);
INSERT INTO stanza VALUES('BF333','2','It may seem like Satan might win,<br/>Our patience may run thin,<br/>what we need is His supply,<br/>In His arms we lie.<br/>',NULL,15307,15307);
INSERT INTO stanza VALUES('BF333','3','Many times we are discouraged,<br/>Our spirit disheartened,<br/>Just ask the Lord for everything,<br/>To strengthen our spirit.<br/>',NULL,15308,15308);
INSERT INTO stanza VALUES('BF333','4','Put aside your opinions,<br/>Just take Christ in as life,<br/>Come again to the altar<br/>For the Lord''s cleansing blood.<br/>',NULL,15309,15309);
INSERT INTO stanza VALUES('BF333','5','How do you want to spend your days?<br/>In God''s house that''s the way,<br/>Let''s make one''s reality,<br/>To gain Christ corporately.<br/>',NULL,15310,15310);
INSERT INTO stanza VALUES('BF334','1','Do you know that you<br/>Have a special portion of Christ<br/>Unique to you?<br/>And it may just be true<br/>That person ''cross the room can benefit<br/>From the Christ in you.<br/>',NULL,15311,15311);
INSERT INTO stanza VALUES('BF334','chorus','Though you may have those butterflies,<br/>Or like me you may just be shy.<br/>Don''t you realize how much help you''ll give<br/>When your Christ in them will live.<br/>',NULL,15312,15312);
INSERT INTO stanza VALUES('BF334','2','Do you know when we<br/>Exercise our spirit with the saints<br/>Our joy is made full.<br/>And that ministering<br/>Our Christ to one another we''re built up<br/>Into something eternal.<br/>',NULL,15313,15313);
INSERT INTO stanza VALUES('BF334','chorus','This is God''s economy<br/>That you would be filled fully,<br/>Overflowing His rich dispensing,<br/>Build the Body corporately.<br/>',NULL,15314,15314);
INSERT INTO stanza VALUES('BF334','3','Do you know it starts<br/>With our enjoyment of the Lord,<br/>To be filled with Him?<br/>And if we do our part<br/>To spend time to receive Him in the Word,<br/>We''ll spontaneously o''erflow Him.<br/>',NULL,15315,15315);
INSERT INTO stanza VALUES('BF334','chorus','So why not turn to Christ right now?<br/>Simply eat Him that is how.<br/>If we''re soaked and filled up to the brim,<br/>We can''t help but express Him.<br/>',NULL,15316,15316);
INSERT INTO stanza VALUES('BF334','chorus','This is God''s economy<br/>That you would be filled fully,<br/>Overflowing His rich dispensing,<br/>Build the Body corporately.<br/>',NULL,15317,15317);
INSERT INTO stanza VALUES('BF335','chorus','I am crucified with Christ:<br/>And it is no longer I<br/>Who liveth, but it is Christ who lives in me;<br/>And the life which I now live<br/>In the flesh, I live in faith.<br/>The faith in the Son of God,<br/>Who loved and gave Himself up for me.<br/>',NULL,15318,15318);
INSERT INTO stanza VALUES('BF335','1','And now I''m walking by the Spirit.<br/>Step by step, day by day.<br/>O Lord, I love You.<br/>You''re the precious One to me.<br/>As I do this and that<br/>Lord, remind me where You''re at.<br/>You''re in my spirit,<br/>Dispensing grace to me.<br/>',NULL,15319,15319);
INSERT INTO stanza VALUES('BF335','2','And now I''m walking by the Spirit,<br/>Walking on toward the goal<br/>O Lord, Your purpose means<br/>Everything to me.<br/>All self love, I lay aside<br/>For the churches, for Your bride,<br/>For the fulfillment of Your economy!<br/>',NULL,15320,15320);
INSERT INTO stanza VALUES('BF336','1','Your face melts me<br/>You are so lovely<br/>Kiss me, woo me<br/>Till I will run after Thee.<br/>',NULL,15321,15321);
INSERT INTO stanza VALUES('BF336','2','Your love draws me<br/>Fills me completely<br/>Sweet death, new life<br/>What can I do but follow Thee?<br/>',NULL,15322,15322);
INSERT INTO stanza VALUES('BF336','3','Your name charmed me<br/>Captured me wholly<br/>What joy, such peace<br/>Call, I will come away with Thee.<br/>',NULL,15323,15323);
INSERT INTO stanza VALUES('BF336','chorus','Love unrivaled<br/>Matchless One,<br/>Transform this will of mine<br/>To Your design.<br/>Draw me with Your voice so sweet.<br/>I must follow<br/>I must follow You,<br/>And come away.<br/>Come away, my love.<br/>Rise and come away;<br/>Come away from Lebanon and follow Me.<br/>',NULL,15324,15324);
INSERT INTO stanza VALUES('BF337','1','Lord, You are more precious than silver;<br/>Lord, You are more costly than gold;<br/>Lord, You are more beautiful than diamonds;<br/>And nothing I desire compares to You!<br/>',NULL,15325,15325);
INSERT INTO stanza VALUES('BF337','2','Lord, Your life is divine, eternal<br/>Lord, Your life regenerated me.<br/>Lord, Your life is growing within me,<br/>Until I am fully conformed to Thee.<br/>',NULL,15326,15326);
INSERT INTO stanza VALUES('BF337','3','Lord, Your love is wide as the ocean.<br/>Lord, Your love is deep as the sea.<br/>Lord, Your love encompasses the nations,<br/>And that is all I want to live in me.<br/>',NULL,15327,15327);
INSERT INTO stanza VALUES('BF337','4','Lord, Your light is shining within us.<br/>Lord, Your light drives darkness away.<br/>Lord, Your light is guiding us onward,<br/>Preparing us for the coming wedding day.<br/>',NULL,15328,15328);
INSERT INTO stanza VALUES('BF338','1','The faith is the economy,<br/>The economy of God,<br/>The household administration,<br/>The dispensing of our God,<br/>The Truth is the contents,<br/>The reality of the faith,<br/>According to God''s economy.<br/>',NULL,15329,15329);
INSERT INTO stanza VALUES('BF338','chorus','Godliness is a living that expresses<br/>The divine reality,<br/>And expression of God in all His riches,<br/>Full of all gravity.<br/>',NULL,15330,15330);
INSERT INTO stanza VALUES('BF338','2','Healthy teaching, words and speaking<br/>Are the ministry of the truth,<br/>Ministering into people<br/>The reality of these truths;<br/>Eternal life is the means<br/>And the power to carry out,<br/>The divine realities<br/>Of the faith.<br/>',NULL,15331,15331);
INSERT INTO stanza VALUES('BF338','3','Faith is the response<br/>To the truth of the faith.<br/>Conscience is a test and a check<br/>To preserve us in the faith.<br/>The faith is the economy,<br/>The economy of God,<br/>The household administration,<br/>The dispensing of our God.<br/>',NULL,15332,15332);
INSERT INTO stanza VALUES('BF338','4','The faith, the truth,<br/>Expressed in healthy words,<br/>Carried out in power<br/>By His life.<br/>Expressed in godly living,<br/>Responded to by faith,<br/>Kept and held in check<br/>By our conscience.<br/>',NULL,15333,15333);
INSERT INTO stanza VALUES('BF339','1','Jesus Lord, I just love You<br/>You’ve attracted me, and my heart renewed<br/>I pursue You like a dove;<br/>I belong to You and You’re my Beloved<br/>',NULL,15334,15334);
INSERT INTO stanza VALUES('BF339','chorus','Everything under the sun is vanity<br/>It’s like chasing after wind, so emptily;<br/>You have put within me, Lord eternity.<br/>',NULL,15335,15335);
INSERT INTO stanza VALUES('BF339','2','Now I rise to come away<br/>In the cleft rock, Lord, I would ever stay.<br/>Kiss me, Lord, refresh me too.<br/>As I gaze at You, and Your death I view.<br/>',NULL,15336,15336);
INSERT INTO stanza VALUES('BF339','chorus','You were broken on the cross for me, dear Lord<br/>All Your being, life, and love for me was poured.<br/>Precious One, You are the One that I adore.<br/>',NULL,15337,15337);
INSERT INTO stanza VALUES('BF339','3','Make me, Lord, a fragrance true,<br/>As a garden filled with Your spices new.<br/>Transform me, Your Bride to be.<br/>For Your heart’s desire through eternity<br/>',NULL,15338,15338);
INSERT INTO stanza VALUES('BF339','chorus','As Your lover in the veil, I long to be,<br/>Be conformed to Your sweet death continually.<br/>‘Til Your city we become eternally.<br/>',NULL,15339,15339);
INSERT INTO stanza VALUES('BF340','1','Lord, I give myself to You again today<br/>Lord, on this consecration path I choose to stay<br/>You bought me with a price, my life I sacrifice<br/>Lord, I am not my own.<br/>',NULL,15340,15340);
INSERT INTO stanza VALUES('BF340','2','Lord, I give myself to You again today<br/>Your mercy reached me though I was so far away<br/>You gave Yourself for me, from earthly dreams you freed<br/>Lord I am Yours alone.<br/>',NULL,15341,15341);
INSERT INTO stanza VALUES('BF340','3','Lord, I give myself to you again today<br/>I open to You so that you may have a way<br/>To work in me that I might serve you my whole life<br/>Lord I love You alone.<br/>',NULL,15342,15342);
INSERT INTO stanza VALUES('BF341','1','If God leads you to walk a way<br/>To walk a way that you know,<br/>It will not benefit you<br/>As much as if He would<br/>Lead you to take the way<br/>To take the way that you do not know.<br/>This forces you to have<br/>Hundreds and<br/>Thousands of conversations<br/>With Him,<br/>Resulting in a journey<br/>That is an everlasting<br/>Memorial between<br/>You and Him.<br/>',NULL,15343,15343);
INSERT INTO stanza VALUES('BF342','1','I will not let Thee go my Lord,<br/>I will not let Thee go!<br/>Confession glad on Thee outpoured,<br/>Thine own dear heart to know.<br/>My hearts desire, my lips request<br/>To be of use to Thee,<br/>That in that day I’d share Your rest —<br/>Through serving faithfully.<br/>',NULL,15344,15344);
INSERT INTO stanza VALUES('BF342','2','And days ahead I shall not fear<br/>I trust Thy sovereign Hand!<br/>So all creation bend and hear<br/>This cry! My joyful stand!<br/>No longer days of sad neglect<br/>Now shall affront my view<br/>Nor sorrowed nights of deep regret<br/>I’ll waste apart from You.<br/>',NULL,15345,15345);
INSERT INTO stanza VALUES('BF342','3','Ambition shall no longer keep,<br/>Unyielding grip on me.<br/>While true ‘tis pride’s veins do run deep<br/>They’re severed Lord in Thee<br/>It was with joy that Caleb stood<br/>‘Hind Joshua on that day.<br/>And glory comes to all who would<br/>Now enter Caleb’s way.<br/>',NULL,15346,15346);
INSERT INTO stanza VALUES('BF342','4','Though not through my own efforts vain<br/>Could I e’er make You glad<br/>But through apostles’ teaching gain<br/>The view such brothers had.<br/>And through their practice enter in<br/>My crown in hand that day.<br/>And joy with Your apostles then<br/>Not having turned away.<br/>',NULL,15347,15347);
INSERT INTO stanza VALUES('BF342','5','My heart, my soul, I have resigned<br/>Drink off’ring for Your joy.<br/>Imagination  ne’er could find<br/>Or want greater employ!<br/>I will not let Thee go my Lord,<br/>I will not let Thee go!<br/>Confession glad on Thee outpoured,<br/>Thine own dear heart to know.<br/>',NULL,15348,15348);
INSERT INTO stanza VALUES('BF343','1','Oh Lord You’re Breath to me,<br/>My all-inclusive Christ!<br/>You’re never far from me,<br/>My all-inclusive Breath!<br/>No longer “raw,”<br/>You’re now the processed Triune God,<br/>So I breathe You in:<br/>Oh Lord Jesus, Lord!<br/>Oh Lord!<br/>Oh Lord!<br/>',NULL,15349,15349);
INSERT INTO stanza VALUES('BF343','2','Oh Lord You’re life to me,<br/>You’re my pneumatic Christ!<br/>You’ve got two elements —<br/>Both human and divine,<br/>Intensified<br/>Seven-fold, consummated Spirit;<br/>So I breathe you in:<br/>Oh Lord Jesus, Lord!<br/>Oh Lord!<br/>Oh Lord!<br/>',NULL,15350,15350);
INSERT INTO stanza VALUES('BF344','1','Lord, You have searched me and You have known me<br/>You understand my thoughts from afar!<br/>You comprehend my path and are acquainted<br/>with all my ways<br/>For there is not a word on my tongue,<br/>But behold You know it all together!<br/>',NULL,15351,15351);
INSERT INTO stanza VALUES('BF344','chorus','Search me O God, and know my heart<br/>Try me and know my anxieties<br/>See if there is any wicked in me<br/>And lead me in the way everlasting!<br/>',NULL,15352,15352);
INSERT INTO stanza VALUES('BF344','2','Lord, You have touched me and You have shown me<br/>That I am not so simple as I thought.<br/>I often run and hide, prone to an errant heart.<br/>But there is not a pause and You pursue!<br/>And behold You''ve caught me altogether!<br/>',NULL,15353,15353);
INSERT INTO stanza VALUES('BF344','chorus','Where can I go from Your Spirit, O Lord?<br/>I can''t flee from Your presence, You''re inside me.<br/>I''ve climbed the steep mountains, but You still are there,<br/>Descend to the valleys but You find me.<br/>',NULL,15354,15354);
INSERT INTO stanza VALUES('BF344','3','Now I see, there''s something more to this pattern:<br/>You want to show me all that You are.<br/>So You''ve drawn me from this strife, into the family life<br/>As one, our prayers can match Your deep desires.<br/>Now behold we follow You together!<br/>',NULL,15355,15355);
INSERT INTO stanza VALUES('BF345','1','Jesus, lover of my soul,<br/>Let me to Thy bosom fly,<br/>While the nearer waters roll,<br/>While the tempest still is high:<br/>Hide me, O my Savior, hide,<br/>Till the storm of life is past;<br/>Safe into the haven guide;<br/>O receive my soul at last.<br/>',NULL,15356,15356);
INSERT INTO stanza VALUES('BF345','2','Other refuge have I none,<br/>Hangs my helpless soul on Thee;<br/>Leave, oh, leave me not alone,<br/>Still support and comfort me.<br/>All my trust on Thee is stayed,<br/>All my help from Thee I bring;<br/>Cover my defenseless head<br/>With the shadow of Thy wing.<br/>',NULL,15357,15357);
INSERT INTO stanza VALUES('BF345','3','Thou, O Christ, art all I want;<br/>More than all in Thee I find;<br/>Raise the fallen, cheer the faint,<br/>Heal the sick and lead the blind.<br/>Just and holy is Thy name,<br/>I am all unrighteousness;<br/>Vile and full of sin I am,<br/>Thou art full of truth and grace.<br/>',NULL,15358,15358);
INSERT INTO stanza VALUES('BF345','4','Plenteous grace with Thee is found,<br/>Grace to cover all my sin;<br/>Let the healing streams abound;<br/>Make and keep me pure within.<br/>Thou of life the fountain art,<br/>Freely let me take of Thee;<br/>Spring Thou up within my heart,<br/>Rise to all eternity.<br/>',NULL,15359,15359);
INSERT INTO stanza VALUES('BF346','1','This time I will not question,<br/>This time I won’t go free,<br/>This time I shall lie quiet,<br/>This time He touches me.<br/>',NULL,15360,15360);
INSERT INTO stanza VALUES('BF346','chorus','Do, Lord, what You will<br/>Freely thus in me —<br/>Without reservation;<br/>All is well with me.<br/>',NULL,15361,15361);
INSERT INTO stanza VALUES('BF346','2','‘Though valleys seem forever,<br/>Few hills, yea, far between,<br/>I ask not for relief from<br/>What’s measured out to me.<br/>',NULL,15362,15362);
INSERT INTO stanza VALUES('BF346','3','I know the way is narrow,<br/>The course is long and rough;<br/>As long as You are happy,<br/>Your smile — it is enough.<br/>',NULL,15363,15363);
INSERT INTO stanza VALUES('BF347','1','The Lord is my light and salvation,<br/>Whom shall I fear?<br/>The Lord is the strength of my life,<br/>Of whom shall I be afraid.<br/>',NULL,15364,15364);
INSERT INTO stanza VALUES('BF347','2','One thing have I desired of the Lord,<br/>That will I seek,<br/>That I may dwell in the house of the Lord,<br/>All the days of my life to behold<br/>The beauty of the Lord,<br/>And to inquire in His temple.<br/>',NULL,15365,15365);
INSERT INTO stanza VALUES('BF347','3','Hear O Lord,<br/>When I cry with my voice,<br/>Have mercy also upon me, and answer me.<br/>',NULL,15366,15366);
INSERT INTO stanza VALUES('BF347','4','When Thou saidst, seek ye My face,<br/>My heart said unto Thee,<br/>Thy face, O Lord will I seek.<br/>',NULL,15367,15367);
INSERT INTO stanza VALUES('BF347','5','Wait on the Lord,<br/>Be of good courage,<br/>And He shall strengthen thine heart,<br/>Wait I say on the Lord.<br/>',NULL,15368,15368);
INSERT INTO stanza VALUES('BF348','1','There is a song within me;<br/>It''s a song of Jesus moving<br/>In the gardens of my heart.<br/>This Jesus lives within me,<br/>Planting flowers of Himself<br/>There to be watered by my Love.<br/>',NULL,15369,15369);
INSERT INTO stanza VALUES('BF348','chorus','I''m loving Jesus, this lovely Person<br/>With personality so strong.<br/>He brought me to Himself<br/>And said to me, "All of your heart''s desire<br/>Is found in Me;<br/>I''m all you need and I love you."<br/>',NULL,15370,15370);
INSERT INTO stanza VALUES('BF348','2','There is a peace within me<br/>That has sprung from deep contentment<br/>With my Lord, who''s all in all.<br/>For my delight is in this<br/>Living One inside of me<br/>Who is Himself, my everything.<br/>',NULL,15371,15371);
INSERT INTO stanza VALUES('BF349','1','If we would love the Lord and care for His unique Body,<br/>The Lord will pour Himself out and move within us as<br/>The sevenfold intensified Spirit to blend us together<br/>For the consummation of the New Jerusalem.<br/>',NULL,15372,15372);
INSERT INTO stanza VALUES('BF350','1','Lord, I''ve set my heart; Lord, I just love You.<br/>Beside You I have no other desire.<br/>Lord, I just like to live You.<br/>',NULL,15373,15373);
INSERT INTO stanza VALUES('BF350','chorus','Lord, I love You because You love me.<br/>I just like to live You,<br/>And be under Your instant moment by<br/>moment leading.<br/>',NULL,15374,15374);
INSERT INTO stanza VALUES('BF350','2','On the entire earth, in the whole universe,<br/>I have no int''rest or other desire:<br/>My desire is only You.<br/>',NULL,15375,15375);
INSERT INTO stanza VALUES('BF350','3','Thank You, dearest Lord; You''ve predestinated me.<br/>You''ve called me and saved me and, Lord, preserved me.<br/>You have brought me, Lord, to this day.<br/>',NULL,15376,15376);
INSERT INTO stanza VALUES('BF351','1','Let the north wind blow —<br/>Let the south wind blow —<br/>Let the north and the south wind<br/>come and blow my way!<br/>',NULL,15377,15377);
INSERT INTO stanza VALUES('BF351','2','Look to the east;<br/>Look to the west;<br/>North, south, east, west —<br/>All this land you see is ours to take!<br/>',NULL,15378,15378);
INSERT INTO stanza VALUES('BF351','3','Arise,<br/>Walk the land!<br/>He is the One who is leading us to fight;<br/>The giants there —<br/>They''re food for us!<br/>Let''s go at once and possess it,<br/>For we are well able to overcome it!<br/>',NULL,15379,15379);
INSERT INTO stanza VALUES('BF352','1','Make a joyful noise unto the Lord,<br/>All ye, all ye lands.<br/>Serve the Lord, the Lord with gladness:<br/>Come before His presence with singing.<br/>',NULL,15380,15380);
INSERT INTO stanza VALUES('BF352','2','Know ye that the Lord He is God:<br/>It is He that hath made us,<br/>And not we ourselves;<br/>We are his people, and the sheep of His pasture.<br/>',NULL,15381,15381);
INSERT INTO stanza VALUES('BF352','3','Enter into His gates with thanksgiving,<br/>And into his courts with praise:<br/>Be thankful unto Him,<br/>And bless, and bless His name.<br/>',NULL,15382,15382);
INSERT INTO stanza VALUES('BF352','4','For the Lord, the Lord is good;<br/>His mercy is everlasting;<br/>And his truth endureth to all,<br/>Endureth to all generations<br/>',NULL,15383,15383);
INSERT INTO stanza VALUES('BF352','5','Hallelujah! Glory hallelujah!<br/>Hallelujah! Glory hallelujah!<br/>Hallelujah! Glory hallelujah!<br/>Hallelujah! Glory hallelujah!<br/>',NULL,15384,15384);
INSERT INTO stanza VALUES('BF353','1','Holding to truth in love,<br/>We may be built up together<br/>That we may no longer be<br/>Children tossed by waves and winds,<br/>For out from Christ<br/>The Body is knit together<br/>For through Christ’s rich supply<br/>The Body builds itself up in love.<br/>',NULL,15385,15385);
INSERT INTO stanza VALUES('BF353','2','Stand with me;<br/>Our purpose is the same.<br/>Run with me;<br/>Bring others to race.<br/>Grow with me;<br/>In Christ in all things.<br/>Pray with me;<br/>For Christ to gain.<br/>',NULL,15386,15386);
INSERT INTO stanza VALUES('BF354','1','Come with me from Lebanon, my bride<br/>With me from Lebanon come.<br/>Look from the top of Amana, Senir, and Hermon,<br/>From the lions'' dens,<br/>From the leopards'' mountains.<br/>From the lions'' dens,<br/>From the leopards'' mountains.<br/>Come with me, from Lebanon come.<br/>',NULL,15387,15387);
INSERT INTO stanza VALUES('BF355','1','Everyone who believes<br/>That Jesus is the Christ<br/>Has been begotten of God,<br/>And everyone who loves<br/>Him who has begotten<br/>Loves him also who<br/>Has been begotten<br/>Of Him.<br/>',NULL,15388,15388);
INSERT INTO stanza VALUES('BF355','2','Everything that has been<br/>Begotten of God<br/>Overcomes the world;<br/>And this is the victory —<br/>Our faith is the victory.<br/>God gave to us eternal life<br/>And this life is in<br/>His Son.<br/>',NULL,15389,15389);
INSERT INTO stanza VALUES('BF356','1','He stepped out of glory,<br/>And put on the lowly,<br/>And life’s very Author<br/>A creature became.<br/>Despised and forsaken,<br/>Afflicted with sorrow,<br/>From infinite splendor,<br/>To the likeness of shame.<br/>',NULL,15390,15390);
INSERT INTO stanza VALUES('BF356','2','He chose to be humbled,<br/>He chose limitation,<br/>He chose to be finite,<br/>He chose to be man.<br/>God’s unfathomed purpose<br/>Found substance in Jesus!<br/>A two-natured being —<br/>The unique God-Man.<br/>',NULL,15391,15391);
INSERT INTO stanza VALUES('BF356','3','His own shell was broken<br/>Releasing His glory,<br/>This life-impartation<br/>Produced many grains.<br/>The Firstborn rejoices<br/>With His many brothers —<br/>An incorporation, divine and human.<br/>',NULL,15392,15392);
INSERT INTO stanza VALUES('BF356','4','We cannot but love Him!<br/>Our lovely Forerunner;<br/>His shame was our vict’ry,<br/>His anguish our joy.<br/>The children of judgment<br/>He brought into glory,<br/>The millions of God-men<br/>Forever rejoice!<br/>',NULL,15393,15393);
INSERT INTO stanza VALUES('BF357','1','In moments like these I sing out a song.<br/>I sing out a love song to Jesus.<br/>In moments like these I sing out a song,<br/>I sing out a song to my Lord;<br/>',NULL,15394,15394);
INSERT INTO stanza VALUES('BF357','chorus','Singing, I love You, Lord.<br/>Singing, I love You, Lord.<br/>Singing, I love You, Lord.<br/>I love You.<br/>',NULL,15395,15395);
INSERT INTO stanza VALUES('BF357','2','In moments like these I call on the Lord.<br/>I call, O Lord Jesus, He saves me.<br/>In moments like these I call on the Lord.<br/>I call, O Lord Jesus, He saves;<br/>',NULL,15396,15396);
INSERT INTO stanza VALUES('BF357','chorus','Calling, O Lord Jesus.<br/>Calling, O Lord Jesus.<br/>Calling, O Lord Jesus,<br/>Jesus is Lord.<br/>',NULL,15397,15397);
INSERT INTO stanza VALUES('BF358','1','Some, these days would tell us that our Jesus is not food,<br/>That we only need to know about Him and do good,<br/>But we’re glad to tell you brothers, it’s just not that way —<br/>Jesus is the bread of life; we eat Him every day.<br/>',NULL,15398,15398);
INSERT INTO stanza VALUES('BF358','chorus','We love the church life,<br/>Eating, drinking, breathing Jesus.<br/>We love the church life,<br/>Taking in God’s Word.<br/>We love to hear those<br/>“O Lord, Amen, Hallelujahs!”<br/>We love the church life,<br/>Feasting with the Lord.<br/>',NULL,15399,15399);
INSERT INTO stanza VALUES('BF358','2','When He fills our inward parts, we’re never quite the same,<br/>So much richness we can taste by calling on His name.<br/>“Services” but once a week for us will never do.<br/>Every day we need the fellowship to take us through.<br/>',NULL,15400,15400);
INSERT INTO stanza VALUES('BF358','3','If these latter days and situations of the world<br/>Make you feel that round a vicious circle you are swirled,<br/>Then please listen closely to the things we have to say;<br/>It may be that you will find with us a better way.<br/>',NULL,15401,15401);
INSERT INTO stanza VALUES('BF359','1','Not pocito, nor kidogo —<br/>I love the Lord a whole bunch. (Un muchos!)<br/>Nicht ein bischen, shao or choto —<br/>I love the Lord a whole bunch.<br/>Grandios and muchos,<br/>Colossal un da —<br/>I love the Lord — O so much.<br/>Not a little but a bunch!<br/>',NULL,15402,15402);
INSERT INTO stanza VALUES('BF359','2','Lord, I do not have all the words<br/>To speak my love out to You.<br/>For Your love to me surpasses all words that<br/>ever I knew.<br/>All the languages, though so different,<br/>They all can say the same thing —<br/>That my love for You is great —<br/>I love You, Lord, O so much!<br/>',NULL,15403,15403);
INSERT INTO stanza VALUES('BF360','1','Be Thou my vision, O Lord of my heart,<br/>Be all else but naught to me, save that Thou art;<br/>Be Thou my best thought in the day and the night,<br/>Both waking and sleeping, Thy presence my light.<br/>',NULL,15404,15404);
INSERT INTO stanza VALUES('BF360','2','Be Thou my wisdom, be Thou my true word,<br/>Be Thou ever with me, and I with Thee Lord;<br/>Be Thou my great Father, and I Thy true son;<br/>Be Thou in me dwelling, and I with Thee one.<br/>',NULL,15405,15405);
INSERT INTO stanza VALUES('BF360','3','Be Thou my breastplate, my sword for the fight;<br/>Be Thou my whole armor, be Thou my true might;<br/>Be Thou my soul''s shelter, be Thou my strong tower:<br/>O raise Thou me heavenward, great Power of my power.<br/>',NULL,15406,15406);
INSERT INTO stanza VALUES('BF360','4','Riches I heed not, nor man''s empty praise:<br/>Be Thou mine inheritance now and always;<br/>Be Thou and Thou only the first in my heart;<br/>O Sovereign of heaven, my treasure Thou art.<br/>',NULL,15407,15407);
INSERT INTO stanza VALUES('BF360','5','High King of heaven, Thou heaven''s bright sun,<br/>O grant me its joys after victory is won;<br/>Great Heart of my own heart, whatever befall,<br/>Still be Thou my vision, O Ruler of all.<br/>',NULL,15408,15408);
INSERT INTO stanza VALUES('BF361','1','God''s economy, His household administration,<br/>is the produce and constitute the Body of Christ,<br/>by dispensing Himself into our being,<br/>to make us the same as He is,<br/>in life and nature but not in the Godhead.<br/>',NULL,15409,15409);
INSERT INTO stanza VALUES('BF361','2','The church of God is the house of the living God,<br/>the pillar and base of the truth,<br/>and the great mystery of godliness —<br/>God was manifested in the flesh.<br/>',NULL,15410,15410);
INSERT INTO stanza VALUES('BF361','3','We must be inoculators, those who inoculate others<br/>against the decline of the church,<br/>by exercising our spirit,<br/>and remaining in the healthy teaching of God''s economy.<br/>',NULL,15411,15411);
INSERT INTO stanza VALUES('BF361','4','We must be inoculators, those who inoculate others<br/>against the decline of the church,<br/>by being a man (a man) of God<br/>with the breath of God.<br/>',NULL,15412,15412);
INSERT INTO stanza VALUES('BF362','1','There are times in my life<br/>When my heart is embittered,<br/>There are questions unanswered,<br/>Yet You’re drawing me<br/>To enter into Your blessed sanctuary<br/>And turning my eyes heavenward<br/>The questions of constant inquiry<br/>Are changed to these words:<br/>',NULL,15413,15413);
INSERT INTO stanza VALUES('BF362','2','Whom do I have in heaven<br/>But You, dear Jehovah?<br/>My flesh and my heart<br/>Constantly fall,<br/>But God’s still the strength of my heart and my portion.<br/>To Him forever I’ll draw near.<br/>I’ve made Jehovah my safe refuge,<br/>So now throughout the years…<br/>',NULL,15414,15414);
INSERT INTO stanza VALUES('BF362','3','Turn my view to see You —<br/>How I need to see Jesus!<br/>Though I don’t understand<br/>The ways that You take.<br/>Lord, make me a babe and suckling always praising,<br/>Enjoying Your worth day by day.<br/>Let each experience constitute me<br/>So Your life I’ll display, In every way.<br/>',NULL,15415,15415);
INSERT INTO stanza VALUES('BF363','1','We need to see a vision of the church<br/>in God the Father with His life and nature<br/>and in the Lord Jesus Christ with<br/>all He is and has done.<br/>',NULL,15416,15416);
INSERT INTO stanza VALUES('BF363','2','Faith as the nature and strength of the work,<br/>love as the motivation for<br/>and characteristic of labor,<br/>and hope as the source of endurance<br/>are the structure of a holy life for the church life.<br/>',NULL,15417,15417);
INSERT INTO stanza VALUES('BF363','3','To walk in a manner worthy of God,<br/>who calls us into His kingdom and glory,<br/>is to live God and express God in our daily living<br/>by walking according to the mingled spirit.<br/>',NULL,15418,15418);
INSERT INTO stanza VALUES('BF363','4','In order to live a holy life for the church life,<br/>we need to cooperate with God''s operation<br/>to establish our heart blameless in holiness<br/>and to sanctify us wholly,<br/>with our spirit, soul, and body preserved complete.<br/>',NULL,15419,15419);
INSERT INTO stanza VALUES('BF364','1','The building of God is the processed Triune God<br/>wrought into us so that under His continual<br/>dispensing we become His enlargement,<br/>expansion, and corporate expression.<br/>(His enlargement, expansion,<br/>and corporate expression.)<br/>',NULL,15420,15420);
INSERT INTO stanza VALUES('BF364','2','The three tabernacles — the type of the tabernacle,<br/>the reality of the tabernacle, and the consummation<br/>of the tabernacle — reveal the goal of God''s economy<br/>to have a corporate people to be His dwelling place<br/>for His expression and representation in eternity.<br/>',NULL,15421,15421);
INSERT INTO stanza VALUES('BF364','3','The intrinsic element of the work of the divine building<br/>is to minister the building and builded God into others<br/>for the building up of the Body of Christ.<br/>',NULL,15422,15422);
INSERT INTO stanza VALUES('BF364','4','The desire of God''s heart is the building of God<br/>into man and the building of man into God<br/>for the building of a great corporate<br/>God-man, the New Jerusalem. (A great corporate<br/>God-man, the New Jerusalem.)<br/>',NULL,15423,15423);
INSERT INTO stanza VALUES('BF365','1','As we become the same as Christ<br/>in life, nature, expression, and function,<br/>we are qualified to work with Him<br/>for His Body.<br/>',NULL,15424,15424);
INSERT INTO stanza VALUES('BF365','2','As we trust in the Lord helplessly,<br/>depend on Him as our love and strength,<br/>and listen to His speaking,<br/>our hope is to be raptured through the redemption<br/>of our body, and our prayer is — "Come, Lord Jesus!"<br/>and our prayer is — "Come, Lord Jesus!"<br/>"Come, Lord Jesus! Lord Jesus, come!”<br/>',NULL,15425,15425);
INSERT INTO stanza VALUES('BF366','1','The divine economy is God''s plan to dispense Christ<br/>Into His chosen people, into His chosen people,<br/>To produce, constitute, and build up the organic<br/>The organic Body of Christ.<br/>',NULL,15426,15426);
INSERT INTO stanza VALUES('BF366','2','The unique oneness of the Body of Christ<br/>Is the oneness of the Spirit, the oneness of the Spirit.<br/>The mingling of the processed Triune God<br/>With all the believers, with all the believers in Christ.<br/>',NULL,15427,15427);
INSERT INTO stanza VALUES('BF366','3','The overcomers see the Body,<br/>Know the Body, care for the Body,<br/>Honor the Body, do the work of the Body,<br/>And keep every principle of the Body.<br/>',NULL,15428,15428);
INSERT INTO stanza VALUES('BF366','4','The overcomers live out and work out<br/>The New Jerusalem, the New Jerusalem.<br/>By the mingling of God with man<br/>For the oneness of the Body, the Body of Christ.<br/>',NULL,15429,15429);
INSERT INTO stanza VALUES('BF367','1','When we live in the mingled spirit<br/>We are learning Christ according to<br/>The reality in Jesus as the Spirit of reality<br/>So that His biography becomes our history<br/>To be the reality of the Body, the Body of Christ.<br/>',NULL,15430,15430);
INSERT INTO stanza VALUES('BF367','2','The Kingdom of God is the Lord Jesus<br/>Sown as a seed into the believers<br/>And developing into a realm<br/>Over which God can rule in the divine life.<br/>',NULL,15431,15431);
INSERT INTO stanza VALUES('BF367','3','Christ''s person with His all-inclusive death<br/>And His wonderful resurrection<br/>Is our all-inclusive replacement<br/>For the producing of the one new man<br/>So we must hear him<br/>And see Jesus only<br/>We must hear Him and see Jesus only.<br/>',NULL,15432,15432);
INSERT INTO stanza VALUES('BF367','4','Let us go forth and preach Christ to all the creation<br/>Proclaiming the gospel, presenting the truth<br/>and ministering life<br/>For the growth, development, and manifestation<br/>Of the Kingdom of God. (The Kingdom of God.)<br/>',NULL,15433,15433);
INSERT INTO stanza VALUES('BF368','1','The fellowship of the eternal life,<br/>the flow of the eternal life within all the believers,<br/>is the reality of living in the Body of Christ.<br/>',NULL,15434,15434);
INSERT INTO stanza VALUES('BF368','2','We know the Triune God by experiencing and enjoying Him<br/>as the One who dwells in our spirit<br/>and desires to spread into our heart.<br/><br/>',NULL,15435,15435);
INSERT INTO stanza VALUES('BF368','3','By the anointing of the all-inclusive compound Spirit,<br/>who is the composition of the Divine Trinity,<br/>we know and enjoy the Father, the Son, and the Spirit<br/>as our life and life supply.<br/>',NULL,15436,15436);
INSERT INTO stanza VALUES('BF368','4','The Son of God has given us an understanding<br/>so that we might know the true One, the genuine and real God,<br/>and be one with Him organically in His Son Jesus Christ,<br/>who is eternal life to us.<br/>',NULL,15437,15437);
INSERT INTO stanza VALUES('BF369','1','In Christ''s death we have been separated from sins,<br/>and in His resurrection we have been enlivened so<br/>that we might live to righteousness under<br/>the government of God.<br/>',NULL,15438,15438);
INSERT INTO stanza VALUES('BF369','2','We must redeem the time to enjoy Christ<br/>as the supreme preciousness of God<br/>so that He can build Himself into us<br/>to make us His spiritual house<br/>and His holy and royal priesthood for the<br/>accomplishment of His heart''s desire.<br/>',NULL,15439,15439);
INSERT INTO stanza VALUES('BF369','3','We should be diligent to pursue the growth<br/>and development of the divine life<br/>and divine nature for a rich entrance<br/>into the eternal kingdom.<br/>',NULL,15440,15440);
INSERT INTO stanza VALUES('BF369','4','As we are contending for the faith,<br/>enjoying the blessed Trinity,<br/>and taking the way of rapture by giving<br/>heed to the prophetic word,<br/>our trust is in our precious Lord and God<br/>as the One who is able to guard us from stumbling<br/>and to set us before His glory without blemish in exultation.<br/>',NULL,15441,15441);
INSERT INTO stanza VALUES('BF370','1','We should not walk by sight<br/>or care for the outward situation.<br/>Rather, in this wonderful faith<br/>we should enjoy its source, which is the Triune God,<br/>to whom we have been joined,<br/>to whom we have been joined, through this faith,<br/>and by this super-excellent love of the Triune God<br/>we should love Him and all those who belong to Him.<br/>Only in this way can we become,<br/>in the current of the church''s degradation,<br/>the overcomers whom the Lord is calling<br/>and is desiring to obtain in Revelation 2 and 3.<br/>',NULL,15442,15442);
INSERT INTO stanza VALUES('BF371','1','This wonderful faith and this super-excellent love,<br/>Are out of the Triune God, who earnestly desires<br/>to be joined to us to be our everything.<br/>',NULL,15443,15443);
INSERT INTO stanza VALUES('BF371','chorus','This Triune God passed through the process,<br/>Of incarnation, crucifixion, resurrection from the dead<br/>And ascension to the heavens on high<br/>And was ultimately consummated as the life-giving Spirit<br/>',NULL,15444,15444);
INSERT INTO stanza VALUES('BF371','2','This Spirit of Life who includes divinity,<br/>Humanity and Christ’s crucifixion,<br/>Resurrection and ascension and is the reality,<br/>Of the all-inclusive Christ<br/>Dwells in our regenerated spirit,<br/>Dwells in our regenerated spirit.<br/>',NULL,15445,15445);
INSERT INTO stanza VALUES('BF372','1','Don’t you want to know your God<br/>What’s hidden in His heart for you<br/>How much He longs for you to come and open up —<br/>To let Him in to every part<br/>Let Him reveal what’s on His heart<br/>What was the joy set before Him?<br/>',NULL,15446,15446);
INSERT INTO stanza VALUES('BF372','chorus','It was for her the Church — His bride<br/>It was for her willingly He died<br/>She is the joy deep in His heart, His masterpiece —<br/>His counterpart<br/>',NULL,15447,15447);
INSERT INTO stanza VALUES('BF372','2','The Lord chose you to be a part<br/>Of His great plan, His work of art<br/>What wonder, what a privilege to satisfy<br/>His yearning to share all He is<br/>Divine unsearchable riches<br/>What wisdom multifarious express?<br/>',NULL,15448,15448);
INSERT INTO stanza VALUES('BF372','3','As we enjoy and enter in<br/>To all He is in building in<br/>To understand the feeling in His heart for us<br/>What love that motivated Him<br/>To come to us despite our sin<br/>Why did He go and sell all that He had?<br/>',NULL,15449,15449);
INSERT INTO stanza VALUES('BF373','1','Oneness is not unity,<br/>Outward agreement<br/>But a life within —<br/>God’s very life!<br/>The Triune God — included us<br/>In His divine —<br/>Oneness — Oneness<br/>',NULL,15450,15450);
INSERT INTO stanza VALUES('BF373','2','That they all may be one;<br/>Even as You Father, are in Me<br/>And I in You —<br/>That they may be —<br/>May be in us.<br/>Oneness — Oneness.<br/>',NULL,15451,15451);
INSERT INTO stanza VALUES('BF374','1','God needs some young people<br/>To keep themselves from defilement,<br/>Some who will stand against<br/>The current of this age<br/>Who will declare,<br/>Lord, from today:<br/>We’re going to flee<br/>Youthful lusts<br/>And pursue<br/>Righteousness<br/>Me and you<br/>Who call upon the Lord<br/>From a pure heart<br/>Keep purifying our hearts,<br/>Enlightening every part.<br/>O Lord, till the church<br/>Is all we see.<br/>',NULL,15452,15452);
INSERT INTO stanza VALUES('BF374','2','God needs some young people<br/>To keep themselves from defilement,<br/>Some who will stand against<br/>The current of this age<br/>Who will declare,<br/>Lord, from today:<br/>We’re going to flee<br/>Youthful lusts<br/>And pursue<br/>Righteousness<br/>With the view<br/>To the building of the church<br/>Not wasting time,<br/>Pressing on toward the goal,<br/>Occupied with the prize.<br/>O Lord, we’ve been wrecked.<br/>We’ll build Your Church.<br/>',NULL,15453,15453);
INSERT INTO stanza VALUES('BF375','1','Since long before the world began,<br/>In Your heart You longed for a Bride;<br/>''Tis mutual dwelling, Your glorious plan;<br/>With me e''er to abide.<br/>Not knowing Your heart,<br/>I sinned and thus should die;<br/>Yet You shed Your blood to set me free.<br/>You gave me Your life, to me drew nigh;<br/>Wondrous love! We two one forever will be.<br/>',NULL,15454,15454);
INSERT INTO stanza VALUES('BF375','2','O glorious divine love! How can I fathom,<br/>Higher than the sky, deeper than the sea;<br/>It crushes death''s pow''r and Satan''s kingdom;<br/>Nothing can compare with Your love to me<br/>So fervid and so deep, so gentle and so true;<br/>I''m in love, Lord, with You.<br/>',NULL,15455,15455);
INSERT INTO stanza VALUES('BF375','3','I give You my heart, my life and my soul,<br/>Come suffering or joy whatever betide.<br/>By Your boundless grace, I''ll lay down my all<br/>To build up Your church, Your glorious Bride;<br/>Your heart to satisfy, mutual abode we''ll be<br/>In eternity.<br/>',NULL,15456,15456);
INSERT INTO stanza VALUES('BF376','1','Prod me with Your loving hands,<br/>Stir me from my deep impasse.<br/>I long to flee this stagnant rut;<br/>My soul, my prison, deadened lot,<br/>Which end is just to taste Your wrath;<br/>So set me on the narrow path.<br/>Thorns and thistles may line this road<br/>But it leads me to the mutual abode.<br/>',NULL,15457,15457);
INSERT INTO stanza VALUES('BF376','chorus','Lift me up with Your mighty hand<br/>Above this frenzied earthly land.<br/>Set me on the mount to see<br/>What the world can offer me;<br/>Till I see the vanity from on high<br/>And earthly desires I bid goodbye<br/>And set my eyes on You.<br/>',NULL,15458,15458);
INSERT INTO stanza VALUES('BF377','1','The goal of the gospel is that loving the Lord Jesus<br/>with the first and best love.<br/>We would pour out upon HIm, pour out upon Him<br/>what is most precious to us.<br/>Even our most costly and valuable spiritual treasure, 	wasting ourselves upon Him.<br/>Even our most costly and valuable spiritual treasure<br/>wasting ourselves upon Him.<br/>',NULL,15459,15459);
INSERT INTO stanza VALUES('BF378','1','Rain on me; rain on me;<br/>Let Your mercy rain on me;<br/>It is not by willing or by running, Lord;<br/>Let Your mercy rain on me.<br/>',NULL,15460,15460);
INSERT INTO stanza VALUES('BF378','2','Reign in me; reign in me;<br/>May Your life, Lord, reign in me,<br/>By Your grace abundant and Your righteousness;<br/>May Your life, Lord, reign in me.<br/>',NULL,15461,15461);
INSERT INTO stanza VALUES('BF378','3','Overcome, overcome;<br/>Lord, I pray to overcome,<br/>By the Spirit sevenfold intensified;<br/>Lord, I pray to overcome.<br/>',NULL,15462,15462);
INSERT INTO stanza VALUES('BF378','4','Grow in me; grow in me;<br/>For the Body grow in me,<br/>Through the rich dispensing of Your life supply;<br/>For the Body grow in me.<br/>',NULL,15463,15463);
INSERT INTO stanza VALUES('BF378','5','Transform me; transform me;<br/>For the Body transform me;<br/>I behold Your glory with an unveiled face;<br/>For the Body transform me.<br/>',NULL,15464,15464);
INSERT INTO stanza VALUES('BF378','6','Lord, gain me; Lord, gain me;<br/>In the Body, Lord, gain me,<br/>For the full expression of the Triune God;<br/>In the Body, Lord, gain me.<br/>',NULL,15465,15465);
INSERT INTO stanza VALUES('BF378','7','Lord, blend me; Lord, blend me;<br/>In the Body, Lord, blend me,<br/>For the consummation—New Jerusalem;<br/>In the Body, Lord, blend me.<br/>',NULL,15466,15466);
INSERT INTO stanza VALUES('BF379','1','Once I thirsted for a fountain,<br/>Something deep that would satisfy,<br/>But the fountain that I''d drink from,<br/>Left me searching and still so dry.<br/>Then one day I found Him,<br/>He satisfied my thirst,<br/>Became in me a deeper source<br/>Whence living waters burst.<br/>Now I drink Him!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,15467,15467);
INSERT INTO stanza VALUES('BF379','2','After tasting such a fountain,<br/>Longed my heart for a place of springs;<br/>Caught a vision on a mountain,<br/>In Jerusalem''s gathering.<br/>Then one day He found me,<br/>He brought me to the church,<br/>Pleasures here abound fore''er<br/>I''ve given up my search.<br/>Hallelujah!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,15468,15468);
INSERT INTO stanza VALUES('BF379','3','Empty wanderer drop the striving —<br/>Isn''t worth all the troublin'';<br/>Open up your heart believing,<br/>Call "Lord Jesus" and He''ll come in!<br/>Then today you''ll find Him,<br/>And calling on His name,<br/>You''re joined to Him, you''re one with Him —<br/>You''ll never be the same.<br/>You won''t want to!<br/>Jesus, Jesus is my life now,<br/>Jesus, Jesus is my life;<br/>I''m fully satisfied now,<br/>Jesus, Jesus is my life.<br/>',NULL,15469,15469);
INSERT INTO stanza VALUES('BF380','1','O I''m a man —<br/>I''m the meaning of the universe;<br/>Yes, I''m a man —<br/>I''m the meaning of the universe.<br/>God made me such,<br/>I am so much;<br/>I''m the center and the meaning of the universe.<br/>',NULL,15470,15470);
INSERT INTO stanza VALUES('BF380','2','Christ lives in me —<br/>He''s the meaning of my human life;<br/>Christ lives in me —<br/>He''s the meaning of my human life.<br/>Yes, He''s in me<br/>My all to be;<br/>He''s the meaning and reality of my human life.<br/>',NULL,15471,15471);
INSERT INTO stanza VALUES('BF380','3','The church is Christ —<br/>His expression on the earth today;<br/>The church is Christ —<br/>His expression on the earth today.<br/>This corporate man<br/>Fulfills God''s plan,<br/>That this man may have dominion over all the earth.<br/>',NULL,15472,15472);
INSERT INTO stanza VALUES('BF380','4','The local church —<br/>It''s the new and real family life;<br/>The local church —<br/>It''s the new and real family life.<br/>We have the way<br/>To live today —<br/>Eating, drinking Christ we''re built up as the<br/>local church.<br/>',NULL,15473,15473);
INSERT INTO stanza VALUES('BF380','5','What shall we do?<br/>We should go and tell the world of this.<br/>What shall we do?<br/>We should go and tell the world of this.<br/>Disciple all —<br/>This is our call.<br/>Let us go and spread the news abroad to every land.<br/>',NULL,15474,15474);
INSERT INTO stanza VALUES('BF381','1','In this godless age,<br/>Lord, You need some Samuels<br/>Burdened with a vision clear of Your economy.<br/>Where''s Your ark today?<br/>And the ones who''d care for You,<br/>E''en to put themselves aside to gain Your heart''s desire?<br/>Raise up some to meet Your need, some Nazarites,<br/>Prophets, priests, and judges, and men of prayer,<br/>Speaking forth Your Word, with Your authority,<br/>A photo of Your heart for Your move.<br/>',NULL,15475,15475);
INSERT INTO stanza VALUES('BF381','2','Train us today,<br/>Full of vision, seeking You,<br/>We''d await Your timing, fully subject to Your will,<br/>Treasuring Your face,<br/>Staying in Your presence, Lord;<br/>E''en the very index of Your eye would we obey.<br/>Raise up some to meet Your need, some Nazarites,<br/>To bring in Your kingdom on earth today,<br/>Taking You as King that You might return<br/>To usher in the end of the age.<br/>',NULL,15476,15476);
INSERT INTO stanza VALUES('BF382','1','The vict''ry''s won! The Lord has triumphed o''er the foe!<br/>The vict''ry shout is heard afar and near!<br/>His blood prevails! It giveth us the victory!<br/>And soon the mighty Victor will appear.<br/>',NULL,15477,15477);
INSERT INTO stanza VALUES('BF382','chorus','(Sisters sing)<br/>The vict''ry''s won! O Christian brothers,<br/>The vict''ry''s won! This shout we raise!<br/>In Zion''s city, proclaim His vict''ry<br/>Till all the earth is filled with praise.<br/>',NULL,15478,15478);
INSERT INTO stanza VALUES('BF382','chorus','(Brothers sing)<br/>The vict''ry''s won! O Christian sisters,<br/>The mighty work of Christ is done!<br/>The Lord victorious has conquered for us —<br/>Eternal joys have now begun.<br/>',NULL,15479,15479);
INSERT INTO stanza VALUES('BF382','2','The vict''ry''s won! We''ve overcome the enemy.<br/>The Word of God we boldly testify.<br/>God speaks His Word — in it there''s life and liberty —<br/>And by the Word the devil we defy.<br/>',NULL,15480,15480);
INSERT INTO stanza VALUES('BF382','3','The vict''ry''s won! Beneath our feet the enemy,<br/>For we love not our soul life unto death;<br/>And so we shout, "O Lord, You are our victory!"<br/>And praise our God with all our spirit''s breath.<br/>',NULL,15481,15481);
INSERT INTO stanza VALUES('BF383','1','Marching on, marching on, in the Spirit marching on;<br/>Hallelujah! the churches march on.<br/>Marching on, marching on, in the Spirit marching on;<br/>Hallelujah! the churches march on.<br/>In the church we see<br/>The Lord''s recovery<br/>And for it the Spirit seven-strong.<br/>The world will know,<br/>Wherever we shall go,<br/>That in our age the Lord''s marching on!<br/>',NULL,15482,15482);
INSERT INTO stanza VALUES('BF384','1','Life is God the Father in Christ Jesus<br/>As the Spirit flowing into us.<br/>How enjoyable, this Person wonderful!<br/>He''s our life so rich and bountiful.<br/>',NULL,15483,15483);
INSERT INTO stanza VALUES('BF384','2','We experienced regeneration<br/>When we opened to this living One.<br/>We were born again; another life came in.<br/>Now it floods us till we''re full of Him.<br/>',NULL,15484,15484);
INSERT INTO stanza VALUES('BF384','3','He within us is the living Spirit<br/>In our spirit, flowing out of it<br/>Into all our heart, transforming every part<br/>By the life which He Himself imparts.<br/>',NULL,15485,15485);
INSERT INTO stanza VALUES('BF384','4','Now He must have our cooperation.<br/>We must set our mind upon the Son.<br/>We must turn away from all that leads astray,<br/>Till our mind is set on Him each day.<br/>',NULL,15486,15486);
INSERT INTO stanza VALUES('BF384','5','Lord, our human spirit now contains You.<br/>Still Your purpose in us You would do;<br/>If our wandering mind would leave old thoughts behind,<br/>Then Your life and peace in it we''ll find.<br/>',NULL,15487,15487);
INSERT INTO stanza VALUES('BF384','6','Lord, we would our every thought be captured<br/>By the rich enjoyment in Your Word.<br/>In it we''re supplied, our mind there will abide,<br/>Till our thoughts are wholly sanctified.<br/>',NULL,15488,15488);
INSERT INTO stanza VALUES('BF384','7','Let''s keep practicing the application<br/>Of this life by minding just the Son.<br/>Praise Him for the way to live by Him today!<br/>Lord, on Your our minds will ever stay.<br/>',NULL,15489,15489);
INSERT INTO stanza VALUES('CB1','1','Himayaong Dios Amahan,<br/>Cristo nga Anak;<br/>Espiritu himayaon<br/>Sa dayon.<br/>',NULL,16124,1);
INSERT INTO stanza VALUES('CB1','2','Kabuhatan kon sud-ongon,<br/>O pagkatahum,<br/>Matandog mi ug magsimba<br/>Maghilom.<br/>',NULL,16125,2);
INSERT INTO stanza VALUES('CB1','3','Pagkadako’s pangandoy Mo<br/>May mga anak<br/>Nga mahigugma’g magdayeg<br/>Kanimo!<br/>',NULL,16126,3);
INSERT INTO stanza VALUES('CB1','4','Diha’s bugna pangagpas Mo,<br/>Ipadayag’s tawo<br/>Mailahang sekreto sa<br/>Pagmahal Mo.<br/>',NULL,16127,4);
INSERT INTO stanza VALUES('CB1','5','Giwagtang dautang gahum<br/>Diha kang Cristo!<br/>Nia’s bag-ong kabuhatan<br/>Magsisimba!<br/>',NULL,16128,5);
INSERT INTO stanza VALUES('CB1','6','Himayaong Dios Amahan,<br/>Cristo nga Anak;<br/>Espiritu himayaon,<br/>Sa dayon.<br/>',NULL,16129,6);
INSERT INTO stanza VALUES('CB7','1','Himayaon ang Amahan!<br/>Himayaon ang Anak!<br/>Himayaong Espiritu,<br/>Dios nga Tulo-sa-usa!<br/>',NULL,16130,1);
INSERT INTO stanza VALUES('CB7','chorus','Daygon Siya, daygon Siya!<br/>Daygon ang Tulo-usa!<br/>Himayaon, himayaon!<br/>Kahibulongang buhat sa Dios!<br/>',NULL,16131,2);
INSERT INTO stanza VALUES('CB7','2','Daygong Amahan nagplano!<br/>Daygong Anak naghuman!<br/>Espiritung nagpalatay!<br/>Daygon ang Dios nagbuhat!<br/>',NULL,16132,3);
INSERT INTO stanza VALUES('CB8','1','Tinubdan S’ya’s kabulahan,<br/>Dios dayga, mga linalang;<br/>Dayga S’ya, langitnong panon,<br/>Amahan, Anak, Esp’ritu.<br/>',NULL,16133,1);
INSERT INTO stanza VALUES('CB8','2','Dayga, Amahan tinubdan,<br/>Dayga, Anak agianan;<br/>Ang Espiritu m’oy agay,<br/>Pahat natong nagkalipay!<br/>',NULL,16134,2);
INSERT INTO stanza VALUES('CB10','1','O Dios, Amahan Ka’s dayon,<br/>Ikawng Dakong Ako Mao;<br/>Karaan pa sa karaan,<br/>Sa wa pang kapanahonan!<br/>',NULL,16135,1);
INSERT INTO stanza VALUES('CB10','2','Gikan sa dayon Ikaw Dios,<br/>Dapit, panahon, gilabwan!<br/>Kahupnganan Ka sa dayon,<br/>Way sinugda’g pagkatapos!<br/>',NULL,16136,2);
INSERT INTO stanza VALUES('CB10','3','Ikaw ang tinubdan’s tanan,<br/>Sa wala pang kalangitan!<br/>Una pa’s tanang nag-una,<br/>Ug labing sayo sa tanan!<br/>',NULL,16137,3);
INSERT INTO stanza VALUES('CB10','4','Kinabuhi Kang molungtad,<br/>Nga wala gyuy pagkalaglag;<br/>Molungtad labaw sa tanan,<br/>Ikaw walay katapusan!<br/>',NULL,16138,4);
INSERT INTO stanza VALUES('CB10','5','Kay una, Ikaw ang Alpa,<br/>Ulahi sab, busa Omega;<br/>Sa sinugda’g katapusan,<br/>Kompleto, hingpit, way kulang!<br/>',NULL,16139,5);
INSERT INTO stanza VALUES('CB10','6','Katuigan Mo way pagtapos,<br/>Dagaya, way sukod, O Dios!<br/>Kahupong Mo pagkadako,<br/>Kahingpit Mo, O daygon ko!<br/>',NULL,16140,6);
INSERT INTO stanza VALUES('CB11','1','Amahan, Espiritu Ka,<br/>Balaan sa tanan;<br/>Sa espiritu simbahon,<br/>Tinuod Kang tawgon.<br/>',NULL,16141,1);
INSERT INTO stanza VALUES('CB11','2','Gihimoan’s espiritu,<br/>Aron makasimba;<br/>Magtubagay’s espiritu<br/>Mahiusa kita.<br/>',NULL,16142,2);
INSERT INTO stanza VALUES('CB11','3','Sa Anak Ikaw nianhi,<br/>Anak, Espiritu,<br/>Sa espiritu nisulod,<br/>Kini grasya gayud!<br/>',NULL,16143,3);
INSERT INTO stanza VALUES('CB11','4','Ang Anak dayong Pulong Mo,<br/>Pulong sab Esp’ritu;<br/>Kinabuhi nga magbag-o<br/>Sa esp’ritu namo.<br/>',NULL,16144,4);
INSERT INTO stanza VALUES('CB11','5','Nausang Espiritu Mo’s<br/>Among espiritu;<br/>Nagsaksi, nagpamatuod,<br/>Gianak mi Nimo.<br/>',NULL,16145,5);
INSERT INTO stanza VALUES('CB11','6','Gigiyahan’s Espiritu,<br/>Magsunod mi Nimo;<br/>Magmaespirituhanon,<br/>Sa kalinaw pun-on.<br/>',NULL,16146,6);
INSERT INTO stanza VALUES('CB11','7','Simbahon Ka’s espiritu<br/>Tawgon’s espiritu,<br/>Hangtud kami mahigawas,<br/>Dagway Mo madayag.<br/>',NULL,16147,7);
INSERT INTO stanza VALUES('CB11','8','Karon daygon Ka, Amahan,<br/>Kay Espiritu Ka!<br/>Sa Esp’ritu’g kamat’oran<br/>Kami mag-ambahan.<br/>',NULL,16148,8);
INSERT INTO stanza VALUES('CB12','1','Tinubdan Ka’s kinabuhi<br/>Diosnon, dato, gawas;<br/>Buhing tubig Kang nag-awas<br/>Hangtud’s eternidad.<br/>',NULL,16149,1);
INSERT INTO stanza VALUES('CB12','2','Dios sa Anak niagay Ka,<br/>Diha sa katawhan;<br/>Espiritung niagay sab<br/>Dinhi’s among sulod.<br/>',NULL,16150,2);
INSERT INTO stanza VALUES('CB12','3','Bisan sad-an mi’g dautan,<br/>Nahilayo Nimo,<br/>Gitubos Mo’g gihatagan<br/>Grasya’g kinabuhi.<br/>',NULL,16151,3);
INSERT INTO stanza VALUES('CB12','4','Sagad makasala Nimo,<br/>Espiritu magsubo;<br/>Apan nia gihapon Ka,<br/>Kinabuhi m’oy dala.<br/>',NULL,16152,4);
INSERT INTO stanza VALUES('CB12','5','Diha’s Anak, Espiritu,<br/>Nasagol Ka namo;<br/>Sa pakig-ambit nagdihog<br/>Labi pang nagtubo!<br/>',NULL,16153,5);
INSERT INTO stanza VALUES('CB12','6','Gugma sa Dios, grasyang Cristo,<br/>Agay’s Espiritu,<br/>Nagpaambit’s kadato’s Dios<br/>Walay pagkatapos.<br/>',NULL,16154,6);
INSERT INTO stanza VALUES('CB12','7','Usa ang Amahan, Anak<br/>Ug ang Espiritu,<br/>Sa pag-atiman kanato<br/>Daygon, higugmaon.<br/>',NULL,16155,7);
INSERT INTO stanza VALUES('CB13','1','Dios, Ikaw gugma’g kahayag,<br/>Sa Anak kinabuhi;<br/>Gugmang nadayag, nagdan-ag,<br/>Ug kami nangabuhi.<br/>',NULL,16156,1);
INSERT INTO stanza VALUES('CB13','chorus','Gugma Ka’g kahayag!<br/>Sa Anak kinabuhi;<br/>Gugmang nadayag, nagdan-ag,<br/>Ug kami nangabuhi!<br/>',NULL,16157,2);
INSERT INTO stanza VALUES('CB13','2','Gugma m’oy pagkamao Mo,<br/>Buhat Nimo kahayag;<br/>Gugma’s sulod, dan-ag’s gawas,<br/>Gugma uban’s kahayag.<br/>',NULL,16158,3);
INSERT INTO stanza VALUES('CB13','3','Sa grasya gugma nadayag,<br/>Kamat’oran kahayag;<br/>Sa gugma napa’muslan Ka,<br/>Sa kahayag naila.<br/>',NULL,16159,4);
INSERT INTO stanza VALUES('CB13','4','Gida’ Ka’s gugma’s Calvario,<br/>Kinabuhi naamo;<br/>Sa kahayag Mo nasabtan,<br/>Magamit Imong dugo.<br/>',NULL,16160,5);
INSERT INTO stanza VALUES('CB13','5','Sa gugma kinabuhi Ka,<br/>Nisulod, makig-ambit;<br/>Sa kahayag nagpahinlo,<br/>Mabuhi’s pakig-ambit.<br/>',NULL,16161,6);
INSERT INTO stanza VALUES('CB13','6','Sa lamdag, dugo naghinlo,<br/>Nasayrang pagdihog Mo;<br/>Labi nang nag-agay namo,<br/>Kinabuhi’s gugma Mo.<br/>',NULL,16162,7);
INSERT INTO stanza VALUES('CB13','7','Sa gugma gipanganak Mo,<br/>Tawgon Ka nga Amahan;<br/>Kahayag magwa’s kangitngit,<br/>Hangtud masama Nimo.<br/>',NULL,16163,8);
INSERT INTO stanza VALUES('CB13','chorus','O grasyang matuod!<br/>Gugma Ka’g kahayag!<br/>Magdayeg mi’s way paghunong,<br/>Ikaw gugma’g kahayag!<br/>',NULL,16164,9);
INSERT INTO stanza VALUES('CB15','1','O Dios pagkalabaw Mo,<br/>Pagkabalaan gyud!<br/>Dili Ka man hitupngan’s<br/>Imong pagkalabaw!<br/>Ikaw labing balaan<br/>Sa tanan nga tanan!<br/>Kinaiya Mo’g gahum<br/>Labaw’s tanang butang.<br/>',NULL,16165,1);
INSERT INTO stanza VALUES('CB15','2','Balaan Kang naglahi,<br/>Matarung ug putli;<br/>Walay gamay nga apan,<br/>Kay Ikaw hingpit man;<br/>Kanimo way igtandi,<br/>Walay ikaindig;<br/>Bisan unsay ipuli,<br/>Pagpasipala man.<br/>',NULL,16166,2);
INSERT INTO stanza VALUES('CB15','3','Ikaw labing halangdon!<br/>Labihan katahum;<br/>Way makatandi Nimo,<br/>Sa pagkamatarung.<br/>Ang Imong pagkatahum<br/>Labaw sab kaayo;<br/>Matahum’s tanang tahum,<br/>Walay makatupong.<br/>',NULL,16167,3);
INSERT INTO stanza VALUES('CB15','4','Kinaiyang balaan<br/>Giandam kanamo;<br/>Kinaiyang ginahin<br/>Kami nakabahin.<br/>Sa Imong pagkalabaw<br/>Kami nakaambit;<br/>Busa Ikaw m’oy sundon<br/>Hangtud’s pagkahamtong.<br/>',NULL,16168,4);
INSERT INTO stanza VALUES('CB15','5','Magdayeg mi’g magsimba’s<br/>Pagkabalaan Mo,<br/>Wala Ka may kaparang,<br/>Labaw Ka sa tanan.<br/>Kinaiya Mo daygon<br/>Lahi, talagsaon;<br/>Naambitan ug karon<br/>Amoa na’s dayon.<br/>',NULL,16169,5);
INSERT INTO stanza VALUES('CB16','1','Amahan kanunayng lunhaw,<br/>Kanunay Kang bag-o;<br/>Buhi’s dayon nga Ginoo,<br/>Daw yamog, kapresko.<br/>',NULL,16170,1);
INSERT INTO stanza VALUES('CB16','chorus','Amahan, way pagkausab,<br/>Di gyud Ka madaan;<br/>Bisan’s daghang katuigan<br/>Kanunay Kang bag-o.<br/>',NULL,16171,2);
INSERT INTO stanza VALUES('CB16','2','Ikaw ang Dios, ug ang “bag-o“;<br/>Kon wala Ka, daan;<br/>Kon naa, bisan’s kadugay<br/>Magpabiling bag-o!<br/>',NULL,16172,3);
INSERT INTO stanza VALUES('CB16','3','Ang hatag Mong panalangin,<br/>May Imong kabag-o;<br/>Pakigsaad, dalan, tanan,<br/>Magpabiling bag-o.<br/>',NULL,16173,4);
INSERT INTO stanza VALUES('CB16','4','Kami bag-ong binuhat Mo<br/>Bag-o’g espiritu;<br/>Adlaw-adlaw gibag-o mi<br/>Sa kinabuhi Mo.<br/>',NULL,16174,5);
INSERT INTO stanza VALUES('CB16','5','Bag-ong yuta’g langit puy-an<br/>Ug bag-ong syudad Mo;<br/>Bag-ong bunga’s matag bulan<br/>M’oy sangkap sa tanan.<br/>',NULL,16175,6);
INSERT INTO stanza VALUES('CB16','6','Amahan kanunayng bag-o,<br/>Bag-ong tanan Nimo;<br/>Sa bag-ong awit awitan<br/>Sa pagdayeg tingban!<br/>',NULL,16176,7);
INSERT INTO stanza VALUES('CB17','1','Amahang Dios, pagtan-aw’s kabuhatan,<br/>Mga katingad-an’s langit, yuta,<br/>Di maisip dagko ug gagmayng butang,<br/>Nagpadayag nga Ikaw gamhanan.<br/>',NULL,16177,1);
INSERT INTO stanza VALUES('CB17','chorus','Mag-awit ko sa pagdayeg Nimo,<br/>Kahibudngan! Labing dako!<br/>Mag-awit ko hangtud’s eternidad,<br/>Kahibudngan! Labing dako!<br/>',NULL,16178,2);
INSERT INTO stanza VALUES('CB17','2','Napa’muslan grasya sa kaluwasan,<br/>Sa Anak nga Imong gipadala,<br/>Aron mahimong kabuhatang bag-o,<br/>Magpadayag sa kinabuhi Mo.<br/>',NULL,16179,3);
INSERT INTO stanza VALUES('CB17','3','Sa iglesia bulahang nag-ambitan,<br/>Ang minilyong may kinabuhi Mo,<br/>Gitukod Mo nga Imong puloy-anan,<br/>Magpadayag’s Imong kahupnganan.<br/>',NULL,16180,4);
INSERT INTO stanza VALUES('CB17','4','Nagpaabot kami sa katumanan,<br/>Bag-ong Jerusalem mag-ambitan,<br/>Yuta’g langit, tanang butang mabag-o,<br/>Ikaw sa tanan madayag didto.<br/>',NULL,16181,5);
INSERT INTO stanza VALUES('CB18','1','Matumanon, kasaligan,<br/>Akong Dios Amahan!<br/>Uniberso’g tanang butang,<br/>Nagpamatuod man!<br/>',NULL,16182,1);
INSERT INTO stanza VALUES('CB18','chorus','Pagkamatinumanon Mo,<br/>Ikaw simbahon ko;<br/>Lig-on pa sa kalangitan<br/>Akong kasaligan!<br/>',NULL,16183,2);
INSERT INTO stanza VALUES('CB18','2','Way landong bisan gamay lang,<br/>Nga Ikaw mausab;<br/>Unsa kanhi, unsa karon,<br/>Mao gyud Ka’s dayon.<br/>',NULL,16184,3);
INSERT INTO stanza VALUES('CB18','3','Pulong Mo segurado gyud,<br/>Dili man molubad;<br/>Yuta’g langit mangawala,<br/>Pulong Mo molungtad!<br/>',NULL,16185,4);
INSERT INTO stanza VALUES('CB18','4','Mga gasa way pagbakwi,<br/>Pagtawag mao sab;<br/>Ngalan Mo sama’s kaluoy,<br/>Grasya Mo molungtad.<br/>',NULL,16186,5);
INSERT INTO stanza VALUES('CB18','5','Ang pulong ug pagtuman Mo,<br/>M’oy garantiya ko;<br/>Niini’g sa kal’wasan Mo,<br/>Nakaseguro ko!<br/>',NULL,16187,6);
INSERT INTO stanza VALUES('CB18','6','Kon mawad-an ko’s pagsalig,<br/>Ikaw kasaligan;<br/>Kaugalingon di talikdan,<br/>Sa pulong magtuman.<br/>',NULL,16188,7);
INSERT INTO stanza VALUES('CB18','7','Buhaton Mo ang gisaad<br/>Ug tuyo’s pagtawag;<br/>Pagkamatinumanon Mo<br/>Kan-on adlaw-adlaw.<br/>',NULL,16189,8);
INSERT INTO stanza VALUES('CB18','8','Ang bangaw m’oy nagpahayag,<br/>Ikaw kasaligan,<br/>Unya sa balaang syudad,<br/>M’oy dagwayng madayag!<br/>',NULL,16190,9);
INSERT INTO stanza VALUES('CB19','1','Dako ang pagkamatinumanon Mo,<br/>Dios Amahan wa Kay pagkausab;<br/>Kaluoy Mo wala gyuy pagkapakyas,<br/>Unsa Ka kanhi mao sa dayon.<br/>',NULL,16191,1);
INSERT INTO stanza VALUES('CB19','chorus','Matinumanon Ka! Matinumanon Ka!<br/>Matag buntag bag-ong kaluoy Mo;<br/>Naghatag Ka sa tanang kinahanglan,<br/>Pagkamatinumanon Mo gayud!<br/>',NULL,16192,2);
INSERT INTO stanza VALUES('CB19','2','Ting-init, tingtugnaw ug tingbuklad ba,<br/>Adlaw, Bulan ug kabitoonan;<br/>Niduyog pagsaksi’s kinaiyahan,<br/>Sa Imong pagkamatinumanon.<br/>',NULL,16193,3);
INSERT INTO stanza VALUES('CB19','3','Gipasaylo’s sala, kalinawng lungtad,<br/>Presensyang naglipay ug naggiya;<br/>Kusog ko karon, paglaum sa ugma,<br/>Kabulahan naako’g daghan pa!<br/>',NULL,16194,4);
INSERT INTO stanza VALUES('CB20','1','Amahan, among simbahon,<br/>Alang’s pagkamatarung;<br/>Gimatarung dihang Cristo,<br/>Tanlag wa na magsubo.<br/>Matarung Ka’g matumanon,<br/>Barugang katarung Mo;<br/>Way di tarung diha Nimo,<br/>Matarung gyung kamot Mo.<br/>',NULL,16195,1);
INSERT INTO stanza VALUES('CB20','2','Sala gipapas-ang Jesus,<br/>Gipatay’s hustisya Mo;<br/>Gituman tanang pangayo,<br/>Sa balaan Mong sugo.<br/>S’ya’y nagbayad’s tanang sala,<br/>Hingpit Ka nga gitagbaw;<br/>Labing matarung namong Dios,<br/>Maningil pa ba namo?<br/>',NULL,16196,2);
INSERT INTO stanza VALUES('CB20','3','Dios Amahan gidawat Mo,<br/>Si Jesus Puli namo;<br/>Alang’s di tarung gihukman,<br/>Usbon ba diayng harong?<br/>Pamatuod sa hustisya,<br/>Sa too Mo nilingkod S’ya;<br/>S’yang hingpit katagbawan Mo,<br/>Nagtagbo’s kin’hanglan Mo.<br/>',NULL,16197,3);
INSERT INTO stanza VALUES('CB20','4','Pagka’tarung Mo naamo,<br/>Tungod sa dugong Jesus;<br/>Napanalipdan’s katarung,<br/>Way makatarug namo;<br/>Kami’s pagkamatarung Mo,<br/>Di na gyud mahukman pa;<br/>Hangtud’s Bag-ong Jerusalem,<br/>Kini ipamatuod.<br/>',NULL,16198,4);
INSERT INTO stanza VALUES('CB21','1','Daygong pagkamatarung Mo,<br/>Imantalang hustisya Mo,<br/>Hingpit pamatud-an.<br/>Maghuhukom Ka’s katawhan,<br/>Kanimo way inhustisya<br/>O kasaypanan ba.<br/>',NULL,16199,1);
INSERT INTO stanza VALUES('CB21','2','Gipasukad ang trono Mo’s,<br/>Lig-ong pagkamatarung Mo,<br/>O Dios nga balaan!<br/>Niining pagkamatarung,<br/>Grasya naghari dihang Cristo,<br/>Kalinaw naamo.<br/>',NULL,16200,2);
INSERT INTO stanza VALUES('CB21','3','Tungod’s pagkamatarung Mo,<br/>Anak Mo nagpakamatay<br/>Sa pagtubos namo;<br/>Mao gayuy nagmatarung,<br/>Pag-aplikar’s katubsanan,<br/>Naamong kal’wasan.<br/>',NULL,16201,3);
INSERT INTO stanza VALUES('CB21','4','Pagpakita’s katarung Mo<br/>Gipasaylo Mong mga tawo<br/>Sa kanhing panahon;<br/>Aron makitang katarung<br/>Nagpasaylo Ikaw karon<br/>Sa makasasala.<br/>',NULL,16202,4);
INSERT INTO stanza VALUES('CB21','5','Tanang tawo hukman Mo unya,<br/>Pagkamatarung i’dayag<br/>Ni Cristo nga Anak;<br/>Magbarug kaming malig-on,<br/>Kini among pamatud-an,<br/>Sa grasya hatagan.<br/>',NULL,16203,5);
INSERT INTO stanza VALUES('CB21','6','Gingharian may hustisya,<br/>Tukoron Mo’s kadaitan,<br/>Tanan mahiusa;<br/>Ang bag-ong langit ug yuta<br/>Hingpit na nga magmatarung<br/>Sumala’s saad Mo.<br/>',NULL,16204,6);
INSERT INTO stanza VALUES('CB22','1','Simbahon Ka, O Amahan,<br/>Ug amo nga awitan;<br/>Labing habog Ka’g balaan,<br/>Daygon “Ngalang Balaan.”<br/>',NULL,16205,1);
INSERT INTO stanza VALUES('CB22','2','Mapanggaon Ka, Amahan,<br/>Gawi Mo matarung man;<br/>Kinaiya Mo balaan,<br/>Kami gipaambitan.<br/>',NULL,16206,2);
INSERT INTO stanza VALUES('CB22','3','Kami’s dayon gibalaan<br/>Sa dugo sa Ginoo;<br/>Makasasala gigahin<br/>Sa Pulong’s kamat’oran.<br/>',NULL,16207,3);
INSERT INTO stanza VALUES('CB22','4','Pinaagi’s Espiritu,<br/>Gibalaan mi Nimo;<br/>Espiritu, kalag, lawas<br/>Hingpit nga balaanon.<br/>',NULL,16208,4);
INSERT INTO stanza VALUES('CB22','5','O balaang kinabuhi,<br/>Sa grasya Mo naamo;<br/>Himoon ming umalambit<br/>Sa pagkabalaan Mo.<br/>',NULL,16209,5);
INSERT INTO stanza VALUES('CB22','6','Unya sa balaang syudad,<br/>Hingpit Mong kabalaan,<br/>Bug-os namong maambitan,<br/>Isulti, “Balaan Ka.”<br/>',NULL,16210,6);
INSERT INTO stanza VALUES('CB23','1','O Amahan, sa kaalam<br/>Ug kabubut-on Mo,<br/>Way katapusang tuyo Mo<br/>Tumanon sa Anak.<br/>',NULL,16211,1);
INSERT INTO stanza VALUES('CB23','chorus','Pagkalalum’s kaalam Mo,<br/>Kinsay makatugkad?<br/>Dios Amahan’s kaalam Mo<br/>Kami gikaloy-an!<br/>',NULL,16212,2);
INSERT INTO stanza VALUES('CB23','2','Ang buhat Mo katingad-an,<br/>Amo bang masabtan?<br/>Gikan, alang Nimong tanan,<br/>Kaalam mapalgan.<br/>',NULL,16213,3);
INSERT INTO stanza VALUES('CB23','3','Tanan gibutang sa sala,<br/>Kaluoy makita;<br/>Aron way ikapagarbo<br/>Kami gawas Nimo.<br/>',NULL,16214,4);
INSERT INTO stanza VALUES('CB23','4','Sa kaalam, pina’gi’s krus,<br/>Imo ming gitubos;<br/>Aron’s espiritu namo,<br/>Bahandi Ka namo.<br/>',NULL,16215,5);
INSERT INTO stanza VALUES('CB23','5','Ipahibalo’s Iglesia<br/>Sa mga punoan;<br/>Nagkadaiyang kaalam,<br/>Makita’s kalangitan.<br/>',NULL,16216,6);
INSERT INTO stanza VALUES('CB23','6','Unya’s Bag-ong Jerusalem,<br/>Kaluoy m’oy garbo;<br/>Maila gyung kaalam Mo,<br/>Sa kahingpitan gyud.<br/>',NULL,16217,7);
INSERT INTO stanza VALUES('CB24','1','O Dios, kang Cristo gitingub<br/>Kaalam Mo’g grasya,<br/>Gihimong kaalam namo<br/>Igsubay’s gawi Mo.<br/>',NULL,16218,1);
INSERT INTO stanza VALUES('CB24','2','Tanang laraw Mo naa N’ya,<br/>Dalan’s grasya Mo S’ya,<br/>Tanan maangkon diha N’ya,<br/>Ug mahimaya Ka.<br/>',NULL,16219,2);
INSERT INTO stanza VALUES('CB24','3','S’yang pagkamatarung namo,<br/>Kan’ya namatarung;<br/>Siya ang pagkabalaan;<br/>Kan’ya gibalaan.<br/>',NULL,16220,3);
INSERT INTO stanza VALUES('CB24','4','Pagtubos usab S’ya namo,<br/>Sumala’s plano Mo,<br/>Aron hingpit nga matubos,<br/>Magmahingpit nga tawo.<br/>',NULL,16221,4);
INSERT INTO stanza VALUES('CB24','5','O Dios, kaalam Mo Siya,<br/>Sa patigayon Mo,<br/>Alang N’ya daygon Ka namo<br/>Uban’s pagpaubos.<br/>',NULL,16222,5);
INSERT INTO stanza VALUES('CB24','6','Kaalam Kan’ya nakita,<br/>Dato, pagkalalum;<br/>Apan labi pang kaalam<br/>Sa gawi Mo mapalgan.<br/>',NULL,16223,6);
INSERT INTO stanza VALUES('CB25','1','Amahan, gikaloy-an Mo kami,<br/>Pagbuot Mo;<br/>Makasasala gihimong anak,<br/>Gipangga Mo.<br/>Sudlanan’s kaluoyng giandam Mo<br/>Aron magpahayag kami Nimo.<br/>',NULL,16224,1);
INSERT INTO stanza VALUES('CB25','2','Nahimuot Ka sa pagkaluoy,<br/>Dili’s halad;<br/>Tungod ni’ni, nahamut-an kami,<br/>Gikaloy-an;<br/>Di’s nagbuot o sa nidagan ba,<br/>Kondi’ Kanimong naluoy namo.<br/>',NULL,16225,2);
INSERT INTO stanza VALUES('CB25','3','Sa kaluoy Mo among napalgan,<br/>Gugma’g grasya;<br/>Ug nawong sa nawong kami magpabilin,<br/>Nganha Nimo;<br/>Tungod’s kaluoy simbahon Ka namo,<br/>Sa tanang adlaw’g ngadto’s eternidad!<br/>',NULL,16226,3);
INSERT INTO stanza VALUES('CB26','1','Dios, daygon Ka’s kaluoy Mo,<br/>Dako gayud ug lalum!<br/>Sa kahuyang ko’g kapakyas,<br/>Kaluoy naglabi man.<br/>Simbahon Ka kay Imo mang<br/>Gipurongan’s kaluoy.<br/>',NULL,16227,1);
INSERT INTO stanza VALUES('CB26','2','Kaluoy Mo kahibudngan,<br/>Pagkalapad, nidangat<br/>Kanakong makasasala,<br/>Ug nag-amping sa dayon.<br/>Unsay makabulag nako<br/>Gikan ni’ning kaluoy?<br/>',NULL,16228,2);
INSERT INTO stanza VALUES('CB26','3','Salamat sa kaluoy Mo,<br/>Dagaya gyud kaayo!<br/>Sa kaluoy ug pagtubos<br/>Nahamut-an Mo ako.<br/>Kon wala Ka pa maluoy,<br/>Kahamut-an ba kaha?<br/>',NULL,16229,3);
INSERT INTO stanza VALUES('CB26','4','Kaluoy Mo makadasig!<br/>Tam-is, suod, malomo!<br/>Pailub Mo ug kalulot,<br/>Sa kin’hanglan nagtagbo!<br/>Gimahal kong kaluoy Mo,<br/>Way butang makatandi.<br/>',NULL,16230,4);
INSERT INTO stanza VALUES('CB26','5','O Amahan, kaluoy Mo,<br/>Kanunay gayung bag-o,<br/>Matag buntag dinhi nako,<br/>Daw naglunhaw nga yamog.<br/>Kaluoy Mo pagkalami!<br/>Nakatilaw mi’g magdayeg.<br/>',NULL,16231,5);
INSERT INTO stanza VALUES('CB26','6','Makahunong ba’s pagdayeg?<br/>Kaluoy hangtud’s dayon!<br/>Grasya Mo ug pag-atiman,<br/>Sa kaluoy naangkon.<br/>Saligan ang kaluoy Mo,<br/>Kasegurohan namo.<br/>',NULL,16232,6);
INSERT INTO stanza VALUES('CB27','1','Maghiusa ta’s pag-awit,<br/>Dios gugma, Dios gugma,<br/>Langit ug yuta padayga,<br/>Dios gugma, Dios gugma.<br/>Pagmata na gikan’s sala,<br/>Kasingkasing paawita,<br/>Duyog na kay awiton ta,<br/>Dios gugma! Dios gugma!<br/>',NULL,16233,1);
INSERT INTO stanza VALUES('CB27','2','Kalipay niang pahat ta!<br/>Dios gugma, Dios gugma,<br/>Makalipay ang saad N’ya,<br/>Dios gugma, Dios gugma.<br/>Adlaw S’ya ug taming nato,<br/>Tabang, paglaum ug kusog;<br/>Uban nato’s tanang adlaw,<br/>Dios gugma! Dios gugma!<br/>',NULL,16234,2);
INSERT INTO stanza VALUES('CB27','3','Sa himaya awiton ta,<br/>Dios gugma, Dios gugma,<br/>Habog kini nga sonata,<br/>Dios gugma, Dios gugma.<br/>Mag-awit ta hangtud’s dayon,<br/>Uban sa langitnong panon,<br/>Labing matam-is awiton,<br/>Dios gugma! Dios gugma!<br/>',NULL,16235,3);
INSERT INTO stanza VALUES('CB28','1','Gugma sa Dios labaw pa sa<br/>Giasoy ug gisulat na;<br/>Habog pa’s kabitoonan,<br/>Lalum pa’s kinalaluman.<br/>Nabalakang duhang sad-an,<br/>Dios, sa Anak nagluwas,<br/>Gipauling nakasala,<br/>Gipasaylo’s sala.<br/>',NULL,16236,1);
INSERT INTO stanza VALUES('CB28','chorus','Gugma sa Dios dato’g putli!<br/>Di masukod, lig-on!<br/>Molahutay pa sa awit<br/>Sa mga balaan.<br/>',NULL,16237,2);
INSERT INTO stanza VALUES('CB28','2','Sa paglabay sa panahon,<br/>Gingharian mangapukan;<br/>Mga tawong di moampo,<br/>Magpatabon’s kapangpangan;<br/>Gugma sa Dios magpadayon<br/>Sa tanang panahon;<br/>Grasya N’ya alang sa tanang<br/>Kaliwat ni Adam.<br/>',NULL,16238,3);
INSERT INTO stanza VALUES('CB28','3','Dagat mapuno ba’s tinta,<br/>Kalangitan ma-papel ba;<br/>Ma-dagang ang tanang tukog,<br/>Matag tawo magsusulat;<br/>Gugma sa Dios kon isulat,<br/>Mamad-an gyung dagat;<br/>Langit di gyud magpaigo,<br/>Bisag inaton nato.<br/>',NULL,16239,4);
INSERT INTO stanza VALUES('CB29','1','O Dios, ang Anak Mo,<br/>Nganong gihatag Mo?<br/>Pinalanggang Anak<br/>Kanamo namatay?<br/>Way lain, gugma’y naingnan,<br/>Nga hatagan’s bugtong mahal.<br/>',NULL,16240,1);
INSERT INTO stanza VALUES('CB29','2','Nganong nibiya man,<br/>Anak Mo sa trono?<br/>Giula ang dugo,<br/>Nag-antus, namatay?<br/>Way lain, gugma’y naingnan,<br/>Nga kami ’yang pakamatyan.<br/>',NULL,16241,2);
INSERT INTO stanza VALUES('CB29','3','Nganong gipaambit,<br/>Sa Espiritu Mo,<br/>Kasingkasing pun-on’s<br/>Gugma ug kalinaw?<br/>Way lain, gugma’y naingnan,<br/>Nagtandog kami hatagan.<br/>',NULL,16242,3);
INSERT INTO stanza VALUES('CB29','4','O Dios sa grasya Mo,<br/>Gugma ihalad ko!<br/>Mag-awas ang kalag,<br/>Way undang nga pagdayeg.<br/>Alang niining gugma Mo,<br/>Padaygon Mo kami’s dayon.<br/>',NULL,16243,4);
INSERT INTO stanza VALUES('CB30','1','O unsang gugma gihatag,<br/>Magpasalamat mi;<br/>Sa pagkamao Mo kami<br/>Magsimba’g magdayeg!<br/>',NULL,16244,1);
INSERT INTO stanza VALUES('CB30','2','Kabubut-on gibugna Mo<br/>Nganhi gayud namo;<br/>Nga nianhi Ka sa Anak,<br/>Nagtuman sa tuyo.<br/>',NULL,16245,2);
INSERT INTO stanza VALUES('CB30','3','Pinanggang Anak gihatag,<br/>Nianhi’g namatay,<br/>Gihimo ming daghang anak,<br/>Uban N’yang manunod.<br/>',NULL,16246,3);
INSERT INTO stanza VALUES('CB30','4','Kinabuhi Mo naangkon,<br/>Amahan Ka namo;<br/>Kinaiya’g pagkamao,<br/>Naambitan namo.<br/>',NULL,16247,4);
INSERT INTO stanza VALUES('CB30','5','Nisulod Ka’s espiritu,<br/>Nisangpit “Amahan,“<br/>Gianak sa Espiritu,<br/>Transpormahon Nimo.<br/>',NULL,16248,5);
INSERT INTO stanza VALUES('CB30','6','Daghang anak maoy tumong,<br/>Sa himaya dad-on;<br/>Sa dagway’s Anak umolon,<br/>Hingpit nga samahon.<br/>',NULL,16249,6);
INSERT INTO stanza VALUES('CB30','7','Tultolan Mo matag usa,<br/>Aron matransporma;<br/>Himaya ngadto’s himaya,<br/>Kanimo masama.<br/>',NULL,16250,7);
INSERT INTO stanza VALUES('CB30','8','Unsang gugma gihatag Mo,<br/>Salamat Amahan;<br/>Simbahon Ka hangtud’s dayon,<br/>Pagdayeg way hunong.<br/>',NULL,16251,8);
INSERT INTO stanza VALUES('CB32','1','O Amahan simbahon Ka,<br/>Sa kahibudngan Mong gugma;<br/>Unsa kami nga hatagan,<br/>Sa grasya nga hilabihan!<br/>',NULL,16252,1);
INSERT INTO stanza VALUES('CB32','2','Sa tinguha Mo, daygon Ka,<br/>Kami sa dagway masama;<br/>Pun-on mi’s kinabuhi Mo,<br/>Aron magpadayag Nimo.<br/>',NULL,16253,2);
INSERT INTO stanza VALUES('CB32','3','Gibuhat mi sa dagway Mo,<br/>Sa kagahum gihatagan;<br/>Kaugalingon Mo gitanyag,<br/>Nga makinabuhi namo.<br/>',NULL,16254,3);
INSERT INTO stanza VALUES('CB32','4','Tinguha Mong masagol’s tawo,<br/>Pinaagi sa grasya Mo;<br/>Transpormahon mi’g tukoron,<br/>Nga puy-anan Mong halangdon.<br/>',NULL,16255,4);
INSERT INTO stanza VALUES('CB32','5','Bisag napakyas wa b’yai,<br/>Gitubos ug gibawi mi;<br/>Sa gugma’g kaalam Ikaw<br/>Namatud-an nga way labaw.<br/>',NULL,16256,5);
INSERT INTO stanza VALUES('CB32','6','Gibugna Mong Kaugalingon,<br/>Dihang Cristo nga nagtubos;<br/>Sa Espiritu nisulod’s tawo,<br/>Ug sa grasya gidad-an Mo.<br/>',NULL,16257,6);
INSERT INTO stanza VALUES('CB32','7','Labing balaan nga dapit,<br/>Espiritu trono’s grasya;<br/>Duolon Ka’s espiritu,<br/>Didto magsunog’s incienso.<br/>',NULL,16258,7);
INSERT INTO stanza VALUES('CB32','8','Grasya nagbaha daw suba,<br/>Gikan sa trono sa grasya;<br/>Niagay, nag-usab namo,<br/>Tukoron mi nga balay Mo.<br/>',NULL,16259,8);
INSERT INTO stanza VALUES('CB32','9','Di katupngan ang grasya Mo,<br/>Kay way bayad, natingala,<br/>Salamat sa dakong gugma,<br/>Sa espiritu magsimba!<br/>',NULL,16260,9);
INSERT INTO stanza VALUES('CB33','1','O Dios, gipili Mo kami<br/>Sa wa pang kabuhatan;<br/>Gugmang matam-is nagdani<br/>Kang Cristo moduol mi.<br/>Ampingan Mo, ampingan Mo,<br/>Magpabilin ni Cristo,<br/>Magpabilin ni Cristo.<br/>',NULL,16261,1);
INSERT INTO stanza VALUES('CB33','2','Bisan tanan mangabalhin,<br/>Apan Dios way pag-usab;<br/>Kaluoy N’ya’g pakigsaad<br/>Magpabilin’s gihapon.<br/>Mga anak, mga anak,<br/>Daygon ta ang ngalan N’ya,<br/>Daygon ta ang ngalan N’ya.<br/>',NULL,16262,2);
INSERT INTO stanza VALUES('CB33','3','Kaluoy’s Dios isugilon,<br/>Ipagarbo ko’s dayon;<br/>Libreng kaluoy way hunong,<br/>Nagtandog Ikaw sundon.<br/>Gimahal Mo, gimahal Mo,<br/>Bisan Anak gihatag,<br/>Bisan Anak gihatag.<br/>',NULL,16263,3);
INSERT INTO stanza VALUES('CB33','4','Amahang mahigugmaon,<br/>Gugma Mo among daygon;<br/>Mag-awit mi’s way paghunong<br/>Hangtud Anak makita,<br/>Himayaon, himayaon,<br/>Ang Dios ug ang Cordero,<br/>Ang Dios ug ang Cordero.<br/>',NULL,16264,4);
INSERT INTO stanza VALUES('CB36','1','Daygon Ikaw, Amahan,<br/>Tumong mi’s grasya Mo;<br/>Alang’s Imong kalipay,<br/>Nia’s presensya Mo.<br/>Gitiman-an Mong daan<br/>Nga alang’s himaya,<br/>Mag-uban mi ni Cristo,<br/>Nga Pinalangga Mo.<br/>',NULL,16265,1);
INSERT INTO stanza VALUES('CB36','2','Ikaw ra, O Amahan<br/>Makatuga namo<br/>Diha sa Imong Anak<br/>Sa Espiritu Mo;<br/>Imo na mi’g mag-uban<br/>Ni Cristo’s himaya,<br/>Magsidlak’s dagway Niya,<br/>Hangtud’s dayon, Amen!<br/>',NULL,16266,2);
INSERT INTO stanza VALUES('CB39','1','Himayaon ang Dios sa ’yang nabuhat,<br/>Sa gugma gihatagan ta’s Anak N’ya;<br/>Nagtugyan’s kinabuhi N’ya’s pagtubos,<br/>Aron’s kinabuhi makasulod ta.<br/>',NULL,16267,1);
INSERT INTO stanza VALUES('CB39','chorus','Daygon S’ya, daygon S’ya<br/>Sa tibuok yuta,<br/>Magdayeg, maglipay<br/>Ang tanang katawhan;<br/>Ihatag Kaniya tanang himaya,<br/>Tungod sa buhat nga Iyang nahuman.<br/>',NULL,16268,2);
INSERT INTO stanza VALUES('CB39','2','Hingpit nga pagtubos, gipalit’s dugo,<br/>Sa tanang nitoo gisaad sa Dios;<br/>Labing dautang motoo gyud Niya,<br/>Mapasaylo niana gyung tungora.<br/>',NULL,16269,3);
INSERT INTO stanza VALUES('CB39','3','Gitudloan’s butang nga nahuman N’ya,<br/>Ug dakong pagkalipay namong Jesus;<br/>Apan mas putli, habog, ug dako pa,<br/>Kahibu’ong, kalipay, kon igkita S’ya.<br/>',NULL,16270,4);
INSERT INTO stanza VALUES('CB40','1','Daygon Ka, O Dios,<br/>Sa Anak Mo’s gugma,<br/>Manluluwas namatay,<br/>Ug nikayab na.<br/>',NULL,16271,1);
INSERT INTO stanza VALUES('CB40','chorus','Hallelujah! Himayaon,<br/>Hallelujah! Amen;<br/>Hallelujah! Himayaon,<br/>Amo Kang daygon!<br/>',NULL,16272,2);
INSERT INTO stanza VALUES('CB40','2','Daygon Ka, O Dios,<br/>Sa Espiritu Mo,<br/>Nagpakita’s Manlul’was,<br/>Kangitngit nagpaylas.<br/>',NULL,16273,3);
INSERT INTO stanza VALUES('CB40','3','Tingban’s himaya<br/>Amahan sa gugma,<br/>Sa katubsanang Jesus,<br/>Gugma nasuta.<br/>',NULL,16274,4);
INSERT INTO stanza VALUES('CB40','4','Daygon pag-usab,<br/>Napuno mi’s gugma,<br/>Nagdilaab ang gugma<br/>Sa matag usa.<br/>',NULL,16275,5);
INSERT INTO stanza VALUES('CB41','1','Di mi laayon moawit ning alawiton:<br/>Daygon ang Dios, hallelujah!<br/>Kusgon ta pag-awit ang pagdayeg Kaniya:<br/>Daygon ang Dios, hallelujah!<br/>',NULL,16276,1);
INSERT INTO stanza VALUES('CB41','chorus','Ang mga anak sa Dios may matahum nga awit<br/>Pinaagi sa grasya dad-on ta N’ya’s himaya.<br/>Mangadto unya kita’s presensya’s atong Hari:<br/>Daygon ang Dios, hallelujah!<br/>',NULL,16277,2);
INSERT INTO stanza VALUES('CB41','2','Naa ta’s kalipay sa gugma nga nagtubos:<br/>Daygon ang Dios, hallelujah!<br/>Tanang panahon bu’t pamatud-an ’yang grasya:<br/>Daygon ang Dios, hallelujah!<br/>',NULL,16278,3);
INSERT INTO stanza VALUES('CB41','3','Mangadto ta’s himaya, matud pa’s Ginoo:<br/>Daygon ang Dios, hallelujah!<br/>Didto ang katahum sa Hari ta makita:<br/>Daygon ang Dios, hallelujah!<br/>',NULL,16279,4);
INSERT INTO stanza VALUES('CB41','4','Mag-awit’s grasya’g kaluoy sa bag-ong awit:<br/>Daygon ang Dios, hallelujah!<br/>Uban’s bulahang panon Manlul’was ta daygon:<br/>Daygon ang Dios, hallelujah!<br/>',NULL,16280,5);
INSERT INTO stanza VALUES('CB42','1','Gidapit Nimo, O Dios,<br/>Motan-aw ming Jesus,<br/>S’ya ang gikahimut-an,<br/>Kanimo nagtuman;<br/>Ang labi gyud nga mahal,<br/>Imo nga gihatag,<br/>Gugma napamatud-an,<br/>Putli ug moluwas!<br/>',NULL,16281,1);
INSERT INTO stanza VALUES('CB42','2','Amahan sa kaluoy,<br/>Sa ngalan ni Cristo,<br/>Kami karon nagtigum,<br/>Ug dunay paglaum;<br/>Tam-is alang Kanimo,<br/>Ang ngalan ni Cristo,<br/>Nag’gawas’ among kalag,<br/>Sa tanang pagtuto!<br/>',NULL,16282,2);
INSERT INTO stanza VALUES('CB42','3','Ang sad-an mahadlok gyud<br/>Dios di makalimot;<br/>Apan kas-ang pagbayad<br/>Utang ’yang gipapas;<br/>Walay makapagawas<br/>Sa amo nga kalag,<br/>Namatay Anak sa Dios,<br/>Ug kami giluwas!<br/>',NULL,16283,3);
INSERT INTO stanza VALUES('CB42','4','Ang Dios wa nay kasuko<br/>Kanatong nitoo;<br/>Kita wa nay kahadlok,<br/>Kay gugma nadawat.<br/>Nipauli gihagkan,<br/>Iyang gibistehan,<br/>Gugmang hingpit nagwala’s<br/>Tanang kalisang ta.<br/>',NULL,16284,4);
INSERT INTO stanza VALUES('CB45','1','Abba Amahan, daygon Ka,<br/>Maubsanong magsimba;<br/>Bulahan kay naila Ka,<br/>Anak ray maka-“Abba.“<br/>Napanunod ning katungod,<br/>Tungod’s dugo ni Jesus,<br/>Espiritu nagpamatuod,<br/>Mga anak mi sa Dios.<br/>',NULL,16285,1);
INSERT INTO stanza VALUES('CB45','2','Nia mi tungod’s tuyo Mo,<br/>Dihang Cristo ug plano,<br/>Gipili nga makatawhan,<br/>Sa wa pang kalibutan.<br/>Unsang gugma, O Amahan,<br/>Nga kami gimahal man!<br/>Sa Anak kami gihatag,<br/>Kalipay’s Imong kalag.<br/>',NULL,16286,2);
INSERT INTO stanza VALUES('CB45','3','Hulog kami dihang Adam,<br/>Bug-os nawad-an sa Dios,<br/>Gidala’s dayong tuyo Mo,<br/>Maduol’s dugong Jesus.<br/>Kay Kaniya may pagtubos,<br/>May grasya ug himaya;<br/>Pagkalalum sa kaluoy!<br/>Nausa Siya namo.<br/>',NULL,16287,3);
INSERT INTO stanza VALUES('CB45','4','Busa sa tanang panahon,<br/>Sa kalisud, kaguol;<br/>Way makausab’s gugma Mo,<br/>Ampingan gyud mi Nimo.<br/>Di madugay mga anak<br/>Mag-alirong’s trono Mo,<br/>Sa kaluwasan mag-awit,<br/>Ang pagdayeg isinggit.<br/>',NULL,16288,4);
INSERT INTO stanza VALUES('CB47','1','Amahan, ngalan Mo daygon,<br/>Tinudloan’s grasya;<br/>Kasingkasing nga matarung,<br/>Maglipay mi’s presensya.<br/>',NULL,16289,1);
INSERT INTO stanza VALUES('CB47','2','Hatag nga pasalig tam-is,<br/>Labaw’s among pagdayeg;<br/>Kasingkasing atoa na,<br/>Kanimo sa langit.<br/>',NULL,16290,2);
INSERT INTO stanza VALUES('CB47','3','Eternidad magpahayag,<br/>Grasya Mo dagaya;<br/>Ang makaambit sa Anak,<br/>May luna’s Anak didto.<br/>',NULL,16291,3);
INSERT INTO stanza VALUES('CB47','4','Nagpaabot ug naglaum,<br/>Imo ming lalinon;<br/>Aron di na maabot pa,<br/>Gahum’s kamatayon!<br/>',NULL,16292,4);
INSERT INTO stanza VALUES('CB47','5','Nalipay kay kahupnganan,<br/>Pahat namo’s dayon,<br/>Sama’s Anak nga papuy-on<br/>Didto’s eternidad.<br/>',NULL,16293,5);
INSERT INTO stanza VALUES('CB47','6','O Amahan, ampingi mi,<br/>Sa ngalan sa gugma;<br/>Sa presensya way kataha,<br/>Kabubut-on masuta.<br/>',NULL,16294,6);
INSERT INTO stanza VALUES('CB48','1','Dios Amahan, daygon Ka,<br/>Kamatayon wa na;<br/>Nalipayng nakaambit<br/>Sa dapit sa Anak!<br/>Nagkinabuhi S’yang Tawo,<br/>Sa atubangan Mo;<br/>Gihigugma pag-ayo,<br/>Sa way katapusan!<br/>',NULL,16295,1);
INSERT INTO stanza VALUES('CB48','2','Dios ug Amahan Niya,<br/>Among Dios Amahan;<br/>Imo S’yang Pinalangga,<br/>Kalipay sa dughan.<br/>Gidala ming Iyaha,<br/>Moambit’s pahat N’ya,<br/>Masayud sa gugma Mo,<br/>Pahiyom’s nawong Mo.<br/>',NULL,16296,2);
INSERT INTO stanza VALUES('CB48','3','Gugmang nigakos namo,<br/>Wala gyuy paglubad;<br/>Natingob diha’s Anak,<br/>Naapil mi Niya.<br/>Gugma ug himaya Mo,<br/>Anaa Kaniya;<br/>Ang daghan Mo nga anak,<br/>Kan’ya nabulahan!<br/>',NULL,16297,3);
INSERT INTO stanza VALUES('CB50','1','Amahan, Anak Mo m’oy nanguna,<br/>Human’s pagkaon ni’ning kombira;<br/>Tam-is nga mga pagdayeg Nimo,<br/>Duyog Kaniya kami nausa.<br/>',NULL,16298,1);
INSERT INTO stanza VALUES('CB50','2','Way kaayohan mi gawas Nimo,<br/>Imohang gugma ray gipangita;<br/>Di matugkad nga kinabuhi Mo,<br/>Simbahon Ka kay karon nasayran!<br/>',NULL,16299,2);
INSERT INTO stanza VALUES('CB50','3','Sa gugma Mo paghigugma namo<br/>Magtubo, molabaw’s gugma’s yuta;<br/>Gugma Mo magbuot’s kasingkasing,<br/>Matagbaw gyud mi sa presensya Mo.<br/>',NULL,16300,3);
INSERT INTO stanza VALUES('CB50','4','Duyog sa Anak nga pinalangga,<br/>Malipayong magdayeg pag-usab;<br/>Magkombira’s balaan Mong gugma,<br/>Sa ngalang tam-is kami magpista.<br/>',NULL,16301,4);
INSERT INTO stanza VALUES('CB51','1','Dios Amahan nisanong mi Nimo,<br/>Mga anak;<br/>Gihimong takus ug gipagawas,<br/>Makaduol;<br/>Nindot hunahunaong daghan mi,<br/>Samang Cristo himo’ng kalipay Mo!<br/>',NULL,16302,1);
INSERT INTO stanza VALUES('CB51','2','Diha Niya kami nakaambit<br/>Sa grasya Mo;<br/>Way butang nga gihigugma Nimo,<br/>Labaw Niya;<br/>Makitang gloria N’ya’s presensya Mo,<br/>Uban ming magpa’mulos’ gugma Mo!<br/>',NULL,16303,2);
INSERT INTO stanza VALUES('CB51','3','Kalipay Niya dinhi mag-awit,<br/>Pagdayeg Nimo;<br/>Matandog mga anak mag-awit,<br/>Usang tingog;<br/>Sa pagsimba Kanimo, Amahan,<br/>Nga tinubdan ug labaw sa tanan!<br/>',NULL,16304,3);
INSERT INTO stanza VALUES('CB52','1','Amahan malipayong awitan<br/>Namong tanan;<br/>Sa presensya Mo kami magdayeg,<br/>Kanimo ra;<br/>Gipapauli, O unsang grasya!<br/>Karon sama nag dapit’s Anak Mo.<br/>',NULL,16305,1);
INSERT INTO stanza VALUES('CB52','2','Sa dapit nga gugma Mo nasayran,<br/>O kalipay!<br/>Diha ra Niya nakita namo<br/>Ang gugma Mo;<br/>Sa kaugalingon Mong pahulay,<br/>S’ya nanguna namo sa pagdayeg!<br/>',NULL,16306,2);
INSERT INTO stanza VALUES('CB52','3','Pagkatahum sa igdulongog Mo<br/>Ang awit N’ya!<br/>Bililhon sab ang gida’ N’ya didto,<br/>Pagkamahal;<br/>Sama mi N’ya’g dapit m’oy plano Mo,<br/>Gimahal sa wa pang kalibutan!<br/>',NULL,16307,3);
INSERT INTO stanza VALUES('CB53','1','Daygong Ngalan Mo’s gugmang gibugna<br/>Kang Cristo nga nagtuman’s buot Mo.<br/>Sa kalipayng makita’s unahan,<br/>Giantus ang krus ug kaulawan.<br/>',NULL,16308,1);
INSERT INTO stanza VALUES('CB53','2','Taliwala sa kaigsoonan,<br/>Awit Niya amo nga duyogan;<br/>Bisan karon kon Siya motingog,<br/>Daygon’s espiritu ug moduyog.<br/>',NULL,16309,2);
INSERT INTO stanza VALUES('CB53','3','Gipili mi diha’s Pinalangga,<br/>May bahin’s kalipay’s presensya Mo;<br/>Gitudlo mi’s wa pang kalibutan<br/>Adto’s dapit nga puno’s grasya Mo.<br/>',NULL,16310,3);
INSERT INTO stanza VALUES('CB53','4','Mga anak gimahal, nagmahal,<br/>Sa Espiritu pun-on mi’g Cristo;<br/>Matag usa magpadayag Niya,<br/>Alang’s kalipay Mo hangtud’s dayon.<br/>',NULL,16311,4);
INSERT INTO stanza VALUES('CB56','1','Ginoo, Pulong Ka sa Dios,<br/>Anak mismo sa Dios;<br/>Dagway Niya nga tinuod,<br/>Usa Kaniya gyud.<br/>',NULL,16312,1);
INSERT INTO stanza VALUES('CB56','2','Ikaw mismo mao ang Dios,<br/>Pagkalawas Niya;<br/>Diha Nimo Dios nadayag,<br/>Ug among nakita.<br/>',NULL,16313,2);
INSERT INTO stanza VALUES('CB56','3','Kasanag Ka’s himaya’s Dios,<br/>Nagdan-ag Ka namo;<br/>Pagpadayag’s pagkamao,<br/>Sa Dios nagmatuod.<br/>',NULL,16314,3);
INSERT INTO stanza VALUES('CB56','4','Dios kahayag diha Nimo,<br/>Kinabuhi namo;<br/>Naambitang kinaiya,<br/>Kaniya nausa.<br/>',NULL,16315,4);
INSERT INTO stanza VALUES('CB56','5','Grasya sa Dios diha Nimo,<br/>Napa’muslan namo;<br/>Kamatuoran napalgan,<br/>Diha Nimong tanan.<br/>',NULL,16316,5);
INSERT INTO stanza VALUES('CB56','6','Kahupnganan’s Dios nadawat,<br/>Grasya ngadto’s grasya;<br/>Diha Nimo nasagol’s Dios,<br/>Mausa na’s bug-os.<br/>',NULL,16317,6);
INSERT INTO stanza VALUES('CB56','7','Ginoong Dios, simbahon Ka,<br/>Ikaw among tanan;<br/>Ikaw ang gimahal namo,<br/>Tawgon Imong Ngalan.<br/>',NULL,16318,7);
INSERT INTO stanza VALUES('CB58','1','Buhing Pulong Ka, Ginoo,<br/>Uban gayud sa Dios;<br/>Himaya N’ya gipakita,<br/>Samtang dinhi’s yuta.<br/>',NULL,16319,1);
INSERT INTO stanza VALUES('CB58','chorus','O buhing Pulong, daygon Ka,<br/>Ang Dios Kanimo makita;<br/>Himaya’g kinaiya N’ya,<br/>Gipadayag Nimo.<br/>',NULL,16320,2);
INSERT INTO stanza VALUES('CB58','2','Gipakita’s kabuhatan<br/>Himaya’s Dios tanan;<br/>Mga butang’s Dios nasayran,<br/>Gahum, kina’yahan.<br/>',NULL,16321,3);
INSERT INTO stanza VALUES('CB58','3','Pulong sa Dios, dato, lalum,<br/>Nagpanghimatuod;<br/>Gisaysay Ka ni’ning Pulong,<br/>Aron Dios maila.<br/>',NULL,16322,4);
INSERT INTO stanza VALUES('CB58','4','Pulong, nahimo Kang unod,<br/>Nakig-uban sa tawo;<br/>Paggawi ug pamulong Mo,<br/>Sa Dios nagpadayag.<br/>',NULL,16323,5);
INSERT INTO stanza VALUES('CB58','5','Pulong, Ikaw kinabuhi,<br/>Ug buhing kahayag;<br/>Kami Imong gihayagan,<br/>Makitang Amahan.<br/>',NULL,16324,6);
INSERT INTO stanza VALUES('CB58','6','Gipaila Mo’s paghukom<br/>Nga ang Dios matarung;<br/>Nagpadayag sab sa bug-os<br/>Sa pagkamao’s Dios.<br/>',NULL,16325,7);
INSERT INTO stanza VALUES('CB58','7','Hingpit Ikawng pagpadayag’s<br/>Kaugalingon sa Dios;<br/>Tanan Niyang pagkamao,<br/>Gipadayag Mo’s tawo.<br/>',NULL,16326,8);
INSERT INTO stanza VALUES('CB61','1','O Ginoo, Anak Ka’s tawo,<br/>Gisul-ob kina’ya namo;<br/>Gianak Ka’s ulayng babaye;<br/>Sa dugo’g unod niambit.<br/>',NULL,16327,1);
INSERT INTO stanza VALUES('CB61','2','Sa dagway’s ulipong ubos,<br/>Nabuhi’s yutang alaut;<br/>Nag-agi’s tanang pag-antus,<br/>Pagkinabuhi gyud sa tawo.<br/>',NULL,16328,2);
INSERT INTO stanza VALUES('CB61','3','Sa pasungan natawo Ka,<br/>Nagdako diha’s kakabus;<br/>Namanday aron mabuhi,<br/>Sa kamatayon nag-antus.<br/>',NULL,16329,3);
INSERT INTO stanza VALUES('CB61','4','Gibanhaw Ka’s mga patay,<br/>Dalang kinaiya sa tawo;<br/>Tawong suot ang diosnong dagway,<br/>Nikayab sab Ka sa langit.<br/>',NULL,16330,4);
INSERT INTO stanza VALUES('CB61','5','Karon labaw’s tanan’s trono,<br/>Tawo gihapong gihimaya;<br/>Tawong na’s Dios diha’s kahayag,<br/>Dios Kaniya natagbaw gyud!<br/>',NULL,16331,5);
INSERT INTO stanza VALUES('CB61','6','Sa himaya mobalik Ka,<br/>Tawo gihapong magpakita;<br/>Hari sa mga hari Ka,<br/>Gamhanan apan tawhanon.<br/>',NULL,16332,6);
INSERT INTO stanza VALUES('CB61','7','Ikawng sentro’s tanang butang,<br/>Unya’s bag-ong langit, yuta;<br/>Ikaw’s walay katapusan,<br/>Magpabiling may pagka-tawo.<br/>',NULL,16333,7);
INSERT INTO stanza VALUES('CB62','1','Ginoong Jesus, nahimo Kang<br/>“Kaliwat’s babaye,“<br/>Gianak’s ulay, ginganlan<br/>Ngani sa ngalan sa tawo.<br/>Gisul-ob Mong kina’ya’s tawo,<br/>Yawa tunobtunoban;<br/>Sa Krus ulo n’ya gisamdan<br/>Sa plano’s Dios nagtuman.<br/>',NULL,16334,1);
INSERT INTO stanza VALUES('CB62','chorus','Himaya nakita’s<br/>Tawhanong katahum,<br/>Pagka-tawo Mo, Ginoo<br/>Pagkahalangdon.<br/>',NULL,16335,2);
INSERT INTO stanza VALUES('CB62','2','Isip tawo, sa pagpakatawo<br/>Unod, dugo gisul-ob;<br/>Aron Satanas laglagon,<br/>Puli ug alang namo.<br/>Jesus Ikaw nga ginganlan,<br/>Emmanuel sab nailhan;<br/>Nahimong among Manlul’was,<br/>Nga kanamo nagluwas.<br/>',NULL,16336,3);
INSERT INTO stanza VALUES('CB62','3','Ikawng “Katapusang Adam,“<br/>“Ikaduha nga tawo,“<br/>Ulo’s bag-ong kabuhatan,<br/>Labaw pa’s unang tawo.<br/>Pagkinabuhi ug gawi<br/>Anak gayud sa tawo;<br/>Karon bisan naa’s langit<br/>Dagway gihapon sa tawo.<br/>',NULL,16337,4);
INSERT INTO stanza VALUES('CB62','4','Sa panahong gitudlo’s Dios<br/>Mobalik Ka, Ginoo,<br/>Dunay himaya’s Amahan<br/>Dagway gihapon sa tawo.<br/>Bisan sa trono’s paghukom<br/>Anak sa tawo gihapon<br/>Ug magpabiling tawhanon<br/>Hangtud gayud sa dayon.<br/>',NULL,16338,5);
INSERT INTO stanza VALUES('CB65','1','Jesus! ang ngalan Mo<br/>Gimahal ko,<br/>Jesus, ang ngalan nga<br/>Di hilabwan!<br/>Ikaw akong tanan,<br/>Wa koy kaayohan<br/>Gawas lang Kanimo,<br/>Ginoo ko!<br/>',NULL,16339,1);
INSERT INTO stanza VALUES('CB65','2','Nahimo Kang Tawo,<br/>Ginoo ko;<br/>Namatay Ka sa krus<br/>Alang nako!<br/>Gugma Mo nilabaw’s<br/>Gugma’s mga tawo,<br/>Gugma namatud-an<br/>Tungod Nimo!<br/>',NULL,16340,2);
INSERT INTO stanza VALUES('CB65','3','Namatarung ako<br/>Diha Nimo,<br/>Ikaw dalangpanan,<br/>Ginoo ko!<br/>Na’ bay kahadlokan?<br/>Kalisdan? Kagul-an?<br/>Kay Ikaw duol man,<br/>Ginoo ko!<br/>',NULL,16341,3);
INSERT INTO stanza VALUES('CB65','4','Ikaw mobalik man,<br/>Di madugay,<br/>Kami magkalipay<br/>Uban Nimo!<br/>Kon igkita Ka na,<br/>Kanimo masama,<br/>Ug makauban pa<br/>Hangtud’s dayon!<br/>',NULL,16342,4);
INSERT INTO stanza VALUES('CB66','1','Pagkatam-is paminawon<br/>Ang Ngalan ni Jesus!<br/>Makahupay sa kasubo,<br/>Sa sakit mag-ayo.<br/>Kahadlok gikuha,<br/>Kahadlok gikuha,<br/>Makahupay sa kasubo,<br/>Sa sakit mag-ayo.<br/>',NULL,16343,1);
INSERT INTO stanza VALUES('CB66','2','Nag-ayo sa espiritu,<br/>Kalinaw sa dughan;<br/>Manna Siya sa gigutom,<br/>Pahulay’s gikapoy,<br/>Pahulay’s gikapoy,<br/>Pahulay’s gikapoy,<br/>Manna Siya sa gigutom,<br/>Pahulay’s gikapoy.<br/>',NULL,16344,2);
INSERT INTO stanza VALUES('CB66','3','Ngalan, Batong gitukoran,<br/>Taming ug tagoanan;<br/>Di makabsang tipiganan,<br/>Dagaya sa grasya.<br/>Dagaya sa grasya,<br/>Dagaya sa grasya,<br/>Di makabsang tipiganan,<br/>Dagaya sa grasya.<br/>',NULL,16345,3);
INSERT INTO stanza VALUES('CB66','4','Manluluwas, Magbalantay,<br/>Abyan, Propeta’g Hari,<br/>Ginoo, kinabuhi ta,<br/>Dalan, atong tumong.<br/>Dalan, atong tumong,<br/>Dalan, atong tumong,<br/>Ginoo, kinabuhi ta,<br/>Dalan, atong tumong.<br/>',NULL,16346,4);
INSERT INTO stanza VALUES('CB66','5','Bisan maluya ug mabugnaw<br/>Kami Kanimo;<br/>Apan kon makita Ka na,<br/>Madasig ming magdayeg.<br/>Madasig ming magdayeg,<br/>Madasig ming magdayeg,<br/>Apan kon makita Ka na,<br/>Madasig ming magdayeg.<br/>',NULL,16347,5);
INSERT INTO stanza VALUES('CB66','6','Imantala ang gugma Mo<br/>Sa matag ginhawa;<br/>Sa Ngalan magmadaugon,<br/>Kamatayon dag-on.<br/>Kamatayon dag-on,<br/>Kamatayon dag-on,<br/>Sa ngalan magmadaugon,<br/>Kamatayon dag-on.<br/>',NULL,16348,6);
INSERT INTO stanza VALUES('CB67','1','Ngalang Jesus pagkatam-is!<br/>Buot kong sublio’g awit;<br/>Sa kalipay ko naghingpit,<br/>Bililhong ngalang Jesus.<br/>',NULL,16349,1);
INSERT INTO stanza VALUES('CB67','chorus','Jesus! O, pagkatam-is,<br/>Jesus! way pagkabalhin,<br/>Jesus! isangyaw gayud<br/>Takus daygon sa dayon.<br/>',NULL,16350,2);
INSERT INTO stanza VALUES('CB67','2','Gihigugma kong ngalan N’ya,<br/>Sa kaguol ko nasayud;<br/>Kahadlok ko gikuha N’ya,<br/>Mahal kong ngalang Jesus.<br/>',NULL,16351,3);
INSERT INTO stanza VALUES('CB67','3','Ngalang ganahang madungog,<br/>Sa kasingkasing naglipay;<br/>Musika kini’s nagsubo,<br/>Ituboyng ngalang Jesus.<br/>',NULL,16352,4);
INSERT INTO stanza VALUES('CB67','4','Walay pulong makaasoy<br/>Sa katam-is sa ngalan N’ya;<br/>O, isinggit ang pagdayeg!<br/>Daygon ang ngalang Jesus.<br/>',NULL,16353,5);
INSERT INTO stanza VALUES('CB68','1','“Jesus” Kanimo gingalan<br/>Ngalan nga katingad-an;<br/>Ulay ang nag-anak Nimo,<br/>Aron ma-Anak sa Tawo.<br/>Si Jehova-Manlul’was Ka,<br/>Nagluwas namo’s sala;<br/>Sa pagdawat namo Nimo,<br/>Kinabuhi naamo.<br/>',NULL,16354,1);
INSERT INTO stanza VALUES('CB68','2','Ginganlan Ikaw ug “Cristo,“<br/>Tungod’s pangalagad Mo;<br/>Tinuod dinihog Ka’s Dios,<br/>Bisan pa’s eternidad.<br/>Ikaw ang Mesias sa Dios,<br/>Sa gugma N’ya gitudlo;<br/>Nagpadayag’s himaya’s Dios,<br/>Nagtuman sa ’yang tuyo.<br/>',NULL,16355,2);
INSERT INTO stanza VALUES('CB68','3','Ginganlan Ka ug “Emmanuel,“<br/>Dios sa tawo mag-uban;<br/>Sa grasya Dios masagol gyud,<br/>Sa among pagka-tawo.<br/>Ang Dios sa unod nadayag,<br/>S’ya grasya’g kamat’oran;<br/>Himaya sa Dios nakita,<br/>S’ya among naambitan.<br/>',NULL,16356,3);
INSERT INTO stanza VALUES('CB68','4','Mahal ang mga ngalan Mo,<br/>Kadato’s Dios nakita;<br/>Bili’g katam-is sa ngalan,<br/>Sa gugma pahimuslan.<br/>Manlul’was pagkabililhon,<br/>Amo Ka nga simbahon;<br/>Ituboy ngalang Emmanuel,<br/>Awit’s pagdayeg sa dayon.<br/>',NULL,16357,4);
INSERT INTO stanza VALUES('CB70','1','May ngalang gustong awiton,<br/>Nga labing bililhon;<br/>Sonata sa pamati ko,<br/>Labi nga matahum.<br/>',NULL,16358,1);
INSERT INTO stanza VALUES('CB70','chorus','O mahal ko’s Jesus,<br/>O mahal ko’s Jesus,<br/>O mahal ko’s Jesus,<br/>Kay mahal man ko Niya!<br/>',NULL,16359,2);
INSERT INTO stanza VALUES('CB70','2','Nag-asoy’s gugma’s Manlul’was,<br/>Namatay’s pagluwas,<br/>Sa dugong giula Niya,<br/>Alang’s makasasala.<br/>',NULL,16360,3);
INSERT INTO stanza VALUES('CB70','3','Tagana’s Amahan nako,<br/>Gugma matag adlaw;<br/>Bisan mangitngit ang dalan,<br/>Naghayag S’ya’s gilakwan.<br/>',NULL,16361,4);
INSERT INTO stanza VALUES('CB70','4','Mobati S’yang nahigugma<br/>Sa kasub-anan ko;<br/>Sa pag-antus S’ya motabang<br/>Di mabuhat’s uban.<br/>',NULL,16362,5);
INSERT INTO stanza VALUES('CB71','1','Tanang gipadayag’s ngalan,<br/>Lami gyud’s naminaw,<br/>Labing mahal Imong ngalan,<br/>Kay gipasaylo man.<br/>',NULL,16363,1);
INSERT INTO stanza VALUES('CB71','2','Ngalang nagputos sa grasya,<br/>Sa Dios-tawo makita;<br/>Ning ngalan masubay Niya<br/>Diosnong kinabuhi.<br/>',NULL,16364,2);
INSERT INTO stanza VALUES('CB71','3','Jesus—gugma’y gipasabut,<br/>Kasubo giantus;<br/>Kanato nahangawa S’ya,<br/>Sa kasub-anan ta.<br/>',NULL,16365,3);
INSERT INTO stanza VALUES('CB71','4','Way sala nahimong sala,<br/>Mamatarung lang ta;<br/>Gitugyan ang Kaugalingon,<br/>Aron mosalig ta.<br/>',NULL,16366,4);
INSERT INTO stanza VALUES('CB71','5','Inigsangpit sa ngalan Mo,<br/>Kanimo magsimba;<br/>Labing tahum Ka’s linibo,<br/>Nagpagawas namo.<br/>',NULL,16367,5);
INSERT INTO stanza VALUES('CB72','1','Jesus, ngalang labaw’s tanan<br/>Malangit ba’g yuta;<br/>Tawo’g anghel mag-ambahan,<br/>Ngalang kahadlokan.<br/>',NULL,16368,1);
INSERT INTO stanza VALUES('CB72','2','Ngalang mahal namo hatag<br/>Mo’s makasasala,<br/>Sa kahadlok m’oy nagkuha,<br/>Kalinaw ang dala.<br/>',NULL,16369,2);
INSERT INTO stanza VALUES('CB72','3','Binilanggo gihubaran,<br/>Yawa ’yang gisamdan;<br/>Ang mga patay gibanhaw,<br/>Naluya gigamhan!<br/>',NULL,16370,3);
INSERT INTO stanza VALUES('CB72','4','Makita unta’s katawhan,<br/>Kadato’s ’yang grasya!<br/>Ang gugmang naggakos nako,<br/>Igo’s tibu’k yuta.<br/>',NULL,16371,4);
INSERT INTO stanza VALUES('CB72','5','S’ya ang pagkamatarung ko,<br/>Maoy isangyaw ko;<br/>Trabaho ko nga isinggit<br/>Tan-awang Cordero!<br/>',NULL,16372,5);
INSERT INTO stanza VALUES('CB72','6','Bisan pa sa katapusan<br/>Matawag ’yang ngalan;<br/>Isangyaw gihapon Siya,<br/>“Tan-awang Cordero!”<br/>',NULL,16373,6);
INSERT INTO stanza VALUES('CB73','1','Jesus, Ngalan nga gamhanan,<br/>Ako nga dalangpanan;<br/>“Naglingkod Ka’s kahitas-an,“<br/>Ngalan Mo kadaugan!<br/>',NULL,16374,1);
INSERT INTO stanza VALUES('CB73','2','Jesus daygon, Manluluwas,<br/>Na’ Nimong kin’hanglan ko;<br/>Tawgon lang ug ginhawaon,<br/>Kinabuhi mainom.<br/>',NULL,16375,2);
INSERT INTO stanza VALUES('CB73','3','Isangyaw, langit ug yuta,<br/>Ang gahum N’ya’g himaya;<br/>Pinasaylo ray nasayud<br/>Ngalan tambal’s kalisud!<br/>',NULL,16376,3);
INSERT INTO stanza VALUES('CB73','4','Jesus, Ngalang labing mahal,<br/>Hinagiban ko’g tambal,<br/>Sa Ngalan Mo mabuhi mi,<br/>Hangtud Ikaw moanhi.<br/>',NULL,16377,4);
INSERT INTO stanza VALUES('CB77','1','Ituboy Ngalang dungganon!<br/>Ipahayag Iyang gahum;<br/>Gamhanan S’ya magbubuntog,<br/>Dayga S’ya, Haring moabot!<br/>',NULL,16378,1);
INSERT INTO stanza VALUES('CB77','2','Habog nga torre ang Ngalan,<br/>Sa pagsulay dalangpanan;<br/>Lig-on, hilwas, sinalipdan,<br/>Ngalang Jesus kadaugan.<br/>',NULL,16379,2);
INSERT INTO stanza VALUES('CB77','3','Ituboy hangtud moabot,<br/>Yuta Ngalan N’ya magbuot;<br/>Wa na unyay sakit, sala,<br/>Kon si Cristo maghari na.<br/>',NULL,16380,3);
INSERT INTO stanza VALUES('CB77','4','Ituboy kay S’ya maghari,<br/>Sundon S’ya sa tanang hari;<br/>Ituboy ang Ngalang labaw,<br/>Ngalang naato, gimahal.<br/>',NULL,16381,4);
INSERT INTO stanza VALUES('CB77','5','Ituboy kay tanang tuhod<br/>Kaniya mangapiko gyud;<br/>Makita Niyang bunga’s Krus,<br/>Tahuron’s yuta si Jesus.<br/>',NULL,16382,5);
INSERT INTO stanza VALUES('CB78','1','Jesus, Ikawng “Ako Mao,“<br/>Ngalang dato ug tinuod,<br/>Malangkubon, kasaligan—<br/>M’oy kin’hanglan ko.<br/>',NULL,16383,1);
INSERT INTO stanza VALUES('CB78','2','Amahan anaa Nimo,<br/>Espiritu Ka’s sulod ko,<br/>Aron ang Imong kadato<br/>Masinati ko.<br/>',NULL,16384,2);
INSERT INTO stanza VALUES('CB78','3','Templo Ka, sa Dios puy-anan,<br/>Nag-asoy’s buhing Amahan;<br/>Diha Nimo nawong’s nawong<br/>Makita Siya.<br/>',NULL,16385,3);
INSERT INTO stanza VALUES('CB78','4','Cordero Ka, Pamanhonon,<br/>Alang’s sala gilansang’s krus,<br/>Aron kami makapahuway,<br/>Ikawng nag-antus.<br/>',NULL,16386,4);
INSERT INTO stanza VALUES('CB78','5','Kaalam Ka’g dalan namo,<br/>Matag adlaw ko plano Mo;<br/>Aron makalakaw’s dalan,<br/>Grasya hatagan.<br/>',NULL,16387,5);
INSERT INTO stanza VALUES('CB78','6','Ginoo, putli’g balaan,<br/>Usa’s Dios, gikahimut-an,<br/>Imo ming gipaambitan,<br/>Sa Dios mausa.<br/>',NULL,16388,6);
INSERT INTO stanza VALUES('CB78','7','Kinabuhi’g kahayag Ka,<br/>Wad-ong ngitngit, kamatayon;<br/>Nagpabuhi, naglamdag Ka,<br/>Nakagawas mi.<br/>',NULL,16389,7);
INSERT INTO stanza VALUES('CB78','8','Gahum Ka sa pagkabanhaw,<br/>Sa impyerno m’oy nagbuntog;<br/>Gigamhan mi’s Imong kusog<br/>Aron maghari.<br/>',NULL,16390,8);
INSERT INTO stanza VALUES('CB78','9','Buhing tubig ug kalan-on,<br/>Namatay Ka aron gayud<br/>Magtagbaw’s among kin’hanglan,<br/>Kan-on Ka karon.<br/>',NULL,16391,9);
INSERT INTO stanza VALUES('CB78','10','Magbalantay, Mananambal,<br/>Giayo Mong balatian,<br/>Misyon Mo maglipay, giya,<br/>Atimanon mi.<br/>',NULL,16392,10);
INSERT INTO stanza VALUES('CB78','11','Sacerdote’g Hari’s dayon,<br/>Sa Dios kami Imong dad-on;<br/>Mag-ambit sa kagahum Mo,<br/>Pagkahalangdon!<br/>',NULL,16393,11);
INSERT INTO stanza VALUES('CB78','12','Paglaum Ka’g Katubsanan,<br/>Usbon daang kabuhatan;<br/>Ihulad mi sama Nimo;<br/>Ipadayag Ka.<br/>',NULL,16394,12);
INSERT INTO stanza VALUES('CB78','13','Kalipay Ka ug Himaya,<br/>Kamatuoran ug Grasya,<br/>Bato, Balay, Bungtod, Adlaw<br/>Dili maasoy.<br/>',NULL,16395,13);
INSERT INTO stanza VALUES('CB78','14','Ikaw walay katapusan,<br/>Dato, dili gyud mahutdan,<br/>Tagbo’s among pangin’hanglan,<br/>Ug mag-awas pa.<br/>',NULL,16396,14);
INSERT INTO stanza VALUES('CB79','1','Naghari S’ya’s kahitas-an,<br/>Daygon labaw’s tanan,<br/>Kinabuhi N’ya gitugyan,<br/>Pagtubos kanato.<br/>',NULL,16397,1);
INSERT INTO stanza VALUES('CB79','chorus','Daygong ngalan N’ya,<br/>Daygong ngalan N’ya,<br/>Daygong ngalan sa Ginoo.<br/>Daygong ngalan N’ya,<br/>Daygong ngalan N’ya,<br/>Daygong ngalan sa Ginoo.<br/>',NULL,16398,2);
INSERT INTO stanza VALUES('CB79','2','Ngalang labaw’s tanang ngalan,<br/>Labi pang ituboy,<br/>Sa toong kamot’s Amahan,<br/>Anghel mag-ambahan.<br/>',NULL,16399,3);
INSERT INTO stanza VALUES('CB79','3','Manunubos, Manluluwas,<br/>Nagplano’s kal’wasan;<br/>Tawong hulog gipakamatyan,<br/>Ikaw alang’s tanan.<br/>',NULL,16400,4);
INSERT INTO stanza VALUES('CB79','4','Magtatambag Imong ngalan;<br/>Principe’s kalinaw;<br/>Nagbuntog’s mga punoan,<br/>Hari’s kahangturan!<br/>',NULL,16401,5);
INSERT INTO stanza VALUES('CB81','1','Karaan ang tinubdan Mo,<br/>Wa pang kanhing eternidad,<br/>Way katapusang Amahan,<br/>Ang dako nga Ako Mao!<br/>',NULL,16402,1);
INSERT INTO stanza VALUES('CB81','2','Bisan sa tawo nakig-uban,<br/>Apan uban’s Dios sa dayon!<br/>Kahingpit way kinutoban,<br/>Sama gyud sa Dios sa tanan!<br/>',NULL,16403,2);
INSERT INTO stanza VALUES('CB81','3','Sama’s Dios ang gigikanan,<br/>Sa wala pang kabuhatan;<br/>Sa kinaunhan, una Ka,<br/>Kanimo way nag-una pa!<br/>',NULL,16404,3);
INSERT INTO stanza VALUES('CB81','4','Ginoo, di Ka mausab,<br/>Hangtud Ka man’s eternidad;<br/>Wa nay ulahi pa Nimo,<br/>Kanimo wa nay mosunod!<br/>',NULL,16405,4);
INSERT INTO stanza VALUES('CB81','5','Sama’s Amahan kahingpit<br/>Kaniya wa Ka maglahi;<br/>Ikawng Alpa ug ang Una,<br/>Ang Omega’g ang Ulahi!<br/>',NULL,16406,5);
INSERT INTO stanza VALUES('CB81','6','Daygon, wa Kay katapusan,<br/>Ituboy kay hingpit Ka man;<br/>Pagkadako’s kahupnganan,<br/>Ikaw walay kinutoban!<br/>',NULL,16407,6);
INSERT INTO stanza VALUES('CB82','1','Manluluwas ko<br/>Nanaug’s himaya,<br/>Nianhi akong Dios,<br/>Iyang ngalan Jesus.<br/>Natawo’s pasungan,<br/>Langyaw sa Iyaha,<br/>Tawo sa kasubo ug pag-agulo.<br/>',NULL,16408,1);
INSERT INTO stanza VALUES('CB82','chorus','Gimahal ko S’ya! Gisimba ko S’ya!<br/>Gininhawa ko, tanan’s tanan!<br/>Ang Magbubuhat Manluluwas ko,<br/>Kahupnganan’s Dios naa Niya.<br/>',NULL,16409,2);
INSERT INTO stanza VALUES('CB82','2','Unsang pagpaubos,<br/>Kanato nagtubos;<br/>Diha’s kangiob sa<br/>Kawalay paglaum,<br/>Siya naluoy,<br/>Pagkadios gihubo,<br/>Aron kalag ko Iyang maangkon.<br/>',NULL,16410,3);
INSERT INTO stanza VALUES('CB82','3','Wa magpanuko,<br/>Na-unod ug dugo<br/>Dagway’s tawo gisul-ob,<br/>Plano’s Dios nadayag;<br/>O ang misteryo,<br/>Halad sa Calvario,<br/>Karon nasayran Kang “AKO MAO.”<br/>',NULL,16411,4);
INSERT INTO stanza VALUES('CB84','1','Paminawa ang awit,<br/>“Himayaon ang Hari;<br/>Sa yuta may kadait,<br/>Dios ug tawo nagkauli.“<br/>Maglipayng kanasuran<br/>Duyog sa kadaugan;<br/>Uban nga magmantala,<br/>“Cristo natawo’s Bethlehem.“<br/>(Sublia ang katapusang duha ka linya)<br/>',NULL,16412,1);
INSERT INTO stanza VALUES('CB84','2','Gisimba’s kahitas-an,<br/>Ginoo’s dayon awitan:<br/>Nianhi Ka’s panahon,<br/>Sa ulay gipanamkon.<br/>Bisan unod nagtabon,<br/>Nakita—Dios na-tawo!<br/>Uban nato nipuyo,<br/>Jesus Immanuel nato.<br/>',NULL,16413,2);
INSERT INTO stanza VALUES('CB84','3','Principe’s kadaitan!<br/>Adlaw’s pagkamatarung!<br/>Kinabuhi’g kahayag,<br/>Pako Mo makaayo;<br/>Gib’yaan Mong himaya,<br/>Aron di mi mamatay;<br/>Mga anak modaghan,<br/>Nga ianak pag-usab.<br/>',NULL,16414,3);
INSERT INTO stanza VALUES('CB84','4','Tinguha’s kanasuran,<br/>Kanamo nagbalay Ka;<br/>Bangon kaliwat’s babaye,<br/>Ulo’s bitin samari;<br/>Palaang dagwayng Adam,<br/>Sa dagway Mo pulihan:<br/>O katapusang Adam,<br/>Ipahiuli’s gugma Mo.<br/>',NULL,16415,4);
INSERT INTO stanza VALUES('CB86','1','Labing mahimayaong Dios,<br/>Nagpakatawo nagpaubos,<br/>Aron mahiduol namo;<br/>Ginoo gihandom!<br/>',NULL,16416,1);
INSERT INTO stanza VALUES('CB86','2','Tanang himaya’g pagkadios<br/>Gipadaplin, gitanggong’s unod,<br/>Way makita nga katahum,<br/>Ginoo gihandom!<br/>',NULL,16417,2);
INSERT INTO stanza VALUES('CB86','3','Daw gamut sa malang yuta,<br/>Tawo sa kasub-anan Ka;<br/>Gitamay ug gidumtan Ka;<br/>Ginoo gihandom!<br/>',NULL,16418,3);
INSERT INTO stanza VALUES('CB86','4','Malomo’g mapaubsanon,<br/>Sa tanan madinawaton,<br/>Sa Dios ug tawo way gimulo;<br/>Ginoo gihandom!<br/>',NULL,16419,4);
INSERT INTO stanza VALUES('CB86','5','Pagka-tawo Mo, O kalomo,<br/>Tanang bahin angay gayud,<br/>Halad-kalan-on’s Amahan,<br/>Ginoo gihandom!<br/>',NULL,16420,5);
INSERT INTO stanza VALUES('CB86','6','Pagbuot’s Dios gibantayan,<br/>Sa Yawa wa magpalimbong,<br/>Way sama Mong maunongon,<br/>Ginoo gihandom!<br/>',NULL,16421,6);
INSERT INTO stanza VALUES('CB86','7','Sa pagsugot’s pagbuot’s Dios,<br/>Ang kamatayon giantus,<br/>Gipulihan ko didto’s Krus,<br/>Ginoo gihandom!<br/>',NULL,16422,7);
INSERT INTO stanza VALUES('CB86','8','Tungod ni’ni gibayaw Ka,<br/>Gipasidunggan’s Amahan,<br/>Mga tuhod mangapiko;<br/>Magsimba ko Nimo!<br/>',NULL,16423,8);
INSERT INTO stanza VALUES('CB87','1','Ginoo, sa among paghandom<br/>Sa kinabuhi Mo;<br/>Puno’s grasya, mahigugmaon,<br/>Sa Dios matinumanon;<br/>',NULL,16424,1);
INSERT INTO stanza VALUES('CB87','2','Gugma Mo nasulayan gyud,<br/>Kusgan pa’s lubnganan;<br/>Bangkaw Kanimo nagdughang,<br/>Nagdugo’s pagluwas;<br/>',NULL,16425,2);
INSERT INTO stanza VALUES('CB87','3','Bisan’s kasakit, kaguol,<br/>Maayo’y gibuhat,<br/>Sa daghan Mong kasub-anan,<br/>Way gibagulbolan.<br/>',NULL,16426,3);
INSERT INTO stanza VALUES('CB87','4','Nagmaluibon ang tanan,<br/>Matinumanon Ka,<br/>Giila ngalan’s Amahan,<br/>Buot N’ya gituman;<br/>',NULL,16427,4);
INSERT INTO stanza VALUES('CB87','5','Wa matandog’s limbong’s yawa,<br/>Kaulawa’g kapildehan;<br/>Ang way kasadyang dalan Mo<br/>Sa krus nagda’ Nimo.<br/>',NULL,16428,5);
INSERT INTO stanza VALUES('CB87','6','Natingala’s kaaghop Mo,<br/>Masama unta mi;<br/>Makapah’way mi’g malipay,<br/>Nga makat-on Nimo.<br/>',NULL,16429,6);
INSERT INTO stanza VALUES('CB90','1','Dawata ang hinayng awit,<br/>Imo mang gahum, pagdayeg;<br/>Grasya Mo halandumon,<br/>Ginoong mahatagon!<br/>',NULL,16430,1);
INSERT INTO stanza VALUES('CB90','2','Dato Ka sa himaya,<br/>Paglaum’s katawhan Mo;<br/>Nakabus aron kami,<br/>Madato uban Nimo.<br/>',NULL,16431,2);
INSERT INTO stanza VALUES('CB90','3','Langit unsay nasumhan?<br/>Yuta na’ ba’y naibgan?<br/>Nganong langit gib’yaan,<br/>Namatayng tinamay man?<br/>',NULL,16432,3);
INSERT INTO stanza VALUES('CB90','4','Sa langit—halangdon Ka!<br/>Sinalikway sa yuta!<br/>Bisan Ikaw nasayud,<br/>Kasakit giantus gyud!<br/>',NULL,16433,4);
INSERT INTO stanza VALUES('CB90','5','Matag handom ning gugmaha,<br/>Malipayng gikaloy-an,<br/>Maulaw sa samang takna,<br/>Kay di Ka man kabaslan.<br/>',NULL,16434,5);
INSERT INTO stanza VALUES('CB90','6','Naglaum moabot Ka,<br/>Kami makagawas na;<br/>Kanimo’s himaya dad-on,<br/>Silbehan’s angay Nimo.<br/>',NULL,16435,6);
INSERT INTO stanza VALUES('CB90','7','Naghulat kami Nimo,<br/>Anus-a Ka makita.<br/>Mabuhi alang Nimo,<br/>Hangtud nga lalinon Mo.<br/>',NULL,16436,7);
INSERT INTO stanza VALUES('CB93','1','Ginoo, gihandom namo<br/>Ang dalan Mo’s kasubo,<br/>Nagtapos nga kasakitan,<br/>Labi Kang mahal namo.<br/>',NULL,16437,1);
INSERT INTO stanza VALUES('CB93','chorus','Manluluwas, O daygon Ka!<br/>Namatay alang namo!<br/>Himayaon, himayaon!<br/>Kinabuhi among naangkon!<br/>',NULL,16438,2);
INSERT INTO stanza VALUES('CB93','2','Kasub-anang naagian<br/>Walay tawong makatugkad;<br/>Way naingnan gidagmalan,<br/>Di maasoy ang tanan.<br/>',NULL,16439,3);
INSERT INTO stanza VALUES('CB93','3','Walay tawo nga makasunod<br/>Samtang Ikaw nagtubos;<br/>Kay kadtong mga pag-antus<br/>Lalum ug di masukod!<br/>',NULL,16440,4);
INSERT INTO stanza VALUES('CB93','4','Gisukod kabug-at’s sala,<br/>Kasuko, pait, tunglo;<br/>Giluib’s tawo, gib’yaan’s Dios,<br/>Nasayud mi’s gugma Mo!<br/>',NULL,16441,5);
INSERT INTO stanza VALUES('CB108','1','“Tawo’s Kasubo” ang ngalan,<br/>Dios Anak nga nianhi,<br/>Aron mabakwi kami;<br/>Hallelujah! Manlul’was S’ya!<br/>',NULL,16442,1);
INSERT INTO stanza VALUES('CB108','2','Naulawa’g gitamay,<br/>Gihukman sa dapit ko;<br/>Tungod N’ya gipasaylo,<br/>Hallelujah! Manlul’was S’ya!<br/>',NULL,16443,2);
INSERT INTO stanza VALUES('CB108','3','Kita sad-an, dautan,<br/>Cordero S’yang way apan;<br/>Gitubos gyud tang tanan,<br/>Hallelujah! Manlul’was S’ya!<br/>',NULL,16444,3);
INSERT INTO stanza VALUES('CB108','4','Gibitay ug namatay,<br/>Singgit Niya, “Tapos na!“<br/>Sa langit gituboy na,<br/>Hallelujah! Manlul’was S’ya!<br/>',NULL,16445,4);
INSERT INTO stanza VALUES('CB108','5','Inigbalik’s Hari ta,<br/>Dad-on ta’s gingharian,<br/>Ato na sab awitan,<br/>Hallelujah! Manlul’was S’ya!<br/>',NULL,16446,5);
INSERT INTO stanza VALUES('CB112','1','Pagkatam-is ni’ning sugilanon ta,<br/>Gugma nagsugo himaya b’yaan N’ya;<br/>Namatay sa Calvario puli nato,<br/>Pagtubos gihuman alang kanato.<br/>',NULL,16447,1);
INSERT INTO stanza VALUES('CB112','chorus','Dayga S’ya! Dayga S’ya!<br/>Tanan natapos N’ya;<br/>Dayga ang ngalan N’ya!<br/>Anak sa Dios dayga.<br/>Himayaon’s Jesus Manlul’was, Abyan;<br/>Awitan ta S’ya sa way katapusan.<br/>',NULL,16448,2);
INSERT INTO stanza VALUES('CB112','2','O katahum! Ang gikin’hanglan’s sugo<br/>Sa dugo sa katubsanan gitagbo;<br/>Hukom sa sala Anak m’oy nangako,<br/>Naghimaya’s Dios sa tanang nahimo.<br/>',NULL,16449,3);
INSERT INTO stanza VALUES('CB112','3','Trono ni Cristo labing masanagon,<br/>Husto gyud, ngalan labaw’s tanan ilhon!<br/>Jesus, Ginoong pinurongan karon,<br/>Takus gayud sa tanan nga simbahon.<br/>',NULL,16450,4);
INSERT INTO stanza VALUES('CB116','1','Katubsanan Mo, Ginoo,<br/>Pagkakatingad-an!<br/>Wa pa igdungog, igkita,<br/>Ni mahunahuna!<br/>Diosnon Ka ug misteryoso,<br/>Dili maasoy ko!<br/>Katubsanan kahibudngan,<br/>Di arang madayeg man!<br/>',NULL,16451,1);
INSERT INTO stanza VALUES('CB116','2','Didto sa Krus ang lawas Mo<br/>Gidughang, gipatay;<br/>Dugo ug tubig niagay,<br/>Nagbuhi’g nagtubos.<br/>Dugong naghinlo kanamo,<br/>Nagpahimuot’s Dios;<br/>Ug gianak Mo pag-usab,<br/>Nausa Kanimo.<br/>',NULL,16452,2);
INSERT INTO stanza VALUES('CB116','3','Usang trigo Kang namatay,<br/>Namunga ug daghan,<br/>Nasakot, na-Lawas Nimo,<br/>Usa’g kina’ya Mo;<br/>Kami m’oy Imong pagtubo,<br/>Ikawng sulod namo;<br/>Mabuhi Ka ug maglihok,<br/>Mapadayag namo.<br/>',NULL,16453,3);
INSERT INTO stanza VALUES('CB116','4','Sanglit Lawas Mong kapuy-an,<br/>Kami puloy-anan;<br/>Dinhi namo napalgan Mo<br/>Imong pahulayan.<br/>Magtagbaw sa tinguha Mo,<br/>Kami kapikas Mo;<br/>Nagpahimulos uban Ka,<br/>Sa usa ka Lawas.<br/>',NULL,16454,4);
INSERT INTO stanza VALUES('CB116','5','Samtang naghandom mi karon<br/>Uban ning timaan;<br/>Puno gayud sa pagdayeg<br/>Sa Imong pagtubos.<br/>Gihimo Mong puloy-anan,<br/>Lawas ug kapikas;<br/>Kanimo magpasalamat,<br/>Magsimba’g magdayeg.<br/>',NULL,16455,5);
INSERT INTO stanza VALUES('CB117','1','Cristo, Ginoo nabanhaw,<br/>Hallelujah!<br/>Nagtagbo sa kinahanglan,<br/>Hallelujah!<br/>Maghugyaw’s kadaugan,<br/>Hallelujah!<br/>Mag-awit langit ug yuta,<br/>Hallelujah!<br/>',NULL,16456,1);
INSERT INTO stanza VALUES('CB117','2','Nabanhaw ang atong Hari,<br/>Hallelujah!<br/>Haing ikot’s kamatayon?<br/>Hallelujah!<br/>Namatay ug nagluwas,<br/>Hallelujah!<br/>Haing pagdaug’s lubnganan?<br/>Hallelujah!<br/>',NULL,16457,2);
INSERT INTO stanza VALUES('CB117','3','Buhat sa gugmang nagtubos,<br/>Hallelujah!<br/>Nakigbisug, nakadaug,<br/>Hallelujah!<br/>Kamatayon way gahum,<br/>Hallelujah!<br/>Cristo nikayab sa langit,<br/>Hallelujah!<br/>',NULL,16458,3);
INSERT INTO stanza VALUES('CB117','4','Nikayab uban kang Cristo,<br/>Hallelujah!<br/>Uban Niya nga gituboy,<br/>Hallelujah!<br/>Gisama N’yang nabanhaw,<br/>Hallelujah!<br/>Gawas na sa tanang gapos,<br/>Hallelujah!<br/>',NULL,16459,4);
INSERT INTO stanza VALUES('CB119','1','Hallelujah, “Nabanhaw S’ya!“<br/>Si Jesus nikayab na!<br/>Ang kamatayon gibungkag;<br/>Singgit’s anghel gitubag:<br/>Nabanhaw S’ya, nabanhaw S’ya,<br/>Buhi, di na mamatay.<br/>',NULL,16460,1);
INSERT INTO stanza VALUES('CB119','2','Hallelujah, nabanhaw S’ya!<br/>Matinuboyng Ulo ta;<br/>Gipasaksing Espiritu,<br/>Manlalaban ta Siya:<br/>Nabanhaw S’ya, nabanhaw S’ya,<br/>Gimatarung ta Niya.<br/>',NULL,16461,2);
INSERT INTO stanza VALUES('CB119','3','Hallelujah, nabanhaw S’ya!<br/>Kamatayon way gahum;<br/>Cristo mismo pagkabanhaw,<br/>Mga “Iya” banhawon:<br/>Nabanhaw S’ya, nabanhaw S’ya,<br/>Ginoo ug Hari ta.<br/>',NULL,16462,3);
INSERT INTO stanza VALUES('CB120','1','Nabanhaw S’ya, paghukom wala na,<br/>Kay gipalit ta sa dugo Niya.<br/>Di na masudya pa’s tanang sala,<br/>Basyo nang lubnganan, nabanhaw S’ya.<br/>',NULL,16463,1);
INSERT INTO stanza VALUES('CB120','2','Nabanhaw S’ya, nabanhaw sab kita,<br/>Gilaglag N’ya tanang kaaway ta.<br/>Pagkabanhaw na m’oy gibarugan,<br/>Wala na gyud sa pagkahinukman.<br/>',NULL,16464,2);
INSERT INTO stanza VALUES('CB120','3','Nabanhaw S’ya, gitubos na kita<br/>Nagsunod’s dalang gilakwan Niya.<br/>Balaang puy-anan nay dapit ta,<br/>Presensya’s Amaha’y gipuy-an ta.<br/>',NULL,16465,3);
INSERT INTO stanza VALUES('CB120','4','Nabanhaw S’ya, Ginoo nag-una.<br/>Pangandoy S’ya, ug di makasala.<br/>Nabanhaw S’ya: maoy isinggit ta,<br/>“Nidaug Ka! Kami nagawas na!”<br/>',NULL,16466,4);
INSERT INTO stanza VALUES('CB123','1','Naghigda sa lubong—<br/>Ang Manluluwas!<br/>Sa adlaw naghulat—<br/>Ginoo ko!<br/>',NULL,16467,1);
INSERT INTO stanza VALUES('CB123','chorus','Nabanhaw S’ya sa lubong!<br/>Ang kaaway N’ya gidaug na;<br/>Gidaug ang gahum sa kangitngitan,<br/>Maghari S’ya uban’s mga balaan.<br/>Buhi na! Nabanhaw!<br/>Hallelujah! Nabanhaw!<br/>',NULL,16468,2);
INSERT INTO stanza VALUES('CB123','2','Kawang ang pagbantay—<br/>Pagsampong sa bato!<br/>Sa lubong sa akong—<br/>Manluluwas.<br/>',NULL,16469,3);
INSERT INTO stanza VALUES('CB123','3','Kamatayon Kan’ya—<br/>Di makagahum,<br/>Nabuksan ang lubong—<br/>Sa Ginoo.<br/>',NULL,16470,4);
INSERT INTO stanza VALUES('CB124','1','Nidaug si Cristo, daygon!<br/>Sala gihukman’s dayon!<br/>Daang Adam gitapos N’ya,<br/>Pagtubos napalgan ta!<br/>Nagwagtang’s gahum’s dautan,<br/>Sa Krus gidaug tanan!<br/>',NULL,16471,1);
INSERT INTO stanza VALUES('CB124','2','Nabanhaw si Cristo, daygon!<br/>Sa lubong gipabangon!<br/>Gilamoy N’yang kamatayon,<br/>Aron kita buhion!<br/>Gibungkag Niya ang gahum<br/>Sa impyerno’g kadulom!<br/>',NULL,16472,2);
INSERT INTO stanza VALUES('CB124','3','Daygon nikayab si Cristo!<br/>Gipalingkod sa trono!<br/>Labaw’s tanang pamunoan,<br/>Labing halangdong Ngalan!<br/>Naangkon tanang kagahum<br/>Kaaway N’ya pukanon!<br/>',NULL,16473,3);
INSERT INTO stanza VALUES('CB124','4','Hallelujah, S’ya nidaug,<br/>Nidaug sa Calvario!<br/>Hallelujah, nabanhaw na,<br/>Gipakitang pagdaug!<br/>Hallelujah, nikayab S’ya,<br/>Sa dayon maghari S’ya!<br/>',NULL,16474,4);
INSERT INTO stanza VALUES('CB127','1','Libolibong mga tingog,<br/>Pagdayeg sa Cordero;<br/>Libolibo ang nisanong,<br/>Singgit kusog nilanog.<br/>',NULL,16475,1);
INSERT INTO stanza VALUES('CB127','2','“Daygong Cordero,” mag-awit,<br/>Tigum’s tibuok langit;<br/>Tanang baba makig-ambit’s<br/>Way katapusang awit.<br/>',NULL,16476,2);
INSERT INTO stanza VALUES('CB127','3','Mao kining pasalamat<br/>Sa Amahan nikayab;<br/>Langit usa’y hunahuna,<br/>Kang Jesus mangluhod ta.<br/>',NULL,16477,3);
INSERT INTO stanza VALUES('CB127','4','Tanang hukom sa Amahan,<br/>Sama’g dungog ang Anak;<br/>Kasanag N’ya nagpadayag’s<br/>Himaya sa Amahan.<br/>',NULL,16478,4);
INSERT INTO stanza VALUES('CB127','5','Pinaagi’s Espiritu,<br/>Panon naglibot’s Cordero,<br/>Purongan S’ya sa kalipay,<br/>Daygon ang “AKO MAO.”<br/>',NULL,16479,5);
INSERT INTO stanza VALUES('CB127','6','Pagkalipay bag-ong binuhat,<br/>Pahulay sa kalinaw;<br/>Binulahan’s kaluwasan,<br/>Kasub-anan nahanaw.<br/>',NULL,16480,6);
INSERT INTO stanza VALUES('CB127','7','Pamatia pa pag-usab,<br/>Tingog’s pagdayeg nilanog!<br/>Tanan nisinggit ug Amen,<br/>Amen! tubag’s kalipay.<br/>',NULL,16481,7);
INSERT INTO stanza VALUES('CB132','1','Si Jesus naglingkod’s langit!<br/>Ginoo ta na’s trono;<br/>S’ya ang tawong gituboy’s Dios,<br/>Gipurongan’s himaya.<br/>',NULL,16482,1);
INSERT INTO stanza VALUES('CB132','2','Gisul-ob kinaiya’s tawo,<br/>Namatay, Dios nagplano,<br/>Uban’s lawas S’ya nabanhaw,<br/>Nikayab ingon nga tawo.<br/>',NULL,16483,2);
INSERT INTO stanza VALUES('CB132','3','Diha N’ya Dios gipaubos,<br/>Uban sa tawo nipuyo;<br/>Diha Niya tawo gituboy,<br/>Napasig-uli sa Dios.<br/>',NULL,16484,3);
INSERT INTO stanza VALUES('CB132','4','Dios nasagol dinhi’s tawo,<br/>Dios sa tawo gimatuod;<br/>Tawo S’yang nasakot sa Dios,<br/>Tawong nahimaya sa Dios.<br/>',NULL,16485,4);
INSERT INTO stanza VALUES('CB132','5','Gikan Niyang Gihimaya,<br/>Nianhi ang Esp’ritu;<br/>Buhat ni Jesus ug Persona,<br/>Kini m’oy nagmantala.<br/>',NULL,16486,5);
INSERT INTO stanza VALUES('CB132','6','Nahiusa ang Iglesia,<br/>Ning gihimaya’s langit;<br/>Pinaagi’s Espiritu<br/>Bahin’s Lawas matukod.<br/>',NULL,16487,6);
INSERT INTO stanza VALUES('CB132','7','Tawo nga naglingkod sa langit!<br/>Ang Ginoo na’s trono;<br/>Manluluwas Jesucristo,<br/>Pinurongan’s himaya!<br/>',NULL,16488,7);
INSERT INTO stanza VALUES('CB133','1','Ikawng Ginoo sa tanan,<br/>Ug ang pinurongan;<br/>Sa gahum ug kahalangdon,<br/>Naila Ka’s tanan.<br/>',NULL,16489,1);
INSERT INTO stanza VALUES('CB133','2','Dinhi Ikaw Dios diha’s tawo,<br/>Ulipon mag dagway;<br/>Sa langit, diha’s Dios tawo Ka,<br/>Ginoong giila.<br/>',NULL,16490,2);
INSERT INTO stanza VALUES('CB133','3','Ikaw ang Tawong gipalingkod,<br/>Sa Dios didto’s trono;<br/>Tanang gahum’s langit, yuta,<br/>Tanan naimoha.<br/>',NULL,16491,3);
INSERT INTO stanza VALUES('CB133','4','Gituboy’s kinahitas-an,<br/>Ngalan labaw’s tanan;<br/>Ilhon’s tanan nga Ginoo<br/>Mangluhod mi Nimo.<br/>',NULL,16492,4);
INSERT INTO stanza VALUES('CB133','5','Gihimo’s Dios Ikawng Cristo,<br/>Ug usab Ginoo,<br/>Sa langit among nakita,<br/>Uban Ka’s Dios sa trono!<br/>',NULL,16493,5);
INSERT INTO stanza VALUES('CB133','6','Ginoo Ka nga mahalon,<br/>Sa awit pagdaygon;<br/>Simbahon Ginoo’s tanan,<br/>Sa pagdayeg angay man!<br/>',NULL,16494,6);
INSERT INTO stanza VALUES('CB147','1','Dinihogan Ka sa Dios,<br/>Hari’s mga hari!<br/>Bug-os kaming magsimba,<br/>Sa awit nga dala!<br/>Gingharia’g trono Mo,<br/>Hangtud gayud’s hangtud!<br/>Uban’s gugma’g hustisya,<br/>Pirmi nang Hari Ka!<br/>',NULL,16495,1);
INSERT INTO stanza VALUES('CB147','2','Ang Dios sa Bukid sa Sion,<br/>Nagtukod Kanimo,<br/>Tanang nasud ihatag<br/>Nga panulondon Mo.<br/>Gitugyanan Ka Niya<br/>Sa tanang kagahum,<br/>Magbuot’s kanasuran,<br/>Hangtud’s kahangturan.<br/>',NULL,16496,2);
INSERT INTO stanza VALUES('CB147','3','Katumanan’s panahon,<br/>Sa di pa moabot,<br/>Magdayeg Nimong linibo,<br/>Adlaw-adlaw gayud!<br/>Katawhan’s tanang dapit,<br/>Kanimo mag-awit,<br/>Simbahon, silbehan Ka,<br/>Haring Manluluwas!<br/>',NULL,16497,3);
INSERT INTO stanza VALUES('CB147','4','Sa gitudlo nga takna<br/>Ikaw moabot na,<br/>Mga nasud sa yuta,<br/>Magingharian Mo.<br/>Kahalangdon, kasanag,<br/>Hari Kang silbehan,<br/>Mga banay’g katawhan,<br/>Magdayeg Nimong tanan!<br/>',NULL,16498,4);
INSERT INTO stanza VALUES('CB148','1','Hari Ka’s mga hari,<br/>Mangyukbo’s presensya Mo;<br/>Simbahon Ka, O Cristo,<br/>Sa balaang kataha.<br/>Pagdayeg’s mga balaan,<br/>Hari, maimo tanan!<br/>',NULL,16499,1);
INSERT INTO stanza VALUES('CB148','2','Pagbulot-an Mo’g gahum,<br/>Modaug bisan asa!<br/>Silbehan Ka sa tanan,<br/>Sa Imong kahalangdon!<br/>Pagdayeg’s mga balaan,<br/>Hari, maimo tanan!<br/>',NULL,16500,2);
INSERT INTO stanza VALUES('CB148','3','Gingharian ra Nimo,<br/>Ang mobarug, Ginoo!<br/>Himaya ug gahum Mo,<br/>Awiton’s kahangturan!<br/>Pagdayeg’s mga balaan,<br/>Hari, maimo tanan!<br/>',NULL,16501,3);
INSERT INTO stanza VALUES('CB148','4','Magbubuot, Hari ko,<br/>Mag-awit mi’s ngalan Mo!<br/>Moabot na ang takna,<br/>Bug-os nang maghari Ka!<br/>Daygon gihapon’s awit,<br/>Hari Ka’s mga hari!<br/>',NULL,16502,4);
INSERT INTO stanza VALUES('CB152','1','Pagkalalum, O Ginoo,<br/>Sa gugma Mo kanako!<br/>Lalum pa sa kadagatan,<br/>Dili gayud matugkad!<br/>Gugma Mo nagpakamatay,<br/>Maangkon ko lang Ikaw;<br/>Naghiusa nako Nimo,<br/>Naghimong kabahin Mo.<br/>',NULL,16503,1);
INSERT INTO stanza VALUES('CB152','2','Gugma Mo dagha’g gihatag,<br/>Di sarang nga maasoy,<br/>Pakig-usa Mo kanako<br/>Maoy labaw sa tanan.<br/>Kay nabatonan ko Ikaw,<br/>Sangkap sa akong tanan;<br/>Kanunayng matagamtaman,<br/>Kinabuhi ko Ikaw.<br/>',NULL,16504,2);
INSERT INTO stanza VALUES('CB152','3','Gugma maoy pagpadayag<br/>Sa kaugalingon Mo,<br/>Naghimo’s kinabuhi ko<br/>Sibo sa diosnong plano.<br/>Grasya Mo pagkadagaya,<br/>Adlaw-adlaw sangkap ko,<br/>Gihigugma, gitagad Mo,<br/>Pagkatam-is, Ginoo.<br/>',NULL,16505,3);
INSERT INTO stanza VALUES('CB152','4','Unsay makabulag nako?<br/>Wala, kay ang gugma Mo<br/>Hangtud man sa katapusan,<br/>Makig-usa, magsakot!<br/>Ako Imo, Ikaw ako,<br/>Hingpit gayud nga usa!<br/>Magpamatuod’s gugma Mo:<br/>Mag-usa nato’s dayon!<br/>',NULL,16506,4);
INSERT INTO stanza VALUES('CB153','1','Maokupahan ba kaha,<br/>Ang among hunahuna<br/>Kon di pa ingon kadako<br/>Ang gugma Mo kanamo!<br/>',NULL,16507,1);
INSERT INTO stanza VALUES('CB153','2','Gimahal ang kahimaya<br/>Nga Kanimo nakita;<br/>Gimahal Ka’s kaulaw’s krus,<br/>Alang namo giantus.<br/>',NULL,16508,2);
INSERT INTO stanza VALUES('CB153','3','Walay gugmang molabaw pa,<br/>Mamatay alang’s abyan;<br/>Apan Ikaw ray namatay,<br/>Alang’s mga kaaway!<br/>',NULL,16509,3);
INSERT INTO stanza VALUES('CB153','4','Bisan may dagway sa Dios Ka,<br/>Gipurongan’s himaya,<br/>Nasulogoo’g dagway Ka,<br/>Gidagsaan’s kasubo.<br/>',NULL,16510,4);
INSERT INTO stanza VALUES('CB153','5','Nasama Ka’s dautang tawo,<br/>Gawas lamang sa sala;<br/>Aron masama mi Nimo,<br/>Lahi sa kaniadto.<br/>',NULL,16511,5);
INSERT INTO stanza VALUES('CB153','6','Sama Nimo’s kusog, gugma,<br/>Sa tanan gyud nga bahin,<br/>Mausab, mahimayaon,<br/>Hangtud nawong Mo masud-ong.<br/>',NULL,16512,6);
INSERT INTO stanza VALUES('CB153','7','Gimahal namo pag-ayo,<br/>Ang paghandom’s gugma Mo;<br/>Ngalan Mo magpabilin gyud,<br/>Angay’s among pagtahud.<br/>',NULL,16513,7);
INSERT INTO stanza VALUES('CB154','1','Gugma Mo bisan di gyud matugkad,<br/>Manlul’was ko, apan kining kalag<br/>Bu’t masayud’s kataas, kalapad,<br/>Kahabog, kalalum, dayong kusog<br/>Sa gugma Mo.<br/>',NULL,16514,1);
INSERT INTO stanza VALUES('CB154','2','Gugma Mo, Jesus, di ikaasoy,<br/>Manlul’was, apan mga ngabil ko<br/>Bu’t mosangyaw’s gugma Mong mokuha<br/>Sa kahadlok’s makasasala ug<br/>Ipanganak.<br/>',NULL,16515,2);
INSERT INTO stanza VALUES('CB154','3','Gugma Mo labaw’s mga pagdayeg,<br/>Jesus, kasingkasing ko moawit,<br/>Gugma Mo dato, puno kaayo,<br/>Makasasalang rebelde Imong<br/>Gipaduol.<br/>',NULL,16516,3);
INSERT INTO stanza VALUES('CB154','4','Bisan di mahimo dinhi karon<br/>Pagtugkad, asoy’g pagdayeg’s gugma Mo,<br/>Apan dad-on ang basyong sudlanan<br/>Kanimo, O tuboran sa gugma,<br/>Ug pun-on Mo.<br/>',NULL,16517,4);
INSERT INTO stanza VALUES('CB154','5','Basyong sudlanan kong wa gyuy dala<br/>Bisan gamayng pagmahal Kanimo;<br/>Balikbalik mang makaduol ko,<br/>Kay, “Gihigugma ko Nimo,” m’oy<br/>Bugtong hangyo ko.<br/>',NULL,16518,5);
INSERT INTO stanza VALUES('CB154','6','O pun-a ako sa Imong gugma,<br/>Dad-a’s buhing tuboran sa langit;<br/>Tugoting makaduol’s kayano,<br/>Di na mangita’g laing tuboran,<br/>Gawas Nimo.<br/>',NULL,16519,6);
INSERT INTO stanza VALUES('CB154','7','Kon makita Ka na gyud sa nawong,<br/>Samtang maglingkod’s trono uban Ka,<br/>Kalag ko mag-awit sa gugma Mo,<br/>Sa kalapad, taas, habog, lalum,<br/>Kusog’s dayon.<br/>',NULL,16520,7);
INSERT INTO stanza VALUES('CB163','1','May linibo untang dila<br/>Magdayeg’s Manunubos,<br/>Kahimayaan’s Dios, Hari,<br/>Pagdaug’s grasya N’ya.<br/>',NULL,16521,1);
INSERT INTO stanza VALUES('CB163','2','Agalon, Dios, puno’s grasya,<br/>Tabanging magsangyaw<br/>Sa kahalangdon’s ngalan Mo,<br/>Sa tibuok yuta.<br/>',NULL,16522,2);
INSERT INTO stanza VALUES('CB163','3','Jesus nagwala’s kahadlok,<br/>Nagkuha’s kasubo;<br/>Ngalan Mo honi’s igdungog,<br/>Kalinaw’g kahimsog.<br/>',NULL,16523,3);
INSERT INTO stanza VALUES('CB163','4','Sa gugma N’ya nabihag ko,<br/>Bu’t kong magpabihag;<br/>Gigapos, gibun-og, gipatay,<br/>Aron kalag ko magawas.<br/>',NULL,16524,4);
INSERT INTO stanza VALUES('CB163','5','Gibungkag gahum sa sala,<br/>Nagawas binilanggo;<br/>Dautan nahinlo’s dugo,<br/>Ako, labi na gyud.<br/>',NULL,16525,5);
INSERT INTO stanza VALUES('CB163','6','Karon Ngalan gimahal ko,<br/>Sugtong pagbuot Mo;<br/>Kon may libong kasingkasing,<br/>Ginoo, maimo.<br/>',NULL,16526,6);
INSERT INTO stanza VALUES('CB170','1','Pamanhonon Kang tinudlo<br/>Sa Dios, ug mahal namo,<br/>Labi Ka nga madanihon,<br/>Ug labi gyung matahum!<br/>',NULL,16527,1);
INSERT INTO stanza VALUES('CB170','2','Gidayeg Ka, Pinalangga,<br/>O pagkabililhon Mo,<br/>Gimahal ko ang gugma Mo,<br/>Ug kahiligugmaon.<br/>',NULL,16528,2);
INSERT INTO stanza VALUES('CB170','3','Matahum Ka’s labing tahum,<br/>Tam-is pa’s labing tam-is;<br/>Malomo Ka’g maluloy-on,<br/>Way katugbang’s katahum.<br/>',NULL,16529,3);
INSERT INTO stanza VALUES('CB170','4','Puno’s mirra ang biste Mo,<br/>Baba Mo puno’s grasya;<br/>Nangalimyon Ka’s kasakit,<br/>Sa gugma gigakos Ka.<br/>',NULL,16530,4);
INSERT INTO stanza VALUES('CB170','5','Lana’s kalipay gidihog<br/>Sa Dios diha Kanimo,<br/>Gikan sa kaiglesiahan<br/>Tingban Ka sa pagdayeg.<br/>',NULL,16531,5);
INSERT INTO stanza VALUES('CB170','6','Dios nagpanalangin Nimo,<br/>Ikaw nagmadaugon;<br/>Naglingkod’s trono’s himaya,<br/>Gahum, pagkahalangdon.<br/>',NULL,16532,6);
INSERT INTO stanza VALUES('CB170','7','Tinguha Ka’s mga nasud,<br/>O pagkabililhon Mo;<br/>Labaw’s tagpulo ka libo,<br/>Takus nga higugmaon.<br/>',NULL,16533,7);
INSERT INTO stanza VALUES('CB171','1','Ginoo’s paghandom namo<br/>Katam-is gibati;<br/>Nangandoy sa hinanali<br/>Nga malalin kami.<br/>',NULL,16534,1);
INSERT INTO stanza VALUES('CB171','chorus','Sama Ka sa bulak nga †copher,<br/>Namulak sa kaparrasan;<br/>Katahum di ikatandi,<br/>Gimahal, gidayeg!<br/>',NULL,16535,2);
INSERT INTO stanza VALUES('CB171','2','Way honing arang magdayeg’s<br/>Kahingpit’s grasya Mo,<br/>May tawo bang makapa’mulos<br/>Sa gugma Mo’s bug-os?<br/>',NULL,16536,3);
INSERT INTO stanza VALUES('CB171','3','Ang labing naglipay namo<br/>Di gugma’g grasya Mo,<br/>Kondi’ Imong Kaugalingon<br/>Nga nagtagbaw namo.<br/>',NULL,16537,4);
INSERT INTO stanza VALUES('CB171','4','Matahum pa sa matahum,<br/>Tam-is pa sa tam-is;<br/>Way lain’s langit o yuta<br/>Magtagbaw’s tinguha.<br/>',NULL,16538,5);
INSERT INTO stanza VALUES('CB172','1','Di pul-ang mohanggap Nimo,<br/>O huyohoy’s gugma;<br/>Humot Ka pa’s kahoyng merto,<br/>Ug †copher alang kanako,<br/>Ikaw ang Balsamo<br/>Gikan sa itaas.<br/>',NULL,16539,1);
INSERT INTO stanza VALUES('CB172','2','Matahum Ka’s labing tahum,<br/>Di puol tan-awon;<br/>Mapuno gyud ko’s kalipay,<br/>Makakita’s Imong dagway,<br/>Kasanag’s nawong Mo,<br/>Katahum! Ginoo.<br/>',NULL,16540,2);
INSERT INTO stanza VALUES('CB172','3','Di gyud igong pagsugot ko,<br/>Manlul’was, Agalon,<br/>Di ko buot magawasnon,<br/>Kondi’ andam, maunongon,<br/>Hangtud’s katapusan<br/>Ikaw alagaran.<br/>',NULL,16541,3);
INSERT INTO stanza VALUES('CB172','4','Di ko pul-an sa pag-awit,<br/>Ngalang labing tam-is;<br/>Awit sa tumang kalipay<br/>Sa sulod ko nidagayday;<br/>Kalag ko napuno<br/>Sa Imong kalipay.<br/>',NULL,16542,4);
INSERT INTO stanza VALUES('CB172','5','Di kahuma’g hisgut Nimo,<br/>Dagha’g ikaasoy;<br/>Pinitik’s kasingkasing Mo<br/>Malomong nagdani nako,<br/>Naghunghong, naglipay,<br/>“Maayo ang tanan.”<br/>',NULL,16543,5);
INSERT INTO stanza VALUES('CB175','1','Labing matahum,<br/>Ginoo sa tanan!<br/>Ikaw Anak sa Dios ug tawo!<br/>Ako Kang mahalon,<br/>Ug akong tahuron,<br/>Himaya Ka’g korona ko!<br/>',NULL,16544,1);
INSERT INTO stanza VALUES('CB175','2','Lunhawng sibsibanan,<br/>Kakahoyang katahum!<br/>Gibistehan’s kabulakan;<br/>Mas matahum’s Jesus,<br/>Labi nga maputli,<br/>Sa nagsubo nagpaawit!<br/>',NULL,16545,2);
INSERT INTO stanza VALUES('CB175','3','Mahayag ang Adlaw,<br/>Hayag pa gyud ang Bulan,<br/>Mga bitoon sa langit;<br/>Jesus mas mahayag,<br/>Putli pa’g kahayag,<br/>Kaysa mapagarbo’s anghel!<br/>',NULL,16546,3);
INSERT INTO stanza VALUES('CB175','4','Labing matahum,<br/>Sa yuta ug langit,<br/>Diha Kanimo mapalgan;<br/>Wa nay mas duol,<br/>Mas tahum, mas mahal,<br/>Kay sa akong Manluluwas.<br/>',NULL,16547,4);
INSERT INTO stanza VALUES('CB177','1','Halangdon gyud nga kalomo<br/>Ang naa’s Manlul’was;<br/>Gipurongan S’ya’s himaya,<br/>Baba puno’s grasya.<br/>',NULL,16548,1);
INSERT INTO stanza VALUES('CB177','2','Way ikatandi Kaniya,<br/>Sa mga anak’s tawo,<br/>Matahum’s tanang matahum,<br/>Sa langitnong panon.<br/>',NULL,16549,2);
INSERT INTO stanza VALUES('CB177','3','Utang kong kinabuhi N’ya,<br/>Tanan kong kalipay;<br/>Gipadaug’s kamatayon,<br/>Gil’was sa lubnganan.<br/>',NULL,16550,3);
INSERT INTO stanza VALUES('CB177','4','Gida’s Amahang puy-anan,<br/>Gipapahulay ko;<br/>Gipakita’s himaya N’ya,<br/>Kalipay gihingpit.<br/>',NULL,16551,4);
INSERT INTO stanza VALUES('CB177','5','Nadawat kadagaya N’ya,<br/>Pamatuod’s gugma,<br/>Kon may libong kasingkasing,<br/>Maimo, Ginoo.<br/>',NULL,16552,5);
INSERT INTO stanza VALUES('CB180','1','Jesus, malipayong nagsimba Nimo,<br/>Magdayeg Nimo nganha sa trono!<br/>Nabulahan, busa kami magsimba,<br/>Moila nga Ikaw ra gyuy angay!<br/>',NULL,16553,1);
INSERT INTO stanza VALUES('CB180','chorus','Ikaw ray angay! Ikaw ray angay!<br/>Daygon, kay Ikaw ra gyud ang angay!<br/>Nabulahan, busa kami magsimba,<br/>Moila nga Ikaw ra gyuy angay!<br/>',NULL,16554,2);
INSERT INTO stanza VALUES('CB180','2','Ikaw ang tinuod nga Dios ug tawo,<br/>Nagpaubos, nahimong Tagtubos;<br/>Kaliwat Ka’s babaye nga natawo,<br/>Nagtunob’s bitin, nagdugmok’s ulo!<br/>',NULL,16555,3);
INSERT INTO stanza VALUES('CB180','3','Magbubuhat ko Ikaw nagpaubos,<br/>Kay gilansang’s mga tawo sa krus!<br/>Gidumtan’s tawo, gisalikway pa sa Dios,<br/>Sa kopang mapait wa mosibog.<br/>',NULL,16556,4);
INSERT INTO stanza VALUES('CB180','4','Gidaug Mo bisan ang kamatayon,<br/>Kadaugan nga mahimayaon!<br/>Makapugong ba mi sa pagsugilon?<br/>Mananaug Ka sa kamatayon.<br/>',NULL,16557,5);
INSERT INTO stanza VALUES('CB181','1','Takus ang Cordero,<br/>Awit sa Iglesia;<br/>Pagdayeg nilanog’s langit,<br/>Takus Siya.<br/>Trono’g gahum magpasakop,<br/>Mag-awit’s matahum’ng tingog,<br/>Cordero takus, ang awit<br/>Nga makusog.<br/>',NULL,16558,1);
INSERT INTO stanza VALUES('CB181','2','Tanang banay, dila, nasud,<br/>Takus Siya;<br/>Magdunga’g awit’s kal’wasan,<br/>Takus Siya.<br/>Sama kakusog’s dalugdog,<br/>Ug baha nga nidahunog,<br/>Magsimba uban’s pagkurog,<br/>Takus Siya.<br/>',NULL,16559,2);
INSERT INTO stanza VALUES('CB181','3','Alpa’g awit magpadayon,<br/>Takus Siya;<br/>Sa sala grasya nidaghan,<br/>Takus Siya.<br/>Sa dugong mahal gilukat,<br/>Nasaag ’yang gipangita,<br/>Gidala N’ya sa himaya;<br/>Takus Siya.<br/>',NULL,16560,3);
INSERT INTO stanza VALUES('CB181','4','Mag-awit ug magpaabot,<br/>Takus Siya;<br/>Latas sa tanang pagsulay,<br/>Takus Siya.<br/>Awit nga labing matahum,<br/>Ni’ning tema magpadayon,<br/>Di gyud mahuma’g sugilon,<br/>Takus Siya.<br/>',NULL,16561,4);
INSERT INTO stanza VALUES('CB183','1','Magduyog ta sa pag-awit,<br/>Manuol sa trono;<br/>Kon may linibong dila pa,<br/>Usa ra ang tema:<br/>',NULL,16562,1);
INSERT INTO stanza VALUES('CB183','2','“Corderong nikayab takus<br/>Nga ituboy sa Dios!“<br/>Isinggit, “Cordero takus,“<br/>“Gipatay S’ya sa krus.”<br/>',NULL,16563,2);
INSERT INTO stanza VALUES('CB183','3','Takus Ka, modawat, Jesus,<br/>Sa himaya’g gahum;<br/>Daghan pang kabulahanan<br/>Angay nga maimo.<br/>',NULL,16564,3);
INSERT INTO stanza VALUES('CB183','4','Di madugay ituboy ta,<br/>Magmaya’g magdayeg,<br/>Ang tanan ubos sa langit<br/>Way hunong mag-awit.<br/>',NULL,16565,4);
INSERT INTO stanza VALUES('CB183','5','Tinubos nga kabuhatan,<br/>Magdayeg sa ngalan<br/>Sa naglingkod didto’s trono,<br/>Ug ngadto’s Cordero.<br/>',NULL,16566,5);
INSERT INTO stanza VALUES('CB187','1','Kadato Mo, O Ginoo,<br/>Gibugna sa gugma Mo!<br/>Kaugalingon Mo kadato,<br/>Gimahal’s espiritu ko.<br/>',NULL,16567,1);
INSERT INTO stanza VALUES('CB187','2','Ikaw ang Pulong, Dios mismo,<br/>Uban’s Dios sa sinugdan;<br/>Natawo’s unod, uban namo,<br/>Dios gipatin-aw Nimo.<br/>',NULL,16568,2);
INSERT INTO stanza VALUES('CB187','3','Ikaw ang tabernaculo,<br/>Himaya’s Dios nakita;<br/>Sa Dios Ikaw sab ang templo,<br/>Dios hingpit Mong giasoy.<br/>',NULL,16569,3);
INSERT INTO stanza VALUES('CB187','4','Bugtong Ka nga Anak sa Dios,<br/>Nagpahayag’s Amahan,<br/>Aron kami makabaton<br/>Sa kinabuhing diosnon.<br/>',NULL,16570,4);
INSERT INTO stanza VALUES('CB187','5','Anak Ka’s Tawo, sama namo,<br/>May samang kinaiya,<br/>Himoon ming mga anak,<br/>Magtubo’s gidak-on Mo.<br/>',NULL,16571,5);
INSERT INTO stanza VALUES('CB187','6','Cristo, Ginoo sa tanan,<br/>Sa Dios gidihogan Ka;<br/>Ikawng tanan, naa’s tanan,<br/>Alang sa Dios ug namo.<br/>',NULL,16572,6);
INSERT INTO stanza VALUES('CB187','7','Manluluwas Kang gilansang,<br/>Nag-ula’s dugo’g tubig,<br/>Aron sa Dios malukat mi,<br/>Masudlan’s kinabuhi.<br/>',NULL,16573,7);
INSERT INTO stanza VALUES('CB187','8','Jesus Ka nang gihimaya,<br/>M’oy nagkunsad kanamo<br/>Malangkubong Espiritu<br/>Uban sa nakab-ot Mo.<br/>',NULL,16574,8);
INSERT INTO stanza VALUES('CB187','9','Kahayag Ka’s kinabuhi<br/>Sa kangitngit naglamdag;<br/>Ang Dios maoy gisidlak Mo,<br/>Sa kasingkasing namo.<br/>',NULL,16575,9);
INSERT INTO stanza VALUES('CB187','10','Kinabuhi Ka nga diosnon,<br/>Nagbuhi’s espiritu;<br/>Nagl’was namo’s kamatayon,<br/>Ug kanamo naglig-on.<br/>',NULL,16576,10);
INSERT INTO stanza VALUES('CB187','11','Ikaw ang kamatuoran,<br/>Sibo’s kahimuot’s Dios;<br/>Nagdala Nimo kanamo,<br/>Aron masayrang sukod Mo.<br/>',NULL,16577,11);
INSERT INTO stanza VALUES('CB187','12','Dalan Ka sa kinabuhi,<br/>Sa himaya dad-on mi;<br/>Dalan sa realidad Mo<br/>Daling makapadaug.<br/>',NULL,16578,12);
INSERT INTO stanza VALUES('CB187','13','Ikaw sab ang pagkabanhaw,<br/>Maglamoy’s kamatayon;<br/>Sundon’s gahum’s pagkabanhaw,<br/>Ang krus among pas-anon.<br/>',NULL,16579,13);
INSERT INTO stanza VALUES('CB187','14','Corderong way ikasaway,<br/>Sa pagtubos namatay;<br/>Maghahatag’s Espiritu,<br/>Ipanganak mi pag-usab.<br/>',NULL,16580,14);
INSERT INTO stanza VALUES('CB187','15','Ikawng bitin nga tumbaga,<br/>Nagl’was namo’s dautan;<br/>Sa kahoy nagdugmok’s yawa,<br/>Alang namo giisa.<br/>',NULL,16581,15);
INSERT INTO stanza VALUES('CB187','16','Magbalantay, pultahan Ka,<br/>Makabiya na’s toril,<br/>May hingpit ’ming kagawasan<br/>Pag-ambit’s sibsibanan.<br/>',NULL,16582,16);
INSERT INTO stanza VALUES('CB187','17','Sama’s dolang, paghugas Mo,<br/>Kanunay nga naghinlo;<br/>Makapakig-ambitay Nimo,<br/>Mag-ambit’s kaluoy Mo.<br/>',NULL,16583,17);
INSERT INTO stanza VALUES('CB187','18','Ikaw ang batong nasiak,<br/>Nag-agay’s buhing tubig,<br/>Nag-inom ning lunhawng sapa,<br/>Kauhaw ko nagkuha.<br/>',NULL,16584,18);
INSERT INTO stanza VALUES('CB187','19','Atabay Ka nga langitnon,<br/>Buhing tubig sa dayon;<br/>Kinabuhi Mo mag-inom,<br/>Dili na gyud uhawon.<br/>',NULL,16585,19);
INSERT INTO stanza VALUES('CB187','20','Tinapay Ka’s kinabuhi,<br/>Kalan-ong magpatubo;<br/>Nagda’s tanan Mong kadato,<br/>Magpakaon’s espiritu.<br/>',NULL,16586,20);
INSERT INTO stanza VALUES('CB187','21','Ikaw among gininhawa,<br/>Hanggapon’s espiritu;<br/>Mabuhi mi tungod Nimo,<br/>Manunod’s kadato Mo.<br/>',NULL,16587,21);
INSERT INTO stanza VALUES('CB187','22','Ikaw ang lugas sa trigo,<br/>Nga namatay’g nabanhaw;<br/>Nagpalugwa’s daghang trigo<br/>Paghulma sa Lawas Mo.<br/>',NULL,16588,22);
INSERT INTO stanza VALUES('CB187','23','Langitnong punoan’s parras,<br/>Kami ang mga sanga;<br/>Magpabilin kami Nimo,<br/>Mag-ambit’s kadato Mo.<br/>',NULL,16589,23);
INSERT INTO stanza VALUES('CB187','24','Ikaw ang Pamanhonon nga<br/>Sa Lawas mangasawa;<br/>Kami Kanimo mausa,<br/>Sa himaya ug gugma.<br/>',NULL,16590,24);
INSERT INTO stanza VALUES('CB187','25','Hagdang nakita ni Jacob,<br/>Gibuksan Mo ang langit;<br/>Diha Nimo balay mi’s Dios,<br/>Yuta nadugtong’s langit.<br/>',NULL,16591,25);
INSERT INTO stanza VALUES('CB187','26','Ikawng dakong “AKO MAO,“<br/>Nagsangkap namo’s tanan;<br/>Matuman sa pagpa’mulos<br/>Ang tanang plano sa Dios.<br/>',NULL,16592,26);
INSERT INTO stanza VALUES('CB188','1','Anak Ka sa Dios, Ginoo,<br/>Hingpit N’yang pagpadayag;<br/>Diha Nimo Dios namulong<br/>Nganhi kanamo karon.<br/>',NULL,16593,1);
INSERT INTO stanza VALUES('CB188','2','Kasanag Ka’s ’yang himaya,<br/>Hulma’s ’yang pagkamao;<br/>Ikaw ngani ang Dios mismo,<br/>Hingpit N’yang sugilanon.<br/>',NULL,16594,2);
INSERT INTO stanza VALUES('CB188','3','Uniberso binuhat Mo,<br/>Ikaw gyud ang nagsapnay;<br/>Gitudlo’s Dios manununod’s<br/>Panulondong tinuod.<br/>',NULL,16595,3);
INSERT INTO stanza VALUES('CB188','4','Sa sala Ikaw naghinlo,<br/>Naglingkod Ka na’s trono,<br/>Naghulat nga mapasakop<br/>Tanan nga kaaway Mo.<br/>',NULL,16596,4);
INSERT INTO stanza VALUES('CB188','5','Ngalang labaw’s ngalan’s anghel,<br/>Napanunod Nimo’s Dios;<br/>Kanamo kinabuhi Ka,<br/>Kay Espiritu man gud.<br/>',NULL,16597,5);
INSERT INTO stanza VALUES('CB188','6','Gingharian iya’s katarung,<br/>Trono magbarug’s dayon;<br/>Dios nagdihog Nimo’s gugma,<br/>Wa gyuy pagkadaan Ka.<br/>',NULL,16598,6);
INSERT INTO stanza VALUES('CB188','7','Tawo Ka gayud nga tinuod,<br/>May kinaiya’s tawo;<br/>Namatay Ka alang namo,<br/>Maamo ang sukod Mo.<br/>',NULL,16599,7);
INSERT INTO stanza VALUES('CB188','8','Nasakop Mong tanang butang,<br/>Gipurongan’s himaya;<br/>Kapitan Ka’s kaluwasan,<br/>Sa pag-antus nahingpit man.<br/>',NULL,16600,8);
INSERT INTO stanza VALUES('CB188','9','Yawa Imo nang gilaglag,<br/>L’was na mi’s kamatayon;<br/>Gibalaan Mo man karon,<br/>Ug sa himaya dad-on.<br/>',NULL,16601,9);
INSERT INTO stanza VALUES('CB188','10','Gipaila Mo kanamo,<br/>Ang Ngalan sa Amahan;<br/>Nanguna’g awit’s Iglesia,<br/>Sa mga pagdayeg Niya.<br/>',NULL,16602,10);
INSERT INTO stanza VALUES('CB188','11','Ingon sa nagtukod’s balay,<br/>Labaw Ka man ni Moises;<br/>Apostol Kang sinugo’s Dios,<br/>Sa labawng dungog takus.<br/>',NULL,16603,11);
INSERT INTO stanza VALUES('CB188','12','Sa pahulay nakasulod<br/>Nimo Josueng tinuod;<br/>Hingpit Kang kal’wasan namo,<br/>Among sentro’s pagtoo.<br/>',NULL,16604,12);
INSERT INTO stanza VALUES('CB188','13','Langitnon Ka nga pahulay,<br/>Nagpuyo’s espiritu;<br/>Yuta Kang among kasudlan,<br/>Manunod’s kaayo Mo.<br/>',NULL,16605,13);
INSERT INTO stanza VALUES('CB188','14','Labaw sab Ka ni Aaron,<br/>Ikaw mismo m’oy halad,<br/>Labawng Sacerdote mosu’d’s<br/>Dapit labing balaan.<br/>',NULL,16606,14);
INSERT INTO stanza VALUES('CB188','15','Melquisedec Ikaw namo,<br/>May kinabuhing dayon,<br/>Magsilbe’s “tinapay’g bino,“<br/>Matag kinahanglanon.<br/>',NULL,16607,15);
INSERT INTO stanza VALUES('CB188','16','Ikawng mas maayong halad,<br/>Sa dayong Espiritu,<br/>Alang namo’s Dios gihalad,<br/>Maangkong kaayo Mo.<br/>',NULL,16608,16);
INSERT INTO stanza VALUES('CB188','17','Pakigsaad mas maayo<br/>Ang nahimo’s dugo Mo;<br/>Gihatag Mong bag-ong tugon,<br/>Sa mga tinubos Mo.<br/>',NULL,16609,17);
INSERT INTO stanza VALUES('CB188','18','Igo Ka g’yung Magbubuhat,<br/>Duna Ka g’yuy katakus;<br/>Batid sab nga Maghahatag,<br/>Tanan among nadawat.<br/>',NULL,16610,18);
INSERT INTO stanza VALUES('CB188','19','Takus Ka nga Tigpatuman,<br/>Ug Tigpataliwala;<br/>Kinabuhi’s pagkabanhaw,<br/>Paagi sa pagtuman.<br/>',NULL,16611,19);
INSERT INTO stanza VALUES('CB188','20','Nakasulod Ka na’s tabil,<br/>Among Mag-uuna Ka;<br/>Pinaagi’s kinabuhi,<br/>Modagan kami’s lumba.<br/>',NULL,16612,20);
INSERT INTO stanza VALUES('CB188','21','Mag-uugda’g Maghihingpit<br/>Ikaw’s among pagtoo;<br/>Sundon Ka’s gugma’g pagtoo,<br/>Magpasakop gyud Nimo.<br/>',NULL,16613,21);
INSERT INTO stanza VALUES('CB188','22','Di matupngan Ka, Ginoo,<br/>Sa pagkabililhon Mo;<br/>Pagkahingpit, kompleto Mo,<br/>Di masukod sa tawo.<br/>',NULL,16614,22);
INSERT INTO stanza VALUES('CB189','1','Pinalangga Kang Anak,<br/>Dagway Ka’s among Dios;<br/>Pahat’s mga balaan,<br/>Naambitan’s dugo.<br/>Sa mga binuhat’s Dios<br/>Ikaw ang Panganay;<br/>Ikawng nagbuhat’s tanan,<br/>Kay kami batonan.<br/>',NULL,16615,1);
INSERT INTO stanza VALUES('CB189','2','Una’s tanang binuhat,<br/>Uban’s tanang butang;<br/>Ikaw ang sentro’s tanan,<br/>Sa tanan nagsapnay.<br/>Ikawng bugtong sinugdan,<br/>Panganay’s nangamatay;<br/>Mahimayaong Ulo’s<br/>Iglesia nga Lawas.<br/>',NULL,16616,2);
INSERT INTO stanza VALUES('CB189','3','Nahamut-an’s Amahan,<br/>Puy-an Ka’s kahupngan;<br/>Aron mag-una’s tanan,<br/>Nga among makit-an.<br/>Gipasig-uli’s dugo,<br/>Tanan ngadto sa Dios,<br/>Ikahalad Mo kaming<br/>Balaan ngadto’s Dios.<br/>',NULL,16617,3);
INSERT INTO stanza VALUES('CB189','4','Kahupnganan’s Dios na’ Nimo,<br/>Ikaw ’yang misteryo;<br/>Kahibalo’g kaalam.<br/>Naa Nimong tanan.<br/>Paglaum Ka’s himaya,<br/>Nagpuyo Ka namo;<br/>Mahingpit diha Nimo<br/>Ug Dios makontento.<br/>',NULL,16618,4);
INSERT INTO stanza VALUES('CB189','5','Mga butang landong lang,<br/>Nagpadayag Nimo;<br/>Ikawng bugtong matuod,<br/>Nigamut mi Nimo.<br/>Kadato Mo pa’muslan,<br/>Makahupnganan mi;<br/>Daw Lawas Ikaw kuptan,<br/>Magtubo mi Nimo.<br/>',NULL,16619,5);
INSERT INTO stanza VALUES('CB189','6','Uban Nimo natago<br/>Kami diha sa Dios;<br/>Nagharing kalinaw Mo,<br/>Wa na makigbisug.<br/>Sa bag-ong tawong Lawas Mo,<br/>Tanan Ka sa tanan;<br/>Manlul’was malangkubon,<br/>Ikaw among tawgon.<br/>',NULL,16620,6);
INSERT INTO stanza VALUES('CB190','1','Samtang Ikaw gihandom ko,<br/>Gisimbang pagkamao Mo;<br/>Katingad-an, kadato Mo,<br/>Bililhon, hiligugmaon!<br/>',NULL,16621,1);
INSERT INTO stanza VALUES('CB190','chorus','Sibo gyud Ka’s kin’hanglan ko!<br/>Mag-awas ko sa pagdayeg!<br/>Pangandoy ko gitagbaw Mo,<br/>Sa pagsangkap naghingapin!<br/>',NULL,16622,2);
INSERT INTO stanza VALUES('CB190','2','Tinuod Ikaw Dios gayud,<br/>Dios nga kahayag ug gugma;<br/>Dios nga naamong kinabuhi,<br/>Nga naglipay namong tanan.<br/>',NULL,16623,3);
INSERT INTO stanza VALUES('CB190','3','Tinuod man nga tawo Ikaw,<br/>Malomo, maayo’g putli;<br/>Nakapahimuot sa Dios,<br/>Nagdaning S’ya’y higugmaon.<br/>',NULL,16624,4);
INSERT INTO stanza VALUES('CB190','4','Ulipon ’sab Ikawng ubos,<br/>Alang namo ngadto sa Dios;<br/>Nisugot bisa’g mamatay,<br/>Aron kami mangaluwas.<br/>',NULL,16625,5);
INSERT INTO stanza VALUES('CB190','5','Gawas ni’ni Ikaw Hari,<br/>Diha’s kinabuhi’g gugma,<br/>Gidihogan’s gahum sa Dios,<br/>Maghari mi uban Nimo.<br/>',NULL,16626,6);
INSERT INTO stanza VALUES('CB190','6','Samtang naghandom, Ginoo,<br/>Nagpa’mulos “pagkamao“;<br/>Sa gugma napa’muslan Ka,<br/>Ingon nga kami kapikas.<br/>',NULL,16627,7);
INSERT INTO stanza VALUES('CB191','1','“Kaliwat Ka sa babaye.“<br/>Natawo magsamad’s bitin;<br/>Dagway’s tawo gisul-ob Mo,<br/>Namatay sa pagdaug.<br/>Dios mismo nagpakatawo,<br/>Niambit’s unod, dugo,<br/>Namatay’s pagdugmok’s yawa,<br/>Ug gahum’s kamatayon.<br/>',NULL,16628,1);
INSERT INTO stanza VALUES('CB191','2','“Kaliwat Ka ni Abraham,“<br/>Gianak tungod’s saad,<br/>Kabulahan’s kanasuran<br/>Moabot suma’s saad;<br/>Una Ka pa ni Abraham,<br/>Kay Ikawng “AKO MAO,“<br/>Apan nakaliwat niya’g<br/>“Cordero” nga ’yang saad.<br/>',NULL,16629,2);
INSERT INTO stanza VALUES('CB191','3','“Kaliwat Ka man ni David,“<br/>Alang’s gingharian ug<br/>Balay sa Dios gipabangon,<br/>Gibutang Ka sa trono.<br/>Ikaw ang “Anak ni David,“<br/>Gitawag n’yang “Ginoo,“<br/>Kay “gamut” Ka n’ya’g tinubdan,<br/>Sa dayon “Ginoo’s tanan.”<br/>',NULL,16630,3);
INSERT INTO stanza VALUES('CB191','4','“Bata” tuod Kang gianak,<br/>Ginganla’g “Gamhanang Dios,“<br/>“Way Katapusang Amahan,“<br/>“Anak” nga gihatag namo.<br/>Gisaad nga kabulahan,<br/>Nag-agad sa pagtoo;<br/>“Oo” ug “Amen” Ka nila,<br/>Tanang sulod ug tuyo!<br/>',NULL,16631,4);
INSERT INTO stanza VALUES('CB193','1','Bililhon Ka, O Ginoo,<br/>Ikaw among tanan;<br/>Sa gagmay’g dagko nga butang,<br/>Tagbo Ka’s kin’hanglan.<br/>Pagkamao Mo gimahal,<br/>Gisimba’s espiritu,<br/>Sa nakitang kadato Mo,<br/>Daygon Ka, Ginoo.<br/>',NULL,16632,1);
INSERT INTO stanza VALUES('CB193','2','Propeta Kang namulong’s Dios,<br/>Daw Moises nagpadayag;<br/>Sa plano’s Dios aron kami,<br/>Magsubay niini.<br/>Daw Jonas gipadala’s Dios,<br/>Namatay’g nabuhi,<br/>Pinaagi ning ilhanan,<br/>Motoo mi Nimo.<br/>',NULL,16633,2);
INSERT INTO stanza VALUES('CB193','3','Propeta Kang gipabangon,<br/>Mosulti may gahum;<br/>Mahigugmaon daw Eliseo,<br/>Puno sa milagro.<br/>Isaias Kang puno’s grasya,<br/>Nagbugna’s Cristo’s Dios,<br/>Aron makaambit mi ni<br/>Cristong kinabuhi.<br/>',NULL,16634,3);
INSERT INTO stanza VALUES('CB193','4','Sacerdote Ka ngadto’s Dios,<br/>Alang gayud namo,<br/>Aaron nga gitawag’s Dios,<br/>Magsilbe kanamo.<br/>Gida’ mi Nimo’s Dios sa gugma,<br/>Labawng Sacerdote Ka;<br/>Gipangamuyo ngadto’s Dios,<br/>Giampingan’s kusog.<br/>',NULL,16635,4);
INSERT INTO stanza VALUES('CB193','5','Harianong Sacerdote<br/>Sa Dios nganhi namo,<br/>Sama Ka ni Melquisedec<br/>Nga ministro sa Dios.<br/>Tinapay’g bino dala Mo<br/>Sa kin’hanglan nagtagbo;<br/>Gidad-an Mo kami ug Dios<br/>Aron makapa’mulos.<br/>',NULL,16636,5);
INSERT INTO stanza VALUES('CB193','6','Hari Ka sama ni David,<br/>Tumong tinguha’s Dios;<br/>Nagpadayag’s tinguha N’ya,<br/>Sa kaaway nagbuntog.<br/>Di sa sungkod nga tawhanon<br/>Trono Mo gilig-on,<br/>Kondi’ maghari’s kagahum<br/>Alang’s Dios ug namo.<br/>',NULL,16637,6);
INSERT INTO stanza VALUES('CB193','7','Sama ni Haring Salomon,<br/>Nagharing malinawon;<br/>Nagmando uban’s kaalam,<br/>Ang Dios gibalayan.<br/>Di makita, naghari Ka<br/>Namo uban’s gugma,<br/>May adlawng Ikaw maghari<br/>Nga uban na kami.<br/>',NULL,16638,7);
INSERT INTO stanza VALUES('CB193','8','Bililhon Ka kay Propeta,<br/>Sacerdote, Hari;<br/>Kabililhon imantala<br/>Uban’s among gugma.<br/>Gimahal’ng pagkamao Mo<br/>Nadani mi Nimo;<br/>Magdayeg mi’g magpasalamat<br/>Hangtud’s eternidad.<br/>',NULL,16639,8);
INSERT INTO stanza VALUES('CB194','1','Sa Dios panghimatuod Ka,<br/>Labaw’s kasugoan;<br/>Sa kasugoan sa letra;<br/>Nahulagway gyud Ka.<br/>Kasugoan katin-awan<br/>Sa hulagway sa Dios;<br/>Apan Ikawng kamat’oran,<br/>Ang Dios naa Nimo.<br/>',NULL,16640,1);
INSERT INTO stanza VALUES('CB194','2','Arka sa panghimatuod,<br/>Hulagway sab Nimo;<br/>Gibutang kasugoan ra,<br/>Naang Dios Kanimo.<br/>Arka hinimo sa kahoy,<br/>Hinal-opan’s bulawan;<br/>Naghulagway nga tawo Ka,<br/>Nga sa Dios kasudlan.<br/>',NULL,16641,2);
INSERT INTO stanza VALUES('CB194','3','Tabernaculo Ka usab,<br/>Balaang puy-anan;<br/>Sa unod nagpakatawo,<br/>Grasya’g kamat’oran.<br/>Himaya’s Dios, diosnong Pulong,<br/>Kanimo masud-ong;<br/>Gugma’g kahayag’s pulong Mo<br/>Sa Dios nagsugilon.<br/>',NULL,16642,3);
INSERT INTO stanza VALUES('CB194','4','Templo maoy hulagway Mo;<br/>Balay Ikaw sa Dios;<br/>Puy-anan, magpadayag N’ya,<br/>Ipaambit Siya.<br/>Bisan gilaglag Ka’s yawa<br/>Ug namatay gayud,<br/>Sa pagkabanhaw nagtukod<br/>Labaw pa nga templo.<br/>',NULL,16643,4);
INSERT INTO stanza VALUES('CB194','5','Kahupnganan Mo ang syudad,<br/>Dagway’s Asawa Mo,<br/>Imong hingpit nga pagtubo,<br/>Diin Ka nagpuyo.<br/>Dios kahayag naa Nimo,<br/>Ikaw m’oy suga n’ya;<br/>Magsidlak pinaagi n’ya<br/>Sa Iyang himaya.<br/>',NULL,16644,5);
INSERT INTO stanza VALUES('CB194','6','Tabernaculo ug arka,<br/>Tipiganan’s sugo,<br/>Ang templo ug syudad usab,<br/>Lunlon, Ikaw ra gyud.<br/>Ikaw ang sentro’g utlanan,<br/>Tanan gyud sa tanan!<br/>Kanimo makit-ang Dios, tawo,<br/>Pagkabililhon Mo!<br/>',NULL,16645,6);
INSERT INTO stanza VALUES('CB195','1','Ikaw ang tanang halad<br/>Andam sa Dios namo;<br/>Tam-is, mahimayaon,<br/>Makahuloganon.<br/>Tinguha’s Dios nagtagbo,<br/>Nagtuman’s ’yang tuyo,<br/>Nagtagbaw usab namo,<br/>Sa gikinahanglan.<br/>',NULL,16646,1);
INSERT INTO stanza VALUES('CB195','2','Ikawng halad-sinunog,<br/>Giut-ot’s kalayo;<br/>Alang sa Dios kahumot,<br/>Nakapahimuot.<br/>Naglakaw’s presensya’s Dios,<br/>Sunod’s ’yang pagbuot;<br/>Halad Ka nga way apan,<br/>Nga ’yang katagbawan.<br/>',NULL,16647,2);
INSERT INTO stanza VALUES('CB195','3','Ikawng halad-kalan-on,<br/>May “lana’g incienso“;<br/>Balaan, pino, hingpit,<br/>Mahumot kaayo.<br/>Halad-sa-pakigdait,<br/>Among kadaitan,<br/>Uban’s Dios maambitan<br/>Sa tanang balaan.<br/>',NULL,16648,3);
INSERT INTO stanza VALUES('CB195','4','Halad Ka tungod’s sala,<br/>Nahimo Kang sala;<br/>Namatay sa pagtubos,<br/>Sa paglukat namo.<br/>Halad-tungod’s-paglapas,<br/>Nagpas-an sa sala,<br/>Nagtagbaw’s hustisya’s Dios,<br/>Kami mapasaylo.<br/>',NULL,16649,4);
INSERT INTO stanza VALUES('CB195','5','Ikawng halad-tinabyog,<br/>Cristo nga nabanhaw;<br/>Gidaug Mong kangitngit,<br/>Kamatayon, Hades.<br/>Ikawng halad-binayaw,<br/>Nikayab ngadto’s Dios;<br/>Balaang kalan-on Ka<br/>Sa langitnong dapit.<br/>',NULL,16650,5);
INSERT INTO stanza VALUES('CB196','1','Naghulagway tanan Nimo,<br/>Tanang timaan Ginoo;<br/>Landong Ka man kaniadto,<br/>Karon tinuod namo.<br/>Samtang kami namalandong,<br/>Nagtutok’s kahibulong,<br/>Pagkadato Mo, Ginoo,<br/>Ikaw among simbahon!<br/>',NULL,16651,1);
INSERT INTO stanza VALUES('CB196','2','Ikawng matuod nga Pasko,<br/>Gilabyan’s Dios tungod Nimo,<br/>Sa kaugalingon, pagtubos,<br/>Giusa mi Nimo’s Dios;<br/>Cordero’s Dios Kang nagtubos<br/>Pinaagi’s dugo Mo;<br/>Giaplikar namong dugo,<br/>Sa pagkaon Kanimo.<br/>',NULL,16652,2);
INSERT INTO stanza VALUES('CB196','3','Tinapay Ka gikan’s langit,<br/>Tinapay’s kinabuhi;<br/>Kon kan-on, masagol Nimo,<br/>Di na makasala pa.<br/>Cordero’g tinapay landong,<br/>Kinabuhi Ka namo,<br/>Magkaon mi Nimo’s talad,<br/>Mapa’muslang kadato.<br/>',NULL,16653,3);
INSERT INTO stanza VALUES('CB196','4','Ikaw ang Langitnong Manna,<br/>Ug sangkap’s adlaw-adlaw;<br/>Naglig-on ug nagtagbaw Ka<br/>Sa tanang kin’hanglanon.<br/>Buhing Bato usab Ikaw,<br/>Nasiak aron mag-agas;<br/>Sa buhing tubig mag-inom,<br/>Nga magkuha’s kauhaw.<br/>',NULL,16654,4);
INSERT INTO stanza VALUES('CB196','5','Ikaw ang Yuta’s Canaan,<br/>Habog, dato, maayo;<br/>Nag-agay’s gatas ug dugos<br/>Nga abunda kaayo.<br/>Magsimba sa kadato Mo,<br/>Makig-ambitay Nimo,<br/>Aron sa gugma mausa,<br/>Matukod nga balay Mo.<br/>',NULL,16655,5);
INSERT INTO stanza VALUES('CB197','1','O pagkamalangkubon Mo;<br/>Naa na mi Nimo—<br/>Pahat Ka nga andam sa Dios,<br/>Maamong tanan’s tanan.<br/>',NULL,16656,1);
INSERT INTO stanza VALUES('CB197','2','Kaalam Ka sa Dios namo,<br/>Nal’was tungod Nimo;<br/>Bugtong Ka nga paagi’s Dios,<br/>Among gisaligan.<br/>',NULL,16657,2);
INSERT INTO stanza VALUES('CB197','3','Pagkamatarung Ka namo,<br/>Sa tanan nagtagbo;<br/>Mamatarung, makompleto<br/>Kami diha Nimo.<br/>',NULL,16658,3);
INSERT INTO stanza VALUES('CB197','4','Pagkabalaan Ka namo,<br/>Mag-usab, magbag-o;<br/>Nabalaan kami Nimo,<br/>Masama sab Nimo.<br/>',NULL,16659,4);
INSERT INTO stanza VALUES('CB197','5','Katubsanan sab Ka namo,<br/>Magbaton’s dagway Mo;<br/>Mangausab unyang lawas,<br/>Uban Nimo magawas.<br/>',NULL,16660,5);
INSERT INTO stanza VALUES('CB197','6','Samtang naghandom mi Nimo,<br/>Nagpa’mulos Nimo,<br/>Dalia nang pagbalik Mo<br/>Di na mabulag Nimo.<br/>',NULL,16661,6);
INSERT INTO stanza VALUES('CB197','7','Katam-is nga natilawan,<br/>Pagkamao Mo dinhi,<br/>Mag-uban na unta Nimo,<br/>Hingpit Kang mapa’muslan.<br/>',NULL,16662,7);
INSERT INTO stanza VALUES('CB198','1','Kahoy Ka sa Kinabuhi,<br/>Sangkap’s kinabuhi;<br/>Mga bunga makatagbaw<br/>Sa among kagutom.<br/>',NULL,16663,1);
INSERT INTO stanza VALUES('CB198','2','Ikawng Punoang tinuod,<br/>Tinubdan’s kinabuhi;<br/>Kanimo nabuhi, nagpabilin,<br/>Ug nagpahulay mi.<br/>',NULL,16664,2);
INSERT INTO stanza VALUES('CB198','3','Ikaw kahoy nga Mansana,<br/>Bunga Mo makaon;<br/>Pagkatam-is gyud nga kan-on,<br/>Kalipay ang landong.<br/>',NULL,16665,3);
INSERT INTO stanza VALUES('CB198','4','Kahoy sab Kang makaayo,<br/>Sa kahoy nag-antus<br/>Alang namo gipatay didto<br/>Aron mi maayo.<br/>',NULL,16666,4);
INSERT INTO stanza VALUES('CB198','5','Naa Nimong kahupnganan’s Dios,<br/>Sanga Ka man sa Dios;<br/>Diha Nimo nadawat S’ya<br/>Realidad, grasya.<br/>',NULL,16667,5);
INSERT INTO stanza VALUES('CB198','6','Sanga Ka usab ni David,<br/>Aron matawo dinhi;<br/>Nakita diha Kanimo<br/>Ang tawong tinuod.<br/>',NULL,16668,6);
INSERT INTO stanza VALUES('CB198','7','Nanalingsing Kang Sanga’s Dios,<br/>Kinabuhing dayon;<br/>Sa gahum’s pagkabanhaw Mo,<br/>Wa nay kamatayon.<br/>',NULL,16669,7);
INSERT INTO stanza VALUES('CB198','8','Ikawng Bugsok nga nilutaw,<br/>“Wasay” ming nahulog;<br/>Sa gahum’s kinabuhi Mo,<br/>Gihaw-as’ kamatayon.<br/>',NULL,16670,8);
INSERT INTO stanza VALUES('CB198','9','Ikawng “Tanom nga Bantugan,“<br/>Datong naambitan,<br/>Samtang gihandom Ka dinhi,<br/>Amo Kang iwali!<br/>',NULL,16671,9);
INSERT INTO stanza VALUES('CB199','1','Ikaw ang Bato sa dayon,<br/>Nasiak alang nako;<br/>Espiritu Kang giinom,<br/>Nahiusa Ko Nimo.<br/>Batong malig-on kaayo,<br/>Kami gitukod didto;<br/>Nausa Nimo’s pagtubos,<br/>Wala nay makatarug.<br/>',NULL,16672,1);
INSERT INTO stanza VALUES('CB199','chorus','Pagkamao Mo, Ginoo,<br/>Hingpit nga alang namo,<br/>Bililhon, hiligugmaon,<br/>Magpa’mulos, maghandom.<br/>',NULL,16673,2);
INSERT INTO stanza VALUES('CB199','2','Bato nga daghang nisulay,<br/>Bililhon sa Dios ug tawo;<br/>Malig-on ug kasaligan,<br/>Kusog Mo katingad-an.<br/>Ikaw ang Bato nga buhi,<br/>Hatag sa Dios, pinili,<br/>Kanamo pagkagamhanan,<br/>Kinabuhi nga dayon.<br/>',NULL,16674,3);
INSERT INTO stanza VALUES('CB199','3','Ikaw ang Patukoranan,<br/>Dios nagbutang, malig-on;<br/>Ning lig-ong patukoranan<br/>Dunay kasegurohan.<br/>Para namo wa nay lain<br/>Nga patukoranan pa,<br/>Bugtong Kang patukoranan<br/>Hangtud sa kahangturan.<br/>',NULL,16675,4);
INSERT INTO stanza VALUES('CB199','4','Espirituhanong balay,<br/>Ikaw Batong pamag-ang,<br/>Judio ug mga Gentil<br/>Gitukod Mo pag-usa.<br/>Ikaw ’sab Ulohang Bato,<br/>Lugwa sa datong grasya,<br/>Among tabon ug himaya,<br/>Daygon’s kasingkasing ko.<br/>',NULL,16676,5);
INSERT INTO stanza VALUES('CB200','1','Adlaw’s pagkamatarung Ka,<br/>Silaw makaayo;<br/>Nagdala sa kadato Mo<br/>Kasanag’s nawong Mo.<br/>',NULL,16677,1);
INSERT INTO stanza VALUES('CB200','2','Malomong kaluoy sa Dios<br/>Nagsugong maghayag,<br/>Kanilang naa’s kangitngit,<br/>Magwa’s kamatayon.<br/>',NULL,16678,2);
INSERT INTO stanza VALUES('CB200','3','Buntag Ka nga way panganud,<br/>Naghayag Ka namo;<br/>Kami ang sagbut nga linghod,<br/>Nabuhi’s silaw Mo.<br/>',NULL,16679,3);
INSERT INTO stanza VALUES('CB200','4','Hiligugmaong silaw Mo,<br/>Hayag nagkakusog;<br/>Sa sulod namo nagdan-ag<br/>Hangtud’s kaudtohon.<br/>',NULL,16680,4);
INSERT INTO stanza VALUES('CB200','5','Naghayag sa kalisdanan,<br/>Init human’s ulan;<br/>Sa kaluoy ug gugma Mo,<br/>Naghayag gihapon.<br/>',NULL,16681,5);
INSERT INTO stanza VALUES('CB200','6','Bitoon Ka’s Kabugason,<br/>Ganti alang namo,<br/>Sa kangitngit maghayag Ka<br/>Sa tanang nahigugma.<br/>',NULL,16682,6);
INSERT INTO stanza VALUES('CB200','7','Pahigugmaa’s kahayag,<br/>Makakita’s layo;<br/>Magtukaw, maghulat Nimo,<br/>Bitoon’s Kabugason.<br/>',NULL,16683,7);
INSERT INTO stanza VALUES('CB203','1','Sa wa pang kapanahonan,<br/>Ug wa pang kabuhatan;<br/>Didto’s sabakan’s Amahan,<br/>Ikaw bugtong nga Anak.<br/>Gihatag Ka N’ya kanamo,<br/>Sa Imo gyung pagkadios,<br/>Aron ang ’yang kahupnganan<br/>Madayag’s Espiritu.<br/>',NULL,16684,1);
INSERT INTO stanza VALUES('CB203','2','Namatay Ka ug nabanhaw,<br/>Nahimo nga Panganay;<br/>Kinabuhi gihatag ug<br/>Naghimo’s mga anak.<br/>Pagsanay’s kinabuhi Mo,<br/>Kami mga igsoon;<br/>Mga hulad’s himaya Mo,<br/>Imong diosnong pagtubo.<br/>',NULL,16685,2);
INSERT INTO stanza VALUES('CB203','3','Kaniadto usang trigo<br/>Diha’s yuta namatay;<br/>Sa kamatayo’g pagkabanhaw<br/>Himaya Mo nisanay.<br/>Nangabuhi tungod Nimo,<br/>Nahimong daghang trigo;<br/>Gisagol’s usang tinapay,<br/>Nahimo nga Lawas Mo.<br/>',NULL,16686,3);
INSERT INTO stanza VALUES('CB203','4','Hingpit kami nga hulad Mo,<br/>Lawas, Pangasaw-onon,<br/>Pagpadayag, kahupnganan,<br/>Magpabilin gyud Nimo.<br/>Sumpay, pagtubo, pagkaylap,<br/>Kami’s kinabuhi Mo;<br/>Pagkahingkod, pag-awas Mo,<br/>Nausa Nimong Ulo.<br/>',NULL,16687,4);
INSERT INTO stanza VALUES('CB206','1','Tuboran S’ya, O Cristo,<br/>’Tabayng tam-is ka’yo;<br/>Buhing agay naimnan,<br/>Nagl’was kasub-anan.<br/>Kaluoy N’ya daw dagat,<br/>Labihan kalapad;<br/>Grasya N’ya igo gayud,<br/>Plano’s kaalam N’ya.<br/>',NULL,16688,1);
INSERT INTO stanza VALUES('CB206','2','Iya ko’s Hinigugma,<br/>Ug akoa Siya;<br/>Gida’ng makasasala<br/>Sa balay’s bino N’ya!<br/>Buhat N’ya gisaligan,<br/>Siya ray kadangpan;<br/>Magtago ako Niya,<br/>Kay Iyang ampingan.<br/>',NULL,16689,2);
INSERT INTO stanza VALUES('CB206','3','S’yang gitan-aw’s Asawa,<br/>Di ang biste niya;<br/>Tutokang Hari’s grasya,<br/>Di unsang himaya.<br/>Di’s koronang gihatag,<br/>Kondi’ sa gilansang;<br/>S’ya ang tanang himaya,<br/>Ug saliganan ko!<br/>',NULL,16690,3);
INSERT INTO stanza VALUES('CB207','1','Ginoo, matag handom ko<br/>Sa gugma’g grasya Mo,<br/>Nangandoy kong makita Ka<br/>Sa nawong gyud Nimo.<br/>',NULL,16691,1);
INSERT INTO stanza VALUES('CB207','2','Bisag naglakaw’s awaaw,<br/>Sa yuta’s kauhaw,<br/>Daghang kaaway ug lit-ag,<br/>Katunokang nagkatag.<br/>',NULL,16692,2);
INSERT INTO stanza VALUES('CB207','3','Apan nakitang giladmon,<br/>Sa gugmang takus daygon;<br/>Busa sa among katagbaw,<br/>Magdayeg, malipayon.<br/>',NULL,16693,3);
INSERT INTO stanza VALUES('CB207','4','Kinabuhi Ka’g Kalan-on,<br/>Pahulay, Kahayag;<br/>Matag handom bag-o gayud,<br/>Ang kalipayng hatag.<br/>',NULL,16694,4);
INSERT INTO stanza VALUES('CB207','5','Lig-ona ang espiritu,<br/>Magsunod gyud Nimo,<br/>Hangtud nawong Mo among makita,<br/>Didto sa himaya.<br/>',NULL,16695,5);
INSERT INTO stanza VALUES('CB208','1','Jesus, labing gihigugma,<br/>Tungod sa gugma Mo,<br/>Pasangpita sa ngalan Mo<br/>Bisan’s makalibo.<br/>',NULL,16696,1);
INSERT INTO stanza VALUES('CB208','chorus','Jesus, pabilin kanako,<br/>Bisan unsay mahitabo;<br/>Pahiyom Mo kalipay ko,<br/>Gihigugma ko Ikaw.<br/>',NULL,16697,2);
INSERT INTO stanza VALUES('CB208','2','Paghigugmang di kapugngan,<br/>Maoy kalipay ko;<br/>Daw kalayo ang gugma Mo,<br/>Nikaylap ning kalag.<br/>',NULL,16698,3);
INSERT INTO stanza VALUES('CB208','3','Kay Ikawng tanan sa tanan,<br/>Dungog ug kadato;<br/>Pangandoy’s kasingkasing ko,<br/>Kalig-on sa kalag.<br/>',NULL,16699,4);
INSERT INTO stanza VALUES('CB208','4','Adlaw’g gabi’ nagdilaab,<br/>Gugma Mo’s sulod ko;<br/>Biya sa yutan-ong gugma,<br/>Gisunog, giwala.<br/>',NULL,16700,5);
INSERT INTO stanza VALUES('CB208','5','Kahayag Ka sa kangitngit,<br/>Dinhi’s yuta, langit;<br/>Jesus, gugma ko’g bahandi,<br/>Way nasayud’s bili.<br/>',NULL,16701,6);
INSERT INTO stanza VALUES('CB208','6','Asa kutob kining gugma?<br/>Unsay makapugong?<br/>Gugma Mo nagkatam-is pa<br/>Karon sa gahapon.<br/>',NULL,16702,7);
INSERT INTO stanza VALUES('CB209','1','Kon mahunahunaan Ka,<br/>Mapuno’s katam-is;<br/>Apan mas tam-is pa unta,<br/>Kon nawong Mo makita.<br/>',NULL,16703,1);
INSERT INTO stanza VALUES('CB209','2','Way tingog nga makaawit,<br/>Madumdom’s pangisip,<br/>Ngalang labaw sa katam-is,<br/>Ngalan’s Manluluwas!<br/>',NULL,16704,2);
INSERT INTO stanza VALUES('CB209','3','Paglaum Ka’s naghinulsol,<br/>Kalipay’s maaghop,<br/>Maluloy-on Ka’s natumba!<br/>Maayo’s nangita!<br/>',NULL,16705,3);
INSERT INTO stanza VALUES('CB209','4','Sa nakakita, unsa Ka?<br/>Di gyud ikaasoy;<br/>Unsa ang gugma ni Jesus,<br/>Kita ray nasayud.<br/>',NULL,16706,4);
INSERT INTO stanza VALUES('CB209','5','Jesus! Ikaw ang kahayag!<br/>Tubod’s kinabuhi!<br/>Labaw’s tanang kalipay ko,<br/>Tanan nakong gusto.<br/>',NULL,16707,5);
INSERT INTO stanza VALUES('CB209','6','Walay laing makatagbaw<br/>Sa kauhaw’s kalag;<br/>O Buhing Tubod, Ikaw ra!<br/>Kay uban nauga.<br/>',NULL,16708,6);
INSERT INTO stanza VALUES('CB209','7','Jesus karon m’oy Kalipay,<br/>Ganti’s umalabot;<br/>Himaya ko Ikaw karon,<br/>Ug hangtud gyud’s dayon.<br/>',NULL,16709,7);
INSERT INTO stanza VALUES('CB215','1','Sa talad bag-ong gibuklad,<br/>Nia Ka uban Namo;<br/>Madaugon nga naglingkod,<br/>Ning bililhong kombira.<br/>Tanang kahadlok nawala,<br/>Ning mga panahona;<br/>Nagpauraray Kanimo,<br/>Naghunahuna Nimo.<br/>',NULL,16710,1);
INSERT INTO stanza VALUES('CB215','2','Nagkalipay’s kaduol Mo,<br/>Dinala’s Espiritu;<br/>Malinawong gihandom Ko<br/>Ang pag-ula Mo’s dugo.<br/>Gidawat tinapay’g kopa,<br/>Mga handumanan Mo;<br/>Lawas napikas, dugo Mong<br/>Giula, palandungon.<br/>',NULL,16711,2);
INSERT INTO stanza VALUES('CB215','3','Makita Ka ning timaan,<br/>Unsa gyud nga kalipay;<br/>Sa tinapay ug sa bino<br/>Nga maglig-on, maglipay!<br/>Nausa kami Kanimo<br/>O nabanhaw nga Ulo,<br/>Maong niinom mi’s kopa<br/>Ug niambit’s tinapay.<br/>',NULL,16712,3);
INSERT INTO stanza VALUES('CB215','4','Saad Mo katinuod gyud,<br/>Magtigum mi uban Ka;<br/>Magtigum ngani’s ngalan Mo<br/>Lami gyung mag-ambitay;<br/>Mas mahal pang gisaad Mo,<br/>Gihulat, mag-uban mi<br/>Sa nahamutangan Nimo,<br/>Hangtud gayud sa hangtud.<br/>',NULL,16713,4);
INSERT INTO stanza VALUES('CB220','1','Nagtutok mi’g natingala<br/>Sa timaan’s talad:<br/>Sa tinapay ug sa kopa,<br/>Plano’s Dios nakita.<br/>',NULL,16714,1);
INSERT INTO stanza VALUES('CB220','2','Naghulagway ang tinapay’s<br/>Langitnong kalan-on;<br/>Sa kamatayon Mo kami<br/>Nakaambit Nimo.<br/>',NULL,16715,2);
INSERT INTO stanza VALUES('CB220','3','Ang pahat, diosnon nga kopa,<br/>Hinimo’s dugo Mo;<br/>Panalangin nga nadawat,<br/>Ang tanan man sa Dios.<br/>',NULL,16716,3);
INSERT INTO stanza VALUES('CB220','4','Nag-ambitay sa tinapay,<br/>Sa pagkaon Nimo;<br/>Naghandom Nimo sa gugma,<br/>Ug nabusog Nimo.<br/>',NULL,16717,4);
INSERT INTO stanza VALUES('CB220','5','Kabulahan napa’muslan<br/>Pag-inom sa kopa;<br/>Malipayon nga naghandom,<br/>Hangtud nga lalinon.<br/>',NULL,16718,5);
INSERT INTO stanza VALUES('CB220','6','Kamatayon gipadayag,<br/>Sa pagkaon-inom Nimo;<br/>Pagmatuod Ikaw among<br/>Kinabuhi’g sangkap.<br/>',NULL,16719,6);
INSERT INTO stanza VALUES('CB220','7','Gihulat namo ang takna,<br/>Hingpit mapa’muslan Ka,<br/>Nabusog’s pagkaon Nimo,<br/>Simbahon’s dayon Ka.<br/>',NULL,16720,7);
INSERT INTO stanza VALUES('CB221','1','Sa tinapay ug sa kopa,<br/>Pagpasalamatan Ka;<br/>Pahimuslan Ka ning talad,<br/>Isip kombira’s gugma.<br/>Moambit mi sa tinapay<br/>Hulagway sa lawas Mo;<br/>Ug moinom sa bino nga<br/>Naghulagway’s dugo Mo.<br/>',NULL,16721,1);
INSERT INTO stanza VALUES('CB221','chorus','Balaan nga talad!<br/>Dili gyud matugkad!<br/>Kahulogan ni’ni lalum,<br/>Way pagkausab!<br/>',NULL,16722,2);
INSERT INTO stanza VALUES('CB221','2','Pinaagi’s kamatayon<br/>Gitubos kaming tanan;<br/>Aron ang kinabuhi Mo<br/>Maambitan sa tanan.<br/>Pinaagi sa pag-ambit<br/>Ning tinapay ug kopa,<br/>Kamatayon gimantala,<br/>Sa gugma gihandom Ka.<br/>',NULL,16723,3);
INSERT INTO stanza VALUES('CB221','3','Ning tinapayng nagtimaan’s<br/>Usang misticong lawas,<br/>Tanang bahin nag-ambitay,<br/>Sa usa nga bugkos ta.<br/>Ni’ning kopa’s panalangin,<br/>Nga gipanal’nginan ta,<br/>May panag-ambitay’s dugo,<br/>Sa tanan nga nitoo.<br/>',NULL,16724,4);
INSERT INTO stanza VALUES('CB221','4','Dayong pahat Ka, Ginoo,<br/>Dinhi natilawan na;<br/>Naghulat’s gingharian Mo,<br/>Ug sa Imong pag-anhi.<br/>Pag-anhi Mo’s gingharian,<br/>Uban’s mga nidaug,<br/>Mokaon Nimo pag-usab,<br/>Mapangasaw-onon Mo.<br/>',NULL,16725,5);
INSERT INTO stanza VALUES('CB222','1','Alang ning tinapay, Ginoo,<br/>Magpasalamat mi,<br/>Kay nakita ang plano Mo<br/>Sa mga misteryo.<br/>',NULL,16726,1);
INSERT INTO stanza VALUES('CB222','2','Tinapay nagsimbolo man’s<br/>Lawas Mong gitugyan,<br/>Aron maambitan namo<br/>Ang kinabuhi Mo.<br/>',NULL,16727,2);
INSERT INTO stanza VALUES('CB222','3','Gipikas ang Imong lawas,<br/>Aron makagawas<br/>Kinabuhi Mong maghimo<br/>Namong kapikas Mo.<br/>',NULL,16728,3);
INSERT INTO stanza VALUES('CB222','4','Ang tinapay nagsimbolo,<br/>Sa lawas Mong mistico,<br/>Buhi kami Nimong bahin,<br/>Sama Nimo’s hingpit.<br/>',NULL,16729,4);
INSERT INTO stanza VALUES('CB222','5','Bisan trigo kaming daghan,<br/>Usa ka tinapay;<br/>Ingon niana naghandom,<br/>Imo nga pakan-on.<br/>',NULL,16730,5);
INSERT INTO stanza VALUES('CB222','6','Pag-ambitay sa tinapay,<br/>Kami gibusog Mo;<br/>Makig-ambit’s tanang balaan,<br/>Ikaw pamatud-an.<br/>',NULL,16731,6);
INSERT INTO stanza VALUES('CB223','1','Sa talad’s Imong gugma,<br/>Naang tinapay’g kopa,<br/>Moambit ning ilhanan,<br/>Mabusog kaming tanan.<br/>Ikaw pasalamatan<br/>Ning kopa’s kabulahan,<br/>Kopa sa kaluwasan<br/>Naghatag’s Imong tanan.<br/>',NULL,16732,1);
INSERT INTO stanza VALUES('CB223','2','Kini dugong giula<br/>Alang sa among sala;<br/>Pakigsaad Mo namo,<br/>Panalangin naamo.<br/>Kopa’s kapungot, Ikaw<br/>Nag-inom alang namo,<br/>Kopa sa panalangin,<br/>Naangkon namong bahin.<br/>',NULL,16733,2);
INSERT INTO stanza VALUES('CB223','3','Ning bahin Dios naangkon,<br/>Nga nawa’ dihang Adam;<br/>Sa pag-ula’s dugo Mo<br/>Ang Dios na-among tanan.<br/>Kinabuhi’g kalinaw,<br/>Malig-ong katubsanan,<br/>Ug tanang giplano’s Dios,<br/>Ning bahin nabatonan.<br/>',NULL,16734,3);
INSERT INTO stanza VALUES('CB223','4','Diosnong kopang nag-awas,<br/>M’oy bahin namo’s dayon;<br/>Langitnon nga pagtilaw<br/>Sa kopang Dios naglaraw.<br/>Dinhi’s gugma moinom,<br/>O Ginoo, maghandom;<br/>Mag-ambit’s espiritu,<br/>Buhat Mo sa Calvario.<br/>',NULL,16735,4);
INSERT INTO stanza VALUES('CB224','1','Sa pag-ambit sa kopa,<br/>Pagdayeg di mapugngan;<br/>Kay dugong giula Mo<br/>Bililhon gyud kaayo.<br/>Dugo Mo bililhon gyud!<br/>Nagsulbad’s problema ko;<br/>Epektibo Mong dugo<br/>Sa kahadlok nagkuha.<br/>',NULL,16736,1);
INSERT INTO stanza VALUES('CB224','2','Ni’ning bililhong dugo<br/>Bag-ong tugon gihimo;<br/>Patukoranang lig-on,<br/>Alang ning pakigsaad.<br/>Gitubos kami sa Dios,<br/>Di sa sapi’g bulawan,<br/>Kondi’ sa Imong dugo,<br/>Nga gibutyag’s gugma Mo.<br/>',NULL,16737,2);
INSERT INTO stanza VALUES('CB224','3','Sa pagpasaylo’s sala<br/>Ang dugo Mo giula,<br/>Alang namo nagtagbo<br/>Sa gikin’hanglan sa Dios.<br/>Gihugasan Mo kami<br/>Sa dugo Mong nagputli,<br/>Konsensya nga giputli,<br/>Isilbe’s Dios nga buhi.<br/>',NULL,16738,3);
INSERT INTO stanza VALUES('CB224','4','Sa dugo nga naggahin,<br/>Nabalaan na kami;<br/>Sa dugong nagpreserba,<br/>Pamatud-ang balaan.<br/>Dugong nagpasig-uli,<br/>Nagmatarung kanamo;<br/>Sa dugo Mong nagtubos,<br/>Hingpit natagbaw ang Dios.<br/>',NULL,16739,4);
INSERT INTO stanza VALUES('CB224','5','Sa dugong giula’s krus,<br/>Napasig-uli mi’s Dios,<br/>Aron makadugtong N’ya<br/>Diha sa kadaitan.<br/>Pag-ambit sa dugo Mo,<br/>May kinabuhing dayon;<br/>Sa dugo’g kinabuhi,<br/>May pahulay’s kasamok.<br/>',NULL,16740,5);
INSERT INTO stanza VALUES('CB224','6','Dugo Mo nga gisablig<br/>Namulong sa maayo;<br/>Gikan’s ikot sa Yawa<br/>Nanalipod kanamo.<br/>Dugo Mong madaugon<br/>Sa kaaway nagbuntog;<br/>Makadaug na kami,<br/>Sa among magsusumbong.<br/>',NULL,16741,6);
INSERT INTO stanza VALUES('CB224','7','Sa dugo, mag-ambitay<br/>Sa tanang balaan Mo;<br/>Sa pagtabon niini<br/>Espiritu malig-on.<br/>Di g’yud namo maasoy<br/>Kabililhon’s dugo Mo;<br/>Kin’hanglang eternidad<br/>Pagmantala’s kaayo.<br/>',NULL,16742,7);
INSERT INTO stanza VALUES('CB226','1','Sa tinapay ug kopa,<br/>Patingang akoa Ka,<br/>Sa mga pulong’s gugma,<br/>Pasalamatan Ka.<br/>',NULL,16743,1);
INSERT INTO stanza VALUES('CB226','2','Kopa ug tinapay ra,<br/>Ning pagtoo nakita;<br/>Ilhanan’s Imong gugma,<br/>Pasalamatan Ka.<br/>',NULL,16744,2);
INSERT INTO stanza VALUES('CB226','3','Tungod sa Imong pulong,<br/>Sa Calvario nisud-ong,<br/>Gipaduol’s pagtoo,<br/>Pasalamatan Ka.<br/>',NULL,16745,3);
INSERT INTO stanza VALUES('CB226','4','Pulong nagpaalimyon’s<br/>Yanong mga timaan,<br/>Kalinaw nga hatag Mo,<br/>Pasalamatan Ka.<br/>',NULL,16746,4);
INSERT INTO stanza VALUES('CB226','5','Espiritu nag’dayag,<br/>Buot Mong handumon Ka<br/>Hangtud’s Imong pagbalik<br/>Pasalamatan Ka.<br/>',NULL,16747,5);
INSERT INTO stanza VALUES('CB226','6','Magtipik sa tinapay<br/>Tipo’s gikaon namo,<br/>Kanhi buhi’g namatay!<br/>Pasalamatan Ka.<br/>',NULL,16748,6);
INSERT INTO stanza VALUES('CB226','7','Kopa’s talad Mo imnon,<br/>Hangtud’s pagbalik Nimo,<br/>Kasingkasing dasigon,<br/>Pasalamatan Ka.<br/>',NULL,16749,7);
INSERT INTO stanza VALUES('CB226','8','Kay gipakita daan,<br/>Pagbalik di masayran,<br/>Alang’s himaya’g trono,<br/>Pasalamatan Ka.<br/>',NULL,16750,8);
INSERT INTO stanza VALUES('CB227','1','Sa tinapay ug sa kopa<br/>Nakita namatay Ka;<br/>Namalandong sa buhat Mo,<br/>Pag-antus Mo gimahal.<br/>Nagkabulag dugo’g lawas,<br/>Timaan’s kamatayon;<br/>O salamat, simbahon Ka,<br/>Sa awit halaran Ka.<br/>',NULL,16751,1);
INSERT INTO stanza VALUES('CB227','chorus','Ikaw ang nag-antus,<br/>Akoy nabulahan;<br/>Buhat sa pagtubos<br/>Gugmang daygon sa dayon!<br/>',NULL,16752,2);
INSERT INTO stanza VALUES('CB227','2','Ang dugong Imong giula<br/>Nagdala namo sa Dios,<br/>Di na gayud magbulag pa<br/>Kanamo gikan Niya.<br/>Himaya’g pagkamatarung<br/>Gitubag sa dugo Mo;<br/>Sa kamatayon Mo, Jesus,<br/>Makapabilin mi’s Dios!<br/>',NULL,16753,3);
INSERT INTO stanza VALUES('CB227','3','Labing balaan nabuksan<br/>Sa paggisi Mo’s tabil,<br/>Gikuha na ang nag-ulang,<br/>Trono’s grasya kadangpan.<br/>Grasya’g kaluoy nagtagbo<br/>Panahon’s pangin’hanglan,<br/>Daw buhing tubig nainom;<br/>Sa Dios mismo nabusog.<br/>',NULL,16754,4);
INSERT INTO stanza VALUES('CB227','4','Gitubos man Nimo kami,<br/>Mahimong sacerdote;<br/>Katam-is sa Dios ambitan,<br/>Pagtuman’s katungdanan.<br/>Unsang kaluoy naako,<br/>Gikan’s pagkamatay Mo;<br/>Way pag-undang handumon ko<br/>Hangtud mag-inom didto.<br/>',NULL,16755,5);
INSERT INTO stanza VALUES('CB228','1','Kombira ni’s gugma,<br/>Sa nagl’was nga grasya,<br/>Magkaon’s tinapay’g kopa,<br/>Among handumon Ka.<br/>',NULL,16756,1);
INSERT INTO stanza VALUES('CB228','2','Nia tanang bisita,<br/>Naglaum, masayran<br/>Sekreto’s Imong Amahan,<br/>Grasya Mo mailhan.<br/>',NULL,16757,2);
INSERT INTO stanza VALUES('CB228','3','Tanlag nga naputli,<br/>Buot nga masayud’s<br/>Katam-is sa kinabuhi,<br/>Kahingpit’s gugma Mo.<br/>',NULL,16758,3);
INSERT INTO stanza VALUES('CB228','4','Dugo alang’s sala,<br/>Simbolong nakita;<br/>Gibating patinga’s sulod,<br/>Nga mahal mi Nimo.<br/>',NULL,16759,4);
INSERT INTO stanza VALUES('CB228','5','Kon matam-is kining<br/>Pasiklap lang’s gugma,<br/>Unsa kahang makalipay,<br/>Pahiyom makita?<br/>',NULL,16760,5);
INSERT INTO stanza VALUES('CB228','6','Makita Ka’s nawong,<br/>Masama mi Nimo,<br/>Imantala’s katuigan,<br/>Grasyang kahibudngan.<br/>',NULL,16761,6);
INSERT INTO stanza VALUES('CB233','1','Katingad-an nga misteryo,<br/>Ikaw nahiusa nako,<br/>Ikaw nia’s akong sulod,<br/>Ako naa sa sulod Mo!<br/>',NULL,16762,1);
INSERT INTO stanza VALUES('CB233','2','Gihatag ang Imong lawas,<br/>Aron makaambit Nimo;<br/>Kanako dugo giula,<br/>Aron magawas sa sala.<br/>',NULL,16763,2);
INSERT INTO stanza VALUES('CB233','3','Pinaagi’s pagkabanhaw<br/>Nahimo Kang Espiritu;<br/>Aron mapuno ko Nimo,<br/>Maako ang kadato Mo.<br/>',NULL,16764,3);
INSERT INTO stanza VALUES('CB233','4','Nakita namo pag-usab<br/>Ang gugma Mo ning simbolo;<br/>Magpasalamat’s plano Mo,<br/>Kasakit Mo palandongon.<br/>',NULL,16765,4);
INSERT INTO stanza VALUES('CB233','5','Nagpa’mulos’ katam-is Mo,<br/>Sa pagkaon ug pag-inom;<br/>Dawaton Ka’s espiritu,<br/>Kami mokaon Kanimo.<br/>',NULL,16766,5);
INSERT INTO stanza VALUES('CB233','6','Nangandoy mi nga labi pang<br/>Mokaon-inom Kanimo;<br/>Hangtud mapuno mi Nimo,<br/>Paghandom gyud kana namo.<br/>',NULL,16767,6);
INSERT INTO stanza VALUES('CB241','1','Kabulahanan ug kadungganan<br/>Ug ang himaya<br/>Alang Kanimo.<br/>Kabulahanan ug kadungganan,<br/>Karon ug sa dayon.<br/>Daygon Siya!<br/>Sa tanang balaan.<br/>Daygon Siya<br/>Karon ug sa dayon.<br/>Hallelujah!<br/>Kabulahanan ug kadungganan<br/>Ug ang himaya<br/>Alang Kanimo.<br/>Kabulahanan ug kadungganan,<br/>Karon ug sa dayon.<br/>',NULL,16768,1);
INSERT INTO stanza VALUES('CB242','1','Karon ang Espiritu sa Dios<br/>Espiritu na ni Jesus,<br/>Dios-tawong namatay ug nabanhaw,<br/>Nikayab ug gihimaya.<br/>',NULL,16769,1);
INSERT INTO stanza VALUES('CB242','2','Gikan ni’nang Jesus nisulod<br/>Ang Espiritu kanato,<br/>Aron ang realidad Niya<br/>Masinati na nato.<br/>',NULL,16770,2);
INSERT INTO stanza VALUES('CB242','3','Naang elemento’s Dios, tawo<br/>Sa Espiritu ni Jesus,<br/>Pagkinabuhi’s tawo naa N’ya.<br/>Nasakot’s himaya’s Dios.<br/>',NULL,16771,3);
INSERT INTO stanza VALUES('CB242','4','Pag-antus sa pagkatawo,<br/>Gahum sa kamatayon,<br/>Pagkabanhaw ug paghari sab,<br/>Na’s gininhawa’s Espiritu.<br/>',NULL,16772,4);
INSERT INTO stanza VALUES('CB242','5','Naglihok ni’ning tanan<br/>Ang Espiritu N’ya kanato,<br/>Sa pagdihog Niya maato<br/>Ang kadato ni Cristo.<br/>',NULL,16773,5);
INSERT INTO stanza VALUES('CB242','6','Espiritung Jesus naglangkob<br/>Sa dagko ug gagmay sab;<br/>Malangkubon nga nagbuhat,<br/>Ma-tanan ang Dios nato.<br/>',NULL,16774,6);
INSERT INTO stanza VALUES('CB243','1','Espiritu’s Dios mao si Cristo,<br/>Espiritu sa realidad;<br/>Nagpuyo’s sulod aron si Cristo<br/>Kanako mahimong tinuod.<br/>',NULL,16775,1);
INSERT INTO stanza VALUES('CB243','2','Cristo maoy pagkalawas sa Dios,<br/>Nagpadayag Dios kinabuhi;<br/>Espiritu mao sab kang Cristo,<br/>Nga S’ya ang labawng kinabuhi.<br/>',NULL,16776,2);
INSERT INTO stanza VALUES('CB243','3','Kahupnganan sa Dios nga Amahan,<br/>Gipakalawas dihang Cristo,<br/>Ug ang tanang kadato sa Anak,<br/>Sa Espiritu realidad.<br/>',NULL,16777,3);
INSERT INTO stanza VALUES('CB243','4','Anaa sa Anak ang Amahan,<br/>Espiritu mao ang Anak;<br/>Amahan sa Anak nahiusa<br/>Espiritu nausa’s Anak.<br/>',NULL,16778,4);
INSERT INTO stanza VALUES('CB243','5','Kon lig-onon ta sa Espiritu,<br/>Magbalay’s kasingkasing’s Cristo,<br/>Kahupnganan ug gugma’s Amahan,<br/>Magpuno’s atong kahiladman.<br/>',NULL,16779,5);
INSERT INTO stanza VALUES('CB243','6','Dihang Cristo Amahan naato,<br/>Nadawat S’ya nga atong tanan;<br/>Cristo nasinati’s Espiritu,<br/>Nga kinabuhi ta ug tanan.<br/>',NULL,16780,6);
INSERT INTO stanza VALUES('CB243','7','Sa diosnong realidad, Ginoo,<br/>Pun-a kami’s Espiritu Mo,<br/>Aron mapuno kami Kanimo,<br/>Magmatuod sa kadato Mo.<br/>',NULL,16781,7);
INSERT INTO stanza VALUES('CB244','1','Espiritu Santo karon,<br/>Espiritu’s kinabuhi,<br/>Gibuhi ta’g gipahaum,<br/>Sa plano’s Dios mahiuyon.<br/>',NULL,16782,1);
INSERT INTO stanza VALUES('CB244','2','Agay’s kinabuhi sangkap,<br/>Tubig magkuha’s kauhaw;<br/>Cristo gipaambit nako,<br/>Kagutom ko ’yang gitagbaw.<br/>',NULL,16783,2);
INSERT INTO stanza VALUES('CB244','3','Kahayag S’ya’s kinabuhi,<br/>Sa kangitngit m’oy nagbugaw;<br/>Hatag nga Cristo kahayag,<br/>Gabii gihimong adlaw.<br/>',NULL,16784,3);
INSERT INTO stanza VALUES('CB244','4','Sa gahum Siya naglig-on,<br/>Sa atong tawo sa sulod;<br/>Cristo gipaambit kusog,<br/>Alang’s Dios naglihok’s sulod.<br/>',NULL,16785,4);
INSERT INTO stanza VALUES('CB244','5','Sa balaod’s kinabuhi,<br/>Nagpagawas nato’s sala;<br/>Ug sa diosnong kinaiya,<br/>Nagbuot nato sa sulod.<br/>',NULL,16786,5);
INSERT INTO stanza VALUES('CB244','6','Espiritu’s kinabuhi,<br/>Pina’gi nato namunga,<br/>Sa ka’yo’s Dios nagpakita,<br/>Cristo gipaambit’s uban.<br/>',NULL,16787,6);
INSERT INTO stanza VALUES('CB244','7','Espiritu sige’g hatag<br/>Sa kinabuhing mag-usab;<br/>Sulodnong bahin gibag-o,<br/>Magpasama nakong Cristo.<br/>',NULL,16788,7);
INSERT INTO stanza VALUES('CB244','8','Pun-a sa Espiritu Mo,<br/>Espiritu’s kinabuhi;<br/>O suropi ko pag-ayo,<br/>Hangtud mapuno Kanimo.<br/>',NULL,16789,8);
INSERT INTO stanza VALUES('CB250','1','Pagtubod, atabay;<br/>Tubig paagaya;<br/>Kalota, Ginoo<br/>Ang nag-ulang nako.<br/>',NULL,16790,1);
INSERT INTO stanza VALUES('CB250','2','Bato nasiak na,<br/>Buhing tubig—agay,<br/>Apan’s kasingkasing<br/>Di na makaagay.<br/>',NULL,16791,2);
INSERT INTO stanza VALUES('CB250','3','Mag-ampo’s pagkalot<br/>Sa akong kahugaw;<br/>Hangtud mahubaran<br/>Ang Espiritu Mo.<br/>',NULL,16792,3);
INSERT INTO stanza VALUES('CB250','4','Di na siakon pa<br/>Pag-usab ang Bato,<br/>Kondi’ kaluton lang,<br/>Tubig patuboron.<br/>',NULL,16793,4);
INSERT INTO stanza VALUES('CB250','5','Labing kin’hanglan ko<br/>Pun-on’s Espiritu;<br/>Aron buhing tubig<br/>Sa sulod magtubod.<br/>',NULL,16794,5);
INSERT INTO stanza VALUES('CB250','6','Kaluton gyud hangtud<br/>Wala na’y magsampong;<br/>Buhing pagpamulong<br/>Sa sulod moagay.<br/>',NULL,16795,6);
INSERT INTO stanza VALUES('CB250','7','Pagtubod, atabay;<br/>Tubig paagaya;<br/>Kalota, Ginoo<br/>Ang nag-ulang nako.<br/>',NULL,16796,7);
INSERT INTO stanza VALUES('CB251','1','Suba sa buhing tubig<br/>Niagay gikan’s trono;<br/>Nag-awas nga panalangin,<br/>Gikan lamang ni Jesus.<br/>',NULL,16797,1);
INSERT INTO stanza VALUES('CB251','chorus','Suba sa buhing tubig,<br/>Suba sa kinabuhi;<br/>Gikan Nimo, Manluluwas,<br/>Paagia kanako.<br/>',NULL,16798,2);
INSERT INTO stanza VALUES('CB251','2','Umari ang giuhaw,<br/>Dagaya kining sangkap,<br/>Tubig daw kristal masihag,<br/>Mapalit Mo way bayad.<br/>',NULL,16799,3);
INSERT INTO stanza VALUES('CB251','3','Hinloi, Manluluwas ko,<br/>Himoang sandayong Mo;<br/>Basyoha, pun-a’g gamita,<br/>Ug Kanimo pasugta.<br/>',NULL,16800,4);
INSERT INTO stanza VALUES('CB251','4','Sa ingon lang niana<br/>Moagayng mga suba;<br/>Mahibaloan sa uban<br/>Ang Imong kahupnganan.<br/>',NULL,16801,5);
INSERT INTO stanza VALUES('CB251','5','Ihalad ko ang tanan<br/>Sa Imo nga tiilan;<br/>Bisan unsa, bisan asa,<br/>Maangay’ng mosilbe N’ya.<br/>',NULL,16802,6);
INSERT INTO stanza VALUES('CB255','1','Ginhawai’s Espiritu,<br/>Tudloi’g hanggap Nimo;<br/>Tabangi ko sa paghabwa<br/>Sa sala’g kaugalingon.<br/>',NULL,16803,1);
INSERT INTO stanza VALUES('CB255','chorus','Giginhawang kasub-anan,<br/>Ug ang sala ko;<br/>Gihanggap kahupnganan Mo<br/>Nganhi’s sulod ko.<br/>',NULL,16804,2);
INSERT INTO stanza VALUES('CB255','2','Kinabuhi giginhawa,<br/>Aron mapuno Nimo;<br/>Kusog ba’g kaluyahon ko,<br/>Ikaw ray hanggapon ko.<br/>',NULL,16805,3);
INSERT INTO stanza VALUES('CB255','3','Masal-anong kinaiya,<br/>Giginhawa pagawas;<br/>Gihanggap ang paghinlo Mo<br/>Kinabuhi napalgan.<br/>',NULL,16806,4);
INSERT INTO stanza VALUES('CB255','4','Giginhawang kasub-anan,<br/>Diha sa Imong dughan;<br/>Gihanggap ang paglipay Mo,<br/>Kalinaw ug pahulay.<br/>',NULL,16807,5);
INSERT INTO stanza VALUES('CB255','5','Giginhawang balatian,<br/>Imo kining gipas-an;<br/>Gihanggap ang pag-ayo Mo,<br/>Saad kanunayng bag-o.<br/>',NULL,16808,6);
INSERT INTO stanza VALUES('CB255','6','Giginhawang pangandoy ko,<br/>Sa namati Mong dunggan;<br/>Gihanggap ang mga tubag,<br/>Nagwa’s mga katahap.<br/>',NULL,16809,7);
INSERT INTO stanza VALUES('CB255','7','Gihanggap Ka matag gutlo,<br/>Nabuhi ako Nimo;<br/>Matag ginhawa, Ginoo,<br/>Ginhawai’s Esp’ritu.<br/>',NULL,16810,8);
INSERT INTO stanza VALUES('CB256','1','Huypi na, Ginoo, samtang naghulat mi,<br/>Mahigawas kami, sa hangin Mo huypi,<br/>Huyopi hangtud madasig mi’g mabuhi,<br/>O Ginoo huypi kami!<br/>',NULL,16811,1);
INSERT INTO stanza VALUES('CB256','chorus','Huyopi na kami karon!<br/>Huypi na ang katulogon!<br/>Huyopi ang among<br/>Pagsibog katapul,<br/>O huypi na mi, Ginoo!<br/>',NULL,16812,2);
INSERT INTO stanza VALUES('CB256','2','Huypi’s diosnong gugma ug padilaaba,<br/>Ginhawai’s langit ang amo nga kalag;<br/>Huyping kawalay pagtagad’s usag usa,<br/>O huypi na, O Ginoo!<br/>',NULL,16813,3);
INSERT INTO stanza VALUES('CB256','3','Huypi’s gahum Mo, dasigang espiritu,<br/>Huypi, buhia ug pun-a’s tinguha Mo;<br/>Huypi hangtud magdilaab kami’s bug-os,<br/>O huypi na, O Ginoo!<br/>',NULL,16814,4);
INSERT INTO stanza VALUES('CB257','1','Huypan Mo unta, Ginoo,<br/>Sa hanging langitnon!<br/>Gamhanang magdasig namo,<br/>Pakit-on Mo’s gahum.<br/>',NULL,16815,1);
INSERT INTO stanza VALUES('CB257','chorus','Pakunsara na, Ginoo,<br/>Ang Espiritu Mo!<br/>Hatagan Mo’s buhing agay,<br/>Modaug kanunay.<br/>',NULL,16816,2);
INSERT INTO stanza VALUES('CB257','2','Espiritu nga naggahum,<br/>Huyop makatangtang;<br/>Ginhawai’s Espiritu,<br/>Makaambit Nimo.<br/>',NULL,16817,3);
INSERT INTO stanza VALUES('CB257','3','Kadato sa Espiritu<br/>Pito na ka pilo;<br/>Makasinati mi’s bug-os<br/>Sa Tulo-usang Dios.<br/>',NULL,16818,4);
INSERT INTO stanza VALUES('CB264','1','Madaugon nga gugma Mo<br/>Gibubo’s kalag ko;<br/>Ako di na gyud matarug,<br/>Mogamut na sa Dios,<br/>Mogamut na sa Dios.<br/>',NULL,16819,1);
INSERT INTO stanza VALUES('CB264','2','Diosnong kalayo sa sulod,<br/>Way hunong magsiga;<br/>Tinguha kong mga bukid,<br/>Tunawon, sunogon,<br/>Tunawon, sunogon.<br/>',NULL,16820,2);
INSERT INTO stanza VALUES('CB264','3','Kalayo sa Pentecostes,<br/>Sala ko ut-ota!<br/>M’oy tawag ko’s Espiritu,<br/>Sunoga na ako,<br/>Sunoga na ako.<br/>',NULL,16821,3);
INSERT INTO stanza VALUES('CB264','4','O kalayo nga tig-ulay<br/>Hayaging kalag ko;<br/>Kinabuhi ipakaylap<br/>Sa matag bahin ko,<br/>Sa matag bahin ko.<br/>',NULL,16822,4);
INSERT INTO stanza VALUES('CB264','5','Kalag ko nga mabalhinon,<br/>Lig-onon Mo karon;<br/>Cristo maoy akong tanan,<br/>Bug-os nang gugma ko,<br/>Bug-os nang gugma ko.<br/>',NULL,16823,5);
INSERT INTO stanza VALUES('CB265','1','Kon nasabligan na’s dugo,<br/>Naa gyud ang pagdihog;<br/>Kita sa Dios makatandog,<br/>May pakig-ambitay gyud.<br/>',NULL,16824,1);
INSERT INTO stanza VALUES('CB265','2','Dugo, simbolo’s pagtubos,<br/>Naghinlo’s tanang sala;<br/>Dihog, simbolo’s Esp’ritu,<br/>Nagdala’s Dios ngadto’s tawo.<br/>',NULL,16825,2);
INSERT INTO stanza VALUES('CB265','3','Dugo, namulong’s buhat’s Dios,<br/>Dihog, kon unsa Siya;<br/>Sa buhat ug Persona N’ya,<br/>Nasagol ang Dios nato.<br/>',NULL,16826,3);
INSERT INTO stanza VALUES('CB265','4','Sa dugo sa katubsanan,<br/>Sa sambog nahinloan;<br/>Sa dihog sa Espiritu,<br/>Ang Dios napahimuslan.<br/>',NULL,16827,4);
INSERT INTO stanza VALUES('CB265','5','Nakuptang pagkausa’s Dios,<br/>Sa paghinlo’g pagdihog;<br/>Ang Dios hingpit nga naato,<br/>Tungod’s dihog ug dugo.<br/>',NULL,16828,5);
INSERT INTO stanza VALUES('CB265','6','Sa pagtoo angkonon ta<br/>Ang paghinlo sa dugo;<br/>Ug ang pagdihog sugton ta,<br/>Makalakaw uban’s Dios.<br/>',NULL,16829,6);
INSERT INTO stanza VALUES('CB265','7','Dios maghayag, masayud ta,<br/>Masinating Dios, gugma,<br/>Magtubo’s kinabuhi’s Dios,<br/>Magmatuod’s gahum N’ya.<br/>',NULL,16830,7);
INSERT INTO stanza VALUES('CB266','1','Diosnong dihog nagpuyo nako,<br/>Sa tanan m’oy nagtudlo;<br/>Nagda’ kanunay nga mabuhi ko<br/>Sa presensya’s Ginoo.<br/>',NULL,16831,1);
INSERT INTO stanza VALUES('CB266','chorus','Sa espiritu ko may dihog,<br/>Nagdihog, nagpuyo’g<br/>nagtudlo sa tanan;<br/>Sa espiritu ko may dihog,<br/>Nagtudlo sa tanang butang.<br/>',NULL,16832,2);
INSERT INTO stanza VALUES('CB266','2','Lihok kini sa Espiritu,<br/>Daw lunsayng dihog’s grasya;<br/>Gibasi sa pagsablig sa dugo,<br/>Ug kini molungtad gyud.<br/>',NULL,16833,3);
INSERT INTO stanza VALUES('CB266','3','Dihog sa pagkamao sa Dios,<br/>Masinati S’ya’s sulod;<br/>Aron masuropan Niya ako<br/>Sa Iyang elemento.<br/>',NULL,16834,4);
INSERT INTO stanza VALUES('CB266','4','Sa dihog sa kinabuhi N’ya,<br/>Mabuhi’s pakig-ambit;<br/>Maglakaw’s kahayag’s kamat’oran,<br/>Gugma N’ya pamatud-an.<br/>',NULL,16835,5);
INSERT INTO stanza VALUES('CB268','1','Daygon Ka, O Manluluwas,<br/>Gikuptan ko’s gugma Mo;<br/>Gil’was, gihinl’an, gipuno,<br/>Aron masandayong Mo.<br/>',NULL,16836,1);
INSERT INTO stanza VALUES('CB268','chorus','Sandayong lang, O Agalon,<br/>Apan puno’s grasya Mo,<br/>Agi namo, magamit mi,<br/>Matag takna ug dapit.<br/>',NULL,16837,2);
INSERT INTO stanza VALUES('CB268','2','Sandayong lang’s kabulahan,<br/>Sa tanan nga giuhaw;<br/>Suginlan’s kal’wasang hingpit,<br/>Ang gugma Mo isulti.<br/>',NULL,16838,3);
INSERT INTO stanza VALUES('CB268','3','Basyoha aron pun-on Mo,<br/>Ma-hinlong sudlanan Mo;<br/>Way kusog gawas’ hatag Mo,<br/>Uban sa matag sugo.<br/>',NULL,16839,4);
INSERT INTO stanza VALUES('CB268','4','Saksi’s grasyang nagl’was nako,<br/>Sa sala’g kaugalingon;<br/>Gilukat aron maangkon<br/>Sudli na’s kahupong Mo.<br/>',NULL,16840,5);
INSERT INTO stanza VALUES('CB268','5','O Ginoo, pun-a ako<br/>Sa Imong Espiritu;<br/>Aron gikan’s akong sulod<br/>Buhing tubig magtubod.<br/>',NULL,16841,6);
INSERT INTO stanza VALUES('CB271','1','Gianak sa Espiritu,<br/>Anak na sa Dios ako;<br/>Espiritu nagpuyo sa<br/>Sulod, tagbo sa tanan.<br/>Apan labi pang kin’hanglan,<br/>Pun-on kami, Ginoo,<br/>Sa Imong Espiritu ug<br/>Mabuhi, madagayaon.<br/>',NULL,16842,1);
INSERT INTO stanza VALUES('CB271','2','Espiritu’s sulod namo<br/>Iya man’s kinabuhi;<br/>Kadato Mo maambitan,<br/>Tungod’s pagkamao N’ya,<br/>Apan gikinahanglan pa<br/>Ang gahum’s Espiritu,<br/>Aron’s buhat, pag-alagad<br/>Kami masinangkapan.<br/>',NULL,16843,2);
INSERT INTO stanza VALUES('CB271','3','Bautismohi’s Espiritu,<br/>Sul-obi’s Imong kusog;<br/>Pinaagi’s kupo’s gahum<br/>Sa Yawa makigbisug.<br/>Huypi karon sa hangin Mo,<br/>Dila’s kalayo hatagi,<br/>Himoang dihogang saksi,<br/>Magtuman’s tinguha Mo.<br/>',NULL,16844,3);
INSERT INTO stanza VALUES('CB271','4','Sa gahum’s Espiritu Mo,<br/>Paambita sa gasa,<br/>Maglihok ang matag usa,<br/>Manghimatuod Nimo.<br/>Pagbubo’s Espiritu Mo,<br/>Gasa iapod-apod,<br/>Panalangin magpadayon,<br/>Aron Lawas matukod.<br/>',NULL,16845,4);
INSERT INTO stanza VALUES('CB271','5','Sa himaya’g gingharian,<br/>Ang Lawas nangamuyo;<br/>Balaang tuyo tumanon,<br/>Kagutom Imong busgon.<br/>Paambita kaming tanan<br/>Sa Imong Espiritu;<br/>Magpuno, magbubo namo<br/>Sa sulod ug sa gawas.<br/>',NULL,16846,5);
INSERT INTO stanza VALUES('CB273','1','Ginoo, nangamuyo mi Nimo,<br/>Sa gahum Imong hatagan;<br/>Alang sa gingharian gamhi na,<br/>Makig-away sa kalangitan.<br/>',NULL,16847,1);
INSERT INTO stanza VALUES('CB273','chorus','Gahum! gahum! sul-obi sa gahum!<br/>Pasul-oba’s dakong gahum Mo!<br/>Gamhi! gamhi! gamhi na Ginoo!<br/>Ang Lawas Mo karon naghangyo!<br/>',NULL,16848,2);
INSERT INTO stanza VALUES('CB273','2','O Ginoo, gihangad Ka namo,<br/>Naghangyo sa diosnong ulan;<br/>Alang sa Lawas, ulan ihatag,<br/>Aron magamit sa buhat Mo.<br/>',NULL,16849,3);
INSERT INTO stanza VALUES('CB273','chorus','Ulan! ulan! ibubo ang ulan!<br/>Ibubo ang diosnon Mong ulan!<br/>Ulan! ulan! ibubo ang ulan!<br/>Ang Lawas Mo karon naghangyo!<br/>',NULL,16850,4);
INSERT INTO stanza VALUES('CB273','3','Maghulat uban’s kasegurohan,<br/>Naghangyo’s diosnong kalayo!<br/>Ulaya ang among kasingkasing,<br/>Aron magsangyaw’s ebanghelyo.<br/>',NULL,16851,5);
INSERT INTO stanza VALUES('CB273','chorus','Ang kalayo padilaabon Mo!<br/>Pasangyawa sa mensahe Mo!<br/>Ang kalayo padilaabon Mo!<br/>Ang Lawas Mo karon naghangyo!<br/>',NULL,16852,6);
INSERT INTO stanza VALUES('CB277','1','Nikayab nang Manluluwas,<br/>Didto sa kahitas-an,<br/>Gipurongan sa Amahan’s<br/>Himaya’g kadungganan;<br/>Gihimo S’yang Ulo’s tanan,<br/>Ginoo di hilabwan.<br/>',NULL,16853,1);
INSERT INTO stanza VALUES('CB277','2','Didto sa Dios S’ya nikayab,<br/>Espiritu gibubo,<br/>Gibubo sa Iyang Lawas,<br/>Mga bahin magamhan;<br/>Aron Ginoo sa tanan,<br/>Iglesia mag-ambahan.<br/>',NULL,16854,2);
INSERT INTO stanza VALUES('CB277','3','Diha sa pagpakatawo,<br/>Ang Dios gidala N’ya’s tawo;<br/>Sa namatay S’ya’g nabanhaw,<br/>Tawo gidala N’ya sa Dios;<br/>Dios ug tawo magkasagol,<br/>Diha Niya maumol.<br/>',NULL,16855,3);
INSERT INTO stanza VALUES('CB277','4','Karon nikayab si Cristo,<br/>Ug nilingkod sa trono;<br/>Ginoo’s tanang ginoo,<br/>Iyahang pagkaulo;<br/>Sa pagbubo’s Espiritu<br/>Masayran S’ya nga mao.<br/>',NULL,16856,4);
INSERT INTO stanza VALUES('CB277','5','Ning pagbubo naamgohan’s<br/>Iglesiang pagkunsad N’ya;<br/>Gibautismohang Iglesia<br/>Ning Espiritu Niya;<br/>Bautismo sa Espiritu<br/>Nahimo na gyud’s hangtud.<br/>',NULL,16857,5);
INSERT INTO stanza VALUES('CB277','6','Hallelujah, nahuman na,<br/>Kas-a, nahuman’s dayon!<br/>Hallelujah, nalakip ta,<br/>Nalakip dagko’g gagmay!<br/>Daygon S’ya sa Espiritu,<br/>Sa bautismo’s Iglesia!<br/>',NULL,16858,6);
INSERT INTO stanza VALUES('CB278','1','Espiritu’s kinabuhi na’ nato,<br/>Sama sa tubig nagtagbaw’s kauhaw;<br/>S’ya atong imnon aron Iyang pun-on,<br/>Hangtud daw suba S’yang moagay nato.<br/>',NULL,16859,1);
INSERT INTO stanza VALUES('CB278','2','Esp’ritu’s gahum nia nato karon,<br/>Sama sa biste nagbiste kanato;<br/>Sa pagbautismo kita gibistehan<br/>Sa pag-alagad gahum masangkapan.<br/>',NULL,16860,2);
INSERT INTO stanza VALUES('CB278','3','Espiritu’s kinabuhi ginhawa,<br/>Iginhawa nganhi kanato karon;<br/>Espiritu’s gahum sama sa hangin,<br/>Huypan ta’s gahum gikan’s kahitas-an.<br/>',NULL,16861,3);
INSERT INTO stanza VALUES('CB278','4','Giginhawa N’ya sa mga tinun-an<br/>Espiritu’s kinabuhi gihatag;<br/>Gibubo’s nikayab sa Pentecostes<br/>Espiritu’s gahum’s mga tinun-an.<br/>',NULL,16862,4);
INSERT INTO stanza VALUES('CB278','5','Ang Espiritu sa kinabuhi N’ya<br/>Kinabuhi nato karon sa sulod;<br/>Sama sa hangin lunhaw, maginhawa;<br/>Espiritu’s gahum alang niini.<br/>',NULL,16863,5);
INSERT INTO stanza VALUES('CB278','6','Kini dili duha ka espiritu,<br/>Usa ra apan duha’y kagamitan;<br/>Magbiste kanato’g Dios ug magpuno,<br/>Aron hingpit masagol uban Niya.<br/>',NULL,16864,6);
INSERT INTO stanza VALUES('CB278','7','Sa matag bahin pun-a’s Espiritu,<br/>Aron magtubo nga masama Nimo;<br/>Ug masul-oban’s Espiritu’s gahum,<br/>Makatuman sa Imong kabubut-on.<br/>',NULL,16865,7);
INSERT INTO stanza VALUES('CB279','1','Una ang dugo sa dihog,<br/>Dihogan kon hinlo na;<br/>Kon di mag-agi’s Golgota,<br/>Wala gyuy Pentecostes.<br/>Kon wa mahinloi’s dugo,<br/>Way gahum’s Espiritu;<br/>Kon kang Cristo manghimat’od.<br/>Ang “ako” ilansang gyud.<br/>',NULL,16866,1);
INSERT INTO stanza VALUES('CB279','chorus','Itugyan ko, Ginoo<br/>Kalagnong kinabuhi;<br/>Bisan unsa antuson ko,<br/>Mapuno lang’s dihog Mo.<br/>',NULL,16867,2);
INSERT INTO stanza VALUES('CB279','2','Hampakon usa ang Bato,<br/>Aron tubig moagay;<br/>Kon si Cristo di mamatay,<br/>Di S’ya makapuyo’s tawo.<br/>Kon mamatay ubang Cristo,<br/>Andam mawad-an’s tanan,<br/>Sa gahum Niya sul-oban,<br/>Magkabig ta’s katawhan.<br/>',NULL,16868,3);
INSERT INTO stanza VALUES('CB279','3','Unang halaran’s kalayo,<br/>Mawad-an, mabatonan;<br/>Kon ihalad ta ang tanan,<br/>Ang trono mabatonan.<br/>Kon andam ta nga mag-antus,<br/>Makasugot lang sa Dios,<br/>Magpakita S’ya sa gahum<br/>Pinaagi kanato.<br/>',NULL,16869,4);
INSERT INTO stanza VALUES('CB279','4','Iandam unang sudlanan,<br/>Kasudlan sa Lana N’ya;<br/>Kanal sa walog kalotan,<br/>Aron mapuno’s Ulan;<br/>Mag-agi una ta’s Jordan,<br/>Ayha ta madihogan;<br/>Salampati masinati’s<br/>Bautismo’s kamatayon.<br/>',NULL,16870,5);
INSERT INTO stanza VALUES('CB279','5','Hinog na ang alanihon,<br/>Makita bulawanon;<br/>Sayri nga daghan nga trigo<br/>Ang nangamatay didto.<br/>Kon buot kitang mamunga<br/>Kin’hanglang mamatay ta;<br/>Kon ilubong ubang Cristo,<br/>Ginhawaan’s Esp’ritu.<br/>',NULL,16871,6);
INSERT INTO stanza VALUES('CB279','6','Ingon man kaha, Ginoo,<br/>Tabangi nga sundon ko;<br/>Batokang garbo, andamang<br/>Mag-antus sa pagsugot.<br/>Labawng gahum di kin’hanglan,<br/>Kondi’ ang kamatayon,<br/>Tanang kahulogan sa Krus,<br/>Buhata nganhi nako.<br/>',NULL,16872,7);
INSERT INTO stanza VALUES('CB280','1','Ginoo, sa dugo Mo,<br/>Hinloan Mo ako;<br/>Dihogi’s Espiritu,<br/>Giampo Kanimo.<br/>Pag-alagad ko pakyas,<br/>Huyang man kaayo;<br/>Mabuhi alang Nimo,<br/>Pun-a’s Espiritu.<br/>',NULL,16873,1);
INSERT INTO stanza VALUES('CB280','chorus','O l’wasa na, Ginoo,<br/>Ako’s kaugalingon;<br/>Himoang sukad karon,<br/>Mapuno Kanimo.<br/>',NULL,16874,2);
INSERT INTO stanza VALUES('CB280','2','Kauga sa sulod ko,<br/>Nangandoy Kanimo;<br/>Pun-a ko’s Espiritu,<br/>Maoy pag-ampo ko.<br/>Patagoa, Ginoo,<br/>Sa samarang Bato;<br/>Buboi’s buhing tubig<br/>Hangtud matagbaw ko.<br/>',NULL,16875,3);
INSERT INTO stanza VALUES('CB280','3','Kabugnaw’s kasingkasing,<br/>Hinay kon mosugot;<br/>Pun-a na’s Espiritu,<br/>Aron di mosukol.<br/>Naghigda sa halaran,<br/>Dili na modagan;<br/>Kalayo Mo manaug,<br/>Kanako magsunog.<br/>',NULL,16876,4);
INSERT INTO stanza VALUES('CB280','4','Krus Mo unta kanako<br/>Lalum nga magbuhat;<br/>Modako Ka kanako<br/>Himoa kong abo.<br/>Magpuno unta nako<br/>Imong Espiritu,<br/>Ang buhi Mo nga tubig,<br/>Kanako ibubo.<br/>',NULL,16877,5);
INSERT INTO stanza VALUES('CB284','1','Gugmang way katapusan,<br/>Gihigugma Mo nako;<br/>Espiritu nagtudlo,<br/>Aron ko mahibalo;<br/>Kahingpit sa kalinaw!<br/>Kadiosnon sa kalipay!<br/>Ning gugmang di matapos,<br/>Ako Iya, S’ya ako.<br/>',NULL,16878,1);
INSERT INTO stanza VALUES('CB284','2','Kabughaw’s kalangitan,<br/>Kalunhaw’s kayutaan;<br/>Nabuhi, mabulokon,<br/>Wa makita’s way Cristo:<br/>Katahum’s kabulakan,<br/>Awit sa kalanggaman,<br/>Sukad ako nasayud<br/>Ako Iya, S’ya ako.<br/>',NULL,16879,2);
INSERT INTO stanza VALUES('CB284','3','Ang kanhing kahadlok ko<br/>Di na gyud makatugaw;<br/>Sa Iyang mga bukton,<br/>Ako nagpauraray.<br/>Ingon unta sa dayon,<br/>Kaniya malipayon;<br/>Samtang Siya naghunghong<br/>Ako Iya, S’ya ako.<br/>',NULL,16880,3);
INSERT INTO stanza VALUES('CB284','4','Iya lamang sa dayon,<br/>Kinsay magbulag namo?<br/>Pahulayng nadawat ko,<br/>Katagbawan kang Cristo.<br/>Langit, yuta mahanaw,<br/>Mapalong mang kahayag,<br/>Tali sa Dios ug nako,<br/>Ako Iya, S’ya ako.<br/>',NULL,16881,4);
INSERT INTO stanza VALUES('CB286','1','Gipangita ni Jesus,<br/>Kay nawala’s sala;<br/>Grasya nga katingad-an<br/>Nagbalik sa panon.<br/>Kalalum’s ’yang kaluoy,<br/>Lalum pa’s kadagatan,<br/>Habog pa’s kalangitan<br/>Tema’s kahangturan.<br/>',NULL,16882,1);
INSERT INTO stanza VALUES('CB286','chorus','Nagkatam-is ’yang gugma,<br/>Sa paglabay’s panahon;<br/>Dato, hupong, lalum,<br/>Gugma nagkalalum<br/>Sa paglabay’s panahon.<br/>',NULL,16883,2);
INSERT INTO stanza VALUES('CB286','2','Gipanaw N’yang Judea,<br/>Sa nabuhi pa S’ya;<br/>Gitapokan’s katawhan,<br/>Grasya m’oy masayran.<br/>Giayo N’yang nasamdan,<br/>Buta gipakita;<br/>Ug nangandoyng panggaon<br/>Bisan ngani ako.<br/>',NULL,16884,3);
INSERT INTO stanza VALUES('CB295','1','Pagkamatarung ko’s Cristo,<br/>Kaanyag, biste’s himaya;<br/>Kon S’ya’y sul-ob ko sa yuta,<br/>Ulo iisa’s kalipay.<br/>',NULL,16885,1);
INSERT INTO stanza VALUES('CB295','2','Nitoo ko sa dugo Mong<br/>Nangamuyo alang nako<br/>Sa trono sa kaluoy Mo,<br/>Giula alang’s kalag ko.<br/>',NULL,16886,2);
INSERT INTO stanza VALUES('CB295','3','Makasasala daghan pa’s<br/>Mga balas sa baybayon,<br/>Apan nalukat Mong tanan,<br/>Sa hingpit nga katubsanan!<br/>',NULL,16887,3);
INSERT INTO stanza VALUES('CB295','4','May kaisug kong mobarug,<br/>Kinsa may makasumbong pa?<br/>Hingpit Mo nang giabswelto<br/>Gikan’s sala ug kaulaw.<br/>',NULL,16888,4);
INSERT INTO stanza VALUES('CB295','5','Sul-ob kong biste way buling,<br/>Di mausab, magpabilin;<br/>Bisan’s kadautan sa tawo<br/>Kini magpabiling bag-o.<br/>',NULL,16889,5);
INSERT INTO stanza VALUES('CB295','6','Dios sa gahum, Dios sa gugma,<br/>Pasaksiha ming mga balaan<br/>Kaanyag Ka’g biste namo,<br/>Ug among Pagkamatarung.<br/>',NULL,16890,6);
INSERT INTO stanza VALUES('CB296','1','Naikag ba kong masayud<br/>Sa dugo sa Manluluwas?<br/>Namatay S’ya alang nako<br/>Nga hinungdan’s ’yang kasakit?<br/>Gugmang pagkakatingad-an!<br/>Nganong ako pakamatyan?<br/>Gugmang pagkakatingad-an!<br/>Nganong ako pakamatyan?<br/>',NULL,16891,1);
INSERT INTO stanza VALUES('CB296','2','O misteryo! Dios namatay!<br/>Plano sa Dios matugkad ba?<br/>Bisag anghel naningkamot<br/>Gugma’s Dios dili masabut!<br/>Kaluoy N’ya kining tanan!<br/>Simbahon S’ya’s kayutaan.<br/>Kaluoy N’ya kining tanan!<br/>Simbahon S’ya’s kayutaan.<br/>',NULL,16892,2);
INSERT INTO stanza VALUES('CB296','3','Gib’yaan trono’s Amahan,<br/>Grasya N’ya way kinutoban;<br/>Kaugalingon gibasyo man,<br/>Namatay alang’s katawhan;<br/>Kaluoy Niya ang tanan,<br/>Ug ako Iyang nasakpan.<br/>Kaluoy Niya ang tanan,<br/>Ug ako Iyang nasakpan.<br/>',NULL,16893,3);
INSERT INTO stanza VALUES('CB296','4','Espiritu ko dugay nang<br/>Naggapos’ sala’g kangitngit;<br/>Gisug-an sa Imong mata,<br/>Nagmata, puno’s kahayag;<br/>Ang gapos ko nangatangtang,<br/>Nibangon ko, Nisunod Nimo.<br/>Ang gapos ko nangatangtang,<br/>Nibangon ko, nisunod Nimo.<br/>',NULL,16894,4);
INSERT INTO stanza VALUES('CB296','5','Way paghukom kahadlokan,<br/>Kay si Jesus naako man;<br/>Mabuhi ko diha Niya,<br/>Gisul-ob pagkamatarung;<br/>May kaisug moduol’s trono<br/>Pag-angkon sa purongpurong<br/>May kaisug moduol’s trono<br/>Pag-angkon sa purongpurong.<br/>',NULL,16895,5);
INSERT INTO stanza VALUES('CB298','1','Way laing gisaligan ko,<br/>Gawas lang ni Jesucristo;<br/>S’ya ang pagkamatarung ko,<br/>Ang ’yang ngalan saligan ko.<br/>',NULL,16896,1);
INSERT INTO stanza VALUES('CB298','chorus','Lig-ong Bato nga si Cristo<br/>Maoy akong gibarugan;<br/>Kay uban di kasaligan.<br/>',NULL,16897,2);
INSERT INTO stanza VALUES('CB298','2','Kon nawong N’ya matabonan,<br/>Grasya N’ya way kausaban;<br/>Sa unos mang labing kusgan,<br/>Giangkla ko sulod’s tabil.<br/>',NULL,16898,3);
INSERT INTO stanza VALUES('CB298','3','Panumpa’g saad, dugo N’ya,<br/>Motabang’s akong kalisud;<br/>Bisan ang tanan manibog,<br/>S’ya paglaum ko ug kusog.<br/>',NULL,16899,4);
INSERT INTO stanza VALUES('CB298','4','Inighuyop sa trumpeta,<br/>Mapalgan unta diha N’ya;<br/>S’ya m’oy pagkamatarung ko;<br/>Way apan moduol’s trono.<br/>',NULL,16900,5);
INSERT INTO stanza VALUES('CB300','1','Bangon, O kalag ko!<br/>Wad-ang kahadlok mo;<br/>Ang nagdugong Halad,<br/>Nipuli man nako.<br/>Kalig-onan atbang’s trono.<br/>Nga’n ko nasulat’s kamot N’ya.<br/>',NULL,16901,1);
INSERT INTO stanza VALUES('CB300','2','Nabuhi S’ya’s dayon,<br/>Tigpangamuyo ko;<br/>Gugma N’yang nagtubos,<br/>Dugo nga naghangyo;<br/>Dugong giula kanato<br/>Gisablig’s trono sa grasya.<br/>',NULL,16902,2);
INSERT INTO stanza VALUES('CB300','3','Lima ang ’yang samad<br/>Didto sa Calvario;<br/>Gamhanang pag-ampo,<br/>Alang gayud nako;<br/>“Pasayloa,” singgit ni’ni,<br/>“Ayaw tugoting mamatay!”<br/>',NULL,16903,3);
INSERT INTO stanza VALUES('CB300','4','Nadungog’s Amahan,<br/>Ampo’s Dinihogan;<br/>Di S’ya makadili<br/>Sa presensya’s Anak;<br/>Esp’ritu nitubag’s dugo,<br/>Niingon gianak ko’s Dios.<br/>',NULL,16904,4);
INSERT INTO stanza VALUES('CB300','5','Napasig-uli ko,<br/>Sa Dios gipasaylo;<br/>Giangkon kong anak,<br/>Wala nay kahadlok.<br/>May pagsalig nga moduol<br/>Motawag, “Abba Amahan.”<br/>',NULL,16905,5);
INSERT INTO stanza VALUES('CB301','1','Gitubos—kalipayng isinggit!<br/>Dugo’s Cordero nagtubos;<br/>Sa ’yang kaluoy gitubos na,<br/>Sa dayon anak ko Niya.<br/>',NULL,16906,1);
INSERT INTO stanza VALUES('CB301','chorus','Gitubos, gitubos,<br/>Dugo’s Cordero nagtubos;<br/>Gitubos, gitubos,<br/>Anak ko Niya sa dayon.<br/>',NULL,16907,2);
INSERT INTO stanza VALUES('CB301','2','Gitubos na diha ni Jesus,<br/>Di maasoy ang kalipay;<br/>Nasayud nga presensya Niya,<br/>Uban nako sa kanunay.<br/>',NULL,16908,3);
INSERT INTO stanza VALUES('CB301','3','Naghunahuna’s Manunubos,<br/>Sa tibuok gyud nga adlaw;<br/>Di makahilom, awiton gyud,<br/>Gugma N’ya m’oy tema’s hangtud.<br/>',NULL,16909,4);
INSERT INTO stanza VALUES('CB301','4','Katahum N’ya unya makit-an,<br/>Hari nga gikahimut-an;<br/>Magbantay’s akong mga lakang,<br/>Maglipay S’ya’s kagul-anan.<br/>',NULL,16910,5);
INSERT INTO stanza VALUES('CB302','1','Sukad nga Iyang gitubos,<br/>Gusto kong awitan,<br/>Ang Hari ko’g Manunubos—<br/>Sa tanang panahon.<br/>',NULL,16911,1);
INSERT INTO stanza VALUES('CB302','chorus','Sukad gitubos N’ya,<br/>Sukad gitubos N’ya,<br/>Maghimaya’s ’yang ngalan;<br/>Sukad gitubos N’ya,<br/>Maghimaya sa Iyang ngalan.<br/>',NULL,16912,2);
INSERT INTO stanza VALUES('CB302','2','Sukad nga gitubos Niya,<br/>May Cristong nagtagbaw;<br/>Nagtuman’s ’yang kabubut-onv<br/>Sukad gitubos N’ya.<br/>',NULL,16913,3);
INSERT INTO stanza VALUES('CB302','3','May saksing tin-aw’g mahayag,<br/>Sukad gitubos N’ya;<br/>Wa nay katahap, kahadlok—<br/>Sukad gitubos N’ya.<br/>',NULL,16914,4);
INSERT INTO stanza VALUES('CB302','4','Kalipay ko di maasoy,<br/>Sukad gitubos N’ya;<br/>Tanan tungod sa Ginoo—<br/>Pagkamatarung ko.<br/>',NULL,16915,5);
INSERT INTO stanza VALUES('CB302','5','May Dios nga alang kanako,<br/>Sukad gitubos N’ya;<br/>Uban Kaniya magpuyo—<br/>Hangtud’s kahangturan.<br/>',NULL,16916,6);
INSERT INTO stanza VALUES('CB308','1','Lig-ong pasalig, Jesus ako;<br/>Pagtilaw daan sa himaya!<br/>Linukat, manunod’s kal’wasan,<br/>Gianak ako’s Espiritu.<br/>',NULL,16917,1);
INSERT INTO stanza VALUES('CB308','chorus','Kini ang akong sugilanon,<br/>Daygon S’ya sa tanang panahon.<br/>Kini ang akong pag-awiton,<br/>Daygon S’ya sa tanang panahon.<br/>',NULL,16918,2);
INSERT INTO stanza VALUES('CB308','2','Kalipayng hingpit ang pagsugot,<br/>May panan-awon na’s paglalin;<br/>Anghel nanaug nagdala sa<br/>Tingog’s kaluoy’g paghigugma.<br/>',NULL,16919,3);
INSERT INTO stanza VALUES('CB308','3','Hingpit pagsugot, may pahulay,<br/>Gibulahan sa Manluluwas;<br/>Nagtukaw, naghulat Kaniya,<br/>Puno’s kaayo ug gugma N’ya.<br/>',NULL,16920,4);
INSERT INTO stanza VALUES('CB309','1','May pagkabalhin sa akong kinabuhi<br/>Sukad naako si Jesus!<br/>May diosnon nga kahayag nagpuno’s kalag,<br/>Kay naako na si Jesus!<br/>',NULL,16921,1);
INSERT INTO stanza VALUES('CB309','chorus','Sukad naako si Jesus!<br/>Sulod ning kasingkasing ko!<br/>Nagbaha ang kalipay sa akong kalag,<br/>Sukad naako si Jesus!<br/>',NULL,16922,2);
INSERT INTO stanza VALUES('CB309','2','Wala na maglaag ug mahisalaag,<br/>Sukad naako si Jesus!<br/>Daghang sala ko gihugasan N’yang tanan,<br/>Sukad naako si Jesus!<br/>',NULL,16923,3);
INSERT INTO stanza VALUES('CB309','3','Ang malig-ong paglaum naako gayud,<br/>Sukad naako si Jesus!<br/>Ug nahanaw ang dag-om sa akong dalan,<br/>Sukad naako si Jesus!<br/>',NULL,16924,4);
INSERT INTO stanza VALUES('CB309','4','Alang nako walog’s kamatayon hayag,<br/>Sukad naako si Jesus!<br/>Ug mga ganghaan sa Syudad makita<br/>Sukad naako si Jesus!<br/>',NULL,16925,5);
INSERT INTO stanza VALUES('CB309','5','Magpuyo unya’s Syudad nga nasayran ko,<br/>Sukad naako si Jesus!<br/>Nalipay kaayo sa pagpadayon ko,<br/>Sukad naako si Jesus!<br/>',NULL,16926,6);
INSERT INTO stanza VALUES('CB310','1','Kanhi nagapos ako sa sala,<br/>Sama’s bihag di makagula;<br/>Apan gapos gibugto ni Jesus,<br/>Ako nahigawas sa bug-os.<br/>',NULL,16927,1);
INSERT INTO stanza VALUES('CB310','chorus','Mahimayaon nga kagawasan,<br/>Wa nay gapos nga kamuloan!<br/>Si Jesus maoy Tigpahigawas,<br/>S’ya akoa’s way katapusan.<br/>',NULL,16928,2);
INSERT INTO stanza VALUES('CB310','2','Gawas na sa unodnong pangibog,<br/>Sa mga kasina’g pagdumot;<br/>Nagawas sa yutan-ong pangandoy,<br/>Sa tanan nga nakapasubo.<br/>',NULL,16929,3);
INSERT INTO stanza VALUES('CB310','3','Gawas na sa garbo ko’g kabuang,<br/>Sa gugma nako sa bulawan;<br/>Gawas na sa dautang batasan,<br/>Sa kasuko’g kabagulbolan.<br/>',NULL,16930,4);
INSERT INTO stanza VALUES('CB310','4','Gawas na sa tanan nga kahadlok,<br/>Sa akong mga kabalaka;<br/>Nahigawas diha’s Manunubos,<br/>Nga nagbugto sa tanang gapos.<br/>',NULL,16931,5);
INSERT INTO stanza VALUES('CB311','1','Walay naangkon nga di grasya N’ya;<br/>Sa pagtoo ko gituga Niya;<br/>Walay kagarbo ni pangandak,<br/>Ako makasasalang nal’was.<br/>',NULL,16932,1);
INSERT INTO stanza VALUES('CB311','chorus','Makasasalang naluwas!<br/>Makasasalang naluwas!<br/>Sugilanon ko: grasya nagluwas,<br/>Ako makasasalang nal’was!<br/>',NULL,16933,2);
INSERT INTO stanza VALUES('CB311','2','Kanhi bugo ko, sala’y nagbuot,<br/>Paggawi ko nahilayo sa Dios;<br/>Nakaplagan N’ya, O kalipay;<br/>Karon sa grasya N’ya naluwas!<br/>',NULL,16934,3);
INSERT INTO stanza VALUES('CB311','3','Mga luha ko wala magpulos,<br/>Gil’was’ kaluoy, kondi’ mamatay;<br/>Gihulga’s sala, nataha’s Dios,<br/>Karon sa grasya N’ya naluwas!<br/>',NULL,16935,4);
INSERT INTO stanza VALUES('CB311','4','Pasuginla sa gugmang nag-awas,<br/>Sa kasingkasing ngadto’s Manlul’was;<br/>Balikbalik nga isugilon,<br/>Makasasala, grasya nagl’was!<br/>',NULL,16936,5);
INSERT INTO stanza VALUES('CB312','1','Nindot paminawon<br/>Ang pulong nga grasya;<br/>Langit nagpalanog aron<br/>Yuta makadungog.<br/>',NULL,16937,1);
INSERT INTO stanza VALUES('CB312','chorus','Igo ang grasya!<br/>Di magkaluya!<br/>Cristo nabuhi’s sulod,<br/>Di makabsan gayud.<br/>',NULL,16938,2);
INSERT INTO stanza VALUES('CB312','2','Ngalan ko nasulat<br/>Sa basahong dayon;<br/>Grasya naghatag’s Corderong<br/>Nagkuha’s kasubo.<br/>',NULL,16939,3);
INSERT INTO stanza VALUES('CB312','3','Grasya m’oy nagtudlo<br/>Magpanaw’s dalan Mo;<br/>Bag-ong sangkap Mo magtagbo,<br/>Sa pagpadayon ko.<br/>',NULL,16940,4);
INSERT INTO stanza VALUES('CB312','4','Grasya nagpaampo,<br/>Luha magpatulo;<br/>Grasyang nag-amping kanako,<br/>Di mobuhi nako.<br/>',NULL,16941,5);
INSERT INTO stanza VALUES('CB312','5','Grasya ang magpurong<br/>Sa tanan nga buhat;<br/>Magtutukod diha’s gugma,<br/>Angayan nga daygon.<br/>',NULL,16942,6);
INSERT INTO stanza VALUES('CB312','6','Dasiga sa grasya<br/>Ang kasingkasing ko;<br/>Tanang kusog itinguha<br/>Nimo’s tanang adlaw.<br/>',NULL,16943,7);
INSERT INTO stanza VALUES('CB313','1','Grasya katingad-an gayud!<br/>Nagluwas kanako!<br/>Nawala, gipangita N’ya,<br/>Buta, gipakita.<br/>',NULL,16944,1);
INSERT INTO stanza VALUES('CB313','2','Grasya nagtudlong mahadlok,<br/>Ug m’oy nagkuha sab;<br/>Gipadayag ang grasya Mo,<br/>Takna’s pagtoo ko!<br/>',NULL,16945,2);
INSERT INTO stanza VALUES('CB313','3','Gisaad tanang maayo<br/>Kanako’s Ginoo;<br/>Siya taming ug pahat ko,<br/>Samtang buhi pa ko.<br/>',NULL,16946,3);
INSERT INTO stanza VALUES('CB313','4','Kon magdugay na ta didto,<br/>Mahayag daw Adlaw,<br/>Ang akong pagdayeg sa Dios,<br/>Labaw pa’s pagsugod.<br/>',NULL,16947,4);
INSERT INTO stanza VALUES('CB316','1','May adlaw nga mopanaw ko,<br/>Di mag-awit sama karon;<br/>Unsang kalipay pagmata<br/>Didto na’s Iyang presensya!<br/>',NULL,16948,1);
INSERT INTO stanza VALUES('CB316','chorus','Makita ko na S’ya’s nawong,<br/>Nal’was’ grasya, isugilon:<br/>Makita ko na S’ya’s nawong,<br/>Nal’was’ grasya, isugilon.<br/>',NULL,16949,2);
INSERT INTO stanza VALUES('CB316','2','Yutan-ong balay maguba,<br/>Wa masayri kon anus-a,<br/>Nasayud lang—S’yang tanan ko,<br/>May dapit na alang nako.<br/>',NULL,16950,3);
INSERT INTO stanza VALUES('CB316','3','O abtan ba sa Ginoo,<br/>Tawgon, pasugaton Niya;<br/>Moingong buhat ko “maayo,“<br/>Makapahulay uban N’ya.<br/>',NULL,16951,4);
INSERT INTO stanza VALUES('CB316','4','Magtukaw ko ug maghulat,<br/>Suga hinloan, magsiga;<br/>Ug sa akong pagsugat N’ya,<br/>Pagtoo ko, makita na.<br/>',NULL,16952,5);
INSERT INTO stanza VALUES('CB319','1','Tuboran Ka’s kabulahan,<br/>Paawita’s grasya Mo;<br/>Way hunong ang kaluoy Mo,<br/>Daygon’s labing makusog.<br/>Dumuloong man unta ko,<br/>Jesus nangita nako;<br/>Aron kalag ko maluwas,<br/>Dugong mahal giula.<br/>',NULL,16953,1);
INSERT INTO stanza VALUES('CB319','2','Dakong utangan ko’s grasya,<br/>Adlaw-adlaw gitandog!<br/>Sama’g gapos untang grasya,<br/>Maghikot nako Nimo.<br/>Tudloi ko, O Ginoo,<br/>Pagmatuod’s grasya Mo,<br/>Di maisip nga kadato’s<br/>Gugmang way pagkausab.<br/>',NULL,16954,2);
INSERT INTO stanza VALUES('CB319','3','Laagan ako, Ginoo,<br/>Sayon mobiya Nimo;<br/>Bihaga nang kasingkasing,<br/>Timbrihe’s Espiritu.<br/>Luwasa gikan sa sala,<br/>Kay gilukat’s dugo Mo,<br/>Magdumuloong ko’s yuta<br/>Anak, manununod’s Dios.<br/>',NULL,16955,3);
INSERT INTO stanza VALUES('CB322','1','Daghang tuig kawang nga gipangita<br/>Tubod way pagkauga;<br/>Walay tanyag gikan sa kalibutan,<br/>Maghatag’s katagbawan.<br/>',NULL,16956,1);
INSERT INTO stanza VALUES('CB322','chorus','Inom sa Tuborang way pagkauga,<br/>Inom sa kinabuhi man kita;<br/>Kalipayng napalgan<br/>Walay kinutoban,<br/>Nag-inom sa buhi nga Tuboran.<br/>',NULL,16957,2);
INSERT INTO stanza VALUES('CB322','2','Di na maglaag’s yuta’s kamingawan,<br/>Kay Tuboran nakit-an,<br/>Kopa sa kalipay ko nag-awas na,<br/>Ginoo ko’g Hari S’ya.<br/>',NULL,16958,3);
INSERT INTO stanza VALUES('CB322','3','Katagbawan ang adlawng nagpanglabay,<br/>May kalinaw’g pahulay;<br/>Sa paglabay’s matag gutlo gilipay,<br/>Nabulahan kanunay.<br/>',NULL,16959,4);
INSERT INTO stanza VALUES('CB322','4','Dinhi sangkap wala gyuy katapusan,<br/>Bisan sa katuigan;<br/>Tuboran nga mag-ayo akong dangpan,<br/>Kalag ko mahuwasan.<br/>',NULL,16960,5);
INSERT INTO stanza VALUES('CB325','1','Gihidlaw nga makainom,<br/>Usa ka bugnawng tubod,<br/>Nga magkuha’s kauhaw ko,<br/>Ug sa tanang kauga.<br/>',NULL,16961,1);
INSERT INTO stanza VALUES('CB325','chorus','Hallelujah! Napalgan ko<br/>Ang dugayng gipangandoy!<br/>Si Jesus nagtagbaw nako;<br/>Kinabuhi N’ya nagl’was.<br/>',NULL,16962,2);
INSERT INTO stanza VALUES('CB325','2','Bunga’s biyatilis napugos<br/>Pagkaon, kay gigutom,<br/>Apan kutob ra’s pangandoy,<br/>Wa makuhang kagutom.<br/>',NULL,16963,3);
INSERT INTO stanza VALUES('CB325','3','Kabus, nangita’s kadato,<br/>Aron ako matagbaw,<br/>Apan abug ang naangkon,<br/>Pangita ko gitamay.<br/>',NULL,16964,4);
INSERT INTO stanza VALUES('CB325','4','Buhing tubig nga nagtubod,<br/>Kalan-on’s kinabuhi,<br/>Kadato nga maangkon ko,<br/>Sa akong Manunubos.<br/>',NULL,16965,5);
INSERT INTO stanza VALUES('CB333','1','Wa ko masayud nganong gibutyag<br/>Grasya N’ya kanako,<br/>Kon nganong gilukat ako<br/>Nga dili man takus.<br/>',NULL,16966,1);
INSERT INTO stanza VALUES('CB333','chorus','Nakaila’s gitoohan ko,<br/>Ug nitoo nga makahimo S’ya’s<br/>Pagbantay sa gitugyan ko,<br/>Hangtud niadtong adlawa.<br/>',NULL,16967,2);
INSERT INTO stanza VALUES('CB333','2','Wa ko masayud giunsa Niya<br/>Paghatag nako’g pagtoo,<br/>O sa pagtoo’s Pulong N’ya,<br/>May kalinaw ako.<br/>',NULL,16968,3);
INSERT INTO stanza VALUES('CB333','3','Wa ko gayud hibaloi,<br/>Lihok’s Espiritu;<br/>Nganong sala ko gituto,<br/>Kang Jesus motoo.<br/>',NULL,16969,4);
INSERT INTO stanza VALUES('CB333','4','Wa ko masayud’s gitagana,<br/>Maayo ba’g dautan,<br/>Laay o madasigon ba,<br/>Sa di pa igkita Siya.<br/>',NULL,16970,5);
INSERT INTO stanza VALUES('CB333','5','Wa masayri kon S’ya mobalik,<br/>Adlaw ba’g gabii,<br/>Moagi pa ba ko’s walog,<br/>Mosugat ba’s panganud.<br/>',NULL,16971,6);
INSERT INTO stanza VALUES('CB339','1','Unsa kalig-on nga patukoranan,<br/>Diha’s pulong gibutang ang pagtoo;<br/>Unsa pay masulti N’ya’s nasulti na,<br/>Mga balaang nidangop ni Jesus?<br/>',NULL,16972,1);
INSERT INTO stanza VALUES('CB339','2','“Ayaw kahadlok, nag-uban Ko nimo,<br/>Ako ang Dios nga motabang kanimo;<br/>Lig-onon Ko ikaw, pabarugon Ko,<br/>Pinaagi sa kamot nga matarung.<br/>',NULL,16973,2);
INSERT INTO stanza VALUES('CB339','3','“Kon sa laglum nga tubig palatason,<br/>Mga suba’s kaguol di paawason;<br/>Mag-uban Ako nimo, magbulahan,<br/>Magbalaan sa imong kasakitan.<br/>',NULL,16974,3);
INSERT INTO stanza VALUES('CB339','4','“Kon may pagsulayng modangat sa dalan,<br/>Igo ang grasya Ko, ikaw sangkapan;<br/>Kalayo di makadaut; mout-ot<br/>Ra sa sambog, mag-ulay’s bulawan mo.<br/>',NULL,16975,4);
INSERT INTO stanza VALUES('CB339','5','“Bisan’s pagkatigulang’s katawhan Ko<br/>Magmatuod gugma Ko di mausab;<br/>Bisan ubanon na ang ilang ulo,<br/>Daw cordero gihapon’s sabakan Ko.<br/>',NULL,16976,5);
INSERT INTO stanza VALUES('CB339','6','“Ang kalag nga nipahulay ni Jesus,<br/>Di gyud itugyan Nako’s ’yang kaaway;<br/>Kalag gipaningkamotan’s impyerno,<br/>Dili, di gyud Nako s’ya isalikway.”<br/>',NULL,16977,6);
INSERT INTO stanza VALUES('CB341','1','Kon kalinaw’s dalan sama sa suba,<br/>Kasub-anan sama’s balud,<br/>Bisan unsay dangatan gitudloan,<br/>“Kini maayo sa kalag ko.”<br/>',NULL,16978,1);
INSERT INTO stanza VALUES('CB341','chorus','Maayo’s kalag ko!<br/>Kini maayo sa kalag ko.<br/>',NULL,16979,2);
INSERT INTO stanza VALUES('CB341','2','Bisan yawa mobun-og, pagsuway moabot,<br/>May bulahan nga pasalig,<br/>Nga si Cristo nagtagad’s kahimtang ko,<br/>Nag-ula’s dugo alang nako.<br/>',NULL,16980,3);
INSERT INTO stanza VALUES('CB341','3','Kanindot nga di usa ra ka bahin,<br/>Kondi’ tibuok kong sala,<br/>Iya nang gikalansang ngadto sa Krus,<br/>Dayga ang Ginoo, kalag ko.<br/>',NULL,16981,4);
INSERT INTO stanza VALUES('CB341','4','Alang nako si Cristo ang nabuhi;<br/>Moabot man ang kangitngit,<br/>Mamatay, mabuhi, wa koy kasakit,<br/>Kalag hunghongan N’ya’s kalinaw.<br/>',NULL,16982,5);
INSERT INTO stanza VALUES('CB348','1','Sukad gil’was ko ni Cristo,<br/>Kalipay nang nabuhi ko;<br/>Diha’s kasub-anan’s yuta,<br/>Si Jesus ang kalipay ko.<br/>',NULL,16983,1);
INSERT INTO stanza VALUES('CB348','chorus','O hallelujah, kalipay!<br/>Kay Cristo napa’muslan ko!<br/>Yuta, dagat, bisan asa,<br/>Kon na’ S’ya, na’ng kalipay ko.<br/>',NULL,16984,2);
INSERT INTO stanza VALUES('CB348','2','Yuta kanhi pagkapait,<br/>Gipahiyoman, na-langit;<br/>Na’ nang kalipay su’d’s kalag,<br/>Kini wa gyuy katapusan.<br/>',NULL,16985,3);
INSERT INTO stanza VALUES('CB348','3','Bisan asa ang puy-anan,<br/>Ma-bukid o ma-walog man;<br/>Ma-payag ba o palasyo,<br/>Si Jesus ray kalipay ko.<br/>',NULL,16986,4);
INSERT INTO stanza VALUES('CB349','1','Sama’s lagsaw nga giuhaw<br/>Sa sapang mabugnaw;<br/>O Dios, ang kalag nangandoy,<br/>Sa grasyang maglunhaw.<br/>',NULL,16987,1);
INSERT INTO stanza VALUES('CB349','2','Kalag, nganong nasubo ka?<br/>Dios, m’oy saligan ra;<br/>Panghupaw mo ’yang ilisan’s<br/>Awit sa kalipay.<br/>',NULL,16988,2);
INSERT INTO stanza VALUES('CB349','3','O buhing Dios ako giuhaw,<br/>Kanimo gimingaw;<br/>Anus-a makitang nawong,<br/>Imong kahalangdon?<br/>',NULL,16989,3);
INSERT INTO stanza VALUES('CB349','4','Anus-a di na masama’s<br/>Gib’yaan, gibangotan<br/>Gisalikway ko’g gitamay<br/>Sa mga kaaway.<br/>',NULL,16990,4);
INSERT INTO stanza VALUES('CB349','5','Nganong nasubo ka kalag ko?<br/>Maglaum, mag-awit;<br/>Dayga Siya nga imong Dios,<br/>Tubod mo’s kalagsik.<br/>',NULL,16991,5);
INSERT INTO stanza VALUES('CB350','1','Dios m’oy tinguha, dili kalipay,<br/>Ni kalinaw ba’g kabulahanan;<br/>Maangkon S’ya di’s kaugalingon,<br/>Sundon lang Siya, bisan unsaon.<br/>',NULL,16992,1);
INSERT INTO stanza VALUES('CB350','2','Sa pagtoo nagpadayon’s tumong,<br/>Nisalig’s gugma, dad-on ka Niya;<br/>Gitabangan N’ya, hugot nagsunod,<br/>Hangtud pag-ampo ko matuman N’ya.<br/>',NULL,16993,2);
INSERT INTO stanza VALUES('CB350','3','Di igsapayang dalan usahay<br/>Lisud ug sakripisyoha’g dako,<br/>Nasayud S’ya pagkab-ot sa tumong,<br/>Hiktin gyung dalan paingon Niya.<br/>',NULL,16994,3);
INSERT INTO stanza VALUES('CB350','4','Usay nasayran, di ka-dili N’ya,<br/>Usay mahimo, gukdon ko Siya;<br/>Dios ko himaya sa adlaw-adlaw,<br/>Ug didto Siya m’oy dakong Balus.<br/>',NULL,16995,4);
INSERT INTO stanza VALUES('CB352','1','Alang’s Dios’ kamingawan!<br/>Komong sampinit nagsiga!<br/>Panalangini, Ginoo,<br/>Alang’s himaya’s Ngalan Mo.<br/>',NULL,16996,1);
INSERT INTO stanza VALUES('CB352','2','Dios, ako sampinit lang,<br/>Nga Imo nga kapuy-an;<br/>Pinaagi kanako<br/>Makapamulong Ka’s tawo,<br/>',NULL,16997,2);
INSERT INTO stanza VALUES('CB352','3','Pangandoy’g tuyo N’ya’s tawo,<br/>Sampinit magkalayo,<br/>Di’s kahayag dinhi’s yuta,<br/>Kondi’s Iyang himaya:<br/>',NULL,16998,3);
INSERT INTO stanza VALUES('CB352','4','Sa sampinit Dios mismo,<br/>M’oy siga nga makita;<br/>Himoa kong ingon Nimo,<br/>Maghimaya’s Ngalan Mo.<br/>',NULL,16999,4);
INSERT INTO stanza VALUES('CB357','1','Jesus, dad-i’g dasiga ko<br/>Sa balaan Mong kalayo,<br/>Hinloi sa dugo;<br/>Bugnai’s Kaugalingon Mo,<br/>Sa gahum Mo pabatia,<br/>Kay gianak Nimo.<br/>',NULL,17000,1);
INSERT INTO stanza VALUES('CB357','2','Gilansang’s krus uban Nimo,<br/>Kasingkasing di mabahin,<br/>Mabuhi na sa Dios.<br/>Patay na ko’s kalibutan,<br/>Sa kagarbo’g kalipayan;<br/>Ikawng himaya ko!<br/>',NULL,17001,2);
INSERT INTO stanza VALUES('CB357','3','Sa di matagbawng kauhaw,<br/>Patinguhaa Kanimo;<br/>Imong Kaugalingon<br/>Mao ray akong pangayo,<br/>Mabuhi Ka nako’s gahum,<br/>Sa tanan Kanimo.<br/>',NULL,17002,3);
INSERT INTO stanza VALUES('CB357','4','Sakopa ang pagbuot ko,<br/>Pakit-a’s sanag’s nawong Mo;<br/>Himoa Ginoo<br/>Nga kasingkasing ko gugma,<br/>Kinabuhi ko way mansa,<br/>Mahimong pagdayeg.<br/>',NULL,17003,4);
INSERT INTO stanza VALUES('CB358','1','Diosnong gugma labaw’s tanan,<br/>Kalipay’s langit nanaug;<br/>Kami himoang puy-anan,<br/>Purongpurongi’s kaluoy;<br/>Jesus maluloy-on gayud,<br/>Gugma Kang putli’g way sukod;<br/>Hatagi’s Imong kal’wasan,<br/>Tanang kasingkasing sudlan.<br/>',NULL,17004,1);
INSERT INTO stanza VALUES('CB358','2','Ginhawai’s Espiritu,<br/>Ang tanang naa’s kasubo;<br/>Diha Nimo manununod<br/>Sa pahulayng gisaad.<br/>Kuhaang pagpakasala;<br/>Alpa Ka ug Omega;<br/>Katapusan Ka’g sinugdan,<br/>Nagpagawas’ katawhan.<br/>',NULL,17005,2);
INSERT INTO stanza VALUES('CB358','3','Luwasa, Labing Gamhanan,<br/>Sa kinabuhi hatagan;<br/>Ang presensya Mo mag-uban,<br/>Templo Mo di na b’yaan.<br/>Kanunay Kang among daygon,<br/>Silbehan’s mauyonan,<br/>Ampoan, daygon’s way hunong,<br/>Sa gugma himayaon.<br/>',NULL,17006,3);
INSERT INTO stanza VALUES('CB358','4','Humana, bag-ong kabuhatan,<br/>Himoang putli’s tanan;<br/>Pakit-a’s dakong kal’wasan,<br/>Mauli’s kahingpitan.<br/>Usba, hangtud mahimaya,<br/>Halaran Ka’s purongpurong;<br/>Sa dihang Ikaw halaran,<br/>Diha’s katinga’s gugma.<br/>',NULL,17007,4);
INSERT INTO stanza VALUES('CB359','1','Hayagi, Kahayag,<br/>Dulom’s sala wad-a,<br/>Mugnai’g adlawan,<br/>Sa sulod hayagan!<br/>',NULL,17008,1);
INSERT INTO stanza VALUES('CB359','chorus','O labaw nga Kahayag,<br/>Magpuyo Ka’s kalag;<br/>Kasubo Imong wad-on,<br/>Sa kalipay pun-on.<br/>',NULL,17009,2);
INSERT INTO stanza VALUES('CB359','2','Dayon, O Kalipay!<br/>Wad-a ang kasubo,<br/>Hatagi’s kalinaw,<br/>Kalipay ko Ikaw!<br/>',NULL,17010,3);
INSERT INTO stanza VALUES('CB359','3','Buboi, Kinabuhi,<br/>Lamyang kamatayon;<br/>Pukawa’s sulod ko<br/>Ang kinabuhi Mo.<br/>',NULL,17011,4);
INSERT INTO stanza VALUES('CB359','4','Gugma, moagay Ka,<br/>Batoki ang sala,<br/>Sulod ko bag-oha;<br/>Gugma, moagay Ka.<br/>',NULL,17012,5);
INSERT INTO stanza VALUES('CB359','5','Kanaug, O Langit,<br/>Gisia nang tabil;<br/>Taposang kasamok;<br/>Kanaug, O Langit!<br/>',NULL,17013,6);
INSERT INTO stanza VALUES('CB359','6','Balik na, Ginoo!<br/>Himoa na ako<br/>Nga puy-anan Nimo;<br/>Balik na, Ginoo!<br/>',NULL,17014,7);
INSERT INTO stanza VALUES('CB362','1','Namatay S’ya alang nako,<br/>Aron mabuhi ko;<br/>Kinabuhi’g gugma, ihalad<br/>Alang Kaniya.<br/>',NULL,17015,1);
INSERT INTO stanza VALUES('CB362','chorus','Jesus, akong Manluluwas,<br/>O pasunda ako Nimo;<br/>Namatay Ka alang kanako,<br/>Mabuhi’g magsilbe Nimo.<br/>',NULL,17016,2);
INSERT INTO stanza VALUES('CB362','2','Sudlon ang ’yang kamatayon,<br/>Mamatay sa sala,<br/>Sa yawa ug kaugalingon,<br/>Tabangi, Ginoo.<br/>',NULL,17017,3);
INSERT INTO stanza VALUES('CB362','3','Nabuhi S’ya nagpasama<br/>Kanako Kaniya;<br/>Kinaiya’g kinabuhi,<br/>Siya ra’y madayag.<br/>',NULL,17018,4);
INSERT INTO stanza VALUES('CB362','4','Nabuhi aron ihatag<br/>Gugma N’ya’s nasubo;<br/>Alang’s uban mabuhi ko,<br/>Sama’s gibuhat N’ya.<br/>',NULL,17019,5);
INSERT INTO stanza VALUES('CB367','1','Labaw Ka, O Jesucristo,<br/>Way porma, pulong, credo,<br/>Iglesia ba’g gugma’s tawo,<br/>Makatandi Nimo.<br/>',NULL,17020,1);
INSERT INTO stanza VALUES('CB367','2','Labaw Ka, O Jesucristo,<br/>Gugma Mo nagsakop nako,<br/>Namatay na’s kaugalingon,<br/>Nabuhi Kanimo.<br/>',NULL,17021,2);
INSERT INTO stanza VALUES('CB367','3','Labaw Ka, O Jesucristo,<br/>Pun-a nang sulod ko;<br/>Samaha’s hunahuna Mo,<br/>Bisan sa pagbuot.<br/>',NULL,17022,3);
INSERT INTO stanza VALUES('CB367','4','Labaw Ka, O Jesucristo,<br/>Ang kinabuhi Mo<br/>Mag-usab’s kinabuhi ko,<br/>Himaya madayag.<br/>',NULL,17023,4);
INSERT INTO stanza VALUES('CB367','5','Labaw Ka, O Jesucristo,<br/>Nalipayng kalag ko,<br/>Magpaulipon, magtuman,<br/>Sa Imo nga gusto.<br/>',NULL,17024,5);
INSERT INTO stanza VALUES('CB368','1','Dugangi, Ginoo,<br/>Ang gugma ko.<br/>Dunggang pag-ampo ko<br/>Nga nagluhod;<br/>Ang hangyo ko kini:<br/>Duganging gugma ko<br/>Alang Nimo,<br/>O Ginoo.<br/>',NULL,17025,1);
INSERT INTO stanza VALUES('CB368','2','Kanhi pangandoy ko<br/>Kakawangan,<br/>Apan Ikaw karon<br/>Tinguha ko;<br/>Pag-ampo ko kini:<br/>Duganging gugma ko<br/>Alang Nimo,<br/>O Ginoo.<br/>',NULL,17026,2);
INSERT INTO stanza VALUES('CB368','3','Tugoting sugo Mo<br/>Nga kasubo;<br/>Magtuman sa buhat<br/>Dinhi nako,<br/>Aron makaawit,<br/>Duganging gugma ko<br/>Alang Nimo,<br/>O Ginoo.<br/>',NULL,17027,3);
INSERT INTO stanza VALUES('CB368','4','Ihunghong pagdayeg,<br/>Bisan pa sa<br/>Ulahing ginhawa<br/>Sa pagpanaw;<br/>Pag-ampo mao ra:<br/>Duganging gugma ko<br/>Alang Nimo,<br/>O Ginoo.<br/>',NULL,17028,4);
INSERT INTO stanza VALUES('CB371','1','Gikinahanglan Ka,<br/>Maluloy-ong Jesus;<br/>Malomong tingog Mo,<br/>Kalinaw ko.<br/>',NULL,17029,1);
INSERT INTO stanza VALUES('CB371','chorus','Akong gikinahanglan<br/>Sa tanang panahon;<br/>Panalangini karon,<br/>Ikaw duolon.<br/>',NULL,17030,2);
INSERT INTO stanza VALUES('CB371','2','Gikinahanglan Ka,<br/>Pabilin kanako;<br/>Panulay way gahum<br/>Kon duol Ka.<br/>',NULL,17031,3);
INSERT INTO stanza VALUES('CB371','3','Gikinahanglan Ka’s<br/>Kasubo’g kalipay,<br/>Kinabuhi kawang<br/>Kon wala Ka.<br/>',NULL,17032,4);
INSERT INTO stanza VALUES('CB371','4','Sa kabubut-on Mo<br/>Tudloi, Ginoo,<br/>Tumanang saad Mo<br/>Nganhi nako.<br/>',NULL,17033,5);
INSERT INTO stanza VALUES('CB371','5','Gikinahanglan Ka,<br/>Balaan sa tanan;<br/>Imoha na ako,<br/>O Ginoo.<br/>',NULL,17034,6);
INSERT INTO stanza VALUES('CB373','1','Way mag-ulang, walay mag-ulang;<br/>Sa Imong himaya<br/>Ako pakitaa,<br/>Kanimo padul-a—<br/>Way mag-ulang.<br/>',NULL,17035,1);
INSERT INTO stanza VALUES('CB373','2','Way mag-ulang, walay mag-ulang;<br/>Di Mo unta tugtan<br/>Nga sa kalibutan,<br/>Tingog Mo tabonan—<br/>Way mag-ulang.<br/>',NULL,17036,2);
INSERT INTO stanza VALUES('CB373','3','Way mag-ulang, walay mag-ulang;<br/>Walay kabalaka,<br/>Bisan mga luha,<br/>Ni kaugalingon—<br/>Way mag-ulang.<br/>',NULL,17037,3);
INSERT INTO stanza VALUES('CB373','4','Way mag-ulang, walay mag-ulang;<br/>Way pagduhaduha,<br/>Kahadlok mawala,<br/>Tungod kay naa Ka—<br/>Way mag-ulang.<br/>',NULL,17038,4);
INSERT INTO stanza VALUES('CB373','5','Way mag-ulang, walay mag-ulang;<br/>Kahayag maghayag,<br/>Way gabong magtabon,<br/>Ikaw ang magbuot—<br/>Way mag-ulang.<br/>',NULL,17039,5);
INSERT INTO stanza VALUES('CB373','6','Way mag-ulang, walay mag-ulang;<br/>Sa tanang pagpanaw,<br/>Makit-an ko Ikaw,<br/>Ubanan’s kalinaw—<br/>Way mag-ulang.<br/>',NULL,17040,6);
INSERT INTO stanza VALUES('CB373','7','Way mag-ulang, walay mag-ulang;<br/>Kasanag’s kahayag<br/>Mo maoy magdan-ag,<br/>Dinhi’s akong kalag—<br/>Way mag-ulang.<br/>',NULL,17041,7);
INSERT INTO stanza VALUES('CB377','1','Kon ang akong dalan<br/>Paingon sa krus,<br/>Kon Imong gitudlo<br/>Ako mag-antus,<br/>Balus unta ni’ni,<br/>Pakigsandurot<br/>Kanimo, Ginoo,<br/>Sa matag gutlo.<br/>',NULL,17042,1);
INSERT INTO stanza VALUES('CB377','2','Kon kuhaan’s yuta,<br/>Dugangi’s langit.<br/>Bisan sakitan man,<br/>Ako magdayeg;<br/>Kon pagbuot Mo nga<br/>Mabulag’s mahal,<br/>Mahiusa unta<br/>Labi pa Nimo.<br/>',NULL,17043,2);
INSERT INTO stanza VALUES('CB377','3','Dalan mamingaw man,<br/>Ikaw kauban;<br/>Dasiga’s pahiyom,<br/>Nga magpadayon;<br/>Grasya Mo saligan,<br/>“Ako” mawala,<br/>Maputling sudlanan,<br/>Mag-awas Nimo.<br/>',NULL,17044,3);
INSERT INTO stanza VALUES('CB378','1','Dad-a ako didto’s bungtod,<br/>Aron Ikaw makita;<br/>Madungog namo ang tingog,<br/>Gikan sa langit gayud.<br/>',NULL,17045,1);
INSERT INTO stanza VALUES('CB378','chorus','Dad-a ako didto’s bungtod,<br/>Makig-ambit Kanimo,<br/>Sa dan-ag nakitang tubod,<br/>Ug dugo Mo naghinlo.<br/>',NULL,17046,2);
INSERT INTO stanza VALUES('CB378','2','Labi pang kahayag didto,<br/>Wala nay panagbangi;<br/>Madayag ang kinabuhi<br/>Dihang Cristo maghari.<br/>',NULL,17047,3);
INSERT INTO stanza VALUES('CB378','3','Ampingi nga magpabilin,<br/>Sa tumong magpadayon,<br/>Hangtud Kanimo masama,<br/>Sa gugma ug sa grasya.<br/>',NULL,17048,4);
INSERT INTO stanza VALUES('CB380','1','Gihatag nga Kalan-on<br/>Alang’s dumuloong;<br/>Manna nga gikan’s langit,<br/>Tagbo’s gikin’hanglan;<br/>Dugay nang gitinguha,<br/>Ikaw pahimuslan,<br/>Hangtud kalipay’s yuta<br/>Mawa’, matagbaw na.<br/>',NULL,17049,1);
INSERT INTO stanza VALUES('CB380','2','Tubig sa kinabuhi<br/>Gikan’s Manluluwas,<br/>Tuboran Ka sa gugma,<br/>Lunsay nga nag-agas.<br/>Paimna mi’s way bayad,<br/>Pagkuha’s kauhaw;<br/>Katam-is di usikan,<br/>Dayong pahimuslan.<br/>',NULL,17050,2);
INSERT INTO stanza VALUES('CB380','3','Magpista kami Nimo,<br/>Simbahon Ka namo;<br/>Kasaligang Pulong Mo,<br/>Tooha’g dawaton.<br/>Tugoting dinhi’s yuta<br/>Ikinabuhi Ka;<br/>Wad-on untang salimbong<br/>Makita Ka’s nawong.<br/>',NULL,17051,3);
INSERT INTO stanza VALUES('CB382','1','Labi pa untang maila,<br/>Si Jesus ug ang grasya N’ya;<br/>Maila ang ’yang pagtubos,<br/>Gugma N’ya alang nako’s krus.<br/>',NULL,17052,1);
INSERT INTO stanza VALUES('CB382','chorus','Labi nga maila,<br/>Maila si Jesus;<br/>Mailang kaluwasan N’ya,<br/>Ug nagpakamatayng gugma.<br/>',NULL,17053,2);
INSERT INTO stanza VALUES('CB382','2','Labi pa untang masayud<br/>Sa ’yang balaang pagbuot;<br/>Espiritu’s Dios nagtudlo<br/>Kang Cristo dinhi kanako.<br/>',NULL,17054,3);
INSERT INTO stanza VALUES('CB382','3','Labi pang motoo’s Pulong,<br/>Makig-ambitay’s Ginoo;<br/>Madungog S’ya’s matag linya,<br/>Maako ang pamulong N’ya.<br/>',NULL,17055,4);
INSERT INTO stanza VALUES('CB382','4','Labi pa untang maila<br/>Kadato sa himaya N’ya;<br/>Pagtubo’s ’yang gingharian,<br/>Anus-a mi ’yang balikan.<br/>',NULL,17056,5);
INSERT INTO stanza VALUES('CB387','1','Nadungog kong pulong Mo, Ginoo,<br/>Nga ako gimahal Mo;<br/>Nangandoy ako diha’s pagtoo,<br/>Mahiduol Kanimo.<br/>',NULL,17057,1);
INSERT INTO stanza VALUES('CB387','chorus','Ipaduol, duol Kanimo,<br/>Sa krus gikamatyan Mo,<br/>Ipaduol, duol, ako Ginoo,<br/>Sa nagdugong kilid Mo.<br/>',NULL,17058,2);
INSERT INTO stanza VALUES('CB387','2','Igahin Mo ako’s pag-alagad,<br/>Pinaagi’s gahum Mo;<br/>Sa lig-ong paglaum pasaliga,<br/>Mawa’ng pagb’ot ko Nimo.<br/>',NULL,17059,3);
INSERT INTO stanza VALUES('CB387','3','O pagkalunsay sa kalipay ko,<br/>Panahon sa trono Mo;<br/>Sa dihang mag-ampo, uban Nimo<br/>Magsultiay daw abyan!<br/>',NULL,17060,4);
INSERT INTO stanza VALUES('CB387','4','Giladmon’s gugma di ko matugkad,<br/>Kon di pa igkita Ka;<br/>Kahabog’s kalipay makab-ot ra<br/>Kon ako mopahuway na.<br/>',NULL,17061,5);
INSERT INTO stanza VALUES('CB389','1','Ginoo, nangandoy akong mabuhi<br/>Sa Imong presensya buntag’ gabii;<br/>Kasingkasing di unta patagbawon<br/>Kon may gimahal nga magbulag nato.<br/>Matag gutlo’g adlaw’s tanang kasakit,<br/>Kon way makalipay o makadasig,<br/>Panghupaw’g paghilak dili kapugngan,<br/>Kalmaha, Ginoo, luha pahiri.<br/>',NULL,17062,1);
INSERT INTO stanza VALUES('CB389','2','Matag damgo’s kaayo’s kinabuhi,<br/>Mag-ampo, Ginoo, naa Ka ni’ni;<br/>Ayaw ko paako-akoa’g pili,<br/>Mangita ba’g kalipay gawas Nimo.<br/>Matag gabii kon maghigda na ko,<br/>Mag-ampo, Ginoo, duol Ka nako,<br/>Matag mokadlawon, samtang natulog,<br/>Hunghongi, tawga ko aron madungog.<br/>',NULL,17063,2);
INSERT INTO stanza VALUES('CB389','3','Matag basa’s Imong balaang Pulong,<br/>Hayagi’s himaya ang matag linya,<br/>Unsang Manlul’was ko tatawng makita,<br/>Ug kadako sa kal’wasang naako.<br/>Kon way mahimo, Ginoo, ludhan Ka,<br/>Mag-ampo kong dunggon ug grasyahan Mo,<br/>Kon may kakulangon ug di Mo dunggon,<br/>Ayaw itago nako Imong nawong.<br/>',NULL,17064,3);
INSERT INTO stanza VALUES('CB389','4','Matag dumdom’s langitnong kabulahan,<br/>Papangandoya kong malalin Nimo,<br/>Bugtong paglaum ko pagbalik Nimo,<br/>Presensya Mo bugtong kalipay dinhi.<br/>Tudloi, Ginoo, akong mabuhi,<br/>Sa Imong presensya buntag’ gabii,<br/>Kasingkasing di unta patagbawon,<br/>Kon may gimahal nga magbulag nato.<br/>',NULL,17065,4);
INSERT INTO stanza VALUES('CB390','1','Ginoo, giyahi ko<br/>Sa Imong Espiritu;<br/>Palakwon Mo’s kahayag,<br/>Di na ko makigbisug.<br/>',NULL,17066,1);
INSERT INTO stanza VALUES('CB390','chorus','Giyahi ko,<br/>Nag-ampo ko, Ginoo;<br/>Dad-a sa pagpalawom,<br/>Sa kinabuhi karon.<br/>',NULL,17067,2);
INSERT INTO stanza VALUES('CB390','2','Ikaw kinabuhi man,<br/>Nga maoy kasugoan;<br/>Kon Imo nga mandoan,<br/>Wala nay kangitngitan.<br/>',NULL,17068,3);
INSERT INTO stanza VALUES('CB390','3','Espiritu naghatag,<br/>Kagawasan sa kalag;<br/>Hunahuna bag-ohon,<br/>Pagbuot Mo lang sugton.<br/>',NULL,17069,4);
INSERT INTO stanza VALUES('CB395','1','Magtubo Ka unta nako,<br/>Ang uban mangahanaw;<br/>Paduola adlaw-adlaw,<br/>Sa sala magawas.<br/>',NULL,17070,1);
INSERT INTO stanza VALUES('CB395','chorus','Tabangi ko sa kusog Mo<br/>Sa kaluyahon ko;<br/>Sa kahayag wad-ang dulom,<br/>Wad-ang kamatayon.<br/>',NULL,17071,2);
INSERT INTO stanza VALUES('CB395','2','Ang kahayag Mo magwala,<br/>Dautang hunahuna;<br/>Wa ko’y bili, Ikawng tanan,<br/>Imo nga tudloan.<br/>',NULL,17072,3);
INSERT INTO stanza VALUES('CB395','3','Pakit-a pa’s himaya Mo,<br/>Putli Ka ug tinuod;<br/>Mahimong buhi Mong dagway,<br/>Sa kasadya’g kasubo.<br/>',NULL,17073,4);
INSERT INTO stanza VALUES('CB395','4','Pun-a’s kalipay’s itaas,<br/>Kupti sa diosnong kusog;<br/>Pasidlaka’s dakong gugma Mo,<br/>Tibuok kong pagkatawo.<br/>',NULL,17074,5);
INSERT INTO stanza VALUES('CB395','5','Pakubsang kaugalingon ko,<br/>Kinabuhi Ka’g tumong,<br/>Adlaw-adlaw sa grasya Mo,<br/>Maangay sa ngalan Mo.<br/>',NULL,17075,6);
INSERT INTO stanza VALUES('CB396','1','Nagpadayon sa pagtungas,<br/>Adlaw-adlaw sa itaas;<br/>Nag-ampo sa pagpadulong,<br/>“Didto Mo ako papuy-on.”<br/>',NULL,17076,1);
INSERT INTO stanza VALUES('CB396','chorus','Ginoo, pabaruga ko,<br/>Sa yutang-talad’s Canaan,<br/>Sa dapit nga labing habog,<br/>Didto Mo ako papuy-on.<br/>',NULL,17077,2);
INSERT INTO stanza VALUES('CB396','2','Way tinguha nga magpuyo<br/>Sa dapit nga may katahap;<br/>Bisan daghan ang nahaylo,<br/>Habog nga dapit ray gusto.<br/>',NULL,17078,3);
INSERT INTO stanza VALUES('CB396','3','Modaug ko’s kalibutan,<br/>Bisan sa yawa tirohan;<br/>Kay may awit sa pagdasig,<br/>Didto sa habog nga dapit.<br/>',NULL,17079,4);
INSERT INTO stanza VALUES('CB396','4','Sak-on ko ang kinatumyan,<br/>Aron himaya makit-an;<br/>Pag-ampo ko magpadayon,<br/>“Sa habog nga dapit dad-on.”<br/>',NULL,17080,5);
INSERT INTO stanza VALUES('CB397','1','Dugangi, Ginoo,<br/>Kabalaan ko,<br/>Duganging pailub<br/>Diha’s pag-antus;<br/>Duganging pagtoo<br/>Sa Manluluwas,<br/>Ug kalipay sa<br/>Pag-alagad Nimo.<br/>',NULL,17081,1);
INSERT INTO stanza VALUES('CB397','chorus','Ginoo, tabangi ko,<br/>Lipaya ug lig-ona;<br/>L’wason Mo matag gutlo,<br/>Gil’was Mo na karon.<br/>',NULL,17082,2);
INSERT INTO stanza VALUES('CB397','2','Duganging pagsalig,<br/>Pagpasalamat,<br/>Tinguha’s himaya,<br/>Paglaum’s Pulong,<br/>Duganging pagluha’s<br/>Kasub-anan N’ya,<br/>Kaaghop’s pagsulay,<br/>Pagdayeg’s paghupay.<br/>',NULL,17083,3);
INSERT INTO stanza VALUES('CB397','3','Duganging pagdaug,<br/>Kusog’s pagdaug,<br/>Paggawas sa yuta,<br/>Pag-agpas’ trono,<br/>Labing maangayan<br/>Sa gingharian,<br/>Labing mabalaan,<br/>Masama Nimo.<br/>',NULL,17084,4);
INSERT INTO stanza VALUES('CB398','1','Masama Nimo! Manunubos ko,<br/>Pangandoy ko kini’s kanunay;<br/>B’yaan ko tanang mahal sa yuta,<br/>Timbrihe ko sa Imong dagway.<br/>',NULL,17085,1);
INSERT INTO stanza VALUES('CB398','chorus','O samaha na, Manunubos ko,<br/>Samaha ako’s kaputli Mo;<br/>Anhia’s katam-is, kahupong Mo,<br/>Itimbreng dagway Mo kanako.<br/>',NULL,17086,2);
INSERT INTO stanza VALUES('CB398','2','Masama Nimo! puno’g kaluoy,<br/>Mapanggaon, lomo’g maayo;<br/>Tabang ug kadasig Ka’s naluya,<br/>Makasasala gipangita.<br/>',NULL,17087,3);
INSERT INTO stanza VALUES('CB398','3','Masama Nimo! mapaubsanon,<br/>Balaan, isug, may pailub;<br/>Hilom nag-antus’ grabeng kasaba,<br/>Aron maluwas Mo ang uban.<br/>',NULL,17088,4);
INSERT INTO stanza VALUES('CB398','4','Masama Nimo! nia karon ko,<br/>Magdawat’s balaang dihog Mo;<br/>Maimo, Ginoo, ning tungora<br/>Tanang pagkamao’g akoa.<br/>',NULL,17089,5);
INSERT INTO stanza VALUES('CB398','5','Samtang nag-ampo ako Kanimo,<br/>Pun-a ang sulod sa gugma Mo;<br/>Himoang templo puloy-anan Mo,<br/>Kinabuhing kahimut-an Mo.<br/>',NULL,17090,6);
INSERT INTO stanza VALUES('CB399','1','Mausab’s dagway N’ya!<br/>M’oy gitinguha!<br/>Tumana, Ginoo,<br/>Kalag dasiga.<br/>',NULL,17091,1);
INSERT INTO stanza VALUES('CB399','2','Mausab’s dagway N’ya!<br/>Espiritu S’ya!<br/>Magpadumala N’ya,<br/>Matumang gusto.<br/>',NULL,17092,2);
INSERT INTO stanza VALUES('CB399','3','Daw salamin ang nawong<br/>Nga walay tabon,<br/>Makitang himaya,<br/>Sumbalik’s grasya.<br/>',NULL,17093,3);
INSERT INTO stanza VALUES('CB399','4','Wa untay magtabon,<br/>Maghanap Niya,<br/>Makapasumbalik<br/>Kan’ya’s kaputli.<br/>',NULL,17094,4);
INSERT INTO stanza VALUES('CB399','5','Tutok’s himaya N’ya,<br/>Nawong sa nawong;<br/>Sigeng magtan-aw N’ya,<br/>Hangtud sa dayon.<br/>',NULL,17095,5);
INSERT INTO stanza VALUES('CB399','6','Mausab’s dagway N’ya!<br/>Bugtong tinguha,<br/>Ipasumbalik S’ya<br/>Aron madayag.<br/>',NULL,17096,6);
INSERT INTO stanza VALUES('CB399','7','Mausab’s dagway N’ya,<br/>Isumbalik pa,<br/>Himaya’s himaya,<br/>Sigeng magdugang.<br/>',NULL,17097,7);
INSERT INTO stanza VALUES('CB403','1','Mabuhi Ka, Jesus, nako,<br/>Ikaw kinabuhi ko;<br/>Sa tanan ko nga problema<br/>Ikaw hingpit nga sulbad.<br/>Mabuhi Ka gikan nako,<br/>Tanan Ikaw magbuot,<br/>Kay ako sudlanan lamang,<br/>Magpadayag sa Anak.<br/>',NULL,17098,1);
INSERT INTO stanza VALUES('CB403','2','Hinalad kining templo Mo,<br/>Hininloan’s kahugaw;<br/>Kalayo sa himaya Mo<br/>Madayag gikan’s sulod.<br/>Maghilom tibuok yuta,<br/>Lawas andam ihalad,<br/>Maulipong masugtanon,<br/>Gipalihok ra Nimo.<br/>',NULL,17099,2);
INSERT INTO stanza VALUES('CB403','3','Binaksan, naghulat’s sugo,<br/>Matag bahin, ’tag gutlo;<br/>Maghago suma’s plano Mo,<br/>O ipadaplin Nimo.<br/>Kon mapugngan man’s tinguha,<br/>Di masamok, matugaw;<br/>Sa kasaligang pagbatok,<br/>Way pagmahay’g bagutbot.<br/>',NULL,17100,3);
INSERT INTO stanza VALUES('CB403','4','Lomong pahulay, kalinaw,<br/>Kay way akoang laraw,<br/>Gawasnon Kang makabuot,<br/>Magtudlo sa dalan ko.<br/>Mabuhi Ka gikan nako,<br/>Ikaw kinabuhi ko;<br/>Sa tanan ko nga problema<br/>Ikaw hingpit nga sulbad.<br/>',NULL,17101,4);
INSERT INTO stanza VALUES('CB405','1','Kalibutan nakita na,<br/>Pabutaha pag-usab;<br/>Basi’g mawad-an’s Presensya<br/>Nga akong Gikalipay.<br/>',NULL,17102,1);
INSERT INTO stanza VALUES('CB405','chorus','Kalibutan nakita na,<br/>Pabutaha pag-usab,<br/>Basi’g mawad-an’s Presensya,<br/>Nga akong Gikalipay.<br/>',NULL,17103,2);
INSERT INTO stanza VALUES('CB405','2','Kadlawon, kilom-kilom ba,<br/>Didto makita ko ra;<br/>Apan samtang gikaloy-an,<br/>Pagkabuta igo na.<br/>',NULL,17104,3);
INSERT INTO stanza VALUES('CB405','3','Di na gustong makagawas<br/>Sa tunok, kon may grasya;<br/>Kon himaya N’ya maghayag<br/>Sa nawong ko’s kasanag.<br/>',NULL,17105,4);
INSERT INTO stanza VALUES('CB405','4','Sa kadulom, ’yang katahum<br/>Mahikap ko’s pagtoo;<br/>Gidumtan S’ya’g gikataw-an,<br/>Himaya N’ya’y nakit-an.<br/>',NULL,17106,5);
INSERT INTO stanza VALUES('CB405','5','Pagkalabaw’s ’yang himaya,<br/>Sa Adlaw ba o Bulan,<br/>Ulong gipuronga’g tunok,<br/>Labaw’g himaya’s tanan.<br/>',NULL,17107,6);
INSERT INTO stanza VALUES('CB406','1','Tudloi, Ginoo,<br/>Sa dalan Mo;<br/>Tabangan Mo ako<br/>Sa grasya Mo.<br/>Maglakaw’s pagtoo,<br/>Dili sa makita;<br/>Dad-a sa kahayag,<br/>Tudloi ko.<br/>',NULL,17108,1);
INSERT INTO stanza VALUES('CB406','2','Kon magduhaduha,<br/>Tudloan Mo;<br/>Kon unos moabot,<br/>Tudloan Mo.<br/>May panganud, ulan,<br/>Kahago’g kasubo,<br/>Sidlaki’g i’dayag<br/>Ang dalan Mo.<br/>',NULL,17109,2);
INSERT INTO stanza VALUES('CB406','3','Tibu’k kinabuhi,<br/>Tudloan Mo;<br/>Unsa may dangatan,<br/>Tudloan Mo.<br/>Hangtud gyud mahuman,<br/>Lumbang gidaganan,<br/>Korona madag-an,<br/>Tudloan Mo.<br/>',NULL,17110,3);
INSERT INTO stanza VALUES('CB408','1','Ginoo, pangandoy ko nga mahingpit,<br/>Ikaw mabuhi sulod sa kalag ko;<br/>Gub-a tanang diosdios ug kaaway ko,<br/>Hinloi aron moputi pa’s nieve.<br/>',NULL,17111,1);
INSERT INTO stanza VALUES('CB408','chorus','Sa kaputi labaw sa nieve;<br/>Hinloi ko labaw pa kaysa nieve.<br/>',NULL,17112,2);
INSERT INTO stanza VALUES('CB408','2','Ginoong Jesus, itugot Mo unta<br/>Ang kinabuhi ko mawalay mansa;<br/>Mahinloan sa dugo ug maputli,<br/>Hinloi aron moputi pa’s nieve.<br/>',NULL,17113,3);
INSERT INTO stanza VALUES('CB408','3','Ginoo, tan-aw gikan sa trono Mo,<br/>Ug tabanging mahingpit ko’ng halad Mo;<br/>Itugyang kaugalingo’g nahibal-an,<br/>Hinloi aron moputi pa’s nieve.<br/>',NULL,17114,4);
INSERT INTO stanza VALUES('CB408','4','Mapaubsanon gyung mangamuyo ko,<br/>Sa tiilan sa gilansangan Nimo,<br/>Nitoo kong mahinloan’s dugo Mo;<br/>Hinloi aron moputi pa’s nieve.<br/>',NULL,17115,5);
INSERT INTO stanza VALUES('CB408','5','Nakita Mong naghuwat mapailubon,<br/>Sa bag-ong kasingkasing mugnai ko,<br/>Sa nangita di gyud Ka mobalibad,<br/>Hinloi aron moputi pa’s nieve.<br/>',NULL,17116,6);
INSERT INTO stanza VALUES('CB412','1','Padaygi’s Kaugalingon,<br/>Aron unod maila;<br/>Grasya Mo pabuhata,<br/>Aron maghinulsol ko.<br/>Tinguha kong modaug,<br/>Apan luya gyud ka’yo;<br/>Di ’kabiya’s dautan,<br/>Di ’kahimo’s maayo.<br/>',NULL,17117,1);
INSERT INTO stanza VALUES('CB412','2','Gusto ko S’ya sa sulod,<br/>Gawi ko makalagot;<br/>Bisan bu’t, di mausab,<br/>Nagapos gyung tinuod!<br/>Sa sugo N’ya nakita<br/>Ako nagapos’ sala;<br/>Bisan bu’t makagawas,<br/>Wala may makaluwas.<br/>',NULL,17118,2);
INSERT INTO stanza VALUES('CB412','3','Sigeng katumba’g bangon,<br/>Kapila na maghukom;<br/>Gusto untang modaug,<br/>Pakyas ko kay misibog.<br/>Nahalin na sa sala,<br/>Kusog ko nangawala;<br/>Sa unod way maayo,<br/>Masal-anon kaayo.<br/>',NULL,17119,3);
INSERT INTO stanza VALUES('CB412','4','Nailang kaugalingon,<br/>Way mahimo, giangkon;<br/>Taras ko lain gayud,<br/>Kinabuhi sab dunot.<br/>Way salig’s kaugalingon,<br/>Sa unodnon bang kusog;<br/>Pagsalig, paglaum ko,<br/>Naa tanan Kanimo.<br/>',NULL,17120,4);
INSERT INTO stanza VALUES('CB412','5','Patyon unta ko sa Krus,<br/>Aron Cristo saligan;<br/>Pun-on unta’s Esp’ritu,<br/>Aron S’ya magamit ko.<br/>Patyon’s ’yang kamatayon,<br/>Unta sa magkalalum;<br/>Kaugalingon malaglag,<br/>Magpuno S’ya sa kalag.<br/>',NULL,17121,5);
INSERT INTO stanza VALUES('CB412','6','Kapait’s kahimtang ko!<br/>Kinsay magluwas nako,<br/>Gikan ning kamatayon,<br/>Sa kadaugang dayon?<br/>Dugo N’ya giula na,<br/>S’yay pagkabalaan ko;<br/>Kinabuhi gidawat,<br/>Cristo way sukod—pahat.<br/>',NULL,17122,6);
INSERT INTO stanza VALUES('CB412','7','Hingpit nagahin karon,<br/>Nagsugot sa ’yang pulong;<br/>Di na gyud ko maulaw<br/>Moduol sa Ginoo.<br/>Ning kinabuhing labaw!<br/>Grasyang hatag’s pagtoo,<br/>Daygon, gidungog Niya<br/>Ampo kong mahigawas.<br/>',NULL,17123,7);
INSERT INTO stanza VALUES('CB413','1','Jesus, tan-awa ako,<br/>Hatagi ko’s kayano;<br/>Pakab’sa, paaghopa,<br/>Mangita Kanimo ra.<br/>',NULL,17124,1);
INSERT INTO stanza VALUES('CB413','2','Gilutas’ pagbuot ko,<br/>Ug sa akong kahakog;<br/>Sa pagkamayubiton,<br/>Ug kahangol nga daygon.<br/>',NULL,17125,2);
INSERT INTO stanza VALUES('CB413','3','Isalikway ang tanang<br/>Makapagarbong butang;<br/>Pagbuot ipasakop,<br/>Sa tiilan ni Jesus.<br/>',NULL,17126,3);
INSERT INTO stanza VALUES('CB413','4','Himoang sama’s bata,<br/>Kaalam mangawala;<br/>Makakita’s kahayag,<br/>Maglakaw ra’s gahum Mo.<br/>',NULL,17127,4);
INSERT INTO stanza VALUES('CB413','5','Magpa’raray’s dughan Mo,<br/>Ang gikapoyng kalag ko;<br/>Dunay kalinaw sa Dios<br/>Tungod’s mahal Mong dugo.<br/>',NULL,17128,5);
INSERT INTO stanza VALUES('CB413','6','Magpabilin’s dughan Mo,<br/>Adlaw-adlaw magdayeg;<br/>Hangtud’s kamatayon ko,<br/>Sa gihapon magdayeg.<br/>',NULL,17129,6);
INSERT INTO stanza VALUES('CB423','1','Natago nga gugma sa Dios,<br/>Taas, lalum, way nasayud,<br/>Nalantaw kong kahayag Mo,<br/>Naghandom dayon’s pahulay;<br/>Kasakit wa gyuy alibyo,<br/>Kay kini naa ra Nimo.<br/>',NULL,17130,1);
INSERT INTO stanza VALUES('CB423','2','Tingog Mo maoy nagdani<br/>Nga sangonon kong yugo Mo;<br/>Gusto ko untang dawaton,<br/>Apan mabalhinbalhinon;<br/>Giulangan sa kanunay;<br/>Ika’y tumong, masaag pa.<br/>',NULL,17131,2);
INSERT INTO stanza VALUES('CB423','3','Kaluoyng gipatinguha,<br/>Sa kalinaw’s hunahuna;<br/>Gipangita Ka, napakyas,<br/>Kalag wala gyuy kalinaw;<br/>Anus-a pa di maglaag,<br/>Paingon Nimo ang lakang.<br/>',NULL,17132,3);
INSERT INTO stanza VALUES('CB423','4','Unsa man ang makailog<br/>Pagdani’s kasingkasing ko?<br/>O tangtangon unta Nimo,<br/>Magbuot Ka’s tanang lihok.<br/>Unya’s yuta mahigawas,<br/>Makapahuway na ko Nimo.<br/>',NULL,17133,4);
INSERT INTO stanza VALUES('CB423','5','Tagoi ang kaugalingon;<br/>Mabuhi Ka gikan nako;<br/>Wad-on Mong unodnong gusto,<br/>Di binlan sa usang bisyo.<br/>Way lain untang makita’g<br/>Tinguhaon gawas Nimo.<br/>',NULL,17134,5);
INSERT INTO stanza VALUES('CB423','6','Ipahaluna Mong tabang,<br/>Luwasa Ko’s kabalaka;<br/>Wad-a tanang pagbuot ko,<br/>Bisan ang na’s kahiladman.<br/>Anak untang masugtanon,<br/>Magsige’g “Abba, Amahan.”<br/>',NULL,17135,6);
INSERT INTO stanza VALUES('CB423','7','Matag gutlo ipalayo<br/>Sa yuta, maghuwat’s tawag Mo;<br/>Kalag ko sultii ni’ni:<br/>“Akong gugma, Dios, tanan mo.“<br/>Gahum, tingog Mo mabati,<br/>Gugma manamnam, gipili.<br/>',NULL,17136,7);
INSERT INTO stanza VALUES('CB426','1','Kuhaang taptap ko<br/>Aron mahayagan,<br/>Di na malimbongan,<br/>Makit-an gyung tanan.<br/>',NULL,17137,1);
INSERT INTO stanza VALUES('CB426','chorus','Kahayag’s kinabuhi,<br/>Wad-a nang kangitngit;<br/>Karon dan-agi ako,<br/>Kini giampo ko.<br/>',NULL,17138,2);
INSERT INTO stanza VALUES('CB426','2','Sa kaugalingon ko<br/>Wala makaila;<br/>Gilimbongan’s garbo,<br/>Hambog ra kaayo.<br/>',NULL,17139,3);
INSERT INTO stanza VALUES('CB426','3','Sa Kaugalingon Mo<br/>Kulang’s pagkaila;<br/>Pulong la’g doktrina,<br/>Kulang gyud sa bugna.<br/>',NULL,17140,4);
INSERT INTO stanza VALUES('CB426','4','Sa kinabuhi Mo<br/>Kulang’s pagkaila;<br/>Unod, espiritu,<br/>Usahay magbaylo.<br/>',NULL,17141,5);
INSERT INTO stanza VALUES('CB426','5','Sagad sa dalan Mo,<br/>Di gyud ko kaklaro;<br/>Kay nag-inusara,<br/>Dali nga masaag.<br/>',NULL,17142,6);
INSERT INTO stanza VALUES('CB426','6','Sa kabubut-on Mo,<br/>Wa masayud ka’yo,<br/>Kanunayng pulihan’s,<br/>Kaugalingong gusto.<br/>',NULL,17143,7);
INSERT INTO stanza VALUES('CB426','7','Sa Imong iglesia<br/>Bugnaan Mo ako,<br/>Aron makaila’s<br/>Kinabuhi’s Lawas.<br/>',NULL,17144,8);
INSERT INTO stanza VALUES('CB426','8','Wala unta’y taptap,<br/>Klaro gyud sa tanan,<br/>Di na malimbongan,<br/>Monunot ba’s garbo.<br/>',NULL,17145,9);
INSERT INTO stanza VALUES('CB430','1','Kon naa’s natural nga tawo,<br/>Unsa gyud kakusganon ko;<br/>Wa masayud, wa kakita,<br/>Nga luya ka’yo.<br/>',NULL,17146,1);
INSERT INTO stanza VALUES('CB430','2','Sa naa pa’s kalibutan,<br/>Wa mabating kapakyasan,<br/>Nangandak pa’s panlimbasug,<br/>Nga nag-uswag ko.<br/>',NULL,17147,2);
INSERT INTO stanza VALUES('CB430','3','Sa na’ pa ko’s kangitngitan,<br/>Di kasulti’s kamabaw ko;<br/>Abi ko’g nanghawod ko’s tanan,<br/>Nagpasigarbo.<br/>',NULL,17148,3);
INSERT INTO stanza VALUES('CB430','4','Sa nakaduol na Nimo,<br/>Hayag Mo nagbutyag nako,<br/>Nakita ang kaugalingon,<br/>Nga wa makita.<br/>',NULL,17149,4);
INSERT INTO stanza VALUES('CB430','5','Nidulot ang kahayag Mo,<br/>Nagtunaw’s tanang kusog ko;<br/>Nagpaubos diha’s abug,<br/>Wala nay garbo.<br/>',NULL,17150,5);
INSERT INTO stanza VALUES('CB430','6','Pagkabuta’g buang’s garbo,<br/>Nga naglig-on sa kalag ko;<br/>Garbong gula’s kasingkasing,<br/>Nagpakontento.<br/>',NULL,17151,6);
INSERT INTO stanza VALUES('CB430','7','Wa may maangkon ang garbo,<br/>Way bahin ko nga perfecto,<br/>Kaulaw ra ug pagmahay,<br/>Di ko kaampo.<br/>',NULL,17152,7);
INSERT INTO stanza VALUES('CB430','8','Sa paghukom dugo nagl’was,<br/>Sa kasuko, kinabuhi;<br/>Unsa diay ko kahugaw<br/>Ug pagkakabus.<br/>',NULL,17153,8);
INSERT INTO stanza VALUES('CB430','9','Moampo ko, way pagtoo,<br/>Gitinguha, Ikawng mao;<br/>Mabag-o bang kasingkasing,<br/>Kaloy-i ako.<br/>',NULL,17154,9);
INSERT INTO stanza VALUES('CB433','1','Iya na ko! Kalipayng di maasoy,<br/>Tam-is nga tubag sa gugma Niya;<br/>Malipayong “Oo’s” ’yang “Ay’g kahadlok,<br/>Gitubos ka Nako, Akoa ka.”<br/>',NULL,17155,1);
INSERT INTO stanza VALUES('CB433','2','Iya na ko! Pagsugid malipayon,<br/>Asawa sa kasal nahinumdom;<br/>Sa pagdawat Kaniya hangtud’s dayon,<br/>S’ya higugmaon, tahuron, sugton.<br/>',NULL,17156,2);
INSERT INTO stanza VALUES('CB433','3','Iya na ko! Tudloi’s kahulogan,<br/>Sa paghigugma ug pag-unongay,<br/>Pag-alagad ug hugot nga pagtugyan,<br/>Way panaganang pagsugot Nimo.<br/>',NULL,17157,3);
INSERT INTO stanza VALUES('CB433','4','Iya na! Lawas, kalag, espiritu,<br/>Iya na! Di na gyud mabawi pa;<br/>Maingon nga Ikaw, Hinigugma ko,<br/>Sa way katapusan akoa na.<br/>',NULL,17158,4);
INSERT INTO stanza VALUES('CB436','1','Kinabuhing hatag,<br/>Dugong giula Mo,<br/>Naglukat, nagbuhi<br/>Kanako, Ginoo.<br/>Kinabuhi gihatag Mo,<br/>Unsay gihatag ko?<br/>',NULL,17159,1);
INSERT INTO stanza VALUES('CB436','2','Nigugol Ka’g mga<br/>Tuig sa kasakit,<br/>Aron masayran ko<br/>Ang himaya’s dayon;<br/>Nigugol Ka’g mga tuig,<br/>Unsay gibalus ko?<br/>',NULL,17160,2);
INSERT INTO stanza VALUES('CB436','3','Puy-anang mahayag<br/>Ug Imo nga trono,<br/>Gib’yaan Mong tanan<br/>Dinhi nagdumu’ong;<br/>Tungod nako gib’yaan Mo,<br/>Unsay gib’yaan ko?<br/>',NULL,17161,3);
INSERT INTO stanza VALUES('CB436','4','Kapait giantus<br/>Walay makaasoy,<br/>Luwason lang ako<br/>Gikan sa impyerno;<br/>Alang nako giantus Mo,<br/>Unsay ibalus ko?<br/>',NULL,17162,4);
INSERT INTO stanza VALUES('CB436','5','Gidad-an Mo’s hingpit<br/>Kal’wasang way bayad,<br/>Pagpasaylo’g gugma<br/>Nga gikan’s itaas;<br/>Dagkong gasa gihatag Mo,<br/>Unsa ang balus ko?<br/>',NULL,17163,5);
INSERT INTO stanza VALUES('CB436','6','Kinabuhi halad<br/>Alang lang Kanimo,<br/>Kalipayng Kanimo<br/>Mag-antus’ kalisud;<br/>Gitugyan Mong Kaugalingon,<br/>Maghalad ko Nimo.<br/>',NULL,17164,6);
INSERT INTO stanza VALUES('CB437','1','Nakita mo na ba Siya?<br/>Kasingkasing bihag ba?<br/>Piliang labing maayo,<br/>Una Siya’s linibo.<br/>',NULL,17165,1);
INSERT INTO stanza VALUES('CB437','chorus','Nabihag’s Iyang katahum,<br/>Halaran’s angay Niya;<br/>Kabililhon N’ya magdasig,<br/>Purongan S’ya nga Hari.<br/>',NULL,17166,2);
INSERT INTO stanza VALUES('CB437','2','Kanhing diosdios nga nagdani,<br/>Hiligugmaong butang;<br/>Gipatahum, makahaylo,<br/>Aron balikbalikan.<br/>',NULL,17167,3);
INSERT INTO stanza VALUES('CB437','3','Unsay makabakwi namo’s<br/>Katahum nga naglimbong?<br/>Dili sugo’s katungdanan,<br/>Pagkakita ra Niya.<br/>',NULL,17168,4);
INSERT INTO stanza VALUES('CB437','4','Di pagdugmok’s mga diosdios,<br/>Kondi’ sa pagsidlak N’ya;<br/>Makita ang ’yang katahum,<br/>Kasingkasing madayag.<br/>',NULL,17169,5);
INSERT INTO stanza VALUES('CB437','5','Kinsay mopalong sa suga,<br/>Kon Adlaw di motungha?<br/>Kinsay mohukas sa kupo,<br/>Kon di pa ang ting-init?<br/>',NULL,17170,6);
INSERT INTO stanza VALUES('CB437','6','Tan-awng nagtunaw ni Pedro,<br/>Nawong nakitang Esteban;<br/>Uban ni Maria’g bakho,<br/>Ang magdani kanato.<br/>',NULL,17171,7);
INSERT INTO stanza VALUES('CB437','7','Daniha ug pun-a ako,<br/>Hangtud mapuno Nimo;<br/>Unsay kalabutan’s diosdios<br/>Sa mga kauban Mo?<br/>',NULL,17172,8);
INSERT INTO stanza VALUES('CB438','1','Gitalikdang kalibutan,<br/>Ug kawang kalipayan,<br/>Kasingkasing gikiling ko<br/>Sa mas maayong butang;<br/>Wa nay gilak’s kakawangan,<br/>Nga magbuta kanako;<br/>Kay gib’yaan ko na’s layo,<br/>Ug di na gyud balikan.<br/>',NULL,17173,1);
INSERT INTO stanza VALUES('CB438','chorus','Gib’yaan’s layo!<br/>Gib’yaan’s layo!<br/>Nakalabang sa nag-ulang,<br/>Kalibutan gib’yaan.<br/>',NULL,17174,2);
INSERT INTO stanza VALUES('CB438','2','Gib’yaan ko na ang sala,<br/>Ug tanang kahilayan;<br/>Baruganan ko Cristo na,<br/>Saad N’ya gidawat ko;<br/>Mapalgan ko’s kalibutan<br/>Ilalum sa krus Niya;<br/>Nilabang na’s kamatayon<br/>Ngadto sa kinabuhi.<br/>',NULL,17175,3);
INSERT INTO stanza VALUES('CB438','chorus','Gib’yaan’s layo!<br/>Gib’yaan’s layo!<br/>Nilabang na’s kamatayon<br/>Ngadto sa kinabuhi.<br/>',NULL,17176,4);
INSERT INTO stanza VALUES('CB438','3','Di ko na gyud balikan pa<br/>Pagkabutang ko kanhi,<br/>Dinhi rang kalinawng hingpit,<br/>Pahulay gikan’s hukom;<br/>Lain na ang agalon ko,<br/>Panaad ko tumanon,<br/>Kalibutan gibiyaan<br/>Hangtud gayud sa dayon.<br/>',NULL,17177,5);
INSERT INTO stanza VALUES('CB438','chorus','Gib’yaan’s layo!<br/>Gib’yaan’s layo!<br/>Kalibutan gibiyaan<br/>Hangtud gayud sa dayon.<br/>',NULL,17178,6);
INSERT INTO stanza VALUES('CB438','4','Pagpili ko hangtud’s dayon,<br/>Way laing Manluluwas;<br/>Di mangayo sa kalipay,<br/>Gawas sa gugma Niya;<br/>Kasingkasing naa ra N’ya,<br/>Di na mabutaan pa;<br/>Nilabang’s kamatayon N’ya,<br/>Gib’yaang kalibutan.<br/>',NULL,17179,7);
INSERT INTO stanza VALUES('CB438','chorus','Gib’yaan’s layo!<br/>Gib’yaan’s layo!<br/>Nilabang’s kamatayon N’ya,<br/>Gib’yaang kalibutan.<br/>',NULL,17180,8);
INSERT INTO stanza VALUES('CB439','1','Hingpit nga magahin<br/>Sa Espiritu!<br/>Nagtinguha’s tanang<br/>Kahupnganan N’ya;<br/>Tangtangan’s naggapos<br/>Ug magpalalum<br/>Sa dakong gahum N’yang<br/>Magl’was, mag-amping.<br/>',NULL,17181,1);
INSERT INTO stanza VALUES('CB439','chorus','Hingpit nga magahin’s<br/>Ginoo’s tanan,<br/>Tanan N’ya agpason,<br/>Tawag tubagon.<br/>',NULL,17182,2);
INSERT INTO stanza VALUES('CB439','2','Hingpit nga magahin<br/>Sa Espiritu!<br/>Nagkaunlod “ako“<br/>Hangtud mawala!<br/>Sudlanan mabasyo,<br/>Madugmok’s hingpit;<br/>Maghuwat’s pagpuno,<br/>Buhat mahuman.<br/>',NULL,17183,3);
INSERT INTO stanza VALUES('CB439','3','Hingpit nga magahin’s<br/>Kabubut-on N’ya;<br/>Maglakaw sa dalan<br/>Nga ’yang gilakwan;<br/>B’yaang kaharuhay,<br/>S’yay pilion ko,<br/>Maghuwat’s paggiya N’ya,<br/>Manimati N’ya.<br/>',NULL,17184,4);
INSERT INTO stanza VALUES('CB439','4','Hingpit nga magahin!<br/>Hangtud sa dayon;<br/>Di gyud ko magbuot,<br/>S’ya ray pabut-on;<br/>Plano’g pangandoy ko<br/>Mawa’s ’yang gusto,<br/>Way ako, tag-iya’s<br/>Tanan diha N’ya.<br/>',NULL,17185,5);
INSERT INTO stanza VALUES('CB439','5','Hingpit nga magahin!<br/>Katam-is ni’ni,<br/>Mabihag’s gugma N’ya,<br/>Pero gawasnon;<br/>Way salang maghari,<br/>Duda’g kahadlok,<br/>Walay kabalaka,<br/>Kasubo’g luwan.<br/>',NULL,17186,6);
INSERT INTO stanza VALUES('CB439','6','Hingpit nga magahin!<br/>Pahulayng tam-is,<br/>Maghuwat’s presensya N’ya,<br/>Sa tiilan N’ya;<br/>Maghuwat nga ’yang pun-on<br/>Sa Espiritu,<br/>Mag-ulay’s sulod ko<br/>Nga mga bahin.<br/>',NULL,17187,7);
INSERT INTO stanza VALUES('CB439','7','Pun-on’s Espiritu<br/>Sa presensya N’ya!<br/>Bulahan diha N’ya!<br/>Hingpit diha N’ya!<br/>Kahayag’s sulod ko<br/>Di gyud mopid-ok,<br/>Magahin, mabuhi<br/>Lang ko Kaniya!<br/>',NULL,17188,8);
INSERT INTO stanza VALUES('CB441','1','Tanan itugyan kang Jesus,<br/>Malipayong magtugyan;<br/>Higugmaon S’ya’g saligan,<br/>Mabuhi’s presensya N’ya.<br/>',NULL,17189,1);
INSERT INTO stanza VALUES('CB441','chorus','Tanan itugyan,<br/>Tanan itugyan.<br/>Alang Nimo, Manluluwas,<br/>Tanan itugyan.<br/>',NULL,17190,2);
INSERT INTO stanza VALUES('CB441','2','Mapaubsanong magtugyan<br/>Sa Imo nga tiilan;<br/>Kalibutan akong b’yaan,<br/>Dawata ako karon.<br/>',NULL,17191,3);
INSERT INTO stanza VALUES('CB441','3','Tanan itugyan Kanimo,<br/>Angkona ako’s hingpit;<br/>Pabatia’s Espiritu,<br/>Masayrang akoa Ka.<br/>',NULL,17192,4);
INSERT INTO stanza VALUES('CB441','4','Tanan itugyan lakip na<br/>Ang akong kaugalingon;<br/>Pun-a’s gugma’g gahum Nimo,<br/>Panalangini ako.<br/>',NULL,17193,5);
INSERT INTO stanza VALUES('CB441','5','Tanan itugyan Kanimo,<br/>Pabatia’s kalayo;<br/>O kalipay’s kaluwasan!<br/>Himayaong ngalan Mo!<br/>',NULL,17194,6);
INSERT INTO stanza VALUES('CB444','1','Tanan ihalad kang Jesus,<br/>Tibu’k kong pagkatawo;<br/>Tanang buhat, sinultian,<br/>Tanang adlaw ug takna.<br/>Tanan ihalad kang Jesus!<br/>Tanang adlaw ug takna.<br/>Tanan ihalad kang Jesus,<br/>Tanang adlaw ug takna!<br/>',NULL,17195,1);
INSERT INTO stanza VALUES('CB444','2','Kamot alang N’ya magbuhat,<br/>Tiil alang’s dalan N’ya;<br/>Mata S’ya ra ang tutokan;<br/>Ngabil alang’s pagdayeg.<br/>Ang tanan alang kang Jesus!<br/>Ngabil alang’s pagdayeg.<br/>Ang tanan alang kang Jesus!<br/>Ngabil alang’s pagdayeg.<br/>',NULL,17196,2);
INSERT INTO stanza VALUES('CB444','3','Garbo sa tanang katawhan<br/>Ang kadato ug dungog;<br/>Apan kini dulaan lang<br/>Nga hinimo sa abug.<br/>Ang tanan alang kang Jesus!<br/>Si Jesus lang saligan.<br/>Ang tanan alang kang Jesus!<br/>Si Jesus lang saligan.<br/>',NULL,17197,3);
INSERT INTO stanza VALUES('CB444','4','Sukad S’yay gitutokan ko,<br/>Wa nay laing gitagad,<br/>Panan-awon’s espiritu<br/>Nagtutok sa Gilansang,<br/>Ang tanan alang kang Jesus!<br/>Nagtutok sa Gilansang.<br/>Ang tanan alang kang Jesus!<br/>Nagtutok sa Gilansang.<br/>',NULL,17198,4);
INSERT INTO stanza VALUES('CB444','5','Hari Ka sa mga hari,<br/>Mahimayaong Jesus,<br/>Papahulayon Mo ako<br/>Ilalum’s Imong pako.<br/>Ang tanan alang kang Jesus!<br/>Magpahulay’s ’yang pako.<br/>Ang tanan alang kang Jesus!<br/>Magpahulay’s ’yang pako.<br/>',NULL,17199,5);
INSERT INTO stanza VALUES('CB445','1','Kinabuhi ihalad,<br/>Kanimo, O Ginoo;<br/>Tanang takna’g adlaw ko,<br/>Way hunong magdayeg Nimo,<br/>Way hunong magdayeg Nimo.<br/>',NULL,17200,1);
INSERT INTO stanza VALUES('CB445','2','Kamot ko palihoka<br/>Sa sugo’s Imong gugma;<br/>Tiil ko padagana,<br/>Sa Maayong Balita,<br/>Sa Maayong Balita.<br/>',NULL,17201,2);
INSERT INTO stanza VALUES('CB445','3','Tingog ko paawita,<br/>Alang lamang’s Hari ko;<br/>Mga ngabil mapuno,<br/>Sa wali gikan Nimo,<br/>Sa wali gikan Nimo.<br/>',NULL,17202,3);
INSERT INTO stanza VALUES('CB445','4','Salapi ba’g bulawan,<br/>Di Ka nako hikawan;<br/>Kusog ko ug kaalam,<br/>Gamita’s nahimut-an,<br/>Gamita’s nahimut-an.<br/>',NULL,17203,4);
INSERT INTO stanza VALUES('CB445','5','Himoang pagbuot ko,<br/>Maimo, O Ginoo!<br/>Kasingkasing ihalad,<br/>Mahimo Mo nga trono,<br/>Mahimo Mo nga trono.<br/>',NULL,17204,5);
INSERT INTO stanza VALUES('CB445','6','Paghigugma ibubo<br/>Sa Imo nga tiilan;<br/>Kaugalingon ug tanan,<br/>Ihalad alang Nimo,<br/>Ihalad alang Nimo.<br/>',NULL,17205,6);
INSERT INTO stanza VALUES('CB449','1','Ang buot Mo tumana, Jesus,<br/>Magkokolon Ka, kolonon ko;<br/>Umola ingon sa buot Mo,<br/>Samtang naghulat ako’s hilom.<br/>',NULL,17206,1);
INSERT INTO stanza VALUES('CB449','2','Ang buot Mo tumana Jesus,<br/>Kasingkasing ko susihon Mo.<br/>Hugasi, putia pa’s nieve,<br/>Samtang maubsanong nagyukbo.<br/>',NULL,17207,2);
INSERT INTO stanza VALUES('CB449','3','Ang buot Mo tumana, Jesus,<br/>Samdan, gikapoy, tabangi ko.<br/>Ikaw gamhanan sa ngatanan,<br/>Hikapa ako ug ayoha.<br/>',NULL,17208,3);
INSERT INTO stanza VALUES('CB449','4','Ang buot Mo tumana, Jesus,<br/>Ikawng magbuot’s akong lihok,<br/>Pun-a’s Espiritu’g pakit-a,<br/>Si Cristo lamang ang mabuhi.<br/>',NULL,17209,4);
INSERT INTO stanza VALUES('CB452','1','Ay’g sultii’s kalipayan,<br/>Tintala ba’s salapi;<br/>Ay’g lipatlipata’s yuta,<br/>Sungoga’s kawang dungog.<br/>Nalutas na’s mga diosdios;<br/>Di na ko’s kaugalingon,<br/>Kasingkasing gihatag na,<br/>Maiya ni Jesus ra.<br/>',NULL,17210,1);
INSERT INTO stanza VALUES('CB452','chorus','Di na ako sa<br/>Kaugalingon,<br/>Iya na karon kang Jesus,<br/>Hangtud’s dayon.<br/>',NULL,17211,2);
INSERT INTO stanza VALUES('CB452','2','Iya ra gayud ni Cristo,<br/>Dala ni’ni pahulay;<br/>Diha’s paghalad ko’s tanan,<br/>Kadato N’ya kadangpan.<br/>Dawata ko, O Ginoo,<br/>Maimoha sa hingpit,<br/>Aron mahimong angayan,<br/>Tawgon nga Ikaw ako.<br/>',NULL,17212,3);
INSERT INTO stanza VALUES('CB452','3','Ayaw na lang pakigbisug,<br/>Di na ka’s kaugalingon,<br/>Kaugalingon ihalad N’ya,<br/>Maiya na sa hingpit.<br/>Nagtugyan S’ya’s Kaugalingon,<br/>Aron ikaw maangkon;<br/>Tanan Iyang gihatag na,<br/>Basli S’ya’s imong gugma.<br/>',NULL,17213,4);
INSERT INTO stanza VALUES('CB456','1','Alang kang Jesus magkinabuhi,<br/>Siya pahimut-an ko sa tanan;<br/>Kinabubut-ong nakig-alayon,<br/>Sa panalangin kini ang dalan.<br/>',NULL,17214,1);
INSERT INTO stanza VALUES('CB456','chorus','O Jesus Ginoo ko,<br/>Magtugyan ko Nimo,<br/>Kay kanako gihatag<br/>Ang kinabuhi Mo;<br/>Wa koy laing Agalon,<br/>Ikaw ray na’s trono,<br/>Kinabuhi ihatag ko<br/>Kanimo, Ginoo.<br/>',NULL,17215,2);
INSERT INTO stanza VALUES('CB456','2','Alang N’yang namatay puli nako,<br/>Sala’g kaulaw giako sa krus;<br/>Gugma nagtandog, mosanong’s tawag,<br/>Sundon S’ya, akong tanan ihatag.<br/>',NULL,17216,3);
INSERT INTO stanza VALUES('CB456','3','Bisan asa mabuhi alang N’ya,<br/>Sa balaang ngalan N’ya mobuhat;<br/>Andam mag-antus ug mapildehan,<br/>Ilhon nga bahin kini’s akong krus.<br/>',NULL,17217,4);
INSERT INTO stanza VALUES('CB456','4','Mabuhi alang N’ya bisan kadyut,<br/>Bahanding mahal ang pahiyom N’ya,<br/>Pangitaon ang mga nawala,<br/>Dad-ong gikapoy nga mopahuway N’ya.<br/>',NULL,17218,5);
INSERT INTO stanza VALUES('CB460','1','Gipas-an ko ang krus, Jesus,<br/>Aron magsunod Nimo;<br/>Tinamay ug sinalikway,<br/>Ikaw na ang tanan ko.<br/>',NULL,17219,1);
INSERT INTO stanza VALUES('CB460','chorus','Bisan’s tanan gib’yaan Ka,<br/>Ikaw sundon ko’s grasya,<br/>Alang nako namatay Ka,<br/>Ang dugo Mo giula.<br/>',NULL,17220,2);
INSERT INTO stanza VALUES('CB460','2','Wad-on tanan kong ambisyon,<br/>Gitinguha’g paglaum;<br/>Dato ang akong kahimtang,<br/>Dios ug Cristo ako man.<br/>',NULL,17221,3);
INSERT INTO stanza VALUES('CB460','3','Patamaya’g pabiyaang<br/>Kalibutan kanako;<br/>Gib’yaan, gisalikway sab<br/>Nila akong Ginoo.<br/>',NULL,17222,4);
INSERT INTO stanza VALUES('CB460','4','Dios kaalam, gugma’g gahum,<br/>Pahiyomi na ako;<br/>Bisan dumtan sa kaaway,<br/>Nawong Mo ang maglipay.<br/>',NULL,17223,5);
INSERT INTO stanza VALUES('CB460','5','Kon samokon man ko’s tawo,<br/>Modangop ko’s dughan Mo;<br/>Bisan daghan ang pagsulay,<br/>Maghatag Ka’s pahulay.<br/>',NULL,17224,6);
INSERT INTO stanza VALUES('CB460','6','Kagul-anan di magdaut,<br/>Gugma Mo nia nako;<br/>Kalipay di makahaylo,<br/>Kon di maglakip Nimo.<br/>',NULL,17225,7);
INSERT INTO stanza VALUES('CB460','7','Sa grasya ngadto’s himaya,<br/>Ako’s pagtoo dad-a;<br/>Didto’s walay katapusan,<br/>Ako Imong giyahan.<br/>',NULL,17226,8);
INSERT INTO stanza VALUES('CB460','8','Matapos na ang tahas ko,<br/>Adlaw’s pagdumuloong;<br/>Paglaum maamgohan na<br/>Ug makitang pagtoo.<br/>',NULL,17227,9);
INSERT INTO stanza VALUES('CB462','1','Unsaon ko pag-awat N’ya<br/>Nga gialagaran’s gugma?<br/>Di gayud mosimang’s dalan,<br/>Nga maghatud sa trono N’ya.<br/>',NULL,17228,1);
INSERT INTO stanza VALUES('CB462','2','Kaguol, pagbiaybiay,<br/>Hago’g ubos nga pagpuyo,<br/>Pagbudhi’g koronang tunok—<br/>Dalan ba’s mga naghalad?<br/>',NULL,17229,2);
INSERT INTO stanza VALUES('CB462','3','Akong panaw kon malisud,<br/>Ayaw itugot magmulo;<br/>Pahandoma’s Calvario Mo,<br/>Di magtagad’s kasakit ko.<br/>',NULL,17230,3);
INSERT INTO stanza VALUES('CB462','4','Pahandoma kong wa gyud Ka<br/>Motilaw’s tanang kalipay,<br/>Giuhaw, gigutom, gikapoy,<br/>Way gihigdaan’s gabii.<br/>',NULL,17231,4);
INSERT INTO stanza VALUES('CB462','5','Nag-antus Ka alang nako!<br/>Wa magtagad’s kalipay Mo;<br/>Bisan yuta madanihon,<br/>Labaw Ka nga higugmaon.<br/>',NULL,17232,5);
INSERT INTO stanza VALUES('CB463','1','Agalon gimahal ko,<br/>Di ko bu’t mobiya,<br/>S’ya akong Manunubos,<br/>Kanako nagtubos.<br/>Gusto ko S’yang silbehan,<br/>Ug m’oy pahamut-an;<br/>Sa takna’s kakapoy, S’ya<br/>Maghatag’s pahulay.<br/>',NULL,17233,1);
INSERT INTO stanza VALUES('CB463','2','Giula Niyang dugo,<br/>Ulipon maangkon;<br/>Nagluwas nako’s gapos,<br/>Sala’g kaugalingon.<br/>Gipiling magsilbe N’ya,<br/>Ako’y gipabuot,<br/>Kagawasang hingpit gyud<br/>Nga di na mawala.<br/>',NULL,17234,2);
INSERT INTO stanza VALUES('CB463','3','Pagsilbe di tungaon,<br/>Iyaha ra gayud!<br/>Gihigugma gyud ko N’ya,<br/>S’ya mismo namatay.<br/>Magsimba, magkalipay,<br/>Ug awitan Siya.<br/>Agalon gimahal ko,<br/>Di ko bu’t mobiya.<br/>',NULL,17235,3);
INSERT INTO stanza VALUES('CB468','1','Sundalo ba ako sa Krus—<br/>Nagsunod’s Cordero?<br/>Hadlok bang molaban Niya,<br/>Moila’s ngalan N’ya?<br/>',NULL,17236,1);
INSERT INTO stanza VALUES('CB468','chorus','Sa ngalan N’yang namatay<br/>Alang nako sa krus;<br/>Sa grasya dag-ong korona,<br/>Bisan unsang krus ko.<br/>',NULL,17237,2);
INSERT INTO stanza VALUES('CB468','2','Sa langit ba ako dad-on,<br/>Uban sa kasayon,<br/>Samtang uban nakigbisug,<br/>Aron lang modaug?<br/>',NULL,17238,3);
INSERT INTO stanza VALUES('CB468','3','Wa bay ka’wayng atubangon?<br/>Way bahang ulangon?<br/>Tabangan ba ko sa yuta,<br/>Magpadayon sa Dios?<br/>',NULL,17239,4);
INSERT INTO stanza VALUES('CB468','4','Kinahanglan makig-away<br/>Ayha makahari.<br/>Hatagi ko sa kaisug<br/>Pag-antus’ kalisud.<br/>',NULL,17240,5);
INSERT INTO stanza VALUES('CB469','1','Kinsay dapig sa Dios,<br/>Mosilbe’s Hari?<br/>Kinsay motabang N’ya,<br/>Pagdala’s kalag?<br/>Kinsay mosalikway<br/>Sa kalibutan?<br/>Alang Niya moatubang<br/>Sa away?<br/>',NULL,17241,1);
INSERT INTO stanza VALUES('CB469','chorus','Pinaagi’s grasya’g<br/>Katubsanan Mo,<br/>Manluluwas, ako<br/>Modapig Nimo.<br/>',NULL,17242,2);
INSERT INTO stanza VALUES('CB469','2','Magsundalo kami,<br/>Moasdang’s gubat,<br/>Di tungod’s himaya<br/>O purongpurong,<br/>Kondi’ sa gugma N’ya<br/>Nga nanag-iya;<br/>Kay ginganlan Niya,<br/>Dapigan gyud S’ya.<br/>',NULL,17243,3);
INSERT INTO stanza VALUES('CB469','3','Gipalit Mo kami<br/>Di sa bulawan,<br/>Dugo’s kinabuhi<br/>Hinooy bugti.<br/>Ang modangop Nimo<br/>Bulahanon Mo,<br/>Mobuot, gawasnong<br/>Maalang Nimo.<br/>',NULL,17244,4);
INSERT INTO stanza VALUES('CB469','4','Gubat bisan lisud,<br/>Ka’way maisug,<br/>Kasundalohan’s Dios<br/>Way makabuntog;<br/>Barug’s bandila N’ya<br/>Kay kamat’oran,<br/>Dili gyud mausab,<br/>Pihong modaug.<br/>',NULL,17245,5);
INSERT INTO stanza VALUES('CB469','5','Piniling sundalo,<br/>Sa langyawng yuta;<br/>Gitawag alang sa<br/>Bando’s Kapitan;<br/>Dili magmabugnaw<br/>Sa pakiggubat,<br/>Isug, maunongon,<br/>Kasaligan gyud.<br/>',NULL,17246,6);
INSERT INTO stanza VALUES('CB471','1','Magpalayo pa ba ako?<br/>Nga Espiritu nagsubo,<br/>Naghulat kanako?<br/>Andam na ko sa pagbalik,<br/>Pangandoy ko sukad karon<br/>Mosunod na Nimo.<br/>',NULL,17247,1);
INSERT INTO stanza VALUES('CB471','2','Way panaganang ihalad<br/>Kaugalingon akong tanan,<br/>Magtuman’s tuyo Mo.<br/>Dawata ug ampingi ko,<br/>Magtinguha ra’s pagtuman’s<br/>Pagbuot’s Amahan.<br/>',NULL,17248,2);
INSERT INTO stanza VALUES('CB471','3','Maulaw kon madumdoman,<br/>Way gipatoo Kanimo,<br/>Pulong Mo gipugngan.<br/>Dihogan Mo unta ako,<br/>Aron mabuhi Ka nako,<br/>Ikay ipamulong.<br/>',NULL,17249,3);
INSERT INTO stanza VALUES('CB471','4','Grasyang hatag pagkadato,<br/>Labaw’s higalang dapit ko,<br/>Pangasaw-onon man.<br/>Kinabuhi’g kapildehan<br/>Andam ko nga maambitan,<br/>Mausa Kaniya.<br/>',NULL,17250,4);
INSERT INTO stanza VALUES('CB472','1','Daghang mosud’s gingharian,<br/>Krus di mopas-an;<br/>Daghang buot malipay lang,<br/>Di bu’t mapildehan;<br/>Alang’s mahal nga Agalon,<br/>Mobiya’s tanan,<br/>Alang’s mahal nga Agalon,<br/>Mobiya’s tanan.<br/>',NULL,17251,1);
INSERT INTO stanza VALUES('CB472','2','Daghang motambong sa talad,<br/>Diyutayng mopuasa;<br/>Kon paimnon’s kopang pait<br/>Mokurog gayud;<br/>Pila ray motukaw<br/>Sa nag-awit uban N’ya.<br/>Pila ray motukaw<br/>Sa nag-awit uban N’ya.<br/>',NULL,17252,2);
INSERT INTO stanza VALUES('CB472','3','Daghang niila’s ’yang kaalam,<br/>Di’s kaulawan.<br/>Kon pahiyoman’s Ginoo,<br/>Dako’g pagdayeg;<br/>Kon sa daklit b’yaan sila,<br/>Di moila N’ya,<br/>Kon sa daklit b’yaan sila,<br/>Di moila N’ya.<br/>',NULL,17253,3);
INSERT INTO stanza VALUES('CB472','4','Apan kadtong nahigugma,<br/>Way pangutana;<br/>Bisan kinabuhing mahal,<br/>Itugyan nila.<br/>Manlul’was, pahigugmaa<br/>Sama niini,<br/>Manlul’was, pahigugmaa<br/>Sama niini.<br/>',NULL,17254,4);
INSERT INTO stanza VALUES('CB473','1','Way dila nga makasaysay’s<br/>Kagawasan’s kalag,<br/>Nga di na mahaylo’s yuta,<br/>Na’ na’s pagbuot N’ya.<br/>Kay ang tanan iyaha man,<br/>Karon, umalabot,<br/>Kalinaw giginhawa n’ya,<br/>Si Cristo’y balay n’ya.<br/>',NULL,17255,1);
INSERT INTO stanza VALUES('CB473','2','Sa trono N’ya gipalingkod,<br/>Gipiling maghari,<br/>Ug ang katingad-an gayud,<br/>Ako ang nidili.<br/>Ayaw ingnang sakripisyo,<br/>Bisan unsay bili;<br/>Dili tiaw nang katungod<br/>Kon masundalo N’ya.<br/>',NULL,17256,2);
INSERT INTO stanza VALUES('CB473','3','Bangon ug isipa karon,<br/>Dugmok mo tibuk-on,<br/>Tanang tawo, butang, hitabo<br/>Mosilbe’s kalag mo.<br/>Kon ikaw Kan’ya mausa<br/>Imoha ang tanan,<br/>Ug kinabuhing dayon pa<br/>Imong mapa’muslan.<br/>',NULL,17257,3);
INSERT INTO stanza VALUES('CB474','1','Ginoo, nausa ako<br/>Kanimo’s espiritu;<br/>Tanan Nimo naako na,<br/>Nabuhi Ka’s sulod ko.<br/>',NULL,17258,1);
INSERT INTO stanza VALUES('CB474','chorus','Nausa Kanimo,<br/>Nausa Kanimo;<br/>Adlaw-adlaw makaambit’s<br/>Kadato Mo, Ginoo.<br/>',NULL,17259,2);
INSERT INTO stanza VALUES('CB474','2','Naambitang pagkatawo Mo,<br/>Gipuno’s pagka-tawo Mo,<br/>Ang kompleto Mong pagsugot<br/>Kanunayng magamit ko.<br/>',NULL,17260,3);
INSERT INTO stanza VALUES('CB474','3','Nausa’s pagkalansang’s krus,<br/>Namatay diha Nimo;<br/>Patay na ko’s kalibutan,<br/>Patay sab kini nako.<br/>',NULL,17261,4);
INSERT INTO stanza VALUES('CB474','4','Nausa Nimo’s pag’banhaw,<br/>Nabuhi diha Nimo;<br/>Kinabuhi Mo, Ginoo,<br/>Ang gikinabuhi ko.<br/>',NULL,17262,5);
INSERT INTO stanza VALUES('CB474','5','Nausa Nimo’s pagkayab,<br/>Uban Nimo’s itaas;<br/>Langyaw, kay kinabuhi ko,<br/>Natago diha Nimo.<br/>',NULL,17263,6);
INSERT INTO stanza VALUES('CB474','6','Nausa’s paglingkod’s trono,<br/>Nag-ambit’s pagbuot Mo;<br/>Na’ ko Nimo, na’ Ka nako,<br/>Usa ta’g kinabuhi.<br/>',NULL,17264,7);
INSERT INTO stanza VALUES('CB475','1','Usa Nimo, Anak’s dayon,<br/>Sa pagtoo’g espiritu,<br/>Usa mi’s kamatayon Mo,<br/>Ug sa kinabuhi Mo.<br/>Usa Nimo, Anak sa Dios,<br/>Sa grasya na-bahin Mo,<br/>Manunod’s usang Amahan,<br/>Puy-anan mi’s Esp’ritu.<br/>',NULL,17265,1);
INSERT INTO stanza VALUES('CB475','2','Uban Nimo gianak mi,<br/>Anak nga nagpakatawo;<br/>Mga bahin mi’s Lawas Mo,<br/>Nagdumu’ong uban Nimo.<br/>Usa Nimo, Dinihogan<br/>May gahum sab’s Esp’ritu,<br/>Matag adlaw, matag takna,<br/>Bulig Nimong naghago.<br/>',NULL,17266,2);
INSERT INTO stanza VALUES('CB475','3','Usa Nimo, sinalikway,<br/>Gihukman ug gitunglo;<br/>Namatay na ngadto’s sala,<br/>Impyerno gitambog na.<br/>Usa Nimo’s pagkabanhaw,<br/>Di dag-on’s kamatayon,<br/>Na’s bag-ong kabuhatan Mo,<br/>Namunga’s pagkamatarung.<br/>',NULL,17267,3);
INSERT INTO stanza VALUES('CB475','4','Usa Nimo nga nikayab,<br/>Naglingkod sa trono Mo,<br/>Gipaambit sa kagahum,<br/>Maghari uban Nimo.<br/>Usa Nimo nga mobalik,<br/>Uban sab himayaon,<br/>Katahum Mo ipadayag,<br/>Usa Nimo sa dayon.<br/>',NULL,17268,4);
INSERT INTO stanza VALUES('CB477','1','Makalibo man nga<br/>Matawo si Cristo;<br/>Kon wa S’ya kanimo,<br/>Luoy ang kalag mo.<br/>Ang Krus sa Golgota<br/>Di makal’was nimo;<br/>Ang Krus lang’s sulod mo<br/>Maoy makaayo.<br/>',NULL,17269,1);
INSERT INTO stanza VALUES('CB477','chorus','Krus ni Cristo dawaton<br/>Sa kasingkasing ko;<br/>Mamatayng kaugalingon,<br/>Ug mabanhaw ang Diosnon.<br/>',NULL,17270,2);
INSERT INTO stanza VALUES('CB477','2','Kon unsay mahal mo,<br/>Mahisama ka gyud;<br/>Maabug, kon abug,<br/>Ma-Dios gyud kon ang Dios.<br/>“Ako” kon mamatay,<br/>Dios maoy mabuhi;<br/>Kon di ako, S’ya na,<br/>Hatagan ka’s tanan.<br/>',NULL,17271,3);
INSERT INTO stanza VALUES('CB477','3','Gugma labing laktud<br/>Dalan paingon’s Dios;<br/>Kon kahibalo sundon,<br/>Maglibotlibot lang.<br/>Hinginling kalibutan,<br/>Pun-on Ka’s gugma’s Dios,<br/>Aron mabalaan ka<br/>Sama gayud Niya.<br/>',NULL,17272,4);
INSERT INTO stanza VALUES('CB479','1','Kahibulongan nga dapit,<br/>Gihatag N’ya kanako!<br/>Giluwas sa Iyang grasya,<br/>Aron masama Niya.<br/>Kon makita si Jesus<br/>Ako mahisama N’ya;<br/>Kon maglakaw ko uban N’ya,<br/>Pagbalik N’ya masama.<br/>',NULL,17273,1);
INSERT INTO stanza VALUES('CB479','chorus','Sama Niya, sama Niya,<br/>Kahibudngang pagkasama,<br/>Giluwas ko sa Iyang grasya,<br/>Mausa Niya, mahisama.<br/>',NULL,17274,2);
INSERT INTO stanza VALUES('CB479','2','Nausa’s kamatayon N’ya,<br/>Nausa’s pagkabanhaw;<br/>Nagawas gikan sa tunglo,<br/>Sama gayud Kaniya.<br/>Nausa sa ’yang trono,<br/>Nausa’s pagkaanak,<br/>Sama’s bana ug asawa,<br/>Sama’s punoa’g sanga.<br/>',NULL,17275,3);
INSERT INTO stanza VALUES('CB479','3','Nausa’s nabuhat Niya<br/>Ug pag-ampo’s ngalan N’ya;<br/>Maangkon ko’s pagsalig<br/>Tanan Niyang katakus.<br/>Usa’s pagtoo’g gugma,<br/>Usa’s kinabuhi N’ya,<br/>Gitimbrehan’s Espiritu,<br/>Mabalaan sama N’ya.<br/>',NULL,17276,4);
INSERT INTO stanza VALUES('CB481','1','Gilansang uban ni Cristo,<br/>Sa kalibuta’g sala;<br/>Sa bag-ong kinabuhi N’ya<br/>Karon nasulod na ko;<br/>Sa pag-ambit’s pag-antus N’ya,<br/>Mauyon’s kamatayon,<br/>Mokuyog ko’s Manluluwas,<br/>Hangtud gyud sa Calvario.<br/>',NULL,17277,1);
INSERT INTO stanza VALUES('CB481','chorus','Hangtud gyud sa Calvario,<br/>Niadto ang Manlul’was,<br/>Tabanging mokuyog ko<br/>Kanimo sa Calvario.<br/>',NULL,17278,2);
INSERT INTO stanza VALUES('CB481','2','Dili lisud nga mamatay<br/>Kon dunay pagkabanhaw,<br/>Dili lisud ang mag-antus<br/>Kon puno ta’s kalipay.<br/>Nipuyo na S’ya’s sulod ko,<br/>Sa gahum’s pagkabanhaw;<br/>Malipayon kong moadto<br/>Hangtud gyud sa Calvario.<br/>',NULL,17279,3);
INSERT INTO stanza VALUES('CB481','3','Kon mamatay, mabuhi ta,<br/>Kon mag-antus, maghari;<br/>Niana ganting himaya<br/>Makab-ot sa modaug.<br/>Niadtong buntag’s kasadya<br/>Kon Agalon moingon,<br/>“Oo, nikuyog ka Nako,<br/>Hangtud gyud sa Calvario.”<br/>',NULL,17280,4);
INSERT INTO stanza VALUES('CB482','1','Gilansang’s krus ubang Cristo,<br/>Krus N’ya nagpahigawas;<br/>Uban Niya nga nabanhaw,<br/>Naghari S’ya’s sulod ko.<br/>',NULL,17281,1);
INSERT INTO stanza VALUES('CB482','chorus','Katam-is mamatay ubang Cristo,<br/>Magawas’ kaugalingon;<br/>Katam-is mabuhi ubang Cristo,<br/>Maghari S’ya’s sulod ko.<br/>',NULL,17282,2);
INSERT INTO stanza VALUES('CB482','2','Misteryo sa katuigan!<br/>Sa pagtoo nasayran:<br/>Cristo—Paglaum’s Himaya,<br/>Sige nga imantala.<br/>',NULL,17283,3);
INSERT INTO stanza VALUES('CB482','3','Sekreto’s kinaiyahan,<br/>Naani ang gilubong;<br/>Bating gisumpay’s maayo,<br/>Bunga mas tam-is, dato.<br/>',NULL,17284,4);
INSERT INTO stanza VALUES('CB482','4','Sekreto kini’s balaan,<br/>Di ato, kondi’ Siya;<br/>Basiyoha mi ug pun-a<br/>Sa Imong kahupnganan.<br/>',NULL,17285,5);
INSERT INTO stanza VALUES('CB482','5','Tambal kini’s tanang sakit,<br/>Mamatay lang’s kusog ta,<br/>Kinabuhi’g kahupong N’ya<br/>Magtagbo’s kinahanglan.<br/>',NULL,17286,6);
INSERT INTO stanza VALUES('CB482','6','M’oy sugilanon’s Agalon,<br/>Trono mag-agi sa Krus;<br/>Sama’s dalan N’ya’s himaya,<br/>Mag-agi’s kamatayon.<br/>',NULL,17287,7);
INSERT INTO stanza VALUES('CB483','1','Gilubong, nabanhaw uban N’ya,<br/>Unsa pa’y akong mahimo?<br/>Hunongon lang pakigbisug ko,<br/>Maglakaw ako sa kabag-o<br/>Sa kinabuhi!<br/>',NULL,17288,1);
INSERT INTO stanza VALUES('CB483','2','Nabanhaw ko uban ni Cristo,<br/>Kabalaan nang gawi ko;<br/>Kini ang nahunahunaan:<br/>Ang namatay di na masad-an.<br/>Himayaong Dios!<br/>',NULL,17289,2);
INSERT INTO stanza VALUES('CB483','3','Nabuhi ko uban ni Cristo,<br/>Nag-una S’ya, mosunod ko;<br/>Sa gapos ko natangtangan na,<br/>Kaugalingon patay na, busa<br/>Himayaong Dios!<br/>',NULL,17290,3);
INSERT INTO stanza VALUES('CB483','4','Nabuhi ko alang kang Cristo,<br/>Mga bahin ’yang masugo,<br/>Di’s kasugoan, kondi’s grasya,<br/>Imbis sala, S’ya ang maghari.<br/>Himayaong Dios!<br/>',NULL,17291,4);
INSERT INTO stanza VALUES('CB483','5','Magtubo ko diha ni Cristo,<br/>Di na’s butang ikaulaw;<br/>Bunga lunlon pagkabalaan,<br/>Kinabuhing dayon sangputan,<br/>Himayaong Dios!<br/>',NULL,17292,5);
INSERT INTO stanza VALUES('CB486','1','Giisip namatay ubang Jesus,<br/>Nabuhi na’s bag-ong kinabuhi;<br/>Jesus tutokan hangtud’s himaya,<br/>Sa matag gutlo Imoha ako.<br/>Matag gutlo ampingan’s gugma N’ya,<br/>May kinabuhi gikan’s itaas;<br/>Jesus tutokan hangtud’s himaya,<br/>Sa matag gutlo, Imoha ako.<br/>2 Moaway S’ya alang sa matarung,<br/>Sa tigiay S’yay makigbisug gyud;<br/>Puti gyung bandila ’yang ituboy,<br/>Matag gutlo bantayan N’ya ako.<br/>',NULL,17293,1);
INSERT INTO stanza VALUES('CB486','3','Wa gyuy pagsulayng di S’ya mag-uban,<br/>Wa gyuy luwan nga di N’ya pas-anon,<br/>Way kasubong di ka N’ya duyogan,<br/>Matag gutlo Iyang giatiman.<br/>',NULL,17294,2);
INSERT INTO stanza VALUES('CB486','4','Wa gyuy kasakit o agulo ba,<br/>Luhang motulo, o danguyngoy ta,<br/>Kakuyaw ba nga didto sa trono<br/>Matag gutlo gihunahuna N’ya.<br/>',NULL,17295,3);
INSERT INTO stanza VALUES('CB486','5','Way kaluyahong di mabati N’ya,<br/>Way sakit nga di Niya ma-ayo;<br/>Matag gutlo lisud ba’g hayahay,<br/>Manlul’was ko magpabilin nako.<br/>',NULL,17296,4);
INSERT INTO stanza VALUES('CB487','1','Nalansang ko sa krus uban ni Cristo,<br/>Sa unod natangtangan ako;<br/>Karon nabuhi uban sa Ginoo,<br/>Sa kinabuhi’s pagkabanhaw!<br/>',NULL,17297,1);
INSERT INTO stanza VALUES('CB487','chorus','Nalansang sa Krus, Ginoo ug ako,<br/>Sa Calvario, sa Calvario,<br/>Uban Niya nabuhi’s pagkabanhaw,<br/>Magpabilin gyud N’ya.<br/>',NULL,17298,2);
INSERT INTO stanza VALUES('CB488','1','Gipakita Mong misteryo,<br/>Uban Nimo namatay ko;<br/>Way laing paagi’g gahum<br/>Nga ako magmadaugon.<br/>',NULL,17299,1);
INSERT INTO stanza VALUES('CB488','2','Ang krus Mo ako sab nga krus,<br/>Ning kahayag dan-agi ko;<br/>Kon namatay uban Nimo,<br/>Kalibutan wa nay gahum.<br/>',NULL,17300,2);
INSERT INTO stanza VALUES('CB488','3','Nalansang’s krus uban Nimo,<br/>Gawas na’s sala’g kaugalingon;<br/>Magpahimulos pa ba ko,<br/>Sa kawang nga kalibutan?<br/>',NULL,17301,3);
INSERT INTO stanza VALUES('CB488','4','Mobarug ko uban Nimo,<br/>Didto sa krus sa Calvario.<br/>Kinabuhi’g gahum Mo ako,<br/>Kay nausa Ka man nako.<br/>',NULL,17302,4);
INSERT INTO stanza VALUES('CB488','5','Kaaway Ikawng naglaglag,<br/>Buhat, gahum n’ya gilumpag;<br/>Modaug sab diha Nimo,<br/>Gahum Mo pamatud-an ko.<br/>',NULL,17303,5);
INSERT INTO stanza VALUES('CB488','6','Apan sa pagdaug saligan,<br/>Ang kamatayong gikamatyan;<br/>Sundon Ka’s dalang gilakwan,<br/>Hangtud tumong’s Dios makuptan.<br/>',NULL,17304,6);
INSERT INTO stanza VALUES('CB488','7','Namatay ko uban Nimo,<br/>Gidawat gyud ug nitoo,<br/>Mas lalum untang makita,<br/>Aron’s unod magawas na.<br/>',NULL,17305,7);
INSERT INTO stanza VALUES('CB488','8','Modaug unta sama Nimo,<br/>Maghari sa pagbalik Mo;<br/>Kon sa krus Mo mopas-an mi,<br/>Sa himaya Mo moambit.<br/>',NULL,17306,8);
INSERT INTO stanza VALUES('CB489','1','Samtang dinhi Ka pa’s yuta<br/>Uban sa mga tinun-an,<br/>Morag wa sila kaila,<br/>Ni makasabut Kanimo.<br/>',NULL,17307,1);
INSERT INTO stanza VALUES('CB489','2','Nadungog nilang tingog Mo,<br/>Nakita ang Imong dagway;<br/>Nagduot pa libot Nimo,<br/>Kinsa Ka? Way nahibalo.<br/>',NULL,17308,2);
INSERT INTO stanza VALUES('CB489','3','Daw nataptapan sab kami,<br/>Morag dugay Kang kaila,<br/>Apan ingnong nakaila,<br/>Dili diay klaro ka’yo.<br/>',NULL,17309,3);
INSERT INTO stanza VALUES('CB489','4','Apan Esp’ritu Ka karon,<br/>Na-laing Maglilipay ko;<br/>Padaygi’s Kaugalingon Mo,<br/>Kay naa Ka na’s templo Mo.<br/>',NULL,17310,4);
INSERT INTO stanza VALUES('CB489','5','Pun-a Ko’s Espiritu Mo,<br/>Tanang suok sa kalag ko;<br/>Matag bahin dasigon Mo,<br/>Tandoga aron mabag-o.<br/>',NULL,17311,5);
INSERT INTO stanza VALUES('CB489','6','Labi pang magpatinuod<br/>Nimo ang bugna’s Esp’ritu;<br/>Wa pa igdungog, igkita,<br/>Ang katinuod Mo namo.<br/>',NULL,17312,6);
INSERT INTO stanza VALUES('CB489','7','Kon kaloy-an, padaygan Mo,<br/>Hatagan’s Espiritu Mo;<br/>Unsay labi pang tinuod<br/>Gawas Nimo, O Ginoo?<br/>',NULL,17313,7);
INSERT INTO stanza VALUES('CB489','8','Pabahaang Espiritu<br/>Sa pagkatawo ko, Ginoo,<br/>Matag bahin mahimaya,<br/>Bisan asa makita Ka.<br/>',NULL,17314,8);
INSERT INTO stanza VALUES('CB489','9','O kasuod namo Nimo,<br/>Daw yuta nasakot’s langit;<br/>Kalag pun-on’s presensya Mo,<br/>Kasingkasing magdayeg Nimo.<br/>',NULL,17315,9);
INSERT INTO stanza VALUES('CB490','1','Sa wala pay nakaila<br/>Sa Amahan, O Ginoo,<br/>Nianhi S’ya diha Nimo,<br/>Aron S’ya among maila.<br/>',NULL,17316,1);
INSERT INTO stanza VALUES('CB490','2','Apan samtang dinhi Ka pa,<br/>Diyutayng nakaila Nimo,<br/>May taptap nag-ali nila,<br/>Wa gyud makatugkad Nimo.<br/>',NULL,17317,2);
INSERT INTO stanza VALUES('CB490','3','Esp’ritu Kang nianhi ’ron,<br/>Amahan nianhi Nimo,<br/>Naila S’ya tungod Nimo,<br/>Sa Esp’ritu maila Ka.<br/>',NULL,17318,3);
INSERT INTO stanza VALUES('CB490','4','Wa Ka na sul-obi’s unod,<br/>Nga kin’hanglan maghago pa,<br/>Esp’ritu na’s kasingkasing,<br/>Nagsangkap way kinutoban.<br/>',NULL,17319,4);
INSERT INTO stanza VALUES('CB490','5','Ginganlan kanhi’g Amahan,<br/>Karon Espiritu Santo;<br/>Esp’ritu laing dagway Mo,<br/>Nga mopuyo’s among sulod.<br/>',NULL,17320,5);
INSERT INTO stanza VALUES('CB490','6','Pagkailang Esp’ritu Ka,<br/>Nasinating pag-awas Mo,<br/>Himaya’g karakter Nimo,<br/>Tanan nailhan na namo.<br/>',NULL,17321,6);
INSERT INTO stanza VALUES('CB490','7','Punos’ pagdayeg’s Ngalan Mo,<br/>Way sama kamahal Nimo;<br/>Kay naila Kang tinuod,<br/>Way mas hiligugmaon pa.<br/>',NULL,17322,7);
INSERT INTO stanza VALUES('CB491','1','Samtang naa Ka pa sa unod,<br/>Di Ka maila pag-ayo;<br/>Nianhi Ka ingog Esp’ritu,<br/>Sa esp’ritu ko maila.<br/>',NULL,17323,1);
INSERT INTO stanza VALUES('CB491','2','Kanhi’s unod Manunubos Ka,<br/>Esp’ritu karong naglipay,<br/>Di Ka na kontakon pa’s gawas,<br/>Kay nausa nako’s sulod.<br/>',NULL,17324,2);
INSERT INTO stanza VALUES('CB491','3','Kay Espiritu Ka na karon,<br/>Sigeng nagbugna Kanimo;<br/>Maila sa espiritu ko<br/>Presensya’g realidad Mo.<br/>',NULL,17325,3);
INSERT INTO stanza VALUES('CB491','4','Naila kong kinabuhi Mo<br/>Labaw’s mga tinun-an Mo,<br/>Bisag nag-uban sila Nimo<br/>Sa dinhi Ka pa sa yuta.<br/>',NULL,17326,4);
INSERT INTO stanza VALUES('CB491','5','Kay nagpuyo nakong Esp’ritu,<br/>Tinuod gyud Ka kanako;<br/>Di mahikap, ’pan kasaligan,<br/>Di makita, gihigugma.<br/>',NULL,17327,5);
INSERT INTO stanza VALUES('CB491','6','Ang Esp’ritu Mo’s kahiladman<br/>Nagsangkap’s pagkamatarung;<br/>Pagkabalaa’g katubsanan,<br/>Kaalam, kamabungahon.<br/>',NULL,17328,6);
INSERT INTO stanza VALUES('CB491','7','Ang Esp’ritu Mo’s esp’ritu ko<br/>Nagsangkap, nausa nako,<br/>Sigeng ako sa kaugalingon<br/>Ug sigeng Ikaw sab ako.<br/>',NULL,17329,7);
INSERT INTO stanza VALUES('CB492','1','Kanhi ang tanang buhat Nimo<br/>Taman ra’s krus sa Calvario;<br/>Nagbuhat Ka gihapon karon<br/>Diha’s lain lang nga dagway.<br/>',NULL,17330,1);
INSERT INTO stanza VALUES('CB492','2','Nagluwas, namulong, naghayag,<br/>Ug naggiya gihapon Ka,<br/>Usang agay Ka’g ang Esp’ritu,<br/>Nagbanlas’ daghan’s sulog Mo.<br/>',NULL,17331,2);
INSERT INTO stanza VALUES('CB492','3','Wa pugnging gahum Mo Kaniya,<br/>Way hunong nga nagbuhat Ka;<br/>Naglipay, nagsugo, nagdasig,<br/>Naglig-on ug nagtangtang pa.<br/>',NULL,17332,3);
INSERT INTO stanza VALUES('CB492','4','Kay nausa Ka’s Espiritu,<br/>Pag-anhi N’ya pag-abot Mo,<br/>Kay na-Espiritu Ka na man,<br/>Pagpuyo N’ya, Imoha sab.<br/>',NULL,17333,4);
INSERT INTO stanza VALUES('CB492','5','Gituman Niya sa sulod ko<br/>Mga tinguha’g hangyo Mo,<br/>Sama sa pagbuhat Mo’s sugo<br/>Sa Amahan dinhi’s yuta.<br/>',NULL,17334,5);
INSERT INTO stanza VALUES('CB492','6','Sa pag-ila N’ya, naila Ka,<br/>Pagsugot N’ya, gisugot Ka;<br/>Sa pagpapuno namo Kan’ya,<br/>Nindot! Napuno mi Nimo.<br/>',NULL,17335,6);
INSERT INTO stanza VALUES('CB492','7','Di Ka layo nga naa’s langit,<br/>Daw ilo ming bulag Nimo,<br/>Nia gihapon Ka sa yuta,<br/>Nabuhi’s kasingkasing ko.<br/>',NULL,17336,7);
INSERT INTO stanza VALUES('CB493','1','Espiritu Ka na karon,<br/>Naghatag ug kinabuhi,<br/>Sa kadato Mo naglig-on,<br/>Kahimaya, pagkadiosnon!<br/>',NULL,17337,1);
INSERT INTO stanza VALUES('CB493','2','Espiritu Ka na karon,<br/>Nagpagawas sa gahum Mo;<br/>Ug ning pagkagawas kami<br/>Gibalaoran’s kinabuhi.<br/>',NULL,17338,2);
INSERT INTO stanza VALUES('CB493','3','Espiritu Ka na karon,<br/>Nagtransporma ug nagsurop,<br/>Gipasama mi’s dagway Mo,<br/>Naghayag sa kahayag Mo.<br/>',NULL,17339,3);
INSERT INTO stanza VALUES('CB493','4','Espiritu Ka na karon,<br/>Nagbalay’s espiritu ko;<br/>Nakigsakot’s esp’ritu ko,<br/>Nausa na sila karon.<br/>',NULL,17340,4);
INSERT INTO stanza VALUES('CB493','5','Ginoo, tudloi ako<br/>Mokontak Nimo’s esp’ritu,<br/>Aron maggawi’s Esp’ritu,<br/>Mabuhi’s realidad Mo.<br/>',NULL,17341,5);
INSERT INTO stanza VALUES('CB494','1','Cristo panghimatuod’s Dios<br/>Sa pagkamao’g sa buhat;<br/>Himaya sa Dios gipadayag N’ya,<br/>Diha N’ya ang Dios mabasa.<br/>',NULL,17342,1);
INSERT INTO stanza VALUES('CB494','2','Mas hingpit S’yang pamatuod<br/>Kaysa buhat’s kasugoan,<br/>Nga nagpakita’s Dios sa letra lang,<br/>Di’s way katapusang gahum.<br/>',NULL,17343,2);
INSERT INTO stanza VALUES('CB494','3','Naa N’yang kahupnganan’s Dios,<br/>Mao gyuy elemento N’ya;<br/>Hingpit gyud S’yang pagkalawas sa Dios—<br/>Sudlanang gipuy-an sa Dios.<br/>',NULL,17344,3);
INSERT INTO stanza VALUES('CB494','4','Gipadayag N’yang Amahan,<br/>Kinaiya gipakita;<br/>Diha N’ya hingpit gyud nga nakita<br/>Ang kasingkasing’s Amahan.<br/>',NULL,17345,4);
INSERT INTO stanza VALUES('CB494','5','Nia’s Cristo nga Esp’ritu<br/>Aron ma-pahat S’ya nato’s dayon;<br/>Maambitan’s espiritu<br/>Tanan Niyang pagkamao.<br/>',NULL,17346,5);
INSERT INTO stanza VALUES('CB495','1','Sentro sa Dios si Cristo,<br/>Iya sab nga paglukop;<br/>S’ya ang kalipay sa Dios<br/>Hangtud gyud’s eternidad.<br/>',NULL,17347,1);
INSERT INTO stanza VALUES('CB495','2','Pagkalawas S’ya sa Dios,<br/>Gipuy-an’s kahupnganan;<br/>Sa Iya nga pagkadios<br/>Labaw Siya sa tanan.<br/>',NULL,17348,2);
INSERT INTO stanza VALUES('CB495','3','Tuyo’s Dios alang Niya,<br/>Ma-tanan sa tanan S’ya;<br/>Butang’s langit ug yuta<br/>Gibuhat diha Niya.<br/>',NULL,17349,3);
INSERT INTO stanza VALUES('CB495','4','Kabuhatan alang N’ya,<br/>S’yay nagbuhat sa tanan;<br/>Kan’ya nilungtad tanan,<br/>S’yay sentro ug utlanan.<br/>',NULL,17350,4);
INSERT INTO stanza VALUES('CB495','5','S’yay tanan’s katubsanan,<br/>Nagpasig-uli’s tanan;<br/>Pinaagi’s dugo N’ya<br/>Karon may kadaitan.<br/>',NULL,17351,5);
INSERT INTO stanza VALUES('CB495','6','Siyay dakong pagsugod<br/>Buhing Ulo’s Iglesia;<br/>Kinabuhi’g sulod n’ya,<br/>Panganay’s mga patay.<br/>',NULL,17352,6);
INSERT INTO stanza VALUES('CB495','7','Hari S’ya’s Gingharian,<br/>Sa gahum gihatagan;<br/>Sa himaya maghari<br/>Dinhi’s yuta ug langit.<br/>',NULL,17353,7);
INSERT INTO stanza VALUES('CB495','8','Sa bag-ong langit, yuta,<br/>Ma-sentro Siya’s tanan,<br/>Alang’s Dios o tawo ba<br/>Hangtud’s way katapusan.<br/>',NULL,17354,8);
INSERT INTO stanza VALUES('CB495','9','Gituyo’s Dios ang tanan,<br/>Si Cristo m’oy mag-una,<br/>Ug masinati Siya<br/>Nga atong tanan’s tanan.<br/>',NULL,17355,9);
INSERT INTO stanza VALUES('CB496','1','Si Cristo ray realidad’s tanan,<br/>Sa Dios o tawo ba’g ubang butang;<br/>Gawas Niya ang Dios di mapalgan;<br/>Gawas kon na’ S’ya, tanan bakak man.<br/>',NULL,17356,1);
INSERT INTO stanza VALUES('CB496','2','Tanang hulagway’s daang panahon,<br/>Tanang kin’hanglan ta, dagko’g gagmay;<br/>Pulos mga landong sa Cristo’s Dios,<br/>Nagpakita ma-tanan gyud S’ya’s tanan.<br/>',NULL,17357,2);
INSERT INTO stanza VALUES('CB496','3','Tanang butang kakawangan gayud<br/>Kondi’ mapuno’g Cristong tinuod;<br/>Tanan mapa’muslan ma’g maato,<br/>Basyo gihapon ta kon way Cristo.<br/>',NULL,17358,3);
INSERT INTO stanza VALUES('CB496','4','Cristo tinuod tang Dios, Ginoo,<br/>Tinuod kinabuhi’g kahayag,<br/>Tinuod tang kalan-o’g ilimnon,<br/>Tinuod ta nga biste ug gahum.<br/>',NULL,17359,4);
INSERT INTO stanza VALUES('CB496','5','Cristo mao ray realidad sab<br/>Sa tanang teolohiya’g doktrina;<br/>Tanang kahibalo’s Kasulatan<br/>Kon wa S’ya, letra’g kakawangan lang.<br/>',NULL,17360,5);
INSERT INTO stanza VALUES('CB496','6','Realidad S’ya’s panaho’g luna,<br/>Realidad S’ya sa matag hugna;<br/>Bugtong realidad S’ya sa tanan,<br/>Sa panapanahon hangtud’s dayon.<br/>',NULL,17361,6);
INSERT INTO stanza VALUES('CB497','1','Labing habog kahulogan’s grasya<br/>Dios sa Anak mapahimuslan ta;<br/>Di butang nahatag o nabuhat,<br/>Kondi’ Dios mismo, na-atong pahat.<br/>',NULL,17362,1);
INSERT INTO stanza VALUES('CB497','2','Dios natawo’s unod aron madawat<br/>Ug masinati gyud nato mismo;<br/>Grasya kining nadawat nato’s Dios,<br/>Naggikan ni Cristo ug S’ya mismo.<br/>',NULL,17363,2);
INSERT INTO stanza VALUES('CB497','3','Giisip ni Pablo’ng tanan biya,<br/>Dios dihang Cristo ray iyang grasya;<br/>Ginoong nasinati—grasya n’ya—<br/>Nagpalabaw n’ya’s tanan sa lumba.<br/>',NULL,17364,3);
INSERT INTO stanza VALUES('CB497','4','Cristo kusog sa sulod m’oy grasya,<br/>Gipun-an’s pagkaigo N’ya’s tanan;<br/>Kini ang naa’s espiritu ta,<br/>Nagpalagsik pagbuhat’s buot N’ya.<br/>',NULL,17365,4);
INSERT INTO stanza VALUES('CB497','5','Kining grasya nga si Cristo mismo<br/>M’oy gikin’hangla’g sination ta;<br/>Makaila unta mi’g mabuhi<br/>Sa Imong Kaugalingon nga grasya.<br/>',NULL,17366,5);
INSERT INTO stanza VALUES('CB498','1','Matahum kong sugilanon,<br/>Nia na si Cristo;<br/>Sa kasingkasing nagpuyo,<br/>Haring mahimayaon.<br/>',NULL,17367,1);
INSERT INTO stanza VALUES('CB498','chorus','Cristo nia na sa sulod ko,<br/>Nia sa sulod ko!<br/>Cristo nia na sa sulod ko,<br/>S’yang paglaum ko.<br/>',NULL,17368,2);
INSERT INTO stanza VALUES('CB498','2','Sugilanong makatandog,<br/>Sa gugma’g kasakit;<br/>May mas mapanggaon pa ba,<br/>Makadani nato.<br/>',NULL,17369,3);
INSERT INTO stanza VALUES('CB498','3','Nalipayng nadawat ko S’ya,<br/>Hari’s kasingkasing;<br/>Sagad nakapasubo N’ya,<br/>Maghalad na’s tanan.<br/>',NULL,17370,4);
INSERT INTO stanza VALUES('CB498','4','Dili na mag-inusara,<br/>Di na sab matumba;<br/>Kanako wa nay makulang,<br/>Tanan sa tanan S’ya.<br/>',NULL,17371,5);
INSERT INTO stanza VALUES('CB498','5','Iyang sabakan gidangpan,<br/>Mao unyay awit;<br/>Nagpabilin ko ni Cristo,<br/>Ug Siya kanako.<br/>',NULL,17372,6);
INSERT INTO stanza VALUES('CB499','1','Kinabuhi! O kalinaw!<br/>Si Cristo nabuhi’s sulod.<br/>Gilansang uban Kaniya;<br/>Mahimayaong kal’wasan.<br/>Karon di ako nabuhi,<br/>Kondi’s Cristo sa sulod ko!<br/>',NULL,17373,1);
INSERT INTO stanza VALUES('CB499','2','O kalipay! O pahulay!<br/>Cristo nahulma’s sulod ko.<br/>Kinabuhi’g kinaiya<br/>Iyang giumol kanako.<br/>Akong tanan gitapos N’ya,<br/>S’ya nahimong akong tanan.<br/>',NULL,17374,2);
INSERT INTO stanza VALUES('CB499','3','O himaya! Dakong garbo!<br/>Mapadako nako’s Cristo.<br/>Way butang makapaulaw,<br/>Kay S’yang iaplikar’s tanan.<br/>Maalaut o mabuwahan,<br/>Cristo ipamatuod ko.<br/>',NULL,17375,3);
INSERT INTO stanza VALUES('CB499','4','O ganti, balus maako,<br/>Tumong S’ya nga giagpas ko.<br/>Way gimahal, gitinguha,<br/>S’ya rang malangkubon’s tanan.<br/>Cristo himaya, paglaum,<br/>Ang wala gyuy makatupong.<br/>',NULL,17376,4);
INSERT INTO stanza VALUES('CB500','1','Kadako’s gahum nga gibanhaw<br/>Sa Dios ni Cristo’s mga patay.<br/>Sa too N’ya gipalabaw,<br/>Ma-Ulo S’ya natong tanan.<br/>Gahum N’ya adto’s Iglesia,<br/>Aron kaaway matumban.<br/>',NULL,17377,1);
INSERT INTO stanza VALUES('CB500','2','Bulahang kamatuoran,<br/>Nga bahin na ko ni Cristo.<br/>Nasakot’s tanang balaan,<br/>Na-kinabuhing bag-ong tawo.<br/>Nausa’s Ulong nikayab,<br/>Ma-iglesia sa plano N’ya.<br/>',NULL,17378,2);
INSERT INTO stanza VALUES('CB500','3','Kalapad, kataas, kalawum,<br/>Kahabog N’ya di matugkad!<br/>Way kinutoban si Cristo,<br/>Di masukod ang kadako.<br/>Pagkamao’g naa Niya,<br/>Kinabuhi nato karon.<br/>',NULL,17379,3);
INSERT INTO stanza VALUES('CB501','1','Mahimayaon nga Cristo,<br/>Pagpadayag’s himaya’s Dios;<br/>Dios untang way kinutoban,<br/>Natawo’s panahon, napugngan.<br/>',NULL,17380,1);
INSERT INTO stanza VALUES('CB501','chorus','Cristo m’oy pagpadayag sa Dios,<br/>Di makabsan’s kadato;<br/>Dios nga nausa sa tawo,<br/>Nia nako akong tanan.<br/>',NULL,17381,2);
INSERT INTO stanza VALUES('CB501','2','Naa Nimong kadato’s Dios,<br/>Himaya N’ya gipadayag;<br/>Kanhi’s unod m’oy nagtubos,<br/>Esp’ritu nang usa nako.<br/>',NULL,17382,3);
INSERT INTO stanza VALUES('CB501','3','Imo ang tanan’s Amahan,<br/>Tanang Imo m’oy naako;<br/>Gipatinuod’s Esp’ritu,<br/>Aron Ka masinati ko.<br/>',NULL,17383,4);
INSERT INTO stanza VALUES('CB501','4','Esp’ritu magbalhin Nimo<br/>Agi’s Pulong nganhi nako.<br/>Pagtandog’s Esp’ritu’g pulong,<br/>Masamkong kinabuhi Mo.<br/>',NULL,17384,5);
INSERT INTO stanza VALUES('CB501','5','Sa nagsud-ong daw salamin,<br/>Nagsumbalik’s himaya Mo,<br/>Matransporma sama Nimo,<br/>Mapadayag Ka na nako.<br/>',NULL,17385,6);
INSERT INTO stanza VALUES('CB501','6','Wa nay lain nga paagi<br/>Mabalaan, makadaug;<br/>Mag-espirituhanon lang,<br/>Kinabuhi na’s himaya.<br/>',NULL,17386,7);
INSERT INTO stanza VALUES('CB501','7','Suropan ko’s Esp’ritu Mo,<br/>Tuhopan’s Dios matag bahin ko,<br/>Ipagawas ko’s daang tawo,<br/>Matukod alang’s plano Mo.<br/>',NULL,17387,8);
INSERT INTO stanza VALUES('CB505','1','May Tawo didto’s himaya,<br/>Alang nako S’ya;<br/>Putli, balaan ug<br/>Madaugon S’ya;<br/>Mahigugmaon gyud,<br/>O pagkalomo!<br/>Makinabuhi ko<br/>S’ya’s himaya;<br/>Makinabuhi ko<br/>S’ya’s himaya.<br/>',NULL,17388,1);
INSERT INTO stanza VALUES('CB505','2','May Tawo didto’s himaya,<br/>Alang nako S’ya,<br/>Nidaug S’ya’s yawa,<br/>Wa S’ya magapos.<br/>Buhi S’yang naghari;<br/>Pagkahalangdon!<br/>Makinabuhi ko<br/>S’ya’s himaya;<br/>Makinabuhi ko<br/>S’ya’s himaya.<br/>',NULL,17389,2);
INSERT INTO stanza VALUES('CB505','3','May Tawo didto’s himaya,<br/>Alang nako S’ya,<br/>Way sakit, kaluya;<br/>Makusganon S’ya.<br/>Puno’s kinabuhi,<br/>O pagkalagsik!<br/>Makinabuhi ko<br/>S’ya’s himaya;<br/>Makinabuhi ko<br/>S’ya’s himaya.<br/>',NULL,17390,3);
INSERT INTO stanza VALUES('CB505','4','May Tawo didto’s himaya,<br/>Alang nako S’ya,<br/>Sigeng kalinaw N’ya;<br/>Mapailubon!<br/>Sadya’g malipayon,<br/>Busa naglaum<br/>Ikinabuhi na<br/>Siya nako;<br/>Ikinabuhi na<br/>Siya nako.<br/>',NULL,17391,4);
INSERT INTO stanza VALUES('CB509','1','Subang nag-agay ug kahoy,<br/>M’oy makita dayon’s Eden,<br/>Kalan-ong sangkap sa tawo,<br/>Mabuhi s’ya’s dayon.<br/>',NULL,17392,1);
INSERT INTO stanza VALUES('CB509','chorus','Dios dihang Cristo ma-sangkap ko,<br/>Dios Espiritu nagpakaon;<br/>Kon mokaon ako ni Cristo,<br/>Kan’ya mapuno ko.<br/>',NULL,17393,2);
INSERT INTO stanza VALUES('CB509','2','Kahoy nagpakitang Cristo,<br/>Kalan-ong sangkap sa tawo,<br/>Kadato’s Dios makaon n’ya,<br/>Ug matagbaw siya.<br/>',NULL,17394,3);
INSERT INTO stanza VALUES('CB509','3','Subang maong Espiritu,<br/>Magsangkap’s espiritu’s tawo,<br/>Mapuno s’ya’s kadato’s Dios<br/>Ug mabalaan s’ya.<br/>',NULL,17395,4);
INSERT INTO stanza VALUES('CB509','4','Kinabuhi nako’s Cristo,<br/>Nagpuyo S’ya’s esp’ritu ko,<br/>Hingpit ko nga masakot’s Dios,<br/>Magsidlak’s dagway N’ya.<br/>',NULL,17396,5);
INSERT INTO stanza VALUES('CB509','5','Cristo’s himaya ituboy,<br/>Espiritu sugton ko gyud,<br/>Ipailang himaya N’ya,<br/>Mapuno ko’s grasya.<br/>',NULL,17397,6);
INSERT INTO stanza VALUES('CB510','1','Napalgang labing bililhon,<br/>Nag-awit’s kalipay;<br/>Moawit gyud kay naako,<br/>O unsa nga Cristo!<br/>',NULL,17398,1);
INSERT INTO stanza VALUES('CB510','2','Cordero’s Dios ang Cristo ko,<br/>Kal’wasan ’yang dala,<br/>Adlaw’s Pagkamatarung S’ya,<br/>Pako makaayo.<br/>',NULL,17399,2);
INSERT INTO stanza VALUES('CB510','3','Kahoy sa Kinabuhi S’ya,<br/>Hitik’s bungang tam-is;<br/>Kagutom ko ’yang gitagbaw,<br/>Kan-on matag adlaw.<br/>',NULL,17400,3);
INSERT INTO stanza VALUES('CB510','4','Cristo ko Batong gihampak,<br/>Buhing tubig nibugwak;<br/>Tuboran S’ya’s kasingkasing,<br/>Nagkuha’s kauhaw.<br/>',NULL,17401,4);
INSERT INTO stanza VALUES('CB510','5','Kinabuhi S’ya’g kalipay,<br/>Kahimsog, dalan ko,<br/>Kalinaw, paglaum, pahuway,<br/>Himaya’g kadato.<br/>',NULL,17402,5);
INSERT INTO stanza VALUES('CB510','6','Kaalam, gahum, katarung,<br/>Garbo’g kadaugan,<br/>Katubsanan, kamat’oran<br/>Ug pagkabalaan.<br/>',NULL,17403,6);
INSERT INTO stanza VALUES('CB510','7','Manluluwas, Magbalantay,<br/>Ginoo’g Manlalaban,<br/>Magtatambag, Dios, Amahan,<br/>Igsoon, Higala.<br/>',NULL,17404,7);
INSERT INTO stanza VALUES('CB510','8','Capitan, Gwardya, ug Giya,<br/>Magtutudlo, Ulo,<br/>Pamanhonon ug Agalon<br/>Nagpuyo’s sulod ko.<br/>',NULL,17405,8);
INSERT INTO stanza VALUES('CB510','9','Sacerdote, Hari, Propeta,<br/>Puno’s pagkakita;<br/>Sacerdoteng tigpataliwa’,<br/>Hari nga naggahum.<br/>',NULL,17406,9);
INSERT INTO stanza VALUES('CB510','10','Mag-uugda’s pagtoo ko,<br/>Maghihingpit usab,<br/>Tigpatunga’g Kalig-onan,<br/>Saksing kasaligan.<br/>',NULL,17407,10);
INSERT INTO stanza VALUES('CB510','11','Cristo, dayong puloy-anan,<br/>Yutang dato gayud;<br/>Kuta, torre, tagoanan,<br/>Dayong baruganan.<br/>',NULL,17408,11);
INSERT INTO stanza VALUES('CB510','12','Igpahulay, bag-ong bulan,<br/>Buntag ko ug adlaw,<br/>Edad ko ug eternidad,<br/>Wa gyuy pagkahanaw.<br/>',NULL,17409,12);
INSERT INTO stanza VALUES('CB510','13','Pagsalig ko ug tinguha,<br/>Matahum kaayo,<br/>Katagbawan, kalipayan,<br/>Nagtagbo sa tanan.<br/>',NULL,17410,13);
INSERT INTO stanza VALUES('CB510','14','Cristo malangkubon’s tanan,<br/>Unsay ingalan ko?<br/>Sinugdan ug katapusan,<br/>S’yang tanan sa tanan.<br/>',NULL,17411,14);
INSERT INTO stanza VALUES('CB510','15','Kay naako S’yang bahandi,<br/>Mag-awit’s kalipay;<br/>Balikbalik kong awiton,<br/>O unsa nga Cristo!<br/>',NULL,17412,15);
INSERT INTO stanza VALUES('CB511','1','Jesus lang ang mensahe ta,<br/>M’oy tema nato’s tanan;<br/>Si Jesus lang ang ituboy,<br/>Si Jesus ray makita.<br/>',NULL,17413,1);
INSERT INTO stanza VALUES('CB511','chorus','Si Jesus ra, S’ya ra gayud,<br/>Awiton ta sa tanan,<br/>Manluluwas ug Mananambal,<br/>Ginoo’g Haring moabot.<br/>',NULL,17414,2);
INSERT INTO stanza VALUES('CB511','2','Si Jesus ray Manlul’was ta,<br/>Tanang sala giako N’ya,<br/>Pagkamatarung S’ya’s dayon,<br/>S’yang kusog adlawng tanan.<br/>',NULL,17415,3);
INSERT INTO stanza VALUES('CB511','3','Tigbalaang nagl’was nato,<br/>Sa sala’g kaugalingon,<br/>Kahupnganan’s Esp’ritu N’ya,<br/>Magpuno’s kasingkasing ta.<br/>',NULL,17416,4);
INSERT INTO stanza VALUES('CB511','4','Si Jesus ray Mananambal ta,<br/>Nag-ayo’s balatian;<br/>Kinabuhi’g pagkabanhaw,<br/>Maambitan gihapon.<br/>',NULL,17417,5);
INSERT INTO stanza VALUES('CB511','5','Si Jesus ray atong Gahum,<br/>Gasa S’ya’s Pentecostes;<br/>Ginhawai mi, O Jesus,<br/>Pun-a sa Espiritu.<br/>',NULL,17418,6);
INSERT INTO stanza VALUES('CB511','6','Ug naghulat ta ni Jesus,<br/>Mamati sa tawag N’ya;<br/>Apan Jesus lang gihapon,<br/>S’ya ra gyud hangtud’s dayon.<br/>',NULL,17419,7);
INSERT INTO stanza VALUES('CB513','1','Kanhi panalangin,<br/>Karon Ginoo;<br/>Kanhi sa pagbati,<br/>Karon ’yang Pulong;<br/>Kanhi Iyang hatag,<br/>Karon’s Naghatag;<br/>Kanhi nagpatambal<br/>Karon Siya ra.<br/>',NULL,17420,1);
INSERT INTO stanza VALUES('CB513','chorus','Ang tanan sa tanan,<br/>Cristo awitan;<br/>Ang tanan kang Cristo<br/>Cristo akong tanan.<br/>',NULL,17421,2);
INSERT INTO stanza VALUES('CB513','2','Kanhi naningkamot,<br/>Karon nisalig;<br/>Kanhi medyo nal’was,<br/>Karon hingpit na;<br/>Kanhi sige’g gunit,<br/>Karon S’yay gunit;<br/>Kanhi anud-anud,<br/>Karon pundo na.<br/>',NULL,17422,3);
INSERT INTO stanza VALUES('CB513','3','Kanhi sige’g plano<br/>Karon nag-ampo;<br/>Kanhi kabalaka,<br/>Karon S’yay duma’;<br/>Kanhi akong gusto,<br/>Sige ug hangyo,<br/>Karon S’yay pabut-on,<br/>Kanunayng daygon.<br/>',NULL,17423,4);
INSERT INTO stanza VALUES('CB513','4','Kanhi akong buhat,<br/>Mogamit Niya,<br/>Karon S’yay magbuhat,<br/>Paggamit nako,<br/>Kanhi kaugalingong<br/>Gusto ug gahum,<br/>Karon Ma’gagahum<br/>Ray tinguhaon.<br/>',NULL,17424,5);
INSERT INTO stanza VALUES('CB513','5','Kanhi naglaum N’ya,<br/>Suga nag-awop,<br/>Karon naako S’ya,<br/>Masanagon na;<br/>Kanhi kamatayon<br/>M’oy gipaabot;<br/>Karon paglaum ko<br/>Pagbalik na N’ya.<br/>',NULL,17425,6);
INSERT INTO stanza VALUES('CB517','1','Jesus Manluluwas akong tanan,<br/>Pagkamaayong Manluluwas S’ya,<br/>Sa balud’s kinabuhi naggiya,<br/>Gamhanang Tigl’was—alang nako.<br/>',NULL,17426,1);
INSERT INTO stanza VALUES('CB517','chorus','Jesus alang<br/>Gayud nako,<br/>Tanang panahon<br/>Ug tanang dapit.<br/>',NULL,17427,2);
INSERT INTO stanza VALUES('CB517','2','Jesus sa kahimsog, balatian,<br/>Jesus sa kakabus, kaharuhay;<br/>Init o bagyo, bisan unsa pa,<br/>Hilwas ko kay alang S’ya nako.<br/>',NULL,17428,3);
INSERT INTO stanza VALUES('CB517','3','S’yang Dangpanan, Bato ug Torre ko,<br/>Akong Kuta, Kalig-on, ug Gahum;<br/>Kinabuhing dayon, ug Tighusay,<br/>Manunubos S’ya alang nako.<br/>',NULL,17429,4);
INSERT INTO stanza VALUES('CB517','4','Propeta, Sacerdote, Hari ko,<br/>Tinapay’s kinabuhi, Tuboran;<br/>Adlaw’s Pagkamatarung, Bitoon,<br/>Sungay’s Kal’wasan—alang nako.<br/>',NULL,17430,5);
INSERT INTO stanza VALUES('CB517','5','Jesus sa kasubo o kalipay,<br/>Bahandi ko S’ya’s pilde ba’g daug;<br/>Kauban nako bisan asa ko,<br/>Buhi ba’g patay—alang nako.<br/>',NULL,17431,6);
INSERT INTO stanza VALUES('CB518','1','Kinsa may ako sa langit?<br/>Ikaw ra, Ginoo!<br/>Ug awiton ko sa dayon,<br/>Alang nako’s Cristo!<br/>Gitumban na N’ya ang bitin,<br/>Gitubos ko “sa dugo N’ya,“<br/>Kalag gipasig-uli’s Dios:<br/>Cristo alang nako!<br/>',NULL,17432,1);
INSERT INTO stanza VALUES('CB518','2','Wa masina’s duwaan’s dato,<br/>Cristo alang nako!<br/>Wa maibog’s duwaan’s yuta,<br/>Cristo alang nako!<br/>Hatag’s yuta way magdugay,<br/>“Molubad” mang tanan dinhi,<br/>Kalipay ko di matapos:<br/>Cristo alang nako!<br/>',NULL,17433,2);
INSERT INTO stanza VALUES('CB518','3','Bisan kakabus m’oy palad,<br/>Cristo alang nako!<br/>“S’ya nasayud’s ma’yo nako,“<br/>Cristo alang nako!<br/>Bisan higuera way bunga,<br/>Ang parras ug ang oliva,<br/>Toril way kanding ni baka,<br/>Cristo alang nako!<br/>',NULL,17434,3);
INSERT INTO stanza VALUES('CB518','4','Bisan na’s yuta’s kaaway,<br/>Cristo alang nako!<br/>Ug gilikosan ko’s sala,<br/>Cristo alang nako!<br/>Pakusga’g gubat ang yuta,<br/>Kalag ko awayon nila,<br/>Yam-iran kanang kapintas,<br/>Cristo alang nako!<br/>',NULL,17435,4);
INSERT INTO stanza VALUES('CB518','5','Kon kinabuhi matapos,<br/>Cristo alang nako!<br/>Magpahulay ko’s ’yang bukton,<br/>Cristo alang nako!<br/>Bisan lawas masakit man,<br/>Sa akong kusog mawad-an,<br/>Sa gihapon mag-awit ko;<br/>Cristo alang nako!<br/>',NULL,17436,5);
INSERT INTO stanza VALUES('CB522','1','Diha Kanimo, O Cristo,<br/>Napalgan’s kalag ko<br/>Ang kalinaw ug kalipayng<br/>Dugayng gipangita.<br/>',NULL,17437,1);
INSERT INTO stanza VALUES('CB522','chorus','Makatagbaw si Cristo ra,<br/>Wala nay lain pa;<br/>Gugma, kinabuhi’g kalipay,<br/>Napalgan diha Nimo.<br/>',NULL,17438,2);
INSERT INTO stanza VALUES('CB522','2','Nangandoy’s pahuway’g kalipay,<br/>Di’s Kaugalingon Mo,<br/>Manluluwas gilabyan ko,<br/>Gikuptan’s gugma N’ya.<br/>',NULL,17439,3);
INSERT INTO stanza VALUES('CB522','3','Liking sudlanan giimnan,<br/>Tubig nihubas man;<br/>Niduko unta’g moinom,<br/>Apan way nakuha.<br/>',NULL,17440,4);
INSERT INTO stanza VALUES('CB522','4','Nasubo’s kalipayng nawa’,<br/>Dili alang Nimo;<br/>Hangtud nakit-an na nako,<br/>Ang pagkatahum Mo.<br/>',NULL,17441,5);
INSERT INTO stanza VALUES('CB523','1','Nia karon’s buhing Tuboran,<br/>Nga gikan sa kahitas-an;<br/>Tubig sa kasamok nalabyan,<br/>Nia’s gugma’s Elim karon;<br/>Atabayng langitnon nainom,<br/>Sa akong sulod nagtubod,<br/>Kalami dili gyud maasoy,<br/>Sa kalipay nga gihatud.<br/>',NULL,17442,1);
INSERT INTO stanza VALUES('CB523','chorus','Ari’s Tuboran’s Kinabuhi,<br/>Nga wala gyuy pagkauga;<br/>Inom sa dagayang sangkap,<br/>Tuboran S’ya’s kinabuhi.<br/>',NULL,17443,2);
INSERT INTO stanza VALUES('CB523','2','Nia sa Tuboran sa Dugo,<br/>Alang sa sala’g kahugaw,<br/>Nagpahugas’ dugong mohinlo,<br/>Puti pa’s nieveng biste ko.<br/>Di kini pagkamatarung ko,<br/>Kang Jesus nga na’s kalag ko.<br/>Sa kinaiya N’ya niambit,<br/>Diha N’ya ako nahingpit.<br/>',NULL,17444,3);
INSERT INTO stanza VALUES('CB523','3','Nia sa Tuboran’s Kahimsog,<br/>Sangkap N’ya way pagkahurot;<br/>Di mapalit kining sekreto<br/>Sa kaalam, bahandi’s tawo.<br/>Apan kini gipadayag na<br/>Sa tuboran sa kilid N’ya,<br/>Naayo kita’s Iyang labud,<br/>Sa pagpuyo Niya’s sulod.<br/>',NULL,17445,4);
INSERT INTO stanza VALUES('CB523','4','Nia sa Tuboran’s Kalipay,<br/>Kalipay N’ya m’oy kusog ko.<br/>Kahayag ko di magpalayo,<br/>Pagkalunsay’s kalipay ko.<br/>Kalipayan, higayon mawa’<br/>Mamatay kahoyng higuera,<br/>Tuboran ko di gyud mauga,<br/>Diosnong pahat ning akoa.<br/>',NULL,17446,5);
INSERT INTO stanza VALUES('CB529','1','Kon di makita si Jesus,<br/>Takna pagkalaay gayud;<br/>Bisan unsa nga matahum,<br/>Wa nay gana nga tan-awon.<br/>Bisan adlaw masanagon,<br/>Kanako sama’s nagdag-um;<br/>Diha N’ya kon malipayon,<br/>Sama’s Mayo ang Disyembre.<br/>',NULL,17447,1);
INSERT INTO stanza VALUES('CB529','2','Ngalan N’ya labing mahumot,<br/>Tingog N’ya tam-is pa’s honi;<br/>Presensya, magwa’s kaguol,<br/>Maglipay’s tanan’s sulod ko.<br/>Kon kanunay lang S’yang duol,<br/>Wa na unta ko’y kahadlok;<br/>Way sama nako’s kalipay,<br/>Molungtad ni’s tibu’k tuig.<br/>',NULL,17448,2);
INSERT INTO stanza VALUES('CB529','3','Kontento nang magsud-ong N’ya,<br/>Tanan ko S’ya ray lipayon;<br/>Dapit, panahon mabalhin,<br/>Hunahuna magpabilin.<br/>Mabati nganing gugma N’ya,<br/>Palasyo dulaan ko ra;<br/>Prisohan man ma-palasyo,<br/>Kon uban S’ya’g puyo didto.<br/>',NULL,17449,3);
INSERT INTO stanza VALUES('CB529','4','Ginoo, kon ako Imo,<br/>Kon Adlaw Ka ug awit ko;<br/>Nganong nagsubo lagi ko?<br/>Kalaay ko pagkadugay?<br/>Panganud ko aboga na,<br/>Presensya Mo ibalik na,<br/>Dad-a uban Nimo’s ’taas,<br/>Diin panganud wala na.<br/>',NULL,17450,4);
INSERT INTO stanza VALUES('CB530','1','S’yang kinabuhi, kalipay,<br/>Tanan’s tanan nako;<br/>Adlaw-adlaw kusog ko S’ya;<br/>Maluya ko kon wa S’ya.<br/>Kon magsubo, adto ko N’ya;<br/>S’ya ray makalipay nako.<br/>S’yang Higala nga maglipay<br/>Kanako.<br/>',NULL,17451,1);
INSERT INTO stanza VALUES('CB530','2','Si Jesus ang akong tanan,<br/>Matuod kong Abyan,<br/>Adto N’ya magpabulahan,<br/>Bulahanon gyud N’ya.<br/>Init, ulan ’yang padad-an;<br/>Trigong maaning kalan-on;<br/>Init, ulan, trigong kan-on—<br/>Abyan S’ya.<br/>',NULL,17452,2);
INSERT INTO stanza VALUES('CB530','3','Si Jesus ang akong tanan,<br/>Magmatinud-anon;<br/>Makalimod ba’s matuod<br/>Kaayo nga Abyan?<br/>Sayud kong hustong sundon S’ya;<br/>Gibantayan ako Niya.<br/>Sundon S’ya adlaw’g gabii,<br/>Abyan S’ya.<br/>',NULL,17453,3);
INSERT INTO stanza VALUES('CB530','4','Si Jesus ang akong tanan,<br/>Way mas ma’yong Abyan.<br/>Saligan S’ya hangtud gayud<br/>Matapos ang adlaw ko.<br/>Nindot mabuhing S’yay Abyan;<br/>Kinabuhing way pagtapos!<br/>Kalipay nga hangtud’s dayon,<br/>Abyan S’ya.<br/>',NULL,17454,4);
INSERT INTO stanza VALUES('CB531','1','Kalipay mawala,<br/>Jesus ako.<br/>Bisan paghigugma,<br/>Jesus ako.<br/>Ni’ning kamingawan<br/>Way kapahulayan,<br/>S’ya ray mobulahan;<br/>Jesus ako.<br/>',NULL,17455,1);
INSERT INTO stanza VALUES('CB531','2','Ayaw ko’g tintala,<br/>Jesus ako.<br/>Mopuyo uban N’ya;<br/>Jesus ako.<br/>Butang mangalaglag,<br/>Kadyut ra mabuhi,<br/>Labying kasingkasing;<br/>Jesus ako.<br/>',NULL,17456,2);
INSERT INTO stanza VALUES('CB531','3','Lakaw na, damgo ko,<br/>Jesus ako.<br/>Nahigmata na ko,<br/>Jesus ako.<br/>Tanan nasulayan,<br/>Lunlon kakawangan,<br/>S’ya ray katagbawan;<br/>Jesus ako.<br/>',NULL,17457,3);
INSERT INTO stanza VALUES('CB531','4','Labyi, kamatayon,<br/>Jesus ako.<br/>Ari, eternidad,<br/>Jesus ako.<br/>Ari, Hinigugma,<br/>Ari, O pahulay,<br/>Sabakan’s Manlul’was;<br/>Jesus ako.<br/>',NULL,17458,4);
INSERT INTO stanza VALUES('CB532','1','Kalinaw, Ikawng tinubdan,<br/>Pagkaigo sa gugma Mo;<br/>Ikawng tabang ug dangpanan,<br/>Lig-on ko kon akoa Ka;<br/>Sala, kaulaw’g kasubo,<br/>Sa ngalan Mo ako motago.<br/>',NULL,17459,1);
INSERT INTO stanza VALUES('CB532','2','Pagkamao Mo m’oy tanan,<br/>Pahulay ko’g kahupayan;<br/>Tambal sa kagul-anan ko;<br/>Kalinaw ko’g kaayohan;<br/>Purongpurong ug himaya,<br/>Panahon sa kaulawan.<br/>',NULL,17460,2);
INSERT INTO stanza VALUES('CB532','3','Sa kawalad-on, m’oy sangkap,<br/>Sa kaluyahon, m’oy gahum;<br/>Sa gapos ko, kagawasan;<br/>Kahayag ko’s kangitngitan,<br/>Mabuhi man o mamatay,<br/>S’yang kalipayng di maasoy.<br/>',NULL,17461,3);
INSERT INTO stanza VALUES('CB535','1','Posible ang tanan niya<br/>Nga nitoo’s ngalang Jesus;<br/>Di na pasipad-ang ngalan,<br/>Dawaton kong kamatuoran;<br/>Makahimo ko’g motoo,<br/>Posibleng tanan kanako.<br/>',NULL,17462,1);
INSERT INTO stanza VALUES('CB535','2','Labing imposible nako<br/>Nga di na magharing sala;<br/>Apan mahimo, mahimo,<br/>Kasaligan Ka, Ginoo;<br/>Kon way malisud Kanimo,<br/>Posibleng tanan kanako.<br/>',NULL,17463,2);
INSERT INTO stanza VALUES('CB535','3','Lalison sa yawa’ng Pulong,<br/>Di mapakyas sa gihapon;<br/>Pagbuot’s sala bungkagon;<br/>Seguro gyud bisag lisud.<br/>Kay ang butang imposible,<br/>Posibleng tanan kanako.<br/>',NULL,17464,3);
INSERT INTO stanza VALUES('CB535','4','Tanang butang mahimo’s Dios,<br/>Kang Cristo, nga gahum nako;<br/>Kanako, kon mabag-o ko,<br/>Maumol gyud ko pag-usab,<br/>Mahigawas na sa sala,<br/>Posibleng tanan kanako.<br/>',NULL,17465,4);
INSERT INTO stanza VALUES('CB535','5','Tanang butang mahimo’s Dios;<br/>Kang Cristo, nga gahum nako;<br/>Ibubong Kaugalingon Mo,<br/>Di na ako kondi’s Cristo<br/>Ang mabuhi, pamatud-an<br/>Gugma Mo pagkagamhanan.<br/>',NULL,17466,5);
INSERT INTO stanza VALUES('CB536','1','Cristo objectibo ug subjectibo,<br/>Alang nato S’ya’s langit nangamuyo;<br/>Subjectibong nabuhi’s atong sulod,<br/>Naghatag’s Iyang pagkamao nato.<br/>',NULL,17467,1);
INSERT INTO stanza VALUES('CB536','2','Sa langit naglingkod S’ya’s too sa Dios,<br/>Labawng Sacerdoteng naghalad’s dugo;<br/>Manlalaban nga nagpas-an’s luwan ta<br/>Kalig-onang nagtagad, puno’s gugma.<br/>',NULL,17468,2);
INSERT INTO stanza VALUES('CB536','3','S’yang Espiritu sa espiritu ta;<br/>Kinabuhi S’ya, nagda’s tanang butang;<br/>Kusog ug grasya ta’s tanang panahon,<br/>Paracletong nagsapnay uban’s gahum.<br/>',NULL,17469,3);
INSERT INTO stanza VALUES('CB536','4','Tawong gihimaya’s langit alang nato,<br/>Mag-uunang nagtuman’s plano sa Dios;<br/>Siya ang Anak ug diha Kaniya<br/>Ang tawo nahiusa sa Dios sa langit.<br/>',NULL,17470,4);
INSERT INTO stanza VALUES('CB536','5','Kahupnganan’s Dios nipuyo Kaniya;<br/>Espiritu S’yang nagda’s Dios sa sulod,<br/>Nagpadayag, nagmatuod’s Dios nato,<br/>Dios, kita, sa kinabuhi natukod.<br/>',NULL,17471,5);
INSERT INTO stanza VALUES('CB536','6','Nikayab’s langit, S’ya didto nagpuyo,<br/>Di madugay mobalik alang nato;<br/>Nagpuyo S’ya sa sulod nato karon,<br/>Di madugay usbon ta’g himayaon.<br/>',NULL,17472,6);
INSERT INTO stanza VALUES('CB536','7','Moabot nang adlaw, langit ug yuta<br/>Mahiusa sa syudad nga halangdon;<br/>Unya ang objectibo’g subjectibo<br/>Mausa’s sulod ta’s himayang dayon.<br/>',NULL,17473,7);
INSERT INTO stanza VALUES('CB537','1','Cristo subjectibo nako,<br/>Nagpuyo’s espiritu;<br/>Malangkubon-sa-tanan S’ya,<br/>Nausa S’ya kanako.<br/>',NULL,17474,1);
INSERT INTO stanza VALUES('CB537','chorus','Subjectibo kaayo’s Cristo nako!<br/>Tinuod, dato’g tam-is!<br/>Malangkubon’s tanan nako!<br/>Nagtagbo’s kin’hanglan ko.<br/>',NULL,17475,2);
INSERT INTO stanza VALUES('CB537','2','Cristo subjectibo nako,<br/>Naghatag’s kinabuhi;<br/>Espiritu S’yang nagdasig,<br/>Naglunhaw matag adlaw.<br/>',NULL,17476,3);
INSERT INTO stanza VALUES('CB537','3','Cristo subjectibo nako,<br/>Nagtransporma kanako;<br/>Hunahuna’g pagbuot ko<br/>Gibag-o, gisama N’ya.<br/>',NULL,17477,4);
INSERT INTO stanza VALUES('CB537','4','Cristo subjectibo nako,<br/>Gahum S’yang nagpagawas;<br/>Balaod’s kinabuhi, S’ya<br/>Espiritung nagtangtang.<br/>',NULL,17478,5);
INSERT INTO stanza VALUES('CB537','5','Cristo subjectibo nako,<br/>Tibu’k adlaw nagbuot;<br/>Nagtul-id ug naggiya S’ya,<br/>Nagpahiangay nako.<br/>',NULL,17479,6);
INSERT INTO stanza VALUES('CB537','6','Cristo subjectibo nako,<br/>Kauhaw ’yang gitagbaw;<br/>Kadato N’ya sangkap nako,<br/>Ma-kahupnganan Niya.<br/>',NULL,17480,7);
INSERT INTO stanza VALUES('CB538','1','Tuyo ug kalipay sa Dios<br/>Ibugna’s Cristo nako;<br/>Di relihiyong makita,<br/>Kondi’ Cristong na’s sulod.<br/>',NULL,17481,1);
INSERT INTO stanza VALUES('CB538','chorus','Tuyo ug kalipay sa Dios<br/>Cristo isulod nako;<br/>Dili dayag nga pagbuhat,<br/>Kondi’ Cristong tanan ko.<br/>',NULL,17482,2);
INSERT INTO stanza VALUES('CB538','2','Tuyo ug kalipay sa Dios<br/>Mabuhi’s Cristo nako;<br/>Way pakitang batasan lang,<br/>Kondi’ S’yang nagbuhat’s su’d.<br/>',NULL,17483,3);
INSERT INTO stanza VALUES('CB538','3','Tuyo ug kalipay sa Dios<br/>Cristo mahulma nako;<br/>Di mga porma ang sundon,<br/>Kondi’ S’yang nagtubo’s su’d.<br/>',NULL,17484,4);
INSERT INTO stanza VALUES('CB538','4','Tuyo ug kalipay sa Dios<br/>Cristo magbalay’s sulod;<br/>Di pakitang pag-alagad,<br/>Kondi’ S’yang nagpuyo’s su’d.<br/>',NULL,17485,5);
INSERT INTO stanza VALUES('CB538','5','Tuyo ug kalipay sa Dios<br/>Ma-paglaum ko’s Cristo;<br/>Di objectibong himaya,<br/>Kondi’ S’yang subjectibo.<br/>',NULL,17486,6);
INSERT INTO stanza VALUES('CB538','6','Tuyo ug kalipay sa Dios<br/>Ma-tanan’s Cristo nako;<br/>Way laing mapanag-iya,<br/>Si Cristo ra sa dayon.<br/>',NULL,17487,7);
INSERT INTO stanza VALUES('CB539','1','Kinabuhi Ka, Ginoo,<br/>Ug tanan kanako!<br/>Subjectibo, na’ kanunay,<br/>Masinati nako.<br/>',NULL,17488,1);
INSERT INTO stanza VALUES('CB539','chorus','Espiritu Ka, Ginoo!<br/>Mahal, duol nako!<br/>Daygon Ka’s kahibul’ngan nga<br/>Pagkana’ kanunay!<br/>',NULL,17489,2);
INSERT INTO stanza VALUES('CB539','2','Sa tanan kong kinahanglan<br/>Ikawng datong sangkap;<br/>Andam ug igo kaayo<br/>Nga mapa’muslan ko.<br/>',NULL,17490,3);
INSERT INTO stanza VALUES('CB539','3','Dihog Mo’g gahum, Ginoo,<br/>Sustener’s kaluya;<br/>Ang sangkap Mo nga kalagsik<br/>Naghatag ug kusog.<br/>',NULL,17491,4);
INSERT INTO stanza VALUES('CB539','4','Balaod sa kinabuhi<br/>Nagbuot’s gawi ko;<br/>Kadato’s realidad Mo<br/>Nagsurop kanako.<br/>',NULL,17492,5);
INSERT INTO stanza VALUES('CB539','5','O usa gyud Ka kanako,<br/>Usang di matupngan;<br/>Nausa’s tanang panahon,<br/>Karon ngadto’s dayon!<br/>',NULL,17493,6);
INSERT INTO stanza VALUES('CB540','1','Unsang kagawasang hatag!<br/>Gihubaran gyud ko N’ya!<br/>Gahum sa sala giguba,<br/>Kamatayon wala na!<br/>',NULL,17494,1);
INSERT INTO stanza VALUES('CB540','chorus','Gihimo’s pagdaug N’ya nga<br/>Labaw pa’s mananaug,<br/>Gahum Niya’s pagkabanhaw<br/>Naglig-on’s espiritu!<br/>',NULL,17495,2);
INSERT INTO stanza VALUES('CB540','2','Gil’was ko N’ya’s kasugoan,<br/>Patay na’s sugo ni’ni;<br/>Di na kini makagapos,<br/>Nabuhi na ko’s grasya.<br/>',NULL,17496,3);
INSERT INTO stanza VALUES('CB540','3','Sala gihukman’s Calvario,<br/>Gahum ni’ni giwala;<br/>Wa nay luna’s sulod nako,<br/>Wa na ko’s gahum ni’ni.<br/>',NULL,17497,4);
INSERT INTO stanza VALUES('CB540','4','Kinabuhing di madunot,<br/>Giwa’ N’yang kamatayon;<br/>Gapos ni’ni gibugto na,<br/>Pagkabanhaw naila.<br/>',NULL,17498,5);
INSERT INTO stanza VALUES('CB540','5','Namatay, yawa gidugmok,<br/>Kalibuta’g demonyo;<br/>Gibalhin gikan’s kangitngit,<br/>Sa kinabuhi’g kahayag.<br/>',NULL,17499,6);
INSERT INTO stanza VALUES('CB540','6','Igong grasya ang ’yang hatag,<br/>Gitabonan’s gahum N’ya.<br/>Nagpagarbo’s kaluyahon,<br/>Kay Siya ang maglig-on.<br/>',NULL,17500,7);
INSERT INTO stanza VALUES('CB541','1','Di ang mga letra,<br/>Kondi’ si Cristo,<br/>Buot ihatag’s Dios<br/>Magluwas nato;<br/>Di mga doktrina,<br/>Kondi’ S’ya mismo<br/>Ang maghubad nato<br/>Sa kaugalingon.<br/>',NULL,17501,1);
INSERT INTO stanza VALUES('CB541','2','Dili pagtulon-an,<br/>Unsa bang porma,<br/>Ang makapabuhi’g<br/>Makatransporma;<br/>S’ya nga Espiritu<br/>M’oy kinabuhi,<br/>Magpakinabuhi<br/>Nato’s plano’s Dios.<br/>',NULL,17502,2);
INSERT INTO stanza VALUES('CB541','3','Di pilosopiya,<br/>O bisan unsa,<br/>Ang makapasama<br/>Nato ni Cristo;<br/>Si Cristo ra gyud nga<br/>Nahimong kita,<br/>Ug sa pagkabanhaw<br/>Na-bahin ta N’ya.<br/>',NULL,17503,3);
INSERT INTO stanza VALUES('CB541','4','Di ang relihiyon<br/>Ni Cristianidad<br/>Makatuman’s tuyo’g<br/>Patigayon’s Dios;<br/>Si Cristo ra ingon<br/>Nga atong tanan<br/>Maoy makatagbo<br/>Sa Iyang tuyo.<br/>',NULL,17504,4);
INSERT INTO stanza VALUES('CB541','5','Tanang hiyas gihatag<br/>sa grasya N’ya,<br/>Kagamitan di<br/>kabaylo ni Cristo;<br/>Si Cristo ra gayud<br/>Ma-tanan nato!<br/>Sa tanan nga butang<br/>Dagko ug gagmay.<br/>',NULL,17505,5);
INSERT INTO stanza VALUES('CB542','1','O kadato’s Manlul’was ko,<br/>Labihang di matugkad;<br/>Tanang kahupnganan sa Dios<br/>Masinati na karon.<br/>',NULL,17506,1);
INSERT INTO stanza VALUES('CB542','chorus','O pagkadato ni Cristo,<br/>Alang gayud kanako!<br/>Di masukod, di matugkad,<br/>Apan realidad ko.<br/>',NULL,17507,2);
INSERT INTO stanza VALUES('CB542','2','O kadato’s Manlul’was ko,<br/>Lakip tanan: kahayag,<br/>Kinabuhi, ka’lam, gahum,<br/>Bahanding kalipay’s Dios;<br/>',NULL,17508,3);
INSERT INTO stanza VALUES('CB542','3','Katubsana’g kaluwasan,<br/>Gahum sa pagkabanhaw;<br/>Nagbalaan, naghimaya,<br/>Naglabaw matag takna!<br/>',NULL,17509,4);
INSERT INTO stanza VALUES('CB542','4','O kadato’s Manlul’was ko—<br/>Dios mismo akong tanan!<br/>Tanang Iya’g pagkamao<br/>Naglipay’s espiritu.<br/>',NULL,17510,5);
INSERT INTO stanza VALUES('CB542','5','O kadato’s Manlul’was ko!<br/>Kinsay nasayud’s tanan,<br/>Lapad, lalum, di masukod,<br/>Kalipay ko ug kusog.<br/>',NULL,17511,6);
INSERT INTO stanza VALUES('CB542','6','Kadato unta masayran,<br/>Hingpit masinatian;<br/>Aron ipaambit’s uban<br/>Ang kadagaya ni’ni.<br/>',NULL,17512,7);
INSERT INTO stanza VALUES('CB544','1','Gihigugma Ka, nasayud kong ako Ka,<br/>Alang Nimo b’yaan kong kalipayan;<br/>Ikawng maluloy-ong Tagtubos, Manlul’was ko,<br/>Kon higugmaon Ka, higugmaon karon.<br/>',NULL,17513,1);
INSERT INTO stanza VALUES('CB544','2','Mahal Ka, kay una kong gimahal Nimo,<br/>Gilukat ang pasaylo ko sa Calvario;<br/>Gimahal Ka nako kay gipurong Mong tunok;<br/>Kon higugmaon Ka, higugmaon karon.<br/>',NULL,17514,2);
INSERT INTO stanza VALUES('CB544','3','Mamatay ug mabuhi Ikaw mahalon,<br/>Ug daygon Ka hangtud may gininhawa pa,<br/>Kon moabot nang kamatayon ko, Ginoo,<br/>Kon higugmaon Ka, higugmaon karon.<br/>',NULL,17515,3);
INSERT INTO stanza VALUES('CB544','4','Sa kalipayng dayon sa eternidad,<br/>Simbahon Ka sa himayang masanagon;<br/>Pinurongan’s kahayag, awitan Ka nako;<br/>Kon higugmaon Ka, higugmaon karon.<br/>',NULL,17516,4);
INSERT INTO stanza VALUES('CB546','1','Gihigugma Ka, di sa gugma ko,<br/>Kay way ikahatag;<br/>Gihigugma Ka’s gugmang Imoha,<br/>Nabuhi ko ni’ni.<br/>Balewala ko, ug nagkalipay<br/>Nga nabasyo, nawa’ diha Nimo.<br/>',NULL,17517,1);
INSERT INTO stanza VALUES('CB546','2','Ikaw ray kin’hanglan’s mga anak,<br/>Wala nay lain pa;<br/>Niagay Nimong kabulahanan,<br/>Magpuyo mi Nimo.<br/>Buhing Tuboran, dagayang grasya,<br/>Tinubda’g sentro, puy-anan namo.<br/>',NULL,17518,2);
INSERT INTO stanza VALUES('CB548','1','Yutan-on kong sudlanan,<br/>Nga gisudlan ug Cristo;<br/>Ako maoy sudlanan,<br/>Siya mismo m’oy sulod.<br/>',NULL,17519,1);
INSERT INTO stanza VALUES('CB548','2','Gihimo ko’s dagway N’ya,<br/>Maangay nga sudlan N’ya;<br/>Busa ako giporma<br/>Sama gyud’s isulod N’ya.<br/>',NULL,17520,2);
INSERT INTO stanza VALUES('CB548','3','Nagpuyo S’ya’s esp’ritu,<br/>Gigamhan ko’s Esp’ritu;<br/>Nausa S’ya kanako,<br/>Siyay realidad ko.<br/>',NULL,17521,3);
INSERT INTO stanza VALUES('CB548','4','Naglihok sa sulod ko,<br/>Nakigsagol kanako,<br/>Nagbalaod’s lihok ko,<br/>Matag bahin nagsurop.<br/>',NULL,17522,4);
INSERT INTO stanza VALUES('CB548','5','I’dayag gikan’s sulod,<br/>Aron makita’s uban;<br/>Masihag unya ako,<br/>Makita S’ya kanako.<br/>',NULL,17523,5);
INSERT INTO stanza VALUES('CB548','6','Pagtransporma kin’hanglan,<br/>Labi pa nga madugmok;<br/>Aron lapokon usbon,<br/>Bahanding mahim’yaon.<br/>',NULL,17524,6);
INSERT INTO stanza VALUES('CB549','1','Sudlong tabil ug mogula’s kampo,<br/>Langit matilawan, b’yaang yuta;<br/>Kon natagbaw ko’s Labing Balaan,<br/>Moambit pa ba sa kakawangan?<br/>',NULL,17525,1);
INSERT INTO stanza VALUES('CB549','2','Sudlong tabil ug mogula’s kampo,<br/>Kon na’ng langit, yuta mopahawa;<br/>Kon esp’ritu danihon’s himaya,<br/>Maangkon ba ko’s kalipay’s yuta?<br/>',NULL,17526,2);
INSERT INTO stanza VALUES('CB549','3','Sudlong tabil ug mogula’s kampo,<br/>Gula’s kampo, papangunaha S’ya;<br/>Kon nadani’s trono’g purongpurong,<br/>Pasungan ug krus di makapugong.<br/>',NULL,17527,3);
INSERT INTO stanza VALUES('CB549','4','Sudlang tabil’s gahum’s pagkabanhaw,<br/>Guwa’s kampo—krus, kasubo antuson,<br/>Kon sa langit makita ’yang nawong,<br/>Mga tunob N’ya dinhi m’oy sundon.<br/>',NULL,17528,4);
INSERT INTO stanza VALUES('CB549','5','Sudlong tabil, magkaon’s katambok,<br/>Gula’s kampo, mag-antus’ kalisud;<br/>Bisag gisakit’s mga pagsulay,<br/>Sandurot nako’s langit naglipay.<br/>',NULL,17529,5);
INSERT INTO stanza VALUES('CB549','6','Sudlong tabil, pa’muslang Cristo ta,<br/>Gula’s kampo, S’ya isangkap’s tawo;<br/>Langit ako nga ikinabuhi,<br/>Mga kalag matagbaw’g magdayeg.<br/>',NULL,17530,6);
INSERT INTO stanza VALUES('CB549','7','Sudlong tabil hangtud ’ni mawala,<br/>Gula’s kampo, kampo mangawala;<br/>Hangtud mausang langit ug yuta,<br/>Dios-tawo mag-uba’g puyo, mag-usa.<br/>',NULL,17531,7);
INSERT INTO stanza VALUES('CB551','1','Gitoohan kong taho,<br/>Hallelujah’s Cordero!<br/>Nakalabang na’s sawang,<br/>O himaya sa Dios!<br/>Nia dapig ni Jesus,<br/>Gibalaan’s halaran,<br/>Namatay na sa sala,<br/>Hallelujah’s Cordero!<br/>',NULL,17532,1);
INSERT INTO stanza VALUES('CB551','chorus','Hallelujah! nakalabang<br/>Sa tabil nga nagisi,<br/>Ngadto’s kahimayaan;<br/>Hallelujah! nia ako<br/>Nabuhi sa atubangan sa Hari.<br/>',NULL,17533,2);
INSERT INTO stanza VALUES('CB551','2','Hari ko’g sacerdote,<br/>Hallelujah’s Cordero!<br/>Sa paghinlo sa dugo,<br/>O himaya sa Dios!<br/>Sa gahum’s Espiritu,<br/>Nabuhi matag adlaw’s<br/>Dapit Labing Balaan,<br/>Hallelujah’s Cordero!<br/>',NULL,17534,3);
INSERT INTO stanza VALUES('CB551','3','Nakalabang sa tabil,<br/>Hallelujah’s Cordero!<br/>Nga kanhi nagsalipod,<br/>O himaya sa Dios!<br/>Dugo m’oy nagpasulod<br/>Sa pagkabalaan’s Dios,<br/>Sala’g “ako” natapos,<br/>Hallelujah’s Cordero!<br/>',NULL,17535,4);
INSERT INTO stanza VALUES('CB551','4','Nia’s Labing Balaan,<br/>Hallelujah’s Cordero!<br/>Nakalabang sa tabil,<br/>O himaya sa Dios!<br/>Gibalaan na sa Dios<br/>Pinaagi sa dugo,<br/>Ginoo puy-anan ko,<br/>Hallelujah’s Cordero!<br/>',NULL,17536,5);
INSERT INTO stanza VALUES('CB552','1','Ay’g katinga’ng nabihag ko,<br/>Ni Cristo sa himaya;<br/>Di bitoong nagkidlap lang,<br/>Labaw pa’s Adlaw Siya.<br/>Tanan’s ubos mangiob man,<br/>Busa way makabihag,<br/>Mingawng dalan’s kasubo ra<br/>Nga kanhi gilakwan N’ya.<br/>',NULL,17537,1);
INSERT INTO stanza VALUES('CB552','2','Ubang tawo nagpanaw’s yuta<br/>Sa kalaay’g kaluya,<br/>Kahayag nakita ko na,<br/>Nga sa Adlaw labaw pa.<br/>Way panganud, pagkapalong,<br/>Nakita ko’s ’yang nawong,<br/>Tanang bahandi’s gugma N’ya,<br/>Tanang kadato’s grasya:<br/>',NULL,17538,2);
INSERT INTO stanza VALUES('CB552','3','Tanang katahum’s himaya,<br/>Ug kaayo’s ’yang gugma—<br/>Giunsa N’ya’g dani nako,<br/>Gimintinar gyud Niya;<br/>Di masiklapan ra Siya,<br/>Kondi’ sulod sa tabil,<br/>Magsud-ong’s nawong N’ya’s dayon,<br/>Maminaw’s Iyang pulong.<br/>',NULL,17539,3);
INSERT INTO stanza VALUES('CB552','4','Nakita kong nawong ni Jesus,<br/>Ayaw’g suginli’s uban;<br/>Nadungog ko Iyang tingog—<br/>Kalag ko ’yang gibusog.<br/>Sa kasanag sa himaya,<br/>Nawong Niya nakita,<br/>Kadtong himaya kong puy-an,<br/>Sa walay katapusan.<br/>',NULL,17540,4);
INSERT INTO stanza VALUES('CB553','1','Unsang kalipay’s kalag ko,<br/>Magtago’s presensya N’ya!<br/>Kabililhon’s nakat-onan,<br/>Sa Iya nga kiliran!<br/>Kabalaka ug pagsulay,<br/>Di makasamok nako;<br/>Kay kon manintal’s Satanas,<br/>Adto ko’s tagong dapit.<br/>(Sublia ang katapusang linya sa matag estansa)<br/>',NULL,17541,1);
INSERT INTO stanza VALUES('CB553','2','Kon luya’g giuhawng kalag,<br/>Sa landong sa pako N’ya<br/>Naay bugnawng kasilongan,<br/>Lunhawng tubod kaimnan;<br/>Mopahuway S’ya tapad nako,<br/>Samtang mag-ambitay mi;<br/>Di ko kasulti’s sulti N’ya<br/>Sa dihang magkita mi.<br/>',NULL,17542,2);
INSERT INTO stanza VALUES('CB553','3','Nasayud rang sultian S’ya’s<br/>Tanang kulba’g kaguol;<br/>Mapailubong maminaw,<br/>Nagdasig’s akong kalag;<br/>Abi mo’g di S’ya mobadlong?<br/>Di unta Abyang tinu’d,<br/>Kon dili ko N’ya sultian<br/>Nga nakita N’yang sad-an.<br/>',NULL,17543,3);
INSERT INTO stanza VALUES('CB553','4','Bu’t bang masayud’s katam-is,<br/>Sa sekreto’s Ginoo?<br/>Adto tago sa landong N’ya;<br/>Maimo kining balus;<br/>Mob’ya ngani ka’s kahilom<br/>Ning malipayong dapit,<br/>Sa Esp’ritu may dagway ka<br/>Sa Agalon sa naw’ng mo.<br/>',NULL,17544,4);
INSERT INTO stanza VALUES('CB554','1','Moduol sa presensya N’ya<br/>Sa di pang banaag’s kadlawon;<br/>Nawong N’ya makita, naghayag nako—<br/>Nagdan-ag Siya sa sulod.<br/>Namulong, nagpadayag S’ya nako<br/>Nga karon alang nako S’ya;<br/>Tam-is dayon ko nga moambit N’ya,<br/>Kagutom ko wala na.<br/>',NULL,17545,1);
INSERT INTO stanza VALUES('CB554','2','Espiritu S’yang namulong,<br/>Hangtud gitubag ko sa awit,<br/>Buhing tubod may grasya’g gahum N’ya,<br/>Sa kalag ko nagtubod.<br/>Namulong, nagpadayag S’ya nako<br/>Nga karon alang nako S’ya;<br/>Sa matag pangin’hanglan, imnon S’ya,<br/>Kauhaw ko wala na.<br/>',NULL,17546,2);
INSERT INTO stanza VALUES('CB554','3','Malomo N’yang giatiman<br/>Sa pagpuyo ko’s presensya N’ya;<br/>Kalag gisuropa’g gisangkapan’s<br/>Tanang pagkamao N’ya.<br/>Namulong, nagpadayag S’ya nako<br/>Nga karon alang nako S’ya;<br/>Niambit ko N’ya sa tanang bahin,<br/>Problema ko wala na.<br/>',NULL,17547,3);
INSERT INTO stanza VALUES('CB556','1','Ngalang humot daw gibubong dihog;<br/>Gugmang ma’yo pa’s bino, daniha!<br/>Kon sundon namong tunob sa panon,<br/>Makaapil’s ambitay’s gugma Mo.<br/>',NULL,17548,1);
INSERT INTO stanza VALUES('CB556','2','Hinigugma ko S’ya, gugma ko N’ya;<br/>Gidani N’ya, gipursigir ko S’ya;<br/>Mirra S’yang gitipigan ko’s dughan,<br/>†Copher’ng matahum, sul-oban ko N’ya.<br/>',NULL,17549,2);
INSERT INTO stanza VALUES('CB556','3','Naligo’s gugma, naghigda ko N’ya,<br/>Nagpa’mus’ kadato’g katam-is N’ya;<br/>Gugma bandila, pakitang mahal,<br/>Malomong naglipay’s kasingkasing.<br/>',NULL,17550,3);
INSERT INTO stanza VALUES('CB556','4','Minahal ako, ako Iyaha,<br/>Lirio ko ug Magbalantay ko S’ya,<br/>Landong ipaylas inigkakadlawon,<br/>Sama’s lagsaw S’ya’s bukid makita.<br/>',NULL,17551,4);
INSERT INTO stanza VALUES('CB556','5','Mirra sa pagkamatay uban N’ya,<br/>Incienso’s pag’banhaw, tuhopan N’ya;<br/>Huypi, hanging amihan, habagat,<br/>Himoang tanamang maglipay N’ya.<br/>',NULL,17552,5);
INSERT INTO stanza VALUES('CB556','6','Kaniya salampating way mansa,<br/>Daw putling lirio sa presensya N’ya,<br/>Iyaha ra, labing kalipay N’ya,<br/>Ako gyud S’yang Awit’s mga awit.<br/>',NULL,17553,6);
INSERT INTO stanza VALUES('CB556','7','Tahum daw Bulan, masama ko N’ya,<br/>Daw Adlawng motubo’s gidak-on N’ya;<br/>Tanan alang’s pagpahimuot N’ya,<br/>Tanan aron ikapadayag S’ya.<br/>',NULL,17554,7);
INSERT INTO stanza VALUES('CB556','8','Kinabuhi Ka, dagway ko Nimo;<br/>Gugmang nag-usa labing malig-on,<br/>Di gyud malaglag o mapulihan<br/>Hangtud madayag Ka’s kabukiran.<br/>',NULL,17555,8);
INSERT INTO stanza VALUES('CB559','1','Gitandog Ka sa pagtoo,<br/>Tinubdan Ka’s kaayo;<br/>Giangkon karon’s pagtoo,<br/>Sa paghinlo’s dugo Mo.<br/>',NULL,17556,1);
INSERT INTO stanza VALUES('CB559','chorus','Siga’s bag-ong kinabuhi,<br/>Siga’s Espiritu Mo;<br/>Naghinlo, nagputli nako,<br/>Himayaong Ngalan Mo!<br/>',NULL,17557,2);
INSERT INTO stanza VALUES('CB559','2','Gitandog Ka sa pagtoo,<br/>Giakong kadato Mo;<br/>Bukas ang tanan ko Nimo,<br/>Hatagi sa tanan Mo.<br/>',NULL,17558,3);
INSERT INTO stanza VALUES('CB559','3','Gihikap Ko ang setro Mo,<br/>O Hari’s mga hari;<br/>Nagdawat’s kahupnganan Mo,<br/>Sakay’s mga pako Mo.<br/>',NULL,17559,4);
INSERT INTO stanza VALUES('CB559','4','Grasya, kusog, ug kaalam,<br/>Gisangkapan Mo’s tanan;<br/>Pasigeha sa pagtandog,<br/>Pabilin’s kiliran Mo.<br/>',NULL,17560,5);
INSERT INTO stanza VALUES('CB561','1','Matud Mo Punoan Ka’s Parras,<br/>Ug ako Imong sanga,<br/>Apan wa ako masayud<br/>Nganong di ko mamunga.<br/>',NULL,17561,1);
INSERT INTO stanza VALUES('CB561','2','Nangandoyng mamunga ko’g daghan,<br/>Kinabuhi madayag;<br/>Trono Mo mapasidunggan,<br/>Pagbuot Mo madayag.<br/>',NULL,17562,2);
INSERT INTO stanza VALUES('CB561','3','Apan wa ako makasabut<br/>Pulong Mong “Magpabilin,“<br/>Naninguhang “magpabilin,“<br/>Nisamot mang nigawas.<br/>',NULL,17563,3);
INSERT INTO stanza VALUES('CB561','4','Wa mabating nagpabilin ko,<br/>Bisan nag-ampo’s hugot,<br/>Apan mora’g layo Ka man,<br/>Wa gihapon koy bunga.<br/>',NULL,17564,4);
INSERT INTO stanza VALUES('CB561','5','Punoan’s Parras Ka man gayud,<br/>Ako sanga na man sab!<br/>Pagdawat kong Manlul’was Ka,<br/>Matuod nang sanga ko.<br/>',NULL,17565,5);
INSERT INTO stanza VALUES('CB561','6','Naa na man ko Nimo karon,<br/>Di na sudlon pa nako;<br/>Kay nausa na ko Nimo,<br/>Usa’s unod, bukog Mo.<br/>',NULL,17566,6);
INSERT INTO stanza VALUES('CB561','7','Ang sekreto—“dili mosulod,“<br/>Kondi’ “nasulod na” ko!<br/>Di gyud mobiya—ampo ko,<br/>Di unsaon makasu’d.<br/>',NULL,17567,7);
INSERT INTO stanza VALUES('CB561','8','Nasulod na ko diha Nimo,<br/>Unsang dapita kini!<br/>Di na mag-ampo’g makigbisug,<br/>Dios mismo ang nagbuhat.<br/>',NULL,17568,8);
INSERT INTO stanza VALUES('CB561','9','Nia’s sulod—wa gyuy alamag,<br/>Nihangyo pang mosulod!<br/>Karon’s pagdayeg ug kalipay,<br/>Sa Pulong Mo nipuyo.<br/>',NULL,17569,9);
INSERT INTO stanza VALUES('CB561','10','Hingpit kong nipahulay Nimo,<br/>Nibuwag na’s kaugalingon;<br/>Kinabuhi Ka ug gahum,<br/>Ikawng tanan kanako.<br/>',NULL,17570,10);
INSERT INTO stanza VALUES('CB578','1','Luya, di ko makabuot,<br/>Halos wa na koy paglaum;<br/>Saligan lang Kang mobuhat,<br/>Magdala nako’s unahan.<br/>',NULL,17571,1);
INSERT INTO stanza VALUES('CB578','2','Pakyas, bisan naningkamot,<br/>Sige gihapong masayop;<br/>Pailub Mo m’oy saligan,<br/>Sa pulong Mo magpatuman.<br/>',NULL,17572,2);
INSERT INTO stanza VALUES('CB578','3','Magpagarbo na ngani ko,<br/>Halos katumbahon na gyud;<br/>Di mangahas sa paglihok,<br/>Kin’hanglan Ka, O Ginoo.<br/>',NULL,17573,3);
INSERT INTO stanza VALUES('CB578','4','Kusog Ka nako’g kalig-on,<br/>Nia, nangita’s nawong Mo;<br/>Bisan labing maluyahon,<br/>Grasya Mo ang akong kusog.<br/>',NULL,17574,4);
INSERT INTO stanza VALUES('CB582','1','Maglakaw uban N’ya<br/>Sa hayag’s Pulong N’ya,<br/>Unsang himaya sa dalan ta;<br/>Pagtuman’s buot N’ya,<br/>Magpuyo S’ya nato,<br/>Ug’s tanang mosalig-sugot N’ya.<br/>',NULL,17575,1);
INSERT INTO stanza VALUES('CB582','chorus','Salig, sugot,<br/>Way laing paagi<br/>Nga magmalipayon N’ya,<br/>Mosalig, mosugot.<br/>',NULL,17576,2);
INSERT INTO stanza VALUES('CB582','2','Way landong mogimaw,<br/>Mga panganud ba,<br/>Dali mang wad-on’s pahiyom N’ya;<br/>Way duda’g kahadlok,<br/>Panghupaw, paghilak,<br/>Magdugay kon mosalig-sugot.<br/>',NULL,17577,3);
INSERT INTO stanza VALUES('CB582','3','Way luwang gipas-an,<br/>Kasubong ambitan,<br/>Kahago ta baslan N’ya’g dako;<br/>Way kapildehan ta,<br/>Way kusmod o krus ba,<br/>Bulahan ta kon mosalig N’ya.<br/>',NULL,17578,4);
INSERT INTO stanza VALUES('CB582','4','Apan di masuta,<br/>Kalipay’s gugma N’ya,<br/>Kondi’ ihalad ang tanan ta;<br/>Kay ang paboran N’ya,<br/>Ug ang lipayon N’ya,<br/>Kadto rang mosalig-sugot N’ya.<br/>',NULL,17579,5);
INSERT INTO stanza VALUES('CB582','5','Tam-is mag-ambitay<br/>Unya’s tiilan N’ya,<br/>Mag-uba’g lakaw sa kilid N’ya;<br/>Buhatong sulti N’ya,<br/>Adtoong sugo N’ya,<br/>Di mahadlok, mosalig-sugot.<br/>',NULL,17580,6);
INSERT INTO stanza VALUES('CB583','1','Adto N’ya “gawas’ kampo,“<br/>Kaulaw N’ya antuson;<br/>Nag-antus Siya didto,<br/>Di magpahayahay ko.<br/>',NULL,17581,1);
INSERT INTO stanza VALUES('CB583','2','Adto N’ya “gawas’ kampo,“<br/>Bisan magpas-an sa krus;<br/>Sundon S’ya’s dalang pit-os,<br/>Bisan mapildehan ko.<br/>',NULL,17582,2);
INSERT INTO stanza VALUES('CB583','3','Adto N’ya “gawas’ kampo,“<br/>B’yaan hasta minahal;<br/>Ambitang pagtagad N’ya<br/>Sa pagbuot’s Amahan.<br/>',NULL,17583,3);
INSERT INTO stanza VALUES('CB583','4','Adto N’ya “gawas’ kampo,“<br/>Ma-kauban ko Niya;<br/>Rel’hiyon di apilan,<br/>O ang katilingban ba.<br/>',NULL,17584,4);
INSERT INTO stanza VALUES('CB583','5','Adto N’ya “gawas’ kampo,“<br/>Bisan mag-inusara;<br/>Pab’yai’s mga abyan,<br/>Kontento na ko Niya.<br/>',NULL,17585,5);
INSERT INTO stanza VALUES('CB583','6','Adto N’ya “gawas’ kampo,“<br/>Mag-uba’g lakaw Niya;<br/>Pahiyom N’ya makita,<br/>Makapah’way’s presensya N’ya.<br/>',NULL,17586,6);
INSERT INTO stanza VALUES('CB583','7','Adto N’ya “gawas’ kampo,“<br/>Hangtud makadlawon na;<br/>Makita dayon Siya,<br/>Uban N’ya’s gingharian.<br/>',NULL,17587,7);
INSERT INTO stanza VALUES('CB585','1','Giyahan N’ya! kabulahan,<br/>Pulong’s paglipayng langitnon;<br/>Bisan unsay buhaton ko,<br/>Giyahan ko N’ya gihapon.<br/>',NULL,17588,1);
INSERT INTO stanza VALUES('CB585','chorus','G’yahan ko N’ya! G’yahan ko N’ya!<br/>Giyahan ko sa kamot N’ya;<br/>Hugot gyung mosunod Niya,<br/>Kay g’yahan ko sa kamot N’ya.<br/>',NULL,17589,2);
INSERT INTO stanza VALUES('CB585','2','Sa panahong labing dulom,<br/>Sa Eden bang mabulakon,<br/>Sa linawng dagat, balud ba,<br/>G’yahan gihapon’s kamot N’ya.<br/>',NULL,17590,3);
INSERT INTO stanza VALUES('CB585','3','Mogunit ko sa kamot Mo,<br/>Wa gyuy mulo o pagmahay;<br/>Kontento sa dangatan ko,<br/>Kay Ikawng naggiya nako.<br/>',NULL,17591,4);
INSERT INTO stanza VALUES('CB585','4','Kon mahumang tahas’ yuta,<br/>Kon sa grasya Mo nidaug,<br/>Di mahadlok’s kamatayon,<br/>Kay nag-una Ka’s pagdaug.<br/>',NULL,17592,5);
INSERT INTO stanza VALUES('CB587','1','Matag tikang adlaw-adlaw<br/>Ubang Jesus maglakaw;<br/>Magsunod sa Iyang tunob,<br/>Sa tibuok gyung panaw.<br/>',NULL,17593,1);
INSERT INTO stanza VALUES('CB587','chorus','Lakang sa pagpanaw,<br/>Mouban ni Jesus,<br/>Sa tanan nga adlaw,<br/>Lakang sa pagpanaw.<br/>',NULL,17594,2);
INSERT INTO stanza VALUES('CB587','2','Hilwas maglakaw uban N’ya,<br/>Salig gyud sa bukton N’ya,<br/>Sundon Siya bisan asa,<br/>Way makadaut nato.<br/>',NULL,17595,3);
INSERT INTO stanza VALUES('CB587','3','Matag tikang ubang Jesus,<br/>Tagsatagsao’g salig,<br/>Way mga pakong iglupad,<br/>Tiil lang nga ikatkat.<br/>',NULL,17596,4);
INSERT INTO stanza VALUES('CB587','4','Uban gyud N’ya’s tibu’k panaw,<br/>Sa hayag ba o dulom,<br/>Dad-on ko’s dugoong tunob,<br/>Sa tanaman, lubnganan.<br/>',NULL,17597,5);
INSERT INTO stanza VALUES('CB587','5','Kadyut maglakaw uban N’ya,<br/>Dili kini magdugay,<br/>Kay gabii ma-buntag na,<br/>Kasubo ma-awit na.<br/>',NULL,17598,6);
INSERT INTO stanza VALUES('CB587','6','Tanang naglakaw uban N’ya,<br/>Magsul-ob ug maputi,<br/>’Subo ta himo’ng kalipay,<br/>Ngiob himo’ng kahayag.<br/>',NULL,17599,7);
INSERT INTO stanza VALUES('CB587','7','Jesus, labi pang pasunda,<br/>Adlaw-adlaw’s tikang Mo;<br/>Magsunod’s mga tunob Mo,<br/>Uban Ka’s tibu’k panaw.<br/>',NULL,17600,8);
INSERT INTO stanza VALUES('CB589','1','Ang Dios may bahandi’s langit,<br/>Kadato di matukib;<br/>Kalipayng way katapusan,<br/>Cristong Anak gimahal.<br/>Sa yuta sab may bahandi,<br/>Dios ray nasayud’s bili—<br/>Di matugkad N’yang kalipay,<br/>Cristong gibugna nato.<br/>',NULL,17601,1);
INSERT INTO stanza VALUES('CB589','2','Dios nikunsad’s Espiritu,<br/>Pi’ling sudlanan pun-on<br/>Sa bahanding way pagtapos,<br/>Di mahurot—makabsan.<br/>Mangunay gyud S’ya’s pagpuno<br/>Gikan’s kahimayaan,<br/>Nagpahilom’s kasingkasing<br/>Sa kadato’s gugma N’ya.<br/>',NULL,17602,2);
INSERT INTO stanza VALUES('CB589','3','Bisag naugtas, gitintal,<br/>Tinawag ka’s himaya;<br/>Pakit-a S’yang nabasyo ka,<br/>Buhing sanga’s Punoan!<br/>Mga sudlanang tinamay,<br/>Kabus, ubos, mahuyang,<br/>Daladalang mahal sa Dios,<br/>Himaya’s nawong ni Cristo.<br/>',NULL,17603,3);
INSERT INTO stanza VALUES('CB589','4','Kanang mabasyo’g maubos,<br/>Wa masayri’g maila,<br/>Mas balaan ngadto sa Dios,<br/>Napuno ra gyug Cristo!<br/>Way sa yuta’g kaugalingon,<br/>Makatabon’s himaya,<br/>Mosugilon hinoon N’ya,<br/>Gibasyo kay pun-on N’ya.<br/>',NULL,17604,4);
INSERT INTO stanza VALUES('CB591','1','Di na ako, ang ituboy si Cristo,<br/>Di na ako madayag, madungog;<br/>Si Cristo ra’s matag tan-aw ug lihok,<br/>Sa matag hunahuna’g pamulong.<br/>',NULL,17605,1);
INSERT INTO stanza VALUES('CB591','chorus','O Ginoo, luwasa ako<br/>Ning kaugalingon,<br/>Hangtud nga dili na ako,<br/>Mabuhi si Cristo.<br/>',NULL,17606,2);
INSERT INTO stanza VALUES('CB591','2','Di na ako, ang maghupay’s kasubo,<br/>Di na ako, ang magpahid’s luha;<br/>Cristo ray makahaw-as sa kabug-at,<br/>Cristo ray magkalma sa kahadlok.<br/>',NULL,17607,3);
INSERT INTO stanza VALUES('CB591','3','Cristo gani walay pagtabitabi,<br/>Cristo gani di magkapuliki,<br/>Di magsapayan sa kaugalingon,<br/>Si Cristo ra, way makitang ako.<br/>',NULL,17608,4);
INSERT INTO stanza VALUES('CB591','4','Cristo ray magsangkap’s panginahanglan,<br/>Cristo ray kusog ug kahimsog ko;<br/>Cristo ra’s espiritu, kalag, lawas,<br/>Ikinabuhi Ka na gyud nako.<br/>',NULL,17609,5);
INSERT INTO stanza VALUES('CB591','5','S’ya ra unyay magpuno’s panan-awon,<br/>Makita nang labaw nga himaya;<br/>Si Cristo ray magtuman’s pangandoy ko,<br/>S’ya ray mahimong tanan sa tanan.<br/>',NULL,17610,6);
INSERT INTO stanza VALUES('CB593','1','Kang Adam lunlon sala’g kamatayon,<br/>Kang Cristo kinabuhi’g pag’matarung;<br/>Diha sa unod, Adam ipadayag,<br/>Kon sa espiritu, Cristo madayag.<br/>',NULL,17611,1);
INSERT INTO stanza VALUES('CB593','2','Kang Adam, bisan di magpakasala<br/>Makasasala nang gihukman’s silot;<br/>Kang Cristo di na mobuhat pa’g ’tarung,<br/>Matarung na tungod kay gimatarung.<br/>',NULL,17612,2);
INSERT INTO stanza VALUES('CB593','3','Diha’s unod di na panlimbasugan,<br/>Ang mapadayag kinaiyang Adam;<br/>Mabuhi’g maghari ko sama Niya,<br/>Mabuhi sama Niya ug maghari.<br/>',NULL,17613,3);
INSERT INTO stanza VALUES('CB593','4','Namatay uban N’ya gawas nang Adam,<br/>Nabuhi N’ya sa bag-ong kinabuhi!<br/>Di magtagad’s unod, Adam mapugngan,<br/>Espiritu’y tagdon, kinabuhi man.<br/>',NULL,17614,4);
INSERT INTO stanza VALUES('CB593','5','Espiritu’y tagdon, pagl’was kini’s Dios,<br/>Espiritu’y tagdon, Cristo i’dayag;<br/>Espiritu’y tagdon, makadaug ta,<br/>Espiritu’y tagdon, makalumba ta.<br/>',NULL,17615,5);
INSERT INTO stanza VALUES('CB593','6','Espiritu’y tagdon, makaila’s krus,<br/>Gahum’s pagkabanhaw moagay nato;<br/>Mabuhi’s Cristo pinaagi nato,<br/>Kinabuhi N’ya motubo’g mahamtong.<br/>',NULL,17616,6);
INSERT INTO stanza VALUES('CB593','7','Cristo kinabuhi’g tanan kanako,<br/>Malangkubon’s-tanan nga nagbulahan;<br/>Mabuhi’s espiritu, kabalaan,<br/>Tulo-usang Dios mobuhat’s sulod ko.<br/>',NULL,17617,7);
INSERT INTO stanza VALUES('CB594','1','Ikawng kinabuhi,<br/>Ug kalinaw ko;<br/>Pag-ambit’s esp’ritu,<br/>Nausa Nimo.<br/>',NULL,17618,1);
INSERT INTO stanza VALUES('CB594','chorus','Sunod’s Espiritu<br/>Mabuhi’s Ginoo,<br/>Kinabuhi’y sangkap<br/>Ug kalinaw N’ya.<br/>',NULL,17619,2);
INSERT INTO stanza VALUES('CB594','2','Iya na’s Ginoo,<br/>Di gyud magapos,<br/>Buhi N’yang balaod<br/>Nag’gawas nako.<br/>',NULL,17620,3);
INSERT INTO stanza VALUES('CB594','3','Di magtagad’s unod,<br/>Sa esp’ritu ra;<br/>Di sundong pagbuot,<br/>Ang Esp’ritu ra.<br/>',NULL,17621,4);
INSERT INTO stanza VALUES('CB594','4','Gamhan ko ni Cristo,<br/>Maesp’rituhanon!<br/>Buhion ang lawas<br/>Sa Iyang gahum.<br/>',NULL,17622,5);
INSERT INTO stanza VALUES('CB594','5','Esp’ritu’g esp’ritu<br/>Usang magsaksi;<br/>Anak kong manunod<br/>Uban ni Cristo.<br/>',NULL,17623,6);
INSERT INTO stanza VALUES('CB595','1','Tilawi nganing Ginoo,<br/>Naa gayuy pakapin;<br/>Kopang pun-on N’ya mag-awas,<br/>Kadato ’yang ihatag;<br/>Way dinawo, way dinaginot,<br/>Gikan’s ’yang tipiganan;<br/>Dinasok, tinantan gayud<br/>Ug mag-awas-awas pa,<br/>Dinasok, tinantan gayud<br/>Ug mag-awas-awas pa.<br/>',NULL,17624,1);
INSERT INTO stanza VALUES('CB595','2','Pakapinan gyud’s Amahan<br/>Kon magpasalamat ta<br/>Sa pagdawat’s gipahat Niya<br/>Ug magdayeg’s giplano N’ya.<br/>Sangkap’s tanang pangin’hanglan,<br/>May kaping katagbawan,<br/>Kon natilawan na’s Jesus<br/>Tinguha ta matagbaw,<br/>Kon natilawan na’s Jesus<br/>Tinguha ta matagbaw.<br/>',NULL,17625,2);
INSERT INTO stanza VALUES('CB595','3','Na’ gyuy pakapin’s pag-ambit<br/>Sa tanan Niyang gugma;<br/>Na’y giladmong wa makalot,<br/>Kahabog, wa makatkat.<br/>Di malitok’s mga ngabil<br/>Tanan Niyang kalomo.<br/>Makadayeg la’g matingala,<br/>Ngalan N’ya daygon’s dayon,<br/>Makadayeg la’g matingala,<br/>Ngalan N’ya daygon’s dayon.<br/>',NULL,17626,3);
INSERT INTO stanza VALUES('CB600','1','Dios, akong Pahat, ug Gugma,<br/>Ang tanan ko’s dayon,<br/>Way lain kondi’ Ikaw ra<br/>Sa langit ba’g yuta,<br/>Sa langit ba’g yuta.<br/>',NULL,17627,1);
INSERT INTO stanza VALUES('CB600','2','Tanang butang kakawangan,<br/>Sa langit ug yuta!<br/>Way butang nga kalipayan,<br/>Nga sama’s akong Dios,<br/>Nga sama’s akong Dios.<br/>',NULL,17628,2);
INSERT INTO stanza VALUES('CB600','3','Bahandi’g kahigalaan,<br/>Kahimsog, puy-anan;<br/>Salamat sa hinatag Mo,<br/>Apan di sila Dios,<br/>Apan di sila Dios.<br/>',NULL,17629,3);
INSERT INTO stanza VALUES('CB600','4','Bulawan itandi Nimo<br/>Kawang nga dulaan!<br/>Kahilwas, kahimsog, abyan,<br/>Unsa sila nako?<br/>Unsa sila nako?<br/>',NULL,17630,4);
INSERT INTO stanza VALUES('CB600','5','Bisan tibu’k yuta ako,<br/>Kabitoonan man,<br/>Kon wa Ka ug ang grasya Mo,<br/>Makaluluoy lang,<br/>Makaluluoy lang.<br/>',NULL,17631,5);
INSERT INTO stanza VALUES('CB600','6','Daw dagat pahakpa sila<br/>Sa tibu’k lapyahan,<br/>Duawa lang sa grasya Mo,<br/>Wa nay tinguhaon,<br/>Wa nay tinguhaon.<br/>',NULL,17632,6);
INSERT INTO stanza VALUES('CB602','1','Kahimaya! Kabalaan!<br/>Dios kinabuhing dayon!<br/>Putli, hayag, maluloy-on,<br/>Puno, way kutob, kusgan!<br/>Kadato N’ya’g kinaiya<br/>Na’ ning kinabuhia.<br/>',NULL,17633,1);
INSERT INTO stanza VALUES('CB602','2','Ma’gugmaon! Maluloy-on!<br/>Dios mismo kinabuhi!<br/>Gigam-an ta’g espiritu<br/>Pagtuman’s Iyang plano.<br/>Tinguha ug pangandoy N’ya<br/>Nga sa tawo madawat S’ya.<br/>',NULL,17634,2);
INSERT INTO stanza VALUES('CB602','3','Kadagaya’s gugma’g grasya!<br/>Niagayng Dios kanato!<br/>Nagpakita’s Kaugalingon<br/>Sa unod ug Esp’ritu,<br/>Aron ang kinabuhi N’ya<br/>Masayran sa mga tawo.<br/>',NULL,17635,3);
INSERT INTO stanza VALUES('CB602','4','Pagkasuod! Pagkaduol!<br/>Dios na-kinabuhi ta!<br/>Dios sa unod nagpakatawo,<br/>Aron makita sa tawo.<br/>Namatay, nabanhaw, sulod<br/>Na’s tawo, kinabuhi n’ya.<br/>',NULL,17636,4);
INSERT INTO stanza VALUES('CB602','5','Katingad-an! Espiritu!<br/>Dios na-kinabuhi’s tawo!<br/>Laing dagway sab S’ya sa Dios,<br/>Nailang Espiritu;<br/>Nagtuto, nagdasig sa tawo,<br/>Nagbalay’s sulod nila.<br/>',NULL,17637,5);
INSERT INTO stanza VALUES('CB602','6','Kahimaya! Kabililhon!<br/>Maila ang Trinidad!<br/>Amahan nianhi’s Anak,<br/>Anak na-Espiritu.<br/>Tawo masudlan’s Espiritu,<br/>Dios ma-kinabuhi n’ya.<br/>',NULL,17638,6);
INSERT INTO stanza VALUES('CB602','7','Misteryoso, tinuod gyud!<br/>Dios kanako nisulod!<br/>Nianhi, nausa nako,<br/>Aron makinabuhi.<br/>Hallelujah! Hallelujah!<br/>Di mohunong’s pagdayeg!<br/>',NULL,17639,7);
INSERT INTO stanza VALUES('CB608','1','Tulo’y persona, usa’g pagkamao<br/>Ang Amahan, Anak, ug Esp’ritu.<br/>Pinaagi’s Esp’ritu diha’s Anak<br/>Dios nisulod sa pagkatawo ta!<br/>Dios Trinidad, karon atong tanan!<br/>Katingad-an! O himaya!<br/>Diosnong Gasa di mahurot nato!<br/>Pagkalabaw! Pagkaayo!<br/>2 Pagkadato sa Amahang tinubdan<br/>Sa tanang atong gipahimuslan!<br/>Kabulahan, naato kining tanan,<br/>Magamit ta hangtud’s kahangturan.<br/>',NULL,17640,1);
INSERT INTO stanza VALUES('CB608','3','Ang Anak pagpadayag sa Amahan,<br/>Diha’s unod nipuyo’s katawhan!<br/>Buhat’s katubsanan pagkagamhanan,<br/>Nausa sa Dios kita nga tanan!<br/>',NULL,17641,2);
INSERT INTO stanza VALUES('CB608','4','Espiritu m’oy pagsulod sa Anak,<br/>Kinabuhi kanato isangkap.<br/>Espiritu ta ug Espiritu N’ya,<br/>Katingad-ang nasagol, nausa!<br/>',NULL,17642,3);
INSERT INTO stanza VALUES('CB608','5','Matuod gyud Dios karon Espiritu,<br/>Matandog, masinati na nato;<br/>Na-usa ta ka espiritu sa Dios,<br/>Sama N’ya’s kinabuhi sa bug-os!<br/>',NULL,17643,4);
INSERT INTO stanza VALUES('CB609','1','Daygon Ka sa misteryo Mo,<br/>Makakontak gyud ko Nimo;<br/>Kanhi di gyud Ka maduol,<br/>Karon Espiritu nang duol.<br/>',NULL,17644,1);
INSERT INTO stanza VALUES('CB609','2','Amahan, Anak, Espiritu,<br/>Dios, dayong kinabuhi ko;<br/>Kanako sangkap Kang hingpit,<br/>Kinaiya Mo maambit.<br/>',NULL,17645,2);
INSERT INTO stanza VALUES('CB609','3','Dios mao ang Espiritu,<br/>Daw hangin niabot nako;<br/>Ni’ni masinatian ko<br/>Katingad-an N’yang misteryo.<br/>',NULL,17646,3);
INSERT INTO stanza VALUES('CB609','4','Pagkamao’g na’s Amahan<br/>Na’ng tanan’s Anak nga mahal,<br/>Tanang kadato sa Anak<br/>Naa karon’s Espiritu.<br/>',NULL,17647,4);
INSERT INTO stanza VALUES('CB609','5','Esp’ritu nikunsad nako,<br/>Nisulod’s espiritu ko;<br/>Nga S’ya, Amahang na’s Anak,<br/>Bulahang pahat ko’s sulod.<br/>',NULL,17648,5);
INSERT INTO stanza VALUES('CB609','6','Amahan maoy tinubdan,<br/>Anak m’oy pagpadayag N’ya;<br/>Espiritu inagay N’ya,<br/>Realidad sa sulod ko.<br/>',NULL,17649,6);
INSERT INTO stanza VALUES('CB609','7','Amahan nianhi’s Anak<br/>Aron Dios mapadayag’s tawo;<br/>Anak Espiritu nisu’d,<br/>Mailhan nang Dios sa sulod.<br/>',NULL,17650,7);
INSERT INTO stanza VALUES('CB609','8','Anak gilaraw’s Amahan<br/>Nga mag-una’s tanang butang,<br/>Ulo’s Anak ang Amahan<br/>Ipasakop Kan’ya’ng tanan.<br/>',NULL,17651,8);
INSERT INTO stanza VALUES('CB609','9','Esp’ritu nagtinguha gyud<br/>Nga ang Anak mahimaya,<br/>S’ya gipadayag N’ya nako,<br/>Aron S’ya pamatud-an gyud.<br/>',NULL,17652,9);
INSERT INTO stanza VALUES('CB609','10','Esp’ritu kahingpitan Mo,<br/>Magdawat’s pagsimba’s sulod;<br/>Kon kadato Mo pa’muslan<br/>Kontakon ko S’ya’s espiritu.<br/>',NULL,17653,10);
INSERT INTO stanza VALUES('CB609','11','Kon simbahon Ka’s esp’ritu,<br/>Mabuhi’g mag-ampo ni’ni,<br/>Espiritu matandog ko<br/>Mapahimuslan Ka gayud.<br/>',NULL,17654,11);
INSERT INTO stanza VALUES('CB610','1','Esp’ritu pagpalatay’s Dios,<br/>Kan’ya Dios mosulod nato;<br/>Kaniya Dios dihang Cristo<br/>Masinati gayud nato.<br/>',NULL,17655,1);
INSERT INTO stanza VALUES('CB610','2','Dios Amahan m’oy tinubdan,<br/>Dios Anak nagpadayag N’ya;<br/>Dios Esp’ritu nisu’d nato,<br/>Aron Dios mabatonan ta.<br/>',NULL,17656,2);
INSERT INTO stanza VALUES('CB610','3','Amahang natago’s kahayag<br/>Ang Anak m’oy nagpadayag;<br/>Gipalatay’s Espiritu,<br/>Aron maila S’ya’s sulod.<br/>',NULL,17657,3);
INSERT INTO stanza VALUES('CB610','4','Anak naa sa Amahan,<br/>Karon S’ya ang Espiritu;<br/>Esp’ritu, Anak, Amahan,<br/>Nausa nato sa sulod.<br/>',NULL,17658,4);
INSERT INTO stanza VALUES('CB610','5','Dios Amahan diha’s Anak<br/>Gipakalawas, gipadayag,<br/>Dios Esp’ritu realidad’s<br/>Anak, mapanag-iya ta.<br/>',NULL,17659,5);
INSERT INTO stanza VALUES('CB610','6','Gugma’s Amahan maila<br/>Nga grasya diha sa Anak,<br/>Sa pakig-ambit’s Esp’ritu<br/>Ang Dios pahat nga maato.<br/>',NULL,17660,6);
INSERT INTO stanza VALUES('CB611','1','Espiritu kinaiya,<br/>Balaang pagkamao N’ya;<br/>Makontak, mapa’muslan S’ya<br/>Sa atong espiritu ra.<br/>',NULL,17661,1);
INSERT INTO stanza VALUES('CB611','2','Espiritu’s kahiladman,<br/>Labing tinuod bahin’s tawo;<br/>Kon kontakong Dios nga buhi,<br/>Espiritu gyuy gamiton.<br/>',NULL,17662,2);
INSERT INTO stanza VALUES('CB611','3','Dios buot magsimba ta N’ya<br/>Diha lang sa espiritu;<br/>Espiritu N’ya mosu’d’s tawo,<br/>Mausang Esp’ritu N’ya’s tawo.<br/>',NULL,17663,3);
INSERT INTO stanza VALUES('CB611','4','Magtawganayng espiritu,<br/>Masagol, mausa sila;<br/>Esp’ritu ta puy-anan N’ya,<br/>Ma-kinabuhi nato S’ya.<br/>',NULL,17664,4);
INSERT INTO stanza VALUES('CB611','5','Mabuhi’s kahupnganan’s Dios<br/>Kon mokontak’s Esp’ritu N’ya;<br/>Sa espiritu lang Siya<br/>Masimba’g maalagad ta.<br/>',NULL,17665,5);
INSERT INTO stanza VALUES('CB611','6','Sa pangalagad, ambitay,<br/>Tawo dad-on gyud’s espiritu;<br/>Pangalagad ma-pag-ampo,<br/>Magsanongayng espiritu.<br/>',NULL,17666,6);
INSERT INTO stanza VALUES('CB611','7','Mag-ampo-silbe’s esp’ritu,<br/>Mokontak’s kinabuhi’s Dios;<br/>Magtubo’g-tukod’s esp’ritu,<br/>Bug-os makahayag’s Cristo.<br/>',NULL,17667,7);
INSERT INTO stanza VALUES('CB611','8','Moliso gyud’s espiritu,<br/>Makat-on’s pagkontak Nimo;<br/>Uba’g agay esp’ritu ta,<br/>Moawas hangtud sa dayon.<br/>',NULL,17668,8);
INSERT INTO stanza VALUES('CB612','1','Tuyo sa Dios Iyang tanan<br/>Himo’ng sangkap ko;<br/>Mausa gyud ko Niya sa<br/>Espiritu.<br/>',NULL,17669,1);
INSERT INTO stanza VALUES('CB612','chorus','Pagkamao’g kadato’s Dios<br/>Na’s Espiritu,<br/>Gamiton gyung espiritu<br/>Pag-ila N’ya.<br/>',NULL,17670,2);
INSERT INTO stanza VALUES('CB612','2','Kadato’s ’yang kinaiya<br/>Gihatag nako;<br/>Tandogon gyud S’ya’s esp’ritu,<br/>Makita ni.<br/>',NULL,17671,3);
INSERT INTO stanza VALUES('CB612','3','Tandogon S’ya’s espiritu,<br/>Sabton’s pangisip;<br/>Ang di mogamit’s esp’ritu<br/>Kulangan gyud.<br/>',NULL,17672,4);
INSERT INTO stanza VALUES('CB612','4','Maminaw ngani’s mensahe,<br/>I-ampo gayud,<br/>Aron mahilis ang pulong<br/>Sa sulod ko.<br/>',NULL,17673,5);
INSERT INTO stanza VALUES('CB612','5','Kon magtuon’s Iyang Pulong<br/>Siya tandogon,<br/>Kon hunahuna gamiton,<br/>Patayng Pulong.<br/>',NULL,17674,6);
INSERT INTO stanza VALUES('CB612','6','Kahimaya, S’ya naghayag<br/>Sa Espiritu!<br/>Kon gamitong espiritu,<br/>Tanan ako.<br/>',NULL,17675,7);
INSERT INTO stanza VALUES('CB614','1','Duol pa gyud Nimo,<br/>O Ginoo,<br/>Bisan kini ang krus<br/>Pas-anon ko,<br/>Mag-awit gihapon,<br/>Duol pa gyud Nimo,<br/>Duol pa gyud Nimo,<br/>Duol Nimo.<br/>',NULL,17676,1);
INSERT INTO stanza VALUES('CB614','2','Gisalopan’s Adlawng<br/>Dumuloong,<br/>Giabtan’s kangitngit,<br/>Unlan bato;<br/>Bisan sa damgo ko,<br/>Duol pa gyud Nimo,<br/>Duol pa gyud Nimo,<br/>Duol Nimo.<br/>',NULL,17677,2);
INSERT INTO stanza VALUES('CB614','3','Nakit-an kong langit<br/>Nga nabuksan,<br/>Tanang gipadala,<br/>Kaluoy Mo;<br/>Gidapit ko’s Anghel,<br/>Duol pa gyud Nimo,<br/>Duol pa gyud Nimo,<br/>Duol Nimo.<br/>',NULL,17678,3);
INSERT INTO stanza VALUES('CB614','4','Ug sa pagmata ko,<br/>Magdayeg Nimo,<br/>Bethel patindogon<br/>Sa kasubo;<br/>Busa sa kasubo<br/>Duol pa gyud Nimo,<br/>Duol pa gyud Nimo,<br/>Duol Nimo.<br/>',NULL,17679,4);
INSERT INTO stanza VALUES('CB620','1','Krus lig-ong nagbarug<br/>Hallelujah! hallelujah!<br/>Tanang kaaway suklan,<br/>Hallelujah! hallelujah!<br/>Hangin’s Hades naghuros,<br/>Kalibutan nagdumot,<br/>Apan di gyud matarug,<br/>Hallelujah alang’s krus!<br/>',NULL,17680,1);
INSERT INTO stanza VALUES('CB620','chorus','Hallelujah, hallelujah,<br/>Hallelujah alang gyud sa krus,<br/>Hallelujah, hallelujah,<br/>Wa gayuy kapildehan.<br/>',NULL,17681,2);
INSERT INTO stanza VALUES('CB620','2','Kini ang krus kanhi,<br/>Hallelujah! hallelujah!<br/>Nidaug, isulti,<br/>Hallelujah! hallelujah!<br/>Grasya sa Dios nisidlak,<br/>Pinaagi sa Anak,<br/>Nga maoy nagtubos,<br/>Hallelujah alang’s krus!<br/>',NULL,17682,3);
INSERT INTO stanza VALUES('CB620','3','Dinhi utang nabayran,<br/>Hallelujah! hallelujah!<br/>Sala ta ’yang gipas-an,<br/>Hallelujah! hallelujah!<br/>Libot sa krus mag-awit<br/>Ni Cristo nga halad ta,<br/>S’yang buhing Hari ta<br/>Hallelujah alang’s krus!<br/>',NULL,17683,4);
INSERT INTO stanza VALUES('CB622','1','Sakit ra bay antuson kon krus pas-anon?<br/>Dili, sa krus seguro gyud ta nga patyon!<br/>Mao man kana ang kahulogan sa krus,<br/>Kaugalingon ta ilansang gyud sa krus.<br/>',NULL,17684,1);
INSERT INTO stanza VALUES('CB622','2','Pagluwas sa Dios, patyon ang tawo didto’s krus,<br/>Mabangis tuod, apan magawas gayud.<br/>Di S’ya makinabuhi kon maglikay’s krus,<br/>Madayag lang S’ya kon kita mamatay gyud.<br/>',NULL,17685,2);
INSERT INTO stanza VALUES('CB622','3','Tumong sa krus, matumang kabubot-on’s Dios,<br/>Kaatbang ni’ni, kaugalingon sa tawo.<br/>Kon kaugalingon wad-on, kalag mo patyon,<br/>Pagbuot N’ya modaug, plano molampos.<br/>',NULL,17686,3);
INSERT INTO stanza VALUES('CB626','1','Kon di pug-on ang oliva<br/>Way lanang moguwa;<br/>Kon di mag-agi’s pigsanan,<br/>Parras di gyud ma-bino;<br/>Nardo kon dili dugmokon,<br/>Di mangalimyon.<br/>Mahadlok ba kong mag-antus<br/>Sa gipili’s gugma Mo.<br/>',NULL,17687,1);
INSERT INTO stanza VALUES('CB626','chorus','Matag hampak Mo<br/>May kaayohan;<br/>Mga butang nga gikuha<br/>Kaugalingon Mo’y puli.<br/>',NULL,17688,2);
INSERT INTO stanza VALUES('CB626','2','Kabliton bang kasingkasing,<br/>’Tugtog’s awit Mo?<br/>Tungod ba kay patahumon,<br/>Kin’hanglan Mong sakiton?<br/>Di mahadlok’s kawalad-on,<br/>Kon danihon Mo;<br/>Bug-os kong motahan Nimo,<br/>Makita lang gugma Mo.<br/>',NULL,17689,3);
INSERT INTO stanza VALUES('CB626','3','Naulaw kay gihikaw ko<br/>Ang kaugalingon;<br/>Gisapsap tuod’s gugma Mo,<br/>Apan napugos lang ko.<br/>Segun’s gusto Mo, Ginoo,<br/>Buhat kanako;<br/>Ayaw tagdang pagbati ko,<br/>Buhat lang sa gusto Mo.<br/>',NULL,17690,4);
INSERT INTO stanza VALUES('CB626','4','Kon lahi tag hunahuna,<br/>Imo’y tumana,<br/>Kon kalipay Mo, kagu’l ko,<br/>Mosugot gihapon ko.<br/>Tinguha kong malipay Ka,<br/>Bisag mag-antus;<br/>Malipay’g mahimaya Ka,<br/>Agwantahon ko ang krus.<br/>',NULL,17691,5);
INSERT INTO stanza VALUES('CB626','5','Magdayeg Nimo bisan luha<br/>Mosagol’s awit.<br/>Nagkatam-is man Ka, busa<br/>Daygon ko’s tibu’k adlaw.<br/>Labi pa Kang nibililhon<br/>Labaw sa tanan;<br/>Motubo Ka, mokunhod ko,<br/>Kini ray pag-ampo ko.<br/>',NULL,17692,6);
INSERT INTO stanza VALUES('CB628','1','Agi’s Bethlehem nanglakaw,<br/>Dios—tumong’s kasingkasing;<br/>Daw puyang nagtuon Niya,<br/>Samtang aping luhaan;<br/>Pasungan ubos kaayo,<br/>Di kahimut-an sa tawo,<br/>Ang pagsunod kinahanglan,<br/>Kon buot nga gantihan.<br/>',NULL,17693,1);
INSERT INTO stanza VALUES('CB628','2','Didto’s Nasaret ang dalan<br/>Bakilid ug sigpit man;<br/>Kahago way nakasabut<br/>Apan tudloan ta’s Dios.<br/>Nga sulugoon di labaw’s<br/>Agalong daghang tuig<br/>Nilikay’s himaya’s yuta,<br/>Sunda S’ya, bisag pait.<br/>',NULL,17694,2);
INSERT INTO stanza VALUES('CB628','3','Nakita ta S’ya’s Galilea,<br/>Gibato’g gitunglo S’ya;<br/>Nasayop ba kaha Siya?<br/>Nganong daghag kasakit?<br/>Wa! Bisan dalan gansangon,<br/>Linaw S’yang nagpadayon,<br/>Sama kang Jesus magpanaw,<br/>Sa tuyo di papugong.<br/>',NULL,17695,3);
INSERT INTO stanza VALUES('CB628','4','Agi sab’s dakong kasakit<br/>Ubos sa kakahoyan,<br/>Gilibotan’s panon’s yawa,<br/>Kalisud hilabihan!<br/>Apan wa ta maluya, kay<br/>Gisilbehan sa anghel,<br/>Niingon, “Tutok’s himaya,<br/>Usang adlaw rang away!”<br/>',NULL,17696,4);
INSERT INTO stanza VALUES('CB628','5','Krus niabot, kay ang tanan<br/>Moagi gyud’s Calvario;<br/>Dinhi gibuksan tang tabil,<br/>S’ya ray magpakita’s da’n.<br/>“Kon mag-antus ta uban N’ya,“<br/>Paminaw, sa kadyut lang,<br/>Makalimtan mo ang tanan<br/>Sa himaya’s pah’yom N’ya!<br/>',NULL,17697,5);
INSERT INTO stanza VALUES('CB628','6','Didto’s lubong nag-alirong,<br/>Nagbakho’s way paglaum;<br/>(Higala, ikaw dili ba<br/>Giisip nga patay na?)<br/>Nibangon, buhi uban N’ya,<br/>Labaw’s gibisugan’s tawo,<br/>Nalipayng nawad-an’s dayon<br/>Sa iya’s kalibutan.<br/>',NULL,17698,6);
INSERT INTO stanza VALUES('CB628','7','Padayon! Kay nagkaduol,<br/>Makitang sidlaksidlak’s<br/>Kuta’s matahum nga syudad<br/>’Tukod’s Dios alang nato;<br/>Madungog mananoyng honi,<br/>Giawitan S’yang kanhi<br/>Namatay aron dad-on ta<br/>Sa trono’s gingharian.<br/>',NULL,17699,7);
INSERT INTO stanza VALUES('CB628','8','Pila ka milya n’lang lakwon,<br/>Tiil di na magsakit;<br/>Wa nay sala, way kaguol,<br/>Si Jesus nag-una man;<br/>Katam-is Siyang nihunghong,<br/>“Padayon, ay’g kaluya,<br/>Di pa moabot ang ugma,<br/>Panaw ta matapos na.”<br/>',NULL,17700,8);
INSERT INTO stanza VALUES('CB630','1','Dalan sa Krus pagpakasakit,<br/>Tanan ihalad sa Dios,<br/>Sa halaran gayud sa kamatayon,<br/>May kalayong magsunog.<br/>',NULL,17701,1);
INSERT INTO stanza VALUES('CB630','chorus','Kini dalan sa Krus, lakwon mo ba kini?<br/>Pas-anon bang Krus alang Niya?<br/>Ikawng naghalad sa tanan Niya,<br/>Magmaunongon ka ba?<br/>',NULL,17702,2);
INSERT INTO stanza VALUES('CB630','2','Sa pag-awit ug pag-ampo ta,<br/>Daling maghalad’s tanan;<br/>Apan may bug-at nga krus sa unahan,<br/>Higpit pang tulobagon.<br/>',NULL,17703,3);
INSERT INTO stanza VALUES('CB630','3','Mohunong o mag’tinud-anon<br/>Mamatay’s krus sa dalan,<br/>Hangtud’s kahupnganan’s kinabuhi N’ya<br/>Pun-on ka adlaw-adlaw?<br/>',NULL,17704,4);
INSERT INTO stanza VALUES('CB630','4','Pagkamatay mo’g pagkabuhi,<br/>Plano N’ya’s kinabuhi,<br/>Aron Siyang gibanhaw, gihimaya<br/>Ikinabuhi nimo.<br/>',NULL,17705,5);
INSERT INTO stanza VALUES('CB631','1','Kon nailang pagkabanhaw,<br/>Higugmaon ko ang Krus;<br/>Mag-agi gyud’s kamatayon,<br/>Ayha may pagkabanhaw.<br/>',NULL,17706,1);
INSERT INTO stanza VALUES('CB631','chorus','Kon di mamatay,<br/>Dili mabuhi;<br/>Mobangon sa kamatayon<br/>Ang kinabuhi.<br/>',NULL,17707,2);
INSERT INTO stanza VALUES('CB631','2','Cristo kon iumol nako<br/>Kin’hanglan mamatay ko;<br/>Kinabuhi kong kalagnon<br/>Sa landong sa Krus patyon.<br/>',NULL,17708,3);
INSERT INTO stanza VALUES('CB631','3','Kon sa Espiritung dayon<br/>Ilansang uban Nimo;<br/>Kamatayon kon magbuhat,<br/>Kinabuhi ibubo.<br/>',NULL,17709,4);
INSERT INTO stanza VALUES('CB635','1','Parras atong palandongon,<br/>Kinabuhi n’ya tun-an,<br/>Pagtubo puno’s pag-antus,<br/>Sa lisud n’yang palibot;<br/>Lahi gayud’s kabulakang<br/>Nagtubo’s kamingawan,<br/>Sa pagtubo nagpatuyang,<br/>Iyaiya’g tuyhad lang.<br/>',NULL,17710,1);
INSERT INTO stanza VALUES('CB635','2','Bulak’s parras way himaya,<br/>Gagmay’g di na makita;<br/>Bisan tuod anaa man,<br/>Halos di mamatikdan.<br/>Sukad’s adlaw nga namulak,<br/>Kini mobunga dayon;<br/>Di kapakita’s katahum,<br/>Pamuklad way higayon.<br/>',NULL,17711,2);
INSERT INTO stanza VALUES('CB635','3','Igaid’s haliging bagon,<br/>Di ka’yo makalambo;<br/>Inigtag-as sa ’yang gaway,<br/>Adto dayon’s gambalay.<br/>Batoong yutang gitamnan,<br/>Sa sangkap ’yang kakuhaan;<br/>Di gyud makapili’s gusto,<br/>Mokagiw ba’s kalisud.<br/>',NULL,17712,3);
INSERT INTO stanza VALUES('CB635','4','Pagkatahum’s mga dahon,<br/>Nikaylap sa umahan.<br/>Kinabuhing malagsikon<br/>Nitubong malamboon.<br/>Puno’s mga sangang linghod,<br/>Nikutay ngadto-ngari,<br/>Halos sa langit moabot,<br/>Sa hangin nga nitabyog.<br/>',NULL,17713,4);
INSERT INTO stanza VALUES('CB635','5','Apan agalon’s parrasan,<br/>Wa man magtinapulan,<br/>Gunting, kutsilyong gipul-ong,<br/>Sa garbo giupawan.<br/>Kalinghod ni’ni wa tagda,<br/>Hait nga gipamutlan,<br/>Nilabawng mga sanga n’ya,<br/>Way nigawayng gibilin.<br/>',NULL,17714,5);
INSERT INTO stanza VALUES('CB635','6','Ning panahon’s kapildehan,<br/>Maluoy ka ba’s bagon?<br/>Gihatag n’yang kaugalingon<br/>Labi pa sa agalon,<br/>Sa kamot nga nagpul-ong n’ya,<br/>Sa tanan n’yang katahum,<br/>Aron dili mausik s’ya,<br/>Kondi’ maghatag’s bunga.<br/>',NULL,17715,6);
INSERT INTO stanza VALUES('CB635','7','Bagon mahimo nga kahoy,<br/>Tanang sangang naputlan,<br/>Ug ang nabilin nga sanga,<br/>Dunay pungpong nga bunga.<br/>Unya’s kainit sa Adlaw,<br/>Mga dahon manglarag;<br/>Bunga labi pang mahinog,<br/>Mahimong pupoonon.<br/>',NULL,17716,7);
INSERT INTO stanza VALUES('CB635','8','Sanga mobawog sa bunga,<br/>Sa luwan maubos s’ya;<br/>Mga pagtubong giantus,<br/>Daghang tinuyong hampak.<br/>Karon hinog na ang bunga<br/>Hayahay na unta s’ya;<br/>Apan duol nang pupoon,<br/>Hayahay wad-on dayon.<br/>',NULL,17717,8);
INSERT INTO stanza VALUES('CB635','9','Kamot mokutlo, ug tiil<br/>Motunob’s ’yang kadato,<br/>Hangtud didto sa pigsanan,<br/>Duga’s parras moawas.<br/>Padayon’s tibuok adlaw<br/>Pulang duga magbaha,<br/>Katam-is ug kadagaya<br/>Maglipay’s tibu’k yuta.<br/>',NULL,17718,9);
INSERT INTO stanza VALUES('CB635','10','Sa dagway ang bagon karon<br/>Upawng makaluluoy;<br/>Tanan gihatag, nidangat’s<br/>Gabiing di matukib.<br/>Way nitanyag s’ya balusan’s<br/>Binong hatag nagsadya,<br/>Gihutdan hinoo’g pul-ong<br/>Gibinlan ra’s punoan.<br/>',NULL,17719,10);
INSERT INTO stanza VALUES('CB635','11','Apan bino n’ya’s tingtugnaw<br/>Ang katam-is nagtagbaw,<br/>Init nagkuha’s katugnaw<br/>Kasubo ug panghupaw.<br/>Sa gawas nag-inusara,<br/>Yelo’g nieve nitabon,<br/>Nag-antus lang s’ya gihapon,<br/>Bisan lisud nga sabton.<br/>',NULL,17720,11);
INSERT INTO stanza VALUES('CB635','12','Liwas tingtugnaw andam s’ya<br/>Nga mamunga pag-usab;<br/>Nangudlot s’ya ug nananga,<br/>Dahon matahum na sab.<br/>Way bagulbol o pagmulo’s,<br/>Naagumang abuso;<br/>Ni sa kapildehan siya<br/>Mokunhod’s mga bunga.<br/>',NULL,17721,12);
INSERT INTO stanza VALUES('CB635','13','Sa hanging way sambog, parras<br/>Niginhawa’g nituyhad,<br/>Bagon dili magpahugaw<br/>Sa yutan-ong pangibog.<br/>Sakripisyo may pahiyom,<br/>Sa gugma nagpapul-ong,<br/>Mga hampak sa pagpul-ong,<br/>Giantus lang gihapon.<br/>',NULL,17722,13);
INSERT INTO stanza VALUES('CB635','14','Mga sangang gikuhaan’s<br/>Dugang gihimong bino,<br/>Parras nawad-an, naghatag,<br/>Labi ba nga nakabsan?<br/>Mga palahubog’s yuta,<br/>Nag-inom sa pagsadya.<br/>Sa ila nga kalipayan,<br/>Nadato ba’s inoman?<br/>',NULL,17723,14);
INSERT INTO stanza VALUES('CB635','15','Dili sa naangkon sukdon<br/>Kondi’s nawala nato;<br/>Dili sa binong nainom,<br/>Kondili sa nabubo.<br/>Kusog sa gugma magbarug<br/>Sa sakripisyong nahimo;<br/>Ang labing dako’g kasakit<br/>Mas dako’g mapaambit.<br/>',NULL,17724,15);
INSERT INTO stanza VALUES('CB635','16','Ang labing mosakripisyo,<br/>Labing makaangkon’s Dios;<br/>Ang masakitan pag-ayo,<br/>M’oy labing makalipay.<br/>Kinsa kadtong wa mag-antus,<br/>“Tulonggon rang sabaan,“<br/>Kadto rang naghalad’s bug-os,<br/>Ang malipayon’s tanan.<br/>',NULL,17725,16);
INSERT INTO stanza VALUES('CB639','1','Kamatayon dili makapugong<br/>Sa kinabuhi sa pagkabanhaw;<br/>Madaugong walay makapukan,<br/>Si Cristo mismo nga nadayag na.<br/>',NULL,17726,1);
INSERT INTO stanza VALUES('CB639','2','Kamatayon dili makapugong<br/>Bisan pag iyang kusog tibuk-on;<br/>Kini mosamot lang pagpadayag<br/>Sa kadato’s gahum’s pagkabanhaw!<br/>',NULL,17727,2);
INSERT INTO stanza VALUES('CB639','3','Kamatayon dili makapugong,<br/>Pagpatay pagpasanay hinoon;<br/>Tanang pag-antus makapatubo,<br/>Makapabunga’g labi pang dako.<br/>',NULL,17728,3);
INSERT INTO stanza VALUES('CB639','4','Kamatayon dili makapugong,<br/>Gibuak Niyang tanang nagsampong;<br/>Hades ug kangitngitan gidaug,<br/>Kamatayon Iya nga giwala.<br/>',NULL,17729,4);
INSERT INTO stanza VALUES('CB639','5','Kamatayon dili makapugong,<br/>Ipadayag n’yang kahupnganan’s Dios;<br/>Pagkabalaa’g pagkamatarung,<br/>Dagwayng madayag mahimayaon.<br/>',NULL,17730,5);
INSERT INTO stanza VALUES('CB639','6','Masayran unta ang pagkabanhaw,<br/>Ibubong gahum N’ya’s kamatayon;<br/>Maila sa akong pagsinati<br/>Nga si Cristo maoy kinabuhi.<br/>',NULL,17731,6);
INSERT INTO stanza VALUES('CB640','1','Mabuhi gikan’s kamatayon, saad<br/>Kini karon o sa umalabot?<br/>Di na hulaton? Sudlanang gubaon<br/>Ayohon sa Magkokolon karon.<br/>',NULL,17732,1);
INSERT INTO stanza VALUES('CB640','2','Mabuhi kita gikan’s kamatayon,<br/>Gipugas luya, moturok lig-on;<br/>Kinabuhi madayag’s pag-ulay na,<br/>Matag takna “di ako, kondi’ S’ya.”<br/>',NULL,17733,2);
INSERT INTO stanza VALUES('CB640','3','Ang panaw nato pagkamingaw gayud,<br/>Ang nakaila’s Krus ray mosunod;<br/>Nabuhi’s pag-ambitay ni “Jesus ra,“<br/>Kaayohan daw kapildehan man.<br/>',NULL,17734,3);
INSERT INTO stanza VALUES('CB640','4','Mabuhi kita gikan’s kamatayon,<br/>Misyono’g dala ang buhing tubig,<br/>Kinabuhi gikan’s tin-aw nga suba,<br/>Aron giuhaw di na uhawon.<br/>',NULL,17735,4);
INSERT INTO stanza VALUES('CB643','1','Hatagi’g panahon<br/>Makigsulti Niya,<br/>Pabilin Kaniya,<br/>Kan-ong Pulong N’ya.<br/>Sa Iyang presensya<br/>Maghulat kita,<br/>Panalangin Niya,<br/>Tinguhaon ta.<br/>',NULL,17736,1);
INSERT INTO stanza VALUES('CB643','2','Hatagi’g panahon<br/>Magsud-ong Niya,<br/>Makigsulti’s tago<br/>Ubang Jesus ra.<br/>Pagtan-aw Kaniya<br/>Mahisama ta,<br/>Kahigalaan ta,<br/>Makakita N’ya.<br/>',NULL,17737,2);
INSERT INTO stanza VALUES('CB643','3','Hatagi’g panahon<br/>Magpagiya N’ya,<br/>Di mag-una-una,<br/>Agdon gyud Siya;<br/>Kalipay’g kasubo,<br/>S’ya m’oy pabut-on,<br/>Si Jesus tutokan,<br/>Pulong saligan.<br/>',NULL,17738,3);
INSERT INTO stanza VALUES('CB643','4','Hatagi’g panahon<br/>Magpalig-on ka,<br/>Pagamha una S’ya’s<br/>Tanang buhaton.<br/>Kay kon Espiritu<br/>Maoy magmando,<br/>Mahimong takus ka<br/>Nga kaloy-an N’ya.<br/>',NULL,17739,4);
INSERT INTO stanza VALUES('CB645','1','O kalag, gikapuyan ka ba?<br/>Way kahayag nga makita?<br/>Sud-onga’s Jesus, may kahayag,<br/>Kinabuhi nga dagaya.<br/>',NULL,17740,1);
INSERT INTO stanza VALUES('CB645','chorus','Liso’g sud-onga’s Jesus,<br/>Nawong N’ya tutoki karon,<br/>Sa himaya N’ya ang tanang butang<br/>Mangalubad, di igsapayan.<br/>',NULL,17741,2);
INSERT INTO stanza VALUES('CB645','2','Mamatay ta unya mabuhi,<br/>Nag-una S’ya, mosunod ta;<br/>Gahum’s sala di na maghari,<br/>Labaw pa’s mananaug ta!<br/>',NULL,17742,3);
INSERT INTO stanza VALUES('CB645','3','Pulong N’ya di gyud mangapakyas,<br/>Toohan S’ya, tanan sayon.<br/>Busa kalibutan sultian<br/>Sa hingpit N’yang kaluwasan!<br/>',NULL,17743,4);
INSERT INTO stanza VALUES('CB656','1','“Isipa S’ya,” himoang sumbanan,<br/>Sayring nabihag ikaw Kaniya,<br/>Mag-ambit’s gahum N’ya’g kinabuhi,<br/>Aron magsidlak sa dagway Niya.<br/>',NULL,17744,1);
INSERT INTO stanza VALUES('CB656','2','“Isipa Siya,” sa adlaw-adlaw,<br/>Labing ubos nga dapit adtoa,<br/>Kontentong palabyon bisan unsa,<br/>Mahimaya lang ang Amahan ta.<br/>',NULL,17745,2);
INSERT INTO stanza VALUES('CB656','3','Ayaw pagsibog, O anak sa Dios,<br/>’Naug ngadto’s kamatayong Jesus;<br/>Sayring gahum’s kinabuhing dayon,<br/>Kagawasan’s sala’g kaugalingon.<br/>',NULL,17746,3);
INSERT INTO stanza VALUES('CB656','4','“Isipa Siya,” kinabuhi mo<br/>Mapuno’s pagtugyan’s kaugalingon;<br/>Buhaton’s Dios sumbanang matuod,<br/>Panig-ingnang Cristo maoy tumong.<br/>',NULL,17747,4);
INSERT INTO stanza VALUES('CB656','5','“Isipa Siya,” pagdagan’s lumba,<br/>Maghangad kanunay’s Iyang nawong;<br/>Matransporma’g magsidlak unya ka,<br/>Dagway N’ya diha nimo makita.<br/>',NULL,17748,5);
INSERT INTO stanza VALUES('CB657','1','Makasugot ba mo’s<br/>Inyong Ginoo,<br/>Kon yuta uyogon,<br/>Langit gun-obon?<br/>Makatoo ba mo<br/>Ang Dios mag-uban<br/>Bisan maglibot pa<br/>Ang katalagman?<br/>',NULL,17749,1);
INSERT INTO stanza VALUES('CB657','2','Makasugot ba mo’s<br/>Inyong Ginoo,<br/>Di gayud mahadlok,<br/>Di sab mosibog;<br/>Bisan ang unahan<br/>Kamatayon man,<br/>Makasugot ba nga<br/>Way panagana?<br/>',NULL,17750,2);
INSERT INTO stanza VALUES('CB657','3','Makasugot ba gyud<br/>Kon tawgon kamo<br/>Pagsulong’s unahan<br/>Batok’s kaatbang?<br/>Tinuod ba kamong<br/>Magpasugo N’ya,<br/>Makiggubat hangtud<br/>Gubat matapos?<br/>',NULL,17751,3);
INSERT INTO stanza VALUES('CB657','4','Makahimo ba mo?<br/>Cristo naghulat!<br/>Angayng magpasakop,<br/>Sugo N’ya sundon;<br/>Kon sundalo mo N’ya,<br/>Sa ’yang pagbalik,<br/>Tawgon mo sa ngalan<br/>Ug daygon Niya!<br/>',NULL,17752,4);
INSERT INTO stanza VALUES('CB659','1','Magkalipay ta diha sa Ginoo,<br/>Sa ’yang gugma ug kalomo;<br/>Gitubos kita, unsay kalisangan?<br/>Si Jesus ang atong tanan.<br/>',NULL,17753,1);
INSERT INTO stanza VALUES('CB659','chorus','Kon ang atong Dios dapig kanato?<br/>Kinsa man ang makabatok kanato?<br/>Kinsa man?<br/>Kinsay makabatok kanato?<br/>',NULL,17754,2);
INSERT INTO stanza VALUES('CB659','2','Magmakusganon ug magmalipayon,<br/>Sa Ginoo maunongon;<br/>Yawa nagngulob, suklan ta’s kaisug,<br/>Ang Ginoo atong kusog.<br/>',NULL,17755,3);
INSERT INTO stanza VALUES('CB659','3','Salig sa Pulong, ’yang saad matuod,<br/>Kang Cristo ang tanan Amen,<br/>Yuta molabay, ’yang pulong motunhay,<br/>Nasulat kini kanunay.<br/>',NULL,17756,4);
INSERT INTO stanza VALUES('CB659','4','Pabilin Niya ug magpadumala,<br/>Sugod’s kinabuhing dayon;<br/>Bisan maluyahon ta ug nagkurog,<br/>Yawa di gyud makailog.<br/>',NULL,17757,5);
INSERT INTO stanza VALUES('CB663','1','“Sulong!” Isinggit ta,<br/>Ngadto’s unahan;<br/>Magpadayon’s tumong,<br/>Way lingi-lingi;<br/>Haligi’s kalayo<br/>Maghayag’s dalan,<br/>Kinsay matalawan,<br/>S’ya ang Kapitan?<br/>Sulong’s kamingawan,<br/>Sa panggubatan;<br/>Naghulat kanato<br/>Ang Gingharian.<br/>',NULL,17758,1);
INSERT INTO stanza VALUES('CB663','2','Dugang nga himaya<br/>Ang giandam N’ya,<br/>Alang sa kalag nga<br/>Nahigugma N’ya;<br/>Wa pa igkita ta,<br/>Ni madungog ba;<br/>Ni mahunahuna,<br/>Pagkahimaya!<br/>Sulong sa unahan<br/>Sa gingharian,<br/>Hangtud pagtoo ta<br/>Makita’s tanan!<br/>',NULL,17759,2);
INSERT INTO stanza VALUES('CB666','1','Matapos nang gabii,<br/>Duol nang kadlawon;<br/>Kalibutan tukawi,<br/>Di tinguhaon.<br/>Pagtukaw, mobalik na<br/>Ang atong Ginoo!<br/>Pagtukaw, gihulat ka,<br/>Ay’ gyug kaluya!<br/>',NULL,17760,1);
INSERT INTO stanza VALUES('CB666','2','Pagtukaw, mag-alagad!<br/>Bisag laayng adlaw;<br/>Pagtukaw, mangabudlay!<br/>Adlaw matapos.<br/>Hinagiban isul-ob!<br/>Tukaw’s espiritu;<br/>Ang yawa suklan nimo,<br/>Mobalik’s Cristo.<br/>',NULL,17761,2);
INSERT INTO stanza VALUES('CB666','3','Moabot nang Manlul’was!<br/>Bito’n’s Kabugason;<br/>Gingharian agpason!<br/>Makigbisug gyud.<br/>Hangtud gabii matapos!<br/>Hangtud mokadlawon;<br/>Tukawi gayud hangtud<br/>Gino’ moabot.<br/>',NULL,17762,3);
INSERT INTO stanza VALUES('CB671','1','Sa kahiladman sa Imong Ngalan,<br/>Nitidlom ko’g puyo sa kalipay;<br/>Igo Ka bisan taas ang adlaw,<br/>Bisan gabii labi kadulom.<br/>',NULL,17763,1);
INSERT INTO stanza VALUES('CB671','2','Ikaw akong Dios—ang Igo’s-tanan,<br/>Mamugna Mong panginahanglan ko;<br/>Gisabwag Mo’s mamingaw kong dalan<br/>Ang milagro’s gugma’g pag-atiman.<br/>',NULL,17764,2);
INSERT INTO stanza VALUES('CB671','3','Kining nisalig mangahas pa gyud<br/>Pagdangop Nimo, O akoang Dios,<br/>Gisimbang paagi Mo’s pagtoo,<br/>Sa hilom nga pahulay’s pagtoo.<br/>',NULL,17765,3);
INSERT INTO stanza VALUES('CB679','1','Sa mga bukton ni Jesus,<br/>Luwas ug malig-on;<br/>O katam-is sa pahulay,<br/>Gugma N’ya m’oy nagpandong.<br/>Awit kining langitnon,<br/>Tam-is paminawon,<br/>Espiritu’s balaan,<br/>Pulos nagkauyon.<br/>',NULL,17766,1);
INSERT INTO stanza VALUES('CB679','chorus','Sa mga bukton ni Jesus,<br/>Luwas ug malig-on,<br/>O katam-is sa pahulay,<br/>Gugma N’ya m’oy nagpandong.<br/>',NULL,17767,2);
INSERT INTO stanza VALUES('CB679','2','Sa mga bukton ni Jesus,<br/>Wa nay kabalaka,<br/>Luwas ka’s mga pagtintal,<br/>Ug pagdaut sa sala.<br/>Magawas sa kasubo,<br/>Katahap ug kahadlok;<br/>Gamay na lang pagsulay,<br/>Gamay nang paghilak.<br/>',NULL,17768,3);
INSERT INTO stanza VALUES('CB679','3','Gipakamatyan ako N’ya,<br/>Dalangpanan ko S’ya;<br/>Bato ko nga malig-on,<br/>Kasaligan’s dayon.<br/>Siya akong hulaton<br/>Nga mapailubon,<br/>Hangtud sa kabuntagon,<br/>Iya kong anhion.<br/>',NULL,17769,4);
INSERT INTO stanza VALUES('CB686','1','Ayaw ug kahadlok,<br/>Ako mag-uban,<br/>Sama sa bitoon<br/>Magdan-ag’s dalan,<br/>Latas tungang gab’i,<br/>Maoy saad Mo,<br/>“Di Ko mob’ya nimo,<br/>Di ka mag-inusara.”<br/>',NULL,17770,1);
INSERT INTO stanza VALUES('CB686','chorus','Di gyud mobiya,<br/>Di ug di gayud,<br/>Saad N’ya di gyud mobiya,<br/>Di gyud mobiya nako.<br/>Di gyud mobiya,<br/>Di ug di gayud,<br/>Saad N’ya di gyud mobiya,<br/>Di gyud mobiya nako.<br/>',NULL,17771,2);
INSERT INTO stanza VALUES('CB686','2','Rosas mangalaya,<br/>Lirio mamatay,<br/>Mawang silaw’s Adlaw,<br/>Langit hayag man!<br/>*Copher’ng bulak, Jesus,<br/>Alang’s Iyaha,<br/>Jesus nga kahayag,<br/>Di gyud mobiya nako.<br/>',NULL,17772,3);
INSERT INTO stanza VALUES('CB686','3','Butang wa makit-i,<br/>Duol’ng kakuyaw,<br/>Mas duol’ng Manlul’was,<br/>Hunghong, “Maglipay“;<br/>Daw langgam nitugdon,<br/>Kalipay’s dughan,<br/>Tam-is nga nag-awit,<br/>“Di S’ya mobiya nako.”<br/>',NULL,17773,4);
INSERT INTO stanza VALUES('CB697','1','Magpapanaw nga gikapoy,<br/>Nanlimbasug sa luwan;<br/>Paminawa ang sulti N’ya,<br/>“Itugyan Niyang luwan.”<br/>',NULL,17774,1);
INSERT INTO stanza VALUES('CB697','chorus','Itugyan na’s Ginoo<br/>Ang tanang kabug-at mo,<br/>S’ya maglig-on nimo,<br/>Mobulig, molipay—<br/>Luwan itugyan Niya.<br/>',NULL,17775,2);
INSERT INTO stanza VALUES('CB697','2','Nagkurog ka ba’s kakapoy?<br/>Ug suga wa mosiga?<br/>Bug-at ra ba ang imong krus?<br/>“Luwan itugyan Niya.”<br/>',NULL,17776,3);
INSERT INTO stanza VALUES('CB697','3','Nahimulag ba’s higala?<br/>Minahal mo hilom na?<br/>May kasakit’s kasingkasing?<br/>“Luwan itugyan Niya.”<br/>',NULL,17777,4);
INSERT INTO stanza VALUES('CB697','4','Kasingkasing nagluya ba?<br/>Nalimtan bang pulong N’ya?<br/>Gidaug ka ba’s kahuyang?<br/>“Luwan itugyan Niya.”<br/>',NULL,17778,5);
INSERT INTO stanza VALUES('CB697','5','Kuptan aron di matumba,<br/>Mga lakang maggiya;<br/>Lig-onon ka’s matag buhat,<br/>Ampingan’s gahum Niya.<br/>',NULL,17779,6);
INSERT INTO stanza VALUES('CB698','1','Sa pagsulayng nahiagoman,<br/>Mga tunok sa akong dalan,<br/>May matam-is nga hunahuna,<br/>Naghandom Ka nako!<br/>',NULL,17780,1);
INSERT INTO stanza VALUES('CB698','chorus','Naghandom Ka nako!<br/>Naghandom Ka nako!<br/>Unsa may kahadlokan ko?<br/>Naghandom Ka nako.<br/>',NULL,17781,2);
INSERT INTO stanza VALUES('CB698','2','Kabalaka ug kalisdanan,<br/>Nagpuno nako’s kangitngitan,<br/>Apan akong nahinumdoman,<br/>Gihandom Mo ako!<br/>',NULL,17782,3);
INSERT INTO stanza VALUES('CB698','3','Kalisud moabot, molabay,<br/>Masanagon ba o mangitngit,<br/>Kontento kay nahibalo ko<br/>Gihandom Mo ako!<br/>',NULL,17783,4);
INSERT INTO stanza VALUES('CB701','1','Manluluwas ko naggiya,<br/>Unsa pay pangayoon?<br/>Magduda pa ba’s kaluoy,<br/>Nga nagg’ya’s tibu’k panaw?<br/>Kalinaw, diosnong paglipay,<br/>Mopuyo N’ya’s pagtoo!,<br/>Kay bisan unsang dangatan,<br/>Tanan ayohon man N’ya,<br/>Kay bisan unsang dangatan,<br/>Tanan ayohon man N’ya.<br/>',NULL,17784,1);
INSERT INTO stanza VALUES('CB701','2','Manluluwas ko naggiya,<br/>Nagdasig nako’s dalan,<br/>Sa pagsuway hatagan’s grasya,<br/>Buhing tinapay sangkap.<br/>Maluya usahay’s lakaw,<br/>Kalag uhawon gayud,<br/>Tan-awa sa unahan ta,<br/>May tubod sa kalipay.<br/>Tan-awa sa unahan ta,<br/>May tubod sa kalipay.<br/>',NULL,17785,2);
INSERT INTO stanza VALUES('CB701','3','Manluluwas ko naggiya,<br/>Kahupong sa grasya N’ya,<br/>Hingpit nga pahuway gisaad<br/>Sa sabakan’s Amahan.<br/>Espiritu kon sul-oban’s<br/>Eternidad, molupad,<br/>Awit ko’s way katapusan:<br/>S’ya nagg’ya’s tibu’k panaw,<br/>Awit ko’s way katapusan:<br/>S’ya nagg’ya’s tibu’k panaw.<br/>',NULL,17786,3);
INSERT INTO stanza VALUES('CB703','1','Magpapanaw nga gikapoy,<br/>Gisaaran ka sa Dios,<br/>Sa yuta ngadto’s himaya,<br/>“Giyahan ka’s Akong mata.”<br/>',NULL,17787,1);
INSERT INTO stanza VALUES('CB703','chorus','Giyahan ka, giyahan ka,<br/>Giyahan ka’s Akong mata;<br/>Sa yuta ngadto’s himaya,<br/>Giyahan ka’s Akong mata.<br/>',NULL,17788,2);
INSERT INTO stanza VALUES('CB703','2','Kon modasmag ang pagtintal,<br/>Sinaligan mangagiw,<br/>Dumdomi kini nga saad,<br/>“Giyahan ka’s Akong mata.”<br/>',NULL,17789,3);
INSERT INTO stanza VALUES('CB703','3','Kon paglaum mangawala,<br/>Gilubong na’s kalimot;<br/>Lipayon unta ning saad,<br/>“Giyahan ka’s Akong mata.”<br/>',NULL,17790,4);
INSERT INTO stanza VALUES('CB703','4','Bulok’s kinabuhi mawa’,<br/>Kamatayon moabot,<br/>Piloto ta paminawa,<br/>“Giyahan ka’s Akong mata.”<br/>',NULL,17791,5);
INSERT INTO stanza VALUES('CB708','1','Lunhaw sama’s yamog’s buntag,<br/>Tam-is pahuway ang dala;<br/>Sa lomong dihog, si Cristo,<br/>Nihunghong ug naglipay:<br/>Magbarug hangtud matapos<br/>Ang pagsulay ug unos,<br/>Baruging himayang Jesus,<br/>Gingharian maangkon.<br/>',NULL,17792,1);
INSERT INTO stanza VALUES('CB708','chorus','Paglaum ko,<br/>tingog Mo katam-is!<br/>Magkalipay ako’s<br/>presensya Mo.<br/>',NULL,17793,2);
INSERT INTO stanza VALUES('CB708','2','Kon espiritu maluya<br/>Sa nagsulayng kasamok,<br/>Pagtoo, dan-ag’s paglaum,<br/>Tanan mangabungkag na,<br/>Bug-os unta kong magamhan’s<br/>Kusog Mo’s kinabuhi,<br/>Aron maambitan nako<br/>Kadato’s himaya Mo.<br/>',NULL,17794,3);
INSERT INTO stanza VALUES('CB708','3','Ginoo, sa kaadlawon,<br/>Kangitngit ko abugon;<br/>Sa pako Mong makaayo,<br/>Gab’i ko himo’ng adlaw.<br/>Lipaya na, O Ginoo,<br/>Kasingkasing nasubo;<br/>Paglaum Ka sa himaya,<br/>Ayaw, ayaw pagbiya.<br/>',NULL,17795,4);
INSERT INTO stanza VALUES('CB717','1','Magkalipay ta diha sa Ginoo,<br/>Bisan pagsulay naglibot nato,<br/>Baha’s kasakit daw balud nibul-og,<br/>Maayong moawit kay’s manghupaw.<br/>',NULL,17796,1);
INSERT INTO stanza VALUES('CB717','chorus','Magkalipay kita hangtud sa dayon,<br/>Maayong moawit kay’s manghupaw,<br/>Maayong mabuhi kay’s mamatay,<br/>Busa magkalipay kita.<br/>',NULL,17797,2);
INSERT INTO stanza VALUES('CB717','2','Magkalipay ta diha sa Ginoo,<br/>Kon udyong’s maninintal manglupad,<br/>Kay si Satanas sa gihapon hadlok gyud,<br/>Sa awit ta labaw sa panghupaw.<br/>',NULL,17798,3);
INSERT INTO stanza VALUES('CB717','3','Magkalipay ta diha sa Ginoo,<br/>Kon sakit nitakboy kanato,<br/>Way sama’s kalipay mag-uli’s kusog,<br/>Kalipay N’ya maoy makaayo.<br/>',NULL,17799,4);
INSERT INTO stanza VALUES('CB720','1','Dios wa magsaad pirming langit,<br/>Bulakong dalan ang agian,<br/>Kanunayng Adlaw nga way ulan,<br/>Pirming kalipay, way kasubo.<br/>',NULL,17800,1);
INSERT INTO stanza VALUES('CB720','chorus','Apan nagsaad ’yang lig-onon,<br/>Ang nagbuhat ’yang pahulayon,<br/>Grasya ihatag sa gisulay,<br/>Gugma ug simpatiya kanunay.<br/>',NULL,17801,2);
INSERT INTO stanza VALUES('CB720','2','Dios wa magsaad di igtagbo<br/>Mga kasamok ug kasubo;<br/>Wa ta sultiing di magpas-an’s<br/>Daghang luwan ug kabalak-an.<br/>',NULL,17802,3);
INSERT INTO stanza VALUES('CB720','3','Dios wa magsaad nga panaw ta<br/>Lunlon sayon, di giyahan N’ya.<br/>Way mga bungtod nga tungason,<br/>O mga suba nga latason.<br/>',NULL,17803,4);
INSERT INTO stanza VALUES('CB722','1','Krus nga hatag N’ya bisan bug-at,<br/>Di molabaw’s ’yang grasya;<br/>Unos nga gikahadlokan ko,<br/>Di motabon’s nawong N’ya.<br/>',NULL,17804,1);
INSERT INTO stanza VALUES('CB722','chorus','Krus nga hatag di labaw’s grasya,<br/>Unos di motabon’s nawong N’ya;<br/>Kontento kong nasayud<br/>Kauban S’ya, mapilde<br/>Tanang kaaway dinhi.<br/>',NULL,17805,2);
INSERT INTO stanza VALUES('CB722','2','Tunok’s dalan ko di mas hait,<br/>Sa tunok gipurong N’ya;<br/>Kopang giinom di matandi’s<br/>Giinom’s Getsemane.<br/>',NULL,17806,3);
INSERT INTO stanza VALUES('CB722','3','Labi pang maghayag ang nawong N’ya,<br/>Kon dalan masulob-on;<br/>Luwan ko mogaan hinoon,<br/>Kon motabang’s nasubo.<br/>',NULL,17807,4);
INSERT INTO stanza VALUES('CB722','4','’Buot N’ya tumanon’s kalipay,<br/>Maggawi’s presensya N’ya;<br/>Pagsulay magda’g panalangin,<br/>Cristo naa niini.<br/>',NULL,17808,5);
INSERT INTO stanza VALUES('CB724','1','Gamay ko nga langgam,<br/>Nadakpan’s umahan,<br/>Bisag gihawla’s Ginoo,<br/>Siyay awitan ko;<br/>Nalipay nga gihawla Mo,<br/>Kay m’oy gikahimut-an Mo.<br/>',NULL,17809,1);
INSERT INTO stanza VALUES('CB724','2','Way laing buhaton,<br/>Sa tanang panahon,<br/>Awita’g pahamut-an S’yang<br/>Naminaw’s awit ko.<br/>Bisan gigapos Mong pako<br/>Namati Ka sa awit ko.<br/>',NULL,17810,2);
INSERT INTO stanza VALUES('CB724','3','Awit paminawon,<br/>Ako bulahanon;<br/>Bisag awit di matahum;<br/>Imong pamation.<br/>Kay nasayud Kang awit ko<br/>Dinasig’s gugma ko Nimo.<br/>',NULL,17811,3);
INSERT INTO stanza VALUES('CB724','4','Bilanggo ning hawla,<br/>Di na makagula;<br/>Kasingkasing ko gawas man,<br/>Bisag pako hiniktan;<br/>Hawla di makabilanggo,<br/>Sa kagawasan’s kalag ko.<br/>',NULL,17812,4);
INSERT INTO stanza VALUES('CB724','5','O nindot ilupad<br/>Kining tanang babag!<br/>Kaniya kansang pagbuot<br/>Ug tuyo gimahal;<br/>Sa pagbuot Mo mapalgan,<br/>Ang kalipay ko’g kagawasan.<br/>',NULL,17813,5);
INSERT INTO stanza VALUES('CB733','1','Dios sa Eden kaniadto<br/>Atbang’s kahoy nagbutang’s tawo;<br/>Usa maong kinabuhi,<br/>Ug ang usa kahibalo.<br/>',NULL,17814,1);
INSERT INTO stanza VALUES('CB733','2','Kinabuhi maoy sentro<br/>Sumala sa Iyang plano;<br/>Dios diha ni Jesucristo<br/>Ma-kinabuhi sa tawo.<br/>',NULL,17815,2);
INSERT INTO stanza VALUES('CB733','3','Kahibalo pasidaan,<br/>Gawas sa Dios may tinubdan:<br/>Ang yawa nga kamatayon,<br/>Mamatay ka kon pilion.<br/>',NULL,17816,3);
INSERT INTO stanza VALUES('CB733','4','Kahoy’s kinabuhi kan-on,<br/>Kinabuhi’s Dios maangkon;<br/>Mahimong batong mahalon,<br/>Magtuman’s ’yang kabubut-on.<br/>',NULL,17817,4);
INSERT INTO stanza VALUES('CB733','5','Kahoy’s kahibalo kan-on,<br/>Yawa ang mosulod sa tawo;<br/>Maghatud n’ya’s kamatayon,<br/>Ang plano sa Dios pakyason.<br/>',NULL,17818,5);
INSERT INTO stanza VALUES('CB733','6','Kini hulagway nga Dios ra<br/>Ang tinubdan’s kinabuhi;<br/>Tanang butang gawas Niya<br/>Tinubdan sa kamatayon.<br/>',NULL,17819,6);
INSERT INTO stanza VALUES('CB733','7','Kahibalo, kamatayon,<br/>Bisa’g maayo tan-awon;<br/>Bisan unsa gawas sa Dios,<br/>Bunga man’s plano sa yawa.<br/>',NULL,17820,7);
INSERT INTO stanza VALUES('CB733','8','Maayo ba o dautan,<br/>Pulos gyud sa Dios kaatbang;<br/>Di pag-ila ra’s dautan,<br/>Bisan usab sa maayo.<br/>',NULL,17821,8);
INSERT INTO stanza VALUES('CB733','9','Ginoo, tudloi kami,<br/>Tandogon rang kinabuhi;<br/>Di maayo o dautan<br/>O gawas ba Nimong butang.<br/>',NULL,17822,9);
INSERT INTO stanza VALUES('CB734','1','Kasugoan’s Dios maayo,<br/>Kay maayo may gisugo;<br/>Tuyo ni’ni klaro ka’yo,<br/>Pakit-on tang di makahimo.<br/>',NULL,17823,1);
INSERT INTO stanza VALUES('CB734','2','Sa salabutan may *sugo,<br/>Nga magbuhat’s maayo gyud;<br/>Apan’s mga bahin nato,<br/>May sugo nga ni’ni nidaug.<br/>',NULL,17824,2);
INSERT INTO stanza VALUES('CB734','3','Sugo’s salabutan ma’yo,<br/>Iya ni’s kinabuhi’s tawo,<br/>Sa paglalang sa Ginoo,<br/>Paggawi nato magmaayo.<br/>',NULL,17825,3);
INSERT INTO stanza VALUES('CB734','4','Sugo na’s mga bahin ta,<br/>Iya’s kinabuhi’s yawa;<br/>Ang lala niya nasulod,<br/>Sa mga bahin ta sa unod.<br/>',NULL,17826,4);
INSERT INTO stanza VALUES('CB734','5','Dautang sugo sa yawa,<br/>Sugo sab sa sala’s sulod;<br/>Mas kusgan’s sugo’s maayo,<br/>Kanunayng modaug’s maayo.<br/>',NULL,17827,5);
INSERT INTO stanza VALUES('CB734','6','Apan’s atong espiritu,<br/>Naang sugo’s kinabuhi;<br/>Kinabuhi gyud ni sa Dios,<br/>Sa pag-anak pag-usab nato.<br/>',NULL,17828,6);
INSERT INTO stanza VALUES('CB734','7','Kasugoang labing kusgan,<br/>Sugong tanan ’yang gilabwan;<br/>Nagpagawas sugo’s sala,<br/>Nagtagbo gyud sa sugo sa Dios.<br/>',NULL,17829,7);
INSERT INTO stanza VALUES('CB734','8','Ibutang tang hunahuna,<br/>Sa espiritu sa sulod;<br/>Ug di’s mga butang’s unod,<br/>Lawas bang nadaut sa sala.<br/>',NULL,17830,8);
INSERT INTO stanza VALUES('CB734','9','Kon unod hunahunaon,<br/>Sala kana’g kamatayon;<br/>Kon ibutang’s espiritu,<br/>Kinabuhi kini’g kalinaw.<br/>',NULL,17831,9);
INSERT INTO stanza VALUES('CB734','10','Paagi ni’s kagawasan!<br/>Paagi ni’s kadaugan!<br/>Sa espiritu mabuhi,<br/>Sa Espiritu maggawi.<br/>',NULL,17832,10);
INSERT INTO stanza VALUES('CB735','1','Kasugoan nagsaysay’s Dios,<br/>M’oy Iyang panghimatuod<br/>Nga S’ya balaan, matarung,<br/>Kanato mahigugmaon.<br/>',NULL,17833,1);
INSERT INTO stanza VALUES('CB735','2','Sumala’s kinaiya N’ya<br/>Kinahanglan mabuhi ta,<br/>Aron matarungong kalag,<br/>Panalanginan N’ya kita.<br/>',NULL,17834,2);
INSERT INTO stanza VALUES('CB735','3','Ang sugo di makahatag<br/>Sa kinabuhi ug kusog,<br/>Apan mosugo gyud kini,<br/>Sa kaluyahon magbutyag.<br/>',NULL,17835,3);
INSERT INTO stanza VALUES('CB735','4','Sugo wa unta planoha,<br/>Tungod sa sala namugna,<br/>Aron tawo makaila,<br/>Nahalin na s’ya sa sala.<br/>',NULL,17836,4);
INSERT INTO stanza VALUES('CB735','5','Ang sugo nagtak-om’s baba<br/>Tanan gibilanggo’s sala;<br/>Nagdala nato kang Cristo<br/>Panalangin’s Dios maato.<br/>',NULL,17837,5);
INSERT INTO stanza VALUES('CB735','6','Sugo hulagway ni Cristo,<br/>Sa Dios Siyay testimonyo,<br/>Nagpadayag sa ’yang gugma,<br/>Kabalaa’g katarung N’ya.<br/>',NULL,17838,6);
INSERT INTO stanza VALUES('CB735','7','Panghimatuod sa Dios S’ya,<br/>Nagsangkap sa kinabuhi,<br/>Aron kita makatagbo<br/>Sa mga hangyo sa sugo.<br/>',NULL,17839,7);
INSERT INTO stanza VALUES('CB735','8','Diha N’ya nakaambit ta,<br/>Sa kusgang kinabuhi N’ya,<br/>Namatay ta’s mga sugo<br/>Mamunga sa Espiritu.<br/>',NULL,17840,8);
INSERT INTO stanza VALUES('CB736','1','Kanhi ang balaod sa Dios<br/>Gikulit’s papan nga bato;<br/>Karon sa kinabuhi na,<br/>Nasulat’s kasingkasing ta.<br/>',NULL,17841,1);
INSERT INTO stanza VALUES('CB736','2','Sugo’s balaod naghangyo,<br/>Nagbutyag’s kaluyahon ta;<br/>Balaod’s kinabuhi N’ya<br/>Maoy naggahum kanato.<br/>',NULL,17842,2);
INSERT INTO stanza VALUES('CB736','3','Balaod’s letra nagdala<br/>Kahibalo’s Dios sa gawas;<br/>Balaod’s kinabuhi N’ya<br/>Naghatag’s pag-ila’s sulod.<br/>',NULL,17843,3);
INSERT INTO stanza VALUES('CB736','4','Balaod’s letra nagbuot<br/>Pinaagi’s patayng sugo;<br/>Balaod sa kinabuhi<br/>Nagbuot’s buhing paagi.<br/>',NULL,17844,4);
INSERT INTO stanza VALUES('CB736','5','Buhing balaod naglihok<br/>Sa tanang nasinati ta,<br/>Nagbalaod nato’s sulod<br/>Gisukot ta’s pagbati’s su’d.<br/>',NULL,17845,5);
INSERT INTO stanza VALUES('CB736','6','Lalum kining magbalaod,<br/>Sa ato gayud nga sulod,<br/>Buhi nga makapabati,<br/>Sa Dios mismo nagpaambit.<br/>',NULL,17846,6);
INSERT INTO stanza VALUES('CB736','7','Ning balaod’s kinabuhi<br/>Di na kin’hanglang tudloan,<br/>Kay Dios buhing mahibal-an,<br/>Sa balaod N’ya tudloan.<br/>',NULL,17847,7);
INSERT INTO stanza VALUES('CB736','8','Paggawia ning balaod,<br/>Pasugta’s pagbuot’s sulod,<br/>Aron makaambit Nimo<br/>Buhi Kang maila namo.<br/>',NULL,17848,8);
INSERT INTO stanza VALUES('CB737','1','Kinabuhing dayon<br/>Nagdala nato,<br/>Sa pakig-ambitay<br/>Sa kinabuhi.<br/>',NULL,17849,1);
INSERT INTO stanza VALUES('CB737','2','Ang pakig-ambitay<br/>Sa kinabuhi,<br/>M’oy mag-usa nato<br/>Sa Espiritu.<br/>',NULL,17850,2);
INSERT INTO stanza VALUES('CB737','3','Masangkapan kita<br/>Sa Iyang grasya,<br/>Sa pakig-ambitay<br/>Sa Espiritu.<br/>',NULL,17851,3);
INSERT INTO stanza VALUES('CB737','4','Ang pakig-ambitay<br/>Sa Espiritu,<br/>Magdala kanato<br/>Diha’s kahayag.<br/>',NULL,17852,4);
INSERT INTO stanza VALUES('CB737','5','Pakig-ambitay ta<br/>Ampingan gayud,<br/>Pinaagi’s dihog<br/>Dugong maghinlo.<br/>',NULL,17853,5);
INSERT INTO stanza VALUES('CB737','6','Paladmon nato’s krus<br/>Ang ambitayay;<br/>Ginhawa’s Esp’ritu<br/>Mag-usbaw ni’ni.<br/>',NULL,17854,6);
INSERT INTO stanza VALUES('CB737','7','Magpagawas nato<br/>Ang ambitayay,<br/>Gikan’s kaugalingon,<br/>Magda’ nato’s Dios.<br/>',NULL,17855,7);
INSERT INTO stanza VALUES('CB738','1','May pagbati’s kinabuhi<br/>Tanang matang ni’ni;<br/>Kinabuhing dayon’s sulod<br/>May diosnong pagbati.<br/>',NULL,17856,1);
INSERT INTO stanza VALUES('CB738','2','Mas habog nga kinabuhi<br/>Labaw ug pagbati;<br/>Pagbati’s kinabuhi’s Dios<br/>Maoy labing habog.<br/>',NULL,17857,2);
INSERT INTO stanza VALUES('CB738','3','Pagbati’s kinabuhi’s su’d,<br/>Pagbati man sa Dios;<br/>Na’s espiritung gibuhi,<br/>Ang labawng pagbati.<br/>',NULL,17858,3);
INSERT INTO stanza VALUES('CB738','4','Pagbati’s kinasuloran,<br/>Pagkaamgo’s sulod,<br/>Makaila’s mga butang<br/>Ug kabubot-on’s Dios.<br/>',NULL,17859,4);
INSERT INTO stanza VALUES('CB738','5','Ni’ni makaila ta’s Dios,<br/>Sa kinabuhi’s su’d;<br/>Gamhanan ug dihadiha,<br/>Di makigbisug gyud.<br/>',NULL,17860,5);
INSERT INTO stanza VALUES('CB738','6','Sa labi nga pagtubo ta,<br/>Pagbati mokusog.<br/>Labi natong tumanon ni,<br/>Labi pang mokusog.<br/>',NULL,17861,6);
INSERT INTO stanza VALUES('CB738','7','Kon mabansay nang pagbati,<br/>Esp’ritu maisug,<br/>Pakig-ambitayng matuod<br/>Maangkon ta gayud.<br/>',NULL,17862,7);
INSERT INTO stanza VALUES('CB739','1','Kadtong gipanganak sa Ginoo<br/>Sa sulod may datong kahibalo,<br/>Pagtudlo’s gawas wa kin’hanglana,<br/>Apan Dios hingpit mahibal-an ra.<br/>',NULL,17863,1);
INSERT INTO stanza VALUES('CB739','2','Kinabuhing dayon, labing habog,<br/>Dunay hingpit nga diosnong katakus,<br/>Niini makaila ta sa Dios<br/>Labaw pa’s kahibalo sa gawas.<br/>',NULL,17864,2);
INSERT INTO stanza VALUES('CB739','3','Balaod’s kinabuhi gibutang<br/>Sa hunahuna’g kasingkasing ta,<br/>Nagbuot’s sulod, Dios mailhan ta<br/>Labaw pa’s gihatag’s pagtulon-an.<br/>',NULL,17865,3);
INSERT INTO stanza VALUES('CB739','4','Balaang dihog na’s espiritu,<br/>Nagpakita’s mga butang sa Dios;<br/>Niini may kahibalo ta’s Dios<br/>Labaw’s mahatag’s pagtulon-an’s tawo.<br/>',NULL,17866,4);
INSERT INTO stanza VALUES('CB739','5','May Dios nga nagpuyo sa sulod ta,<br/>Naglihok, nagbuhat’s tanang takna,<br/>Sa pagbati gumikan N’ya, ang Dios<br/>Maila’s di matugkad nga sukod.<br/>',NULL,17867,5);
INSERT INTO stanza VALUES('CB739','6','Tungod sa kahibalo ta’s sulod,<br/>Kabatid sa tawo wa kin’hanglana,<br/>Sa espiritu magkinabuhi,<br/>Sa pagbati sa sulod maggawi.<br/>',NULL,17868,6);
INSERT INTO stanza VALUES('CB739','7','Labi tang mabuhi dihang Cristo,<br/>Maggawi sunod’s pagbati’s sulod,<br/>Labing may kahibalong matuod,<br/>Ug ang Anak maumol kanato.<br/>',NULL,17869,7);
INSERT INTO stanza VALUES('CB739','8','Pinaagi’s buhing kahibalo<br/>May pakig-ambitay kita sa Dios;<br/>Sa kahibalong nabatonan ta<br/>Kahupnganan’s Dios ipadayag N’ya.<br/>',NULL,17870,8);
INSERT INTO stanza VALUES('CB740','1','Ang prinsipyo sa pagpakatawo<br/>Pagkasagol sa Dios ug tawo,<br/>Nagbuligay ang Dios ug tawo<br/>Pagtuman’s dayon nga plano.<br/>',NULL,17871,1);
INSERT INTO stanza VALUES('CB740','2','Tawo maoy pagpadayag sa Dios,<br/>Panag-iyahon una N’ya;<br/>Sa dihang maiya na’s bug-os,<br/>Mapadayag na’s tawo ang Dios.<br/>',NULL,17872,2);
INSERT INTO stanza VALUES('CB740','3','Nahuman nang pagtubos sa tawo,<br/>Nagpadayag’s kaalam’s Dios;<br/>Kaluwasan sa tawo gibatbat,<br/>Masayud tanang binuhat.<br/>',NULL,17873,3);
INSERT INTO stanza VALUES('CB740','4','Pagbuhat’s Dios sa pa’tigayon,<br/>Tawo mobuhat gyud uban N’ya;<br/>Dios ug tawo suod ug relasyon;<br/>Magsaligay’s usag usa.<br/>',NULL,17874,4);
INSERT INTO stanza VALUES('CB740','5','Dili Dios mismo m’oy maghago,<br/>Tawo di m’oray mag-alagad;<br/>Dios ug tawo mag-usa’s pagbuhat,<br/>Aron plano N’ya madayag.<br/>',NULL,17875,5);
INSERT INTO stanza VALUES('CB740','6','Ang prinsipyo sa pagpakatawo<br/>Gamiton’s tanang pagbuhat,<br/>Sa tanang gasa’g pag-alagad,<br/>Aron usang mag-alagad.<br/>',NULL,17876,6);
INSERT INTO stanza VALUES('CB741','1','Gitudlo’s Dios’ pagkaanak,<br/>Sa wa pang kabuhatan,<br/>Samahon ta’s Espiritu<br/>Sa dagway sa Anak N’ya;<br/>Aron bugtong Anak Niya<br/>Mahimo nga Panganay,<br/>Uban’s daghang igsoon N’ya<br/>May pagpadayag na S’ya.<br/>',NULL,17877,1);
INSERT INTO stanza VALUES('CB741','2','Sa diosnong pag-anak ta,<br/>Mga anak na sa Dios,<br/>Apan mahamtong gyud aron<br/>May katungod’s panganay.<br/>Gianak, nahamtong’s hingpit,<br/>Mag-ambit’s pagkaanak;<br/>Sa sukod sa pagkahamtong,<br/>Pagka-anak madayag.<br/>',NULL,17878,2);
INSERT INTO stanza VALUES('CB741','3','Lawas, kalag, espiritu,<br/>Masama gyud ni Cristo;<br/>Hingpit kini nga mahuman<br/>Sa pagbalik’s Ginoo.<br/>Sa katubsanan’s lawas ta<br/>Pagkaanak mahingpit;<br/>Katapusang pagtransporma<br/>Makatagbo’s tuyo N’ya.<br/>',NULL,17879,3);
INSERT INTO stanza VALUES('CB741','4','Pagtransporma’s katapusan,<br/>Hingpit tang mabalaan;<br/>Dad-on ta’s Dios sa himaya<br/>Sa Anak N’ya masama.<br/>Pagpadayag’s mga anak<br/>Gihulat’s kabuhatan,<br/>Sa gapos sila magawas<br/>Mahimaya ang lawas.<br/>',NULL,17880,4);
INSERT INTO stanza VALUES('CB742','1','Lawas, kalag ug esp’ritu,<br/>Maoy tulo ka bahin’s tawo,<br/>Pagtuman’s tuyo nga diosnon,<br/>Panulondon’s Dios m’oy tumong.<br/>',NULL,17881,1);
INSERT INTO stanza VALUES('CB742','2','Ang lawas m’oy naa’s gawas,<br/>Aron ang tawo may pamatyag,<br/>Pagtandog sa mga butang<br/>Nga naa sa kalibutan.<br/>',NULL,17882,2);
INSERT INTO stanza VALUES('CB742','3','Ang kalag m’oy naa’s sulod,<br/>Maoy kaugalingon’s tawo;<br/>May pagbati’s kaugalingon,<br/>Sa kalibutang kalagnon.<br/>',NULL,17883,3);
INSERT INTO stanza VALUES('CB742','4','Esp’ritu’s kinasuloran,<br/>M’oy inugdawat n’yang Cristo;<br/>Dinhi mabati n’ya ang Dios,<br/>Masabtan butang’s esp’ritu.<br/>',NULL,17884,4);
INSERT INTO stanza VALUES('CB742','5','Diha’s kalag sa tawo naay<br/>Hunahuna, pagbati’g pagbuot,<br/>Mga kagamitan sa tawo,<br/>Nga magtuman’s ’yang pagkatawo.<br/>',NULL,17885,5);
INSERT INTO stanza VALUES('CB742','6','Sulod’s espiritu sa tawo<br/>May konsensya’g pakig-ambit;<br/>Ug direkta nga pagbati;<br/>M’oy isimba’s Dios sa hingpit.<br/>',NULL,17886,6);
INSERT INTO stanza VALUES('CB742','7','Kalag mopili gyud sa Dios,<br/>Aron ang Dios maiyaha;<br/>Dios dawaton’s espiritu,<br/>Ug sa lawas ipadayag S’ya.<br/>',NULL,17887,7);
INSERT INTO stanza VALUES('CB742','8','Esp’ritu ianak pag-usab,<br/>Hatagan’s kinabuhing diosnon;<br/>Kalag n’ya sa Dios kambyohon,<br/>Lawas n’ya masama’s kang Cristo.<br/>',NULL,17888,8);
INSERT INTO stanza VALUES('CB742','9','Ning mga lakang’s buhat’s Dios,<br/>Sa tulo ka bahin sa tawo<br/>Tawo masagol sa Ginoo<br/>Ug magpadayag N’ya’s bug-os.<br/>',NULL,17889,9);
INSERT INTO stanza VALUES('CB743','1','Gibuhat tang sudlanan’s Dios,<br/>Magpadayag’s tanan N’ya;<br/>Kasingkasing mahigugma,<br/>Esp’ritu modawat N’ya.<br/>',NULL,17890,1);
INSERT INTO stanza VALUES('CB743','2','Mahalon S’ya’s kasingkasing,<br/>Angkonon’s espiritu,<br/>Kinabuhi S’yang ambitan,<br/>Aron mapadayag S’ya.<br/>',NULL,17891,2);
INSERT INTO stanza VALUES('CB743','3','Gidaut ta sa kaaway,<br/>Espiritu gipatay,<br/>Aron Dios di ta makontak,<br/>Mabuhi’s atong kalag.<br/>',NULL,17892,3);
INSERT INTO stanza VALUES('CB743','4','Kasingkasing, espiritu,<br/>Sa kal’wasan gibag-o;<br/>Naulian, makadawat,<br/>Mahigugma’s Ginoo.<br/>',NULL,17893,4);
INSERT INTO stanza VALUES('CB743','5','Nabag-ong kasingkasing ta,<br/>Makatinguha na N’ya;<br/>Sa kabag-o’s espiritu,<br/>Dios makontak na nato.<br/>',NULL,17894,5);
INSERT INTO stanza VALUES('CB743','6','Tinuod, putli, hugot gyud<br/>Kasingkasing ta sa Dios,<br/>Kabus ug esp’ritu nga<br/>Mangita’g mokontak’s Dios.<br/>',NULL,17895,6);
INSERT INTO stanza VALUES('CB743','7','Ampinging kasingkasing ko,<br/>Lig-onang espiritu,<br/>Aron sigeng kontak Nimo<br/>Sa kabag-o’s esp’ritu.<br/>',NULL,17896,7);
INSERT INTO stanza VALUES('CB744','1','Kasingkasing tarungon ta’s,<br/>Pagtagad nato N’ya,<br/>Aron makaambit kita’s<br/>Kadato’g grasya N’ya.<br/>',NULL,17897,1);
INSERT INTO stanza VALUES('CB744','2','Nagkinahanglan gyud kita’g,<br/>Putling kasingkasing,<br/>Himsog, tin-awng hunahuna,<br/>Nga makasabut N’ya.<br/>',NULL,17898,2);
INSERT INTO stanza VALUES('CB744','3','Kasingkasing mapanggaon,<br/>Ang kinahanglan ta;<br/>Mainiton labaw’s tanan,<br/>Alang gayud Niya.<br/>',NULL,17899,3);
INSERT INTO stanza VALUES('CB744','4','Kasingkasing masugtanon,<br/>Ug mapasakupon,<br/>Humok, apan malig-on sab,<br/>Motuman’s tuyo N’ya.<br/>',NULL,17900,4);
INSERT INTO stanza VALUES('CB744','5','Kasingkasing way pagtuto,<br/>Sa Dios tanan husto;<br/>Nga may konsensyang nahinlo,<br/>Tinabonan’s dugo.<br/>',NULL,17901,5);
INSERT INTO stanza VALUES('CB744','6','Kasingkasing ingon ni’ni<br/>Karon hatagi mi,<br/>Ikawng tumong nga ambitan,<br/>Makahupnganan mi.<br/>',NULL,17902,6);
INSERT INTO stanza VALUES('CB745','1','Espiritu Ikaw karon,<br/>Nia’s espiritu,<br/>Ang duha ka espiritu<br/>Karon nahiusa.<br/>',NULL,17903,1);
INSERT INTO stanza VALUES('CB745','2','Ang duha ka espiritu<br/>Maoy nagmatuod<br/>Nga kami mga anak’s Dios,<br/>Iyang manununod.<br/>',NULL,17904,2);
INSERT INTO stanza VALUES('CB745','3','Kontakon Ka’s espiritu,<br/>Mapahimuslan Ka,<br/>Espiritu Kang naghatag’s<br/>Kaugalingon Mo.<br/>',NULL,17905,3);
INSERT INTO stanza VALUES('CB745','4','Makagawi mi’s esp’ritu,<br/>Sige’g sunod Nimo;<br/>Espiritu Kang manguna,<br/>Sigeng maghayag Ka.<br/>',NULL,17906,4);
INSERT INTO stanza VALUES('CB745','5','Sa espiritu, Ginoo,<br/>Simbahon Ka namo;<br/>Diha’s among espiritu<br/>Kami lig-onon Mo.<br/>',NULL,17907,5);
INSERT INTO stanza VALUES('CB745','6','Uban sa Espiritu Mo<br/>Nag-ampo mi Nimo,<br/>Esp’ritu Kang niagulo,<br/>Di maasoy’s sulod.<br/>',NULL,17908,6);
INSERT INTO stanza VALUES('CB745','7','Mobalik mi’s espiritu,<br/>Kontakon Ka didto;<br/>Sa esp’ritu maambitan<br/>Diosnong panulondon.<br/>',NULL,17909,7);
INSERT INTO stanza VALUES('CB745','8','Kining duhang espiritu<br/>Nausa pag-ayo!<br/>Nabuhing Espiritu Mo’s<br/>Among espiritu.<br/>',NULL,17910,8);
INSERT INTO stanza VALUES('CB746','1','Kalainan’s kalag, espiritu,<br/>Pailha kami, Ginoo;<br/>Espiritu Ka’s espiritu,<br/>Nausa, nasagol namo.<br/>',NULL,17911,1);
INSERT INTO stanza VALUES('CB746','2','Kalag dumilian na namo,<br/>Pailha mi’s espiritu;<br/>Magsunod Nimo’s espiritu,<br/>I-apply’ng Kaugalingon Mo.<br/>',NULL,17912,2);
INSERT INTO stanza VALUES('CB746','3','Pailha kami’s espiritu,<br/>Hunahuna di itumong<br/>Sa unod, kondi’s espiritu,<br/>Di magapos kaugalingon.<br/>',NULL,17913,3);
INSERT INTO stanza VALUES('CB746','4','Pailha kami’s espiritu,<br/>Aron di mi makalagnon;<br/>Maesp’rituhanon hinoon<br/>Kami’s tanan nga panahon.<br/>',NULL,17914,4);
INSERT INTO stanza VALUES('CB746','5','Pailha kami’s espiritu,<br/>Kaugalingon mabutyag gyud;<br/>Krus i-apply sa kaugalingon,<br/>Di mabuhi’s kaugalingon.<br/>',NULL,17915,5);
INSERT INTO stanza VALUES('CB746','6','Pailha kami’s espiritu,<br/>Matranspormang kalag namo,<br/>Hangtud masama mi’s dagway Mo,<br/>Mahamtong pagkab-ot’s tumong.<br/>',NULL,17916,6);
INSERT INTO stanza VALUES('CB746','7','Pailha kami’s espiritu,<br/>Hatagi’s buhing pulong Mo,<br/>Mabahing kalag’s espiritu,<br/>Sa labing balaan magpuyo.<br/>',NULL,17917,7);
INSERT INTO stanza VALUES('CB747','1','Labing balaan’s templo’s Dios,<br/>M’oy labing kinasuloran;<br/>Didtong arka’g presensya N’ya,<br/>Matagbo’s sacerdote S’ya.<br/>',NULL,17918,1);
INSERT INTO stanza VALUES('CB747','2','Templo kitang tuloy parte,<br/>Kinasulorang esp’ritu;<br/>Didto Cristo’g Dios nagpuyo,<br/>Ning dapit labing balaan.<br/>',NULL,17919,2);
INSERT INTO stanza VALUES('CB747','3','Ning kinasulorang dapit,<br/>Dios kang Cristo tanan nato,<br/>Dinhi usab Espiritu,<br/>Naghimo N’yang realidad.<br/>',NULL,17920,3);
INSERT INTO stanza VALUES('CB747','4','Sulod ni’ning espiritu,<br/>Makontak nato si Cristo;<br/>Sa esp’ritu ta uban S’ya,<br/>May pakig-ambitay kita.<br/>',NULL,17921,4);
INSERT INTO stanza VALUES('CB747','5','Dinhi sama Siya’s yuta,<br/>Mapuy-an, mapahimuslan;<br/>Dinhi awayon tang yawa,<br/>Gamiton ’yang pagbulot-an.<br/>',NULL,17922,5);
INSERT INTO stanza VALUES('CB747','6','Esp’ritu ila-ilahon,<br/>Maila kini sa kalag,<br/>Magpuyo’s labing balaan;<br/>Dios simbahon ug m’oy tumong.<br/>',NULL,17923,6);
INSERT INTO stanza VALUES('CB747','7','Ang kalag ta isalikway,<br/>Padayon, sudlong pahulay;<br/>Cristo mapanag-iya ta,<br/>Matuman ang plano Niya.<br/>',NULL,17924,7);
INSERT INTO stanza VALUES('CB749','1','Espiritu sa Trinidad<br/>Nagpuyo’s atong esp’ritu;<br/>Nagtinguha nga moawas,<br/>Mapadayag dihang Cristo.<br/>',NULL,17925,1);
INSERT INTO stanza VALUES('CB749','2','Apan nasirhan’s tawo’s gawas<br/>Ang Espiritung na’s sulod;<br/>Imbis balay unta ta N’ya,<br/>Prisohan man hinoon ta.<br/>',NULL,17926,2);
INSERT INTO stanza VALUES('CB749','3','Sama S’ya’s bahanding mahal,<br/>Gisulod’s yutang sudlanan;<br/>Buk-on gyud kay kinahanglan,<br/>Bahandi makit-an’s tanan.<br/>',NULL,17927,3);
INSERT INTO stanza VALUES('CB749','4','Kaugalingon ta dugmokon,<br/>Kay tawo’s gawas ta nagsampong;<br/>Hingpit gayud nga dugmokon,<br/>Esp’ritu magawas dayon.<br/>',NULL,17928,4);
INSERT INTO stanza VALUES('CB749','5','Mao kini ang hinungdan,<br/>Lisud usahay dangatan;<br/>Kay niini dugmokon man,<br/>Ang tawo sa gawas batokan.<br/>',NULL,17929,5);
INSERT INTO stanza VALUES('CB749','6','Tawo’s gawas—daang kalag,<br/>Ut-uton, kunhuron gayud;<br/>Espiritu—tawo’s sulod,<br/>Makagawas uban Niya.<br/>',NULL,17930,6);
INSERT INTO stanza VALUES('CB749','7','Hatagan unta’s pagdugmok,<br/>L’wasa ko’s pagkatibuok,<br/>Andam modawat sa samad<br/>Nga ihatag Mo’s kalag ko.<br/>',NULL,17931,7);
INSERT INTO stanza VALUES('CB749','8','Mahalon kong pagdugmok Mo,<br/>Dili gayud moreklamo;<br/>Tamdan ko ang kapildehan,<br/>Labaw’s tanang kaayohan.<br/>',NULL,17932,8);
INSERT INTO stanza VALUES('CB750','1','Tuyo sa Dios samahon ta<br/>Sa pinanggang Anak N’ya;<br/>Buhat N’ya sa pagtransporma<br/>Buhaton’s Espiritu.<br/>',NULL,17933,1);
INSERT INTO stanza VALUES('CB750','chorus','Matag bahin’s kalag namo<br/>Transpormaha’s dagway Mo;<br/>Suropi’s Espiritu Mo,<br/>Pun-ang tibu’k pagkatawo.<br/>',NULL,17934,2);
INSERT INTO stanza VALUES('CB750','2','Gianak ta N’ya pag-usab<br/>Diha’s espiritu ta;<br/>Apan transpormahon pa gyung<br/>Kalag’s kinabuhi N’ya.<br/>',NULL,17935,3);
INSERT INTO stanza VALUES('CB750','3','Gikan’s esp’ritu mokaylap<br/>Magtransporma’s kalag ta,<br/>Sulodnong bahin bag-ohon,<br/>Hangtud makontrol Niya.<br/>',NULL,17936,4);
INSERT INTO stanza VALUES('CB750','4','Sa gahum’s Espiritu N’ya<br/>Sa dagway N’ya umolon;<br/>Gikan’s himaya ngadto’s himaya<br/>Sa dagway N’ya masama.<br/>',NULL,17937,5);
INSERT INTO stanza VALUES('CB750','5','Padayong magbalaan S’ya,<br/>Hangtud mahamtong kita;<br/>Kalag ta mapanag-iya,<br/>Ensaktong gidak-on N’ya.<br/>',NULL,17938,6);
INSERT INTO stanza VALUES('CB751','1','Di’s pagpanlimbasug,<br/>Kondi’s pagtugyan,<br/>Makapahulay ko<br/>Sa pangabudlay.<br/>Di’s pagbuot-buot<br/>Kondi’s pagsugot,<br/>Makagawas’ sala,<br/>Magawas’ gapos.<br/>',NULL,17939,1);
INSERT INTO stanza VALUES('CB751','2','Di sa letra, kondi’<br/>Sa Espiritu,<br/>Mahimut-an sa Dios;<br/>Ako mabuhi.<br/>Di’s mga pagtudlo,<br/>Kondi’s dihog Mo,<br/>Madan-agan ko ug<br/>Makaambitay.<br/>',NULL,17940,2);
INSERT INTO stanza VALUES('CB751','3','Di’s pagbuot ko nga<br/>Modagan’s lumba,<br/>Kondi’s kaluoy Mo<br/>Grasya madawat.<br/>Di sa kahibalo,<br/>Kondi’s grasya ra,<br/>Makalatas’ pait,<br/>Nimo masama.<br/>',NULL,17941,3);
INSERT INTO stanza VALUES('CB751','4','Di sa mga pulong,<br/>Kondi’s gahum Mo,<br/>Makag’ya’s nasaag<br/>Sa kinabuhi’s Dios.<br/>Di sa kaalam ko,<br/>Kondi’s Esp’ritu,<br/>Maghaum nako’s<br/>Pagtuman’s Pulong Mo.<br/>',NULL,17942,4);
INSERT INTO stanza VALUES('CB762','1','Pag-ampo incienso’s kasingkasing,<br/>Gikan’s nasamdan, dugmok nga butang;<br/>Gipasiga’s sunog’s Espiritu,<br/>Ug gilupad sa atong pagtoo.<br/>',NULL,17943,1);
INSERT INTO stanza VALUES('CB762','2','Pag-ampo alimyon’s tanom’s grasya,<br/>Bulak’s pailub, pagtoo’g gugma;<br/>Gitipigan’s “garapa’s incenso,“<br/>Gihanggap gayud’s atong Ginoo.<br/>',NULL,17944,2);
INSERT INTO stanza VALUES('CB762','3','Pag-ampo maoy asong nagsangkap’s<br/>Ulan’s panalangin, agay’s sapa<br/>Ngadto’s kamad-an, hangtud ang tanan<br/>Daw rosas mamuwak’s kamingawan.<br/>',NULL,17945,3);
INSERT INTO stanza VALUES('CB762','4','Pag-ampo m’oy telepono nato,<br/>Sa langit sa yuta magpaduol;<br/>Sa igdulongog, kasingkasing N’ya,<br/>Isulting luwan ta ug kaguol.<br/>',NULL,17946,4);
INSERT INTO stanza VALUES('CB762','5','Pag-ampo telegramang magdala,<br/>Sa pinitik’s dughan’s kalangitan;<br/>Inigtandog’s kasingkasing sa Dios,<br/>Tubag magdasig’s pagtoo’g gugma.<br/>',NULL,17947,5);
INSERT INTO stanza VALUES('CB762','6','Pag-ampo m’oy tubo’s Espiritu,<br/>Nagsangkap ug lana sa suga’s Dios;<br/>Samtang usa kita nga mag-ampo,<br/>Pun-on’s Esp’ritu, suga magsiga.<br/>',NULL,17948,6);
INSERT INTO stanza VALUES('CB762','7','Labing dakong kusog’s yuta’g langit,<br/>Pag-ampo dinamita’s atong Dios;<br/>Sa tanang butang m’oy magpalihok,<br/>Sa buhing mga ligid mag’tuyok.<br/>',NULL,17949,7);
INSERT INTO stanza VALUES('CB762','8','Tudloi’s pag-ampo, dasiga mi!<br/>Paampoa mi’s Imong pagbati!<br/>Hangtud Cristo’s sulod m’oy mag-ampo<br/>Ni Cristo nga naa sa itaas!<br/>',NULL,17950,8);
INSERT INTO stanza VALUES('CB762','9','Padaygi kami’s kabubut-on Mo,<br/>Hangtud matandog tib’uk pagkatawo!<br/>Pag-ampo namo mahimong tubag’s<br/>Dios sa sulod sa Dios sa itaas!<br/>',NULL,17951,9);
INSERT INTO stanza VALUES('CB764','1','Sa presensya Mo maghilom ako,<br/>Sa kahiladman moduol Nimo;<br/>Mag-ampo dili sa paagi ko,<br/>Pag-ampo Mo maoy pag-ampo ko.<br/>',NULL,17952,1);
INSERT INTO stanza VALUES('CB764','2','Morag naminaw Ka nako’s langit,<br/>Apan’s esp’ritu ko nagpuyo Ka;<br/>M’orag nag-ampo ko nganha Nimo,<br/>Ikaw diayng nag-ampo’s esp’ritu.<br/>',NULL,17953,2);
INSERT INTO stanza VALUES('CB764','3','Kon way pulong makaasoy’s luwan,<br/>Espiritu mag-agulo’s sulod;<br/>Di sa pulong isulti kong hangyo<br/>Kondi’s ampo Mong di ikaasoy.<br/>',NULL,17954,3);
INSERT INTO stanza VALUES('CB764','4','Ginhawaon ko Ikaw, Ginoo,<br/>Kan-on, imnon ingon nga sangkap ko.<br/>Lalum pang ambitayay ihatag,<br/>Aron kanako Ikaw madayag.<br/>',NULL,17955,4);
INSERT INTO stanza VALUES('CB764','5','Sa pakig-ambitay naghayag Ka,<br/>Sa dugo Mo gihinloan gyud ko;<br/>Kahayag Mo di lang mahalon ko,<br/>Madayag gyud Ka, tin-awng makita.<br/>',NULL,17956,5);
INSERT INTO stanza VALUES('CB764','6','Lana Mo nagdihog’s tanang bahin,<br/>Way hunong nga gidihog Ka’s sulod;<br/>Mokunhod Ko, magsige Ka’g tubo,<br/>Hingpit Kang madayag dinhi nako.<br/>',NULL,17957,6);
INSERT INTO stanza VALUES('CB764','7','Kaugalingon buksan, mosulod Ka;<br/>Buksan alang’s uban, moagay Ka;<br/>Nianang sulog, pag-ambitay’s sulod,<br/>Madayag Ka nga kinabuhi ko.<br/>',NULL,17958,7);
INSERT INTO stanza VALUES('CB767','1','Tudloi mi sa pag-ampo,<br/>Pag-abog’s kaaway,<br/>Paggapos n’ya, pagbuhi sa<br/>Binilanggo niya.<br/>',NULL,17959,1);
INSERT INTO stanza VALUES('CB767','2','Tudloi mi sa pag-ampo,<br/>Malig-ong magbarug,<br/>Pagsulong-gun-ob’s ’yang kuta,<br/>Kaaway mahadlok.<br/>',NULL,17960,2);
INSERT INTO stanza VALUES('CB767','3','Tudloi paggamit’s sungkod’s<br/>Madaugong ampo,<br/>Sa dugo Mo uyogon gyud<br/>Gahum’s kahanginan.<br/>',NULL,17961,3);
INSERT INTO stanza VALUES('CB767','4','Sa pag-ampo ug pagtoo<br/>Mobulig Kanimo,<br/>Kadaugan, pagbulot-an<br/>Amoa nang tanan.<br/>',NULL,17962,4);
INSERT INTO stanza VALUES('CB769','1','Mosu’d’s labing balaan,<br/>Sulod’s tabil molabang;<br/>Motandog’s trono’s grasya,<br/>Agayan’s kinabuhi.<br/>',NULL,17963,1);
INSERT INTO stanza VALUES('CB769','2','Dapit labing balaan<br/>Naa’s espiritu ko;<br/>Uban nakong Ginoo,<br/>Nausa’s esp’ritu ko.<br/>',NULL,17964,2);
INSERT INTO stanza VALUES('CB769','3','Mobalik’s espiritu<br/>S’ya matagbo ko didto;<br/>O katingad-an kini!<br/>Nia S’ya sa sulod ko.<br/>',NULL,17965,3);
INSERT INTO stanza VALUES('CB769','4','Humot’s nabanhawng Cristo<br/>Mokatap’s espiritu;<br/>Kon mag-ampo’s esp’ritu,<br/>Mapasundayag’s Cristo.<br/>',NULL,17966,4);
INSERT INTO stanza VALUES('CB769','5','Kon matandog ko Siya,<br/>Mapuno’s kadato N’ya;<br/>Kinabuhi, kahayag,<br/>Gugma’g grasya moagay.<br/>',NULL,17967,5);
INSERT INTO stanza VALUES('CB769','6','Kon matandog S’ya’s sulod,<br/>Dato S’yang masinati;<br/>Balaod’s kinabuhi<br/>Tin-aw gyud nga mabati.<br/>',NULL,17968,6);
INSERT INTO stanza VALUES('CB769','7','Lalum’s espiritu ko<br/>Matandog kong Ginoo,<br/>Sa kinahiladman gyud<br/>Ug manna N’yang tinago.<br/>',NULL,17969,7);
INSERT INTO stanza VALUES('CB769','8','Kon ang kinabuhi N’ya<br/>Mamatuod na nako,<br/>Manalingsing daw sungkod,<br/>Mahinangponon ko’s Dios.<br/>',NULL,17970,8);
INSERT INTO stanza VALUES('CB769','9','Ania’s trono’s grasya,<br/>Buhing tubig nag-agay,<br/>Suba nga puno’s grasya<br/>Maghatag nako’s grasya.<br/>',NULL,17971,9);
INSERT INTO stanza VALUES('CB769','10','Matag tigum’s pag-ampo,<br/>Hubarang espiritu;<br/>Espiritu masagol,<br/>Sacerdoteng magsilbe.<br/>',NULL,17972,10);
INSERT INTO stanza VALUES('CB769','11','Dinhi’s labing balaan<br/>Makatandog tang tanan<br/>Sa Ginoo’g trono N’ya<br/>Hangtud buboan’s grasya.<br/>',NULL,17973,11);
INSERT INTO stanza VALUES('CB770','1','Sudlon ta karon, labing balaan,<br/>Trono sa grasya tandogon;<br/>Sudlon ta karon, labing balaan,<br/>Grasya daw suba moagay.<br/>',NULL,17974,1);
INSERT INTO stanza VALUES('CB770','chorus','Hallelujah! Hallelujah!<br/>Grasya daw suba moagay;<br/>Hallelujah! Hallelujah!<br/>Grasya daw suba moagay.<br/>',NULL,17975,2);
INSERT INTO stanza VALUES('CB770','2','Mabuhi’s atubangan’s nawong N’ya,<br/>Himaya mosidlak nako;<br/>Mabuhi’s atubangan’s nawong N’ya,<br/>Himaya mosidlak nako.<br/>',NULL,17976,3);
INSERT INTO stanza VALUES('CB770','chorus','Hallelujah! Hallelujah!<br/>Himaya mosidlak nako;<br/>Hallelujah! Hallelujah!<br/>Himaya mosidlak nako!<br/>',NULL,17977,4);
INSERT INTO stanza VALUES('CB770','3','Liso’s esp’ritu, sunog’s incienso,<br/>Tandogang buhi nga tubod;<br/>Liso’s esp’ritu, sunog’s incienso,<br/>Tandogang buhi nga tubod.<br/>',NULL,17978,5);
INSERT INTO stanza VALUES('CB770','chorus','Hallelujah! Hallelujah!<br/>Tandogang buhi nga tubod;<br/>Hallelujah! Hallelujah!<br/>Tandogang buhi nga tubod!<br/>',NULL,17979,6);
INSERT INTO stanza VALUES('CB771','1','O nagisi na ang tabil,<br/>Nabuksan nang dalan;<br/>Makaduol tungod’s dugo,<br/>Kami makaampo.<br/>',NULL,17980,1);
INSERT INTO stanza VALUES('CB771','2','Pagtubos Mo nakaduol<br/>Sa labing balaan;<br/>Espiritu Mo magdihog,<br/>Sa trono magtandog.<br/>',NULL,17981,2);
INSERT INTO stanza VALUES('CB771','3','Sa espiritu mag-ampo,<br/>Batonan mi Nimo,<br/>Aron si Cristo incienso<br/>Nga moabot’s trono.<br/>',NULL,17982,3);
INSERT INTO stanza VALUES('CB771','4','Grasya’g kaluoy daw sapa,<br/>Niagay sa trono,<br/>Tabang ta sa matag takna,<br/>Pagkatam-is, dato.<br/>',NULL,17983,4);
INSERT INTO stanza VALUES('CB771','5','Bisan’s butang di mangayo,<br/>Sundong Espiritu;<br/>Nasayud Ka’s kinahanglan,<br/>Kanamo mag-andam.<br/>',NULL,17984,5);
INSERT INTO stanza VALUES('CB771','6','Dili mahasol bisan pa’g<br/>Dunay kasub-anan,<br/>Isang-at man Nimong tanan,<br/>Kami mahubaran.<br/>',NULL,17985,6);
INSERT INTO stanza VALUES('CB771','7','Makig-ambitay Kanimo<br/>Sa bug-os kong kalag;<br/>Giyahi sa Espiritu<br/>Pagsunog’s incienso.<br/>',NULL,17986,7);
INSERT INTO stanza VALUES('CB772','1','Nagtigum mi, Ginoo,<br/>Naghiusa’s pag-ampo;<br/>Mga sacerdote Mo,<br/>Naghulat karon Nimo.<br/>',NULL,17987,1);
INSERT INTO stanza VALUES('CB772','chorus','Usa dinhing nag-ampo,<br/>Nagtandog’s labing ma’yo,<br/>Espiritu masagol,<br/>Iglesia Mo matukod.<br/>',NULL,17988,2);
INSERT INTO stanza VALUES('CB772','2','Sacerdoteng tinuod,<br/>Mobati’s pagbuot Mo,<br/>Mag-alagad Kanimo,<br/>Magtuman’s Imong plano.<br/>',NULL,17989,3);
INSERT INTO stanza VALUES('CB772','3','Labing balaan sudlon,<br/>Trono’s grasya tandogon,<br/>Pagbati’s su’d i-ampo,<br/>Subay sa Espiritu.<br/>',NULL,17990,4);
INSERT INTO stanza VALUES('CB772','4','Gikan’s trono’s grasya Mo<br/>Suba’s grasya mogula;<br/>Maglunhaw’s espiritu,<br/>Tabang’s kinahanglan ko.<br/>',NULL,17991,5);
INSERT INTO stanza VALUES('CB772','5','Pag-ampo unta namo,<br/>Pahayag’s Espiritu,<br/>Dili’s among tinguha,<br/>Kondi’ suma’s Imoha.<br/>',NULL,17992,6);
INSERT INTO stanza VALUES('CB772','6','Bisa’g daghan ang buhat,<br/>Kinahanglan i-ampo;<br/>Apan palabihon ko<br/>Mahimong sandayong Mo.<br/>',NULL,17993,7);
INSERT INTO stanza VALUES('CB772','7','Pamation Mo unta,<br/>Buhing tubig ihatag;<br/>Kon tagbawon’s grasya Mo,<br/>Maila nang buhat Mo.<br/>',NULL,17994,8);
INSERT INTO stanza VALUES('CB775','1','Sa gamhanang Ngalang Jesus,<br/>Moyukbo’s Imong trono;<br/>Daghang kaaway gipatay,<br/>Daghang away gidaug.<br/>',NULL,17995,1);
INSERT INTO stanza VALUES('CB775','chorus','Ngalan nga gamhanan!<br/>Kini m’oy kadaugan!<br/>Sala’g kamatayon,<br/>Gidaug N’ya sa dayon.<br/>',NULL,17996,2);
INSERT INTO stanza VALUES('CB775','2','Pangamuyo’s Ngalang Jesus,<br/>Mokagiw gyung kaaway.<br/>Jesus! Jesus nga Bililhon!<br/>Ngalan Mo kadaugan.<br/>',NULL,17997,3);
INSERT INTO stanza VALUES('CB775','3','Di na madugay ang takna,<br/>Modaug na ta’s gubat,<br/>Kon Gamhanang Ngalang Jesus<br/>Magtuboy nato’s trono.<br/>',NULL,17998,4);
INSERT INTO stanza VALUES('CB778','1','Awit sa pagsalig<br/>Bisan dulom’ng langit;<br/>Kay sa pagdayeg Dios mobuhat,<br/>Aron mangatuman<br/>Tanang gisaligan.<br/>',NULL,17999,1);
INSERT INTO stanza VALUES('CB778','2','Awit sa pagsalig,<br/>Ikaw magmalig-on,<br/>Kay ang Dios ta mahimuot,<br/>Kon pagsalig makadayeg<br/>Bisan dugayng gabii.<br/>',NULL,18000,2);
INSERT INTO stanza VALUES('CB778','3','Awit sa pagsalig,<br/>Kaaway mokagiw;<br/>Ayaw’g hunongang pag-awit,<br/>Pagdaug mang pagdayeg,<br/>Pagdaug mang pagdayeg.<br/>',NULL,18001,3);
INSERT INTO stanza VALUES('CB778','4','Awit sa pagsalig,<br/>Adlaw mosubang na,<br/>Mosugat ta sa Ginoo,<br/>Ug moapil’s awit<br/>Nga way katapusan.<br/>',NULL,18002,4);
INSERT INTO stanza VALUES('CB779','1','Usang mag-ampo’s esp’ritu,<br/>Di segun’s hunahuna;<br/>Sa dihog ra unta Niya,<br/>Sama’s ’yang gitinguha.<br/>',NULL,18003,1);
INSERT INTO stanza VALUES('CB779','chorus','Usang mag-ampo’s esp’ritu,<br/>Di segun’s hunahuna,<br/>Sa dihog ra unta Niya,<br/>Sama’s ’yang gitinguha.<br/>',NULL,18004,2);
INSERT INTO stanza VALUES('CB779','2','Usang mag-ampo’s esp’ritu,<br/>Did-an ang kalag sa krus,<br/>Tanang tuyo ug tinguha,<br/>Espiritu pabut-on.<br/>',NULL,18005,3);
INSERT INTO stanza VALUES('CB779','3','Usang mag-ampo’s esp’ritu,<br/>Daw naa’s kalangitan,<br/>Tumban tinguhang yutan-on,<br/>Pamunoan awayon.<br/>',NULL,18006,4);
INSERT INTO stanza VALUES('CB779','4','Usang mag-ampo’s esp’ritu,<br/>Alang sa usag usa;<br/>Pangitaon ’yang paggiya,<br/>Uyon sa Espiritu.<br/>',NULL,18007,5);
INSERT INTO stanza VALUES('CB779','5','Usang mag-ampo’s esp’ritu,<br/>Sa pagtukaw padayon;<br/>Alang’s Iyang gingharian,<br/>Sa pag-ampo mag-uyon.<br/>',NULL,18008,6);
INSERT INTO stanza VALUES('CB779','6','Usang mag-ampo’s esp’ritu,<br/>Usang mangita sa Dios;<br/>Sa Espiritu sa Lawas,<br/>Mag-uyon sa pag-ampo.<br/>',NULL,18009,7);
INSERT INTO stanza VALUES('CB780','1','Mag-ampo gyud’s espiritu,<br/>Di gyud’s unod, pangisip!<br/>Kon buhaton ning sekreto,<br/>Mapalgang presensya N’ya.<br/>',NULL,18010,1);
INSERT INTO stanza VALUES('CB780','chorus','Mag-ampo gyud’s espiritu,<br/>Kini maoy sekreto;<br/>Ang Dios kanunayng makontak<br/>Hawiran tang sekreto.<br/>',NULL,18011,2);
INSERT INTO stanza VALUES('CB780','2','Mag-ampo gyud’s espiritu,<br/>Dili’s hunahuna ta!<br/>Pakig-ambit’s Espiritu,<br/>S’ya kanato madala.<br/>',NULL,18012,3);
INSERT INTO stanza VALUES('CB780','3','Mag-ampo gyud’s espiritu,<br/>Magpadayag’s tuyo N’ya,<br/>Puyo uban N’ya’s esp’ritu,<br/>Magdilaab gyud kita.<br/>',NULL,18013,4);
INSERT INTO stanza VALUES('CB780','4','Mag-ampo gyud’s espiritu,<br/>Sa sulod mag-agulo,<br/>Sa pagpanton’s Espiritu<br/>Makaampo’s ’yang tuyo.<br/>',NULL,18014,5);
INSERT INTO stanza VALUES('CB780','5','Mag-ampo gyud’s espiritu’s<br/>Dapit labing balaan;<br/>Dinhi lamang’s espiritu,<br/>Mausa ang Dios ug tawo.<br/>',NULL,18015,6);
INSERT INTO stanza VALUES('CB780','6','Mag-ampo gyud’s espiritu,<br/>Maoy bugtong paagi;<br/>Kahupnganan’s Dios maambitan,<br/>Kon kini makat-onan.<br/>',NULL,18016,7);
INSERT INTO stanza VALUES('CB781','1','Bansayong esp’ritu,<br/>Nga mag-ampo gyud!<br/>Gamay’g inampoan,<br/>Hinay’g pamatyag.<br/>Bisag nag-ampo ko,<br/>Esp’ritu way labut,<br/>Magsunod gyud unta’s<br/>Lihok’s Esp’ritu.<br/>',NULL,18017,1);
INSERT INTO stanza VALUES('CB781','2','Ampo na’s esp’ritu,<br/>Uyon’s agulo,<br/>Ampo subay’s dihog,<br/>Di’s nadumdoman.<br/>Di sa hunahuna,<br/>Kondi’s esp’ritu,<br/>Pagdayeg, pangamuyo,<br/>G’yahan’s Esp’ritu.<br/>',NULL,18018,2);
INSERT INTO stanza VALUES('CB781','3','Magbansay’s esp’ritu<br/>Nga di ako ra,<br/>Ampo uban’s uban<br/>Buhaton ko sab.<br/>Ampo’s espiritu,<br/>Subay’s esp’ritu,<br/>Kay na’s kinasuloran<br/>Tubag’s esp’ritu.<br/>',NULL,18019,3);
INSERT INTO stanza VALUES('CB781','4','Ubang mag-alagad,<br/>Molihok’s ampo,<br/>Ambitay’s esp’ritu,<br/>Di sa pulong ra.<br/>Di mag-usa’g ampo,<br/>Tuaw nagdaghan,<br/>Apan wa gyuy ambitay<br/>Diha’s esp’ritu.<br/>',NULL,18020,4);
INSERT INTO stanza VALUES('CB781','5','Bansayong esp’ritu<br/>Bisan asa ta,<br/>Diyutay’g daghang tawo ba,<br/>Kinsay kauban.<br/>Di mag-impluwensya<br/>Dapit ba’g tawo,<br/>Esp’ritu hubaran<br/>Sa tanang tigum.<br/>',NULL,18021,5);
INSERT INTO stanza VALUES('CB781','6','Esp’ritung naisa,<br/>Makabuhat S’ya;<br/>Malig-ong esp’ritu,<br/>Magamit ko N’ya.<br/>Makitang nag-agay<br/>Ang buhing tubig;<br/>Sagolay’s balaan,<br/>Iglesia matukod.<br/>',NULL,18022,6);
INSERT INTO stanza VALUES('CB782','1','Misteryoso, Ginoo,<br/>Esp’ritu Mo nagpuyo<br/>Sulod’s espiritu ko,<br/>Nagkausa pag-ayo.<br/>',NULL,18023,1);
INSERT INTO stanza VALUES('CB782','2','Maggawi’s espiritu,<br/>Maespirituhanon;<br/>Ni’ni mag-alagad ko<br/>Ug magsimba Kanimo.<br/>',NULL,18024,2);
INSERT INTO stanza VALUES('CB782','3','Sa Pulong Mo’g ampo ko,<br/>Motandog’s espiritu,<br/>Ibayaw’g lig-onon Mo,<br/>Ang akong espiritu.<br/>',NULL,18025,3);
INSERT INTO stanza VALUES('CB782','4','Padasiga, Ginoo,<br/>Sa espiritu’s uban;<br/>Espiritu lig-ona<br/>Aron dasigon sila.<br/>',NULL,18026,4);
INSERT INTO stanza VALUES('CB782','5','Sa matag pamulong ko,<br/>Espiritu’y mamulong;<br/>Bisan unsay buhaton,<br/>Sa esp’ritu dasigon.<br/>',NULL,18027,5);
INSERT INTO stanza VALUES('CB782','6','Molihok na ngani ko,<br/>Mabuksan untang uban,<br/>Iglihok’s espiritu,<br/>Maisa sila Nimo.<br/>',NULL,18028,6);
INSERT INTO stanza VALUES('CB782','7','Kaloy-i na, Ginoo,<br/>Huypi ko’s Espiritu;<br/>Madatong espiritu<br/>Mabag-o gayud Nimo.<br/>',NULL,18029,7);
INSERT INTO stanza VALUES('CB783','1','Ampo-tandog’s trono N’ya,<br/>Grasya N’ya pangitaa;<br/>Ug kita ’yang kaloy-an,<br/>Magtagbo’s pangin’hanglan.<br/>',NULL,18030,1);
INSERT INTO stanza VALUES('CB783','2','Ampo-tandog’s trono N’ya,<br/>Bation gyud sa lalum<br/>Pangin’hanglan sa grasya,<br/>Makig-ambitay Niya.<br/>',NULL,18031,2);
INSERT INTO stanza VALUES('CB783','3','Ampo-tandog’s trono N’ya,<br/>Datong grasya maila;<br/>Gamiton, pahimuslan,<br/>Ang Dios pasalamatan.<br/>',NULL,18032,3);
INSERT INTO stanza VALUES('CB783','4','Ampo-tandog’s trono N’ya,<br/>Tandog sab’s trono’s gahum;<br/>Sa ngalan sa Ginoo<br/>Batoking batokanan.<br/>',NULL,18033,4);
INSERT INTO stanza VALUES('CB783','5','Ampo-tandog’s trono N’ya,<br/>Sa buhi N’yang pagtoo;<br/>Pagbulot-an gamiton<br/>Buntogong kamatayon.<br/>',NULL,18034,5);
INSERT INTO stanza VALUES('CB783','6','Ampo-tandog’s trono N’ya,<br/>Gahum’s yawa uyogon;<br/>Ampo uban’s paghari,<br/>Ubang Cristo ning takna.<br/>',NULL,18035,6);
INSERT INTO stanza VALUES('CB784','1','Ampo nga makig-ambit N’ya,<br/>Diha sa espiritu;<br/>Maminaw sa ’yang presensya,<br/>Maghulat sa dapit N’ya.<br/>',NULL,18036,1);
INSERT INTO stanza VALUES('CB784','chorus','Ampo nga makig-ambit N’ya,<br/>Diha sa espiritu;<br/>Maminaw sa ’yang presensya,<br/>Maghulat sa dapit N’ya.<br/>',NULL,18037,2);
INSERT INTO stanza VALUES('CB784','2','Ampo nga makig-ambit N’ya,<br/>Binuksan ang sulod ko,<br/>Uban’s nawong nga way taptap,<br/>Putli, lunsay, tinuod.<br/>',NULL,18038,3);
INSERT INTO stanza VALUES('CB784','3','Ampo nga makig-ambit N’ya,<br/>Mangita N’ya’s pagtoo;<br/>Magtandog N’yang Espiritu,<br/>Matahurong mosalig.<br/>',NULL,18039,4);
INSERT INTO stanza VALUES('CB784','4','Ampo nga makig-ambit N’ya,<br/>Wa gyuy pagmaomao;<br/>Mangayo suma’s esp’ritu,<br/>Sa pagbati sa sulod.<br/>',NULL,18040,5);
INSERT INTO stanza VALUES('CB784','5','Ampo nga makig-ambit N’ya,<br/>Maminaw gyud ni Jesus;<br/>Magtagad’s mga tuyo N’ya,<br/>Sa sulod mouyon N’ya.<br/>',NULL,18041,6);
INSERT INTO stanza VALUES('CB784','6','Ampo nga makig-ambit N’ya,<br/>Ligoon sa nawong N’ya;<br/>Suropan sa katahum N’ya,<br/>Magsidlak’s kaayo N’ya.<br/>',NULL,18042,7);
INSERT INTO stanza VALUES('CB785','1','Ampong mapadayag S’ya,<br/>Di kitay mapadayag;<br/>Papadaygon ta’s Cristo,<br/>Patagdon ta’s tuyo N’ya.<br/>',NULL,18043,1);
INSERT INTO stanza VALUES('CB785','2','Ampong mapadayag S’ya,<br/>Isulti gyung tuyo N’ya,<br/>Pangagpas ta hilomon,<br/>Masagol sa Iyaha.<br/>',NULL,18044,2);
INSERT INTO stanza VALUES('CB785','3','Ampong mapadayag S’ya,<br/>Mohangad kanunay N’ya,<br/>Saming mopasumbalik’s<br/>Himaya N’ya gikan’s su’d.<br/>',NULL,18045,3);
INSERT INTO stanza VALUES('CB785','4','Ampong mapadayag S’ya,<br/>Papangamuyoon S’ya;<br/>S’yang nagpuyo-ampo’s su’d<br/>Ni Cristong naa’s langit.<br/>',NULL,18046,4);
INSERT INTO stanza VALUES('CB785','5','Ampong mapadayag S’ya,<br/>Di akoy tuo’g ampo;<br/>Ampong bug-os uban N’ya,<br/>Nga pina’gi ra gyud N’ya.<br/>',NULL,18047,5);
INSERT INTO stanza VALUES('CB786','1','Maghago sa pag-ampo,<br/>Aron S’ya makabuhat;<br/>Motandog N’ya’g matandog<br/>Gikan’s su’d hangtud’s gawas.<br/>',NULL,18048,1);
INSERT INTO stanza VALUES('CB786','2','Maghago sa pag-ampo<br/>Mausa’s Iyang tuyo;<br/>Hangtud bahaan kita,<br/>Sa panalangin Niya.<br/>',NULL,18049,2);
INSERT INTO stanza VALUES('CB786','3','Maghago sa pag-ampo,<br/>Kaugalingon kalimtan;<br/>Pagbuot dumilian,<br/>Tuyo N’ya ra’y matuman.<br/>',NULL,18050,3);
INSERT INTO stanza VALUES('CB786','4','Maghago sa pag-ampo,<br/>Pasugdon ang Ginoo<br/>Sa tanang plano’g buhat;<br/>Kanato S’ya mobuhat.<br/>',NULL,18051,4);
INSERT INTO stanza VALUES('CB786','5','Maghago sa pag-ampo,<br/>Hangtud ligid molihok;<br/>Mag-ampo uban Niya,<br/>Iglesia magmatuod.<br/>',NULL,18052,5);
INSERT INTO stanza VALUES('CB789','1','Atong higala si Jesus,<br/>Magpapas-an’s kasubo!<br/>Unsang katungod nga tanan<br/>Kaniya ikaampo!<br/>Sa kalinaw di mawad-an,<br/>Daghang pait likayan,<br/>Kon mahibalong motug-an,<br/>Kaniya’s atong tanan!<br/>',NULL,18053,1);
INSERT INTO stanza VALUES('CB789','2','May kaguol ba’g kalisud?<br/>Pagtintal ba’g pagsulay?<br/>Di kita angay maluya,<br/>Iampo lang nato N’ya.<br/>Higala S’yang kasaligan,<br/>Motabang’s kasub-anan;<br/>S’ya nasayud’s kahuyang ta,<br/>Busa mag-ampo Kan’ya.<br/>',NULL,18054,2);
INSERT INTO stanza VALUES('CB789','3','Gikapoy ba’g nabug-atan,<br/>Kabalaka na’s dughan?<br/>S’ya gihapo’y dalangpanan,<br/>Siya m’oy pangamuy-an.<br/>Mga higala nib’ya ba?<br/>Mangamuyo Kaniya;<br/>Sabakan N’ya panalipod,<br/>Kalipay ta ug kusog.<br/>',NULL,18055,3);
INSERT INTO stanza VALUES('CB791','1','Sacerdote, kabalaan;<br/>Sa Dios sigeng naghalad man,<br/>Sud-ong’s katahum N’ya, sunog’s<br/>Incienso’s pag-ampo.<br/>',NULL,18056,1);
INSERT INTO stanza VALUES('CB791','chorus','Incienso’s pag-ampo<br/>Sunogon na nato;<br/>Sug-an ta, adlaw, gabii<br/>Buboan S’ya’s pagdayeg.<br/>',NULL,18057,2);
INSERT INTO stanza VALUES('CB791','2','Balaang dapit way hayag,<br/>Gawas sa suga niini;<br/>Kon magsunog s’ya’g incienso,<br/>Magdagkot sab’s suga.<br/>',NULL,18058,3);
INSERT INTO stanza VALUES('CB791','3','Grasya sa Dios atong daygon,<br/>Kasingkasing paawiton;<br/>Mga sacerdote di lang<br/>Magsuga, magdayeg pa.<br/>',NULL,18059,4);
INSERT INTO stanza VALUES('CB791','4','Pagsunog’s incienso ampo,<br/>Pagdala’s nabanhawng Cristo,<br/>Tuyo’s Dios dinhi matagbo,<br/>Maghatag’s kalipay.<br/>',NULL,18060,5);
INSERT INTO stanza VALUES('CB791','5','Pagbasa’s Pulong hayagan,<br/>Sama ako nga gisug-an,<br/>Diosnon nga sidlak maghayag,<br/>Ihatag ko’s uban.<br/>',NULL,18061,6);
INSERT INTO stanza VALUES('CB791','6','Mga sacerdote mag-awit,<br/>Mag-awit ngadto’s Ginoo;<br/>Kasingkasing pun-on N’ya sa<br/>Pagdayeg’s gugma’g grasya.<br/>',NULL,18062,7);
INSERT INTO stanza VALUES('CB791','7','Cristo ihalad’s pag-ampo,<br/>Magbasa, magpadan-ag N’ya,<br/>Mag-awit, magdayeg’s grasya,<br/>Esp’ritu moawas.<br/>',NULL,18063,8);
INSERT INTO stanza VALUES('CB792','1','Naghulat ko Nimo, Ginoo,<br/>Papahulaya ko;<br/>Padaygi’s buot Mo,<br/>Kini ang hangyo ko,<br/>Naghulat ko, O Ginoo.<br/>',NULL,18064,1);
INSERT INTO stanza VALUES('CB792','2','Naghulat ko Nimo, Ginoo,<br/>Padaygi’s dalan Mo,<br/>Mag-ampo ra gyud ko,<br/>Pinaagi Nimo—<br/>Naghulat ko, O Ginoo.<br/>',NULL,18065,2);
INSERT INTO stanza VALUES('CB792','3','Naghulat ko Nimo, Ginoo,<br/>Mosagol Ka nako,<br/>Mausa ko Nimo,<br/>Mahimong dagway Mo—<br/>Naghulat ko, O Ginoo.<br/>',NULL,18066,3);
INSERT INTO stanza VALUES('CB792','4','Naghulat ko Nimo Ginoo,<br/>Pasayra’s buot Mo,<br/>Tabangi’s pagtuman,<br/>Moagay Ka nako—<br/>Naghulat ko, O Ginoo.<br/>',NULL,18067,4);
INSERT INTO stanza VALUES('CB792','5','Naghulat ko Nimo, Ginoo,<br/>Himoang ampo ko<br/>Pagpadayag Nimo<br/>Hatagi’s sekreto—<br/>Naghulat ko, O Ginoo.<br/>',NULL,18068,5);
INSERT INTO stanza VALUES('CB793','1','Hilom, kalag, paghulat’s Ginoo!<br/>Pasultia S’ya, ayha sultii;<br/>Pag-ampong tinuod, S’yay magsugod,<br/>Sandayong ka lang magpadayag N’ya.<br/>',NULL,18069,1);
INSERT INTO stanza VALUES('CB793','2','Hilom, kalag, paghulat’s Ginoo!<br/>Tun-ing magdili’s hunahuna mo.<br/>Sa Kaugalingon’s Dios padihog ka,<br/>Sa pag-ampo tuyo N’yay tumana.<br/>',NULL,18070,2);
INSERT INTO stanza VALUES('CB793','3','Hilom, kalag, paghulat’s Ginoo!<br/>Hiloma tanang gusto mo’g plano;<br/>Haylo’g kabalaka’s yuta wad-a,<br/>Ug sugo N’ya S’ya m’oy pahimoa.<br/>',NULL,18071,3);
INSERT INTO stanza VALUES('CB793','4','Hilom, kalag, paghulat’s Ginoo!<br/>Itugyan ang tanan’s espiritu;<br/>Pakit-on Ka’s gibugna’s Ginoo,<br/>Magmasugtanon Ka’s Iyang sugo.<br/>',NULL,18072,4);
INSERT INTO stanza VALUES('CB793','5','Hilom, kalag, paghulat’s Ginoo!<br/>S’yay paampoa pina’gi nimo;<br/>Bug-os kang maglihok uban Niya,<br/>Pag-ampo mo m’oy pagpadayag N’ya.<br/>',NULL,18073,5);
INSERT INTO stanza VALUES('CB793','6','Hilom, kalag, paghulat’s Ginoo!<br/>Hangtud usa na N’ya’s espiritu,<br/>Hangtud mapanag-iya ka na N’ya<br/>Ug sa Anak bug-os matransporma.<br/>',NULL,18074,6);
INSERT INTO stanza VALUES('CB793','7','Hilom, kalag, paghulat’s Ginoo!<br/>Hangtud Dios gawasnong makaagay,<br/>Sa pulong ug lihok mo kanunay<br/>Magtuman’s pagbuot sa Ginoo.<br/>',NULL,18075,7);
INSERT INTO stanza VALUES('CB797','1','Dasigang buhat Mo!<br/>Padaygan Mo kami!<br/>Mamulong Ka sa matag usa,<br/>Katawhan mausa!<br/>',NULL,18076,1);
INSERT INTO stanza VALUES('CB797','chorus','Dasigang buhat Mo!<br/>Nagpaabot kami,<br/>Kaloy-i na, O Ginoo,<br/>Panalangini mi!<br/>',NULL,18077,2);
INSERT INTO stanza VALUES('CB797','2','Dasigang buhat Mo!<br/>Ang tanan tandoga;<br/>Kasingkasing sunoga na<br/>Sa diosnong kalayo!<br/>',NULL,18078,3);
INSERT INTO stanza VALUES('CB797','3','Dasigang buhat Mo!<br/>Ngalan Mo ituboy!<br/>Kasingkasing padilaaba<br/>Sa langitnong gugma!<br/>',NULL,18079,4);
INSERT INTO stanza VALUES('CB797','4','Dasigang buhat Mo!<br/>Pinaagi’s Pulong!<br/>Kaputli’g kamatuoran<br/>Mabati’s pagtoo!<br/>',NULL,18080,5);
INSERT INTO stanza VALUES('CB797','5','Dasigang buhat Mo!<br/>Himoang maisug;<br/>Aron magbuhat pag-usab<br/>Sama kaniadto.<br/>',NULL,18081,6);
INSERT INTO stanza VALUES('CB797','6','Dasigang buhat Mo!<br/>Hatagi mi’s ulan!<br/>Ma-imo ang kadungganan!<br/>Kami mabulahan!<br/>',NULL,18082,7);
INSERT INTO stanza VALUES('CB799','1','Tibuok Biblia ginhawa’s Dios,<br/>Giginhawa sa Espiritu N’ya;<br/>Gisulat sa mga diosnong tawo,<br/>Aron mahatag ang kadato N’ya.<br/>',NULL,18083,1);
INSERT INTO stanza VALUES('CB799','2','Gininhawa’s Dios, kahayag sa tawo,<br/>Diosnong kahayag, tawo ’yang lamdagan<br/>Diha’s kangitngit, aron makit-an<br/>Tinuod n’ya nga panginahanglan.<br/>',NULL,18084,2);
INSERT INTO stanza VALUES('CB799','3','Gininhawa’s Dios, kinabuhi’s tawo,<br/>Nagpaambit’s diosnong kinaiya;<br/>Nagbuhi ug nag-anak pag-usab,<br/>Nag-usab’s kalag, nagbag-o nato.<br/>',NULL,18085,3);
INSERT INTO stanza VALUES('CB799','4','Gininhawa’s Dios, kaalam sa tawo,<br/>Kahibalo’s Dios magtudlo sa tawo,<br/>Nagpakita’s dayong tuyo sa Dios,<br/>Naggiya’s tawo unsaon pagkab-ot.<br/>',NULL,18086,4);
INSERT INTO stanza VALUES('CB799','5','Gininhawa sa Dios, kusog sa tawo,<br/>Diosnong gahum gisangkap kanato;<br/>Aron ang gikapoy ug naluya<br/>Magamhang motuman sa plano N’ya.<br/>',NULL,18087,5);
INSERT INTO stanza VALUES('CB799','6','Gininhawa’s Dios, ginhawaon ta,<br/>Aron makapahimulos ta N’ya;<br/>Dawaton pina’gi’s espiritu,<br/>Tanang kinahanglan S’yay magtagbo.<br/>',NULL,18088,6);
INSERT INTO stanza VALUES('CB800','1','Namulong na ang Dios, gibugna na S’ya,<br/>Personalidad N’ya gipadayag na;<br/>Gibugna sa mga anak ni Adam,<br/>Misteryo hingpit gayud nga dayag na.<br/>',NULL,18089,1);
INSERT INTO stanza VALUES('CB800','2','Gibutyag na’s Dios ang kasingkasing N’ya,<br/>Nga Anak N’ya maoy mag-una’s tanan,<br/>Aron diha’s Anak mahimaya S’ya,<br/>Taliwala sa tanang binuhat N’ya.<br/>',NULL,18090,2);
INSERT INTO stanza VALUES('CB800','3','Dios namulong, gipadayag na’s Cristo,<br/>Tinuod S’ya nga Dios, tinuod nga tawo;<br/>S’ya ang tanan’s tanan, tanan naa N’ya,<br/>Sentro’g utlanan sa dayong plano S’ya.<br/>',NULL,18091,3);
INSERT INTO stanza VALUES('CB800','4','Dios namulong, misteryo gibutyag na,<br/>Gimbut-an N’ya Cristo’g pagpadayag N’ya,<br/>Cristo ug kahupnganan’s Dios m’oy Ulo,<br/>Iglesia nga Lawas N’ya, S’yay magpuno.<br/>',NULL,18092,4);
INSERT INTO stanza VALUES('CB800','5','Dios namulong na, gipakita’s langit<br/>Nga tulo-usang Dios makigsagol’s tawo:<br/>Amahan’s Anak, Anak’s Espiritu,<br/>Magpuyo’s Lawas, magtuman’s ’yang plano.<br/>',NULL,18093,5);
INSERT INTO stanza VALUES('CB800','6','Dios namulong, ang bugna gihatag na,<br/>Sa paglalang N’ya’g ubos nga pagkatawo;<br/>Sa pagtubos ug kal’wasang hingpit N’ya,<br/>Mapuno untang yuta’s pagsimba N’ya.<br/>',NULL,18094,6);
INSERT INTO stanza VALUES('CB801','1','Buhing Pulong sa Dios, dagway Ka’s Dios,<br/>Sulod Ka ning Pulong nasulat na;<br/>Kanimo mapalgang kahupong’s Dios,<br/>Diha’s Kasulatan mabasa Ka.<br/>',NULL,18095,1);
INSERT INTO stanza VALUES('CB801','2','Way tawo nga nakakita sa Dios,<br/>Labi pa gyud kon way Kasulatan;<br/>Dios gipahayag Mo sa katawhan<br/>Ug gipaila Ka’s Kasulatan.<br/>',NULL,18096,2);
INSERT INTO stanza VALUES('CB801','3','Hingpit Ka nga pagkalawas sa Dios,<br/>Gihulagway Ka sa Kasulatan;<br/>Aron kami makasabut Nimo,<br/>Ug mahimo Kang matuod namo.<br/>',NULL,18097,3);
INSERT INTO stanza VALUES('CB801','4','Esp’ritung Taghatag’s-kinabuhi,<br/>Espiritu Ka ngani sa Pulong;<br/>Kon basahon ko sa Espiritu,<br/>Kahupnganan’s Dios maambitan ko.<br/>',NULL,18098,4);
INSERT INTO stanza VALUES('CB801','5','Diha Nimo makaambitay’s Dios,<br/>Sa Pulong makakaon ko Nimo;<br/>Pagtuon ubanan sa pag-ampo,<br/>Kadato Mo mapahimuslan ko.<br/>',NULL,18099,5);
INSERT INTO stanza VALUES('CB801','6','Tudloi paggamit’s espiritu,<br/>Magtuon’s Pulong, mokontak Nimo,<br/>Aron mausa Ka’s Kasulatan,<br/>Matag adlaw mahimong manna ko.<br/>',NULL,18100,6);
INSERT INTO stanza VALUES('CB802','1','Pulong Ka ug Espiritu;<br/>Simbahon namo’s esp’ritu!<br/>Sa Pulong nakasabut mi,<br/>Nakontak Ka’s Espiritu.<br/>',NULL,18101,1);
INSERT INTO stanza VALUES('CB802','2','Ikaw naako nga tanan,<br/>Kay nausa ako Nimo;<br/>Ikaw Pulong, Espiritu,<br/>Aron mahimong sangkap ko.<br/>',NULL,18102,2);
INSERT INTO stanza VALUES('CB802','3','Kon di Ka Pulong, Ginoo,<br/>Unsaon pagkaila ko?<br/>Kon di Ka pa Espiritu,<br/>Unsaon Ka makontak ko?<br/>',NULL,18103,3);
INSERT INTO stanza VALUES('CB802','4','Pulong nagpadayag Nimo,<br/>Aron Ikaw maila ko;<br/>Esp’rituy pagkamao Mo,<br/>Ikaw mismo matandog ko.<br/>',NULL,18104,4);
INSERT INTO stanza VALUES('CB802','5','Kinabuhi Ka’g kahayag,<br/>Dalan, kusog, kalan-on ko;<br/>Pinaagi sa Pulong Mo,<br/>Masinati Ka na namo.<br/>',NULL,18105,5);
INSERT INTO stanza VALUES('CB802','6','Pulong gisulti’s Biblia,<br/>Esp’ritu nagpuyo nako;<br/>Pu’ng—esp’ritu’g kinabuhi,<br/>Kon naa na’s esp’ritu ko.<br/>',NULL,18106,6);
INSERT INTO stanza VALUES('CB802','7','Kon Pulong Mo akong sabton,<br/>Espiritu gyuy tandogon;<br/>Di lang sabton’s hunahuna,<br/>Iampo sab’s espiritu.<br/>',NULL,18107,7);
INSERT INTO stanza VALUES('CB802','8','Pulong Mo akong gimahal,<br/>Espiritu makig-ambit;<br/>Sa Pulong Mo magkalipay,<br/>Sa espiritu mag-awit.<br/>',NULL,18108,8);
INSERT INTO stanza VALUES('CB806','1','Pikasang Tinapay’s Kinabuhi,<br/>Sama’s gibuhat Mo sa baybayon,<br/>Ikaw gipangita ko’s basahon;<br/>Buhing Pulong sa Dios, gihidlaw mi.<br/>',NULL,18109,1);
INSERT INTO stanza VALUES('CB806','2','Ikawng Tinapay sa Kinabuhi,<br/>Balaang Pulong nga nagl’was nako;<br/>Pakan-a ug mabuhi na ako,<br/>Tudloi’s paghigugma’s Pulong Mo.<br/>',NULL,18110,2);
INSERT INTO stanza VALUES('CB806','3','Ang Espiritu Mo ipadala<br/>Aron mag-abli sa akong mata;<br/>Kamatuoran Mo makita ko,<br/>Ug maila na Ikaw, Ginoo.<br/>',NULL,18111,3);
INSERT INTO stanza VALUES('CB806','4','Panalangining mga pulong Mo,<br/>Pagpanalangin sama’s Galilea;<br/>Matangtang nang gapos, way mag-ulang,<br/>Mahimo Kang akong tanan’s tanan.<br/>',NULL,18112,4);
INSERT INTO stanza VALUES('CB811','1','Ang akong kasingkasing gigutom,<br/>Ug espiritu giuhaw sa Dios;<br/>Ania ko Kanimo, Ginoo,<br/>Ikaw ra ang gikinahanglan ko.<br/>',NULL,18113,1);
INSERT INTO stanza VALUES('CB811','chorus','Pakan-a ako ug paimna,<br/>Busgang gigutom ug giuhaw;<br/>Sa kalipay pun-a ug matagbaw,<br/>Sa kagutom ug sa kauhaw.<br/>',NULL,18114,2);
INSERT INTO stanza VALUES('CB811','2','Ikaw ang kalan-on ug ilimnon,<br/>Makadasig sa espiritu ko;<br/>Kaon-inom Nimo, nangandoy ko,<br/>Pahimuslan Ka’s pagbasa-ampo.<br/>',NULL,18115,3);
INSERT INTO stanza VALUES('CB811','3','Pulong Ka nga may kahupnganan’s Dios,<br/>Esp’ritu aron kinabuhi S’ya;<br/>Pulong Ka nga nakalan-on nako,<br/>Esp’ritu tubig nga mainom ko.<br/>',NULL,18116,4);
INSERT INTO stanza VALUES('CB811','4','Kalan-on Kang nanaug sa langit,<br/>Batong gihampak aron mainom;<br/>Ikaw di mahurot nga kalan-on,<br/>Ikaw ang tubig nga sapa nako.<br/>',NULL,18117,5);
INSERT INTO stanza VALUES('CB811','5','Esp’ritu kinabuhi Ka’s Pulong,<br/>Sa Pulong Mo makakaon Nimo;<br/>Nabuhi Ka sa espiritu ko,<br/>Akong mainom sa espiritu.<br/>',NULL,18118,6);
INSERT INTO stanza VALUES('CB811','6','Sa Pulong pahimuslan Ka namo,<br/>Magpakabusog ug di na gutmon,<br/>Sa espiritu moliso Nimo,<br/>Imnon Ka hangtud di na uhawon.<br/>',NULL,18119,7);
INSERT INTO stanza VALUES('CB811','7','Kaon-inom Kanimo, Ginoo,<br/>Kaon-pagbasa, inom-pag-ampo;<br/>Basa-ampo, kaon-inom Nimo,<br/>Basa-ampo, maangkon Ka namo.<br/>',NULL,18120,8);
INSERT INTO stanza VALUES('CB811','8','Dinhi Ginoo, mokaon Nimo,<br/>Sa Espiritu’g Pulong Mo pun-a;<br/>Mahimo Ka untang pista nako,<br/>Nga wa sukad mapahimusli’s tawo.<br/>',NULL,18121,9);
INSERT INTO stanza VALUES('CB812','1','Giuhaw kaayo<br/>Kanimo, Ginoo;<br/>Mokaon-inom Kanimo,<br/>Pahimuslan Ka gyud.<br/>',NULL,18122,1);
INSERT INTO stanza VALUES('CB812','2','Motan-aw lang Nimo,<br/>Tuaw’s kasingkasing;<br/>Nangandoyng moinom Nimo,<br/>Kauhaw matagbaw.<br/>',NULL,18123,2);
INSERT INTO stanza VALUES('CB812','3','Kasanag’s nawong Mo<br/>Kalipayng makita;<br/>Mopuyo ko’g di mobiya,<br/>Sige Kang sud-ongon.<br/>',NULL,18124,3);
INSERT INTO stanza VALUES('CB812','4','Nianang ambitay<br/>Ikaw ang grasya ko;<br/>Natagbaw ko ug nalipay,<br/>Ug nakapahulay.<br/>',NULL,18125,4);
INSERT INTO stanza VALUES('CB812','5','Maglangay pa dinhi,<br/>Ikaw pangitaon,<br/>Padayong magbasa-ampo,<br/>Moagay Ka nako.<br/>',NULL,18126,5);
INSERT INTO stanza VALUES('CB813','1','Ania ko sa trono Mo,<br/>Ang kasingkasing gigutom,<br/>Sa grasya ug kaluoy Mo,<br/>Tagbo’s panginahanglan ko.<br/>',NULL,18127,1);
INSERT INTO stanza VALUES('CB813','2','Dinhi magsud-ong’s nawong Mo,<br/>Maghayag ni’s kasingkasing,<br/>Mout-ot, moayo’s tanang<br/>Kaluyahon ug apan ko.<br/>',NULL,18128,2);
INSERT INTO stanza VALUES('CB813','3','Dinhi ako mahayagan,<br/>Akong kahimtang makit-an;<br/>Ang gahum sa Imong dugo<br/>Sa akong sala maghinlo.<br/>',NULL,18129,3);
INSERT INTO stanza VALUES('CB813','4','Espiritu Mo magdihog,<br/>Pagkamao Mo maako;<br/>Ikaw akong mapa’muslan,<br/>Ang Imong plano masayran.<br/>',NULL,18130,4);
INSERT INTO stanza VALUES('CB813','5','Dinhi Pulong Mo gibasa,<br/>Sama’s sugang gipasiga;<br/>Espiritu maong lana,<br/>Magsuga’s Pulong, maghayag.<br/>',NULL,18131,5);
INSERT INTO stanza VALUES('CB813','6','Sama’s mga sacerdote,<br/>Lahutay’g sunog’s incienso;<br/>Ingon sab akong pag-ampo<br/>Kanimo sa espiritu.<br/>',NULL,18132,6);
INSERT INTO stanza VALUES('CB813','7','Pulong kahayag, kalan-on,<br/>Nga naghayag ug nagsangkap;<br/>Labi pang mobasa-kaon,<br/>Mahayagan ug mabusog.<br/>',NULL,18133,7);
INSERT INTO stanza VALUES('CB813','8','Ikaw ang buhi nga tubig<br/>Nga hingpit gyung makadasig;<br/>Labi pang moampo-inom,<br/>Moawas gyud nakong suba.<br/>',NULL,18134,8);
INSERT INTO stanza VALUES('CB813','9','Incienso Ka ngadto sa Dios,<br/>Gikahinangpan sa bug-os;<br/>Labi pa akong mag-ampo,<br/>Maghalad ni’ning kahumot.<br/>',NULL,18135,9);
INSERT INTO stanza VALUES('CB813','10','Sa pagbasa mahayagan,<br/>Sa pag-ampo matagbaw ko;<br/>Isangkap Ikaw kanako,<br/>Sa pangin’hanglan magtagbo.<br/>',NULL,18136,10);
INSERT INTO stanza VALUES('CB813','11','Ambitay gitinguha ko,<br/>Masakot ta’s basa-ampo;<br/>Masuropan Mo pag-ayo,<br/>Hangtud moawas Ka nako.<br/>',NULL,18137,11);
INSERT INTO stanza VALUES('CB814','1','Di mabuhi’s tinapay lang,<br/>Kondi’s pu’ng mog’was baba’s Dios,<br/>Pulong Niya atong kan-on,<br/>Himoong kinabuhi gyud.<br/>',NULL,18138,1);
INSERT INTO stanza VALUES('CB814','2','Di gibuhata’g lawas ra,<br/>Espiritu ug kalag sab;<br/>Espiritu’y labing sulod,<br/>Igkontak, ig-agpas sa Dios.<br/>',NULL,18139,2);
INSERT INTO stanza VALUES('CB814','3','Maingon nga gikin’hanglan<br/>Lawas mabusog’s kalan-on,<br/>Espiritu may kalan-on,<br/>Ikaw’s Imong Kaugalingon.<br/>',NULL,18140,3);
INSERT INTO stanza VALUES('CB814','4','Espiritu Ka, Pulong Mo<br/>Pagpadayag’s Kaugalingon;<br/>Espiritu Ikaw mismo,<br/>Sa sulod namo dawaton.<br/>',NULL,18141,4);
INSERT INTO stanza VALUES('CB814','5','Pagdawat sa Imong Pulong,<br/>Di lang amo nga basahon;<br/>Ug sa hunahuna sabton,<br/>Espiritu sab gamiton.<br/>',NULL,18142,5);
INSERT INTO stanza VALUES('CB814','6','Sa espiritu Pulong kan-on,<br/>Sa kahiladman dawaton;<br/>Sa paggamit’s espiritu,<br/>Iampong nasabtan’s ulo.<br/>',NULL,18143,6);
INSERT INTO stanza VALUES('CB814','7','Pulong magpabilin’s ulo,<br/>Bug-at lang nga kahibalo;<br/>Apan kon dad-on’s esp’ritu<br/>Makinabuhi’g esp’ritu.<br/>',NULL,18144,7);
INSERT INTO stanza VALUES('CB814','8','Kon espiritu modawat<br/>Sa Pulong mokontak Nimo,<br/>Matuod magkaon’s Pulong,<br/>Matandog Ka namo dayon.<br/>',NULL,18145,8);
INSERT INTO stanza VALUES('CB814','9','Tudloi kami, Ginoo,<br/>Paggamit sa espiritu;<br/>Aron’s pagbasa sa Pulong,<br/>Makakaon mi Kanimo.<br/>',NULL,18146,9);
INSERT INTO stanza VALUES('CB815','1','Cristo Pulong, Espiritu,<br/>Espiritu S’yang na’s Pulong,<br/>Pulong nga Iyang gisulti,<br/>Espiritu’g kinabuhi.<br/>',NULL,18147,1);
INSERT INTO stanza VALUES('CB815','2','Balaang Pulong na’s gawas,<br/>Espiritu Santo’s sulod;<br/>Duha ka dakong gasa’s Dios,<br/>Kan’ya makapahimulos.<br/>',NULL,18148,2);
INSERT INTO stanza VALUES('CB815','3','Pulong nag-asoy’s Espiritu,<br/>Espiritu’y realidad;<br/>Duhang bahin’s usang butang,<br/>Dili gyud kini mabulag.<br/>',NULL,18149,3);
INSERT INTO stanza VALUES('CB815','4','Kon lamdagan’s Espiritu,<br/>Pu’ng mahimong kinabuhi;<br/>Kon Pulong bulag’s Esp’ritu,<br/>Haw-ang, hagit lang’s pangisip.<br/>',NULL,18150,4);
INSERT INTO stanza VALUES('CB815','5','Pulong tandogon’s esp’ritu,<br/>Mahimo nga kinabuhi;<br/>Espiritung ipadayag<br/>Pulong’s kinabuhiy sangkap.<br/>',NULL,18151,5);
INSERT INTO stanza VALUES('CB815','6','Espiritu ta bansayon<br/>Pagdawat’s Pulong N’ya’s sulod,<br/>Espiritu ug Pulong Mo,<br/>Mausa nganhi kanamo.<br/>',NULL,18152,6);
INSERT INTO stanza VALUES('CB815','7','Mahimo untang Pulong Mo<br/>Kinabuhi sa sulod ko,<br/>Espiritu diha’s Pulong,<br/>Tinuod ko nga ekspresyon.<br/>',NULL,18153,7);
INSERT INTO stanza VALUES('CB816','1','Pulong di lang kahibalo,<br/>Kondi’ kinabuhi’s tawo;<br/>Di lang hunahuna sa Dios,<br/>Kondi’ S’ya’s ’yang Kaugalingon;<br/>Di lang bugna’s tinguha N’ya,<br/>Kondi’ ni Cristo mismo,<br/>Di lang mga pagtulon-an,<br/>Kondi’ S’yang masinati.<br/>',NULL,18154,1);
INSERT INTO stanza VALUES('CB816','2','Kon basahon ta ang letra,<br/>Pulong kahibalo ra,<br/>Kon basahon’s espiritu,<br/>Kinabuhing tinuod.<br/>Tanang letra’g kahibalo,<br/>Makamatay lang nato,<br/>Pulong diha’s espiritu,<br/>Makabuhi kanato.<br/>',NULL,18155,2);
INSERT INTO stanza VALUES('CB816','3','Pagbasang di S’ya matagbo,<br/>Kawang nga kahibalo,<br/>Apan kon Siya matagbo,<br/>Kinabuhi maato.<br/>Pagbasang way pagtandog N’ya,<br/>Hagit ra’s hunahuna;<br/>Apan kon matandog ta S’ya,<br/>Makinabuhi nato.<br/>',NULL,18156,3);
INSERT INTO stanza VALUES('CB816','4','Ang kahibalo’s Biblia<br/>Himoong kinabuhi,<br/>Tanang pagpanabut’s ulo,<br/>Umolon’s espiritu;<br/>Tanang kasayuran’s Pulong,<br/>Mahimong kinabuhi;<br/>Tanang kahibalo’s letra,<br/>Dawaton’s espiritu.<br/>',NULL,18157,4);
INSERT INTO stanza VALUES('CB816','5','Kon alang’s kahibalo ta,<br/>Kang Eva mahisama;<br/>Kita matintal sa yawa,<br/>Aron magpakasala;<br/>Kon dawaton ta ang Pulong<br/>Nga kahoy’s kinabuhi;<br/>Mga Pulong sa Ginoo,<br/>Kalan-on’s espiritu.<br/>',NULL,18158,5);
INSERT INTO stanza VALUES('CB818','1','Misteryo sa Dios si Cristo,<br/>Dios nga di makita nato;<br/>Dagway wa sukad makita’s tawo,<br/>Gipaila S’ya ni Cristo.<br/>',NULL,18159,1);
INSERT INTO stanza VALUES('CB818','2','Pulong gyud si Cristo sa Dios,<br/>Matuod N’yang paghulagway;<br/>Pagkalawas N’ya sa bug-os,<br/>Nagpadayag’s Iyang dagway.<br/>',NULL,18160,2);
INSERT INTO stanza VALUES('CB818','3','Dagway’s Dios nga di makita,<br/>S’yang silaw sa ’yang himaya,<br/>Nagpuyo N’yang kahupong’s Dios,<br/>Iya gyung panghimatuod.<br/>',NULL,18161,3);
INSERT INTO stanza VALUES('CB818','4','Iglesia misteryong Cristo,<br/>Kay di man S’ya makita’s tawo;<br/>Way makakita N’ya karon,<br/>Maila ra S’ya’s Iglesia.<br/>',NULL,18162,4);
INSERT INTO stanza VALUES('CB818','5','Iglesia pagpadayag N’ya,<br/>Sa lawas gyud nagpuyo S’ya;<br/>Tinuod siyang hulad N’ya,<br/>Diha niya makita S’ya.<br/>',NULL,18163,5);
INSERT INTO stanza VALUES('CB818','6','May dagway N’ya ang Iglesia,<br/>S’yay pagtubo’g pagkaylap N’ya;<br/>Mapalgan’s Cristo kaniya,<br/>Si Cristo Ulo, Lawas s’ya.<br/>',NULL,18164,6);
INSERT INTO stanza VALUES('CB818','7','Naa’s Anak ang Amahan,<br/>Espiritu maong Anak;<br/>Espiritu sa Trinidad<br/>Na’s Iglesia, nausa n’ya.<br/>',NULL,18165,7);
INSERT INTO stanza VALUES('CB819','1','Ingon’s lawas nga kahupnganan,<br/>Ug pagpadayag ta<br/>Iglesia mao sab Kaniya,<br/>Pagpadayag Niya.<br/>',NULL,18166,1);
INSERT INTO stanza VALUES('CB819','2','Ingon ni Eva, bahing Adam,<br/>Kay kan’ya naggikan,<br/>Iglesia sab m’oy pagtubo N’ya,<br/>Si Cristo ang sulod.<br/>',NULL,18167,2);
INSERT INTO stanza VALUES('CB819','3','Ingon sa binhing gilubong nga<br/>Nadaghan nga trigo,<br/>Gisakot pag-usa’g giporma<br/>Nga usang tinapay.<br/>',NULL,18168,3);
INSERT INTO stanza VALUES('CB819','4','Kitang daghang iya’s Iglesia,<br/>Nga pagpadaghan N’ya;<br/>Usang Lawas nga nagpadayag,<br/>Naghimaya sa Dios.<br/>',NULL,18169,4);
INSERT INTO stanza VALUES('CB819','5','Ingon’s mga sanga sa parras<br/>Nga nikatay’s gawas,<br/>Nausa ni’ni’g nagpabilin,<br/>Namunga’g pinungpong.<br/>',NULL,18170,5);
INSERT INTO stanza VALUES('CB819','6','Busa daghang miembro’s Iglesia<br/>M’oy pagdakong Cristo,<br/>Sa kinabuhi nausa N’ya,<br/>Nagpakaylap Niya.<br/>',NULL,18171,6);
INSERT INTO stanza VALUES('CB819','7','Kahupnganan, hulad, pagsanay,<br/>Hingpit ekspresyon N’ya,<br/>Pagtubo, pagkaylap, ug sumpay,<br/>Labing dagaya gyud.<br/>',NULL,18172,7);
INSERT INTO stanza VALUES('CB819','8','Mao ang Iglesia kang Cristo,<br/>Ug diha N’ya ang Dios<br/>Mahimaya’s mga tinubos<br/>Hangtud’s eternidad.<br/>',NULL,18173,8);
INSERT INTO stanza VALUES('CB819','9','Busa si Cristo ug Iglesia,<br/>Dakong misteryo’s Dios,<br/>Mao ang panagsagol sa Dios<br/>Ug sa katawhan N’ya.<br/>',NULL,18174,9);
INSERT INTO stanza VALUES('CB820','1','Kadato N’ya pahimuslan,<br/>Mahimo N’yang kahupnganan;<br/>Si Cristo mismo ambitan,<br/>Pamatuod N’ya makit-an.<br/>',NULL,18175,1);
INSERT INTO stanza VALUES('CB820','2','Kadato N’ya mao Siya<br/>Kanatong mga bahin N’ya;<br/>Makahupnganan ta Niya,<br/>Sama’s lawas nga iya’s tawo.<br/>',NULL,18176,2);
INSERT INTO stanza VALUES('CB820','3','Gihulagwayng kadato N’ya<br/>Sa mga abut’s Canaan,<br/>Dakong templo nga natukod,<br/>Hulagway sa Iglesia gyud.<br/>',NULL,18177,3);
INSERT INTO stanza VALUES('CB820','4','Eva kahupnganang Adam,<br/>Ingon sab Iglesiang Cristo;<br/>Eva naggikan ni Adam,<br/>Cristo’y nag-anak’s Iglesia.<br/>',NULL,18178,4);
INSERT INTO stanza VALUES('CB820','5','Kadato N’ya Siya mismo,<br/>Kahupnganan N’ya Iglesia,<br/>Pagpadayag N’ya, puno N’ya;<br/>Bug-os nga tinukod Niya.<br/>',NULL,18179,5);
INSERT INTO stanza VALUES('CB821','1','Iglesia sudlanang Cristo,<br/>Sudlan N’ya’g magpadayag N’ya,<br/>Sama’s lawas sa tawo nga<br/>Magpadayag sab kaniya.<br/>',NULL,18180,1);
INSERT INTO stanza VALUES('CB821','2','Ingon’s templo ngadto’s arka,<br/>Sudlana’g pahulayanan;<br/>Cristo ang sulod’s Iglesia,<br/>Ug Iglesia puy-anan N’ya.<br/>',NULL,18181,2);
INSERT INTO stanza VALUES('CB821','3','Si Cristo misteryo gyud’s Dios,<br/>Nagbatbat, nagpadayag N’ya;<br/>Iglesia—misteryong Cristo,<br/>Magbatbat, magpadayag N’ya.<br/>',NULL,18182,3);
INSERT INTO stanza VALUES('CB821','4','Mga miembro sa Iglesia,<br/>May pagkakolonon sila;<br/>Nagkin’hanglan transpormahon,<br/>Anam nga magkabililhon.<br/>',NULL,18183,4);
INSERT INTO stanza VALUES('CB821','5','Matukod’s pagkatransporma,<br/>Masudlanan silang Cristo;<br/>Pagkamalangkubon Niya,<br/>Klarong ipadayag nila.<br/>',NULL,18184,5);
INSERT INTO stanza VALUES('CB821','6','Sa tanan nga pagtransporma,<br/>Tulo-usang Dios magbuhat.<br/>Iglesia—hugpong sudlanan,<br/>Daw bag-ong Jerusalem man.<br/>',NULL,18185,6);
INSERT INTO stanza VALUES('CB821','7','Iglesia sudlanang Cristo,<br/>Sudlan N’ya’g magpadayag N’ya,<br/>Sama’s lawas sa tawo nga<br/>Magpadayag sab kaniya.<br/>',NULL,18186,7);
INSERT INTO stanza VALUES('CB821','8','Ingon’s templo ngadto’s arka,<br/>Sudlana’g pahulayanan;<br/>Cristo ang sulod’s Iglesia,<br/>Ug Iglesia puy-anan N’ya.<br/>',NULL,18187,8);
INSERT INTO stanza VALUES('CB821','9','Si Cristo misteryo gyud’s Dios,<br/>Nagbatbat, nagpadayag N’ya;<br/>Iglesia—misteryong Cristo,<br/>Magbatbat, magpadayag N’ya.<br/>',NULL,18188,9);
INSERT INTO stanza VALUES('CB821','10','Mga miembro sa Iglesia,<br/>May pagkakolonon sila;<br/>Nagkin’hanglan transpormahon,<br/>Anam nga magkabililhon.<br/>',NULL,18189,10);
INSERT INTO stanza VALUES('CB821','11','Matukod’s pagkatransporma,<br/>Masudlanan silang Cristo;<br/>Pagkamalangkubon Niya,<br/>Klarong ipadayag nila.<br/>',NULL,18190,11);
INSERT INTO stanza VALUES('CB821','12','Sa tanan nga pagtransporma,<br/>Tulo-usang Dios magbuhat.<br/>Iglesia—hugpong sudlanan,<br/>Daw bag-ong Jerusalem man.<br/>',NULL,18191,12);
INSERT INTO stanza VALUES('CB822','1','Iglesia tangkawang Cristo,<br/>Cristo’y suga, Dios kahayag;<br/>Si Cristo ang nagsidlak’s Dios,<br/>Iglesia ang gisang-atan.<br/>',NULL,18192,1);
INSERT INTO stanza VALUES('CB822','2','Kahayag nagsidlak’s suga<br/>Maong Dios nga kinabuhi;<br/>Tangkawan bulawan aron<br/>Motakdo’s gisidlak ni’ni.<br/>',NULL,18193,2);
INSERT INTO stanza VALUES('CB822','3','Ning mangitngit nga panahon<br/>Kinabuhi’s Dios nisidlak<br/>Sa daghang sentro’s katawhan,<br/>Testimonio N’ya makit-an.<br/>',NULL,18194,3);
INSERT INTO stanza VALUES('CB822','4','Kon putling pamatuod ta,<br/>Ampingan gyung “unang gugma“;<br/>Gikan’s kahoy’s kinabuhi<br/>Maiyang pahat’s mananaug.<br/>',NULL,18195,4);
INSERT INTO stanza VALUES('CB822','5','Ang paglutos kon antuson,<br/>Kinabuhi m’oy korona;<br/>Tanang diosdios atong dag-on,<br/>Makakaon’s “tagong manna.”<br/>',NULL,18196,5);
INSERT INTO stanza VALUES('CB822','6','Buhat ni “Jezabel” wad-on,<br/>Makabaton ta’s kagahum;<br/>Hugawng kamatayon dag-on,<br/>Linong maputiy sul-obon.<br/>',NULL,18197,6);
INSERT INTO stanza VALUES('CB822','7','Sama’s “Filadelfia,” pulong<br/>Gituman, Ngalan giila;<br/>Garbong dagaang wad-on ta,<br/>Mokaon’s talad uban N’ya.<br/>',NULL,18198,7);
INSERT INTO stanza VALUES('CB822','8','Iglesia sama kaulay,<br/>Tangkawan, bulawang lunsay;<br/>Angay’s lunsayng pag’matuod,<br/>Sa kinabuhi ni Jesus.<br/>',NULL,18199,8);
INSERT INTO stanza VALUES('CB822','9','Iglesia lokal nga tanan,<br/>Ning panahon m’oy tangkawan;<br/>Ugma bag-ong Jerusalem<br/>M’oy tangkawan’s kahangturan.<br/>',NULL,18200,9);
INSERT INTO stanza VALUES('CB822','10','Daw lunsayng bulawang syudad,<br/>Katapusang pag’dayag’s Dios;<br/>Cristo—suga s’yay magkupot,<br/>Aron magsidlak’s kahayag.<br/>',NULL,18201,10);
INSERT INTO stanza VALUES('CB823','1','Sa wa pa ang kalibutan<br/>Iglesia nahimut-an,<br/>Gipili’s Dios dihang Cristo,<br/>Maanak, mabalaan;<br/>Mahimo N’ya nga kabtangan,<br/>Sa Esp’ritu timbrehan;<br/>Patinga, panulondon ta,<br/>Sa Anak ’yang padaygan.<br/>',NULL,18202,1);
INSERT INTO stanza VALUES('CB823','2','Cristo nikayab sa trono,<br/>Labaw’s tanang kagahum;<br/>Dios naghimo Niyang Ulo,<br/>Sa Iglesiang Lawas N’ya.<br/>Tanang butang Iyang pun-on,<br/>Kahupnganan madayag<br/>Pinaagi sa Iglesia,<br/>Makita ang dagway N’ya.<br/>',NULL,18203,2);
INSERT INTO stanza VALUES('CB823','3','Nangamatay unta’s sala,<br/>Sunod’s panahon karon;<br/>Sa yawa nagpasakop ta,<br/>Nagpatuyang sa unod.<br/>Nabanhaw uban ni Cristo,<br/>Naglingkod’s kalangitan;<br/>Mahimayaong buhat’s Dios,<br/>Diha kang Cristo Jesus.<br/>',NULL,18204,3);
INSERT INTO stanza VALUES('CB823','4','Judio’g Gentil nausa,<br/>Misteryo’s Dios nakita;<br/>Cristo ang Batong pamag-ang,<br/>Nahimong sukaranan;<br/>Kita matukod Kaniya,<br/>Puloy-an’s Dios makita,<br/>Espiritu nagpaangay<br/>Mahimo ’yang pahulay.<br/>',NULL,18205,4);
INSERT INTO stanza VALUES('CB823','5','Gilaraw’s Dios eternidad,<br/>Kaalam N’ya ipadayag,<br/>Misteryo nga Iglesia N’ya,<br/>Kabalayan’s ’yang Anak.<br/>Matugkad’s mga balaan,<br/>Cristo way kinutoban;<br/>Ang gugma N’yang di masukod,<br/>Mapanag-iya ang Dios.<br/>',NULL,18206,5);
INSERT INTO stanza VALUES('CB823','6','Usa’s Lawas, Espiritu,<br/>Paglaum ug Ginoo;<br/>Usang pagtoo, bautismo,<br/>Usang Amahan’s tanan;<br/>Busa Iglesia usa ra,<br/>Dinhi Cristo maila;<br/>Makatubo’s pagkahamtong,<br/>Dili na magpalimbong.<br/>',NULL,18207,6);
INSERT INTO stanza VALUES('CB823','7','Gihatag N’ya tanang gasa,<br/>Pagtukod sa Lawas N’ya,<br/>Paghingpit’s mga balaan<br/>Sa ilang pangalagad.<br/>Hukason ang daang tawo,<br/>Ug isul-ob ang bag-o;<br/>Hunahuna’g espiritu,<br/>Mabag-o samang Cristo.<br/>',NULL,18208,7);
INSERT INTO stanza VALUES('CB823','8','Gihatag ’yang Kaugalingon,<br/>Iglesia balaanon,<br/>Walay kunot, buling, mansa,<br/>Iyang pangasaw-onon.<br/>Gipakaon, gipangga N’ya<br/>Sama sa Kaugalingon.<br/>Nausa S’ya sa Iglesia,<br/>Kadakong misteryoha.<br/>',NULL,18209,8);
INSERT INTO stanza VALUES('CB824','1','Iglesia Lawas Niya,<br/>Puy-anan sab sa Dios;<br/>Katiguman’s tinawag,<br/>Pagsakot’s Dios ug tawo;<br/>Dios nagpili n’yang daan,<br/>Ug gitubos sa krus;<br/>Kinaiya’g posisyon,<br/>O pagkalangitnon.<br/>',NULL,18210,1);
INSERT INTO stanza VALUES('CB824','2','Bag-ong tawo binuhat,<br/>Gianak’s Nabanhaw;<br/>Gibautismohan sa Dios,<br/>Gibalaan’s Pulong.<br/>Cristo ’yang kinabuhi,<br/>Iyang Ulo usab;<br/>Uban Niyang nikayab,<br/>Nagtunob’s kaaway.<br/>',NULL,18211,2);
INSERT INTO stanza VALUES('CB824','3','Patukoranan’s Lawas<br/>Si Cristo ra mismo;<br/>Diosnon sama ni Cristo<br/>Sa tanan nga butang;<br/>Tanang bahin kin’hanglan<br/>Mag-agi’s Calvario,<br/>Gitukod’s pagkabanhaw—<br/>Bililhon nga bato.<br/>',NULL,18212,3);
INSERT INTO stanza VALUES('CB824','4','Kinaiya n’ya usa,<br/>Usang Dios, Ginoo;<br/>Espiritu, pagtoo,<br/>Paglaum, bautismo.<br/>Dios Trinidad na’s sulod,<br/>Usa ra ka Lawas;<br/>Sa pagtoo nausa,<br/>Paglaum’s himaya.<br/>',NULL,18213,4);
INSERT INTO stanza VALUES('CB824','5','Tanang mga bahin n’ya<br/>Gikan’s kanasuran,<br/>Bisan unsang matanga,<br/>Usahon N’yang tanan;<br/>Wa nay Judio’g Gentil,<br/>Agalon, ulipon,<br/>Way ubos o dungganon,<br/>“Bag-ong tawo” Cristo ra.<br/>',NULL,18214,5);
INSERT INTO stanza VALUES('CB824','6','Usa lang’s uniberso,<br/>Sa lokal nadayag;<br/>Usa ka dapit usa,<br/>Sukaranan lokal.<br/>Mangako’s kaugalingon<br/>Pagdumala’s dapit;<br/>Apan sa pakig-ambit<br/>Usa’s uniberso.<br/>',NULL,18215,6);
INSERT INTO stanza VALUES('CB824','7','Iglesia’s matag lokal<br/>Hulagway sa Syudad;<br/>Sa tanan nga bahin gyud<br/>Syudad gipadayag.<br/>Cristo Sugang magsidlak.<br/>Dios na’s su’d, Kahayag;<br/>Tangkawang masanagon<br/>Dagway N’yang matahum.<br/>',NULL,18216,7);
INSERT INTO stanza VALUES('CB829','1','Si Cristo mismo binhi’s Iglesia<br/>Nga gipugas sa kasingkasing ta,<br/>Nagtubong trigo, himo’ng harina,<br/>Matinapayng magtagbaw’s Dios ug tawo.<br/>',NULL,18217,1);
INSERT INTO stanza VALUES('CB829','2','Ang mga mini nga magtotoo,<br/>Bunglayon taliwala sa trigo,<br/>Magpalibog, mag-ulang’s pagtubo,<br/>Aron plano sa Dios di mahimo.<br/>',NULL,18218,2);
INSERT INTO stanza VALUES('CB829','3','Kinabuhi’s Iglesia utanon,<br/>Naggikan kang Cristo nga mustasa;<br/>Tago, lumalabay, ug gamay ra,<br/>Apan maayong kan-on’s gigutom.<br/>',NULL,18219,3);
INSERT INTO stanza VALUES('CB829','4','Ang utanon gibayloan’s Yawa<br/>Sa kinaiya ug sa ’yang porma;<br/>Nitubo nga dako nga punoan,<br/>Puloy-anan sa mga dautan.<br/>',NULL,18220,4);
INSERT INTO stanza VALUES('CB829','5','Hulog nga iglesia gipa’muslan,<br/>Gisaktan ug paganong batasan,<br/>Ingon’s harinang gipatuboan,<br/>Di na makaon kay sinambogan.<br/>',NULL,18221,5);
INSERT INTO stanza VALUES('CB829','6','Apan transpormahon silang Cristo,<br/>Himoong perla, hamiling bato,<br/>Materyales itukod’s Iglesia,<br/>Aron Gingharian N’ya maila.<br/>',NULL,18222,6);
INSERT INTO stanza VALUES('CB829','7','Katigumang magtubo kang Cristo,<br/>Matukod ubang Cristo, makambyo,<br/>Daw maayong perla kahamili,<br/>Ingon sa gilubong nga bahandi.<br/>',NULL,18223,7);
INSERT INTO stanza VALUES('CB829','8','Igahin kami’s mga “bunglayon,“<br/>Sa dakong “kahoy” Imong luwason,<br/>Putlia mi’s tanang “levadura,“<br/>Aron makaon mi’s tawo ug Nimo.<br/>',NULL,18224,8);
INSERT INTO stanza VALUES('CB829','9','Patuboa kami’s kinabuhi,<br/>Transpormaha, tukora na kami,<br/>Lawas—ekspresyon Mo himoa na,<br/>Gingharian Mo kanamo makita.<br/>',NULL,18225,9);
INSERT INTO stanza VALUES('CB831','1','Pagkinabuhi’s balaan<br/>Pagkausa’s Iglesia;<br/>Esp’ritung nagpuyo’s sulod<br/>Maoy nag-usa nila.<br/>Naila’g ginganlan kinig<br/>Pagkausa’s Esp’ritu;<br/>Basi sa gikausahang<br/>Pagtoo natong tanan.<br/>',NULL,18226,1);
INSERT INTO stanza VALUES('CB831','2','Hamiling pagtoo nato,<br/>Inumol gayud lamang<br/>Ni Cristo ug’s katubsanan,<br/>Nga bugtong ug balaan.<br/>Ni’ni balaan nausa,<br/>Tinuod nagkauyon,<br/>Gikan’s usa ka pagtoo,<br/>Nilugwa ang Iglesia.<br/>',NULL,18227,2);
INSERT INTO stanza VALUES('CB831','3','Iglesia sa uniberso,<br/>Usang panu’ndong Cristo;<br/>Busa usa gyud makita<br/>Sa lokal ang Iglesia;<br/>Elemento n’ya usa ra—<br/>Dios, Ginoo, pagtoo,<br/>Espiritu ug bautismo,<br/>Lawas ug paglaum sab.<br/>',NULL,18228,3);
INSERT INTO stanza VALUES('CB831','4','Pagkausa sukaranan<br/>Sa Iglesia tang tanan,<br/>Bugtong sukaranang hangyo<br/>Kanato’s Espiritu.<br/>Maampingang pagkausa<br/>Pagpalakaw’s Iglesia,<br/>Magtukod sa ’yang ekspresyon<br/>Pinaagi’s komunyon.<br/>',NULL,18229,4);
INSERT INTO stanza VALUES('CB831','5','Tabangi ming maningkamot<br/>Pag-amping’s pagkausa,<br/>Pinaagi sa pagsalmot<br/>Sa kinabuhi’s Lawas.<br/>Aron ang gitinguha Mo<br/>Matuman gyud sa hingpit,<br/>Ug ang dayong tuyo sa Dios<br/>Hingpit na gyung matapos.<br/>',NULL,18230,5);
INSERT INTO stanza VALUES('CB832','1','Cristo nga Anak’s Dios ug pagtubos N’ya,<br/>Pagtoong moluwas, bugtong kredo ta;<br/>Doktrina wa may labut sa pagtoo,<br/>Cristo, ’yang buhat ug persona ra N’ya.<br/>',NULL,18231,1);
INSERT INTO stanza VALUES('CB832','2','Pagtulon-an kon di husto’g paggamit,<br/>Mga hanging moguba’s pagkausa,<br/>Magpalayo natong Cristo nga Ulo,<br/>Di makatukod’s Lawas, moguba pa.<br/>',NULL,18232,2);
INSERT INTO stanza VALUES('CB832','3','Busa buhian ta tanang doktrina,<br/>Pagtoo ampingan kay mausa ta.<br/>Usa gyud diha’s Ginoong Esp’ritu;<br/>Kini ray kinahanglan buhaton ta.<br/>',NULL,18233,3);
INSERT INTO stanza VALUES('CB832','4','Huptang kamat’oran—si Cristo mismo,<br/>Magawas’ mabahinong kaugalingon,<br/>Magtubo ngadto’s Ulo nga si Cristo,<br/>Lawas matukod puno’s kahupnganan.<br/>',NULL,18234,4);
INSERT INTO stanza VALUES('CB832','5','“Pagkausa sa pagtoo” kab-oton,<br/>Tanang hangin’s doktrina di dawaton,<br/>Huptan nato’s Cristo nga Espiritu,<br/>Aron Lawas magtubo’s pagkausa.<br/>',NULL,18235,5);
INSERT INTO stanza VALUES('CB834','1','Ikaw ang Bato’s pamag-ang,<br/>Gitamay’s magtutukod,<br/>Sa pagkabanhaw gibutang,<br/>Bililhon alang sa Dios.<br/>Kal’wasan nadawat namo,<br/>Ug Kanimo natukod,<br/>Judio’g Gentil puy-anan Mo,<br/>Usa ka bag-ong tawo.<br/>',NULL,18236,1);
INSERT INTO stanza VALUES('CB834','2','Bato sab Ka nga gihampak,<br/>Kauhaw’s tawo magtagbaw,<br/>Barugan’s mga mahuyang,<br/>Magtukod sa balay’s Dios,<br/>Batong Patukoranan’s Sion,<br/>Sinulayan Kang lig-on;<br/>Bato suportar’s Iglesia,<br/>Patukoranan niya.<br/>',NULL,18237,2);
INSERT INTO stanza VALUES('CB834','3','Natukod s’ya diha Nimo,<br/>Ug bisan s’ya unoson,<br/>Iglesia mobarug gayud,<br/>Impyerno di kadaug.<br/>Nakabaton’s kagahum Mo ,<br/>Mogapos ba’g motangtang,<br/>Dad-ong tawo sa gingharian,<br/>Bihag’s yawa buhian.<br/>',NULL,18238,3);
INSERT INTO stanza VALUES('CB834','4','Buhing Bato Ka, Ginoo,<br/>Mahal, pilion gayud;<br/>Gihimo ming buhing bato,<br/>Sama’g kinaiya Mo.<br/>Usang gitukod nga templo,<br/>Nga kapuy-an’s among Dios,<br/>Balaan ming sacerdote,<br/>Kanimo maghalad mi.<br/>',NULL,18239,4);
INSERT INTO stanza VALUES('CB834','5','Anak usab ni David Ka,<br/>Magtukod’s templo sa Dios,<br/>Aron makatuman’s tahas<br/>Hari’g Sacerdote Ka.<br/>Naghari Ka aron ang tawo<br/>Magpasakop gyud sa Dios;<br/>Sacerdote’s presensya N’ya<br/>Nagdala’s tawo Kaniya.<br/>',NULL,18240,5);
INSERT INTO stanza VALUES('CB834','6','Pagbuot Mo gikan’s trono<br/>Naghatag’s kadaitan;<br/>Ambitayay naa’s suba,<br/>Magsangkap, magpadaghan.<br/>Kon maangay kining duha<br/>Tuyo sa Dios matuman,<br/>Pagkahari’g sacerdote,<br/>Usa alang’s pagtukod.<br/>',NULL,18241,6);
INSERT INTO stanza VALUES('CB834','7','Dios, apan nahimong unod,<br/>Dios, tawo nagpuyo Nimo;<br/>Templo alang’s himaya N’ya,<br/>Dios Kanimo giasoy.<br/>Iglesia sab panagsagol,<br/>Pagkausa’s Dios ug tawo,<br/>Ingon sab ang matag bahin<br/>Aron plano N’ya matukod.<br/>',NULL,18242,7);
INSERT INTO stanza VALUES('CB834','8','Puloy-anan Ka nga dayon,<br/>Balay’s tanang panahon;<br/>Ikaw among panalipod,<br/>Mabuhi lang mi Nimo.<br/>Balaang Dapit Ka namo,<br/>Dios ug kami nagpuyo.<br/>Presensya sa Dios Ka’s sulod,<br/>Gisimba’s way pagtapos.<br/>',NULL,18243,8);
INSERT INTO stanza VALUES('CB834','9','Pamag-ang, Patukoranan,<br/>Ulohang Bato, Bato,<br/>Iglesia, Buhing Bato ug<br/>Puy-anan, Bal’ang Dapit.<br/>Daygon kay Magtutukod sab,<br/>Kahibulongan man gyud!<br/>Matukod na unta kami,<br/>Mga buhing bato Mo.<br/>',NULL,18244,9);
INSERT INTO stanza VALUES('CB837','1','Daygon O Dios, Imong plano,<br/>Puloy-an ming buhaton Mo;<br/>Nga kapuy-an, mapuno Mo,<br/>Aron’s Anak madayag Ka.<br/>',NULL,18245,1);
INSERT INTO stanza VALUES('CB837','2','Gibuhat mi sa dagway Mo,<br/>Sa kagahum gihatagan,<br/>Apan mga kolonon man,<br/>Di diosnon bisag gamay lang.<br/>',NULL,18246,2);
INSERT INTO stanza VALUES('CB837','3','Kinabuhi Kang dawaton<br/>Kinaiya Mo maangkon;<br/>Ikaw’g kami mahiusa,<br/>Usang Lawas mapadayag.<br/>',NULL,18247,3);
INSERT INTO stanza VALUES('CB837','4','Mag-agayng kinabuhi Mo,<br/>Magpuno, magbag-o’s kalag;<br/>Mahimong hamiling bato,<br/>Sama sa dagway’s Ginoo.<br/>',NULL,18248,4);
INSERT INTO stanza VALUES('CB837','5','Apan amo gyung naamgo,<br/>Di kini aron daygon’s tawo,<br/>Materyal lang nga tukorong<br/>Mahimayaong balay Mo.<br/>',NULL,18249,5);
INSERT INTO stanza VALUES('CB837','6','Ihalad kong kaugalingon,<br/>Ikaw man ang maalamon;<br/>Matukod mi kon dugmokon,<br/>Nga balayng kinahanglan Mo.<br/>',NULL,18250,6);
INSERT INTO stanza VALUES('CB837','7','Natural ko dugmokon Mo,<br/>Batokang pagkalain ko,<br/>Di magkinaugalingon,<br/>Mausa’s tanang balaan.<br/>',NULL,18251,7);
INSERT INTO stanza VALUES('CB837','8','Ug mahimong Asawa Mo,<br/>Sa lawak kauban Nimo,<br/>Pa’muslang gugma Mong puno,<br/>Aron Ikaw makontento!<br/>',NULL,18252,8);
INSERT INTO stanza VALUES('CB838','1','Gimahal ko, O Ginoo,<br/>Plano Mo’s tabernaculo;<br/>Kon unsaon ’ni pagtukod,<br/>Madayag ang himaya Mo.<br/>',NULL,18253,1);
INSERT INTO stanza VALUES('CB838','2','Ang arka m’oy sentro’s tolda,<br/>Tolda pahuwayan lang ni’ni;<br/>Na’ ni’ning ’pulo ka sugo,<br/>Sa dayon na’ kini’s tolda.<br/>',NULL,18254,2);
INSERT INTO stanza VALUES('CB838','3','Arka nagpakita’s Dios-tawo,<br/>Dios sagol’s tawo, bulawa’g kahoy;<br/>Balaod pagpadayag’s Dios,<br/>Hingpit nagpuyo ni Cristo.<br/>',NULL,18255,3);
INSERT INTO stanza VALUES('CB838','4','Cristo sentro sa Iglesia<br/>Nga m’oy kapahulayan N’ya;<br/>Amahan anaang Cristo,<br/>Ug nagpuyo sa Iglesia.<br/>',NULL,18256,4);
INSERT INTO stanza VALUES('CB838','5','Ang tolda pagtubo’s arka,<br/>Kahoyng hal-opan’s bulawan;<br/>Iglesia pagtubong Cristo,<br/>Dios nga nasagol’s tawo nadayag.<br/>',NULL,18257,5);
INSERT INTO stanza VALUES('CB838','6','Mga tabla sangga’s tolda,<br/>Nagbarug’s suksokang sa’pi;<br/>Hal-op bulawan, may singsing,<br/>Mga balabag naglig-on.<br/>',NULL,18258,6);
INSERT INTO stanza VALUES('CB838','7','Iglesia balaang natigum<br/>Nagbarug’s katubsanang Cristo;<br/>Nabugkos sa Espiritu,<br/>Nahaum, natukod pag-ayo.<br/>',NULL,18259,7);
INSERT INTO stanza VALUES('CB838','8','Upat ka tabon sa tolda<br/>Sa Cristo’s Dios nagpakita;<br/>Nagtimaan’s ’yang himaya,<br/>Nagtabon sa puy-anan N’ya.<br/>',NULL,18260,8);
INSERT INTO stanza VALUES('CB838','9','Natabonan’s maong Cristo,<br/>Tanang balaan nausa;<br/>Nagpahimulos Kaniya,<br/>Diha N’ya natukod sila.<br/>',NULL,18261,9);
INSERT INTO stanza VALUES('CB838','10','Balaod gisulod’s arka,<br/>Arka gisulod sa tolda;<br/>Dios dihang Cristo’s Iglesia,<br/>Nadayag ang himaya N’ya.<br/>',NULL,18262,10);
INSERT INTO stanza VALUES('CB839','1','Ginoo, magkokolon,<br/>Ikaw magtutukod sab;<br/>Di lang ako umulon,<br/>Imo pa nga tukoron.<br/>Ako di lang kolonon,<br/>Buhi usab nga bato;<br/>Di lamang sudlanan Mo,<br/>Himoon sab nga templo.<br/>',NULL,18263,1);
INSERT INTO stanza VALUES('CB839','2','Hinimo mi’s kolonon,<br/>Imo nga transpormahon;<br/>Kanimo makabaton,<br/>Himo’ng batong mahalon,<br/>Ug tukoron pag-usa,<br/>Mahimo Mong Asawa,<br/>Ug Lawas nga usa ra<br/>Mausa, matagbaw Ka.<br/>',NULL,18264,2);
INSERT INTO stanza VALUES('CB839','3','Tinguha’g gimahal Mo<br/>Di lang bililhong bato,<br/>Kondi’ usang matukod,<br/>Mapuy-anang tinuod.<br/>Malangkubon nga Cristo,<br/>Gikin’hanglan’s Iglesia,<br/>Aron ang kadato Mo,<br/>Mosidlak gyud’s kasanag.<br/>',NULL,18265,3);
INSERT INTO stanza VALUES('CB839','4','Tinguha Mo ma’dayag<br/>Di’s esp’rituhanong tawo<br/>Nga nag-iyaiya ra,<br/>Kondi’s hiniusa gyud.<br/>Di maka’dayag Nimo<br/>Mga bahing nabulag,<br/>Lawas hino’ng naangay,<br/>Ang makahupnganan Mo.<br/>',NULL,18266,4);
INSERT INTO stanza VALUES('CB839','5','Tukora, O Ginoo,<br/>Uban’s mga balaan,<br/>Tanan segun’s plano Mo,<br/>Ihaum, idugtong ko.<br/>Kasinatia’g gasa<br/>Di ko ipasigarbo,<br/>Alang kini’s pagtukod,<br/>Aron mahimaya Ka.<br/>',NULL,18267,5);
INSERT INTO stanza VALUES('CB840','1','Luwasa sa kaugalingon,<br/>Ginoo, tukora ko<br/>Uban sa mga balaan,<br/>Mahimong Imong templo.<br/>Luwasa sa kinaiya,<br/>Kagarbo’g pag-inusara,<br/>Aron mapuy-anan Nimo,<br/>Sa tanang adlaw namo.<br/>',NULL,18268,1);
INSERT INTO stanza VALUES('CB840','2','Sa agay’s kinabuhi Mo<br/>Matransporma’g magtubo,<br/>Matukod, mausa Nimo’s<br/>Pakigtambayayongay;<br/>Han-ay’s Lawas mintinahon,<br/>Kabubut-on Mo buhaton,<br/>Silbehan, tabangang uban,<br/>Sa tuyo Mo magtuman.<br/>',NULL,18269,2);
INSERT INTO stanza VALUES('CB840','3','Pagsinati’g kahibalo,<br/>Ang ituboy di ako,<br/>Magpasakop ug modawat,<br/>Magpaangay lang’s Lawas;<br/>Mohawid’s Ulo, magtubo’s<br/>Pagtubo’g paggawi N’ya,<br/>Masumpay pag-usa’s sangkap’s<br/>Lutaha’g kaugatan.<br/>',NULL,18270,3);
INSERT INTO stanza VALUES('CB840','4','Gipalig-on’s Espiritu<br/>Ang tawo ko sa sulod,<br/>Aron sa gugma masayud<br/>Lalum, lapad, ug habog;<br/>Magpa’mu’s gyud’s kadato Mo,<br/>Makahupnganan Nimo,<br/>Motubo sa pagkahingkod,<br/>Ang Lawas Mo matukod.<br/>',NULL,18271,4);
INSERT INTO stanza VALUES('CB840','5','Sa balay’s Dios, sa Lawas Mo,<br/>Ginoo, tukora ko;<br/>Himo’ng hinugpong sudlanan,<br/>Ikaw makit-an’s tanan.<br/>Katahum’s balaang syudad,<br/>Dinhi’s yuta madayag,<br/>Tangkawang magsidlaksidlak’s<br/>Imong pagkabililhon.<br/>',NULL,18272,5);
INSERT INTO stanza VALUES('CB841','1','Ikawng kinabuhi,<br/>Nabuhi nako;<br/>Kahupnganan Ka’s Dios,<br/>Gihatag nako.<br/>Gibalaan ako’s<br/>Kinaiya Mo,<br/>Sa pagkabanhaw Mo,<br/>Nidaug ako.<br/>',NULL,18273,1);
INSERT INTO stanza VALUES('CB841','2','Agay’s kinabuhi,<br/>Naghayag nako,<br/>Dala’s espiritu<br/>Ambitay Nimo;<br/>Nagsangkap’s kin’hanglan,<br/>Tagbo’s sugo Mo,<br/>Aron magpahinlo,<br/>Magbarug Nimo.<br/>',NULL,18274,2);
INSERT INTO stanza VALUES('CB841','3','Dihog’s Espiritu,<br/>Magtuhop nako,<br/>Kalag, espiritu<br/>Suropan Nimo;<br/>Usbon tanang bahin<br/>Isama Nimo,<br/>Padangaton ako<br/>Sa pagkahamtong.<br/>',NULL,18275,3);
INSERT INTO stanza VALUES('CB841','4','Ang kinabuhi Mo,<br/>Dato, nag-awas,<br/>Kanunayng nagbag-o,<br/>Naggahum nako.<br/>Lamyong kamatayon,<br/>Him’ong kusganon,<br/>Gapos ko bugtoon<br/>Ug paawiton.<br/>',NULL,18276,4);
INSERT INTO stanza VALUES('CB841','5','Itugyan, Ginoo,<br/>Ang kaugalingon,<br/>Matuman lang Nimo<br/>Ang tinguha Mo.<br/>Di na mag-usab ko<br/>Sa kaugalingon,<br/>Magbabag sa Imong<br/>Buot buhaton.<br/>',NULL,18277,5);
INSERT INTO stanza VALUES('CB841','6','Mohunong na gyud ko’s<br/>Akong pangusog,<br/>Transpormaha ako<br/>Hangtud magawas;<br/>Tukora ko’s uban<br/>Hangtud makit-an<br/>Ang pagpadayag Mo<br/>Dinhi kanamo.<br/>',NULL,18278,6);
INSERT INTO stanza VALUES('CB843','1','Ginhawai’s kinabuhi Mo,<br/>Daw bukog akong nabulag;<br/>Ipahiuli ko, Ginoo,<br/>Ug ipausa’s Lawas Mo.<br/>',NULL,18279,1);
INSERT INTO stanza VALUES('CB843','2','Ginhawai’s kinabuhi Mo,<br/>Espiritu ko ginapos;<br/>Bugtoang gapos, buhii ko,<br/>Aron masagol’s Lawas Mo.<br/>',NULL,18280,2);
INSERT INTO stanza VALUES('CB843','3','Ginhawai’s kinabuhi Mo,<br/>Esp’ritu ko di kabangon,<br/>Dasiga ug maulian ko,<br/>Mag-ambit’s sangkap’s Lawas Mo.<br/>',NULL,18281,3);
INSERT INTO stanza VALUES('CB843','4','Ginhawai’s kinabuhi Mo,<br/>Way kalipayng espiritu;<br/>Tagbawa’g panalangini ko,<br/>Pahimuslang kadato’s Lawas.<br/>',NULL,18282,4);
INSERT INTO stanza VALUES('CB843','5','Ginhawai’s kinabuhi Mo,<br/>Pasaliga ko sa bug-os;<br/>Batoking pag-inusara ko,<br/>Aron mabuhi’s Lawas Mo.<br/>',NULL,18283,5);
INSERT INTO stanza VALUES('CB845','1','Hubaring esp’ritu! M’oy kin’hanglan:<br/>Masumpay unta’s tanang balaan;<br/>Di tinguhaon Ka’s paagi ko,<br/>Wa na’s kaugalingon, na’s pagtukod.<br/>',NULL,18284,1);
INSERT INTO stanza VALUES('CB845','2','Hubaring esp’ritu! M’oy hangyo ko,<br/>Di na mabilanggo’s kaugalingon;<br/>Kadugay ko nang na’s kaugalingon,<br/>Di kagawas kon di Mo luwason.<br/>',NULL,18285,2);
INSERT INTO stanza VALUES('CB845','3','Hubaring esp’ritu! Nag-ampo ko,<br/>Makagula unta’s kaugalingon;<br/>Aron moagay ang Espiritu,<br/>Presensya Mo makit-an na dayon.<br/>',NULL,18286,3);
INSERT INTO stanza VALUES('CB845','4','Hubaring esp’ritu! M’oy gusto ko,<br/>Mobiya na’s naandang paglain;<br/>Nakabus lang sa paningkamot ko,<br/>L’wasa’s kaugalingon, padatoa.<br/>',NULL,18287,4);
INSERT INTO stanza VALUES('CB845','5','Hubaring esp’ritu! Tinguha ko,<br/>Di na mabilanggo’s kaugalingon;<br/>Di na malimbongan ni Satanas,<br/>Magpa’mulos gyud’s pagkamao Mo.<br/>',NULL,18288,5);
INSERT INTO stanza VALUES('CB845','6','Hubaring esp’ritu! M’oy pangandoy,<br/>Di na magapos ni’s kaugalingon;<br/>Masagol na sa tanang balaan,<br/>Magpahimulos Nimo sa dayon.<br/>',NULL,18289,6);
INSERT INTO stanza VALUES('CB847','1','Nangandoy ko’s pakig-ambitay,<br/>Masagol’s mga balaan,<br/>Maluwas’ pagtinagsaanay,<br/>Matukod uban’s balaan.<br/>',NULL,18290,1);
INSERT INTO stanza VALUES('CB847','2','Nangandoy ko’s pakig-ambitay,<br/>Espiritu ko mabuksan,<br/>Maluwas pag-inusarahay,<br/>Magsimba uban’s balaan.<br/>',NULL,18291,2);
INSERT INTO stanza VALUES('CB847','3','Nangandoy ko’s pakig-ambitay,<br/>Espiritu ko mogula,<br/>Maluwas’ limbong’s kaugalingon,<br/>Sa nag-ulang modaug na.<br/>',NULL,18292,3);
INSERT INTO stanza VALUES('CB847','4','Nangandoy nga makig-ambitay,<br/>Makaampo duyog’s uban,<br/>Di na magpakaaron-ingnon,<br/>Tinuod makig-ambitay.<br/>',NULL,18293,4);
INSERT INTO stanza VALUES('CB847','5','Nangandoy nga makig-ambitay,<br/>Makaila’s pagbulot-an;<br/>Makig-ambitay’s pag-alagad<br/>Tambayayongan kong buhat.<br/>',NULL,18294,5);
INSERT INTO stanza VALUES('CB847','6','Tumana na kining pangandoy,<br/>Dasiga’s pakig-ambitay,<br/>Aron matukod nang balay Mo,<br/>Matumang gitinguha Mo.<br/>',NULL,18295,6);
INSERT INTO stanza VALUES('CB848','1','Kabulahan’s sacerdote,<br/>Tinawag, harianon;<br/>Ning katungdanan magsilbe,<br/>Bisan ug naulahi.<br/>',NULL,18296,1);
INSERT INTO stanza VALUES('CB848','chorus','Tanang pagtukod sa Lawas<br/>Nagsalig’s sacerdote;<br/>Pag-ampo sa espiritu<br/>Maoy katungdanan ko.<br/>',NULL,18297,2);
INSERT INTO stanza VALUES('CB848','2','Kon ning harianong tawag<br/>Motubag’s pagbuot N’ya,<br/>Sacerdote moalagad,<br/>Matukod ang iglesia.<br/>',NULL,18298,3);
INSERT INTO stanza VALUES('CB848','3','Ang atong gikinahanglan<br/>Magsacerdoteng tanan;<br/>Mobulig ug magkausa,<br/>Pagtukod sa iglesia.<br/>',NULL,18299,4);
INSERT INTO stanza VALUES('CB848','4','Sa pagkadaut’s iglesia,<br/>Sacerdote nangawa’;<br/>Kaluya’s esp’ritu nila,<br/>Wali ray nidagaya.<br/>',NULL,18300,5);
INSERT INTO stanza VALUES('CB848','5','Daghang nagsalig’s mensahe,<br/>Wali ray importante,<br/>Gipasagdan ang pag-ampo<br/>Ug pagbansay’s esp’ritu.<br/>',NULL,18301,6);
INSERT INTO stanza VALUES('CB848','6','Batoki’g ipahiangay<br/>Sa wali o pag-ampo;<br/>Uban sigeng dad-o’g ampo,<br/>Sama’s pagwali’s Pulong.<br/>',NULL,18302,7);
INSERT INTO stanza VALUES('CB848','7','Mag-alagad ra’s pag-ampo,<br/>Espiritu masagol;<br/>Wali’g ampo tagdo’g angay,<br/>Matukod ang iglesia.<br/>',NULL,18303,8);
INSERT INTO stanza VALUES('CB849','1','Ang mga sacerdote<br/>Mao ang batong buhi;<br/>Kini sila mabalay<br/>Sa pag-ampo kanunay.<br/>',NULL,18304,1);
INSERT INTO stanza VALUES('CB849','chorus','Dapit labing balaan,<br/>Kanunay nga abutan;<br/>Mag-ampo sa Ginoo,<br/>Pagtukod N’ya mahimo.<br/>',NULL,18305,2);
INSERT INTO stanza VALUES('CB849','2','Sacerdoteng magsilbe,<br/>Mahimong batong buhi;<br/>Kinahanglan magtuman<br/>Sa ilang katungdanan.<br/>',NULL,18306,3);
INSERT INTO stanza VALUES('CB849','3','Kanhi ang sacerdote,<br/>Mag-uban gyud sa tolda;<br/>I’gsilbe’s sacerdote,<br/>Mag-usa kining duha.<br/>',NULL,18307,4);
INSERT INTO stanza VALUES('CB849','4','Balayng espirituwal,<br/>Usa sa sacerdote;<br/>Pagtukod’s balay karon<br/>Buhat sa sacerdote.<br/>',NULL,18308,5);
INSERT INTO stanza VALUES('CB849','5','Ang mga sacerdote<br/>M’oy mopuno’s pagtukod;<br/>Makompletong balay’s Dios<br/>Kon mobuhat na sila.<br/>',NULL,18309,6);
INSERT INTO stanza VALUES('CB849','6','Pagtukod sa Dios ug tawo<br/>M’oy buhat’s sacerdote;<br/>Ning diosnong ambitayay<br/>Balaan magkausa.<br/>',NULL,18310,7);
INSERT INTO stanza VALUES('CB849','7','Kon esp’ritu masakot<br/>Sa pag-ampo, matukod,<br/>Masacerdote kita,<br/>Maghalad sa Ginoo.<br/>',NULL,18311,8);
INSERT INTO stanza VALUES('CB849','8','Mahalon ko, Ginoo,<br/>Ang pagkasacerdote;<br/>Mag-alagad, mag-ampo,<br/>Iglesia Mo matukod.<br/>',NULL,18312,9);
INSERT INTO stanza VALUES('CB851','1','Hiligugmaong balay Mo!<br/>Sa sawang Mo nangandoy ko;<br/>Naglaum sa presensya Mo,<br/>M’oy tuaw’s kasingkasing ko.<br/>',NULL,18313,1);
INSERT INTO stanza VALUES('CB851','2','Sa halaran’s mga halad,<br/>Ug halaran sa incienso,<br/>Gorion’s balay nakakaplag,<br/>Sayaw nakakaplag’s salag.<br/>',NULL,18314,2);
INSERT INTO stanza VALUES('CB851','3','Mahuyang daw gorion ako,<br/>Bulahan, kay na’s balay Mo;<br/>Nagsalig’s dugo’s halaran,<br/>Nagpa’mus’ inciensong daghan.<br/>',NULL,18315,3);
INSERT INTO stanza VALUES('CB851','4','Bulahang mga tawhana,<br/>Kusgan, kay nisalig Nimo;<br/>Naghunahuna’s dalan’s Sion,<br/>Sa kalisud wa magtagad.<br/>',NULL,18316,4);
INSERT INTO stanza VALUES('CB851','5','Bisan walog sa paghilak,<br/>Himo’ng yuta’s mga tubod;<br/>Pun-on gayud Nimo’s ulan,<br/>Panalangin’s akong dalan.<br/>',NULL,18317,5);
INSERT INTO stanza VALUES('CB851','6','Nagkalig-on nga nanglakaw,<br/>Makigkita’s Dios didto’s Sion;<br/>Ikaw ra gyuy gipangita,<br/>Grasya Mo kinahanglanon.<br/>',NULL,18318,6);
INSERT INTO stanza VALUES('CB851','7','Usang adlaw sa sawang Mo<br/>Labaw’s linibo sa gawas;<br/>Ma’y pang magbantay’s ganghaan Mo<br/>Kay’s magpuyo’s tolda’s dautan.<br/>',NULL,18319,7);
INSERT INTO stanza VALUES('CB851','8','Ikawng Adlaw, Ikawng taming,<br/>Grasya’g himaya sangkap Mo;<br/>Presensya Mo’g Ikaw mismo<br/>Nagtagbaw’s pangin’hanglan ko.<br/>',NULL,18320,8);
INSERT INTO stanza VALUES('CB851','9','Way kaayong ihikaw Mo,<br/>Sa tawong naggawi’s katarung,<br/>Ang mosalig bulahanon,<br/>Grasya’g himaya hatagan.<br/>',NULL,18321,9);
INSERT INTO stanza VALUES('CB852','1','Gimahal ko, O Ginoo,<br/>Ang Imong Iglesia;<br/>Kalipay’g gikahimut-an,<br/>Kapahulayan Mo.<br/>',NULL,18322,1);
INSERT INTO stanza VALUES('CB852','2','Alang n’ya gitugyan Nimo<br/>Ang Kaugalingon;<br/>Alang n’ya lawas ihalad,<br/>Pagtagbo’s gusto Mo.<br/>',NULL,18323,2);
INSERT INTO stanza VALUES('CB852','3','Alang n’ya kinabuhi Kang<br/>Ikinabuhi ko;<br/>Alang n’ya di’s kaugalingon,<br/>Mapuno s’ya Nimo.<br/>',NULL,18324,3);
INSERT INTO stanza VALUES('CB852','4','Ang Iglesia Asawa Mo,<br/>Makit-an Ka’s Lawas;<br/>S’yay kalipay’g tinguha ko,<br/>Ug gisaligan ko.<br/>',NULL,18325,4);
INSERT INTO stanza VALUES('CB852','5','Diha n’ya hingpit Mong sangkap<br/>Gipaambit nako;<br/>Diha n’ya bat’nan Mo ako,<br/>Magtagbaw Kanimo.<br/>',NULL,18326,5);
INSERT INTO stanza VALUES('CB852','6','Gimahal ko, O Ginoo,<br/>Iglesiang balay Mo;<br/>Magpuyo sa dayon didto,<br/>Di na gyud maglaag.<br/>',NULL,18327,6);
INSERT INTO stanza VALUES('CB854','1','Tanan nga balaan<br/>Bahin ni Cristo;<br/>Nagtambayayongay<br/>Sa pagkausa.<br/>',NULL,18328,1);
INSERT INTO stanza VALUES('CB854','2','Espiritu usa,<br/>Daghan mag gasa;<br/>Daghang kagamitan,<br/>Ginoo usa.<br/>',NULL,18329,2);
INSERT INTO stanza VALUES('CB854','3','Tanan nagkin’hanglan<br/>Sa usag usa;<br/>Tanan dunay luna<br/>Ug kagamitan.<br/>',NULL,18330,3);
INSERT INTO stanza VALUES('CB854','4','Sinukod’s grasya ta<br/>Ang mga gasa;<br/>Tagsatagsa’g angkon<br/>Sa iyang luna.<br/>',NULL,18331,4);
INSERT INTO stanza VALUES('CB854','5','Tanan magtuman sa<br/>Katungdanan n’ya,<br/>Espiritu kusgan<br/>Ug kasaligan.<br/>',NULL,18332,5);
INSERT INTO stanza VALUES('CB854','6','Naghaum, nagsangkap,<br/>Pina’gi’s grasya;<br/>Wa gyuy pagbingkilay,<br/>Cristo giuna.<br/>',NULL,18333,6);
INSERT INTO stanza VALUES('CB854','7','Iglesia, Lawas N’ya,<br/>Siya m’oy Ulo;<br/>Sa agay’s Esp’ritu,<br/>Kita mausa.<br/>',NULL,18334,7);
INSERT INTO stanza VALUES('CB860','1','Bulahan kaayo,<br/>Sa gugma nabugkos,<br/>Ambitay ta’s espiritu<br/>Sama gyud sa langit.<br/>',NULL,18335,1);
INSERT INTO stanza VALUES('CB860','2','Sa trono’s Amahan,<br/>Gibubong pag-ampo;<br/>Usang paglaum, tumong ta,<br/>Kalipay’g pagtagad.<br/>',NULL,18336,2);
INSERT INTO stanza VALUES('CB860','3','Usahang kasubo,<br/>Pas-anay’g kabug-at;<br/>Maghinilakay man ngani<br/>Tungod’s kahangawa.<br/>',NULL,18337,3);
INSERT INTO stanza VALUES('CB860','4','Kon magkabulag ta,<br/>Magsakit gyung sulod;<br/>Apan usa’s kasingkasing,<br/>Magkita pag-usab.<br/>',NULL,18338,4);
INSERT INTO stanza VALUES('CB860','5','Magawas’ kasubo,<br/>Kasakit, kahago;<br/>Maghari ang gugmang hingpit,<br/>Hangtud’s eternidad.<br/>',NULL,18339,5);
INSERT INTO stanza VALUES('CB863','1','Sa inadlawng gawi’g mga tigum,<br/>Si Cristo m’oy sentro ug tanan ta;<br/>Di alang sa porma ug doktrina,<br/>Alang ni Cristo ra nagtigum ta.<br/>',NULL,18340,1);
INSERT INTO stanza VALUES('CB863','2','S’yang dalan, kahayag’s kinabuhi,<br/>Naglakaw diha N’ya, gig’yahan N’ya;<br/>S’yang buhing tubig, buhing kalan-on,<br/>Kaon-inom N’ya ug mabusog ta.<br/>',NULL,18341,2);
INSERT INTO stanza VALUES('CB863','3','S’yang kamatuorang pamatud-an,<br/>Kinabuhing gipangalagad ta;<br/>S’yang Ginoo, S’yang gipadako ta,<br/>S’ya ang Ulo, ug gituboy ta S’ya.<br/>',NULL,18342,3);
INSERT INTO stanza VALUES('CB863','4','Sa Dios ug tawo Cristo m’oy tanan,<br/>S’ya m’oy nagtagbaw sa Dios ug nato;<br/>S’yay realidad sulod’s Iglesia—<br/>Tungod N’ya kinabuhi motubo.<br/>',NULL,18343,4);
INSERT INTO stanza VALUES('CB863','5','Mga awit ug mga pag-ampo,<br/>Pagpadayag sa realidad N’ya;<br/>Tanang kalihokan’s pag-ambitay,<br/>Pagpadayag sab sa pagbuhat N’ya.<br/>',NULL,18344,5);
INSERT INTO stanza VALUES('CB863','6','Tigum’s Ngalan N’ya, lihok’s Esp’ritu,<br/>Nga way hunahuna nga mag-una;<br/>Sa gahum N’ya mag-ampo, magdayeg,<br/>Gamitong espiritu uban S’ya.<br/>',NULL,18345,6);
INSERT INTO stanza VALUES('CB863','7','Tanan kalimtan, Cristo unongan,<br/>Gamiton ta S’ya hangtud mahamtong;<br/>Tanan isipon tang kapildehan,<br/>Maangkon lamang Siya nga tanan.<br/>',NULL,18346,7);
INSERT INTO stanza VALUES('CB864','1','Tigum tang may Cristong hatag,<br/>Sa kaping kadagaya N’ya,<br/>Kalan-ong ihalad sa Dios,<br/>Ipakita’s Cristo.<br/>',NULL,18347,1);
INSERT INTO stanza VALUES('CB864','chorus','Ipakita’s Cristo,<br/>Ipakita’s Cristo,<br/>Kapin N’ya dad-on’s iglesia,<br/>Ipakita’s Cristo.<br/>',NULL,18348,2);
INSERT INTO stanza VALUES('CB864','2','Diha Niya nabuhi ta,<br/>Naghago adlaw’g gabii,<br/>Magkausa sa kapin N’ya,<br/>Ipakita’s Cristo.<br/>',NULL,18349,3);
INSERT INTO stanza VALUES('CB864','3','Si Cristo ang kinabuhi,<br/>Tanang pagkamao’g buhat,<br/>Aron’s magkatigum na ta,<br/>Ikapakita S’ya.<br/>',NULL,18350,4);
INSERT INTO stanza VALUES('CB864','4','Cristo dad-on’s mga tigum,<br/>Ipaambit’s usa’g usa,<br/>Dios makapa’mulos N’ya didto,<br/>Ipakita’s Cristo.<br/>',NULL,18351,5);
INSERT INTO stanza VALUES('CB864','5','Nabanhawng Cristo dad-on’s Dios,<br/>Cristong nikayab ihalad,<br/>Pagtubag’s makatagbaw’s Dios,<br/>Ipakita’s Cristo.<br/>',NULL,18352,6);
INSERT INTO stanza VALUES('CB864','6','Ang sentro ug realidad,<br/>Kahimtang ug pangalagad,<br/>Sa tanang tigum alang ra<br/>Sa pagpakita N’ya.<br/>',NULL,18353,7);
INSERT INTO stanza VALUES('CB864','7','Panghimatuod, pag-ampo,<br/>Ug tanang panag-ambitay,<br/>Paggamit ba’s gasa, tanan<br/>Magpakitang Cristo.<br/>',NULL,18354,8);
INSERT INTO stanza VALUES('CB864','8','Mahimaya tang Amahan,<br/>Niana matuboyng Anak,<br/>Matagbo ang tuyo’s tigum,<br/>Ipakita’s Cristo.<br/>',NULL,18355,9);
INSERT INTO stanza VALUES('CB865','1','Sa esp’ritu’g kamat’oran,<br/>Nagtigum, nagsimba;<br/>Tinudloan kami’s Anak,<br/>Manuol Kanimo.<br/>',NULL,18356,1);
INSERT INTO stanza VALUES('CB865','2','Salamat Espiritu Ka,<br/>Duol, mahal namo;<br/>Makontak nga kinabuhi,<br/>Simba’s kamat’oran.<br/>',NULL,18357,2);
INSERT INTO stanza VALUES('CB865','3','Gibuhata’g espiritu,<br/>Makasimba Nimo,<br/>Di sa gawas makigbisug,<br/>Mangita sa sulod.<br/>',NULL,18358,3);
INSERT INTO stanza VALUES('CB865','4','Gianak Niya pag-usab,<br/>Gibag-ong pangisip,<br/>Nagpuyo S’ya’s sulod nato,<br/>Tinu’d makasimba.<br/>',NULL,18359,4);
INSERT INTO stanza VALUES('CB865','5','Magsimba dinhi subay gyud<br/>Sa pagbati’s sulod,<br/>Magpadayag’s kahupnganan<br/>N’ya, sa Espiritu.<br/>',NULL,18360,5);
INSERT INTO stanza VALUES('CB865','6','Magsilbe’g magsimba sab sa<br/>Kamatuoran gyud,<br/>Dihang Cristo, di sa landong,<br/>Amahan simbahon.<br/>',NULL,18361,6);
INSERT INTO stanza VALUES('CB865','7','Si Cristo nga nasinati<br/>Ihalad nato’s Dios;<br/>Magkalipay ta uban’s Dios,<br/>Sa Iyang katam-is.<br/>',NULL,18362,7);
INSERT INTO stanza VALUES('CB865','8','Sa esp’ritu’g realidad<br/>Magtigum ta dinhi,<br/>Magdayeg, mag-ambit, magsimba,<br/>Libot sa trono N’ya.<br/>',NULL,18363,8);
INSERT INTO stanza VALUES('CB866','1','Bansayong esp’ritu!<br/>Di hunahuna;<br/>Magkatigumay ta,<br/>Tahurong Lawas.<br/>',NULL,18364,1);
INSERT INTO stanza VALUES('CB866','2','Bansayong esp’ritu!<br/>Di’s tanang porma;<br/>Mag-ambitayay ta,<br/>Ambitan’s Cristo.<br/>',NULL,18365,2);
INSERT INTO stanza VALUES('CB866','3','Bansayong esp’ritu!<br/>Di magnatural;<br/>Mag-alagaray ta,<br/>Iwali’s Cristo.<br/>',NULL,18366,3);
INSERT INTO stanza VALUES('CB866','4','Bansayong esp’ritu!<br/>Dili na’s kalag;<br/>Magtinabangay ta,<br/>Mosalig Niya.<br/>',NULL,18367,4);
INSERT INTO stanza VALUES('CB866','5','Gawas na’s esp’ritu<br/>Sa pagmatarung<br/>O pagsaway ba<br/>Sa kaugalingon.<br/>',NULL,18368,5);
INSERT INTO stanza VALUES('CB866','6','Gawas na’s esp’ritu<br/>Sa kaugalingong<br/>Paghiguma’g garbo,<br/>Tanan gidaug.<br/>',NULL,18369,6);
INSERT INTO stanza VALUES('CB866','7','Bansayong esp’ritu,<br/>Ato’ng pagdaug<br/>Sa dugong mohinlo’g<br/>Ngalang gamhanan.<br/>',NULL,18370,7);
INSERT INTO stanza VALUES('CB866','8','Bansayong esp’ritu<br/>Sa pagtandog N’ya;<br/>Pina’gi’s esp’ritu<br/>Kan-on S’ya’s Pulong.<br/>',NULL,18371,8);
INSERT INTO stanza VALUES('CB866','9','Pina’gi’s esp’ritu<br/>Isaksi’s Cristo;<br/>Pina’gi’s esp’ritu<br/>Matagbaw ang tawo.<br/>',NULL,18372,9);
INSERT INTO stanza VALUES('CB866','10','Bansayong esp’ritu!<br/>M’oy kinahanglan!<br/>Bansayong esp’ritu!<br/>G’yahan unta N’ya!<br/>',NULL,18373,10);
INSERT INTO stanza VALUES('CB867','1','Magpadayag ni Cristo<br/>Kitang bahin’s Lawas,<br/>Tanan magtuo’g lihok,<br/>Magpadayag Niya.<br/>Di mga mananan-aw,<br/>Bahin gyung molihok,<br/>Way tigda’g kamatayon,<br/>Lunlon mapuslanon.<br/>',NULL,18374,1);
INSERT INTO stanza VALUES('CB867','2','Di mag-inato’g lihok,<br/>Usa ka team kita,<br/>Magtinambayayongay<br/>Ug magsinaligay;<br/>Di ta magbuotbuot,<br/>Magsunod lang’s agay,<br/>Lipatlipat di magda’,<br/>Masayud’s gawi N’ya.<br/>',NULL,18375,2);
INSERT INTO stanza VALUES('CB867','3','Di maglain ug sentro,<br/>Tutok lang ni Cristo;<br/>Moambit’s kadato N’ya’s<br/>Tam-is nga ambitay.<br/>S’yay Ulo’g sulod nato,<br/>I’dayag Lawas N’ya;<br/>Bisan unsay buhaton<br/>Ipakita gyud S’ya.<br/>',NULL,18376,3);
INSERT INTO stanza VALUES('CB867','4','Matukod diha’s gugma,<br/>Wala gyuy manaway;<br/>Hingpitay’s usag usa,<br/>Buhat natong tanan.<br/>Mal’was sa kaugalingon,<br/>Mob’ya’s natural ta;<br/>Mabansay’s espiritu<br/>Mabuhi sa Lawas.<br/>',NULL,18377,4);
INSERT INTO stanza VALUES('CB868','1','Sa dili pa kami magkabulag,<br/>Magpasalamat kami pag-usab,<br/>Sa presensya Mo’g grasyang naglunhaw,<br/>Nga dato Mong gipaambit namo.<br/>',NULL,18378,1);
INSERT INTO stanza VALUES('CB868','2','Bisan human nang tigum, sa grasya,<br/>Presensya Mo di gyud mob’ya namo;<br/>Kusog Mong nagsustener kanamo<br/>Sa gugma way hunong nga ihatag.<br/>',NULL,18379,2);
INSERT INTO stanza VALUES('CB868','3','Presensya mag-uban unta namo,<br/>L’wan namo’s kasingkasing pas-ana,<br/>Aron mapahimuslan Ka namo,<br/>Hangtud’s sunod nga panagkatigum.<br/>',NULL,18380,3);
INSERT INTO stanza VALUES('CB869','1','Sa di pa mi magbulag, daygon Ka,<br/>Sa buhing Pulong Mo ug presensya;<br/>Nadani kami’s kabililhon Mo,<br/>Kasingkasing nadani’s nadungog.<br/>',NULL,18381,1);
INSERT INTO stanza VALUES('CB869','2','Pulong kinabuhi’g espiritu,<br/>Nagtil-og, nagpatubo kanamo;<br/>Aron matransporma sa dagway Mo,<br/>Ug motubo sa hingkod Mong sukod.<br/>',NULL,18382,2);
INSERT INTO stanza VALUES('CB869','3','Ipaambit ang Kaugalingon Mo,<br/>Paggawia kami’s espiritu,<br/>Aron sigeng mag-ambitay Nimo,<br/>Hangtud’s sunod nga panagkatigum.<br/>',NULL,18383,3);
INSERT INTO stanza VALUES('CB870','1','Tindog alang kang Jesus!<br/>Mga sundalo’s krus;<br/>Ikayab ang bandila,<br/>Di gyud magpadaug,<br/>Daghan nga kadaugan<br/>Iya na nga gidag-an,<br/>Hangtud ka’way maparot<br/>Ug S’ya Ginoo gyud.<br/>',NULL,18384,1);
INSERT INTO stanza VALUES('CB870','2','Tindog alang kang Jesus!<br/>Ang tawag N’ya sundon;<br/>Ngadto’s gubat padayon<br/>Ning adlaw’s himaya.<br/>Siya ang alagaran<br/>Batok’s kaawayng daghan;<br/>Magmaisugon lamang’s<br/>Kapeligrohanan.<br/>',NULL,18385,2);
INSERT INTO stanza VALUES('CB870','3','Tindog alang kang Jesus!<br/>Kusog N’ya saligan;<br/>Kay di gyud kasaligan<br/>Ang unodnong kusog.<br/>Hinagiban isul-ob<br/>Sa maayong balita,<br/>Magtukaw ug mag-ampo,<br/>Sa tawag magtagbo.<br/>',NULL,18386,3);
INSERT INTO stanza VALUES('CB870','4','Tindog alang kang Jesus!<br/>Gubat di magdugay;<br/>Karon kasaba’s gubat,<br/>Ugma awit’s pagdaug;<br/>Mananaug maghari,<br/>Purongan’s kinabuhi,<br/>Uban’s Hari’s himaya<br/>Sa dayon maghari.<br/>',NULL,18387,4);
INSERT INTO stanza VALUES('CB871','1','Kuyog Cristohanon<br/>Sa panggubatan!<br/>Ug ang krus ni Jesus<br/>Mag-una’s tanan.<br/>Si Cristo Pangulo<br/>Magmamando ta,<br/>Padayon sa bugno<br/>Sa unahan pa.<br/>',NULL,18388,1);
INSERT INTO stanza VALUES('CB871','chorus','Kuyog Cristohanon<br/>Kay may gubat pa!<br/>Ug ang krus ni Jesus<br/>Mag-una’s tanan!<br/>',NULL,18389,2);
INSERT INTO stanza VALUES('CB871','2','Sa ngalan ni Jesus<br/>Yawa modagan;<br/>Ug ang Cristohanon<br/>May kadaugan!<br/>Ang Hades mokurog<br/>Sa singgit’s pagdayeg;<br/>Ipatugbawng tingog,<br/>Awit’s makusog!<br/>',NULL,18390,3);
INSERT INTO stanza VALUES('CB871','3','Sama’s kasundalohan<br/>Ang Iglesia’s Dios:<br/>Sa tunob’s balaan<br/>Nagsunod kita;<br/>Usa ta ka Lawas,<br/>Wa gyud mabahin,<br/>Usa sa pagtoo<br/>Ug Espiritu.<br/>',NULL,18391,4);
INSERT INTO stanza VALUES('CB871','4','Mga gingharian<br/>Mangapukan man,<br/>Ang Iglesiang Jesus<br/>Way katapusan.<br/>Ganghaan sa Hades,<br/>Di gyud ’kapukan,<br/>Kay ang saad sa Dios<br/>Way kapakyasan.<br/>',NULL,18392,5);
INSERT INTO stanza VALUES('CB871','5','Busa magpadayon<br/>Kita nga tanan;<br/>Isinggit ang tingog<br/>Sa kadaugan.<br/>Dungog ug himaya<br/>Alang kang Cristo,<br/>Ngalan N’ya awiton<br/>Sa tanan daygon.<br/>',NULL,18393,6);
INSERT INTO stanza VALUES('CB873','1','Sulong, mga sundalo!<br/>Nagsugod nang gubat;<br/>Singgit nga madaugon—<br/>“Nakadaug na ta!“<br/>Kusog’s Yawa bungkagon,<br/>Gahum’s Hades wad-on;<br/>Kapitan’s kasundal’han<br/>Moabot, modaug.<br/>',NULL,18394,1);
INSERT INTO stanza VALUES('CB873','2','Sulong, mga sundalo!<br/>Tutok sa Ginoo;<br/>Kon moaway alang N’ya,<br/>Gantihan sa trono.<br/>Gubat iya’s esp’ritu,<br/>Di manukad’s yuta;<br/>Ginoo nasayud gyud<br/>Kaaway naglibot.<br/>',NULL,18395,2);
INSERT INTO stanza VALUES('CB873','3','Sulong, mga sundalo!<br/>Naghulat ’yang trono;<br/>Gahum N’ya’s pagkabanhaw<br/>Mag-isa’s esp’ritu.<br/>Pina’gi N’ya gamhan mo;<br/>Pagbuntog’s kaaway;<br/>Mag-awit’s kadaugan,<br/>Ug Iyang purongan.<br/>',NULL,18396,3);
INSERT INTO stanza VALUES('CB873','4','Sulong, mga sundalo!<br/>Mosaka mo’s trono,<br/>Kombira giandam N’ya,<br/>Alang gayud ninyo.<br/>Uban N’ya nabanhaw ta,<br/>Ibabaw’s kasamok;<br/>Labaw’s tanang naggapos,<br/>Diha N’ya habog ta.<br/>',NULL,18397,4);
INSERT INTO stanza VALUES('CB873','5','Sulong, mga sundalo!<br/>Kamoy manununod;<br/>Gipili gikan’s abug,<br/>Moambit’s trono N’ya.<br/>Sa kangitngit wala na,<br/>Sanag ang ugma ta;<br/>Makig-uban N’ya’s dayon<br/>Malipay’s gugma N’ya.<br/>',NULL,18398,5);
INSERT INTO stanza VALUES('CB873','6','Uban’s paghugyaw sulong!<br/>Na’ nang gingharian;<br/>Didto’s tumoy sa Sion,<br/>Mag-awit’s pagdaug.<br/>Nidaug nang Cordero!<br/>Naa na S’ya’s trono!<br/>Uban’s paghugyaw daygon<br/>Kay S’ya madaugon.<br/>',NULL,18399,6);
INSERT INTO stanza VALUES('CB876','1','Kon gubat mapintas,<br/>Yawa mangtas,<br/>Saliging Pulong’s Dios<br/>Mag-awit gyud.<br/>',NULL,18400,1);
INSERT INTO stanza VALUES('CB876','2','Singgit lang ug kas-a,<br/>Modaug ka;<br/>Baba di tak-omon<br/>Kay dag-on ka.<br/>',NULL,18401,2);
INSERT INTO stanza VALUES('CB876','3','Kon espiritu mo,<br/>Walay kusog,<br/>Ampo, salig’s dugo,<br/>Modaug gyud.<br/>',NULL,18402,3);
INSERT INTO stanza VALUES('CB876','4','Kapintas’ kaaway,<br/>Awayon gyud;<br/>Kon lig-ong mobarug,<br/>S’ya mokurog.<br/>',NULL,18403,4);
INSERT INTO stanza VALUES('CB876','5','Busa imantala<br/>Pagdaug N’ya;<br/>Kahimtang mangiob<br/>Mohayag ra.<br/>',NULL,18404,5);
INSERT INTO stanza VALUES('CB877','1','Di gyud ako padaug<br/>Kay naang Calvario,<br/>Diin yawa gibuntog<br/>Sa atong Ginoo;<br/>Ginoo, bugnai ko<br/>Pag-asdang sa gubat,<br/>Himoang mananaug<br/>Gamhi’s Espiritu.<br/>',NULL,18405,1);
INSERT INTO stanza VALUES('CB877','chorus','Nidaug! nidaug!<br/>Tungod sa Calvario;<br/>Himoang mananaug,<br/>Diha gyud Kanimo, Ginoo.<br/>',NULL,18406,2);
INSERT INTO stanza VALUES('CB877','2','Di gyud ako padaug,<br/>Tungod kay si Cristo<br/>Nagtawag nako’s gubat<br/>Nga gidaug na N’ya.<br/>Hatagi ko’s kaisug<br/>Ug sa Espiritu,<br/>Himoang mananaug,<br/>Puy-i sa gahum Mo.<br/>',NULL,18407,3);
INSERT INTO stanza VALUES('CB877','3','Di gyud ako padaug,<br/>Si Jesus nagmando,<br/>Sulong ngadto sa Hades,<br/>Moambit’s ’yang Trono;<br/>Hatagi ko sa kusog<br/>Pagbakyaw’s espada,<br/>Himoang mananaug<br/>Sa hingpit Mong Pulong.<br/>',NULL,18408,4);
INSERT INTO stanza VALUES('CB877','4','Di gyud ako padaug,<br/>Adlaw nanghinapos,<br/>“Maayong pagkabuhat“<br/>Unya akong balus;<br/>O Ginoo tugahi<br/>Ko sa Espiritu,<br/>Himoang mananaug<br/>Hangtud’s katapusan.<br/>',NULL,18409,5);
INSERT INTO stanza VALUES('CB880','1','Alang sa kaaway mo-“Dili“<br/>Ug sa Amahan “Oo,“<br/>Aron Iyang tambag, plano<br/>Hingpit gyud nga mahuman;<br/>Sa pagsugot ko’s sugo Mo,<br/>Hatagi’s kagahum Mo,<br/>Sa pagtuman sa plano Mo,<br/>Gamhi ako, Ginoo.<br/>',NULL,18410,1);
INSERT INTO stanza VALUES('CB880','2','Alang sa kaaway mo-“Dili“<br/>Ug sa Amahan “Oo“;<br/>Kini gyud ang akong harong,<br/>Iya kong bulahanon.<br/>Basig sa akong pagsugot,<br/>Si Satanas modaut,<br/>Busa kaloy-i, Ginoo,<br/>Sa pagsugot’s sugo Mo.<br/>',NULL,18411,2);
INSERT INTO stanza VALUES('CB880','3','Alang sa kaaway mo-“Dili“<br/>Ug sa Amahan “Oo“;<br/>Sa hingpit ako mosugot,<br/>Bisan pa ug mag-antus.<br/>L’wason, ampingan’s Ginoo,<br/>Sa pagsunod ko Niya,<br/>Way pagsulayng makaulang,<br/>Bisan kaawayng tanan.<br/>',NULL,18412,3);
INSERT INTO stanza VALUES('CB885','1','Makiggubat diha’s Lawas,<br/>Dili mag-inusara;<br/>Makiggubat dugtong’s Ulo,<br/>Didto gayud sa trono.<br/>',NULL,18413,1);
INSERT INTO stanza VALUES('CB885','chorus','Makiggubat diha’s Lawas,<br/>Pinaagi sa Ulo;<br/>Uban’s Lawas magmalig-on,<br/>Kadaugan maangkon.<br/>',NULL,18414,2);
INSERT INTO stanza VALUES('CB885','2','Hinagiban alang’s Lawas,<br/>Di alang kanimo ra;<br/>Kon sa Lawas makigbisug,<br/>Kaayohan maimo.<br/>',NULL,18415,3);
INSERT INTO stanza VALUES('CB885','3','Iglesia nga tinukod’s Dios,<br/>Di dag-on ni Satanas;<br/>Kini natukod nga Lawas<br/>Nga mosukol’s kaaway.<br/>',NULL,18416,4);
INSERT INTO stanza VALUES('CB885','4','Sa Lawas, Ulo saligan,<br/>Maglingkod ka sa langit;<br/>Imong suklan ang dautan,<br/>Ug mga pamunoan.<br/>',NULL,18417,5);
INSERT INTO stanza VALUES('CB885','5','Uban sa kaigsoonan,<br/>Magbarug tang bahin N’ya;<br/>Mag-ampo sa Espiritu,<br/>Modaug sa Dugo N’ya.<br/>',NULL,18418,6);
INSERT INTO stanza VALUES('CB885','6','Naglingkod sa kalangitan,<br/>Nidaug gayud’s tanan;<br/>Makiggubat diha Niya,<br/>Mga sundalo kita.<br/>',NULL,18419,7);
INSERT INTO stanza VALUES('CB885','7','Sa Lawas kon makigbisug,<br/>Makita ang pagdaug;<br/>Kaaway atong gapuson,<br/>Sila himo’ng kalan-on.<br/>',NULL,18420,8);
INSERT INTO stanza VALUES('CB886','1','Atong Dios m’oy lig-ong Salipdanan,<br/>Panalipod nga di mabuntog;<br/>Sa tanang pagsulay S’yang Katabang,<br/>Gidaug tanang katalagman:<br/>Kaaway tang daan<br/>Gusto gyung modaut;<br/>Kusgan s’yag limbongan,<br/>Yuta way dag-anan<br/>Sa kapungot n’ya’g kadautan.<br/>',NULL,18421,1);
INSERT INTO stanza VALUES('CB886','2','Nagsalig ba kita’s atong kusog,<br/>Mapilde gyud ta’s panlimbasug;<br/>Di ba nia S’ya dapig nato,<br/>S’ya nga pinili gyud sa Dios:<br/>Mangutana pa ba?<br/>Di ba’s Jesucristo;<br/>Ngalan N’ya Ginoo,<br/>Wa gyuy pagkausab,<br/>Pirmi gayud nga modaug.<br/>',NULL,18422,2);
INSERT INTO stanza VALUES('CB886','3','Bisan puno’s demonyong yuta,<br/>Sigeng hulga nga patyon ta,<br/>Way kahadlok, kay ang Dios nagbuot;<br/>Dag-on s’ya’s kamatuoran:<br/>Modaug gyud’s dayon,<br/>Di gyud ta mangurog’s<br/>Principe’s Kangiob;<br/>Hagis n’ya antuson<br/>Kay malaglag s’ya’s usang pulong.<br/>',NULL,18423,3);
INSERT INTO stanza VALUES('CB886','4','Pulong nga labaw’s tanang gahum,<br/>Nagpabilin di tungod nila;<br/>Espiritu’g gasa atoa,<br/>Gikan N’yang Manlalaban ta:<br/>Ang butang palabya,<br/>Bisan kinabuhi;<br/>Mapatay mang lawas,<br/>Magpabiling pulong,<br/>Kini hangtud gayud’s dayon.<br/>',NULL,18424,4);
INSERT INTO stanza VALUES('CB887','1','Ngalan ni Jesus barugan,<br/>Maoy kadaugan;<br/>Di magsalig’s kaugalingon,<br/>Kondi’ sa Ginoo.<br/>Gubat espirituhanon,<br/>Ug dili unodnon,<br/>Hinagiban’s Dios isul-ob,<br/>Kita makigbisug.<br/>',NULL,18425,1);
INSERT INTO stanza VALUES('CB887','2','Mga kaaway nagsabut,<br/>Lig-on tang magbarug!<br/>Bisan mapintas ang gubat,<br/>Sukli diha Niya!<br/>Kon mahadlok ta’g modagan,<br/>Daghang madalahig.<br/>Ayaw pakyasang igsoon,<br/>Kaaway sulongon.<br/>',NULL,18426,2);
INSERT INTO stanza VALUES('CB887','3','Panahon n’ya hamubo na,<br/>Nasayran sa yawa;<br/>Busa sa di pa mapukan,<br/>Kabangis nagdugang.<br/>Kita paluyahon niya’s<br/>Mga kasakitan,<br/>Kusog sa Hades kaatbang<br/>Labi pang maglisang.<br/>',NULL,18427,3);
INSERT INTO stanza VALUES('CB887','4','Kangiob’s panahon karon,<br/>Unsay barugan mo?<br/>Mangita ba sa kasayon<br/>Aron iyang lamyon?<br/>Samtang kasamok magdugang,<br/>Isug bang mag-antus?<br/>Mabuhi’g mamatay dinhi!<br/>Daygon ba ta sa Dios?<br/>',NULL,18428,4);
INSERT INTO stanza VALUES('CB887','5','Alang ni Cristo mobarug,<br/>Siya Mananaug!<br/>Alang Niya makaantus’<br/>Tanang kasakitan.<br/>Takna’s pagdaug makita,<br/>Ginoo mobalik na;<br/>Kon mag-antus alang Niya,<br/>Maghari uban N’ya.<br/>',NULL,18429,5);
INSERT INTO stanza VALUES('CB889','1','Dag-ong kaaway sa dugo<br/>Ni Cristong Mananaug,<br/>Sa nahuma’g gahum ni’ni<br/>Maimong kadaugan.<br/>',NULL,18430,1);
INSERT INTO stanza VALUES('CB889','chorus','Dag-ong kaaway sa dugo<br/>Ni Cristong Mananaug,<br/>Sa nahuma’g gahum ni’ni<br/>Maimong kadaugan.<br/>',NULL,18431,2);
INSERT INTO stanza VALUES('CB889','2','Sukling nagsumbong nga yawa,<br/>Sa dugo’s Mananaug,<br/>Dugong modepensa nimo<br/>Sa pagdaut’s kaaway.<br/>',NULL,18432,3);
INSERT INTO stanza VALUES('CB889','3','Toohing Dios kasaligan,<br/>Sa dugo’s Mananaug,<br/>Dawatang pagpasaylo N’ya,<br/>Sa dugo’s Manunubos.<br/>',NULL,18433,4);
INSERT INTO stanza VALUES('CB889','4','Ipailang posisyon mo,<br/>Sa dugo’s Mananaug,<br/>Sa madaugong dugo N’ya,<br/>Ambit sa ’yang pagdaug.<br/>',NULL,18434,5);
INSERT INTO stanza VALUES('CB889','5','Angkonang pagbulot-an N’ya,<br/>Sa dugo’s Mananaug,<br/>Dugong Jesus gamita lang,<br/>Ug pildehang kaaway.<br/>',NULL,18435,6);
INSERT INTO stanza VALUES('CB889','6','Magbarug sa kalangitan,<br/>Sa dugo’s Mananaug,<br/>Sa gahum Niyang nikayab<br/>Yataking pamunoan.<br/>',NULL,18436,7);
INSERT INTO stanza VALUES('CB890','1','Daygon! Cristo Mananaug,<br/>Isulti gayud,<br/>Mananaug gihapon S’ya<br/>Sa kamatayon.<br/>',NULL,18437,1);
INSERT INTO stanza VALUES('CB890','chorus','Daygon! Cristo Mananaug,<br/>Isulti gayud,<br/>Mananaug gihapon S’ya<br/>Sa kamatayon.<br/>',NULL,18438,2);
INSERT INTO stanza VALUES('CB890','2','Daygon! Cristo Mananaug,<br/>Sakit mangagiw,<br/>Kon mangayo’s ’yang pagdaug<br/>Didto’s Calvario.<br/>',NULL,18439,3);
INSERT INTO stanza VALUES('CB890','3','Daygon! Cristo Mananaug,<br/>Isug mobuhat;<br/>Bisan asa ipada’ N’ya,<br/>Ampo la’g kusog.<br/>',NULL,18440,4);
INSERT INTO stanza VALUES('CB890','4','Daygon! Cristo Mananaug,<br/>Way pilde’g kulba<br/>Nga magpalong’s panan-awon mo<br/>S’yay hawan’s dalan.<br/>',NULL,18441,5);
INSERT INTO stanza VALUES('CB890','5','Daygon! Cristo Mananaug,<br/>Madungog na S’ya,<br/>“Ari mga mananaug,<br/>Kuyog sa Hari.”<br/>',NULL,18442,6);
INSERT INTO stanza VALUES('CB892','1','Gitugyan nang tanang kagahum,<br/>Sa nabanhaw nga Ginoo;<br/>Kon usang mabuhi Kan’ya,<br/>Kaaway mapasakop ta.<br/>',NULL,18443,1);
INSERT INTO stanza VALUES('CB892','2','Ideklarar’s ngalang Jesus<br/>Nga ang kaaway dag-on ta;<br/>Kagahum ta gikan Niya,<br/>Sa ulo’s bitin magdugmok.<br/>',NULL,18444,2);
INSERT INTO stanza VALUES('CB892','3','Bisan unsa kahabog’s bungtod,<br/>Sa langit ba o sa yuta,<br/>Mapatag ka namo gayud,<br/>Sa ngalang Jesus mobiya!<br/>',NULL,18445,3);
INSERT INTO stanza VALUES('CB892','4','Sugo’s pagtoo, “Pahawa!<br/>Ug matambog ka sa dagat!“<br/>Angay, mahimo, buhaton gyud,<br/>Tuyo’s Dios kita magsunod.<br/>',NULL,18446,4);
INSERT INTO stanza VALUES('CB893','1','Gubat karon kusog,<br/>Yawa nagkalig-on;<br/>Singgit’s gubat nidahunog,<br/>Nanawag gyud nato.<br/>Ang tingog sa hades<br/>Labi pang nikusog;<br/>Apan hapit na madungog,<br/>Ako mobalik na!<br/>',NULL,18447,1);
INSERT INTO stanza VALUES('CB893','2','Pags’way nagkapait,<br/>Gubat nagkadako;<br/>Pwersa’s hades gitingub gyud<br/>Pagsulong kanato.<br/>Pagtukaw nabati<br/>Ang kakusog’s gubat,<br/>Nadungog tang sadyang awit,<br/>Duol na si Jesus!<br/>',NULL,18448,2);
INSERT INTO stanza VALUES('CB893','3','Labi pang malisud<br/>Pagmatuod’s pulong,<br/>Kay Satanas mangusog gyud<br/>Pag-ulang kanato.<br/>Kin’hanglan ang labawng<br/>Gahum modaug n’ya,<br/>Kalipayng makita ta S’ya,<br/>Tapos panghupaw ta!<br/>',NULL,18449,3);
INSERT INTO stanza VALUES('CB893','4','Kinsa may mosulong<br/>Diha sa gahum N’ya?<br/>Kinsay lig-ong mosalig N’ya<br/>Hangtud nga modaug;<br/>Hangtud sugdang awit’s<br/>Mga mananaug?<br/>Malipay s’yang makadungog,<br/>Magdali Ko’g balik!<br/>',NULL,18450,4);
INSERT INTO stanza VALUES('CB893','5','Kinsay mopili sa<br/>Labing maayo’s Dios?<br/>Molakaw sa dalang sigpit,<br/>Bisan agi’g unos?<br/>Kinsay mopadayon,<br/>Moantus kasakit?<br/>Silang tanan magkalipay,<br/>Duol nang Ginoo!<br/>',NULL,18451,5);
INSERT INTO stanza VALUES('CB893','6','Bisan mangitngit na,<br/>Padayon gihapon,<br/>Hangtud malalin, mosugat<br/>Sa himaya Niya.<br/>Didto makita S’ya,<br/>Satanas pilde na;<br/>Hugyaw’s mga mananaug,<br/>Nia na si Jesus!<br/>',NULL,18452,6);
INSERT INTO stanza VALUES('CB894','1','Buot ka ba makadaug?<br/>Cristo nagtawag!<br/>Mosunod ka ba N’ya bisan<br/>Di ka ’kamao?<br/>',NULL,18453,1);
INSERT INTO stanza VALUES('CB894','chorus','Buot ka ba makadaug,<br/>Maoy pilion,<br/>Nanawag si Cristo karon,<br/>S’ya pamation!<br/>',NULL,18454,2);
INSERT INTO stanza VALUES('CB894','2','Buot ka ba makadaug?<br/>Duol’s Ginoo!<br/>Unang gugma ay’g biyai,<br/>Hangtud’s kadlawon.<br/>',NULL,18455,3);
INSERT INTO stanza VALUES('CB894','3','Buot ka ba makadaug?<br/>Salig Kaniya!<br/>Antusong mga paglutos,<br/>Hangtud matapos.<br/>',NULL,18456,4);
INSERT INTO stanza VALUES('CB894','4','Buot ka ba makadaug?<br/>Pamatud-i S’ya!<br/>Palayo’s mining relih’yon,<br/>May “tagong manna.”<br/>',NULL,18457,5);
INSERT INTO stanza VALUES('CB894','5','Buot ka ba makadaug,<br/>Tinuod, yano?<br/>Dag-a ang dautang sambog,<br/>Pagbu’t maimo.<br/>',NULL,18458,6);
INSERT INTO stanza VALUES('CB894','6','Buot ka ba makadaug?<br/>Salig’s Ginoo!<br/>Ay’g pahugaw’s pagkapatay,<br/>Dag-ang kinabuhi.<br/>',NULL,18459,7);
INSERT INTO stanza VALUES('CB894','7','Buot ka ba makadaug?<br/>Di magdagaang,<br/>Di makontento’s na’ nimo,<br/>Daghang maimo.<br/>',NULL,18460,8);
INSERT INTO stanza VALUES('CB894','8','Buot ka ba makadaug?<br/>S’ya nagtawag pa!<br/>Magmaunongon ka ba N’ya,<br/>Magtuman’s sugo.<br/>',NULL,18461,9);
INSERT INTO stanza VALUES('CB907','1','Dili sa pagpili ta,<br/>Kondi’s Iyang paggiya,<br/>Buhing tubig mag-agay,<br/>Dulom him’ong kahayag.<br/>',NULL,18462,1);
INSERT INTO stanza VALUES('CB907','2','Di ang gipiling buhat,<br/>Ang unya Iyang daygon;<br/>Kondi’ ang alang ra N’ya,<br/>Ug wa ta pangayoa.<br/>',NULL,18463,2);
INSERT INTO stanza VALUES('CB907','3','Di pangandoyng iampo<br/>Pagluhod sa ’yang Trono,<br/>Kondi’ ang pangin’hanglang<br/>Giagulo’s Esp’ritu.<br/>',NULL,18464,3);
INSERT INTO stanza VALUES('CB907','4','Di ang garbong gihalad<br/>Ang Iya nga gitagad,<br/>Kon sulod ta nidili<br/>Sa gikinahanglan N’ya.<br/>',NULL,18465,4);
INSERT INTO stanza VALUES('CB907','5','Pagkamatay, mabuhi’s<br/>Kalangitan uban N’ya;<br/>Niana mosilbe, ampo,<br/>Cristo mismo balus ta.<br/>',NULL,18466,5);
INSERT INTO stanza VALUES('CB908','1','Espiritu ug di’s letra,<br/>Paagi’s Bag-ong Tugon;<br/>Magbuhi gyung espiritu,<br/>Apan mopatayng letra.<br/>Alang’s Dios buhat way bili<br/>Kon dili gikan’s sulod;<br/>Mag-alagad di linetra,<br/>Kondi’ sa kinabuhi.<br/>',NULL,18467,1);
INSERT INTO stanza VALUES('CB908','2','Lihok di pagtudlo’s gawas,<br/>Kondi’ sa pagdihog N’ya;<br/>Pinaagi’s panan-awon,<br/>Di sa sumbanan’s gawas.<br/>Di’s tawhanong mga lagda,<br/>Kondi’s pagbuot’s langit;<br/>Di sa desisyon sa tawo,<br/>Kondi’ sa paggiya N’ya.<br/>',NULL,18468,2);
INSERT INTO stanza VALUES('CB908','3','Ikinabuhi si Cristo,<br/>Di ang patayng relihiyon;<br/>Ang ihatag buhing Cristo,<br/>Di mga teolohiya.<br/>Di kahibalo’s doktrina,<br/>Kondi’ Cristo’y mensahe,<br/>Di pagtudlo, gasa, porma,<br/>Kondili Cristo sa Dios.<br/>',NULL,18469,3);
INSERT INTO stanza VALUES('CB908','4','Di objectibong pagsimba,<br/>Alagaran S’ya’s sulod;<br/>Di objectibong magsangyaw,<br/>Kondi’ ipasinati.<br/>Di lang silbehan’s Biblia<br/>Kondi’ sa espiritu;<br/>Sa Espiritu, di’s unod,<br/>Magawas, magpapuno.<br/>',NULL,18470,4);
INSERT INTO stanza VALUES('CB909','1','Sa sulog! sa sulog! mobuhat alang N’ya,<br/>Sa hunahuna N’yang gipadayag’s Pulong;<br/>Sa agay’s kinabuhi, buhat’s gahum N’ya,<br/>Alang’s Gingharia’g Iglesia’s takna N’ya.<br/>',NULL,18471,1);
INSERT INTO stanza VALUES('CB909','chorus','Sa sulog! sa sulog!<br/>Mobuhat gyud kita!<br/>Sa sulog! sa sulog!<br/>Mobuhat ingog “team’s” langit!<br/>',NULL,18472,2);
INSERT INTO stanza VALUES('CB909','2','Sa sulog! sa sulog! mobuhat alang N’ya,<br/>Sa agay’s Esp’ritu, pagtudlo’s Pulong N’ya;<br/>Dili gawasnon, mag-inato ug buhat,<br/>Mag-alagad kita nga may pagkausa.<br/>',NULL,18473,3);
INSERT INTO stanza VALUES('CB909','3','Sa sulog! sa sulog! mobuhat alang N’ya,<br/>Uban’s Iglesia, sa kahayag’s Pulong N’ya;<br/>Ihatag ang Pulong, sangkap’s kinabuhi,<br/>Magtuman’s plano’s Dios, magpadayon’s agay.<br/>',NULL,18474,4);
INSERT INTO stanza VALUES('CB910','1','Ang buhat, pagkinabuhi,<br/>Inawas’ kinabuhi;<br/>Ang imensahe nato’s tawo,<br/>Pagsinati gyud nato.<br/>Buhat ug kinabuhi kon<br/>Usa, magmapuslanon;<br/>Mensahe’g kinabuhi kon<br/>Usa, pulong molampos.<br/>',NULL,18475,1);
INSERT INTO stanza VALUES('CB910','2','Buhat—bunga’s kinabuhi,<br/>Da’s agay’s Espiritu;<br/>Isip mga sanga Niya,<br/>Mamunga, magpabuhi.<br/>Cristo mismo m’oy mobuhat,<br/>Aron mapadayag S’ya,<br/>Kadato’s kinabuhi N’ya<br/>Ipakita sa uban.<br/>',NULL,18476,2);
INSERT INTO stanza VALUES('CB910','3','Di ni kalihokan sa tawo,<br/>Gahum N’yay nagpalihok;<br/>Di binuhatan sa gawas,<br/>Paglihok ’noon’s sulod.<br/>Pagpaila’s kinabuhi,<br/>Di buhat’s patigayon;<br/>Di paghago nga molampos,<br/>S’ya mismo nagpadayag.<br/>',NULL,18477,3);
INSERT INTO stanza VALUES('CB910','4','Plano, tumong, kusog nato,<br/>B’yaan gyud natong tanan,<br/>S’yay buhat’s plano N’ya nato,<br/>Ang Iya ra gyung tumong.<br/>Tanang pagkamao’g ato,<br/>Itahan’s kamatayon,<br/>Aron mabuhi S’ya nato,<br/>May himaya’g kadato.<br/>',NULL,18478,4);
INSERT INTO stanza VALUES('CB911','1','Bulahan ang sacerdote,<br/>Cristo’y tanan’s tanan n’ya,<br/>Pagkaon, biste’g puy-anan,<br/>Ug ang pahat sab niya.<br/>',NULL,18479,1);
INSERT INTO stanza VALUES('CB911','chorus','Bulahan ang sacerdote,<br/>Cristo’y tanan’s tanan n’ya,<br/>Pagkaon, biste’g puy-anan,<br/>Ug ang pahat sab niya.<br/>',NULL,18480,2);
INSERT INTO stanza VALUES('CB911','2','Biste n’ya sa pag-alagad<br/>Ang katahum’s Ginoo;<br/>Tabon’s dughan ug abaga,<br/>Puno gayud’s himaya.<br/>',NULL,18481,3);
INSERT INTO stanza VALUES('CB911','3','Naghalad siya ug Cristo,<br/>Halad nga gusto sa Dios;<br/>Mahimo S’yang kalan-on n’ya,<br/>Mapuno’s ’yang kadato.<br/>',NULL,18482,4);
INSERT INTO stanza VALUES('CB911','4','Isul-ob n’ya S’ya nga saput,<br/>Ipadayag n’ya’s Cristo;<br/>Kaon-inom, masagol N’ya,<br/>Cristo mapanag-iya.<br/>',NULL,18483,5);
INSERT INTO stanza VALUES('CB911','5','Puy-anan mahimayaon,<br/>Pagtubo man’s Ginoo;<br/>Hi’usa kitang tukoron<br/>Nga balay alang sa Dios.<br/>',NULL,18484,6);
INSERT INTO stanza VALUES('CB911','6','Tanang pahat, kinabuhi,<br/>Tanang nabatonan ta—<br/>Lunlon nga Cristo ug Iyang<br/>Pagkamalangkubon gyud.<br/>',NULL,18485,7);
INSERT INTO stanza VALUES('CB912','1','Pagpangalagad ug Cristo,<br/>Pagsilbe sa Dios ug tawo,<br/>Pagsangkap’s kadatong Cristo,<br/>Pag-alagad tinuod.<br/>',NULL,18486,1);
INSERT INTO stanza VALUES('CB912','chorus','Pagpangalagad ug Cristo,<br/>Pagsilbe sa Dios ug tawo,<br/>Pagsangkap’s kadatong Cristo,<br/>Pag-alagad tinuod.<br/>',NULL,18487,2);
INSERT INTO stanza VALUES('CB912','2','Israelitas naghalad gyud<br/>Sa sobrang abut’s yuta,<br/>Bungang maani nato N’ya,<br/>Dad-on ta’s pag-alagad.<br/>',NULL,18488,3);
INSERT INTO stanza VALUES('CB912','3','Maghago’s yutang si Cristo,<br/>Anihon S’yang kalan-on;<br/>Pa’muslan hangtud moawas,<br/>Ikapaambit’s uban.<br/>',NULL,18489,4);
INSERT INTO stanza VALUES('CB912','4','Kuptan’s Cristo, magtubo ta,<br/>Matag bahin molihok;<br/>Modawat, moambit Niya,<br/>Isilbe S’ya’s Lawas N’ya.<br/>',NULL,18490,5);
INSERT INTO stanza VALUES('CB912','5','Pag-ambitay’g pamatuod,<br/>Pangalagad, pagsimba,<br/>Tanang tabang ug pagsilbe,<br/>Tinu’d pag-alagad S’ya.<br/>',NULL,18491,6);
INSERT INTO stanza VALUES('CB913','1','Mosilbe’g buhat sud’s Lawas,<br/>Gipasabut N’ya kini;<br/>Kay ang Lawas m’oy tuyo N’ya,<br/>Mosunod gyud ta ni’ni.<br/>',NULL,18492,1);
INSERT INTO stanza VALUES('CB913','chorus','Mosilbe’g buhat sud’s Lawas,<br/>Di gyud kinaugalingon;<br/>Isip mga bahin’s Lawas,<br/>Magtambayayongay ta.<br/>',NULL,18493,2);
INSERT INTO stanza VALUES('CB913','2','Mga bahin tang gibuhi,<br/>Di tinagsang gawasnon;<br/>Usa gyud tang moalagad,<br/>Kay masigkabahin man.<br/>',NULL,18494,3);
INSERT INTO stanza VALUES('CB913','3','Buhing bato tang gitukod,<br/>Himoong balay sa Dios;<br/>Bal’ang mga sacerdote<br/>Usa nga mag-alagad.<br/>',NULL,18495,4);
INSERT INTO stanza VALUES('CB913','4','Tukoron gyud ta pag-usa,<br/>Mangalagad’s pwesto ta;<br/>Sukaranan’s pag-alagad<br/>Kinaiya man’s Lawas.<br/>',NULL,18496,5);
INSERT INTO stanza VALUES('CB913','5','Magbuhat ug mag-alagad,<br/>Sangkapan una’s Lawas;<br/>Kay kon kita mahimulag,<br/>Mawad-an’s kapuslanan.<br/>',NULL,18497,6);
INSERT INTO stanza VALUES('CB913','6','Makaambit’s kadato N’ya<br/>Kon mag-alagad’s Lawas;<br/>Kon mga bahin maglihok<br/>Mabatonang sukod N’ya.<br/>',NULL,18498,7);
INSERT INTO stanza VALUES('CB913','7','Mounong gyud ta sa Ulo,<br/>Aron usang magtubo;<br/>Sangkap nga gikan sa Ulo<br/>Moagay ngadto’s Lawas.<br/>',NULL,18499,8);
INSERT INTO stanza VALUES('CB913','8','Lawas ihalad, usba ko,<br/>Pasayra’s pagbuot Mo;<br/>Pailha sa Lawas aron<br/>Su’d ni’ni mag-alagad.<br/>',NULL,18500,9);
INSERT INTO stanza VALUES('CB914','1','Alang’s Iglesia magsilbe,<br/>Kabubut-on’s Dios kini;<br/>Bugtong paagi’s pagbuhat<br/>Gisunod’s apostoles.<br/>',NULL,18501,1);
INSERT INTO stanza VALUES('CB914','chorus','Magsilbe alang’s Iglesia,<br/>Di magtagbaw’s tuyo ta;<br/>M’oy hingpit N’yang kabubut-on,<br/>Kin’hanglan atong sundon.<br/>',NULL,18502,2);
INSERT INTO stanza VALUES('CB914','2','Ma-sudlanan N’yang Iglesia,<br/>M’oy dayong tinguha N’ya;<br/>Gusto N’yang tanang pagsilbe<br/>Alang’s pagtukod ni’ni.<br/>',NULL,18503,3);
INSERT INTO stanza VALUES('CB914','3','Tanang tawong ginasahan<br/>Gihatag’s Ulo’s Lawas,<br/>Tabang’s pagtukod’s Iglesia,<br/>Magda’ N’ya’s kahupnganan.<br/>',NULL,18504,4);
INSERT INTO stanza VALUES('CB914','4','Tanang gasa’g kagamitan,<br/>Tanang gahum’s Esp’ritu,<br/>Tanang pangalagad, hatag<br/>Alang ra gyud’s Iglesia.<br/>',NULL,18505,5);
INSERT INTO stanza VALUES('CB914','5','Pagsangyaw sa Ebanghelyo,<br/>Pangalagad’s pagtudlo,<br/>Ug ubang pag-alagad ta,<br/>Alang ra gyud’s Iglesia.<br/>',NULL,18506,6);
INSERT INTO stanza VALUES('CB914','6','Ministri alang’s Iglesia,<br/>Di ’glesia alang ni’ni;<br/>Tangkawan maong Iglesia,<br/>Di unsa nga ministri.<br/>',NULL,18507,7);
INSERT INTO stanza VALUES('CB914','7','Mag-amping ni’s pagkausa,<br/>Magluwas nato’s sekta;<br/>Magsulay sa motibo ta,<br/>Magtul-id sa tumong ta.<br/>',NULL,18508,8);
INSERT INTO stanza VALUES('CB914','8','Luwasa mi’s buhat namo,<br/>Sa unsang pundokpundok;<br/>Alang’s Iglesia maghago,<br/>Aron kini matukod.<br/>',NULL,18509,9);
INSERT INTO stanza VALUES('CB921','1','L’wasang mangalaglag,<br/>Ug himalatyon,<br/>Iloga sa sala’g kamatayon;<br/>Bakhoi’g bangona<br/>Ang nangatumba,<br/>Jesus moluwas sultii sila.<br/>',NULL,18510,1);
INSERT INTO stanza VALUES('CB921','chorus','L’wasang mangalaglag,<br/>Ug himalatyon;<br/>Jesus maluloy-on,<br/>S’ya moluwas.<br/>',NULL,18511,2);
INSERT INTO stanza VALUES('CB921','2','Naghuwat gihapon S’ya<br/>Bisan wa tagda,<br/>Nga maghinulsol kay dawaton N’ya;<br/>Sa tumang kalomo<br/>Ug kasibut gyud,<br/>Hangyoon sila nga motoo na.<br/>',NULL,18512,3);
INSERT INTO stanza VALUES('CB921','3','Kasingkasing sa tawo<br/>Gidugmok’s yawa,<br/>Ang grasya ra ang makapaayo;<br/>Gugma’g kaayo Mo<br/>M’oy makatandog<br/>Sa nalubong nga mga pagbati.<br/>',NULL,18513,4);
INSERT INTO stanza VALUES('CB921','4','L’wasang mangalaglag,<br/>M’oy kaakohan;<br/>Ginoo magsangkap nimo’s kusog,<br/>Sa tumang pasensya,<br/>Sila kabiga,<br/>Manlul’was namatay alang nila.<br/>',NULL,18514,5);
INSERT INTO stanza VALUES('CB922','1','Ipangalagad si Cristo,<br/>Di’s pu’ng kondi’s kinabuhi,<br/>Ipaambit’s binuhatan,<br/>Sa kalag nga nakigbisug.<br/>',NULL,18515,1);
INSERT INTO stanza VALUES('CB922','chorus','Ipangalagad si Cristo,<br/>Pina’gi’s inadlawng gawi;<br/>Si Cristong gikinabuhi<br/>M’oy ihatag’s tanang tawo.<br/>',NULL,18516,2);
INSERT INTO stanza VALUES('CB922','2','Ipangalagad si Cristo,<br/>Ang Mahal nga naa nimo;<br/>Ipaambit’s gimahal mo,<br/>Aron Siya mailaha.<br/>',NULL,18517,3);
INSERT INTO stanza VALUES('CB922','3','Ipangalagad si Cristo,<br/>Ang Cristong napa’muslan mo,<br/>Ipaambit’s higala mo,<br/>Ingon nga kalipay nila.<br/>',NULL,18518,4);
INSERT INTO stanza VALUES('CB922','4','Ipangalagad si Cristo,<br/>S’yang kinabuhi’g tanan mo,<br/>Ipaambit’s mahinagbo,<br/>Tanan, magagmay’g dagko.<br/>',NULL,18519,5);
INSERT INTO stanza VALUES('CB923','1','Mangahoy kamo alang sa Balay,<br/>Kabiga ug dad-ang mga kalag;<br/>Dad-ang katawhang gibuhat sa Dios,<br/>Dad-a silang giilog sa sala.<br/>',NULL,18520,1);
INSERT INTO stanza VALUES('CB923','2','Mangahoy kamo alang sa Balay,<br/>Tawo gikan’s kalibutan luwasa,<br/>Gikan’s kangitngit, limbong sa Yawa,<br/>Ug gikan sa mga pagtintal n’ya.<br/>',NULL,18521,2);
INSERT INTO stanza VALUES('CB923','3','Mangahoy kamo alang sa Balay,<br/>Danihang kalag, S’ya mahimaya;<br/>Ang kaaway sa Dios buntoga na,<br/>Usahan pagbadbad makasasala.<br/>',NULL,18522,3);
INSERT INTO stanza VALUES('CB923','4','Mangahoy kamo alang sa Balay,<br/>Cristo diha’s Lawas imantala;<br/>Sa mga balaan mahiusa,<br/>Budyong’s ebanghelyo patingoga.<br/>',NULL,18523,4);
INSERT INTO stanza VALUES('CB925','1','Ang pagsangyaw’s ebanghelyo<br/>Pag-agay’s kinabuhi;<br/>Buhi kining testimonyo,<br/>Magluwas’ nangasaag.<br/>',NULL,18524,1);
INSERT INTO stanza VALUES('CB925','chorus','Paagaya O Ginoo,<br/>Ako’s kinabuhi Mo;<br/>Himoang buhing sudlanan,<br/>Makabuhi sa uban.<br/>',NULL,18525,2);
INSERT INTO stanza VALUES('CB925','2','Buhing pagmat’ud kusganon,<br/>Makapasalig dayon;<br/>Pagpaambit’s kinabuhi<br/>Sa kalag makabuhi.<br/>',NULL,18526,3);
INSERT INTO stanza VALUES('CB925','3','Aron mamunga daw sanga,<br/>Kanunayng pabilin N’ya;<br/>Sa pag-agay’s kinabuhi,<br/>Sa uban ihatag Ka.<br/>',NULL,18527,4);
INSERT INTO stanza VALUES('CB925','4','Kinabuhi ta pagsangyaw,<br/>Kanato makit-an S’ya;<br/>Dili sa mga pulong ra,<br/>Kondi’s binhing mapugas.<br/>',NULL,18528,5);
INSERT INTO stanza VALUES('CB930','1','“Moadto ba kong way dala“<br/>Pagtagbo’s Manunubos?<br/>Wala ko’y nahimong buhat,<br/>Bisan unsa alang N’ya.<br/>',NULL,18529,1);
INSERT INTO stanza VALUES('CB930','chorus','“Moadto ba kong way dala“<br/>Pagtagbo’s Manluluwas?<br/>Way dalang kalag alang N’ya,<br/>Bisan usa na lamang.<br/>',NULL,18530,2);
INSERT INTO stanza VALUES('CB930','2','Mamatay man way kahadlok,<br/>Kay giluwas na ako;<br/>Apan moadtong way dala,<br/>Kaguol palandongon.<br/>',NULL,18531,3);
INSERT INTO stanza VALUES('CB930','3','O, mga tuig nausik<br/>Diha sa kasal-anan,<br/>Kon mobalik pa lang unta,<br/>Ihalad ko N’yang tanan.<br/>',NULL,18532,4);
INSERT INTO stanza VALUES('CB930','4','O, kamong mga balaan,<br/>Magbuhat’s adlawan pa;<br/>Sa di pa ang kamatayon,<br/>Mga kalag kabigon.<br/>',NULL,18533,5);
INSERT INTO stanza VALUES('CB936','1','Nalubong uban ni Cristo,<br/>Uban Niya namatay ako;<br/>Kalibutan di kaagpas,<br/>Kanako gahum n’ya napapas.<br/>Uban N’ya nabanhaw sab,<br/>Uban N’yang maggawi’g mabuhi;<br/>Sa Espiritu sinangkapan,<br/>Gilig-on’s gahum nga dili makabsan!<br/>',NULL,18534,1);
INSERT INTO stanza VALUES('CB937','1','Nausa’s kamatayon Mo<br/>Sa pagpabautismo;<br/>Sa kal’oy’g grasya padaygi’s<br/>Bili’s pagkausa.<br/>',NULL,18535,1);
INSERT INTO stanza VALUES('CB937','2','Nausa’s kamatayon Mo,<br/>Usa sab ug lubong;<br/>Patay na gyud mi sa sala,<br/>Gawas na’s ’yang gahum.<br/>',NULL,18536,2);
INSERT INTO stanza VALUES('CB937','3','Nausa’s kamatayon Mo,<br/>Usa sab ug lubong;<br/>Sa kalibutan nibiya,<br/>Di ulipon’s yawa.<br/>',NULL,18537,3);
INSERT INTO stanza VALUES('CB937','4','Nabanhaw sab uban Nimo,<br/>Gawas’ kamatayon,<br/>Pagkabal’an bunga karon,<br/>Kinabuhing bag-o.<br/>',NULL,18538,4);
INSERT INTO stanza VALUES('CB937','5','Gibautismohan’s ngalan Mo,<br/>Di na’s kaugalingon;<br/>Ikinabuhi, sundon Ka,<br/>Kanimo mausa.<br/>',NULL,18539,5);
INSERT INTO stanza VALUES('CB938','1','Namatay na! Gilubong na!<br/>Tapos na ko’s daan nga tawo!<br/>Namatay na! Gilubong na!<br/>Tapos na ko’s daan nga tawo!<br/>',NULL,18540,1);
INSERT INTO stanza VALUES('CB938','2','Di na ako! Di na ako!<br/>Ang nabuhi mao si Cristo!<br/>Di na ako! Di na ako!<br/>Ang nabuhi mao si Cristo!<br/>',NULL,18541,2);
INSERT INTO stanza VALUES('CB941','1','Ang gingharian sa Dios<br/>Maoy paghari N’ya;<br/>Pagbuot N’ya kini nga<br/>Magtunhay’s han-ay N’ya.<br/>Hingpit gyud N’yang gamiton<br/>Ang Iyang kagahum<br/>Sulod’s gingharian N’ya<br/>Ug sa eternidad.<br/>',NULL,18542,1);
INSERT INTO stanza VALUES('CB941','2','Sa trono nga m’oy sentro’s<br/>Diosnong kagamhanan,<br/>Dios naghari sa tuyo<br/>Nga mahusayng tanan.<br/>Pagkaulo’g-ginoo<br/>S’ya ray magmintinar,<br/>Kay Hari’s gingharian,<br/>Magmando S’ya’s tanan.<br/>',NULL,18543,2);
INSERT INTO stanza VALUES('CB941','3','Paghari’s gingharian<br/>Pagbu’t N’ya gibuhat,<br/>Ug diha’s pagduma’ N’ya<br/>Tuyo N’ya matuman.<br/>Sa gingharian ra’s Dios<br/>Mapanalanginan;<br/>Moagay man’s trono N’ya<br/>Sulog’s kinabuhi.<br/>',NULL,18544,3);
INSERT INTO stanza VALUES('CB941','4','Ma’yong gawi maato<br/>Kon magpasakop’s Dios;<br/>Pagsupak’s Pagkaulo,<br/>Gigikanan’s sala.<br/>Satanas dunay tumong—<br/>Trono’s Dios pukanon;<br/>Tumong tang makaila<br/>Sa pagbuot Niya.<br/>',NULL,18545,4);
INSERT INTO stanza VALUES('CB941','5','Sulod’s gingharian’s Dios<br/>Cristo gipadako;<br/>Amahan mahimaya<br/>Kon maghari’s Cristo.<br/>Kon Dios ang nagdumala,<br/>Tanan bulahan gyud;<br/>Himaya’s Dios madayag,<br/>Kon maghari’s Cristo.<br/>',NULL,18546,5);
INSERT INTO stanza VALUES('CB941','6','Katumanan’s panahon<br/>S’yay mag-ulo’s tanan,<br/>Ilhon’s tanan S’yay Hari,<br/>Simbahon S’ya’s tanan.<br/>Paghari’s kinabuhi<br/>Matilawan karon,<br/>Magpadali’s gingharian<br/>Ang pagpasakop ta.<br/>',NULL,18547,6);
INSERT INTO stanza VALUES('CB942','1','Gingharian’s Dios sa yuta<br/>M’oy pagbuot N’ya sa sulod;<br/>Si Cristo ni’s sulod nato,<br/>Ginoo’g Haring magbuot.<br/>',NULL,18548,1);
INSERT INTO stanza VALUES('CB942','2','Kinabuhi’g kagahum N’ya<br/>Nagpalingkod N’ya’s trono ta<br/>Magduma’s pulong ug gawi,<br/>Ug magbalaod’s sulod ta.<br/>',NULL,18549,2);
INSERT INTO stanza VALUES('CB942','3','Paghari N’ya sa sulod ta,<br/>Magtukod’s Gingharian N’ya,<br/>Nagpasalig maghari S’ya,<br/>Mag-andam alang’s tuyo’s Dios.<br/>',NULL,18550,3);
INSERT INTO stanza VALUES('CB942','4','Sa paghari N’ya’s sulod ta,<br/>Kinabuhi isangkap N’ya;<br/>Kon S’yay Ginoo ug Hari,<br/>Matagbaw ta’s kadato N’ya.<br/>',NULL,18551,4);
INSERT INTO stanza VALUES('CB942','5','Paghari N’ya gikan’s sulod<br/>Kahupong mapamatud-an;<br/>Paghari’s ’yang gingharian,<br/>Lawas bulahan, matukod.<br/>',NULL,18552,5);
INSERT INTO stanza VALUES('CB942','6','Langitnong paghari’s sulod<br/>Magkinabuhing langitnon;<br/>Pagpasakop’s pagbuot N’ya,<br/>Gipadayag nato S’yay Hari.<br/>',NULL,18553,6);
INSERT INTO stanza VALUES('CB942','7','Mabuhi ta’s gingharian,<br/>Langitnong gahum maato<br/>Maggawi’g makigbisug ta<br/>Hangtud Gingharian makita.<br/>',NULL,18554,7);
INSERT INTO stanza VALUES('CB943','1','Ang kin’hanglan’s Gingharian<br/>Mahigpit pa’s kasugoan;<br/>Dios wa nay gikinahanglan<br/>Nga labaw pa kay niini.<br/>',NULL,18555,1);
INSERT INTO stanza VALUES('CB943','2','Maghinulsol kay duol na,<br/>M’oy unang gikinahanglan;<br/>Mag-usab sa hunahuna<br/>Sa Dios lig-on nga molaban.<br/>',NULL,18556,2);
INSERT INTO stanza VALUES('CB943','3','Aron makasu’d’s Gingharian,<br/>Pagkamatarung kin’hanglan;<br/>Nga labaw pa’s kasugoan;<br/>Lugwa gyud sa kinabuhi.<br/>',NULL,18557,3);
INSERT INTO stanza VALUES('CB943','4','Aron makasu’d’s Gingharian,<br/>Magbuhat’s buot’s Amahan,<br/>Di’s gusto natong buhaton,<br/>Kondi’ tuyo N’ya tumanon.<br/>',NULL,18558,4);
INSERT INTO stanza VALUES('CB943','5','Aron makasu’d’s Gingharian,<br/>Mahimo kita nga bata—<br/>Maaghop, masinugtanon—<br/>Makadaug’s kaugalingon.<br/>',NULL,18559,5);
INSERT INTO stanza VALUES('CB943','6','Gingharian nagkin’hanglan<br/>Mahingpit ta sama sa Dios;<br/>Tagboon kining sukdanan<br/>Makaambit ta’s kalipay.<br/>',NULL,18560,6);
INSERT INTO stanza VALUES('CB943','7','Gingharian paghari’s Dios;<br/>Haum sa kinaiya N’ya;<br/>Sa kinabuhi ra sa Dios,<br/>Sa Gingharian makasu’d.<br/>',NULL,18561,7);
INSERT INTO stanza VALUES('CB943','8','Pagbuot kini sa langit;<br/>Magpahiangay gyud kita;<br/>Sa kinabuhi ra’s langit,<br/>Makaambit uban Niya.<br/>',NULL,18562,8);
INSERT INTO stanza VALUES('CB944','1','Pagkamao’s Gingharian<br/>Kinabuhing na’s langitnong<br/>Pagbuot, kinaiya diosnon,<br/>Cristo bug-os masinati.<br/>',NULL,18563,1);
INSERT INTO stanza VALUES('CB944','2','Naa’s espiritung kabus,<br/>Maaghop, mahinulsolon,<br/>Ngadto’s uban maluloy-on,<br/>Ug ang Dios ra’y gitinguha.<br/>',NULL,18564,2);
INSERT INTO stanza VALUES('CB944','3','Isip mga anak sa Dios<br/>Nakigdait ug nagbuhat’s<br/>Pagkamatarung, bisan pag<br/>Giyubit, gisakit tungod N’ya.<br/>',NULL,18565,3);
INSERT INTO stanza VALUES('CB944','4','Asin, nagsanta’s kadunot,<br/>Sa kangitngit m’oy kahayag,<br/>Tinguha’g gawi matuod,<br/>Way pag-agpas sa katungod.<br/>',NULL,18566,4);
INSERT INTO stanza VALUES('CB944','5','Nagsalikway’s iyang tanan,<br/>Nag-ampo alang’s gingharian;<br/>Nagsalig’s Dios alang’s tanan,<br/>Giuna ’yang gingharian.<br/>',NULL,18567,5);
INSERT INTO stanza VALUES('CB944','6','Higpit sa kaugalingon,<br/>Sa uban s’ya maluloy-on;<br/>Nagbuhat’s ’yang kabubut-on,<br/>Naggawi sumala’s pulong.<br/>',NULL,18568,6);
INSERT INTO stanza VALUES('CB944','7','Wa maghatag luna’s Yawa,<br/>Kalibutan, o sa sala,<br/>Nangita’s mandong langitnon<br/>Kagahum sa Dios maangkon.<br/>',NULL,18569,7);
INSERT INTO stanza VALUES('CB944','8','Kinabuhi nagpasakop<br/>Sa tanang butang’s sugo’s Dios;<br/>Aron mapadali ni’ni,<br/>Pagpadayag’s gingharian.<br/>',NULL,18570,8);
INSERT INTO stanza VALUES('CB946','1','O himaya! O katahum!<br/>Gingharian nadayag!<br/>Ug ang Hari, Agalon ta,<br/>Sa pagtudlo’s Dios gidayeg.<br/>Kanhi S’ya nagpakaubos,<br/>Gidumtan, gitamay’s tawo;<br/>Karon nibalik’s pagtuman,<br/>Plano N’ya’s Gingharian.<br/>',NULL,18571,1);
INSERT INTO stanza VALUES('CB946','2','Magdawat S’ya’s Gingharian<br/>Sa Dios, Labing Karaan,<br/>Moabot uban’s Gingharian,<br/>Mahimayaong magbuot.<br/>S’ya “ang Bato” nga modugmok’s,<br/>Mga nasud’s kinaubsan,<br/>Ug mahimong “dakong bukid,“<br/>Pagpadayag’s Gingharian.<br/>',NULL,18572,2);
INSERT INTO stanza VALUES('CB946','3','Tan-awa, tibuok yuta,<br/>Kang Cristo na ang tanan;<br/>Kanasuran’s ’yang pagbuot,<br/>Mapuno’s kadaitan.<br/>Wa nay gubat ug pagdumot<br/>Diha sa mga nasud;<br/>Kay kahibalo sa Dios daw<br/>Tubig magpuno’s dagat.<br/>',NULL,18573,3);
INSERT INTO stanza VALUES('CB946','4','Maghari uban ni Cristo<br/>Ang tanang mananaug,<br/>Ug saling nal’was sa Israel<br/>Masacerdote na’s Dios.<br/>Kanasurang katawhan’s Dios<br/>Haria’g tudloan nila<br/>Makitang pagpahiuli<br/>Sa tibuok kabuhatan.<br/>',NULL,18574,4);
INSERT INTO stanza VALUES('CB946','5','Satanas gapuson, pa’waon;<br/>Di na s’yay magbuot’s yuta;<br/>Si Cristo ang Hari’g Ulo,<br/>Yuta mabulahan unya.<br/>Tanan masakop ni Cristo,<br/>Sa pagbuot N’ya’g gahum;<br/>Masanagong Ulo’g Sentro,<br/>Magtuman’s diosnong tuyo.<br/>',NULL,18575,5);
INSERT INTO stanza VALUES('CB947','1','Gingharian’s Dios pagbansayng matuod,<br/>Paghari ni Cristo mahimo ning balus;<br/>Kaalam’s Dios nga kita karon mabansay,<br/>Plano N’ya matuman, hustisya motunhay.<br/>',NULL,18576,1);
INSERT INTO stanza VALUES('CB947','2','Gianak ta’s Dios, maghari uban N’ya,<br/>Aron modaug kin’hanglan mabansay ta.<br/>Makat-on sa paghari’s gingharian N’ya,<br/>Dinhi nato madayag pagkahari N’ya.<br/>',NULL,18577,2);
INSERT INTO stanza VALUES('CB947','3','Kin’hanglan makat-on’s pagpasakop N’ya,<br/>Higpit magkinabuhi’g magpadumala;<br/>Makaambit ta sa Iyang pagbulot-an,<br/>Uban sa Anak maghari’s kanasuran.<br/>',NULL,18578,3);
INSERT INTO stanza VALUES('CB947','4','Sa kahigpit pagkamatarung huptan,<br/>Maluloy-on’s uban, masadyaon sa Dios;<br/>Magpabilin’s realidad’s Gingharian,<br/>Maandam paghari’s pagpadayag ni’ni.<br/>',NULL,18579,4);
INSERT INTO stanza VALUES('CB947','5','Gantihang maghari uban ni Cristo,<br/>Sa pag-abot N’ya uban’s gingharian’s Dios;<br/>Pagkamatarung Niya mintinaron ta,<br/>Madayag sa kagamhanan kaalam N’ya.<br/>',NULL,18580,5);
INSERT INTO stanza VALUES('CB947','6','Alang ni’ni Apostol giduot gyud,<br/>Kay nisalig’s Gingharian s’ya di mawa’;<br/>Nag-awhag siya’s uban tungod niini,<br/>“Magminatud-on’s Ginoo kay may ganti.”<br/>',NULL,18581,6);
INSERT INTO stanza VALUES('CB947','7','Ginoo, grasyahi aron mabuhi<br/>Sa Gingharian, mabansay’g magantihan;<br/>Mabansay mi’s realidad’s Gingharian<br/>Pagpadayag ni’ni dako namong ganti.<br/>',NULL,18582,7);
INSERT INTO stanza VALUES('CB948','1','Misteryo gibugna karon kanako,<br/>Kini’s Cristong realidad’s Dios.<br/>Pagkalawas sa Dios, kinabuhi ko,<br/>Unya himaya’g paglaum ko.<br/>',NULL,18583,1);
INSERT INTO stanza VALUES('CB948','chorus','Cristo kinabuhi’s sulod ko!<br/>Mahimayaong paglaum ko!<br/>Sa espiritu ko S’ya ang misteryo!<br/>Siya unya ang himaya ko.<br/>',NULL,18584,2);
INSERT INTO stanza VALUES('CB948','2','Gianak pag-usab’s espiritu ko,<br/>Nagtransporma karon’s kalag ko.<br/>Usbon N’yang lawas ko, masama’s Iya,<br/>Aron hingpit kong masama N’ya.<br/>',NULL,18585,3);
INSERT INTO stanza VALUES('CB948','3','Usa’s kinabuhi’g kinaiya N’ya,<br/>Aron didto unya’s himaya,<br/>Magpahimulos sa Iyang presensya,<br/>Wa gyuy kalainan’s dagway N’ya.<br/>',NULL,18586,4);
INSERT INTO stanza VALUES('CB949','1','Paglaum ko si Cristo, kinabuhi ko S’ya,<br/>Gianak ko pag-usab, ug gisuropan N’ya;<br/>Usbon Niyang lawas ko sa dako N’yang gahum,<br/>Sama gyud’s lawas N’yang mahimayaon.<br/>',NULL,18587,1);
INSERT INTO stanza VALUES('CB949','chorus','Moanhi S’ya, himayaon ako!<br/>Sama gayud sa lawas N’ya, ang lawas ko usbon;<br/>Moanhi S’ya ug ako ’yang tubson!<br/>Siya m’oy akong paglaum nga mahimayaon.<br/>',NULL,18588,2);
INSERT INTO stanza VALUES('CB949','2','Paglaum ko si Cristo, misteryo S’ya sa Dios;<br/>Kahupnganan’s Dios Iyang gipaambit nako.<br/>Nia aron masakot ko’s Dios’ tanang bahin,<br/>Makaambit’s himaya N’ya sa dayon.<br/>',NULL,18589,3);
INSERT INTO stanza VALUES('CB949','3','Paglaum ko si Cristo, S’ya’y katubsanan ko:<br/>Lawas ko ipagawas gikan’s kamatayon,<br/>Nia aron lawas usbong mahimayaon,<br/>Kamatayon lamyon hangtud sa dayon.<br/>',NULL,18590,4);
INSERT INTO stanza VALUES('CB949','4','Paglaum ko si Cristo, S’yay kasaysayan ko:<br/>Kinabuhi N’ya maoy kasinatian ko<br/>Nia aron dad-on ko sa kagawasan N’ya,<br/>Hingpit unyang mausa ako Niya.<br/>',NULL,18591,5);
INSERT INTO stanza VALUES('CB956','1','Di madugay moanhi nang Ginoo,<br/>Mga tunob Niya madungog.<br/>Magtukaw ug kanunay nga magbantay,<br/>Aron lipayon N’ya’s paglalin.<br/>',NULL,18592,1);
INSERT INTO stanza VALUES('CB956','chorus','O himaya! Cristo mobalik!<br/>O himaya! Ubang maghari!<br/>Mahimayao’g lawas, uban Niya,<br/>Malipayong usang magdayeg N’ya.<br/>',NULL,18593,2);
INSERT INTO stanza VALUES('CB956','2','Di madugay Bitoon S’yang motungha;<br/>Gabii lalum, mokadlawon na.<br/>Di gyud magpaanod sa urog karon,<br/>Makalikay’s dakong pagsulay.<br/>',NULL,18594,3);
INSERT INTO stanza VALUES('CB956','3','Pagbalik N’ya sulugoon gantihan;<br/>Nagmahal N’ya purongpurongan.<br/>Magtukaw gyud ta, dag-ong kalibutan,<br/>Higugmaon S’ya ug silbehan.<br/>',NULL,18595,4);
INSERT INTO stanza VALUES('CB956','4','Di madugay maghari’s gingharian;<br/>Yawa gapuson, yuta dag-on.<br/>Makig-away gyud ta, dag-ong kaaway,<br/>Sa trono N’ya ilakip dayon.<br/>',NULL,18596,5);
INSERT INTO stanza VALUES('CB958','1','Sukad’s Betania kita nagkabulag,<br/>Kasingkasing ko naay kahaw-ang;<br/>Unsaon ko pagtugtog’s akong alpa?<br/>Mga awit, kon wa Ka, way gana.<br/>Mga takna sa gabiing nagtukaw—<br/>Way gibating kaguol, kalipay—<br/>Nadumdom kong saad Mo nga pagbalik,<br/>Nanghupaw: Nganong wa Ka pa magpakita?<br/>',NULL,18597,1);
INSERT INTO stanza VALUES('CB958','2','Pasungan Mo nagpadumdom nga wa koy<br/>Krus Mo nagkuha’s kalipay’s kalag; [ba’y;<br/>Pag-anhi Mo nag-agni’s labawng nasud,<br/>Kay Ikaw nay tumong nako karon.<br/>Kay wa Ka na, kalipay wa nay lami,<br/>Alawiton wala nay katam-is.<br/>Kay wa Ka na, sama ako’s nailo.<br/>Moanhi Ka na unta, di na maglangan.<br/>',NULL,18598,2);
INSERT INTO stanza VALUES('CB958','3','Bisan napa’muslan kong presensya Mo,<br/>Apan’s kahiladman morag kulang,<br/>Paghayag, pagpangga Mo di magtagbaw,<br/>Gusto kong mobalik na unta Ka.<br/>Sa kalinaw bation kong kamingaw;<br/>Sa kalipay naa pay panghupaw;<br/>Sa katagbawan naa pay pangandoy<br/>Nga makita Ka’s nawong gyud m’oy tuaw ko.<br/>',NULL,18599,3);
INSERT INTO stanza VALUES('CB958','4','Bihag di ba buot makauli’s ila?<br/>Di ba mingawon’s mga kabanay?<br/>Kinsay nilangyawng makalimot’s banay?<br/>Naglagyong trato di bu’t magkita?<br/>Ginoo, ikatandi ba ’ning pagbati<br/>Sa tanang kalipay’s pagbalik Mo?<br/>Kon di ko makita dinhi ang nawong Mo,<br/>Manghupaw ra hangtud magpakita Ka na.<br/>',NULL,18600,4);
INSERT INTO stanza VALUES('CB958','5','Ginoo, nalimtan Mo ba ang saad<br/>Nga mobalik Ka ug lalinon ko?<br/>Daghang adlaw ug tuig kong naghulat,<br/>Naghulat, way nakitang nibalik.<br/>Dumdoming daghang tuig kong naghulat,<br/>Bisan naglangan Ka pa sa layo,<br/>Unsa kadugayng maghulat pa Nimo,<br/>Hangtud ba masanagon Kang moanhi?<br/>',NULL,18601,5);
INSERT INTO stanza VALUES('CB958','6','Mga balaan’s daghang kaliwatan<br/>Nabuhi, naghulat, nangatulog,<br/>Wa igkitang natuman ang saad Mo,<br/>Kadugay na, dugay na gyud ka’yo!<br/>Nganong di mi makadungog’s tunob Mo?<br/>Nganong tak-om pa mang kalangitan?<br/>Magdugay pa bang paghuwat namo Nimo<br/>Sa di pa ipadayag ang himaya Mo?<br/>',NULL,18602,6);
INSERT INTO stanza VALUES('CB958','7','Nadumdom kong daghang tuig’s paghulat’s<br/>Pagbalik Mo—apan di ako ra,<br/>Kondi’ daghang balaan’s kaliwatan<br/>Nangamuyo balikan ming Imo.<br/>Sa di maihap nga luha’g pag-ampo,<br/>Tubaga na sa pagdali’g tungha.<br/>Ari na, tingog ’ni’s kapanahonan,<br/>Ari, tubaga kining hiusang tuaw.<br/>',NULL,18603,7);
INSERT INTO stanza VALUES('CB959','1','Sukad pagb’ya Mo’s Bukid sa Olivo,<br/>Nganong nalangan ang pag-anhi Mo?<br/>Daghang tuig nangandoy’s pag-anhi Mo;<br/>Pag-ampo namo wa ba madungog?<br/>',NULL,18604,1);
INSERT INTO stanza VALUES('CB959','chorus','Anhia na,<br/>O kami anhia na;<br/>Pagbalik Mo bugtong tinguha namo,<br/>Pagdali unta’g balik.<br/>',NULL,18605,2);
INSERT INTO stanza VALUES('CB959','2','Pinangga, sukad’s tuig nikayab Ka,<br/>Kami dinhi pulos gilaayan;<br/>Sagad’s pag-ampo, paglihok, pagtukaw,<br/>Alang Nimo, Ginoo, manghupaw.<br/>',NULL,18606,3);
INSERT INTO stanza VALUES('CB959','3','Maayo man tuod usahay dinhi,<br/>Bulak matahum, langgam may awit;<br/>Apan anus-a Ka nako makita?<br/>Gimingaw ko kaayo’s nawong Mo.<br/>',NULL,18607,4);
INSERT INTO stanza VALUES('CB959','4','Ginoo, dugay na ming nagpaabot,<br/>Hangtud anus-a pa kadugay ni?<br/>Pagsubang’s Adlaw hangtud sa pagsalop<br/>Ika’y gilaumang makita na.<br/>',NULL,18608,5);
INSERT INTO stanza VALUES('CB959','5','Mag-ulan, mag-init, hunas ba’g taub,<br/>Matag huyohoy ug subang’s Bulan,<br/>Gilaum nga mobalik Ka na unta,<br/>Nahigawad, kay wala pa man Ka.<br/>',NULL,18609,6);
INSERT INTO stanza VALUES('CB959','6','Kon dili pa’s tugong panamilit Mo,<br/>Maluya mi, ug di na mobuhat;<br/>Apan buot Mong samtang naghulat mi,<br/>Alang Nimo mabuhi’g mobuhat.<br/>',NULL,18610,7);
INSERT INTO stanza VALUES('CB959','7','Handuma nga dugay na gyud kaayo,<br/>Saad Mo anus-a man matuman?<br/>Sigeng naglaum; wala gyu’y pag-undang;<br/>Mahimo bang moanhi Ka karon?<br/>',NULL,18611,8);
INSERT INTO stanza VALUES('CB960','1','Ang Hari ko mobalik gyud,<br/>Langit mapuno N’ya;<br/>Uniberso Iyang tubson,<br/>Sa kahayag N’ya pun-on.<br/>Plano N’ya ’yang tumanon na,<br/>Nadungog tunob N’ya;<br/>Mahimayaong dagway N’ya,<br/>Daklit makita na.<br/>',NULL,18612,1);
INSERT INTO stanza VALUES('CB960','2','Nangandoy ko’s presensya N’ya,<br/>Di na magtinapol<br/>Samtang naghuwat’s pagbalik N’ya,<br/>Makita S’ya mismo.<br/>Bugtong gilaum—’anhi S’ya,<br/>Pagtoo—’kit-an na;<br/>Way laing kalipay’s yuta,<br/>S’ya akong makita.<br/>',NULL,18613,2);
INSERT INTO stanza VALUES('CB960','3','Kasingkasing uban gyud N’ya,<br/>Mata itumong N’ya,<br/>Way laing ipamulong ko,<br/>Sugatong Ginoo.<br/>Duol na Siyang mobalik,<br/>Alang gayud nako;<br/>Di na madugay tumanon,<br/>Saad N’yang malig-on.<br/>',NULL,18614,3);
INSERT INTO stanza VALUES('CB960','4','Pulong Mo, Manluluwas ko,<br/>Di gyud katahapan;<br/>Gidasig kong magmatumanon<br/>Nimo adlaw-adlaw.<br/>Himaya makita unta,<br/>Kaaway mapukan;<br/>Mga saad Mo matuman,<br/>Mada’ mi’s trono Mo.<br/>',NULL,18615,4);
INSERT INTO stanza VALUES('CB960','5','Bukton Mo maoy dangpanan,<br/>Dios ko’g Manluluwas;<br/>Nag-amping sama’s Amahan<br/>Sa tanang nisalig.<br/>Carnero’g tigbantay usa,<br/>Sama’s ulo’g lawas;<br/>Way makailog’s kamot Mo<br/>Sa nisalig Nimo.<br/>',NULL,18616,5);
INSERT INTO stanza VALUES('CB960','6','Libong kamot di mag-ulang,<br/>Libong mata di sab;<br/>Tunok sa dalan motabang<br/>Sa ganti moasdang.<br/>Kasingkasing ko, bangon na,<br/>Yuta palabya na;<br/>Kuhaon ko N’ya’s di madugay,<br/>Uban N’ya’s itaas!<br/>',NULL,18617,6);
INSERT INTO stanza VALUES('CB960','7','Paglaum, Adlaw’s pag-ayo!<br/>Mahal kong silaw Mo.<br/>Matarung, mahimayaon,<br/>Ginoo’g Hari ko;<br/>Pagdali’g saka sa trono,<br/>Nawong ipadayag;<br/>Tukora nang gingharian,<br/>Katawhan grasyahan.<br/>',NULL,18618,7);
INSERT INTO stanza VALUES('CB960','8','Hari untang kamat’oran<br/>Raynang kagawasan;<br/>Bakak dugayng nikuyanap,<br/>Sa yuta nanguna.<br/>Kamatuoran balik na,<br/>Kahayag Mo dad-a;<br/>Dugmokang ka’way, dad-ang mga<br/>Anak’s sabakan N’ya.<br/>',NULL,18619,8);
INSERT INTO stanza VALUES('CB962','1','O, anus-a Ka man mobalik?<br/>Makita untang nawong Mo,<br/>Awiton ko ang pagdaug Mo<br/>Ug sud-ongon Ka, puno’s grasya.<br/>Pagdali na, O Ginoo,<br/>O balik na ug lipaya ako;<br/>Pagdali na, O Ginoo,<br/>Gusto ko nga ig-uban Ka.<br/>',NULL,18620,1);
INSERT INTO stanza VALUES('CB965','1','Kon mobalik nang Ginoo,<br/>L’wason ko’s tanang kasakit,<br/>Uban’s balaan magsunod N’ya,<br/>O daygon S’ya!<br/>O daygon S’ya! O daygon S’ya!<br/>Uban’s balaan magsunod N’ya,<br/>O daygon S’ya!<br/>',NULL,18621,1);
INSERT INTO stanza VALUES('CB965','2','Kon igkita na S’ya’s nawong,<br/>Uban N’yang mopuyo’s dayon,<br/>Maghugyaw-awit’s grasya N’ya,<br/>O daygon S’ya!<br/>O daygon S’ya! O daygon S’ya!<br/>Maghugyaw-awit’s grasya N’ya,<br/>O daygon S’ya!<br/>',NULL,18622,2);
INSERT INTO stanza VALUES('CB965','3','Kon igkita na S’ya’s Trono,<br/>Mawa’ng mga pag-antus ko,<br/>Magkalipay nga nidaug,<br/>O daygon S’ya!<br/>O daygon S’ya! O daygon S’ya!<br/>Magkalipay nga nidaug,<br/>O daygon S’ya!<br/>',NULL,18623,3);
INSERT INTO stanza VALUES('CB965','4','Magmatu’d niadtong adlawa,<br/>Way labaw’s kinabuhi N’ya,<br/>Unsang himaya’s paglalin,<br/>O daygon S’ya!<br/>O daygon S’ya! O daygon S’ya!<br/>Unsang himaya’s paglalin,<br/>O daygon S’ya!<br/>',NULL,18624,4);
INSERT INTO stanza VALUES('CB965','5','Magtago unta’s kilid N’ya,<br/>Usa ug di gyud mabulag,<br/>Aron Siya matagbaw na,<br/>O daygon S’ya!<br/>O daygon S’ya! O daygon S’ya!<br/>Aron Siya matagbaw na,<br/>O daygon S’ya!<br/>',NULL,18625,5);
INSERT INTO stanza VALUES('CB965','6','O Hari ko, O balik na,<br/>Lalina suma’s saad Mo,<br/>Gantihi ang mananaug,<br/>O daygon Ka!<br/>O daygon Ka! O daygon Ka!<br/>Gantihi ang mananaug,<br/>O daygon Ka!<br/>',NULL,18626,6);
INSERT INTO stanza VALUES('CB966','1','Maoy paglaum Cristo mobalik!<br/>Malalin kita ug matransporma;<br/>Mahimaya ta uban Kaniya,<br/>Sa pagkasama N’ya maporma ta.<br/>',NULL,18627,1);
INSERT INTO stanza VALUES('CB966','chorus','Mahimayaong paglaum!<br/>Kay si Cristo mobalik man!<br/>Malalin kita ug matransporma,<br/>Paglaum’s himaya, mobalik S’ya!<br/>',NULL,18628,2);
INSERT INTO stanza VALUES('CB966','2','Maoy paglaum Cristo mobalik!<br/>Mahanaw ang daang kabuhatan;<br/>Magawas, di na ta mag-agulo,<br/>Kaluwasang bug-os pahimuslan.<br/>',NULL,18629,3);
INSERT INTO stanza VALUES('CB966','3','Maoy paglaum Cristo mobalik!<br/>Maghari uban N’ya’s kanasuran,<br/>Sa ’yang presensya S’ya alagaran,<br/>Kita mga sacerdoteng tanan.<br/>',NULL,18630,4);
INSERT INTO stanza VALUES('CB966','4','Maoy paglaum Cristo mobalik!<br/>Maminatud-on nga mag-alagad,<br/>Dagan’s lumba magmapadayonon,<br/>Maangayan’s ganti’s Gingharian.<br/>',NULL,18631,5);
INSERT INTO stanza VALUES('CB970','1','Alang’s pagpadayag unya<br/>Sa mga anak sa Dios;<br/>Tanang binuhat naghulat<br/>Nga sila magawas na.<br/>',NULL,18632,1);
INSERT INTO stanza VALUES('CB970','2','Nag-agulong kabuhatan,<br/>Kay naa’s kakawangan,<br/>Naglaum sa kagawasan’s,<br/>Pagkagapos, kadunot.<br/>',NULL,18633,2);
INSERT INTO stanza VALUES('CB970','3','Bisan kita nag-agulo,<br/>Nga hingkod nang modako;<br/>Kay sagupon sa pagtubo,<br/>Ipakasamang Cristo.<br/>',NULL,18634,3);
INSERT INTO stanza VALUES('CB970','4','Agulo sab’s Espiritu,<br/>Isama ta ni Cristo;<br/>Masigkatabang ang tanan<br/>Aron ta matransporma.<br/>',NULL,18635,4);
INSERT INTO stanza VALUES('CB970','5','Dad-on ta’s Dios sa himaya,<br/>Ug unya himayaon;<br/>Kita kang Cristo suropan,<br/>Hingpit nga mabalaan.<br/>',NULL,18636,5);
INSERT INTO stanza VALUES('CB970','6','Kagawasnon ning himaya,<br/>Magawas’ kabuhatan;<br/>Nati motapad’s leopardo,<br/>Mag-uban baka’g uso.<br/>',NULL,18637,6);
INSERT INTO stanza VALUES('CB970','7','Manunod uban ni Cristo,<br/>Panu’ndon N’ya maato;<br/>Himayaon uban Niya,<br/>Magpadayag’s Dios kita.<br/>',NULL,18638,7);
INSERT INTO stanza VALUES('CB971','1','Dayong tuyo sa Dios<br/>Mahiusa’s tawo,<br/>Ianak pag-usab<br/>Ang sudlanan N’ya,<br/>Kinabuhing hatag<br/>’Yang Kaugalingon,<br/>Tawo magpadayag N’ya,<br/>Kan’ya mausa.<br/>',NULL,18639,1);
INSERT INTO stanza VALUES('CB971','2','Gibuhat’s dagway’s Dios<br/>Ang mga tawo,<br/>Aron makatuman<br/>Sa Iyang plano;<br/>Kahoy’s kinabuhi<br/>Madawat Siya,<br/>Makahupnganan N’ya<br/>Sama’s asawa.<br/>',NULL,18640,2);
INSERT INTO stanza VALUES('CB971','3','Sa kinabuhi N’ya<br/>Tawo matransporma,<br/>Mahamiling bato,<br/>Masama Niya.<br/>Tawo matukod na nga<br/>Kapikas Niya,<br/>Mahimong puy-anan,<br/>Makatagbaw N’ya.<br/>',NULL,18641,3);
INSERT INTO stanza VALUES('CB971','4','Bag-ong Jerusalem,<br/>Balaang syudad,<br/>Dios nasagol’s tawo,<br/>Magpuyo nato.<br/>S’ya m’oy sulod nato,<br/>Panagway ta N’ya;<br/>Usa Niya’s dayon<br/>Sa himaya N’ya.<br/>',NULL,18642,4);
INSERT INTO stanza VALUES('CB971','5','S’ya gayud ang sentro,<br/>Maghari’s trono,<br/>Ang kinabuhi N’ya,<br/>Mag-usa nato.<br/>Sa Iyang kahayag<br/>Ampingan kita,<br/>Kalipay pa’muslan<br/>Ang pagkausa.<br/>',NULL,18643,5);
INSERT INTO stanza VALUES('CB971','6','S’ya ang buhing tubig<br/>Ug kalan-on ta;<br/>Kagutom, kauhaw<br/>Siya magtagbaw.<br/>Kanato S’ya templo,<br/>M’oy puy-anan ta,<br/>Sa presensya Niya<br/>Magsimba gyud ta.<br/>',NULL,18644,6);
INSERT INTO stanza VALUES('CB972','1','Sentrong hunahuna’s Dios<br/>Mausa Siya sa tawo;<br/>Mahimo S’yang tanan ta,<br/>Magtuman sa plano N’ya.<br/>',NULL,18645,1);
INSERT INTO stanza VALUES('CB972','2','Gibuhat tang sudlanan—<br/>Lawas, kalag, esp’ritu,<br/>Kinabuhi madawat,<br/>Mausa ta ni Cristo.<br/>',NULL,18646,2);
INSERT INTO stanza VALUES('CB972','3','Sa agay’s kinabuhi,<br/>Tawo ma-batong hamili,<br/>Sa pagtukod maangay,<br/>Mahimaya N’yang balay.<br/>',NULL,18647,3);
INSERT INTO stanza VALUES('CB972','4','Syudad nga tinukod’s Dios<br/>Puy-anang kin’hanglan N’ya,<br/>Ang Bag-ong Jerusalem,<br/>Nga magtuman’s gusto N’ya.<br/>',NULL,18648,4);
INSERT INTO stanza VALUES('CB972','5','Kining pagtukod nato,<br/>Panagsagol’s Dios ug tawo,<br/>Giplano sa Amahan<br/>Sa wa pang kalibutan.<br/>',NULL,18649,5);
INSERT INTO stanza VALUES('CB972','6','Sa sentro’g gahum ni’ni,<br/>Trono’s Dios ug ni Cristo,<br/>Nag-awas’ kinabuhi,<br/>Ang baha’s Espiritu.<br/>',NULL,18650,6);
INSERT INTO stanza VALUES('CB972','7','S’ya kahoy’s kinabuhi,<br/>Daplin’s nag-agayng sapa,<br/>Namunga’g diosnong bunga,<br/>Kalan-on’s kinabuhi.<br/>',NULL,18651,7);
INSERT INTO stanza VALUES('CB972','8','Ang Dios diha ni Cristo<br/>M’oy kahayag sa syudad;<br/>Nagpaylas sa ’yang dulom,<br/>Sa kinabuhing diosnon.<br/>',NULL,18652,8);
INSERT INTO stanza VALUES('CB972','9','Masigpuy-anan, Dios-tawo,<br/>Ang Dios m’oy sulod sa tawo;<br/>Ang Dios mapadayag na,<br/>Diha gayud sa tawo.<br/>',NULL,18653,9);
INSERT INTO stanza VALUES('CB974','1','Nangita s’ya’s syudad, nagpuyo’s tolda,<br/>Dumuloong gyud siya sa himaya;<br/>Saad’s Dios naglipay, harianon s’ya,<br/>Maong wa’ mangita’s himaya’s yuta.<br/>',NULL,18654,1);
INSERT INTO stanza VALUES('CB974','chorus','Matahum nga syudad!<br/>Dayong puy-anan’s Dios uban’s tawo tua didto.<br/>',NULL,18655,2);
INSERT INTO stanza VALUES('CB974','2','Nangita s’ya’s syudad, andam’s Dios alang n’ya;<br/>Way mansyon’s yutang kaibga’g kapuy-an,<br/>Giingnan s’ya’s Dios, balayng harianon<br/>Naghulat’s dumuloong tumoy’s dalan.<br/>',NULL,18656,3);
INSERT INTO stanza VALUES('CB974','3','Usahay manghupaw pagpangita’s syudad,<br/>Nga maglakaw sa yuta mamalibad,<br/>Makapaawit, hunahuna’s syudad,<br/>Dalan bisan lisud, dili na layo.<br/>',NULL,18657,4);
INSERT INTO stanza VALUES('CB974','4','Nangita s’ya’s syudad, tumong atoa sab,<br/>Nasayud’s syudad pahat nga andam’s Dios,<br/>Kay dumuloong man ta ubang Jesus,<br/>Andam nga tolda lang ang atong atop.<br/>',NULL,18658,5);
INSERT INTO stanza VALUES('CB975','1','Sa kanhiayng panahon tanaman,<br/>Sa katapusan kwadradong syudad,<br/>Sentro’s kabuhatan na’s tanaman,<br/>Pagtukod’s Dios sa syudad mosangko.<br/>',NULL,18659,1);
INSERT INTO stanza VALUES('CB975','2','Sa tanama’g syudad nga matahum<br/>Naang kahoy’s kinabuhi’g suba,<br/>Cristo maoy sangkap’s kinabuhi,<br/>Espiritu maoy buhing sapa.<br/>',NULL,18660,2);
INSERT INTO stanza VALUES('CB975','3','Sa tanama’g syudad nga masanag<br/>Dunay tulo ka bililhong butang;<br/>Bulawan, perlas, hamiling bato,<br/>Dagaya alang’s pagtukod sa Dios.<br/>',NULL,18661,3);
INSERT INTO stanza VALUES('CB975','4','Sa tanaman k’ing bililhong butang,<br/>Materyales rang natago’s yuta,<br/>Apan’s syudad tanan natukod na<br/>Sa puy-anang bililhon naghulma.<br/>',NULL,18662,4);
INSERT INTO stanza VALUES('CB975','5','Sa tanaman tawo’s abug gihulma,<br/>Gibuhat sama gyud sa Dios siya;<br/>Kahoy’s kinabuhi na’s gawas n’ya,<br/>Wa pa mahimong kinabuhi n’ya.<br/>',NULL,18663,5);
INSERT INTO stanza VALUES('CB975','6','Sa syudad kahoy mahimayaon<br/>Sulod’s hiniusang “tawo” nagtubo,<br/>Tataw nga kinabuhi n’ya’s Cristo,<br/>Nagsangkap’s kinabuhi sa tawo.<br/>',NULL,18664,6);
INSERT INTO stanza VALUES('CB975','7','Tawo gibuhat alang man sa syudad,<br/>Gianak pag-usab, gitransporma—<br/>Bulawan, perlas, hamiling bato,<br/>Lawas ni Cristo, sama Kaniya.<br/>',NULL,18665,7);
INSERT INTO stanza VALUES('CB975','8','Sulod sa tanaman may asawa,<br/>Alang kang Adam kapikas niya;<br/>Sa ulahi, syudad m’oy asawa,<br/>Kahupnganan ni Cristo, mahal N’ya.<br/>',NULL,18666,8);
INSERT INTO stanza VALUES('CB975','9','Syudad katumanan’s pagtukod’s Dios,<br/>Kahugpongan’s mga gimatarung;<br/>Kini maoy puloy-anan sa Dios,<br/>Hinigugmang asawa ni Cristo.<br/>',NULL,18667,9);
INSERT INTO stanza VALUES('CB975','10','Kinasang-ang pagpadayag sa Dios,<br/>Hiniusa, unibersohanon;<br/>Hingpit nagpadayag’s himaya’s Dios,<br/>Mahimayaong asawang Cristo.<br/>',NULL,18668,10);
INSERT INTO stanza VALUES('CB976','1','Kaming tinubos m’oy Lawas,<br/>Pangasaw-onon Nimo;<br/>Kahupnganan, pagpadayag<br/>Sa tanang kadato Mo.<br/>Ikaw ang ’yang tanan’s tanan,<br/>S’ya m’oy pasundayag Mo;<br/>Hingpit s’ya nga suropan Mo,<br/>Makabahin’s himaya.<br/>',NULL,18669,1);
INSERT INTO stanza VALUES('CB976','chorus','Tan-awa ang syudad,<br/>Puno sa kasanag!<br/>Hingpit kining pagpadayag’s<br/>Dios dinhi’s tawo.<br/>',NULL,18670,2);
INSERT INTO stanza VALUES('CB976','2','Dios ug tawo hingpit nasakot,<br/>Misteryo’s pagkadiosnon,<br/>Dios sa himaya, puno gyud,<br/>Tawo, puy-anan, sudlanang<br/>Nagpadayag N’ya’s kin’lapdan,<br/>Kahupnganan s’ya sa Dios,<br/>Nagpakita’s katahum N’ya,<br/>Nasagol’s kabalaan N’ya.<br/>',NULL,18671,3);
INSERT INTO stanza VALUES('CB976','3','Buhing komposisyon kini’s<br/>Balaang gitransporma;<br/>Daw mutya’g bililhong bato<br/>Sibo gayud’s dagway Mo.<br/>Gikan’s trono’s Dios, ’yang sentro,<br/>Buhing tubig niagay;<br/>Cristo kahoy’s kinabuhi,<br/>Bunga madagayaon.<br/>',NULL,18672,4);
INSERT INTO stanza VALUES('CB976','4','Bulawang tangkawan kini,<br/>Nagkupot N’ya nga suga;<br/>Dios kang Cristo ’yang kahayag<br/>Nadayag’s Espiritu.<br/>Kinasang-ang pagpadayag—<br/>Tawo na’s Dios ug Dios na’s tawo;<br/>Masigkapuy-anan sila,<br/>Tumong’s dayong plano’s Dios.<br/>',NULL,18673,5);
INSERT INTO stanza VALUES('CB978','1','Bag-ong Jerusalem na’s<br/>Bag-ong langit, yuta;<br/>Gikan’s Dios gipanganak,<br/>Pinilong kasanag.<br/>',NULL,18674,1);
INSERT INTO stanza VALUES('CB978','chorus','Tan-awa, may dagway’s Dios,<br/>Ug silaw’s himaya N’ya!<br/>Atua ang Ginoo<br/>Niadtong syudad’s Dios.<br/>',NULL,18675,2);
INSERT INTO stanza VALUES('CB978','2','Perlas tanang ganghaan,<br/>Sa bulawang syudad,<br/>Bulawan sab ang dalan,<br/>Dose’g patuk’ranan.<br/>',NULL,18676,3);
INSERT INTO stanza VALUES('CB978','3','May suba’s kinabuhi,<br/>Dagaya gyug sangkap,<br/>May kahoy’s kinabuhi,<br/>Nagtagbo’s kin’hanglan.<br/>',NULL,18677,4);
INSERT INTO stanza VALUES('CB978','4','Dios didto AKO MAO,<br/>Sa syudad’s kahayag;<br/>Dios diha sa Cordero,<br/>M’oy kahayag sa tawo.<br/>',NULL,18678,5);
INSERT INTO stanza VALUES('CB979','1','O pagkamahimayaon,<br/>Sa balaang Jerusalem;<br/>Puy-anan sa Dios ug sa tawo,<br/>Pangasaw-onon’s Cordero.<br/>',NULL,18679,1);
INSERT INTO stanza VALUES('CB979','2','Balaan’s Daan ug Bag-o,<br/>Manunod sa saad sa Dios,<br/>Bahing nag-umol sa syudad,<br/>Gitukod nga puy-anan’s Dios.<br/>',NULL,18680,2);
INSERT INTO stanza VALUES('CB979','3','Syudad hingpit nga kwadrado,<br/>Sama’g sukod tanang kilid,<br/>Way taas o mubo’g sukod,<br/>Tul-id gyud kining nagtindog.<br/>',NULL,18681,3);
INSERT INTO stanza VALUES('CB979','4','Syudad ug dalang bulawan,<br/>Sama’g bildo’s ’yang katin-aw,<br/>Nagpakitang kinaiya<br/>Ni’ni maong kinabuhi N’ya.<br/>',NULL,18682,4);
INSERT INTO stanza VALUES('CB979','5','Perla ang doseng ganghaan;<br/>Tawo gitubos, gianak pag-usab,<br/>Gitransporma nga daw perla,<br/>Makasulod’s ginsakpan N’ya.<br/>',NULL,18683,5);
INSERT INTO stanza VALUES('CB979','6','Batong mahal dayandayan’s,<br/>Doseng patuk’ranan’s yuta;<br/>Sa ka’yo’g dat-og giumol,<br/>Aron mabililhon’s dayon.<br/>',NULL,18684,6);
INSERT INTO stanza VALUES('CB979','7','Kutang jaspe pagkatin-aw,<br/>Dios sa himaya makita;<br/>Nagsidlak sa kahayag N’ya,<br/>Daw batong jaspe tan-awon.<br/>',NULL,18685,7);
INSERT INTO stanza VALUES('CB979','8','Kuta nga naggahin ni’ni,<br/>Wa maglakip’s tanang hugaw,<br/>Bulawan, perla, ug bato<br/>M’oy naa ra didto’s syudad.<br/>',NULL,18686,8);
INSERT INTO stanza VALUES('CB979','9','Templo ang Dios ug Cordero!<br/>Masud-ong natong nawong N’ya;<br/>Di gyud mob’yang presensya N’ya,<br/>Simbahon ta S’ya sa dayon.<br/>',NULL,18687,9);
INSERT INTO stanza VALUES('CB979','10','Syudad wa magkinahanglan<br/>Sa kahayag’s Adlaw’g Bulan;<br/>Kay Cordero maoy suga,<br/>Mag-iwag’s tanang direksyon.<br/>',NULL,18688,10);
INSERT INTO stanza VALUES('CB979','11','Sa trono’s Dios ug Cordero<br/>May nigulang sapang buhi;<br/>Sa masigkadaplin ni’ni,<br/>Dunay kahoy’s kinabuhi.<br/>',NULL,18689,11);
INSERT INTO stanza VALUES('CB979','12','Timaan ni’s kinabuhi’s Dios,<br/>Di lang kalan-on o tubig;<br/>Nagdala pa’s kagahum’s Dios,<br/>Nag-agay’s tibuok syudad.<br/>',NULL,18690,12);
INSERT INTO stanza VALUES('CB979','13','Ang dalan lunsayng bulawan,<br/>Kinaiya’s Dios makit-an;<br/>Subang niagay niini,<br/>Nagpabunga’s kinabuhi.<br/>',NULL,18691,13);
INSERT INTO stanza VALUES('CB979','14','Ang dose nagkahulogan’s<br/>Hingpit, dayong kagamhanan;<br/>Katulo pil-a sa upat,<br/>Simbolo’s Dios-tawo nasakot.<br/>',NULL,18692,14);
INSERT INTO stanza VALUES('CB979','15','Way kamatayo’g kangitngit,<br/>Wa nay kasubo’g kasakit;<br/>Ang tanang butang mabag-o,<br/>Dios magpuyo uban sa tawo.<br/>',NULL,18693,15);
INSERT INTO stanza VALUES('CB979','16','Syudad may hingpit dagway’s Dios,<br/>Naghari alang N’yang Hari,<br/>Sa dayong tuyo nagtuman,<br/>Maghatag N’ya’s katagbawan.<br/>',NULL,18694,16);
INSERT INTO stanza VALUES('CB980','1','Sa tibuok Kasulatan<br/>Gitipong mga balaan<br/>Daw asawa, maglipay’s Dios,<br/>Daw balay, pahulayan N’ya.<br/>',NULL,18695,1);
INSERT INTO stanza VALUES('CB980','2','Mga hulagway’s Iglesia<br/>Sa Daang Tugon mao ni:<br/>Balayng kabuhian-but-an,<br/>Asawang angay’s lalaki.<br/>',NULL,18696,2);
INSERT INTO stanza VALUES('CB980','3','Ang katawhan sa Dios kanhi<br/>Ginganlan Niya’g asawa;<br/>Balay’g syudad gitukod’s Dios,<br/>Pinaagi gyud kanila.<br/>',NULL,18697,3);
INSERT INTO stanza VALUES('CB980','4','Si Cristo Dios nga natawo,<br/>Bana alang sa asawa;<br/>Gibuhi s’ya Niya mismo,<br/>Aron s’ya makapikas N’ya.<br/>',NULL,18698,4);
INSERT INTO stanza VALUES('CB980','5','Diha’s pagkabanhaw, Cristo<br/>Nagtukod sa diosnong templo,<br/>Aron Dios may pahulayan,<br/>Ug maghuman’s ’yang gimbut-an.<br/>',NULL,18699,5);
INSERT INTO stanza VALUES('CB980','6','Iglesia, asawang Cristo,<br/>Na’ n’yang hingpit kalipay N’ya;<br/>Puloy-anan kini sa Dios<br/>Diin mapadayag Siya.<br/>',NULL,18700,6);
INSERT INTO stanza VALUES('CB980','7','Ang bag-o nga Jerusalem<br/>Mao unyay kinasang-an’s<br/>Hulagway’s balay’g asawa,<br/>Kahingpitan sa plano N’ya.<br/>',NULL,18701,7);
INSERT INTO stanza VALUES('CB980','8','Asawang angay ni Cristo,<br/>Nga m’oy makapadayag N’ya,<br/>Tabernaculo sab kini’s Dios,<br/>Harian, pahulayan N’ya.<br/>',NULL,18702,8);
INSERT INTO stanza VALUES('CB980','9','Kinasang-ang kahingpitan<br/>Sa buhat’s Dios sa katawhan,<br/>Hingpit Niyang pagpadayag<br/>Sa mga tinubos’ dayon.<br/>',NULL,18703,9);
INSERT INTO stanza VALUES('CB981','1','Patigayon’s Dios himoon’s<br/>Cristo nga Ulo’s tanan;<br/>Himoon S’yang Ulo’g sentro,<br/>Usang tanan, mag-uyon.<br/>',NULL,18704,1);
INSERT INTO stanza VALUES('CB981','2','Cristong Ulo maoy sentro;<br/>Dios m’oy Kahayag’s sulod;<br/>S’ya ug Dios maglingkod’s trono,<br/>Magtuman’s kalipay N’ya.<br/>',NULL,18705,2);
INSERT INTO stanza VALUES('CB981','3','Kinabuhi N’ya m’oy sulod,<br/>S’ya’y Ulo’s tanang butang;<br/>Kitang tanan m’oy sudlanan,<br/>Mag’dayag’s ’yang himaya.<br/>',NULL,18706,3);
INSERT INTO stanza VALUES('CB981','4','Nisulod ang Yawa sa tawo<br/>Aron pagdaut’s tanan;<br/>Kangitngit ug pagkadunot,<br/>Magpakyas’ diosnong plano.<br/>',NULL,18707,4);
INSERT INTO stanza VALUES('CB981','5','Kaugalingon gipaambit<br/>Ni Cristong kinabuhi,<br/>Aron gahum’s kamatayon<br/>Di na makaulipon.<br/>',NULL,18708,5);
INSERT INTO stanza VALUES('CB981','6','Cristo magsumada’s tanan,<br/>Agi’s Iglesia, Lawas,<br/>Tanan ihaum pag-usa,<br/>Ma-dagko ug gagmay ba.<br/>',NULL,18709,6);
INSERT INTO stanza VALUES('CB981','7','Sa hingpit nga pag-ulo N’ya,<br/>Tanan na’s pagkausa;<br/>Sa kahayag ang Iglesia<br/>Mabuhi’s pagkausa.<br/>',NULL,18710,7);
INSERT INTO stanza VALUES('CB981','8','Pag-ila N’yang Ulo’g Sentro,<br/>Tanan magkaangay na;<br/>Pagsidlak sa Iyang Lawas,<br/>Ang tanan mahigawas.<br/>',NULL,18711,8);
INSERT INTO stanza VALUES('CB981','9','Way kangitngit, pagkadunot,<br/>Kamatay’g kakawangan;<br/>Tanan mahubaran’s gapos,<br/>Hangtud gyud’s eternidad.<br/>',NULL,18712,9);
INSERT INTO stanza VALUES('CB984','1','Suba sa buhing tubig<br/>Gikan’s trono nag-agay,<br/>Naghatag’s pakig-ambitay<br/>Nag’dayag’s kagahum’s Dios.<br/>',NULL,18713,1);
INSERT INTO stanza VALUES('CB984','chorus','Suba sa buhing tubig,<br/>Nagda’s pakig-ambitay;<br/>Nagpadayag’s kagahum’s Dios,<br/>Diin kini mag-agay.<br/>',NULL,18714,2);
INSERT INTO stanza VALUES('CB984','2','Tubig sa kinabuhi,<br/>Dios niini nag-agay;<br/>Nagda’s pagka-Ginoo N’ya<br/>Diin kini mag-agay.<br/>',NULL,18715,3);
INSERT INTO stanza VALUES('CB984','3','Nag’agay’s dalang bulawan,<br/>Nagtultol nato’s dalan;<br/>Nag-agay’s kinaiya’s Dios<br/>Magpuyo ta’s dalan N’ya.<br/>',NULL,18716,4);
INSERT INTO stanza VALUES('CB984','4','Kahoy’s kinabuhi’s suba,<br/>Maong Dios, kalan-on ta;<br/>Sa hupong nga agay’s suba<br/>Bunga’s kahoy madawat.<br/>',NULL,18717,5);
INSERT INTO stanza VALUES('CB985','1','Di na’s sudlanang yuta<br/>Unya bahandi’s Dios,<br/>Kondi’s tumang katahum,<br/>Mosidlak Ka nako.<br/>',NULL,18718,1);
INSERT INTO stanza VALUES('CB985','2','Sa bulawang sudlanan<br/>Magsidlak himaya;<br/>Adlaw wa kin’hanglana;<br/>Kay Dios m’oy kahayag.<br/>',NULL,18719,2);
INSERT INTO stanza VALUES('CB985','3','Cristo, Batong bililhon,<br/>Syudad’s Dios matahum;<br/>Magsidlak S’ya daw jaspe<br/>Sa tumang himaya.<br/>',NULL,18720,3);
INSERT INTO stanza VALUES('CB985','4','Himayang di mapalong,<br/>Kahayag’s sudlanan;<br/>Kusog nga magahayag<br/>Sa tibuok yuta.<br/>',NULL,18721,4);
INSERT INTO stanza VALUES('CB985','5','Himaya’s Dios makita’s<br/>Bag-ong kabuhatan;<br/>Sudlanan nga magsidlak<br/>Asawa’s Cordero.<br/>',NULL,18722,5);
INSERT INTO stanza VALUES('CB985','6','Bulawan nga sudlanan,<br/>Simbahon sa tanan;<br/>Dios diha sa Cordero<br/>Madayag sa dayon.<br/>',NULL,18723,6);
INSERT INTO stanza VALUES('CB986','1','Katubsanan gihuman N’ya:<br/>Katingad-ang Manlul’was!<br/>Gilukat ta! nabayran na:<br/>Katingad-ang Manlul’was!<br/>',NULL,18724,1);
INSERT INTO stanza VALUES('CB986','chorus','Katingad-ang Manlul’was,<br/>Si Jesus, si Jesus!<br/>Katingad-ang Manlul’was,<br/>Ang Ginoo ko!<br/>',NULL,18725,2);
INSERT INTO stanza VALUES('CB986','2','Daygon S’ya’s dugong naghinlo,<br/>Katingad-ang Manlul’was!<br/>Nagpasig-uli nako’s Dios,<br/>Katingad-ang Manlul’was!<br/>',NULL,18726,3);
INSERT INTO stanza VALUES('CB986','3','Gihinloan’s tanang sala,<br/>Katingad-ang Manlul’was!<br/>Naghari karon’s sulod ko;<br/>Katingad-ang Manlul’was!<br/>',NULL,18727,4);
INSERT INTO stanza VALUES('CB986','4','Nagpuyo S’ya sa sulod ko,<br/>Katingad-ang Manlul’was!<br/>Nag-amping nga mounong N’ya,<br/>Katingad-ang Manlul’was!<br/>',NULL,18728,5);
INSERT INTO stanza VALUES('CB986','5','Gahum’s pagdaug gihatag,<br/>Katingad-ang Manlul’was!<br/>Sa tanang gubat modaug,<br/>Katingad-ang Manlul’was!<br/>',NULL,18729,6);
INSERT INTO stanza VALUES('CB986','6','Tanan gihalad Kaniya,<br/>Katingad-ang Manlul’was!<br/>Kalibutan wa nay labut,<br/>Katingad-ang Manlul’was!<br/>',NULL,18730,7);
INSERT INTO stanza VALUES('CB988','1','Siya maluloy-on,<br/>Mahigugmaon,<br/>Nag-antus’ kasakit<br/>Alang kanato.<br/>Namatay didto’s krus<br/>Alang’s sala ta;<br/>Cristo Manluluwas,<br/>Unsay buhaton mo?<br/>',NULL,18731,1);
INSERT INTO stanza VALUES('CB993','1','Mensahe, O pagkatam-is,<br/>Imo’s pagtoo;<br/>Gahapon, karon, sa dayon,<br/>Jesus mao ra.<br/>Moluwas’ makasasala,<br/>Moayo’s sakit;<br/>Molipay Siya’s nagsubo,<br/>Daygong ngalan N’ya!<br/>',NULL,18732,1);
INSERT INTO stanza VALUES('CB993','chorus','Gahapon, karon, sa dayon,<br/>Jesus mao ra,<br/>Tanan mabalhin, S’ya dili!<br/>Daygong Ngalan N’ya,<br/>Daygong Ngalan N’ya,<br/>Daygong Ngalan N’ya;<br/>Tanan mabalhin, S’ya dili!<br/>Daygong Ngalan N’ya!<br/>',NULL,18733,2);
INSERT INTO stanza VALUES('CB993','2','Higala’s makasasala,<br/>Nangita nimo;<br/>Umari na, paghinulsol<br/>Kan’ya moyukbo.<br/>“Di Ko ikaw hukman, ay’ nag<br/>Pagpakasala.“<br/>’Yang isulting pagpasaylo,<br/>Sama ’niadto.<br/>',NULL,18734,3);
INSERT INTO stanza VALUES('CB993','3','Mga nag-antus giayo’s<br/>Gamhanang kamot;<br/>Mga sakit ug kasubo<br/>Mob’ya sa ’yang sugo.<br/>S’yang naghatag ug pag-ayo’s<br/>Hikap’s babaye;<br/>Buhaton sab N’ya’s motoo<br/>Kanang pag-ayo.<br/>',NULL,18735,4);
INSERT INTO stanza VALUES('CB993','4','Sama kanhi nag-uban S’ya<br/>Nila sa Emmaus;<br/>Sa tibu’k kinabuhi ta<br/>Ubanan sab N’ya.<br/>Di madugay S’ya igkita,<br/>Gino’ pagdali!<br/>Mao rang Jesus makita,<br/>Sama ’niadto.<br/>',NULL,18736,5);
INSERT INTO stanza VALUES('CB994','1','Kangitngit nagputos sa esp’ritu ko!<br/>Napalgan N’ya akong nagsubo;<br/>Gitabok N’yang mga tubig’s kalag ko,<br/>Giwalang kangitngit, kasubo.<br/>',NULL,18737,1);
INSERT INTO stanza VALUES('CB994','chorus','Alang nako niadto S’ya’s Calvario,<br/>Alang nako niadto S’ya,<br/>Alang nako namatay S’ya’s Calvario,<br/>Aron maluwas ko.<br/>',NULL,18738,2);
INSERT INTO stanza VALUES('CB994','2','Sa kahadlok nakasala nagkurog,<br/>Kon di pa’s grasya, way pasaylo;<br/>“Hunongang pagmahay” m’oy nadungog ko,<br/>“Sala mo nabayran nang Jesus.”<br/>',NULL,18739,3);
INSERT INTO stanza VALUES('CB994','3','Gugmang katingad-an Iyang gihatag!<br/>Alang sa krus gib’yaang trono;<br/>Nag-inusarang nagpas-an sa sala,<br/>Ngalan N’ya daygon, ipaila.<br/>',NULL,18740,4);
INSERT INTO stanza VALUES('CB996','1','Anak sa Dios, Manlul’was,<br/>Tigpas-an’s among sala,<br/>Tigbugto’s among gapos,<br/>Tighinlo’s among mansa,<br/>',NULL,18741,1);
INSERT INTO stanza VALUES('CB996','2','Namatay Kang daw sad-an,<br/>Sa krus Ikaw gilansang;<br/>Alang sa among sala,<br/>Ikaw ang gisilotan.<br/>',NULL,18742,2);
INSERT INTO stanza VALUES('CB996','3','Cordero’s Dios, Pasalig,<br/>Gipalit mi’s dugo Mo;<br/>Utang gipapas tanan,<br/>Wala na miy bayranan;<br/>',NULL,18743,3);
INSERT INTO stanza VALUES('CB996','4','Wa na miy pas-anon pa,<br/>Way tabangag pangako;<br/>Kalipay’g pasaylo ra,<br/>May gugma’g kalinaw pa.<br/>',NULL,18744,4);
INSERT INTO stanza VALUES('CB996','5','Mosalig ko Kanimo,<br/>Sa pagsalig magdayeg,<br/>Magpagaan, mag-ayo,<br/>Ang pagsalig ko Nimo.<br/>',NULL,18745,5);
INSERT INTO stanza VALUES('CB996','6','Jesus, Manlul’was namo,<br/>Tigpas-an’s among kargo;<br/>Mosaka ko Kanimo,<br/>Mahigugma, magdayeg.<br/>',NULL,18746,6);
INSERT INTO stanza VALUES('CB997','1','Niingong Manlul’was,<br/>“Gamay rang kusog mo,<br/>Magtukaw’g mag-ampo,<br/>Akoy tanan nimo.”<br/>',NULL,18747,1);
INSERT INTO stanza VALUES('CB997','chorus','Gibayrang Jesus<br/>Tanan kong utang;<br/>Salang nagbili’g mansa,<br/>Giputi daw nieve.<br/>',NULL,18748,2);
INSERT INTO stanza VALUES('CB997','2','Ginoo, napalgan,<br/>Ang Imong gahum ray<br/>Mag-ayo’s sanlahon,<br/>Magtunaw’s katig-a.<br/>',NULL,18749,3);
INSERT INTO stanza VALUES('CB997','3','Kay way kaayo ko,<br/>Makaangkon’s grasya—<br/>Labhang mga sapot<br/>Sa dugo’s Cordero.<br/>',NULL,18750,4);
INSERT INTO stanza VALUES('CB997','4','Kon’s trono Mo ako<br/>Hingpit nang magbarug,<br/>“Namatay Ka’s pagl’was<br/>Nako,” m’oy idayeg.<br/>',NULL,18751,5);
INSERT INTO stanza VALUES('CB998','1','Nausa’s makasasala,<br/>Nagkinabuhi nga tawo;<br/>Gilansang sa krus si Cristo,<br/>Kinabuhi ’yang gihatag.<br/>',NULL,18752,1);
INSERT INTO stanza VALUES('CB998','chorus','Nianhi alang nato,<br/>Namatay alang nato;<br/>Oo, alang gayud nato.<br/>Nianhi’g namatay S’ya.<br/>',NULL,18753,2);
INSERT INTO stanza VALUES('CB1003','1','Nganong mabalaka ako?<br/>Di ba gipapas-an’s Anak<br/>Sa Dios ang sala ko?<br/>Utang nabayran nang Cristo,<br/>Paninglon pa ba kanako<br/>Sa Dios nga matarung?<br/>',NULL,18754,1);
INSERT INTO stanza VALUES('CB1003','2','Hingpit ang ’yang katubsanan,<br/>Tanang utang ’yang gibayran,<br/>Wa na’s kasugoan.<br/>Way kahadlok’s kasuko’s Dios,<br/>Sinabligan man’s ’yang dugo,<br/>Nga nagtabon nako.<br/>',NULL,18755,2);
INSERT INTO stanza VALUES('CB1003','3','S’yay nagbaton alang nako,<br/>Sa hingpit nga pagpasaylo,<br/>Utang ko naimpas;<br/>Dios di gyud maningil’s duha,<br/>Una’s ’yang Anak, dayon nako,<br/>Anak Kalig-onan.<br/>',NULL,18756,3);
INSERT INTO stanza VALUES('CB1003','4','Busa may kalinaw’g pahuway,<br/>Nabuhat N’yang labing ma’yo,<br/>Nahigawas na ko;<br/>Sa epektibo N’yang dugo,<br/>Di na gyud ko hukman sa Dios,<br/>S’ya may puli nako!<br/>',NULL,18757,4);
INSERT INTO stanza VALUES('CB1006','1','May tubod nga puno’s dugo<br/>Sa kilirang Jesus;<br/>Kon dangpan ta kining tubod,<br/>Sala mangawala:<br/>Sala mangawala,<br/>Sala mangawala;<br/>Kon dangpan ta kining tubod,<br/>Sala mangawala.<br/>',NULL,18758,1);
INSERT INTO stanza VALUES('CB1006','2','Nagkalipay ang tulisang<br/>Nakakita’s tubod;<br/>Bisan dautan sama n’ya,<br/>Hugasan ko’s tubod:<br/>Hugasan ko’s tubod,<br/>Hugasan ko’s tubod;<br/>Bisan dautan sama n’ya,<br/>Hugasan ko’s tubod.<br/>',NULL,18759,2);
INSERT INTO stanza VALUES('CB1006','3','Dugo’s Corderong gipatay<br/>Di mawad-an’s gahum,<br/>Hangtud tinubos maluwas,<br/>Di na makasala:<br/>Di na makasala,<br/>Di na makasala;<br/>Hangtud tinubos maluwas,<br/>Di na makasala.<br/>',NULL,18760,3);
INSERT INTO stanza VALUES('CB1006','4','Sukad nakita’s pagtoo<br/>Ang dugong sangkap Mo,<br/>Gugmang nagtubos, tema ko<br/>Hangtud gyud mamatay:<br/>Hangtud gyud mamatay,<br/>Hangtud gyud mamatay;<br/>Gugmang nagtubos, tema ko<br/>Hangtud gyud mamatay.<br/>',NULL,18761,4);
INSERT INTO stanza VALUES('CB1006','5','Kon maghilom na’s lubnganan<br/>Kining dilang yungit,<br/>Sa pagkabanhaw mag-awit’s<br/>Gahum Mong nagluwas:<br/>Gahum Mong nagluwas,<br/>Gahum Mong nagluwas;<br/>Sa pagkabanhaw mag-awit’s<br/>Gahum Mong nagluwas.<br/>',NULL,18762,5);
INSERT INTO stanza VALUES('CB1007','1','Nahugasan ka ba’s dugo’s Cordero?<br/>Nahinloan na ba ni Jesus?<br/>Nisalig ba’s grasya N’ya ning taknaa?<br/>Nahugasan ka ba’s dugo N’ya?<br/>',NULL,18763,1);
INSERT INTO stanza VALUES('CB1007','chorus','Nahugasan na ba<br/>Sa dugong makahinlo’s kalag?<br/>Biste mo puti ba sama sa nieve?<br/>Nahugasan ka ba’s dugo N’ya?<br/>',NULL,18764,2);
INSERT INTO stanza VALUES('CB1007','2','Adlaw-adlaw naglakaw ba uban N’ya?<br/>Nahugasan ka ba’s dugo N’ya?<br/>Nagpahuway ba matag gutlo’s Gilansang?<br/>Nahugasan ka ba’s dugo N’ya?<br/>',NULL,18765,3);
INSERT INTO stanza VALUES('CB1007','3','Biste mo puti ba inig-anhi N’ya?<br/>Nahugasan ka ba’s dugo N’ya?<br/>Kalag mo andam ba sa ’yang presensya?<br/>Nahugasan ka ba’s dugo N’ya?<br/>',NULL,18766,4);
INSERT INTO stanza VALUES('CB1007','4','Bisteng namansahan’s sala ihiklin,<br/>Pahugas ka’s dugo’s Cordero;<br/>May tubod alang sa paghinlo’s kalag,<br/>Pahugas ka’s dugo’s Cordero.<br/>',NULL,18767,5);
INSERT INTO stanza VALUES('CB1008','1','Unsay maghinlo’s sala?<br/>Ang dugo lamang ni Jesus;<br/>Unsa ang makaayo?<br/>Ang dugo lamang ni Jesus.<br/>',NULL,18768,1);
INSERT INTO stanza VALUES('CB1008','chorus','O bililhong dugo,<br/>Nagpaputi nako;<br/>Way laing tuboran,<br/>Ang dugo lamang ni Jesus.<br/>',NULL,18769,2);
INSERT INTO stanza VALUES('CB1008','2','Alang sa paghinlo ko—<br/>Ang dugo lamang ni Jesus!<br/>Alang sa pasaylo ko—<br/>Ang dugo lamang ni Jesus!<br/>',NULL,18770,3);
INSERT INTO stanza VALUES('CB1008','3','Way makapapas’ sala—<br/>Ang dugo lamang ni Jesus!<br/>Di buhat, kondi’ grasya—<br/>Ang dugo lamang ni Jesus!<br/>',NULL,18771,4);
INSERT INTO stanza VALUES('CB1008','4','Kalinaw’g paglaum ko—<br/>Ang dugo lamang ni Jesus!<br/>Ug ang pagkamatarung—<br/>Ang dugo lamang ni Jesus!<br/>',NULL,18772,5);
INSERT INTO stanza VALUES('CB1009','1','Buot bang mal’was’ kabug-at’s sala?<br/>May gahum’s dugo, gahum’s dugo;<br/>Buot ka bang modaug’s dautan?<br/>Dugo ni Jesus may gahum.<br/>',NULL,18773,1);
INSERT INTO stanza VALUES('CB1009','chorus','May gahum nga kahibulongan,<br/>Sa dugo’s Cordero;<br/>May gahum nga kahibulongan!<br/>Sa bililhon N’ya nga dugo.<br/>',NULL,18774,2);
INSERT INTO stanza VALUES('CB1009','2','Sa kailibgon paluwas ka ba?<br/>May gahum’s dugo, gahum’s dugo;<br/>Duol karon ug magpahinlo ka,<br/>Dugo ni Jesus may gahum.<br/>',NULL,18775,3);
INSERT INTO stanza VALUES('CB1009','3','Buot ka bang moputi pa’s nieve?<br/>May gahum’s dugo, gahum’s dugo;<br/>Mansa wad-on’s agay’s kinabuhi;<br/>Dugo ni Jesus may gahum.<br/>',NULL,18776,4);
INSERT INTO stanza VALUES('CB1009','4','Sa Hari mo moalagad ka ba?<br/>May gahum’s dugo, gahum’s dugo;<br/>Adlaw-adlaw magdayeg ka ba N’ya?<br/>Dugo ni Jesus may gahum.<br/>',NULL,18777,5);
INSERT INTO stanza VALUES('CB1013','1','Unsay dili makapasaag sa mga tawo?<br/>Way lain, gugma ni Jesus!<br/>Unsay makapausab’s mga masalaypon?<br/>Way lain, gugma ni Jesus!<br/>',NULL,18778,1);
INSERT INTO stanza VALUES('CB1013','chorus','Gugma ra ni Jesus ang makapugong!<br/>Gugma ra ni Jesus ang makalig-on!<br/>Walay makakabig’s makasasala,<br/>Way lain, gugma ni Jesus!<br/>',NULL,18779,2);
INSERT INTO stanza VALUES('CB1013','2','Unsay makakuha’s kapait sa nag-antus?<br/>Way lain, gugma ni Jesus!<br/>Unsay makapahid’s mga luha’s nagbakho?<br/>Way lain, gugma ni Jesus.<br/>',NULL,18780,3);
INSERT INTO stanza VALUES('CB1013','3','Unsang haplas moayo’s samad’s kasingkasing?<br/>Way lain, gugma ni Jesus!<br/>Unsang ulan sa tinghulaw ang makalipay?<br/>Way lain, gugma ni Jesus!<br/>',NULL,18781,4);
INSERT INTO stanza VALUES('CB1013','4','Unsay makatagbaw’s kakawangan’s mga tawo?<br/>Way lain, gugma ni Jesus!<br/>Unsay makalamoy sa gahum’s kamatayon?<br/>Way lain, gugma ni Jesus!<br/>',NULL,18782,5);
INSERT INTO stanza VALUES('CB1017','1','Nagpakatawo si Cristo sama gayud kanako,<br/>Namatay sa krus aron mahigawas ko ni Adam,<br/>Nabanhaw, ug Espiritu S’ya nga nipuyo nako,<br/>Ma-kinabuhi ko.<br/>',NULL,18783,1);
INSERT INTO stanza VALUES('CB1017','chorus',replace('Unang Chorus:<br/>O himaya! Hallelujah!<br/>O himaya! Hallelulah!<br/>O himaya! Hallelujah!<br/>Cristo kinabuhi!\nIkaduhang Chorus:<br/>Mananaug! Hallelujah!<br/>Mananaug! Hallelujah!<br/>Mananaug! Hallelujah!<br/>Cristo akong tanan!<br/>','\n',char(10)),NULL,18784,2);
INSERT INTO stanza VALUES('CB1019','1','May punoan nangutanang Jesus,<br/>Unsaon nga s’ya mahayagan, mal’was;<br/>“Ipanganak ka gyud pag-usab,” tin-awng<br/>Tubag’s Agalon n’ya.<br/>',NULL,18785,1);
INSERT INTO stanza VALUES('CB1019','chorus','“Ipanganak gyud ka!“<br/>“Ianak pag-usab!“<br/>“Ipanganak gyud ka pag-usab karon,“<br/>Moingon Ko nimo.<br/>',NULL,18786,2);
INSERT INTO stanza VALUES('CB1019','2','Paminawa ninyo ang pulong N’ya,<br/>Nga bug-at gyud nga gisulti ni Jesus<br/>“Ipanganak gyud ka pag-usab,” kini<br/>Di unta makawang.<br/>',NULL,18787,3);
INSERT INTO stanza VALUES('CB1019','3','O kamong mosulod sa pahulay,<br/>Moduyog sa awit’s mga tinubos,<br/>“Ipanganak gyud ka pag-usab,” imo<br/>Dayong kinabuhi.<br/>',NULL,18788,4);
INSERT INTO stanza VALUES('CB1020','1','Kinsay makaluwas nato?<br/>Si Cristo! Si Cristo!<br/>Kinsay ma-kinabuhi ta?<br/>Si Cristo!<br/>Si Cristo! Si Cristo!<br/>S’ya ray makal’was nato,<br/>Si Cristo!<br/>',NULL,18789,1);
INSERT INTO stanza VALUES('CB1021','1','Naulipon ta sa sala,<br/>Nahiloan’s ikot;<br/>Si Cristo ray makaluwas<br/>Nato’s kamatayon.<br/>S’ya ang Walay Katapusan,<br/>Buot mol’was nato;<br/>Kon dili ta motoo N’ya,<br/>Mamatay’s kasubo.<br/>',NULL,18790,1);
INSERT INTO stanza VALUES('CB1024','1','Si Cristo ray imong gikin’hanglan,<br/>Siya ang Dios nga nagpakatawo;<br/>Giantus N’ya tanang kasakitan,<br/>Namatay S’ya aron sala mo mahinloan.<br/>',NULL,18791,1);
INSERT INTO stanza VALUES('CB1024','chorus','Gikin’hanglan mo si Jesus!<br/>Tanan nagkin’hanglan N’ya!<br/>Alang sa katubsanan,<br/>Alang sa kaluwasan,<br/>Sa kinabuhing dayon,<br/>S’ya kinahanglan!<br/>',NULL,18792,2);
INSERT INTO stanza VALUES('CB1024','2','Nabanhaw S’ya ug nikayab’s langit,<br/>Aron mahatag N’yang kinabuhi;<br/>Kon sa kasingkasing tuohan mo,<br/>Ipaambit N’ya nimo tanang gikin’hanglan.<br/>',NULL,18793,3);
INSERT INTO stanza VALUES('CB1024','3','Hayagan N’ya ang kasingkasing mo,<br/>Pasayloon ug l’wason ka’s gahum;<br/>Hinloan’s dugo tanang mansa mo,<br/>Hatagan’s kinabuhi’s Dios, kin’hanglan mo S’ya!<br/>',NULL,18794,4);
INSERT INTO stanza VALUES('CB1024','4','Kinabuhi mo dunay nakulang,<br/>Sa paglabay’s tuig nagkagrabe;<br/>Si Jesus ray makatagbaw ni’ni,<br/>Kakawangan S’yay mopuno, kin’hanglan mo S’ya!<br/>',NULL,18795,5);
INSERT INTO stanza VALUES('CB1024','chorus','Gikin’hanglan mo si Jesus!<br/>Tanan nagkin’hanglan N’ya!<br/>Paglikay’s kakawangan,<br/>Pagbaton’s kamat’oran,<br/>Kinabuhi may tumong,<br/>Kinahanglan S’ya.<br/>',NULL,18796,6);
INSERT INTO stanza VALUES('CB1024','5','Kalibutan puno’s kasakitan,<br/>Sa kalisud walay makatabang;<br/>Tanan kawang, di mo kasaligan,<br/>Ug nagpadayag kinahanglan mo si Jesus!<br/>',NULL,18797,7);
INSERT INTO stanza VALUES('CB1025','1','Kalibutan kon biyaan,<br/>Si Cristo m’oy mabatonan;<br/>Gawas Niya tanang butang<br/>Basiyo ug kakawangan!<br/>',NULL,18798,1);
INSERT INTO stanza VALUES('CB1025','chorus','O pagkadato ni Cristo,<br/>Magtagbaw’s kinahanglan mo!<br/>Katam-is N’ya’g kamaayo,<br/>Labaw sa gitinguha mo.<br/>',NULL,18799,2);
INSERT INTO stanza VALUES('CB1025','2','Kon si Cristo madawat mo,<br/>Ubang butang wa nay gusto;<br/>Kay S’ya ray gikin’hanglan mo,<br/>Magtagbaw’s kasingkasing mo.<br/>',NULL,18800,3);
INSERT INTO stanza VALUES('CB1025','3','Kalibutan bisan dako,<br/>Gamay ang kasingkasing mo,<br/>Kalibutan ug kadato,<br/>Di makapuno kanimo.<br/>',NULL,18801,4);
INSERT INTO stanza VALUES('CB1025','4','Kon may Cristo, may kalipay;<br/>Kon way Cristo, kasakit lang;<br/>Kon may Cristo masanagon,<br/>Kon wa Siya, way paglaum.<br/>',NULL,18802,5);
INSERT INTO stanza VALUES('CB1027','1','Malomong nanawag si Jesus karon—<br/>Nanawag nimo’g nako;<br/>Mapailubon nga naghulat Siya—<br/>Kanimo ug kanako!<br/>',NULL,18803,1);
INSERT INTO stanza VALUES('CB1027','chorus','Uli na mo!<br/>Kamong gikapoy, uli!<br/>Maikagon nga nanawag si Jesus,<br/>Pauli na mo karon!<br/>',NULL,18804,2);
INSERT INTO stanza VALUES('CB1027','2','Nganong maglangan, Jesus nangamuyo—<br/>Alang nimo ug nako?<br/>Nganong di pamation ’yang kaluoy—<br/>Alang nimo ug nako?<br/>',NULL,18805,3);
INSERT INTO stanza VALUES('CB1027','3','Panahon dali ra gyud nga molabay—<br/>Gikan nimo ug nako;<br/>Kamatayon moabot di madugay—<br/>Nganha nimo ug nako.<br/>',NULL,18806,4);
INSERT INTO stanza VALUES('CB1027','4','Katingad-ang gugma Iyang gisaad—<br/>Alang nimo ug nako;<br/>Bisan sad-an, maluoy’g mopasaylo—<br/>S’ya kanimo’g kanako.<br/>',NULL,18807,5);
INSERT INTO stanza VALUES('CB1028','1','Malomong gipapauli ka N’ya—<br/>Gipapauli ka karon!<br/>Nganong magpahilayo ka’s gugma,<br/>Nagkalayo, layo pa?<br/>',NULL,18808,1);
INSERT INTO stanza VALUES('CB1028','chorus','Gitawag ka! gitawag ka!<br/>Gitawag ka N’ya, gitawag ni<br/>Jesus karon!<br/>',NULL,18809,2);
INSERT INTO stanza VALUES('CB1028','2','Gitawag ni Jesus ang gikapoy<br/>Aron papahulayon N’ya;<br/>Dad-a N’yang luwan, mabulahan ka:<br/>Di gyud isalikway ka.<br/>',NULL,18810,3);
INSERT INTO stanza VALUES('CB1028','3','Ari na, kay naghulat S’ya nimo,<br/>Naghulat kanimo karon!<br/>Dad-ang mga sala’s tiilan N’ya,<br/>Ayaw na paglangana.<br/>',NULL,18811,4);
INSERT INTO stanza VALUES('CB1028','4','Jesus naghangyo, O pamatia!<br/>Pamatia karon Siya!<br/>Maghugyaw ang motoo’s ngalan N’ya,<br/>Bangon ug pauli na!<br/>',NULL,18812,5);
INSERT INTO stanza VALUES('CB1037','1','Sala bisan mapula,<br/>Pution sama’s nieve;<br/>Sala bisan mapula,<br/>Pution sama’s nieve;<br/>Bisa’g unsa kapula,<br/>Pution gyud N’ya,<br/>Sala bisan mapula,<br/>Sala bisan mapula,<br/>Pution sama’s nieve,<br/>Pution sama’s nieve.<br/>',NULL,18813,1);
INSERT INTO stanza VALUES('CB1037','2','Paminawang Ginoo,<br/>Bumalik kamo sa Dios!<br/>Paminawang Ginoo,<br/>Bumalik kamo sa Dios!<br/>Ang tawag paminawa<br/>Nga puno’s gugma.<br/>Ang tingog paminawa,<br/>Ang tingog paminawa.<br/>Bumalik kamo sa Dios!<br/>Bumalik kamo sa Dios!<br/>',NULL,18814,2);
INSERT INTO stanza VALUES('CB1037','3','Sala mo pasayloon,<br/>Ug dili na handumon;<br/>Sala mo pasayloon,<br/>Ug dili na handumon;<br/>Tan-awa, O katawhan,<br/>Ang Ginoo mo;<br/>Sala mo pasayloon,<br/>Sala mo pasayloon,<br/>Ug dili na handumon,<br/>Ug dili na handumon.<br/>',NULL,18815,3);
INSERT INTO stanza VALUES('CB1038','1','Sa sala kon ikaw gibug-atan,<br/>Pasudla dayon si Jesus;<br/>Kon buot kinabuhi mabag-o,<br/>Pasudla dayon si Jesus.<br/>',NULL,18816,1);
INSERT INTO stanza VALUES('CB1038','chorus','Ayaw pagduhaduha,<br/>Karon magpasakop ka,<br/>Dawaton Siya karon;<br/>Si Jesus pasudlon dayon.<br/>',NULL,18817,2);
INSERT INTO stanza VALUES('CB1038','2','Kon sa kaputli nagtinguha ka,<br/>Pasudla dayon si Jesus;<br/>Naghinlong tubod nag-agay’s duol,<br/>Pasudla dayon si Jesus.<br/>',NULL,18818,3);
INSERT INTO stanza VALUES('CB1038','3','Kon may unos nga di mo madaug,<br/>Pasudla dayon si Jesus;<br/>Kon may kahaw-ang nga di mapuno,<br/>Pasudla dayon si Jesus.<br/>',NULL,18819,4);
INSERT INTO stanza VALUES('CB1043','1','Kinabuhi mubo ra,<br/>Sama’s dahong nalaya,<br/>Sama’s binangang trigo,<br/>Mosayo!<br/>Kadali’s mga adlaw,<br/>Hitabo takulahaw,<br/>Kamatayon moduaw,<br/>Mosayo!<br/>',NULL,18820,1);
INSERT INTO stanza VALUES('CB1043','chorus','Mosayo! Mosayo!<br/>Samtang nagtawag si Jesus,<br/>Mosayo!<br/>Kon maghulat ka’s sala,<br/>Masirhan ka na unya,<br/>Maulahing pagt’yabaw;<br/>Mosayo!<br/>',NULL,18821,2);
INSERT INTO stanza VALUES('CB1043','2','Bulak daling madugta,<br/>Kusog, ’tahum mawala;<br/>Di ka magdugay dinhi,<br/>Mosayo!<br/>Samtang gidapit ka’s Dios,<br/>Ayaw na paglaag pa,<br/>Basin ug malaglag ka,<br/>Mosayo!<br/>',NULL,18822,3);
INSERT INTO stanza VALUES('CB1043','3','Katulin sa panahon,<br/>Kaduol na’s paghukom,<br/>Dangop’s ’yang mga bukton,<br/>Mosayo!<br/>Bili imong kwentahon,<br/>Sa di pang kamatayon,<br/>Aron di mapildehan’s<br/>Kalag mo.<br/>',NULL,18823,4);
INSERT INTO stanza VALUES('CB1043','4','Pasidaan dawata,<br/>Ang Ginoo pilia,<br/>Kalangitan naghugyaw,<br/>Mosayo!<br/>Sa kahayag sulod na,<br/>Patarunga nimo S’ya,<br/>Dawat’s kinabuhi N’ya,<br/>Mosayo!<br/>',NULL,18824,5);
INSERT INTO stanza VALUES('CB1044','1','Andam ka na ba karon<br/>Makig-atubang sa Dios?<br/>Andam ka na ba karon<br/>Mosugat Niya?<br/>Andam na ba, andam na ba,<br/>Nga mosugat N’ya?<br/>',NULL,18825,1);
INSERT INTO stanza VALUES('CB1047','1','Eternidad! Eternidad!<br/>Unsaon mong Eternidad?<br/>Ikaw, ako, pangutan-on,<br/>Unsaon mong Eternidad?<br/>Tubaga higala, karon,<br/>Unsaon mong Eternidad?<br/>',NULL,18826,1);
INSERT INTO stanza VALUES('CB1047','2','Eternidad! Eternidad!<br/>Unsaon mong Eternidad?<br/>Daghang nipili ni Cristo,<br/>Nib’ya’s tanang sala nila;<br/>Nahimo S’yang pahat nila:<br/>Unsaon mong Eternidad?<br/>',NULL,18827,2);
INSERT INTO stanza VALUES('CB1047','3','Eternidad! Eternidad!<br/>Unsaon mong Eternidad?<br/>Nib’ya ka’s piut nga dalan,<br/>Pagkaunlod gipaingnan;<br/>Unsa may imong dangatan—<br/>Unsaon mong Eternidad?<br/>',NULL,18828,3);
INSERT INTO stanza VALUES('CB1047','4','Eternidad! Eternidad!<br/>Unsaon mong Eternidad?<br/>Toohi na ning taknaa,<br/>Grasya’g gahum sa Manlul’was:<br/>Ug malipayong tubaga,<br/>Luwas na sa Eternidad!<br/>',NULL,18829,4);
INSERT INTO stanza VALUES('CB1048','1','Sa kahimtang, way gisaligan,<br/>Apan gipakamatyan Mo,<br/>Gidapit moanha Nimo,<br/>Cordero’s Dios, nia ako!<br/>',NULL,18830,1);
INSERT INTO stanza VALUES('CB1048','2','Nia, wa maghulat, sala<br/>Mapapas ba’g bisan gamay;<br/>Kay’s tanan makahinlo Ka;<br/>Cordero’s Dios, nia ako!<br/>',NULL,18831,2);
INSERT INTO stanza VALUES('CB1048','3','Nia, bisan wa kaseguro,<br/>Daghang sumpaki’g pagduda;<br/>Bingkil’s sulod, kulba’s gawas,<br/>Cordero’s Dios, nia ako!<br/>',NULL,18832,3);
INSERT INTO stanza VALUES('CB1048','4','Nia, buta, ug dautan,<br/>Diha Kanimo mapalgan<br/>Ang kadato ug kaayo,<br/>Cordero’s Dios, nia ako!<br/>',NULL,18833,4);
INSERT INTO stanza VALUES('CB1048','5','Nia suma’s kahimtang ko,<br/>Pasayloon, hinloan Mo;<br/>Sa saad Mo nitoo ko,<br/>Cordero’s Dios, nia ako!<br/>',NULL,18834,5);
INSERT INTO stanza VALUES('CB1048','6','Nia suma’s kahimtang ko,<br/>Gugma magguba’s nag-ulang;<br/>Maimoha ra gyud ako,<br/>Cordero’s Dios, nia ako!<br/>',NULL,18835,6);
INSERT INTO stanza VALUES('CB1050','1','Sa gapos, kasubo’g kangitngit,<br/>Jesus, nia ako karon!<br/>Magawas, malipay’g mohayag,<br/>Jesus, nia ako!<br/>Gikan’s sakit ngadto’s kahimsog,<br/>Sa kawad-on ngadto’s kadato,<br/>Gikan’s sala nganha Kanimo,<br/>Jesus, nia ako!<br/>',NULL,18836,1);
INSERT INTO stanza VALUES('CB1050','2','Gikan’s kaulaw’g kapildehan,<br/>Jesus, nia ako karon!<br/>Ngadto sa kadaugan sa krus,<br/>Jesus, nia ako!<br/>Sa kasakit ngadto’s pag-ayo,<br/>Sa unos ngadto’s kalinaw Mo,<br/>Sa kalisud ngadto’s paghugyaw,<br/>Jesus, nia ako!<br/>',NULL,18837,2);
INSERT INTO stanza VALUES('CB1050','3','Gikan’s kagarbo’g way pahulay,<br/>Jesus, nia ako karon!<br/>Papuy-a ko’s kabubut-on Mo,<br/>Jesus, nia ako!<br/>Sa kaugalingon ngadto’s gugma,<br/>Sa kasubo ngadto’s kalipay,<br/>Palupara ko paitaas,<br/>Jesus, nia ako!<br/>',NULL,18838,3);
INSERT INTO stanza VALUES('CB1050','4','Gikan’s kahadlok’s kamatayon,<br/>Jesus, nia ako karon!<br/>Ngadto’s kalipay nga Imoha,<br/>Jesus, nia ako!<br/>Gikan’s di maasoyng kadaut,<br/>Ngadto’s panong gihigugma Mo,<br/>Magsud-ong’s nawong Mo sa dayon,<br/>Jesus, nia ako!<br/>',NULL,18839,4);
INSERT INTO stanza VALUES('CB1051','1','Nagdapit Ka, Jesus,<br/>Tingog Mo malomo;<br/>Moduol Nimo’g mahinlo<br/>Sa dugo’s Calvario.<br/>',NULL,18840,1);
INSERT INTO stanza VALUES('CB1051','chorus','Moduol ako<br/>Nimo, Ginoo,<br/>Hinlo-i sa dugo nga<br/>Niagas’ Calvario.<br/>',NULL,18841,2);
INSERT INTO stanza VALUES('CB1051','2','Bisan dautan ko,<br/>Gipasaligan Mo;<br/>Kadautan ko hinloan,<br/>Maputli’g way buling.<br/>',NULL,18842,3);
INSERT INTO stanza VALUES('CB1051','3','Jesus nagmatuod<br/>Sa buhat N’ya’s sulod,<br/>Aron di magharing sala,<br/>Grasya pun-an’s grasya.<br/>',NULL,18843,4);
INSERT INTO stanza VALUES('CB1051','4','Ug nisaksi S’ya sa<br/>Mga maunongon,<br/>Nga matag saad tumanon,<br/>Sa hangyo’s pagtoo.<br/>',NULL,18844,5);
INSERT INTO stanza VALUES('CB1051','5','Daygon ang dugo Mo!<br/>Daygon ang grasya Mo!<br/>Pagkamatarung ug kusog,<br/>Gasa Mo kanamo.<br/>',NULL,18845,6);
INSERT INTO stanza VALUES('CB1052','1','Nahilayo ako sa Dios,<br/>Karon mouli;<br/>Dugay nang nagpakasala,<br/>Karon mouli.<br/>',NULL,18846,1);
INSERT INTO stanza VALUES('CB1052','chorus','Mouli, mouli,<br/>Di na maglaag;<br/>Buksing bukton Mo’s gugma;<br/>Mouli na ko.<br/>',NULL,18847,2);
INSERT INTO stanza VALUES('CB1052','2','Giusikang mga tuig,<br/>Karon mouli;<br/>Maghinulsol uban’s luha,<br/>Ako mouli.<br/>',NULL,18848,3);
INSERT INTO stanza VALUES('CB1052','3','Gikapoy’s sala’g paglaag,<br/>Karon mouli;<br/>Mosalig ko sa gugma Mo;<br/>Ako mouli.<br/>',NULL,18849,4);
INSERT INTO stanza VALUES('CB1052','4','Kalag nasakit, guol gyud,<br/>Karon mouli;<br/>Bag-ohang kusog, paglaum:<br/>Ako mouli.<br/>',NULL,18850,5);
INSERT INTO stanza VALUES('CB1052','5','Bugtong hangyo’g paglaum ko,<br/>Karon mouli;<br/>Namatay Ka alang nako;<br/>Ako mouli.<br/>',NULL,18851,6);
INSERT INTO stanza VALUES('CB1052','6','Gikin’hanglan kong dugo N’ya,<br/>Karon mouli;<br/>Putia ko labaw’s nieve;<br/>Ako mouli.<br/>',NULL,18852,7);
INSERT INTO stanza VALUES('CB1054','1','Ay’ ko’g labyi, Manluluwas,<br/>Dunggang tuaw ko;<br/>Samtang’s uban nagtawag Ka,<br/>Ayaw ko’g labyi.<br/>',NULL,18853,1);
INSERT INTO stanza VALUES('CB1054','chorus','Manluluwas,<br/>Pamatia ko;<br/>Samtang’s uban nagtawag Ka,<br/>Ayaw ko’g labyi.<br/>',NULL,18854,2);
INSERT INTO stanza VALUES('CB1054','2','Sa trono Mo sa kaluoy<br/>Papahulaya;<br/>Nagluhod mahinulsolon,<br/>Wa koy pagtoo.<br/>',NULL,18855,3);
INSERT INTO stanza VALUES('CB1054','3','Nagsalig ra sa buhat Mo,<br/>Pangitaon Ka;<br/>Esp’ritung samdan ayoha,<br/>L’wasa’s grasya Mo.<br/>',NULL,18856,4);
INSERT INTO stanza VALUES('CB1054','4','Labaw Ka pa’s kinabuhi,<br/>Tubod’s kalipay;<br/>Walay lain gawas Nimo’s<br/>Langit ba’g yuta.<br/>',NULL,18857,5);
INSERT INTO stanza VALUES('CB1057','1','Jesus, hinigugma ko,<br/>Padangpa’s sabakan Mo,<br/>Sa nagkadagkong balud,<br/>Sa unos nagkakusog:<br/>Tagoi, O Manlul’was,<br/>Hangtud unos molabay;<br/>Hilwas nga giyahan Mo,<br/>O kalag ko dawata.<br/>',NULL,18858,1);
INSERT INTO stanza VALUES('CB1057','2','Way lain nga kadangpan,<br/>Kasaligan’s kalag ko;<br/>O ayaw ko’g biyai,<br/>Lipaya ko’g tabangi.<br/>Na’ Nimong pagsalig Ko,<br/>Dad-on tanang tabang Mo;<br/>Taboni ang ulo ko,<br/>Sa landong sa pako Mo.<br/>',NULL,18859,2);
INSERT INTO stanza VALUES('CB1057','3','Ikaw ray gikin’hanglan,<br/>Kay labaw Ka sa tanan;<br/>Giayo Mong natumba,<br/>Gidasig ang naluya.<br/>Matarung, balaan Ka<br/>Dili gyud ko matarung;<br/>Dautan, puno’s sala,<br/>Kamat’oran, grasya Ka.<br/>',NULL,18860,3);
INSERT INTO stanza VALUES('CB1057','4','Na’ Nimong daghang grasya,<br/>Grasyang tabon’s sala ko;<br/>Dad-i’s sapang mag-ayo,<br/>Magputli nako’s sulod.<br/>Tubod Ka’s kinabuhi,<br/>Way bayad paimna ko;<br/>Sa sulod ko magtubod,<br/>Hangtud gayud sa hangtud.<br/>',NULL,18861,4);
INSERT INTO stanza VALUES('CB1058','1','O nasiak nga Bato,<br/>Patagoa’s sulod Mo;<br/>Dugo’g tubig niagay,<br/>Sa kilid Mong gidughang,<br/>Dobleng pag-ayo’s sala,<br/>Luwasa’s gahum’s sala.<br/>',NULL,18862,1);
INSERT INTO stanza VALUES('CB1058','2','Dili ang paghago ko<br/>Ang magtuman’s sugo Mo;<br/>Bisan di mopahulay,<br/>Luha ko sigeng agay,<br/>Di ’ni magpala’s sala,<br/>L’wasa gyud ko’s grasya Mo.<br/>',NULL,18863,2);
INSERT INTO stanza VALUES('CB1058','3','Kamot ko walay dala,<br/>Krus Mo m’oy saligan ra;<br/>Hubo, ako bistihe,<br/>Way mahimo, grasyahi,<br/>Hugaw, adto’s tuboran,<br/>Hugasi, kay mamatay.<br/>',NULL,18864,3);
INSERT INTO stanza VALUES('CB1058','4','Kon ginhawa mohunong,<br/>Mga mata mopiyong,<br/>Moadto’s wa masayri,<br/>Moatubang’s hukmanan,<br/>O nasiak nga Bato,<br/>Patagoa’s sulod Mo.<br/>',NULL,18865,4);
INSERT INTO stanza VALUES('CB1059','1','Paduola ko sa krus,<br/>Didto may tuboran,<br/>Way bayad nga moayo,<br/>Gikan sa Calvario.<br/>',NULL,18866,1);
INSERT INTO stanza VALUES('CB1059','chorus','Diha’s krus, diha’s krus,<br/>Naang himaya ko;<br/>Kalag nga ’yang gitubos<br/>Di gyud mabulag’s krus.<br/>',NULL,18867,2);
INSERT INTO stanza VALUES('CB1059','2','Duol sa krus, kalag ko<br/>Napalgan’s gugma Mo;<br/>Gihayagan ko didto’s<br/>Bito’n’s Kabugason.<br/>',NULL,18868,3);
INSERT INTO stanza VALUES('CB1059','3','Duol’s krus, Cordero’s Dios,<br/>Pakit-a’s hitabo;<br/>Palakwa adlaw-adlaw<br/>Diha’s landong sa krus.<br/>',NULL,18869,4);
INSERT INTO stanza VALUES('CB1059','4','Duol’s krus magtukaw ko,<br/>Mosalig, molaum,<br/>Hangtud nawong N’ya makita,<br/>Ig-uban S’ya’s dayon.<br/>',NULL,18870,5);
INSERT INTO stanza VALUES('CB1060','1','Gibiyaan Mo ang korona ug trono,<br/>Sa pag-anhi alang nako;<br/>Apan’s Bethlehem way lawak nga napalgan<br/>Aron Imo nga matawhan.<br/>',NULL,18871,1);
INSERT INTO stanza VALUES('CB1060','chorus','Umari Ka’s kasingkasing ko,<br/>May lawak alang Kanimo!<br/>Umari Ka’s kasingkasing ko,<br/>May lawak alang Kanimo!<br/>',NULL,18872,2);
INSERT INTO stanza VALUES('CB1060','2','Langit nilanog sa awit’s manulonda,<br/>Nagmantala’s kahalangdon Mo,<br/>Apan natawo Kang labi nga kabus,<br/>Sa dako nga pagpaubos.<br/>',NULL,18873,3);
INSERT INTO stanza VALUES('CB1060','3','Mga milo ug tanang kalanggaman,<br/>Sa lasang may kapahulayan;<br/>Apan Anak’s Dios natawo sa pasungan,<br/>Nagdako sa kamingawan.<br/>',NULL,18874,4);
INSERT INTO stanza VALUES('CB1060','4','Nianhi Ka uban sa buhing Pulong,<br/>Aron katawhan Mo luwason;<br/>Apan gipurongan Ka’g tunok, gitamay,<br/>Didto’s Calvario gipatay.<br/>',NULL,18875,5);
INSERT INTO stanza VALUES('CB1060','chorus','Umari Ka’s kasingkasing ko,<br/>Krus bugtong gisaligan ko;<br/>Umari Ka’s kasingkasing ko,<br/>Krus bugtong gisaligan ko.<br/>',NULL,18876,6);
INSERT INTO stanza VALUES('CB1060','5','Langit molanog sa awit sa pagdayeg,<br/>Sa moabot N’yang pagdaug,<br/>Tawgon Mo unta sa trono Mo magbarug,<br/>Sultiang may lawak ako!<br/>',NULL,18877,7);
INSERT INTO stanza VALUES('CB1060','chorus','Malipay mag-awit’s pagdayeg,<br/>Kon moabot Ka’g tawgon ko;<br/>Malipay mag-awit’s pagdayeg,<br/>Kon moabot Ka’g tawgon ko.<br/>',NULL,18878,8);
INSERT INTO stanza VALUES('CB1061','1','Sulod na sa kasingkasing ko,<br/>Nag-ampo ko, Ginoo;<br/>Gihasol, gikapoyng kalag ko,<br/>Sulod na nako karon.<br/>',NULL,18879,1);
INSERT INTO stanza VALUES('CB1061','chorus','Sulod na sa kasingkasing,<br/>Sulod na, Ginoong Jesus;<br/>Mopuyo Ka sa sulod ko,<br/>Karon dayon, O Ginoo.<br/>',NULL,18880,2);
INSERT INTO stanza VALUES('CB1061','2','Sulod na sa kasingkasing ko,<br/>Laayng kinabuhi ko;<br/>Mabug-at ang luwan sa sala,<br/>Sulod na’g mopuyo Ka.<br/>',NULL,18881,3);
INSERT INTO stanza VALUES('CB1061','3','Sulod na sa kasingkasing ko,<br/>Hinloi ug hayagi;<br/>Pun-a na sa Espiritu Mo,<br/>Sulod na ug gamhi ko.<br/>',NULL,18882,4);
INSERT INTO stanza VALUES('CB1062','1','Nianhi ako sa krus;<br/>Buta, luya, ug kabus;<br/>Tanan giisip—biya<br/>Kal’wasan mapalgan na.<br/>',NULL,18883,1);
INSERT INTO stanza VALUES('CB1062','chorus','Saligan Ka, Ginoo,<br/>Cordero sa Calvario,<br/>Niyukbo ko sa krus Mo,<br/>L’wasa ko, Jesus, karon.<br/>',NULL,18884,2);
INSERT INTO stanza VALUES('CB1062','2','Dugay’ng gipangandoy Ka;<br/>Dugay’ng gipuy-an’s sala;<br/>Matam-is giingnan Mo,<br/>“Hinloan Kong sala mo.”<br/>',NULL,18885,3);
INSERT INTO stanza VALUES('CB1062','3','Halaran Ka sa tanan—<br/>Higala ug kabtangan;<br/>Lawas ba o panahon—<br/>Maimo hangtud’s dayon.<br/>',NULL,18886,4);
INSERT INTO stanza VALUES('CB1062','4','Nisalig’s mga saad,<br/>Sa dugong gipadapat;<br/>Sa abug nihapa ko,<br/>Gilansang ubang Cristo.<br/>',NULL,18887,5);
INSERT INTO stanza VALUES('CB1064','1','Ganahang isugilon<br/>Ang butang’ langitnon,<br/>Ni Jesus, ’yang himaya,<br/>Bisan’s Iyang gugma.<br/>Sugilanon kanindot,<br/>Kay tinuod man gyud;<br/>Nagtagbaw’s pangandoy ko,<br/>Labaw’s tanang butang.<br/>',NULL,18888,1);
INSERT INTO stanza VALUES('CB1064','chorus','Ganahang isugilon,<br/>Tema unya’s himaya,<br/>Karaang sugilanon<br/>Ni Jesus, ’yang gugma.<br/>',NULL,18889,2);
INSERT INTO stanza VALUES('CB1064','2','Ganahang isugilon;<br/>Daw labi pang ’tahum<br/>Sa mga gihanduraw<br/>Ug’s tanang damgo ko,<br/>Dako ka’yog nahimo<br/>Kini alang nako;<br/>Kini maoy hinungdan<br/>Ako kang suginlan.<br/>',NULL,18890,3);
INSERT INTO stanza VALUES('CB1064','3','Ganahang isugilon;<br/>Kanindot sublion<br/>Ang magkatam-is pa gyud<br/>Matag sugilon ko.<br/>Isugilon labi na<br/>Sa wa pa ’kadungog<br/>Ang mensahe’s kal’wasan<br/>Sa Pulong balaan.<br/>',NULL,18891,4);
INSERT INTO stanza VALUES('CB1064','4','Ganahan sa’ng suginlan<br/>Silang nasayud na,<br/>Kay kagutom sama ra’s<br/>Bag-ong nakadungog.<br/>Unya’s himayang dayon<br/>Bag-ong awit awiton,<br/>Ang daang sugilanon<br/>M’oy tema gihapon.<br/>',NULL,18892,5);
INSERT INTO stanza VALUES('CB1065','1','O dakong kaluwasan!<br/>O dakong kaluwasan!<br/>O dakong kaluwasan!<br/>Jesus nagluwas!<br/>',NULL,18893,1);
INSERT INTO stanza VALUES('CB1065','chorus','Giguba ang nag-ulang!<br/>Giguba ang nag-ulang!<br/>Giguba ang nag-ulang!<br/>Jesus nagtangtang!<br/>',NULL,18894,2);
INSERT INTO stanza VALUES('CB1065','2','Sala ko gipasaylo!<br/>Kaulangan gikuha!<br/>Malinawon na ako!<br/>Jesus nagluwas!<br/>',NULL,18895,3);
INSERT INTO stanza VALUES('CB1065','3','Pagtintal ba o sala,<br/>Pagsamok ba sa Yawa;<br/>Bisan ang kalibutan,<br/>Di moulipon!<br/>',NULL,18896,4);
INSERT INTO stanza VALUES('CB1065','4','Moawit Hallelujah!<br/>Moawit Hallelujah!<br/>Moawit Hallelujah!<br/>Jesus nagluwas!<br/>',NULL,18897,5);
INSERT INTO stanza VALUES('CB1066','1','Sa krus namatyan’s Manlul’was ko,<br/>Didto gihangyong hugasan ko,<br/>Sala ko gihugasan’s dugo;<br/>Daygong ngalan N’ya!<br/>',NULL,18898,1);
INSERT INTO stanza VALUES('CB1066','chorus','Daygong ngalan N’ya,<br/>Daygong ngalan N’ya;<br/>Sala ko gihugasan’s dugo;<br/>Daygong ngalan N’ya.<br/>',NULL,18899,2);
INSERT INTO stanza VALUES('CB1066','2','Katingad-ang nal’was sa sala,<br/>Nagpuyo’s sulod ko si Jesus;<br/>Gidawat ako Niya sa krus;<br/>Daygong ngalan N’ya.<br/>',NULL,18900,3);
INSERT INTO stanza VALUES('CB1066','3','Tubod nga nagluwas sa sala,<br/>Akong nakasulod nagmaya;<br/>Jesus nagl’was, naghinlo nako;<br/>Daygong ngalan N’ya.<br/>',NULL,18901,4);
INSERT INTO stanza VALUES('CB1066','4','Duol’s tam-is, datong tuboran;<br/>Kalag’s tiilan N’ya itugyan;<br/>Salom karon, magpahingpit ka;<br/>Daygong ngalan N’ya.<br/>',NULL,18902,5);
INSERT INTO stanza VALUES('CB1068','1','Gipangita N’ya akong<br/>Gikapoy na’s sala,<br/>Ug gipas-an’s abaga<br/>Balik sa panon N’ya;<br/>Manulonda sige’g awit,<br/>Sa presensya N’ya sa langit.<br/>',NULL,18903,1);
INSERT INTO stanza VALUES('CB1068','chorus','O gugmang nangita,<br/>O dugong naglukat;<br/>O grasyang nagpauli’s panon,<br/>Nagpauli nako sa panon!<br/>',NULL,18904,2);
INSERT INTO stanza VALUES('CB1068','2','Gibuboang samad ko<br/>Sa lana ug bino;<br/>Nagpasalig S’ya nako,<br/>“Ikaw Akoa na.“<br/>Way tingog nga matam-is pa,<br/>Nga kanako nakalipay!<br/>',NULL,18905,3);
INSERT INTO stanza VALUES('CB1068','3','Gilansang nga kamot N’ya,<br/>Dugo nga giula,<br/>Tunokon nga korona,<br/>Tanan alang nako.<br/>Unsa kahay nakita N’ya<br/>Kanako, nag-antus man S’ya?<br/>',NULL,18906,4);
INSERT INTO stanza VALUES('CB1068','4','Naglingkod’s presensya N’ya,<br/>Gihayagan’s nawong,<br/>Samtang akong gihandom<br/>Ang panalangin N’ya.<br/>Morag mubong eternidad<br/>Alang sa pagdayeg Niya.<br/>',NULL,18907,5);
INSERT INTO stanza VALUES('CB1068','5','Busa’s taknang nanglabay,<br/>Hingpit ang pahulay;<br/>Naghulat’s kabuntagon<br/>Nga labing matahum,<br/>Kon tawgon na kita Niya<br/>Ma-asawa N’yang way mansa.<br/>',NULL,18908,6);
INSERT INTO stanza VALUES('CB1069','1','Sa buhing Tinapay nangaon,<br/>Sa buhing tubod nanginom;<br/>“S’yang moinom,” Jesus nag-ingon,<br/>“Dili na gayud uhawon.”<br/>',NULL,18909,1);
INSERT INTO stanza VALUES('CB1069','chorus','Unsay di na uhawon?<br/>Di na gyud uhawon!<br/>Unsay di na uhawon?<br/>Di na gyud uhawon!<br/>“S’yang moinom,” Jesus nag-ingon,<br/>“Dili na gayud uhawon.”<br/>',NULL,18910,2);
INSERT INTO stanza VALUES('CB1070','1','Naunlod ko sa sala,<br/>Layo sa baybayon,<br/>Nagpadulong sa lalum,<br/>Wala nay paglaum;<br/>Apan Agalon’s dagat<br/>Namati’s tawag ko,<br/>Gikan sa kadagatan<br/>Gil’was ako.<br/>',NULL,18911,1);
INSERT INTO stanza VALUES('CB1070','chorus','Gugma nagl’was!<br/>Gugma nagl’was!<br/>Way laing nitabang,<br/>Gugma nagl’was.<br/>',NULL,18912,2);
INSERT INTO stanza VALUES('CB1070','2','Kasingkasing ihatag,<br/>Alang lamang Niya,<br/>Mabuhi’s ’yang presensya,<br/>Magdayeg gyud Niya.<br/>Gugmang dako’g matuod<br/>Angay nga awitan,<br/>Higugmaon, silbehan<br/>Labaw’s tanan.<br/>',NULL,18913,3);
INSERT INTO stanza VALUES('CB1070','3','Kalag nga na’s kakuyaw,<br/>Kang Jesus motan-aw;<br/>Sa gugma l’wason ka gyud,<br/>Gikan’s mga balud.<br/>S’ya m’oy Agalon’s dagat,<br/>Sugton’s mga balud;<br/>Manluluwas mo Siya—<br/>Luwason ka.<br/>',NULL,18914,4);
INSERT INTO stanza VALUES('CB1073','1','Niay natagong misteryo,<br/>Gikan’s kasaysayan’s tawo!<br/>Paminawa’g dawata ’ni,<br/>Mausa S’ya nimo!<br/>O himaya, hallelujah!<br/>O himaya, hallelujah!<br/>Si Cristo maong misteryo,<br/>Mausa S’ya nimo!<br/>',NULL,18915,1);
INSERT INTO stanza VALUES('CB1074','1','Unsa nga misteryo, Manlul’was<br/>Usa nako!<br/>O kaluwasang kahibudngan<br/>Gihatag’s Dios nako!<br/>Hallelujah! Hallelujah!<br/>Unsang misteryo!<br/>Way makabulag’s langit, yuta<br/>Kang Jesus kanako!<br/>',NULL,18916,1);
INSERT INTO stanza VALUES('CB1079','1','Kon maangkon ko ang kalibutan,<br/>Ug sa Manluluwas mawad-an;<br/>Kinabuhi ko unsa may bili,<br/>Kon sa daklit mangahanaw lang.<br/>Kon maangkon ko ang kalibutan,<br/>Ug sa Manluluwas mawad-an,<br/>Kalipay’s yuta ikatandi ba<br/>Sa kinabuhing puno’g Cristo.<br/>',NULL,18917,1);
INSERT INTO stanza VALUES('CB1079','2','Kon may igo gyung bahandi’g gugma<br/>Ngalang gitahud bisan asa,<br/>Apan way paglaum sa unahan,<br/>Sa akong panaw kadunggoan.<br/>Kon maangkon ko ang kalibutan,<br/>Ug sa Manluluwas mawad-an,<br/>Makahatag ba ang kalibutan,<br/>Dalangpanan ko’s kasakitan?<br/>',NULL,18918,2);
INSERT INTO stanza VALUES('CB1079','3','Kon way Manlul’was—O pagkahaw-ang<br/>Taliwa’s sala’g kasubo dinhi!<br/>Kangitngit’s eternidad kon wa’ S’ya!<br/>Lunlon luha’g kasakitan ra!<br/>Kon mabuhi nga way Manluluwas,<br/>Mamatay unya way pagtoo;<br/>Pagkalisud kini atubangon,<br/>Malaglag ka hangtud sa dayon!<br/>',NULL,18919,3);
INSERT INTO stanza VALUES('CB1079','4','O ang kalipay nga mabatonan,<br/>Diha kang Jesus atong tanan!<br/>Tambal S’ya sa tanang kasakitan,<br/>Sa sala ta magpasaylo man.<br/>Bisan si Jesus ray nabatonan,<br/>Wa nay lain sa kalibutan—<br/>Kang Jesus tanang butang mapalgan,<br/>Siya magtagbo’s kinahanglan.<br/>',NULL,18920,4);
INSERT INTO stanza VALUES('CB1080','1','Way bili tanang paghago,<br/>Way bag-ong butang kanato!<br/>Nangagi di hinumdoman,<br/>Kay kakawangan.<br/>',NULL,18921,1);
INSERT INTO stanza VALUES('CB1080','chorus','Kawang lang! Kawang lang!<br/>Kawang lang! Kawang lang!<br/>Hakop sa hangin,<br/>Tanan kawang lang!<br/>',NULL,18922,2);
INSERT INTO stanza VALUES('CB1080','2','Kinabuhi’s tawo kapait,<br/>Kaalam magda’g kasakit,<br/>Nunot’s kahibawo kasubo,<br/>Kakawangan lang!<br/>',NULL,18923,3);
INSERT INTO stanza VALUES('CB1080','3','Mag-unsa mang bahandi ta,<br/>Kalipay ug pamilya ba,<br/>Mabalaka man gihapon,<br/>Kakawangan lang!<br/>',NULL,18924,4);
INSERT INTO stanza VALUES('CB1080','4','Adlaw’g gabii naghago,<br/>Naa man tuoy maato,<br/>Mawa’ man inigkamatay,<br/>Kakawangan lang!<br/>',NULL,18925,5);
INSERT INTO stanza VALUES('CB1080','5','Dios handuma’s kabatan-on,<br/>Maayong mahadlok ka N’ya,<br/>Diha N’ya matagbaw gyud ka,<br/>Kay di S’ya kawang!<br/>',NULL,18926,6);
INSERT INTO stanza VALUES('CB1080','chorus','Way Cristo, kawang lang!<br/>May Cristo, kaayohan!<br/>Tanan kawang,<br/>S’ya ray di kawang!<br/>',NULL,18927,7);
INSERT INTO stanza VALUES('CB1083','1','Unsa kaduol S’ya’s tanang motawag Niya!<br/>Maglig-on sa sulod ta ang Iyang presensya.<br/>Mangita, mapalgan S’ya, motawag, duol S’ya.<br/>Unsang kalipay’s pagtawag’s mahal nga ngalan N’ya!<br/>',NULL,18928,1);
INSERT INTO stanza VALUES('CB1083','chorus','Jesus! O ang ngalan!<br/>Naghatag ug kinabuhi!<br/>Madaugon, mahim’yaon,<br/>Tinuboy man—O ang ngalan!<br/>Jesus! Makalig-on!<br/>Gino’ng Jesus! Makalipay!<br/>Mahanggap’s ampo, bisan asa ka,<br/>Gin’ong Jesus! O ang ngalan!<br/>',NULL,18929,2);
INSERT INTO stanza VALUES('CB1083','2','Tawga ang ngalan ni Jesus, ug maluwas ka,<br/>Hallelujah, di ka na gyud maulipon pa!<br/>Madawat sa pagtawag ta kopa’s kal’wasan;<br/>Kaluwasan’s daghang butang ang hatag’s ’yang ngalan.<br/>',NULL,18930,3);
INSERT INTO stanza VALUES('CB1083','3','Sa mga Judio ug Gresyanhon, S’ya sama ra,<br/>Sa tanang motawag’s Iyang ngalan dato S’ya.<br/>Kalipayng motawag ug mabuhi, Ginoo;<br/>Unsang kalipay nga makaginhawa’s ngalan Mo.<br/>',NULL,18931,4);
INSERT INTO stanza VALUES('CB1083','4','Magkalipay ta’s Dios sa atong kaluwasan,<br/>Sa tanang panahon magtawag sa ’yang ngalan,<br/>Sa tibuok kinabuhi tawgon ’yang ngalan,<br/>Ikiling N’yang igdulongog, ug grasya hatagan.<br/>',NULL,18932,5);
INSERT INTO stanza VALUES('CB1083','5','Tawgon nato ang ngalan N’ya nga takus daygon;<br/>Kasingkasing magsimba, mapasalamaton.<br/>Kita ang nanawag’s ’yang ngalan’s tanang dapit<br/>Uban sa tanang putli’g kasingkasing mosangpit.<br/>',NULL,18933,6);
INSERT INTO stanza VALUES('CB1085','1','Ngalan—Kahibudngan;<br/>Ngalan—Magtatambag;<br/>Ngalan—Gamhanang Dios,<br/>Ginoo ko.<br/>Bata ug Anak S’ya;<br/>Dayong Amahan pa;<br/>Principe’s kalinaw,<br/>Ginoo ko.<br/>Magbubuhat S’ya,<br/>Jesus Manlul’was,<br/>Espiritu karon.<br/>Simbaha’s esp’ritu,<br/>Higugmaa S’ya,<br/>Ngalan—Kahibudngan,<br/>Ginoo ko.<br/>',NULL,18934,1);
INSERT INTO stanza VALUES('CB1086','1',replace('Gimahal sa katim-os,<br/>Ang ngalan ni Jesus!<br/>Sa yuta o langit man—<br/>Labaw sa tanan.<br/>Paghanggap ning ngalana,<br/>Kamatayon mawala na;<br/>Kay sa ngalan naa ang Persona N’ya!\nSa dila namong tanan—<br/>Isugid Imong ngalan,<br/>Among himayaon ang Dios Amahan.<br/>Kay ang pagdayeg Nimo<br/>Dako nga pagpahimulos;<br/>JESUS, pagtawag man’s among gimahal!<br/>','\n',char(10)),NULL,18935,1);
INSERT INTO stanza VALUES('CB1089','1','Way buling nga Cordero’s Dios,<br/>Gipatay alang namo.<br/>Dugong giula nagtubos,<br/>Naghinlos’ mansa namo.<br/>Cordero Ka nga nagtubos,<br/>Nagkuha’s among sala,<br/>Nagkuha’s among sala!<br/>',NULL,18936,1);
INSERT INTO stanza VALUES('CB1089','2','Bronseng bitin, sud-ongon Ka,<br/>Anak sa Tawong giisa;<br/>Unod’s sala gisul-ob Mo,<br/>Namatay sa dagway’s tawo.<br/>Gitapos Mong kabuhatan,<br/>Satanas, kalibutan,<br/>Satanas, kalibutan!<br/>',NULL,18937,2);
INSERT INTO stanza VALUES('CB1089','3','Lugas sa trigo usa ra,<br/>Kon dili mamatay S’ya;<br/>Kinabuhi di kagawas,<br/>Kon dili S’ya ipugas.<br/>Kinabuhi mahubaran,<br/>Mobunga’g trigong daghan,<br/>Mobunga’g trigong daghan!<br/>',NULL,18938,3);
INSERT INTO stanza VALUES('CB1089','4','Cordero—lukat’s sala ta,<br/>Bitin—nagtapos’ Yawa,<br/>Trigo—nagpasanay Niya,<br/>Nasakot’s daghang trigo.<br/>Hallelujah, Hallelujah!<br/>Unsa kamalangkubon<br/>Sa Iyang kamatayon!<br/>',NULL,18939,4);
INSERT INTO stanza VALUES('CB1095','1','Kon mag-awit’s pagdayeg,<br/>Ang Dios mahimaya;<br/>Panon sa manulonda<br/>Maminaw’s awit ta;<br/>Ang makadungog nato<br/>Maghimaya sa Dios;<br/>Si Satanas mokurog,<br/>Dali gyung mosibog.<br/>',NULL,18940,1);
INSERT INTO stanza VALUES('CB1095','2','Kon baba ta tak-omon,<br/>Yawa mopahiyom;<br/>Busa awaya na s’ya,<br/>Sige gyung abuga.<br/>Sa mga pagdayeg ta,<br/>Ug singgit’s pagdaug—<br/>Kaulaw ray bugti ta,<br/>Mabuang alang’s Dios!<br/>',NULL,18941,2);
INSERT INTO stanza VALUES('CB1095','3','Kalibutan way tabang<br/>Sa pagdayeg’s Manlul’was,<br/>Bisan sa paghimaya,<br/>Pagpasalamat ba;<br/>Mananghid pa ba kita<br/>Sa pagdayeg Niya?<br/>Espiritu hubaran,<br/>Pagdayeg usahan.<br/>',NULL,18942,3);
INSERT INTO stanza VALUES('CB1095','4','Dili kita maghilom!<br/>Maninggit hinoon!<br/>Tingog ta magpadayag<br/>Sa diosnong pagdaug.<br/>Panahon na’s pagdayeg,<br/>Oo, karon dayon!<br/>Kalipay’s kal’wasan mo,<br/>Kaluoy N’ya garbo.<br/>',NULL,18943,4);
INSERT INTO stanza VALUES('CB1096','1','Proklamar’s iglesia lokal,<br/>S’ya Ginoo!<br/>Tanang balaan nagngalan<br/>S’ya Ginoo.<br/>Tanang buhat ’yang nahuman,<br/>Si Satanas gidaug man;<br/>Naglingkod karon sa trono,<br/>S’ya Ginoo!<br/>',NULL,18944,1);
INSERT INTO stanza VALUES('CB1096','2','S’ya ang buhing Espiritu,<br/>S’ya Ginoo!<br/>Nia karon, paminawa:<br/>S’ya Ginoo!<br/>Di na magpaluoyluoy;<br/>Tawga S’ya, mosu’d S’ya nimo,<br/>Magmahim’yaong sentro mo—<br/>S’ya Ginoo!<br/>',NULL,18945,2);
INSERT INTO stanza VALUES('CB1096','3','Kambyohong kinabuhi mo,<br/>Sa Ginoo!<br/>Hatagan ka’s ’yang kadato,<br/>S’ya Ginoo!<br/>Tagbawon ka gyud sa dayon,<br/>Sangkapan sa buntag, hapon,<br/>Ug sa Dios ikaw usahon,<br/>S’ya Ginoo!<br/>',NULL,18946,3);
INSERT INTO stanza VALUES('CB1096','4','Sa kaluoy gidawat N’ya,<br/>S’ya Ginoo!<br/>Kanato di gyud mobiya,<br/>S’ya Ginoo!<br/>Kahupnganan’s ’yang persona<br/>Sa Lawas N’ya makita ta,<br/>Kaaway nikalagiw na,<br/>S’ya Ginoo!<br/>',NULL,18947,4);
INSERT INTO stanza VALUES('CB1097','1','Ginoo, pagkamaayo’s<br/>Ngalan’s tibu’k yuta!<br/>Sa ’yang bili pasangyawa<br/>Tanang banay’g dila.<br/>Sa baba sa mga bata<br/>Pagdayeg gipalig-on,<br/>Aron kaaway mapahilom<br/>Ug matapos dayon.<br/>',NULL,18948,1);
INSERT INTO stanza VALUES('CB1097','2','Sa pagsud-ong’s uniberso,<br/>Buhat sa kamot Mo—<br/>Adlaw, Bulan, kabit’onan,<br/>Giplano’s kaalam;<br/>Unsa ang tawo nga gitagad<br/>Gihunahuna Mo?<br/>Giduaw ang anak sa tawo’s<br/>Pamatigayon Mo.<br/>',NULL,18949,2);
INSERT INTO stanza VALUES('CB1097','3','Jesus, Ikawng nagpakatawo<br/>Aron mausa namo,<br/>Ang unod gisul-ob Nimo,<br/>Nagpakaubos Ka.<br/>Karon may purong’s himaya,<br/>Hingpit nga Hari na.<br/>Pin’agi’s Lawas nagbuot,<br/>Tanan gipasakop.<br/>',NULL,18950,3);
INSERT INTO stanza VALUES('CB1097','4','Pagkatawo’g pagkabanhaw sab,<br/>Ug pagkalabaw Mo,<br/>Pagkaginoo, Hari, Ulo,<br/>Ug Lawas makita.<br/>Ni’ning lakang’s diosnong buhat,<br/>Naglig-on Ka’s pagdayeg.<br/>Mag-awas ang kasingkasing<br/>Pagsimba’g pagdayeg.<br/>',NULL,18951,4);
INSERT INTO stanza VALUES('CB1097','5','Moabot di na madugay,<br/>Ang bulahang adlaw!<br/>Apan sa iglesia lokal<br/>Unang makatilaw.<br/>Ginoo, pagkamaayo’s<br/>Ngalan’s tibu’k yuta!<br/>Sa ’yang bili pasaysaya<br/>Tanang banay’g dila.<br/>',NULL,18952,5);
INSERT INTO stanza VALUES('CB1103','1','Unsa S’ya: S’yang Amahan.<br/>Amahang way katapusan.<br/>Panganay S’ya’s kabuhatan,<br/>Ang nabuhi sa sulod ko.<br/>Amahang kahibudngan!<br/>',NULL,18953,1);
INSERT INTO stanza VALUES('CB1103','2','Unsa S’ya: S’ya ang suba.<br/>Kusganong nag-agayng suba.<br/>Gitubigan N’ya’s kamingawan.<br/>Tagoanan S’ya; ang among tawo.<br/>S’yang suba! Kahibudngan!<br/>',NULL,18954,2);
INSERT INTO stanza VALUES('CB1103','3','Unsa S’ya: S’yang punoan.<br/>S’yang sanga, gamut ni Isai.<br/>Kahoy’s kinabuhi: katungod ta<br/>Pagkaon N’ya ug mabuhi.<br/>S’yang punoan! Maayo!<br/>',NULL,18955,3);
INSERT INTO stanza VALUES('CB1103','4','Unsa S’ya: Magbalantay.<br/>Cordero’s Dios, laking kanding.<br/>Mopahuway, kaon’s sibsibanan.<br/>Isablig dugo, kan-on S’ya.<br/>Magbalantay! Maayo!<br/>',NULL,18956,4);
INSERT INTO stanza VALUES('CB1103','5','Unsa S’ya: Espiritu.<br/>Malangkubong Espiritu.<br/>S’yang tanan nato, tanan’s tanan,<br/>Sa pagtawag ta, buhion N’ya.<br/>Espiritu! Maayo!<br/>',NULL,18957,5);
INSERT INTO stanza VALUES('CB1103','6','Unsa S’ya: S’yang Persona.<br/>Matuod, buhing Persona.<br/>Nabuhi S’ya’s sulod ta karon,<br/>Personang mahimayaon.<br/>S’yang Persona! Maayo!<br/>',NULL,18958,6);
INSERT INTO stanza VALUES('CB1103','7','Unsa S’ya: S’ya ang Lawas;<br/>S’ya sa Dios ang kahupnganan;<br/>S’yang sentro sa plano’s Amahan,<br/>Cristo’g iglesia, bag-ong tawo.<br/>Kahibudngan, Kahibudngan!<br/>',NULL,18959,7);
INSERT INTO stanza VALUES('CB1103','chorus','Kahibudngan, kahibudngan!<br/>Kahibudngan, kahibudngan!<br/>',NULL,18960,8);
INSERT INTO stanza VALUES('CB1104','1','Halad’s pakigdait Ka<br/>Tapin-an Ka’s kamot.<br/>Praktikal ug tinuod<br/>Nausa mi Nimo.<br/>Sa gitigumang tolda<br/>Among ihalad Ka;<br/>Uban sa Dios nagkaon<br/>Ikaw ang kalan-on.<br/>',NULL,18961,1);
INSERT INTO stanza VALUES('CB1104','chorus','Pakigdait Ka, Ginoo!<br/>Gipahiuli Mo!<br/>Pakigdait Ka’s Dios ug tawo<br/>Daygon Ikaw namo.<br/>',NULL,18962,2);
INSERT INTO stanza VALUES('CB1104','2','Unsang kalinawng hatag,<br/>Igkakita’s dugo;<br/>Dugo’s halad nagdala’s<br/>Pakigdait sa Dios.<br/>Isug nga ipahayag—<br/>Kaaway, paminaw—<br/>“Pakigdait’s ’yang dugo!“<br/>M’oy pagdaug namo.<br/>',NULL,18963,3);
INSERT INTO stanza VALUES('CB1104','3','Basi’s halad-sinunog,<br/>Ug halad-kalan-on,<br/>Mahalad namo’s Jesus<br/>Among kadaitan.<br/>Labi kaming magkaon<br/>Sa ’yang pagka-tawo,<br/>Labi S’yang mapa’muslan,<br/>Kaon nga usahan.<br/>',NULL,18964,4);
INSERT INTO stanza VALUES('CB1104','chorus','(Sa v. 3 lang kini nga chorus)<br/>Unsa nga panag-ambitay,<br/>Giusahan’s Dios, tawo<br/>Unsang kalipay, kombira,<br/>Uban’s ’yang katawhan.<br/>',NULL,18965,5);
INSERT INTO stanza VALUES('CB1104','4','Mapa’muslan N’yang pahat—<br/>Mahumot nga halad—<br/>Tanang sacerdote gyud<br/>Magkaon’s tinabyog.<br/>Sacerdoteng naghalad,<br/>Ang labing maayo<br/>Iya: usang abaga<br/>Ug usang tinapay.<br/>',NULL,18966,6);
INSERT INTO stanza VALUES('CB1104','5','Ang tinabyog nga dughan—<br/>Gugmang alang’s tanan;<br/>Gipalingkod uban N’ya,<br/>Sa pagkabanhaw N’ya!<br/>Unsang kusog pagkaon’s<br/>Abaga’s Nikayab.<br/>Matil-ogan’s tinapay,<br/>Maggawi sama N’ya.<br/>',NULL,18967,7);
INSERT INTO stanza VALUES('CB1104','6','Magkaon’s kadato N’ya,<br/>Uban’s nahinloan;<br/>O tinu’d ning komunyon,<br/>Bugtong tiniguman.<br/>Dad-ong pasalamat ta,<br/>Bisan ang panumpa—<br/>Alang’s pahiuli N’ya<br/>Kay alang nato S’ya.<br/>',NULL,18968,8);
INSERT INTO stanza VALUES('CB1105','1','Ang talad’s atubangan ta,<br/>May tinapay ug kopa:<br/>Manlul’was naghulat nato,<br/>Nag-agda sa pagkaon.<br/>“Sa talad umari kamo,<br/>Magsalo ta’s pagkaon“;<br/>Talad kanato giandam,<br/>Uban N’ya kombirahan.<br/>',NULL,18969,1);
INSERT INTO stanza VALUES('CB1105','2','Nagkaon uban’s Manlul’was,<br/>Nagsalo-salo kita;<br/>Hallelujah, hallelujah!<br/>Di matapos nga pista!<br/>Kaon-inom mi Kanimo<br/>Busog gyud mi kaayo.<br/>Nakatilaw’s kombira Mo,<br/>Ambitan’s Asawa Mo.<br/>',NULL,18970,2);
INSERT INTO stanza VALUES('CB1106','1','Nagtigum mi alang’s Imong panihapon:<br/>Nagpasundayag’s among pagkausa.<br/>May presensya Niya, ipailang pag’usa,<br/>Sa pagkaon-inom, nabulahan kita.<br/>',NULL,18971,1);
INSERT INTO stanza VALUES('CB1106','2','Nagkaon’s tinapayng lawas N’yang gipikas<br/>Nausang Lawas karon napa’muslan;<br/>Tinapay sa talad—usa gyud nga Lawas,<br/>Giusa’s Ginoo, atong pamatud-an.<br/>',NULL,18972,2);
INSERT INTO stanza VALUES('CB1106','3','Nag-inom sab mi’s kopa’s kabulahanan,<br/>Panag-ambitay’s iglesia’s dugo N’ya;<br/>Pagtoo, gitubos; dawatong balaan,<br/>Kadtong gitubos nga nakaduol sa Dios.<br/>',NULL,18973,3);
INSERT INTO stanza VALUES('CB1106','4','O unsay masulti kondi’ “Hallelujah!“<br/>Sa kamatuorang gihatag Niya.<br/>Dugo Mo gigamit, Lawas gipa’muslan;<br/>Maangkon Mong mahimayaong iglesia.<br/>',NULL,18974,4);
INSERT INTO stanza VALUES('CB1107','1','Nagtigum mi, Ginoo, nga Lawas Mo:<br/>Bisan daghan, apan usa ra mi.<br/>Giusahan ang Imong kinabuhi.<br/>Busa usa ra ming tanang bahin.<br/>',NULL,18975,1);
INSERT INTO stanza VALUES('CB1107','chorus','May usang Lawas sa uniberso,<br/>Dinhi gipadayag nato;<br/>Sa lokal nagbarug’s pagkausa,<br/>Usang iglesia makita.<br/>',NULL,18976,2);
INSERT INTO stanza VALUES('CB1107','2','Usang tinapay simbolo’s lawas Mo;<br/>Gipikas aron among ambitan;<br/>Gikaong tinapay ug nagpahayag<br/>Nausa gyud mi’s tanang balaan.<br/>',NULL,18977,3);
INSERT INTO stanza VALUES('CB1107','3','Usang tinapay, ug usa nga kopa,<br/>Nagpakita nga usa ra gyud ta;<br/>Gitubos N’ya, gihimo nga Lawas N’ya:<br/>“Amen” ra gayud ang masulti ta.<br/>',NULL,18978,4);
INSERT INTO stanza VALUES('CB1107','4','Usang nagbarug, dili gyud mabulag,<br/>Pagkausa mao si Cristo ra;<br/>Usang mag-ambit’s tinapay ug kopa,<br/>Dayag makita ang pagkausa.<br/>',NULL,18979,5);
INSERT INTO stanza VALUES('CB1107','5','Unsang kalipay dunay pagkausa!<br/>Mabati Ginoo, natagbaw Ka;<br/>Naambitan sab namong katagbawan—<br/>Pagtilaw’s Bana uban’s Asawa.<br/>',NULL,18980,6);
INSERT INTO stanza VALUES('CB1108','1','Kan-ang tinapay, katawhan’s Dios:<br/>Daygon S’ya kita gihiusa;<br/>Karon usa kitang mangaon,<br/>Iglesiang gihimong Iyaha.<br/>',NULL,18981,1);
INSERT INTO stanza VALUES('CB1108','chorus','Kan-ang tinapay, imnang kopa!<br/>Usa ta Niya’s dayon.<br/>Barug sa sukaranang lokal,<br/>Usang magkaon-inom!<br/>',NULL,18982,2);
INSERT INTO stanza VALUES('CB1108','2','Katawhan’s Dios, inom sa kopa:<br/>Iglesia kitang gipalit N’ya;<br/>Gilukat aron mahiusa,<br/>Kini dugay nang pangandoy N’ya.<br/>',NULL,18983,3);
INSERT INTO stanza VALUES('CB1108','3','Barugi katawhan’s Ginoo,<br/>Dili kita tinagsang trigo,<br/>Usa ta, nasakot, nausa,<br/>Daw tinapay sa matag lokal.<br/>',NULL,18984,4);
INSERT INTO stanza VALUES('CB1108','4','Usa kitang iya’s Ginoo,<br/>Ipahayag usa gyud kita!<br/>Di’s pulong, kondi’s kinabuhi,<br/>Pamatud-an kini buhat N’ya!<br/>',NULL,18985,5);
INSERT INTO stanza VALUES('CB1108','5','Kan-ang tinapay, katawhan’s Dios:<br/>Daygon S’ya kita gihiusa,<br/>Karon usa kitang mangaon,<br/>Iglesiang gihimong Iyaha.<br/>',NULL,18986,6);
INSERT INTO stanza VALUES('CB1110','1','O Ginoo, sa talad Mo nanambong,<br/>Nakita ang tinapay ug kopa;<br/>Daygon Ka kay kalan-ong mapa’muslan<br/>Sa mga tawo sa daghang paagi.<br/>',NULL,18987,1);
INSERT INTO stanza VALUES('CB1110','chorus','Unang Chorus:<br/>Busa mag-awit mi’s pagdayeg Nimo,<br/>Pagkagamay gayud Nimo!<br/>Ug kan-on Ka hangtud’s eternidad;<br/>Pagkagamay gayud Nimo!<br/>',NULL,18988,2);
INSERT INTO stanza VALUES('CB1110','2','Sa pag-anhi Nimo sa kalibutan,<br/>Kinabuhi Mo untay isangkap;<br/>Apan ang tawo nagsalig’s pagtulon-an,<br/>Busa way kadatong napa’muslan.<br/>',NULL,18989,3);
INSERT INTO stanza VALUES('CB1110','chorus','Ikaduhang Chorus:<br/>Ang kinahanglan pagkaon ra N’ya;<br/>Kahibulongan gyud Siya!<br/>Ug sa pagkaon maulian ta,<br/>Sa sulod ta magtubo S’ya.<br/>',NULL,18990,4);
INSERT INTO stanza VALUES('CB1110','3','Wala Ka moanhi aron maghari<br/>Nga magdumala namo sa gawas.<br/>Apan kalan-on Ikaw nga nianhi,<br/>Magtagbaw aron mabuhi kami.<br/>(Unang chorus)<br/>',NULL,18991,5);
INSERT INTO stanza VALUES('CB1110','4','Sa kadako Mo ug himaya, daygon,<br/>Sa gahum Mo ug pagkahalangdon;<br/>Apan labaw kaming magpasalamat<br/>Nigamay Ka nga among makaon.<br/>(Unang chorus)<br/>',NULL,18992,6);
INSERT INTO stanza VALUES('CB1113','1','Tulo-usang Dios nipuyo na’s sulod,<br/>Ang kahibudngang Espiritu.<br/>Nasagol, nausa ta’s Espiritu<br/>Nga taghatag ug kinabuhi.<br/>',NULL,18993,1);
INSERT INTO stanza VALUES('CB1113','chorus','O S’yang kahibudngang Espiritu,<br/>Nga nagpuyo sa sulod nato!<br/>Dios naa’s Anak, Anak Espiritu—<br/>S’yang kahibudngang Espiritu!<br/>',NULL,18994,2);
INSERT INTO stanza VALUES('CB1113','2','“Abba Amahan” m’oy tuaw sa sulod,<br/>Sa kahibudngang Espiritu.<br/>Espiritu’s Anak ang nituaw N’ya,<br/>Ang Taghatag ug kinabuhi.<br/>',NULL,18995,3);
INSERT INTO stanza VALUES('CB1113','3','Ginoo karon nabuhi’s sulod ta,<br/>Ang kahibudngang Espiritu.<br/>Nausab S’ya’s dagway, napa’muslan ta,<br/>Ang Taghatag ug kinabuhi.<br/>',NULL,18996,4);
INSERT INTO stanza VALUES('CB1113','4','Nia nang Espiritu’s realidad,<br/>Ang kahibudngang Espiritu.<br/>Tin-aw nang butang ni Cristo kanato,<br/>Kay S’yang Espiritu sa sulod.<br/>',NULL,18997,5);
INSERT INTO stanza VALUES('CB1113','5','Dasigon ta kining gasa’s sulod ta,<br/>Ang kahibudngang Espiritu.<br/>Kon motawag ta, “O Ginoong Jesus“<br/>Magmakusganong espiritu!<br/>',NULL,18998,6);
INSERT INTO stanza VALUES('CB1117','1','Daygon Ka, O Dios,<br/>Sa Espiritu Mo<br/>Nga nipuyo sa sulod,<br/>Kinabuhi ko.<br/>Hallelujah’s Espiritu!<br/>Hallelujah’s sulod!<br/>Hallelujah, sa kadato,<br/>Di mahurot gyud!<br/>',NULL,18999,1);
INSERT INTO stanza VALUES('CB1117','2','Sa espiritu<br/>Awitan ta Siya,<br/>Naghatag’s kinabuhi,<br/>Nato nausa.<br/>Hallelujah, kini’s Jesus,<br/>Ug dunay dugang pa,<br/>Hallelujah, Espiritu,<br/>Kinabuhi ta.<br/>',NULL,19000,2);
INSERT INTO stanza VALUES('CB1117','3','Gianak pag-usab<br/>Diha’s espiritu,<br/>Gitransporma aron<br/>Kang Cristo masama.<br/>Hallelujah! Gibuhi N’ya,<br/>Ug gitransporma pa.<br/>Hallelujah! Di madugay<br/>Masama na N’ya!<br/>',NULL,19001,3);
INSERT INTO stanza VALUES('CB1117','4','Masama gayud<br/>Kon mokaon kita,<br/>Sa kinabuhi N’yang<br/>Tagbo’s kinahanglan.<br/>Hallelujah’s kaluwasan!<br/>Hallelujah’s ganti!<br/>Hallelujah! Igo gyud S’ya’s<br/>Tanang adlaw ta.<br/>',NULL,19002,4);
INSERT INTO stanza VALUES('CB1119','1','Sa Pulong sa Dios nakit-an,<br/>Kaayo ni’ni nako;<br/>Pagtudlo’s tawo di kin’hanglan,<br/>Dihog nagpuyo nako!<br/>',NULL,19003,1);
INSERT INTO stanza VALUES('CB1119','chorus','Oo, naglihok’s espiritu ko!<br/>Oo, naa koy dihog!<br/>Dios nag-agay nako!<br/>O, nakita ko!<br/>Gipadayag N’ya—<br/>Gamiton ko gyud kini!<br/>Nagpuyo nakong dihog!<br/>',NULL,19004,2);
INSERT INTO stanza VALUES('CB1119','2','Makapasinating Cristo,<br/>Dios madawat sa Pulong;<br/>Espiritung usa nako,<br/>Saad Niya tumanon.<br/>',NULL,19005,3);
INSERT INTO stanza VALUES('CB1119','3','Basi sa dugong naghinlo,<br/>Walay makaulang gyud;<br/>Cristo nga dihog naglihok!<br/>Naghinlo’s akong sulod.<br/>',NULL,19006,4);
INSERT INTO stanza VALUES('CB1119','4','Dios kang Cristo Espiritu,<br/>Kinabuhing nisulod!<br/>“Balaan” nagdihog nako,<br/>Hangtud masama kami.<br/>',NULL,19007,5);
INSERT INTO stanza VALUES('CB1119','5','Dios Espiritu matandog;<br/>S’yang agay’s esp’ritu ko.<br/>Mas lalum S’ya, lapad, dato—<br/>Dios nga nakaila ko!<br/>',NULL,19008,6);
INSERT INTO stanza VALUES('CB1119','6','Mamati ning maong dihog,<br/>Magpabilin Kaniya,<br/>Nagtudlo, nidangat nako,<br/>Bug-os kong batonan N’ya.<br/>',NULL,19009,7);
INSERT INTO stanza VALUES('CB1122','1','“Pitong Espiritu’s” Dios—<br/>Nausab nang panahon<br/>Gikan’s panahon’s Anak<br/>Ngadto’s Espiritu na.<br/>',NULL,19010,1);
INSERT INTO stanza VALUES('CB1122','chorus','O pitong Espiritu,<br/>Pahiuli humana!<br/>Sunoga, susiha mi,<br/>Alang ming tanan Nimo.<br/>Susiha na,<br/>Alang ming tanan Nimo!<br/>',NULL,19011,2);
INSERT INTO stanza VALUES('CB1122','2','Pito ka pilo karon<br/>Tungod’s pagkapatay ta,<br/>Aron kita buhion,<br/>Mosunog, mosusi S’ya.<br/>',NULL,19012,3);
INSERT INTO stanza VALUES('CB1122','3','Esp’ritu gipakusgan<br/>Sa pito ka pilo gyud,<br/>Aron iglesia karon<br/>Iyang masangkapan gyud.<br/>',NULL,19013,4);
INSERT INTO stanza VALUES('CB1122','4','Pitong Esp’ritu karon<br/>Pitong suga’s kalayo,<br/>Di motudlo—mosunog,<br/>Magtagbo’s tinguha’s Dios!<br/>',NULL,19014,5);
INSERT INTO stanza VALUES('CB1122','5','Pitong Esp’ritu karon,<br/>Nagsusing mga mata.<br/>Magbutyag sa iglesia,<br/>Tanan putlion Niya.<br/>',NULL,19015,6);
INSERT INTO stanza VALUES('CB1122','6','Pitong Esp’ritu karon<br/>Alang’s mga iglesia;<br/>Pa’muslan unta kini’s<br/>Tanang naa’s iglesia.<br/>',NULL,19016,7);
INSERT INTO stanza VALUES('CB1123','1','Gianak sa Espiritu—<br/>Tinubdan kining Jesus;<br/>Puno, iya’s Espiritu,<br/>M’oy Iyang pagkamao.<br/>Diha, uban’s Espiritu,<br/>Karon S’ya Espiritu;<br/>Diha’s espiritu kita<br/>Sama usab Kaniya.<br/>',NULL,19017,1);
INSERT INTO stanza VALUES('CB1123','2','Pagbautismo’s Espiritu,<br/>Nahumol’s Espiritu;<br/>Iglesia gianak Niya,<br/>Relihiyon gibungkag N’ya.<br/>Diha ra sa Espiritu,<br/>Ang gikinahanglan ta.<br/>Manaa gyud’s Espiritu,<br/>Di’s pagtulon-a’g credo.<br/>',NULL,19018,2);
INSERT INTO stanza VALUES('CB1123','3','Pag-ambitay’s Espiritu,<br/>Ambitayng giusahan;<br/>Magtagad lang’s Espiritu<br/>Tanang kaigsoonan.<br/>Espiritu namulong sa<br/>Iglesia, maminaw ta;<br/>Pitong Espiritu pahat,<br/>Alang’s mga iglesia.<br/>',NULL,19019,3);
INSERT INTO stanza VALUES('CB1123','4','“Ari, inom’s buhing tubig,“<br/>Ang awhag kanato sa<br/>Espiritu ug Asawa<br/>Nga bug-os gyung nausa.<br/>Kin’hanglan marealidad<br/>Paggawi’s Espiritu;<br/>Espiritu ra’s iglesia,<br/>Pahiuli’s Ginoo.<br/>',NULL,19020,4);
INSERT INTO stanza VALUES('CB1127','1','Gil’was na’s kalibutan,<br/>Dili na gyud ko mobalik.<br/>Gil’was na’s kalibutan,<br/>Dili na gyud ko mobalik.<br/>',NULL,19021,1);
INSERT INTO stanza VALUES('CB1127','chorus','Dili, dili na,<br/>Dili na gyud ko mobalik;<br/>Dili, dili na,<br/>Dili na gyud ko mobalik.<br/>',NULL,19022,2);
INSERT INTO stanza VALUES('CB1127','2','Nigula’s Babilonia;<br/>Dili na gyud ko mobalik.<br/>Nigula’s Babilonia,<br/>Dili na gyud ko mobalik.<br/>',NULL,19023,3);
INSERT INTO stanza VALUES('CB1127','3','Iglesia lokal napalgan,<br/>Di na gyud ko’s kalibutan.<br/>Iglesia lokal napalgan,<br/>Di na gyud ko’s kalibutan.<br/>',NULL,19024,4);
INSERT INTO stanza VALUES('CB1127','4','Natandog ko si Cristo,<br/>Di na gyud ko’s kalibutan.<br/>Natandog ko si Cristo,<br/>Di na gyud ko’s kalibutan.<br/>',NULL,19025,5);
INSERT INTO stanza VALUES('CB1127','5','Si Cristo akong tanan,<br/>Di na gyud ko’s kalibutan.<br/>Si Cristo akong tanan,<br/>Di na gyud ko’s kalibutan.<br/>',NULL,19026,6);
INSERT INTO stanza VALUES('CB1127','6','Nauli’s panimalay,<br/>Di na gyud ko’s kalibutan.<br/>Nauli’s panimalay,<br/>Di na gyud ko’s kalibutan.<br/>',NULL,19027,7);
INSERT INTO stanza VALUES('CB1127','7','Alang na’s pahiuli,<br/>Di na gyud ko’s kalibutan.<br/>Alang na’s pahiuli,<br/>Di na gyud ko’s kalibutan.<br/>',NULL,19028,8);
INSERT INTO stanza VALUES('CB1130','1','Daygon, Dios nga kal’wasan ta,<br/>Cristo nabuhi’s sulod;<br/>Sa diosnong kinabuhi N’ya<br/>Gil’was ta ug di’s sugo;<br/>Sa nabuhat na ang tanan,<br/>Kinabuhi N’yang gamhanan,<br/>Mag-usab natong tanan.<br/>',NULL,19029,1);
INSERT INTO stanza VALUES('CB1130','2','Magluwas nato’s hingpit gyud<br/>Gahum N’ya’s kinabuhi;<br/>Tuhopan N’ya’s Kaugalingon,<br/>Matag takna luwason.<br/>Pagsulod N’ya m’oy pagluwas,<br/>Gil’was N’ya di lang sa sala,<br/>Kondi’ ngadto’s himaya!<br/>',NULL,19030,2);
INSERT INTO stanza VALUES('CB1130','3','Gihimo S’yang Sacerdote,<br/>Maghatag’s kinabuhi;<br/>Kinabuhiy kinaiya,<br/>Makal’was kaugalingon:<br/>Di madugtang kinabuhi,<br/>Hingpit gyud nga makaluwas:<br/>Daygong Dios, makahimo!<br/>',NULL,19031,3);
INSERT INTO stanza VALUES('CB1130','4','Kinabuhi N’ya takus gyud<br/>Pagda’ nato’s himaya;<br/>Kon wa pa masulayi S’ya,<br/>Di unta maluwas ta.<br/>Gisulayan sukad natawo,<br/>Hangtud gilansang’s krus didto,<br/>Agig kamatay, Hades.<br/>',NULL,19032,4);
INSERT INTO stanza VALUES('CB1130','5','Mol’was gyud nagpasalig S’ya,<br/>Kinabuhi nagbuhat<br/>Gibuhat N’yang tanan nato<br/>Aron hingpiton kita.<br/>Pakyas mang kinabuhi ta,<br/>Ang Iya nasulayan na,<br/>Hingpit gyung makaluwas!<br/>',NULL,19033,5);
INSERT INTO stanza VALUES('CB1130','6','Buhi S’ya ug alang nato<br/>Sa dayon nangamuyo;<br/>Buhaton N’ya sa panahon,<br/>’Yang pagkasacerdote.<br/>Dili mausab ug buhi,<br/>Labaw pa sa kalangitan,<br/>M’oy atong gikin’hanglan.<br/>',NULL,19034,6);
INSERT INTO stanza VALUES('CB1130','7','Manuol’s Dios agi Niya,<br/>Ay’g balik’s pagkalaglag;<br/>Ari, baton’s kinabuhi,<br/>Magamit gyud ka ka’yo;<br/>Ari, baton’s kinabuhi,<br/>Himoon tang katawhan N’ya,<br/>Kamatayon wad-on na.<br/>',NULL,19035,7);
INSERT INTO stanza VALUES('CB1131','1','Sa bilanggoang way paglaum,<br/>Motoo unta, way igtoo;<br/>Gipatin-aw’s Dios, nitungha’s Jesus,<br/>Gituhopan mi’s Dios!<br/>Gituhopan mi’s Dios!<br/>',NULL,19036,1);
INSERT INTO stanza VALUES('CB1131','chorus','Ang dugong nagpasig-uli,<br/>Pagtubos nagbalik nato’s Dios!<br/>Wa nay paghukom, pagpamatarung!<br/>May pakigdait’s Dios!<br/>May pakigdait’s Dios!<br/>',NULL,19037,2);
INSERT INTO stanza VALUES('CB1131','2','Natawo kang Adam, kamatyonon,<br/>May sakit tang way makaayo;<br/>Anak gipada’, Adam gitapos;<br/>Namatay si Adam,<br/>Nahigawas na ta!<br/>',NULL,19038,3);
INSERT INTO stanza VALUES('CB1131','3','Nagkalipay, nagbarug’s grasya,<br/>Sala napapas, Hallelujah!<br/>Sa sulod, Dios niagay, nagtubo,<br/>Sa kinabuhi N’ya<br/>Nangaluwas kita!<br/>',NULL,19039,4);
INSERT INTO stanza VALUES('CB1132','1','Tudloi’s pag-ampo,<br/>Di sama sa mga nasud,<br/>Usba’s ginawian;<br/>Adlaw-adlaw patawga Kanimo—<br/>Motubo Ka’s sulod.<br/>',NULL,19040,1);
INSERT INTO stanza VALUES('CB1132','2','Binhi Kang gipugas,<br/>Sa amo gyung kasingkasing,<br/>Nakasugod Ka na;<br/>Adlaw-adlaw patuboa pa gyud<br/>Ang kinabuhi Mo.<br/>',NULL,19041,2);
INSERT INTO stanza VALUES('CB1132','3','Kami pahumoka,<br/>Diin mi gikan, sayud Ka;<br/>I’gtawag’s ngalan Mo,<br/>Ay’g binli’s yutang bagtok o bato—<br/>Ikaw makatubo.<br/>',NULL,19042,3);
INSERT INTO stanza VALUES('CB1132','4','Maghayag Ka namo<br/>Aron makatuman Nimo;<br/>Apan may mensahe,<br/>Molampos ang Imong kinabuhi—<br/>Ikaw makatubo.<br/>',NULL,19043,4);
INSERT INTO stanza VALUES('CB1132','5','Himoa ming kabus;<br/>Kuhai mi’s nahibal-an;<br/>Bukas mi’s agay Mo,<br/>Sa kinabuhi makapatubo—<br/>Motubo Ka’s sulod.<br/>',NULL,19044,5);
INSERT INTO stanza VALUES('CB1132','6','Putlia, Ginoo;<br/>Di mi makontento kon di<br/>Ka mopuno namo,<br/>Bag-oha tibuok namong kalag—<br/>Motubo Ka’s sulod.<br/>',NULL,19045,6);
INSERT INTO stanza VALUES('CB1132','7','Kami padumdoma,<br/>Adlaw-adlaw dawaton Ka;<br/>Makatubong binhi,<br/>Magpadangat’s gingharian dinhi,<br/>Motubo Ka’s sulod.<br/>',NULL,19046,7);
INSERT INTO stanza VALUES('CB1132','8','Amen!—Kinabuhi,<br/>Motubo, way di mahimo,<br/>Magbag-o’s sulod ko.<br/>Mahimo gyud kini tungod Nimo,<br/>Motubo Ka’s sulod,<br/>O Ginoong Jesus!<br/>',NULL,19047,8);
INSERT INTO stanza VALUES('CB1134','1','Lig-ona akong espiritu,<br/>Giampo ko, Ginoo;<br/>O lig-ona na sa gahum Mo<br/>Makakaylap Ka’s sulod.<br/>',NULL,19048,1);
INSERT INTO stanza VALUES('CB1134','chorus','Makakaylap, O Ginoo,<br/>Ikaw sa kasingkasing ko;<br/>Makabalay, makabuot<br/>Sa akong tanan, Ginoo.<br/>',NULL,19049,2);
INSERT INTO stanza VALUES('CB1134','2','Mokaylap Ka’s kasingkasing ko,<br/>Giampo ko, Ginoo;<br/>Mokaylap gikan’s espiritu,<br/>Kaylap na karon dayon.<br/>',NULL,19050,3);
INSERT INTO stanza VALUES('CB1134','3','Magbalay Ka’s kasingkasing ko,<br/>Giampo ko, Ginoo;<br/>Mapuno mi’s kahupnganan Mo,<br/>Ug magbalay Ka karon.<br/>',NULL,19051,4);
INSERT INTO stanza VALUES('CB1134','4','Kan’ya nga arang makahimo<br/>Labaw’s gihunahuna,<br/>Kasingkasing namo binuksan,<br/>Andam nga pasudlon Ka.<br/>',NULL,19052,5);
INSERT INTO stanza VALUES('CB1137','1','Kanunay S’yang igkita’s manulonda,<br/>Wa makaila’s gugma N’ya;<br/>Kitang nakaila’s dakong gugma N’ya,<br/>Wa hinoon makakita.<br/>Dili madugay igkita nato S’ya,<br/>Makaambit’s himaya N’ya;<br/>Si Maria nga nakakita’s luha N’ya,<br/>Nasayud’s kasakitan N’ya,<br/>Nasayud’s kasakitan N’ya.<br/>',NULL,19053,1);
INSERT INTO stanza VALUES('CB1137','2','Hapit nang masayran nato’s bug-os S’ya,<br/>Pag-ilang way makasama;<br/>Apan hikap N’yang nag-ayo’s kasubo,<br/>Dili na mabati didto.<br/>Bisan unya sa pagdayeg mapuno,<br/>Wa nay mainitong ampo;<br/>Wa nay paglipay agig kasakitan,<br/>Way pagsalig’s kalisdanan,<br/>Way pagsalig’s kalisdanan.<br/>',NULL,19054,2);
INSERT INTO stanza VALUES('CB1137','3','Bisan unya didto purongpurongan,<br/>Wala na tay krus nga sugton;<br/>Tam-is pakig-ambitay’s ’yang pag-antus,<br/>Maambitan lamang karon.<br/>Pagsulod’s pahulay, kakapoy wa na,<br/>Walay mga pagsulay sab,<br/>Di na maglisud, ni magsubo pa ba,<br/>O mag-antus alang Niya,<br/>O mag-antus alang Niya.<br/>',NULL,19055,3);
INSERT INTO stanza VALUES('CB1137','4','Kanihit’s higayon nga mag-antus ta<br/>O maulawan tungod N’ya;<br/>Daling molabay kanang higayona<br/>Nga kaabag S’ya’s problema.<br/>Tanang di pagsinabtanay’g kamingaw,<br/>Mga pagtamay mahanaw;<br/>Gimahal ko kining kabulahanan,<br/>Kay tungod ni’ni, Ginoo,<br/>Tam-is kong mausa Nimo.<br/>',NULL,19056,4);
INSERT INTO stanza VALUES('CB1137','5','Gipangandoy kong sayo Kang makita,<br/>Pagkaanindot gyud unta.<br/>Apan di buot molikay’s pagsulay<br/>Mawad-an’s atong sandurot.<br/>Kaloy-i ug pun-a’s dakong gugma Mo,<br/>Magkinabuhi ra Nimo,<br/>Aron di magmahay nga gipalabay,<br/>Ang higayon nako karon,<br/>Ang higayon nako karon.<br/>',NULL,19057,5);
INSERT INTO stanza VALUES('CB1141','1','Mag-awit’s Ginoo’s espiritu,<br/>Mag-awit’s Ginoo sa sulod,<br/>Mag-awit hallelujah ni Jesus;<br/>Ug masakot pag-usa Niya.<br/>',NULL,19058,1);
INSERT INTO stanza VALUES('CB1141','2','Daghang tuig na diha’s relih’yon,<br/>Daghang tuig na’s hunahuna,<br/>Daghang tuig na sa pagbati ta,<br/>Sigeg pangita, wa kakita.<br/>',NULL,19059,2);
INSERT INTO stanza VALUES('CB1141','3','Nagtuon pagliso’s espiritu,<br/>Nagtuon pagdawat kang Cristo;<br/>Nagtuon sa pagkaon kang Jesus,<br/>Ug magawas sa pakigbisug.<br/>',NULL,19060,3);
INSERT INTO stanza VALUES('CB1141','4','Daygong kinabuhi’s Espiritu,<br/>Daygong pagkabag-o sa sulod,<br/>Inigliso nato’s espiritu,<br/>Mapahimuslang kadato N’ya.<br/>',NULL,19061,4);
INSERT INTO stanza VALUES('CB1142','1','Jesus buhing Espiritu,<br/>Realidad ta;<br/>Mapa’muslan S’ya’s pagtawag<br/>Lang “O Ginoo.”<br/>',NULL,19062,1);
INSERT INTO stanza VALUES('CB1142','chorus','Jesus buhing Espiritu,<br/>Imantala ta;<br/>Dato sa tanang motawag<br/>Sa ngalan Niya.<br/>',NULL,19063,2);
INSERT INTO stanza VALUES('CB1142','2','Jesus buhing Espiritu,<br/>Nagpahigawas;<br/>Maayo, mahinatagon,<br/>Sulayi’g tawag.<br/>',NULL,19064,3);
INSERT INTO stanza VALUES('CB1142','3','Jesus buhing Espiritu,<br/>Ug buhing Pulong;<br/>Tandogon S’ya’s ampo-basa,<br/>Madawat ta S’ya.<br/>',NULL,19065,4);
INSERT INTO stanza VALUES('CB1142','4','Jesus buhing Espiritu,<br/>Nag-agay nato;<br/>Pakig-ambitay magdala’s<br/>Pagkausa ta.<br/>',NULL,19066,5);
INSERT INTO stanza VALUES('CB1142','5','Jesus buhing Espiritu,<br/>Datong kombira;<br/>Karon Lawas nagpa’mulos<br/>Ug nagdayeg N’ya.<br/>',NULL,19067,6);
INSERT INTO stanza VALUES('CB1143','1','Kahoy’s kinabuhi ang Dios,<br/>Tam-is kaayo’g bunga.<br/>Patay ko kanhi, karon buhi,<br/>Gutom, busog na ’ron.<br/>',NULL,19068,1);
INSERT INTO stanza VALUES('CB1143','2','Dios ang nagda’ nako’s kahoy,<br/>May Cristong kalan-on;<br/>Nilami gyud kadtong kahoy<br/>Pagsugod ko’g kaon.<br/>',NULL,19069,2);
INSERT INTO stanza VALUES('CB1143','3','Gino’ mismo kalan-on ko,<br/>Sangkap’s kinabuhi;<br/>Malunsay kong pagpa’mulos,<br/>S’ya ray makatagbaw.<br/>',NULL,19070,3);
INSERT INTO stanza VALUES('CB1143','4','Ning buhing kahoy mokaon,<br/>Pagkaon m’oy pa’gi<br/>Masulod kanako ang Dios,<br/>Tungod N’ya mabuhi.<br/>',NULL,19071,4);
INSERT INTO stanza VALUES('CB1144','1','Tin-aw tang gisuginlan sa Pulong,<br/>Sa dagway’s Dios gibuhat ang tawo.<br/>Magpadayag N’ya, magduma’s yuta,<br/>Magbuot, magtuman’s plano N’ya.<br/>',NULL,19072,1);
INSERT INTO stanza VALUES('CB1144','chorus','Sa dagway N’ya,<br/>Ang tawo gibuhat’s dagway N’ya.<br/>Sa dagway N’ya,<br/>Magbuot, magtuman’s plano N’ya.<br/>',NULL,19073,2);
INSERT INTO stanza VALUES('CB1144','2','Way gisugo S’ya gawas niini:<br/>“Tanang kahoy makaon ninyo.“<br/>Gawas sa kahoy sa kahibalo,<br/>Nga makamatay gayud ninyo.<br/>',NULL,19074,3);
INSERT INTO stanza VALUES('CB1144','chorus','Kahibalo,<br/>Bunga nga dili angayng kan-on.<br/>Kahibalo,<br/>Bunga nga dili angayng kan-on.<br/>',NULL,19075,4);
INSERT INTO stanza VALUES('CB1144','3','May kahoy’s kinabuhi’s tanaman,<br/>Ang Dios sa ’yang Kaugalingon.<br/>Apan kaaway nagtintal’s tawo,<br/>Pagkaon’s kahoy’s kahibalo.<br/>',NULL,19076,5);
INSERT INTO stanza VALUES('CB1144','chorus','Tawo natintal,<br/>Nikaon sa bungang gidili.<br/>Tawo natintal,<br/>Kin’hanglan siyang mahiuli.<br/>',NULL,19077,6);
INSERT INTO stanza VALUES('CB1144','4','Jesucristo kahoy’s kinabuhi,<br/>Nagtagbo’s gipangayo sa Dios.<br/>Kita gianak, yuta gitubos,<br/>Nahimo S’ya nga kalan-on ta.<br/>',NULL,19078,7);
INSERT INTO stanza VALUES('CB1144','chorus','Jesus, Jesus,<br/>Maayo S’ya nga kalan-on ta.<br/>Jesus, Jesus,<br/>Ilimnon, kalan-ong matuod.<br/>',NULL,19079,8);
INSERT INTO stanza VALUES('CB1144','5','Wa S’ya maglaraw, magtagbaw’s kalag;<br/>Kahibalo makapagarbo.<br/>Nia S’ya, matud pa, aron kan-on,<br/>Busa ay’g tun-i, kan-a lang S’ya.<br/>',NULL,19080,9);
INSERT INTO stanza VALUES('CB1144','chorus','Kan-a Siya,<br/>Makatagbaw gyud Siya nimo.<br/>Kan-a Siya,<br/>S’ya ang kahoy’s kinabuhi ta.<br/>',NULL,19081,10);
INSERT INTO stanza VALUES('CB1144','6','Sa pagkaon Niya magtubo ta,<br/>Sa kinabuhi’g gidaghanon.<br/>Tinoon gyud ang pahiuli’s Dios,<br/>Kalan-on S’ya, di relihiyon.<br/>',NULL,19082,11);
INSERT INTO stanza VALUES('CB1144','chorus','Kan-a Siya,<br/>S’yang kalan-ong kinahanglan ta.<br/>Kan-a Siya,<br/>Mabuhi gyud ang mokaon N’ya.<br/>',NULL,19083,12);
INSERT INTO stanza VALUES('CB1144','7','Cristo makinabuhi ta karon,<br/>Pagkaon N’ya di lang kulangon.<br/>Sa pagkaon, iglesia mahingpit,<br/>Makapabalik’s Pamanhonon.<br/>',NULL,19084,13);
INSERT INTO stanza VALUES('CB1144','chorus','Ang pagkaon,<br/>Di gyud nato pasarpasaron.<br/>Ang pagkaon,<br/>Makapabalik’s Pamanhonon.<br/>',NULL,19085,14);
INSERT INTO stanza VALUES('CB1145','1','Anak gihatag’s Dios sa tawo,<br/>Kahoy’s kinabuhing dato;<br/>Makaon, ug makita’s tawo<br/>Nga Dios laming kan-on.<br/>Oo, laming kan-on!<br/>Dios lami nga kan-on!<br/>Makapamatuod kami,<br/>Dios lami gyung kan-on!<br/>',NULL,19086,1);
INSERT INTO stanza VALUES('CB1145','2','Ning kombira nikaon’s Dios,<br/>Ug nabuhi tungod Niya,<br/>Kay elemento’s pagkaon,<br/>Ang ’yang Kaugalingon.<br/>Si Jesus kalan-on!<br/>Oo, S’ya kalan-on!<br/>Nabuhi sa pagkaon N’ya,<br/>Si Jesus kalan-on!<br/>',NULL,19087,2);
INSERT INTO stanza VALUES('CB1145','3','Cristo Jesus ang gikaon,<br/>S’yang unod ug tinapay ta;<br/>Sangkap’s kinabuhi, hingpit;<br/>Kan-on adlaw-adlaw.<br/>Kan-on adlaw-adlaw,<br/>Kan-on adlaw-adlaw,<br/>Sangkap’s kinabuhi, hingpit;<br/>Kan-on adlaw-adlaw.<br/>',NULL,19088,3);
INSERT INTO stanza VALUES('CB1145','4','Kining kalan-on lami gyud,<br/>Na’ kanunay, mapa’muslan,<br/>Dios nag-ingon bisan kinsa<br/>Makakaon Niya.<br/>Oo, makakaon,<br/>Ug wala gyuy bayad.<br/>Dios nag-ingon bisan kinsa<br/>Makakaon Niya.<br/>',NULL,19089,4);
INSERT INTO stanza VALUES('CB1148','1','Ang Ginoo nagdapit nato karon,<br/>Kaon kang Jesus sa tanang panahon!<br/>S’ya ra ang makatagbaw<br/>Sa ato nga kagutom,<br/>“Umari,” nagdapit S’ya nato karon.<br/>',NULL,19090,1);
INSERT INTO stanza VALUES('CB1148','2','Ang Ginoo nagdapit nato karon,<br/>Inom kang Jesus sa tanang panahon.<br/>Kinabuhi S’ya’s sulod,<br/>Kita Iya mang pun-on<br/>“Umari,” nagdapit S’ya nato karon.<br/>',NULL,19091,2);
INSERT INTO stanza VALUES('CB1149','1','Ang grasya’g kamatuoran,<br/>Gikan gayud ni Cristo;<br/>Niinom na ning tuboran,<br/>Diha’s balay Niya!<br/>',NULL,19092,1);
INSERT INTO stanza VALUES('CB1149','chorus','Daygon ang Dios! Niinom na’s tuboran!<br/>Daygon ang Dios! Nia’s balay sa Dios!<br/>',NULL,19093,2);
INSERT INTO stanza VALUES('CB1149','2','Pangayo lang kay hatagan,<br/>Niinom ta’s tuboran;<br/>S’ya ra ang tinguhaon ta,<br/>Dinhi sa balay N’ya!<br/>',NULL,19094,3);
INSERT INTO stanza VALUES('CB1149','3','Bisan unsaon sa Yawa,<br/>Niinom ta’s tuboran;<br/>Dili gyud makadaug s’ya<br/>Batok sa iglesia!<br/>',NULL,19095,4);
INSERT INTO stanza VALUES('CB1149','4','Adto dayon kon uhawon,<br/>Sa tuboran moinom;<br/>Tubod dili gyud mauga,<br/>Naa ’ni’s iglesia!<br/>',NULL,19096,5);
INSERT INTO stanza VALUES('CB1150','1','Nagkaon sa buhing tinapay,<br/>Nag-inom sa buhing tuboran;<br/>Ug bisan kinsang moinom,<br/>Dili na gayud uhawon.<br/>Unsay dili uhawon? Oo, di na uhawon!<br/>Unsay dili uhawon? Oo, di na uhawon!<br/>Bisan kinsa nga moinom,<br/>Dili na gayud uhawon!<br/>',NULL,19097,1);
INSERT INTO stanza VALUES('CB1150','2','Nagkaon sa buhing tinapay,<br/>Kalan-ong dulot sa Ginoo,<br/>Bisan kinsa nga mokaon,<br/>Dili na gayud gutomon.<br/>Unsay di na gutomon? Oo, di na gutomon!<br/>Unsay di na gutomon? Oo, di na gutomon!<br/>Bisan kinsa nga mokaon,<br/>Dili na gayud gutomon.<br/>',NULL,19098,2);
INSERT INTO stanza VALUES('CB1150','3','Nagginhawa sa buhing hangin,<br/>Pag-ambit’s kinabuhi N’ya,<br/>Bisan kinsay moginhawa—<br/>Kinabuhi maangkon n’ya.<br/>Unsa, Dios maangkon ta? Oo, Dios maangkon ta!<br/>Unsa, Dios maangkon ta? Oo, Dios maangkon ta!<br/>Bisan kinsay moginhawa,<br/>Kinabuhi maangkon n’ya!<br/>',NULL,19099,3);
INSERT INTO stanza VALUES('CB1150','4','Natilawan nang buhing bino,<br/>Diosnong kinabuhi’s Ginoo,<br/>Bisan kinsay makatilaw,<br/>Sa Dios gyud siya maghugyaw.<br/>Unsa, sa Dios maghugyaw? Oo, sa Dios maghugyaw!<br/>Unsa, sa Dios maghugyaw? Oo, sa Dios maghugyaw!<br/>Bisan kinsay makatilaw,<br/>S’ya gayud maghugyaw.<br/>',NULL,19100,4);
INSERT INTO stanza VALUES('CB1150','5','Si Cristo ang nabanhawng Hari,<br/>Magdala nato sa kinabuhi,<br/>Bisan kinsa nga modawat,<br/>Mabuhi hangtud sa dayon.<br/>Unsa, mabuhi’s dayon? Oo, mabuhi’s dayon!<br/>Unsa, mabuhi’s dayon? Oo, mabuhi’s dayon!<br/>Bisan kinsa nga modawat,<br/>Mabuhi hangtud sa dayon!<br/>',NULL,19101,5);
INSERT INTO stanza VALUES('CB1151','1','Inom sa lunsayng suba nga gikan sa trono;<br/>Kaon’s kahoy’s kinabuhi, dato kaayo;<br/>Suga, Adlaw ug Bulan, di na kinahanglan,<br/>Way gabii didto.<br/>',NULL,19102,1);
INSERT INTO stanza VALUES('CB1151','chorus','Ang Espiritu ug Pangasaw-onon<br/>Nagdapit, “Umari kamong giuhaw.“<br/>Way bayad kamong makainom karon<br/>Sa tubig sa kinabuhi.<br/>',NULL,19103,2);
INSERT INTO stanza VALUES('CB1151','2','Cristo atong suba ug tubig nga nagtubod;<br/>Kahoy ug mga bunga napa’muslan’s sulod.<br/>Atong adlaw, kahayag, bito’n’s kabugason:<br/>Cristo atong tanan!<br/>',NULL,19104,3);
INSERT INTO stanza VALUES('CB1151','3','Nanglaba’s mga biste aron makakaon,<br/>Sa kahoy’s kinabuhi—Jesus pagkatam-is!<br/>Gamitong espiritu aron masinati<br/>Unsa si Cristo!<br/>',NULL,19105,4);
INSERT INTO stanza VALUES('CB1151','4','May balay kita nga mas masanag pa’s Adlaw,<br/>Diin mga igsoon nahiusa gayud.<br/>Si Jesus ang nag-una, S’yay ipasundayag<br/>Sa iglesia lokal.<br/>',NULL,19106,5);
INSERT INTO stanza VALUES('CB1152','1','Matag adlaw kasingkasing nadani kang Jesus;<br/>Matahum pa S’ya’s linibo, sa yamog mas bag-o,<br/>Di S’ya ikaasoy’s labing nindot nga pamulong,<br/>Ug labi pa Siyang mahal kay sa kaniadto.<br/>',NULL,19107,1);
INSERT INTO stanza VALUES('CB1152','chorus','Dili S’ya mahanduraw’s kabahandianon,<br/>Labi pa Siya nga mahal kay sa kaniadto!<br/>',NULL,19108,2);
INSERT INTO stanza VALUES('CB1152','2','Nakitang himaya N’ya dinhi ra sa iglesia,<br/>Niang kadato N’ya, dili na pangitaon pa;<br/>Dinhi gitagbaw N’yang nangandoy tang espiritu,<br/>Ug labi pa Siyang mahal kay sa kaniadto.<br/>',NULL,19109,3);
INSERT INTO stanza VALUES('CB1152','3','Buhi S’yang Espiritu nagpuyo’s espiritu,<br/>Sa dihog N’ya nangadasig ang kinabuhi ta!<br/>Sa tigum nato espiritu pagkahabog gyud,<br/>Kay labi pa Siyang mahal kay sa kaniadto.<br/>',NULL,19110,4);
INSERT INTO stanza VALUES('CB1152','4','Gihiusa kita Niya alang’s pahiuli:<br/>Cristo, iglesia, makita unta’s mga tawo,<br/>Ibubo tanang nabatonan ug pagkamao<br/>Alang’s tuyo N’ya nga mahal kay sa kaniadto!<br/>',NULL,19111,5);
INSERT INTO stanza VALUES('CB1153','1','Napalgan namo’s Cristong tanan,<br/>S’ya ang tanan kanamo;<br/>Pagtawag Kaniya kalipay,<br/>Pagkamahimayaon!<br/>',NULL,19112,1);
INSERT INTO stanza VALUES('CB1153','chorus','Kalipay way sama ug mahimayaon,<br/>Mahimayaon, mahimayaon;<br/>Kalipay way sama ug mahimayaon,<br/>Wa pa ikaasoy ang tanan!<br/>',NULL,19113,2);
INSERT INTO stanza VALUES('CB1153','2','Napalgang Espiritu’s Cristo<br/>Nagpuyo’s esp’ritu ta;<br/>Nia kanunay, pagkaduol,<br/>Ug tam-is kaayo S’ya.<br/>',NULL,19114,3);
INSERT INTO stanza VALUES('CB1153','3','Mabuhi diay ta ni Cristo<br/>Sa pagtawag’s ngalan N’ya;<br/>Igo nang mokaon-inom N’ya,<br/>Imantalang kaayo.<br/>',NULL,19115,4);
INSERT INTO stanza VALUES('CB1153','4','Iglesia lokal nakaplagan,<br/>Nahiuli na gayud!<br/>Wala na ta sa Babilonia,<br/>Puy-anan ta iglesia.<br/>',NULL,19116,5);
INSERT INTO stanza VALUES('CB1153','5','Ang ato nga panagkatigum,<br/>Labing kalipay karon;<br/>Ang espiritu ta malig-on,<br/>Nabuhi nga bililhon.<br/>',NULL,19117,6);
INSERT INTO stanza VALUES('CB1158','1','Gihigugma Ka, Ginoo,<br/>Gidaug ko’s gugma Mo;<br/>Kinsay makasama Nimo?<br/>Sa katahum ug kalomo?<br/>Katahum Mo di hitupngan,<br/>Walay ikatandi man!<br/>',NULL,19118,1);
INSERT INTO stanza VALUES('CB1158','2','Gihigugma Ka, Ginoo,<br/>Ang tawag Mo sugton ko;<br/>Sukad nadungog ang tingog,<br/>Ubang butang di katandog;<br/>Kawang ang ubang tinguha,<br/>Garbo Imong gikuha.<br/>',NULL,19119,2);
INSERT INTO stanza VALUES('CB1158','3','Gihigugma Ka, Ginoo,<br/>Di na ako mosuki;<br/>Ipadaplin kong kagahi,<br/>Uban’s awit mopauli;<br/>Gugma Mo naggapos nako,<br/>Malipayong mosugot.<br/>',NULL,19120,3);
INSERT INTO stanza VALUES('CB1158','4','Gihigugma Ka, Ginoo,<br/>Pilion kong dalan Mo;<br/>Bisan luha ko moagay,<br/>Mosalig gihapon Nimo;<br/>Pangandoy kong kalipay Mo,<br/>Ug kalinaw’s gugma Mo.<br/>',NULL,19121,4);
INSERT INTO stanza VALUES('CB1158','5','Gihigugma Ka, Ginoo,<br/>Kon Ikaw mahilayo,<br/>Adlaw morag di mosidlak,<br/>Nawong ko wa gyuy kahayag;<br/>Gimingaw sa pagbalik Mo,<br/>Sa presensya mopuyo.<br/>',NULL,19122,5);
INSERT INTO stanza VALUES('CB1158','6','Gihigugma Ka, Ginoo,<br/>Ikaasoy bang tanan?<br/>Ikaw akong katagbawan,<br/>Pahat nga way katapusan;<br/>Ikaw ra ang tinguhaon,<br/>Magtagbo’s akong tanan!<br/>',NULL,19123,6);
INSERT INTO stanza VALUES('CB1158','7','Gihigugma Ka, Ginoo,<br/>Tanan akong itugyan;<br/>Kinsay makasama Nimo?<br/>Sa katahum ug kalomo?<br/>Katahum Mo di hitupngan,<br/>Walay ikatandi man.<br/>',NULL,19124,7);
INSERT INTO stanza VALUES('CB1159','1','Pagkatahum Mo gayud, Ginoo,<br/>Kasingkasing ko nabihag Mo;<br/>Nagawas sa pagkarelihiyoso,<br/>Ikaw ra karon ang sundon ko.<br/>Samtang nagsud-ong’s Imong himaya,<br/>Dughan napuno’s diosnong gugma;<br/>Suropi na ako, O Ginoo,<br/>Isagol na’s Espiritu Mo.<br/>',NULL,19125,1);
INSERT INTO stanza VALUES('CB1159','2','Masidlakon—katin-aw’s langit ko!<br/>Anak’s Tawo, nakita ko’s trono!<br/>Balaan, kalayo’s Dios nag-ut-ot,<br/>Hangtud Ikaw ray isidlak ko.<br/>Pagkakita ko’s Imong katahum,<br/>Nawalang gugma’s kaugalingon;<br/>Karon Imo nang gugma’g pagdayeg ko,<br/>Nagpa’mulos sa katam-is Mo.<br/>',NULL,19126,2);
INSERT INTO stanza VALUES('CB1159','3','Ginoo, ang akong alabastro<br/>Buk-on tungod’s gugma ko Nimo;<br/>Dihogan kong ulo Mo, Ginoo;<br/>Imo nang labing maayo ko.<br/>Usikan kong akong kaugalingon;<br/>Natagbaw sa gugma ko Nimo.<br/>Gugma gikan’s kinasuloran ko,<br/>Lanang mahal ibubo Nimo.<br/>',NULL,19127,3);
INSERT INTO stanza VALUES('CB1159','4','Balik na, Ginoong gihigugma,<br/>Gimingaw akong makita Ka;<br/>Pahimusli ang gugma ning dughan,<br/>Hangtud magpahulay ko Nimo.<br/>Di ako ra ang nagmahal Nimo,<br/>Bisan mang Pangasaw-onon Mo;<br/>Pagdali, kay naghulat mi Nimo,<br/>Matagbaw Ka sa gugma namo.<br/>',NULL,19128,4);
INSERT INTO stanza VALUES('CB1164','1','Yutang malangkubon’s tanan,<br/>Cristo alang nako:<br/>S’yang sapa, laglum nga dapit,<br/>Ug mga tuboran.<br/>Sa walog ug kabukiran,<br/>Nag-agay, nagpuno’s tanan,<br/>Kinabuhing gipabaha—<br/>Himaya.<br/>',NULL,19129,1);
INSERT INTO stanza VALUES('CB1164','2','Si Jesus ang yuta’s trigo—<br/>Natawo, gilansang’s krus.<br/>Cebada S’ya, pagkabanhaw,<br/>Yuta’s parras, igos.<br/>Bino’s parras makalipay,<br/>Magkuha’s imong kalaay;<br/>Matagbaw ka sa sangkap N’ya—<br/>S’yang yuta!<br/>',NULL,19130,2);
INSERT INTO stanza VALUES('CB1164','3','Cristo pagkadagaya gyud:<br/>Granadang matuod;<br/>Lana S’ya’s kahoyng oliva,<br/>Kanato nagdihog.<br/>Gatas, dugos ang dala N’ya,<br/>Matam-is ug makabusog.<br/>Cristo puno sa sustansya,<br/>Dato S’ya!<br/>',NULL,19131,3);
INSERT INTO stanza VALUES('CB1164','4','Magkaon kita’s tinapay<br/>Sa maayong yuta;<br/>Way kanihit ug kagutom,<br/>Sa kadato N’ya busgon.<br/>Yuta S’yang lapad, dako gyud;<br/>Kompleto, di gyud masukod,<br/>S’yang labing maayong yuta—<br/>Kanato.<br/>',NULL,19132,4);
INSERT INTO stanza VALUES('CB1164','5','Yuta S’ya sa puthaw-bato,<br/>Tinubdan’s kagahum.<br/>Kaloton ta kining Cristo,<br/>Ang yawa gapuson.<br/>Pag-antus maagian ta,<br/>Mahimong ulayng tumbaga.<br/>Puthaw, tumbaga kin’hanglan<br/>Man nato.<br/>',NULL,19133,5);
INSERT INTO stanza VALUES('CB1164','6','Daygon Ka, alang ning yuta,<br/>Malangkubong Cristo!<br/>Nagkaon, nabusog Niya,<br/>Igo gyud ang sangkap N’ya!<br/>Tudloing maghago kami<br/>Ning yuta sa realidad;<br/>Kalipayng magamit Siya—<br/>Yuta ta.<br/>',NULL,19134,6);
INSERT INTO stanza VALUES('CB1165','1','Nia na kita sa yuta!<br/>O Hallelujah! Sa yuta!<br/>Si Cristo mao ang yuta<br/>O daygon Siya ang yuta!<br/>',NULL,19135,1);
INSERT INTO stanza VALUES('CB1165','chorus','Siya ang gatas ug dugos;<br/>Lugas, lana, bag-ong bino.<br/>Nia na kita sa yuta!<br/>O Hallelujah! Sa yuta!<br/>',NULL,19136,2);
INSERT INTO stanza VALUES('CB1165','2','Yutang naglangkob sa tanan:<br/>Trigo, cebada, higuera,<br/>Daghan kaayong tuboran;<br/>Dagaya nga kaparrasan.<br/>',NULL,19137,3);
INSERT INTO stanza VALUES('CB1165','chorus','Mag-uma ta adlawng tanan,<br/>Aron ang abut modaghan,<br/>Matag tigum ihalad ta,<br/>Ang labing maayong bunga.<br/>',NULL,19138,4);
INSERT INTO stanza VALUES('CB1170','1','Ginoo akong Magbalantay,<br/>Ako ’yang gipapahulay,<br/>Gida’ N’ya’s tubig nga malinaw,<br/>O unsa S’ya makatagbaw!<br/>',NULL,19139,1);
INSERT INTO stanza VALUES('CB1170','chorus','Ang kaayo’g kaluoy magsunod gyud<br/>Kanako sa tanan nga adlaw;<br/>Ang kaayo’g kaluoy magsunod gyud<br/>Kanako sa tanan nga adlaw.<br/>Ug magpuyo ako sa balay sa Ginoo,<br/>Ug mokaon sa talad nga andam N’ya;<br/>Ang kaayo’g kaluoy magsunod gyud<br/>Kanako sa tanan nga adlaw.<br/>',NULL,19140,2);
INSERT INTO stanza VALUES('CB1170','2','S’ya mismo akong sibsibanan,<br/>Tubig sa kapahulayan;<br/>Mokaon ko sa ’yang kadato,<br/>Moinom sa Espiritu.<br/>',NULL,19141,3);
INSERT INTO stanza VALUES('CB1170','3','Sa kalag ko Siya moayo,<br/>Hunahuna ko’g pagbuot;<br/>Maglakaw man ako sa walog,<br/>Kauban S’ya, way kahadlok.<br/>',NULL,19142,4);
INSERT INTO stanza VALUES('CB1170','4','Talad giandam’s Magbalantay,<br/>Atubangan gyud’s kaaway;<br/>Ulo ko gidihogag lana,<br/>Kopa nag-awas’ kalipay!<br/>',NULL,19143,5);
INSERT INTO stanza VALUES('CB1170','5','Karon nagpuyo’s Iyang balay,<br/>Nagpa’mulos kaayo’s Dios;<br/>Di ko ikaasoyng kalipay!<br/>Kalipay ko ang Ginoo!<br/>',NULL,19144,6);
INSERT INTO stanza VALUES('CB1174','1','O unsa nga kadaugan!<br/>Ang Dios mismo nahimong tawo,<br/>Suot N’yang kinaiya’s tawo,<br/>Magtuman’s ’yang dakong plano;<br/>Namatay naglaglag’s Yawa;<br/>Nabanhaw, Anak sa Tawo!<br/>',NULL,19145,1);
INSERT INTO stanza VALUES('CB1174','2','Sa ma’yong kagawian N’ya,<br/>Napugngan Niyang Yawa;<br/>Tawo S’yang nidaug’s panulay,<br/>Nakalabang’s pagsulay.<br/>Madawat na’s espiritu,<br/>Kagawian maako.<br/>',NULL,19146,2);
INSERT INTO stanza VALUES('CB1174','3','Sa Espiritu ning Jesus,<br/>Na’ng ma’yong kinabuhi’s tawo.<br/>May maayong kagawian,<br/>Lunlon diosnon kaayo.<br/>Kadato ning Espiritu,<br/>Sangkap N’ya’s tanang tawo!<br/>',NULL,19147,3);
INSERT INTO stanza VALUES('CB1174','4','Matuod gyud! Misteryoso!<br/>Nagpuyo S’ya sa sulod ko.<br/>Nikaylap, nakinabuhi—<br/>Sa tibu’k kasingkasing ko.<br/>Hallelujah! Hallelujah!<br/>Way hunong nga daygon ko.<br/>',NULL,19148,4);
INSERT INTO stanza VALUES('CB1174','5','O pagkamahimayaon!<br/>Ang Dios nadayag sa unod.<br/>Mga bahin ta’s Lawas N’ya,<br/>Magpadayag’s ’yang pagka-tawo.<br/>Kinabuhi’s pagkatawo N’ya,<br/>Alang’s puy-anan sa Dios.<br/>',NULL,19149,5);
INSERT INTO stanza VALUES('CB1178','1','Nakitang realidad’s Cristo:<br/>Apan dili kini paigo:<br/>Kin’hanglan masinati ta S’ya<br/>Nga atong tanan.<br/>Sa pag-ampo makitang nawong N’ya,<br/>Sa Pulong, tigum maila S’ya;<br/>Apan’s matag adlaw ug dapit,<br/>Unsa S’ya nato?<br/>',NULL,19150,1);
INSERT INTO stanza VALUES('CB1178','chorus','Hallelujah! Sa paghayag N’ya<br/>Makitang tinuod, dato S’ya.<br/>Kon moliso lang ta N’ya’s tanang<br/>takna, tanang adlaw,<br/>Tanang butang, paagi ug—<br/>Tinoon gyud nga realidad!<br/>Dili lamang nga linangkob ra!<br/>Kon i-apply S’ya makita ta<br/>Kanato tanan S’ya.<br/>',NULL,19151,2);
INSERT INTO stanza VALUES('CB1178','2','Kinabuhi puno’s higayon,<br/>Gihan-ay sa kamot’s Amahan:<br/>Makita tang labing maayo,<br/>Angkonon’s Cristo!<br/>Cristo sulod ta’g realidad<br/>Magsidlak gikan’s atong sulod:<br/>Kin’hanglan gyung mosidlak Siya<br/>Gikan kanato.<br/>',NULL,19152,3);
INSERT INTO stanza VALUES('CB1178','chorus','Hallelujah! Diha sa lawas<br/>Magdala’s kamatayong Cristo:<br/>Kinabuhi Niya madayag<br/>Kon tawo sa gawas mabungkag,<br/>Tawo sa sulod magsidlak aron—<br/>Makita nga ni’ning kolonon<br/>Dunay bahandi nga tinuod!<br/>Aron himaya’s ebanghelyo<br/>Mosidlak na gyud.<br/>Di lang doktrina’g teolohiya,<br/>Kondi’ realidad sa sulod;<br/>Cristo nga tanan sa sulod ta,<br/>Tanan nato Siya!<br/>',NULL,19153,4);
INSERT INTO stanza VALUES('CB1179','1','Gilansang nang daang tawo uban N’ya,<br/>Uban’s bahong kadunot niini;<br/>Gilubong halasnong kinaiya,<br/>Dakong kamat’oran natapos na,<br/>Hawiran ta.<br/>',NULL,19154,1);
INSERT INTO stanza VALUES('CB1179','2','Karon may Persona’s espiritu,<br/>Ikatandi sa batang masuso;<br/>Magtubo’s lunsayng gatas sa Pulong,<br/>Tawo sa sulod magmadaugon<br/>Mag-angkon nako.<br/>',NULL,19155,2);
INSERT INTO stanza VALUES('CB1179','3','Sa kasingkasing S’ya manag-iya,<br/>Sa tanang bahin mag-una gyud S’ya.<br/>Bisan samokon’s kanhing agalon,<br/>Hunahuna, pagbati, sudlon Mo,<br/>Dawaton ko.<br/>',NULL,19156,3);
INSERT INTO stanza VALUES('CB1179','4','Masagol, mausa’s espiritu,<br/>Ug mahiusa ang Dios ug tawo;<br/>Hustong galamhan kinahanglan Mo,<br/>Aron tibu’k Mong personalidad<br/>Mapadayag!<br/>',NULL,19157,4);
INSERT INTO stanza VALUES('CB1179','5','Kasingkasing ihalad Kanimo,<br/>Sa tanang paagi mapuy-an Mo;<br/>Himoang dapit pahulayan Mo,<br/>Ang buhat’s pahiuli mahingpit,<br/>Sa bag-ong tawo.<br/>',NULL,19158,5);
INSERT INTO stanza VALUES('CB1191','1','Sa espiritu ko may tubod nag-awas,<br/>Tulo-usang Dios nag-agay;<br/>Amahan tinubdan, Anak agianan,<br/>Espiritu nagpaambit.<br/>',NULL,19159,1);
INSERT INTO stanza VALUES('CB1191','chorus','Mahal kong agay’s kinabuhi,<br/>Sa kalag ako magdumili;<br/>Niining agay magpalalum<br/>Aron kinabuhi mahamtong.<br/>',NULL,19160,2);
INSERT INTO stanza VALUES('CB1191','2','Sa lunhaw nga sagbut gipahigda ako;<br/>Gidala’s tubig’s pahulay;<br/>Wala nay kaugalingon nga paningkamot;<br/>Mabulahan sa ’yang agay.<br/>',NULL,19161,3);
INSERT INTO stanza VALUES('CB1191','3','Gitawag sa Dapit nga Labing Balaan,<br/>Papuy-on sa presensya N’ya;<br/>Hallelujah, gidasig ako sa pulong:<br/>“Pabilin kay ikaw sanga.”<br/>',NULL,19162,4);
INSERT INTO stanza VALUES('CB1193','1','Kinabuhi ang Dios nga Amahan,<br/>Cristong niagayng Espiritu,<br/>Kalami ning Personaha, maayo!<br/>Datong kinabuhi nato S’ya.<br/>',NULL,19163,1);
INSERT INTO stanza VALUES('CB1193','2','Gipanganak na kita pag-usab<br/>Sa pagdawat Kaniyang buhi.<br/>Gisudlan kita’s laing kinabuhi,<br/>Karon napuno kita Niya.<br/>',NULL,19164,2);
INSERT INTO stanza VALUES('CB1193','3','S’yang buhing Espiritu’s sulod ta,<br/>Sa espiritu ngadto’s kalag,<br/>Moagay, magtransporma’s matag bahin,<br/>Sa kinabuhing ipaambit.<br/>',NULL,19165,3);
INSERT INTO stanza VALUES('CB1193','4','Karon mobulig gayud ta Niya.<br/>Hunahuna itumong’s Anak.<br/>Magpahilayo’s tanang magpasaag,<br/>Itumong ra N’ya tibu’k kalag.<br/>',NULL,19166,4);
INSERT INTO stanza VALUES('CB1193','5','Ginoo, nia Ka’s espiritu.<br/>Apan buhaton pang tuyo Mo;<br/>Kon b’yaan nang hunahunang nagkatag,<br/>’Palgang kinabuhi’g kalinaw.<br/>',NULL,19167,5);
INSERT INTO stanza VALUES('CB1193','6','Bihaga tanang hunahuna ko,<br/>Datong magpa’mulos’ Pulong Mo;<br/>Hunahuna magpabilin sa Pulong,<br/>Sangkapan Mo ug balaanon.<br/>',NULL,19168,6);
INSERT INTO stanza VALUES('CB1193','7','Padayon nga buhatong pag-apply,<br/>Ning kinabuhing magtagad N’ya.<br/>Daygon S’ya’s paagi’s pagkinabuhi!<br/>Hunahuna itumong Nimo.<br/>',NULL,19169,7);
INSERT INTO stanza VALUES('CB1196','1','Atong Dios buhi—O Hallelujah!<br/>Nagpuyo nato—O Hallelujah!<br/>Natilawan ta<br/>Ang kadato N’ya,<br/>Siya ang panulondon ta.<br/>',NULL,19170,1);
INSERT INTO stanza VALUES('CB1196','2','Sa paghiusa way molabaw pa—<br/>Kay panimalay ta N’ya’s esp’ritu,<br/>Buhing Lawas N’ya<br/>Ipadayag S’ya,<br/>Jesus atong realidad.<br/>',NULL,19171,2);
INSERT INTO stanza VALUES('CB1196','3','Sa tanang iglesia gipuno ta,<br/>Aron suropon ang kanasuran,<br/>Jesus ikaylap<br/>Sa matag syudad,<br/>Buhing Cristo makita na.<br/>',NULL,19172,3);
INSERT INTO stanza VALUES('CB1198','1','Ang Dios gamhanang pag-agay,<br/>Sa tanang kapanahonan.<br/>Aron maagayan N’yang tawo<br/>Anaa S’ya’s daghang hugna;<br/>Apan usang Dios ra,<br/>Usang agay’s dayon;<br/>Kini ’yang paagi,<br/>Sa tawo makaagay,<br/>Nia na S’ya’s sulod ta!<br/>',NULL,19173,1);
INSERT INTO stanza VALUES('CB1198','2','Sa sinugdan makita ta,<br/>Dios niagay sama’s suba,<br/>Naghatud’s kahoyng S’ya mismo,<br/>Nga kinabuhi nato.<br/>Ug sa katapusan,<br/>Suba nagpabilin,<br/>Kahoy nga nagtubo,<br/>Pag-agay gyud sa Dios,<br/>Diha’s Cordero’s dayon.<br/>',NULL,19174,2);
INSERT INTO stanza VALUES('CB1198','3','Dios niagay nganhi sa tawo,<br/>Nga ginganlan ug Jesus.<br/>Kinabuhi N’ya gitugyan,<br/>Aron Dios mahubaran.<br/>Yawa naningkamot<br/>Pagpugong’s ’yang agay—<br/>Sa krus S’ya gilansang,<br/>Kilid N’ya gidughang—<br/>Dugo’g tubig nigula!<br/>',NULL,19175,3);
INSERT INTO stanza VALUES('CB1198','4','Dugo’g tubig gikan Niya,<br/>Sulog’s lunsayng kal’wasan.<br/>Dugong naghinlo’s tanang sala,<br/>Tubig, nag-anak pag-usab.<br/>Agay’s Espiritu<br/>Dios gayud ang dala,<br/>Ang mahimo’s Yawa<br/>Paghubad ra’s agay,<br/>Dios sige mang nag-agay.<br/>',NULL,19176,4);
INSERT INTO stanza VALUES('CB1199','1','Tuyo sa Dios sa uniberso anaa’s mga tawo,<br/>Na-Espiritu ang Ginoo aron masagol’s tawo.<br/>Nalipay tang nakaambit sa ’yang pamatigayon,<br/>Oo, panagsagol.<br/>',NULL,19177,1);
INSERT INTO stanza VALUES('CB1199','chorus','Panagsagol, hallelujah,<br/>Panagsagol, hallelujah,<br/>Panagsagol, hallelujah,<br/>Kini ang paagi!<br/>',NULL,19178,2);
INSERT INTO stanza VALUES('CB1199','2','Gikan sa sentro sa pagkatawo ngadto’s kalag ta,<br/>Pihong dapit gibuhat aron nga kasudlan Niya;<br/>Hunahuna, pagbati ug atong pagbuot pun-on,<br/>Oo, panagsagol.<br/>',NULL,19179,3);
INSERT INTO stanza VALUES('CB1199','3','Nalipay dinhi’s pahiuli nakit-ang paagi,<br/>Ang Tulo-usang Dios masinati, makinabuhi—<br/>Busa’s nasagol nga espiritu magpuyo karon;<br/>Oo, panagsagol.<br/>',NULL,19180,4);
INSERT INTO stanza VALUES('CB1199','4','Taliwala’s pitong tangkawan Anak’s Tawo makita;<br/>Alang’s pahiuli mga mata Niya nagsiga.<br/>Tinguha’s Dios Iyang humanon—tawo nga hinugpong;<br/>Oo, panagsagol.<br/>',NULL,19181,5);
INSERT INTO stanza VALUES('CB1199','5','Sa inadlawng buhat, hunahuna, pagkamao ta;<br/>Magpalalum pa’s panagsagol, mag-angkon’s Ginoo;<br/>Ihalad ang kaugalingon aron masagol ta,<br/>Oo, panagsagol.<br/>',NULL,19182,6);
INSERT INTO stanza VALUES('CB1199','6','Bag-ong Jerusalem—bunga’s inadlawng kinabuhi,<br/>Kinasang-ang panagsagol—kini diosnong katawhan.<br/>Kalipay nga nakaambit tang tanan’s hiniusa.<br/>Oo, panagsagol.<br/>',NULL,19183,7);
INSERT INTO stanza VALUES('CB1205','1','Magpadayon’s atong tumong—<br/>Cristong malangkubon.<br/>Ganti sa tawag maangkon,<br/>Basta magpadayon!<br/>',NULL,19184,1);
INSERT INTO stanza VALUES('CB1205','chorus','Padayon! Padayon!<br/>Padayon! Hallelujah sa ganti<br/>Nga maangkon! Padayon!<br/>Magpadayon karon!<br/>',NULL,19185,2);
INSERT INTO stanza VALUES('CB1205','2','Isipa nga kapildehan,<br/>Ang tanang naangkon,<br/>Kon si Cristo’y mabatonan,<br/>Mas mahimayaon!<br/>',NULL,19186,3);
INSERT INTO stanza VALUES('CB1205','3','Makaila pa gyud Niya<br/>Ug gahum’s pag’banhaw—<br/>O kinalabwan ning balus,<br/>Bisan pag mag-antus!<br/>',NULL,19187,4);
INSERT INTO stanza VALUES('CB1205','4','Ato gayud nga timan-an<br/>Nangagi kalimtan;<br/>Sulong lang didto’s unahan,<br/>Cristo atua man!<br/>',NULL,19188,5);
INSERT INTO stanza VALUES('CB1206','1','May lumba kita karon nga salmotan,<br/>Ug paagi kini madag-an.<br/>Sa tanang nakasugod, Dios nag-ingon:<br/>“Lingiw ug tutoking Ginoo!”<br/>',NULL,19189,1);
INSERT INTO stanza VALUES('CB1206','chorus','Tutoki! O tutoki!<br/>Si Jesus tutokan mo!<br/>Lingiw’s tanan, si Jesus ang tutokan,<br/>Lingiw sa tanan, S’ya tutokan!<br/>',NULL,19190,2);
INSERT INTO stanza VALUES('CB1206','2','Ilingiw ang panan-aw sa palibot,<br/>Sa tanang kasamok, kagubot;<br/>May kalinaw si Jesus—Hallelujah,<br/>Lingiw sa tanan, tutokan S’ya.<br/>',NULL,19191,3);
INSERT INTO stanza VALUES('CB1206','3','Molingiw ta sa mausabong kalag,<br/>Sa pakyas gyung kaugalingon;<br/>Lingiw ug tutok’s tumong—Hallelujah,<br/>Lingiw sa tanan, tutokan S’ya.<br/>',NULL,19192,4);
INSERT INTO stanza VALUES('CB1206','4','Molingiw sa nangagi—Hallelujah,<br/>Lingiw’s maayo ug sa sala;<br/>Hawid lang sa buhing Dios—Hallelujah,<br/>Lingiw sa tanan, tutokan S’ya.<br/>',NULL,19193,5);
INSERT INTO stanza VALUES('CB1206','5','Lingiw, tutoking nawong N’ya—Hallelujah,<br/>S’yang mohuman sa gisugdan N’ya.<br/>O dakong grasya ang modagan’s lumba,<br/>Nga makuha sa pagtutok N’ya!<br/>',NULL,19194,6);
INSERT INTO stanza VALUES('CB1214','1','Kuhaa, kuhaa, kuhaa,<br/>Ang sala nga kanako nagsudya!<br/>Kuhaa, kuhaa, kuhaa,<br/>Ang sala nga kanako nagsudya!<br/>',NULL,19195,1);
INSERT INTO stanza VALUES('CB1214','chorus','Kon sala makuha,<br/>Agay mogula . . . Hallelujah!<br/>Kuhaa, kuhaa, kuhaa,<br/>Ang sala nga kanako nagsudya!<br/>',NULL,19196,2);
INSERT INTO stanza VALUES('CB1214','2','Kuhaa, kuhaa, kuhaa,<br/>Ang kawang nga mga pangandoy ko!<br/>Kuhaa, kuhaa, kuhaa,<br/>Ang kawang nga mga pangandoy ko!<br/>',NULL,19197,3);
INSERT INTO stanza VALUES('CB1214','chorus','Kuhaang damgo ko,<br/>Agay mogula . . . Hallelujah!<br/>Kuhaa, kuhaa, kuhaa,<br/>Ang kawang nga mga pangandoy ko!<br/>',NULL,19198,4);
INSERT INTO stanza VALUES('CB1214','3','Kuhaa, kuhaa, kuhaa,<br/>Tanan nga nagsamok nga pagbati!<br/>Kuhaa, kuhaa, kuhaa,<br/>Tanan nga nagsamok nga pagbati!<br/>',NULL,19199,5);
INSERT INTO stanza VALUES('CB1214','chorus','Kuhaang gugma ko,<br/>Sa kaugalingon . . . Hallelujah!<br/>Mogula ang kinabuhi Mo<br/>Kuhaang nagsamok nga pagbati!<br/>',NULL,19200,6);
INSERT INTO stanza VALUES('CB1214','4','Kuhaa, kuhaa, kuhaa<br/>Tanang pagsuki sa pagbuot ko!<br/>Kuhaa, kuhaa, kuhaa,<br/>Tanang pagsuki sa pagbuot ko!<br/>',NULL,19201,7);
INSERT INTO stanza VALUES('CB1214','chorus','Kuhaang pagbuot,<br/>Ikaw magbuot . . . Hallelujah!<br/>Kuhaa, kuhaa, kuhaa,<br/>Tanang pagsuki sa pagbuot ko!<br/>',NULL,19202,8);
INSERT INTO stanza VALUES('CB1214','5','Kuhaa, kuhaa, kuhaa,<br/>Tanang kaugalingong tinguha ko!<br/>Kuhaa, kuhaa, kuhaa,<br/>Tanang kaugalingong tinguha ko!<br/>',NULL,19203,9);
INSERT INTO stanza VALUES('CB1214','chorus','Tanan nga paglaum,<br/>Imong kuhaon . . . Hallelujah!<br/>Mogula ang kinabuhi Mo<br/>Kuhaang kaugalingong tinguha!<br/>',NULL,19204,10);
INSERT INTO stanza VALUES('CB1214','6','Ang kinabuhi Mo moagay,<br/>Gikan’s tubod sa kasingkasing ko!<br/>Ang kinabuhi Mo moagay,<br/>Gikan’s tubod sa kasingkasing ko!<br/>',NULL,19205,11);
INSERT INTO stanza VALUES('CB1214','chorus','Ang kasingkasing ko<br/>Kon mahigawas . . . Hallelujah!<br/>Diha nako S’ya makaagay,<br/>Gikan’s tubod sa kasingkasing ko!<br/>',NULL,19206,12);
INSERT INTO stanza VALUES('CB1217','1','Ang tawag among nadunggan,<br/>“Duol’s Labing Balaan,“<br/>Aron himaya masud-ong<br/>Kasanag’s Imong nawong.<br/>',NULL,19207,1);
INSERT INTO stanza VALUES('CB1217','chorus','Moduol’s Labing Balaan,<br/>Pina’gi’s incienso man;<br/>Tabil nga nagbulag wa na,<br/>May kaisug sudlon ta.<br/>',NULL,19208,2);
INSERT INTO stanza VALUES('CB1217','2','Moduol’s Labing Balaan<br/>Agi’s bag-o nga dalan,<br/>Bag-o pa gyud nga gibuksan;<br/>Pagkamahimayaon.<br/>',NULL,19209,3);
INSERT INTO stanza VALUES('CB1217','3','Moduol kita’s atong Dios,<br/>Nga naglingkod sa trono;<br/>Dalan’s himaya gibuksan<br/>Sa krus ug Iyang dugo.<br/>',NULL,19210,4);
INSERT INTO stanza VALUES('CB1217','4','Moduol’s bag-ong panahon,<br/>Maisug, masaligon.<br/>Magpa’mulos’ tuyong dayon,<br/>Daan di na lingion.<br/>',NULL,19211,5);
INSERT INTO stanza VALUES('CB1217','5','Daygon kay kaduolan man,<br/>Sulod’s Labing Balaan,<br/>Dios Ka namo’g tawo mi Nimo;<br/>Dinhi magpuyo’s dayon.<br/>',NULL,19212,6);
INSERT INTO stanza VALUES('CB1220','1','Kuhaang taptap, Ginoo,<br/>Sa kasingkasing ko;<br/>Padaygi sa panan-awon,<br/>Sa pahiuli Mo.<br/>',NULL,19213,1);
INSERT INTO stanza VALUES('CB1220','2','Matugkad’s bugnang gahum Mo<br/>Nga nagbanhawng Cristo;<br/>Gahum nadawat’s pagtoo,<br/>Nadala’s iglesia.<br/>',NULL,19214,2);
INSERT INTO stanza VALUES('CB1220','3','Gipagawas’ Imong gahum<br/>Sa butang madanihon;<br/>Nagpasu’d nako’s iglesia lokal,<br/>Kining dakong gahum.<br/>',NULL,19215,3);
INSERT INTO stanza VALUES('CB1220','4','Pagsulod’s iglesia lokal,<br/>Personahon Ka gyud,<br/>Tawo ko’s gawas magkakunhod,<br/>Alang ko’s Ginoo.<br/>',NULL,19216,4);
INSERT INTO stanza VALUES('CB1220','5','Personahon Ka nako Ginoo,<br/>Nalansang uban Nimo.<br/>Gipahiuli tawo ko’s sulod;<br/>Gipuy-an na Nimo.<br/>',NULL,19217,5);
INSERT INTO stanza VALUES('CB1220','6','Kon isalikwayng kaugalingon,<br/>Maila ang Lawas Mo,<br/>Kon mag-ambit’s Persona Mo,<br/>Madayag bag-ong tawo.<br/>',NULL,19218,6);
INSERT INTO stanza VALUES('CB1220','7','Kinabuhi’s iglesia bag-ong tawo<br/>Madayag’s tanang iglesia lokal,<br/>Hiniusang tawo ang Lawas Mo,<br/>Madayag usang Tawo.<br/>(Sublia ang katapusang duha ka linya sa matag estansa)<br/>',NULL,19219,7);
INSERT INTO stanza VALUES('CB1221','1','Si Jesus Magbalantay ta,<br/>Sa toril gigawas ta;<br/>Sa sibsibanan gidala,<br/>Sa kadagaya Niya.<br/>',NULL,19220,1);
INSERT INTO stanza VALUES('CB1221','chorus','Pagkadagaya!<br/>Sa pagkaon’s iglesia,<br/>Kinabuhing imando N’ya’s<br/>Nagpuyo’s pagkausa.<br/>',NULL,19221,2);
INSERT INTO stanza VALUES('CB1221','2','Sa pagkabahi’g kagutom<br/>Kita ’yang gipangita;<br/>Gidala’s maayong yuta,<br/>Sa atong espiritu!<br/>',NULL,19222,3);
INSERT INTO stanza VALUES('CB1221','3','Jesus mismong sibsibanan,<br/>Kalan-ong gikaon ta;<br/>Carnero tang gipakaon,<br/>Busgon N’ya’s matag tigum.<br/>',NULL,19223,4);
INSERT INTO stanza VALUES('CB1221','4','Habog nga bungtod gipuy-an,<br/>Sa yamog linunhawan,<br/>Tubod nagkuha’s kauhaw,<br/>Buhing tubig, kalunhaw.<br/>',NULL,19224,5);
INSERT INTO stanza VALUES('CB1221','5','S’yang pahulay, pagpa’mulos,<br/>Dinhi way kahadlokan;<br/>Mga carnero bantayan,<br/>Sa presensya ampingan.<br/>',NULL,19225,6);
INSERT INTO stanza VALUES('CB1226','1','Iglesia mahimayaon ug bahin gayud kita—<br/>Nalipayng giusa kita’s Ginoo!<br/>Dunay Lawas sa uniberso, ug nasakop kita—<br/>Hallelujah! giusa ta’s Ginoo!<br/>',NULL,19226,1);
INSERT INTO stanza VALUES('CB1226','chorus','Hallelujah alang’s Lawas!<br/>Mga bahin ta sa Lawas!<br/>Hugot nga alang sa Lawas!<br/>Hallelujah, giusa ta’s Ginoo!<br/>',NULL,19227,2);
INSERT INTO stanza VALUES('CB1226','2','Di’s tinagsang Cristohanon, kondi’ Lawas hinugpong—<br/>Alang’s hingpit nga pagpadayag sa Dios;<br/>Di tinagsang iglesia kondi’ hiniusang Lawas—<br/>Hallelujah, naa na kita’s Lawas!<br/>',NULL,19228,3);
INSERT INTO stanza VALUES('CB1226','chorus','Hallelujah alang’s Lawas!<br/>Magkurog gyud si Satanas!<br/>Madaugon diha’s Lawas!<br/>Hallelujah, naa na kita’s Lawas!<br/>',NULL,19229,4);
INSERT INTO stanza VALUES('CB1226','3','May pitong bulawang tangkawan—diosno’g kinaiya—<br/>Wa may natural nga gitugot’s Lawas.<br/>Kon kinaiya’s Dios ambitan tangkawan magsidlak—<br/>Hallelujah, nagsidlak kini karon!<br/>',NULL,19230,5);
INSERT INTO stanza VALUES('CB1226','chorus','Hallelujah alang’s Lawas!<br/>Alang’s tangkawan nga Lawas!<br/>Bulawang Lawas nagsidlak!<br/>Hallelujah, nagsidlak kini karon!<br/>',NULL,19231,6);
INSERT INTO stanza VALUES('CB1226','4','Pagkausa ipadayag, magdiosnon pa’g magsidlak,<br/>Pagkaon kang Jesus, bugtong paagi!<br/>S’yang kahoy’s kinabuhi, ang manna ug ang kombira—<br/>Hallelujah, inadlawng makaon S’ya!<br/>',NULL,19232,7);
INSERT INTO stanza VALUES('CB1226','chorus','Usa tungod’s pagkaon N’ya!<br/>Diosnon tungod’s pagkaon N’ya!<br/>Nagsidlak sa pagkaon N’ya!<br/>Pagkaon kang Jesus bugtong paagi!<br/>',NULL,19233,8);
INSERT INTO stanza VALUES('CB1232','1','Kanhi patay kita sa sala,<br/>Na’s nabahin gyud nga yuta;<br/>Gibuhi ta pag-usa sa Dios,<br/>Aron molingkod uban sa Ginoo.<br/>',NULL,19234,1);
INSERT INTO stanza VALUES('CB1232','chorus','Giusa ta karon ni Jesus,<br/>Tan-awa, kita nagkausa.<br/>Gidugtong kita N’ya sa gugma,<br/>Ngadto sa hingkod nga sukod’s<br/>Lawas N’ya.<br/>',NULL,19235,2);
INSERT INTO stanza VALUES('CB1232','2','Uban’s tanan makasabut na,<br/>Sa tanang mga sukod’s Dios.<br/>Pagkasayud’s gugma ni Cristo,<br/>Mapuno ta sa kahupnganan sa Dios.<br/>',NULL,19236,3);
INSERT INTO stanza VALUES('CB1232','3','Sa tuyo’s Dios nasayud kita,<br/>Nakita na ang misteryo N’ya;<br/>Mao si Cristo ug iglesia,<br/>Nga magpakaulaw gyud sa kaaway.<br/>',NULL,19237,4);
INSERT INTO stanza VALUES('CB1232','4','Ning tuyo nag-ampo’s Amahan—<br/>Lig-onon ang sulod nga tawo;<br/>Magbalay Ka sa kasingkasing,<br/>Pasukaron mi’s gugma ug plano Mo.<br/>',NULL,19238,5);
INSERT INTO stanza VALUES('CB1232','5','Sa Lawas kita ipahaum,<br/>Ingo’g mga bahin ni Cristo;<br/>Magbuhat sumala’s sukod ta,<br/>Sa pagtubo’s gugma mangatukod ta.<br/>',NULL,19239,6);
INSERT INTO stanza VALUES('CB1232','6','Nausa pagtuman’s tuyo N’ya,<br/>Ingo’g bag-ong tawo’s plano N’ya.<br/>Mahimaya S’ya sa iglesia,<br/>Ug dihang Jesucristo hangtud’s dayon!<br/>',NULL,19240,7);
INSERT INTO stanza VALUES('CB1233','1','O pauli na<br/>Sulod sa iglesia,<br/>Sa kanunay maglipay kita;<br/>Diin si Cristo<br/>Ang kinabuhi ta,<br/>O Hallelujah, sa iglesia!<br/>',NULL,19241,1);
INSERT INTO stanza VALUES('CB1233','chorus','O pauli na,<br/>Mopauli na sa iglesia;<br/>Sa tanang adlaw<br/>Daygon nato Siya,<br/>“Hallelujah—Cristo’g iglesia!”<br/>',NULL,19242,2);
INSERT INTO stanza VALUES('CB1233','2','Dinhi nga dapit<br/>Ang Dios mopahulay<br/>Dako gyud ang Iyang kalipay!<br/>Kasingkasing ta m’oy<br/>Puloy-anan N’ya,<br/>Magpadayag sa himaya N’ya.<br/>',NULL,19243,3);
INSERT INTO stanza VALUES('CB1233','chorus','Puloy-an sa Dios<br/>Mao man ang Iyang iglesia;<br/>Kini mao gyud ang<br/>Iyang tinguha,<br/>“Hallelujah—Cristo’g iglesia!”<br/>',NULL,19244,4);
INSERT INTO stanza VALUES('CB1236','1','Sa iglesia nadungog ang tingog’s kinabuhi,<br/>Kalipay ni Cristo nakita’s tanang dapit;<br/>Kawang nga nagtawag Babilonia, butang’s yuta.<br/>Sa ma’yong yuta nahiuli na!<br/>',NULL,19245,1);
INSERT INTO stanza VALUES('CB1236','chorus','Nakig-iglesia kita<br/>Diha sa Espiritu,<br/>Diha sa sukaranan<br/>Sa iglesia lokal.<br/>Oo, uban’s mga igsoon, yuta padahunogon<br/>Sa hallelujah, Cristo—yuta!<br/>',NULL,19246,2);
INSERT INTO stanza VALUES('CB1236','2','Kagikan ta ug tanang gasa ug pagtulon-an,<br/>Gib’yaan’s layo labi na gyung kalibutan;<br/>Gugma ni Cristo nituhop’s kinahiladman ta,<br/>Way makatarug nato sa yuta.<br/>',NULL,19247,3);
INSERT INTO stanza VALUES('CB1236','3','“Ning bato tukoron Kong iglesia,” sulting Jesus,<br/>Ug nakita natong pagtukod sa ’yang plano;<br/>Segun’s nahamut-an nagbutang ug mga miembro,<br/>Tukoron pag-usa N’ya nga yuta.<br/>',NULL,19248,4);
INSERT INTO stanza VALUES('CB1236','4','Pahiuli karon nagpadayon’s tanang dapit,<br/>Nagkausang mga iglesia pagmando N’ya:<br/>“Padaliang adlaw yuta mag-ampo-basa na<br/>Ug mag-hallelujah’ng Cristong yuta!”<br/>',NULL,19249,5);
INSERT INTO stanza VALUES('CB1237','1','Mahimayaong iglesia! Gidala ta daygon S’ya,<br/>Sa pagsinati ning Cristong nagtubo!<br/>S’ya dato nga pahimuslan sa tanan nga balaan,<br/>Lunhaw, bag-o, S’ya labing duol nato.<br/>',NULL,19250,1);
INSERT INTO stanza VALUES('CB1237','chorus','Malipayon ko ning dapita,<br/>Sa ’yang grasya magtubo kita!<br/>Way labaw sa pagkaon’s kahoy sa kinabuhi<br/>Ug sa pag-inom sa tubig nga buhi.<br/>',NULL,19251,2);
INSERT INTO stanza VALUES('CB1237','2','Di kini tulonghaan o simbahan’s kahanginan,<br/>Apan tanaman nga Iyang kapugsan.<br/>Busa gihiusa ta ingon nga tanaman Niya,<br/>Iyang umahon ug ’yang patuboon.<br/>',NULL,19252,3);
INSERT INTO stanza VALUES('CB1237','3','Sa kinabuhi’s iglesia may kahoy nga namunga,<br/>Puno’s kinabuhi ug makaon ta,<br/>Busa ayaw pagpatig-a, ang pangagpas mo wad-a!<br/>Sa tanang panahon pahimuslan S’ya!<br/>',NULL,19253,4);
INSERT INTO stanza VALUES('CB1237','4','Uban sa kahoy may tubig, mao ang Dios nag-agay,<br/>Nagkuha sa tanan natong kalaay,<br/>Hallelujah! Sa tanaman Jesus kapahimuslan<br/>Nagsangkap kanato ug nagpatubo.<br/>',NULL,19254,5);
INSERT INTO stanza VALUES('CB1237','5','Natagbaw ba kamo nga gidala ta sa Ginoo<br/>Sa Iyang kalipayan ug kadato?<br/>Busa magkalipay ta, sa espiritu magpista,<br/>Sa tanaman nga dagaya ug bunga.<br/>',NULL,19255,6);
INSERT INTO stanza VALUES('CB1240','1','O dad-a kami sa krus ni Jesus,<br/>Ug palaluma;<br/>Ang kamatayon ug kinabuhi,<br/>Mag-uban gayud.<br/>Agay palaluma,<br/>Pagbuhat kanamo;<br/>Hangtud pagkatawo,<br/>Hingpit na nga mabag-o!<br/>',NULL,19256,1);
INSERT INTO stanza VALUES('CB1240','2','Pahaboga sa kinabuhi Mo,<br/>Kay ubos kami.<br/>Makapahabog Ka pa kanamo—<br/>Pahaboga mi.<br/>Ampo adlaw-adlaw—<br/>Transpormahon kami—<br/>Labing modato pa,<br/>Agay’s kinabuhi Mo.<br/>',NULL,19257,2);
INSERT INTO stanza VALUES('CB1240','3','Ginoo nagtubo’s sulod namo,<br/>Sa adlaw-adlaw.<br/>Agayang pagkinabuhi namo—<br/>M’oy paagi Mo.<br/>Magtubo ka unta<br/>Namo adlaw-adlaw.<br/>Di igong masayud,<br/>Patuboon Ka gayud.<br/>',NULL,19258,3);
INSERT INTO stanza VALUES('CB1240','4','Si Cristo atong pagkinabuhi,<br/>Praktikal gayud:<br/>Bisan unsa ug tanan nga butang—<br/>S’ya naa’s tanan.<br/>S’ya ikinabuhi,<br/>Sa tanang paagi.<br/>Tawga ang ngalan N’ya,<br/>Sa tanan mo tugyani.<br/>',NULL,19259,4);
INSERT INTO stanza VALUES('CB1240','5','Si Jesus ang ato nga Persona,<br/>Nia’s sulod ta.<br/>S’yang gana, tinagdan, ug lihok ta;<br/>O kahimaya!<br/>Persona Ka namo,<br/>Magbalay sa sulod.<br/>Sa tanang paagi,<br/>Matag adlaw, Ginoo.<br/>',NULL,19260,5);
INSERT INTO stanza VALUES('CB1240','6','Nakita natong tanan ang agay<br/>Diha’s iglesia.<br/>Mas lalum, habog, S’yang kinabuhi<br/>Magtubo kita.<br/>Karon ang iglesia,<br/>Mao ra si Cristo.<br/>Wad-ong kaugalingon,<br/>Ang Lawas patuboon.<br/>',NULL,19261,6);
INSERT INTO stanza VALUES('CB1240','7','Makitang pagtukod sa iglesia,<br/>Ning paagiha:<br/>Si Cristo atong sination gyud—<br/>Bugtong paagi.<br/>Tukora na kami,<br/>Sa among pagtubo,<br/>Mga tawo unta mi<br/>Sa bag-ong Jerusalem.<br/>',NULL,19262,7);
INSERT INTO stanza VALUES('CB1240','8','Di madugay balikan ni Jesus,<br/>Pangasaw-onon.<br/>Nangandam kitang tanan’s iglesia,<br/>Nga mahimaya.<br/>Baliki na kami,<br/>Ampo namo karon.<br/>Daygon Ka sa dayon,<br/>O baliki na kami!<br/>',NULL,19263,8);
INSERT INTO stanza VALUES('CB1246','1','Nitugyang sundong mga iglesia<br/>Diha’s pagkausa;<br/>Sundong lihok N’ya’s mga iglesia,<br/>Kita magkausa.<br/>',NULL,19264,1);
INSERT INTO stanza VALUES('CB1246','chorus','Sundon ang Espiritu,<br/>Uban sa kayano.<br/>Nia dinhi si Jesus,<br/>Hingpit S’yang mosunod!<br/>',NULL,19265,2);
INSERT INTO stanza VALUES('CB1246','2','Nitugyang mosunod sa nisunod,<br/>Tinu’d ming nakat-on;<br/>Di gyud magtinguha nga mangulo,<br/>Liso’s Espiritu.<br/>',NULL,19266,3);
INSERT INTO stanza VALUES('CB1246','3','Nitugyang mosunod’s tunob’s panon,<br/>Kay na’ng Magbalantay.<br/>Jesus nanguna’s mga iglesia,<br/>Didto namulong S’ya.<br/>',NULL,19267,4);
INSERT INTO stanza VALUES('CB1246','4','Nitugyan mi Nimo’s kaugalingon,<br/>Dili gyud mosimang;<br/>Asa nganing Cordero, adto mi,<br/>Bisan pag unsaon.<br/>',NULL,19268,5);
INSERT INTO stanza VALUES('CB1246','5','Nitugyang mosulod’s gingharian,<br/>Sa kombira’s kasal;<br/>Paglutos, pagsulay o pag-antus,<br/>Di kapugong namo.<br/>',NULL,19269,6);
INSERT INTO stanza VALUES('CB1246','6','Gusto’s Cristo nga may magsusunod<br/>Nga kasultian N’ya;<br/>“Kini nakakita’s Akong tuyo,<br/>Hingpit nga nisunod!”<br/>',NULL,19270,7);
INSERT INTO stanza VALUES('CB1248','1','Nanumpa si David,<br/>“Di ko mosulod’s balay,<br/>O sa higdaanan,<br/>O mahikatulog ba,<br/>Kondi’ makakita’g dapit,<br/>Alang Mo, Ginoo.“<br/>Nagtinguha ang atong Dios,<br/>Ug balayng kapuy-an.<br/>',NULL,19271,1);
INSERT INTO stanza VALUES('CB1248','2','Pagkabuta nato,<br/>Natakpan’s atoa ra;<br/>Samtang balay sa Dios<br/>Anaa’s kaawaaw—<br/>Manungas tag mangahoy,<br/>Ug itukod’s balay,<br/>Di moingon nga “Ugma na!“<br/>Karon panahon na!<br/>',NULL,19272,2);
INSERT INTO stanza VALUES('CB1248','3','Ning mga adlawa,<br/>Magdasig Ka’s pagtukod,<br/>Sama’s adlawng David—<br/>May salin nga mobuhat<br/>Andam motukod’s balay Mo,<br/>Bulahan nga sugo!<br/>Tinguha Mo, amoa sab—<br/>Nia, ug magtukod.<br/>',NULL,19273,3);
INSERT INTO stanza VALUES('CB1248','4','Sa mga gitawag<br/>Ibutang ang pagtagad<br/>Alang sa pagtukod—<br/>Panahon ni’s pangandam;<br/>Ang Hades di gyud modaug’s<br/>Iglesiang natukod!<br/>Pagkadiyutay’s magtutukod—<br/>Tukora, Ginoo!<br/>(Sublia ang katapusang upat ka linya)<br/>',NULL,19274,4);
INSERT INTO stanza VALUES('CB1251','1','Nia mi’s Jerusalem,<br/>Wa na mi’s Babilonia,<br/>Karon nagkahiusa,<br/>O himaya sa Dios!<br/>Pagtulon-an, opinyon,<br/>Amo nang gibiyaan,<br/>Espiritu ug kalag<br/>Mahibalong mobulag.<br/>',NULL,19275,1);
INSERT INTO stanza VALUES('CB1251','chorus','Hallelujah! Hallelujah!<br/>Kami nagkahiusa,<br/>Alang’s balay’s Ginoo,<br/>Hallelujah! Hallelujah!<br/>Nagkinabuhi na’s iglesia lokal!<br/>',NULL,19276,2);
INSERT INTO stanza VALUES('CB1251','2','Kin’hanglang sacerdote,<br/>Sa Iyang pahiuli—<br/>Kadtong nabuhi Niya,<br/>O himaya sa Dios!<br/>Gisuropan’s Ginoo,<br/>May ganti silang Cristo.<br/>Makatukod ni sila<br/>Karon’s iglesia lokal.<br/>',NULL,19277,3);
INSERT INTO stanza VALUES('CB1251','3','Makitang pagkahari<br/>May diosnong pagbulot-an—<br/>Mosugot ta niini,<br/>O himaya sa Dios!<br/>Magpasakop gyud kita<br/>Sa Espiritu Niya—<br/>Alang sa kaayohan<br/>Karon’s iglesia lokal.<br/>',NULL,19278,4);
INSERT INTO stanza VALUES('CB1251','4','Magbaton ug halaran,<br/>Nga kahalaran’s tanan.<br/>Patyong halad-sinunog,<br/>O himaya sa Dios!<br/>Di ni nato lalisan,<br/>Hugot alang’s iglesia,<br/>Ibton ’tong makadaut<br/>Karon’s iglesia lokal.<br/>',NULL,19279,5);
INSERT INTO stanza VALUES('CB1251','5','Patuk’ranan nabutang—<br/>Pagkahimaya gayud!<br/>Nalipay kitang tanan,<br/>O himaya sa Dios!<br/>Isinggit sa makusog—<br/>Nga sa layo madungog,<br/>Kaaway ta mosibog,<br/>Karon’s iglesia lokal.<br/>',NULL,19280,6);
INSERT INTO stanza VALUES('CB1252','1','Sa Babilonia, binihag kita,<br/>Espiritu ta gipukaw N’ya!<br/>Nagtibulaag, way pagkausa,<br/>Espiritu ta gipukaw N’ya!<br/>Gipukaw N’ya!<br/>Gipukaw ang espiritu ta!<br/>',NULL,19281,1);
INSERT INTO stanza VALUES('CB1252','2','Sa Babilonia daghan ang sekta<br/>Sa pagkabahin mamangon ta!<br/>Di kini m’oy hustong sukaranan,<br/>Sa pagkabahin mamangon ta!<br/>Bangon! Bangon!<br/>Sa pagkabahin mamangon ta!<br/>',NULL,19282,2);
INSERT INTO stanza VALUES('CB1252','3','Manguli kita sa Jerusalem,<br/>Manungas ta kay nag-uban S’ya!<br/>Ngadto’s sukaranan’s pagkausa,<br/>Manungas ta kay nag-uban S’ya!<br/>Manungas ta!<br/>Kay nag-uban S’ya, manungas ta!<br/>',NULL,19283,3);
INSERT INTO stanza VALUES('CB1252','4','Mga sudlanang puno ug Cristo,<br/>Tanan dad-on sab gayud nato!<br/>Ngadto’s iglesia, pagbuot sa Dios,<br/>Ang mga sudlanan dad-on ta!<br/>Dad-on! Dad-on!<br/>Ang mga sudlanan dad-on ta!<br/>',NULL,19284,4);
INSERT INTO stanza VALUES('CB1252','5','Sa Jerusalem, pinili sa Dios,<br/>Tukoron ta ang templo Niya!<br/>Magsilbe uban’s mga balaan,<br/>Tukoron ta ang templo Niya!<br/>Tukoron ta!<br/>Tukoron ta ang templo Niya!<br/>',NULL,19285,5);
INSERT INTO stanza VALUES('CB1254','1','Panahon na gyud karon pagtukod sa templo,<br/>Tanang kaiglesiahan Iya mang ayohon.<br/>Dili kini panahon sa kaugalingon;<br/>Samtang ang balay sa Dios naawaaw!<br/>',NULL,19286,1);
INSERT INTO stanza VALUES('CB1254','chorus','Magmalig-on sa pagtukod karon,<br/>Ang Ginoo uban nato, sa himaya N’ya pun-on!<br/>Magmalig-on, usahan’s pagtukod,<br/>Aron makita sa nasud ang templo’s Ginoo.<br/>',NULL,19287,2);
INSERT INTO stanza VALUES('CB1254','2','Si Jehova nag-ingon: Gawi mo susiha,<br/>Daghan ka ug gipugas, gamay ra’g ani ka,<br/>Tumungas ngadto’s bukid, sa kahoy manguha,<br/>Itukod’s Akong balay sa himaya.<br/>',NULL,19288,3);
INSERT INTO stanza VALUES('CB1254','3','Sacerdoteng tinawag, sa Dios mosugot gyud,<br/>Pasagding biaybiay, kay S’ya uban nato,<br/>Magmadasigon gayud sa buhat’s pagtukod,<br/>Iampong matag usa mangako gyud.<br/>',NULL,19289,4);
INSERT INTO stanza VALUES('CB1254','4','Si Jehova nag-ingon, Templo Akong pun-on<br/>Sa himayang labaw pa sa kanhing panahon!<br/>Tinguha’s mga nasud ipasundayag na,<br/>Himaya uban N’ya hangtud gyud’s dayon.<br/>',NULL,19290,5);
INSERT INTO stanza VALUES('CB1255','1','Alang ta’s pagpahiuli’s<br/>Iglesia lokal.<br/>Alang ta’s pagpahiuli<br/>Sa syudad ug yuta.<br/>Nagbarug sa pagkausa<br/>Usa’s Ginoo,<br/>Gitukod nato ang templo’s<br/>Atong Ginoo.<br/>',NULL,19291,1);
INSERT INTO stanza VALUES('CB1255','chorus','Alang’s Ginoo,<br/>Alang’s Ginoo,<br/>Alang ta’s pagpahiuli N’ya!<br/>Alang’s Ginoo,<br/>Alang’s Ginoo,<br/>Alang’s pagpahiuli N’ya!<br/>',NULL,19292,2);
INSERT INTO stanza VALUES('CB1255','2','Alang ta’s pagpahiuli,<br/>Gimahal kini;<br/>Kon gamitong espiritu,<br/>Tin-aw’g panan-awon.<br/>Natumba nang Babilonia,<br/>Yawa gitambog,<br/>Iglesia lokal natukod,<br/>Sa sukaranan.<br/>',NULL,19293,3);
INSERT INTO stanza VALUES('CB1257','1','Nakita ba’s syudad sila,<br/>Nagtigum’s sukaranan?<br/>Sila bulawang tangkawan,<br/>Sa Ginoo puy-anan.<br/>',NULL,19294,1);
INSERT INTO stanza VALUES('CB1257','chorus','Iglesia lokal nga pinili sa Dios,<br/>Mga balaan nausa!<br/>Iglesia lokal nga pinili sa Dios,<br/>Mga balaan nausa!<br/>',NULL,19295,2);
INSERT INTO stanza VALUES('CB1257','2','Nakita mo ba sa tigum,<br/>Nagpatugbaw sa tingog?<br/>Nag-ambit tanang igsoon,<br/>Nagpadako’s Ginoo!<br/>',NULL,19296,3);
INSERT INTO stanza VALUES('CB1257','3','Ang tanan nag-ampo-basa,<br/>Nihanggap’s buhing Pulong;<br/>Ampo, dayeg, inom, kaon,<br/>Nagpahimulos sila!<br/>',NULL,19297,4);
INSERT INTO stanza VALUES('CB1257','4','Nagtawag “Ginoong Jesus!“<br/>Sa ngalang gihigugma;<br/>Naglabing kalipay nila,<br/>Sa pagtawag Kaniya.<br/>',NULL,19298,5);
INSERT INTO stanza VALUES('CB1257','5','Nadungog bang hallelujah?<br/>Daw lanog sa dalugdog;<br/>Hallelujah! Hallelujah!<br/>Ang yawa gitambog na!<br/>',NULL,19299,6);
INSERT INTO stanza VALUES('CB1257','6','Paglalin nakita mo ba,<br/>Daygon S’ya ning lihoka<br/>Sa iglesia’s matag syudad,<br/>Aron mobalik na S’ya.<br/>',NULL,19300,7);
INSERT INTO stanza VALUES('CB1257','7','Mobalik na ang Ginoo<br/>Alang gyud sa iglesia;<br/>Sa iglesia giandam N’ya<br/>Ang Pangasaw-onon N’ya.<br/>',NULL,19301,8);
INSERT INTO stanza VALUES('CB1257','chorus','Mahimayaon kini nga iglesia,<br/>Way mansa, kunot, ug buling,<br/>Mahimayaon kini nga iglesia,<br/>Puno’s himaya’s Ginoo!<br/>',NULL,19302,9);
INSERT INTO stanza VALUES('CB1260','1','Na’s iglesia lokal, pinili’s Dios;<br/>Cristo m’oy kinabuhi<br/>Ug panalangin. (Hallelujah!)<br/>“Sa espiritu ug sukaranan“<br/>Kaaway dag-on nato,<br/>Ipadangat ang gingharian.<br/>',NULL,19303,1);
INSERT INTO stanza VALUES('CB1266','1','Magmainiton gyud kita,<br/>Liso gyud sa espiritu,<br/>Mausa’s dayong tuyo N’ya’s<br/>espiritu;<br/>Sa sukaranan sa lokal,<br/>Pagkausa i’dayag—<br/>Daghang bahin, Lawas usa,<br/>Cristo’y Ulo.<br/>',NULL,19304,1);
INSERT INTO stanza VALUES('CB1266','chorus','Cristo ug iglesia,<br/>Cristo ug iglesia,<br/>Atong realidad ug kinabuhi,<br/>Hallelujah, Hallelujah!<br/>Ihalad na namong tanan<br/>Aron matukod ang Lawas<br/>Ug matukod sa gugma.<br/>',NULL,19305,2);
INSERT INTO stanza VALUES('CB1266','2','Mohanggap, hanggap gyud kita,<br/>Bag-ong kinabuhiy dawat,<br/>Matransporma gikan’s daan<br/>ngadto’s bag-o;<br/>Igula da’ng kinabuhi,<br/>Hanggapong bag-o’g ’kausa,<br/>Gihanggap si Jesus, gihanggap<br/>tang kinabuhi.<br/>',NULL,19306,3);
INSERT INTO stanza VALUES('CB1273','1','Gitawag na tang Cristo,<br/>Gitawag pa gyug usab.<br/>Moamen sa tawag N’ya!<br/>Dag-on ta!<br/>Kay iglesia nahulog<br/>Abi’g nahibawo’s tanan,<br/>Apan way kinabuhi;<br/>Dag-on ta!<br/>',NULL,19307,1);
INSERT INTO stanza VALUES('CB1273','chorus','Dag-on ta! Dag-on ta!<br/>Dag-ong nadaut nga<br/>Cristianidad!<br/>Buhat mo ipadaplin,<br/>Tanan nga makabahin;<br/>Kan-on lang ang Ginoo—<br/>Dag-on ta!<br/>',NULL,19308,2);
INSERT INTO stanza VALUES('CB1273','2','Palad sa tawo mokaon,<br/>Pahiuli’s Ginoo;<br/>Mopilde ni’s kaaway—<br/>Dag-on ta!<br/>Biyaing pakigbisug,<br/>Ang buhing kahoy kan-a,<br/>Sa pagkaon modaug—<br/>Dag-on ta!<br/>',NULL,19309,3);
INSERT INTO stanza VALUES('CB1273','3','Pagtulon-an dili gyud<br/>Makatransporma’s kalag,<br/>Pagkaon kang Cristo ra—<br/>Dag-on ta!<br/>Sa pagkaon modaug,<br/>Sa tinagsa’g tigum ba,<br/>Kompletong kalan-on S’ya,<br/>Dag-on ta!<br/>',NULL,19310,4);
INSERT INTO stanza VALUES('CB1273','4','Pagkaon magpalugwa<br/>Sa anak nga lalaki;<br/>Magpabalik’s Ginoo—<br/>Dag-on ta!<br/>Matagbo unta nato,<br/>Ang tinguha’s Ginoo,<br/>Pangasaw-onon kita—<br/>Dag-on ta!<br/>',NULL,19311,5);
INSERT INTO stanza VALUES('CB1278','1','Sa iglesia dunay gugma alang nimo,<br/>Gugmang labing lunsay, lalum, malomo,<br/>Nganong nanghupaw kag nag-inusara,<br/>Nga dagaya mang sangkap sa iglesia.<br/>',NULL,19312,1);
INSERT INTO stanza VALUES('CB1278','2','Diha sa iglesia dunay kinabuhi,<br/>Init sama’s Adlaw, tam-is daw yamog;<br/>Nganong mahadlok ka ug mabalaka,<br/>Nga inatiman man ang gilukat N’ya?<br/>',NULL,19313,2);
INSERT INTO stanza VALUES('CB1278','3','Diha sa iglesia may buhat naghulat;<br/>Bisan mga anghel gustong moapil;<br/>Nganong magtinapol ning dakong buhat,<br/>Iglesia nangin’hanglan man’s tabang mo.<br/>',NULL,19314,3);
INSERT INTO stanza VALUES('CB1278','4','Diha sa iglesia may dapit ka gayud;<br/>Dapit masanagon ug malinawon;<br/>Nganong naglaag ka’s panawng malaay?<br/>Nga iglesia imo mang panimalay.<br/>',NULL,19315,4);
INSERT INTO stanza VALUES('CB1282','1','Padayong magmartsa sa Espiritu karon;<br/>Hallelujah! Padayon kita.<br/>Padayong magmartsa sa Espiritu karon;<br/>Hallelujah! Padayon kita.<br/>Makita’s iglesia<br/>Pahiuli N’ya,<br/>Espiritu pito ka pilo.<br/>Masayran’s tawo,<br/>Bisan asa kita,<br/>Panahon ta S’ya nagpadayon!<br/>',NULL,19316,1);
INSERT INTO stanza VALUES('CB1283','1','Away alang kang Jesus!<br/>Ayaw’g kahadlok’s kaaway N’ya!<br/>Ikinabuhi Siya,<br/>Tumban mo ang kaaway N’ya!<br/>Iampong iglesia malig-on,<br/>Mga balaan magpadayon,<br/>Bag-ong tawo makig-away,<br/>Magtuman sa plano N’ya!<br/>(Daygon! Hallelujah!)<br/>',NULL,19317,1);
INSERT INTO stanza VALUES('CB1287','1','Ang yuta nga hatag sa Dios ilogon ta;<br/>Mabuhi ta sa kadagaya N’ya:<br/>Sinangkapan kita’s tanang kinahanglan—<br/>Dugo, Pulong, Esp’ritu, iglesia.<br/>',NULL,19318,1);
INSERT INTO stanza VALUES('CB1287','chorus','(Mga sister moawit)<br/>Ilogon ta, mga igsoon!<br/>Ang yuta nga hatag sa Dios.<br/>Magmakusganon, kay mailog ta<br/>Ang yutang mahimayaon!<br/>',NULL,19319,2);
INSERT INTO stanza VALUES('CB1287','chorus','(Mga brother moawit)<br/>Ilogon ta, mga igsoon,<br/>Mamati gyud ning butanga,<br/>Ginoo tua sa unahan ta,<br/>Naghatag’s tanang kin’hanglan!<br/>',NULL,19320,3);
INSERT INTO stanza VALUES('CB1287','2','May dugo ta! Si Cristo maong halad ta,<br/>Siyang nagtugyan pagtagbaw sa Dios;<br/>May kaisug moduol’s trono sa grasya,<br/>Tibu’k adlaw i-apply ang dugo.<br/>',NULL,19321,4);
INSERT INTO stanza VALUES('CB1287','3','May Pulong ta! Pulong inadlawng kalan-on;<br/>Saktan’s pagtoo, moingon “Amen!“<br/>Kini tibu’k adlaw kanato mamulong,<br/>Magdumala’s pagkinabuhi ta.<br/>',NULL,19322,5);
INSERT INTO stanza VALUES('CB1287','4','Espiritu sa realidad ato na,<br/>May Kaugalingon nga pagbati S’ya;<br/>Nagpuyo ug nagtudlo sa atong sulod,<br/>Naggiya nato’s tanang matuod.<br/>',NULL,19323,6);
INSERT INTO stanza VALUES('CB1287','5','May iglesia! magbaton gyud ang tanan ning<br/>Kahupnganan sa ’yang realidad;<br/>Cristo nga naglangkob-sa-tanan angko-non,<br/>Mahimo Siyang tanan kanato.<br/>',NULL,19324,7);
INSERT INTO stanza VALUES('CB1289','1','Gidaug na sa Ginoo ang kaaway!<br/>Isinggit ta ang lanog sa layo!<br/>Ang dugo N’ya naghatag ug kadaugan!<br/>Di madugay Mananaug nia na.<br/>',NULL,19325,1);
INSERT INTO stanza VALUES('CB1289','chorus','(Mga sister moawit)<br/>Gidaug na! Mga igsoon,<br/>Gidaug na! Isinggit ta!<br/>Kadaugan ta gikan sa Sion,<br/>Ang yuta’s pagdayeg pun-on.<br/>',NULL,19326,2);
INSERT INTO stanza VALUES('CB1289','chorus','(Mga brother moawit)<br/>Gidaug na! Mga igsoon,<br/>Gamhanang buhat tapos na!<br/>Ginoo nibuntog alang nato—<br/>Kalipayng dayon ato na.<br/>',NULL,19327,3);
INSERT INTO stanza VALUES('CB1289','2','Gidaug na! Kaaway ta gibuntog na.<br/>Pulong sa Dios gipamatud-an ta.<br/>Nia ni’ning kinabuhi’g kagawasan,<br/>Sa Pulong N’ya kaaway ta suklan.<br/>',NULL,19328,4);
INSERT INTO stanza VALUES('CB1289','3','Gidaug na! Yawa nahimong tumbanan,<br/>Kay way kahadlok bisag mamatay;<br/>Isinggit ta, “Ikaw among kadaugan!“<br/>Dios daygon’s espiritu ug kusog.<br/>',NULL,19329,5);
INSERT INTO stanza VALUES('CB1293','1','O ako tawo—<br/>Ang kahulogan’s uniberso;<br/>Oo, tawo—<br/>Ang kahulogan’s uniberso.<br/>Binuhat’s Dios,<br/>Bililhon gyud,<br/>Akoy sentro ug kahulogan’s uniberso.<br/>',NULL,19330,1);
INSERT INTO stanza VALUES('CB1293','2','Ug si Cristo—<br/>Kahulogan’s kinabuhi ko;<br/>S’ya nabuhi—<br/>Kahulogan’s kinabuhi ko.<br/>Nia nako,<br/>Akong tanan;<br/>S’yang kahuloga’g realidad’s kinabuhi ko.<br/>',NULL,19331,2);
INSERT INTO stanza VALUES('CB1293','3','Ang iglesia—<br/>Pagpadayag ni Cristo karon;<br/>S’ya si Cristo—<br/>Pagpadayag ni Cristo karon.<br/>Tawong hinugpong<br/>S’yang magtuman [tibuok yuta.<br/>Sa plano’s Dios—tawo magbuot’s<br/>',NULL,19332,3);
INSERT INTO stanza VALUES('CB1293','4','Ang iglesia—<br/>Sa lokal, tinu’d pamilya ta;<br/>Ang iglesia—<br/>Sa lokal, tinu’d pamilya ta.<br/>M’oy paagi’s<br/>Pagkabuhi—<br/>Kaon-inom N’ya, iglesia lokal matukod.<br/>',NULL,19333,4);
INSERT INTO stanza VALUES('CB1293','5','Buhaton ta—<br/>Ni’ni suginlang kalibutan;<br/>Buhaton ta—<br/>Ni’ni suginlang kalibutan.<br/>Tudloan ta—<br/>Silang tanan.<br/>Manlakaw, isangyawng balita’s tibu’k yuta.<br/>',NULL,19334,5);
INSERT INTO stanza VALUES('CB1302','1','Nia na ang ilhanan,<br/>Duol nang katapusan;<br/>Kita karon mangandam<br/>Si Jesus mobalik na!<br/>',NULL,19335,1);
INSERT INTO stanza VALUES('CB1302','chorus','Mobalik na, mobalik na,<br/>Di na gyud S’ya magdugay,<br/>Tungang gabi’ manawag S’ya,<br/>Mobalik na, mobalik na,<br/>Maalamong ulay, mangandam ta!<br/>Si Jesus mobalik na!<br/>',NULL,19336,2);
INSERT INTO stanza VALUES('CB1302','2','Ang kalag ta likayan,<br/>Si Jesus ray tutokan;<br/>Wala nay panahon pa—<br/>Si Jesus mobalik na!<br/>',NULL,19337,3);
INSERT INTO stanza VALUES('CB1302','3','Mga buangbuang man<br/>Kadtong dili mangandam’s<br/>Lana’s ilang sudlanan—<br/>Si Jesus mobalik na!<br/>',NULL,19338,4);
INSERT INTO stanza VALUES('CB1302','4','Di mag-usik’s panahon,<br/>Sa kalibutan karon;<br/>Magpapuno’s esp’ritu—<br/>Si Jesus mobalik na!<br/>',NULL,19339,5);
INSERT INTO stanza VALUES('CB1302','5','Mangadto ta Kaniya,<br/>Di lang hinlo ug suga,<br/>May lana pa nga dala—<br/>Si Jesus mobalik na!<br/>',NULL,19340,6);
INSERT INTO stanza VALUES('CB1302','6','Nagpaingon na Siya,<br/>Adlaw wa mo masayri;<br/>Pagtukaw’s presensya N’ya—<br/>Si Jesus mobalik na!<br/>',NULL,19341,7);
INSERT INTO stanza VALUES('CB1303','1','Duol nang gingharian’s Dios:<br/>Napulong ulay nangandam,<br/>Pagsugat sa Pamanhonon,<br/>Lima ra ang maalamon.<br/>Sila may dagayang lana,<br/>Apan buangbuang way da’;<br/>Panahon wala gamita,<br/>Pagpamalit unta’s lana.<br/>',NULL,19342,1);
INSERT INTO stanza VALUES('CB1303','2','Klaro ang Imong mensahe:<br/>Anhion Mong maalamon,<br/>Nga namalit’s lana karon,<br/>Ug nagkuha’s tanang babag.<br/>Kadtong kalag natransporma,<br/>Ug may dagaya nga lana,<br/>Wala mahigugma’s kalag—<br/>Maghari gyud’s gingharian.<br/>',NULL,19343,2);
INSERT INTO stanza VALUES('CB1303','3','Hinloan namo ang suga,<br/>’Tawag Nimo adlaw-adlaw.<br/>Ang espiritu bansayon,<br/>Tanang kadaan sunogon.<br/>May lalum pang kinahanglan,<br/>Magtubong kamatuoran,<br/>Hangtud magbalay sa sulod,<br/>Lana moawas’ sudlanan.<br/>',NULL,19344,3);
INSERT INTO stanza VALUES('CB1303','4','Nakitang kangitngit karon,<br/>Nasayran duol nang takna.<br/>Ginoo paturoki mi’s<br/>Kahadlok nga maabtan Mo.<br/>Aron tubsong matag gutlo,<br/>Mag-ampo-basa sa Pulong,<br/>Tun-an tanang pagtulon-an,<br/>Sa takna kami mangandam.<br/>',NULL,19345,4);
INSERT INTO stanza VALUES('CB1303','5','Bulahan, Ginoo, kadtong<br/>Magpadangat’s gingharian,<br/>Magpahari Nimo’s tanan,<br/>Magpadayag’s Imong gahum!<br/>Bulahang naa’s kombira,<br/>Mausa Ka’s Asawahon!<br/>Himoa ming maalamon,<br/>Magpabilin’s presensya Mo.<br/>',NULL,19346,5);
INSERT INTO stanza VALUES('CB1308','1','May lana ta’s suga—nagsiga ta!<br/>May lana ta’s suga karon!<br/>Ginoo, palisoa’s esp’ritu,<br/>Palisoa gyud mi sa dayon.<br/>O Ginoo, Hallelujah!<br/>Magsiga gyud mi adlaw-adlaw!<br/>O Ginoo, Hallelujah!<br/>Palisoa mi’s dayon!<br/>',NULL,19347,1);
INSERT INTO stanza VALUES('CB1308','2','Sudlanan ta nagkin’hangla’g lana;<br/>Naa gyuy pundong sangkap ta.<br/>Busa sudlanan ato gyung pun-on<br/>Aron suga di gyud mapalong.<br/>Pun-a, Jesus! Pun-a, Jesus!<br/>Matag gutlo pun-an mi Nimo!<br/>Pun-a, Jesus! Pun-a, Jesus!<br/>Pun-a mi’s realidad!<br/>',NULL,19348,2);
INSERT INTO stanza VALUES('CB1308','3','Magsiga hangtud makita ta S’ya,<br/>Hangtud nga S’ya moanhi na.<br/>Mosulod dayon’s kasal uban N’ya,<br/>Masanagong magsiga’s dayon.<br/>Umari Ka, O Ginoo!<br/>Nia, puno mi ug nagsiga!<br/>Umari Ka, O Ginoo!<br/>Kalipaying Asawa!<br/>',NULL,19349,3);
INSERT INTO stanza VALUES('CB1315','1','Magkalipay! Di na magdugay,<br/>Ang atong Pamanhonon,<br/>Kalipay kaslon kita Niya,<br/>Sa pag-awit pun-on ta.<br/>',NULL,19350,1);
INSERT INTO stanza VALUES('CB1315','chorus','O adlaw nga mahimayaon,<br/>Inig-anhi ni Cristo:<br/>Sudlanang puno ug nagsiga,<br/>Sugatong pagbalik N’ya.<br/>Magkalipay! Di na magdugay<br/>Ang atong Pamanhonon!<br/>Kalipay kaslon kita Niya<br/>Sa pag-awit pun-on ta.<br/>',NULL,19351,2);
INSERT INTO stanza VALUES('CB1315','2','Bakwion ta ang matag gutlo,<br/>Mamalit pa ug lana,<br/>Sudlanan pun-on nato’s lana,<br/>Sa di pa moabot S’ya.<br/>',NULL,19352,3);
INSERT INTO stanza VALUES('CB1315','3','Unsang kalipay pagpangandam<br/>Sa kasal ta’s Ginoo,<br/>Niambit bisan’s kasakitan,<br/>Aron ta magantihan!<br/>',NULL,19353,4);
INSERT INTO stanza VALUES('CB1315','4','Unsang paglalin, pagkalipay,<br/>Sa adlaw sa kasal ta;<br/>Usa ka libo ka tuig ta<br/>Mag-uban N’ya’s kombira!<br/>',NULL,19354,5);
INSERT INTO stanza VALUES('CB1325','1','Dios sa dayon dunay tuyo,<br/>Sa kanhing eternidad;<br/>Ngadto unya’s eternidad,<br/>Panahon naa’s tunga.<br/>Kay ni’ni na’ng kahikayan,<br/>Magbuhat S’ya’s panahon;<br/>Magpapanaw ta’s panahon—<br/>Alang ta’s eternidad.<br/>',NULL,19355,1);
INSERT INTO stanza VALUES('CB1325','2','Katawhan buot maangkon,<br/>Matukod sa ’yang plano,<br/>Masagol, magtambayayong,<br/>Sudlanan N’ya—bag-ong tawo.<br/>Mosulod S’ya ning sudlanan,<br/>Uban’s ’yang kinaiya,<br/>Masagol S’ya’s espiritu,<br/>Alang’s nahimut-an N’ya.<br/>',NULL,19356,2);
INSERT INTO stanza VALUES('CB1325','3','Tulong direksyong nagbuhat<br/>Alang sa Iyang plano;<br/>Ingon nga Tulo-usang Dios,<br/>Gipaambit S’ya nato!<br/>Kabuhatan maoy dapit—<br/>Langit, yuta alang’s plano;<br/>Tungod ni’ni, kita dunay<br/>Lawas, kalag, espiritu.<br/>',NULL,19357,3);
INSERT INTO stanza VALUES('CB1325','4','Espiritu ta ang sentro,<br/>Sa plano gayud sa Dios:<br/>Pagtawag sa ngalang Jesus,<br/>Mausa’s espiritu.<br/>Gikan’s sentro sa palibot,<br/>Suropang matag bahin;<br/>Magbag-o sa hunahuna,<br/>Pagbati ug pagbuot.<br/>',NULL,19358,4);
INSERT INTO stanza VALUES('CB1325','5','Sa kinabuhi matukod,<br/>Mausa diha’s gugma;<br/>Plano’s Dios gituman karon,<br/>Nasugdan ’yang humanon.<br/>Ginoo, patuboa pa<br/>Kaugalingon Mo’s sulod,<br/>Hinugpong nga sudlanan Mo,<br/>Mapuno kami Nimo.<br/>',NULL,19359,5);
INSERT INTO stanza VALUES('CB1325','6','Produkto Mo’g katumanan,<br/>Iglesia mahimaya,<br/>Pagkahingpit sa tuyo Mo,<br/>Nga giplano nang daan.<br/>Dios may hinugpong sudlanan<br/>Sa tanan N’yang himaya;<br/>Hingpit kami alang ni’ni,<br/>Tumong Mo kab-ota na.<br/>',NULL,19360,6);
INSERT INTO stanza VALUES('CB1327','1','Kanhi gihidlaw ko’s tubod,<br/>Nga kanako makatagbaw,<br/>Apan tubod nga naimnan,<br/>Naghatag’s labawng kauhaw.<br/>Napalgan ko Siya,<br/>Gikuhang kauhaw,<br/>Nahimong tubod sa sulod<br/>Sa buhi nga tubig.<br/>Giinom S’ya!<br/>Jesus, kinabuhi karon,<br/>Jesus, kinabuhi ko;<br/>Hingpit ko nga natagbaw,<br/>Jesus kinabuhi ko.<br/>',NULL,19361,1);
INSERT INTO stanza VALUES('CB1327','2','Tubod human matilawan,<br/>Gihidlaw’s dapit’s tuboran;<br/>Panan-awon nakita’s bungtod,<br/>Sa tigum sa Jerusalem.<br/>Napalgan N’ya ako,<br/>Gidala’s iglesia,<br/>Kalipay ko nidagaya,<br/>Wa na ko mangita.<br/>Hallelujah!<br/>Jesus, kinabuhi karon,<br/>Jesus, kinabuhi ko;<br/>Hingpit ko nga natagbaw,<br/>Jesus, kinabuhi ko.<br/>',NULL,19362,2);
INSERT INTO stanza VALUES('CB1327','3','Ay na’g laag ug paningkamot,<br/>Hasol lang na ug way pulos;<br/>Tumoo na, ug tawga S’ya,<br/>Kay S’ya mosulod kanimo!<br/>Ug mapalgan mo S’ya.<br/>Tawga lang ngalan N’ya,<br/>Madugtong ka, mausa N’ya—<br/>Ug mausab ka na.<br/>Mausab gyud!<br/>Jesus, kinabuhi karon,<br/>Jesus, kinabuhi ko;<br/>Hingpit ko nga natagbaw,<br/>Jesus, kinabuhi ko.<br/>',NULL,19363,3);
INSERT INTO stanza VALUES('CB1330','1','“Tanan naandam,” gidapit ka!<br/>Ang talad puno’s kalan-on;<br/>Ang gigutom ug gikapoy,<br/>Umari kay ’yang busgon.<br/>',NULL,19364,1);
INSERT INTO stanza VALUES('CB1330','chorus','Paminawang pagdapit,<br/>Bisan kinsay gusto;<br/>Kaluwasan nga hingpit<br/>Sa tanang modawat.<br/>',NULL,19365,2);
INSERT INTO stanza VALUES('CB1330','2','“Tanan naandam,” gidapit ka!<br/>Samtang bukas pang pultahan;<br/>May dapit nga gitagana,<br/>Alang gayud kanimo.<br/>',NULL,19366,3);
INSERT INTO stanza VALUES('CB1330','3','“Tanan naandam,” gidapit ka!<br/>Samtang S’ya naghulat nimo;<br/>Karon maoy higayon mo,<br/>Ugma di maseguro.<br/>',NULL,19367,4);
INSERT INTO stanza VALUES('CB1330','4','“Tanan naandam,” gidapit ka!<br/>B’yai tanang kabalaka;<br/>Mangaon ta’s Cristo sa Dios,<br/>Kinabuhing dayon S’ya.<br/>',NULL,19368,5);
INSERT INTO stanza VALUES('CB1335','1','Dako ang Dios, ug angay gyung daygon,<br/>Sa syudad sa atong Dios,<br/>Sa bukid’s Iyang kabalaan.<br/>Matahum gyud sa gitas-on, kalipay sa yuta.<br/>Bukid sa Sion naa’s amihanan,<br/>Syudad sa dakong Hari.<br/>Bukid sa Sion naa’s amihanan,<br/>Syudad sa dakong Hari.<br/>',NULL,19369,1);
INSERT INTO stanza VALUES('CB1340','1','Busa magtimba ta sa tubig,<br/>Sa atabay’s kaluwasan,<br/>Ug niadtong adlawa,<br/>Daygon S’ya!<br/>(Isubli ang upat ka estansa sa taas)<br/>Tawgong ngalan N’ya, Ipahayag Siya sa katawhan,<br/>Ngalan Niya ibayaw kanunay!<br/>Isinggit ta, mga lumulopyo sa Sion,<br/>Kay dako ang Balaan sa Israel nganhi kanato!<br/>',NULL,19370,1);
INSERT INTO stanza VALUES('CB1345','1','Kasingkasing kon iliso karon,<br/>Taptap mo kuhaon dayon,<br/>Busa iliso’s Ginoo karon,<br/>Ug taptap mo kuhaon dayon.<br/>Ginoo, Espiritu<br/>Ug hain nganing Espiritu<br/>May kagawasan—kagawasan!<br/>Kasingkasing mo iliso karon<br/>Taptap mo kuhaon dayon.<br/>',NULL,19371,1);
INSERT INTO stanza VALUES('CB1331','1','Tilawi ug makita nimo,<br/>Nga maayo gyud ang Ginoo.<br/>Maayo Siya alang nimo,<br/>Busa tilawi gyud ang Ginoo.<br/>',NULL,19372,1);
INSERT INTO stanza VALUES('CB1331','2','Tawga lang S’ya, O Ginoo,<br/>Ug mag-usab Siya kanimo;<br/>Hatagan ka’s dakong grasya,<br/>Busa tawga gyud ang Ginoo.<br/>',NULL,19373,2);
INSERT INTO stanza VALUES('CB1331','3','Gugmang tinuod mabati mo,<br/>Sulod sa kasingkasing mo;<br/>Agay gikan sa Dios mismo,<br/>Masayran gugmang matuod.<br/>',NULL,19374,3);
INSERT INTO stanza VALUES('CB1331','4','Dayga ang Dios nga kinabuhi,<br/>Nga naa na diha kanimo;<br/>Gibubo N’ya datong Cristo,<br/>Busa dayga ang Ginoo!<br/>',NULL,19375,4);
INSERT INTO stanza VALUES('CB1333','1','Unsang kalipay,<br/>Sa pagdawat ko kang Jesus,<br/>Gikuha N’ya ang tanan nga kangitngit<br/>Kasingkasing gihayagan.<br/>',NULL,19376,1);
INSERT INTO stanza VALUES('CB1333','2','Karon nagsugod’s<br/>Kinabuhi diha’s Anak.<br/>Nagpuli sa mga kawang nga damgo,<br/>Buhi S’yang niagay nako.<br/>',NULL,19377,2);
INSERT INTO stanza VALUES('CB1333','3','Liso Kaniya,<br/>Pun-on ko sa kinabuhi.<br/>Kini mahimo kong realidad;<br/>O hallelujah, nia S’ya!<br/>',NULL,19378,3);
INSERT INTO stanza VALUES('CB1333','4','Gihigugma Ka,<br/>Gibugto Mo ubang gugma.<br/>Wala akoy lain nga higugmaon<br/>Kinabuhi Ka sa dayon.<br/>',NULL,19379,4);
INSERT INTO stanza VALUES('CB1341','1',replace('Ug ang mga tinubos sa Ginoo,<br/>Manguli sila ngadto sa Sion;<br/>Manglakaw, mag-awit, singgit sa kalipay.<br/>Ug ang mga tinubos sa Ginoo,<br/>Manguli sila ngadto sa Sion;<br/>Manglakaw, mag-awit, singgit sa kalipay.\nSilang tanan may kasadya,<br/>Kasubo, pagbalata wala na.<br/>(Sublia ang unang tulo ka linya)<br/>','\n',char(10)),NULL,19380,1);
INSERT INTO stanza VALUES('NS1','1','God’s economy is to have God and man<br/>Incorporated as one—divine-human,<br/>To build up His Body—an organism,<br/>Which consummates the New Jerusalem.<br/>',NULL,19381,1);
INSERT INTO stanza VALUES('NS1','2','God the Father loves man and chooses man<br/>In eternity past, in His great plan,<br/>According to His purpose, and not of works<br/>But of Him, in the section of Jacob.<br/>',NULL,19382,2);
INSERT INTO stanza VALUES('NS1','3','God the Father calls man and justifies man<br/>In time, in the section of Abraham;<br/>That man may live by faith, know grace from within<br/>That man may live in fellowship with Him.<br/>',NULL,19383,3);
INSERT INTO stanza VALUES('NS1','4','God the Son gives man His rich inheritance,<br/>And a life enjoying His abundance,<br/>And a life in peace, totally without lack—<br/>Fully blessed, in the section of Isaac.<br/>',NULL,19384,4);
INSERT INTO stanza VALUES('NS1','5','God the Spirit transforms man and causes man<br/>To be mature in life, enabling man<br/>To bless and supply all, and rule o’er the earth,<br/>In the section of Jacob with Joseph.<br/>',NULL,19385,5);
INSERT INTO stanza VALUES('NS2','1','The goal of God’s complete salvation<br/>Is to make His redeemed people<br/>His dwelling place on earth<br/>That they may fellowship with God, serve God<br/>And be God’s holy people living a holy life<br/>Through the tabernacle with the offerings, and by the priests—<br/>All types of the all-inclusive Christ—<br/>To issue in the gaining of Christ as their mutual rest<br/>And enjoyment typified by the feasts.<br/>',NULL,19386,1);
INSERT INTO stanza VALUES('NS3','1','God has a dream, this is what He’s wanting.<br/>God has a dream, and we are part of it.<br/>God has a dream...that we may be one with Him.<br/>God has a dream...realized in you and me!<br/>God, you and me...a dwelling place to be.<br/>God in man, and man in God: one entity.<br/>Now, it’s my dream...my vision and life to be!<br/>God has a dream...realised in you and me!<br/>',NULL,19387,1);
INSERT INTO stanza VALUES('NS4','1','God wants His holy people to become His army;<br/>Rise up, all ages! March on for His testimony;<br/>Christ is our meaning of life, testimony and center,<br/>In everything He’s the way, the goal and the Leader.<br/>',NULL,19388,1);
INSERT INTO stanza VALUES('NS4','2','For God to gain His army, priesthood, and dwelling place,<br/>Defilement must be dealt with, that to Him we’d be chaste,<br/>Make us the same as You, Lord, truly righteous and holy,<br/>Meeting Your strict requirements, becoming Your army.<br/>',NULL,19389,2);
INSERT INTO stanza VALUES('NS4','3','In our journey to gain Christ—the good land giv’n by God,<br/>Hindrances and trials would come when we walk with the Lord,<br/>Through suff’rings we’d be humbled and in spirit contrite,<br/>And be exposed through testing, thus purged and purified.<br/>',NULL,19390,3);
INSERT INTO stanza VALUES('NS4','4','To inherit the good land, we must be renumbered;<br/>Make a willing vow to Him to fulfill His standard.<br/>For the Lord’s up-to-date move, let’s fight and pay the price,<br/>Enter and possess the land, our all-inclusive Christ!<br/>',NULL,19391,4);
INSERT INTO stanza VALUES('NS5','1','This unique truth the whole Bible unveils:<br/>Our God has put on humanity;<br/>Both God and man, as the Scripture reveals;<br/>Hallelujah unto eternity.<br/>',NULL,19392,1);
INSERT INTO stanza VALUES('NS5','chorus','Praise the Lord for Christ’s humanity!<br/>It’s central to God’s economy<br/>To produce a divine-human incorporation<br/>Which consummates the New Jerusalem.<br/>',NULL,19393,2);
INSERT INTO stanza VALUES('NS5','2','Old Testament portrays Christ as a Man,<br/>With four types showing His humanity:<br/>Seed of the woman, seed of Abraham,<br/>The seed of David, branch of Jesse.<br/>',NULL,19394,3);
INSERT INTO stanza VALUES('NS5','3','Christ as a Man in His humanity<br/>Visited Abraham, with Jacob fought,<br/>Met Joshua as Captain of God’s army,<br/>Foretold of Samson, Israel’s comfort.<br/>',NULL,19395,4);
INSERT INTO stanza VALUES('NS5','4','As Man of sorrows He lived, and was slain,<br/>Suffered, despised, our redemption to win.<br/>According to righteousness He will reign,<br/>There’ll be enjoyment and protection.<br/>',NULL,19396,5);
INSERT INTO stanza VALUES('NS5','5','Above the firmament, Christ is enthroned,<br/>Satan’s dominion is far, far below.<br/>Each measurement of God’s building He knows,<br/>In midst of Israel, His possession.<br/>',NULL,19397,6);
INSERT INTO stanza VALUES('NS5','6','Christ as a Man walked with Daniel’s three friends,<br/>In fiery trial appearing with them;<br/>Met Daniel’s need as a Man once again;<br/>He’s everything in God’s move as a Man.<br/>',NULL,19398,7);
INSERT INTO stanza VALUES('NS5','7','Though they dispersed, Christ was with Israel,<br/>Measured Jerus’lem to gain her in full;<br/>As Shoot of David, God’s temple He’ll build,<br/>He’ll be a Priest and o’er all nations rule.<br/>',NULL,19399,8);
INSERT INTO stanza VALUES('NS5','8','As Son of Man, He’s with Israel involved,<br/>With us as well: we His oneness enjoy;<br/>He’s stock of Israel exalted by God,<br/>He’ll gain the Kingdom, enemies destroy.<br/>',NULL,19400,9);
INSERT INTO stanza VALUES('NS5','9','Christ as revealed in the New Testament<br/>Came in the flesh; Son of Man now is He!<br/>Fulfillment of God’s economy,<br/>All carried out in Christ’s humanity.<br/>',NULL,19401,10);
INSERT INTO stanza VALUES('NS6','1','There is a great mystery,<br/>A wonderful story;<br/>For ages ’twas hidden,<br/>Now shown in His wisdom;<br/>’Tis a divine romance<br/>Of God and man in time;<br/>Beyond understanding,<br/>Yet seen in God’s speaking.<br/>',NULL,19402,1);
INSERT INTO stanza VALUES('NS6','chorus','God fell in love with man;<br/>For only God’s love can<br/>Make man just the same as He<br/>In life and in nature.<br/>We are His expression,<br/>His bride, His enlargement;<br/>Forever, together,<br/>As living, insep’rable as one couple<br/>Eternally.<br/>',NULL,19403,2);
INSERT INTO stanza VALUES('NS6','2','Though He was rejected<br/>By men who were blinded;<br/>His love is constraining,<br/>His heart still unchanging;<br/>Thus in incarnation<br/>Came He as salvation;<br/>His name is called Jesus,<br/>And He came to seek us.<br/>',NULL,19404,3);
INSERT INTO stanza VALUES('NS6','3','Though born as a sinner,<br/>His blood has redeemed me.<br/>He suffered on Calv’ry,<br/>Then raised up in glory,<br/>To regenerate me.<br/>Now joined in one spirit <br/>I love to enjoy Him,<br/>For I’ve been forgiven!<br/>',NULL,19405,4);
INSERT INTO stanza VALUES('NS6','4','His love is so tender,<br/>To Him I’ll surrender;<br/>His name is so precious,<br/>I gladly call, “Jesus!“<br/>His Person’s so charming,<br/>My heart ever winning;<br/>I’ll hold back no longer,<br/>I’ll love Him forever.<br/>',NULL,19406,5);
INSERT INTO stanza VALUES('NS7','1','O Father God, how faithful You<br/>Are through eternity;<br/>For Your eternal purpose You<br/>Are faithful now in me.<br/>',NULL,19407,1);
INSERT INTO stanza VALUES('NS7','chorus','How steadfast is Thy faithfulness!<br/>For this I worship Thee;<br/>It is established in the heav’n,<br/>And ever stands for me.<br/>',NULL,19408,2);
INSERT INTO stanza VALUES('NS7','2','You’ve called us into fellowship<br/>Of Your dear Son, our Lord,<br/>That He may be our portion full,<br/>Our center, our accord.<br/>',NULL,19409,3);
INSERT INTO stanza VALUES('NS7','3','Though we unfaithful oft will be,<br/>Yet You are faithful still,<br/>Though not for human welfare but<br/>For Your eternal will.<br/>',NULL,19410,4);
INSERT INTO stanza VALUES('NS7','4','Since we’ve believed into Your Son<br/>Some losses You’ve allowed<br/>That we from broken cisterns turn <br/>To drink our Fountain-God.<br/>',NULL,19411,5);
INSERT INTO stanza VALUES('NS7','5','Your faithfulness has led us in<br/>To Your economy,<br/>Where Christ we all enjoy that You<br/>In us may increased be.<br/>',NULL,19412,6);
INSERT INTO stanza VALUES('NS7','6','The living water’s faithful flow<br/>We drink and shout, Amen;<br/>The destination of this flow<br/>The New Jerusalem.<br/>',NULL,19413,7);
INSERT INTO stanza VALUES('NS8','1','Blend us, Lord, blend us, Lord, ’til we are in one accord.<br/>Hallelujah—the saints going on!<br/>Blend us, Lord, blend us, Lord, open hearts we can afford.<br/>Hallelujah—the churches go on!<br/>As the members of<br/>His organic Body,<br/>We need the others to go on.<br/>As local churches,<br/>We do also need<br/>One another for our going on.<br/>',NULL,19414,1);
INSERT INTO stanza VALUES('NS8','2','Build us up, build us up, as with one another sup’.<br/>Hallelujah—the riches of Christ!<br/>Build us up, build us up, as with You we all rise up.<br/>Hallelujah—the living Body!<br/>As blended members<br/>Of His one Body,<br/>We, the Lord do glorify!<br/>His Light does shine!<br/>Reviving Life does flow!<br/>And we do see that Satan is crushed!<br/>',NULL,19415,2);
INSERT INTO stanza VALUES('NS8','3','Bless us, Lord! bless us, Lord! All prevailing is Your blood!<br/>Hallelujah, we’re built up in love!<br/>Consummate! Consummate! All Your purpose consummate!<br/>Hallelujah—“The fullness thereof!“<br/>The gates of Hades<br/>Never will prevail<br/>Against the builded up church!<br/>When we are one,<br/>The enemy is done!<br/>The Lord Jesus is able to come!<br/>',NULL,19416,3);
INSERT INTO stanza VALUES('NS8','4','Intercede! Intercede! For Your people, meet Your need! <br/>Hallelujah! Get Your Bride this way. <br/>Have Your way! Have Your way! Do a building work we pray—<br/>Hallelujah—in our life each day! <br/>Through the cross of Jesus, <br/>By the Spirit filled, <br/>We are blending, building up! <br/>We all are one! <br/>We are...Jerusalem! <br/>Dear Lord Jesus, we ask You to come!<br/>',NULL,19417,4);
INSERT INTO stanza VALUES('NS9','1','Oh my Lord, I really love You<br/>Because You first loved us.<br/>You so loved us that You gave us,<br/>Your only begotten Son to save us all.<br/>Oh my Lord, Your love is divine.<br/>Oh with love, You sacrifice;<br/>Went through the pain, went to the cross,<br/>Shed Your blood that we may have Your salvation, Lord.<br/>Jesus Lord, the Name I love.<br/>With true love, I call Your Name.<br/>’Tis sweet to call, so dear to call.<br/>You are my Lord, my all in all.<br/>Jesus Lord, Hallelujah!<br/>With rejoicing, we praise and call.<br/>Just call Your Name, Amen! Oh Lord!<br/>Oh Jesus Lord, You will come,<br/>Come to us.<br/>',NULL,19418,1);
INSERT INTO stanza VALUES('NS10','1','Before you get the answer, you get the Answer;<br/>Before you get the things you ask for, you get the One;<br/>Before you get the object, you get the Person;<br/>Before you get the answer, you get the Lord.<br/>',NULL,19419,1);
INSERT INTO stanza VALUES('NS10','chorus','Cast all your anxiety with Him.<br/>Give them, commit them, throw them once for all.<br/>Throw your whole life with all its cares on Him<br/>Because it matters to Him concerning you.<br/>',NULL,19420,2);
INSERT INTO stanza VALUES('NS11','1','Love covers all things and believes all things,<br/>Love hopes in all things and endures all things.<br/>Love never falls away and won’t be rendered useless.<br/>But other things will pass away.<br/>',NULL,19421,1);
INSERT INTO stanza VALUES('NS11','2','Life is the element of God, who’s love;<br/>Hence God as life is shown by love, through you.<br/>Don’t neglect love, but pursue it first;<br/>Love makes a person spiritual.<br/>',NULL,19422,2);
INSERT INTO stanza VALUES('NS11','3','Love suffers long and love is kind, so kind,<br/>Love does not brag, is not puffed up,<br/>Love rejoices when God’s truth is manifest,<br/>Love is the element of God.<br/>',NULL,19423,3);
INSERT INTO stanza VALUES('NS11','4','If I speak in tongues, but do not love, I am<br/>Like sounding brass giving lifeless sounds, not life.<br/>If I know all mysteries but do not love my brother,<br/>I have no love and am nothing.<br/>',NULL,19424,4);
INSERT INTO stanza VALUES('NS12','1','Father, I know that all my life is portioned out for me,<br/>And the changes that are sure to come I do not fear to see;<br/>But I ask Thee for a present mind intent on pleasing Thee.<br/>',NULL,19425,1);
INSERT INTO stanza VALUES('NS12','2','I ask Thee for a thoughtful love, through constant watching wise,<br/>To meet the glad with joyful smiles, and to wipe the weeping eyes;<br/>And a heart at leisure from itself, to soothe and sympathize.<br/>',NULL,19426,2);
INSERT INTO stanza VALUES('NS12','3','I would not have the restless will that hurries to and fro,<br/>Seeking for some great thing to do or secret thing to know;<br/>I would be treated as a child, and guided where I go.<br/>',NULL,19427,3);
INSERT INTO stanza VALUES('NS12','4','Wherever in the world I am, in whatso’er estate,<br/>I have a fellowship with hearts to keep and cultivate;<br/>And a work of lowly love to do for the Lord on whom I wait.<br/>',NULL,19428,4);
INSERT INTO stanza VALUES('NS12','5','So I ask Thee for the daily strength, to none that ask denied,<br/>And a mind to blend with outward life while keeping at Thy side;<br/>Content to fill a little space, if Thou be glorified.<br/>',NULL,19429,5);
INSERT INTO stanza VALUES('NS12','6','And if some things I do not ask in my cup of blessing be,<br/>I would have my spirit filled the more with grateful love to Thee,<br/>More careful, not to serve Thee much, but to please Thee perfectly.<br/>',NULL,19430,6);
INSERT INTO stanza VALUES('NS12','7','There are briers besetting every path that call for patient care;<br/>There is a cross in every lot, and an earnest need for prayer;<br/>But a lowly heart that leans on Thee is happy anywhere.<br/>',NULL,19431,7);
INSERT INTO stanza VALUES('NS12','8','In a service which Thy will appoints there are no bonds for me;<br/>For my inmost heart is taught “the truth” that makes Thy children “free“<br/>And a life of self-renouncing love is a life of liberty.<br/>',NULL,19432,8);
INSERT INTO stanza VALUES('NS13','1','The New Jerusalem—ultimate sign;<br/>The ultimate goal of God’s economy;<br/>Incorporation, ’tis human-divine;<br/>Deified, we with God one building will be.<br/>',NULL,19433,1);
INSERT INTO stanza VALUES('NS13','2','In constitution, not corporeal; <br/>But fully organic, entirely of life.<br/>Her one reality’s spiritual;<br/>In our living and work, at this we’ll arrive.<br/>',NULL,19434,2);
INSERT INTO stanza VALUES('NS13','3','All aspects of New Jerusalem<br/>Were by the apostles perceived and conveyed.<br/>Their teaching was the whole New Testament;<br/>All their living and work this vision displayed.<br/>',NULL,19435,3);
INSERT INTO stanza VALUES('NS13','4','Her base, her gates, her foundations, her wall,<br/>Her temple, her throne, her supply and her light—<br/>All shown by signs in the last book of all;<br/>Their significance rich we cannot deny.<br/>',NULL,19436,4);
INSERT INTO stanza VALUES('NS13','5','One life, one work, this our one goal today:<br/>For that highest point where we’ll all be the same;<br/>Flesh, nat’ral being no more have a place;<br/>Going up step by step, God’s goal to attain.<br/>',NULL,19437,5);
INSERT INTO stanza VALUES('NS14','1','I am crucified with Christ;<br/>And it is no longer I who live,<br/>But it is Christ who lives in me;<br/>And the life which I now live<br/>In the flesh I live in faith,<br/>The faith in the Son of God,<br/>Who loved me and gave Himself up for me.<br/>',NULL,19438,1);
INSERT INTO stanza VALUES('NS15','1','I am crucified with Christ, with Christ;<br/>And it is no longer I who live, I who live,<br/>But it is Christ who lives in me, it is Christ who lives in me;<br/>And the life which I now live in the flesh<br/>I live in faith, the faith in the Son of God,<br/>Who loved me and gave Himself,<br/>Gave Himself up for me, gave Himself up for me.<br/>Who loved me and gave Himself,<br/>Gave Himself up for me, gave Himself up for me.<br/>',NULL,19439,1);
INSERT INTO stanza VALUES('NS16','1','It’s no longer I that liveth,<br/>But Christ that liveth in me.<br/>It’s no longer I that liveth,<br/>But Christ that liveth in me.<br/>He lives, He lives,<br/>Jesus is alive in me!<br/>It’s no longer I that liveth,<br/>But Christ that liveth in me.<br/>',NULL,19440,1);
INSERT INTO stanza VALUES('NS17','1','It’s so easy to love the Lord.<br/>It’s so easy to love the Lord.<br/>It’s so easy to love the Lord.<br/>It’s so easy to love the Lord.<br/>',NULL,19441,1);
INSERT INTO stanza VALUES('NS17','chorus','It’s so easy, it’s so easy—Amen.<br/>It’s so easy, it’s so easy—love Him.<br/>It’s so easy, it’s so easy—Amen.<br/>It’s so easy, it’s so easy—love Him.<br/>It’s so easy to love the Lord.<br/>',NULL,19442,2);
INSERT INTO stanza VALUES('NS17','2','When we call on Him we see,<br/>Just how beautiful is He.<br/>Just one look—it is enough,<br/>For us all to fall in love.<br/>',NULL,19443,3);
INSERT INTO stanza VALUES('NS17','3','Nothing else I need to do,<br/>Just to “stop” and look anew.<br/>Swells my heart with love divine,<br/>When His Spirit flows in mine.<br/>',NULL,19444,4);
INSERT INTO stanza VALUES('NS17','4','There’s no need to dwell on sin,<br/>In His blood we’ve entered in.<br/>Now in spirit we are free,<br/>To enjoy reality!<br/>',NULL,19445,5);
INSERT INTO stanza VALUES('NS17','5','Crazy love is filling me!<br/>I don’t care what I will be!<br/>Only one thing matters still,<br/>Lord e’en more my spirit fill!<br/>',NULL,19446,6);
INSERT INTO stanza VALUES('NS18','1','Jehovah is my Shepherd; I will lack nothing.<br/>He makes me lie down in green pastures;<br/>He leads me beside waters of rest.<br/>He restores my soul; He guides me on the paths<br/>Of righteousness for His name’s sake.<br/>Your rod and staff comfort me.<br/>Though I walk through death’s valley<br/>I fear no evil, for You are with me.<br/>You spread a feast before me,<br/>You anoint my head with oil; My cup runs over.<br/>Goodness and lovingkindness<br/>Will follow me always,<br/>I will dwell in the house of Jehovah<br/>For the length of my days.<br/>',NULL,19447,1);
INSERT INTO stanza VALUES('NS19','1','Let me love and not be requited.<br/>Let me serve and not be rewarded.<br/>Let me labor and not be remembered.<br/>Let me suffer and not be regarded.<br/>',NULL,19448,1);
INSERT INTO stanza VALUES('NS19','2','Let me pour wine, while I drink not.<br/>Let me break bread, while I keep not,<br/>Pour my life out that others be blessed,<br/>Be in suff’ring that they be contented.<br/>',NULL,19449,2);
INSERT INTO stanza VALUES('NS19','3','None to pity me or care for me,<br/>None to praise me or to console me.<br/>I would rather be desolate, wretched,<br/>Lonely, friendless, and wrongly treated.<br/>',NULL,19450,3);
INSERT INTO stanza VALUES('NS19','4','With my blood and tears pay the price to gain the crown,<br/>Suffer loss that I might a pilgrim’s life live out,<br/>For, Lord, this is how You lived Your life<br/>&nbsp;&nbsp;&nbsp;&nbsp;when You walked on this earthly sphere,<br/>Gladly bore all loss that those who drew near<br/>Could be freed from all suffering and fear.<br/>',NULL,19451,4);
INSERT INTO stanza VALUES('NS19','5','I know not how far the future lies ahead.<br/>On this path of no retreating I am led.<br/>So, Lord, let me now learn from Your perfect pattern,<br/>Suff’ring wrong, no resentment in return.<br/>',NULL,19452,5);
INSERT INTO stanza VALUES('NS19','6','May You in this difficult, tedious day,<br/>All my tears shed in secret wipe away;<br/>Learning You are my only solacement,<br/>And let my life for others’ joy be spent.<br/>',NULL,19453,6);
INSERT INTO stanza VALUES('NS20','1','Lord, I still love You,<br/>Though it seems, sometimes, hard to do.<br/>So many things, in all my life<br/>I do not understand. Oh my Lord,<br/>I need You. I love You.<br/>',NULL,19454,1);
INSERT INTO stanza VALUES('NS20','2','Lord, the church—Your Bride,<br/>You’ve included me—qualified!<br/>So, in the whole wide world,<br/>My city, home, and heart—Spread dear Lord,<br/>House to house, for whom You’ve died.<br/>',NULL,19455,2);
INSERT INTO stanza VALUES('NS21','1','Lord Jesus, all our hearts You’ve gained,<br/>You are the only One we love.<br/>Lord, keep our hearts single and pure<br/>To love You and Your church.<br/>',NULL,19456,1);
INSERT INTO stanza VALUES('NS21','chorus','Increase Yourself, O Lord,<br/>Now in us, grow more and more.<br/>And build the glorious church,<br/>You love and have died for.<br/>Lord, we suffer and live to You,<br/>’Tis our glory and joy.<br/>',NULL,19457,2);
INSERT INTO stanza VALUES('NS21','2','Lord Jesus, we are Your increase,<br/>The church, the kingdom, now we see;<br/>Lord, may we in Your kingdom live,<br/>Fighting for Your interest.<br/>',NULL,19458,3);
INSERT INTO stanza VALUES('NS21','chorus','May Your recovery,<br/>Forward march, spread far and wide.<br/>May Your lampstands shine forth,<br/>In each city so bright.<br/>We fear not hardship nor evil,<br/>For Lord You stand with us.<br/>',NULL,19459,4);
INSERT INTO stanza VALUES('NS22','1','Lord Jesus Christ, I do love You<br/>Because You first loved me.<br/>You shed Your blood, were crucified,<br/>While hanging on a tree.<br/>',NULL,19460,1);
INSERT INTO stanza VALUES('NS22','2','In resurrection and through death,<br/>You mingled God with man—<br/>Produced Your Body, consummating<br/>The New Jerusalem.<br/>',NULL,19461,2);
INSERT INTO stanza VALUES('NS22','3','For You Lord, open my heart wide.<br/>With others build me up.<br/>In You we would together blend,<br/>Enjoy Salvation’s cup.<br/>',NULL,19462,3);
INSERT INTO stanza VALUES('NS23','1','Lovers of Christ in His ascension—<br/>Enjoy the riches of His life.<br/>She becomes His private garden<br/>With its fountain, fruit, and spice.<br/>Christ is hers and she is Christ’s dear love.<br/>',NULL,19463,1);
INSERT INTO stanza VALUES('NS23','2','She is as beautiful as Tirzah<br/>As lovely as Jerusalem.<br/>Through her living in Christ’s ascension<br/>Her dear heart is now His home.<br/>She’s become the sanctuary of God.<br/>',NULL,19464,2);
INSERT INTO stanza VALUES('NS23','3','Who is this woman I am seeing?<br/>Shining forth as the moon and sun.<br/>She is absolutely heavenly,<br/>From the old creation free;<br/>Overcoming all to live within the veil.<br/>',NULL,19465,3);
INSERT INTO stanza VALUES('NS23','4','An army terrible with banners<br/>Christ’s lovers overcome to be.<br/>Those attracted by His beauty,<br/>Fully trusting in His power.<br/>Her romance is now the dances of two camps.<br/>',NULL,19466,4);
INSERT INTO stanza VALUES('NS23','5','The Shulamite, His duplication,<br/>His counterpart has now become.<br/>She’s the same in life and nature,<br/>His expression to the full;<br/>Consummated as the New Jerusalem.<br/>',NULL,19467,5);
INSERT INTO stanza VALUES('NS24','1','Lord, You are more precious than silver;<br/>Lord, You are more costly than gold;<br/>Lord, You are more beautiful than diamonds;<br/>And nothing I desire compares with You.<br/>',NULL,19468,1);
INSERT INTO stanza VALUES('NS24','2','Lord, Your life is divine, eternal.<br/>Lord, Your life regenerated me.<br/>Lord, Your life is growing within me,<br/>Until I am fully conformed to Thee.<br/>',NULL,19469,2);
INSERT INTO stanza VALUES('NS24','3','Lord, Your love is wide as the ocean.<br/>Lord, Your love is deep as the sea.<br/>Lord, Your love encompasses the nations,<br/>And that is all I want to live in me.<br/>',NULL,19470,3);
INSERT INTO stanza VALUES('NS24','4','Lord, Your light is shining within us;<br/>Lord, Your light drives darkness away.<br/>Lord, Your light is guiding us onwards,<br/>Preparing us for the coming wedding day.<br/>',NULL,19471,4);
INSERT INTO stanza VALUES('NS25','1','O Lord, I love You,<br/>I really love You,<br/>Without You life’s really nothing.<br/>You are so attracting,<br/>And You are so charming;<br/>Your riches are unsearchable.<br/>Your name’s so dear and sweet,<br/>Calling makes one satisfied,<br/>Now You are mine and I am Thine, Lord;<br/>Joined and mingled with You,<br/>God-man incorporation,<br/>Foretaste of the New Jerusalem.<br/>',NULL,19472,1);
INSERT INTO stanza VALUES('NS26','1','O the joy of having nothing and being nothing, seeing nothing<br/>But a living Christ in glory,<br/>And being careful for nothing but His interests down here.<br/>Whom have I in heaven but Thee?<br/>And there is none upon the earth that I desire beside Thee.<br/>O the joy of having nothing and being nothing, seeing nothing<br/>But a living Christ in glory,<br/>And being careful for nothing but His interests down here.<br/>',NULL,19473,1);
INSERT INTO stanza VALUES('NS27','1','Oh! the joy of having nothing,<br/>Being nothing, seeing nothing<br/>But a living Christ in glory<br/>And being careful for nothing.<br/>Oh! the joy of having nothing,<br/>Being nothing, seeing nothing<br/>But a living Christ in glory<br/>And His interest here on earth!<br/>',NULL,19474,1);
INSERT INTO stanza VALUES('NS28','1','God has called us for His purpose,<br/>His economy so glorious,<br/>For which He was fully processed;<br/>Consummated now is He!<br/>As the Spirit, He indwells us;<br/>As our God alloted portion,<br/>Working out His full salvation,<br/>Making us the same as He is.<br/>',NULL,19475,1);
INSERT INTO stanza VALUES('NS28','chorus','Oh, may a clear, controlling vision of<br/>The Lord’s economy direct my heart,<br/>And burn in me until my spirit’s wholly set afire!<br/>With spirit strong and active we’ll press on<br/>To consummate God’s goal—<br/>New Jerusalem, Hallelujah!<br/>',NULL,19476,2);
INSERT INTO stanza VALUES('NS28','2','Jesus lived the God-man pattern,<br/>Set the way for us to follow,<br/>He denied His natural man and <br/>Was obedient unto death,<br/>Once He was the only God-man;<br/>Now we are His duplication.<br/>As the many grains we’re blended<br/>As His corporate reproduction.<br/>',NULL,19477,3);
INSERT INTO stanza VALUES('NS28','3','Living out His resurrection,<br/>Dying to the flesh and soul-life.<br/>Living by the mingled spirit,<br/>Natural man we will deny.<br/>Now we’re living in the Body,<br/>Every day we’re overcoming,<br/>Striving for the peak of Zion,<br/>Watching for our Lord’s appearing.<br/>',NULL,19478,4);
INSERT INTO stanza VALUES('NS28','4','God and man will have one living,<br/>Always in the mingled spirit;<br/>We two are incorporated <br/>One organic entity!<br/>This the vision of the ages<br/>Will control our daily living<br/>That the Lord may have His Body<br/>Shining as the holy city.<br/>',NULL,19479,5);
INSERT INTO stanza VALUES('NS29','1','Set your mind on the things which are above,<br/>Not on the things which are on the earth.<br/>For I died, for I died,<br/>And my life is hidden<br/>With Christ, with Christ in God.<br/>',NULL,19480,1);
INSERT INTO stanza VALUES('NS30','1','Take time to receive Him—the blessing’s outpoured,<br/>And we may obtain it by reading His Word;<br/>We bask in the splendour of His healing light,<br/>And light becomes life, as in Him we delight.<br/>',NULL,19481,1);
INSERT INTO stanza VALUES('NS30','2','Take time to absorb Him, to gain the supply,<br/>That we may be watered and nourished thereby;<br/>The deeper the roots spread, the deeper the flow,<br/>And richer and higher within us He’ll grow.<br/>',NULL,19482,2);
INSERT INTO stanza VALUES('NS30','3','Take time to inhale Him—His Word we may breathe;<br/>By breathing it, God’s very life we receive—<br/>He breathes Himself out so that we may breathe in<br/>The life, the reality, fullness of Him.<br/>',NULL,19483,3);
INSERT INTO stanza VALUES('NS30','4','Take time to enjoy Him, our portion is He:<br/>Our present, available reality;<br/>Our practical, real, and enjoyable Lord<br/>Is everything to us through His living Word.<br/>',NULL,19484,4);
INSERT INTO stanza VALUES('NS30','5','Take time to behold Him, gaze oft on His face,<br/>Receiving His Person, and grace upon grace.<br/>By His pleasant shining, infused we will be;<br/>Our faces will glow with His light, radiantly.<br/>',NULL,19485,5);
INSERT INTO stanza VALUES('NS31','1','The flowing of life divine,<br/>In spirit so sweetly flows—<br/>The overflowing life divine,<br/>Nourishing my spirit so—<br/>Bringing the Triune God’s fullness,<br/>In spirit operates and moves,<br/>Bringing me all of His supply—<br/>Life as my supply.<br/>',NULL,19486,1);
INSERT INTO stanza VALUES('NS31','2','Oh, this precious life divine<br/>Is the Triune God Himself!<br/>All He is and all He has<br/>Are all concealed in this life.<br/>God’s life into my spirit comes,<br/>Mingling with me in life as one—<br/>Wisdom, pow’r, holy righteousness<br/>Are my experience.<br/>',NULL,19487,2);
INSERT INTO stanza VALUES('NS31','3','The outflow of life divine—<br/>Manifested in His Son;<br/>In Him is the life divine,<br/>Saviour He’s of everyone.<br/>Life of all lives—unique is He,<br/>And He released His life to me<br/>That this life I ever may gain—<br/>Yes, His life divine!<br/>',NULL,19488,3);
INSERT INTO stanza VALUES('NS31','4','The release of life divine<br/>The life-giving Spirit is;<br/>The working of life divine<br/>In my spirit operates;<br/>He is the wonderful ointment<br/>In my spirit, anointing me<br/>With His compounded elements—<br/>Pervading through me.<br/>',NULL,19489,4);
INSERT INTO stanza VALUES('NS31','5','Oh, this life I treasure so—<br/>Life divine so wonderful!<br/>In me this life’s working—so<br/>Divine, rich and bountiful!<br/>Salvation great and excellent,<br/>And it’s all mine to experience;<br/>Truly, this life is all to me—<br/>All my life is He.<br/>',NULL,19490,5);
INSERT INTO stanza VALUES('NS32','1','The processed and consummated Triune God,<br/>According to the good pleasure of His desire<br/>And for the highest intention in His economy,<br/>Is building Himself into His chosen people<br/>And His chosen people into Himself<br/>That He may have a constitution in Christ<br/>As the mingling of divinity with humanity<br/>To be His organism and the Body of Christ<br/>As His eternal expression and the mutual abode<br/>For the redeeming God and the redeemed man.<br/>The ultimate consummation of this miraculous structure of treasure<br/>Will be the New Jerusalem for eternity.<br/>',NULL,19491,1);
INSERT INTO stanza VALUES('NS33','1','If there’s such love in the human race,<br/>To meet all our need with wondrous grace,<br/>Firm and endless and free,<br/>Like the high mount and sea,<br/>Our dear Lord need not a human be;<br/>In the dark, He has heard,<br/>How I sigh, how I pine,<br/>On the way, He has seen,<br/>How I wander in life.<br/>',NULL,19492,1);
INSERT INTO stanza VALUES('NS33','2','In His love to us He has drawn nigh,<br/>Coming to us from His throne on high.<br/>Seeking me without rest,<br/>Thirst and hunger did taste,<br/>On the cross the Lord paid all my debt,<br/>He arose from the grave,<br/>All the sinners He saved,<br/>Joined with me, He filled me with His faith.<br/>',NULL,19493,2);
INSERT INTO stanza VALUES('NS33','3','Love I’ve found within the human race,<br/>Of all love in heav’n and earth the best,<br/>Firm and endless and free,<br/>Like the high mount and sea,<br/>True and precious, through eternity;<br/>He’s with me all my days,<br/>Leading me all the way;<br/>O my Lord, O my love,<br/>“I love You!” ’Tis my prayer.<br/>',NULL,19494,3);
INSERT INTO stanza VALUES('NS34','1','Fear not, He knows;<br/>My soul why fret and tremble?<br/>Fear not, He knows;<br/>Your life is in His hands.<br/>Fear not, He knows;<br/>And you know He is able<br/>To care for You,<br/>So trust the best is planned!<br/>',NULL,19495,1);
INSERT INTO stanza VALUES('NS34','chorus','Oh Lord, You know;<br/>’Tis a thought so joyous!<br/>Though I don’t know,<br/>What need have I to fear?<br/>You know, You know;<br/>Thank and praise You, Jesus!<br/>Through all unknowns,<br/>You make Yourself so dear!<br/>',NULL,19496,2);
INSERT INTO stanza VALUES('NS34','2','Just trust, He knows<br/>Life’s still unwritten letter.<br/>Just trust, He knows<br/>Plans time would now disguise.<br/>Just trust, He knows,<br/>He sees which turn is better;<br/>At the right time<br/>He’ll open up your eyes!<br/>',NULL,19497,3);
INSERT INTO stanza VALUES('NS34','3','Just rest, He knows;<br/>With Him blindness is pleasant!<br/>Just rest, He knows;<br/>Sightless, you see Him best!<br/>Just rest, He knows;<br/>My soul, don’t waste the present<br/>On those “what-if’s“.<br/>Just turn to Him and rest!<br/>',NULL,19498,4);
INSERT INTO stanza VALUES('NS34','4','Just seek, He knows;<br/>Seek first His heart’s great yearning.<br/>Just seek, He knows;<br/>Serve Him, in Him abide.<br/>Just seek, He knows;<br/>Have peace and rest while turning.<br/>Put His cares first;<br/>All else He will provide.<br/>',NULL,19499,5);
INSERT INTO stanza VALUES('NS35','1','Jesus Lord, I love You.<br/>Nothing more do I want.<br/>Nothing in this whole world<br/>Satisfies as You do, Lord.<br/>Though I wander away,<br/>Still Your love seeks after me,<br/>Reaching me; I’m subdued<br/>And I turn back to You.<br/>',NULL,19500,1);
INSERT INTO stanza VALUES('NS36','1','Sometimes it seems that<br/>I have no room in my heart for You.<br/>But then You touch me<br/>And soften me to turn to You.<br/>',NULL,19501,1);
INSERT INTO stanza VALUES('NS36','chorus','Recover my heart,<br/>Rekindle my love for You.<br/>Fill me with love<br/>Eternally, ever new.<br/>Make me wholly Thine.<br/>',NULL,19502,2);
INSERT INTO stanza VALUES('NS36','2','Lord, I long to<br/>Empty myself of all but You;<br/>Give You my best love,<br/>Preeminence in all I do.<br/>',NULL,19503,3);
INSERT INTO stanza VALUES('NS36','3','I want to love You<br/>With all my heart and all my soul.<br/>I want no other,<br/>I give myself to be Yours alone.<br/>',NULL,19504,4);
INSERT INTO stanza VALUES('NS37','1','I’ve got a river of life flowing within me;<br/>It makes the lame to walk and the blind to see.<br/>It opens prison doors, sets the captives free.<br/>I’ve got a river of life flowing within me.<br/>',NULL,19505,1);
INSERT INTO stanza VALUES('NS37','chorus','Spring up, O well, within my spirit!<br/>Rise up and tell, so all can hear it!<br/>Spring up, O well, so I experience<br/>That life abundantly.<br/>',NULL,19506,2);
INSERT INTO stanza VALUES('NS37','2','I’ve got a river of life flowing within me;<br/>It started gushing up when God set me free.<br/>That I keep the flow is my only plea.<br/>I’ve got a river of life springing within me.<br/>',NULL,19507,3);
INSERT INTO stanza VALUES('NS37','3','Once I call His name there’s a flow within;<br/>It turns me from my day, makes Him Lord again.<br/>As my spirit burns, Satan cannot win.<br/>Calling, “Oh Lord Jesus,” keeps the flow within.<br/>',NULL,19508,4);
INSERT INTO stanza VALUES('NS38','1','Jesus Lord, I long<br/>For Your embrace<br/>To taste Your kisses sweeter than wine,<br/>To know the love that surpasses all time,<br/>To feel the joy when I am in Your arms,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Precious One.<br/>',NULL,19509,1);
INSERT INTO stanza VALUES('NS38','2','Jesus Lord, You died <br/>To set me free.<br/>Now You’re my all and my everything;<br/>I am so lost when I’m not near Thee;<br/>Sick with love for You I’ll ever be,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Treasured One.<br/>',NULL,19510,2);
INSERT INTO stanza VALUES('NS38','3','Jesus Lord, I’m charmed<br/>By Your mercy<br/>And I rejoice that You’ve chosen me<br/>To be with You in eternity<br/>But until then keep me close to Thee,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Lovely One.<br/>',NULL,19511,3);
INSERT INTO stanza VALUES('NS39','1','Lord, when I’m bad I get so sad;<br/>It seems the Lamb I never knew,<br/>But blood was shed, depression fled<br/>So now I hide in You.<br/><br/>It’s in the Son I have begun,<br/>It’s in the Son I’ll onward go<br/>In Him I’ll walk, in Him I’ll talk,<br/>In Him I’ll surely grow.<br/>',NULL,19512,1);
INSERT INTO stanza VALUES('NS39','chorus','Oh Jesus now grow in me;<br/>I want for You to be<br/>Pleased to be in me what You want to be<br/>And when it gets too hard feel free<br/>To grow some more in me.<br/>',NULL,19513,2);
INSERT INTO stanza VALUES('NS39','2','Lord, I’m not strange, I just can’t change<br/>It’s not from lack of effort though<br/>The more I try, the more I find<br/>I need for You to grow.<br/><br/>Where I have failed, Lord You’ve prevailed<br/>The secret of success I know:<br/>That all I need is life indeed,<br/>I pray for You to grow.<br/>',NULL,19514,3);
INSERT INTO stanza VALUES('NS39','3','With flags unfurled here comes the world<br/>It’s beauty does my heart embrace<br/>But it grows pale whene’er that veil<br/>Removed displays Your face.<br/><br/>As my heart turns, with love it burns<br/>Your face is all I want to see<br/>Your image Lord which I adore<br/>My image soon will be.<br/>',NULL,19515,4);
INSERT INTO stanza VALUES('NS40','1','Lord Jesus, draw me one step further;<br/>Draw me, Lord from where I am.<br/>I’ve been here too long already.<br/>Move me, Lord, I know You can.<br/>',NULL,19516,1);
INSERT INTO stanza VALUES('NS40','2','Your whisper, Lord, so softly sounding,<br/>Deep within my heart does burn.<br/>Let Your stillness now subdue me<br/>That Your feeling I discern.<br/>',NULL,19517,2);
INSERT INTO stanza VALUES('NS40','3','All idle thoughts and impure feelings,<br/>Lord, remove from mind and heart.<br/>Wash me in the crystal water<br/>And more life to me impart.<br/>',NULL,19518,3);
INSERT INTO stanza VALUES('NS40','4','All hidden things that block my vision,<br/>Rocks of self-ambition, pride;<br/>Now expose and burn away, Lord<br/>By Your look intensified.<br/>',NULL,19519,4);
INSERT INTO stanza VALUES('NS40','5','Increase the weight of glory in me,<br/>Let Your Spirit now transform,<br/>That all things would not be wasted<br/>But would work to save me more.<br/>',NULL,19520,5);
INSERT INTO stanza VALUES('NS40','6','Lord Jesus, oh how much I need You!<br/>Thank You, Lord, that You are here,<br/>Ever present as the Body.<br/>I would always seek You there.<br/>',NULL,19521,6);
INSERT INTO stanza VALUES('NS41','1','Lord, I thank You for another new day to live You;<br/>Another day for me to practise being one spirit with You.<br/>Remind me this whole day to reject my self,<br/>Not to trust myself,<br/>And not to live by myself.<br/>Strengthen me to live by You.<br/>Make this a day for me to live You out.<br/>Taking You as my everything,<br/>Abiding in You as a branch in the vine.<br/>',NULL,19522,1);
INSERT INTO stanza VALUES('NS42','1','Dearest Lord, I come;<br/>This is now my pray’r,<br/>Keep me open to You,<br/>May I always love You.<br/>',NULL,19523,1);
INSERT INTO stanza VALUES('NS42','chorus','Lord, I love You more today,<br/>So much more than yesterday;<br/>Lord, I need You, Lord, I love You.<br/>',NULL,19524,2);
INSERT INTO stanza VALUES('NS42','2','Now that the choice is mine,<br/>Lord, I still choose You;<br/>’Though the paths be not marked,<br/>I’m still trusting in You.<br/>',NULL,19525,3);
INSERT INTO stanza VALUES('NS42','3','And if the way is hard,<br/>If things don’t go my way,<br/>Keep my heart soft to You,<br/>Keep me open to You.<br/>',NULL,19526,4);
INSERT INTO stanza VALUES('NS42','4','Dearest Lord, I pray,<br/>Lead me everyday;<br/>Don’t let things come between,<br/>Keep my eyes fixed on You.<br/>',NULL,19527,5);
INSERT INTO stanza VALUES('NS42','5','When many years have gone,<br/>And many things have passed,<br/>I will still be for You,<br/>I will still say to You:<br/>',NULL,19528,6);
INSERT INTO stanza VALUES('NS43','1','Lord, I love You, I just want to love You.<br/>You are my dearest One, my only love.<br/>O Lord, I love You,<br/>O Lord, I love You with all my heart.<br/>',NULL,19529,1);
INSERT INTO stanza VALUES('NS44','1','We love You, Lord, we love You.<br/>You are altogether lovely.<br/>We’ve seen Your beauty<br/>Here in the church, in all Your saints.<br/>',NULL,19530,1);
INSERT INTO stanza VALUES('NS45','1','The last Adam became a life-giving Spirit.<br/>The Lord is the Spirit, the Spirit gives life.<br/>But He who is joined to the Lord is one spirit.<br/>Oh, we have been joined to the Lord!<br/>We are one spirit with Him.<br/>The last Adam became a life-giving Spirit.<br/>The Lord is the Spirit, the Spirit gives life.<br/>',NULL,19531,1);
INSERT INTO stanza VALUES('NS46','1','Lord, You love me so immensely;<br/>I would love You more intensely.<br/>Every day and every moment,<br/>O Lord, capture me.<br/>Let my goal and my life’s theme be,<br/>Lord, to love You more supremely;<br/>With all my heart, Lord Jesus,<br/>Keep me faithful unto Thee.<br/>',NULL,19532,1);
INSERT INTO stanza VALUES('NS46','chorus','Draw me, Lord, each day.<br/>Take my veils away.<br/>With a pure heart will I see You;<br/>Lord I just love You.<br/>Nothing else I seek;<br/>No one else for me.<br/>I would fully and absolutely<br/>Give my whole being unto Thee.<br/>',NULL,19533,2);
INSERT INTO stanza VALUES('NS47','1','Known of my Father before time began,<br/>Washed in the sprinkling blood of the Lamb,<br/>Now in the spirit I am a God-man,<br/>Hallelujah, Hallelujah!<br/>',NULL,19534,1);
INSERT INTO stanza VALUES('NS47','chorus','Hallelujah, Hallelujah, Hallelujah,<br/>Hallelujah, Hallelujah, Hallelujah.<br/>',NULL,19535,2);
INSERT INTO stanza VALUES('NS47','2','Father, You knew me a long time ago.<br/>In Your foreknowledge, Your mercy to show,<br/>You foreordained me Your glory to know,<br/>Hallelujah, Hallelujah!<br/>',NULL,19536,3);
INSERT INTO stanza VALUES('NS47','3','Son, in Your blood, the most precious of all,<br/>I have been purchased and saved from the fall.<br/>Your resurrection’s my reason to call,<br/>Hallelujah, Hallelujah!<br/>',NULL,19537,4);
INSERT INTO stanza VALUES('NS47','4','Spirit, You came and You sanctified me.<br/>You gave me faith when my eyes couldn’t see.<br/>Now You’re the Spirit of life within me,<br/>Hallelujah, Hallelujah!<br/>',NULL,19538,5);
INSERT INTO stanza VALUES('NS47','5','You are my Father and I have Your seed!<br/>I have been purchased and I am redeemed!<br/>I have the Spirit within me indeed!<br/>Hallelujah, Hallelujah!<br/>',NULL,19539,6);
INSERT INTO stanza VALUES('NS48','1','God wants someone to love Him,<br/>Not just someone to serve Him;<br/>He wants someone to love Him<br/>&nbsp;&nbsp;&nbsp;&nbsp;As His bride.<br/>God wants someone to match Him,<br/>Not just to imitate Him;<br/>He wants a counterpart,<br/>&nbsp;&nbsp;&nbsp;&nbsp;One from His side.<br/>',NULL,19540,1);
INSERT INTO stanza VALUES('NS48','chorus','For this He came down to us,<br/>He came to court, to woo us,<br/>Away from everything, and unto Him.<br/>Now we’re espoused unto Him,<br/>Pledged and betrothed unto Him;<br/>Yes, we are bound unto Him by His love.<br/>',NULL,19541,2);
INSERT INTO stanza VALUES('NS48','2','God wants someone to love Him,<br/>Not just someone to fear Him;<br/>He wants a sweetheart who will<br/>&nbsp;&nbsp;&nbsp;&nbsp;Be His bride.<br/>God wants someone to know Him,<br/>Not just to know about Him,<br/>He wants someone who’ll look Him<br/>&nbsp;&nbsp;&nbsp;&nbsp;In the eye.<br/>',NULL,19542,3);
INSERT INTO stanza VALUES('NS49','1','There are times and times again,<br/>When my love seems far away;<br/>The hours would stretch, the days turn gray;<br/>All the while, I know not how,<br/>In my darkest hour, He prays<br/>In the saints, oh, for my sake.<br/>',NULL,19543,1);
INSERT INTO stanza VALUES('NS49','chorus','By a touch of His dear love,<br/>By the sound of His sweet voice,<br/>Whispers from above,<br/>Spoken through men of clay.<br/>And this world just fades away.<br/>(Let this world just fade away.)<br/>',NULL,19544,2);
INSERT INTO stanza VALUES('NS49','2','Blinded soul, I cannot see<br/>What this world has done to me;<br/>My heart grows cold and life would bleed;<br/>Then He comes, knocks on my door,<br/>Through the saints—and there they stand<br/>With the Lord, oh, for my need!<br/>',NULL,19545,3);
INSERT INTO stanza VALUES('NS50','1','He washed away my sins,<br/>Gave me a brand new heart;<br/>A heart to love Him, trust Him,<br/>Seek Him in His Word.<br/>',NULL,19546,1);
INSERT INTO stanza VALUES('NS50','chorus','He tells me guard thy heart<br/>Above all that thou guardest;<br/>For out of it, flows the springs,<br/>The springs of life.<br/>',NULL,19547,2);
INSERT INTO stanza VALUES('NS50','2','He walks with me each day;<br/>I open up to Him;<br/>He is my life, my stay,<br/>And everything I need.<br/>',NULL,19548,3);
INSERT INTO stanza VALUES('NS50','3','And sometimes when I fail,<br/>I forget that He’s there;<br/>He’s just waiting, watching,<br/>Then He draws me near.<br/>',NULL,19549,4);
INSERT INTO stanza VALUES('NS51','1','Create in me a clean heart, O God,<br/>And renew a right spirit within me.<br/>Create in me a clean heart, O God,<br/>And renew a right spirit within me.<br/>Cast me not away from Thy presence;<br/>Take not Thy holy Spirit from me.<br/>Restore unto me the joy of Thy salvation;<br/>And renew a right spirit within me.<br/>',NULL,19550,1);
INSERT INTO stanza VALUES('NS52','1','Are you the One who came from heav’n?<br/>The mighty God who suffered the curse of sin and died,<br/>And they pierced Your side.<br/>Rose from the grave, You’re ever new;<br/>You’ve sown in me the seed of life that grew<br/>From sinner, poor and blind<br/>To New Jerusalem.<br/>',NULL,19551,1);
INSERT INTO stanza VALUES('NS52','chorus','I love You more<br/>With all my heart, with all my soul,<br/>(Oh, Love divine)<br/>With all my strength, with all my mind;<br/>Sweet, sweet repose.<br/>',NULL,19552,2);
INSERT INTO stanza VALUES('NS52','2','Are You the One my heart has known?<br/>Are You the One, my spirit has richly grown to love?<br/>Oh come, Beloved<br/>And with my lips, shall I confess<br/>That deep in You my heart found rest<br/>And peace as ocean’s depth?<br/>Oh, fill me with Your breath!<br/>',NULL,19553,3);
INSERT INTO stanza VALUES('NS53','1','From the morning to the evening, His faithfulness I see;<br/>His mercy reaching sinners, reaching even me;<br/>And I know, now I know.<br/>Brighter than the brightest sunlight, all doubts and fears must cease;<br/>Sweeter than the sweetest delight, His living Word in me;<br/>And I know, now I know.<br/>',NULL,19554,1);
INSERT INTO stanza VALUES('NS53','chorus','That God is there for me tomorrow,<br/>As He is for me today;<br/>That He’ll take my cares and sorrow,<br/>And He’ll wipe them all away;<br/>There’s no crisis that He can’t bear,<br/>There’s no storm He can’t abate;<br/>He’s my God, He’s my God.<br/>',NULL,19555,2);
INSERT INTO stanza VALUES('NS53','2','Day by day His grace grows dearer; His love has conquered me,<br/>Never leaving, never ceasing, His Spirit constantly<br/>Flooding me, rich and free;<br/>Higher than the highest heaven, He lifts me up to see<br/>New Jerusalem descending, His Bride, His love to be<br/>Eternally, it shall be.<br/>',NULL,19556,3);
INSERT INTO stanza VALUES('NS54','1','We don’t care where you come from,<br/>We don’t care where you would go.<br/>Since we meet in the Lord,<br/>Let us all meet joyfully.<br/>Things may come to discourage<br/>And they leave you somewhat sad;<br/>Let it all go, let it go!<br/>And let’s sing a melody.<br/>',NULL,19557,1);
INSERT INTO stanza VALUES('NS54','chorus','Welcome here, our dear friend,<br/>We’re so glad that you have come,<br/>Here we all love you,<br/>And the Lord loves you most.<br/>In the church we need you now,<br/>Everything here is for you.<br/>We wait for you to return,<br/>Just remember that we’ll think of you.<br/>',NULL,19558,2);
INSERT INTO stanza VALUES('NS54','2','Won’t you cast off your burdens,<br/>Put aside all your restraints,<br/>Sing a song full of joy,<br/>Breathe in the refreshing air<br/>Let’s enjoy holy feelings<br/>Savour sweetness and repose <br/>Let’s bring home peace and this joy<br/>So we’ll never be distressed.<br/>',NULL,19559,3);
INSERT INTO stanza VALUES('NS55','1','Call, call, won’t you call Jesus’ name;<br/>He’s everything that’s real, and He’s always the same.<br/>Get out of your mind, get your spirit in gear,<br/>That’s the way to get to Jesus from here.<br/>That’s the way to get to Jesus from here.<br/>',NULL,19560,1);
INSERT INTO stanza VALUES('NS55','2','Life, Life, O the issue is Life.<br/>Living isn’t worth it if you haven’t got Life.<br/>So drop all your concepts, they’re killing you dead,<br/>&nbsp;&nbsp; And touch the living Jesus instead.<br/>&nbsp;&nbsp; And touch the living Jesus instead.<br/>',NULL,19561,2);
INSERT INTO stanza VALUES('NS55','3','God, God, O you gave us your Son,<br/>He died for us and rose again; the victory He won!<br/>And now He lives within us, new life has begun.<br/>&nbsp;&nbsp; O we praise You, Lord, it all has been done.<br/>&nbsp;&nbsp; O we praise You, Lord, it all has been done.<br/>',NULL,19562,3);
INSERT INTO stanza VALUES('NS56','1','Rain on me; rain on me;<br/>Let Your mercy rain on me;<br/>It is not by willing or by running, Lord;<br/>Let Your mercy rain on me.<br/>',NULL,19563,1);
INSERT INTO stanza VALUES('NS56','2','Reign in me; reign in me;<br/>May Your life, Lord, reign in me,<br/>By Your grace abundant and Your righteousness;<br/>May Your life, Lord, reign in me.<br/>',NULL,19564,2);
INSERT INTO stanza VALUES('NS56','3','Overcome, overcome;<br/>Lord, I pray to overcome,<br/>By the Spirit sevenfold intensified;<br/>Lord, I pray to overcome.<br/>',NULL,19565,3);
INSERT INTO stanza VALUES('NS56','4','Grow in me; grow in me;<br/>For the Body grow in me,<br/>Through the rich dispensing of Your life supply;<br/>For the Body grow in me.<br/>',NULL,19566,4);
INSERT INTO stanza VALUES('NS56','5','Transform me; transform me;<br/>For the Body transform me;<br/>I behold Your glory with an unveiled face;<br/>For the Body transform me.<br/>',NULL,19567,5);
INSERT INTO stanza VALUES('NS56','6','Lord, gain me; Lord, gain me;<br/>In the Body, Lord, gain me,<br/>For the full expression of the Triune God;<br/>In the Body, Lord, gain me.<br/>',NULL,19568,6);
INSERT INTO stanza VALUES('NS56','7','Lord, blend me; Lord, blend me;<br/>In the Body, Lord, blend me,<br/>For the consummation—New Jerusalem;<br/>In the Body, Lord, blend me.<br/>',NULL,19569,7);
INSERT INTO stanza VALUES('NS57','1','Have you found your human spirit?<br/>It’s connected to your mouth!<br/>“Hallelujah, O Lord Jesus!“<br/>That’s the way to let it out.<br/>',NULL,19570,1);
INSERT INTO stanza VALUES('NS57','chorus','What is born of God is our human spirit—<br/>Praise God, the job has been done!<br/>What is born of Spirit is just our spirit,<br/>And the two spirits are one.<br/>',NULL,19571,2);
INSERT INTO stanza VALUES('NS57','2','Don’t wait for an inspiration—<br/>That’s the subtle enemy.<br/>Open up! Release your spirit,<br/>Testifying you are free.<br/>',NULL,19572,3);
INSERT INTO stanza VALUES('NS58','1','The Bible is God’s breath; the essence of His Person.<br/>God’s speaking out through man; borne by the Holy Spirit.<br/>The Bible is God’s speaking in the prophets and the Son;<br/>The Bible is the Holy Spirit’s revelation.<br/>',NULL,19573,1);
INSERT INTO stanza VALUES('NS58','2','The Bible testifies concerning the Lord Jesus;<br/>The Bible makes man wise, wise unto salvation;<br/>The Bible causes man to be regenerated;<br/>Our spiritual milk, our bread of life;<br/>It makes us all complete.<br/>',NULL,19574,2);
INSERT INTO stanza VALUES('NS59','1','You have come as light to me, Jesus, my Lord;<br/>That I shall not be in darkness from now and on.<br/>I was lost in sin, but then You came and restored my soul.<br/>You left all to find me,<br/>You received me with open arms,<br/>All the angels sang and rejoiced,<br/>Lovingly You treated me.<br/>Father, I come back to You in Your light.<br/>',NULL,19575,1);
INSERT INTO stanza VALUES('NS59','chorus','O Lord Jesus, Precious Jesus, Rescue me, Savior.<br/>O Lord Jesus, Precious Jesus, Rescue me, Savior.<br/>',NULL,19576,2);
INSERT INTO stanza VALUES('NS60','1','O there’s One in me who<br/>Is the most lovely One<br/>In the whole universe—<br/>I just love Him.<br/>',NULL,19577,1);
INSERT INTO stanza VALUES('NS60','2','He has made me fall in love<br/>With Him more and more each day:<br/>And for now that I’m in love—<br/>I’ll always stay.<br/>',NULL,19578,2);
INSERT INTO stanza VALUES('NS60','chorus','For my Jesus has captured my heart.<br/>He has wrecked me with all He can impart.<br/>He drew me to Himself,<br/>Now I love nothing else.<br/>His beauty, love and charm won my heart.<br/>',NULL,19579,3);
INSERT INTO stanza VALUES('NS60','3','As the days go on and on<br/>There’s a hold that is so strong.<br/>A tide floods all my being—<br/>For I’m in love.<br/>',NULL,19580,4);
INSERT INTO stanza VALUES('NS60','4','There’s a face I long to see<br/>Whose arms will embrace me.<br/>As I rest in this sweet place<br/>I love Him more and more.<br/>',NULL,19581,5);
INSERT INTO stanza VALUES('NS61','1','Early in the morning,<br/>Meeting with the saints,<br/>Gather the fresh manna,<br/>Take in His rich grace!<br/>',NULL,19582,1);
INSERT INTO stanza VALUES('NS61','chorus','Christ in all the saints,<br/>Living, fresh and new.<br/>Blending with each other,<br/>Tasting morning dew!<br/>',NULL,19583,2);
INSERT INTO stanza VALUES('NS61','2','Singing songs together,<br/>Spirits exercised.<br/>Drawing from each other,<br/>Christ is realized!<br/>',NULL,19584,3);
INSERT INTO stanza VALUES('NS61','3','Reading in the Bible,<br/>Each one taking turns;<br/>Fellowship together,<br/>How our spirit burns!<br/>',NULL,19585,4);
INSERT INTO stanza VALUES('NS61','4','Praying for our loved ones,<br/>Bring them to the throne.<br/>Christ desires to save them,<br/>Bringing them all home!<br/>',NULL,19586,5);
INSERT INTO stanza VALUES('NS61','5','Morning, noon and evening,<br/>Gath’ring with the saints;<br/>Joy in each one’s presence,<br/>Taking in fresh grace.<br/>',NULL,19587,6);
INSERT INTO stanza VALUES('NS62','1','Oh, there’s a place for you, my friend<br/>Where the earthly sorrows end,<br/>And the joy is flowing like a river, free;<br/>Where everyone is satisfied,<br/>As we mutually abide<br/>In the One who gave His life for you and me.<br/>',NULL,19588,1);
INSERT INTO stanza VALUES('NS62','chorus','Oh, Jesus is blending us together;<br/>He is the reason why we’re here.<br/>We will be one in Him forever,<br/>And we will build according to this vision clear.<br/>',NULL,19589,2);
INSERT INTO stanza VALUES('NS62','2','If you would like to know this place<br/>Where you’ll find abundant grace,<br/>All that I can say is that you’ll have to “see.“<br/>’Cause words come short of the appeal—<br/>I just know that it is real—<br/>Once you’ve seen it too, I think that you’ll agree!<br/>',NULL,19590,3);
INSERT INTO stanza VALUES('NS63','1','Christ is God incarnated,<br/>Born according to God’s plan<br/>To bring divinity, into humanity,<br/>By mingling with man.<br/><br/>Christ is God incarnated,<br/>He became the Son of Man;<br/>A man of flesh yet without sin,<br/>Accomplishing redemption,<br/>He was a perfect man.<br/>',NULL,19591,1);
INSERT INTO stanza VALUES('NS63','chorus','And He shall be named Jesus,<br/>And called Emmanuel,<br/>Hallelujah! God with us,<br/>In man He came to dwell.<br/>',NULL,19592,2);
INSERT INTO stanza VALUES('NS63','2','Christ is God incarnated,<br/>How wonderful! How marvellous!<br/>Incarnated so that He could<br/>Live inside of you and me,<br/>He’s mingling now with us.<br/><br/>Christ is God incarnated,<br/>He became the first God-man.<br/>Oh! How glorious!<br/>Now He lives inside of us,<br/>Fulfilling God’s great plan.<br/>',NULL,19593,3);
INSERT INTO stanza VALUES('NS64','1','There’s a man who died to set us free.<br/>Everybody knows it’s Jesus;<br/>He came down from heaven just to live in me.<br/>Everybody knows it’s Jesus!<br/>',NULL,19594,1);
INSERT INTO stanza VALUES('NS64','chorus','Jesus, Jesus,<br/>Everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,19595,2);
INSERT INTO stanza VALUES('NS64','2','There’s no other name on which to call,<br/>So open up and call on Jesus;<br/>Stop your doubting and start to call,<br/>Just open up and call on Jesus!<br/>',NULL,19596,3);
INSERT INTO stanza VALUES('NS64','3','Jesus fills the empty places with Himself,<br/>Come along and call, “Lord Jesus!“<br/>Listen closely while we tell you ’bout His wealth,<br/>Come along and call, “Lord Jesus!”<br/>',NULL,19597,4);
INSERT INTO stanza VALUES('NS64','4','God’s been waiting just to get inside of you,<br/>So turn to Him and call, “Lord Jesus!“<br/>Open up your heart and let Him into you<br/>By calling on the name of Jesus!<br/>',NULL,19598,5);
INSERT INTO stanza VALUES('NS65','1','I love God because He loved me long before the world began.<br/>I love God because He knew my destiny.<br/>I love God because He made me part of His eternal plan.<br/>I love God because He first loved me.<br/>',NULL,19599,1);
INSERT INTO stanza VALUES('NS65','chorus','I love Him for all the things He’s done for me.<br/>I love Him for all that He is, all that He is to me.<br/>But, most of all, I love Him as the Spirit<br/>Who deep within my spirit lives.<br/>',NULL,19600,2);
INSERT INTO stanza VALUES('NS65','2','I love God because He came in time to be the Son of Man.<br/>I love God because He gave Himself for me.<br/>I love God because He conquered death that I might live in Him.<br/>I love God because He first loved me.<br/>',NULL,19601,3);
INSERT INTO stanza VALUES('NS65','3','I love God because He’s processed now to be my life within.<br/>I love God because He is transforming me.<br/>I love God because He’s building up the New Jerusalem.<br/>I love God because He still loves me.<br/>',NULL,19602,4);
INSERT INTO stanza VALUES('NS66','1','Arise! Arise! And open up your heart,<br/>Christ will come in and life to you impart.<br/>As the Spirit He is now our bountiful supply<br/>And all our need His life will satisfy.<br/>',NULL,19603,1);
INSERT INTO stanza VALUES('NS66','2','Arise! Arise! And open up your mouth,<br/>Join in the praise and let your spirit out.<br/>He is rich unto all those who call upon His name;<br/>Together now His riches we proclaim.<br/>',NULL,19604,2);
INSERT INTO stanza VALUES('NS67','1','In the church life we can see<br/>We are God’s own family.<br/>As we blend with the saints<br/>We are built up in love,<br/>His expression thus to be.<br/>',NULL,19605,1);
INSERT INTO stanza VALUES('NS67','chorus','In the church we are home;<br/>Here our joy has begun.<br/>In this sweet fellowship<br/>We are built up in love<br/>As the many, yet as one.<br/>',NULL,19606,2);
INSERT INTO stanza VALUES('NS67','2','In each member we can see<br/>Our God in humanity;<br/>As each functions in life,<br/>Christ is then manifest<br/>Through His Body practic’ly.<br/>',NULL,19607,3);
INSERT INTO stanza VALUES('NS67','3','As we gather we can see<br/>One expression, corp’rately;<br/>As His Body on earth,<br/>Now Christ’s riches we share<br/>In the church life, heavenly!<br/>',NULL,19608,4);
INSERT INTO stanza VALUES('NS68','1','Here we are gathered, one family in the Lord;<br/>His life is the bond that we share.<br/>Although we are many, we are in one accord,<br/>And as the members, know the family care.<br/>',NULL,19609,1);
INSERT INTO stanza VALUES('NS68','chorus','And blending with the saints we know,<br/>Our joy has just begun;<br/>We blend together and we blend as one.<br/>And blending with the saints we know,<br/>The building has begun;<br/>We build together and we build as one.<br/>',NULL,19610,2);
INSERT INTO stanza VALUES('NS68','2','When we’re together our joy is made so full;<br/>The love of the Lord fills our hearts,<br/>And we all partake of the Spirit bountiful.<br/>We’ve found, here in the family life, a part.<br/>',NULL,19611,3);
INSERT INTO stanza VALUES('NS68','3','Here we will stay, Lord, according to Your plan,<br/>For here in the church life we’re one;<br/>And we will be built up to be the corp’rate man<br/>To consummate the New Jerusalem.<br/>',NULL,19612,4);
INSERT INTO stanza VALUES('NS69','1','Jesus won’t You come, won’t You come, won’t You come,<br/>We say to our Bridegroom come.<br/>Jesus won’t You come, won’t You come, won’t You come,<br/>We say to our Bridegroom come.<br/>',NULL,19613,1);
INSERT INTO stanza VALUES('NS69','2','Blend us all us one, all as one<br/>That we will be a Bride that matches You perfectly.<br/>Make us all to be, all to be, all to be<br/>The expression of Your glory.<br/>',NULL,19614,2);
INSERT INTO stanza VALUES('NS69','chorus','Oh, our love!<br/>We know You are longing for Your Bride!<br/>Lord, we long that Your heart’s desire would be satisfied.<br/>',NULL,19615,3);
INSERT INTO stanza VALUES('NS70','1','I will not let Thee go, my Lord,<br/>I will not let Thee go!<br/>Confession glad on Thee outpoured,<br/>Thine own dear heart to know.<br/>My heart desires, my lips request<br/>To be of use to Thee,<br/>That in that day I’d share Your rest<br/>Through serving faithfully.<br/>',NULL,19616,1);
INSERT INTO stanza VALUES('NS70','2','And days ahead I shall not fear<br/>I trust Thy sovereign Hand!<br/>So all creation bend and hear<br/>This cry!&nbsp;&nbsp;My joyful stand!<br/>No longer days of sad neglect<br/>Now shall affront my view<br/>Nor sorrowed nights of deep regret<br/>I’ll waste apart from You.<br/>',NULL,19617,2);
INSERT INTO stanza VALUES('NS70','3','Ambition shall no longer keep,<br/>Unyielding grip on me.<br/>While true ’tis pride’s veins do run deep<br/>They’re severed Lord in Thee<br/>It was with joy that Caleb stood<br/>’Hind Joshua on that day.<br/>And glory comes to all who would<br/>Now enter Caleb’s way.<br/>',NULL,19618,3);
INSERT INTO stanza VALUES('NS70','4','Though not through my own efforts vain<br/>Could I e’er make You glad<br/>But through apostles’ teaching gain<br/>The view such brothers had.<br/>And through their practice enter in<br/>My crown in hand that day.<br/>And joy with Your apostles then<br/>Not having turned away.<br/>',NULL,19619,4);
INSERT INTO stanza VALUES('NS70','5','My heart, my soul, I have resigned<br/>Drink off’ring for Your joy.<br/>Imagination&nbsp;&nbsp;ne’er could find<br/>Or want greater employ!<br/>I will not let Thee go my Lord,<br/>I will not let Thee go!<br/>Confession glad on Thee outpoured,<br/>Thine own dear heart to know.<br/>',NULL,19620,5);
INSERT INTO stanza VALUES('NS71','1','I have lived my life by myself,<br/>Never letting You get too close to me,<br/>Kept my heart preoccupied with empty things;<br/>My eyes have failed to see.<br/><br/>But You had called me,<br/>How could I explain,<br/>All the things I thought were real were vain.<br/>',NULL,19621,1);
INSERT INTO stanza VALUES('NS71','2','Deceived by sin since cunning words<br/>He made me hold in things that fade away<br/>He weighs my ears, and keeps me bound;<br/>Never letting me out of his domain.<br/><br/>And then You freed me,<br/>Transferred from the place,<br/>Brought into the kingdom of Your grace.<br/>',NULL,19622,2);
INSERT INTO stanza VALUES('NS71','3','Bring me to be with others, Lord,<br/>That we express Your Person corporately.<br/>A living stone for building now,<br/>Make us to be Your Body, one with Thee.<br/><br/>Lord, keep growing,<br/>Your building would complete, <br/>One in Christ for all the world to see.<br/>',NULL,19623,3);
INSERT INTO stanza VALUES('NS72','1','He’s the Spirit of reality,<br/>Pneumatic Christ, the Firstborn Son in me,<br/>The consummation of the Triune God,<br/>Life-giving Spirit, all-inclusive Christ<br/>&nbsp;&nbsp; Intensified sevenfold.<br/>',NULL,19624,1);
INSERT INTO stanza VALUES('NS72','2','He’s the Spirit of Reality.<br/>He’s the secret. He is one with me;<br/>He’s in my spirit. God dispensed in me<br/>From my spirit, soul and then, body,<br/>&nbsp;&nbsp; Producing reality.<br/>',NULL,19625,2);
INSERT INTO stanza VALUES('NS72','3','Don’t be fooled by outward circumstance.<br/>Lord, do grant us visions and a trance:<br/>The New Jerusalem, a mingling<br/>A mutual dwelling place of God and man.<br/>&nbsp;&nbsp; Lord, You’re reality!<br/>',NULL,19626,3);
INSERT INTO stanza VALUES('NS72','4','Seven Spirits and the seven eyes,<br/>Organic salvation He intensifies,<br/>Producing overcomers in this age,<br/>To build His Body and to consummate<br/>&nbsp;&nbsp; The New Jerusalem.<br/>',NULL,19627,4);
INSERT INTO stanza VALUES('NS73','1','Trust in Jehovah with all your heart,<br/>Do not rely on your own understanding.<br/>In all your ways acknowledge Him,<br/>And He will make your paths straight.<br/>O the depth of the riches<br/>And wisdom and knowledge of God!<br/>How unsearchable are His judgments<br/>And untraceable His ways!<br/>Because out from Him and through Him<br/>And to Him are all things.<br/>To Him be the glory forever. Amen.<br/>',NULL,19628,1);
INSERT INTO stanza VALUES('NS74','1','Jesus, O living Word of God,<br/>Wash me and cleanse me with Your blood<br/>So You can speak to me.<br/><br/>Just let me hear Your words of grace,<br/>Just let me see Your radiant face,<br/>Beholding constantly.<br/><br/>Jesus, living Word,<br/>My heart thirsts for Thee;<br/>Of Thee I’d eat and drink,<br/>Enjoy Thee thoroughly.<br/>',NULL,19629,1);
INSERT INTO stanza VALUES('NS74','2','Jesus, most precious One to me,<br/>I want to seek You constantly<br/>So you can spread through me.<br/><br/>I would just call upon Your name,<br/>Open to you; I have no shame<br/>Loving You, Jesus Lord.<br/><br/>Jesus, precious One,<br/>Be so real to me.<br/>You are all I want;<br/>I open wide to Thee.<br/>',NULL,19630,2);
INSERT INTO stanza VALUES('NS74','3','Jesus, Oh living One in me,<br/>Open my eyes that I might see<br/>All that You are to me.<br/><br/>Just let me enter in Your heart,<br/>Never from You would I depart,<br/>Loving You constantly.<br/><br/>Jesus, living One,<br/>Flood me thoroughly;<br/>Take my willing heart<br/>And overcome in me.<br/>',NULL,19631,3);
INSERT INTO stanza VALUES('NS74','4','Lord I want You to have Your way,<br/>Save me from being Satan’s prey,<br/>I am believing You.<br/><br/>All I can give to You, my Lord,<br/>Is my whole being, love outpoured;<br/>Lord, I belong to You.<br/><br/>Jesus, faithful God,<br/>Gain us through and through;<br/>Use us thoroughly<br/>To see Your purpose through.<br/>',NULL,19632,4);
INSERT INTO stanza VALUES('NS75','1','From my spirit, when I’m sensing the supply<br/>Of God’s speaking, from a fount that ne’er runs dry,<br/>And within me comes a fresh and sweet supply,<br/>Then I’ve got to open up and water you.<br/>',NULL,19633,1);
INSERT INTO stanza VALUES('NS75','chorus','Water you, water you,<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I’ll surely testify,<br/>I’ll stand up, release my Christ and water you!<br/>',NULL,19634,2);
INSERT INTO stanza VALUES('NS75','2','In the meeting, when the spirit’s rising high,<br/>And it seems like we will go beyond the sky—<br/>I can’t help it, I must speak or else I’ll die,<br/>For my Christ is rising up to water you.<br/>',NULL,19635,3);
INSERT INTO stanza VALUES('NS75','3','Should a pause come, or the meeting ebb real low,<br/>While within me there’s a rich and living flow,<br/>Then I’ll stand up, so that all the saints will know,<br/>That I’m here to share my Christ and water you.<br/>',NULL,19636,4);
INSERT INTO stanza VALUES('NS75','4','In the church life, in our daily living too,<br/>In the meeting, and in everything we do,<br/>Christ is speaking and the Spirit’s breaking through,<br/>That is why there’s the supply to water you.<br/>',NULL,19637,5);
INSERT INTO stanza VALUES('NS76','1','The Lord has put me in the Body,<br/>He has made a member out of me;<br/>I’m leaving all the things on the tree of knowledge,<br/>And learning how to eat the living tree.<br/>Well now I’m taking in much more of Jesus!<br/>He’s put me on His farm here just to grow,<br/>We’re only here because we love our Jesus,<br/>We stand as ONE so all the world will know.<br/>',NULL,19638,1);
INSERT INTO stanza VALUES('NS76','2','The Lord doesn’t need more individuals,<br/>He’s got too many now, it’s plain to see;<br/>All He wants is One New Man forever,<br/>And that doesn’t leave any room for you and me.<br/>The only way that we’ll be one is Jesus!<br/>The only way for Him to gather us,<br/>Is by our EATING, DRINKING, BREATHING JESUS!<br/>Until His riches overflow in us!<br/>',NULL,19639,2);
INSERT INTO stanza VALUES('NS76','3','The Lord has put me in the church life,<br/>Christ and the church, His image to express;<br/>He’s chosen me according to His purpose,<br/>And won’t be satisfied with something less.<br/>The only way that we’ll be one is Jesus!<br/>The only way for Him to gather us,<br/>Is by our EATING, DRINKING, BREATHING JESUS!<br/>Until His riches overflow in us!<br/>',NULL,19640,3);
INSERT INTO stanza VALUES('NS77','1','I called upon Thy name, O Lord,<br/>Out of a low dungeon.<br/>Thou hast heard my voice, O Lord,<br/>Thou hast heard my voice:<br/>Hide not Thine ear at my breathing, at my cry.<br/>Hide not Thine ear at my breathing, at my cry.<br/>',NULL,19641,1);
INSERT INTO stanza VALUES('NS78','1','Lord Jesus, You’re lovely.<br/>You’re more to be desired,<br/>Than any earthly pleasure.<br/>You’re fine, beyond compare.<br/>Lord Jesus, Your beauty<br/>Does far exceed all others.<br/>You’re comely and You’re tender.<br/>You’re radiant and You’re fair.<br/>',NULL,19642,1);
INSERT INTO stanza VALUES('NS78','2','When I behold You Jesus,<br/>You draw my heart completely.<br/>I cannot turn away Lord,<br/>I rest in Your embrace;<br/>And time is gone there’s only<br/>Your holy, matchless presence<br/>Abiding in You, gazing<br/>Upon Your glorious face.<br/>',NULL,19643,2);
INSERT INTO stanza VALUES('NS78','3','I give my life to You Lord,<br/>For You alone are worthy.<br/>There’s nothing and there’s no one<br/>That I desire but You.<br/>May all my days be Yours, Lord,<br/>My heart be given to love You,<br/>To treasure and to serve You<br/>By Your sufficient grace.<br/>',NULL,19644,3);
INSERT INTO stanza VALUES('NS79','1','Praise the Lord, God sent His Son,<br/>Hallelujah!<br/>And salvation’s work was done,<br/>Glory to God!<br/>God Himself became a man,<br/>So that we might live in Him.<br/>',NULL,19645,1);
INSERT INTO stanza VALUES('NS79','chorus','That’s why I call on Him,<br/>I give my all to Him.<br/>',NULL,19646,2);
INSERT INTO stanza VALUES('NS79','2','For us He was crucified,<br/>Hallelujah!<br/>For the many, one Man died,<br/>Glory to God!<br/>One grain fell into the earth,<br/>Many grains to bring to birth.<br/>',NULL,19647,3);
INSERT INTO stanza VALUES('NS79','3','He arose in victory,<br/>Hallelujah!<br/>From the grave, triumphantly,<br/>Glory to God!<br/>Now in resurrection He<br/>As the Spirit lives in me.<br/>',NULL,19648,4);
INSERT INTO stanza VALUES('NS79','4','Call on Him from deep within,<br/>Hallelujah!<br/>Just by calling, He comes in,<br/>Glory to God!<br/>Once you call upon His name,<br/>Nevermore you’ll be the same.<br/>',NULL,19649,5);
INSERT INTO stanza VALUES('NS79','chorus','We all must call on Him,<br/>We give our all to Him.<br/>',NULL,19650,6);
INSERT INTO stanza VALUES('NS80','1','Our Christ is so enjoyable,<br/>His life is so applicable;<br/>He lives in us to cause the flow<br/>To reach the world, His life to show.<br/>Oh saints, don’t just sit idly by;<br/>Rise up! Your gift do not despise;<br/>Let’s eat and drink of this sweet Christ!<br/>',NULL,19651,1);
INSERT INTO stanza VALUES('NS80','chorus','Let’s enjoy Christ to reach the goal,<br/>Partake of Him to beat the foe,<br/>All His vast riches we extol,<br/>Yes, we are freed from every woe!<br/>We may not know a lot of things,<br/>But we are kept from Satan’s stings<br/>By eating Christ, and Christ alone!<br/>',NULL,19652,2);
INSERT INTO stanza VALUES('NS80','2','We all can do so many things,<br/>But first of all to Christ we’ll cling;<br/>Enjoy Him, blessings then He’ll bring,<br/>His life-supply means everything!<br/>Enjoy Him—grace He will bestow,<br/>And we’ll be led to join the flow;<br/>Yes, we will do all things in Him.<br/>',NULL,19653,3);
INSERT INTO stanza VALUES('NS81','1','How I love Your reigning life, Lord.<br/>How I love abundant grace.<br/>How I love to have Your presence,<br/>As I live before Your face.<br/>',NULL,19654,1);
INSERT INTO stanza VALUES('NS81','chorus','By Your life, Lord, I am reigning.<br/>I am over, over everything.<br/>As I’m joyfully confessing,<br/>Jesus, as my Lord and King.<br/>',NULL,19655,2);
INSERT INTO stanza VALUES('NS81','2','Sin, you helpless little fellow,<br/>Lost your pow’r on Calvary.<br/>I have made exchange of masters,<br/>Now it’s Christ who rules in me.<br/>',NULL,19656,3);
INSERT INTO stanza VALUES('NS81','3','World, with all your little trappings,<br/>You oppress with doubts and cares.<br/>I have found a new provider,<br/>My anxiety He bears.<br/>',NULL,19657,4);
INSERT INTO stanza VALUES('NS81','4','Self, you cruel manipulator,<br/>You are wholly crucified,<br/>I have no more need to struggle,<br/>In Christ’s vict’ry I abide!<br/>',NULL,19658,5);
INSERT INTO stanza VALUES('NS81','5','Lord, when You return in glory,<br/>When You then the kingdom bring;<br/>By Your life my Lord then make me<br/>Manifested as a king.<br/>',NULL,19659,6);
INSERT INTO stanza VALUES('NS82','1','I once was dead—dead in my sins;<br/>Behaved myself in lust of flesh.<br/>By nature such a child of wrath,<br/>Even as the rest.<br/>',NULL,19660,1);
INSERT INTO stanza VALUES('NS82','2','But God being so merciful<br/>Because of His great love to me<br/>Enlivened me I’m now in Christ<br/>Seated in the heavenlies.<br/>',NULL,19661,2);
INSERT INTO stanza VALUES('NS82','3','But that’s not all! I’m with the saints.<br/>Together we’re His workmanship,<br/>His masterpiece expressing Him<br/>In the heavens and on earth.<br/>',NULL,19662,3);
INSERT INTO stanza VALUES('NS82','4','I was once apart from Christ, you know;<br/>Alien from the wealth of Israel;<br/>Not a hope—not even one to tell,<br/>Without God in the world.<br/>',NULL,19663,4);
INSERT INTO stanza VALUES('NS82','5','Now in Christ He has become my peace;<br/>By the blood of Christ I am released.<br/>I am one with all the saints, since He’s<br/>Broken down the middle wall.<br/>',NULL,19664,5);
INSERT INTO stanza VALUES('NS82','6','He has died creating one new man.<br/>Thus fulfilling God’s eternal plan.<br/>With all saints together, let us stand,<br/>Shout and sing and praise the Lord!<br/>',NULL,19665,6);
INSERT INTO stanza VALUES('NS83','1','Oh! Let us sing joyfully. Sing an unveiled mystery.<br/>We enjoy the realm of the Spirit now,<br/>The divine and mystical reality.<br/>Oh! Enjoy! Sing! Rejoice!<br/>&nbsp;&nbsp; This divine mystery!<br/>&nbsp;&nbsp; We enjoy the realm of the Spirit now,<br/>&nbsp;&nbsp; The divine and mystical reality.<br/>',NULL,19666,1);
INSERT INTO stanza VALUES('NS83','2','Oh! You are the Spirit, Lord, in my spirit one with me<br/>When I touch the life-giving Spirit now<br/>I am one with You and You are one with me.<br/>&nbsp;&nbsp; Oh! Experience of God in the Spirit of life.<br/>&nbsp;&nbsp; When I touch the life-giving Spirit now<br/>&nbsp;&nbsp; I am one with You and You are one with me.<br/>',NULL,19667,2);
INSERT INTO stanza VALUES('NS83','3','Oh! I’m saved organic’ly, growing to maturity.<br/>Now from sin, the world and the self I’m free<br/>In the Spirit who is sanctifying me.<br/>&nbsp;&nbsp; Oh His nature in me sanctifies thoroughly;<br/>&nbsp;&nbsp; Now from sin, the world and the self I’m free<br/>&nbsp;&nbsp; In the Spirit who is sanctifying me.<br/>',NULL,19668,3);
INSERT INTO stanza VALUES('NS83','4','Oh! In spirit we’re transformed, to the Son we are conformed.<br/>He’s the resurrected, surpassing One;<br/>Who is formed and constituted within me.<br/>&nbsp;&nbsp; Oh! Transformed! Oh! Conformed! To the image of the Son!<br/>&nbsp;&nbsp; He’s the resurrected, surpassing One;<br/>&nbsp;&nbsp; Who is formed and constituted within me.<br/>',NULL,19669,4);
INSERT INTO stanza VALUES('NS83','5','Oh! May I be one with Thee, an expression of glory.<br/>Once a vessel rough, full of dishonor<br/>Now I grow up into Thee organically.<br/>&nbsp;&nbsp; Oh! This life! Glorious! Reaching full maturity!<br/>&nbsp;&nbsp; Once a vessel rough, full of dishonor<br/>&nbsp;&nbsp; Now I grow up into Thee organically.<br/>',NULL,19670,5);
INSERT INTO stanza VALUES('NS84','1','It is God who firmly attaches us,<br/>It is God who firmly attaches us,<br/>It is God who firmly attaches us,<br/>With you unto Christ.<br/>',NULL,19671,1);
INSERT INTO stanza VALUES('NS84','chorus','It is God, it is us,<br/>It is Christ as the Spirit.<br/>',NULL,19672,2);
INSERT INTO stanza VALUES('NS84','2','It is God who has anointed us,<br/>It is God who has anointed us,<br/>It is God who has anointed us,<br/>With the Spirit in our hearts.<br/>',NULL,19673,3);
INSERT INTO stanza VALUES('NS85','1','Set your mind on the things that are above,<br/>Not on the things that are on earth.<br/>For you have died and your life—<br/>Is hid with Christ in God.<br/>When Christ Who is our life—shall appear,<br/>Then we also shall appear<br/>With Him in GLORY!<br/>',NULL,19674,1);
INSERT INTO stanza VALUES('NS86','1','Come, all ye saints, and sing with me.<br/>His love and joy have set me free.<br/>The greatest Savior ever, He!<br/>Come praise and sing in Jubilee!<br/>',NULL,19675,1);
INSERT INTO stanza VALUES('NS86','chorus','He changed my life with one simple call.<br/>He gained my heart to love Him o’er all.<br/>And now I will praise Him, and tell the whole world.<br/>I love my Jesus forevermore!<br/>',NULL,19676,2);
INSERT INTO stanza VALUES('NS86','2','Our Lord has been anointed for<br/>Announcing good news to the poor,<br/>Release to captives—ye much more—<br/>The blind, their sight He has restored.<br/>',NULL,19677,3);
INSERT INTO stanza VALUES('NS86','3','You, Lord, have sent away, released,<br/>Those once oppressed, whose bondage ceased.<br/>You have proclaimed today to be<br/>God’s promised year of Jubilee.<br/>',NULL,19678,4);
INSERT INTO stanza VALUES('NS86','4','Lord, You have now fulfilled God’s Word;<br/>Your proclamation we have heard.<br/>We join with You, our hearts You’ve stirred;<br/>God’s kingdom’s here, the age has turned.<br/>',NULL,19679,5);
INSERT INTO stanza VALUES('NS87','1','Let’s mingle and blend,<br/>Our hearts knit again,<br/>In the family of God.<br/>Let’s mingle and blend,<br/>Our hearts knit again,<br/>With our family of God.<br/>',NULL,19680,1);
INSERT INTO stanza VALUES('NS87','chorus','Isn’t it pure and fine?<br/>Isn’t it right and holy?<br/>Isn’t it noble, true?<br/>Isn’t it sweet and lovely?<br/>',NULL,19681,2);
INSERT INTO stanza VALUES('NS87','2','Open up your heart, <br/>Open up your home,<br/>Open up your mouth,<br/>Open up your song,<br/>Open up your life,<br/>Open up your time,<br/>Open up your poem,<br/>Open up your rhyme.<br/>',NULL,19682,3);
INSERT INTO stanza VALUES('NS87','3','How we love one another!<br/>We are sisters! We are brothers!<br/>How our hearts fill with love<br/>When we think on things above!<br/>',NULL,19683,4);
INSERT INTO stanza VALUES('NS87','4','Let’s mingle and blend...<br/>Our hearts knit again...<br/>In the spirit of love...<br/>In the fam’ly of God.<br/>',NULL,19684,5);
INSERT INTO stanza VALUES('NS88','1','What a wonderful church life,<br/>All the saints truly are one,<br/>No matter where and who we are,<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>Nothing can set us apart,<br/>For we have the same life,<br/>Although Satan tried and tried,<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>',NULL,19685,1);
INSERT INTO stanza VALUES('NS88','chorus','We are, we are, we are one in Christ!<br/>Abiding in the true vine,<br/>Receiving all the riches of the life divine,<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>We are, we are, we are one in Christ!<br/>Growing in the tree of life,<br/>In Him we fellowship unto eternal life,<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>',NULL,19686,2);
INSERT INTO stanza VALUES('NS88','2','What a glorious church life,<br/>Christ in us has made us one,<br/>Eating the tree of life,<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>How can we ever depart<br/>Such a sweet and blessed life?<br/>Christ in us and we in Christ!<br/>&nbsp;&nbsp;&nbsp;&nbsp;We are one!<br/>',NULL,19687,3);
INSERT INTO stanza VALUES('NS89','1','My Savior the good Shepherd is,<br/>He’ll never leave the flock.<br/>The One Who truly loves the sheep,<br/>Became the Lamb of God.<br/>Despised, afflicted in my stead,<br/>He spent His soul for me.<br/>And to the slaughter He was led,<br/>That I not thirsty be.<br/>',NULL,19688,1);
INSERT INTO stanza VALUES('NS89','2','My Shepherd is the Lamb of God,<br/>He calls to me each day,<br/>To drink the waters flowing free,<br/>From His pierced side of grace.<br/>Yet when I stray or choose my way,<br/>He still would search for me,<br/>And bring me home on shoulders strong.<br/>Do I not His love see?<br/>',NULL,19689,2);
INSERT INTO stanza VALUES('NS89','3','My Shepherd’s face is how I live,<br/>I love to look at Him.<br/>Though He might lead through shearing trial,<br/>But still I follow Him.<br/>Just as the Father’s presence cheered <br/>Him through each suffering day,<br/>’Tis once I saw His tender care<br/>That here I want to stay.<br/>',NULL,19690,3);
INSERT INTO stanza VALUES('NS89','4','Oh, Father thank You for Your Son,<br/>He shares Your heart for us.<br/>That gladly He would bear us to<br/>The bosom of Your love.<br/>No greater Shepherd could there be,<br/>That He would not lose one!<br/>And lead us all to dwell with You.<br/>Sweet Pasture, Living Stream.<br/>',NULL,19691,4);
INSERT INTO stanza VALUES('NS90','1','How could this age be so dark, Lord?<br/>All around persecute You.<br/>Though cruel religion would slay You,<br/>No one takes thought or concern.<br/>While Your heart ached for God’s chosen,<br/>We were just lepers You cleansed.<br/>While they reject Your speaking,<br/>We were the dead ones You raised.<br/>While they despised Your Person,<br/>We are the grateful You saved.<br/><br/>Lord, we’re so glad to be<br/>The house in Bethany.<br/>We bid You rest and eat,<br/>Come, we’ve prepared for Thee.<br/>',NULL,19692,1);
INSERT INTO stanza VALUES('NS90','2','Safe in this house, Lord You’re cherished,<br/>We treasure You above all!<br/>We grasp the chance to be with You,<br/>Your presence our greatest joy.<br/>Comfort Your heart with our tears, Lord,<br/>Wash the world’s hatred away.<br/>May we serve You a meal, Lord?<br/>May we share in Your trial?<br/>May we prepare Your Body?<br/>May our love satisfy.<br/><br/>Oh! We are blessed to be,<br/>Your house in Bethany.<br/>Sharing Your table, we<br/>Focus our gaze on Thee.<br/>',NULL,19693,2);
INSERT INTO stanza VALUES('NS90','3','Lord, in our eyes You are worthy,<br/>And what we have, Lord, we give.<br/>Breaking our flask we anoint Thee,<br/>What is most precious we spend.<br/>All our heart’s ointment so costly,<br/>Lord, we pour out on Thee.<br/>May all the house be filled, Lord,<br/>With fragrance sweet to Thee.<br/>May Your whole church then hunger,<br/>With more desire for Thee.<br/><br/>Lord, may we always be,<br/>With You in Bethany.<br/>Our free will offering,<br/>The best, poured out on Thee.<br/>',NULL,19694,3);
INSERT INTO stanza VALUES('NS91','1','Make me a hungry seeker,<br/>Your filling to receive.<br/>Make mine a longing soul, Lord,<br/>Your goodness satisfy me.<br/>If I’m not hungry empty within,<br/>Your blessing will pass me by.<br/>Make me a hungry seeker, Lord,<br/>I want Your rich supply.<br/>',NULL,19695,1);
INSERT INTO stanza VALUES('NS91','2','My eyes be set on You, Lord;<br/>Each pleasure and each pain<br/>Would make me look at You, Lord,<br/>God’s riches and grace to gain.<br/>If I am full and think I’m rich,<br/>Empty, You’ll send me away;<br/>Continually I’m hungry, Lord.<br/>My heart on You will stay.<br/>',NULL,19696,2);
INSERT INTO stanza VALUES('NS92','1','We’d experience Christ daily,<br/>Him we would constantly pursue.<br/>Our pursuing has a purpose<br/>To build His Body is our view.<br/>',NULL,19697,1);
INSERT INTO stanza VALUES('NS92','chorus','Occupy us for Your Body.<br/>Grace supplying, You afford.<br/>Always bearing, always caring,<br/>By Your grace we’d be outpoured.<br/>',NULL,19698,2);
INSERT INTO stanza VALUES('NS92','2','Grant us, Lord, a willing spirit.<br/>To build Your Body we would strive.<br/>By our measure we would function,<br/>Until full grown we’d all arrive.<br/>',NULL,19699,3);
INSERT INTO stanza VALUES('NS92','3','As the members of His Body,<br/>Each one is now a life supply.<br/>Serving Christ to one another,<br/>In love, His Body built thereby.<br/>',NULL,19700,4);
INSERT INTO stanza VALUES('NS93','1','I’ve got a story you should know,<br/>Happened many years ago,<br/>Long before this world was known to you or me.<br/>A man named Jesus came and died,<br/>On the cross was crucified.<br/>There He gave Himself to set all people free!<br/>',NULL,19701,1);
INSERT INTO stanza VALUES('NS93','2','You see, this world was lost in sin,<br/>People’s hearts were dark within,<br/>But God loved us just too much to let us go.<br/>So then He sent His only Son<br/>’Cause He knew he needed One<br/>Who could rescue all His loved ones here below.<br/>',NULL,19702,2);
INSERT INTO stanza VALUES('NS93','3','At first nobody would believe,<br/>And they failed to receive<br/>The free gift of life that only He could give.<br/>But when He died that awful day,<br/>He took all our sins away,<br/>That to Him we might now look and, thereby, live.<br/>',NULL,19703,3);
INSERT INTO stanza VALUES('NS93','4','So won’t you open from within,<br/>Let Him take away your sin,<br/>’Cause He’d like to be your Savior tried and true.<br/>And you will never be the same,<br/>Once you call upon His name,<br/>And His wonderful salvation reaches you!<br/>',NULL,19704,4);
INSERT INTO stanza VALUES('NS94','1','To be set free from the bond of sin,<br/>To have the joy and peace within,<br/>To live a life full of meaning,<br/>Believe into the Lord.<br/>Man’s way to please God—religion;<br/>God’s way—a living Person;<br/>Christ is God’s way of salvation;<br/>Believe and you’ll be saved.<br/>',NULL,19705,1);
INSERT INTO stanza VALUES('NS94','chorus','It pleases God to rescue us<br/>Out of this present evil age,<br/>And to reveal His Son in us—<br/>Most peerless One of all!<br/>',NULL,19706,2);
INSERT INTO stanza VALUES('NS94','2','We have received Christ the Spirit<br/>Through faith and not our merit;<br/>Having begun by the Spirit,<br/>We learn to live by faith.<br/>We are the sons of the living God,<br/>Enjoy the blessings of our Lord,<br/>Grace to our spirit He doth afford,<br/>From our self-effort freed.<br/>',NULL,19707,3);
INSERT INTO stanza VALUES('NS94','3','Oh what a joy! Christ now lives in us;<br/>No longer I—how glorious!<br/>He’s daily growing within us<br/>Till He is formed in us.<br/>We live and walk by the Spirit,<br/>Enjoy the fruit of the Spirit;<br/>To Him our whole lives we commit;<br/>All else is vanity.<br/>',NULL,19708,4);
INSERT INTO stanza VALUES('NS95','1','May my day be full of Christ.<br/>May my words be spoken in Him.<br/>May my being find rest<br/>Lying on His sweet breast,<br/>May my day be full of Christ.<br/>',NULL,19709,1);
INSERT INTO stanza VALUES('NS95','2','May my mind be filled with His light,<br/>May my spirit be shining so bright,<br/>May His life bear much fruit,<br/>May I be absolute,<br/>To partake of the living Christ.<br/>',NULL,19710,2);
INSERT INTO stanza VALUES('NS96','1','If there is no resurrection,<br/>God would be God of the dead;<br/>Christ Himself would not be living,<br/>N’er have been raised from the dead.<br/>',NULL,19711,1);
INSERT INTO stanza VALUES('NS96','chorus','But there is a resurrection<br/>Which is the vitality,<br/>Both the life pulse and the life-line<br/>Within God’s economy.<br/>',NULL,19712,2);
INSERT INTO stanza VALUES('NS96','2','If there is no resurrection,<br/>Christ a Savior dead would be,<br/>Not the One Who lives forever,<br/>Who can save most utterly.<br/>',NULL,19713,3);
INSERT INTO stanza VALUES('NS96','3','If there is no resurrection,<br/>Christ a Savior dead would be,<br/>Not the One Who lives forever,<br/>Who can save most utterly.<br/>',NULL,19714,4);
INSERT INTO stanza VALUES('NS96','4','If there is no resurrection<br/>Life imparting would be stayed.<br/>And so would regeneration<br/>With renewing pass away.<br/>',NULL,19715,5);
INSERT INTO stanza VALUES('NS96','5','If there is no resurrection,<br/>Then whatever would there be?<br/>There would be no transformation,<br/>Nor to Christ conformity.<br/>',NULL,19716,6);
INSERT INTO stanza VALUES('NS96','6','If there is no resurrection,<br/>Where the members of the Christ?<br/>There to Him would be no Body,<br/>Which His fullness is in life.<br/>',NULL,19717,7);
INSERT INTO stanza VALUES('NS96','7','If there is no resurrection<br/>Then the church would n’er have been,<br/>Which is both to Christ His dear bride<br/>And to God the one new man.<br/>',NULL,19718,8);
INSERT INTO stanza VALUES('NS96','8','If there is no resurrection<br/>Then would God’s economy,<br/>With the voiding of His purpose,<br/>In collapse fall totally.<br/>',NULL,19719,9);
INSERT INTO stanza VALUES('NS97','1','Dearest Lord, You’ve called us here,<br/>And opened up Your heart.<br/>O the joy to hear Your call<br/>And enter in the Ark.<br/>Saving us from day to day<br/>O Lord, this is Your way.<br/>In Yourself we stay afloat,<br/>Above this wicked age today.<br/>',NULL,19720,1);
INSERT INTO stanza VALUES('NS97','chorus','Thank You Lord, in Your eyes we find grace,<br/>And with open hearts we come to You.<br/>Regardless what our friends might say to us or do,<br/>O Lord Jesus, we love You.<br/>',NULL,19721,2);
INSERT INTO stanza VALUES('NS97','2','Seeking of this age to taste,<br/>And of it have a part.<br/>If we only knew, dear Lord,<br/>The ways we grieve Your heart.<br/>We would come and turn to You<br/>With a repenting heart,<br/>And would give ourselves to be<br/>With you, O Lord, inside the Ark.<br/>',NULL,19722,3);
INSERT INTO stanza VALUES('NS97','3','Praise You Lord, we’re safe in You;<br/>Outside death-waters pour.<br/>Many things that I once loved<br/>Are on the ocean floor.<br/>Keep us open to You Lord,<br/>Don’t let us miss the mark.<br/>Hallelujah, praise the Lord,<br/>We’re here within the church, the Ark.<br/>',NULL,19723,4);
INSERT INTO stanza VALUES('NS98','chorus','I’m walking down the road<br/>That leads to glory.<br/>I’m pressing toward the mark<br/>By enjoying God!<br/>I don’t know so much,<br/>Just to love Him.<br/>I’m walking down the road,<br/>Glory, here I come.<br/>',NULL,19724,1);
INSERT INTO stanza VALUES('NS98','1','With the brothers and the sisters,<br/>We enjoy Him day by day.<br/>It’s so simple and easy,<br/>Our worries flee away.<br/>Now we’re growing together,<br/>As one big family,<br/>Abiding in the joy of the Lord.<br/>',NULL,19725,2);
INSERT INTO stanza VALUES('NS98','2','We enjoy You, Lord Jesus,<br/>In our experience.<br/>We’re getting to know You—<br/>It’s making us leap and dance.<br/>Just eating and drinking,<br/>It’s what we do the best,<br/>Delighting in the love of the Lord.<br/>',NULL,19726,3);
INSERT INTO stanza VALUES('NS98','3','We’re walking, not running,<br/>Cause we’re in the pasture land.<br/>Our Shepherd is nearby,<br/>We’re trusting in His hand.<br/>He’s everything to us,<br/>He’s all we ever need,<br/>Resting in the peace of the Lord.<br/>',NULL,19727,4);
INSERT INTO stanza VALUES('NS99','1','Mary poured out her love offering<br/>To many such love was a waste.<br/>Throughout all of the centuries<br/>Such lovers Your sweetness do taste.<br/>Precious lives and heart treasures, too<br/>Positions and golden futures,<br/>Have been “wasted” on You, Lord;<br/>Your sweetness a fragrance so sure.<br/>She took opportunity<br/>To love You; Lord, with her best.<br/>Like her, Lord, I too would pour<br/>My love and all that I have.<br/>',NULL,19728,1);
INSERT INTO stanza VALUES('NS99','2','As I love You I set my being—<br/>My spirit, my soul and body.<br/>With my heart, my mind, and my strength,<br/>Absolutely on Thee.<br/>Lord, I let my entire being<br/>Be occupied by Thee<br/>As I enter in Your heart<br/>I sense a fellowship sweet.<br/>Occupied and lost in You;<br/>My Lord, You’re my everything.<br/>Fellowship so intimate;<br/>In spirit Lord I enjoy Thee.<br/>',NULL,19729,2);
INSERT INTO stanza VALUES('NS99','3','Lord there’s none in heav’n nor on earth<br/>That I desire but Thee.<br/>Though my heart and flesh faileth, Lord,<br/>Thou ever my portion will be.<br/>All is vanity, all is dung;<br/>I count all other things loss;<br/>Everything else drains my love<br/>But You have captured my heart.<br/>Lord, I’ve seen Thy preciousness,<br/>Thy worth, Thy reality.<br/>Now, my Lord, I must confess<br/>My heart is only for Thee.<br/>',NULL,19730,3);
INSERT INTO stanza VALUES('NS100','1','God the Creator became a God-man,<br/>His death redeemed us for His glorious plan.<br/>Now in resurrection the Spirit’s released<br/>Producing the church.<br/>This is God’s masterpiece.<br/>',NULL,19731,1);
INSERT INTO stanza VALUES('NS100','2','Lord, You are my choice.<br/>I have seen Your beauty.<br/>I belong to You<br/>Now and evermore.<br/>You’re my only choice<br/>Lord, You are so lovely.<br/>Lord I give all for Your masterpiece.<br/>',NULL,19732,2);
INSERT INTO stanza VALUES('NS100','3','Lord, I love You.<br/>There is no other.<br/>I’ll love You always.<br/>Lord, I love You.<br/>My heart is recovered.<br/>Lord, I give all for Your masterpiece.<br/>',NULL,19733,3);
INSERT INTO stanza VALUES('NS100','4','Thank You, Lord Jesus, for capturing me.<br/>Thank You, Lord, I now experience Thee.<br/>By feasting! Enjoying!<br/>Your Life would increase.<br/>Thank You, Lord,<br/>I’m part of God’s masterpiece.<br/>',NULL,19734,4);
INSERT INTO stanza VALUES('NS101','1','And we know that all things work together for good<br/>To those who love God,<br/>Those called according to His purpose.<br/>For who shall separate us from the love of Christ?<br/>In all things we more than conquer through Him who loved us.<br/>Nothing shall separate us from the love of God,<br/>which is in Christ Jesus our Lord.<br/>',NULL,19735,1);
INSERT INTO stanza VALUES('NS102','1','The gift of righteousness is measured in abundance,<br/>The depth of His love I’ll never understand.<br/>His love reaches me and you;<br/>His mercy goes farther too.<br/>The One on the throne of God is called the Lamb.<br/>',NULL,19736,1);
INSERT INTO stanza VALUES('NS102','chorus','So, why not open up and call His name, “Oh Lord!“<br/>Find your spirit where His grace has been outpoured.<br/>Call His name, taste His grace, exercise before His face<br/>He’s longing and yearning.<br/>He’s hoping and waiting.<br/>He’s ever desiring for you...<br/>To turn to Him.<br/>',NULL,19737,2);
INSERT INTO stanza VALUES('NS102','2','He knows your deepest thought,<br/>&nbsp;&nbsp; Your every situation.<br/>He understands your heart,<br/>He knows your history.<br/>There’s nothing in His way,<br/>He’s just waiting for you to say<br/>“Lord Jesus, my wandering heart<br/>&nbsp;&nbsp; I give to Thee.”<br/>',NULL,19738,3);
INSERT INTO stanza VALUES('NS103','1','Now Christ is the life-giving Spirit;<br/>Now Christ is the Spirit today.<br/>Now Christ is the life-giving Spirit;<br/>So turn to your spirit and say—<br/>',NULL,19739,1);
INSERT INTO stanza VALUES('NS103','chorus','O Lord, Amen,<br/>O Lord, Amen, Hallelujah!<br/>O Lord, Amen,<br/>O Lord, Amen, Hallelujah!<br/>',NULL,19740,2);
INSERT INTO stanza VALUES('NS103','2','Now Christ is the life-giving Spirit;<br/>Now Christ is the living Word too.<br/>The Spirit will flow in our spirit,<br/>The Word will be life to us through—<br/>',NULL,19741,3);
INSERT INTO stanza VALUES('NS103','chorus','Praying, reading, praising and<br/>Calling upon His name;<br/>Praying, reading, praising and<br/>Calling upon Him.<br/>',NULL,19742,4);
INSERT INTO stanza VALUES('NS104','chorus','O that Christ may make His home my heart,<br/>Spread Himself in every part!<br/>Saturate and life impart!<br/>That with all saints, I may apprehend<br/>All the vast dimensions of my loving Christ.<br/>',NULL,19743,1);
INSERT INTO stanza VALUES('NS104','1','Father God, forgive me if I groan;<br/>For so long I’ve been on a plateau.<br/>Now with tears, I bow my knees and pray<br/>By Your Spirit make my spirit strong today.<br/>',NULL,19744,2);
INSERT INTO stanza VALUES('NS104','2','As I came this morning to Your word<br/>With no strength to even read a verse;<br/>Yet my plea, is “Lord, I do need You!“<br/>How You strengthen me, Your power within to prove.<br/>',NULL,19745,3);
INSERT INTO stanza VALUES('NS104','3','I myself was losing heart each day;<br/>Then the Lord brought some saints my own way;<br/>I alone could not Thee apprehend<br/>But with all the saints You now my joy have been.<br/>',NULL,19746,4);
INSERT INTO stanza VALUES('NS104','4','All these years I’ve come the church to know,<br/>Yet O Lord, there’re things I can’t let go;<br/>Yet within me there is an “Amen“;<br/>O now joy I never knew in me’s flowin’.<br/>',NULL,19747,5);
INSERT INTO stanza VALUES('NS105','1','Fallen, that’s the way we all begin:<br/>Imprisoned by the evil fate we’re in.<br/>How can we from this hard world of sin<br/>&nbsp;&nbsp;&nbsp;&nbsp;be saved?<br/>',NULL,19748,1);
INSERT INTO stanza VALUES('NS105','chorus','Just by calling, “Jesus, Jesus, Jesus.“<br/>Every moment, each day!<br/>Calling on the name of Jesus—<br/>We’re finding is the way.<br/>It’s Jesus, Lord Jesus!<br/>',NULL,19749,2);
INSERT INTO stanza VALUES('NS105','2','Even though we love the Lord so much,<br/>Somehow, it seems we get out of touch<br/>With Jesus. How can we be freed from such<br/>&nbsp;&nbsp;&nbsp;&nbsp;distress?<br/>',NULL,19750,3);
INSERT INTO stanza VALUES('NS105','3','Sometimes we know we aren’t being real<br/>Then times, we just live by how we feel.<br/>Is there some way we could ever deal<br/>&nbsp;&nbsp;&nbsp;&nbsp;with self?<br/>',NULL,19751,4);
INSERT INTO stanza VALUES('NS105','4','Christians, scattered throughout all the earth<br/>Are wand’ring—Lord, where is Your Bride of worth?<br/>How can all those of the second birth<br/>&nbsp;&nbsp;&nbsp;&nbsp;be one?<br/>',NULL,19752,5);
INSERT INTO stanza VALUES('NS106','1','Until He comes again,<br/>I’ll watch and wait and call on Him<br/>I’ll pray that by His life and power,<br/>I’ll overcome in every hour.<br/>',NULL,19753,1);
INSERT INTO stanza VALUES('NS106','2','Until He comes again,<br/>His blood will cleanse me of my sin<br/>His word will sanctify within,<br/>And make me wholly unto Him.<br/>',NULL,19754,2);
INSERT INTO stanza VALUES('NS106','chorus','(Bro.) He died to be life to me—<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; From death I’m free.<br/>(Sis.) He rose and as Spirit He<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Now lives in me.<br/>(Bro.) In splendor and in glory<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Like Him I’ll be.<br/>',NULL,19755,3);
INSERT INTO stanza VALUES('NS106','3','Until He comes again,<br/>My soul-life I’ll give up for Him.<br/>No worldly pleasure can compare<br/>To what my Savior has to share.<br/>',NULL,19756,4);
INSERT INTO stanza VALUES('NS106','4','And when He comes again,<br/>All saints built up and one in Him.<br/>His Body, Bride, and Counterpart,<br/>Eternal pleasure of His heart.<br/>',NULL,19757,5);
INSERT INTO stanza VALUES('NS106','chorus','(Sis.) Lord, gain Your kingdom in me,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; I long to be...<br/>(Bro.) One with my Savior and King,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Eternally.<br/>(Sis.) Oh, what a joy it will be<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Your face to see.<br/>',NULL,19758,6);
INSERT INTO stanza VALUES('NS107','1','Loving You, Lord’s all I’m living for;<br/>Loving You, Lord, to the uttermost.<br/>Lord, forgive me if I’ve left my first love,<br/>That’s the bridal love to You.<br/>You are more than any one I love.<br/>You are more than anything I have,<br/>Even my dear self; nothing can compare<br/>To my beloved Bridegroom.<br/>',NULL,19759,1);
INSERT INTO stanza VALUES('NS107','chorus','I give You the first place in all things by faith.<br/>Let nothing take Your place in all my heart.<br/>Infuse me with Yourself abundantly<br/>’Til we meet, dear Lord.<br/>I’ll love You with the best love.<br/>',NULL,19760,2);
INSERT INTO stanza VALUES('NS107','2','You’ve the right to take all that I love,<br/>But replace it with Yourself much more.<br/>You are what I need, give Yourself to me,<br/>Do not give all that I want.<br/>Everything is sure to pass away,<br/>Everyone is going their own way.<br/>But I still have You and You have me too,<br/>Loving one another’s sweet.<br/>',NULL,19761,3);
INSERT INTO stanza VALUES('NS107','3','I treasure my time alone with You,<br/>Just to gain the best love You long for.<br/>My dearest Husband, draw me with Yourself<br/>Into Your chambers right now.<br/>Be the first in all my work and life,<br/>Be the first in all my service too.<br/>In relationships, You must be the first;<br/>Have preeminence in me.<br/>',NULL,19762,4);
INSERT INTO stanza VALUES('NS108','1','Your sweetness is just a taste of enjoyment.<br/>Your beauty is simply my heart’s attraction.<br/>Your radiance has captured me.<br/>Your eyes draw things out of me.<br/>I want to daily kiss You and hold on to You.<br/>',NULL,19763,1);
INSERT INTO stanza VALUES('NS108','chorus','O Jesus, I’m crazy loving You.<br/>O Jesus, I’m crazy loving You.<br/>O Jesus, I’m crazy loving You<br/>Until myself is no more.<br/>O Jesus, I’m crazy loving You.<br/>O Jesus, I’m crazy loving You.<br/>O Jesus, I’m crazy loving You<br/>’Til I’m lost in You.<br/>',NULL,19764,2);
INSERT INTO stanza VALUES('NS108','2','Forgetting all that I’m outwardly doing.<br/>Forgetting all of my thoughts of improving.<br/>You only want to be loved,<br/>I give my love unto You;<br/>A crazy lover of Christ, I’m jumping for joy.<br/>',NULL,19765,3);
INSERT INTO stanza VALUES('NS108','3','Yes, my life’s just to love You with my whole being.<br/>Yes, my work’s just to love You with my whole being.<br/>Loving You is my pleasure,<br/>Loving You is my service,<br/>Loving You is my motive and also my will.<br/>',NULL,19766,4);
INSERT INTO stanza VALUES('NS108','4','O my Love, You’ve blinded me towards all things.<br/>O my Love, You make the world simply nothing.<br/>Just let me see You alone,<br/>Just make me need You alone;<br/>None other is there for me, it’s Jesus alone!<br/>',NULL,19767,5);
INSERT INTO stanza VALUES('NS109','chorus','Lord, there’s nothing in this world like You;<br/>You fill me up completely.<br/>And I would never give You up for anything<br/>Because nothing else could satisfy me so.<br/>',NULL,19768,1);
INSERT INTO stanza VALUES('NS109','1','People think that they can find<br/>Satisfaction, peace of mind.<br/>Everything leads to another,<br/>But I’ve found the best.<br/>',NULL,19769,2);
INSERT INTO stanza VALUES('NS109','2','No more trying something else,<br/>Or thinking that there’s something more;<br/>No more hoping “someday,“<br/>’Cause today I have the best.<br/>',NULL,19770,3);
INSERT INTO stanza VALUES('NS109','3','Looking not at failures past,<br/>Hoping not in future dreams;<br/>Not wishing I were different,<br/>Knowing everything’s the best.<br/>',NULL,19771,4);
INSERT INTO stanza VALUES('NS110','1','Life’s too short<br/>To waste a single day<br/>The kingdom’s life<br/>Is closer everyday.<br/>',NULL,19772,1);
INSERT INTO stanza VALUES('NS110','chorus','In the midst of time,<br/>The kingdom’s mine<br/>Just by calling on His name each day.<br/>',NULL,19773,2);
INSERT INTO stanza VALUES('NS110','2','The sweetest taste<br/>Of life is deep within.<br/>Its flowing out<br/>Is primed by calling Him.<br/>',NULL,19774,3);
INSERT INTO stanza VALUES('NS110','chorus','In the midst of time,<br/>The kingdom’s mine<br/>Just by calling on His name each day.<br/>',NULL,19775,4);
INSERT INTO stanza VALUES('NS110','3','Time is quickly<br/>Running out each day.<br/>The Lord will come<br/>And swiftly end this age.<br/>',NULL,19776,5);
INSERT INTO stanza VALUES('NS110','chorus','At the end of time,<br/>The goal we’ll see<br/>The millennium is our entry.<br/>',NULL,19777,6);
INSERT INTO stanza VALUES('NS110','chorus','At the end of time,<br/>The goal we’ll see<br/>The New Jerusalem we’ll be.<br/>',NULL,19778,7);
INSERT INTO stanza VALUES('NS111','1','There’s a gospel of today<br/>That says believe and you’ll be saved and then<br/>You can go to heaven and see the pearly gates<br/>And walk the golden streets;<br/>Words like these fail to treat<br/>All the vanity that is hidden in me.<br/>',NULL,19779,1);
INSERT INTO stanza VALUES('NS111','2','But the gospel is to me<br/>The Triune God within humanity<br/>As the Spirit reaching me to be in me<br/>The one reality;<br/>Love untold—Gospel Thee<br/>Never getting old—story told eternally.<br/>',NULL,19780,2);
INSERT INTO stanza VALUES('NS111','3','Left the ninety-nine behind—<br/>You searched until the lost sheep You did find,<br/>Laid me on Your shoulders there, You bore me in<br/>Your tender loving care;<br/>Rejoicing—You found me<br/>Though a small lost sheep—You gave all to come find me.<br/>',NULL,19781,3);
INSERT INTO stanza VALUES('NS111','4','Sweeping in my deepest parts,<br/>You lit a lamp and searched my inward heart,<br/>Sanctifying deep within You shined in me,<br/>Exposed me of my sin;<br/>Repenting—now I see<br/>Lord, You’re sprinkling me—with the blood You shed for me.<br/>',NULL,19782,4);
INSERT INTO stanza VALUES('NS111','5','Eagerly awaiting me<br/>That I the slightest turn to Thee would make<br/>Though my life had been a wreck, You ran to me<br/>And fell upon my neck<br/>Kissing me, affectionately;<br/>Killed the calf for me—“Let us eat and be merry.”<br/>',NULL,19783,5);
INSERT INTO stanza VALUES('NS112','1','I want to tell You, Lord, how much You mean to me.<br/>Through years of careful molding, Your plan at last I see.<br/>Though pain I’ve had and suffering too,<br/>Myself I yield at last, Lord, to You.<br/>',NULL,19784,1);
INSERT INTO stanza VALUES('NS112','2','I want to care for You, the way You’ve cared for me.<br/>You’ve been my friend to comfort, received me when I’ve strayed.<br/>And in return I offer You<br/>My life so small compared, Lord, to You.<br/>',NULL,19785,2);
INSERT INTO stanza VALUES('NS112','3','I’d like for You to fill me with all that You are.<br/>And empty out my heart from everything You’re not.<br/>You’ve blessed me Lord by finding me.<br/>Possess me now eternally.<br/>',NULL,19786,3);
INSERT INTO stanza VALUES('NS113','1','Bless me, Lord, with days and nights<br/>Of talks alone with Thee,<br/>With hours and minutes, moments too<br/>That I would thus know Thee.<br/>',NULL,19787,1);
INSERT INTO stanza VALUES('NS113','2','Bless me with Thy presence sweet,<br/>For I have naught but Thee;<br/>Yea, nothing left but Thee Thyself,<br/>Lord, give Thyself to me.<br/>',NULL,19788,2);
INSERT INTO stanza VALUES('NS113','3','Bless me with Thy shining light<br/>And deal with every part.<br/>That I would unreserved be<br/>A channel of Thine heart.<br/>',NULL,19789,3);
INSERT INTO stanza VALUES('NS113','4','Bless Thee, Lord, forevermore;<br/>Come in these days between<br/>’Til I one day I am as Thou art<br/>And Morning Star be seen.<br/>',NULL,19790,4);
INSERT INTO stanza VALUES('NS114','1','Nothing’s quite so precious<br/>As Jesus in my spirit.<br/>He takes away the care<br/>And fills me with His peace.<br/>He never leaves me,<br/>E’en as the days grow weary.<br/>His presence goes with me.<br/>My soul delights to hide in His arms.<br/>',NULL,19791,1);
INSERT INTO stanza VALUES('NS114','chorus','I call His name, “Lord Jesus,<br/>Help me in my weakness.“<br/>So faithfully each day in me<br/>He proves His life is so sufficient.<br/>',NULL,19792,2);
INSERT INTO stanza VALUES('NS114','2','Nothing’s quite so precious<br/>As Jesus in my spirit.<br/>He turns my heart to Him,<br/>To feast upon His life.<br/>It’s nothing I do—<br/>His mercy’s just upon me.<br/>And God’s free gift of grace<br/>Becomes an endless joy to me.<br/>',NULL,19793,3);
INSERT INTO stanza VALUES('NS115','1','Good morning, Lord Jesus,<br/>Thank You for today.<br/>Thank You for my spirit,<br/>Thank You I can pray.<br/>Good morning, Lord Jesus,<br/>To You I love to sing.<br/>Thank You, Lord, for everything.<br/>',NULL,19794,1);
INSERT INTO stanza VALUES('NS116','1','Lord, I give myself to You right now.<br/>I want to be occupied with You.<br/>I leave all else behind<br/>And concentrate my being on You alone.<br/>Lord, You are my focus,<br/>You are my goal,<br/>Lord, I give myself to You right now.<br/>Lord, You are my focus,<br/>You are my goal,<br/>Lord, I give myself to You right now.<br/>',NULL,19795,1);
INSERT INTO stanza VALUES('NS117','1','I’m thankful that God has placed me<br/>With you to build up His Body.<br/>Christ in you is the hope for me!<br/>You also need Christ lived in me.<br/>',NULL,19796,1);
INSERT INTO stanza VALUES('NS117','chorus','I live, if you stand firm in the Lord.<br/>You live, if I stand firm in the Lord.<br/>My going on is for you,<br/>Your going on is for me,<br/>Not sep’rate entities,<br/>I need you saints desp’rately!<br/>',NULL,19797,2);
INSERT INTO stanza VALUES('NS117','2','Oh, what a sweet church life have we!<br/>Built up in Him, His bride to be!<br/>In Him steadfast, you help me be;<br/>Encouraged by Christ whom I see.<br/>',NULL,19798,3);
INSERT INTO stanza VALUES('NS117','3','Your faith in Christ helps me pursue;<br/>My progress depends upon you!<br/>As I seek Christ, with you in view,<br/>My heart, full of prayers, is for you.<br/>',NULL,19799,4);
INSERT INTO stanza VALUES('NS117','4','God’s heart longs, desires that we,<br/>His lovers, seek Him corp’rately.<br/>On each other spent constantly;<br/>My life is for you, yours for me.<br/>',NULL,19800,5);
INSERT INTO stanza VALUES('NS117','5','I want to encourage you all,<br/>Without your supply I would fall.<br/>Never think that your Christ is small.<br/>Christ needs you, and so do we all.<br/>',NULL,19801,6);
INSERT INTO stanza VALUES('NS118','1','Jesus Lord, You’re our first love;<br/>You’re the One we love the best.<br/>When our heart is loving You,<br/>How we’re filled with Your sweet rest!<br/>',NULL,19802,1);
INSERT INTO stanza VALUES('NS118','2','Lord, we love You for Yourself,<br/>Not for what You give or do.<br/>Nothing else could e’er compare<br/>With the joy of loving You.<br/>',NULL,19803,2);
INSERT INTO stanza VALUES('NS118','chorus','Lord, we’ve been drawn off by many things;<br/>Now we turn our heart back—how it sings!<br/>We repent of loving other things—<br/>Jesus, Lord, You’re our first love.<br/>',NULL,19804,3);
INSERT INTO stanza VALUES('NS118','3','Never more could we desire<br/>Anything that’s less than You,<br/>And to this we would aspire—<br/>Simply to be filled with You.<br/>',NULL,19805,4);
INSERT INTO stanza VALUES('NS118','4','Jesus Lord, You’re our first love;<br/>You’re the One we love the best.<br/>When our heart is loving You,<br/>How we’re filled with Your sweet rest!<br/>',NULL,19806,5);
INSERT INTO stanza VALUES('NS119','1','There is a song within me;<br/>It’s a song of Jesus moving<br/>In the gardens of my heart.<br/>This Jesus lives within me,<br/>Planting flowers of Himself<br/>There to be watered by my Love.<br/>',NULL,19807,1);
INSERT INTO stanza VALUES('NS119','chorus','I’m loving Jesus, this lovely Person<br/>With personality so strong.<br/>He brought me to Himself<br/>And said to me, “All of your heart’s desire<br/>is found in Me;<br/>I’m all you need and I love you.”<br/>',NULL,19808,2);
INSERT INTO stanza VALUES('NS119','2','There is a peace within me<br/>That has sprung from deep contentment<br/>With my Lord, who’s All in All.<br/>For my delight is in this<br/>Living One inside of me<br/>Who is Himself, my everything.<br/>',NULL,19809,3);
INSERT INTO stanza VALUES('NS120','1','Seek ye first the kingdom of God<br/>And His righteousness;<br/>And all these things shall be added unto you.<br/>Hallelu, Hallelujah!<br/>',NULL,19810,1);
INSERT INTO stanza VALUES('NS120','2','Ask, and it shall be given unto you;<br/>Seek, and you shall find.<br/>Knock, and it shall be opened unto you.<br/>Hallelu, Hallelujah!<br/>',NULL,19811,2);
INSERT INTO stanza VALUES('NS120','3','Man shall not live by bread alone,<br/>But by every word<br/>That proceeds out from the mouth of God.<br/>Hallelu, Hallelujah!<br/>',NULL,19812,3);
INSERT INTO stanza VALUES('NS121','1','Draw me, Lord;<br/>Lest these earthly cares consume<br/>My driven soul.<br/>Move me Lord;<br/>As a coursing river turns<br/>Within Thine hands.<br/>',NULL,19813,1);
INSERT INTO stanza VALUES('NS121','chorus','Draw me, Lord!<br/>Draw me, Lord!<br/>',NULL,19814,2);
INSERT INTO stanza VALUES('NS121','2','Capture me;<br/>Be the conqueror of this<br/>Wild, charging mare.<br/>Win me Lord,<br/>And subdue all pow’r of self<br/>To yield to Thee.<br/>',NULL,19815,3);
INSERT INTO stanza VALUES('NS121','3','Draw me, Lord;<br/>Ev’ry heartbeat tends to drift<br/>My course from Thee.<br/>Draw me, Lord;<br/>I would gladly let Thee win<br/>And yield my sword.<br/>',NULL,19816,4);
INSERT INTO stanza VALUES('NS121','4','Draw me, Lord;<br/>Oh, Thy love compels me as<br/>An ocean’s tide!<br/>Draw me, Lord;<br/>For Thy drawing maketh hearts<br/>To fast pursue.<br/>',NULL,19817,5);
INSERT INTO stanza VALUES('NS122','1','When I’m with the saints,<br/>Happy am I!<br/>Peaceful am I!<br/>Restful am I!<br/>When I’m with the saints,<br/>Joyful am I!<br/>A joy I can’t deny!<br/>',NULL,19818,1);
INSERT INTO stanza VALUES('NS122','2','When I’m with the saints,<br/>Christ we pursue!<br/>Seeking for You!<br/>Here loving You!<br/>When I’m with the saints,<br/>Christ we do share!<br/>And for each member care!<br/>',NULL,19819,2);
INSERT INTO stanza VALUES('NS122','3','When I’m with the saints,<br/>Christ we employ!<br/>Without alloy!<br/>Christ we enjoy!<br/>When I’m with the saints,<br/>Hopeful am I!<br/>They are my life supply!<br/>',NULL,19820,3);
INSERT INTO stanza VALUES('NS122','4','When I’m with the saints,<br/>Christ in them see!<br/>Our hope is He!<br/>Hope of glory!<br/>When I’m with the saints,<br/>Foretaste have we!<br/>Conformed to Him we’ll be!<br/>',NULL,19821,4);
INSERT INTO stanza VALUES('NS122','5','When I’m with the saints,<br/>Christ we await!<br/>Anticipate!<br/>Lord, don’t be late!<br/>When I’m with the saints,<br/>For Christ we yearn!<br/>We long for His return!<br/>',NULL,19822,5);
INSERT INTO stanza VALUES('NS122','6','When I’m with the saints,<br/>You will go on!<br/>I will go on!<br/>Let’s all go on!<br/>When I’m with the saints,<br/>This we affirm!<br/>We live if you stand firm!<br/>',NULL,19823,6);
INSERT INTO stanza VALUES('NS123','chorus','Abide in Me, and I in you,<br/>As the branch cannot bear fruit<br/>Of itself unless<br/>It abides in the vine,<br/>So neither can you<br/>Unless you abide in Me.<br/>',NULL,19824,1);
INSERT INTO stanza VALUES('NS123','1','I am the vine,<br/>You are the branches,<br/>He who abides in Me and I in him.<br/>He bears much fruit<br/>For apart from Me you can do nothing.<br/>',NULL,19825,2);
INSERT INTO stanza VALUES('NS123','2','If you abide in Me and my words abide in you<br/>Ask whatever you will and it will be done for you.<br/>When we abide in the Lord and let His words abide in us,<br/>We actually are one with Him as He works within us.<br/>Then when we ask in prayer for whatever we will<br/>It is not only we who are praying<br/>He too is praying, in our praying.<br/>This kind of prayer is related to fruit bearing<br/>and will surely be answered.<br/>',NULL,19826,3);
INSERT INTO stanza VALUES('NS123','3','You did not choose Me, but I chose you and I set you.<br/>That you should go forth and bear fruit,<br/>And that your fruit should remain,<br/>That whatever you ask the Father in my name,<br/>He may give you.<br/>',NULL,19827,4);
INSERT INTO stanza VALUES('NS124','1','Calling, “O Lord Jesus!“<br/>Oh, it makes our spirit strong!<br/>We can really touch Him,<br/>And our gloom is turned to song!<br/>Don’t listen to Satan, with all His distraction;<br/>Just turn to your spirit, and spring into action!<br/>Calling, “O Lord Jesus!“<br/>You’ll enjoy Him all day long!<br/>',NULL,19828,1);
INSERT INTO stanza VALUES('NS125','chorus','Go on, go on, go on in the Lord.<br/>Be strengthened, go on in the Lord.<br/>Your labor is not in vain in the Lord.<br/>You must go on, go on in the Lord.<br/>',NULL,19829,1);
INSERT INTO stanza VALUES('NS125','1','Trials may come and discouragements, too.<br/>You must go on, go on in the Lord.<br/>Yesterday’s gone and His mercies are new.<br/>You must go on, go on in the Lord.<br/>',NULL,19830,2);
INSERT INTO stanza VALUES('NS125','chorus','Press on, press on, press on in the Lord.<br/>Be strengthened, press on in the Lord.<br/>Your labor is not in vain in the Lord.<br/>You must press on, press on in the Lord.<br/>',NULL,19831,3);
INSERT INTO stanza VALUES('NS125','2','To worry is vain—He will care for Your needs.<br/>You must go on, go on in the Lord.<br/>Tomorrow’s not here and it never may be.<br/>You must go on, go on in the Lord.<br/>',NULL,19832,4);
INSERT INTO stanza VALUES('NS125','chorus','Sail on, sail on, sail on in the Lord.<br/>Be strengthened, sail on in the Lord.<br/>Your labor is not in vain in the Lord.<br/>You must sail on, sail on in the Lord.<br/>',NULL,19833,5);
INSERT INTO stanza VALUES('NS125','chorus','You must sail on, sail on,<br/>Press on, press on,<br/>You must go on, and on in the Lord.<br/>',NULL,19834,6);
INSERT INTO stanza VALUES('NS126','1','Therefore being justified by faith<br/>We have peace with God<br/>Through our Lord Jesus Christ<br/>',NULL,19835,1);
INSERT INTO stanza VALUES('NS126','chorus','Because the love of God is shed abroad<br/>In our hearts, by the Holy Spirit<br/>Which is given, which is given<br/>Unto us, to us, to us.<br/>',NULL,19836,2);
INSERT INTO stanza VALUES('NS126','2','God hath commended His love toward us<br/>In that while we were yet sinners<br/>Christ died for us.<br/>',NULL,19837,3);
INSERT INTO stanza VALUES('NS127','1','He grew up like a tender plant—<br/>The Son of God,<br/>And like a root out of dry ground—<br/>No attracting form<br/>Nor majesty.<br/>',NULL,19838,1);
INSERT INTO stanza VALUES('NS127','2','He alone bore the sin of man,<br/>To save me<br/>And poured out His life unto death;<br/>The Lamb of God,<br/>Oh Jesus Christ!<br/>',NULL,19839,2);
INSERT INTO stanza VALUES('NS127','chorus','Surely He has borne our sicknesses<br/>And carried our sorrows.<br/>He made Himself an offering,<br/>An offering for sin.<br/>He was crushed because of our iniquities<br/>And by His stripes we’ve been healed.<br/>He will see the fruit of the travail of His soul.<br/>The righteous One will make the many righteous.<br/>',NULL,19840,3);
INSERT INTO stanza VALUES('NS128','1','Draw me, dear Lord, with Your beauty,<br/>Capture my heart till earth fades away.<br/>I need Your love to attract me<br/>So I can love You more today.<br/>',NULL,19841,1);
INSERT INTO stanza VALUES('NS128','2','Empty me, Lord, how I need You!&nbsp;&nbsp;<br/>Unclog my mind, emotion, and will.<br/>All that I have, I abandon<br/>So You can fill my heart today.<br/>',NULL,19842,2);
INSERT INTO stanza VALUES('NS128','3','Oh fill me now with Your life, Lord,<br/>Flood my whole being with rivers divine.<br/>I open wide; what enjoyment!<br/>So all my heart, Your life can fill.<br/>',NULL,19843,3);
INSERT INTO stanza VALUES('NS129','1','Lord, You are Beloved, Fairest of the fair;<br/>Altogether lovely, unrivaled beauty;<br/>It’s You! Your presence, I long for and seek;<br/>You’re the One in Whom my heart delights,<br/>So, I just love to tell You...<br/>',NULL,19844,1);
INSERT INTO stanza VALUES('NS129','chorus','Jesus, I love You,<br/>My treasure, You are;<br/>How could I choose anything less than You?<br/>Dear Lord, my inmost heart<br/>You’ve captured and won.<br/>',NULL,19845,2);
INSERT INTO stanza VALUES('NS129','2','Dead I was in sin Lord, so lost without You;<br/>Helpless, wounded, weary, rebellious, too;<br/>But Lord, You came! You would not let me go;<br/>The blood and water flowed from Your side,<br/>Constraining me to tell You...<br/>',NULL,19846,3);
INSERT INTO stanza VALUES('NS129','3','Thank You Lord, You opened my blind eyes to see<br/>I was lame, but now I can walk; You healed me!<br/>My leprosy, Lord, You cleansed all away;<br/>My ears were opened to hear Your voice,<br/>And now I follow You ’cause...<br/>',NULL,19847,4);
INSERT INTO stanza VALUES('NS129','4','Sometimes Lord, I’m drawn off by my selfish cares;<br/>And the world it draws me with glitter and glare.<br/>O Lord, You’ve trapped me. Don’t let me go.<br/>Kiss me and woo me, and win my heart,<br/>So, I will always tell You...<br/>',NULL,19848,5);
INSERT INTO stanza VALUES('NS129','5','Keep my heart so soft, Lord, so open to You;<br/>It would be the good ground to bear fruit for You;<br/>Capture my friends Lord, and build us, I pray;<br/>Your Bride, We’d match You in every way,<br/>And corporately we tell You:<br/>',NULL,19849,6);
INSERT INTO stanza VALUES('NS129','chorus','Jesus, Come quickly,<br/>We’re waiting for You;<br/>We’re the virgins to You,<br/>So single and true;<br/>Forever and ever<br/>Your counterpart true.<br/>',NULL,19850,7);
INSERT INTO stanza VALUES('NS130','1','Lord, how I thank You that<br/>You died on the cross for me.<br/>Your mercy, my Savior, reached me.<br/>And Lord, You paid the highest price,<br/>My life bought with Your shed blood,<br/>My life now belongs, Lord, to You.<br/><br/>And Lord, how can I turn away from Your love,<br/>The eternal love which You have for me?<br/>I give You my heart;<br/>Lord, spread in every part,<br/>Till my whole heart belongs to You.<br/>',NULL,19851,1);
INSERT INTO stanza VALUES('NS130','2','Lord gain my heart so that<br/>It is single and pure for You.<br/>No other love, Lord would I know.<br/>Lord I am so in love with You.<br/>For You are so lovely,<br/>My everything, my all in all.<br/><br/>And Lord, I really want to know<br/>This Person inside of me.<br/>Lord, keep my heart open to You.<br/>Keep flowing Your life,<br/>Into me that I would grow,<br/>And be saturated with You.<br/>',NULL,19852,2);
INSERT INTO stanza VALUES('NS131','1','I’m gonna praise God unceasingly<br/>Because He lives in me,<br/>He’s everything to me,<br/>Gives life continually.<br/>I’m gonna praise God unceasingly<br/>Because He lives in me,<br/>And He will never leave.<br/>',NULL,19853,1);
INSERT INTO stanza VALUES('NS131','chorus','Now in our spirit we can feed,<br/>Jesus Christ is all we need,<br/>Call His name and He becomes reality.<br/>Open up your mouth and you will see,<br/>Just how rich our Lord can be.<br/>He’s the very life supply, complete is He.<br/>',NULL,19854,2);
INSERT INTO stanza VALUES('NS131','2','Now I live by the tree of life,<br/>His fruit does nourish me,<br/>O, how it strengthens me,<br/>I’ll live eternally.<br/>Now I live by the tree of life,<br/>Him daily I apply,<br/>He is my food supply.<br/>',NULL,19855,3);
INSERT INTO stanza VALUES('NS131','3','There’s a river of life in me,<br/>Flowing so livingly,<br/>Moving continually,<br/>He just keeps flooding me.<br/>There’s a river of life in me,<br/>He’s always filling me,<br/>His name is Jesus Christ!<br/>',NULL,19856,4);
INSERT INTO stanza VALUES('NS132','1','The new covenant ministers<br/>Are captives in a procession,<br/>Defeated and subdued by Christ<br/>For His victorious celebration.<br/><br/>Lord, make me Your captive.<br/>Never let me win.<br/>Defeat me all the time.<br/>Lord, make home in me.<br/>',NULL,19857,1);
INSERT INTO stanza VALUES('NS132','2','The new covenant ministers<br/>Are incense-bearers of Christ<br/>Scattering His sweet fragrance<br/>In every place—bringing death and life.<br/><br/>Lord, have the liberty<br/>To fill me wholly.<br/>Dear Lord, fill me daily!<br/>Lord, make home in me.<br/>',NULL,19858,2);
INSERT INTO stanza VALUES('NS132','3','The new covenant ministers<br/>Are Christ’s own living letters<br/>Inscribed with the Spirit of God,<br/>To express the rich Christ to others.<br/><br/>Lord, write Yourself in me.<br/>Inscribe in my heart<br/>That I may write on others.<br/>Lord, make home in me.<br/>',NULL,19859,3);
INSERT INTO stanza VALUES('NS132','4','The new covenant ministers<br/>Are mirrors of the Christ of glory<br/>Beholding and reflecting Him<br/>So as to be transformed inwardly.<br/><br/>Lord, I turn my whole heart<br/>To focus on You.<br/>Shine in me, transform me.<br/>Lord, make home in me.<br/>',NULL,19860,4);
INSERT INTO stanza VALUES('NS132','5','The new covenant ministers<br/>Are earthen vessels that are worthless<br/>Who live by the excellent p’wer<br/>Of Christ as the treasure—priceless.<br/><br/>Lord, You are so precious!<br/>I give You my whole being;<br/>Break me, renew me, Lord!<br/>Lord, make home in me.<br/>',NULL,19861,5);
INSERT INTO stanza VALUES('NS132','6','Lord, grant me the experiences<br/>To produce such a ministry.<br/>Through revelation and sufferings,<br/>Lord, constitute Yourself in me.<br/><br/>By Your all-fitting life,<br/>Lord, I learn to live.<br/>By Your sufficient grace,<br/>Lord, make home in me.<br/>',NULL,19862,6);
INSERT INTO stanza VALUES('NS133','1','I love my Master, and I will not go out free.<br/>For He has died for me, the highest price He has paid for me.<br/>I love my Master, I will serve Him willingly. <br/>Remaining near, and close to Him this my plea.<br/>',NULL,19863,1);
INSERT INTO stanza VALUES('NS133','chorus','I love You Master, from You I will never leave.<br/>You are my liberty, and my joy complete.<br/>I love my Master, and I will not go out free.<br/>To Him I give my all, my life eternally!<br/>',NULL,19864,2);
INSERT INTO stanza VALUES('NS133','2','Oh Jesus, Master, to the door post now bring me.<br/>Open my ears to hear, Your voice and all that You say to me.<br/>Oh Jesus, Master, I will obey willingly.<br/>To love and serve Him all my life, this my plea!<br/>',NULL,19865,3);
INSERT INTO stanza VALUES('NS134','1','Prod me with Your loving hands,<br/>Stir me from my deep impasse.<br/>I long to flee this stagnant rut;<br/>My soul, my prison, deadened lot,<br/>Which end is just to taste Your wrath;<br/>So set me on the narrow path.<br/>Thorns and thistles may line this road<br/>But it leads me to the mutual abode.<br/><br/>Lift me up with Your mighty hand<br/>Above this frenzied earthly land.<br/>Set me on the mount to see<br/>What the world can offer me;<br/>Till I see the vanity from on high<br/>And earthly desires I bid goodbye<br/>And set my eyes on You.<br/>',NULL,19866,1);
INSERT INTO stanza VALUES('NS135','1','Thank You, Lord Jesus, for dying for me.<br/>It’s Your precious blood cleansing all iniquities.<br/>It’s there on the cross where You bled and died for me.<br/>Lord Jesus, I thank You, I’m fully justified in Thee.<br/>',NULL,19867,1);
INSERT INTO stanza VALUES('NS135','chorus','Lord Jesus, I love You,<br/>You’re precious to me.<br/>It’s here in Your presence,<br/>I’ve seen Your beauty.<br/>You’re matchless, You’re priceless,<br/>You’re everything to me.<br/>I’ll love You forever—<br/>You are the only One for me.<br/>',NULL,19868,2);
INSERT INTO stanza VALUES('NS135','2','Daily I come to be supplied by Your word.<br/>It’s by this supply that I’m richly satisfied.<br/>It’s here that I’m strengthened to live the Christian life.<br/>It’s nothing I do, but Your overflowing grace to me.<br/>',NULL,19869,3);
INSERT INTO stanza VALUES('NS135','3','Each day as I wake up I come to You, Lord.<br/>Our fellowship sweet must be daily restored.<br/>Void of offense, keep my conscience so pure.<br/>Soften me, Lord, so that You alone may have my heart.<br/>',NULL,19870,4);
INSERT INTO stanza VALUES('NS136','1','I’m a sinner without one plea,<br/>But the Lamb of God in me;<br/>I was lost and without hope<br/>But my Savior came and sought me out.<br/>’Tis my story and my song;<br/>To the world I say so long;<br/>I now walk and live in light<br/>With the New Jerusalem in sight.<br/>',NULL,19871,1);
INSERT INTO stanza VALUES('NS136','chorus','Till the end of days,<br/>He will be with me<br/>And lead me to that place;<br/>I give my all:<br/>My life, my ways, my thoughts,<br/>And everything to Him, my love.<br/>',NULL,19872,2);
INSERT INTO stanza VALUES('NS136','2','Sometimes I think that I might leave<br/>And wallow in misery,<br/>But then graciously He comes<br/>And applies His gentle, soothing touch.<br/>’Tis my story and my fight;<br/>To the self I say goodbye;<br/>I now walk and live in light<br/>With the coming kingdom full in sight.<br/>',NULL,19873,3);
INSERT INTO stanza VALUES('NS137','1','I won’t say goodbye<br/>Or even think about all that I’ve left behind.<br/>This world is worthless in my mind;<br/>I’ve crossed the great divide;<br/>No looking back, there’s no way back to my old life.<br/>To Christ I come, to Christ I go.<br/>',NULL,19874,1);
INSERT INTO stanza VALUES('NS137','chorus','I died to this world, but then He raised me, lifted to<br/>The heavenly<br/>And there I find His perfect peace; God and I live in<br/>Harmony.<br/>River of life, flowing freely.<br/>Here I’ll drink, and drink, and drink, and drink from<br/>Now to Eternity.<br/>',NULL,19875,2);
INSERT INTO stanza VALUES('NS137','2','Raining day and night<br/>While water rise, I’m safe inside my Christ the ark.<br/>This world is buried ’neath the dark,<br/>I’ve stepped into the light.<br/>His word I see, I trace the rainbow through the sky.<br/>To Christ I come, to Christ I go.<br/>',NULL,19876,3);
INSERT INTO stanza VALUES('NS138','1','What things were gains to me,<br/>These I now count as loss.<br/>Jesus has set me free<br/>From what I was!<br/>All of the things I had;<br/>Everything, good or bad,<br/>I count as refuse<br/>That I may gain Christ!<br/>',NULL,19877,1);
INSERT INTO stanza VALUES('NS138','chorus','I won’t give up!<br/>I will keep running until<br/>I have attained<br/>The goal of my calling!<br/>I must press on!<br/>I must pursue until<br/>I lay hold of Him<br/>Who laid hold of me!<br/>',NULL,19878,2);
INSERT INTO stanza VALUES('NS138','2','Forget the things behind!<br/>Stretch for the things before!<br/>Press onward with this mind:<br/>Always want more!<br/>Seeking in Him to grow,<br/>Increasingly to know<br/>Him that I daily might<br/>Be found in Christ.<br/>',NULL,19879,3);
INSERT INTO stanza VALUES('NS139','1','I thought I knew You, I did not love You;<br/>I thought I met You, I had only heard of You.<br/>You whispered to me, I shut my ears, Lord.<br/>You tried to show me that You could be something more.<br/><br/>And then You caught me—<br/>The great love You had for me—<br/>I could not help but love Thee.<br/>Lord, Your compassion had drawn me so entirely.<br/>At last, I glimpsed Your beauty.<br/>',NULL,19880,1);
INSERT INTO stanza VALUES('NS139','2','I felt so filthy, You shone on my sin.<br/>I asked Your pardon, then You cleansed me from within.<br/>My eyes were opened, now I could see You.<br/>You were more real than anything I ever knew.<br/><br/>And then You freed me—<br/>You hung and died on a tree—<br/>I wasn’t even worthy.<br/>Lord, then You found me and rescued me from my sins.<br/>Lord, You are full of mercy.<br/>',NULL,19881,2);
INSERT INTO stanza VALUES('NS140','1','Lord, I am only Yours alone,<br/>I love You, Lord above.<br/>I give myself to You right now,<br/>Lord, You alone I love.<br/>',NULL,19882,1);
INSERT INTO stanza VALUES('NS140','2','You paid the price upon the cross,<br/>Your blood, You shed for me.<br/>The right of ownership o’er me<br/>Has been transferred to Thee.<br/>',NULL,19883,2);
INSERT INTO stanza VALUES('NS140','3','Lord, thank You I am sacrificed<br/>Upon the altar of love;<br/>Unto You I am set apart,<br/>I love You, Lord above.<br/>',NULL,19884,3);
INSERT INTO stanza VALUES('NS140','4','I consecrate myself to You,<br/>I give myself to You.<br/>Work in me fully that I may<br/>Be useful Lord, to You.<br/>',NULL,19885,4);
INSERT INTO stanza VALUES('NS140','5','Lord, I give You my whole future,<br/>I bind myself to You.<br/>I cut all ties with worldly things,<br/>I yield myself to You.<br/>',NULL,19886,5);
INSERT INTO stanza VALUES('NS152','1','O Lord, You have from days of eternity<br/>Desired to be expressed through man corporately.<br/>As one whom You’ve chosen to share in Your plan,<br/>I’m being constituted to impart You to man.<br/>',NULL,19887,1);
INSERT INTO stanza VALUES('NS152','chorus','Lord, I fully consecrate myself to be<br/>A normal Christian in Your economy.<br/>I would live solely with the Body in view,<br/>Fulfilling my stewardship—“to me for you.”<br/>',NULL,19888,2);
INSERT INTO stanza VALUES('NS152','2','In Christ as Spirit You dispense all to me,<br/>Making me a steward in Your economy.<br/>Ever faithful to the measure I have received<br/>To impart You to others, life conceived.<br/>',NULL,19889,3);
INSERT INTO stanza VALUES('NS152','3','Lord, I give You ground to make Your home in my heart.<br/>Settle down and strengthen every inward part.<br/>The unlimited Christ experienced by me,<br/>To others I minister for Your glory.<br/>',NULL,19890,4);
INSERT INTO stanza VALUES('NS152','4','In fellowship with You, my spirit employ,<br/>Your unsearchable riches I would enjoy.<br/>Not confine them within, myself to gild,<br/>But with others share them, Your Body to build.<br/>',NULL,19891,5);
INSERT INTO stanza VALUES('NS153','1','Thy word is sweet unto my taste,<br/>Yea, sweeter more than honey.<br/>It says to watch and pray that you<br/>May not enter into temptation.<br/><br/>But flee youthful lusts and pursue righteousness,<br/>faith, love, and peace.<br/>Whatever you do,<br/>do in the name of the Lord Jesus Christ.<br/>And pursue with those,<br/>Those who call on the Lord out of a pure heart.<br/>',NULL,19892,1);
INSERT INTO stanza VALUES('NS154','1','God’s love: long, broad, high, and deep,<br/>Indeed beyond measure;<br/>Else how could such a sinner as me,<br/>Be with bountiful grace favored.<br/>',NULL,19893,1);
INSERT INTO stanza VALUES('NS154','2','My Lord paid a price so great,<br/>To buy me back to Him;<br/>Now willing I’m the cross to bear,<br/>And follow Him to the end.<br/>',NULL,19894,2);
INSERT INTO stanza VALUES('NS154','3','I now have forsaken all,<br/>In order Christ to gain;<br/>Or life, or death, unworthy a thought,<br/>Not even one backward glance!<br/>',NULL,19895,3);
INSERT INTO stanza VALUES('NS154','4','Loved ones, desires, wealth and fame,<br/>To me what good are they?<br/>My Lord for me poor and woe became,<br/>For Him I’d be poor today.<br/>',NULL,19896,4);
INSERT INTO stanza VALUES('NS154','5','I love my Savior Lord,<br/>I only long for His “Yes“;<br/>For Him no ease can comfort hold,<br/>All gains a loss became.<br/>',NULL,19897,5);
INSERT INTO stanza VALUES('NS154','6','You are my true comfort,<br/>My gracious Lord Jesus;<br/>Whom but You have I in heaven?<br/>What else I love on earth?<br/>',NULL,19898,6);
INSERT INTO stanza VALUES('NS154','7','Suffer, opposed, tossed around,<br/>Hence I will all disregard;<br/>Only I’d ask my Lord with Your love,<br/>Spirit, soul, and body surround.<br/>',NULL,19899,7);
INSERT INTO stanza VALUES('NS154','8','O Lord, I now beseech You,<br/>Guide me in grace onward;<br/>Stand by and strengthen me all way through,<br/>To pass this dark, evil world.<br/>',NULL,19900,8);
INSERT INTO stanza VALUES('NS154','9','Satan, the world, and the flesh,<br/>Oft’n tempt and humiliate;<br/>If You don’t add me with more strength<br/>I may Your name disgrace!<br/>',NULL,19901,9);
INSERT INTO stanza VALUES('NS154','10','Now time is running short,<br/>Set me free, O Lord, I pray;<br/>Once You return, I’ll sing with joy,<br/>Hallelujah! Amen!<br/>',NULL,19902,10);
INSERT INTO stanza VALUES('NS155','1','Let the word of Christ dwell in you<br/>Richly, in all wisdom<br/>Teaching and admonishing one another<br/>In psalms, and hymns, and spiritual songs,<br/>Singing with grace in your hearts to the Lord<br/>And whatever you do, in word or in work<br/>Do all in the name of our Lord Jesus Christ,<br/>Do all in the name of our Lord.<br/>',NULL,19903,1);
INSERT INTO stanza VALUES('NS156','1','Lord, I love You,<br/>I desire You;<br/>No pleasure, prospects on this earth compare to You.<br/>Lord, I love You,<br/>I treasure You;<br/>No fame nor riches of this world compete with You.<br/>Lord, who have I<br/>In heaven but You,<br/>There’s none on earth<br/>I desire but You;<br/>You are my all,<br/>My All in all;<br/>Lord Jesus, I just love You,<br/>I love only You.<br/>',NULL,19904,1);
INSERT INTO stanza VALUES('NS156','2','Lord, I love You,<br/>I now choose You;<br/>No love, nor praises of men can e’er replace You.<br/>Lord, I love You,<br/>I lay hold of You;<br/>No hope, no expectation I have ’part from You.<br/>Lord, who have I<br/>In heaven but You;<br/>There’s none on earth<br/>I desire but You;<br/>You’re my first love,<br/>My final love;<br/>I give my life and all<br/>To love and follow You.<br/>',NULL,19905,2);
INSERT INTO stanza VALUES('NS156','3','Lord, I love You,<br/>I pursue You;<br/>No person, object in this life can e’er match You.<br/>Lord, I love You,<br/>I run after You;<br/>You are my life, my aim, my goal and future too.<br/>Lord, who have I<br/>In heaven but You;<br/>There’s none on earth<br/>I desire but You;<br/>I give my heart,<br/>Lord, now to You;<br/>Lord make me a drink off’ring here<br/>To satisfy You.<br/>',NULL,19906,3);
INSERT INTO stanza VALUES('NS157','1','We’re renewed and revived by the Lord day by day;<br/>He is grace upon grace and refreshing as dew.<br/>Shining brighter and brighter, our path’s a clear way,<br/>As morning by morning His mercies are new.<br/>',NULL,19907,1);
INSERT INTO stanza VALUES('NS157','2','Transformed by beholding from glory to glory,<br/>And from strength to strength on to Zion we go.<br/>Constitute us with truth as daily we study—<br/>Here a little there a little—Your Word to know.<br/>',NULL,19908,2);
INSERT INTO stanza VALUES('NS157','3','Perfected and nourished from house to house meeting,<br/>We speak one by one that the church may be built.<br/>As little by little ev’ry enemy’s fleeing,<br/>More and more surpassingly with glory we’re filled.<br/>',NULL,19909,3);
INSERT INTO stanza VALUES('NS157','chorus','Day by day,<br/>Grace upon grace,<br/>Brighter and brighter,<br/>Morning by morning<br/>(His mercies are new.)<br/>',NULL,19910,4);
INSERT INTO stanza VALUES('NS157','chorus','Glory to glory,<br/>Strength to strength,<br/>Here a little,<br/>There a little<br/>(Your Word to know.)<br/>',NULL,19911,5);
INSERT INTO stanza VALUES('NS157','chorus','House to house,<br/>One by one,<br/>Little by little,<br/>More and more<br/>(With glory we’re filled.)<br/>',NULL,19912,6);
INSERT INTO stanza VALUES('NS158','1','Immersed in Thy love;<br/>Fresher than morning dew;<br/>Here I’m kept away from every earthly care.<br/>Such tender feeling;<br/>Caressed by my Beloved;<br/>You’re the loveliest, much fairer than the fair.<br/>',NULL,19913,1);
INSERT INTO stanza VALUES('NS158','chorus','Moments with You,<br/>How affectionate!<br/>Now I seize this opportunity to say<br/>That I love You.<br/>I will be with You all my days, come what may.<br/>',NULL,19914,2);
INSERT INTO stanza VALUES('NS158','2','I cannot help it,<br/>I’m so in love with You;<br/>For I’ve tasted Your divine heavenly wine.<br/>I’m soaked with Thy love,<br/>I pour my all on You.<br/>What my future holds for me, my Lord are Thine.<br/>',NULL,19915,3);
INSERT INTO stanza VALUES('NS158','3','I’m so attracted<br/>By Your constraining love,<br/>And Your Name is sweet as ointment poured forth.<br/>I’m captivated<br/>By Your dear Person, Lord.<br/>Draw me from this age to pursue only You...<br/>',NULL,19916,4);
INSERT INTO stanza VALUES('NS159','1','Christ’s divinity’s glorious indeed;<br/>’Twas concealed in Him as in a grain of wheat.<br/>While incarnated, He was pressed, constrained<br/>For the release of His glory within.<br/>',NULL,19917,1);
INSERT INTO stanza VALUES('NS159','chorus','Incorporation! Incorporation—<br/>The issue of Christ’s glorification.<br/>In our daily walk, we must join to Him<br/>And must live in Him, and work as one with Him.<br/>',NULL,19918,2);
INSERT INTO stanza VALUES('NS159','2','Christ was glorified, dying on the cross;<br/>Glory was released—this was not a loss!<br/>Spirit He became, for life-giving;<br/>Last Adam is He, for His dispensing.<br/>',NULL,19919,3);
INSERT INTO stanza VALUES('NS159','3','Resurrected, Christ thus was born to be<br/>God’s firstborn Son with humanity.<br/>Many sons were through resurrection, born;<br/>The Lord Spirit, Christ, their being will transform.<br/>',NULL,19920,4);
INSERT INTO stanza VALUES('NS159','4','We in faith were regenerated;<br/>God and man thus incorporated.<br/>This took place through Christ’s resurrection.<br/>For His divine, glorious multiplication.<br/>',NULL,19921,5);
INSERT INTO stanza VALUES('NS159','5','Three aspects of incorporation:<br/>Father’s house for His satisfaction,<br/>The true vine for His multiplication,<br/>Child of the Spirit, for His move on earth.<br/>',NULL,19922,6);
INSERT INTO stanza VALUES('NS160','1','Give yourself to love the Lord.<br/>No other way is so prevailing<br/>And no other way, no other way is so safe.<br/>',NULL,19923,1);
INSERT INTO stanza VALUES('NS160','2','Give yourself to love the Lord.<br/>No other way is so rich, <br/>And so full, oh so full, of enjoyment.<br/>',NULL,19924,2);
INSERT INTO stanza VALUES('NS160','chorus','Each morning we must rise up and say to Him,<br/>“Lord Jesus, I love You.”<br/>',NULL,19925,3);
INSERT INTO stanza VALUES('NS160','3','Give yourself to love the Lord.<br/>Do not care for anything else;<br/>Just love Him! Do not care!<br/>Give yourself to love the Lord!<br/>',NULL,19926,4);
INSERT INTO stanza VALUES('NS160','chorus','We are not our own, Lord;<br/>All we have we give to You.<br/>Lord Jesus! Lord Jesus!<br/>Lord Jesus, we love You!<br/>',NULL,19927,5);
INSERT INTO stanza VALUES('NS161','1','I’ve found the One who’s all to me;<br/>He’s become reality.<br/>Now He’s in my life to stay;<br/>He is the truth, the life, the way.<br/>',NULL,19928,1);
INSERT INTO stanza VALUES('NS161','chorus','And Jesus is the One who came<br/>Down to earth to bear our shame,<br/>But that’s not all, He lives in me.<br/>Once I was blind, but now I see.<br/>',NULL,19929,2);
INSERT INTO stanza VALUES('NS161','2','Now through His life we have the flow,<br/>Showing us the way to go;<br/>Keeping us in unity,<br/>And this is His recovery.<br/>',NULL,19930,3);
INSERT INTO stanza VALUES('NS161','3','Now Jesus is the Lord of all;<br/>On His name we all must call.<br/>Then our spirits find release,<br/>And thus our hearts have found real peace.<br/>',NULL,19931,4);
INSERT INTO stanza VALUES('NS162','chorus','Christ is everything, I need Him.<br/>He is everything you need, believe Him.<br/>Life is a person, receive Him,<br/>Open up your heart and sing.<br/>',NULL,19932,1);
INSERT INTO stanza VALUES('NS162','1','Open yourself to the new creation.<br/>Open your eyes to the joy of change.<br/>Life is a fruit of God’s creation.<br/>Every new birth is a soul regained.<br/>',NULL,19933,2);
INSERT INTO stanza VALUES('NS162','2','Drinking His life from a living fountain.<br/>Sweet water running inside of me.<br/>Oh, how I love to live on the mountain,<br/>Ever since Jesus set me free.<br/>',NULL,19934,3);
INSERT INTO stanza VALUES('NS162','3','Follow the Lord like a charging stallion.<br/>Race for the Son with all your might.<br/>Guard your heart like a gold medallion,<br/>Keep the kingdom full in sight.<br/>',NULL,19935,4);
INSERT INTO stanza VALUES('NS163','1','If you wish to find the Lord,<br/>Do not seek Him in the world,<br/>For the world is not the place in which He dwells.<br/>In which He dwells, in which He dwells,<br/>In which He dwells, in which He dwells,<br/>For the world is not the place in which He dwells.<br/>',NULL,19936,1);
INSERT INTO stanza VALUES('NS163','2','If you wish to find the Lord,<br/>Do not seek Him in the mind,<br/>For the mind can only know, it cannot taste.<br/>It cannot taste, it cannot taste,<br/>It cannot taste, it cannot taste,<br/>For the mind can only know, it cannot taste.<br/>',NULL,19937,2);
INSERT INTO stanza VALUES('NS163','3','If you wish to find the Lord,<br/>You must open up your heart,<br/>You must open up your heart and let Him in.<br/>Let Him in, let Him in,<br/>Let Him in, let Him in,<br/>You must open up your heart and let Him in.<br/>',NULL,19938,3);
INSERT INTO stanza VALUES('NS163','4','If you wish to let Him in,<br/>You just call upon His name,<br/>You just call upon His name and let Him in.<br/>Call His name, call His name,<br/>Call His name, call His name,<br/>You just call upon His name and let Him in.<br/>',NULL,19939,4);
INSERT INTO stanza VALUES('NS164','1','Do you know what you were made for;<br/>Do you ever wonder why?<br/>What’s the purpose for your being;<br/>What’s the reason you’re alive?<br/>Do you know God wants to be your life?<br/>He wants to be your life, He wants to be your life.<br/>You were made with something deep within,<br/>A vessel to contain just Him.<br/>',NULL,19940,1);
INSERT INTO stanza VALUES('NS164','2','Deep within you is your spirit,<br/>Even deeper than your “heart“;<br/>Many other things can fill you—<br/>Only Jesus can fill this part.<br/>You have been so empty all these years;<br/>In spite of all you’ve tried, you’re still not satisfied.<br/>Don’t you feel a longing deep within<br/>To open up and take Christ in?<br/>',NULL,19941,2);
INSERT INTO stanza VALUES('NS164','3','Doesn’t matter how you see things,<br/>For in God’s eyes “all have sinned“;<br/>Jesus shed His blood to cleanse you<br/>For the purpose of getting in.<br/>He’s done everything there is to do,<br/>And He’s the Spirit now so He can get in you.<br/>Makes no difference what your past has been;<br/>The living Christ will still come in.<br/>',NULL,19942,3);
INSERT INTO stanza VALUES('NS164','4','Just as you are in your body,<br/>Perfectly contained therein,<br/>God wants you for His container,<br/>All you need to do is let Him in.<br/>Would you open up from deep within<br/>To let the Lord come in and fill you to the brim.<br/>Why not open up from deep within<br/>And call upon the name of Him.<br/>',NULL,19943,4);
INSERT INTO stanza VALUES('NS165','1','I just existed empty, not knowing<br/>what life was for;<br/>Until one day someone told me that<br/>there was something more;<br/>At first I wouldn’t take it—<br/>it seemed too simple to me!<br/>',NULL,19944,1);
INSERT INTO stanza VALUES('NS165','chorus','Calling His name, “O Lord Jesus!“<br/>Saying, “Amen,” when He speaks.<br/>Filling my spirit with His life.<br/>Filling my whole life with His life.<br/>Flooding my living with His life.<br/>Filling my whole life with His life!<br/>',NULL,19945,2);
INSERT INTO stanza VALUES('NS165','2','But then at length I tried it—<br/>first softly, to myself.<br/>As I called I felt like someone sick<br/>brought back to health.<br/>The flow of life within me, I’d never<br/>felt before.<br/>',NULL,19946,3);
INSERT INTO stanza VALUES('NS165','3','Then as I called on Jesus I felt<br/>that I’d been found!<br/>I was so full; I was calling “Jesus!“<br/>right out loud.<br/>I’d never dreamed that I could know<br/>reality by...<br/>',NULL,19947,4);
INSERT INTO stanza VALUES('NS165','4','And now I’m full and happy, so<br/>satisfied with Him,<br/>Because He has come and filled me<br/>clear up past the brim.<br/>His life is now my portion—<br/>I’ll go on all my life, just...<br/>',NULL,19948,5);
INSERT INTO stanza VALUES('NS166','1','Fallen, in her condition<br/>Israel left her Love.<br/>She was stubborn in her position—<br/>To God she would not come.<br/>Under the Lord’s chastising<br/>She was an unturned cake.<br/>But Jehovah, with love unchanging<br/>Makes Israel His own son—a change to make.<br/>',NULL,19949,1);
INSERT INTO stanza VALUES('NS166','2','You became a man—<br/>Cord of love to me.<br/>I am drawn with loving bands<br/>And embraced by Thee.<br/>From the heavens came,<br/>You stepped out of eternity,<br/>Died and rose as a man<br/>That You could impart Your life to me.<br/>',NULL,19950,2);
INSERT INTO stanza VALUES('NS167','1','I always knew deep down in me<br/>There was a longing to be free,<br/>A kind of hunger deep inside—<br/>To fill it up, I tried and tried.<br/>There were a lot of things I had;<br/>Some things were good,<br/>Some things were bad.<br/>But all those things of mine before<br/>Don’t satisfy me anymore.<br/>',NULL,19951,1);
INSERT INTO stanza VALUES('NS167','chorus','Now life affords a real reward<br/>Whenever I just call “O Lord!“<br/>The Triune God the Spirit is,<br/>And He can fill mine up with His.<br/>',NULL,19952,2);
INSERT INTO stanza VALUES('NS167','2','Thank You, Lord Jesus, for the wine<br/>That I enjoy as life divine.<br/>I thank You, Lord, for mercy all<br/>That opened me to heed Your call.<br/>O Lord, now make Your home my heart<br/>And fully saturate each part.<br/>O Lord, my words just can’t express<br/>The way You’ve filled my emptiness!<br/>',NULL,19953,3);
INSERT INTO stanza VALUES('NS167','chorus','O Lord, I know that You will grow<br/>And from my spirit overflow.<br/>Lord, saturate me through and through—<br/>O Lord Jesus, I love You.<br/>',NULL,19954,4);
INSERT INTO stanza VALUES('NS167','3','I always knew deep down in me<br/>There was a longing to be free.<br/>A kind of hunger deep inside—<br/>But now it can be satisfied...<br/>Christ in my heart—the only way<br/>To spread within me day by day.<br/>Lord Jesus! Lord, I have to say<br/>You’re home in me and home to stay!<br/>',NULL,19955,5);
INSERT INTO stanza VALUES('NS167','chorus','O Lord, I know now You will grow<br/>And from my spirit overflow!<br/>Now saturate me through and through!<br/>O Lord Jesus, I love You!<br/>O Lord Jesus, I love You!<br/>O Lord Jesus, I love You!<br/>',NULL,19956,6);
INSERT INTO stanza VALUES('NS168','1','From the time I spoke Your name,<br/>Lord, my life’s not been the same<br/>Since I called on the only One who’d save me.<br/>When forsaken, in despair—<br/>Who’d have thought that You’d be there!<br/>Now I’ve found out, Jesus, You’re alive!<br/>',NULL,19957,1);
INSERT INTO stanza VALUES('NS168','chorus','Now my eyes begin to see<br/>I’m living as I ought to be,<br/>As this turning, burning God<br/>moves in my heart...<br/>I don’t care now how I feel;<br/>I just know that this is real,<br/>And I know, oh Jesus, You’re alive!<br/>',NULL,19958,2);
INSERT INTO stanza VALUES('NS168','2','All my friends might think it’s square—<br/>Since I touched You, I don’t care—<br/>For I’ve found You’re the only life worth living.<br/>Though some mock and criticize,<br/>Lord, they just don’t realize<br/>That I’ve found out, Jesus, You’re alive!<br/>',NULL,19959,3);
INSERT INTO stanza VALUES('NS168','3','It’s no statue that I call,<br/>Not a picture on the wall,<br/>But a person who lives His life within me.<br/>Wish they’d told me long before,<br/>All You want’s an open door<br/>And that really, Jesus, You’re alive!<br/>',NULL,19960,4);
INSERT INTO stanza VALUES('NS169','1','Morning dawn had arisen,<br/>Abraham saddled his donkey,<br/>Took his two young men with him<br/>And Isaac, his beloved son.<br/>Lord, You’re God’s only Son<br/>And of God begotten<br/>“This is My beloved Son, in whom<br/>I am well-pleased.”<br/>',NULL,19961,1);
INSERT INTO stanza VALUES('NS169','2','To his young men he said then,<br/>“Stay and we’ll return to you.“<br/>To Moriah he led him,<br/>His son Isaac, just them two.<br/>Just the son and the father,<br/>Speaking with one another.<br/>Isaac said, “My father!” Abraham<br/>&nbsp;&nbsp;&nbsp;&nbsp;said, “Here I am.”<br/>',NULL,19962,2);
INSERT INTO stanza VALUES('NS169','3','As You spoke with Your Father<br/>You bore the wood God laid on You;<br/>As a lamb to the slaughter<br/>Obedient to the death were You.<br/>Precious blood of a Lamb,<br/>Slain from when earth began,<br/>Laid Your life down for Your sheep, in love,<br/>&nbsp;&nbsp;&nbsp;&nbsp;that I might live.<br/>',NULL,19963,3);
INSERT INTO stanza VALUES('NS169','4','Man of sorrows, I love You.<br/>From You men did hide their face.<br/>With no majesty to You,<br/>Despised, forsaken, and disgraced.<br/>For my sins You were crushed.<br/>Lord, I love You so much.<br/>Chastened, scourged and then pierced through, my griefs<br/>&nbsp;&nbsp;&nbsp;&nbsp;and sorrows bore.<br/>',NULL,19964,4);
INSERT INTO stanza VALUES('NS169','5','Dead in sins and offenses,<br/>I’m a bruised reed—smoking flax.<br/>Yet to death You were given,<br/>For of Your sheep, You’d not lose one.<br/>Like the woman, I’d weep,<br/>Flow my tears at Your feet.<br/>Jesus Lord, I just love You—dear Lord,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Jesus my Lord.<br/>',NULL,19965,5);
INSERT INTO stanza VALUES('NS170','1','Everybody ought to know; (Everybody ought to know)<br/>Everybody ought to know; (Everybody ought to know)<br/>Everybody ought to know; (Everybody ought to know)<br/>Where Jesus dwells.<br/>(Repeat)<br/>',NULL,19966,1);
INSERT INTO stanza VALUES('NS170','chorus','He is dwelling in our spirit;<br/>He is Breath and Life to us;<br/>We are one with Him in spirit.<br/>Everybody ought to know.<br/>',NULL,19967,2);
INSERT INTO stanza VALUES('NS170','2','Everybody ought to know;<br/>Everybody ought to know;<br/>Everybody ought to know;<br/>The living Christ.<br/>(Repeat)<br/>',NULL,19968,3);
INSERT INTO stanza VALUES('NS170','chorus','Christ is the life-giving Spirit;<br/>All God’s fullness He contains;<br/>We partake of all His riches<br/>Just by calling on His Name.<br/>',NULL,19969,4);
INSERT INTO stanza VALUES('NS171','1','I’m a beggar ’cause... I’m blind<br/>So I take what I... can find<br/>I’m groping for rea...lity<br/>Only wishing I... could see<br/>My parents, they can see<br/>Why is this blindness in me?<br/>All I know is I want to see reality.<br/>',NULL,19970,1);
INSERT INTO stanza VALUES('NS171','2','Lord, I am sitting by... the road<br/>Begging outside of Je...richo<br/>Now, Lord I hear that You... pass by<br/>Lord, Son of David... I cry<br/>Lord, Son of David, I cry<br/>Please, Christ, don’t pass me by<br/>I believe that you can open my eyes.<br/>',NULL,19971,2);
INSERT INTO stanza VALUES('NS171','3','You gave me life but where’s... my sight?<br/>I am still blind and that’s... my plight<br/>Blind lead the blind and then... both fall<br/>So right now on You... I call<br/>Jesus have mercy on me<br/>Open my eyes that I might see<br/>All I know is my only hope is in You.<br/>',NULL,19972,3);
INSERT INTO stanza VALUES('NS171','4','Lord I am rebuked by... the crowd<br/>For You I cry out more... the loud<br/>All the world wants to di...stract me<br/>So I forget that I... can’t see<br/>Jesus don’t leave me behind<br/>You are the one I want to find<br/>All I know is I just really need You.<br/>',NULL,19973,4);
INSERT INTO stanza VALUES('NS171','5','Still I’m afraid that You’ll... go on<br/>But joyful ears hear You... respond<br/>What would you like for me... to do<br/>Oh Christ I just want to see You<br/>Open my eyes to... see You<br/>Let me find what my spirit can do<br/>All I know is I just want to see You.<br/>',NULL,19974,5);
INSERT INTO stanza VALUES('NS171','6','In my spirit I... can see<br/>Because that’s where You... touch me<br/>By your touch dear Lord... I’m healed<br/>All my sin and death... must yield<br/>Now Lord, I am healed<br/>In my spirit You are so real<br/>All I know is I want to keep touching You.<br/>',NULL,19975,6);
INSERT INTO stanza VALUES('NS171','7','Lord my sight is for... one thing<br/>So that I to You... can cling<br/>I think I’m in love... with You<br/>No one else for me... will do<br/>Lord Christ let me follow You please<br/>You’re so real and so special to me<br/>All I know is Lord I never want to leave.<br/>',NULL,19976,7);
INSERT INTO stanza VALUES('NS172','1','I had a debt I could not pay,<br/>He paid the debt He did not owe,<br/>I needed someone,<br/>To wash my sins away.<br/>And now I sing a brand new song,<br/>“Amazing grace” all day long,<br/>Christ Jesus paid the debt,<br/>That I could never pay.<br/>',NULL,19977,1);
INSERT INTO stanza VALUES('NS173','1','The faith is the economy, the economy of God<br/>The household administration, the dispensing of our God<br/>The truth is the contents, the reality of the faith,<br/>According to God’s economy.<br/>',NULL,19978,1);
INSERT INTO stanza VALUES('NS173','chorus','Godliness is a living that expresses<br/>The divine reality,<br/>An expression of God in all His riches;<br/>Full of all gravity.<br/>',NULL,19979,2);
INSERT INTO stanza VALUES('NS173','2','Healthy teaching, words, and speaking<br/>Are the ministry of the truth,<br/>Ministering into people the reality of these truths;<br/>Eternal life is the means and the power to carry out,<br/>The divine realities of the faith;<br/>',NULL,19980,3);
INSERT INTO stanza VALUES('NS173','3','Faith is the response to the truth of the faith<br/>Conscience is a test and a check to preserve us in the faith.<br/>The faith is the economy, the economy of God,<br/>The household administration, the dispensing of our God;<br/>',NULL,19981,4);
INSERT INTO stanza VALUES('NS173','4','The faith, the truth, expressed in healthy words,<br/>Carried out in power by His life<br/>Expressed in Godly living responded to by faith,<br/>Kept and held in check by our conscience.<br/>',NULL,19982,5);
INSERT INTO stanza VALUES('NS174','chorus','Victory through Christ’s resurrection<br/>The victory is won!<br/>Praise Him for what He has done<br/>The victory is won!<br/>',NULL,19983,1);
INSERT INTO stanza VALUES('NS174','1','The victory over death,<br/>Over Satan and the world<br/>He defeated them triumphantly<br/>For all to see,<br/>Oh, what a victory!<br/>',NULL,19984,2);
INSERT INTO stanza VALUES('NS174','2','Designated as the Son<br/>Bringing man into God<br/>He uplifted humanity<br/>Displayed His glory<br/>Oh, what a victory!<br/>',NULL,19985,3);
INSERT INTO stanza VALUES('NS174','3','He became the Spirit too<br/>So that He could dwell in us<br/>He’s dispensing into you and me<br/>Now He’s life-giving<br/>Oh, what a victory!<br/>',NULL,19986,4);
INSERT INTO stanza VALUES('NS174','4','He regenerated us<br/>Now we’re brothers of the Lord<br/>We’re the members of His family<br/>We’re in the Body<br/>Oh, what a victory!<br/>',NULL,19987,5);
INSERT INTO stanza VALUES('NS174','5','Now we partake of Him<br/>In His victory we share<br/>He’s available to us daily<br/>In God’s economy<br/>We’re enjoying...<br/>',NULL,19988,6);
INSERT INTO stanza VALUES('NS175','1','Lord, there’s always been one person<br/>Like Abraham who ran to meet You.<br/>Samuel, he ministered<br/>And David had a heart full of praise,<br/>But You want many more.<br/>',NULL,19989,1);
INSERT INTO stanza VALUES('NS175','2','Lord, we want to be that people<br/>That minister and refresh You,<br/>Meet Your need, and wash Your feet,<br/>That satisfy Your heart’s desire<br/>And be a friend to You.<br/>What can we do?<br/>',NULL,19990,2);
INSERT INTO stanza VALUES('NS175','chorus','We can call O Lord,<br/>We can praise Your name,<br/>Turn our heart to You,<br/>Let You rule and reign.<br/>Lord, a single heart that’s true,<br/>That’s what we desire.<br/>',NULL,19991,3);
INSERT INTO stanza VALUES('NS175','3','Lord, You’ve shown You’re rich in mercy<br/>To those saints who stand together<br/>In Your plan, one new man.<br/>So grant us all a single heart;<br/>A heart that just loves You<br/>A heart that’s true.<br/>',NULL,19992,4);
INSERT INTO stanza VALUES('NS175','chorus','We can call O Lord.<br/>We can praise Your name,<br/>Turn our heart to You,<br/>Let You rule and reign.<br/>Lord, a single heart that’s true,<br/>That’s what we desire—<br/>A heart for You.<br/>',NULL,19993,5);
INSERT INTO stanza VALUES('NS176','1','Oh listen to a story of abounding grace<br/>Of how our God came down to earth to join the human race<br/>And through His kind intention, He came up with a plan<br/>That He Himself might be expressed by dispensing into man.<br/>',NULL,19994,1);
INSERT INTO stanza VALUES('NS176','chorus','Oh what a kind intention, oh what abounding grace<br/>How our God came down to earth to join the human race<br/>It surely was a mystery so deep we could not trace<br/>That we might be to the praise of the glory of His grace.<br/>',NULL,19995,2);
INSERT INTO stanza VALUES('NS176','2','For God had predetermined, by His counsel and His will<br/>That man might be a vessel, which He Himself would fill<br/>And so for this He chose us, back in eternity<br/>And He predestinated us His very sons to be.<br/>',NULL,19996,3);
INSERT INTO stanza VALUES('NS176','3','His task, it was not easy, it surely took much grace<br/>When on the earth He first appeared, a man in time and space<br/>And then for thirty-three long years, He lived out God in Man<br/>That He might fully carry out all of the Father’s plan.<br/>',NULL,19997,4);
INSERT INTO stanza VALUES('NS176','4','At the end of His lifetime, He did a wondrous thing<br/>Went to the cross and shed His blood, redemption to win<br/>This brought us into favour, into a blessed place<br/>For God forgave our offenses by the riches of His grace.<br/>',NULL,19998,5);
INSERT INTO stanza VALUES('NS176','5','Now in the application, the Spirit’s moving in<br/>Applying all the Son has done, forgiving all our sin<br/>He’s sealing God into us, full sonship to bring<br/>Oh, this is the mystery of the universe, and this is why we sing.<br/>',NULL,19999,6);
INSERT INTO stanza VALUES('NS177','1','The Triune God and the Person<br/>And the work of Christ,<br/>The Triune God is a mystery,<br/>The mystery of life.<br/>The Father, Son, and Spirit—<br/>Three-One now to be,<br/>Not for comprehending,<br/>But to flow into me.<br/>',NULL,20000,1);
INSERT INTO stanza VALUES('NS177','2','The Triune God is forever,<br/>Forever to be<br/>The life supply in my spirit;<br/>He’s dwelling in me!<br/>The Father in the Son came<br/>Displayed for all to see;<br/>The Son as Spirit flows now<br/>To flow God into me.<br/>',NULL,20001,2);
INSERT INTO stanza VALUES('NS177','3','I’m calling His name “Lord Jesus“;<br/>He’s coming in my heart.<br/>He’s spreading out from my spirit<br/>To all my inward parts.<br/>The more I contact daily,<br/>The more my heart Christ’s home,<br/>And with the saints I’m built up<br/>Into the church, Christ’s home!<br/>(Repeat verse 3)<br/>',NULL,20002,3);
INSERT INTO stanza VALUES('NS178','1','Born of my father, descended from Adam,<br/>A life in my flesh is God’s enemy.<br/>I have inherited God’s condemnation,<br/>Death and sin were reigning in me.<br/>',NULL,20003,1);
INSERT INTO stanza VALUES('NS178','2','But love eternal appeared and He called me,<br/>Out from the lost and hopeless race.<br/>Into His Son now I have been transferred,<br/>Born of the Spirit, into His grace.<br/>',NULL,20004,2);
INSERT INTO stanza VALUES('NS178','3','I am God’s child now, free to enjoy Him.<br/>The Spirit of Life is reigning in me.<br/>Christ is my walking, my living, my breathing,<br/>All that I have and ever will be.<br/>',NULL,20005,3);
INSERT INTO stanza VALUES('NS178','4','Chosen and guided into His purpose,<br/>From individual to corporate man.<br/>Now in His Body, we can experience<br/>All the unlimited grace of His plan.<br/>',NULL,20006,4);
INSERT INTO stanza VALUES('NS178','5','This is the mystery hidden from ages.<br/>For this God brought us from sinner to son.<br/>Practical church life, daily transforming<br/>Into the oneness, God’s expression.<br/>',NULL,20007,5);
INSERT INTO stanza VALUES('NS179','1','Recall how David swore,<br/>“I’ll not come into my house,<br/>Nor go up to my bed,<br/>Give slumber to mine eyelids,<br/>Until I find a place for Thee,<br/>A place, O Lord, for Thee.“<br/>Our mighty God desires a home<br/>Where all His own may come.<br/>',NULL,20008,1);
INSERT INTO stanza VALUES('NS179','2','How blinded we have been:<br/>“We’ll build Your habitation“<br/>When we are short of Christ—<br/>We need Your saturation!<br/>O Lord, You care for our house!<br/>Oh, what a blessed word!<br/>As You’re to God, You’d be to us—<br/>A mutual abode.<br/>',NULL,20009,2);
INSERT INTO stanza VALUES('NS179','3','There’s nothing that we are<br/>Or have or do well-pleasing;<br/>We need Thee, glorious Christ,<br/>Inwrought into our being.<br/>O Lord, our heart’s still vacant now!<br/>Come in and settle down.<br/>Come saturate and permeate<br/>And fill us with Yourself.<br/>',NULL,20010,3);
INSERT INTO stanza VALUES('NS179','4','Our spirit You have filled<br/>At our regeneration,<br/>But mind, emotion, will<br/>Await Your saturation.<br/>How much of You is built in us<br/>To make our heart Your home?<br/>O Triune God, we welcome You.<br/>Come build, oh, build in us.<br/>',NULL,20011,4);
INSERT INTO stanza VALUES('NS179','5','Into our innermost<br/>Intrinsic constitution,<br/>Come, Lord, Yourself dispense<br/>By constant, fresh infusion;<br/>Transform us, Lord, and work Yourself,<br/>As God’s embodiment,<br/>Into our heart, and life each part,<br/>With Your reality.<br/>',NULL,20012,5);
INSERT INTO stanza VALUES('NS179','6','To build Your house today,<br/>Self-effort You’re refusing—<br/>All stubble, wood, and hay;<br/>Gold, silver, gems, You’re using.<br/>The consummated Triune God<br/>Transmitted into us<br/>Now builds Himself into a home—<br/>His dwelling, glorious.<br/>(Repeat the last four lines)<br/>',NULL,20013,6);
INSERT INTO stanza VALUES('NS180','1','God’s eternal economy<br/>Is to make man the same as He is<br/>In life and nature,<br/>But not in the Godhead<br/>And to make Himself one with man<br/>And man one with Him<br/>Thus to be enlarged and expanded in His expression<br/>That all His divine, that all His divine<br/>Attributes may be expressed in human virtues.<br/>',NULL,20014,1);
INSERT INTO stanza VALUES('NS181','1','God’s economy and His eternal plan,<br/>His heart’s desire and intention is to be one with man.<br/>Yet man has failed completely throughout all history.<br/>But hallelujah! Praise the Lord! God’s life is now in me.<br/>',NULL,20015,1);
INSERT INTO stanza VALUES('NS181','2','Now this life in me is flowing as the river of water of life,<br/>Washing away all my sins, my cares, and all my strife.<br/>This life is overcoming situations in my day.<br/>Hallelujah! Praise the Lord! For this is what I pray:<br/>',NULL,20016,2);
INSERT INTO stanza VALUES('NS181','chorus','Lord Jesus, I love You!<br/>I give You the preeminence in what I do.<br/>Enjoying You is the overcoming way.<br/>Thank You for Your recovery; Your Word we will obey.<br/>',NULL,20017,3);
INSERT INTO stanza VALUES('NS181','3','Thank You for our situations and the environments we are in.<br/>That we’d turn to You in all things, and turn away from sin.<br/>We’d drop all our anxieties and put our trust in You.<br/>And experience this living One whose life is ever new.<br/>',NULL,20018,4);
INSERT INTO stanza VALUES('NS181','4','Now the church life is so precious with all the saints so dear.<br/>Enjoying all Your riches, our vision is so clear,<br/>That all would prophesy of Christ from what they’ve seen,<br/>According to Your scripture in First Corinthians fourteen.<br/>',NULL,20019,5);
INSERT INTO stanza VALUES('NS182','chorus','Christ is our light, our food, our air;<br/>He’s everything we’ll ever need.<br/>Christ is our drink, our life, our way,<br/>If in our being, He’d be freed.<br/>',NULL,20020,1);
INSERT INTO stanza VALUES('NS182','1','Sisters: You say He’s mighty God.<br/>Brothers: I say He’s man.<br/>Sisters: Son, Spirit, Father all,<br/>All: He’s rich, O so rich, when we call.<br/>',NULL,20021,2);
INSERT INTO stanza VALUES('NS182','2','Brothers: He’s Son of righteousness,<br/>Sisters: Hope, peace, and faith,<br/>Brothers: The Lamb of God is He,<br/>All: So call on Him now, don’t you wait.<br/>',NULL,20022,3);
INSERT INTO stanza VALUES('NS182','3','Sisters: You say He’s Son of God,<br/>Brothers: And Son of Man,<br/>Sisters: Firstborn among the dead,<br/>All: Firstborn of creation, AMEN!<br/>',NULL,20023,4);
INSERT INTO stanza VALUES('NS182','4','Brothers: Our Lord’s the great I AM,<br/>Sisters: The start, the end.<br/>Brothers: Alpha, Omega,<br/>All: Lord Jesus, come quickly, AMEN!<br/>',NULL,20024,5);
INSERT INTO stanza VALUES('NS183','1','Christ is a genuine man,<br/>The perfect and finest man,<br/>Obedient, serving, no appearance of evil,<br/>The finest personality,<br/>Divinity expressed through humanity.<br/>',NULL,20025,1);
INSERT INTO stanza VALUES('NS183','2','Christ is the pattern for our human living.<br/>His perfect life is filling us.<br/>Christ is the pattern for our human living,<br/>The fine and balanced humanity of Jesus!<br/>(Repeat 1st stanza)<br/>',NULL,20026,2);
INSERT INTO stanza VALUES('NS184','1','To be baptized in the Spirit<br/>Is to get into the Spirit<br/>And to be lost in Him.<br/>To drink of the Spirit<br/>Is to take the Spirit in<br/>And have our being saturated with Him.<br/>By these two procedures<br/>We are mingled with the Spirit.<br/>To be baptized in the Spirit<br/>Is the initiation of the mingling<br/>And is once for all.<br/>To drink the Spirit<br/>Is the accomplishment of the mingling<br/>And is perpetual forever.<br/>',NULL,20027,1);
INSERT INTO stanza VALUES('NS185','1','The spirit of the prophet<br/>Is subject to the prophet;<br/>The word declares it so.<br/>I don’t have to wait for an inspiration,<br/>My spirit is ready to go.<br/>I don’t have to live according to my feelings,<br/>Or wait for a better day.<br/>I can turn, I can call, “Lord Jesus!”<br/>',NULL,20028,1);
INSERT INTO stanza VALUES('NS186','1','Now the Lord is the Spirit—that’s how<br/>He can get inside of you right now.<br/>It’s so easy to be filled with Him.<br/>He’s made it really simple.<br/>One, two, three—<br/>That’s how easy it can be.<br/>',NULL,20029,1);
INSERT INTO stanza VALUES('NS186','chorus','O Lord! Amen!<br/>That’s the way to let Him in.<br/>Hallelujah! I love to hear it.<br/>He who is joined to the Lord is one spirit.<br/>',NULL,20030,2);
INSERT INTO stanza VALUES('NS186','2','Now the Lord is the living air;<br/>You can breathe Him in anywhere—<br/>Anytime of day, whenever you please.<br/>He’s made it really easy.<br/>O Lord! Amen!<br/>Let’s sing it again.<br/>',NULL,20031,3);
INSERT INTO stanza VALUES('NS186','3','Now the Lord lives inside of me.<br/>And He’s filling me constantly.<br/>Yes, He’s filling up every gap.<br/>He makes me really happy.<br/>I’m so happy!<br/>Hallelujah! Taste and see!<br/>',NULL,20032,4);
INSERT INTO stanza VALUES('NS187','1','Turn to your spirit, where the Spirit of Jesus is;<br/>Turn to your spirit—Oh, how it makes you sing!<br/>Turn to your spirit in the middle of everything.<br/>Turn to the Lord. Oh, turn to the Lord!<br/>',NULL,20033,1);
INSERT INTO stanza VALUES('NS187','2','Turn to your spirit, where the Spirit of Jesus is,<br/>Turn to your spirit—where life is really found.<br/>Turn to your spirit if you’re up or if you’re down,<br/>Turn to the Lord. Oh, turn to the Lord!<br/>',NULL,20034,2);
INSERT INTO stanza VALUES('NS187','3','Turn to your spirit, where the Spirit of Jesus is,<br/>Turn to your spirit, calling upon His name—<br/>Now and forever, Jesus is the very same.<br/>Turn to the Lord. Oh, turn to the Lord!<br/>',NULL,20035,3);
INSERT INTO stanza VALUES('NS188','1','It’s the life, life, life that makes us want to shout,<br/>Hallelujah! Praise the Lord!<br/>It’s the life, life, life that makes us want to shout,<br/>Hallelujah! Praise the Lord!<br/>We’re full of joy! How glorious<br/>That we have Jesus Christ in us!<br/>That we have Jesus Christ in us!<br/>',NULL,20036,1);
INSERT INTO stanza VALUES('NS189','1','The issue of the third fall of man,<br/>The withdrawing of the Holy Spirit;<br/>The coming flood to destroy mankind,<br/>But Noah found grace in the eyes of Jehovah:<br/>Lord, make me like Noah,<br/>Finding grace every day.<br/>Grace is God Himself enjoyed by us<br/>Through our cooperation<br/>By calling, “Oh Lord Jesus.”<br/>',NULL,20037,1);
INSERT INTO stanza VALUES('NS190','1','I want to be filled<br/>with the Triune God.<br/>He makes me happy;<br/>I want to be filled with Him.<br/>(Repeat)<br/>',NULL,20038,1);
INSERT INTO stanza VALUES('NS190','chorus','So I will drink, drink, drink, drink, drink<br/>that living water,<br/>And I will eat, eat, eat, eat, eat<br/>the tree of life,<br/>And I will call upon His name,<br/>O Lord Jesus!<br/>’cause I want to be filled<br/>up, up, up<br/>Oh, I want to be filled<br/>up, up, up<br/>Yes, I want to be filled<br/>up, up, up with Him.<br/>',NULL,20039,2);
INSERT INTO stanza VALUES('NS191','1','If you are hungry, come to the feast.<br/>Open to Jesus—He is all you need.<br/>He fed the thousands, now He’ll feed you.<br/>Just open your mouth and take Him in—<br/>That’s all you have to do.<br/>We’ve found that calling on Jesus fills us within.<br/>He came as food, so now we take Him in.<br/>No doctrines or forms that you have to learn<br/>To come and meet with us.<br/>Just enjoy the Lord Jesus!<br/>',NULL,20040,1);
INSERT INTO stanza VALUES('NS191','2','If you are thirsty, He’s heard your cry.<br/>He is a fountain that will not run dry.<br/>He’s quenching our longings, we’re satisfied,<br/>Just eating and drinking the risen Lord!<br/>Yes, that is why He died;<br/>So He could become the Spirit, get into us,<br/>Fill all our being—Oh, how glorious!<br/>It’s really so simple—just take and eat;<br/>That’s all you have to do.<br/>Come enjoy the Lord Jesus.<br/>',NULL,20041,2);
INSERT INTO stanza VALUES('NS192','1','Some, these days, would tell us that our Jesus is not food,<br/>That we only need to know about Him and do good,<br/>But we’re glad to tell you brothers, it’s just not that way—<br/>Jesus is the bread of life; we eat Him every day.<br/>',NULL,20042,1);
INSERT INTO stanza VALUES('NS192','chorus','We love the church life, eating,<br/>drinking, breathing Jesus.<br/>We love the church life, taking<br/>in God’s Word.<br/>We love to hear those “O Lord,<br/>Amen, Hallelujahs!“<br/>We love the church life, feasting<br/>with the Lord.<br/>',NULL,20043,2);
INSERT INTO stanza VALUES('NS192','2','When He fills our inward parts, we’re never quite the same,<br/>So much richness we can taste by calling on His name.<br/>“Services” but once a week for us will never do.<br/>Every day we need the fellowship to take us through.<br/>',NULL,20044,3);
INSERT INTO stanza VALUES('NS192','3','If these latter days and situations of the world<br/>Make you feel that round a vicious circle you are swirled,<br/>Then please listen closely to the things we have to say; <br/>It may be that you will find with us a better way.<br/>',NULL,20045,4);
INSERT INTO stanza VALUES('NS193','1','It is God’s commandment and it is His desire<br/>That His people call, call upon His name.<br/>It’s the joyful way, the joyful way to drink<br/>From the fountain of God’s rich salvation.<br/>Calling is the way to delight oneself in God;<br/>That is to enjoy Him, enjoy the Lord our God.<br/>Hence, we as God’s people, must daily call on Him.<br/>This must be our practice for God’s jubilee.<br/>',NULL,20046,1);
INSERT INTO stanza VALUES('NS194','1','Lord, You are the living spring,<br/>The river of water of life;<br/>Only You can quench my thirst;<br/>Only You satisfy.<br/>Lord, You are the living tree,<br/>You are the Tree of Life;<br/>Only You can fill my hunger;<br/>Only You satisfy.<br/>',NULL,20047,1);
INSERT INTO stanza VALUES('NS194','chorus','Every moment in so many ways<br/>He is the sure supply;<br/>Now and forever and always,<br/>Only You satisfy.<br/>',NULL,20048,2);
INSERT INTO stanza VALUES('NS194','2','Lord, You are the living vine,<br/>In You we would abide;<br/>Only You give life divine;<br/>Only You satisfy.<br/>So we must praise<br/>And we must sing,<br/>And we must testify;<br/>Lord, You are the only One;<br/>Only You satisfy.<br/>',NULL,20049,3);
INSERT INTO stanza VALUES('NS195','1','Breathing in the Lord<br/>Is how we live today.<br/>Not by thinking do we live,<br/>But breathing is the way.<br/>We just call “O Lord!“<br/>From very deep within,<br/>And with joy we testify<br/>We’re breathing in of Him.<br/>Breathe in Christ,<br/>Breathe in Life,<br/>Breathe Him in today!<br/>He’s our very life supply,<br/>So breathe Him right away! (Repeat)<br/>',NULL,20050,1);
INSERT INTO stanza VALUES('NS195','2','He’s so wonderful,<br/>The Breath of Life is He;<br/>Once he simply was a man,<br/>But now He’s breath to me.<br/>He has changed His form;<br/>The Spirit now is He.<br/>He’s the Christ breathed out from God,<br/>The Breath breathed in by me.<br/>Everywhere, everywhere,<br/>Christ is life to me;<br/>I just call upon His name,<br/>And breath comes into me! (Repeat)<br/>',NULL,20051,2);
INSERT INTO stanza VALUES('NS196','1','Enter into the enjoyment<br/>Experience the Lord<br/>He’s the rich supply<br/>Don’t let a day go by<br/>Without the presence of the Lord!<br/>We don’t care about the tree of knowledge<br/>Good and evil kill us dead.<br/>We don’t need to behave ourselves into the grave<br/>Just touch the living Lord instead.<br/>',NULL,20052,1);
INSERT INTO stanza VALUES('NS197','1','Lord, You are my only goal!<br/>You’re my only hope!<br/>I only care for You!<br/>I never could replace You,<br/>And I would never want to.<br/>I have everything, Lord—<br/>I have You!<br/>',NULL,20053,1);
INSERT INTO stanza VALUES('NS197','2','Lord, I only live for You—<br/>Not anything else!<br/>In everything You’re my source;<br/>No more good intentions,<br/>No more right or wrong.<br/>I don’t want a “good” life—<br/>I want You!<br/>',NULL,20054,2);
INSERT INTO stanza VALUES('NS198','1','It is not a message that I’ve heard, (Just the Christ, in the word,)<br/>Not some points that I’ve learned, (The Christ in all I’ve heard,)<br/>Not a song or verse I know by heart, (But Christ in every song or verse,)<br/>That can meet your need, or wash your feet, (Christ can meet your need,)<br/>Touch your heart, or fill the void,<br/>But it’s Christ, just the Christ, (Just this Christ,)<br/>That I’ve enjoyed. (Just this Christ enjoyed.)<br/>',NULL,20055,1);
INSERT INTO stanza VALUES('NS198','2','It is nothing good that is of myself, (Just the Christ, in you and me,)<br/>Nothing of my natural life, (The Christ who’s all to be,)<br/>Not the best of fruit from the knowledge tree, (Only Christ we’d know,)<br/>That can touch your life, or turn your heart, (Christ can touch your life,)<br/>Refresh you in your deepest part,<br/>But it’s Christ, just the Christ, (Just this Christ,)<br/>Lived out through me. (Just the Christ in me.)<br/>',NULL,20056,2);
INSERT INTO stanza VALUES('NS199','1','Nearer each day to me,<br/>Dearer each day to me,<br/>This Person inside me is<br/>Becoming reality.<br/>Saving me, loving me,<br/>Faith and hope giving me.<br/>You’re all the world to me Jesus, my Lord.<br/>',NULL,20057,1);
INSERT INTO stanza VALUES('NS199','2','Even when faith is small,<br/>When there’s no hope at all,<br/>I hear Him say to me,<br/>Trust in Me and you’ll see,<br/>That I’ll supply all your needs,<br/>If only you will believe.<br/>All anxious doubts will cease,<br/>While trusting in Me.<br/>',NULL,20058,2);
INSERT INTO stanza VALUES('NS200','1','Jesus Lord, Jesus Lord.<br/>How we long to touch Thee,<br/>More and more, more and more,<br/>That You may grow within us.<br/>“Blossom of Gold” may You bloom and grow.<br/>Bloom and grow forever<br/>Then all will see, all will know,<br/>You are the Lord within us.<br/>',NULL,20059,1);
INSERT INTO stanza VALUES('NS201','1','I just keep calling, “O Lord!“<br/>As I walk along;<br/>I just keep calling, “O Lord“<br/>And He gives a song.<br/>Though the storm clouds darken the sky,<br/>O’er the upward trail;<br/>I just keep calling, “O Lord“;<br/>He will never fail.<br/>He’s a faithful friend,<br/>Such a faithful friend;<br/>I can count on Him<br/>To the very end.<br/>Though the storm clouds darken the sky,<br/>O’er the upward trail;<br/>I just keep calling, “O Lord“<br/>He will never fail.<br/>',NULL,20060,1);
INSERT INTO stanza VALUES('NS202','1','Lord, I love You, Lord, I need You,<br/>You’re the One, the One I need,<br/>To live this life, Lord, I need You always;<br/>By Your presence, Lord, take lead.<br/>Lord, look into me,<br/>And infuse me<br/>To walk by the strength of Your eyes.<br/>Lord embrace me,<br/>Bear me in You,<br/>Deep in Your love I hide.<br/>And when I’m weak, Lord, and can’t go on more,<br/>Lift my eyes to gaze on You;<br/>Speak softly to me, Come in, subdue me;<br/>In Your strength, Lord, take me through.<br/>',NULL,20061,1);
INSERT INTO stanza VALUES('NS203','1','Lord, I have the life; but Lord, You know<br/>That I need the lights of the fourth day.<br/>I have the light from the first day already,<br/>But I need the lights of the fourth day.<br/>Lord Jesus, I need You as the Sun.<br/>I need to contact You directly.<br/>I want to be in Your presence<br/>Day by day, I want to be under Your shining.<br/>I also need the church, the moon,<br/>And I need the stars;<br/>I need the overcoming saints,<br/>The ones who are shining, who turn many to righteousness,<br/>I need those who can turn people<br/>From darkness to light!<br/>',NULL,20062,1);
INSERT INTO stanza VALUES('NS204','1','When all around my sky is falling<br/>And fear and doubt run deep in my heart,<br/>It’s in these times I’m on You calling,<br/>Opening to You, Lord, my deepest part.<br/>',NULL,20063,1);
INSERT INTO stanza VALUES('NS204','chorus','Oh, Lord Jesus!<br/>How I love You!<br/>And I need You<br/>All the time.<br/>Ahh, to touch You<br/>In my weakness,<br/>And to hold You,<br/>Savior mine.<br/>',NULL,20064,2);
INSERT INTO stanza VALUES('NS204','2','Lord, by Your mercy You consume me.<br/>It’s all according to God’s plan.<br/>By resurrection life renew me,<br/>Day by day, my inner man.<br/>',NULL,20065,3);
INSERT INTO stanza VALUES('NS205','1','Nothing can content me more,<br/>Than Jesus in the morning,<br/>Echoing the hallways of my heart.<br/>My eyes from darkness clearly see,<br/>The love within His smile, for me.<br/>It’s then I know the reason for my life.<br/>',NULL,20066,1);
INSERT INTO stanza VALUES('NS205','chorus','Jesus, You’re my reason for being here,<br/>Oh, it’s so clear; so I sing!<br/>',NULL,20067,2);
INSERT INTO stanza VALUES('NS205','2','No greater joy can be for me,<br/>Than turning to Jesus,<br/>When the shadows of the day begin to haunt me.<br/>His soft, warm Spirit spreads throughout,<br/>Quenching all my fear and doubt.<br/>Jesus is the all-inclusive love.<br/>',NULL,20068,3);
INSERT INTO stanza VALUES('NS206','1','Lord, do unveil<br/>The more we strive, the more we fail<br/>All the strife—they all come out to no avail.<br/>Lord, they’re just not for your need<br/>By “self“, we won’t succeed.<br/>',NULL,20069,1);
INSERT INTO stanza VALUES('NS206','2','Lord, we confess<br/>We are not able, Lord, unless<br/>We have You; You’re all in all—You’re our success!<br/>All we need, O Lord, is You<br/>’Cause nothing else will do.<br/>',NULL,20070,2);
INSERT INTO stanza VALUES('NS206','3','O Lord, we pray<br/>Increase Thyself in us each day<br/>And the “self“—decrease it ’til it’s done away.<br/>Lord, we want the growth in life<br/>We don’t want all the strife.<br/>',NULL,20071,3);
INSERT INTO stanza VALUES('NS206','4','Lord, life’s begun<br/>Two spirits mingled into one<br/>Day by day, walk in the spirit and we’ve won!<br/>Then the “self” will be decreased<br/>And Christ in us increased.<br/>',NULL,20072,4);
INSERT INTO stanza VALUES('NS207','1','Every new day’s a new start.<br/>Lord, again we’re coming to You.<br/>Lord, could You ever break through within us<br/>If, Lord, we gave You a part?<br/>',NULL,20073,1);
INSERT INTO stanza VALUES('NS207','chorus','O Lord, we can’t do it on our own.<br/>O Lord Jesus, how we need You!<br/>Win us, woo us, to Thyself, Lord,<br/>That we’d ever stay, Lord, with You.<br/>',NULL,20074,2);
INSERT INTO stanza VALUES('NS207','2','Lord, before time had begun,<br/>We were marked and called out by You.<br/>We had no choice, we were trapped by You, Lord;<br/>We had no place we could run.<br/>',NULL,20075,3);
INSERT INTO stanza VALUES('NS207','3','Some of my friends are so free.<br/>Who could I blame, Lord, but Thee?<br/>I cannot do all the things that they do<br/>Because You set me apart.<br/>',NULL,20076,4);
INSERT INTO stanza VALUES('NS207','4','Lord, I’m realizing that<br/>Loving You’s a tender trap.<br/>Since You have kissed me, my heart has melted;<br/>All my resistance has cracked.<br/>',NULL,20077,5);
INSERT INTO stanza VALUES('NS208','1','There are three kinds of life in our existence today:<br/>There is Bios, the physical, and soul-life, Psuche;<br/>Now the third life is God’s life and its called Zoe;<br/>And we all have to choose what life we’ll live by today.<br/>',NULL,20078,1);
INSERT INTO stanza VALUES('NS208','chorus','Oh, it’s God in Christ Jesus, through the Spirit today,<br/>Who is flowing within us, flowing through us this way.<br/>We don’t care for the Bios; we don’t want Psuche;<br/>All we want is God’s Zoe life to fill us today.<br/>',NULL,20079,2);
INSERT INTO stanza VALUES('NS208','2','We don’t care for the Bios, we don’t care for the soul.<br/>We don’t care for the cares of life, world’s pleasure and show.<br/>We don’t care for the pride of life, the flesh and sin—<br/>We say, “No!” to the soul life, we’ll take God’s life within.<br/>',NULL,20080,3);
INSERT INTO stanza VALUES('NS208','3','Do you know what God’s life is? Well, just listen to this:<br/>It is God in Christ Jesus through the Spirit—no less!<br/>He is flowing within us, He is flowing through—<br/>Hallelujah! He’s moving to make everything new.<br/>',NULL,20081,4);
INSERT INTO stanza VALUES('NS208','4','We have this Life within us, in our spirit today;<br/>To our spirit we turn, O Lord, and take You this way.<br/>We can overcome Bios and the Psuche too;<br/>Hallelujah, the Spirit of the Lord takes us through.<br/>',NULL,20082,5);
INSERT INTO stanza VALUES('NS209','1','Lord, now I see,<br/>You only want me to believe<br/>Not to change.<br/>In all my failures and defeats<br/>To believe what You have done,<br/>And not in what I see.<br/>',NULL,20083,1);
INSERT INTO stanza VALUES('NS209','2','Lord I believe,<br/>When all around me is defeat<br/>And it seems that nothing’s changing outwardly.<br/>No! I’m not discouraged,<br/>I’m believing You.<br/>',NULL,20084,2);
INSERT INTO stanza VALUES('NS209','3','Yes, I believe,<br/>And there is no demand on me.<br/>Simple faith, yes, that is all You want from me.<br/>Freed from anxious doubting—<br/>I’m free to just believe!<br/>',NULL,20085,3);
INSERT INTO stanza VALUES('NS209','4','Believing You,<br/>Because, Lord, You are my success!<br/>When I fail, all I must do is just confess,<br/>And go on enjoying You—<br/>I love believing You!<br/>',NULL,20086,4);
INSERT INTO stanza VALUES('NS210','1','He understands you thoroughly;<br/>There’s nothing He does not know.<br/>All your problems and weaknesses<br/>Don’t say it isn’t so!<br/>He’s your Helper, sympathizing.<br/>He’s the Spirit. Don’t neglect Him.<br/>He’s praying for you<br/>And sustaining you.<br/>',NULL,20087,1);
INSERT INTO stanza VALUES('NS210','2','He gives support and comforts you,<br/>Interceding night and day.<br/>And when you’re weak He groans for you<br/>With words you cannot say.<br/>He’s the Spirit, interceding.<br/>He’s the Spirit. Don’t neglect this<br/>Wonderful One,<br/>Who is praying for you.<br/>',NULL,20088,2);
INSERT INTO stanza VALUES('NS210','3','So many times we are so weak,<br/>But Someone deep within<br/>Supplies the very help we need,<br/>And we’re upheld by Him.<br/>He says, “Don’t be disappointed.“<br/>He knows all your fears and failures;<br/>He’s praying for you<br/>As no one else can do.<br/>',NULL,20089,3);
INSERT INTO stanza VALUES('NS211','1','Jesus Lord, truly I love Thee;<br/>My heart refine!<br/>I’d redeem each precious moment,<br/>To enjoy Thy love divine.<br/>Lord, behold, all to Thee I yield,<br/>Constrained this day<br/>By compassions never failing,<br/>Thy perfecting care,<br/>Dear Lord, open mine ear,<br/>At the doorpost of God’s house,<br/>Responding to Thy voice,<br/>I would be Thine and Thine forever,<br/>Set me a seal on Thine heart,<br/>With Thy love, even Thy jealousy,<br/>Let me be Thy crazy lover <br/>Through all my days.<br/>',NULL,20090,1);
INSERT INTO stanza VALUES('NS211','2','God of glory, we bow the knee,<br/>Grant us today<br/>Spir’t of wisdom, revelation,<br/>The mystery to see,<br/>I’d outpour all my life for Thine economy,<br/>Just for Thine eternal pleasure,<br/>The Body of Christ,<br/>In my mingled spirit lead me<br/>To the Body’s reality,<br/>In Thine intensification<br/>Make us the testimony of Jesus<br/>O Lord! For this we yearn!<br/>Quickly come, as once Thou promised!<br/>Lord, our deepest longing<br/>Is Thy return!<br/>',NULL,20091,2);
INSERT INTO stanza VALUES('NS212','1','Each time in the morning, a while before dawn<br/>To You, Lord, I whisper a praise or a song,<br/>And feel Your life stirring so deep within me—<br/>My cup runneth over with joy!<br/>',NULL,20092,1);
INSERT INTO stanza VALUES('NS212','2','And then at the moment my heart turns to Thee,<br/>The eyes of my spirit Your presence can see;<br/>While all is so fresh and the sunlight breaks through—<br/>My cup runneth over with joy!<br/>',NULL,20093,2);
INSERT INTO stanza VALUES('NS212','3','And when at the noontime I’m hungry and worn<br/>And feel that the cares of this world have me torn,<br/>You come as my haven, my rest, and my food—<br/>My cup runneth over with joy!<br/>',NULL,20094,3);
INSERT INTO stanza VALUES('NS212','4','And then in the evening when my thoughts are free,<br/>Remembr’ing that You, Lord, still dwell within me,<br/>This sweet fact releases a river in me—<br/>My cup runneth over with joy!<br/>',NULL,20095,4);
INSERT INTO stanza VALUES('NS213','chorus','Reading the Bible—<br/>I love the Word of God!<br/>Reading the Bible—<br/>I love the Word of God!<br/>',NULL,20096,1);
INSERT INTO stanza VALUES('NS213','1','Every verse reveals Yourself to me,<br/>Every line conveys reality.<br/>When I pray the words that You breathed out<br/>You become so real to me.<br/>',NULL,20097,2);
INSERT INTO stanza VALUES('NS213','2','As I read, I pray, as I pray, I read,<br/>Mingling both as one spontaneously.<br/>You respond within with words so sweet,<br/>I repeat these words to Thee.<br/>',NULL,20098,3);
INSERT INTO stanza VALUES('NS213','3','I’m a newborn babe—it’s the milk I need,<br/>Not the knowledge of the dead teaching.<br/>When I eat Your word, it becomes to me<br/>My heart’s joy and rejoicing.<br/>',NULL,20099,4);
INSERT INTO stanza VALUES('NS213','4','Sweeter than honey, precious more than gold;<br/>It will not be void, but as the rain and snow,<br/>It will do Your will—bear the life divine,<br/>Bearing fruit a hundred-fold.<br/>',NULL,20100,5);
INSERT INTO stanza VALUES('NS213','5','When my heart is like a rock so cold,<br/>It’s Your word so strong that hammers stone,<br/>That the grain of life may come to me<br/>And supply me inwardly.<br/>',NULL,20101,6);
INSERT INTO stanza VALUES('NS213','6','It’s my food, my drink, and my life supply;<br/>I love to eat it every day and night.<br/>I just turn and open up to Him,<br/>And the rivers flow right in.<br/>',NULL,20102,7);
INSERT INTO stanza VALUES('NS214','chorus','Lord, grant me today’s supply of grace;<br/>May Your divine life grow apace;<br/>Little by little, day by day, to grow<br/>More and more, into You.<br/>',NULL,20103,1);
INSERT INTO stanza VALUES('NS214','1','Day by day, bit by bit, life will grow as is fit,<br/>Increasing gradually until,<br/>However imperceptibly,<br/>Your life matures within me.<br/>',NULL,20104,2);
INSERT INTO stanza VALUES('NS214','2','I would be desperately, constantly, patiently,<br/>Drawing each breath of life from You, Lord;<br/>Knowing that every day while I breathe,<br/>Your life will permeate me.<br/>',NULL,20105,3);
INSERT INTO stanza VALUES('NS214','3','Every day, may I rest, knowing that each bequest,<br/>Matches my daily need exactly;<br/>Jesus Christ intercedes for me,<br/>A member of His body.<br/>',NULL,20106,4);
INSERT INTO stanza VALUES('NS214','chorus','Lord, grant me a heavenly, corporate view;<br/>That all of my growth and prayers to You,<br/>Little by little, day by day,<br/>Would cause building up into You.<br/>',NULL,20107,5);
INSERT INTO stanza VALUES('NS214','4','We would be corporately, growing up steadily<br/>Till we reach the stature of Your fullness;<br/>Transforming and conforming us, Your<br/>Manifested people.<br/>',NULL,20108,6);
INSERT INTO stanza VALUES('NS214','chorus','Lord, grant me today’s supply of grace;<br/>May Your divine life grow apace;<br/>Little by little, day by day, to grow<br/>More and more, into You.<br/>',NULL,20109,7);
INSERT INTO stanza VALUES('NS214','chorus','Lord, grant me a heavenly, corporate view;<br/>That all of my growth and prayers to You,<br/>Little by little, day by day,<br/>Would cause building up into the New Jerusalem.<br/>',NULL,20110,8);
INSERT INTO stanza VALUES('NS215','1','I wake up this morning, Lord;<br/>The sun shines through my windowsill.<br/>How can I help but praise Your name!<br/>You’re my Lord and King!<br/>',NULL,20111,1);
INSERT INTO stanza VALUES('NS215','chorus','Because You...gave Your life up for me.<br/>The Spirit...You were raised to be.<br/>Now You are...living deep in me,<br/>As my hope of glory.<br/>',NULL,20112,2);
INSERT INTO stanza VALUES('NS215','2','Each day Your mercies they are new,<br/>To me refreshing as the dew;<br/>You are my bountiful supply.<br/>Every morning You’re nigh!<br/>',NULL,20113,3);
INSERT INTO stanza VALUES('NS215','3','For me You came from up above,<br/>Because You are the God of love;<br/>Your love will never let me go;<br/>Everyday it flows.<br/>',NULL,20114,4);
INSERT INTO stanza VALUES('NS215','4','Your love flows out to me as grace,<br/>Enabling me to run the race;<br/>As truth You’re my reality,<br/>As my all to be.<br/>',NULL,20115,5);
INSERT INTO stanza VALUES('NS215','5','As I walk on this pilgrim road,<br/>My flesh and self You will erode;<br/>In my heart, You will have Your way;<br/>Take more room each day.<br/>',NULL,20116,6);
INSERT INTO stanza VALUES('NS215','6','Each day the world I leave behind;<br/>You write Your laws upon my mind,<br/>Inscribing on my softened heart,<br/>Filling every part.<br/>',NULL,20117,7);
INSERT INTO stanza VALUES('NS215','7','O Lord, I’m just a tree in You,<br/>Rooted and being built in You,<br/>Absorbing all You are to me,<br/>What a place to be!<br/>',NULL,20118,8);
INSERT INTO stanza VALUES('NS216','1','Speak to me, Lord every day.<br/>Speak to me, Lord—I love to hear what You say.<br/>Speak to me, Lord until I have heard.<br/>Speak to me, Lord through Your living Word.<br/>',NULL,20119,1);
INSERT INTO stanza VALUES('NS216','2','Speak to me, Lord every day.<br/>Speak to me, Lord—I love to hear what You say.<br/>Speak to me, Lord, fill me with light.<br/>Speak to me, Lord all Your words of life.<br/>',NULL,20120,2);
INSERT INTO stanza VALUES('NS217','1','There’s a life that’s deeper than our mind,<br/>With experience of man, yet so divine.<br/>It’s a life that knows no bounds;<br/>And with glory is crowned;<br/>It’s of depth and height and breadth unsearchable.<br/>Now this life is just the Living One<br/>Manifested in the Person of the Son.<br/>As the Spirit, He flows;<br/>In our spirit He grows,<br/>Growing up to be the church that He desires.<br/>',NULL,20121,1);
INSERT INTO stanza VALUES('NS217','chorus','O Lord, we’re just for Your flowing;<br/>How we need a deeper knowing!<br/>Life is why we’re here<br/>And why You’ve come in us.<br/>Turn us, Lord, turn us now;<br/>Turn us deeply—Life is how<br/>You will get the church,<br/>The home You’re longing for.<br/>',NULL,20122,2);
INSERT INTO stanza VALUES('NS217','2','In the church, we all can apprehend<br/>All the riches of this life that is within.<br/>Not just shallowness with strife,<br/>But a deep and peaceful life<br/>Is just waiting to flow out, a living spring.<br/>With the saints it’s easy to be bold,<br/>To pursue this life, to gain it, to lay hold.<br/>All the other things we find,<br/>Must be quickly left behind,<br/>So that only life remains for us to see.<br/>',NULL,20123,3);
INSERT INTO stanza VALUES('NS217','3','Deeper, Lord our turn must be to You;<br/>We would move by life in everything we do;<br/>All our concepts refute,<br/>For Your life be absolute—<br/>Grant us grace to turn much deeper day by day.<br/>When we touch our spirit—such a thrill!<br/>This is far beyond emotion, mind, and will—<br/>It’s within our hidden part—<br/>Come, make home in all our heart;<br/>Let Your presence flow as rivers deep within.<br/>',NULL,20124,4);
INSERT INTO stanza VALUES('NS218','1','Day one You came to me,<br/>Brooding so tenderly,<br/>You spoke a word to me,<br/>And light did shine.<br/>My darkness You effaced,<br/>My emptiness replaced,<br/>The gospel’s light erased<br/>My history vain.<br/>',NULL,20125,1);
INSERT INTO stanza VALUES('NS218','2','Day two did come and go,<br/>But one thing I did know,<br/>Things earthly lost their glow,<br/>They’re dead to me;<br/>The atmosphere expanse,<br/>Lifted my circumstance,<br/>That life may thus advance,<br/>For growth in me.<br/>',NULL,20126,2);
INSERT INTO stanza VALUES('NS218','3','Day three the land so dry,<br/>Emerged from waters high,<br/>Grass, herbs, and trees did rise,<br/>Your life had sprung.<br/>My death You now received,<br/>As life to rise in me,<br/>Rise more ’till there’s no sea,<br/>Within my being.<br/>',NULL,20127,3);
INSERT INTO stanza VALUES('NS218','4','Day four the sun did shine,<br/>With rays of healing light,<br/>The moon was shining too,<br/>The church, my home.<br/>The saints as stars with light,<br/>Shine ’midst this darkening night,<br/>Setting my feet aright,<br/>To walk Your way.<br/>',NULL,20128,4);
INSERT INTO stanza VALUES('NS218','5','Day five the fish arrive,<br/>Against the worldly tide,<br/>Death waters did survive,<br/>With life and power;<br/>From fish to bird I soar,<br/>I’m waiting on You, Lord,<br/>Your grace to me afford,<br/>Strength for all things.<br/>',NULL,20129,5);
INSERT INTO stanza VALUES('NS218','6','Day six from air to ground,<br/>Cattle and beasts around,<br/>Then all creation found,<br/>With men like these,<br/>Through growth expressing Thee,<br/>With Your authority,<br/>I’ve reached maturity,<br/>Your purpose gained.<br/>',NULL,20130,6);
INSERT INTO stanza VALUES('NS219','1','Sometimes we’re caught in a world full of baits<br/>Tempting us to live our lives contrary to Your aim,<br/>But Your faithfulness and love and mercy<br/>Always will remain;<br/>Lord, turn us fully back to You again.<br/>',NULL,20131,1);
INSERT INTO stanza VALUES('NS219','chorus','Lord, our whole being we give to You<br/>’Cause You have bought us with Your blood<br/>So we no longer live to ourselves,<br/>But everyday our lives we live<br/>To You alone, not to our own,<br/>Your glory, Lord, will then be shown.<br/>',NULL,20132,2);
INSERT INTO stanza VALUES('NS219','2','Sometimes we lean only on ourselves,<br/>Thinking we can do things without asking for Your help,<br/>But Your Spirit in our spirit’s<br/>Working in and breaking through<br/>To free us from the “self” and back to You.<br/>',NULL,20133,3);
INSERT INTO stanza VALUES('NS220','1','Lord, keep me from this evil and perverted age;<br/>Wholly sanctify my eyes—on You to gaze.<br/>Satisfy my deepest part.<br/>O Lord, preserve my heart.<br/>',NULL,20134,1);
INSERT INTO stanza VALUES('NS220','2','Rescue me, Lord, from this dark world—it’s just display.<br/>Shine in me, and show me, Lord, You are the way.<br/>Nothing matches me but You.<br/>Only Your life will do.<br/>',NULL,20135,2);
INSERT INTO stanza VALUES('NS220','3','Lord, cause my love for You to grow in me each day.<br/>Through this love, show me the world’s passing away.<br/>Separate me unto You.<br/>O Lord, my heart renew.<br/>',NULL,20136,3);
INSERT INTO stanza VALUES('NS220','4','Don’t let me go; I’m here for You and this You know.<br/>Day by day, Your life within me has to grow.<br/>Though this world is so corrupt,<br/>I can and do love You.<br/>',NULL,20137,4);
INSERT INTO stanza VALUES('NS220','5','O Lord, become a river flowing out of me,<br/>That the world may take a drink of You and see<br/>That You are the only way,<br/>The One reality.<br/>',NULL,20138,5);
INSERT INTO stanza VALUES('NS221','1','More of our heart, dear Lord, we’d give You now;<br/>Even more ground to You, Lord, we’d allow.<br/>All that distracts us we’d despise,<br/>All that draws away our eyes—<br/>Lord, do fill our vision<br/>’Til the morning star has risen!<br/>We would count all things loss, but Jesus gain;<br/>Our inward parts cry out for You to reign.<br/>Worthy You are our heart to claim—<br/>Come, engrave on us Your name,<br/>We would love You, Jesus, more.<br/>',NULL,20139,1);
INSERT INTO stanza VALUES('NS221','2','Less we would argue, Lord, and go our way;<br/>More we would say “Amen” to what You say.<br/>Grant us a walk to You conformed,<br/>’Til our living is transformed.<br/>We adore You, Jesus—<br/>May a pure love for You seize us.<br/>Any unwillingness, Lord, quickly slay;<br/>Even by faith we open all the way—<br/>Rising to heights of love unknown,<br/>Christ our destiny alone,<br/>We would love You, Jesus, more!<br/>',NULL,20140,2);
INSERT INTO stanza VALUES('NS222','1','These are the days, my friend,<br/>Time’s drawing to an end,<br/>And we must choose,<br/>must choose whom we will serve.<br/>We will fight for the Lord<br/>And stand in one accord<br/>For the defeat of God’s arch enemy!<br/>',NULL,20141,1);
INSERT INTO stanza VALUES('NS222','2','These are the days, O saints,<br/>The heart of man, it faints<br/>For Satan’s work<br/>that’s seen throughout the land.<br/>So we must count all loss,<br/>Be one at any cost,<br/>And give our all for God’s recovery.<br/>',NULL,20142,2);
INSERT INTO stanza VALUES('NS222','3','These are the days, my friend,<br/>The Spirits moving in<br/>To raise the standard<br/>up against the foe,<br/>To show the one new man<br/>According to His plan<br/>And draw this generation to Himself.<br/>',NULL,20143,3);
INSERT INTO stanza VALUES('NS222','4','These are the latter days,<br/>Go forth and sound His praise,<br/>Proclaim to men<br/>the kingdom that shall come.<br/>The army’s moving out<br/>The enemy to rout,<br/>And Christ will gain His rightful place on earth.<br/>',NULL,20144,4);
INSERT INTO stanza VALUES('NS223','1','We are the generation<br/>The Lord has waited for.<br/>He has sought us and pursued us.<br/>When we touched Him, He renewed us.<br/>Now the time has come<br/>For all the young<br/>To be in touch with Him!<br/>',NULL,20145,1);
INSERT INTO stanza VALUES('NS223','2','God loves this generation—<br/>He chose us for His plan.<br/>We were young and disillusioned<br/>In the age of mass confusion.<br/>Now we are His choice,<br/>We all rejoice—<br/>To God we say “Amen.”<br/>',NULL,20146,2);
INSERT INTO stanza VALUES('NS223','chorus','Once we were searching,<br/>Always worrying—<br/>When would we end our search?<br/>Now we’re reborn;<br/>Our veils are torn,<br/>Since He brought us into the church!<br/>',NULL,20147,3);
INSERT INTO stanza VALUES('NS223','3','At last our search has ended;<br/>Our praises fill the air.<br/>We’re the chosen generation!<br/>Jesus loves this generation!<br/>And the time has come<br/>For all the young<br/>To be in love with Him!<br/>',NULL,20148,4);
INSERT INTO stanza VALUES('NS224','1','I’ve given up the world because<br/>I’ve found something more:<br/>He’s better than anything<br/>I’ve ever found before.<br/>Yes, I have found the Living One,<br/>Oh, how my spirit soars!<br/>I called His name, I’m not the same,<br/>I am for the Lord!<br/>',NULL,20149,1);
INSERT INTO stanza VALUES('NS224','chorus','I’m for the Lord!<br/>I’m loving Jesus!<br/>I’m for the Lord!<br/>I’m calling O Lord Jesus!<br/>',NULL,20150,2);
INSERT INTO stanza VALUES('NS224','2','I’ve given up the world because<br/>I’ve found something better:<br/>I have found the Living One<br/>And He breaks every fetter.<br/>Yes, He’s the One who set me free.<br/>Oh, how my spirit soars!<br/>I called His name, I’m not the same,<br/>I am for the Lord!<br/>',NULL,20151,3);
INSERT INTO stanza VALUES('NS224','3','And now I’m really happy,<br/>Yes I’m fully satisfied.<br/>I have found the Living One,<br/>And He lives right inside<br/>Of you and me, so come and see<br/>Now our spirits soar!<br/>We called His name, we’re not the same,<br/>We are for the Lord!<br/>',NULL,20152,4);
INSERT INTO stanza VALUES('NS224','chorus','We’re for the Lord!<br/>We’re loving Jesus!<br/>We’re for the Lord!<br/>We’re calling O Lord Jesus!<br/>',NULL,20153,5);
INSERT INTO stanza VALUES('NS225','1','Praise the Lord! The God of glory<br/>Who appeared to Abraham<br/>Has appeared to us in spirit<br/>For His purpose and His plan!<br/>God of glory, God of glory,<br/>Do appear to us today,<br/>Saturate and permeate us<br/>Till You fully have Your way.<br/>',NULL,20154,1);
INSERT INTO stanza VALUES('NS225','2','Once we were in old Chaldea,<br/>Worshipping the idols there;<br/>But the God of glory called us,<br/>Saved us all from Satan’s snare.<br/>Get out, get out, from Chaldea,<br/>From that evil foreign land.<br/>Come in, come in, to the good land,<br/>Christ, the church, the one new man.<br/>',NULL,20155,2);
INSERT INTO stanza VALUES('NS225','3','With the calling comes the promise<br/>Of the kingdom life on earth.<br/>This becomes our strength and motive<br/>To get out of all the dearth!<br/>Lord, we’re crossing every river—<br/>For this You must call us on,<br/>Till Your kingdom and expression<br/>On this earth are fully come.<br/>',NULL,20156,3);
INSERT INTO stanza VALUES('NS225','4','This is now the highest gospel<br/>To those still in Chaldee’s land—<br/>Leave the fallen situation,<br/>You’ve been chosen for God’s plan.<br/>God of glory, God of glory,<br/>Do appear to us each day,<br/>Call us out into Your building,<br/>Your desire on earth today.<br/>',NULL,20157,4);
INSERT INTO stanza VALUES('NS226','1','I love You, Lord Jesus!<br/>I love, You, Lord, Precious One!<br/>No other one compares to You!<br/>(Repeat)<br/>',NULL,20158,1);
INSERT INTO stanza VALUES('NS226','chorus','Jesus, Lord Jesus,<br/>Dear Lord, most lovely One,<br/>No one compares to You!<br/>',NULL,20159,2);
INSERT INTO stanza VALUES('NS227','1','To realize and participate<br/>In the deep and hidden things<br/>God has ordained and prepared for us<br/>Requires us not only to believe in Him<br/>But also to love Him.<br/>To fear God, to worship God,<br/>And to believe in God,<br/>That is, to receive God,<br/>Are all inadequate;<br/>To love Him is the indispensable requirement.<br/>To love Him is the indispensable requirement.<br/>',NULL,20160,1);
INSERT INTO stanza VALUES('NS228','1','Oh, who’s like our Jesus? He’s all we desire!<br/>His love draws us near—sets our spirits afire!<br/>We cannot but love Him—As one we proclaim:<br/>“Lord Jesus, we love Thee—exalt Thy dear name!”<br/>',NULL,20161,1);
INSERT INTO stanza VALUES('NS228','2','O Jesus, our Jesus, with Thee we are blest—<br/>Our Life, our Enjoyment, our Peace and our Rest:<br/>Thy name be our theme, and Thy love be our song;<br/>Thy love has inspired both our heart and our tongue!<br/>',NULL,20162,2);
INSERT INTO stanza VALUES('NS228','3','O Jesus, our Jesus, how can we express<br/>Thy dearness, so precious, and Thy loveliness?<br/>When we see Thy beauty, all else fades away—<br/>All shadows must flee at the breaking of day!<br/>',NULL,20163,3);
INSERT INTO stanza VALUES('NS228','4','We love Thee, we love Thee, we love Thee, O Lord.<br/>We love Thee, our Jesus, we love Thee, our God!<br/>We love Thee, we love Thee, and that Thou dost know;<br/>As we’re in Thy presence, love for Thee will grow!<br/>',NULL,20164,4);
INSERT INTO stanza VALUES('NS229','chorus','Lord, I love You.<br/>Thank You for opening my eyes.<br/>Lord I’ve seen who You are,<br/>And I can’t help falling in love.<br/>',NULL,20165,1);
INSERT INTO stanza VALUES('NS229','1','One day so desperate for You,<br/>Praying earnestly to You.<br/>Lord, I’m not satisfied.<br/>Show me, Lord, how lovely You are.<br/>',NULL,20166,2);
INSERT INTO stanza VALUES('NS229','2','Thank You for Your faithfulness.<br/>I have seen Thy preciousness.<br/>Now, Lord, I can’t deny<br/>Your beauty has captured my heart.<br/>',NULL,20167,3);
INSERT INTO stanza VALUES('NS229','3','Now, Lord, You’re all I want.<br/>I waste all that I have.<br/>No one compares to You.<br/>Here in love, Lord, will I remain.<br/>',NULL,20168,4);
INSERT INTO stanza VALUES('NS230','1','Simply loving everyday;<br/>Loving through a stormy way,<br/>Even when my faith is small,<br/>Loving Jesus, that is all.<br/>',NULL,20169,1);
INSERT INTO stanza VALUES('NS230','chorus','Loving as the moments fly,<br/>Loving as the days go by,<br/>Loving Him whate’er befall,<br/>Loving Jesus, that is all.<br/>',NULL,20170,2);
INSERT INTO stanza VALUES('NS230','2','Brightly doth His Spirit shine<br/>Into this poor heart of mine;<br/>While He leads I cannot fall,<br/>Loving Jesus, that is all.<br/>',NULL,20171,3);
INSERT INTO stanza VALUES('NS230','3','Singing if my way be clear,<br/>Praying if the path be drear;<br/>If in danger, for Him call,<br/>Loving Jesus, that is all.<br/>',NULL,20172,4);
INSERT INTO stanza VALUES('NS230','4','Loving Him while life shall last,<br/>Loving Him till earth is past,<br/>Till His gracious advent call,<br/>Loving Jesus, that is all.<br/>',NULL,20173,5);
INSERT INTO stanza VALUES('NS231','1','Lord Jesus, I love You.<br/>You’re my all—<br/>You’re my all in all.<br/>You gave me life indeed;<br/>You’re all I need,<br/>You’re all I need.<br/>Real peace and joy I never knew,<br/>Until in spirit I touched You, so—<br/>',NULL,20174,1);
INSERT INTO stanza VALUES('NS231','chorus','Lord, I just open up to You;<br/>I let You do what You want to do.<br/>Lord, I just give myself to You,<br/>’Cause I love You—Lord, I do.<br/>',NULL,20175,2);
INSERT INTO stanza VALUES('NS231','2','You save me all day long;<br/>Though I’m weak,<br/>You’re so strong.<br/>The flow of life and peace<br/>Within me shows the way,<br/>Hour by hour, day by day;<br/>And if through weakness I should fall,<br/>You always save me when I call, so—<br/>(Repeat Chorus)<br/>',NULL,20176,3);
INSERT INTO stanza VALUES('NS231','3','O Lord, one touch with Thee<br/>Brought life into me.<br/>And now I can’t live without You.<br/>You’re my only delight—<br/>You’ve made everything right<br/>With a love that constrains me<br/>Till I say that—<br/>(Repeat Chorus)<br/>You’re my lover—You’re my all.<br/>',NULL,20177,4);
INSERT INTO stanza VALUES('NS232','1','Jesus Lord, I just love You.<br/>You’ve attracted me, and my heart renewed.<br/>I pursue You like a dove;<br/>I belong to You, and You’re my Beloved.<br/>Everything under the sun is vanity:<br/>It’s like chasing after wind, so emptily;<br/>You have put within me, Lord, eternity...<br/>',NULL,20178,1);
INSERT INTO stanza VALUES('NS232','2','Now I rise to come away;<br/>In the cleft rock, Lord, I would ever stay.<br/>Kiss me, Lord; refresh me, too,<br/>As I gaze at You, and Your death I view.<br/>You were broken on the cross for me, dear Lord.<br/>All Your being, life and love for me was poured.<br/>Precious One, You are the One that I adore...<br/>',NULL,20179,2);
INSERT INTO stanza VALUES('NS232','3','Make me, Lord, a fragrance true,<br/>As a garden filled, with Your spices new.<br/>Transform me, Your Bride to be,<br/>For Your heart’s desire, through eternity.<br/>As Your lover in the veil, I long to be,<br/>Be conformed to Your sweet death continually,<br/>’Til Your city we become eternally.<br/>',NULL,20180,3);
INSERT INTO stanza VALUES('NS233','1','Not poquito, nor kidogo<br/>I love the Lord a whole bunch.<br/>(Un muchos!!)<br/>Nicht ein bischen, shao or choto—<br/>I love the Lord a whole bunch.<br/>Grandios and muchos<br/>Colossal un da—<br/>I love You, Lord—O so much.<br/>Not a little but a bunch.<br/>',NULL,20181,1);
INSERT INTO stanza VALUES('NS233','2','Lord, I do not have all the words<br/>To speak my love out to You.<br/>For Your love to me surpasses<br/>All words that ever I knew.<br/>All the languages, though so different<br/>They all can say the same thing—<br/>That my love for You is great.<br/>I love You, Lord—O so much!<br/>',NULL,20182,2);
INSERT INTO stanza VALUES('NS234','1','Pursue Christ,<br/>Gain Christ,<br/>Be found in Christ.<br/>Magnify Christ;<br/>This is the way to experience Christ.<br/>',NULL,20183,1);
INSERT INTO stanza VALUES('NS235','1','Do you not know that those who run,<br/>Run on a racecourse, all run,<br/>All run, but one receives the prize?<br/>Run in this way, that you may lay hold.<br/>And everyone who contends exercises<br/>Self-control in all things; those therefore,<br/>That they may receive a corruptible crown,<br/>But we receive an incorruptible.<br/>',NULL,20184,1);
INSERT INTO stanza VALUES('NS236','chorus','Lord, in these days I want to set my heart,<br/>Ever and only, always on You,<br/>That I would not defiled be,<br/>Keeping my heart so single and pure for Thee.<br/>',NULL,20185,1);
INSERT INTO stanza VALUES('NS236','1','Lord, write Your law, inscribe on our hearts,<br/>That this law of life, would of us be part,<br/>We are so hopeless, yet we hope in Him,<br/>Preparing a way for Christ to come in.<br/>',NULL,20186,2);
INSERT INTO stanza VALUES('NS236','2','Lord as the fountain You’d want us to drink,<br/>Always supplying, it’s my only link,<br/>Staying connected to this precious flow,<br/>Planting my roots here that they would grow.<br/>',NULL,20187,3);
INSERT INTO stanza VALUES('NS236','3','You are the Potter, we are the clay,<br/>Form now the church, Your expression today,<br/>In Christ there’s nothing that we may lack,<br/>As now Your Body, we’d bring You back.<br/>',NULL,20188,4);
INSERT INTO stanza VALUES('NS237','1','I beseech you brothers as a pris’ner in the Lord,<br/>To walk worthily of your calling,<br/>The calling with which you were called,<br/>With all lowliness and meekness,<br/>With long-suffering,<br/>Bearing one another in love,<br/>Being diligent to keep the oneness of the Spirit<br/>In the uniting bond of peace.<br/><br/>The calling with which you were called,<br/>With all lowliness and meekness,<br/>With long-suffering,<br/>Bearing one another in love,<br/>Being diligent to keep the oneness of the Spirit<br/>In the uniting bond of peace.<br/>',NULL,20189,1);
INSERT INTO stanza VALUES('NS237','2','One Body and one Spirit,<br/>Even as also you were called in one hope,<br/>One hope of your calling;<br/>One Lord, one faith, one baptism;<br/>One God and one Father of all,<br/>Who is over all and through all and in all.<br/><br/>One hope of your calling;<br/>One Lord, one faith, one baptism;<br/>One God and one Father of all,<br/>Who is over all and through all and in all.<br/>',NULL,20190,2);
INSERT INTO stanza VALUES('NS238','1','From my heart comes a melody<br/>Of the One who gave His life for me.<br/>How can I turn away from Thee;<br/>Lord, I have seen Thy changeless love for me.<br/>Enjoyment so full!<br/>Life’s reality!<br/>That’s what You’re to me:<br/>Lord, You have won my heart!<br/>Take my heart, take my whole life too;<br/>Lord, I can’t help giving myself to You.<br/>',NULL,20191,1);
INSERT INTO stanza VALUES('NS238','2','From the day that I first met You.<br/>How could I help falling in love with You?<br/>Emptiness turned life’s pleasures blue;<br/>No earthly love ever could see me through.<br/>’Till I turned one day<br/>Opened up my heart,<br/>Let Your love flow in<br/>And fill my deepest part.<br/>Now I know, Lord, You’re one with me;<br/>And I can’t help giving myself to Thee.<br/>Lord, I can’t help giving myself to Thee.<br/>',NULL,20192,2);
INSERT INTO stanza VALUES('NS239','chorus','Lord, take my life<br/>I give it, Lord, to You.<br/>You have opened my eyes, Lord,<br/>And turned me to You.<br/>You are my Creator, O Lord,<br/>How I love You.<br/>You are also my Savior<br/>And everything that’s true.<br/>',NULL,20193,1);
INSERT INTO stanza VALUES('NS239','1','Lord, so often I’m like Thomas<br/>Who would not receive:<br/>“Unless I see Your face, Lord, I would not believe...“<br/>But then You would appear...<br/>“My Lord and my God“<br/>Saying, Blessed are they who see not, yet believe.<br/>',NULL,20194,2);
INSERT INTO stanza VALUES('NS239','2','I have someone deep within me<br/>Welling up in me each day.<br/>Even though I have not seen Him in such an outward way—<br/>“Whom having not seen, I love,<br/>I love, oh so much.<br/>And by having His life, yes, I believe.“<br/>(Chorus)<br/>',NULL,20195,3);
INSERT INTO stanza VALUES('NS239','3','Day by day I look forward to<br/>That time I spend with You.<br/>Just as Mary poured her love out,<br/>O Lord, I would too.<br/>Grant me, Lord, a heart<br/>that’s single and true.<br/>And a daily life that’s living just by You.<br/>',NULL,20196,4);
INSERT INTO stanza VALUES('NS239','4','So when daily I see trials<br/>And tribulations sore,<br/>May I put my trust in You, Lord,<br/>“For Christ has gone before“<br/>And open to Your living Word,<br/>Receiving faith—<br/>Reach me, Lord, with Your mercy and Your grace.<br/>(Chorus)<br/>',NULL,20197,5);
INSERT INTO stanza VALUES('NS240','1','Lord, I give myself to You again today<br/>Lord, on this consecration path I choose to stay<br/>You bought me with a price<br/>My life I sacrifice<br/>Lord, I am not my own.<br/>',NULL,20198,1);
INSERT INTO stanza VALUES('NS240','2','Lord, I give myself to You again today<br/>Your mercy reached me though I was so far away<br/>You gave Yourself for me<br/>From whose earthly dreams You freed<br/>Lord, I am Yours alone.<br/>',NULL,20199,2);
INSERT INTO stanza VALUES('NS240','3','Lord, I give myself to You again today<br/>I open to You so that You may have a way<br/>To work in me that I<br/>Might serve You my whole life<br/>Lord, I love You alone.<br/>',NULL,20200,3);
INSERT INTO stanza VALUES('NS241','1','Manifest, manifest, manifest, manifest—<br/>God is manifest in us,<br/>In the church, in the church,<br/>in the church, in the church—<br/>God’s great myst’ry, the church life glorious!<br/>Vindicated in Spirit, seen by angels and men,<br/>Preached and believed in the nations,<br/>And received up into glory.<br/>',NULL,20201,1);
INSERT INTO stanza VALUES('NS242','1','Everything’s alright in the Father’s house,<br/>In the Father’s house,<br/>In the Father’s house,<br/>Everything’s alright in the Father’s house,<br/>In the Father’s house.<br/>',NULL,20202,1);
INSERT INTO stanza VALUES('NS242','2','We are all at home in the Father’s house...<br/>',NULL,20203,2);
INSERT INTO stanza VALUES('NS242','3','We have perfect peace in the Father’s house...<br/>',NULL,20204,3);
INSERT INTO stanza VALUES('NS242','4','We are loving God in the Father’s house...<br/>',NULL,20205,4);
INSERT INTO stanza VALUES('NS242','5','We smile all day long in the Father’s house...<br/>',NULL,20206,5);
INSERT INTO stanza VALUES('NS242','6','We are satisfied in the Father’s house...<br/>',NULL,20207,6);
INSERT INTO stanza VALUES('NS242','7','We love Jesus Christ in the Father’s house...<br/>',NULL,20208,7);
INSERT INTO stanza VALUES('NS242','8','Bring Your children back to the Father’s house...<br/>',NULL,20209,8);
INSERT INTO stanza VALUES('NS243','1','The Church of God—we are the church,<br/>So important to God’s great plan;<br/>Organic, full of God’s rich life,<br/>We’re born into the living church.<br/>Essence, nature of God, not man,<br/>The foundation is Christ, Himself.<br/>The glorious church the glorious church<br/>Is God expressed. Is God expressed.<br/>',NULL,20210,1);
INSERT INTO stanza VALUES('NS243','2','We need to see the House of God,<br/>The Assembly of called out ones,<br/>God’s masterpiece and His Kingdom,<br/>His counterpart; her purpose is<br/>Satisfaction and rest in love.<br/>It’s God’s desire that Christ may have<br/>A bride, a wife, a bride, a wife<br/>Eternally. Eternally.<br/>',NULL,20211,2);
INSERT INTO stanza VALUES('NS243','3','The One New Man has Christ our Lord<br/>As a Person, expressing God,<br/>Subdues Satan for God’s purpose.<br/>Body of Christ with Christ our Head,<br/>Supplying us with His riches;<br/>Many members, all functioning,<br/>Yet all are one, yet all are one<br/>With Christ as life. With Christ as life.<br/>',NULL,20212,3);
INSERT INTO stanza VALUES('NS243','4','Hallelujah! The two aspects:<br/>Universal and the local church.<br/>The local ground preserves oneness;<br/>Genuine oneness will be obtained.<br/>One fellowship and one teaching<br/>Throughout the earth, universal<br/>Body expressed, body expressed<br/>Locally. Locally.<br/>',NULL,20213,4);
INSERT INTO stanza VALUES('NS243','5','Learn the lesson from church hist’ry<br/>Of the failures we must avoid;<br/>Degradation we fight against,<br/>Recov’ring from divisive ground<br/>To the oneness of the Body;<br/>Returning to what God’s revealed.<br/>Lord build in us, Lord build in us<br/>The Kingdom life. The Kingdom life.<br/>',NULL,20214,5);
INSERT INTO stanza VALUES('NS243','6','We believers have been renewed,<br/>Must grow in life and be matured,<br/>Perfected as overcomers<br/>So that we as the builded church,<br/>The corporate Bride, will consummate<br/>All in the New Jerusalem—<br/>Fulfilling God’s, fulfilling God’s<br/>Eternal plan! Eternal plan!<br/>',NULL,20215,6);
INSERT INTO stanza VALUES('NS244','1','Oh, how we enjoy the blending,<br/>With the saints along the way,<br/>Singing, praising, and enjoying,<br/>Fill our spirits ’til we say:<br/>',NULL,20216,1);
INSERT INTO stanza VALUES('NS244','chorus','Hallelujah for the blending!<br/>It’s the way to live today.<br/>So we’re standing and proclaiming,<br/>“In the church is where we’ll stay.”<br/>',NULL,20217,2);
INSERT INTO stanza VALUES('NS244','2','We see what God is recovering<br/>What a sight it is to see!<br/>What a treasure He is building,<br/>It’s His Body corporately:<br/>',NULL,20218,3);
INSERT INTO stanza VALUES('NS244','3','We’re so happy and so thankful<br/>For this opportunity;<br/>Thank You, Lord, You’ve been so faithful<br/>To show all of this to me;<br/>',NULL,20219,4);
INSERT INTO stanza VALUES('NS245','1','How glorious is Thy church, Oh Lord—<br/>No trace of sin in her.<br/>What myst’ry this: God died as man,<br/>For, oh, He loves her so!<br/>',NULL,20220,1);
INSERT INTO stanza VALUES('NS245','chorus','Glorious, Glorious church,<br/>She is Thy dear Bride;<br/>She was built from Thine own side;<br/>She is the same as Thee.<br/>',NULL,20221,2);
INSERT INTO stanza VALUES('NS245','2','How precious is Thy Body, Lord;<br/>How costly in Thy sight.<br/>I’d ne’er bring anything of self,<br/>For she is out from Thee.<br/>',NULL,20222,3);
INSERT INTO stanza VALUES('NS245','3','How faithful is Thyself, dear Lord—<br/>Eternally the same.<br/>Though man may fail to reach Thy will,<br/>Thou shalt obtain Thy Bride.<br/>',NULL,20223,4);
INSERT INTO stanza VALUES('NS245','4','How subtle is my self, Oh Lord;<br/>Yet I wilt be transformed.<br/>Through Spirit’s work—become a stone<br/>To build up Thine own Bride.<br/>',NULL,20224,5);
INSERT INTO stanza VALUES('NS245','5','How precious is Thy Body, Lord;<br/>How costly in my sight.<br/>I would decrease, and Thee increase<br/>At any cost for her.<br/>',NULL,20225,6);
INSERT INTO stanza VALUES('NS246','1','Though I love You, Lord,<br/>My life seems all deformed.<br/>I give my life to You—<br/>Then drift away.<br/>Lord, may I ask You that You’d draw me yet again,<br/>And keep me running after You.<br/>',NULL,20226,1);
INSERT INTO stanza VALUES('NS246','chorus','Lord, I’ve seen Your purpose.<br/>Your heart’s unveiled to me.<br/>Now I’d just like to see You gain me fully.<br/>Though You I often limit<br/>And fail by compromise,<br/>Keep me in the index of Your eyes.<br/>',NULL,20227,2);
INSERT INTO stanza VALUES('NS246','2','Lord, I want Your best.<br/>I want Your full blessing.<br/>I don’t want any less,<br/>Though good it be.<br/>Have mercy, Lord, to push, to pull, lay hold of me.<br/>Keep me still running toward the prize.<br/>',NULL,20228,3);
INSERT INTO stanza VALUES('NS246','3','Mold me, shape me, Lord.<br/>Be my reality.<br/>Even break my heart,<br/>If it has to be.<br/>I’m desperate, Lord, that You would have Your way with me.<br/>Others could touch You then through me.<br/>',NULL,20229,4);
INSERT INTO stanza VALUES('NS246','4','Set my heart aflame.<br/>Don’t let me stay the same.<br/>Don’t let things remain<br/>Which now grieve You.<br/>My life I give to You and all I’ve claimed as mine.<br/>May I just hold, Lord, unto You.<br/>',NULL,20230,5);
INSERT INTO stanza VALUES('NS247','1','Lord, You promised Your return.<br/>Make us virgins who are wise.<br/>Spread in all our being<br/>That we could be prepared<br/>For Your coming.<br/>Our dear Bridegroom,<br/>Come soon.<br/>',NULL,20231,1);
INSERT INTO stanza VALUES('NS247','2','Lord, You promised Your return.<br/>Make us lovers who are pure.<br/>Keep our heart for You;<br/>We would pursue You<br/>Together.<br/>Our Beloved,<br/>Come soon.<br/>',NULL,20232,2);
INSERT INTO stanza VALUES('NS247','3','Lord, You promised Your return.<br/>Make us those who match Your heart.<br/>Capture every part<br/>Until we only live<br/>For Your coming.<br/>Precious Bridegroom,<br/>Come soon.<br/>',NULL,20233,3);
INSERT INTO stanza VALUES('NS248','1','God’s complete salvation<br/>Is based upon His righteousness and through our faith.<br/>By the two divine transfers:<br/>Out of Adam into Christ<br/>And out of the flesh into the Spirit.<br/>In the one spiritual union of the<br/>Spirit of Life with our spirit<br/>Forming a mingled spirit.<br/>For us to reign in life by the abundance of grace<br/>and of the gift of righteousness.<br/>For us to reign in life by the abundance of grace<br/>and of the gift of righteousness.<br/>',NULL,20234,1);
INSERT INTO stanza VALUES('NS249','1','God’s intention is for Christ<br/>To be wrought into His chosen people<br/>That they may become the sons of God<br/>For His corporate expression.<br/>',NULL,20235,1);
INSERT INTO stanza VALUES('NS249','2','We need to be rescued<br/>Out of the present evil age<br/>By the revelation of God’s Son in us.<br/>',NULL,20236,2);
INSERT INTO stanza VALUES('NS249','3','To live the Christian life<br/>Is to live the processed Triune God<br/>As the consummated Spirit.<br/>',NULL,20237,3);
INSERT INTO stanza VALUES('NS249','4','God’s goal is the divine sonship<br/>For His corporate expression<br/>As the household of the faith,<br/>The new creation, and the Israel of God;<br/>As the household of the faith,<br/>The new creation, and the Israel of God.<br/>',NULL,20238,4);
INSERT INTO stanza VALUES('NS250','1','The Christian life is a life,<br/>A life of living Christ<br/>For the constitution and building up<br/>Of the Body of Christ;<br/>The Christian life is a life of living Christ.<br/>',NULL,20239,1);
INSERT INTO stanza VALUES('NS250','2','We need to work out our own salvation<br/>By obeying the inner operating God.<br/>We need to be conformed to the mold of Christ’s death<br/>By the power of His resurrection that we may attain<br/>To the out resurrection from the dead.<br/>',NULL,20240,2);
INSERT INTO stanza VALUES('NS250','3','The Christian life is a life,<br/>A life full of Christ<br/>As forbearance but without anxiety;<br/>The Christian life is a life full of Christ.<br/>',NULL,20241,3);
INSERT INTO stanza VALUES('NS251','1','The new covenant ministry—a ministry of God—<br/>is the ministry of the Spirit who gives life (who gives life)<br/>and of righteousness as the expression of God.<br/>',NULL,20242,1);
INSERT INTO stanza VALUES('NS251','2','The new covenant ministers are persons<br/>Whose hearts have turned to the Lord,<br/>Who are enjoying the Lord as the Spirit,<br/>And who are being transformed<br/>into the image of the Lord<br/>by beholding and reflecting Him.<br/>',NULL,20243,2);
INSERT INTO stanza VALUES('NS251','3','The new covenant ministers are ambassadors of Christ<br/>Carrying out the ministry of reconciliation<br/>To bring us into God and to make us one with God.<br/>',NULL,20244,3);
INSERT INTO stanza VALUES('NS251','4','The new covenant ministers’ living<br/>Is a living of grace,<br/>The experience of grace,<br/>Which is the Divine Trinity<br/>Transmitted into us for our enjoyment.<br/>',NULL,20245,4);
INSERT INTO stanza VALUES('NS252','1','God has called us into the fellowship of His Son,<br/>That we may partake of Christ and enjoy Him<br/>As our unique center and as our God-given portion.<br/>God has called us into the fellowship of His Son.<br/>',NULL,20246,1);
INSERT INTO stanza VALUES('NS252','2','The enjoyment of the crucified Christ<br/>as the life-giving Spirit in our spirit,<br/>Solves all the problems in the church,<br/>And issues in the growth in life,<br/>And issues in the growth in life,<br/>For the building up of the church.<br/>For the building up of the church.<br/>',NULL,20247,2);
INSERT INTO stanza VALUES('NS252','3','The essence of the New Testament is the two spirits—<br/>The divine Spirit and the human spirit—<br/>Mingled together as one spirit.<br/>The essence of the New Testament is the two spirits.<br/>',NULL,20248,3);
INSERT INTO stanza VALUES('NS252','4','Love is the most excellent way<br/>And prophesying is the excelling gift<br/>For the building up of the church,<br/>For the building up of the church.<br/>',NULL,20249,4);
INSERT INTO stanza VALUES('NS253','1','Always rejoice;<br/>Unceasingly pray;<br/>In everything give thanks;<br/>For this is the will of God<br/>In Christ Jesus for you.<br/>',NULL,20250,1);
INSERT INTO stanza VALUES('NS254','1','How lovely are Thy dwelling places;<br/>My soul longs for the courts of the Lord.<br/>My heart and my flesh,<br/>They sing for joy to the living God;<br/>You are my King and my God.<br/>',NULL,20251,1);
INSERT INTO stanza VALUES('NS255','1','Brothers, I do not account of myself to have laid hold;<br/>But one thing—<br/>Forgetting the things which are behind<br/>And stretching forward to what is before,<br/>I pursue toward the goal<br/>For the prize of the high calling<br/>The high calling of God in Christ Jesus.<br/>',NULL,20252,1);
INSERT INTO stanza VALUES('NS256','1','Thou art worthy, Thou art worthy,<br/>Thou art worthy, O Lord.<br/>Thou art worthy to receive glory,<br/>Glory and honor and power.<br/>For Thou hast created, hast all things created,<br/>For Thou hast created all things.<br/>And for Thy pleasure they are created;<br/>Thou art worthy, O Lord.<br/>',NULL,20253,1);
INSERT INTO stanza VALUES('NS257','1','The church is the house of the living God;<br/>The church is the pillar and base of the truth.<br/>And great is the myst’ry of godliness;<br/>That God was manifested in the flesh.<br/>',NULL,20254,1);
INSERT INTO stanza VALUES('NS258','1','For unto us a child is born,<br/>Unto us a son is given;<br/>And the government shall be upon<br/>His shoulder;<br/>And His name shall be called Wonderful,<br/>Counselor, the mighty God,<br/>The everlasting Father,<br/>And the Prince of Peace is He.<br/>',NULL,20255,1);
INSERT INTO stanza VALUES('NS259','1','I will enter His gates with thanksgiving in my heart;<br/>I will enter His courts with praise.<br/>I will say this is the day that the Lord has made.<br/>I will rejoice for He has made me glad.<br/>He has made me glad, He has made me glad,<br/>I will rejoice for He has made me glad.<br/>He has made me glad, He has made me glad,<br/>I will rejoice for He has made me glad.<br/>',NULL,20256,1);
INSERT INTO stanza VALUES('NS260','1','Abraham is the father of faith to all,<br/>He was counted as righteous by heeding God’s call.<br/>Did you know all your works never justify?<br/>Believe! You are justified by faith in Him.<br/>',NULL,20257,1);
INSERT INTO stanza VALUES('NS260','2','I believe, He gives life to the dead;<br/>I believe, He creates righteous men;<br/>All your works never justify the sins you’ve done.<br/>Believe! He creates His righteousness within.<br/>',NULL,20258,2);
INSERT INTO stanza VALUES('NS261','1','Seek the Lord while He may be found,<br/>Call upon Him while He is near:<br/>Let the wicked forsake his way,<br/>And the unrighteous man his thoughts:<br/>And let him return to the Lord,<br/>Unto our God,<br/>And He will abundantly pardon,<br/>He will abundantly pardon you—<br/>Return to the Lord.<br/>',NULL,20259,1);
INSERT INTO stanza VALUES('NS262','1','Come bless the Lord, (Come bless the Lord,)<br/>All ye servants of the Lord, (All ye servants of the Lord,)<br/>Who stand by night, (Who stand by night,)<br/>In the house of the Lord. (In the house of the Lord.)<br/>Lift up your hands, (Lift up your hands,)<br/>In the Holy Place, (In the Holy Place,)<br/>And bless the Lord. (And bless the Lord.)<br/>And bless the Lord. (And bless the Lord.)<br/>',NULL,20260,1);
INSERT INTO stanza VALUES('NS263','1','It’s a good thing to give thanks unto the Lord<br/>And to sing praises unto our God.<br/>It’s a good thing to give thanks unto the Lord<br/>And to sing praises unto our God.<br/>To show forth Thy lovingkindness<br/>In the morning and every night.<br/>It’s a good thing to give thanks unto the Lord.<br/>To show forth Thy lovingkindness<br/>In the morning and every night.<br/>It’s a good thing to give thanks unto the Lord.<br/>',NULL,20261,1);
INSERT INTO stanza VALUES('NS264','1','Lord, I am continually with Thee:<br/>Thou hast holden me by my right hand,<br/>Thou shalt guide me—<br/>Thou shalt guide me with Thy counsel,<br/>And afterward receive me—<br/>Receive me to glory.<br/>',NULL,20262,1);
INSERT INTO stanza VALUES('NS264','2','Whom have I in heaven but Thee?<br/>And there is none upon the earth<br/>That I desire beside Thee.<br/>My flesh and my heart faileth;<br/>But God is the strength of my heart,<br/>And my portion forever.<br/>',NULL,20263,2);
INSERT INTO stanza VALUES('NS265','1','My Beloved is mine and I am His,<br/>His banner over me is love;<br/>My Beloved is mine and I am His,<br/>His banner over me is love;<br/>My Beloved is mine and I am His,<br/>His banner over me is love;<br/>His banner over me is love.<br/>',NULL,20264,1);
INSERT INTO stanza VALUES('NS265','2','He brought me to His banqueting table...<br/>',NULL,20265,2);
INSERT INTO stanza VALUES('NS265','3','He lifted me up into heavenly places...<br/>',NULL,20266,3);
INSERT INTO stanza VALUES('NS265','4','My Beloved is mine and I am His...<br/>',NULL,20267,4);
INSERT INTO stanza VALUES('NS266','1','I will sing of the mercies of the Lord forever,<br/>I will sing, I will sing;<br/>What a mercy that I am in the church forever;<br/>I will sing of the mercies of the Lord.<br/>',NULL,20268,1);
INSERT INTO stanza VALUES('NS266','chorus','With my mouth will I make known<br/>Thy faithfulness, Thy faithfulness,<br/>With my mouth will I make known<br/>Thy faithfulness to all generations.<br/>',NULL,20269,2);
INSERT INTO stanza VALUES('NS266','2','I will sing of the mercies of the Lord forever,<br/>I will sing, I will sing;<br/>What a mercy that I am in the church forever;<br/>I will sing of the mercies of the Lord.<br/>(Do not repeat chorus)<br/>',NULL,20270,3);
INSERT INTO stanza VALUES('NS267','1','Now on the last day, (Now on the last day,)<br/>The great day, (The great day,)<br/>The day of the feast, (The day of the feast,)<br/>The day of the feast, (The day of the feast,)<br/>Jesus stood (Jesus stood)<br/>And cried out (And cried out)<br/>If anyone thirsts<br/>let him come to Me...<br/>If anyone thirsts, (If anyone thirsts,)<br/>Let him come to Me (Let him come to Me)<br/>And drink, and drink, and drink.<br/>',NULL,20271,1);
INSERT INTO stanza VALUES('NS268','1','Search me, O God, and know my heart;<br/>Try me and know my thoughts;<br/>And see if there be any wicked way in me;<br/>Lead me in the way, lead me in the way,<br/>Lead me in the way everlasting.<br/>',NULL,20272,1);
INSERT INTO stanza VALUES('NS268','2','You have searched me;<br/>You have known me;<br/>My downsitting, my uprising;<br/>You understand my thoughts from afar;<br/>You know all my ways,<br/>You know all my ways.<br/>(Two parts can be sung simultaneously)<br/>',NULL,20273,2);
INSERT INTO stanza VALUES('NS269','1','He’s my Lord, He’s my Lord,<br/>He has risen from the dead and<br/>He’s my Lord!<br/>Every knee shall bow,<br/>Every tongue confess,<br/>That Jesus Christ is Lord.<br/>',NULL,20274,1);
INSERT INTO stanza VALUES('NS270','1','The Lord is the portion of my inheritance,<br/>And He is my cup.<br/>The Lord is the portion of my inheritance,<br/>And He is my cup.<br/>',NULL,20275,1);
INSERT INTO stanza VALUES('NS270','chorus','Thou wilt show me the path of life;<br/>Thy presence is fullness of joy.<br/>At Thy right hand there are pleasures<br/>Forevermore.<br/>',NULL,20276,2);
INSERT INTO stanza VALUES('NS270','2','For I have set Jesus forever before me:<br/>He’s at my right hand.<br/>For I have set Jesus forever before me:<br/>He’s at my right hand.<br/>',NULL,20277,3);
INSERT INTO stanza VALUES('NS270','3','Therefore is my heart glad, My spirit rejoiceth,<br/>My flesh rests in hope.<br/>Therefore is my heart glad, My spirit rejoiceth,<br/>My flesh rests in hope.<br/>',NULL,20278,4);
INSERT INTO stanza VALUES('NS271','1','Always rejoice,<br/>Unceasingly pray,<br/>In everything give thanks.<br/>(repeat)<br/>',NULL,20279,1);
INSERT INTO stanza VALUES('NS271','2','For this is the will of God in Christ Jesus,<br/>The will of God in Christ for you.<br/>Therefore always rejoice, unceasingly pray,<br/>In everything give thanks.<br/>',NULL,20280,2);
INSERT INTO stanza VALUES('NS271','3','Do not quench the Spirit,<br/>Do not despise prophecies,<br/>Approve all things,<br/>Hold fast to what is good,<br/>Abstain from every kind of evil.<br/>(Repeat 1st and 2nd stanzas)<br/>',NULL,20281,3);
INSERT INTO stanza VALUES('NS272','chorus','The mighty God, even the Lord,<br/>The mighty God, even the Lord,<br/>Hath spoken, and called the earth<br/>From the rising of the sun<br/>Unto the going down thereof.<br/>',NULL,20282,1);
INSERT INTO stanza VALUES('NS272','1','Out of Zion,<br/>The perfection of beauty, God hath shined.<br/>Out of Zion,<br/>The perfection of beauty, God hath shined.<br/>',NULL,20283,2);
INSERT INTO stanza VALUES('NS272','2','Our God shall come,<br/>He shall come and shall not keep silence;<br/>He shall call<br/>To the heaven above and to the earth.<br/>',NULL,20284,3);
INSERT INTO stanza VALUES('NS272','3','Gather my saints<br/>Gather my saints together unto me.<br/>And the heavens<br/>Shall declare His righteousness. Selah.<br/>',NULL,20285,4);
INSERT INTO stanza VALUES('NS273','1','But verily God hath heard me;<br/>He hath attended to the voice of my prayer.<br/>Blessed be God, Who hath not turned away<br/>My prayer, nor His mercy from me.<br/>',NULL,20286,1);
INSERT INTO stanza VALUES('NS274','chorus','Lord, Thou has been our dwelling place in all generations.<br/>Before the mountains were brought forth,<br/>Or ever Thou has formed the earth and the world,<br/>Even from eternity to eternity,<br/>Thou art God.<br/>',NULL,20287,1);
INSERT INTO stanza VALUES('NS274','1','For a thousand years in Thy sight are but yesterday,<br/>When it is past as a watch in the night.<br/>So teach us to number our days,<br/>That we may apply our hearts unto wisdom.<br/>',NULL,20288,2);
INSERT INTO stanza VALUES('NS274','2','O satisfy us early with Thy mercy,<br/>That we may rejoice and be glad all our days.<br/>Make us glad according to the days,<br/>And the years wherein we have seen evil.<br/>',NULL,20289,3);
INSERT INTO stanza VALUES('NS274','3','Let Thy work appear unto Thy servants,<br/>And Thy glory unto their children.<br/>And let the beauty of the Lord,<br/>The beauty of the Lord, our God be upon us.<br/>(Repeat chorus as finale)<br/>',NULL,20290,4);
INSERT INTO stanza VALUES('NS275','1','O come let us sing unto the Lord;<br/>Let us make a joyful noise<br/>To the rock of our salvation.<br/>O come let us sing unto the Lord;<br/>Let us make a joyful noise<br/>To the rock of our salvation.<br/>',NULL,20291,1);
INSERT INTO stanza VALUES('NS275','chorus','Let us come before His presence<br/>With thanksgiving,<br/>And make a joyful noise unto Him with psalms.<br/>For the Lord is a great God,<br/>And a great King above all gods.<br/>',NULL,20292,2);
INSERT INTO stanza VALUES('NS275','2','In His hand are the deep places of the earth.<br/>The strength of the hills is His also,<br/>The sea is His, and He made it,<br/>And His hands formed the dry land,<br/>And His hands formed the dry land.<br/>',NULL,20293,3);
INSERT INTO stanza VALUES('NS275','3','O come, let us worship and bow down;<br/>Let us kneel before the Lord, our Maker.<br/>For He is our God, and we are<br/>The people of His pasture,<br/>And the sheep of His hand.<br/>',NULL,20294,4);
INSERT INTO stanza VALUES('NS276','1','Rise up, my love, my beautiful one,<br/>And come away, for behold, the winter is past,<br/>The rain is over and gone.<br/>Flow’rs appear on the earth,<br/>The time of singing has come,<br/>And the voice of the turtle dove<br/>Is heard in our land.<br/>My beloved is mine,<br/>And I am His,<br/>He who feeds His flocks among the lilies.<br/>’Til the day breaks,<br/>And the shadows flee away,<br/>Come my beloved,<br/>Come my beloved!<br/>Rise up, my love, my beautiful one<br/>And come away, for behold, the winter is past,<br/>The rain is over and gone.<br/>',NULL,20295,1);
INSERT INTO stanza VALUES('NS277','1','Unto Thee, O Lord, do I lift up my soul,<br/>Unto Thee, O Lord, do I lift up my soul.<br/>',NULL,20296,1);
INSERT INTO stanza VALUES('NS277','chorus','Oh my God, I trust in Thee,<br/>Let me not be ashamed,<br/>Let not mine enemies triumph over me.<br/>',NULL,20297,2);
INSERT INTO stanza VALUES('NS277','2','Yea, let none that wait on Thee be ashamed,<br/>Yea, let none that wait on Thee be ashamed<br/>',NULL,20298,3);
INSERT INTO stanza VALUES('NS277','3','Show me Thy ways, teach me Thy paths,<br/>Show me Thy ways, teach me Thy paths<br/>',NULL,20299,4);
INSERT INTO stanza VALUES('NS277','4','Remember not the sins of my youth,<br/>Remember not the sins of my youth<br/>',NULL,20300,5);
INSERT INTO stanza VALUES('NS277','5','All the paths of the Lord are mercy and truth,<br/>All the paths of the Lord are mercy and truth<br/>',NULL,20301,6);
INSERT INTO stanza VALUES('NS277','6','What man is he that feareth the Lord?<br/>What man is he that feareth the Lord?<br/>',NULL,20302,7);
INSERT INTO stanza VALUES('NS277','7','The secret of the Lord is with them that fear Him,<br/>The secret of the Lord is with them that fear Him<br/>',NULL,20303,8);
INSERT INTO stanza VALUES('NS277','8','Turn Thee unto me and have mercy upon me,<br/>Turn Thee unto me and have mercy upon me<br/>',NULL,20304,9);
INSERT INTO stanza VALUES('NS277','9','O keep my soul and deliver me,<br/>O keep my soul and deliver me<br/>',NULL,20305,10);
INSERT INTO stanza VALUES('NS277','10','Let integrity and uprightness preserve me,<br/>Let integrity and uprightness preserve me<br/>',NULL,20306,11);
INSERT INTO stanza VALUES('NS277','11','Redeem Israel, O God, out of all his troubles,<br/>Redeem Israel, O God, out of all his troubles<br/>',NULL,20307,12);
INSERT INTO stanza VALUES('NS278','1','We give thanks to Thee, O Lord,<br/>We give thanks.<br/>We give thanks to Thee, O Lord,<br/>We give thanks.<br/>For Thy name is near;<br/>Thy wondrous works men declare—<br/>We give thanks to Thee O Lord,<br/>We give thanks.<br/>',NULL,20308,1);
INSERT INTO stanza VALUES('NS278','2','For Thou, Lord, art high—<br/>Above all the earth.<br/>Thou art exalted<br/>Far above all gods.<br/>For Thou, Lord, art high—<br/>Above all the earth.<br/>Thou art exalted<br/>Far above all gods.<br/>',NULL,20309,2);
INSERT INTO stanza VALUES('NS278','3','We exalt Thee; we exalt Thee;<br/>We exalt Thee, O Lord!<br/>We exalt Thee; we exalt Thee;<br/>We exalt Thee, O Lord!<br/>',NULL,20310,3);
INSERT INTO stanza VALUES('NS280','1','Lord, make me to know mine end,<br/>And the measure of my days, what it is,<br/>That I may know how frail I am,<br/>How frail I am.<br/>',NULL,20311,1);
INSERT INTO stanza VALUES('NS280','2','Behold, Thou hast made my days as an handbreadth;<br/>And mine age is as nothing before Thee;<br/>Verily every man at his best state,<br/>Is altogether vanity. Selah.<br/>',NULL,20312,2);
INSERT INTO stanza VALUES('NS280','3','Surely every man walketh in a vain show;<br/>Surely they are disquieted in vain;<br/>He heapeth up riches, and knoweth not<br/>Who shall gather them.<br/>',NULL,20313,3);
INSERT INTO stanza VALUES('NS280','4','And now, Lord, what wait I for?<br/>My hope is in Thee.<br/>Now Lord, what wait I for?<br/>My hope is in Thee.<br/>My hope is in Thee.<br/>(repeat stanzas 3 and 4)<br/>',NULL,20314,4);
INSERT INTO stanza VALUES('NS281','1','The law of the Lord is perfect,<br/>Converting the soul;<br/>The testimony of the Lord is sure,<br/>Making wise the simple.<br/>',NULL,20315,1);
INSERT INTO stanza VALUES('NS281','chorus','More to be desired are they than gold.<br/>Yea, than much fine gold:<br/>Sweeter also than honey<br/>And the honeycomb.<br/>',NULL,20316,2);
INSERT INTO stanza VALUES('NS281','2','The statues of the Lord are right,<br/>Rejoicing the heart:<br/>The commandment of the Lord is pure,<br/>Enlightening the eyes.<br/>',NULL,20317,3);
INSERT INTO stanza VALUES('NS281','3','The fear of the Lord is clean,<br/>Enduring forever;<br/>The judgments of the Lord are true<br/>And righteous altogether.<br/>',NULL,20318,4);
INSERT INTO stanza VALUES('NS281','4','Let the words of my mouth<br/>And the meditation of my heart,<br/>Be acceptable in Thy sight, O Lord,<br/>My strength, and my redeemer.<br/>',NULL,20319,5);
INSERT INTO stanza VALUES('NS281','chorus','Moreover by them is Thy servant warned:<br/>Is Thy servant warned:<br/>And in keeping of them there is<br/>Great reward.<br/>',NULL,20320,6);
INSERT INTO stanza VALUES('NS282','1','The Lord is my light and salvation;<br/>Whom shall I fear?<br/>The Lord is the strength of my life;<br/>Of whom shall I be afraid?<br/>',NULL,20321,1);
INSERT INTO stanza VALUES('NS282','2','One thing have I desired of the Lord,<br/>That will I seek;<br/>That I may dwell in the house of the Lord<br/>All the days of my life,<br/>To behold the beauty of the Lord,<br/>And to inquire in His temple.<br/>',NULL,20322,2);
INSERT INTO stanza VALUES('NS282','3','Hear, O Lord, when I cry with my voice;<br/>Have mercy also upon me, and answer me.<br/>When thou saidst, seek ye my face;<br/>My heart said unto thee,<br/>Thy face, O Lord, will I seek.<br/>',NULL,20323,3);
INSERT INTO stanza VALUES('NS282','4','Wait on the Lord;<br/>Be of good courage,<br/>And He shall strengthen thine heart;<br/>Wait, I say on the Lord.<br/>Wait, I say on the Lord.<br/>',NULL,20324,4);
INSERT INTO stanza VALUES('NS283','chorus','I am crucified with Christ<br/>And it is no longer I who liveth,<br/>But it is Christ who lives in me;<br/>And the life which I now live<br/>In the flesh, I live in faith—<br/>The faith in the Son of God<br/>Who loved and gave Himself up for me.<br/>',NULL,20325,1);
INSERT INTO stanza VALUES('NS283','1','And now I’m walking by the Spirit<br/>Step by step, day by day,<br/>O Lord, I love You.<br/>You’re the precious One to me.<br/>As I do this and that<br/>Lord, remind me where You’re at;<br/>You’re in my spirit,<br/>Dispensing grace to me.<br/>',NULL,20326,2);
INSERT INTO stanza VALUES('NS283','2','And now I’m walking by the Spirit,<br/>Marching on toward the goal.<br/>O Lord, Your purpose<br/>Means everything to me.<br/>All self-love I lay aside<br/>For the churches, for Your Bride,<br/>For the fulfillment<br/>Of Your economy.<br/>',NULL,20327,3);
INSERT INTO stanza VALUES('NS284','1','Having been regenerated<br/>Not of corruptible seed but of incorruptible.<br/>Through the living and abiding word of God;<br/>Through the living and abiding word of God.<br/>',NULL,20328,1);
INSERT INTO stanza VALUES('NS284','2','As newborn babes long for the<br/>Guileless milk of the word<br/>That by it you may grow unto<br/>Salvation...<br/>(Repeat stanza 1)<br/>',NULL,20329,2);
INSERT INTO stanza VALUES('NS285','1','As we become the same as Christ<br/>In life, nature, expression, and function,<br/>We are qualified to work with Him<br/>For His Body.<br/>',NULL,20330,1);
INSERT INTO stanza VALUES('NS285','2','As we trust in the Lord helplessly,<br/>Depend on Him as our love and strength,<br/>And listen to His speaking,<br/>Our hope is to be raptured<br/>Through the redemption of our body.<br/>',NULL,20331,2);
INSERT INTO stanza VALUES('NS285','chorus','And our prayer is—<br/>“Come, Lord Jesus!“<br/>And our prayer is—<br/>“Come, Lord Jesus!“<br/>“Come, Lord Jesus!<br/>Lord Jesus, come!”<br/>',NULL,20332,3);
INSERT INTO stanza VALUES('NS286','1','We have a Father<br/>Whose heart is full of love toward us.<br/>His heart is so great<br/>And His love is so unlimited.<br/>Even when we sin,<br/>We can always come back to Him;<br/>This is our Father’s great love toward us.<br/>We just need to repent,<br/>In His loving arms we were meant;<br/>This is our Father’s great love toward us.<br/>',NULL,20333,1);
INSERT INTO stanza VALUES('NS287','1','There are times in my life<br/>When my heart is embittered.<br/>There are questions unanswered,<br/>Yet, You’re drawing me<br/>',NULL,20334,1);
INSERT INTO stanza VALUES('NS287','chorus','To enter<br/>Into Your blessed sanctuary<br/>And turning my eyes heavenward,<br/>The questions of constant inquiry<br/>Are changed to these words,<br/>',NULL,20335,2);
INSERT INTO stanza VALUES('NS287','2','“Whom do I have in heaven<br/>But You, dear Jehovah.<br/>My flesh and my heart<br/>Constantly fail,<br/>',NULL,20336,3);
INSERT INTO stanza VALUES('NS287','chorus','But God’s still<br/>The strength of my heart and my portion;<br/>To Him forever I’ll draw near.<br/>I’ve made Jehovah my sweet refuge.<br/>So now throughout the years<br/>',NULL,20337,4);
INSERT INTO stanza VALUES('NS287','3','Turn my view to see You,<br/>How I need to see Jesus!!<br/>Though I don’t understand<br/>The ways that You take;<br/>',NULL,20338,5);
INSERT INTO stanza VALUES('NS287','chorus','Lord, make me<br/>A babe and suckling always praising.<br/>Enjoying Your worth day by day.<br/>Let each experience constitute me<br/>So Your life I’ll display<br/>In every way.<br/>',NULL,20339,6);
INSERT INTO stanza VALUES('NS288','1','Lord, keep my heart open and soft toward You.<br/>Lord, draw my eyes to see nothing else but You.<br/>',NULL,20340,1);
INSERT INTO stanza VALUES('NS288','2','Whatever may happen,<br/>I know You want to gain my heart.<br/>Though I may not understand,<br/>Just keep dispensing into my every part.<br/>',NULL,20341,2);
INSERT INTO stanza VALUES('NS288','3','Make me a believer<br/>By looking at You.<br/>Standing on Your Word,<br/>Faithful and true.<br/>',NULL,20342,3);
INSERT INTO stanza VALUES('NS289','1','But the God of all grace,<br/>He who has called you into His eternal glory<br/>In Christ Jesus,<br/>After you have suffered a little while,<br/>Will Himself perfect, establish, strengthen, and ground you.<br/>',NULL,20343,1);
INSERT INTO stanza VALUES('NS289','2','To Him be the glory and the might forever and ever.<br/>Amen.<br/>',NULL,20344,2);
INSERT INTO stanza VALUES('NS290','1','Lord, Your beauty and love have drawn me,<br/>To pursue after You speedily.<br/>In Your chambers I am brought,<br/>And nourished here by Thee.<br/>',NULL,20345,1);
INSERT INTO stanza VALUES('NS290','chorus','My Belov’d, I belong to You.<br/>O my Love, You’re so beautiful.<br/>We’re the same in life and in nature,<br/>In love ever insep’rable.<br/>',NULL,20346,2);
INSERT INTO stanza VALUES('NS290','2','By Your nature is mine sanctified,<br/>And my beauty’s from Your life divine.<br/>I’m renewed, submissive, sweet,<br/>With Thee, with hind’s feet leap.<br/>',NULL,20347,3);
INSERT INTO stanza VALUES('NS290','3','As a dove, You alone do I see;<br/>As a lily, I’m trusting in Thee.<br/>I’m transformed and built by Thee<br/>Your rest and joy to be.<br/>',NULL,20348,4);
INSERT INTO stanza VALUES('NS290','4','In the fields let me follow You, Lord,<br/>All my days work, in loving accord.<br/>Be matured, Your Queen, Your Bride,<br/>Then raptured, glorified.<br/>',NULL,20349,5);
INSERT INTO stanza VALUES('NS290','chorus','O set me a seal on Thy heart,<br/>Your love strong as death doth abound.<br/>King, Belov’d, for You I am longing,<br/>Come quickly upon Spice’s Mount!<br/>',NULL,20350,6);
INSERT INTO stanza VALUES('NS291','1','If God leads you to walk<br/>A way that you know,<br/>It will not benefit you as much as<br/>If He would lead you to take the way<br/>That you do not know.<br/>This forces you to have<br/>Hundreds and thousands of<br/>Conversations with Him,<br/>Resulting in a journey that is an<br/>Everlasting memorial<br/>Between you and Him.<br/>',NULL,20351,1);
INSERT INTO stanza VALUES('NS292','1','Though the world may promise me more,<br/>I’m just made to be filled with the Lord.<br/>Nor it’s life worth living a day,<br/>For the things that will soon pass away.<br/>Doesn’t matter how rich or successful I’d be,<br/>Or how many pleasures be offered to me.<br/>There’s nothing that compares to my destiny—<br/>To be thoroughly filled with the Lord.<br/>',NULL,20352,1);
INSERT INTO stanza VALUES('NS292','2','Now although I’m still kind of small,<br/>And the future is in front of me.<br/>In my heart I’ve heard the Lord’s call,<br/>Just to follow Him absolutely.<br/>Though the path may be holding<br/>Much joy or much pain,<br/>What matters is that more of Him I would gain,<br/>Regardless what happens,<br/>I never would change.<br/>’Cause I’m made to be filled with the Lord.<br/>Yes, I’m made to be filled with the Lord.<br/>',NULL,20353,2);
INSERT INTO stanza VALUES('NS293','chorus','Did you know that I’m a God-man?<br/>A three-part man mingled with the Triune God,<br/>And I have a spirit<br/>Where the enemy has no way, no hope, no ground...<br/>I am a God-man!<br/>[I am a God-man] (spoken)<br/>',NULL,20354,1);
INSERT INTO stanza VALUES('NS293','1','The Lord lives inside of Me,<br/>And He’s using my spirit as a beachhead<br/>To spread Himself into every part<br/>Of my mind, emotion, and will.<br/>He sowed Himself as the seed<br/>Into my innermost part—<br/>And the kingdom is here,<br/>Today, now, inside of me<br/>And my heart is now His home!<br/>',NULL,20355,2);
INSERT INTO stanza VALUES('NS293','2','Every time I say “Amen” to His Spirit<br/>And walk by my spirit,<br/>The kingdom seed grows and develops<br/>Deep inside of me.<br/>On the outside, it may seem that there’s<br/>No change in me—<br/>But I’m not the same,<br/>’Cause as the seed grows in me,<br/>Inside I’m becoming God!<br/>',NULL,20356,3);
INSERT INTO stanza VALUES('NS294','chorus','Jesus Christ You are the Man-Savior<br/>Expressing God;<br/>Beautifully, sweetly, and pleasantly.<br/>',NULL,20357,1);
INSERT INTO stanza VALUES('NS294','1','Jesus Christ, the genuine, complete,<br/>Moral, perfect Man revealing God;<br/>In His saving grace to fallen man,<br/>In the Jubilee of grace.<br/>',NULL,20358,2);
INSERT INTO stanza VALUES('NS294','chorus','Jesus Christ You are the God-Man—<br/>The reality,<br/>The reality of the Jubilee.<br/>',NULL,20359,3);
INSERT INTO stanza VALUES('NS294','2','Tell me all about the Shepherd Who<br/>Left the ninety-nine to find the lost sheep;<br/>How You came to earth to search for me,<br/>And came rejoicing when You found me.<br/>(Repeat Chorus 1)<br/>',NULL,20360,4);
INSERT INTO stanza VALUES('NS294','3','Tell me all about the Woman Who<br/>Lit the lamp and swept<br/>Throughout the whole house,<br/>Seeking everywhere to find one coin!<br/>I’m so glad the Spirit found me!<br/>(Repeat Chorus 2)<br/>',NULL,20361,5);
INSERT INTO stanza VALUES('NS294','4','Tell me all about the Father who<br/>Waited every day to greet His lost son;<br/>Kissed his neck<br/>And gave him the finest robe,<br/>And brought him back into the household.<br/>(Repeat Chorus 1)<br/>',NULL,20362,6);
INSERT INTO stanza VALUES('NS295','1','Lord, I give my heart to You<br/>And all that’s mine, enjoying You forever,<br/>Lord, I give my heart to You<br/>And all that’s mine, enjoying You forever;<br/>For the joy of loving You, my dear Lord,<br/>In Your presence I’m in love with You,<br/>As Your bride and wife,<br/>Oh my Lord, I love You.<br/>For the joy of loving You, my dear Lord,<br/>In Your presence I’m in love with You,<br/>As Your bride and wife,<br/>Oh my Lord, I love You, Jesus.<br/>',NULL,20363,1);
INSERT INTO stanza VALUES('NS296','1','Jesus, Jesus our Redeemer<br/>Has become our Jubilee,<br/>Sent to proclaim the release<br/>Of all held in captivity.<br/>To the blind recovered sight—<br/>The release of all oppressed.<br/>To proclaim the year of the Lord,<br/>Hallelujah Jubilee.<br/>',NULL,20364,1);
INSERT INTO stanza VALUES('NS296','2','Jesus, Jesus our Redeemer<br/>Has secured our liberty,<br/>He has freed us from our bondage<br/>Now in His life we are free.<br/>From the darkness to the light—<br/>Now in Him reality.<br/>We proclaim the year of our Lord,<br/>Hallelujah Jubilee.<br/>',NULL,20365,2);
INSERT INTO stanza VALUES('NS296','3','Jesus, Jesus our Redeemer<br/>Has restored us to the land,<br/>He has brought us to the Father<br/>Now fore’er to dwell in Him.<br/>From a distant land to home—<br/>His embrace now comforts us.<br/>We proclaim the year of our Lord,<br/>Hallelujah Jubilee.<br/>',NULL,20366,3);
INSERT INTO stanza VALUES('NS296','4','Jesus, Jesus our Redeemer<br/>Has restored the family,<br/>Brothers, sisters we are here now<br/>In God’s house eternally.<br/>No more strangers from His love—<br/>Now His children ere to be.<br/>We proclaim the year of our Lord,<br/>Hallelujah Jubilee.<br/>',NULL,20367,4);
INSERT INTO stanza VALUES('NS297','1','Buried? Yes, but it is seed<br/>From which Continents may feed;<br/>Millions yet may bless the day<br/>When that seed was laid away.<br/>',NULL,20368,1);
INSERT INTO stanza VALUES('NS297','2','Buried! hidden! out of sight!<br/>Dwelling in the deepest night;<br/>Losing, underneath the sod,<br/>Everything, except its God.<br/>',NULL,20369,2);
INSERT INTO stanza VALUES('NS297','3','Buried, unremember’d, lost<br/>So thinks man: but all the cost<br/>God has counted to display<br/>Life abundant one glad day.<br/>',NULL,20370,3);
INSERT INTO stanza VALUES('NS297','4','Art thou buried? God’s pure seed<br/>Doth thy heart in silence bleed?<br/>Change thy sighing into song,<br/>Thus alone can harvests come.<br/>',NULL,20371,4);
INSERT INTO stanza VALUES('NS298','1','The love of Christ is Christ Himself.<br/>Just as Christ is immeasurable,<br/>So also is His love;<br/>Hence, it is knowledge surpassing.<br/>Yet we can know it by experiencing it.<br/>',NULL,20372,1);
INSERT INTO stanza VALUES('NS298','2','When Christ makes His home in our hearts,<br/>And when we are full of strength to apprehend<br/>With all the saints the dimensions of Christ<br/>And to know by experience His knowledge surpassing love,<br/>We will be filled unto all the fullness of God,<br/>Which is the church, the corporate expression of God<br/>For the fulfillment of His intention.<br/>',NULL,20373,2);
INSERT INTO stanza VALUES('NS299','1','I’m so attracted by Your love,<br/>And I’m drawn by You<br/>In Your sweetness, to pursue, after You<br/>For my full satisfaction.<br/>',NULL,20374,1);
INSERT INTO stanza VALUES('NS299','chorus','I’m in love, I’m in love, I’m in love<br/>With the most beautiful One.<br/>',NULL,20375,2);
INSERT INTO stanza VALUES('NS299','2','I’m captivated by Your name<br/>And I’m charmed by You;<br/>With Your fragrance covering me I was gained<br/>As You kissed me with Your kisses.<br/>',NULL,20376,3);
INSERT INTO stanza VALUES('NS299','chorus','I’m in love, I’m in love, I’m in love<br/>With the most affectionate One.<br/>',NULL,20377,4);
INSERT INTO stanza VALUES('NS299','3','I’m fellowshipping in Your love<br/>And rejoicing in You.<br/>In Your chambers I enjoy our sweet love<br/>For the church, Your satisfaction.<br/>',NULL,20378,5);
INSERT INTO stanza VALUES('NS299','chorus','I’m in love, I’m in love, I’m in love<br/>With the most intimate One.<br/>',NULL,20379,6);
INSERT INTO stanza VALUES('NS300','1','Lord, I do thank You for another day<br/>To practice living You, in You to stay,<br/>Lord, grant me the grace, You life mine to replace<br/>Two lives one, oh what a sweet embrace.<br/>',NULL,20380,1);
INSERT INTO stanza VALUES('NS300','2','Lord, You are glory, You are beauty;<br/>Divine and human woven utterly<br/>Have mercy on me, that I may be<br/>Joined to You, expressing You daily.<br/>',NULL,20381,2);
INSERT INTO stanza VALUES('NS300','3','Lord, be my pattern, humble and lowly;<br/>Save me from self and pride and vainglory.<br/>Preserve and keep me, for Your economy,<br/>Live in me, possess me wholly.<br/>',NULL,20382,3);
INSERT INTO stanza VALUES('NS300','4','Lord, I do love You, operate in me,<br/>Be my salvation, save me constantly<br/>To hold forth Your word, life to others afford;<br/>Shining You, so radiantly, dear Lord.<br/>',NULL,20383,4);
INSERT INTO stanza VALUES('NS300','5','Lord, I’m so saturated with Your joy<br/>That I am drunken, You as wine enjoy;<br/>I’d pour out my being, as a drink offering<br/>Upon You, God satisfying.<br/>',NULL,20384,5);
INSERT INTO stanza VALUES('NS300','6','Lord, my desire is to be found in You<br/>As lived out righteousness, give me this view.<br/>Lord, clothe and stitch me, with embroidery<br/>Day by day, inwrought Your gold in me.<br/>',NULL,20385,6);
INSERT INTO stanza VALUES('NS301','1','Thou art my Beloved,<br/>The most lovely Beloved,<br/>My heart and my soul are<br/>Seeking after Thee;<br/>Thou art my Beloved,<br/>The most lovely Beloved,<br/>My heart I open wide to Thee.<br/>',NULL,20386,1);
INSERT INTO stanza VALUES('NS301','2','Come now! Fill me! With Thy Spirit!<br/>Fill up this vessel! I belong to Thee!<br/>Come now! Fill me! With Thy Spirit!<br/>That I Your expression may be!<br/>',NULL,20387,2);
INSERT INTO stanza VALUES('NS301','3','Come and fill me, Lord, to the brim!<br/>Yes, Lord, even me!<br/>Capture me, never let me win!<br/>Come and fill me, Lord, to the brim!<br/>Overflow in me!<br/>Overcome in me!<br/>',NULL,20388,3);
INSERT INTO stanza VALUES('NS302','chorus','Draw me, dear Lord.<br/>Draw me today.<br/>From everything else, dear Lord,<br/>Draw me away.<br/>',NULL,20389,1);
INSERT INTO stanza VALUES('NS302','1','O Lord, this whole world<br/>Seems to weigh me down.<br/>All the cares, the strife the sin,<br/>Within me and all around.<br/>',NULL,20390,2);
INSERT INTO stanza VALUES('NS302','2','But, Lord, I want to set my heart,<br/>And, Lord, I want to stay with You.<br/>’Cause only when You’re near to me<br/>Is everything okay.<br/>',NULL,20391,3);
INSERT INTO stanza VALUES('NS302','3','And though everything may fall apart<br/>Or everything go my way,<br/>It doesn’t really matter, Lord,<br/>As long as I gain You today.<br/>',NULL,20392,4);
INSERT INTO stanza VALUES('NS303','1','Lord, I take You as my sin offering for what I am,<br/>But Lord, I take You as my burnt offering for what I’m not.<br/>I’m not loving, submissive, patient, kind, or meek,<br/>I’m not single in view, Lord, nor is it God I seek.<br/>But dearest Lord, You’re all these things, all virtue’s in You,<br/>So Lord I lay my hands on You in all I do.<br/>',NULL,20393,1);
INSERT INTO stanza VALUES('NS303','2','Lord, in me is all self-love, envy, anxiety<br/>Lord, in me is only pride and no humility.<br/>I’m not pure, Lord, or trusting, neither absolute<br/>For Your purpose, I waver — I’m not resolute!<br/>But dearest Lord, You’re all these things, all virtue’s in You,<br/>So Lord I lay my hands on You in all I do.<br/>',NULL,20394,2);
INSERT INTO stanza VALUES('NS303','3','Such a laying on of hands is not for substitution;<br/>When we lay our hands on Christ, it brings in a union.<br/>By our laying our hands on Christ, we are joined to Him.<br/>We become one — no longer two — we become Him!<br/>In such a union all our weaknesses, wounds, and scars<br/>Are taken on by Him and His virtues become ours.<br/>',NULL,20395,3);
INSERT INTO stanza VALUES('NS303','4','Such a union requires exercise through proper prayer<br/>We open our failures, defects for our Lord to bear.<br/>As we pray in this way, Christ — the One with no such sin<br/>As the life-giving Spirit moves and works within<br/>To live in us a life, a repetition of Christ our King,<br/>The One who lived on earth the life of the burnt offering.<br/>',NULL,20396,4);
INSERT INTO stanza VALUES('NS303','5','Lord, You’re balanced, fine and pure and loving through and through<br/>You welcome the leprous ones, blind, lame all come to You.<br/>You have eyes of a dove, Lord — blemish free are You.<br/>No mixed motives, self-glory, what the Father says You do!<br/>Your humility’s unsurpassed — obedient e’en unto death.<br/>Trusting in the Father’s will, living by Him breath by breath!<br/>',NULL,20397,5);
INSERT INTO stanza VALUES('NS303','6','Thus, I open up to You each failure, blemish, and spot.<br/>I want You to know me, Lord, and know all that I’m not.<br/>You’re my Husband, my strong One, I am just Your wife.<br/>Bear my burdens, my loved One, give me Your wonderful life!<br/>I take up this exchange, God Himself is what I’ve got.<br/>You can bear all that I am, You can be all that I’m not!<br/>You can bear all that I am, You can be all that I’m not!<br/>',NULL,20398,6);
INSERT INTO stanza VALUES('NS304','1','Lord, I love You:<br/>Lord, take my heart.<br/>Lord, saturate me.<br/>Fill every part with Your life divine.<br/>Lord, I now surrender all to You.<br/>Keep me turning to You every day.<br/>Until I’m expressing only You always.<br/>Until I’m expressing only You.<br/>',NULL,20399,1);
INSERT INTO stanza VALUES('NS304','2','Lord, keep us burning;<br/>Make us Your counterpart.<br/>Lord, saturate us;<br/>Fill every part with Your life divine.<br/>Lord, we now surrender all to You.<br/>Keep us turning to You every day,<br/>Until we’re expressing only You, always;<br/>Until we’re expressing only You.<br/>',NULL,20400,2);
INSERT INTO stanza VALUES('NS305','1','From the moment I first met Thee,<br/>How my heart was filled with joy.<br/>Hallelujah! Full joy in me,<br/>As Thou flood me without alloy.<br/>Oh the sweetest love is this first love;<br/>Jesus, O Jesus my love!<br/>Far excelling all other loves,<br/>Such love reaches me.<br/>Such a sweet love, such a true love—<br/>Jesus, O Jesus my love!<br/>',NULL,20401,1);
INSERT INTO stanza VALUES('NS306','1','The risen Christ my Shepherd is.<br/>He graciously my soul doth feed.<br/>My Christ is mine, and I am His.<br/>How can I lack or e’er have need?<br/>',NULL,20402,1);
INSERT INTO stanza VALUES('NS306','2','In pastures green He makes me lie.<br/>My soul He satisfies always,<br/>The restful water leads me by,<br/>In fellowship and perfect peace.<br/>',NULL,20403,2);
INSERT INTO stanza VALUES('NS306','3','I often stray; He seeketh me<br/>To yield my heart to His control.<br/>For His name’s sake He leadeth me<br/>And shepherds my oft-shaken soul.<br/>',NULL,20404,3);
INSERT INTO stanza VALUES('NS306','4','Incredible the thought beside—<br/>Pursuing Thee all care is stilled.<br/>Thy rod and staff support and guide;<br/>My way is with Thy presence filled.<br/>',NULL,20405,4);
INSERT INTO stanza VALUES('NS306','5','Emboldened in Thy victory,<br/>I feast surrounded by my foes,<br/>My head anointed bountifully,<br/>My cup with blessings overflows.<br/>',NULL,20406,5);
INSERT INTO stanza VALUES('NS306','6','Thy love the measure of my days,<br/>Thy grace a boundless treasure store;<br/>Good Shepherd, may I sing Thy praise<br/>Within Thy house forevermore.<br/>',NULL,20407,6);
INSERT INTO stanza VALUES('NS307','1','Sun in the day, the moon at night, declare how great is Thy<br/>Lovingkindness and Thy faithfulness (Psalm 92:2)<br/>Give life and breath to man, Your race<br/>Longing for them to seek Your face (Acts 17:25-27)<br/>Loved me, You’re not ashamed<br/>“I have called you by name” (Isaiah 43:1)<br/>Healed me, the brutish and lame<br/>“I have held you by hand” (Psalm 73:23)<br/>Your faithfulness, Your love untold<br/>At last Lord You break my stronghold.<br/>',NULL,20408,1);
INSERT INTO stanza VALUES('NS307','chorus','We consecrate anew<br/>Do train, conform us to You<br/>“May we be like the morning dew,<br/>“How I love You“<br/>Young people satisfying You.” (Psalm 110:3)<br/>',NULL,20409,2);
INSERT INTO stanza VALUES('NS307','2','Your charming self and cheering love drew me to run to You<br/>I thought I could be absolute<br/>But how I’ve failed, how I’ve stumbled<br/>To run this race divine by self<br/>Now I abhor myself<br/>“Look away unto Me” (Hebrew 12:2)<br/>I just cannot prevail<br/>“It is by My Spirit” (Zechariah 4:6)<br/>I am faithless, You’re faithful still (2 Tim 2:13)<br/>Your love is stronger than my will.<br/>',NULL,20410,3);
INSERT INTO stanza VALUES('NS307','3','Your gracious gifts, Your holy calls are irrevocable (Roman 11:29)<br/>Though I am not but You are able<br/>From strength to strength, grace upon grace (Psalm 84:7, John 1:16)<br/>Sustaining me to win the race<br/>My life I give to You<br/>“I will never leave you” (Hebrew 13:5)<br/>My dreams and future, too<br/>“Nor will I forsake you” (Hebrew 13:5)<br/>Oh Lord I do! I do! I do!<br/>I love You Lord I really do.<br/>',NULL,20411,4);
INSERT INTO stanza VALUES('NS308','1','Oh Lord, for this I pray: Make my heart the good earth<br/>So that You may grow in me, grow and grow continually.<br/>Oh Lord, may this living incorruptible seed<br/>Within me enlivening, grow unto maturity.<br/>',NULL,20412,1);
INSERT INTO stanza VALUES('NS308','chorus','Let Your life within me saturate,<br/>Let Your life within me permeate.<br/>May all Your fulness be expressed through me<br/>And my being be conformed to Thee.<br/>',NULL,20413,2);
INSERT INTO stanza VALUES('NS308','2','Renew my mind, oh Lord, day by day dispense Your life;<br/>My wandering thoughts purify completely;<br/>Replace my will, oh Lord, with Your will that I would say<br/>“Oh Lord, Amen,” always trusting You, following You.<br/>',NULL,20414,3);
INSERT INTO stanza VALUES('NS308','3','Increase my love for You so that I would love You,<br/>Return Your love with Yours, responding to Your call;<br/>Reveal more of Yourself to me so I can see<br/>Your divine economy, shine on me Your speaking.<br/>',NULL,20415,4);
INSERT INTO stanza VALUES('NS309','1','Throughout the past twenty centuries<br/>Tens of thousands of precious lives,<br/>Heart treasures, high positions,<br/>And golden futures have been “wasted“<br/>Upon the Lord Jesus.<br/>To the ones who love Him in such a way<br/>He is altogether lovely and worthy of their offering.<br/>What they have poured upon the Lord is not a waste<br/>But a fragrant testimony of His sweetness.<br/>What they have poured upon the Lord is not a waste<br/>But a fragrant testimony of His sweetness.<br/>',NULL,20416,1);
INSERT INTO stanza VALUES('NS311','1','There are two greatest prayers we must pray everyday,<br/>For which Paul the apostle taught us in Ephesians,<br/>One in chapter one and the other, chapter three,<br/>One for vision and the other for experience.<br/>',NULL,20417,1);
INSERT INTO stanza VALUES('NS311','chorus','Grant us spirit of wisdom and of revelation,<br/>Strengthen us, Lord, with power into our inner man,<br/>Your economy then may become our vision,<br/>And You may make home in our hearts to fulfill Your plan.<br/>',NULL,20418,2);
INSERT INTO stanza VALUES('NS311','2','We have prayed for our many concerns, worries, and plans,<br/>We have prayed for our heart’s desire and so many aims,<br/>We have prayed for good meetings and our gospel friends,<br/>Now let’s rise up and pray prayers that would turn this age!<br/>',NULL,20419,3);
INSERT INTO stanza VALUES('NS311','3','Two millennia have gone by Christians countless as sands,<br/>God’s economy yet a mystery hidden to man,<br/>Many zealous yet with no vision, no restraint,<br/>Who would kneel down and pray to see God’s central vision?<br/>',NULL,20420,4);
INSERT INTO stanza VALUES('NS311','4','What’s God’s calling and glory of His inheritance?<br/>What’s the surpassing greatness of His power fourfold?<br/>What’s the transmission of Christ as Head to the church?<br/>What’s His Body, His fullness while He fills all in all?<br/>',NULL,20421,5);
INSERT INTO stanza VALUES('NS311','5','To see vision we need to pray for four elements,<br/>Wisdom to know and revelation of the objects,<br/>Light for illumination and our eyes opened,<br/>God’s economy then shall be a vision so clear.<br/>',NULL,20422,6);
INSERT INTO stanza VALUES('NS311','6','With the vision we must not be proud or be content,<br/>Lest as Laodicea soon we lukewarm become,<br/>Empty knowledge would only make you poor, blind, naked,<br/>“Buy gold, garments and eyesalve!” — this’ how we overcome!<br/>',NULL,20423,7);
INSERT INTO stanza VALUES('NS311','7','What’re Christ’s unsearchable riches Paul as gospel proclaimed?<br/>What’re the breadth, length, height, depth of Christ we shall apprehend?<br/>What’s the knowledge-surpassing love of Christ to know?<br/>What’s to be filled with all the fullness of God fore’er?<br/>',NULL,20424,8);
INSERT INTO stanza VALUES('NS311','8','Thus we all must pursue to gain the experience,<br/>E’en as Mary wouldn’t let go till the Lord manifest’d,<br/>Look how Paul ran his race to gain Christ till the end,<br/>Let us forget all things and press on to Christ ahead.<br/>',NULL,20425,9);
INSERT INTO stanza VALUES('NS311','9','For experience we must pray to be strengthened always,<br/>That from soul into spirit we would turn and remain,<br/>Only when we’re in spirit can Christ have a way,<br/>From our spirit to make His home in our hearts through faith.<br/>',NULL,20426,10);
INSERT INTO stanza VALUES('NS311','10','Seeing the vision would help us walk on God-ordained way,<br/>Being in spirit then God will build up His dwelling place,<br/>Making home in our hearts is how Christ builds His church,<br/>How His bride is prepared for Him to come end this age.<br/>',NULL,20427,11);
INSERT INTO stanza VALUES('NS311','11','Heav’nly vision must be renewed and ne’er disobeyed,<br/>To experience Christ for His Body — that’s all we care!<br/>Let’s all pray these two greatest prayers day by day,<br/>Hallelujah! We’ll soon bring Him back — no more delay!<br/>',NULL,20428,12);
INSERT INTO stanza VALUES('NS312','1','God realized by us,<br/>With Christ identified—<br/>God reconciled us to Himself,<br/>Now Christ, identified!<br/>',NULL,20429,1);
INSERT INTO stanza VALUES('NS312','2','Born into Adam, we—<br/>But transferred now to Christ;<br/>Made one with Christ, as baptized ones,<br/>Growing togeth’r with Him.<br/>',NULL,20430,2);
INSERT INTO stanza VALUES('NS312','3','In likeness of His death,<br/>That is, newness of life—<br/>Ourselves be reckoned dead to sin,<br/>But live to God, in Christ.<br/>',NULL,20431,3);
INSERT INTO stanza VALUES('NS312','4','We would present ourselves,<br/>To God, from dead—alive.<br/>Present our members “righteous slaves,“<br/>Become thus sanctified.<br/>',NULL,20432,4);
INSERT INTO stanza VALUES('NS313','1','I’m pressing on the God-man way,<br/>New Christ I’m gaining every day,<br/>Still groaning through this world of strife<br/>I want to live a God-man life!<br/>',NULL,20433,1);
INSERT INTO stanza VALUES('NS313','chorus','Lord grow in me! You are the seed,<br/>Of God-man life; You’re all I need.<br/>In all my heart, I give You ground.<br/>Lord, may Your life in me abound!<br/>',NULL,20434,2);
INSERT INTO stanza VALUES('NS313','2','My heart has no desire to stay,<br/>On hardened ground, in the world’s way.<br/>Satan no more shall steal Your Word,<br/>I’ll move my heart where You are heard!<br/>',NULL,20435,3);
INSERT INTO stanza VALUES('NS313','3','I want to deal with rocks in me,<br/>From hidden sins, I would be free.<br/>My heart I would clear up through prayer,<br/>I’ll gain more depth to root You there!<br/>',NULL,20436,4);
INSERT INTO stanza VALUES('NS313','4','The choking thorns, us barren make,<br/>The life seed soon they’ll overtake.<br/>Riches, anxiety reject,<br/>Just for God’s growth the ground protect!<br/>',NULL,20437,5);
INSERT INTO stanza VALUES('NS313','5','The sun must shine for us to grow,<br/>So persecution we will know.<br/>When it seems more than we can bear,<br/>Lord, help us drink You deeply there!<br/>',NULL,20438,6);
INSERT INTO stanza VALUES('NS313','6','We want to grow to utmost height,<br/>Until Your Body comes in sight.<br/>Yourself in man will then be shown;<br/>Your plan at last by all be known!<br/>',NULL,20439,7);
INSERT INTO stanza VALUES('NS314','1','And they sing a new song, saying:<br/>You are worthy to take the scroll<br/>And to open its seals, for You were slain and have purchased for God<br/>By Your blood men out of every tribe and tongue and people and nation,<br/>Men out of every tribe and tongue and people and nation<br/>',NULL,20440,1);
INSERT INTO stanza VALUES('NS314','chorus','And have made them a kingdom and priests to our God;<br/>And they will reign on the earth,<br/>And they will reign on the earth.<br/>',NULL,20441,2);
INSERT INTO stanza VALUES('NS314','2','You are worthy,<br/>You were slain,<br/>You have purchased men for God<br/>Out of every<br/>Tribe and tongue<br/>And people and nation.<br/>',NULL,20442,3);
INSERT INTO stanza VALUES('NS315','1','In this godless age<br/>Lord, You need some Samuels<br/>Burdened with a vision clear of Your economy<br/>Where’s Your ark today?<br/>And the ones who’d care for You,<br/>E’en to put themselves aside to gain Your heart’s desire?<br/>',NULL,20443,1);
INSERT INTO stanza VALUES('NS315','chorus','Raise up some to meet Your need, some Nazarites,<br/>Prophets, priests, and judges, and men of prayer,<br/>Speaking forth Your word, with Your authority,<br/>A photo of Your heart for Your move.<br/>',NULL,20444,2);
INSERT INTO stanza VALUES('NS315','2','Train us up today,<br/>Full of vision, seeking You,<br/>We’d await Your timing, fully subject to Your will,<br/>Treasuring Your face,<br/>Staying in Your presence, Lord;<br/>E’en the very index of Your eye would we obey.<br/>',NULL,20445,3);
INSERT INTO stanza VALUES('NS315','chorus','Raise up some to meet Your need, some Nazarites,<br/>To bring in Your kingdom on earth today,<br/>Taking You as King that You might return<br/>To usher in the end of the age.<br/>',NULL,20446,4);
INSERT INTO stanza VALUES('NS315','3','When God wants to move,<br/>He must gain an instrument;<br/>Overcomers separated from the current age.<br/>They have joined themselves<br/>Through His word to His desire.<br/>Overcomers constituted with the Holy Word.<br/>',NULL,20447,5);
INSERT INTO stanza VALUES('NS315','chorus','Raise up some to meet Your need, some Nazarites,<br/>Voluntary consecrated ones,<br/>Who through Your word are joined to Your desire;<br/>Your living testimony on the earth.<br/>',NULL,20448,6);
INSERT INTO stanza VALUES('NS315','4','God needs men who pray;<br/>Those who lay the tracks for Him;<br/>God’s economy is carried out through men of prayer.<br/>They love not themselves;<br/>But a willing sacrifice.<br/>What they fear—offending God, losing His presence dear.<br/>',NULL,20449,7);
INSERT INTO stanza VALUES('NS315','chorus','Make us those who meet Your need, the Nazarites.<br/>Make us those through whom You’d close this age;<br/>Who are one with You to bring the kingdom in,<br/>Young people absolute for Your move.<br/>',NULL,20450,8);
INSERT INTO stanza VALUES('NS316','1','Oh Jesus, dearest, precious Lord,<br/>We love, we love with all of our heart.<br/>Please make Your home, Lord, more in us.<br/>Lord, spread and gain each part<br/>’Till all our being belongs to You;<br/>Surrender, Lord, ourselves unto You.<br/>Oh Jesus, dearest, precious Lord,<br/>We treasure You with all of our heart.<br/>',NULL,20451,1);
INSERT INTO stanza VALUES('NS316','chorus','We love, we love with all of our hearts.<br/>Please make Your home, Lord, more in us.<br/>Keep spreading until Your work is done.<br/>We’re drawn and captured by You, Lord.<br/>You’ve won our hearts so joyously.<br/>We cannot help but fall in love with You.<br/>',NULL,20452,2);
INSERT INTO stanza VALUES('NS316','2','A purer, deeper lover of Christ;<br/>Lord, keep our hearts so tenderly.<br/>Teach us to trust You and obey.<br/>Lord, soften and renew.<br/>Lord, capture us, appear to us.<br/>You’re matchless in Your beauty and worth.<br/>Abide, we, in Your preciousness;<br/>We’re lovers of this living Person.<br/>',NULL,20453,3);
INSERT INTO stanza VALUES('NS316','chorus','We thank You, Lord, You’re reality.<br/>So sweet and comely is Your presence.<br/>You’re precious and You’re lovely, Dear Lord Jesus.<br/>We’re drawn and captured by You, Lord.<br/>You’ve won our hearts so joyously.<br/>We can’t but help, Lord, fall in love with You.<br/>',NULL,20454,4);
INSERT INTO stanza VALUES('NS316','3','We long that You’d be satisfied.<br/>Lord, grant our hearts for You to burn.<br/>Appear to us, Lord, day by day,<br/>Until we’re fully drawn.<br/>We come to You by Your embrace,<br/>We cling to You, Lord, by Your might.<br/>Lord, grow in us, make home in us.<br/>Oh Lord, You’re our Beloved Bridegroom.<br/>',NULL,20455,5);
INSERT INTO stanza VALUES('NS316','chorus','We love, we love with all of our hearts.<br/>Please make Your home, Lord, more in us.<br/>Keep spreading until Your work is done.<br/>We’re drawn and captured by You, Lord.<br/>You’ve won our hearts so joyously.<br/>We cannot help but fall in love with You.<br/>',NULL,20456,6);
INSERT INTO stanza VALUES('NS317','1','You fill me Lord Jesus<br/>You enlighten my darkness;<br/>Your life brings me freedom<br/>Your love heals my pain<br/>Your dream is my treasure;<br/>Your majesty awes me<br/>You’ve filled me Lord Jesus<br/>Come fill me again.<br/>',NULL,20457,1);
INSERT INTO stanza VALUES('NS317','2','Let Your north wind blow on me,<br/>Let Your Spirit surround me<br/>’Til my being is open, trusting You once again.<br/>Then burn and consume me<br/>With Your jealous God’s fire<br/>’Til me being is obedient,<br/>’Til my soul You have gained.<br/>',NULL,20458,2);
INSERT INTO stanza VALUES('NS317','3','I will turn my heart to You;<br/>Seal and pledge Yourself in me.<br/>Mingle with me completely<br/>Like the fire in the flame;<br/>Til my being is glowing;<br/>Your workmanship showing;<br/>I will turn my heart to You<br/>Again and again.<br/>',NULL,20459,3);
INSERT INTO stanza VALUES('NS318','1','But to Him who is able<br/>Able to do superabundantly<br/>Above all that we ask or think,<br/>According to the power<br/>Which operates in us,<br/>',NULL,20460,1);
INSERT INTO stanza VALUES('NS318','2','To Him be the glory in the church<br/>And in Christ Jesus<br/>Unto all the generations.<br/>To Him be the glory,<br/>To Him be the glory<br/>Forever and ever. Amen.<br/>',NULL,20461,2);
INSERT INTO stanza VALUES('NS319','1','God’s economy is His plan to dispense Himself<br/>Into His chosen, predestinated, and redeemed people<br/>As their life (as their life), their life supply, (their life supply)<br/>And their everything<br/>To produce (to produce), constitute (constitute),<br/>And build up the organic Body of Christ,<br/>Which consummates the New Jerusalem.<br/>',NULL,20462,1);
INSERT INTO stanza VALUES('NS319','2','God’s eternal economy<br/>Is to make man the same as He is<br/>In life and nature but not in the Godhead<br/>And to make Himself one with man<br/>And man one with Him,<br/>Thus to be enlarged<br/>And expanded in His expression,<br/>That all His divine,<br/>That all His divine attributes<br/>May be expressed in human virtues.<br/>',NULL,20463,2);
INSERT INTO stanza VALUES('NS319','3','God’s economy and goal<br/>According to His heart’s desire<br/>Are to build Himself into our being<br/>And to build us into His being<br/>In order to mingle His divinity with our humanity<br/>Into one entity (one entity)—<br/>The Body of Christ,<br/>Which consummates the New Jerusalem,<br/>Which consummates the New Jerusalem.<br/>',NULL,20464,3);
INSERT INTO stanza VALUES('NS320','chorus','We work together with God by a life,<br/>We work together with God by a life:<br/>All-sufficient,<br/>All-mature;<br/>',NULL,20465,1);
INSERT INTO stanza VALUES('NS320','1','(Brothers) Able to fit<br/>(Sisters) All situations,<br/>(Brothers) Able to endure<br/>(Sisters) Any kind of treatment,<br/>(All) To accept any kind of environment;<br/>(Brothers) All-fitting life!<br/>',NULL,20466,2);
INSERT INTO stanza VALUES('NS320','2','Able to work<br/>In any condition,<br/>To take any kind<br/>Of opportunity<br/>For the carrying out of our ministry;<br/>All-fitting life!<br/>',NULL,20467,3);
INSERT INTO stanza VALUES('NS320','chorus','We work together with God by a life,<br/>We work together with God by a life:<br/>All-sufficient,<br/>All-mature;<br/>All-sufficient<br/>All-mature;<br/>All-fitting life.<br/>',NULL,20468,4);
INSERT INTO stanza VALUES('NS321','1','Glorious vision, I have seen it: My life is meant for God’s economy!<br/>Earthly bondage, I have left it: My heart outpours for the Lord’s recovery!<br/>Divine Trinity, Divine dispensing: Christ to be life as Spirit real is He;<br/>Churches of God, Body of Christ, New Jerusalem—how I long to see.<br/>',NULL,20469,1);
INSERT INTO stanza VALUES('NS321','chorus','O Lord, we give ourselves afresh, Into Your training hands to be,<br/>Molded, shaped, and worked on daily, To be vessels of Your glory!<br/>May all my life and work declare, Uniqueness of Your recovery<br/>To build Your Body, prepare Your bride, To bring You back, fulfill Your longing!<br/>',NULL,20470,2);
INSERT INTO stanza VALUES('NS321','2','Heav’n and earth shall have one living: God and man in organic union live,<br/>Resurrection power supplying, Conformed to Christ’s death, no longer I live!<br/>Take His model, tread His footsteps, Go out the camp to live within the veil,<br/>Walk with God, obey His headship, New man un’versal, God’s kingdom to bring.<br/>',NULL,20471,3);
INSERT INTO stanza VALUES('NS321','3','As the members of one Body, Built up in love, support in spirit each,<br/>Christ dispensing, Spirit minist’ring, Blending until we’re all made one in Him.<br/>Give our whole being, one soul to be, Vital groups forming, build up Body His,<br/>Gospelize and truthize widely, Shepherd as God, New Revival to reach.<br/>',NULL,20472,4);
INSERT INTO stanza VALUES('NS321','4','Zion Highways, Our heart’s longing, Though pass through Baca valley yet not cease,<br/>All loss count we, Refuse, rubbish; Care for God’s interests, vision ever heed.<br/>My Lord shall be no more delayed, Be overcomers, pave the way for Him!<br/>Conquering all foes, reigning with Him, How splendid, beauteous, Zion the High Peak!<br/>',NULL,20473,5);
INSERT INTO stanza VALUES('NS322','1','We have found a simple way for us to really touch the Lord:<br/>All we do is pray four words, and O what grace He does afford!<br/>From our spirit now we say them, and we spread the news abroad,<br/>It’s easy to touch the Lord!<br/>',NULL,20474,1);
INSERT INTO stanza VALUES('NS322','chorus','Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>It’s easy to touch the Lord!<br/>',NULL,20475,2);
INSERT INTO stanza VALUES('NS323','1','Behold what manner of love<br/>The Father has given unto us,<br/>Behold what manner of love<br/>The Father has given unto us,<br/>That we should be called the sons of God,<br/>That we should be called the sons of God.<br/>',NULL,20476,1);
INSERT INTO stanza VALUES('NS324','1','Jesus is the Lord, and He lives in me;<br/>Now I’m as happy as I can be.<br/>O Hallelujah! O Hallelujah!<br/>Jesus lives in me!<br/>',NULL,20477,1);
INSERT INTO stanza VALUES('NS324','2','All the world is filled with vanity;<br/>Jesus is the one reality.<br/>O Hallelujah! O Hallelujah!<br/>Jesus lives in me!<br/>',NULL,20478,2);
INSERT INTO stanza VALUES('NS325','1','Rejoice in the Lord always;<br/>And again I say, rejoice.<br/>Rejoice in the Lord always;<br/>And again I say, rejoice.<br/>',NULL,20479,1);
INSERT INTO stanza VALUES('NS326','1','You shall love the Lord with all your heart<br/>You shall love the Lord with all your soul,<br/>You shall love the Lord with all your mind,<br/>With all your heart, with all your soul, with all your mind.<br/>',NULL,20480,1);
INSERT INTO stanza VALUES('NS326','2','Oh, Lord I love You for all the things You are!<br/>Oh, Lord I love You for all the things You do!<br/>Oh, Lord I love You. Help me love You more,<br/>With all my heart, with all my soul, with all my mind.<br/>',NULL,20481,2);
INSERT INTO stanza VALUES('NS327','1','But you, O man of God, flee these things,<br/>And pursue righteousness, godliness, faith,<br/>Love, endurance, meekness.<br/>Fight the good fight of the faith;<br/>Lay hold on the eternal life, to which you were called.<br/>',NULL,20482,1);
INSERT INTO stanza VALUES('NS328','1','S: And I saw,<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; And behold,<br/>S: The Lamb standing<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; On Mount Zion,<br/>All: With a hundred and forty-four thousand,<br/>S: Having His name<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; And the name<br/>S: Of His Father<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; Of His Father<br/>All: Written on their foreheads.<br/>',NULL,20483,1);
INSERT INTO stanza VALUES('NS328','2','S: These are they<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; Who are undefiled,<br/>S: These are they<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; Without guile.<br/>All: These are they who follow the Lamb.<br/>S: These are they<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; Who were purchased<br/>S: From among men,<br/>B:&nbsp;&nbsp;&nbsp;&nbsp; Firstfruits to God.<br/>All: These are they who follow the Lamb, who follow the Lamb.<br/>',NULL,20484,2);
INSERT INTO stanza VALUES('NS328','3','Those who follow, follow the Lamb,<br/>Live and walk in the mingled spirit<br/>And are thus led, led by the Spirit<br/>Continually, continually in their daily life.<br/>',NULL,20485,3);
INSERT INTO stanza VALUES('NS329','1','If therefore anyone cleanses himself from these,<br/>He will be a vessel unto honor sanctified,<br/>Useful to the master,<br/>Prepared unto every good work, unto every good work.<br/>A vessel unto honor, sanctified, useful to the master.<br/>',NULL,20486,1);
INSERT INTO stanza VALUES('NS329','2','But flee youthful lusts, and pursue righteousness,<br/>Faith, love, peace with those who<br/>Call on the Lord out of a pure heart.<br/>',NULL,20487,2);
INSERT INTO stanza VALUES('NS329','3','But flee youthful lusts, and pursue<br/>Righteousness, faith, love, peace with<br/>Those who call, call on the Lord<br/>Out of a pure heart.<br/>',NULL,20488,3);
INSERT INTO stanza VALUES('NS330','1','Turn, turn my heart to You;<br/>Lord, I confess my heart is untrue.<br/>Turn, turn my wandering heart;<br/>Lord, unto me Thy love impart.<br/>',NULL,20489,1);
INSERT INTO stanza VALUES('NS330','chorus','Lord, I call,<br/>I call on Thee.<br/>You’re the only One for me!<br/>',NULL,20490,2);
INSERT INTO stanza VALUES('NS330','2','Rich, rich, He’s rich to all,<br/>Rich unto all that call on His name.<br/>Rich, rich, He’s rich, so call;<br/>Now and forever, Jesus the same.<br/>',NULL,20491,3);
INSERT INTO stanza VALUES('NS330','3','Love, love, the love of God<br/>Flows as a river, full to the brim.<br/>Love, love, I’m filled with love,<br/>Crazy in love with Jesus within.<br/>',NULL,20492,4);
INSERT INTO stanza VALUES('NS331','1','O God of love, in Your everlasting love,<br/>Yearning earnestly for Your elect,<br/>As for Israel so long ago,<br/>That they’d turn from their idols to gain<br/>Your incarnate Christ as righteousness.<br/>',NULL,20493,1);
INSERT INTO stanza VALUES('NS331','2','Christ came as man, as Your righteousness to us,<br/>That in Your divine economy<br/>He Your people’s everything might be<br/>As our universality and our centrality<br/>&nbsp;&nbsp;experienced.<br/>',NULL,20494,2);
INSERT INTO stanza VALUES('NS331','3','Wicked by birth, deceitful corrupt in heart,<br/>Our one hope: redemption from our fall,<br/>Wickedness and sin, but that’s not all—<br/>The redemption of Christ and salvation by life<br/>&nbsp;&nbsp;divine dispensed to us.<br/>',NULL,20495,3);
INSERT INTO stanza VALUES('NS331','4','Saved by Your life and Your life’s capacity,<br/>We’re renewed that You could be our God<br/>And that we Your people all could be<br/>That we’d share the enjoyment of all of the riches of<br/>&nbsp;&nbsp;the Trinity.<br/>',NULL,20496,4);
INSERT INTO stanza VALUES('NS331','5','Israel will be restored in the coming age;<br/>With Your overcomers they’ll enjoy<br/>All Your riches which will consummate<br/>In new earth and new heav’n for eternity in the New<br/>&nbsp;&nbsp;Jerusalem.<br/>',NULL,20497,5);
INSERT INTO stanza VALUES('NS332','1','Lord, You have searched me and You have known me.<br/>You understand my thoughts from afar!<br/>You comprehend my path and are acquainted with all my ways,<br/>For there is not a word on my tongue,<br/>But behold You know it all together!<br/>',NULL,20498,1);
INSERT INTO stanza VALUES('NS332','chorus','Search me, O God, and know my heart;<br/>Try me and know my anxieties;<br/>See if there is any wicked in me,<br/>And lead me in the way everlasting!<br/>',NULL,20499,2);
INSERT INTO stanza VALUES('NS332','2','Lord, You have touched me and You have shown me<br/>That I am not so simple as I thought.<br/>I often run and hide, prone to an errant heart.<br/>But there is not a pause and You pursue!<br/>And behold You’ve caught me altogether!<br/>',NULL,20500,3);
INSERT INTO stanza VALUES('NS332','chorus','Where can I go from Your Spirit, O Lord?<br/>I can’t flee from Your presence, You’re inside me.<br/>I’ve climbed the steep mountains, but You still are there,<br/>Descend to the valleys but You find me.<br/>',NULL,20501,4);
INSERT INTO stanza VALUES('NS332','3','Now I see, there’s something more to this pattern:<br/>You want to show me all that You are.<br/>So You’ve drawn me from this strife, into the family life.<br/>As one, our prayers can match Your deep desires.<br/>Now behold we follow You together!<br/>',NULL,20502,5);
INSERT INTO stanza VALUES('NS333','1','O how glorious! O how precious!<br/>Now the Spirit dwells in me.<br/>Life imparting, truth revealing,<br/>Shining, leading constantly.<br/>',NULL,20503,1);
INSERT INTO stanza VALUES('NS333','chorus','Fill me now! Fill me now!<br/>Fill me with Thy Spirit now!<br/>Strip me wholly, empty thoroughly,<br/>Fill me with Thy Spirit now!<br/>',NULL,20504,2);
INSERT INTO stanza VALUES('NS333','2','Word of promise, real within me,<br/>Life divine now freeing me—<br/>From sin’s cruel control releasing,<br/>From death’s power setting free.<br/>',NULL,20505,3);
INSERT INTO stanza VALUES('NS333','3','Deepest springs of life dispensing,<br/>Like the hart I thirst for Thee;<br/>Desp’rate, may I drink Thy fullness<br/>Till Thy river flows through me.<br/>',NULL,20506,4);
INSERT INTO stanza VALUES('NS333','4','May my self be put to death, Lord,<br/>Under Thy control I’d be.<br/>Transformed to Thy living image,<br/>I’d forever flow out Thee.<br/>',NULL,20507,5);
INSERT INTO stanza VALUES('NS334','1','Emmanuel, Emmanuel,<br/>His name is called Emmanuel.<br/>God with us, revealed in us,<br/>His name is called Emmanuel.<br/>',NULL,20508,1);
INSERT INTO stanza VALUES('NS335','1','For I’m persuaded to believe<br/>Nothing can separate us<br/>From the wonderful love of God;<br/>For the Lord who has called us<br/>According to His purpose<br/>Works all things together for good;<br/>Neither height, nor depth,<br/>Nor principalities,<br/>Things present, nor things to come,<br/>Though the devil hates us,<br/>He can never separate us<br/>From the wonderful love of God.<br/>',NULL,20509,1);
INSERT INTO stanza VALUES('NS336','1','Great is the mystery of godliness,<br/>Great is the mystery of godliness.<br/>The church is the pillar and base of the truth,<br/>The church is the pillar and base of the truth.<br/>The church is the house of the living God.<br/>God was manifested in the flesh,<br/>Justified in the Spirit,<br/>Seen by angels, preached among the nations,<br/>Believed on in the world, taken up in glory.<br/>',NULL,20510,1);
INSERT INTO stanza VALUES('NS337','1','Glory! Glory! Christ is life in me,<br/>As the Spirit leading constantly!<br/>What was weak is mighty,<br/>What was dark is light,<br/>Glory! Glory! Christ is life in me!<br/>',NULL,20511,1);
INSERT INTO stanza VALUES('NS337','2','Glory, Glory! Living by the Lord,<br/>Walking by the Spirit in His Word!<br/>Failure’s turned to vict’ry,<br/>Sighing’s turned to praise.<br/>Glory! Glory! Living by the Lord!<br/>',NULL,20512,2);
INSERT INTO stanza VALUES('NS338','1','Blessed are those who wash their robes<br/>That they might have right to the tree of life.<br/>Blessed are those who wash their robes<br/>That they might have right to the tree of life.<br/>',NULL,20513,1);
INSERT INTO stanza VALUES('NS338','2','And may enter, and may enter, and may enter by the gates<br/>And may enter, and may enter, and may enter by the gates<br/>Into the city, blessed are those.<br/>',NULL,20514,2);
INSERT INTO stanza VALUES('NS338','3','I am the Alpha and the Omega,<br/>The First and the Last,<br/>The First and the Last.<br/>The Beginning and the End,<br/>Blessed are those who wash their robes,<br/>Blessed are those who wash their robes,<br/>Wash their robes!<br/>',NULL,20515,3);
INSERT INTO stanza VALUES('NS339','1','But holding to truth in love<br/>We may grow up in all things<br/>Into Him who is the Head<br/>Christ is the Head<br/>Out from Whom all the Body<br/>Being joined together and<br/>Being knit together through<br/>Ev’ry joint of the rich supply<br/>And through the operation<br/>In the measure of each one part<br/>&nbsp;&nbsp;of each one part<br/>Causes the growth of the Body unto the<br/>&nbsp;&nbsp;building up of itself in love,<br/>&nbsp;&nbsp;in love, in love.<br/>',NULL,20516,1);
INSERT INTO stanza VALUES('NS340','1','Like the woman at the well, I was seeking<br/>For things that could not satisfy.<br/>And then I heard my Savior speaking—<br/>“Draw from My well that never shall run dry.”<br/>',NULL,20517,1);
INSERT INTO stanza VALUES('NS340','chorus','Fill my cup, Lord;<br/>I lift it up Lord;<br/>Come and quench this thirsting of my soul.<br/>Bread of Heaven, feed me till I want no more.<br/>Fill my cup, fill it up and make me whole.<br/>',NULL,20518,2);
INSERT INTO stanza VALUES('NS340','2','There are millions in this world who are seeking<br/>For pleasures earthly goods afford.<br/>But none can match the wondrous treasure<br/>That I find in Jesus Christ my Lord.<br/>',NULL,20519,3);
INSERT INTO stanza VALUES('NS340','3','So my brother if the things that this world gives you<br/>Leave hungers that won’t pass away,<br/>My blessed Lord will come and save you<br/>If you kneel to Him and humbly pray—<br/>',NULL,20520,4);
INSERT INTO stanza VALUES('NS341','1','I have fought the good fight;<br/>I have finished the course;<br/>I have fought the good fight;<br/>I have kept the faith.<br/>',NULL,20521,1);
INSERT INTO stanza VALUES('NS341','2','Henceforth there is laid up for me<br/>The crown of righteousness,<br/>Which the Lord, the Righteous Judge,<br/>Will recompense me in that day,<br/>And not only me<br/>But also all those who have loved His appearing.<br/>',NULL,20522,2);
INSERT INTO stanza VALUES('NS342','1','We all with unveiled face,<br/>Beholding and reflecting as a mirror<br/>The glory of the Lord,<br/>Are being transformed into the same image<br/>',NULL,20523,1);
INSERT INTO stanza VALUES('NS342','2','From glory to glory, from glory to glory,<br/>From glory to glory, we are being transformed.<br/>',NULL,20524,2);
INSERT INTO stanza VALUES('NS342','3','(Brothers:) From glory to glory, from glory to glory,<br/>(Sisters:) ...From glory to glory,<br/>(Everyone:) From glory to glory,<br/>Even as from the Lord Spirit.<br/>',NULL,20525,3);
INSERT INTO stanza VALUES('NS343','1','God is processed, this I know,<br/>For the Bible tells me so.<br/>Incarnated as a man,<br/>Lived and died and raised again.<br/>',NULL,20526,1);
INSERT INTO stanza VALUES('NS343','chorus','Yes, God is processed,<br/>Now He’s the Spirit<br/>To constitute us<br/>With the processed Triune God.<br/>',NULL,20527,2);
INSERT INTO stanza VALUES('NS343','2','Incarnation: mingled makes,<br/>Crucifixion: terminates,<br/>Resurrection: germinates,<br/>Life divine now animates.<br/>',NULL,20528,3);
INSERT INTO stanza VALUES('NS343','3','Incarnated so He can<br/>Have the living of a man.<br/>Crucified and raised that He<br/>Could impart His life to me.<br/>',NULL,20529,4);
INSERT INTO stanza VALUES('NS344','1','He’s able, He’s able,<br/>I know He’s able,<br/>I know my Lord is able<br/>To carry me through.<br/>(Repeat)<br/>',NULL,20530,1);
INSERT INTO stanza VALUES('NS344','2','He healed the broken-hearted<br/>And set the captive free,<br/>He made the lame to walk again<br/>And caused the blind to see.<br/>',NULL,20531,2);
INSERT INTO stanza VALUES('NS344','3','He’s able, He’s able,<br/>I know He’s able,<br/>I know my Lord is able<br/>To carry me through.<br/>',NULL,20532,3);
INSERT INTO stanza VALUES('NS345','1','Be Thou my vision, O Lord of my heart;<br/>Naught be all else to me, save that Thou art;<br/>Thou my best thought, by day or by night;<br/>Waking or sleeping, Thy presence my light.<br/>',NULL,20533,1);
INSERT INTO stanza VALUES('NS345','2','Be Thou my wisdom, and Thou my true Word;<br/>I ever with Thee and Thou with me, Lord;<br/>Thou my great Father and I, Thy true son;<br/>Thou in me dwelling, and I with Thee one.<br/>',NULL,20534,2);
INSERT INTO stanza VALUES('NS345','3','Riches I heed not, nor man’s empty praise;<br/>Thou mine inheritance, now and always;<br/>Thou and Thou only, first in my heart;<br/>O King of glory, my treasure Thou art.<br/>',NULL,20535,3);
INSERT INTO stanza VALUES('NS345','4','O King of glory, my victory won;<br/>Rule and reign in me ’til Thy will be done;<br/>Heart of my own heart, whatever befall;<br/>Still be my vision, O Ruler of all.<br/>',NULL,20536,4);
INSERT INTO stanza VALUES('NS346','1','You shall love the Lord your God<br/>With all your heart and with all your soul,<br/>With all your strength and with all your mind,<br/>And love your neighbour as yourself.<br/>',NULL,20537,1);
INSERT INTO stanza VALUES('NS346','2','You shall love the Lord your God,<br/>You shall love the Lord your God.<br/>',NULL,20538,2);
INSERT INTO stanza VALUES('NS347','1','One day as the Lord passed a well,<br/>A woman so thirsty was there.<br/>He was not content until<br/>He left her the water that’s real, pure, and clear.<br/>Oh, come see a man,<br/>Oh, come see a man,<br/>Who told me all things that ever I did.<br/>Is this not the Christ?<br/>Is this not the Christ?<br/>He fills me forever and ever! Amen.<br/>',NULL,20539,1);
INSERT INTO stanza VALUES('NS347','chorus','Oh, come see a man,<br/>Oh, come see a man,<br/>Who told me all things that ever I did.<br/>Is this not the Christ?<br/>Is this not the Christ?<br/>He fills me forever and ever! Amen.<br/>',NULL,20540,2);
INSERT INTO stanza VALUES('NS347','2','He spoke words that I’d never heard,<br/>Yet how He did stir up my thirst!<br/>He spoke of the water that lives,<br/>To all who are thirsty, He freely will give.<br/>',NULL,20541,3);
INSERT INTO stanza VALUES('NS347','3','Now this living water have I!<br/>I drink and I soar to the sky!<br/>His praises now fill all the air<br/>Because I am speaking Him, now, everywhere!<br/>',NULL,20542,4);
INSERT INTO stanza VALUES('NS348','1','Incarnation<br/>Human living<br/>Crucifixion<br/>Resurrection<br/>Became Spirit<br/>And ascended man!<br/>God became a man<br/>According to God’s plan<br/>To dispense Himself as life to us.<br/>He was processed thus:<br/>Oh, how marvelous!<br/>Then like Him we’re processed through...<br/>',NULL,20543,1);
INSERT INTO stanza VALUES('NS348','2','Regeneration<br/>Sanctification<br/>Then renewing<br/>Transformation<br/>Conformation<br/>Glorification—we<br/>Become God in life<br/>And nature, not in Godhead<br/>Through His organic salvation.<br/>We are processed thus:<br/>Oh, how glorious<br/>To express the processed Triune God.<br/>',NULL,20544,2);
INSERT INTO stanza VALUES('NS349','1','The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you.<br/>',NULL,20545,1);
INSERT INTO stanza VALUES('NS349','2','The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you.<br/>',NULL,20546,2);
INSERT INTO stanza VALUES('NS349','3','The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you.<br/>',NULL,20547,3);
INSERT INTO stanza VALUES('NS349','4','The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you,<br/>The Lord be with your spirit,<br/>Grace be with you.<br/>The Lord be with your spirit,<br/>Grace be with you.<br/>',NULL,20548,4);
INSERT INTO stanza VALUES('NS350','1','O Lord, we’d know Your heart today,<br/>You’d gain a Bride who will not sway;<br/>One seeking only after You,<br/>Whose heart, whose mind, whose will, whose goal<br/>Is always ever true.<br/>',NULL,20549,1);
INSERT INTO stanza VALUES('NS350','2','O Lord, just make us such a one:<br/>A Bride well-pleasing in the Son.<br/>One to satisfy Your heart;<br/>O we would fill Thy longing, Lord,<br/>As Thy sweet counterpart.<br/>',NULL,20550,2);
INSERT INTO stanza VALUES('NS350','3','O Lord, do capture every thought,<br/>Your mind in ours would be inwrought;<br/>Grant us to see Your economy<br/>Until that glorious day, dear Lord,<br/>When You’d be all we see.<br/>',NULL,20551,3);
INSERT INTO stanza VALUES('NS350','4','O Lord, grant us the strength to say,<br/>Our will is Yours in every way;<br/>You’d move through us to all the earth,<br/>To show the nations Your unbounded,<br/>Everlasting worth.<br/>',NULL,20552,4);
INSERT INTO stanza VALUES('NS350','5','O Lord, this would be our life’s goal:<br/>You’d saturate our very soul;<br/>O Lord we’re crying out to You,<br/>Make us Your overcoming Bride, <br/>And see Your purpose through.<br/>',NULL,20553,5);
INSERT INTO stanza VALUES('NS351','1','Jesus Lord, my best love Thou art,<br/>Thou hast fully captured my heart;<br/>None compares with Thee, none on earth or heav’n,<br/>God yet man, most beautiful One!<br/>How I longed to vanish in Thee<br/>When Thy tender voice came to me.<br/>All past loves forsaking most joyfully,<br/>I’d just love Thee — wholeheartedly.<br/>',NULL,20554,1);
INSERT INTO stanza VALUES('NS351','chorus','Who in all the world is as fair as Thee?<br/>Or who else can love so romantic’ly?<br/>Oh, most holy One, now You live in me!<br/>Jesus Lord, I deeply love Thee!<br/>No more trusting self, nor deceived I’d be;<br/>I’d put off my self, just be filled with Thee;<br/>Oh, let all apart from Thee fade and flee;<br/>My one love, my best love, is Thee.<br/>',NULL,20555,2);
INSERT INTO stanza VALUES('NS351','2','Jesus Lord, my best love Thou art;<br/>I was once rebellious and hard,<br/>But I drop it all now to come to Thee,<br/>Self forsake, that like Thee I’d be.<br/>When I live, be it Thou, I pray,<br/>Not self’s will, but God’s I’d obey;<br/>To Thine heart attuned, Thy delight I’d seek;<br/>No more struggling, fully at peace.<br/>',NULL,20556,3);
INSERT INTO stanza VALUES('NS351','3','Jesus Lord, my best love Thou art;<br/>We two never, ever will part;<br/>Thy dear presence is all my breath and might;<br/>Thy dear smile is all my delight.<br/>I would pour my heart out to Thee,<br/>Love Thee, serve Thee, joined utterly;<br/>My eternal portion, dear Lord, is Thee;<br/>My one hope, Thy coming to see.<br/>',NULL,20557,4);
INSERT INTO stanza VALUES('NS352','1','Don’t you want to know your God?<br/>What’s hidden in His heart for you?<br/>How much He longs for you to come <br/>And open up—<br/>To let Him in to every part<br/>Let Him reveal what’s on His heart<br/>What was the joy set before Him?<br/>',NULL,20558,1);
INSERT INTO stanza VALUES('NS352','chorus','It was for her the church—His bride<br/>It was for her, willingly He died<br/>She is the joy deep in His heart <br/>His masterpiece—<br/>His counterpart.<br/>',NULL,20559,2);
INSERT INTO stanza VALUES('NS352','2','The Lord chose you to be a part<br/>Of His great plan, His work of art.<br/>What wonder! What a privilege!<br/>To satisfy<br/>His yearning to share all He is—<br/>Divine, unsearchable riches! <br/>What wisdom, multifarious expressed!<br/>',NULL,20560,3);
INSERT INTO stanza VALUES('NS352','3','As we enjoy and enter in<br/>To all He is then we’ll begin<br/>To understand the feeling in<br/>His heart toward us.<br/>What love that motivated Him<br/>To come to us, despite our sin <br/>Why did He go and sell all that He had?<br/>',NULL,20561,4);
INSERT INTO stanza VALUES('NS353','1','Now to Him Who is able,<br/>Able to establish you according to my gospel;<br/>The proclamation of Jesus Christ<br/>According to the revelation of the mystery;<br/>To the only wise God through Jesus Christ,<br/>The only wise God, To Him be the glory forever,<br/>Forever and ever. Amen. Amen.<br/>',NULL,20562,1);
INSERT INTO stanza VALUES('NS354','1','O my God, within Thee there is eternal life<br/>And this life is expressed in the Son<br/>He has risen, today, as the Spirit of life<br/>Which in us quickens us, gives us life.<br/>',NULL,20563,1);
INSERT INTO stanza VALUES('NS354','2','O behold, from the throne of our God and the Lamb<br/>Flows a river of water of life<br/>God the source, Christ the fount, God the Spirit the flow,<br/>Springing up as a river of life.<br/>',NULL,20564,2);
INSERT INTO stanza VALUES('NS354','3','Jesus Lord, from my spirit I turn unto Thee<br/>Open wide, call Thy name, drink Thee in;<br/>Dearest Lord, to this stream I outpour utterly;<br/>Triune God, flow as life, flood my being.<br/>',NULL,20565,3);
INSERT INTO stanza VALUES('NS355','1','In the Holy Bible<br/>Is a central line,<br/>Truths and revelation<br/>Span the bridge of time.<br/>’Midst the supplemental<br/>And the “branch” or “leaf“<br/>Is the Christ anointed<br/>For eternity.<br/>',NULL,20566,1);
INSERT INTO stanza VALUES('NS355','2','Christ in the beginning<br/>Was the Word of God;<br/>As a living person<br/>Christ on earth did trod.<br/>As the Word Incarnate<br/>He is God defined,<br/>So that by His speaking<br/>Life and light men find.<br/>',NULL,20567,2);
INSERT INTO stanza VALUES('NS355','3','Father, Son, and Spirit<br/>Is the Triune One;<br/>Mutually indwelling,<br/>Father in the Son;<br/>Enjoyed in the Spirit,<br/>Accessed through the Son,<br/>Unto God, the Father<br/>All are joined as one.<br/>',NULL,20568,3);
INSERT INTO stanza VALUES('NS355','4','God by His dispensing,<br/>God’s economy,<br/>Will fulfill His purpose<br/>In His trinity;<br/>From the loving Father,<br/>Through the Son as grace,<br/>In the mingled Spirit,<br/>Is His dwelling place.<br/>',NULL,20569,4);
INSERT INTO stanza VALUES('NS355','5','Christ is all-inclusive,<br/>All-inheriting;<br/>Firstborn of creation,<br/>First in everything;<br/>Son of God effulgent,<br/>Bright, extensive, vast,<br/>Christ, High Priest and Builder,<br/>Is the First and Last.<br/>',NULL,20570,5);
INSERT INTO stanza VALUES('NS355','6','Jesus Christ, the Spirit,<br/>All-inclusive cure,<br/>Is a compound ointment,<br/>Life-giving and pure;<br/>By His sweet anointing<br/>All are sanctified;<br/>For the church, the Spirit<br/>Is intensified.<br/>',NULL,20571,6);
INSERT INTO stanza VALUES('NS355','7','Living in the Body,<br/>Body life is known,<br/>Living by the Spirit<br/>Christ is fully grown;<br/>By organic union<br/>Members cultivate<br/>Body-conscious living,<br/>Age to consummate.<br/>',NULL,20572,7);
INSERT INTO stanza VALUES('NS355','8','See the Holy City,<br/>God’s supernal goal,<br/>God’s organic blueprint,<br/>His eternal scroll;<br/>Corporate reproduction,<br/>New Jerusalem,<br/>Bride of Christ presented;<br/>Worship, praise to Him.<br/>',NULL,20573,8);
INSERT INTO stanza VALUES('NS356','1','In a time before time,<br/>In an age before the ages,<br/>There was God, all alone, in eternity.<br/>Yet He had a heart’s desire.<br/>And an object He required;<br/>A desire in His heart<br/>For a bride, a counterpart<br/>That was deep inside the hidden heart of God.<br/>',NULL,20574,1);
INSERT INTO stanza VALUES('NS356','2','So the heavens He spread,<br/>Earth was made, its foundations laid.<br/>At His word were the birds and the animals.<br/>Then He breathed the breath of life in<br/>To a man created like Him.<br/>As they walked along the way<br/>In the coolness of the day<br/>The intent was still within the heart of God.<br/>',NULL,20575,2);
INSERT INTO stanza VALUES('NS356','3','Man surveyed what God made<br/>Giving names, but he never came<br/>To a mate, and he ached for a counterpart.<br/>He could taste the ’ternal yearning<br/>That so long in God was burning!<br/>Eve was built from Adam’s side<br/>And his heart was satisfied;<br/>Told the story of the hidden heart of God.<br/>',NULL,20576,3);
INSERT INTO stanza VALUES('NS356','4','But when Eve was deceived<br/>What was pure fell beyond a cure.<br/>Dead to God through the dreaded serpent’s subtlety.<br/>Left creation in a quandary!<br/>Generations lived in mystery!<br/>Seeking Job could not perceive<br/>But persisted to believe<br/>There was purpose in the hidden heart of God.<br/>',NULL,20577,4);
INSERT INTO stanza VALUES('NS356','5','In the time He designed<br/>He was born of a virgin’s womb<br/>To reveal what was sealed from eternity.<br/>He was born in human history<br/>To reveal its greatest mystery.<br/>That the answer for the earth<br/>Was that Christ so loved the church.<br/>He would die to satisfy the heart of God.<br/>',NULL,20578,5);
INSERT INTO stanza VALUES('NS356','6','As the throne had foreknown<br/>Many men were deceived again<br/>Through the lies they devised<br/>He was crucified.<br/>As the lonely grain was falling<br/>Still the joy before was calling;<br/>Blood and water from His side<br/>Would redeem and build His bride.<br/>She would satisfy the riven heart of God.<br/>',NULL,20579,6);
INSERT INTO stanza VALUES('NS356','7','Though His death’s final breath,<br/>Finally fell, He could not be held<br/>For His life was divine and unbreakable.<br/>He arises, powers hear it!<br/>He will court her as the Spirit!<br/>As the Spirit giving life<br/>He will find and form His wife.<br/>She will satisfy the living heart of God.<br/>',NULL,20580,7);
INSERT INTO stanza VALUES('NS356','8','When He breathed, she received<br/>His divine personality,<br/>Moving in, washing sin, death and age away.<br/>So that He might sanctify her<br/>By the washing of the water!<br/>Adding beauty, adding health<br/>To present her to Himself<br/>And to satisfy the holy heart of God.<br/>',NULL,20581,8);
INSERT INTO stanza VALUES('NS356','9','In a time beyond time,<br/>In an age beyond the ages,<br/>God and man will be one for eternity.<br/>Hallelujah, what a story!<br/>She was brought from gloom to glory!<br/>And the longing from the start<br/>For a bride, a counterpart<br/>Is fulfilled inside the happy heart of God.<br/>',NULL,20582,9);
INSERT INTO stanza VALUES('NS357','1','Lord, I love You, I’m charmed by You.<br/>I open my whole being to be infused by You.<br/>Lord, do whatever You have to do in me<br/>To make me what You need.<br/>Lord, make my heart a duplication of<br/>Your heart in every possible way.<br/>O Lord, do something in me for You,<br/>And keep my heart single for You.<br/>Lord, I love You.<br/>',NULL,20583,1);
INSERT INTO stanza VALUES('NS358','chorus','Lord, You revealed Yourself to me,<br/>You showed me Your purpose,<br/>To have the church as Your body<br/>So You can mingle all that You are.<br/>',NULL,20584,1);
INSERT INTO stanza VALUES('NS358','1','Though I am blinded by self and flesh<br/>But You, dear Lord, have chosen me<br/>As a vessel to contain You<br/>And express You ’til You come back.<br/>',NULL,20585,2);
INSERT INTO stanza VALUES('NS358','2','Forgive me, Lord I’m open to You.<br/>Fill me more and more each day.<br/>Build me with the saints in love<br/>And keep us running toward the prize.<br/>',NULL,20586,3);
INSERT INTO stanza VALUES('NS358','3','Lord keep me growing and functioning.<br/>Don’t ever let me out of Your sight.<br/>Grant me a spirit of boldness.<br/>Open my mouth, Lord, to prophesy.<br/>',NULL,20587,4);
INSERT INTO stanza VALUES('NS359','1','Me He sought, a lost and wand’ring lamb,<br/>Me He bought, His life outpoured;<br/>I receive His life divine,<br/>Know, enjoy Him evermore.<br/>O my Lord, how I love Thee!<br/>I can’t help but sink in Thee!<br/>By such great love I’m moved, constrained,<br/>All my life I give to Thee.<br/>',NULL,20588,1);
INSERT INTO stanza VALUES('NS359','2','You’re so sweet, my brook, my pasture green,<br/>Waking me, to righteous paths,<br/>’Tis by faith that I’m empow’red<br/>To live out Thy righteousness.<br/>Though the world would bring me woe,<br/>Tide of age would ebb and flow,<br/>Yet, Lord, Thy love cannot be swayed,<br/>In Thy care, no lack I know.<br/>',NULL,20589,2);
INSERT INTO stanza VALUES('NS359','3','When my sense of Thy dear presence fades,<br/>When I lose all touch with Thee,<br/>Though my heart is caught in doubt,<br/>Rod and staff, they comfort me.<br/>Life by faith, I surely know,<br/>Shepherd leads me as I go<br/>Here as I feast before my foes,<br/>Cup of blessing overflows.<br/>',NULL,20590,3);
INSERT INTO stanza VALUES('NS359','4','Foll’wing Thee, Good Shepherd, I would feed,<br/>Shepherd those allotted me,<br/>E’er I’d touch Thy heart’s desire,<br/>Live in Thine economy.<br/>O my Lord, All thanks to Thee!<br/>Goodness, mercy follow me;<br/>I’d ever dwell within Thy house,<br/>As Thy Body glorious!<br/>',NULL,20591,4);
INSERT INTO stanza VALUES('NS360','1','But if I delay,<br/>I write that you may know<br/>How one ought to conduct<br/>Himself in the house of God,<br/>Which is the church,<br/>The church of the living God,<br/>The pillar and base,<br/>The pillar and base of the truth.<br/>',NULL,20592,1);
INSERT INTO stanza VALUES('NS360','2','He who was manifested in the flesh,<br/>Justified in the spirit,<br/>Seen by angels,<br/>Preached among the nations,<br/>Believed on in the world,<br/>Taken up in glory.<br/>',NULL,20593,2);
INSERT INTO stanza VALUES('NS361','1','The goal of the gospel is that,<br/>Loving the Lord Jesus<br/>With the first love,<br/>We would pour out upon Him,<br/>Pour out upon Him<br/>What is most precious to us,<br/>Even our most costly and valuable<br/>Spiritual treasure,<br/>“Wasting” ourselves upon Him.<br/>Even our most costly and valuable<br/>Spiritual treasure,<br/>“Wasting” ourselves upon Him.<br/>',NULL,20594,1);
INSERT INTO stanza VALUES('NS362','1','Lord, for this day, thankful to You,<br/>I give myself to be joined to You anew.<br/>You’re the living water,<br/>Satisfies me ever,<br/>Fills my spirit, in me spreads, and<br/>Floods me till life’s fully manifest.<br/>',NULL,20595,1);
INSERT INTO stanza VALUES('NS362','2','No need for doubt or anxious care,<br/>Just seek His kingdom and righteousness fore’er.<br/>Daily needs compelling,<br/>All to Him I’m telling,<br/>And His peace, so rich and deep,<br/>Preserves me safe and keeps me constantly.<br/>',NULL,20596,2);
INSERT INTO stanza VALUES('NS362','3','Always rejoice, ceaselessly pray,<br/>In all give thanks, ’tis the all-excelling way.<br/>Christ’s the living fountain,<br/>My supply abundant,<br/>All to His hand I entrust, and<br/>He’ll preserve and keep me to the end.<br/>',NULL,20597,3);
INSERT INTO stanza VALUES('NS363','1','For which cause, I remind you<br/>To fan into flame the gift of God<br/>Which is in you<br/>Through the laying on of my hands,<br/>You fan into flame the gift of God,<br/>Which is in you.<br/>',NULL,20598,1);
INSERT INTO stanza VALUES('NS363','2','Do not be, be not ashamed<br/>Of the testimony of our Lord<br/>Nor of me;<br/>Suffer with me and with the gospel,<br/>It’s the testimony of our Lord<br/>For the gospel.<br/>',NULL,20599,2);
INSERT INTO stanza VALUES('NS364','1','Our condition was dead in offenses,<br/>To the flesh we were enslaved.<br/>But together with Christ Jesus He has raised us,<br/>By His grace we have been saved. [Eph. 2:2-6]<br/><br/>God, Your mercy and Your love have reached us,<br/>You have made us alive.<br/>By Your Spirit entering our spirit,<br/>In Your life we’ve been revived. [Eph. 2:4-5]<br/>',NULL,20600,1);
INSERT INTO stanza VALUES('NS364','2','We were once far off but have become near<br/>In the blood of the dear Son.<br/>In His flesh abolished all the ordinances,<br/>Thus creating two as one. [Eph. 2:13, 15]<br/><br/>We have access directly to the Father<br/>Through Christ Jesus, our Lord<br/>In one Spirit, whether Jew or Gentile,<br/>Fellowship has been restored. [Eph. 2:18]<br/>',NULL,20601,2);
INSERT INTO stanza VALUES('NS364','3','Make the prayer that Paul had in Ephesians<br/>The prayer in our daily plan.<br/>Father strengthen us with power through Your Spirit,<br/>Deep into the inner man. [Eph. 3:16]<br/><br/>Lord, keep spreading into every corner,<br/>Lord, keep gaining each part.<br/>We allow you to have the room within us.<br/>Make Your home in all our heart. [Eph. 3:17]<br/>',NULL,20602,3);
INSERT INTO stanza VALUES('NS364','4','Lord, Your riches are so unsearchable.<br/>I can never comprehend. <br/>But with all the saints in such a corporate church life<br/>Your dimensions apprehend. [Eph. 3:8, 18-19]<br/><br/>By Your mercy, keep me in Your Body,<br/>Taking the rich supply.<br/>Through each member’s function in their measure<br/>All the Body edify. [Eph. 4:16]<br/>',NULL,20603,4);
INSERT INTO stanza VALUES('NS364','5','Deep within You is the greatest mystery,<br/>One that countless men have searched.<br/>But to us You have unveiled the revelation,<br/>Now we see Christ and the church. [Eph. 5:32]<br/><br/>Lord, we’re wholly for Your heart’s desire—<br/>Make Your church sanctified.<br/>Through the washing in the pure word’s water<br/>May You gain Your glorious Bride. [Eph. 5:25-26]<br/>',NULL,20604,5);
INSERT INTO stanza VALUES('NS365','1','With the kisses of Your mouth,<br/>Have You kissed me, Lord.<br/>From Your kisses flows a fountain,<br/>From a depth unknown.<br/>Gently tempered by Your touching<br/>Of my deepest chords,<br/>My heart’s renewed with gladness,<br/>And my love o’erflows.<br/>',NULL,20605,1);
INSERT INTO stanza VALUES('NS365','2','Let me kiss You, drink You deeper,<br/>Fully satisfy<br/>All the longings deep within me,<br/>For Your presence nigh,<br/>And a deeper, sweeter union,<br/>Of Your life with mine<br/>That our natures fully mingled,<br/>Would our hearts entwine.<br/>',NULL,20606,2);
INSERT INTO stanza VALUES('NS365','3','Ever increase, Lord, within me,<br/>My desire for You.<br/>Let Your kisses ever kiss me,<br/>And that I’d kiss You.<br/>Dear Lord Jesus, may I ever be,<br/>So betrothed to You.<br/>May I love You, always love You,<br/>And respond to You.<br/>May I love You, always love You,<br/>And respond to You.<br/>',NULL,20607,3);
INSERT INTO stanza VALUES('NS366','1','My heart longs for absolute surrender<br/>That I’d wholly consecrated be,<br/>Not in word alone but all my being<br/>Would be fully given unto Thee.<br/>',NULL,20608,1);
INSERT INTO stanza VALUES('NS366','2','There is little willingness within me<br/>To place all I am before Thy feet,<br/>So I lay my hands on Thy dear head, Lord<br/>As the burnt off’ring, perfect, complete.<br/>',NULL,20609,2);
INSERT INTO stanza VALUES('NS366','3','Lord, You are the only One who offered<br/>Yourself without reluctance unto God;<br/>Full obedience to the Father given,<br/>Absolute, You sacrificed Your all.<br/>',NULL,20610,3);
INSERT INTO stanza VALUES('NS366','4','As this One, You’re dwelling in my spirit;<br/>Moving, spreading outward day by day.<br/>There’s a whisper of Amen within me<br/>In response to all that You would say.<br/>',NULL,20611,4);
INSERT INTO stanza VALUES('NS366','5','I say Yes and give You full permission<br/>To touch every corner of my heart;<br/>Break through all the barriers in my being;<br/>Do not let me withhold any part.<br/>',NULL,20612,5);
INSERT INTO stanza VALUES('NS366','6','’Tis my joy to give You all the ground, Lord;<br/>Make my heart a dwelling place for You;<br/>I want You to be at home within me;<br/>Come and settle down in every room.<br/>',NULL,20613,6);
INSERT INTO stanza VALUES('NS366','7','Lord, do cleanse my heart from all self-seeking<br/>That I’d truly want nothing but Thee;<br/>Let my soul be occupied, possessed, Lord,<br/>That You would be magnified in me.<br/>',NULL,20614,7);
INSERT INTO stanza VALUES('NS367','1','O glorious Christ revealed,<br/>Myself I fully yield;<br/>I long to run to You,<br/>To kiss Your lips anew,<br/>God’s house is my desire,<br/>Bethel, my dream realized;<br/>A dwelling for the lonely,<br/>A feast in Bethany.<br/>Forgiveness, love and care,<br/>Real kingdom life we share;<br/>Peace and joy and righteousness,<br/>The City filled with praise.<br/>Campus, homes, and nations,<br/>Whole earth propagation;<br/>Glory and praise to His name,<br/>To all the earth proclaim.<br/>',NULL,20615,1);
INSERT INTO stanza VALUES('NS367','chorus','Lord, I would offer myself,<br/>Build Your organic Body;<br/>Open homes,<br/>Gain the young,<br/>Shepherd men,<br/>Perfect them,<br/>Bring in the glorious church,<br/>Hasten, Lord, Your return.<br/>',NULL,20616,2);
INSERT INTO stanza VALUES('NS368','1','Have you realized before the foundation of the world<br/>You were marked out?<br/>You cannot escape God’s hand,<br/>Even though you’ve tried a number of times.<br/>The more you try, the stronger He grasps you,<br/>Wherever you go, He is there!<br/>Oh we’ll never rest, ’till we love Him the best,<br/>This lovely One—has us in His heart.<br/>',NULL,20617,1);
INSERT INTO stanza VALUES('NS368','2','It is also by Your mercy we’ve seen<br/>Something so deep in Your heart.<br/>You came to earth and sold all You had<br/>To buy this great pearl of worth.<br/>Oh save me Lord, from chasing vanity,<br/>From selfish dreams, from all that’s binding me—<br/>There’s nothing so high in this universe<br/>As giving ourselves—for what’s on Your heart.<br/>',NULL,20618,2);
INSERT INTO stanza VALUES('NS368','3','You have purposed in time that You’ll build Your church<br/>That nothing prevails over her.<br/>As we flee to meet with the saints,<br/>You’re building Christ into our hearts.<br/>Oh this is not an outward activity!<br/>A meaningful life, one day all men will see—<br/>Oh Lord stir our hearts, to never depart,<br/>To give all we are—for Christ and the church.<br/>',NULL,20619,3);
INSERT INTO stanza VALUES('NS369','1','“The new way brings forth the new man,<br/>The new man walks on the new way.“<br/>Lord, give this new vision to us,<br/>To all of the churches today.<br/>And as we begin this new year,<br/>Make every new day a new start,<br/>Make us the new persons in You:<br/>New spirit, new mind, and new heart.<br/>',NULL,20620,1);
INSERT INTO stanza VALUES('NS369','2','We’re walking in newness of life<br/>And singing a joyful new song;<br/>In newness of spirit we serve,<br/>This new one accord makes us strong.<br/>We’re drinking the new life divine,<br/>Oh, how this new wine our heart cheers!<br/>The new man will walk this new way<br/>Until the new city appears.<br/>',NULL,20621,2);
INSERT INTO stanza VALUES('NS369','3','New man, new creation, new way,<br/>New vision, new spirit, new light,<br/>New year, and new month, and new day,<br/>New mind, and new heart, and new sight,<br/>New garment, new wineskin, new wine,<br/>New blessings, and new covenant,<br/>New mercies, and new life divine,<br/>And completed New Testament!<br/>',NULL,20622,3);
INSERT INTO stanza VALUES('NS370','1','Do you know what you were saved for?<br/>Do you ever wonder why?<br/>What is God’s intent and purpose?<br/>Why has Christ become your life?<br/>',NULL,20623,1);
INSERT INTO stanza VALUES('NS370','chorus','Up till now we Christians only knew<br/>Christ wants to get in you,<br/>And that, indeed, is true;<br/>Yet the vision goes much deeper still,<br/>He has a plan He must fulfill.<br/>',NULL,20624,2);
INSERT INTO stanza VALUES('NS370','2','Eden’s river has a purpose,<br/>Bringing life where’er it goes;<br/>God’s salvation, like a river,<br/>Goes through stages as it flows.<br/>',NULL,20625,3);
INSERT INTO stanza VALUES('NS370','chorus','First we’re saved from Satan’s tyranny,<br/>And later, we will see, from Christianity.<br/>God is flowing in recovery,<br/>Just open up to Him and see.<br/>',NULL,20626,4);
INSERT INTO stanza VALUES('NS370','3','Not just individual Christians,<br/>Isolated, wand’ring free,<br/>But as stones built up together,<br/>Christ expressing corporately.<br/>',NULL,20627,5);
INSERT INTO stanza VALUES('NS370','chorus','We were saved just Jesus to contain,<br/>But there’s a reason too,<br/>That Christ came into you;<br/>He came in, His purpose to secure,<br/>To gain for Him a bride so pure.<br/>',NULL,20628,6);
INSERT INTO stanza VALUES('NS370','4','Not the stones, though very precious,<br/>Elevated “spiritually,“<br/>But the stones built up together<br/>In the Spirit, practically.<br/>',NULL,20629,7);
INSERT INTO stanza VALUES('NS370','chorus','You will ne’er be fully satisfied,<br/>Or be content inside,<br/>Till Jesus has His Bride.<br/>Did you know the Lord is seeking you<br/>To build into His building true?<br/>',NULL,20630,8);
INSERT INTO stanza VALUES('NS371','1','My inner parts have yearned for Him;<br/>To my Beloved I now open;<br/>My Beloved’s gone, He has withdrawn,<br/>I open but He was gone.<br/>',NULL,20631,1);
INSERT INTO stanza VALUES('NS371','chorus','I am sick with love, I am sick with love for Him.<br/>If you find Him, please tell Him that<br/>I am sick with love for Him.<br/>',NULL,20632,2);
INSERT INTO stanza VALUES('NS371','2','I sought Him but I found Him not.<br/>I called Him yet He answered not.<br/>If you find my love please tell Him that<br/>I’m sick with love for Him.<br/>',NULL,20633,3);
INSERT INTO stanza VALUES('NS372','1','Who can be entrusted, God’s gospel spread,<br/>Willing to respond, be commissioned, sent?<br/>His love’s constraining me, ’tis I no more,<br/>This day my response bursts forth: Send me, Lord!<br/>',NULL,20634,1);
INSERT INTO stanza VALUES('NS372','chorus','How I long to live this gospel life,<br/>Afresh consecrate, spread Christ with might,<br/>Respond to His call, press boldly forward, following the Lamb,<br/>Knock on every door! Lord, may You quickly come!<br/>',NULL,20635,2);
INSERT INTO stanza VALUES('NS372','2','In life and in death, in love mutually <br/>Standing in one spirit, co-laboring,<br/>Only for the Body of Christ, and not for self,<br/>Forming His victorious Bride, age turning.<br/>',NULL,20636,3);
INSERT INTO stanza VALUES('NS373','1','There is now then no condemnation to those<br/>Who are in Christ Jesus.<br/>For the law of the Spirit of life has freed me<br/>In Christ Jesus from the law of sin and death.<br/>',NULL,20637,1);
INSERT INTO stanza VALUES('NS373','chorus','For the mind set on the flesh is death,<br/>But the mind set on the spirit is life.<br/>So I will walk in the Spirit today,<br/>Being filled with life and peace!<br/>',NULL,20638,2);
INSERT INTO stanza VALUES('NS373','2','For that which the law could not do, being weak,<br/>In the flesh, God sending His Son,<br/>In the likeness of flesh, and concerning sin,<br/>He condemned sin in the flesh.<br/>',NULL,20639,3);
INSERT INTO stanza VALUES('NS373','3','That the righteous requirement of the law<br/>Might be fulfilled in us,<br/>Who do not walk according to the flesh of sin<br/>But who walk according to the spirit.<br/>',NULL,20640,4);
INSERT INTO stanza VALUES('NS373','4','For those who are according to the flesh,<br/>They all mind the things of the flesh;<br/>But those who are according to the spirit,<br/>Mind the things of the Spirit.<br/>',NULL,20641,5);
INSERT INTO stanza VALUES('NS374','1','What then, brothers? What then, sisters?<br/>What then, shall we do?<br/>Whenever you come together as the church?<br/>What then, brothers? What then, sisters?<br/>What then, shall we do?<br/>Whenever you come together as the church?<br/>',NULL,20642,1);
INSERT INTO stanza VALUES('NS374','2','Each one has a psalm to sing with the saints,<br/>Each one has a teaching to share with the saints,<br/>Each one has a revelation, tongue, and interpretation.<br/>Let all things be done for building up.<br/>',NULL,20643,2);
INSERT INTO stanza VALUES('NS375','1','For we do not have a High Priest who cannot<br/>Be touched with the feeling of our weaknesses,<br/>But One who has been tempted in all respects like us,<br/>Yet without sin, yet without sin.<br/>',NULL,20644,1);
INSERT INTO stanza VALUES('NS375','2','Let us therefore come forward<br/>With boldness to the throne of grace<br/>That we may receive mercy and find grace<br/>For timely help.<br/>',NULL,20645,2);
INSERT INTO stanza VALUES('NS376','1','Lord, nothing but Thy smiling presence will satisfy me.<br/>I do not want anything but the smile of Thy glorious face.<br/>As long as I have this,<br/>I care not whether the heaven comes down<br/>&nbsp;&nbsp;&nbsp;&nbsp;or the earth falls apart.<br/>The whole world may rise up against me,<br/>&nbsp;&nbsp;&nbsp;&nbsp;but as long as I have Thy smile upon me,<br/>I can praise Thee, I can praise Thee,<br/>&nbsp;&nbsp;&nbsp;&nbsp;and everything is well.<br/>',NULL,20646,1);
INSERT INTO stanza VALUES('NS377','1','Being diligent to keep the oneness<br/>Of the Spirit<br/>In the uniting bond of peace:<br/>',NULL,20647,1);
INSERT INTO stanza VALUES('NS377','2','One Body and one Spirit,<br/>Even as also you were called<br/>In one hope, in one hope of your calling;<br/>',NULL,20648,2);
INSERT INTO stanza VALUES('NS377','3','One Lord, one faith, one baptism;<br/>One God and Father of all,<br/>Who is over all and through all and in all.<br/>',NULL,20649,3);
INSERT INTO stanza VALUES('NS378','1','What caused Mary to give her all?<br/>What moved Peter to answer Your call?<br/>Many lives were wasted for Your testimony;<br/>Oh Lord, why do these people care so much for Thee?<br/>',NULL,20650,1);
INSERT INTO stanza VALUES('NS378','chorus','See the vision of Christ and the church;<br/>Count the cost; reckon all things as loss;<br/>Pay the price. The prize to gain Christ,<br/>Burn the bridges; leave the world behind;<br/>On God’s economy your heart be set<br/>To live a life of no regrets.<br/>',NULL,20651,2);
INSERT INTO stanza VALUES('NS378','2','Others have considerations,<br/>When serving You, Lord, is the highest profession.<br/>No longer good for the world with all its glory,<br/>We’re for Christ and the church, ’tis now our testimony.<br/>',NULL,20652,3);
INSERT INTO stanza VALUES('NS378','chorus','See the vision of Christ and the church;<br/>Count the cost; reckon all things as loss;<br/>Pay the price. The prize to gain Christ,<br/>Burn the bridges; leave the world behind;<br/>On God’s economy your heart be set<br/>To live a life...<br/>',NULL,20653,4);
INSERT INTO stanza VALUES('NS378','chorus','We’ve seen the vision of Christ and the church.<br/>Reckoned the cost; all things are but loss.<br/>Will pay the price — give all of our lives;<br/>We’re burning bridges, left the world behind.<br/>On God’s economy our hearts are set<br/>We’re living a life...<br/>On God’s economy our hearts are set,<br/>We’ll live a life of no regrets.<br/>',NULL,20654,5);
INSERT INTO stanza VALUES('NS379','1','Preserve me, O God, for I take refuge in You.<br/>I say to Jehovah, You are my Lord;<br/>Preserve me, O God, for I take refuge in You.<br/>I say to Jehovah, You are my Lord.<br/>',NULL,20655,1);
INSERT INTO stanza VALUES('NS379','2','You are my Lord, You are my Lord;<br/>No good have I beyond You;<br/>You are my Lord, You are my Lord;<br/>No good have I beyond You.<br/>',NULL,20656,2);
INSERT INTO stanza VALUES('NS379','3','As for the saints who are on the earth,<br/>They are the excellent;<br/>All my delight is in them.<br/>',NULL,20657,3);
INSERT INTO stanza VALUES('NS380','1','And to the messenger<br/>Of the church in Philadelphia write:<br/>These things says the Holy One,<br/>The true One,<br/>The One who has the key of David,<br/>The One who opens and no one will shut,<br/>And shuts and no one opens:<br/>',NULL,20658,1);
INSERT INTO stanza VALUES('NS380','2','I know your works;<br/>Behold, I’ve put before you<br/>An opened door<br/>Which no one can shut,<br/>Because you have a little power<br/>And have kept My word<br/>And have not denied My name.<br/>',NULL,20659,2);
INSERT INTO stanza VALUES('NS381','1','I am the living bread, which came down out of heaven;<br/>If anyone, if anyone eats of this bread he shall live forever;<br/>',NULL,20660,1);
INSERT INTO stanza VALUES('NS381','2','And the bread (and the bread)<br/>Which I will (which I)<br/>Will give is my flesh,<br/>given for (given for)<br/>for the life (for the)<br/>life of the world.<br/>',NULL,20661,2);
INSERT INTO stanza VALUES('NS381','3','I am the living bread, which came down out of heaven;<br/>If anyone, if anyone eats of this bread he shall live forever.<br/>',NULL,20662,3);
INSERT INTO stanza VALUES('NS382','1','Little by little,<br/>The Lord is cutting off all our natural life;<br/>As we grow in Him,<br/>He replaces us with more of His life divine.<br/>',NULL,20663,1);
INSERT INTO stanza VALUES('NS382','chorus','It is our destiny,<br/>To live a normal life in the divine dispensing,<br/>It is a blessing,<br/>To be satisfied with ordinary days<br/>&nbsp;&nbsp;in the divine dispensing.<br/>',NULL,20664,2);
INSERT INTO stanza VALUES('NS382','2','Day by day,<br/>Our inward parts are being renewed by the Lord;<br/>Every day,<br/>Fresh and rich supply to us He does afford.<br/>',NULL,20665,3);
INSERT INTO stanza VALUES('NS382','3','Here a little,<br/>And there a little, Christ reveals Himself to us;<br/>When we read His word,<br/>We are satisfied and we enjoy Him thus.<br/>',NULL,20666,4);
INSERT INTO stanza VALUES('NS382','4','Morning by morning,<br/>Jehovah He is faithful to awaken us;<br/>He instructs our ears,<br/>With just a word, the weary to sustain we must.<br/>',NULL,20667,5);
INSERT INTO stanza VALUES('NS382','5','From strength to strength,<br/>We’re on the highways to enter into our God;<br/>Though Satan opposes,<br/>We are strengthened to lay hold of more of God.<br/>',NULL,20668,6);
INSERT INTO stanza VALUES('NS382','6','Grace upon grace,<br/>The Triune God is processed for us to enjoy;<br/>The law is over,<br/>Now we can partake of His supply through grace.<br/>',NULL,20669,7);
INSERT INTO stanza VALUES('NS382','7','From glory to glory,<br/>We are in the process of being transformed;<br/>Beholding, reflecting,<br/>To God’s image with all saints we’ll be conformed.<br/>',NULL,20670,8);
INSERT INTO stanza VALUES('NS383','1','These things says the Holy One,<br/>The true One, the One who has the key of David,<br/>The One who opens, no one will shut,<br/>And shuts and no one opens:<br/>',NULL,20671,1);
INSERT INTO stanza VALUES('NS383','2','I know your works;<br/>Behold, I have put before you an opened door<br/>Which no one can shut,<br/>Because you have<br/>A little power,<br/>Have kept My word,<br/>Have not denied My name.<br/>',NULL,20672,2);
INSERT INTO stanza VALUES('NS384','1','Things which eye has not seen and ear has not heard<br/>and which have not come up in man’s heart;<br/>things which God has prepared for those who love Him;<br/>things which God has prepared for those who love Him.<br/>',NULL,20673,1);
INSERT INTO stanza VALUES('NS384','2','But to us God has revealed them through the Spirit,<br/>for the Spirit searches all things,<br/>even the depths of God.<br/>For who among men knows the things of man,<br/>except the spirit of man which is in him?<br/>',NULL,20674,2);
INSERT INTO stanza VALUES('NS384','3','In the same way, the things of God also<br/>no one has known except the Spirit of God;<br/>no one has known except the Spirit of God.<br/>',NULL,20675,3);
INSERT INTO stanza VALUES('NS385','1','In a world full of temptations,<br/>Sorrows, and sins,<br/>Lord, do shine in me that You’re the way.<br/>Only You can satisfy my deepest, inward part.<br/>Cause Your love to grow within me each day.<br/>',NULL,20676,1);
INSERT INTO stanza VALUES('NS385','2','By Your Spirit in our spirit—<br/>Working, breaking through,<br/>Free us from the self and back to You.<br/>We redeem each precious moment,<br/>Spending time with You,<br/>To become the testimony of Christ.<br/>',NULL,20677,2);
INSERT INTO stanza VALUES('NS385','3','Lord, there is none whom I desire but You.<br/>I would love You and give my all to You.<br/>',NULL,20678,3);
INSERT INTO stanza VALUES('NS386','chorus','When we believe into the Son,<br/>By His Spirit, we are made one;<br/>When we believe into the Son,<br/>By His Spirit, we are made one.<br/><br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Everyone: We are one.<br/>',NULL,20679,1);
INSERT INTO stanza VALUES('NS386','1','The world is longing, seeking for peace,<br/>Yet wars and rumors of wars still increase.<br/>There is no way for men to end all this fear,<br/>All this pain, all this hate, all these tears,<br/>Yet Jesus is here!<br/>',NULL,20680,2);
INSERT INTO stanza VALUES('NS386','2','We are dwelling in the love of the Lord,<br/>He our unity has now restored.<br/>Brothers, sisters in one family,<br/>As the Father and the Son, always one,<br/>So are we!<br/>',NULL,20681,3);
INSERT INTO stanza VALUES('NS386','3','How good and pleasant it can be<br/>When brothers dwell in unity;<br/>Like sweet anointing and the mountain dew;<br/>Life eternal for me and for you—<br/>All things are new!<br/>',NULL,20682,4);
INSERT INTO stanza VALUES('NS387','1','But whoever drinks of the water<br/>That I will give<br/>Shall by no means thirst forever;<br/>The water I’ll give<br/>Will become in him a<br/>Fountain of water<br/>Springing up into eternal life.<br/>',NULL,20683,1);
INSERT INTO stanza VALUES('NS388','1','I am my beloved’s,<br/>And his desire is for me.<br/>',NULL,20684,1);
INSERT INTO stanza VALUES('NS388','2','Come, my beloved,<br/>Let us go forth into the fields;<br/>Let us lodge in the villages.<br/>',NULL,20685,2);
INSERT INTO stanza VALUES('NS388','3','Let us rise up early for the vineyards;<br/>Let us see if the vine has budded,<br/>If the blossom is open,<br/>If the pomegranates are in bloom;<br/>There I will give you my love.<br/>',NULL,20686,3);
INSERT INTO stanza VALUES('NS389','1','The Lord is my greatest love, <br/>He’s won me completely;<br/>As Comforter He ever brings<br/>Timely help and sympathy.<br/>He died, that I be redeemed,<br/>He rose, a life-giving Stream;<br/>Now He in me abides, <br/>My peace, my joy, my life;<br/>Dear Lord! How I love Thee,<br/>Evermore, I love Thee!<br/>',NULL,20687,1);
INSERT INTO stanza VALUES('NS389','2','The church is my home sweet home,<br/>She fills all my longing,<br/>The Lord’s beloved bride is she,<br/>All my days for her shall be. <br/>O home full of love and care!<br/>God’s river of life we share;<br/>I’m strengthened every day,<br/>And guided all the way;<br/>Dear Church! How I love Thee,<br/>Home sweet home, I love Thee!<br/>',NULL,20688,2);
INSERT INTO stanza VALUES('NS390','1','Let us work together with the Lord through prayer,<br/>Praying every time and everywhere.<br/>He will not accomplish His will on His own;<br/>Seek Him ‘till His purpose is made known.<br/>',NULL,20689,1);
INSERT INTO stanza VALUES('NS390','chorus','Make us those who’re one with You in prayer,<br/>Echoing the things for which You care.<br/>Lord, do make us one so that Your heart’s desire we share;<br/>In this age, Lord gain Your men of prayer.<br/>',NULL,20690,2);
INSERT INTO stanza VALUES('NS390','2','Let us open to the Lord Himself through prayer,<br/>Breathe Him deeply as the living air.<br/>Gain the life supply by praying into Him,<br/>’Till our being’s filled up to the brim.<br/>',NULL,20691,3);
INSERT INTO stanza VALUES('NS390','3','Let us fellowship with God in spir’t through prayer;<br/>There is nothing else that can compare.<br/>Lord, we realize there’s nothing we can do,<br/>But all things are possible through You.<br/>',NULL,20692,4);
INSERT INTO stanza VALUES('NS390','4','Let us move together with the Lord through prayer;<br/>For His move on earth we must prepare.<br/>Lord do grow in us ’till we’re matured in life,<br/>As Your army fully qualified.<br/>',NULL,20693,5);
INSERT INTO stanza VALUES('NS390','5','Let us fight together with the Lord through prayer;<br/>Over death, Christ’s vict’ry we declare.<br/>One with the ascended Christ; we soar in prayer,<br/>Fight as one for God’s move everywhere.<br/>',NULL,20694,6);
INSERT INTO stanza VALUES('NS391','1','Oh how sweet it is just to know my Christ!<br/>Knowing Him’s the goal of my whole life.<br/>Gaining Him supplies me, day by day,<br/>He’s rich, He’s excellent in every way.<br/>I’m fully captured by Him, my All in all,<br/>He fills my heart with faith to love Him when I call.<br/>Every day He grows more as faith in me<br/>As I dwell one with Him organically.<br/>',NULL,20695,1);
INSERT INTO stanza VALUES('NS391','2','As a stream of love, how His life flows in!<br/>Motivating us to just love Him.<br/>So we give ourselves; Lord, do grow in us<br/>May we know You in Your preciousness.<br/>O Lord, do make us one as we run toward You,<br/>Pursuing corporately in everything we do<br/>With the saints until full maturity<br/>As Your loving counterpart eternally.<br/>',NULL,20696,2);
INSERT INTO stanza VALUES('NS392','1','Our God is one and yet triune,<br/>The Father in the Son;<br/>Successive stages were His plan,<br/>The Spirit to become;<br/>The first One sent the second One,<br/>Yet, both are still the same;<br/>The first One sent the third One, and,<br/>We’re baptized in His name.<br/>',NULL,20697,1);
INSERT INTO stanza VALUES('NS392','chorus','The Spirit of the Triune God<br/>Is God’s economy;<br/>The consummated Holy One<br/>Flows on and on eternally.<br/>',NULL,20698,2);
INSERT INTO stanza VALUES('NS392','2','Though God in nature cannot change,<br/>He passed through womb and cross;<br/>The Lamb of God has been prepared,<br/>Yet, nothing has been lost.<br/>The Spirit is the compound God;<br/>The One that was “not yet“;<br/>The seven Spirits, seven eyes,<br/>Today are “The Spirit“.<br/>',NULL,20699,3);
INSERT INTO stanza VALUES('NS392','3','The processed God, the flowing God,<br/>Is the eternal source;<br/>Emerging in a bubbling spring,<br/>An overflowing course.<br/>The Father’s love, a fountain is;<br/>The Son, as grace, the spring;<br/>The fellowshipping Spirit flows<br/>Out from our inmost being.<br/>',NULL,20700,4);
INSERT INTO stanza VALUES('NS392','4','The Spirit is a holy realm,<br/>Divine and mystical;<br/>We enter in and live by Him,<br/>He is so practical.<br/>Sevenfold intensified,<br/>The Spirit’s final stage,<br/>Will overcomers soon produce,<br/>To consummate the age.<br/>',NULL,20701,5);
INSERT INTO stanza VALUES('NS393','chorus','Jesus, we love You,<br/>We’re glad You came;<br/>Jesus, we love You!<br/>We call Your name;<br/>Your life impart;<br/>Breathe now into our heart;<br/>Jesus, we love You so!<br/><br/>Spirit, we love You,<br/>Reality!<br/>Spirit, we love You!<br/>Be real to me!<br/>Shine strong, shine bright;<br/>Your light intensify;<br/>Lord Spirit, we love You!<br/><br/>Father, we love You,<br/>We give You praise;<br/>Father, we love You!<br/>And we will always...<br/>',NULL,20702,1);
INSERT INTO stanza VALUES('NS393','1','Give Christ first place;<br/>Enjoy His flowing grace;<br/>We love Your firstborn Son.<br/>',NULL,20703,2);
INSERT INTO stanza VALUES('NS393','2','Sing, praise, pray, call!<br/>Christ is our all in all,<br/>Abba, our Father God!<br/>',NULL,20704,3);
INSERT INTO stanza VALUES('NS394','1','The living vine, a reality<br/>Of God and man, one organically<br/>Mutual abode, organism sweet.<br/>Expression full, mingling complete.<br/>',NULL,20705,1);
INSERT INTO stanza VALUES('NS394','2','When we abide, there’s a flow within.<br/>As branches we—are expressing Him.<br/>Our God needs us, we depend on Him.<br/>To bear much fruit, to bring others in.<br/>',NULL,20706,2);
INSERT INTO stanza VALUES('NS394','3','Father, Cultivator—Husbandman,<br/>The source is He.<br/>Soil, sunshine and the air—<br/>Nutrients complete.<br/>Son, the living vine is—<br/>The embodiment of God.<br/>And the Spirit makes Him real—<br/>As the life juice sweet!<br/>',NULL,20707,3);
INSERT INTO stanza VALUES('NS395','1','That I might be a minister,<br/>A minister of Christ Jesus to the Gentiles,<br/>A laboring priest of the gospel of God,<br/>A laboring priest of the gospel of God,<br/>In order that the offering,<br/>The offering of the Gentiles might be acceptable,<br/>Having been sanctified in the Holy Spirit,<br/>Sanctified in the Holy Spirit.<br/>',NULL,20708,1);
INSERT INTO stanza VALUES('NS396','1','Take me Lord, and fill me with Your dear Self,<br/>Till my whole being is one with You.<br/>Lord, I’m willing to open to You<br/>Every moment in my life;<br/>Fully trusting You, to live Your dream<br/>For Your rest and expression.<br/>',NULL,20709,1);
INSERT INTO stanza VALUES('NS396','2','Beside You I have no one<br/>In heaven or on the earth.<br/>To You, dear Lord, I give my all.<br/>I will not let You go.<br/>Make Your desire my heart’s desire<br/>For our goal, the New Jerusalem.<br/>',NULL,20710,2);
INSERT INTO stanza VALUES('NS397','1','My only hope is the Lord;<br/>Everything depends on Him.<br/>Lord, I’ve loved You before,<br/>But I know that love is unstable.<br/>Set me as a seal on Your heart,<br/>Set me as a seal on Your arm.<br/>My trust is not in my holding power<br/>But in Your love and strength.<br/>In this close, sweet union,<br/>I lean on You, my Beloved.<br/>Fill my being to express You, Lord,<br/>Until You come, my Love.<br/>',NULL,20711,1);
INSERT INTO stanza VALUES('NS398','1','When I first believed, and His life I received,<br/>The seed was sown into me.<br/>Now this seed must grow, and this zoe life flow<br/>As on to maturity.<br/>',NULL,20712,1);
INSERT INTO stanza VALUES('NS398','chorus','Am I a person of life?<br/>Do I experience life?<br/>Does my living bear the issues of life?<br/>Good trees bear good fruit;<br/>Healthy plant, healthy root;<br/>Oh Lord! The ground in my heart!<br/>',NULL,20713,2);
INSERT INTO stanza VALUES('NS398','2','We know that life’s seed is growing indeed<br/>When fruits of life are expressed<br/>Such as virtues of joy, peace, faithfulness, love.<br/>Does my daily life pass the test?<br/>',NULL,20714,3);
INSERT INTO stanza VALUES('NS398','3','When these virtues show others surely will know<br/>The beauty of life will shine,<br/>And the gospel word of life will be heard<br/>Bringing many to know life divine!<br/>',NULL,20715,4);
INSERT INTO stanza VALUES('NS398','4','Lord grant me today, a new start in this way.<br/>A person of life I would be—<br/>Just expressing You in all that I do.<br/>Oh may this life flow out of me!<br/>',NULL,20716,5);
INSERT INTO stanza VALUES('NS400','1','Bit by bit, day by day, His dear words of grace,<br/>Ever fresh, ever sweet, warm my heart apace;<br/>Spirit of wisdom and revelation grant,<br/>Show us our glorious hope and inheritance;<br/>Strengthen us, Lord, into our inner man with strength,<br/>So that Christ may make His home in our hearts through faith. INSERT INTO stanza VALUES('NS400','2','Bit by bit, day by day, I His grace receive;<br/>Grief and fears, pass away! How He cares for me!<br/>In petition and prayer, tell Him everything<br/>And the peace, peace of Christ, passes all we think. INSERT INTO stanza VALUES('NS400','3','Bit by bit, day by day, pow’r of God is shown,<br/>What is seen’s temporal, what’s unseen we’d know;<br/>Treasure in jars of earth, show God’s pow’r divine,<br/>Sharing in Jesus’ death, that His life may shine;  INSERT INTO stanza VALUES('NS401','1','Full Salvation.<br/>Redemption’s not the goal<br/>Full Salvation.<br/>Involves much more—<br/>Full Salvation.<br/>Is all about life spreading—<br/>Filling every part.<br/>',NULL,20720,1);
INSERT INTO stanza VALUES('NS401','2','Christ is—<br/>In me as my hope of—<br/>Glory—Wonderful!<br/>One day—<br/>This seed will fully blossom!<br/>I’ll be glorified!<br/>',NULL,20721,2);
INSERT INTO stanza VALUES('NS402','1','Where is the house you’ll build for Me,<br/>And the place of my rest?<br/>Where then is the house you’ll build for Me,<br/>And the place of my rest?<br/>Heaven is My throne, and the earth<br/>The footstool for My feet.<br/>Where then is the house you’ll build for Me,<br/>And the place of my rest?<br/>',NULL,20722,1);
INSERT INTO stanza VALUES('NS402','2','For all these things My hand has made,<br/>And so all these things have come into being, declares Jehovah.<br/>But to this kind of man will I look, to him who is poor<br/>And of a contrite spirit, and who trembles at My word.<br/>',NULL,20723,2);
INSERT INTO stanza VALUES('NS402','3','Where then is the house you’ll build for Me,<br/>And the place of my rest?<br/>Where then is the house you’ll build for Me,<br/>And the place of my rest?<br/>Heaven is My throne, and the earth<br/>The footstool for My feet.<br/>Where then is the house you’ll build for Me,<br/>And the place of my rest?<br/>',NULL,20724,3);
INSERT INTO stanza VALUES('NS403','1','For God so loved the world<br/>That He gave His only begotten Son,<br/>That everyone who believes into Him<br/>Would not perish.<br/>',NULL,20725,1);
INSERT INTO stanza VALUES('NS403','2','For God so loved the world<br/>That He gave His only begotten Son,<br/>That everyone who believes into Him<br/>Would not perish,<br/>But would have eternal life.<br/>',NULL,20726,2);
INSERT INTO stanza VALUES('NS403','3','O how I adore my Lord,<br/>For He has died for me.<br/>O how I adore my Lord,<br/>For He has given life to me.<br/>',NULL,20727,3);
INSERT INTO stanza VALUES('NS403','4','For God so loved the world<br/>That He gave His only begotten Son,<br/>That everyone who believes into Him<br/>Would not perish,<br/>But would have eternal life.<br/>',NULL,20728,4);
INSERT INTO stanza VALUES('NS404','1','Peace to the brothers and love with faith<br/>From God the Father and the Lord Jesus Christ.<br/>',NULL,20729,1);
INSERT INTO stanza VALUES('NS404','2','Grace be with all those who love our Lord Jesus Christ<br/>In incorruptibility.<br/>',NULL,20730,2);
INSERT INTO stanza VALUES('NS404','3','Grace with those who love our Lord Jesus Christ<br/>In incorruptibility.<br/>Grace with those who love our Lord Jesus Christ.<br/>Grace with those who love our Lord Jesus Christ.<br/>',NULL,20731,3);
INSERT INTO stanza VALUES('NS405','1','Saying, Where is He<br/>Who has been born King of the Jews?<br/>For we saw His star at its rising,<br/>For we saw His star at its rising<br/>And have come to worship Him.<br/>',NULL,20732,1);
INSERT INTO stanza VALUES('NS405','2','And when they saw the star,<br/>They rejoiced exceedingly,<br/>Rejoiced exceedingly with great joy.<br/>And when they saw the star,<br/>They rejoiced exceedingly,<br/>Rejoiced exceedingly with great joy.<br/>',NULL,20733,2);
INSERT INTO stanza VALUES('NS406','1','But God commends His own love to us<br/>In that while we were yet sinners,<br/>Christ died for us.<br/>',NULL,20734,1);
INSERT INTO stanza VALUES('NS406','2','Much more then, having been justified now<br/>In His blood, we shall be saved<br/>Through Him from the wrath.<br/>',NULL,20735,2);
INSERT INTO stanza VALUES('NS406','3','For if, while we were enemies,<br/>We were reconciled to God,<br/>To God through the death of His Son,<br/>Much more, much more,<br/>Having been reconciled,<br/>We shall be saved in His life.<br/>We shall be saved in His life.<br/>',NULL,20736,3);
INSERT INTO stanza VALUES('NS407','1','The first walk in verse sixteen means<br/>“Treading around“,<br/>“Walking at large“,<br/>Habitually, gen’rally<br/>A common walk—for our daily life.<br/>',NULL,20737,1);
INSERT INTO stanza VALUES('NS407','chorus','Living, acting, having our being according<br/>To the spirit,<br/><i>Peripateo</i> and <i>Stoicheo</i><br/>There are two kinds of walk.<br/>',NULL,20738,2);
INSERT INTO stanza VALUES('NS407','2','The walk in verse twenty-five means<br/>“Marching in rank“,<br/>“Keeping in step“,<br/>Deliberately, purposefully<br/>An ordered walk—to fulfill God’s goal.<br/>',NULL,20739,3);
INSERT INTO stanza VALUES('NS407','3','The Spirit Himself should be—<br/>Our rule and our way,<br/>Our principle, goal<br/>Constantly, following<br/>The inner sense—of life and peace.<br/>',NULL,20740,4);
INSERT INTO stanza VALUES('NS408','-','The full ministry of Christ<br/>Is carried out in three stages<br/>For the fulfillment of God’s eternal economy.<br/>',NULL,20741,1);
INSERT INTO stanza VALUES('NS408','1','In the first stage of incarnation:<br/>To bring God into man,<br/>To express God in humanity,<br/>And to accomplish His judicial redemption.<br/>',NULL,20742,2);
INSERT INTO stanza VALUES('NS408','2','In the second stage of inclusion:<br/>To be begotten as God’s firstborn Son,<br/>To become the life-giving Spirit, and<br/>To regenerate the believers for His Body.<br/>',NULL,20743,3);
INSERT INTO stanza VALUES('NS408','3','In the third stage of intensification:<br/>To intensify His organic salvation,<br/>To produce the overcomers, and<br/>To consummate the New Jerusalem.<br/>',NULL,20744,4);
INSERT INTO stanza VALUES('NS408','-','Incarnation, inclusion, intensification.<br/>Incarnation, inclusion, intensification.<br/>',NULL,20745,5);
INSERT INTO stanza VALUES('NS409','chorus','Triune God,<br/>Oh how much You love us.<br/>Triune God,<br/>You gave Yourself to us.<br/>Triune God,<br/>Now You’re the Spirit in us,<br/>We are one with You always.<br/>',NULL,20746,1);
INSERT INTO stanza VALUES('NS409','1','O God our loving Father,<br/>You would receive back Your Son,<br/>Christ the Son our Shepherd<br/>And the Holy Spirit’s sweeping<br/>To bring us back to You always.<br/>',NULL,20747,2);
INSERT INTO stanza VALUES('NS409','2','God the Father’s the staff,<br/>Christ the rock smitten for us,<br/>Once stricken, water poured out,<br/>Issued in the Spirit flowing<br/>That we may have His life always.<br/>',NULL,20748,3);
INSERT INTO stanza VALUES('NS409','3','The Triune God’s dispensing<br/>Himself to us as our life,<br/>His grace is love expressed and <br/>Fellowship keeps us together;<br/>We’re mingled now with Him always.<br/>',NULL,20749,4);
INSERT INTO stanza VALUES('NS409','chorus','Triune God,<br/>Oh how much we love You.<br/>Triune God,<br/>We give ourselves to You.<br/>Triune God,<br/>Now we open to You,<br/>We are one with You always.<br/>',NULL,20750,5);
INSERT INTO stanza VALUES('NS410','1','But unto you who fear My name<br/>Will the Sun of righteousness arise<br/>With healing in His wings,<br/>With healing in His wings.<br/>',NULL,20751,1);
INSERT INTO stanza VALUES('NS410','2','And you will go forth and leap about<br/>&nbsp;&nbsp;&nbsp;&nbsp;like well-fed calves,<br/>And you will go forth and leap about<br/>&nbsp;&nbsp;&nbsp;&nbsp;like well-fed calves.<br/>',NULL,20752,2);
INSERT INTO stanza VALUES('NS410','3','But unto you who fear My name<br/>Will the Sun of righteousness arise<br/>With healing in His wings,<br/>With healing in His wings.<br/>',NULL,20753,3);
INSERT INTO stanza VALUES('NS411','1','Our flesh, which is with us the rest of our lives<br/>Needs to be dealt with, exposed, recognized.<br/>It’s only by eating our Christ every day;<br/>A little each morning, oh this is God’s way!<br/>',NULL,20754,1);
INSERT INTO stanza VALUES('NS411','-','What is it? Manna!<br/>Christ as our food!<br/>Oh change our diet!<br/>Reconstitute us!<br/>What is it? Manna!<br/>Christ as our food!<br/>Oh change our diet!<br/>Reconstitute.<br/>',NULL,20755,2);
INSERT INTO stanza VALUES('NS411','2','The heavenly diet fulfills God’s great plan<br/>Because it supplies and reconstitutes man<br/>To build up the church, His unique dwelling place.<br/>For this heavenly manna, Lord give us the taste!<br/>',NULL,20756,3);
INSERT INTO stanza VALUES('NS412','1','The church is the building up<br/>Of all God’s chosen and redeemed,<br/>Regenerated and transformed people,<br/>The ultimate work of God,<br/>His counterpart, the new man,<br/>The seven golden lampstands,<br/>God’s house on earth,<br/>The Body of Christ,<br/>The desire of God’s heart.<br/>',NULL,20757,1);
INSERT INTO stanza VALUES('NS412','2','Praise the Lord! Philadelphia:<br/>They hold fast to God’s Word,<br/>Never denying His name,<br/>Living in the local church,<br/>Fellowshipping universally<br/>On the ground of genuine oneness,<br/>Constituting the Body of Christ.<br/>',NULL,20758,2);
INSERT INTO stanza VALUES('NS412','3','Rise up! Grow in life!<br/>Minister Christ to the nations,<br/>Arrive at oneness—<br/>Lord, have mercy,<br/>We would see Your eternal purpose.<br/>Keep us faithful<br/>To recover and build up Your church.<br/>',NULL,20759,3);
INSERT INTO stanza VALUES('NS413','1','Let Him kiss me with the kisses of His mouth,<br/>Whether bitter cold north wind or gentle south;<br/>You are beautiful, my love,<br/>With your eyes of turtledoves;<br/>“Let Him kiss me with the kisses of His mouth“.<br/>',NULL,20760,1);
INSERT INTO stanza VALUES('NS413','chorus','Lord I love You, I really love You,<br/>You’re the dearest, sweetest, precious love to me!<br/>Lord I love You, I really love You,<br/>Jesus, my Beloved, for eternity!<br/>',NULL,20761,2);
INSERT INTO stanza VALUES('NS413','2','She’s become a lily, simple, pure and sweet,<br/>Not relying on her naturalness and strength<br/>She is trusting in Christ’s life,<br/>In His rich abundant life;<br/>“Let Him kiss me with the kisses of His mouth“.<br/>',NULL,20762,3);
INSERT INTO stanza VALUES('NS413','3','She’s become a garden, fountain, streams, and springs,<br/>From which fragrant, luscious produce Christ’s life brings,<br/>Resurrection life expressed,<br/>In ascension she can rest;<br/>“Let Him kiss me with the kisses of His mouth“.<br/>',NULL,20763,4);
INSERT INTO stanza VALUES('NS413','4','She’s become the New Jerusalem, His Bride,<br/>Where His presence for eternity abides,<br/>Here His faithfulness we prove,<br/>And we serve Him for His move;<br/>“Let Him kiss me with the kisses of His mouth“.<br/>',NULL,20764,5);
INSERT INTO stanza VALUES('NS413','5','In the final stage of love a kiss remains,<br/>Where the lover and His love forever reign,<br/>“When I find you here with Me, <br/>I will kiss you, all will see“;<br/>“Let Him kiss me with the kisses of His mouth“.<br/>',NULL,20765,6);
INSERT INTO stanza VALUES('NS414','1','Oneness is not unity,<br/>Outward agreement<br/>But a life within—<br/>God’s very life! <br/>The Triune God—included us<br/>In His divine—<br/>Oneness—Oneness.<br/>',NULL,20766,1);
INSERT INTO stanza VALUES('NS414','2','That they all may be one;<br/>Even as You Father, are in Me<br/>And I in You—<br/>That they may be—<br/>May be in us.<br/>Oneness—Oneness.<br/>',NULL,20767,2);
INSERT INTO stanza VALUES('NS415','1','Lord, I love You more today, than any other.<br/>Lord, I love You more right now, than ever before.<br/>Lord, You are so dear, how could my heart desire<br/>Anything that’s less than You;<br/>Lord, You are the One I must choose;<br/>Lord, I love You.<br/>',NULL,20768,1);
INSERT INTO stanza VALUES('NS415','2','Lord, I need You more today, than any other.<br/>Lord, I need You more right now, than ever before.<br/>Lord, You are so near, be everything to me,<br/>I couldn’t live a day without You;<br/>I’m totally dependent on You;<br/>Lord, I need You.<br/>',NULL,20769,2);
INSERT INTO stanza VALUES('NS415','3','Lord, I love You (Lord, I love You),<br/>I’ll never let You go (won’t let You go).<br/>Lord, I love You,<br/>I want You to know,<br/>Lord, I love You so.<br/>',NULL,20770,3);
INSERT INTO stanza VALUES('NS416','1','Lord, today, increase Thyself in me,<br/>Let Thy life grow to maturity;<br/>Just a channel of life, let me be,<br/>A pure vessel glorifying Thee.<br/>',NULL,20771,1);
INSERT INTO stanza VALUES('NS147','1','I was in a world of misery<br/>In this crooked and perverted generation;<br/>But the Lord has call me there one day<br/>And now I’m living in this new generation.<br/>',NULL,20772,1);
INSERT INTO stanza VALUES('NS147','chorus','Oh, what a wonderful story<br/>Of me and my glorious Lord.<br/>Together we make our history;<br/>A mingling of God and of man—<br/>Becoming the New Jerusalem,<br/>Full of God’s glory. Hallelujah!<br/>',NULL,20773,2);
INSERT INTO stanza VALUES('NS147','2','The Lord has regenerated me,<br/>Calling me out of Satan’s kingdom into Him;<br/>Day by day, He is renewing me,<br/>Sanctifying, transforming me to be like Him.<br/>',NULL,20774,3);
INSERT INTO stanza VALUES('NS147','3','Lord, help me to live a God-man life<br/>At home, with the saints, or wherever I would be;<br/>Taking Christ, living Christ as my life<br/>Exercising forbearance without anxiety.<br/>',NULL,20775,4);
INSERT INTO stanza VALUES('NS147','4','I want to be an overcomer<br/>O Lord, I consecrate myself to You right now.<br/>O Lord, make me an overcomer—<br/>Today and for the rest of my days here on earth.<br/>',NULL,20776,5);
INSERT INTO stanza VALUES('NS149','1','Christ has come to be life, the processed divine Trinity.<br/>God the Father’s the source, a fountain emerging to be.<br/>God the Son as a gushing up spring,<br/>And the Spirit’s a river for life imparting<br/>Oh how can this miracle be? The Triune God flowing in me!<br/>Oh, I’ve got rivers of life flowing out of my innermost being!<br/>I’ve got rivers of life flowing out of my innermost being!<br/>',NULL,20777,1);
INSERT INTO stanza VALUES('NS149','chorus','As this life flows through me, I’m supplied abundantly.<br/>His life nullifies sin! Power springs now from within!<br/>To be free, overcoming spontaneously.<br/>',NULL,20778,2);
INSERT INTO stanza VALUES('NS149','2','Yet this life though it frees, is not meant for mere victory.<br/>God is full of intent and never could flow aimlessly.<br/>So this life has a totality, a consummate issue encompassing me.<br/>Life moves and life grows, life shapes as it flows<br/>Now I share in this life’s destiny.<br/>Oh, I’ve got rivers of life flowing out of my innermost being!<br/>I’ve got rivers of life flowing out of my innermost being!<br/>',NULL,20779,3);
INSERT INTO stanza VALUES('NS149','chorus','We’ll abide mutually, God and man revealed to be<br/>Lamb, Wife, Spirit, and Bride.<br/>Come! Drink! And riverside, <br/>Grows the tree, our enjoyment for eternity!<br/>',NULL,20780,4);
INSERT INTO stanza VALUES('NS149','3','So I’ve no cause to frown as one who’s received this zoe.<br/>I know life runs its course and triumphs inevitably.<br/>I’m required just to stay in the flow, <br/>If I do the drinking then God gives the growth.<br/>So there’s joy in my heart, and a spring in my step, <br/>And a smile on my face as I sing,<br/>Oh, I’ve got rivers of life flowing out of my innermost being!<br/>I’ve got rivers of life flowing out of my innermost being!<br/>',NULL,20781,5);
INSERT INTO stanza VALUES('NS150','1','Greatly I rejoiced in the Lord,<br/>Because your thinking for me<br/>Now at length anew has blossomed,<br/>Which you had indeed taken thought,<br/>But lacked opportunity.<br/>',NULL,20782,1);
INSERT INTO stanza VALUES('NS150','chorus','Not by lack so that I speak,<br/>But Christ my secret,<br/>For I have learned in whatever circumstances<br/>To be content.<br/>',NULL,20783,2);
INSERT INTO stanza VALUES('NS150','2','I know how to be abased,<br/>And I know how to abound,<br/>To be filled, to hunger or lack,<br/>In all things and in everything<br/>I’ve learned the secret.<br/>',NULL,20784,3);
INSERT INTO stanza VALUES('NS150','3','I am able to do all things<br/>In Him who empowers me.<br/>Nevertheless you did well<br/>To have fellowship with me<br/>In my affliction.<br/>',NULL,20785,4);
INSERT INTO stanza VALUES('NS151','1','What miracle! What mystery!<br/>That God and man should blended be!<br/>God became man to make man God,<br/>Untraceable economy!<br/>From His good pleasure, heart’s desire,<br/>His highest goal attained will be.<br/>',NULL,20786,1);
INSERT INTO stanza VALUES('NS151','2','Flesh He became, the first God-man,<br/>His pleasure that I God may be:<br/>In life and nature I’m God’s kind,<br/>Though Godhead’s His exclusively.<br/>His attributes my virtues are;<br/>His glorious image shines through me.<br/>',NULL,20787,2);
INSERT INTO stanza VALUES('NS151','3','No longer I alone that live,<br/>But God together lives with me.<br/>Built with the saints in the Triune God,<br/>His universal house we’ll be,<br/>And His organic Body we<br/>For His expression corp’rately.<br/>',NULL,20788,3);
INSERT INTO stanza VALUES('NS151','4','Jerusalem, the ultimate,<br/>Of visions the totality;<br/>The Triune God, tripartite man—<br/>A loving pair eternally—<br/>As man yet God they coinhere,<br/>A mutual dwelling place to be;<br/>God’s glory in humanity<br/>Shines forth in splendor radiantly!<br/>',NULL,20789,4);
INSERT INTO stanza VALUES('NS279','1','Love suffers long. Love is kind; it is not jealous.<br/>Love does not brag and is not puffed up.<br/>Love suffers long. Love is kind; it is not jealous.<br/>Love does not brag and is not puffed up.<br/>',NULL,20790,1);
INSERT INTO stanza VALUES('NS279','2','It does not behave unbecomingly;<br/>It does not seek its own things;<br/>It is not provoked and does not take account of evil;<br/>It does not rejoice because of unrighteousness,<br/>But rejoices with the truth.<br/>',NULL,20791,2);
INSERT INTO stanza VALUES('NS279','3','It covers all things, believes all things,<br/>Hopes all things, endures all things.<br/>Love never falls away, Love never falls away,<br/>Love never falls away, Love never falls away.<br/>',NULL,20792,3);
INSERT INTO stanza VALUES('NS310','1','Once again a new beginning,<br/>Yesterday I’ve put behind,<br/>To You Lord I come in seeking,<br/>For Your Words, bring them to mind.<br/>Oh Lord, grant me Your rich speaking,<br/>Cause my spirit filled to be,<br/>Lord, my heart and thoughts transforming,<br/>That my life I live by Thee.<br/>',NULL,20793,1);
INSERT INTO stanza VALUES('NS310','2','Lord, today I give unto Thee,<br/>Saturate me, capture me,<br/>Shine upon me, burn within me,<br/>Purge my darkness, sin in me.<br/>Free from every fetter, burden,<br/>Joy in choosing all Your ways,<br/>Keeping to the path You’ve trodden,<br/>I’ll submit to You always.<br/>',NULL,20794,2);
INSERT INTO stanza VALUES('NS399','1','When you speak the Word,<br/>He fills you within <br/>And clothes you without;<br/>Then words full of power,<br/>Authority, impact flow out.<br/>',NULL,20795,1);
INSERT INTO stanza VALUES('NS399','chorus','Channels of life are we,<br/>Allowing God to flow!<br/>Through us and out of us<br/>That others life may know!<br/>',NULL,20796,2);
INSERT INTO stanza VALUES('NS399','2','After you receive,<br/>Are filled and enriched<br/>By such a supply,<br/>Go! Open your mouth!<br/>Speak to all men the words of this life!<br/>',NULL,20797,3);
INSERT INTO stanza VALUES('NS399','3','And having the same<br/>Spirit of faith,<br/>Be strong! Be not weak!<br/>“We also believe,<br/>Therefore we also must speak!”<br/>',NULL,20798,4);
INSERT INTO stanza VALUES('NS141','1','Since long before the world began,<br/>In Your heart You longed for a Bride;<br/>’Tis mutual dwelling, Your glorious plan;<br/>With me e’er to abide.<br/><br/>Not knowing Your heart,<br/>I sinned and thus should die;<br/>Yet You shed Your blood to set me free.<br/>You gave me Your life, to me drew nigh;<br/>Wondrous love! We two one forever will be.<br/><br/>O glorious divine love! How can I fathom,<br/>Higher than the sky, deeper than the sea;<br/>It crushes death’s pow’r and Satan’s kingdom;<br/>Nothing can compare with Your love to me<br/>So fervid and so deep, so gentle and so true;<br/>I’m in love, Lord, with You.<br/><br/>I give You my heart, my life and my soul,<br/>Come suffering or joy whatever betide.<br/>By Your boundless grace, I’ll lay down my all<br/>To build up Your church, Your glorious Bride;<br/>Your heart to satisfy, mutual abode we’ll be<br/>In eternity.<br/>',NULL,20799,1);
INSERT INTO stanza VALUES('NS142','1','In nothing be anxious,<br/>But in everything,<br/>By prayer and petition<br/>With thanksgiving,<br/>Let your requests, let your requests<br/>Be made known to God;<br/><br/>In nothing be anxious,<br/>But in everything,<br/>By prayer and petition<br/>With thanksgiving,<br/>Let your requests, let your requests<br/>Be made known to God;<br/><br/>And the peace of God,<br/>Which surpasses<br/>Every man’s understanding,<br/>Will guard your hearts<br/>Will guard your thoughts<br/>In Christ Jesus.<br/>',NULL,20800,1);
INSERT INTO stanza VALUES('NS143','1','To You, dear Lord,<br/>I give myself afresh again<br/>Unsparingly for Your desire,<br/>Your economy.<br/>',NULL,20801,1);
INSERT INTO stanza VALUES('NS143','2','O, fire from above,<br/>Come and consume me thoroughly<br/>That You may be my all,<br/>My life, my everything.<br/>',NULL,20802,2);
INSERT INTO stanza VALUES('NS143','3','It’s Your mercy and Your love<br/>That I can give myself to You.<br/>Since it’s in like manner<br/>That You gave up Yourself for me.<br/>',NULL,20803,3);
INSERT INTO stanza VALUES('NS143','4','Set Your throne in my heart<br/>From now on to the very end.<br/>It takes eternity to know its worth<br/>To You, to me.<br/>',NULL,20804,4);
INSERT INTO stanza VALUES('NS144','1','Our spirit is our organ to receive God.<br/>So every day, all the time, we must exercise,<br/>Exercise this organ to take the word.<br/>In this way, we receive life.<br/>This is the experience of life.<br/>The experience of life is just to exercise,<br/>Exercise our spirit<br/>To eat the word that we may receive life.<br/>After being received by us<br/>This life will live out all kind of<br/>Divine, spiritual, and heavenly things<br/>In an unlimited way.<br/>',NULL,20805,1);
INSERT INTO stanza VALUES('NS145','1','In my spirit, I can see You as You are.<br/>You’re the Alpha, Omega, the Bright and Morning Star.<br/>Here You’ll stay, just as a flow within<br/>To occupy my heart and spread Your life within,<br/>In my spirit! You’re all in all to me.<br/>',NULL,20806,1);
INSERT INTO stanza VALUES('NS145','chorus','In my spirit is the key,<br/>No longer need I worry right or wrong;<br/>In the church, reality—<br/>Rooted, grounded in Your plan<br/>&nbsp;&nbsp; where I belong.<br/>',NULL,20807,2);
INSERT INTO stanza VALUES('NS145','2','In my spirit, I can see You in the church;<br/>It’s Your heart’s desire, for it a people You will search.<br/>Here I’ll stay, within Your perfect will,<br/>Built up into a home, Your glory here to fill.<br/>In the church! I must no longer roam.<br/>',NULL,20808,3);
INSERT INTO stanza VALUES('NS145','3','In Your purpose, we just flow along in life.<br/>It’s so simple, no more unrest and strife.<br/>In the churches, we just enjoy You, Lord.<br/>Here You can build us up, for we’re in one accord;<br/>In the churches—we know You’ll be back soon.<br/>',NULL,20809,4);
INSERT INTO stanza VALUES('NS148','1','Just to behold You.<br/>Lord, that’s all I desire.<br/>And just to love You.<br/>Set my heart afire.<br/><br/>Just loving You and only You.<br/>Lord, You’re my goal and focus too.<br/>Lord, I love You.<br/>',NULL,20810,1);
INSERT INTO stanza VALUES('NS148','2','Just captivate me.<br/>Lord, draw me closer to You.<br/>And win me fully<br/>To run after You.<br/><br/>Just seeking You and only You.<br/>Lord, You’re my goal and focus too.<br/>Lord, I treasure You.<br/>',NULL,20811,2);
INSERT INTO stanza VALUES('NS148','3','Just to pursue You.<br/>Lord, I count all things as loss and<br/>Stretch forward to You<br/>And lay hold of You.<br/><br/>Pursuing You and only You.<br/>Lord, You’re my goal and focus too.<br/>Lord, I pursue.<br/>',NULL,20812,3);
INSERT INTO stanza VALUES('NS146','1','He who sows unto his own flesh<br/>Reaps corruption of the flesh, (trouble)<br/>He who sows unto the Spirit<br/>Will reap eternal life.<br/>',NULL,20813,1);
INSERT INTO stanza VALUES('NS146','chorus','God’s not mocked,<br/>Do not be deceived,<br/>For whatever you sow, you will reap,<br/>You will reap what you sow;<br/>Sow the life seed.<br/>',NULL,20814,2);
INSERT INTO stanza VALUES('NS146','2','Every choice is planting seeds,<br/>So be careful what you sow. (careful)<br/>Just as an apple seed,<br/>It will grow an apple tree.<br/>',NULL,20815,3);
INSERT INTO stanza VALUES('CS28','1','來與我同歡唱!<br/>我心曾經匱乏,<br/>如今尋得愛的寶藏,<br/>供應豐富無差。<br/>',NULL,21345,1);
INSERT INTO stanza VALUES('CS28','2','來與我同歡唱!<br/>我原病弱無望,<br/>喜遇救主知我景況,<br/>並賜醫治良方。<br/>',NULL,21346,2);
INSERT INTO stanza VALUES('CS28','3','來與我同歡唱!<br/>困倦疲憊如我,<br/>歡然投靠大能臂膀,<br/>加力、扶持無輟。<br/>',NULL,21347,3);
INSERT INTO stanza VALUES('CS28','4','來與我同歡唱!<br/>我原偏行己路,<br/>今由慈牧領回身旁,<br/>祂裏安然居住。<br/>',NULL,21348,4);
INSERT INTO stanza VALUES('CS28','5','來與我同歡唱!<br/>孤獨乖僻如我,<br/>竟得一友知我心腸,<br/>用愛將我緊握。<br/>',NULL,21349,5);
INSERT INTO stanza VALUES('CS28','6','從前未識祂愛,<br/>但祂早已愛上;<br/>這愛深厚、堅定、<br/>實在,既溫柔又堅剛。<br/>',NULL,21350,6);
INSERT INTO stanza VALUES('CS28','7','我樂聽祂慈聲,<br/>引我日日向上;<br/>祂愛既是如此豐盛,<br/>我豈能不歡唱?<br/>',NULL,21351,7);
INSERT INTO stanza VALUES('CS29','1','歷代聖徒都頌讚:<br/>“美哉,神的羔羊!<br/>捨命救人脫罪孽,<br/>將人罪債清償。<br/>救贖大恩多人識,<br/>卻鮮有人歌唱:<br/>“爭戰獅子已得捷,<br/>配得永遠稱揚!<br/>',NULL,21352,1);
INSERT INTO stanza VALUES('CS29','2','坐寶座者右手中,<br/>書卷七印封嚴;<br/>”天上、地下、地底下,<br/>誰配展開書卷?<br/>約翰以為無人配,<br/>為此痛哭掩面;<br/>奧祕若真不得啟,<br/>我們能不悲歎?<br/>',NULL,21353,2);
INSERT INTO stanza VALUES('CS29','3','宇宙奧祕深難測,<br/>須藉啟示照明;<br/>神的旨意若不彰,<br/>萬有都歸虛空。<br/>看哪,猶大的獅子!<br/>祂已爭戰得勝,<br/>配展書卷揭七印,<br/>將神經綸完成。<br/>',NULL,21354,3);
INSERT INTO stanza VALUES('CS29','4','前在暗中無亮光,<br/>未識神心祕密;<br/>今蒙光照,心眼開,<br/>異象輝煌無比;<br/>只願活著為神旨,<br/>此心堅定不移;<br/>“獅子羔羊”揭奧祕,<br/>我們讚美不已!<br/>',NULL,21355,4);
INSERT INTO stanza VALUES('CS29','5','長老、活物齊俯伏,<br/>座前敬拜歌唱;<br/>讚美晝夜不歇息,<br/>都歸“獅子羔羊”<br/>我們和聲同響應,<br/>高聲歡呼頌揚:<br/>神聖計畫已顯明,<br/>讚美“獅子羔羊”!<br/>',NULL,21356,5);
INSERT INTO stanza VALUES('CS30','1','耶和華對我主說,<br/>“你坐在我右邊,<br/>等我使你眾仇敵<br/>作腳凳伏你前。”<br/>耶和華必從錫安<br/>伸出你大能仗:<br/>列國必歸你管治,<br/>直到永世無疆。<br/>',NULL,21357,1);
INSERT INTO stanza VALUES('CS30','2','當你爭戰的日子,<br/>你民獻上自己;<br/>甘心奉獻為彩飾,<br/>榮美有何能比!<br/>暢爽、滋潤如甘露,<br/>新鮮,孕於清晨,<br/>少年人分別歸你,<br/>於你如寶如珍。<br/>',NULL,21358,2);
INSERT INTO stanza VALUES('CS30','3','耶和華必不後悔,<br/>祂已明確起誓:<br/>“照麥基洗德等次,<br/>你必永為祭司。<br/>你既無時日之始,<br/>也無生命之終;<br/>憑你代求供聖職,<br/>我們受恩無窮。<br/>',NULL,21359,3);
INSERT INTO stanza VALUES('CS30','4','在神右邊你是主,<br/>列邦受你審判;<br/>當你發怒傷列王,<br/>敵權盡都潰散。<br/>路旁河水供你飲,<br/>你必抬頭勝敵;<br/>我們如此解你渴,<br/>同你收復全地。<br/>',NULL,21360,4);
INSERT INTO stanza VALUES('CS30','5','哦主,你已升高天,<br/>登極安坐神右;<br/>神已使你將敵剿,<br/>萬有之上居首。<br/>你是君王施權柄,<br/>又是祭司代求,<br/>且是榮耀得勝者,<br/>配得我們所有。<br/>',NULL,21361,5);
INSERT INTO stanza VALUES('CS31','1','哦主,你是平安祭,<br/>我們按手於你;<br/>你的事實我經歷,<br/>因為你我是一。<br/>眾聖歡聚會幕裏,<br/>以你向神獻祭;<br/>同父喫喝享受你,<br/>豐富有何能比。<br/>',NULL,21362,1);
INSERT INTO stanza VALUES('CS31','chorus','讚美基督是平安祭,<br/>使神與人滿意;<br/>距離全去,交通甜蜜,<br/>平安永遠堅立!<br/>',NULL,21363,2);
INSERT INTO stanza VALUES('CS31','2','血灑於壇何有能,<br/>神聖平安得成;<br/>寶血功效永堅定,<br/>神前我享安寧。<br/>我們放膽齊頌稱<br/>“和平藉血己成!”<br/>仇敵聞之驚又恐,<br/>我們昂然誇勝。<br/>',NULL,21364,3);
INSERT INTO stanza VALUES('CS31','3','燔祭馨香使神喜,<br/>素祭叫人滿意,<br/>據此再獻平安祭─<br/>全是基督自己。<br/>救主人性何柔細,<br/>我們喫喝不已;<br/>如此享受真可喜,<br/>每逢我們聚集。<br/>',NULL,21365,4);
INSERT INTO stanza VALUES('CS31','chorus','交通何美筵席何富,<br/>神人同得飽足!<br/>喜樂盈盈,平安處處,<br/>聖民怎不歡呼!<br/>',NULL,21366,5);
INSERT INTO stanza VALUES('CS31','4','內臟、脂油最甘美,<br/>當先歸神回味;<br/>搖祭的胸何寶貝,<br/>全體祭司受惠;<br/>無酵餅同舉祭腿,<br/>純全有能寶貴,<br/>供職祭司受無愧,<br/>福分拔尖全備。<br/>',NULL,21367,6);
INSERT INTO stanza VALUES('CS31','chorus','讚美基督是平安祭,<br/>使神與人滿足!<br/>喜樂盈盈,平安處處,<br/>聖民怎不歡呼!<br/>',NULL,21368,7);
INSERT INTO stanza VALUES('CS31','5','胸作搖祭何豐富,<br/>豫表復活基督,<br/>以愛圍繞且照護,<br/>使我超越脫俗。<br/>腿作舉祭何充足,<br/>描繪升天救主,<br/>使我有能歷世途,<br/>活出他命無誤。<br/>',NULL,21369,8);
INSERT INTO stanza VALUES('CS31','6','得潔眾聖聚一堂,<br/>基督愛筵飽嘗;<br/>如此享受真無雙,<br/>帶來交通無量。<br/>心存感恩來歌唱,<br/>因主恩典深廣;<br/>為使主旨得顯彰,<br/>願將全人獻上。<br/>',NULL,21370,10);
INSERT INTO stanza VALUES('CS32','1','基督在地生活超凡且佳美,<br/>祂是神、人調和,價值何寶貴;<br/>態度、揀選、喜悅全與神相合─<br/>惟祂是那配住神的帳幕者。<br/>',NULL,21371,1);
INSERT INTO stanza VALUES('CS32','2','“神,求你保守我,因我投靠你”─<br/>無論起何風暴,祂安居神裏。<br/>“你是我主我神,我一切好處”─<br/>惟神是祂心中朝夕所思慕。<br/>',NULL,21372,2);
INSERT INTO stanza VALUES('CS32','3','“論到地上聖民,尊高又可悅,”<br/>屬神子民祂心最喜愛、關切,<br/>祂親臨地服事且照護殷殷,<br/>如四福音書中所記述顯明。<br/>',NULL,21373,3);
INSERT INTO stanza VALUES('CS32','4','“神外別有揀選,愁苦必加增”─<br/>耶穌在地生活與偶像無分。<br/>神外任何名號一概都不題,<br/>祂的追求、想望全是神自己。<br/>',NULL,21374,4);
INSERT INTO stanza VALUES('CS32','5','“惟你是我產業,是我杯中分”─<br/>祂在一切事上只揀選父神。<br/>“那指教我的神,我晝夜稱頌”─<br/>祂己全然棄絕,只活出神命。<br/>',NULL,21375,5);
INSERT INTO stanza VALUES('CS32','6','因此祂心喜樂,祂靈也歡騰,<br/>甚至被置死地仍能讚美神;<br/>神必不將祂魂撇棄在陰間,<br/>祂的肉身安居,復活顯神前。<br/>',NULL,21376,6);
INSERT INTO stanza VALUES('CS32','7','神已使祂復起,賜祂榮耀冕,<br/>祂在神前所得喜樂何豐滿。<br/>高升遠超萬有,父右邊安坐,<br/>享受無窮無盡無終的福樂。<br/>',NULL,21377,7);
INSERT INTO stanza VALUES('CS33','1','主耶和華永是我牧者，<br/>使我躺臥，令我喜樂；<br/>祂領我在可安歇水邊，<br/>何等滿足，何等甘甜！<br/>',NULL,21378,1);
INSERT INTO stanza VALUES('CS33','chorus','我一生一世必有恩惠慈愛隨著我，<br/>必有恩惠慈愛隨著我。<br/>我一生一世必有恩惠慈愛隨著我，<br/>必有恩惠慈愛隨著我。<br/>我且要住在神的殿中，直到永遠，<br/>享受祂為我擺設的筵席。<br/>我一生一世必有恩惠慈愛隨著我，<br/>必有恩惠慈愛隨著我。<br/>',NULL,21379,2);
INSERT INTO stanza VALUES('CS33','2','我的牧者是我青草地，<br/>也是流水 使我安息；<br/>我在靈中享受祂豐富，<br/>吃喝祂哦！何等蒙福！<br/>',NULL,21380,3);
INSERT INTO stanza VALUES('CS33','3','我的牧者使我魂甦醒，<br/>行走義路，隨祂引領；<br/>我雖行過死蔭的幽谷，<br/>有祂同在，我能安渡。<br/>',NULL,21381,4);
INSERT INTO stanza VALUES('CS33','4','祂在敵前為我設筵席，<br/>在筵席間 擊敗仇敵，<br/>豐厚膏油祂抹我頭上，<br/>我的福杯 滿溢流淌。<br/>',NULL,21382,5);
INSERT INTO stanza VALUES('CS33','5','我今安住在我神殿裏，<br/>享受神的 美善不已；<br/>我的喜樂非口舌能述，<br/>因主自己 是我滿足。<br/>',NULL,21383,6);
INSERT INTO stanza VALUES('CS34','1','來向基督讚美歌頌,<br/>神使救恩藉祂成功;<br/>得救惟靠神聖生命,<br/>律法規條一無所成;<br/>人雖努力不能得勝,<br/>神聖生命纔有大能;<br/>將人改變帶來重生。<br/>',NULL,21384,1);
INSERT INTO stanza VALUES('CS34','2','藉祂賜下生命能力,<br/>祂將信徒整救到底;<br/>神聖生命注入人裏,<br/>供應救恩時刻不息;<br/>人雖失喪祂來臨及,<br/>拯救罪人脫離仇敵;<br/>帶領眾子進榮耀裏。<br/>',NULL,21385,2);
INSERT INTO stanza VALUES('CS34','3','祂是祭司為神所立,<br/>賜人生命帶來實際;<br/>神的生命就在祂裏,<br/>拯救世人脫罪勝己;<br/>永遠生命不朽不已,<br/>所施救恩全備無比;<br/>讚美我主完全能力。<br/>',NULL,21386,3);
INSERT INTO stanza VALUES('CS34','4','祂的生命足能擔保,<br/>帶領我們達到榮耀;<br/>若非祂曾得勝宣告,<br/>我們有何可以信靠。<br/>祂受試驗屹立不搖,<br/>終於十架始於馬槽;<br/>不受死亡陰間纏繞。<br/>',NULL,21387,4);
INSERT INTO stanza VALUES('CS34','5','祂作憑質供人接受,<br/>擔保信徒完全得救;<br/>全備供應包羅萬有,<br/>親自成全終能成就;<br/>屬人生命失敗、老舊,<br/>惟祂生命堅定永久;<br/>祂作生命完全拯救。<br/>',NULL,21388,5);
INSERT INTO stanza VALUES('CS34','6','基督今日高過諸天,<br/>忠信代求直到永遠;<br/>不受輭弱、死亡阻攔,<br/>祭司職分無需更換;<br/>長遠活著,立於神前,<br/>代求滿足神、人心願;<br/>祂已高升遠超諸天。<br/>',NULL,21389,6);
INSERT INTO stanza VALUES('CS34','7','來到神前,靠主寶血,<br/>絶不退縮而遭毁壞;<br/>來到神前,得著生命,<br/>各盡功用不作嬰孩;<br/>來到神前,享受生命,<br/>作祂子民,蒙祂所愛;<br/>生命作王,死亡不在。<br/>',NULL,21390,7);
INSERT INTO stanza VALUES('CS35','1','萬軍之耶和華阿,<br/>你的居所何等可愛!<br/>住在你殿中真有福;<br/>他們仍要讚美你。<br/>因你有力量,心中想往<br/>錫安大道,便為有福。<br/>流淚谷變泉源之地;<br/>秋雨之福,蓋滿這谷。<br/>行走力上加力,<br/>到錫安朝見我主神。<br/>求你垂顧我們盾牌;<br/>觀看受膏者面。<br/>在你的院宇住一日,<br/>勝似在別處住千日;<br/>願常在你殿享受你<br/>所賜恩典和榮耀。<br/>',NULL,21391,1);
INSERT INTO stanza VALUES('CS36','1','你將我們的罪孽擺在你面前,<br/>將我們隱藏的罪擺在你面光之中。<br/>我們經過的日子,都在你盛怒之中;<br/>我們度盡的年歲,好像一聲歎息。<br/>我們一生的年日是七十歲,<br/>若是強壯可到八十歲;<br/>但其中所矜誇不過是勞苦愁煩,<br/>轉眼成空,我們便如飛而去。<br/>求你指教我們怎樣數算自己的日子,<br/>好叫我們得著智慧的心,得著智慧的心。<br/>求你使我們在早晨飽得你的慈愛,<br/>好叫我們一生歡呼喜樂,一生歡呼喜樂!<br/>求你照著你使我們受苦的日子,<br/>照著我們遭難的年歲,<br/>叫我們喜樂,叫我們喜樂。<br/>',NULL,21392,1);
INSERT INTO stanza VALUES('CS37','1','當向萬有之主高聲來頌揚;<br/>祂作為奇妙,當傳佈四方;<br/>諸天是祂座位,祂竟臨地上,<br/>與百姓同住,在撒冷為王。<br/>從錫安而出,救恩何深廣;<br/>被擄者歸回,怎能不歌唱?<br/>當喜樂歡騰,唱祂恩無量!<br/>當喜樂歡騰,唱祂恩無量!<br/>',NULL,21393,1);
INSERT INTO stanza VALUES('CS37','2','聖城為祂居所,聖民同歡唱;<br/>主名何尊大,全地當稱揚;<br/>讚美為祂寶座,歡呼應明朗;<br/>祂獨愛錫安,傾福於其上。<br/>在地方召會,神行動剛強;<br/>享祂作永分,滿足又歡暢;<br/>產業何豐富,我們竟得享!<br/>產業何豐富,我們竟得享!<br/>',NULL,21394,2);
INSERT INTO stanza VALUES('CS37','3','誰能登上聖山,國權來執掌?<br/>誰能住聖所,使神家顯彰?<br/>必須手潔心清,尋求主面光,<br/>迎接祂進來,居衷作君王。<br/>讓我們抬頭,尋求主面光,<br/>向榮耀君王,心門全開放;<br/>讓基督進來,居衷永作王;<br/>讓基督進來,居衷永作王。<br/>',NULL,21395,3);
INSERT INTO stanza VALUES('CS37','4','看哪神的帳幕降臨在地上;<br/>哦以馬內利!”眾聖齊歌唱。<br/>一切都已完成,神人永同享;<br/>基督與召會─美妙的詩章!<br/>眾城要抬頭,注目主榮光!<br/>門戶要舉起,迎祂來作王!<br/>讚美榮耀王,歡呼聲要強!<br/>讚美榮耀王,歡呼聲要強!<br/>',NULL,21396,4);
INSERT INTO stanza VALUES('CS138','1','“我必叫雨按時落下;<br/>那必是賜福的雨”─<br/>立約的神堅定應許,<br/>藉主救贖而賜與。<br/>',NULL,21397,1);
INSERT INTO stanza VALUES('CS138','chorus','哦,賜福的雨,<br/>我們同心所渴求;<br/>處處滴落盡是憐憫,<br/>哦求恩雨來澆透。<br/>',NULL,21398,2);
INSERT INTO stanza VALUES('CS138','2','賜福的雨必然降臨,<br/>帶來生命的復興;<br/>寶貴甘霖滋潤大地,<br/>山谷中沛雨充盈。<br/>',NULL,21399,3);
INSERT INTO stanza VALUES('CS138','3','賜福的雨必然降臨,<br/>因主應許不落空;<br/>主命這雨按時落下,<br/>使我們不感力窮!<br/>',NULL,21400,4);
INSERT INTO stanza VALUES('CS138','4','賜福的雨必然降臨,<br/>願主應許今成就;<br/>主必向祂子民仰臉,<br/>當我們同心呼求。<br/>',NULL,21401,5);
INSERT INTO stanza VALUES('CS138','5','賜福的雨必然降臨,<br/>若人肯相信順從;<br/>舒爽時期就要來到,<br/>若人願讓神流通。<br/>',NULL,21402,6);
INSERT INTO stanza VALUES('CS139','1','沒藥與香肉桂,香菖蒲與桂皮─<br/>你成分何包羅,耶穌我主!<br/>橄欖油中相調,分量完整奇妙─<br/>寶貴膏油塗抹,供應豐富!<br/>香料加上油,四調和於一,<br/>終成複合之靈;<br/>基督之 死甜美, 基督復活馨香,<br/>複合成為膏油,流進我靈!<br/>',NULL,21403,1);
INSERT INTO stanza VALUES('CS139','2','蘇合香與香螺,白松香與乳香─<br/>你成分何包羅,耶穌我主!<br/>生命產生眾子,救贖使罪脫落,<br/>驅逐死亡鬼魔,功效全足!<br/>分量各相等,復活裏調和,<br/>加鹽製成香物;<br/>搗細置 於櫃前, 供神聖火焚燒,<br/>至純至聖之香,耶穌我主!<br/>',NULL,21404,2);
INSERT INTO stanza VALUES('CS139','3','膏油是為我們,馨香完全為神,<br/>人神同享基督,榮耀豐富!<br/>膏油流至我們,帶來福分全備,<br/>馨香升達寶座,使神滿足!<br/>先塗抹膏油,後焚燒馨香,<br/>如此經歷基督;<br/>禱告讚 美高舉, 出自我們經歷,<br/>珍貴蒙神悅納─全是基督!<br/>',NULL,21405,3);
INSERT INTO stanza VALUES('CS140','1','出於聖靈,由靈而生─<br/>神人耶穌何神聖;<br/>充滿那靈,全是那靈─<br/>祂的素質就是靈。<br/>死而復活,成為那靈,<br/>如今主就是那靈;<br/>是靈在靈、憑靈眷臨,<br/>我們與祂成一靈。<br/>',NULL,21406,1);
INSERT INTO stanza VALUES('CS140','2','我們受浸歸入聖靈,<br/>浸於靈中,飲於靈;<br/>召會全然出於那靈,<br/>宗教、規條盡除摒。<br/>活在靈裏,照靈而行,<br/>信條、儀文勿倚憑;<br/>召會實際全在於靈,<br/>故當操練活靈中。<br/>',NULL,21407,2);
INSERT INTO stanza VALUES('CS140','3','在此所享神聖交通,<br/>乃是那靈的交通;<br/>我們所顧惟有那靈,<br/>此外無何可依從。<br/>那靈今已加強七倍,<br/>神聖經綸來完成;<br/>眾召會中,那靈發聲,<br/>凡有耳者當聆聽。<br/>',NULL,21408,3);
INSERT INTO stanza VALUES('CS140','4','來罷!那靈、新婦呼召:<br/>“生命活水可白喝!”<br/>召會那靈發聲如一─<br/>終極、完滿的聯合。<br/>今日務要實際操練,<br/>“照靈而行”為原則;<br/>眾召會中惟有那靈,<br/>是主恢復的獨特。<br/>',NULL,21409,4);
INSERT INTO stanza VALUES('CS141','1','神在基督耶穌裏成那靈，<br/>流入我們靈裏作生命；<br/>何等的享受，三一奇妙人位，<br/>來作生命全足又全豐。<br/>',NULL,21410,1);
INSERT INTO stanza VALUES('CS141','2','祂是活神，我們向祂敞開，<br/>由祂所生，經歷何實在；<br/>美妙的重生！神將我們充滿，<br/>藉祂生命不斷流進來。<br/>',NULL,21411,2);
INSERT INTO stanza VALUES('CS141','3','祂是活靈住在我們靈裡，<br/>向外湧流，分賜祂自己；<br/>在我們心間，祂正擴展不已，<br/>逐步變化，成就祂美意。<br/>',NULL,21412,3);
INSERT INTO stanza VALUES('CS141','4','哦，讓我們配合裏面的主，<br/>目標專一，只思念基督；<br/>時刻轉向祂，離棄打岔事物，<br/>除祂以外，心別無所屬。<br/>',NULL,21413,4);
INSERT INTO stanza VALUES('CS141','5','我們不僅靈中將主盛裝，<br/>更要讓祂定旨得開廣；<br/>丟棄老觀念，不再心思流蕩，<br/>生命平安我們可得享。<br/>',NULL,21414,5);
INSERT INTO stanza VALUES('CS141','6','哦主，得著我們每一思想，<br/>在你話中不斷得滋養；<br/>藉你話供應，心思常置於靈，<br/>就得聖別，模成你形像。<br/>',NULL,21415,6);
INSERT INTO stanza VALUES('CS141','7','我們同來經歷生命之神，<br/>思念那靈，操練當認真；<br/>何等的實際！憑祂而活有路！<br/>主，我們心與你永不分。<br/>',NULL,21416,7);
INSERT INTO stanza VALUES('CS142','1','我神乃是澎湃水流,<br/>歷世歷代湧流不休;<br/>種種過程祂已盡歷,<br/>為要流進卑微人裏。<br/>獨一、不變活神,為要作人永分,<br/>祂竟親臨人間,歷經多方變遷,<br/>現今湧流我們裏面!<br/>',NULL,21417,1);
INSERT INTO stanza VALUES('CS142','2','在那起初樂園之中<br/>神已流出,滿帶豐盛;<br/>祂是水河,又是果樹,<br/>分賜生命,作人永福。<br/>這河湧流不息,直至永世無已;<br/>神在羔羊裏流,樹果供應豐厚,<br/>神聖分賜無盡、悠久!<br/>',NULL,21418,2);
INSERT INTO stanza VALUES('CS142','3','看哪那人耶穌基督,<br/>是神流出與人同處;<br/>為人捨命,成功救贖,<br/>為將神聖生命釋出。<br/>撒但詭計多端,要將水流阻斷;<br/>豈知祂釘十架,兵丁扎祂肋下,<br/>不過引出血、水無價!<br/>',NULL,21419,3);
INSERT INTO stanza VALUES('CS142','4','哦,血與水從祂而出,<br/>救恩泉源湧流不住;<br/>寶血洗罪永遠有能,<br/>生命之水使人重生。<br/>如今那靈流通─是神流入人中;<br/>仇敵伎倆依舊;不過助長水流,<br/>我神湧流無止、無休!<br/>',NULL,21420,4);
INSERT INTO stanza VALUES('CS143','1','看哪,暴風颳自北方,力無窮;<br/>來吹動!來吹動!<br/>是神眷臨使人翻轉得復興;<br/>來吹動!來吹動!<br/>',NULL,21421,1);
INSERT INTO stanza VALUES('CS143','chorus','來吹動!聖靈強風吹動,<br/>使我悔改得生命!<br/>來吹動!恩典大風吹動,<br/>使我主裏得復興!<br/>',NULL,21422,2);
INSERT INTO stanza VALUES('CS143','2','看哪,還有一朵大雲隨風到;<br/>來覆罩!來覆罩!<br/>主同在如雲滿足所有需要;<br/>來覆罩!來覆罩!<br/>',NULL,21423,3);
INSERT INTO stanza VALUES('CS143','chorus','來覆罩!神來與人相交,<br/>覆庇、加力又照料!<br/>來覆罩!神恩如雲圍繞,<br/>帶來安慰和榮耀!<br/>',NULL,21424,4);
INSERT INTO stanza VALUES('CS143','3','雲中又有烈火不斷的閃爍;<br/>來焚燒!來焚燒!<br/>罪肉體魂生命再無處可躲;<br/>來焚燒!來焚燒!<br/>',NULL,21425,5);
INSERT INTO stanza VALUES('CS143','chorus','來焚燒!神聖嫉妒烈火<br/>燒遍全人每角落!<br/>來焚燒!神外一切盡脫,<br/>天然、舊造都滅沒!<br/>',NULL,21426,6);
INSERT INTO stanza VALUES('CS143','4','火中發出金銀合金顯光耀;<br/>在顯耀!在顯耀!<br/>救贖之神經歷寶貴又高超;<br/>在顯耀!在顯耀!<br/>',NULL,21427,7);
INSERT INTO stanza VALUES('CS143','chorus','在顯耀!我們今已嘗到<br/>羔羊神豐美味道!<br/>在顯耀!救贖之神榮耀,<br/>彰顯於人何奇妙!<br/>',NULL,21428,8);
INSERT INTO stanza VALUES('CS143','5','風雲、火金的經歷將人點活;<br/>多又多!多又多!<br/>願這循環將我重構永不輟;<br/>多又多!多又多!<br/>',NULL,21429,9);
INSERT INTO stanza VALUES('CS143','chorus','風吹到!雲覆罩!火焚燒!<br/>金銀合金顯榮耀!<br/>願與主如此全然相調,<br/>使主榮形得顯照!<br/>',NULL,21430,10);
INSERT INTO stanza VALUES('CS144','1','你若要脫離天然與自己,<br/>阿們生命之律!<br/>讓這律自動運行在你裏,<br/>阿們生命之律!<br/>阿們生命之律!阿們生命之律!<br/>如此被變化,與主像無異,<br/>阿們生命之律!<br/>',NULL,21431,1);
INSERT INTO stanza VALUES('CS144','2','這律是出自神聖的生命,<br/>阿們生命之律!<br/>憑生命大能自然的運行,<br/>阿們生命之律!<br/>阿們生命之律!阿們生命之律!<br/>生命是憑倚,掙扎可全停,<br/>阿們生命之律!<br/>',NULL,21432,2);
INSERT INTO stanza VALUES('CS144','3','生命之律能成全神心意,<br/>阿們生命之律!<br/>切勿憑己力改良你自己,<br/>阿們生命之律!<br/>阿們生命之律!阿們生命之律!<br/>主我願配合,成就你所期,<br/>阿們生命之律!<br/>',NULL,21433,3);
INSERT INTO stanza VALUES('CS144','4','生命律帶來生機的變化,<br/>阿們生命之律!<br/>將我們構成身體主所誇,<br/>阿們生命之律!<br/>阿們生命之律!阿們生命之律!<br/>舊人漸消減,神生命添加,<br/>阿們生命之律!<br/>',NULL,21434,4);
INSERT INTO stanza VALUES('CS144','5','這律將基督銘刻在我心,<br/>阿們生命之律!<br/>直至祂充滿內裏各部分,<br/>阿們生命之律!<br/>阿們生命之律!阿們生命之律!<br/>讓基督成形,非外在教訓,<br/>阿們生命之律!<br/>',NULL,21435,5);
INSERT INTO stanza VALUES('CS145','1','基督要從我靈深處<br/>向外擴展並征服─<br/>心思、情感、意志各部,<br/>盡都充滿祂豐富。<br/>基督作王,悖逆全除,<br/>黑暗盡去,光顯露;<br/>生命吞滅死亡、陰府,<br/>撒但國度再無處。<br/>這是得勝主的恢復,<br/>上好!我們齊歡呼!<br/>當將主權完全歸主,<br/>直至國度全顯出。<br/>',NULL,21436,1);
INSERT INTO stanza VALUES('CS146','1','哦主你在復活裏,<br/>已成賜生命之靈;<br/>使我與你同復起,<br/>使我重生得生命。<br/>',NULL,21437,1);
INSERT INTO stanza VALUES('CS146','2','這靈就是你進入,<br/>帶著豐盛的生命;<br/>包羅萬有的豐富,<br/>作我全備的供應。<br/>',NULL,21438,2);
INSERT INTO stanza VALUES('CS146','3','如今這靈已內住,<br/>在你無數肢體裏;<br/>我們與你得聯屬,<br/>我們活著就是你。<br/>',NULL,21439,3);
INSERT INTO stanza VALUES('CS146','4','憑靈全備的供應,<br/>我們將你來活出;<br/>成為你的活見證,<br/>成為團體的基督。<br/>',NULL,21440,4);
INSERT INTO stanza VALUES('CS146','5','藉著你靈的率領,<br/>見證向外能普及;<br/>我們是你見證人,<br/>將你傳揚到地極。<br/>',NULL,21441,5);
INSERT INTO stanza VALUES('CS146','6','如此擴展這見證,<br/>達到終極的完成;<br/>乃是新耶路撒冷,<br/>永遠豐滿無止境。<br/>',NULL,21442,6);
INSERT INTO stanza VALUES('CS147','1','我神如今你已成那靈,<br/>藉你話語實化我靈裏;<br/>運用我靈來接觸你話,<br/>話中之靈我就能經歷。<br/>',NULL,21443,1);
INSERT INTO stanza VALUES('CS147','chorus','主阿!你話離我並不遠,<br/>在我口裏也在我心裏,<br/>你靈藉話來作你實際,<br/>你我聯調合併永為一。<br/>',NULL,21444,2);
INSERT INTO stanza VALUES('CS147','2','你之所是及一切屬性,<br/>全都具體實化基督裏;<br/>我享你靈、你話、你自己,<br/>經歷中作我愛光聖義。<br/>',NULL,21445,3);
INSERT INTO stanza VALUES('CS147','3','住你話裏就是住你裏,<br/>我在愛裏藉話享受你;<br/>你住我裏與我成為一,<br/>我活出你,彰顯你祕密。<br/>',NULL,21446,4);
INSERT INTO stanza VALUES('CS148','1','子同著父並憑著靈而來,<br/>哦這是何等奧祕!<br/>神格一切的豐滿都有形<br/>有體住在祂裏。<br/>',NULL,21447,1);
INSERT INTO stanza VALUES('CS148','chorus','子同著父,<br/>祂何等奇妙!<br/>子憑著靈,<br/>祂何等高超!<br/>耶穌基督至寶,<br/>三一何深奧,<br/>三一神何奇妙!<br/>',NULL,21448,2);
INSERT INTO stanza VALUES('CS148','2','子同著父並憑著靈而來,<br/>由童女懷孕所生;<br/>耶穌基督奇妙的神人,<br/>在他,神、人成一身。<br/>',NULL,21449,3);
INSERT INTO stanza VALUES('CS148','3','祂的生活將父完全彰顯,<br/>是人卻憑神生命;<br/>祂是神無罪羔羊,<br/>罪、世界、撒但不能得逞。<br/>',NULL,21450,4);
INSERT INTO stanza VALUES('CS148','chorus','在人性裏,<br/>來救贖洗淨;<br/>在神性裏,<br/>作救恩保證。<br/>祂血將我洗淨,<br/>祂又作保證─<br/>神今是我保證。<br/>',NULL,21451,5);
INSERT INTO stanza VALUES('CS148','4','祂雖無罪卻有分血肉之體,<br/>這使撒但中計;<br/>肉體罪撒但<br/>與祂同釘一起,<br/>哦何等清理!<br/>',NULL,21452,6);
INSERT INTO stanza VALUES('CS148','chorus','祂已了結<br/>舊造眾仇敵!<br/>祂已廢掉<br/>罪、撒但、肉體!<br/>哦應許的後裔,<br/>祂毁壞古蛇,<br/>勝過魔鬼詭計。<br/>',NULL,21453,7);
INSERT INTO stanza VALUES('CS148','5','在基督的復活裏,<br/>這位奇妙三一成為那靈;<br/>如今三一之神己成那靈,<br/>作祂終極完成。<br/>',NULL,21454,8);
INSERT INTO stanza VALUES('CS148','chorus','何親何近,<br/>賜生命的靈!<br/>三一之神<br/>己終極完成。<br/>子與父是一靈,<br/>祂成為那靈,<br/>今內住於我靈。<br/>',NULL,21455,9);
INSERT INTO stanza VALUES('CS148','6','這奇妙人子在升天裏,<br/>仍是一人在神右邊;<br/>神已將人子升高至極,<br/>使祂作王並掌權。<br/>',NULL,21456,10);
INSERT INTO stanza VALUES('CS148','chorus','萬主之主,<br/>是王中之王;<br/>基督耶穌,<br/>遠超萬名上;<br/>祂登寶座為王,<br/>至高寶座上,<br/>得榮人子為王。<br/>',NULL,21457,11);
INSERT INTO stanza VALUES('CS148','7','經過種種過程,主今已登<br/>寶座,萬有祂治理;<br/>作生命之靈分賜給人,<br/>接受產生祂身體。<br/>',NULL,21458,12);
INSERT INTO stanza VALUES('CS148','chorus','神是三一,<br/>不是為道理;<br/>神是三一,<br/>分賜祂自己。<br/>分賜永不停息,<br/>我們可經歷,<br/>盡享祂的自己。<br/>',NULL,21459,13);
INSERT INTO stanza VALUES('CS149','1','在創世之前,神就豫定了我們,<br/>按祂所喜悅,來得兒子的名分;<br/>及至時候滿足,神就差出祂兒子,<br/>由女子所生,為贖我們竟受死;<br/>並且神又差出祂兒子的靈,<br/>帶來生機救恩,進入我們的心。<br/>',NULL,21460,1);
INSERT INTO stanza VALUES('CS149','chorus','何其甜美而親密,<br/>同靈呼叫阿爸,父!<br/>真實主觀的經歷<br/>兒子名分的豐富。<br/>',NULL,21461,2);
INSERT INTO stanza VALUES('CS150','1','靈裡貧窮的人有福了,<br/>因為諸天的國是他們的。<br/>哀慟的人有福了,<br/>因為他們必得安慰。<br/>溫柔的人有福了,<br/>因為他們必承受地土。<br/>飢渴慕義的人有福了,<br/>因為他們必得飽足。<br/>憐憫人的人有福了,<br/>因為他們必蒙憐憫。<br/>清心的人有福了,<br/>因為他們必看見神。<br/>製造和平的人有福了,<br/>因為他們必稱為神的兒子。<br/>為義受逼迫的人有福了,<br/>因為諸天的國是他們的。<br/>',NULL,21462,1);
INSERT INTO stanza VALUES('CS248','1','興起!我魂,興起!<br/>擺脫懼怕蒙蔽;<br/>救主流血作祭,<br/>神前我蒙稱義。<br/>寶座之前擔保確立,<br/>我得安穩在神手裏,<br/>我得安穩在神手裏。<br/>',NULL,21463,1);
INSERT INTO stanza VALUES('CS248','2','救主活到永久,<br/>在天為我代求;<br/>祂愛贖回萬有,<br/>祂血滿足要求;<br/>為救萬族、萬民而流,<br/>施恩座前功效不朽,<br/>施恩座前功效不朽。<br/>',NULL,21464,2);
INSERT INTO stanza VALUES('CS248','3','加畧十字架上,<br/>手足、肋旁受創;<br/>祂行父旨不忘,<br/>代求,將罪擔當;<br/>寬容、赦免無知頂撞,<br/>蒙贖罪人免去死亡,<br/>蒙贖罪人免去死亡。<br/>',NULL,21465,3);
INSERT INTO stanza VALUES('CS248','4','禱告蒙父垂聽,<br/>受膏基督高升;<br/>救贖大功完成,<br/>父來稱許、印證;<br/>祂靈應允寶血之聲,<br/>宣告我已由神而生,<br/>宣告我已由神而生。<br/>',NULL,21466,4);
INSERT INTO stanza VALUES('CS248','5','我今與神和好,<br/>知祂赦免、寬饒;<br/>兒女將父倚靠,<br/>憂慮不再攪擾;<br/>憑信坦然進前宣告:<br/>阿爸,父阿,與你和好,<br/>阿爸,父阿,與你和好。<br/>',NULL,21467,5);
INSERT INTO stanza VALUES('CS249','1','一切變遷中有一位,<br/>永遠屹立不朽;<br/>惟祂昔是、今是、永是,<br/>包羅萬有,永久!<br/>這是基督─永久磐石,<br/>哦,祂是首先,<br/>祂也是末後。<br/>',NULL,21468,1);
INSERT INTO stanza VALUES('CS249','chorus','耶穌是首先,<br/>耶穌是末後,<br/>已往交祂擔去,<br/>將來祂保守;<br/>耶穌是首先,<br/>耶穌是末後,<br/>基督-永久磐石,<br/>首先與末後。<br/>',NULL,21469,2);
INSERT INTO stanza VALUES('CS249','2','這位用祂大能膀臂,<br/>托住宇宙萬有,<br/>但祂向人敞開胸臆,<br/>要人向祂倚投;<br/>憂疑儘可帶來歸祂,<br/>因祂是首先,<br/>祂也是末後。<br/>',NULL,21470,3);
INSERT INTO stanza VALUES('CS249','3','驚濤駭浪不過證明:<br/>祂愛永無盡頭;<br/>直到所有風波過去,<br/>祂手仍必保守;<br/>信靠耶穌絕不蒙羞,<br/>因祂是首先,<br/>祂也是末後。<br/>',NULL,21471,4);
INSERT INTO stanza VALUES('CS249','4','我們加冠至愛基督,<br/>祂是首先、末後。<br/>萬主之主,你腳凳前,<br/>冠冕都當傾投。<br/>那日快臨,萬有拜叩:<br/>惟你是首先,<br/>你也是末後。<br/>',NULL,21472,5);
INSERT INTO stanza VALUES('CS250','1','我已尋得一生命泉源,<br/>清新活泉流自高天;<br/>脫開屬地掙扎與糾纏,<br/>歡然飲於“以琳”愛泉。<br/>何等神聖屬天的活泉,<br/>在我深處湧流不斷;<br/>帶來喜樂滿足時加添,<br/>無人話語能以盡言。<br/>',NULL,21473,1);
INSERT INTO stanza VALUES('CS250','chorus','請來暢飲於活水泉源,<br/>無須代價只要你願;<br/>活水供應甘甜豐富無限,<br/>因主自己就是這泉。<br/>',NULL,21474,2);
INSERT INTO stanza VALUES('CS250','2','我今投靠於洗罪泉源,<br/>洗淨一切污穢罪愆;<br/>藉主寶血我罪得赦免,<br/>潔白如雪立於神前。<br/>蒙神稱義非憑我優點,<br/>乃因基督活我裏面;<br/>屬天性情我取用無間,<br/>在祂裏面我得完全。<br/>',NULL,21475,3);
INSERT INTO stanza VALUES('CS250','3','恩主也是我醫治泉源,<br/>作我秘訣供應無限;<br/>遠超人智慧所及所見,<br/>也非財富可以兌現。<br/>這醫治活泉神聖完全,<br/>流自救主被刺肋邊;<br/>祂受鞭傷使我得康健,<br/>又來安家在我心間。<br/>',NULL,21476,4);
INSERT INTO stanza VALUES('CS250','4','我愛暢飲於喜樂泉源,<br/>作我力量溢我心田;<br/>主是我日光輝煌燦爛,<br/>我的歡欣在祂裏面。<br/>草木榮華轉眼即凋殘,<br/>人間宴樂短似雲煙;<br/>主作我喜樂從未消減,<br/>以神為樂在地如天。<br/>',NULL,21477,5);
INSERT INTO stanza VALUES('CS251','1','在聖經開始,神已經啟示,<br/>人是按著祂形像造成;<br/>為要彰顯祂,並且代表祂,<br/>征服全地帶進祂權能。<br/>',NULL,21478,1);
INSERT INTO stanza VALUES('CS251','chorus','形像,形像─<br/>人是按著神形像造成;<br/>形像,形像─<br/>征服全地帶進祂權能。<br/>',NULL,21479,2);
INSERT INTO stanza VALUES('CS251','2','祂沒有立下任何的律法,<br/>只說園中果子隨意喫;<br/>但是善惡樹,萬不可接觸,<br/>喫了知識果子必定死。<br/>',NULL,21480,3);
INSERT INTO stanza VALUES('CS251','chorus','知識,知識─<br/>知識果子不能隨意喫;<br/>知識,知識─<br/>知識果子喫了必定死。<br/>',NULL,21481,4);
INSERT INTO stanza VALUES('CS251','3','在伊甸樂園,擺在人面前,<br/>有生命樹代表神自己;<br/>但是那毒蛇,詭詐又邪惡,<br/>藉著知識使人心偏離。<br/>',NULL,21482,5);
INSERT INTO stanza VALUES('CS251','chorus','墮落,墮落─<br/>人不幸已中了蛇的毒;<br/>墮落,墮落─<br/>人需要一個完全恢復。<br/>',NULL,21483,6);
INSERT INTO stanza VALUES('CS251','4','主耶穌基督就是生命樹,<br/>神成肉身,滿足神要求;<br/>祂救贖我們,又重生我們,<br/>現今成了我們的珍饈。<br/>',NULL,21484,7);
INSERT INTO stanza VALUES('CS251','chorus','耶穌基督─<br/>耶穌基督是我真食物;<br/>耶穌基督─<br/>喫喝享受祂就得飽足。<br/>',NULL,21485,8);
INSERT INTO stanza VALUES('CS251','5','主不是要搞我們的頭腦,<br/>知識只叫人自高自大;<br/>祂來的目的乃是作筵席,<br/>不重研究乃在喫喝祂。<br/>',NULL,21486,9);
INSERT INTO stanza VALUES('CS251','chorus','接受,接受─<br/>祂作食物,供應真充足;<br/>接受,接受─<br/>耶穌乃是我們生命樹。<br/>',NULL,21487,10);
INSERT INTO stanza VALUES('CS251','6','越多喫喝祂,越不斷長大,<br/>生命、人數必加增不已;<br/>我們要清楚神今天恢復,<br/>基督不是宗教,是筵席。<br/>',NULL,21488,11);
INSERT INTO stanza VALUES('CS251','chorus','喫祂,喫祂─<br/>越多喫祂,祂越要增多;<br/>喫祂,喫祂─<br/>喫祂的人必因祂活著。<br/>',NULL,21489,12);
INSERT INTO stanza VALUES('CS251','7','今天的道路是喫喝基督,<br/>沒有一件事比此重要;<br/>召會藉著喫,新婦得妝飾,<br/>迎接新郎帶進神榮耀。<br/>',NULL,21490,13);
INSERT INTO stanza VALUES('CS251','chorus','喫喝,喫喝─<br/>沒有一件事比此重要<br/>喫喝,喫喝─<br/>迎接新郎帶進神榮耀。<br/>',NULL,21491,14);
INSERT INTO stanza VALUES('CS252','1','神聖應許甘甜無比:<br/>人若敬畏耶和華名,<br/>必見公義日頭升起,<br/>其翼能醫罪、病。<br/>',NULL,21492,1);
INSERT INTO stanza VALUES('CS252','2','救主滿帶醫治大能,<br/>信祂名者祂必不棄;<br/>痛悔之心速來投誠,<br/>藏身醫治聖翼。<br/>',NULL,21493,2);
INSERT INTO stanza VALUES('CS252','3','公義救主如日展翅;<br/>我若糾纏罪中不離,<br/>怎能得祂撫摸、醫治,<br/>安歇於祂聖翼?<br/>',NULL,21494,3);
INSERT INTO stanza VALUES('CS252','4','妙哉祂已毁傷蛇頭,<br/>毒螫消解苦痛全去;<br/>愛的胸臆我當緊投,<br/>醫治翼下無虞。<br/>',NULL,21495,4);
INSERT INTO stanza VALUES('CS252','5','醫治翼下我得安息,<br/>滿心樂極,高歌頌稱:<br/>公義日頭今已升起,<br/>其翼能醫罪、病。<br/>',NULL,21496,5);
INSERT INTO stanza VALUES('CS253','1','基督美地,包羅萬有-<br/>祂是我的一切:<br/>源、泉、河川,清新明透,<br/>日夜湧流不歇;<br/>谷中山上流出水來,<br/>潤我心田,滿溢充盈;<br/>何等榮耀,活水澎湃─<br/>作我生命!<br/>',NULL,21497,1);
INSERT INTO stanza VALUES('CS253','2','神成肉身,忍辱受死,<br/>繁增如同小麥;<br/>死而復活,生命分賜,<br/>初熟如同大麥;<br/>無花果樹,甘甜滿足,<br/>葡萄產酒,神、人喜悅;<br/>如此供應,全在基督─<br/>有祂無缺!<br/>',NULL,21498,2);
INSERT INTO stanza VALUES('CS253','3','基督還是真石榴樹,<br/>生命豐美充足;<br/>是橄欖樹,新油產出,<br/>膏抹永不缺如;<br/>流奶與蜜,美善甘甜,<br/>供我滋養,加我能力;<br/>祂的豐富,如此完全─<br/>基督美地!<br/>',NULL,21499,3);
INSERT INTO stanza VALUES('CS253','4','在這美地不缺食物,<br/>我們一無所缺;<br/>祂是如此豐饒富庶,<br/>我們頌讚不絕;<br/>上好美地,廣大無邊,<br/>應有盡有,齊備完全;<br/>今在我心還要擴展─<br/>無量無限!<br/>',NULL,21500,4);
INSERT INTO stanza VALUES('CS253','5','這地石頭如鐵之堅,<br/>山內可以挖銅;<br/>權柄如鐵,憑以爭戰,<br/>仇敵不能得逞;<br/>再經苦難,渣滓全去,<br/>煉淨明亮,如銅顯出;<br/>有鐵有銅,應付所需─<br/>全是基督!<br/>',NULL,21501,5);
INSERT INTO stanza VALUES('CS253','6','為這美地我們頌讚:<br/>主,你何其包羅!<br/>喫喝飽足,讓你充滿,<br/>豐富豈能盡說!<br/>求使我們經營不輟,<br/>美地實際增長不已;<br/>我的喜樂,我的生活─<br/>基督美地!<br/>',NULL,21502,6);
INSERT INTO stanza VALUES('CS254','1','生活祕訣歡然尋得,<br/>神聖異象照明亮:<br/>蒙神接枝在基督裏,<br/>如同枝子住在葡萄樹上。<br/>',NULL,21503,1);
INSERT INTO stanza VALUES('CS254','chorus','讚美神使我們<br/>得住葡萄樹上,<br/>神聖生命豐富得全享!<br/>住在葡萄樹上,<br/>留此不再他往;<br/>哦,我們安住葡萄樹上!<br/>',NULL,21504,2);
INSERT INTO stanza VALUES('CS254','2','不再徒然掙扎、努力,<br/>尋求如何得進入;<br/>奇妙事實-我在主裏;<br/>奧妙聯結-葡萄樹是住處。<br/>',NULL,21505,3);
INSERT INTO stanza VALUES('CS254','3','只要住在葡萄樹上,<br/>內裏膏抹必不斷,<br/>帶來神聖寶貴素質,<br/>滋潤、浸透,時時充滿加添。<br/>',NULL,21506,4);
INSERT INTO stanza VALUES('CS254','4','如此活在生命流中,<br/>神聖之光常放明;<br/>神人互住,安息穩固,<br/>神的心意在此盡得完成。<br/>',NULL,21507,5);
INSERT INTO stanza VALUES('CS255','1','基督復活能力浩大無比,<br/>今向祂身體,正在輸供;<br/>我們藉信領受這大能力─<br/>何等神聖、奇妙輸供!<br/>浩大能力,復活的能力,<br/>向召會,在輸供!<br/>浩大能力,復活的能力,<br/>向基督身體,在輸供!<br/>',NULL,21508,1);
INSERT INTO stanza VALUES('CS255','2','浩大能力使基督得高升,<br/>遠超諸執政,坐在神右;<br/>高升遠超一切受稱之名─<br/>大能向召會在傾投!<br/>浩大能力,升天的能力,<br/>向召會,在輸供!<br/>浩大能力,升天的能力,<br/>向基督身體,在輸供!<br/>',NULL,21509,2);
INSERT INTO stanza VALUES('CS255','3','浩大能力使萬有都歸服,<br/>在基督腳下,無不歸順;<br/>如此大能正向召會傳輸,<br/>使身體與頭無可分。<br/>浩大能力,歸服的能力,<br/>向召會,在輸供!<br/>浩大能力,歸服的能力,<br/>向基督身體,在輸供!<br/>',NULL,21510,3);
INSERT INTO stanza VALUES('CS255','4','浩大能力使基督向召會,<br/>作萬有的頭,支配各方;<br/>如此大能乃向著祂召會,<br/>且要藉召會全顯彰。<br/>浩大能力,支配的能力,<br/>向召會,在輸供!<br/>浩大能力,支配的能力,<br/>向基督身體,在輸供!<br/>',NULL,21511,4);
INSERT INTO stanza VALUES('CS256','1','復活的大能,神已經顯明,<br/>使祂的兒子從死復生;<br/>因此見大能,我們得加力,<br/>復活生命裏昂然誇勝。<br/>大能大能,復活生命大能─<br/>內裏運行,時時加添能力;<br/>大能大能,復活生命大能─<br/>裏面的人時時得加力!<br/>',NULL,21512,1);
INSERT INTO stanza VALUES('CS256','2','超越的大能使基督高升,<br/>坐在神右邊,遠超萬有:<br/>執政掌權者,有能主治者,<br/>因基督大名無不拜叩。<br/>大能大能,超越一切大能─<br/>內裏運行,使人離地上騰;<br/>大能大能,超越一切大能─<br/>裏面的人離地得上騰。<br/>',NULL,21513,2);
INSERT INTO stanza VALUES('CS256','3','征服的大能使萬有歸服,<br/>悖逆盡消弭,基督為大;<br/>作祂的身體,分享祂能力,<br/>有何不踏在我們腳下?<br/>大能大能,征服一切大能─<br/>內裏運行,處處施行管治;<br/>大能大能,征服一切大能─<br/>裏面的人處處施管治。<br/>',NULL,21514,3);
INSERT INTO stanza VALUES('CS256','4','歸一的大能使基督居首,<br/>向著召會作萬有的頭;<br/>大能的輸供成功主身體,<br/>作祂的豐滿神旨成就。<br/>大能大能,掌管萬有大能─<br/>裏裏外外,一切盡都歸順;<br/>大能大能,掌管萬有大能─<br/>裏面的人率先來歸順。<br/>',NULL,21515,4);
INSERT INTO stanza VALUES('CS257','1','求主賜我啟示的靈,<br/>認識復活的大能,<br/>這大能在基督身上,<br/>運行不息時加增。<br/>不單叫祂從死復活,<br/>更叫我因祂得生;<br/>浩大能力藉信經歷,<br/>使我活在屬天層。<br/>',NULL,21516,1);
INSERT INTO stanza VALUES('CS257','2','復活乃是信徒經歷,<br/>非僅歷史一事實;<br/>墳墓雖已千年空置,<br/>復活大能仍運施。<br/>這個大能不是神學,<br/>不僅是理論而已;<br/>它使信徒天天實際,<br/>聯於復活主自己。<br/>',NULL,21517,2);
INSERT INTO stanza VALUES('CS257','3','復活帶進新造領域,<br/>使我脫離舊自我;<br/>非如拉撒路之神蹟,<br/>苟延舊造並重活。<br/>我所需要不是任何<br/>起死回生的經過,<br/>亦非任何工作能力,<br/>乃讓復活將我摸。<br/>',NULL,21518,3);
INSERT INTO stanza VALUES('CS257','4','一切死亡陰間經歷,<br/>皆為復活啟生機;<br/>生藉死亡發動運行,<br/>肉體治死靈奮起。<br/>死亡所設千萬防線,<br/>基督走過何容易;<br/>暢遊陰間樂園深淵,<br/>從未恐慌或逃離。<br/>',NULL,21519,4);
INSERT INTO stanza VALUES('CS257','5','死亡對人最大威脅,<br/>無非懼怕與捆綁;<br/>當主打破死亡門檻,<br/>粉碎限制與驚惶。<br/>天然生命不再纏擾,<br/>復活生命得顯揚;<br/>最後仇敵既被吞滅,<br/>有何能將生命擋?<br/>',NULL,21520,5);
INSERT INTO stanza VALUES('CS257','6','基督人性藉著復活,<br/>已被拔高並標出;<br/>從此墮落人類生命,<br/>可望與主同前途。<br/>經歷基督全備救恩,<br/>不僅那日體得贖,<br/>人性更被拯救、拔高,<br/>提升等同復活主。<br/>',NULL,21521,6);
INSERT INTO stanza VALUES('CS257','7','復活並不改良舊造,<br/>減輕舊造的折騰;<br/>也不加強舊造生命,<br/>使之能以自逞能。<br/>基督雖曾肉體痛哭,<br/>靈裏卻是倚靠神;<br/>復活不求改變環境,<br/>只在環境顯效能。<br/>',NULL,21522,7);
INSERT INTO stanza VALUES('CS257','8','神藉舊造產生新造,<br/>此為極大的奧祕;<br/>罪、死雖然污染肉體,<br/>經死一筆全清洗。<br/>主將伊甸所造人性,<br/>給予重整賦新機;<br/>復活原則永不改變─<br/>新造取材舊造裏。<br/>',NULL,21523,8);
INSERT INTO stanza VALUES('CS257','9','基督復活生為長子,<br/>人性拔高至神性;<br/>大衞後裔今日被生,<br/>此為真正的福音。<br/>從此人類新生有望,<br/>復活產生新族羣─<br/>同父同胎同命同性,<br/>同一源頭同命運。<br/>',NULL,21524,9);
INSERT INTO stanza VALUES('CS257','10','復活大能使我重生,<br/>得有神聖諸供備;<br/>使我有權成為兒女,<br/>從神而生屬神類─<br/>生命性情與神一樣,<br/>只與神格無分位。<br/>第一神人我們長兄,<br/>作我原型並原胚。<br/>',NULL,21525,10);
INSERT INTO stanza VALUES('CS257','11','我與基督已經聯合,<br/>祂我生命已接枝;<br/>復活生命天天交流,<br/>時時相調永無止。<br/>祂更成了賜生命靈,<br/>作神終極的顯出,<br/>帶來神性人性豐富,<br/>使我活出子基督。<br/>',NULL,21526,11);
INSERT INTO stanza VALUES('CS257','12','我們成了基督肢體,<br/>與主成為一單元;<br/>祂的經歷成我履歷,<br/>我的一切祂成全。<br/>復活早晨新生男孩,<br/>乃是宇宙新生族;<br/>這是神人互住父家,<br/>又是生機葡萄樹。<br/>',NULL,21527,12);
INSERT INTO stanza VALUES('CS257','13','復活實際-生命之靈,<br/>今已住在我靈中;<br/>使我天天經歷復活,<br/>與我同活同行動;<br/>永遠勝過罪與死律,<br/>作王生命來居衷;<br/>最終漫溢必死身體,<br/>使我賤身與祂同。<br/>',NULL,21528,13);
INSERT INTO stanza VALUES('CS257','14','在復活裏與祂同長,<br/>活出生命的新樣,<br/>一舉一動結出義果,<br/>主觀稱義得顯彰。<br/>水浸埋葬舊人自己,<br/>靈浸引我奔義路;<br/>在此賽程不偏左右,<br/>直至我被義構成。<br/>',NULL,21529,14);
INSERT INTO stanza VALUES('CS257','15','復活彰顯在我事奉,<br/>發芽枯杖作仲裁;<br/>只憑復活生命建造,<br/>召會必成杏樹臺。<br/>木草禾稭燒盡去淨,<br/>只用復活作建材;<br/>聖城撒冷神人合一,<br/>作我工作的賞賚。<br/>',NULL,21530,15);
INSERT INTO stanza VALUES('CS257','16','但願我能深切認識,<br/>何謂復活的大能,<br/>天天模成十架模型,<br/>單憑復活度此生;<br/>認識復活人位基督,<br/>在那靈中時加增,<br/>直到見主被提時刻,<br/>傑出復活展上騰。<br/>',NULL,21531,16);
INSERT INTO stanza VALUES('CS258','1','主,我在你內,你在我裏;<br/>住在你裏面,時刻不離;<br/>你與我同在,何其親密;<br/>主,我們彼此,聯結為一。<br/>',NULL,21532,1);
INSERT INTO stanza VALUES('CS258','chorus','神聖經綸,神聖分賜,<br/>在你三一裏;<br/>向我傳輸,與我調和,<br/>用你的自己。<br/>',NULL,21533,2);
INSERT INTO stanza VALUES('CS258','2','我是你枝子,你是真樹;<br/>我在你裏面,安然居住;<br/>主,我心深願,住留此處;<br/>主,我是屬你,你也我屬。<br/>',NULL,21534,3);
INSERT INTO stanza VALUES('CS258','3','橄欖枝與你已經相接,<br/>得豐富供應,取用不竭;<br/>享生命湧流,永不停歇;<br/>在此必成長,因這聯結。<br/>',NULL,21535,4);
INSERT INTO stanza VALUES('CS258','4','當我們內住彼此裏面,<br/>實際的相聯真是無間;<br/>當我們停留彼此裏面,<br/>主觀的相調纔得完全。<br/>',NULL,21536,5);
INSERT INTO stanza VALUES('CS258','5','主,愛你享你,滿足我需;<br/>你成為我裏應時話語;<br/>在我裏代求,促我前去;<br/>結常存果子,讓你繼續。<br/>',NULL,21537,6);
INSERT INTO stanza VALUES('CS258','6','生命在我裏,流通四處;<br/>你就能充滿,洋溢不住;<br/>我們成為一,將你顯出;<br/>住在你裏面,喜樂滿足。<br/>',NULL,21538,7);
INSERT INTO stanza VALUES('CS331','1','我是屬主!哦,喜樂真是難述!<br/>甜美的回應主愛的招呼;<br/>“你是屬我,別怕,我已將你贖”─<br/>祂柔聲應許我憑信順服。<br/>',NULL,21539,1);
INSERT INTO stanza VALUES('CS331','2','我是屬主!哦,心中歡喜承認!<br/>享快樂之日,望婚娶之晨;<br/>我說“我願”迎接祂進入心門,<br/>敬愛順從主永作“主的人”。<br/>',NULL,21540,2);
INSERT INTO stanza VALUES('CS331','3','我是屬主!哦,要學更深一步:<br/>不願自由去,因我愛我主;<br/>忠貞、愛慕、犠牲事奉並降服,<br/>我毫無保留永作你奴僕。<br/>',NULL,21541,3);
INSERT INTO stanza VALUES('CS331','4','我是屬主!哦,靈、魂、體每一部,<br/>都有你印記,永不再他屬;<br/>就像你,主,滿帶恩典和豐富,<br/>一直到永遠,全都歸我屬。<br/>',NULL,21542,4);
INSERT INTO stanza VALUES('CS332','1','僅僅一摸,親愛主,<br/>僅僅一望便知足,<br/>你與我親嘴,我心別無所歸。<br/>讓我再聽你慈聲,<br/>最後選擇不變更,<br/>向我愛語陳,我就枉費你身。<br/>',NULL,21543,1);
INSERT INTO stanza VALUES('CS332','chorus','無人無物能滿足我情我意,<br/>愛主,惟你。<br/>耶穌,我愛你,我心惟一所要愛你,<br/>直到天曉。<br/>',NULL,21544,2);
INSERT INTO stanza VALUES('CS332','2','讓我摸你如昨曾,<br/>渴慕之情日添增,<br/>至寶我已得,為你,一切願捨!<br/>與我親嘴愛何深,<br/>頌讚歡呼溢我脣,<br/>主,你滿恩惠,何等甜美滋味!<br/>',NULL,21545,3);
INSERT INTO stanza VALUES('CS332','chorus','無人無物能滿足我情我意,<br/>愛主惟你。<br/>耶穌,起初愛,將,我全人焚燒<br/>我心惟一所要!<br/>',NULL,21546,4);
INSERT INTO stanza VALUES('CS332','3','你的愛眼來注目,<br/>哦,這聯結何穩固。<br/>每當我凝視,我被充滿,消失。<br/>惟有你纔能滿足,<br/>我不能活無你處,<br/>讓我你身倚,與你聯結為一。<br/>',NULL,21547,5);
INSERT INTO stanza VALUES('CS332','chorus','無人無物能滿足我情我意,<br/>愛主惟你。<br/>耶穌,我愛你我,心惟一所要<br/>愛主,將我焚燒!<br/>',NULL,21548,6);
INSERT INTO stanza VALUES('CS332','4','今我悔改歸向神,<br/>求讓我心為你焚!<br/>願你這熱火,我裏真實燒著。<br/>今我悔改歸向神,<br/>求讓我心為你焚!<br/>願你這熱火,我裏真實燒著。<br/>',NULL,21549,7);
INSERT INTO stanza VALUES('CS332','chorus','耶穌,起初愛!哦,耶穌,上好愛!<br/>我全歸來!<br/>耶穌,起初愛!哦,耶穌,上好愛!<br/>我愛!求聽此籟!<br/>',NULL,21550,8);
INSERT INTO stanza VALUES('CS333','1','我愛我主,非用天然之愛;<br/>我無可以給你。<br/>主,我愛你,這愛全然屬你,<br/>使我活在你裏。<br/>我一無所有,卻歡然經歷,<br/>倒空,消失,浸沒在你愛裏。<br/>',NULL,21551,1);
INSERT INTO stanza VALUES('CS333','2','我主,惟你是我一切所需,<br/>我心別無所願;<br/>住在你裏,經歷祝福江河,<br/>從你湧流無間。<br/>飲生命活泉,享你作恩典,<br/>作我中心、居所、祝福之源。<br/>',NULL,21552,2);
INSERT INTO stanza VALUES('CS334','1','哦,主耶穌願你吸引我,<br/>我就快跑來跟隨,<br/>享受你的名如倒出香膏,<br/>你的愛比酒更美!<br/>你是我王,帶我進你內室,<br/>享受你甜美的同在;<br/>我要稱讚你寶貴愛情,<br/>價值存到萬代。<br/>',NULL,21553,1);
INSERT INTO stanza VALUES('CS334','2','我原頑強如法老駿馬,<br/>你使我變化如鴿,<br/>在你面光中,純一來仰望,<br/>信靠你,猶似百合。<br/>以你性情構成我的妝飾,<br/>我兩腮因金辮秀美;<br/>倔強頸項因珠串美麗,<br/>甘服你旨不違。<br/>',NULL,21554,2);
INSERT INTO stanza VALUES('CS334','3','躥山越嶺,你如同羚羊,<br/>召我脫“自己”拘禁:<br/>“冬天已過去雨水也止住,<br/>佳偶,來與我同去!”<br/>百鳥鳴叫,地上百花開放,<br/>復活的豐富何繁茂,<br/>深深吸引我脫離自己,<br/>進入你的高超。<br/>',NULL,21555,3);
INSERT INTO stanza VALUES('CS334','4','“我的佳偶,你在磐穴中,<br/>在陡巖的隱密處,<br/>讓我見你面,得聽你聲音-<br/>我死裏你當留駐。<br/>聲音柔和,面貌更顯秀美-<br/>復活裏新造何饒優!”<br/>主我寶貴你十架模型,<br/>願在此永住留。<br/>',NULL,21556,4);
INSERT INTO stanza VALUES('CS334','5','“我的妹子,你奪了我心,<br/>你全然美麗可珍,<br/>用你眼一看,用你項上鍊,<br/>深深奪取了我心;<br/>我的新婦,你愛情何其美,<br/>你膏油香氣無可比,<br/>嘴唇滴蜜,舌下有奶、蜜,<br/>衣服香氣盈溢。”<br/>',NULL,21557,5);
INSERT INTO stanza VALUES('CS334','6','我願成為關鎖的園子,<br/>只供良人你享樂;<br/>又如利巴嫩,在你升天裏,<br/>流出溪水解乾渴。<br/>南風吹來,北風阿快醒起,<br/>吹在我心中的園地,<br/>好,使香氣從園中溢出,<br/>叫我良人滿意。<br/>',NULL,21558,6);
INSERT INTO stanza VALUES('CS334','7','親愛良人,我只屬於你,<br/>愛中聯調永不移,<br/>求將我如同印記放心上<br/>帶在臂上如戳記!<br/>主,我深知愛情如死堅強,<br/>眾水也不能來熄滅;<br/>直到永世仍要唱不盡,<br/>你我情深聯結!<br/>',NULL,21559,7);
INSERT INTO stanza VALUES('CS335','1','人的心哪,你愛甚麼?<br/>若非基督,無安息。<br/>哦,主,求你悅納我心,<br/>上好之愛,來愛你。<br/>',NULL,21560,1);
INSERT INTO stanza VALUES('CS335','2','今將世界全都拋棄,<br/>我主耶穌最美麗;<br/>你是可愛、甘甜、柔細,<br/>憐憫、恩典全洋溢。<br/>',NULL,21561,2);
INSERT INTO stanza VALUES('CS335','3','你的榮臉,明亮輝煌,<br/>發光照耀永無已;<br/>最美事物也無可比,<br/>惟你使我心歡喜。<br/>',NULL,21562,3);
INSERT INTO stanza VALUES('CS335','4','主!是你愛先來臨及,<br/>流血拯救你仇敵;<br/>你之愛我,永不止息,<br/>我心豈可不愛你?<br/>',NULL,21563,4);
INSERT INTO stanza VALUES('CS335','5','保守我心忠誠向你,<br/>使我同你藏神裏,<br/>在世一切所經所歷,<br/>讓你榮耀留足迹。<br/>',NULL,21564,5);
INSERT INTO stanza VALUES('CS336','1','請告訴我,祂被移到何處?<br/>石頭已輥開,只留下空墓。<br/>哦!有人己將祂移出,<br/>祂在何處?<br/>',NULL,21565,1);
INSERT INTO stanza VALUES('CS336','2','門徒前來,親眼看見空墓;<br/>竟然就離開,回自己住處。<br/>眼前事實,他們滿足。<br/>祂在何處?<br/>',NULL,21566,2);
INSERT INTO stanza VALUES('CS336','chorus','何處尋祂─主耶穌?<br/>何處尋祂-愛主?<br/>何處尋祂-我心所慕?<br/>耶穌,摯愛,我要你,主。<br/>',NULL,21567,3);
INSERT INTO stanza VALUES('CS336','3','我心破碎,失去最深渴慕;<br/>不要問我:婦人,你為何哭?<br/>除了耶穌,別無滿足。<br/>祂在何處?<br/>',NULL,21568,4);
INSERT INTO stanza VALUES('CS336','4','轉過身來,看見復活耶穌;<br/>以為是園丁,我竟未認出;<br/>以為他知主在何處。<br/>祂在何處?<br/>',NULL,21569,5);
INSERT INTO stanza VALUES('CS336','chorus','何處尋祂─主耶穌?<br/>何處尋祂-愛主?<br/>何處尋祂-指示我路,<br/>我要取祂,不畏險阻。<br/>',NULL,21570,6);
INSERT INTO stanza VALUES('CS336','5','我聽見祂對我柔聲輕訴;<br/>甜美呼喚進入我心深處。<br/>熟悉聲音,就是我主;<br/>是我耶穌!<br/>',NULL,21571,7);
INSERT INTO stanza VALUES('CS336','chorus','我已尋見主耶穌,<br/>我已尋見愛主,<br/>我已尋見我心所慕,<br/>耶穌,摯愛,我愛你,主。<br/>',NULL,21572,8);
INSERT INTO stanza VALUES('CS336','6','得見我主,我心喜難述;<br/>祂要升天,使父心滿意足。<br/>祂神、祂父成我們神、<br/>我們的父。<br/>',NULL,21573,9);
INSERT INTO stanza VALUES('CS336','chorus','你要升天,去見父;<br/>要我告訴門徒:<br/>你神已成我們的神,<br/>你父已成我們的父。<br/>',NULL,21574,10);
INSERT INTO stanza VALUES('CS337','1','已過二十世紀以來，<br/>千千萬萬寶貴的性命，<br/>心愛的奇珍、崇高的地位、<br/>以及燦爛的前途，<br/>都曾枉費在主耶穌身上。<br/>對這些愛主的人，<br/>祂是全然可愛，<br/>祂是全然可愛，<br/>配得我們獻上一切，<br/>我們澆在主身上的不是枉費，<br/>乃是馨香的見證，<br/>見證祂的甘甜。<br/>',NULL,21575,1);
INSERT INTO stanza VALUES('CS338','1','主耶穌，我是真愛你，願意單純，<br/>贖回我所有的光陰，享你愛恩。<br/>喔看那！我能在今天全然奉獻，<br/>是因你始終的恩眷，奇妙成全。<br/>求你開通我耳，在你這神家的門，<br/>當你發出呼聲，我願意永遠向你忠誠。<br/>把我印在你心，以你愛甚至你嫉恨；<br/>讓我一生作你瘋狂愛人。<br/>',NULL,21576,1);
INSERT INTO stanza VALUES('CS338','2','榮耀神，今願在這裡，向你屈膝，<br/>賜我們智慧啟示靈，得見奧秘。<br/>這一生只願投身你神聖經綸，<br/>只為你永遠的心意︰基督身體。<br/>在我調和靈裡，帶我進身體實際；<br/>享你加強救恩，使我們成耶穌的見證。<br/>主阿！願你快來！照著你所曾經答應；<br/>我們唯一羨慕是你再臨。<br/>',NULL,21577,2);
INSERT INTO stanza VALUES('CS339','1','主，袮保守我心永真誠，<br/>絕不稍退後，時見袮面容。<br/>一心單純、清潔，只願面見袮。<br/>一心只愛袮，只寶貝袮自己。<br/>',NULL,21578,1);
INSERT INTO stanza VALUES('CS339','chorus','袮愛困迫，我願奉獻我所有，<br/>袮愛吸引，我心全向袮倚投，<br/>哦，何等權利，能將自己給袮，<br/>主，我愛袮！親愛主！我只願深愛袮。<br/>',NULL,21579,2);
INSERT INTO stanza VALUES('CS339','2','主，使我愛向著袮焚燒！<br/>從來不熄滅，火熱不減少，<br/>深願這愛向袮，一生都顯耀；<br/>新鮮如當日，初嘗袮的上好。<br/>',NULL,21580,3);
INSERT INTO stanza VALUES('CS339','3','主，得着我一生獻給袮，<br/>縱有命成千，歸袮也願意。<br/>無何保留為己，一切全爲袮，<br/>我命、我一生，愛主，願都為袮。<br/>',NULL,21581,4);
INSERT INTO stanza VALUES('CS340','1','主,我愛你逐日益深摯,<br/>主,我愛你今日勝昨日。<br/>我不能再活無你之處,<br/>我不能重步往日行徑。<br/>',NULL,21582,1);
INSERT INTO stanza VALUES('CS340','2','哦,在往昔無你歲月中,<br/>當我失喪,你來施拯救。<br/>我每憶過往其餘年日,<br/>虛空心痛並潸然淚流。<br/>',NULL,21583,2);
INSERT INTO stanza VALUES('CS340','chorus','主,我真愛你,日益深摯。<br/>主,我真愛你,歷久彌新無止。<br/>',NULL,21584,3);
INSERT INTO stanza VALUES('CS340','3','哦乾渴吞噬我心深處,<br/>驅使我尋求以得滿足。<br/>哦我曾嘗試許多事物,<br/>卻仍乾渴且不得滿足。<br/>',NULL,21585,4);
INSERT INTO stanza VALUES('CS340','4','主你充滿我全人深處,<br/>豐美甘甜最令人滿足。<br/>你是那靈,作我的一切,<br/>你靈與我靈洋溢不住。<br/>',NULL,21586,5);
INSERT INTO stanza VALUES('CS340','5','追尋新事物總無止境,<br/>惟你纔是我終日渴求。<br/>我前盲目且汲汲營營,<br/>直至飲你作活水源頭。<br/>',NULL,21587,6);
INSERT INTO stanza VALUES('CS340','6','何感謝!主,你進入我靈,<br/>今在我裡你不斷擴展。<br/>何寶貝!主安家我心房,<br/>將我裡面各部分充滿。<br/>',NULL,21588,7);
INSERT INTO stanza VALUES('CS341','1','從前沉溺罪惡地,<br/>良心終日無安息,<br/>深感痛苦、無能力我知罪,<br/>我自責,因罪污不義。<br/>',NULL,21589,1);
INSERT INTO stanza VALUES('CS341','2','悲慘人生無所期,<br/>虛空世界無意義,<br/>追求快樂和刺激如補風,<br/>如捉影,既虛空又無益。<br/>',NULL,21590,2);
INSERT INTO stanza VALUES('CS341','3','神!我曾遠離你,<br/>你至高、至大、獨一;<br/>哦!你竟然成為肉體,<br/>親來尋覓,血將我洗,<br/>釘死作我代替。<br/>',NULL,21591,3);
INSERT INTO stanza VALUES('CS341','chorus','願一生愛你,<br/>願與你更親密,<br/>願將生命和一切全獻給你。<br/>願一生愛你,<br/>願與你更親密,<br/>願將生命和一切全獻給你。<br/>',NULL,21592,4);
INSERT INTO stanza VALUES('CS342','1','願你用口與我親嘴,<br/>因你愛情比酒美;<br/>我雖然黑,卻是秀美,<br/>哪噠香膏滿香味。<br/>我嘗甘甜,我享筵宴,<br/>你的呼召我聽見;<br/>喚我起來同你往前,<br/>我何愚昧竟遲延。<br/>',NULL,21593,1);
INSERT INTO stanza VALUES('CS342','chorus','主阿,在你與我愛的交通裏,<br/>你天天吸引,呼召我脫自己;<br/>要我凡事與你是一,<br/>與你同工等候被提。<br/>',NULL,21594,2);
INSERT INTO stanza VALUES('CS342','2','驀然醒悟,失去你面,<br/>身體裏將你尋見;<br/>我愛作你華轎坐墊,<br/>我成你喜樂冠冕。<br/>你召我上真理山嶺,<br/>同你活在升天境;<br/>我心答應,我目送情,<br/>甘心作你園、泉、井。<br/>',NULL,21595,3);
INSERT INTO stanza VALUES('CS342','3','聽見柔聲,要我開門,<br/>上前,你竟已轉身;<br/>當我述說可愛良人,<br/>真實同在又滿魂。<br/>作你佳偶,全因你恩,<br/>且帶盼望如清晨;<br/>書拉密女與所羅門,<br/>神人調和永不分。<br/>',NULL,21596,4);
INSERT INTO stanza VALUES('CS342','4','起來與你同往田間,<br/>清晨流連葡萄園;<br/>風茄見證你我相聯,<br/>我結果佳美新鮮。<br/>為你旨意,愛你所愛,<br/>豫備新婦趁現在;<br/>殷勤勞苦,盼望等待,<br/>良人哪,願你快來。<br/>',NULL,21597,5);
INSERT INTO stanza VALUES('CS343','1','你的愛和你美麗自己，<br/>吸引我快跑跟隨你。<br/>我重生進你內室，<br/>蒙你餧養到永世。<br/>',NULL,21598,1);
INSERT INTO stanza VALUES('CS343','chorus','良人阿！我只屬於你。<br/>佳偶阿！你何等美麗。<br/>你我生命、性情是一，<br/>愛裡聯結永不分離。<br/>',NULL,21599,2);
INSERT INTO stanza VALUES('CS343','2','因你，我得有聖別性情，<br/>我美麗來自你生命。<br/>得更新順從聽命，<br/>同良人躥山越嶺。<br/>',NULL,21600,3);
INSERT INTO stanza VALUES('CS343','3','單一裡注視你如良鴿，<br/>荊棘中信靠如百合。<br/>被變化，得你建造，<br/>成為你安息、喜樂。<br/>',NULL,21601,4);
INSERT INTO stanza VALUES('CS343','4','在田間隨你往前腳蹤，<br/>願一生愛你而同工。<br/>作王女，滿你情衷，<br/>更巴望被提得榮。<br/>',NULL,21602,5);
INSERT INTO stanza VALUES('CS343','chorus','請將我銘刻你心上，<br/>因你愛如死之堅強。<br/>朝思暮想，良人，我王，<br/>願你快來，香草山上！<br/>',NULL,21603,6);
INSERT INTO stanza VALUES('CS344','1','祂尋我如同尋找迷羊，<br/>祂贖我捨了性命；<br/>使我能得祂生命，<br/>經歷祂享受不盡。<br/>哦，我主，我真愛你，<br/>不自禁消失你裡，<br/>因你的愛困迫激勵，<br/>願一生奉獻給你。<br/>',NULL,21604,1);
INSERT INTO stanza VALUES('CS344','2','你甘美如草場、如溪水，<br/>我甦醒來走義路；<br/>憑信心生活有力，<br/>引導我能活出義。<br/>但世界時來攪擾，<br/>世代流行如浪潮，<br/>而你的愛永不動搖，<br/>牧養顧惜不減少。<br/>',NULL,21605,2);
INSERT INTO stanza VALUES('CS344','3','忽不覺你寶貴的同在，<br/>摸不著可愛的你，<br/>我的心不住猶疑，<br/>你杖，竿安慰不已。<br/>深領會憑信而活，<br/>我牧人引我行走，<br/>面對仇敵享你筵席，<br/>真經歷福杯滿溢。<br/>',NULL,21606,3);
INSERT INTO stanza VALUES('CS344','4','我牧長，我願意跟隨你，<br/>牧養你託付羊群，<br/>體貼你心中美意，<br/>永遠活在經綸裡。<br/>哦，我主，我感謝你，<br/>你恩慈隨我不離，<br/>願永住在你的殿裡，<br/>彰顯你榮耀身體。<br/>',NULL,21607,4);
INSERT INTO stanza VALUES('CS345','1','主耶穌，你是我至愛，<br/>我全心歸你不他依；<br/>天地間有何能與你比擬？<br/>神而人者，你最美麗！<br/>真渴望消失在你裡，<br/>當你柔聲入我心底；<br/>前我所眷戀，今歡然撇棄，<br/>只願愛你─全心全意。<br/>',NULL,21608,1);
INSERT INTO stanza VALUES('CS345','chorus','世上有誰像你如此美麗？<br/>人間有何與你愛情能比？<br/>哦，聖中之聖，你竟住我裡；<br/>主耶穌，我深深愛你！<br/><br/>不願再受欺，不願再任意；<br/>惟願脫自己，只被你充溢；<br/>你以外，哦，讓一切都絕跡；<br/>我惟一的最愛是你。<br/>',NULL,21609,2);
INSERT INTO stanza VALUES('CS345','2','主耶穌，你是我至愛，<br/>雖我曾頑梗又悖逆，<br/>今放下一切，你前來侍立，<br/>只願像你那樣無己。<br/>真渴望活著就是你，<br/>順從神旨，不憑己意；<br/>與你心合拍，只要你所喜；<br/>掙扎全停，盡是安息。<br/>',NULL,21610,3);
INSERT INTO stanza VALUES('CS345','3','主耶穌，你是我至愛<br/>你與我永遠不分離；<br/>你同在是我氣息、我動力，<br/>你的笑臉是我欣喜。<br/>真渴望你前吐心意，<br/>愛你、事你，聯結依依；<br/>親愛主，我的永分就是你<br/>你的來臨是我所期。<br/>',NULL,21611,4);
INSERT INTO stanza VALUES('CS346','1','用我的詩歌,向我所愛的主,<br/>唱出我心聲,也唱出我愁楚。<br/>年來所行路,是備嘗人世苦,<br/>除了我的主,還有誰可傾訴?<br/>除了我的主,還有誰可傾訴?<br/>',NULL,21612,1);
INSERT INTO stanza VALUES('CS346','2','用我的詩歌,向我所愛的主,<br/>獻上我讚美,也傾吐我思慕。<br/>雖然所行路,是淒酸多雲霧,<br/>但主手領我,仍前進不後顧。<br/>但主手領我,仍前進不後顧。<br/>',NULL,21613,2);
INSERT INTO stanza VALUES('CS346','3','用我的詩歌,向我所愛的主,<br/>表示我願意,一直走此窄路。<br/>雖然所飲杯,是苦膽調酸醋,<br/>我亦無怨言,我亦樂意順服。<br/>我亦無怨言,我亦樂意順服。<br/>',NULL,21614,3);
INSERT INTO stanza VALUES('CS346','4','用我的詩歌,向我所愛的主,<br/>唱這十架路,是我惟一歸途。<br/>雖然所經過,是傷心流淚谷,<br/>但主卻領我,由此路通國度。<br/>但主卻領我,由此路通國度。<br/>',NULL,21615,4);
INSERT INTO stanza VALUES('CS347','1','主,我心願更貞潔,<br/>一切求你喜悅,<br/>願我愛火燒更烈,<br/>眾水不能熄滅。<br/>',NULL,21616,1);
INSERT INTO stanza VALUES('CS347','chorus','哦主,我已奉獻給你,<br/>哦,主,我已獻給你,<br/>我只怕心偏於邪,<br/>失去純一清潔,<br/>願我的心能更愛你,<br/>你外我無他喜悅。<br/>',NULL,21617,2);
INSERT INTO stanza VALUES('CS347','2','凡事學習要謹守,<br/>恩座前常祈求,<br/>拒絕試探和引誘,<br/>不貪罪中自由。<br/>',NULL,21618,3);
INSERT INTO stanza VALUES('CS347','3','處世願自居卑微,<br/>不慕通達高貴,<br/>將來新城榮且美,<br/>恩典福分全備。<br/>',NULL,21619,4);
INSERT INTO stanza VALUES('CS347','4','今日一切勞和苦,<br/>為主都甘經受,<br/>昔日恩主所行路,<br/>更是歷盡苦憂。<br/>',NULL,21620,5);
INSERT INTO stanza VALUES('CS347','5','卑微通到榮耀路,<br/>必須經過十架,<br/>今日所有的重負,<br/>見主都必卸下。<br/>',NULL,21621,6);
INSERT INTO stanza VALUES('CS347','6','歎息聲音何時已?<br/>勞苦何時得息?<br/>不是旅程走完畢,<br/>便是主來接提。<br/>',NULL,21622,7);
INSERT INTO stanza VALUES('CS348','1','我是時常輭弱,輭弱至極,<br/>所有信心消沒,力量都疲;<br/>但你長久忍耐,從不放棄,<br/>仍要引我歸愛,傍你胸臆。<br/>',NULL,21623,1);
INSERT INTO stanza VALUES('CS348','2','我是時常起伏,憂懼不停,<br/>所有亮光衰微,盼望搖動;<br/>但你應許恩言,不改堅定,<br/>仍來開我心眼,向你忠誠。<br/>',NULL,21624,2);
INSERT INTO stanza VALUES('CS348','3','我是時常保留,損失都畏,<br/>所有籌畫為己,祭壇傾廢;<br/>但你柔愛憐憫,竟不收回,<br/>仍來將我吸引,向你全歸。<br/>',NULL,21625,3);
INSERT INTO stanza VALUES('CS348','4','我是時常單獨,自己追求,<br/>所有歡樂愁苦,寂寞承受;<br/>但你細細部署,不肯鬆手,<br/>仍來領我腳步,向你倚投。<br/>',NULL,21626,4);
INSERT INTO stanza VALUES('CS348','5','我是時常無知,錯識你心,<br/>所有思念體貼都在己身;<br/>但你光照不止,啟示心意,<br/>仍來轉我想願,與你成一。<br/>',NULL,21627,5);
INSERT INTO stanza VALUES('CS348','6','當我想到你的一切對待,<br/>我是不知如何回報你愛;<br/>在我每一今日尚有微力,<br/>仍然我要盡力,一生愛你。<br/>',NULL,21628,6);
INSERT INTO stanza VALUES('CS348','7','不問我的前途光明黑暗,<br/>不理我的道路平順艱難;<br/>如果是你許可,寧願等候,<br/>只要是你揀選,歡然行走。<br/>',NULL,21629,7);
INSERT INTO stanza VALUES('CS349','1','對主我們如同園子,<br/>流露各種的馨香;<br/>耶穌所有寶貴果子,<br/>園中自由的生長。<br/>哪噠鳳仙、並番紅花,<br/>菖蒲、肉桂、乳香木、<br/>沒藥沉香在此長出,<br/>甜美芬芳全為歸給主。<br/>',NULL,21630,1);
INSERT INTO stanza VALUES('CS349','2','“主請進入你的園子;<br/>良人請來隨意嘗,<br/>佳美果子上等香品,<br/>甘美豐盈供你享。<br/>“我的妹子,我的新婦,<br/>園中蜂房滴甘蜜,<br/>還有酒奶豐美、滋養,<br/>在此喫喝,滿足實無比。”<br/>',NULL,21631,2);
INSERT INTO stanza VALUES('CS349','3','園內所產復活果品,<br/>經過變他成珍寶,<br/>不僅甘美,更為建造,<br/>成為聖城主所要。<br/>先是園子,終為聖城,<br/>生長變化何美妙;<br/>基督在此得著彰顯,<br/>神的榮光輝煌全顯耀。<br/>',NULL,21632,3);
INSERT INTO stanza VALUES('CS349','4','如今這城美麗、秀美,<br/>得勝如晨光顯明,<br/>且是軍隊剛強有能,<br/>在得勝裏向前行。<br/>城與軍隊─團體聖徒,<br/>變化、建造成為一;<br/>向著仇敵,何等威武,<br/>向著主又是何等美麗!<br/>',NULL,21633,4);
INSERT INTO stanza VALUES('CS430','1','主,你得勝,我今服矣;<br/>恩典迫使我心決意,<br/>奉獻一切於你;<br/>你的可畏我能久抗,<br/>但你大愛有誰能擋?<br/>愛大,我無能力。<br/>',NULL,21634,1);
INSERT INTO stanza VALUES('CS430','2','即使你命萬鈞雷霆,<br/>轟擊我魂向我施刑,<br/>我仍固執不悔;<br/>但你憐憫征服我心,<br/>當我見主流血情景,<br/>我今恨惡我罪!<br/>',NULL,21635,2);
INSERT INTO stanza VALUES('CS430','3','主,我羨慕只屬於你;<br/>速來釋放我這容器,<br/>完全歸你佔有;<br/>撒但暴政我既得脫,<br/>就願全人向你而活,<br/>服事你到永久。<br/>',NULL,21636,3);
INSERT INTO stanza VALUES('CS431','1','只要相信耶穌大名,<br/>在信的人凡事都能;<br/>主,求使我不辱你名,<br/>使你真理在我顯明。<br/>只要對你堅信確定,<br/>在信的人凡事都能。<br/>',NULL,21637,1);
INSERT INTO stanza VALUES('CS431','2','罪惡權勢糾纏不已,<br/>我欲掙脫,毫無能力;<br/>但你應許罪奴得釋,<br/>此事必成,我心深知。<br/>並無一事在主難成,<br/>在信的人凡事都能。<br/>',NULL,21638,2);
INSERT INTO stanza VALUES('CS431','3','任憑陰府否認聖言,<br/>神的話語堅定在天;<br/>罪惡鎖鍊縱然頑強,<br/>主能打碎,將人釋放。<br/>難成之事必然得成,<br/>在信的人凡事都能。<br/>',NULL,21639,3);
INSERT INTO stanza VALUES('CS431','4','不僅在神凡事都能,<br/>在主基督凡事亦然─<br/>祂是“神能”顯於人身,<br/>我在祂裏全人更新,<br/>罪惡權勢不再得逞,<br/>在信的人凡事都能。<br/>',NULL,21640,4);
INSERT INTO stanza VALUES('CS431','5','哦主,你這神的大能,<br/>求在我裏開展、擴增,<br/>直到活著不再是我,<br/>乃是基督在我活著,<br/>此時我要甘甜唱出:<br/>你愛大能無量、全足。<br/>',NULL,21641,5);
INSERT INTO stanza VALUES('CS432','1','奇妙秘訣我已學會,<br/>就是住在主裏面;<br/>在此暢飲生命純泉,<br/>日日飽嚐祂聖言;<br/>在祂有能寶血底下,<br/>我得加力享肥甘;<br/>敗壞的『己』日漸消逝,<br/>當我浸沒祂裏面。<br/>',NULL,21642,1);
INSERT INTO stanza VALUES('CS432','chorus','我今住在主裏面,<br/>相信祂可靠聖言;<br/>甜美、安息,隱藏祂愛胸懷間。<br/>是的,住在主裏面,<br/>相信祂可靠聖言、<br/>甜美、安息,隱藏祂愛胸懷間。<br/>',NULL,21643,2);
INSERT INTO stanza VALUES('CS432','2','我與基督已經同釘,<br/>祂今與我同生活;<br/>我已停下一切掙扎,<br/>今是祂,不再是我。<br/>當我意志降服於祂,<br/>祂靈掌權我心內,<br/>祂的救贖、拯救有能,<br/>使我潔淨並脫罪。<br/>',NULL,21644,3);
INSERT INTO stanza VALUES('CS432','3','我將疾病帶來歸祂,<br/>由祂一一都擔去;<br/>我告祂以輭弱、憂、懼,<br/>祂使我一無罣慮。<br/>我的力量取自基督,<br/>生活行動祂指點;<br/>祂賜我以生命、信、愛,<br/>使我活出祂意念。<br/>',NULL,21645,4);
INSERT INTO stanza VALUES('CS432','4','我以祂智作我言、語<br/>憑祂靈力而作工;<br/>祂的同在作我道路,<br/>不住保衛、引導我。<br/>祂是無窮喜樂泉源,<br/>作我永分藏心房-<br/>是我救主、聖別、醫治、<br/>榮耀主、永世君王。<br/>',NULL,21646,5);
INSERT INTO stanza VALUES('CS433','1','我今上行,毫不遲疑,<br/>每日邁向更高之地;<br/>前行途中,禱告不息:<br/>“主使我立更高之地。”<br/>',NULL,21647,1);
INSERT INTO stanza VALUES('CS433','chorus','主,加我力,將我舉起,<br/>使我踏上更高之地;<br/>更高境地,憑信站立;<br/>主,使我立更高之地。<br/>',NULL,21648,2);
INSERT INTO stanza VALUES('CS433','2','我心不願徘徊舊地,<br/>疑惑四起,恐懼來襲;<br/>人雖寧願姑且安逸,<br/>我心卻在更高之地。<br/>',NULL,21649,3);
INSERT INTO stanza VALUES('CS433','3','雖有惡者火箭攻擊,<br/>我要安坐諸天界裏;<br/>信心聽見樂歌洋溢,<br/>發自最美,最高之地。<br/>',NULL,21650,4);
INSERT INTO stanza VALUES('CS433','4','登上山巔,只看見你,<br/>榮光將我心眼開啟;<br/>安息在望,仍要求祈:<br/>“主,領我往更高之地。”<br/>',NULL,21651,5);
INSERT INTO stanza VALUES('CS434','1','每當我們嘗主美善,<br/>總是豐富有盈餘;<br/>祂賜福杯充盈滿溢,<br/>供應充足永不渝。<br/>祂的寶庫從不匱乏,<br/>無限無量何充足;<br/>十足量器,連搖帶按,<br/>上尖下流何豐富,<br/>祂的供應從不吝惜,<br/>向屬祂者時傾注。<br/>',NULL,21652,1);
INSERT INTO stanza VALUES('CS434','2','每當我們從父領受,<br/>總是豐富有盈餘;<br/>祂所量給總是上好,<br/>感謝領受永無虞。<br/>祂賜滿足豐富深厚,<br/>供應我需必無誤;<br/>自從我心能彀領畧,<br/>祂的富足和看顧,<br/>所有心願因祂滿足,<br/>祂外不再有所慕。<br/>',NULL,21653,2);
INSERT INTO stanza VALUES('CS434','3','每當我們飽嘗主愛,<br/>總是豐富有盈餘;<br/>闊、長、高、深無法測度,<br/>豈只應付我所需?<br/>無人言語能以盡述,<br/>祂的甘美和富庶;<br/>我們只有希奇感戴,<br/>祂名泱漭且全足,<br/>安然投靠祂愛胸膛,<br/>讚美祂名到永古。<br/>',NULL,21654,3);
INSERT INTO stanza VALUES('CS435','1','耶穌十架陰影下,<br/>我今歡然站立;<br/>如在炎熱疲乏之地,<br/>尋得磐石蔭蔽。<br/>曠野之中安居無虞,<br/>途中亦享安息;<br/>日間暑溽,操煩重壓<br/>都不能將我襲。<br/>',NULL,21655,1);
INSERT INTO stanza VALUES('CS435','2','此避難所經試驗─<br/>穩妥、可悅、甘甜!<br/>天來恩愛、至上公義<br/>在此竟可兩全。<br/>如同先祖夢中所見,<br/>梯子立地頂天,<br/>藉我救主釘死木架,<br/>人竟與天結聯。<br/>',NULL,21656,2);
INSERT INTO stanza VALUES('CS435','3','陰間雖擴張其欲,<br/>開口噬人無數,<br/>在我卻已盡失權勢,<br/>因有十架隔阻。<br/>如同儆夫把守險途,<br/>十架居間聳立,<br/>伸展雙臂施行拯救,<br/>永死詛咒消弭。<br/>',NULL,21657,3);
INSERT INTO stanza VALUES('CS435','4','自從我眼得看見,<br/>耶穌木上流血,<br/>忍辱、受死全是為我,<br/>此景難以磨滅。<br/>痛悔之心頓生感讚,<br/>希奇天來恩惠:<br/>榮耀之愛何竟臨及,<br/>我這如蛆之輩。<br/>',NULL,21658,4);
INSERT INTO stanza VALUES('CS435','5','哦,十字架陰影下,<br/>我得永遠安居;<br/>恩主面光我所欣羨,<br/>其他亮光無需。<br/>今世榮華任其消逝,<br/>得失於我無差;<br/>羞慚捨卻罪惡、自己,<br/>惟誇榮耀十架。<br/>',NULL,21659,5);
INSERT INTO stanza VALUES('CS436','1','基督所賜豐滿福分,<br/>是否渴慕能得著?<br/>主所命定得勝生活,<br/>祕訣是否已掌握?<br/>答案明示於祂聖言:<br/>“基督是我們生命;”<br/>只要向祂敞開心懷,<br/>憑信取用祂豐盛。<br/>',NULL,21660,1);
INSERT INTO stanza VALUES('CS436','2','基督受死將你救贖,<br/>且要居衷掌王權;<br/>在你裏外顯祂能力,<br/>日復一日時加添。<br/>在你不能,在祂都能─<br/>祂靈要作工你身;<br/>“不再是我,乃是基督”─<br/>你要見證此深恩。<br/>',NULL,21661,2);
INSERT INTO stanza VALUES('CS436','3','神的豐滿住祂裏面,<br/>你在祂裏得豐盛;<br/>起來,取用兒子名分,<br/>切勿辜負父恩情。<br/>全是恩典,絕不遲誤,<br/>只要讚美來領受;<br/>神聖供備永無不足,<br/>憑祂而活何饒優。<br/>',NULL,21662,3);
INSERT INTO stanza VALUES('CS436','4','主我前來,單純信靠,<br/>你的聖言永不變,<br/>信你救贖洗罪有能,<br/>信你得勝、得榮冕。<br/>但願你那無窮生命<br/>帶愛從我流不息,<br/>臨及暗中無望人羣,<br/>引領多人來歸依。<br/>',NULL,21663,4);
INSERT INTO stanza VALUES('CS437','1','哦主,你話如同糧倉,<br/>供應充足、多方;<br/>凡飢餓者都可來此<br/>榮耀,豐富飽嘗。<br/>你話又如深處寶礦,<br/>稀有珍物盡藏;<br/>凡尋求者來此挖掘,<br/>必得至寶無上。<br/>',NULL,21664,1);
INSERT INTO stanza VALUES('CS437','2','你話猶如眾星發亮,<br/>光芒四射輝煌;<br/>天程旅客在此光中<br/>屬天,家鄉直往。<br/>你話又如軍器庫房,<br/>收藏全備軍裝;<br/>爭戰雖長,終必奏凱,<br/>因有供備無量。<br/>',NULL,21665,2);
INSERT INTO stanza VALUES('CS437','3','願我寶愛你的聖言,<br/>盡享礦藏富源;<br/>願我取用榮耀豐富<br/>光中,生活無間。<br/>願我尋得話中兵器,<br/>靠此誇勝敵前;<br/>揮動那靈可靠的劍,<br/>為主權益爭戰。<br/>',NULL,21666,3);
INSERT INTO stanza VALUES('CS437','4','哦,永活神生命的話,<br/>你是神的光輝;<br/>得你,我就得神自己<br/>並脫,屬地纏累。<br/>求主賜我正直的靈,<br/>話中得你智慧;<br/>猶如孩童心中單純,<br/>轉向屬天恩惠。<br/>',NULL,21667,4);
INSERT INTO stanza VALUES('CS438','1','主,教導我禱告,<br/>不要外邦世俗老套,<br/>不用天然技巧,<br/>每日簡單將你聖名求告。<br/>主,願你長在我裏。<br/>',NULL,21668,1);
INSERT INTO stanza VALUES('CS438','2','主,你在我心中,<br/>乃是奇妙生命之種;<br/>願你分賜更豐,<br/>在我裏面完成所動善工。<br/>主,願你長在我裏。<br/>',NULL,21669,2);
INSERT INTO stanza VALUES('CS438','3','主,使我心柔輭,<br/>你知我心一切為難;<br/>呼求你名不斷,<br/>翻動我心除去硬石阻攔。<br/>主,願你長在我裏。<br/>',NULL,21670,3);
INSERT INTO stanza VALUES('CS438','4','主,你光照明亮,<br/>暴露我總讓你失望;<br/>但你仍賜盼望,<br/>生命種子必定發苗生長。<br/>主,願你長在我裏。<br/>',NULL,21671,4);
INSERT INTO stanza VALUES('CS438','5','主,倒空我所有─<br/>靈裏貧窮毫無保留;<br/>願你生命湧流,<br/>將我浸透生命達到成熟。<br/>主,願你長在我裏。<br/>',NULL,21672,5);
INSERT INTO stanza VALUES('CS438','6','主,使我心純潔,<br/>有你充滿,作我一切,<br/>我就一無所缺,<br/>心思情感意志更新不歇。<br/>主,願你長在我裏。<br/>',NULL,21673,6);
INSERT INTO stanza VALUES('CS438','7','主,銘刻我心上,<br/>願你深入我心土壤,<br/>天天有路擴長,<br/>生命種子帶進國度顯彰。<br/>主,願你長在我裏。<br/>',NULL,21674,7);
INSERT INTO stanza VALUES('CS438','8','主,你長在我裏!<br/>生命力量無可匹敵,<br/>必拯救我到底,<br/>以你生命將我更新不已。<br/>主,願你長在我裏。<br/>',NULL,21675,8);
INSERT INTO stanza VALUES('CS439','1','神阿,你的大愛將我圍困,<br/>有如強潮澎湃迫我而來;<br/>不再自縛,全人歡然投順,<br/>好讓你愛流過,毫無阻礙。<br/>',NULL,21676,1);
INSERT INTO stanza VALUES('CS439','2','困迫之愛,大能有誰能檔?<br/>愛潮洶湧,我豈能再頑固?<br/>我神,你的恩慈有誰能抗?<br/>我今投誠不再依然如故。<br/>',NULL,21677,2);
INSERT INTO stanza VALUES('CS439','3','天上之愛攻破我的天然,<br/>修直心思、意念所有途徑,<br/>漫溢我情,純淨所有意願,<br/>使你純潔生命流通不停。<br/>',NULL,21678,3);
INSERT INTO stanza VALUES('CS439','4','如此,我神在我居衷掌權,<br/>恩典帶愛緩緩湧自心懷;<br/>恩愛江河從今流到永遠,<br/>能愛,是因滿享我神大愛。<br/>',NULL,21679,4);
INSERT INTO stanza VALUES('CS440','1','哦主,聖化我們,加添你的自己;<br/>願你寶貴人位擴展在我衷裏,<br/>使你榮耀召會在此顯為實際;<br/>哦主,求你加添自己。<br/>',NULL,21680,1);
INSERT INTO stanza VALUES('CS440','chorus','哦主,今日聖化我們,<br/>捨此無路滿足神心。<br/>惟願你作人位,擴展徧及四圍;<br/>哦主,今日聖化我們。<br/>',NULL,21681,2);
INSERT INTO stanza VALUES('CS440','2','哦主,潔淨我們,向我們心說話;<br/>洗滌我們全人,直至聖別無瑕。<br/>願你活話擴長,來將我們聖化;<br/>哦主,求你潔淨聖化。<br/>',NULL,21682,3);
INSERT INTO stanza VALUES('CS440','chorus','哦主,今日潔淨我們,<br/>不容天然生命留存。<br/>美麗、榮耀添加,<br/>皆因你的說話;<br/>哦主,今日潔淨我們。<br/>',NULL,21683,4);
INSERT INTO stanza VALUES('CS440','3','哦主,滋養我們,惟你是真食物;<br/>只需喫飽喝足,變化自然顯出。<br/>惟有得你餧養;我們纔真滿足;<br/>哦主,求你滋養眷顧。<br/>',NULL,21684,5);
INSERT INTO stanza VALUES('CS440','chorus','哦主,今日滋養我們,<br/>老舊、天然洗滌淨盡。<br/>求你來施潔淨,<br/>又將我們充盈;<br/>哦主,今日滋養我們。<br/>',NULL,21685,6);
INSERT INTO stanza VALUES('CS440','4','哦主,顧惜我們,以你柔愛養育;<br/>藉你溫情撫慰,眷顧我們所需。<br/>輭化剛硬石心,好來施情佔據;<br/>哦主,今日顧惜我們。<br/>',NULL,21686,7);
INSERT INTO stanza VALUES('CS440','chorus','哦主,今日顧惜我們,<br/>冷淡、死沉全都驅盡。<br/>當你懷搋緊緊,<br/>我們能不歡欣?<br/>哦主,今日顧惜我們。<br/>',NULL,21687,8);
INSERT INTO stanza VALUES('CS440','5','哦主,榮化我們,藉你內裏運行;<br/>非為個人明亮,乃為召會得榮。<br/>願你得著新婦,成就你愛經營;<br/>哦主,求你在我運行。<br/>',NULL,21688,9);
INSERT INTO stanza VALUES('CS440','chorus','哦主,今日運行我身,<br/>妝飾新婦迎你再臨。<br/>願你開展擴充,<br/>召會榮上加榮,<br/>哦主,今日榮化我們。<br/>',NULL,21689,10);
INSERT INTO stanza VALUES('CS441','1','求主賜下神聖啟示,<br/>使我有光得看見,<br/>你作生命何其真實,<br/>在我靈中時增添;<br/>還要不斷充滿浸透,<br/>從我靈向外開廣,<br/>每一部分讓你佔有,<br/>你就安家我心房。<br/>',NULL,21690,1);
INSERT INTO stanza VALUES('CS441','2','非照己意追求完美,<br/>品行端正人稱羨,<br/>也非改良外在行為,<br/>舉止穩重似完全;<br/>乃是基督活的人位,<br/>與我靈中相調和,<br/>',NULL,21691,2);
INSERT INTO stanza VALUES('CS441','3','求主使我更深經歷,<br/>生活、工作全憑你,<br/>言語、行動、態度、定意,<br/>只求單單出於你。<br/>拒絕虛空教訓、<br/>道理,放下規條和力勁,<br/>且在我心獨居首位,<br/>使我憑祂而活著。<br/>使我活著惟一憑倚,<br/>是你湧流的生命。<br/>',NULL,21692,3);
INSERT INTO stanza VALUES('CS441','4','生命感覺我肯響應,<br/>你的生命就流通;<br/>膏油塗抹豐厚運行,<br/>使我活出你性情。<br/>前我憑靠己意、己力,<br/>縱有成就亦速逝;<br/>今我只願照你心意,<br/>活你─永遠的“我是”。<br/>',NULL,21693,4);
INSERT INTO stanza VALUES('CS441','5','如此我願被主充滿,<br/>使我全人成聖別;<br/>放下老舊宗教觀念,<br/>道理、規條全棄絕。<br/>榮耀基督我心安家,<br/>將祂自己時添加;<br/>生命供應無以復加,<br/>全備、充足我所誇。<br/>',NULL,21694,5);
INSERT INTO stanza VALUES('CS442','1','基督要使尋求祂者,<br/>成為煙柱和臥榻,<br/>且成華轎、榮耀冠冕,<br/>主必作成絕無差。<br/>',NULL,21695,1);
INSERT INTO stanza VALUES('CS442','chorus','祂的佳偶,祂心所愛,<br/>富有吸引,祂喜悅;<br/>奪得祂心,怡悅祂意,<br/>在祂眼中何超絕。<br/>',NULL,21696,2);
INSERT INTO stanza VALUES('CS442','2','然而黑影尚未飛逝,<br/>基督尚未全滿足;<br/>祂要得著生長園子,<br/>成為祂所愛新婦。<br/>',NULL,21697,3);
INSERT INTO stanza VALUES('CS442','3','園中石榴、上好果子、<br/>鳳仙、哪噠、番紅花、<br/>菖蒲、肉桂、沒藥、沉香,<br/>各種香料全歸祂。<br/>',NULL,21698,4);
INSERT INTO stanza VALUES('CS442','4','基督進到自己園中,<br/>採了沒藥和香料,<br/>嘗了蜂蜜,飲了酒奶,<br/>豐富享受,何美好!<br/>',NULL,21699,5);
INSERT INTO stanza VALUES('CS442','5','佳美園子產生材料,<br/>經過變化被建造,<br/>成為聖城使神滿意,<br/>且使仇敵全竄逃。<br/>',NULL,21700,6);
INSERT INTO stanza VALUES('CS442','6','“我的佳偶,美如得撒,<br/>秀美如耶路撒冷。”<br/>美妙、絕佳,令人讚賞,<br/>主的心意得完成。<br/>',NULL,21701,7);
INSERT INTO stanza VALUES('CS443','1','基督乃是真葡萄樹,<br/>我們是祂真枝子;<br/>住在主裏,讓祂內住,<br/>生命流通永不止。<br/>',NULL,21702,1);
INSERT INTO stanza VALUES('CS443','chorus','葡萄樹,真住處,<br/>是我主與我聯屬;<br/>與主互住時刻無阻,<br/>我就得識祂豐富。<br/>',NULL,21703,2);
INSERT INTO stanza VALUES('CS443','2','祂乃是話內住我靈,<br/>說話豐富且應時;<br/>神聖發言儆醒傾聽,<br/>“互住”經歷纔真實。<br/>',NULL,21704,3);
INSERT INTO stanza VALUES('CS443','3','我們若是全心愛主,<br/>就必遵行祂吩咐;<br/>如此必能實際、深入,<br/>居住祂裏享富足。<br/>',NULL,21705,4);
INSERT INTO stanza VALUES('CS443','4','祂愛住在我們裏面,<br/>我們也住祂愛裏;<br/>生命交通和諧、甘甜,<br/>帶來喜樂無可比。<br/>',NULL,21706,5);
INSERT INTO stanza VALUES('CS443','5','如此互住何等寶貴,<br/>親密、甜美又豐富,<br/>結出美果豐碩纍纍,<br/>神、人喜樂同滿足。<br/>',NULL,21707,6);
INSERT INTO stanza VALUES('CS444','1','神是光,在祂裏面毫無黑暗污穢;<br/>交通於祂面光,何等甘美。<br/>光中行,神兒子耶穌的血必洗淨<br/>一切的罪。<br/>',NULL,21708,1);
INSERT INTO stanza VALUES('CS445','1','耶穌基督已登寶座,<br/>我們與祂同坐;<br/>世界、撒但、罪、己脫落,<br/>不能再將我迫!<br/>基督一次永遠受死,<br/>救贖大工完成;<br/>可憐罪奴得新地位,<br/>與祂同命共榮。<br/>',NULL,21709,1);
INSERT INTO stanza VALUES('CS445','2','歡然安居活神家中-<br/>榮耀召會生活;<br/>坦然昂首進至聖所,<br/>不再下沉退縮!<br/>魂的曠野不再留戀,<br/>聖所已在身後;<br/>至聖之處永遠住留,<br/>全人被神浸透。<br/>',NULL,21710,2);
INSERT INTO stanza VALUES('CS445','3','更美之約己經立定,<br/>榮耀遺贈有三:<br/>生命之律大能高超,<br/>將我變化完全;<br/>我作祂民,祂作我神,<br/>神聖福分無窮;<br/>對神認識深刻主觀,<br/>惟憑內裏生命。<br/>',NULL,21711,3);
INSERT INTO stanza VALUES('CS445','4','此外神已忘記我罪,<br/>不義一概寬恕;<br/>皆因救主十架代死,<br/>我罪全都清除;<br/>罪案全勾,不再追究,<br/>罪過都己消蹤;<br/>生命之律靈中引我,<br/>救恩路上直行。<br/>',NULL,21712,4);
INSERT INTO stanza VALUES('CS445','5','加畧妙死雙重功績,<br/>為神經綸效力:<br/>生命之律運行無礙,<br/>罪的攔阻絕迹!<br/>大工完成住入安息,<br/>主今安坐天上;<br/>新約遺贈我們全享,<br/>憑祂代禱馨香。<br/>',NULL,21713,5);
INSERT INTO stanza VALUES('CS445','6','惟願棄絕老舊觀念,<br/>取用遺贈豐富;<br/>主說成了我們享用,<br/>天天讚美不住!<br/>聽大祭司幔內呼召-<br/>“前進!”直到路終:<br/>直至達成終極目標,<br/>榮耀聖城撒冷!<br/>',NULL,21714,6);
INSERT INTO stanza VALUES('CS446','1','用你大能將我加強,<br/>主,使我進入全人深處,<br/>使我靈剛強、我心順服,<br/>讓你能安家無阻。<br/>',NULL,21715,1);
INSERT INTO stanza VALUES('CS446','chorus','進入我心!進入我心!<br/>來安家我心,主耶穌!<br/>滿帶豐富,恩主,請進!<br/>來安家我心,主耶穌!<br/>',NULL,21716,2);
INSERT INTO stanza VALUES('CS446','2','在我心房開展,主耶穌,<br/>你的安家是我所慕;<br/>從我靈中向外開展,<br/>主,佔有我全心各部。<br/>',NULL,21717,3);
INSERT INTO stanza VALUES('CS446','3','來安家我心中,主耶穌,<br/>使我全心成你住處;<br/>願你充滿,顯明你豐足,<br/>來安家我心,恩主。<br/>',NULL,21718,4);
INSERT INTO stanza VALUES('CS446','4','你必運行,充盈成就,主,<br/>超我所想、所能求訴;<br/>我今敞開,切求主進入,<br/>現在就進來居住。<br/>',NULL,21719,5);
INSERT INTO stanza VALUES('CS447','1','有一人,有一人,寶座上坐著;<br/>有一人,作先鋒,道路已開拓;<br/>這人子是耶穌,我們樂追隨;<br/>祂已得勝,我們與祂同登位。<br/>',NULL,21720,1);
INSERT INTO stanza VALUES('CS447','2','向上去,向上去,與祂同登極;<br/>向上去,經罪世,勝黑暗憂悒;<br/>撒但雖將人擄,我們得釋放,<br/>且必同主高升,寶座上為王。<br/>',NULL,21721,2);
INSERT INTO stanza VALUES('CS447','3','同蒙召,同蒙召,命定作君王;<br/>同蒙召,成後嗣,世界甘埋葬;<br/>但我們豈彀格,配得這命定?<br/>求主搜尋、焚燒,將我全煉淨。<br/>',NULL,21722,3);
INSERT INTO stanza VALUES('CS447','4','來搜尋,來搜尋,焚燒我內心;<br/>來搜尋,來焚燒,渣滓都除盡;<br/>毋畏懼,毋退縮,當清楚看見:<br/>如此搜尋、焚燒乃是主恩眷。<br/>',NULL,21723,4);
INSERT INTO stanza VALUES('CS447','5','一道虹,一道虹,顯人子周圍;<br/>一道虹,在宣告,信實永不頽:<br/>神審判厲如火,我本當遭禍,<br/>竟蒙赦宥,前來讚祂恩深闊。<br/>',NULL,21724,5);
INSERT INTO stanza VALUES('CS448','1','神的旨意在這宇宙,全在祂與人關係;<br/>為此主成那靈,進入人靈,與人調為一。<br/>我們為此歡喜,因能有分神永遠旨意─<br/>調和是神心意。<br/>',NULL,21725,1);
INSERT INTO stanza VALUES('CS448','chorus','神人調和,阿利路亞!<br/>神人調和,阿利路亞!<br/>神人調和,阿利路亞!<br/>調和是神心意。<br/>',NULL,21726,2);
INSERT INTO stanza VALUES('CS448','2','人裏有一比心思、情感、意志更深之地,<br/>是神所造的靈,好使人能盛裝祂自己。<br/>祂且要從人靈裏湧出,像江河無止息─<br/>調和是神心意。<br/>',NULL,21727,3);
INSERT INTO stanza VALUES('CS448','3','在主恢復中,我們已看見神永遠心意,<br/>就是憑祂而活,天天經歷祂神聖三一;<br/>轉回我們的靈,一直留在調和的靈裏─<br/>調和是神心意。<br/>',NULL,21728,4);
INSERT INTO stanza VALUES('CS448','4','我們看見人子,在燈臺中間保養顧惜,<br/>眼目如火、雙腳像銅,為神的恢復效力;<br/>祂要完成神的旨意,以得著團體實體─<br/>調和是神心意。<br/>',NULL,21729,5);
INSERT INTO stanza VALUES('CS448','5','我們何等需要更深經歷與神調為一,<br/>行事為人、言語思想,更多得著祂自己。<br/>為著調和,我們願意奉獻,全照祂心意─<br/>調和是神心意。<br/>',NULL,21730,6);
INSERT INTO stanza VALUES('CS448','6','新耶路撒冷來自我們每日對神經歷,<br/>她是神、人二性調和,完全顯出的終極;<br/>一同有分享受那城我們喜樂真無比─<br/>調和是神心意。<br/>',NULL,21731,7);
INSERT INTO stanza VALUES('CS449','1','神的作為公義、公平,<br/>道路、法則皆完備;<br/>祂的行動全然正直,<br/>配得我們的讚美。<br/>祂的定罪、祂的要求,<br/>無一不顯祂公義;<br/>律法已將我們判罪,<br/>審判座前誰能立?<br/>',NULL,21732,1);
INSERT INTO stanza VALUES('CS449','2','律法雖定我們死罪,<br/>神愛始終未遺棄;<br/>公義審判歸神兒子,<br/>因祂作了我代替。<br/>阿利路亞!我們今享<br/>基督救贖的功績:<br/>買回我們歸神自己,<br/>甚至成為祂的義。<br/>',NULL,21733,2);
INSERT INTO stanza VALUES('CS449','3','神的性情聖別超凡,<br/>祂之所是乃至聖;<br/>祂要聖化我們全人,<br/>使其合乎祂性情。<br/>從我靈中向外擴展,<br/>祂要安家我心房;<br/>直到全人內裏各部,<br/>盡得更新像祂樣。<br/>',NULL,21734,3);
INSERT INTO stanza VALUES('CS449','4','生機拯救過程奇妙,<br/>全由生命來效力;<br/>每日每時都可經歷,<br/>主的救恩何實際。<br/>時常思念那靈的事,<br/>心思就成為生命;<br/>主在我裏得著地位,<br/>我得變化成神聖。<br/>',NULL,21735,4);
INSERT INTO stanza VALUES('CS449','5','榮耀乃是神的彰顯,<br/>祂之所是顯無盡;<br/>也是救贖終極一步,<br/>具體顯明於我身。<br/>榮耀乃是神聖生命<br/>聖別過程的完成;<br/>也是生命供應目的─<br/>身體變像顯殊榮。<br/>',NULL,21736,5);
INSERT INTO stanza VALUES('CS449','6','為此,我們熱切等待<br/>得贖、被提、得榮耀;<br/>神的豐滿顯明於地,<br/>耶穌見證全顯照。<br/>我們就要完全像主,<br/>永遠彰顯祂榮形;<br/>神的眾子顯於榮耀,<br/>宇宙萬有共歡騰。<br/>',NULL,21737,6);
INSERT INTO stanza VALUES('CS449','7','因神憐憫,蒙神選召,<br/>榮耀定命得有分;<br/>非藉人的定意奔跑,<br/>全是神主宰憐憫。<br/>野橄欖枝竟得聯於<br/>栽種橄欖的豐富;<br/>生機聯結,分享肥汁,<br/>長成榮耀的國度。<br/>',NULL,21738,7);
INSERT INTO stanza VALUES('CS449','8','在這美妙過程之中,<br/>日日因生命成聖;<br/>滿心感謝祂所賜與,<br/>召會生活的供應。<br/>在此全享神的自己,<br/>實際、真切、又富饒;<br/>同作眾子,同為後嗣,<br/>召會生活何榮耀!<br/>',NULL,21739,8);
INSERT INTO stanza VALUES('CS450','1','神話語賜盼望何等堅定:<br/>主來時,我全人必得贖;<br/>但患難帶來疑惑與憂懼,<br/>盼望隱,異象逐漸糢糊。<br/>磨難間,本不知如何禱告,<br/>無言中,只有深處歎息;<br/>雖輭弱,有那靈幫同擔負,<br/>照著神,為我代禱求祈。<br/>',NULL,21740,1);
INSERT INTO stanza VALUES('CS450','2','主,我是不敢求受苦更深,<br/>只望能免去試煉襲擊;<br/>你若許,求將苦杯速撤去,<br/>但必須是你旨,非我意。<br/>真希奇!此時艱難雖四佈,<br/>深處竟安然一無罣慮;<br/>因有神大愛澆灌我心內,<br/>溢我魂,驅盡所有疑懼。<br/>',NULL,21741,2);
INSERT INTO stanza VALUES('CS450','3','何穩妥!神主宰調度萬有,<br/>全為使愛祂者得益處;<br/>勿讓我因眼瞎竟不知悉,<br/>無一事非祂愛所部署。<br/>乃是父答應那靈的代求,<br/>賜我以諸般試煉、煎熬;<br/>患難中,願主擴增我減少,<br/>直到我充滿基督榮耀。<br/>',NULL,21742,3);
INSERT INTO stanza VALUES('CS450','4','神兒女既有神兒子生命,<br/>祂豈不藉管教施成全?<br/>如器皿在窰匠甄陶手中,<br/>豈不經琢磨使榮美現?<br/>神衷心所渴望是得眾子,<br/>模成祂長子榮耀形像;<br/>我們既是基督許多弟兄,<br/>豈能不與祂一式一樣?<br/>',NULL,21743,4);
INSERT INTO stanza VALUES('CS450','5','何盼望!同基督作神後嗣;<br/>何輝煌!救恩要達至極。<br/>今時的苦楚似沉痛難當,<br/>不配與將來榮耀相比。<br/>凡事上,我們已得勝有餘,<br/>乃藉祂-那愛我們的主;<br/>榮耀日,神眾子就要顯出,<br/>受造物享自由何滿足!<br/>',NULL,21744,5);
INSERT INTO stanza VALUES('CS451','1','神已賜、神已賜,神今已賜與;<br/>寶貴信、神能力、並極大應許;<br/>我們信而領受,供備全得著,<br/>就能憑此長大成熟進神國。<br/>',NULL,21745,1);
INSERT INTO stanza VALUES('CS451','2','何寶貴、何寶貴,同樣的寶貴,<br/>信是神所分給,在眾聖心內;<br/>我們雖會搖擺,此信不稍減,<br/>且要逐日扶持、加強到永遠。<br/>',NULL,21746,2);
INSERT INTO stanza VALUES('CS451','3','神能力、神能力,如泉源豐盛,<br/>既剛強,又得勝,今在我運行;<br/>在我裏賜生命,所需全供應,<br/>使我活出敬虔,彰顯神榮形。<br/>',NULL,21747,3);
INSERT INTO stanza VALUES('CS451','4','藉榮耀、藉美德,神呼召我們,<br/>又寶貴又極大應許作我分;<br/>脫情慾、脫敗壞,世界失權能,<br/>藉應許我們得有分神性情。<br/>',NULL,21748,4);
INSERT INTO stanza VALUES('CS451','5','基督是神能力,在我靈裏居,<br/>祂又是神話語─神全備應許;<br/>讀祂話,摸祂靈,天天當操練─<br/>呼求、讀經、禱告,生命時加添。<br/>',NULL,21749,5);
INSERT INTO stanza VALUES('CS451','6','神能力、神應許,同寶貴的信,<br/>我們既已得著,應用當殷勤;<br/>多供應、勤澆灌,生命日豐碩,<br/>信心種子必結出愛的美果。<br/>',NULL,21750,6);
INSERT INTO stanza VALUES('CS451','7','要增長、要增長,主裏要增長,<br/>勿閒懶,結美果,豐富又多方;<br/>我們罪已得潔,救恩不該忘,<br/>不再眼瞎,乃要天天讓主長。<br/>',NULL,21751,7);
INSERT INTO stanza VALUES('CS451','8','當殷勤、當殷勤,日日長生命,<br/>神呼召和揀選因此得堅定;<br/>我們與神種子配合使成長,<br/>就必進入神國享豐富無量。<br/>',NULL,21752,8);
INSERT INTO stanza VALUES('CS451','9','寶貴信、神應許、神聖的能力─<br/>神供備何充足,捨此不他依;<br/>主,我們獻自己,願與你合作,<br/>靠恩長大,直至豐富進神國。<br/>',NULL,21753,9);
INSERT INTO stanza VALUES('CS452','1','寶貴信仰已經一次<br/>永遠交付聖徒,<br/>持守信仰、竭力爭辯<br/>乃是我們託付。<br/>',NULL,21754,1);
INSERT INTO stanza VALUES('CS452','chorus','我們深知所信的是誰,<br/>並且憑信、愛、藉內住聖靈,<br/>保守那美好的託付─<br/>健康話語的規範。<br/>',NULL,21755,2);
INSERT INTO stanza VALUES('CS452','2','美好託付務必持守,<br/>絕不稍微偏離;<br/>這是神經綸的標的,<br/>是主恢復目的。<br/>',NULL,21756,3);
INSERT INTO stanza VALUES('CS452','3','當用清潔無虧良心,<br/>持守信仰奧祕;<br/>行事為人莊重、聖別,<br/>只活聖別無比!<br/>',NULL,21757,4);
INSERT INTO stanza VALUES('CS452','4','健康話語善美規範,<br/>憑信和愛持守;<br/>不同教訓、虛空言談,<br/>棄絕,一概不留!<br/>',NULL,21758,5);
INSERT INTO stanza VALUES('CS452','5','傳講健康純全教訓─<br/>合乎敬虔真理;<br/>保守託付,持守信仰,<br/>生求得主歡喜。<br/>',NULL,21759,6);
INSERT INTO stanza VALUES('CS452','6','主,使我們忠於所託,<br/>殷勤教導、傳揚;<br/>言語、為人、愛、信、純潔,<br/>都作信徒榜樣。<br/>',NULL,21760,7);
INSERT INTO stanza VALUES('CS453','1','我生活有何等奇妙的大改變,<br/>當我對主話說“阿們”;<br/>主生命何豐富在我裏時加添,<br/>當我對主話說“阿們”。<br/>',NULL,21761,1);
INSERT INTO stanza VALUES('CS453','chorus','對主話我要說“阿們”,<br/>對主話我要說“阿們”;<br/>如此讓主安家,我全人得變化-<br/>對主話我要說“阿們”。<br/>',NULL,21762,2);
INSERT INTO stanza VALUES('CS453','2','神自己在我裏成就我所不能,<br/>當我對主話說“阿們”;<br/>這改變何真實,眾人皆能印證,<br/>當我對主話說“阿們”。<br/>',NULL,21763,3);
INSERT INTO stanza VALUES('CS453','3','我流蕩得止息,永不再走迷途,<br/>當我對主話說“阿們”;<br/>老愛好、舊思慮不覺間盡消除,<br/>當我對主話說“阿們”。<br/>',NULL,21764,4);
INSERT INTO stanza VALUES('CS453','4','憑信心過生活,我已尋得祕訣:<br/>只要對主話說“阿們”;<br/>主於我既真實又寶貴,勝一切-<br/>只要對主話說“阿們”。<br/>',NULL,21765,5);
INSERT INTO stanza VALUES('CS453','5','愛弟兄,無虛假,相調中,益親熱,<br/>當我對主話說“阿們”;<br/>為建造主居所,與眾聖相結合,<br/>當我對主話說“阿們”。<br/>',NULL,21766,6);
INSERT INTO stanza VALUES('CS453','6','我的主,我的愛,惟願你快顯現-<br/>對你話我要說“阿們”;<br/>我朝夕所思慕是見你面對面-<br/>對你話我要說“阿們”。<br/>',NULL,21767,7);
INSERT INTO stanza VALUES('CS453','chorus','對你話我要說“阿們”,<br/>對你話我要說“阿們”。<br/>你說,“我必快來!”我全心說“阿們”;<br/>對 你話我要說“阿們“。<br/>',NULL,21768,8);
INSERT INTO stanza VALUES('CS454','1','恩主我心至愛，今我歸你懷抱！<br/>你外任何事物，不能將我攪擾。<br/>你曾以愛呼召，我曾被你吸引；<br/>曠野道路默默，愛情結盟緊緊。<br/>',NULL,21769,1);
INSERT INTO stanza VALUES('CS454','2','我願奉獻自己，全因你的大愛；<br/>此情主未遺忘，時刻銘記心懷。<br/>幼年曙光黎明，前途一片燦爛，<br/>壇火原不該滅，直至天光爛漫。<br/>',NULL,21770,2);
INSERT INTO stanza VALUES('CS454','3','偶像奪取人心，叫人醉倒傾迷，<br/>無知的心受拐，不覺偷被牽離。<br/>只是幼年恩愛，仍然呼召不已，<br/>能否保持此心，永為未耕之地？<br/>',NULL,21771,3);
INSERT INTO stanza VALUES('CS454','4','雖我羞步遲疑，你仍誘導依依，<br/>賜我葡萄果園，使我陶醉忘己；<br/>應聲亞割幽谷，踏上指望之門，<br/>憐愛臉光披露，重獲久別良人。<br/>',NULL,21772,4);
INSERT INTO stanza VALUES('CS454','5','前雖汗勞一身，僅知工作主人，<br/>今你成我丈夫，以愛聘娶委身。<br/>棄絕破裂池子，歸依活水泉源，<br/>享受愛情筵宴，沈溺恩典深淵。<br/>',NULL,21773,5);
INSERT INTO stanza VALUES('CS454','6','恩主今我屬你，與我心心相繫，<br/>只望不再我活，永遠與你合一，<br/>你我只一空間，密切個人情深，<br/>我願消失你裡，直至永世不分。<br/>',NULL,21774,6);
INSERT INTO stanza VALUES('CS455','1','為這一天，我獻感謝，<br/>全人再次交托與主聯結；<br/>祂是生命活水，使我滿足歡暢，<br/>從我靈裏向外流淌，將我溢漫且從我顯彰。<br/>',NULL,21775,1);
INSERT INTO stanza VALUES('CS455','2','無須憂慮，無須懷疑，<br/>惟尋求祂的國和祂的義，<br/>每天都有需要，凡事向祂述說，<br/>祂賜平安深且廣闊，時時保守使我永穩妥。<br/>',NULL,21776,2);
INSERT INTO stanza VALUES('CS455','3','常常喜樂，不住禱告，<br/>凡事謝恩無何比這更美好；<br/>主是永活源頭，作我一切供應，<br/>凡我交托在祂手中，祂能保全一直到路終。<br/>',NULL,21777,3);
INSERT INTO stanza VALUES('CS456','1','轉!黑暗丟在背後,<br/>光,在前頭。<br/>轉!虛空世界脫落,<br/>愛,在左右。<br/>',NULL,21778,1);
INSERT INTO stanza VALUES('CS456','chorus','歡然邁入新境地,<br/>憑神脫去陳舊,<br/>神調人新生活,<br/>盼望得榮時候。<br/>走,跟耶穌腳踨!<br/>今我們得神聖生命不朽,<br/>享受神兒子自由;<br/>走,同基督行動!<br/>流,隨聖靈湧流!<br/>經綸的神正在呼召,<br/>一個新人─我人生所投。<br/>',NULL,21779,2);
INSERT INTO stanza VALUES('CS456','2','轉!往新方向尋求,<br/>進入方舟。<br/>轉!公義、和平、喜樂,<br/>是神的國。<br/>',NULL,21780,3);
INSERT INTO stanza VALUES('CS456','3','轉!離棄狹窄自我,<br/>神旨承託。<br/>轉!國度福音展擴,<br/>剛強開拓。<br/>',NULL,21781,4);
INSERT INTO stanza VALUES('CS457','1','我在這裏,天使睽睽注目;<br/>主權已交出,如釋重負,<br/>不再為世界奴僕。<br/>我在這裏!今全屬基督,<br/>願跟隨卑微耶穌,<br/>直至掌權國度!<br/>',NULL,21782,1);
INSERT INTO stanza VALUES('CS457','2','我在這裏,世人瞠目驚喟:<br/>“竟如此枉費?”但我無悔,<br/>因知道所信是誰!<br/>我在這裏!得上好機會,<br/>將寶貴玉瓶打碎,<br/>見證祂的甘美。<br/>',NULL,21783,2);
INSERT INTO stanza VALUES('CS457','3','我在這裏,撒但已在抖顫:<br/>真相終揭穿─大巴比倫,<br/>要被神烈火審判。<br/>我在這裏!永不向後看!<br/>上到樓房來奉獻,<br/>福音地極傳遍!<br/>',NULL,21784,3);
INSERT INTO stanza VALUES('CS457','4','我在這裏,我看見祂微笑:<br/>祂的一聲“好”,價值何高,<br/>勝一切人的榮耀。<br/>我在這裏!歸回為建造;<br/>黑夜已深將破曉,<br/>惟願祂來得早!<br/>',NULL,21785,4);
INSERT INTO stanza VALUES('CS458','1','我本世人與你為敵,<br/>棄絕你恩漠視你意,<br/>有人對我講你心腸,<br/>要我歸回滿你切望,<br/>而我總是置之不理,<br/>引我回家,真是不易。<br/>',NULL,21786,1);
INSERT INTO stanza VALUES('CS458','2','等我歸來得見你面,<br/>纔知救恩如此完全:<br/>如蟲世人成為信徒,<br/>不過與你和好初步,<br/>直到你我聯調為一,<br/>纔是與你和好極地。<br/>',NULL,21787,2);
INSERT INTO stanza VALUES('CS458','3','一重幔子我已經過,<br/>歡然來到你的聖所,<br/>二重幔子雖已裂開,<br/>我的經歷仍是不逮,<br/>但你卻要引我進入,<br/>至聖所在,享你供輸。<br/>',NULL,21788,3);
INSERT INTO stanza VALUES('CS458','4','和好還是完全分別,<br/>離棄不法,除去不潔,<br/>肉身和靈一切污穢,<br/>需你榮光如同雨沛,<br/>盡都洗去,洗得盡淨,<br/>每一部分完全成聖。<br/>',NULL,21789,4);
INSERT INTO stanza VALUES('CS458','5','拯救之日,悅納時候,<br/>要我與你和好無隔,<br/>我願竭力靠你大能,<br/>奔這“完全和好”路程,<br/>你的恩典不致徒受,<br/>你的救恩我能全得。<br/>',NULL,21790,5);
INSERT INTO stanza VALUES('CS458','6','當我看見你的心意,<br/>你所要我到達境地,<br/>我又羨慕,我又驚懼,<br/>依我能力我怎能及?<br/>求你作工用你恩典,<br/>使我不住,不住向前。<br/>',NULL,21791,6);
INSERT INTO stanza VALUES('CS459','1','主,你旨意我願憑,<br/>主,你聖言我聽,不讓閒話漏生命,<br/>不讓俗務擾靈。<br/>求你向我多吸引,<br/>使我與你更親,<br/>讓我常見你榮形,<br/>緊緊跟隨你行。<br/>',NULL,21792,1);
INSERT INTO stanza VALUES('CS459','2','主,你道路我願走,<br/>不管風狂雨驟,<br/>雖然有憂也有愁,<br/>主恩卻更深厚。<br/>我今追求雖不彀,<br/>有時會貪優游,<br/>求你仍把我收留,<br/>用愛把我浸透。<br/>',NULL,21793,2);
INSERT INTO stanza VALUES('CS459','3','主,你十架我願負,<br/>面向你的國度,<br/>雖然流淚雖然苦,<br/>你手卻常攙扶。<br/>前面路程已不長,<br/>屬天家鄉在望,<br/>有朝,父懷我安躺,<br/>我就喜樂歡暢。<br/>',NULL,21794,3);
INSERT INTO stanza VALUES('CS459','4','主,你榮耀快顯現,<br/>這是我心所羨,<br/>你的應許不改變,<br/>你來將不遲延。<br/>求主使我能自勉,<br/>不向世界流連,<br/>我眼能常望著天,<br/>心能向你戀戀。<br/>',NULL,21795,4);
INSERT INTO stanza VALUES('CS460','1','我的手不能停作主的聖工,<br/>因我早已對主應許永事奉;<br/>雖然有時會遇患難和貧窮,<br/>但我願不改變向主的盡忠;<br/>雖然有時會遇患難和貧窮,<br/>但我願不改變向主的盡忠;<br/>我的手不能停作主的聖工,<br/>因我早已對主應許永事奉。<br/>',NULL,21796,1);
INSERT INTO stanza VALUES('CS460','2','我的腳不能離十架的窄路,<br/>因那是我愛主所走過路途;<br/>雖然是有眼淚也多有痛苦,<br/>但我仍願前進不稍有回顧;<br/>雖然是有眼淚也多有痛苦,<br/>但我仍願前進不稍有回顧;<br/>我的腳不能離屬天的家鄉,<br/>因那是神計畫終極的彰顯。<br/>',NULL,21797,2);
INSERT INTO stanza VALUES('CS460','3','我的眼常仰望屬天的家鄉,<br/>因那是神計畫終極的彰顯;<br/>在那裏無憂愁也再無悲傷,<br/>只有神恩和愛是我所安享;<br/>在那裏無憂愁也再無悲傷,<br/>只有神恩和愛是我所安享;<br/>我的眼常仰望屬天的家鄉,<br/>因那是神計畫終極的彰顯。<br/>',NULL,21798,3);
INSERT INTO stanza VALUES('CS460','4','我的心不能忘救主的再來,<br/>因那是眾聖徒久久所懸待;<br/>到那時見主面安息在主懷,<br/>就與主不分開永與主同在。<br/>到那時見主面安息在主懷,<br/>就與主不分開永與主同在;<br/>我的心不能忘救主的再來,<br/>因那是眾聖徒久久所懸待。<br/>',NULL,21799,4);
INSERT INTO stanza VALUES('CS461','1','你竟獨行這條十架窄路,<br/>客西馬尼,別後成殊途。<br/>羊羣逃散,牧人獨蹣跚,<br/>幽暗掌權,炭火添冷淡。<br/>',NULL,21800,1);
INSERT INTO stanza VALUES('CS461','chorus','在人手中被推擠,<br/>在人口中被唾棄,<br/>你面如堅石肅然佇立;<br/>主,愛你卻不敢認你。<br/>',NULL,21801,2);
INSERT INTO stanza VALUES('CS461','2','你何獨行這條十架窄路?<br/>前說恩言,今被人厭詛!<br/>歎息聲滅,欺凌卻暴烈,<br/>神的愛子,何竟遭天絕!<br/>',NULL,21802,3);
INSERT INTO stanza VALUES('CS461','chorus','我無法停止淚彈,<br/>當你憂傷回首看,<br/>想起曾說與你同苦難;<br/>主我的愛何等不堪。<br/>',NULL,21803,4);
INSERT INTO stanza VALUES('CS461','3','你終獨行這條十架窄路,<br/>各各他山,罪愆獨背負。<br/>釘痕的手,困我似囚牢?<br/>無力脫開,槍扎的懷抱?<br/>',NULL,21804,5);
INSERT INTO stanza VALUES('CS461','chorus','起初的愛未忘記,<br/>跟隨的心卻離棄,<br/>你愛我,竟為我捨性命;<br/>主我愛你卻捨何情?<br/>',NULL,21805,6);
INSERT INTO stanza VALUES('CS461','4','與你同行這條十架窄路,<br/>斷絕世界,今生葬泥土。<br/>“你愛我嗎?”是的我愛你!<br/>不再別依,隨你腳蹤起。<br/>',NULL,21806,7);
INSERT INTO stanza VALUES('CS461','chorus','去罷!屬地的賄賂!<br/>去罷!虛假的祝福!<br/>這條古老的十架窄路,<br/>主愛你的人當同赴。<br/>',NULL,21807,8);
INSERT INTO stanza VALUES('CS462','1','大哉!敬虔奧祕!神顯於肉體,<br/>支搭帳幕,豐滿恩典何實際;<br/>神聖奧祕三一,今在我們裏,<br/>基督奧祕身體彰顯神自己。<br/>',NULL,21808,1);
INSERT INTO stanza VALUES('CS462','chorus','何神聖!何奧祕!三一竟可進入。<br/>何榮耀!何有福!得享一切豐富。<br/>那靈充滿浸透全人每一部,<br/>直到長大成熟,作榮美新婦。<br/>',NULL,21809,2);
INSERT INTO stanza VALUES('CS462','2','神已經過過程又終極完成,<br/>成為複合那靈,眷臨賜生命;<br/>神聖膏油塗抹─神性調人性,<br/>我們得祂分賜,有分神性情。<br/>',NULL,21810,3);
INSERT INTO stanza VALUES('CS462','3','我們今蒙憐憫,出宗教營外,<br/>跟隨基督,不致退縮遭毁壞;<br/>享受那靈運行,和圍繞雲彩,<br/>經歷調和,將身體建造起來。<br/>',NULL,21811,4);
INSERT INTO stanza VALUES('CS462','4','基督生機身體,是父神的家,<br/>我們互為肢體,調和又配搭;<br/>基督乃是生命、人位和彰顯,<br/>神聖奧祕範圍,現今得擴大。<br/>',NULL,21812,5);
INSERT INTO stanza VALUES('CS462','5','我們得著生命,有父神性情,<br/>且藉達到聖別,成為一見證;<br/>今在父榮耀裏,將三一顯明,<br/>至終達到聖城-新耶路撒冷。<br/>',NULL,21813,6);
INSERT INTO stanza VALUES('CS463','1','創世之前,蒙神揀選,<br/>在你愛裏,在你面前成為聖別。<br/>雖然我們常是善變,<br/>但你憐憫和恩典卻仍然眷憐。<br/>心清、心輭、心愛與心安,<br/>我要運用我靈,照著你的心意,<br/>心得堅固,使我活你面前,<br/>全然聖別,得以完全。<br/>',NULL,21814,1);
INSERT INTO stanza VALUES('CS463','2','我們蒙召,雖然年幼,<br/>卻受吸引,願在你前成為聖別。<br/>信心工作、愛心勞苦<br/>並盼望忍耐,是我們屬靈特質。<br/>我主,我靈、我心、我全人,<br/>全然傾倒你前,竭力操練敬虔,<br/>靠你寶血,使我履敗履站,<br/>勝過肉體,全然聖別。<br/>',NULL,21815,2);
INSERT INTO stanza VALUES('CS464','1','當遇難處使我躊躇,<br/>屬天異象漸糢糊,<br/>四圍充滿艱辛攔阻,<br/>似乎無力再隨主;<br/>但主告我祂曾歷世途,<br/>經憂患無枕首處,<br/>被掛木上嘗苦膽酸醋,<br/>憂苦祂已擔負。<br/>',NULL,21816,1);
INSERT INTO stanza VALUES('CS464','2','靈中聽主題醒囑咐,<br/>需要憑信走窄路;<br/>祂的患難要我補足,<br/>經歷十架學順服。<br/>祂話內住,時將我鼓舞,<br/>使我得力再舉步,<br/>歡然隨主歷短暫苦楚,<br/>永遠榮耀在目。<br/>',NULL,21817,2);
INSERT INTO stanza VALUES('CS464','3','看見建造異象藍圖,<br/>放膽前行無旁騖;<br/>所有境遇是為幫助,<br/>信徒生命早成熟。<br/>何等榮耀,有分神建築,<br/>金、銀、寶石非草、木,<br/>讓神安居,且成主新婦,<br/>主的再臨催促。<br/>',NULL,21818,3);
INSERT INTO stanza VALUES('CS464','4','等我行完此生路途,<br/>我要迎見親愛主,<br/>且與眾聖同聲歡呼,<br/>此路原來不孤獨。<br/>“好!你這良善忠信奴僕”─<br/>公義的主要宣佈;<br/>主人快樂得歡然進入,<br/>纔識你恩豐足。<br/>',NULL,21819,4);
INSERT INTO stanza VALUES('CS465','1','神心所傾,撒冷美麗;<br/>錫安高峯,滿祂情衷。<br/>神人合併,互為安息,<br/>至深美意,願否響應?<br/>',NULL,21820,1);
INSERT INTO stanza VALUES('CS465','chorus','親愛良人,我願隨你同行;<br/>榮耀君王,今你據我全心。<br/>作得勝者,被提滿足你意,<br/>錫安山上同你站立。<br/>',NULL,21821,2);
INSERT INTO stanza VALUES('CS465','2','平凡如我,竟入聖城;<br/>心羨錫安:得勝赤誠。<br/>榮耀異象,引我腳蹤,<br/>撇下纏累,踏上旅程。<br/>',NULL,21822,3);
INSERT INTO stanza VALUES('CS465','3','主恩眷臨,祂愛激勵;<br/>憑信築壇,“以撒”為祭。<br/>世途成燼,馨香盈溢,<br/>神聖經綸,此生意義。<br/>',NULL,21823,4);
INSERT INTO stanza VALUES('CS465','4','雲彩圍繞,同奔向前;<br/>靈中爭戰,配搭無間。<br/>己意棄絕,身體得建,<br/>高峯在望,實際出現。<br/>',NULL,21824,5);
INSERT INTO stanza VALUES('CS465','5','愛裏同工,勞苦不息;<br/>流中跟隨,同魂同心。<br/>國度福音,徧傳全地,<br/>建造錫安,迎你再臨。<br/>',NULL,21825,6);
INSERT INTO stanza VALUES('CS466','1','晨光東方升起，喚我起來歌唱，<br/>祂的日頭醫治亮光，使我甦醒舒暢。<br/>主恩如同甘露，溫潤冰冷心靈，<br/>在祂慈愛臉光之下，偶像陰影遁形。<br/>',NULL,21826,1);
INSERT INTO stanza VALUES('CS466','chorus','新的黎明，新的復興，主我奉獻，奉獻今天；<br/>靠你得勝，因你更新，直到恩主顯現。<br/>',NULL,21827,2);
INSERT INTO stanza VALUES('CS466','2','時刻扎根主裏，生活開花發芽；<br/>天天起來拾取嗎哪，愛慕追求主話。<br/>不住恆切禱告，單純如百合花，<br/>灌滿新酒和橄欖油，散發基督榮華。<br/>',NULL,21828,3);
INSERT INTO stanza VALUES('CS466','3','主必加倍補還，蝗蟲吃去時光，<br/>祂的復活生命大能，吞滅失敗死亡。<br/>藉祂不斷顯現，步步唱上行詩，<br/>今生功名煙消雲逝，譜寫神聖歷史。<br/>',NULL,21829,4);
INSERT INTO stanza VALUES('CS466','4','不再勞碌經營，自己破爛草廈，<br/>同心合意上山取木，起來建造神家。<br/>清理打開家門，迎接萬邦罪人，<br/>彼此歡呼帶回禾捆，牧養群羊歸神。<br/>',NULL,21830,5);
INSERT INTO stanza VALUES('CS466','5','復興之律來臨，晝夜循環不息；<br/>隨時隨地洋溢讚美，福音遍傳四極。<br/>團體神人生活，在地如同在天，<br/>求主時刻保守我們，新鮮直到主前。<br/>',NULL,21831,6);
INSERT INTO stanza VALUES('CS467','1','榮耀的基督這超越的寶貝，<br/>吸引我們打破玉瓶，<br/>並將一切全然枉費在祂身上；<br/>枉費在祂身上；<br/>燔祭壇上的火要一直燒著，不可熄滅，<br/>好使我們消減成灰，<br/>而成為新耶路撒冷。<br/>我們在帳棚裏過團體神人生活，<br/>並接受國度的操練，<br/>好對世界作相反的見證；<br/>為著時期滿足時的經綸，<br/>我們需要打開家並栽種召會樹，<br/>好成為萬邦的祝福。<br/>我們需要打開家並栽種召會樹，<br/>好成為萬邦的祝福。<br/>',NULL,21832,1);
INSERT INTO stanza VALUES('CS468','1','誰能配如此的枉費?<br/>誰會肯如此的犧牲;<br/>誰能述說這樣的結果!<br/>誰能擁有這樣的豐收!<br/>雖已杯傾卻仍滿溢!<br/>雖已盤罄卻仍滿席!<br/>從未求福卻叫別人得福,<br/>未嘗求報卻叫別人得飽。<br/>不再受縛,不再無奈;<br/>不再作難,不再悲哀;<br/>永遠湧流,永遠施愛;<br/>永遠傾捨,永遠澎湃。<br/><br/>甘心以死亡換來生命的溢洋。<br/>甘心受破碎以散發復活馨香。<br/>這正是你留下的腳蹤,<br/>呼召人默默的跟從。<br/>從他們那臉上的笑容,<br/>看見遙遠榮耀的路終。<br/><br/>我已算清這條道路的代價,<br/>就此樂意為你把一切放下;<br/>只願成為供應人喜樂的奠祭,<br/>不斷傾倒直至此生止極。<br/>主阿,讓我愛!你作我賞賚!<br/>讓你的同在永遠不離開。<br/>使我維持你裡面的喜樂,<br/>讓我的眼淚消失在永世。<br/>',NULL,21833,1);
INSERT INTO stanza VALUES('CS469','1','歌中之歌乃是描繪,<br/>神生命與建造;<br/>基督新婦生命歷程,<br/>皆顯明於表號,<br/>皆顯明於表號。<br/>',NULL,21834,1);
INSERT INTO stanza VALUES('CS469','2','她之愛主初如駿馬,<br/>屬世牽連未斷;<br/>奔跑迅捷、力大無匹,<br/>剛強卻是天然,<br/>剛強卻是天然!<br/>',NULL,21835,2);
INSERT INTO stanza VALUES('CS469','3','觀念逐日因主改變,<br/>眼目漸似鴿眼;<br/>無何能與主愛比擬,<br/>惟非她所倚,<br/>惟主是她所羨,<br/>惟主是她所羨!<br/>',NULL,21836,3);
INSERT INTO stanza VALUES('CS469','4','她之於主有如百合,<br/>單純靠主憐憫;<br/>屬地勞苦非她所倚,<br/>惟主是她吸引,<br/>惟主是她吸引!<br/>',NULL,21837,4);
INSERT INTO stanza VALUES('CS469','5','在主面前又如良鴿,<br/>藏身磐石穴中,<br/>享主復活、升天生命,<br/>有愛不知驚恐,<br/>有愛不知驚恐!<br/>',NULL,21838,5);
INSERT INTO stanza VALUES('CS469','6','且成煙柱,立地頂天,<br/>曠野流蕩止息;<br/>意志降服,與主合拍,<br/>馨香之氣盈溢,<br/>馨香之氣盈溢!<br/>',NULL,21839,6);
INSERT INTO stanza VALUES('CS469','7','看哪,竟成主的臥榻,<br/>在這駭人夜間,<br/>供主躺臥,使主安息,<br/>仇敵崩潰逃竄,<br/>仇敵崩潰逃竄!<br/>',NULL,21840,7);
INSERT INTO stanza VALUES('CS469','8','還要成為一乘華轎,<br/>為著將主盛裝;<br/>萬王之王藉她行動,<br/>在她得著彰顯,<br/>在她得著彰顯!<br/>',NULL,21841,8);
INSERT INTO stanza VALUES('CS469','9','利巴嫩木品質高貴,<br/>充滿復活人性;<br/>銀柱支撐─贖穩固,<br/>金底顯神性情,<br/>金底顯神性情!<br/>',NULL,21842,9);
INSERT INTO stanza VALUES('CS469','10','紫色坐墊君尊寶貴-<br/>王權為其座位;<br/>眾女向王所獻愛情,<br/>盡都鋪陳其內,<br/>盡都鋪陳其內!<br/>',NULL,21843,10);
INSERT INTO stanza VALUES('CS469','11','婚娶日近,心中歡喜,<br/>王要得勝凱歸;<br/>得著佳偶作祂榮冕,<br/>與祂全然匹配,<br/>與祂全然匹配。<br/>',NULL,21844,11);
INSERT INTO stanza VALUES('CS469','12','關鎖的園,只為良人<br/>產生寶貴材料;<br/>生命豐盛、美麗芬芳,<br/>更為神聖建造,<br/>更為神聖建造。<br/>',NULL,21845,12);
INSERT INTO stanza VALUES('CS469','13','佳偶屹立猶如京城,<br/>益顯華麗秀美;<br/>又如軍隊展開旌旗,<br/>威武,使敵敗退,<br/>威武,使敵敗退!<br/>',NULL,21846,13);
INSERT INTO stanza VALUES('CS469','14','藉著喫主與祂聯調,<br/>新婦妝飾整齊;<br/>生命變化帶進建造,<br/>成功神聖旨意,<br/>成功神聖旨意。<br/>',NULL,21847,14);
INSERT INTO stanza VALUES('CS470','1','神聖真理深廣無邊,<br/>人智豈能侷限?<br/>一己殘見,囿於時空,<br/>勿將天光遮掩。<br/>嶄新亮光,更美盼望,<br/>惟願人心能見:<br/>主話真光越照越明,<br/>釋放真理無限。<br/>',NULL,21848,1);
INSERT INTO stanza VALUES('CS470','2','天來聖諭普賜萬邦,<br/>歷代人當稱羨;<br/>誰竟擅用無知言語,<br/>阻擋神聖意念?<br/>如同宇宙闊長高深,<br/>浩瀚洋海無邊:<br/>主話真光越照越明,<br/>釋放真理無限。<br/>',NULL,21849,2);
INSERT INTO stanza VALUES('CS470','3','先聖邁開追尋旅程,<br/>暗中摸索而前;<br/>晨光乍顯,旭輝漸明,<br/>直至如日中天。<br/>榮耀太陽,願你顯身,<br/>輝煌光線盡現。<br/>主話真光越照越明,<br/>釋放真理無限。<br/>',NULL,21850,3);
INSERT INTO stanza VALUES('CS470','4','幽谷已過,昂首上行,<br/>直攻真理之巔;<br/>前人肩上極目一覽,<br/>始識主智深遠;<br/>清明空中,天樂得聆,<br/>纔知主富綿延:<br/>主話真光越照越明,<br/>釋放真理無限。<br/>',NULL,21851,4);
INSERT INTO stanza VALUES('CS470','5','哦願父神藉靈運行,<br/>基督安家心間,<br/>好使眾聖能同領畧,<br/>神聖大愛艱言;<br/>如此神聖實際得以<br/>日日加增不斷:<br/>主話真光越照越明,<br/>釋放真理無限。<br/>',NULL,21852,5);
INSERT INTO stanza VALUES('CS534','1','哦,主將我帕子去除,<br/>賜下真實啟示;<br/>哦,主使我異象清楚,<br/>知你恢復所是。<br/>',NULL,21853,1);
INSERT INTO stanza VALUES('CS534','2','你從死裏復活能力,<br/>我藉啟示知悉;<br/>大能傳輸藉信經歷,<br/>引我到召會裏。<br/>',NULL,21854,2);
INSERT INTO stanza VALUES('CS534','3','你的大能將我釋放,<br/>脫離煩擾俗務;<br/>你的大能為我開廣<br/>進入召會路途。<br/>',NULL,21855,3);
INSERT INTO stanza VALUES('CS534','4','我今進入地方召會,<br/>願以你為人位;<br/>外面舊人日漸銷毀,<br/>心向你能絕對。<br/>',NULL,21856,4);
INSERT INTO stanza VALUES('CS534','5','我接受你作人位主,<br/>與你同釘十架;<br/>裏面之人得著恢復,<br/>你在我心安家。<br/>',NULL,21857,5);
INSERT INTO stanza VALUES('CS534','6','當眾肢體都願捨己,<br/>榮耀身體得顯;<br/>人數雖多,人位同一,<br/>新人在地出現。<br/>',NULL,21858,6);
INSERT INTO stanza VALUES('CS534','7','召會生活─一個新人,<br/>顯於各地召會;<br/>你的身體是團體人,<br/>顯出一個人位。<br/>',NULL,21859,7);
INSERT INTO stanza VALUES('CS535','1','基督聖心深愛慕,<br/>無他,惟有召會;<br/>言語、計畫並行動,<br/>皆以她為依歸。<br/>此情此意永堅定,<br/>無何能以搖撼;<br/>召會縈繞祂心頭,<br/>遠在創世之前。<br/>',NULL,21860,1);
INSERT INTO stanza VALUES('CS535','2','萬有尚都未開始,<br/>祂已籌畫全備,<br/>要得祂心所鍾愛,<br/>與祂喜悅匹配。<br/>萬物受造雖奇妙,<br/>並非祂所專注;<br/>深藏祂心難追測,<br/>乃一榮耀新婦。<br/>',NULL,21861,2);
INSERT INTO stanza VALUES('CS535','3','贏得佳偶相與共,<br/>是祂所最心許;<br/>美哉,此情永不移,<br/>此意始終不渝。<br/>人雖被罪深誘害,<br/>無助、無望、無倚;<br/>祂心所望從未棄,<br/>戀慕之情依依。<br/>',NULL,21862,3);
INSERT INTO stanza VALUES('CS535','4','祂愛何廣難估量,<br/>藉祂憐憫臨及;<br/>親自施恩來找尋,<br/>深哉,智慧無匹。<br/>傾注愛情得她心,<br/>此愛惟神盡知;<br/>傾倒祂命作祭物,<br/>馨香上揚不止。<br/>',NULL,21863,4);
INSERT INTO stanza VALUES('CS535','5','今在復活榮耀裏,<br/>與她親近無距,<br/>祂的笑臉時顯露,<br/>情深,難以言喻。<br/>日近一日,祂新婦<br/>單單將祂注視,<br/>浸沐新郎榮耀中,<br/>等候被提之時。<br/>',NULL,21864,5);
INSERT INTO stanza VALUES('CS536','1','何等可愛,哦,何寶貴,<br/>是主眾地方召會!<br/>我魂羨慕,甚至渴想,<br/>主,你院宇極華美。<br/>我心渴慕,我靈切望<br/>能交通於眾召會;<br/>為此我向活神呼籲,<br/>我心、我命不別歸。<br/>',NULL,21865,1);
INSERT INTO stanza VALUES('CS536','2','心中想往錫安大道,<br/>如此之人為有福;<br/>必因我主行走有力,<br/>終日頌讚與稱祝。<br/>召會生活時有樂歌,<br/>因靠我神勝險阻;<br/>雖經巴迦流淚之谷,<br/>卻使成為泉源處。<br/>',NULL,21866,2);
INSERT INTO stanza VALUES('CS536','3','在你召會住留一日,<br/>勝似別處住千日;<br/>我主乃是日頭、盾牌,<br/>至微肢體亦得恃。<br/>恩典、榮耀從主傾注,<br/>無一好處祂不賜;<br/>如此安居召會之中,<br/>必蒙祝福永無止。<br/>',NULL,21867,3);
INSERT INTO stanza VALUES('CS537','1','當日挪亞照神吩咐,努力建造方舟,<br/>多人觀看,他的話卻無人留意、接受;<br/>惟獨挪亞蒙恩,聽見神話語謹遵守,<br/>全心建造方舟,不浪費任何的時候。<br/>',NULL,21868,1);
INSERT INTO stanza VALUES('CS537','chorus','今日耶穌的見證,已向我們顯明:<br/>見證的方舟建立在眾地方召會中。<br/>',NULL,21869,2);
INSERT INTO stanza VALUES('CS537','2','那時的世代墮落、彎曲、悖謬又腐朽,<br/>地上的罪惡甚大,人心邪惡無可救;<br/>但挪亞持守異象,抵擋放蕩的潮流,<br/>不計較任何代價,建造見證的方舟。<br/>',NULL,21870,3);
INSERT INTO stanza VALUES('CS537','3','當時也有多人說他們是在敬拜神,<br/>他們事奉、獻祭,卻不能有分神救恩;<br/>神所渴望建造,他們不恥、不願過問,<br/>思念屬地之事,以致與惡者同浮沉。<br/>',NULL,21871,4);
INSERT INTO stanza VALUES('CS537','4','一日,方舟建成,神將八人關入裏頭,<br/>天上窗戶盡都敞開,大雨傾瀉不休;<br/>水勢浩力,但方舟內挪亞安息無憂,<br/>地雖淹沒,他卻漂浮其上,安全得救。<br/>',NULL,21872,5);
INSERT INTO stanza VALUES('CS537','5','這方舟就是當代神在地得勝見證,<br/>是一個團體的人,將神榮總全顯明;<br/>神也要我們同被建造,顯出祂豐盛,<br/>使神顯現於肉體,在眾地方召會中。<br/>',NULL,21873,6);
INSERT INTO stanza VALUES('CS537','6','儆醒!莫隨洪流浮沉而偏離神心意;<br/>當讓耶穌的見證如火在我心燃起!<br/>地方召會乃是方舟,將神見證無遺,<br/>為此我們獻上自己,現今世代遠離。<br/>',NULL,21874,7);
INSERT INTO stanza VALUES('CS538','1','在眾召會湧流不息─弟兄相愛;<br/>生命、光、愛,流通、洋溢─弟兄相愛。<br/>聯結為一,毫無猜忌;<br/>照神接納,不憑人意;<br/>不再讓神聖靈憂戚─弟兄相愛。<br/>',NULL,21875,1);
INSERT INTO stanza VALUES('CS538','2','愛中洗滌,交通無礙─弟兄相愛;<br/>以愛裹傷,彼此懷搋─弟兄相愛。<br/>凡事相信,凡事忍耐,<br/>凡事盼望,凡事遮蓋;<br/>彼此擔就,恩慈相待─弟兄相愛。<br/>',NULL,21876,2);
INSERT INTO stanza VALUES('CS538','3','猶如枝子結果豐盈─弟兄相愛;<br/>又是肢體同命同榮─弟兄相愛。<br/>棄絕天然,己命不從,<br/>只隨那靈,狹路前行;<br/>出死入生在此證明─弟兄相愛。<br/>',NULL,21877,3);
INSERT INTO stanza VALUES('CS538','4','歡然上行,樂歌四起─弟兄相愛!<br/>懼怕、憂疑盡都絕迹─弟兄相愛!<br/>和睦同居,美善無比,<br/>靈與生命─堅固根基;<br/>建造錫安,達到終極─弟兄相愛。<br/>',NULL,21878,4);
INSERT INTO stanza VALUES('CS538','5','生命種子生長不已─弟兄相愛;<br/>“非拉鐵非”湧流、普及─弟兄相愛。<br/>主名、主話,持守不離,<br/>神聖之愛澆灌、充溢;<br/>得勝有餘,無何能敵─弟兄相愛!<br/>',NULL,21879,5);
INSERT INTO stanza VALUES('CS539','1','愛的召會─非拉鐵非,<br/>請聽榮耀的事實;<br/>天上聖別、真實的主,<br/>述說關於你的事。<br/>國度之門由祂掌管,<br/>大衞鑰匙祂手持;<br/>“我已開門,無人能關”─<br/>祂話既出必如是。<br/>',NULL,21880,1);
INSERT INTO stanza VALUES('CS539','2','阿利路亞!非拉鐵非,<br/>行為、工作主悅納;<br/>看哪,主賜敞開的門,<br/>無人比你更通達。<br/>因你稍微有點能力,<br/>也曾持守祂活話;<br/>未曾否認祂的聖名,<br/>忠信見證殊可嘉。<br/>',NULL,21881,2);
INSERT INTO stanza VALUES('CS539','3','蒙愛召會,非拉鐵非,<br/>忍耐的話既遵守,<br/>主必保守,免你經過<br/>全地試煉的時候。<br/>你的仇敵終必俯伏,<br/>知主愛你到永久;<br/>“我必快來,你要持守,<br/>免得冠冕被奪走。”<br/>',NULL,21882,3);
INSERT INTO stanza VALUES('CS539','4','阿利路亞!得勝信徒<br/>必定從主得奬賞;<br/>在神殿中不再出去,<br/>作為柱子顯堅剛。<br/>神的聖名、主的新名,<br/>聖城之名寫身上;<br/>三一之神與人聯結,<br/>互住、調和顯輝煌。<br/>',NULL,21883,4);
INSERT INTO stanza VALUES('CS539','5','耶路撒冷從天而降,<br/>神聖新城何榮耀;<br/>珍珠之門、碧玉城牆,<br/>珍貴材料同建造。<br/>非拉鐵非─弟兄相愛─<br/>得勝新婦主所要;<br/>眾召會中,凡有耳者,<br/>當聽那靈在呼召!<br/>',NULL,21884,5);
INSERT INTO stanza VALUES('CS540','1','榮耀異象，我已看見；神的經綸是我人生意義！ <br/>屬地纏累，我已全棄；主的恢復是我全心所傾！ <br/>神聖三一，神聖分賜，基督作生命，那靈為實際； <br/>神的召會，基督身體，新耶路撒冷，聖城我所期。<br/>',NULL,21885,1);
INSERT INTO stanza VALUES('CS540','chorus','主！我們再獻上自己，一生交你訓練手裡， <br/>製作、甄陶，不斷經歷，成神尊貴、榮耀大器！ <br/>深願主恢復的獨特，作我生活、工作標記， <br/>建造身體，豫備新婦，接你再來，滿足你心意！<br/>',NULL,21886,2);
INSERT INTO stanza VALUES('CS540','2','天上人間有一生活；生機聯結裡，神人同生活； <br/>復活大能全備供應，模成基督之死，不再是我！ <br/>隨主榜樣，步祂腳蹤，出宗教營外，幔內過生活， <br/>與神同行，服於元首；成宇宙新人，帶進神的國。<br/>',NULL,21887,3);
INSERT INTO stanza VALUES('CS540','3','同作肢體，相互提攜，愛裡同建造，靈中共勉勵； <br/>分賜基督，供應那靈，我們相調和，在主裡合一。 <br/>拚上全人，同心合意，實行活力排，建造主身體； <br/>廣傳福音，教導真理，照著神牧養，達到新復興。<br/>',NULL,21888,4);
INSERT INTO stanza VALUES('CS540','4','錫安大道，心中想往，雖經流淚谷，前進不稍退； <br/>我們願付一切代價，顧到神權益，異象永不違。 <br/>不讓我主再受遲延，作祂得勝者，鋪路迎祂歸， <br/>擊敗仇敵，與祂同王，神經綸高峰---錫安何華美！<br/>',NULL,21889,5);
INSERT INTO stanza VALUES('CS541','1','神造萬有美好、有序,<br/>徧佈天、地、空中;<br/>仇敵竟來敗壞、佔據,<br/>阻撓神旨完成。<br/>那權能者恣意背判,<br/>先來將地篡奪;<br/>又在空中蓄勢爭戰,<br/>建立黑暗之國。<br/>',NULL,21890,1);
INSERT INTO stanza VALUES('CS541','2','神的心意是要在地<br/>建立祂的國度,<br/>好使祂能掌權治理,<br/>顯明祂智豐足。<br/>地雖荒廢,淵面黑暗,<br/>神來恢復、再造,<br/>且按祂的神聖意念,<br/>造人與祂相肖。<br/>',NULL,21891,2);
INSERT INTO stanza VALUES('CS541','3','惡者撒但又將人騙,<br/>誘離神恩源頭;<br/>亞伯拉罕見神顯現,<br/>蒙召族類起首。<br/>神領選民脫離埃及,<br/>經過紅海、野疆,<br/>進入迦南應許美地,<br/>神國在此彰顯。<br/>',NULL,21892,3);
INSERT INTO stanza VALUES('CS541','4','以色列民竟棄神治,<br/>屬地君主依恃;<br/>神國彰顯再次喪失,<br/>直至大衞之時;<br/>藉他神得執政道路,<br/>神國重新恢復;<br/>百姓終究仍是失誤,<br/>被擄,失去國度。<br/>',NULL,21893,4);
INSERT INTO stanza VALUES('CS541','5','人雖不堪,神不失敗,<br/>親來成為肉身;<br/>向人宣告“:應當悔改!<br/>因為國度臨近。”<br/>神人耶穌,完美絕佳,<br/>為神權柄執掌;<br/>撒但將祂釘死十架,<br/>不過顯其愚妄。<br/>',NULL,21894,5);
INSERT INTO stanza VALUES('CS541','6','妙哉,耶穌救贖成就,<br/>復活勝過死亡,<br/>為要使地得蒙拯救,<br/>脫離撒但捆綁;<br/>且成那靈進入人裏,<br/>召會藉此建立─<br/>生命洋溢,混亂消弭,<br/>神旨通行於地。<br/>',NULL,21895,6);
INSERT INTO stanza VALUES('CS541','7','如今召會在地顯明,<br/>神國豐滿實際;<br/>神聖權柄盡得通行,<br/>使地歸神管理。<br/>我們在此為神執政,<br/>撒但只能逃遁;<br/>如此召會作神見證,<br/>國度不再藏隱。<br/>',NULL,21896,7);
INSERT INTO stanza VALUES('CS542','1','主的恢復需要我們<br/>歸回顧到神權益;<br/>出到營外勝過墮落,<br/>建造召會主身體。<br/>靈中站住合一立場,<br/>持守基督作生命;<br/>陳明真理至死忠信,<br/>作主獨一活見證。<br/>',NULL,21897,1);
INSERT INTO stanza VALUES('CS542','chorus','何其憐憫,我們得以<br/>一生作你獨特子民;<br/>為你恢復我們全傾,<br/>緊緊跟隨不稍偏離。<br/>終極異象管制規律,<br/>枉費一切為你身體;<br/>同奔賽程神旨得成,<br/>榮耀新婦迎你再臨!<br/>',NULL,21898,2);
INSERT INTO stanza VALUES('CS542','2','榮耀召會為神所有,<br/>純潔無瑕何神聖;<br/>憑神生命活神性情,<br/>窄門狹路靈中行。<br/>照神旨意生活事奉,<br/>偉大成就非我望;<br/>憑著禱告、那靈與話,<br/>與神同工同前往。<br/>',NULL,21899,3);
INSERT INTO stanza VALUES('CS542','3','獨一之神獨一心意,<br/>獨一經綸已開啟;<br/>三一神裏神聖的一,<br/>擴大彰顯於身體。<br/>獨一水流全人投進,<br/>同心合意來事奉;<br/>獨一交通、獨一工作,<br/>終極完成於撒冷。<br/>',NULL,21900,4);
INSERT INTO stanza VALUES('CS542','4','時代異象、時代職事,<br/>同負一軛同腳蹤;<br/>留在其中抵擋敗落,<br/>健康話語當遵從。<br/>使徒教訓成我口味,<br/>不同教訓不容忍。<br/>同吹獨一爭戰號聲,<br/>忠信教導神經綸。<br/>',NULL,21901,5);
INSERT INTO stanza VALUES('CS543','1','倘若我躭延,你也可以知道<br/>在神的家中當怎樣行;<br/>這家就是活神的召會,<br/>真理的柱石和根基。<br/>並且,大哉!敬虔的奧祕!<br/>這是眾所公認的,就是:<br/>祂顯現於肉體,被稱義於靈裏,<br/>被天使看見,被傳於萬邦,<br/>被信仰於世人中,被接去於<br/>榮耀裏,被接去於榮耀裏。<br/>',NULL,21902,1);
INSERT INTO stanza VALUES('CS619','1','“同心合意”─樓房上同聚集,<br/>耶穌從者忠信禱告不息;<br/>同一盼望,每魂儆醒所期;<br/>同一目標,眾人心志如一。<br/>',NULL,21903,1);
INSERT INTO stanza VALUES('CS619','2','“同心合意”─直等五旬能力<br/>全備靈中降臨,澆灌、充溢;<br/>眾見證人宣揚復活信息,<br/>活出神命開拓及於地極。<br/>',NULL,21904,2);
INSERT INTO stanza VALUES('CS619','3','“同心合意”─神家中何歡暢,<br/>阿利路亞!天天讚美頌揚;<br/>一心一口,基督榮耀顯彰,<br/>耶穌尊名傳揚達到四方。<br/>',NULL,21905,3);
INSERT INTO stanza VALUES('CS619','4','那靈澆灌,我們願再經歷,<br/>如同甘雨,使人復甦、得力;<br/>主的子民若真同心合意,<br/>五旬榮景就必重現此地。<br/>',NULL,21906,4);
INSERT INTO stanza VALUES('CS620','1','讚美父神是生命源頭,<br/>我們在你寶貴名裏,<br/>作你眾子來彰顯你。<br/>讚美父神是生命源頭。<br/>在生命裏,在生命裏,<br/>在父生命裏我們是一。<br/>在生命裏,在生命裏,<br/>在父生命裏我們是一。<br/>',NULL,21907,1);
INSERT INTO stanza VALUES('CS620','2','感謝父藉你寶貴聖言,<br/>用你性情浸透我們,<br/>分別我們脫離俗塵。<br/>感謝父賜你寶貴聖言。<br/>藉你聖言,藉你聖言,<br/>藉你聖言我們成為一。<br/>',NULL,21908,2);
INSERT INTO stanza VALUES('CS620','3','哦,三一神的神聖榮耀!<br/>眾子得享何等福分!<br/>神的榮耀彰顯無盡─。<br/>哦三一神的神聖榮耀!<br/>在榮耀裏,在榮耀裏,<br/>在你榮耀裏我們是一。<br/>',NULL,21909,3);
INSERT INTO stanza VALUES('CS621','1','讓我們同來聚集擘餅，<br/>讚美主！因祂使我們成為一。<br/>飽嘗祂，眾人同心合意，<br/>作祂召會，全歸祂自己。<br/>',NULL,21910,1);
INSERT INTO stanza VALUES('CS621','chorus','聖徒們，我們喫餅喝杯；<br/>在主裏我們是一。<br/>喫喝享受，建造在一起；<br/>見證基督身體的實際。<br/>',NULL,21911,2);
INSERT INTO stanza VALUES('CS621','2','讓我們同來聚集喝杯─是召會，<br/>寶血所買，珍貴無比；<br/>蒙救贖，眾人同心合意，<br/>成就祂永遠經綸目的。<br/>',NULL,21912,3);
INSERT INTO stanza VALUES('CS621','chorus','聖徒們，我們喫餅喝杯；<br/>在主裏我們是一。<br/>喫喝享受，建造在一起；<br/>見證基督身體的實際。<br/>',NULL,21913,4);
INSERT INTO stanza VALUES('CS621','3','讓我們一同堅定站立─是身體，<br/>就不再作孤單子粒；<br/>相調和，眾人同心合意，<br/>成為一餅，彰顯在各地。<br/>',NULL,21914,5);
INSERT INTO stanza VALUES('CS621','chorus','聖徒們，我們喫餅喝杯；<br/>在主裏我們是一。<br/>喫喝享受，建造在一起；<br/>見證基督身體的實際。<br/>',NULL,21915,6);
INSERT INTO stanza VALUES('CS621','4','讓我們作神合一子民，齊宣告：<br/>我們是一，不再分離；<br/>有真理，也有生命經歷，<br/>見證神作為何等希奇。<br/>',NULL,21916,7);
INSERT INTO stanza VALUES('CS621','chorus','聖徒們，我們喫餅喝杯；<br/>在主裏我們是一。<br/>喫喝享受，建造在一起；<br/>見證基督身體的實際。<br/>',NULL,21917,8);
INSERT INTO stanza VALUES('CS621','5','讓我們同來聚集擘餅，<br/>讚美主！因祂使我們成為一。<br/>飽嘗祂，眾人同心合意，<br/>作祂召會，全歸祂自己。<br/>',NULL,21918,9);
INSERT INTO stanza VALUES('CS622','1','看哪!桌上擺設筵席,<br/>一餅一杯,神聖表記;<br/>親愛救主熱切邀集,<br/>我們歡喜來坐席。<br/>祂來呼召,神、人同席,<br/>顯明救主永遠心意;<br/>豐富供應,全備、洋溢,<br/>前來同享勿遲疑。<br/>',NULL,21919,1);
INSERT INTO stanza VALUES('CS622','2','我們現在與祂同席,<br/>祂與我們何等親近;<br/>阿利路亞!讚美不已!<br/>上好筵席無止盡。<br/>喫喝享受主的自己,<br/>滿足我們全人全心;<br/>豫嘗那日榮耀筵席,<br/>作祂新婦何歡欣。<br/>',NULL,21920,2);
INSERT INTO stanza VALUES('CS623','1','哦主你筵席榮耀無比!<br/>我們蒙召同你坐席,<br/>與你同住,在你家裏;<br/>哦主,你筵席榮耀無比!<br/>',NULL,21921,1);
INSERT INTO stanza VALUES('CS623','chorus','阿利路亞!阿利路亞!<br/>阿利路亞,為這筵席。<br/>阿利路亞!阿利路亞!<br/>哦主,你筵席榮耀無比!<br/>',NULL,21922,2);
INSERT INTO stanza VALUES('CS623','2','哦主,你筵席何等享受!<br/>在你桌前,交通自由!<br/>阿利路亞!尋見所求;<br/>哦主,你筵席榮耀無比!<br/>',NULL,21923,3);
INSERT INTO stanza VALUES('CS623','3','哦主,你筵席實在寶貴!<br/>宣告你死,陳列餅杯,<br/>我魂生命再無地位,<br/>全因你筵席豐富全備。<br/>',NULL,21924,4);
INSERT INTO stanza VALUES('CS623','4','哦主,你筵席富有意義!<br/>餅指我們是你身體,<br/>因著你愛,我們是一;<br/>哦主,你筵席富有意義!<br/>',NULL,21925,5);
INSERT INTO stanza VALUES('CS623','5','哦主,你筵席令人舒暢!<br/>何等滿足,將你全享,<br/>得著供應,無限無量;<br/>哦主,你筵席令人舒暢!<br/>',NULL,21926,6);
INSERT INTO stanza VALUES('CS623','6','哦主,你筵席將我激勵!<br/>“直到你來”堅定不移,<br/>日日等候,盼望見你;<br/>哦主,你筵席將我激勵!<br/>',NULL,21927,7);
INSERT INTO stanza VALUES('CS624','1','今日惟有識你身體,<br/>哦主,纔是認識你,<br/>因此我求得蒙開啟,<br/>在你肢體看見你;<br/>非僅識你元首身分─<br/>至高、個別救贖主,<br/>更見你已具體化身,<br/>顯為身體的基督。<br/>',NULL,21928,1);
INSERT INTO stanza VALUES('CS624','2','你的聖徒多年追求,<br/>渴慕尋得你實際;<br/>舉目仰望,深處探求,<br/>無非要見你自己。<br/>豈知天上榮耀基督,<br/>今乃顯為祂身體;<br/>內住基督今正活出,<br/>在祂身體顯無遺!<br/>',NULL,21929,2);
INSERT INTO stanza VALUES('CS624','3','主,我自知易於受欺,<br/>僅識你崇高至極,<br/>卻未摸著你的實際,<br/>暗中摸索,憑己意。<br/>豈知在你地上肢體,<br/>我就得見你自己!<br/>永遠之神顯於肉體,<br/>大哉,敬虔的奧祕!<br/>',NULL,21930,3);
INSERT INTO stanza VALUES('CS624','4','求主勿讓我再單獨,<br/>囿於個人的光照;<br/>你的身體促我投入,<br/>憑“身體感”為引導。<br/>不再作那離散塵土,<br/>乃是活石被建造;<br/>如此使你心滿意足,<br/>團體顯明你榮耀。<br/>',NULL,21931,4);
INSERT INTO stanza VALUES('CS625','1','我們是神救贖子民,<br/>照祂計畫成一個新人;<br/>雖來自各民族方言,<br/>祂裏蒙召,合一何甘甜。<br/>是神榮耀顯於地,<br/>將祂寶貴顯無遺;<br/>我們是神救贖子民<br/>照祂計畫成一個新人。<br/>',NULL,21932,1);
INSERT INTO stanza VALUES('CS625','2','十架上,規條全廢棄,<br/>猶太、外邦兩下成為一;<br/>主得勝,仇敵祂踐踏,<br/>我們與神和好,親“阿爸”。<br/>隔斷的牆已拆除,<br/>我們是一,喊“:哦,主!”<br/>十架上,規條全廢棄,<br/>猶太、外邦兩下成為一。<br/>',NULL,21933,2);
INSERT INTO stanza VALUES('CS625','3','主,我們願同心合意,<br/>接受你作人位,不偏離;<br/>不再憑雄心與己意,<br/>在“身體基督”裏調為一。<br/>一個新人在主裏,<br/>為神權益得全地;<br/>主,我們願同心合意<br/>接受你作人位,不偏離。<br/>',NULL,21934,3);
INSERT INTO stanza VALUES('CS626','1','我們在靈裏是一,<br/>憑神生命是一;<br/>我們過身體生活,<br/>一切分裂遠離;<br/>救贖已成,隔閡全去,<br/>主裏我們是一。<br/>',NULL,21935,1);
INSERT INTO stanza VALUES('CS626','chorus','(弟兄)<br/>弟兄們,我們是一,<br/>讚美主,讚美主!<br/><br/>(姊妹)<br/>姊妹們,我們是一,<br/>讚美主,讚美主!<br/><br/>(同聲)<br/>主已成就大事,<br/>使身體合一得恢復。<br/>',NULL,21936,2);
INSERT INTO stanza VALUES('CS626','2','我們在靈裏是一,<br/>同魂為神站立;<br/>這“一”從我們靈裏<br/>向外擴展不已-<br/>心思、情感、意志都被浸透,<br/>我們是一。<br/>',NULL,21937,3);
INSERT INTO stanza VALUES('CS626','3','我們在靈裏是一,<br/>在實際裏是一;<br/>“一”是我們的實行,<br/>並非空談、道理;<br/>在眾召會之中,<br/>我們享受一的實際。<br/>',NULL,21938,4);
INSERT INTO stanza VALUES('CS626','4','我們在靈裏是一,<br/>且在各地是一;<br/>為保守主賜的“一”,<br/>我們獻上自己,<br/>使這“一”彰顯於全地,<br/>叫世人都稱奇。<br/>',NULL,21939,5);
INSERT INTO stanza VALUES('CS627','1','看哪何等美善!弟兄和睦同居;<br/>以和平相結聯,所有距離全去。<br/>平安義果,神、人共享,<br/>弟兄相愛,喜樂歡暢。<br/>弟兄相愛,喜樂歡暢。<br/>',NULL,21940,1);
INSERT INTO stanza VALUES('CS627','2','眾聖相聯相依,跟隨羔羊緊緊;<br/>一靈、一心、一意、一口,為榮耀神;<br/>愛裏相調,緊密結聯,<br/>其樂無比,非人能言。<br/>其樂無比,非人能言。<br/>',NULL,21941,2);
INSERT INTO stanza VALUES('CS627','3','這“一”實際出現,帶來恩典無量;<br/>我們在地若天,因享甘露舒爽;<br/>上好膏油在此流淌,<br/>流自元首,眾聖同享。<br/>流自元首,眾聖同享。<br/>',NULL,21942,3);
INSERT INTO stanza VALUES('CS627','4','這“一”何等芬芳,因有恩膏溢漫;<br/>膏油四處放香,滋潤、浸透、充滿;<br/>凡受恩者無不讚美,<br/>滿口稱謝,滿臉光輝。<br/>滿口稱謝,滿臉光輝。<br/>',NULL,21943,4);
INSERT INTO stanza VALUES('CS627','5','凡神贖民都當有分於這膏袜;<br/>站住合一立場,享受福分包羅;<br/>膏油徧及鬍鬚、衣襟,<br/>大小肢體同蒙深恩。<br/>大小肢體同蒙深恩。<br/>',NULL,21944,5);
INSERT INTO stanza VALUES('CS627','6','上好油澆亞倫,黑門露降錫安;<br/>神所命定福分,豐盈且時加添;<br/>生命之福白白臨及,<br/>皆因有分寶貴合一。<br/>皆因有分寶貴合一。<br/>',NULL,21945,6);
INSERT INTO stanza VALUES('CS628','1','看哪,弟兄和睦同居,<br/>是何等的善,是何等的美!<br/>看哪,弟兄和睦同居,<br/>是何等的善,是何等的美!<br/>',NULL,21946,1);
INSERT INTO stanza VALUES('CS628','chorus','這好比那上好的油,<br/>上好的油,<br/>澆在亞倫的頭上,<br/>流到鬍鬚,<br/>又流到,流到他的衣襟;<br/>',NULL,21947,2);
INSERT INTO stanza VALUES('CS628','2','看哪,弟兄和睦同居,<br/>是何等的善,是何等的美!<br/>',NULL,21948,3);
INSERT INTO stanza VALUES('CS628','3','又好比黑門的甘露,降在錫安山;<br/>黑門的甘露,降在錫安山;<br/>因為在那裏有耶和華所命定的福,<br/>就是永遠的生命。<br/>',NULL,21949,4);
INSERT INTO stanza VALUES('CS629','1','榮耀基督顯現，引我全然奉獻；<br/>渴望以嘴親子，投奔入你裡面。<br/>神家是我心願，伯特利夢實現；<br/>孤獨者有居所，伯大尼家筵宴。<br/>赦免、相愛、相依，國度生活實際；<br/>和平、喜樂、公義，城中頌讚洋溢。<br/>校園、家與邦國，開展遍及全地；<br/>主名尊崇不已，見證直到地極。<br/>',NULL,21950,1);
INSERT INTO stanza VALUES('CS629','chorus','主，我願獻上自己， 建造你生機身體；<br/>打開家，得青年，牧養人，同成全，<br/>帶進榮耀召會，讓你能早歸回。<br/>',NULL,21951,2);
INSERT INTO stanza VALUES('CS753','1','主,我愛你國度,<br/>就是你的住處;<br/>是你召會,你血所贖,<br/>你將重價已付。<br/>',NULL,21952,1);
INSERT INTO stanza VALUES('CS753','2','神,我愛你召會,<br/>她與世俗分別;<br/>是你眼中惟一至美,<br/>手中惟一寶貝。<br/>',NULL,21953,2);
INSERT INTO stanza VALUES('CS753','3','為她禱告不歇,<br/>為她晝夜流淚;<br/>補滿基督患難缺欠,<br/>直至與你相會。<br/>',NULL,21954,3);
INSERT INTO stanza VALUES('CS753','4','她的屬天行徑,<br/>是我珍愛歌頌:<br/>相交甘甜,相許貞堅,<br/>愛戴、讚美無終。<br/>',NULL,21955,4);
INSERT INTO stanza VALUES('CS753','5','正如你的真理,<br/>必定屹立不已;<br/>那日錫安必得榮耀,<br/>光輝無比、至極。<br/>',NULL,21956,5);
INSERT INTO stanza VALUES('CS754','1','為主見證移民開展,<br/>誰願蒙恩向前走?<br/>何時?何處?照主差遣,<br/>恩主面光當尋求。<br/>',NULL,21957,1);
INSERT INTO stanza VALUES('CS754','2','為將聖殿、聖城建立,<br/>擴展神國及全地;<br/>背判征服,混亂消弭,<br/>同心合意眾如一。<br/>',NULL,21958,2);
INSERT INTO stanza VALUES('CS754','3','父乃源頭,子作管道,<br/>那靈湧流為憑藉;<br/>站住立場,靈中相調,<br/>此乃得勝的祕訣。<br/>',NULL,21959,3);
INSERT INTO stanza VALUES('CS754','4','主所籌畫偉大、完全,<br/>激動我們全奉獻;<br/>好讓聖靈浸透、充滿,<br/>神聖定旨得實現。<br/>',NULL,21960,4);
INSERT INTO stanza VALUES('CS754','5','今日在此學習多方:<br/>配搭建造、靈剛強;<br/>那日前往各城、各邦,<br/>建立燈臺顯榮光。<br/>',NULL,21961,5);
INSERT INTO stanza VALUES('CS754','6','諸天掌權需“灘頭堡”─<br/>地方召會─先建立;<br/>求主興起各地建造,<br/>實現國度為目的。<br/>',NULL,21962,6);
INSERT INTO stanza VALUES('CS754','7','那時,全地榮耀歸你,<br/>失敗、羞辱歸仇敵;<br/>萬民稱頌你名不已,<br/>國度掌權達至極。<br/>',NULL,21963,7);
INSERT INTO stanza VALUES('CS754','8','有福之日不久就到,<br/>榮耀經綸得成就;<br/>喜樂、讚美達到至高,<br/>神聖管治徧萬有。<br/>',NULL,21964,8);
INSERT INTO stanza VALUES('CS754','9','讚美聖父,阿利路亞,<br/>讚美聖子,阿利路,<br/>讚美聖靈,阿利路亞,<br/>神旨得成,阿利路。<br/>',NULL,21965,9);
INSERT INTO stanza VALUES('CS754','10','召會榮耀,阿利路亞,<br/>眾聖美善,阿利路,<br/>聚會美善,阿利路亞,<br/>誰不受感來歸服?<br/>',NULL,21966,10);
INSERT INTO stanza VALUES('CS754','11','阿利路亞,阿利路亞,<br/>阿利路亞,高聲唱,<br/>阿利路亞,阿利路亞,<br/>阿利路亞,讚我王!<br/>',NULL,21967,11);
INSERT INTO stanza VALUES('CS755','1','活基督者佳美蹤迹,<br/>應當效法且追隨;<br/>己意、己力不再憑倚,<br/>跟隨榜樣不羞愧。<br/>',NULL,21968,1);
INSERT INTO stanza VALUES('CS755','chorus','弟兄姊妹腳蹤佳美,<br/>活主生命何寶貴;<br/>如此榜樣應當跟隨,<br/>豫備新婦迎主歸。<br/>',NULL,21969,2);
INSERT INTO stanza VALUES('CS755','2','呼求主名取用寶血,<br/>佳美榜樣緊跟隨;<br/>如此跟隨,步履確切,<br/>必將仇敵全擊潰。<br/>',NULL,21970,3);
INSERT INTO stanza VALUES('CS755','3','當將心懷全然開啟,<br/>榜樣言語樂聽取;<br/>並非接受人言、人意,<br/>乃是領受神話語。<br/>',NULL,21971,4);
INSERT INTO stanza VALUES('CS755','4','如此,主話速速傳開,<br/>主的恢復達地極;<br/>神聖行動何能阻礙,<br/>神旨成功日可期。<br/>',NULL,21972,5);
INSERT INTO stanza VALUES('CS755','5','一路跟隨,不偏不倚,<br/>直至婚娶之日臨,<br/>直至新婦妝飾整齊,<br/>迎接羔羊同歡欣。<br/>',NULL,21973,6);
INSERT INTO stanza VALUES('CS756','1','我們今樂意跟隨眾召會,<br/>主裏是一,顯無遺;<br/>在眾召會中,主今正行動,<br/>堅定跟隨,眾如一。<br/>',NULL,21974,1);
INSERT INTO stanza VALUES('CS756','chorus','跟隨!跟隨主聖靈,<br/>單純跟隨,莫遲誤!<br/>跟隨!憑靈中羔羊,<br/>絕對跟隨,憑基督!<br/>',NULL,21975,2);
INSERT INTO stanza VALUES('CS756','2','我們今學習跟隨眾從者,<br/>流中往前無己意;<br/>時刻轉向靈,絕不望領頭,<br/>首位惟歸主自己。<br/>',NULL,21976,3);
INSERT INTO stanza VALUES('CS756','3','我們今歡然跟羊羣腳蹤,<br/>享受牧者的照應;<br/>在眾召會中,主今正引領,<br/>祂的發言當聆聽。<br/>',NULL,21977,4);
INSERT INTO stanza VALUES('CS756','4','我們今全然獻給主基督,<br/>緊緊跟隨不他依;<br/>不管何遭遇,隨羔羊前行,<br/>無論何往不稍離。<br/>',NULL,21978,5);
INSERT INTO stanza VALUES('CS756','5','一路緊跟隨,宜到進國度,<br/>羔羊婚筵樂有分;<br/>今縱有逼迫、痛苦和試煉,<br/>不過促我享主恩。<br/>',NULL,21979,6);
INSERT INTO stanza VALUES('CS756','6','在眾召會中,主今正召喚,<br/>忠信從者來得賞;<br/>我們願答應,全人都拚上,<br/>神旨成功不延宕。<br/>',NULL,21980,7);
INSERT INTO stanza VALUES('CS757','1','緊緊跟隨救主耶穌,<br/>靈中生活不遲誤;<br/>作得勝者,聽主招呼,<br/>心靠恩典得堅固。<br/>跟隨耶穌,作得勝者,<br/>靈中行事不憑己;<br/>跟隨耶穌,每時每刻─<br/>主,領我們跟隨你。<br/>',NULL,21981,1);
INSERT INTO stanza VALUES('CS757','2','緊緊跟隨主內弟兄,<br/>同心合意齊建造;<br/>互作肢體,生命流通,<br/>聯絡、結合精而牢。<br/>跟隨弟兄,同心建造,<br/>不再單獨來事奉;<br/>跟隨弟兄,彼此相調,<br/>守住等次盡功用。<br/>',NULL,21982,2);
INSERT INTO stanza VALUES('CS757','3','緊緊跟隨地方召會,<br/>為主恢復全奉獻;<br/>取得全地歸主支配,<br/>國度應許必實現。<br/>跟隨召會,獻上所有,<br/>同心為著主恢復;<br/>跟隨召會,投身水流,<br/>直到帶進主國度。<br/>',NULL,21983,3);
INSERT INTO stanza VALUES('CS757','4','主的聖言歡喜聆聽,<br/>必使我們得加力;<br/>惟主、召會、弟兄是從,<br/>羊羣腳蹤不偏離。<br/>跟隨耶穌、召會、弟兄,<br/>跟隨聖靈的水流;<br/>“阿們”主話,永不力窮,<br/>神旨必定得成就。<br/>',NULL,21984,4);
INSERT INTO stanza VALUES('CS758','1','藉著救主復活大能,<br/>我們已成祂弟兄─<br/>祂心所愛,復活所生,<br/>同祂得勝,同高升。<br/>',NULL,21985,1);
INSERT INTO stanza VALUES('CS758','chorus','耶穌基督,滿有那靈,<br/>宗教之外神顯明;<br/>死而復活,衝破幽冥,<br/>神眾子中作長兄。<br/>作祂召會,我們聚集,<br/>老套規條已全棄;<br/>長兄榮面,我們所喜,<br/>祂作中心和目的。<br/>',NULL,21986,2);
INSERT INTO stanza VALUES('CS758','2','長兄復起,我們亦同,<br/>歡喜聚集復活中;<br/>天然生命,惟願消蹤,<br/>使主喜樂並得榮。<br/>',NULL,21987,3);
INSERT INTO stanza VALUES('CS758','3','禱讀聖言,享受不已,<br/>天天遇見主自己;<br/>靈裏火熱,同來聚集,<br/>被主充滿且洋溢!<br/>',NULL,21988,4);
INSERT INTO stanza VALUES('CS758','4','每逢聚集都是赴席,<br/>喫主喝主,樂無比;<br/>祂作活糧,無量供給,<br/>滋養、滿足且加力。<br/>',NULL,21989,5);
INSERT INTO stanza VALUES('CS758','5','新鮮基督獻作“佳餚”,<br/>使主滿足、得榮耀;<br/>各人所獻儘管微小,<br/>卻叫眾人得建造。<br/>',NULL,21990,6);
INSERT INTO stanza VALUES('CS758','6','聚會非為傳講道理,<br/>乃為與主同聚集;<br/>祂的同在有何能比?<br/>長兄榮美真無匹!<br/>',NULL,21991,7);
INSERT INTO stanza VALUES('CS759','1','當主在地與人同聚,<br/>宗教、老套全撇棄;<br/>我們今日主裏聚集,<br/>儀文豈可再憑倚?<br/>哦,讓我們在復活裏,<br/>以主基督為實際,<br/>每逢聚集都是新樣,<br/>死沉、虛儀無蹤迹。<br/>',NULL,21992,1);
INSERT INTO stanza VALUES('CS759','2','主已復活,桎梏全除,<br/>宗教事物已過時;<br/>祂是活殿,是真供物,<br/>憑祂敬拜纔真實。<br/>阿利路亞,同主復活,<br/>何等釋放,何超脫!<br/>聚集過節,享受盛筵,<br/>貧窮、老舊都消沒。<br/>',NULL,21993,2);
INSERT INTO stanza VALUES('CS759','3','唉呀!宗教何其狡猾,<br/>墮落血輪中藏著;<br/>求主啟示,大光照亮,<br/>使那,惡魔無處躲。<br/>哦主,救我脫離宗教,<br/>脫開魂中的囚牢;<br/>每逢聚集將靈釋放,<br/>滿足神、人的需要。<br/>',NULL,21994,3);
INSERT INTO stanza VALUES('CS759','4','山上、海邊,處處可聚,<br/>主作實際當持守;<br/>活的基督,我們至愛,<br/>有祂同在復何求?<br/>埋葬宗教,除去老舊,<br/>靈中新樣神所寶;<br/>非“基督教,”乃是基督,<br/>纔是實際神所要。<br/>',NULL,21995,4);
INSERT INTO stanza VALUES('CS760','1','救主耶穌受死前,曾對彼得囑咐:<br/>仇敵會像篩麥子,想要得著門徒;<br/>但祂為我們祈求-真實且有能;<br/>阿利路亞,仇敵必不能得著我們!<br/>',NULL,21996,1);
INSERT INTO stanza VALUES('CS760','chorus','每天生活中都會經歷屬靈爭戰,<br/>走主道路者必定遇見試煉、艱難<br/>祂在一切境遇中,為我們代禱,<br/>祂的全備供應也滿足我們需要。<br/>',NULL,21997,2);
INSERT INTO stanza VALUES('CS760','2','單獨、孤立基督徒,無論如何剛強,<br/>在仇敵詭計之下仍然難以抵擋、<br/>我們活在身體中,就堅定站立;<br/>阿利路亞,仇敵必不能勝過身體!<br/>',NULL,21998,3);
INSERT INTO stanza VALUES('CS760','3','神為我們所命定旨意何等美妙;<br/>經歷變化,與基督同王,真是榮耀!<br/>我們有基督召會,仇敵不可畏;<br/>阿利路亞,仇敵必不能勝過召會!<br/>',NULL,21999,4);
INSERT INTO stanza VALUES('CS761','1','我們在主同在間,同心俯伏祂腳前;<br/>因著祂愛的感動,因著那靈的交通,<br/>甘心放下己榮耀,脫下外衣束上腰,<br/>存心卑微跟隨主,彼此洗腳作門徒。<br/>',NULL,22000,1);
INSERT INTO stanza VALUES('CS761','2','祂捨自己到至極,祂愛我們愛到底;<br/>我們與祂聯為一,不再保留魂與己。<br/>一人既替眾人死,眾人無法再自恃;<br/>跟隨受苦的腳蹤,彼此牧養作僕從。<br/>',NULL,22001,2);
INSERT INTO stanza VALUES('CS761','3','這是愛裏的服役,這是生命的洗滌;<br/>主既領先下尊位,甘以謙卑作巾圍。<br/>彼此服事盡恩愛,體貼救主的胸懷;<br/>藉此心再得暢快,洗盡世俗的塵埃。<br/>',NULL,22002,3);
INSERT INTO stanza VALUES('CS761','4','彼此饒恕相顧惜,愛裏扶持共勉勵;<br/>同樂同苦同淌淚,同活同行同依偎。<br/>彼此相愛世人睹,從此認出主門徒;<br/>保守我們心相繫,隱主肋旁不分離。<br/>',NULL,22003,4);
INSERT INTO stanza VALUES('CS762','1','我們都是主身上肢體,<br/>彼此相聯永不離,<br/>同來關心主在地權益,<br/>為此事奉纔合理,<br/>雖然在途中,<br/>經過許可的損失、疼痛,<br/>有分許多的患難交通,<br/>越發堅定而順從;<br/>沒有人單獨行動,<br/>你我都是弟兄,<br/>當一人受主感動,<br/>全體跟著向前衝,<br/>彼此扶持,苦樂與共,<br/>我只求這一生<br/>與你們同活在主身體中。<br/>',NULL,22004,1);
INSERT INTO stanza VALUES('CS762','2','就像迦勒陪同約書亞,<br/>爭戰為以色列家,<br/>並以利沙跟隨以利亞,<br/>同心放膽說主話,<br/>配搭的榜樣,<br/>保羅、西拉在靈裏剛強,<br/>身陷牢中仍讚美歌唱,<br/>神救恩大得顯彰;<br/>看我們臉上榮光更加有福、<br/>盼望同領受一個異象,<br/>沒有不同的方向,<br/>跟上時代隨主前往,<br/>使新路更開,<br/>廣願為神國度福音走四方。<br/>',NULL,22005,2);
INSERT INTO stanza VALUES('CS762','3','我們知道眼前所奔跑,<br/>非屬地康莊大道,<br/>還要經過主一再焚燒,<br/>煉淨我天然、愛好,<br/>儘管我渺小,常是輭弱,<br/>會沮喪跌倒,<br/>你們卻又把我帶回到<br/>主那起初的懷抱;<br/>我真是歡喜跳躍,<br/>有主作我至寶<br/>又能與你們聯調,<br/>沒有比這更美好,<br/>我要時時向外宣報,<br/>讓更多人進入<br/>基督與召會永遠的榮耀。<br/>',NULL,22006,3);
INSERT INTO stanza VALUES('CS850','1','我愛,我愛我恩主,<br/>不願自由外出;<br/>因祂是我救贖主,<br/>為我贖價已付。<br/>愛祂、事祂永不離,<br/>何其甘甜、蒙福;<br/>雖然有時會困倦,<br/>祂賜安息穩固。<br/>',NULL,22007,1);
INSERT INTO stanza VALUES('CS850','2','我主捨命流寶血,<br/>重價買我歸屬;<br/>救我脫離罪權勢,<br/>脫離己的束縛。<br/>祂既召我來事奉,<br/>我願甘心順服;<br/>如此永享真自由─<br/>愛中作祂奴僕。<br/>',NULL,22008,2);
INSERT INTO stanza VALUES('CS850','3','全心事奉不半途,<br/>惟有祂是我主;<br/>祂是愛我將命捨,<br/>我願永遠祂屬。<br/>我心感戴、靈歡騰,<br/>口中高歌不住:<br/>我愛,我愛我恩主,<br/>不願自由外出。<br/>',NULL,22009,3);
INSERT INTO stanza VALUES('CS851','1','求主發言,教導我舌,<br/>使我能言,照你心意;<br/>尋回愚蒙並失迷者,<br/>像你愛中細細尋覓。<br/>',NULL,22010,1);
INSERT INTO stanza VALUES('CS851','2','求主引導,使我有光,<br/>領浪蕩者歸回正途;<br/>供我飲食,使我有糧,<br/>餧養飢渴之徒無數。<br/>',NULL,22011,2);
INSERT INTO stanza VALUES('CS851','3','求主加力,使我得以<br/>穩踏基督磐石之上,<br/>且能伸出愛的膀臂,<br/>風暴海中救援喪亡。<br/>',NULL,22012,3);
INSERT INTO stanza VALUES('CS851','4','求主教我如何將你<br/>寶貴救恩向人陳述,<br/>使我言辭如有雙翼,<br/>及於人心,觸人深處。<br/>',NULL,22013,4);
INSERT INTO stanza VALUES('CS851','5','賜我以你甜美安息,<br/>使我言語應時如你,<br/>能施安撫,復甦、加力,<br/>使疲乏者都得再起。<br/>',NULL,22014,5);
INSERT INTO stanza VALUES('CS851','6','用你豐富充滿我心,<br/>直至滿溢恩典美辭:<br/>述說你愛,頌揚你恩,<br/>分賜生命、亮光不止。<br/>',NULL,22015,6);
INSERT INTO stanza VALUES('CS851','7','我雖不堪,願主使用,<br/>隨時、隨處照你喜悅;<br/>直至見你,榮耀之中,<br/>同享安息,喜樂不絕。<br/>',NULL,22016,7);
INSERT INTO stanza VALUES('CS852','1','興起!角聲發出,喜信傳佈;<br/>宣揚萬主之主─救主耶穌;<br/>述說祂名寶貴,高舉祂的尊位,<br/>好使萬眾來歸─耶穌是主!<br/>',NULL,22017,1);
INSERT INTO stanza VALUES('CS852','2','誰願為祂前去?誰願興起?<br/>地愛迷人難拒,為祂全棄:<br/>鄙視屬地榮華,萬事看為卑下,<br/>惟誇救主十架;誰願興起?<br/>',NULL,22018,2);
INSERT INTO stanza VALUES('CS852','3','得賞之日不遠,奮勇向前;<br/>晨星快要出現,不再遲延。<br/>高舉十架救恩,征服偶像、判民;<br/>惟盼有福之晨,與主相見。<br/>',NULL,22019,3);
INSERT INTO stanza VALUES('CS852','4','請聽勝利角聲,耶穌為王!<br/>基督登極執政,無能違抗:<br/>全地復歸祂有,惟祂居高為首,<br/>座前無不拜叩─耶穌為王!<br/>',NULL,22020,4);
INSERT INTO stanza VALUES('CS853','1','速興起傳福音!速搶救靈魂!<br/>請你看千萬人天天沉淪!<br/>莫塞住憐憫心,莫看重金銀,<br/>鬆開手傳福音,趁著現今。<br/>',NULL,22021,1);
INSERT INTO stanza VALUES('CS853','chorus','速興起傳福音!速搶救靈魂!<br/>你為何仍忍心,看人沉淪!<br/>',NULL,22022,2);
INSERT INTO stanza VALUES('CS853','2','人雖藐視真神,祂仍不灰心,<br/>要向人施憐憫,等待殷殷。<br/>人只要肯相信,必得享救恩,<br/>速前去向罪人勸誨諄諄!<br/>',NULL,22023,3);
INSERT INTO stanza VALUES('CS853','3','撒但雖將人擄,使人心麻木,<br/>神恩典能眷顧,將人恢復。<br/>心弦斷祂修復,用恩慈復甦,<br/>愛之樂又發出,遠勝當初!<br/>',NULL,22024,4);
INSERT INTO stanza VALUES('CS853','4','速興起傳福音!盡你我本分,<br/>作主工,靠主恩,不畏艱辛!<br/>生命路將人引,不吝惜耐心;<br/>使罪人都聽聞:神愛世人!<br/>',NULL,22025,5);
INSERT INTO stanza VALUES('CS854','1','洗罪之泉何其深廣,<br/>湧自耶穌肋旁!<br/>大能救主為我受戕,<br/>將我罪債清償。<br/>',NULL,22026,1);
INSERT INTO stanza VALUES('CS854','chorus','我見血泉流自加畧,<br/>立投此泉,使罪得潔!<br/>讚美救主為我流血,<br/>罪魁如我,竟也得潔!<br/>',NULL,22027,2);
INSERT INTO stanza VALUES('CS854','2','復活救主,我得看見,<br/>聽祂美言甘甜;<br/>更美之血為我美言,<br/>我靈甦醒、感讚。<br/>',NULL,22028,3);
INSERT INTO stanza VALUES('CS854','3','神前行走,光明無比,<br/>世俗罪污遠離;<br/>內得新心,外有白衣,<br/>基督居衷登極。<br/>',NULL,22029,4);
INSERT INTO stanza VALUES('CS855','1','豈能不高聲頌揚?<br/>豈能不徧傳四方?<br/>寶血洗罪有功效,<br/>罪人速速來投靠!<br/>',NULL,22030,1);
INSERT INTO stanza VALUES('CS855','2','遠比祭牲血更美,<br/>帶來救恩福全備;<br/>羔羊無瑕、血無疵,<br/>不見朽壞到永世。<br/>',NULL,22031,2);
INSERT INTO stanza VALUES('CS855','3','聽哪!寶血在發聲,<br/>聞於神前顯權能;<br/>在寶座前為我言,<br/>功效絕佳永不變。<br/>',NULL,22032,3);
INSERT INTO stanza VALUES('CS855','4','前我良心有虧欠,<br/>時有控告無平安;<br/>所有玷污盡顯露,<br/>歎息、痛苦不止住。<br/>',NULL,22033,4);
INSERT INTO stanza VALUES('CS855','5','豈知寶血洗罪污,<br/>神前功效永充足;<br/>罪案全銷,得近神,<br/>藉血罪人蒙神恩!<br/>',NULL,22034,5);
INSERT INTO stanza VALUES('CS855','6','無須祭牲血再灑,<br/>無須憑“死行”脫罰;<br/>無何能使神喜悅,<br/>諸天惟聽主寶血。<br/>',NULL,22035,6);
INSERT INTO stanza VALUES('CS855','7','因祂流血我得贖,<br/>罪得全赦,享永福;<br/>先民不過將罪遮,<br/>我得潔淨,唱樂歌。<br/>',NULL,22036,7);
INSERT INTO stanza VALUES('CS855','8','進入平安,何穩妥,<br/>良心無虧,罪污脫;<br/>不再羞愧,無重擔,<br/>與神和好,心安然。<br/>',NULL,22037,8);
INSERT INTO stanza VALUES('CS855','9','阿利路亞!深難測!<br/>寶血價值我尋得!<br/>故當歌唱,再歌唱,<br/>祂血永是我保障!<br/>',NULL,22038,9);
INSERT INTO stanza VALUES('CS856','1','前困深牢中,全然無望;<br/>試圖要相信,仍舊徬徨。<br/>耶穌一顯現,天光照明亮;<br/>大愛澆灌我心,<br/>神今住我心房!<br/>',NULL,22039,1);
INSERT INTO stanza VALUES('CS856','chorus','耶穌流寶血,成就平息;<br/>不再有定罪,因信稱義。<br/>我今歸與神,因救贖永定;<br/>藉著耶穌基督,對神有了和平!<br/>',NULL,22040,2);
INSERT INTO stanza VALUES('CS856','2','生在亞當裏,奔向死亡;<br/>身心全受創,病入膏肓。<br/>神差祂兒子,了結舊亞當;<br/>罪、死不再得逞,祂死,我得釋放!<br/>',NULL,22041,3);
INSERT INTO stanza VALUES('CS856','3','今在恩典中,喜樂歡暢;<br/>罪惡全消蹤,神在流淌。<br/>神長在我心,我享恩無量─<br/>在生命裏得救,在生命中作王!<br/>',NULL,22042,4);
INSERT INTO stanza VALUES('CS857','1','應當宣揚,宣揚主話使國度來臨;<br/>盡力宣揚,宣揚主話直到國度臨。<br/>和平福音,和平福音<br/>不該藏隱;不該藏隱;<br/>應當宣揚,宣揚主話直到國度臨。<br/>',NULL,22043,1);
INSERT INTO stanza VALUES('CS857','2','主話有能,儘管釋放,必不歸徒然;<br/>憑信撒種,必有結果,絕不歸徒然。<br/>殷勤撒種,必得亨通;<br/>主話有能,儘管撒種,必不歸徒然。<br/>',NULL,22044,2);
INSERT INTO stanza VALUES('CS857','3','這是時候!我們傳揚福音徧人間;<br/>把握今日,傳揚福音不怕人棄嫌。<br/>不必畏縮,主已工作!<br/>天程旅客與主合作,不怕人棄嫌。<br/>',NULL,22045,3);
INSERT INTO stanza VALUES('CS857','4','只管傳講,基督必在人心作見證。<br/>我們傳講,基督就在人心作見證。<br/>宣揚主恩,為主得人;<br/>我們傳講,基督就在人心作見證。<br/>',NULL,22046,4);
INSERT INTO stanza VALUES('CS857','5','莊稼已熟!前去收割不必再等候!<br/>田已發白!前去收割不必再等候!<br/>基督、召會,豐滿全備─<br/>完滿福音速速傳揚,滿足人所求。<br/>',NULL,22047,5);
INSERT INTO stanza VALUES('CS858','1','高品福音,無上福祉,<br/>應當傳揚,無畏無愧;<br/>人得重生,成神兒子,<br/>成全神旨,至高至貴;<br/>不僅出死,脫離罪罰,<br/>更得成為聖別族類;<br/>如此喜信,超凡絕佳,<br/>地上萬人都當來歸。<br/>',NULL,22048,1);
INSERT INTO stanza VALUES('CS858','2','長兄基督,神所立定,<br/>萬有歸祂承受管理;<br/>我們與祂同性、同命,<br/>同作後嗣榮耀無匹。<br/>創世以前,蒙神揀選,<br/>我們得享殊榮無比;<br/>如此基督,如此恩典,<br/>誰能不受吸引歸依?<br/>',NULL,22049,2);
INSERT INTO stanza VALUES('CS858','3','同蒙天召聖別弟兄,<br/>身分崇高,非人能及,<br/>且與兄長定命與共─<br/>如此佳音,誰不稱奇?<br/>榮耀基督天上執政,<br/>我們竟得與祂是一,<br/>如此呼召超絕神聖,<br/>誰竟愚頑,棄而不理?<br/>',NULL,22050,3);
INSERT INTO stanza VALUES('CS859','1','福音的交通,我們同有分,<br/>從頭一天至今;<br/>為推廣福音,眾人如一人,<br/>主話徧傳遠近。<br/>辯護且證實,我們活福音,<br/>在此同享主恩;<br/>主既動善工,必成全無遜,<br/>直至榮中降臨。<br/>',NULL,22051,1);
INSERT INTO stanza VALUES('CS859','2','每日的境遇,無論苦或甜,<br/>都為福音進展;<br/>為福音、死活,使主顯人前,<br/>生活在地如天。<br/>篤信無畏懼,靈中常放膽,<br/>講說神的聖言;<br/>在愛裏行事,憑大能爭戰,<br/>與主聯結無間。<br/>',NULL,22052,2);
INSERT INTO stanza VALUES('CS859','3','凡事能放膽,不怕仇敵阻,<br/>主靈供應充足;<br/>基督常顯大,無論何事故,<br/>生死都不在乎。<br/>無一事羞愧,我們只切慕,<br/>活著就是基督─<br/>惟祂作人位,從我們活出,<br/>事事處處無誤。<br/>',NULL,22053,3);
INSERT INTO stanza VALUES('CS859','4','行事並為人與福音是一,<br/>無論何事臨及;<br/>在一個靈裏,為福音站立,<br/>同魂一起努力。<br/>讓我們宣揚福音的奧祕,<br/>使主稱心如意;<br/>基督作生命,召會為身體,<br/>傳遍居人之地。<br/>',NULL,22054,4);
INSERT INTO stanza VALUES('CS860','1','去！使萬民作主的門徒，教導神聖的真理，<br/>將國度福音傳遍全地，催促主日子來臨；<br/>享受包羅萬有的基督，將祂分賜外邦人，<br/>使他們都成為神兒女，作神祭物獻給神。<br/>',NULL,22055,1);
INSERT INTO stanza VALUES('CS860','chorus','福音號角在吹響，真理旌旗在飄揚。<br/>起來，神福音勤奮的祭司！<br/>起來！起來！<br/>',NULL,22056,2);
INSERT INTO stanza VALUES('CS860','2','在素質上並在經綸上，被終極的靈充溢，<br/>傳好信息給困苦的人，使被囚的得開釋；<br/>宣揚救主悅納人禧年，讓世人都歸向祂，<br/>現在正是拯救的日子，主！得著我的全家！<br/>',NULL,22057,3);
INSERT INTO stanza VALUES('CS860','3','凡我所行都是為福音，我不以福音為恥！<br/>順從恩膏不住的禱告，真正福音的服事！<br/>放下自己同心並同魂，進入福音的交通。<br/>天天被真理的話構成，展開福音的行動。<br/>',NULL,22058,4);
INSERT INTO stanza VALUES('CS860','4','主使我作福音的出口，讓福音火焚燒我！<br/>交出我家作福音出路，讓主騎驢駒經過。<br/>抓住機會盡福音本份，到所有居人地帶，<br/>祝福萬族催促主再來，帶進國度的時代。<br/>',NULL,22059,5);
INSERT INTO stanza VALUES('CS866','1','一盞燈光,一戶人家,<br/>家需要光照亮,<br/>神就是光,聖潔無瑕,<br/>竟來我家施恩無量;<br/>除去憂傷,除去迷惘,<br/>我的家每一心房,<br/>喜樂、歡暢越發明亮。<br/>',NULL,22060,1);
INSERT INTO stanza VALUES('CS866','2','我家乃是屬神的家,<br/>這裏有愛流淌,<br/>神就是愛,真實、美佳,<br/>浸潤充滿,甜美馨香;<br/>帶來體諒,帶來盼望,<br/>我的家每一心房,<br/>滿足、安康越發興旺。<br/>',NULL,22061,2);
INSERT INTO stanza VALUES('CS867','1','奮力之神,內裏運行,<br/>我願聽招呼,追隨祂步武。<br/>屬世前途,何屑一顧,<br/>上好的愛,只屬良人基督。<br/>天天被提,更近我主;<br/>天天殉道,照耀榮美耶穌。<br/>雲彩圍繞,同奔天路;<br/>歌中之歌,與眾童女共譜。<br/>',NULL,22062,1);
INSERT INTO stanza VALUES('CS867','chorus','我們願以奉獻為彩飾,<br/>獻上自己作清晨甘露,<br/>解主乾渴,生死不顧,<br/>同生活,同爭戰,同榮辱。<br/>起來!寫下神行動歷史,<br/>承接時代榮耀的託付,<br/>作主新婦,同祂凱歸,<br/>全地成主甘甜美麗國度。<br/>',NULL,22063,2);
INSERT INTO stanza VALUES('CS867','2','我時輭弱、冷淡搖動,<br/>你仍來眷臨,保養又顧惜!<br/>愛裏回應天上職事,<br/>擺上全人,為神經綸再起。<br/>與主同心,牧養羣羊;<br/>堅定持續,實行神所命定。<br/>無論晴雨,勞苦不息,<br/>全為應驗神的夢-伯特利。<br/>',NULL,22064,3);
INSERT INTO stanza VALUES('CS867','3','同受異象,作主先鋒,<br/>一聽主號令全體向前衝。<br/>獨一職事,獨一工作,<br/>神的奴僕,相調中同事奉。<br/>調和的靈是我祕訣;<br/>死而復活,在配搭裏行動。<br/>同憂同樂,相愛相交,<br/>身體實際,達到錫安高峯。<br/>',NULL,22065,4);
INSERT INTO stanza VALUES('CS867','4','亙古而出,奮力前進,<br/>祂的出來將得勝者興起!<br/>我獻自己至死忠信,<br/>跟隨羔羊,與神七靈是一。<br/>活力事奉,編組成軍;<br/>代求守望,以維護神權益。<br/>建立燈臺,照亮萬民,<br/>國度福音徧傳居人之地。<br/>',NULL,22066,5);
INSERT INTO stanza VALUES('CS869','1','誰肯受託，宣揚神福音？<br/>誰願答應，受差遣前行？<br/>主愛激勵困迫，不再我活。<br/>今日起來應聲：『請差遣我！』<br/>',NULL,22067,1);
INSERT INTO stanza VALUES('CS869','chorus','深願神福音成我生活，<br/>更新我奉獻剛強開拓，<br/>答應主呼召，忠勇邁進，跟隨羔羊前行，<br/>遍地叩門！主阿，願你快臨！<br/>',NULL,22068,2);
INSERT INTO stanza VALUES('CS869','2','生死夥伴，愛裏相提攜。<br/>同靈站住，同魂齊努力。<br/>只為基督身體，不顧自己。<br/>作主得勝新婦，時代轉移。<br/>',NULL,22069,3);
INSERT INTO stanza VALUES('CS870','1','榮耀異象如日放明,<br/>神心所願,是我所羨;<br/>主愛困迫、吸引我向前,<br/>答應呼召就在今天。<br/>更新奉獻,接受主陶甄,<br/>基督安家,居中掌權!<br/>供應生命,湧流活泉,<br/>基督見證擴展無邊。<br/>',NULL,22070,1);
INSERT INTO stanza VALUES('CS870','chorus','興起!同主前進!投身聖靈流中。<br/>在神的行動中行動,徧地叩門,<br/>主!我願你快臨!<br/>',NULL,22071,2);
INSERT INTO stanza VALUES('CS870','2','投身流中,剛強開拓!<br/>羔羊腳蹤緊緊跟隨;<br/>同靈同魂,服元首權柄,<br/>完成神旨,將敵擊潰。<br/>生、養、教、建,栽種召會樹,<br/>團體新人,得勝、有為,<br/>召會、身體,榮美新婦<br/>顯於各地,促主歸回。<br/>',NULL,22072,3);
INSERT INTO stanza VALUES('CS870','3','作主飛鷹,翱翔天際,<br/>在復活裏,與祂是一;<br/>主話擴長,門徒化萬民,<br/>國度福音徧傳地極。<br/>神的旨意,我榮耀定命:<br/>作得勝者,照神心意,<br/>聖城得建,國度實現,<br/>錫安山上同祂站立。<br/>',NULL,22073,4);
INSERT INTO stanza VALUES('CS871','1','國度福音徧傳地極,<br/>使萬民識神心意;<br/>行動大輪隨靈前行,<br/>為成就時代目的。<br/>主聲呼召、祂愛激勵,<br/>你我豈能再遲疑?<br/>隨同羔羊出到全地,<br/>宣揚神經綸奧祕。<br/>',NULL,22074,1);
INSERT INTO stanza VALUES('CS871','chorus','在今天,更新奉獻,一生隨主往前;<br/>將祂計畫實現,是我心願。<br/>願一生儆醒主前,等候晨星出現;<br/>直到永遠,同祂作王掌權!<br/>',NULL,22075,2);
INSERT INTO stanza VALUES('CS871','2','靈裏扶持,愛裏提攜,<br/>同作肢體不稍離;<br/>持定元首、結合一起,<br/>眾人消失配搭裏。<br/>交出自己、信託身體,<br/>靠主權能得加力;<br/>無一失敗、同享勝利,<br/>憑禱告擊敗仇敵!<br/>',NULL,22076,3);
INSERT INTO stanza VALUES('CS871','3','在身體裏向前邁進,<br/>宣揚禧年徧全地;<br/>陳明真理、湧流生命,<br/>與新約職事是一。<br/>突破文化、語言、國籍,<br/>將人遷到基督裏;<br/>各地聖徒同心合意,<br/>齊顯出新人實際!<br/>',NULL,22077,4);
INSERT INTO stanza VALUES('CS871','4','起來!回應神的心意,<br/>投身流中趁現今;<br/>拚上!只望討主歡欣,<br/>奔賽程竭力前進!<br/>作得勝者殉道、被提,<br/>享受主隱殿中密來臨;<br/>殿中柱子擔負見證,<br/>聖城光輝顯無盡!<br/>',NULL,22078,5);
INSERT INTO stanza VALUES('CS872','1','走過千重山,渡過萬里洋,<br/>何處找到安息的地方?<br/>年日去匆匆,人生路茫茫,<br/>何時尋得永遠的盼望?<br/>我魂阿!快甦醒,把握不多時光,<br/>神的福音此刻在傳揚,<br/>我靈阿!當興起,走出黑暗、死亡,<br/>基督救恩現今已顯彰;<br/>敞開疲困心,接受生命光,<br/>我願全人脫罪惡捆綁,<br/>主阿,主耶穌!請聽我渴望:<br/>我來就你,求將我釋放。<br/>',NULL,22079,1);
INSERT INTO stanza VALUES('CS872','2','原是榮耀神,何竟從天降,<br/>為救罪人甚且將命喪,<br/>身體為我裂,寶血為我淌,<br/>罪的刑罰由祂一人當。<br/>超越知識的愛,過我所求、所想-<br/>祂為我死、復活、升天上,<br/>無窮無盡的恩,供應全備、深廣-<br/>祂成那靈內住我心房;<br/>人不再漂泊,心不再流蕩,<br/>安家召會,神人同歡暢,<br/>享生命救恩,懷榮耀盼望,<br/>我已尋得屬天的家鄉。<br/>',NULL,22080,2);
INSERT INTO stanza VALUES('CS873','1','看哪!我王坐車前往,<br/>剛強無不得勝;<br/>光輝奪人,引我跟隨,<br/>就此一定永定。<br/>凱旋行列,撒香俘虜,<br/>歡呼同祂前行;<br/>世途捨棄竭力拚上,<br/>作祂行動見證。<br/>',NULL,22081,1);
INSERT INTO stanza VALUES('CS873','chorus','站住奉獻地位,只聽主號令;<br/>作初熟果,邁向榮耀,<br/>建成新耶路撒冷。<br/>',NULL,22082,2);
INSERT INTO stanza VALUES('CS873','2','主愛牧養,柔細顧惜,<br/>是我全備供應;<br/>使我脫離天然、自己,<br/>顯大復活生命。<br/>相愛、相倚,眾人如一,<br/>惟憑靈中交通;<br/>基督身體,建造擴展,<br/>新人實際完成。<br/>',NULL,22083,3);
INSERT INTO stanza VALUES('CS873','3','神聖經綸,獨一異象,<br/>我今投身其中。<br/>海口啟程,宣揚佳音,<br/>全地燈臺照明。<br/>作主新婦,榮耀軍隊,<br/>敵前顯祂得勝;<br/>諸王、萬國無不俯伏,<br/>和聲尊大主名。<br/>',NULL,22084,4);
INSERT INTO stanza VALUES('CS874','1','等候耶和華，重新得力；<br/>必如鷹展翅，上騰離地。<br/>憑復活大能，翱翔天際；<br/>奔跑不困倦，行走不疲。<br/>飛向蔚藍天，遠離家鄉；<br/>脫世俗羈絆，去地捆綁。<br/>願受主差遣，同祂前往；<br/>將國度福音，帶給萬邦。<br/>',NULL,22085,1);
INSERT INTO stanza VALUES('CS874','chorus','神的飛鷹，展翅翱翔，<br/>直到錫安，永遠同主作王。<br/>',NULL,22086,2);
INSERT INTO stanza VALUES('CS874','2','顧到神權益，不為自己；<br/>使我被取代，讓主頂替。<br/>與主成為一，有如飛鷹；<br/>成為得勝者，擊拜仇敵。<br/>往普天下去，傳揚福音；<br/>栽種召會樹，開展移民。<br/>作耶穌見證，跟隨七靈；<br/>金燈台照亮，國度降臨。<br/>',NULL,22087,3);
INSERT INTO stanza VALUES('CS875','1','西布倫,出外可以歡喜,<br/>隨聖靈大風揚帆起行;<br/>福音船滿載基督豐富,<br/>傳揚基督復活,作祂見證。<br/>我們是主的見證人,<br/>將祂繁殖達四境;<br/>使萬民歸順主門徒,<br/>執行我主偉大使命。<br/>',NULL,22088,1);
INSERT INTO stanza VALUES('CS875','2','復活裏,如母鹿得釋放,<br/>拿弗他利出嘉美言語;<br/>滿恩惠,蒙耶和華賜福,<br/>必得海和南方為業無虞。<br/>讓我們湧流主生命,<br/>剛強開拓無畏懼;<br/>以高品福音人得地,<br/>憑主大能,照主應許。<br/>',NULL,22089,2);
INSERT INTO stanza VALUES('CS875','3','看,全地盡是饑餓人羣,<br/>需你我分賜基督富餘;<br/>速興起,打開約瑟糧倉,<br/>答應主的呼召,供人所需。<br/>主神說,我可差遣誰?<br/>誰肯為我們前去?<br/>哦,主阿,是我,我在這裏,<br/>請差遣我,照你所欲。<br/>',NULL,22090,3);
INSERT INTO stanza VALUES('CS875','4','得勝者─猶大支派獅子,<br/>擊敗眾仇敵,建立國度;<br/>權杖與國杖永不離開,<br/>直到細羅來到,平安處處。<br/>讓我們展覽主得勝,<br/>黑暗權勢盡驅除;<br/>憑那靈,在生命中作王,<br/>使全地眾民都蒙福。<br/>',NULL,22091,4);
INSERT INTO stanza VALUES('CS875','5','約瑟是多結果子樹枝,<br/>泉源旁結果纍纍下垂;<br/>無何能限制生命繁殖,<br/>枝條探出牆外,延展加倍。<br/>讓我們住在主裏面,生命流通益豐沛;<br/>環境中總將基督顯大,<br/>常結新果顯主作為。<br/>',NULL,22092,5);
INSERT INTO stanza VALUES('CS875','6','以薩迦,羊圈間可躺臥,<br/>得佳美之地,滿享安息;<br/>帳棚裏,盡情享受快樂;<br/>低肩背重,獻貢物主所喜。<br/>讓我們宗教盡脫落,<br/>享受基督作美地;<br/>召會中作肢體盡功用,<br/>生機建造基督身體。<br/>',NULL,22093,6);
INSERT INTO stanza VALUES('CS875','7','便雅憫,耶和華所親愛,<br/>爭戰中,如同撕掠的狼;<br/>滅仇敵,早晨喫所掠奪,<br/>晚上分所擄獲,得勝剛強。<br/>主所愛,必與主同居,<br/>得遮蔽,安息歡暢;<br/>永世裏,神人同得滿足─<br/>向此標竿,我們直往!<br/>',NULL,22094,7);
INSERT INTO stanza VALUES('CS876','1','神就是愛,祂差獨生愛子前來;<br/>當世人敗壞,正墮落無奈,<br/>竟來與人同在。<br/>我猶罪人,基督即已為我受害;<br/>神莫測大愛,在此就佈開,<br/>當得我心感戴。<br/>',NULL,22095,1);
INSERT INTO stanza VALUES('CS876','chorus','你既如此不吝,捨你愛子受害,<br/>父阿,因祂寶貴,我讚美敬拜。<br/>',NULL,22096,2);
INSERT INTO stanza VALUES('CS876','2','有誰能知,源自父神懷裏奇愛?<br/>眼雖未曾見,耳雖未曾聞,<br/>我卻得贖蒙愛。<br/>哦,神的愛!祂竟生為人子嬰孩,<br/>咒詛祂擔代,十架上受害,<br/>流血為將我買。<br/>',NULL,22097,3);
INSERT INTO stanza VALUES('CS876','chorus','父,感謝你差派獨生愛子前來;<br/>祂血流自加略,顯明你大愛。<br/>',NULL,22098,4);
INSERT INTO stanza VALUES('CS876','3','神愛世人,甚至將獨生子差來。<br/>信祂不滅亡,永遠生命享;<br/>來罷,切勿等待!<br/>信祂不滅亡,永遠生命享;<br/>來罷,切勿等待!<br/>',NULL,22099,5);
INSERT INTO stanza VALUES('CS877','1','甚麼使你為我捨命?<br/>為何救我?我是你仇敵。<br/>你上十架,為作我代替;<br/>你受咒詛,我享福氣。<br/>',NULL,22100,1);
INSERT INTO stanza VALUES('CS877','chorus','我原是你仇敵,何來為我捨命?<br/>你受咒詛,我享福氣。<br/>神竟為人捨命,哦!是極大奧祕!<br/>你來受死,為你仇敵。<br/>',NULL,22101,2);
INSERT INTO stanza VALUES('CS877','2','未曾想到,你如此行;<br/>溫柔、憐恤,全向我洋溢。<br/>為何你愛?我罪大惡極;<br/>但你愛我─你的仇敵。<br/>',NULL,22102,3);
INSERT INTO stanza VALUES('CS877','3','你之愛我,從永遠起;<br/>你愛恆久、堅定不稍移。<br/>雖我言語,冒犯得罪你;<br/>但你等候,代求不息。<br/>',NULL,22103,4);
INSERT INTO stanza VALUES('CS877','4','我是罪人,犯罪不已;<br/>活在罪中,行不法不義。<br/>我的惡心,反判又悖逆;<br/>但你慈心,感我衷裏。<br/>',NULL,22104,5);
INSERT INTO stanza VALUES('CS877','chorus','我原是你仇敵,竟也能歸服你;<br/>因你眷臨,愛裏尋覓。<br/>是你愛和憐憫,征服頑梗剛愎;<br/>昔日仇敵,今願服你。<br/>',NULL,22105,6);
INSERT INTO stanza VALUES('CS877','5','我一轉身,就遇見你;<br/>你正等我,懷聖別愛意。<br/>我怎忍心,再與你為敵?<br/>耶穌,我今降服歸你。<br/>',NULL,22106,7);
INSERT INTO stanza VALUES('CS878','1','人生不定無長久,<br/>我的所有遭剝奪,<br/>無奈承受痛與羞,<br/>獨自絕望中倒臥,<br/>深深苦情無人憐,<br/>重重患難誰來遣,<br/>以為生命即消散,<br/>祂竟出現在眼前。<br/>',NULL,22107,1);
INSERT INTO stanza VALUES('CS878','chorus','今生今世我口最愛提說,<br/>就是我主祂來過,<br/>驅走黑暗,擔我輭弱,<br/>作我平安永穩妥。<br/>',NULL,22108,2);
INSERT INTO stanza VALUES('CS878','2','祂用油酒來敷裹,<br/>我心傷痛與坎坷,<br/>懷我、肩我、扶助我,<br/>那有一點我配得,<br/>我這纔知何為愛,<br/>竟然施與我無賴,<br/>為使一生都開懷,<br/>接我到神家裏來。<br/>',NULL,22109,3);
INSERT INTO stanza VALUES('CS878','3','別看今我有何長,<br/>若非主我早崩潰,<br/>我命、我愛、我力量,<br/>全都屬祂不別歸,<br/>喜樂、盼望真顯明,<br/>救恩全備又有能,<br/>我口頌讚心感銘,<br/>一生因祂樂歡騰。<br/>',NULL,22110,4);
INSERT INTO stanza VALUES('CS878','chorus','我心歌唱主愛高深長濶,<br/>祂必永不離開我,<br/>作我生命,與我同活,<br/>伴我此生共度過。<br/>',NULL,22111,5);
INSERT INTO stanza VALUES('CS879','1','我一直尋求平安,或能有喜樂半點,<br/>我所有不過愁煩,人生坎坷艱難;<br/>我怨歎:奮鬬努力竟換得失望,<br/>我感傷:為何前景始終淒涼!<br/>真的神阿,你今何在?我需要你理睬,<br/>哦,我真想投入你懷。還是你不存在?<br/>',NULL,22112,1);
INSERT INTO stanza VALUES('CS879','2','是耶穌將我尋回,正當我萬念俱灰,<br/>祂平安入我心內,湧出喜樂眼淚;<br/>我的信終於有了生命的迴響,<br/>我的心流進神聖安息、盼望!<br/>哦,主耶穌,我感謝你,與我聯結為一,<br/>無人像你真情實意,我餘生都給你。<br/>',NULL,22113,2);
INSERT INTO stanza VALUES('CS879','3','何喜樂,不再是我,是基督在我活著,<br/>祂救我脫罪、死、魔,經歷死而復活;<br/>我高喊:耶穌,耶穌,祂真是愛我,<br/>我頌讚:祂賜救恩這大!這博!<br/>哦,真的神是我耶穌,神是萬主之主,<br/>我心、我命為你傾注,愛著你就滿足。<br/>',NULL,22114,3);
INSERT INTO stanza VALUES('CS880','1','“當信靠主耶穌,當信當信靠主耶穌,<br/>你和你一家都必得救;”<br/>踏出你信心腳步,神必定為你開路,<br/>祂旣如此應許,必定會成就。<br/>你心不要疑惑,你只管放心交託,<br/>在人所不能,在神都能;<br/>只要祂為你掌握,相信總會有結果,<br/>現在起來呼求,高舉主聖名。<br/>',NULL,22115,1);
INSERT INTO stanza VALUES('CS880','2','“當信靠主耶穌,當信當信靠主耶穌,<br/>你和你一家都必得救;”<br/>這蒙恩見證無數,全都在向我說出,<br/>神總不會遲誤,要聽我祈求。<br/>耶穌的愛何大,愛我也愛我全家,<br/>我一人信主,全家蒙福;<br/>我要全心讚美祂,永遠是信實可誇,<br/>同來敬拜稱祝,這寶貴救主。<br/>',NULL,22116,2);
INSERT INTO stanza VALUES('CS861','1','神今日的行動乃是要產生得勝者，<br/>過活力的生活，實行活力的事奉，<br/>照著神牧養，為著建造基督的身體。<br/><br/>我們需要在基督天上的職事裏，<br/>與代求的基督是一，好執行祂神聖的行政，<br/>好執行祂神聖的行政，完成祂的經綸。<br/><br/>蒙救贖被聖別的子民，編組成神聖別的軍隊，<br/>在奮力活動的神裏行動並爭戰，以得著地。<br/><br/>我們要在神的行動中行動，<br/>去，使萬民作主的門徒，教導神聖的真理；<br/>將國度的福音傳遍居人之地，使金燈台照亮全地，<br/>催促主的日子來到。催促主的日子來到！<br/>',NULL,22117,1);
INSERT INTO stanza VALUES('CS862','1','我們有分神聖工作,<br/>是因祂恩永遠彀用;<br/>只要向祂絕對、純誠,<br/>必得祝福,無量豐富。<br/>',NULL,22118,1);
INSERT INTO stanza VALUES('CS862','2','有祂無我,捨祂無為;<br/>彼此之間同心、相愛,<br/>沒有己意,沒有猜忌,<br/>必得祝福,無量豐富。<br/>',NULL,22119,2);
INSERT INTO stanza VALUES('CS862','3','存心、行動、為人、工作,<br/>完全受靈管治約束,<br/>蒙祂靈的權能同在,<br/>必定見祂工作成就。<br/>',NULL,22120,3);
INSERT INTO stanza VALUES('CS862','4','時常呼求,凡事禱告,<br/>只憑信心,不憑眼見,<br/>必得祝福,無量豐富,<br/>必定見祂工作成就。<br/>',NULL,22121,4);
INSERT INTO stanza VALUES('CS863','1','“今日的”真理,帶進神行動,<br/>使我得堅固,清楚異象;<br/>在今時代裏,我當有耳聽,<br/>留意暗處燈,等候晨星。<br/>',NULL,22122,1);
INSERT INTO stanza VALUES('CS863','chorus','儆醒,儆醒,那靈對我說話!<br/>興起,興起,當有真實復興!<br/>跟上,跟上,經綸大輪行動!<br/>得勝,得勝,持守榮耀冕!<br/>',NULL,22123,2);
INSERT INTO stanza VALUES('CS863','2','正常基督徒,天天有復興,<br/>過活力生活,日日得勝;<br/>成為得勝者,脫離老底嘉,<br/>持守主恢復,棄絕撒狄。<br/>',NULL,22124,3);
INSERT INTO stanza VALUES('CS863','3','配合神行動,成為四活物,<br/>團體行動中,風、雲、火、金;<br/>保守身體裏,聖別過生活,<br/>焚燒在一起,彼此建造。<br/>',NULL,22125,4);
INSERT INTO stanza VALUES('CS863','4','基督登寶座,成為代求者,<br/>禱告裏禱告,需我配合;<br/>成為守望者,執行神行政,<br/>香氣升神前,威力無窮。<br/>',NULL,22126,5);
INSERT INTO stanza VALUES('CS863','5','國度的福音,傳遍居人地,<br/>見證於萬民,結束時代;<br/>主能差遣誰,誰願為主去?<br/>主我在這裏,請差遣我!<br/>',NULL,22127,6);
INSERT INTO stanza VALUES('CS863','6','主,我真愛你,願作得勝者,<br/>同你寫歷史,與你是一;<br/>奮力活動神,激動我全人,<br/>起來奔賽程,直到路終。<br/>',NULL,22128,7);
INSERT INTO stanza VALUES('CS864','1','我看見寬闊天空,就想飛翔;<br/>振翼整裝,卻常常迷惘,<br/>徧尋不到真方向。<br/>主來,是真光,<br/>帶我重新啟航,<br/>知道神造人像神,<br/>將祂盛裝,<br/>為要代表管理,<br/>且作團體顯彰。<br/>',NULL,22129,1);
INSERT INTO stanza VALUES('CS864','chorus','永遠的話成肉身,且成那靈,<br/>來使人變化,有祂生命性情。<br/>這是神新約的經綸如同大輪,<br/>往全地開展,榮耀,我竟有分!<br/>',NULL,22130,2);
INSERT INTO stanza VALUES('CS864','2','我今有何等榮景,懷抱雄心;<br/>國度福音,如生命種子,<br/>就要百倍結實。<br/>我去,是奴僕,<br/>使人作主門徒,<br/>願祂現在更照耀,<br/>君王基督那日從天歸回,<br/>並自我裏透出。<br/>',NULL,22131,3);
INSERT INTO stanza VALUES('CS865','1','奧祕經綸,藏於神裏,<br/>天地之主渴望尋得安息;<br/>神家異象,顯於我靈,<br/>抓奪如我,無心竟能知悉:<br/>神成為人,經死、復活,<br/>作天梯,內住我靈裏;<br/>人成為神,重生、變化,<br/>成居所滿足神心意。<br/>',NULL,22132,1);
INSERT INTO stanza VALUES('CS865','chorus','恩主,是你極深憐恤,<br/>榮耀經綸引我離地;<br/>愛裏回應,奉獻全人,<br/>不從己意,惟願是你。<br/>同靈、同魂、思念同一,<br/>為建神家一齊努力;<br/>成神帳幕─聖城撒冷,<br/>神人永得滿足安息。<br/>',NULL,22133,2);
INSERT INTO stanza VALUES('CS865','2','無奈己意,只求稱心,<br/>羨慕神旨,卻仍貪享安逸;<br/>光照臨及,纔識自己,<br/>處處攙雜事,事己意充替。<br/>主手管治,破碎甄陶,<br/>我衰減,逐日脫自己;<br/>聖靈分賜,更新變化,<br/>你擴增,安家我心裏。<br/>',NULL,22134,3);
INSERT INTO stanza VALUES('CS865','3','築壇奉獻,得著加力;<br/>神卻呼召:起來,上伯特利!<br/>經歷神家─召會實際,<br/>不再是“我,乃基督活我裏。”<br/>你愛困迫,脫離個人,<br/>為你家,我們纔安息;<br/>同眾肢體,獻作活祭,<br/>為召會,“枉費”亦歡喜。<br/>',NULL,22135,4);
INSERT INTO stanza VALUES('CS865','4','答應呼召,憑七倍靈,<br/>作得勝者,此心絕不稍移;<br/>持守主話,靠主聖名,<br/>忠勇向前,一生不再偏離。<br/>竭力奮鬬,同心配搭,<br/>奉差遣,心繫於全地。<br/>國度福音,徧傳地極,<br/>懷雄心,只討主欣喜。<br/>',NULL,22136,5);
INSERT INTO stanza VALUES('CS868','1','耶穌─好牧人,尋找稅吏、罪人;<br/>祂是神成肉身,拯救世人脫沉淪;<br/>肩負疲魂,喜樂、情深,領迷羊歸神。<br/>',NULL,22137,1);
INSERT INTO stanza VALUES('CS868','2','那靈─光照者,正尋覓失落者;<br/>生命之光照射,要世人知罪自責;<br/>銀幣蒙塵,祂心不捨,終被祂尋得。<br/>',NULL,22138,2);
INSERT INTO stanza VALUES('CS868','3','父神─親愛父,憐憫世上罪奴;<br/>放蕩揮霍無度,不知何時纔醒悟?<br/>慈愛天父,朝思夜慕,浪子上歸途。<br/>',NULL,22139,3);
INSERT INTO stanza VALUES('CS868','4','父神─接納者,親吻那流浪者;<br/>披華美,罪全赦,享肥甘,不再飢渴;<br/>死而復活,失而又得,神、人同歡樂。<br/>',NULL,22140,4);
INSERT INTO stanza VALUES('CS917','1','今日爭戰兇猛,<br/>撒但尚未退敗;<br/>戰場傳來呼喊之聲,<br/>比前更加澎湃;<br/>陰府背叛喧囂,<br/>雖仍強悍不衰;<br/>請聽夜半主發呼聲:<br/>“看哪,我必快來!”<br/>',NULL,22141,1);
INSERT INTO stanza VALUES('CS917','2','雖有更苦試煉,<br/>爭戰不斷接連;<br/>黑暗權勢如同軍隊,<br/>集聚進逼無間,<br/>正當儆醒等候,<br/>正逢艱苦試驗;<br/>卻聞歌聲喜樂、甘甜:<br/>我主已快顯現!<br/>',NULL,22142,2);
INSERT INTO stanza VALUES('CS917','3','當在末後年日,<br/>持守見證不移;<br/>撒但無所不用其極,<br/>我們仍需站立;<br/>應當重新得力,<br/>纔能勝過仇敵;<br/>直到見主,何等歡喜,<br/>歎息全都止息。<br/>',NULL,22143,3);
INSERT INTO stanza VALUES('CS917','4','誰願奮力進前,<br/>靠主能力遮蓋?<br/>誰願堅定為主爭戰,<br/>直到那日奏凱?<br/>得勝歡呼號聲,<br/>至終必定傳開;<br/>何等喜樂,已先聽見,<br/>“看哪,我必快來!”<br/>',NULL,22144,4);
INSERT INTO stanza VALUES('CS917','5','誰願走上窄路,<br/>將神旨意揀選?<br/>歷經風暴,通過考驗,<br/>絕不退後、心變?<br/>誰願忠勇進前,<br/>忍受痛苦、凶險?<br/>眾得勝者彷彿看見,<br/>“我主已快顯現!”<br/>',NULL,22145,5);
INSERT INTO stanza VALUES('CS917','6','應當加緊腳步,<br/>儘管黑暗四佈;<br/>期待那日被提之福,<br/>榮耀輝煌奪目;<br/>終將撒但征服,<br/>迎接再臨基督;<br/>得勝者阿,揚聲歡呼:<br/>“看哪!耶穌,我主!”<br/>',NULL,22146,6);
INSERT INTO stanza VALUES('CS918','1','時日或許更黑暗,長夜更令人倦,<br/>一事我心深確知,儘管我主遲延:<br/>祂必顯為更親近,交通必更甘甜,<br/>更親、更近、更甘甜,我主與我之間。<br/>',NULL,22147,1);
INSERT INTO stanza VALUES('CS918','2','我們等候親愛主─盼望!喜樂!友伴!<br/>一心只想迎見祂─也許在日盡前,<br/>就在隱密轉角處,祂的榮身要顯;<br/>等候就要成過去,安息就要完全。<br/>',NULL,22148,2);
INSERT INTO stanza VALUES('CS919','1','創造之神有一目的,<br/>使人活著有意義;<br/>按祂形像我們被造,<br/>將祂權柄顯於地。<br/>人雖落入撒但詭計,<br/>使神目標受蒙蔽;<br/>但神終將得祂國度,<br/>子必完成父心意。<br/>',NULL,22149,1);
INSERT INTO stanza VALUES('CS919','2','耶穌基督要得國度,<br/>撒但詭計必無路;<br/>生命種子長出實際,<br/>不顧一切的攔阻。<br/>並非宗教人士所說,<br/>死後纔能進國度;<br/>基督正在建造國度,<br/>我們見證且目睹。<br/>',NULL,22150,2);
INSERT INTO stanza VALUES('CS919','3','神子耶穌,我們救主,<br/>是神親來成肉體;<br/>今成那靈進入人裏,<br/>作為賜生命之氣。<br/>祂是小小生命子粒,<br/>生根在人的靈裏;<br/>從裏到外,不住擴展,<br/>直到生命全漫溢。<br/>',NULL,22151,3);
INSERT INTO stanza VALUES('CS919','4','弟兄,時間己經短促,<br/>主正切慕得新婦;<br/>藉著生命長大成熟,<br/>我們催促祂腳步。<br/>不再掙扎,不再奮鬬,<br/>只要靈中轉向主;<br/>凡事長入元首基督,<br/>生命種子成國度。<br/>',NULL,22152,4);
INSERT INTO stanza VALUES('CS919','5','惟憑生命正常生長,<br/>基督得著祂國度;<br/>變化並非瞬間卽成,<br/>逐日增長是正途。<br/>哦,讓我們發展、取用<br/>生命種子的豐富;<br/>寶貴種子長成國度,<br/>神旨成功不遲誤。<br/>',NULL,22153,5);
INSERT INTO stanza VALUES('CS920','1','榮耀新婦主所期,喜樂婚筵祂備齊;<br/>穿上潔淨細麻衣─要及時!<br/>經過苦難與死地,基督生命緊憑倚,<br/>活出之義成所披─要及時!<br/>',NULL,22154,1);
INSERT INTO stanza VALUES('CS920','chorus','要及時!要及時!<br/>羔羊婚筵今在卽,要及時!<br/>魂的生命肯離棄,讓靈浸透且漫溢,<br/>就必彀格來坐席─要及時!<br/>',NULL,22155,2);
INSERT INTO stanza VALUES('CS920','2','精明童女主所期,豫備新油當積極,<br/>切莫輕忽神心意─要及時!<br/>買油代價不容易,必須我們對付己,<br/>器皿充滿且洋溢─要及時!<br/>',NULL,22156,3);
INSERT INTO stanza VALUES('CS920','3','忠信奴僕主所期,運用恩賜作生意,<br/>莫因懶惰被撇棄─要及時!<br/>一他連得不藏匿,克服鬆懶的己意,<br/>憑主事奉不乏力─要及時!<br/>',NULL,22157,4);
INSERT INTO stanza VALUES('CS920','4','成熟麥子主所期,初熟部分先被提,<br/>大體莊稼仍在地─要及時!<br/>勿向世界再尋覓,屬地水分不留遺,<br/>生命成熟討主喜─要及時!<br/>',NULL,22158,5);
INSERT INTO stanza VALUES('CS920','5','得勝信徒主所期,為祂萬事不足惜,<br/>起初的愛總不棄─要及時!<br/>與主聯結成為一,勝過所有的死寂,<br/>奔向標竿盡全力─要及時!<br/>',NULL,22159,6);
INSERT INTO stanza VALUES('CS920','6','看哪,基督要來地,屬天國度將臨及,<br/>服主權柄莫遲疑─要及時!<br/>悖逆的己須脫離,順服功課當學習,<br/>讓主掌權登至極─要及時!<br/>',NULL,22160,7);
INSERT INTO stanza VALUES('CS921','1','神在子裏成為肉身,乃神所賜宏恩;<br/>基督豐富享受不盡,供應全備常新。<br/>此恩浩大,超人能度,奇妙,難盡述說;<br/>否則滅亡之子如我,怎能成神傑作?<br/>',NULL,22161,1);
INSERT INTO stanza VALUES('CS921','2','受造之物受縛被囚,殷殷熱切等候,<br/>神的眾子顯現時候,得享永遠自由。<br/>我神定旨永遠深廣,就要完全明朗;<br/>榮耀盼望如今隱藏,那時全得顯彰。<br/>',NULL,22162,2);
INSERT INTO stanza VALUES('CS921','3','番石榴樹代替蒺藜,松樹頂替荊棘;<br/>和平掌權,戰爭消弭,咒詛再無蹤迹。<br/>大山小山發聲歡呼,樹木拍掌鼓舞;<br/>榮耀自由得以進入,當神眾子顯出。<br/>',NULL,22163,3);
INSERT INTO stanza VALUES('CS921','4','神的深恩細緻陶甄,每日作工我身;<br/>分賜之工今雖隱藏,那日要顯無盡。<br/>神的自己在我加添,神聖分賜無間;<br/>受造萬有無不讚歎,當神傑作展現。<br/>',NULL,22164,4);
INSERT INTO stanza VALUES('CS921','5','得贖宇宙歡呼頌稱,神聖計畫成功!<br/>千萬天使和聲歌頌,無邊榮耀之中。<br/>惡者雖曾肆無忌憚,終如煙消雲散;<br/>惟主智慧卓越超凡,配得永遠稱讚。<br/>',NULL,22165,5);
INSERT INTO stanza VALUES('CS921','6','為此我們欣然奉獻,配合主的心願,<br/>接受祂的分賜、充滿,逐日讓祂擴展。<br/>惟願今日生活點滴,盡是因典滴瀝;<br/>是神自己加添我裏,那日光榮無比。<br/>',NULL,22166,6);
INSERT INTO stanza VALUES('CS922','1','我們向神的信心,當徧傳遠近,<br/>宣告已離棄偶像,事奉真活神;<br/>用信調和主聖言,高聲說“阿們!<br/>”藉主話轉向主,時刻經歷救恩。<br/>',NULL,22167,1);
INSERT INTO stanza VALUES('CS922','chorus','信心的工作要不斷增長,<br/>愛心的勞苦要漫溢四方,<br/>蒙祂聖別保守,徧及全人裏外;<br/>以盼望的忍耐,儆醒等候祂來。<br/>',NULL,22168,2);
INSERT INTO stanza VALUES('CS922','2','我們以神聖的愛,彼此來關懷,<br/>這愛在末後日子,更洋溢佈開;<br/>主引導我們的心,進入神的愛,<br/>豫備我們全人,盼望那日主來。<br/>',NULL,22169,3);
INSERT INTO stanza VALUES('CS922','3','信實的主必保守我們的各部─<br/>靈、魂、身子全聖別,構成祂新婦;<br/>今日凡事願聽從主大小吩咐,<br/>不久就要聽見祂的再臨招呼。<br/>',NULL,22170,4);
INSERT INTO stanza VALUES('CS922','4','我們等候主回來─祂甜美同在;<br/>哦,何等榮耀盼望!“主,願你快來!”<br/>作光明白、晝之子,儆醒勿懈怠,<br/>惟盼主顯榮身,婚娶之日,樂哉!<br/>',NULL,22171,5);
INSERT INTO stanza VALUES('CS923','1','主,你必快顯現,<br/>那日如在眼前,<br/>我們所慕惟你“同在”!<br/>我主、我命、我愛,<br/>你外無可替代,<br/>良人耶穌,願你快來!<br/>',NULL,22172,1);
INSERT INTO stanza VALUES('CS923','2','被提時刻臨近,<br/>儆醒聽你聲音,<br/>切盼與你榮中相見。<br/>惟當你顯榮身,<br/>在那婚娶之晨,<br/>纔識你愛超絕無限。<br/>',NULL,22173,2);
INSERT INTO stanza VALUES('CS923','3','時日飛逝如箭,<br/>不久要見你面─<br/>阿們,我主,願你快回!<br/>只盼早日見你,<br/>並且永遠偕你-<br/>我們全心別無所歸。<br/>',NULL,22174,3);
INSERT INTO stanza VALUES('CS923','4','是的,再過片時,<br/>新郎不再延遲,<br/>就要迎娶所愛新婦。<br/>祈求終變感讚,<br/>渴望盡成眼見,<br/>主,你也必心滿意足。<br/>',NULL,22175,4);
INSERT INTO stanza VALUES('CS924','1','今在靈裏,在召會中,<br/>得見異象,高、深、長、闊:<br/>我們定命卓越超凡,<br/>前所未見,超人能度。<br/>',NULL,22176,1);
INSERT INTO stanza VALUES('CS924','2','非僅道理,乃是啟示<br/>基督自己奇妙、奧祕;<br/>遠超心思所能領畧,<br/>但在靈中都成實際。<br/>',NULL,22177,2);
INSERT INTO stanza VALUES('CS924','3','祂是豐富、無限、深奧,<br/>無法測度、超絕美妙;<br/>竟需我們得著救恩,<br/>同為後嗣顯祂榮耀。<br/>',NULL,22178,3);
INSERT INTO stanza VALUES('CS924','4','神已計畫,也來創造,<br/>還要作出新造無窮;<br/>祂已立子作祂後嗣,<br/>執掌祂的神聖行政。<br/>',NULL,22179,4);
INSERT INTO stanza VALUES('CS924','5','但在神的經綸之中,<br/>並非僅有一子得榮;<br/>乃是長子率眾弟兄,<br/>同作後嗣,定命與共。<br/>',NULL,22180,5);
INSERT INTO stanza VALUES('CS924','6','為著彀格作神後嗣,<br/>我們必須長大成熟,<br/>好與基督同得榮耀,<br/>承受神的所是所有。<br/>',NULL,22181,6);
INSERT INTO stanza VALUES('CS924','7','作神後嗣,隨同長兄,<br/>承受萬有,豐富無缺;<br/>更是同夥,一同經營<br/>“基督、召會”宇宙大業。<br/>',NULL,22182,7);
INSERT INTO stanza VALUES('CS924','8','今在靈裏,在召會中,<br/>得見我們呼召、盼望:<br/>並非遙望,等“上天堂”,<br/>乃是在地與主同王。<br/>',NULL,22183,8);
INSERT INTO stanza VALUES('CS924','9','貧寒如我,竟成君王,<br/>有分寶座,承受國度;<br/>凡神所是並祂所有,<br/>全地、萬有無不我屬。<br/>',NULL,22184,9);
INSERT INTO stanza VALUES('CS925','1','永遠之神榮耀定旨,<br/>已過永遠早立定,<br/>跨越時間作為橋梁,<br/>將來永遠必達成。<br/>漫長歲月乃是過程,<br/>全為成功祂心意;<br/>我們居此不過客旅,<br/>無終永世為目的。<br/>',NULL,22185,1);
INSERT INTO stanza VALUES('CS925','2','一個新人是神所要,<br/>照祂計畫被建造;<br/>我們在此相聯相調─<br/>團體器皿何榮耀!<br/>神的生命、神的性情<br/>調進其中時增添;<br/>神靈、人靈調為一靈,<br/>叫祂榮耀得稱讚。<br/>',NULL,22186,2);
INSERT INTO stanza VALUES('CS925','3','三一之神三方工作,<br/>乃為達成祂定旨;<br/>父、子、聖靈何等奧妙,<br/>將神自己來分賜。<br/>天地宏偉不過背景,<br/>三部分人是標的─<br/>靈、魂、身體何等美妙,<br/>為盛裝神作實際。<br/>',NULL,22187,3);
INSERT INTO stanza VALUES('CS925','4','我們的靈乃是中心,<br/>是神計畫的關鍵;<br/>耶穌大名敞開呼求,<br/>人靈與祂就結聯。<br/>心中各房讓祂安家,<br/>始於中心達圓周;<br/>更新心思、情感、意志,<br/>每一部分祂浸透。<br/>',NULL,22188,4);
INSERT INTO stanza VALUES('CS925','5','在生命中同被建造,<br/>愛裏聯結成為一;<br/>如此成就祂的善工,<br/>成全祂心愛美意。<br/>願主擴長,我們衰減,<br/>讓祂建造我們裏;<br/>直到長成團體大器,<br/>充滿祂榮耀自己。<br/>',NULL,22189,5);
INSERT INTO stanza VALUES('CS925','6','最終召會,身體,新人,<br/>要顯現於榮耀裏;<br/>永世計畫終極完成,<br/>神的智慧顯無遺。<br/>神終得著團體器皿,<br/>將祂榮耀盡陳明─<br/>為此我們奉獻自己,<br/>求使主旨速完成。<br/>',NULL,22190,6);
INSERT INTO stanza VALUES('CS926','chorus','一道生命的水流，流自神和羔羊寶座，<br/>歷經世代未停歇，向前直奔流，<br/>千萬愛主青年，<br/>不斷縱身入這流，<br/>因基督的愛吸引，往另一方向追尋。<br/>',NULL,22191,1);
INSERT INTO stanza VALUES('CS926','1','神永遠經綸，今向我開啟，神來成為人，使我們成神；<br/>產生並建造主生機身體，活出並作出新耶路撒冷。<br/>深入地探究經歷中享受，妝飾並豫備祂榮美新婦，<br/>這屬天異象，召我跟從主，同靈同魂，與職事同步武。<br/>',NULL,22192,2);
INSERT INTO stanza VALUES('CS926','chorus','主愛激勵我們獻自己，蒙召投身時代水流裡：<br/>啟示高峰，神人生活，照神牧養，達『新的復興』；<br/>『榮耀託付』引我們前行，同著良人開展到全地，<br/>葡萄園裡，獻上愛情，香草山上，催促我主快臨。<br/>',NULL,22193,3);
INSERT INTO stanza VALUES('CS926','2','良人愛吸引，童女齊追隨，躥山越嶺來，陡巖隱密處；<br/>金辮加銀釘，祂香粉薰透，滿園播芬芳，全為祂享受。<br/>靠良人上來，切慕聽見祂，主堅愛保守，銘刻如印戳，<br/>全心得堅固，全人成為祂，良人與佳偶，同顯神的國。<br/>',NULL,22194,4);
INSERT INTO stanza VALUES('CS926','3','父愛赦免心，子神牧養靈，因和好職事，與神成為一；<br/>為顧神權益，奮力往前行，憑靈同行動，完成神旨意。<br/>愛中受囑咐，當彼此洗腳，肢體同背負，相互地代禱，<br/>為建造，愛是極超越的路，成身體模型，使主得滿足。<br/>',NULL,22195,5);
INSERT INTO stanza VALUES('CS926','chorus','主愛激勵我們獻自己，蒙召投身時代水流裡：<br/>啟示高峰，神人生活，照神牧養，達『新的復興』；<br/>『榮耀託付』引我們前行，同著良人開展到全地，<br/>葡萄園裡，獻上愛情，香草山上，催促我主快臨。<br/>主耶穌阿！願你快再臨！<br/>',NULL,22196,6);
INSERT INTO stanza VALUES('CS927','1','三一神已成那靈,滿帶神聖的生命,<br/>像一道水河,可白白取用,<br/>每當我歡然呼求主名;<br/>還有一棵生命樹,供應新鮮又豐富,<br/>祂就是萬有、內住的基督,<br/>藉著主話作我們食物。<br/>我們喫祂並喝祂,天天享受祂,<br/>作我們內在元素,<br/>得以像祂並活祂,同來彰顯祂,<br/>好成為祂活的建築;<br/>有父聖別的性情,有子復活的生命,<br/>加上靈多方變化並作工,<br/>步步進入榮耀中。<br/>',NULL,22197,1);
INSERT INTO stanza VALUES('CS927','2','主,我愛你的定旨,願出代價買金子,<br/>因你,將萬事都看為損失,<br/>憑你大能,模成你的死。<br/>那靈藉萬事管治,除掉我天然雜質,<br/>好構成精金、珍珠和寶石,<br/>像你,純淨而沒有瑕疵。<br/>我們供應三一神給需要的人,<br/>作他們內在元素,<br/>活在生命交通中,跟隨主行動,<br/>將人帶進這活建築;<br/>這是新耶路撒冷,我們正在建構中,<br/>神與人聯調、建造的工程,<br/>全由三一所構成。<br/>',NULL,22198,2);
INSERT INTO stanza VALUES('CS928','1','讚美神,你是恩典化身,<br/>藉成為人,豐豐滿滿賜給我們,<br/>為救我,竟上十架被戳,<br/>捨了自己,將我救活,同坐寶座;<br/>我要唱,全心歌唱,恩典已作王,<br/>我歡暢,全靈歡暢,恩典真無量,<br/>何喜悅,我的所有了結,<br/>有祂真好,有祂無缺,作我一切。<br/>',NULL,22199,1);
INSERT INTO stanza VALUES('CS928','2','感謝神,在你神聖經綸,<br/>所得福分完完全全是本於恩,<br/>我因信,藉著應許而生,<br/>同來得著兒子名分,出於撒冷;<br/>來享受父、子、聖靈,價值益顯明,<br/>來湧流神聖生命,使人得供應,<br/>我一生,必須經過路程,<br/>有祂同在,直到路終,恩典彀用。<br/>',NULL,22200,2);
INSERT INTO stanza VALUES('CS928','3','敬拜神,今我成何等人,<br/>我要見證,全是因著神的宏恩,<br/>從開始,盡是恩典故事,<br/>樣樣是神恩典所賜,無限展示,<br/>願今後,向著我們更洋溢擴增,<br/>到永久,終極完成新耶路撒冷,<br/>願恩典榮耀得著稱讚,<br/>藉著聖城神得彰顯,永永遠遠。<br/>',NULL,22201,3);
INSERT INTO stanza VALUES('CS929','1','當我們在生命、性情、彰顯<br/>和功用上,成為與基督一樣,<br/>我們就彀資格為著祂的身體與祂同工。<br/>當我們無依無靠的信靠主,<br/>倚靠祂作我們的愛和力量,<br/>並且聽祂說話,<br/>我們的盼望就是藉著身體的得贖而被提,<br/>我們的禱告乃是:“主耶穌阿,我願你來!”<br/>我願你來!主耶穌來!<br/>',NULL,22202,1);
INSERT INTO stanza VALUES('CS930','1','日近一日,恩主耶穌快回來;<br/>贖回光陰,勿讓今生空白。<br/>精明童女儆醒豫備不稍怠,<br/>切切等候面見新郎風采。<br/>',NULL,22203,1);
INSERT INTO stanza VALUES('CS930','chorus','當祂來臨,我們是否正等待?<br/>己的糾纏,是否脫離無礙?<br/>何等巴望被提進入祂同在,<br/>享受婚筵,作祂新婦、至愛!<br/>',NULL,22204,2);
INSERT INTO stanza VALUES('CS930','2','主,助我們,黃金歲月全贖回;<br/>屬天膏油,器皿裏常豫備。<br/>每一試煉,都知是你所量<br/>給,使你加多,你愛更顯豐沛。<br/>',NULL,22205,3);
INSERT INTO stanza VALUES('CS930','chorus','主必快來,現今每刻都寶貴;<br/>被靈充滿,買油應當加倍。<br/>苦難試煉,放膽迎接毫不畏;<br/>今雖傷痛,那日國度甘美。<br/>',NULL,22206,4);
INSERT INTO stanza VALUES('CS930','3','主,轉我們,屬魂享樂不留戀,<br/>惟注視你溫柔,美麗榮臉。<br/>保守我們,奔跑賽程不困倦,<br/>忍耐到底,直至見你顯現。<br/>',NULL,22207,5);
INSERT INTO stanza VALUES('CS930','chorus','當主來臨,能否被提到祂前?<br/>能否見祂,坐席享受婚筵?<br/>應當儆醒,無一刻鬆懶隨便;<br/>朝思暮想,惟盼新郎歸旋。<br/>',NULL,22208,6);
INSERT INTO stanza VALUES('CS930','4','同眾童女,歡喜出去迎新郎;<br/>靈裏焚燒,燈都發光剔亮;<br/>器皿充滿,眼目注視祂榮光,<br/>與祂同在,完全滿足歡暢。<br/>',NULL,22209,7);
INSERT INTO stanza VALUES('CS930','chorus','完全滿足─新郎新婦永同享;<br/>完全滿足─直到永世無疆!<br/>何等安息!喜樂、恩愛又輝煌,<br/>永世對耦,福樂盈溢無上!<br/>',NULL,22210,8);
INSERT INTO stanza VALUES('CS916','1','神的聖城,居高華美,<br/>榮耀之事論及你;<br/>神已立你作祂居所,<br/>祂話堅定永不移。<br/>永久磐石為你根基,<br/>安穩住處誰能動?<br/>救恩高牆四面環繞,<br/>永向仇敵顯光榮。<br/>',NULL,22211,1);
INSERT INTO stanza VALUES('CS916','2','看那豐沛活水江河，<br/>湧自神聖永遠愛；<br/>錫安之民不虞匱乏，<br/>因有供應永不衰。<br/>水河所至，乾渴絕迹，<br/>且有恩典施眷顧；<br/>此恩如同賜恩之主，<br/>永不敗落永豐足。<br/>',NULL,22212,2);
INSERT INTO stanza VALUES('CS916','3','錫安聖城蒙福之民，<br/>藉血蒙贖得潔淨；<br/>作神祭司且作君王，<br/>神前侍立同執政。<br/>因主大愛，憑主恩典，<br/>作王管制己生命；<br/>且作祭司獻上感戴，<br/>讚美頌揚無止境。<br/>',NULL,22213,3);
INSERT INTO stanza VALUES('CS916','4','罪人如我竟登錫安，<br/>這是何等的恩情。<br/>任憑俗世譏笑嘲諷，<br/>我所誇耀惟主名。<br/>世人所樂都在消逝，<br/>所誇、所傲終滅絕；<br/>永久寶藏、真實福樂，<br/>惟錫安民能領畧。<br/>',NULL,22214,4);
INSERT INTO stanza VALUES('CH1','1','Praise Him, praise Him, all ye little children,<br/>God is love, God is love;<br/>Praise Him, praise Him, all ye little children,<br/>God is love, God is love.<br/>',NULL,22226,1);
INSERT INTO stanza VALUES('CH1','2','Love Him, love Him, all ye little children,<br/>&nbsp;&nbsp;&nbsp;&nbsp;God is love, God is love;<br/>Love Him, love Him, all ye little children,<br/>&nbsp;&nbsp;&nbsp;&nbsp;God is love, God is love.<br/>',NULL,22227,2);
INSERT INTO stanza VALUES('CH1','3','Thank Him, thank Him, all ye little children,<br/>&nbsp;&nbsp;&nbsp;&nbsp;God is love, God is love;<br/>Thank Him, thank Him, all ye little children,<br/>&nbsp;&nbsp;&nbsp;&nbsp;God is love, God is love.<br/>',NULL,22228,3);
INSERT INTO stanza VALUES('CH2','1','Let the glory of the Lord endure forever.<br/>Let the Lord be glad in His words.<br/>I will sing unto the Lord as long as I live;<br/>I will sing praise to my God while I have my being.<br/>',NULL,22229,1);
INSERT INTO stanza VALUES('CH3','1','The birds upon the tree tops sing their song;<br/>The angels chant their chorus all day long;<br/>The flowers in the garden blend their hue,<br/>So why shouldn’t I, why shouldn’t you praise Him too?<br/>',NULL,22230,1);
INSERT INTO stanza VALUES('CH4','1','This is the day, this is the day.<br/>That the Lord has made, that the Lord has made.<br/>We will rejoice, we will rejoice,<br/>And be glad in it, and be glad in it.<br/>This is the day that the Lord has made.<br/>We will rejoice and be glad in it.<br/>This is the day, this is the day<br/>That the Lord has made.<br/>',NULL,22231,1);
INSERT INTO stanza VALUES('CH4','2','We are the sons, we are the sons,<br/>Of the living God, of the living God.<br/>We will rejoice, we will rejoice,<br/>And be glad in Him, and be glad in Him.<br/>We are the sons of the living God.<br/>We will rejoice and be glad in Him.<br/>We are the sons, we are the sons<br/>&nbsp;&nbsp;&nbsp;&nbsp;Of the living God.<br/>',NULL,22232,2);
INSERT INTO stanza VALUES('CH5','1','Genesis and Exodus, Leviticus, Numbers, Deuteronomy,<br/>Joshua, Judges, Ruth, First and Second Samuel,<br/>&nbsp;&nbsp;&nbsp;&nbsp;and First and Second Kings;<br/>First and Second Chronicles, then Ezra, Nehemiah,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Esther, Job, the book of Psalms,<br/>Proverbs, Ecclesiastes, Song of Songs,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Isaiah, Jeremiah, Lamentations, and Ezekiel;<br/>Daniel, Hosea, Joel, Amos, Obadiah,<br/>Jonah, Micah, Nahum, Habakkuk,<br/>Zephaniah, Haggai, Zechariah, Malachi.<br/>',NULL,22233,1);
INSERT INTO stanza VALUES('CH6','1','Oh, the grass will wither and the flower fade,<br/>But the word will stand forever.<br/>Oh, the grass will wither and the flower fade,<br/>But the word will stand forever.<br/>In the beginning was the Word, the Word in the beginning.<br/>The Word was with God, and the Word was God,<br/>The Word in the beginning.<br/>NOT... A.... jot or a tittle,<br/>&nbsp;&nbsp;an iota or a serif will fail;<br/>&nbsp;&nbsp;it stands forever;<br/>Every jot, every tittle,<br/>&nbsp;&nbsp;every serif and iota is firm,<br/>&nbsp;&nbsp;it stands forever!<br/>',NULL,22234,1);
INSERT INTO stanza VALUES('CH7','1','Honor, honor, honor, honor,<br/>Honor, honor, honor!<br/>Honor, honor, honor, honor,<br/>Honor, honor, honor!<br/>',NULL,22235,1);
INSERT INTO stanza VALUES('CH7','2','Honor God, honor God!<br/>Honor all men also.<br/>Honor God, honor God!<br/>Honor all men also.<br/>',NULL,22236,2);
INSERT INTO stanza VALUES('CH7','3','Do unto others as you would have them do unto you.<br/>Do unto others as you would have them do unto you.<br/>',NULL,22237,3);
INSERT INTO stanza VALUES('CH8','1','D-A-V-I-D, was a skillful shepherd boy, (just a boy,)<br/>Watching over sheep out in the night cold; (Brrrr!)<br/>Seeking for the one who left the sheepfold. (Ba a-a-a-a-a!)<br/>D-A-V-I-D, H-O-N-O-R-E-D<br/>His God, his folks, his brothers and his country, too,<br/>David was the one the Lord had chosen!<br/>None of his brothers, but the little, singing, shepherd boy:<br/>David was the one!<br/>',NULL,22238,1);
INSERT INTO stanza VALUES('CH9','1','You come to me with a sword and a spear,<br/>But I come to you in the name of the God of the ranks of Israel,<br/>Whom you’ve defied, but on this day<br/>Jehovah will deliver you into my hand!<br/>',NULL,22239,1);
INSERT INTO stanza VALUES('CH9','2','It’s not by sword (or shield) that Jehovah saves,<br/>For the battle is the Lord’s, He will prevail!<br/>Then all our shame will be turned away;<br/>And all the earth will know there’s a God in Israel!<br/>',NULL,22240,2);
INSERT INTO stanza VALUES('CH9','3','The giant rose and came to fight,<br/>And David hurried, running to the battle line!<br/>He chose a stone from the five in his sack<br/>And slung it quickly at that giant, just in time!<br/>',NULL,22241,3);
INSERT INTO stanza VALUES('CH9','4','Goliath tall had a giant fall!<br/>Brave David won that day with just a stone and sling!<br/>Their giant dead, the Philistines fled,<br/>And Israel chased them that whole day far, far away!<br/>',NULL,22242,4);
INSERT INTO stanza VALUES('CH10','1','Can you say, “How do you do, do you do, do you do?“<br/>Can you say, “How do you do, how do you do?“<br/>We can say, “How do you do?” and “I’m just fine and how are you?“<br/>We can say, “How do you do, do you do?”<br/>',NULL,22243,1);
INSERT INTO stanza VALUES('CH10','2','Can you give a hand a shake, hand a shake, hand a shake?<br/>Can you give a hand a shake, hand a shake?<br/>We can smile and give a shake, a new friend then we will make,<br/>We can give a hand a shake, hand a shake.<br/>',NULL,22244,2);
INSERT INTO stanza VALUES('CH10','3','Can you look ’em in the eye, in the eye, in the eye?<br/>Can you look ’em in the eye, in the eye?<br/>We can look ’em in the eye, not the floor and not the sky!<br/>We can look ’em in the eye, in the eye.<br/>',NULL,22245,3);
INSERT INTO stanza VALUES('CH10','4','Can you greet with, “Buenos dias, buenos dias, buenos dias“,<br/>Can you greet with “Buenos dias, buenos dias.“<br/>We can greet with “Buenos dias, we’re so glad you came to see us!“<br/>We can greet with “Buenos dias, buenos dias.”<br/>',NULL,22246,4);
INSERT INTO stanza VALUES('CH10','5','Can you bow bending low and say, “Ahn nyeong hasayo?“<br/>Can you bow low and say, “Ahn nyeong hasayo?“<br/>We can bow bending low and say, “Ahn nyeong hasayo!“<br/>To Koreans we say, “Ahn nyeong hasayo.”<br/>',NULL,22247,5);
INSERT INTO stanza VALUES('CH10','6','Can you nod and say, “Nee how,” say, “Nee how,“say, “Nee how,“<br/>Can you nod and say, “Nee how,” say, “Nee how.“<br/>We can nod and say, “Nee how;” They’ll say, “You know Chinese, WOW!“<br/>We can nod and say, “Nee how,” say, “Nee how.”<br/>',NULL,22248,6);
INSERT INTO stanza VALUES('CH11','1','If you’re happy and you know it,<br/>Clap your hands.<br/>If you’re happy and you know it,<br/>Clap your hands.<br/>If you’re happy and you know it,<br/>And you really want to show it,<br/>If you’re happy and you know it,<br/>Clap your hands.<br/>',NULL,22249,1);
INSERT INTO stanza VALUES('CH11','2','If you’re happy and you know it,<br/>Stomp your feet.<br/>(stomp, stomp)<br/>',NULL,22250,2);
INSERT INTO stanza VALUES('CH11','3','If you’re happy and you know it,<br/>Call, “Oh, Lord“.<br/>(Oh, Lord)<br/>',NULL,22251,3);
INSERT INTO stanza VALUES('CH11','4','If you’re happy and you know it,<br/>Say, “Amen“.<br/>(Amen)<br/>',NULL,22252,4);
INSERT INTO stanza VALUES('CH11','5','If you’re happy and you know it,<br/>Do all four.<br/>(clap, clap; stomp, stomp; Oh, Lord; Amen.)<br/>',NULL,22253,5);
INSERT INTO stanza VALUES('CH12','1','Deep and wide, deep and wide,<br/>There’s a fountain flowing deep and wide.<br/>Deep and wide, deep and wide,<br/>There’s a fountain flowing deep and wide.<br/>',NULL,22254,1);
INSERT INTO stanza VALUES('CH13','1','Let’s honor with manners!<br/>Let’s honor each other today!<br/>It’s “Yes, sir!” and “no, sir!” and<br/>“Yes, ma’am!” and “No, ma’am!” and<br/>Before we eat, let’s pray!<br/>“How do you do, sir?” “So glad to meet you!“<br/>Open the door and let her through. Oh,<br/>',NULL,22255,1);
INSERT INTO stanza VALUES('CH13','2','Let’s honor with manners!<br/>Let’s honor each other today!<br/>We’re vying in showing<br/>Politeness and kindness,<br/>Preferring each other this way!<br/>So we say, “Please pass the potatoes.“<br/>Let’s keep our elbows off the table. Oh,<br/>',NULL,22256,2);
INSERT INTO stanza VALUES('CH14','chorus','In the ten commandments God gave us,<br/>There’s a promise found in one:<br/>If we honor both our parents then<br/>our days will be made long.<br/>',NULL,22257,1);
INSERT INTO stanza VALUES('CH14','1','All we think, (all we think!) all we do, (all we do)<br/>All we choose and all we say,<br/>We can show our honor for our folks,<br/>When we cheerfully obey!<br/>',NULL,22258,2);
INSERT INTO stanza VALUES('CH14','2','Obey! (Obey!) Obey! (Obey!)<br/>Obey our folks today. (today)<br/>When we say, “Amen!” we honor them,<br/>Let’s cheerfully obey!<br/>',NULL,22259,3);
INSERT INTO stanza VALUES('CH15','1','B-I-B-L-E,<br/>B-I-B-L-E,<br/>B-I-B-L-E,<br/>the B-I-B-L-E,<br/>Jesus said, It’s written<br/>That a man shall live<br/>By the Word proceeding<br/>From the mouth of God.<br/>',NULL,22260,1);
INSERT INTO stanza VALUES('CH15','2','Not by bread alone,<br/>But by the Word of God,<br/>Not by bread alone<br/>But by the Word of God!<br/>NO! man cannot live by<br/>Earthly bread alone;<br/>YES! we need the words of the<br/>B-I-B-L-E!<br/>',NULL,22261,2);
INSERT INTO stanza VALUES('CH16','1','For a Child is born to us;<br/>a Son is giv’n to us;<br/>and the government is upon His shoulder.<br/>And His Name will be called:<br/>Wonderful Counselor,<br/>Mighty God,<br/>Eternal Father,<br/>Prince of Peace.<br/>(repeat)<br/>',NULL,22262,1);
INSERT INTO stanza VALUES('CH16','2','And His Name will be called:<br/>Wonderful Counselor.<br/>',NULL,22263,2);
INSERT INTO stanza VALUES('CH16','3','The government is upon<br/>His shoulder<br/>',NULL,22264,3);
INSERT INTO stanza VALUES('CH16','4','For a Child is born, a Son is giv’n,<br/>Isaiah nine six.<br/>',NULL,22265,4);
INSERT INTO stanza VALUES('CH17','1','Matthew, the gospel of Jesus, the Christ, who<br/>Came as the King to establish His kingdom.<br/>Recommended and anointed, tested,<br/>Tried, and still rejected,<br/>Jesus, kingly Savior!<br/>His ministry, parables,<br/>Healing, authority,<br/>Crucifixion, then rising in vict’ry:<br/>Sowed He forth the kingdom seed,<br/>He’s coming back some day to reap it!<br/>Jesus, King of Kings!<br/>',NULL,22266,1);
INSERT INTO stanza VALUES('CH18','1','I’m spending time now,<br/>Just me and my God!<br/>I’m lingering longer;<br/>Just me and my God!<br/>',NULL,22267,1);
INSERT INTO stanza VALUES('CH18','2','The sheep are a’ snoring!<br/>I’m singing and psalming!<br/>My heart is a harp-sing<br/>Unto my God!<br/>',NULL,22268,2);
INSERT INTO stanza VALUES('CH18','3','I’m spending time now,<br/>Just me and my God!<br/>I’m lingering longer;<br/>Just me and my God!<br/>',NULL,22269,3);
INSERT INTO stanza VALUES('CH18','4','Your words are sweet as<br/>Honey unto my taste,<br/>And a light unto my path;<br/>I’m lingering,<br/>Just me and my God!<br/>',NULL,22270,4);
INSERT INTO stanza VALUES('CH19','1','In Matthew’s house and at his table,<br/>Jesus was there to eat with all the sinners.<br/>Strong ones don’t need a physician,<br/>He came for those who are ill.<br/>',NULL,22271,1);
INSERT INTO stanza VALUES('CH19','chorus','Then Jesus went to visit,<br/>To teach and preach and heal.<br/>To shepherd all the lost ones,<br/>Compassion He did feel.<br/>',NULL,22272,2);
INSERT INTO stanza VALUES('CH19','2','In Matthew’s house and at his table,<br/>Jesus was there to eat with all the sinners.<br/>Strong ones don’t need a physician,<br/>He came for those who are ill.<br/>',NULL,22273,3);
INSERT INTO stanza VALUES('CH19','3','Jesus said to His disciples:<br/>The harvest is great but the workers are so few!<br/>Pray to the Lord of the harvest<br/>To send out workers, yes, do!<br/>',NULL,22274,4);
INSERT INTO stanza VALUES('CH20','1','I wanna be good ground!<br/>I wanna be good ground!<br/>I wanna be good ground,<br/>So God’s Word can grow in me!<br/>',NULL,22275,1);
INSERT INTO stanza VALUES('CH20','2','I’m gonna break up that hard ground,<br/>I’m gonna dig up those rocks,<br/>Lord, I’m gonna pull out those thorns<br/>So God’s Word can grow in me!<br/>',NULL,22276,2);
INSERT INTO stanza VALUES('CH21','1','There is a name I love to hear,<br/>&nbsp;&nbsp;&nbsp;&nbsp;I love to sing its worth;<br/>It sounds like music in mine ear,<br/>&nbsp;&nbsp;&nbsp;&nbsp;The sweetest name on earth.<br/>',NULL,22277,1);
INSERT INTO stanza VALUES('CH21','chorus','Oh, how I love Jesus,<br/>Oh, how I love Jesus,<br/>Oh, how I love Jesus,<br/>Because He first loved me!<br/>',NULL,22278,2);
INSERT INTO stanza VALUES('CH23','1','Go, Jesus! Go, Jesus, go!<br/>Travel a circuit; You love man so!<br/>Through the grain fields to a town;<br/>Up to the mountains, and then down!<br/>Visit a village, walk by the sea.<br/>Eat in a house with people like me!<br/>All around the countryside,<br/>You’re serving people far and wide!<br/>',NULL,22279,1);
INSERT INTO stanza VALUES('CH24','1','He didn’t stay home;<br/>He went and visited people.<br/>He didn’t stay home;<br/>Jesus taught disciples.<br/>Fed the following crowd outdoors;<br/>Made them glad forevermore;<br/>Serving’s what His life was for;<br/>He didn’t stay home. SO!!!!!<br/>',NULL,22280,1);
INSERT INTO stanza VALUES('CH24','2','Don’t stay home! (go, go!)<br/>Go and visit people!<br/>Don’t stay home! (go, go!)<br/>Go and teach disciples. (GO!)<br/>Fix some food, go out the door;<br/>Make them glad forevermore;<br/>Serving is what life is for,<br/>So DON’T STAY HOME!!<br/>',NULL,22281,2);
INSERT INTO stanza VALUES('CH25','1','He’s the serving Savior, (Yes, He is!)<br/>Comes to all the people (Everywhere)<br/>Full of deep compassion<br/>And sympathy! (What a Savior)<br/>',NULL,22282,1);
INSERT INTO stanza VALUES('CH25','2','Oh, what open love (to the needy ones)<br/>Lots of tender love (to the little ones)<br/>To the leprous one said,<br/>I am willing, be clean! (and He touched Him!)<br/>',NULL,22283,2);
INSERT INTO stanza VALUES('CH26','1','Jesus came proclaiming: God’s kingdom has drawn near!<br/>For this your way of thinking must be fresh and clear.<br/>Repent and change your view! Consider Him anew.<br/>Jesus came proclaiming and He says this to you:<br/>',NULL,22284,1);
INSERT INTO stanza VALUES('CH26','chorus','Repent and believe! Repent and believe!<br/>Jesus came proclaiming: Repent and believe!<br/>R-E-P-E-N-T! B-E-L-I-E-V-E!<br/>Jesus came proclaiming: Repent and believe!<br/>',NULL,22285,2);
INSERT INTO stanza VALUES('CH27','1','Before God put the leaves on the trees...<br/>Before God made the herbs bearing seeds...<br/>',NULL,22286,1);
INSERT INTO stanza VALUES('CH27','chorus','He thought about you...<br/>And He thought about me...<br/>And He loves us...<br/>And He loves us!<br/>',NULL,22287,2);
INSERT INTO stanza VALUES('CH27','2','Before God put the clouds in the sky...<br/>Before He taught the birds how to fly...<br/>',NULL,22288,3);
INSERT INTO stanza VALUES('CH27','3','Before God made the sun giving light...<br/>Before God made the stars shining bright...<br/>',NULL,22289,4);
INSERT INTO stanza VALUES('CH27','4','Before God put the whale in the sea...<br/>Before God made the fish swimming free...<br/>',NULL,22290,5);
INSERT INTO stanza VALUES('CH27','5','Before God made the insects that creep...<br/>Before God made the cattle and sheep...<br/>',NULL,22291,6);
INSERT INTO stanza VALUES('CH28','1','God has made all things,<br/>The Creator He—<br/>Everything that God created<br/>Was made perfectly.<br/>',NULL,22292,1);
INSERT INTO stanza VALUES('CH28','2','God has made all things,<br/>Made them perfectly—<br/>What a wonderful creation<br/>Everything we see.<br/>',NULL,22293,2);
INSERT INTO stanza VALUES('CH28','3','God has made all things,<br/>Made them perfectly—<br/>What a wonderful Creator<br/>In His work we see!<br/>',NULL,22294,3);
INSERT INTO stanza VALUES('CH29','1','God made the universe purposefully.<br/>It was His plan to create man<br/>As the center of all that we see,<br/>That the heavens for the earth be,<br/>And the earth would be for us.<br/>God made the universe so marvelous!<br/>God made the universe so marvelous!<br/>',NULL,22295,1);
INSERT INTO stanza VALUES('CH30','1','God, our God, our God, our God,<br/>Our God, our God is good.<br/>He created me. He created me.<br/>',NULL,22296,1);
INSERT INTO stanza VALUES('CH30','2','God, our God, our God, our God,<br/>Our God, our God is good.<br/>He created you. He created you.<br/>',NULL,22297,2);
INSERT INTO stanza VALUES('CH30','3','God, our God, our God, our God,<br/>Our God, our God is good.<br/>He created us. Yes, our God is good.<br/>He’s God, He’s good,<br/>He’s God, He’s G-O-O-D!<br/>',NULL,22298,3);
INSERT INTO stanza VALUES('CH32','1','There’s a part inside of me—<br/>It’s my conscience, and I see,<br/>If I listen and obey,<br/>I will be preserved this way.<br/>',NULL,22299,1);
INSERT INTO stanza VALUES('CH32','chorus','Yes, I will listen,<br/>Yes, to my conscience;<br/>If I will listen,<br/>Then I will be preserved.<br/>',NULL,22300,2);
INSERT INTO stanza VALUES('CH33','1','Did the mountains and the trees just happen?<br/>Were the flowers always there?<br/>Did the stars put themselves in the sky?<br/>No! God put them there.<br/>',NULL,22301,1);
INSERT INTO stanza VALUES('CH33','2','Did the lions and the bears just happen?<br/>Were the birds always in the air?<br/>Did the fish put themselves in the sea?<br/>No! God put them there.<br/>',NULL,22302,2);
INSERT INTO stanza VALUES('CH34','1','God said, God saw,<br/>God called, and God made.<br/>God created, God blessed, God rested.<br/>It was good.<br/>',NULL,22303,1);
INSERT INTO stanza VALUES('CH35','1','God is so good,<br/>God is so good,<br/>God is so good,<br/>He’s so good to me.<br/>',NULL,22304,1);
INSERT INTO stanza VALUES('CH35','2','God loves me so,<br/>God loves me so,<br/>God loves me so,<br/>He’s so good to me.<br/>',NULL,22305,2);
INSERT INTO stanza VALUES('CH36','1','God will do what He said He will do.<br/>The promises of God are always true.<br/>God will do what He said He will do.<br/>The promises of God are always true.<br/>',NULL,22306,1);
INSERT INTO stanza VALUES('CH37','1','Heaven’s for earth,<br/>Earth’s for man,<br/>Man’s for God, and<br/>That’s what I am;<br/>I’m a man for God.<br/>Yessiree!<br/>I’m for God and He made ME!<br/>',NULL,22307,1);
INSERT INTO stanza VALUES('CH38','1','Look at all the flowers<br/>And look at all the trees.<br/>Our God is amazing;<br/>He created all of these.<br/><br/>So look at all the flowers<br/>And look at all the trees.<br/>Our God loves man;<br/>He created all things.<br/>',NULL,22308,1);
INSERT INTO stanza VALUES('CH38','2','Look at all the flowers<br/>And look at all the trees.<br/>My God is amazing;<br/>He created them for me.<br/><br/>So look at all the flowers<br/>And look at all the trees.<br/>My God loves me;<br/>He created all things.<br/>',NULL,22309,2);
INSERT INTO stanza VALUES('CH38','chorus','Ending:<br/>So look at all the flowers<br/>And let’s look at all the trees.<br/>Our God loves man;<br/>All things are for ME!!<br/>',NULL,22310,3);
INSERT INTO stanza VALUES('CH39','1','Never forget! That it’s God who created you,<br/>Never forget He’s a wonderful God.<br/>Never forget! That it’s God who created you,<br/>Wonderful, wonderful Creator God.<br/>You have...<br/>',NULL,22311,1);
INSERT INTO stanza VALUES('CH39','2','Arms that bend, knees that bend and a back that bends right over,<br/>Toes that wiggle and hands that tickle, and a mouth that<br/>giggles—’hee hee hee.’<br/>',NULL,22312,2);
INSERT INTO stanza VALUES('CH40','1','Whatever God says is true,<br/>Whatever God does is good,<br/>Whatever God plans He carries through,<br/>Whatever God says is true.<br/>',NULL,22313,1);
INSERT INTO stanza VALUES('CH41','1','We would love the Lord our God<br/>With our heart! With our whole heart!<br/>Love our God with all our soul,<br/>With our soul, love the Lord!<br/>Love our God with all our mind—<br/>All we think and all we know.<br/>Love our God with all our strength!<br/>Love the Lord! Love the Lord!<br/>',NULL,22314,1);
INSERT INTO stanza VALUES('CH42','1','Remember your Creator<br/>While you are young,<br/>As a child, know the Scriptures<br/>And seek out God’s truth.<br/>Oh, remember your Creator<br/>While you are young,<br/>And let Him have a way<br/>In the days of your youth.<br/>',NULL,22315,1);
INSERT INTO stanza VALUES('CH42','2','Remember your Creator<br/>While you are young.<br/>To remember our Creator<br/>Means to love Him.<br/>The Lord is the Creator,<br/>Our source of life.<br/>In the days of our youth<br/>We would love only Him.<br/>',NULL,22316,2);
INSERT INTO stanza VALUES('CH42','3','We treasure the Word of God<br/>While we are young,<br/>As a child, we may read it<br/>And read it again.<br/>Yes, the Scriptures are able<br/>To make us wise,<br/>Wise unto salvation<br/>In Jesus the Lord.<br/>',NULL,22317,3);
INSERT INTO stanza VALUES('CH42','4','We come to the light<br/>When we come to God’s Word,<br/>How the light brightly shines<br/>When we really love God!<br/>As we love Him and seek Him,<br/>God opens His Word,<br/>So that God’s light shines brightly<br/>In His holy Word.<br/>',NULL,22318,4);
INSERT INTO stanza VALUES('CH42','5','We like to spend time<br/>In the Word of our God,<br/>To be faithful to read it<br/>With diligent care.<br/>Yes, we read and we pray,<br/>And we pray what we read—<br/>In the days of our youth,<br/>We would open God’s Word.<br/>',NULL,22319,5);
INSERT INTO stanza VALUES('CH42','6','Remember your Creator<br/>While you are young,<br/>From a child, know the Scriptures<br/>And seek out God’s truth.<br/>Oh, remember your Creator<br/>All your life long.<br/>And let HIm have a way<br/>All your days on the earth.<br/>',NULL,22320,6);
INSERT INTO stanza VALUES('CH43','1','Whatever Jehovah pleases<br/>He does in heaven and on earth.<br/>Whatever Jehovah pleases<br/>He does in heaven and on earth.<br/>Whatever Jehovah pleases<br/>He does in heaven and on earth.<br/>Whatever Jehovah pleases<br/>He does in heaven and on earth.<br/>Psalm one hundred thirty five, verse six.<br/>',NULL,22321,1);
INSERT INTO stanza VALUES('CH44','1','Our God is so big,<br/>So strong, and so mighty—<br/>There’s nothing our God cannot do.<br/>That’s right!<br/>(repeat)<br/>',NULL,22322,1);
INSERT INTO stanza VALUES('CH44','2','The mountains are His;<br/>The valleys are His;<br/>The stars are His handiwork, too.<br/>',NULL,22323,2);
INSERT INTO stanza VALUES('CH44','3','Our God is so big,<br/>So strong, and so mighty—<br/>There’s nothing our God cannot do.<br/>That’s right!<br/>',NULL,22324,3);
INSERT INTO stanza VALUES('CH45','1','Who made the world so big and round?<br/>God, our great Creator.<br/>Who put the flowers in the ground?<br/>God, our great Creator.<br/>Who put the stars up in the sky?<br/>Who made the little birds to fly?<br/>Did you do it? No, not I!<br/>God, our great Creator.<br/>',NULL,22325,1);
INSERT INTO stanza VALUES('CH46','1','Wonderf’lly, wonderf’lly,<br/>God made me wonderf’lly,<br/>When I look, I can see I’m just fine.<br/>I’m designed perfectly,<br/>Don’t need changed, no sir-ee!<br/>This same face has been in style<br/>A long, long while.<br/>',NULL,22326,1);
INSERT INTO stanza VALUES('CH46','2','Ears that hear, they’re so dear!<br/>Nose to smell, very well!<br/>And two eyes taking pictures constantly. (click, click)<br/>With my mouth I can feed,<br/>Drink and sing, pray and read<br/>Thank You, Lord, You made me<br/>Wonderf’lly!<br/>',NULL,22327,2);
INSERT INTO stanza VALUES('CH47','1','I love God. He put the leaves on the trees,<br/>He put the fish in the seas,<br/>And the birds in the air.<br/>',NULL,22328,1);
INSERT INTO stanza VALUES('CH47','2','I love God! He put the color in my eye,<br/>He put the fingers on my hands,<br/>And the toes on my feet.<br/>',NULL,22329,2);
INSERT INTO stanza VALUES('CH47','3','So I love God! He does such wonderful things!<br/>He perfectly placed me—<br/>In my family.<br/>',NULL,22330,3);
INSERT INTO stanza VALUES('CH48','1','I want to thank God for making me,<br/>So very specially.<br/>Each part so perfectly,<br/>He made me awesomely!<br/>I want to thank God for making me,<br/>He made me wonderfully,<br/>For He created me!<br/>',NULL,22331,1);
INSERT INTO stanza VALUES('CH49','1','People like to know<br/>How things have occurred.<br/>How did things we see<br/>Ever come to be?<br/>',NULL,22332,1);
INSERT INTO stanza VALUES('CH49','chorus','Who, who, who was there?<br/>Who, who, who was there?<br/>Who, who, who was there?<br/>Who was there with God?<br/>',NULL,22333,2);
INSERT INTO stanza VALUES('CH49','2','If you want to know<br/>Who made all things so,<br/>Go right to the Source,<br/>Which is God, of course!<br/>',NULL,22334,3);
INSERT INTO stanza VALUES('CH49','chorus','Who, who, who was there?<br/>Who, who, who was there?<br/>Who, who, who was there?<br/>Only God was there?<br/>',NULL,22335,4);
INSERT INTO stanza VALUES('CH50','1','You can train a dog to shake hands for fun;<br/>But the paw is for walking when the trick is done.<br/>A paw is designed to run and stand.<br/>The dog has a paw, and the man has a hand.<br/>',NULL,22336,1);
INSERT INTO stanza VALUES('CH51','1','Jesus loves me, this I know,<br/>For the Bible tells me so;<br/>Little ones to Him belong;<br/>They are weak, but He is strong.<br/>',NULL,22337,1);
INSERT INTO stanza VALUES('CH51','chorus','Yes, Jesus loves me,<br/>Yes, Jesus loves me,<br/>Yes, Jesus loves me,<br/>The Bible tells me so.<br/>',NULL,22338,2);
INSERT INTO stanza VALUES('CH51','2','Jesus, take this heart of mine;<br/>Make it pure and wholly Thine.<br/>Thou hast bled and died for me;<br/>I will live henceforth for Thee.<br/>',NULL,22339,3);
INSERT INTO stanza VALUES('CH51','chorus','Yes, I love Jesus.<br/>Yes, I love Jesus.<br/>Yes, I love Jesus.<br/>In prayer I tell Him so.<br/>',NULL,22340,4);
INSERT INTO stanza VALUES('CH52','1','In God’s green pastures feeding by His cool waters lie;<br/>Soft in the evening walk my Lord and I,<br/>All the sheep of His pasture<br/>Fare so wondrously fine; His sheep am I.<br/>',NULL,22341,1);
INSERT INTO stanza VALUES('CH52','chorus','Sisters: Waters cool,<br/>Brothers: In the valley;<br/>Sisters: Pastures green,<br/>Brothers: On the mountain,<br/>Sisters: In the evening<br/>Brothers: In the evening<br/>Everyone: Walk my Lord and I.<br/>',NULL,22342,2);
INSERT INTO stanza VALUES('CH52','chorus','Sisters: Dark the night,<br/>Brothers: In the valley,<br/>Sisters: Rough the way,<br/>Brothers: On the mountain,<br/>Sisters: Step by step...<br/>Brothers: Step by step.<br/>Everyone: My Lord and I.<br/>',NULL,22343,3);
INSERT INTO stanza VALUES('CH52','2','Through the streets of the city in the darkness of the night,<br/>Far from the fold, He heard my lonely cry.<br/>Now I sit at His table in the palace of light;<br/>His sheep am I.<br/>',NULL,22344,4);
INSERT INTO stanza VALUES('CH53','1','Once I thought the love of God was just for you and me.<br/>Once I thought we were the only ones.<br/>Now I know God’s love can find all those from sea to sea;<br/>And when it finds them, they become His sons.<br/>God’s love is warmer than the warmest sunshine,<br/>Softer than a sigh.<br/>God’s love is deeper than the deepest ocean,<br/>Wider than the sky.<br/>God’s love is brighter than the brightest star<br/>That shines every night above;<br/>And there is nothing in this world<br/>That can ever change His love.<br/>',NULL,22345,1);
INSERT INTO stanza VALUES('CH54','1','Hold out your hands! Aren’t they wonderful,<br/>So many things that your hands can do—<br/>Catch a ball, open a can, peel an orange too—<br/>Throw and clap, zip and snap, and wave to you.<br/>',NULL,22346,1);
INSERT INTO stanza VALUES('CH55','1','A dog has a welcome bark, likes to race around the park,<br/>But let me know, if it steps on your toe;<br/>Will it be sorry? I don’t think so.<br/>',NULL,22347,1);
INSERT INTO stanza VALUES('CH55','2','A cat has a silky fur, and a deep and friendly purr,<br/>But let me know, if it steps on your toe,<br/>Will it be sorry? I don’t think so.<br/>',NULL,22348,2);
INSERT INTO stanza VALUES('CH55','3','It’s easy now to see, they’re not like you and me.<br/>I let you know if I step on your toe;<br/>And I’ll be sorry! And I’ll say so.<br/>',NULL,22349,3);
INSERT INTO stanza VALUES('CH56','1','God’s design, God’s design,<br/>Look all around you, it’s easy to find.<br/>God’s design, God’s design<br/>Fills us with wonder, amazed every time.<br/>',NULL,22350,1);
INSERT INTO stanza VALUES('CH56','2','From mountains to-o the seas,<br/>Flowers, bugs, rocks, webs, grass, shells, stars and trees.<br/>God’s design we-e can see<br/>In things great and small, created for me.<br/>',NULL,22351,2);
INSERT INTO stanza VALUES('CH57','1','We rush through the door and there’s so much to say,<br/>But Mom’s on the bed and she looks kind of gray.<br/>Shhhhh... This is when we’re quiet.<br/>',NULL,22352,1);
INSERT INTO stanza VALUES('CH57','2','I’m in the library, looking at books,<br/>If I make a noise then I get funny looks.<br/>Shhhhh... This is when we’re quiet.<br/>',NULL,22353,2);
INSERT INTO stanza VALUES('CH57','3','Today’s our meeting, my friends have all come,<br/>We’ve sung and we’ve chatted, now story’s begun.<br/>Shhhhh... This is when we’re quiet.<br/>',NULL,22354,3);
INSERT INTO stanza VALUES('CH58','1','Jesus loves the little children,<br/>All the children of the world.<br/>Red and yellow, black and white,<br/>All are precious in His sight,<br/>Jesus loves the little children of the world.<br/>',NULL,22355,1);
INSERT INTO stanza VALUES('CH59','1','Jesus’ love is sweet and wonderful,<br/>Jesus’ love is sweet and wonderful,<br/>Jesus’ love is sweet and wonderful,<br/>Oh, wonderful love!<br/>',NULL,22356,1);
INSERT INTO stanza VALUES('CH59','2','So high, you can’t get over it.<br/>So low, you can’t get under it.<br/>So wide, you can’t get around it.<br/>Oh, wonderful love!<br/>',NULL,22357,2);
INSERT INTO stanza VALUES('CH60','1','I’ve got the joy, joy, joy, joy<br/>Down in my heart,<br/>Down in my heart,<br/>Down in my heart,<br/>I’ve got the joy, joy, joy, joy<br/>Down in my heart,<br/>Down in my heart to stay.<br/>',NULL,22358,1);
INSERT INTO stanza VALUES('CH60','2','And I’m so happy,<br/>So very happy;<br/>I’ve got the love of Jesus in my heart.<br/>And I’m so happy,<br/>So very happy,<br/>I’ve got the love of Jesus in my heart.<br/>',NULL,22359,2);
INSERT INTO stanza VALUES('CH61','1','God is light, and in Him there is no darkness at all!<br/>Oh, how we love within His presence to dwell!<br/>In this light we enjoy a constant cleansing within—<br/>&nbsp;&nbsp;&nbsp;&nbsp;From every sin!<br/>',NULL,22360,1);
INSERT INTO stanza VALUES('CH61','chorus',replace('Sisters: In the light,<br/>Brothers: We are walking—<br/>Sisters: Fellowship,<br/>Brothers: We’re enjoying;<br/>Sisters: And the blood<br/>Brothers: Of God’s Son<br/>Everyone: Is cleansing us from sin.\nSisters: We confess,<br/>Brothers: He is faithful<br/>Sisters: To forgive—<br/>Brothers: He is righteous.<br/>Sisters: What a joy!<br/>Brothers: We are cleansed<br/>Everyone: From every sin!<br/>','\n',char(10)),NULL,22361,2);
INSERT INTO stanza VALUES('CH62','1','Trust in the Lord with all your heart,<br/>Lean not to your own understanding.<br/>In all your ways acknowledge Him,<br/>And He shall direct your paths.<br/>',NULL,22362,1);
INSERT INTO stanza VALUES('CH63','1','The fish need water,<br/>The birds need air, (clap clap clap)<br/>The children need home meetings.<br/>(repeat)<br/>',NULL,22363,1);
INSERT INTO stanza VALUES('CH63','2','The cows eat grass,<br/>The cars need gas, (beep beep beep)<br/>The children need home meetings.<br/>(repeat)<br/>',NULL,22364,2);
INSERT INTO stanza VALUES('CH63','3','I need you,<br/>And you need me, (clap clap clap)<br/>We’re members of a family.<br/>(repeat)<br/>',NULL,22365,3);
INSERT INTO stanza VALUES('CH63','3','And God needs us,<br/>And we need God, (clap clap clap)<br/>To be His testimony.<br/>(repeat)<br/>',NULL,22366,4);
INSERT INTO stanza VALUES('CH64','1','In everything we do and say,<br/>We are sowing seeds.<br/>And the kind of seeds we sow<br/>Will be what we reap.<br/>How we act, how we play,<br/>Everything, everything, each and every day.<br/>In everything we do and say,<br/>We are sowing seeds.<br/>',NULL,22367,1);
INSERT INTO stanza VALUES('CH65','1','I’m a vessel, this I know!<br/>For the Bible tells me so.<br/>God’s the Potter, I’m the clay;<br/>He made me this special way.<br/>',NULL,22368,1);
INSERT INTO stanza VALUES('CH66','1','I love to sing a joyful song,<br/>That turns my heart to God,<br/>A song that fills my every thought<br/>With love only for Him.<br/>',NULL,22369,1);
INSERT INTO stanza VALUES('CH67','1','Remember your Creator<br/>While you are young,<br/>As a child, know the Scriptures<br/>And seek out God’s truth.<br/>Remember your Creator<br/>While you are young,<br/>Let Him have a way<br/>In the days of your youth.<br/>',NULL,22370,1);
INSERT INTO stanza VALUES('CH67','2','Remember your Creator<br/>While you are young.<br/>To remember our Creator<br/>Means to love Him.<br/>The Lord is the Creator,<br/>Our source of life.<br/>In the days of our youth<br/>We would love only Him.<br/>',NULL,22371,2);
INSERT INTO stanza VALUES('CH68','1','By listening (echo)<br/>I can obey (echo)<br/>All of the words (echo)<br/>My parents say. (echo)<br/>',NULL,22372,1);
INSERT INTO stanza VALUES('CH68','chorus','Obedience, love, joy, and peace,<br/>Daily these must all increase<br/>In the proper boys and girls<br/>Who are the Lord’s.<br/>',NULL,22373,2);
INSERT INTO stanza VALUES('CH68','2','A heart of love (echo)<br/>Is one that’s kind, (echo)<br/>Forgiving is (echo)<br/>One of its signs. (echo)<br/>',NULL,22374,3);
INSERT INTO stanza VALUES('CH68','3','I, child of joy (echo)<br/>When friends are sad (echo)<br/>With tearful words, (echo)<br/>Will make them glad. (echo)<br/>',NULL,22375,4);
INSERT INTO stanza VALUES('CH68','4','Peacemakers are (echo)<br/>What we should be; (echo)<br/>Speaking kind words (echo)<br/>Making harmony. (echo)<br/>',NULL,22376,5);
INSERT INTO stanza VALUES('CH69','1','Listen, listen, your conscience speaks to you.<br/>If you will listen, you’ll know what to do.<br/>When you obey then you are happy too.<br/>Listen to your conscience speak the whole day through.<br/>',NULL,22377,1);
INSERT INTO stanza VALUES('CH69','2','Listen, listen, your parents speak to you.<br/>If you will listen, you’ll know what to do.<br/>When you obey then you are happy too.<br/>Listen to your parents speak the whole day through.<br/>',NULL,22378,2);
INSERT INTO stanza VALUES('CH70','1','What do you do when your friends say,<br/>“Let’s do” something you know you really shouldn’t?<br/>That’s the time to walk away and part company.<br/>Part company, part company,<br/>That’s the time to walk away and part company.<br/>',NULL,22379,1);
INSERT INTO stanza VALUES('CH70','2','We don’t need those kinds of friends<br/>And we don’t need to be with them;<br/>They’ll only hurt us in the end, they’re bad company.<br/>Bad company, bad company,<br/>Don’t be afraid to say, “Goodbye” to bad company.<br/>',NULL,22380,2);
INSERT INTO stanza VALUES('CH70','3','What kind of friends then should we play with,<br/>Have overnight, or spend the day with?<br/>Those who are going the right way; they’re good company.<br/>Good company, good company,<br/>Those who are going the right way are good company.<br/>',NULL,22381,3);
INSERT INTO stanza VALUES('CH71','1','We are so happy we’re here today.<br/>This time is special in many ways;<br/>So as we gather we gladly say:<br/>Now it’s children’s time.<br/>',NULL,22382,1);
INSERT INTO stanza VALUES('CH71','chorus','Now it’s children’s time,<br/>Now it’s children’s time,<br/>This time is special in many ways,<br/>Now it’s children’s time.<br/>',NULL,22383,2);
INSERT INTO stanza VALUES('CH72','1','Where are your shoes?<br/>Where are your shoes?<br/>Can’t find them! Can’t find them!<br/>They are where you left them.<br/>They are where you left them.<br/>Where is that? Where is that?<br/>',NULL,22384,1);
INSERT INTO stanza VALUES('CH72','2','If you put them, if you put them,<br/>In their place, in their place,<br/>You’ll know where to find them.<br/>You’ll know where to find them.<br/>They’ll be there! They’ll be there!<br/>',NULL,22385,2);
INSERT INTO stanza VALUES('CH73','1','Open up to your parents, open up.<br/>Open up to your parents, open up.<br/>For you know your parents love you,<br/>They’re the best ones who can help you,<br/>But it’s up to you to come and open up.<br/>',NULL,22386,1);
INSERT INTO stanza VALUES('CH73','2','Come and tell your troubles to them, open up.<br/>Come and tell your troubles to them, open up.<br/>Let them know how you are feeling,<br/>For you know that they are caring<br/>About everything you’re sharing, open up.<br/>',NULL,22387,2);
INSERT INTO stanza VALUES('CH74','1','No man ever, spoke like Jesus;<br/>No man ever, no man ever;<br/>No man ever, spoke like Jesus,<br/>John seven, forty-six.<br/>',NULL,22388,1);
INSERT INTO stanza VALUES('CH74','2','Jesus said, I’m the Bread!<br/>Peace, be still! Bring the children.<br/>He declared, I’m the Shepherd,<br/>Stretch your hand out! You’re forgiv’n!<br/>',NULL,22389,2);
INSERT INTO stanza VALUES('CH74','3','Jesus said, I’m resurrection!<br/>I can give you living water!<br/>If you’ve seen Me, you’ve seen the Father!<br/>No man ever spoke like Him!<br/>',NULL,22390,3);
INSERT INTO stanza VALUES('CH22','1','All English children call Him, “Lord,“<br/>And all the Spanish say, “Senor,“<br/>With all the Germans who call Him, “Herr.“<br/>They are calling His name everywhere.<br/>',NULL,22391,1);
INSERT INTO stanza VALUES('CH22','2','“O Shuyo,” call the Japanese,<br/>“O Tju Ah,” echo the Chinese,<br/>“O Hallelujah,” they all exclaim.<br/>In each land they are praising His Name.<br/>',NULL,22392,2);
INSERT INTO stanza VALUES('CH22','3','Children are meeting in Brazil,<br/>Canada, Mexico, Taiwan,<br/>England, New Zealand, and Germany.<br/>Hear them all, as they sing joyfully.<br/>',NULL,22393,3);
INSERT INTO stanza VALUES('CH31','1','Lord, today, keep my heart,<br/>Keep it all the day.<br/>While I’m young, keep my heart<br/>Soft, dear Lord, I pray;<br/>Lord, I would keep my heart through everyday<br/>Soft and open to You.<br/>',NULL,22394,1);
INSERT INTO stanza VALUES('C557','chorus',replace('阿利路亞！阿利路亞！<br/>恩惠臨到如同江河；<br/>阿利路亞！阿利路亞！<br/>恩惠臨到如同江河。<br/>\n','\n',char(10)),NULL,22395,2);
INSERT INTO stanza VALUES('C557','chorus','阿利路亞！阿利路亞！<br/>榮光照耀將我射過；<br/>阿利路亞！阿利路亞！<br/>榮光照耀將我射過。<br/>',NULL,22396,4);
INSERT INTO stanza VALUES('C557','chorus','阿利路亞！阿利路亞！<br/>摸著生命活水泉源；<br/>阿利路亞！阿利路亞！<br/>摸著生命活水泉源。<br/>',NULL,22397,6);
INSERT INTO stanza VALUES('NS417','1','Waters to swim in will meet our every need,<br/>Water is flowing and never to recede;<br/>Limited, restricted by living, flowing grace,<br/>Losing all our freedom, our soul-life is replaced.<br/>',NULL,22501,1);
INSERT INTO stanza VALUES('NS417','chorus','Drink the living water, (Sisters)<br/>Rivers flowing free! (Brothers)<br/>Water! Living waters! (Sisters)<br/>Have Your way in me! (Brothers)<br/>Daily increasing the growth of life in me,<br/>For His glorious building and His recovery!<br/>',NULL,22502,2);
INSERT INTO stanza VALUES('NS417','2','Waters to swim in is flowing toward the east,<br/>Water is flowing to glory that we seek;<br/>Having the preeminence in life, work and home,<br/>The church life is a life-flow from which we never roam.<br/>',NULL,22503,3);
INSERT INTO stanza VALUES('NS417','3','Waters to swim in, increasing stage by stage,<br/>Flowing and rising to consummate the age;<br/>Judging and testing that we, more life, possess,<br/>Until the living Jesus, His name, all men confess.<br/>',NULL,22504,4);
INSERT INTO stanza VALUES('NS417','chorus','Drink the living water (Sisters)<br/>Rivers flowing free! (Brothers)<br/>Water! Living waters! (Sisters)<br/>Have Your way in me! (Brothers)<br/>Daily increasing the growth of life in me,<br/>For His glorious building and His recovery!<br/>',NULL,22505,5);
INSERT INTO stanza VALUES('NS418','1','Christ is coming as a thief to steal those who are faithful,<br/>Those who are most valuable and in the night, so watchful.<br/>I seek, Lord, to be precious; make me a crazy lover!<br/>Increase Your life within me that I would be Your treasure.<br/><br/>Christ will come as a bridegroom—His person most attractive—<br/>Taking virgins wise with Him—those in pursuit so active.<br/>I buy oil for my vessel; may Thy life spread to my soul.<br/>When we’d meet I’d be burning and savor Your feast so full.<br/>',NULL,22506,1);
INSERT INTO stanza VALUES('NS418','chorus','Christ’s coming is His presence<br/>Spreading in us.<br/>He’s promised to come quickly;<br/>Lord, grow in us!<br/>',NULL,22507,2);
INSERT INTO stanza VALUES('NS418','2','Christ will be the morning star to those eagerly waiting,<br/>Watching for Him everyday in darkness for His rising.<br/>It’s dark and most are sleeping; I rise for Your appearing.<br/>Reward me every morning; I want Your gentle shining.<br/><br/>Christ is coming as a judge, all His people to meet.<br/>All our work He’ll test through fire before His judgement seat.<br/>So burn in me today, Lord! I open to Your searching.<br/>Burn the wood and fill with gold; I’m desperate for Your purging!<br/>',NULL,22508,3);
INSERT INTO stanza VALUES('NS418','3','Christ is coming as a King to spread His kingdom on earth.<br/>He will reign with all His saints who know His kingdom’s worth.<br/>Reign in all my life, dear King; I give You full permission.<br/>Under Your authority, I’m given Your dominion.<br/><br/>Christ will come still as a Man—the Son of Man forever.<br/>First He was God’s only Son, now He has many brothers.<br/>The Father’s Firstborn Son now has a pure duplication;<br/>We truly match each other—we are divine and human.<br/>',NULL,22509,4);
INSERT INTO stanza VALUES('NS419','1','And we have the prophetic word<br/>Made more firm, to which you do well<br/>To give heed as to a lamp<br/>Shining in a dark place,<br/>',NULL,22510,1);
INSERT INTO stanza VALUES('NS419','2','Until the day dawns<br/>And the morning star<br/>Rises in your hearts.<br/>(repeat)<br/>',NULL,22511,2);
INSERT INTO stanza VALUES('NS420','1','He who testifies these things says,<br/>Yes, I come quickly.<br/>He who testifies these things says,<br/>Yes, I come quickly.<br/>Amen. Come, Lord!<br/>Come, Jesus quickly!<br/>Amen. Come, Lord!<br/>Come, Jesus quickly!<br/>',NULL,22512,1);
INSERT INTO stanza VALUES('NS421','1','Have you seen God’s salvation?<br/>Do you feel His provision?<br/>Have you won the victory o’er the flesh?<br/>Have you entered the kingdom of God?<br/>',NULL,22513,1);
INSERT INTO stanza VALUES('NS421','chorus','Have you climbed the mountain?<br/>Are you in the light?<br/>Have you changed your diet?<br/>Are you eating Christ?<br/>',NULL,22514,2);
INSERT INTO stanza VALUES('NS421','2','Do you long for His presence?<br/>Do you know His intention<br/>Is to make us just the same as He?<br/>And to love Him constantly?<br/>',NULL,22515,3);
INSERT INTO stanza VALUES('NS421','3','Will you be a loving seeker?<br/>Not a poor, dead law keeper?<br/>We can read His word day by day,<br/>Infuse us Lord, we pray.<br/>',NULL,22516,4);
INSERT INTO stanza VALUES('NS421','4','Are you in His recovery?<br/>Do you know the highest story<br/>Is the mingling of both God and man<br/>To fulfill His eternal plan?<br/>',NULL,22517,5);
INSERT INTO stanza VALUES('NS421','chorus','We have climbed the mountain,<br/>We are in the light,<br/>We have changed our diet,<br/>We are eating Christ!<br/>',NULL,22518,6);
INSERT INTO stanza VALUES('NS421','end-note','(Repeat the last line of each verse)<br/>',NULL,22519,7);
INSERT INTO stanza VALUES('NS422','1','But we all with unveiled face,<br/>Beholding and reflecting like a mirror<br/>The glory of the Lord, are being transformed<br/>Into the same image<br/>From glory to glory,<br/>Even as from the Lord Spirit.<br/>From glory to glory,<br/>Even as from the Lord Spirit.<br/>',NULL,22520,1);
INSERT INTO stanza VALUES('NS423','1','Of which I became a minister<br/>According to the stewardship<br/>Of God, which was given<br/>To me for you,<br/>To complete the word of God,<br/>The mystery which has been hidden<br/>From the ages and from the generations<br/>But now has been manifested<br/>To His saints;<br/>To whom God willed to make known<br/>What are the riches<br/>Of the glory of this mystery<br/>Among the Gentiles,<br/>Which is Christ in you,<br/>The hope of glory.<br/>',NULL,22521,1);
INSERT INTO stanza VALUES('NS424','1','Christ desires to marry us,<br/>By His Word He’s preparing us,<br/>To present the church glorious<br/>To Himself, as His Bride.<br/>',NULL,22522,1);
INSERT INTO stanza VALUES('NS424','2','Saints, enjoy the Word every day,<br/>Get those blemishes washed away;<br/>Open your Bibles, rejoice always,<br/>Singing to the Lord.<br/>',NULL,22523,2);
INSERT INTO stanza VALUES('NS424','3','Christ desires to marry us,<br/>By His Word He’s preparing us,<br/>To present the church glorious<br/>To Himself, as His Bride.<br/>',NULL,22524,3);
INSERT INTO stanza VALUES('NS425','1','And I saw the holy city,<br/>New Jerusalem,<br/>Coming down out of heaven from God,<br/>Prepared as a bride<br/>Adorned for her husband,<br/>Coming down out of heaven from God.<br/>',NULL,22525,1);
INSERT INTO stanza VALUES('NS426','1','For the word of God, word of God,<br/>Is living and operative, operative,<br/>And sharper than any two-edged sword,<br/>And piercing even to the<br/>Dividing of soul and spirit<br/>And of joints and marrow,<br/>And able to discern<br/>The thoughts and intentions of the heart,<br/>The thoughts and intentions of the heart.<br/>',NULL,22526,1);
INSERT INTO stanza VALUES('NS427','1','I have brought you out of Egypt.<br/>I’ve gathered you unto Myself.<br/>O Israel how I have loved you!<br/>O how much I long to be with you!<br/>With my living Word I’ll infuse you,<br/>That you may be one with Me always.<br/>',NULL,22527,1);
INSERT INTO stanza VALUES('NS427','2','I love Your Word O Jehovah!<br/>Because Your Word is just You!<br/>Your words infuse me with all that You are—<br/>Until I express only You.<br/>',NULL,22528,2);
INSERT INTO stanza VALUES('NS428','1','In the clefts of the rock<br/>I delight to be.<br/>In the covert of the precipice<br/>You would find me.<br/>Lord, conform me now,<br/>Daily to Your death.<br/>Let me see Your countenance,<br/>I am a dove,<br/>In the clefts of the rock.<br/>',NULL,22529,1);
INSERT INTO stanza VALUES('NS428','2','My Beloved responds:<br/>Rise up my love,<br/>My beauty and come away;<br/>The rain is gone.<br/>The winter is past,<br/>The time of singing has come.<br/>Rise up and come away,<br/>You are my dove,<br/>In the clefts of the rock.<br/>',NULL,22530,2);
INSERT INTO stanza VALUES('NS428','3','It’s just so difficult,<br/>In these clefts to remain.<br/>Naught but Your resurrection power<br/>Could me sustain.<br/>Now to Your call I respond,<br/>From introspection to come.<br/>Now and always, my Beloved,<br/>I’d be Your dove,<br/>In the clefts of the Rock.<br/>',NULL,22531,3);
INSERT INTO stanza VALUES('NS429','1','Through God’s dispensing, abundance of grace,<br/>Christ’s saving life will reign and death displace;<br/>God’s holy nature, our life sanctifies,<br/>His saving life soon, our life glorifies,<br/>His saving life soon, our life glorifies...<br/>(our life, glorifies.)<br/>',NULL,22532,1);
INSERT INTO stanza VALUES('NS429','2','The law of life from our spirit within,<br/>Saves us from death and the bondage of sin;<br/>Spontaneously working, from slavery freed,<br/>His divine life is forever increased,<br/>His divine life is forever increased...<br/>(forever increased.)<br/>',NULL,22533,2);
INSERT INTO stanza VALUES('NS429','3','The divine Trinity spreads through our soul,<br/>To saturate our whole being, life’s goal;<br/>We become members, the Body of Christ,<br/>Built up together by Christ’s saving life,<br/>Built up together by Christ’s saving life...<br/>(by Christ’s saving life.)<br/>',NULL,22534,3);
INSERT INTO stanza VALUES('NS429','4','Christ’s saving life when expressed in each town,<br/>Strengthens the saints causing grace to abound;<br/>And by the reigning in life every church<br/>Is blent together, and Satan is crushed,<br/>Is blent together and Satan is crushed...<br/>(and Satan is crushed.)<br/>',NULL,22535,4);
INSERT INTO stanza VALUES('NS430','1','The spirit of man<br/>Is the lamp of Jehovah,<br/>Searching all the innermost parts<br/>Of the inner being.<br/>(repeat)<br/>',NULL,22536,1);
INSERT INTO stanza VALUES('NS430','2','The spirit of man<br/>Is the lamp of Jehovah,<br/>The spirit of man<br/>Is the lamp of Jehovah,<br/>The spirit of man...<br/>',NULL,22537,2);
INSERT INTO stanza VALUES('NS431','1','And as for you,<br/>The anointing which you have received<br/>From Him abides in you, and you have no need<br/>That anyone teach you;<br/>But as His anointing teaches you<br/>Concerning all things and is true<br/>And is not a lie,<br/>And even as it has taught you,<br/>Abide in Him,<br/>Abide in Him.<br/>',NULL,22538,1);
INSERT INTO stanza VALUES('NS432','1','Lord, You are the General<br/>Leading us triumphantly;<br/>We Your little captives, Lord,<br/>Showing forth Your victory.<br/>',NULL,22539,1);
INSERT INTO stanza VALUES('NS432','chorus','Take me captive, Lord,<br/>Never let me win;<br/>Defeat me all the time<br/>And conquer me within.<br/>',NULL,22540,2);
INSERT INTO stanza VALUES('NS432','2','Lord, I open all the way<br/>Just to be invaded;<br/>By Your Spirit all renewed<br/>Till I’m permeated.<br/>',NULL,22541,3);
INSERT INTO stanza VALUES('NS432','chorus','Day by day I grow,<br/>Be the stronger part;<br/>Lord, for this I pray,<br/>You make Your home my heart.<br/>',NULL,22542,4);
INSERT INTO stanza VALUES('NS433','chorus','If we do not have the heart to take care of God’s house for His satisfaction,<br/>No matter how much we eat or drink or how well we dress,<br/>There will be no satisfaction; if we neglect the church—<br/>Thus says Jehovah, Consider your ways.<br/>Go up to the mountain and bring wood,<br/>And build My house, and I’ll take pleasure in it,<br/>And will be glorified.<br/>',NULL,22543,1);
INSERT INTO stanza VALUES('NS434','1','Listen closely now to His gospel free:<br/>You were made by God to His vessel be;<br/>You were formed as a man,<br/>To fulfill His great plan:<br/>Now He wants to be your life!<br/>He will be so real to you,<br/>Make your life so beautiful,<br/>Full of joy, and meaningful,<br/>If you come to Him.<br/>',NULL,22544,1);
INSERT INTO stanza VALUES('NS434','2','In eternity He selected you,<br/>Then He came to earth in His love for you;<br/>On the cross, His life gave,<br/>Then He rose from the grave.<br/>Coming forth to seek for you,<br/>To bring God Himself to you,<br/>Life divine impart to you,<br/>Grace abundant give that you<br/>May be satisfied.<br/>',NULL,22545,2);
INSERT INTO stanza VALUES('NS434','3','When the Triune God lives Himself in you,<br/>He will change your being, your life renew;<br/>You’ll be quickened within,<br/>Filled with joy to the brim,<br/>And your flesh shall rest in hope!<br/>Open now your heart to Him,<br/>Breathe His name from deep within,<br/>In an instant He’ll come in<br/>And with you be one!<br/>',NULL,22546,3);
INSERT INTO stanza VALUES('NS435','1','I’m so happy here,<br/>With my Father dear,<br/>Once lost, now I’m near again!<br/>(It was) First His smiling face,<br/>Then His warm embrace,<br/>I’m surprised by grace again!<br/>',NULL,22547,1);
INSERT INTO stanza VALUES('NS435','chorus','I was lost, now I’m found again!<br/>I was dead, but now I live!<br/>Come rejoice with us, and be merry then.<br/>Back in my Father’s house again!<br/>',NULL,22548,2);
INSERT INTO stanza VALUES('NS435','2','Robe, ring, sandals on<br/>And my hunger’s gone!<br/>Back where I belong , again!<br/>(Because He) Clothed me thoroughly,<br/>(And then He) Reinstated me!<br/>(Now I’m) Back in the family again!<br/>',NULL,22549,3);
INSERT INTO stanza VALUES('NS436','chorus','And let the peace of Christ<br/>Arbitrate in your hearts,<br/>To which also<br/>You were called<br/>In one Body;<br/>And be thankful.<br/>(repeat)<br/>',NULL,22550,1);
INSERT INTO stanza VALUES('NS437','1','Lord, You’re with me when I’m by myself,<br/>Always comforting me when I’m lonely,<br/>You’re the One in whom I find my true rest,<br/>And You satisfy me...<br/>',NULL,22551,1);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>Lord, You are the only One for me.<br/>And I see...<br/>You’re the Friend who’s with me constantly.<br/>And I see...<br/>Lord, You’re living right inside of me.<br/>And I see, Lord You are for me.<br/>',NULL,22552,2);
INSERT INTO stanza VALUES('NS437','2','You became a man to die for me,<br/>You shed Your blood that I might be redeemed,<br/>You loved me more than my words can ere tell,<br/>And You attracted me...<br/>',NULL,22553,3);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>Lord, You died and rose to save me to You.<br/>And I see...<br/>A divine romance with us human beings.<br/>And I see...<br/>You loved me before time ever began.<br/>And I see You really love me.<br/>',NULL,22554,4);
INSERT INTO stanza VALUES('NS437','3','You’re the One inside who cherishes me,<br/>Feeding me with milk from Your holy Word,<br/>Lord, You bring me just to feast upon You.<br/>And You feed me richly...<br/>',NULL,22555,5);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>You’re the One who’s always shepherding me.<br/>And I see...<br/>You’re the One who’s feeding, watering me.<br/>And I see...<br/>You’re the One who loves me as Your sheep.<br/>And I see, Lord, You shepherd me.<br/>',NULL,22556,6);
INSERT INTO stanza VALUES('NS437','4','Lord, I consecrate myself unto You,<br/>My time, my life, my riches; future too,<br/>You’re the One on whom I’ll pour everything,<br/>That’s because I love You...<br/>',NULL,22557,7);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>You’re the only One who’s within my view.<br/>And I see...<br/>You’re the One who I will give myself to.<br/>And I see...<br/>You’re the only One who I will pursue.<br/>’Cause I see, Lord, You are lovely.<br/>',NULL,22558,8);
INSERT INTO stanza VALUES('NS437','5','Lord, without You I just cannot go on,<br/>You’re the One in whom my life has meaning,<br/>I am absolutely for Your purpose,<br/>And I know why I live...<br/>',NULL,22559,9);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>You’re the only One who I truly need.<br/>And I see...<br/>I am living for Your economy.<br/>And I see...<br/>It’s because Your being captivates me.<br/>And I see I’m in love with You.<br/>',NULL,22560,10);
INSERT INTO stanza VALUES('NS437','6','Lord, I’ve set my feet upon the track,<br/>Pressing onward just to fulfill Your dream,<br/>And may I nevermore turn my head back,<br/>’Cause I am just for You...<br/>',NULL,22561,11);
INSERT INTO stanza VALUES('NS437','chorus','And now I see...<br/>Lord, You’ve drawn me away to Yourself.<br/>And I see...<br/>I’m pursuing You, Lord, wholeheartedly.<br/>And I see...<br/>There is nothing else on earth for me.<br/>And I see, Lord, You are my goal.<br/>',NULL,22562,12);
INSERT INTO stanza VALUES('NS438','1','What a Christ we have, the all-inclusive One,<br/>Our allotted portion, set apart in light.<br/>In the kingdom of the Son of God, the Son of God’s love,<br/>Here He rules us in the light of His love.<br/>',NULL,22563,1);
INSERT INTO stanza VALUES('NS438','2','Lift your eyes up and look from where you are.<br/>When you see the Christ, our all-inclusive land,<br/>Then we walk in this blessed land, enjoying all we see,<br/>Getting saved eating milk and honey.<br/>',NULL,22564,2);
INSERT INTO stanza VALUES('NS438','3','See the wheat, the restricted Jesus Christ.<br/>Incarnation was restriction in the flesh.<br/>Limited outwardly, by God’s power set free,<br/>Resurrected as unlimited barley.<br/>',NULL,22565,3);
INSERT INTO stanza VALUES('NS438','4','See the vine trees, the sacrificing Christ.<br/>He produced wine thus cheering God and man.<br/>When we drink this new wine, we are so energized,<br/>For the Lord to be a living sacrifice.<br/>',NULL,22566,4);
INSERT INTO stanza VALUES('NS438','5','See the fig trees, Christ’s sweetness our supply.<br/>To progress in the joy of all our faith,<br/>Be a channel of supply so others experience Christ,<br/>And be happy in the bountiful supply.<br/>',NULL,22567,5);
INSERT INTO stanza VALUES('NS438','6','See the pomegranates, fulness of His life;<br/>The abundance and the beauty of this life.<br/>As the olive tree the Spirit fills to honor God and man,<br/>Bearing fruit as branches grafted into Christ.<br/>',NULL,22568,6);
INSERT INTO stanza VALUES('NS438','7','See our portion so available to take,<br/>To be walked in and experienced in full.<br/>Apprehending the unsearchable extent of this good land,<br/>When we corporately enjoy Him with the saints.<br/>',NULL,22569,7);
INSERT INTO stanza VALUES('NS439','1','Genuine, Exact, Strict,<br/>Diligent, Broad, Fine,<br/>Stable, Patient, Deep,<br/>Pure, Just, Calm,<br/>Single, Corporate, Open,<br/>Affectionate, Ardent, Accommodating,<br/>Strong, Pliant, Submissive,<br/>Suffering, Lowly, Poor,<br/>Steadfast, Enduring, Bearing,<br/>Clear, Magnanimous, and Grave.<br/>',NULL,22570,1);
INSERT INTO stanza VALUES('NS440','1','Revelation Twenty-Two Verse Sixteen, Seventeen say,<br/>I Jesus have sent My angel<br/>To testify to you these things, these things<br/>For the churches.<br/>I am the Root<br/>And the Offspring of David,<br/>The bright morning star,<br/>The bright morning star.<br/>',NULL,22571,1);
INSERT INTO stanza VALUES('NS440','2','And the Spirit and the bride say, Come!<br/>And let him who hears say, Come! Come!<br/>And let him who is thirsty come,<br/>Thirsty come, thirsty come;<br/>Let him who wills, wills, wills<br/>Take the water of life,<br/>Take the water of life<br/>Freely, freely.<br/>',NULL,22572,2);
INSERT INTO stanza VALUES('NS441','1','The secret of the universe<br/>In ages past a mystery<br/>Hidden in God but now made known<br/>By revelation’s six-fold key,<br/>Which opens and unlocks the plan<br/>Of His economy<br/>To gain a wife, His counterpart,<br/>And match eternally.<br/>',NULL,22573,1);
INSERT INTO stanza VALUES('NS441','chorus','The Triune God, tripartite man;<br/>A universal pair.<br/>The Spirit processed, bride transformed;<br/>One married nature share.<br/>',NULL,22574,2);
INSERT INTO stanza VALUES('NS441','2','Creation is the lovely platform<br/>Of this divine romance sublime<br/>Between a creature and Creator<br/>Upon the bridge of space and time;<br/>For this the heavens were stretched forth<br/>The earth’s foundations laid<br/>Tripartite man, made to contain Him,<br/>Was with a spirit made.<br/>',NULL,22575,3);
INSERT INTO stanza VALUES('NS441','3','God became man through incarnation<br/>Man’s empty virtues to imbue,<br/>In Christ fulfilling His intention<br/>Creation old becoming new;<br/>God’s attributes so bountiful<br/>In human virtues shown<br/>Uplifted, filled, enriched, and strengthened;<br/>Love, life, and light—made known.<br/>',NULL,22576,4);
INSERT INTO stanza VALUES('NS441','4','Though man became usurped by Satan<br/>God gave His Son man’s life to win;<br/>The Olive Tree was cut and wounded<br/>So sinners could be grafted in<br/>Transferred from Adam into Christ,<br/>Brought out of death into life;<br/>Forgiveness kissing man’s repentance<br/>Hath sealed them Husband and wife.<br/>',NULL,22577,5);
INSERT INTO stanza VALUES('NS441','5','God became man to make man God;<br/>The King became a countryman<br/>Through incarnation, human living<br/>The cross and resurrection’s plan;<br/>A country girl to be His queen<br/>Presented as His bride,<br/>Fully redeemed, regenerated<br/>Transformed and glorified.<br/>',NULL,22578,6);
INSERT INTO stanza VALUES('NS441','6','Christ and the church a perfect match<br/>And universal loving pair<br/>The Spirit and the bride in union<br/>One mingled life and living share;<br/>The Husband is the processed God<br/>The man the transformed wife<br/>To be the New Jerusalem<br/>Living a marriage life.<br/>',NULL,22579,7);
INSERT INTO stanza VALUES('NS442','1','In God’s economy Christ is unique;<br/>He holds the first place and centrality.<br/>All is in Him, through Him, and unto Him;<br/>He is all—the universality.<br/>',NULL,22580,1);
INSERT INTO stanza VALUES('NS442','chorus','Christ plus nothing,<br/>Christ plus nothing is everything;<br/>In God’s eternal economy<br/>Christ plus nothing equals everything.<br/>',NULL,22581,2);
INSERT INTO stanza VALUES('NS442','2','Within the Godhead the center is Christ,<br/>In Him the fullness is pleased thus to dwell;<br/>All that the Father is He doth express<br/>And of His Person the Spirit doth tell.<br/>',NULL,22582,3);
INSERT INTO stanza VALUES('NS442','3','The universe was created through Christ,<br/>In Him do all things cohere and subsist;<br/>Framed by His Word and upheld by His power,<br/>As the Firstborn in whom all things exist.<br/>',NULL,22583,4);
INSERT INTO stanza VALUES('NS442','4','Looking away from the prophets and law,<br/>Christ, God’s delight and beloved, we see;<br/>For all things testify concerning Him,<br/>Of all the shadows, the body is He.<br/>',NULL,22584,5);
INSERT INTO stanza VALUES('NS442','5','In the new man Christ is all and in all,<br/>In resurrection the Firstborn is He,<br/>All persons, matters, and things are crossed out,<br/>Christ alone is the constituency.<br/>',NULL,22585,6);
INSERT INTO stanza VALUES('NS442','6','The New Jerusalem will consummate<br/>With Christ, as Head, over all things to be <br/>The Lamb enthroned—its unique centerpiece<br/>Ruling and reigning for eternity.<br/>',NULL,22586,7);
INSERT INTO stanza VALUES('NS442','7','Christ as the element, sphere, means, and goal<br/>Must be our center, our focus, and aim;<br/>In God’s economy Christ must be all:<br/>The inward substance and the outward frame.<br/>',NULL,22587,8);
INSERT INTO stanza VALUES('NS442','8','Oh, may it be—Christ plus nothing in me;<br/>Neither my old man self-cultivating<br/>Nor substitute, nor addition to Thee<br/>But Christ as all and in all—everything.<br/>',NULL,22588,9);
INSERT INTO stanza VALUES('NS443','1','And He humbled me and let me go hungry<br/>And He fed me the manna,<br/>Which I had never known nor<br/>My fathers had ever known, so<br/>That He might make me know<br/>That man lives not by bread alone,<br/>Man lives not by bread alone,<br/>But that man<br/>Lives by everything that<br/>Proceeds out from the mouth<br/>Of Jehovah.<br/>',NULL,22589,1);
INSERT INTO stanza VALUES('NS444','1','But of Him you are in Christ Jesus,<br/>Who became wisdom to us from God:<br/>Both righteousness and sanctification<br/>And redemption,<br/>',NULL,22590,1);
INSERT INTO stanza VALUES('NS444','2','And the God of peace Himself<br/>Sanctify you wholly,<br/>And may your spirit and soul and body<br/>Be preserved complete,<br/>Without blame, at the coming<br/>Of our Lord Jesus Christ,<br/>Of our Lord Jesus Christ.<br/>',NULL,22591,2);
INSERT INTO stanza VALUES('NS445','1','Who, being the effulgence of His glory<br/>And the impress of His substance<br/>And upholding and bearing all things<br/>By the word of His power,<br/>Having made purification of sins,<br/>Sat down on the right hand,<br/>the right hand of<br/>The Majesty on high.<br/>',NULL,22592,1);
INSERT INTO stanza VALUES('NS446','1','This is My Son, the Beloved,<br/>In Whom I have found my delight.<br/>This is My Son, the Beloved,<br/>In Whom I have found my delight.<br/>Hear Him, hear Him!<br/>My Son, in Whom I’ve found My delight.<br/>Hear Him, hear Him!<br/>My Son, in Whom I’ve found my delight.<br/>',NULL,22593,1);
INSERT INTO stanza VALUES('NS447','1','I live and yet not I,<br/>For Christ He lives in me.<br/>The life I live in the flesh now<br/>Is Christ, just Christ, to be.<br/>',NULL,22594,1);
INSERT INTO stanza VALUES('NS447','chorus','O what a marvelous hope, Lord,<br/>To find myself in You,<br/>And in experience my boasting,<br/>To know You through and through.<br/>',NULL,22595,2);
INSERT INTO stanza VALUES('NS447','2','O what a wondrous existence,<br/>Of all which is most blessed.<br/>You see, Lord, I am now softened<br/>To take from You what’s best.<br/>',NULL,22596,3);
INSERT INTO stanza VALUES('NS447','chorus','It’s not my fervent resolve, Lord,<br/>Nor e’en my love untrue.<br/>It’s You in me Who is doing,<br/>What I for You couldn’t do.<br/>',NULL,22597,4);
INSERT INTO stanza VALUES('NS447','3','From every other attraction—<br/>Be faithful, break me free.<br/>Though smarting, Lord, from Love’s action,<br/>Each wound draws me to Thee.<br/>',NULL,22598,5);
INSERT INTO stanza VALUES('NS447','chorus','You see each end from beginning;<br/>Take me through each dark phase;<br/>As long, Lord, as love conforms me,<br/>Fits me to meet You that day.<br/>',NULL,22599,6);
INSERT INTO stanza VALUES('NS447','4','So here we are, dear Lord Jesus,<br/>And may Your precious hand,<br/>Accomplish all that You’ve purposed,<br/>All that You’ve for us planned.<br/>',NULL,22600,7);
INSERT INTO stanza VALUES('NS447','chorus','You are our one destination,<br/>You are our destiny.<br/>These days, just for our preparing,<br/>Will leave what in memory?<br/>',NULL,22601,8);
INSERT INTO stanza VALUES('NS447','5','In us, Lord, gain all You’re after,<br/>In us, Lord, gain Your Bride.<br/>In us, be so very blessed.<br/>In us, be satisfied.<br/>',NULL,22602,9);
INSERT INTO stanza VALUES('NS447','chorus','As we, Lord, become Your fullness<br/>And You in us reside,<br/>Keep us, dear Lord, in Your love-bonds,<br/>As mutually we abide.<br/>',NULL,22603,10);
INSERT INTO stanza VALUES('NS448','1','I have an excuse to praise my God and Father,<br/>I have an excuse to give thanks to my Lord.<br/>I have an excuse to give glory to my God,<br/>Because I know that He is and He’s on the throne.<br/>',NULL,22604,1);
INSERT INTO stanza VALUES('NS448','chorus','Praise the Lord! Praise the Lord!<br/>I will bless the God and Father<br/>Praise the Lord! Praise the Lord!<br/>Of my Lord Jesus Christ<br/>Praise the Lord! Praise the Lord!<br/>I will praise while I have breath<br/>Because I know that He is and I have breath now.<br/>',NULL,22605,2);
INSERT INTO stanza VALUES('NS448','2','I have an excuse to praise my God and Father,<br/>I have an excuse to give thanks to my Lord.<br/>I have an excuse to give glory to my God,<br/>Because I know that He is and He’s on the throne.<br/>',NULL,22606,3);
INSERT INTO stanza VALUES('NS448','chorus','Hallelujah!<br/>Praise You God and Father!<br/>Hallelujah!<br/>Praise You Lord Jesus Christ!<br/>Hallelujah!<br/>I will praise while I have breath<br/>Because I know that He is and He loves me so.<br/>',NULL,22607,4);
INSERT INTO stanza VALUES('NS449','1','The measure of our value,<br/>And preciousness to God,<br/>Is not our work and service,<br/>But nearness to the Lord.<br/>Though outer court is needed,<br/>We would not there abide;<br/>We’d be His faithful servants,<br/>And His dear, loving Bride.<br/>',NULL,22608,1);
INSERT INTO stanza VALUES('NS449','2','The priesthood of the gospel<br/>Brings sinners to His grace;<br/>Yet in our priestly service,<br/>Are we before His face?<br/>The Father still is seeking<br/>True worship in His sight—<br/>The “fat” and “blood” of Jesus<br/>In Whom is His delight.<br/>',NULL,22609,2);
INSERT INTO stanza VALUES('NS449','3','“The priests and sons of Zadok<br/>Shall draw near unto Me<br/>And e’en before my table<br/>Within the sanctuary<br/>To minister unto Me<br/>The fat and blood to bring”—<br/>Christ’s precious work and person<br/>God’s longed-for offering.<br/>',NULL,22610,3);
INSERT INTO stanza VALUES('NS449','4','God’s people at Mount Horeb<br/>Upon three levels trod,<br/>And thus had different levels<br/>Of fellowship with God.<br/>The nearer to His presence,<br/>The more their view could be,<br/>But two stood right before Him,<br/>His glory full to see.<br/>',NULL,22611,4);
INSERT INTO stanza VALUES('NS449','5','Just as upon Mount Hermon<br/>Where Jesus brought the three—<br/>Where His transfiguration<br/>Was unveiled privately;—<br/>Our height of revelation<br/>Will differ in degree;<br/>Lord, draw us ever nearer,<br/>More of Thyself to see.<br/>',NULL,22612,5);
INSERT INTO stanza VALUES('NS449','6','One in the House of Feasting<br/>Life’s vict’ry testified;<br/>One, busy with much service,<br/>The outward needs supplied.<br/>But one more thing was needed,<br/>To gain the better part:<br/>A love with revelation<br/>To satisfy His heart.<br/>',NULL,22613,6);
INSERT INTO stanza VALUES('NS449','7','Before the feet of Jesus,<br/>Attending every word,<br/>A woman bearing ointment<br/>Cared only for her Lord;<br/>His heart’s desire and preference<br/>To her alone revealed,<br/>Her flask was “wasted” on Him,<br/>The house with fragrance filled.<br/>',NULL,22614,7);
INSERT INTO stanza VALUES('NS449','8','When we give Him the first place<br/>And first love following,<br/>Then first works manifest will<br/>His glory’s fragrance bring.<br/>The house thus filled with fragrance<br/>Draws seeking sinners close;<br/>Such ministry to God is<br/>Our service to His house.<br/>',NULL,22615,8);
INSERT INTO stanza VALUES('NS450','1','Oh, how I love Thee dearest Lord;<br/>On Thee alone I lean.<br/>Though rapturous with ecstasy<br/>Or tears unceasing stream;<br/>When all my world comes crashing down<br/>And nothing falls in place,<br/>Uphold me with Thy love and strength<br/>To cling to Thine embrace.<br/>',NULL,22616,1);
INSERT INTO stanza VALUES('NS450','2','Thy person, Lord, alone can bring<br/>My jaded heart to cheer;<br/>Thy smile gladdens my heart strings<br/>Whene’er Thou dost appear.<br/>Thus gloom becomes triumphant song<br/>And darkness turns to light,<br/>My valley’s shades to inundate<br/>With beams of sweet delight.<br/>',NULL,22617,2);
INSERT INTO stanza VALUES('NS450','3','Thy presence meaneth everything;<br/>Thou art my secret, Lord.<br/>I welcome Thee into my boat; <br/>True rest Thou dost afford.<br/>Though bitterness surround my soul,<br/>Thy sweetness I can taste,<br/>For in life’s storms in Thee I find<br/>The eye wherein I’m graced.<br/>',NULL,22618,3);
INSERT INTO stanza VALUES('NS450','4','Thy visitation, gracious, sweet<br/>In trials comforts me.<br/>In tribulation’s form to bring<br/>Thine all-sufficiency; <br/>While journeying along life’s stream,<br/>Should I, by boulders, be fazed?<br/>For thornless grace I would not seek,<br/>But water’s level raised.<br/>',NULL,22619,4);
INSERT INTO stanza VALUES('NS450','5','When in the index of Thine eyes,<br/>My heart’s joy is maintained;<br/>With Thee alone I’m occupied,<br/>And by Thy love constrained.<br/>There’s naught on earth that can frustrate<br/>The man enjoying Thee;<br/>Now all else from my vision fades;<br/>Thou Lord, alone, I see.<br/>',NULL,22620,5);
INSERT INTO stanza VALUES('NS451','1','Lord, deeper make Thy home in me<br/>’Til ev’ry room belong to Thee,<br/>That Thou might fully make me Thee<br/>And so full rest Thou have in me.<br/>',NULL,22621,1);
INSERT INTO stanza VALUES('NS451','2','So also deeper into Thee<br/>I’d make my home, my rest in Thee;<br/>A pillar in Thy temple be<br/>And stay in Thee eternally.<br/>',NULL,22622,2);
INSERT INTO stanza VALUES('NS451','3','Thy precious blood was shed that we<br/>Could closer, closer, closest be;<br/>In resurrection brought to Thee<br/>That we might be as one as Thee.<br/>',NULL,22623,3);
INSERT INTO stanza VALUES('NS451','4','My lovely Lord, my dear Bridegroom,<br/>In trust I open ev’ry room;<br/>This mind, emotion, will be Thine;<br/>When Thou hast rest, that rest is mine.<br/>',NULL,22624,4);
INSERT INTO stanza VALUES('NS451','5','Oh mystery of mysteries—<br/>Lord, Thou in me and I in Thee!<br/>The church, Thy temple—we to Thee,<br/>And Thee our tabernacle be.<br/>',NULL,22625,5);
INSERT INTO stanza VALUES('NS451','6','Lord, make Thy home more ev’ry day,<br/>’Til one with Thee in ev’ry way,<br/>’Til on me write Thy holy name,<br/>’Til on me write Thy city’s name.<br/>',NULL,22626,6);
INSERT INTO stanza VALUES('NS451','7','Lord, Thou art me and I am Thee,<br/>As lovers coinhering, we;<br/>Soon then shall come eternity<br/>When God and man dwell mutually.<br/>',NULL,22627,7);
INSERT INTO stanza VALUES('NS452','1','Beloved we are children of God,<br/>And through this life we onward trod;<br/>When He is seen on earth again<br/>We will be seen as only Him,<br/>Even as He is.<br/>',NULL,22628,1);
INSERT INTO stanza VALUES('NS452','chorus','Even as He is,<br/>Even as He is,<br/>Even as He is we will be;<br/>Even as He is we will be.<br/>',NULL,22629,2);
INSERT INTO stanza VALUES('NS452','2','He who has this hope in Him<br/>Is purified in how he lives;<br/>By living Christ as righteousness,<br/>He lives a life in blessedness,<br/>Even as He is pure.<br/>',NULL,22630,3);
INSERT INTO stanza VALUES('NS452','3','Little children don’t be led astray,<br/>We will see Him on judgment day;<br/>He who is righteous and lives in light,<br/>Will live Him out as He is right,<br/>Even as He is right.<br/>',NULL,22631,4);
INSERT INTO stanza VALUES('NS452','4','In this we know that we are Him,<br/>And while in Him we cannot sin;<br/>We live in Him, live side by side,<br/>We walk in Him, with Him abide,<br/>Even as He walked.<br/>',NULL,22632,5);
INSERT INTO stanza VALUES('NS453','1','I have set before you life and death, blessing and curse;<br/>Therefore choose life that you and your seed may live,<br/>I have set before you life and death, blessing and curse;<br/>Therefore choose life that you and your seed may live,<br/>',NULL,22633,1);
INSERT INTO stanza VALUES('NS453','2','In loving Jehovah your God by listening to His voice<br/>and holding fast to Him; for He is your life;<br/>In loving Jehovah your God by listening to His voice<br/>and holding fast to Him; for He is your life<br/>and the length of your days.<br/>',NULL,22634,2);
INSERT INTO stanza VALUES('NS454','1','Oh, conquer me dear Lord,<br/>And never let me win.<br/>May Thou defeat me all the time<br/>Till I’m subdued within.<br/>',NULL,22635,1);
INSERT INTO stanza VALUES('NS454','chorus','Conquer me dear Lord,<br/>Never let me win;<br/>Oh, defeat me all the time<br/>Till I’m subdued within.<br/>',NULL,22636,2);
INSERT INTO stanza VALUES('NS454','2','I, once Thine enemy,<br/>Was captured, Lord, by Thee;<br/>Yet Thee I hold, rebelliously,<br/>As captive unto me.<br/>',NULL,22637,3);
INSERT INTO stanza VALUES('NS454','3','Defeated, Lord, by Thee,<br/>Thy prisoner I’d be.<br/>Yet when Thou would’st make home in me,<br/>I oft imprison Thee.<br/>',NULL,22638,4);
INSERT INTO stanza VALUES('NS454','4','Though conquered Lord, by Thee,<br/>My old man liveth still.<br/>O, come and be my person, Lord,<br/>In mind, emotion, will.<br/>',NULL,22639,5);
INSERT INTO stanza VALUES('NS454','5','Make me a captive, Lord<br/>And then I shall be free;<br/>Break through, have Thine own way in me<br/>For Thine economy.<br/>',NULL,22640,6);
INSERT INTO stanza VALUES('NS455','1','Can we forget Thy coming,<br/>The dawning of the day?<br/>Two days have passed before us;<br/>Oh, third day don’t delay!<br/>How long wilt Thou yet tarry?<br/>How long Thy coming stay?<br/>We long for Thine appearing!<br/>Wouldst Thou e’en come today?<br/>',NULL,22641,1);
INSERT INTO stanza VALUES('NS455','chorus','Come quickly, Oh, come quickly!<br/>Make haste to come again!<br/>We long to be e’er with Thee;<br/>Come quickly, Lord! Amen.<br/>',NULL,22642,2);
INSERT INTO stanza VALUES('NS455','2','Now in night’s darkest hour<br/>The hope of glory shines,<br/>Thy Word a lamp in darkness<br/>Prophetically reminds;<br/>The sureness of Thy coming<br/>As dawn’s prevailing ray<br/>Shines brighter, ever brighter,<br/>Unto the perfect day.<br/>',NULL,22643,3);
INSERT INTO stanza VALUES('NS455','3','The echo of the ages<br/>Doth summon Thy return,<br/>Reflecting Thine own promise<br/>From countless hearts that yearn;<br/>Oh, that Thou wouldst give heed, Lord,<br/>To our most fervent plea:<br/>Make haste with Thine appearing<br/> And take us up to Thee!<br/>',NULL,22644,4);
INSERT INTO stanza VALUES('NS455','4','With eyes on the horizon,<br/>Eastward our hearts incline,<br/>Still going forth to meet Thee<br/>Till daybreak’s glimmer shines<br/>Rise, Morning Star, within us<br/>Till to the full degree<br/>We’d be with Thee forever<br/>In rapturous ecstasy.<br/>',NULL,22645,5);
INSERT INTO stanza VALUES('NS456','1','Lord Jesus Christ my sole desire,<br/>My heart is fixed, alone, on Thee.<br/>Among ten thousand Thou art peerless;<br/>Chiefest of all art Thou to me.<br/>',NULL,22646,1);
INSERT INTO stanza VALUES('NS456','2','Thy matchlessness and worth surpassing,<br/>Transcend all else exceedingly.<br/>Oh, how supreme and prepossessing,<br/>Is Thine unrivaled love to me.<br/>',NULL,22647,2);
INSERT INTO stanza VALUES('NS456','3','My life-long quest is just to know Thee<br/>Till more and more subjectively,<br/>I would arrive at the full knowledge,<br/>Of all the excellence of Thee.<br/>',NULL,22648,3);
INSERT INTO stanza VALUES('NS456','4','Since the first day that I beheld Thee<br/>I’ve longed to know Thee ever more<br/>My heart doth love Thee most supremely<br/>Thy preciousness, Lord, I adore.<br/>',NULL,22649,4);
INSERT INTO stanza VALUES('NS456','5','Lost in Thee, Lord, I gaze intently<br/>Drawn from all else to look away,<br/>Thou, Magnet of my soul, hast charmed me<br/>Far more today than yesterday.<br/>',NULL,22650,5);
INSERT INTO stanza VALUES('NS456','6','I’m captivated by Thy beauty,<br/>Incomp’rable Thou art to me.<br/>Counting all things as loss and refuse,<br/>I’d pay the price of gaining Thee.<br/>',NULL,22651,6);
INSERT INTO stanza VALUES('NS456','7','My daily goal and aim—to win Thee,<br/>For this I press on desperately,<br/>Forgetting all that is behind me<br/>And stretching forward earnestly.<br/>',NULL,22652,7);
INSERT INTO stanza VALUES('NS456','8','Toward this goal I’m pressing onward<br/>That I may lay hold of the Prize,<br/>Gain me in full that I may gain Thee<br/>Thy peerlessness to realize.<br/>',NULL,22653,8);
INSERT INTO stanza VALUES('NS456','9','Not I alone; we in the Body<br/>Strive to delve into and explore<br/>The rich dimensions of Thy vastness,<br/>Thine endless wealth and treasure store.<br/>',NULL,22654,9);
INSERT INTO stanza VALUES('NS456','10','When Thou, our Christ, so all-inclusive,<br/>We apprehend, know, and possess<br/>Thine attributes divine, our virtues<br/>Will all Thy fullness thus express.<br/>',NULL,22655,10);
INSERT INTO stanza VALUES('NS456','11','Thine excellency may we know, Lord,<br/>That Thou, Thy home in us, may make<br/>Till we arrive at Thy full knowledge<br/>And, of Thy riches full, partake.<br/>',NULL,22656,11);
INSERT INTO stanza VALUES('NS457','1','Lord, grant us a revival<br/>In Thy recovery,<br/>The ultimate and greatest<br/>E’er seen in history.<br/>Two days have passed before us<br/>Come third, without delay!<br/>Prepare Thy bride made ready<br/>Bring in Thy wedding day.<br/>',NULL,22657,1);
INSERT INTO stanza VALUES('NS457','chorus','Lord, grant us a revival<br/>In Thy recovery;<br/>Raise up a generation<br/>To end this age for Thee.<br/>',NULL,22658,2);
INSERT INTO stanza VALUES('NS457','2','Raise up a generation<br/>In Thy recovery<br/>To see the high peak vision,<br/>And live accordingly;<br/>The vital groups in function<br/>Thine instrument to be,<br/>To end this dispensation<br/>And turn the age for Thee.<br/>',NULL,22659,3);
INSERT INTO stanza VALUES('NS457','3','Bring forth a corporate model<br/>As Zion’s peak today;<br/>Produce Thine overcomers<br/>To take Thine ordained way:<br/>Train and perfect this remnant<br/>To consummate this age,<br/>Prepare Thy corporate army<br/>To fight, Thy warfare wage.<br/>',NULL,22660,4);
INSERT INTO stanza VALUES('NS457','4','Build up Thy corporate Body<br/>In each locality;<br/>Prepare Thy Bride made ready,<br/>And host to fight for Thee;<br/>Raise up Thy corporate beachheads<br/>And stepping-stones in them<br/>To usher in Thy kingdom;<br/>The New Jerusalem.<br/>',NULL,22661,5);
INSERT INTO stanza VALUES('NS458','1','Dead in sin and void of purpose,<br/>In pursuit of vanity;<br/>Occupied with life’s vainglory,<br/>Groped I for my life’s true meaning<br/>In the world and without Thee,<br/>In the world and without Thee.<br/>',NULL,22662,1);
INSERT INTO stanza VALUES('NS458','2','Then one day I heard the gospel,<br/>I believed and called on Thee;<br/>Thou as life came in to fill me,<br/>Making life so full of meaning<br/>As the Son revealed in me,<br/>As the Son revealed in me.<br/>',NULL,22663,2);
INSERT INTO stanza VALUES('NS458','3','All-inclusive was the transfer,<br/>Baptized—four-fold—into Thee,<br/>Into Thy death, Body, and Person,<br/>Thus to live and walk in newness;<br/>One in life and living with Thee,<br/>One in life and living with Thee.<br/>',NULL,22664,3);
INSERT INTO stanza VALUES('NS458','4','Captivated by Thy beauty,<br/>I left all to follow Thee;<br/>All my hopes and dreams forsaking,<br/>Counting all as loss and refuse;<br/>Losing sight of all but Thee,<br/>Losing sight of all but Thee.<br/>',NULL,22665,4);
INSERT INTO stanza VALUES('NS458','5','Strengthening me with Thy power,<br/>Through Thy Spirit inwardly;<br/>From my spirit Thou art spreading,<br/>All my soul Thou art transforming;<br/>Thou art making home in me,<br/>Thou art making home in me.<br/>',NULL,22666,5);
INSERT INTO stanza VALUES('NS458','6','I’d grow up in Thee in all things<br/>Till I am the same as Thee;<br/>Till through me, Thou, once more living,<br/>And my human virtues filling;<br/>Art thus fully formed in me,<br/>Art thus fully formed in me.<br/>',NULL,22667,6);
INSERT INTO stanza VALUES('NS458','7','Using all things, persons, and matters<br/>Thou art disciplining me<br/>Till by outer man consuming,<br/>And my inner-man renewing;<br/>’Tis no longer I but Thee<br/>’Tis no longer I but Thee.<br/>',NULL,22668,7);
INSERT INTO stanza VALUES('NS458','8','Not alone but with Thy members<br/>Thou art sweetly placing me;<br/>Fitting me into Thy building,<br/>Blending out all self distinctions,<br/>That Thy church would builded be,<br/>That Thy church would builded be.<br/>',NULL,22669,8);
INSERT INTO stanza VALUES('NS458','9','Till that day I stand before Thee;<br/>Render my account to Thee,<br/>Grant me grace that I’d live daily<br/>One with Thee in Thine appearing;<br/>Thou, my glorious hope, to be,<br/>Thou, my glorious hope, to be.<br/>',NULL,22670,9);
INSERT INTO stanza VALUES('NS459','1','Deuteronomy 30:19,<br/>Deuteronomy 30:19:<br/>I call heaven and earth<br/>To witness against you today:<br/>That I have set before you life and death,<br/>Blessing and curse;<br/>Therefore choose life,<br/>Therefore choose life,<br/>That you and your seed,<br/>You and your seed may live,<br/>Choose life that you and your seed may live.<br/>',NULL,22671,1);
INSERT INTO stanza VALUES('NS460','1','Thou, Triune God, eternally<br/>Distinctly three, insep’rably one;<br/>A realm divine and mystical,<br/>Art formed as an incorporation.<br/>',NULL,22672,1);
INSERT INTO stanza VALUES('NS460','2','By Thine indwelling mutually<br/>Thou doth exist essentially;<br/>Thy will to bring humanity<br/>Into this sphere economically.<br/>',NULL,22673,2);
INSERT INTO stanza VALUES('NS460','3','Through incarnation in the Son<br/>This realm was first seen in the flesh;<br/>Within Christ’s body physical<br/>The Godhead’s fullness manifest.<br/>',NULL,22674,3);
INSERT INTO stanza VALUES('NS460','4','His human life did manifest<br/>Coordination beauteous:<br/>One acted, Three did operate<br/>In harmony so marvelous.<br/>',NULL,22675,4);
INSERT INTO stanza VALUES('NS460','5','Through death and resurrection was<br/>This life divine in full released<br/>To form Thy Body mystical,<br/>This realm divine to thus increase.<br/>',NULL,22676,5);
INSERT INTO stanza VALUES('NS460','6','This habitation’s Thine abode,<br/>Thy Body mystical, divine,<br/>Enlargement of our Father’s house,<br/>The Spirit’s child, Son’s spreading vine.<br/>',NULL,22677,6);
INSERT INTO stanza VALUES('NS460','7','Thy final form the Spirit is,<br/>The realization of the Son;<br/>With Thee we’re blent, divine-human<br/>Incorporation to become.<br/>',NULL,22678,7);
INSERT INTO stanza VALUES('NS460','8','Thy Spirit into ours has come,<br/>One mingled spirit formed, become<br/>The Body, Father, Spirit, Son—<br/>An entity that’s Four yet One.<br/>',NULL,22679,8);
INSERT INTO stanza VALUES('NS460','9','By Thine own glory, life, and word<br/>Here we are all thus one in Thee;<br/>Such oneness doth reflect Thine own,<br/>The oneness seen among the Three.<br/>',NULL,22680,9);
INSERT INTO stanza VALUES('NS460','10','God’s love, Christ’s grace, the fellowship<br/>Of Holy Spirit, reaching man<br/>As living water, issue from<br/>The throne of God and of the Lamb.<br/>',NULL,22681,10);
INSERT INTO stanza VALUES('NS460','11','This fellowship of life divine<br/>Our Father and His Son have shared;<br/>We’re called into this fellowship,<br/>Which the apostles have declared.<br/>',NULL,22682,11);
INSERT INTO stanza VALUES('NS460','12','The Spirit with our spirit is<br/>The factor for us to be one,<br/>The key to live the Christian life,<br/>And secret of our salvation.<br/>',NULL,22683,12);
INSERT INTO stanza VALUES('NS460','13','The ministry of Christ in full<br/>Within this realm is carried out,<br/>And God’s complete salvation too<br/>Within this sphere is brought about.<br/>',NULL,22684,13);
INSERT INTO stanza VALUES('NS460','14','In all their living and their work<br/>This mingled life th’ apostles sought,<br/>The Triune God to manifest<br/>In character and service wrought.<br/>',NULL,22685,14);
INSERT INTO stanza VALUES('NS460','15','In all our living and our work<br/>So we must also do the same,<br/>In daily life, we would make this<br/>Our top priority and aim.<br/>',NULL,22686,15);
INSERT INTO stanza VALUES('NS460','16','As therefore we have thus received,<br/>So in all things we walk in Thee;<br/>Thine all-inclusiveness to grasp,<br/>We call and pray unceasingly.<br/>',NULL,22687,16);
INSERT INTO stanza VALUES('NS460','17','We live in Thee and Thou with us<br/>In two-way traffic mutually:<br/>In Thee we live, exist, and move,<br/>Abide uninterruptedly.<br/>',NULL,22688,17);
INSERT INTO stanza VALUES('NS460','18','Thy name which Thou hast given us<br/>Denotes Thy Person as our sphere,<br/>Sum total of Thy Being, Lord,<br/>Into which we’ve been gathered here.<br/>',NULL,22689,18);
INSERT INTO stanza VALUES('NS460','19','Thou art in us Thy kingdom too;<br/>With joy and peace and righteousness.<br/>Eternal life’s totality,<br/>The church life, sphere in which we’re blessed.<br/>',NULL,22690,19);
INSERT INTO stanza VALUES('NS460','20','The New Jerusalem will be<br/>This realm’s domain perpetually;<br/>Thou in the Father, we in Thee,<br/>And Thou in us eternally.<br/>',NULL,22691,20);
INSERT INTO stanza VALUES('NS460','21','O, may we see, experience<br/>The realm of Thine economy<br/>In all the details of our life<br/>To practice living one with Thee.<br/>',NULL,22692,21);
INSERT INTO stanza VALUES('NS461','1','Let him kiss me with the kisses of his mouth!<br/>For your love is better than wine.<br/>Your name is like ointment poured forth;<br/>Therefore the virgins love you.<br/>',NULL,22693,1);
INSERT INTO stanza VALUES('NS461','2','The king brought me, brought me into his chambers—<br/>We’ll be glad and joy in you;<br/>We’ll extol your love much more than wine.<br/>Draw me; we will run after you.<br/>',NULL,22694,2);
INSERT INTO stanza VALUES('NS461','3','Tell me, you whom my soul loves,<br/>Where do you feed your flock?<br/>Where do they lie down at noon?<br/>Where do you pasture your flock?<br/>',NULL,22695,3);
INSERT INTO stanza VALUES('NS461','4','If you yourself do not know,<br/>Go by the flock’s footsteps,<br/>Feed your young, O fairest one,<br/>By the shepherds’ tents.<br/>',NULL,22696,4);
INSERT INTO stanza VALUES('NS462','1','Lo, the Spirit is now working!<br/>To convict all men of sin,<br/>Christ became the unique sinner,<br/>Men, as prodigals, to win.<br/>',NULL,22697,1);
INSERT INTO stanza VALUES('NS462','chorus','Oh, the Spirit is now working!<br/>Sanctifying, sweeping, searching;<br/>Men, convicting and inspiring,<br/>To salvation He doth bring.<br/>',NULL,22698,2);
INSERT INTO stanza VALUES('NS462','2','Lo, the Spirit is now working!<br/>To convict of righteousness,<br/>For which Christ hath resurrected;<br/>All the nations thus to bless.<br/>',NULL,22699,3);
INSERT INTO stanza VALUES('NS462','3','Lo, the Spirit is now working!<br/>Satan’s judgment to proclaim;<br/>Thus releasing from his bondage<br/>All who would not share his shame.<br/>',NULL,22700,4);
INSERT INTO stanza VALUES('NS462','4','Lo, the Spirit is now working!<br/>To proclaim to every man<br/>Sin, and righteousness, and judgment;<br/>God’s economy and plan.<br/>',NULL,22701,5);
INSERT INTO stanza VALUES('NS463','1','Lord, Thou hast won my heart;<br/>With Thee I love to be;<br/>There’s not one thing, save what Thou art,<br/>My heart desires to see.<br/>',NULL,22702,1);
INSERT INTO stanza VALUES('NS463','2','What else could I desire<br/>In heaven or on earth?<br/>To this alone I would aspire:<br/>To know Thy peerless worth.<br/>',NULL,22703,2);
INSERT INTO stanza VALUES('NS463','3','Thou art my heart’s delight,<br/>The Sweetest of the sweet;<br/>All else becomes devoid of taste<br/>When once compared to Thee.<br/>',NULL,22704,3);
INSERT INTO stanza VALUES('NS463','4','Lord, on account of Thee<br/>All other loves grow pale;<br/>Chiefest among ten thousand, Thou<br/>Dost e’er o’er all prevail.<br/>',NULL,22705,4);
INSERT INTO stanza VALUES('NS463','5','Enamored of Thyself<br/>I forfeit all to Thee,<br/>For ’tis when I have nothing that<br/>I’ve everything in Thee.<br/>',NULL,22706,5);
INSERT INTO stanza VALUES('NS464','1','We must redeem the time!<br/>Let it not slip away,<br/>For we will stand before the Lord<br/>That coming day.<br/>Redeem the time!<br/>Seize every opportunity;<br/>Redeem the time!<br/>',NULL,22707,1);
INSERT INTO stanza VALUES('NS464','2','We must redeem the time!<br/>The Lord is drawing nigh.<br/>And just around the bend<br/>We’ll hear the midnight cry.<br/>Redeem the time!<br/>Seize every opportunity;<br/>Redeem the time!<br/>',NULL,22708,2);
INSERT INTO stanza VALUES('NS464','3','We must redeem the time!<br/>Each opportunity<br/>Will come and pass<br/>Ne’er to return eternally.<br/>Redeem the time!<br/>Seize every opportunity;<br/>Redeem the time!<br/>',NULL,22709,3);
INSERT INTO stanza VALUES('NS464','4','We must redeem the time!<br/>Buy back the time we’ve lost.<br/>Forsaking all to pay the price<br/>Is worth the cost.<br/>Redeem the time!<br/>Seize every opportunity;<br/>Redeem the time!<br/>',NULL,22710,4);
INSERT INTO stanza VALUES('NS464','5','We must redeem the time!<br/>We have not time to spare;<br/>Each moment He hath measured<br/>For us to prepare.<br/>Redeem the time!<br/>Seize every opportunity;<br/>Redeem the time!<br/>',NULL,22711,5);
INSERT INTO stanza VALUES('NS465','1','The Father God, the deepest spring,<br/>The rich eternal source,<br/>Emerges as the living spring,<br/>In Jesus Christ, the course;<br/>The Spirit is the flowing spring,<br/>A springing up in us;<br/>The river of life, the triune spring,<br/>Profoundly glorious.<br/>',NULL,22712,1);
INSERT INTO stanza VALUES('NS465','chorus','This river is huge, this river is deep,<br/>This river is wide,<br/>It’s flowing out from the smitten rock,<br/>The Savior’s side;<br/>This river is clear, this river is pure,<br/>This river is bright,<br/>The Triune God, the glorified Christ,<br/>Resurrection life.<br/>',NULL,22713,2);
INSERT INTO stanza VALUES('NS465','2','Uniquely one, this flowing grace,<br/>The living God divine<br/>From Eden flows to every place,<br/>And reaches all mankind;<br/>By drinking of the stream of life,<br/>The saints become His bride,<br/>His counterpart, increase of Christ,<br/>The issue from His side.<br/>',NULL,22714,3);
INSERT INTO stanza VALUES('NS465','3','This river of God is flowing free,<br/>A priceless living spring,<br/>Wherever it flows conveys the tree,<br/>Brings life to everything;<br/>This turbulent river is full and great,<br/>And man regenerates;<br/>This hydropower permeates,<br/>Transforms and saturates.<br/>',NULL,22715,4);
INSERT INTO stanza VALUES('NS465','4','These rapids of life will not relent<br/>But swiftly reach the end,<br/>The Triune God mingling with men,<br/>The New Jerusalem;<br/>The sweetness of this river of life,<br/>The all-inclusive Christ,<br/>Will consummate the sanctified<br/>Unto eternal life.<br/>',NULL,22716,5);
INSERT INTO stanza VALUES('NS466','1','I was drawn to the world and it’s sin,<br/>I was seeking but empty within;<br/>Then this man crossed my path,<br/>And instead of God’s wrath<br/>He loved me and opened God’s heart!<br/>Jesus loves me and waters my heart.<br/>',NULL,22717,1);
INSERT INTO stanza VALUES('NS466','chorus','He drew me with cords of a man,<br/>With bands of love;<br/>Christ’s coming His living, His dying,<br/>His rising far above,<br/>Descending... like a dove;<br/>Reaching me, even me,<br/>With God’s love.<br/>',NULL,22718,2);
INSERT INTO stanza VALUES('NS466','2','I was seeking the world and it’s things,<br/>I was wealthy and yet could not see<br/>It was Christ I desired,<br/>Of the world I was tired,<br/>He loved me and came to my house!<br/>Jesus loves me and saves all my house!<br/>',NULL,22719,3);
INSERT INTO stanza VALUES('NS466','3','I was happy with friends, all my mates,<br/>With my music, wild parties and dates;<br/>Yet when Christ came to call,<br/>I have gladly left all!<br/>He loved me and He gave His all!<br/>Jesus loves me, I answer His call!<br/>',NULL,22720,4);
INSERT INTO stanza VALUES('NS467','1','But for me, I will wait on Jehovah;<br/>I will look for the God of my strength;<br/>In the darkness Jehovah will shine like a light;<br/>Let my enemies no more rejoice.<br/>For I fall, but then I will rise up;<br/>Praise the Lord, Who’s the strength of my heart;<br/>So for me, I will wait on the Lord Jesus Christ;<br/>And in Christ I will rise up again.<br/>',NULL,22721,1);
INSERT INTO stanza VALUES('NS468','1','Lord, in that coming day<br/>When all will bow the knee,<br/>’Twill be a commonplace display<br/>To waste one’s all on Thee.<br/>',NULL,22722,1);
INSERT INTO stanza VALUES('NS468','2','For Thee, Lord, on that day<br/>Ten thousand hearts would break,<br/>And if there were ten thousand worlds,<br/>These all, men would forsake.<br/>',NULL,22723,2);
INSERT INTO stanza VALUES('NS468','3','But now, while yet ’tis rare,<br/>My being won’t delay;<br/>Inspired by Thy love, could I,<br/>Thy noble tribute stay?<br/>',NULL,22724,3);
INSERT INTO stanza VALUES('NS468','4','My all I gladly give<br/>In love’s response to Thee,<br/>For how can I withhold my all<br/>When Thou gav’st all for me?<br/>',NULL,22725,4);
INSERT INTO stanza VALUES('NS468','5','Time’s window soon shall close;<br/>Now, while ’tis open still,<br/>This golden moment I’d redeem,<br/>Thy house with fragrance fill.<br/>',NULL,22726,5);
INSERT INTO stanza VALUES('NS468','6','The moments fly apace;<br/>Lord, Thou art coming soon!<br/>Can I delay, and fail to grasp<br/>This moment opportune?<br/>',NULL,22727,6);
INSERT INTO stanza VALUES('NS468','7','While there is still today<br/>(Beyond, no guarantee),<br/>Seizing this opportunity,<br/>I waste myself on Thee.<br/>',NULL,22728,7);
INSERT INTO stanza VALUES('NS468','8','That woman’s noble deed<br/>Was for Thy going wrought;<br/>In view of Thy return, I too<br/>Would offer as I ought.<br/>',NULL,22729,8);
INSERT INTO stanza VALUES('NS468','9','Two resurrections tell<br/>The foolish from the wise;<br/>Some would “beforehand” pay the price<br/>And lukewarmness despise.<br/>',NULL,22730,9);
INSERT INTO stanza VALUES('NS468','10','I dare not passive be<br/>But fully consecrate<br/>“Beforehand”, lest I miss my chance,<br/>And risk arriving late.<br/>',NULL,22731,10);
INSERT INTO stanza VALUES('NS468','11','There is but one regret<br/>Both hell and heaven hold—<br/>The loss of opportunity<br/>Eternity unfolds.<br/>',NULL,22732,11);
INSERT INTO stanza VALUES('NS468','12','Performing love’s sweet task,<br/>While time doth still permit,<br/>I break mine alabaster flask<br/>And Thine own love requit.<br/>',NULL,22733,12);
INSERT INTO stanza VALUES('NS468','13','May this be, in that day<br/>When I Thy coming hail<br/>(E’en if I sleep and wait for Thee),<br/>Our love’s memorial.<br/>',NULL,22734,13);
INSERT INTO stanza VALUES('NS469','1','One thing every heart desireth<br/>As it probes in vanity,<br/>Groping for its life’s true meaning,<br/>Longing for reality.<br/>',NULL,22735,1);
INSERT INTO stanza VALUES('NS469','2','Hid in every aspiration,<br/>In whate’er man doth contrive,<br/>Is the longing for fulfillment;<br/>For this man doth ever strive.<br/>',NULL,22736,2);
INSERT INTO stanza VALUES('NS469','3','For with nothing here to live for,<br/>How long could man be sustained?<br/>Thus within the old creation<br/>Man’s existence is maintained.<br/>',NULL,22737,3);
INSERT INTO stanza VALUES('NS469','4','For this, old creation’s needed:<br/>It’s the bridge of space and time,<br/>Till God brings forth new creation,<br/>His eternal realm sublime.<br/>',NULL,22738,4);
INSERT INTO stanza VALUES('NS469','5','This implanted sense of purpose<br/>Sown within the heart of man;<br/>Working throughout all the ages,<br/>Is for God’s eternal plan.<br/>',NULL,22739,5);
INSERT INTO stanza VALUES('NS469','6','Deep in man’s a God-shaped vacuum,<br/>Something only God can fill,<br/>There’s a human spirit longing<br/>To know God’s eternal will.<br/>',NULL,22740,6);
INSERT INTO stanza VALUES('NS469','7','All things are but temporary;<br/>Vanity of vanities<br/>But th’eternal life assuageth<br/>Thirsty sinners who believe.<br/>',NULL,22741,7);
INSERT INTO stanza VALUES('NS469','8','Though the nations think they’re seeking<br/>Joy, peace, love, security,<br/>Christ alone can fill their longing,<br/>As the one reality.<br/>',NULL,22742,8);
INSERT INTO stanza VALUES('NS470','1','We must ever preach the gospel,<br/>Holding forth the word of life.<br/>We must never shirk our duty;<br/>Saving man from sin and strife.<br/>',NULL,22743,1);
INSERT INTO stanza VALUES('NS470','chorus','Fellowship unto the gospel<br/>For the increase and the spread;<br/>In the vital groups empowered,<br/>Into victory we’ll be led.<br/>',NULL,22744,2);
INSERT INTO stanza VALUES('NS470','2','We must ever preach the gospel,<br/>Thus our friends and neighbors gain;<br/>House to house with vital partners,<br/>That our new ones will remain.<br/>',NULL,22745,3);
INSERT INTO stanza VALUES('NS470','3','We must ever preach the gospel,<br/>Cherishing and nourishing;<br/>Loving them as our dear children,<br/>As our priestly offering.<br/>',NULL,22746,4);
INSERT INTO stanza VALUES('NS470','4','We must ever preach the gospel<br/>By perfecting in the homes<br/>Through the word and prayer and singing,<br/>Never laboring alone.<br/>',NULL,22747,5);
INSERT INTO stanza VALUES('NS470','5','We must ever preach the gospel,<br/>Learning how to prophesy<br/>For the building of the Body,<br/>Thus the Lord to glorify.<br/>',NULL,22748,6);
INSERT INTO stanza VALUES('NS471','1','Shout Hosanna, all ye people,<br/>Christ defeated every evil;<br/>We unite with one accord;<br/>Praise Thee, ever conq’ring Lord.<br/>',NULL,22749,1);
INSERT INTO stanza VALUES('NS471','2','Nevermore we fear the devil,<br/>Christ destroyed him on the cross,<br/>Stripping off the authorities;<br/>Now we live His victory.<br/>',NULL,22750,2);
INSERT INTO stanza VALUES('NS471','chorus','God of peace now crushes Satan<br/>Under overcoming feet;<br/>Our rejoicing overthrows him,<br/>Shaming every enemy.<br/>',NULL,22751,3);
INSERT INTO stanza VALUES('NS471','3','All day long sing hallelujahs<br/>In the train of vanquished foes;<br/>Through our praise we never leave,<br/>Seated with Him at the throne.<br/>',NULL,22752,4);
INSERT INTO stanza VALUES('NS471','chorus','Never let the lies deceive you;<br/>Christ has shut the serpent’s mouth;<br/>Claim the fact that we have seen him<br/>In the lake of fire now.<br/>',NULL,22753,5);
INSERT INTO stanza VALUES('NS471','4','Soon the earth cries out, exalting<br/>Our returning, shining Lord;<br/>Until then we praise and sing;<br/>All the glory’s to our King.<br/>',NULL,22754,6);
INSERT INTO stanza VALUES('NS471','chorus','Consummated corporate warrior,<br/>New Jerusalem are we,<br/>One with our ascended Husband,<br/>Lord of lords and King of kings.<br/>',NULL,22755,7);
INSERT INTO stanza VALUES('NS471','5','Hallelujah, Christ the Conqueror,<br/>Every day we’re one with Him,<br/>Walking in Him constantly,<br/>Living Christ our victory.<br/>',NULL,22756,8);
INSERT INTO stanza VALUES('NS472','1','I’m a wild rose, wild rose of Sharon<br/>And I am like a lily of the valleys.<br/>',NULL,22757,1);
INSERT INTO stanza VALUES('NS472','2','So is my love among the daughters<br/>I am a lily among the thorns.<br/>',NULL,22758,2);
INSERT INTO stanza VALUES('NS472','3','As the apple tree among the trees<br/>Is my Beloved among the sons:<br/>In His shade delighted I sat down,<br/>And His fruit was sweet, was sweet to my taste.<br/>',NULL,22759,3);
INSERT INTO stanza VALUES('NS473','1','From all the young descendants<br/>Among our God’s elect<br/>Came forth some overcomers,<br/>Who Satan did reject.<br/>Midst all the opposition<br/>The enemy could hurl,<br/>They raised a heavenly standard;<br/>God’s banner to unfurl.<br/>',NULL,22760,1);
INSERT INTO stanza VALUES('NS473','chorus','As victors, as victors<br/>In Christ they took their stand.<br/>In Him they’re overcomers<br/>To bring forth His victory<br/>O’er the land.<br/>',NULL,22761,2);
INSERT INTO stanza VALUES('NS473','2','In subtle opposition the enemy did move;<br/>He offered king’s provisions,<br/>Their loyalties to prove.<br/>But Daniel and companions<br/>Were equal to the test.<br/>They spurned the royal dainties<br/>To settle for God’s best.<br/>',NULL,22762,3);
INSERT INTO stanza VALUES('NS473','3','Thus through the proper eating,<br/>The tree of life to take;<br/>Preserving inward virtue,<br/>Defilements forsake.<br/>God blessed them with all wisdom,<br/>In visions and in dreams;<br/>He gave them understanding<br/>And made their spirits keen.<br/>',NULL,22763,4);
INSERT INTO stanza VALUES('NS473','4','And when Nebuchadnezzar<br/>Was startled by a dream,<br/>He gathered his magicians<br/>To tell him what he’d seen.<br/>A statue as a portrait<br/>Of human governments<br/>From earliest beginnings<br/>Through predetermined ends.<br/>',NULL,22764,5);
INSERT INTO stanza VALUES('NS473','5','So Daniel told the vision,<br/>The king he was amazed.<br/>Daniel, you will have honor,<br/>Authority all your days.<br/>Like him our vision opened,<br/>Our hearts they must be wise<br/>To see in all these cultures;<br/>The enemy’s disguise.<br/>',NULL,22765,6);
INSERT INTO stanza VALUES('NS473','6','And through an open window<br/>God’s faithful one did pray;<br/>As for the holy city<br/>He bowed three times a day.<br/>Stirred up were Satan’s minions<br/>With jealousy and strife<br/>To frustrate God’s recovery<br/>And snare His servant’s life.<br/>',NULL,22766,7);
INSERT INTO stanza VALUES('NS473','7','Though still as roaring lion<br/>The enemy may rage,<br/>Our Father seeks a people<br/>To terminate the age.<br/>To stand within the lion’s den,<br/>For God be absolute;<br/>With Christ as our companion,<br/>All earthly tide refute.<br/>',NULL,22767,8);
INSERT INTO stanza VALUES('NS473','chorus','As victors, as victors<br/>In Christ we take our stand.<br/>To be His overcomers<br/>And bring forth the victory<br/>O’er the land.<br/>',NULL,22768,9);
INSERT INTO stanza VALUES('NS474','1','Let me love and not be respected;<br/>Let me serve and not be rewarded;<br/>Let me labor and not be remembered;<br/>Let me suffer and not be regarded.<br/>',NULL,22769,1);
INSERT INTO stanza VALUES('NS474','2','’Tis the pouring, not the drinking;<br/>’Tis the breaking, not the keeping—<br/>A life suff’ring to seek others’ blessing,<br/>A life loving and true comfort giving.<br/>',NULL,22770,2);
INSERT INTO stanza VALUES('NS474','3','Not expecting pity or concern,<br/>Not accepting solace or praise;<br/>Even lonely, even forgotten;<br/>Even wordless, even forsaken.<br/>',NULL,22771,3);
INSERT INTO stanza VALUES('NS474','4','Tears and blood for the righteous crown<br/>My price shall be; losing all,<br/>My cost for a faithful pilgrim’s life.<br/>’Twas the life, O Lord, that You chose to live<br/>In those days when on earth You walked,<br/>Gladly suff’ring all injuries and loss<br/>So that all might draw near and repose.<br/>',NULL,22772,4);
INSERT INTO stanza VALUES('NS474','5','I cannot see how much farther I shall go;<br/>Still I press on, knowing there is no return.<br/>Let me follow Your pattern, so perfect and true,<br/>Bearing all gratefully without complaint.<br/>',NULL,22773,5);
INSERT INTO stanza VALUES('NS474','6','In this time of trial, O my Lord,<br/>I pray that You would wipe my hidden tears away;<br/>Let me learn, O Lord, You are my reward;<br/>Let me be others’ blessing all my days.<br/>',NULL,22774,6);
INSERT INTO stanza VALUES('NS475','1','Lord we yearn for Your display<br/>On the earth as Your abode,<br/>Your authority and grace<br/>In the churches, in Your home.<br/>Every nation, every place,<br/>May Your name, Lord, be extolled<br/>That Your kingdom may increase,<br/>That Your glory may be told.<br/>',NULL,22775,1);
INSERT INTO stanza VALUES('NS475','2','How can we complacent be<br/>When Your churches are so few?<br/>Let us spread thru all the land;<br/>Make us faithful, make us true.<br/>Send me, Lord, unto Your work;<br/>Let me gain a harvest grand<br/>That Your kingdom might be spread,<br/>And Your testimony stand.<br/>',NULL,22776,2);
INSERT INTO stanza VALUES('NS475','3','Lampstand brightly shining forth<br/>In the darkest hour of night,<br/>Bringing hope and radiance sure<br/>To a world of pain and strife.<br/>Let us corporately come forth,<br/>Let us wage the worthy fight<br/>That Your building might be built<br/>And the world may see Your light.<br/>',NULL,22777,3);
INSERT INTO stanza VALUES('NS475','4','Churches spread throughout the earth<br/>As a stand of living trees,<br/>Full of life and full of fruit,<br/>Comfort, healing in their leaves.<br/>May we plant in thirsty hearts<br/>Living kingdom gospel seed;<br/>May we water, may we build<br/>And Your great commission heed.<br/>',NULL,22778,4);
INSERT INTO stanza VALUES('NS475','5','Rise up early and go forth<br/>To the vineyard and the field;<br/>Pomegranates here abound,<br/>And the vineyard is revealed.<br/>With the One we call Beloved<br/>There to labor, give our all,<br/>In the villages to lodge,<br/>There fulfill our Master’s call.<br/>',NULL,22779,5);
INSERT INTO stanza VALUES('NS476','1','There’s always been something hidden deep in Your heart,<br/>Yet I had not given it one single thought,<br/>I only knew that I was wand’ring, feeling lost,<br/>Dreaming were You, and I was too, in the wilderness,<br/>Until one day You revealed Your dream in my heart.<br/>',NULL,22780,1);
INSERT INTO stanza VALUES('NS476','2','Your heart’s desire is with man to mingle as one,<br/>To dwell with man, an eternal bond to form,<br/>’Twas for this dream You became man, uplifting man,<br/>That God and man, heaven and earth, be joined for aye,<br/>God’s house, heav’n’s gate, now descends, Your dream to attain.<br/>',NULL,22781,2);
INSERT INTO stanza VALUES('NS476','3','From heav’n You came as my bread of eternal life,<br/>By eating You, I can now enjoy Your life,<br/>Brought to His house, the Father’s love for You is mine,<br/>I’m joined, a branch, to You, the vine—union divine,<br/>By bearing fruit, this relationship multiplies.<br/>',NULL,22782,3);
INSERT INTO stanza VALUES('NS476','4','Abide in love,soHis life in us may flow free,<br/>By mutual love, His disciples we will be;<br/>The more we’re joined, the more we’re built organically,<br/>And by His word we’re sanctified, not of the world,<br/>As one new man, corporate God-man living we’ll see.<br/>',NULL,22783,4);
INSERT INTO stanza VALUES('NS476','5','O Lord, I place myself on the altar for You,<br/>For Your desire, that Your dream may become true.<br/>As for my life, I’d gladly dwell in a lowly tent,<br/>To bea drink off’ring outpoured for man<br/>God’s pillar, stand to fulfill God’s eternal plan.<br/>',NULL,22784,5);
INSERT INTO stanza VALUES('NS477','1','As the living Father has sent Me<br/>And I live because of the Father,<br/>As the living Father has sent Me<br/>And I live because of the Father,<br/>So he who eats Me, eats Me, eats Me,<br/>So he who eats Me, eats Me, eats Me,<br/>He also shall live<br/>Because of Me.<br/>',NULL,22785,1);
INSERT INTO stanza VALUES('NS478','1','Our Christ He is the fruit of earth,<br/>In excellence replete;<br/>Jehovah’s shoot, divinity;<br/>Where God with man does meet.<br/>',NULL,22786,1);
INSERT INTO stanza VALUES('NS478','2','Our Christ He is the canopy<br/>To shelter God’s elect,<br/>A hiding place, a shade from heat,<br/>God’s work He does protect.<br/>',NULL,22787,2);
INSERT INTO stanza VALUES('NS478','3','As virgin’s Son, to us He came—<br/>The universal sign;<br/>Immanuel, God dwells with us;<br/>O what a joy divine.<br/>',NULL,22788,3);
INSERT INTO stanza VALUES('NS478','4','Now unto us this child is born,<br/>As firstborn Son He came;<br/>As counselor, He’s wonderful,<br/>The mighty God His name.<br/>',NULL,22789,4);
INSERT INTO stanza VALUES('NS478','5','The shadow of a massive rock<br/>Upon a wasted soil,<br/>A refuge He from storm and wind,<br/>A rest from earthly toil.<br/>',NULL,22790,5);
INSERT INTO stanza VALUES('NS478','6','A twig and branch and Jesse’s root,<br/>The fruit of all the earth;<br/>He grew up as a tender plant,<br/>O what a Christ of worth.<br/>',NULL,22791,6);
INSERT INTO stanza VALUES('NS478','7','Our Christ, He is the cornerstone;<br/>He’s tested and secure,<br/>The glory of the Father’s house,<br/>Upon Him resting sure.<br/>',NULL,22792,7);
INSERT INTO stanza VALUES('NS478','8','Although He was despised by man,<br/>Acquainted He with grief;<br/>He paid the greatest sacrifice<br/>That we should find release.<br/>',NULL,22793,8);
INSERT INTO stanza VALUES('NS478','9','A peg that’s driven in the wall<br/>On which all glory rests,<br/>The faithful household steward He,<br/>God’s wisdom manifest.<br/>',NULL,22794,9);
INSERT INTO stanza VALUES('NS478','10','Eternal covenant He makes<br/>With David’s mercies sure;<br/>The thirsty He does satisfy<br/>With living waters pure.<br/>',NULL,22795,10);
INSERT INTO stanza VALUES('NS478','11','To properly portray this One,<br/>The Bible uses three:<br/>Isaiah, Cyrus, Israel;<br/>A threefold Servant He.<br/>',NULL,22796,11);
INSERT INTO stanza VALUES('NS478','12','The Prince of Peace and Mighty God,<br/>The Savior and the King,<br/>The light in the Millennium,<br/>’Tis of this One we sing.<br/>',NULL,22797,12);
INSERT INTO stanza VALUES('NS478','13','Since unto us this light has shined,<br/>Who dwell in Galilee,<br/>We evermore declare His praise,<br/>O what a Christ is He.<br/>',NULL,22798,13);
INSERT INTO stanza VALUES('NS479','1','He brought me in, into His banqueting house,<br/>And His banner high over me was just love.<br/>Here I’m refreshed and sustained by His love,<br/>For I’m sick, sick with love, in love with Him.<br/>',NULL,22799,1);
INSERT INTO stanza VALUES('NS479','2','Sustain me love with the sweet raisin cakes,<br/>And refresh me with the apples so sweet,<br/>Here I am conquered by Your sweet, sweet love,<br/>For I’m sick, sick with love, in love with You.<br/>',NULL,22800,2);
INSERT INTO stanza VALUES('NS479','3','His left hand is under my head,<br/>And His right hand embraces me.<br/>I am held and embraced by Him,<br/>Oh daughters of Jerusalem.<br/>',NULL,22801,3);
INSERT INTO stanza VALUES('NS479','4','He brought me into His banqueting house,<br/>And His banner over me was love,<br/>I’m sick with love for Him.<br/>',NULL,22802,4);
INSERT INTO stanza VALUES('NS480','1','Stone-ify me for Your building,<br/>I desire a home for Thee;<br/>Let me share Your dream of Bethel;<br/>Duplicate Your heart in me.<br/>Burn, refine away the nat’ral,<br/>Transformed preciousness I’d be;<br/>Lord, perfect me as a pillar,<br/>Standing solid, weightily.<br/>',NULL,22803,1);
INSERT INTO stanza VALUES('NS480','2','Ankle-holder, a supplanter;<br/>My demands to God I bring.<br/>If God keeps me, clothes and feeds me,<br/>Him I’ll own as God, my King.<br/>Chosen ere the earth’s foundation;<br/>“Israel,” I to blessing cling.<br/>Though I suffer, squeezed by Laban,<br/>I am sheltered ’neath Your wing.<br/>',NULL,22804,2);
INSERT INTO stanza VALUES('NS480','3','Ladder, joining earth and heaven;<br/>Make my heart Your dwelling place.<br/>Burden me to build Your house, Lord;<br/>For this now I consecrate.<br/>Pillars stand He will Establish,<br/>In Him’s Strength—of truth the base.<br/>Gain me to enlarge Your temple,<br/>Testimony propagate.<br/>',NULL,22805,3);
INSERT INTO stanza VALUES('NS480','4','While I pass through tribulations,<br/>Situations heated press.<br/>Let me see Your hand most sovereign;<br/>Oil anointing on me dress.<br/>All my days, Your presence filleth;<br/>Life and nature, God express.<br/>Leaning on You, Staff, my Shepherd;<br/>Flowing out to others bless.<br/>',NULL,22806,4);
INSERT INTO stanza VALUES('NS480','5','Stone-ify me for Your building,<br/>I desire a home for Thee;<br/>Let me share Your dream of Bethel;<br/>Duplicate Your heart in me.<br/>Burn, refine away the nat’ral,<br/>Transformed preciousness I’d be;<br/>Lord, perfect me as a pillar,<br/>Standing solid, weightily.<br/>',NULL,22807,5);
INSERT INTO stanza VALUES('BF434','1','Hark, the Savior’s knocking,<br/>Knocking at your heart!<br/>Oh, do not be hardened,<br/>Lest He should depart.<br/>Rise and open up your heart,<br/>Quickly let Him in;<br/>Life divine He’ll give you,<br/>And forgive your sin.<br/>',NULL,22808,1);
INSERT INTO stanza VALUES('BF434','chorus','Let Him in! Let Him in!<br/>He is knocking at your heart;<br/>Let Him in! Oh, let Him in!<br/>Let Him into your heart.<br/>',NULL,22809,2);
INSERT INTO stanza VALUES('BF434','2','Why should you still tarry,<br/>Keep Him waiting there?<br/>He is kind and gracious,<br/>Merciful and dear.<br/>Listen to His tender voice<br/>Do not grieve His heart,<br/>Won’t you let Him enter,<br/>And His grace impart.<br/>',NULL,22810,3);
INSERT INTO stanza VALUES('BF435','1','Sun of my soul, Thou Savior dear,<br/>It is not night if Thou be near;<br/>Oh, may no earthborn cloud arise<br/>To hide Thee from Thy servant’s eyes.<br/>',NULL,22811,1);
INSERT INTO stanza VALUES('BF435','2','When the soft dews of kindly sleep<br/>My wearied eyelids gently steep,<br/>Be my last thought how sweet to rest<br/>Forever on my Savior’s breast.<br/>',NULL,22812,2);
INSERT INTO stanza VALUES('BF435','3','Abide with me from morn till eve,<br/>For without Thee I cannot live;<br/>Abide with me when night is nigh,<br/>For without Thee I dare not die.<br/>',NULL,22813,3);
INSERT INTO stanza VALUES('BF435','4','Come near, and bless us when we wake,<br/>Ere through the world our way we take;<br/>Till in the ocean of Thy love<br/>We lose ourselves in Thee above.<br/>',NULL,22814,4);
INSERT INTO stanza VALUES('BF436','1','Through God’s word, my hope at His returning<br/>Is that all my being be redeemed;<br/>Yet in times of grief and tribulation,<br/>Doubt and fear arise, no hope is seen.<br/>In those hours, when prayer cannot be uttered,<br/>Only groaning from my breast is heard.<br/>Then the Spirit, in like manner, helps me,<br/>Praying in my weakness unto God.<br/>',NULL,22815,1);
INSERT INTO stanza VALUES('BF436','2','Lord, my prayer is not for deeper suffering,<br/>But that from each trial I’d be free.<br/>Let the cup of bitterness be taken;<br/>Yet, Thy will, not mine, dear Lord, must be.<br/>Even now, though trials sore surround me,<br/>Still within my heart there is a peace,<br/>For the love of God outpoured within me<br/>Floods my heart and bids my doubting cease.<br/>',NULL,22816,2);
INSERT INTO stanza VALUES('BF436','3','Blest assurance! God has fully ordered<br/>Every matter by His sovereign hand;<br/>Every person (though we see so dimly),<br/>Every thing’s according to His plan.<br/>Every trial is but the Father’s answer<br/>To the groaning of the Spirit’s prayer;<br/>May He gain in every tribulation,<br/>Until we Christ’s glory fully share.<br/>',NULL,22817,3);
INSERT INTO stanza VALUES('BF436','4','How could God from all His dealings spare us,<br/>After He spared not His only Son?<br/>Could the Potter’s hand upon the vessel<br/>Ever leave the shaping work undone?<br/>For the center of God’s heart’s desire<br/>Is that many brethren we will be<br/>Unto Christ, His precious First-begotten,<br/>And to Him, conformed we’ll fully be.<br/>',NULL,22818,4);
INSERT INTO stanza VALUES('BF436','5','Heirs of God! Joint-heirs with our Lord Jesus!<br/>What a hope of glory this for us!<br/>Though the suff’rings presently seem grievous,<br/>Greater far the glory then for us!<br/>Yea, in all these things we more than conquer,<br/>Through the One whose love has us possessed;<br/>Soon the day for which waits all creation,<br/>When the sons of God are manifest!<br/>',NULL,22819,5);
INSERT INTO stanza VALUES('BF437','1','Thou Magnet of my soul!<br/>Let me come nearer, till<br/>The life of self pulsates no more,<br/>But is forever still.<br/>',NULL,22820,1);
INSERT INTO stanza VALUES('BF437','2','Thou Sunshine of my heart!<br/>Fill Thou each crevice there,<br/>And let Thy garden yield to Thee<br/>A fragrance sweet and rare.<br/>',NULL,22821,2);
INSERT INTO stanza VALUES('BF437','3','Thou Ransomer from death!<br/>Possess Thy ransomed one:<br/>Appropriate to Thine Own use<br/>The spoil that Thou hast won.<br/>',NULL,22822,3);
INSERT INTO stanza VALUES('BF437','4','Thou Lord of Life and Light!<br/>I bow beneath Thy sway,<br/>And count it holy privilege<br/>Thy precepts to obey.<br/>',NULL,22823,4);
INSERT INTO stanza VALUES('BF437','5','Thou Gift unspeakable!<br/>Straight from God’s heart of love;<br/>I break my heart to give Thee room<br/>And thus Thy sweetness prove.<br/>',NULL,22824,5);
INSERT INTO stanza VALUES('BF438','1','I give my heart to Thee,<br/>O Jesus most desired;<br/>And heart for heart the gift shall be,<br/>For Thou my heart hast fired.<br/>Thou hearts alone wouldst move,<br/>Thou only hearts dost love;<br/>I would love Thee as Thou lov’st me,<br/>O Jesus most desired.<br/>',NULL,22833,1);
INSERT INTO stanza VALUES('BF438','2','What off’ring can I make,<br/>Dear Lord, to love like Thine;<br/>That Thou, the Word, didst stoop to take<br/>A human form like mine?<br/>“Give Me thy heart, my son“:<br/>Lord, Thou my heart hast won;<br/>I would love Thee as Thou lov’st me,<br/>O Jesus most desired.<br/>',NULL,22834,2);
INSERT INTO stanza VALUES('BF438','3','Thy heart is opened wide,<br/>Its offered love most free,<br/>That heart to heart I may abide,<br/>And hide myself in Thee.<br/>Ah, how Thy love doth burn,<br/>Till I that love return!<br/>I would love Thee as Thou lov’st me,<br/>O Jesus most desired.<br/>',NULL,22835,3);
INSERT INTO stanza VALUES('BF438','4','Here finds my heart its rest,<br/>Repose that knows no shock,<br/>The strength of love that keeps it blest<br/>In Thee, the riven Rock.<br/>My heart, as girt around,<br/>Her citadel hath found;<br/>I would love Thee as Thou lov’st me,<br/>O Jesus most desired.<br/>',NULL,22836,4);
INSERT INTO stanza VALUES('BF439','1','Arise, my soul, arise!<br/>Shake off thy guilty fears;<br/>The bleeding Sacrifice<br/>In my behalf appears.<br/>Before the throne my Surety stands;<br/>My name is written on His hands.<br/>',NULL,22849,1);
INSERT INTO stanza VALUES('BF439','2','He ever lives above<br/>For me to intercede,<br/>His all-redeeming love,<br/>His precious blood to plead.<br/>His blood was shed for all our race,<br/>And sprinkles now the throne of grace.<br/>',NULL,22850,2);
INSERT INTO stanza VALUES('BF439','3','Five bleeding wounds He bears,<br/>Received on Calvary;<br/>They pour effectual prayers;<br/>They strongly speak for me.<br/>Forgive him, O forgive, they cry,<br/>Nor let that ransomed sinner die!<br/>',NULL,22851,3);
INSERT INTO stanza VALUES('BF439','4','The Father hears Him pray,<br/>His dear anointed One;<br/>He cannot turn away<br/>The presence of His Son.<br/>His Spirit answers to the blood,<br/>And tells me I am born of God.<br/>',NULL,22852,4);
INSERT INTO stanza VALUES('BF439','5','To God I’m reconciled,<br/>His pardoning voice I hear;<br/>He owns me for His child,<br/>I can no longer fear.<br/>With confidence I now draw nigh,<br/>And Father, Abba, Father, cry.<br/>',NULL,22853,5);
INSERT INTO stanza VALUES('E811','7',replace('Feeding and drinking, Lord Jesus, of Thee,<br/>Feeding by reading, and drinking by prayer;<br/>Reading and praying, I eat and I drink,<br/>Praying and reading-Lord, Thou art my fare.<br/>\n','\n',char(10)),NULL,22854,4214);
INSERT INTO stanza VALUES('E811','8','Here, O my Lord, may I feast upon Thee;<br/>Flood with Thy Spirit and fill by Thy Word;<br/>May, Lord, Thou be such a feast unto me<br/>As man hath never enjoyed nor e’er heard.<br/>',NULL,22855,4215);
INSERT INTO stanza VALUES('C1001','1','頌讚與尊貴與榮耀歸你，<br/>與榮耀歸你，<br/>與榮耀歸你。<br/>頌讚與尊貴與榮耀歸你，<br/>直到永永遠遠。<br/>讚祂！讚祂！<br/>聖徒都要拜祂！<br/>讚祂！讚祂！<br/>直到永永遠遠。<br/>阿利路亞！<br/>頌讚與尊貴與榮耀歸你，<br/>與榮耀歸你，<br/>與榮耀歸你。<br/>頌<br/>讚與尊貴與榮耀歸你，<br/>直到永永遠遠。<br/>',NULL,22856,1);
INSERT INTO stanza VALUES('C1002','chorus','阿利路、阿利路、<br/>阿利路、阿利路亞，<br/>讚美我主！<br/>阿利路、阿利路、<br/>阿利路、阿利路亞，<br/>讚美我主！<br/>讚美我主，阿利路亞，<br/>讚美我主！阿利路亞，<br/>讚美我主！阿利路亞，<br/>讚美我主！<br/>',NULL,22857,1);
INSERT INTO stanza VALUES('C1003','1','諸天述說神的榮耀；<br/>穹蒼傳揚祂的巧妙。<br/>日夜發言，曉諭不已，<br/>通遍天下，傳到地極。<br/>神的永能，和祂特徵，<br/>藉祂創造全都顯明；<br/>雖非人眼所能見到，<br/>但觀造物即可洞曉。<br/>',NULL,22858,1);
INSERT INTO stanza VALUES('C1003','2','創造天地、萬物活神，<br/>為證自己存在可信：<br/>常施恩惠，賞賜豐稔，<br/>使人飽足，喜樂滿心。<br/>天降甘霖，地生五穀，<br/>永活真神所賜之福；<br/>豐衣足食，享受天恩，<br/>理當念及造物之神。<br/>',NULL,22859,2);
INSERT INTO stanza VALUES('C1003','3','天地之主，萬物之神，<br/>生命、氣息，賜給萬人；<br/>年限、疆界，由祂定準，<br/>要人揣摩，將祂求尋。<br/>自隱之神，人間之謎；<br/>不見之神，宇宙之祕。<br/>此一真理，人人當知，<br/>宇宙意義始能賞識。<br/>',NULL,22860,3);
INSERT INTO stanza VALUES('C1003','4','不見之神顯於所見，<br/>神聖啟示尚非完全；<br/>神的身位，神的形像，<br/>還需一人前來表彰。<br/>耶穌基督，神的愛子，<br/>降世成為人的樣式；<br/>神的特性，神的所是，<br/>全由這人彰顯盡致。<br/>',NULL,22861,4);
INSERT INTO stanza VALUES('C1003','5','奧祕基督，奇妙救主，<br/>乃是神在人間顯出。<br/>原是永遠無限的神，<br/>竟作時間有限的人。<br/>奧妙基督，神的化身，<br/>神人調和，驚人佳音。<br/>祂是真神，又是真人，<br/>要進你心，作你福分。<br/>',NULL,22862,5);
INSERT INTO stanza VALUES('C1003','6','神的神性藏祂裏面，<br/>神的榮形從祂彰顯。<br/>前在肉身成功救贖，<br/>今成那靈與人聯屬。<br/>神人基督，道成肉身，<br/>捨命流血，救贖罪人；<br/>從死復活，化身那靈，<br/>為進你靈，作你生命。<br/>',NULL,22863,6);
INSERT INTO stanza VALUES('C1004','1','人是神造的容器，<br/>有靈有魂又有體。<br/>神要作人的內容，<br/>從人顯出祂光榮。<br/>',NULL,22864,1);
INSERT INTO stanza VALUES('C1004','2','人原有神的形像，<br/>身分地位何高尚；<br/>還須有神的生命，<br/>得以分享祂性情。<br/>',NULL,22865,2);
INSERT INTO stanza VALUES('C1004','3','基督乃是神顯出，<br/>為人受死，將人贖；<br/>復活成為生命靈，<br/>進入人靈作生命。<br/>',NULL,22866,3);
INSERT INTO stanza VALUES('C1004','4','人的生存無基督，<br/>一切盡都感虛無：<br/>失缺人生的意義，<br/>無指無望，無目的。<br/>',NULL,22867,4);
INSERT INTO stanza VALUES('C1004','5','接受基督作生命，<br/>人就靈裏得重生；<br/>時時憑祂而生活，<br/>虛空人生變詩歌。<br/>',NULL,22868,5);
INSERT INTO stanza VALUES('C1004','6','如此便能彰顯神，<br/>也能造福於人群，<br/>流出活水的江河，<br/>解除群眾的乾渴。<br/>',NULL,22869,6);
INSERT INTO stanza VALUES('C1004','7','基督凱歸榮耀中，<br/>你的身體必得榮，<br/>變得與祂形狀同，<br/>同榮共存永無終。<br/>',NULL,22870,7);
INSERT INTO stanza VALUES('C1005','1','何大神蹟！何深奧祕！<br/>神竟與人聯調為一！<br/>神成為人，人成為神，<br/>天使、世人莫測經綸；<br/>出自神的心愛美意，<br/>達到神的最高目的。<br/>出自神的心愛美意，<br/>達到神的最高目的。<br/>',NULL,22871,1);
INSERT INTO stanza VALUES('C1005','2','神成肉身，來作神人，<br/>為要使我能成為神，<br/>生命、性情與祂同類，<br/>惟我無分祂的神位；<br/>祂的屬性變我美德，<br/>祂的榮形在我顯活。<br/>祂的屬性變我美德，<br/>祂的榮形在我顯活。<br/>',NULL,22872,2);
INSERT INTO stanza VALUES('C1005','3','不再是我單獨活著，<br/>乃是神我共同生活；<br/>並與眾聖神裏配搭，<br/>建成三一宇宙之家，<br/>且成基督生機身體，<br/>作祂顯身團體大器。<br/>且成基督生機身體，<br/>作祂顯身團體大器。<br/>',NULL,22873,3);
INSERT INTO stanza VALUES('C1005','4','最終聖城耶路撒冷，<br/>異象、啟示集其大成。<br/>三一之神，三部分人，<br/>永世對耦是人又神；<br/>神性人性互為居所，<br/>神的榮耀在人顯赫。<br/>神性人性互為居所，<br/>神的榮耀在人顯赫。<br/>',NULL,22874,4);
INSERT INTO stanza VALUES('C1006','1','神，你生命所施拯救，<br/>全都照你公義要求；<br/>你的救恩完整無弊，<br/>既合法理，又富生機。<br/>',NULL,22875,1);
INSERT INTO stanza VALUES('C1006','2','救贖是照法理完成，<br/>拯救是由生機施行；<br/>法理滿足你的公義，<br/>生機成就你的美意。<br/>',NULL,22876,2);
INSERT INTO stanza VALUES('C1006','3','法理使我得你稱義，<br/>生機使我與你合一：<br/>將我重生成為神人，<br/>將我聖化全人更新。<br/>',NULL,22877,3);
INSERT INTO stanza VALUES('C1006','4','將我變化模成榮形，<br/>新陳代謝顯於生命；<br/>生命成熟長大成人，<br/>同人配搭建成一身。<br/>',NULL,22878,4);
INSERT INTO stanza VALUES('C1006','5','身體得贖，進入榮耀，<br/>兒子名分達到至高；<br/>與你相調，互為居所，<br/>聖城撒冷成我詩歌。<br/>',NULL,22879,5);
INSERT INTO stanza VALUES('E1403','1','The heavens God’s glory declare,<br/>And the sky His work proclaimeth;<br/>Day unto day their speech pours forth<br/>To farthest reaches of the earth.<br/>God’s attributes, eternal pow’r<br/>By creation are thus made known;<br/>Things human eyes can’t realize<br/>By things He created are shown.<br/>',NULL,22880,1);
INSERT INTO stanza VALUES('E1403','2','The living Creator of all<br/>Did not leave Himself without witness,<br/>With grace and harvest bounteous,<br/>He fills our hearts with gladness.<br/>Heav’n sends down rain, earth brings forth grain—<br/>As bestowed from God, living, true;<br/>Ye clothed, sustained, enjoying grace,<br/>Be mindful of Him who made you.<br/>',NULL,22881,2);
INSERT INTO stanza VALUES('E1403','3','The Lord of all heaven and earth,<br/>Life and breath to all men giveth;<br/>Their boundaries and seasons sets<br/>That groping they might find Him yet.<br/>God—hidden, unseen mystery—<br/>Universal secret is He;<br/>All men must learn, this truth discern,<br/>Creation’s true meaning to see.<br/>',NULL,22882,3);
INSERT INTO stanza VALUES('E1403','4','Creation shows something of God,<br/>But ’tis not full revelation.<br/>His person, image, only can<br/>Be properly expressed through man.<br/>Christ Jesus, God’s beloved Son,<br/>Came to earth, a human became;<br/>God’s very nature, all God is,<br/>He constantly, fully displayed.<br/>',NULL,22883,4);
INSERT INTO stanza VALUES('E1403','5','Mysterious Christ, marvelous!<br/>God is manifest among us.<br/>God infinite, in eternity,<br/>Yet man in time, finite to be;<br/>O Christ, mysterious, God in flesh,<br/>Wond’rous news—God mingled with man!<br/>As God yet man, He’d enter in,<br/>Your blessed rich portion within.<br/>',NULL,22884,5);
INSERT INTO stanza VALUES('E1403','6','God’s nature was hidden in Him;<br/>He did manifest God’s image.<br/>In flesh He has redemption wrought;<br/>As Spirit, oneness with me sought.<br/>Oh, God-man Christ, incarnate Word,<br/>Bled and died to sinners redeem,<br/>Rose from the grave, as Spirit came<br/>To fill you, your life to be.<br/>',NULL,22885,6);
INSERT INTO stanza VALUES('E1404','1','God made man a vessel he<br/>With a spirit, soul, body.<br/>God to man his content be<br/>That through man His glory see.<br/>',NULL,22886,1);
INSERT INTO stanza VALUES('E1404','2','Man does have God’s image true,<br/>Noble in his status, too.<br/>But God’s life man also needs<br/>Divine nature to receive.<br/>',NULL,22887,2);
INSERT INTO stanza VALUES('E1404','3','Christ in death as God expressed<br/>Man redeemed, His blood was shedd’st.<br/>In His resurrection He<br/>Enters us our life to be.<br/>',NULL,22888,3);
INSERT INTO stanza VALUES('E1404','4','Man without Christ will perceive<br/>That all things are vanity.<br/>Human life is meaningless<br/>Without hope or purpose.<br/>',NULL,22889,4);
INSERT INTO stanza VALUES('E1404','5','But when man takes Christ as life,<br/>He’s in spirit born anew.<br/>When he daily lives by Christ,<br/>Vanity is turned to song.<br/>',NULL,22890,5);
INSERT INTO stanza VALUES('E1404','6','Therefore, man can God express<br/>That the whole world he would bless.<br/>Living water flowing out<br/>People’s thirst to satisfy.<br/>',NULL,22891,6);
INSERT INTO stanza VALUES('E1404','7','When in glory Christ returns<br/>Glorified our body be<br/>To His glorious body conformed<br/>With Him for eternity.<br/>',NULL,22892,7);
INSERT INTO stanza VALUES('T102','1','die to all Master?<br/>Thou who Thee? give I me.<br/>Shall I Thee, didst give of less give I possess,<br/>Or shall I for shall what What<br/>',NULL,23391,1);
INSERT INTO stanza VALUES('T102','chorus','all home shall of a giv’n all Lord giv’n half Thy leave for for die me;<br/>Thou give hast hast and my will all didst just Thee, above<br/>To me;<br/>Not I on Jesus, Master?<br/>Thou give to my Savior;<br/>Thou part heart,<br/>I Calvary.<br/>What Thee. or<br/>',NULL,23392,2);
INSERT INTO stanza VALUES('T102','2','small I it my all—<br/>Surrendered hast redeemed Thee, is to but Master?<br/>Thou What control. Thy soul;<br/>My my is shall gift give<br/>',NULL,23393,3);
INSERT INTO stanza VALUES('T102','3','shall talents gold—<br/>For divine!<br/>I What or be Master?<br/>Giver Thee, hold everything give not will time, Thine. shall gifts I of<br/>',NULL,23394,4);
INSERT INTO stanza VALUES('E975','7','’Tis for the city man is wrought upon,<br/>Therefore regenerated and transformed<br/>To purest gold, to pearls and precious stones,<br/>As Christ’s own Body, to Himself conformed.<br/>',NULL,26996,5107);
INSERT INTO stanza VALUES('E975','8','Within the garden also was a bride,<br/>Who was to Adam as his counterpart;<br/>Lastly, the city is itself the bride<br/>As Christ’s own fulness, precious to His heart.<br/>',NULL,26997,5108);
INSERT INTO stanza VALUES('E975','9','The city is God’s building work replete,<br/>A composition of the justified;<br/>A habitation it affords to God<br/>And is to Christ His own beloved bride.<br/>',NULL,26998,5109);
INSERT INTO stanza VALUES('E975','10','’Tis God’s expression, ultimate and full,<br/>Corporate and universal, marvelous;<br/>God’s glory it completely manifests,<br/>And is Christ’s counterpart most glorious.<br/>',NULL,26999,5110);
INSERT INTO stanza VALUES('E576','5','I take Him for this mortal frame,<br/>I take my healing through His Name,<br/>And all His risen life I claim,<br/>“I take”—“He undertakes.”<br/>',NULL,27000,2953);
INSERT INTO stanza VALUES('E576','6','I simply take Him at His word,<br/>I praise Him that my prayer is heard,<br/>And claim my answer from the Lord,<br/>“I take”—“He undertakes.”<br/>',NULL,27001,2954);
INSERT INTO stanza VALUES('FR1','1','Rendons gloire à notre Père,<br/>Rendons toute gloire au Fils,<br/>À l''Esprit rendons la gloire,<br/>Trois en Un, sois exalté<br/>',NULL,27003,1);
INSERT INTO stanza VALUES('FR1','chorus','Nous Te louons ! Nous Te louons !<br/>Toi qui es un, qui es trois !<br/>Gloire à Toi ! à Toi la gloire !<br/>Des merveilles Tu as fait pour nous.<br/>',NULL,27004,2);
INSERT INTO stanza VALUES('FR1','2','Le dessein de notre Père,<br/>Christ le Fils l''a accompli,<br/>Tout est transmis par Dieu l''Esprit :<br/>Louée soit la trinité!<br/>',NULL,27005,3);
INSERT INTO stanza VALUES('FR2','1','Ô Père, source de la vie,<br/>Ton courant nous est cher !<br/>Eau vive qui coule et jaillit<br/>Jusqu''en éternité !<br/>',NULL,27006,1);
INSERT INTO stanza VALUES('FR2','2','Coulant, par amour, dans le Fils,<br/>Tu T''approchas de nous.<br/>Tu coules par l''Esprit aussi,<br/>Avec Ta grâce en nous.<br/>',NULL,27007,2);
INSERT INTO stanza VALUES('FR2','3','Alors que dans l''iniquité<br/>Nous avons fui Ta face,<br/>Dans le Fils Tu nous as sauvés,<br/>Nous donnant vie et grâce.<br/>',NULL,27008,3);
INSERT INTO stanza VALUES('FR2','4','Souvent T''avons-nous dédaigné<br/>Attristant Ton Esprit.<br/>Dans l''Esprit Tu es arrivé<br/>Pour nous donner la vie.<br/>',NULL,27009,4);
INSERT INTO stanza VALUES('FR2','5','En tant qu'' Esprit et dans le Fils,<br/>Tu es la sainte onction.<br/>Ton être entier nous est transmis<br/>En pleine communion.<br/>',NULL,27010,5);
INSERT INTO stanza VALUES('FR2','6','L''amour de Dieu nous a donné<br/>La grâce de Son Fils,<br/>Nous pouvons donc participer<br/>À Dieu par Son Esprit.<br/>',NULL,27011,6);
INSERT INTO stanza VALUES('FR2','7','Ô Père, Fils et Saint-Esprit :<br/>Tu prends bien soin de nous.<br/>Nous chantons Ton amour béni,<br/>T''adorons pour toujours !<br/>',NULL,27012,7);
INSERT INTO stanza VALUES('FR3','1','Nous Te vénérons, cher Père !<br/>Tu es saint et tout-puissant.<br/>Nous Te louons tous ensemble,<br/>Tu es digne, Tu es grand.<br/>',NULL,27013,1);
INSERT INTO stanza VALUES('FR3','2','Plein d''amour et de lumière,<br/>Tout Ton être est sainteté<br/>Tous Tes actes sont justice,<br/>Grande est Ta fidélité.<br/>',NULL,27014,2);
INSERT INTO stanza VALUES('FR3','3','L''aspersion du sang de Jésus,<br/>Nous a mis à part pour toi.<br/>Ta parole sainte et pure<br/>toujours nous sanctifiera.<br/>',NULL,27015,3);
INSERT INTO stanza VALUES('FR3','4','Avec jalousie Tu chéris<br/>L'' Esprit que Tu m''as donné<br/>Que ma marche et tout mon être<br/>Soient du monde séparé.<br/>',NULL,27016,4);
INSERT INTO stanza VALUES('FR3','5','Par Ta grâce, Tu m''as donné<br/>En Ton Fils, Ta sainte vie.<br/>Je prends part à Ta nature,<br/>De Toi-même je jouis.<br/>',NULL,27017,5);
INSERT INTO stanza VALUES('FR3','6','La Jérusalem céleste<br/>Est constituée d''or fin.<br/>De Ta sainteté divine<br/>Tu satureras Tes saints !<br/>',NULL,27018,6);
INSERT INTO stanza VALUES('FR4','1','L''amour de Dieu de loin surpasse,<br/>Ce qu''en peut dire un cœur humain.<br/>Il est plus grand que les espaces,<br/>Même en l''abîme, il nous atteint.<br/>Pour le péché de notre monde,<br/>Dieu nous donna Jésus.<br/>Il nous pardonne, oh ! paix profonde !<br/>Il sauve les perdus.<br/>',NULL,27019,1);
INSERT INTO stanza VALUES('FR4','chorus','L''amour de Dieu, si fort, si tendre,<br/>Est un amour sans fin,<br/>Tel est le chant, que font entendre,<br/>Les anges et les saints.<br/>',NULL,27020,2);
INSERT INTO stanza VALUES('FR4','2','Que notre monde un jour chancelle,<br/>Avec ses trônes, avec ses rois,<br/>Quand trembleront tous les rebelles,<br/>Soudain saisis d''un grand effroi,<br/>L''amour de Dieu, que rien ne lasse,<br/>Pour nous encore vivra.<br/>C''est le miracle de la grâce.<br/>Amen ! Alléluia !<br/>',NULL,27021,3);
INSERT INTO stanza VALUES('FR4','3','Versez de l''encre dans les ondes,<br/>Changez le ciel en parchemin,<br/>Tendez la plume à tout le monde<br/>Et que chacun soit écrivain.<br/>Écrire tout l''amour de Père<br/>Ferait tarir les eaux<br/>Et remplirait la place entière,<br/>Sur ces divins rouleaux.<br/>',NULL,27022,4);
INSERT INTO stanza VALUES('FR5','1','Cher Père, Tu nous as aimés<br/>D''un amour si profond,<br/>Nos cœurs reconnaissants Te louent,<br/>Nous élevons Ton nom !<br/>',NULL,27023,1);
INSERT INTO stanza VALUES('FR5','2','Tu nous as révélé Ton cœur,<br/>Ton dessein bienveillant.<br/>Tu vins dans Ton Fils bien-aimé,<br/>Pour accomplir Ton plan.<br/>',NULL,27024,2);
INSERT INTO stanza VALUES('FR5','3','Ton Fils unique Tu livras.<br/>La mort Il accepta,<br/>Pour faire de nombreux pécheurs<br/>Beaucoup de fils pour Toi.<br/>',NULL,27025,3);
INSERT INTO stanza VALUES('FR5','4','Nous sommes, Père, Tes enfants,<br/>Tu nous as engendrés.<br/>Ta vie divine nous avons,<br/>À nous Tu T''es donné.<br/>',NULL,27026,4);
INSERT INTO stanza VALUES('FR5','5','L'' Esprit du Fils dans notre esprit<br/>« Abba cher Père ! » crie.<br/>Scellés de Lui, nous jouissons<br/>Du gage de l''Esprit.<br/>',NULL,27027,5);
INSERT INTO stanza VALUES('FR5','6','De gloire en gloire par l''Esprit,<br/>Nous sommes transformés<br/>Et à l''image de Ton Fils,<br/>Tu vas nous conformer.<br/>',NULL,27028,6);
INSERT INTO stanza VALUES('FR5','7','Quand dans la gloire Tu auras<br/>Conduit les rachetés,<br/>Ton but alors sera atteint,<br/>Ton désir satisfait.<br/>',NULL,27029,7);
INSERT INTO stanza VALUES('FR5','8','Cher Père, Tu nous as aimés.<br/>Nous magnifions Ton nom.<br/>Nos cœurs Te sont reconnaissants.<br/>Combien nous T''adorons !<br/>',NULL,27030,8);
INSERT INTO stanza VALUES('FR6','1','Tu nous as aimés, cher Père,<br/>Bien avant la création.<br/>À Jésus Tu nous attires,<br/>Par Ta tendre persuasion.<br/>Tu nous gardes, Tu nous gardes<br/>Toujours en sécurité<br/>Toujours en sécurité!<br/>',NULL,27031,1);
INSERT INTO stanza VALUES('FR6','2','Ton amour est immuable,<br/>Sa richesse coule à flots.<br/>Sa puissance inaltérable,<br/>Nous garde en un saint repos.<br/>Dieu et Père, Dieu et Père !<br/>C''est Toi que nous adorons !<br/>C''est Toi que nous adorons !<br/>',NULL,27032,2);
INSERT INTO stanza VALUES('FR6','3','Dieu d''amour, nos cœurs T''adorent.<br/>Que Ta grâce soit chantée !<br/>Jusqu''au jour où nos couronnes<br/>Seront devant Toi posées.<br/>Chants de gloire, Chants de gloire<br/>Soient à Dieu et à l''Agneau,<br/>Soient à Dieu et à l''Agneau !<br/>',NULL,27033,3);
INSERT INTO stanza VALUES('FR7','1','Nous Te louons Père,<br/>Pour le Fils bien-aimé:<br/>Le Sauveur qui mourut<br/>Et qui fut élevé.<br/>',NULL,27034,1);
INSERT INTO stanza VALUES('FR7','chorus','Alléluia, à Toi la gloire !<br/>Alléluia, amen !<br/>Alléluia, à Toi la gloire !<br/>Pour l''éternité!<br/>',NULL,27035,2);
INSERT INTO stanza VALUES('FR7','2','Nous Te louons Père,<br/>Pour l''Esprit de lumière,<br/>Qui montra le Sauveur<br/>Et chassa notre nuit.<br/>',NULL,27036,3);
INSERT INTO stanza VALUES('FR7','3','À Toi soit l''honneur,<br/>Et à Toi soit la gloire !<br/>En Christ, la rédemption<br/>Nous révèle Ton cœur.<br/>',NULL,27037,4);
INSERT INTO stanza VALUES('FR7','4','Nous Te louons Père,<br/>Ton amour nous remplit,<br/>Tu réveilles nos cœurs,<br/>Nous montrant Ton amour.<br/>',NULL,27038,5);
INSERT INTO stanza VALUES('FR8','1','Ton plaisir, Dieu de grâce,<br/>En Christ est révélé<br/>Je sais : rien ne surpasse<br/>Ta sainte volonté !<br/>Jésus franchit le voile,<br/>Un homme entra au ciel,<br/>Manifestant Ta gloire,<br/>Ton dessein éternel.<br/>',NULL,27039,1);
INSERT INTO stanza VALUES('FR8','2','L''amour sur Son visage<br/>Rayonne et resplendit.<br/>De cette source brille<br/>La lumière bénie.<br/>Ce que Tu es, Toi, Père,<br/>La dévoilé Ton Fils.<br/>Ta grâce nous accorde<br/>Une place avec Lui.<br/>',NULL,27040,2);
INSERT INTO stanza VALUES('FR8','3','Toi source de la grâce !<br/>Toi, fontaine de joie !<br/>Unis devant Ta face,<br/>Nous disons notre foi !<br/>Nos cœurs Ta gloire chantent,<br/>Renvoyant chaque jour,<br/>L''écho de voix ardentes,<br/>Qui crient : « Dieu est amour ! »<br/>',NULL,27041,3);
INSERT INTO stanza VALUES('FR9','1','Père, Ton Fils en nous veut Te louer,<br/>Nous voici, unis à Ton Bien-aimé,<br/>De Lui remplis, nous entonnons ce chant,<br/>Pour publier Ton nom dans l''assemblée.<br/>',NULL,27042,1);
INSERT INTO stanza VALUES('FR9','2','Père, sans Toi nous sommes sans amour,<br/>Toi seul es digne de notre affection.<br/>Te connaissant, ô Toi, le seul vrai Dieu,<br/>Nous chérissons Ta vie, suprême don !<br/>',NULL,27043,2);
INSERT INTO stanza VALUES('FR9','3','Père, en nous Ton amour grandit toujours,<br/>Bien au-dessus de tous nos liens humains.<br/>Ce tendre amour est puissant dans nos cœurs,<br/>Pour nous conduire à vivre dans Ton sein.<br/>',NULL,27044,3);
INSERT INTO stanza VALUES('FR9','4','Père, en Ton Fils, nous Te rendons honneur,<br/>Nous célébrons, joyeux, Ton nom glorieux.<br/>Que Tu es saint, juste et compatissant !<br/>Gloire à Toi sur la terre et dans les cieux !<br/>',NULL,27045,4);
INSERT INTO stanza VALUES('FR10','1','Père, pour Toi montent, dans Ta présence,<br/>De doux accents,<br/>Une réponse à Ton amour immense,<br/>De joyeux chants.<br/>Auprès de Toi, les objets de Ta grâce,<br/>Avec Ton Fils, ont une heureuse place.<br/>',NULL,27046,1);
INSERT INTO stanza VALUES('FR10','2','C''est une scène où l''allégresse est sainte,<br/>Où tout répond<br/>À Ton amour, donnant sous Ton étreinte.<br/>Gloire à Ton nom.<br/>Dans Ton repos, ceint de splendeur suprême,<br/>C''est Ton cher Fils qui la louange mène.<br/>',NULL,27047,2);
INSERT INTO stanza VALUES('FR10','3','Et quel plaisir cette louange donne,<br/>Père à Ton cœur !<br/>Nous nous joignons à ce chant qu'' Il entonne<br/>En Ton honneur.<br/>Oui, Tu L''aimais avant que fut le monde,<br/>Et près de Lui, notre joie est profonde.<br/>',NULL,27048,3);
INSERT INTO stanza VALUES('FR11','1','Ô Dieu et Père, à Toi gloire et honneur !<br/>Qui plus que Toi devrait être loué ?<br/>Car Tu recherches des adorateurs,<br/>Qui Te louent en esprit, en vérité.<br/>',NULL,27049,1);
INSERT INTO stanza VALUES('FR11','2','Père, en Ton Fils, Tu créas l''univers.<br/>Tout subsiste en Sa puissance infinie.<br/>Que Tu es digne d''être célébré,<br/>Car nous pouvons venir à Toi par Lui !<br/>',NULL,27050,2);
INSERT INTO stanza VALUES('FR11','3','Dans l''assemblée, Il chante Tes vertus,<br/>Et dans la sphère bénie nous conduit.<br/>De Ton cher Fils nous sommes revêtus,<br/>Tu nous reçois, oh ! Quelle joie pour Lui !<br/>',NULL,27051,3);
INSERT INTO stanza VALUES('FR11','4','Unis par Lui, nous chantons notre joie !<br/>Tu es, cher Père, vraiment satisfait.<br/>Dans nos louanges, Tu entends Sa voix<br/>Et Ta demeure est en nous à jamais.<br/>',NULL,27052,4);
INSERT INTO stanza VALUES('FR12','1','Ô Dieu et Père, nous nous approchons,<br/>Grâce au précieux, précieux sang du Sauveur.<br/>Tout près de Toi, toujours nous resterons,<br/>Nous T''adorons, Toi, notre Dieu et Père.<br/>',NULL,27053,1);
INSERT INTO stanza VALUES('FR12','2','Tous réunis, nous voulons présenter,<br/>Le doux parfum de Ton Fils bien-aimé.<br/>Nous apprécions la grâce illimitée,<br/>Que par Sa mort Il a pour nous donnée.<br/>',NULL,27054,2);
INSERT INTO stanza VALUES('FR12','3','Nous partageons Ta joie d''être avec Lui,<br/>Ton bon plaisir délecte notre cœur.<br/>Sa gloire brille au milieu de la nuit,<br/>Sur les ténèbres règne le Seigneur !<br/>',NULL,27055,3);
INSERT INTO stanza VALUES('FR12','4','Devant Ton trône nous nous inclinons,<br/>Nous contemplons l''objet de Ton amour.<br/>Unis à Lui, ensemble nous chantons :<br/>À Lui l''honneur, la gloire pour toujours !<br/>',NULL,27056,4);
INSERT INTO stanza VALUES('FR13','1','Ton nom, ô Jésus, est si doux<br/>Pour tous Tes enfants rachetés !<br/>Il calme les tourments en nous,<br/>Guérit toutes nos plaies.<br/>Guérit toutes nos plaies.<br/>Guérit toutes nos plaies.<br/>Il calme les tourments en nous,<br/>Guérit toutes nos plaies.<br/>',NULL,27057,1);
INSERT INTO stanza VALUES('FR13','2','Ce beau nom fortifie l''esprit,<br/>Apaise le cœur oppressé.<br/>Il est la manne qui nourrit,<br/>La paix des opprimés.<br/>La paix des opprimés.<br/>La paix des opprimés.<br/>Il est la manne qui nourrit,<br/>La paix des opprimés.<br/>',NULL,27058,2);
INSERT INTO stanza VALUES('FR13','3','Ton nom est notre fondement,<br/>Un roc puissant, un bouclier.<br/>Il est ce trésor abondant,<br/>La grâce en vérité.<br/>La grâce en vérité.<br/>La grâce en vérité.<br/>Il est ce trésor abondant,<br/>La grâce en vérité.<br/>',NULL,27059,3);
INSERT INTO stanza VALUES('FR13','4','Jésus, Sauveur, Pasteur, Ami,<br/>Prophète, Sacrificateur,<br/>Tu es le Chemin et La vie.<br/>Nous Te louons, Seigneur !<br/>Nous Te louons, Seigneur !<br/>Nous Te louons, Seigneur !<br/>Tu es le Chemin et La vie.<br/>Nous Te louons, Seigneur !<br/>',NULL,27060,4);
INSERT INTO stanza VALUES('FR13','5','Combien sont vains tous nos efforts<br/>Et rares nos désirs ardents.<br/>Nous T''admirons, toi, vrai trésor,<br/>Et Tu nous rends brulants !<br/>Et Tu nous rends brulants !<br/>Et Tu nous rends brulants !<br/>Nous T''admirons, toi, vrai trésor,<br/>Et Tu nous rends brulants !<br/>',NULL,27061,5);
INSERT INTO stanza VALUES('FR13','6','Nous publierons Ton grand amour,<br/>À chaque instant de notre vie.<br/>En Toi, nous vaincrons tous les jours,<br/>Ton nom nous affranchit !<br/>Ton nom nous affranchit !<br/>Ton nom nous affranchit !<br/>En Toi, nous vaincrons tous les jours,<br/>Ton nom nous affranchit !<br/>',NULL,27062,6);
INSERT INTO stanza VALUES('FR14','1','Nom de gloire et de puissance !<br/>Mon abri, ma protection !<br/>Ô Jésus, que je T''adore !<br/>La victoire est dans Ton nom.<br/>',NULL,27063,1);
INSERT INTO stanza VALUES('FR14','2','Nom puissant : Jésus, Mon Sauveur !<br/>Tout mon bien je trouve en Lui.<br/>Respirant ce nom si tendre,<br/>Je reçois en moi la vie !<br/>',NULL,27064,2);
INSERT INTO stanza VALUES('FR14','3','Nom béni et nom qui sauve,<br/>Sur la terre et dans les cieux !<br/>Les pécheurs que Tu rachètes,<br/>Sentent Son parfum précieux.<br/>',NULL,27065,3);
INSERT INTO stanza VALUES('FR14','4','C''est Ton nom : « Jésus », j''aime - Baume dans nos afflictions !<br/>En Ton nom est la victoire.<br/>Cher Seigneur nous T''attendons.<br/>',NULL,27066,4);
INSERT INTO stanza VALUES('FR15','1','Ton nom, Jésus, est un parfum.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Ton nom, Jésus, est un parfum.<br/>Ton nom, Jésus, est un parfum.<br/>',NULL,27067,1);
INSERT INTO stanza VALUES('FR15','2','Les vierges, Jésus, T''aiment tant.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Les vierges, Jésus, T''aiment tant.<br/>Les vierges, Jésus, T''aiment tant.<br/>',NULL,27068,2);
INSERT INTO stanza VALUES('FR15','3','Tous, nous célébrons Ton amour.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Tous, nous célébrons Ton amour.<br/>Tous, nous célébrons Ton amour.<br/>',NULL,27069,3);
INSERT INTO stanza VALUES('FR15','4','Entraine-moi et nous courrons.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Entraine-moi et nous courrons.<br/>Entraine-moi et nous courrons.<br/>',NULL,27070,4);
INSERT INTO stanza VALUES('FR15','5','Oh ! que Tu es beau, Bien-aimé.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Oh ! que Tu es beau, Bien-aimé.<br/>Oh ! que Tu es beau, Bien-aimé.<br/>',NULL,27071,5);
INSERT INTO stanza VALUES('FR15','6','J''ai retrouvé Celui que j''aime.<br/>Jésus, Jésus, Jésus, Jésus,<br/>J''ai retrouvé Celui que j''aime.<br/>J''ai retrouvé Celui que j''aime.<br/>',NULL,27072,6);
INSERT INTO stanza VALUES('FR15','7','Mon cœur ne veut plus Te lâcher.<br/>Jésus, Jésus, Jésus, Jésus,<br/>Mon cœur ne veut plus Te lâcher.<br/>Mon cœur ne veut plus Te lâcher.<br/>',NULL,27073,7);
INSERT INTO stanza VALUES('FR15','8','Reviens, Bien-aimé, oh ! reviens !<br/>Jésus, Jésus, Jésus, Jésus,<br/>Reviens, Bien-aimé, oh ! reviens !<br/>Reviens, Bien-aimé, oh ! reviens !<br/>',NULL,27074,8);
INSERT INTO stanza VALUES('FR15','9','De tout notre cœur, nous T''aimons.<br/>Jésus, Jésus, Jésus, Jésus,<br/>De tout notre cœur, nous T''aimons.<br/>De tout notre cœur, nous T''aimons.<br/>',NULL,27075,9);
INSERT INTO stanza VALUES('FR16','1','Son nom est « merveilleux »,<br/>Son nom : le « conseiller »,<br/>Il est le « Dieu puissant »,<br/>Jésus mon Dieu !<br/>L''enfant divin est né,<br/>Le Fils nous est donné,<br/>Son nom : « Père éternel »,<br/>« Prince de paix ».<br/>Dieu que j''adore,<br/>Devint un homme,<br/>En nous vit Son Esprit !<br/>Viens et célèbre-Le !<br/>Aime et adore-Le !<br/>Il est le grand Sauveur,<br/>Jésus mon Dieu !<br/>',NULL,27076,1);
INSERT INTO stanza VALUES('FR17','1','Quittant Sa gloire,<br/>Sphère inapprochable,<br/>Dieu le Tout-puissant vint,<br/>Jésus, le Fils divin.<br/>Né dans l''étable,<br/>Comme un misérable,<br/>Il a été maltraité, opprimé.<br/>',NULL,27077,1);
INSERT INTO stanza VALUES('FR17','chorus','Oh ! que je L''aime, que je L''adore !<br/>Lumière, vie et salut complet.<br/>Le Créateur, Il devint mon Sauveur :<br/>Dieu révélé dans l''humanité.<br/>',NULL,27078,2);
INSERT INTO stanza VALUES('FR17','2','Il devint homme<br/>Et même un esclave.<br/>Il a payé le prix,<br/>Donnant pour moi Sa vie.<br/>Dieu, dans Sa grandeur,<br/>A quitté Sa splendeur,<br/>Pour me chercher afin de me sauver.<br/>',NULL,27079,3);
INSERT INTO stanza VALUES('FR17','3','Il s''est abaissé,<br/>Il a été brisé,<br/>Pour nos iniquités,<br/>Afin de nous gagner.<br/>Qui peut comprendre<br/>Ce glorieux mystère ?<br/>Je sais Seigneur, Tu es le grand : « Je Suis » !<br/>',NULL,27080,4);
INSERT INTO stanza VALUES('FR18','1','Bien qu''étant Dieu glorieux, exalté,<br/>De nous dans la chair, Tu t''es approché<br/>Devenant ainsi Seigneur, un homme humble.<br/>Je me souviens de Toi.<br/>',NULL,27081,1);
INSERT INTO stanza VALUES('FR18','2','La gloire de Dieu fut dissimulée,<br/>Pour sous la tente de chair demeurer,<br/>Sans apparente beauté à montrer.<br/>Je me souviens de Toi.<br/>',NULL,27082,2);
INSERT INTO stanza VALUES('FR18','3','Toi, la racine de terre asséchée,<br/>Tu fus aussi attristé, affligé,<br/>Étant un homme haï et méprisé.<br/>Je me souviens de Toi.<br/>',NULL,27083,3);
INSERT INTO stanza VALUES('FR18','4','Ton cœur est doux, rempli d''humilité,<br/>À souffrir de toutes parts, disposé,<br/>À l''homme, à Dieu, ne se plaignant jamais.<br/>Je me souviens de Toi.<br/>',NULL,27084,4);
INSERT INTO stanza VALUES('FR18','5','Tendre et si doux dans Ton humanité,<br/>En toutes choses, complet, mesuré ;<br/>Oblation devant le Père acceptée.<br/>Je me souviens de Toi.<br/>',NULL,27085,5);
INSERT INTO stanza VALUES('FR18','6','Faire le vœu de Ton Père est Ta joie.<br/>Tu rejetas de Satan, tout mensonge.<br/>Qui, à part Toi, est fidèle et si sage ?<br/>Je me souviens de Toi.<br/>',NULL,27086,6);
INSERT INTO stanza VALUES('FR18','7','Faisant toujours de Dieu la volonté,<br/>Tu te plias aux souffrances, à la mort.<br/>Tu pris ma place, à la croix fus cloué.<br/>Je me souviens de Toi.<br/>',NULL,27087,7);
INSERT INTO stanza VALUES('FR18','8','Le Père, pour tout ceci T''exalta,<br/>La gloire et la majesté T''octroya ;<br/>La terre et les cieux plieront le genou.<br/>Nous T''adorons Seigneur !<br/>',NULL,27088,8);
INSERT INTO stanza VALUES('FR19','1','Seigneur, Tu ressuscitas, Alléluia !<br/>Du Hadès Tu échappas, Alléluia !<br/>Ressuscités avec Lui, Alléluia !<br/>Louons le Prince de vie, Alléluia !<br/>',NULL,27089,1);
INSERT INTO stanza VALUES('FR19','2','Notre Roi, le Christ vivant, Alléluia !<br/>A détruit la mort, Satan. Alléluia !<br/>Jésus-Christ a triomphé, Alléluia !<br/>Il a tout mis sous Ses pieds. Alléluia !<br/>',NULL,27090,2);
INSERT INTO stanza VALUES('FR19','3','Les pécheurs sont rachetés, Alléluia !<br/>Anéanti le péché, Alléluia !<br/>De l''esclavage affranchis, Alléluia !<br/>Vivons maintenant par Lui ! Alléluia !<br/>',NULL,27091,3);
INSERT INTO stanza VALUES('FR19','4','Purs de cœur, forts en esprit, Alléluia !<br/>Nous voulons être bâtis, Alléluia !<br/>Dans la vie nous édifions, Alléluia !<br/>Pierres vives, Sa maison. Alléluia !<br/>',NULL,27092,4);
INSERT INTO stanza VALUES('FR20','1','À Toi la gloire, Christ ressuscité !<br/>À Toi la victoire pour l''éternité !<br/>Brillant de lumière, l''ange est descendu,<br/>Il roule la pierre du tombeau vaincu.<br/>',NULL,27093,1);
INSERT INTO stanza VALUES('FR20','chorus','À Toi la gloire, Christ ressuscité !<br/>Â Toi la victoire pour l''éternité !<br/>',NULL,27094,2);
INSERT INTO stanza VALUES('FR20','2','Vois-Le paraitre, c''est Lui, c''est Jésus,<br/>Ton Sauveur, Ton Maitre ! Non, ne doute plus !<br/>Sois dans l''allégresse, peuple du Seigneur,<br/>Et redis sans cesse que Christ est vainqueur !<br/>',NULL,27095,3);
INSERT INTO stanza VALUES('FR21','1','Christ est ressuscité,<br/>Qu''en des joyeux chants,<br/>Soit toujours exalté<br/>Son nom puissant !<br/>',NULL,27096,1);
INSERT INTO stanza VALUES('FR21','chorus','À Toi la gloire et l''honneur,<br/>Ô Sauveur, ô Rédempteur puissant !<br/>Du sépulcre Tu sortis vainqueur,<br/>Tu vis, régnant avec Tes saints maintenant !<br/>Gloire à Toi ! Gloire à Toi !<br/>À jamais, oh ! Gloire à Toi !<br/>',NULL,27097,2);
INSERT INTO stanza VALUES('FR21','2','Christ est ressuscité !<br/>Cherche en Lui toujours,<br/>Ô peuple racheté,<br/>Force et secours !<br/>',NULL,27098,3);
INSERT INTO stanza VALUES('FR21','3','Christ est ressuscité,<br/>Par Lui nous vivons,<br/>Et dans l''éternité,<br/>nous régnerons !<br/>',NULL,27099,4);
INSERT INTO stanza VALUES('FR22','1','Louons, louons, Christ le Vainqueur !<br/>Il remporta la victoire !<br/>Plus de péché, plus de vieil homme,<br/>Mais la pleine rédemption.<br/>Vaincues sont les forces du mal,<br/>Oh ! quel triomphe à la croix !<br/>',NULL,27100,1);
INSERT INTO stanza VALUES('FR22','2','Chantons : Christ est ressuscité !<br/>Dieu L''a relevé des morts.<br/>Pour toujours la mort est vaincue,<br/>L''homme est rendu à la vie.<br/>L''enfer trembla, tout s''écroula,<br/>Christ manifesta Sa gloire.<br/>',NULL,27101,2);
INSERT INTO stanza VALUES('FR22','3','Dieu a élevé Jésus-Christ,<br/>Il L''a placé sur le trône.<br/>Au- dessus de toute puissance,<br/>Il a été fait Seigneur.<br/>Dieu a tout placé sous Ses pieds,<br/>Tout pouvoir Lui a donné.<br/>',NULL,27102,3);
INSERT INTO stanza VALUES('FR22','4','Alléluia, Christ est vainqueur !<br/>Il triompha au Calvaire.<br/>Alléluia, ressuscité,<br/>Il publia Sa victoire !<br/>Élevé par Dieu, Il règne :<br/>Pour toujours Il est le Roi !<br/>',NULL,27103,4);
INSERT INTO stanza VALUES('FR23','1','Dans les cieux, un homme règne,<br/>C''est Jésus-Christ , le Seigneur !<br/>Couronné par Dieu le Père,<br/>Il reçoit gloire et honneur.<br/>',NULL,27104,1);
INSERT INTO stanza VALUES('FR23','2','Dieu devint un jour un homme,<br/>Jésus mourut pour Son plan.<br/>Mais Son corps quitta la tombe,<br/>Christ aux cieux monta vivant.<br/>',NULL,27105,2);
INSERT INTO stanza VALUES('FR23','3','Quand Jésus vint sur la terre,<br/>Dieu en Lui s''est abaissé,<br/>Élevé au ciel en gloire,<br/>L''homme en Lui fut exalté.<br/>',NULL,27106,3);
INSERT INTO stanza VALUES('FR23','4','Il est Dieu uni à l''homme,<br/>Dieu en Lui s''est incarné,<br/>Dieu en l''homme se révèle,<br/>L''homme en Dieu est glorifié.<br/>',NULL,27107,4);
INSERT INTO stanza VALUES('FR23','5','Dans le ciel, le Fils en gloire<br/>Envoya l''Esprit de vie<br/>Qui proclame Sa Personne<br/>Et ce qu''Il a accompli.<br/>',NULL,27108,5);
INSERT INTO stanza VALUES('FR23','6','Au Fils qui est sur le trône<br/>L''église est identifiée.<br/>Par l''Esprit du Fils de l''homme,<br/>Tous les saints sont édifiés.<br/>',NULL,27109,6);
INSERT INTO stanza VALUES('FR23','7','Dans les cieux un homme règne,<br/>C''est Jésus-Christ, le Sauveur.<br/>À jamais empreint de gloire,<br/>Il est couronné Seigneur.<br/>',NULL,27110,7);
INSERT INTO stanza VALUES('FR24','1','Gloire à Lui ! Oui, Gloire à jamais !<br/>À Jésus, l''Agneau de Dieu !<br/>Gloire à Lui ! Oui, Gloire à jamais !<br/>Chantons haut Son nom précieux !<br/>Nom plus grand que tous les autres,<br/>Sur la terre et dans les cieux !<br/>Gloire à Lui ! Oui, Gloire à jamais !<br/>Au grand Roi, gloire en tous lieux !<br/>',NULL,27111,1);
INSERT INTO stanza VALUES('FR24','2','Lui, Prince glorieux dans les cieux,<br/>Dieu L''établit pour régner.<br/>Et en très humble serviteur,<br/>Son Père Il a satisfait.<br/>Par Sa force inébranlable,<br/>Dans la honte de la croix,<br/>Il servit jusqu''à en mourir,<br/>Dans son amour, fit ce choix.<br/>',NULL,27112,2);
INSERT INTO stanza VALUES('FR24','3','Que de gloire et que de beauté<br/>L'' Humilié est couronné !<br/>Et que la robe de splendeur<br/>À Lui seul soit destinée !<br/>Que tous les genoux fléchissent,<br/>Que Son nom soit confessé !<br/>Maitre ici comme dans les cieux,<br/>Qu'' Il soit toujours élevé !<br/>',NULL,27113,3);
INSERT INTO stanza VALUES('FR24','4','Gloire à Lui ! Oui, Gloire à jamais !<br/>Qui prétend donc L''égaler ?<br/>Que sur la terre et dans les cieux,<br/>Le grand Roi soit adoré !<br/>Gloire au grand « Je Suis » qui règne !<br/>Gloire à Lui, le seul vrai Dieu !<br/>Gloire à Lui ! Oui, Gloire à jamais !<br/>À l''Agneau qui règne aux cieux !<br/>',NULL,27114,4);
INSERT INTO stanza VALUES('FR25','1','Jésus ! Chantons Son nom puissant !<br/>Tombons tous à Ses pieds,<br/>Tombons tous à Ses pieds,<br/>Couronnons-Le royalement !<br/>',NULL,27115,1);
INSERT INTO stanza VALUES('FR25','chorus','Qu'' Il règne, Lui,<br/>Qu'' Il règne, Jésus !<br/>Jésus ! Jésus ! Jésus !<br/>Qu'' Il règne, le Seigneur !<br/>',NULL,27116,2);
INSERT INTO stanza VALUES('FR25','2','Toi Israël, semence élue,<br/>À Dieu réconcilié,<br/>À Dieu réconcilié,<br/>Sa grâce vint pour ton salut.<br/>',NULL,27117,3);
INSERT INTO stanza VALUES('FR25','3','Pécheur, n''oublie jamais Sa croix,<br/>Son sang, Son agonie,<br/>Son sang, Son agonie,<br/>Apporte à Ses pieds tes trophées.<br/>',NULL,27118,4);
INSERT INTO stanza VALUES('FR25','4','De chaque peuple et des nations,<br/>Sur terre réunis,<br/>Sur terre réunis,<br/>Que Dieu reçoive adoration !<br/>',NULL,27119,5);
INSERT INTO stanza VALUES('FR25','5','À cette multitude joints,<br/>Tombons tous à Ses pieds,<br/>Tombons tous à Ses pieds,<br/>Chantons la gloire du Dieu saint !<br/>',NULL,27120,6);
INSERT INTO stanza VALUES('FR26','1','Couronnez-Le d''honneur !<br/>Lui, l''Agneau sur le trône,<br/>Entonnez de tout votre cœur,<br/>Les hymnes du royaume.<br/>Réveille-toi mon âme,<br/>Pour chanter ton Sauveur !<br/>Ton Roi incomparable acclame,<br/>Lui, le Triomphateur.<br/>',NULL,27121,1);
INSERT INTO stanza VALUES('FR26','2','Couronnez-Le de gloire !<br/>Lui, Fils né d''une femme,<br/>Vois la couronne de victoire,<br/>Qui Son triomphe acclame.<br/>Voyez le Victorieux,<br/>Présentant le trophée.<br/>Il l''acquit par Son sang précieux<br/>Et en est couronné.<br/>',NULL,27122,2);
INSERT INTO stanza VALUES('FR26','3','Couronnez le Seigneur !<br/>Lui, qui nous a aimés,<br/>Fut brisé comme un malfaiteur<br/>Puis par Dieu élevé.<br/>Les anges dans les cieux<br/>Ne saisiront jamais,<br/>L''amour profond et mystérieux<br/>Qui nous a rachetés.<br/>',NULL,27123,3);
INSERT INTO stanza VALUES('FR26','4','Couronnez le Seigneur !<br/>Le prince de la paix,<br/>Puissant, Il règne avec splendeur,<br/>Soumet toute la terre,<br/>Pour que les guerres cessent,<br/>S''achève Son dessein<br/>Et que Son royaume apparaisse.<br/>Il n''aura pas de fin.<br/>',NULL,27124,4);
INSERT INTO stanza VALUES('FR26','5','Couronnez le Seigneur !<br/>Voyez l''Ancien des jours,<br/>De l''univers le Créateur,<br/>Souverain pour toujours !<br/>Nous T''acclamons, Sauveur,<br/>Pour Ton si grand amour,<br/>À Toi la louange et l''honneur !<br/>Toi, notre Rédempteur.<br/>',NULL,27125,5);
INSERT INTO stanza VALUES('FR27','1','Combien Ton amour est vaste !<br/>Oh ! Seigneur, qu''il est puissant !<br/>Mystérieux et insondable,<br/>Plus profond qu''un océan !<br/>C''est pour moi, dans la souffrance,<br/>Qu''à la croix Tu T''es donné,<br/>Pour qu''à Toi je participe,<br/>Que sur Toi, je sois greffé.<br/>',NULL,27126,1);
INSERT INTO stanza VALUES('FR27','2','Qui peut dire les merveilles,<br/>Que fait naitre Ton amour ?<br/>Voici le plus grand miracle :<br/>Dieu s''incarna pour toujours.<br/>Ton amour m''approvisionne<br/>Des richesses de Ta vie.<br/>Je prends part à Ta nature,<br/>De Ta grâce je jouis.<br/>',NULL,27127,2);
INSERT INTO stanza VALUES('FR27','3','Ton amour, Seigneur, nous parle<br/>De Ton glorieux plan divin,<br/>Et sur terre, il harmonise<br/>Ma vie avec Ton dessein.<br/>Oh ! ce don de vie me comble<br/>De tous Tes nombreux bienfait !<br/>Tes faveurs, Seigneur, me gagnent,<br/>Ta douceur je goûterai.<br/>',NULL,27128,3);
INSERT INTO stanza VALUES('FR27','4','Qui pourrait, de Toi qui m''aimes,<br/>Ô Seigneur ! me séparer ?<br/>Ta nature si parfaite,<br/>À mon être est mélangée ;<br/>Et telle une seule plante,<br/>Je suis Tien et Tu es mien.<br/>C''est pourquoi, partout je chante :<br/>« Par amour, je T''appartiens ! »<br/>',NULL,27129,4);
INSERT INTO stanza VALUES('FR28','1','Quelle faveurs Ton grand amour exprime !<br/>Il est plus haut que la plus haute cime<br/>Et que l''azur insondable des cieux.<br/>Je veux, Seigneur, vers cet amour sublime<br/>Lever les yeux.<br/>',NULL,27130,1);
INSERT INTO stanza VALUES('FR28','2','Il est si grand ! Je ne puis le comprendre.<br/>Mais qu''ici-bas, ma voix se fasse entendre<br/>Et que mon cœur, par l''amour soulevé,<br/>Chante aujourd''hui l''amour tendre et puissant<br/>Qui m''a sauvé !<br/>',NULL,27131,2);
INSERT INTO stanza VALUES('FR28','3','Oh ! quel amour ! Il m''entoure, il m''inonde.<br/>C''est une mer calme, pure et profond<br/>Qui se déroule aux regards de ma foi.<br/>Vaste océan, que murmure ton onde ?<br/>Pour toi, pour toi !<br/>',NULL,27132,3);
INSERT INTO stanza VALUES('FR28','4','Oui, c''est pour moi : je le crois et j''adore.<br/>Jésus, Sauveur, qu''il retentisse encore,<br/>Ce mot divin, ce mot de Ton amour !<br/>Redis-le-moi jusqu''à la proche aurore<br/>De Ton retour.<br/>',NULL,27133,4);
INSERT INTO stanza VALUES('FR28','5','Je suis si vide : ni une pensée,<br/>Ni un regard d''amour ne T''ai donné.<br/>Pourtant, à Toi je reviens et je lance<br/>L''appel afin que Tu viennes et me dises :<br/>« Oh ! que je T''aime ! »<br/>',NULL,27134,5);
INSERT INTO stanza VALUES('FR28','6','Oh ! rempli-moi d''amour Jésus, Sauveur !<br/>Conduis-moi à la fontaine divine.<br/>Je m''y approcherai par simple foi.<br/>Toute autre source j''ai abandonnée,<br/>Je n''ai que Toi.<br/>',NULL,27135,6);
INSERT INTO stanza VALUES('FR28','7','Lorsque, Seigneur, nous serons face à face<br/>Et sur Ton trône, nous serons assis,<br/>Toutes les dimensions de Ton amour<br/>Je chanterais ; ma louange infinie<br/>S''élèvera.<br/>',NULL,27136,7);
INSERT INTO stanza VALUES('FR29','1','De Dieu, Tu es l''image,<br/>Toi, le Fils bien-aimé.<br/>Tu es notre héritage,<br/>Grâce à Ton sang versé.<br/>La création entière<br/>T''acclame Premier-né ;<br/>Par Toi sont toutes choses<br/>Et tout T''est destiné.<br/>',NULL,27137,1);
INSERT INTO stanza VALUES('FR29','2','Tout être Tu précèdes<br/>Et tout subsiste en Toi.<br/>De tout Tu es le centre<br/>Et tout existe en Toi.<br/>Commencement unique<br/>Et Premier-né des morts,<br/>Tu règnes dans l''église,<br/>Tu édifies Ton Corps.<br/>',NULL,27138,2);
INSERT INTO stanza VALUES('FR29','3','Combien la plénitude<br/>S''est plut à être en Toi ;<br/>Prends la première place,<br/>En tout sois notre choix !<br/>Par Ton sang, toutes choses<br/>Tu voulus racheter.<br/>À Dieu Tu nous présentes<br/>Sans tache et sanctifiés.<br/>',NULL,27139,3);
INSERT INTO stanza VALUES('FR29','4','En Toi est le mystère<br/>De la divinité.<br/>Sagesse et connaissance<br/>En Toi sont révélées.<br/>Espérance de gloire,<br/>Tu vis, grandis en nous,<br/>Toujours nous perfectionnes,<br/>Qu''à Dieu nous donnions tout.<br/>',NULL,27140,4);
INSERT INTO stanza VALUES('FR29','5','Tout l''univers est l''ombre<br/>De Ta réalité.<br/>Tu veux que l''on Te gagne<br/>Pour être en Toi fondés.<br/>Nous goûtons Tes richesses,<br/>Nous attachant à Toi.<br/>Ainsi le nouvel homme,<br/>Ton Corps, se former et croit.<br/>',NULL,27141,5);
INSERT INTO stanza VALUES('FR29','6','Cachés en Dieu le Père,<br/>Nous vivons avec Toi.<br/>Ta paix en nous préside,<br/>Met fin à nos combats.<br/>Tu sauves tous Tes membres,<br/>Ta vie remplace tout,<br/>Et quant au nouvel homme,<br/>Là, Tu es tout en tous.<br/>',NULL,27142,6);
INSERT INTO stanza VALUES('FR30','1','Jésus, nous portons les regards<br/>Sur Toi, l''objet de nos désirs.<br/>Tu es si riche et merveilleux,<br/>Toi seul nos cœurs as su ravir !<br/>',NULL,27143,1);
INSERT INTO stanza VALUES('FR30','chorus','Nos cœurs débordent de louanges !<br/>Tu pourvois à tous nos besoins,<br/>Tous nos désirs, Seigneur, Tu combles,<br/>Toujours, Tu es notre soutien !<br/>',NULL,27144,2);
INSERT INTO stanza VALUES('FR30','2','Tu es seul véritable et saint,<br/>Le Dieu de justice et de vie.<br/>Dieu de lumière et Dieu d''amour,<br/>Le Dieu qui notre cœur ravit !<br/>',NULL,27145,3);
INSERT INTO stanza VALUES('FR30','3','Tu es aussi un homme vrai,<br/>Un homme intègre, pur et droit,<br/>Le Bien-aimé, l''élu de Dieu,<br/>Qui notre amour ardent reçoit.<br/>',NULL,27146,4);
INSERT INTO stanza VALUES('FR30','4','Comme un esclave Tu vécus,<br/>Venu de Dieu pour nous servir.<br/>Obéissant jusqu''à la croix,<br/>Tu mourus pour nous affranchir.<br/>',NULL,27147,5);
INSERT INTO stanza VALUES('FR30','5','Tu es, Seigneur, le Roi des rois<br/>Régnant dans l''amour et la vie.<br/>De la puissance revêtu,<br/>Tu vis en nous, Tu nous conduis.<br/>',NULL,27148,6);
INSERT INTO stanza VALUES('FR30','6','Qu''il est précieux le souvenir,<br/>De tout ce que Tu es pour nous !<br/>Les vrais trésors sont tous en Toi,<br/>Nous T''attendons, glorieux époux !<br/>',NULL,27149,7);
INSERT INTO stanza VALUES('FR31','1','Oh ! Semence de la femme !<br/>Dans Ta chair, Tu pris le blâme,<br/>Tu remportas la victoire<br/>Et écrasas l''ennemi.<br/>Tu es le vrai Dieu incarné,<br/>Au sang, la chair, Tu pris part.<br/>Les liens de la mort Tu brisas,<br/>Tu anéantis le diable.<br/>',NULL,27150,1);
INSERT INTO stanza VALUES('FR31','2','Toi, d''Abraham la Semence,<br/>Tu vins selon la promesse,<br/>Afin que les peuples sur terre,<br/>Ta bénédiction reçoivent.<br/>Tu as précédé Abraham,<br/>Car Tu es le grand « Je Suis » .<br/>Tu fus pourtant son rejeton<br/>Et devins l''Agneau promis.<br/>',NULL,27151,2);
INSERT INTO stanza VALUES('FR31','3','Toi, de David la Semence<br/>Germinée pour le royaume.<br/>Pour qu''à Dieu revienne la gloire,<br/>Tu fus placé sur le trône.<br/>David T''appela « mon Seigneur » ,<br/>Toi, qui fus son rejeton ;<br/>Car Seigneur, Tu es le premier<br/>Et le dernier en tout temps.<br/>',NULL,27152,3);
INSERT INTO stanza VALUES('FR31','4','« Un enfant » de nature humaine,<br/>Est appelé « Dieu puissant ».<br/>« Un Fils » nous a été donné,<br/>« Père éternel » est Son nom.<br/>Toutes les promesses de Dieu<br/>Sont accomplies en Toi seul,<br/>Toi le contenu, l''objectif<br/>De toute bénédiction.<br/>',NULL,27153,4);
INSERT INTO stanza VALUES('FR32','1','Seigneur Tu es la source,<br/>Où je goûte la vie.<br/>Ton fleuve me libère,<br/>Des peines, des conflits.<br/>Et Ta miséricorde<br/>Est comme un océan.<br/>Partout je vois Ta grâce,<br/>Sagesse de Ton plan !<br/>',NULL,27154,1);
INSERT INTO stanza VALUES('FR32','2','Je suis à Toi qui m''aimes,<br/>Qui me tiens par la main.<br/>Un vil pécheur Tu mènes<br/>À la maison du vin.<br/>Fondé sur Tes mérites,<br/>Je n''ai pas d''autre appui.<br/>Caché dans Ta présence,<br/>C''est par Toi que je vis.<br/>',NULL,27155,2);
INSERT INTO stanza VALUES('FR32','3','L''épouse ne contemple,<br/>Que son si cher époux.<br/>Ne cherchant plus ma gloire,<br/>Je veux mon Roi si doux,<br/>Qu''importe mon salaire,<br/>Je vois Ses mains percées.<br/>L'' Agneau seul est ma gloire,<br/>Pour toute éternité !<br/>',NULL,27156,3);
INSERT INTO stanza VALUES('FR33','1','Quand nous pensons à Toi Seigneur,<br/>À Ton amour, Ta grâce,<br/>Le désir brule en notre cœur<br/>De Te voir face à face.<br/>',NULL,27157,1);
INSERT INTO stanza VALUES('FR33','2','Quoique parfois lassés, chargés,<br/>Les Tiens, ici, cheminent<br/>En un lieu sec et désolé,<br/>Où ne croit que l''épine.<br/>',NULL,27158,2);
INSERT INTO stanza VALUES('FR33','3','Satisfaits pourtant, chaque jour,<br/>S''attachant à Ta trace.<br/>Ils peuvent chanter Ton amour<br/>Et célébrer Ta grâce.<br/>',NULL,27159,3);
INSERT INTO stanza VALUES('FR33','4','Toi, notre refuge et rocher,<br/>Repos, salut, justice ;<br/>De Toi, Seigneur, nous approcher,<br/>Fait tout notre délice.<br/>',NULL,27160,4);
INSERT INTO stanza VALUES('FR33','5','Sauveur béni qui nous soutient,<br/>Tu fortifies Tes saints,<br/>Jusqu''au jour où tous Tes vainqueurs,<br/>Contempleront Ta gloire.<br/>',NULL,27161,5);
INSERT INTO stanza VALUES('FR34','1','Jésus, Jésus, ô cher Seigneur,<br/>Pardonne si je dis,<br/>Par simple amour, Ton nom béni,<br/>Plus de mille fois par jour.<br/>',NULL,27162,1);
INSERT INTO stanza VALUES('FR34','chorus','Seigneur, demeure auprès de moi<br/>Pour que je me repose en Toi.<br/>Oui, Ton regard sera ma joie,<br/>Je T''aime cher Seigneur !<br/>',NULL,27163,2);
INSERT INTO stanza VALUES('FR34','2','Je T''aime tant que je ne puis<br/>Contenir mon amour.<br/>Ton feu ardent brule et consume<br/>Mon âme chaque jour.<br/>',NULL,27164,3);
INSERT INTO stanza VALUES('FR34','3','Tu es pour moi tout et en tous,<br/>Le désir de mon cœur,<br/>La pleine guérison de l''âme,<br/>La force de mon corps.<br/>',NULL,27165,4);
INSERT INTO stanza VALUES('FR34','4','Brule, ô Amour ! Brule et consume !<br/>Remplis mon cœur de Toi,<br/>Afin que tout amour terrestre,<br/>Soit consumé en moi.<br/>',NULL,27166,5);
INSERT INTO stanza VALUES('FR34','5','Tu es ma joie au sein des peines.<br/>Tu es inestimable :<br/>Éclat divin chassant la nuit,<br/>Oh ! trésor ineffable !<br/>',NULL,27167,6);
INSERT INTO stanza VALUES('FR34','6','Seigneur, Ta grâce surabonde,<br/>Ton amour est sans fin,<br/>De jour en jour il nous inonde,<br/>Jamais rien ne l''éteint.<br/>',NULL,27168,7);
INSERT INTO stanza VALUES('FR35','1','Ta table avec le pain , le vin,<br/>Nous contemplons, Seigneur.<br/>Par ces symboles nous voyons<br/>Le dessein de Ton cœur.<br/>',NULL,27169,1);
INSERT INTO stanza VALUES('FR35','2','Seigneur, Tu es le pain de vie,<br/>Qui descendit des cieux.<br/>Tu fus brisé pour Te donner,<br/>Tu es le pain de Dieu.<br/>',NULL,27170,2);
INSERT INTO stanza VALUES('FR35','3','La coupe est la portion de Dieu,<br/>Qui nous est accordée.<br/>Ce sang précieux nous qualifie,<br/>Pour nous L''approprier.<br/>',NULL,27171,3);
INSERT INTO stanza VALUES('FR35','4','Nous Te mangeons, oh ! Pain de vie !<br/>Nous souvenant de Toi.<br/>En prenant part à Tes richesses,<br/>Nous Te donnons la gloire.<br/>',NULL,27172,4);
INSERT INTO stanza VALUES('FR35','5','La coupe de bénédiction<br/>Nous en boirons avec joie.<br/>Nous en boirons jusqu''à ce jour,<br/>Où nous pourrons Te voir.<br/>',NULL,27173,5);
INSERT INTO stanza VALUES('FR35','6','Prenant part à ce doux festin,<br/>Ta mort nous proclamons<br/>Et témoignons de jour en jour<br/>De Toi, notre portion.<br/>',NULL,27174,6);
INSERT INTO stanza VALUES('FR35','7','Nous attendons le grand festin,<br/>Lorsque Tu reviendras.<br/>Nous mangerons, nous festoierons,<br/>Toujours devant Ta face !<br/>',NULL,27175,7);
INSERT INTO stanza VALUES('FR36','1','Cher Seigneur, Tu nous rassembles<br/>Par ce pain et par ce vin.<br/>Sur la table, Tu t''es donnes<br/>Comme un festin à Tes saints !<br/>Nous avons tous part au seul pain,<br/>Le symbole de Ton corps ;<br/>À la même coupe buvons<br/>Le sang versé à Ta mort !<br/>',NULL,27176,1);
INSERT INTO stanza VALUES('FR36','chorus','Quelle sainte table ! Symbole admirable !<br/>Elle est insondable et riche en significations !<br/>',NULL,27177,2);
INSERT INTO stanza VALUES('FR36','2','Grâce à Ton grand sacrifice,<br/>Tu peux nous donner la vie.<br/>Tu t''es même offert aux hommes,<br/>Tout Ton être nous nourrit.<br/>Réunis à cette table,<br/>De Ta mort nous témoignons.<br/>Nous mangeons, buvons Ton être,<br/>Cher Seigneur, nous T''adorons !<br/>',NULL,27178,3);
INSERT INTO stanza VALUES('FR36','3','Par ce pain qui représente<br/>Ton seul corps universel,<br/>Tous Tes membres communient<br/>En partage fraternel.<br/>Bénie soit la sainte coupe<br/>De Ton sang pour nous versé.<br/>Quelle communion glorieuse<br/>Avec tous Tes rachetés !<br/>',NULL,27179,4);
INSERT INTO stanza VALUES('FR36','4','Tu es notre portion riche,<br/>Qui nous comble chaque jour.<br/>Nous attendons Ton royaume,<br/>Voulons hâter Ton retour.<br/>À Ta venue dans Ton règne,<br/>Avec tous les saints vainqueurs,<br/>Nous serons Ta chère épouse,<br/>Qui réjouira Ton cœur !<br/>',NULL,27180,5);
INSERT INTO stanza VALUES('FR37','1','Seigneur, nous apprécions ce pain :<br/>Symbole saint, divin !<br/>Il nous révèle les mystères,<br/>De Ton précieux dessein.<br/>',NULL,27181,1);
INSERT INTO stanza VALUES('FR37','2','Ce pain décrit Ton corps physique<br/>Qui pour nous fut livré,<br/>Afin que nous ayons Ta vie,<br/>En prenant part à Toi.<br/>',NULL,27182,2);
INSERT INTO stanza VALUES('FR37','3','Ton corps pour nous tous, fut brisé<br/>Pour libérer la vie,<br/>Dans tous Tes saints la dispenser,<br/>Faisant d''eux Ton épouse.<br/>',NULL,27183,3);
INSERT INTO stanza VALUES('FR37','4','Ce pain unique représente<br/>Aussi Ton corps mystique.<br/>Nous sommes maintenant Tes membre,<br/>En tout pareils à Toi.<br/>',NULL,27184,4);
INSERT INTO stanza VALUES('FR37','5','Nous sommes tous des grains de blé,<br/>Qui forment un seul pain.<br/>Le souvenir de Ta personne<br/>Nous comble tous de joie !<br/>',NULL,27185,5);
INSERT INTO stanza VALUES('FR37','6','Nous prenons part au même pain<br/>Et Tu nous satisfais.<br/>Avec Tes saints en communion,<br/>Nous témoignons de Toi.<br/>',NULL,27186,6);
INSERT INTO stanza VALUES('FR38','1','En seul corps, ici, Tu nous rassemble.<br/>Quoique nombreux, nous vivons l''unité.<br/>Seule Ta vie en fait de nous les membres,<br/>Et nous sommes un, en Toi tous rassembles !<br/>',NULL,27187,1);
INSERT INTO stanza VALUES('FR38','chorus','Il y a un seul corps dans cet univers !<br/>Oh ! quelle joie de L''exprimer !<br/>Dans chaque ville brille un chandelier<br/>Pour déclarer notre unité !<br/>',NULL,27188,2);
INSERT INTO stanza VALUES('FR38','2','Étant tous un, nous mangeons à Ta table<br/>L''unique pain, symbole de Ton corps.<br/>Tu t''es rendu si proche et accessible<br/>Pour qu''en Toi, nous marchions d''un même accord.<br/>',NULL,27189,3);
INSERT INTO stanza VALUES('FR38','3','Tous réunis, buvons à cette coupe ;<br/>Ton sang versé, un jour, nous racheta !<br/>À chaque fois, ce repas nous annonce<br/>Que Tu mourus et que Tu reviendras.<br/>',NULL,27190,4);
INSERT INTO stanza VALUES('FR38','4','Tu nous unis malgré nos différences,<br/>Tu es, Seigneur, Toi-même notre paix.<br/>Chacun de nous à ce repas déclare<br/>Qu''il fait partie de Ton corps si parfait.<br/>',NULL,27191,5);
INSERT INTO stanza VALUES('FR38','5','Oh ! quelle joie ! En nous l''Esprit témoigne,<br/>Que Tu es satisfait Seigneur Jésus.<br/>Quel avant-goût des noces Tu nous donnes.<br/>Nous T''attendons, Seigneur et cher époux !<br/>',NULL,27192,6);
INSERT INTO stanza VALUES('FR39','1','Prends cette coupe et bois<br/>Le sang versé du Roi !<br/>Son coté fut percé,<br/>Sa vie Il a livré :<br/>La rédemption est accomplie !<br/>Par cette paix qu'' Il établit,<br/>Nous venons hardiment à Lui !<br/>',NULL,27193,1);
INSERT INTO stanza VALUES('FR39','2','Prends l''Agneau par la foi,<br/>Jésus est mort pour toi !<br/>Accours à Son festin,<br/>Prends le pain et le vin !<br/>Oui, à Sa table, mange et bois,<br/>Bénis la coupe et loue Ton Roi,<br/>Dieu dans l''Agneau - Oh ! quelle joie !<br/>',NULL,27194,2);
INSERT INTO stanza VALUES('FR39','3','Aurions-nous Son pardon<br/>Si pour nos transgressions,<br/>Nous devions sacrifier<br/>Des veaux et des béliers ?<br/>Le souvenir de nos péchés<br/>nous serait chaque an rappelé,<br/>Jamais il ne serait oté.<br/>',NULL,27195,3);
INSERT INTO stanza VALUES('FR39','4','Mais Christ s''est sacrifié,<br/>Sans tache et sans péché,<br/>La mort Il accepta<br/>Et ainsi nous sauva !<br/>Nous jouissons donc maintenant,<br/>De l''efficacité du sang<br/>Et prenons part au Dieu vivant !<br/>',NULL,27196,4);
INSERT INTO stanza VALUES('FR39','5','Son sang est efficace,<br/>Tout péché il efface.<br/>La conscience est lavée<br/>Et nous avons Sa paix.<br/>Nous appliquons ce précieux sang<br/>Dans notre marche à tout moment,<br/>Sa vie peut couler librement.<br/>',NULL,27197,5);
INSERT INTO stanza VALUES('FR40','1','Ô Seigneur, que Ta table est glorieuse !<br/>Rassemblant ici tous Tes saints,<br/>Tu as préparé ce festin.<br/>Ô Seigneur, que Ta table est glorieuse !<br/>',NULL,27198,1);
INSERT INTO stanza VALUES('FR40','chorus','Alléluia, alléluia !<br/>Alléluia, quel festin !<br/>Alléluia, alléluia !<br/>Ô Seigneur, que Ta table est glorieuse !<br/>',NULL,27199,2);
INSERT INTO stanza VALUES('FR40','2','Cette table nous remplit de joie,<br/>Quand nous communions autour d''elle.<br/>Nous l''avons trouvée, qu''elle est belle !<br/>Cette table nous remplit de joie !<br/>',NULL,27200,3);
INSERT INTO stanza VALUES('FR40','3','Ô Seigneur, Ta table nous est chère !<br/>Partageant Ton corps et Ton sang,<br/>Dans l''amour nous Te contemplons.<br/>Ô Seigneur, Ta table nous est chère !<br/>',NULL,27201,4);
INSERT INTO stanza VALUES('FR40','4','Ô Seigneur, Ta table est importante !<br/>Nous voyons Ton corps grâce au pain :<br/>En mangeant nous sommes tous un.<br/>Ô Seigneur, Ta table est importante !<br/>',NULL,27202,5);
INSERT INTO stanza VALUES('FR40','5','Ô Seigneur, Ta table est rassasie !<br/>Accessible de jour en jour,<br/>Tu nous satisfais pour toujours.<br/>Ô Seigneur, Ta table est rassasie !<br/>',NULL,27203,6);
INSERT INTO stanza VALUES('FR40','6','Cette table nous remplit d''espoir !<br/>L''espérance de Ton retour<br/>Affermit nos cœur dans l''amour.<br/>Cette table nous remplit d''espoir !<br/>',NULL,27204,7);
INSERT INTO stanza VALUES('FR41','1','Gloire et louange, puissance et honneur<br/>À Christ le Seigneur,<br/>L'' Agneau rédempteur !<br/>Force et richesse, sagesse et honneur<br/>À Christ, l''Agneau sauveur !<br/>',NULL,27205,1);
INSERT INTO stanza VALUES('FR41','chorus','Louons, louons !<br/>Prions Dieu, nous les croyants !<br/>Chantons, chantons :<br/>Jésus-Christ est vivant !<br/>Alléluia !<br/>',NULL,27206,2);
INSERT INTO stanza VALUES('FR41','2','Gloire et louange, puissance et honneur<br/>À Christ le Seigneur,<br/>L'' Agneau rédempteur !<br/>Force et richesse, sagesse et honneur<br/>À Christ, l''Agneau sauveur !<br/>',NULL,27207,3);
INSERT INTO stanza VALUES('FR42','1','Souffle sur nous Seigneur,<br/>Infuse-Toi en nous<br/>Et notre vie témoignera<br/>Que nos cœur soient lavés !<br/>',NULL,27208,1);
INSERT INTO stanza VALUES('FR42','2','Souffle sur nous Seigneur,<br/>Que nos cœurs soient lavés !<br/>Pour que nous choisissions Tes voies,<br/>Prends notre volonté !<br/>',NULL,27209,2);
INSERT INTO stanza VALUES('FR42','3','Souffle sur nous Seigneur,<br/>Pour que notre être entier<br/>Soit embrasé par Ton ardeur,<br/>Qu''il Te soit dévoué !<br/>',NULL,27210,3);
INSERT INTO stanza VALUES('FR42','4','Souffle sur nous Seigneur,<br/>Jamais nous ne mourrons !<br/>Sur le péché et sur la mort,<br/>Par Toi, nous régnerons !<br/>',NULL,27211,4);
INSERT INTO stanza VALUES('FR43','1','Ton Esprit est comme un souffle,<br/>Apprends-moi à L''inspirer.<br/>Je désire Te remettre<br/>Mes soucis et mes péchés.<br/>',NULL,27212,1);
INSERT INTO stanza VALUES('FR43','chorus','Oui, j''expire mes faiblesses<br/>Dieu de mon salut.<br/>Je T''inspire, en Toi je puise<br/>Toutes Tes vertus.<br/>',NULL,27213,2);
INSERT INTO stanza VALUES('FR43','2','e T''apporte tous mes besoins,<br/>Tu m''écoutes patiemment ;<br/>Je remets tout entre Tes mains,<br/>Tu me calmes tendrement.<br/>',NULL,27214,3);
INSERT INTO stanza VALUES('FR43','3','Je veux expirer mes peines,<br/>À Tes pieds, les déposer,<br/>Que Ton nom pour moi devienne,<br/>Joie et paix en vérité.<br/>',NULL,27215,4);
INSERT INTO stanza VALUES('FR43','4','Tu as pris sur Toi les fautes<br/>Que j''expire en T''invoquant.<br/>Je reçois Ta plénitude<br/>Chaque instant en T''inspirant.<br/>',NULL,27216,5);
INSERT INTO stanza VALUES('FR43','5','J''ai besoin de Tes richesses - Je suis tiède, indifférent.<br/>Je T''inspire, je Te laisse<br/>Rendre mon esprit ardent.<br/>',NULL,27217,6);
INSERT INTO stanza VALUES('FR43','6','Expirant ma vie ancienne,<br/>Je serai rempli de Toi :<br/>Tu transmets en moi la tienne,<br/>Par l''Esprit qui coule en moi.<br/>',NULL,27218,7);
INSERT INTO stanza VALUES('FR43','7','Ô Seigneur, je Te respire !<br/>Pour ne vivre que par Toi.<br/>Ta réalité j''inspire,<br/>Souffle Ton Esprit sur moi !<br/>',NULL,27219,8);
INSERT INTO stanza VALUES('FR44','1','L''amour parfait venant des cieux<br/>Demeure dans mon cœur,<br/>Le fonde et l''enracine en Dieu<br/>Et le remplit d''ardeur,<br/>Et le remplit d''ardeur.<br/>',NULL,27220,1);
INSERT INTO stanza VALUES('FR44','2','Que puisse enfin Ton feu sacré,<br/>Me prendre et m''embraser,<br/>Mes passions vaines consumer,<br/>Mes désirs purifier,<br/>Mes désirs purifier.<br/>',NULL,27221,2);
INSERT INTO stanza VALUES('FR44','3','Que puisse enfin Ton Esprit-Saint<br/>Traiter tous mes péchés.<br/>Seigneur achève Ton dessein,<br/>Que je sois sanctifié !<br/>Que je sois sanctifié !<br/>',NULL,27222,3);
INSERT INTO stanza VALUES('FR44','4','Consume en moi, Esprit de feu,<br/>Ce qui n''est pas de Toi.<br/>Infuse en moi la vie de Dieu,<br/>Remplace tout en moi,<br/>Remplace tout en moi.<br/>',NULL,27223,4);
INSERT INTO stanza VALUES('FR44','5','Remplis mon âme, affermis-la,<br/>Si stable je serai.<br/>Mon univers Tu deviendras<br/>Et Toi seul j''aimerai,<br/>Et Toi seul j''aimerai.<br/>',NULL,27224,5);
INSERT INTO stanza VALUES('FR45','1','L''onction divine en moi demeure<br/>Et j''ai son enseignement ;<br/>Vers le Seigneur, je suis toujours conduit,<br/>En tout temps, Il est présent.<br/>',NULL,27225,1);
INSERT INTO stanza VALUES('FR45','chorus','Dans mon esprit, j''ai l''onction de Dieu,<br/>Oui, j''ai l''onction de Dieu,<br/>J''ai son enseignement.<br/>Dans mon esprit, j''ai l''onction de Dieu,<br/>Je vis par son enseignement.<br/>',NULL,27226,2);
INSERT INTO stanza VALUES('FR45','2','L'' Esprit en nous est comme l''huile,<br/>L''huile pure qui nous oint.<br/>L''onction dépend de l''aspersion du sang,<br/>À jamais j''en suis empreint.<br/>',NULL,27227,3);
INSERT INTO stanza VALUES('FR45','3','Je connais Dieu par Sa nature,<br/>Que l''onction infuse en moi.<br/>J''expérimente tous Ses attributs,<br/>Qui sont déposés en moi.<br/>',NULL,27228,4);
INSERT INTO stanza VALUES('FR45','4','En communion avec le Père,<br/>Nous vivons par cette onction.<br/>Dans Sa lumière ensemble nous marchons,<br/>L''amour de Sa grâce ayant.<br/>',NULL,27229,5);
INSERT INTO stanza VALUES('FR46','1','Quelle gloire, en moi l''Esprit vit,<br/>Qui témoigne du Sauveur,<br/>La réalité révèle,<br/>Guide et adoucit mon cœur.<br/>',NULL,27230,1);
INSERT INTO stanza VALUES('FR46','chorus','Remplis-moi, remplis-moi !<br/>Remplis-moi, Seigneur-Esprit !<br/>Vide et affranchis mon être,<br/>Remplis-moi du Saint-Esprit !<br/>',NULL,27231,2);
INSERT INTO stanza VALUES('FR46','2','Maintenant Tu me libères,<br/>Par la loi de Ton Esprit.<br/>Le péché perd sa puissance<br/>Et la mort est abolie.<br/>',NULL,27232,3);
INSERT INTO stanza VALUES('FR46','3','Je languis comme une biche,<br/>Qui désir s''abreuver.<br/>Que l''eau vive en moi jaillisse<br/>Et que j''en sois inondé.<br/>',NULL,27233,4);
INSERT INTO stanza VALUES('FR46','4','Afin de remplir mon être,<br/>Rends-moi conforme à Ta mort,<br/>Règne sur ma vie entière,<br/>Glorifie-Toi dans mon corps.<br/>',NULL,27234,5);
INSERT INTO stanza VALUES('FR47','1','Je T''adore, mon cher Maitre,<br/>Ton amour m''a capturé.<br/>tu me laves, Tu me sauves,<br/>Ô Jésus, sois exprimé !<br/>',NULL,27235,1);
INSERT INTO stanza VALUES('FR47','chorus','Je veux être, mon cher Maitre,<br/>En tout temps, rempli de moi.<br/>Que Ta grâce de moi fasse<br/>Un bon vase utile à Toi !<br/>',NULL,27236,2);
INSERT INTO stanza VALUES('FR47','2','L''évangile Tu me donnes,<br/>Pour bénir les assoiffés.<br/>La nouvelle que j''annonce,<br/>Doit toucher le monde entier !<br/>',NULL,27237,3);
INSERT INTO stanza VALUES('FR47','3','Tu me prends et me façonnes,<br/>Comme un vase entre Tes mains.<br/>Je suis faible, sois ma force,<br/>Je dépends de Ton soutien.<br/>',NULL,27238,4);
INSERT INTO stanza VALUES('FR47','4','Je témoigne de Ta grâce<br/>Qui me sauve à tout instant.<br/>Tu m''as acquis à un grand prix,<br/>Gagne_moi entièrement !<br/>',NULL,27239,5);
INSERT INTO stanza VALUES('FR47','5','Oh ! déverse Ta vie sainte,<br/>Dans mon cœur qui s''ouvre à Toi !<br/>Et Ta grâce de mon être,<br/>Comme un fleuve jaillira !<br/>',NULL,27240,6);
INSERT INTO stanza VALUES('FR48','1','À Toi, nous venons et revendiquons :<br/>Nous Te demandons Ta puissance.<br/>Pour Tes intérêts, d''Esprit Tu nous vêts,<br/>Des cieux, luttons avec assurance.<br/>Oui ! Revêts-nous de Ta grande puissance !<br/>De Ta puissance venue des cieux !<br/>Oui ! Revêts-nous de Ta grande puissance !<br/>Hardiment, tous Tes membres s''écrient !<br/>',NULL,27241,1);
INSERT INTO stanza VALUES('FR48','2','Seigneur, c''est nos yeux tournés vers Toi que<br/>Nous réclamons les eaux célestes ;<br/>Au profit du Corps, ouvre les écluses !<br/>Les eaux pour Ton œuvre nous ajustent.<br/>Seigneur, Seigneur, ouvre les écluses !<br/>Que Ton Esprit soit sur nous versé !<br/>Seigneur, Seigneur, ouvre les écluses !<br/>Voici, Ton Corps maintenant s''écrie !<br/>',NULL,27242,2);
INSERT INTO stanza VALUES('FR48','3','Seigneur, brule-nous et consume-nous,<br/>Nous réclamons le divin feu.<br/>Nous voulons le feu pour mener à Dieu,<br/>Tous ceux qui sont loin de Toi, errants.<br/>Du feu, donne-nous des langues de feu !<br/>Pour Ton évangile proclamer !<br/>Du feu, donne-nous des langues de feu !<br/>Voici, Ton corps maintenant s''écrie !<br/>',NULL,27243,3);
INSERT INTO stanza VALUES('FR49','1','L'' Esprit est en nous et nous donne la vie,<br/>Il est comme l''eau qui notre être rempli.<br/>Il nous désaltère quand nous Le buvons,<br/>Des fleuves d''eau vive de nous jailliront.<br/>',NULL,27244,1);
INSERT INTO stanza VALUES('FR49','2','L'' Esprit de puissance est sur nous aujourd''hui,<br/>Pour l''œuvre Il nous revêt, Il est habit.<br/>En Lui baptisés et de Lui équipés,<br/>Dans Son ministère nous pouvons entre.<br/>',NULL,27245,2);
INSERT INTO stanza VALUES('FR49','3','L'' Esprit essentiel est en nous aujourd''hui,<br/>Il s''est insufflé, Il est en nous la vie.<br/>L'' Esprit de puissance est aussi comme un vent.<br/>Il souffle sur nous, Sa puissance donnant.<br/>',NULL,27246,3);
INSERT INTO stanza VALUES('FR49','4','En résurrection, le Seigneur s''insuffla,<br/>L'' Esprit essentiel aux disciples légua,<br/>Et en ascension déversa Son Esprit,<br/>Avec Sa puissance ainsi Il les remplit.<br/>',NULL,27247,4);
INSERT INTO stanza VALUES('FR49','5','L'' Esprit entre en nous pour nous donner la vie.<br/>Il est comme un souffle qui nous vivifie.<br/>Il souffle sue nous, de puissance revêt,<br/>Nous rafraichit, fortifie et satisfait.<br/>',NULL,27248,5);
INSERT INTO stanza VALUES('FR49','6','L'' Esprit nous remplit et L'' Esprit nous revêt,<br/>Ce sont là, du même Esprit, les deux aspects.<br/>À Dieu mélangés, de Lui nous jouissons,<br/>Son dessein, ensemble, nous accomplissons.<br/>',NULL,27249,6);
INSERT INTO stanza VALUES('FR49','7','Rempli nos parties intérieures d'' Esprit,<br/>Que nous agissions et croissions dans Ta vie.<br/>Seigneur, en esprit, nous voulons Te servir,<br/>Ta volonté, Ton bon plaisir accomplir.<br/>',NULL,27250,7);
INSERT INTO stanza VALUES('FR50','1','Le Dieu trinitaire vit dans notre esprit,<br/>C''est le merveilleux Esprit en nous !<br/>Et nous sommes mélangés à Jésus-Christ,<br/>Qui est l''Esprit qui donne la vie.<br/>',NULL,27251,1);
INSERT INTO stanza VALUES('FR50','chorus','L'' Esprit est merveilleux maint''nant en nous,<br/>Il est merveilleux maint''nant en nous,<br/>Dieu est dans le Fils, et le Fils est l''Esprit -<br/>Il est merveilleux, maint''nant en nous.<br/>',NULL,27252,2);
INSERT INTO stanza VALUES('FR50','2','« Abba Père ! » En nous, s''écrie le Saint-Esprit,<br/>De la profondeur de notre sein.<br/>C''est l''Esprit du Fils qui vit dans notre esprit,<br/>Il est l''Esprit qui donne la vie.<br/>',NULL,27253,3);
INSERT INTO stanza VALUES('FR50','3','Le Seigneur Jésus-Christ vit dans notre esprit,<br/>Il est merveilleux maint''nant en nous !<br/>Ressuscité, Il a été glorifié,<br/>Devenant un Esprit vivifiant.<br/>',NULL,27254,4);
INSERT INTO stanza VALUES('FR50','4','Christ est devenu l''Esprit de vérité,<br/>Dans la réalité Il nous conduit.<br/>Nous pouvons, alors, tous L''expérimenter :<br/>Ses richesses sont dans notre esprit.<br/>',NULL,27255,5);
INSERT INTO stanza VALUES('FR50','5','Ranimons le don du Saint-Esprit en nous,<br/>Il est mélangé à notre esprit !<br/>Invoquant : « Seigneur ! » notre esprit tressaillit<br/>Par l'' Esprit qui nous donne la vie.<br/>',NULL,27256,6);
INSERT INTO stanza VALUES('FR51','1','Aujourd''hui, l'' Esprit de Dieu<br/>est sept fois intensifié.<br/>Dieu va obtenir l''église,<br/>Que Son cœur a désirée.<br/>',NULL,27257,1);
INSERT INTO stanza VALUES('FR51','chorus','Viens, Esprit intensifié !<br/>Accomplis Ta volonté,<br/>Brule et sonde tous les cœurs.<br/>Les églises sont à Toi.<br/>Brule et sonde !<br/>Les églises sont à Toi.<br/>',NULL,27258,2);
INSERT INTO stanza VALUES('FR51','2','Lui, sept fois intensifié,<br/>La mort chasse de l''église,<br/>Pour que nous soyons bâtis<br/>Et que Sa vie nous remplisse.<br/>',NULL,27259,3);
INSERT INTO stanza VALUES('FR51','3','Maintenant, l''Esprit de Dieu<br/>Est sept fois intensifié.<br/>En tous temps et en tous lieux,<br/>Son église est recouvrée.<br/>',NULL,27260,4);
INSERT INTO stanza VALUES('FR51','4','Sept Esprits devant le trône<br/>Brulent comme un feu ardent,<br/>Ce n''est pas pour enseigner,<br/>Mais pour achever Son plan.<br/>',NULL,27261,5);
INSERT INTO stanza VALUES('FR51','5','Maintenant, les sept Esprits<br/>Sont sept yeux perçants qui sondent,<br/>Chaque église Ils purifient,<br/>Exposant en nous le monde.<br/>',NULL,27262,6);
INSERT INTO stanza VALUES('FR51','6','Vois, comment l''Esprit de Dieu,<br/>En puissance s''amplifie.<br/>Ainsi, toutes les église<br/>D''autant plus se fortifient.<br/>',NULL,27263,7);
INSERT INTO stanza VALUES('FR52','1','L''amour qui m''a recherché,<br/>Quand j''étais égaré,<br/>La grâce qui a mené<br/>Mon âme à mon Berger<br/>Et Sa miséricorde - Sans fin, comme les cieux :<br/>Voici mon héritage !<br/>Ces dons sont merveilleux !<br/>',NULL,27264,1);
INSERT INTO stanza VALUES('FR52','chorus','Au fil des années qui passent,<br/>Son amour devient plus doux,<br/>Plus profond, plus vaste,<br/>Bien plus riche et large,<br/>Son amour devient si doux !<br/>',NULL,27265,2);
INSERT INTO stanza VALUES('FR52','2','Avant, quand sur la terre,<br/>Jésus se déplaçait,<br/>Autour de Lui, la foule<br/>Avide Le pressait.<br/>Les sourds et les aveugles<br/>Sortirent de leur nuit,<br/>Et moi aussi, Il m''aime,<br/>Me cherche et me guérit !<br/>',NULL,27266,3);
INSERT INTO stanza VALUES('FR53','1','Tous mes péchés Tu pardonnas,<br/>Tu les jetas derrière Toi.<br/>Jamais, Tu ne t''en souviendras,<br/>Pour eux Tu mourus à la croix.<br/>',NULL,27267,1);
INSERT INTO stanza VALUES('FR53','chorus','Mes transgressions sont effacées,<br/>Comme un nuage, dissipées.<br/>Pour toujours, Tu as oublié<br/>Mes fautes et mes iniquités.<br/>',NULL,27268,2);
INSERT INTO stanza VALUES('FR53','2','Mes péchés sont tous loin de moi,<br/>Tel l''orient l''est de l''occident.<br/>J''obtins le pardon par la foi ;<br/>Seigneur, Tu en es le Garant.<br/>',NULL,27269,3);
INSERT INTO stanza VALUES('FR54','beginning-note','( Répétez les deux derniers vers de chaque strophe.)<br/>',NULL,27270,1);
INSERT INTO stanza VALUES('FR54','1','Et se peut-il que du Sauveur,<br/>Le sang me prodigue un tel gain ?<br/>Moi qui engendrai Sa douleur,<br/>Moi qui Le perçai dans Son sein...<br/>Suprême amour que sur la croix<br/>Mon Dieu, souffrant, soit mort pour moi !<br/>',NULL,27271,2);
INSERT INTO stanza VALUES('FR54','2','Quel grand mystère ! Oh ! quel dessein !<br/>Dieu, l''Immortel, un jour est mort !<br/>Anges, vous exposez en vain<br/>Les profondeurs de Son amour !<br/>Que ciel et terre, l''univers<br/>Proclame et chante ce mystère !<br/>',NULL,27272,3);
INSERT INTO stanza VALUES('FR54','3','Toutes Sa gloire, Il a quitté.<br/>Miséricorde illimitée !<br/>Lui, plein d''amour, s''est dépouillé.<br/>Il saigna pour l''humanité.<br/>C''est Toi, mon Dieu, qui m''as trouvé,<br/>Ton sang versé m''a racheté.<br/>',NULL,27273,4);
INSERT INTO stanza VALUES('FR54','4','Ton regard, source de lumière,<br/>Dans ma prison s''est infiltré.<br/>Sur mon péché jaillit l''éclair,<br/>Mon être entier fut embrasé.<br/>Libre, affranchi, dans mon esprit,<br/>Je me levai et Te suivis.<br/>',NULL,27274,5);
INSERT INTO stanza VALUES('FR54','5','Craindrais je d''être condamné ?<br/>Tout ce qu''est Christ est aussi mien<br/>Et Sa justice me revêt,<br/>Il est ma vie et mon soutien.<br/>Hardi, vers Lui je veux courir,<br/>Pour la couronne enfin saisir.<br/>',NULL,27275,6);
INSERT INTO stanza VALUES('FR55','1','Je suis en paix avec mon Dieu,<br/>En parfaite harmonie.<br/>Un grand pécheur est revenu<br/>À Dieu en Jésus-Christ.<br/>',NULL,27276,1);
INSERT INTO stanza VALUES('FR55','2','Nous étions morts dans nos péchés,<br/>De Dieu des ennemis.<br/>Mais par la foi au sang précieux,<br/>Nous recevons Sa vie.<br/>',NULL,27277,2);
INSERT INTO stanza VALUES('FR55','3','Il m''a sauvé, je ne crains rien,<br/>Si sur de mon salut.<br/>Il est à moi; je suis à Lui,<br/>Depuis qu''en Lui j''ai cru.<br/>',NULL,27278,3);
INSERT INTO stanza VALUES('FR55','4','Nous ayant pardonné en Christ,<br/>Dieu veut nous posséder.<br/>Approchons-nous du Saint des Saints,<br/>Soyons réconciliés !<br/>',NULL,27279,4);
INSERT INTO stanza VALUES('FR55','5','Le premier voile je franchis,<br/>Quand je fus justifié.<br/>Puis le second je franchirai,<br/>Pour être en Dieu trouvé.<br/>',NULL,27280,5);
INSERT INTO stanza VALUES('FR56','1','J''appartiens à Jésus,<br/>Je suis tout à Lui.<br/>Je Lui rends tout ce que j''ai,<br/>Tout ce que je suis.<br/>',NULL,27281,1);
INSERT INTO stanza VALUES('FR56','2','J''appartiens à Jésus,<br/>Lui donne mon cœur<br/>Pour qu'' Il règne dans ma vie,<br/>Qu'' Il soit le Seigneur !<br/>',NULL,27282,2);
INSERT INTO stanza VALUES('FR56','3','J''appartiens à Jésus,<br/>Mon âme est sauvée.<br/>Grâce au sang qu'' Il a versé,<br/>Il m''a racheté.<br/>',NULL,27283,3);
INSERT INTO stanza VALUES('FR56','4','J''appartiens à Jésus,<br/>Je vis par la foi.<br/>En Lui je suis crucifié,<br/>Il mourut pour moi.<br/>',NULL,27284,4);
INSERT INTO stanza VALUES('FR56','5','J''appartiens à Jésus,<br/>Quand je suis confus,<br/>Dans la brume ou dans la nuit,<br/>Il est mon salut.<br/>',NULL,27285,5);
INSERT INTO stanza VALUES('FR56','6','J''appartiens à Jésus,<br/>Quand je suis blessé,<br/>Il me porte avec amour<br/>En soignant mes plaies.<br/>',NULL,27286,6);
INSERT INTO stanza VALUES('FR56','7','J''appartiens à Jésus,<br/>Puissant Rédempteur !<br/>De ce monde Il m''arracha,<br/>Il est mon sauveur !<br/>',NULL,27287,7);
INSERT INTO stanza VALUES('FR57','1','Seigneur, devant Toi nous venons,<br/>Jouir de Ta présence.<br/>Nous nous approchons hardiment,<br/>En appliquant Ton sang.<br/>Nous nous confions en Ta justice<br/>Et en Ton sang précieux.<br/>Nos propres œuvres, nos mérites,<br/>Ne comptent pas pour Toi.<br/>',NULL,27288,1);
INSERT INTO stanza VALUES('FR57','2','Tes jugements, ils sont loyaux,<br/>Saints, justes et droits, Seigneur.<br/>Nous n''essayons pas de cacher,<br/>Toutes nos transgression.<br/>Rien ne pourrait sur cette terre,<br/>Blanchir tous nos péchés.<br/>Nous Te louons ! Nous chérissons,<br/>Seigneur, Ton sang précieux.<br/>',NULL,27289,2);
INSERT INTO stanza VALUES('FR57','3','Dieu jugea une fois pour toutes<br/>Le péché à la croix.<br/>Sur Lui la colère tomba,<br/>Sur l''Agneau, non sur moi.<br/>Ainsi, je m''approche hardiment,<br/>Son sang me justifie.<br/>Il se livra, mon substitut,<br/>Et devint mon garant.<br/>',NULL,27290,3);
INSERT INTO stanza VALUES('FR57','4','Seigneur, nous nous réjouissons,<br/>De la vertu du sang.<br/>En appréciant Ta rédemption,<br/>Combien nous T''adorons !<br/>Seigneur, que Ta miséricorde<br/>Est vaste, illimitée !<br/>Agneau de Dieu, nous Te louons<br/>Pour toute éternité !<br/>',NULL,27291,4);
INSERT INTO stanza VALUES('FR58','1','Quelle assurance : Christ est à moi !<br/>Quel avant-goût d''une glorieuse joie !<br/>Dieu m''a sauvé, je suis racheté,<br/>Né de l''Esprit, dans Son sang lavé.<br/>',NULL,27292,1);
INSERT INTO stanza VALUES('FR58','chorus','C''est mon histoire, c''est là mon chant,<br/>Louer mon Sauveur le jour durant.<br/>C''est mon histoire, c''est là mon chant,<br/>Louer mon Sauveur le jour durant.<br/>',NULL,27293,2);
INSERT INTO stanza VALUES('FR58','2','Soumis à Lui, je suis dans la joie !<br/>Tout voile Il ote pour que je le voie.<br/>Quel autre au ciel aurais-je que Lui ?<br/>Sur terre, Jésus seul me réjouit.<br/>',NULL,27294,3);
INSERT INTO stanza VALUES('FR58','3','Aux pieds du maitre, je suis en paix,<br/>La joie m''inonde, Il me satisfait !<br/>Je veille et prie, je m''attends à Lui,<br/>En abondance reçois Sa vie.<br/>',NULL,27295,4);
INSERT INTO stanza VALUES('FR59','1','Merveilleux changement : je naquis de nouveau,<br/>Quand Jésus entra dans mon cœur.<br/>La lumière jaillit, je sortis du tombeau,<br/>Quand Jésus entra dans mon cœur.<br/>',NULL,27296,1);
INSERT INTO stanza VALUES('FR59','chorus','Depuis qu''Il entra dans mon cœur,<br/>Depuis qu''Il entra dans mon cœur,<br/>Quelle joie, quel bonheur que de voir mon Sauveur,<br/>Depuis qu''Il entra dans mon cœur.<br/>',NULL,27297,2);
INSERT INTO stanza VALUES('FR59','2','Je ne peux plus errer et toujours m''égarer,<br/>Depuis qu''Il entra dans mon cœur.<br/>Mes péchés sont lavés et je suis pardonné,<br/>Depuis qu''Il entra dans mon cœur.<br/>',NULL,27298,3);
INSERT INTO stanza VALUES('FR59','3','J''ai la pleine assurance et la joie du salut,<br/>Depuis qu''Il entra dans mon cœur.<br/>Sa parole le dit, non je ne doute plus,<br/>Depuis qu''Il entra dans mon cœur.<br/>',NULL,27299,4);
INSERT INTO stanza VALUES('FR59','4','La vallée de la mort n''est plus sombre pour moi,<br/>Depuis qu''Il entra dans mon cœur.<br/>En esprit, une sainte cité j''aperçois,<br/>Depuis qu''Il entra dans mon cœur.<br/>',NULL,27300,5);
INSERT INTO stanza VALUES('FR59','5','L''Esprit m''a révélé d''où je viens, où je vais,<br/>Depuis qu''Il entra dans mon cœur.<br/>Plus j''avance, plus je suis heureux et comblé,<br/>Depuis qu''Il entra dans mon cœur.<br/>',NULL,27301,6);
INSERT INTO stanza VALUES('FR60','1','La joie me remplit,<br/>Mon Seigneur m''a ravi.<br/>La joie me remplit,<br/>Dieu change mon cœur en un cœur de chair.<br/>En nouveauté d''esprit, dès lors, je Le sers.<br/>La joie me remplit,<br/>Mon Seigneur m''a ravi.<br/>',NULL,27302,1);
INSERT INTO stanza VALUES('FR60','2','L''Esprit vivifie,<br/>Fortifie, rafraichit.<br/>L'' Esprit m'' affranchit :<br/>Du corps du péché Il m''a libéré.<br/>Les fruits de justice sont manifestés.<br/>L''Esprit vivifie,<br/>Fortifie, rafranchit.<br/>',NULL,27303,2);
INSERT INTO stanza VALUES('FR61','1','J''étais esclave, lié dans mes chaines,<br/>Couvert de honte, luttant en vain.<br/>Alors Jésus vint prendre mes peines,<br/>Pour m''affranchir et briser mes lien.<br/>',NULL,27304,1);
INSERT INTO stanza VALUES('FR61','chorus','Quelle merveille d''être enfin libre,<br/>De ne plus geindre dans mes péchés !<br/>Le grand Sauveur, Celui que j''adore,<br/>Il est à moi pour l''éternité !<br/>',NULL,27305,2);
INSERT INTO stanza VALUES('FR61','2','Libre de toute passion charnelle,<br/>Des préférences, des jalousies.<br/>Je n''assouvis plus mes passion vaines,<br/>Désormais, rien ne ternit ma vie !<br/>',NULL,27306,3);
INSERT INTO stanza VALUES('FR61','3','Libre des vaines gloires du monde,<br/>Des convoitises et de l''argent,<br/>De mes colères, de mes caprices,<br/>Je servirai Dieu en Le louant !<br/>',NULL,27307,4);
INSERT INTO stanza VALUES('FR61','4','Libre des craintes et des angoisses,<br/>De toute peine, de tout souci.<br/>Libre en Celui qui brisa mes chaines,<br/>J''exalterai mon Sauveur béni !<br/>',NULL,27308,5);
INSERT INTO stanza VALUES('FR62','1','Des années durant, la source j''ai cherché<br/>Qui ne tarirait jamais.<br/>Je goûtais le monde avec sa vanité,<br/>Mais n''étais pas satisfait !<br/>',NULL,27309,1);
INSERT INTO stanza VALUES('FR62','chorus','Je bois à la source qui toujours jaillit,<br/>Je bois à la source d''où vient la vie,<br/>J''y comble mes désirs,<br/>J''y trouve mon plaisir,<br/>Car je bois cette eau qui jaillit de Lui !<br/>',NULL,27310,2);
INSERT INTO stanza VALUES('FR62','2','Dans les sables du désert je n''erre plus,<br/>J''ai trouvé une oasis.<br/>Ma coupe de joie déborde maintenant,<br/>Jésus est Seigneur et Roi !<br/>',NULL,27311,3);
INSERT INTO stanza VALUES('FR62','3','J''ai lavé Toutes mes plaies.<br/>Me désaltère à jamais.<br/>À cette fontaine qui toujours guérit,<br/>J''ai lavé toutes mes plaies.<br/>',NULL,27312,4);
INSERT INTO stanza VALUES('FR62','4','En ce lieu, au fil des jours, je suis heureux.<br/>J''ai trouvé un vrai soutien.<br/>C''est là que je jouis d''un salut précieux.<br/>Je ne manquerai de rien !<br/>',NULL,27313,5);
INSERT INTO stanza VALUES('FR63','1','La voix de Jésus j''entendis :<br/>« Viens et repose-toi ;<br/>Et mets ta tête sur Mon sein,<br/>Toi qui es faible et las. »<br/>Tel que j''étais je vins à Lui,<br/>Fourbu, triste, épuisé.<br/>Le vrai repos j''ai découvert,<br/>Le Seigneur m''a comblé.<br/>',NULL,27314,1);
INSERT INTO stanza VALUES('FR63','2','La voix de Jésus j''entendis :<br/>« Je suis l''eau de la vie.<br/>Toi qui es toujours assoiffé,<br/>À moi viens, bois et vis. »<br/>À Jésus je vins et je bus<br/>À ce courant divin.<br/>Désaltéré et vivifié,<br/>Je vis de Son soutien.<br/>',NULL,27315,2);
INSERT INTO stanza VALUES('FR63','3','La voix de Jésus j''entendis :<br/>« Je brille dans la nuit.<br/>Regarde-moi, le jour viendra<br/>Pour éclairer ta vie. »<br/>Je portai mes regards sur Lui,<br/>L''étoile du matin.<br/>De jour en jour Sa vie en moi<br/>Éclaire mon chemin.<br/>',NULL,27316,3);
INSERT INTO stanza VALUES('FR64','1','L''ancre de ta vie est-elle fixée,<br/>Quand l''orage gronde et veut te couler ?<br/>Quand les ancres tirant sous les marées,<br/>Pourras-tu tenir, ne point lâcher ?<br/>',NULL,27317,1);
INSERT INTO stanza VALUES('FR64','chorus','Notre âme à l''ancre tient fermement,<br/>Sure et solide sous les grands vents,<br/>Fixée à l''immuable rocher,<br/>À l''amour du Fils qui nous a sauvés.<br/>',NULL,27318,2);
INSERT INTO stanza VALUES('FR64','2','Elle est amarrée, défiant tous les flots,<br/>La main de Dieu veille à mon bateau.<br/>Les cordages vont de Son cœur au mien,<br/>Rien ne les rompra : ils sont divins.<br/>',NULL,27319,3);
INSERT INTO stanza VALUES('FR64','3','Lorsque les brisants montrent un récif,<br/>Rien ne fait trembler mon frêle esquif.<br/>Sous les coups sauvages de l''ouragan,<br/>Nulle vague au loin ne le surprend.<br/>',NULL,27320,4);
INSERT INTO stanza VALUES('FR64','4','L''ancre nous tiendra dans les flots de mort,<br/>Qui font frémir, loin de notre port.<br/>Elle est sure et forte dans la marée,<br/>L''espoir au-delà du voile ancrée.<br/>',NULL,27321,5);
INSERT INTO stanza VALUES('FR65','1','Affranchi du vieil Adam,<br/>Je fus transféré en Christ !<br/>Et voici, tout est nouveau !<br/>Je jouis de Sa paix.<br/>Que Dieu soit loué !<br/>Je suis libre, avec Lui un seul esprit !<br/>Oh ! Alléluia, Christ est ma vie !<br/>',NULL,27322,1);
INSERT INTO stanza VALUES('FR66','1','Telle une rivière, la paix nous atteint,<br/>Au sein des grands flots déchainés.<br/>Tu m''as enseigné, quel que soit mon destin,<br/>À chanter que Tu m''as délivré.<br/>',NULL,27323,1);
INSERT INTO stanza VALUES('FR66','chorus','Tout va bien dans mon âme !<br/>Tout va bien, ô Seigneur, dans mon âme !<br/>',NULL,27324,2);
INSERT INTO stanza VALUES('FR66','2','Et quand Satan veut sans répit m''accabler,<br/>Je peux lui répondre hardiment :<br/>« Jésus à la croix a déjà triomphé !<br/>Le Seigneur m''a lavé par Son sang ! »<br/>',NULL,27325,3);
INSERT INTO stanza VALUES('FR66','3','Oh ! Félicité de ce fait glorieux !<br/>Mes iniquités sont ôtées,<br/>Clouées à la croix, oubliées par mon Dieu !<br/>Que Jésus, mon Seigneur, soit loué !<br/>',NULL,27326,4);
INSERT INTO stanza VALUES('FR66','4','Pour moi, vivre Christ est le vœu de mon cœur,<br/>Partout et en tout occasion,<br/>Dès lors je ne crains ni chagrin ni douleur,<br/>Car Lui seul est ma bénédiction !<br/>',NULL,27327,5);
INSERT INTO stanza VALUES('FR67','1','Je veux Seigneur, en Toi demeurer,<br/>Ta gloire contempler,<br/>Te laisser me parler<br/>Et en Toi me cacher.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27328,1);
INSERT INTO stanza VALUES('FR67','2','Je veux Seigneur, en Toi demeurer,<br/>Qu''en moi Ta douce voix,<br/>Dirige tous mes choix.<br/>Elle est ma paix, ma joie.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27329,2);
INSERT INTO stanza VALUES('FR67','3','Je veux Seigneur, en Toi demeurer,<br/>Je ne veux être pris<br/>Par la vie, ses soucis,<br/>Le monde qui me lie.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27330,3);
INSERT INTO stanza VALUES('FR67','4','Je veux Seigneur, en Toi demeurer,<br/>Pardonne mes péchés,<br/>Chasse mes anxiétés,<br/>Qui veulent me troubler.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27331,4);
INSERT INTO stanza VALUES('FR67','5','Je veux Seigneur, en Toi demeurer,<br/>Ta lumière a jailli,<br/>Elle a chassé ma nuit<br/>Et règne dans ma vie.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27332,5);
INSERT INTO stanza VALUES('FR67','6','Je veux Seigneur, en Toi demeurer,<br/>Que mes yeux soient fixés,<br/>Sur Toi mon bien-aimé.<br/>En Toi je marcherai.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27333,6);
INSERT INTO stanza VALUES('FR67','7','Je veux Seigneur, en Toi demeurer,<br/>La face dévoilée,<br/>Je serai transformé,<br/>Pour Ton retour paré.<br/>Tu es à moi, je suis à Toi.<br/>',NULL,27334,7);
INSERT INTO stanza VALUES('FR68','1','Jésus, Ta présence est mon plus cher désir,<br/>O, sois chaque jour mon unique univers !<br/>Ne permets pas que mon cœur soit satisfait,<br/>D'' aimer autre chose que ce qui T'' est cher !<br/>Dans tous mes tourments et dans tous mes chagrins,<br/>Quand rien ici-bas ne peut me secourir,<br/>Quand rien ne parvient plus à tarir mes pleurs,<br/>Seigneur, prends mes larmes, calme mes soupirs.<br/>',NULL,27335,1);
INSERT INTO stanza VALUES('FR68','2','Quand je songe à toutes les joies de la vie,<br/>Seigneur, je Te prie, sois si précieux pour moi !<br/>Pénètre mon cœur afin qu''à chaque pas,<br/>Je cherche à Te plaire et à vivre par Toi.<br/>Quand je suis couché solitaire la nuit,<br/>Je prie et languis : « Sois toujours près de moi ! »<br/>Que Ta douce voix, quand à l''aube je dors,<br/>Murmure et m''éveille, m''attire vers Toi !<br/>',NULL,27336,2);
INSERT INTO stanza VALUES('FR68','3','Quand je lis Ta Sainte Parole en priant,<br/>Éclaire-moi de Ta lumière, Seigneur.<br/>Fais que mes yeux s''ouvrent pour que je Te voie<br/>Dans toute Ta gloire, Toi mon rédempteur.<br/>Lorsque, démuni, à Ton trône je viens,<br/>Donne-moi Ta grâce, réponds à mes pleurs.<br/>Si mes torts T''empêchent d''entendre mon cri,<br/>Je veux voir quand même Ta face, Seigneur !<br/>',NULL,27337,3);
INSERT INTO stanza VALUES('FR68','4','Et lorsque je pense aux célestes bienfaits,<br/>Mon cœur voudrait être vers Toi enlevé !<br/>Ma seule espérance ici est Ta venue :<br/>Alors, Ta présence saura me combler.<br/>Apprendre-moi, Seigneur, à marcher devant Toi,<br/>O, sois chaque jour mon unique univers !<br/>Ne permets pas que mon cœur soit satisfait<br/>D''aimer autre chose que ce qui T''est cher !<br/>',NULL,27338,4);
INSERT INTO stanza VALUES('FR69','1','Seigneur Jésus, grandis en moi<br/>Et que toute ombre fuie.<br/>Que ,on cœur soit toujours à Toi,<br/>De tout lien affranchi.<br/>',NULL,27339,1);
INSERT INTO stanza VALUES('FR69','chorus','Sois mon soutien dans mes faiblesses,<br/>Exauce ma prière.<br/>Que davantage je connaisse<br/>Ta vie et Ta lumière.<br/>',NULL,27340,2);
INSERT INTO stanza VALUES('FR69','2','L''éclat de Tes rayons divins<br/>Dévoile mes pensées,<br/>Me montrant que je ne suis rien<br/>Sans Toi, mon ben-aimé !<br/>',NULL,27341,3);
INSERT INTO stanza VALUES('FR69','3','Ô Véritable, Sage et Saint !<br/>Je veux Te contempler.<br/>En tout malheur comme en tout bien,<br/>Toi seul j''exprimerai.<br/>',NULL,27342,4);
INSERT INTO stanza VALUES('FR69','4','Accorde-moi la joie d''en haut,<br/>Demeure mon rocher.<br/>Que Ton amour à jamais soit<br/>Dans mon cœur attisé !<br/>',NULL,27343,5);
INSERT INTO stanza VALUES('FR69','5','Que mon vieil homme soit détruit,<br/>Que j''en sois dépouillé !<br/>Que par Ta grâce dans ma vie,<br/>Ton nom soit honoré !<br/>',NULL,27344,6);
INSERT INTO stanza VALUES('FR70','1','À Ton image, rends-moi conforme,<br/>C''est mon attente, mon vif désir.<br/>Pour Te poursuivre, je fuis le monde,<br/>Ses convoitises, ses vains plaisirs.<br/>',NULL,27345,1);
INSERT INTO stanza VALUES('FR70','chorus','À Ton image , oui ! à Ton image !<br/>Rends-moi conforme, mon rédempteur.<br/>Qu''en moi se grave Ta sainte image,<br/>Dans Ta douceur, viens prendre mon cœur !<br/>',NULL,27346,2);
INSERT INTO stanza VALUES('FR70','2','À Ton image, rends-moi conforme,<br/>Tu es patient, doux, plein de bonté,<br/>Compatissant, humble et longanime,<br/>Tu es justice et fidélité !<br/>',NULL,27347,3);
INSERT INTO stanza VALUES('FR70','3','À Ton image, rends-moi conforme,<br/>Pauvre en esprit et humble de cœur.<br/>Tu fus si tendre dans la souffrance,<br/>Dans l''affliction pour tous les pécheurs.<br/>',NULL,27348,4);
INSERT INTO stanza VALUES('FR70','4','À Ton image, rends-moi conforme,<br/>Je veux Te suivre, tout Te donner.<br/>Ce que je suis , ce que je possède,<br/>Je veux, Seigneur, tout Te consacrer !<br/>',NULL,27349,5);
INSERT INTO stanza VALUES('FR70','5','À Ton image, rends-moi conforme,<br/>Déverse en moi Ton amour ardent.<br/>Modèle-moi, je veux la vie sainte,<br/>Qui Te convienne parfaitement !<br/>',NULL,27350,6);
INSERT INTO stanza VALUES('FR71','1','Apprends-nous à prier ;<br/>Détourne-nous de nos pensées<br/>Et de la vanité.<br/>Rappelle-nous de T''invoquer toujours - Jésus, grandis en nous !<br/>',NULL,27351,1);
INSERT INTO stanza VALUES('FR71','2','Toi, semence de vie,<br/>Tu T''es semé dans notre cœur,<br/>Mais ce n''est qu''un début ;<br/>De jour en jour, Tu veux nous infuser - Jésus, grandis en nous !<br/>',NULL,27352,2);
INSERT INTO stanza VALUES('FR71','3','Adoucis notre cœur;<br/>Seigneur, Tu sais d''où nous venons.<br/>Nous invoquons Ton nom ;<br/>Seigneur, ne laisse aucune pierre en nous - Jésus, grandis en nous !<br/>',NULL,27353,3);
INSERT INTO stanza VALUES('FR71','4','Ta lumière a jailli :<br/>Sans Toi, nous ne pouvons rien faire ;<br/>Mais la semence en nous<br/>Va percer et laisser Ta vie œuvrer - Jésus, grandis en nous !<br/>',NULL,27354,4);
INSERT INTO stanza VALUES('FR71','5','Rends-nous pauvres d''esprit,<br/>Prends ce que nous croyons savoir<br/>Et œuvre-Toi en nous ;<br/>Seigneur, nous voulons Te laisser agir - Jésus, grandis en nous !<br/>',NULL,27355,5);
INSERT INTO stanza VALUES('FR71','6','Rends-nous si purs de cœur,<br/>Car nous ne serons satisfaits<br/>Que lorsque Tu auras<br/>Rempli et vraiment possédé notre ame - Jésus, grandis en nous !<br/>',NULL,27356,6);
INSERT INTO stanza VALUES('FR71','7','Touche mon cœur, Seigneur ;<br/>Contrains-moi à jouir de Toi,<br/>Te prenant chaque jour.<br/>Ta vie en nous produira le royaume - Jésus, grandis en nous !<br/>',NULL,27357,7);
INSERT INTO stanza VALUES('FR71','8','Amen pour la croissance !<br/>Rien ne peut arrêter Ta vie;<br/>Oh ! renouvelle nous !<br/>Ce n''est que par Toi que nous murirons - Jésus, grandis en nous !<br/>Jésus, grandis en nous !<br/>',NULL,27358,8);
INSERT INTO stanza VALUES('FR72','1','Seigneur, fortifie tout mon être.<br/>Oui, fortifie-le, je Te prie.<br/>Remplis mon esprit de puissance,<br/>Possède mon cœur, Seigneur.<br/>',NULL,27359,1);
INSERT INTO stanza VALUES('FR72','chorus','Oui, dans mon cœur ! Oui, dans mon cœur !<br/>Répands-Toi, Seigneur, dans mon cœur.<br/>Habite en lui et sois vainqueur,<br/>Oui, sois victorieux dans mon cœur !<br/>',NULL,27360,2);
INSERT INTO stanza VALUES('FR72','2','Possède, Seigneur, tout mon être,<br/>Oui, prends-le, Seigneur, je Te prie.<br/>Depuis mon esprit, prends mon âme,<br/>Répand-Toi dans tout mon cœur.<br/>',NULL,27361,3);
INSERT INTO stanza VALUES('FR72','3','Seigneur, Ta maison fais dans mon cœur !<br/>2 Fais-y Ta demeure, je prie.<br/>Afin que Ta vie nous inonde,<br/>Possède mon cœur Seigneur.<br/>',NULL,27362,4);
INSERT INTO stanza VALUES('FR72','4','Alors, à Celui qui peut faire<br/>Bien plus que ce que nous pensons,<br/>Par Sa propre vie et puissance,<br/>À Lui, nous ouvrons nos cœurs !<br/>',NULL,27363,5);
INSERT INTO stanza VALUES('FR73','1','Amour qui ne me lâche pas,<br/>Mon âme se repose en Toi.<br/>Je rends la vie que je Te dois,<br/>Pour qu''en Ton profond océan,<br/>Son flot soit débordant.<br/>',NULL,27364,1);
INSERT INTO stanza VALUES('FR73','2','Lumière éclairant mon sentier,<br/>Je rends ma faible flamme à Toi.<br/>Mon cœur son rayon Te renvoie,<br/>Pour qu''en Ton soleil si brillant,<br/>Son éclat soit plus grand.<br/>',NULL,27365,2);
INSERT INTO stanza VALUES('FR73','3','Ô joie, même dans les douleurs,<br/>Mon cœur demeure ouvert à Toi.<br/>Dans la pluie l''arc-en-ciel je vois,<br/>Ce que Dieu promet n''est pas vain,<br/>Mes pleurs ont une fin.<br/>',NULL,27366,3);
INSERT INTO stanza VALUES('FR73','4','Ô croix, révélant mon regard,<br/>Je n''ose m''éloigner de Toi.<br/>Ma gloire dans la boue se noie,<br/>Le sang de ce lieu a coulé,<br/>Jésus en moi est né.<br/>',NULL,27367,4);
INSERT INTO stanza VALUES('FR74','1','« Je T''appartiens ! Oh ! quelle joie profonde ! »<br/>C''est ma réponse au grand amour divin.<br/>La foi répond « oui » à ces mots si tendres :<br/>« Tu es Mon racheté, tu M''appartiens ! »<br/>',NULL,27368,1);
INSERT INTO stanza VALUES('FR74','2','« Je suis à Lui ! » déclare Son épouse,<br/>Se rappelant le jour où par amour,<br/>Proclamant : « oui », elle a promis de L''aimer,<br/>Lui obéir et L''honorer toujours.<br/>',NULL,27369,2);
INSERT INTO stanza VALUES('FR74','3','Je suis Toi ! Oh ! quelle union intime !<br/>Elle implique amour, foi et loyauté,<br/>Un cœur fidèle et un saint sacerdoce,<br/>Tout comme une obéissance illimitée.<br/>',NULL,27370,3);
INSERT INTO stanza VALUES('FR74','4','Je T''appartiens ! Prends mon corps et mon âme.<br/>Marque mon être de Ton sceau divin,<br/>Car Bien-aimé, dans toutes Tes richesses,<br/>Tu m''appartiens pour toujours, cher Seigneur !<br/>',NULL,27371,4);
INSERT INTO stanza VALUES('FR75','beginning-note','(Répétez les deux derniers vers de chaque strophe.)<br/>',NULL,27372,1);
INSERT INTO stanza VALUES('FR75','1','Ta vie Tu as livré,<br/>Tu as versé Ton Sang<br/>Et Tu m''as racheté,<br/>Tu m''as rendu vivant.<br/>Ta vie pour moi Tu as livré,<br/>Que T''ai-je présenté ?<br/>',NULL,27373,2);
INSERT INTO stanza VALUES('FR75','2','Pour moi tu enduras<br/>L''opprobre et la douleur,<br/>Pour que Ta gloire soit<br/>Sans cesse dans mon cœur.<br/>Pour moi, Seigneur, Tu fus blessé,<br/>Et moi, qu''ai-je à donner ?<br/>',NULL,27374,3);
INSERT INTO stanza VALUES('FR75','3','Le trône Tu quittas<br/>Et Tu fus humilié,<br/>La gloire abandonnas,<br/>Pour moi fus dépouillé.<br/>De tout, pour moi, Tu t''es privé,<br/>Je n''ai rien mérité.<br/>',NULL,27375,4);
INSERT INTO stanza VALUES('FR75','4','Tu as vécu pour moi<br/>La plus grande agonie,<br/>De l''enfer me sauvas,<br/>Pour me donner la vie.<br/>Pour moi, Tu as été percé,<br/>Et moi, qu''ai-je enduré ?<br/>',NULL,27376,5);
INSERT INTO stanza VALUES('FR75','5','Des cieux Tu descendis,<br/>M''offris Ton grand pardon,<br/>Le plein salut gratuit,<br/>L''amour, suprême don !<br/>Le Saint-Esprit, Tu m''as donné,<br/>Et moi, qu''ai-je apporté ?<br/>',NULL,27377,6);
INSERT INTO stanza VALUES('FR75','6','Je me consacre à Toi,<br/>Du monde détaché.<br/>De peines et de joies,<br/>Mes jours seront tissés.<br/>Tu t''es, Seigneur, donné pour moi,<br/>Et moi, je m''offre à Toi !<br/>',NULL,27378,7);
INSERT INTO stanza VALUES('FR76','1','Au monde entier j''ai renoncé,<br/>Ses illusions sont vaines.<br/>Je veux ailleurs donner mon cœur,<br/>Le grand Sauveur m''entraine.<br/>Je ne veux plus être aveuglé,<br/>J''ai tout quitté, j''ai tout laissé !<br/>De moi, le monde est très loin !<br/>',NULL,27379,1);
INSERT INTO stanza VALUES('FR76','2','Je veux laisser ma vieille vie<br/>Et mes folies d''autre fois.<br/>Dieu m''a placé en Jésus-Christ,<br/>Je veux rester sous la croix.<br/>La mort je quitte pour la vie,<br/>Je brandis sa bannière.<br/>C''est là que je vais demeurer,<br/>De moi, le monde est très loin !<br/>',NULL,27380,3);
INSERT INTO stanza VALUES('FR76','3','Mon ame plus jamais n''ira<br/>Sur ces traces anciennes.<br/>Je suis en paix, j''ai Son repos,<br/>C''est Lui qui prend mes peines.<br/>Mon nouveau maitre j''ai choisi,<br/>Par un serment de gloire.<br/>Et pour toujours je veux laisser<br/>De moi, le monde est très loin !<br/>',NULL,27381,5);
INSERT INTO stanza VALUES('FR76','4','Je ne veux point d''autre Sauveur,<br/>À Lui seul je m''adresse.<br/>Lui seul m''inonde de bonheur,<br/>D''amour et de tendresse.<br/>Mon cœur se tourne vers Jésus,<br/>Mes yeux voient Sa lumière.<br/>L''abime de la mort franchi,<br/>De moi, le monde est très loin !<br/>',NULL,27382,7);
INSERT INTO stanza VALUES('FR77','1','Ô Jésus ! je m''abandonne,<br/>Je Te cède tous mes biens.<br/>Oui, je T''aime et veux Te vivre,<br/>Me livrer entre Tes mains.<br/>',NULL,27383,1);
INSERT INTO stanza VALUES('FR77','chorus','J''abandonne tout,<br/>J''abandonne tout,<br/>À Toi mon Sauveur bien-aimé,<br/>J''abandonne tout.<br/>',NULL,27384,2);
INSERT INTO stanza VALUES('FR77','2','Ô Jésus ! je m''abandonne,<br/>Me prosterne devant Toi.<br/>Les plaisirs du monde laisse,<br/>Me voici, je suis à Toi !<br/>',NULL,27385,3);
INSERT INTO stanza VALUES('FR77','3','Ô Jésus ! je m''abandonne,<br/>Je suis toujours plus à Toi.<br/>Ton Esprit en moi témoigne,<br/>Qu''à jamais, Tu es mon Roi.<br/>',NULL,27386,4);
INSERT INTO stanza VALUES('FR77','4','Ô Jésus ! je m''abandonne,<br/>Prends ma vie, c''est là mon vœu !<br/>Remplis-moi d''amour, de force,<br/>Sois pour moi le plus précieux.<br/>',NULL,27387,5);
INSERT INTO stanza VALUES('FR77','5','Ô Jésus ! je m''abandonne,<br/>Car Ton feu saint brule en moi.<br/>Ton si grand salut me comble,<br/>Gloire, honneur, hommage à Toi !<br/>',NULL,27388,6);
INSERT INTO stanza VALUES('FR78','1','Tout pour Jésus ! Tout pour Jésus !<br/>Tout mon être est fortifié,<br/>Mes pensées, mes mots, mes actes,<br/>Chaque instant de mes journées.<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Chaque instant de mes journées !<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Chaque instant de mes journées !<br/>',NULL,27389,1);
INSERT INTO stanza VALUES('FR78','2','Que mes mains suivent Ses ordres,<br/>Que mes pieds suivent Ses voies,<br/>Que mes yeux ne voient que Jésus,<br/>Que ma bouche crie de joie.<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Que ma bouche crie de joie !<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Que ma bouche crie de joie !<br/>',NULL,27390,2);
INSERT INTO stanza VALUES('FR78','3','Le monde tient à ses joyaux,<br/>À ses vains pièges dorés.<br/>Qu''il se vante de ses gloire !<br/>À Jésus, j''ai tout confié !<br/>Tout pour Jésus ! Tout pour Jésus !<br/>À Jésus, j''ai tout confié !<br/>Tout pour Jésus ! Tout pour Jésus !<br/>À Jésus, j''ai tout confié !<br/>',NULL,27391,3);
INSERT INTO stanza VALUES('FR78','4','Je fixe mes yeux sur Jésus,<br/>Mon esprit est captivé.<br/>Toute autre vision s''efface,<br/>Quand je vois le Crucifié.<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Quand je vois le Crucifié.<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Quand je vois le Crucifié.<br/>',NULL,27392,4);
INSERT INTO stanza VALUES('FR78','5','Quelle joie ! Quelle merveille !<br/>Jésus-Christ, le Roi des rois !<br/>Mon Bien-aimé je T''appelle,<br/>Sous Tes ailes, tu me choies.<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Sous Tes ailes, tu me choies !<br/>Tout pour Jésus ! Tout pour Jésus !<br/>Sous Tes ailes, tu me choies !<br/>',NULL,27393,5);
INSERT INTO stanza VALUES('FR79','beginning-note','( Répontez le dernier vers de chaque strophe.)<br/>',NULL,27394,1);
INSERT INTO stanza VALUES('FR79','1','Prends ma vie, que tout entier<br/>À Toi je sois consacré !<br/>Prends mes jours, prends chaque instant,<br/>Que je vive en Te louant.<br/>',NULL,27395,2);
INSERT INTO stanza VALUES('FR79','2','Prends mes mains, fais-les servir<br/>Ton dessein et Ton désir.<br/>Prends mes pieds pour annoncer,<br/>L''évangile de Ta paix.<br/>',NULL,27396,3);
INSERT INTO stanza VALUES('FR79','3','Prends ma voix, fais-la chanter,<br/>Que mon Roi soit exalté !<br/>Prends mes lèvres, que par Toi<br/>Elles parles de ma foi.<br/>',NULL,27397,4);
INSERT INTO stanza VALUES('FR79','4','Prends mon or et prends mes biens,<br/>Car, Seigneur, tout T''aapartient.<br/>Prends tous mes raisonnements,<br/>Qu''ils Te soient obéissants.<br/>',NULL,27398,5);
INSERT INTO stanza VALUES('FR79','5','Prends pour Toi ma volonté,<br/>Oui, je veux Te la céder.<br/>Prends mon cœur, car il est Tien,<br/>Qu''il devienne un bon terrain !<br/>',NULL,27399,6);
INSERT INTO stanza VALUES('FR79','6','Prends, Seigneur, tout mon amour,<br/>Qu''il augmente chaque jour !<br/>Prends mon être tout entier,<br/>Et que je sois consacré !<br/>',NULL,27400,7);
INSERT INTO stanza VALUES('FR80','1','Quelle libération quand l''âme,<br/>Du monde détachée<br/>Et sous l''autorité de Dieu,<br/>Consacre tout à Lui !<br/>À elle la vie et la mort,<br/>Le présent, l''avenir !<br/>En demeurant, en paix, en Christ,<br/>Son souffle vient de Lui.<br/>',NULL,27401,1);
INSERT INTO stanza VALUES('FR80','2','Alors que nous avons le choix,<br/>De prendre part au trône,<br/>Combien il serait insensé,<br/>De ne pas être à Lui.<br/>Ne parle pas de sacrifice !<br/>Quel glorieux privilège !<br/>De tout donner et d''être à Lui,<br/>Dans l''armée du calvaire.<br/>',NULL,27402,2);
INSERT INTO stanza VALUES('FR80','3','Debout ! Conclus le saint marché :<br/>Pour rien, tu auras tout !<br/>Tout concourra au bien de l''âme,<br/>De l''âme rachetée.<br/>Tout est à toi quand tu te donnes,<br/>Tu es un avec Lui !<br/>En Lui, la vie, la grâce, abondent<br/>Et le royaume viendra.<br/>',NULL,27403,3);
INSERT INTO stanza VALUES('FR81','1','À Toi, cher Jésus, mon Maitre,<br/>En esprit je suis uni.<br/>Tout Ton être je possède,<br/>Car en moi, Seigneur, Tu vis.<br/>',NULL,27404,1);
INSERT INTO stanza VALUES('FR81','chorus','Je suis un avec Toi !<br/>Je suis un avec Toi !<br/>Je prends part à Tes richesses.<br/>Tu es tout, oui, tout pour moi !<br/>',NULL,27405,2);
INSERT INTO stanza VALUES('FR81','2','Tu remplis ma vie humaine,<br/>De Ta fine humanité.<br/>J''apprends Ton obéissance,<br/>Ta glorieuse humilité.<br/>',NULL,27406,3);
INSERT INTO stanza VALUES('FR81','3','Avec Toi, dans Tes souffrances,<br/>Dans l''opprobre de la croix,<br/>Je suis mort, Seigneur, au monde<br/>Et le monde est mort pour moi.<br/>',NULL,27407,4);
INSERT INTO stanza VALUES('FR81','4','La victoire est mon partage,<br/>Grâce à Ta résurrection.<br/>Je jouis de Ta puissance,<br/>Qui toujours est ma portion.<br/>',NULL,27408,5);
INSERT INTO stanza VALUES('FR81','5','Ô Seigneur ! Tu me fais vivre<br/>Dans les cieux en ascension.<br/>Pèlerin sur cette terre,<br/>Je jouis de cette union.<br/>',NULL,27409,6);
INSERT INTO stanza VALUES('FR81','6','Sur le trône, dans la gloire,<br/>Tu es mon autorité.<br/>Cette vie est mon partage,<br/>Avec Toi, en Dieu cachée.<br/>',NULL,27410,7);
INSERT INTO stanza VALUES('FR82','1','Crucifié en Christ, mon Sauveur,<br/>À ce monde et au péché,<br/>Dans la vie, la vie de Jésus,<br/>Librement, je peux entrer.<br/>Je contemple le calvaire,<br/>Qu''Il souffrit, là, sur la croix<br/>Et toujours, j''ai Sa présence,<br/>En demeurant à la croix.<br/>',NULL,27411,1);
INSERT INTO stanza VALUES('FR82','chorus','Le chemin de Golgotha,<br/>Mon Sauveur l''a fait pour moi.<br/>Mon Seigneur, assiste-moi,<br/>Oh ! que je reste à la croix !<br/>',NULL,27412,2);
INSERT INTO stanza VALUES('FR82','2','Renier mon moi est simple,<br/>Quand je marche par Sa vie<br/>Et souffrir m''est préférable,<br/>Quand Sa joie mon cœur remplit.<br/>Agissant dans Sa puissance,<br/>Il fait Sa demeure en moi.<br/>Et mon cœur heureux veut vivre,<br/>En demeurant à la croix.<br/>',NULL,27413,3);
INSERT INTO stanza VALUES('FR82','3','Par la croix, nous pourrons vivre<br/>Et régner en Jésus-Christ !<br/>Dans la mort et la souffrance,<br/>La victoire est notre prix.<br/>Le matin du jour de gloire,<br/>Notre Maitre nous dira :<br/>« Vous m''avez été fidèles,<br/>En demeurant à la croix. »<br/>',NULL,27414,4);
INSERT INTO stanza VALUES('FR83','1','Je suis crucifié et libre,<br/>Je veux vivre par la croix.<br/>Alors Christ me vivifie,<br/>Lui qui vit et règne en moi.<br/>',NULL,27415,1);
INSERT INTO stanza VALUES('FR83','chorus','Qu''il est doux de mourir avec Christ,<br/>Au péché, au monde, à soi.<br/>Qu''il est doux de vivre avec mon Christ,<br/>Quand Il vit et règne en moi !<br/>',NULL,27416,2);
INSERT INTO stanza VALUES('FR83','2','Le mystère de tout age,<br/>Par la foi m''est révélé.<br/>L'' espérance de la gloire,<br/>Christ en moi m''est dévoilé !<br/>',NULL,27417,3);
INSERT INTO stanza VALUES('FR83','3','Le secret de la nature :<br/>Sous la terre croit le grain !<br/>Par la greffe, le vieux rameau<br/>Devient riche, fort et sain.<br/>',NULL,27418,4);
INSERT INTO stanza VALUES('FR83','4','Tournons-nous vers notre Tête,<br/>Car Lui seul est le chemin !<br/>Ô Seigneur, Tu nous épures !<br/>Que par Toi nous soyons saints !<br/>',NULL,27419,5);
INSERT INTO stanza VALUES('FR83','5','Lui, le baume qui m''apaise,<br/>Quand ma force je renie,<br/>Pour qu''Il soit ma plénitude,<br/>De Sa vie Il me nourrit.<br/>',NULL,27420,6);
INSERT INTO stanza VALUES('FR83','6','Pour atteindre la victoire,<br/>Notre Maitre prit la croix.<br/>Pour marcher vers notre gloire,<br/>Nous suivons la même voie !<br/>',NULL,27421,7);
INSERT INTO stanza VALUES('FR84','1','Je suis à la croix car Christ m''a crucifié,<br/>Je suis libéré de mes passions.<br/>C''est un fait glorieux, je vis par mon Seigneur,<br/>Je jouis de Sa résurrection.<br/><br/>Sur la croix de Golgotha, j''étais en Lui,<br/>J''étais en Lui, le Crucifié,<br/>Aujourd''hui, en Lui j''ai ma demeure et vis<br/>Sa vie ressuscitée.<br/>',NULL,27422,1);
INSERT INTO stanza VALUES('FR85','1','Christ est le centre, la réalité,<br/>De tout sur terre, de tout dans les cieux.<br/>La création na parle que de Lui,<br/>Tout n''est que le reflet du Christ de Dieu.<br/>',NULL,27423,1);
INSERT INTO stanza VALUES('FR85','2','Tout est une ombre, Christ en est le corps,<br/>Tout s''accomplit en Lui, le grand « Je suis ! »<br/>Types, symboles, faits des temps anciens,<br/>Se réalisent par Lui dans nos vies.<br/>',NULL,27424,2);
INSERT INTO stanza VALUES('FR85','3','Vaine est la vie car tout est vanité,<br/>Seul Christ en nous est la réalité.<br/>Nos possessions ici-bas amassées,<br/>Sans Lui nous laissent vides, affamés.<br/>',NULL,27425,3);
INSERT INTO stanza VALUES('FR85','4','Christ est l''unique dieu et seul Seigneur,<br/>Notre lumière, source de la vie.<br/>Il nous nourrit, nous sommes abreuvés.<br/>Il nous revêt de Lui, nous fortifie.<br/>',NULL,27426,4);
INSERT INTO stanza VALUES('FR85','5','Toute doctrine et tout enseignement,<br/>Sans Christ ne peuvent nourrir notre esprit.<br/>Sondons et relisons les écritures,<br/>Elles témoignent que seul Christ est vie.<br/>',NULL,27427,5);
INSERT INTO stanza VALUES('FR85','6','Christ est le centre du temps, de l''espace,<br/>De l''univers, Lui, la réalité.<br/>Christ seul est la réalité de tout,<br/>Hier, aujourd''hui, et pour l''éternité !<br/>',NULL,27428,6);
INSERT INTO stanza VALUES('FR86','1','Suprême grace, grace illimitée,<br/>C''est Dieu en Christ dont tous nous jouissons.<br/>Serait-ce un don, serait-ce une faveur ?<br/>C''est Dieu Lui-même, glorieuse portion !<br/>',NULL,27429,1);
INSERT INTO stanza VALUES('FR86','2','Dieu devint chair afin que nous puissions<br/>Le recevoir et L '' expérimenter.<br/>Telle est la grâce qui nous vient de Dieu,<br/>Nous vient par Christ, en Lui nous est donnés.<br/>',NULL,27430,2);
INSERT INTO stanza VALUES('FR86','3','L''apôtre Paul cette grâce cherchait,<br/>Seul Dieu en Christ dans son esprit comptait.<br/>Sa vie sur terre lui importait peu,<br/>Pour gagner Christ - but ultime - il courait.<br/>',NULL,27431,3);
INSERT INTO stanza VALUES('FR86','4','C''est cette grâce - Christ en nous puissant - Qui nous remplit et qui nous fortifie,<br/>Réalisant la volonté de Dieu,<br/>Depuis notre esprit, source qui jaillit.<br/>',NULL,27432,4);
INSERT INTO stanza VALUES('FR86','5','Que cette grâce - Christ en nous vivant - Soit notre vie et comble nos désirs !<br/>Puis-je la vivre et l''expérimenter !<br/>Que cette grâce puisse en moi grandir !<br/>',NULL,27433,5);
INSERT INTO stanza VALUES('FR87','1','Oh ! quelle vie ! Oh ! quelle paix !<br/>En moi vit Christ ressuscité.<br/>Il accomplit ce fait glorieux :<br/>En Lui j''ai été crucifie,<br/>Ce n''est plus moi, c''est Lui qui vit,<br/>C''est Jésus-Christ ressuscité !<br/>',NULL,27434,2);
INSERT INTO stanza VALUES('FR87','2','Oh ! quelle joie ! Oh ! quel repos !<br/>Je sais que Christ se forme en moi.<br/>Sa vraie nature en moi gravée<br/>M''emplit de Sa divine joie.<br/>Dès lors, en Lui je me confie,<br/>Car Jésus-Christ est tout en moi !<br/>',NULL,27435,3);
INSERT INTO stanza VALUES('FR87','3','Oh ! quelle gloire de savoir<br/>Qu''en moi rayonne Jésus-Christ !<br/>Aucune honte je n''aurai,<br/>Il est la source de ma vie !<br/>Que dans ma peine et dans ma joie,<br/>Toujours Jésus-Christ soit transmis !<br/>',NULL,27436,4);
INSERT INTO stanza VALUES('FR87','4','Christ est mon prix, Christ est mon gain !<br/>Il est mon but, vers Lui je cours.<br/>Lui, ma couronne et mon trésor,<br/>Il est l''objet de mon amour,<br/>Mon espérance et mon désir,<br/>Il est l''unique pour toujours !<br/>',NULL,27437,5);
INSERT INTO stanza VALUES('FR88','1','Oh ! Christ glorieux, mon Sauveur !<br/>Toi qui es divine splendeur,<br/>Dieu infini, dans l''éternité<br/>Dans l''homme Tu T''es limité.<br/>',NULL,27438,1);
INSERT INTO stanza VALUES('FR88','chorus','Ô Christ, glorieuse expression de Dieu,<br/>Insondable, riche et si doux !<br/>À l''homme, Dieu s''est mélangé.<br/>Il vit en moi, en vérité.<br/>',NULL,27439,2);
INSERT INTO stanza VALUES('FR88','2','Le Dieu trinitaire est en moi,<br/>Tu en manifestes l''éclat.<br/>Tu mourus pour la rédemption,<br/>En nous Tu vis, oh ! quelle union !<br/>',NULL,27440,3);
INSERT INTO stanza VALUES('FR88','3','Ce qui est au Père est à Toi.<br/>Dans l''Esprit, Tu es tout à moi.<br/>L ''Esprit Te rend réel en moi,<br/>Toujours, je me réjouis de Toi.<br/>',NULL,27441,4);
INSERT INTO stanza VALUES('FR88','4','Ta parole est Esprit et vie,<br/>Afin qu''en moi Tu sois transmis.<br/>En la lisant, je T''ai touché,<br/>Ta vie en moi a pénétré.<br/>',NULL,27442,5);
INSERT INTO stanza VALUES('FR88','5','Quand je Te contemple en esprit,<br/>De Ta gloire, je resplendis.<br/>Par Toi, je serai transformé,<br/>Par moi, Tu seras exprimé.<br/>',NULL,27443,6);
INSERT INTO stanza VALUES('FR88','6','Ta vie dans mon esprit, Seigneur,<br/>Me transforme et me rend vainqueur,<br/>Me sanctifie, me glorifie,<br/>Mon être entier Te magnifie.<br/>',NULL,27444,7);
INSERT INTO stanza VALUES('FR88','7','Ton Esprit me saturera,<br/>Tout mon être Tu rempliras.<br/>L''église sera édifiée,<br/>Lorsqu''en nous Tu seras œuvré.<br/>',NULL,27445,8);
INSERT INTO stanza VALUES('FR89','1','Un homme est en gloire,<br/>Sa vie en nous demeure,<br/>Si pure et si sainte,<br/>Dans tous Ses aspects.<br/>Si riche en tendresse,<br/>En amour, en sagesse.<br/>Sa vie dans la gloire<br/>Transforme à Son image<br/>Ma vie de gloire en gloire,<br/>Alléluia !<br/>',NULL,27446,1);
INSERT INTO stanza VALUES('FR89','2','Un homme est en gloire,<br/>Sa vie en nous demeure,<br/>Il a vaincu l''ennemi,<br/>Brisé tous les liens.<br/>Assis sur le trône,<br/>Il règne dans ma vie.<br/>Sa vie dans la gloire<br/>Transforme à Son image<br/>Ma vie de gloire en gloire,<br/>Alléluia !<br/>',NULL,27447,2);
INSERT INTO stanza VALUES('FR89','3','Un homme est en gloire,<br/>Sa vie en nous demeure,<br/>Aucune faiblesse<br/>Ne subsiste en Lui.<br/>Puissant, plein de force,<br/>Dans notre esprit Il brule.<br/>Sa vie dans la gloire<br/>Transforme à Son image<br/>Ma vie de gloire en gloire,<br/>Alléluia !<br/>',NULL,27448,3);
INSERT INTO stanza VALUES('FR89','4','Un homme est en gloire,<br/>Sa vie en nous demeure,<br/>Sa grande paix nous rassure,<br/>Il est si patient !<br/>Il veut nous transmettre<br/>Sa propre vie, Son être.<br/>Sa vie dans la gloire<br/>Transforme à Son image<br/>Ma vie de gloire en gloire,<br/>Alléluia !<br/>',NULL,27449,4);
INSERT INTO stanza VALUES('FR90','1','Très loin de Dieu, plein de péchés,<br/>Très sombre était mon cœur.<br/>Mais Sa Parole m''éclaira,<br/>Je reçus le Seigneur.<br/>',NULL,27450,1);
INSERT INTO stanza VALUES('FR90','chorus','Christ habite en moi,<br/>Christ habite en moi,<br/>Oh ! quel salut merveilleux !<br/>Oui, Christ habite en moi !<br/>',NULL,27451,2);
INSERT INTO stanza VALUES('FR90','2','Grâce aux rayons chauds du soleil,<br/>Les champs ont tous fleuri.<br/>De même Christ en moi produit<br/>Amour, lumière et vie.<br/>',NULL,27452,3);
INSERT INTO stanza VALUES('FR90','3','Christ a été en moi semé,<br/>En Lui je suis comblé.<br/>Il vit, grandit, se forme en moi,<br/>Pour qu''Il soit glorifié.<br/>',NULL,27453,4);
INSERT INTO stanza VALUES('FR90','4','Mon cœur aspire à devenir<br/>Obéissant, soumis.<br/>Quand je pense à ce fait glorieux,<br/>Jésus remplit ma vie !<br/>',NULL,27454,5);
INSERT INTO stanza VALUES('FR91','1','Gloire, gloire ! Christ est notre vie !<br/>Gloire, gloire ! L''Esprit nous conduit,<br/>Chasse les ténèbres, nous ramène à Lui.<br/>Alléluia ! Christ est notre vie !<br/>',NULL,27455,1);
INSERT INTO stanza VALUES('FR91','2','Gloire, gloire ! Nous vivons par Lui !<br/>Gloire, gloire ! Marchons par l''Esprit !<br/>Arrachés au monde, nous vivons pour Dieu.<br/>Gloire, gloire ! Nous vivons par Lui !<br/>',NULL,27456,2);
INSERT INTO stanza VALUES('FR92','1','Dans le jardin que Dieu planta,<br/>Un fleuve coule, un arbre croit.<br/>L''homme devait boire et manger,<br/>La vie de Dieu gagner.<br/>',NULL,27457,1);
INSERT INTO stanza VALUES('FR92','chorus','Dieu en Christ est ma satisfaction.<br/>Dans mon esprit, combien Il est bon !<br/>Dieu l''Esprit sans cesse me nourrit,<br/>De Lui je suis rempli !<br/>',NULL,27458,2);
INSERT INTO stanza VALUES('FR92','2','L''arbre dépeint le Christ glorieux,<br/>Qui est l''image de mon Dieu.<br/>Il est vivant, porte du fruit,<br/>De Lui je me nourris !<br/>',NULL,27459,3);
INSERT INTO stanza VALUES('FR92','3','Le fleuve exprime l''Esprit-Saint,<br/>Qui atteint mon esprit humain.<br/>De Sa richesse Il me remplit,<br/>Mon être sanctifie.<br/>',NULL,27460,4);
INSERT INTO stanza VALUES('FR92','4','Christ est ma gloire, Il est ma vie,<br/>Il est l''Esprit dans mon esprit.<br/>Il veut mon âme transformer,<br/>À travers moi briller.<br/>',NULL,27461,5);
INSERT INTO stanza VALUES('FR92','5','J''élèverai mon grand Sauveur,<br/>Dans l''allégresse et dans les pleurs.<br/>J''obéirai à Son Esprit,<br/>En Lui mon cœur se fie !<br/>',NULL,27462,6);
INSERT INTO stanza VALUES('FR93','1','L'' Inestimable j''ai trouvé,<br/>Mon cœur est plein de joie.<br/>Je veux chanter, toujours chanter,<br/>Ce Christ qui vit en moi !<br/>',NULL,27463,1);
INSERT INTO stanza VALUES('FR93','2','Mon Christ, Il est l''Agneau de Dieu,<br/>Car pour moi Il mourut.<br/>Lui, le Soleil de la justice,<br/>Il est mon plein salut.<br/>',NULL,27464,2);
INSERT INTO stanza VALUES('FR93','3','Mon Christ est l''arbre de la vie,<br/>Aux fruits nombreux de doux.<br/>Il satisfait toujours ma faim,<br/>Pour moi, Il devient tout.<br/>',NULL,27465,3);
INSERT INTO stanza VALUES('FR93','4','Mon Christ est le rocher frappé,<br/>D''où l''eau de vie jaillit.<br/>Il est la source dans mon cœur,<br/>Ma soif s''apaise en Lui.<br/>',NULL,27466,4);
INSERT INTO stanza VALUES('FR93','5','Je trouve en Christ lumière et vie.<br/>Il est mon seul chemin,<br/>Ma joie, ma gloire et mon repos,<br/>Ma paix et mon soutien.<br/>',NULL,27467,5);
INSERT INTO stanza VALUES('FR93','6','Christ est sagesse et vérité,<br/>Ma sanctification,<br/>Ma force et mon autorité,<br/>Il est ma rédemption.<br/>',NULL,27468,6);
INSERT INTO stanza VALUES('FR93','7','Mon Conseiller, mon Avocat,<br/>Seigneur, Sauveur, Berger,<br/>Il est mon Dieu et mon ami,<br/>Mon Frère et Bien-aimé.<br/>',NULL,27469,7);
INSERT INTO stanza VALUES('FR93','8','Christ est mon Guide et mon Gardien,<br/>Il parle et je Le suis.<br/>Il est mon Maitre et mon époux,<br/>Il dirige ma vie.<br/>',NULL,27470,8);
INSERT INTO stanza VALUES('FR93','9','Christ est Prophète, Prêtre et Roi<br/>Qui juge et tout percoit,<br/>Qui me rapproche de mon Dieu<br/>Et qui gouverne en moi.<br/>',NULL,27471,9);
INSERT INTO stanza VALUES('FR93','10','Mon Christ est l''Auteur de ma foi<br/>Et son Consommateur.<br/>Mon Médiateur et mon Garant,<br/>Qui plaide en ma faveur.<br/>',NULL,27472,10);
INSERT INTO stanza VALUES('FR94','1','Le Seigneur surpasse<br/>Ses bénédictions.<br/>Sa Parole règne<br/>Sur mes sentiments.<br/>Sa Personne j''aime,<br/>Plus que tous Ses dons<br/>Et je Le préfère<br/>À ma guérison.<br/>',NULL,27473,1);
INSERT INTO stanza VALUES('FR94','chorus','J''aime Sa Personne !<br/>Il est tout pour moi.<br/>Sa vie Il me donne,<br/>Et Lui seul est ma joie !<br/>',NULL,27474,2);
INSERT INTO stanza VALUES('FR94','2','Vaines sont mes luttes !<br/>Je me fie à Lui.<br/>C''est Lui qui me sauve,<br/>Qui tout accomplit.<br/>Parfois je m''agrippe,<br/>Et cherche un soutien.<br/>Mais j''ai jeté l''ancre,<br/>C''est Lui qui la tient.<br/>',NULL,27475,3);
INSERT INTO stanza VALUES('FR94','3','Je voulais moi-même<br/>Gouverner ma vie,<br/>Je cherchais à prendre<br/>Sur moi mes soucis.<br/>Enfin je discerne,<br/>Que la barre Il tient.<br/>Je Le loue sans cesse,<br/>Je suis dans Sa main.<br/>',NULL,27476,4);
INSERT INTO stanza VALUES('FR94','4','Tout m''était pénible,<br/>Ma charge Il ôta.<br/>Je n''ai qu''à Le suivre,<br/>Il conduit mes pas.<br/>J''ai laissé mon œuvre,<br/>Pour qu''Il s''œuvre en moi.<br/>Il est ma puissance,<br/>Dans tous mes combats.<br/>',NULL,27477,5);
INSERT INTO stanza VALUES('FR94','5','Aujourd''hui j''affirme,<br/>Que Jésus est mien.<br/>Grâce à Lui ma lampe<br/>Jamais ne s''éteint.<br/>Pour Lui je me pare,<br/>J''attends Sa venue,<br/>Lui mon espérance,<br/>Lui mon seul salut.<br/>',NULL,27478,6);
INSERT INTO stanza VALUES('FR95','1','Tu es, Jésus, mon univers,<br/>Ma vie, ma joie, mon gain.<br/>Tu me prodigues Tes bontés,<br/>Me gardes dans Ta main.<br/>Quand je suis las, à Toi je viens,<br/>Tu me consoles, me soutiens,<br/>Je crie à Toi, Tu es mon Bien,<br/>Mon Ami !<br/>',NULL,27479,1);
INSERT INTO stanza VALUES('FR95','2','Tu es, Jésus, mon univers,<br/>Présent dans mes douleurs,<br/>Je viens à Toi, Tu me bénis,<br/>De toutes Tes faveurs.<br/>Toi, mon soleil qui resplendit,<br/>Tu es la pluie qui rafraichit,<br/>Qui, en mon cœur, produit du fruit,<br/>Mon Ami !<br/>',NULL,27480,2);
INSERT INTO stanza VALUES('FR95','3','Tu es, Jésus, mon univers,<br/>Fidèle je serai !<br/>Comment renier ce grand Ami<br/>Qui s''est pour moi livré ?<br/>Je suis heureux quand je Te suis,<br/>Tu me protèges jour et nuit.<br/>Dans Tes sentiers, Tu me conduis,<br/>Mon Ami.<br/>',NULL,27481,3);
INSERT INTO stanza VALUES('FR95','4','Tu es, Jésus, mon univers,<br/>Toi, mon meilleur Ami.<br/>Tout prendra fin, tout passera,<br/>En Toi je me confie !<br/>L''éternité est devant moi,<br/>Quand en mon Dieu je mets ma foi.<br/>Tu es, Jésus, ma vie, ma joie,<br/>Mon Ami !<br/>',NULL,27482,4);
INSERT INTO stanza VALUES('FR96','1','Dévoiler en moi Jésus-Christ<br/>Est le bon plaisir de Dieu,<br/>Mais les formes religieuses<br/>Ne font que voiler mes yeux.<br/>',NULL,27483,1);
INSERT INTO stanza VALUES('FR96','chorus','Que Christ gagne tout mon être,<br/>C''est Son plan, Sa volonté.<br/>Toute forme humaine est vaine,<br/>Qu''Il soit na réalité !<br/>',NULL,27484,2);
INSERT INTO stanza VALUES('FR96','2','Que Son christ puisse en moi vivre,<br/>C''est de Dieu le bon plaisir.<br/>Je ne veux pas de routine,<br/>Mais toujours en Christ agir.<br/>',NULL,27485,3);
INSERT INTO stanza VALUES('FR96','3','Que Son Fils en moi se forme,<br/>C''est le bon plaisir de Dieu.<br/>Dieu n''agrée pas d''œuvres mortes.<br/>Christ doit croitre, c''est Son vœu.<br/>',NULL,27486,4);
INSERT INTO stanza VALUES('FR96','4','Que Son Fils en moi demeure,<br/>C''est de Dieu le bon plaisir.<br/>Il nous oint et nous enseigne<br/>À toujours Lui obéir.<br/>',NULL,27487,5);
INSERT INTO stanza VALUES('FR96','5','C''est Son plan, ce qu''Il désir,<br/>Que je sois en Lui trouvé.<br/>Je ne cherche et ne désir<br/>Que Lui pour l''éternité.<br/>',NULL,27488,6);
INSERT INTO stanza VALUES('FR97','1','Seigneur, Tu es en moi la vie<br/>Et Tu es tout pour moi.<br/>Tu es toujours à ma portée,<br/>Je marche et vis par Toi.<br/>',NULL,27489,1);
INSERT INTO stanza VALUES('FR97','chorus','Seigneur, Tu es accessible,<br/>Tu es l''Esprit de vie !<br/>Toujours si proche, à ma portée,<br/>Mon cœur Tu réjouis !<br/>',NULL,27490,2);
INSERT INTO stanza VALUES('FR97','2','toujours Tu combles mes besoins,<br/>Qu''ils soient grands ou petits.<br/>Dans mes faiblesses, je suis fort,<br/>En tout Tu me suffis.<br/>',NULL,27491,3);
INSERT INTO stanza VALUES('FR97','3','Ta douce onction opère en moi,<br/>Me guide, me soutient.<br/>Toi qui m''assistes chaque jour,<br/>Mes forces Tu maintiens.<br/>',NULL,27492,4);
INSERT INTO stanza VALUES('FR97','4','Ta loi de vie dans mon esprit,<br/>Mon cœur veut gouverner.<br/>Par les richesses de Ta vie<br/>Mon être est rassasié.<br/>',NULL,27493,5);
INSERT INTO stanza VALUES('FR97','5','Tu es en moi, je suis en Toi,<br/>Suprême vérité !<br/>Union qui fut scellée par Dieu,<br/>Pour toute éternité !<br/>',NULL,27494,6);
INSERT INTO stanza VALUES('FR98','1','Seigneur, je T''aime, mais de Ton amour,<br/>Car je n''ai pas d''amour.<br/>L''amour que j''ai pour Toi, Seigneur, je sais<br/>N''est rien d''autre que Toi.<br/>Vide, inutile, je n''ai rien sans Toi.<br/>Je suis perdu et immergé en Toi.<br/>',NULL,27495,1);
INSERT INTO stanza VALUES('FR98','2','Toi seul, Seigneur, est ce dont Tes enfants<br/>Ont maintenant besoin.<br/>Quand en Toi nous demeurons, nous avons<br/>Ta vie si abondante.<br/>Source de vie et grâce illimitée,<br/>Notre univers, notre centre et demeure.<br/>',NULL,27496,2);
INSERT INTO stanza VALUES('FR99','1','J''ai reçu Son évangile,<br/>Alléluia pour l''Agneau !<br/>Franchi l''aire du parvis,<br/>Oh ! gloire à notre Dieu !<br/>Oui, je suis du bon coté,<br/>Sur l''autel suis sanctifié,<br/>Mort au monde et au péché,<br/>Alléluia pour l''Agneau !<br/>',NULL,27497,1);
INSERT INTO stanza VALUES('FR99','chorus','Alléluia ! Alléluia !<br/>Oui, j''ai traversé le voile,<br/>Là, j''ai contemplé Sa gloire.<br/>Alléluia ! Alléluia !<br/>Maintenant, je vis toujours devant le Roi !<br/>',NULL,27498,2);
INSERT INTO stanza VALUES('FR99','2','Par le sang Il fait de moi<br/>Alléluia pour l''Agneau !<br/>Sacrificateur et roi,<br/>Oh ! gloire à notre Dieu !<br/>Que ma vie, par Son Esprit,<br/>De lumière soit remplie,<br/>Dans le Saint des Saints qui brille,<br/>Alléluia pour l''Agneau !<br/>',NULL,27499,3);
INSERT INTO stanza VALUES('FR99','3','Le premier voile écarté,<br/>Alléluia pour l''Agneau !<br/>La lumière a éclaté,<br/>Oh ! gloire à notre Dieu !<br/>Et le sang m''a fait entrer,<br/>Dans le lieu de sainteté !<br/>Fin au moi et au péché,<br/>Alléluia pour l''Agneau !<br/>',NULL,27500,4);
INSERT INTO stanza VALUES('FR99','4','Le second voile est franchi,<br/>Alléluia pour l''Agneau !<br/>Dans le Saint des Saints je vis,<br/>Oh ! gloire à notre Dieu !<br/>Mon Dieu, en me sanctifiant,<br/>Par l''application du sang,<br/>Est ma demeure à présent,<br/>Alléluia pour l''Agneau !<br/>',NULL,27501,5);
INSERT INTO stanza VALUES('FR100','1','Quelle communion, quelle immense joie :<br/>Le Dieu tout-puissant est mon soutien !<br/>Sa vie me remplit, Sa paix règne en moi,<br/>Son bras éternel est mon soutien !<br/>',NULL,27502,1);
INSERT INTO stanza VALUES('FR100','chorus','Soutien, soutien,<br/>J''ai tout remis entre Ses mains.<br/>Soutien, soutien,<br/>Son bras éternel est mon soutien !<br/>',NULL,27503,2);
INSERT INTO stanza VALUES('FR100','2','Marchant avec joie comme un pèlerin,<br/>Le Dieu tout-puissant est mon soutien !<br/>Toujours plus radieux s''ouvre mon chemin,<br/>Son bras éternel est mon soutien !<br/>',NULL,27504,3);
INSERT INTO stanza VALUES('FR100','3','Pourquoi m''effrayer, qu''ai-je à redouter ?<br/>Le Dieu tout-puissant est mon soutien !<br/>tout près du Seigneur, je suis rassuré,<br/>Son bras éternel est mon soutien !<br/>',NULL,27505,4);
INSERT INTO stanza VALUES('FR101','1','Demeure en Christ et Tu seras béni,<br/>Demeure en Lui pour être uni à Lui.<br/>À chaque instant, chéris la communion,<br/>Que rien ne vienne briser cette union !<br/>',NULL,27506,1);
INSERT INTO stanza VALUES('FR101','2','Demeure en Christ et l''onction coulera,<br/>En communion, l''Esprit te guidera.<br/>En Le suivant, tu jouiras de Lui,<br/>De Ses richesses, tu seras rempli.<br/>',NULL,27507,2);
INSERT INTO stanza VALUES('FR101','3','Demeure en Lui, tu seras éclairé.<br/>En communion, les voiles sont otés.<br/>Dans la lumière, Sa vie grandira,<br/>En Lui, ton ame se réjouira.<br/>',NULL,27508,3);
INSERT INTO stanza VALUES('FR101','4','Demeure en Christ, en Lui tu seras fort<br/>Et Sa vie engloutira toute mort.<br/>Il changera tes soupirsen des chants.<br/>En Lui, te seras pour toujours vivant.<br/>',NULL,27509,4);
INSERT INTO stanza VALUES('FR101','5','Demeure en Lui et Satan tu vaincras,<br/>Le monde n''aura plus d''attrait pour toi.<br/>En communion, ton moi est crucifié,<br/>Le pouvoir du péché est annulé.<br/>',NULL,27510,5);
INSERT INTO stanza VALUES('FR101','6','Demeure en Lui, tu seras transformé,<br/>Tu grandiras jusqu''à maturité.<br/>Tu connaitra Christ dans la communion,<br/>Lui, Sa puissance de résurrection.<br/>',NULL,27511,6);
INSERT INTO stanza VALUES('FR101','7','Mon cœur après Toi languit chaque jour,<br/>En Toi, je veux demeurer pour toujours.<br/>Que tout mon être soit perdu en Toi,<br/>À jamais, Seigneur, tu seras à moi !<br/>',NULL,27512,7);
INSERT INTO stanza VALUES('FR102','1','Tu as dis : « Je suis le vrai cep,<br/>Et vous êtes les sarments »,<br/>Mais je ne comprends pas pourquoi<br/>Je ne porte pas de fruit.<br/>',NULL,27513,1);
INSERT INTO stanza VALUES('FR102','2','Je voudrais tant porter du fruit,<br/>Afin de mieux T''exprimer<br/>Et Seigneur, Ton nom glorifier,<br/>Accomplir Ta volonté.<br/>',NULL,27514,2);
INSERT INTO stanza VALUES('FR102','3','Mais je ne comprends pas, Seigneur,<br/>Que veut dire : « demeurez ».<br/>Plus je tente de demeurer,<br/>Moins je me sens près de Toi.<br/>',NULL,27515,3);
INSERT INTO stanza VALUES('FR102','4','Malgré mes nombreuses prières,<br/>En Toi, je n''habite pas.<br/>Tu me sembles si loin de moi,<br/>Et ma vie, vide de Toi.<br/>',NULL,27516,4);
INSERT INTO stanza VALUES('FR102','5','Cependant, Tu le dis Seigneur :<br/>En Toi, je suis un sarment.<br/>Quand je Te prends, Toi mon Sauveur,<br/>Ce fait devient si réel.<br/>',NULL,27517,5);
INSERT INTO stanza VALUES('FR102','6','Maintenant, je me trouve en Toi,<br/>Pourquoi chercher à entrer ?<br/>Car je suis uni avec Toi,<br/>Un avec Ta chair, Ton sang.<br/>',NULL,27518,6);
INSERT INTO stanza VALUES('FR102','7','Le secret, ce n''est pas « d''entrer »,<br/>Mais voir que j''y suis déjà.<br/>Je ne prie pas d''entrer en Toi,<br/>Mais de n''en jamais sortir.<br/>',NULL,27519,7);
INSERT INTO stanza VALUES('FR102','8','J''y suis déjà ! Je suis en Toi !<br/>Tu m''amenas en ce lieu.<br/>Rien ne sert de lutter, prier,<br/>Car Dieu a déjà œuvré.<br/>',NULL,27520,8);
INSERT INTO stanza VALUES('FR102','9','Je suis déjà entré en Toi,<br/>Pourquoi chercher à entrer ?<br/>De Ta Parole je jouis,<br/>Qui me dit qu''en Toi je suis.<br/>',NULL,27521,9);
INSERT INTO stanza VALUES('FR102','10','Je suis dans le repos en Toi,<br/>Car mon moi est à la croix.<br/>Pour moi, Tu es tout et en tous,<br/>Tu es vie, Tu es puissance.<br/>',NULL,27522,10);
INSERT INTO stanza VALUES('FR103','1','Demeure aux pieds de ton Sauveur,<br/>Quel merveilleux et doux bonheur.<br/>Je crois en Lui, je suis comblé,<br/>Je reste dans le Crucifié.<br/>',NULL,27523,1);
INSERT INTO stanza VALUES('FR103','chorus','Demeure ! Demeure !<br/>Oh ! quelle douceur !<br/>Aux pieds du Sauveur,<br/>Où est mon repos.<br/>',NULL,27524,2);
INSERT INTO stanza VALUES('FR103','2','Il parle pour donner Sa paix,<br/>Ce don du ciel, quel don parfait !<br/>La paix du monde ne m''est rien,<br/>La paix céleste je détiens !<br/>',NULL,27525,3);
INSERT INTO stanza VALUES('FR103','3','Et si je vis, ce n''est plus moi,<br/>C''est Lui qui œuvre quand je crois<br/>Et mort à moi, pour Lui je vis !<br/>Ce que je perds est gain en Lui !<br/>',NULL,27526,4);
INSERT INTO stanza VALUES('FR103','4','Mon cœur a trouvé son repos,<br/>Car Christ a pris tous mes fardeaux.<br/>Mon âme emplie de paix s''emploie<br/>À dire au monde entier sa joie !<br/>',NULL,27527,5);
INSERT INTO stanza VALUES('FR104','1','En Toi demeurer ! Amour merveilleux !<br/>Jésus, Seigneur, divin Agneau de Dieu.<br/>Proches, comme le cep et les sarments,<br/>En Toi je demeurerai, mon Seigneur.<br/>',NULL,27528,1);
INSERT INTO stanza VALUES('FR104','2','En Toi demeurer ! Mon Sauveur, mon Dieu,<br/>Fleuve d''amour, Tu coules en moi des cieux.<br/>Mon vase vide comblé de Ta joie,<br/>Doit sans mélange déborder de Toi.<br/>',NULL,27529,2);
INSERT INTO stanza VALUES('FR104','3','En Toi demeurer ! Ni doute ou péché,<br/>À Ta vie en moi, ne peut résister.<br/>En communion profonde, à Toi unie,<br/>Mon âme est gouvernée par Ton Esprit.<br/>',NULL,27530,3);
INSERT INTO stanza VALUES('FR104','4','En Toi demeurer ! Et je connaitrai,<br/>Ici-bas, de Ta pensée les secrets,<br/>Et en Ta Parole la connaissance,<br/>Tout fruit, pour tout servie, Ta puissance.<br/>',NULL,27531,4);
INSERT INTO stanza VALUES('FR105','1','Confiant en Lui chaque jour,<br/>Confiant quand la route est dure,<br/>Même quand ma foi est frêle,<br/>Ma confiance est en Jésus.<br/>',NULL,27532,1);
INSERT INTO stanza VALUES('FR105','chorus','Confiant quand les heures passent,<br/>Confiant quand les jours s''envolent,<br/>Dans la joie, dans la tristesse,<br/>Ma confiance est en Jésus.<br/>',NULL,27533,2);
INSERT INTO stanza VALUES('FR105','2','Son Esprit éclatant brille,<br/>Dans mon pauvre cœur fragile.<br/>Sa conduite est mon salut,<br/>Ma confiance est en Jésus.<br/>',NULL,27534,3);
INSERT INTO stanza VALUES('FR105','3','Chantant quand la route est claire<br/>Et priant quand elle est raide,<br/>Peu importent les tempêtes,<br/>Ma confiance est en Jésus.<br/>',NULL,27535,4);
INSERT INTO stanza VALUES('FR105','4','Confiant pour ma vie entière,<br/>Tant que tournera la terre,<br/>Jusqu''à Son avènement,<br/>Ma confiance est en Jésus.<br/>',NULL,27536,5);
INSERT INTO stanza VALUES('FR106','1','Ma volonté s''est affaiblie<br/>Et mon espoir s''est envolé.<br/>En Ta seule œuvre, je me fie,<br/>Tu me soutiens et me conduis.<br/>',NULL,27537,1);
INSERT INTO stanza VALUES('FR106','2','Tous mes efforts ont échoué,<br/>Comme autrefois, je suis tombé.<br/>Mais Ta patience est mon salut,<br/>Tu peux toujours me pardonner.<br/>',NULL,27538,2);
INSERT INTO stanza VALUES('FR106','3','Lorsque mon cœur est exalté,<br/>Je suis si près de trébucher.<br/>Je n''ose rien faire ou penser,<br/>Toi seul, Seigneur, dois opérer !<br/>',NULL,27539,3);
INSERT INTO stanza VALUES('FR106','4','Toi mon Sauveur et mon soutien !<br/>Je veux Ta face rechercher.<br/>Quand je suis faible et accablé,<br/>Ta grâce seule est mon rocher !<br/>',NULL,27540,4);
INSERT INTO stanza VALUES('FR107','1','J''étais mort en Adam, dans l''iniquité.<br/>Maintenant, je vis, car Christ m''a engendré.<br/>Dans ma chair, j''exprime le vieil homme Adam,<br/>En esprit, je magnifie le Christ vivant.<br/>',NULL,27541,1);
INSERT INTO stanza VALUES('FR107','2','Quand j''étais en Adam, même sans pécher,<br/>Pécheur par nature, j''étais condamné.<br/>Mais en Christ, mon Sauveur, même sans œuvrer,<br/>Je suis juste aux yeux de Dieu et approuvé.<br/>',NULL,27542,2);
INSERT INTO stanza VALUES('FR107','3','Dans ma chair domine, malgré mes efforts,<br/>D''Adam la nature qui me met à mort.<br/>En esprit, je vis Christ pour Le glorifier,<br/>De mes vaines luttes je suis libéré.<br/>',NULL,27543,3);
INSERT INTO stanza VALUES('FR107','4','Le vieil homme est mort car Christ l''a crucifié,<br/>Je vis dans la foi au Christ ressuscité.<br/>En plaçant mes pensées sur le Saint-Esprit,<br/>Je soumets ma chair et je vis par Sa vie.<br/>',NULL,27544,4);
INSERT INTO stanza VALUES('FR107','5','Mes pensée je place sur le Saint-Esprit.<br/>De la loi du péché je suis affranchi<br/>Et les convoitises ne me trompent plus.<br/>Je jouis en tout temps de ce plein salut.<br/>',NULL,27545,5);
INSERT INTO stanza VALUES('FR107','6','Mes pensées je place sur le Saint-Esprit,<br/>C''est Christ qui me sauve, car Sa croix agit.<br/>Sa résurrection peut œuvrer puissamment,<br/>Je Le vis, Il grandit, en moi se répand.<br/>',NULL,27546,6);
INSERT INTO stanza VALUES('FR107','7','Ce n''est que dans l''Esprit que Christ est ma vie<br/>Et c''est dans mon esprit qu''Il me fortifie.<br/>Par Son Esprit, je suis sauvé, sanctifié,<br/>Dans mon esprit, Il est ma réalité.<br/>',NULL,27547,7);
INSERT INTO stanza VALUES('FR108','1','En moi, Christ habite :<br/>Lui-même est ma vie.<br/>En Lui je demeure,<br/>Car nous somme unis.<br/>',NULL,27548,1);
INSERT INTO stanza VALUES('FR108','chorus','En esprit je marche,<br/>Sa paix me remplit,<br/>Sa vie en moi règne<br/>Et je vis par Lui.<br/>',NULL,27549,2);
INSERT INTO stanza VALUES('FR108','2','Jésus me libère,<br/>Par Sa loi de vie.<br/>Plus rien ne m''oppresse<br/>Quand je viens à Lui.<br/>',NULL,27550,3);
INSERT INTO stanza VALUES('FR108','3','Sur l''Esprit je place<br/>Toutes mes pensées.<br/>Dieu les renouvelle,<br/>Pour me transformer.<br/>',NULL,27551,4);
INSERT INTO stanza VALUES('FR108','4','Tout, en Lui, j''endure,<br/>Car Il me rend fort.<br/>Sa puissance opère,<br/>Vivifie mon corps.<br/>',NULL,27552,5);
INSERT INTO stanza VALUES('FR108','5','L ''Esprit-Saint m''assure,<br/>De puis mon esprit,<br/>Que de Dieu j''hérite<br/>Tout en Jésus-Christ.<br/>',NULL,27553,6);
INSERT INTO stanza VALUES('FR109','1','Nous chantons au Seigneur de notre esprit,<br/>Nous chantons de notre être intérieur,<br/>Nous chantons : Jésus-Christ, Alléluia !<br/>Notre esprit est uni avec Lui.<br/>',NULL,27554,1);
INSERT INTO stanza VALUES('FR109','2','Durant des années nous avons cherché,<br/>Nous avons erré dans nos pensées,<br/>Nous avons été dans la religion,<br/>Cherchant toujours désespérément.<br/>',NULL,27555,2);
INSERT INTO stanza VALUES('FR109','3','Maintenant, vers l''esprit nous nous tourons,<br/>Apprenant à manger Jésus.<br/>Désormais déchargés de nos efforts,<br/>Nous nous ouvrons à Lui simplement.<br/>',NULL,27556,3);
INSERT INTO stanza VALUES('FR109','4','Alléluia, la vie est dans l''esprit !<br/>Alléluia, par Lui, nous marchons.<br/>En tout temps, vers l''esprit, nous nous tournons,<br/>Jésus-Christ devient notre portion.<br/>',NULL,27557,4);
INSERT INTO stanza VALUES('FR110','1','En mangeant tous les jours Jésus,<br/>De Sa vie nous serons remplis,<br/>Rien ne pourra nous opprimer,<br/>Cet homme a déjà tout gagné !<br/>Mangeons plus de Jésus !<br/>Mangeons plus de Jésus !<br/>Pourquoi encore être affamés ?<br/>Nous avons Son humanité !<br/>',NULL,27558,1);
INSERT INTO stanza VALUES('FR110','2','Buvant Jésus à chaque instant,<br/>Nous Le laissons de nous jaillir,<br/>Torrents et fleuves jailliront,<br/>Satisferont les assoiffés.<br/>Buvons plus de Dieu !<br/>Buvons plus de Dieu !<br/>Pourquoi encore être assoiffés ?<br/>Nous avons Son humanité !<br/>',NULL,27559,2);
INSERT INTO stanza VALUES('FR110','3','Mangeant Jésus, tous nous pourrons<br/>Accomplir son plan sur la terre,<br/>Un homme sera exprimé,<br/>Par Son église en chaque ville.<br/>Mangeons ! Buvons Jésus !<br/>Mangeons ! Buvons Jésus !<br/>Et nous viendrons aux réunions,<br/>Offrir Jésus, notre portion.<br/>',NULL,27560,3);
INSERT INTO stanza VALUES('FR111','1','Nous mangeons Christ, le pain de vie,<br/>Nous buvons Christ, l''eau qui jaillit.<br/>Oui, celui qui boira n''aura<br/>Plus jamais, jamais, jamais soif !<br/><br/>Quoi ! Jamais, jamais soif ?<br/>Non ! Jamais, jamais soif !<br/>Quoi ! Jamais, jamais soif ?<br/>Non ! Jamais, jamais soif !<br/>Oui, celui qui boira n''aura<br/>Plus jamais, jamais, jamais soif !<br/>',NULL,27561,1);
INSERT INTO stanza VALUES('FR111','2','Nous mangeons Christ, le pain vivant,<br/>Le festin déjà préparé.<br/>Quiconque mangera n''aura<br/>Plus jamais, jamais, jamais faim !<br/><br/>Quoi ! Jamais, jamais faim ?<br/>Non ! Jamais, jamais faim !<br/>Quoi ! Jamais, jamais faim ?<br/>Non ! Jamais, jamais faim !<br/>Quiconque mangera n''aura<br/>Plus jamais, jamais, jamais faim !<br/>',NULL,27562,2);
INSERT INTO stanza VALUES('FR111','3','Nous respirons le souffle saint,<br/>Nous recevons l''Esprit divin.<br/>Quiconque s''ouvrira à Christ,<br/>La vie de Dieu en lui viendra.<br/><br/>Quoi ! Dieu en lui viendra ?<br/>Oui ! Dieu en lui viendra !<br/>Quoi ! Dieu en lui viendra ?<br/>Oui ! Dieu en lui viendra !<br/>Quiconque s''ouvrira à Christ,<br/>La vie de Dieu en lui viendra.<br/>',NULL,27563,3);
INSERT INTO stanza VALUES('FR111','4','Nous goûtons au vin de la vie,<br/>Le vin divin dans notre esprit,<br/>Quiconque boira de ce vin<br/>Aura en lui la joie de Dieu.<br/><br/>Quoi ! Il aura la joie ?<br/>Oui ! Il aura la joie.<br/>Quoi ! Il aura la joie ?<br/>Oui ! Il aura la joie.<br/>Quiconque boira de ce vin<br/>Aura en lui la joie de Dieu.<br/>',NULL,27564,4);
INSERT INTO stanza VALUES('FR111','5','Christ est le Roi ressuscité,<br/>Qui mourut pour Sa vie donner.<br/>Reçois-Le et tu chanteras<br/>Et pour l''éternité vivras !<br/><br/>Quoi ! Pour l''éternité ?<br/>Oui ! Pour l''éternité !<br/>Quoi ! Pour l''éternité ?<br/>Oui ! Pour l''éternité !<br/>Reçois-Le et tu chanteras<br/>Et pour l''éternité vivras !<br/>',NULL,27565,5);
INSERT INTO stanza VALUES('FR112','1','Bois au fleuve pur qui sort du trône de l''Agneau,<br/>L''arbre de la vie pousse au milieu de ce cours d''eau.<br/>Christ est la lumière qui nous éclaire et conduit :<br/>Il n''y a plus de nuit !<br/>',NULL,27566,1);
INSERT INTO stanza VALUES('FR112','chorus','Viens boire ! Ô viens boire !<br/>L ''Esprit, l''épouse disent :<br/>Viens boire ! Ô viens boire !<br/>À cette source puise !<br/>Viens boire ! Ô viens boire !<br/>Et sois rempli de Lui,<br/>Car Christ est l''eau de la vie.<br/>',NULL,27567,2);
INSERT INTO stanza VALUES('FR112','2','Christ est l''eau de la vie et la source qui jaillit.<br/>Lui aussi est l''arbre de la vie qui nous nourrit,<br/>La lumière et le jour, notre approvisionnement<br/>Riche et abondant !<br/>',NULL,27568,3);
INSERT INTO stanza VALUES('FR112','3','Nous lavons nos robes pour avoir droit à la vie.<br/>« Seigneur, amen, alléluia ! » Jésus rassasie !<br/>Nous exerçons notre esprit pour L''expérimenter,<br/>En Lui demeurer !<br/>',NULL,27569,4);
INSERT INTO stanza VALUES('FR112','4','Nous avons enfin trouvé l''église, Sa maison.<br/>Ici, tous ensembles, pour Son Corps nous nous donnons !<br/>Jésus nous rassemble et en nous est manifesté,<br/>Christ est magnifié !<br/>',NULL,27570,5);
INSERT INTO stanza VALUES('FR113','1','Nous avons trouvé le Christ glorieux,<br/>Insondable et riche en nous.<br/>Invoquer Son nom, c''est merveilleux !<br/>Chaque jour Il est si doux !<br/>',NULL,27571,1);
INSERT INTO stanza VALUES('FR113','chorus','Quelle joie comblée de gloire et insondable,<br/>Insondable, insondable !<br/>Quelle joie comblée de gloire et insondable,<br/>Ce trésor devient toujours plus riche !<br/>',NULL,27572,2);
INSERT INTO stanza VALUES('FR113','2','Nous avons trouvé le Christ Esprit,<br/>Qui dans notre esprit demeure.<br/>Il est accessible dans nos vies,<br/>Rien n''égale Sa douceur.<br/>',NULL,27573,3);
INSERT INTO stanza VALUES('FR113','3','Nous avons trouvé qu''en L''invoquant<br/>Nous pouvons vivre par Lui.<br/>Nous prions Sa Parole en tout temps,<br/>Davantage Il nous remplit.<br/>',NULL,27574,4);
INSERT INTO stanza VALUES('FR113','4','Son église nous avons trouvé :<br/>Nous voici à la maison !<br/>Babylone nous avons laissé,<br/>En quittant les divisions !<br/>',NULL,27575,5);
INSERT INTO stanza VALUES('FR113','5','Nous avons trouvé que réunis,<br/>Nous goûtons à la vraie joie.<br/>C''est ici que notre esprit revit,<br/>La bénédiction reçoit.<br/>',NULL,27576,6);
INSERT INTO stanza VALUES('FR114','1','Je T''aime, ô Jésus,<br/>Ton amour ardent<br/>Nous entraine à Te suivre,<br/>Vers Toi nous courons !<br/>Nous entraine à Te suivre,<br/>Vers Toi nous courons !<br/>Tu es, Bien-aimé,<br/>Si merveilleux et glorieux.<br/>Mon cœur de réjouit en Toi seul.<br/>',NULL,27577,2);
INSERT INTO stanza VALUES('FR114','2','Jésus, Ton amour<br/>Vaut mieux que le vin,<br/>Et Ton nom est un parfum,<br/>D''un nard si précieux ;<br/>Et Ton nom est un parfum,<br/>D''un nard si précieux.<br/>Ta table, mon Roi,<br/>Est riche en mets succulents;<br/>Ton grand chef - d''œuvre en moi se forme.<br/>',NULL,27578,3);
INSERT INTO stanza VALUES('FR114','3','Viens voir, Bien-aimé,<br/>Fleurir mon jardin.<br/>Viens sentir les arômes<br/>De précieux parfums.<br/>Viens sentir les arômes<br/>De précieux parfums.<br/>Descends, mon amour,<br/>Viens admirer Ton jardin,<br/>Réjouis-Toi du miel et du vin !<br/>',NULL,27579,4);
INSERT INTO stanza VALUES('FR115','1','Cher Seigneur, Ta beauté me captive,<br/>À Toi, j''ouvre largement mon cœur.<br/>Enfin délivré des œuvres mortes,<br/>Laisse-moi en Toi seul demeurer.<br/>Ici je veux contempler Ta gloire !<br/>Remplis-moi de Ton éclat divin,<br/>œuvre-Toi en moi, oh ! je T''implore,<br/>Et mélange Ton Esprit au mien.<br/>',NULL,27580,5);
INSERT INTO stanza VALUES('FR115','2','Tu resplendis dans le ciel azuré,<br/>Fils de l''homme, Tu es sur le trône.<br/>Par Toi, mon être entier est embrasé,<br/>Tout-Puissant, Ton feu m''a consumé.<br/>Quand pour la première fois, je Te vis,<br/>Ma fierté tomba dans le mépris.<br/>Maintenant, Seigneur, mon cœur Te chante !<br/>En goûtant la douceur de Ton nom.<br/>',NULL,27581,2);
INSERT INTO stanza VALUES('FR115','3','Je T''apporte mon vase d''albâtre,<br/>Récipient d''un parfum de grand prix.<br/>Je le brise de bon cœur, cher Maitre !<br/>Je veux oindre Tes pieds, Bien-aimé.<br/>Ô Jésus, sur Toi je répands l''amour !<br/>Qui émane du fond de mon cœur.<br/>Ton amour me satisfait pour toujours,<br/>Pour Toi, je veux garder le meilleur.<br/>',NULL,27582,3);
INSERT INTO stanza VALUES('FR115','4','Et sur les montagnes des aromates,<br/>Bien-aimé, je languis de Te voir.<br/>Viens boire à la fontaine de mon cœur,<br/>Viens Te reposer dans Ton jardin.<br/>Je T''adore, aux autres saints me joignant,<br/>Nous voici, l''épouse désirée.<br/>Reviens vite, car notre amour T''attend,<br/>Cher Seigneur, Tu seras satisfait.<br/>',NULL,27583,4);
INSERT INTO stanza VALUES('FR116','1','Jésus, pays tout-inclusif<br/>Est maintenant en nous,<br/>Pays de lacs et de ruisseaux,<br/>Dans les vallées et sur les monts,<br/>Nous Le buvons, nous débordons,<br/>Eau qui jaillit, source de vie :<br/>Notre Christ !<br/>',NULL,27584,1);
INSERT INTO stanza VALUES('FR116','2','Dieu s''est fait chair, puis Il mourut,<br/>Pays où croit le blé.<br/>Pays où d''abord l''orge pousse,<br/>Christ est ressuscité.<br/>Pays de vignes dont le vin<br/>Sert à réjouir Dieu et les Siens.<br/>Nous Le goûtons, nous L''appliquons :<br/>Notre Christ !<br/>',NULL,27585,2);
INSERT INTO stanza VALUES('FR116','3','Notre Christ est riche, abondant,<br/>Il est le grenadier.<br/>Et Il nous oint par Son Esprit,<br/>Il est notre olivier.<br/>Pays où coulent miel et lait,<br/>Christ nous nourrit, nous satisfait.<br/>Quelle jouissance et abondance :<br/>Notre Christ !<br/>',NULL,27586,3);
INSERT INTO stanza VALUES('FR116','4','Dans ce pays, tous nous avons<br/>Du pain à satiété.<br/>En Lui, de rien nous ne manquons :<br/>Il est illimité.<br/>Riche et complet, ce bon pays<br/>À tous égards, nous réjouit.<br/>En nous Il vit, dans notre esprit :<br/>Notre Christ !<br/>',NULL,27587,4);
INSERT INTO stanza VALUES('FR116','5','Pays où les pierres sont fer,<br/>Source d''autorité !<br/>Nous extrayons ce Christ puissant,<br/>Pour l''ennemi lier.<br/>Par les souffrances, il faut passer,<br/>Par le feu être purifié,<br/>Nous devenons ainsi brillants,<br/>C''est Son plan !<br/>',NULL,27588,5);
INSERT INTO stanza VALUES('FR116','6','Père, merci pour ce pays,<br/>C''est Christ, notre portion !<br/>En Lui, nous voulons moissonner<br/>Des fruits pour Ta maison.<br/>Enseigne-nous à travailler,<br/>Sur cette terre illimitée.<br/>Nous partageons notre portion :<br/>Notre Christ !<br/>',NULL,27589,6);
INSERT INTO stanza VALUES('FR117','1','Tabernacle en bois précieux,<br/>Bois d''acacia couvert d''or :<br/>Humanité transformée,<br/>Vie divine à l''homme mélangée.<br/>',NULL,27590,1);
INSERT INTO stanza VALUES('FR117','2','Le bois d''acacia : Jésus,<br/>Homme raffiné et doux !<br/>Il ne vivait que pour Dieu.<br/>Gloire à Dieu ! Gloire à Dieu ! Gloire à Dieu !<br/>',NULL,27591,2);
INSERT INTO stanza VALUES('FR117','3','Sagesse du plan de Dieu,<br/>Fils de l''homme et Fils de Dieu !<br/>En Lui est le nouvel homme.<br/>Gloire à Dieu ! Gloire à Dieu ! Gloire à Dieu !<br/>',NULL,27592,3);
INSERT INTO stanza VALUES('FR117','4','Adam nous légua la mort,<br/>Jésus nous légua la vie,<br/>Pour former le nouvel homme.<br/>Gloire à Dieu ! Gloire à Dieu ! Gloire à Dieu !<br/>',NULL,27593,4);
INSERT INTO stanza VALUES('FR117','5','La loi pour nous est une ombre,<br/>Jésus la réalité.<br/>En nous, doit grandir cet homme.<br/>Gloire à Dieu ! Gloire à Dieu ! Gloire à Dieu !<br/>',NULL,27594,5);
INSERT INTO stanza VALUES('FR117','6','Seigneur, Ton humanité<br/>Doit venir nous saturer,<br/>Pour que Tu puisses attirer,<br/>Beaucoup d''autres hommes à Toi, Seigneur.<br/>',NULL,27595,6);
INSERT INTO stanza VALUES('FR118','1','Pour nous Christ est la réalité,<br/>Mais nous devons être transformés.<br/>Dans notre expérience, Il doit régner,<br/>Être tout pour nous.<br/>En prière, nous Le contemplons,<br/>Dans Sa Parole et les réunions.<br/>Mais dans notre vie de tous les jours,<br/>Est-Il tout pour nous ?<br/><br/>Alléluia ! Sa lumière brille<br/>Et nous montre combien Il est riche,<br/>Quand à Lui nous ouvrons tout notre être<br/>Et que nous vivons par Lui<br/>Tous les jours en toutes choses.<br/>Frères, marchons donc selon l''esprit,<br/>Mangeons Christ afin de vivre en Lui !<br/>Laissons opérer en nous Sa vie,<br/>Il sera tout pour nous.<br/>',NULL,27596,1);
INSERT INTO stanza VALUES('FR118','2','Chaque circonstance journalière<br/>A été préparée par le Père,<br/>Nous le voyons : tout est pour le mieux,<br/>Oui ! Gagnons Christ !<br/>Christ, le contenu, la vie, la source,<br/>Veut jaillir, briller et s''exprimer.<br/>Il doit trouver un passage en nous,<br/>Pour pouvoir couler.<br/><br/>En nous œuvre puissamment Sa mort,<br/>Tous les jours, dans notre propre corps,<br/>Sa vie va pouvoir enfin jaillir !<br/>L''homme extérieur est détruit,<br/>L''homme intérieur renouvelé.<br/>Le vase de terre exprimera<br/>Le trésor, la vie, oui Christ Lui-même.<br/>L''évangile de la gloire en nous<br/>Va briller et jaillir.<br/><br/>Laissons de côté la tradition,<br/>Tournons-nous vers la réalité :<br/>Christ est tout en toi et tout en moi,<br/>Oui ! Il est tout pour nous !<br/>',NULL,27597,2);
INSERT INTO stanza VALUES('FR119','1','Mon vieil homme a été crucifié,<br/>En Jésus-Christ à la croix cloué,<br/>Il ne peut pas être amélioré,<br/>Car il est détruit.<br/>Quelqu''un vit en moi et m''affranchit,<br/>Une vie nouvelle en moi jaillit,<br/>Chaque jour, de Lui je suis rempli.<br/>Il veut me changer !<br/><br/>Sa personne habite en moi esprit,<br/>Il désir que je m''ouvre à Lui,<br/>Et de moi rayonnera Sa vie.<br/>Qu''Il habite dans mon cœur et y fasse Sa demeure,<br/>Qu''Il soumette enfin ma volonté !<br/>Jésus-Christ pourra se glorifier,<br/>D''être tout en tous !<br/>',NULL,27598,1);
INSERT INTO stanza VALUES('FR119','2','Par Sa vie qui croit, prend forme en moi,<br/>Son Corps, l''édifice grandira.<br/>Je ne suivrai plus mes propres voies,<br/>Je ne suis plus seul !<br/>Avec chaque membre en harmonie,<br/>Je conserve l''unité bénie,<br/>À la Tête, nous restons soumis,<br/>Pour Son bon plaisir.<br/><br/>L''église a pour mission d''accomplir<br/>Le dessein de Dieu, Son grand désir.<br/>Christ pourra Son épouse obtenir,<br/>L''univers admirera en nous Christ dans Son éclat et<br/>L''ennemi sera enfin détruit.<br/>Il n''y aura plus jamais de nuit.<br/>Dieu à Ses élus sera uni<br/>Pour l''éternité !<br/><br/>Dans la ville coule l''eau de vie,<br/>L''arbre de la vie produit Ses fruits,<br/>Sur le trône pour l''éternité,<br/>Dieu est glorifié !<br/>',NULL,27599,2);
INSERT INTO stanza VALUES('FR120','1','Je sais qu''Il vit, mon Rédempteur,<br/>Toujours pour moi Il prie.<br/>L''amour de Dieu scella mon cœur,<br/>En Christ, Il m''affranchit.<br/>',NULL,27600,1);
INSERT INTO stanza VALUES('FR120','2','Je sais qu''Il vit, mon Rédempteur,<br/>Il est l''Esprit de vie.<br/>En moi vivant, toujours vainqueur,<br/>Sa grâce est infinie !<br/>',NULL,27601,2);
INSERT INTO stanza VALUES('FR120','3','Je sais qu''Il est mon grand salut,<br/>Sans cesse Il vit en moi.<br/>Bientôt Il vient, en Lui j''ai cru,<br/>Tout oeil l''admirera.<br/>',NULL,27602,3);
INSERT INTO stanza VALUES('FR120','4','Je sais qu''Il veut ma sainteté,<br/>Pourquoi Lui résister ?<br/>Sa grâce en moi va opérer,<br/>Selon Sa volonté.<br/>',NULL,27603,4);
INSERT INTO stanza VALUES('FR120','5','Je sais que Sa parole est vraie,<br/>Mon cœur peut s''y fier.<br/>Quand Il viendra, mon nom, je sais,<br/>Demeurera gravé.<br/>',NULL,27604,5);
INSERT INTO stanza VALUES('FR121','1','Qu''elle est sainte et glorieuse,<br/>Cette vie qui vient des cieux,<br/>Éternelle et sans limites,<br/>Pur et puissant don de Dieu !<br/>Il nous donne Sa lumière,<br/>Son amour est merveilleux !<br/>',NULL,27605,1);
INSERT INTO stanza VALUES('FR121','2','Son amour comme un grand fleuve,<br/>Par Sa grâce nous atteint.<br/>Il n''est plus inaccessible,<br/>Il s''est dévoilé aux Siens.<br/>Que tout homme Le connaisse,<br/>Lui, Sa vie et Son dessein !<br/>',NULL,27606,2);
INSERT INTO stanza VALUES('FR121','3','Accessible et combien proche,<br/>Dieu en Christ s''est révélé.<br/>Nous avons pu Le voir vivre,<br/>Le toucher, Le contempler,<br/>Vivant une vie parfaite,<br/>Exemplaire et sans péché.<br/>',NULL,27607,3);
INSERT INTO stanza VALUES('FR121','4','Quelle image merveilleuse :<br/>Dans la terre un grain tomba !<br/>Pour que tant de fruits abondent,<br/>Christ alla jusqu''à la croix.<br/>Il mourut dans la souffrance,<br/>Puis germa. ressuscita !<br/>',NULL,27608,4);
INSERT INTO stanza VALUES('FR121','5','Quel triomphe et quelle gloire !<br/>Le tombeau Il a vaincu !<br/>L''ange a descellé la pierre,<br/>Aux Siens Christ est apparu,<br/>Puis retourna vers Son Père,<br/>Comme Prince du salut.<br/>',NULL,27609,5);
INSERT INTO stanza VALUES('FR121','6','Quel amour et quelle grâce !<br/>Dieu veut être notre vie !<br/>Pour que Son plan s''accomplisse,<br/>Il est devenu l''Esprit.<br/>Il languit d''être par l''homme,<br/>Accepté, vécu, béni.<br/>',NULL,27610,6);
INSERT INTO stanza VALUES('FR121','7','Quelle vie mystérieuse !<br/>Dieu Lui-même coule en moi !<br/>La réalité suprême<br/>Alimente notre foi.<br/>Que Sa vie règne sur terre,<br/>Chantons tous : « Alléluia ! »<br/>',NULL,27611,7);
INSERT INTO stanza VALUES('FR122','1','Dieu le Père en Christ est notre source<br/>Et le Saint-Esprit habite en nous.<br/>Il est accessible, Il coule et nous remplit,<br/>Sa Personne vit dans notre esprit !<br/>',NULL,27612,1);
INSERT INTO stanza VALUES('FR122','2','Christ, le grain de vie tombé en terre,<br/>Nous régénéra dans notre esprit.<br/>Comme une semence, Il se met à germer,<br/>Peu à peu, il va nous restaurer.<br/>',NULL,27613,2);
INSERT INTO stanza VALUES('FR122','3','L''Esprit de Jésus en nous demeure,<br/>Notre esprit humain est Sa maison.<br/>Il opère en nous et veut nous transformer,<br/>Laissons cette vie nous inonder !<br/>',NULL,27614,3);
INSERT INTO stanza VALUES('FR122','4','En esprit nous pouvons tous Lui plaire,<br/>En tournant nos pensées vers Jésus,<br/>Nous nous détournons de toute vanité,<br/>Pour qu''Il puisse enfin nous capturer.<br/>',NULL,27615,4);
INSERT INTO stanza VALUES('FR122','5','C''est dans notre que Christ habite,<br/>Mais Son plan en nous doit s''accomplir,<br/>Qu''Il nous renouvelle et s''œuvre en nos pensées !<br/>Que Sa vie puisse enfin s''exprimer !<br/>',NULL,27616,5);
INSERT INTO stanza VALUES('FR122','6','Qu''à l''Esprit nos pensées soient soumises !<br/>Attachons-nous à la vérité !<br/>C''est en mangeant Christ, que nous avons la vie,<br/>Frères, plaçons nos pensées sur Lui.<br/>',NULL,27617,6);
INSERT INTO stanza VALUES('FR122','7','Cette vie est simple et si pratique !<br/>Frères, tournons-nous vers Jésus-Christ !<br/>Il est accessible, en nous toujours présent,<br/>Gagnons-Le et rachetons le temps !<br/>',NULL,27618,7);
INSERT INTO stanza VALUES('FR123','1','Dieu est vivant ! Oui, chante alléluia !<br/>Jésus vit en nous ! Chante alléluia !<br/>Nous goûtons Sa vie,<br/>Il est notre pain.<br/>Dis : « Seigneur Jésus ! », goûte et vois !<br/>',NULL,27619,1);
INSERT INTO stanza VALUES('FR123','2','Nous nous rassemblons ! Il n''est rien de mieux !<br/>En esprit, nous sommes une famille,<br/>Ainsi Son Corps est<br/>Sur terre exprimé,<br/>Jésus, notre réalité !<br/>',NULL,27620,2);
INSERT INTO stanza VALUES('FR123','3','Dans les églises, nous sommes remplis,<br/>Pour devenir Son vrai témoignage,<br/>Dispensant Sa vie<br/>Dans chaque ville,<br/>Tout le pays verra ce Christ !<br/>',NULL,27621,3);
INSERT INTO stanza VALUES('FR124','1','Quel grand mystère est le Dieu trinitaire,<br/>En substance un, mais en Personne trois.<br/>Que c''est glorieux ! Dieu dans le Fils par l''Esprit,<br/>S''unit à moi et devient tout pour moi.<br/>',NULL,27622,1);
INSERT INTO stanza VALUES('FR124','chorus','Dieu trinitaire, Tu es tout pour moi,<br/>Dieu merveilleux, Dieu glorieux.<br/>Ce don divin à jamais insondable,<br/>Est excellent, est merveilleux.<br/>',NULL,27623,2);
INSERT INTO stanza VALUES('FR124','2','Tu es, ô Père, une abondante source !<br/>Qui peut remplir, combler l''humanité.<br/>Tu es si riche et toujours accessible,<br/>Portion glorieuse, vaste, illimitée.<br/>',NULL,27624,3);
INSERT INTO stanza VALUES('FR124','3','Ô Fils de Dieu ! Riche expression du Père,<br/>Venu en chair, parmi nous Tu vécus.<br/>Ta rédemption efficace est parfaite,<br/>Dieu s''est uni à nous pécheurs perdus.<br/>',NULL,27625,4);
INSERT INTO stanza VALUES('FR124','4','Venu en nous pour nous donner la vie,<br/>Cet Esprit est le Fils transfiguré.<br/>Fait merveilleux : Son Esprit et notre esprit<br/>Ne forment qu''un, les deux sont mélangés.<br/>',NULL,27626,5);
INSERT INTO stanza VALUES('FR124','5','Dieu est Esprit, réalité glorieuse,<br/>Nous Le touchons et L''expérimentons,<br/>Jour après jour, nous partageons Sa vie,<br/>De Sa nature, en rien ne différons.<br/>',NULL,27627,6);
INSERT INTO stanza VALUES('FR125','1','C''est mon bonheur ici-bas,<br/>Que de vivre sous la croix,<br/>Pour connaitre la puissance<br/>Du Sauveur dans les souffrances.<br/>',NULL,27628,1);
INSERT INTO stanza VALUES('FR125','2','Les épreuves surviendront,<br/>Mais je vois par simple foi,<br/>Que l''amour les accompagne.<br/>Je les le avec joie.<br/>',NULL,27629,2);
INSERT INTO stanza VALUES('FR125','3','Si je ne suis éprouvé,<br/>Limité, châtié, pressé,<br/>Je ferais bien d''avoir peur,<br/>D''être par Lui rejeté.<br/>',NULL,27630,3);
INSERT INTO stanza VALUES('FR125','4','Les douleurs me rendent doux,<br/>Me font fléchir les genoux.<br/>Mes prières vivifient,<br/>M''humilient devant Lui.<br/>',NULL,27631,4);
INSERT INTO stanza VALUES('FR126','1','Jour après jour, je vois la croix bénie,<br/>De mon Sauveur.<br/>Jour après jour, je tends mes bras vers elle,<br/>Et là, je meurs.<br/>',NULL,27632,1);
INSERT INTO stanza VALUES('FR126','2','Seigneur, j''embrasse ma croix et l''exalte<br/>À chaque pas.<br/>Ta puissance agit librement en moi.<br/>Je vis par Toi !<br/>',NULL,27633,2);
INSERT INTO stanza VALUES('FR126','3','En demeurant en tout temps à la croix,<br/>Ma joie déborde.<br/>Car au-delà de cette mort, je vois<br/>Une couronne.<br/>',NULL,27634,3);
INSERT INTO stanza VALUES('FR126','4','Oh ! qu''il est doux de recevoir, Jésus<br/>De Toi, la croix !<br/>Si je veux Te gagner, je dois aussi<br/>Souffrir pour Toi.<br/>',NULL,27635,4);
INSERT INTO stanza VALUES('FR126','5','Je veux connaitre la perte de tout,<br/>Pour Toi, Ton nom.<br/>Pour pouvoir saisir tout ce que Tu es,<br/>Seigneur pour moi.<br/>',NULL,27636,5);
INSERT INTO stanza VALUES('FR127','1','Jamais la mort ne retiendra la vie.<br/>Vie invincible que rien ne détruit,<br/>Vie éternelle, de résurrection,<br/>C''est Dieu Lui-même en Son Fils Jésus-Christ !<br/>',NULL,27637,1);
INSERT INTO stanza VALUES('FR127','2','Jamais la mort ne retiendra la vie.<br/>Liguant ses forces pour la supprimer,<br/>Elle lui donne toujours l''occasion,<br/>De démontrer Sa force illimitée.<br/>',NULL,27638,2);
INSERT INTO stanza VALUES('FR127','3','Jamais la mort ne retiendra la vie.<br/>Plus on l''enterre, plus elle fleurit.<br/>Toute souffrance ne fait que l''aider<br/>À s''exprimer en produisant du fruit.<br/>',NULL,27639,3);
INSERT INTO stanza VALUES('FR127','4','Jamais la mort ne retiendra la vie.<br/>Chaque barrage éclate sous ses flots.<br/>Elle abolit le pouvoir de la nuit,<br/>En brandissant contre elle son flambeau.<br/>',NULL,27640,4);
INSERT INTO stanza VALUES('FR127','5','Jamais la mort ne retiendra la vie.<br/>Qui nous dispense les vertus de Dieu :<br/>Sa sainteté, Sa parfaite équité,<br/>Son grand amour, Son être merveilleux.<br/>',NULL,27641,5);
INSERT INTO stanza VALUES('FR127','6','Je veux connaitre cette vie en Christ,<br/>Qui sur la mort sera toujours vainqueur !<br/>Puissé-je dans ma vie réaliser<br/>Qu''elle est en Christ, en mon puissant Seigneur !<br/>',NULL,27642,6);
INSERT INTO stanza VALUES('FR128','1','Es-tu lasse et troublée, mon âme ?<br/>Ne vois-tu pas une lueur ?<br/>Relève-toi et prends courage,<br/>Jésus est un très grand Sauveur !<br/>',NULL,27643,1);
INSERT INTO stanza VALUES('FR128','chorus','Oh ! regarde vers Jésus,<br/>Contemple ce Christ merveilleux !<br/>Les plaisirs du monde s''estomperont,<br/>Dans l''éclat de ton Dieu glorieux.<br/>',NULL,27644,2);
INSERT INTO stanza VALUES('FR128','2','Il donne la vie éternelle,<br/>Ayant triomphé sur la mort.<br/>Le péché n''a plus son emprise,<br/>Tu es par Jésus le plus fort.<br/>',NULL,27645,3);
INSERT INTO stanza VALUES('FR128','3','Il ne trahit pas Sa parole,<br/>En Lui crois et Il sera tien.<br/>À ce monde qui agonise,<br/>Dis que Jésus brisa tes liens.<br/>',NULL,27646,4);
INSERT INTO stanza VALUES('FR129','1','Lumière de la vie,<br/>En Toi nous demeurons,<br/>Voulons Te contempler.<br/>Oh ! quelle communion !<br/>Ton Esprit nous suivons,<br/>Toi seul, nous célébrons,<br/>Lumière de la vie !<br/>',NULL,27647,1);
INSERT INTO stanza VALUES('FR130','1','« Ce que je suis ? Non, mais ce que Tu es »,<br/>Cela suffit pour l''âme reposer.<br/>Seul Ton amour peut assurer ma paix,<br/>Calmer mon cœur quand il est agité.<br/>',NULL,27648,1);
INSERT INTO stanza VALUES('FR130','2','Ton grand amour bannit toutes mes peurs.<br/>Je reconnais la voix qui dit : « C''est Moi ! »<br/>Qui m''encourage dans tous mes malheurs,<br/>Mots familiers, pleins de céleste joie.<br/>',NULL,27649,2);
INSERT INTO stanza VALUES('FR130','3','Ton nom d''amour me parvient de Ta croix !<br/>Ton nom d''amour je lis sur Ton tombeau !<br/>Quand cet amour se manifeste en moi,<br/>Ma sombre nuit de dissipe aussitôt.<br/>',NULL,27650,3);
INSERT INTO stanza VALUES('FR130','4','Il me bénit, toujours me bénira,<br/>Me sauvera, me sauve chaque jour.<br/>Il me soutient aux temps de désarroi,<br/>Me fait franchir les grands flots sans détour.<br/>',NULL,27651,4);
INSERT INTO stanza VALUES('FR130','5','Ce que je sais de Toi, Seigneur mon Dieu,<br/>Mon cœur apaise et m''incite à chanter :<br/>« Toi ma vigueur, qui me rends victorieux,<br/>Toi mon refuge, où je peux m''abriter. »<br/>',NULL,27652,5);
INSERT INTO stanza VALUES('FR130','6','Révèle-Toi, ô mon Seigneur, mon Dieu,<br/>Plus de Ta gloire fais-moi contempler !<br/>Dévoile-Toi, Dieu miséricordieux,<br/>Dans les vertus de Ton humanité !<br/>',NULL,27653,6);
INSERT INTO stanza VALUES('FR131','1','Ô Toi, le sujet de mon bonheur parfait !<br/>À Toi je crie dans la détresse.<br/>Refuge dans ma nuit, soutien de mon jour,<br/>Ma foi, mon salut et mon tout.<br/>',NULL,27654,1);
INSERT INTO stanza VALUES('FR131','2','Oh ! fais-moi savoir où Tu pais Ton troupeau !<br/>Là où Ton repos Tu lui donnes.<br/>Pourquoi donc gémir dans la vallée des pleurs ?<br/>Pourquoi mourir dans ce désert ?<br/>',NULL,27655,2);
INSERT INTO stanza VALUES('FR131','3','Pourquoi errer loin de Ta face et de Toi ?<br/>Pourquoi murmurer contre Toi ?<br/>Tes ennemis rient de me voir humilié,<br/>Se moquent des larmes versées.<br/>',NULL,27656,3);
INSERT INTO stanza VALUES('FR131','4','Avez-vous vu, filles de Jérusalem,<br/>L''étoile au-dessus d''Isael ?<br/>Savez-vous où est passé mon Bien-aimé ?<br/>Où Son Troupeau Il a mené ?<br/>',NULL,27657,4);
INSERT INTO stanza VALUES('FR131','5','Berger saint ! à Ton appel je répondrai,<br/>Je sais le doux son de Ta voix.<br/>En Toi, pour toujours, oui, je me réjouirai !<br/>Toi mon rocher et tout pour moi.<br/>',NULL,27658,5);
INSERT INTO stanza VALUES('FR132','1','Ne reste pas désemparé,<br/>Dieu prendra soin de toi.<br/>Viens sous Ses ailes t''abriter,<br/>Dieu prendra soin de toi.<br/>',NULL,27659,1);
INSERT INTO stanza VALUES('FR132','chorus','Dieu prendra soin de toi,<br/>Sur ton parcours de chaque jour.<br/>Il prendra soin de toi,<br/>Dieu prendra soin de toi.<br/>',NULL,27660,2);
INSERT INTO stanza VALUES('FR132','2','Ton cœur est lourd et accablé,<br/>Dieu prendra soin de toi.<br/>Par les dangers tu es cerné,<br/>Dieu prendra soin de toi.<br/>',NULL,27661,3);
INSERT INTO stanza VALUES('FR132','3','Il comblera tous tes besoins,<br/>Dieu prendra soin de toi.<br/>Repos-toi entre Ses mains,<br/>Dieu prendra soin de toi.<br/>',NULL,27662,4);
INSERT INTO stanza VALUES('FR132','4','Si tu es triste et sans ami,<br/>Dieu prendra soin de toi.<br/>Il met en paix ton cœur meurtri,<br/>Dieu prendra soin de toi.<br/>',NULL,27663,5);
INSERT INTO stanza VALUES('FR132','5','Si dans l''épreuve tu gémis,<br/>Dieu prendra soin de toi.<br/>Si tu t''appuies toujours sur lui,<br/>Dieu prendra soin de toi.<br/>',NULL,27664,6);
INSERT INTO stanza VALUES('FR133','1','Lorsque la tempête s''abat sur ta vie,<br/>Que lassé, tu penses que tout est détruit,<br/>Compte les bienfaits de Dieu, entends Sa voix,<br/>Tu seras surpris de ce qu''Il fait pour toi.<br/>',NULL,27665,1);
INSERT INTO stanza VALUES('FR133','chorus','Compte Ses bienfaits, entends Sa voix !<br/>Compte tout ce qu''Il a fait pour toi.<br/>Tous Ses bienfaits, écoute Sa voix,<br/>Ses bénédictions s''obtiennent par la foi !<br/>',NULL,27666,2);
INSERT INTO stanza VALUES('FR133','2','Es-tu trop chargé du poids de tes soucis,<br/>Vaincu par le monde, blessé par la vie ?<br/>Compte Ses bienfaits, tes doutes s''enfuiront<br/>Et la joie de Dieu remplira ta maison.<br/>',NULL,27667,3);
INSERT INTO stanza VALUES('FR133','3','Ne te laisse pas couvrir d''or ou d''argent,<br/>Car le vrai bonheur nous vient du Tout-Puissant.<br/>Compte les bienfaits de Dieu, cherche les fruits,<br/>Que Christ a produit en ceux qui L''ont suivi.<br/>',NULL,27668,4);
INSERT INTO stanza VALUES('FR133','4','Dans les inquiétudes, dans le désarroi,<br/>Ne perds pas courage, Dieu veille et te voit.<br/>Compte Ses bienfaits, toujours Il peut t''aider,<br/>Tout au long de ton chemin te consoler.<br/>',NULL,27669,5);
INSERT INTO stanza VALUES('FR134','1','Dans chaque vie que Dieu créa,<br/>Une impression de vie,<br/>À chaque instant, spontanément<br/>S''exprime et réagit.<br/>',NULL,27670,1);
INSERT INTO stanza VALUES('FR134','2','La vie de Dieu qui est en nous,<br/>Vie la plus élevée,<br/>Surpasse en sensibilité,<br/>Les vies par Dieu créées.<br/>',NULL,27671,2);
INSERT INTO stanza VALUES('FR134','3','La sensation de vie en nous<br/>Est Dieu, que je perçois.<br/>En nous, la vie de Dieu produit<br/>Un sentiment divin.<br/>',NULL,27672,3);
INSERT INTO stanza VALUES('FR134','4','La sensation la plus profonde<br/>Dans ma conscience agit,<br/>Discerne ce qui plait à Dieu<br/>Et à Lui me conduit.<br/>',NULL,27673,4);
INSERT INTO stanza VALUES('FR134','5','C''est par cette impression de vie,<br/>Que Dieu peut nous guider,<br/>Dans notre marche et dans nos choix,<br/>Selon Sa volonté.<br/>',NULL,27674,5);
INSERT INTO stanza VALUES('FR134','6','Quand cette vie en nous murit,<br/>Sa vitalité croit,<br/>Qui nous restreint et nous conduit,<br/>Sur le chemin étroit.<br/>',NULL,27675,6);
INSERT INTO stanza VALUES('FR134','7','En suivant cette perception,<br/>Notre esprit est hardi,<br/>Languit après la communion<br/>Et l''unité chérit.<br/>',NULL,27676,7);
INSERT INTO stanza VALUES('FR135','1','Pour en tout temps venir à Dieu,<br/>Un cœur pur est précieux,<br/>Pour qu''à nous toutes Ses richesses,<br/>Soient données, dans Sa grâce.<br/>',NULL,27677,1);
INSERT INTO stanza VALUES('FR135','2','Change mon cœur qui n''est pas droit,<br/>Éclaire mes pensées,<br/>Pour discerner Tes intentions,<br/>Saisir Ta volonté.<br/>',NULL,27678,2);
INSERT INTO stanza VALUES('FR135','3','Seigneur, Tu veux un cœur fervent,<br/>Un cœur brulant d''amour,<br/>Pour Toi, rempli de sentiments,<br/>Désirant Ton retour.<br/>',NULL,27679,3);
INSERT INTO stanza VALUES('FR135','4','Tu veux un cœur obéissant :<br/>Soumets ma volonté,<br/>Adoucis-là, mais rends-moi fort,<br/>Pour Ton plan, Bien-aimé !<br/>',NULL,27680,4);
INSERT INTO stanza VALUES('FR135','5','Mon cœur ne doit pas mépriser,<br/>Mais en tout chercher Dieu.<br/>Et la conscience est purifiée,<br/>Par le sang si précieux.<br/>',NULL,27681,5);
INSERT INTO stanza VALUES('FR135','6','En moi, Seigneur, mets un tel cœur,<br/>Toujours tourné vers Toi !<br/>Pour y graver Ta sainteté<br/>Et T''exprimer par moi !<br/>',NULL,27682,6);
INSERT INTO stanza VALUES('FR136','1','Tu es l''Esprit, Seigneur Jésus,<br/>Tu vis dans mon esprit.<br/>Les deux esprits ne forment qu''un,<br/>À Toi, je suis uni.<br/>',NULL,27683,1);
INSERT INTO stanza VALUES('FR136','2','L''Esprit témoigne en mon esprit,<br/>Que je suis né de Lui.<br/>Enfant de Dieu, Son héritier,<br/>Je prends part à Sa vie.<br/>',NULL,27684,2);
INSERT INTO stanza VALUES('FR136','3','Tu es l''Esprit de vie, Seigneur,<br/>Qui se dispense en nous.<br/>Tu es si riche en notre esprit,<br/>Toi seul es notre tout.<br/>',NULL,27685,3);
INSERT INTO stanza VALUES('FR136','4','Tu nous conduis, Seigneur Esprit,<br/>Nous demeurons en Toi.<br/>Nos deux esprits sont mélangés,<br/>Nous marchons selon Toi.<br/>',NULL,27686,4);
INSERT INTO stanza VALUES('FR136','5','Tu es l''Esprit dans notre esprit,<br/>Qui toujours nous soutient.<br/>Nous T''adorons et Te servons.<br/>Un avec tous les saints.<br/>',NULL,27687,5);
INSERT INTO stanza VALUES('FR136','6','Par nos prières et nos soupirs,<br/>Dans notre esprit, Tu pries,<br/>Tu intercèdes auprès de Dieu,<br/>Pour Ton économie.<br/>',NULL,27688,6);
INSERT INTO stanza VALUES('FR136','7','Nous revenons à notre esprit,<br/>Tu coules abondamment.<br/>Dans Ton Esprit, nous recevons<br/>L''approvisionnement.<br/>',NULL,27689,7);
INSERT INTO stanza VALUES('FR136','8','Quelle glorieuse union, Seigneur !<br/>Indissociable lien !<br/>Ton Esprit vit dans mon esprit,<br/>Le mien vit dans le Tien.<br/>',NULL,27690,8);
INSERT INTO stanza VALUES('FR137','1','Notre Dieu veut voir Ses enfants<br/>Exprimer Son Bien-aimé.<br/>Son Esprit de gloire en gloire<br/>Doit nos âmes transformer.<br/>',NULL,27691,1);
INSERT INTO stanza VALUES('FR137','chorus','Oh ! Transforme tout mon être<br/>Et rends-le conforme à Toi !<br/>Que Ton Esprit me sature,<br/>Je serai semblable à Toi !<br/>',NULL,27692,2);
INSERT INTO stanza VALUES('FR137','2','Dieu est entré dans mon esprit,<br/>Sa vie m''a régénéré.<br/>Il veut que toute mon âme,<br/>Soit par l''Esprit transformée.<br/>',NULL,27693,3);
INSERT INTO stanza VALUES('FR137','3','Répand-Toi depuis mon esprit,<br/>Renouvelle mes pensées.<br/>Prends mes sentiments, cher Seigneur,<br/>Adoucis ma volonté.<br/>',NULL,27694,4);
INSERT INTO stanza VALUES('FR137','4','Sa puissante vie divine<br/>Me transforme peu à peu,<br/>Elle change ma nature,<br/>Me rend absolu pour Dieu.<br/>',NULL,27695,5);
INSERT INTO stanza VALUES('FR137','5','Nous devenons Son ouvrage,<br/>Quand nous jouissons de Dieu.<br/>Puis, nous serons transfigurés,<br/>Recevrons un corps glorieux.<br/>',NULL,27696,6);
INSERT INTO stanza VALUES('FR138','1','Prie quand ton âme veut parler<br/>Et dire avec ardeur,<br/>Les réactions et les pensées,<br/>Qui montent de ton cœur.<br/>',NULL,27697,1);
INSERT INTO stanza VALUES('FR138','2','Prie quand ton âme veut pleurer<br/>Sous le poids des soupirs.<br/>Dieu seul toujours sait t''écouter,<br/>Comprendre ton désir.<br/>',NULL,27698,2);
INSERT INTO stanza VALUES('FR138','3','Prie comme l''âme d''un enfant,<br/>Apprends ses simples mots.<br/>Ensuite attends, calme et confiant,<br/>Tous les secours d''en haut.<br/>',NULL,27699,3);
INSERT INTO stanza VALUES('FR138','4','Le souffle vital du chrétien,<br/>C''est de toujours prier,<br/>Face à la mort et à ses liens,<br/>En paix il peut rester.<br/>',NULL,27700,4);
INSERT INTO stanza VALUES('FR138','5','Les saints qui prient ne forment qu''un,<br/>Un cœur, une pensée.<br/>Père et Fils leur sont en commun,<br/>Une douce unité.<br/>',NULL,27701,5);
INSERT INTO stanza VALUES('FR138','6','Toi par qui nous venons à Dieu,<br/>Tu es la Vérité.<br/>Tu prias toujours, en tous lieux,<br/>Apprends-nous à prier !<br/>',NULL,27702,6);
INSERT INTO stanza VALUES('FR139','1','Apprends-nous à prier, Seigneur,<br/>Pour chasser l''ennemi,<br/>Pour que son pouvoir soit lié,<br/>Ses captifs affranchis.<br/>',NULL,27703,1);
INSERT INTO stanza VALUES('FR139','2','Dans la prière, enseigne-nous<br/>La constance au combat.<br/>La diable sera confondu,<br/>Son bastion tombera.<br/>',NULL,27704,2);
INSERT INTO stanza VALUES('FR139','3','Dans nos requêtes, revêts-nous<br/>De Ton autorité.<br/>Ton adversaire nous vaincrons,<br/>Par Ton sang, protégés.<br/>',NULL,27705,3);
INSERT INTO stanza VALUES('FR139','4','Le cœur sincère et plein de foi.<br/>Nous servons à l''autel,<br/>En Ta victoire tous unis,<br/>Confiants en Ton appel.<br/>',NULL,27706,4);
INSERT INTO stanza VALUES('FR140','1','Dans le Saint des Saints, près du trône, viens !<br/>Et Sa grâce tu trouveras.<br/>Dans le Saint des Saints, près du trône, viens !<br/>Et Sa grâce tu trouveras.<br/><br/>Alléluia ! Alléluia !<br/>Et Sa grâce tu trouveras.<br/>Alléluia ! Alléluia !<br/>Et Sa grâce tu trouveras.<br/>',NULL,27707,1);
INSERT INTO stanza VALUES('FR140','2','Dans ce lieu glorieux, viens, rencontre Dieu !<br/>Tu reflèteras Son éclat.<br/>Dans ce lieu glorieux, viens, rencontre Dieu !<br/>Tu reflèteras Son éclat.<br/><br/>Alléluia ! Alléluia !<br/>Tu reflèteras Son éclat.<br/>Alléluia ! Alléluia !<br/>Tu reflèteras Son éclat.<br/>',NULL,27708,2);
INSERT INTO stanza VALUES('FR140','3','Tourne-toi vers Lui, prie dans ton esprit,<br/>Puise au fleuve d''eau de la vie.<br/>Tourne-toi vers Lui, prie dans ton esprit,<br/>Puise au fleuve d''eau de la vie.<br/><br/>Alléluia ! Alléluia !<br/>Puise au fleuve d''eau de la vie.<br/>Alléluia ! Alléluia !<br/>Puise au fleuve d''eau de la vie.<br/>',NULL,27709,3);
INSERT INTO stanza VALUES('FR141','1','Ton appel atteint l''église :<br/>« Entrez dans le Saint des Saints,<br/>Contemplez toute Ma gloire,<br/>Reflétez l''éclat divin. »<br/>',NULL,27710,1);
INSERT INTO stanza VALUES('FR141','chorus','Dans le Saint des Saints nous entrons,<br/>À l''autel, tout en priant.<br/>Dieu a déchiré le voile,<br/>Oui, nous entrons hardiment.<br/>',NULL,27711,2);
INSERT INTO stanza VALUES('FR141','2','Cette voie riche et nouvelle<br/>A été inaugurée.<br/>Maintenant, l''accès est libre,<br/>Nous entrons sans hésiter.<br/>',NULL,27712,3);
INSERT INTO stanza VALUES('FR141','3','Nous venons auprès du père,<br/>Sur le trône, Il est le Roi.<br/>Le chemin Jésus nous ouvre,<br/>Grâce au sang et à la croix.<br/>',NULL,27713,4);
INSERT INTO stanza VALUES('FR141','4','Pleins de foi, le cœur sincère,<br/>Gardons-nous de reculer.<br/>Demeurons dans cette sphère,<br/>Oublions notre passé !<br/>',NULL,27714,5);
INSERT INTO stanza VALUES('FR141','5','Du repos, les Siens jouissent,<br/>Ici, dans le Saint des Saints.<br/>Notre Dieu et nous Son peuple<br/>Demeurons bénis sans fin.<br/>',NULL,27715,6);
INSERT INTO stanza VALUES('FR142','1','Quel Ami fidèle et tendre,<br/>Nous avons en Jésus-Christ !<br/>Toujours prêt à nous entendre,<br/>À répondre à notre cri.<br/>Il connait nos défaillances,<br/>Nos combats de chaque jour.<br/>Sévère en Ses exigences,<br/>Il est riche en Son amour.<br/>',NULL,27716,1);
INSERT INTO stanza VALUES('FR142','2','Quel Ami fidèle et tendre,<br/>Nous avons en Jésus-Christ !<br/>Toujours prêt à nous comprendre,<br/>Quand nous sommes en souci.<br/>Disons-Lui toutes nos craintes,<br/>Ouvrons-Lui tout notre cœur.<br/>Bientôt Ses paroles saintes,<br/>Nous rendront le vrai bonheur.<br/>',NULL,27717,2);
INSERT INTO stanza VALUES('FR142','3','Quel Ami fidèle et tendre,<br/>Nous avons en Jésus-Christ !<br/>Il désire nous apprendre,<br/>À toujours compter sur Lui.<br/>S''Il nous voit vrais et sincères,<br/>À chercher Sa sainteté,<br/>Il écoute nos prières<br/>Et nous rend la liberté.<br/>',NULL,27718,3);
INSERT INTO stanza VALUES('FR143','1','Combien c''est merveilleux ! Jésus change ma vie,<br/>Quand je prends Sa Parole en moi.<br/>Plus de vie, plus de Christ, sont en moi ajoutés,<br/>Quand je prends Sa Parole en moi.<br/>',NULL,27719,1);
INSERT INTO stanza VALUES('FR143','chorus','Quand je prends Sa Parole en moi,<br/>Quand je prends Sa Parole en moi,<br/>Le Seigneur prend mon cœur et y fait Sa demeure,<br/>Quand je prends Sa Parole en moi.<br/>',NULL,27720,2);
INSERT INTO stanza VALUES('FR143','2','Ce que ne peux faire, l''Esprit l''accomplit,<br/>Quand je prends Sa Parole en moi.<br/>Cette transformation est vraie et tous la voient,<br/>Quand je prends Sa Parole en moi.<br/>',NULL,27721,3);
INSERT INTO stanza VALUES('FR143','3','Oui, je cesse d''errer, de toujours m''égarer,<br/>Quand je prends Sa Parole en moi.<br/>Mes penchants, mes désirs sont vraiment crucifiés,<br/>Quand je prends Sa Parole en moi.<br/>',NULL,27722,4);
INSERT INTO stanza VALUES('FR143','4','Le secret de la foi, ô Seigneur ! Je le vois :<br/>C''est dire : « Amen ! » à Ta Parole.<br/>La foi se développe en moi quand je Te dis :<br/>« Amen ! » Seigneur, à Ta Parole.<br/>',NULL,27723,5);
INSERT INTO stanza VALUES('FR143','5','Mon amour pour les frères grandit toujours plus,<br/>Quand je dis : « Amen ! » à Jésus.<br/>Et je suis édifié avec eux toujours plus,<br/>Quand je dis : « Amen ! » à Jésus.<br/>',NULL,27724,6);
INSERT INTO stanza VALUES('FR143','6','L''espérance en moi de son retour s''affermit,<br/>Quand je dis : « Amen ! » à Jésus.<br/>Je m''apprête à bientôt le revoir, mon Seigneur !<br/>En disant : « Amen ! » à Jésus.<br/>',NULL,27725,7);
INSERT INTO stanza VALUES('FR144','1','Mon cœur a soif et mon esprit a faim,<br/>Rien ne me comble vraiment, sinon Toi.<br/>Je viens à Toi, Seigneur, Tu es ma vie,<br/>Toi seul, Jésus, peux ma faim assouvir.<br/>',NULL,27726,1);
INSERT INTO stanza VALUES('FR144','chorus','Nourris-moi Jésus, abreuve-moi,<br/>Ma soif étanche, rassasie-moi !<br/>Remplis mon cœur et inonde ma vie,<br/>Ma soif étanche, à Toi je prie !<br/>',NULL,27727,2);
INSERT INTO stanza VALUES('FR144','2','Tu es le pain, Tu es l''eau de la vie,<br/>Pour vivifier, soutenir mon esprit.<br/>Mon âme languit, soupire après Toi,<br/>Par la prière, Seigneur, je Te bois.<br/>',NULL,27728,3);
INSERT INTO stanza VALUES('FR144','3','Tu es la Parole, Dieu incarné,<br/>Tu es l''Esprit qui la vie m''a donnée.<br/>Par Ta Parole, ici, je me nourris,<br/>Par Ton Esprit, Tu es l''eau de la vie.<br/>',NULL,27729,4);
INSERT INTO stanza VALUES('FR144','4','Tu es le pain qui des cieux descendit,<br/>Tu fus frappé, du rocher l''eau sortit :<br/>Inépuisable approvisionnement ;<br/>En Esprit, Tu es un fleuve vivant !<br/>',NULL,27730,5);
INSERT INTO stanza VALUES('FR144','5','Oh ! Tes Paroles sont Esprit et vie !<br/>En les lisant, de Toi je me nourris.<br/>Tu es l''Esprit, Tu demeures en moi,<br/>Dans mon esprit, avec joie, je Te bois.<br/>',NULL,27731,6);
INSERT INTO stanza VALUES('FR144','6','Dans Ta Parole je cherche la vie,<br/>Quand je la lis, je la mange en esprit.<br/>Fleuve de vie, où s''abreuve mon cœur,<br/>Coule et jaillis de mon homme intérieur !<br/>',NULL,27732,7);
INSERT INTO stanza VALUES('FR144','7','Je me nourris, je m''abreuve de Toi.<br/>En lisant, je mange; en priant, je bois.<br/>Lisant et priant, je mange et je bois,<br/>Ma récompense, cher Maitre, c''est Toi !<br/>',NULL,27733,8);
INSERT INTO stanza VALUES('FR144','8','Ô Seigneur ! Sois pour moi un vrai festin,<br/>Avec Ta Parole et Ton Esprit Saint !<br/>Oh ! Sois pour moi ce festin intérieur,<br/>Mon allégresse, la joie de mon cœur !<br/>',NULL,27734,9);
INSERT INTO stanza VALUES('FR145','1','Je viens à Toi, Seigneur,<br/>J''ai faim, j''ai soif de Toi.<br/>Sois mes délices, mon festin,<br/>Deviens la joie en moi.<br/>',NULL,27735,1);
INSERT INTO stanza VALUES('FR145','2','Te contempler, Seigneur,<br/>C''est mon ardent désir.<br/>Je veux de Toi me rassasier,<br/>Me réjouir de Ta vie.<br/>',NULL,27736,2);
INSERT INTO stanza VALUES('FR145','3','Je veux Te voir, Seigneur,<br/>Là, dans le lieu Très Saint,<br/>Pour Ton visage contempler,<br/>En Toi rester enfin.<br/>',NULL,27737,3);
INSERT INTO stanza VALUES('FR145','4','Dans cette communion,<br/>Ta grâce coule en moi.<br/>L''esprit, le cœur, de joie remplis,<br/>Je me repose en Toi.<br/>',NULL,27738,4);
INSERT INTO stanza VALUES('FR145','5','Auprès de Toi Seigneur,<br/>Mon âme veut rester,<br/>Pour que Tu puisses par l''Esprit,<br/>Mon être saturer.<br/>',NULL,27739,5);
INSERT INTO stanza VALUES('FR146','1','Nous ne vivons pas de pain seul,<br/>Mais la parole est notre manne,<br/>Prononcée par le Dieu vivant,<br/>Nous la mangeons, vivons par elle.<br/>',NULL,27740,1);
INSERT INTO stanza VALUES('FR146','2','Notre être entier - corps, âme, esprit - Dieu le créa en trois parties.<br/>La plus profonde est notre esprit,<br/>Pour Le toucher, Le contacter.<br/>',NULL,27741,2);
INSERT INTO stanza VALUES('FR146','3','Nous avons tous besoin du pain<br/>Qui peut assouvir notre faim.<br/>Notre esprit doit être nourri,<br/>Par Sa parole et Son Esprit.<br/>',NULL,27742,3);
INSERT INTO stanza VALUES('FR146','4','Ta substance est Esprit, Seigneur,<br/>Nous la trouvons dans Ta Parole.<br/>Seigneur, Tu te transmets à nous,<br/>Quand, dans l''esprit, nous Te prenons.<br/>',NULL,27743,4);
INSERT INTO stanza VALUES('FR146','5','Pour Te trouver dans Ta Parole,<br/>Il ne suffit pas de la lire<br/>Ni de sonder les écritures,<br/>C''est l''esprit, qu''il faut exercer.<br/>',NULL,27744,5);
INSERT INTO stanza VALUES('FR146','6','Le vrai festin, c''est Ta Parole,<br/>Qui nourrit notre homme intérieur.<br/>Nous la prions et, en esprit,<br/>Nous apprenons à la manger.<br/>',NULL,27745,6);
INSERT INTO stanza VALUES('FR146','7','Donc, Ta Parole doit aller<br/>Par delà notre intelligence,<br/>Jusqu''à atteindre notre esprit,<br/>Pour devenir esprit et vie.<br/>',NULL,27746,7);
INSERT INTO stanza VALUES('FR146','8','Le moyen de Te contacter,<br/>C''est festoyer de Ta Parole,<br/>Étant actifs dans notre esprit,<br/>Venant à Toi pour Te toucher.<br/>',NULL,27747,8);
INSERT INTO stanza VALUES('FR146','9','Tu dois nous enseigner, Seigneur,<br/>À exercer l''esprit en nous,<br/>Nous serons donc de Toi nourris,<br/>Quand Ta Parole nous mangeons.<br/>',NULL,27748,9);
INSERT INTO stanza VALUES('FR147','1','Le Corps de Christ, l''église,<br/>Est la maison de Dieu.<br/>Des pécheurs Dieu appelle,<br/>Les rassemble en ce lieu.<br/>Sauvée par le Calvaire,<br/>Élue avant les temps,<br/>L''église a la nature<br/>De son Seigneur vivant.<br/>',NULL,27749,1);
INSERT INTO stanza VALUES('FR147','2','En Christ, le nouvel homme<br/>A été engendré.<br/>Par l''Esprit qui l''abreuve,<br/>Le Corps est sanctifié.<br/>Christ, sa Tête, lui donne<br/>Croissance, force et vie<br/>Et dans les lieux célestes<br/>Il vainc Son ennemi.<br/>',NULL,27750,2);
INSERT INTO stanza VALUES('FR147','3','L''église se repose,<br/>Sur Christ son fondement.<br/>Par Lui, elle est divine,<br/>En tous ses éléments.<br/>Ses saints expérimentent<br/>La croix par Son Esprit.<br/>En Christ seul ils subsistent,<br/>Ensemble ils sont bâtis.<br/>',NULL,27751,3);
INSERT INTO stanza VALUES('FR147','4','En Dieu, Christ et l''Esprit Saint,<br/>Ses membres ne font qu''un.<br/>Dans la foi, l''espérance,<br/>Le baptême, ils sont un.<br/>Car le Dieu trinitaire,<br/>Du Corps et l''unité,<br/>Manifestant la gloire,<br/>Pour toute éternité.<br/>',NULL,27752,4);
INSERT INTO stanza VALUES('FR147','5','Les membres de l''église,<br/>Proviennent de tous lieux.<br/>Issus de toute classe,<br/>Ils sont unis en Dieu.<br/>Ni maitre, ni esclave,<br/>Ni clan Juif ou Gentil,<br/>Ni l''humble, ni le libre,<br/>Le « nouvel homme » est Christ.<br/>',NULL,27753,5);
INSERT INTO stanza VALUES('FR147','6','Universel est Son Corps,<br/>Locale est l''expression.<br/>Le terrain de la ville,<br/>En est la dimension.<br/>Chaque assemblée possède<br/>Son administration,<br/>Mais toutes les églises<br/>Demeurent en communion.<br/>',NULL,27754,6);
INSERT INTO stanza VALUES('FR147','7','Modèle des églises<br/>Est la sainte cité.<br/>Ses caractéristiques,<br/>Déterminent leurs traits.<br/>Christ est la lampe qui luit,<br/>La lumière en est Dieu,<br/>Ce sont des chandeliers d''or,<br/>L''exprimant en tout lieu.<br/>',NULL,27755,7);
INSERT INTO stanza VALUES('FR148','1','Toi, Seigneur, le grand Potier,<br/>Créateur que nous louons,<br/>Tu façonnes, Tu construis<br/>Ton chef-d''œuvre, Ta maison.<br/>Je suis homme fait d''argile,<br/>Devenu pierre vivante.<br/>Oui, je suis Ton vase saint,<br/>À Ton temple j''appartiens.<br/>',NULL,27756,1);
INSERT INTO stanza VALUES('FR148','2','Bien qu''argile nous soyons,<br/>Tu voulus nous façonner.<br/>En or pur, en vrais joyaux,<br/>Tu voulus nous transformer.<br/>En un seul Corps, tous unis,<br/>Dans l''amour, Tu nous bâtis.<br/>Et Ton cœur, ainsi comblé,<br/>Par l''épouse est satisfait.<br/>',NULL,27757,2);
INSERT INTO stanza VALUES('FR148','3','Tu ne veux pas que des pierres,<br/>Quand bien même nous brillons,<br/>Tu dois tous nous édifier,<br/>Pour Ta gloire, Ta maison.<br/>Toi, le Christ riche et glorieux,<br/>C''est l''église que Tu veux,<br/>Pour que puissent rayonner,<br/>Ta lumière et majesté.<br/>',NULL,27758,3);
INSERT INTO stanza VALUES('FR148','4','Ce n''est pas l''individu,<br/>Spirituel et isolé,<br/>Mais le Corps, qui peut combler<br/>Ton désir, Ta volonté.<br/>À cela aucun des membres,<br/>Séparé, ne peut prétendre,<br/>Seuls les membres édifiés<br/>Pourront Ta gloire exprimer.<br/>',NULL,27759,4);
INSERT INTO stanza VALUES('FR148','5','Édifie-moi, restreins-moi,<br/>Unis-moi à d''autres saints.<br/>À Ton aise ajuste-moi,<br/>Pour l''église, Ton dessein.<br/>Je ne cherche plus ma gloire,<br/>Ni mes dons, ni mes victoires.<br/>Je ne veux que Ta maison,<br/>Elle est Ta satisfaction.<br/>',NULL,27760,5);
INSERT INTO stanza VALUES('FR149','1','Toi seul es ma vie,<br/>Bien-aimé Seigneur.<br/>Dans Ta plénitude,<br/>Tu remplis mon cœur.<br/>Ta nature sainte<br/>Va me sanctifier,<br/>Ta résurrection va en moi triompher.<br/>',NULL,27761,1);
INSERT INTO stanza VALUES('FR149','2','Ton courant de vie,<br/>Brille dans mon cœur,<br/>Me ramène à l''esprit,<br/>À Toi cher Seigneur.<br/>Tu m''approvisionnes,<br/>Combles mes besoins.<br/>En Toi je demeure, purifié et saint.<br/>',NULL,27762,2);
INSERT INTO stanza VALUES('FR149','3','Ton onction me donne<br/>Tous Tes éléments.<br/>Elle me transforme,<br/>En me saturant.<br/>En moi cette vie<br/>Je laisse opérer,<br/>Tu vas me conduire à maturité.<br/>',NULL,27763,3);
INSERT INTO stanza VALUES('FR149','4','Ta vie abondante<br/>Coule librement<br/>Et me fortifie,<br/>M''abreuve en tout temps.<br/>La mort par la vie<br/>Est anéantie.<br/>Par la loi de vie, Je suis affranchi.<br/>',NULL,27764,4);
INSERT INTO stanza VALUES('FR149','5','Seigneur, je me donne<br/>À Toi pleinement.<br/>En moi je Te laisse<br/>Accomplir Ton plan.<br/>Vaines sont mes luttes,<br/>Mes résolutions.<br/>Oh ! que rien n''empêche ton opération !<br/>',NULL,27765,5);
INSERT INTO stanza VALUES('FR149','6','Libéré des luttes,<br/>Je Te laisse œuvrer.<br/>Gagne enfin mon être<br/>Pour le transformer.<br/>Bâtis-moi, je Te prie,<br/>Avec tous les saints,<br/>Glorifie-Toi en nous, tel est Ton dessein.<br/>',NULL,27766,6);
INSERT INTO stanza VALUES('FR150','1','Que mon esprit, Seigneur, puisse couler !<br/>C''est le vœu de mon cœur, oh ! coule en moi !<br/>Oubliant le passé, je Te laisse opérer.<br/>Je veux que mon esprit soit libéré.<br/>',NULL,27767,1);
INSERT INTO stanza VALUES('FR150','2','Que mon esprit, Seigneur, puisse couler !<br/>C''est mon désir ardent, oh ! coule en moi !<br/>Lié par ma fierté, je me sens encombré.<br/>Je veux que mon esprit soit dégagé.<br/>',NULL,27768,2);
INSERT INTO stanza VALUES('FR150','3','Que mon esprit, Seigneur, puisse couler !<br/>C''est mon soupir profond, oh ! coule en moi !<br/>Je ne veux plus laisser l''orgueil m''emprisonner.<br/>Je veux que mon esprit soit délivré.<br/>',NULL,27769,3);
INSERT INTO stanza VALUES('FR150','4','Que mon esprit, Seigneur, puisse couler !<br/>Je cherche Ta présence, oh ! coule en moi !<br/>Plus jamais isolé, ni me croyant parfait,<br/>Je veux que mon esprit soit délié.<br/>',NULL,27770,4);
INSERT INTO stanza VALUES('FR150','5','Que mon esprit, Seigneur, puisse couler !<br/>C''est ma supplication, oh ! coule en moi !<br/>Je me renierai, la croix je connaitrai.<br/>Je veux que mon esprit soit déchargé.<br/>',NULL,27771,5);
INSERT INTO stanza VALUES('FR150','6','Que mon esprit, Seigneur, puisse couler !<br/>Exauce ma prière, oh ! coule en moi !<br/>Je veux être édifié, dans le Corps ajusté,<br/>Que Ton désir, Seigneur, soit satisfait.<br/>',NULL,27772,6);
INSERT INTO stanza VALUES('FR151','1','J''aime l''église, Ta maison,<br/>Là, Tu veux demeurer.<br/>Tu la désires, la chéris,<br/>Ton cœur y est comblé.<br/>',NULL,27773,1);
INSERT INTO stanza VALUES('FR151','2','Pour l''acquérir, Tu t''es livré,<br/>L''église T''appartient.<br/>Je Te présente aussi mon corps,<br/>En sacrifice saint.<br/>',NULL,27774,2);
INSERT INTO stanza VALUES('FR151','3','Pour T''exprimer dans Ton église,<br/>Tu m''as transmis Ta vie.<br/>Elle devient Ta plénitude,<br/>Lorsque je me renie.<br/>',NULL,27775,3);
INSERT INTO stanza VALUES('FR151','4','Dans Ta maison, Tu me fournis<br/>L''approvisionnement.<br/>Tu m''as pour elle capturé,<br/>Je l''aime tendrement.<br/>',NULL,27776,4);
INSERT INTO stanza VALUES('FR151','5','Dans Ton épouse bien-aimée,<br/>Je perçois Ton désir.<br/>Elle est aussi toute ma joie,<br/>J''y trouve mon plaisir.<br/>',NULL,27777,5);
INSERT INTO stanza VALUES('FR151','6','J''aime l''église, Ta demeure,<br/>Qui Ton cœur satisfait.<br/>Je l''aimerai, j''y resterai<br/>Sans jamais dévier.<br/>',NULL,27778,6);
INSERT INTO stanza VALUES('FR152','1','Chantons Ses louanges, chantons au Seigneur !<br/>Au lieu choisi, l''église, Son bonheur.<br/>À Jérusalem, que Dieu soit célébré !<br/>Avec Son peuple Il désire habiter.<br/>C''est de Sion que parait le salut !<br/>C''est là que Dieu rassemble Ses élus !<br/>Crions de joie, oui, réjouissons-nous !<br/>Crions de joie, oui, réjouissons-nous !<br/>',NULL,27779,1);
INSERT INTO stanza VALUES('FR152','2','Dans la ville sainte, parmi tous les Tiens,<br/>Ta gloire brille, que Ton nom est saint !<br/>Tu es célébré par toute l''assemblée,<br/>Là, à Sion, Tes désirs sont comblés.<br/>Toute l''église Te suit pas à pas.<br/>Nous témoignons que Tu es notre Roi,<br/>Notre héritage, notre unique bien !<br/>Notre héritage, notre unique bien !<br/>',NULL,27780,2);
INSERT INTO stanza VALUES('FR152','3','Qui s''élèvera jusqu''au lieu saint de Dieu ?<br/>Qui entrera dans Son temple glorieux ?<br/>Celui qui Te cherche et purifie son cœur,<br/>Celui qui marche devant Toi, Seigneur.<br/>Cherchons Sa face et tournons-nous vers Lui !<br/>Ouvrons nos cœurs, qu''Il y règne aujourd''hui !<br/>N''attendons plus, le Roi veut revenir !<br/>N''attendons plus, le Roi veut revenir !<br/>',NULL,27781,3);
INSERT INTO stanza VALUES('FR152','4','Tout est accompli : Dieu est avec les Siens,<br/>Son tabernacle est l''œuvre de Ses mains.<br/>Christ est le vainqueur ! Enfants de Dieu, voyez !<br/>Jérusalem, la ville est édifiée !<br/>Ouvrons nos portes, laissons-Le entrer !<br/>Levons nos têtes, Christ revient régner !<br/>Crions de joie, Son règne est éternel !<br/>Crions de joie, Son règne est éternel !<br/>',NULL,27782,4);
INSERT INTO stanza VALUES('FR153','1','Te connaitre dans l''église<br/>Est mon grand besoin, Seigneur,<br/>Et Te voir dans tous Tes membres,<br/>La prière de mon cœur.<br/>Non plus simplement connaitre<br/>Une « Tête séparée »,<br/>Mais, Te voir Seigneur, incarné<br/>Dans le Corps, selon Ton plan.<br/>',NULL,27783,1);
INSERT INTO stanza VALUES('FR153','2','Tant de saints, pendant des siècles,<br/>Ont cherché Ta réalité.<br/>Ils T''ont poursuivi sans cesse,<br/>Pour Te voir, Te contempler.<br/>Maintenant, le Christ des cieux est<br/>Dans Ses membres, révélé.<br/>Maintenant, le Christ en nous est<br/>Dans le Corps, manifesté.<br/>',NULL,27784,2);
INSERT INTO stanza VALUES('FR153','3','Oui, enclin à la déroute<br/>Par mes propres conceptions,<br/>Je Te cherche, mais je ne peux<br/>Toucher Ta réalité.<br/>Oh ! Seigneur, combien il me faut<br/>Te connaitre dans le Corps !<br/>Demeurant parmi les hommes,<br/>Dieu est révélé en chair.<br/>',NULL,27785,3);
INSERT INTO stanza VALUES('FR153','4','Détruit mon indépendance,<br/>Tourne-moi vers Ton église !<br/>Je ne veux plus simplement voir<br/>La lumière issue du ciel.<br/>Je veux apprendre à connaitre<br/>Tes richesses dans le Corps,<br/>Être bâti dans l''église,<br/>Pour enfin Te satisfaire.<br/>',NULL,27786,4);
INSERT INTO stanza VALUES('FR154','1','Admirons l''église du Seigneur : combien elle est glorieuse !<br/>Quelle gloire notre Dieu nous a unis !<br/>Il y a un Corps dans l''univers ; nous en faisons partie.<br/>Alléluia ! Le Seigneur nous a unis !<br/><br/>Alléluia pour l''église !<br/>Nous donnons tout pour l''église.<br/>Nous voici, Son Corps, Ses membres,<br/>Alléluia ! Le Seigneur nous a unis !<br/>',NULL,27787,1);
INSERT INTO stanza VALUES('FR154','2','Le Seigneur n''a pas besoin que de croyants individuels,<br/>Non ! Il veut gagner une expression sur terre.<br/>C''est Son Corps, Sa plénitude, qui Son cœur peut satisfaire.<br/>Alléluia ! Nous faisons partie du Corps !<br/><br/>Alléluia pour l''église !<br/>Satan fuit devant l''église !<br/>Oui, au Corps est la victoire,<br/>Alléluia ! Nous faisons partie du Corps !<br/>',NULL,27788,2);
INSERT INTO stanza VALUES('FR154','3','Il y a sept chandeliers en or qui sont purs et divins,<br/>Rien de naturel le Corps n''acceptera !<br/>Si nous conservons notre unité, remplis de Sa nature<br/>Alléluia ! Que l''église brillera !<br/><br/>Alléluia pour l''église !<br/>Pour les chandeliers qui luisent !<br/>Ils sont purs, divins et glorieux,<br/>Alléluia ! Car ils brillent maintenant !<br/>',NULL,27789,3);
INSERT INTO stanza VALUES('FR154','4','Or, comment manifester cette unité bénie de Dieu ?<br/>Alléluia ! Nous devons manger Jésus.<br/>Il est l''arbre de la vie et notre manne : quel festin !<br/>Alléluia ! Chaque jour, mangeons de Lui !<br/><br/>Nous mangeons, Il nous rend tous un.<br/>Nous mangeons, Il nous rend divins.<br/>Nous mangeons, Il nous rend brillants,<br/>Alléluia ! Chaque jour, mangeons de Lui !<br/>',NULL,27790,4);
INSERT INTO stanza VALUES('FR155','1','Il vient d''abord seul pour mourir,<br/>Afin de nous donner la vie,<br/>Puis reviendra chercher pour Lui,<br/>Une glorieuse épouse.<br/>',NULL,27791,1);
INSERT INTO stanza VALUES('FR155','chorus','Ô Jésus, reviens bientôt !<br/>Cher époux, nous T''attendons.<br/>Ô Jésus, remplis nos cœurs !<br/>Nous serons Ton épouse.<br/>',NULL,27792,2);
INSERT INTO stanza VALUES('FR155','2','Ce que désire le Seigneur,<br/>La seule attente de Son cœur,<br/>C''est que Ses saints soient tout à Lui,<br/>Pour être Son épouse.<br/>',NULL,27793,3);
INSERT INTO stanza VALUES('FR155','3','À Lui, nous serons présentés,<br/>Comme une vierge préparée.<br/>Chacun de nous peut se parer,<br/>En ne vivant que par Lui !<br/>',NULL,27794,4);
INSERT INTO stanza VALUES('FR155','4','Comment peut-on ce monde aimer,<br/>Quand Christ languit de se marier ?<br/>Son retour nous pouvons hâter,<br/>En aimant Christ, notre époux !<br/>',NULL,27795,5);
INSERT INTO stanza VALUES('FR156','1','Il nous a trouvés, à l''église amenés,<br/>Où les frères sont à la maison.<br/>Ici, Christ est vie,<br/>Les tensions sont bannies.<br/>Alléluia ! Pour Christ et l''église !<br/><br/>Ici, dans l''église,<br/>Notre recherche s''est terminée.<br/>Or, de jour en jour,<br/>Chantons dans Son amour :<br/>Alléluia ! Pour Christ et l''église !<br/>',NULL,27796,1);
INSERT INTO stanza VALUES('FR156','2','Oui, Dieu se repose, Son dessein atteint.<br/>Enfin, Il a trouvé Sa maison.<br/>Il se plait en nous,<br/>Fait de nous Sa demeure,<br/>Puis Sa gloire en nous resplendira.<br/><br/>Ici, dans l''église,<br/>Oui, Sa recherche s''est terminée.<br/>Or, dans Son amour,<br/>Proclamons chaque jour :<br/>Alléluia pour Christ et l''église !<br/>',NULL,27797,2);
INSERT INTO stanza VALUES('FR157','1','L''église est un jardin riche, verdoyant et plein de vie,<br/>C''est ici que Jésus-Christ prend forme et croit.<br/>Il est accessible et frais, ici chacun jouit de Lui.<br/>L''unité de tous Ses saints L''emplit de joie !<br/>',NULL,27798,1);
INSERT INTO stanza VALUES('FR157','chorus','Je suis heureux dans ce lieu glorieux :<br/>Un jardin de grâce merveilleux !<br/>Avec joie, je me nourris<br/>Du fruit de l''arbre de la vie<br/>Et je bois l''eau qui jaillit dans mon esprit.<br/>',NULL,27799,2);
INSERT INTO stanza VALUES('FR157','2','Ce n''est pas une chapelle ni un ordre religieux,<br/>Mais un beau jardin où Dieu peut se semer.<br/>Jésus nous a rassemblés pour former ce verger glorieux,<br/>Qu''Il peut librement soigner et cultiver.<br/>',NULL,27800,3);
INSERT INTO stanza VALUES('FR157','3','Au milieu de ce jardin, un petit arbre plein de vie<br/>Porte chaque mois des fruits si savoureux.<br/>Ouvre-toi donc simplement, pour que ton cœur soit adouci,<br/>Mange ce Jésus qui est si délicieux !<br/>',NULL,27801,4);
INSERT INTO stanza VALUES('FR157','4','Près de l''arbre coule un fleuve : Dieu en Christ, qui nous atteint,<br/>Il étanche notre soif et nous unit.<br/>Alléluia ! Jésus coule librement dans ce jardin,<br/>Nous arrose, nous remplit, nous fait grandir.<br/>',NULL,27802,5);
INSERT INTO stanza VALUES('FR157','5','Si tu vois vraiment pourquoi notre Seigneur t''y a conduit,<br/>Tu ne pourras t''empêcher de Le louer !<br/>Sois heureux, réjouis-toi, reste en esprit et sois rempli,<br/>Et les fruits de Son jardin vont abonder.<br/>',NULL,27803,6);
INSERT INTO stanza VALUES('FR158','beginning-note','(Répétez les quatre derniers vers de la dernière strophe.)<br/>',NULL,27804,1);
INSERT INTO stanza VALUES('FR158','1','Non, je n''entrerai pas<br/>Dans la tente où je réside,<br/>Je ne monterai pas<br/>Sur le lit où je repose !<br/>Je ne donnerai de repos,<br/>À mes yeux pour mon Dieu,<br/>Jusqu''à ce que je trouve un lieu,<br/>Où Il puisse habiter.<br/>',NULL,27805,2);
INSERT INTO stanza VALUES('FR158','2','Combien l''aveuglement<br/>Nous emporte et nous égare,<br/>Jamais ne nous souciant<br/>De l''église, Sa demeure.<br/>Jamais nous ne redirons plus :<br/>« Le temps n''est pas venu. »<br/>Nous monterons, nous bâtirons,<br/>La maison du Seigneur.<br/>',NULL,27806,3);
INSERT INTO stanza VALUES('FR158','3','Comme au temps de David,<br/>Ô Seigneur, convaincs des hommes.<br/>En eux mets le désir,<br/>D''accomplir Ton plan sur terre.<br/>Seigneur, nous nous réjouissons,<br/>De venir pour bâtir !<br/>C''est Ton désir, notre désir,<br/>Oui, nous venons, Seigneur.<br/>',NULL,27807,4);
INSERT INTO stanza VALUES('FR158','4','Seigneur, mets dans le cœur<br/>De tous ceux que Tu appelles,<br/>La vraie consécration,<br/>Qui pourra Ton but atteindre.<br/>L''enfer ne pourra prévaloir,<br/>L''église est édifiée !<br/>L''heure est venue, grandis en nous,<br/>Ensemble bâtis-nous !<br/>',NULL,27808,5);
INSERT INTO stanza VALUES('FR159','1','Oui ! Nous sommes tous sortis<br/>De la Grande Babylone !<br/>Pour aller au lieu choisi,<br/>Oh ! gloire à notre Dieu !<br/>À Jérusalem unis,<br/>Nous vivons dans notre esprit.<br/>Le Seigneur est notre vie,<br/>Aujourd''hui, dans les églises.<br/>',NULL,27809,1);
INSERT INTO stanza VALUES('FR159','chorus','Alléluia ! Alléluia !<br/>L''unité nous conservons,<br/>Pour construire Sa maison.<br/>Alléluia ! Alléluia !<br/>Nous vivons dans les églises maintenant !<br/>',NULL,27810,2);
INSERT INTO stanza VALUES('FR159','2','Que suscite le Seigneur,<br/>Pour accomplir Son dessein ?<br/>Tant de sacrificateurs !<br/>Oh ! gloire à notre Dieu !<br/>Ceux qui vivent par le Christ,<br/>Saturés de Son Esprit,<br/>Ils produisent l''édifice,<br/>Aujourd''hui, dans les églises.<br/>',NULL,27811,3);
INSERT INTO stanza VALUES('FR159','3','Sa divine royauté,<br/>Dans l''église est restaurée.<br/>Son royaume est exprimé,<br/>Oh ! gloire à notre Dieu !<br/>Étant soumis à l''esprit,<br/>Son église s''édifie<br/>Et la vie se multiplie,<br/>Aujourd''hui, dans les églises.<br/>',NULL,27812,4);
INSERT INTO stanza VALUES('FR159','4','L''autel doit être érigé,<br/>Pour qu''y brule mon offrande,<br/>Et qu''à Dieu je sois donné,<br/>Oh ! gloire à notre Dieu !<br/>Nous nous consacrons à Lui<br/>Et donnons tout pour l''église.<br/>Quelle gloire et quel honneur,<br/>Aujourd''hui, dans les églises.<br/>',NULL,27813,5);
INSERT INTO stanza VALUES('FR159','5','Nous avons le fondement,<br/>Dans l''église maintenant,<br/>Nous voici, de joie remplis,<br/>Oh ! gloire à notre Dieu !<br/>Son église bâtissez !<br/>Oui, chantez, priez, louez !<br/>L''ennemi est écrasé,<br/>Aujourd''hui, dans les églises.<br/>',NULL,27814,6);
INSERT INTO stanza VALUES('FR160','1','Le recouvrement du Seigneur,<br/>Brule dans nos cœurs !<br/>Dieu recouvre Son église,<br/>Sur le terrain de la ville.<br/>L''unité de Dieu nous rend un,<br/>Nous la conservons,<br/>Pour ainsi bâtir le temple<br/>De notre Seigneur.<br/>',NULL,27815,1);
INSERT INTO stanza VALUES('FR160','chorus','Le recouvrement,<br/>A lieu maintenant,<br/>Le recouvrement de Sa maison.<br/>Nous nous consacrons,<br/>Notre tout donnant,<br/>Pour que s''accomplisse Son plan.<br/>',NULL,27816,2);
INSERT INTO stanza VALUES('FR160','2','Le recouvrement de l''église,<br/>À nos yeux est cher.<br/>Quand nous exerçons notre esprit,<br/>Cette vision est si chaire.<br/>Déjà, Babylone est tombée,<br/>L''ennemi, détruit !<br/>Car nous édifions l''église<br/>Sur le bon terrain.<br/>',NULL,27817,3);
INSERT INTO stanza VALUES('FR161','1','Nous prenons position,<br/>Pour Son église.<br/>Oui, Christ est notre vie,<br/>Il est le Bon pays.<br/>« En Christ, sur le terrain ! »<br/>C''est notre cri.<br/>Ici, nous vainquons l''ennemi,<br/>Et le Royaume est établi.<br/>',NULL,27818,1);
INSERT INTO stanza VALUES('FR162','1','Le Christ nous a appelés.<br/>Maintenant, Il nous rappelle,<br/>Car Il cherche des vainqueurs,<br/>Dis : « Amen ! »<br/>Son église s''affaiblit,<br/>Par tant de savoir remplie,<br/>Mais il lui manquait la vie :<br/>« Sois vainqueur ! »<br/>',NULL,27819,1);
INSERT INTO stanza VALUES('FR162','chorus','« Sois vainqueur ! Sois vainqueur ! »<br/>Tu vaincras le christianisme dégradé.<br/>Mets tes œuvres de coté,<br/>Les doctrines qui divisent,<br/>Sois vainqueur en mangeant Christ.<br/>« Sois vainqueur ! »<br/>',NULL,27820,2);
INSERT INTO stanza VALUES('FR162','2','Manger est le seul moyen<br/>De se remplir de la vie<br/>Et de vaincre l''ennemi,<br/>« Sois vainqueur ! »<br/>Viens ! Prends l''arbre de la vie<br/>Et renonce aux divisions,<br/>Sois vainqueur par Jésus-Christ,<br/>« Sois vainqueur ! »<br/>',NULL,27821,3);
INSERT INTO stanza VALUES('FR162','3','Les doctrines ne pourront<br/>Jamais transformer ton âme.<br/>Mange Jésus, tu verras<br/>Que c''est bon !<br/>Car pour vaincre, il faut manger,<br/>Le festin tout préparé,<br/>Dans le Corps, le partager,<br/>« Sois vainqueur ! »<br/>',NULL,27822,4);
INSERT INTO stanza VALUES('FR162','4','Mange afin que l''enfant mâle<br/>Puisse enfin être enfanté.<br/>Mange ! Le Seigneur revient,<br/>« Sois vainqueur ! »<br/>Sois l''enfant que Christ attend,<br/>Sois l''église qu''Il désire,<br/>Alors Christ aura l''épouse,<br/>« Sois vainqueur ! »<br/>',NULL,27823,5);
INSERT INTO stanza VALUES('FR163','1','Christ est le centre , Christ est tout pour nous<br/>Dans notre vie et dans nos réunions.<br/>Et par-delà les vérités reçues,<br/>C''est pour Lui seul que nous nous rassemblons.<br/>',NULL,27824,1);
INSERT INTO stanza VALUES('FR163','2','Lui, le chemin, lumière de la vie,<br/>Il nous conduit quand nous marchons en Lui.<br/>Christ est l''eau vive, Christ est notre pain,<br/>C''est Lui qui désaltère et rassasie.<br/>',NULL,27825,2);
INSERT INTO stanza VALUES('FR163','3','Christ est la vie, et nous Le dispensons,<br/>La vérité, de Lui nous témoignons.<br/>Christ est Seigneur et nous Le magnifions,<br/>Il est Tête que nous exaltons.<br/>',NULL,27826,3);
INSERT INTO stanza VALUES('FR163','4','Pour Dieu et l''homme, Christ est tout en tous,<br/>Avec Lui, l''homme et Dieu sont satisfaits.<br/>Réalité au sein de Son église,<br/>Il se propage et Sa vie se transmet.<br/>',NULL,27827,4);
INSERT INTO stanza VALUES('FR163','5','Chantons, prions, pour exprimer ce Christ,<br/>Qui est le centre de nos réunions.<br/>Par Sa puissance, nous pouvons servir,<br/>En demeurant sans cesse en communion.<br/>',NULL,27828,5);
INSERT INTO stanza VALUES('FR163','6','C''est dans Son nom que nous nous rassemblons,<br/>Dans Son Esprit, non dans nos opinions.<br/>Par Sa puissance, nous voulons prier,<br/>En esprit, Le louer, bénir son nom.<br/>',NULL,27829,6);
INSERT INTO stanza VALUES('FR163','7','Oublions tout, à Christ attachons-nous,<br/>Poursuivons-Le, cherchons-Le tous les jours.<br/>Considérons tout comme de la boue,<br/>Pour Le connaitre, Le gagner toujours.<br/>',NULL,27830,7);
INSERT INTO stanza VALUES('FR164','1','Quand nous venons aux réunions,<br/>En abondance Christ offrons.<br/>À Dieu, Son aliment donnons,<br/>Christ sera magnifié !<br/>',NULL,27831,1);
INSERT INTO stanza VALUES('FR164','chorus','À Dieu nous offrons Christ !<br/>Â Dieu nous offrons Christ !<br/>Chacun apporte sa portion,<br/>À Dieu, présente Christ !<br/>',NULL,27832,2);
INSERT INTO stanza VALUES('FR164','2','Le bon pays nous labourons,<br/>En Christ vivons et combattons.<br/>Puis, réunis, la dime offrons,<br/>Et Christ est magnifié !<br/>',NULL,27833,3);
INSERT INTO stanza VALUES('FR164','3','Christ est Lui-même ;''élément,<br/>L''essence de nos mouvements.<br/>C''est en formant Son Corps vivant,<br/>Que nous Le magnifions !<br/>',NULL,27834,4);
INSERT INTO stanza VALUES('FR164','4','Nous offrons Christ aux réunions,<br/>Ensemble, nous Le partageons.<br/>Devant Dieu, nous en jouissons,<br/>Et Christ est magnifié !<br/>',NULL,27835,5);
INSERT INTO stanza VALUES('FR164','5','Le Christ ressuscité offrons,<br/>Le Christ monté en ascension.<br/>Le bon plaisir de Dieu cherchons,<br/>Que Christ soit magnifié !<br/>',NULL,27836,6);
INSERT INTO stanza VALUES('FR164','6','Christ est celui que nous prêchons,<br/>Le sens de notre communion,<br/>Le centre de nos réunions.<br/>Lui seul est magnifié !<br/>',NULL,27837,7);
INSERT INTO stanza VALUES('FR164','7','Chantons, prions et témoignons,<br/>Servons, exerçons tous nos dons !<br/>Ensemble, Christ nous exprimons.<br/>Lui seul est magnifié !<br/>',NULL,27838,8);
INSERT INTO stanza VALUES('FR164','8','Ô Père ! Tu es glorifié,<br/>Quand nous T''offrons le Bien-aimé.<br/>Par Lui, nous voulons T''adorer<br/>Et Lui seul magnifier !<br/>',NULL,27839,9);
INSERT INTO stanza VALUES('FR165','1','Exerce ton esprit !<br/>Tes pensées rejette.<br/>Aux saints, toujours unis,<br/>Le Corps tu respectes.<br/>',NULL,27840,1);
INSERT INTO stanza VALUES('FR165','2','Exerce ton esprit !<br/>Toute forme oublie.<br/>Partage avec les saints,<br/>Jouis de ton Christ.<br/>',NULL,27841,2);
INSERT INTO stanza VALUES('FR165','3','Exerce ton esprit !<br/>À ton moi renonce.<br/>Servant avec les saints,<br/>Ton Seigneur annonce.<br/>',NULL,27842,3);
INSERT INTO stanza VALUES('FR165','4','Exerce ton esprit,<br/>Ton ame renie.<br/>Prends bien soin des autres,<br/>Prends Christ comme appui.<br/>',NULL,27843,4);
INSERT INTO stanza VALUES('FR165','5','Libéré en esprit,<br/>De tes propres lois,<br/>Ne te condamne pas,<br/>Mais sois à la croix.<br/>',NULL,27844,5);
INSERT INTO stanza VALUES('FR165','6','Libéré en esprit,<br/>Du moi obstiné<br/>Et de la vaine gloire, Pour tout surmonter.<br/>',NULL,27845,6);
INSERT INTO stanza VALUES('FR165','7','Exerce ton esprit,<br/>Sois donc victorieux,<br/>Par le sang qui lave, Par Son nom glorieux.<br/>',NULL,27846,7);
INSERT INTO stanza VALUES('FR165','8','Exerce ton esprit,<br/>Saisis le Seigneur,<br/>Prends la Parole en toi, Touchant ton esprit.<br/>',NULL,27847,8);
INSERT INTO stanza VALUES('FR165','9','Ton esprit te permet,<br/>De Le proclamer.<br/>Ton esprit te permet, D''être satisfait.<br/>',NULL,27848,9);
INSERT INTO stanza VALUES('FR165','10','Exerce ton esprit,<br/>C''est ton seul besoin,<br/>Exerce ton esprit, Et tout ira bien.<br/>',NULL,27849,10);
INSERT INTO stanza VALUES('FR166','1','Nous devons combattre, En avant, soldats !<br/>Dans l''armée de Jésus,<br/>Marchons sous Sa croix !<br/>En Vainqueur et Maitre,<br/>Notre roi nous dit :<br/>« Suivez Ma bannière<br/>Contre l''ennemi ! »<br/>',NULL,27850,1);
INSERT INTO stanza VALUES('FR166','chorus','Nous devons combattre,<br/>En avant, soldats !<br/>Dans l''armée de Jésus,<br/>Marchons sous la croix !<br/>',NULL,27851,2);
INSERT INTO stanza VALUES('FR166','2','Au seul nom de Jésus, L''armée de Satan,<br/>Devant nous recule.<br/>Allons de l''avant !<br/>An cri des louanges,<br/>L''enfer tremble et craint !<br/>Levons-nous, les frères,<br/>Chantons nos<br/>Refrains !<br/>',NULL,27852,3);
INSERT INTO stanza VALUES('FR166','3','Puissante est l''église, c''est l''armée de Dieu.<br/>Jésus l''a conduite,<br/>Sur la voie des cieux.<br/>C''est Son Corps unique,<br/>Jamais divisé,<br/>Car l''Esprit l''habite,<br/>Pour l''éternité !<br/>',NULL,27853,4);
INSERT INTO stanza VALUES('FR166','4','Les royaumes tombent, leur gloire pâlit,<br/>Tandis que l''église,<br/>Jamais ne périt.<br/>« L''enfer ne prévaut point<br/>Contre Ma maison » ,<br/>Jésus a proclamé,<br/>Et nous Le croyons !<br/>',NULL,27854,5);
INSERT INTO stanza VALUES('FR166','5','Venez, hommes, femmes, marchez avec nous !<br/>Chantons tous ensemble,<br/>Devant Lui, debout !<br/>Que même les anges<br/>Rejoignent nos voix !<br/>« Gloire, honneur, louanges,<br/>Au plus grand des rois ! »<br/>',NULL,27855,6);
INSERT INTO stanza VALUES('FR167','1','C''est un rempart que notre Dieu,<br/>Une invincible armure,<br/>Un défenseur victorieux,<br/>Une aide prompte et sure.<br/>L''ennemi, contre nous,<br/>Redouble de courroux :<br/>Vaine colère !<br/>Que pourrait l''adversaire ?<br/>L''éternel détourne ses coups.<br/>',NULL,27856,1);
INSERT INTO stanza VALUES('FR167','2','Seuls, nous bronchons à chaque pas<br/>Quand l''ennemi nous presse.<br/>Mais un héros pour nous combat<br/>Et nous soutient sans cesse.<br/>Quel est ce défenseur ?<br/>C''est Toi, divin Sauveur,<br/>Dieu des armées !<br/>Tes tribus opprimées<br/>Connaissent leur libérateur.<br/>',NULL,27857,2);
INSERT INTO stanza VALUES('FR167','3','Que les démons, forgeant des fers,<br/>Menacent Ton église,<br/>Ta Sion brave les enfers,<br/>Sur le rocher assise.<br/>Constant dans son effort,<br/>En vain, avec la mort,<br/>Satan conspire.<br/>Pour briser son empire,<br/>il suffit d''un mot du Dieu fort.<br/>',NULL,27858,3);
INSERT INTO stanza VALUES('FR167','4','Dis-le, ce mot victorieux<br/>Dans toutes nos détresses,<br/>Et donne-nous, du haut des cieux,<br/>Ta force et Ta sagesse.<br/>Qu''on nous ôte nos biens,<br/>Qu''on serre nos liens,<br/>Que nous importe !<br/>Ta grâce est la plus forte,<br/>Et Ton royaume est pour les Tiens.<br/>',NULL,27859,4);
INSERT INTO stanza VALUES('FR168','1','C''est la victoire ! Christ a vaincu l''ennemi,<br/>Ce cri de joie en tout lieu retentit.<br/>Le sang triomphe, nous voici, des victorieux.<br/>Bientôt le Vainqueur glorieux va venir.<br/>',NULL,27860,1);
INSERT INTO stanza VALUES('FR168','2','Quelle victoire ! Nous avons vaincu Satan !<br/>Nous proclamons Sa Parole hardiment.<br/>Dieu a parlé, et Sa Parole est vérité.<br/>Par elle, l''ennemi est écrasé !<br/>',NULL,27861,3);
INSERT INTO stanza VALUES('FR168','3','C''est la victoire ! L''ennemi est sous nos pieds !<br/>N''aimant pas notre âme jusqu''à la mort !<br/>Nous proclamons : « Seigneur, Tu es le Victorieux ! »<br/>De notre esprit, nous louons notre Dieu.<br/>',NULL,27862,4);
INSERT INTO stanza VALUES('FR169','1','Dans le fleuve divin, nous servons le Seigneur,<br/>Connaissant Sa pensée, Sa Parole et Son cœur.<br/>Dans ce courant de vie, vêtus de Sa puissance,<br/>Pour Son Corps, Son royaume et sous Son intendance.<br/>',NULL,27863,1);
INSERT INTO stanza VALUES('FR169','chorus','Dans le fleuve divin,<br/>Travaillons dans le fleuve !<br/>Dans le fleuve divin,<br/>Servons toujours dans ce courant.<br/>',NULL,27864,2);
INSERT INTO stanza VALUES('FR169','2','Dans le fleuve divin, nous servons le Seigneur,<br/>Sa Parole en nous vit, dans le courant demeure !<br/>N''œuvre pas solitairement et désuni,<br/>Mais sois coordonné, en parfaite harmonie.<br/>',NULL,27865,3);
INSERT INTO stanza VALUES('FR169','3','Dans le fleuve divin, nous servons le Seigneur,<br/>Dans le commun accord, les saints ont un seul cœur.<br/>Sers aux gens la Parole, en dispensant la vie,<br/>Dans ce fleuve, le dessein de Dieu s''accomplit.<br/>',NULL,27866,4);
INSERT INTO stanza VALUES('FR170','1','Prenons part au sacerdoce,<br/>Servons Dieu en Jésus-Christ.<br/>Il est tout : notre parure,<br/>Nos offrandes, notre vie.<br/>',NULL,27867,1);
INSERT INTO stanza VALUES('FR170','chorus','Quel honneur, quel privilège !<br/>Nous servons le Dieu vivant !<br/>Christ est tout, notre parure,<br/>Notre demeure en tout temps.<br/>',NULL,27868,2);
INSERT INTO stanza VALUES('FR170','2','La parure de service<br/>Manifeste Sa beauté.<br/>L''éphod et le pectoral sont<br/>Artistement travaillés.<br/>',NULL,27869,3);
INSERT INTO stanza VALUES('FR170','3','Nous offrons en sacrifice,<br/>Christ à Dieu, selon Son plan.<br/>Dieu devient la nourriture,<br/>Que nous prenons en servant.<br/>',NULL,27870,4);
INSERT INTO stanza VALUES('FR170','4','Du Seigneur nous nous revêtons,<br/>Pour qu''Il brille dans nos vies,<br/>Nous mangeons de Ses offrandes,<br/>Pour ne vivre que par Lui.<br/>',NULL,27871,5);
INSERT INTO stanza VALUES('FR170','5','Sa demeure est glorieuse,<br/>Jésus-Christ y resplendit.<br/>L''édifice en Lui s''élève,<br/>Quand nous servons en esprit.<br/>',NULL,27872,6);
INSERT INTO stanza VALUES('FR170','6','Louons-Le pour ce service,<br/>Don précieux pour tous les saints.<br/>Notre seul grand héritage,<br/>Sera Dieu, suprême bien.<br/>',NULL,27873,7);
INSERT INTO stanza VALUES('FR171','1','Que nous servions Dieu ou l''homme,<br/>En tout, Christ est dispensé.<br/>Offrons-Le en abondance,<br/>Par Lui, Dieu sera comblé.<br/>',NULL,27874,1);
INSERT INTO stanza VALUES('FR171','chorus','Que nous servions Dieu ou l''homme,<br/>En tout, Christ est dispensé.<br/>Offrons-Le en abondance,<br/>Par Lui, Dieu sera comblé.<br/>',NULL,27875,2);
INSERT INTO stanza VALUES('FR171','2','Israel offrait en son temps,<br/>Les produits du bon pays.<br/>Nous aussi, moissonnons Jésus,<br/>Servons-Le, au Dieu béni !<br/>',NULL,27876,3);
INSERT INTO stanza VALUES('FR171','3','Christ est notre riche pays,<br/>Nous voulons Le labourer.<br/>Moissonnons-Le abondamment,<br/>Pour ensemble festoyer.<br/>',NULL,27877,4);
INSERT INTO stanza VALUES('FR171','4','Attachons-nous à la Tête,<br/>Nous croitrons, fonctionnerons.<br/>Dans le Corps, à chaque membre,<br/>Notre portion servirons.<br/>',NULL,27878,5);
INSERT INTO stanza VALUES('FR171','5','Vivons Christ et témoignons-en.<br/>Quand pour Lui nous travaillons,<br/>Magnifions-Le dans notre œuvre.<br/>Constamment en Lui vivons.<br/>',NULL,27879,6);
INSERT INTO stanza VALUES('FR172','1','Sur les chemins et sentiers de la vie,<br/>Beaucoup sont las et blessés.<br/>Sois la lumière au milieu de leur nuit,<br/>Donne espoir aux affligés !<br/>',NULL,27880,1);
INSERT INTO stanza VALUES('FR172','chorus','Fais que je brille ! Fais que je brille !<br/>Que je rayonne en Jésus-Christ !<br/>Fais que je brille, Sauveur, Dieu d''amour,<br/>Fais que je brille pour quelqu''un, ce jour !<br/>',NULL,27881,2);
INSERT INTO stanza VALUES('FR172','2','Parle de Christ et de Son grand amour,<br/>Dis qu''Il pardonne à chacun !<br/>D''autres à Dieu auront aussi recours,<br/>Si tu deviens Son parfum.<br/>',NULL,27882,3);
INSERT INTO stanza VALUES('FR172','3','Donne, car dans ton besoin tu reçus,<br/>Aime, car Dieu t''a aimé !<br/>Sois un secours pour ceux qui sont perdus,<br/>Sois un fidèle envoyé !<br/>',NULL,27883,4);
INSERT INTO stanza VALUES('FR173','1','Dois-je donc bras et mains vides,<br/>Mon Rédempteur rencontrer ?<br/>Être un serviteur indigne,<br/>Sans trophée à Lui donner ?<br/>',NULL,27884,1);
INSERT INTO stanza VALUES('FR173','chorus','Devrais-je donc, bras et mains vides,<br/>Au Sauveur me présenter ?<br/>Et comme une femme stérile,<br/>Sans enfants me présenter ?<br/>',NULL,27885,2);
INSERT INTO stanza VALUES('FR173','2','La mort ne me fait pas trembler :<br/>Mon salut est assuré.<br/>Mais mon tourment, c''est de penser,<br/>Qu''à Lui j''irai, sans trophée.<br/>',NULL,27886,3);
INSERT INTO stanza VALUES('FR173','3','Tant d''années gâchées au péché !<br/>Si je pouvais les refaire,<br/>Au Sauveur je les donnerai,<br/>Pour Son dessein satisfaire.<br/>',NULL,27887,4);
INSERT INTO stanza VALUES('FR173','4','Levons-nous et soyons fidèles !<br/>Tant qu''il fait jour, travaillons !<br/>Avant que la mort ne nous prenne,<br/>Pour les âmes combattons !<br/>',NULL,27888,5);
INSERT INTO stanza VALUES('FR174','1','Je suis un homme,<br/>La raison, le sens de l''univers.<br/>Je suis un homme,<br/>La raison, le sens de l''univers.<br/>Dieu m''a créé,<br/>Pour L''exprimer.<br/>Moi, le centre, la raison, le sens de l''univers !<br/>',NULL,27889,1);
INSERT INTO stanza VALUES('FR174','2','Christ vit en moi,<br/>Lui, le sens de toute vie humaine.<br/>Christ vit en moi,<br/>Lui, le sens de toute vie humaine.<br/>Dans mon esprit,<br/>Il me remplit,<br/>Lui, le sens, la réalité de toute vie humaine.<br/>',NULL,27890,2);
INSERT INTO stanza VALUES('FR174','3','L''église est Christ !<br/>Exprimé aujourd''hui sur la terre.<br/>L''église est Christ !<br/>Exprimé aujourd''hui sur la terre.<br/>Pour obtenir,<br/>Son bon plaisir,<br/>Dieu veut que le nouvel homme puisse L''exprimer.<br/>',NULL,27891,3);
INSERT INTO stanza VALUES('FR174','4','Oui, dans l''église,<br/>Notre vie est riche en communion.<br/>Oui, dans l''église,<br/>Notre vie est riche en communion.<br/>C''est en mangeant,<br/>Et en buvant,<br/>Que nous sommes édifiés toujours dans les églises.<br/>',NULL,27892,4);
INSERT INTO stanza VALUES('FR174','5','Qu''allons-nous faire ?<br/>Annonçons-Le dans le monde entier !<br/>Qu''allons-nous faire ?<br/>Annonçons-Le dans le monde entier !<br/>Publions-Le !<br/>Déclarons-Le !<br/>Que cette nouvelle parcoure la terre entière !<br/>',NULL,27893,5);
INSERT INTO stanza VALUES('FR175','1','J''ai, de mes yeux, vu Dieu le Véritable.<br/>Oh ! quel transfert j''ai expérimenté !<br/>Et je suis passé de l''ombre à la lumière.<br/>Oh ! quel salut ! Sa grâce Il m''a donné.<br/>',NULL,27894,1);
INSERT INTO stanza VALUES('FR175','2','Tu m''as sauvé, sauve aussi ma famille,<br/>Tu t''es livré aussi pour leurs péchés.<br/>Tu l''as promis : crois en Jésus le Seigneur,<br/>Ta maisonnée sera aussi sauvée.<br/>',NULL,27895,2);
INSERT INTO stanza VALUES('FR175','3','Entends Seigneur, mon cri pour ma famille,<br/>J''ai dans mon cœur, formé ce vœu pour eux :<br/>Moi et les miens, nous servirons le Seigneur,<br/>L''adorerons, Il est le seul vrai Dieu.<br/>',NULL,27896,3);
INSERT INTO stanza VALUES('FR176','1','Le matin nous sortons semer Sa parole.<br/>Tout le jour, nous voulons témoigner de Lui.<br/>Lors de la récolte, rassemblons les gerbes,<br/>Avec allégresse, récoltons les fruits.<br/>',NULL,27897,1);
INSERT INTO stanza VALUES('FR176','chorus','Récoltons les fruits, récoltons les fruits,<br/>Avec allégresse, récoltons les fruits.<br/>Récoltons les fruits, récoltons les fruits,<br/>Avec allégresse, récoltons les fruits.<br/>',NULL,27898,2);
INSERT INTO stanza VALUES('FR176','2','De l''aube à l''aurore, semons Sa parole,<br/>Qu''il vente ou qu''il pleuve, dispensons Sa vie !<br/>Après avoir œuvré, labouré et semé,<br/>Avec allégresse, récoltons les fruits.<br/>',NULL,27899,3);
INSERT INTO stanza VALUES('FR176','3','Nous semons en pleurant, moissonnons en chantant,<br/>Toute perte afflige, mais restons hardis.<br/>Attendons le Maitre, car Il va paraitre,<br/>Avec allégresse, récoltons les fruits.<br/>',NULL,27900,4);
INSERT INTO stanza VALUES('FR177','1','Je suis mort en Christ mon Sauveur,<br/>Dans l''eau du baptême enseveli,<br/>Et le monde n''a plus d''attrait,<br/>Car mon Dieu en Christ l''a crucifié.<br/>Avec Christ ressuscité,<br/>Je sers Dieu en nouveauté de vie.<br/>J''ai le soutien de Son Esprit<br/>Et dans mon esprit Sa puissance agit !<br/>',NULL,27901,1);
INSERT INTO stanza VALUES('FR178','1','Je suis mort et enseveli !<br/>Mon vieil homme anéanti !<br/>Je suis mort et enseveli !<br/>Mon vieil homme anéanti !<br/>',NULL,27902,1);
INSERT INTO stanza VALUES('FR178','2','Ce n''est plus moi, mais Christ qui vit !<br/>Christ en moi est exprimé !<br/>Ce n''est plus moi, mais Christ qui vit !<br/>Christ en moi est exprimé !<br/>',NULL,27903,2);
INSERT INTO stanza VALUES('FR179','1','Jésus, le royaume en nous, est venu,<br/>Dans notre esprit, nous L''avons tous reçu.<br/>Comme une semence en nous Il entra,<br/>Jour après jour, en nous, Il veut régner.<br/>',NULL,27904,1);
INSERT INTO stanza VALUES('FR179','chorus','Laissons-Le donc en nous grandir !<br/>Le royaume en nous doit grandir.<br/>Le royaume en nous, Jésus, veut fleurir,<br/>Le royaume en nous, Jésus, doit grandir.<br/>',NULL,27905,2);
INSERT INTO stanza VALUES('FR179','2','Repentons-nous car le royaume est proche.<br/>Laissons nos œuvres, nos plans, nos pensées.<br/>Changeons de voie pour nous soumettre au Roi.<br/>Laissons nos concepts et suivons le Roi !<br/>',NULL,27906,3);
INSERT INTO stanza VALUES('FR179','3','Plein d''enseignements et de concepts,<br/>Aujourd''hui, à nouveau, la religion<br/>Passe à coté du royaume des cieux,<br/>En négligeant la croissance de vie.<br/>',NULL,27907,4);
INSERT INTO stanza VALUES('FR179','4','Mais, le royaume nous est révélé :<br/>C''est Jésus seul, en nous Il s''est semé.<br/>Car Sa semence en nous a pénétré,<br/>Lorsque Son nom nous avons invoqué.<br/>',NULL,27908,5);
INSERT INTO stanza VALUES('FR180','1','Dieu a révélé un grand mystère en moi.<br/>Maintenant je suis rempli d''espoir.<br/>Dieu demeure en Christ, qui est la vie en moi,<br/>Il est l''espérance de ma gloire !<br/>',NULL,27909,1);
INSERT INTO stanza VALUES('FR180','chorus','Gloire ! Gloire ! Christ en moi la vie !<br/>Gloire ! Gloire ! C''est Lui mon espoir !<br/>Christ est le mystère en moi, dans mon esprit,<br/>Il est l''espérance de ma gloire !<br/>',NULL,27910,2);
INSERT INTO stanza VALUES('FR180','2','C''est dans mon esprit qu''Il m''a régénéré,<br/>Mon âme, Il désir transformer.<br/>À Sa ressemblance, Il va mon corps changer,<br/>Pleinement Il sera magnifié.<br/>',NULL,27911,3);
INSERT INTO stanza VALUES('FR180','3','Unis avec Lui dans Sa nature et vie,<br/>Dans la gloire je serai en Lui.<br/>Pour l''éternité, je jouirai de Lui,<br/>Pleinement rendu conforme à Lui.<br/>',NULL,27912,4);
INSERT INTO stanza VALUES('FR181','1','Christ est mon espérance, en moi Il est la vie,<br/>Il mourut à ma place, dès lors je vis par Lui.<br/>Un jour, Seigneur, Tu viendras transfigurer mon corps,<br/>Tu veux le rendre glorieux, ôter sa mort.<br/>',NULL,27913,1);
INSERT INTO stanza VALUES('FR181','chorus','Reviens, reviens, reviens me glorifier,<br/>Mon corps sera semblable au Tien,<br/>Un corps transfiguré !<br/>Reviens, reviens, reviens le racheter,<br/>Toi, glorieuse espérance en moi,<br/>Reviens me glorifier !<br/>',NULL,27914,2);
INSERT INTO stanza VALUES('FR181','2','Christ est mon espérance, Sa vie en moi grandit,<br/>De Dieu la plénitude demeure en mon esprit.<br/>Tous les jours Il dispense Sa vie divine en moi,<br/>J''aurai part à Sa gloire, quand Il viendra !<br/>',NULL,27915,3);
INSERT INTO stanza VALUES('FR181','3','Christ est mon espérance, complète rédemption,<br/>Il remplira de gloire mon corps d''humiliation.<br/>La création désire ce jour avec ardeur<br/>Où seront manifestés les saints vainqueurs.<br/>',NULL,27916,4);
INSERT INTO stanza VALUES('FR181','4','Christ est mon espérance, Il va me glorifier,<br/>À Sa gloire éternelle Dieu nous a appelés.<br/>Devant Lui, face à face, nous serons comme Lui<br/>Et pour toujours, nous serons à Lui unis !<br/>',NULL,27917,5);
INSERT INTO stanza VALUES('FR182','1','Le Seigneur de gloire paraîtra, du ciel Il descendra,<br/>Tous les morts en Christ seront ressuscités.<br/>Le Seigneur de gloire descendra, tous les vivants prendra<br/>Et ensemble nous serons transfigurés !<br/>',NULL,27918,1);
INSERT INTO stanza VALUES('FR182','chorus','Le Seigneur vient dans Sa gloire,<br/>Prenons part à Sa victoire !<br/>Le Seigneur vient dans Sa gloire,<br/>Alléluia, Il nous transfigurera !<br/>',NULL,27919,2);
INSERT INTO stanza VALUES('FR182','2','Le Seigneur de gloire paraîtra, nous attendons ce jour,<br/>Il enlèvera nos larmes, nos douleurs.<br/>Le Seigneur de gloire descendra, Son règne établira,<br/>Il n''y aura plus de mort ni de malheurs.<br/>',NULL,27920,3);
INSERT INTO stanza VALUES('FR182','3','Le Seigneur, l''étoile du matin, bientôt se lèvera.<br/>Veillons pour être enlevés, gagnons le prix !<br/>Le soleil de la justice éclairera l''humanité<br/>Et la terre sera restaurée par Lui.<br/>',NULL,27921,4);
INSERT INTO stanza VALUES('FR182','4','Le Seigneur de gloire paraîtra, soyons tous vigilants !<br/>Ayons nos reins ceints, nos lampes allumées !<br/>Servons-Le fidèlement et n''enterrons pas nos talents !<br/>Remplissons la tache qu''Il nous a confiée !<br/>',NULL,27922,5);
INSERT INTO stanza VALUES('FR183','1','Combien de temps devrai-je encore attendre,<br/>Le cœur brisé, que Tu reviennes enfin ?<br/>À Béthanie, Tu nous étais si proche,<br/>Comment peut-on chanter quand Tu es loin !<br/>Pendant des nuits, je reste seul à veiller,<br/>Indifférent aux joies et aux douleurs.<br/>Tu as pourtant promis de venir bientôt,<br/>Mais je soupire : pourquoi tardes-Tu, Seigneur ?<br/>',NULL,27923,1);
INSERT INTO stanza VALUES('FR183','2','Je suis errant - Ta crèche le suggère.<br/>Rien n''a d''attrait - Ta croix opère en moi.<br/>Mon cœur languit après une vraie patrie,<br/>Espère en Toi, ne désire que Toi.<br/>Comment combler le vide que j''éprouve,<br/>Quand Toi, Seigneur, Tu tardes à revenir ?<br/>Même mon chant a perdu de sa fraicheur,<br/>L''âme brisée, je ne peux plus me réjouir.<br/>',NULL,27924,2);
INSERT INTO stanza VALUES('FR183','3','Tu vis en moi et Ta présence est chère,<br/>Tu me soutiens, éclaires mon sentier.<br/>Mais rien ne peur vraiment me satisfaire,<br/>Je veux Te voir, je veux Te rencontrer !<br/>Malgré Ta paix, je me sens solitaire.<br/>Malgré Ta joie, je soupire en mon cœur.<br/>Dans mon désir de Te voir face à face,<br/>Je ne puis contenir ce cri : reviens Seigneur !<br/>',NULL,27925,3);
INSERT INTO stanza VALUES('FR183','4','Quel exilé n''a jamais voulu rentrer,<br/>Dans Son pays pour saluer les siens ?<br/>Quel amoureux n''a jamais voulu s''unir<br/>À l''être aimé pour fixer son destin ?<br/>Rien ne pourra apaiser ma souffrance,<br/>Ni étancher ma soif de Te revoir.<br/>Si je ne peux contempler Ton visage,<br/>Ma solitude restera toujours ma part.<br/>',NULL,27926,4);
INSERT INTO stanza VALUES('FR183','5','Peux-Tu, Seigneur, oublier Ta promesse,<br/>De revenir pour m''enlever à Toi ?<br/>J''ai attendu et j''attendrai encore,<br/>Je persévère et Tu ne reviens pas !<br/>Oh ! Souviens-Toi de mes années d''errance,<br/>Quand j''espérais entendre enfin Tes pas !<br/>Combien d''années me faudra-t-il attendre,<br/>Ce glorieux jour où Tu te manifesteras ?<br/>',NULL,27927,5);
INSERT INTO stanza VALUES('FR183','6','Combien de saints de siècle en siècle ont vécu,<br/>Sans jamais voir ce jour tant désiré ?<br/>Tu as promis que Tu reviendrais bientôt,<br/>Combien de temps depuis s''est écoulé !<br/>Devrai-je encore attendre davantage ?<br/>Je veux Te voir, reviens donc me rechercher !<br/>Pourquoi les cieux refusent-ils de s''ouvrir ?<br/>Pourquoi les cieux demeurent-ils ainsi scellés ?<br/>',NULL,27928,6);
INSERT INTO stanza VALUES('FR183','7','Sois attentif au cri de Ton épouse,<br/>Prête l''oreille à ses supplications.<br/>J''unis ma voix à celle de Ton peuple,<br/>Reviens bientôt, Seigneur, nous T''implorons !<br/>Quand viendras-Tu nous convier aux noces ?<br/>Quand pourrons-nous partager Ton festin ?<br/>Reviens, Seigneur, établir Ton royaume,<br/>Reviens pour être glorifié dans tous Tes saints !<br/>',NULL,27929,7);
INSERT INTO stanza VALUES('FR184','1','Bientôt mon Roi va revenir, le ciel Il remplira.<br/>Tout l''univers en parlera, sa gloire éclatera.<br/>Seigneur, Ton plan va s''accomplir.<br/>J''entends déjà Tes pas.<br/>Ta silhouette j''aperçois, oui, viens, approche-Toi !<br/>',NULL,27930,1);
INSERT INTO stanza VALUES('FR184','2','Je veux, debout et vigilant, paraitre devant Toi !<br/>Ton imminent retour j''attends, je vais Te voir, mon Roi !<br/>Toi l''espérance de ma vie,<br/>Bientôt apparaitras.<br/>Sur terre, je n''attends que Toi, toi seul me combleras.<br/>',NULL,27931,2);
INSERT INTO stanza VALUES('FR184','3','Sur Christ se portent les regards d''un citoyen des cieux.<br/>Sa bouche annonce hardiment : « Bientot je verrai Dieu ! »<br/>Le jour approche, je le crois,<br/>Où Tu apparaitras,<br/>Car Ta promesse s''accomplit, tu ne tarderas pas !<br/>',NULL,27932,3);
INSERT INTO stanza VALUES('FR184','4','Tes saints préceptes, mon Sauveur, jamais ne passeront.<br/>Ta vie me presse d''accepter des peines pour Ton nom.<br/>Ta gloire apparaitra bientôt,<br/>Satan sera vaincu,<br/>Ton grand dessein va s''accomplir, quel merveilleux salut !<br/>',NULL,27933,4);
INSERT INTO stanza VALUES('FR184','5','Tu es mon Dieu, mon grand Sauveur, mon refuge est en Toi.<br/>Mon défenseur et mon gardien, je place en Toi ma foi.<br/>Berger, Gardien du seul troupeau,<br/>Tu prends bien soin de lui,<br/>Et de Ta main nul ne pourra ravir une brebis.<br/>',NULL,27934,5);
INSERT INTO stanza VALUES('FR184','6','Non, rien ne peut me retenir, de courir après Toi !<br/>L''épreuve même m''aidera, à entrer dans Ta joie.<br/>Mon âme, prends courage et crois :<br/>Le monde passera !<br/>Tu viens, Tu viens sans plus tarder, à Toi m''enlèveras !<br/>',NULL,27935,6);
INSERT INTO stanza VALUES('FR184','7','La liberté va triompher, la vérité régner.<br/>Bientôt le monde entier verra, en nous Christ glorifié.<br/>Rien ne pourra rester caché,<br/>Tout sera dévoilé.<br/>Son ennemi sera vaincu, nos pieds vont l''écraser !<br/>',NULL,27936,7);
INSERT INTO stanza VALUES('FR184','8','Bientôt mon Roi va revenir, le ciel Il remplira.<br/>Tout l''univers en parlera, sa gloire éclatera.<br/>Viens, règne enfin, révèle-Toi ! Ta face montre-nous !<br/>Ton trône ici-bas établi, reviens, reviens mon Roi !<br/>',NULL,27937,8);
INSERT INTO stanza VALUES('FR185','1','Quand reviendra mon cher Seigneur,<br/>Il prendra toutes mes douleurs<br/>Et je Le suivrai de tout cœur.<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Et je Le suivrai de tout cœur. Oh ! Gloire à Dieu !<br/>',NULL,27938,1);
INSERT INTO stanza VALUES('FR185','2','Devant Lui quand je paraitrai,<br/>Toujours avec Lui je serai,<br/>Je chanterai, j''exulterai :<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Je chanterai, j''exulterai : Oh ! Gloire à Dieu !<br/>',NULL,27939,2);
INSERT INTO stanza VALUES('FR185','3','Quand mon Roi je rencontrerai,<br/>De mes souffrances délivré,<br/>Je chanterai, triompherai.<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Je chanterai, triompherai. Oh ! Gloire à Dieu !<br/>',NULL,27940,3);
INSERT INTO stanza VALUES('FR185','4','Ce jour-là je témoignerai :<br/>Sa vie, rien ne peut l''égaler !<br/>Vers Lui je serai enlevé,<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Vers Lui je serai enlevé, Oh ! Gloire à Dieu !<br/>',NULL,27941,4);
INSERT INTO stanza VALUES('FR185','5','Puissions-nous en Lui nous cacher,<br/>Être un et jamais divisés,<br/>Alors Son cœur sera comblé,<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Alors Son cœur sera comblé, Oh ! Gloire à Dieu !<br/>',NULL,27942,5);
INSERT INTO stanza VALUES('FR185','6','Reviens mon Roi, mon cher Seigneur,<br/>Et récompense les vainqueurs,<br/>Nous T''attendons avec ardeur,<br/>Oh ! Gloire à Dieu ! Oh ! Gloire à Dieu !<br/>Oh ! Gloire à Dieu !<br/>Nous T''attendons avec ardeur, Oh ! Gloire à Dieu !<br/>',NULL,27943,6);
INSERT INTO stanza VALUES('FR186','1','Quelle espérance, Jésus reviendra !<br/>Il paraitra et nous enlèvera.<br/>Nous serons tous avec Lui glorifiés,<br/>À Son image serons transformés.<br/>',NULL,27944,1);
INSERT INTO stanza VALUES('FR186','chorus','Christ reviendra, Christ reviendra !<br/>Que c''est glorieux, Il paraitra !<br/>Nous serons enlevés, transfigurés !<br/>Quelle espérance, Jésus reviendra !<br/>',NULL,27945,2);
INSERT INTO stanza VALUES('FR186','2','Quelle espérance, Jésus reviendra !<br/>La création ancienne engloutira.<br/>De l''esclavage Il va nous libérer.<br/>Les fils de Dieu seront manifestés.<br/>',NULL,27946,3);
INSERT INTO stanza VALUES('FR186','3','Quelle espérance, Jésus reviendra !<br/>Nous régnerons avec Lui ici-bas.<br/>Dans Sa présence, nous Le servirons,<br/>De Son salut complet nous jouirons.<br/>',NULL,27947,4);
INSERT INTO stanza VALUES('FR186','4','Quelle espérance, Jésus reviendra !<br/>Priant et veillant, Il nous trouvera.<br/>Courons la course et remportons le prix,<br/>Pour entrer dans le royaume promis.<br/>',NULL,27948,5);
INSERT INTO stanza VALUES('FR187','1','Écoutez, le royaume est proche :<br/>Dix vierges, leurs lampes allumées,<br/>S''en vont rencontrer leur époux,<br/>Cinq d''entrer elles sont insensées.<br/>Les sages ont des vases remplis,<br/>Oui, remplis d''huile abondamment,<br/>Les folles n''ont rien, n''ont rien pris,<br/>N''ayant pas le temps racheté !<br/>',NULL,27949,1);
INSERT INTO stanza VALUES('FR187','2','Seigneur, Ton message est si clair :<br/>Tu reviens pour les vierges sages,<br/>Qui achètent l''huile aujourd''hui,<br/>Qui maintenant renient leur âme.<br/>Ces vierges ont été transformées,<br/>Leur vase est rempli de l''Esprit.<br/>Elles iront donc dans le royaume<br/>Et avec le Roi règneront !<br/>',NULL,27950,2);
INSERT INTO stanza VALUES('FR187','3','Pour bruler nous devons veiller<br/>À garder nos lampes allumées.<br/>En invoquant à tout instant,<br/>Notre esprit va vraiment bruler.<br/>Mais, bien plus, la vie doit grandir,<br/>La réalité se répandre.<br/>Nos vases alors seront remplis,<br/>Nos âmes déborderont d''huile.<br/>',NULL,27951,3);
INSERT INTO stanza VALUES('FR187','4','La corruption est à son comble,<br/>Le Seigneur na va pas tarder,<br/>À tout moment, nous L''attendons,<br/>Il va revenir pour régner.<br/>Ô Maitre, mets en nous le zèle,<br/>Pour racheter tout notre temps,<br/>Laissant le Roi nous enseigner,<br/>Nous posséder, nous préparer.<br/>',NULL,27952,4);
INSERT INTO stanza VALUES('FR187','5','Seigneur, que nous sommes bénis<br/>D''amener Ton règne sur terre,<br/>Et que sur tout, Tu sois le Roi,<br/>Aux hommes, montrant Ta valeur !<br/>Alors nous serons au festin,<br/>Où l''épouse et Toi seront un.<br/>Fais de nous tous des vierges sages,<br/>Qui en Ta présence demeurent.<br/>',NULL,27953,5);
INSERT INTO stanza VALUES('FR188','1','Dans nos lampes, de l''huile nous avons,<br/>Afin d''être toujours brulants !<br/>Vers Toi dans notre esprit, nous nous tournons,<br/>Nous nous tournons, tournons, tout le temps !<br/><br/>Seigneur, amen, alléluia !<br/>Nous demeurons brulants en tout temps !<br/>Seigneur, amen, alléluia !<br/>Nous nous tournons maintenant !<br/>',NULL,27954,1);
INSERT INTO stanza VALUES('FR188','2','Notre vase a besoin d''être rempli<br/>D''une réserve d''huile en plus !<br/>Aujourd''hui, nous nous tournons vers l''esprit<br/>Pour gagner cette huile toujours plus !<br/><br/>Seigneur Jésus, Seigneur Jésus,<br/>Conduis-nous à racheter le temps !<br/>Seigneur Jésus, Seigneur Jésus,<br/>Rends-nous sages maintenant !<br/>',NULL,27955,2);
INSERT INTO stanza VALUES('FR188','3','Nous brulons tous pour Lui dans notre esprit,<br/>Jusqu''à l''heure du grand festin.<br/>Dans la salle de noce Il nous conduit,<br/>Nous brulons tout le long du chemin !<br/><br/>Viens ô Jésus ! Viens ô Jésus !<br/>Viens nous préparer pour ce grand jour !<br/>Viens ô Jésus ! Viens ô Jésus !<br/>Nous attendons Ton retour !<br/>',NULL,27956,3);
INSERT INTO stanza VALUES('FR189','1','Tu viens, Seigneur, bientôt,<br/>Ton jour est là tantôt.<br/>Oh ! que nous aimons Ton retour !<br/>Nous n''avons d''autre vie,<br/>De Seigneur ou d''ami,<br/>Que Toi seul Jésus notre amour !<br/>',NULL,27957,1);
INSERT INTO stanza VALUES('FR189','2','L''heure est près d''arriver,<br/>Tu vas nous appeler.<br/>Dans la nuée Tu descendras.<br/>Oh ! quel moment pour nous,<br/>Quand l''épouse et l''époux<br/>Se rencontreront dans la joie !<br/>',NULL,27958,2);
INSERT INTO stanza VALUES('FR189','3','Le temps n''est plus très long,<br/>Bientôt nous Te verrons !<br/>Viens sans tarder, amen, Seigneur !<br/>Nous désirons Te voir,<br/>Demeurer avec Toi,<br/>Car Tu as gagné notre cœur.<br/>',NULL,27959,3);
INSERT INTO stanza VALUES('FR189','4','Ce temps touche à sa fin .<br/>Toi, notre époux divin,<br/>Tu viens chercher Ta bien-aimée,<br/>Seigneur, nous T''attendons,<br/>Ici, nous languissons,<br/>Que Ton cœur soit aussi comblé !<br/>',NULL,27960,4);
INSERT INTO stanza VALUES('FR190','1','Pour s''unir à l''homme<br/>- Tel est Son dessein - Dieu le fait renaitre,<br/>Comme un vase saint.<br/>Il veut qu''il déborde,<br/>De Sa propre vie,<br/>Pour que l''homme exprime<br/>Sa gloire infinie.<br/>',NULL,27961,1);
INSERT INTO stanza VALUES('FR190','2','À Sa propre image,<br/>Dieu fit l''être humain,<br/>Pour qu''il accomplisse<br/>Son glorieux dessein,<br/>Que l''homme reçoive<br/>L''arbre de la vie,<br/>Pour qu''il s''en nourrisse<br/>Et Dieu glorifie.<br/>',NULL,27962,2);
INSERT INTO stanza VALUES('FR190','3','L''homme est la demeure,<br/>De l''Esprit de vie.<br/>Il devient l''épouse,<br/>Sa contrepartie.<br/>Dieu comme un grand fleuve,<br/>Coule plein d''amour.<br/>Toutes nos ténèbres<br/>Fuient devant Son jour !<br/>',NULL,27963,3);
INSERT INTO stanza VALUES('FR190','4','Quand la vie abonde,<br/>L''homme est transformé<br/>En précieuse pierre,<br/>Pour être édifié.<br/>C''est la ville sainte :<br/>Dieu à l''homme uni !<br/>L''homme et Dieu jubilent,<br/>En pleine harmonie.<br/>',NULL,27964,4);
INSERT INTO stanza VALUES('FR190','5','Dieu est le vrai centre,<br/>Le Roi souverain.<br/>Sa vie magistrale<br/>Rend un tous Ses saints.<br/>L''éclat de Sa gloire,<br/>Brille sur chacun.<br/>Ils sont d''un seul accord,<br/>Par l''Esprit divin.<br/>',NULL,27965,5);
INSERT INTO stanza VALUES('FR190','6','Il est leur eau vive<br/>Et l''Arbre de vie,<br/>Leur soif Il étanche,<br/>Leur faim rassasie.<br/>Il est leur vrai temple,<br/>Ainsi, dans la joie,<br/>Tous, dans Sa présence,<br/>Élèvent leurs voix.<br/>',NULL,27966,6);
INSERT INTO stanza VALUES('FR191','1','Dans la Genèse, il y a un jardin,<br/>Le centre de la création de Dieu.<br/>L''Apocalypse nous montre une ville :<br/>L''achèvement de Son dessein glorieux.<br/>',NULL,27967,1);
INSERT INTO stanza VALUES('FR191','2','Dans le jardin et dans la sainte ville,<br/>Se trouve un fleuve et un arbre de vie.<br/>Christ est cet arbre, notre provision,<br/>L''Esprit est le courant qui vivifie.<br/>',NULL,27968,2);
INSERT INTO stanza VALUES('FR191','3','Dans le jardin et la cité divine,<br/>Nous découvrons trois matériaux précieux.<br/>De l''or, des perles, des pierres précieuses,<br/>Pour édifier l''habitation de Dieu.<br/>',NULL,27969,3);
INSERT INTO stanza VALUES('FR191','4','Dans le jardin, ces matériaux précieux<br/>Sont encore éparpillés sur la terre.<br/>Tandis que dans la ville, ils sont bâtis<br/>Demeure de Dieu dans cet univers.<br/>',NULL,27970,4);
INSERT INTO stanza VALUES('FR191','5','L''homme au commencement fut fait de terre,<br/>Dans le jardin, c''est Dieu qui l''a formé.<br/>Mais l''homme était de la vie éloigné,<br/>Car l''arbre de vie il devait manger.<br/>',NULL,27971,5);
INSERT INTO stanza VALUES('FR191','6','Dans la cité, grandit l''arbre de vie,<br/>À l''intérieur de l''homme collectif,<br/>Révélant que Christ est la vie en lui,<br/>Inépuisable don tout-inclusif.<br/>',NULL,27972,6);
INSERT INTO stanza VALUES('FR191','7','Dieu œuvre en nous pour avoir une ville,<br/>Nous régénère, remplit et transforme<br/>En or pur, perles et pierres précieuses.<br/>L''homme est ainsi à Christ rendu conforme.<br/>',NULL,27973,7);
INSERT INTO stanza VALUES('FR191','8','Dans le jardin se trouvait une épouse,<br/>Elle était la contrepartie d''Adam.<br/>À la fin, la cité devient l''épouse,<br/>Qui, du Seigneur, est le désir ardent.<br/>',NULL,27974,8);
INSERT INTO stanza VALUES('FR191','9','La ville est l''œuvre de Dieu achevées,<br/>Elle est formée de tous Ses rachetés.<br/>Elle est l''habitation du Dieu vivant,<br/>Pour Christ, elle est Sa femme bien-aimée.<br/>',NULL,27975,9);
INSERT INTO stanza VALUES('FR191','10','C''est l''expression divine universelle,<br/>Parfaite, complète et corporative,<br/>La ville exprime Dieu, toute Sa gloire,<br/>Elle est l''épouse, Sa contrepartie.<br/>',NULL,27976,10);
INSERT INTO stanza VALUES('FR192','1','Par Ses meurtrissures,<br/>L''Homme de douleur,<br/>Par amour se livre,<br/>Pour tous les pécheurs.<br/>Par Sa mort Il ôte,<br/>Lave mes péchés.<br/>Jésus est le Sauveur,<br/>Pourquoi résister ?<br/>',NULL,27977,1);
INSERT INTO stanza VALUES('FR193','1','Oh ! dans quelle fosse gisait mon esprit !<br/>Oh ! dans quelle nuit, Christ me surprit !<br/>Quand l''abime de mon âme Il traversa,<br/>Il chassa ma nuit, me restaura.<br/>',NULL,27978,1);
INSERT INTO stanza VALUES('FR193','chorus','Jusqu''à Golgotha, Il est allé pour moi,<br/>Oui, sur la croix, Il me sauva.<br/>Jusqu''à Golgotha, Il est allé pour moi,<br/>Et mourut à la croix.<br/>',NULL,27979,2);
INSERT INTO stanza VALUES('FR193','2','Un pécheur tout tremblant à Ses pieds pleura :<br/>« J''ignorais Ta grâce, ton rachat. »<br/>« Laisse Tes regrets », me dit le Saint-Esprit,<br/>« Jésus a payé : c''est accompli ! »<br/>',NULL,27980,3);
INSERT INTO stanza VALUES('FR193','3','Quel amour extrême le Sauveur montra :<br/>Il quitta Son trône pour la croix,<br/>Et tous mes péchés, Il les porta sur Lui,<br/>Que Son nom soit à jamais béni !<br/>',NULL,27981,4);
INSERT INTO stanza VALUES('FR194','1','Jésus, Fils de Dieu, Sauveur,<br/>Tu pris le poids du pécheur,<br/>Brisant du captif les liens,<br/>Supprimant Ses maux anciens.<br/>',NULL,27982,1);
INSERT INTO stanza VALUES('FR194','2','Les pécheurs T''ont mis à mort,<br/>Sur Toi, Tu pris notre tort,<br/>En Ta chair, Tu fus percé,<br/>Tous nos péchés T''ont blessé.<br/>',NULL,27983,2);
INSERT INTO stanza VALUES('FR194','3','Tu deviens notre Garant,<br/>En nous sauvant par Ton sang.<br/>Nos péchés sont effacés,<br/>Plus rien ne reste payer !<br/>',NULL,27984,3);
INSERT INTO stanza VALUES('FR194','4','Plus rien ne reste à porter,<br/>Pour nous, rien à partager,<br/>Si ce n''est Ton grand pardon,<br/>Ton amour, Ta paix, Ton don !<br/>',NULL,27985,4);
INSERT INTO stanza VALUES('FR194','5','Maintenant pour Toi je vis !<br/>Te contemplant, je guéris !<br/>Quand je suis tourné vers Toi,<br/>Tu ,.éclaires, fais ma joie.<br/>',NULL,27986,5);
INSERT INTO stanza VALUES('FR194','6','Jésus, Fils de Dieu, Sauveur,<br/>Tu pris le poids du pécheur.<br/>Maintenant, tous devant Toi,<br/>Nous T''adorons avec joie !<br/>',NULL,27987,6);
INSERT INTO stanza VALUES('FR195','1','Le Christ s''est uni aux pécheurs,<br/>Il prit part à la vie humaine.<br/>Mis à la croix pour nous pécheurs,<br/>Il nous donna Sa vie glorieuse.<br/>Jésus-Christ vint pour nous,<br/>Jésus mourut pour nous.<br/>Oh ! Oui ! pour nous, pour nous, pour nous,<br/>Christ vint mourir pour nous.<br/>',NULL,27988,1);
INSERT INTO stanza VALUES('FR196','1','Qu''aurais-je à craindre, à redouter ?<br/>Dieu n''a-t-Il pas déjà jugé<br/>Son propre Fils pour moi ?<br/>Dieu pourrait-Il changer d''avis ?<br/>Christ a déjà payé le prix,<br/>En mourant à la croix !<br/>',NULL,27989,1);
INSERT INTO stanza VALUES('FR196','2','Christ accomplit la rédemption,<br/>Il m''accorda le plein pardon,<br/>M''affranchit de la loi.<br/>Je ne crains point l''ire de Dieu,<br/>Le sang me rend juste à Ses yeux.<br/>Christ le versa pour moi.<br/>',NULL,27990,2);
INSERT INTO stanza VALUES('FR196','3','Son précieux sang Il a versé,<br/>Par Lui, j''ai été acquitté,<br/>Mes dettes sont payées.<br/>Dieu ne peut exiger de moi,<br/>La dette immense que paya<br/>Mon Sauveur crucifié.<br/>',NULL,27991,3);
INSERT INTO stanza VALUES('FR196','4','Je suis en paix, libre et radieux,<br/>Car mon Sauveur a comblé Dieu,<br/>Son amour m''a gracié.<br/>J''ai l''assurance du salut.<br/>Dieu ne me condamnera plus,<br/>Christ pour moi fut livré.<br/>',NULL,27992,4);
INSERT INTO stanza VALUES('FR197','1','De Jésus approche-toi, sois purifié,<br/>Sois lavé par le sang de l''Agneau !<br/>Aie confiance en Lui, en Sa fidélité,<br/>Sois lavé par le sang de l''Agneau !<br/>',NULL,27993,1);
INSERT INTO stanza VALUES('FR197','chorus','Sois lavé par le sang !<br/>Par le sang de l''Agneau sans défaut,<br/>Et ta robe sera blanchie dans le sang,<br/>Sois lavé par le sang de l''Agneau !<br/>',NULL,27994,2);
INSERT INTO stanza VALUES('FR197','2','Marche chaque jour en Lui et par la foi,<br/>Sois lavé par le sang de l''Agneau !<br/>Dans le Crucifié, en Lui, repose-toi,<br/>Sois lavé par le sang de l''Agneau !<br/>',NULL,27995,3);
INSERT INTO stanza VALUES('FR197','3','Purifie ta robe, car l''époux revient,<br/>Sois lavé par le sang de l''Agneau !<br/>Pare-toi, car Il vient rechercher les Siens,<br/>Sois lavé par le sang de l''Agneau !<br/>',NULL,27996,4);
INSERT INTO stanza VALUES('FR197','4','Ton habit rejette, car il est souillé,<br/>Sois lavé par le sang de l''Agneau !<br/>Une source coule pour te purifier,<br/>Sois lavé par le sang de l''Agneau !<br/>',NULL,27997,5);
INSERT INTO stanza VALUES('FR198','1','Veux-tu briser du péché le pouvoir ?<br/>La force est en Christ ! Elle est en Christ !<br/>Si dans ton cœur, tu veux Le recevoir,<br/>La force est dans le sang de Christ !<br/>',NULL,27998,1);
INSERT INTO stanza VALUES('FR198','chorus','Je suis fort, fort, oui, plus que vainqueur,<br/>Par le sang de Jésus !<br/>Je suis fort, fort, oui, plus que vainqueur,<br/>Par le sang précieux du Sauveur !<br/>',NULL,27999,2);
INSERT INTO stanza VALUES('FR198','2','Veux-tu braver et la mort et l''enfer ?<br/>La force est en Christ ! Elle est en Christ !<br/>Jésus d''un mot fait tomber tous tes fers,<br/>La force est dans le sang de Christ !<br/>',NULL,28000,3);
INSERT INTO stanza VALUES('FR198','3','Veux-tu marcher toujours pur, triomphant ?<br/>La force est en Christ ! Elle est en Christ !<br/>Pour te garder, Jésus est tout-puissant,<br/>La force est dans le sang de Christ !<br/>',NULL,28001,4);
INSERT INTO stanza VALUES('FR198','4','Veux-tu jouir de Sa paix chaque jour ?<br/>La force est en Christ ! Elle est en Christ !<br/>Et demeurer en Jésus tous les jours ?<br/>La force est dans le sang de Christ !<br/>',NULL,28002,5);
INSERT INTO stanza VALUES('FR199','1','Christ prit ma nature humaine,<br/>devenant semblable à moi.<br/>Il me libéra du vieil homme en<br/>me clouant à la croix.<br/>Il ressuscita, devint l''Esprit,<br/>afin d''entrer en moi,<br/>Pour devenir ma vie.<br/>',NULL,28003,1);
INSERT INTO stanza VALUES('FR199','chorus','Gloire ! Gloire ! Alléluia !<br/>Gloire ! Gloire ! Alléluia !<br/>Gloire ! Gloire ! Alléluia !<br/>Jésus-christ est ma vie !<br/>',NULL,28004,2);
INSERT INTO stanza VALUES('FR199','chorus','Victoire ! Amen ! Alléluia !<br/>Victoire ! Amen ! Alléluia !<br/>Victoire ! Amen ! Alléluia !<br/>Oui, Christ est tout pour moi !<br/>',NULL,28005,3);
INSERT INTO stanza VALUES('FR200','1','Qui peut ôter nos péchés ?<br/>Seul Jésus ! Seul Jésus !<br/>Qui peut être notre vie ?<br/>Seul Jésus ! Seul Jésus ! Seul Jésus !<br/>Seul Jésus peut nous sauver,<br/>Seul Jésus !<br/>',NULL,28006,1);
INSERT INTO stanza VALUES('FR201','1','Christ le Sauveur, tu as besoin de Lui !<br/>Dieu incarné, Il est un homme aussi.<br/>Par les épreuves et souffrances Il passa,<br/>Il mourut, tes péchés ôta,<br/>Il te faut Jésus !<br/>',NULL,28007,1);
INSERT INTO stanza VALUES('FR201','chorus','Oui de Jésus ! Oui de Jésus !<br/>Tu as besoin de Jésus !<br/>Pour ta rédemption : Jésus !<br/>Et pour ton salut : Jésus !<br/>Pour avoir la vie de Dieu,<br/>Il te faut Jésus !<br/>',NULL,28008,2);
INSERT INTO stanza VALUES('FR201','2','Levé des morts, aux cieux Il est monté,<br/>La vie de Dieu t''est pleinement donnée.<br/>Tu Le reçois, lorsque tu crois en Lui,<br/>Alors, tu reçois tout de Lui.<br/>Il te faut Jésus !<br/>',NULL,28009,3);
INSERT INTO stanza VALUES('FR201','3','Ton cœur par Sa lumière est éclairé,<br/>Tes péchés, Sa puissance a pardonnés,<br/>Son sang peut tes souillures purifier,<br/>La vie de Dieu Il peut donner.<br/>Il te faut Jésus !<br/>',NULL,28010,4);
INSERT INTO stanza VALUES('FR201','4','Tu ressens dans ta vie un grand néant,<br/>Qui avec le temps, devient bien plus grand,<br/>Qui, ce vide, Jésus peut le combler,<br/>Dissoudre cette vanité.<br/>Il te faut Jésus !<br/>',NULL,28011,5);
INSERT INTO stanza VALUES('FR201','chorus','Oui de Jésus ! Oui de Jésus !<br/>Tu as besoin de Jésus !<br/>Pour quitter la vanité,<br/>Toucher la réalité,<br/>À ta vie, un sens donner.<br/>Il te faut Jésus !<br/>',NULL,28012,6);
INSERT INTO stanza VALUES('FR201','5','Le monde entier, n''est que difficultés,<br/>Tu es troublé et rien ne peut t''aider.<br/>Tout est si vide, à quoi peux-tu te fier ?<br/>Tout ceci révèle et témoigne :<br/>Il te faut Jésus !<br/>',NULL,28013,7);
INSERT INTO stanza VALUES('FR202','1','J''entends Ta voix, Seigneur,<br/>Je viens, Tu me reçois.<br/>Ton sang précieux me purifie,<br/>Tu le versas pour moi.<br/>',NULL,28014,1);
INSERT INTO stanza VALUES('FR202','chorus','Je veux, cher Seigneur,<br/>Te donner mon cœur.<br/>Purifie-moi, lave-moi,<br/>Tu es mon Rédempteur.<br/>',NULL,28015,2);
INSERT INTO stanza VALUES('FR202','2','J''étais impur et vil,<br/>Gisant dans le malin.<br/>Mais Tu as lavé mon péché,<br/>Ta droite me soutient.<br/>',NULL,28016,3);
INSERT INTO stanza VALUES('FR202','3','Seigneur, tu finiras<br/>Ton œuvre en moi bénie.<br/>Ta grâce se dispense en moi<br/>Et me transmet Ta vie.<br/>',NULL,28017,4);
INSERT INTO stanza VALUES('FR202','4','Tu ne dédaignes pas,<br/>Un cœur pur et brisé.<br/>Quand il Te supplie par la foi,<br/>Tu peux lui pardonner.<br/>',NULL,28018,5);
INSERT INTO stanza VALUES('FR202','5','Ta grace j''ai recu,<br/>Ton sang m''a racheté.<br/>Tu t''es donné pour moi, Seigneur,<br/>Et Tu m''as justifié.<br/>',NULL,28019,6);
INSERT INTO stanza VALUES('FR203','1','J''ai trop longtemps, Seigneur, erré,<br/>Aujourd''hui, je viens.<br/>J''ai trop trainé dans le péché,<br/>À Toi je reviens.<br/>',NULL,28020,1);
INSERT INTO stanza VALUES('FR203','chorus','Je reviens ! Je reviens !<br/>Je T''ouvre mon cœur.<br/>Ouvre-moi Tes bras d''amour,<br/>Je reviens, Seigneur !<br/>',NULL,28021,2);
INSERT INTO stanza VALUES('FR203','2','J''ai gaspillé beaucoup d''années,<br/>Aujourd''hui, je viens.<br/>En pleurs à cause du péché,<br/>À Toi je reviens.<br/>',NULL,28022,3);
INSERT INTO stanza VALUES('FR203','3','Lassé d''errer loin de Tes voies,<br/>Aujourd''hui, je viens.<br/>En Ta parole, en Toi, je crois,<br/>À Toi je reviens.<br/>',NULL,28023,4);
INSERT INTO stanza VALUES('FR203','4','L''âme éprouvée, le cœur meurtri,<br/>Aujourd''hui, je viens.<br/>Restaure-moi, car j''ai tiédi,<br/>À Toi je reviens.<br/>',NULL,28024,5);
INSERT INTO stanza VALUES('FR203','5','Mon seul espoir, ma seule joie,<br/>Aujourd''hui, je viens.<br/>C''est que Jésus mourut pour moi,<br/>À Toi je reviens.<br/>',NULL,28025,6);
INSERT INTO stanza VALUES('FR203','6','Ton sang, Seigneur, pour moi coula,<br/>Aujourd''hui, je viens.<br/>Plus blanc que neige lave-moi,<br/>À Toi je reviens.<br/>',NULL,28026,7);
INSERT INTO stanza VALUES('FR204','1','Garde-moi près de Ta croix,<br/>Où Ton sang fut versé,<br/>Pour me sauver, me guérir,<br/>Pour ôter mes péchés.<br/>',NULL,28027,1);
INSERT INTO stanza VALUES('FR204','chorus','À la croix, à la croix,<br/>Sois ma gloire à jamais.<br/>Là, mon âme rachetée<br/>Trouve un repos parfait.<br/>',NULL,28028,2);
INSERT INTO stanza VALUES('FR204','2','Pauvre et tremblant, je reçus,<br/>À la croix, grâce.<br/>Là, l''étoile du matin,<br/>Brilla sur ma face.<br/>',NULL,28029,3);
INSERT INTO stanza VALUES('FR204','3','Que la scène de la croix,<br/>Dans mon cœur demeure.<br/>À son ombre, je voudrais<br/>Marcher d''heure en heure.<br/>',NULL,28030,4);
INSERT INTO stanza VALUES('FR204','4','À la croix, je veille et prie,<br/>Son retour j''espère.<br/>De mes yeux, je veux Le voir.<br/>Telle est ma prière.<br/>',NULL,28031,5);
INSERT INTO stanza VALUES('FR205','1','Jésus mourut à la croix pour moi,<br/>Quand je Le vis, Il me purifia,<br/>Son sang précieux mon péché lava,<br/>Gloire à mon Sauveur !<br/>',NULL,28032,1);
INSERT INTO stanza VALUES('FR205','chorus','Gloire à mon Sauveur !<br/>Gloire à mon Sauveur !<br/>Son sang précieux mon péché lava,<br/>Gloire à mon Sauveur !<br/>',NULL,28033,2);
INSERT INTO stanza VALUES('FR205','2','Je suis sauvé, je suis plein de joie,<br/>Car mon Sauveur est entré en moi.<br/>C''est à la croix qu''Il m''ouvrit Ses bras,<br/>Gloire à mon Sauveur !<br/>',NULL,28034,3);
INSERT INTO stanza VALUES('FR205','3','Source abondante qui m''a sauvé,<br/>Elle est ouverte pour mes péchés.<br/>À tout moment, je viens y puiser,<br/>Gloire à mon Sauveur !<br/>',NULL,28035,4);
INSERT INTO stanza VALUES('FR205','4','Viens à la fontaine riche et douce,<br/>Jette ton âme aux pieds du Sauveur,<br/>Plonge et dès lors tu seras complet.<br/>Gloire à mon Sauveur !<br/>',NULL,28036,5);
INSERT INTO stanza VALUES('FR206','1','Le bon Berger si tendre<br/>Me chercha, me saisit,<br/>Me prit sur Ses épaules,<br/>M''amena aux brebis.<br/>Aux cieux, les anges crient de joie,<br/>Lorsqu''un pécheur en Jésus croit!<br/>',NULL,28037,1);
INSERT INTO stanza VALUES('FR206','chorus','Son amour me cherche<br/>Et Son sang me lave.<br/>Au troupeau Sa grâce m''a conduit,<br/>Au troupeau Sa grâce m''a conduit.<br/>',NULL,28038,2);
INSERT INTO stanza VALUES('FR206','2','Il soigne mes blessures,<br/>Versant l''huile et le vin.<br/>Paisible, Il me murmure :<br/>« N''aie crainte, tu es Mien ! »<br/>Enfin, Sa douce voix j''entends,<br/>Qui réjouit mon cœur souffrant.<br/>',NULL,28039,3);
INSERT INTO stanza VALUES('FR206','3','Il montre Ses blessures,<br/>Le sang qu''Il a versé.<br/>Ému, je vois Sa tête,<br/>D''épines couronnée.<br/>Par quoi, en moi, fut-Il saisi,<br/>Pour endurer telle agonie ?<br/>',NULL,28040,4);
INSERT INTO stanza VALUES('FR206','4','Assis dans Sa présence,<br/>J''admire Sa beauté.<br/>De Lui je m''émerveille,<br/>Retrace Ses bontés.<br/>Aurais-je dans l''éternité,<br/>Assez de temps pour Le louer ?<br/>',NULL,28041,5);
INSERT INTO stanza VALUES('FR206','5','Dès lors, je me repose,<br/>Sa paix réside en moi.<br/>Bientôt Il va paraître,<br/>Mon Bien-aimé, mon Roi !<br/>Il reviendra pour enlever<br/>Sa chère épouse préparée.<br/>',NULL,28042,6);
INSERT INTO stanza VALUES('FR207','1','Nous mangeons Christ, le pain de vie,<br/>Nous buvons Christ, l''eau qui jaillit.<br/>Oui, celui qui boira n''aura<br/>Plus jamais, jamais, jamais soif !<br/><br/>Quoi ! Jamais, jamais soif ?<br/>Non ! Jamais, jamais soif !<br/>Quoi ! Jamais, jamais soif ?<br/>Non ! Jamais, jamais soif !<br/>Oui, celui qui boira n''aura<br/>Plus jamais, jamais, jamais soif !<br/>',NULL,28043,1);
INSERT INTO stanza VALUES('FR208','1','Mystère glorieux ! Le Sauveur<br/>À moi s''unit !<br/>Oh ! qu''il est merveilleux le salut<br/>De Dieu en Jésus-Christ !<br/>Alléluia ! Alléluia !<br/>Quel fait glorieux !<br/>Rien, rien ne pourra sur cette terre,<br/>De Lui me séparer !<br/>',NULL,28044,1);
INSERT INTO stanza VALUES('FR209','1','Assis tout seul, mendiant sur la grand-route,<br/>L''homme est aveugle, à ses yeux rien ne luit.<br/>Dans ses haillons, il grelotte dans l''ombre,<br/>Puis, Jésus vient chasser sa sombre nuit !<br/>',NULL,28045,1);
INSERT INTO stanza VALUES('FR209','chorus','Quand Jésus vient, le diable perd ses forces,<br/>Quand Jésus vient, mon être est consolé.<br/>Il prend ma nuit, remplit mon cœur de gloire,<br/>Tout change en moi, quand Il vient s''y loger.<br/>',NULL,28046,2);
INSERT INTO stanza VALUES('FR209','2','Loin de chez lui, au milieu des sépulcres,<br/>Il est errant, guidé par ses démons.<br/>Il se détruit : le diable le possède,<br/>Puis Jésus vient abattre sa prison !<br/>',NULL,28047,3);
INSERT INTO stanza VALUES('FR209','3','« Impur, impur ! » Crie le lépreux sans cesse,<br/>Les pharisiens ne peuvent rien pour lui.<br/>La fièvre ronge, agresse sa victime,<br/>Puis Jésus vient chasser la maladie !<br/>',NULL,28048,4);
INSERT INTO stanza VALUES('FR209','4','Leur cœur pleurait, lorsqu''ils l''ensevelirent,<br/>C''était la mort qui l''avait emmené,<br/>Profonde nuit où coulent tant de larmes,<br/>Mais Jésus vient pour le ressusciter !<br/>',NULL,28049,5);
INSERT INTO stanza VALUES('FR209','5','L''homme a compris que seul Jésus le sauve,<br/>De ses passions, ses soifs et ses péchés.<br/>Son cœur brisé le laisse seul et triste,<br/>Puis Jésus vient, Lui-même, l''habiter !<br/>',NULL,28050,6);
INSERT INTO stanza VALUES('FR210','1','Quel profit donne ton labeur ?<br/>Pour l''homme aucune nouveauté !<br/>Ne regrette pas le passé,<br/>Tout est vanité !<br/>',NULL,28051,1);
INSERT INTO stanza VALUES('FR210','chorus','Vanité ! Vanité !<br/>Vanité ! Vanité !<br/>Poursuite du vent,<br/>Tout est vanité !<br/>',NULL,28052,2);
INSERT INTO stanza VALUES('FR210','2','La vie est pleine de chagrins,<br/>Les sages ne peuvent t''aider !<br/>La science ne peut consoler !<br/>Tout est vanité !<br/>',NULL,28053,3);
INSERT INTO stanza VALUES('FR210','3','Malgré nos richesses, nos joies,<br/>Malgré nos fortes amitiés,<br/>En nous demeurent les soucis !<br/>Tout est vanité !<br/>',NULL,28054,4);
INSERT INTO stanza VALUES('FR210','4','Chaque jour, tu vis pour ton travail,<br/>Tu amasses tout dans ton grenier.<br/>Mais quand tu meurs, tout est perdu,<br/>Tout est vanité !<br/>',NULL,28055,5);
INSERT INTO stanza VALUES('FR210','5','Jeunes gens, pensez à votre Dieu,<br/>Craignez-Le sur votre chemin.<br/>En Lui seul vous serez comblés :<br/>En Lui, tout est gain !<br/>',NULL,28056,6);
INSERT INTO stanza VALUES('FR210','chorus','Hors de Christ, tout est vain !<br/>Mais en Christ, tout est gain !<br/>Le monde n''est rien,<br/>Seul Christ est un gain !<br/>',NULL,28057,7);
INSERT INTO stanza VALUES('FR211','1','J''ai tant cherché une source,<br/>Qui toujours me satisferait.<br/>Mais le monde et sa fontaine,<br/>À chaque instant me décevaient.<br/>Mais un jour, je Le trouvai !<br/>Je fus désaltéré.<br/>Je découvris en moi la source,<br/>Qui toujours jaillit,<br/>Que je L''aime !<br/>',NULL,28058,1);
INSERT INTO stanza VALUES('FR211','chorus','Jésus est ma source maintenant,<br/>Toujours Il me rafraîchit.<br/>En Lui, je suis enfin comblé,<br/>Son Esprit me vivifie.<br/>',NULL,28059,2);
INSERT INTO stanza VALUES('FR211','2','J''ai goûté à cette source<br/>Et l''église je découvris.<br/>Je vis l''unité précieuse,<br/>Que Dieu a toujours béni.<br/>Oui, un jour Il me trouva,<br/>L''église me montra,<br/>Avec les saints, son nom j''invoque.<br/>Jésus est ma joie !<br/>Que je L''aime !<br/>',NULL,28060,3);
INSERT INTO stanza VALUES('FR211','3','Vagabond cesse tes efforts,<br/>Car ils n''ont aucune valeur.<br/>Crois à Jésus, ouvre ton cœur,<br/>Invoquant le nom du Seigneur.<br/>Et puis tu Le trouveras,<br/>Quand tu L''invoqueras,<br/>Dans ton esprit, à toi Il se joindra,<br/>Il sera ta joie !<br/>Des regrets ? Non !<br/>',NULL,28061,4);
INSERT INTO stanza VALUES('FR212','1','Venez au festin, car tout est prêt !<br/>Venez ! La table est préparée !<br/>Les affamés, les assoiffés,<br/>Oui, venez vous rassasier !<br/>',NULL,28062,1);
INSERT INTO stanza VALUES('FR212','chorus','Dieu invite au festin,<br/>Viens ! Prends ! Si tu le veux !<br/>Au plein salut de Dieu, goûte !<br/>Viens ! Prends ! Si tu le veux !<br/>',NULL,28063,2);
INSERT INTO stanza VALUES('FR212','2','Venez au festin, car tout est prêt !<br/>Venez ! La porte est grande ouverte.<br/>Voici, ta place est réservée,<br/>Aux cotés de notre Maître.<br/>',NULL,28064,3);
INSERT INTO stanza VALUES('FR212','3','Viens donc au festin, car tout est prêt !<br/>Viens ! Alors qu''il est encore temps.<br/>Viens maintenant ! Le Roi t''attend.<br/>Demain sera bien trop tard.<br/>',NULL,28065,4);
INSERT INTO stanza VALUES('FR212','4','Viens donc au festin, car tout est prêt !<br/>Laisse les soucis de ce monde,<br/>Viens ! De ton Dieu, réjouis-toi !<br/>la vie éternelle bois !<br/>',NULL,28066,5);
INSERT INTO stanza VALUES('FR213','1','Tu changeas mon deuil en une danse, Seigneur,<br/>Mes larmes Tu essuyas.<br/>Tu changeas mon deuil en une danse, Seigneur,<br/>Mon cœur de joie Tu comblas.<br/>Je ne serai plus muet, Tu m''as libéré,<br/>C''est la victoire !<br/>Seigneur, mon Dieu,<br/>À Toi la gloire et l''honneur à jamais !<br/>',NULL,28067,1);
INSERT INTO stanza VALUES('FR214','1','Oh ! quel miracle ! Oh ! quel mystère !<br/>Que l''homme et Dieu soient mélangés !<br/>Dieu devint homme pour qu''il soit Dieu,<br/>Quelle insondable économie !<br/>Le désir ardent de Son cœur,<br/>Son but divin, sera atteint.<br/>Le désir ardent de Son cœur,<br/>Son but divin, sera atteint.<br/>',NULL,28068,1);
INSERT INTO stanza VALUES('FR214','2','Un Homme-Dieu, vêtu de chair,<br/>Son grand plaisir : que je sois Dieu,<br/>Selon Sa nature et Sa vie,<br/>Mais à Lui seul, la Déité.<br/>Ses attributs sont mes vertus,<br/>Sa gloire est exprimée en moi.<br/>Ses attributs sont mes vertus,<br/>Sa gloire est exprimée en moi.<br/>',NULL,28069,2);
INSERT INTO stanza VALUES('FR214','3','Je ne vis plus seul, que par moi,<br/>Car Dieu vit au-dedans de moi.<br/>Avec les saints bâtis en Dieu,<br/>Sa maison, nous tous deviendrons.<br/>Son Corps sur terre nous serons :<br/>Son expression corporative.<br/>Son Corps sur terre nous serons :<br/>Son expression corporative.<br/>',NULL,28070,3);
INSERT INTO stanza VALUES('FR214','4','Jérusalem, le but final,<br/>Des visions, la totalité.<br/>Dieu complet et l''homme crée :<br/>Couple amoureux éternell''ment.<br/>L''homme et Dieu sont co-inhérents :<br/>Une demeure mutuelle.<br/>Dieu, dans Sa gloire, est exprimé<br/>En splendeur dans l''humanité !<br/>',NULL,28071,4);
INSERT INTO stanza VALUES('FR215','1','Dieu dans l''éternité passée<br/>Établit Son économie.<br/>Par elle, Il désire<br/>Que l''homme et Dieu soient un :<br/>L''homme ayant Sa vie, Sa nature,<br/>Mais pas Sa Déité.<br/>Ainsi Dieu sera agrandi, Son expression amplifiée,<br/>Pour que Ses divins, oui tous Ses divins<br/>Attributs soient exprimés dans les vertus humaines.<br/>',NULL,28072,1);
INSERT INTO stanza VALUES('NS481','1','We have not one regret for taking this way,<br/>Not a single regret, journeying this day;<br/>Rough and winding terrain, rocks and thorns can’t dissuade,<br/>Narrow gate, narrow way, the cross’s wounds pervade.<br/>',NULL,28616,1);
INSERT INTO stanza VALUES('NS481','2','Without any regret, our all we consecrate;<br/>Never any regret, our first love we waste.<br/>Though constricted the gate, on this way, Lord, You lead;<br/>Rough and narrow the way, companions compass me.<br/>',NULL,28617,2);
INSERT INTO stanza VALUES('NS481','chorus','Lord, once more I’d give myself unto Thee;<br/>Be the grace and willingness in me,<br/>Shine forth light and reality<br/>And on Zion’s highways lead me.<br/>',NULL,28618,3);
INSERT INTO stanza VALUES('NS481','3','Still upright now we stand, no scent of smoke have we;<br/>Resolutely we stand, face set steadfastly.<br/>Giving up all the world, run to joy set before,<br/>Each step fills us with hope and glory more and more.<br/>',NULL,28619,4);
INSERT INTO stanza VALUES('NS481','4','We stand boldly today, with pure heart testify,<br/>We stand boldly today, spirits are upright:<br/>I love Him, no regret: His life for me He gave;<br/>Faith grows more steadfast yet:<br/>He’s ne’er my trust betrayed.<br/>',NULL,28620,5);
INSERT INTO stanza VALUES('NS481','chorus','Lord, once more I’d give myself unto Thee;<br/>Be the grace and willingness in me,<br/>Shine forth light and reality<br/>And on Zion’s highways lead me.<br/>',NULL,28621,6);
INSERT INTO stanza VALUES('NS482','1','And let them make a sanctuary for Me,<br/>That I may dwell in their midst,<br/>Our prayer is “Lord, we give ourselves to Thee,<br/>We’ll be the builders for Your economy.”<br/>',NULL,28622,1);
INSERT INTO stanza VALUES('NS482','chorus','Under a clear sky,<br/>On the mountain,<br/>Beholding the glory of the<br/>Vision of His building,<br/>That He may have His dwelling place,<br/>That He may have His dwelling place.<br/>',NULL,28623,2);
INSERT INTO stanza VALUES('NS482','2','God needs a group of us to turn the age,<br/>To fellowship and consecrate,<br/>To be in oneness — Yes! This is the way,<br/>No pride or boasting, giving Him first place.<br/>',NULL,28624,3);
INSERT INTO stanza VALUES('NS482','3','Our testimony in the church today,<br/>Is the expression of God through man,<br/>Let’s be the pillars for His dwelling place,<br/>But don’t be passive — trust in His way.<br/>',NULL,28625,4);
INSERT INTO stanza VALUES('NS483','1','My love is like a dove,<br/>In the clefts of the rock,<br/>In the covert of the precipice,<br/>That’s where My love is safe.<br/><br/>At this secret place we meet,<br/>Here your voice, my love, is sweet;<br/>Your countenance is lovely,<br/>And here you’re pleasing to Me.<br/>',NULL,28626,1);
INSERT INTO stanza VALUES('NS483','chorus','Let Me hear your voice;<br/>See your countenance;<br/>For your voice is so sweet,<br/>And you’re lovely.<br/><br/>Let Me hear your voice,<br/>See your countenance;<br/>For your voice is so sweet,<br/>And you’re lovely to me.<br/>',NULL,28627,2);
INSERT INTO stanza VALUES('NS483','2','My love is like a dove,<br/>In the clefts of the rock,<br/>In the covert of the precipice,<br/>That’s where you’re lovely.<br/><br/>At this secret place we meet,<br/>Here your voice, my love, is sweet;<br/>Your countenance is lovely,<br/>And you’re lovely to Me.<br/>',NULL,28628,3);
INSERT INTO stanza VALUES('NS484','chorus','For in Him dwells<br/>All the fullness<br/>Of the Godhead<br/>Bodily,<br/>',NULL,28629,1);
INSERT INTO stanza VALUES('NS484','chorus','For of His fullness<br/>We have all received,<br/>Grace upon grace,<br/>Grace upon grace.<br/>',NULL,28630,2);
INSERT INTO stanza VALUES('NS485','chorus','Put on therefore, as God’s chosen ones,<br/>Holy and beloved,<br/>Inward parts of compassion,<br/>Kindness, lowliness,<br/>Meekness, long-suffering;<br/>',NULL,28631,1);
INSERT INTO stanza VALUES('NS485','chorus','Bearing one another and forgiving one another,<br/>If anyone should have a complaint against anyone;<br/>Even as the Lord forgave you,<br/>So also should you forgive.<br/>',NULL,28632,2);
INSERT INTO stanza VALUES('NS486','1','The New Jerusalem, the kingdom with God’s throne,<br/>Is Christ, the ruling Head of God’s house, the church, God’s home;<br/>The life within the church is the life of God Himself,<br/>The life that rules and reigns, and saves from sin and self.<br/>',NULL,28633,1);
INSERT INTO stanza VALUES('NS486','chorus','New Jerusalem! The city and the bride!<br/>Builded up, beautified, and wholly sanctified!<br/>',NULL,28634,2);
INSERT INTO stanza VALUES('NS486','2','The New Jerusalem is in reality<br/>The church with Christ as Head in God’s economy;<br/>The content of the church must be the kingdom life,<br/>Expressed through all the saints experiencing Christ.<br/>',NULL,28635,3);
INSERT INTO stanza VALUES('NS486','3','The New Jerusalem is builded in the Lord,<br/>A company in Christ established in the Word;<br/>As fellow citizens, God’s kingdom manifest,<br/>In spirit live and walk, and enter Sabbath rest.<br/>',NULL,28636,4);
INSERT INTO stanza VALUES('NS486','4','The New Jerusalem, the bride who is prepared,<br/>Is beautified by Christ, to be His wife, matured;<br/>In nature and in life she must in stature grow<br/>And in the Body live, the Body-life to know.<br/>',NULL,28637,5);
INSERT INTO stanza VALUES('NS486','5','The New Jerusalem, eternal, builded bride,<br/>From self she is delivered from independent pride;<br/>Her righteousness is Christ yet in her daily life<br/>She manifested God, and lived and worked in Christ.<br/>',NULL,28638,6);
INSERT INTO stanza VALUES('NS486','6','The New Jerusalem, the city and the bride,<br/>Remains in God forever, forever to abide;<br/>A city that is holy, in God one entity,<br/>And shining forth with Christ unto eternity.<br/>',NULL,28639,7);
INSERT INTO stanza VALUES('NS487','chorus','The inner essence of the Bible<br/>Is the divine breath,<br/>Spiritual milk, the breath of life,<br/>Spirit and life, and God Himself.<br/>When we pray-read the Word<br/>We touch its essence,<br/>And receive the Word of God<br/>As our food, drink, and breath.<br/>',NULL,28640,1);
INSERT INTO stanza VALUES('NS488','1','Jesus, precious Jesus,<br/>How my heart longs for You.<br/>I have been drawn by Your love,<br/>Attracted by Your sweetness, too.<br/>',NULL,28641,1);
INSERT INTO stanza VALUES('NS488','chorus','Lord, I love You.<br/>You’re the only One I want.<br/>Now I make my choice, Lord Jesus,<br/>To just, just love You;<br/>To just love You.<br/>',NULL,28642,2);
INSERT INTO stanza VALUES('NS488','2','O Lord, my dearest Lord,<br/>What else can I desire?<br/>All this earth’s beauties fade away;<br/>To gain Yourself I aspire.<br/>',NULL,28643,3);
INSERT INTO stanza VALUES('NS488','3','O Lord, the time is short;<br/>My all I give to You—<br/>My life, my love, and all I have,<br/>Because I love You, Lord, I do.<br/>',NULL,28644,4);
INSERT INTO stanza VALUES('NS489','chorus','God will sovereignly<br/>Use persons, things and events to empty us<br/>Of everything that has filled us<br/>And to take away every preoccupation<br/>',NULL,28645,1);
INSERT INTO stanza VALUES('NS489','chorus','So that we may have<br/>An increased capacity<br/>To be filled with God,<br/>To be filled with God.<br/>',NULL,28646,2);
INSERT INTO stanza VALUES('NS489','chorus','So that we may have<br/>An increased capacity<br/>To be filled with God,<br/>To be filled with God.<br/>',NULL,28647,3);
INSERT INTO stanza VALUES('NS490','chorus','Put away the foreign gods that are among you,<br/>And purify yourselves, and change your garments.<br/>And let us rise up and let us go up,<br/>Up to Bethel and make an altar<br/>To the God who has been with me wherever I have gone,<br/>To the God who has been with me wherever I have gone,<br/>To the God who has been with me wherever I have gone.<br/>',NULL,28648,1);
INSERT INTO stanza VALUES('NS491','chorus','Jehovah bless you and keep you;<br/>Jehovah make His face shine upon you<br/>And be gracious to you;<br/>Jehovah lift up His countenance upon you<br/>And give you peace.<br/>',NULL,28649,1);
INSERT INTO stanza VALUES('NS491','end-note','(Repeat verse)<br/>',NULL,28650,2);
INSERT INTO stanza VALUES('NS491','chorus','God the Father’s keeping;<br/>God the Son is shining;<br/>God the Spirit’s countenance<br/>Cheering, uplifting you;<br/>What a Triune blessing;<br/>God Himself dispensing,<br/>For your rich enjoyment<br/>All your days.<br/>',NULL,28651,3);
INSERT INTO stanza VALUES('NS492','1','Lord, I give my heart to You,<br/>Surrender myself unto Thee;<br/>Love pours from the depths of my being;<br/>My King, my Husband, my Lord.<br/>',NULL,28652,1);
INSERT INTO stanza VALUES('NS492','chorus','Your soft voice, Your lovingkindness<br/>Draws me closer to You.<br/>Your love constrains me; caught in Your beauty.<br/>Lord, there’s none more worthy than You.<br/>',NULL,28653,2);
INSERT INTO stanza VALUES('NS492','2','Together, one united,<br/>The Bridegroom and His bride;<br/>Lord, I want to be Your companion<br/>The way that You’ve become mine.<br/>',NULL,28654,3);
INSERT INTO stanza VALUES('NS493','1','To live a life<br/>In the Holy of Holies<br/>We must become a captive of Christ.<br/>Many times, reality is that<br/>Christ is captive to us,<br/>This becomes our own fleshly<br/>Victory.<br/>',NULL,28655,1);
INSERT INTO stanza VALUES('NS493','2','Conquer me,<br/>Subdue me,<br/>That I’d no longer be Your enemy.<br/>Defeat me at any cost<br/>That my own will would be lost.<br/>Your desires make my own.<br/>Never let me win.<br/>',NULL,28656,2);
INSERT INTO stanza VALUES('NS493','3','I’m willing,<br/>Defeat me.<br/>Put the world and sins beneath my feet.<br/>Within me is rebellion.<br/>Defeat it, conquer and subdue it.<br/>Carry me away as Your captive.<br/>',NULL,28657,3);
INSERT INTO stanza VALUES('NS493','4','Today <br/>There’s a need<br/>For us to become captives. <br/>We will see <br/>The affect on those around us.<br/>So become a little captive,<br/>A living sacrifice, <br/>In the triumph of Christ.<br/>',NULL,28658,4);
INSERT INTO stanza VALUES('NS493','5','But thanks be to God<br/>Who always leads us<br/>In the triumph<br/>In the Christ.<br/>',NULL,28659,5);
INSERT INTO stanza VALUES('NS494','1','Lord, by Your mercy, I would take<br/>This opportunity<br/>To let You live Yourself in me;<br/>And let You, Lord, gain me.<br/>',NULL,28660,1);
INSERT INTO stanza VALUES('NS494','chorus','Lord, save me from the past,<br/>And save me from the future;<br/>Yesterday is over,<br/>Tomorrow may not be;<br/>I only have this day;<br/>I only have this moment.<br/>',NULL,28661,2);
INSERT INTO stanza VALUES('NS494','2','And I would hope that You would take<br/>This opportunity<br/>To go as far as possible,<br/>As possible in me.<br/>',NULL,28662,3);
INSERT INTO stanza VALUES('NS494','3','’Though many barriers hidden be,<br/>You know, Lord, deep within—<br/>Lord, I want nothing else but You,<br/>Lord, I want no one else but You.<br/>',NULL,28663,4);
INSERT INTO stanza VALUES('NS494','4','So only this moment have I,<br/>This opportunity;<br/>This precious time I grant, dear Lord,<br/>Solely unto You.<br/>',NULL,28664,5);
INSERT INTO stanza VALUES('NS495','1','God has chosen you and me out of the world<br/>For His plan, for man to live expressing Him.<br/>Use us! Infuse us! Shine as the light from within.<br/>Saturate us; be manifested through our entire being.<br/>',NULL,28665,1);
INSERT INTO stanza VALUES('NS495','chorus','Pay the price and come, be filled with life!<br/>Not just filled!<br/>Life must multiply!<br/>Bury not your talent in the ground!<br/>Bear much fruit!<br/>Increase all around!<br/>Life, from God to me;<br/>Life, through me for you.<br/>With this balance, God will surely move.<br/>',NULL,28666,2);
INSERT INTO stanza VALUES('NS495','2','Many have no real joy ’cause they are barren.<br/>That’s the subtle enemy to us today.<br/>Go forth! Pray, “Oh Lord! In desperation we act!<br/>Oh, Lord grow more! Bring many sons to You!” we pray, more and more!<br/>',NULL,28667,3);
INSERT INTO stanza VALUES('NS495','3','Duplicate Your heart in me to care for others.<br/>As I’m nourished, I can nourish others too.<br/>Jesus! You need us to bear the fruit for the vine!<br/>How we need You! Lord, grant the growth in life that they might remain!<br/>',NULL,28668,4);
INSERT INTO stanza VALUES('NS495','4','God in man, and man in God, a mutual mingling.<br/>Grafted into Him, the vine, the rich supply.<br/>Build us! Perfect us! A transformation so sweet!<br/>Oh how glorious! The New Jerusalem, the bride, we will be!<br/>',NULL,28669,5);
INSERT INTO stanza VALUES('NS496','chorus','Grant me by the riches of Your glory to be strengthened<br/>With power through Your Spirit into my inner man,<br/>That Christ may make His home in all of my heart through faith.<br/>',NULL,28670,1);
INSERT INTO stanza VALUES('NS496','chorus','Lord, Your purpose and Your heart’s desire<br/>Is to build Your church, Your temple.<br/>For this purpose You created man<br/>As a vessel to contain You.<br/>You were processed as the Spirit<br/>Now You’re working in our being.<br/>To Your image You’re conforming us.<br/>Lord, Your work is glorious.<br/>',NULL,28671,2);
INSERT INTO stanza VALUES('NS496','chorus','May this vision, Lord, re-center us,<br/>Save us from our old self-centeredness.<br/>Be our center and centrality,<br/>And our inward harmony.<br/>Give us sight to see Your purpose—<br/>Build Yourself into our being!<br/>Mind, emotion, will, Lord, we give to You—<br/>All our heart Your home must be.<br/>',NULL,28672,3);
INSERT INTO stanza VALUES('NS496','chorus','So grant me by the riches of Your glory to be strengthened<br/>With power through Your Spirit into my inner man,<br/>That You may make Your home in all of my heart through faith.<br/>Lord, make Your home in all of my heart through faith!<br/>',NULL,28673,4);
INSERT INTO stanza VALUES('NS497','1','Begin the day with God, He really wants you to<br/>Hoping you’ll let Him come and spend the day with you.<br/>Rise up! Don’t wait! You’ll miss the Son.<br/>It’s the best part of the day.<br/>His taste is sweet, to all who meet<br/>Him in the morning when He’s fresh and new.<br/>',NULL,28674,1);
INSERT INTO stanza VALUES('NS497','2','Begin the day with God, He’s waiting there for you.<br/>Morning by morning come, His mercy is brand new.<br/>Rise up! Don’t wait! You’ll miss the Son.<br/>He has so much for you.<br/>Enjoy your portion and your part<br/>Until the Morning Star rises in your heart.<br/>',NULL,28675,2);
INSERT INTO stanza VALUES('NS497','3','Begin the day with God, He needs His people to<br/>Be those who love Him best! Get up with this in view.<br/>Rise up! Don’t wait! You’ll miss the Son.<br/>He needs some to watch and pray.<br/>Spend time with Him and let Him in—<br/>To your heart so He can have His way.<br/>',NULL,28676,3);
INSERT INTO stanza VALUES('NS498','1','Lord, Thou as the living oyster<br/>Left the realm of life and light;<br/>Seeking deep in deaths dark waters<br/>Precious ones for God’s delight.<br/>',NULL,28677,1);
INSERT INTO stanza VALUES('NS498','2','But a worthless grain You found me;<br/>Base and cruel to pierce Your side.<br/>Yet within that wound You held me,<br/>Pouring out Thy very life.<br/>',NULL,28678,2);
INSERT INTO stanza VALUES('NS498','3','Now Thy wound’s redemption keeps me<br/>Ever in Thy tender death.<br/>Prisoned there, Thy life’s secretion<br/>Covers me with preciousness.<br/>',NULL,28679,3);
INSERT INTO stanza VALUES('NS498','4','Thus a pearl, through death I enter<br/>Thine own realm of life and light;<br/>Built to be Thy habitation,<br/>Thine expression, Thy delight!<br/>',NULL,28680,4);
INSERT INTO stanza VALUES('NS498','5','Now as gates of pearl we stand here<br/>Calling to earth’s corners four,<br/>All may enter! All may enter!<br/>Worthless grains He will transform!<br/>',NULL,28681,5);
INSERT INTO stanza VALUES('NS499','1','Jacob saw the vision of a dream in Bethel,<br/>Moses saw the vision on a mountain, do tell,<br/>David saw the vision of the holy temple,<br/>Ezekiel saw the vision of the house.<br/>',NULL,28682,1);
INSERT INTO stanza VALUES('NS499','chorus','Then John.... saw the vision of the New Jerusalem,<br/>Well, it’s God.... dispensed and God built into men,<br/>We need a vision so we open to the Lord,<br/>Seeking revelation in the Holy Word,<br/>Turning to the spirit for the building of the church,<br/>The church is the fullness of the One.<br/>(Ephesians one: twenty three)<br/>',NULL,28683,2);
INSERT INTO stanza VALUES('NS499','2','Zechariah’s vision was for God’s recovery,<br/>Daniel had a vision of Christ in victory,<br/>Paul and Peter’s vision of the building of the Body<br/>Complete the revelation of the age.<br/>',NULL,28684,3);
INSERT INTO stanza VALUES('NS500','chorus','But whoever drinks of the water<br/>That I will give him<br/>Shall by no means thirst forever;<br/>But the water that I will give him<br/>Will become in him<br/>A fountain of water<br/>Springing up into eternal life;<br/>Will become in him<br/>A fountain of water<br/>Springing up into eternal life,<br/>Eternal life.<br/>',NULL,28685,1);
INSERT INTO stanza VALUES('NS501','chorus','But flee youthful lusts,<br/>And pursue righteousness,<br/>Faith, love, peace<br/>With those who call<br/>On the Lord out of a pure heart.<br/>',NULL,28686,1);
INSERT INTO stanza VALUES('NS501','chorus','But wherever their heart turns to the Lord,<br/>The veil is taken away,<br/>But whenever their heart turns to the Lord,<br/>The veil is taken away,<br/>Whenever their heart turns to the Lord,<br/>The veil is taken away,<br/>But whenever their heart turns to the Lord,<br/>The veil is taken away.<br/>',NULL,28687,2);
INSERT INTO stanza VALUES('NS502','1','We all with unveiled face,<br/>Beholding and reflecting<br/>As a mirror the glory of the Lord,<br/>Are being transformed<br/>Into the same image<br/>From glory to glory,<br/>From the Lord Spirit.<br/>',NULL,28688,1);
INSERT INTO stanza VALUES('NS502','chorus','Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>Where the Spirit of the Lord is,<br/>There is freedom;<br/>Whenever the heart turns to the Lord.<br/>',NULL,28689,2);
INSERT INTO stanza VALUES('NS502','2','You are a letter of Christ,<br/>Inscribed with the Spirit;<br/>In the fleshly tablets of the hearts.<br/>We are the ministers<br/>Of a new covenant,<br/>Not the letter which kills,<br/>But the life-giving Spirit.<br/>',NULL,28690,3);
INSERT INTO stanza VALUES('NS503','chorus','For you are a holy people<br/>To Jehovah your God;<br/>It is you whom Jehovah your God has<br/>Chosen from among<br/>All the peoples which are upon<br/>The face of the earth<br/>To be a people<br/>For His personal treasure.<br/>',NULL,28691,1);
INSERT INTO stanza VALUES('NS503','chorus','In Your lovingkindness<br/>You have led the people<br/>Whom You have redeemed;<br/>You have guided them<br/>In Your strength<br/>To Your holy habitation.<br/>',NULL,28692,2);
INSERT INTO stanza VALUES('NS504','1','He gives power to the faint,<br/>And to those who have no vigor<br/>He multiplies strength.<br/>',NULL,28693,1);
INSERT INTO stanza VALUES('NS504','2','Though youths will faint and become weary,<br/>And young men will collapse exhausted;<br/>Yet those who wait on Jehovah<br/>Will renew their strength;<br/>They will mount up with wings like eagles;<br/>They will run and will not faint;<br/>They will walk and will not become weary.<br/>',NULL,28694,2);
INSERT INTO stanza VALUES('NS504','3','To wait on the eternal God<br/>Means that we terminate ourselves.<br/>That we stop ourselves with our living, <br/>Our doing, and activity;<br/>Receive God in Christ<br/>As our life, our person, replacement.<br/>Receive God in Christ<br/>As our life, our person, replacement.<br/>',NULL,28695,3);
INSERT INTO stanza VALUES('NS504','end-note','Verses 1 and 2 can be sung together.<br/>',NULL,28696,4);
INSERT INTO stanza VALUES('NS505','1','God used John, the Baptist,<br/>Who left his home and good past;<br/>Left the religion of his age.<br/>He turned from the oldness,<br/>And spoke the Word with boldness,<br/>Repent and leave this crooked age.<br/>',NULL,28697,1);
INSERT INTO stanza VALUES('NS505','chorus','God needs the overcomers,<br/>Our dear Lord Jesus lovers!<br/>Make us those who live to turn the age!<br/>God needs the overcomers,<br/>Our dear Lord Jesus lovers!<br/>Make us those who consummate the age!<br/>',NULL,28698,2);
INSERT INTO stanza VALUES('NS505','2','God called Saul of Tarsus,<br/>For His own plan and purpose,<br/>Who became Paul, the Apostle;<br/>He saw a heav’nly vision,<br/>Where there is no division,<br/>In the one Body of the Lord.<br/>',NULL,28699,3);
INSERT INTO stanza VALUES('NS505','3','God called Timothy, now,<br/>Like-souled with Paul, who knew how<br/>To pray and be soaked in the Word;<br/>His spirit fanned into flame,<br/>Lord, make my spirit the same,<br/>An overcoming man of God!<br/>',NULL,28700,4);
INSERT INTO stanza VALUES('NS505','chorus','Make us the overcomers,<br/>Christ’s bride, and God’s age-turners.<br/>Make us those who consummate the age!<br/>',NULL,28701,5);
INSERT INTO stanza VALUES('NS506','1','Noah’s life was one that surely changed the age,<br/>When he found the grace of God;<br/>He was not afraid to stand against the world,<br/>So he built the ark of wood.<br/>',NULL,28702,1);
INSERT INTO stanza VALUES('NS506','chorus','Would you choose to be a living overcomer,<br/>Be a person not ashamed to be a Jesus lover,<br/>One who eats the tree of life,<br/>And drinks the living water?<br/>Would you choose to be a living overcomer,<br/>To leave the world and consecrate<br/>To be today’s age-turner?<br/>I give myself to You for Your return.<br/>',NULL,28703,2);
INSERT INTO stanza VALUES('NS506','2','Moses was a person who was called by God,<br/>He was meant to turn the age;<br/>He was God’s companion, he was for God’s move,<br/>He was faithful, meek, and sage.<br/>',NULL,28704,3);
INSERT INTO stanza VALUES('NS506','3','Samuel ministered to be a God-pleasing priest,<br/>He was absolute for Him;<br/>Samuel gave himself to be a Nazarite,<br/>Saved from death, the world, and sin.<br/>',NULL,28705,4);
INSERT INTO stanza VALUES('NS506','4','Daniel had companions, and they ate God’s Word,<br/>From the world, they stood apart;<br/>Through a praying spirit were aligned with God,<br/>For His people, God’s own heart.<br/>',NULL,28706,5);
INSERT INTO stanza VALUES('NS506','chorus','I will choose to be a living overcomer,<br/>Be a person not ashamed to be a Jesus lover,<br/>One who eats the tree of life,<br/>And drinks the living water.<br/>I will give myself to be an overcomer,<br/>To see a heav’nly vision,<br/>Keep my flaming spirit burning!<br/>I give myself to You, to turn this age.<br/>',NULL,28707,6);
INSERT INTO stanza VALUES('NS507','1','God’s intention is to flow Himself into man.<br/>He supplies our every need.<br/>He is free, there’s no demand.<br/>Just open to the flow.<br/>',NULL,28708,1);
INSERT INTO stanza VALUES('NS507','chorus','Can you see God’s plan?<br/>God Himself in man!<br/>He is all we need!<br/>Oh Lord keep me open unto Thee!<br/>',NULL,28709,2);
INSERT INTO stanza VALUES('NS507','2','I have come to You. I am thirsty; let me drink!<br/>All the riches of this life<br/>Flood in me, with joy I cry,<br/>“I am no longer dry!”<br/>',NULL,28710,3);
INSERT INTO stanza VALUES('NS507','chorus','You have come to us!<br/>Now we come to drink!<br/>We are filled with Christ<br/>Drinking at the Fount of life am I!<br/>',NULL,28711,4);
INSERT INTO stanza VALUES('NS507','3','Though I fail each day, I return to You and pray,<br/>Asking Lord, “Unveil my face.<br/>Keep me always in Your grace.<br/>I drown without You Lord!”<br/>',NULL,28712,5);
INSERT INTO stanza VALUES('NS507','chorus','Though I fail each day,<br/>I return and pray.<br/>And I’m drawn to say<br/>Lord make home in all my heart and stay!<br/>',NULL,28713,6);
INSERT INTO stanza VALUES('NS507','4','There is a river flowing from the throne<br/>Reaching man in every place.<br/>All our problems are erased.<br/>We love You Jesus Lord!<br/>',NULL,28714,7);
INSERT INTO stanza VALUES('NS507','chorus','God flows in me<br/>He will never leave.<br/>I am now set free!<br/>I am satisfied eternally!<br/>',NULL,28715,8);
INSERT INTO stanza VALUES('NS508','chorus','Precious in the sight of the Lord<br/>Is the death of His faithful ones.<br/>Precious in the sight of the Lord<br/>Is the death of His faithful ones.<br/>',NULL,28716,1);
INSERT INTO stanza VALUES('NS508','chorus','They lived to Him<br/>and died to Him;<br/>Precious to Him,<br/>They are now with Him<br/>whom they love.<br/>',NULL,28717,2);
INSERT INTO stanza VALUES('NS509','1','Father with Thee in secret I would be, <br/>Just to allow Thy Son to pray through me;<br/>Waiting in love to hear Thy blest reply,<br/>Thy heart revealed to me in Christ thereby.<br/>',NULL,28718,1);
INSERT INTO stanza VALUES('NS509','2','Father with Thee in secret I would meet,<br/>E’er to delight in, fellowship so sweet;<br/>In Thy blest Son, abundant life’s supplied,<br/>My empty, broken heart is satisfied.<br/>',NULL,28719,2);
INSERT INTO stanza VALUES('NS509','3','Father with Thee in secret I would meet,<br/>Closed to the world with all its dark deceit,<br/>Only the fragrance of Thy lovely Son<br/>Passing between us, He our rest becomes.<br/>',NULL,28720,3);
INSERT INTO stanza VALUES('NS509','4','Father with Thee in secret I’d remain,<br/>Letting Thy light my thoughts and will make plain,<br/>Thy Son, my only plea, I now embrace,<br/>Sheltered in Him from my unholy ways.<br/>',NULL,28721,4);
INSERT INTO stanza VALUES('NS509','5','Father with Thee in secret I would be,<br/>Seeking Thy will’s fulfillment thus to see,<br/>Christ as the first in all things big and small;<br/>Heaven and earth Thy glory shown to all.<br/>',NULL,28722,5);
INSERT INTO stanza VALUES('NS510','1','Into our care did God entrust<br/>The children, an inheritance,<br/>We must equipped in spirit be,<br/>To match God’s heart in shepherding.<br/>',NULL,28723,1);
INSERT INTO stanza VALUES('NS510','chorus','To shepherd them, seize every chance,<br/>Impart the faith with diligence;<br/>Build character without delay,<br/>Raise up the vessels of the age.<br/>',NULL,28724,2);
INSERT INTO stanza VALUES('NS510','2','Enjoy the grace of Christ each day,<br/>Each moment live the God-man way;<br/>For the right timing, watch and pray,<br/>And be good patterns every day.<br/>',NULL,28725,3);
INSERT INTO stanza VALUES('NS510','3','This crooked age defiled all lands;<br/>The church alone most holy stands.<br/>Coordinate with other saints,<br/>Young vessels unto honor gain.<br/>',NULL,28726,4);
INSERT INTO stanza VALUES('NS511','1','Are you willing to be an age-turner?<br/>Are you trusting to listen to Him?<br/>The Spirit of life is ours for the taking<br/>So let’s charge forth with boldness,<br/>Leave the world behind!<br/>',NULL,28727,1);
INSERT INTO stanza VALUES('NS511','chorus','We have to claim this divine power,<br/>Not be ashamed of our wonderful Christ.<br/>We have to claim this divine Spirit<br/>To minister and function, propagate and spread!<br/>',NULL,28728,2);
INSERT INTO stanza VALUES('NS511','2','Will you be making a fresh consecration?<br/>To build a new altar, preparing for His bride,<br/>It’s all up to us—His corporate expression<br/>So let’s charge forth with boldness,<br/>Taking Christ as life!<br/>',NULL,28729,3);
INSERT INTO stanza VALUES('NS511','3','Are you open to this dispensation?<br/>Are you ready to answer His call?<br/>To turn this age, He needs the young people<br/>So let’s charge forth with boldness<br/>For the Lord’s return!<br/>',NULL,28730,4);
INSERT INTO stanza VALUES('NS511','chorus','Yes! We will claim this divine power,<br/>Not be ashamed of our wonderful Christ.<br/>Yes! We will claim this divine Spirit<br/>To minister and function, propagate and spread!<br/>',NULL,28731,5);
INSERT INTO stanza VALUES('NS512','1','If I go to the meeting,<br/>But shy away from speaking,<br/>There’s no life that’s releasing<br/>Of my loving Christ.<br/>',NULL,28732,1);
INSERT INTO stanza VALUES('NS512','chorus','Let’s not quench the Spirit,<br/>But take heed to say,<br/>Let’s not quench the Spirit,<br/>But fan it into flame<br/>By calling “Oh Lord Jesus“!<br/>Let’s speak your word today!<br/>We can grow in life divine<br/>Without fluctuation!<br/>We can grow in life divine,<br/>Discipling the nation!<br/>',NULL,28733,2);
INSERT INTO stanza VALUES('NS512','2','Though a brother is speaking,<br/>Am I closed to receiving?<br/>Why won’t I just be open;<br/>Be filled and say “Amen“!<br/>',NULL,28734,3);
INSERT INTO stanza VALUES('NS513','1','Worldly affairs encumbered me; till the Lord said, “Come, follow Me!”<br/>I was exhausted, faltering; still He called and would not leave me be;<br/>At once, when I responded: “Yes!”, He shined His glad’ning ray!<br/>Glory, rest, shouts of praise fill all my days as I follow on His way.<br/>',NULL,28735,1);
INSERT INTO stanza VALUES('NS513','2','Though in this world a way exists<br/>Filled with crowds with greatness obsessed;<br/>My heart already is possessed, let those who would take it try their best;<br/>Lord, I’ve been sanctified by Thee, For God alone I’m meant,<br/>My all is in Your sovereign hand, all for the new way to be spent.<br/>',NULL,28736,2);
INSERT INTO stanza VALUES('NS513','3','No man can serve two masters, from God and the world seek reward,<br/>Whether ’tis spent or whether reserved, ointment can but once be outpoured;<br/>Lord, You’re my only one true love, I’d ne’er repent nor swerve.<br/>Lord, You alone are worthy of all my life and all my love.<br/>',NULL,28737,3);
INSERT INTO stanza VALUES('NS513','chorus','Upon this altar of consecration, supply the flame; refine me, I pray;<br/>Lord, You chose me, ’twas mercy and grace; Gladly I choose Thee, to repay.<br/>The days of this life don’t seem that special, but the earth to heaven they join;<br/>In Your smile’s delight, I fix my sight, running towards th’ eternal crown.<br/>',NULL,28738,4);
INSERT INTO stanza VALUES('NS514','1','Your people will offer themselves willingly<br/>In the day of Your warfare;<br/>Your people will offer themselves willingly<br/>In the day of Your warfare,<br/>In the splendor of their consecration.<br/>Your young men will be like dew to You<br/>From the womb of the dawn.<br/>You will drink from the brook, Your overcomers,<br/>As You fight on the way to carry out<br/>God’s economy.<br/>',NULL,28739,1);
INSERT INTO stanza VALUES('NS514','2','Dear Lord, I will offer myself willingly<br/>In the day of Your warfare;<br/>Dear Lord, I will offer myself willingly<br/>In the day of Your warfare,<br/>In the splendor of fresh consecration.<br/>As young men we’ll be like dew to You<br/>Of our generation.<br/>We will be the brook to water You, Lord,<br/>As You take th’ lead to fight through to the end;<br/>You will lift up Your head.<br/>',NULL,28740,2);
INSERT INTO stanza VALUES('NS515','1','The heavenly vision<br/>Concerning the function<br/>Of God’s chosen people on earth today<br/>Controls and directs us,<br/>Restricts and perfects us<br/>To minister Christ and close this age!<br/>',NULL,28741,1);
INSERT INTO stanza VALUES('NS515','chorus','Reigning in life:<br/>Being ruled by the Spirit,<br/>Restricted and limited;<br/>Reigning in life:<br/>To bring in God’s kingdom<br/>And realize the kingdom life.<br/>',NULL,28742,2);
INSERT INTO stanza VALUES('NS515','2','A time of confinement<br/>To seek the experience<br/>In being alone with our Lord today<br/>And speak forth with boldness<br/>The dreams of our father,<br/>Discipling the nations to close this age!<br/>',NULL,28743,3);
INSERT INTO stanza VALUES('NS516','chorus','Your people will offer themselves willingly<br/>In the day of Your warfare,<br/>In the splendor of their consecration.<br/>Your young men will be to You<br/>Like the dew from the womb of the dawn.<br/>(repeat)<br/>',NULL,28744,1);
INSERT INTO stanza VALUES('NS516','chorus','He will drink from the brook by the way;<br/>Therefore He will lift up His head.<br/>He will drink from the brook by the way;<br/>Therefore He will lift up His head.<br/>',NULL,28745,2);
INSERT INTO stanza VALUES('NS517','1','Chosen, called, responding to You, Meeting You has given my life value.<br/>Though I’m young, I haste to pursue You, To be a vessel Your riches shine through.<br/>Consecrating, I hesitate: Can I that blest goal of glory attain?<br/>In Your light I suddenly see: Not my might, but Your unrivaled mercy!<br/>',NULL,28746,1);
INSERT INTO stanza VALUES('NS517','chorus','Fresh consecration! Wholly for Thee, I’ll closely follow, time redeem!<br/>Live Your transcendent life, Lord, through me, That the treasure within be seen!<br/>',NULL,28747,2);
INSERT INTO stanza VALUES('NS517','2','Treasure hid in vessels of earth Manifests Your power and transcendence;<br/>In Your face’s light e’er abiding, If nearer Thee, naught more would I desire.<br/>Pressure, persecutions, and wounds Just bring resurrection life into bloom;<br/>Though we suffer light trans’ient pain, The eternal weight of glory’s gained!<br/>',NULL,28748,3);
INSERT INTO stanza VALUES('NS517','3','God of glory shines, drawing us; Goodbye world, our lives are for God’s purpose!<br/>Precious vessels ready for using, No matter where, as long as it’s with Thee.<br/>We are washed and cleansed by Your word, Unencumbered, holy, transparent, pure;<br/>Mold us, Lord, conform us to Thee; At Your call, we’d rise up instantly!<br/>',NULL,28749,4);
INSERT INTO stanza VALUES('NS517','4','New Jerusalem is our dream; For her building, steadfast we’re pursuing;<br/>Love outpoured, sweet ointment o’erflowing, Fight boldly for the interests of our God.<br/>Vital, spread the God-ordained way Till as one the new revival we gain;<br/>Oh my Lord, my love, quickly come, As You promised, in our generation!<br/>',NULL,28750,5);
INSERT INTO stanza VALUES('NS518','chorus','Simon, son of John,<br/>Do you love me?<br/>He said to Him, Yes Lord,<br/>You know that I love You.<br/>I love You, I love You,<br/>You know that I love You.<br/>He said to him, shepherd My sheep.<br/>',NULL,28751,1);
INSERT INTO stanza VALUES('NS519','1','“I will impart My laws into their mind,”<br/>Our covenanting God revealed to mankind;<br/>“I will inscribe My laws upon their heart,”<br/>God’s highest law of life into us impart.<br/>',NULL,28752,1);
INSERT INTO stanza VALUES('NS519','chorus','Christ is the title deed of all God is;<br/>Christ is a testament with all its bequests;<br/>Now the New Testament is ours to claim,<br/>As we in spirit call upon His name.<br/>',NULL,28753,2);
INSERT INTO stanza VALUES('NS519','2','“I will be God to them” declares the Lord,<br/>Christ, our inheritance, described in God’s Word;<br/>“And they will be to Me a people,” possessed<br/>As God’s inheritance, His riches expressed.<br/>',NULL,28754,3);
INSERT INTO stanza VALUES('NS519','3','“For all will know Me” and consecrate,<br/>Even the little ones and also the great;<br/>All have capacity to live such a life;<br/>All live in oneness, abiding in Christ.<br/>',NULL,28755,4);
INSERT INTO stanza VALUES('NS519','4','“I will propitiate,” forgiving sin,<br/>Cleansing the inward parts and washing within;<br/>Christ’s efficacious blood has set us free,<br/>Restoring fellowship eternally.<br/>',NULL,28756,5);
INSERT INTO stanza VALUES('NS520','1','Hidden behind every scene,<br/>Lovingly, sweetly operating,<br/>One who is sovereign and wise,<br/>Patiently guides even our eyes.<br/>Look at My Son, the Beloved,<br/>Sitting here at My right hand.<br/>Jesus is King, yet He’s bound,<br/>He cannot move until His people<br/>give Him ground.<br/>',NULL,28757,1);
INSERT INTO stanza VALUES('NS520','chorus','Lord, we see You! Lord, we love You!<br/>Lord, we submit everything to You.<br/>Each day, Your ruling and Your reigning<br/>Brings a sweet supply.<br/>Oh, what a rich blessing!<br/>We’re in the hand of our King. <br/>Everything You hope to accomplish,<br/>do in me.<br/>',NULL,28758,2);
INSERT INTO stanza VALUES('NS520','2','In us a small Kingdom seed,<br/>Orders our steps, governs our deeds.<br/>Jesus, enthroned in our hearts,<br/>Gently He touches our every part.<br/>Do you not know you’re the temple<br/>Of your God, King of Kings?<br/>Through us our Lord has a way,<br/>To rule and to reign here on the earth<br/>day by day.<br/>',NULL,28759,3);
INSERT INTO stanza VALUES('NS521','1','On the cross You gave Your life for me,<br/>That I might live again.<br/>In resurrection You have lifted me<br/>To newness born within.<br/>Through the blood I repent of all my sins,<br/>Precious Lord I now give in;<br/>Fill me Lord Jesus,<br/>Lord, I ask You to come in.<br/>',NULL,28760,1);
INSERT INTO stanza VALUES('NS521','2','Upon my heart Lord write Your law,<br/>So the Christ in me may grow.<br/>Renew me in my mind too, Lord,<br/>That Your light through me may show;<br/>Calling, “O Lord Jesus!”<br/>Wherever I may be;<br/>Thank You sweet, sweet Jesus,<br/>For today You set me free.<br/>',NULL,28761,2);
INSERT INTO stanza VALUES('NS521','3','Lord, I really love You,<br/>You’re everything I need.<br/>Make Your home within my heart,<br/>Only You I will believe.<br/>Loving You and living You<br/>With a heart that’s pure and true;<br/>O dear Lord Jesus,<br/>I trust my life to You.<br/>',NULL,28762,3);
INSERT INTO stanza VALUES('NS522','1','While Christ builds His church,<br/>Gates of Hades will<br/>Rise up to attack us<br/>But will never prevail.<br/>',NULL,28763,1);
INSERT INTO stanza VALUES('NS522','2','’Tis not what we face<br/>But ’tis how much grace<br/>We receive in the midst<br/>Of our circumstances.<br/>',NULL,28764,2);
INSERT INTO stanza VALUES('NS522','3','Why not turn to prayer<br/>For those in need like us<br/>While we can sympathize, that<br/>Through this they will gain Christ.<br/>',NULL,28765,3);
INSERT INTO stanza VALUES('CS330','1','讓我佇立你背後，主！<br/>讓我挨著你的腳哭，<br/>讓我頭髮擦拭你足，<br/>讓我香膏，為著你<br/>全然倒出。<br/><br/>我愛你！愛你主耶穌！<br/>為你甘願枉費，一無所顧。<br/>從我玉瓶傾倒香膏，<br/>為你身、你頭、你腳，<br/>為你─摯愛主，我愛，你耶穌！<br/>',NULL,28766,1);
INSERT INTO stanza VALUES('CS330','2','我將貴重膏油取出，<br/>膏抹我所至愛的主；<br/>在你腳前我今俯伏，<br/>膏油芬芳，因著愛，<br/>漫溢四處。<br/><br/>我愛你！愛你主耶穌！<br/>為你甘願枉費，一無所顧。<br/>從我玉瓶傾倒香膏，<br/>為你身、你頭、你腳，<br/>為你─摯愛主，我愛，你耶穌！<br/>',NULL,28767,2);
INSERT INTO stanza VALUES('CS330','3','人說你若凡事知道，<br/>必知是誰在摸你腳；<br/>是的，我罪實不可告，<br/>不配摸你，還妄想<br/>獻上香膏。<br/><br/>但我愛。。。愛你，主耶穌！<br/>愛深是因多得赦罪之故。<br/>從我玉瓶傾倒香膏，<br/>為你身、你頭、你腳，<br/>為你─摯愛主，我愛，你耶穌！<br/>',NULL,28768,3);
INSERT INTO stanza VALUES('CS330','4','我要用我愛洗你足，<br/>你腳前，我己可不顧；<br/>你的價值有誰能述？<br/>我的愛情並全人<br/>都當你屬。<br/><br/>我愛你！愛你，主耶穌！<br/>我愛情我全人都為你，主。<br/>求悅納我和我香膏，<br/>愛主，這是我上好，<br/>為你─摯愛主，我愛，你耶穌！<br/>',NULL,28769,4);
INSERT INTO stanza VALUES('K1','1','성부 성자 성령님께 영광 돌리세<br/>영원토록 영광 돌려 하나님께<br/>',NULL,28770,1);
INSERT INTO stanza VALUES('K1','2','하나님의 지혜로 된 광대한 창조<br/>감상할 때 영 감동돼 경배하네<br/>',NULL,28771,2);
INSERT INTO stanza VALUES('K1','3','하나님의 원하심은 아들들 얻어<br/>찬미하며 감상하게 하심일세<br/>',NULL,28772,3);
INSERT INTO stanza VALUES('K1','4','계시로써 사랑 비밀 나타내시어<br/>깨닫고 또 영접하여 사랑케 해<br/>',NULL,28773,4);
INSERT INTO stanza VALUES('K1','5','그리스도 구속으로 원수 깨뜨려<br/>새 창조 안에 경배자 얻었다네<br/>',NULL,28774,5);
INSERT INTO stanza VALUES('K1','6','성부 성자 성령님께 영광 돌리세<br/>영원토록 영광 돌려 하나님께<br/>',NULL,28775,6);
INSERT INTO stanza VALUES('K10','1','뛰어난 하나님 - 거룩한 하나님 - 그 무엇도 당신과<br/>비교할 수 없네 우주 안에 지극히 거룩하신 주님<br/>영원한 신성 능력 만유 초월하네<br/>',NULL,28776,1);
INSERT INTO stanza VALUES('K10','2','죄 없고 흠 없으며 완전히 성별되신 당신과 그 무엇을<br/>비길 수 있으랴 무엇이 당신에게 배필이 되 - 리요 -<br/>아무도 주 당신을 대신할 수 없네<br/>',NULL,28777,2);
INSERT INTO stanza VALUES('K10','3','뛰어난 자들보다 더 뛰어나시고 - 아름다운 자보다<br/>아름다우신 분 그 어떤 선한 자도 당신과 비 - 교 못해<br/>당신의 선과 미는 탁월한 것일세<br/>',NULL,28778,3);
INSERT INTO stanza VALUES('K10','4','거룩한 주의 특성 우리에게 주셔 - 우린 다 그 성품에<br/>참예한 자 됐네 우리도 당신 성품 지녀서 뛰 - 어나고<br/>당신의 거룩 좇아 거룩히 분별돼<br/>',NULL,28779,4);
INSERT INTO stanza VALUES('K10','5','당신의 뛰어남과 성별함 찬양할 때 당신과 비교할 것<br/>그 무엇 있으랴 우리도 당신 특성 받고서 찬 - 양하며<br/>당신의 분별하는 성품에 참여해<br/>',NULL,28780,5);
INSERT INTO stanza VALUES('K100','1','주 부활했네 심판 지났네<br/>사망이 다시 침입 못하리<br/>이제 나에게 정죄함 없네<br/>빈 무덤 그의 부활 증거해<br/>',NULL,28781,1);
INSERT INTO stanza VALUES('K100','2','주 부활할 때 나도 부활해<br/>그 무덤 안에 원수 묻혔네<br/>주 부활할 때 나도 해방돼<br/>그 부활 생명 의지해 사네<br/>',NULL,28782,2);
INSERT INTO stanza VALUES('K100','3','주 부활할 때 나도 구출돼<br/>이 광야에서 주님을 좇네<br/>주님과 함께 지성소에 가<br/>하나님 얼굴빛 앞에 사네<br/>',NULL,28783,3);
INSERT INTO stanza VALUES('K100','4','주 부활하여 선봉 되셨네<br/>난 진영 밖서 주의 간증돼<br/>난 큰 소리로 개가 부르리<br/>“주 승리 백성 자유케 하네”<br/>',NULL,28784,4);
INSERT INTO stanza VALUES('K1000','1','영 안에서 우린 보았네 하나님의 이상을<br/>그의 왕국 땅에 임하는 높고 분명한 이상을<br/>주의 회복의 불 내 마음에 불타 오르네<br/>불타 오르네 내 맘에 불타네<br/>모든 소극적인 것들은 다 태워 버리고<br/>영광 영광으로 건축해<br/>',NULL,28785,1);
INSERT INTO stanza VALUES('K1000','2','타오르는 불로 인하여 모든 것 다 던지고<br/>목표 향해 전진 하리라 성령 안에 달하리라<br/>주의 회복의 불 내 마음에 불타 오르네<br/>불타 오르네 내 맘에 불타네<br/>모든 소극적인 것들은 다 태워 버리고<br/>영광 영광으로 건축해<br/>',NULL,28786,2);
INSERT INTO stanza VALUES('K1000','3','온 땅 위의 주 회복 위해 온 생명 다 바치리<br/>우리에게 주여 불타는 마음을 주시옵소서<br/>주의 회복의 불 내 마음에 불타 오르네<br/>불타 오르네 내 맘에 불타네<br/>모든 소극적인 것들은 다 태워 버리고<br/>영광 영광으로 건축해<br/>',NULL,28787,3);
INSERT INTO stanza VALUES('K1000','4','지방마다 우린 하나로 그의 등대 선포해<br/>그리스도 다시 오시리 그의 신부 맞으려고<br/>주의 회복의 불 내 마음에 불타 오르네<br/>불타 오르네 내 맘에 불타네<br/>모든 소극적인 것들은 다 태워 버리고<br/>영광 영광으로 건축해<br/>',NULL,28788,4);
INSERT INTO stanza VALUES('K1001','1','다윗은 말했지“난- 백향목 궁에- 사나-<br/>나의 하나님은 장-막에 거하시-네- -<br/>주의 집 짓기까지는 나는 쉴 수 없어-<br/>전능하신 하나님의 집 이루기까진”<br/>',NULL,28789,1);
INSERT INTO stanza VALUES('K1001','2','하나님의 집은 황-폐해져 있어-도- -<br/>우린 오랫동안 눈- 멀어 보지 못-했네-<br/>오 주여 우릴 깨우사 산 오르게 하여-<br/>집 건축할 나무들 가져오게 하소서<br/>',NULL,28790,2);
INSERT INTO stanza VALUES('K1001','3','다른 날 있다고 우린 말하지 않으-리- -<br/>오늘 이 때가 곧 주- 성전 건축할- 때니-<br/>주여 이 건축 위하여 남은 자 깨우사-<br/>다 와서 주의 집을 건축하게 하소서<br/>',NULL,28791,3);
INSERT INTO stanza VALUES('K1001','4','에스라 때처럼 돌-아와 집 건축-하자-<br/>이 복된 책임을 우리 즐겨 감당하-자- -<br/>이는 주의 갈망이요 우리 갈망일세-<br/>오 주여 우린 지금 와서 건축합니다<br/>',NULL,28792,4);
INSERT INTO stanza VALUES('K1001','5','음부의 권세가 이-기지 못하는- 교회-<br/>그의 건축 위해 우리 자신 바칩니-다- -<br/>시간은 빨리 지나니 우리 맘 불타네-<br/>오 주여 우릴 어서 빨리 건축하소서<br/>',NULL,28793,5);
INSERT INTO stanza VALUES('K1002','1','우리 주의 지방 교회 회복 위하여<br/>우리 주의 지방 교회 각지에 있네<br/>지방 입장 위에 설 때 주 안에 하나<br/>영광스런 주의 성전 세워져 가네<br/>',NULL,28794,1);
INSERT INTO stanza VALUES('K1002','chorus','주를 위하여 주를 위하여<br/>우리 주의 회복 위-해<br/>주를 위하여 주를 위하여<br/>우리 주의 회복 위-해<br/>',NULL,28795,2);
INSERT INTO stanza VALUES('K1002','2','우리 주의 지방 교회 회복 위하여<br/>주를 높이 증거하세 왕국 세우세<br/>성령 안에 입장 위에 복음 전하세<br/>주여 아멘 할렐루야 주 곧 오시리<br/>',NULL,28796,3);
INSERT INTO stanza VALUES('K1002','3','우리 주의 지방 교회 회복 위하여<br/>우리 영을 훈련하면 더 밝아지네<br/>바벨론은 무너지고 사탄 패했네<br/>영광 속에 내려오는 새 예루살렘<br/>',NULL,28797,4);
INSERT INTO stanza VALUES('K1003','1','예수님께 영광- 돌려 홀과 보좌의 주-인<br/>할렐루야 주님- 승리 홀로 얻으시었-네<br/>주의 보혈 열방- 중에 우릴 구원하셨-네<br/>구속 받은 주의- 무리 찬양 높이 부르-네<br/>',NULL,28798,1);
INSERT INTO stanza VALUES('K1003','2','죄 가운데 살던- 우리 참된 주인 찾으-니<br/>할렐루야 믿음-으로 주님 영접하였-네<br/>“너와 항상 함께-하리”약속 기억 합니-다<br/>주님 승천 하실- 때에 구름까지 환영-해<br/>',NULL,28799,2);
INSERT INTO stanza VALUES('K1003','3','할렐루야 하늘-의 떡 우리 양식 참 가-정<br/>할렐루야 배고-픈 자 매일 주님 먹겠-네<br/>전능하신 하나-님이 우리 주가 되셨-네<br/>구세주요 변호-사로 우리 중보 되시-니<br/>',NULL,28800,3);
INSERT INTO stanza VALUES('K1003','4','예수님께 영광- 돌려 홀과 보좌의 주-인<br/>할렐루야 주님- 승리 홀로 얻으시었-네<br/>주의 보혈 열방- 중에 우릴 구원하셨-네<br/>구속받은 주의- 무리 찬양 높이 부르-네<br/>',NULL,28801,4);
INSERT INTO stanza VALUES('K1004','1','바벨론을 떠나서 모이세 예루살렘<br/>우리 하나로 뭉쳐 주께 영광 돌리세<br/>각종 도리와 견해 사람 뜻을 버리고<br/>지방 입장 위에서 하나로 증거하세<br/>',NULL,28802,1);
INSERT INTO stanza VALUES('K1004','chorus','할렐루야 할렐루야 맘과 뜻을<br/>합하여 주의 몸을 이루세<br/>할렐루야 할렐루야 몸된 교회 생활 안에 있도다<br/>',NULL,28803,2);
INSERT INTO stanza VALUES('K1004','2','회복 전진 위하여 제사장들 필요해<br/>은혜 받은 무리들 주께 영광 돌리세<br/>주님으로 적셔져 참 제사장 생활해<br/>지방 입장 위에서 주의 집 건축하세<br/>',NULL,28804,3);
INSERT INTO stanza VALUES('K1004','3','우리 눈이 열려져 그의 왕권 보리라<br/>주의 권위 세워져 주께 영광 돌리세<br/>교회 유익 위하여 주의 말씀 지키고<br/>지방 입장 위에서 성령께 순종하세<br/>',NULL,28805,4);
INSERT INTO stanza VALUES('K1004','4','제단 앞에 나와서 모든 소유 바치세<br/>이렇게 섬김으로 주께 영광 돌리세<br/>아무 논쟁치 말고 온전히 주께 바쳐<br/>지방 입장 위에서 주의 한 몸 이루세<br/>',NULL,28806,5);
INSERT INTO stanza VALUES('K1004','5','기초는 닦였으니 어떠한 영광인가<br/>우리 기쁨 넘치어 주께 찬미합시다<br/>큰 소리로 외치어 땅 끝까지 전하세<br/>지방 입장 위에서 원수 마귀 멸하세<br/>',NULL,28807,6);
INSERT INTO stanza VALUES('K1005','1','우린- 하나님의 회복 위해 하나님의- - 회복 위해- -<br/>우린- - 하나님의 간증 위해 하나님의- - 간증 위해- -<br/>강하- -고 불타는 영 우릴 모두- 불 사르네- 불 사르네- -<br/>단순- -한 순결한 맘으로 주를 순간순간- - 가까이 해- - -<br/>사업 장래 날 못 붙잡네- 오직 주의 회복 위하리<br/>주의 회복 주의 회복 회복 회복<br/>우린 주의 회복 주의 간증 위하네-<br/>',NULL,28808,1);
INSERT INTO stanza VALUES('K1006','1','달려가세 푯대 향해 그리스도 향해<br/>주의 높은 부르심의 상 얻기 위하여<br/>',NULL,28809,1);
INSERT INTO stanza VALUES('K1006','chorus','달리세 달리세 달리세 할렐루야<br/>우리들은 달리네 앞으로 주만 바라보며<br/>',NULL,28810,2);
INSERT INTO stanza VALUES('K1006','2','달려가세 계산하며 잃으면 얻으리<br/>그리스도 그 영광의 상 얻기 위하여<br/>',NULL,28811,3);
INSERT INTO stanza VALUES('K1006','3','달려가세 우리 앞에 고통 있더라도<br/>주의 부활의 능력은 모든 것 이기리<br/>',NULL,28812,4);
INSERT INTO stanza VALUES('K1006','4','달려가세 다만 달려 모든 것 잊고서<br/>앞에 계신 주만 향해 달리세 앞으로<br/>',NULL,28813,5);
INSERT INTO stanza VALUES('K1007','1','방해하는 무거운 짐 벗었으니<br/>이 길 빨리 달려갈 수 있다네<br/>주님만 주목해 주목해<br/>기쁨으로 우린 목표 바라본다-<br/>그 가- 우-릴 온전히 얻으리라<br/>주님만 주목해 주목해<br/>그 분은 앞서 달리시고 이기셨다<br/>하나님 오른편에 계신 주는<br/>영광 가져 온다 우리에게<br/>모든 것 벗어나서 주만 보자<br/>예수만 주목하자<br/>',NULL,28814,1);
INSERT INTO stanza VALUES('K1008','1','나아가세 주 찬미합시다<br/>나아가세 아멘 나아가세<br/>들리네 주여 아멘 할렐루야<br/>주님 알려 주신 길로 나가세<br/>나아가세 형제 자매 지금 곧<br/>나가세 영광 할렐루야<br/>지방 교회 중에 성령 인도하니<br/>모두 나아가세<br/>',NULL,28815,1);
INSERT INTO stanza VALUES('K1009','1','주님이 어느 때 오실지 모르네<br/>주님이 어느 때 오실지 모르네<br/>주님이 어느 때 오실지 모르네<br/>깨어 주를 기다리세<br/>',NULL,28816,1);
INSERT INTO stanza VALUES('K1009','2','주님은 우리의 사랑스런 신랑<br/>주님은 우리의 사랑스런 신랑<br/>주님은 우리의 사랑스런 신랑<br/>우린 신부 할렐루야<br/>',NULL,28817,2);
INSERT INTO stanza VALUES('K1009','3','우리는 주님만 보면서 가겠네<br/>우리는 주님만 보면서 가겠네<br/>우리는 주님만 보면서 가겠네<br/>뒤는 돌아보잖으리<br/>',NULL,28818,3);
INSERT INTO stanza VALUES('K1009','4','주님이 오시네 우리는 달리네<br/>주님이 오시네 우리는 달리네<br/>주님이 오시네 우리는 달리네<br/>주와 우린 곧 만나리<br/>',NULL,28819,4);
INSERT INTO stanza VALUES('K101','1','그리스도 부활했네 할렐루야 승리 주<br/>죽었다가 다시 사신 주를 높이 찬양해<br/>나의 마음 감사하며 주 예수께 경배해<br/>고통 이긴 주를 인해 함께 개가 부르네<br/>',NULL,28820,1);
INSERT INTO stanza VALUES('K101','chorus','그리스도 부활했네 할렐루야 승리 주<br/>그를 높이 찬양하세 죽었다가 사신 주<br/>',NULL,28821,2);
INSERT INTO stanza VALUES('K101','2','그리스도 부활했네 땅의 고통 지나서<br/>열린 문을 통과하여 생명으로 오셨네<br/>사망 음부 정복하고 부활로 승리했네<br/>상처받은 머리 위에 영광의 관 쓰셨네<br/>',NULL,28822,3);
INSERT INTO stanza VALUES('K101','3','그리스도 부활했네 사망 음부 이겼네<br/>나는 주께 속하여서 주로 인해 생활해<br/>모든 의심 모든 실망 멀리 다 사라지고<br/>부활의 날 기뻐하며 주의 잔치 누리네<br/>',NULL,28823,4);
INSERT INTO stanza VALUES('K1010','1','주예수 앞에 나와서 그분을 누리세<br/>지성소 들어갈 담력 그 피로 얻었네<br/>자신의 의와 공로는 의지할 수 없네<br/>주님의 의와 피로만 구속을 얻겠네<br/>',NULL,28824,1);
INSERT INTO stanza VALUES('K1010','2','하나님의 의로우심은 죄 심판 필요해<br/>어린 양 되어 오셔서 죄 짊어 지셨네<br/>새롭고 산 길 열렸네 십자가 인하여<br/>대속물 되신 예수님 우리 죄 사했네<br/>',NULL,28825,2);
INSERT INTO stanza VALUES('K1010','3','구속을 이룬 주님께 찬양을 드리세<br/>그의 피 적용할 때에 산 체험 누리리<br/>얼마나 높고 깊은가 하나님 긍휼은<br/>어린 양 우리 주님께 찬양을 드리세10<br/>',NULL,28826,3);
INSERT INTO stanza VALUES('K1011','1','어느 이른 봄 날 우물가에 아브라함의 종<br/>그의 약대들을 멈추게 했네<br/>그의 지루했던 여행 결코 헛되지 않아<br/>그는 찾아냈네 이삭의 신부<br/>',NULL,28827,1);
INSERT INTO stanza VALUES('K1011','chorus','예비하라 저물기 전에<br/>부르는 저 소리 들린다-<br/>저 약대들이 들어 오는 저녁이 되면<br/>기쁜 혼인 잔치 시작된다네<br/>',NULL,28828,2);
INSERT INTO stanza VALUES('K1011','2','그는 아름다운 리브가를 곱게 꾸며서<br/>그의 주인에게 데리고 왔네<br/>거기에서 리브가와 이삭 서로 사랑해<br/>혼인 날의 기쁨 시작 되었네<br/>',NULL,28829,3);
INSERT INTO stanza VALUES('K1011','3','지금 은혜의 성령이 귀한 신부 찾으려<br/>위의 아버지께로 부터 왔네<br/>거기 우리의 이삭이 장막 예비해 놓고<br/>그의 리브가를 기다린다네<br/>',NULL,28830,4);
INSERT INTO stanza VALUES('K1011','4','우린 부르심을 받아 아비 친척 떠났네<br/>그의 맑고 흠없는 신부 되려<br/>우린 예수 보리 축복받은 영원 속에서<br/>그날 행복한 혼인 잔치에서<br/>',NULL,28831,5);
INSERT INTO stanza VALUES('K1012','1','나아가세 나아가세 구원의 주와<br/>영광에 인도하리니 우린 싸우세<br/>그는 이미 싸우셨네 고난 받았네<br/>그가 닦은 길로 우릴 인도해<br/>',NULL,28832,1);
INSERT INTO stanza VALUES('K1012','2','나아가세 나아가세 영광 보이네<br/>모든 강을 건너 가나안 위해 싸우세<br/>그가 항상 우릴 영광으로 보내니<br/>고난은 다만 우릴 달리게 해<br/>',NULL,28833,2);
INSERT INTO stanza VALUES('K1012','3','나아가세 나아가세 앞길 밝으니<br/>아들 다시 오기까지 용감히 싸워<br/>그가 우릴 떡과 포도주로 보살펴<br/>이 회복 얼마나 영광스런가<br/>',NULL,28834,3);
INSERT INTO stanza VALUES('K1013','1','보라 지금 때는 바로 전쟁의 날이다<br/>거스르는 흐름만이 온통 일렁인다<br/>성도들아 주 예수의 참된 형상 갖고<br/>이 땅 위에 그의 권위 함께 나타내자<br/>',NULL,28835,1);
INSERT INTO stanza VALUES('K1013','chorus','주님의 충만하신 인성을 누리자<br/>타락된 세찬 물결 이기는 인성을<br/>악한 무리 가운데서 패역한 이 세대에서<br/>교회를 통해 예수 인성 나타내야 한다<br/>',NULL,28836,2);
INSERT INTO stanza VALUES('K1013','2','저- 사탄 사람 생명 망치려 왔지만<br/>참 사람이 일어났다 그는 여자의 씨<br/>하나님이 육신 입고 사람된 주 예수<br/>마지막 아담이 되어 사탄 뜻 파했네<br/>',NULL,28837,3);
INSERT INTO stanza VALUES('K1013','3','사람이신 예수 불러 먹고 마심으로<br/>그의 인성 누리면서 사탄 진멸하자<br/>혼의 생명 부인하고 주께 돌아서서<br/>사탄 공작 깨뜨리자 새 사람 누리며<br/>',NULL,28838,4);
INSERT INTO stanza VALUES('K1013','4','보라 타락한 저 열국 죄 중에 떨어져<br/>점점 깊이 부패한다 날이 지날수록<br/>주의 나라 자녀들은 이 땅의 소금 돼<br/>주의 인성 이 땅에서 우릴 보존한다<br/>',NULL,28839,5);
INSERT INTO stanza VALUES('K1014','1','복음 안에서 교제를 나눠 주 받은 날부터<br/>복음의 진보 위하여 우린 주 말씀 전파해<br/>복음의 변명 확정 위하여 은혜에 참예하니<br/>시작한 그가 다 이루시리 주 뵙는 날까지<br/>',NULL,28840,1);
INSERT INTO stanza VALUES('K1014','2','어떠한 일들 당할지라도 복음으로 향해<br/>복음을 위해 묶인 자 됨을 모두가 알도록<br/>하나님 말씀 겁없이 말해 담대히 전파하리<br/>사랑과 능력 안에서 전해 마지막 날까지<br/>',NULL,28841,2);
INSERT INTO stanza VALUES('K1014','3','나의 몸 통해 그리스도만 나타나기 원해<br/>살든- 죽든 어떤 일에나 온전히 담대해<br/>내게 사는 것 그리스도니 부끄러울 것 없어<br/>그는 우리의 생명 또 인격 우리의 모든 것<br/>',NULL,28842,3);
INSERT INTO stanza VALUES('K1014','4','우리 온 생활 복음에 더욱 합당케 되도록<br/>복음의 신앙 위해 협력해 한 영 안에 서서<br/>주 만족 위해 선포하겠네 온전한 이 복음을<br/>주님은 생명 교회는 표현 온 땅에 외치리<br/>',NULL,28843,4);
INSERT INTO stanza VALUES('K1015','1','정말 네 맘 공허하여 채우기 원하면<br/>오직 한 분 널 채울 수 있다- -<br/>그는 예수 네- 안에 들어 오시려고<br/>지금까지 늘 기다렸네-<br/>주 예수- 주 예수- 그는 널 사랑하신다<br/>영원토록 주 예수- 주 예수- 부를 때 채워 주리-<br/>',NULL,28844,1);
INSERT INTO stanza VALUES('K1015','2','정말 네 맘 공허하여 채우기 원하면<br/>오직 한 분 널 채울 수 있다- -<br/>그는 예수 네- 안에 들어 오시려고<br/>지금까지 늘 기다렸네-<br/>주 예수- 부를 때- 그는 네 안에 오신다<br/>언제든지 주 예수- 부를 때- 그는 네 안에 오셔-<br/>',NULL,28845,2);
INSERT INTO stanza VALUES('K1016','1','내-가 너희를 한 남편인 그-리스도께<br/>드리려고 정결한 처녀로 드리려고<br/>중매 하노라 주 예수께<br/>',NULL,28846,1);
INSERT INTO stanza VALUES('K1016','2','너희를 평강의 하나님이 온전히 거룩게<br/>하-시고 또 너희 온 영과 혼과 몸이<br/>흠없게 보전 되기 원해<br/>',NULL,28847,2);
INSERT INTO stanza VALUES('K1016','3','내 은혜 너에게 족하도다 이는 내 능력이<br/>약한데서 온전해 짐이라 내 은혜가<br/>네게 족하다 족하도다<br/>',NULL,28848,3);
INSERT INTO stanza VALUES('K1016','4','주 예수 그-리스-도의 은혜와 하나님<br/>사-랑과 또-한 성령의 교통함이<br/>너희와 함께 있을지라<br/>',NULL,28849,4);
INSERT INTO stanza VALUES('K1017','1','어두운 데-서 빛이 비취라 하신 하나님께서<br/>그리스-도의 얼굴에 있는 하나님의 영광<br/>아는 빛을 우리 마음에 비취셨도다<br/>어두운 데서 빛이 있으라 하신<br/>하나님이 우리의 마-음에 비취셨도다<br/>',NULL,28850,1);
INSERT INTO stanza VALUES('K1018','1','교회 생활 아름다와 빛이 찬란한 동산<br/>주가 우릴 인도했네 찬미해<br/>하나님의 모든 풍성 우릴 공급하므로<br/>여기에서 우린 자라난다네<br/>',NULL,28851,1);
INSERT INTO stanza VALUES('K1018','chorus','난 행복해 주의 동산서<br/>참 기쁘고 사랑스럽네<br/>매일 생명나무 실과 먹고 생명수 마셔<br/>내게 이런 기쁨 다시 없다네<br/>',NULL,28852,2);
INSERT INTO stanza VALUES('K1018','2','우리 교회 생활 공장이나 학교 아닐세<br/>주가 자라나는 생명의 동산<br/>주는 우릴 함께 사랑스런 이 곳에 심고<br/>항상 물 주시며 양육하시네<br/>',NULL,28853,3);
INSERT INTO stanza VALUES('K1018','3','교회 생활 동산에는 생명나무가 있어<br/>생명 충만하고 먹기 편리해<br/>모든 의견 내려놓고 관념 벗어 버리고<br/>다만 생명나무 먹고 누리리<br/>',NULL,28854,4);
INSERT INTO stanza VALUES('K1018','4','보라 생명수의 복락의 강 여전히 흘러<br/>나의 메마름을 모두 적시네<br/>할렐루야 이 동산서 모두 내 안에 흘러<br/>나를 공급하네 성숙하도록<br/>',NULL,28855,5);
INSERT INTO stanza VALUES('K1018','5','주는 날 인도해 그분 자신 누리게 했네<br/>나의 맘과 영에 찬미 넘치네<br/>그의 풍성함과 즐거움을 매일 누리며<br/>낙원에서 생명 열매 맺겠네<br/>',NULL,28856,6);
INSERT INTO stanza VALUES('K1019','1','와서 먹세 주님 부르네 와서 먹세<br/>항상 주를 먹고 마실 수 있네<br/>매일 양식 주 공급해 주만 우리 채우시네<br/>와서 먹세 주님 부르네 와서 먹세<br/>',NULL,28857,1);
INSERT INTO stanza VALUES('K1019','2','와서 먹세 주님 부르네 와서 먹세<br/>우리 항상 주를 먹고 마실 때<br/>주는 우리 생명 되고 내게 성령 충만되네<br/>와서 먹세 주님 부르네 와서 먹세<br/>',NULL,28858,2);
INSERT INTO stanza VALUES('K102','1','구주 예수 부활했네 할 - 렐 - 루 - 야 사망 묶임 다 벗었네 할 - 렐 - 루 - 야<br/>천사들도 환호해 할 - 렐 - 루 - 야 은혜 입은 죄인 찬미하네 할 - 렐 - 루 - 야<br/>',NULL,28859,1);
INSERT INTO stanza VALUES('K102','2','주는 음부 떠나셨네 할 - 렐 - 루 - 야 사망의 침 다시 없네 할 - 렐 - 루 - 야<br/>주가 부활했으니 할 - 렐 - 루 - 야 무 - 덤 - 이 주 못 잡았네 할 - 렐 - 루 - 야<br/>',NULL,28860,2);
INSERT INTO stanza VALUES('K102','3','구속 모두 이뤘네 - 할 - 렐 - 루 - 야 원수 멸해 이겼네 - 할 - 렐 - 루 - 야<br/>주가 사망 뚫고서 할 - 렐 - 루 - 야 높 - 이 - 올라 원수 밟네 할 - 렐 - 루 - 야<br/>',NULL,28861,3);
INSERT INTO stanza VALUES('K102','4','우리 또한 부활했네 할 - 렐 - 루 - 야 주와 함께 초월하네 할 - 렐 - 루 - 야<br/>하늘 위에 앉았네 할 - 렐 - 루 - 야 땅 - 의 - 묶임 벗어났네 할 - 렐 - 루 - 야<br/>',NULL,28862,4);
INSERT INTO stanza VALUES('K1020','1','그리스도 생명 주는 영 곧 생명의 말씀일세<br/>생명의 영 내 안에 흘러 그 말씀 날 변케 했네<br/>종일 주를 먹고 또 마시며 숨 쉬네<br/>종일 주를 먹고 또 마시며 숨 쉬어<br/>',NULL,28863,1);
INSERT INTO stanza VALUES('K1020','2','그리스도 생명 주는 영 곧 생명의 말씀일세<br/>생명의 영 내 안에 흘러 그 말씀 날 변케 했네<br/>기도하며 주 말씀 읽고 또 찬양해<br/>기도하며 주 말씀 읽고 또 찬양<br/>',NULL,28864,2);
INSERT INTO stanza VALUES('K1021','1','우리를 부른 주님 다시 또 부르신다<br/>그의 부르심에 우린 아멘해 타락된 교회들은<br/>생각으로만 알 뿐 생명은 실패했네 잃었네<br/>',NULL,28865,1);
INSERT INTO stanza VALUES('K1021','chorus','이기세 이기세 타락된 기독교를 회복하세<br/>나의 노력 떠나서 모든 학설 떠나서<br/>어떤 일에든 주 먹어 이기세<br/>',NULL,28866,2);
INSERT INTO stanza VALUES('K1021','2','먹는 건 우리 운명 먹는 건 주의 회복<br/>먹음으로 원수를 깨뜨려 와서 생명 누리세<br/>교리 분쟁 떠나서 주님을 먹음으로 이기세<br/>',NULL,28867,3);
INSERT INTO stanza VALUES('K1021','3','교훈으로 우리 혼 변화시킬 수 없고<br/>하나님의 목적을 못 이뤄 주님을 먹음으로<br/>모든 것을 해결해 주를 온전히 먹어 이기세<br/>',NULL,28868,4);
INSERT INTO stanza VALUES('K1021','4','사내아이 낳으려면 주 모셔 내리려면<br/>모든 부족함 중에 주 먹세 주 원하는 사내아이<br/>주님 원하는 교회 주님 감탄할 신부 되려면<br/>',NULL,28869,5);
INSERT INTO stanza VALUES('K1022','1','오 우리 모두 잔치에 갑시다 다 함께 즐거운<br/>노래 부르며 슬픔과 고통과 아픔 지나고<br/>이제는 다 함께 기쁘게 뛰어 봅시다<br/>영광스러운 기쁨 있고 즐거운 노래 있는 곳<br/>한 번이라도 맛본 자는 선포하리 참 좋다고<br/>오 우리 모두 잔치에 갑시다 다 함께 즐거운<br/>노래 부르며 슬픔과 고통과 아픔 지나고<br/>이제는 다 함께 기쁘게 가세<br/>',NULL,28870,1);
INSERT INTO stanza VALUES('K1022','2','예루살렘은 잔치 누리는 곳 우리의 하나를<br/>간증하는 곳 이미 우리는 이 곳에 왔으니<br/>주님께 감사와 찬송을 높이 부르세<br/>예루살렘 성전 세우고 참된 교통 가집시다<br/>주님 사랑하는 자 모두 하나님 영광 나타내<br/>예루살렘은 잔치 누리는 곳 우리의 하나를<br/>간증하는 곳 이미 우리는 이 곳에 왔으니<br/>주님께 감사와 찬송을 불러<br/>',NULL,28871,2);
INSERT INTO stanza VALUES('K1022','3','공수로는 그 곳에 갈 수 없네 염소나 송아지<br/>혹은 비둘기 무교병이나 한줌의 밀가루<br/>우리의 하나님께 모두 바쳐야 하네<br/>풍성하신 그리스도는 우리들의 참된 수확<br/>주를 누리기 위해서는 하나님을 섬겨야 해<br/>공수로는 그 곳에 갈 수 없네 염소나 송아지<br/>혹은 비둘기 무교병이나 한줌의 밀가루<br/>우리의 하나님께 모두 드려<br/>',NULL,28872,3);
INSERT INTO stanza VALUES('K1023','1','영광스런 구세주 하늘 광-채 보이니<br/>아름답-고 위대함 믿음으-로 보겠네<br/>',NULL,28873,1);
INSERT INTO stanza VALUES('K1023','2','찬양받기 합당한 달콤하-신 주 예수<br/>비교할- 데 없는 이 하나님-의 참 표현<br/>',NULL,28874,2);
INSERT INTO stanza VALUES('K1024','1','영광스런 주님의 상에 우리는 초대 받았네<br/>주의 가족 만찬석에 영광스런 주님의 상에<br/>',NULL,28875,1);
INSERT INTO stanza VALUES('K1024','chorus','할렐루-야 할렐루야 할렐루야 이- 잔-치<br/>할렐루-야 할렐루야 영광스런 주-님의 상<br/>',NULL,28876,2);
INSERT INTO stanza VALUES('K1024','2','누릴만한 주님의 상에 우리 서로 교통하네<br/>할렐루야 찾았도다 누릴만한 주님의 상을<br/>',NULL,28877,3);
INSERT INTO stanza VALUES('K1024','3','주의 죽음 선포하도다 상에 있는 떡과 잔이<br/>주의 상을 누릴 때에 원수 마귀 도망하도다<br/>',NULL,28878,4);
INSERT INTO stanza VALUES('K1024','4','실재이신 주님의 상을 떡을 통해 볼 수 있네<br/>주의 육체 찢어짐은 우리 향한 사랑 나타내<br/>',NULL,28879,5);
INSERT INTO stanza VALUES('K1024','5','신선하신 주님의 상은 우릴 만족하게 하네<br/>매일 우릴 공급하니 신선하신 주의 상일세<br/>',NULL,28880,6);
INSERT INTO stanza VALUES('K1024','6','격려하는 주님의 상을 오실 때까지 먹겠네<br/>기다리고 기다리네 주의 상에 참여하면서<br/>',NULL,28881,7);
INSERT INTO stanza VALUES('K1025','1','금과 은을 가지곤 구속 못 사고 많은 재물 내 혼을 구원 못해<br/>십자가의 피가 참 유일한 근거 내 구주의 죽음만이 구원해<br/>',NULL,28882,1);
INSERT INTO stanza VALUES('K1025','chorus','하나님 날 구속 하셨네 금과 은이 아니라<br/>그의 아들 그 귀한 피로 사랑의 값 치뤘네<br/>',NULL,28883,2);
INSERT INTO stanza VALUES('K1025','2','금과 은을 가지곤 구속 못 사고 양심은 늘 가책에 시달릴 때<br/>십자가의 피가 참 유일한 근거 내 구주의 죽음이 날 사셨네<br/>',NULL,28884,3);
INSERT INTO stanza VALUES('K1025','3','금과 은을 가지곤 구속 못 사고 나는 하나님을 가까이 못해<br/>십자가의 피가 참 유일한 근거 내 구주의 죽음이 날 이끌어<br/>',NULL,28885,4);
INSERT INTO stanza VALUES('K1025','4','금과 은을 가지곤 구속 못 사고 천국으로 가는 표 사지 못해<br/>십자가의 피가 참 유일한 근거 내 구주의 죽음이 날 구속해<br/>',NULL,28886,5);
INSERT INTO stanza VALUES('K1026','1','주님의 그 귀한 높은 값 치루셨네<br/>헛된 삶 살아갈 우리 주가 구속하셨네<br/>',NULL,28887,1);
INSERT INTO stanza VALUES('K1026','chorus','그 고귀한 피로 우리를 구속했네<br/>성결한 생활을 통해 주님을 나타내세<br/>',NULL,28888,2);
INSERT INTO stanza VALUES('K1026','2','썩어져 가는 구습을 따르던 나의 생활<br/>의미도 목표도 없이 텅빈 것 뿐이었네<br/>',NULL,28889,3);
INSERT INTO stanza VALUES('K1026','3','오직 주 예수의 피만 우리를 살 수 있네<br/>흠 없는 어린 양으로 십자가 달리셨네<br/>',NULL,28890,4);
INSERT INTO stanza VALUES('K1026','4','수많은 사람들 중에 우리는 특이하네<br/>주님께 선택을 받아 피뿌림 받았으니<br/>',NULL,28891,5);
INSERT INTO stanza VALUES('K1027','1','오 달콤-한 생명나무 하나님-의 생명<br/>죽었-던 나 살아-났네 그 실과 먹고서<br/>',NULL,28892,1);
INSERT INTO stanza VALUES('K1027','2','주 하나님 날 이끄네 생명나무 앞에<br/>오, 귀한 실과 나 먹으니 이는 그리스도<br/>',NULL,28893,2);
INSERT INTO stanza VALUES('K1027','3','참된 양식 생명 공급 이는 곧 주 예수<br/>참된 누림 되신 주만 날 만족게 하네<br/>',NULL,28894,3);
INSERT INTO stanza VALUES('K1027','4','값없이 생명과 먹어 하나님 충만해<br/>주로 인해 주 말미암아 주 위해 산다네<br/>',NULL,28895,4);
INSERT INTO stanza VALUES('K1028','1','나는 생명의 샘에 왔네- 하늘로부터 흐르네-<br/>쓴 물 거쳐 이 곳에 왔네- 사랑의 엘림에 왔다네-<br/>하늘에서 흐르는 샘물- - 내안에서 솟아나와-<br/>말로 다 못할 기쁨의 샘- 주님 나에게 가져 왔네-<br/>',NULL,28896,1);
INSERT INTO stanza VALUES('K1028','chorus','이 생명의 샘으로 오라 마르지 않는 샘으로-<br/>흐르는- 샘 그리스도를 마시어 공급 얻으라<br/>',NULL,28897,2);
INSERT INTO stanza VALUES('K1028','2','나는 보혈의 샘에 왔네 죄와 허물 씻기 원해<br/>그 곳에서 죄를 씻었네- 이제 내 옷은 희어졌네<br/>나의 의는 가치가 없지만 주님 나의 의 되시오니<br/>이제 주님의 신성을 나눠 그 안에서 온전케 되리<br/>',NULL,28898,3);
INSERT INTO stanza VALUES('K1028','3','나는 치료의 샘에 왔네 비길데 없는 공급돼<br/>재물로도 지식으로도- 찾거나 살 수 없는 샘물<br/>주가 나에게 주신 비밀- 창에 찔려 흘리신 샘물<br/>그 상처 인해 치료함 받고 내 안에 주님 모시었네<br/>',NULL,28899,4);
INSERT INTO stanza VALUES('K1028','4','나는 기쁨의 샘에 왔네 내 마음의 참된 능력<br/>순수하게 주님만 누릴 때 내게 참된 빛 비취리라<br/>풀은 마르고 시들어도- 세상 쾌락도 지나가도<br/>나의 샘은 마르지 않아- 거룩한 기쁨의 분깃 돼<br/>',NULL,28900,5);
INSERT INTO stanza VALUES('K1029','1','자신 버린 주 안에서 하나님 기쁨 얻네<br/>이 땅에서 사신 그 길 하나님 만족하네<br/>다만 하나님 뜻대-로 우리 주님 사셨네<br/>우리 또한 자신 바쳐 주님 살아 내겠네<br/>',NULL,28901,1);
INSERT INTO stanza VALUES('K1029','2','죽임당한 어린 양께 감사 찬송 드리세<br/>하나님의 만족 위해 태워지신 제물 돼<br/>하나님께 바친 제-물 우릴 위한 어린 양<br/>주의 헌신 주의 생활 우리로 본받게 해<br/>',NULL,28902,2);
INSERT INTO stanza VALUES('K1029','3','주님 자신 먹음으로 우리 또한 헌신해<br/>주의 순종 우리 안에 깊이 새겨졌으니<br/>우리 오늘 헌신함-은 강요 때문 아닐세<br/>우리 안의 주님 자신 바로 헌신이시니<br/>',NULL,28903,3);
INSERT INTO stanza VALUES('K1029','4','양식이신 주님께서 우리 헌신 되셨네<br/>주님 누려 하나 되는 참되고 굳센 연합<br/>주의 뜻과 주의 계-획 나의 것이 됐으니<br/>주님 먹고 누림으로 헌신할 수 있겠네<br/>',NULL,28904,4);
INSERT INTO stanza VALUES('K103','1','내 대-신 죽으신 예수 그 부-활 나는 기다려<br/>내 죄-악 주를 붙들고 주 속-박하지 않-았나<br/>',NULL,28905,1);
INSERT INTO stanza VALUES('K103','2','내 죄-가 너무 많아서 다 용-서할 수 없는가<br/>주 보-혈로 내 모든 것 다 포-함하지 못-하나<br/>',NULL,28906,2);
INSERT INTO stanza VALUES('K103','3','외치-세 주의 부활을 주 영-광 증가되었네<br/>주 어-둠에 들어가사 어둠-의 권세 없-앴네<br/>',NULL,28907,3);
INSERT INTO stanza VALUES('K103','4','하나-님 공의 만족됨 부활-로 증명하셨네<br/>하나-님 큰 사랑으로 주 이-미 구속 이-뤘네<br/>',NULL,28908,4);
INSERT INTO stanza VALUES('K103','5','피 흘-려 이룬 구속을 하나-님 확증하셨네<br/>할렐-루야 정결케 돼 할렐-루야 사함- 받아<br/>',NULL,28909,5);
INSERT INTO stanza VALUES('K1030','1','주 만찬에 모여서 함께 누리니<br/>우리 모두 하나됨 간증하네<br/>주를 먹고 마시며 주의 축복 누려<br/>여기서 우리 하나된 것 증거하네<br/>',NULL,28910,1);
INSERT INTO stanza VALUES('K1030','2','주 당신의 찢긴 몸 떡으로 먹어<br/>그 유일한 주의 몸 누린다네<br/>그 상 위에 놓여진 단 하나의 떡은<br/>주께서 우릴 한 몸으로 만든 증거<br/>',NULL,28911,2);
INSERT INTO stanza VALUES('K1030','3','축복의 잔 마시며 교통 누리네<br/>그리스도 흘리신 피로 인해<br/>믿음으로 영접해 거듭난 우리들<br/>하나님 앞에 나와 그를 누린다네<br/>',NULL,28912,3);
INSERT INTO stanza VALUES('K1030','4','우리들은 외치네 오 할렐루야<br/>그런 실재 그 누림 은혜 인해<br/>그의 피를 적용해 몸을 누릴 때에<br/>주님은 그의 영광스런 교회 얻네<br/>',NULL,28913,4);
INSERT INTO stanza VALUES('K1031','1','주 예수여 당신의 상에 모여 포도주와 떡<br/>바라봅니다 모든 사람 누릴 수 있게 하려<br/>음식 되신 주 찬양합니다<br/>',NULL,28914,1);
INSERT INTO stanza VALUES('K1031','chorus','우리 안에서 주님께 찬양 작은 주님<br/>먹기 좋네 언제까지나 주님 먹으리<br/>먹기 좋은 작은 주님<br/>',NULL,28915,2);
INSERT INTO stanza VALUES('K1031','2','그의 생명 분배하려 했을 때 사람들은<br/>교훈 더 원했네 생명 풍성 부요를 원치 않아<br/>얼마나 어리석은 일인가<br/>',NULL,28916,3);
INSERT INTO stanza VALUES('K1031','chorus','우린 주님을 다만 먹겠네 뛰어난 주<br/>영광의 주 새롭게 하는 주님 먹을 때<br/>주님으로 충만하리<br/>',NULL,28917,4);
INSERT INTO stanza VALUES('K1031','3','주 예수는 사람들 밖에 서서 다스리시려<br/>오지 않았네 배고픔을 채우는 양식 되어<br/>생명으로서 인도하시네<br/>',NULL,28918,5);
INSERT INTO stanza VALUES('K1031','4','우리 모두 주님을 찬양하세 광대하심과<br/>위엄과 권능 크신 은혜 풍성히 주신다네<br/>우리는 그를 먹을 수 있네<br/>',NULL,28919,6);
INSERT INTO stanza VALUES('K1032','1','그 어린 주 예수 눌 자리 없어<br/>그 귀하신 몸이 구유에 있네<br/>저 하늘의 별들 반짝이는데<br/>그 어린 주 예수 꼴 위에 자네<br/>',NULL,28920,1);
INSERT INTO stanza VALUES('K1032','2','저 육축 소리에 아기 잠깨나<br/>그 순하신 예수 우시지 않네<br/>귀하신 예수를 나 사랑하니<br/>새 날이 밝도록 함께하소서<br/>',NULL,28921,2);
INSERT INTO stanza VALUES('K1032','3','주 예수 내 곁에 가까이 계셔<br/>그 한없는 사랑 늘 베푸시고<br/>온 세상 사람들 다 품어 주사<br/>주 품 안에 안겨 살게 하소서<br/>',NULL,28922,3);
INSERT INTO stanza VALUES('K1033','1','십자가 지시고 죽은 주 하나님 만족게 하였네<br/>그 피로 내 죄를 씻었네 주께 영광을<br/>',NULL,28923,1);
INSERT INTO stanza VALUES('K1033','chorus','주께 영광을- 주께 영광을-<br/>그 피로 내 죄를 씻었네 주께 영광을<br/>',NULL,28924,2);
INSERT INTO stanza VALUES('K1033','2','우리는 죄에서 구원돼 값없이 구속을 누리네<br/>영원한 기업을 주시니 주께 영광을<br/>',NULL,28925,3);
INSERT INTO stanza VALUES('K1033','3','예수님 죽으신 그 사실 우리 빚 다 갚아 주셨네<br/>그 생명 분배해 주셨네 주께 영광을<br/>',NULL,28926,4);
INSERT INTO stanza VALUES('K1033','chorus','주께 영광을- 주께 영광을-<br/>그 생명 분배해 주셨네 주께 영광을<br/>',NULL,28927,5);
INSERT INTO stanza VALUES('K1033','4','피로써 정결케 되었네 생명수 기쁨을 주었네<br/>생명과 구속을 누리니 주께 영광을<br/>',NULL,28928,6);
INSERT INTO stanza VALUES('K1034','1','나 속죄함을 받은 후 한없는 기쁨을<br/>다 헤아릴 수 없어서 늘 찬송 합니다<br/>',NULL,28929,1);
INSERT INTO stanza VALUES('K1034','chorus','나 속죄받은 후 나 속죄받은 후<br/>주를 찬미하겠네 나 속죄받은 후<br/>주의 이름 찬미하겠네<br/>',NULL,28930,2);
INSERT INTO stanza VALUES('K1034','2','나 속죄함을 받은 후 내 맘이 새로워<br/>주 뜻을 준행하면서 죄 길을 버리네<br/>',NULL,28931,3);
INSERT INTO stanza VALUES('K1034','3','나 속죄함을 받은 후 성령이 오셔서<br/>하나님 자녀된 것을 곧 증거합니다<br/>',NULL,28932,4);
INSERT INTO stanza VALUES('K1034','4','나 속죄함을 받은 후 보혈의 공로로<br/>내 주의 은혜 입으니 늘 평안합니다<br/>',NULL,28933,5);
INSERT INTO stanza VALUES('K1035','1','겟세마네 동산의 주를 생각할 때에<br/>근심이 나 걱정을 사양할 수 있을까<br/>나를 항상 버리고 주를 따라가겠네<br/>',NULL,28934,1);
INSERT INTO stanza VALUES('K1035','2','빌라도의 뜰에선 주를 생각할 때에<br/>수치됨과 아픈 것 못 견딜 수 있을까<br/>길이 참고 묵묵히 주를 따라가겠네<br/>',NULL,28935,2);
INSERT INTO stanza VALUES('K1035','3','갈보리산 올라간 주를 생각할 때에<br/>나의 받는 괴로움 비교할 수 없으리<br/>십자가를 짐으로 주를 따라가겠네<br/>',NULL,28936,3);
INSERT INTO stanza VALUES('K1035','4','무덤에서 부활한 주를 생각할 때에<br/>환난이나 죽음도 두려울 것 없으리<br/>승전가를 부르며 주를 따라가겠네<br/>',NULL,28937,4);
INSERT INTO stanza VALUES('K1036','1','오랫동안 모든 죄 가운데 빠져 더럽기가 한량없던 우리들<br/>아무공로 없이 구원함을 얻어 하나님의 자녀 지금되었네<br/>',NULL,28938,1);
INSERT INTO stanza VALUES('K1036','chorus','주의 그사랑 한량없도다 찬송할지어다 예수의 공로<br/>주의 그사랑 한량없도다 찬송할지어다 예수의 공로<br/>',NULL,28939,2);
INSERT INTO stanza VALUES('K1036','2','주의 보혈로써 정결하게 씻어 죄악에서 떠난 몸이 되었고<br/>세상근심구름 간곳 없어지니 하나님의 빛이 영화롭도다<br/>',NULL,28940,3);
INSERT INTO stanza VALUES('K1036','3','죄의 깊은 잠과 뜬 세상의 꿈을 어서 깰지어다 나의 친구여<br/>은혜받을 날과 구원얻을 때가 지금 온 세상에 선포되었네<br/>',NULL,28941,4);
INSERT INTO stanza VALUES('K1037','1','면류관 씌우세 보좌의 어린 양<br/>저 천사 기쁜 노래가 온 땅에 퍼지네<br/>내 혼아 깨어나 주 찬송하여라<br/>온 백성 죄를 속하신 만왕의 왕이라<br/>',NULL,28942,1);
INSERT INTO stanza VALUES('K1037','2','면류관 씌우세 사랑의 주 예수<br/>그 손과 몸의 상처가 영광 중 빛난다<br/>하늘의 천사도 그 영광 보고서<br/>고난의 신비 알고자 늘 흠모하도다<br/>',NULL,28943,2);
INSERT INTO stanza VALUES('K1037','3','면류관 씌우세 평화의 주 예수<br/>온 세상 전쟁 그치고 참 평화 오리라<br/>주 보좌 앞에서 온 백성 엎드려<br/>그 한량 없는 영광을 늘 찬송하겠네<br/>',NULL,28944,3);
INSERT INTO stanza VALUES('K1038','1','은혜가 풍성한 하나님은 믿는 자 한 사람 한 사람<br/>어제나 오늘도 언제든지 변찮고 보호해 주시네<br/>',NULL,28945,1);
INSERT INTO stanza VALUES('K1038','chorus','주여 성령의 은사들을 오늘도 내리어 줍소서<br/>성령의 뜨거운 불길로써 오늘도 충만케 합소서<br/>',NULL,28946,2);
INSERT INTO stanza VALUES('K1038','2','정욕과 죄악의 물든 맘을 성령의 불길로 태우사<br/>정결케 합소서 태우소서 깨끗게 하여 주옵소서<br/>',NULL,28947,3);
INSERT INTO stanza VALUES('K1038','3','희생의 제물로 돌아가신 우리 주 예수님이시여<br/>구속의 은혜를 내리시사 오늘도 구원해 줍소서<br/>',NULL,28948,4);
INSERT INTO stanza VALUES('K1038','4','주님의 깊으신 은혜만을 세상에 널리 전하리라<br/>하늘의 능력과 권세로써 오늘도 입혀 주옵소서<br/>',NULL,28949,5);
INSERT INTO stanza VALUES('K1039','1','예수 나를 오라 하네 예수 나를 오라 하네<br/>어디든지 주를 따라 주와 같이 같이 가려네<br/>',NULL,28950,1);
INSERT INTO stanza VALUES('K1039','chorus','주의 인도하심 따라 주의 인도하심 따라<br/>어디든지 주를 따라 주와 같이 같이 가려네<br/>주께서 사랑하는<br/>',NULL,28951,2);
INSERT INTO stanza VALUES('K1039','2','겟세마네 동산까지 주와 함께 가려 하네<br/>피땀 흘린 동산까지 주와 함께 함께 가려네<br/>',NULL,28952,3);
INSERT INTO stanza VALUES('K1039','3','심판하실 자리까지 주와 함께 가려 하네<br/>심판하실 자리까지 주와 함께 함께 가려네<br/>',NULL,28953,4);
INSERT INTO stanza VALUES('K1039','4','주가 크신 은혜 내려 나를 항상 돌아보고<br/>많은 영광 보여 주며 나와 함께 함께 가시네<br/>',NULL,28954,5);
INSERT INTO stanza VALUES('K1039','1','주께서 사랑하는 귀한 청소년들<br/>택하여 거룩게 된 사랑스런 자들<br/>주여 당신의 회복 장래를 위하여<br/>견고히 교회 안에 심어 주옵소서<br/>',NULL,28955,6);
INSERT INTO stanza VALUES('K1039','2','이러한 조망갖고 힘써 기도하며<br/>섬기고 수고하며 돌보게 하소서<br/>하나님 분량으로 부담을 가지고<br/>이상을 저들에게 주게 하옵소서<br/>',NULL,28956,7);
INSERT INTO stanza VALUES('K1039','3','당신의 회복 위해 교회 생활 위해<br/>저들을 보존하여 기둥삼으소서<br/>당신의 회복위해 청소년들 위해<br/>인내로 이 부담을 실행케 하소서<br/>',NULL,28957,8);
INSERT INTO stanza VALUES('K104','1','내 주는 죄의 독 없었지만 사망의 영토로 들어 갔네<br/>사망 권세 잡은 마귀를 멸하여 사람을 못 가두-게 하셨네<br/>',NULL,28958,1);
INSERT INTO stanza VALUES('K104','2','무덤을 뚫고서 부활한 주 죽음도 내 주님 묶지 못해<br/>길고 어둔 무덤 걸어 나오셨네 죽음의 그늘 다- 제해졌네<br/>',NULL,28959,2);
INSERT INTO stanza VALUES('K104','3','당신의 능력의 승리로써 하나님께 영광 돌리시고<br/>믿는 이들 안에 거처 정하시니 그들은 당신 인해 살아가네<br/>',NULL,28960,3);
INSERT INTO stanza VALUES('K104','4','당신은 맨 처음 열매시요 하나님 사랑의 맏아들로<br/>날 인도하시는 내 으뜸이시니 영광과 존귀 받기 합당하셔<br/>',NULL,28961,4);
INSERT INTO stanza VALUES('K1040','1','주의 사랑 비췰 때에 기쁨 오네<br/>근심 걱정 물러 가고 기쁨 오네<br/>기도하게 하시며 희미한 것 물리쳐<br/>주의 사랑 비췰 때 기쁨 오네<br/>',NULL,28962,1);
INSERT INTO stanza VALUES('K1040','chorus','그 큰 사랑 내 맘 속에<br/>명랑하게 비췰 때에 찬송하네<br/>그 큰 사랑 내 맘 속에<br/>화평함과 기쁨 주네 그 큰 사랑<br/>',NULL,28963,2);
INSERT INTO stanza VALUES('K1040','2','주의 사랑 비췰 때에 이 세상은<br/>아름답고 활기차게 다 변하네<br/>화평 중에 내 영혼 영광스런 새 생명<br/>다시 찾게 되었네 그 큰 사랑<br/>',NULL,28964,3);
INSERT INTO stanza VALUES('K1040','3','주의 사랑 비췰 때에 이 세상은<br/>어둠 슬픔 중한 짐이 다 없겠네<br/>우리들의 가는 길 밝히 비춰 주시며<br/>복음 받게 하시네 그 큰 사랑<br/>',NULL,28965,4);
INSERT INTO stanza VALUES('K1041','1','우리 다시 만날 때까지 하나님이 함께 계셔<br/>훈계로써 인도하며 도와 주시기를 바라네<br/>',NULL,28966,1);
INSERT INTO stanza VALUES('K1041','chorus','다시 만날 때 다시 만날 때 예수 앞에 만날 때<br/>다시 만날 때 다시 만날 때 그때까지 계심 바라네<br/>',NULL,28967,2);
INSERT INTO stanza VALUES('K1041','2','우리 다시 만날 때까지 하나님이 함께 계셔<br/>간데마다 보호하며 양식 주시기를 바라네<br/>',NULL,28968,3);
INSERT INTO stanza VALUES('K1041','3','우리 다시 만날 때까지 하나님이 함께 계셔<br/>위태한 일 면케 하고 품어 주시기를 바라네<br/>',NULL,28969,4);
INSERT INTO stanza VALUES('K1041','4','우리 다시 만날 때까지 하나님이 함께 계셔<br/>사망 권세 이기도록 지켜 주시기를 바라네<br/>',NULL,28970,5);
INSERT INTO stanza VALUES('K1042','1','감추인 생명 이는 하나님 그의 목적은 사람에 있네<br/>생명 나무로 사람 이끄사 하나님 생명 얻기 원했네<br/>',NULL,28971,1);
INSERT INTO stanza VALUES('K1042','2','사람은 뱀의 유혹에 빠져 죄 짓고 다른 근원 취했네<br/>지식의 열매 받아 들여서 그 권세 아래 지배당했네<br/>',NULL,28972,2);
INSERT INTO stanza VALUES('K1042','3','사람 안에서 지식 발전해 이 땅의 문화 이루어갔네<br/>하나님 계획 위한 사람이 전락해 사탄 도구 되었네<br/>',NULL,28973,3);
INSERT INTO stanza VALUES('K1042','4','하나님 사람 되어 오셔서 이 땅에 사신 그는 주 예수<br/>하나님 생명 인해 사신 주 모든 사람의 산 본 되셨네<br/>',NULL,28974,4);
INSERT INTO stanza VALUES('K1042','5','십자가에서 죽으심으로 옛 사람 지식 끝낸 주 예수<br/>소극적인 것 모두 끝냈네 사망도 그는 정복하셨네<br/>',NULL,28975,5);
INSERT INTO stanza VALUES('K1042','6','부활하신 주 마지막 아담 생명을 주는 영이 되셨네<br/>주 예수 믿고 이름 부를 때 그는 내 안에 오셔 거하네<br/>',NULL,28976,6);
INSERT INTO stanza VALUES('K1042','7','삼일 하나님 지금 내 안에 그 영광 내 영 연합되었네<br/>우리는 주와 하나 되었네 영원히 주와 하나 누리네<br/>',NULL,28977,7);
INSERT INTO stanza VALUES('K1042','8','온전히 영을 따라 행하네 영 안에 살며 보며 생각해<br/>놀라운 생활 영 안의 생활 하나님 충만 맘껏 누리네<br/>',NULL,28978,8);
INSERT INTO stanza VALUES('K1042','9','우리의 생각 그에게 두네 매 순간 생각 영 안에 두네<br/>이 영 인하여 구원 누리며 속 생명 인해 모두 정복해<br/>',NULL,28979,9);
INSERT INTO stanza VALUES('K1042','10','이 영 인하여 해방되겠네 죄와 사망의 법으로부터<br/>사망의 몸이 생명 얻겠네 범사에 거룩하여지겠네<br/>',NULL,28980,10);
INSERT INTO stanza VALUES('K1042','11','우리의 본성 변케 하는 영 자아로부터 우릴 구원해<br/>주님과 같은 형상 될 때에 하나님 계획 완성되겠네<br/>',NULL,28981,11);
INSERT INTO stanza VALUES('K1042','12','생명은 삼일 하나님 자신 유일한 길은 생명뿐일세<br/>몸 변형되어 구속될 날을 사모하면서 우린 기다려<br/>',NULL,28982,12);
INSERT INTO stanza VALUES('K1043','1','주는 나를 그의 몸에 넣어 하나의 지체 만드셨습니다<br/>난 지식의 나무 모든 것들을 떠나 생명의 나무 먹고 있다네<br/>그는 날 키우려 그의 농장에 뒀네 다만 우린 예수 사랑하므로<br/>여기에 하나로서 있을 뿐입니다 온 세상이 다 알게될 때까지<br/>주는 나를 그의 몸에 넣어 하나의 지체 만드셨습니다<br/>난 지식 나무 모든 것들을 떠나 생명의 나무 먹고 있다네<br/>',NULL,28983,1);
INSERT INTO stanza VALUES('K1043','2','주는 혼자 신령한 사람을 이제 더 이상 원치 않습니다<br/>그가 원하는 건 바로 한 새 사람 영원히 한 새 사람이라네<br/>우리 하나 되는 길은 오직 예수 그의 부요함이 넘칠 때까지<br/>주 예수를 먹고 마시고 호흡할 때 그는 우릴 모아 하나 만드네<br/>주는 혼자 신령한 사람을 이제 더 이상 원치 않습니다<br/>그가 원하는 건 바로 한 새 사람 영원히 한 새 사람이라네<br/>',NULL,28984,2);
INSERT INTO stanza VALUES('K1044','1','찬양하세 사랑으로 우리 죄를 씻은 주<br/>우린 그의 나라에서 왕과 같은- 제사장<br/>죽임 당한 어린 양께 영광 존귀 축복을<br/>',NULL,28985,1);
INSERT INTO stanza VALUES('K1044','2','영광 존귀 축복 찬양 우리 왕께 돌리세<br/>우리들을 지으신 주 존귀 능력- 권세라<br/>주님만이 찬양 받기 합당한 왕이실세<br/>',NULL,28986,2);
INSERT INTO stanza VALUES('K1044','3','영광 영광 천사의 왕 만왕의 왕 주님께<br/>열방의 왕 영광 돌려 천지여 찬미-하라<br/>영광의 왕 우리 주께 항상 영광 돌리세<br/>',NULL,28987,3);
INSERT INTO stanza VALUES('K1045','1','우리의 주 하나님은 목적 있는 하나님<br/>계획하신 것을 그는 반드시 다 이루네<br/>창세기서 계시록까지 온전한 그 뜻 말하네<br/>그의 중심 목적은 곧 생명과 건축일세<br/>',NULL,28988,1);
INSERT INTO stanza VALUES('K1045','2','그의 목적 이루려고 먼저 사람 지었네<br/>몸과 혼과 영이 있는 그릇으로 지었네<br/>흙을 빚어 사람- 지어 불어- 넣은 생기는<br/>하나님을 영접하는 사람의 영 되었네<br/>',NULL,28989,2);
INSERT INTO stanza VALUES('K1045','3','보기 좋고 먹기 좋은 나무들 나게 하니<br/>동산 안의 중앙에는 생명나무 있었네<br/>첫 사람이 자유-롭게 생명의 실과 먹을 때<br/>사람은 곧 담게 되네 하나님의 생명을<br/>',NULL,28990,3);
INSERT INTO stanza VALUES('K1045','4','에덴에서 발원한 강 동산을 다 적시고<br/>동서남북 나뉘어져 네 근원이 되었네<br/>생명이신 그리-스도 우리- 안에 흐르듯<br/>할렐루야 이 강물이 생수 공급한다네<br/>',NULL,28991,4);
INSERT INTO stanza VALUES('K1045','5','강물 흘러 가는 곳에 금과 진주 호마노<br/>보석들이 나온다네 그의 건축 위하여<br/>주로 인해 영으로 인해 매일- 변화될 때에<br/>우리들도 그와 같이 보석되어 간다네<br/>',NULL,28992,5);
INSERT INTO stanza VALUES('K1045','6','하나님 아버지는 곧 거룩한 정금이요<br/>아들은 곧 상처 받아 진주 되신 주 예수<br/>성령은 흙 변화-시켜 돌들- 만들어내네<br/>영의 흐름 그 안에서 우린 매일 변화돼<br/>',NULL,28993,6);
INSERT INTO stanza VALUES('K1045','7','주의 성분 더하므로 재료들 준비되어<br/>하나로 다 건축될 때 하나님의 집 이뤄<br/>그의 처소 건축- 위해 우리- 자신 드려서<br/>지방마다 나타내네 하나님의 안식처<br/>',NULL,28994,7);
INSERT INTO stanza VALUES('K1045','8','마지막 곧 계시록에 주의 신부 보이네<br/>이는 우리 하나님의 목적의 완성일세<br/>신랑의 짝 새 예루살렘 그를- 만족게 하네<br/>이는 바로 그리스도가 고대하던 신불세<br/>',NULL,28995,8);
INSERT INTO stanza VALUES('K1045','9','그의 목적 이루려면 상합하고 연합해<br/>혼의 생명 부인하고 영 안에서 주 누려<br/>그를 우리 생명-으로 매일- 먹고 마실 때<br/>그가 우릴 변화시켜 그의 신부 만드네<br/>',NULL,28996,9);
INSERT INTO stanza VALUES('K1046','1','내 영광 내 머리를 드는 주 내 영광 내 머리를 드는 주<br/>오 주 나의 방패 내 영광- 내 머리를 드는 분일세<br/>목소리 높여 주께 소리쳤네- 목소리 높여 주께 외쳤네-<br/>목소리 높여 주께 소리쳤네- 그 성산서 응답하시리<br/>내 영광 내 머리를 드는 주 내 영광 내 머리를 드는 주<br/>오 주 나의 방패 내 영광- 내 머리를 드는 분일세<br/>',NULL,28997,1);
INSERT INTO stanza VALUES('K1047','1','경륜따라 하나님 육신 입고 오셨네<br/>사람으로 사시고 죽고 부활 하셨네<br/>',NULL,28998,1);
INSERT INTO stanza VALUES('K1047','chorus','경륜을 거친 그는 지금 영 난 조성되네 삼일 하나님으로<br/>',NULL,28999,2);
INSERT INTO stanza VALUES('K1047','2','연합되신 성육신 모두 끝낸 십자가<br/>새 시작의 부활로 이제 주만 사시네<br/>',NULL,29000,3);
INSERT INTO stanza VALUES('K1047','3','성육신 되심으로 인생 거친 주 예수<br/>죽고 부활함으로 생명 나눠 주셨네<br/>',NULL,29001,4);
INSERT INTO stanza VALUES('K1048','1','오 친구여 외롭고 괴로울 때 예-수 예-수<br/>거기 계신다 근심과 혼란의 밤 닥칠 때<br/>예-수 예-수 빛 되신다 깊은 속에서 주 향해<br/>맘 돌이킬 때 주께서 모든 짐 가져가신다<br/>네 자신의 어떠함 부인하고 예-수 예-수 그를 누려<br/>',NULL,29002,1);
INSERT INTO stanza VALUES('K1048','2','어떤 환경 어떤 일 닥쳐와도 예-수 예-수<br/>여기 계신다 이 세상 괴로움 몰려올 때<br/>예-수 예-수 그를 누려 깊은 속에서<br/>주님을 부를 때 그는 반드시 구원해 신실하신 주님<br/>이 세상 염-려 몰려올 때 다-만 불-러 주- 예수<br/>',NULL,29003,2);
INSERT INTO stanza VALUES('K1049','1','언제든지 부를 때면 가까우신 주<br/>그가 우리 깊은 속을 강건케 하네<br/>그를 불러 찾을 때에 찾으리로다<br/>오 그의 이름 부를 때에 평강 넘치네<br/>',NULL,29004,1);
INSERT INTO stanza VALUES('K1049','chorus','예수 귀한 이름 생명 주는 이름일세<br/>승리하신 영광 얻은 높이 들린 이름일세<br/>힘을 주는 이름 안위하는 이름일세<br/>어디서든지 불러 호흡해<br/>오 주 예수 놀라운 주<br/>',NULL,29005,2);
INSERT INTO stanza VALUES('K1049','2','오 주 예수 부를 때에 구원받겠네<br/>오 주 예수 할렐루야 해방되겠네<br/>그를 불러 구원의 잔 함께 누릴 때<br/>오 만유의 주 그로부터 구원이 오네<br/>',NULL,29006,3);
INSERT INTO stanza VALUES('K1049','3','유대인과 헬라인의 차별이 없네<br/>한 주께서 모든 사람 주가 되시어<br/>그의 이름 부르는 자 부요케 하네<br/>오, 그의 이름 호흡할 때 기쁨 넘치네<br/>',NULL,29007,4);
INSERT INTO stanza VALUES('K1049','4','구원의 하나님 안에 즐거움 넘쳐<br/>항상 그를 부를 때에 빛이 충만해<br/>끝날까지 부르겠네 달콤한 이름<br/>주 귀 기울여 듣고 은혜 넘치게 주리<br/>',NULL,29008,5);
INSERT INTO stanza VALUES('K1049','5','찬송받기 합당하신 우리 주님께<br/>감사하는 마음으로 찬양 드리리<br/>우리들은 각처에서 주를 부르는 자<br/>깨끗한 맘으로 함께 주를 부르네<br/>',NULL,29009,6);
INSERT INTO stanza VALUES('K105','1','할렐루야 부활한 주 높은 하늘 올랐네<br/>죽음의 문 빗장 열고 주님 승리하셨네<br/>부활한 주 오늘 살아 우리 생명되셨네<br/>부활한 주 오늘 살아 우리 생명되셨네<br/>',NULL,29010,1);
INSERT INTO stanza VALUES('K105','2','할렐루야 부활한 주 만주의 주 되셨네<br/>성령 내려 증거하고 모든 소유 주셨네<br/>나를 의롭다 하시며 구원하여 주셨네<br/>나를 의롭다 하시며 구원하여 주셨네<br/>',NULL,29011,2);
INSERT INTO stanza VALUES('K105','3','할렐루야 부활한 주 사망 세력 이겼네<br/>부활이신 그리스도 우릴 죽음서 건져<br/>부활한 주 항상 살아 우리 은사 되시네<br/>부활한 주 항상 살아 우리 은사 되시네<br/>',NULL,29012,3);
INSERT INTO stanza VALUES('K1050','1','나가네 나가네 나가네 내 맘 속의 정죄는 나가네<br/>나가네 나가네 나가네 내 맘 속의 정죄는 나가네<br/>모든 죄 나가네 주님 흐를 때<br/>나가네 나가네 내 맘 속의 정죄는 나가네<br/>',NULL,29013,1);
INSERT INTO stanza VALUES('K1050','2','나가네 나가네 나가네 나의 모든 공상은 나가네<br/>나가네 나가네 나가네 나의 모든 공상은 나가네<br/>헛된 꿈 나가네 주님 흐를 때<br/>나가네 나가네 나가네 나의 모든 공상은 나가네<br/>',NULL,29014,2);
INSERT INTO stanza VALUES('K1050','3','나가네 나가네 나가네 변덕 많은 감정은 나가네<br/>나가네 나가네 나가네 변덕 많은 감정은 나가네<br/>옛 자아 나가네 주님 흐를 때<br/>나가네 나가네 나가네 변덕 많은 감정은 나가네<br/>',NULL,29015,3);
INSERT INTO stanza VALUES('K1050','4','나가네 나가네 나가네 거스리던 의지는 나가네<br/>나가네 나가네 나가네 거스르던 의지는 나가네<br/>내 자아 나가네 주님 흐를 때<br/>나가네 나가네 나가네 거스르던 의지는 나가네<br/>',NULL,29016,4);
INSERT INTO stanza VALUES('K1050','5','나가네 나가네 나가네 자신 높이려는 맘 나가네<br/>나가네 나가네 나가네 자신 높이려는 맘 나가네<br/>내 원함 나가네 주님 흐를 때<br/>나가네 나가네 나가네 자신 높이려는 맘 나가네<br/>',NULL,29017,5);
INSERT INTO stanza VALUES('K1050','6','찬양해 주님만 흐르네 내 맘 속의 샘에서 흐르네<br/>찬양해 주님만 흐르네 내 맘 속의 샘에서 흐르네<br/>맘 활짝 열 때에 주님 흐르네<br/>찬양해 주님만 흐르네 내 맘 속의 샘에서 흐르네<br/>',NULL,29018,6);
INSERT INTO stanza VALUES('K1051','1','영으로서 영으로 난 예수 근원 영일세<br/>영에 충만 영의 전부 예수 본질 영일세<br/>영 안에서 영과 함께 영으로서 오셨네<br/>이제 주님 영이시며 영에 나와 하날세<br/>',NULL,29019,1);
INSERT INTO stanza VALUES('K1051','2','성령 안에 침례 받아 그 영 안에 잠겼네<br/>영으로서 교회 나고 모든 종교 끝났네<br/>영 안에서 영 안에서 그 영만이 필요해<br/>교회 안에 영만 있고 교리 필요 없다네<br/>',NULL,29020,2);
INSERT INTO stanza VALUES('K1051','3','영의 교통 우리 서로 함께 나누는 교통<br/>모든 형제 모든 자매 다만 영을 관심해<br/>이제 영은 교회 안에 우리 향해 말씀해<br/>교회 위한 일곱 영이 우리들의 몫일세<br/>',NULL,29021,3);
INSERT INTO stanza VALUES('K1051','4','오라, 생명수를 마셔 영과 신부 말하네<br/>영과 교회 일치되어 연합하여 말하네<br/>영을 따라 행동함을 우리 실재로 삼고<br/>교회 안에 그 영 외에 주의 회복 없으리<br/>',NULL,29022,4);
INSERT INTO stanza VALUES('K1052','1','좋은 땅 예수를 경작하세 밭 갈며 심고 또 물을 줄 때<br/>실재의 소산이 생산되고 내 안에 수확을 거두겠네<br/>',NULL,29023,1);
INSERT INTO stanza VALUES('K1052','chorus','예수 좋은 이 땅을 나 경작하겠네 곳곳을<br/>점령하여 완전히 얻으리 주님 목적은 이 땅 경작<br/>축복하리 주 예수 자신 얻어서 주만 소유하리<br/>',NULL,29024,2);
INSERT INTO stanza VALUES('K1052','2','결심해 예수를 경작하세 경작 시작 후 나 후회 없어<br/>경작을 할 때 비 내려오고 주님의 소산 내 획득일세<br/>',NULL,29025,3);
INSERT INTO stanza VALUES('K1052','3','실재로 예수를 경작하세 영 안에 말씀 기도로 읽고<br/>그의 산 인도를 따라갈 때 건축을 하며 또 교회 얻네<br/>',NULL,29026,4);
INSERT INTO stanza VALUES('K1052','4','경작해 실재를 생산하세 집회서 충만을 볼 수 있게<br/>주님과 사람 다 만족하고 하나님 임재 늘 함께하니<br/>',NULL,29027,5);
INSERT INTO stanza VALUES('K1052','5','주님이 확장케 경작하세 주님의 집에서 잔치하며<br/>넘치는 농작물 주께 바쳐 풍성함 먹고서 기뻐하리<br/>',NULL,29028,6);
INSERT INTO stanza VALUES('K1053','1','제일 좋은 나의 친구 그 이름 주 예수<br/>아름답고 나의 모든 것 되네<br/>내- 모든 필요함과 신선한 공급은<br/>모두 주 안에서 채워진다네<br/>아플 때 위로하며 시험을 당할 때<br/>내- 짐을 주가 담당하시니<br/>내- 주는 나의 신랑 빛나는 새벽별<br/>만인 중에 가장 뛰어난 사랑<br/>',NULL,29029,1);
INSERT INTO stanza VALUES('K1053','2','내- 아픔 담당하고 슬픔을 나누며<br/>유혹당할 때에 안전한 망대<br/>모-든 것 내려 놓고 우상을 버리니<br/>내 안에서 강한 능력 되시네<br/>세상의 배척 받고 시험을 당해도<br/>예-수로 인해 푯대 향하리<br/>내- 주는 나의 신랑 빛나는 새벽별<br/>만인 중에 가장 뛰어난 사랑<br/>',NULL,29030,2);
INSERT INTO stanza VALUES('K1053','3','날- 항상 버리잖고 열납해 주시니<br/>믿음으로 살며 그 뜻 따르리<br/>불- 시험 당할 때도 두려움 없겠네<br/>만-나로 내게 공급하시니<br/>영광에 들림 받아 주 얼굴 뵈오리<br/>그- 때에 내 맘 기쁨 넘치리<br/>내- 주는 나의 신랑 빛나는 새벽별<br/>만인 중에 가장 뛰어난 사랑<br/>',NULL,29031,3);
INSERT INTO stanza VALUES('K1054','1','화목제 되신 주께 내 손 안수하네<br/>주님과 하나일세 사실과 실재로<br/>회막서 하나님께 주님을 드려서<br/>주님을 아버지와 먹으며 누리세<br/>',NULL,29032,1);
INSERT INTO stanza VALUES('K1054','chorus','화목이신 그리스도 우리 주 찬양해<br/>하나님과 우리의 화목 회복되었다<br/>',NULL,29033,2);
INSERT INTO stanza VALUES('K1054','2','피 뿌려짐 볼 때에 어떤 평강인가<br/>제물의 피흘림이 화목게 했으니<br/>원수를 향해 말해 두려움이 없이<br/>“주 예수 피로 인해 화목되었다”고<br/>',NULL,29034,3);
INSERT INTO stanza VALUES('K1054','3','태워진 제물 되어 소제가 됨으로<br/>화목제 되신 예수 하나님께 드려<br/>더욱더 주를 먹고 마심으로 인해<br/>성도들과 다 함께 잔치를 누리자<br/>',NULL,29035,4);
INSERT INTO stanza VALUES('K1054','4','감추인 달콤함을 하나님 누리고<br/>모든 제사장들은 가슴 부분 먹고<br/>드리는 제사장은 더 좋은 것으로<br/>거제와 더불어서 유교병 취한다<br/>',NULL,29036,5);
INSERT INTO stanza VALUES('K1054','chorus','하나님과 사람들의 놀라운 이 교통<br/>주님의 백성 잔치하며 기뻐하여라<br/>',NULL,29037,6);
INSERT INTO stanza VALUES('K1054','5','사랑의 가슴 부분 누리는 이 기쁨<br/>부활한 그리스도 우릴 초월케 해<br/>거제로 드린 제물 승천의 힘 되니<br/>떡 먹고 힘을 얻어 주의 뒤 좇으리<br/>',NULL,29038,7);
INSERT INTO stanza VALUES('K1054','6','다 함께 그리스도 부요함 누리자<br/>진정한 교통함이 집회에 있도록<br/>낙헌제 가져오고 서원제 드려서<br/>주님과 교회 위해 자신을 바치자<br/>',NULL,29039,8);
INSERT INTO stanza VALUES('K1055','1','우릴 창조하신 주 우리에게 부탁해<br/>우리는 아멘하며- 섬기세<br/>교회를 건축함이 우리의 목표이니-<br/>일어나서 다 함께- 섬기세<br/>',NULL,29040,1);
INSERT INTO stanza VALUES('K1055','chorus','섬기세 섬-기세 왕 같은 제사장들아 섬기세<br/>전엔 드릴 것 없는 헛된 삶이었지만-<br/>이제 섬기란 주 음성들었네<br/>',NULL,29041,2);
INSERT INTO stanza VALUES('K1055','2','제사장인 우리들 성소만이 아니라<br/>휘장 가운데로 들어 가겠네<br/>모든 교통 가질 때 이상은 새롭게 돼-<br/>그 때 잔치 하면서- 섬기세<br/>',NULL,29042,3);
INSERT INTO stanza VALUES('K1055','3','주의 권위 주어져 왕의 자격 얻었네<br/>주의 정부 나라 모든 권세도<br/>그 영 운행하심을 방해할 것 없으니-<br/>승리는 우리의 것- 섬기세<br/>',NULL,29043,4);
INSERT INTO stanza VALUES('K1055','4','주님의 저 대적자 우릴 패배 못 시켜<br/>우리 항상 주님을- 섬길 때<br/>아말렉을 멸하고 그의 것은 거절해-<br/>기도하며 깨어서- 섬기세<br/>',NULL,29044,5);
INSERT INTO stanza VALUES('K1056','1','생생-한 생-명 느낌 있네 우리가 살- 동안<br/>영원한 생명의- 느낌- 참 거-룩한- 느낌<br/>',NULL,29045,1);
INSERT INTO stanza VALUES('K1056','2','그 생-명 고-귀할-수록 느낌-도 고-상해<br/>거룩한 생명의- 느낌- 참 뛰-어난 느낌<br/>',NULL,29046,2);
INSERT INTO stanza VALUES('K1056','3','그 살-아 있-는 느-낌은 하나-님 느낌일세<br/>우리의 영에 계시는 주님 선과- 악 능-가해<br/>',NULL,29047,3);
INSERT INTO stanza VALUES('K1056','4','그러-한 느-낌 주-는 것 양심-이 분별해<br/>하나님 기뻐하시는 것- 우리-로 알-게 해<br/>',NULL,29048,4);
INSERT INTO stanza VALUES('K1056','5','그 살-아 있-는 느-낌은 하나-님 알 -게 해<br/>우리의 노력 아 -니라- 계시-로 인-하여<br/>',NULL,29049,5);
INSERT INTO stanza VALUES('K1056','6','내적-인 생-명 성-장해 주 인-해 살-도록<br/>민감하고도 엄격하게- 그 느-낌 순-종해<br/>',NULL,29050,6);
INSERT INTO stanza VALUES('K1056','7','그러-한 느-낌 훈-련해 담대-해 지-도록<br/>그때에 하나님과의 교통 생생-해 지-리라<br/>',NULL,29051,7);
INSERT INTO stanza VALUES('K1057','1','생명의 주 오사 나로 충만케 해<br/>주님의 사랑하는 뜻 행하-게 하소서<br/>',NULL,29052,1);
INSERT INTO stanza VALUES('K1057','2','주 영 - 내게 불어 정결케 하소서<br/>주님의 뜻 내 뜻 되어 행하-게 하소서<br/>',NULL,29053,2);
INSERT INTO stanza VALUES('K1057','3','우리에게 불어 우리를 얻으사<br/>우리 안에 있는 세상 소멸-케 하소서<br/>',NULL,29054,3);
INSERT INTO stanza VALUES('K1057','4','우리에게 불어 사망 몰아내사<br/>온전히 영원한 생명 얻게- 하옵소서<br/>',NULL,29055,4);
INSERT INTO stanza VALUES('K1058','1','아버지여 당신- 자녀 경배 찬양 드립니다<br/>주 안에서 선택-하셔 거룩하게 하시-네<br/>당신 이름 높이-면서 아바 아버지 외-쳐<br/>아버지여 당신- 자녀 경배 찬양 드립니다<br/>',NULL,29056,1);
INSERT INTO stanza VALUES('K1058','2','보좌 위에 계신- 인자 경배 찬양 드립니다<br/>당신 백성 어린- 양께 가까이 나갑니-다<br/>아들이신 하나-님은 죽기 위해 오셨-네<br/>보좌 위에 계신- 인자 경배 찬양 드립니다<br/>',NULL,29057,2);
INSERT INTO stanza VALUES('K1058','3','성부 성자 성령-이여 경배 찬양드립니다<br/>목소리와 마음- 다해 후사됨을 찬양-해<br/>성 삼이일 하나-님은 찬양받기 합당-해<br/>성부 성자 성령-이여 경배 찬양드립니다<br/>',NULL,29058,3);
INSERT INTO stanza VALUES('K1059','1','주님을 진정 사랑합니다 드릴 것 없으나<br/>모든 사랑을 주께 바치리 주 안에 살면서<br/>난 아무것도 아닐지라도 비워서 주님 자신 채우리<br/>',NULL,29059,1);
INSERT INTO stanza VALUES('K1059','2','나에게 필요한 건 주님 뿐 비할 데 없도다<br/>강물이 흘러 내림과 같은 주님 주신 축복<br/>생명이 근원 흐르는 은혜 내 삶의 중심 샘물과 거처<br/>',NULL,29060,2);
INSERT INTO stanza VALUES('K106','1','영광 돌리세 부활하신 주님께<br/>죽음 뚫고 정복했네 승리하셨네<br/>흰옷 입은 천사 돌을 굴려 내었네<br/>그가 누우셨던 곳엔 세마포뿐였네<br/>',NULL,29061,1);
INSERT INTO stanza VALUES('K106','chorus','영광 돌리세 부활하신 주님께<br/>죽음 뚫고 정복했네 승리하셨네<br/>',NULL,29062,2);
INSERT INTO stanza VALUES('K106','2','부활한 주님 다-시- 오셨네<br/>숨-은- 제자들을 만나러 왔네<br/>죽-음-의 끈 끊고 다시 사신 주<br/>모-든- 성도 기뻐 찬미- 부르네<br/>',NULL,29063,3);
INSERT INTO stanza VALUES('K106','3','영광 돌리세 생-명-의 왕께<br/>주-의- 생명 얻고 사망 이기네<br/>부-활- 능력으로 넉넉히 이겨<br/>주-의- 나라 향해 나아- 가겠네<br/>',NULL,29064,4);
INSERT INTO stanza VALUES('K1060','1','나의 영 안에는 흐르는 샘 있네 삼일 하나님 흐르시네-<br/>원천은 아버지 아들은 솟는 샘 그 영은 내게 생명 주네-<br/>',NULL,29065,1);
INSERT INTO stanza VALUES('K1060','chorus','달콤한 흐름 사랑하리- 혼의 생명을 부인케 해-<br/>오 주여 더욱 흐르소서- 생명 면류관 얻기까지-<br/>',NULL,29066,2);
INSERT INTO stanza VALUES('K1060','2','푸른 초장에서 나는 쉼을 얻네 물가에서 난 안식하네-<br/>스스로의 힘과 헛된 노력 버려 흐름 가운데 축복 얻네-<br/>',NULL,29067,3);
INSERT INTO stanza VALUES('K1060','3','휘장에 들어가 주와 살게 하려 주님은 나를 부르셨네-<br/>주 음성 듣고서 주 안에 거하리 포도나무의 가지이니-<br/>',NULL,29068,4);
INSERT INTO stanza VALUES('K1061','1','내 혼아 잠잠하여라 아버지 나를 다루시니<br/>주 앞에 입을 다물고 원하시는 틀 모양 돼<br/>내 혼아 잠잠하여라 두려워 말고 손길 느껴<br/>십자가 지고 잠잠히 주님의 틀의 모양 될 때까지<br/>주 앞에 입을 다물고 원하시는 틀 모양 돼<br/>',NULL,29069,1);
INSERT INTO stanza VALUES('K1061','2','내 혼아 근심 말라는 주님의 음성 들으-라<br/>나는 하나님이-니 네 근심 내게 맡기라<br/>내 혼아 잠잠하여라 두려워 말고 손길 느껴<br/>십자가 지고 잠잠히 주님의 틀의 모양 될 때까지<br/>나는 하나님이-니 네 근심 내게 맡기라<br/>',NULL,29070,2);
INSERT INTO stanza VALUES('K1061','3','내 혼아 두려워 말라 담대하라고 말씀하네<br/>내니 두려워 말지라 너와 항상 같이 하리<br/>내 혼아 잠잠하여라 두려워 말고 손길 느껴<br/>십자가 지고 잠잠히 주님의 틀의 모양 될 때까지<br/>내니 두려워 말지라 너와 항상 같이 하리<br/>',NULL,29071,3);
INSERT INTO stanza VALUES('K1061','4','내 혼아 간구하여라 신실한 하나님에-게<br/>주의 뜻 순종하면서 인내와 소망 가지고<br/>내 혼아 잠잠하여라 두려워 말고 손길 느껴<br/>십자가 지고 잠잠히 주님의 틀의 모양 될 때까지<br/>주의 뜻 순종하면서 인내와 소망 가지고<br/>',NULL,29072,4);
INSERT INTO stanza VALUES('K1061','5','내 혼아 강건하여라 주님이 늦어지더라도<br/>지체치 않으시-고 머잖아 돌아오시리<br/>내 혼아 잠잠하여라 두려워 말고 손길 느껴<br/>십자가 지고 잠잠히 주님의 틀의 모양 될 때까지<br/>지체치 않으시-고 머잖아 돌아오시리<br/>',NULL,29073,5);
INSERT INTO stanza VALUES('K1062','1','선하신 목자 예수 날 우리서 구출했네<br/>풍부한 초장 가운데 사랑으로 인도해<br/>',NULL,29074,1);
INSERT INTO stanza VALUES('K1062','chorus','오 교-회 생활 풍성한 양식 있네<br/>여기서 하나 될 때에 영생을 명하시네<br/>',NULL,29075,2);
INSERT INTO stanza VALUES('K1062','2','분열과 공허로부터 주님 날 구하셨네<br/>좋은 땅으로 인도해 그 땅은 우리의 영<br/>',NULL,29076,3);
INSERT INTO stanza VALUES('K1062','3','예수는 우리의 초장 자양분 있는 음식<br/>우리가 모일 때마다 양떼를 먹이시네<br/>',NULL,29077,4);
INSERT INTO stanza VALUES('K1062','4','이슬이 내리는 산에 우리는 살고 있네<br/>샘에서 마음껏 마셔 갈증을 해소하네<br/>',NULL,29078,5);
INSERT INTO stanza VALUES('K1062','5','그리스도는 참 누림 안식과 보호이니<br/>주 손의 한 마리 양도 빼앗기지 않으리<br/>',NULL,29079,6);
INSERT INTO stanza VALUES('K1063','1','오 할렐루야 우리 모임은 주님의 승리<br/>전시하는 것 원수는 패배 수치 당하고<br/>우리는 해방되어 주님과 잔치하네<br/>',NULL,29080,1);
INSERT INTO stanza VALUES('K1063','2','하나님 백성 애굽 땅에서 종노릇할 때<br/>주님 말씀해 내 백성으로 가게 하여라<br/>바다를 건너 광야에서 잔치 누리라<br/>',NULL,29081,2);
INSERT INTO stanza VALUES('K1063','3','전능의 팔로 그들 인도해 뒤에는 원수<br/>쫓아오지만 주께서 바다에서 처리해<br/>백성은 마른 바다 건너가서 잔치해<br/>',NULL,29082,3);
INSERT INTO stanza VALUES('K1063','4','좋은 땅에서 잔치 계속돼 기업으로 주신<br/>산 위에서 하나님 처소 세우고 나서<br/>일 년에 삼차 주님께 절기를 지키네<br/>',NULL,29083,4);
INSERT INTO stanza VALUES('K1063','5','주님께 절기 지키기 위해 예루살렘으로<br/>가야 하리 모두가 가장 좋은 것으로<br/>주님이 정하신 곳에서 드려야 하네<br/>',NULL,29084,5);
INSERT INTO stanza VALUES('K1063','6','이제 우리들 세대에서는 절기의 실재<br/>누릴 수 있네 제물은 실재인 그리스도<br/>시온은 주님의 참 거처인 주의 교회<br/>',NULL,29085,6);
INSERT INTO stanza VALUES('K1063','7','그리스도는 참된 가나안 그 안에 모든<br/>부요함 있네 주님이 집회의 제물이요<br/>교회가 모일 때에 잔치하며 만족해<br/>',NULL,29086,7);
INSERT INTO stanza VALUES('K1063','8','오 거룩한 성 들어가겠네 생명나무와<br/>생명강 마셔 주님과 영원히 잔치하며<br/>영원히 성도들과 함께 주를 찬양해<br/>',NULL,29087,8);
INSERT INTO stanza VALUES('K1064','1','놀라운 생명과 이상 우리의 비밀일세<br/>우리는 주님 안에서 하나님의 소유-되었네<br/>',NULL,29088,1);
INSERT INTO stanza VALUES('K1064','chorus','주 안에 거하세 주 안에 거하세<br/>하나님의 풍성 누리며 생명에 거하며<br/>떠나지 않으리라 영원히 이 곳에 살리<br/>',NULL,29089,2);
INSERT INTO stanza VALUES('K1064','2','옳은 길 찾기 위하여 애쓰는 형제들아<br/>모든 것 내려 놓고서 포도나무 안에- 거하라<br/>',NULL,29090,3);
INSERT INTO stanza VALUES('K1064','3','거룩한 기름 부음이 모든 것 가르치니<br/>주 안에 거하는 자는 하나님의 임재- 맛보리<br/>',NULL,29091,4);
INSERT INTO stanza VALUES('K1064','4','생명의 강이 흐르고 밝은 빛 넘치는 곳<br/>사람과 하나님 거처 포도나무 안에- 거하세<br/>',NULL,29092,5);
INSERT INTO stanza VALUES('K1065','1','주님 맘껏 맛 보아도 항상 쓰고도 남네<br/>모든 잔은 넘치어서 가치 있는 공급돼<br/>부족함이 전혀 없는 주님의 보물 창고<br/>풍성 부요 넘치도록 우리에게 주시네<br/>풍성 부요 넘치도록 우리에게 주시네<br/>',NULL,29093,1);
INSERT INTO stanza VALUES('K1065','2','아버지의 주신 기업 항상 쓰고도 남네<br/>우리 소유 되신 주께 감사 찬양드리세<br/>가난하고 목마른 자 깊이 만족 얻으리<br/>그리스도 맛보는 자 부요 만족 얻겠네<br/>그리스도 맛보는 자 부요 만족 얻겠네<br/>',NULL,29094,2);
INSERT INTO stanza VALUES('K1065','3','그 사랑을 누릴 때에 항상 쓰고도 남네<br/>가장 높고 깊고 넓은 한이 없는 그 사랑<br/>우리들의 입술로는 사랑 표현 못하리<br/>다만 주의 이름 높여 찬송 찬양 드리세<br/>다만 주의 이름 높여 찬송 찬양 드리세<br/>',NULL,29095,3);
INSERT INTO stanza VALUES('K1066','1','지식과 체험 있다고 교만할 수 없으리<br/>순종하며 겸손하게 몸에 상합되겠네<br/>머리를 붙듦으로써 온 몸이 자라나니-<br/>마디와 힘줄 통하여 공급받고 연합 돼<br/>',NULL,29096,1);
INSERT INTO stanza VALUES('K1066','2','능력으로 속 사람이 강건함을 입으리<br/>주의 넓고 깊은 사랑 헤아릴 수 없도다<br/>그리스도 풍성 누려 충만함을 얻고서<br/>온전한 사람 이룰 때 몸이 건축되겠네<br/>',NULL,29097,2);
INSERT INTO stanza VALUES('K1066','3','주의 몸된 그 집에서 건축되기 원하니<br/>단체적인 그릇으로 주 영광 표현하리<br/>주의 신부 예루살렘 머지않아 나타나-<br/>빛나는 등대 통하여 주의 가치 보겠네<br/>',NULL,29098,3);
INSERT INTO stanza VALUES('K1067','1','교회 생활은 내 누림 날마다 내게 부요함 공급돼<br/>이 곳엔 배고픔 없네 우리 모두 다 누리세<br/>',NULL,29099,1);
INSERT INTO stanza VALUES('K1067','chorus','방주에 들어와 교회 생활하세<br/>지체하지 말고 함께 기뻐하세-<br/>방주에 들어와 교회 생활하세<br/>신랑되신 주님 곧 오시리<br/>',NULL,29100,2);
INSERT INTO stanza VALUES('K1067','2','교회 생활은 유일해 자신을 바칠 가치가 있다네<br/>그리스도와 교회를 더할 수 없이 사랑해<br/>',NULL,29101,3);
INSERT INTO stanza VALUES('K1067','3','교회 생활은 귀하네 주님의 집엔 모든 자 부요해<br/>모두가 기능 발휘해 주님의 몸을 표현해<br/>',NULL,29102,4);
INSERT INTO stanza VALUES('K1067','4','교회 생활은 내 생활 우리를 먹일 비옥한 땅이니<br/>그 좋은 땅을 경작해 풍성한 집회 누리세<br/>',NULL,29103,5);
INSERT INTO stanza VALUES('K1067','5','교회 생활은 참 안식 하나님 집과 거처가 되었네<br/>다 함께 건축될 때에 사탄은 패배당하리<br/>',NULL,29104,6);
INSERT INTO stanza VALUES('K1068','1','영 안에서부터 시작해 생각 감정 의지로-<br/>그리스도께서 그 생명 온 존재에 채우네-<br/>',NULL,29105,1);
INSERT INTO stanza VALUES('K1068','chorus','어두움이 변해 빛 되고 거역은 사라지리-<br/>원수 쫓겨나고 주께서 왕 노릇 하시겠네-<br/>',NULL,29106,2);
INSERT INTO stanza VALUES('K1068','2','주가 가장 좋은 것으로 우리에게 주시니-<br/>그의 왕국 임할 때까지 주께 지위 드리리-<br/>',NULL,29107,3);
INSERT INTO stanza VALUES('K1069','1','언제 들리려나 외치는 소리“보라 신랑이다”<br/>승리 선포하는 소리와 함께“보라 신랑이다”<br/>',NULL,29108,1);
INSERT INTO stanza VALUES('K1069','chorus','우린 그의 영광 느낄 수 있네<br/>매일 매일 동틀 때가 가까워<br/>우렁찬 소리에 가슴 뛰도다“보라 신랑이다”<br/>',NULL,29109,2);
INSERT INTO stanza VALUES('K1069','2','당신 손에 등불 빛나고 있나“보라 신랑이다”<br/>기름 예비하라 더 늦기 전에“보라 신랑이다”<br/>',NULL,29110,3);
INSERT INTO stanza VALUES('K1069','3','말씀으로 씻김 받고 있느냐“보라 신랑이다”<br/>얼룩진 것들을 닦아 내었나“보라 신랑이다”<br/>',NULL,29111,4);
INSERT INTO stanza VALUES('K1069','4','그리스도 배필 될 수 있느냐“보라 신랑이다”<br/>서둘러서 그를 맞을 준비해“보라 신랑이다”<br/>',NULL,29112,5);
INSERT INTO stanza VALUES('K1069','5','깨끗한 세마포 준비되었나“보라 신랑이다”<br/>옳은 행실 가져 들림받으리“보라 신랑이다”<br/>',NULL,29113,6);
INSERT INTO stanza VALUES('K1069','6','성령과 신부가 함께 외치네“보라 신랑이다”<br/>혼인 잔치 혹시 오늘 아닐까“보라 신랑이다”<br/>',NULL,29114,7);
INSERT INTO stanza VALUES('K107','1','무덤에서 나온 주 사망 다시-못 해쳐<br/>우린 안위 얻고서 주의 이름 찬미해<br/>구속 역사 완성돼-대적 이미 이겼네<br/>영 단번에 속량해 다시 고통 없겠네<br/>',NULL,29115,1);
INSERT INTO stanza VALUES('K107','2','무덤 지킨 군병들 모든 계획- 헛되네<br/>음부 또한 무익해 주를 묶지 못했네<br/>잠시 주 고통당해- 나는 영영 복 얻네<br/>주 한 번 죽었으니 다시 죽지 않겠네<br/>',NULL,29116,2);
INSERT INTO stanza VALUES('K107','3','한 알의 밀 죽어서 많은 밀알- 싹텄네<br/>원래 한 분이더니 오늘 교회 되었네<br/>우린 그의 몸이니- 머리 따라 올라가<br/>만세토록 찬미해 머리 되신 주 이름<br/>',NULL,29117,3);
INSERT INTO stanza VALUES('K1070','1','난 주의 소유 어떤 기쁨인가 달콤한 주의 음성 들리네<br/>사랑의 교통 주와 나눌 때에“두려워 말라”말씀하시네<br/>',NULL,29118,1);
INSERT INTO stanza VALUES('K1070','2','난 주의 소유 어떤 고백인가 신부는 그날 잊지 못하리<br/>영원한 사랑 신랑께 바쳐서 늘 순종하며 그를 따르리<br/>',NULL,29119,2);
INSERT INTO stanza VALUES('K1070','3','난 주의 소유 가르쳐 주소서 사랑과 신의 거룩한 봉사<br/>온전한 헌신 모두 아낌없이 사랑함으로 주께 드리리<br/>',NULL,29120,3);
INSERT INTO stanza VALUES('K1070','4','난 주의 소유 인쳐 주옵소서 내 영과 혼과 온 몸 까지도<br/>은혜로 인해 당신 얻었으니 영원히 주의 소유되었네<br/>',NULL,29121,4);
INSERT INTO stanza VALUES('K1071','1','내 생명이 되신 주 영광 안에 계셔<br/>순수하네 거룩하네 승리했네<br/>은혜로운 주님은 달콤하시도-다<br/>온유하고 다정한 그 영광스런 생명<br/>그 영광스런 생명 내 소유 됐네<br/>',NULL,29122,1);
INSERT INTO stanza VALUES('K1071','2','내 생명이 되신 주 영광 안에 계셔<br/>마귀 올무 이기시고 승리했네<br/>그 장엄함 위대함 위엄 넘치도-다<br/>그의 모든 어떠함 그 영광스런 생명<br/>그 영광스런 생명 내 소유 됐네<br/>',NULL,29123,2);
INSERT INTO stanza VALUES('K1071','3','내 생명이 되신 주 영광 안에 계셔<br/>연약함과 질병 모두 처리했네<br/>그 강함과 능력은 비교할 수 없-어<br/>그의 모든 어떠함 그 영광스런 생명<br/>그 영광스런 생명 내 소유 됐네<br/>',NULL,29124,3);
INSERT INTO stanza VALUES('K1071','4','내 생명이 되신 주 영광 안에 계셔<br/>한이 없는 인내 평강 되셨도다<br/>그 기쁨과 찬란함 형용할 수 없-네<br/>그의 모든 어떠함 그 영광스런 생명<br/>그 영광스런 생명 내 소유 됐네<br/>',NULL,29125,4);
INSERT INTO stanza VALUES('K1072','1','나는 알았다네 주님 안에 거하는 비결<br/>나는 맛보았네 말씀 통해 생명 생수를<br/>나는 가졌다네 보혈 인한 힘과 능력을<br/>나는 잠겼다네 예수님과 하나님 안에<br/>',NULL,29126,1);
INSERT INTO stanza VALUES('K1072','chorus','주님 안에 거하고 말씀 의지하면서<br/>주의 사랑스런 품에 안기네<br/>주님 안에 거하고 말씀 의지하면서<br/>주의 사랑스런 품에 안기네<br/>',NULL,29127,2);
INSERT INTO stanza VALUES('K1072','2','나는 체험했네 주와 함께 죽고 사는 것<br/>나는 멈추었네 나의 헛된 모든 노력을<br/>나는 원한다네 주의 영이 다스리는 것<br/>나는 누린다네 용서하는 그 피의 효능<br/>',NULL,29128,3);
INSERT INTO stanza VALUES('K1072','3','주가 담당했네 나의 모든 약함과 질병<br/>주가 보살피네 나의 고통 모든 두려움<br/>주가 불어주네 힘을 주는 거룩한 공기<br/>주가 주셨다네 그의 생명 믿음 사랑을<br/>',NULL,29129,4);
INSERT INTO stanza VALUES('K1072','4','주가 능력 주네 말씀 통한 지혜로 인해<br/>주가 동행하네 모든 길에 인도하면서<br/>주가 공급하네 내 마음의 기쁨의 원천<br/>주가 가져오네 치유함과 거룩함까지<br/>',NULL,29130,5);
INSERT INTO stanza VALUES('K1073','1','상전을 사랑하니 자유치 않으리<br/>그는 내 구속주요 날 피로 사신 분<br/>주 섬기는 이 직분 달콤하고 귀해<br/>괴롭고 슬플 때도 안식을 주시네<br/>',NULL,29131,1);
INSERT INTO stanza VALUES('K1073','2','나의 주 피 흘리사 나 같은 노예를<br/>죄와 그 속박에서 해방해 주셨네<br/>상전을 섬기도록 기회 주셨으니<br/>끝까지 순종하며 영원히 섬기리<br/>',NULL,29132,2);
INSERT INTO stanza VALUES('K1073','3','그토록 사랑하사 자신 주셨으니<br/>영원히 나의 상전 떠나지 않겠네<br/>당신을 섬기는 것 최상의 은혜니<br/>내 일생 주님만을 높이며 섬기리<br/>',NULL,29133,3);
INSERT INTO stanza VALUES('K1073','4','그날에 주님께서 내게 말씀하리<br/>잘하였도다 나의 충성된 종아<br/>지극히 작은 일에 충성하였으니<br/>주인의 즐거움에 참예할지어다<br/>',NULL,29134,4);
INSERT INTO stanza VALUES('K1073','5','I love, I love my Mas-ter,<br/>I will not go out free,<br/>For He is my Re-deem-er,<br/>He paid the price for me,<br/>I would not leave His ser-vice,<br/>It is so sweet and blest:<br/>And in the wea-riest mo-ments<br/>He gives the tru-est rest<br/>',NULL,29135,5);
INSERT INTO stanza VALUES('K1074','1','교회 생활은 아름다-와 그 날 맛 봐<br/>새 예루살렘 새 예루살렘 안식과 만족<br/>',NULL,29136,1);
INSERT INTO stanza VALUES('K1074','2','젖과 꿀-이 흐르는- 땅 아름다워<br/>마음껏 누리네 마음껏 누리네 풍성한 생명<br/>',NULL,29137,2);
INSERT INTO stanza VALUES('K1074','3','건축된 교회는 하나님 거처 그분이 안식해<br/>그가 왕 되어 그가 왕 되어 다스리시네<br/>',NULL,29138,3);
INSERT INTO stanza VALUES('K1074','4','달을 보아도 별을 보아도 주님만 생각해<br/>어서 오소서 속히 오소서 아멘 주 예수<br/>',NULL,29139,4);
INSERT INTO stanza VALUES('K1075','1','주 사랑 안에 잠길 때 모든 염려 사라져<br/>사랑으로 감싸시며 주 안으로 이끄네<br/>주의 빛난 얼굴 뵐- 때 얼마나 친근한지<br/>억누를 수 없는 사랑 영원히 함께 하리<br/>주의 사랑 안에 잠길 때 모든 염려 사라져<br/>사랑으로 감싸시며 주 안으로 이끄네<br/>',NULL,29140,1);
INSERT INTO stanza VALUES('K1075','2','주의 사랑 안에 거해 교통하고 의지해<br/>그의 사랑 우릴 묶어 영원히 나뉨 없네<br/>그의 사랑 에워싸시니 얼마나 달콤한지<br/>우리 함께 사랑 안에 맘과 맘이 하나 돼<br/>주의 사랑 안에 거할 때 교통하고 의지해<br/>그의 사랑 우릴 묶어 영원히 나뉨 없네<br/>',NULL,29141,2);
INSERT INTO stanza VALUES('K1076','1','구름같은 증-인들 우리를 격려하네<br/>허다하게 둘러서서 달리게 힘을 주네<br/>밝은 불기둥처럼 어둔 길 비추고<br/>우리 갈길 인도해 전진하게 하네<br/>',NULL,29142,1);
INSERT INTO stanza VALUES('K1076','2','광야 산중 암혈 토굴 유리한 증-인들<br/>먼저 가서 우리 위해 본-이 되-었네<br/>이런 사람 세상이 감당할 수 없네<br/>유리하며 궁핍과 학대받-았네<br/>',NULL,29143,2);
INSERT INTO stanza VALUES('K1076','3','저희 위해 예비했네 하늘에 있는 성을<br/>하나님은 저희들의 하나님 되었-네<br/>이 땅에선 외국인 나그네-였네<br/>증인들은 사모했네 하늘 본-향을<br/>',NULL,29144,3);
INSERT INTO stanza VALUES('K1076','4','주 예수는 믿음의 주 온전케 하시는 이<br/>주 예수를 바라보세 십자가 참으신 분<br/>죄인들의 거역을 참으심 생각해<br/>낙심 말고 전진하세 승리하기까지<br/>오 주여- 내 모든 짐 내려 놓고<br/>당한 경주 달리게 하-소서<br/>',NULL,29145,4);
INSERT INTO stanza VALUES('K1077','1','만족게 하는 자 누구인가 자기 생명 준 자 누군가<br/>그 사랑으로 우리를 끄네 그는 바로 주 예수<br/>예수-는 주시요- - 우리-의 대가라-<br/>크고 작은 필요를- 다 공급해 만유의 주-<br/>만족게 하는 자 누구인가 자기 생명 준 자 누군가<br/>그 사랑으로 우리를 끄네 그는 바로 주 예수<br/>',NULL,29146,1);
INSERT INTO stanza VALUES('K1078','1','그리스도는 지방 교회의 지방 교회의 머리 되시고<br/>그리스도는 지방 교회의 머리 되시네<br/>',NULL,29147,1);
INSERT INTO stanza VALUES('K1078','2','그리스도는 지방 교회의 지방 교회의 실재 되시고<br/>그리스도는 지방 교회의 실재 되시네<br/>',NULL,29148,2);
INSERT INTO stanza VALUES('K1078','3','풍성한 공급 여기에 있네 지방 교회에 지방 교회에<br/>풍성한 공급 여기에 있네 지방 교회에<br/>',NULL,29149,3);
INSERT INTO stanza VALUES('K1078','4','우리 안식처 여기에 있네 지방 교회에 지방 교회에<br/>우리 안식처 여기에 있네 사랑스런 집<br/>',NULL,29150,4);
INSERT INTO stanza VALUES('K1079','1','이 땅에 교회 함께 모일 때마다 주 그리스도 함께 해<br/>종교를 떠나 형식을 떠나 모여 부활의 생명 안에서<br/>부활 안에 실재 누릴 때 모든 문제 사라-져<br/>죽은- 종교 벗어- 버-리고 부활- 안에 모이세<br/>',NULL,29151,1);
INSERT INTO stanza VALUES('K1079','2','그리스도 부활하셨을 때 모든 종교 끝났네<br/>이제 주 예수 우리의 산 성전 우리의 모든 공급돼<br/>할렐루야 부활의 주와 우린 해방 되었네<br/>처량한 종교 벗어버리고 누려 우리 집회는 잔칠세<br/>',NULL,29152,2);
INSERT INTO stanza VALUES('K1079','3','교묘한 종교 아직도 우리 속에 스며들려고 애쓰네<br/>보이지 않는 간교한 무리들 늘 우리 속을 노리네<br/>순간순간 종교에 찌든 혼을 떠나 깨이세<br/>형제 자매여 영 맘껏 해방하세 모일 때마다 해방해<br/>',NULL,29153,3);
INSERT INTO stanza VALUES('K1079','4','입장 위에서 교회가 모일 때에 주 예수 함께 하시네<br/>사신 예수 우리와 함께하니 이에 더 무엇 바라리<br/>낡은 종교 깨뜨리고서 사신 주님 누리세<br/>예수 예수 우리의 주 예수 그는 우리 실젤세<br/>',NULL,29154,4);
INSERT INTO stanza VALUES('K108','1','사랑의 구주 그리스도 당신께 노-래해<br/>피 흘려 구속 이-루사 날 축복하셨네<br/>큰 능력으로 원수 멸해 하늘에 올-랐네-<br/>또한 날 영광에 이끄네 천국에 이끄네<br/>',NULL,29155,1);
INSERT INTO stanza VALUES('K108','2','사랑의 구주 그리스도 당신께 노-래해<br/>사망의 영토 공-격해 사망의 왕 잡아<br/>사망의 권세 쫓-겨나 세상 다시- 못 와-<br/>주 손에 사망 쥐-고서 음부 다스리네<br/>',NULL,29156,2);
INSERT INTO stanza VALUES('K108','3','사랑의 구주 그리스도 당신께 노-래해<br/>배반한 이 세대-의 왕 십자가로 이겨<br/>생명 능력으로- 이겨 깊고 긴 음-부를-<br/>죽음의 죄수 해-방해 자유케 하셨네<br/>',NULL,29157,3);
INSERT INTO stanza VALUES('K108','4','사랑의 구주 그리스도 당신께 노-래해<br/>영원히 나를 해방하신 승리의 주 예수<br/>구원의 능력이신 주님 날 자유케-하니-<br/>하나님과 주 예-수께 영광을 돌리네<br/>',NULL,29158,4);
INSERT INTO stanza VALUES('K1080','1','주께 구합니다 참된 기도를 배워서<br/>주님께 돌이켜 매일 주님을 더 부르도록<br/>주여 더 자라소서<br/>',NULL,29159,1);
INSERT INTO stanza VALUES('K1080','2','내 맘에 심어진 생명의 씨앗인 주님<br/>주님의 생명은 나에게 참된 양식이오니<br/>주여 더 자라소서<br/>',NULL,29160,2);
INSERT INTO stanza VALUES('K1080','3','모든 것 아시는 주여 우리 맘 녹이사<br/>주님을 부를 때 돌을 제하고 경작 하소서<br/>주여 더 자라소서<br/>',NULL,29161,3);
INSERT INTO stanza VALUES('K1080','4','주님의 빛 앞에 우리의 허물 보이나<br/>소망이 있음은 우리 안의 씨 발아하는 것<br/>주여 더 자라소서<br/>',NULL,29162,4);
INSERT INTO stanza VALUES('K1080','5','가난한 영으로 주님의 다루심 받고<br/>생명이 흐르니 그 생명 인해 우리 성장해<br/>주여 더 자라소서<br/>',NULL,29163,5);
INSERT INTO stanza VALUES('K1080','6','주여 우리에게 순수한 마음을 주사<br/>생각과 감정과 의지를 새롭게 하옵소서<br/>주여 더 자라소서<br/>',NULL,29164,6);
INSERT INTO stanza VALUES('K1080','7','우리를 강권해 매일 주님을 살도록<br/>자랄 수 있도록 이 땅에 주의 나라 얻도록<br/>주여 더 자라소서<br/>',NULL,29165,7);
INSERT INTO stanza VALUES('K1080','8','아멘 주의 자람 능력 있는 주의 생명<br/>우릴 새롭게 해 주 안에 분명히 자라나니<br/>주여 더 자라소서<br/>',NULL,29166,8);
INSERT INTO stanza VALUES('K1081','1','강한 사랑 날 강권하시고 큰 파도같이<br/>나를 덮으사 내 혼에 통로 얻기 원하며-<br/>모든 장애물 무너뜨리네<br/>',NULL,29167,1);
INSERT INTO stanza VALUES('K1081','2','그 강권에 순종치 않으랴 사랑의 흐름<br/>거절하겠나 온유한 당신 나를 정복해-<br/>나의 삶 전과 같지 않으리<br/>',NULL,29168,2);
INSERT INTO stanza VALUES('K1081','3','사랑으로 내 성품 깨뜨려 내 의지 감정<br/>소유하시네 생각과 마음 씻어 주실 때-<br/>당신의 생명만이 남으리<br/>',NULL,29169,3);
INSERT INTO stanza VALUES('K1082','1','주와 함께 죽은 놀라운 사실 육과 정욕에서 해방해<br/>주와 함께 사는 놀라운 사실 나는 부활 생명 얻었네<br/>갈보리의 십자가에 주님은 나와 함께 못 박혔네<br/>주와 함께 부활 생명 누리며 항상 살아가리<br/>',NULL,29170,1);
INSERT INTO stanza VALUES('K1083','1','교회 교회 교회 교회<br/>우리는 주의 회복안의 지방 교회<br/>우리는 주의 회복안의 지방 교회<br/>우리는 요한계시록의 등대들<br/>우리는 요한계시록의 등대들<br/>교회 교회 교회 교회<br/>우리는 요한계시록의 등대들<br/>',NULL,29171,1);
INSERT INTO stanza VALUES('K1083','chorus','교회 등대 예수 성령 성령 더 누려 풍성한 교회 위해<br/>',NULL,29172,2);
INSERT INTO stanza VALUES('K1083','2','등대 등대 등대 등대<br/>등대는 바로 증가된 그리스도<br/>등대는 바로 증가된 그리스도<br/>등대는 바로 일곱영의 재생산<br/>등대는 바로 일곱영의 재생산<br/>등대 등대 등대 등대<br/>등대는 바로 일곱 영의 재생산<br/>',NULL,29173,3);
INSERT INTO stanza VALUES('K1083','3','예수 예수 예수 예수<br/>이 등대들이 예수의 증거라네<br/>이 등대들이 예수의 증거라네<br/>예수의 증거를 하나님 나타냈네<br/>예수의 증거를 하나님 나타냈네<br/>예수 예수 예수 예수<br/>예수의 증거를 하나님 나타냈네<br/>',NULL,29174,4);
INSERT INTO stanza VALUES('K1083','4','성령 성령 성령 성령<br/>교회는 주와 함께 빛나는 성령<br/>교회는 주와 함께 빛나는 성령<br/>성령 더 누려 풍성한 교회 위해<br/>성령 더 누려 풍성한 교회 위해<br/>성령 성령 성령 성령<br/>성령 더 누려 풍성한 교회 위해<br/>',NULL,29175,5);
INSERT INTO stanza VALUES('K1084','1','땅 점령하자 하나님이 주신 이 땅<br/>주는 우리 모든 것 되네 땅 점령 위해<br/>우리에게 필요한 것 피와 말씀 성령과 교회<br/>',NULL,29176,1);
INSERT INTO stanza VALUES('K1084','chorus','형제들아 점령하자 하나님이 주신 이 땅을<br/>용감하여라! 이길 수 있다! 이 땅 점령할 수 있다<br/>자매들아 점령하자 신실히 이 땅 지키자<br/>앞서 가신 주! 강권하신다! 필요한 것 다 주시며<br/>',NULL,29177,2);
INSERT INTO stanza VALUES('K1084','2','그리스도는 우리의 흠 없는 제물<br/>하나님을 만족게 한 분 우린 담대히<br/>은혜의 보좌 앞으로 주의 보혈 힘입어 온다<br/>',NULL,29178,3);
INSERT INTO stanza VALUES('K1084','3','주의 말씀은 우리의 일용할 양식<br/>우린 말씀 믿고 아멘해 이 말씀 종일<br/>우리 안에 들려오며 우리 생활 인도하신다<br/>',NULL,29179,4);
INSERT INTO stanza VALUES('K1084','4','실재의 영 그 영은 바로 우리의 것<br/>그는 우리 안에 사시네 우리로 그의 안에<br/>거하게 하시네 실재 중에 인도하시며<br/>',NULL,29180,5);
INSERT INTO stanza VALUES('K1084','5','주의 교회에 이 큰 실재 충만함을<br/>모두 와서 함께 누리자 만유를 포함하신<br/>그리스도 얻자 그는 모든 것의 모든 것<br/>',NULL,29181,6);
INSERT INTO stanza VALUES('K1085','1','생명 강 흐름 중에 몸을 담았네 지방 입장 위에서<br/>생명 강 흐름 중에 몸을 담았네 지방 입장 위에서<br/>',NULL,29182,1);
INSERT INTO stanza VALUES('K1085','chorus','오 주여 우리는 지방 입장 위에서<br/>오 주여 우리는 지방 입장 위에 서 있네<br/>',NULL,29183,2);
INSERT INTO stanza VALUES('K1085','2','우리는 보네 교회 회복 이상을 지방 입장 위에서<br/>우리는 보네 교회 회복 이상을 지방 입장 위에서<br/>',NULL,29184,3);
INSERT INTO stanza VALUES('K1085','3','지방 교회는 종파 공회 아닐세 지방 입장 위에서<br/>지방 교회는 종파 공회 아닐세 지방 입장 위에서<br/>',NULL,29185,4);
INSERT INTO stanza VALUES('K1085','4','여기에 형제 자매 사랑 흐르네 지방 입장 위에서<br/>여기에 형제 자매 사랑 흐르네 지방 입장 위에서<br/>',NULL,29186,5);
INSERT INTO stanza VALUES('K1085','5','주의 부르심 받고 함께 훈련해 지방 입장 위에서<br/>주의 부르심 받고 함께 훈련해 지방 입장 위에서<br/>',NULL,29187,6);
INSERT INTO stanza VALUES('K1085','6','우리는 주의 군사 되어 싸우네 지방 입장 위에서<br/>우리는 주의 군사 되어 싸우네 지방 입장 위에서<br/>',NULL,29188,7);
INSERT INTO stanza VALUES('K1085','7','영 안에 서세 주의 오시기까지 지방 입장 위에서<br/>영 안에 서세 주의 오시기까지 지방 입장 위에서<br/>',NULL,29189,8);
INSERT INTO stanza VALUES('K1086','1','지방 교회 중에 우리 모두<br/>주 예수 생명 삼아 영 안에 주<br/>오 할렐루야 영 안에 입장에<br/>굳게 서서 주 위해 싸워 이겨<br/>그리스도 왕국 세우세<br/>',NULL,29190,1);
INSERT INTO stanza VALUES('K1087','1','나 지금 지방 교회 중에 있네 지방 교회 지방 교회<br/>지방 교회 내 마음 속에 있네 지방 교회 내 맘 속에<br/>영원히 있네 참 즐겁고도 참 기쁘도다<br/>나 지금 지방 교회에 있네 참 즐겁고도<br/>참 놀랍도다 지방 교회 내 맘 속에 있네<br/>',NULL,29191,1);
INSERT INTO stanza VALUES('K1088','1','찬양해- 주님을 주의 회복 안에서- 끝날까지-<br/>교회에 거하리- 새 창조 안에 우린 찬양해-<br/>성도들과 한 새 사람을 건축해-<br/>하나로 사모하는 주 다시- 오시는 날까지 서- 서<br/>하-나를 간-증하리라 아무도 막지 못-하리<br/>',NULL,29192,1);
INSERT INTO stanza VALUES('K1089','1','속죄하신 구세주를 내가 찬송하리라<br/>내게 자유 주시려고 주가 고난 당했네<br/>',NULL,29193,1);
INSERT INTO stanza VALUES('K1089','chorus','크신 사랑 찬양하리 나의 죄 사하려고<br/>십자가에 돌아가신 나의 주 찬양하리<br/>',NULL,29194,2);
INSERT INTO stanza VALUES('K1089','2','내가 구원받은 증거 기뻐 전파하리라<br/>내 죄 모두 담당하신 주의 사랑 크셔라<br/>',NULL,29195,3);
INSERT INTO stanza VALUES('K1089','3','승리하신 구세주를 내가 찬송하리라<br/>죄와 죽음 지옥 권세 주가 모두 이겼네<br/>',NULL,29196,4);
INSERT INTO stanza VALUES('K1089','4','고마우신 구세주를 내가 찬송하리라<br/>죽음에서 생명으로 나를 인도하셨네<br/>',NULL,29197,5);
INSERT INTO stanza VALUES('K109','1','찬양하세! 주의 승리 주는 승리하셨네!<br/>죄를 씻고 옛 사람 다 끝내 구속-이뤘네!<br/>십자가로 사탄 깨고 악령 묶어 이겼네!<br/>',NULL,29198,1);
INSERT INTO stanza VALUES('K109','2','찬양하세 주의 부활 주는 부활하셨네!<br/>사망 권능 삼키시고 생명 해방-하셨네!<br/>음부 어둠 타파하여 부활 능력 나타내!<br/>',NULL,29199,2);
INSERT INTO stanza VALUES('K109','3','찬양하세 주의 승천 주는 승천하셨네!<br/>우주 안에 뛰어난 주 존귀한 이름 얻었네!<br/>모든 권세 얻으신 주 발로 원수 밟겠네!<br/>',NULL,29200,3);
INSERT INTO stanza VALUES('K109','4','할렐루야 주의 승리 주 이미 승리했네!<br/>할렐루야 주의 부활 주 이미 부-활했네<br/>할렐루야 주의 승천 주 이미 승천했네!<br/>',NULL,29201,4);
INSERT INTO stanza VALUES('K1090','1','그리스도의 십자가 칭의 위하여<br/>그리스도의 부활은 성화 위하네<br/>생명 주는 영이신 주 풍성한 생명으로<br/>주의 성분 분배하여 성화시키네<br/>',NULL,29202,1);
INSERT INTO stanza VALUES('K1090','2','흘리신 보혈의 피로 얻은 아들들<br/>아들은 아버지 닮아 거룩해지네<br/>할렐루야 오 주 예수 그리스도 안에서<br/>영원한 하나님 아들로 영화롭게 돼<br/>',NULL,29203,2);
INSERT INTO stanza VALUES('K1090','3','많은 아들 얻으심이 아버지 갈망<br/>단체적인 표현 교회 하나님 목적<br/>그리스도의 생명과 교회 생활이 전부<br/>단장된 교회인 신부 신랑 맞으리<br/>',NULL,29204,3);
INSERT INTO stanza VALUES('K1090','4','아들들이 된 우리는 기업 후사요<br/>그와 함께 영광 받고 영광 찬미돼<br/>오 주 예수 그리스도 삼일 하나님 영광<br/>영원한 영광의 극치 새 예루살렘<br/>',NULL,29205,4);
INSERT INTO stanza VALUES('K1091','1','하늘에서 들려오는 찬양하는 저 노래<br/>온 하늘이 잔치하네 예수 다스리시니<br/>보좌에 앉으신 주님 세상 주관하시도다<br/>',NULL,29206,1);
INSERT INTO stanza VALUES('K1091','chorus','할렐루야 할렐루야 할렐루야 아-멘<br/>',NULL,29207,2);
INSERT INTO stanza VALUES('K1091','2','십자가를 지신 주님 함께 찬양하도다<br/>그에게 권세가 있네 영광 중에 계신 왕<br/>우리 부를 찬송 제목 달콤하게 불러 보네<br/>',NULL,29208,3);
INSERT INTO stanza VALUES('K1091','3','주의 영광 빛 넘치네 당신은 생명의 주<br/>주의 빛난 웃는 얼굴 성도들 사로 잡네<br/>당신의 놀라운 사랑 거룩하고 신성하니<br/>',NULL,29209,4);
INSERT INTO stanza VALUES('K1091','4','영원토록 영광의 왕 면류관을 쓰셨네<br/>영원히 우리는 하나 당신 소유되었네<br/>주님의 은혜 누리고 주의 얼굴 바라보니<br/>',NULL,29210,5);
INSERT INTO stanza VALUES('K1091','5','오 주여 속히 오셔서 영광의 날 주소서<br/>힘찬 음성 들려올 때 천지는 없어지리<br/>우리 함께 부를 찬송 영광 영광 우리 왕께<br/>',NULL,29211,6);
INSERT INTO stanza VALUES('K1092','1','오 할렐루야 십자가 주님 죽으셨네<br/>주님 한 분만 아니라 모든 사람도<br/>그 위에 포함시키셨-네 당신과 나까-지<br/>오- 할-렐루-야- 십자가-<br/>',NULL,29212,1);
INSERT INTO stanza VALUES('K1092','2','주님을 찬미합니다 옛 사람 끝났네<br/>결국 나의 옛 사람도 하나님 끝내 버렸네<br/>오 존귀한 죽-음 오 존귀한 죽-음<br/>오- 할-렐루-야- 끝났네-<br/>',NULL,29213,2);
INSERT INTO stanza VALUES('K1092','3','주님을 찬미합니다 그 신성한 죽음<br/>떨어진 한 알의 밀알 땅에서 많이 번식해<br/>많은 밀알 되었네 거룩한 생명으로<br/>오- 할-렐루-야- 이 생명-<br/>',NULL,29214,3);
INSERT INTO stanza VALUES('K1092','4','십자가 찬미합니다 참 온전한 죽음<br/>온 우주의 중심이요 영원히 가치 있는 것<br/>십자가 사랑-해 십자가 사랑-해<br/>오- 할-렐루-야- 십자가-<br/>',NULL,29215,4);
INSERT INTO stanza VALUES('K1093','1','하나님 우리를 교통케 하려 불렀네<br/>그리스도는 우리에게 지혜 되었네<br/>의로움과 거룩함 되-시네 또 우리 구속함 되네<br/>',NULL,29216,1);
INSERT INTO stanza VALUES('K1093','2','주와 합하는 자 주님과 한- 영일세<br/>오직 그리스도 건축의 유일한 기초<br/>금과 은과 보 -석으로 지어 예수 그리스도 위에<br/>',NULL,29217,2);
INSERT INTO stanza VALUES('K1094','1','우리를 불러 교통케 하신 하나님은 미쁘시다<br/>그 교통 안에 누리는 그리스도 하나님의 기업<br/>',NULL,29218,1);
INSERT INTO stanza VALUES('K1095','1','하나님께로서 나와서 우리에게 지혜 된<br/>그리스도 나 얻으리 완전한 구-원일세<br/>',NULL,29219,1);
INSERT INTO stanza VALUES('K1095','2','그가 우리 의- 되시니 우린 의롭다네<br/>하나님께로서 거듭나 새 생-명- 얻었네<br/>',NULL,29220,2);
INSERT INTO stanza VALUES('K1095','3','그는 이제 우리 거룩함 우릴 거룩게 해<br/>우리 생각 감정 의지 주가- 변-케하네<br/>',NULL,29221,3);
INSERT INTO stanza VALUES('K1095','4','그는 우리 구-속되네 우리 몸 변하여<br/>그 날에 그- 영광의 형상-으로 화하리<br/>',NULL,29222,4);
INSERT INTO stanza VALUES('K1095','5','하나님의 온-전하고 완전한 구-원<br/>온 영과 혼과 몸 안에 우린- 주와 하나 돼<br/>',NULL,29223,5);
INSERT INTO stanza VALUES('K1095','6','그는 우리의- 의로움 거룩함 또 구속<br/>매일매일 훈련하여 누리-고 또 누리세<br/>',NULL,29224,6);
INSERT INTO stanza VALUES('K1095','7','하나님 우릴- 주님과 하나 되게 하니<br/>우린 자랑할 것 없어 다만- 주- 찬양해<br/>',NULL,29225,7);
INSERT INTO stanza VALUES('K1096','1','나는 심고 아볼로는 물 주고<br/>하나님-은 자라게 했네<br/>심는 이 물 주는 이 아무 것 아닐세<br/>오직 자라게 하신 하-나님 뿐일세<br/>너희는 하나님의- 밭이-요 하나님의- 집<br/>',NULL,29226,1);
INSERT INTO stanza VALUES('K1097','1','내-가 너희에게 전-한 것-은 주-께 받-은<br/>것이-니 곧- 주 예수께서 잡히시-던 밤-에<br/>떡-을 가지-사 축사하시고<br/>이는 너희를 위하는 나의 몸-이니<br/>이를 행해 나를 기념하라 나를 기념하라-<br/>식-후에 또-한 이-와 같-이 잔-을 가지시고<br/>가라사대 이- 잔은 내- 피로 세운 새 언약이니<br/>마-실 때마다 나를 기념하라<br/>너희가 이 떡을 먹으-며 이 잔을 마-실 때마-다<br/>주의 죽으심을 오실 때까-지<br/>전하는 것이니 주 오실 때까지<br/>이는 너희를 위하는 나의 몸-이니<br/>이를 행해 나를 기념하라 나를 기념하라-<br/>',NULL,29227,1);
INSERT INTO stanza VALUES('K1098','1','언제든-지 주께 돌-아-가면 그 수건이 벗어지리라<br/>언제든-지 주께 돌-아-가면 그 수건이 벗어지리<br/>지금 주님은그 영-이시-니<br/>주의- 영이 있는 곳에는 자유함이있네-<br/>언제든-지 주께 돌-아-가면 그 수건이 벗어지리<br/>',NULL,29228,1);
INSERT INTO stanza VALUES('K1099','1','우리가 다 수건-을 벗은 얼굴로 거울을- 보듯-<br/>주의 영광- 보매 저와 같은 형상으로 화해-<br/>영광으로 영광에 영광으로 영-광-에 이르네<br/>우리가- 변화되네 영광으로 영광에<br/>영광으로 영-광-에 이르네<br/>우리가- 변화되네 영광으로 영광에 이르네<br/>영광으로 영광에- 주-의 영으로 인하여-<br/>',NULL,29229,1);
INSERT INTO stanza VALUES('K11','1','오 아버지는 소나무처럼 늘 새로우신 분<br/>영원히 실패하지 않고 항상 살아 계시네<br/>',NULL,29230,1);
INSERT INTO stanza VALUES('K11','chorus','늘 새로우신 아버지 결코 늙지 않아<br/>천만 년 가도 항상 신선해 영원 영원히<br/>',NULL,29231,2);
INSERT INTO stanza VALUES('K11','2','오 새로우신 하나님 없으면 다 낡아져도<br/>당신 계시면 모든 것 새롭네 세월 지나도<br/>',NULL,29232,3);
INSERT INTO stanza VALUES('K11','3','우리가 얻은 당신의 축복은 모두 새로워<br/>새 언약 새 길 모든 것 영원히 항상 새롭네<br/>',NULL,29233,4);
INSERT INTO stanza VALUES('K11','4','오 우린 주의 새 창조 새 사람 날로 새로워<br/>새 마음 새 영 강건해 새 생명 항상 충만해<br/>',NULL,29234,5);
INSERT INTO stanza VALUES('K11','5','새 하늘 새 땅 새 성엔 모든 것 새롭게 되네<br/>날마다 새로운 실과 공급돼 묵은 것 없네<br/>',NULL,29235,6);
INSERT INTO stanza VALUES('K11','6','오 새로우신 아버지 하나님 늘 찬양하리<br/>늘 새로우신 당신을 영원히 찬미하겠네<br/>',NULL,29236,7);
INSERT INTO stanza VALUES('K110','1','들-어 보라 천-천만만 뇌-성 같이 외-치며<br/>하-나님의 어-린 양을 높-이는 저 찬송을<br/>',NULL,29237,1);
INSERT INTO stanza VALUES('K110','2','하-늘에서 모-든 회중 우-리 구주 찬-양해<br/>모-든 입이 주- 예수를 시-인하며 찬양해<br/>',NULL,29238,2);
INSERT INTO stanza VALUES('K110','3','우-리 마음 향-연처럼 보-좌 향해 오-를 때<br/>모-든 무릎 아-들 향해 꿇-고 경배드리네<br/>',NULL,29239,3);
INSERT INTO stanza VALUES('K110','4','영-광이신 아-버지를 나-타내는 아-들은<br/>영-광의 광채-요 또한 본-체의 형상이라<br/>',NULL,29240,4);
INSERT INTO stanza VALUES('K110','5','하-나님은 선-포하네 그-의 모든 지-혜로<br/>그-의 아들 그-와 같이 존-귀함을 선포해<br/>',NULL,29241,5);
INSERT INTO stanza VALUES('K110','6','우-리 안에 들-어오려 성-령으로 오-신 주<br/>그-의 역사 영-원토록 찬-양하고 찬양해<br/>',NULL,29242,6);
INSERT INTO stanza VALUES('K110','7','온-전하고 견-고하네 영-광스런 새- 창조<br/>안-식 기쁨 누-리게 해 만-족스런 새 창조<br/>',NULL,29243,7);
INSERT INTO stanza VALUES('K110','8','주-은혜로 복-음 얻어 구-원받은 우-리들<br/>이-제 다신 묶-임 없고 다-신 고통 없겠네<br/>',NULL,29244,8);
INSERT INTO stanza VALUES('K110','9','들-어 보라 하-늘 위에 뇌-성 같은 찬-송을<br/>우-주 안에 충-만하네 아-멘 할렐루-야<br/>',NULL,29245,9);
INSERT INTO stanza VALUES('K1100','1','그리스도 사랑이 우릴 강권하시니<br/>우린 사랑 안에서 제한되고 갇히네<br/>주의 역사 우리로 한 목적만 향케 해<br/>목적 안에 우리를 가두고 또 세우네<br/>',NULL,29246,1);
INSERT INTO stanza VALUES('K1100','2','그리스도 사랑이 우릴 강권하시어<br/>좁은 길로 우리를 걸어가게 하시네<br/>한 사람이 모든 사람 위해 죽으셨으니<br/>모든 사람 죽었네 모두 죽은 것일세<br/>',NULL,29247,2);
INSERT INTO stanza VALUES('K1100','3','그리스도 사랑이 우릴 강권하시어<br/>우리 자신 위하여 살지 않게 하시고<br/>우리 위해 죽으신 주를 위해 살게 해<br/>주 사랑 날 강권해 주만 위해 살게 해<br/>',NULL,29248,3);
INSERT INTO stanza VALUES('K1100','4','그리스도 사랑이 우릴 강권하시어<br/>자신 위해 살던 나 주 위해 살게 하고<br/>점점 우리 옛 생명 후패하게 하시네<br/>그 사랑에 포로 돼 주만 위해 살겠네<br/>',NULL,29249,4);
INSERT INTO stanza VALUES('K1101','1','히브리서에 하나님 아들 안에서 말해<br/>그 말씀은 우리에게 계시돼<br/>더 이상은 감춰 있지 않고<br/>이젠 나타내 할렐루야 아들 통해 말씀해<br/>그리스도 귀한 아들 그 안에서 말씀하셔<br/>우리에게 계시됐네<br/>할렐루야 주는 하나님 자신<br/>',NULL,29250,1);
INSERT INTO stanza VALUES('K1101','2','하나님 아들로서 천사보다 월등해<br/>가장 아름다운 이름 얻었네<br/>천사들은 피조됐고 아들은 창조했네<br/>천사보다 훨씬 뛰어나신 분<br/>아버지 표현은 아들 아들은 아버지 형상<br/>주님의 영광의 광채<br/>모든 것이 말씀으로 지탱돼<br/>',NULL,29251,2);
INSERT INTO stanza VALUES('K1101','3','사도이신 그리스도 모세로 예표됐네<br/>우리 함께 하나님을 나누려<br/>그 생명과 그 성품과 신성한 온전함에<br/>영원토록 우리 참여케 했네<br/>모세보다 뛰어난 분 영광과 존귀를 돌려<br/>거룩한 사도 주 예수<br/>자신 버린 신실하신 주님께<br/>',NULL,29252,3);
INSERT INTO stanza VALUES('K1101','4','그리스도 아론보다 뛰어난 대제사장<br/>우리 연약함을 체휼하시네<br/>때를 따라 돕는 은혜 얻기 위해 나가세<br/>신실하고 유일한 대제사장<br/>우리들의 참된 사도 우리들의 대제사장<br/>구원의 대장 주 예수<br/>그리스도 우리 참 여호수아<br/>',NULL,29253,4);
INSERT INTO stanza VALUES('K1102','1','우리가 이 영원한 생명을 전함은<br/>너희에게 영원한 이 생명 전함은<br/>너희로 우리와 교통 있게 함이라<br/>너희로 우리와 교통 있게 함이라<br/>',NULL,29254,1);
INSERT INTO stanza VALUES('K1103','1','그의 기름 부음 너희에게<br/>모든 것 다 가르치니<br/>너희를 가르치신 그-대-로<br/>주 안-에- 거하라<br/>',NULL,29255,1);
INSERT INTO stanza VALUES('K1104','1','왕- 만세의 왕- 만세의 왕<br/>영원히 썩지 않고 보이지 않고<br/>홀로 하나인 하나님께<br/>존귀와 영광이 세세토록 있을지라 아멘<br/>존귀와 영광이 세세토록 있을지라<br/>',NULL,29256,1);
INSERT INTO stanza VALUES('K1105','1','하나님께로-서 난 자는 모두 이 세상을 이기네<br/>능히 이기네 악한 자가 저-를 만지지 못해<br/>악한 자가 저-를 만지지 못해<br/>하나님께로-서- 난 자는 모-두<br/>이 세상을 이기네 능히 이기네<br/>',NULL,29257,1);
INSERT INTO stanza VALUES('K1106','1','태초부터 있는 생-명의 말-씀<br/>생명의 말씀에 관하여 우리가 듣-고<br/>눈으로 본 바요 주목하고 만진바라<br/>',NULL,29258,1);
INSERT INTO stanza VALUES('K1106','2','비밀의 말-씀 생명의 말씀이<br/>만질 수 있는 육신 됐네 부활하신 후에<br/>영에 속한 그 몸 도마도 만져 보았네<br/>',NULL,29259,2);
INSERT INTO stanza VALUES('K1106','3','제일 큰 비밀은 생명의 분밸세<br/>생명의 교통 기름 부음 거룩한 출생과<br/>물과 피와 그 영 성도의 체험되었네<br/>',NULL,29260,3);
INSERT INTO stanza VALUES('K1107','1','저가 빛 가운데 계심같이<br/>우리도 빛 가운데 행하면 교통 있고<br/>그의 아들 예수 피가 우릴<br/>모든 죄에서 깨끗하게 하실 것이라<br/>',NULL,29261,1);
INSERT INTO stanza VALUES('K1108','1','사랑하는 자들아 우린 하나님의 자녀-라<br/>장래 어찌 될 것 아-직 나타나지 않았지만<br/>주 나타날 때 우리도 그와 같은 줄 아는 것은<br/>그의 계신 그-대-로 볼 것-을- 인-함이-라<br/>',NULL,29262,1);
INSERT INTO stanza VALUES('K1109','1','자녀들아 너흰 하나님께 속해 저를 이겼다<br/>너희 안에 계신 이는 크다 세상 왕보다 크다<br/>생명 주는 영이 되신 삼이일 하나님은<br/>악한 영인 사탄보다 더욱 크고 강하다<br/>',NULL,29263,1);
INSERT INTO stanza VALUES('K111','1','하-나님 아들 주 예수 피로 우릴 속해 주셨네<br/>죄 벗게 하셨네 주- 성도들은 즐거이 영-광의<br/>관 쓴 주님을 하늘 보좌 위에 앉은 주 본다네<br/>',NULL,29264,1);
INSERT INTO stanza VALUES('K111','2','아-버지 사랑 주 높여 영광 존귀 권능 주시고<br/>우편에 앉게 해 이제 찬송 지혜 풍성이 모두 주<br/>당신께 속하리 주 그의 연대는 무한해 끝없네<br/>',NULL,29265,2);
INSERT INTO stanza VALUES('K111','3','교-회의 머리 주 예수 모든 지체에게 복 주네<br/>주 우리 것일세 우-리를 굳게 서게 해 원-수를<br/>이기게 하니 주 우리 생명과 또 능력이실세<br/>',NULL,29266,3);
INSERT INTO stanza VALUES('K111','4','곧- 영광의 날 임할 때 우린 신부로서 올라가<br/>주님을 만나리 주- 아름다움 보면서 우릴 인정하는<br/>주 음성 듣고 또 주님과 영원히 안식해<br/>',NULL,29267,4);
INSERT INTO stanza VALUES('K1110','1','사랑하는 자들아 서로 사랑하-자<br/>하나님께 속한 사랑을 형제 사랑하는 자<br/>하나님께로 나서 하나님을 안-다네<br/>',NULL,29268,1);
INSERT INTO stanza VALUES('K1111','1','사랑하는 자들아 우리 서로 사랑하자<br/>하나님은 사랑이라 형제 사랑하는 자는<br/>모두 하나님께로서 난 자로다<br/>',NULL,29269,1);
INSERT INTO stanza VALUES('K1111','2','형-제를 사랑치 않는 자는 하-나님<br/>결단코 알지 못해 사랑은 은혜의 근원이니<br/>이 사랑 나타남이 은혤세<br/>',NULL,29270,2);
INSERT INTO stanza VALUES('K1112','1','만유를 포-함한 복합적인 과정을 거치신<br/>칠 배의 강한 영 생명 주는 영이신 내주하는- 영<br/>우리 안에 들-어와 기름 부음 됐네<br/>항상 살아 움직이고 또 가르치네<br/>',NULL,29271,1);
INSERT INTO stanza VALUES('K1113','1','하늘의 곡조 울리니 내 마음 기쁘도다-<br/>아름다운 멜로디로 날마다 주 찬양해-<br/>',NULL,29272,1);
INSERT INTO stanza VALUES('K1113','chorus','노래하는 순례자- 구주의 손 잡고-<br/>약속의 땅 찾아서- 길 가는 순례자-<br/>',NULL,29273,2);
INSERT INTO stanza VALUES('K1113','2','주께서 내 짐 지시니 발걸음 가벼웁다-<br/>주님의 그 크신 은혜 날마다 찬송하리-<br/>',NULL,29274,3);
INSERT INTO stanza VALUES('K1113','3','언젠가 주님 오실 때 기쁘게 만나리니-<br/>순례자 나가는 길엔 두려움 없으리라-<br/>',NULL,29275,4);
INSERT INTO stanza VALUES('K1114','1','내적인 생명 따름이 새 언약 안의 길일세<br/>생명률 따라 살 때에 하나님 계획 이뤄져<br/>',NULL,29276,1);
INSERT INTO stanza VALUES('K1114','chorus','오 주여 새 언약의 길 모두 다 가게 하소서<br/>주의 뜻 이룰 때까지 이 한 길 가게 하소서<br/>',NULL,29277,2);
INSERT INTO stanza VALUES('K1114','2','생명의 역량 생명률 하나님 닮게 하시네<br/>그리스도의 몸 이뤄 직분 다하게 하시네<br/>',NULL,29278,3);
INSERT INTO stanza VALUES('K1114','3','죄와 불법 다 사하고 다시 기억도 안하셔<br/>맘 속에 그 법 새기어 하나님 알게 하시네<br/>',NULL,29279,4);
INSERT INTO stanza VALUES('K1114','4','새 예루살렘 안에는 한 흐름 한 길 한 나무<br/>먹고 마시고 누리며 하나님 표현한다네<br/>',NULL,29280,5);
INSERT INTO stanza VALUES('K1115','1','생수의 근원 와서 마시라 생수의<br/>근원 여호와를- 물 담지 못할<br/>웅덩이 버려 그것은 새고 말라버려-<br/>생수의 근원 와서 마시라<br/>생수의 근원 여호와를-<br/>물 담지 못 할 웅덩이 버려<br/>그것은 새고 말라버려-<br/>',NULL,29281,1);
INSERT INTO stanza VALUES('K1115','2','주의 달콤한 인자하심이 매일<br/>우리를 소멸 않고 그분의 긍휼<br/>우리를 살려 매-일 아침 새-로워<br/>그는 내 기업 내 분깃이라<br/>나는 그분을 바라리라<br/>그는 내 분깃 내 생수 근원<br/>주의 선하심 받으리라<br/>',NULL,29282,2);
INSERT INTO stanza VALUES('K1115','3','의로운 싹을 다윗에게서<br/>일으키셨네 지혜의 왕 주는<br/>우리의 구속 의로움 부르라 주님<br/>우리의 의 그들의 죄를 기억 않으리<br/>그들의 악을 잊으리라<br/>주는 우리의 구속 의로움<br/>부르라 주님 우리의 의<br/>',NULL,29283,3);
INSERT INTO stanza VALUES('K1115','4','나의 새 언약 선포하리라 의문이<br/>아닌 생명일세 생명의 법을<br/>그 속에 두고 나의 자신을 기록하리<br/>나는 하나님 그들은 백성<br/>나를 앎으로 나를 살리<br/>그들의 죄를 기억 않으리<br/>그들의 악을 잊으리라<br/>',NULL,29284,4);
INSERT INTO stanza VALUES('K1115','5','오라 생수의 성으로 오라 먹으라<br/>와서 생명 열매 신성한 분배의 길을 걸으라<br/>삼일성 표현 빛-의 성<br/>그가 새긴 글 와서 읽으라<br/>생명의 법의 체현을<br/>하나님 증가 신성한 확장<br/>새 예루살렘 신부에게<br/>',NULL,29285,5);
INSERT INTO stanza VALUES('K1116','1','사랑의 주여 영원한 주 사랑- 택한 자들<br/>열망하시니- 이스라엘 돌이켰다네-<br/>그들은 돌이켜 우상들로부터 그리스도께로-<br/>',NULL,29286,1);
INSERT INTO stanza VALUES('K1116','2','의이신 주님 사람으로 오셔- 신성하신<br/>경륜 안에서- 우리의 모든 것-으로-<br/>우주와 중심과 둘레로 날마다 체험 되신다네-<br/>',NULL,29287,2);
INSERT INTO stanza VALUES('K1116','3','나면서부터 사악한 우리는- 주-님의<br/>구속 바라네- 부패와 죄 끝이 아닐세-<br/>주님의 구속과 구원의 신성한 생명 분배하네-<br/>',NULL,29288,3);
INSERT INTO stanza VALUES('K1116','4','생명의 구원 생명의 역량이- 우리로<br/>하나님 되게 해- 우리로 모든 것 하게 해-<br/>삼일성 풍성의 모든 것 누림을 나누어 가졌네-<br/>',NULL,29289,4);
INSERT INTO stanza VALUES('K1116','5','이스라엘 회복되리라 그때- 이-기는<br/>자들과 함께- 주의 풍성 완성되리라-<br/>새 하늘 새 땅의 새 예루살렘을 영원히 누리네-<br/>',NULL,29290,5);
INSERT INTO stanza VALUES('K1117','1','그분경륜 위-해 주께 필요한 단체적인<br/>사람 되기 위하여 성도들아우-리<br/>모든 것 걸고 그리스도얻고 낳자 주 뜻 이루자<br/>',NULL,29291,1);
INSERT INTO stanza VALUES('K1117','chorus','성도들아담대-하라 주가 부른-다<br/>일어나라그 땅 점령하여라<br/>',NULL,29292,2);
INSERT INTO stanza VALUES('K1117','2','주가함께 하-니 담대하여라주를 말해 내어<br/>원수를 밟자 우리 행동 그-분 경륜에 맞춰<br/>주와 하나 되-어- 주 역사 쓰자<br/>',NULL,29293,3);
INSERT INTO stanza VALUES('K1117','3','붉은줄 드리-운 라합과 같이 믿음으로주께<br/>가족 이끌자 하나님의백-성 향해 돌이켜<br/>주의 구원 가져오는 사람이 되자<br/>',NULL,29294,4);
INSERT INTO stanza VALUES('K1117','4','제사장들로-서 언약궤 메고 그분 죽음 안에<br/>발을 내딛자 일렁이는파-도 두려워 말고<br/>모두 지나갈 때까지 굳게 서 있자<br/>',NULL,29295,5);
INSERT INTO stanza VALUES('K1117','5','하나님역사-의 부분인 우리 얽매임들 벗고<br/>굳건히 서자 오늘 이 땅 위-에 주 권익 위해<br/>위대한 그 바-퀴의 한 부분 되자<br/>',NULL,29296,6);
INSERT INTO stanza VALUES('K1118','1','그분이 우리 모든 것 되길<br/>영원서부터 갈망하신 주<br/>우릴 배필로 조성하시어<br/>그분께 맞는 신부 되게 해<br/>',NULL,29297,1);
INSERT INTO stanza VALUES('K1118','2','이 계획 따라 태초로부터<br/>그 형상대로 창조된 사람<br/>독립하여서 행동함으로<br/>대적의 미혹에 넘어갔네<br/>',NULL,29298,2);
INSERT INTO stanza VALUES('K1118','3','여전히 우릴 사랑하신 주<br/>이 땅에 오셔 뱀을 깨셨네<br/>자신 낮추어 죽으심으로<br/>그분의 신부 구출하셨네<br/>',NULL,29299,3);
INSERT INTO stanza VALUES('K1118','4','당신은 우리 영웅이시니<br/>우릴 온전히 다 드립니다<br/>변함없는 그 크신 사랑이<br/>우리 맘 다 얻으셨습니다<br/>',NULL,29300,4);
INSERT INTO stanza VALUES('K1118','5','공과를 배운 아내이오니<br/>매일 당신의 덮으심 아래<br/>무슨 일에나 당신께 묻고<br/>늘 주와 하나 돼 살렵니다<br/>',NULL,29301,5);
INSERT INTO stanza VALUES('K1118','6','이 하나로써 승리 얻을 때<br/>저 원수 대적 수치당하니<br/>주 증가로써 배필 건축해<br/>당신 맘 만족게 하렵니다<br/>',NULL,29302,6);
INSERT INTO stanza VALUES('K1119','1','해 아래 새 것이- 없나니 이 죄인 살리신 주<br/>보라 새롭게 된 이 피조물 주의 놀라운 권능<br/>찬양하세 우리 주 오 주여 영광 받으소서<br/>새롭게 하소서 새롭게 하소서<br/>새롭게 하소서 늘 새롭게 하소서<br/>',NULL,29303,1);
INSERT INTO stanza VALUES('K112','1','승리의 주 존귀 영광 갖고 개가 크게 부르며<br/>구름 타고 하늘 왕궁 향해 올라가셨네<br/>천사들도 소리 모아 할렐루야 찬송해 하늘 성문<br/>고-개- 들어 주님을 환영해 천국 왕 환-영하네<br/>',NULL,29304,1);
INSERT INTO stanza VALUES('K112','2','희년 기쁜 나-팔- 소리 영광 가져오신 왕<br/>만군의 하나님 예수 이미 승리하셨네<br/>십자가의 고난 이겨 무덤에서 일어나 죄와 사탄<br/>진-멸-했네 주님의 죽음이 원수 소멸-하셨네<br/>',NULL,29305,2);
INSERT INTO stanza VALUES('K112','3','손을 들어 축-복-한 주 그때 이 땅 떠나서<br/>제자들이 바라볼 때 구름 위로 가셨네<br/>하나님과 동행하며 하나님 기쁘게 해 진리 심판<br/>전하신 참 에녹 하늘에 올라가 하나님께- 나갔네<br/>',NULL,29306,3);
INSERT INTO stanza VALUES('K112','4','참된 아론 지-성-소에 피 가지고 나갔네<br/>참 여호수아 가나안에 가서 왕들 이겼네<br/>하나님의 택한 백성 좋은 땅에 심었네 참 엘리야<br/>축-복-주네 이중 복 이중 복 하늘의 복- 내렸네<br/>',NULL,29307,4);
INSERT INTO stanza VALUES('K112','5','주는 인성 올-리-셨네 하나님 우편으로<br/>우린 그와 함께 앉아 영광 안에 거하네<br/>천사들도 경배하네 왕이 되신 예수께 나도 함께<br/>승-리-하리 주 승천 안에서 나도 승리-하겠네<br/>',NULL,29308,5);
INSERT INTO stanza VALUES('K1120','1','예수 결박 푸셨도다- 모든 결박 푸셨도다-<br/>나의 결박 푸셨도다-<br/>',NULL,29309,1);
INSERT INTO stanza VALUES('K1120','chorus','나는 자유-해-<br/>',NULL,29310,2);
INSERT INTO stanza VALUES('K1120','2','소리 높여 할렐루야- 소리 높여 할렐루야-<br/>소리 높여 할렐루야-<br/>',NULL,29311,3);
INSERT INTO stanza VALUES('K1120','3','모든 영광 하나님께- 모든 영광 하나님께-<br/>모든 영광 하나님께-<br/>',NULL,29312,4);
INSERT INTO stanza VALUES('K1120','4','찬양하리 영원토록- 찬양하리 영원토록-<br/>찬양하리 영원토록-<br/>',NULL,29313,5);
INSERT INTO stanza VALUES('K1121','1','그때 그 무리들이 예수님 못 박았네<br/>녹슨 세 개의 그 못으로-<br/>망치 소리 내 마음 울리면서 들렸네<br/>',NULL,29314,1);
INSERT INTO stanza VALUES('K1121','chorus','그 피로 내 죄 씻었-네-<br/>',NULL,29315,2);
INSERT INTO stanza VALUES('K1121','2','주여 저들의 죄를 용서하여 주소서<br/>주님 눈물로 기도했네-<br/>귀중한 그 보배 피 나를 위해 흘렸네<br/>',NULL,29316,3);
INSERT INTO stanza VALUES('K1121','3','비웃는 그 무리들 주의 옷 벗긴 후에<br/>주의 몸 깊이 상처냈네-<br/>귀중한 그 보배 피 나를 위해 흘렸네<br/>',NULL,29317,4);
INSERT INTO stanza VALUES('K1121','4','주여 나의 영혼을 받아 주시옵소서<br/>그때 구원을 이루셨네-<br/>마지막 피 한 방울 나를 위해 흘렸네<br/>',NULL,29318,5);
INSERT INTO stanza VALUES('K1122','1','나 같은- 죄인 살리신 주 은혜- 놀라워<br/>잃었-던- 생명 찾-았-고 광명을- 얻었네<br/>',NULL,29319,1);
INSERT INTO stanza VALUES('K1122','2','큰 죄악-에서 살리신 주 은혜- 고마와<br/>나 처-음- 믿은 그- 시-간 귀하고- 귀하다<br/>',NULL,29320,2);
INSERT INTO stanza VALUES('K1122','3','이제껏- 내가 산 것도 주님의- 은혜라<br/>또 나-를- 장차 본-향-에 인도해- 주시리<br/>',NULL,29321,3);
INSERT INTO stanza VALUES('K1122','4','거기서- 우리 영원히 주님의- 은혜로<br/>해처-럼- 밝게 살-면-서 주 찬양-하리라<br/>',NULL,29322,4);
INSERT INTO stanza VALUES('K1122','5','할렐루-야 할렐루야할렐루-야 아멘<br/>할렐-루-야 할렐-루-야 할렐루-야 아멘<br/>',NULL,29323,5);
INSERT INTO stanza VALUES('K1122','6','A maz-ing grace! how sweet the sound,<br/>That saved a wretch like me!<br/>I once was lost, but now am found,<br/>was blind, but now I see, Amem<br/>',NULL,29324,6);
INSERT INTO stanza VALUES('K1123','1','내 맘 속에 있는 참된 이 평화는 누구도<br/>앗아갈 수 없네- 주님은 내 맘에<br/>구주 되-셨네 오- 주 없인 살 수 없네-<br/>',NULL,29325,1);
INSERT INTO stanza VALUES('K1123','chorus','오- 주 없인 살 수 없네- 오직 주께만 구원있네<br/>주님 없는 세상 평화 없네 오 주 없인 살 수 없네-<br/>',NULL,29326,2);
INSERT INTO stanza VALUES('K1123','2','평화 없는 세상 고통과 싸움뿐 사람들은<br/>무서워 떠네- 평화의 주님이<br/>다시 올 때까지 죄와 전쟁은 끝이 없네-<br/>',NULL,29327,3);
INSERT INTO stanza VALUES('K1124','1','오 아름다운 날 즐거운 날 내 어이 잊으리오-<br/>어두움 속에서 헤매던 나 주 예수님 만났네-<br/>다정하고 따뜻한 내 친구 내 마음 채우셨네-<br/>어두움 물리친 구주 예수님을 기쁨으로 증거해-<br/>',NULL,29328,1);
INSERT INTO stanza VALUES('K1124','chorus','나 죄사함 받고- 밤이 밝은 낮 되었네<br/>하늘 영광 내 맘에 임했네- -<br/>',NULL,29329,2);
INSERT INTO stanza VALUES('K1124','2','성령이 내 맘을 주장하사 내 생활 변화되고-<br/>갈보리 십자가 그 사랑이 내 죄를 사하셨네-<br/>이전에 죄악된 내 생활은 모두 다 물러가고-<br/>놀라운 주 은혜 넘치게 주시니 주 이름 찬양하세-<br/>',NULL,29330,3);
INSERT INTO stanza VALUES('K1124','3','세월은 흘러도 내 맘 속엔 희망은 변함 없고-<br/>하늘의 확실한 참 소망은 나 항상 갖고 있네-<br/>놀라운 그 축복 받은 날은 내 주님 알게 된 날-<br/>영원한 하늘의 고귀한 축복은 내 주님 알게 된 날<br/>',NULL,29331,4);
INSERT INTO stanza VALUES('K1125','1','죄인들을 위하여 주님 찾아 오셨네<br/>주 안에 생명이 있네-<br/>죄인들을 위하여 주님 찾아 왔으나<br/>사람들 영접 안했네-<br/>',NULL,29332,1);
INSERT INTO stanza VALUES('K1125','chorus','예수 안에 생명 있네 주님이 빛이 되시네 -<br/>예수 안에 생명 있네 주님이 빛이 되시네 -<br/>',NULL,29333,2);
INSERT INTO stanza VALUES('K1125','2','주님 영접하는 자 하나님의 자녀요<br/>그 안에 생명이 있네-\<br/>주님 앞에 오시오 어서 빨리 오시오<br/>주 안에 생명이 있네-<br/>',NULL,29334,3);
INSERT INTO stanza VALUES('K1125','3','He - came un -to his own, and his own<br/>re -ceived him not-<br/>But his life is the light of men -<br/>He - came un -to his own<br/>and his own re -ceived him not<br/>But his life is the light of men -<br/>In Him is life, In Him is life,<br/>and His life is the light of men -<br/>In Him is life, in Him is life,<br/>and His life is the light of men -<br/>',NULL,29335,4);
INSERT INTO stanza VALUES('K1126','1','이 세상의 친구들 나를 버려도<br/>나를 사랑하는 이 예수 뿐일세<br/>',NULL,29336,1);
INSERT INTO stanza VALUES('K1126','chorus','예수 내 친구 날 버리잖네<br/>온 천지는 변해도 날 버리지 않네<br/>',NULL,29337,2);
INSERT INTO stanza VALUES('K1126','2','검은 구름 덮이고 광풍 일어도<br/>예수 나의 힘 되니 겁낼 것 없네<br/>',NULL,29338,3);
INSERT INTO stanza VALUES('K1126','3','괴로운 일 당해도 낙심 말아라<br/>영원한 그 사랑이 주 안에 있네<br/>',NULL,29339,4);
INSERT INTO stanza VALUES('K1127','1','주 은혜를 받으려 모여 온 우리 주 크신 뜻 깨닫게 하시오니<br/>고통스런 멍에를 나 벗은 후에 그 자비하신 이름 찬양하리<br/>',NULL,29340,1);
INSERT INTO stanza VALUES('K1127','2','주 우리들 곁에서 인도하시니 그 거룩한 나라가 이뤄진다<br/>원수들과 싸워서 늘 승리하여 큰 영광 주께 돌려 찬양하리<br/>',NULL,29341,2);
INSERT INTO stanza VALUES('K1127','3','우리들의 방패와 창검이 되사 승리하신 주님을 기립니다<br/>큰 환난을 당할 때 늘 도우시니 승전가 높이 불러 찬양하리<br/>',NULL,29342,3);
INSERT INTO stanza VALUES('K1128','1','주께 두 손 모아 비나니 크신 은총 베푸사<br/>밝아 오는 이- 아침을 환히 비춰 주소서<br/>오- 주 우리 모든 허물을 보혈의 피로 씻기어<br/>하-나님 사랑 안에서 행복을- 갖게 하소서<br/>서-로 믿음 안에서 서-로 소망 가운데<br/>서-로 사랑 안에서 손잡고 가는 길<br/>',NULL,29343,1);
INSERT INTO stanza VALUES('K1128','chorus','오- 주 사랑의 종소리가 사-랑의 종소리가<br/>이 시간 우리 모두를 감싸게 하여 주소서<br/>',NULL,29344,2);
INSERT INTO stanza VALUES('K1128','2','주께 두 손 모아 비나니 크신 은총 베푸사<br/>주가 예비하신 동산에 항상 있게 하소서<br/>오- 주 우리 맘에 새 빛이 어두움 밝게 하시고<br/>진-리의 말씀 안에서 늘 순종-하게 하소서<br/>서-로 참아 주면서 서-로 감싸 주면서<br/>서-로 사랑 안에서 주께로 가는 길<br/>',NULL,29345,3);
INSERT INTO stanza VALUES('K1128','1','다시 은혜로 날 일으켜 새 날 주신 하나님<br/>밝아 오는 이 아침에 주 흠뻑마십니다<br/>주와 입 맞추며 시작한 이 행복한 하루를<br/>신성한 생명 안에서 왕 노릇 하게 하소서<br/>',NULL,29346,4);
INSERT INTO stanza VALUES('K1128','chorus','나는 주님 안에서 주는 나의 안에서<br/>서로 안에 거하며 동역게 하소서<br/>삼일 하나님의 합병이 내 안에 더 확장돼<br/>벽옥의 새 예루살렘 이루게 하소서<br/>',NULL,29347,5);
INSERT INTO stanza VALUES('K1128','2','오늘 내게주신 이 하루 주께 감사합니다<br/>해 저무는 이 저녁에 주께 경배합니다<br/>주와 동역하며 순종한 이 즐거운 하루를<br/>평강의 주님과 함께 안식을 누립니다<br/>',NULL,29348,6);
INSERT INTO stanza VALUES('K1129','1','눈을 들어 하늘 보라 어지러운 세상 중에<br/>곳곳마다 상한 영의 탄식 소리 들려온다<br/>빛을 잃은 많은 사람 길을 잃고 헤매이며<br/>탕자처럼 기진하니 믿는 자여 어이할꼬<br/>',NULL,29349,1);
INSERT INTO stanza VALUES('K1129','2','눈을 들어 하늘 보라 어두워진 세상 중에<br/>외치는 자 많건마는 생명수는 말랐어라<br/>죄를 대속하신 주님 선한 일꾼 찾으시나<br/>대답할 이 어디있나 믿는 자여 어이할꼬<br/>',NULL,29350,2);
INSERT INTO stanza VALUES('K1129','3','눈을 들어 하늘 보라 살아계신 주 하나님<br/>약한 자를 부르시어 하늘 뜻을 전하셨다<br/>생명수는 홀로 예수 처음이요 나중이라<br/>주님 너를 부르신다 믿는 자여 어이할꼬<br/>',NULL,29351,3);
INSERT INTO stanza VALUES('K1129','4','눈을 들어 하늘 보라 다시 사신 그리스도<br/>만 백성을 사랑하사 오래 참고 기다리셔<br/>인애하신 우리 구주 의의 심판 하시는 날<br/>곧 가까이 임하는데 믿는 자여 어이할꼬<br/>',NULL,29352,4);
INSERT INTO stanza VALUES('K113','1','오 예수 이름 존귀해 권능의 주 이름<br/>만유의 주께 경-배-해 면류관 드리-세<br/>만유의 주께 경-배-해 면류관 드-리세<br/>',NULL,29353,1);
INSERT INTO stanza VALUES('K113','2','역대의 모든 순교자 제단서 외치네<br/>이새의 가지 높-이-세 소리를 합하-여<br/>이새의 가지 높-이-세 소리를 합-하여<br/>',NULL,29354,2);
INSERT INTO stanza VALUES('K113','3','아담의 구속된 후예 타락을 벗어나<br/>은혜를 입고 구-원-돼 만유 주 경배-해<br/>은혜를 입고 구-원-돼 만유 주 경-배해<br/>',NULL,29355,3);
INSERT INTO stanza VALUES('K113','4','쓸개와 신 포도주를 못 잊을 죄인아<br/>오늘도 주께 나-아-와 만유의 주 보-라<br/>오늘도 주께 나-아-와 만유의 주-보라<br/>',NULL,29356,4);
INSERT INTO stanza VALUES('K113','5','온 땅의 모든 백성들 구주께 환호해<br/>영광과 존귀 돌-리-세 만유의 주님-께<br/>영광과 존귀 돌-리-세 만유의 주-님께<br/>',NULL,29357,5);
INSERT INTO stanza VALUES('K113','6','우뢰와 같은 찬송에 나 또한 엎드려<br/>만유의 주께 영-원-히 찬송과 경배-해<br/>만유의 주께 영-원-히 찬송과 경-배해<br/>',NULL,29358,6);
INSERT INTO stanza VALUES('K1130','1','탕자처럼 방황-할 때도 애타게 기다리는-<br/>부드런 주님의 음성이 내 맘을 녹이셨네-<br/>오 주님 나 이제 갑니다 날 받아 주소-서-<br/>이제는 주님만 위하여 이 몸을 바치리라-<br/>',NULL,29359,1);
INSERT INTO stanza VALUES('K1130','2','불순종한 요나와 같이도 방황하던 나에게-<br/>따뜻한 주님의 손길이 내 손을 잡으셨네-<br/>오 주님 나 이제 갑니다 날 받아 주소-서-<br/>이제는 주님만 위하여 이 생명 바치리라-<br/>',NULL,29360,2);
INSERT INTO stanza VALUES('K1130','3','죄 많은 저 고멜과 같이도 방황하던 나에게-<br/>너그런 주님의 용서가 내 맘을 녹이셨네-<br/>오 주님 나 이제 갑니다 날 받아 주소-서-<br/>이제는 주님만 위하여 죽도록 충성하리<br/>',NULL,29361,3);
INSERT INTO stanza VALUES('K1131','1','예수- 귀하신 이름-<br/>아-름다운- 영광의 주- - -<br/>임마누엘- 함께 하시는-<br/>은혜의 구주- 말씀이라-<br/>',NULL,29362,1);
INSERT INTO stanza VALUES('K1131','2','성령- 놀라운 이름-<br/>아-름다운- 위로의 주- - -<br/>임마누엘- 함께하시는-<br/>거룩하신 주- 보혜사라-<br/>',NULL,29363,2);
INSERT INTO stanza VALUES('K1131','3','하나님- 사랑의 이름-<br/>아-름다운- 권능의 주- - -<br/>임마누엘- 함께 하시는-<br/>전능하신 주- 여호와라-<br/>',NULL,29364,3);
INSERT INTO stanza VALUES('K1132','1','내 맘에 한 노래 있어 나 즐겁게 늘 부르네<br/>이 노래를 부를 때에 큰 평화 임하도다<br/>',NULL,29365,1);
INSERT INTO stanza VALUES('K1132','chorus','평화 평화 하나님이 주신 선물<br/>오 크고 놀라운 평화- 하나님 선물일세<br/>',NULL,29366,2);
INSERT INTO stanza VALUES('K1132','2','주 십자가에 달리사 내 빚을 갚아 주셨고<br/>주 예수님 고난 받아 나 평화 누리도다<br/>',NULL,29367,3);
INSERT INTO stanza VALUES('K1132','3','나 주께 영광 돌릴 때 이 평화 충만하도다<br/>주 하나님 축복으로 이 평화 누리도다<br/>',NULL,29368,4);
INSERT INTO stanza VALUES('K1132','4','이 평화를 얻으려고 주 앞으로 나아갈 때<br/>주 예수님 우리에게 이 평화 주시도다<br/>',NULL,29369,5);
INSERT INTO stanza VALUES('K1133','1','누구든지 목마르거든 내게로 와서 마셔라<br/>누구든지 목마르거든 내게로 와서 마셔라<br/>',NULL,29370,1);
INSERT INTO stanza VALUES('K1133','chorus','나를 믿는 자는- 성경에 이름과 같이<br/>그 배에서 생수의 강이 흘러나리라<br/>',NULL,29371,2);
INSERT INTO stanza VALUES('K1133','2','누구든지 예수 믿으면 구원을 얻으리로다<br/>누구든지 예수 믿으면 구원을 얻으리로다<br/>',NULL,29372,3);
INSERT INTO stanza VALUES('K1133','3','누구든지 예수 믿으면 영생을 얻으리로다<br/>누구든지 예수 믿으면 영생을 얻으리로다<br/>',NULL,29373,4);
INSERT INTO stanza VALUES('K1133','4','누구든지 예수 믿으면 기쁨을 얻으리로다<br/>누구든지 예수 믿으면 기쁨을 얻으리로다<br/>',NULL,29374,5);
INSERT INTO stanza VALUES('K1134','1','이 시간 주님께 기도합니다<br/>영원한 생명을 주신 주님-께<br/>아 메마른 저 곳에 참 사랑이 되신 주<br/>아 차가운 저 곳에 참 소망이 되신 주<br/>경건한 맘으로 기도합니다<br/>영원한 생명을 주신 주님-께<br/>',NULL,29375,1);
INSERT INTO stanza VALUES('K1134','2','이 시간 주님께 기도합니다<br/>진실한 사랑을 주여 주옵소서<br/>아 메마른 저 곳에 참 사랑이 되신 주<br/>아 차가운 저 곳에 참 소망이 되신 주<br/>경건한 맘으로 기도합니다<br/>진실한 사랑을 주여 주옵소서<br/>',NULL,29376,2);
INSERT INTO stanza VALUES('K1135','1','이 세상 유혹 우리 맘을 끌어도<br/>난 구주 예수 사랑합니다<br/>좋은 것이 많아도 많은 친구 있어도<br/>구주 예수 외에는 모두 헛되네<br/>',NULL,29377,1);
INSERT INTO stanza VALUES('K1135','chorus','예수 내- 친구 어이 멀리하리요<br/>예수 내- 주만 사랑하겠네<br/>',NULL,29378,2);
INSERT INTO stanza VALUES('K1135','2','젊은 우리 맘 쉽게 요동하지만<br/>주님의 사랑 잊을 수 없네<br/>그는 우리 위하여 십자가를 지셨네<br/>물과 피를 흘리며 죽임 당했네<br/>',NULL,29379,3);
INSERT INTO stanza VALUES('K1135','3','장미빛 유혹 떨치기 어렵지만<br/>주님의 사랑 내 맘 녹이네<br/>베드로를 바라 본 인자하신 주의 눈<br/>오늘 내 맘 만지니 감사 한없네<br/>',NULL,29380,4);
INSERT INTO stanza VALUES('K1135','4','주 떠난 시간 어둡고 불안했네<br/>주 안에 올 때 밝고 평안해<br/>이젠 속지 않으리 사탄의 거짓 기쁨<br/>이젠 가지 않으리 세상 친구들<br/>',NULL,29381,5);
INSERT INTO stanza VALUES('K1135','5','오늘 우리는 하나님의 자녀요<br/>구주의 은혜 얻은 자일세<br/>장래 우린 주님을 섬길 사람들이요<br/>세상에게 내어 줄 사람 아닐세<br/>',NULL,29382,6);
INSERT INTO stanza VALUES('K1135','6','주님의 갈망 우리 얻는 것이니<br/>우리의 일생 주께 드리리<br/>우리 일생 투자해 그리스도 얻으리<br/>영광스런 하나님 일꾼 되리라<br/>',NULL,29383,7);
INSERT INTO stanza VALUES('K1136','1','호산-나 호산-나 호산-나- 찬미하세<br/>호산-나 호산-나 호산-나- 찬미하세<br/>주의 이름으로 오신 크신 왕<br/>겸손하여 어린 나귀 타셨네<br/>어린아이 젖먹이들 외치니 호산-나- 찬미하세<br/>',NULL,29384,1);
INSERT INTO stanza VALUES('K1136','2','호산-나 호산-나 호산-나- 찬미하세<br/>호산-나 호산-나 호산-나- 찬미하세<br/>우리 모두 겉옷 벗어 드리며<br/>나뭇가지 베어 길에 펴면서<br/>앞에 가고 혹은 뒤에 따르며 호산나- 찬미하세<br/>',NULL,29385,2);
INSERT INTO stanza VALUES('K1136','3','주 예-수 주 예-수 주 예-수- 불러보세<br/>주 예-수 주 예-수 주 예-수- 불러보세<br/>주의 이름 모르는 자 성내나<br/>어린아이 젖먹이들 외치네<br/>겸손하여 어린 나귀 타신 왕 주 예수- 불러보세<br/>',NULL,29386,3);
INSERT INTO stanza VALUES('K1137','1','이 세상에서 가장 큰 축복 주 믿는 것<br/>이 세상에서 가장 큰 기쁨 주 믿는 것<br/>이 세상에서 가장 큰 사랑 주의 사랑<br/>이 세상에서 가장 큰 선물 구주 예수<br/>',NULL,29387,1);
INSERT INTO stanza VALUES('K1137','chorus','믿으-면 영생 얻네 믿으면 기쁨 얻네<br/>',NULL,29388,2);
INSERT INTO stanza VALUES('K1137','2','이 세상에서 가장 큰 승리 주 십자가<br/>이 세상에서 가장 큰 비밀 그리스도<br/>이 세상에서 가장 큰 능력 부활 능력<br/>내 마음 속에 살아 계시네 영원토록<br/>',NULL,29389,3);
INSERT INTO stanza VALUES('K1138','1','주 안에 자라라 훈계를 받으며<br/>너희는 우리의 사랑하는 자<br/>너희들이 주- 사랑할 때<br/>우리는 세상에 바랄게 없다<br/>',NULL,29390,1);
INSERT INTO stanza VALUES('K1138','2','주님만 사랑해 마음을 다하여<br/>너희는 우리의 사랑하는 자<br/>이 세상엔 아- -무 것도<br/>바랄 것 가질 것 전혀 없단다<br/>',NULL,29391,2);
INSERT INTO stanza VALUES('K1138','3','주 안에 성장해 사랑을 받으며<br/>너희는 우리의 사랑하는 자<br/>너희들이 주- 말해낼 때<br/>우리는 기뻐서 춤을 춘단다<br/>',NULL,29392,3);
INSERT INTO stanza VALUES('K1139','1','주 믿는 성도여 아브라함같이<br/>갈데아 우르 우상의 땅 떠나<br/>만유 포함한 좋은 땅으로<br/>우리 모두 힘차게 주 따라 가자<br/>',NULL,29393,1);
INSERT INTO stanza VALUES('K1139','2','헛된 일 버리고 바벨탑 깨뜨려<br/>하나님 믿고 순간순간 살자<br/>우리의 소망 하나님 자신<br/>이 땅 누림 버리고 하나님 얻자<br/>',NULL,29394,2);
INSERT INTO stanza VALUES('K114','1','보라 영광 면류관 쓴 하나님의 어린 양<br/>영광 존귀 주께 돌려<br/>지극히 높-은 곳에 이르신 주 예수께<br/>',NULL,29395,1);
INSERT INTO stanza VALUES('K114','2','하늘 보좌 위에 오른 놀라우신 주 예수<br/>성도들의 노래 제목<br/>아버지의- 사랑의 보물이신 주 예수<br/>',NULL,29396,2);
INSERT INTO stanza VALUES('K114','3','그는 높고 크시어도 우리 찬송 기뻐해<br/>우리 찬송 미약해도<br/>구주의 귀에 들리네 기꺼이 열납하네<br/>',NULL,29397,3);
INSERT INTO stanza VALUES('K114','4','죽음 당한 어린 양께 높여진 어린양께<br/>보좌 위에 앉은 주께<br/>나의 찬송-드리리 오직 그분에게만<br/>',NULL,29398,4);
INSERT INTO stanza VALUES('K114','5','전에 사람 멸시 받던 주 이제 존귀 받네<br/>면류관과 높은 위치<br/>본래 그의- 것이니 거리낌 없이 받네<br/>',NULL,29399,5);
INSERT INTO stanza VALUES('K1140','1','하나님은 창조해 그의 형상 따라서<br/>영과 혼과 몸 있는 그릇으로 사람을<br/>존귀한 사람 이 땅 다스려<br/>주 나타내네 하나님 담아서-<br/>',NULL,29400,1);
INSERT INTO stanza VALUES('K1140','2','사탄에게 유혹돼 선악 열매 먹은 뒤<br/>나무 잎새 엮어서 가렸지만 헛되네<br/>타락한 사람 구속하시려<br/>양 잡아 주님 옷 입혀주셨네-<br/>',NULL,29401,2);
INSERT INTO stanza VALUES('K1140','3','믿음으로 아벨은 양을 잡아드렸네<br/>하나님은 열납해 뜻에 따른 제물을<br/>타락한 사람 제물 필요해<br/>아벨과 같이 양 제물 드리세-<br/>',NULL,29402,3);
INSERT INTO stanza VALUES('K1140','4','비로소 깨달았네 사람의 약한 것을<br/>그러므로 에노스 주의 이름 불렀네<br/>오 주 예수여 오 주 예수여<br/>오 주 예수여 그 이름 부르세-<br/>',NULL,29403,4);
INSERT INTO stanza VALUES('K1140','5','타락한 세대에서 하나님과 동행해<br/>죽음 맛보지 않고 데려가심 얻었네<br/>삼백 년 동안 동행한 에녹<br/>주 데려갔네 상 얻게 하셨네-<br/>',NULL,29404,5);
INSERT INTO stanza VALUES('K1140','6','죄가 가득한 때에 의로웠던 노아는<br/>하나님 은혜 입어 하나님과 동역해<br/>방주 건축해 세상 심판해<br/>주님과 함께 새 시대 열었네-<br/>',NULL,29405,6);
INSERT INTO stanza VALUES('K1140','7','반역의 땅 가운데 아브라함 불러내<br/>본토 친척 떠나서 약속의 땅 주셨네<br/>하나님 약속 모든 이방들<br/>그 자손 통해 복 얻게 하셨네-<br/>',NULL,29406,7);
INSERT INTO stanza VALUES('K1140','8','은혜 안에 태어나 은혜 안에 자라나<br/>은혜 안에 후사 돼 모든 기업 얻었네<br/>이삭의 순종 아들 나타내<br/>주 일으켰네 리브가 얻었네-<br/>',NULL,29407,8);
INSERT INTO stanza VALUES('K1140','9','창세 전에 선택돼 사랑하심 받았네<br/>많은 환경 통과해 처리받고 변화돼<br/>부러진 야곱 하나님 왕자<br/>생명의 성숙 사람을 축복해-<br/>',NULL,29408,9);
INSERT INTO stanza VALUES('K1140','10','꿈꾸는 자 요셉은 애굽 땅에 팔리어<br/>많은 고생했으나 하나님은 기억해<br/>원망 없었네 사랑 충만해<br/>양식 공급하며 온 땅을 통치해-<br/>',NULL,29409,10);
INSERT INTO stanza VALUES('K1141','1','찬양과 존귀와 영광을 주께 예수께 돌려<br/>주께 돌려 찬양과 존귀와 영광을<br/>주께 예수께 돌려<br/>영원토록 주를 찬미하-세<br/>성도들 모두 경배 찬미해 할렐루야<br/>찬양과 존귀와 영광을 주께 예수께 돌려<br/>주께 돌려 찬양과 존귀와 영광을<br/>주께 예수께 돌려<br/>',NULL,29410,1);
INSERT INTO stanza VALUES('K1142','1','할렐루 할렐루 할렐루 할렐루야 주 찬양해<br/>할렐루 할렐루 할렐루 할렐루야 주 찬양해<br/>주 찬양해 할렐루야 주 찬양해 할렐루야<br/>주 찬양해 할렐루야 주 찬양해<br/>',NULL,29411,1);
INSERT INTO stanza VALUES('K1143','1','아멘 주 예수여 아멘 아멘 언제든지<br/>성경의 말씀에 아멘 구절마다 아멘<br/>귀한건 오직 주님의 산 말씀 뿐이니<br/>아멘 주여 주신 말씀 믿고 순종하리<br/>',NULL,29412,1);
INSERT INTO stanza VALUES('K1143','2','아멘 교회에 또 아멘 아멘 그 길따라<br/>앞서가는 발걸음을 따라가며 아멘<br/>어떤 환경 어떤 시험 다가오더라도<br/>지난 실패 다 잊고서 또 다시 아-멘<br/>',NULL,29413,2);
INSERT INTO stanza VALUES('K1144','1','할렐루야- 할렐루야- 할렐루야- 할렐루-야-<br/>할렐루야- 할렐루야- 할렐루야- 할렐루야<br/>예수님은- 나의 구주- 예수님은- 나의 구-주-<br/>예수님은- 나의 구주- 예수님은- 나의 구주<br/>예수님은- 나의 구주- 예수님은- 나의 구-주-<br/>예수님은- 나의 구주- 예수님은- 나의 구주<br/>',NULL,29414,1);
INSERT INTO stanza VALUES('K115','1','보-라 하늘 보-좌 위에 인-자 예수 앉-았네<br/>하-나님이 높-인 사람 영-광의 관 쓰셨네<br/>',NULL,29415,1);
INSERT INTO stanza VALUES('K115','2','하-나님의 계-획 따라 죽-으신 인자- 예수<br/>몸-을 갖고 다-시 살아 승-천한 사람일세<br/>',NULL,29416,2);
INSERT INTO stanza VALUES('K115','3','이- 땅에서 예-수 안에 하-나님 낮춰-지고<br/>하-늘에서 예-수 안에 사-람은 높여졌네<br/>',NULL,29417,3);
INSERT INTO stanza VALUES('K115','4','하-나님은 사-람 통해 자-신 나타내-시고<br/>하-나님과 하나 된 사람 보-좌 영광 얻었네<br/>',NULL,29418,4);
INSERT INTO stanza VALUES('K115','5','영-광 얻은 그-는 이제 만-유 포함한- 성령<br/>인-자 예수 모-든 역사 성-령 안에 있다네<br/>',NULL,29419,5);
INSERT INTO stanza VALUES('K115','6','그-가 영광 얻-을 때에 교회도 영광 얻-었네<br/>이- 영광을 성-령 안에 모-든 지체 누리네<br/>',NULL,29420,6);
INSERT INTO stanza VALUES('K115','7','보-라 하늘 보-좌 위에 인-자 예수 앉-았네<br/>만- 주의 주 우-리 구주 영-광의 관 쓰셨네<br/>',NULL,29421,7);
INSERT INTO stanza VALUES('K115','8','보-라 주가 분-배하네 그-는 우리 모-든 것<br/>조-성하여 산-출하네 영-광의 이기는 자<br/>',NULL,29422,8);
INSERT INTO stanza VALUES('K116','1','주 예수 나를 위하여 그 온유한 걸음으로<br/>수치의 길 갔네 그 모든 역사 이루고<br/>주 하나님께 높여져 모든 열매 갖고<br/>',NULL,29423,1);
INSERT INTO stanza VALUES('K116','2','가시에 찔린 주 머리 영광의 관을 쓰시고<br/>보좌에 앉았네 난 진정 주를 찬송해<br/>주 영영 경배하겠네 주만이 존귀해<br/>',NULL,29424,2);
INSERT INTO stanza VALUES('K116','3','보좌에 계신 머리와 온 지체들 연결될 때<br/>주 예수 소유를 다함께 누릴 수 있네<br/>주님의 영광과 보좌 권위와 천국을<br/>',NULL,29425,3);
INSERT INTO stanza VALUES('K116','4','주 승리 인해 우리도 다 즐거웁게 찬송해<br/>주 나와 하날세 주 고난 당하셨으나<br/>그 보좌 주께 속했네 참 기쁨 넘치네<br/>',NULL,29426,4);
INSERT INTO stanza VALUES('K117','1','만유의 주 보좌 오르셨네<br/>면류관 얻으신 어린 양이 영원히 사셔서<br/>초월하셔 온 만유 위에 더 뛰어나네<br/>',NULL,29427,1);
INSERT INTO stanza VALUES('K117','chorus','못 박히신 예수 이제 만유 위에 가장 뛰어나네<br/>그 발등상 앞에 경배하세 주 하나님께서 높이신 주<br/>',NULL,29428,2);
INSERT INTO stanza VALUES('K117','2','광풍이 불어와 날 삼키고<br/>파도가 몰아쳐 엄몰할 때 파도 위 걸어온 구주<br/>나를 평안히 육지로 인도하네<br/>',NULL,29429,3);
INSERT INTO stanza VALUES('K117','3','나아갈 그 성은 높고 크나<br/>장애물 힘써 날 붙잡으나 뛰어난 주<br/>믿고 담대하게 나아가 하나씩 이기겠네<br/>',NULL,29430,4);
INSERT INTO stanza VALUES('K117','4','온 땅의 만물과 모든 왕국<br/>뛰어난 주님께 굴복하네 이기는 자 모두<br/>주와 함께 온 만유 위에 더 뛰어나네<br/>',NULL,29431,5);
INSERT INTO stanza VALUES('K118','1','가-시관 썼던 주 머리- 영광의 관 썼네<br/>우-리의 머리 되신 주- 이미 승천했네<br/>',NULL,29432,1);
INSERT INTO stanza VALUES('K118','2','주는 땅의 성도의 기쁨- 하늘의 빛이요<br/>날-사랑의 강 마시어- 그 깊이 알게 해<br/>',NULL,29433,2);
INSERT INTO stanza VALUES('K118','3','주- 치욕 또한 권위 다- 나에게 줍소서<br/>세-상이 부인한 주를- 하나님은 높여<br/>',NULL,29434,3);
INSERT INTO stanza VALUES('K118','4','주-님과 고난 받는 자- 곧 영광 얻으리<br/>세-상의 쾌락 멸시하게 날 잡아 주소서<br/>',NULL,29435,4);
INSERT INTO stanza VALUES('K118','5','치-욕과 죽음 십자가- 내겐 생명이요<br/>내 영광과 권세요 또- 영원한 안식처<br/>',NULL,29436,5);
INSERT INTO stanza VALUES('K119','1','영광 영광 높이 오른 그리스도께 돌려<br/>영광 영광 높여 지신 구주께로 돌리세<br/>존귀하고 높은 이름 주가 이미 얻었네<br/>하늘과 땅 땅 아래의 만물이 주 찬송해<br/>',NULL,29437,1);
INSERT INTO stanza VALUES('K119','2','하늘 영광 보좌에서 거하시던 당신이<br/>종의 형체 입고 오셔 고난 인생 가셨네<br/>아버지의 뜻을 따라 죽기까지 순종해<br/>십자가의 죽음 수치 남기잖고 받았네<br/>',NULL,29438,2);
INSERT INTO stanza VALUES('K119','3','자신 낮춘 주 예수께 하늘 영광 돌려져<br/>존귀하신 그 이름에 모든 무릎 굴복해<br/>모든 입이 그를 주라 시인하며 찬송해<br/>천지의 주 만세의 왕 모두 함께 찬양해<br/>',NULL,29439,3);
INSERT INTO stanza VALUES('K119','4','보배롭고 측량 못할 그리스도께 영광<br/>하늘과 땅 모든 영광 그분께로 돌리세<br/>자존자인 하나님께 영광 존귀 돌리세<br/>영광 영광 영원토록 그리스도께 영광<br/>',NULL,29440,4);
INSERT INTO stanza VALUES('K12','1','주 하나님 지으신 모든 세계 내 마음 속에 그리어 볼 때<br/>하늘의 별 울려퍼지는 뇌성 주님의 권능 우주에 찼네<br/>',NULL,29441,1);
INSERT INTO stanza VALUES('K12','chorus','주님의 높고 위대하심을 내 영혼이 찬양하네<br/>주님의 높고 위대하심을 내 영혼이 찬양하네<br/>',NULL,29442,2);
INSERT INTO stanza VALUES('K12','2','숲속이나 험한 산골짝에서 지저귀는 저 새소리들과<br/>고요하게 흐르는 시냇물은 주님의 솜씨 노래하도다<br/>',NULL,29443,3);
INSERT INTO stanza VALUES('K12','3','주 하나님 독생자 아낌없이 우리를 위해 땅에 보내어<br/>십자가에 피 흘려 죽게 하사 내 모든 죄를 구속하셨네<br/>',NULL,29444,4);
INSERT INTO stanza VALUES('K12','4','나 바라던 기한이 차게 될 때 새 예루살렘 참예케 되리<br/>옛 것 지나 온 천지 새로울 때 주 어떠하심 온전히 알리<br/>',NULL,29445,5);
INSERT INTO stanza VALUES('K120','1','주 예수는 곧 만유의 주 영광-관 썼네<br/>주의- 권-위 위-엄 인해 다 주를- 찬양해<br/>',NULL,29446,1);
INSERT INTO stanza VALUES('K120','2','사람이 되어 노예로서 사신- 주 이제<br/>하나-님- 안에- 하늘에서 존귀-하시네<br/>',NULL,29447,2);
INSERT INTO stanza VALUES('K120','3','주 예수님이 하나님과 보좌-에 앉아<br/>하늘-과- 땅의- 모든 권세 다 얻-으셨네<br/>',NULL,29448,3);
INSERT INTO stanza VALUES('K120','4','주께서 승천하여 얻은 귀한- 이름에<br/>모든- 입- 주라- 시인하고 무릎-을 꿇네<br/>',NULL,29449,4);
INSERT INTO stanza VALUES('K120','5','성령이 주가 그리스도 되심- 증거해<br/>영광- 안-에 하-늘 위에서 보좌- 얻었네<br/>',NULL,29450,5);
INSERT INTO stanza VALUES('K120','6','영광의 주께 경배하며 높이- 찬미해<br/>만유-의- 주와- 만왕의 왕 높이- 찬미해<br/>',NULL,29451,6);
INSERT INTO stanza VALUES('K121','1','고난당한 아들 예수 크신- 영광 얻었네<br/>전쟁에서 승리하여 큰 보-좌에 앉았네<br/>관 씌우세 관 씌우세 왕 중 왕께 관 씌워<br/>',NULL,29452,1);
INSERT INTO stanza VALUES('K121','2','사람들의 희롱받고 가시-관을 쓰신 주<br/>이제 영광 관 쓰시니 모든- 성도 경배해<br/>관 씌우세 관 씌우세 사랑하는 아들게<br/>',NULL,29453,2);
INSERT INTO stanza VALUES('K121','3','죄인들아 관 씌우자 우리- 구주 예수께<br/>그의 보좌 우리 맘에 자리- 잡게 하여라<br/>관 씌우세 관 씌우세 죄인들의 은인께<br/>',NULL,29454,3);
INSERT INTO stanza VALUES('K121','4','들어 보라 성도들의 승리-에 찬 환호를<br/>높이 오른 주 예수님 우릴- 열광케 하네<br/>관 씌우세 관 씌우세 극히 높은 예수께<br/>',NULL,29455,4);
INSERT INTO stanza VALUES('K122','1','영광 안에 계신 예수 영 안에 주목할 때<br/>세상에서 능욕받은 사실 읽게 된다네<br/>',NULL,29456,1);
INSERT INTO stanza VALUES('K122','2','가시관 쓴 머리 보고 사람들 비웃었네<br/>주의 맘에 받은 상처 이제 영광 되었네<br/>',NULL,29457,2);
INSERT INTO stanza VALUES('K122','3','버림 받고 십자가에 홀로 못 박힌 주님<br/>오늘은 아버지 앞에 높이 올려지셨네<br/>',NULL,29458,3);
INSERT INTO stanza VALUES('K122','4','아버지도 듣지 않은 주님의 부르짖음<br/>여위신 주 얼굴에서 아버지 영광 보네<br/>',NULL,29459,4);
INSERT INTO stanza VALUES('K122','5','귀하신 주 주목할 때 우리 찬양 넘치네<br/>찬송 받기 합당하신 어린 양께 찬송해<br/>',NULL,29460,5);
INSERT INTO stanza VALUES('K122','6','우리 맘아 일어나서 주님을 찬미하라<br/>아버지와 아들에게 찬송 감사 돌리세<br/>',NULL,29461,6);
INSERT INTO stanza VALUES('K123','1','크신 주의 맘의 사랑 그리스도 은혜여<br/>우리 맘과 혼을 다해 당신 앞에 경배해<br/>경배하며 찬미해 비교 못할 주의 길<br/>',NULL,29462,1);
INSERT INTO stanza VALUES('K123','2','기름 부름 받은 왕이 영광에 들어갔네<br/>전에 사람 조소 받고 싫어한 바 되었네<br/>사랑하며 칭송해 존귀 영광 얻은 주<br/>',NULL,29463,2);
INSERT INTO stanza VALUES('K123','3','우릴 축복하신 주님 대신 저주 받았네<br/>고난 받고 순종 배운 아버지 귀한 아들<br/>앙망하며 기념해 고난의 땅 가신 주<br/>',NULL,29464,3);
INSERT INTO stanza VALUES('K123','4','주님 머리에 관 쓰고 철장 권세 가지리<br/>우린 그리스도 지금 강림하길 기다려<br/>사랑하며 순종해 하나님 그리스도<br/>',NULL,29465,4);
INSERT INTO stanza VALUES('K124','1','왕 중 왕-인 주님께 안 돌아올 자 누구랴-<br/>하나님의 그리스도 경외하-며 존중해<br/>왕 중 왕인 당신을 천만 성도가 찬양해<br/>',NULL,29466,1);
INSERT INTO stanza VALUES('K124','2','이 나라부터 저 나라 모두 주-가 다스려-<br/>만민 주-께 돌아와 왕인 당-신 섬기리<br/>왕 중 왕-인 당신을 찬양 안할 자 누구랴<br/>',NULL,29467,2);
INSERT INTO stanza VALUES('K124','3','주의 왕-국 영원해 주의 보-좌 견고해-<br/>주의 영-광 왕권을 영원토-록 찬양해<br/>왕 중 왕-인 당신을 천만 성-도 찬양해<br/>',NULL,29468,3);
INSERT INTO stanza VALUES('K124','4','사랑의-주 왕 중 왕 존귀한 이름 좋아해-<br/>주의 통-치 친근해 왕국 속-히 임하리<br/>왕 중 왕-인 당신을 여기에-서 찬양해<br/>',NULL,29469,4);
INSERT INTO stanza VALUES('K125','1','주- 하나님의 그리스도 왕 중 왕-일-세-<br/>다 엎드려- 경배해 높-이 주 찬-양해<br/>주- 왕국 무궁하며 주-보좌 견고해-<br/>주 다스림- 공평해 그- 영광 뛰-어나<br/>',NULL,29470,1);
INSERT INTO stanza VALUES('K125','2','하-나님 주를 세웠네 거룩한 시-온서-<br/>만국을 기-업으로 당-신께 주-었네<br/>권-위 다 맡기셨네 온-전히 당신께-<br/>끝없이 영-원토록 만-국을 다-스려<br/>',NULL,29471,2);
INSERT INTO stanza VALUES('K125','3','아-직은 때가 안- 차 흑암이 다스려도-<br/>주님께 충-성하는 성-도들 많-다네<br/>바-다 이편 저편서 주- 향해 노래해-<br/>그들의 왕-인 주를 경-배해 섬-기네<br/>',NULL,29472,3);
INSERT INTO stanza VALUES('K125','4','예-정된 그날 올- 때 주 강림하-시리-<br/>온 땅과 열-국 모두 주-님께 돌-아가<br/>위-엄과 빛 가득한 왕-되어 다스려-<br/>각 민족 나-라들이 주- 찬양하-리라<br/>',NULL,29473,4);
INSERT INTO stanza VALUES('K126','1','내 구-주 사-랑 참-되고- 또 광대하-여라-<br/>내 맘과 생명 힘-을 다- 주-께 드-리-겠네<br/>',NULL,29474,1);
INSERT INTO stanza VALUES('K126','2','내 사-랑 주-께 비-하면- 아무 것 아-닐세-<br/>십자가 치욕 견-딘 주- 어-찌 사랑 않-을까<br/>',NULL,29475,2);
INSERT INTO stanza VALUES('K126','3','친구- 위해- 죽은- 사람- 자랑을 하-지만-<br/>당신은 원수 위-하여- 생-명을- 주-셨네<br/>',NULL,29476,3);
INSERT INTO stanza VALUES('K126','4','영광-의 하-늘 거-하던- 하나님 형-상이-<br/>노예로 오셔 질-고와- 슬-픔 경-험-했네<br/>',NULL,29477,4);
INSERT INTO stanza VALUES('K126','5','모든- 일을- 우리-처럼- 다 겪으셨-지만-<br/>죄 없는 주님 우-리로- 주- 닮게- 하-시네<br/>',NULL,29478,5);
INSERT INTO stanza VALUES('K126','6','모든- 일에- 당신-처럼- 강하고 온-유해-<br/>영광 위에 영광- 더해- 변- 화되-기- 원해<br/>',NULL,29479,6);
INSERT INTO stanza VALUES('K126','7','우리- 주님-의 사-랑을- 마음에 간-직해-<br/>그 존귀하신 이-름에- 감-사를- 드-리리<br/>',NULL,29480,7);
INSERT INTO stanza VALUES('K127','1','예-수 내 영광의 왕 그 사랑 넓도다<br/>보좌를 버리고 세상에 오셔<br/>구-유에 탄생하사 애굽에 피하고<br/>또 갈릴리 나사렛에서 사셨네<br/>인생의 삼십삼 년 멸시를 받으며<br/>널리 다니시며 복음 전했네<br/>굶주림 지침 속에 쉴 곳도 없었네<br/>아름답고 선한 깊고 긴 사랑<br/>',NULL,29481,1);
INSERT INTO stanza VALUES('K127','2','예-수 내 구세의 왕 그 사랑 강권해<br/>겟세마네에서 간구하셨네<br/>아-버지 뜻을 따라 순종의 기도로<br/>몸을 버려 세상 구하시려고<br/>수치와 고난 속에 조소를 참으며<br/>십자가를 지고 골고다 향해<br/>수-족에 못 박히고 피와 물 흘리신<br/>아름답고 선한 깊고 긴 사랑<br/>',NULL,29482,2);
INSERT INTO stanza VALUES('K127','3','예-수 내 승리의 왕 그 사랑 무한해<br/>십자가에 달려 기도하셨네<br/>못- 박힌 한 강도가 산 소망 얻었네<br/>주는 죄 짐 지고 버림받았네<br/>아픔과 갈함 속에 쓸개와 초 맛봐<br/>구-속의 싸움 승리하셨네<br/>무-덤서 부활하사 승천해 기도해<br/>아름답고 선한 깊고 긴 사랑<br/>',NULL,29483,3);
INSERT INTO stanza VALUES('K127','4','예-수 내 평강의 왕 그 사랑 넘치네<br/>나 같은 죄인을 위해 죽었네<br/>내- 모든 죄를 씻고 상처를 고치사<br/>가르치며 갈 길 인도하시네<br/>대적이 흉악해도 주는 내 방패니<br/>내가 연약할 때 주 내 힘이라<br/>나-의 주 내 맘 속에 평강의 왕 되니<br/>아름답고 선한 깊고 긴 사랑<br/>',NULL,29484,4);
INSERT INTO stanza VALUES('K128','1','주 은혜 놀라우니 주 앞에 엎드려<br/>나 같은 괴수 구해 돌아오게 했네<br/>늘 항상 주를 피해 이 세상 탐낸 나<br/>왜 찾아내어 주사 그 팔로 감싸나<br/>',NULL,29485,1);
INSERT INTO stanza VALUES('K128','2','나 죄악에 묶여서 참 괴로웠지만<br/>구원을 거절했네 주 그때 오셨네<br/>난 주의 음성 듣고 무관심했었네<br/>늘 주를 반대한 나 참 주의 원술세<br/>',NULL,29486,2);
INSERT INTO stanza VALUES('K128','3','왜 나를 위해 주가 죄 담당하셨나<br/>저 십자가에 달려 죽으셔야 했나<br/>난 누구보다 악해 육체를 위했네<br/>죄 많은 나를 어찌 주 사랑하셨나<br/>',NULL,29487,3);
INSERT INTO stanza VALUES('K128','4','그 천하고도 낮은 말구유에 났네<br/>주 낮추고 또 낮춰 인생길 가셨네<br/>내 어떤 점이 좋아 날 사랑하셨나<br/>왜 나를 사랑하여 복 얻게 하셨나<br/>',NULL,29488,4);
INSERT INTO stanza VALUES('K128','5','난 남보다도 나은 고상한 점 없네<br/>그 무엇이 주 오셔 죽으시게 했나<br/>나에겐 주 기쁘게 할 것도 없는데<br/>주 나를 위해 어찌 그 목숨 버렸나<br/>',NULL,29489,5);
INSERT INTO stanza VALUES('K128','6','주 조건 없이 나를 사랑해 주셨네<br/>이 은혜는 말로 모두 표현 못하네<br/>난 선하지도 않고 귀하지도 않아<br/>주 이유 없이 괴수 사랑해 주셨네<br/>',NULL,29490,6);
INSERT INTO stanza VALUES('K128','7','은혜 받은 나 응당 주 사랑해야 해<br/>주 순종해야 주께 보답할 수 있네<br/>지금도 나의 마음 차갑기만 하네<br/>주 사랑 알면서도 반응이 없다네<br/>',NULL,29491,7);
INSERT INTO stanza VALUES('K128','8','날 위해 목숨 버린 주께 난 무정해<br/>날 위해 하늘 떠난 주 나는 의심해<br/>좁은 길 원망하며 이 세상 못 버려<br/>묵묵한 주 원망해 자신을 못 놓네<br/>',NULL,29492,8);
INSERT INTO stanza VALUES('K128','9','오 나의 성품 너무 부패되었다네<br/>오 나의 생활 심히 악할 뿐이라네<br/>주님은 내 이러함 잘 모르셨을까<br/>냉담한 내게 왜 애초 은혜 주셨나<br/>',NULL,29493,9);
INSERT INTO stanza VALUES('K128','10','오 주님 어찌하여 차가운 날 위해<br/>세상의 모든 수모 감당하셨나요<br/>왜 이러한 나 위해 죽으셨던가요<br/>이 악한 자를 위해 못 박히셨나요<br/>',NULL,29494,10);
INSERT INTO stanza VALUES('K128','11','늘 잘 변하는 나를 잘 아시면서도<br/>주 날 사랑해 죽고 또 다시 사셨네<br/>이 사랑 생각할 때 눈물이 흐르네<br/>그 조건 없는 사랑 늘 감사드리네<br/>',NULL,29495,11);
INSERT INTO stanza VALUES('K128','12','내 주의 큰 사랑을 난 이해 못하네<br/>주 기이하심 항상 찬송 경배하리<br/>하늘의 복락 크나 내 마음은 오직<br/>내 주 하나님 항상 찬송하고 싶네<br/>',NULL,29496,12);
INSERT INTO stanza VALUES('K128','13','빛나는 영광 안에 늘 찬송하리라<br/>하늘에 속한 성에 늘 안식하면서<br/>말로 다 할 수 없는 그 크신 사랑을<br/>다 보답할 수 없는 그 크신 은혜를<br/>',NULL,29497,13);
INSERT INTO stanza VALUES('K129','1','기묘하신 나의 구주 비할 데 없는 큰 사랑<br/>바다보다도 더 깊고 하늘보다도 더 높네<br/>새롭고도 오랜 사랑 언제나 어디서든지<br/>참된 주 그를 찬양해<br/>',NULL,29498,1);
INSERT INTO stanza VALUES('K129','2','존귀한 곳 하늘 보좌 버리고 이 땅에 오셔<br/>잃은 양들 찾으려고 영광 버리고 오셨네<br/>하늘의 복 다 버리고 견고한 그 사랑으로<br/>내 주님 나를 찾았네<br/>',NULL,29499,2);
INSERT INTO stanza VALUES('K129','3','외로운 길 가신 주님 동정하는 자 없었네<br/>마음 같이하는 자도 동반자도 없었지만<br/>뒤돌아보지 않고서 나아가신 주님 이제<br/>내 안에 들어오셨네<br/>',NULL,29500,3);
INSERT INTO stanza VALUES('K129','4','사람에게 팔린 그 날 사람들의 고소받고<br/>굴욕과 고통 속에서 가시면류관 쓰고서<br/>채찍 맞으며 골고다 홀로 나 위해 오르신<br/>내 주님 나를 구했네<br/>',NULL,29501,4);
INSERT INTO stanza VALUES('K129','5','죽기까지 나는 그를 그 사랑을 간증하리<br/>이 세상의 그 무엇과 바꿀 수 없는 그 사랑<br/>그의 얼굴 친히 뵈올 그날 올 때까지 나는<br/>주님을 찬양하리라<br/>',NULL,29502,5);
INSERT INTO stanza VALUES('K13','1','신실한 하나님 오 내 아버지 영원히 변찮는 그 큰 사랑<br/>긍휼과 자비로 날 품으시니 언제나 당신만 향합니다<br/>',NULL,29503,1);
INSERT INTO stanza VALUES('K13','chorus','신실한 하나님 신실한 하나님 긍휼과 은혜가 풍성하셔<br/>내 모든 필요함 다 공급하셔 신실한 하나님 내 아버지<br/>',NULL,29504,2);
INSERT INTO stanza VALUES('K13','2','해와 달 별들이 제 궤도 돌며 온 세상 만물과 증거하네<br/>당신의 변찮는 신실하심을 긍휼과 큰 사랑 나타내네<br/>',NULL,29505,3);
INSERT INTO stanza VALUES('K13','3','신실한 하나님 당신 자신이 나에게 위로와 길 되시네<br/>당신 자신만이 오늘 내 능력 내일의 찬란한 소망 되네<br/>',NULL,29506,4);
INSERT INTO stanza VALUES('K130','1','넓고- 깊은 주의- 사-랑 나는- 측-량 못-하리<br/>바다- 보다 깊고- 넓-어 이 사-랑- 날 이-끄네<br/>자신- 버린 그 큰- 사랑 나로- 주님 얻게- 해<br/>나로- 주와 하나-되-고 주의- 지-체 되-게 해<br/>',NULL,29507,1);
INSERT INTO stanza VALUES('K130','2','이 사-랑의 크신- 역-사 말로- 다- 할 수- 없네<br/>이 큰- 사랑 나를- 주-와 하나-되-게 하-셨네<br/>주가- 나의 모든- 것 돼 모든- 공급 됐으-니<br/>나는- 다만 주를- 누-려 시시-때-때로- 누려<br/>',NULL,29508,2);
INSERT INTO stanza VALUES('K130','3','이 사-랑은 주님- 자-신 거룩-하-신 주- 예수<br/>내 인-생의 뜻 되-신- 주 주만- 나-를 살-게 해<br/>주는- 나의 생명- 능력 나로- 누리게 하-네<br/>나는- 주의 사랑의 대-상 주 은-혜-의 대상일세<br/>',NULL,29509,3);
INSERT INTO stanza VALUES('K130','4','그 무-엇도 끊지- 못-해 영원-한- 우리- 사랑<br/>주와- 나는 영원히 하-나 그 무-엇-도 못- 나눠<br/>이 사-랑 날 강권-하니 주를- 높이 찬양-해<br/>나는- 주가 되고- 또-한 주는- 내-가 된-다네<br/>',NULL,29510,4);
INSERT INTO stanza VALUES('K131','1','광야에서 표류-한 나 사랑으로 찾아서<br/>은혜의 손으로 끌어 부축하신 내 주님<br/>정녕 주 날 사랑-해 십자가에 죽었네<br/>',NULL,29511,1);
INSERT INTO stanza VALUES('K131','2','동산에서 들려-오는 울음소리 무언가<br/>모든 제자 졸던 그때 주가 기도함일세<br/>정녕 주 날 위하-여 자기 목숨 버렸네<br/>',NULL,29512,2);
INSERT INTO stanza VALUES('K131','3','하나님의 공의- 분노 주가 대신 맛봤네<br/>죄인 위해 그 쓴 잔을 기꺼이 다 마셨네<br/>정녕 주 날 사랑-해 자신을 다 버렸네<br/>',NULL,29513,3);
INSERT INTO stanza VALUES('K131','4','참담한 마지막- 모습 하나님의 심판이<br/>파도처럼 홍수처럼 주께 엄습하였네<br/>정녕 주 날 위하-여 자신을 다 버렸네<br/>',NULL,29514,4);
INSERT INTO stanza VALUES('K131','5','주가 고통당함-으로 날 새 창조 되게 한<br/>측량할 수 없는 사랑 비할 데 없는 사랑<br/>정녕 주 날 위하-여 자기 생명 버렸네<br/>',NULL,29515,5);
INSERT INTO stanza VALUES('K131','6','들어보라 아버-지를 찾는 저 부르짖음<br/>내 하나님 내 하나님 왜 날 버리십니까<br/>정녕 주 날 위하-여 자기 생명 버렸네<br/>',NULL,29516,6);
INSERT INTO stanza VALUES('K131','7','주의 고난 인해- 나는 이제 기쁨 누리네<br/>승천한 주 아버지의 우편에서 영존해<br/>정녕 난 주 위하-여 자신 바쳐 살겠네<br/>',NULL,29517,7);
INSERT INTO stanza VALUES('K131','8','주 놀라운 은혜- 인해 우린 주께 경배해<br/>온전하게 하시는 주 향해 우린 찬송해<br/>“정녕 주 날 위하-여 자신을 다 버렸네”<br/>',NULL,29518,8);
INSERT INTO stanza VALUES('K132','1','끝이 없는 길이와 끝이 없는 넓이와<br/>하늘같은 높-이와 바다 같은 깊-이의 그 큰 사랑<br/>',NULL,29519,1);
INSERT INTO stanza VALUES('K132','chorus','그리스도 사랑 크고도 커 측량 못할<br/>큰 사랑 충만하게 내게 영영 임했네<br/>',NULL,29520,2);
INSERT INTO stanza VALUES('K132','2','목숨 버린 긴 사랑 구원의 넓은 사랑<br/>나를 높인 높은 사랑 내 생활에 임-하신 깊은 사랑<br/>',NULL,29521,3);
INSERT INTO stanza VALUES('K132','3','날 사하신 긴 사랑 은혜의 넓은 사랑<br/>하늘 앉힌 높은 사랑 나의 안에 사-신 깊은 주 사랑<br/>',NULL,29522,4);
INSERT INTO stanza VALUES('K132','4','길이 넓이 무엔가 높이 깊이 무엔가<br/>도량 척도 아-니요 그리스도 큰- 사랑 가리키네<br/>',NULL,29523,5);
INSERT INTO stanza VALUES('K133','1','만인 위에 뛰어난 주 오 그 사랑!<br/>혈육보다 강한 사랑 오- 그 사랑!<br/>친구들은 날 떠나고 시간 따라 변하지만<br/>이 친구는 변치 않네 오 그 사랑!<br/>',NULL,29524,1);
INSERT INTO stanza VALUES('K133','2','나는 이제 평강 누려 오 그 사랑!<br/>죄 빚 대신 갚아 주신 오- 그 사랑!<br/>보혈 흘려 날 사한 주 광야에 와 날 찾았네<br/>양무리로 날 인도해 오 그 사랑!<br/>',NULL,29525,2);
INSERT INTO stanza VALUES('K133','3','주 예수는 우리 친구 오 그 사랑!<br/>축복 주며 은혜 주네 오- 그 사랑!<br/>난 기뻐 주 앙망하고 주는 나를 안주케 해<br/>내 어찌 주 미워하랴 오 그 사랑!<br/>',NULL,29526,3);
INSERT INTO stanza VALUES('K133','4','나를 사한 주의 이름 오 그 사랑!<br/>내게 축복 임하게 한 오- 그 사랑!<br/>원수들의 목전에서 잔치상을 베푸시네<br/>영광에 날 이끄시는 오 그 사랑!<br/>',NULL,29527,4);
INSERT INTO stanza VALUES('K134','1','내 구주 예수 크신 사랑을<br/>그 누가 측량할 수 있으랴<br/>그 높이 깊이 길이 넓이를<br/>나에게 알려 주의 능력 나타내게 해<br/>',NULL,29528,1);
INSERT INTO stanza VALUES('K134','2','내 구주 예수 친근한 사랑<br/>그 누가 다 말할 수 있으랴<br/>내 입술 열어 가르치겠네<br/>근심을 풀며 기쁨 주는 주의 사랑을<br/>',NULL,29529,2);
INSERT INTO stanza VALUES('K134','3','내 구주 예수 놀라운 사랑<br/>누가 다 찬양할 수 있으랴<br/>이 사랑 항상 노래하겠네<br/>나같이 악한 자도 은혜로 적시는 주<br/>',NULL,29530,3);
INSERT INTO stanza VALUES('K134','4','이 넘쳐나는 주의 사랑을<br/>다 찬송하지 못할지라도<br/>사랑의 이 샘으로 가오니<br/>내 공허한 맘 주여 채워 주시옵소서<br/>',NULL,29531,4);
INSERT INTO stanza VALUES('K134','5','난 공허하고 공허한 그릇<br/>주 깊이 사모하지 않으나<br/>주 나를 사랑하심 알므로<br/>주 긍휼 얻기 위해 지금 주 앞에 오네<br/>',NULL,29532,5);
INSERT INTO stanza VALUES('K134','6','주 사랑으로 날 채우시고<br/>영원한 강에 인도하소서<br/>다른 것 구하지 않게 하사<br/>단순한 믿음으로 주 누리게 하소서<br/>',NULL,29533,6);
INSERT INTO stanza VALUES('K134','7','내 구주 얼굴 마주 대하며<br/>그 보좌 앞에 엎드릴 때에<br/>그 깊고 높고 넓고 긴 사랑<br/>기이히 여겨 노래하며 경배하겠네<br/>',NULL,29534,7);
INSERT INTO stanza VALUES('K135','1','천만의 입이 있-어도 내 구-주 찬미하리-<br/>그 깊고 깊은 은-혜와 풍성-한 영-광을<br/>',NULL,29535,1);
INSERT INTO stanza VALUES('K135','2','내 고통 위로하는 이름 두려-움 쫓는 이름-<br/>내 안식 나의 생-명과 내 음-악 되-었네<br/>',NULL,29536,2);
INSERT INTO stanza VALUES('K135','3','내 주님 날 사랑-하사 고초- 다 겪-었네-<br/>죄 권세 이미 소-멸해 죄에-서 해-방해<br/>',NULL,29537,3);
INSERT INTO stanza VALUES('K135','4','그 사랑 생각할- 때에 난 자-격 없-다네-<br/>죄인 중 괴수 어-찌해 주가- 사랑-했나<br/>',NULL,29538,4);
INSERT INTO stanza VALUES('K135','5','주 사랑의 포로-되길 난 기-꺼이- 원해-<br/>날 자유케 하시-려고 주 죽-으셨-기에<br/>',NULL,29539,5);
INSERT INTO stanza VALUES('K135','6','주님이 나를 대-하신 선한- 뜻 알-기에-<br/>천만 개 마음 있-어도 다 주-께 드-리리<br/>',NULL,29540,6);
INSERT INTO stanza VALUES('K136','1','주 사-랑하-는 자 다 와-서 찬미해<br/>주 달콤한 사-랑 함께 누리며 보-좌 앞에 가자<br/>',NULL,29541,1);
INSERT INTO stanza VALUES('K136','chorus','즐겁-고 즐-거워 값없-는 은혜여!<br/>참 즐-겁도-다 완전하-신 용-서받-았네<br/>',NULL,29542,2);
INSERT INTO stanza VALUES('K136','2','주 이-름 모르는 자 잠잠-하게 두라<br/>주 백-성 은-혜 받았으-니 기-뻐 뛰-겠네<br/>',NULL,29543,3);
INSERT INTO stanza VALUES('K136','3','영광-의 성-에서 정금-길 걷기 전<br/>이 실-과 풍-성 달콤함-을 미-리 맛-보네<br/>',NULL,29544,4);
INSERT INTO stanza VALUES('K136','4','아픔-다 잊-고서 크게- 다 찬송해<br/>하늘-에 속-한 더 좋은- 집 향-해 나-가자<br/>',NULL,29545,5);
INSERT INTO stanza VALUES('K137','1','주 나 위해 존귀 버려 천한 곳에 오셨네<br/>십자가의 쓴 맛보고 모든 죄 담당했네<br/>바다보다도 더 깊은 은혜<br/>보답 못할 큰 은혜에 사랑 드리네<br/>',NULL,29546,1);
INSERT INTO stanza VALUES('K138','1','주는 하나님 보물 하나님의 기쁨<br/>기쁨의 기름 받아 동류보다- 승-해<br/>',NULL,29547,1);
INSERT INTO stanza VALUES('K138','chorus','우리의 마음으로 주 선함 감상해<br/>당-신의 향기로움 달콤함 감상해<br/>',NULL,29548,2);
INSERT INTO stanza VALUES('K138','2','세상 모든 이보다 더 아름다운 주<br/>사랑스런 주 입엔 은혜가 충-만-해<br/>',NULL,29549,3);
INSERT INTO stanza VALUES('K138','3','주 나실 때 박사들 보물을 바쳤네<br/>나실 때부터 주는 존경을 받-았-네<br/>',NULL,29550,4);
INSERT INTO stanza VALUES('K138','4','주 죽으실 때 그 몸 향료로 감쌌네<br/>주님의 마지막도 여전히 사랑스러워<br/>',NULL,29551,5);
INSERT INTO stanza VALUES('K138','5','주의 머리와 발에 기름 부어졌네<br/>당신의 모든 부분 다 사랑스-러-워<br/>',NULL,29552,6);
INSERT INTO stanza VALUES('K138','6','주 죽음 몰약같이 우리 맘 안위해<br/>주 부활 향료같이 하나님 만-족게 해<br/>',NULL,29553,7);
INSERT INTO stanza VALUES('K138','7','주 향기 몰약 같고 그 고벨화 같아<br/>사과나무와 같이 무성하고- 달-아<br/>',NULL,29554,8);
INSERT INTO stanza VALUES('K138','8','술보다 나은 사랑 향 같은 그 이름<br/>주 보물 삼은 우리 늘 주를 생-각-해<br/>',NULL,29555,9);
INSERT INTO stanza VALUES('K138','9','다만 주 선하심만 묵상하지 않고<br/>우리 주 달콤함을 더욱더 맛-보-리<br/>',NULL,29556,10);
INSERT INTO stanza VALUES('K139','1','보좌에 앉은 주 예수 머리에 관썼네<br/>거룩 존귀 장엄한 주 입-에 은혜 넘쳐 입에 은혜 넘쳐<br/>',NULL,29557,1);
INSERT INTO stanza VALUES('K139','2','이 땅의 모든 사람들 주와 비교 못해<br/>홀로 아름다우신 주 비-할 자 없겠네 비할 자 없겠네<br/>',NULL,29558,2);
INSERT INTO stanza VALUES('K139','3','주는 내 생명 호흡과 내 기쁨 되시니<br/>죽음의 능력 이기고 흑-암 떠나게 해 흑암 떠나게 해<br/>',NULL,29559,3);
INSERT INTO stanza VALUES('K139','4','내 거처인 하나님께 내 걸음 이끌어<br/>하나님 영광 더하여 날- 기쁘게 하네 날 기쁘게 하네<br/>',NULL,29560,4);
INSERT INTO stanza VALUES('K139','5','풍성한 그의 은혜로 그 사랑 알았네<br/>천만 개 마음 있어도 다- 주께 드리리 다 주께 드리리<br/>',NULL,29561,5);
INSERT INTO stanza VALUES('K14','1','오 하나님의 미쁘심 그 신실하심을<br/>온 만물들이 간증하며 선포하도다<br/>',NULL,29562,1);
INSERT INTO stanza VALUES('K14','chorus','오 변치 않는 신실함에 경배드리세<br/>오 영원토록 요동하지 않는 하나님<br/>',NULL,29563,2);
INSERT INTO stanza VALUES('K14','2','늘 변함없네 회전하는 그림자 없네<br/>전에도 있고 이제 있고 장차 오실 분<br/>',NULL,29564,3);
INSERT INTO stanza VALUES('K14','3','오 당신처럼 그 말씀도 영영 신실해<br/>온 천지는 다 없어져도 말씀 영원해<br/>',NULL,29565,4);
INSERT INTO stanza VALUES('K14','4','당신의 선택 부르심엔 후회 없으니<br/>당신의 은혜 긍휼 또한 변치 않으리<br/>',NULL,29566,5);
INSERT INTO stanza VALUES('K14','5','당신의 말씀 신실함이 내 보증이니<br/>나 이로 인해 주의 구원 굳게 확신해<br/>',NULL,29567,6);
INSERT INTO stanza VALUES('K140','1','사랑스런 나의 신랑 주 예수는 내 사랑<br/>주님 자신 날 이끄니 어찌 사랑 않으리<br/>',NULL,29568,1);
INSERT INTO stanza VALUES('K140','2','사랑스런 주의 귀함 말로 다할 수 없네<br/>주의 사랑 참된 사랑 무한한 사랑일세<br/>',NULL,29569,2);
INSERT INTO stanza VALUES('K140','3','아름답고 아름다와 달콤하고 달콤해<br/>부드럽고 친근한 주 완전하신 나의 주<br/>',NULL,29570,3);
INSERT INTO stanza VALUES('K140','4','주의 옷엔 몰약 넘쳐 주의 입 은혜로와<br/>고난당한 향기 안에 주의 귀함 간직해<br/>',NULL,29571,4);
INSERT INTO stanza VALUES('K140','5','즐거움의 기름 받아 동류보다 승한 주<br/>상아궁들 발해 내네 주께 대한 찬미를<br/>',NULL,29572,5);
INSERT INTO stanza VALUES('K140','6','이제 영광 관 쓰신 주 보좌 위에 계시네<br/>그 무엇도 비교 못할 주의 권세 주 위엄<br/>',NULL,29573,6);
INSERT INTO stanza VALUES('K140','7','모든 열방 사모하리 주의 가치 다 알리<br/>찬양받기 합당한 주 만인 위에 뛰어나<br/>',NULL,29574,7);
INSERT INTO stanza VALUES('K141','1','주님을 생각할 때에- 내 마음 달-콤해<br/>사랑스런 주 곁으로- 나 들림받겠네<br/>',NULL,29575,1);
INSERT INTO stanza VALUES('K141','chorus','참 아름다운 고벨화는 저 포도원에 있으니<br/>참 아름다운 당신을- 우리는 그리네<br/>',NULL,29576,2);
INSERT INTO stanza VALUES('K141','2','주 은혜 모두 표현할- 노래는 없-다네<br/>주 사랑 모두 누릴 맘- 가진 자도 없네<br/>',NULL,29577,3);
INSERT INTO stanza VALUES('K141','3','주님의 사랑 은혜 날- 기쁘게 했-지만<br/>주님 자신만 나의 맘- 심히 만족케 해<br/>',NULL,29578,4);
INSERT INTO stanza VALUES('K141','4','저 하늘에도 땅에도- 사모할 것- 없네<br/>오 아름답고 달콤한- 주님만 내 사랑<br/>',NULL,29579,5);
INSERT INTO stanza VALUES('K142','1','땅의 모든 꽃들보다 향기로운 주님<br/>당신은 하늘의 향유 내마음 속 몰약 향낭<br/>봄 날 미풍처럼 내 품속에 오네<br/>',NULL,29580,1);
INSERT INTO stanza VALUES('K142','2','맑은 아침 이슬처럼 주님 날 적실 때<br/>목마름은 사라지고 신선함만 가득 차네<br/>내 맘 속 깊은 곳 흠뻑 적셔 주네<br/>',NULL,29581,2);
INSERT INTO stanza VALUES('K142','3','누가 능히 비교하랴 아름다운 주와<br/>주님의 빛나는 얼굴 그 귀함 내 맘 녹이네<br/>아름다운 자 중 아름다우신 주<br/>',NULL,29582,3);
INSERT INTO stanza VALUES('K142','4','영원히 뛰어난 이름 향기로운 이름<br/>어찌 찬송치 않으랴 내 깊은 속에서부터<br/>주를 찬송할 때 기쁨 넘쳐나네<br/>',NULL,29583,4);
INSERT INTO stanza VALUES('K142','5','사랑하는 주님에게 내 모든 것 말해<br/>부드럽고 온유하신 그 마음 날 붙드시니<br/>나는 속삭이네“주님만 내 사랑”<br/>',NULL,29584,5);
INSERT INTO stanza VALUES('K143','1','아름다운 예수 대자연의 주-인<br/>하나님 아들 사람 아들 영원한 말-씀<br/>내 사랑 내 감동 내 기쁨 내 자랑일세<br/>',NULL,29585,1);
INSERT INTO stanza VALUES('K143','2','저푸른 잔디와 보암직한 수-풀<br/>봄날의 화사한 꽃보다 더 아름다운 주<br/>더 달콤한 예수 상처 받은 맘 치료해<br/>',NULL,29586,2);
INSERT INTO stanza VALUES('K143','3','맑고 아름다운 해와 달보다-도<br/>반짝이는 별-들보다 더욱더 밝-고<br/>더 맑은 예-수 천체보다 더 승하네<br/>',NULL,29587,3);
INSERT INTO stanza VALUES('K143','4','하늘의 모든 것 이 땅의 모든- 것<br/>그 모든 아름다움보다 더 빛나는- 분<br/>더 사랑스런 분 더 뛰어난 구주 예수<br/>',NULL,29588,4);
INSERT INTO stanza VALUES('K144','1','어디-부터 말하-리요 주 내-게 주-신 축-복을<br/>노예- 풀려 죽음- 피해 원수-됨 벗-게 하셨네<br/>어떻-게 주 경배-하고 높여야 합-당하리요<br/>',NULL,29589,1);
INSERT INTO stanza VALUES('K144','2','어떻-게 다 말하-리요 주께-서 주-신 평-강을<br/>불 못-에 갈 진노- 자식 구원-해 아-들 되게 해<br/>내 모-든 죄 다 도-말해 하늘의 축-복 주시네<br/>',NULL,29590,2);
INSERT INTO stanza VALUES('K144','3','우리- 맘에 주 충-만해 그 풍-성 나-타내-겠네<br/>주는- 우리 노래- 제목 사랑-하는- 구주일세<br/>우리- 모든 입을- 열어 주님께 영-광 돌리네<br/>',NULL,29591,3);
INSERT INTO stanza VALUES('K144','4','이 세-상의 누구-보다 아름-답고- 거룩-한 주<br/>주의- 맘엔 사랑- 넘쳐 주 입-엔 은-혜 넘치네<br/>고난- 받고 몸 버-리신 주님께 영-영 찬송해<br/>',NULL,29592,4);
INSERT INTO stanza VALUES('K145','1','기묘하신 구주 왕 중 왕 예수<br/>천사들 경배해 우린 찬송해<br/>가장 아름다운 주께 경배해<br/>가장 아름다운 주께 노래해<br/>',NULL,29593,1);
INSERT INTO stanza VALUES('K145','2','땅의 모든 안락 빈 동굴이니<br/>주 없으면 모두 어둠이 되네<br/>그리스도 영광 하늘 빛이니<br/>예수의 영광 빛 땅을 비추네<br/>',NULL,29594,2);
INSERT INTO stanza VALUES('K145','3','주를 떠난 그때 사망에 잠겨<br/>주의 임재 안에 생명 왕성해<br/>우주 인류 천사 지으신 주님<br/>사람 성품 입고 세상에 왔네<br/>',NULL,29595,3);
INSERT INTO stanza VALUES('K145','4','아름다움 선함 예수께 있네<br/>하나님의 영광 광채인 예수<br/>주의 얼굴 본 자 은혜 받으리<br/>나도 이 은혜에 참예키 원해<br/>',NULL,29596,4);
INSERT INTO stanza VALUES('K146','1','주 하나님의 그리스도 함께-찬양해<br/>천만-의- 입이- 있다 해도 주만- 찬송해<br/>',NULL,29597,1);
INSERT INTO stanza VALUES('K146','2','이 찬송 오직 승천하신 어린 양께 돌려<br/>나 위-해- 자신- 낮추신 주 찬송-하겠네<br/>',NULL,29598,2);
INSERT INTO stanza VALUES('K146','3','주 예수만이 존귀 권위 영광- 얻도록<br/>우리-가- 드릴- 모든 찬송 주께- 드리리<br/>',NULL,29599,3);
INSERT INTO stanza VALUES('K146','4','곧 들림받을 승리자들 찬송-발하라<br/>저 하-늘- 아래- 거하는 자 다 찬-양하라<br/>',NULL,29600,4);
INSERT INTO stanza VALUES('K146','5','구속된 우주 하나 되길 다 기-다리며<br/>영광-을- 얻은- 어린 양을 다 찬-양하세<br/>',NULL,29601,5);
INSERT INTO stanza VALUES('K147','1','주님께 영-광을 돌리며 찬-송하세<br/>어린 양께 죽음과 슬픔을 제하신<br/>그 은혜 그 사랑 영원히 찬송하세<br/>',NULL,29602,1);
INSERT INTO stanza VALUES('K147','2','은혜 받은- 자들 보좌 앞에- 경배해<br/>어린 양께 하나님과 나의 간격을 제하고<br/>화목케 하려고 피 흘린 주<br/>',NULL,29603,2);
INSERT INTO stanza VALUES('K147','3','구속된 족-속들 다 와서 경-배하세<br/>어린 양께 주 은혜 인하여 즐거워하면서<br/>감사와 찬송을 맘껏 발해<br/>',NULL,29604,3);
INSERT INTO stanza VALUES('K147','4','온 세상 변-해도 내 찬미 변-치 않네<br/>어린 양께 쉬잖고 찬송해 나의 주 나의 왕<br/>환호가 궁창에 상달되네<br/>',NULL,29605,4);
INSERT INTO stanza VALUES('K148','1','보좌에 앉으신 주 예수 향해 찬미를 부르니<br/>참 기뻐라 축복받은 우린 경배하면서<br/>주만이 합당함 말하리라<br/>',NULL,29606,1);
INSERT INTO stanza VALUES('K148','chorus','주 당신만이 참 합당하네 찬양을<br/>받-기에 합당하네 축복받은 우리<br/>주 경배하며 주님의 영광을 말하리라<br/>',NULL,29607,2);
INSERT INTO stanza VALUES('K148','2','하나님 사람인 주 그리스도 천사들보다<br/>더 못하게 돼 여자의 씨로서 세상에 오셔<br/>옛 뱀을 짓밟고 머리 깼네<br/>',NULL,29608,3);
INSERT INTO stanza VALUES('K148','3','창조주 하나님 자신을 낮춰 사람에 의하여<br/>못 박혔네 버림을 받으신 주 예수 홀로<br/>쓴 잔을 마시고 흑암 거쳐<br/>',NULL,29609,4);
INSERT INTO stanza VALUES('K148','4','죽음의 격랑과 싸우신 주님 영광의 승리를<br/>얻으셨네 음부의 문 이미 무너졌으니<br/>찬송이 넘치네 충만하네<br/>',NULL,29610,5);
INSERT INTO stanza VALUES('K149','1','주 예수-만 찬-송받기 합당하신 분일-세<br/>주의 사랑 은혜- 선함 우-리- 생각- 초월해<br/>',NULL,29611,1);
INSERT INTO stanza VALUES('K149','2','감사하-는 마-음 넘쳐 주의 이름 찬송-해<br/>평생 은혜 충만-하여 주-의- 귀함- 말하리<br/>',NULL,29612,2);
INSERT INTO stanza VALUES('K149','3','우리들-이 경-배하는 주는 너그러운- 분<br/>주의 능력 또한- 사랑 무-한-하여- 끝없네<br/>',NULL,29613,3);
INSERT INTO stanza VALUES('K149','4','주 예수-는 처-음 나중 끝까지 날 이끄-네<br/>과거 인해 주 찬 -미해 미-래- 위해- 의지해<br/>',NULL,29614,4);
INSERT INTO stanza VALUES('K149','5','찬양하-세 찬-양하세 나의 은인 찬양-해<br/>하늘 위에 이르-도록 길-이- 길이- 찬양해<br/>',NULL,29615,5);
INSERT INTO stanza VALUES('K15','1','보혈 없이 죄 - 사하면 공의가 - 아니요<br/>보혈 아래 정죄해도 공의 - 가 - 아닐세<br/>',NULL,29616,1);
INSERT INTO stanza VALUES('K15','2','나의 주님 나 - 위하여 제물 되 - 셨으니<br/>하나님도 더 이상 날 꾸짖 - 지 - 못하네<br/>',NULL,29617,2);
INSERT INTO stanza VALUES('K15','3','내 주께서 의 - 의 요구 다 지불 - 했으니<br/>더 이상 심판 없겠네 용서 - 만 - 있겠네<br/>',NULL,29618,3);
INSERT INTO stanza VALUES('K15','4','사랑으로 구 - 속 이뤄 의의 요 - 구 이뤄<br/>나의 주님 모든 죄수 다 해 - 방 - 하시네<br/>',NULL,29619,4);
INSERT INTO stanza VALUES('K15','5','오 놀라운 주 - 십자가 나 지금 - 대하니<br/>사랑과 공의의 역사 내 찬 - 송 - 한없네<br/>',NULL,29620,5);
INSERT INTO stanza VALUES('K150','1','주 만유 포함하-시니 나 그- 안에- 있네-<br/>주님은 우리 영-원한 분깃- 또 모-든 것<br/>',NULL,29621,1);
INSERT INTO stanza VALUES('K150','2','우리 지혜인 주- 인해 우린- 구원-받네-<br/>구원의 유일한- 길과 유일-한 통로인 주<br/>',NULL,29622,2);
INSERT INTO stanza VALUES('K150','3','주는 우리의 공-의 돼 하나-님 요구 이뤄-<br/>주 안에 난 의롭-게 돼 내게-서 죄 못 찾네<br/>',NULL,29623,3);
INSERT INTO stanza VALUES('K150','4','우리의 성결 되-신 주 우리-를 변-케 해-<br/>주 안에 나는 성-화돼 주 닮-을 때-까지<br/>',NULL,29624,4);
INSERT INTO stanza VALUES('K150','5','우릴 주같이 되-도록 주 우-리 구-속해-<br/>우리 몸 변형될- 때에 주님-과 같-게 돼<br/>',NULL,29625,5);
INSERT INTO stanza VALUES('K150','6','주 어떠하심 여-기서 함께- 기념-하니 -<br/>주여 더 지체 마-시고 속히- 곧 오-소서<br/>',NULL,29626,6);
INSERT INTO stanza VALUES('K150','7','이 미리 맛봄 달-콤해 날 만-족게-하나-<br/>난 주와 함께 있-으며 주 누-리기- 원해<br/>',NULL,29627,7);
INSERT INTO stanza VALUES('K151','1','주 당신은 만세 반석 나 위해 열린 반석<br/>이 반석의 생수 마셔 난 주와 연결됐네<br/>당신은 영원한 반석 난 그 위에 건축돼<br/>구속 인해 연합된 나 그 누가 요동시키랴-<br/>',NULL,29628,1);
INSERT INTO stanza VALUES('K151','chorus','참 진귀한 주의 가치 다 나를 위함이니<br/>사랑 안에 주의 풍성 충만히 누리겠네<br/>',NULL,29629,2);
INSERT INTO stanza VALUES('K151','2','많은 사람 시험한 돌 하나님께 귀한 돌<br/>우리에게 사랑스런 영생의 산 돌일세<br/>지극히 견고한 산 돌 우리의 의지할 돌<br/>무궁한 생명 안으로 이끄는 능-력의 돌-<br/>',NULL,29630,3);
INSERT INTO stanza VALUES('K151','3','이 거룩한 기초 돌을 하나님이 세웠네<br/>이 견고한 기초 통해 우리는 안전 누려<br/>주 예수 외에 누구도 다른 기초 못 세워<br/>주는 내 유일한 기초 영원히 변치 않으리-<br/>',NULL,29631,4);
INSERT INTO stanza VALUES('K151','4','하나님의 건축 위한 모퉁이 돌인 주님<br/>유대인과 이방인을 한 몸 되게 하셨네<br/>측량 못할 은혜 낳는 그 머리 돌이신 주<br/>당신은 우리의 영광 우리 맘 시로 충만해-<br/>',NULL,29632,5);
INSERT INTO stanza VALUES('K152','1','주 사랑 내게 주 풍성 주 분량 말해 주네<br/>주의 부-요함 무한-함 내 영 안에서 누림 돼<br/>',NULL,29633,1);
INSERT INTO stanza VALUES('K152','2','태초에 주 하나님과 함께 계신 그 말씀<br/>육신 되-어서 사시-며 하나님 말해 냈-네<br/>',NULL,29634,2);
INSERT INTO stanza VALUES('K152','3','하나님 장막이신 주 그 영광 나타내네<br/>참 성전-이신 주 안-에 하나님 거하시-네<br/>',NULL,29635,3);
INSERT INTO stanza VALUES('K152','4','오 독생하신 아들이 늘 아버지 나타내<br/>주 하나-님의 성품-에 날 참예하게 하-네<br/>',NULL,29636,4);
INSERT INTO stanza VALUES('K152','5','나 같은 성정 가지신 인자이신 주 예수<br/>나로 아-들이 되게- 해 주 형상 이루시-네<br/>',NULL,29637,5);
INSERT INTO stanza VALUES('K152','6','주 그리스도 만유 주 하나님의 메시야<br/>만유 가-운데 만유-인 하나님 사람일-세<br/>',NULL,29638,6);
INSERT INTO stanza VALUES('K152','7','주 십자가에 못 박혀 피와 물 흘리셨네<br/>나 구속-받아 거듭-나 그분의 보물 됐-네<br/>',NULL,29639,7);
INSERT INTO stanza VALUES('K152','8','오 영광 받은 예수는 생명 주는 영 됐네<br/>풍성 누-리게 하시-네 만유를 포함한- 영<br/>',NULL,29640,8);
INSERT INTO stanza VALUES('K152','9','오 어둠 속에 비추는 거룩한 생명의 빛<br/>내 마음- 충만하도-록 주 항상 비춰 주-네<br/>',NULL,29641,9);
INSERT INTO stanza VALUES('K152','10','내 죽은 영을 살리는 그 영원하신 생명<br/>사망에-서 날 해방-해 그 풍성 누리게- 해<br/>',NULL,29642,10);
INSERT INTO stanza VALUES('K152','11','하나님 기쁘시게 한 주님만이 참 실재<br/>이 실재- 내가 누릴- 때 주 무한하심 아-네<br/>',NULL,29643,11);
INSERT INTO stanza VALUES('K152','12','오 주님만이 길이니 하나님께 인도해<br/>생명으-로 날 이끄-네 주 영광 안에 이끄네<br/>',NULL,29644,12);
INSERT INTO stanza VALUES('K152','13','오 모든 사망 이긴 주 참 놀라우신 부활<br/>부활의- 능력 안에-서 나 주와 연합했-네<br/>',NULL,29645,13);
INSERT INTO stanza VALUES('K152','14','주 나를 구속해주신 흠 없으신 어린 양<br/>나로 생-명을 얻게- 한 생명을 주는 영-돼<br/>',NULL,29646,14);
INSERT INTO stanza VALUES('K152','15','날 구원하신 주님은 나무에 달린 놋 뱀<br/>십자가- 위에 달리-어 사망의 권세 멸했네<br/>',NULL,29647,15);
INSERT INTO stanza VALUES('K152','16','율법의 굴레 속에서 날 구원하신 목자<br/>주 통해- 나는 해방-돼 이 푸른 초장 누-려<br/>',NULL,29648,16);
INSERT INTO stanza VALUES('K152','17','주 나를 씻는 효능은 물두멍과도 같네<br/>날 교통- 안에 지키-니 그 은혜 한이 없-네<br/>',NULL,29649,17);
INSERT INTO stanza VALUES('K152','18','주 나를 위해 맞으사 생수를 흘린 반석<br/>늘 새로-운 물 마실- 때 나 모든 피곤 벗-어<br/>',NULL,29650,18);
INSERT INTO stanza VALUES('K152','19','주 영원하신 생명 샘 생수가 넘쳐나네<br/>영원한- 생수 마신- 자 또 목마르지 않-네<br/>',NULL,29651,19);
INSERT INTO stanza VALUES('K152','20','주 하늘로서 내려온 거룩한 생명의 떡<br/>늘 무한-하신 풍성-을 내 영 안에 공급-해<br/>',NULL,29652,20);
INSERT INTO stanza VALUES('K152','21','주 내 영 안에 호흡된 생명의 공기이니<br/>주 의뢰-하여 생활-해 주 예수 자신 누-려<br/>',NULL,29653,21);
INSERT INTO stanza VALUES('K152','22','이 땅에 오셔 죽으신 주는 한 알의 밀알<br/>많은 밀-알들 맺어-서 주 비밀한 몸 이-뤄<br/>',NULL,29654,22);
INSERT INTO stanza VALUES('K152','23','주는 참 포도나무요 우린 다 그의 가지<br/>주 안에- 거해 연합-해 주 모든 소유 누-려<br/>',NULL,29655,23);
INSERT INTO stanza VALUES('K152','24','주 우리 신랑 되시니 우리는 그의 신부<br/>영 안에- 주와 한 몸-돼 풍성한 사랑 누-려<br/>',NULL,29656,24);
INSERT INTO stanza VALUES('K152','25','오 야곱이 본 사다리 하늘을 여는 인자<br/>우린 하-나님 성전-돼 이 땅과 하늘 잇-네<br/>',NULL,29657,25);
INSERT INTO stanza VALUES('K152','26','오 주는 우릴 채우는 놀라운 자존자니<br/>우리 주-님을 누려-서 주 영광 나타내-리<br/>',NULL,29658,26);
INSERT INTO stanza VALUES('K153','1','주는- 날 돕-는 보혜사 신실-한 내 중보<br/>하나-님 앞에 나- 위해 일하-는 분일세<br/>',NULL,29659,1);
INSERT INTO stanza VALUES('K153','2','범사-에 중-보 기도를 날 위-해 드리는<br/>주는- 내 변호자-시요 늘 나-를 돕는 자<br/>',NULL,29660,2);
INSERT INTO stanza VALUES('K153','3','하나-님 기-쁘심 따라 날 위-해 일하는<br/>주는-하늘에 계-시고 내 안-에 계시네<br/>',NULL,29661,3);
INSERT INTO stanza VALUES('K153','4','하늘-서 항-상 날 위해 변호-하시는 주<br/>내 안-에 탄식하-시며 날 위-해 간구해<br/>',NULL,29662,4);
INSERT INTO stanza VALUES('K153','5','하나-님 뜻-을 좇아서 영원-히 사시며<br/>부활- 생명 능력-으로 속 강-건케 하네<br/>',NULL,29663,5);
INSERT INTO stanza VALUES('K153','6','생명-을 주-는 영인 주 항상- 날 돌보며<br/>내 영- 안에 큰 능-력 돼 주 의-지하게 해<br/>',NULL,29664,6);
INSERT INTO stanza VALUES('K153','7','주 사-랑 긍-휼 통하여 주님-만 섬기리<br/>주 나-의 만유 되-시어 충만-케 되도록<br/>',NULL,29665,7);
INSERT INTO stanza VALUES('K154','1','창세 전-에 아버지-의 품에 있던 독-생자<br/>하나님-이 보내셨-네 우리에-게 이 땅에<br/>사람들과 같은 모-양 인성- 입은 주- 이제<br/>아버지-의 모든 충-만 성령 안-에 선포해<br/>',NULL,29666,1);
INSERT INTO stanza VALUES('K154','2','주는 죽-음 부활 거-쳐 하나님의 맏아들 돼<br/>그의 생-명 부음으-로 많은 아-들 낳았네<br/>우린 모두 영 안에-서 하나-님의 아-들들<br/>우린 주-의 많은 형-제 우린 주-와 하날세<br/>',NULL,29667,2);
INSERT INTO stanza VALUES('K154','3','전에 한- 알 밀로 떨어져 이 땅에서 죽으신 주<br/>죽음 부-활 거쳐 번성해 많은 열-매 맺었네<br/>우린 주의 성분으-로 많은- 열매 되-었네<br/>한 떡으-로 뭉쳐져-서 주 완전-함 선포해<br/>',NULL,29668,3);
INSERT INTO stanza VALUES('K154','4','우리들-은 주의 신-부 주의 표현 주의 충만<br/>주의 연-장 주의 발-전 주의 번-성 주의 몸<br/>부요하신 주의 넘-침 주의- 충만한- 성장<br/>영광스-런 머리 되-신 주와 우-린 하날세<br/>',NULL,29669,4);
INSERT INTO stanza VALUES('K155','1','모든 예표 그림자-는 주님 자신 묘사하니<br/>주는 이런 표징처-럼 내게 정-말- 귀하네<br/>주 어떠함 주목하-며 뛰어나신 모습 볼 때<br/>주 풍성에 다만 놀-라 만유인- 주- 경배해<br/>',NULL,29670,1);
INSERT INTO stanza VALUES('K155','2','유월절인 주로 인 -해 하나님 날 넘어가-<br/>주의 구속 통해 우-린 하나님-과- 화목돼<br/>하나님의 어린 양-인 주 피 흘려 날 구속해<br/>주의 피 내 속전 되-니 주를 먹-어- 살겠네<br/>',NULL,29671,2);
INSERT INTO stanza VALUES('K155','3','하늘에서 내려오-신 누룩 없는 생명의 떡<br/>주를 먹어 하나된- 나 주님 안-에- 참예해<br/>어린 양과 떡은 모-두 내 생명 된 주 예표해<br/>잔치에서 주를 먹-어 주의 풍-성- 누리네<br/>',NULL,29672,3);
INSERT INTO stanza VALUES('K155','4','주 당신은 하늘 만 -나 우리의 일용할 양식<br/>먹이시고 능력 주-사 모든 필-요- 채우네<br/>주는 또 산 반석으-로 나를 위해 열려져-<br/>생명 생수 흐르게- 해 우리 갈-증- 해결해<br/>',NULL,29673,4);
INSERT INTO stanza VALUES('K155','5','주는 가나안 더 좋은- 땅 풍성하고 아름다와<br/>젖과 꿀이 흐르는- 땅 모든 곡-식- 풍성해<br/>주의 풍성 거둬 들-여 하나님께 경배하리<br/>사랑 안에 연결되-어 주의 건-축-이루리<br/>',NULL,29674,5);
INSERT INTO stanza VALUES('K156','1','공의의 태양인- 주님 치료-하는- 광선-<br/>영광스런 주 얼-굴 빛 생명-과 평-안 줘<br/>',NULL,29675,1);
INSERT INTO stanza VALUES('K156','2','하나님 긍휼의- 심장 우리-에게- 임해-<br/>흑암과 사망 그-늘에 앉은- 자 비-추네<br/>',NULL,29676,2);
INSERT INTO stanza VALUES('K156','3','주는 내게 구름- 없는 맑은- 아침- 빛 돼-<br/>우린 다 연한 풀-같이 주 빛-에 자-라나<br/>',NULL,29677,3);
INSERT INTO stanza VALUES('K156','4','사랑스런 광선-으로 퍼지-는 은-혜 빛-<br/>내 안에서 밝게- 빛나 정오-에 이르도록<br/>',NULL,29678,4);
INSERT INTO stanza VALUES('K156','5','비 내린 후의 해-처럼 고난-을 뚫-고서-<br/>주님의 긍휼과- 사랑 영원-히 비-취네<br/>',NULL,29679,5);
INSERT INTO stanza VALUES('K156','6','주 맑은 새벽별-로써 날 깨-우는- 내 상-<br/>흑암이 깊어질-수록 날 비-춰 주-시네<br/>',NULL,29680,6);
INSERT INTO stanza VALUES('K156','7','주여 내 눈을 밝-게 해 주 빛- 사모-케 해-<br/>늘 깨어 기도하-면서 주 맞-게 하-소서<br/>',NULL,29681,7);
INSERT INTO stanza VALUES('K157','1','주 어떠하심 생각하며 주께 경배합니다<br/>풍성하고 놀라운 주- 귀하고 사랑스런 주<br/>',NULL,29682,1);
INSERT INTO stanza VALUES('K157','chorus','당신의 무한한 공급- 내 필요 만족케 하네<br/>마음 다해 주님 당신께 찬양과 경배합니다<br/>',NULL,29683,2);
INSERT INTO stanza VALUES('K157','2','당신은 빛과 사랑의 참 하나님이십니다<br/>우리의 생명 되시며- 은혜 베푸는 하나님<br/>',NULL,29684,3);
INSERT INTO stanza VALUES('K157','3','온유하고 또 순수한 참 사람이신 당신은<br/>하나님 맘 기쁘게 하며 내 맘을 얻으십니다-<br/>',NULL,29685,4);
INSERT INTO stanza VALUES('K157','4','우리를 위해 자신 낮춰 하나님 노예 되어<br/>죽기까지 순종하사- 우릴 구원하신 주님<br/>',NULL,29686,5);
INSERT INTO stanza VALUES('K157','5','하나님 기름 부어져 세워진 왕이신 당신<br/>생명과 사랑으로써- 다스리는 주십니다<br/>',NULL,29687,6);
INSERT INTO stanza VALUES('K157','6','주 어떠하심 기념하며 주 함께 누립니다<br/>사랑 안에 주님 자신- 영원히 누리렵니다<br/>',NULL,29688,7);
INSERT INTO stanza VALUES('K158','1','알파와 오메가인 주 그리스도여<br/>당신 앞에나 뒤에 그 누구도 없네<br/>유일한 시작이며 또 마침이신 주<br/>모-두 다 포함하신 주 만유이실세<br/>',NULL,29689,1);
INSERT INTO stanza VALUES('K158','2','알파인 주에게서 만유가 시작돼<br/>오메가인 주 위에 만유가 있다네<br/>모든 글자인 주로 만유가 조성돼<br/>주- 당신 인해 만유 다 유지된다네<br/>',NULL,29690,2);
INSERT INTO stanza VALUES('K158','3','피조물 중에 먼저 난 만유의 머리<br/>주는 만유의 나중 또 만유의 마침<br/>만유가 주에게서 나오고 존재해<br/>만-유의 나중이신 주께로 돌아가<br/>',NULL,29691,3);
INSERT INTO stanza VALUES('K158','4','만유의 기원으로 먼저 계신 자요<br/>만유의 결론인 주 만유 소유하네<br/>기원인 주로 인해 창조된 만유가<br/>유-일한 마침이신 주 예수로 끝나<br/>',NULL,29692,4);
INSERT INTO stanza VALUES('K158','5','만유 위에 계시는 주 알파 오메가<br/>만유의 창시자요 또 종결자일세<br/>만유 위에 계신 주 다 이루셨으니<br/>경-배와 찬송 받기 참 합당하시네<br/>',NULL,29693,5);
INSERT INTO stanza VALUES('K159','1','주는 생 -명의- 출구요 생명-의 나무니<br/>그 열 -매엔 생명- 많아 내 좋-은 음식 돼<br/>',NULL,29694,1);
INSERT INTO stanza VALUES('K159','2','주는 생 -명 공-급 근원 참 포-도나무니<br/>주 안 -에서 거하-면서 주 풍 -성 누리네<br/>',NULL,29695,2);
INSERT INTO stanza VALUES('K159','3','주는 나 -의 누-림 되는 참 사-과나무니<br/>그 그 -늘서 주의- 열매 달콤-함 맛보네<br/>',NULL,29696,3);
INSERT INTO stanza VALUES('K159','4','주는 날 - 위해- 죽으신 치료-하는 나무<br/>나무- 위에 못 박 -히사 날 치-료하셨네<br/>',NULL,29697,4);
INSERT INTO stanza VALUES('K159','5','하나님- 풍성- 감춰진 유일-한 가지니<br/>주 안 -에서 하나-님이 실재-와 은혜 돼<br/>',NULL,29698,5);
INSERT INTO stanza VALUES('K159','6','주 예수-는 성-육신 된 다윗-의 가지니<br/>주 안 -에서 하나-님이 실재-와 은혜 돼<br/>',NULL,29699,6);
INSERT INTO stanza VALUES('K159','7','주는 무 -궁한- 생명의 싹난- 지팡이니<br/>주 부 -활의 그 큰 - 능력 사망-을 이기네<br/>',NULL,29700,7);
INSERT INTO stanza VALUES('K159','8','주는 물 -에 뜨-는 나무 난 잠-기는 도끼<br/>주 초 -월의 능력- 인해 물 위-에 떠 있네<br/>',NULL,29701,8);
INSERT INTO stanza VALUES('K159','9','유명한- 식물-이신 주 풍성-히 누리며<br/>여기-에서 주 기 -념해 주 찬 -양하겠네<br/>',NULL,29702,9);
INSERT INTO stanza VALUES('K16','1','내 주의 공의 찬양하며 주의 정의 인정하고<br/>간증하겠네 온 땅을 심판하실 주<br/>불의없는 주님 온전하고 의로우시네<br/>',NULL,29703,1);
INSERT INTO stanza VALUES('K16','2','주 보좌 기초 공의이니 이로 인해 화평 세워<br/>변함 없으리 그 공의 인해 주께서<br/>왕노릇함으로 다스리니 화평 누리네<br/>',NULL,29704,2);
INSERT INTO stanza VALUES('K16','3','그 공의 인해 십자가에 가신 아들 나를 위해<br/>죽임당했네 그 구속 믿기만 하면<br/>즉시 나를 의롭다 하시고 구원받게 해<br/>',NULL,29705,3);
INSERT INTO stanza VALUES('K16','4','당신의 공의 나타내려 구약 시대 모든 죄들<br/>간과하셨네 당신의 공의 위하여<br/>이 - 시대 모든 죄인 죄악 용서하셨네<br/>',NULL,29706,4);
INSERT INTO stanza VALUES('K16','5','그날에 만민 심판할 때 주의 공의 완전하게<br/>나타나겠네 그리스도의 공의로<br/>굳 - 게 선 우리 그 무엇도 요동케 못해<br/>',NULL,29707,5);
INSERT INTO stanza VALUES('K160','1','주는 율법 능가하는 하나님의 간증<br/>율법은 주의 축소요 주는 율법 실재<br/>율법은 하-나님 묘사 하나님- 설명뿐<br/>주는 하나님 거하는 하나님의 실재<br/>',NULL,29708,1);
INSERT INTO stanza VALUES('K160','2','율법 가진 언약궤는 주님의 예표나<br/>하나님의 모든 것이 다 주 안에 있네<br/>나무로 된- 언약궤에 금이 덮-인 것은<br/>인성과 신성 연합된 주를 말함일세<br/>',NULL,29709,2);
INSERT INTO stanza VALUES('K160','3','참된 장막 당신 안에 하나님 거하니<br/>육신 되신 당신 안에 은혜 진리 넘쳐<br/>하나님 산- 말씀인 주 하나님- 영광 빛<br/>하나님의 산 그림돼 사랑과 빛 되네<br/>',NULL,29710,3);
INSERT INTO stanza VALUES('K160','4','주는 하나님 참 성전 하나님 표현해<br/>주 안에 하나님 거해 모든 것 가지고<br/>사탄이 깨-뜨리려고 사지에- 두어도<br/>당신은 부활 안에서 더 큰 성전 짓네<br/>',NULL,29711,4);
INSERT INTO stanza VALUES('K160','5','거룩한 성은 주 신부 주 충만 뜻하니<br/>이는 주 충만서 나온 주 충만의 확충<br/>하나님은- 그 성의 빛 주님은- 등이니<br/>온 성에 그 빛 비췰 때 하나님의 영광<br/>',NULL,29712,5);
INSERT INTO stanza VALUES('K160','6','장막과 언약궤 율법 성전 거룩한 성<br/>모두가 귀한 주님의 그 풍성 말하네<br/>중심도 주-변도 주님 모두가- 주님뿐<br/>하나님 사람인 주님 맘 다해 사랑해<br/>',NULL,29713,6);
INSERT INTO stanza VALUES('K161','1','오 풍성하-신 내 주님 내 모-든 것-일세<br/>내 필요 얼-마이든지 주가 다 채-우네<br/>내 맘은 주-를 감상해 영은- 주 경-배해<br/>주 풍성 누-릴 때마다 감사함 넘쳐나네<br/>',NULL,29714,1);
INSERT INTO stanza VALUES('K161','2','하나님 능-력 풍성한 주님-은 선-지자<br/>모세같이- 하나님 뜻 나타내 행하셨네<br/>죽음과 부-활 통과한 요나-같은- 주님<br/>죽음과 부활의 표징에 난 믿고 회-개해<br/>',NULL,29715,2);
INSERT INTO stanza VALUES('K161','3','오 빛과 능-력 충만한 선지-자인 주님<br/>능력의 기-적 행했던 엘리사 같-은 주<br/>이사야처-럼 계시해 하나-님 그리스도<br/>나로 주님-의 모든 것 풍성히 누리게 해<br/>',NULL,29716,3);
INSERT INTO stanza VALUES('K161','4','사람들 중-에 선택된 거룩-한 제-사장<br/>사람을 대-신해 섬긴 아론과 같-은 주<br/>대제사장-같이 나를 하나-님 앞-에 둬<br/>날 위해 늘- 간구하며 내 약함 감-당해<br/>',NULL,29717,4);
INSERT INTO stanza VALUES('K161','5','하나님 보-내심 받은 왕 같-은 제-사장<br/>하나님 위-해 섬기신 살렘 왕 멜기세덱<br/>하나님 떡-과 포도주 나에-게 공-급해<br/>철 따라 그- 모든 풍성 나로 누리-게 해<br/>',NULL,29718,5);
INSERT INTO stanza VALUES('K161','6','하나님 뜻- 생각하신 다윗-과 같-은 왕<br/>대적과 싸-워 이겨서 하나님 뜻-이뤄<br/>보좌에 앉-으신 주님 왕으-로 다-스려<br/>사람의 손-이 아닐세 신성한 권위일세<br/>',NULL,29719,6);
INSERT INTO stanza VALUES('K161','7','화평을 갖-고 집권한 솔로-몬 같-은 주<br/>성전 건축- 경륜 위해 지혜로 왕 노릇 해<br/>사랑으로- 모든 성도 다스-리는- 주님<br/>장래 그날-에 우리와 함께 왕 노-릇 해<br/>',NULL,29720,7);
INSERT INTO stanza VALUES('K161','8','제사장 선-지자 왕인 주 정-말 풍-성해<br/>하나님과- 사람에게 그 가치 참- 귀해<br/>주 어떠하-심 누릴 때 온 존-재 이-끌려<br/>끝없는 경-배 찬미를 주님께 드-리네<br/>',NULL,29721,8);
INSERT INTO stanza VALUES('K162','1','주 예수는 여자의- 씨 원수 없애려고 나셔<br/>죽음 통해 승리하-려 사람 성-품- 입었네<br/>혈육의 몸 입으시-고 육신 되신 하나님-<br/>사망으로 마귀 없-애 사망 세-력- 제했네<br/>',NULL,29722,1);
INSERT INTO stanza VALUES('K162','2','하나님의 약속 따-라 아브라함 씨 되셔-<br/>하나님의 약속하-신 축복 얻-게- 하셨네<br/>아브라함보다 훨-씬 먼저 계신 주시나-<br/>하나님의 약속 위-해 아브라-함- 씨 됐네<br/>',NULL,29723,2);
INSERT INTO stanza VALUES('K162','3','하나님의 왕국 위-해 일으켜진 다윗의 씨<br/>하나님의 건축 위-해 이미 보-좌- 얻었네<br/>다윗 후손이시지-만 다윗의 주이신 당신<br/>본래 다윗 뿌리였-네 영원하-신- 만유 주<br/>',NULL,29724,3);
INSERT INTO stanza VALUES('K162','4','인성 지닌 한 아기-는 전능하신 하나님-<br/>우리에게 주신 아-들 영존하-는- 아버지<br/>하나님의 모든 축-복 믿음으로 받을 때에<br/>모든 약속 주 안에-서 예가 되-고- 실재돼<br/>',NULL,29725,4);
INSERT INTO stanza VALUES('K163','1','오 하나님의 형상 사랑하는 아들 또 성도들의<br/>기업인 우리 주 예수 주 말미암아 주 위해<br/>만물 창조돼 그는 모든 창조물보다 먼저 나신 자<br/>',NULL,29726,1);
INSERT INTO stanza VALUES('K163','2','오 만물보다 먼저 계신 당신 안에 만물이<br/>서 있다네 주 만물의 중심 죽은 자 가운데서<br/>먼저 난 주 예수 영-광스런 머릴세 그 몸된 교회의<br/>',NULL,29727,2);
INSERT INTO stanza VALUES('K163','3','아버지는 기뻐해 그 모든 충만이 주 예수<br/>안에 거함 기뻐하신다네 주 그의 피로 우릴<br/>화목케 하시어 그- 앞에 흠이 없고 거룩게 하시네<br/>',NULL,29728,3);
INSERT INTO stanza VALUES('K163','4','오 하나님의 비밀 주 예수 안에는 지혜와<br/>지식 보화 다 감춰져 있네 우리 안의 주님은<br/>곧 영광의 소망 완-전한 자로 우릴 세워 가신다네<br/>',NULL,29729,4);
INSERT INTO stanza VALUES('K163','5','모든 것은 그림자 주님만 실재니 이 풍성<br/>누려 우린 주 충만된다네 몸인 우리는 모두<br/>머리를 붙들고 주- 하나님을 인해 자라고 자라네<br/>',NULL,29730,5);
INSERT INTO stanza VALUES('K163','6','주 그리스도 우리 생명 되셨으니 하나님<br/>안에 우린 주님과 감춰져 주 평강이 지키니<br/>다툼을 버리네 한- 새사람 안에서 주 만유이실세<br/>',NULL,29731,6);
INSERT INTO stanza VALUES('K164','1','하나님의 아들인 주 하나님-의 나타남-<br/>주를 통해 하나님이 우리에-게 말씀해<br/>',NULL,29732,1);
INSERT INTO stanza VALUES('K164','2','하나님의 본체 형상 하나님-의 영광 빛-<br/>그는 바로 하나님의 나타나-심이시네<br/>',NULL,29733,2);
INSERT INTO stanza VALUES('K164','3','주로 인해 우주 만물 지어지-고 유지돼-<br/>장래 만유 승계하실 하나님의 그리스도<br/>',NULL,29734,3);
INSERT INTO stanza VALUES('K164','4','주는 이미 내 죄 씻고 보좌 우-편 앉았네-<br/>원수가 주 발등상이 될 때까-지 기다려<br/>',NULL,29735,4);
INSERT INTO stanza VALUES('K164','5','천사보다 뛰어난 주 존귀하-신 이름 얻어<br/>부활하여 하나님의 아들로-서 인정돼<br/>',NULL,29736,5);
INSERT INTO stanza VALUES('K164','6','주의 왕국 공의로와 주의 보-좌 영원해-<br/>즐거움의 기름 받아 동류보-다 승하셔<br/>',NULL,29737,6);
INSERT INTO stanza VALUES('K164','7','주님은 또 인성 지닌 참된 사-람 아들로-<br/>나를 위해 죽음 맛봐 나로 생-명 얻게 해<br/>',NULL,29738,7);
INSERT INTO stanza VALUES('K164','8','영광 존귀 얻은 주께 모든 만-유 굴복해-<br/>고난 인해 온전케 된 주는 구-원의 원수<br/>',NULL,29739,8);
INSERT INTO stanza VALUES('K164','9','죽음으로 마귀 없애 나를 해-방하셨네-<br/>주 생명 날 거룩게 해 영광으-로 인도해<br/>',NULL,29740,9);
INSERT INTO stanza VALUES('K164','10','주와 우린 형제 되어 아버지-를 찬양해-<br/>교회 중에 소리 합해 아버지-께 찬송해<br/>',NULL,29741,10);
INSERT INTO stanza VALUES('K164','11','건축자가 집보다도 더욱 존-귀하듯이-<br/>주 예수는 모세보다 존귀하-신 사돌세<br/>',NULL,29742,11);
INSERT INTO stanza VALUES('K164','12','주는 우릴 안식으로 인도하-는 여호수아<br/>구원이신 주님 안에 우리 믿-음 있다네<br/>',NULL,29743,12);
INSERT INTO stanza VALUES('K164','13','주는 우리 참된 안식 내 영 안-에 거하네-<br/>그 안식에 들어가서 주의 풍-성 누리네<br/>',NULL,29744,13);
INSERT INTO stanza VALUES('K164','14','대제사장 택함 받은 아론보-다 귀한 주-<br/>성결하고 흠 없는 주 우리 위-해 간구해<br/>',NULL,29745,14);
INSERT INTO stanza VALUES('K164','15','주님은 참 멜기세덱 생명 능-력 가지고-<br/>우리에게 공급하셔 떡과 포-도주 함께<br/>',NULL,29746,15);
INSERT INTO stanza VALUES('K164','16','영원하신 성령으로 나를 위-해 드려져-<br/>더욱 좋은 제물 되어 효능 누-리게 하셔<br/>',NULL,29747,16);
INSERT INTO stanza VALUES('K164','17','주 예수의 더 나은 피 나은 언-약 세웠네-<br/>주로 인해 나도 함께 새 언약-에 동참해<br/>',NULL,29748,17);
INSERT INTO stanza VALUES('K164','18','주님만이 자격 있어 새 언약-을 세웠네-<br/>주가 내게 약속 주사 만유 얻-게 하시네<br/>',NULL,29749,18);
INSERT INTO stanza VALUES('K164','19','주는 부활 생명으로 새 언약-을 집행하셔<br/>새 언약의 중보로서 온전히- 다 이루셔<br/>',NULL,29750,19);
INSERT INTO stanza VALUES('K164','20','주는 이미 휘장 안의 유일하-신 선봉장-<br/>진영 밖의 주 발자취 주 힘입-어 좇으리<br/>',NULL,29751,20);
INSERT INTO stanza VALUES('K164','21','나의 믿음 창시자요 믿음 온-전케 하는 주<br/>영원토록 주 순종해 믿음 사-랑 인하여<br/>',NULL,29752,21);
INSERT INTO stanza VALUES('K164','22','주님 자신 귀히 여겨 사랑하-며 사모해-<br/>온전하고 완전한 주 우리 생-각 초월해<br/>',NULL,29753,22);
INSERT INTO stanza VALUES('K165','1','나 위해 예비되신 제물이신 주님<br/>풍성하고 달콤한 뜻 가지셨다네<br/>아버지의 뜻을 이뤄 그 갈망 성취해<br/>내- 모든 필요 채워 부족함 없게 해<br/>',NULL,29754,1);
INSERT INTO stanza VALUES('K165','2','신성한 불에 타는 향기로운 번제<br/>하나님 만족게 한 달콤한 향길세<br/>하나님 뜻은 바로 주님의 뜻이니<br/>흠- 없는 자신 드려 하나님 앞으로<br/>',NULL,29755,2);
INSERT INTO stanza VALUES('K165','3','기름과 유향 섞인 달콤한 소제니<br/>순결하고 온유해 또 온전하시네<br/>날 위해 화평 이룬 화목 제물로써<br/>내- 풍성한 음식돼 날 공급하시네<br/>',NULL,29756,3);
INSERT INTO stanza VALUES('K165','4','내 속죄 제물 된 주 죄가 되시어서<br/>죽음으로 속량해 내 구속 이뤘네<br/>내 속건 제물 된 주 내 죄를 담당해<br/>하-나님 공의 이뤄 죄사함 얻게 해<br/>',NULL,29757,4);
INSERT INTO stanza VALUES('K165','5','죽음서 부활한 주 내 요제 되셔서<br/>음부와 사망 흑암 다 이기셨다네<br/>날 위해 하나님께 올려진 거제 돼<br/>하-늘에 속한 음식 날 만족게 하네<br/>',NULL,29758,5);
INSERT INTO stanza VALUES('K166','1','주님 안에 모일 때에 다른 것은- 안 뵈-고-<br/>주의 임재 기뻐하며 주만 의지게 되네<br/>',NULL,29759,1);
INSERT INTO stanza VALUES('K166','2','날 사랑한 주의 사랑 무한하여- 다 몰-라-<br/>주에 대한 아버지 뜻 귀히 여기며 새겨<br/>',NULL,29760,2);
INSERT INTO stanza VALUES('K166','3','아버지의 안식 기쁨 모두 주 안-에 있-네-<br/>주 사랑한 아버지 맘 오직 주만이 아네<br/>',NULL,29761,3);
INSERT INTO stanza VALUES('K166','4','아버지의 모든 사랑 주님 안에- 있었-네-<br/>내게 생명 주시려고 아들 죽게 하셨네<br/>',NULL,29762,4);
INSERT INTO stanza VALUES('K166','5','장차 주를 뵈올 때에 나는 기뻐- 부르-리-<br/>하나님의 마음 속에 향기 되신 주 이름<br/>',NULL,29763,5);
INSERT INTO stanza VALUES('K166','6','기쁜 노래 영광의 시 그침없이- 찬송-해-<br/>영원토록 찬송 찬미 주께 더욱 드리리<br/>',NULL,29764,6);
INSERT INTO stanza VALUES('K167','1','주는 생명의 근원 깊고 달콤한 샘<br/>이 생수 맛본 사람 목마르지- 않으리<br/>주 당신의 긍휼은 넓고도 풍성해<br/>주의 은혜 지혜 또한 측량할 수 없네<br/>',NULL,29765,1);
INSERT INTO stanza VALUES('K167','2','나는 내 사랑하는 자에게 속했고<br/>내 사랑하는 자는 나에게 속-했-네<br/>나같이 더러운 자 잔치에 이끌어<br/>예-복을 입히는 주 그 품에 숨겠네<br/>',NULL,29766,2);
INSERT INTO stanza VALUES('K167','3','신부의 장식품은 다른 것 아닐세<br/>오직 사랑하는 자 그분이 장-식-돼<br/>내게 귀한 건 오직 주의 아름다움<br/>주-님 자신이 나의 영광의 면류관<br/>',NULL,29767,3);
INSERT INTO stanza VALUES('K168','1','주 예수 은- -혜 사- -랑을 우리가 생-각할 때<br/>우리 영은 주의- 얼굴 맞대-고 보기 원해<br/>',NULL,29768,1);
INSERT INTO stanza VALUES('K168','2','우리가 가- -는 광- -야엔 외롬과 놀- -람뿐<br/>사방에 가시 엉 - 겅퀴 원수-함정-있네<br/>',NULL,29769,2);
INSERT INTO stanza VALUES('K168','3','깊은 데서- - 주 생-각할 때 그 사랑 가-치 아네<br/>우리의 맘 밝아-지니 그 은-혜 찬-양해<br/>',NULL,29770,3);
INSERT INTO stanza VALUES('K168','4','주는 우리- - 생명- - 능력 방패 반석- - 노래<br/>아무리 생각하-여도 우리-는 즐-거워<br/>',NULL,29771,4);
INSERT INTO stanza VALUES('K168','5','사랑의 주- -를 따-르도록 우리를 지-키소서<br/>당신의 영광의- 형상 뵙는- 그날-까지<br/>',NULL,29772,5);
INSERT INTO stanza VALUES('K169','1','예수 예수 나의 생명 주 사랑하-므로<br/>주 이름 하루에 천-번 부르게 하-소서-<br/>',NULL,29773,1);
INSERT INTO stanza VALUES('K169','chorus','사랑하는 예수 예수 그 무엇과도 비교 못해<br/>주 웃는 얼굴만이 내 기쁨 내 주 예수<br/>',NULL,29774,2);
INSERT INTO stanza VALUES('K169','2','주 사랑하는 이 마음을 억누를 수 없네<br/>불같이 뜨거운 주 사랑 내 마음 불사르네-<br/>',NULL,29775,3);
INSERT INTO stanza VALUES('K169','3','주는 내 의지 양식 의사 사모하-는 자<br/>내 혼의 영원한 힘이요 내 모든 것의 모든 것<br/>',NULL,29776,4);
INSERT INTO stanza VALUES('K169','4','오 내 맘 속에 타오르는 주 예수의 사랑<br/>다른 사랑 다 제하도록 밤낮으로 태우소서<br/>',NULL,29777,5);
INSERT INTO stanza VALUES('K169','5','어두움 속의 빛이시요 근심 속의 기쁨<br/>나의 사랑- 나의 노래 누가 주의 가치 알리요<br/>',NULL,29778,6);
INSERT INTO stanza VALUES('K169','6','오 그침없는 이 사랑을 제한 못-하리<br/>내 주의 달콤함과 가치 날이 갈수-록 더해<br/>',NULL,29779,7);
INSERT INTO stanza VALUES('K17','1','죄로 충만해 고통할 때 공의는 나를 심 - 판했네<br/>내 주님 피흘려 구속 이루니 공의는 내게 평강 주네<br/>',NULL,29780,1);
INSERT INTO stanza VALUES('K17','2','하나님 공의 인 - 하여 내 구주 십자가 - 지셨네<br/>그 공의 인 - 해 모든 죄 - 인 의롭다 - 함 얻 - 겠네<br/>',NULL,29781,2);
INSERT INTO stanza VALUES('K17','3','하나님 의가 요구했네 모든 빚 깨끗이 - 갚으라<br/>내 주가 모든 빚 갚으셨느니 공의는 다시 요구 못해<br/>',NULL,29782,3);
INSERT INTO stanza VALUES('K17','4','내 주님 피를 흘렸으니 또다시 죽음 요 - 구 못해<br/>주님 날 사하고 정케했으니 또다시 내게 요구 못해<br/>',NULL,29783,4);
INSERT INTO stanza VALUES('K17','5','전에는 주의 공의 듣고 두렵고 떨려 도 - 망했네<br/>이제는 주의 의 선포될 때에 사랑스럽고 소중하네<br/>',NULL,29784,5);
INSERT INTO stanza VALUES('K17','6','당신의 공의 알고부터 당신의 은혜 깨닫게 됐네<br/>공의는 나에게 안식 주 - 고 은혜는 나를 안위하네<br/>',NULL,29785,6);
INSERT INTO stanza VALUES('K170','1','내 맘이 사랑하는 주 예수 입으로 그 맘 표현하고파<br/>부활과 축복되신 주님께 나 지금 맘 껏 찬송하겠네<br/>',NULL,29786,1);
INSERT INTO stanza VALUES('K170','2','사랑스럽고 귀한 주 임재 여기서 다시 맛보게 하네<br/>주 그늘 아래 안식하면서 주 선한 열매 충만히 누려<br/>',NULL,29787,2);
INSERT INTO stanza VALUES('K170','3','한 밀알 많은 열매 맺듯이 사지에 주님 떨어지셔서<br/>부활로 많은 형제들 얻고 우리로 함께 참예케 하네<br/>',NULL,29788,3);
INSERT INTO stanza VALUES('K170','4','이제는 만유 되신 주 예수 주 안에 우린 부족함 없네<br/>내 모든 필요 만족게 하신 주님을 맘껏 찬송하겠네<br/>',NULL,29789,4);
INSERT INTO stanza VALUES('K171','1','주를 생각할 때마다 내 맘 달콤하나<br/>주 얼굴 친히 뵐 때에 달콤함 더 크리<br/>',NULL,29790,1);
INSERT INTO stanza VALUES('K171','2','당신의 이름보다 더 기쁜 소리 없네<br/>주 예수 이름보다도 좋은 이름 없네<br/>',NULL,29791,2);
INSERT INTO stanza VALUES('K171','3','통회하는 자의 소망 희락이 되신 주<br/>넘어지는 자에게도 동정이 넘치네<br/>',NULL,29792,3);
INSERT INTO stanza VALUES('K171','4','주 사랑하는 자만이 그 사랑 알겠네<br/>주 사랑 깊이 넓이와 길이와 높이를<br/>',NULL,29793,4);
INSERT INTO stanza VALUES('K171','5','세상의 빛인 주님은 참 생명의 근원<br/>내 누림 사모함보다 더욱더 뛰어나<br/>',NULL,29794,5);
INSERT INTO stanza VALUES('K171','6','주 외엔 아무도 없네 내 갈증 씻을 자<br/>다른 샘 다 고갈돼도 주는 무궁한 샘<br/>',NULL,29795,6);
INSERT INTO stanza VALUES('K171','7','주님은 지금 내 기쁨 장래엔 나의 상<br/>영원토록 주 당신은 내 영광 내 찬송<br/>',NULL,29796,7);
INSERT INTO stanza VALUES('K172','1','주는 내 맘의 기쁨과 생명의 근원이-시니<br/>이 땅의 모든 쾌 -락서 돌이켜 주만 봅-니다<br/>',NULL,29797,1);
INSERT INTO stanza VALUES('K172','2','주 진실 변치 않으니 구하는 모든 자- 돕네<br/>찾는 자에게 자 -상해 주는 모든 것 되-시네<br/>',NULL,29798,2);
INSERT INTO stanza VALUES('K172','3','생명의 떡인 주 예수 맛보고 더욱 맛-보리<br/>생수의 샘인 주 - 예수 마시고 더욱 마-시리<br/>',NULL,29799,3);
INSERT INTO stanza VALUES('K172','4','불안한 내 영 돌이켜 주님을 갈망할- 때에<br/>주 웃는 얼굴 보 -게 해 믿음으로 주 잡-게 해<br/>',NULL,29800,4);
INSERT INTO stanza VALUES('K172','5','주는 내 힘 나의 의지 날 항상 밝게 하-시네<br/>어둠과 죄악 쫓 -고서 거룩한 빛 부으-소서<br/>',NULL,29801,5);
INSERT INTO stanza VALUES('K173','1','주 은혜의 말-씀 따라 겸손한- 맘으로<br/>죽임당한 주 예수를 함께- 기-념하네<br/>',NULL,29802,1);
INSERT INTO stanza VALUES('K173','2','나의 공급 되-시려고 그 몸 갈-라졌네<br/>언약의 잔 높임으로 주를- 기-념하세<br/>',NULL,29803,2);
INSERT INTO stanza VALUES('K173','3','겟세마네 외-로움과 피 같은- 눈물 땀<br/>다 알면서 어찌 주를 기념-치- 않으랴<br/>',NULL,29804,3);
INSERT INTO stanza VALUES('K173','4','눈을 들어 갈-보리의 십자가- 주 보며<br/>내 구원된 하나님의 어린- 양- 기념해<br/>',NULL,29805,4);
INSERT INTO stanza VALUES('K173','5','나의 호흡 있-는 동안 내 맥박- 뛰는 한<br/>주님의 고통과 사랑 늘 기-념-하겠네<br/>',NULL,29806,5);
INSERT INTO stanza VALUES('K173','6','나 쇠약해 소-리 작고 기억 희-미할 때<br/>주님의 왕국 임할 때 날 기-억-하소서<br/>',NULL,29807,6);
INSERT INTO stanza VALUES('K174','1','주의 잔치 누릴 때에 사랑의 기 덮는<br/>주 크신 구속 크신 은혜 감사하며 기념해<br/>상에 놓인 떡과 잔은 주의 사-랑 나타내-<br/>우리 함께 주의 은혜 누리며 주 경배해<br/>',NULL,29808,1);
INSERT INTO stanza VALUES('K174','2','이 세상에 노예로 와 질고 시험 당하며<br/>베개 둘 곳 없었던 주 함께 기념하려네<br/>죄인 구원하시려고 거절당-한 주 예수-<br/>죄인 하나 얻기 위해 피 흘리기 원했네<br/>',NULL,29809,2);
INSERT INTO stanza VALUES('K174','3','십자가에 못 박히사 사람 정죄받은 주<br/>우리 속전 지불하사 사랑 나타내셨네<br/>이제 보좌 우편에서 우리 위-해 간구해-<br/>다시 오신다 한 약속 속히 이뤄 주소서<br/>',NULL,29810,3);
INSERT INTO stanza VALUES('K175','1','축복의 잔 나눌 때 어찌 입을 다물까<br/>누가 주의 보혈의 가치 온전히 알까<br/>오 귀중한 주의 피 모든 문제 해결해<br/>효능있는 보혈로 모든 근심 사라져<br/>',NULL,29811,1);
INSERT INTO stanza VALUES('K175','2','효능 있는 보혈로 새 언약을 세웠네<br/>더 나은 언약 위해 그 피 기초 견고해<br/>우릴 하나님께로 구속한 것 보혈뿐<br/>금과 은이 아니요 흠 없는 주의 피라<br/>',NULL,29812,2);
INSERT INTO stanza VALUES('K175','3','내 죄 씻기 위하여 주님 피를 흘리사<br/>하나님의 의로운 요구 만족게 했네<br/>주의 능력 있는 피 정결하게 하는 피<br/>나의 양심 씻고서 하나님 섬기게 해<br/>',NULL,29813,3);
INSERT INTO stanza VALUES('K175','4','분별하는 보혈로 우린 거룩게 됐네<br/>주의 보혈 인하여 거룩함 내 간증 돼<br/>속죄하는 보혈로 나는 의롭게 됐네<br/>구속하는 보혈로 주와 간격 없다네<br/>',NULL,29814,4);
INSERT INTO stanza VALUES('K175','5','십자가의 피로써 하나님과 화목돼<br/>나는 평강 안에서 하나님과 교통해<br/>주의 피에 참예해 주의 생명 얻었네<br/>피와 생명 인하여 자유 평강 누리네<br/>',NULL,29815,5);
INSERT INTO stanza VALUES('K175','6','하늘에서 주의 피 나를 위해 말하네<br/>피의 보호 아래서 사탄 공격 벗어나<br/>승리한 주 보혈로 우린 원수 이겼네<br/>주의 보혈 의지해 참소자를 이기네<br/>',NULL,29816,6);
INSERT INTO stanza VALUES('K175','7','주의 피를 인하여 성도들과 교통해<br/>피로 나를 덮으니 두려움이 없겠네<br/>주의 보혈 이야기 어찌 말로 다하리<br/>귀한 보혈 그 가치 말로 다 할 수 없네<br/>',NULL,29817,7);
INSERT INTO stanza VALUES('K176','1','주의 사랑의 상에 떡과 잔이 놓-였네<br/>이 표징에 참여해 주- 뛰어남 누리네<br/>이 잔 인해 감사해 주가 주신 복된 잔<br/>주의 피로 예비한 넘치는- 구원의 잔<br/>',NULL,29818,1);
INSERT INTO stanza VALUES('K176','2','이는 주의 흘린 피 나의 죄악 씻-었네<br/>이는 주의 새 언약 나-로 축복 얻게 해<br/>진노의 잔 마신 주 나를 위해 죽으사<br/>복된 이 잔 사시어 내 분깃- 얻게 했네<br/>',NULL,29819,2);
INSERT INTO stanza VALUES('K176','3','아담 타락 인하여 잃었던 내 하-나님<br/>주의 보혈 인하여 찾-아 내 은혜 됐네<br/>구속 생명 만유가 이 분깃에 다 있네<br/>주의 계획 갈망도 분깃 안-에 있다네<br/>',NULL,29820,3);
INSERT INTO stanza VALUES('K176','4','이는 영원한 분깃 신성한 축복-의 잔<br/>주가 주신 잔으로 하-늘에 속한 맛봐<br/>사랑으로 마시며 은혜의 주 기념해<br/>영 안에서 마시며 갈보리-를 누리네<br/>',NULL,29821,4);
INSERT INTO stanza VALUES('K177','1','주는 내 안에 난 주 안에 이는 기-적-아닌가<br/>주님과 나는 하-나-니 참 놀라운 비밀일세<br/>',NULL,29822,1);
INSERT INTO stanza VALUES('K177','2','죄에서 날 해방하려 주 그의 피-를- 흘렸네<br/>주 나와 함께하-려-고 그 몸을 나눠 주셨네<br/>',NULL,29823,2);
INSERT INTO stanza VALUES('K177','3','부활로 주님 변화해 이제는 성-령-되셨네<br/>주 나를 채워 그- 풍-성 내 것이 되게 하셨네<br/>',NULL,29824,3);
INSERT INTO stanza VALUES('K177','4','주께서 거친 경륜을 내 맘에 새-겨-볼 때에<br/>주님의 갈망 보-면-서 주님께 감사드리네<br/>',NULL,29825,4);
INSERT INTO stanza VALUES('K177','5','주님을 먹고 마시며 주님의 인-도-받아서<br/>영 안에 주를 받-을- 때 주 우릴 길러 주시네<br/>',NULL,29826,5);
INSERT INTO stanza VALUES('K177','6','주 나를 채워 내 안에 주 형상 이-룰- 때까지<br/>주님을 먹고 마-시-며 영 안에 흡수하겠네<br/>',NULL,29827,6);
INSERT INTO stanza VALUES('K178','1','떡과 잔을 진열하는 주의 상에 감사해<br/>이 상에서 당신 누려 사랑의 이 잔치를<br/>떡은 주-가 버리신 몸 우리 함-께 나누네<br/>잔은 주가 흘리신 보혈 함께 마시고 맛보네<br/>',NULL,29828,1);
INSERT INTO stanza VALUES('K178','chorus','보라 거룩한 상! 어떠한 표인가!<br/>의미 깊고 영원하여 측량 못하네<br/>',NULL,29829,2);
INSERT INTO stanza VALUES('K178','2','구속하는 죽음 통해 생명 분배하셨네<br/>나로 주께 참여토록 당신 자신 주셨네<br/>떡과 잔-을 나눔으로 주의 죽-음 진열해<br/>주를 먹고 마-심으로 주를 기-념한다네<br/>',NULL,29830,3);
INSERT INTO stanza VALUES('K178','3','떡은 주의 비밀한 몸 몸의 하나 간증해<br/>그 안에서 모든 지체 함께 교통 누리네<br/>우리들-이 축복하는 거룩한- 축복의 잔<br/>피로 인해 모-든 성도 서로 교-통 나누네<br/>',NULL,29831,4);
INSERT INTO stanza VALUES('K178','4','우리들의 영원 분깃 여기에서 맛보네<br/>주의 왕국 기다리며 다시 오심 재촉해<br/>이긴 성- 도들과 함께 왕국 안-에 오실 때<br/>새로웁게 주- 누리며 사랑스-런 신부 돼<br/>',NULL,29832,5);
INSERT INTO stanza VALUES('K179','1','주님-의 상- 주목할 때 그 표-징 놀라워<br/>한 떡-과 한 잔 놓-였네 하나-님 뜻 따라<br/>',NULL,29833,1);
INSERT INTO stanza VALUES('K179','2','이 떡-은 하-늘의 음식 생명-의 떡일세<br/>죽음-으로 분배-하사 풍성- 참예케 해<br/>',NULL,29834,2);
INSERT INTO stanza VALUES('K179','3','이 잔-은 거-룩한 분깃 피로- 성취됐네<br/>축복-의 잔 받음-으로 하나-님 맛보네<br/>',NULL,29835,3);
INSERT INTO stanza VALUES('K179','4','여기-서 이- 떡 나누어 생명- 양식 먹고<br/>사랑- 안에 기념-하여 생명- 공급받네<br/>',NULL,29836,4);
INSERT INTO stanza VALUES('K179','5','하나-님 축-복 누리네 이 잔-을 마시며<br/>들림- 받을 그날-까지 당신- 기념하리<br/>',NULL,29837,5);
INSERT INTO stanza VALUES('K179','6','이 떡-과 잔- 먹고 마셔 죽으-심 진열해<br/>주 우-리 생명이-심을 다 간-증한다네<br/>',NULL,29838,6);
INSERT INTO stanza VALUES('K179','7','잔치-에 앉-아 누리며 끝없-이 경배해<br/>영광-의 그날 오-기를 다함-께 기다려<br/>',NULL,29839,7);
INSERT INTO stanza VALUES('K18','1','하나님의 공의 인 - 해 무릎 꿇고 찬송 - 해<br/>주 안에 날 의롭다 하니 누가 날 참소하 - 랴<br/>공의롭 - 고 신실하 - 신 주 의지해 서 있네<br/>주에게는 영원토 - 록 불의 - 전 - 혀 - 없다 - 네<br/>',NULL,29840,1);
INSERT INTO stanza VALUES('K18','2','나의 죄를 대신 지 - 고 공의 따라 죽은 - 주<br/>주가 의의 요구 이 - 뤄 하나님 만족케 - 해<br/>속전 치 - 뤄 주셨으 - 니 나는 해방되었네<br/>의로우신 하나님 - 이 다시 - 요 - 구 - 하시 - 랴<br/>',NULL,29841,2);
INSERT INTO stanza VALUES('K18','3','아버지가 나 대신 - 에 예수 받으셨으 - 니<br/>의로우신 하나님 - 의 심판 대신 받았 - 네<br/>보좌 우 - 편 앉으신 - 주 의의 증거 되시니<br/>하나님도 의로 인 - 해 영영 - 변 - 치 - 못하 - 네<br/>',NULL,29842,3);
INSERT INTO stanza VALUES('K18','4','속죄하는 보혈로 - 써 하나님의 의 얻 - 어<br/>의가 나를 가리우 - 니 요동할 수 없겠 - 네<br/>내가 주 - 의 의 됐으 - 니 누가 날 정죄하랴<br/>거룩한 성 안에서 - 도 이 간 - 증 - 영 - 원하 - 리<br/>',NULL,29843,4);
INSERT INTO stanza VALUES('K180','1','여기서 주의 얼굴 맞대고 믿음 안에서 실재 붙잡네-<br/>더 깊이 은혜 알기 원하며 내 곤고 주의 발 앞에 두리<br/>',NULL,29844,1);
INSERT INTO stanza VALUES('K180','2','주께서 주신 좋은 것 먹고 축복의 잔을 함께 마시네-<br/>내 모든 어려움 다 잊고서 죄 사함 평강 다시 맛보네<br/>',NULL,29845,2);
INSERT INTO stanza VALUES('K180','3','내 자신 죄 투성이이지만 주님의 행사 공의로우니-<br/>주님의 보혈 나의 죄 씻고 주님의 공의 내 죄 처리해<br/>',NULL,29846,3);
INSERT INTO stanza VALUES('K180','4','주 외에 다른 도움 없으니 사람의 선심 모두 헛되네-<br/>주님의 사랑 내게 있으니 난 만족하고 굳건히 서네<br/>- 아래의 세 절은 떡을 뗀 후에 부름 -<br/>',NULL,29847,4);
INSERT INTO stanza VALUES('K180','5','떡과 잔 속히 지나가지만 구원의 사랑 지나가잖아-<br/>잔치는 속히 지나가지만 주 더욱 친근하여 내 왕 돼<br/>',NULL,29848,5);
INSERT INTO stanza VALUES('K180','6','이 광야에서 다시 밤 올 때 밤 틈타 우린 정복해야 해 -<br/>주께서 부르실 때 좇아가 광명한 성에 우린 이르리<br/>',NULL,29849,6);
INSERT INTO stanza VALUES('K180','7','모이고 흩어지고 또 모여 잔치와 잔치 누리는 우리-<br/>그날에 어린 양과 신부의 기쁨의 잔치 함께 맛보리<br/>',NULL,29850,7);
INSERT INTO stanza VALUES('K181','1','주의 죽음 진열하는 떡과 잔을 대할 때<br/>주 사랑의 역사 새겨 죽음 가치 감상해<br/>피와 살-이 나뉘어져 죽음 이-뤄졌으니<br/>감사하고 경배-하며 주를 찬양-하겠네<br/>',NULL,29851,1);
INSERT INTO stanza VALUES('K181','chorus','주가 쓴 잔 마셔 나는 축복 얻네<br/>주 사랑의 역-사 늘 찬송하겠네<br/>',NULL,29852,2);
INSERT INTO stanza VALUES('K181','2','사랑으로 피를 흘려 하나님께 이끄네<br/>하나님과 거리 없이 항상 그 얼굴 뵙네<br/>하나님-의 영광 성결 공의 요-구 만족 돼<br/>주의 죽음 업적-으로 하나님을- 접촉해<br/>',NULL,29853,3);
INSERT INTO stanza VALUES('K181','3','죽음으로 휘장 열어 지성소로 가게 해<br/>방해물 다 제하시고 시은좌로 가게 해<br/>하나님-의 긍휼 얻고 돕는 은-혜 입게 해<br/>신성 풍성 충만-하게 샘물처럼- 맛보네<br/>',NULL,29854,4);
INSERT INTO stanza VALUES('K181','4','주가 나를 속량하여 제사장이 되게 해<br/>하나님의 면전에서 거룩한 직무 행해<br/>주의 죽-음 통하여서 축복 은-혜 얻었네<br/>새 것으로 마실 날까지 그침없이- 기념해<br/>',NULL,29855,5);
INSERT INTO stanza VALUES('K182','1','주님의 죽음 가르치실 때 하나를 위해 기도하셨네<br/>우리가 주 뜻 성취하도록 주 죽음 항상 보여 주소서<br/>우리가 떼는- 이 한 떡으로 표시된 한 몸 다 이루도록<br/>',NULL,29856,1);
INSERT INTO stanza VALUES('K182','2','주 교회 위해 기도하오니 다시는 나뉨 없게 하소서<br/>서로 긴밀히 연결되도록 우리의 마음 끌어 주소서<br/>우리가 떼는- 이 한 떡으로 표시된 한 몸 다 이루도록<br/>',NULL,29857,2);
INSERT INTO stanza VALUES('K182','3','떠난 양 위해 기도하오니 선한 목자여 돌이키소서<br/>처음에 있던 진리 안으로 진리가 있는 교회 안으로<br/>우리가 떼는- 이 한 떡으로 표시된 한 몸 곧 갖게 되리<br/>',NULL,29858,3);
INSERT INTO stanza VALUES('K182','4','이 모든 상징 지나갈 때에 하늘 시온과 하나 되리라<br/>온 성도들과 평강 누리며 한없이 서로 사랑하리라<br/>하나님 아들과 영원 영원히 사랑과 평강 누리게 되리<br/>',NULL,29859,4);
INSERT INTO stanza VALUES('K183','1','저주는 주 받으셨고 축복은 내가 누리네<br/>쓴 잔은 주가 마셨고 잔치는 내가 누리네<br/>',NULL,29860,1);
INSERT INTO stanza VALUES('K183','2','깊고도 깊은 그 사랑 누가 다 측량하리요<br/>내 혼아 일어나거라 주 힘껏 찬양하여라<br/>',NULL,29861,2);
INSERT INTO stanza VALUES('K184','1','사-람들 그 날 밤에 주 곁에 있었네<br/>흑-암이 몰려 주 맘 고통케 하였네<br/>이렇게 행한 것은 날 기념케 함이라<br/>말씀따라 우린 지금 주를 기념하네<br/>',NULL,29862,1);
INSERT INTO stanza VALUES('K184','2','주- 나를 위해 마신 진노의 쓴 잔과<br/>주- 나를 위해 받은 죽음의 침례여<br/>갈보리에서 주님 버림 받-으셨네<br/>주님께 우린 감사해 주 기념한다네<br/>',NULL,29863,2);
INSERT INTO stanza VALUES('K184','3','그-날 어두움 몰려 주 공격하였네<br/>큰- 물결 파도 몰려 주 엄습하였네<br/>무궁한 은혜 사랑 거기에-있으니<br/>슬픔과 기쁨 겹치어 주 기념한다네<br/>',NULL,29864,3);
INSERT INTO stanza VALUES('K184','4','주- 이미 부활하여 첫 열매 되셨네<br/>아-버지 우편에서 교회의 머리 돼<br/>주 인해 구출되어 열납되-었으니<br/>주님만 사모하면서 늘 기념하겠네<br/>',NULL,29865,4);
INSERT INTO stanza VALUES('K184','5','대- 환난 피하도록 날 휴거시키사<br/>영-원히 주와 함께 안식케 하소서<br/>난 계속 주의 죽음을 본받-으리라<br/>주 존경하고 사랑해 늘 기념하리라<br/>',NULL,29866,5);
INSERT INTO stanza VALUES('K185','1','거-룩한 상징 이 떡 인-해 난 주-께 감-사해<br/>하나님 비밀 보 -게-돼 이 떡-을 인-하여<br/>',NULL,29867,1);
INSERT INTO stanza VALUES('K185','2','이- 떡은 우리 위-하-신 주의- 몸 표-명해<br/>날 주 생명에 참 -예-해 주 얻-게 하-셨네<br/>',NULL,29868,2);
INSERT INTO stanza VALUES('K185','3','날- 위해 자신 분배하-려 주의- 몸 여-셨네<br/>주님의 생명 얻 -게-해 주 배-필 되-게 해<br/>',NULL,29869,3);
INSERT INTO stanza VALUES('K185','4','이-떡은 또한 가-리-켜 비밀-한 주-의 몸<br/>우리는 주의 지 -체-들 주님-과 하-날세<br/>',NULL,29870,4);
INSERT INTO stanza VALUES('K185','5','많-은 밀알인 우-리-가 한 떡-이 되-었네<br/>여기서 주를 기 -념-해 주 공-급 누-리네<br/>',NULL,29871,5);
INSERT INTO stanza VALUES('K185','6','이- 떡을 인해 교-통-해 주 만-족게- 하네<br/>온 성도들과 교 -통하며 주 풍-성 간-증해<br/>',NULL,29872,6);
INSERT INTO stanza VALUES('K186','1','은-혜의 이 잔치- 거-룩해 달콤해<br/>이 떡과 잔을 누리며 주 기념한다네<br/>',NULL,29873,1);
INSERT INTO stanza VALUES('K186','2','아-버지 모든 뜻- 주-님의 은혜를<br/>우리는 모두 여기서 보기를 원하네<br/>',NULL,29874,2);
INSERT INTO stanza VALUES('K186','3','생-명떡 달콤함- 내- 공급 되었네<br/>내 영은 이제 만족해 주 간증하겠네<br/>',NULL,29875,3);
INSERT INTO stanza VALUES('K186','4','하-나님 요구를- 보-혈이 채웠네<br/>양심에 정죄 없으니 기쁨이 넘치네<br/>',NULL,29876,4);
INSERT INTO stanza VALUES('K186','5','사-랑스런 잔치- 달-콤한 이 잔치<br/>그날 주 함께 앉으면 더 달콤하겠네<br/>',NULL,29877,5);
INSERT INTO stanza VALUES('K186','6','나- 주 얼굴 뵙고- 주-형체 입을 때<br/>기묘하신 모든 은혜 다 간증하리라<br/>',NULL,29878,6);
INSERT INTO stanza VALUES('K187','1','자신 낮춘 아들과 비 같은 주 은혜와<br/>이 떡과 잔 인하여 감사를 드리세<br/>',NULL,29879,1);
INSERT INTO stanza VALUES('K187','2','변함없는 떡과 잔 이를 통해 나타난<br/>거룩하신 사랑에 감사를 드리네<br/>',NULL,29880,2);
INSERT INTO stanza VALUES('K187','3','우릴 부른 주 향해 믿음으로 나아가<br/>주의 구원 보면서 감사를 드리네<br/>',NULL,29881,3);
INSERT INTO stanza VALUES('K187','4','온유하신 내 주님 가난한 길 가셨네<br/>그 길 기념하면서 감사를 드리네<br/>',NULL,29882,4);
INSERT INTO stanza VALUES('K187','5','다시 오실 때까지 이같이 행하라신<br/>주의 사랑 이끄니 감사를 드리네<br/>',NULL,29883,5);
INSERT INTO stanza VALUES('K187','6','내 생명 된 주님을 표명하는 이 떡을<br/>끝날까지 떼면서 감사를 드리네<br/>',NULL,29884,6);
INSERT INTO stanza VALUES('K187','7','참 축복인 주님을 표명하는 이 잔을<br/>끝날까지 마시며 감사를 드리네<br/>',NULL,29885,7);
INSERT INTO stanza VALUES('K187','8','그날 가까울수록 영광의 왕국 보며<br/>다시 오실 주님께 감사를 드리네<br/>',NULL,29886,8);
INSERT INTO stanza VALUES('K188','1','태초-부터 계신 주님 상고-에 근원- 있-네<br/>우주-보다 먼저 계신 전능-하신 하-나-님<br/>시작- 없고 끝도 없어 아비- 어미도 없-네<br/>족보- 없고 변함 없네 연대- 다함 없-는- 주<br/>',NULL,29887,1);
INSERT INTO stanza VALUES('K188','2','만물- 창조하신 주님 만유-의 근원-일-세<br/>만유- 주재 만유 머리 만유- 으뜸 되-신- 분<br/>그의- 말씀 만물 잡고 만물-이 주 의지-해<br/>만물- 승계하실 주께 만물- 돌아가-리-라<br/>',NULL,29888,2);
INSERT INTO stanza VALUES('K188','3','육신- 되신 그리스도 장막- 치고 오-셨-네<br/>처녀- 몸을 통해 나셔 육신- 입은 하-나-님<br/>자신- 낮춰 종이 되신 하나-님 사람일-세<br/>하나-님의 영광 광채 하나-님 본체- 형-상<br/>',NULL,29889,3);
INSERT INTO stanza VALUES('K188','4','십자-가에 죽은 주님 내 죄- 담당하-셨-네<br/>하나-님의 심판받고 죽음- 쓴 맛 보-셨-네<br/>내 옛- 사람 함께 끝내 사탄- 마귀 없-이 해<br/>날 완-전히 해방했네 죄의- 권세로-부-터<br/>',NULL,29890,4);
INSERT INTO stanza VALUES('K188','5','죽음-에서 부활하여 처음- 익은 열-매-돼<br/>나도- 함께 부활하여 생명- 나눠 받-았-네<br/>한 알- 밀알 되신 주님 많은- 밀알 얻었-네<br/>하나-에서 나온 우리 주의- 형제 되-었-네<br/>',NULL,29891,5);
INSERT INTO stanza VALUES('K188','6','성령-되신 그리스도 내 영- 안에 오-셨-네<br/>나로- 주님 성품 안에 참예-하게 하-셨-네<br/>내 안-에서 형상 이뤄 주의- 형상 되게- 해<br/>나로- 주님 풍성 누려 주의- 신장 갖-게- 해<br/>',NULL,29892,6);
INSERT INTO stanza VALUES('K188','7','높은- 하늘 오른 주님 만왕-의 왕 되-셨-네<br/>존귀- 영광 관을 쓰고 높은- 이름 얻-었-네<br/>또한- 나를 이끄시어 하늘- 위에 앉게- 해<br/>나로- 주의 권위 누려 강건-하게 하-시-네<br/>',NULL,29893,7);
INSERT INTO stanza VALUES('K188','8','주가- 성령 내리시니 교회- 세워졌-다-네<br/>기능- 위해 은사 주셔 몸 된- 교회 건-축-해<br/>교회-들을 보양하고 교회- 통해 표현-돼<br/>교회-는 이 우주 안에 주의- 연장 확-장-돼<br/>',NULL,29894,8);
INSERT INTO stanza VALUES('K188','9','왕국- 위해 임할 주님 그의- 성도 올-리-리<br/>원수- 밟고 심판하셔 그의- 왕국 세-우-리<br/>성도-들과 왕 노릇 해 땅 끝-까지 다스-려<br/>화평- 노래 넘칠 때에 온 땅- 안식 누-리-리<br/>',NULL,29895,9);
INSERT INTO stanza VALUES('K188','10','영세- 중심 되신 주님 거룩-한 성 얻-으-리<br/>천지-만물 새로워져 낡은- 것 다 벗-으-리<br/>하나-님은 빛이시요 어린- 양은 등이-라<br/>주의- 표현 거룩한 성 영원-토록 빛-나-리<br/>',NULL,29896,10);
INSERT INTO stanza VALUES('K189','1','어린 양의 선한 새 노래 영광의 주 영광의 주<br/>이 복음은 무한한 기쁨 주 영광 높이세<br/>보좌를 떠나 이 땅에 우리를 구속하셨네<br/>이 은혜 세상엔 없어 모든 사람 놀라네<br/>',NULL,29897,1);
INSERT INTO stanza VALUES('K189','chorus','큰 소리로 불러 화답해 영광의 주 영광의 주<br/>이런 찬미 다시 없도다 주 영광 높이세<br/>',NULL,29898,2);
INSERT INTO stanza VALUES('K189','2','하늘에서 찬미 들리네 영광의 주 영광의 주<br/>그는 빛과 사랑 되시네 주 영광 높이세<br/>세상에 슬퍼 우는 자 땅 위에 모든 죄인들<br/>그 어떤 사람이든지 죄빚 모두 갚았네<br/>',NULL,29899,3);
INSERT INTO stanza VALUES('K189','3','찬미하세 심판 지났네 영광의 주 영광의 주<br/>부활했네 주와 연합해 지극히 높은 주<br/>우리는 무덤 저 편에 사망은 다시 못 오리<br/>원수는 홍해에 묻고 의의 확신 주셨네<br/>',NULL,29900,4);
INSERT INTO stanza VALUES('K189','4','외치라 주 다시 오시리 영광의 주 영광의 주<br/>교회 성숙 늦지 않으리 지극히 높은 주<br/>전에 구하던 모든 것 지금은 모두 받았네<br/>내 마음 영원히 열고 주 함께 전진하리<br/>',NULL,29901,5);
INSERT INTO stanza VALUES('K189','5','청아하게 다시 불러라 영광의 주 영광의 주<br/>이 찬송 부르고 불러라 지극히 높은 주<br/>찬송할 때 맘 기쁘고 천지에 가득 퍼지네<br/>사랑스럽다 새 창조 쉬지 말고 찬송해<br/>',NULL,29902,6);
INSERT INTO stanza VALUES('K19','1','거룩하신 아버지께 무릎 꿇고 찬송해<br/>그의 거룩 그의 초월 존경받기 합당해<br/>',NULL,29903,1);
INSERT INTO stanza VALUES('K19','2','하나님 마음은 사랑 그의 역사 공의요<br/>그의 성품 거룩이니 나로 참예하게 해<br/>',NULL,29904,2);
INSERT INTO stanza VALUES('K19','3','주의 보혈 나를 영영 거룩하게 하셨고<br/>주의 진리 내 온 존재 분별되게 하셨네<br/>',NULL,29905,3);
INSERT INTO stanza VALUES('K19','4','주의 성령 날 성별해 주께 돌아가게 해<br/>내 온 존재 영 혼 몸을 거룩하게 하시네<br/>',NULL,29906,4);
INSERT INTO stanza VALUES('K19','5','주 은혜로 나는 이미 거룩한 생명 얻어<br/>거룩하신 그 성품에 참예하게 되었네<br/>',NULL,29907,5);
INSERT INTO stanza VALUES('K19','6','거룩한 성 그 안에서 거룩함에 참예해<br/>놀라우신 주의 성결 영영 간증하겠네<br/>',NULL,29908,6);
INSERT INTO stanza VALUES('K190','1','찬미하세 우리의 구속주 예수 노래하세<br/>기이한 그 사랑 성도들아 그리스도를 칭송해<br/>존귀 능력 그분께 있으니 목자같-이 주 그의<br/>양들 길러 그의 품에 평안 누리게 해<br/>',NULL,29909,1);
INSERT INTO stanza VALUES('K190','chorus','찬미하세 주님의 기묘한 사랑<br/>칭송하세 거룩한 주 이름<br/>',NULL,29910,2);
INSERT INTO stanza VALUES('K190','2','찬미하세 우리의 구속주 예수 내 죄 위해<br/>형벌을 받았네 칭송하세 견고한 반석이신 주<br/>영원하신 구원을 이뤘네 나의 고-통 담당한<br/>크신 사랑 순결하고 견고한 그 사랑<br/>',NULL,29911,3);
INSERT INTO stanza VALUES('K190','3','찬미하세 우리의 구속주 예수 하늘 문을<br/>울리는“호산나”관 씌우세 만유의 주이신<br/>예수 영원토록 제사장 왕 되네 모두 이-겨<br/>왕국을 세운 주께 영광 권위 영원히 돌리세<br/>',NULL,29912,4);
INSERT INTO stanza VALUES('K191','1','피를 흘-려- 구원하려 목숨 버-린- 주 이제<br/>내 안에 사니 전능 영-광 나라 주께 있다네<br/>',NULL,29913,1);
INSERT INTO stanza VALUES('K192','1','오직 예수 오직 예수 내 구주 당신만을 경배해<br/>오직 예수 오직 예수 내 구주 당신만을 경배해<br/>',NULL,29914,1);
INSERT INTO stanza VALUES('K192','2','오직 예수 오직 예수 내 구주 당신만을 찬미해<br/>오직 예수 오직 예수 내 구주 당신만을 찬미해<br/>',NULL,29915,2);
INSERT INTO stanza VALUES('K192','3','오직 예수 오직 예수 내 구주 당신께만 감사해<br/>오직 예수 오직 예수 내 구주 당신께만 감사해<br/>',NULL,29916,3);
INSERT INTO stanza VALUES('K192','4','오직 예수 오직 예수 내 구주 당신만을 높이리<br/>오직 예수 오직 예수 내 구주 당신만을 높이리<br/>',NULL,29917,4);
INSERT INTO stanza VALUES('K193','1','영원토록 그리스도<br/>나의 구주 할렐-루야 할렐-루-야<br/>할렐루야- 주 찬미해<br/>',NULL,29918,1);
INSERT INTO stanza VALUES('K194','1','하나-님 영이 이-제는 그리스도 영이요 실재의 영<br/>그는- 내 안에 거-하며 내 실-제 공급되시네<br/>',NULL,29919,1);
INSERT INTO stanza VALUES('K194','2','하나-님 체현이-신 주 하나-님 나-타내-시고<br/>영은- 또 주의 표-현돼 생명-된 주를 계시해<br/>',NULL,29920,2);
INSERT INTO stanza VALUES('K194','3','하나-님 본성 모든 충만 그 안-에 육-체로- 거해<br/>주님-은 풍성 가-지고 실재-로 그 영 되셨네<br/>',NULL,29921,3);
INSERT INTO stanza VALUES('K194','4','아버-지 아들 되-시고 아들-은 지-금 그- 영 돼<br/>근원-과 유출 흘-러옴 삼일-의 하나님일세<br/>',NULL,29922,4);
INSERT INTO stanza VALUES('K194','5','그 영- 날 강건케-하고 내 맘-에 거-처 정-하네<br/>아버-지 모든 충-만이 내 전-체 충만케 하네<br/>',NULL,29923,5);
INSERT INTO stanza VALUES('K194','6','아들-을 통해 보-았네 아버-지 모-든 충-만을<br/>이제-영 안에 체-험해 생명-과 만유인 아들<br/>',NULL,29924,6);
INSERT INTO stanza VALUES('K194','7','날 주-로 충만되-어서 주 풍-성 다- 누리-도록<br/>그 영-으로 날 채우소서 거룩-한 주의 실재를<br/>',NULL,29925,7);
INSERT INTO stanza VALUES('K195','1','나는 죄에서 해방되기 원하여 전심으로 기도했었네<br/>오늘 주께서 나의 기도 응답해 성령 나타내셨네<br/>',NULL,29926,1);
INSERT INTO stanza VALUES('K195','chorus','나의 맘에 나타난 성령 나를 해방해<br/>죄를 벗게 하셨네 내게 찬양 넘치네 성령 나타내셨네<br/>',NULL,29927,2);
INSERT INTO stanza VALUES('K195','2','나는 강하길 진정 원하였으나 연약하여 할 수 없었네<br/>주가 은혜로 기쁨 충만케 했네 성령 나타내셨네<br/>',NULL,29928,3);
INSERT INTO stanza VALUES('K195','3','나의 맘 열려 간증할 수 있다네 성령의 기묘한 능력을<br/>나는 죄 씻고 교만에서 떠났네 성령 나타내셨네<br/>',NULL,29929,4);
INSERT INTO stanza VALUES('K195','4','주가 날 씻어 투명하게 됐으니 오늘 내게 확신 넘치네<br/>지금 내 영에 은혜 충만하다네 성령 나타내셨네<br/>',NULL,29930,5);
INSERT INTO stanza VALUES('K196','1','이제 우리 하나님의 영 예수 그리스도의 영 됐네<br/>부활하신 하나님 사람 승천하여 그 영 되셨네<br/>',NULL,29931,1);
INSERT INTO stanza VALUES('K196','2','승천하신 예수로부터 내 영 안에 그 영이 임했네<br/>그의 모든 실재 이-제 우리 체험 되게 하셨네<br/>',NULL,29932,2);
INSERT INTO stanza VALUES('K196','3','예수 그리스도의- 영 모든 성분을 포함하였네<br/>신-성과 인성도 있고 하나님의 영광 감춰져<br/>',NULL,29933,3);
INSERT INTO stanza VALUES('K196','4','이 영 안에 포함돼 있네 죽음 효능 부활의 능력<br/>승천 보좌 권위와 왕국 하나님의 모든 성분이<br/>',NULL,29934,4);
INSERT INTO stanza VALUES('K196','5','이 영이 그 모든 성분을 내 영 안에서 역사하시네<br/>그의 기름부음 통하여 나도 주의 풍성 누리네<br/>',NULL,29935,5);
INSERT INTO stanza VALUES('K196','6','나의 모든 비결 되-신 만유 포함한 그 영 인하여<br/>하나님 내 모든 것 되어 내 안에서 역사하시네<br/>',NULL,29936,6);
INSERT INTO stanza VALUES('K197','1','이 기쁜 소식을 온 땅에 전하세 큰 환난<br/>고통을 당하는 자에게 모든 믿는 이들<br/>다 전할 소식은 보혜사 오셨네<br/>',NULL,29937,1);
INSERT INTO stanza VALUES('K197','chorus','보혜사 오셨네 보혜사 오셨네 주 약속 이루사<br/>성령을 보냈네 온 땅에 이 소식 널리 전파하세<br/>보혜사 오셨네<br/>',NULL,29938,2);
INSERT INTO stanza VALUES('K197','2','어둔 밤 지나고 새벽이 되었네 슬픈<br/>울음소리 애통은 지났네 먼 산에 새벽빛<br/>이미 찬란하니 보혜사 오셨네<br/>',NULL,29939,3);
INSERT INTO stanza VALUES('K197','3','치료하는 광선 가지고 오신 왕 모든<br/>죄수들을 다 해방하셨네 이제 저 감옥은<br/>텅빈 곳 되었네 높이 개가 불러<br/>',NULL,29940,4);
INSERT INTO stanza VALUES('K197','4','내 둔한 입술로 방랑자들에게 무한한<br/>이 사랑 늘 전파하겠네 죄인인 내 안에<br/>거하려 오신 주 그 은혜 전하리<br/>',NULL,29941,5);
INSERT INTO stanza VALUES('K197','5','우주와 궁창에 메아리치도록 무궁한<br/>사랑을 높이 노래하세 이 땅에 하늘에<br/>찬송의 물결이 메아리치도록<br/>',NULL,29942,6);
INSERT INTO stanza VALUES('K198','1','사람들은 주- 예-수-를 나사-렛 사람으로<br/>멸시하-고- 마지막엔 십자가-에- 달았네<br/>사람 눈-엔 주의 역-사 아주 끝난듯 했네<br/>',NULL,29943,1);
INSERT INTO stanza VALUES('K198','2','주 예수님 승-천-할- 때 하늘- 상황 달랐네<br/>하나님-이- 우주에게 준비하-라- 명했네<br/>주가 우-주 머리 되-심 환영하는 음악을<br/>',NULL,29944,2);
INSERT INTO stanza VALUES('K198','3','이제 주와 그-리-스-도 되신- 구주 예수님<br/>하늘에-나- 땅 위에서 주의 뛰-어-남 알아<br/>굴복 않-는 사람 없-네 순종 않는 자 없네<br/>',NULL,29945,3);
INSERT INTO stanza VALUES('K198','4','멀고 먼 저 하-늘- 일-을 내가- 어찌 알리요<br/>모든 사-실- 증거하려 성령 내-려- 오셨네<br/>나의 몸-에 은사 되-어 예수 권세 증명해<br/>',NULL,29946,4);
INSERT INTO stanza VALUES('K198','5','나의 안의 성 -령-께-서 그리-스도 증명해<br/>하나님-의- 그리스도 성령으-로- 내주해<br/>참되고-도 견고하-신 예수 내 주 되셨네<br/>',NULL,29947,5);
INSERT INTO stanza VALUES('K198','6','영영 변치 않 -는- 사-실 예수-님은 주시라<br/>내 안으-로- 오신 성령 내게 주-신- 은사니<br/>성령 은-사 내게 주-심 다만 찬송하겠네<br/>',NULL,29948,6);
INSERT INTO stanza VALUES('K199','1','영광의- 주 하늘서 그의 성-령 내렸네<br/>성령의 각종 은혜를 교회에게 주셨네<br/>주여 신-실함 따라 내-게 은-사 주소서<br/>',NULL,29949,1);
INSERT INTO stanza VALUES('K199','2','오늘 주- 이름 안에 침례 받-아 한 영 돼<br/>주-의 몸을 얻었네 은사와 주의 소유<br/>나도 한- 지체이니 능-력 받-을 수 있네<br/>',NULL,29950,2);
INSERT INTO stanza VALUES('K199','3','주의 이-름 전하게 내게 능-력 주소서<br/>주-의 구원 전하게 내게 은사 주소서<br/>주의 백-성 섬기게 내-게 지-식 주소서<br/>',NULL,29951,3);
INSERT INTO stanza VALUES('K199','4','여기서- 안수받고 은사 원해 서원하니<br/>주-의 사실 따라서 무궁한 능력 내려<br/>어디서-나 유용한 그-릇 되-게 하소서<br/>',NULL,29952,4);
INSERT INTO stanza VALUES('K2','1','영광 영광 영광 찬양 경배하세<br/>파도 같은 찬송 영원토록 들리네<br/>성부 성자 성령 계시되셨으니<br/>모두 다 무릎 꿇고 경배해<br/>',NULL,29953,1);
INSERT INTO stanza VALUES('K2','2','무한 부요하신 근원이신 성부<br/>권능 명령으로 만유 붙드신 성자<br/>영광으로 만유 채우시는 성령<br/>오 정녕 찬송 받기 합당해<br/>',NULL,29954,2);
INSERT INTO stanza VALUES('K2','3','만유 근원이신 존귀한 하나님<br/>성결로써 우린 단장하고 경배해<br/>위엄 존귀 권능 영광 초월 탁월<br/>다 만유 근원 당신께 속해<br/>',NULL,29955,3);
INSERT INTO stanza VALUES('K20','1','오 아버지는 지혜로써 갈망을 따라<br/>이 만유 안에 그의 아들 충만케 하네<br/>',NULL,29956,1);
INSERT INTO stanza VALUES('K20','chorus','오 깊고 깊은 이 지혜를 누가 재리요<br/>그 지혜 인해 나도 은혜 긍휼 받았네<br/>',NULL,29957,2);
INSERT INTO stanza VALUES('K20','2','당신에게서 만유 나와 당신께 가니<br/>나 여기에서 당신 지혜 보고 놀라네<br/>',NULL,29958,3);
INSERT INTO stanza VALUES('K20','3','죄 중에 있는 사람에게 긍휼 나타내<br/>모든 입으로 당신 이름 시인케 하네<br/>',NULL,29959,4);
INSERT INTO stanza VALUES('K20','4','십자가 통해 나를 위해 구속 이루사<br/>귀하신 당신 내 영 안에 오게 하셨네<br/>',NULL,29960,5);
INSERT INTO stanza VALUES('K20','5','교회로 인해 정사들이 주 풍성 알고<br/>각종 지혜를 하늘에서 깨닫게 되네<br/>',NULL,29961,6);
INSERT INTO stanza VALUES('K20','6','새 예루살렘에서 긍휼 자랑할 때에<br/>당신의 지혜 완전하게 나타나겠네<br/>',NULL,29962,7);
INSERT INTO stanza VALUES('K200','1','주 하나님의 거룩의 영 지금 생명 영일세<br/>날 살리시고 생명 주사 주께 적합게 하네<br/>',NULL,29963,1);
INSERT INTO stanza VALUES('K200','2','주 나의 갈증 푸는 생수 생명 흐름 공급해<br/>내 생명이신 그리스도 내 갈망 다 이루네<br/>',NULL,29964,2);
INSERT INTO stanza VALUES('K200','3','주 생명 빛을 내게 비춰 흑암 몰아 내소서<br/>주 그리스도 비춰질 때 맑은 하늘 나타나<br/>',NULL,29965,3);
INSERT INTO stanza VALUES('K200','4','날 능력으로 강건케 해 속사람에 능력 줘<br/>내 능력 되신 그리스도 주 뜻 위해 은혜 줘<br/>',NULL,29966,4);
INSERT INTO stanza VALUES('K200','5','그 거룩하신 생명의 법 죄에서 날 해방해<br/>주 거룩하신 성품 통해 나를 규제하시네<br/>',NULL,29967,5);
INSERT INTO stanza VALUES('K200','6','이 생명의 영 나를 통해 풍성한 열매 맺네<br/>주 각종 미덕 나타내며 주를 공급게 하네<br/>',NULL,29968,6);
INSERT INTO stanza VALUES('K200','7','이 생명의 영 생명 주사 나를 변케 하시네<br/>내 속부분을 새롭게 해 그리스도 닮게 해<br/>',NULL,29969,7);
INSERT INTO stanza VALUES('K200','8','이 생명의 영 내 각 부분 충만하게 하소서<br/>주 생명으로 나를 적셔 주 나타낼 때까지<br/>',NULL,29970,8);
INSERT INTO stanza VALUES('K201','1','주여 파내소서 모든 장애물을<br/>주의 흐름 나를 통해 흐르도록<br/>',NULL,29971,1);
INSERT INTO stanza VALUES('K201','2','반석인 주 깨져 생수 흐르지만<br/>내 마음은 막혀 흐르지 못하네<br/>',NULL,29972,2);
INSERT INTO stanza VALUES('K201','3','기도로 파 내리 흙 완전히 파리<br/>흐름 흐르도록 영을 해방하리<br/>',NULL,29973,3);
INSERT INTO stanza VALUES('K201','4','반석인 주 다시 깨질 필요 없네<br/>오직 파내는 데 나를 드려야 해<br/>',NULL,29974,4);
INSERT INTO stanza VALUES('K201','5','내 필요는 오직 성령 충만하여<br/>나의 맘 속에서 생수 솟는 걸세<br/>',NULL,29975,5);
INSERT INTO stanza VALUES('K201','6','파 내소서 주여 남김없이 모두<br/>생명수의 흐름 흘러가기까지<br/>',NULL,29976,6);
INSERT INTO stanza VALUES('K201','7','주여 파 내소서 생수 흐르도록<br/>주의 흐름 나를 통해 흐르도록<br/>',NULL,29977,7);
INSERT INTO stanza VALUES('K202','1','이스라엘 백성 저 광야에서 고갈 되었을 때<br/>주님 명했네“생수 나게 반석 명하라”<br/>반석은 이미 갈라졌으니 또 다시 칠 필요없다네<br/>',NULL,29978,1);
INSERT INTO stanza VALUES('K202','chorus','생수나게 반석 명하라 성령은 이미 주어졌으니<br/>모든 풍성을 받아들여라 순복만하면 부요 얻으리<br/>',NULL,29979,2);
INSERT INTO stanza VALUES('K202','2','만세 반석 지금 열려져 있네 성령의 은사도<br/>기다린다네 발버둥쳐 무엇 얻었나<br/>다만 주님과 연합될 때에 요단 건너 성령 얻겠네<br/>',NULL,29980,3);
INSERT INTO stanza VALUES('K202','3','단순한 맘으로 믿기만 하라 평강의 맘으로<br/>주만 구하라 주님 품에 안식하면서<br/>세상 젖 끊고 주 사랑 맛봐 주 충만할 때에 안식해<br/>',NULL,29981,4);
INSERT INTO stanza VALUES('K203','1','하늘의 보-좌에서 생명수 강 흐르네<br/>축복을 흠-뻑 담고 그리스도로부터<br/>',NULL,29982,1);
INSERT INTO stanza VALUES('K203','chorus','값없이 모-두 마실 생명수 날- 거쳐<br/>모든 사람-의 갈증 풀도록 흐르소서<br/>',NULL,29983,2);
INSERT INTO stanza VALUES('K203','2','수정과 같-은 생수 풍성한 공급 있네<br/>목마른 자- 마시면 생명을 얻게 되네<br/>',NULL,29984,3);
INSERT INTO stanza VALUES('K203','3','주여 날 통-로 되게 정결케 해 주소서<br/>나로 주 순-종케 해 날 사용하옵소서<br/>',NULL,29985,4);
INSERT INTO stanza VALUES('K203','4','생수강 흐-를 때는 바로 지금 이땔세<br/>이렇게 흐-를 때에 주 풍성 알-게 돼<br/>',NULL,29986,5);
INSERT INTO stanza VALUES('K203','5','모든 것 가-져와서 주의 발 앞에 드려<br/>범사에 생-수 나를 넘치고 흐르도록<br/>',NULL,29987,6);
INSERT INTO stanza VALUES('K204','1','수정 같은- 생수 강 하늘 보좌서 흘러<br/>어디든지- 흐르네 권위와 교통 갖고<br/>',NULL,29988,1);
INSERT INTO stanza VALUES('K204','chorus','생수의 강- 흐를 때 어디나 막힘없네<br/>어디든지- 흐르네 권위와 교통갖고<br/>',NULL,29989,2);
INSERT INTO stanza VALUES('K204','2','생명강은-곧 성령 하나님 흐름일세<br/>권위를 갖-고 흘러 어디든 막힘없이<br/>',NULL,29990,3);
INSERT INTO stanza VALUES('K204','3','정금길 가-운데로 생명의 강이 흘러<br/>신성의 생-수 있는 그 곳에 길이 있네<br/>',NULL,29991,4);
INSERT INTO stanza VALUES('K204','4','강 좌우 생-명나무 음식이신 하나님<br/>막힘없이- 강 흘러 한없이 공급 넘쳐<br/>',NULL,29992,5);
INSERT INTO stanza VALUES('K204','5','생수 나오-게 하려 주 갈라지셨으니<br/>주 생수 흐-르도록 날 깨뜨려 주소서<br/>',NULL,29993,6);
INSERT INTO stanza VALUES('K205','1','생수가 넘쳐 흐르네 영광의 성전에서<br/>성전의 입구를 거쳐 분별의 경계까지<br/>',NULL,29994,1);
INSERT INTO stanza VALUES('K205','chorus','하나님의 생수 신선한 공급되네<br/>사망을 모두 삼키고 생명 풍성 나타내<br/>',NULL,29995,2);
INSERT INTO stanza VALUES('K205','2','생수가 넘쳐 흐르네 신성한 영광 위해<br/>제단에 다 바치도록 모든 장애 뚫고서<br/>',NULL,29996,3);
INSERT INTO stanza VALUES('K205','3','생수가 넘쳐 흐르네 범사에 척량받아<br/>하나님 심판을 거쳐 주가 모두 얻으리<br/>',NULL,29997,4);
INSERT INTO stanza VALUES('K205','4','생수가 갈수록 넘쳐 헤엄칠 강이 되니<br/>스스로 행하지 못해 은혜로만 살겠네<br/>',NULL,29998,5);
INSERT INTO stanza VALUES('K206','1','내 마음대로 방랑하여 성령 근심케 하고<br/>나 냉담하고 후퇴해도 그는 미워 안 했네<br/>',NULL,29999,1);
INSERT INTO stanza VALUES('K206','chorus','성령을 더욱 많이 주사 비추고 태우소서<br/>늘- 기도하기 원하오니 생명 공급주소서<br/>',NULL,30000,2);
INSERT INTO stanza VALUES('K206','2','내 마음 돌아설 때까지 인내하신 성-령<br/>날 위해 근심한 그 사랑 나는 거절했었네<br/>',NULL,30001,3);
INSERT INTO stanza VALUES('K206','3','오늘 내 맘에 있는 성령 나의 주로 삼으리<br/>주님의 작은 한 말씀도 나는 경외하겠네<br/>',NULL,30002,4);
INSERT INTO stanza VALUES('K206','4','난 주의 사랑하심같이 사랑하지 못하나<br/>주께서 내 맘 불 붙이면 나도 불타게 되리<br/>',NULL,30003,5);
INSERT INTO stanza VALUES('K207','1','내 가난한 맘에 주 능력 주셨네<br/>시시로 돕고 또 은혜를 주시네<br/>성령이 거하며 내 전체 다스려<br/>사랑의 불길이 내 맘 속 불태워<br/>',NULL,30004,1);
INSERT INTO stanza VALUES('K207','chorus','내 맘에 불타네 내 맘에 불타네 하늘로부터<br/>사랑의 불 내리네 보혜사 성령 이미 내려왔다네<br/>그 사랑의 불 나의 마음 태우네<br/>',NULL,30005,2);
INSERT INTO stanza VALUES('K207','2','십자가 아래서 내 머리 숙이며<br/>단 위에 내 일생 다 헌신합니다<br/>날 구속하시어 안식 얻게 한 주<br/>하늘의 불 내려 산 제물 열납해<br/>',NULL,30006,3);
INSERT INTO stanza VALUES('K207','3','내 공로 없으니 주 약속 뿐일세<br/>아들이 벌 받아 난 은혜 받았네<br/>내 마음 속에서 불타는 이 사랑<br/>날 강권하여서 주 사랑케 하네<br/>',NULL,30007,4);
INSERT INTO stanza VALUES('K208','1','주여 불타는 영을 나에게 주옵소서<br/>자신 위한 기쁨을 모두 다 태우소서<br/>',NULL,30008,1);
INSERT INTO stanza VALUES('K208','chorus','나의 평생 소원은 오직 불타는 영 뿐<br/>내 소원들어 주사 내 전체 태우소서<br/>주여 우린 성령 앙망합니다<br/>',NULL,30009,2);
INSERT INTO stanza VALUES('K208','2','제단 앞에 나아와 내 온 존재 드리니<br/>정욕서 날 해방해 영으로 채우소서<br/>',NULL,30010,3);
INSERT INTO stanza VALUES('K208','3','보배로운 주 위해 내 일생 드리오니<br/>구속 위해 피 흘린 주 위해 태우소서<br/>',NULL,30011,4);
INSERT INTO stanza VALUES('K208','4','피로 인한 권리를 믿음으로 취하며<br/>주 이름 의지하니 약속 이뤄 주소서<br/>',NULL,30012,5);
INSERT INTO stanza VALUES('K209','1','주 예수 승리의 사랑 내 맘에 부어져<br/>다시는 요동치 않고 뿌-리를 내리네 뿌-리를 내리네<br/>',NULL,30013,1);
INSERT INTO stanza VALUES('K209','2','거룩한 불이 내 맘에 한없이 타올라<br/>천박한 모든 것 태워 산-도 녹이소서 산-도 녹이소서<br/>',NULL,30014,2);
INSERT INTO stanza VALUES('K209','3','제단의 불로 내 죄를 불태워 주소서<br/>주 영을 나의 마음에 충-만케 하소서 충-만케 하소서<br/>',NULL,30015,3);
INSERT INTO stanza VALUES('K209','4','연단케 하는 불 받아 옛 창조 태우리<br/>생명을 뿌려 내 전체 거-룩게 하소서 거-룩게 하소서<br/>',NULL,30016,4);
INSERT INTO stanza VALUES('K209','5','요동하는 내 마음을 견고케 하소서<br/>주 나의 세계 되도록 사-랑 채우소서 사-랑 채우소서<br/>',NULL,30017,5);
INSERT INTO stanza VALUES('K21','1','아버지 지혜와 은혜 아들 안에 있네<br/>그리스도 내 지 - 혜 - 돼 나 은혜 받았 - 네<br/>그리스도 내 지 - 혜 - 돼 나 은혜 받 - 았네<br/>',NULL,30018,1);
INSERT INTO stanza VALUES('K21','2','아버지 계획 모두가 예수께 있다네<br/>이 지혜 안에 아 - 버 - 지 풍성을 누리 - 네<br/>이 지혜 안에 아 - 버 - 지 풍성을 누 - 리네<br/>',NULL,30019,2);
INSERT INTO stanza VALUES('K21','3','공의의 주 예수 인해 우리도 의롭네<br/>거룩함이신 주 - 인 - 해 우리도 거룩 - 해<br/>거룩함이신 주 - 인 - 해 우리도 거 - 룩해<br/>',NULL,30020,3);
INSERT INTO stanza VALUES('K21','4','영원한 계획 따라서 내 구속 되신 주<br/>결국에 나의 몸 - 또 - 한 영광의 구속 되리<br/>결국에 나의 몸 - 또 - 한 영광의 구 - 속 돼<br/>',NULL,30021,4);
INSERT INTO stanza VALUES('K21','5','신성한 경륜 안에서 하나님 지혜 된<br/>주 인해 무릎 꿇 - 고 - 서 경배와 찬양 - 해<br/>주 인해 무릎 꿇 - 고 - 서 경배와 찬 - 양해<br/>',NULL,30022,5);
INSERT INTO stanza VALUES('K21','6','당신의 지혜 주 안에 깊고도 풍성해<br/>내 안에 더욱 깊 - 고 - 도 풍성케 되겠 - 네<br/>내 안에 더욱 깊 - 고 - 도 풍성케 되 - 겠네<br/>',NULL,30023,6);
INSERT INTO stanza VALUES('K210','1','주여 내게 성령 부어 마시게 가르치며<br/>주의 품에 죄와 자아 쏟게 도와 주소서<br/>',NULL,30024,1);
INSERT INTO stanza VALUES('K210','chorus','나의 슬픔 뿜어 내고 죄악 내쉬고<br/>나는 깊이 들이마셔 주의 풍성을<br/>',NULL,30025,2);
INSERT INTO stanza VALUES('K210','2','자아 생명 뿜어내야 당신으로 충만돼<br/>나의 약함 거절하고 주의 은혜 마시리<br/>',NULL,30026,3);
INSERT INTO stanza VALUES('K210','3','죄의 법의 고통 내쉬어 주가 날 구했으니<br/>주의 성결 풍성 마셔 생명의 주 알았네<br/>',NULL,30027,4);
INSERT INTO stanza VALUES('K210','4','사랑하는 당신 품에 나의 근심 내쉬고<br/>주의 기쁨 위로 평강 안에 들이마시네<br/>',NULL,30028,5);
INSERT INTO stanza VALUES('K210','5','주 내 질병 담당하고 평강 주시었으니<br/>나의 질병 뿜어내고 주의 치료 마시네<br/>',NULL,30029,6);
INSERT INTO stanza VALUES('K210','6','주의 사랑하는 귀에 내 사모함 내쉬며<br/>주의 응답 마시오니 의심 두려움 없네<br/>',NULL,30030,7);
INSERT INTO stanza VALUES('K210','7','순간 순간 주님 자신 생명으로 호흡해<br/>내어 쉬고 들이마셔 주 날 통해 나타나<br/>',NULL,30031,8);
INSERT INTO stanza VALUES('K211','1','생명의 주여 불어와 주의 샘 내-게 여소서<br/>내 속에서 날 살리며 생명의 빛 비추소서<br/>',NULL,30032,1);
INSERT INTO stanza VALUES('K211','2','주님 내 안에 계시니 하늘서 찾-지 않겠네<br/>영 안에 돌아갈 때에 주 직접 만나게 되네<br/>',NULL,30033,2);
INSERT INTO stanza VALUES('K211','3','하늘에 계신 내 중보 내 영 안에- 기름 부음<br/>주 날 위하여 이룬 것 영 안에서 다 만지네<br/>',NULL,30034,3);
INSERT INTO stanza VALUES('K211','4','내 맘은 감동받아도 여전히 순-종 않으니<br/>내 온 존재 움직이게 주 생기 넣어 주소서<br/>',NULL,30035,4);
INSERT INTO stanza VALUES('K211','5','내 영이 침체되어서 주 은혜 표-현 못할 때<br/>내 속에 생기 넣으사 주 충만하게 하소서<br/>',NULL,30036,5);
INSERT INTO stanza VALUES('K212','1','성령의 바람 하늘로부터 오순절 같이 불어-와<br/>나를 살리고 강퍅한 맘과 죄악 벗어나게 하시네<br/>',NULL,30037,1);
INSERT INTO stanza VALUES('K212','chorus','불어오네 성령의 큰 바람 덮고 감싸 은혜의 구름이<br/>불사르네 거룩한 그 불로 정금 영광 나타나도록<br/>',NULL,30038,2);
INSERT INTO stanza VALUES('K212','2','은혜의 구름 충만히 내려 장막 치듯이 날 덮-어<br/>생명 주시고 거룩게 하여 하나님을 거하게 하네<br/>',NULL,30039,3);
INSERT INTO stanza VALUES('K212','3','거룩한 불이 나를 태우사 사악함 태워 정케-해<br/>천함 제하고 거룩게 하여 나를 주와 연합하게 해<br/>',NULL,30040,4);
INSERT INTO stanza VALUES('K212','4','빛나는 정금 내 맘 비추어 신의 성품에 참여케 해<br/>사람의 영과 주 영 연합해 주의 생명 표현케 하네<br/>',NULL,30041,5);
INSERT INTO stanza VALUES('K213','1','주여 하늘에 속한 바람 보내 주소서<br/>감동시켜 부흥케 할 큰 능력 주소서<br/>',NULL,30042,1);
INSERT INTO stanza VALUES('K213','chorus','큰 능력의 주 예수여 내게 임하소서<br/>성령의 바람 내게 불어 생수 넘치게<br/>',NULL,30043,2);
INSERT INTO stanza VALUES('K213','2','주 능력의 영 불어와 장애 제하소서<br/>주 생명의 영 내쉬니 난 사랑 마시네<br/>',NULL,30044,3);
INSERT INTO stanza VALUES('K213','3','주 예수의 영 이제는 칠 배의 영이니<br/>이 영 안에 나 참예해 주 예수 체험해<br/>',NULL,30045,4);
INSERT INTO stanza VALUES('K214','1','주여 기다리니 불게 하옵소서<br/>자유함 주시는 당신의 큰 바람 우리 모든 사람<br/>다 부흥되도록 오 주여 불게 하소서<br/>',NULL,30046,1);
INSERT INTO stanza VALUES('K214','chorus','오 주여 불게 하소서 게으름 몰아내도록<br/>큰 바람 임하여 내 침체 다 쫓게 오 주여 불게하소서<br/>',NULL,30047,2);
INSERT INTO stanza VALUES('K214','2','차가운 나의 맘 뜨겁게 타도록<br/>사랑의 공기를 내 맘에 부으사 우리 모든 사람<br/>뜨거워지도록 오 주여 불게 하소서<br/>',NULL,30048,3);
INSERT INTO stanza VALUES('K214','3','침체된 죽은 영 살리는 영이여<br/>오 지금 나에게 불어와 주소서 부활의 생명이<br/>충만케 되어서 약함과 실망 없도록<br/>',NULL,30049,4);
INSERT INTO stanza VALUES('K215','1','내 마음 속에 은혜의 주 아름다운 내 노래<br/>어떠한 노래 이와 같으랴 기묘한 기쁨의 맛<br/>',NULL,30050,1);
INSERT INTO stanza VALUES('K215','chorus','내 맘 속에 달고 아름다운 하늘 기쁜 찬송 찬송 부르네<br/>내 맘 속에 기묘한 사랑의 아름다운 노래해<br/>',NULL,30051,2);
INSERT INTO stanza VALUES('K215','2','기묘한 사랑 날 구했네 구원의 기쁨 넘쳐<br/>은혜의 주가 내 안에 살아 사랑의 찬미케 해<br/>',NULL,30052,3);
INSERT INTO stanza VALUES('K215','3','주 예수 나를 인도하니 어떠한 광명인가<br/>평강의 주가 내 안에 사셔 찬미로 전진케 해<br/>',NULL,30053,4);
INSERT INTO stanza VALUES('K215','4','성도들 승리 찬송하며 높이 들림 받겠네<br/>나 주와 같이 왕 노릇 하리 어떠한 영광인가<br/>',NULL,30054,5);
INSERT INTO stanza VALUES('K215','5','새 예루살렘 들어가서 생명 강물 마시리<br/>생명의 열매 먹는 배부름 어떠한 풍성인가<br/>',NULL,30055,6);
INSERT INTO stanza VALUES('K216','1','속죄 피가 뿌려진데 귀한 관-유 발라져-<br/>이로 인해 사람들이 하나님-과 교통해<br/>',NULL,30056,1);
INSERT INTO stanza VALUES('K216','2','피는 구속 대가로써 모든 죄-악 씻었네-<br/>영의 표징 관유로써 하나님-이 더해져<br/>',NULL,30057,2);
INSERT INTO stanza VALUES('K216','3','주의 역사 주님 자신 이는 바-로 피와 관유<br/>이로 인해 하나님과 사람들-이 연합돼<br/>',NULL,30058,3);
INSERT INTO stanza VALUES('K216','4','주의 피의 씻음 통해 모든 죄-를 벗어나-<br/>영의 역사 바름 통해 하나님-을 얻었네<br/>',NULL,30059,4);
INSERT INTO stanza VALUES('K216','5','씻음 통해 바름 통해 하나님-과 하나 돼-<br/>피와 관유 통하여서 하나님-을 누리네<br/>',NULL,30060,5);
INSERT INTO stanza VALUES('K216','6','주의 보혈 필요할 때 믿음으-로 씻음 구해<br/>기름 부음 순종하여 영영 주-와 동행해<br/>',NULL,30061,6);
INSERT INTO stanza VALUES('K216','7','피와 관유 체험하여 빛과 사-랑 누리네-<br/>주를 누려 간격 없이 하나님-과 하나 돼<br/>',NULL,30062,7);
INSERT INTO stanza VALUES('K217','1','오 놀라운 영광 축복 진리의 영 내 맘에<br/>구주 예수 증거하며 진리 계시해 주네<br/>',NULL,30063,1);
INSERT INTO stanza VALUES('K217','chorus','충만히 충만히 나를 채워 주소서<br/>날 비우고 사로잡아 충만하게 하소서<br/>',NULL,30064,2);
INSERT INTO stanza VALUES('K217','2','주의 말씀 내 안에서 확증하여 주시며<br/>생명의 영 날 해방해 죄와 사망 권세서<br/>',NULL,30065,3);
INSERT INTO stanza VALUES('K217','3','사슴처럼 갈급할 때 내 목마름 해결해<br/>충만함을 맛볼 때에 생수 강이 흐르네<br/>',NULL,30066,4);
INSERT INTO stanza VALUES('K217','4','죽음 속에 던지워도 주의 성령 채우리<br/>주 내 전체 다스리어 영광으로 화하리<br/>',NULL,30067,5);
INSERT INTO stanza VALUES('K218','1','찬양하세! 귀한 구주 그 사랑 날 잡았네<br/>구원하고 죄를 씻어 주의 통로 되게해<br/>',NULL,30068,1);
INSERT INTO stanza VALUES('K218','chorus','축복의 주 통로 됐네 놀라운 주 은혜로<br/>우릴 통해 흐르면서 항상 사용하소서<br/>',NULL,30069,2);
INSERT INTO stanza VALUES('K218','2','나는 다만 주의 통로 갈급한 자들에게<br/>주의 구원 주의 말씀 소리 높여 전하리<br/>',NULL,30070,3);
INSERT INTO stanza VALUES('K218','3','주님 자신 채우시려 깨끗게 한 이 그릇<br/>힘 없으나 순종하며 항상 은혜 받겠네<br/>',NULL,30071,4);
INSERT INTO stanza VALUES('K218','4','죄와 자아 벗게 하는 주의 은혜 말하리<br/>나를 사서 소유하신 주여 충만하소서<br/>',NULL,30072,5);
INSERT INTO stanza VALUES('K218','5','주여 이제 당신의 영 나를 충만하소서<br/>생수 넘쳐 흐르도록 주께 순복합니다<br/>',NULL,30073,6);
INSERT INTO stanza VALUES('K219','1','주를 구함 부족하여 이런 갈증 있으니<br/>나의 갈증 푸실 주를 더욱 사모합니다<br/>',NULL,30074,1);
INSERT INTO stanza VALUES('K219','chorus','나 지금 구하니 성령 충만 주소서<br/>',NULL,30075,2);
INSERT INTO stanza VALUES('K219','2','열매 없고 주님 없고 찬미 없는 모든 것<br/>행위 간증 모든 일들 실패임을 압니다<br/>',NULL,30076,3);
INSERT INTO stanza VALUES('K219','3','주께 나의 모든 실패 약함 시인합니다<br/>강퍅함과 감췬 악과 자만 시인합니다<br/>',NULL,30077,4);
INSERT INTO stanza VALUES('K219','4','주여 나를 자아에서 구원하여 주시고<br/>주와 함께 못 박힌 것 알게 하여 주소서<br/>',NULL,30078,5);
INSERT INTO stanza VALUES('K219','5','모든 생각 일과 말에 내가 살지 않도록<br/>항상 주가 생활하셔 나를 통과하소서<br/>',NULL,30079,6);
INSERT INTO stanza VALUES('K219','6','주의 성령 나의 안팎 항상 통과하시어<br/>나로 주의 간증 영광 되게 하여 주소서<br/>',NULL,30080,7);
INSERT INTO stanza VALUES('K219','7','주의 이름 안의 기도 이미 응답됐으니<br/>주의 말씀 인해 다만 믿고 안식합니다<br/>',NULL,30081,8);
INSERT INTO stanza VALUES('K219','chorus','기도를 들으신 주를 찬양합니다<br/>',NULL,30082,9);
INSERT INTO stanza VALUES('K22','1','높고 깊은 아버지의 긍휼 찬양하겠네<br/>나의 약함 실패 위에 항상 긍휼 더하네<br/>경배하고 경배하세 주의 긍휼 날 높이네 -<br/>주의 긍휼 날 높여<br/>',NULL,30083,1);
INSERT INTO stanza VALUES('K22','2','자신 낮춘 변함없는 긍휼 정말 놀라워<br/>죄인 내게 임한 긍휼 항상 계속되겠네<br/>그 무엇도 이 긍휼을 잃게 하지 못하리라 -<br/>주의 긍휼 영원해<br/>',NULL,30084,2);
INSERT INTO stanza VALUES('K22','3','풍성하고 풍족하네 아버지의 큰 긍휼<br/>구속 인해 날 돌보니 부족함이 없도다<br/>무엇으로 이 큰 사랑 받게 할 수 있으리요 -<br/>주의 긍휼 풍성해<br/>',NULL,30085,3);
INSERT INTO stanza VALUES('K22','4','부드럽고 달콤하네 사랑스런 이 긍휼<br/>주의 은혜 인내로써 나의 필요 채우네<br/>귀하고도 귀한 긍휼 우리에게 완전하네 -<br/>주의 긍휼 완전해<br/>',NULL,30086,4);
INSERT INTO stanza VALUES('K22','5','긍휼 누려 영원토록 낡지 않고 새롭네<br/>적셔지는 이슬처럼 매일 아침 임하네<br/>이 얼마나 달콤한가 주의 긍휼 찬양하세 -<br/>주의 긍휼 찬양해<br/>',NULL,30087,5);
INSERT INTO stanza VALUES('K22','6','주의 긍휼 영원하니 찬양 그칠 수 없어<br/>주 은혜와 돌보심 날 영원토록 지키네<br/>신실하신 주의 긍휼 날 부끄럽지 않게 해 -<br/>주의 긍휼 신실해<br/>',NULL,30088,6);
INSERT INTO stanza VALUES('K220','1','영 안에-서 성령으-로 하나님의 아-들 돼<br/>내 영 안-에 보증되-신 주의 성-령 얻었네<br/>주의 풍성 누리도-록 주여- 성령 더- 주사<br/>성령으-로 충만케- 해 날 풍성-케 하소서<br/>',NULL,30089,1);
INSERT INTO stanza VALUES('K220','2','내 영 안-에 계신 성-령 주의 생명 영-이니<br/>나를 주-의 풍성 안-에 참예하-게 하시네<br/>위로부터 임하시-는 능력-의 영 더-하사<br/>주의 일-을 하게 하-고 주 섬기-게 하소서<br/>',NULL,30090,2);
INSERT INTO stanza VALUES('K220','3','주여 나-로 성령 침-례 체험하게 하-소서<br/>주 능력-의 겉옷 입-고 원수 공-격하도록<br/>주의 크신 바람 불-어 혀의-불 같은- 것 줘<br/>주의 기-름 부음 받-은 증인 되-게 하소서<br/>',NULL,30091,3);
INSERT INTO stanza VALUES('K220','4','성령 능-력 얻었어-도 주의 은사 필-요해<br/>나로 지-체 기능 다-해 주 섬기-게 하소서<br/>주의 영의 충만하-신 옮겨-부음 통-하여<br/>내게 은-사 나눠주-사 몸을 건-축하소서<br/>',NULL,30092,4);
INSERT INTO stanza VALUES('K220','5','주의 영-광 왕국 위 - 해 부르짖음 들-으사<br/>거룩하-신 뜻 이루-고 내 필요-채우소서<br/>주의 영에 참예하-여 그를- 적용할- 때에<br/>안의 충-만 밖의 능-력 은사로- 다 누리리<br/>',NULL,30093,5);
INSERT INTO stanza VALUES('K221','1','주가 사람으로 날 때 성령으로 잉태돼-<br/>사역 시작하기 전에 성령 또 충만했네<br/>그가 사역 시작할 때 거룩한 직분 위해-<br/>성령 침례 받으시고 위의 능력 입었네<br/>',NULL,30094,1);
INSERT INTO stanza VALUES('K221','2','베드로와 모든 제자 모두 영으로 났네-<br/>주가 숨을 내쉬실 때 성령 들이마셨네<br/>후에 모든 제자 또한 성령 침례 받았네-<br/>능력 입고 장비돼야 직분 다할 수 있네<br/>',NULL,30095,2);
INSERT INTO stanza VALUES('K221','3','바울과 에베소인들 사마리아 신자들-<br/>모두 성령으로 나서 내주하는 영 있네<br/>모두 안수받은 후에 성령 침례 받았네-<br/>성령 능력 입은 후에 주를 증거하였네<br/>',NULL,30096,3);
INSERT INTO stanza VALUES('K221','4','우리 또한 믿을 때에 성령으로 거듭나-<br/>지금 그 영 마시면서 주의 풍성 누리네<br/>또한 우리들은 더욱 성령 침례 받고서-<br/>위의 능력 입어야만 직분 다할 수 있네<br/>',NULL,30097,4);
INSERT INTO stanza VALUES('K221','5','주여 나로 성령 침례 체험하게 하소서-<br/>교회 건축 위해 내게 능력의 영 주소서<br/>주여 지금 나 이렇게 간절히 구하오니-<br/>위의 능력 내게 부어 투명하게 하소서<br/>',NULL,30098,5);
INSERT INTO stanza VALUES('K222','1','주의 말씀이 이미 계시한 복된 사실 내게 있으니<br/>성령 안에 난 침례 받았네 주의 사실 받아들이리<br/>받아 들여 더 이상 지체말고서<br/>받아 들여 믿음으로 사실 받으라<br/>2- 신약의 말씀 밝히 말했네 나는 성령 침례 받았네<br/>',NULL,30099,1);
INSERT INTO stanza VALUES('K222','2','신약의 말씀 밝히 말했네 나는 성령 침례 받았네<br/>붙잡으라 이미 이루어진 이 사실<br/>붙잡으라 믿음으로 사실 붙잡아<br/>',NULL,30100,2);
INSERT INTO stanza VALUES('K222','3','주가 교회에 성령 부었네 나는 성령 침례 받았네<br/>풍성한 축복 함께 나누리 나는 이미 침례 받았네<br/>함께 나눠 이미 얻은 은사 나누세<br/>함께 나눠 믿음으로 사실 나누세<br/>',NULL,30101,3);
INSERT INTO stanza VALUES('K222','4','주의 몸 안의 사실 따라서 몸과 함께 행동하겠네<br/>모든 죄악을 자백하면서 모든 의심 거절하겠네<br/>행동하라 믿음으로 주의 몸 안에<br/>행동하라 주의 사실따라 행동해<br/>',NULL,30102,4);
INSERT INTO stanza VALUES('K223','1','주께 나아가 간구하오니 주의 능력을 부으소서<br/>주의 왕국과 능력 임하여 주의 원수 공격하도록<br/>능력 능력 내게 입히소서 위로부터 오는 큰 능력<br/>능력 능력 내게 입히소서 주의 몸이 간구합니다-<br/>',NULL,30103,1);
INSERT INTO stanza VALUES('K223','2','주를 앙망해 간구하오니 주의 단 비를 내리소서<br/>주의 사역과 필요 위하여 주의 몸에 공급하소서<br/>단비 단비 내게 부으소서 하늘로서 오는 단 비를<br/>단비 단비 내게 부으소서 주의 몸에 내려 주소서<br/>',NULL,30104,2);
INSERT INTO stanza VALUES('K223','3','주를 기다려 간구하오니 거룩한 불을 주소-서<br/>복음 위하여 나를 태우사 사람들을 인도하도록<br/>불로 불로 나를 태우소서 사랑으로 불사르소서<br/>불로 불로 나를 태우소서 주의 몸이 간구합니다<br/>',NULL,30105,3);
INSERT INTO stanza VALUES('K224','1','구주 예수 높이 올라 하늘 위에 앉았네<br/>아버지의 우편에서 영광 존귀- 관 썼네<br/>만유 머리 되신 주님 가장 높이 되셨네<br/>',NULL,30106,1);
INSERT INTO stanza VALUES('K224','2','올리우신 주로부터 성령 옮겨 부어져<br/>몸의 모든 지체에게 성령 입혀- 주셨네<br/>교회 인해 만유의 주 경배 받으시도록<br/>',NULL,30107,2);
INSERT INTO stanza VALUES('K224','3','하나님을 이끌어 온 육신 되신 주 예수<br/>또한 죽음 부활 통해 사람 이끌-어 갔네<br/>하나님과 사람 연합 주 안에 이뤄졌네<br/>',NULL,30108,3);
INSERT INTO stanza VALUES('K224','4','이제 주는 높은 하늘 영광 보좌에 앉아<br/>만주의 주 만왕의 왕 모든 권위- 얻었네<br/>그가 성령 내리시어 이를 확증하셨네<br/>',NULL,30109,4);
INSERT INTO stanza VALUES('K224','5','그의 영을 옮겨 부어 교회에 강림한 주<br/>성령 안에 온 교회에 이미 침례- 주셨네<br/>다 완성된 침례 안에 모든 신자 참예해<br/>',NULL,30110,5);
INSERT INTO stanza VALUES('K224','6','할렐루야 영 단번에 이미 완성되었네<br/>크고 작은 믿는 이들 모두 침례- 받았네<br/>주가 모든 지체에게 성령 침례 주셨네<br/>',NULL,30111,6);
INSERT INTO stanza VALUES('K225','1','주님의 능력 구합니다 나에게 능력 입히소서<br/>나 오랫동안 연약하니 주 능력 주소서<br/>',NULL,30112,1);
INSERT INTO stanza VALUES('K225','chorus','겸손하게 주께 엎드려<br/>간절하게 부르짖으니<br/>나에게 능력 주옵소서 능력 입히소서<br/>',NULL,30113,2);
INSERT INTO stanza VALUES('K225','2','돌아보시고 은혜 주사 교회에 은사 주옵소서<br/>다시는 기운 잃지 않게 능력을 주소서<br/>',NULL,30114,3);
INSERT INTO stanza VALUES('K225','3','오순절날에 행하셨듯 권세의 능력 입히소서<br/>더 기다리게 하지 말고 응답해 주소서<br/>',NULL,30115,4);
INSERT INTO stanza VALUES('K225','4','주 예수 이름 의지하여 믿음으로써 간구하니<br/>성령의 불을 내리소서 성령비 주소서<br/>',NULL,30116,5);
INSERT INTO stanza VALUES('K226','1','생명의 영 내 안에 들어 오셔<br/>생수의 샘 되어서 갈증 푸네<br/>난 이 영을 마시어- 충만되어<br/>큰 강처-럼- 영원히 넘치겠네<br/>',NULL,30117,1);
INSERT INTO stanza VALUES('K226','2','능력의 영 내 위에 임하여서<br/>겉옷처럼 나의 힘 되셨으니<br/>그 안에서 침례로- 옷 입은 후<br/>나 주의- 일- 위하여 장비되네<br/>',NULL,30118,2);
INSERT INTO stanza VALUES('K226','3','생명의 영 생명의 실재 되어<br/>공기처럼 내 안에 호흡 되네<br/>능력의 영 불어와- 바람처럼<br/>저 위로-서- 불어와 날 움직여<br/>',NULL,30119,3);
INSERT INTO stanza VALUES('K226','4','부활한 주 그의 숨 내쉼으로<br/>그 제자들 안으로 생명 넣고<br/>승천한 주 오순절- 능력의 영<br/>큰 바람-이- 되어서 불어왔네<br/>',NULL,30120,4);
INSERT INTO stanza VALUES('K226','5','생명의 영 내 안에 생명 되고<br/>능력의 영 이 생명 위해 있네<br/>오 불어온 바람이- 공기 주어<br/>날 호흡-게- 함으로 생명 주네<br/>',NULL,30121,5);
INSERT INTO stanza VALUES('K226','6','내 안에는 하나님 충만하고<br/>내 밖에는 하나님 옷 입으니<br/>하나님과 영원히- 연합되어<br/>한 성령-의- 두 기능 누린다네<br/>',NULL,30122,6);
INSERT INTO stanza VALUES('K226','7','생명의 영 내 속을 충만케 해<br/>내 생명을 자라게 하옵소서<br/>능력의 영 내 밖에- 입혀주사<br/>주 당신-의- 사명을 이루도록<br/>',NULL,30123,7);
INSERT INTO stanza VALUES('K227','1','먼-저 피-로 씻고서 관유로- 적셔지네<br/>골고다 가-지 않으면 오순절-을 못 얻어<br/>우리 씻-지 않-으면 능력 임-할 수- 없네<br/>주-의 간-증 되려면 자아 못- 박혀야 해<br/>',NULL,30124,1);
INSERT INTO stanza VALUES('K227','chorus','십자가로 내 혼 생명 처리하여 주소서<br/>나로 대가 지불하여 성령 충만하도록<br/>',NULL,30125,2);
INSERT INTO stanza VALUES('K227','2','먼-저 반-석 깨져야 생수 넘-쳐 흐르네<br/>먼-저 죽-음 거쳐야 성령 충-만 얻으리<br/>우리 진-정 주-님과 함께 죽-고 잃-을 때<br/>주-의 능-력 강림해 세상 구-원하리라<br/>',NULL,30126,3);
INSERT INTO stanza VALUES('K227','3','제-단 후-에 불이요 잃은 후-에 열매니<br/>모-두 드-린 후에야 보좌 위-에 오르리<br/>우리 진-정 희-생해 주께 순-복할- 때에<br/>필-경 얻-게 되리라 주가 주-는 능력을<br/>',NULL,30127,4);
INSERT INTO stanza VALUES('K227','4','먼-저 빈-병 있어야 안에 기-름 부어져<br/>먼-저 계-곡 파져야 생수 깊-이 흐르리<br/>먼저 요-단 건-너야 영의 느-낌 많-아져<br/>먼-저 침-례 거쳐야 영광 비둘기 임하리<br/>',NULL,30128,5);
INSERT INTO stanza VALUES('K227','5','황-금 들-판 볼 때에 우리 기-뻐하지만<br/>먼-저 밀-알 죽어야 많은 열-매 얻는다<br/>생명의- 밀 위-하여 죽음 체-험 필-요해<br/>갈-보리-를 피하면 생명 능-력 없다네<br/>',NULL,30129,6);
INSERT INTO stanza VALUES('K227','6','주-여 나-로 신실히 좁은 길-을 가게 해<br/>야-심 제-해 순종해 고통 받-게 하소서<br/>더 큰 능-력 보-다도 깊은 죽-음 필-요해<br/>갈-보리-의 참 뜻이 내 게 이-뤄지도록<br/>',NULL,30130,7);
INSERT INTO stanza VALUES('K228','1','보혈로 날 씻으사 죄과를 다 씻고<br/>주 거룩한 그 관유 내게 바르소서<br/>생활의 모든 실패 약함 시인하고<br/>주 영으로 충만해 주 위해 살겠네<br/>',NULL,30131,1);
INSERT INTO stanza VALUES('K228','chorus','오 주여 내 자신을 구원해 주옵소서<br/>이제부터 주로만 충만케 하소서<br/>',NULL,30132,2);
INSERT INTO stanza VALUES('K228','2','메마른 내 맘 항상 약하여 탄식해<br/>성령의 충만 받길 진정 사모하네<br/>주여 날 상처받은 반석에 감추사<br/>생수를 갈망하는 간구 들으소서<br/>',NULL,30133,3);
INSERT INTO stanza VALUES('K228','3','내 마음 냉담하고 순종함 느리니<br/>다시 주 거역 않게 성령 부으소서<br/>오늘 나 제단 위에 자신을 드리니<br/>하늘의 불 내리사 다 태워 주소서<br/>',NULL,30134,4);
INSERT INTO stanza VALUES('K228','4','내 몸에 주 십자가 더 깊이 역사해<br/>날 티끌 되게 하여 날 넓혀 주소서<br/>매일 더 성령으로 충만케 하소서<br/>주 생수 넘쳐 흘러 온 땅에 흐르게<br/>',NULL,30135,5);
INSERT INTO stanza VALUES('K229','1','땅의 일 다 변하여 하늘에 속했네<br/>주 찬미하세 은혜 받고 생명과 평안 누려<br/>주 안에 있네 주 찬미해<br/>',NULL,30136,1);
INSERT INTO stanza VALUES('K23','1','아버지 긍휼 이미 우리에게 나타내셔<br/>당신의 계시 따라 이 죄인이 아들 되었네<br/>날 예비했네 긍휼의 그릇으로 영원히<br/>당신 위해 간증하겠네<br/>',NULL,30137,1);
INSERT INTO stanza VALUES('K23','2','제사를 원치 않고 긍휼 원한 주 하나님<br/>이 긍휼 인해 우린 은사 얻고 영광 얻었네<br/>원하는 자로 말미암지 않 - 고<br/>긍휼히 여기시는 주 말미암네<br/>',NULL,30138,2);
INSERT INTO stanza VALUES('K23','3','난 이미 아버지의 긍휼 은혜 사랑 맛봐<br/>긍휼엔 주의 임재 주 얼굴빛 담기어 있네<br/>주 긍휼 인해 당신께 경배하네<br/>주 긍휼 인해 영영 찬송하겠네<br/>',NULL,30139,3);
INSERT INTO stanza VALUES('K230','1','하나님 세상을 사랑하심<br/>성경에 분명히 기록됐네<br/>놀랍고 달콤한 그 말씀은<br/>주 예수 날 사랑 하심일세<br/>',NULL,30140,1);
INSERT INTO stanza VALUES('K230','chorus','주님 날 사랑하셨으니<br/>나는 정말 기쁘도다<br/>주님 날 사랑하셨으니 나는 참기쁘다<br/>',NULL,30141,2);
INSERT INTO stanza VALUES('K230','2','나는 주 떠나서 방랑해도<br/>주 나를 여전히 사랑했네<br/>날 찾을 때까지 찾으시고<br/>주께로 돌이켜 데려왔네<br/>',NULL,30142,3);
INSERT INTO stanza VALUES('K230','3','주님 날 사랑해 날 구하려<br/>내 죄를 위하여 죽으셨네<br/>주 예수 날 사랑하심 믿고<br/>나 또한 주 예수 사랑하리<br/>',NULL,30143,4);
INSERT INTO stanza VALUES('K230','4','이 사랑 기묘함 확신하나<br/>말로는 다 표현 못하겠네<br/>영 안에 성령을 인치시고<br/>주 사랑 늘 내게 확증하네<br/>',NULL,30144,5);
INSERT INTO stanza VALUES('K230','5','이 증거있으니 안식하네<br/>주 말씀있으니 의심 없네<br/>주께서 날 사랑하심 듣고<br/>사탄은 저 멀리 도망갔네<br/>',NULL,30145,6);
INSERT INTO stanza VALUES('K230','6','영광에 들어가 내 왕 뵐 때<br/>영원히 영원히 부를 찬송<br/>“참으로 놀랍고 기묘한 일<br/>주 예수 날 사랑하심일세”<br/>',NULL,30146,7);
INSERT INTO stanza VALUES('K231','1','신선하고 달콤한 주 사랑 찬양해<br/>나 위해 죽으시고 내 맘에 거하네<br/>내게 생명 평강 주며 끝없이 돌보시네<br/>주 사랑 날로 날로 새롭고 달콤해<br/>날로 더욱 달콤해- 날로 더욱 달콤해<br/>나는 그침없이 찬송 찬양하리<br/>달콤한 주의 사랑<br/>',NULL,30147,1);
INSERT INTO stanza VALUES('K231','2','길고도 넓고 깊고 또 높은 주 사랑<br/>그 누구보다 더욱 친근한 나의 주<br/>깊은 사랑으로 대해 서로의 맘에 인쳐<br/>주 사랑 날로 날로 깊고도 풍성해<br/>날로 더욱 깊어져-날로 더욱 깊어져<br/>나는 그침없이 찬송 찬양하리<br/>넓고 깊은 그 사랑<br/>',NULL,30148,2);
INSERT INTO stanza VALUES('K231','3','온유하고도 강한 주 사랑 찬양해<br/>그 무엇보다 더욱 강한 주의 사랑<br/>온- 천지 변하여도 저 바다 사라져도<br/>주 사랑 소멸찮네 영원히 변찮네<br/>날이 가도 변찮네- 해가 가고 변찮네<br/>나는 그침없이 찬송 찬양하리<br/>변치 않는 주 사랑<br/>',NULL,30149,3);
INSERT INTO stanza VALUES('K232','1','날 사랑한 주 사랑 은혜로 난 알았네<br/>이를 내게 알리려 성령 불어오시네<br/>충만한 평강이여 신성한 기쁨이여<br/>나는 주께 속하고 주는 내게 속하네<br/>',NULL,30150,1);
INSERT INTO stanza VALUES('K232','2','주 없을 땐 못 보던 아름다운 경치여<br/>푸르른 저 하늘과 푸르른 저 땅이여<br/>새의 노래 고운 꽃 날 더 기쁘게 하네<br/>내가 주와 하나 됨 깨달은 그날부터<br/>내가 주와 하나 됨 깨달은 그날부터<br/>',NULL,30151,2);
INSERT INTO stanza VALUES('K232','3','많은 일들 있어도 내 안식 못 뺏으리<br/>주의 팔을 베고서 주의 품에 안기네<br/>주 품에서 영원히 근심 벗고 들으리<br/>부드러운 주 음성“너는 나의 것이라”<br/>부드러운 주 음성“너는 나의 것이라”<br/>',NULL,30152,3);
INSERT INTO stanza VALUES('K232','4','영원히 주께 속한 나를 누가 나누랴<br/>주 내 맘에 거하니 축복 안식 충만해<br/>천지는 없어져도 주와 나는 하날세<br/>나는 주께 속하고 주는 내게 속하네<br/>나는 주께 속하고 주는 내게 속하네<br/>',NULL,30153,4);
INSERT INTO stanza VALUES('K233','1','주는 내 죄를 등 뒤에 던지고 기억지 않네<br/>내 죄를 발로 짓밟고 다시 또 살피지 않네<br/>',NULL,30154,1);
INSERT INTO stanza VALUES('K233','chorus','내 범한 죄 사면함이 구름 사라짐 같게 해<br/>주 내 죄 모두 도말하심이 구름 다 소멸됨 같아<br/>',NULL,30155,2);
INSERT INTO stanza VALUES('K233','2','주는 내 죄를 돌같이 깊은 바다에 던졌네<br/>내 죄를 동이 서에서 멀듯 떠나게 하셨네<br/>',NULL,30156,3);
INSERT INTO stanza VALUES('K234','1','구주의 피로 이-루-신 그 큰- 구-원 놀라운 사랑<br/>죄는 내가 범하였으나 죽임은 주께서 당하셨네<br/>내 주님 내 하나님이 죽임당했네<br/>나 위-하여 내- 대신 죽임당했네<br/>내 하나님 그 큰 사랑! 날 위하여 죽임당했네<br/>',NULL,30157,1);
INSERT INTO stanza VALUES('K234','2','죽지 않는 자 죽임당하신 이 큰- 비-밀 그 누가 알리<br/>높고도 깊고 길고 넓은 거룩한 이 사랑 측량 못해<br/>모든 것 긍휼로 이 -뤄-졌으니<br/>천사-들아 다- 와서 경배하여라<br/>이 모든 것 긍휼이니 모든 천사 경배하여라<br/>',NULL,30158,2);
INSERT INTO stanza VALUES('K234','3','하늘 보좌를 떠-나-서 이 땅-에- 크-신 은혜<br/>소망 없는- 아담 족속 구하-려 친-히 오셨네<br/>자기 몸 버려- 피- 흘려 죄 사해<br/>이 모-두가 긍-휼과 은-혜일세<br/>이 큰 긍휼 한량 없어 죄인 괴수 내게 임했네<br/>',NULL,30159,3);
INSERT INTO stanza VALUES('K234','4','어두운 본성 악 -한 내 맘 죄 안-에 - 갇힌 나-의 영<br/>주께서 돌 -아보시니 은혜- 빛 비-춰 깨어나<br/>날 묶는 사슬- 벗-어-나-서<br/>내 전- -체 일-어나 주- 따르네<br/>내 온 존재 해방되어 주 따르니 참- 즐거워<br/>',NULL,30160,4);
INSERT INTO stanza VALUES('K234','5','왜 근심하나 정 -죄 없네 주와- 만-유 내- 소유니<br/>머리인 주 안에 살때에 그의-의 나-를 덮겠네<br/>은혜의 보좌- 앞-에- 가-니<br/>주 나- -의 참- -된 면- -류관<br/>보좌 앞에 나올 때에 그리스도 내- 면류관<br/>',NULL,30161,5);
INSERT INTO stanza VALUES('K235','1','왜 근심하나 하나님 내 모든 죄를 예수께<br/>다 돌리셨는데 주 나를 위해 갚은 빚<br/>의-로운 분이 어이해 또 요구하시랴<br/>',NULL,30162,1);
INSERT INTO stanza VALUES('K235','2','완전한 구속 영원히 내 죄의 값을 지불해<br/>나 칭의 얻었네 오 놀라운신 그 은혜<br/>하-나님께서 어이해 또 분노하시랴<br/>',NULL,30163,2);
INSERT INTO stanza VALUES('K235','3','내 죄를 사한 주 예수 내 모든 죄 빚 은혜로<br/>다 청산하셨네 내 중보자가 갚은 빚<br/>하-나님께서 어이해 또 계산하시랴<br/>',NULL,30164,3);
INSERT INTO stanza VALUES('K235','4','구주의 모든 역사로 나 죄의 속박 벗어나<br/>참 안식하겠네 날 위해 주 피 흘렸네<br/>하-나님께서 어이해 또 정죄하시랴<br/>',NULL,30165,4);
INSERT INTO stanza VALUES('K236','1','다시는 정죄- 없겠네 얼마나- 놀라-운가<br/>네 죄지고 죽-은 예수 널 소생-케 했네<br/>',NULL,30166,1);
INSERT INTO stanza VALUES('K236','2','그 피 날 위해- 하늘서 영원토-록 말-하네<br/>보석과 같이- 성도들 매일 돌-보시네<br/>',NULL,30167,2);
INSERT INTO stanza VALUES('K236','3','“다시는 정죄- 없겠네”주 하나-님의- 말씀<br/>부활한 주님- 안에서 나 또한- 이기네<br/>',NULL,30168,3);
INSERT INTO stanza VALUES('K236','4','나의 왕 그리-스도만 주목하-고 앙-망해<br/>주님의 귀한- 뜻 따라 주 영화-롭게 해<br/>',NULL,30169,4);
INSERT INTO stanza VALUES('K237','1','그리스도는 나-의 의 아름다움 내 눈-부신 옷<br/>이 옷 입고- 보좌 앞에- 가 나는 기-뻐 찬양하리<br/>',NULL,30170,1);
INSERT INTO stanza VALUES('K237','2','주 구속 나를 해-방해 내 죄와 수치 두-려움서<br/>주 나를 의-롭다 하니- 난 담대하-게 나-아가<br/>',NULL,30171,2);
INSERT INTO stanza VALUES('K237','3','구속받은 모든- 성도 아브라함같이- 선포해<br/>죄인 구원-한 주 예수- 그 귀한 이-름 자-랑해<br/>',NULL,30172,3);
INSERT INTO stanza VALUES('K237','4','옛 창조 모두 사라져도 깨끗한 이 옷 영- -원해<br/>세월 가도- 변치 않는- 옷 그 영광- 늘 새-롭네<br/>',NULL,30173,4);
INSERT INTO stanza VALUES('K237','5','그 얼굴 친히 뵐 때까지 언제나 주를 자-랑하리<br/>내 아름다-움 놀라운- 옷 주는 나-의 영원한 의<br/>',NULL,30174,5);
INSERT INTO stanza VALUES('K238','1','내 모든 소망 기초는 내 의 되신 그리스도<br/>다른 이 의지하잖고 주 예수만을 의지해<br/>',NULL,30175,1);
INSERT INTO stanza VALUES('K238','chorus','굳건한 반석이시니 그 위에 내가 서리라<br/>그 위에 내가 서리라<br/>',NULL,30176,2);
INSERT INTO stanza VALUES('K238','2','구름이 주를 가려도 주 맘과 은혜 변찮네<br/>풍랑이 엄몰하여도 믿음의 닻을 던지리<br/>',NULL,30177,3);
INSERT INTO stanza VALUES('K238','3','미쁘신 보혈과 언약 그 안에 내가 있으니<br/>사방이 다 무너져도 주 여전히 날 지키리<br/>',NULL,30178,4);
INSERT INTO stanza VALUES('K238','4','주 오셔 나팔 울릴 때 나 주님 안에 나타나<br/>오직 주 예수 옷 입고 그 보좌 앞에 서리라<br/>그 위에 내가 서리라 그 위에 내가 서리라<br/>',NULL,30179,5);
INSERT INTO stanza VALUES('K239','1','내 대신 죄짐지신 흠 없는 어린 양<br/>내 대신 저주받고 날 해방하셨네<br/>하나님 나의 죄를 어린 양께 돌려-<br/>내 대신 고통 당해 죄 빚 갚게 했네<br/>',NULL,30180,1);
INSERT INTO stanza VALUES('K239','2','내 모든 질병 갖고 채찍 맞으신 주<br/>내 약함 짊어지니 난 치료받았네<br/>주 나의 질고 지니 난 건강 얻었네-<br/>주 나의 근심 제해 난 평강 누리네<br/>',NULL,30181,2);
INSERT INTO stanza VALUES('K239','3','의로운 나의 왕의 귀한 죽음으로<br/>하나님 만족하고 내 양심 씻었네<br/>이제 난 의지하네 내 능력 되신 예수<br/>주님의 생명 나를 강건케 하시네<br/>',NULL,30182,3);
INSERT INTO stanza VALUES('K239','4','내 맘 예수께 드려 주가 왕 노릇 해<br/>내 생명 내 주 되셔 내 맘에 거하리<br/>난 주의 형상 닮아 주 나타내기 원해<br/>내 태도 행동 통해 주만 나타내리<br/>',NULL,30183,4);
INSERT INTO stanza VALUES('K24','1','하나님의 그 크신 사랑 말로 다 형용 못하리<br/>해와 달과 별보다 높고 지옥보다 더 깊네<br/>벌레만도 못한 우리 - 위하여 독 - 생자<br/>아낌없이 보내주사 이 죄인 구하셨네<br/>',NULL,30184,1);
INSERT INTO stanza VALUES('K24','chorus','오 하나님의 크신 사랑 참말로 측량 못해<br/>천사들과 모든 성도여 영원히 찬양하세<br/>',NULL,30185,2);
INSERT INTO stanza VALUES('K24','2','인간 영화는 쇠패하고 천지가 없어질 때에<br/>그 큰 사랑 거절한 영혼 그 누가 구할 수 있나<br/>영원토록 변치 않는 - 그 크신 사 - 랑은<br/>우리 죄빚 다 갚았으니 성도여 찬양하세<br/>',NULL,30186,3);
INSERT INTO stanza VALUES('K24','3','바다의 물이 먹이 되고 하늘이 흰 종이 되며<br/>온 세상 사람 시인 되어 초목을 붓으로 삼아<br/>그 먹과 종이 다하도록 쓰고 또 쓴다 해도<br/>하나님의 그 크신 사랑 다 표현할 수 없네<br/>',NULL,30187,4);
INSERT INTO stanza VALUES('K240','1','하나님과 화-평한 맘이 어떠한 맘인가!<br/>피로 화목 이-룬- 죄인 놀라운 화평일세!<br/>',NULL,30188,1);
INSERT INTO stanza VALUES('K240','2','본성이나 실-행이나 하나님과 멀던 나<br/>이제 주의 피-를- 믿어 그와 가까워졌네<br/>',NULL,30189,2);
INSERT INTO stanza VALUES('K240','3','하나님과 가-까우니 가깝고도 가까워<br/>그의 아들 인-해- 나는 아들같이 가깝네<br/>',NULL,30190,3);
INSERT INTO stanza VALUES('K240','4','하나님께 귀-한 나는 귀하고도 귀하네<br/>그가 아들 사-랑-하듯 나를 사랑하시네<br/>',NULL,30191,4);
INSERT INTO stanza VALUES('K240','5','하나님의 소-유된 나 무슨 염려하리요<br/>밤낮 나를 돌-보-시며“넌 내 것이라”하네<br/>',NULL,30192,5);
INSERT INTO stanza VALUES('K241','1','주 예수 내 맘에 들어와 계신 후<br/>변하여 새 사람되고 내가 늘 바라던<br/>참 빛을 찾음도 주 예수 내 맘에 오심<br/>',NULL,30193,1);
INSERT INTO stanza VALUES('K241','chorus','주 예수 내 맘에 오심<br/>주 예수 내 맘에 오심<br/>물밀듯 내 맘에 기쁨이 넘침은<br/>주 예수 내 맘에 오심<br/>',NULL,30194,2);
INSERT INTO stanza VALUES('K241','2','주 예수 내 맘에 임하여 오신 후<br/>망령된 행실을 끊고 머리털보다도<br/>더 많던 내 죄가 눈보다 더 희어졌네<br/>',NULL,30195,3);
INSERT INTO stanza VALUES('K241','3','사망의 음침한 골짜기 가다가<br/>밝은 빛 홀연히 보고 어둠의 구름이<br/>사라져버림도 주 예수 내 맘에 오심<br/>',NULL,30196,4);
INSERT INTO stanza VALUES('K241','4','내 맘에 소망을 든든히 가짐은<br/>주 예수 내 맘에 오심 영광의 소망이<br/>환하게 보임도 주 예수 내 맘에 오심<br/>',NULL,30197,5);
INSERT INTO stanza VALUES('K242','1','기쁨 내 맘을 채우네 채우네<br/>돌같은 내 맘 부드러운 맘으로 바꾸네<br/>성령은 나를 새롭게 하시네<br/>기쁨 내 맘을 채우네 채우네<br/>',NULL,30198,1);
INSERT INTO stanza VALUES('K242','2','성령 내 맘을 채우네 채우네<br/>내 죄 사하고 내 모든 약함을 소멸하시네<br/>나 성결에 이르게 하신다네<br/>성령 내 맘을 채우네 채우네<br/>',NULL,30199,2);
INSERT INTO stanza VALUES('K243','1','나의 죄짐 모두 벗겨졌다네<br/>항상 고통 속에 짊어진 짐<br/>주의 말씀 듣고서 주를 영접한 순간<br/>나의 죄짐 다 벗겨졌다네<br/>',NULL,30200,1);
INSERT INTO stanza VALUES('K243','chorus','완전히 벗었네 난 참 기뻐 죄짐 벗겨졌으니<br/>완전히 벗었네 난 참 기뻐 죄짐 벗겨졌으니<br/>',NULL,30201,2);
INSERT INTO stanza VALUES('K243','2','나의 죄짐 모두 벗겨졌다네<br/>밤낮 죄짐 지고 두려웠네<br/>성령 지시 따라서 십자가 가까이해<br/>나의 죄짐 다 벗겨졌다네<br/>',NULL,30202,3);
INSERT INTO stanza VALUES('K243','3','나의 죄짐 모두 벗겨졌다네<br/>오랫동안 죄짐 날 묶었네<br/>은혜 보좌 앞에서 주의 영광 뵐 때에<br/>나의 죄짐 다 벗겨졌다네<br/>',NULL,30203,4);
INSERT INTO stanza VALUES('K243','4','지금 나는 기뻐 노래 부르네<br/>나의 죄짐 모두 벗겨졌네<br/>밤낮 감사 넘치며 찬송 그침 없다네<br/>이제 난 주를 위해 산다네<br/>',NULL,30204,5);
INSERT INTO stanza VALUES('K244','1','난 예수께 돌아와 해방됐네 주 오늘 내 맘에서 왕노릇해<br/>난 성령에 충만돼 찬양 넘쳐 주 예수 날 해방했네<br/>',NULL,30205,1);
INSERT INTO stanza VALUES('K244','chorus','오 영광의 해방일세 또 묶이지 않으리라-<br/>난 보혈로 씻어서 맑게 됐네 주 예수 날 해방했네<br/>',NULL,30206,2);
INSERT INTO stanza VALUES('K244','2','저 죄악과 정욕은 날 못 묶네 이 세상의 근심도 묶지 못해<br/>이 땅 위의 묶임 다 끊어졌네 주 예수 날 해방했네<br/>',NULL,30207,3);
INSERT INTO stanza VALUES('K244','3','주 날 위해 세상 벽 헐으셨네 주 날 위해 마귀를 타파했네<br/>은혜의 빛 그 영광 날 비추네 주 예수 날 해방했네<br/>',NULL,30208,4);
INSERT INTO stanza VALUES('K245','1','죄가 나의 주인 되어 나를 묶었네<br/>주가 죄의 노예들을 해방함 모르고<br/>몸부림치며 늘 탄식했네<br/>난 이제 주 은혜로 죄의 권세 벗었네<br/>생명의 산 샘 마셔 구원을 누리네<br/>오 할렐루야 풍성함과 달콤함 기쁨 넘쳐<br/>은혜 입은 나 주 찬송해<br/>',NULL,30209,1);
INSERT INTO stanza VALUES('K246','1','죄악의 사슬 날 묶었을 때<br/>발버둥쳐도 헛되었네<br/>주 예수 사슬 깨뜨리셨네<br/>놀라운 해방 난 받았네<br/>',NULL,30210,1);
INSERT INTO stanza VALUES('K246','chorus','영광의 해방 놀라운 해방<br/>주 예수 내 영광의 구주<br/>죄 사슬에서 해방됐으니<br/>나 이제 영영 고통 없네<br/>',NULL,30211,2);
INSERT INTO stanza VALUES('K246','2','육체와 정욕 사욕 벗어나<br/>질투와 미움 싸움 벗어<br/>세상과 허영 명예 벗어나<br/>헛된 모든 것 벗어났네<br/>',NULL,30212,3);
INSERT INTO stanza VALUES('K246','3','금전의 유혹 벗어 버리네<br/>강퍅한 자아 욕심 벗어<br/>율법의 형식 제한 벗어나<br/>놀라운 해방 참 기묘해<br/>',NULL,30213,4);
INSERT INTO stanza VALUES('K247','1','오 놀라-운 주의 은혜 나 구원- 얻었네<br/>길을- 잃-고 헤매-던- 나 생명 길- 찾았네<br/>',NULL,30214,1);
INSERT INTO stanza VALUES('K247','2','내 맘 깊-이 쌓인 근심 멀리 사-라지고<br/>처-음- 주-를 만난- 시-간 그 은혜- 귀하다<br/>',NULL,30215,2);
INSERT INTO stanza VALUES('K247','3','주 내 만-족 또 내 소망 주 날 지-키시니<br/>주 내- 방-패 또 내- 기-업 나의 끝-날까지<br/>',NULL,30216,3);
INSERT INTO stanza VALUES('K247','4','그의 날-에 주와 함께 태양 빛- 같으리<br/>찬송- 불-러 영원-토-록 주를 찬-양하리<br/>',NULL,30217,4);
INSERT INTO stanza VALUES('K248','1','죄 대신한 은혜 내 맘 속 다스려<br/>날 죄의 권능 벗게해 옛 성품 벗게 해<br/>',NULL,30218,1);
INSERT INTO stanza VALUES('K248','chorus','은혜 족하니 부족함 없네<br/>주 내 안에 사셔서 은혜 누리게 해<br/>',NULL,30219,2);
INSERT INTO stanza VALUES('K248','2','주 은혜 하늘 길 행하게 하시네<br/>때 따라 돕는 은혜가 늘 풍성하도다<br/>',NULL,30220,3);
INSERT INTO stanza VALUES('K248','3','주 예수 자신이 곧 은혜이시니<br/>성육신 했던 하나님 내 안에 계시네<br/>',NULL,30221,4);
INSERT INTO stanza VALUES('K248','chorus','주의 은혜를 매일 누리니<br/>내게 은혜 나타나 늘 새로워지네<br/>',NULL,30222,5);
INSERT INTO stanza VALUES('K249','1','그날 은 줄 풀어질 때 이렇게 노래 못하나<br/>깨어나서 왕 뵈리니 그 기쁨 한량 없으리<br/>',NULL,30223,1);
INSERT INTO stanza VALUES('K249','chorus','그날 주의 얼굴 보며 구원의 은혜 말하리<br/>그날 주의 얼굴 보며 구원의 은혜 말하리<br/>',NULL,30224,2);
INSERT INTO stanza VALUES('K249','2','땅의 장막 어느 때에 무너질지 모르지만<br/>나는 주와 함께할 것 그것을 확실히 아네<br/>',NULL,30225,3);
INSERT INTO stanza VALUES('K249','3','그날 구주 다시 올 때 나의 일을 곧 마치리<br/>충성된 종 칭찬받고 안식에 들어가겠네<br/>',NULL,30226,4);
INSERT INTO stanza VALUES('K249','4','깨어 그날 준비하리 등을 밝게 수리하고<br/>그날 나는 주를 만나 주 임재 영영 누리리<br/>',NULL,30227,5);
INSERT INTO stanza VALUES('K25','1','오 아버지의 큰 사랑에 감사드리네<br/>주 거룩하신 그 이름 경배해 찬양해<br/>',NULL,30228,1);
INSERT INTO stanza VALUES('K25','2','마음을 열어 뜻을 나타내신 하나님<br/>그 아들 안에 오시어 뜻 다 이루셨네<br/>',NULL,30229,2);
INSERT INTO stanza VALUES('K25','3','우릴 사랑해 아들 버려 죽게 하셨네<br/>우리도 함께 후사 됐네 아들들 됐네<br/>',NULL,30230,3);
INSERT INTO stanza VALUES('K25','4','주 인해 우린 하나님의 생명 얻어서<br/>주 거룩하신 성품 안에 참예케 됐네<br/>',NULL,30231,4);
INSERT INTO stanza VALUES('K25','5','내 영 안으로 아들의 영 보내주시어<br/>날 거듭나고 인침 받아 변케 하시네<br/>',NULL,30232,5);
INSERT INTO stanza VALUES('K25','6','주 아들들을 영광 안에 이끌기 위해<br/>아들의 형상 이르도록 본받게 하네<br/>',NULL,30233,6);
INSERT INTO stanza VALUES('K25','7','이 변화 과정 모든 것을 주가 이끌어<br/>다 영광에서 영광으로 이르게 하네<br/>',NULL,30234,7);
INSERT INTO stanza VALUES('K25','8','오 아버지의 큰 사랑에 감사드리네<br/>다 무릎 꿇어 경배해 그 이름 찬양해<br/>',NULL,30235,8);
INSERT INTO stanza VALUES('K250','1','만복 근원 주 예수님 나를 찬송케 하네<br/>긍휼의 강 넘쳐 흘러 높이 찬송케 하네<br/>하나-님을 멀리 떠-나 방랑-하던 외인을<br/>주님 찾아 구원하려 날 위해 못 박혔네<br/>',NULL,30236,1);
INSERT INTO stanza VALUES('K250','2','주 은혜에 큰 빚진 나 매일 강권함 받네<br/>방랑하는 이 내 맘을 은혜로 묶으소서<br/>나는- 쉽게 방탕하-여 사랑-의 주 떠나니<br/>주의 영의 능력으로 내 마음 이끄소서<br/>',NULL,30237,2);
INSERT INTO stanza VALUES('K250','3','나는 이미 구원 얻고 죄와 사망 떠났네<br/>하나님의 아들만을 항상 표현하겠네<br/>주가- 도움 주시므-로 에벤-에셀 세우네<br/>주의 기뻐하심따라 주의 인도 얻겠네<br/>',NULL,30238,3);
INSERT INTO stanza VALUES('K251','1','내 있는 모든 것 주 은혜로 주신 것 다 받은 것 뿐일세<br/>내 자랑할 것 자존할 것 없고 주의 은혜 뿐일세<br/>',NULL,30239,1);
INSERT INTO stanza VALUES('K251','chorus','이 죄인 은혜 받았네 이 죄인 은혜받았네<br/>이는 내 신분 큰 영광일세 이 죄인 은혜 받았네<br/>',NULL,30240,2);
INSERT INTO stanza VALUES('K251','2','이전에 내 맘에 죄 뿐일 때 내 발걸음은 주 떠났었네<br/>지금은 주님 날 찾으셨네 내 어찌 기뻐 안 하랴<br/>',NULL,30241,3);
INSERT INTO stanza VALUES('K251','3','내 눈물 내 공로 소용없고 주 긍휼 아니면 멸망일세<br/>이전엔 내가 죄 있어서 주께 가까이 못 갔었네<br/>',NULL,30242,4);
INSERT INTO stanza VALUES('K251','4','내 주를 사랑해 기쁨 넘쳐 이 구원 안 밝힐 수가 없네<br/>내 음성 높여 또 밝히겠네 이 죄인 은혜 받았네<br/>',NULL,30243,5);
INSERT INTO stanza VALUES('K252','1','애굽에서 죄의 종 돼 평강 모르던 나 자유 얻어 보려<br/>벽돌 적게 구웠네 오히려 더 부담 늘어<br/>고통 속에 빠져 영광의 땅 들어 본적 없네<br/>',NULL,30244,1);
INSERT INTO stanza VALUES('K252','chorus','난 이제 올라가네 맑은 하늘 높은 산<br/>끝없이 넘쳐나는 산 샘을 마시네 풍성과 은혜 넘쳐나네<br/>젖과 꿀 흐르는 땅 난 이제 거해 영광의 땅<br/>',NULL,30245,2);
INSERT INTO stanza VALUES('K252','2','하나님의 유월절 양 피로 구속 얻어 침례 받고<br/>애굽 떠나 광야로 갔네 구부러진 광야 길을<br/>계속 방황하며 그 땅에 갈 믿음이 없었네<br/>',NULL,30246,3);
INSERT INTO stanza VALUES('K252','3','그리스도 나를 높여 하늘에 앉히니 공중 권세<br/>무너지고 사탄 쩔쩔매 주 예수의 이름 앞에<br/>음부 물러나네 영광의 땅 승리의 땅일세<br/>',NULL,30247,4);
INSERT INTO stanza VALUES('K252','4','한량없는 평강 기쁨 비교할 데 없네 안식 안에<br/>근심 없네 외로움 없네 달콤한 그 사랑 교통<br/>얼마나 좋은지 항상 찬송 넘쳐 영광의 땅<br/>',NULL,30248,5);
INSERT INTO stanza VALUES('K253','1','내 맘 속에 있는 음악은 주의 부드런 음성<br/>너는 내게 속하였으니 영영 버리지 않아<br/>',NULL,30249,1);
INSERT INTO stanza VALUES('K253','chorus','예수 예수 예수 달콤한 이름<br/>날 만족게 하며 전진하게 하시네<br/>',NULL,30250,2);
INSERT INTO stanza VALUES('K253','2','본래 죄의 상처 받은 나 마음에는 고통 뿐-<br/>은혜의 주 내 맘에 오셔 개가 부르게 하네<br/>',NULL,30251,3);
INSERT INTO stanza VALUES('K253','3','이제 나는 주의 은혜와 사랑 속에 안식해-<br/>주의 웃는 얼굴 보이니 기뻐하며 찬송해<br/>',NULL,30252,4);
INSERT INTO stanza VALUES('K253','4','불과 같은 고난 속에도 주는 나의 동반자-<br/>피치 못할 무거운 짐을 주가 담당하시네<br/>',NULL,30253,5);
INSERT INTO stanza VALUES('K253','5','주 오셔서 나를 이끌어 왕국으로 가시리-<br/>나의 모양 변케 하시리 함께 왕노릇하리<br/>',NULL,30254,6);
INSERT INTO stanza VALUES('K254','1','지금까지 나는 찾지 못했네 목마르지 않는 샘<br/>땅의 것은 나의 갈망 못 이뤄 내 맘 만족 못시켜<br/>',NULL,30255,1);
INSERT INTO stanza VALUES('K254','chorus','이제 나는 마셔 영원한 생수<br/>달콤함 기쁨 넘쳐 흐르네<br/>이제 나는 마셔 목마름이 다시 없는<br/>생수 근원 함께 마셔<br/>',NULL,30256,2);
INSERT INTO stanza VALUES('K254','2','나는 이제 생수 근원 찾았네 세상 멀리 떠났네<br/>그리스도 내 마음을 채웠네 평강 기쁨 넘치네<br/>',NULL,30257,3);
INSERT INTO stanza VALUES('K254','3','내가 얻은 만족함과 달콤함 날이 갈수록 더해<br/>주가 내게 평강 안식 주시니 주의 축복 누리네<br/>',NULL,30258,4);
INSERT INTO stanza VALUES('K254','4','주의 무한하신 공급 받으며 은혜 안에 산다네<br/>치료하는 주의 생수 근원에 내 마음 연결됐네<br/>',NULL,30259,5);
INSERT INTO stanza VALUES('K255','1','내 안에 있는 기름 부음 모든 것 가르치며<br/>늘 하나님의 임재 주시며 주와 교통케 하네<br/>',NULL,30260,1);
INSERT INTO stanza VALUES('K255','chorus','기름 부음 내 안에 거하며 내게 가르치네 모두 가르쳐<br/>기름 부음 내 안에 거하며 모든 것을 가르쳐<br/>',NULL,30261,2);
INSERT INTO stanza VALUES('K255','2','내 안에 운행하는 성령 부드러운 관유여<br/>보혈의 귀한 씻음 위에서 영원히 존재하리<br/>',NULL,30262,3);
INSERT INTO stanza VALUES('K255','3','하나님 본질 내게 발라 실재로 알게 하네<br/>주 모든 성분 얻게 하시니 내 전체 충만하네<br/>',NULL,30263,4);
INSERT INTO stanza VALUES('K255','4','내 안에 생명 바르시어 교통 중에 행하네<br/>진리의 빛 가운데 살 때에 은혜의 사랑 넘쳐<br/>',NULL,30264,5);
INSERT INTO stanza VALUES('K256','1','나의 마음 기쁘게 한 예수 나를 찬송케 해<br/>주 계시니 기쁨 넘쳐 주 계시니 찬송 넘쳐<br/>',NULL,30265,1);
INSERT INTO stanza VALUES('K256','chorus','할렐루야 기쁨 넘쳐 할렐루야 찬송 넘쳐<br/>주 계시니 기쁨 넘쳐 주 계시니 찬송 넘쳐<br/>',NULL,30266,2);
INSERT INTO stanza VALUES('K256','2','몸과 맘의 무거운 짐 이젠 멀리 사라졌네<br/>주가 내 죄 다 사하고 내 모든 짐 담당했네<br/>',NULL,30267,3);
INSERT INTO stanza VALUES('K256','3','칠흙같이 어둡던 나 이제 맑은 하늘 보네<br/>미로에서 주 날 끌어 바른 길로 가게 하네<br/>',NULL,30268,4);
INSERT INTO stanza VALUES('K256','4','쓸쓸하고 외롭던 나 이제 주와 함께하니<br/>주님 항상 날 도우며 모든 일에 함께하네<br/>',NULL,30269,5);
INSERT INTO stanza VALUES('K256','5','주의 사랑 날 격려해 은혜로 날 순종케 해<br/>그의 사랑 날 구원해 은혜의 손 날 지키네<br/>',NULL,30270,6);
INSERT INTO stanza VALUES('K256','6','하늘에나 땅에서나 주님 외에 누가 있나<br/>변함없는 그의 사랑 현재에서 영원까지<br/>',NULL,30271,7);
INSERT INTO stanza VALUES('K257','1','일생 동안 사모하던 시원한 샘 찾았네<br/>그 샘 내 속 타는 갈증 해결하여 주셨네<br/>',NULL,30272,1);
INSERT INTO stanza VALUES('K257','chorus','할렐루야 갈망했던 그를 이제 찾았네<br/>주의 생명 날 구원해 나의 갈망 채우네<br/>',NULL,30273,2);
INSERT INTO stanza VALUES('K257','2','배고픔을 달래려고 쥐엄 열매 구했네<br/>내 힘 모두 소모해도 굶주림 못 면했네<br/>',NULL,30274,3);
INSERT INTO stanza VALUES('K257','3','굶주림을 채우려고 애써 구한 모든 것<br/>나로 치욕 느끼게 한 배설물과 같았네<br/>',NULL,30275,4);
INSERT INTO stanza VALUES('K257','4','그침없는 생수의 샘 생명떡은 값없어<br/>나를 위한 주의 풍성 영영 부족함 없네<br/>',NULL,30276,5);
INSERT INTO stanza VALUES('K258','1','아-픔만이 가-득하던 소-망없던 내- 맘<br/>이-제 주님 내- 왕되니 기-쁨이 충-만-해<br/>',NULL,30277,1);
INSERT INTO stanza VALUES('K258','chorus','이제 주 예-수- 내 맘을 만-족게 하-시-네<br/>사랑과 생명 기-쁨 - 다 내 주-가- 주 시 네<br/>',NULL,30278,2);
INSERT INTO stanza VALUES('K258','2','이-세상을 맛-볼수록 갈-증만 더 심-해<br/>하-늘 아래 그-무엇도 내- 맘 못 채-웠-네<br/>',NULL,30279,3);
INSERT INTO stanza VALUES('K258','3','복- 구하던 나-의 마음 주- 찾지 않았-네<br/>무-시했던 주- 예수님 내-게로 오-셨-네<br/>',NULL,30280,4);
INSERT INTO stanza VALUES('K258','4','시-원함을 구-하였네 터-진 웅덩이-서<br/>아- 물은 다 새-나가고 목-마름 더-했-네<br/>',NULL,30281,5);
INSERT INTO stanza VALUES('K258','5','축-복 잃고 맘- 아파도 주- 올 것 몰랐-네<br/>주- 나의 눈 열-어 주니 주- 사랑 알-게-돼<br/>',NULL,30282,6);
INSERT INTO stanza VALUES('K259','1','아 하나님-의- 은혜로 이 쓸데 없-는- 자<br/>왜 구속 하-여- 주는지 난 알 수 없-도-다<br/>',NULL,30283,1);
INSERT INTO stanza VALUES('K259','chorus','내가 믿고 또 의지함은 내 모든 형편 잘 아는 주님<br/>늘 돌보아 주실 것을 나는 확실히 아네<br/>',NULL,30284,2);
INSERT INTO stanza VALUES('K259','2','왜 내게 굳-센- 믿음과 또 복음 주-셔-서<br/>내 맘이 항-상- 편한지 난 알 수 없-도-다<br/>',NULL,30285,3);
INSERT INTO stanza VALUES('K259','3','왜 내게 성-령- 주셔서 내 맘을 감-동-해<br/>주 예수 믿-게-하는지 난 알 수 없-도-다<br/>',NULL,30286,4);
INSERT INTO stanza VALUES('K259','4','주 언제 강-림-하실지 혹 밤에 혹- 낮-에<br/>나 주님 만-날- 그날도 난 알 수 없-도-다<br/>',NULL,30287,5);
INSERT INTO stanza VALUES('K26','1','하나 - 님 그 - 의 사랑으로 많은 은사 주셨지만<br/>하늘 위에서 보 - 혈보 - 다 더 큰 것 못 보았네<br/>',NULL,30288,1);
INSERT INTO stanza VALUES('K26','2','그 피 - 에 대 - 한 믿 - 음을 당신 - 이 안 주시면<br/>은사로 나의 부족함 채워도 공허해 무 - 익해<br/>',NULL,30289,2);
INSERT INTO stanza VALUES('K26','3','오 하나님 사 - 랑 깊은 바다 내 죄 - 다 묻 - 히네<br/>내 모든 불의 거 - 리낌 - 을 가리고 제 - 하네<br/>',NULL,30290,3);
INSERT INTO stanza VALUES('K26','4','보혈 - 안에 - 서 찾 - 았네 사랑 - 의 발 - 자취<br/>당신의 용서 여기서 알 - 고 공 - 의 안 - 다네<br/>',NULL,30291,4);
INSERT INTO stanza VALUES('K26','5','내 맘 - 과 몸 - 은 쇠하여도 나 변 - 함없이 믿네<br/>천지가 없어질 - 지라 - 도 닻 이미 던 - 졌네<br/>',NULL,30292,5);
INSERT INTO stanza VALUES('K26','6','그 사랑의 놀라운 가 - 치를 그날 - 난 증명하리<br/>오늘은 나의 생 - 명 먼 - 저 그 사랑 의지하리<br/>',NULL,30293,6);
INSERT INTO stanza VALUES('K26','7','귀하 - 신 구 - 주 표현케 한 그 능 - 력 주 - 셨네<br/>모든 것 주가 주 - 셨으 - 니 찬 - 송 찬 - 양해<br/>',NULL,30294,7);
INSERT INTO stanza VALUES('K260','1','참 견고한 기촐세 믿는 이들 위해 천지보다<br/>견-고한 주의 말씀 피난처로 피하듯 주-께로<br/>갈- 때 주 말씀 보증하네 너 영영 견고함-<br/>주 말씀이 보증해 너의 견고함<br/>',NULL,30295,1);
INSERT INTO stanza VALUES('K260','2','주 믿는 자 영원히 멸망하지 않아 주 손에서<br/>빼-앗아 갈 자 없네 만유보다 크신 내 아-버지<br/>시-니 아버지께서 준 자 하나도 잃지 않네<br/>아버지께서 준 자 잃지 않으리<br/>',NULL,30296,2);
INSERT INTO stanza VALUES('K260','3','주가 의를 주시어 의롭다 했으니 그 누구가<br/>정-죄할 수 있으랴 내 주께서 대신해 죽-으셨<br/>으-니 누가- 심판하랴 누가- 끊으랴-<br/>내 주-의 사랑서 누가 끊으랴<br/>',NULL,30297,3);
INSERT INTO stanza VALUES('K260','4','주 가까이 하는 자 영영 버리잖네 주 의지<br/>하는- 자 꼭 건지시리 주는 너의 생명 넌 주-의-<br/>지-체 주님-과 하나니 무엇-이<br/>나누랴 주님-과 하나니 누가 나누랴<br/>',NULL,30298,4);
INSERT INTO stanza VALUES('K260','5','악한 자로 인하여 의심 일어날 때 속히 주의<br/>말-씀- 붙잡으라 믿음의 닻 던질 때 요-동치<br/>않-아 영원-히 견고해 든든-케 되리라<br/>영원-히 견고해 든든하리라<br/>',NULL,30299,5);
INSERT INTO stanza VALUES('K261','1','은혜 받은 무리여 다-함께 와서 주 풍성한<br/>은-혜를 노래하세 우리 죄를 사하고 생-명 준<br/>주-께 함께 와 감사하세 함께 와 감사하세<br/>함께 와 감사하세 구주 예수께<br/>',NULL,30300,1);
INSERT INTO stanza VALUES('K261','2','사랑 받은 무리여 다- 함께 오라 주의 사랑<br/>그 깊이를 노래하세 우릴 구원하려고 우리 안에<br/>거-한 주님께 찬양하세 주님께 찬양하세<br/>주님께 찬양하세 내 구주 예수<br/>',NULL,30301,2);
INSERT INTO stanza VALUES('K262','1','영광의 빛 혼에 비취네 햇빛보다 더 밝게<br/>그 빛 맑고 휘황 찬란해 주는 빛 되시네<br/>',NULL,30302,1);
INSERT INTO stanza VALUES('K262','chorus','영광의 빛 복-락의 빛 평강 희락 넘쳐 흐르네<br/>주 예수의 웃는 그 얼굴 빛이 영광 빛을 비추네<br/>',NULL,30303,2);
INSERT INTO stanza VALUES('K262','2','찬미 소리 혼에 넘치네 우리 주 왕 찬양해<br/>주가 지금 듣고 계시니 온 힘껏 찬양해<br/>',NULL,30304,3);
INSERT INTO stanza VALUES('K262','3','지금 평안 혼 안에 찼네 주 내 맘에 계시니<br/>내 맘 속에 평강이 있어 은혜의 꽃 폈네<br/>',NULL,30305,4);
INSERT INTO stanza VALUES('K262','4','지금 기쁨 혼에 충만해 찬송 소망 가득해<br/>주는 이미 은혜 주시고 상 예비하셨네<br/>',NULL,30306,5);
INSERT INTO stanza VALUES('K263','1','예수 나의 주로 택한 오늘 영영 못 잊으리<br/>내 맘 기쁨 타오르니 곳곳에 다 전파하리<br/>',NULL,30307,1);
INSERT INTO stanza VALUES('K263','chorus','기쁜 날 기쁜 날 예수 나를 구원한 날<br/>속죄의 피 내 죄 씻고 생명 생수 만족게 해<br/>기쁜 날 기쁜 날 예수 나를 구원한 날<br/>',NULL,30308,2);
INSERT INTO stanza VALUES('K263','2','예수 나의 주로 택함 영영 후회 안 하겠네<br/>주가 나를 이끄시니 기쁨으로 따르리라<br/>',NULL,30309,3);
INSERT INTO stanza VALUES('K263','3','두 마음을 품었던 나 이제 주만 중심 삼네<br/>주님만을 주목할 때 모든 축복 얻게 되네<br/>',NULL,30310,4);
INSERT INTO stanza VALUES('K263','4','예수 나의 주로 택함 더 새로워지기 원해<br/>눈을 감고 세상 떠나 영원 안에 가기까지<br/>',NULL,30311,5);
INSERT INTO stanza VALUES('K264','1','참 기묘 참 비밀 죄인이 주와 연합했네<br/>사람도 지방도 시간도 주와 날 못 나눠<br/>할렐루야 할렐루야 영광의 비밀<br/>참 비밀 참 비밀 주 안에 성부와 하날세<br/>',NULL,30312,1);
INSERT INTO stanza VALUES('K264','2','참 초월 참 초월 나 주와 함께 부활했네<br/>죄악과 마귀는 또다시 날 묶지 못하네<br/>할렐루야 할렐루야 영광의 초월<br/>참 초월 참 초월 나 지금 주와 같이 사네<br/>',NULL,30313,2);
INSERT INTO stanza VALUES('K265','1','그리스도와 하나된 나 어떠한 축복 확신인가<br/>피로 구속돼 은사 얻고 성령으로 나 후사됐네<br/>',NULL,30314,1);
INSERT INTO stanza VALUES('K265','chorus','이것이 나의 간증이요 이것이 나의 찬송일세<br/>온 종일 주께 노래하며 맘 다해 구주 찬양하리<br/>',NULL,30315,2);
INSERT INTO stanza VALUES('K265','2','달콤함 속에 순종하며 들림받는 날 사모하네<br/>하늘로부터 소리 있어 긍휼과 사랑 일러주네<br/>',NULL,30316,3);
INSERT INTO stanza VALUES('K265','3','늘 주와 함께 교통하며 순종할 때 참 안식일세<br/>주 오심 깨어 기다리며 주 사랑으로 적셔지네<br/>',NULL,30317,4);
INSERT INTO stanza VALUES('K266','1','난 하나님 뜻 정하심을 이해할 수 없지만<br/>하나님 우편 계신 주가- 구주이심 아네<br/>',NULL,30318,1);
INSERT INTO stanza VALUES('K266','2','주 죄인 위해 죽음 알고 그의 효능 믿었네<br/>내 필요함은 오직 그가- 구주 되는 걸세<br/>',NULL,30319,2);
INSERT INTO stanza VALUES('K266','3','주 영광 보좌 떠나 왔네 사람 구하시려고<br/>이 기이하신 사랑 이제- 나도 알게 됐네<br/>',NULL,30320,3);
INSERT INTO stanza VALUES('K266','4','주 수고 공로 내 맘에서 완전히 알기 원해<br/>나 만족하듯 아버지도- 함께 만족하셔<br/>',NULL,30321,4);
INSERT INTO stanza VALUES('K266','5','나 살든 죽든 이 보화로 힘과 위안 얻으니<br/>주 죽음 통해 구주 되셔- 영원한 왕 됐네<br/>',NULL,30322,5);
INSERT INTO stanza VALUES('K267','1','오랫동안 알지 못했네 내 주님 왜 못 박혔는지<br/>갈보리의 죽음 날 위한 것 몰랐네<br/>',NULL,30323,1);
INSERT INTO stanza VALUES('K267','chorus','크신 긍휼 값없는 은혜 내 많은 죄 모두 사했네<br/>해방받고 짐을 벗었네 갈보리서<br/>',NULL,30324,2);
INSERT INTO stanza VALUES('K267','2','율법 앞에 두려워 떤 나 갈보리 산 향해 돌이켜<br/>하나님 비췸 받고 내 죄 알았네<br/>',NULL,30325,3);
INSERT INTO stanza VALUES('K267','3','내 모든 것 주께 드리고 자원하여 주의 종 되리<br/>주가 받은 고통 영영 잊지 않으리<br/>',NULL,30326,4);
INSERT INTO stanza VALUES('K267','4','사랑으로 구원 이룬 주 은혜로 구원 가져온 주<br/>그의 강력 나를 하나님께 이끄네<br/>',NULL,30327,5);
INSERT INTO stanza VALUES('K268','1','내 평생에 가는 길 순-탄하여 늘 잔잔한 강 같든지<br/>큰 풍파로 무섭고 어렵든지 나의 영혼은 늘 편하다<br/>',NULL,30328,1);
INSERT INTO stanza VALUES('K268','chorus','내 영혼 평안해 내 영혼 내 영혼 평안해<br/>',NULL,30329,2);
INSERT INTO stanza VALUES('K268','2','저 마귀는 우리를 삼-키려고 입 벌리고 달려와도<br/>주 예수는 우리의 대장되니 끝내 싸워서 이기겠네<br/>',NULL,30330,3);
INSERT INTO stanza VALUES('K268','3','이 얼마나 영광된 사-실인가 내 죄 다 못 박혔다네<br/>난 죄에서 해방돼 찬송하네 나의 혼이여 찬송하라<br/>',NULL,30331,4);
INSERT INTO stanza VALUES('K268','4','내게 사는 것 오직 그-리스도 주님 나를 다스리니<br/>죽음의 강 파도를 일으켜도 그의 음성 날 평안케 해<br/>',NULL,30332,5);
INSERT INTO stanza VALUES('K268','5','오 내 구주 오심을 기-다리며 무덤 아닌 주를 보네<br/>천사 나팔 울릴 때 주 오시리 참된 소망과 축복일세<br/>',NULL,30333,6);
INSERT INTO stanza VALUES('K269','1','시내 찾는 사-슴처럼 목마른 나의 맘<br/>하나님이 적셔주니 신성-한- 은혤세<br/>',NULL,30334,1);
INSERT INTO stanza VALUES('K269','2','살아 계신 하-나님에 내 맘 목말랐네<br/>내 전체 주 가까이해 주 맘-껏- 누리리<br/>',NULL,30335,2);
INSERT INTO stanza VALUES('K269','3','주는 나의 생-명 능력 또한 내 거처니<br/>배고픈 나 주로 인해 만족-함- 얻었네<br/>',NULL,30336,3);
INSERT INTO stanza VALUES('K269','4','주의 웃는 그- 얼굴이 내 구원 되시니<br/>오직 주의 임재만을 난 간-구-하겠네<br/>',NULL,30337,4);
INSERT INTO stanza VALUES('K269','5','시내 찾는 사-슴처럼 목마른 나의 맘<br/>하나님이 적셔주니 주만-이- 내 필요<br/>',NULL,30338,5);
INSERT INTO stanza VALUES('K27','1','아버지 당 - 신은 죄인 - 을 위하여 -<br/>사랑 - 의 아 - 들을 어이 죽게 했나요<br/>그 - 만이 당신의 유일한<br/>유 - 일한 사 - 랑이거늘<br/>어떻게 버리셨 - 나요<br/>',NULL,30339,1);
INSERT INTO stanza VALUES('K27','2','어이해 아 - 들이 하늘 - 보좌 떠나 -<br/>죽기까지 고통 당해 보혈을 흘렸나요<br/>당 - 신의 큰 사랑이 그를<br/>날 - 위해 고 - 통 받고서<br/>죽게까지 하셨 - 군요<br/>',NULL,30340,2);
INSERT INTO stanza VALUES('K27','3','무엇이 당 - 신의 마음 - 을 감동해 -<br/>성령 - 을 내 - 리사 채우게 하셨나요<br/>당 - 신의 큰 사랑이 그를<br/>나 - 에게 임하게 하셨네<br/>성령을 보내 주 - 셨네<br/>',NULL,30341,3);
INSERT INTO stanza VALUES('K27','4','하나님 은 - 혜는 이렇 - 게 크건만 -<br/>내 사 - 랑은 - 실로 너무도 부 - 족해<br/>내 - 맘아 감 - 사하여라<br/>찬 - 양과 환 - 호 발하라<br/>영원히 그를 찬송하라<br/>',NULL,30342,4);
INSERT INTO stanza VALUES('K270','1','내 맘의 구함 하나님 자신 기쁨과 평안 축복 아닐세<br/>대가 지불해 이 땅 얻음은 내 힘 아니요 은혜 힘일세<br/>',NULL,30343,1);
INSERT INTO stanza VALUES('K270','2','하나님 자신 얻기 위하여 믿음으로써 전진하겠네<br/>하나님으로 충만하도록 내 자아에서 구원하소서<br/>',NULL,30344,2);
INSERT INTO stanza VALUES('K270','3','때로는 이 길 두려워지고 대가도 너무 큰 것 같지만<br/>주가 내 필요 알고 계시니 구부러진 길 갈 수 없다네<br/>',NULL,30345,3);
INSERT INTO stanza VALUES('K270','4','날이 갈수록 주 필요하니 오직 주님만 얻기 원하네<br/>하나님 나의 영광 되심이 내 최종 보상 되기 원하네<br/>',NULL,30346,4);
INSERT INTO stanza VALUES('K271','1','전능한 하나님께 간구하니 내 부르짖음 들어주소서<br/>무한한 영광 속의 하나님께 생명을 주는 분께 구합니다<br/>',NULL,30347,1);
INSERT INTO stanza VALUES('K271','2','주님의 십자가의 죽음 통해 날 흑암 권세에서 건지사<br/>사랑의 아들의 빛의 나라로 온전히 나를 옮겨 놓으셨네<br/>',NULL,30348,2);
INSERT INTO stanza VALUES('K271','3','내 중심부터 충만하게 하사 주변에까지 채워주소서<br/>내 몸에서 주변에 이르도록 당신의 영광 빛을 비추소서<br/>',NULL,30349,3);
INSERT INTO stanza VALUES('K271','4','지극히 거룩하신 하나님이 내 안에 계신 생명 영이니<br/>당신의 영광 나타낼 수 있게 다른 것 구치 않게 하옵소서<br/>',NULL,30350,4);
INSERT INTO stanza VALUES('K271','5','하나님 은혜로 난 주와 함께 생명 안에서 왕 노릇하네<br/>언제나 그리스도 자랑하며 십자가 통해 주의 생명 누려<br/>',NULL,30351,5);
INSERT INTO stanza VALUES('K272','1','하나님을 위하여 불 붙은- 가시떨기<br/>주의 은-혜 입고서 주의 영-광 나타내<br/>',NULL,30352,1);
INSERT INTO stanza VALUES('K272','2','가시떨기 통하여 주 놀라-움 나타내<br/>하나님-의 능력을 능히 나-타낸다네<br/>',NULL,30353,2);
INSERT INTO stanza VALUES('K272','3','가시떨기 연료로 사용하-지 않고서<br/>하나님- 자신만이 그 안에-서 불타네<br/>',NULL,30354,3);
INSERT INTO stanza VALUES('K272','4','가시떨기 통하여 영광 나-타났으니<br/>나도 은-혜 인하여 주 영광- 나타내리<br/>',NULL,30355,4);
INSERT INTO stanza VALUES('K273','1','하나님 내 장래 안배하며 나의 성 허물고 계시는데<br/>충성된 자들은 적어지고- 오해 증가하고 결백 줄어<br/>',NULL,30356,1);
INSERT INTO stanza VALUES('K273','chorus','내 눈의 눈물이 주를 못 보게 해<br/>주 말씀 전보다 못 믿으니<br/>주의 뜻 전보다 더 달콤하도록 날 줄여 주 증가하소서<br/>',NULL,30357,2);
INSERT INTO stanza VALUES('K273','2','더 이상 견딜 힘 없어진 나 주의 손 멈추길 구했지만<br/>당신이 양보치 마옵시고- 내 순종 기다려 주옵소서<br/>',NULL,30358,3);
INSERT INTO stanza VALUES('K273','3','고통의 멍에를 메는 것이 당신의 기쁨과 뜻이라면<br/>오직 난 주의 뜻 순종하여- 기꺼이 고통을 받으리라<br/>',NULL,30359,4);
INSERT INTO stanza VALUES('K273','4','당신의 기쁨의 대가 위해 주 날 막으실 때 쓰러져도<br/>당신의 마음의 기쁨 위해- 기꺼이 막으심 환영하리<br/>',NULL,30360,5);
INSERT INTO stanza VALUES('K273','5','주께서 그들을 차에 태워 내 머리 지나게 하셨으니<br/>내 주여 내 소유 탈취해도- 주의 손 나에게 남기소서<br/>',NULL,30361,6);
INSERT INTO stanza VALUES('K274','1','거룩하신 주 하-나님 이 땅 위에 내려-와<br/>우리 안에 거하-시니 놀라우신 은혤-세<br/>주 예수의 사랑- 긍휼 무한하고 순결-해<br/>통회하는 맘에- 오셔 구원하여 주시-네<br/>',NULL,30362,1);
INSERT INTO stanza VALUES('K274','2','가난한 맘 있는 자마다 그의 성령 마실- 때<br/>그의 안에 만유- 누려 약속하신 안식 누려<br/>모든 죄를 도말-하신 주는 알파 또 오메가<br/>처음이요 나중이신 주 우리 마음 자유케 해<br/>',NULL,30363,2);
INSERT INTO stanza VALUES('K274','3','우릴 구원하여- 주사 자기 생명 주셨-네<br/>우리 안에 오신- 생명 결코 떠나지 않-네<br/>그가 우리 참된- 복 돼 모든 공급 되시-네<br/>완전하신 주의- 사랑 감사하며 찬송-해<br/>',NULL,30364,3);
INSERT INTO stanza VALUES('K274','4','옛 사람을 끝내-시고 새 창조를 시작-해<br/>흠과 티를 제하-시고 영화롭게 하시-네<br/>주의 크신 구원- 우릴 매일 변화시키-니<br/>놀라우신 주님-만을 사랑하며 찬송-해<br/>',NULL,30365,4);
INSERT INTO stanza VALUES('K275','1','사랑하는 귀한 주님 나의 것은 헛되니<br/>주님만이 아름답고 달콤하고 온유하네<br/>비교할 이 없는 주님 누가 주와 비하리<br/>',NULL,30366,1);
INSERT INTO stanza VALUES('K275','2','사랑하는 귀한 주님 그 부르심 들리네<br/>주의 음성 들려 올 때 모든 묶임 벗어나네<br/>교만함과 모든 욕심 천박하게 보이네<br/>',NULL,30367,2);
INSERT INTO stanza VALUES('K275','3','사랑하는 귀한 주님 나의 모든 완악함<br/>주 발 앞에 내려두고 찬송하며 집에 가리<br/>기쁨으로 주 노예 돼 기꺼이 굴복하리<br/>',NULL,30368,3);
INSERT INTO stanza VALUES('K275','4','사랑하는 귀한 주님 주의 길을 택한 나<br/>간혹 눈물 흘리지만 결코 이 길 안 바꾸리<br/>나는 주 맘 기쁘게 해 사랑 더욱 얻으리<br/>',NULL,30369,4);
INSERT INTO stanza VALUES('K275','5','사랑하는 귀한 주님 승천하신 후부터<br/>내 얼굴에 웃음 없고 내 하늘은 밝지 못해<br/>오직 주의 오심만을 사모하며 기다려<br/>',NULL,30370,5);
INSERT INTO stanza VALUES('K275','6','사랑하는 귀한 주님 당신만이 내 사랑<br/>주 얻을 때 모두 얻어 나의 마음 만족게 해<br/>주님 외에 아무 것도 더 구하지 않겠네<br/>',NULL,30371,6);
INSERT INTO stanza VALUES('K275','7','사랑하는 귀한 주께 나의 것 다 드리네<br/>주님만이 아름답고 달콤하고 온유하네<br/>비교할 이 없는 주님 누가 주와 비하리<br/>',NULL,30372,7);
INSERT INTO stanza VALUES('K276','1','내 맘에 사모하는 것 빼앗아 가려면<br/>주여 그 대신 주님을 내게 주옵소서<br/>',NULL,30373,1);
INSERT INTO stanza VALUES('K276','chorus','오 사랑하는 주여 당신 더 주소서<br/>나 주께 순종하니 당신 더 주소서<br/>',NULL,30374,2);
INSERT INTO stanza VALUES('K276','2','내 감정 속에 기복을 허락하셨으니<br/>주여 그 대신 주님을 내게 주옵소서<br/>',NULL,30375,3);
INSERT INTO stanza VALUES('K276','3','내 의지하는 것들을 다 폐하셨으니<br/>주여 그대신 주님을 내게 주옵소서<br/>',NULL,30376,4);
INSERT INTO stanza VALUES('K276','4','더 인내해야 한다면 당신 더 주소서<br/>곧 오시지 않으려면 당신 더 주소서<br/>',NULL,30377,5);
INSERT INTO stanza VALUES('K277','1','들어오소서 문 열렸으니 주님의 음성 나는 압니다<br/>해는 기울고 강풍 임하니 이는 곧 당신의 때입니다<br/>',NULL,30378,1);
INSERT INTO stanza VALUES('K277','2','이 차가웁고 처량한 방에 가구는 모두 어둠에 싸여<br/>정돈도 안 된 빈- 이 방에 손님을 맞을 수가 있을까<br/>',NULL,30379,2);
INSERT INTO stanza VALUES('K277','3','이 비참함이 나로 하여금 당신을 환영하게 하였네<br/>어둠과 혼란 가득한 방에 주님의 빛과 임재 필요해<br/>',NULL,30380,3);
INSERT INTO stanza VALUES('K277','4','빛으로 오신 당신 앞에서 난 개선 요구하지 않으리<br/>내 모든 것은 악하기만 해 당신을 막고 못 오게 했네<br/>',NULL,30381,4);
INSERT INTO stanza VALUES('K277','5','들어오소서 나의 마음에 주님의 거처 삼아주소서<br/>흑암과 죄악 깨끗이 쫓고 예수여 지금 들어오소서<br/>',NULL,30382,5);
INSERT INTO stanza VALUES('K278','1','빛 중의 빛이여 내 안을 비추사<br/>죄악의 밤 쫓고 낮 나타내소서<br/>',NULL,30383,1);
INSERT INTO stanza VALUES('K278','chorus','오 뛰어난 빛이여 내 맘에 들어와<br/>고통의 쾌락 쫓고 거하시옵소서<br/>',NULL,30384,2);
INSERT INTO stanza VALUES('K278','2','기쁨 중의 기쁨 내 안에 들어와<br/>평강으로 내 맘 채워 주옵소서<br/>',NULL,30385,3);
INSERT INTO stanza VALUES('K278','3','생명 중의 생명 내 안에 들어와<br/>죄악의 사망을 다 삼키옵소서<br/>',NULL,30386,4);
INSERT INTO stanza VALUES('K278','4','사랑 중의 사랑 내 안에 흐르사<br/>죄악의 미움을 근절시키소서<br/>',NULL,30387,5);
INSERT INTO stanza VALUES('K278','5','하늘 위의 하늘 내게 강림하사<br/>구름의 휘장을 다 제하옵소서<br/>',NULL,30388,6);
INSERT INTO stanza VALUES('K278','6','내 하나님이여 내 맘에 들어와<br/>거처 정하시고 충만케 하소서<br/>',NULL,30389,7);
INSERT INTO stanza VALUES('K279','1','오 주-여 나의 안-에와 내 마-음 돌-봐 주-소서<br/>피로- 씻었으니 주 자신 내-게 공급하여<br/>주 풍성 누리게 하소서 난 주-의 자녀니<br/>',NULL,30390,1);
INSERT INTO stanza VALUES('K279','2','나 주-와 함께 죽-었네 그 무엇도 내- 맘 못- 나눠<br/>난 세-상 우상과 오락에 대-해 죽-었네<br/>하나님 향해 삶 -으로 주만- 나타내리<br/>',NULL,30391,2);
INSERT INTO stanza VALUES('K279','3','내 주-를 향한 사-모함 갈수-록 더-욱 더-하니<br/>사모-하는 주여 주보다 작은 것 주지 말고<br/>내 은혜로서 오-셔서 주 자-신 주소서<br/>',NULL,30392,3);
INSERT INTO stanza VALUES('K279','4','주 안-에 모두 잃-었네 주 나-의 모-든 것- 됐네<br/>내 영-원한 분깃 주 안에 참-예 하-면서<br/>다른 것 사랑 않 -으리 오라- 참 은혜여<br/>',NULL,30393,4);
INSERT INTO stanza VALUES('K28','1','주 하나님 받으소서 참사랑 향 - 한 우리 경배<br/>성소 안에서 받으소서 당신께서 친히 오셔<br/>피할 데 없 - 는 죄수 우릴 구하여 해방시 - 켰네<br/>오 한량없는 사 - 랑으로 가슴에 긍휼 품고서<br/>우리를 구원하 - 셨네<br/>',NULL,30394,1);
INSERT INTO stanza VALUES('K28','2','죄인 멸망 원치 않고 그들의 구 - 주 되기 위해<br/>당신은 우릴 택 - 했네 죄와 사망 벗어나서<br/>영원한 축 - 복 받게 했네 아들 안에서 구원했네<br/>우린 더 이상 두렵지 않네 아바 아버지 부르며<br/>더 친근하게 나아가네<br/>',NULL,30395,2);
INSERT INTO stanza VALUES('K28','3','주께 속한 모든 자들 그날에 보 - 좌 둘러싸고<br/>당신께 경배 찬양하리 구속받은 큰 무리들<br/>달콤한 찬 - 송 발하리니 저 먼 곳까지 울 - 리리<br/>그날에 우린 무 - 릎 꿇고 당신께 경배하면서<br/>당신의 은혜 노래하리<br/>',NULL,30396,3);
INSERT INTO stanza VALUES('K280','1','주 당신은 나의 생명 생명의 공급이니<br/>나의 영을 돌아보며 풍성케 하소서<br/>',NULL,30397,1);
INSERT INTO stanza VALUES('K280','2','주님 자신 적용하여 주의 성령 내쉬사<br/>나로 주와 함께 죽어 주 닮게 하소서<br/>',NULL,30398,2);
INSERT INTO stanza VALUES('K280','3','음부 사탄 이긴 주님 내 안에 역사하사<br/>나의 성분 소멸하고 주 공급하소서<br/>',NULL,30399,3);
INSERT INTO stanza VALUES('K280','4','당신 자신 적용하여 내 옛 성분 죽이사<br/>날 장사해 나로 주와 살게 하옵소서<br/>',NULL,30400,4);
INSERT INTO stanza VALUES('K280','5','내 속에서 왕노릇한 강한 원수 정복해<br/>주 형상만 나타내고 주께서 사소서<br/>',NULL,30401,5);
INSERT INTO stanza VALUES('K280','6','남은 죄들 제하시고 날 주 거처 삼으사<br/>주의 영광 나를 적셔 주 나타내소서<br/>',NULL,30402,6);
INSERT INTO stanza VALUES('K281','1','주님만 더 깊이 사랑하리 이 간구 들으사 이루소서<br/>오직 주 예수만 사랑하기 원해 더욱 깊이 더욱 깊이<br/>',NULL,30403,1);
INSERT INTO stanza VALUES('K281','2','전에는 세상 복 구했지만 이제는 주님만 구하겠네<br/>오직 주 예수만 사랑하기 원해 더욱 깊이 더욱 깊이<br/>',NULL,30404,2);
INSERT INTO stanza VALUES('K281','3','고통과 슬픔 날 시험하나 내 주만 더욱더 찬송하리<br/>오직 주 예수만 사랑하기 원해 더욱 깊이 더욱 깊이<br/>',NULL,30405,3);
INSERT INTO stanza VALUES('K281','4','내 호흡 내 노래 쇠잔해도 영원히 주님만 사모하리<br/>오직 주 예수만 사랑하기 원해 더욱 깊이 더욱 깊이<br/>',NULL,30406,4);
INSERT INTO stanza VALUES('K282','1','고난 받는 것이 내 길이라면 간고의 길 주가 정하셨다면<br/>주님과의 교통 더욱 친근해 순간 순간 간격 없기 원하네<br/>',NULL,30407,1);
INSERT INTO stanza VALUES('K282','2','땅의 즐거움이 감소될 때에 주여 내게 하늘 더욱 주소서<br/>내 마음은 상해 아플지라도 영은 주를 향해 찬송하도록<br/>',NULL,30408,2);
INSERT INTO stanza VALUES('K282','3','주님 자신 더욱 얻기 위하여 이 땅과의 연결 끊어진대도<br/>주님과의 사이 더 달콤하게 연결되어 주의 향기 누리리<br/>',NULL,30409,3);
INSERT INTO stanza VALUES('K282','4','외로운 이 길에 주 내 동반자 웃는 얼굴로 날 격려하소서<br/>주 은혜로 자아 벗어버리고 생명 분배하는 그릇 되도록<br/>',NULL,30410,4);
INSERT INTO stanza VALUES('K283','1','북풍아 일어나라 남풍아 오너라<br/>내 맘의 동산 안에 향기가 넘치게<br/>북풍아 일어나라 남풍아 오너라<br/>내 맘의 동산 안에 향기가 넘치게<br/>',NULL,30411,1);
INSERT INTO stanza VALUES('K283','chorus','사랑하는 자 내게 오라 순결한 네 사랑을 맛보라<br/>사랑하는 자 내게 오라 순결한 네 사랑을 맛보라<br/>',NULL,30412,2);
INSERT INTO stanza VALUES('K283','2','그의 머리에 나드 향유 부어졌고<br/>아름다운 머리털 그 발을 닦았네<br/>그의 머리에 나드 향유 부어졌고<br/>아름다운 머리털 그 발을 닦았네<br/>',NULL,30413,3);
INSERT INTO stanza VALUES('K283','3','사과나무인 그의 그늘에 쉬겠네<br/>그 과일 달콤하여 내 맘 시원케 해<br/>사과나무인 그의 그늘에 쉬겠네<br/>그 과일 달콤하여 내 맘 시원케 해<br/>',NULL,30414,4);
INSERT INTO stanza VALUES('K283','4','당신은 내게 속해 난 당신께 속해<br/>우리 함께 밭에 가 과실을 누리리<br/>당신은 내게 속해 난 당신께 속해<br/>우리 함께 밭에 가 과실을 누리리<br/>',NULL,30415,5);
INSERT INTO stanza VALUES('K283','5','그분의 맘에 나는 인처럼 새겨져<br/>엄몰치 못할 사랑 죽음보다 강해<br/>그분의 맘에 나는 인처럼 새겨져<br/>엄몰치 못할 사랑 죽음보다 강해<br/>',NULL,30416,6);
INSERT INTO stanza VALUES('K283','6','하늘에 당신 외에 누가 또 있으리<br/>당신 외에는 내가 돌아갈 곳 없네<br/>하늘에 당신 외에 누가 또 있으리<br/>당신 외에는 내가 돌아갈 곳 없네<br/>',NULL,30417,7);
INSERT INTO stanza VALUES('K284','1','막힘없이 오, 막힘없이 주님 영광 보게<br/>이끌어 주시고 사랑해 주소서 막힘없이 막힘없이<br/>',NULL,30418,1);
INSERT INTO stanza VALUES('K284','2','막힘없이 오, 막힘없이 주님 음성 듣게<br/>세상 소리 막고 주 말씀만 듣게 막힘없이 막힘없이<br/>',NULL,30419,2);
INSERT INTO stanza VALUES('K284','3','막힘없이 오, 막힘없이 세상 근심 없고<br/>자아가 입을 옷 제하여 주소서 막힘없이 막힘없이<br/>',NULL,30420,3);
INSERT INTO stanza VALUES('K284','4','막힘없이 오, 막힘없이 주님 가까울 때<br/>의심 사라지고 두려움 없어져 막힘없이 막힘없이<br/>',NULL,30421,4);
INSERT INTO stanza VALUES('K284','5','막힘없이 오, 막힘없이 주의 빛 비추사<br/>안개 제하시고 날 다스리소서 막힘없이 막힘없이<br/>',NULL,30422,5);
INSERT INTO stanza VALUES('K284','6','막힘없이 오, 막힘없이 주님만 보면서<br/>주님과 걷도록 날 소유하소서 막힘없이 막힘없이<br/>',NULL,30423,6);
INSERT INTO stanza VALUES('K284','7','막힘없이 오, 막힘없이 주의 영원한 빛<br/>어둠에 떠올라 날 비췰 때까지 막힘없이 막힘없이<br/>',NULL,30424,7);
INSERT INTO stanza VALUES('K285','1','높은 산에 날 이끌어 주만 보게 하소서<br/>하늘 음성 듣게 하며 맑은 공기 주소서<br/>',NULL,30425,1);
INSERT INTO stanza VALUES('K285','chorus','높은 산에 날 이끌어 주와 교통케 하여<br/>영 안에서 산 샘 마셔 주 누리게 하소서<br/>',NULL,30426,2);
INSERT INTO stanza VALUES('K285','2','더 높은 산 위에 올라 이 땅 초월케 하고<br/>생명 안에 왕 노릇 해 자아 벗게 하소서<br/>',NULL,30427,3);
INSERT INTO stanza VALUES('K285','3','높은 산에 나를 두사 전진하게 하소서<br/>주의 형상 이루어서 주 나타내기 원해<br/>',NULL,30428,4);
INSERT INTO stanza VALUES('K286','1','은혜의 주 예수 내게 늘 필요해<br/>부드러운 음성 늘 평강 주시네<br/>',NULL,30429,1);
INSERT INTO stanza VALUES('K286','chorus','주여 늘 필요하니 항상 내게 오사<br/>매 순간 귀한 은혜 주시옵소서<br/>',NULL,30430,2);
INSERT INTO stanza VALUES('K286','2','주 필요하오니 내게로 오소서<br/>주 가까이하여 유혹 떨치도록<br/>',NULL,30431,3);
INSERT INTO stanza VALUES('K286','3','기쁘나 슬프나 늘 필요한 주님<br/>내 빈 맘 채우고 떠나지 마소서<br/>',NULL,30432,4);
INSERT INTO stanza VALUES('K286','4','늘 필요한 주여 날 가르치소서<br/>주 약속한 축복 내게 주시도록<br/>',NULL,30433,5);
INSERT INTO stanza VALUES('K286','5','지극히 거룩한 은혜의 주님께<br/>나 온전히 속해 늘 함께 있겠네<br/>',NULL,30434,6);
INSERT INTO stanza VALUES('K287','1','주께 속하여 주 음성 듣고 나를 사랑함 아-네<br/>믿음으로 더 높이 올려져 주께 더 친밀하리<br/>',NULL,30435,1);
INSERT INTO stanza VALUES('K287','chorus','날 이끄니 사랑의 주께 더 가까이 가겠네<br/>보혈 흘린 주께 더 가까이 가 주와 함께 있겠네<br/>',NULL,30436,2);
INSERT INTO stanza VALUES('K287','2','나를 분별해 내 마음 다해 주 섬기게 하소-서<br/>내 뜻 버리고 주께 견고한 확신 갖게 하소서<br/>',NULL,30437,3);
INSERT INTO stanza VALUES('K287','3','주의 상에서 머무는 시간 그 발 앞에 엎드-려<br/>주와 대면해 교통할 때에 기쁨 한량없도다<br/>',NULL,30438,4);
INSERT INTO stanza VALUES('K287','4','주의 면전에 안식하기 전 그날 그곳 가기- 전<br/>사랑의 깊이 기쁨의 높이 나는 다 알 수 없네<br/>',NULL,30439,5);
INSERT INTO stanza VALUES('K288','1','해 기울 때 주 함께 하소서 흑암 깊을 때 함께 하소서<br/>누구도 내게 위안 못 줄 때 위로의 주님 함께 하소서<br/>',NULL,30440,1);
INSERT INTO stanza VALUES('K288','2','인생 짧아 곧 황혼이 오니 세상의 영광 풀의 꽃 같아<br/>모든 것 변해 썩어질 때에 변치 않는 주 함께 하소서<br/>',NULL,30441,2);
INSERT INTO stanza VALUES('K288','3','위엄을 가진 왕 중 왕 예수 주님의 눈물 내 근심 씻네<br/>주님의 마음 내 간청 듣네 죄인의 친구인 주 오소서<br/>',NULL,30442,3);
INSERT INTO stanza VALUES('K288','4','나 항상 주의 임재 원하니 주 은혜만이 마귀 물리쳐<br/>어두울 때나 밝을 때에나 주 항상 나와 함께하소서<br/>',NULL,30443,4);
INSERT INTO stanza VALUES('K288','5','주 계시면 적 두렵지 않네 눈물 흘려도 아프지 않네<br/>어떤 죽음도 어떤 무덤도 주 나와 함께 하면 다 이겨<br/>',NULL,30444,5);
INSERT INTO stanza VALUES('K288','6','운명할 때 주 내 곁에 계셔 어두운 계곡 밝히 비추리<br/>하늘과 땅이 폐할지라도 주 항상 나와 함께 하소서<br/>',NULL,30445,6);
INSERT INTO stanza VALUES('K289','1','오 뛰어나-신 주 예수- 그 무엇과 비-하리<br/>그 어-떤 신-조 형식과 세상-의 사랑과<br/>',NULL,30446,1);
INSERT INTO stanza VALUES('K289','2','오 뛰어나-신 주 예수- 사랑 날 정-복해<br/>주 십-자가-로 죽은 나 주 향-해 산다네<br/>',NULL,30447,2);
INSERT INTO stanza VALUES('K289','3','오 뛰어나-신 주 예수- 날 충-만케- 하사<br/>내 생-각 애-호 의지가 주 같-게 하소서<br/>',NULL,30448,3);
INSERT INTO stanza VALUES('K289','4','오 뛰어나-신 주 예수- 날 변-케 하-소서<br/>이 장-막 통-해 주 영광 나타-낼 수 있게<br/>',NULL,30449,4);
INSERT INTO stanza VALUES('K289','5','오 뛰어나-신 주 예수- 내 마-음 원-함은<br/>내 평-생 주-의 노예 돼 주 뜻- 행함일세<br/>',NULL,30450,5);
INSERT INTO stanza VALUES('K29','1','사망과 죄 - 악 속 - 에서 - 헤매던 우리들<br/>이제 - 는 하나님 - 께로 - 서 분 - 깃 얻 - 었네<br/>',NULL,30451,1);
INSERT INTO stanza VALUES('K29','2','죄 중에 있 - 던 나 - 에게 - 주 찾아오셨네<br/>내 마 - 음 감동케 - 하니 - 난 믿 - 고 즐 - 거워<br/>',NULL,30452,2);
INSERT INTO stanza VALUES('K29','3','내 누림 나 - 의 소 - 망은 - 다 성도 위한 것<br/>나 혼 - 자 얻은 것 - 없고 - 다 주 - 의 은 - 혤세<br/>',NULL,30453,3);
INSERT INTO stanza VALUES('K29','4','그 누가 주 - 의 큰 - 사랑 - 다 보답하리요<br/>사람 - 의 뜻을 능 - 가한 거룩 - 한 이 - 사랑<br/>',NULL,30454,4);
INSERT INTO stanza VALUES('K29','5','오 아버지 - 여 매 - 순간 깨닫게 하소서<br/>주만 - 이 나의 생 - 명과 - 내 사 - 랑이 - 심을<br/>',NULL,30455,5);
INSERT INTO stanza VALUES('K29','6','그 누가 다 - 감사 - 하며 - 다 보답하리요<br/>바다 - 보다 더 깊 - 고도 - 넓은 - 이 사 - 랑을<br/>',NULL,30456,6);
INSERT INTO stanza VALUES('K29','7','주님의 크 - 신 사 - 랑을 - 계산할 수 없네<br/>우리 - 를 향한 큰 - 사랑 - 다 셀 - 수 없 - 다네<br/>',NULL,30457,7);
INSERT INTO stanza VALUES('K29','8','지극히 높 - 은 그 - 사랑 - 보답할 수 없어<br/>내 마 - 음 오직 감 - 사해 - 주께 - 경배 - 하리<br/>',NULL,30458,8);
INSERT INTO stanza VALUES('K29','9','사랑하는 - 아버 - 지께 - 빚진 자 된 우리<br/>다만 - 감사를 드 - 리며 - 주 안 - 에 안 - 식해<br/>',NULL,30459,9);
INSERT INTO stanza VALUES('K290','1','주임재 안-에 늘 살게하소서종일주님만이내 세계되어<br/>주 없는일-들을 생각할 때에 나의 맘 기쁘지 않게 하소서<br/>매- 순간 내 위로 되시는 주여 세-상엔날 격려할것- 없-으-니<br/>탄식참지- 못해 눈물흘릴 때 내 눈물 닦으사 멎게 하소서<br/>',NULL,30460,1);
INSERT INTO stanza VALUES('K290','2','꿈꾸듯 내- 인생 생각할 때에 주님도 그 안에 계시옵소서<br/>주 떠나즐-거움 구치않도록스스로 택하지않게하소서<br/>내- 주여 매일 밤 고요한 때에 홀-로 있을때에 함께- 하-소-서<br/>새벽에 깨-기 전 잠잘때에도낮은 소리로 날 불러 주소서<br/>',NULL,30461,2);
INSERT INTO stanza VALUES('K290','3','거룩한주- 말씀읽을 때마다 주 영광으로 글 비춰주소서<br/>귀하신 구-주와주의 큰 구원 내게 속함밝히 보게 하소서<br/>주-보좌 앞에서 무릎 꿇을 때 내- 기도들으사은혜- 주-소-서<br/>내 잘못인해 듣지 않으실 때도 주 임재 거두어 가지 마소서<br/>',NULL,30462,3);
INSERT INTO stanza VALUES('K290','4','하늘의신령한 복 생각할때에들림받기를사모케하소서<br/>오늘내 소-망은 주 다시오심 그날 내 즐거움 주의 임재뿐<br/>주- 나를 가르쳐주 앞에살며 주-만이내 세계 되게- 하-소-서<br/>주 없는일-들을 사랑할 때에 내 마음 기쁘지 않게 하소서<br/>',NULL,30463,4);
INSERT INTO stanza VALUES('K291','1','주여 나를 인도해 생명 빛에 이끌어<br/>임의로 살지 않고 영 안에 생활하게<br/>',NULL,30464,1);
INSERT INTO stanza VALUES('K291','chorus','주여 주여 나를 인도 하소서- -<br/>생명 흐름 통하여 주의 길을 걷도록<br/>',NULL,30465,2);
INSERT INTO stanza VALUES('K291','2','나의 생명 되신 주 생명의 율 되시어<br/>나의 전체 다스려 어둠 변해 빛 되네<br/>',NULL,30466,3);
INSERT INTO stanza VALUES('K291','3','사람의 영 해방한 주여 날 이끄소서<br/>내 생각 새롭게 돼 주 만족하시도록<br/>',NULL,30467,4);
INSERT INTO stanza VALUES('K292','1','주여 나를 인도해 미로에서 건지사<br/>이 세상 끝날까지 주 사랑에 거하게<br/>',NULL,30468,1);
INSERT INTO stanza VALUES('K292','chorus','주여 주여 나를 인도하소서- -<br/>내 길 확신 없으니 이 세상 끝날까지<br/>',NULL,30469,2);
INSERT INTO stanza VALUES('K292','2','인생 풍파 닥쳐도 주 내 피난처시니<br/>주 가까이 계실 때 나는 안전하겠네<br/>',NULL,30470,3);
INSERT INTO stanza VALUES('K292','3','나의 일생 끝까지 주 다시 올 때까지<br/>주여 날 이끄소서 주와 안식 누리게<br/>',NULL,30471,4);
INSERT INTO stanza VALUES('K293','1','주여 나 위해 내 길 선택해 줍소서<br/>내 원함 버리고서 주 뜻 구합니다-<br/>주께서 정한 길에 어떤 고난 있어도<br/>단 맘으로 순종해 주 기쁨 구하리<br/>',NULL,30472,1);
INSERT INTO stanza VALUES('K293','chorus','내 약함 아시오니 내 손 붙드소서<br/>나 혼자는 길 몰라 근심하는 자니<br/>주 뜻대로 정하사 날 인도하소서<br/>어떤 길 택하시든 내 맘 달콤하니<br/>',NULL,30473,2);
INSERT INTO stanza VALUES('K293','2','평탄한 길이든지 굽은 길이든지<br/>내 맘이 기뻐하든 기뻐하지 않든<br/>스스로 주 되기를 원치 않사오니<br/>주 음성 따르리니 내 길 택하소서<br/>',NULL,30474,3);
INSERT INTO stanza VALUES('K293','3','주 손 안의 나의 때 빠르든 혹 늦든<br/>내 원함 없사오니 계획하옵소서<br/>나로 오래 참도록 정한 길이라면<br/>장애물 없어지길 원치 않습니다-<br/>',NULL,30475,4);
INSERT INTO stanza VALUES('K293','4','내 남은 생의 잔을 주 뜻대로 부으사<br/>주 원함따라 나를 이끌어 주소서<br/>주 뜻인 줄 알 때엔 고통도 달콤하고<br/>주의 주심 아니면 기쁨도 원찮네<br/>',NULL,30476,5);
INSERT INTO stanza VALUES('K293','5','건강이든 병이든 주께서 택하소서<br/>웃은 얼굴 우는 눈 큰 일 또 작은 일<br/>어떤 이름이든지 주가 택하소서<br/>내 느낌 원치 않고 주 영광 원하니<br/>',NULL,30477,6);
INSERT INTO stanza VALUES('K294','1','주여 내 손을 잡아 주옵소서<br/>주 없이 나는 못 나갑니다<br/>사랑의 주님 나를 부축하면<br/>두려움 나를 엄습 못하리<br/>',NULL,30478,1);
INSERT INTO stanza VALUES('K294','2','주여 내 손을 잡아 주옵소서<br/>내 발이 실족하지 않도록<br/>나 혹시 흘러 내려가지 않고<br/>주님을 잃어버리지 않게<br/>',NULL,30479,2);
INSERT INTO stanza VALUES('K294','3','주여 내 손을 잡아 주옵소서<br/>주 얼굴 없인 앞길 모르니<br/>주님의 영광 믿음으로 볼 때<br/>나 기뻐 즉시 소리 발하네<br/>',NULL,30480,3);
INSERT INTO stanza VALUES('K294','4','주여 내 손을 잡아 주옵소서<br/>날 위해 주가 가신 이 길을<br/>하늘에 속한 빛을 내게 비춰<br/>나로 이 길을 가게 하소서<br/>',NULL,30481,4);
INSERT INTO stanza VALUES('K295','1','주님의 길이면- 어둡고 험해도<br/>날 위하여 주여 선택해 주소서<br/>',NULL,30482,1);
INSERT INTO stanza VALUES('K295','2','순탄한 길이든- 거칠은 길이든<br/>날 안식으로 이끌 것을 믿으리<br/>',NULL,30483,2);
INSERT INTO stanza VALUES('K295','3','감히 나 스스로- 택하지 않으리<br/>날 빗나가지 않게 하여 주소서<br/>',NULL,30484,3);
INSERT INTO stanza VALUES('K295','4','고통이 있든지- 기쁨이 있든지<br/>내 잔을 당신으로 채워 주소서<br/>',NULL,30485,4);
INSERT INTO stanza VALUES('K295','5','내 친구까지도- 택하여 주소서<br/>내 빈부 여하도 주가 택하소서<br/>',NULL,30486,5);
INSERT INTO stanza VALUES('K295','6','크고 작은 일에- 내 애호 버리리<br/>주 나의 인도 지혜 보물이시니<br/>',NULL,30487,6);
INSERT INTO stanza VALUES('K296','1','주를 더 알기 원하네 주 길 더 좇기 원하네<br/>주님의 구속 더 알고 풍성 더 누리기 원해<br/>',NULL,30488,1);
INSERT INTO stanza VALUES('K296','chorus','그리스도 더욱더 알기를 원해<br/>그의 구속과 풍성을 더 알고 누리기 원해<br/>',NULL,30489,2);
INSERT INTO stanza VALUES('K296','2','부활의 능력 더 알고 무궁한 생명 체험해<br/>승천의 권세 취하여 영광의 승리 누리리<br/>',NULL,30490,3);
INSERT INTO stanza VALUES('K296','3','성령의 계시 더 얻어 아버지 뜻을 더 알아<br/>휘장 안의 일 보고서 주님의 죽음 본받아<br/>',NULL,30491,4);
INSERT INTO stanza VALUES('K296','4','주 말씀 더욱 믿고서 주 은혜 더 의지하리<br/>주의 오심 더 기다려 주님의 왕권 사모해<br/>',NULL,30492,5);
INSERT INTO stanza VALUES('K297','1','주여나로 더욱 주 사랑케 해 주 위해 더 열심 내게 하소서<br/>주 말씀 더 믿고 주 뜻 사모해 더 완전히 순종하게하소서<br/>',NULL,30493,1);
INSERT INTO stanza VALUES('K297','chorus','매일날 부축하사내게 힘을 주소서<br/>나의 일생 주 위해 좁은 길 가도록<br/>',NULL,30494,2);
INSERT INTO stanza VALUES('K297','2','주여나로 더욱 승리케 하사 충성-을 다해 섬기게 하사<br/>당신의 손에 더 유용하게돼 주 대적에 대해 더 용감하게<br/>',NULL,30495,3);
INSERT INTO stanza VALUES('K297','3','주여나로 더욱 주 친근케 해 고통 당할 때에 인내케 하고<br/>범죄할 때 더욱 애통케 하며 기쁨으로항상 수고하도록<br/>',NULL,30496,4);
INSERT INTO stanza VALUES('K297','4','주여나로 더욱 하늘에 속해 주 당신의 얼굴 더 보게 하고<br/>주 다시 오심 더 사모케 하고 주 당신의 임재 더 생각하게<br/>',NULL,30497,5);
INSERT INTO stanza VALUES('K298','1','주여 내 맘에 더 자라소-서 주만 구합니다<br/>주님과 날로 더 친근하-여 죄 벗게 하소서<br/>',NULL,30498,1);
INSERT INTO stanza VALUES('K298','chorus','주 능-력 매일 날 부축하여 약함 돌봐 주소서<br/>주의 빛 나의 어둠 제하-여 사망 삼키소서<br/>',NULL,30499,2);
INSERT INTO stanza VALUES('K298','2','주 영광 빛 내 맘에 비췰- 때 악한 생각 제해<br/>난 무익하나 주 만유 됨-을 늘 가르치소서<br/>',NULL,30500,3);
INSERT INTO stanza VALUES('K298','3','거룩한 주님 영광의 주-님 더 보게 하소서<br/>기쁨에서나 고통에서-나 주 형상 되도록<br/>',NULL,30501,4);
INSERT INTO stanza VALUES('K298','4','뜨거운 주의 사랑의 불-길 내 전체 덮도록<br/>기름을 부어 영의 능력으로 날 도와주소서<br/>',NULL,30502,5);
INSERT INTO stanza VALUES('K298','5','가련한 자아 사라지게 하여 주만 남기소서<br/>주 은혜 인해 늘 주와 교-통 나누게 하소서<br/>',NULL,30503,6);
INSERT INTO stanza VALUES('K299','1','하늘의 노정 가는 나그네 양식은<br/>성-도의 일용하는 매일의 만날-세<br/>하늘에 속한- 성품 공급하는 주-님<br/>그- 풍성 누릴 때에 땅의 기쁨 사라져<br/>',NULL,30504,1);
INSERT INTO stanza VALUES('K299','2','신령한 반석 열려 생명 생수 넘쳐<br/>수정같이 맑은 산 샘 달콤한 샘일-세<br/>내 갈증 제한- 생수 값없이 마시-네<br/>영-원히 주 당신만 마시게 하소-서<br/>',NULL,30505,2);
INSERT INTO stanza VALUES('K299','3','주 먹고 마심으로 주님께 경배해<br/>그- 말씀 그 영 안에 큰 사랑 맛보-네<br/>주님의 양육-받고 주 의지해 사-네<br/>장-성한 분량 충만 나타낼 수 있도록<br/>',NULL,30506,3);
INSERT INTO stanza VALUES('K3','1','영광 영광 아버지께 영광 영광 아들께<br/>영광 영광 성령님께 하나님께 영 - 광<br/>',NULL,30507,1);
INSERT INTO stanza VALUES('K3','chorus','찬양하세 찬양하세 삼일 하나님 - 께(찬양하세)<br/>영광 돌려 영광 돌려 구원 이룬 주 하나님께<br/>',NULL,30508,2);
INSERT INTO stanza VALUES('K3','2','뜻을 세우신 아버지 뜻을 이루신 아들<br/>또한 운행하는 성령 우리 생명 되셨네<br/>',NULL,30509,3);
INSERT INTO stanza VALUES('K30','1','아버 - 지 크신 사 - 랑에 무릎 꿇고 경 - 배합 - 니다<br/>사람 - 이 - 무엇이관대 생 - 각하며 권 - 고 합 - 니까<br/>',NULL,30510,1);
INSERT INTO stanza VALUES('K30','2','사람 - 을 당신 형상대로 당신 - 의 모 - 양대로 지어<br/>당신 - 을 - 채워 나타내 표 - 현하게 계 - 획하 - 셨네<br/>',NULL,30511,2);
INSERT INTO stanza VALUES('K30','3','당신 - 의 형상대로 지은 사람에게 다스릴 권세 맡겨<br/>주 생 - 명 - 으로 영접해 주 - 전 - 체 누 - 리게 - 하네<br/>',NULL,30512,3);
INSERT INTO stanza VALUES('K30','4','당신 - 은 사람 속 - 에 와 사람 - 과 하 - 나 되 - 셔서<br/>사람 - 을 - 거처 삼고서 당 - 신 - 의 영 - 광 나 - 타내<br/>',NULL,30513,4);
INSERT INTO stanza VALUES('K30','5','사람 - 은 타락했 - 으나 당신 - 은 포 - 기하지 않고<br/>구속 - 을 - 통해 회복해 주 - 사 - 랑 지 - 혜 나 - 타내<br/>',NULL,30514,5);
INSERT INTO stanza VALUES('K30','6','아들 - 을 통해 나타나고 죽음 - 과 부활로 구속 이뤄<br/>그 영 - 이 - 되어 내 안에 은혜 주 - 며 권 - 고하 - 시네<br/>',NULL,30515,6);
INSERT INTO stanza VALUES('K30','7','내 영 - 을 지성소로 삼고 그 안 - 에 시은좌 세웠으니<br/>기도 - 의 - 향을 피우며 영 - 안 - 에 주 - 와 교 - 통해<br/>',NULL,30516,7);
INSERT INTO stanza VALUES('K30','8','은혜 - 의 보좌로 - 부터 은혜 - 의 강 - 물 흐 - 르네<br/>내게 - 흘 - 러 날 변케 해 날 - 주 - 의 집으로 건 - 축해<br/>',NULL,30517,8);
INSERT INTO stanza VALUES('K30','9','우린 - 다 사랑 은 - 혜와 거룩 - 한 돌보심 받 - 았네<br/>주 크 - 신 - 사랑 놀라와 감 - 사하며 영 안에 경 - 배해<br/>',NULL,30518,9);
INSERT INTO stanza VALUES('K300','1','주의 형상으로 변하기 원해<br/>주여 나의 갈망 이뤄 주소서<br/>',NULL,30519,1);
INSERT INTO stanza VALUES('K300','2','그 영이신 주님 나의 안에서<br/>흐를 때 내 갈망 이뤄진다네<br/>',NULL,30520,2);
INSERT INTO stanza VALUES('K300','3','내 얼굴을 들어 주 영광 보네<br/>반사하여 주의 형상 비춰 내<br/>',NULL,30521,3);
INSERT INTO stanza VALUES('K300','4','수건없이 주만 반사하겠네<br/>순수한 맘으로 주를 반사해<br/>',NULL,30522,4);
INSERT INTO stanza VALUES('K300','5','주와 대면하여 주 영광 보리<br/>다른 것 안 보고 주만 보겠네<br/>',NULL,30523,5);
INSERT INTO stanza VALUES('K300','6','주의 형상으로 변하기 원해<br/>주 내 맘에 새겨 영광 반사해<br/>',NULL,30524,6);
INSERT INTO stanza VALUES('K300','7','주의 형상 되어 주 나타내리<br/>영광 위에 영광 나타내겠네<br/>',NULL,30525,7);
INSERT INTO stanza VALUES('K301','1','사랑의 구주 닮고 싶어라 이는 내 간구 내 사모함<br/>이 땅의 부요 기꺼이 버려 주님의 형상 닮기 원해<br/>',NULL,30526,1);
INSERT INTO stanza VALUES('K301','chorus','주를 닮으리 주를 닮으리 사랑의 구주 닮으리라<br/>주의 달콤함 견고함 닮아 주 형상 내게 새기리라<br/>',NULL,30527,2);
INSERT INTO stanza VALUES('K301','2','오 닮고파라 온유하신 주 용서와 자비 사랑의 주<br/>외로운 자를 도우시는 주 절망한 자와 죄인의 벗<br/>',NULL,30528,3);
INSERT INTO stanza VALUES('K301','3','오 닮고파라 인내와 겸손 거룩함 충만하신 주님<br/>학대와 능욕 거절하잖고 자신 죽어 남 구하신 주<br/>',NULL,30529,4);
INSERT INTO stanza VALUES('K301','4','주처럼 되길 갈-망하여 대가 지불해 주 따르리<br/>내 모든 것과 내 모든 소유 온전히 주께 드리겠네<br/>',NULL,30530,5);
INSERT INTO stanza VALUES('K301','5','오 주 닮으리 간구할 때에 그 사랑 내게 채워주사<br/>주님 거하는 성전 되도록 내 생명 주 같게 하소서<br/>',NULL,30531,6);
INSERT INTO stanza VALUES('K302','1','어떠한 비밀인가 내 영안의- 주의 영<br/>어떠한 실재인가 두 영 한 영되었네<br/>',NULL,30532,1);
INSERT INTO stanza VALUES('K302','2','영을 인해 행하며 영 안에서- 신령해<br/>영을 인해 섬기며 영 안에서 경배해<br/>',NULL,30533,2);
INSERT INTO stanza VALUES('K302','3','영 안에서 접촉해 내 영 강건-케 되네<br/>영 안에서 기도해 내 영 높이 오르네<br/>',NULL,30534,3);
INSERT INTO stanza VALUES('K302','4','내 영 강하게 하사 남의 영도- 살리며<br/>내 영 높이 올리사 남의 영도 해방해<br/>',NULL,30535,4);
INSERT INTO stanza VALUES('K302','5','항상 말할 때마다 내 영 움직-이게 해<br/>어떤 일을 하든지 영의 공급 원하네<br/>',NULL,30536,5);
INSERT INTO stanza VALUES('K302','6','나의 영이 열려야 남의 영도- 열리네<br/>나의 영이 움직여 남의 영도 올려져<br/>',NULL,30537,6);
INSERT INTO stanza VALUES('K302','7','내게 긍휼 베푸사 그 영 부어- 주소서<br/>주로 인해 모든 영 강건하여지도록<br/>',NULL,30538,7);
INSERT INTO stanza VALUES('K303','1','천사들은 그 얼굴 보았지만 그 큰 사랑 알지 못해<br/>성도들은 그 크신 사랑 아나 그의 모습 못 보았네<br/>잠시 후에는 주의 얼굴 뵙고 그 영광 빛 알겠지만 우리는<br/>지금 주의 눈물 알고 주님의 맘 알기 원해 그 아픈 맘 알기 원해<br/>',NULL,30539,1);
INSERT INTO stanza VALUES('K303','2','그날에는 우리 주 어떠하심 온전히 다 알겠지만<br/>상한 마음 만지며 치료하심 그 날에는 못 누리리<br/>뇌성과 같은 찬송 흐르지만 눈물 속의 간구 없네 통곡과<br/>고난 속의 주의 위로 여기에서 지금 맛봐 여기에서 맛보겠네<br/>',NULL,30540,2);
INSERT INTO stanza VALUES('K303','3','그날에는 영광의 상 있어도 순종할 십자가 없네<br/>우리 위해 주께서 받은 고난 안에 오늘 교통하네<br/>안식 안에는 다시 피로 없고 주를 위한 고통 없네 또 주를<br/>위해 시험 당함 없네 행복 잃고 드림 없네 그 날에는 기회 없네<br/>',NULL,30541,3);
INSERT INTO stanza VALUES('K303','4','오, 기회는 신속히 지나가니 주 위한 기회 많지않아<br/>주님 위해 수치를 당할 기회 조소 받을 기회 적네<br/>잠시 후에는 오해 비방 이별 외로움도 다 없으리<br/>이 모든 고난 축복으로 여겨 그 안에서 주 누리리<br/>주 당신과 연결하리<br/>',NULL,30542,4);
INSERT INTO stanza VALUES('K303','5','오, 주님의 그 얼굴 뵈옵기를 갈망하고 사모하나<br/>주 위해 오늘 시험 피하잖고 이 달콤함 잃잖으리<br/>주 긍휼 인해 주의 사랑 인해 주께 모두 드리면서<br/>주 위해 살리 그 날 바라보며 오늘 기회 붙잡으리<br/>그날 후회 안 하도록<br/>',NULL,30543,5);
INSERT INTO stanza VALUES('K304','1','나의 생명되신 주님 살아 나타낼 때에<br/>주가 나의 모든 해답 모든 열쇠 되시네<br/>주의 비밀 나타내는 투명한 그릇 되어-<br/>주님 자신 살아낼 때 주 뜻 행하게 되네<br/>',NULL,30544,1);
INSERT INTO stanza VALUES('K304','2','우린 주의 성전이니 모든 더러움 씻고<br/>주의 영광 빛 내게서 나타나게 하소서<br/>이제 나의 몸 드리니 주께 순종하는 종 돼<br/>주의 명하심만 따라 행하기 원합니다-<br/>',NULL,30545,2);
INSERT INTO stanza VALUES('K304','3','매 순간 내 모든 지체 주 말씀 기다리며<br/>주 당신의 멍에 메고 속박 받게 하소서<br/>주의 처리 받을 때에 원망 없게 하옵소서<br/>불안한 맘 없게 하고 후회 없게 하소서<br/>',NULL,30546,3);
INSERT INTO stanza VALUES('K304','4','주가 내 길 지시할 때 자유로우시도록<br/>나의 견해 나의 취향 떨치도록 하소서<br/>생명 되신 나의 주님 살아 나타낼 때마다<br/>주가 나의 모든 해답 열쇠 되어 주소서<br/>',NULL,30547,4);
INSERT INTO stanza VALUES('K305','1','내 아버지께서 내 일생 분별하셨-으니<br/>나에게 임-할 환경들 두려워 하지 않네<br/>변함없는 충성으로 주 기쁨만 구하기 원해<br/>',NULL,30548,1);
INSERT INTO stanza VALUES('K305','2','내 눈은 주의 깊은 사랑 향해 늘 깨-오니<br/>모든 것 웃으며 받도록 내 눈물 닦으소서<br/>내 마음 그 사랑과 연합될 때 참된 위로 있네<br/>',NULL,30549,2);
INSERT INTO stanza VALUES('K305','3','늘 분주하-나 불안함 난 결코 원치 않아<br/>몇가지 큰- 일 하기도 난 요구하지 않네<br/>어린아이같-이 주 뜻 따-라 가기 원하네<br/>',NULL,30550,3);
INSERT INTO stanza VALUES('K305','4','어떠한 환-경 당하든 어떤 사람 대하든<br/>나의 왕 섬기기 위하여 내 생명 다- 바쳐<br/>그 사-랑 인하여 타는 맘으로 힘을 다하리<br/>',NULL,30551,4);
INSERT INTO stanza VALUES('K305','5','늘 가르침-을 받도록 은혜 부어 주소서<br/>나 주와 교-통할 때에 내 안팎 하-나 돼<br/>내 분-량 작지만 주님 영-광 얻을 수 있네<br/>',NULL,30552,5);
INSERT INTO stanza VALUES('K305','6','거짓된 모-든 일들은 날 인내케-하고<br/>그 모든 환경의 십자가 날 주만 의뢰케 해<br/>내 마-음 겸손해질 때 모든 것 사랑스럽네<br/>',NULL,30553,6);
INSERT INTO stanza VALUES('K305','7','내 마음 늘- 행복하나 또 구할 것 있다면<br/>주님께 내- 사랑의 맘 다 표현하-는 것<br/>주 위-한 많은 일보다 주-의 기쁨 구하리<br/>',NULL,30554,7);
INSERT INTO stanza VALUES('K305','8','주 사랑 인하여 택한 길 묶임이 아-닐세<br/>어둔 밤 지날 때 주가 날 이끌며 알려 주신<br/>자신- 부인-한 주의 일생이 곧 내 길일세<br/>',NULL,30555,8);
INSERT INTO stanza VALUES('K306','1','주 나를 위해 죽었기에- 내가 살 수 있네<br/>나 또한 나 위해 죽은 주 위해 생명 사랑드리리<br/>',NULL,30556,1);
INSERT INTO stanza VALUES('K306','chorus','오 예수 내 구주- 나로 주 따르게 하옵소서<br/>주 날 위해 죽고 사셨듯 주 위해 죽고 살도록<br/>',NULL,30557,2);
INSERT INTO stanza VALUES('K306','2','주 나를 위해 사시기에- 나 죽을 수 있네<br/>자아에 대-해 죽을 때-에 속됨 떠날 수 있네<br/>',NULL,30558,3);
INSERT INTO stanza VALUES('K306','3','주 나를 위해 사시기에- 나 자아 벗고서<br/>내 주의 생-명 성품 살-아 나타낼- 수 있네<br/>',NULL,30559,4);
INSERT INTO stanza VALUES('K306','4','나 주와 연합함-으로- 주 의지하겠네<br/>깊은 죽음-에 연합하-고 삶에 연합하겠네<br/>',NULL,30560,5);
INSERT INTO stanza VALUES('K306','5','주 나를 위해 사시므로- 나 주 분배하리<br/>다른 이 위-해 주님처-럼 살게 하-옵소서<br/>',NULL,30561,6);
INSERT INTO stanza VALUES('K307','1','오 주여 날 온전케 하옵소서 주가 늘 내 혼 안에 살아 계셔<br/>모든 우상 깨-뜨려 실패 쫓아 날 눈보다 더 희게 씻으소서<br/>',NULL,30562,1);
INSERT INTO stanza VALUES('K307','chorus','눈보다 희게 하옵소서 날 눈보다 더 희게 씻으소서<br/>',NULL,30563,2);
INSERT INTO stanza VALUES('K307','2','하늘 보좌로부터 긍휼 내려 나 주 앞에 완전한 제물 되게<br/>날 도우사 장-애 다 벗게 하고 내 자신을 버리게 하옵소서<br/>',NULL,30564,3);
INSERT INTO stanza VALUES('K307','3','오 주여 나 겸손히 간구하니 주 십자가 피로 날 씻으소서<br/>나 주 보혈 온-전히 신뢰하니 날 눈보다 더 희게 하옵소서<br/>',NULL,30565,4);
INSERT INTO stanza VALUES('K307','4','오 주여 내 간구함 아시오니 곧 나에게 청결한 맘 주소서<br/>주 당신은 내- 구함 아시오니 날 눈보다 더 희게 하옵소서<br/>',NULL,30566,5);
INSERT INTO stanza VALUES('K308','1','이 세상의 영화로움 나 이미 보았지만<br/>주여 다시 내 눈 감겨 주만 보게 하소서<br/>내 육신의 눈으로는 세상밖에 못보니<br/>주여 내 눈 감겨 주사 주만 보게 하소서<br/>',NULL,30567,1);
INSERT INTO stanza VALUES('K308','2','아침 햇빛 저녁 이슬 밤하늘의 별들과<br/>피어나는 꽃구름의 아름다운 광경도<br/>지금 보기 원치 않고 낙원에서 보겠네<br/>주의 긍휼하심따라 소경 되기 원하네<br/>',NULL,30568,2);
INSERT INTO stanza VALUES('K308','3','나의 고통 모든 찔림 떠나기 원치 않네<br/>항상 내가 약한 그때 주의 은혜 더 하네<br/>보좌 영광 내 맘 속에 계시해 주셨으니<br/>사람들의 눈으로는 볼 수 없는 것일세<br/>',NULL,30569,3);
INSERT INTO stanza VALUES('K308','4','칠흑같이 어두운 밤 그의 얼굴 대하여<br/>믿음으로 그를 볼 때 그의 얼굴 광채가<br/>수치 모욕 당하시던 그 얼굴에 빛나네<br/>내 육신의 눈으로는 볼 수 없는 것일세<br/>',NULL,30570,4);
INSERT INTO stanza VALUES('K308','5','밤의 달빛보다 밝고 해보다 더 빛나며<br/>은하수와 뭉게구름보다 더 아름답네<br/>가시면류관을 썼던 거룩한 그 머리에<br/>지금 나타난 영광은 말로 표현 못하네<br/>',NULL,30571,5);
INSERT INTO stanza VALUES('K309','1','주님 자신 계시해 내 육 알게 하소서<br/>주 은혜로 티끌에 쓰러지게 하소서<br/>항상 승리 구하나 계속 무능했던 나<br/>선은 행치 못하고 미운 악만 행했네<br/>',NULL,30572,1);
INSERT INTO stanza VALUES('K309','2','속에서 주 원하나 밖의 행위 가증해<br/>속에 원함 있으나 밖에 능력 없었네<br/>율법과 죄 함께 해 선과 악이 함께해<br/>지체의 법 안에서 벗어날 수 없었네<br/>',NULL,30573,2);
INSERT INTO stanza VALUES('K309','3','넘어지고 일어나 뜻 세우고 또 잃어<br/>거룩하기 원하나 다시 더럽게 됐네<br/>악한 죄에 팔린 나 행할 능력 없었네<br/>선한 것이 없는 나 흑암 중에 있었네<br/>',NULL,30574,3);
INSERT INTO stanza VALUES('K309','4','내게 능력 없음을 이제서야 알았네<br/>나의 생명 철저히 부패함도 알았네<br/>신뢰할 수 없는 나 육체 이길 수 없네<br/>나의 소망 오로지 내 주 예수께 있네<br/>',NULL,30575,4);
INSERT INTO stanza VALUES('K309','5','주 의지해 살도록 십자가로 날 치사<br/>주의 죽음 안으로 들어가게 하소서<br/>주 인해 일하도록 성령 채워 주소서<br/>주의 죽음 내 몸에 깊이 역사하소서<br/>',NULL,30576,5);
INSERT INTO stanza VALUES('K309','6','노예 되어 곤고한 내게 승리 없으니<br/>사망의 이 몸에서 누가 나를 건지랴<br/>나 위해 주 피 흘려 나의 성결 되셨네<br/>주 내 생명 삼고서 주 명령만 따르리<br/>',NULL,30577,6);
INSERT INTO stanza VALUES('K309','7','아버지 앞에 올 때 부끄러움 없다네<br/>주의 얼굴 뵐 때에 다시 괴로움 없네<br/>주의 이름 부를 때 즉시 은혜 임하네<br/>참된 자유 베푸신 주께 감사 드리네<br/>',NULL,30578,7);
INSERT INTO stanza VALUES('K31','1','창세 전에 우리들을 선택하신 아버지<br/>끝이 없고 달콤한 그 사랑 나를 강권해<br/>깊은 사랑 나로 주님 가까이 하게 하고<br/>또 우릴 견고케 하도다<br/>',NULL,30579,1);
INSERT INTO stanza VALUES('K31','2','천지는 다 변하여도 변치 않는 하나님<br/>그 사랑과 그 말씀은 내게 항상 견고해<br/>찬양하라 찬양하라 하나님의 자녀들아<br/>그의 영원함 찬양해<br/>',NULL,30580,2);
INSERT INTO stanza VALUES('K31','3','그의 긍휼 내 입술로 그를 자랑케 하고<br/>그의 은혜 내 마음과 생명 바치게 하네<br/>그의 아들 우리에게 주시기까지 하나님은<br/>우릴 사랑하셨네<br/>',NULL,30581,3);
INSERT INTO stanza VALUES('K31','4','기이하신 그 사랑을 마음 다해 찬양해<br/>하늘 위에 이르도록 땅끝까지 퍼지게<br/>영광 돌려 영광 돌려 하나님과 어린양에게<br/>영원토록 영원히<br/>',NULL,30582,4);
INSERT INTO stanza VALUES('K310','1','총명-해 적-수 없-던 나 에서-와 이삭 지-나와<br/>나 지-금 생-사 관-문서 절망하나 자-신 붙잡네<br/>손 놓-고는 난 못-견뎌 힘쓰-고 계-략 써-야 해<br/>',NULL,30583,1);
INSERT INTO stanza VALUES('K310','2','내 진-영 안-에 온- 그가 두려-웠지만 맞-섰네<br/>내 마-지막-이 올-까봐 전신-의 힘-을 다했네<br/>발버-둥쳐 씨름-했네 사지-에 임-한 자-처럼<br/>',NULL,30584,2);
INSERT INTO stanza VALUES('K310','3','내 과-거 체-험 사-용해 한나-절 씨름했-지만<br/>그는- 여전-히 서-있네 내 힘- 빠진- 것 알고도<br/>내게- 보복 안 하-셨네 그래-도 나-는 맞-섰네<br/>',NULL,30585,3);
INSERT INTO stanza VALUES('K310','4','그 같-은 적-수 못-봤네 그 이-름 알려 줬-지만<br/>난 그-를 알-지 못-했네 그에-게 상- 있음 알고<br/>축복-하길 강요-했네 나에-게 굴-복하-라고<br/>',NULL,30586,4);
INSERT INTO stanza VALUES('K310','5','날 이-미 밝-아왔-으나 승부-를 내지 못-했네<br/>내 강-요 인-해 그-가 날 축복-하고- 칭찬했네<br/>내 새- 이름 이스-라엘 일어-날 때- 난 절-었네<br/>',NULL,30587,5);
INSERT INTO stanza VALUES('K310','6','작은- 빛 맘-에 올- 때에 난 비-췸 받고 알-았네<br/>능력- 있으-면 왜-삐나 나 이-겼다-면 왜 저나<br/>이는- 그의 승리-의 표 내 어-리석-음 경-고해<br/>',NULL,30588,6);
INSERT INTO stanza VALUES('K310','7','그 순-간 빛-이 홍수처럼 날 채-워 둑이 터-졌네<br/>끝없-는 영-광 보-고서 내 자-신 감-추려 했네<br/>내 큰- 죄악 내 더-러움 그제-야 알-게 되-었네<br/>',NULL,30589,7);
INSERT INTO stanza VALUES('K310','8','하나-님 이-기려-한 나 참으-로 어리석-었네<br/>이제- 내게- 화 있-으리 죽어-서 마-땅하리라<br/>내 두- 손이 주 하-나님 못 움-직이-게 했-다니<br/>',NULL,30590,8);
INSERT INTO stanza VALUES('K310','9','오 영-광스-런 하-나님 놀라-운 만군의- 주여<br/>나 이-제 당-신 알-고서 그 어-떠함-을 보았네<br/>크게- 울며 통회-하며 당신-께 무-릎 꿇-었네<br/>',NULL,30591,9);
INSERT INTO stanza VALUES('K310','10','나 어-찌 당-신 뵙-고서 당신-과 대립하-리요<br/>내 수-치 감-출 구-멍이 없는- 것 너-무 한이 돼<br/>왜 난- 진작 소멸-되어 이 세-상 떠나지 않-았나<br/>',NULL,30592,10);
INSERT INTO stanza VALUES('K310','11','교만-에 눈-이 감-긴 나 너무-도 혼미했-었네<br/>주 이-긴 것- 생각-하니 큰 두-려움- 날 붙잡네<br/>내 온- 몸의 힘이- 빠져 무너-져 내-릴 것- 같아<br/>',NULL,30593,11);
INSERT INTO stanza VALUES('K310','12','내 일-생 회-고해-보니 부패-만 가득 차- 있네<br/>날 위-해 주-를 희-생해 내 뜻-만 아-는 자였네<br/>하나-님께 강요-하여 축복-만 얻-으려- 했네<br/>',NULL,30594,12);
INSERT INTO stanza VALUES('K310','13','내 욕-망 나-의 주-장을 하늘-이 듣기 원-했네<br/>주께-서 내-게 양-보해 내 뜻-만 이-루기 원해<br/>조급-한 자 다뤄- 오신 주께-는 실-패 없-다네<br/>',NULL,30595,13);
INSERT INTO stanza VALUES('K310','14','난 사-악하-고 완-악해 교만-하고 사특-한 자<br/>부패-와 미-움 가-득한 야곱-인 날- 주 아시니<br/>주 긍 -휼만 바라-보네 긍휼-히 여-기시-기를<br/>',NULL,30596,14);
INSERT INTO stanza VALUES('K310','15','나 절-뚝거-릴 때-마다 주님-의 긍휼 기-억해<br/>난 이-스라-엘이-지만 영원-히 절-름발일세<br/>나의- 남은 다리-로써 주님-만 의-지하-겠네<br/>',NULL,30597,15);
INSERT INTO stanza VALUES('K310','16','주여- 나 항-복합-니다 당신-이 이겼습-니다<br/>주님-과 겨-뤄 이-긴 나 내 실-패 철-저히 봤네<br/>평생- 떨며 두려-우며 주님-의 뜻-을 행-하리<br/>',NULL,30598,16);
INSERT INTO stanza VALUES('K311','1','주여 나를 보시고 단순함-을 주소서<br/>영 안에-서 가난해 낮아지-게 하소서<br/>',NULL,30599,1);
INSERT INTO stanza VALUES('K311','2','주인 됨을 벗어나 돈의 노-예 벗어나<br/>자신 나-타내잖고 자랑 않-게 하소서<br/>',NULL,30600,2);
INSERT INTO stanza VALUES('K311','3','모든 교만 떨치고 주께 복-종케 하여<br/>죽음에- 이르도록 순종하-게 하소서<br/>',NULL,30601,3);
INSERT INTO stanza VALUES('K311','4','어린 아이 같도록 내 힘 지-혜 폐하사<br/>오직 주- 빛 가운데 주 의지-케 하소서<br/>',NULL,30602,4);
INSERT INTO stanza VALUES('K311','5','젖뗀 아이와 같이 주의 품-에 의지해<br/>주의 평-강 느끼며 주 앙망-케 하소서<br/>',NULL,30603,5);
INSERT INTO stanza VALUES('K311','6','항상 이런 자세로 찬송하-게 하소서<br/>변치 않-고 끝까지 주를 기-다립니다<br/>',NULL,30604,6);
INSERT INTO stanza VALUES('K312','1','주님만 내 안식으로 누리기 원하네<br/>내 모든 활동 멈추고 주 맛보기 원해<br/>',NULL,30605,1);
INSERT INTO stanza VALUES('K312','2','간교한 나의 자아는 늘 발버둥치며<br/>주님과 나를 나누어 안식 못하게 해<br/>',NULL,30606,2);
INSERT INTO stanza VALUES('K312','3','내 자아 여러 형태로 늘 나를 막으며<br/>주 안에 있는 안식을 신뢰 못하게 해<br/>',NULL,30607,3);
INSERT INTO stanza VALUES('K312','4','난 오늘 자아 떠나서 주의 안식 구해<br/>주만이 왕노릇하여 안팎 다스리게<br/>',NULL,30608,4);
INSERT INTO stanza VALUES('K312','5','나 주의 손에 누우니 내게 역사하사<br/>나 자신 신뢰 않도록 은혜를 주소서<br/>',NULL,30609,5);
INSERT INTO stanza VALUES('K312','6','내 자아 주의 은혜로 온전히 깨어져<br/>주의 빛 나타내도록 주 형상 가지리<br/>',NULL,30610,6);
INSERT INTO stanza VALUES('K313','1','주여 날 비워 자아를 벗게- 하소서<br/>이 성결의 큰 역사는 주가- 이루니<br/>',NULL,30611,1);
INSERT INTO stanza VALUES('K313','chorus','주여 날 비워 자아를 벗게- 하소서<br/>내 속에는 선함 없고 어둠- 교만 뿐<br/>속임당한 나의 일생 벗게- 하소서<br/>',NULL,30612,2);
INSERT INTO stanza VALUES('K313','2','주 향한 나의 호소를 들어- 주소서<br/>주의 눈에 나의 죄는 참 더-러우니<br/>',NULL,30613,3);
INSERT INTO stanza VALUES('K313','3','내 불안 뿌리 무언지 보여- 주소서<br/>내 양심은 소리 없이 참소-하오니<br/>',NULL,30614,4);
INSERT INTO stanza VALUES('K313','4','주와 나 사이 담 있어 교통- 끊어져<br/>어디에서 넘어졌나 담대-함 없네<br/>',NULL,30615,5);
INSERT INTO stanza VALUES('K314','1','믿는 이들이 겁내는 감추인 대적은<br/>죄보다 더 간교하고 맘과 잘 융화돼<br/>이는 고집 센 자아요 강퍅한 나 자-신<br/>이 자아 못 박혀야만 주가 살 수 있네<br/>',NULL,30616,1);
INSERT INTO stanza VALUES('K314','2','내 낡은 천성 안에서 능력 있는 자아<br/>자기 신뢰 자기 사랑 자기 자랑 넘쳐<br/>자아를 거절하고서 사지에 두어-야<br/>영 안의 가나안 들어가 안식의 주 누려<br/>',NULL,30617,2);
INSERT INTO stanza VALUES('K314','3','주 보좌 뺏은 자아서 날 구원하소서<br/>주 안에 나를 영원히 잃기 원하오니<br/>자기 신뢰와 자만과 자족을 떠나-서<br/>주만 내 힘과 거처로 삼게 하옵소서<br/>',NULL,30618,3);
INSERT INTO stanza VALUES('K314','4','자아의 추구 벗어나 날 제단에 올려<br/>주님께 산 제물로써 드리게 하소서<br/>교만과 자랑 허영을 벗어나게 하-사<br/>주만 내 자랑 삼고서 높이게 하소서<br/>',NULL,30619,4);
INSERT INTO stanza VALUES('K314','5','맹렬한 바람 보내사 내 자아 불태워<br/>자아의 모든 면들을 소멸해 주소서<br/>주 영광 충만할 때에 모세가 그랬-듯<br/>주 영광으로 날 채워 자아 끝내소서<br/>',NULL,30620,5);
INSERT INTO stanza VALUES('K315','1','입술도 맘도- 부정해<br/>실패와 더러움 뿐인<br/>이런 자에게 여-전-히<br/>주님의 은혜 있나요<br/>',NULL,30621,1);
INSERT INTO stanza VALUES('K315','2','성결과 겸손- 여전히<br/>내 행위 의지하였네<br/>내 죄로 인한 통-회-도<br/>주의 피 씻음 필요해<br/>',NULL,30622,2);
INSERT INTO stanza VALUES('K315','3','자신을 버린- 데에도<br/>감추인 동기 있었네<br/>내 맘이 나의 적-이-니<br/>주 소망 삼을 수 있나<br/>',NULL,30623,3);
INSERT INTO stanza VALUES('K315','4','주님을 섬길-때에나<br/>남들을 사랑할 때도<br/>여전히 자아 있-으-니<br/>난 감히 행동 못하네<br/>',NULL,30624,4);
INSERT INTO stanza VALUES('K315','5','벗기 어려운- 옛 창조<br/>자아는 항상 함께 해<br/>주 영광만 더 사-모-해<br/>주로만 충만되겠네<br/>',NULL,30625,5);
INSERT INTO stanza VALUES('K315','6','난 감히 맹세- 못하고<br/>주만을 주목하겠네<br/>주님을 말씀 보-내-사<br/>주 영광 계시하소서<br/>',NULL,30626,6);
INSERT INTO stanza VALUES('K316','1','은혜를 받-고 남에게 은혜 베푼다 생-각해<br/>내 분수 알지 못-했네 주 앞에 사는 줄 알고<br/>스스로 만족했-었네 자신의 경-건 행-했네<br/>',NULL,30627,1);
INSERT INTO stanza VALUES('K316','2','아무나 견-디지 못할 그 많은 시험 거-친 나<br/>내 자신 강한 줄- 알고 스스로 인정했었네<br/>언제나 나의 체-험을 잊지 못하-고 있-었네<br/>',NULL,30628,2);
INSERT INTO stanza VALUES('K316','3','난 은혜 많-이 받았네 그 누구보다 더- 많이<br/>내 몸과 마음 속-에는 주님의 역사 많다네<br/>나에게 있는 주- 역사 스스로 감-상하-였네<br/>',NULL,30629,3);
INSERT INTO stanza VALUES('K316','4','난 나의 업-적 잘 알고 내 선과 의를 잘-아네<br/>어느덧 나는 자-만해 자신을 중심 삼았네<br/>어제의 만나 변-하여 부패해 짓-밟혀-졌네<br/>',NULL,30630,4);
INSERT INTO stanza VALUES('K316','5','친구가 날-위로하고 내 고통 동정할- 때에<br/>내 교만 감춰지-잖고 내 인내 즉시 끝났네<br/>다른 사람과 똑-같이 난 실패하-고 말-았네<br/>',NULL,30631,5);
INSERT INTO stanza VALUES('K316','6','난 항상 주-를 전하고 주님에 대해 말-하며<br/>모든 것 할 수 있-었네 부패했던 나의 자아<br/>아무런 변화 없-었네 언제나 그-대로-였네<br/>',NULL,30632,6);
INSERT INTO stanza VALUES('K316','7','이제 주 직-접 뵈올 때 더러운 자아 드-러나<br/>주의 빛 나를 깨-뜨려 영광 날 통회케 하네<br/>어찌 자신에 빠-져서 또다시 살-수 있-으랴<br/>',NULL,30633,7);
INSERT INTO stanza VALUES('K316','8','주 은혜로- 날 장식한 부끄러운 나의- 모습<br/>주 역사 이용하-여서 자신을 높인 자일세<br/>모든 동기가 비-천해 승리도 수-치뿐-일세<br/>',NULL,30634,8);
INSERT INTO stanza VALUES('K316','9','부끄러운- 나의 교만 우둔해 눈이 멀-었네<br/>더러움 좋게 여-기고 육체도 좋게 여겼네<br/>스스로 의롭다- 한 나 영광을 내-게 돌-렸네<br/>',NULL,30635,9);
INSERT INTO stanza VALUES('K316','10','주는 내 부-패 아시나 난 전혀 알지 못-했네<br/>자신을 신뢰한- 것이 수치인 줄을 몰랐네<br/>주여 날 구원하-소서 여기서 풀-어 주-소서<br/>',NULL,30636,10);
INSERT INTO stanza VALUES('K316','11','주여 난 흙-에 누워서 재 쓰고 있기 원-하니<br/>내 타락 통회케- 하사 내 수치 알게 하소서<br/>부패한 마음 가-진 나 부끄러움-을 알-도록<br/>',NULL,30637,11);
INSERT INTO stanza VALUES('K316','12','내 말에 정-확함 없고 내 생활 천박하-여서<br/>내 품은 것은 더-러움 모두가 미운 것일세<br/>내 자신 미워하-는 나 주께만 소-망 가-지리<br/>',NULL,30638,12);
INSERT INTO stanza VALUES('K317','1','주여 날 가-려 주소서 고난 피하는 간-구서<br/>전진 못하는 근-심서 자아를 사랑한데서<br/>날 해방하여 주-소서 입대한 작-은 군-병을<br/>',NULL,30639,1);
INSERT INTO stanza VALUES('K317','2','하나님 어-린 양이여 날 구원하여 주-소서<br/>곤란함 피하는- 데서 쉬운 일 취하는 데서<br/>영을 강하게 하-시고 범사에 구-원 하-소서<br/>',NULL,30640,2);
INSERT INTO stanza VALUES('K317','3','전진을 위-한 사랑과 낙심치 않는 믿-음과<br/>좌절치 않는 소-망을 내 안에 채워 주소서<br/>날 높이 올라가-게 해 구름 다 뚫-게 하-소서<br/>',NULL,30641,3);
INSERT INTO stanza VALUES('K318','1','믿음으로 보네 십자가의 주를<br/>나의 주여 내 기도 들으사 날 용서하시고<br/>나 주께 속하게 하옵소서<br/>',NULL,30642,1);
INSERT INTO stanza VALUES('K318','2','능력과 은혜를 이 약한 내 맘에<br/>주옵소서 날 위해 주 예수 피 흘리셨으니<br/>나 또한 주 깊이 사랑하리<br/>',NULL,30643,2);
INSERT INTO stanza VALUES('K318','3','세상 길 갈 때에 근심 고통 오나<br/>날 이끄사 나 후회 않도록 지켜 주옵소서<br/>날 구원하시어 주 좇도록<br/>',NULL,30644,3);
INSERT INTO stanza VALUES('K318','4','인생 곧 지나고 죽음의 강물이<br/>엄몰할 때 주 내게 은혜 줘 두려움 제하고<br/>소망과 안위를 주옵소서<br/>',NULL,30645,4);
INSERT INTO stanza VALUES('K319','1','나는 능력없어서 홀로 설 수 없는 자이나<br/>주를 의지할 때에 나의 약함 축복되리라<br/>',NULL,30646,1);
INSERT INTO stanza VALUES('K319','chorus','언제나 내게는 주의 은혜 필요해<br/>의지할 것 없으니 주를 나타내어 주소서<br/>',NULL,30647,2);
INSERT INTO stanza VALUES('K319','2','괴로운 내 노정은 항상 험하고도 곤하나<br/>주의 은혜 있으면 내가 실족하지 않겠네<br/>',NULL,30648,3);
INSERT INTO stanza VALUES('K319','3','내 느낌 늘 변하고 모두 가치 없어졌다네<br/>내 눈 뵈지 않을 때 내 주 심히 가까울 때라<br/>',NULL,30649,4);
INSERT INTO stanza VALUES('K319','4','주의 달콤함 돌봄 비밀스런 임재 없다면<br/>나는 인내 못하고 쉽게 웃고 쉽게 노하네<br/>',NULL,30650,5);
INSERT INTO stanza VALUES('K319','5','갈수록 강 깊으나 나는 강을 건너가겠네<br/>나 홀로 기도하니 나의 약함 기억하소서<br/>',NULL,30651,6);
INSERT INTO stanza VALUES('K32','1','영광의 아버지여 찬양드립니다<br/>창세 전에 우리를 택하여 주시고<br/>영광에 들어가 - 게 예정해 주셨으니<br/>사랑하는 아들 안에 아들들 됐네<br/>',NULL,30652,1);
INSERT INTO stanza VALUES('K32','2','우릴 거룩게 하려 창세 전에 택해<br/>영광의 기업 되게 예정하셨도다<br/>아들의 명분 주 - 려 일찍이 우리 택해<br/>신령한 복 얻고 또 자라게 하시네<br/>',NULL,30653,2);
INSERT INTO stanza VALUES('K32','3','예정하고 또 우릴 은혜로 부르사<br/>그 생명 얻게 하려 우리 죄 씻었네<br/>기업의 보증 되 - 는 성령의 인침 받고<br/>우린 영원히 주께 속한 자 되었네<br/>',NULL,30654,3);
INSERT INTO stanza VALUES('K32','4','아버지 외에 누가 이 복을 주리요<br/>당신의 생명 얻고 누리는 큰 복을<br/>당신의 영광스 - 런 형상을 나타내며<br/>우린 영원히 주와 영광을 얻으리<br/>',NULL,30655,4);
INSERT INTO stanza VALUES('K320','1','메 말-라 쓸-모 없-었던 한 그-루 나무인- 내가<br/>주님-의 눈-에 띄-었네 주여- 날 버-리지 말고<br/>주 손-으로 취하-여 주사 깨뜨-려 다-뤄 주-옵소서<br/>',NULL,30656,1);
INSERT INTO stanza VALUES('K320','2','여인-이 새- 천 취-하듯 조각-가 밀납 취-하듯<br/>대장장이 쇳덩이 취-하듯 날 버리지 말-아 주소서<br/>주 당-신의 사랑으로 날 당신-의 작-품 만드소서<br/>',NULL,30657,2);
INSERT INTO stanza VALUES('K320','3','내 안-에 금-이 있-어도 돌 같-은 의지 때-문에<br/>그 보-배로-움 못 나타내 타고-난 맘- 쓸모없네<br/>어느- 것도 안 새겨지는 돌 같은 나 버리지 마옵소서<br/>',NULL,30658,3);
INSERT INTO stanza VALUES('K320','4','폭약-이 바-위 깨뜨리듯 망치-가 돌을 깨-듯이<br/>맷돌-로 밀-을 갈-듯이 껍질 벗겨 열-매 다듬듯<br/>주 손-으로 날 깨뜨리소서 주여- 날 버리지 마옵소서<br/>',NULL,30659,4);
INSERT INTO stanza VALUES('K320','5','나 이-미 부-서졌-으나 나 이-미 눌려졌-으나<br/>멸망하는 무-리 공급 못해 주여- 날 폐하지 마시고<br/>주 일- 위해 날 만드소서 주 영-원하-신 사랑으로<br/>',NULL,30660,5);
INSERT INTO stanza VALUES('K320','6','금덩-이 연-단 거-쳐서 유용-한 모양 되-듯이<br/>밀가-루 반-죽 구-워져 사람-의 양-식 되듯이<br/>불로- 나를 다뤄 주소서 영원-히 버리지 마옵소서<br/>',NULL,30661,6);
INSERT INTO stanza VALUES('K321','1','하나님 감추인 사-랑을 아는 자 과연 누-군가<br/>멀리서 주 -의 빛-보며 난 탄식하며 안식 구해<br/>주 안에 안식 못할 때 내 맘엔 고통 뿐일세<br/>',NULL,30662,1);
INSERT INTO stanza VALUES('K321','2','주 음성 은밀히 날-불러 달콤한 멍에 메-게 해<br/>난 주의 부-름 듣-고도 장래를 걱정하-였네<br/>나의 길 정해졌으나 아직도 주를 거스려<br/>',NULL,30663,2);
INSERT INTO stanza VALUES('K321','3','내 마음 이-끌어-주사 주 안에 안식케- 하나<br/>나는 주 가까이 못 -하고 주 의지하지 못-했네<br/>언제나 나의 발걸음 주님을 향할 수 있나<br/>',NULL,30664,3);
INSERT INTO stanza VALUES('K321','4','무엇이 주-와 겨-루어 내 마음 나눌 수- 있나<br/>주만이 왕 노릇 하 -도록 모든 것 제해 주-소서<br/>주 안에 안식할 때에 내 마음 속박 벗으리<br/>',NULL,30665,4);
INSERT INTO stanza VALUES('K321','5','주여 내 자-아 끝-내고 내 안에 주만 사-소서<br/>사악한 정 -욕 못- 박혀 흔적도 없게 하-소서<br/>주 외엔 구하지 않고 원하지 않게 하소서<br/>',NULL,30666,5);
INSERT INTO stanza VALUES('K321','6','오 주여 헛-된 근-심서 날 해방하여 주-소서<br/>자아의 뜻 -을 쫓-아내 흑암서 날 구하-소서<br/>날 항상 순종케 하고 늘 감사하게 하소서<br/>',NULL,30667,6);
INSERT INTO stanza VALUES('K321','7','나로 늘 이-땅 떠-나서 주 명령 듣게 하-소서<br/>주가 내 사-랑 생-명 됨 늘 내게 들려 주-소서<br/>나 주의 음성 듣고서 사랑 맛보게 하소서<br/>',NULL,30668,7);
INSERT INTO stanza VALUES('K322','1','나 주께 묶일 때 참 자유 얻었네<br/>내 무기 주께 드릴- 때 나 속히 승리해<br/>날 의지하면은 난 위기에 빠져<br/>주 팔이 나를 묶을 때 난 더 힘있게 돼<br/>',NULL,30669,1);
INSERT INTO stanza VALUES('K322','2','주께 맡기기 전 난 연약하였네<br/>원하는 것을 못하-고 늘 표류하였네<br/>주 사슬 없으면 난 전진 못하리<br/>주 사랑 나를 붙잡아 난 능력 얻게 돼<br/>',NULL,30670,2);
INSERT INTO stanza VALUES('K322','3','내 생명 안에서 늘 실패뿐이니<br/>내 육체 인해 탄식-해 늘 무능했었네<br/>나 죽지 않으면 살 수가 없다네<br/>자아서 해방하실 때 나 주 얻게 되네<br/>',NULL,30671,3);
INSERT INTO stanza VALUES('K322','4','이제 난 주 알고 나 자신 알았네<br/>또다시 타고난 내- 힘 의지 안 하겠네<br/>영원한 영으로 못 박힌 내 생명<br/>더 감소될 때 주 생명 더 증가하겠네<br/>',NULL,30672,4);
INSERT INTO stanza VALUES('K323','1','이제 빛 비추소서 나 심히 어두우니<br/>당신의 큰 빛으로 내 맘 비추소서<br/>',NULL,30673,1);
INSERT INTO stanza VALUES('K323','2','빛으로 다 비추사 자아 뜻 제하소서<br/>나에게 빛 없으니 주의 빛 주소서<br/>',NULL,30674,2);
INSERT INTO stanza VALUES('K323','3','사탄이 날 속일 때 난 어둠 헤매이니<br/>주의 빛 비추소서 내게 비추소서<br/>',NULL,30675,3);
INSERT INTO stanza VALUES('K323','4','내 생명 비춰 주사 내 약함 알게 하며<br/>내 자신 철저하게 깨닫게 하소서<br/>',NULL,30676,4);
INSERT INTO stanza VALUES('K323','5','내 마음 주님께만 집중케 하옵소서<br/>주의 빛 비춤으로 자유케 하소서<br/>',NULL,30677,5);
INSERT INTO stanza VALUES('K323','6','그림자 전혀 없는 빛 안에 행하게 해<br/>주 빛의 파쇄하심 알게 하옵소서<br/>',NULL,30678,6);
INSERT INTO stanza VALUES('K324','1','내 수건 제하여 주의 빛 보게 해<br/>속임당치 않고 참 알게 하소서<br/>',NULL,30679,1);
INSERT INTO stanza VALUES('K324','chorus','주여 당신의 참 빛 생명의 이 빛이<br/>날 비춰 나의 전체 다 밝혀 주소서<br/>',NULL,30680,2);
INSERT INTO stanza VALUES('K324','2','내 자신에 대해 난 알지 못했네<br/>교만에 속아서 늘 자만하였네<br/>',NULL,30681,3);
INSERT INTO stanza VALUES('K324','3','주님에 대하여 난 더욱 모르네<br/>아는 건 교리뿐 참 계시 없었네<br/>',NULL,30682,4);
INSERT INTO stanza VALUES('K324','4','주 생명에 대해 내 인식 부족해<br/>육체와 성령을 구분치 못했네<br/>',NULL,30683,5);
INSERT INTO stanza VALUES('K324','5','주 길에 대하여 난 혼미하였네<br/>늘 치우쳤던 나 참 길을 몰랐네<br/>',NULL,30684,6);
INSERT INTO stanza VALUES('K324','6','주 뜻이 무언지 난 알지 못했네<br/>늘 내 마음대로 가시채 찼었네<br/>',NULL,30685,7);
INSERT INTO stanza VALUES('K324','7','주 교회에 대해 계시를 주소서<br/>주님의 지혜를 취하게 하소서<br/>',NULL,30686,8);
INSERT INTO stanza VALUES('K324','8','내 수건 제해져 빛 비춤 얻을 때<br/>더 속지 않으리 교만치 않으리<br/>',NULL,30687,9);
INSERT INTO stanza VALUES('K325','1','자신을 의지하던 나 자신을 강하다 믿고<br/>얼마나 무능한지를 난 몰랐-네<br/>',NULL,30688,1);
INSERT INTO stanza VALUES('K325','2','세상 가운데 살 때에 자신의 부족 모르고<br/>내가 늘 전진하는 줄 착각했-네<br/>',NULL,30689,2);
INSERT INTO stanza VALUES('K325','3','나 어둠 안에 거할 때 나 깊이 없음 모르고<br/>겸손할 필요조차도 못 느꼈-네<br/>',NULL,30690,3);
INSERT INTO stanza VALUES('K325','4','주님의 면전에 나와 주님의 비춤 받으니<br/>전에 못 보던 모든 것 다 드러-나<br/>',NULL,30691,4);
INSERT INTO stanza VALUES('K325','5','주님의 면전에 오니 난 다만 부끄러울 뿐<br/>벌거숭이가 되어서 약한 자- 돼<br/>',NULL,30692,5);
INSERT INTO stanza VALUES('K325','6','교만할 것 전혀 없네 의지할 것도 없다네<br/>부끄러움과 통회함뿐이라-네<br/>',NULL,30693,6);
INSERT INTO stanza VALUES('K325','7','다행히 주의 보혈로 정죄에서 해방됐네<br/>주 나를 불사름에서 구원했-네<br/>',NULL,30694,7);
INSERT INTO stanza VALUES('K325','8','나 진정 어리석어서 늘 교만했음 알았네<br/>내 마음 어두웠기에 오만했-네<br/>',NULL,30695,8);
INSERT INTO stanza VALUES('K325','9','잠잠하면 불안하고 말하면 너무 지나쳐<br/>모든 게 실패 부당함 약함일-세<br/>',NULL,30696,9);
INSERT INTO stanza VALUES('K325','10','구하려 하나 못 믿고 의뢰할 줄도 모르네<br/>주여 날 불쌍히 여겨 이끄소-서<br/>',NULL,30697,10);
INSERT INTO stanza VALUES('K326','1','주 날 비춰주소서 아멘<br/>내 죄 드러내소서 할렐루야<br/>그 피로 나의 더러움을 다 씻어주소서 아멘<br/>',NULL,30698,1);
INSERT INTO stanza VALUES('K326','2','주 날 해방하소서 아멘<br/>죄 끈 끊어주소서 할렐루야<br/>저 마귀 멸해 날 해방해 초월케 하소서 아멘<br/>',NULL,30699,2);
INSERT INTO stanza VALUES('K326','3','주 날 회복하소서 아멘<br/>내 약함을 벗도록 할렐루야<br/>주 사랑의 불 붙게 하사 주 위해 살도록 아멘<br/>',NULL,30700,3);
INSERT INTO stanza VALUES('K327','1','내 구주여 내 영을 정결하게 하소서<br/>더러움을 깨끗이 제해 주소서<br/>더러움을 온전하게 제해 주소서<br/>',NULL,30701,1);
INSERT INTO stanza VALUES('K327','2','나로 나의 그릇을 비우도록 하소서<br/>깨끗하게 나의 죄 자백하도록<br/>철저하게 자백하게 하시옵소서<br/>',NULL,30702,2);
INSERT INTO stanza VALUES('K327','3','내 구주여 내 영을 충만하게 하소서<br/>영으로 날 부흥케 하여 주소서<br/>내 온 존재 부흥되게 하여 주소서<br/>',NULL,30703,3);
INSERT INTO stanza VALUES('K328','1','주 얼굴 사모하오니 내 눈을 열어 주소서<br/>주 영광의 빛 비-추사 내 흑암 다 제하소서<br/>나 주의 얼굴 구하니 다시 감추지 마소서<br/>내 눈을 열어 주 얼굴 볼 수 있게<br/>',NULL,30704,1);
INSERT INTO stanza VALUES('K328','2','주 음성 사모하오니 내 귀를 열어 주소서<br/>주 음성 내게 들-리어 거짓말 듣게 마소서<br/>나 주의 얼굴 구하니 다시 감추지 마소서<br/>거룩한 주의 말씀을 청종토록<br/>',NULL,30705,2);
INSERT INTO stanza VALUES('K328','3','주님을 사모하오니 내 맘에 충만하소서<br/>주 충만 내 맘에- 넘쳐 나 자신 잃게 하소서<br/>나 주의 얼굴 구하니 다시 감추지 마소서<br/>내 맘을 열어 주 은혜 채우소서<br/>',NULL,30706,3);
INSERT INTO stanza VALUES('K329','1','주 떠나 다른 길 가는 자<br/>양무리 남 몰래 떠난 자<br/>세상을 사랑해 탐한 자<br/>주여 내가 아닌지요<br/>',NULL,30707,1);
INSERT INTO stanza VALUES('K329','chorus','주 말씀 내 맘을 찌릅니다<br/>주여 나 그런 자 아닙니까<br/>주 분깃 상실한 그 한 사람<br/>혹시 내가 아닌지요<br/>',NULL,30708,2);
INSERT INTO stanza VALUES('K329','2','주님을 뒤에 버려둔 자<br/>악인의 궤휼을 따른 자<br/>성령을 근심케 하는 자<br/>주여 내가 아닌지요<br/>',NULL,30709,3);
INSERT INTO stanza VALUES('K329','3','주 은혜 보답치 않는 자<br/>재물의 신을 섬기는 자<br/>죄악에 빠져서 있는 자<br/>주여 내가 아닌지요<br/>',NULL,30710,4);
INSERT INTO stanza VALUES('K329','4','내 구주 예수 부인한 자<br/>주님을 부끄럽게 한 자<br/>친구와 주님을 판 사람<br/>주여 내가 아닌지요<br/>',NULL,30711,5);
INSERT INTO stanza VALUES('K329','5','주 앞에 들림받을 사람<br/>안식과 달콤함 누릴 자<br/>생명의 면류관 얻을 자<br/>있다 하신 주의 말씀<br/>',NULL,30712,6);
INSERT INTO stanza VALUES('K33','1','오 아버지 당신은 어 - 린 양 안에 - 서 내 소망 안식이요<br/>나타 - 내신 모든 - 인자함 다 복 주시기 위함일세<br/>',NULL,30713,1);
INSERT INTO stanza VALUES('K33','2','당신 - 은 크시고 지혜롭고 또 의롭고 인자한 내 아버지<br/>보혈 - 로 우린 당신께 속해 자녀들 되어 연결됐네<br/>',NULL,30714,2);
INSERT INTO stanza VALUES('K33','3','오 사슴이 시냇물 갈망하듯 고통 - 과 답답함 중 - 에도<br/>피곤 - 한 영이 주 - 께 나와 당신의 이름 앙 - 망해<br/>',NULL,30715,3);
INSERT INTO stanza VALUES('K33','4','당신 - 이 은 - 혜 베푸시니 우린 - 더 당신과 친 - 근해<br/>주 임 - 재 나의 거 - 처 돼 - 내 기쁨 더욱 커 - 지네<br/>',NULL,30716,4);
INSERT INTO stanza VALUES('K33','5','오 우 - 리 영 - 영 기뻐 뜀은 어둔 - 밤 빛으로 변함일세<br/>마지 - 막 호흡 힘 - 을 다해 당신을 찬양하 - 겠네<br/>',NULL,30717,5);
INSERT INTO stanza VALUES('K330','1','길고 넓-고 높-고 깊-은 사-랑 인-해<br/>나와 같-은 죄-인 괴-수 큰- 은혜- 받았-네<br/>',NULL,30718,1);
INSERT INTO stanza VALUES('K330','2','내 주 대-가 치-뤄 나-를 구-속했-네<br/>나는 십-자가-를 지-고 주-를 따-르겠-네<br/>',NULL,30719,2);
INSERT INTO stanza VALUES('K330','3','주님 얻-기 위-해 모-두 내-려 놓-네<br/>생명이-나 죽-음까-지 생-각하-지 않-네<br/>',NULL,30720,3);
INSERT INTO stanza VALUES('K330','4','친구 명-성 선-행 무-슨 소-용있-나<br/>주 날 위-해 낮-췄으-니 나-도 낮-추겠-네<br/>',NULL,30721,4);
INSERT INTO stanza VALUES('K330','5','내 구주- 사랑-해 그-의 칭-찬 구-해<br/>안락 이-익 고-통 손-실 주- 위해- 바꾸-리<br/>',NULL,30722,5);
INSERT INTO stanza VALUES('K330','6','나의 위-로 되-신 은-혜로-운 예-수<br/>하늘에-나 땅-에서-나 주-님 밖-에 없-네<br/>',NULL,30723,6);
INSERT INTO stanza VALUES('K330','7','고통 반-대 불-행 돌-아보-지 않-네<br/>오직 주-의 사-랑으 -로 내- 전체- 싸소-서<br/>',NULL,30724,7);
INSERT INTO stanza VALUES('K330','8','주여 간-구하-니 내-게 은-혜 주-사<br/>늘 힘 주-사 어-둔 세-상 지-나게- 하소-서<br/>',NULL,30725,8);
INSERT INTO stanza VALUES('K330','9','사탄 세-상 육-체 나-를 시-험하-니<br/>힘 주소-서 주-의 이-름 부-끄럽-지 않-게<br/>',NULL,30726,9);
INSERT INTO stanza VALUES('K330','10','이제 지-체 말-고 세-상 벗-기 원-해<br/>주 오실- 때 외-치겠-네“아-멘 할-렐루-야”<br/>',NULL,30727,10);
INSERT INTO stanza VALUES('K331','1','널 위해 피 흘려- - 내 생명 버렸다<br/>널 깨끗이 씻고- - 죽음서 살-렸다<br/>널 위해 생-명 줬건만 넌 무엇 주-느냐<br/>널 위해 생-명 줬건만 넌 무엇 주-느냐<br/>',NULL,30728,1);
INSERT INTO stanza VALUES('K331','2','널 위해 여러 해 - - 고통 재앙 받아<br/>널 영영 평강과- - 즐거움 누리게 해<br/>널 위해 다- 주었건만 넌 무엇 주-느냐<br/>널 위해 다- 주었건만 넌 무엇 주-느냐<br/>',NULL,30729,2);
INSERT INTO stanza VALUES('K331','3','내 아버지의 집- - 내 영광 보좌를<br/>널 위해 버리고- - 이 땅에 표-류해<br/>널 위해 다- 버렸건만 넌 무엇 버렸느냐<br/>널 위해 다- 버렸건만 넌 무엇 버렸느냐<br/>',NULL,30730,3);
INSERT INTO stanza VALUES('K331','4','널 위해 지극한- - 고난 고초 받아<br/>널 음부로부터- - 해방되게-했다<br/>널 위해 고통 받았건만 넌 무엇 짊어졌나<br/>널 위해 고통 받았건만 넌 무엇 짊어졌나<br/>',NULL,30731,4);
INSERT INTO stanza VALUES('K331','5','완전한 구원과- - 사랑의 용서를<br/>널 위해 하늘서- - 가져와 주-었다<br/>널 위해 가-져왔건만 넌 무엇 가져왔나<br/>널 위해 가-져왔건만 넌 무엇 가져왔나<br/>',NULL,30732,5);
INSERT INTO stanza VALUES('K331','6','주여 내 생명과- - 세월 다 드려서<br/>이 땅 묶임 벗고- - 주 명령 따릅니다<br/>날 위해 다- 버린 당신 위해 다 버립니다<br/>날 위해 다- 버린 당신 위해 다 버립니다<br/>',NULL,30733,6);
INSERT INTO stanza VALUES('K332','1','날 놓지 않는 주의 사랑 내 피곤한 혼 안식게 해<br/>내 빚진 여생 가져와서 주 깊은 바다 두리<br/>더 충만히 넘치게<br/>',NULL,30734,1);
INSERT INTO stanza VALUES('K332','2','내 길을 비추시는 빛께 내 꺼져가는 등불 맡겨<br/>내 맘은 주의 빛으로- 다시 빛 발하네<br/>더 밝고 아름다웁게<br/>',NULL,30735,2);
INSERT INTO stanza VALUES('K332','3','고통에 빠진 나를 찾은 주 향해 내 맘 닫지 못해<br/>난 무지개를 찾았다네 주 말씀 신실하심<br/>아니 눈물 없다네<br/>',NULL,30736,3);
INSERT INTO stanza VALUES('K332','4','내 머리 들게 한 십자가 난 주를 떠나지 않네-<br/>이생의 허영 땅에 묻혀 그 흙에 생명의<br/>꽃 피어나게 하겠네<br/>',NULL,30737,4);
INSERT INTO stanza VALUES('K333','1','네 영 이미 주 접촉하고 네 맘 주께 빼앗겼으니<br/>응당 주를 으뜸으로 여겨 분복으로 즐겨 택하라<br/>',NULL,30738,1);
INSERT INTO stanza VALUES('K333','chorus','오 만인의 으뜸이신 주여 내 마음 더 사로 잡으소서<br/>우상 다 깨고 내게 관 씌운 당신은 으뜸 나의 주 예수<br/>',NULL,30739,2);
INSERT INTO stanza VALUES('K333','2','세상 헛된 영광 보화는 우릴 넘어 뜨리는 우상<br/>그에 붙잡히고 덮여지면 순수하게 초월 못하리<br/>',NULL,30740,3);
INSERT INTO stanza VALUES('K333','3','현란한 우상들의 모양 사라지게 하는 그것은<br/>낙심 실망과 권면 아닐세 귀한 주의 나타남일세<br/>',NULL,30741,4);
INSERT INTO stanza VALUES('K333','4','우상 흙으로 만드는 건 어떤 지위 압력 아니요<br/>주의 영광의 아름다움과 주의 사랑의 흐름일세<br/>',NULL,30742,5);
INSERT INTO stanza VALUES('K333','5','아침 해가 뜨지 않을 때 누가 등불 끄기 원하랴<br/>따스한 바람 불지 않을 때 누가 두꺼운 옷 벗으랴<br/>',NULL,30743,6);
INSERT INTO stanza VALUES('K333','6','오직 베드로가 본 눈과 스데반이 본 그 얼굴과<br/>마리아와 함께한 그 맘이 나로 땅의 유혹 벗게 해<br/>',NULL,30744,7);
INSERT INTO stanza VALUES('K333','7','주만 내 마음 채우도록 사랑으로 날 이끄소서<br/>주의 구속된 동반자인 나 우상과 아무 상관없네<br/>',NULL,30745,8);
INSERT INTO stanza VALUES('K334','1','분별되어 모두 주께 돌아가 대가 아끼잖고 주 풍성 구해<br/>모든 묶임 끊고 깊은 물 열어 그 큰 능력 얻고 축복 얻으리<br/>',NULL,30746,1);
INSERT INTO stanza VALUES('K334','chorus','절대 분별되어 주께 돌아가 주의 부르심에 응답하겠네<br/>',NULL,30747,2);
INSERT INTO stanza VALUES('K334','2','분별되어 모두 주께 돌아가 자아 끝내도록 침몰되리라<br/>주 발 앞에 자신 파쇄되도록 주의 은혜 채워 넘칠 때까지<br/>',NULL,30748,3);
INSERT INTO stanza VALUES('K334','3','분별되어 모두 주의 뜻 좇고 은혜 힘 의지해 주의 길 가리<br/>안락 버리고서 주를 좇으리 주의 음성 듣고 인도받으리<br/>',NULL,30749,4);
INSERT INTO stanza VALUES('K334','4','분별되리 모두 영세에까지 내 뜻 구치 않고 주 뜻 구하리<br/>나의 계획 갈망 사라졌으니 내 소유 없으나 만유 내 것일세<br/>',NULL,30750,5);
INSERT INTO stanza VALUES('K334','5','모두 분별되니 달콤함 넘쳐 주의 포로 되어 자유 누리네<br/>죄의 억압 의심 두려움 벗고 모든 무거운 짐 근심 벗었네<br/>',NULL,30751,6);
INSERT INTO stanza VALUES('K334','6','모두 분별되니 참 안식일세 주의 뜻을 좇아 충만되겠네<br/>그의 성령으로 충만될 때에 나의 각 부분이 연단되겠네<br/>',NULL,30752,7);
INSERT INTO stanza VALUES('K334','7','주의 임재 안에 충만 누리며 주의 축복 사랑 맘껏 누리네<br/>영원토록 주께 분별되어서 내 안의 빛 영영 밝게 빛나리<br/>',NULL,30753,8);
INSERT INTO stanza VALUES('K335','1','난 이미 세상 쾌락서 내 몸을 돌렸다네<br/>내 맘은 이미 더 좋은 하늘의 저축 향해<br/>그 허영 자랑 이제 또 날 잡아 끌지 못해<br/>난 이미 세상 던지고 그 경계 넘어섰네<br/>등 뒤로 멀리 멀리 버렸네<br/>난 이미 세상 던지고 그 경계 넘어 섰네<br/>',NULL,30754,1);
INSERT INTO stanza VALUES('K335','2','난 어리석고 죄악된 그 행위 버렸다네<br/>난 이제 주의 인도와 주 음성 따른다네<br/>죽음의 종 되지 않고 나 주를 의지하네<br/>주 위해 세상 등 뒤에 저 멀리 버린다네<br/>등 뒤로 멀리 멀리 버리리<br/>주 위해 세상 등 뒤에 저 멀리 버린다네<br/>',NULL,30755,2);
INSERT INTO stanza VALUES('K335','3','이전의 어리석은 데 나 다시 가지 않네<br/>더 정죄 없이 안식과 참 평강 누린다네<br/>내 주인 바뀌었으니 그분만 섬기겠네<br/>이 땅의 묶임 벗어나 세상을 뒤로 버려<br/>등 뒤로 멀리 멀리 버리리<br/>이 땅의 묶임 벗어나 세상을 뒤로 버려<br/>',NULL,30756,3);
INSERT INTO stanza VALUES('K335','4','내 장래 정해졌으니 딴 주인 원치 않네<br/>주 나의 모든 죄악을 다 사해 주셨다네<br/>내 맘은 주만 섬기길 꼭 작정하였으니<br/>과거를 향해 다시는 더 돌아서지 않네<br/>등 뒤로 멀리 멀리 버리네<br/>과거를 향해 다시는 더 돌아서지 않네<br/>',NULL,30757,4);
INSERT INTO stanza VALUES('K336','1','분별되니 기-쁨 넘쳐 거룩함- 축복- 넘쳐<br/>주만이 내 사-랑되니 모든 것 다 벗-어나네<br/>주-님 안-에 안-식해<br/>주-님 안-에 안-식해<br/>',NULL,30758,1);
INSERT INTO stanza VALUES('K336','2','주 날 불러 분-별했네 그가 이- 길 인-도해<br/>주님 그의 생-활 통해 분별됨을 예-증했네<br/>누-가 주-를 따-를까<br/>누-가 주-를 따-를까<br/>',NULL,30759,2);
INSERT INTO stanza VALUES('K336','3','나로 영문 밖-에 가서 주께 오-게 하-소서<br/>달게 주께 항-복하고 능욕지게 하-옵소서<br/>주-께 돌-아가-리라<br/>주-께 돌-아가-리라<br/>',NULL,30760,3);
INSERT INTO stanza VALUES('K336','4','분별되어 근-심 벗네 분별되-어 죄- 벗네<br/>죄인들을 관-심하며 등에 짊어지-기 원해<br/>주-의 자-취 따-르리<br/>주-의 자-취 따-르리<br/>',NULL,30761,4);
INSERT INTO stanza VALUES('K336','5','사랑하는 주-께 가리 주와 간-격 없-도록<br/>철저하게 헌-신하리 완전하게 돌-아가리<br/>영-영 주-께 돌-아가<br/>영-영 주-께 돌-아가<br/>',NULL,30762,5);
INSERT INTO stanza VALUES('K337','1','내 모든 것 주 예수께 아낌없이 드리네<br/>영영 주를 사랑하며 주님 앞에 살겠네<br/>',NULL,30763,1);
INSERT INTO stanza VALUES('K337','chorus','모두 드리네 모두 드리네<br/>은혜로운 나의 주께 모두 드리네<br/>',NULL,30764,2);
INSERT INTO stanza VALUES('K337','2','내 모든 것 주 예수께 아낌없이 드리네<br/>주 발 앞에 엎드리니 나를 받아 주소서<br/>',NULL,30765,3);
INSERT INTO stanza VALUES('K337','3','내 모든 것 주 예수께 아낌없이 드리네<br/>온전히 날 얻으소서 주의 소유 되도록<br/>',NULL,30766,4);
INSERT INTO stanza VALUES('K337','4','내 모든 것 주 예수께 아낌없이 드리네<br/>주의 생명 나타내게 주의 은혜 주소서<br/>',NULL,30767,5);
INSERT INTO stanza VALUES('K337','5','내 모든 것 주 예수께 아낌없이 드리네<br/>거룩한 불 날 태우니 주께 영광 돌리네<br/>',NULL,30768,6);
INSERT INTO stanza VALUES('K338','1','주 예수께 다 드림이 합당한 것 아닌가<br/>주의 피로 구속된 나 주의 소유 아닌가<br/>',NULL,30769,1);
INSERT INTO stanza VALUES('K338','chorus','주 예수께 다 드리리 아낌없이 드리리<br/>그리스도 내 구주께 아낌없이 드리리<br/>',NULL,30770,2);
INSERT INTO stanza VALUES('K338','2','주 예수께 다 드리길 내 마음 사모하네<br/>주 사랑 날 격려하니 어찌 아니 드릴까<br/>',NULL,30771,3);
INSERT INTO stanza VALUES('K338','3','주 예수께 다 드려서 거룩하게 되겠네<br/>영과 혼과 몸과 함께 시간 재물 드리리<br/>',NULL,30772,4);
INSERT INTO stanza VALUES('K338','4','내 손 주께 쓰임 받고 내 발 주 길 좇으며<br/>내 눈 주의 얼굴 보며 내 입 주를 찬송해<br/>',NULL,30773,5);
INSERT INTO stanza VALUES('K338','5','내 눈 주를 주목한 후 나의 생각 변했네<br/>십자가의 주를 볼 때 달게 멍에 메겠네<br/>',NULL,30774,6);
INSERT INTO stanza VALUES('K338','6','길고 높고 넓고 깊은 주의 놀라운 은혜<br/>영광의 주 왕 중 왕이 나를 보배로 보네<br/>',NULL,30775,7);
INSERT INTO stanza VALUES('K339','1','주여 나의 일생이 헌신되게 하시고<br/>매일 순간순간을 쓰임 받게 하소서<br/>',NULL,30776,1);
INSERT INTO stanza VALUES('K339','chorus','나를 위해 가시관 쓰고 나를 위해 못박히셨네<br/>영원히 내 생명 주께 바쳐서 주를 사랑하겠네<br/>',NULL,30777,2);
INSERT INTO stanza VALUES('K339','2','나의 손발 얻으사 주 일하게 하시고<br/>입과 혀를 얻으사 주를 전케 하소서<br/>',NULL,30778,3);
INSERT INTO stanza VALUES('K339','3','나의 은금까지도 보류 않게 하시고<br/>나의 재능 얻으사 주 뜻대로 쓰소서<br/>',NULL,30779,4);
INSERT INTO stanza VALUES('K339','4','내 뜻 감정 얻으사 돌이키게 하시고<br/>나의 사랑 얻으사 주만 보게 하소서<br/>',NULL,30780,5);
INSERT INTO stanza VALUES('K34','1','주 하나님 세상을 사랑하사 우리에게 주신 독생자 예수<br/>자기 생명 버려서 구속 이뤄 생명의 문 열고 다 오라 하네<br/>',NULL,30781,1);
INSERT INTO stanza VALUES('K34','chorus','찬양해 찬양해 그 음성 들은 자 찬양해 찬양해 은혜 받은 자여<br/>이 큰 구원 행하신 주 예수께 다 찬양해 영광과 감사 드려<br/>',NULL,30782,2);
INSERT INTO stanza VALUES('K34','2','오 완전한 구속 보혈의 구속 모든 믿는 자에게 주신 약속<br/>주 예수님 믿고서 영접할 때 그 어떠한 죄인도 용서받네<br/>',NULL,30783,3);
INSERT INTO stanza VALUES('K34','3','오 위대한 구원을 이루신 주 우리에게 넘치는 기쁨 되네<br/>주 안에서 자라고 변화되어 주 다시 뵐 때 기쁨 더욱 크리<br/>',NULL,30784,4);
INSERT INTO stanza VALUES('K340','1','나 이-제 주께 모두- 드려 다 내-어 놓고<br/>주께- 드려 내 모-든 소유를 제단-에 놓으리<br/>날 속-량해 주신 주께 드려<br/>',NULL,30785,1);
INSERT INTO stanza VALUES('K340','2','주 내-게 모두 주셨-으니 나 또-한 주께<br/>다 드-리리 치우-치지 않고 주 좇-기 원하네<br/>주 말-씀 끝까지 순종하리<br/>',NULL,30786,2);
INSERT INTO stanza VALUES('K340','3','주 내-게 준 것 참 풍-성해 주 나-를 사신<br/>주인-이니 내 모-든 소유 다 주님-께 속하네<br/>금은-과 재물도 드리겠네<br/>',NULL,30787,3);
INSERT INTO stanza VALUES('K340','4','온전-히 주께 다 드-리리 내 안-의 생명<br/>살아-내게 주 안-에 하나님 풍성-이 있으니<br/>나 아-닌 주께서 이기소서<br/>',NULL,30788,4);
INSERT INTO stanza VALUES('K341','1','땅의 향락 천한 이익 나를 유혹 못하네<br/>땅의 헛된 그림자도 나를 못 괴롭히네<br/>가면쓰고 오는 우상 나는 이미 버렸네<br/>내 맘 주께 드렸으니 그분께만 속하리<br/>',NULL,30789,1);
INSERT INTO stanza VALUES('K341','chorus','나는 주의 것 나는 주의 것<br/>자신의 것 아닌 그리스도의 것<br/>',NULL,30790,2);
INSERT INTO stanza VALUES('K341','2','오직 주께 속할 때에 어떠한 안식인가<br/>나의 소유 안 남길 때 주의 풍성 의지해<br/>나는 주의 소유이니 주여 나를 받으사<br/>나의 전체 주께 속해 주 누리게 하소서<br/>',NULL,30791,3);
INSERT INTO stanza VALUES('K341','3','피곤하던 몸부림을 그만 포기하여라<br/>자신 보류하지 말고 모두 주께 드리라<br/>너를 얻기 위해 주가 그분 자신 주셨다<br/>그의 전부 주셨으니 네 것 어찌 아끼랴<br/>',NULL,30792,4);
INSERT INTO stanza VALUES('K342','1','단순히 주님만 위해 살길 모든 일에 주의 기쁨 얻길<br/>자원해 주님께 순종하길 원함이 축복의 비결일세<br/>',NULL,30793,1);
INSERT INTO stanza VALUES('K342','chorus','예수 내 주 내 구주 내 대신 죽으사<br/>자신 내게 준 주께 나 자신 드리네 이제 다른 주 없네<br/>내 맘은 주 보좌 내 일생 오직 주님만 위해 살기 원해<br/>',NULL,30794,2);
INSERT INTO stanza VALUES('K342','2','날 위해 십자가 모욕과 죄 담당한 주님만 위해 살리<br/>그 사랑 날 강권해 이끄니 겸손히 내 소유 주께 드려<br/>',NULL,30795,3);
INSERT INTO stanza VALUES('K342','3','어디서나 예수 위해 살리 주 위해 주 소유 되기 원해<br/>손실과 고통과 모든 시험 십자가 일부로 달게 받아<br/>',NULL,30796,4);
INSERT INTO stanza VALUES('K342','4','주 위해 살 날이 많지 않네 내 귀한 비밀은 주의 얼굴<br/>잃은 자 찾으려 죽으신 주 날 구속해 안식 누리게 해<br/>',NULL,30797,5);
INSERT INTO stanza VALUES('K343','1','발-버둥 침 무익하니 주-께 돌아와<br/>주- 의지해 힘-을 얻고 안-식한다네<br/>',NULL,30798,1);
INSERT INTO stanza VALUES('K343','2','헛-된 분투 노력 떠나 무-조건 주께<br/>온-전하게 헌-신할 때 안-식 얻으리<br/>',NULL,30799,2);
INSERT INTO stanza VALUES('K343','3','주-께 모든 힘 있으니 주-가 구원해<br/>주-의 사랑 인-해 주의 노-예 되겠네<br/>',NULL,30800,3);
INSERT INTO stanza VALUES('K343','4','순-종할 때 능력 얻고 죽을 때 살겠네<br/>내- 뜻 아닌 그-의 뜻만 날- 이기게 해<br/>',NULL,30801,4);
INSERT INTO stanza VALUES('K344','1','토기장이인 주 뜻따라 진흙인 나를 빚으소서<br/>나 굴복하고 기다리니 주 형상 따라 만드소서<br/>',NULL,30802,1);
INSERT INTO stanza VALUES('K344','2','겸손히 주께 엎드리니 날 감찰하고 시험하사<br/>나의 참 모습 드러내어 날 순수하게 씻으소서<br/>',NULL,30803,2);
INSERT INTO stanza VALUES('K344','3','완전히 나의 자아에서 벗어나기를 사모하니<br/>날 깨뜨리사 파 내소서 남는 것 없게 비우소서<br/>',NULL,30804,3);
INSERT INTO stanza VALUES('K344','4','주의 뜻 따라 내 온 존재 주 앞에 굴복하기 원해<br/>주 충만하고 주 나타내 주 형상으로 주를 살리<br/>',NULL,30805,4);
INSERT INTO stanza VALUES('K345','1','어떻게 내 주 사-랑해 주님을 기쁘게-할까<br/>늘 주의 길-을 안 떠나- 주 가까이- 함 배-우리<br/>',NULL,30806,1);
INSERT INTO stanza VALUES('K345','2','이 길에 고통 있-어도 물러서지는 않-으리<br/>주 십자가- 짐 기억해- 순종하-게 하-소서<br/>',NULL,30807,2);
INSERT INTO stanza VALUES('K345','3','당신의 순결한- 그 길 언제나 생각하-겠네<br/>향락 다 버-린 곤한 길- 늘 정처없-고 주-린 길<br/>',NULL,30808,3);
INSERT INTO stanza VALUES('K345','4','내 기쁨 구치 않-으리 주님의 죽음 생-각해<br/>내 어찌 땅-의 안락을- 주보다 더-욱 취-할까<br/>',NULL,30809,4);
INSERT INTO stanza VALUES('K345','5','주님의 기쁨 얻-으려 모든 것 해로 여-기네<br/>아낌없이- 내 모든 것- 다 배설물-로 여-기네<br/>',NULL,30810,5);
INSERT INTO stanza VALUES('K346','1','난 어떤 길을 가든 주를 따르리<br/>평탄하든 험난하든 협착하든<br/>구주 나와 함께 하니 주를 따르리<br/>주저하지 않고 왕국에까지<br/>',NULL,30811,1);
INSERT INTO stanza VALUES('K346','chorus','주를 따르리 주 예수 따르리<br/>괴롭든 즐겁든 주를 따르리 주를 따르리<br/>주 예수 따르리 어디로 날 인도하든 따르리<br/>',NULL,30812,2);
INSERT INTO stanza VALUES('K346','2','난 밝고 즐거워도 주를 따르고<br/>사망의 골짜기서도 주 따르리<br/>구주 나를 돌보시니 주를 따르리<br/>마지막 한 걸음까지 따르리<br/>',NULL,30813,3);
INSERT INTO stanza VALUES('K346','3','난 어느 때나 항상 주를 따르리<br/>밝을 때나 어둔 구름 있을 때나<br/>구주 나를 안배하니 주를 따르리<br/>모든 염려 벗고 날이 밝도록<br/>',NULL,30814,4);
INSERT INTO stanza VALUES('K347','1','명예와 이익과 영화버리고<br/>주 은혜 의지해 주 말씀 지켜<br/>끝까지 내 주께 충성다하리<br/>그날에 주께서 상 주시리니<br/>면류관 그 영광 비할 데 없네<br/>비할 데 없네 비할 데 없네<br/>',NULL,30815,1);
INSERT INTO stanza VALUES('K348','1','내 모든 것 내려놓고 십자가를 지고서<br/>달게 멸시 고통 당해 좁은 길을 가겠네<br/>나의 이전 구하던 것 모두 사-라졌지만-<br/>주가 나의 분깃 되니 이 어떠한 복인가<br/>',NULL,30816,1);
INSERT INTO stanza VALUES('K348','2','세상아 너 주 버렸듯 나도 함께 버려라<br/>사람들은 날 속여도 주 날 속이지 않네<br/>친구들이 멀리하고 대적 흉-악 하지만-<br/>주의 웃는 얼굴 볼 때 나의 마음 평안해<br/>',NULL,30817,2);
INSERT INTO stanza VALUES('K348','3','가라 세상 명성 재물 오라 고통 비웃음<br/>주의 기쁨 함께 하면 손실도 이익이라<br/>아바 아버지인 주께 내 맘 몰-두했으니-<br/>폭풍이나 구름 모두 나를 유익게 하리<br/>',NULL,30818,3);
INSERT INTO stanza VALUES('K348','4','사람들 날 핍박할 때 더욱 주 앞에 가네<br/>세상 고통 억누를 때 하늘 평강 더 달아<br/>주의 영광 얼굴 뵈니 근심 고-통 이기네-<br/>주님 없는 세상 쾌락 어찌 날 미혹하리<br/>',NULL,30819,4);
INSERT INTO stanza VALUES('K348','5','은혜로 더 전진하여 영광에 들어가리<br/>믿음이 내 방패 되고 간구가 내 날개 돼<br/>땅의 사역 멈추는 날 나그네-길 끝날 때-<br/>소망이 내 사실 되고 나의 간구 찬양 돼<br/>',NULL,30820,5);
INSERT INTO stanza VALUES('K349','1','왕국 찾-는 이 많으나 십자가 피해<br/>상 원하-는 이 많으나 세상 못-버려<br/>주 십자-가 좁은 길-은 거절하면서<br/>많은 이-들 주의 축복 기대 한다네<br/>',NULL,30821,1);
INSERT INTO stanza VALUES('K349','2','주의 영-광 사모하나 수욕 원찮네<br/>왕 노릇-은 원하지만 손실 원-찮아<br/>주로 인-해 모든 것-을 해로 여기고<br/>배설물-로 여기는 자 어디에 있나<br/>',NULL,30822,2);
INSERT INTO stanza VALUES('K349','3','주 달콤-함 원하지만 금식 싫어해<br/>주의 보-좌 좋아하나 고난 원-찮아<br/>주와 함-께 노래하-기 좋아하지만<br/>깨어 수-고하는 자들 심히 적다네<br/>',NULL,30823,3);
INSERT INTO stanza VALUES('K349','4','고귀함-은 사모하나 비천함 겁내<br/>주가 범-사 예비하면 감사드-리나<br/>주가 조-금 요구할-때 즉시 원망해<br/>주가 조-금 요구하면 곧 원망하네<br/>',NULL,30824,4);
INSERT INTO stanza VALUES('K349','5','성실히- 주 섬기는자 해든 복이든<br/>묻지 않-고 주 위하여 생명 버-리네<br/>주여 나-로 살든 죽-든 모두 다 잊고<br/>끝날까-지 충성하게 하시옵소서<br/>',NULL,30825,5);
INSERT INTO stanza VALUES('K35','1','그 아들 보내 나를 위해 죽고<br/>부활 승천해 내 제사장 되게 해<br/>',NULL,30826,1);
INSERT INTO stanza VALUES('K35','chorus','할렐루야 영광 돌려 할렐루야 아멘<br/>할렐루야 아버지께 감사하여라<br/>',NULL,30827,2);
INSERT INTO stanza VALUES('K35','2','빛 비춰주사 구속주 계시해<br/>나의 눈 밝게 열어서 보게 했네<br/>',NULL,30828,3);
INSERT INTO stanza VALUES('K35','3','영광과 찬양 아버지께 돌려<br/>나를 구했네 아들의 구속 통해<br/>',NULL,30829,4);
INSERT INTO stanza VALUES('K35','4','그 크신 사랑 찬양 감사하세<br/>사랑 인하여 맘 불타 경배하세<br/>',NULL,30830,5);
INSERT INTO stanza VALUES('K350','1','누가 주 편에서 왕을 맞을까<br/>누가 싱싱하고 항상 푸른가<br/>의문 문자 떠나 영 안에 사나<br/>누가 회복 위해 주 편에 설까<br/>',NULL,30831,1);
INSERT INTO stanza VALUES('K350','chorus','형제 자매 모두 주 편에 서세<br/>영 안에 뜨겁게 항상 찬송해<br/>',NULL,30832,2);
INSERT INTO stanza VALUES('K350','2','주의 군대에서 힘써 싸움은<br/>면류관의 영광 구함 아니요<br/>주 사랑 강권돼 전진함일세<br/>은혜 받아 응당 주 편에 서리<br/>',NULL,30833,3);
INSERT INTO stanza VALUES('K350','3','금과 은이 아닌 주의 보혈로<br/>나를 구속하여 백성 삼았네<br/>주를 따르는 자 축복 얻으니<br/>자원하여 자유 안에 전진해<br/>',NULL,30834,4);
INSERT INTO stanza VALUES('K350','4','전쟁 맹렬하고 대적 악해도<br/>주 예수의 군대 파할 자 없네<br/>주의 깃발 아래 승리 얻으니<br/>참된 주님 의지하여 이기네<br/>',NULL,30835,5);
INSERT INTO stanza VALUES('K350','5','주의 군사로서 택함 받고서<br/>나의 충성 다해 주를 좇으리<br/>냉담하지 않고 나의 왕 섬겨<br/>정절 다해 용맹 다해 싸우리<br/>',NULL,30836,6);
INSERT INTO stanza VALUES('K351','1','하나님 어린 양 좇아 십자가 지려면<br/>내 어찌 대가 두려워 세상에 굽히랴<br/>',NULL,30837,1);
INSERT INTO stanza VALUES('K351','chorus','주의 이름 인하여 어떤 고난 있어도<br/>주 은혜 의지하면서 주 기쁨 구하리<br/>',NULL,30838,2);
INSERT INTO stanza VALUES('K351','2','성도들 영광 위하여 피땀 흘리는데<br/>내 어찌 가마 타고서 편히 들리우랴<br/>',NULL,30839,3);
INSERT INTO stanza VALUES('K351','3','저 대적 구멍 뚫을 때 어찌 안 막으랴<br/>어찌 세상과 어울려 그 도움 구하랴<br/>',NULL,30840,4);
INSERT INTO stanza VALUES('K351','4','나 그날 다스리려면 오늘 싸워야 해<br/>주 은혜 말씀 의지해 환난 이기겠네<br/>',NULL,30841,5);
INSERT INTO stanza VALUES('K352','1','난 항상 요동-하여-도 주님은 변하-지 않-네<br/>주 약속 다 이-뤄 지-니 천지보다 더 견고-해<br/>',NULL,30842,1);
INSERT INTO stanza VALUES('K352','2','난 몰래 두 맘- 품어-도 주는 날 버리-지 않-네<br/>사람의 천대-받을-때 진정한 나의 친구-돼<br/>',NULL,30843,2);
INSERT INTO stanza VALUES('K352','3','영영 날 버리-지 않-고 내 모든 부탁- 듣는- 주<br/>주 예수 날 사-랑하-되 끝까지 사랑하시-네<br/>',NULL,30844,3);
INSERT INTO stanza VALUES('K352','4','양심도 없이- 주 잊-고 변심해 돌아-섰던- 나<br/>내 맘에 우상- 있어-도 미안해하지 않았-네<br/>',NULL,30845,4);
INSERT INTO stanza VALUES('K352','5','이 우상 쓰러-졌을-때 슬퍼하면서-왔다-네<br/>전에 내가 버-린 친-구 늘 변함없는 구주-께<br/>',NULL,30846,5);
INSERT INTO stanza VALUES('K352','6','주 다시 나를-영접-해 가까이하게- 하시-네<br/>그런 일 없던- 것처-럼 끝까지 나를 사랑-해<br/>',NULL,30847,6);
INSERT INTO stanza VALUES('K352','7','내 맘과 힘을- 다하-여 주 사랑 찬양-하겠-네<br/>죽음보다 강-한 사-랑 내 마음 녹게 하시-네<br/>',NULL,30848,7);
INSERT INTO stanza VALUES('K353','1','전에 나-는 열심히 전진하려 애썼네<br/>이젠 변-해 구주를 가까이 안하네<br/>부지런-히 수고해 밤낮없이 일한 나<br/>이젠 변-해 오히려 냉랭하게 됐네<br/>',NULL,30849,1);
INSERT INTO stanza VALUES('K353','chorus','어찌 나의 구주 잊고 떠나겠나<br/>주 아픈 맘 잊고 나 어찌 편하랴<br/>',NULL,30850,2);
INSERT INTO stanza VALUES('K353','2','전엔 내-몸 드리고 돈 위하지 않았네<br/>이젠 세-상 종 되어 그 안에 잠겼네<br/>전엔 순-결 지킨 나 이젠 느슨해졌네<br/>오래 방-황하여도 통회하지 않네<br/>',NULL,30851,3);
INSERT INTO stanza VALUES('K353','3','전엔 주-만 사모해 주만 사랑했던 나<br/>잠든 때-나 깰 때나 늘 주 생각했네<br/>무의미-한 모든 것 세상 다 버렸었네<br/>이젠 흙-만 구하니 세상과 똑같네<br/>',NULL,30852,4);
INSERT INTO stanza VALUES('K353','4','전에 주-를 따를 때 만족 기쁨 넘쳤네<br/>주의 보-냄 받고서 순종키 원했네<br/>주님 외-의 다른 것 원하지도 않았네<br/>이제 마-음 식어져 그 약속 잊었네<br/>',NULL,30853,5);
INSERT INTO stanza VALUES('K353','5','주를 떠-난 수고들 바람 잡는 것일세<br/>양무리-를 떠나니 늘 고통뿐이네<br/>속히 가-는 세상에 어찌 다시 묶이랴<br/>주님 사-랑하기를 더 주저 못하리<br/>',NULL,30854,6);
INSERT INTO stanza VALUES('K353','6','세월 점-점 빠르고 밤은 이내 지나니<br/>속히 타-락 떠나서 주 기쁨 구하리<br/>세상 마-귀 버리고 다시 하늘 맛보네<br/>처음 사-랑 찾고서 다시 일어서네<br/>',NULL,30855,7);
INSERT INTO stanza VALUES('K353','chorus','이 세상을 떠나 좁은 길을 가리<br/>곧 영광 오리니 충성을 다하리<br/>',NULL,30856,8);
INSERT INTO stanza VALUES('K354','1','냉랭하여 물러나서 성령을 근심케 한 나<br/>주님은 기다려 오늘 난 몸을 돌이켜<br/>미-련을 두지 않고서 주 따르기 원해<br/>',NULL,30857,1);
INSERT INTO stanza VALUES('K354','2','오늘 내 소유 전체를 영원히 주께 드리네<br/>주 받아주시리 아무것 바라지 않고<br/>아-무것 구하지 않고 주 뜻만 좇겠네<br/>',NULL,30858,2);
INSERT INTO stanza VALUES('K354','3','부끄런 나의 옛 생활 영혼을 관심 안 했네<br/>내 마음 통회해 주여 내게 기름부어<br/>구-원의 출구되도록 날 강권하소서<br/>',NULL,30859,3);
INSERT INTO stanza VALUES('K354','4','주께서 깊은 은혜로 친구와 같이 대하네<br/>날 배필 삼았네 내 의지할 것 그 생명<br/>그-의 고난 받으므로 생명을 전파해<br/>',NULL,30860,4);
INSERT INTO stanza VALUES('K355','1','이 땅의 유-혹 버리고 주 위해 살- 때에<br/>누리는 부-요한 풍성 말로 다 못하네<br/>생명과 죽음 또 만유가 다 나의 것-일세<br/>그리스도는 나의 생명 호흡 또 거철세<br/>',NULL,30861,1);
INSERT INTO stanza VALUES('K355','2','왕이 나 같은 자 택하여 보좌 참예케 했네<br/>그 택함 응하지 않은 나 참 바보 아닌가<br/>오 어떤 대-가 들어도 희생이 아-닐세<br/>거룩한 갈보리 군대에 참여만 한다면<br/>',NULL,30862,2);
INSERT INTO stanza VALUES('K355','3','부분과 완전을 바꾸는 거룩한 이- 거래<br/>만사만물- 다 구속된 우릴 위해 있네<br/>나 그리스도께 속할 때 만유 내게- 속해<br/>무한한 이 생명 누리는 놀라운 이 특권<br/>',NULL,30863,3);
INSERT INTO stanza VALUES('K356','1','영원하신 아들과 합해 믿음으로 한 영 됐네<br/>죽음으로 말미암-아 썩지 않을 생명 얻었네<br/>사랑하는 아들과 합해 은혜로 주 일부분 돼<br/>함께 주의 후사가 되고 성령의- 거처 되었네<br/>',NULL,30864,1);
INSERT INTO stanza VALUES('K356','2','변모하신 주와 연합해 그 기묘한 지체 됐네<br/>새 생명의 가지 되 -고 주와 함께 객이 되었네<br/>기름 부은 아들과 합해 성령 능력 얻었다네<br/>날이 가고 시간 가-도 변치 않고 떠나지 않네<br/>',NULL,30865,2);
INSERT INTO stanza VALUES('K356','3','버린바 된 아들과 합해 심판 저주 다 거쳤네<br/>죄에 대해 죽은 우-리 악한 음부 권세 이겼네<br/>부활하신 아들과 합해 무덤에서 벗어났네<br/>새 생명의 새 생활-로 의의 열-매- 맺겠네<br/>',NULL,30866,3);
INSERT INTO stanza VALUES('K356','4','승천하신 아들과 합해 보좌에서 다스리네<br/>주 예수와 하나 되 -어 주와 권위 함께 누리네<br/>다시 오실 아들과 합해 영광 얻고 땅에 임해<br/>영원토록 하나 되-어 주의 영-광- 나타내<br/>',NULL,30867,4);
INSERT INTO stanza VALUES('K357','1','승-리한- 주 십자가에 나 연합됐-으-니<br/>큰 환난-에도 견고-해 주 나-를- 부축-해<br/>',NULL,30868,1);
INSERT INTO stanza VALUES('K357','2','부-활 주-와 연합하여 하늘에 거-하-네<br/>주 십자-가의 영광-이 곧 나-타-나겠-네<br/>',NULL,30869,2);
INSERT INTO stanza VALUES('K357','3','승-리 주-와 연합하여 영 높이 오-르-네<br/>주 예수- 이름 선포-해 곧 흑-암- 사라-져<br/>',NULL,30870,3);
INSERT INTO stanza VALUES('K357','4','장-엄하-신 부활 주와 나 연합되-어-서<br/>주 십자-가로 승리-해 저 사-탄- 깨뜨-려<br/>',NULL,30871,4);
INSERT INTO stanza VALUES('K357','5','주- 예수-와 연합함이 곧 구원이-로-다<br/>오 흠 없-으신 어린- 양 늘 찬-양-하겠-네<br/>',NULL,30872,5);
INSERT INTO stanza VALUES('K358','1','주 안에 나 있으니- 얼마나 놀라운가<br/>주 안에 얻은 위치- 참으로 귀하-네<br/>장래 주 나타날 때 나 주를 닮으리라<br/>오늘 나 여기서도- 주같이 될 수 있네<br/>',NULL,30873,1);
INSERT INTO stanza VALUES('K358','chorus','주님과 똑같으리<br/>주 은혜 임하여 주님과 나 하나되어- 주 닮게 돼<br/>',NULL,30874,2);
INSERT INTO stanza VALUES('K358','2','주님의 죽음 안에서 나 주와 연합됐네<br/>주님의 부활 안에서 나 주와 연합됐네<br/>저주서 해방되어 주님과 함께 사네<br/>주님과 승천하여- 주님과 하나 됐네<br/>',NULL,30875,3);
INSERT INTO stanza VALUES('K358','3','주께서 이룬 업적- 그 안에 나도 서서<br/>주님의 가치 효능- 믿음으로 누리네<br/>믿음과 사랑 안에 생명 안에 하날세<br/>주의 영 늘 함께 하니 주같이 거룩게 돼<br/>',NULL,30876,4);
INSERT INTO stanza VALUES('K359','1','나는 주 예수와 하나 성령 안에 하날세<br/>주의 모든 것은 내 것 주는 내 안에 사네<br/>',NULL,30877,1);
INSERT INTO stanza VALUES('K359','chorus','주님과 하날세 주님과 하날세<br/>매일 매일 주를 누려 주는 나의 모든 것<br/>',NULL,30878,2);
INSERT INTO stanza VALUES('K359','2','안에 주를 충만케 해 주의 인성 나타내<br/>주님의 온전한 순종 내게서도 이뤄져<br/>',NULL,30879,3);
INSERT INTO stanza VALUES('K359','3','주님 안에 나도 함께 십자가에 죽었네<br/>나는 세상 대해 죽고 세상 내게 죽었네<br/>',NULL,30880,4);
INSERT INTO stanza VALUES('K359','4','주와 함께 부활하여 주와 함께 산다네<br/>나는 주님 안에 살고 주는 내 안에 사네<br/>',NULL,30881,5);
INSERT INTO stanza VALUES('K359','5','주와 함께 승천하여 함께 하늘에 있네<br/>주 안에 내 참된 생명 감취어져 있다네<br/>',NULL,30882,6);
INSERT INTO stanza VALUES('K359','6','주와 함께 보좌 앉아 주의 권위 누리네<br/>주와 함께 만물 밟고 다스리고 정복해<br/>',NULL,30883,7);
INSERT INTO stanza VALUES('K36','1','노래로 다할 수 없는 주의 큰 영광<br/>주께 영광 - 할렐루 - 야<br/>모든 형제 소리 높여 함께 찬미해<br/>주께 영광 - 할렐루야<br/>',NULL,30884,1);
INSERT INTO stanza VALUES('K36','chorus','하나님의 자녀여 크게 찬미 부르며<br/>밝고 거룩한 길로 기쁨으로 나가세<br/>주의 영광 안으로 함께 들어가겠네<br/>주께 영광 - 할렐루야<br/>',NULL,30885,2);
INSERT INTO stanza VALUES('K36','2','우리들의 기쁜 것은 말 못하겠네<br/>주께 영광 - 할렐루 - 야<br/>찬미하며 성전 안에 함께 살겠네<br/>주께 영광 - 할렐루야<br/>',NULL,30886,3);
INSERT INTO stanza VALUES('K36','3','하나님이 건축하신 성에 이르리<br/>주께 영광 - 할렐루 - 야<br/>그 곳에서 주의 영광 광채 보겠네<br/>주께 영광 - 할렐루야<br/>',NULL,30887,4);
INSERT INTO stanza VALUES('K36','4','새 노래로 주의 구속 찬미하겠네<br/>주께 영광 - 할렐루 - 야<br/>영원토록 기쁨 영광 한량없겠네<br/>주께 영광 - 할렐루야<br/>',NULL,30888,5);
INSERT INTO stanza VALUES('K360','1','오 골고다 내 주께서 죽임을 당한 곳-<br/>주 못박혀 피흘리어 날 해방하셨네<br/>',NULL,30889,1);
INSERT INTO stanza VALUES('K360','chorus','주 예수여 저 골고다 그 비밀 계시해<br/>나 주 당신과 하나 된 것 알게 하소서<br/>',NULL,30890,2);
INSERT INTO stanza VALUES('K360','2','오 골고다 내 주님과 못 박힌 곳이여-<br/>나 주님과 못 박히어 내 짐이 풀렸네<br/>',NULL,30891,3);
INSERT INTO stanza VALUES('K360','3','오 골고다 내 주님과 장사된 곳이여-<br/>나 주님의 부활 안에 참예해 살았네<br/>',NULL,30892,4);
INSERT INTO stanza VALUES('K360','4','오 골고다 사탄 무리 수치를 당한 곳-<br/>주 이름에 악령 마귀 무릎을 꿇었네<br/>',NULL,30893,5);
INSERT INTO stanza VALUES('K360','5','오 골고다 주 이름이 날 승리케 하네-<br/>내 주님의 이름 앞에 저 원수 피하네<br/>',NULL,30894,6);
INSERT INTO stanza VALUES('K360','6','오 골고다 주 찬미해 주 죽으심으로-<br/>목숨 버려 날 속량해 날 해방하셨네<br/>',NULL,30895,7);
INSERT INTO stanza VALUES('K360','7','오 골고다 나 그 의미 다 배우기 원해-<br/>나 주님과 승리하고 늘 찬송하리라<br/>',NULL,30896,8);
INSERT INTO stanza VALUES('K361','1','주여 나 주님과 죽은 비밀 나에게 계시-하소-서<br/>내 방법 내 힘- 사용않고 완전한 승리 얻도-록<br/>',NULL,30897,1);
INSERT INTO stanza VALUES('K361','2','내 맘에 빛이- 비췰- 때 주 십자가는- 나의-것<br/>주님과 죽음- 믿으-니 세상은 능력 잃게-돼<br/>',NULL,30898,2);
INSERT INTO stanza VALUES('K361','3','나 주와 함께- 못 박-혀 죄악과 자아- 이겼-네<br/>내 어찌 이 땅- 구하-며 세상의 축복 바라-리<br/>',NULL,30899,3);
INSERT INTO stanza VALUES('K361','4','나 주와 함께- 서 있-네 십자가 죽음-의 땅-에<br/>나 주와 하나- 됐으-니 주 생명 권능 내 것일세<br/>',NULL,30900,4);
INSERT INTO stanza VALUES('K361','5','주 오셔 사탄-의 역-사 죽음의 세력- 멸했-네<br/>나 주와 함께- 할 때-에 주 능력 매일 체험-해<br/>',NULL,30901,5);
INSERT INTO stanza VALUES('K361','6','십자가 의지-해야-만 승리를 얻을- 수 있-네<br/>우리도 주의- 길 가-리 주님을 만날 때까-지<br/>',NULL,30902,6);
INSERT INTO stanza VALUES('K361','7','영원한 영으-로 인-해 죽으신 뜻 더- 알게-해<br/>날 죄와 자아- 육에-서 벗어나도록 하소-서<br/>',NULL,30903,7);
INSERT INTO stanza VALUES('K361','8','주님과 함께-승리-해 왕 노릇 하기- 원하-니<br/>기꺼이 십자-가 지-고 이 영광 안에 참예-해<br/>',NULL,30904,8);
INSERT INTO stanza VALUES('K362','1','주와 함께 못 박혀서 자아 세상 떠난 나<br/>죽음 거친 주의 생명 이제 받을 수 있네<br/>주와 함께 고난 받고 죽기까지 순종해<br/>예수 그리스도 좇아 십자가의 길 가리<br/>',NULL,30905,1);
INSERT INTO stanza VALUES('K362','chorus','십자가의 길 가리 내- - 주님 가신 길<br/>주여 나로 십자가- 그 길 가게 하소서<br/>',NULL,30906,2);
INSERT INTO stanza VALUES('K362','2','주의 부활 알았으니 죽음 두렵지 않네<br/>주의 뜻을 순종하며 고난 두려워 않네<br/>주가 나의 영 안에서 부활 능력 되시니<br/>나는 기뻐 뛰며 가리 십자가의 좁은 길<br/>',NULL,30907,3);
INSERT INTO stanza VALUES('K362','3','주와 함께 죽을 때에 주와 함께 살겠네<br/>주와 함께 고난받고 주와 높이 오르리<br/>주의 이기는 자 되어 주의 상을 받으리<br/>끝날까지 충성되이 십자가의 길 가리<br/>',NULL,30908,4);
INSERT INTO stanza VALUES('K363','1','구주와 함께 못 박혔으니 구주와 함께 또 영생 얻네<br/>영광의 기약이 이르도록 시시때때로 주만 봅니다<br/>',NULL,30909,1);
INSERT INTO stanza VALUES('K363','chorus','시시때때로 날 사랑하사 시시때때로 새 생명 주네<br/>영광의 기약이 이르도록 시시때때로 주만 봅니다<br/>',NULL,30910,2);
INSERT INTO stanza VALUES('K363','2','맘 속에 시험을 받을 때와 무거운 근심이 있을 때에<br/>주께서 그것도 같이하며 시시때때로 날 도우시네<br/>',NULL,30911,3);
INSERT INTO stanza VALUES('K363','3','비참한 눈물을 흘릴 때와 애통한 맘으로 탄식할 때<br/>주께서 그것도 같이하며 시시때때로 날 위로하네<br/>',NULL,30912,4);
INSERT INTO stanza VALUES('K363','4','내 몸의 연약함 아시는 주 못 고칠 질병이 아주 없네<br/>괴로운 날이나 기쁜 때나 주 나와 함께 늘 계시도다<br/>',NULL,30913,5);
INSERT INTO stanza VALUES('K364','1','주님과 함께 죽고 사니 내가 할 일이<br/>무엇이랴 허공을 치듯 분투않고<br/>새 생명 좇아 행함으로 주님께 영광<br/>',NULL,30914,1);
INSERT INTO stanza VALUES('K364','2','머리인 주와 부활하여 거룩한 길을<br/>걷고 있네 죽은 자 죄를 벗어나니<br/>앞으로 다만 전진하여 주님께 영광<br/>',NULL,30915,2);
INSERT INTO stanza VALUES('K364','3','영원한 주와 함께 살며 영원한 주와<br/>함께 행해 죽음 안에서 거할 때에<br/>모든 묶임서 벗어나서 주님께 영광<br/>',NULL,30916,3);
INSERT INTO stanza VALUES('K364','4','내 지체 드려 주를 살며 영원히 주의<br/>노예 되리 나 은혜 아래 거할 때에<br/>죄 권능 벗고 주 따르며 주님께 영광<br/>',NULL,30917,4);
INSERT INTO stanza VALUES('K364','5','주 의지하며 자랄 때에 성결의 열매<br/>절로 맺혀 하나님 갈망 만족게 해<br/>하나님 뜻을 좇아 행해 주님께 영광<br/>',NULL,30918,5);
INSERT INTO stanza VALUES('K365','1','주와 함께 못 박힌- 나 십자가-로 해방돼<br/>주와 함께 부활했네 주 내 안-에 사시네<br/>',NULL,30919,1);
INSERT INTO stanza VALUES('K365','chorus','주와 함께 죽-었으니 놀-라운 안식 아닌가!<br/>세상 자아 죄 벗었네 주- 이제 날- 다스리네<br/>',NULL,30920,2);
INSERT INTO stanza VALUES('K365','2','영원부터 감췬 비-밀 믿음으-로 알게 돼<br/>내주하는 그리스도 나의 영-광의 소망<br/>',NULL,30921,3);
INSERT INTO stanza VALUES('K365','3','한 알의 밀 죽을 때-에 많은 밀-알 거두네<br/>접붙일 때 바뀌어져 쓴 열매-가 달게 돼<br/>',NULL,30922,4);
INSERT INTO stanza VALUES('K366','1','베들레헴에 주님 태어나셨지만-<br/>주 네 안에 나셔야 네 혼 구원되리<br/>골고다의 십자가 네 혼 못 구하리<br/>네 안의 십자가만 널 온전케 하리<br/>',NULL,30923,1);
INSERT INTO stanza VALUES('K366','chorus','네 맘에 받아들이라 그리스도의 십자가<br/>네 자아 대하여 죽-고 주 대하여 살도록<br/>',NULL,30924,2);
INSERT INTO stanza VALUES('K366','2','네가 사랑하는 것 그것이 네가 돼-<br/>주 사랑하려느냐 흙 사랑하려느냐<br/>주 채우면 주 되고 흙 채우면 흙 돼<br/>네 자신 비울 때에 주 만유 채우리<br/>',NULL,30925,3);
INSERT INTO stanza VALUES('K366','3','주 아는 가까운 길 이는 사랑일세-<br/>지식을 따를 때엔 늘 헤매게 되네<br/>주 사랑 네 맘 속에 충만케 될 때에<br/>세상 다 물러가고 거룩게 되리라<br/>',NULL,30926,4);
INSERT INTO stanza VALUES('K367','1','오 주는 갈보-리 에-서 안식을 이루셨지만<br/>또 다른 모-양-으-로- 와 오늘도 역사하시네<br/>',NULL,30927,1);
INSERT INTO stanza VALUES('K367','2','지금도 주는- 말씀-해 비추고 인도하시네<br/>성령과 주-는- 한- 흐-름 주 외의 것 다 씻어 내<br/>',NULL,30928,2);
INSERT INTO stanza VALUES('K367','3','주님의 능력- 주 역-사 영 안에 계속 흐르네<br/>자유케 하-며-강-하게 해 안위하고 또 다스려<br/>',NULL,30929,3);
INSERT INTO stanza VALUES('K367','4','성령이 올 때- 주 오-셔 주님과 성령 하나니<br/>성령의 거-처-는- 바-로 주님의 거처이실세<br/>',NULL,30930,4);
INSERT INTO stanza VALUES('K367','5','내 마음 속에- 이루-네 주의 뜻 주님의 갈망<br/>아버지 뜻-을- 이- 땅-에 온전히 다 이루시네<br/>',NULL,30931,5);
INSERT INTO stanza VALUES('K367','6','성령께 순종-하는- 것 주님께 순종함일세<br/>성령의 충-만- 받-음-이 곧 주를 충만함일세<br/>',NULL,30932,6);
INSERT INTO stanza VALUES('K367','7','하늘 보좌에- 있는- 주 또한 이 땅에 계시네<br/>우리를 버-리-지- 않-고 주 우리 맘에 사시네<br/>',NULL,30933,7);
INSERT INTO stanza VALUES('K368','1','온 세상 성부 모를 때 예수로 땅에 오셨네<br/>우리가 무지하여도 주 알 때 성부도 아네<br/>',NULL,30934,1);
INSERT INTO stanza VALUES('K368','2','예수가 세상 계실 때 그를 아는 자 적었네<br/>주 앞에 밀려 왔으나 주를 만지지 못했네<br/>',NULL,30935,2);
INSERT INTO stanza VALUES('K368','3','이전에 성부 오실 때 예수 안에서 오시듯<br/>지금 주 영 안에 왔네 영 안에서만 알겠네<br/>',NULL,30936,3);
INSERT INTO stanza VALUES('K368','4','지금 주는 육신 입고 수고하는 분 아니네<br/>그는 내 영 안에 계셔 시시때때로 공급해<br/>',NULL,30937,4);
INSERT INTO stanza VALUES('K368','5','이전엔 성부였으나 지금은 성령이시네<br/>성령은 또 다른 형태 당신의 두 번째 상태<br/>',NULL,30938,5);
INSERT INTO stanza VALUES('K368','6','오늘 이 성령 알므로 주 영광 알게 되었네<br/>당신의 생명과 성품 기묘한 본질 알게 돼<br/>',NULL,30939,6);
INSERT INTO stanza VALUES('K368','7','주는 참 내게 실재니 항상 그 이름 찬미해<br/>세상의 친절과 인정 주님과 바꿀 수 없네<br/>',NULL,30940,7);
INSERT INTO stanza VALUES('K369','1','나 이-전에 주 예-수를- 육체-를 따라 알-았네<br/>주 그-를 알게 하-시려 성령-으로- 내 영에 왔네<br/>',NULL,30941,1);
INSERT INTO stanza VALUES('K369','2','육신- 입었던 나-의 주- 이제-는 보혜사- 성령<br/>밖의- 동거함보-다도 내 안-에 연-합 이-뤘네<br/>',NULL,30942,2);
INSERT INTO stanza VALUES('K369','3','성령-으로 내 영-에 와- 주님- 자신을 계-시해<br/>한량- 없는 성령-으로 주 실-제 알-게 된-다네<br/>',NULL,30943,3);
INSERT INTO stanza VALUES('K369','4','주 육-신 입고 사-실 때- 제자-들이 다 보-았던<br/>주 예-수의 생명- 실재 영 안-에 나-도 누-리네<br/>',NULL,30944,4);
INSERT INTO stanza VALUES('K369','5','내 영- 안에 주의- 성령- 참 놀-라운 실재-일세<br/>만지-지는 못하-지만 확실-하고-도 신-실해<br/>',NULL,30945,5);
INSERT INTO stanza VALUES('K369','6','내 깊-은 데 계신- 성령- 주님- 자신 공급-하네<br/>의와- 성결 구속- 지혜 그 모-든 풍-성 공-급해<br/>',NULL,30946,6);
INSERT INTO stanza VALUES('K37','1','아버지여 주로 인 - 해 당신 앞에 나아 - 와<br/>약속된 복 얻기 위 - 해 자녀들 모입니 - 다<br/>주의 보 - 혈 나를 씻 - 어 은혜 얻게 하시고<br/>그 영 우릴 가르치 - 니 아바 - 아버지라 부르 - 네<br/>',NULL,30947,1);
INSERT INTO stanza VALUES('K37','2','탕자처럼 당신 떠 - 나 방황했던 우리 - 를<br/>죄보다 더 큰 은혜 - 로 구출하신 아버 - 지<br/>구원의 - 옷 입히시 - 고 잔치 누리게 하니<br/>광대하신 은혜 인 - 해 함께 - 즐 - 거움 누리 - 네<br/>',NULL,30948,2);
INSERT INTO stanza VALUES('K37','3','사랑의 입맞춤으 - 로 사하심 나타내 - 고<br/>살진 송아지를 잡 - 아 영원한 하나 이 - 룬<br/>아버지 - 의 음성 들 - 려 “기뻐하고 즐기자”<br/>이 내 아들 죽었다 - 가 다시 - 살 - 아 - 났도 - 다<br/>',NULL,30949,3);
INSERT INTO stanza VALUES('K37','4','놀라우신 사랑 인 - 해 아버지를 찬미 - 해<br/>우리 인해 천사들 - 도 큰 은혜에 놀라 - 네<br/>우린 다 - 시 보좌 앞 - 에 큰 사랑 되새기리<br/>풍성하신 아버지 사랑 놀라 - 우 - 신 - 용서 - 를<br/>',NULL,30950,4);
INSERT INTO stanza VALUES('K370','1','주 예수 이 땅 계-실 때 주 따르던- 많은 사람<br/>주 아는 것 같았-지만 오 그들은 주님을 몰랐네<br/>',NULL,30951,1);
INSERT INTO stanza VALUES('K370','2','주님의 음성 듣-고도 그 모습 능-력 보고도<br/>주 둘러싼 그 무 -리들 주님-이 누군지 몰랐네<br/>',NULL,30952,2);
INSERT INTO stanza VALUES('K370','3','그들처럼 우리-들도 주님을 육-체로 봤네<br/>주님을 안다 했 -지만 온전-히 알-지 못했네<br/>',NULL,30953,3);
INSERT INTO stanza VALUES('K370','4','또 다른 보혜사-로 온 주님은 지-금 성-령<br/>날 성전 삼고 내 안에 와 내 맘-에 주-를 나타내<br/>',NULL,30954,4);
INSERT INTO stanza VALUES('K370','5','날 성령으로 채-우사 내 혼을 다- 채우소서<br/>주 생기 불어 넣 -으사 내 전-체 새-로와지게<br/>',NULL,30955,5);
INSERT INTO stanza VALUES('K370','6','눈으로 보지 못-해도 귀로도 듣-지 못해도<br/>성령으로 주 내 - 안에 더욱-더 실-제 되시네<br/>',NULL,30956,6);
INSERT INTO stanza VALUES('K370','7','우리에게 주님- 자신 성령으로- 나타내니<br/>이보다 큰 실재- 없네 더 참-된 실-제 없다네<br/>',NULL,30957,7);
INSERT INTO stanza VALUES('K370','8','오 주여 내 각 부-분에 흐르고 흘-러 넘치어<br/>내 전체 주의 성 -분 돼 영광-의 빛- 비추소서<br/>',NULL,30958,8);
INSERT INTO stanza VALUES('K370','9','이 생명 안에 누-리네 하늘과 땅-의 만남을<br/>오 달콤함 혼 적 -시니 마음-껏 주-만 찬양해<br/>',NULL,30959,9);
INSERT INTO stanza VALUES('K371','1','오 주님 지-금 그 영일세 내 생명 되어 살게 해<br/>그 풍성 내게 주시니 아 거-룩한- 영광-일세<br/>',NULL,30960,1);
INSERT INTO stanza VALUES('K371','2','오 주님 지-금 그 영일세 그 능력 나를 해방해<br/>생명률 안에 살 때에 나 자-유롭-고 강-해져<br/>',NULL,30961,2);
INSERT INTO stanza VALUES('K371','3','오 주님 지-금 그 영일세 날 변케 하며 밝게 해<br/>날 주의 형상 만들어 주 영-광 나-타내-게 해<br/>',NULL,30962,3);
INSERT INTO stanza VALUES('K371','4','오 주님 지-금 그 영일세 내 영 안에서 거하네<br/>두 영이 상합하여서 주 내- 영 통-해 행-동해<br/>',NULL,30963,4);
INSERT INTO stanza VALUES('K371','5','주여 날 훈-련하-소서 내 영의 움직임따라<br/>주 영 안에서 살면서 늘 실-제 나-타내-도록<br/>',NULL,30964,5);
INSERT INTO stanza VALUES('K372','1','주는 하나님 중심 또한 그-의 전체니<br/>영원서- 영원까지 하나님- 사랑 기쁨<br/>',NULL,30965,1);
INSERT INTO stanza VALUES('K372','2','주는 하나님 체현 그분 충-만 거하네<br/>그의 존-귀 신성은 비교할- 데 없겠네<br/>',NULL,30966,2);
INSERT INTO stanza VALUES('K372','3','하나님의 계획은 만유에- 주 충만해<br/>천지만-물 인하여 영광 얻-는 것일세<br/>',NULL,30967,3);
INSERT INTO stanza VALUES('K372','4','모든 것이 주 위해 주에게-서 났으며<br/>주를 인-해 서 있네 주가 축-과 둘렐세<br/>',NULL,30968,4);
INSERT INTO stanza VALUES('K372','5','주로 인해 만유가 다시 교-통 회복해<br/>효능 있-는 보혈로 하나님-과 화목돼<br/>',NULL,30969,5);
INSERT INTO stanza VALUES('K372','6','모든 것의 시작과 교회 머-리 되신 주<br/>교회 생-명 되신 주 죽음에-서 부활해<br/>',NULL,30970,6);
INSERT INTO stanza VALUES('K372','7','주가 천국 왕 되어 모든 권-세 잡았네<br/>주가 다-스리시니 천지만-물 복종해<br/>',NULL,30971,7);
INSERT INTO stanza VALUES('K372','8','새 하늘 새 땅에서 주가 중-심 되시네<br/>무궁하-게 영원히 신성 인-성 나타내<br/>',NULL,30972,8);
INSERT INTO stanza VALUES('K372','9','그가 으뜸 되심이 하나님-의 뜻일세<br/>만유 포-함하신 주 나의 달-콤한 누림<br/>',NULL,30973,9);
INSERT INTO stanza VALUES('K373','1','그리스도는- 하나님의 참 간증 본질 또 말씀<br/>하나님 영-광- 나-타-내 그 성품 보여 주시네<br/>',NULL,30974,1);
INSERT INTO stanza VALUES('K373','2','율법보다 승한 그리스도 하나님 완전한 간증<br/>율법은 의-문-으-로-만 하나님 설명한다네<br/>',NULL,30975,2);
INSERT INTO stanza VALUES('K373','3','신격의 충만- 주 안-에 내용과 성분 되셨네<br/>참 하나님-의- 체현인- 주 그의 거처 그의 그릇<br/>',NULL,30976,3);
INSERT INTO stanza VALUES('K373','4','하나님 영광- 그 형-상 주 안에 전부 나타나<br/>하나님 뜻-과- 길- 모-두 주 안에서 보여 주네<br/>',NULL,30977,4);
INSERT INTO stanza VALUES('K373','5','그리스도 지금 내 영-에 거하며 내 분깃 되네<br/>신성의 모-든- 소-유-를 영 안에 맘껏 누리네<br/>',NULL,30978,5);
INSERT INTO stanza VALUES('K374','1','그리스도는 만유의 실재 그만이 유일하신 실젤세<br/>그분 떠나선 만유 헛되네 하나님 찾을 수도 없-다네<br/>',NULL,30979,1);
INSERT INTO stanza VALUES('K374','2','모든 형상과 모든 예표들 사람의 필요는 다 그림자<br/>내 모든 것 된 그리스도와 하나님 표명하는 것-일세<br/>',NULL,30980,2);
INSERT INTO stanza VALUES('K374','3','그리스도가 만물 가운데 충만치 않을 때 다 공허해<br/>모든 것 얻고 누릴지라도 그리스도 없으면 공-허해<br/>',NULL,30981,3);
INSERT INTO stanza VALUES('K374','4','참 하나님과 참된 주이신 그리스도는 나의 참된 빛<br/>참 사물 참 옷 참된 양 -식 참 생명 생수 또한 참-된 맛<br/>',NULL,30982,4);
INSERT INTO stanza VALUES('K374','5','모든 신학과 모든 교리에 그리스도가 실재 돼야 해<br/>그리스도 없는 성경 지식들 공허한 의문밖에 안-되네<br/>',NULL,30983,5);
INSERT INTO stanza VALUES('K374','6','시간과 공간 모든 실재는 오로지 그리스도뿐일세<br/>영원한 실재 변치 않으리 그만이 유일하신 실-젤세<br/>',NULL,30984,6);
INSERT INTO stanza VALUES('K375','1','주 이미 나-의 실-제니 믿음 안에서 누-리리<br/>이 땅의 무-엇 보-다도 참되신 영광 실-젤세<br/>친밀하고 사랑스런 주 내게 가장 가깝네<br/>',NULL,30985,1);
INSERT INTO stanza VALUES('K375','2','내 온전함-이 되-신 주 내 갈망 순결케- 했네<br/>거룩한 사-랑 불-타는 그 복된 이상 난- 봤네<br/>나의 성품 높이 올려 주 풍성으로 적시네<br/>',NULL,30986,2);
INSERT INTO stanza VALUES('K375','3','언제나 내-게 가-깝고 사랑스런 은혜-의 주<br/>주 얼굴 빛- 더 빛-나고 말씀 더 능력 있-도록<br/>사랑 안에 날 변케 해 긍휼과 은혜 안에서<br/>',NULL,30987,3);
INSERT INTO stanza VALUES('K376','1','은혜에 대한 참된 정의는 아들 안에 주신 하나님 자신<br/>은혜는 어떤 사물 아니요 내 분깃 되신 하나님 자신<br/>',NULL,30988,1);
INSERT INTO stanza VALUES('K376','2','하나님 육신 되어 오심은 사람이 그를 얻게 함이니<br/>주 말미암아 얻은 은혜는 내 안에 오신 하나님 자신<br/>',NULL,30989,2);
INSERT INTO stanza VALUES('K376','3','바울의 은혜 그리스도뿐 다른 것 모두 배설물였네<br/>그는 이 은혜 체험함으로 그 누구보다 더 수고했네<br/>',NULL,30990,3);
INSERT INTO stanza VALUES('K376','4','내 안에 있는 능력의 주만 의지할 만한 나의 참 은혜<br/>늘 족한 은혜 능력 주시며 하나님 목적 이루게 하네<br/>',NULL,30991,4);
INSERT INTO stanza VALUES('K376','5','이 은혜는 곧 주 그리스도 내 모든 것 돼 날 돌보시네<br/>이 참된 은혜 더 알기 원해 은혜로 누림 더하기 원해<br/>',NULL,30992,5);
INSERT INTO stanza VALUES('K377','1','영광 영광 주는 내 생명<br/>영광 성령 나를 인도해<br/>연약함이 변해 능력이 되네<br/>흑암 변해 광명 된다네<br/>',NULL,30993,1);
INSERT INTO stanza VALUES('K377','2','영광 주로 인해 태어나<br/>영광 성령 좇아 행하네<br/>모든 실패 변해 성공이 되네<br/>탄식 변해 찬송 된다네<br/>',NULL,30994,2);
INSERT INTO stanza VALUES('K378','1','오 놀라운 참 생명과 평안<br/>주 그리스도가 내 안에 사네<br/>내 주와 함께 십자가에 못 박힌 영광의 묘한 구원<br/>이제는 나 사는 것 아니요 내 안에<br/>주 그리스도 내 안에서 살고 계시네<br/>오 지금은 내 안에서 그리스도 살고 계시네<br/>',NULL,30995,1);
INSERT INTO stanza VALUES('K378','2','오 놀라운 참 기쁨과 안식<br/>주 그리스도의 형상 이루네<br/>그의 생명과 그의 성품 내 온 사람 전체에 채워져<br/>내 이전 모든 것 다 끝나고 지금은<br/>주 그리스도 그의 성분 내 것이 됐네<br/>내 모든 것 다 끝났네 주님만이 내 성분 됐네<br/>',NULL,30996,2);
INSERT INTO stanza VALUES('K378','3','오 놀라운 큰 영광의 자랑<br/>주 그리스도만 항상 나타내<br/>어떠한 때나 죽든 살든 내 주를 부끄러워 안 하네<br/>어떠한 일이나 어떤 환경 만나도<br/>다 나로 인해 그리스도 나타내게 해<br/>어떤 환경 어떤 일도 그리스도 나타내게 해<br/>',NULL,30997,3);
INSERT INTO stanza VALUES('K378','4','오 놀라운 큰 축복과 결실<br/>내 사는 이 생활 주 사는 생활<br/>그의 뜻을 난 즐겨 하고 그의 영광을 난 나타나네<br/>무엇이 귀한가 무얼 필요로하나<br/>주 그리스도 오직 나의 참된 목푤세<br/>참 귀하고 참 필요한 그리스도 내 목표일세<br/>',NULL,30998,4);
INSERT INTO stanza VALUES('K379','1','어떤 능력과 어떤 힘인가<br/>주 그리스도는 다시 사셨네<br/>하늘에 올라 하나님의 보좌의 우편에 앉게 했네<br/>나 위해 만유의 머리 되신 큰 능력<br/>다 교회 위해 모든 만유 복종케 했네<br/>그리스도 온 만유의 머리 되사 복종케 했네<br/>',NULL,30999,1);
INSERT INTO stanza VALUES('K379','2','어떤 사실 어떤 비밀인가<br/>나 그리스도의 몸의 지첼세<br/>모든 성도와 연합하여 새 사람 안에서 건축되네<br/>우리는 승천한 머리와 연합되어<br/>다 그의 한 몸 이루어서 주 인해 사네<br/>승천하신 한 머리의 한 몸 이뤄 주 인해 사네<br/>',NULL,31000,2);
INSERT INTO stanza VALUES('K379','3','아 얼마나 높고 또 깊은가<br/>얼마나 길고도 넓고 넓은가<br/>그 도량 측량할 길 없네 무한한 무량한 그리스도<br/>한없이 넓어서 그의 둘레 못 찾네<br/>주 그리스도 우리 생각 초월하시네<br/>주 어떠함 모든 소유 다 교회를 위한 것일세<br/>',NULL,31001,3);
INSERT INTO stanza VALUES('K38','1','아버지께 찬송하 - 며 겸손하게 경배해<br/>당신이 곧 축복이 - 심 우린 이제 알았네<br/>존귀하신 예수 이름 인해 이런 권세 - 얻었네<br/>우리에 - 게 생명 있음을 그 영 친히 - 증거해<br/>',NULL,31002,1);
INSERT INTO stanza VALUES('K38','2','우릴 당신 아들 되 - 어 생명 공급 얻도록<br/>창세 전에 예정했 - 네 그리스도 안에서<br/>아버지의 놀라운 사 - 랑 우릴 은혜 - 받게 해<br/>죄인들 - 을 당신 성품에 참예하게 - 하셨네<br/>',NULL,31003,2);
INSERT INTO stanza VALUES('K38','3','아담 안의 우리 본 - 성 심히 부패했지만<br/>영원한 뜻 안에 우 - 릴 당신께로 돌이켜<br/>구주 예수 우릴 - 구속해 거듭나게 - 하셨네<br/>천부 구주와 교회 하나니 참말 기이한 은혤세<br/>',NULL,31004,3);
INSERT INTO stanza VALUES('K38','4','모든 환경 변하여 - 도 환란 시험 있어도<br/>당신 사랑 변치 않 - 고 우릴 항상 이끄네<br/>그날 주의 속량된 자녀들 보좌 앞에 - 모여서<br/>구원받 - 은 이야기 - 들 나누며 찬 - 송하리<br/>',NULL,31005,4);
INSERT INTO stanza VALUES('K380','1','영광 영광 영광 생명 주는 영광의 생명<br/>성결 공의 양선 광명 얼마나 풍성한가<br/>신성 영광 모든 풍성 주 안에 감춰 있네<br/>그는 지금 내 생명돼 내게 공급하시네<br/>',NULL,31006,1);
INSERT INTO stanza VALUES('K380','2','신성 신성 신성 생명 주는 신성한 생명<br/>그는 이미 성령 되어 내 안에서 거하네<br/>관유처럼 가르치며 빛 비추며 역사해<br/>충만하게 적셔주며 내게 능력 공급해<br/>',NULL,31007,2);
INSERT INTO stanza VALUES('K380','3','능력 능력 능력 생명 주는 능력의 생명<br/>나를 함께 못 박게 해 죄로부터 해방해<br/>주와 함께 살리시고 주를 살게 하시네<br/>부활 능력 공급하여 나로 체험케 하네<br/>',NULL,31008,3);
INSERT INTO stanza VALUES('K380','4','승리 승리 승리 생명 주는 승리의 생명<br/>십자가에 승리한 주 나를 자유케 하네<br/>사탄 마귀 세상 인정 다 이기신 주 예수<br/>나의 승리 생명 되어 내 안에서 공급해<br/>',NULL,31009,4);
INSERT INTO stanza VALUES('K380','5','영광 신성 능력 승리 주가 모든 것 되네<br/>날 자라고 성숙케 해 이기고 강건케 해<br/>나의 본질 변케 하여 주를 닮게 하시네<br/>들림 받는 그날까지 내게 공급하시네<br/>',NULL,31010,5);
INSERT INTO stanza VALUES('K381','1','내 생명된 주님 내 안에 사셔<br/>하나님의 모든 충만 주시네<br/>주의 신성으로 날 거룩게 해<br/>주의 부활 내게 승리주시네<br/>',NULL,31011,1);
INSERT INTO stanza VALUES('K381','2','주의 생명 흘러 나를 비추며<br/>영 안에서 주와 교통케 하네<br/>나의 모든 필요 공급하시며<br/>나로 주님 안에 서게 하시네<br/>',NULL,31012,2);
INSERT INTO stanza VALUES('K381','3','주의 성령 나를 충만케 하여<br/>내 온 영과 혼을 흠뻑 적시네<br/>내 각 부분 모두 변케 하시네<br/>주의 형상으로 화할 때까지<br/>',NULL,31013,3);
INSERT INTO stanza VALUES('K381','4','넘치는 주 생명 값없이 흘러<br/>날 새롭게 하네 능력 주시네<br/>생명으로 사망 삼켜 버리니<br/>모든 묶임 벗고 다만 찬송해<br/>',NULL,31014,4);
INSERT INTO stanza VALUES('K381','5','주의 맘의 갈망 다 이루도록<br/>내 모든 것 주께 다 바칩니다<br/>자신 고치려던 노력 버리니<br/>내 안에 주 홀로 역사하소서<br/>',NULL,31015,5);
INSERT INTO stanza VALUES('K381','6','헛된 노력 모두 떨쳐 버리니<br/>주의 생명으로 날 변케 하사<br/>지체들과 함께 건축하소서<br/>주님의 완전한 표현 되도록<br/>',NULL,31016,6);
INSERT INTO stanza VALUES('K382','1','영광스런 사랑의 주 하나님의 영광 나타내<br/>영원 무궁한 한계 떠나서 시간에 제한되셨네<br/>',NULL,31017,1);
INSERT INTO stanza VALUES('K382','chorus','크신 영광 주 육신 입으사 기묘한 풍성 되셨네<br/>거룩한 중 거룩한 사람 내 영 안에 들어왔네<br/>',NULL,31018,2);
INSERT INTO stanza VALUES('K382','2','하나님의 충만인 주 하나님의 영광 나타내<br/>전엔 육신 돼 구속 이루고 지금은 내 영에 계셔<br/>',NULL,31019,3);
INSERT INTO stanza VALUES('K382','3','아버지는 아들 안에 아들 풍성 영 안에 있네<br/>그 영 내 안에 안식하시며 내 생활의 실재 되네<br/>',NULL,31020,4);
INSERT INTO stanza VALUES('K382','4','주의 영은 생명으로 내게 살아 있는 말씀 돼<br/>말씀 받을 때 그 영 접촉해 내 생명 공급 되시네<br/>',NULL,31021,5);
INSERT INTO stanza VALUES('K382','5','영 안에 주 바라볼 때 거울처럼 영광 반사해<br/>나는 변화해 주의 형상 돼 주 나를 통해 나타나<br/>',NULL,31022,6);
INSERT INTO stanza VALUES('K382','6','이와 같은 생활만이 성결함을 이룰 수 있네<br/>이런 생활만 승리 이루네 영광의 생명 나타내<br/>',NULL,31023,7);
INSERT INTO stanza VALUES('K382','7','이로 인해 주의 영이 모든 지체 충만케 하니<br/>어느 곳이나 주님 뿐일세 온 성도 주의 거처 돼<br/>',NULL,31024,8);
INSERT INTO stanza VALUES('K383','1','영광 안에 계신 주 하나님 사람<br/>성결 공의 지혜와 빛이 충만해<br/>나로 주의 성품에 참예케 하려<br/>나를 위해 죽으사- 구원 이뤘네<br/>',NULL,31025,1);
INSERT INTO stanza VALUES('K383','2','영광 안에 계신 주 승리의 왕이<br/>흑암 권세 부수고 사탄 깨뜨려<br/>음부 뚫고 권세들 초월하셨네<br/>나도 주와 올라가- 승리 선포해<br/>',NULL,31026,2);
INSERT INTO stanza VALUES('K383','3','영광 안에 계신 주 그는 내 생명<br/>내 안에서 거하며 나를 다스려<br/>주의 거룩한 형상 내 안에 이뤄<br/>그의 영광 생명을- 표현하도록<br/>',NULL,31027,3);
INSERT INTO stanza VALUES('K383','4','영광 안에 계신 주 그는 내 소망<br/>잠시 후에 다시 와 날 인도하리<br/>영광 능력으로 날 변형시키사<br/>주의 영광 형상으로 변케 하시리<br/>',NULL,31028,4);
INSERT INTO stanza VALUES('K384','1','하나의 강과 한 나무 이는 곧 낙원의 특색<br/>음식과 생수 공급해 사람을 살게 해<br/>',NULL,31029,1);
INSERT INTO stanza VALUES('K384','chorus','사람의 양식 되시려고 하나님 예수 안에 왔네<br/>지금은 주님 그 영되어 무한한 공급해<br/>',NULL,31030,2);
INSERT INTO stanza VALUES('K384','2','나무는 생명 양식 된 영광의 그리스도니<br/>하나님 풍성 누릴 때 만족함 얻게 돼<br/>',NULL,31031,3);
INSERT INTO stanza VALUES('K384','3','강물은 우리 영 안에 공급이 되려 오신 영<br/>우리가 풍성 채울 때 거룩함 이뤄져<br/>',NULL,31032,4);
INSERT INTO stanza VALUES('K384','4','내 생명 되신 주 예수 그 영 돼 내 영에 사네<br/>하나님과 나 연합해 주 형상 나타내<br/>',NULL,31033,5);
INSERT INTO stanza VALUES('K384','5','나 주를 높이기 원해 무한한 영 순종하리<br/>하나님 영광 나타내 은혜로 영원히<br/>',NULL,31034,6);
INSERT INTO stanza VALUES('K385','1','주는 하늘에서 내려온 만나요<br/>날 만족게 하는 내 음-식 되-시네-<br/>',NULL,31035,1);
INSERT INTO stanza VALUES('K385','2','생수가 흐르는 주는 깨진 반석<br/>나 마실 때마다 목마-름 사-라져-<br/>',NULL,31036,2);
INSERT INTO stanza VALUES('K385','3','배고파 목말라 주께로 나오니<br/>주 자신 먹이사 날 축-여 주-소서-<br/>',NULL,31037,3);
INSERT INTO stanza VALUES('K385','4','주 먹고 마시며 주 흡수하겠네<br/>주 생명 누리며 성령-을 마-시리-<br/>',NULL,31038,4);
INSERT INTO stanza VALUES('K385','5','이렇게 채울 때 공허함 사라져<br/>주 먹고 마실 때 생활-의 힘-얻네-<br/>',NULL,31039,5);
INSERT INTO stanza VALUES('K386','1','예수는 나의 힘이요 내 생명 되시니<br/>구주 예수 떠나가면 죄중에 빠-지리<br/>눈물이 앞을 가리고 내 맘에 근심 쌓일 때<br/>위로할 이 누구시뇨 주 예수<br/>',NULL,31040,1);
INSERT INTO stanza VALUES('K386','2','예수는 나의 힘이요 내 친구 되시니<br/>그 은혜를 간구하면 풍성히 받-겠네<br/>햇빛과 비를 주시니 추수할 곡식 많도다<br/>기쁜 열매 주신 이는 주 예수<br/>',NULL,31041,2);
INSERT INTO stanza VALUES('K386','3','예수는 나의 힘이요 내 기쁨 되시니<br/>그 명령을 준행하여 늘 충성하-겠네<br/>주야로 보호하시며 바른 길 가게 하시니<br/>의지하고 따라갈 이 주 예수<br/>',NULL,31042,3);
INSERT INTO stanza VALUES('K386','4','예수는 나의 힘이요 내 소망 되시니<br/>이 세상의 끝날까지 나 주를 의-지해<br/>한없는 복을 주시고 영원한 기쁨 주시니<br/>나의 생명 나의 기쁨 주 예수<br/>',NULL,31043,4);
INSERT INTO stanza VALUES('K387','1','아무리 죄가 깊어도 아무리 길이 험해도<br/>어려운 환경 속에도 부족함 없-는 주<br/>',NULL,31044,1);
INSERT INTO stanza VALUES('K387','2','큰 시험 작은 시험에 수많은 근심 쌓일 때<br/>내가 혹 실족하여도 부족함 없-는 주<br/>',NULL,31045,2);
INSERT INTO stanza VALUES('K387','3','땅의 것 달콤할 때에 모든 것 순조로울 때<br/>안락이 구름 되어도 부족함 없-는 주<br/>',NULL,31046,3);
INSERT INTO stanza VALUES('K387','4','근심의 병이 들 때에 실망과 낙심뿐일 때<br/>맘과 영 마비되어도 부족함 없-는 주<br/>',NULL,31047,4);
INSERT INTO stanza VALUES('K387','5','내 환경 어떠하든지 주가 날 붙들어주사<br/>부족함 없는 당신을 체험케 하-시네<br/>',NULL,31048,5);
INSERT INTO stanza VALUES('K388','1','나는 우주의 보화 얻었네 마음 속의 기쁨 외쳐<br/>그리스도 얻게 되었네 아 어떤 분인가!<br/>',NULL,31049,1);
INSERT INTO stanza VALUES('K388','2','나의 주는 하나님 어린 양 나의 죄 담당하셨네<br/>하나님의 공의의 햇빛 치료하는 광선<br/>',NULL,31050,2);
INSERT INTO stanza VALUES('K388','3','나의 주는 생명의 나물세 낙원 안에 심겨 있네<br/>그의 과실 나의 식물 돼 참 풍성 공급해<br/>',NULL,31051,3);
INSERT INTO stanza VALUES('K388','4','나의 주는 생명의 강일세 내 안에서 흘러나네<br/>영원토록 흐르고 흘러 목마름 없게 해<br/>',NULL,31052,4);
INSERT INTO stanza VALUES('K388','5','나의 주는 내 제사장일세 하나님 앞에 서 계셔<br/>계시가 충만한 선지자 권위의 왕일세<br/>',NULL,31053,5);
INSERT INTO stanza VALUES('K388','6','나의 주는 구주 중보 의사 나의 목자 모사 머리<br/>내 아버지 형님 하나님 선생 애인 친구<br/>',NULL,31054,6);
INSERT INTO stanza VALUES('K388','7','나의 주는 생명 능력 지혜 나의 공의 성결 구속<br/>평안 기쁨 소망과 안식 영광 또 빛과 길<br/>',NULL,31055,7);
INSERT INTO stanza VALUES('K388','8','나의 주는 만유 충만하니 어찌 말로 표현하리<br/>모든 것의 모든 것 된 주 처음 또 나중 돼<br/>',NULL,31056,8);
INSERT INTO stanza VALUES('K388','9','이런 보화 얻-은 나의 맘 소리 높여 외치겠네<br/>내가 얻은 주 그리스도 아 어떤 분인가!<br/>',NULL,31057,9);
INSERT INTO stanza VALUES('K388','10','나의 주는 깨진 반석일세 생수의 강 흘러나네<br/>내 안에서 생명 샘 되어 내 갈증 해결해<br/>',NULL,31058,10);
INSERT INTO stanza VALUES('K388','11','나의 주는 생명과 빛 또 길 나의 위로 안식 강함<br/>나의 자랑 영광 풍성 또 평강 기쁨 소망<br/>',NULL,31059,11);
INSERT INTO stanza VALUES('K388','12','나의 주는 지혜와 공의요 나의 성결 나의 실재<br/>나의 구속 나의 능력돼 나의 해방 승리<br/>',NULL,31060,12);
INSERT INTO stanza VALUES('K388','13','나의 주는 구원의 원수요 길을 여신 선-주자<br/>나의 호위 안내 보호자 인도자 보혜사<br/>',NULL,31061,13);
INSERT INTO stanza VALUES('K388','14','나의 주는 영원한 거처요 풍성하고 좋-은 땅<br/>나의 요새 망대 피난처 내 영원한 목적<br/>',NULL,31062,14);
INSERT INTO stanza VALUES('K388','15','나의 주는 나의 소망 의지 나의 기쁨 만족일세<br/>나의 상과 나의 참 목표 내 공급 내 도움<br/>',NULL,31063,15);
INSERT INTO stanza VALUES('K388','16','나의 주는 비옥한 땅일세 나의 봄비 나의 이슬<br/>그는 나의 참 포도나무 나 그 안에 거해<br/>',NULL,31064,16);
INSERT INTO stanza VALUES('K388','17','나의 주는 나의 절기 월삭 나의 참된 안-식일<br/>나의 새벽 나의 대낮과 내 금세 내 영세<br/>',NULL,31065,17);
INSERT INTO stanza VALUES('K389','1','세상 복 없을 때 주 나의 것-<br/>세상 정 끊길 때에 주는 나의 것<br/>이 흑암 광야에 안식할 데 없네<br/>나 의지할 이 오직 주는 나의 것<br/>',NULL,31066,1);
INSERT INTO stanza VALUES('K389','2','주 함께 있겠네 주 나의 것<br/>주 함께 살기 원해 주는 나의 것-<br/>이 세상 오락은 일시적 속임수<br/>내 맘에서 떠나라 주는 나의 것<br/>',NULL,31067,2);
INSERT INTO stanza VALUES('K389','3','가거라 세상 꿈 주 나의 것-<br/>나 지금 꿈을 깼네 주는 나의 것<br/>내 이전 생각은 날 고통케 했네<br/>주님만 나의 만족 주는 나의 것<br/>',NULL,31068,3);
INSERT INTO stanza VALUES('K389','4','가거라 세상아 주 나의 것<br/>오너라 새 세계야 주는 나의 것-<br/>사랑스런 축복 오너라 참 안식<br/>은혜의 주 오소서 주는 나의 것<br/>',NULL,31069,4);
INSERT INTO stanza VALUES('K39','1','아버지 앞에 모두 머리 숙여 무릎 꿇고 - 경 - 배 - 하네 -<br/>소나 양 - 의 제사 필요 - 없으니 영 안에 실 - 제 드리네<br/>',NULL,31070,1);
INSERT INTO stanza VALUES('K39','2','스스로 항상 계시는 아버지 영원서부 - 터 - 영원까지 -<br/>주의 보 - 좌 영영 무한 - 하 - 네 영 - 광 성 - 결 능력이<br/>',NULL,31071,2);
INSERT INTO stanza VALUES('K39','3','소망이 없던 죄인이었던 나 당신께 감히 기도 못하였네 -<br/>주의 공의만 보고 사랑 - 몰랐네 자애의 마 - 음 몰랐네<br/>',NULL,31072,3);
INSERT INTO stanza VALUES('K39','4','당신의 품 속 독생자 - 통해 당신을 완전히 - 계시했네 -<br/>단 - 하루도 죄인 회개함 없으면 당신은 만족하지 않네<br/>',NULL,31073,4);
INSERT INTO stanza VALUES('K39','5','죄인인 우리 건 - 지 - 시려 독생자 잠 - 시 - 버 - 리사 -<br/>십자가에서 고통 받게 - 하시어 우리의 길 - 을 여셨네<br/>',NULL,31074,5);
INSERT INTO stanza VALUES('K39','6','사랑의 아들 인 - 하 - 여 - 우리는 당 - 신 - 아들 됐네 -<br/>전엔 두렵던 당신 이젠 - 나에게 사랑스런 아바 아버지<br/>',NULL,31075,6);
INSERT INTO stanza VALUES('K39','7','깊으신 사랑 높으신 - 은혜 어찌 다 보답할 - 수 - 있나 -<br/>다만 영원히 감사 찬양 - 드리며 아버지 하나님 경배해<br/>',NULL,31076,7);
INSERT INTO stanza VALUES('K390','1','내 모든 것 되신 예수 내 주 기묘한 구주 내 기쁨 되니<br/>그가 날 인도해 보호하사 그 모든 환경 통과케 해<br/>',NULL,31077,1);
INSERT INTO stanza VALUES('K390','chorus','구주 예수 날 위하네 언제 어디서나 날 위하네<br/>',NULL,31078,2);
INSERT INTO stanza VALUES('K390','2','건강할 때에나 아플 때나 빈곤할 때에나 부할 때나<br/>햇빛이 비추든 비 내리든 그는 내 평강 날 위하네<br/>',NULL,31079,3);
INSERT INTO stanza VALUES('K390','3','그는 내 반석과 요새 방패 내 생명 나의 빛 나의 망대<br/>보호자 피난처 내 구속주 예수 늘 나를 위하시네<br/>',NULL,31080,4);
INSERT INTO stanza VALUES('K390','4','그는 내 선지자 제사장 왕 내 생명 샘이요 생명의 떡<br/>빛나는 의의 해 구원의 뿔 예수 늘 나를 위하시네<br/>',NULL,31081,5);
INSERT INTO stanza VALUES('K390','5','즐거울 때에나 슬플 때나 승리할 때에나 패할 때나<br/>보화인 주 나를 동정하네 사나 죽으나 주 날 위해<br/>',NULL,31082,6);
INSERT INTO stanza VALUES('K391','1','고요히 감 -췬 근원인 주님은 거룩한- 사랑<br/>나의 도움 내 의지할 산 나의 안전은 주 임재<br/>모든 염려 곤고- 떠나 주 안에 나-를 감 -추네<br/>',NULL,31083,1);
INSERT INTO stanza VALUES('K391','2','주가 내 모 -든 필요요 고통 중에 위로-되네<br/>내 맘의 약 또 평안되니 손실 중에 내 소득 돼<br/>학대받을 때 기 -쁨 돼 수치 받을- 때 면류관 돼<br/>',NULL,31084,2);
INSERT INTO stanza VALUES('K391','3','부족할 때 - 내 공급돼 에워싸일 때 해 -방돼<br/>연약할 때 내 능 -력 돼 흑암 중에 내 빛 되네<br/>슬플 때 나의 기-쁨 돼 죽음 가운-데 부 -활 돼<br/>',NULL,31085,3);
INSERT INTO stanza VALUES('K391','4','고요히 감 -췬 근원인 주님은 거룩한- 사랑<br/>주 안에 나 늘 감 -춰져 달콤함 임재 누리리<br/>모든 것 되신 주- 어찌 온전히 누-릴 수 - 있나<br/>',NULL,31086,4);
INSERT INTO stanza VALUES('K392','1','참 친근-하시-며 사랑스-러운 주<br/>내 평생- 찾으며 의-뢰할 주 예수<br/>',NULL,31087,1);
INSERT INTO stanza VALUES('K392','2','궁핍함-돌보-며 날 부축-하는 주<br/>참 아름-다우며 늘- 신실하신 주<br/>',NULL,31088,2);
INSERT INTO stanza VALUES('K392','3','끝없는- 기쁨-의 샘이신- 주 예수<br/>참 친근-하시며 사-랑스런 예수<br/>',NULL,31089,3);
INSERT INTO stanza VALUES('K393','1','기쁨 중-의 기-쁨 내 갈증- 해결해<br/>노래 중-의 노래 내- 외로움 제해<br/>',NULL,31090,1);
INSERT INTO stanza VALUES('K393','2','참 아름-다운- 분 내 삶에- 맛 주네<br/>참 귀하-신 내 주 비-교 못할 보배<br/>',NULL,31091,2);
INSERT INTO stanza VALUES('K393','3','생명 중-의 생-명 날 다시- 살리네<br/>참 거룩-하신 분 날- 분별시키네<br/>',NULL,31092,3);
INSERT INTO stanza VALUES('K393','4','참 의로-우신- 분 날 서게- 하시네<br/>힘 중의- 힘인 주 나- 피곤치 않네<br/>',NULL,31093,4);
INSERT INTO stanza VALUES('K393','5','능력 중-의 능-력 날 높이- 올리네<br/>승리 중-의 승리 내- 원수 다 제해<br/>',NULL,31094,5);
INSERT INTO stanza VALUES('K393','6','강함 중-의 강-함 내 전체- 해방해<br/>참 전능-하신 주 내- 영 강건케 해<br/>',NULL,31095,6);
INSERT INTO stanza VALUES('K393','7','왕 중의- 왕인- 주 내 맘을 다스려<br/>빛 중의- 빛인 주 늘- 내 맘 밝게 해<br/>',NULL,31096,7);
INSERT INTO stanza VALUES('K393','8','만주의- 주 지-금 내 맘에- 거하네<br/>길 중의- 길인 주 늘- 내 길 인도해<br/>',NULL,31097,8);
INSERT INTO stanza VALUES('K393','9','참 치료-자인- 주 내 영 혼- 몸 고쳐<br/>참 기묘-자인 주 날- 영화롭게 해<br/>',NULL,31098,9);
INSERT INTO stanza VALUES('K393','10','소망 중-의 소-망 날 하늘- 향케 해<br/>상 예비-하신 주 날- 전진케 하네<br/>',NULL,31099,10);
INSERT INTO stanza VALUES('K393','11','사랑 중-의 사-랑 찬송을- 받겠네<br/>인내 중-의 인내 경-배를 받겠네<br/>',NULL,31100,11);
INSERT INTO stanza VALUES('K393','12','큰 자 중- 크신- 주 홀로 존-경받고<br/>영광 중-의 영광 칭-송을 받겠네<br/>',NULL,31101,12);
INSERT INTO stanza VALUES('K394','1','축복 구하던 나 이젠 주 구해<br/>치료 구하던 나 치료자 구해<br/>은사 구하던 나 주님만 구해<br/>능력 구하던 나 전능자 구해<br/>',NULL,31102,1);
INSERT INTO stanza VALUES('K394','chorus','예수만을 높여 항상 찬-미해-<br/>만유이신 예-수 나의 모든 것<br/>',NULL,31103,2);
INSERT INTO stanza VALUES('K394','2','감정 따르던 나 주 안에 쉬네<br/>애를 쓰던 내가 이젠 안식해<br/>느낌 따르던 나 말씀 의지해<br/>주를 시험한 나 이젠 확신해<br/>',NULL,31104,3);
INSERT INTO stanza VALUES('K394','3','바삐 계획한 나 이젠 간구해<br/>염려 근심한 날 주가 담당해<br/>내 원함 따른 나 이젠 주 따라<br/>의심 많던 내가 이젠 찬미해<br/>',NULL,31105,4);
INSERT INTO stanza VALUES('K394','4','주를 이용한 날 주가 사용해<br/>내 일하던 내가 주 위해 일해<br/>사람 칭찬보다 주 기쁨 구해<br/>자신 위하던 나 주만 위하네<br/>',NULL,31106,5);
INSERT INTO stanza VALUES('K394','5','얻기 원했던 주 나에게 속해<br/>꺼져 가던 내 등 이젠 찬란해<br/>죽기 원하던 나 이젠 변하여<br/>들림 받는 그날 기다린다네<br/>',NULL,31107,6);
INSERT INTO stanza VALUES('K395','1','예-수만이 나-의 제목 유-일한 내 메-시지<br/>예-수만이 나-의 노래 유-일한 내 희망일세<br/>',NULL,31108,1);
INSERT INTO stanza VALUES('K395','chorus','오-직 예수 오-직 예수 그-를 영영 찬미하리<br/>그-는 구주 생-명 의사 왕-국 세울 왕-일세<br/>',NULL,31109,2);
INSERT INTO stanza VALUES('K395','2','예-수만이 나-의 구주 내- 죄 담당하-셨네<br/>영- 단번에 이-룬 구속 나-로 은혜 얻-게 해<br/>',NULL,31110,3);
INSERT INTO stanza VALUES('K395','3','예-수만이 나-의 생명 자-아에서 구-원해<br/>성-령으로 내- 맘 채운 예수는 나의 힘-일세<br/>',NULL,31111,4);
INSERT INTO stanza VALUES('K395','4','예-수만이 나-의 의사 나-의 질병 치-료해<br/>부-활 생명 승-천 풍성 그-의 몸에 분-배해<br/>',NULL,31112,5);
INSERT INTO stanza VALUES('K395','5','예-수만이 나-의 능력 오-순절을 오-게 해<br/>주-여 나로 승-리하게 성-령 채워 주-소서<br/>',NULL,31113,6);
INSERT INTO stanza VALUES('K395','6','이-제 우린 기-다리네 주-가 부르는- 소리<br/>끝-날까지 만-유 구주 예-수만을 기다리리<br/>',NULL,31114,7);
INSERT INTO stanza VALUES('K396','1','주 얼굴 빛 못볼 때에 난 얼마나 지루한 지<br/>저 예쁘던 새들과 꽃 날 기쁘게 하지 못해<br/>저 햇빛도 빛을 잃고 저 들녘도 황량하네<br/>나 주 안에 즐거울 때 저 구름도 아름다워<br/>',NULL,31115,1);
INSERT INTO stanza VALUES('K396','2','오 달콤한 주의 이름 오 달콤한 주의 음성<br/>주 임재 내 근심 제해 내 기쁨을 충만케 해<br/>늘 주 예수 가까이해 난 두려움 전혀 없네<br/>이 세상에 나보다도 더 즐거운 자 없으리<br/>',NULL,31116,2);
INSERT INTO stanza VALUES('K396','3','참 달콤한 주의 얼굴 내 마음을 기쁘게 해<br/>난 오직 주 기뻐하심 늘 구하며 순종하리<br/>주 사랑이 충만하면 저 궁정도 티끌 같아<br/>주 나와 함께하시면 이 감옥도 궁전 되리<br/>',NULL,31117,3);
INSERT INTO stanza VALUES('K396','4','주 참 나의 햇빛인데 나 어이해 근심하나<br/>이 혹독한 겨울 추위 왜 이리도 길고 긴가<br/>오 주여 저 먹구름을 다 쫓아내 주옵소서<br/>날 주께로 인도하사 주 임재 회복하소서<br/>',NULL,31118,4);
INSERT INTO stanza VALUES('K397','1','실재 되신 그리스-도 이제 내 안에 사시네<br/>주는 만유 포함한 영 나와 하-나 되셨네<br/>',NULL,31119,1);
INSERT INTO stanza VALUES('K397','chorus','실재되신 그-리스도 참- 부요하고 달콤해<br/>만유 포함하신 주님 내- 모든 필-요 채우네<br/>',NULL,31120,2);
INSERT INTO stanza VALUES('K397','2','실재 되신 그리스-도 항상 생-명 공급해<br/>성령으로 나를 살려 매일 새롭게 하시네<br/>',NULL,31121,3);
INSERT INTO stanza VALUES('K397','3','실재 되신 그리스-도 나의 전-체 변케 해<br/>나의 생각 감정 의지 그의 형-상 되게 해<br/>',NULL,31122,4);
INSERT INTO stanza VALUES('K397','4','실재 되신 그리스-도 나를 자-유케 하네<br/>생명과 성령의 법이 죄와 사망서 해방해<br/>',NULL,31123,5);
INSERT INTO stanza VALUES('K397','5','실재 되신 그리스-도 매일 나-를 다스려<br/>인도하며 바로잡네 항상 모-든 길에서<br/>',NULL,31124,6);
INSERT INTO stanza VALUES('K397','6','실재 되신 그리스-도 나를 만-족게 하네<br/>모든 풍성 공급하셔 주의 완전함 간증해<br/>',NULL,31125,7);
INSERT INTO stanza VALUES('K398','1','주 하늘서 날 위해 대언하며 내 안에서 내 생명 되셨다네<br/>늘 내 속에 그분을- 공급하네 오 객관-적- 주관적 되신 주님<br/>',NULL,31126,1);
INSERT INTO stanza VALUES('K398','2','주 하늘서 대제사장이 되어 날 위하여 하나님께 피 드려<br/>내 중보가 되셔서- 내 짐 지고 날 사랑-과- 신실로 변호하셔<br/>',NULL,31127,2);
INSERT INTO stanza VALUES('K398','3','오 생명의 영인 주 내 영 안에 내 생명과 능력과 만유 되네<br/>늘 나에게 은혜를- 공급하네 주 언제-나- 안에서 날 지키네<br/>',NULL,31128,3);
INSERT INTO stanza VALUES('K398','4','하늘에서 영광의 사람인 주 휘장 안에 영광의 몸 나타내<br/>오 사람을 하나님- 안에 끌어 하나님-과- 사람을 연합케 해<br/>',NULL,31129,4);
INSERT INTO stanza VALUES('K398','5','날 하나님 성품에 참예토록 하나님을 내 안에 이끌어 와<br/>계시로써 하나님- 내 실재 돼 나 주님-과- 영원히 연합됐네<br/>',NULL,31130,5);
INSERT INTO stanza VALUES('K398','6','승천한 주 하늘에 거하시네 주 오실 때 모든 눈 그를 보리<br/>내 영 안에 사시는- 실재인 주 곧 나타- 나- 나의 몸 변케 하리<br/>',NULL,31131,6);
INSERT INTO stanza VALUES('K398','7','때 이르면 새 하늘 새 땅에서 거룩한 성 새 예루살렘에서<br/>하나님과 사람 더- 간격 없이 완전한- 연합 영원히 나타내리<br/>',NULL,31132,7);
INSERT INTO stanza VALUES('K399','1','내 안에 주 계시하길 하나님 기뻐하니<br/>밖의 종교 받지 말고 맘에 주 거하게 해<br/>',NULL,31133,1);
INSERT INTO stanza VALUES('K399','chorus','하나님의 원하심은 밖의 성취 아니요<br/>내 안에 주 역사하여 주가 확장됨일세<br/>',NULL,31134,2);
INSERT INTO stanza VALUES('K399','2','내 안에 주 사시기를 하나님 기뻐하니<br/>일과 실행 주의 말고 다만 주를 누리세<br/>',NULL,31135,3);
INSERT INTO stanza VALUES('K399','3','주의 형상 이루기를 하나님 기뻐하니<br/>밖의 의식 좇지 말고 주만 증가하게 해<br/>',NULL,31136,4);
INSERT INTO stanza VALUES('K399','4','내게 거처 정하기를 하나님 기뻐하니<br/>밖의 봉사 열심 떠나 주 날 점유하게 해<br/>',NULL,31137,5);
INSERT INTO stanza VALUES('K399','5','주만 소망 삼는 것을 하나님 기뻐하니<br/>밖의 영광 구치 않네 주가 곧 영광일세<br/>',NULL,31138,6);
INSERT INTO stanza VALUES('K399','6','주가 나의 만유 되길 하나님 기뻐하니<br/>밖의 것을 구치 않고 주를 비결 삼으리<br/>',NULL,31139,7);
INSERT INTO stanza VALUES('K4','1','거룩 거룩 거룩 전능하신 주여<br/>영원토록 당신 향해 찬송합니다<br/>거룩 거룩 거룩 전능 자비하신<br/>성부 성자 성령 한 분이실세<br/>',NULL,31140,1);
INSERT INTO stanza VALUES('K4','2','거룩 거룩 거룩 모든 무릎 꿇고<br/>천사들이 보좌 앞에 면류관 던져<br/>전에도 계시고 이제도 계시며<br/>영원히 계실 주께 경배해<br/>',NULL,31141,2);
INSERT INTO stanza VALUES('K4','3','거룩 거룩 거룩 자신 나타내사<br/>죄인들로 주의 영광 보게 합소서<br/>거룩하신 주님 주 같은 이 없네<br/>완전한 사랑 순결과 능력<br/>',NULL,31142,3);
INSERT INTO stanza VALUES('K4','4','거룩 거룩 거룩 전능하신 주님<br/>온 천지간 피조물이 찬송합니다<br/>거룩 거룩 거룩 전능 자비하신<br/>성부 성자 성령 한 분이실세<br/>',NULL,31143,4);
INSERT INTO stanza VALUES('K40','1','이제 다시 없 - 네 피 - 나 제단 제 - 사<br/>연 - 기 불 - 탐 희 - 생 없 - 네 더 - 나 - 은 - 피 흘러<br/>사람의 모든 더러움 씻고<br/>사람들의 죄 빚 모두 다 갚았네<br/>',NULL,31144,1);
INSERT INTO stanza VALUES('K40','2','하나님 감사 - 해 그 - 아들 피 인 - 해 우 - 린<br/>의 - 롭다 - 함 받 - 고 피 - 로 - 승 - 리하네<br/>불 못과 사망 흑암 이겼네<br/>두 번 싸움 없네 원수 다 멸했네<br/>',NULL,31145,2);
INSERT INTO stanza VALUES('K40','3','하나님 감사 - 해 하 - 늘 은혜 인 - 해<br/>큰 - 불의 - 와 깊 - 은 죄 - 악 다 - 용 - 서 - 하셨네<br/>주 영광 권위 영원하시듯<br/>영원한 주 사랑 다 찬양하겠네<br/>',NULL,31146,3);
INSERT INTO stanza VALUES('K40','4','하나님 감사 - 해 변 - 함없는 소 - 망<br/>침 - 체된 - 영 올 - 라가 - 네 새 - 벽 - 오 - 기까지<br/>피곤한 광야 험한 길에서<br/>복된 소망 항상 우릴 격려하네<br/>',NULL,31147,4);
INSERT INTO stanza VALUES('K40','5','하나님 감사 - 해 그 - 영광 면류 - 관<br/>들 - 풀처 - 럼 마르지 않 - 고 영 - 영 - 썩 - 지 않네<br/>그날에 주의 보좌 향해서<br/>면류관 던질 때 참 기쁨 넘치리<br/>',NULL,31148,5);
INSERT INTO stanza VALUES('K400','1','오 주님만이 내 생명 나에게 모든 것 되니<br/>참 친절하고 편리해 영원히 쓰고도 남네<br/>',NULL,31149,1);
INSERT INTO stanza VALUES('K400','chorus','오 주는 생명 주는 영 참 친근하시니<br/>주 아는 사람 그를 좋아해 항상 새롭네<br/>',NULL,31150,2);
INSERT INTO stanza VALUES('K400','2','오 주님만이 나에게 필요한 공급 되시니<br/>참 완전하고 풍족해 내 영을 사용할 때에<br/>',NULL,31151,3);
INSERT INTO stanza VALUES('K400','3','주 내게 기름 부으며 인도해 날 도우시니<br/>주 능력으로 내 약함 변하여 강함이 되네<br/>',NULL,31152,4);
INSERT INTO stanza VALUES('K400','4','영 안에 율법 생명률 내 생활 자유케 하며<br/>주 주신 풍성 실재로 내 온 몸 충만케 하네<br/>',NULL,31153,5);
INSERT INTO stanza VALUES('K400','5','주 나와 한 영 됨으로 영원히 거리가 없네<br/>이같은 거룩한 연결 무엇과 비할 수 없네<br/>',NULL,31154,6);
INSERT INTO stanza VALUES('K400','6','주 내게 인격 되셔서 마음에 안식합소서<br/>갈수록 영광 빛 가해 내 온 몸 변케 합소서<br/>',NULL,31155,7);
INSERT INTO stanza VALUES('K401','1','주가 내게 주신 자유 나를 해방시켰네<br/>죄의 권세 사망의 침 내 몸 이미 떠났네<br/>',NULL,31156,1);
INSERT INTO stanza VALUES('K401','chorus','주가 승리 주시므로 십자가를 높이네<br/>생명의 힘 생명의 율 내게 강한 능력돼<br/>',NULL,31157,2);
INSERT INTO stanza VALUES('K401','2','주가 나를 율법에서 영원히 해방하셔<br/>완전하신 은혜 아래 묶임 없이 살게 해<br/>',NULL,31158,3);
INSERT INTO stanza VALUES('K401','3','주는 육신 입고 오사 내 죄 담당하셨네<br/>죄는 다시 내 몸에서 지위 얻지 못하네<br/>',NULL,31159,4);
INSERT INTO stanza VALUES('K401','4','주는 사망 음부 거쳐 썩지 않을 생명 돼<br/>모든 사망 폐하시고 부활 능력 보였네<br/>',NULL,31160,5);
INSERT INTO stanza VALUES('K401','5','주는 사탄 깨뜨리고 악령 심판하셨네<br/>나를 흑암 권세에서 생명 빛에 옮겼네<br/>',NULL,31161,6);
INSERT INTO stanza VALUES('K401','6','주 풍성한 은혜 넘쳐 그의 능력 알게 해<br/>주의 능력 가운데서 온전하여짐일세<br/>',NULL,31162,7);
INSERT INTO stanza VALUES('K402','1','의문 율법 아닌 생명 주는 영 그 영 내게 줄 때<br/>짐을 벗었네 또한 이론 아닌 생명 영만이<br/>죄와 자아에서 해방케 하네<br/>',NULL,31163,1);
INSERT INTO stanza VALUES('K402','2','형식과 교훈이 살게 못하며 또한 나의 혼을<br/>변케 못하네 영 안의 주만이 생명 공급해<br/>하나님 나타내 경륜 이루네<br/>',NULL,31164,2);
INSERT INTO stanza VALUES('K402','3','어떤 철학이나 논리 아니요 그것으론 지체<br/>만질 수 없네 주님 자신만이 인성 안에서<br/>부활 능력으로 몸을 이루네<br/>',NULL,31165,3);
INSERT INTO stanza VALUES('K402','4','어떤 종교 또한 조직으로는 주의 원하는 뜻<br/>이룰 수 없네 내 안의 주만이 모든 것 되어<br/>하나님의 참 뜻 성취하시네<br/>',NULL,31166,4);
INSERT INTO stanza VALUES('K402','5','주가 주신 은사 어떤 능력도 주님 자신과는<br/>비교 못하니 주가 우리 안에 내용 되도록<br/>주님 자신만을 충만케 하리<br/>',NULL,31167,5);
INSERT INTO stanza VALUES('K403','1','오 내 주의 신성 풍성 측량할 자 없도다<br/>성스러운 모든 풍성 내게 누리게 했네<br/>',NULL,31168,1);
INSERT INTO stanza VALUES('K403','chorus','거룩한 영광의 풍성 주 풍성 나 위하네<br/>측량 못할 크신 풍성 실재로 나 얻었네<br/>',NULL,31169,2);
INSERT INTO stanza VALUES('K403','2','오 내 주의 신성 풍성 측량할 자 없도다<br/>치료함과 평안 기쁨 모든 것 포함했네<br/>',NULL,31170,3);
INSERT INTO stanza VALUES('K403','3','완전 구속 은혜 풍성 의와 성결 또 해방<br/>부활 능력 승천 초월 하나님 보화 창고<br/>',NULL,31171,4);
INSERT INTO stanza VALUES('K403','4','오 내 주의 신성 풍성 하나님 나타나셔<br/>그의 모든 소유 전체 영 안에 얻게 했네<br/>',NULL,31172,5);
INSERT INTO stanza VALUES('K403','5','오 내 주의 신성 풍성 누가 능히 알리요<br/>측량 못할 그리스도 나로 누리게 하네<br/>',NULL,31173,6);
INSERT INTO stanza VALUES('K403','6','오 내 주의 모든 풍성 어떠함을 깨달아<br/>하나님의 기쁨 안에 함께 누리기 원해<br/>',NULL,31174,7);
INSERT INTO stanza VALUES('K404','1','날 인도하신 주의 뜻 얼마나 아름-다운지<br/>모든 것 모든 일 중에 주 - 인도의- 손- 있다네<br/>',NULL,31175,1);
INSERT INTO stanza VALUES('K404','chorus','날 인도하는 주 예-수 날 친히 인-도-하시니<br/>나 어디든지 따르-리 때와 곳 가-리-지 않고<br/>',NULL,31176,2);
INSERT INTO stanza VALUES('K404','2','때로는 고통당하고 때로는 기쁨- 넘치네<br/>평온하든 풍파 일든 주-의 손 나-를- 인도해<br/>',NULL,31177,3);
INSERT INTO stanza VALUES('K404','3','주여 내 손을 잡으사 내 갈길 인도-하소서<br/>축복이든 고통이든 주-님이 인-도-하소서<br/>',NULL,31178,4);
INSERT INTO stanza VALUES('K404','4','내 인생길 다 마치고 주 은혜로 승-리하리<br/>주 나를 인도하리니 죽-음도 피-하-잖으리<br/>',NULL,31179,5);
INSERT INTO stanza VALUES('K405','1','은혜의 주 내-게 속하였으니<br/>죄의 즐거움- 다 버리렵니다<br/>피로 나를 속-량한 구-주시니-<br/>이제 주님만-을 사랑-합니다<br/>',NULL,31180,1);
INSERT INTO stanza VALUES('K405','2','주 날 먼저 사-랑하시었으니<br/>나도 맘 다해- 주 사랑합니다<br/>날 위하여 가-시관 쓰-셨으니-<br/>이제 주님만-을 사랑-합니다<br/>',NULL,31181,2);
INSERT INTO stanza VALUES('K405','3','나의 호흡 멎-는 그 순간까지<br/>주를 사랑하-며 부르렵니다<br/>죽음 앞에서-도 내 말-할 것은-<br/>이제 주님만-을 사랑-합니다<br/>',NULL,31182,3);
INSERT INTO stanza VALUES('K405','4','영광 빛 가운-데 경배하리라<br/>영광의 관 쓰-신 내 주 예수를<br/>영원토록 주-님께 말-할 것은-<br/>이제 주님만-을 사랑-합니다<br/>',NULL,31183,4);
INSERT INTO stanza VALUES('K406','1','달콤한 교통 풍성한 기쁨 영원하신 팔에 안식해<br/>넘치는 축복 거룩한 평안 영원하신 팔에 안식해<br/>',NULL,31184,1);
INSERT INTO stanza VALUES('K406','chorus','안식하세 두려움 없는 그 팔에<br/>안식하세 영원하신 팔에 안식해<br/>',NULL,31185,2);
INSERT INTO stanza VALUES('K406','2','나그네 길에 평강 넘치네 영원하신 팔에 안식해<br/>날이 갈수록 빛이 찬란해 영원하신 팔에 안식해<br/>',NULL,31186,3);
INSERT INTO stanza VALUES('K406','3','두려움이나 불안함 없네 영원하신 팔에 안식해<br/>주와 동거해 평강 넘치니 영원하신 팔에 안식해<br/>',NULL,31187,4);
INSERT INTO stanza VALUES('K407','1','예수는 나-의 태양이니 주님이 계시면 밤도 밝아<br/>주 얼굴 가리는 구름 내게서 거둬 주-소서<br/>',NULL,31188,1);
INSERT INTO stanza VALUES('K407','2','피곤함 내- 눈 감-길 때 늦은 밤 주-를 사-모해<br/>영세 안에서 주 품에 안식하기를 사 -모해<br/>',NULL,31189,2);
INSERT INTO stanza VALUES('K407','3','주 없는 삶-은 뜻 없으니 늘 나와 함-께 하-소서<br/>죽음의 그늘 없도록 늘 나와 함께하-소서<br/>',NULL,31190,3);
INSERT INTO stanza VALUES('K407','4','잠에서 깰- 때 날 축복해 늘 나를 부-축하-소서<br/>들림받아 주 곁에 가 주 사랑 안에 잠기도록<br/>',NULL,31191,4);
INSERT INTO stanza VALUES('K408','1','주님의 이름 쏟은 향 기름 주님의 사랑 술보다 달아<br/>양 무리 자취 따라 갈 때에 사랑의 교통 안에 들어가<br/>',NULL,31192,1);
INSERT INTO stanza VALUES('K408','2','그는 내 사랑 난 그의 배필 주 인도하니 그를 좇아가<br/>몰약의 향 내 맘에 간직해 고벨화 아름다움 입겠네<br/>',NULL,31193,2);
INSERT INTO stanza VALUES('K408','3','그 사랑 안에 달콤함 누려 그 품에 누워 향기 맛보네<br/>그는 내 깃발 나를 가리며 그 사랑 내 맘 상쾌하게 해<br/>',NULL,31194,3);
INSERT INTO stanza VALUES('K408','4','그는 나의 것 나는 그의 것 난 그의 백합 그가 날 길러<br/>날이 샐 때면 어둠 사라져 아침 노루인 그를 만나리<br/>',NULL,31195,4);
INSERT INTO stanza VALUES('K408','5','주 함께 죽은 몰약의 향기 부활의 유향 내 맘 적시네<br/>북풍아 일라 남풍아 불라 내 맘의 동산 주 기쁨 되게<br/>',NULL,31196,5);
INSERT INTO stanza VALUES('K408','6','난 그의 눈에 비둘기 같고 순전한 백합 같기 원하네<br/>온전히 주께 속한 나에게 주만이 노래 중의 노래라<br/>',NULL,31197,6);
INSERT INTO stanza VALUES('K408','7','달처럼 그의 형상 얻으리 해처럼 맑게 나는 자라리<br/>내 사랑 주께 온전히 속해 주님의 마음 기쁘게 하리<br/>',NULL,31198,7);
INSERT INTO stanza VALUES('K408','8','그는 내 생명 난 그의 형상 사랑의 연합 굳세고 강해<br/>내 사랑 다시 오실 때까지 당신의 향기로운 산으로<br/>',NULL,31199,8);
INSERT INTO stanza VALUES('K409','1','내게는 보-배로운 한 좋은 친구 있네<br/>그는 날 사랑해 온유해 그 사랑 참 달콤해<br/>난 주 없는 덴 못살아 내 사랑 그를 잡네<br/>난 그와 동거하며 함께 사네<br/>',NULL,31200,1);
INSERT INTO stanza VALUES('K409','2','때로는 넘-어질 때 그는 내 약함 아셔<br/>나에게 주 의지하게 해 주는 날 붙드시네<br/>주 나를 인도함으로 광명의 길 가게 해<br/>주 나와 함께 행해 주는 나와<br/>',NULL,31201,2);
INSERT INTO stanza VALUES('K409','3','그는 내 사랑의 길이 그 넓이 다 아시네<br/>주 나를 사랑한 사랑은 영원히 다 말 못해<br/>주 사랑만은 영원해 갈수록 타오르네<br/>우린 서로 맘과 뜻 주고 받네<br/>',NULL,31202,3);
INSERT INTO stanza VALUES('K409','4','내 모든 고통과 기쁨 그에게 고-하네<br/>내 사모하-는 모든 것 또 상처 고-하네<br/>그는 내게 할 일 알려 나로 일하게 하네<br/>우린 서로 맘과 뜻 주고 받네<br/>',NULL,31203,4);
INSERT INTO stanza VALUES('K409','5','한 영혼 구-원하길 나는 참 사모하네<br/>기묘한 사랑의 소식을 전하라 말씀했네<br/>죽음 거쳐 나온 사랑 내 맘을 강권하네<br/>우린 서로 동거해 주와 함께<br/>',NULL,31204,5);
INSERT INTO stanza VALUES('K409','6','주 내게 그-의 왕국 열어서 보여주네<br/>더 빨리 그곳에 이르길 내 주는 원하시네<br/>참 복락과 소망-은 영광 보좌에 있네<br/>우린 왕 노릇 하리 주와 함께<br/>',NULL,31205,6);
INSERT INTO stanza VALUES('K41','1','오 하나님 날 부르사 보게 하셨네<br/>하나님 맘의 보물인 아들 주 예수<br/>간절한 사랑으로 날 구출하시려<br/>그 - 사랑하는 독생자 버리셨다네<br/>',NULL,31206,1);
INSERT INTO stanza VALUES('K41','2','오 거룩한 아버지 긍휼의 하나님<br/>우린 아들 이름 안에 은혜 구하네<br/>당신이 항상 듣기 원하는 그 이름<br/>모 - 든 의심에서 우릴 벗어나게 해<br/>',NULL,31207,2);
INSERT INTO stanza VALUES('K41','3','주가 날 위해 받으신 형벌 인하여<br/>내 과거 영영 기억지 않는 아버지<br/>그 어느 것이 우리를 자유케 하랴<br/>그 - 아들 죽음 우리의 죄 빚 갚았네<br/>',NULL,31208,3);
INSERT INTO stanza VALUES('K41','4','주 예수 믿고 아버지 집에 올 때에<br/>당신의 맘의 분노 다 사라졌다네<br/>돌아온 자녀 껴안고 의복 주시네<br/>큰 - 사랑 우리 마음을 위로하시네<br/>',NULL,31209,4);
INSERT INTO stanza VALUES('K41','5','오 우린 당신 비웃고 미워했는데<br/>당신은 어찌 우리를 사랑하실까<br/>오 기이하고 기이한 거룩한 비밀<br/>나 - 이제 주께 말하네 “당신 것이라”<br/>',NULL,31210,5);
INSERT INTO stanza VALUES('K410','1','영광 안의 그리스도 내 마음을 비추네<br/>별보다도 해보다도 더 밝은 그 빛으로<br/>흑암뿐인 이 땅 어찌 내 마음을 얻을까<br/>주가 가신 고난의 길 내 마음의 보밸세<br/>',NULL,31211,1);
INSERT INTO stanza VALUES('K410','2','땅의 빛을 의지하여 피곤하게 살 때에<br/>해보다도 밝은 그 빛 하늘로서 임했네<br/>영광스런 주의 얼굴 비추는 영원한 빛<br/>주의 사랑 은혜 충만 나로 보게 하시네<br/>',NULL,31212,2);
INSERT INTO stanza VALUES('K410','3','놀라워라 주의 영광 기묘해라 주 사랑<br/>나를 위해 만세토록 초월 위치 얻은 주<br/>휘장 안에 들어가서 주 얼굴 주목하며<br/>비밀하신 주의 말씀 들으면서 안주해<br/>',NULL,31213,3);
INSERT INTO stanza VALUES('K410','4','영광스런 주의 얼굴 은혜로운 주 말씀<br/>날 만족게 하였으니 아무 불만 없다네<br/>영광 광채 빛 발하는 주의 얼굴 주목해<br/>영원 안의 거처에서 안식할 그날까지<br/>',NULL,31214,4);
INSERT INTO stanza VALUES('K411','1','서산으로 해질 때 밤하늘에 별뜰 때<br/>주를 가까이-하여 영 안에서 맑-아져 깨끗케 돼<br/>',NULL,31215,1);
INSERT INTO stanza VALUES('K411','chorus','주께 가까이 해 마음 다해 영 안에서<br/>사모해 사랑스런 주 얼굴 친근한 주<br/>',NULL,31216,2);
INSERT INTO stanza VALUES('K411','2','넓은 이 우주에서 오직 주를 구하네<br/>주의 얼굴 광-채만 더욱 사모하-오니 비추소서<br/>',NULL,31217,3);
INSERT INTO stanza VALUES('K411','3','이 밤 어두울수록 별들 뚫고 주 보리<br/>주를 가까이-할 때 나는 외롭지- 않네 영원토록<br/>',NULL,31218,4);
INSERT INTO stanza VALUES('K411','4','어두운 밤 지날 때 영원한 아침 오리<br/>밤의 그림자- 걷혀 주의 영광 모-습을 뵈오리라<br/>',NULL,31219,5);
INSERT INTO stanza VALUES('K412','1','공급 근원되신 주를 믿음으로 접하네<br/>나를 씻는 보혈 믿고 주의 미덕 선포해<br/>',NULL,31220,1);
INSERT INTO stanza VALUES('K412','chorus','주의 영을 접촉할 때 생명 공급 누리네<br/>날 순결케 하는 그 영 주의 충만 주시네<br/>',NULL,31221,2);
INSERT INTO stanza VALUES('K412','2','믿음으로 주 만지고 주의 풍성 적용해<br/>내 온 존재 주께 열고 주님만을 채우네<br/>',NULL,31222,3);
INSERT INTO stanza VALUES('K412','3','더욱 깊이 주를 접해 주의 풍성 취하리<br/>은혜 위에 은혜 얻어 주만 나타내도록<br/>',NULL,31223,4);
INSERT INTO stanza VALUES('K412','4','능력 지혜 사랑 은혜 내게 공급하시니<br/>쉬지 않고 주를 접해 주님만을 취하리<br/>',NULL,31224,5);
INSERT INTO stanza VALUES('K413','1','고요히 나 접촉하네 아름답고 보배로운 주<br/>사랑스럽고 부드런 소리 내 깊은 속에 들리네<br/>',NULL,31225,1);
INSERT INTO stanza VALUES('K413','chorus','귀한 구주 사랑의 예수님 내게 말해 주옵소서<br/>하늘에 속한 주님 어이해 고요한 데 계시는지<br/>',NULL,31226,2);
INSERT INTO stanza VALUES('K413','2','조용할 때 내게 임해 내실로 날 이끄시는 주<br/>그의 갈망과 참된 사랑을 은밀히 말해 주시네<br/>',NULL,31227,3);
INSERT INTO stanza VALUES('K413','3','주와 함께 있는 곳은 거룩하고 하늘에 속해<br/>주 가까이해 기쁨 누릴 때 주 사랑 내게 나타나<br/>',NULL,31228,4);
INSERT INTO stanza VALUES('K413','4','나 고요히 엎드리어 주 음성에 귀 기울이네<br/>주의 사랑의 한- 부분도 잃지 않기를 원하네<br/>',NULL,31229,5);
INSERT INTO stanza VALUES('K413','5','주의 품에 편히 누워 사랑스런 얼굴 뵈오니<br/>이보다 더한 즐거움 없어 내 혼과 맘 다 만족해<br/>',NULL,31230,6);
INSERT INTO stanza VALUES('K414','1','휘장 안으로 들어가려면 영문밖으로 나아가야 돼<br/>하늘의 기쁨 얻기 원하면 땅의 사랑을 버려야 하네<br/>',NULL,31231,1);
INSERT INTO stanza VALUES('K414','2','휘장 안으로 들어가려면 영문 밖으로 나아가야 돼<br/>하늘 영광이 내 영 이끄니 땅의 복 내 사랑 못 빼앗네<br/>',NULL,31232,2);
INSERT INTO stanza VALUES('K414','3','휘장 안에서 영광 주 보며 영문 밖에 간 예수 따르리<br/>보좌 면류관 날 격려하니 말구유 십자가 날 못 막네<br/>',NULL,31233,3);
INSERT INTO stanza VALUES('K414','4','휘장 안에서 부활 흡수해 영문 밖에서 십자가 길 가<br/>하늘에 계신 주 얼굴 보며 주님의 이 땅 자취 따르네<br/>',NULL,31234,4);
INSERT INTO stanza VALUES('K414','5','휘장 안에서 하늘 맛보며 영문 밖에서 땅을 견디네<br/>땅의 체험 날 아프게 하나 하늘의 교통 날 찬미케 해<br/>',NULL,31235,5);
INSERT INTO stanza VALUES('K414','6','휘장 안에서 주를 누리며 영문 밖에서 공급하겠네<br/>하늘의 생명 살아 나타내 사람들 축복 얻게 하겠네<br/>',NULL,31236,6);
INSERT INTO stanza VALUES('K414','7','휘장 안으로 들어가겠네 영문 밖으로 나아가겠네<br/>하늘과 땅의 모든 것들이 다 하나 안에 들어오도록<br/>',NULL,31237,7);
INSERT INTO stanza VALUES('K415','1','주와 함께 안주하며 주의 달콤함 누려<br/>주의 앞에 엎드려서 주의 공과 배우네<br/>괴롭히던 근심 시험 나를 멀리 떠나네<br/>사탄 나를 유혹할 때 주의 은밀한 데로 속히 가서 거하리<br/>',NULL,31238,1);
INSERT INTO stanza VALUES('K415','2','피곤하고 목마를 때 주의 날개로 오네<br/>그늘 아래 보호 받아 상쾌하고 즐거워<br/>맑은 생명 샘에서 나 주와 교통할 때에<br/>향기롭고 달콤하네 나의 말로 다 못해 그의 비밀의 말을<br/>',NULL,31239,2);
INSERT INTO stanza VALUES('K415','3','주를 향해 나의 고통 모두 토해 낼 때에<br/>주는 오래 참으시고 내게 힘을 주시네<br/>나의 거짓된 것 모두 주께 드러날 때에<br/>그는 탄식하시면서 내게 말씀하시네 나를 가르치시네<br/>',NULL,31240,3);
INSERT INTO stanza VALUES('K415','4','주의 아름다움 정말 네가 알기 원하면<br/>주의 그늘 아래 거해 주의 향기 맛보라<br/>주와 교통하며 항상 그의 안에 거하여<br/>주의 영광스런 형상 너의 얼굴 통하여 반사하게 되리라<br/>',NULL,31241,4);
INSERT INTO stanza VALUES('K416','1','참된 사실 믿은 나 주의 죽음 누리며<br/>바깥 마당 거쳤네 할렐루야 찬미해<br/>속죄하는 보혈로 나는 주께 드려져<br/>거룩하게 되었네 할렐루야 어린 양<br/>',NULL,31242,1);
INSERT INTO stanza VALUES('K416','chorus','할렐루야할렐루야열린 휘장 지나니 항상 영광 충만해<br/>할렐루야할렐루야 이젠 왕 앞에서 생활한다네<br/>',NULL,31243,2);
INSERT INTO stanza VALUES('K416','2','밖의 휘장 지나서 성소 안에 들어가<br/>주의 공급 누리네 할렐루야 찬미해<br/>하나님과 화목돼 제단 거쳐 성결해<br/>세상 영영 버리네 할렐루야 어린 양<br/>',NULL,31244,3);
INSERT INTO stanza VALUES('K416','3','안의 휘장 지나서 지성소에 들어가<br/>은혜 보좌 누리네 할렐루야 찬미해<br/>주의 앞에 생활해 나는 주의 거처 돼<br/>죄와 자아 없다네 할렐루야 어린양<br/>',NULL,31245,4);
INSERT INTO stanza VALUES('K416','4','구속 거친 나 이제 하나님의 제사장<br/>나의 신분 확실해 할렐루야 찬미해<br/>주의 영광 앞에서 영 안에서 산다네<br/>날이 가도 변찮네 할렐루야 어린 양<br/>',NULL,31246,5);
INSERT INTO stanza VALUES('K417','1','밤 그림자 남아 있고 새벽빛이 비추기 전에<br/>은혜의 주께 다시 나오니 주 나를 비춰 주시네<br/>내게 말씀하-여 주시네 오늘 누릴 주 풍성을<br/>달콤하고 기쁜 누림에 굶주림 다 채워지네<br/>',NULL,31247,1);
INSERT INTO stanza VALUES('K417','2','주의 영과 나의 영이 말씀 통해 교-통하니<br/>은혜 넘치는 생-명의 샘 내 안에 항상 흐르네<br/>내게 말씀하-여 주시네 오늘 누릴 주 풍성을<br/>주를 깊이 깊이 마실 때 내 목마름 다 사라져<br/>',NULL,31248,2);
INSERT INTO stanza VALUES('K417','3','주 얼굴빛 거할 때에 주의 사랑 나를 다루네<br/>신-성하신 주-의 성분 내 전체 적셔 주시네<br/>내게 말씀하-여 주시네 오늘 누릴 주 풍성을<br/>충만하게 주를 누릴 때 모든 문제 달아나네<br/>',NULL,31249,3);
INSERT INTO stanza VALUES('K418','1','가장 큰 복은 주 안에 거해 주님과 함께 교통함일세<br/>주 안에 살며 주와 연합해 늘 교통할 때 막힘 없으리<br/>',NULL,31250,1);
INSERT INTO stanza VALUES('K418','2','주 안에 살 때 기름 부음과 성령의 인도 얻을 수 있네<br/>기름부음의 풍성 누리고 그 영을 따라 주와 동행해<br/>',NULL,31251,2);
INSERT INTO stanza VALUES('K418','3','주 안에 살 때 빛이 비취고 늘 교통할 때 어둠 사라져<br/>빛 순종할 때 생명 자라고 어둠 다 벗고 마음 상쾌해<br/>',NULL,31252,3);
INSERT INTO stanza VALUES('K418','4','주 안에 살 때 약함 강해져 늘 교통할 때 사망 이기네<br/>주 안에 살 때 탄식 찬송돼 늘 교통할 때 기쁨 넘치네<br/>',NULL,31253,4);
INSERT INTO stanza VALUES('K418','5','주 안에 살 때 사탄 이기고 늘 교통할 때 세상 이기네<br/>주 안에 살 때 죄 권능 잃고 늘 교통할 때 자아 사라져<br/>',NULL,31254,5);
INSERT INTO stanza VALUES('K418','6','주 안에 살 때 형상 본받고 늘 교통할 때 생명 충만해<br/>주 안에 살 때 능력을 얻고 늘 교통할 때 풍성 흡수해<br/>',NULL,31255,6);
INSERT INTO stanza VALUES('K418','7','주 안에 살길 내 영 사모해 늘 교통하길 성령 강권해<br/>주 안에 흠뻑 적셔짐으로 주님과 조화되기 원하네<br/>',NULL,31256,7);
INSERT INTO stanza VALUES('K419','1','주 예수는 포도-나무 나는 그의 가진데<br/>나는 나는 어이-하여 열매 맺지- 못하나<br/>',NULL,31257,1);
INSERT INTO stanza VALUES('K419','2','나는 많은 열매- 맺어 주의 생명 나타내<br/>기도 응답받고- 주께 영광 돌리-기 원해<br/>',NULL,31258,2);
INSERT INTO stanza VALUES('K419','3','나는 항상 주님- 안에 거하지 못하였네<br/>거하려고 구할-수록 밖에 있는- 것 같아<br/>',NULL,31259,3);
INSERT INTO stanza VALUES('K419','4','기도하고 뜻 세-우나 주 안에 있지 않고<br/>주와 멀리 떨어-진듯 생명 열매- 없다네<br/>',NULL,31260,4);
INSERT INTO stanza VALUES('K419','5','주는 포도나무-시요 나는 가지인 것을<br/>믿을 때에 성령-께서 이 사실 이-루셨네<br/>',NULL,31261,5);
INSERT INTO stanza VALUES('K419','6','이미 주 안에 있-으니 다시 구하지 않네<br/>나는 주와 연합-되어 온전하게- 하나 돼<br/>',NULL,31262,6);
INSERT INTO stanza VALUES('K419','7','내가 가서 거하지 않네 이미 주 안에 있네<br/>이미 내가 얻은- 위치 안 떠나면- 된다네<br/>',NULL,31263,7);
INSERT INTO stanza VALUES('K419','8','주 안에서 거하-는 것 하나님이 이뤘네<br/>기도 노력 필요-없이 하나님이- 주셨네<br/>',NULL,31264,8);
INSERT INTO stanza VALUES('K419','9','어리석은 노력- 끊고 주를 찬양하여라<br/>거짓 없는 말씀-만을 다만 믿고- 누리라<br/>',NULL,31265,9);
INSERT INTO stanza VALUES('K419','10','주 안에서 안식-할 때 주 내 모든 것 되네<br/>주 내 생명 능력-이니 내 모든 것- 끝났네<br/>',NULL,31266,10);
INSERT INTO stanza VALUES('K42','1','아버지께 겸손히 무릎 꿇고 경배해<br/>제물되신 주 인해 - 아버지 경배해<br/>',NULL,31267,1);
INSERT INTO stanza VALUES('K42','2','깊고 넓고 큰 사랑 죽음으로 임했네<br/>은혜 공의 얻은 나 - 아버지 경배해<br/>',NULL,31268,2);
INSERT INTO stanza VALUES('K42','3','본래 더러운 죄인 하나님 아들 됐네<br/>이 어떠한 은혠가 - 아버지 경배해<br/>',NULL,31269,3);
INSERT INTO stanza VALUES('K42','4','주는 나의 실재니 영 안에서 경배해<br/>향기로운 제사로 - 아버지 경배해<br/>',NULL,31270,4);
INSERT INTO stanza VALUES('K42','5','깊은 속에서부터 다시 감사 찬송해<br/>한량없는 사랑에 - 아버지 경배해<br/>',NULL,31271,5);
INSERT INTO stanza VALUES('K420','1','주님 안에서 거하기 원해 늘 주와 끊어지지 않도록<br/>포도나무가 연결되듯이 나 또한 주님 안에 거하리<br/>',NULL,31272,1);
INSERT INTO stanza VALUES('K420','2','주 안에 거해 풍성 누릴 때 나 통해 주의 모든 것 흘러<br/>주님의 연한 가지 되어서 주 열매 항상 맺기 원하네<br/>',NULL,31273,2);
INSERT INTO stanza VALUES('K420','3','주 안에 거해 연결할 때에 죄악과 자아 권능 잃으며<br/>주의 생명을 이기지 못해 영이 혼 모든 행동 통제해<br/>',NULL,31274,3);
INSERT INTO stanza VALUES('K420','4','주 안에 거해 주의 뜻 아네 주 임재 안에 그 비밀 만져<br/>기쁨과 평강 내게 충만해 주 말씀 공급 내 능력 되네<br/>',NULL,31275,4);
INSERT INTO stanza VALUES('K421','1','주님 없으면 나는 설자리 없다네<br/>능력도 선한 것도 내게는 없다네<br/>사랑의 주가 내게 모든 것 되시니<br/>주 부축 받을 때에 약함 축복이 돼<br/>',NULL,31276,1);
INSERT INTO stanza VALUES('K421','2','주 없으면 이 길은 너무도 피곤해<br/>난 찬송 대신 탄식 내쉬는 약한 자<br/>난 길을 모르지만 주님은 아시니<br/>길 잃지 않게 나를 인도해 주소서<br/>',NULL,31277,2);
INSERT INTO stanza VALUES('K421','3','주 없으신 것 나는 상상할 수 없어<br/>사랑의 구주 항상 날 가까이하네<br/>달콤한 주의 교통 안식이 없다면<br/>이 삭막한 세상엔 외롬과 고통뿐<br/>',NULL,31278,3);
INSERT INTO stanza VALUES('K421','4','주 없으면 난 몰라 내 영의 깊은 뜻<br/>내 마음 속에 와서 설명할 자 없네<br/>날 위안하여 주며 날 잠잠케 할 자<br/>내 주님뿐이시네 주만이 하시네<br/>',NULL,31279,4);
INSERT INTO stanza VALUES('K421','5','주 없으면 난 홀로 이 강을 건너리<br/>파도가 강하여도 주 나를 안 떠나<br/>주 여전히 나에게 사랑을 베풀며<br/>낮은 소리로 항상 속삭여 주시리<br/>',NULL,31280,5);
INSERT INTO stanza VALUES('K422','1','하늘에 내게 주 외에 누가 또 있으리<br/>날 위하신 내 주님을 끝까지 찬송해<br/>날 위해 피를 흘린 주 고난 받고 속죄양 됐네<br/>날 하나님과 영원히 화목게 하셨네<br/>',NULL,31281,1);
INSERT INTO stanza VALUES('K422','2','다른 복 원치 않으리 주님만 구하리<br/>도금한 세상 버리고 주님만 원하리<br/>내 자신 위한 축복은 순식간에 사-라지나<br/>주 주신 기쁨 영원해 주님만 필요해<br/>',NULL,31282,2);
INSERT INTO stanza VALUES('K422','3','부하려는 맘 버리네 주는 날 위하네<br/>내 평안 안락 구찮네 주는 날 위하네<br/>내 소득 많지 않아도 내 쌓은 재산- 없어도<br/>기쁨으로 주 찬미해 주는 날 위하네<br/>',NULL,31283,3);
INSERT INTO stanza VALUES('K422','4','내 맘 온전히 안식해 주는 날 위하네<br/>시험도 두렵지 않네 주는 날 위하네<br/>유혹이 맹렬하여도 주 의지하여- 강하리<br/>무익한 유혹 비웃네 주는 날 위하네<br/>',NULL,31284,4);
INSERT INTO stanza VALUES('K422','5','내 인생길 다 가도록 주님만 필요해<br/>그의 팔 의지하겠네 주님만 필요해<br/>내 몸에 고통 있어도 내 타고난 힘- 쇠해도<br/>소리를 높여 찬송해 주님만 필요해<br/>',NULL,31285,5);
INSERT INTO stanza VALUES('K423','1','내 의지 능력 약하고 내 소망 다 소멸-됐네<br/>오직 주 내게 역-사해 부축하심만 의-지해<br/>',NULL,31286,1);
INSERT INTO stanza VALUES('K423','2','나의 힘 다 쏟았어도 그 결과 실패뿐-이니<br/>주 외엔 믿을 것- 없네 주 날 지킴만 믿-겠네<br/>',NULL,31287,2);
INSERT INTO stanza VALUES('K423','3','내 마음 높아질 때에 위험한 땅에 넘-어져<br/>어떤 일 어떤 곳-에나 주님만 내게 필-요해<br/>',NULL,31288,3);
INSERT INTO stanza VALUES('K423','4','강한 주 날 체휼하니 주 얼굴만을 구-하네<br/>나는 악하고 약-해도 주 은혜 내 능력-일세<br/>',NULL,31289,4);
INSERT INTO stanza VALUES('K424','1','내- 마음 주-님- 안에 참- 안식 누-리-네<br/>죄 - 인이 찬-양-하는 전-능한 주- 예-수<br/>주 빛은 나의 지혜 날 근면-케 하네<br/>주 영광의 위치로 날마다- 인-도-해<br/>',NULL,31290,1);
INSERT INTO stanza VALUES('K424','2','내- 죄는 크-고- 크나 주- 은혜 더- 크-네<br/>어-린 양 죽-음-으로 난- 형벌 면-했-네<br/>나 죄에서 해방돼 죄 먼지- 떠났네<br/>주 말씀 내 빛이요 주의 피- 내- 보-배<br/>',NULL,31291,2);
INSERT INTO stanza VALUES('K424','3','온-유한 주-의- 목적 내-게서 이-뤄-져<br/>주- 뜻을 행-하-도록 내- 일생 드-리-네<br/>난 실로 약하지만 주 내 능-력이니<br/>주 당신 소유할 때 범사에- 풍-성-해<br/>',NULL,31292,3);
INSERT INTO stanza VALUES('K424','4','어-두움 날- 덮-을 때 주- 내게 가-깝-네<br/>내-믿음 견-고-케 해 강-하게 하-소서<br/>주 품에 편히 누워 주 얼굴- 주목해<br/>주 나의 안식처니 사탄은- 도-망-해<br/>',NULL,31293,4);
INSERT INTO stanza VALUES('K424','5','주-만 날 기-쁘-게 해 날- 해방하-시-네<br/>영-원히 주- 찬-양해 영-원히 찬-송-해<br/>이 땅의 사랑 복락 다 마를-지라도<br/>나 살든 죽든 오직 주 공급- 원-하-네<br/>',NULL,31294,5);
INSERT INTO stanza VALUES('K425','1','나는 피조된 그릇 보배인 주 담았네<br/>나는 주님의 그릇 주는 내 안의 내용<br/>',NULL,31295,1);
INSERT INTO stanza VALUES('K425','2','주 형상대로 지어 주 거하기 적합해<br/>내용인 주 담도록 하나님 날 지었네<br/>',NULL,31296,2);
INSERT INTO stanza VALUES('K425','3','주는 지금 내 영에 거하며 날 붙드네<br/>나는 그와 한 영 돼 실재의 공급 받네<br/>',NULL,31297,3);
INSERT INTO stanza VALUES('K425','4','매일 내 속에 거해 교통하며 가르쳐<br/>주가 나의 각 부분 적시며 보호하네<br/>',NULL,31298,4);
INSERT INTO stanza VALUES('K425','5','그를 표현함으로 사람들이 주 보리<br/>내가 투명할 때에 주 날 통해 나타나<br/>',NULL,31299,5);
INSERT INTO stanza VALUES('K425','6','내 온 존재 부서져 변화되기 원하네<br/>흙의 모습 변하여 보배 모양 되겠네<br/>',NULL,31300,6);
INSERT INTO stanza VALUES('K426','1','말씀 빛 가운데 주와 함께할 때 영광 내 온 몸 비추시네<br/>주의 말씀 믿고 주께 순종할 때 주가 내 영을 충만케 해<br/>',NULL,31301,1);
INSERT INTO stanza VALUES('K426','chorus','다만 믿고 주께 순종하라<br/>주 기뻐하심 위해 믿고 순종하라<br/>',NULL,31302,2);
INSERT INTO stanza VALUES('K426','2','주의 웃는 얼굴 내게 나타날 때 어떤 어둠도 날 못 덮네<br/>믿고 순종할 때 두려움 사라져 눈물 근심 다 사라지네<br/>',NULL,31303,3);
INSERT INTO stanza VALUES('K426','3','모든 무거운 짐 주가 돌보시네 모든 어려움 돌보시네<br/>믿고 순종할 때 모든 고통 손실 모든 수치 다 축복 되리<br/>',NULL,31304,4);
INSERT INTO stanza VALUES('K426','4','나를 제단 위에 놓지 않을 때에 주의 사랑을 이해 못해<br/>믿고 순종할 때 진정 맛보리라 주가 주시는 찬송 기쁨<br/>',NULL,31305,5);
INSERT INTO stanza VALUES('K426','5','믿고 순종할 때 주의 빛 가운데 달콤한 교통 누리겠네<br/>주와 한 보조로 함께 전진하리 주의 보내심 받고 가리<br/>',NULL,31306,6);
INSERT INTO stanza VALUES('K427','1','주님 나를 부르시네 주님 나를 부르시네<br/>좁은 길을 오라 하네 주를 따라 오라 하시네<br/>',NULL,31307,1);
INSERT INTO stanza VALUES('K427','chorus','어디서나 언제든지 그를 따라 오라 하네<br/>평안에나 위험에나 물러서지 말라 하시네<br/>',NULL,31308,2);
INSERT INTO stanza VALUES('K427','2','주의 부름 응답하리 주의 부름 응답하리<br/>단 맘으로 일생토록 나의 주를 따라 가리라<br/>',NULL,31309,3);
INSERT INTO stanza VALUES('K427','chorus','어디서나 언제든지 나의 주를 따르겠네<br/>평안에나 위험에나 물러서지 않고 따르리<br/>',NULL,31310,4);
INSERT INTO stanza VALUES('K427','3','친구 세상 버리고 친구 세상 버리고서<br/>단 맘으로 일생토록 나의 주를 따라 가리라<br/>',NULL,31311,5);
INSERT INTO stanza VALUES('K427','4','십자가를 지고 가리 십자가를 지고 가리<br/>좁은 길을 단 맘으로 일생토록 주를 따르리<br/>',NULL,31312,6);
INSERT INTO stanza VALUES('K427','5','다시 돌아서지 않고 계속 전진하며 가리<br/>단 맘으로 일생토록 나의 주를 따라 가겠네<br/>',NULL,31313,7);
INSERT INTO stanza VALUES('K428','1','내 몸- 고통 있다해도 단 맘으로 주 따라<br/>한 걸-음- 한 걸-음 주 발자취 따르리<br/>한 걸음 한 걸음 주 예수 따르리<br/>날마다 날마다 좁은 길을 가리<br/>',NULL,31314,1);
INSERT INTO stanza VALUES('K428','2','주를- 따라 행할 때에 빛 속에 늘 살겠네<br/>순간- 순간 주를 따라 좁은 길을 가겠네<br/>한 걸음 한 걸음 주 예수 따르리<br/>매순간 주따라 좁은 길을 가리<br/>',NULL,31315,2);
INSERT INTO stanza VALUES('K428','3','사방-에서 고난 와도 두려움이 없겠네<br/>한 걸-음씩 주를 따라 주의 인도 좇으리<br/>한 걸음 한 걸음 주 따르리<br/>어디든 주 따라 좁은 길을 가리<br/>',NULL,31316,3);
INSERT INTO stanza VALUES('K428','4','주를- 따라 행할 때에 주와 왕국 얻으리<br/>주의- 푯대 향해 가며 좁은 길을 가겠네<br/>한 걸음 한 걸음 주 예수 따르리<br/>언제나 어디나 주를 따라 가리<br/>',NULL,31317,4);
INSERT INTO stanza VALUES('K429','1','영문 밖에 나가서 주 예수 가까이 해<br/>주의 능욕 지고서 주의 수치 견디리<br/>',NULL,31318,1);
INSERT INTO stanza VALUES('K429','2','영문 밖에 나가서 십자가 고통 지고<br/>주가 가신 좁은 길 단 맘으로 좇으리<br/>',NULL,31319,2);
INSERT INTO stanza VALUES('K429','3','영문 밖에 나가서 사람의 정 끊으리<br/>아버지 뜻 따르신 주를 따라 가겠네<br/>',NULL,31320,3);
INSERT INTO stanza VALUES('K429','4','영문 밖에 나가서 주만 가까이하리<br/>세상 조직 떠나서 주 예수를 따르리<br/>',NULL,31321,4);
INSERT INTO stanza VALUES('K429','5','모두 나를 버려도 영문 밖에 나가리<br/>주 내 배필이시니 고통 와도 만족해<br/>',NULL,31322,5);
INSERT INTO stanza VALUES('K429','6','영문 밖에 나가서 주와 동행하겠네<br/>주 얼굴 내 격려요 주 임재 내 거철세<br/>',NULL,31323,6);
INSERT INTO stanza VALUES('K429','7','영문 밖에 나가리 주 다시 올 때까지<br/>그날 주 칭찬 얻고 왕국에 들어가리<br/>',NULL,31324,7);
INSERT INTO stanza VALUES('K43','1','내 아버지의 큰 사랑 끝없는 사랑 안에<br/>은혜의 가르 - 침 받아 즐거움 넘쳐나네<br/>저 창세 전에 예정해 우리를 선택하사<br/>이 시간 안에 - 은혜로 큰 구원 이루셨네<br/>',NULL,31325,1);
INSERT INTO stanza VALUES('K43','2','죽은 자 중에 살아나 으뜸이 되신 주님<br/>역사 다 이루 - 셨으니 우린 주 승리 믿네<br/>그 맏아들을 인하여 다 아들들 된 우리<br/>늘 즐거움이 - 넘치니 어찌 찬송 않으리<br/>',NULL,31326,2);
INSERT INTO stanza VALUES('K43','3','그분의 하나님께서 우리 하나님 되고<br/>그분의 아버 - 지께서 우리 아버지 됐네<br/>우리는 그의 뼈와 살 나뉘어질 수 없네<br/>이제 회중서 - 다 함께 아버지 찬양하네<br/>',NULL,31327,3);
INSERT INTO stanza VALUES('K43','4','신성한 사랑과 은혜 영원한 연합이여<br/>이는 곧 영원 - 한 분깃 아버지 기쁨일세<br/>이제 우리는 그 아들 강림을 기다리니<br/>우리의 모든 - 갈망은 즐거운 가락일세<br/>',NULL,31328,4);
INSERT INTO stanza VALUES('K430','1','하나님이 미리 알고 예정한 자를 부르시어 그 아들 형상<br/>',NULL,31329,1);
INSERT INTO stanza VALUES('K430','chorus','본받게해 아들 형상 하나님의 아들 형상 본받게 하시네<br/>',NULL,31330,2);
INSERT INTO stanza VALUES('K430','2','하나님의 아들 형상 본받게 하려고 성령 항상 탄식하네<br/>',NULL,31331,3);
INSERT INTO stanza VALUES('K430','3','하나님의 아들 형상 본받게 하려고 내 속 성령 역사하네<br/>',NULL,31332,4);
INSERT INTO stanza VALUES('K430','4','성령역사 중재 기도 우릴 주의 형상으로변하게 하시네<br/>',NULL,31333,5);
INSERT INTO stanza VALUES('K430','5','주를사랑하는 자를 변케 하려 모든 것이 다 협력한다네<br/>',NULL,31334,6);
INSERT INTO stanza VALUES('K430','6','아들형상 본받을 때 하나님은많은 아들 얻을 수가 있네<br/>',NULL,31335,7);
INSERT INTO stanza VALUES('K430','7','영광얻게 하시려고우릴 그의 아들 형상 본받게 하시네<br/>',NULL,31336,8);
INSERT INTO stanza VALUES('K430','8','아들형상 본받도록그리스도 사랑 항상 끊어지지않네<br/>',NULL,31337,9);
INSERT INTO stanza VALUES('K431','1','보라 천한 그-릇 통해 주의 은혜 비-췬다<br/>피곤하고 외로운 맘에 주 얼굴-빛 발한다<br/>',NULL,31338,1);
INSERT INTO stanza VALUES('K431','2','하늘 빛이 충-만한 주 오늘 이 땅 비-춘다<br/>사람 속의 생-명의 영 사망 그-늘 비춘다<br/>',NULL,31339,2);
INSERT INTO stanza VALUES('K431','3','질그릇이 표 -현하는 영광스런 하-나님<br/>사람 통해 나-타난 주 사랑스럽고 달콤해<br/>',NULL,31340,3);
INSERT INTO stanza VALUES('K431','4','질그릇은 천-하여도 안의 보배 귀-하다<br/>영광 빛 늘 새-로우며 변치 않-는 보배라<br/>',NULL,31341,4);
INSERT INTO stanza VALUES('K431','5','연약한 이 질-그릇에 하나님이 담-겨져<br/>측량할 수 없-이 귀한 보배 늘- 나타낸다<br/>',NULL,31342,5);
INSERT INTO stanza VALUES('K432','1','하나님 내 맘 비췰 때 난 옛 것 벗고 새롭네<br/>난 보배 담은 질그릇 주 크신 능력 나타내<br/>',NULL,31343,1);
INSERT INTO stanza VALUES('K432','chorus','보배를 담은 질그릇 큰 능력 나타내겠네<br/>큰 능력 나타내겠네<br/>',NULL,31344,2);
INSERT INTO stanza VALUES('K432','2','사방에 우겨싸여도 싸이지 아니하겠네<br/>핍박을 받을지라도 버린 바 되지 않으리<br/>',NULL,31345,3);
INSERT INTO stanza VALUES('K432','3','답답한 일을 당해도 낙심치 아니하겠네<br/>거꾸러뜨림 당해도 망하지 아니하리라<br/>',NULL,31346,4);
INSERT INTO stanza VALUES('K432','4','주 죽음 짊어질 때에 주 생명 나타나겠네<br/>내 안에 사망 역사해 주 생명 나타내리라<br/>',NULL,31347,5);
INSERT INTO stanza VALUES('K432','5','하나님 주 살렸으니 나 또한 살리시리라<br/>겉사람 후패하여도 속사람 날로 새롭네<br/>',NULL,31348,6);
INSERT INTO stanza VALUES('K433','1','나 아닌 주만 높여지시기를 나 아닌 주만 믿은 바 되길<br/>말과 행동과 생각과 태도에 나 아닌 주만 나타나기를<br/>',NULL,31349,1);
INSERT INTO stanza VALUES('K433','chorus','주여 날 자신서 벗어나 주 안에 있게 해<br/>나 아닌 주만 내 안에서 거하옵소서<br/>',NULL,31350,2);
INSERT INTO stanza VALUES('K433','2','나 아닌 주가 모든 것의 시작 나 아닌 주가 공급의 근원<br/>나 아닌 주가 나의 일의 목적 나 아닌 주가 생활의 목표<br/>',NULL,31351,3);
INSERT INTO stanza VALUES('K433','3','오직 주님뿐 다신 한담 없고 오직 주님뿐 분요 없으리<br/>오직 주님뿐 자신 연민 없고 오직 주님뿐 자존 없으리<br/>',NULL,31352,4);
INSERT INTO stanza VALUES('K433','4','오직 주 예수 내겐 자랑 없네 오직 주 예수 내 자유 없네<br/>오직 주 예수 무거운 짐 없네 오직 주 예수 두려움 없네<br/>',NULL,31353,5);
INSERT INTO stanza VALUES('K433','5','오직 주 예수 나의 시야 채워 뛰어난 영광 곧 나타나리<br/>오직 주님께 영영 감사하리 주 그리스도 나의 모든 것<br/>',NULL,31354,6);
INSERT INTO stanza VALUES('K434','1','하늘 보배 그의 가치 말로 다 할 수 없네<br/>하나님의 사랑하는 아들 주 그리스도<br/>하늘서나 땅에-서나 유일하신 보배-인<br/>주가 내게 보인 사랑 사람들은 모르네<br/>',NULL,31355,1);
INSERT INTO stanza VALUES('K434','2','주가 택한 그릇들을 주가 친히 채우네<br/>영원하고 무궁하며 비교 못할 가치로<br/>하늘 영광 안에- 친히 성령으로 채우-네<br/>사모하는 모든 맘을 사랑으로 채우네<br/>',NULL,31356,2);
INSERT INTO stanza VALUES('K434','3','시련 시험 몰려와도 부르심은 너의 것<br/>포도나무 가지인 너 주께 자신 비우라<br/>질그릇은 비천-하여 세상 멸시 받아-도<br/>하나님의 보배 담아 주의 영광 표현해<br/>',NULL,31357,3);
INSERT INTO stanza VALUES('K434','4','더 비우고 겸손하여 드러내지 않으리<br/>다만 주의 영광으로 충만한 그릇 되리<br/>어느 때나 어디-서나 영광 가리지 않으리<br/>주님으로 채워져서 주의 미덕 전하리<br/>',NULL,31358,4);
INSERT INTO stanza VALUES('K435','1','아담에 속한 것 죄와 사망뿐 주 안에서 의와 생명을 얻네<br/>육신에 거할 때 아담 표현해 영 안에 있을 때 주님 나타내<br/>',NULL,31359,1);
INSERT INTO stanza VALUES('K435','2','아담 안에서는 죄 안 지어도 사형 선고받은 죄인인 우리<br/>주 안에 있을 때 선행 안 해도 이미 의로워져 칭의 받았네<br/>',NULL,31360,2);
INSERT INTO stanza VALUES('K435','3','육신 안에서 나 노력 안 해도 아담의 죄 성품 표현하게 돼<br/>영 안에서 노력 열심 없어도 주님처럼 살고 왕 노릇 하네<br/>',NULL,31361,3);
INSERT INTO stanza VALUES('K435','4','주와 함께 죽어 아담 떠나고 주와 함께 살아 생명 얻었네<br/>육에 생각 두면 옛 아담 사나 영에 생각 두면 생명 확증돼<br/>',NULL,31362,4);
INSERT INTO stanza VALUES('K436','1','주는 나의 생명 나의 참 평강<br/>그 영 안에 주와 연결케 하네<br/>',NULL,31363,1);
INSERT INTO stanza VALUES('K436','chorus','그 영 좇아 행해 주 안에 살 때-<br/>생명 맛보면서 평강 누리네<br/>',NULL,31364,2);
INSERT INTO stanza VALUES('K436','2','이미 주께 속해 묶임 더 없네<br/>생명 성령의 법 나를 해방해<br/>',NULL,31365,3);
INSERT INTO stanza VALUES('K436','3','육신 생각 않고 영의 생각해<br/>육신 좇지 않고 영 좇아 행해<br/>',NULL,31366,4);
INSERT INTO stanza VALUES('K436','4','다시 하나님 법 거역 않으리<br/>율법보다 나은 의를 가졌네<br/>',NULL,31367,5);
INSERT INTO stanza VALUES('K436','5','내 영 안의 그 영 날 신령케 해<br/>죽을 몸까지도 살리시겠네<br/>',NULL,31368,6);
INSERT INTO stanza VALUES('K436','6','나의 영과 그 영 한 영 되어서<br/>하나님 자녀 됨 증거하시네<br/>',NULL,31369,7);
INSERT INTO stanza VALUES('K437','1','나의 마음 만족게 한 그리스도 얻-겠네<br/>세상 자랑 다 버리고 그리스도 얻-겠네<br/>',NULL,31370,1);
INSERT INTO stanza VALUES('K437','chorus','다 말 못할 그의 충만 그 충만을 맛-보네<br/>뛰어난 주 달콤함을 영원토록 누-리리<br/>',NULL,31371,2);
INSERT INTO stanza VALUES('K437','2','세상 버려 주 얻으리 주님만이 내- 만족<br/>그 무엇도 못 채우던 나의 마음 주가 채워<br/>',NULL,31372,3);
INSERT INTO stanza VALUES('K437','3','세상 커도 작은 내 맘 만족시킬 수- 없네<br/>작은 맘의 모든 필요 오직 주가 채-우네<br/>',NULL,31373,4);
INSERT INTO stanza VALUES('K437','4','주 있으면 기뻐 뛰고 주 없으면 근-심해<br/>나의 모든 보화 되신 주님 안에 안-주해<br/>',NULL,31374,5);
INSERT INTO stanza VALUES('K438','1','난 이미 예수 택했네 나의 세계로<br/>그 사랑 실로 내 전체 만족게 하네<br/>난 주의 그릇이니 주님만 채우네<br/>수가의 물은 마셔도 목말라<br/>',NULL,31375,1);
INSERT INTO stanza VALUES('K438','chorus','예수 예수 난 예수 택-했네<br/>내 마음 만유 근원이신 주 안에- 사네<br/>예수 예수 내 만족이시니<br/>그가 내 요구 내 원함 다 채워주시네<br/>',NULL,31376,2);
INSERT INTO stanza VALUES('K438','2','난 이미 예수 택했네 내 기쁨으로<br/>고통 날 에워싸도 나 주를 찬송해<br/>주만 있으면 난 기뻐 소리 발하네<br/>내 모든 기쁨 주 안에 있으니<br/>',NULL,31377,3);
INSERT INTO stanza VALUES('K438','3','난 이미 예수 택했네 내 소망으로<br/>주 주신 기업의 풍성 날 누리게 해<br/>이 기업이신 내 구주 나의 보밸세<br/>내 마음 오직 주만 얻기 원해<br/>',NULL,31378,4);
INSERT INTO stanza VALUES('K438','4','난 이미 예수 택했네 내 주인으로<br/>그 사랑 맛본 자 모두 주께 굴복해<br/>내 주께 다른 요구 더 할 것 없으니<br/>늘 깨어 주의 기쁨만 구하리<br/>',NULL,31379,5);
INSERT INTO stanza VALUES('K439','1','오늘 내 맘은 기뻐 노래해 주 나의 생명 평안되시니<br/>주여 내 앞길 인도하소서 주 나를 위하심 나 믿으니<br/>',NULL,31380,1);
INSERT INTO stanza VALUES('K439','chorus','모든 것이 주로 인해 골고다 인하여 이뤄졌네<br/>',NULL,31381,2);
INSERT INTO stanza VALUES('K439','2','전에 난 멸망 두려워하며 행위로 자신 장식하고서<br/>하나님 형벌 피하려 했네 이제 주만이 내 구원일세<br/>',NULL,31382,3);
INSERT INTO stanza VALUES('K439','3','그날에 죄인 통곡할 때에 주 교회 축복 속에 휴거돼<br/>주께서 휘장 안에 피 뿌려 교회가 음부의 문 이기네<br/>',NULL,31383,4);
INSERT INTO stanza VALUES('K439','4','날 위해 죄악 지신 어린 양 날 구해 영원토록 살게 해<br/>날 위해 주 진노의 잔 마셔 심판과 죽음 지나게 했네<br/>',NULL,31384,5);
INSERT INTO stanza VALUES('K439','5','주 나를 푸른 초장에 눕혀 나에게 가장 좋은 것 주네<br/>이제 나 주의 품에 기대어 주님과 교통하며 사랑해<br/>',NULL,31385,6);
INSERT INTO stanza VALUES('K439','6','비웃음 훼방 내게 닥쳐도 내 생명 아름다움 지키사<br/>늘 주를 앙망하고 의탁해 늘 기뻐하게 가르치소서<br/>',NULL,31386,7);
INSERT INTO stanza VALUES('K439','7','세상의 명성 다 거절하고 불과 물 거친 강한 얼굴로<br/>주님과 함께 수치 견디고 주 위해 순교하게 하소서<br/>',NULL,31387,8);
INSERT INTO stanza VALUES('K439','8','그 날에 인자 앞에 설 때에 못 박힌 주님 나의 시 되리<br/>하늘 떠나 인생 고초 겪고 갈보리에서 생명 버린 주<br/>',NULL,31388,9);
INSERT INTO stanza VALUES('K439','chorus','모든 것을 나로 인해 나 하나 위하여 겪으셨네<br/>',NULL,31389,10);
INSERT INTO stanza VALUES('K44','1','오 은혜 받은 자녀들이 아버지 찬송해<br/>그 생명 - 우릴 양무 - 리로 이끄니 참 즐거워<br/>',NULL,31390,1);
INSERT INTO stanza VALUES('K44','2','당신의 선물 구원 확신 난 다 찬송 못해<br/>나의 마 - 음은 하늘에 있는 당신 보좌 향 - 해<br/>',NULL,31391,2);
INSERT INTO stanza VALUES('K44','3','당신은 항상 변함없이 우리 의지 되셔<br/>죄인들 - 에게 생명 - 주고 죄인 해방했 - 네<br/>',NULL,31392,3);
INSERT INTO stanza VALUES('K44','4','영원히 주 예수의 은혜 풍성 나타내고<br/>그 아들 - 인해 자녀 된 자들 영영 감사하겠네<br/>',NULL,31393,4);
INSERT INTO stanza VALUES('K44','5','저 새벽 동이 트기까지 우린 나아가리<br/>그분이 - 오셔 사망 무덤서 올리시길 기다려<br/>',NULL,31394,5);
INSERT INTO stanza VALUES('K44','6','당신 자신이 분깃이니 기쁨 한량없네<br/>당신의 - 아들 닮아 - 그와 밝은 아침 누리리<br/>',NULL,31395,6);
INSERT INTO stanza VALUES('K44','7','오 거룩하신 아버지의 이름 우릴 지켜<br/>아무런 - 근심 걱정 - 없이 그를 좇게 하소서<br/>',NULL,31396,7);
INSERT INTO stanza VALUES('K440','1','햇볕에 밖은 검게 탔으나 빛의 아들들 속 아름다와<br/>사람들 모를 비밀한 기쁨 영광의 왕이 각각 주셨네<br/>사람이 생각 못했던 만지지 못한 것일세<br/>성도들 주의 빛에 거하여 감추인 영광 얻었-네<br/>',NULL,31397,1);
INSERT INTO stanza VALUES('K440','2','사람 보기엔 다를 바 없는 이 땅에 속한 아담의 족속<br/>타락한 많은 죄인들처럼 질병과 고통 겪으며 사네<br/>사람이 중히 여기는 헛된 용모와 자세를<br/>멸시하도록 하-려-고 똑같은 생활하게- 해<br/>',NULL,31398,2);
INSERT INTO stanza VALUES('K440','3','하나님 생명 얻은 그들은 주 말씀으로 거듭났다네<br/>신성한 사랑 불붙음으로 새 예루살렘 속한 자 됐네<br/>달콤한 시와 찬미로 지극히 높은 하나님<br/>찬미하면서 교통한다네 놀라운 소리 발하-네<br/>',NULL,31399,3);
INSERT INTO stanza VALUES('K440','4','땅에 행하나 하늘에 거해 어둠 중에서 땅을 다스려<br/>어두움 속에 주 평강 누려 빈곤함 속에 선을 이루네<br/>거꾸러뜨림 당해도 망하지 않고 일어서<br/>죽음의 그늘 가는 듯해도 무궁한 생명 살아 있네<br/>',NULL,31400,4);
INSERT INTO stanza VALUES('K440','5','그날에 주님 나타나셔서 왕 노릇 할 때 함께 나타나<br/>그리스도와 드러나리라 감추인 영광 나타나리라<br/>빛의 자녀들 일어나 빛 발하리라 저 멀리<br/>모든 성도들 해와 같으리 주님과 함께 비추-리<br/>',NULL,31401,5);
INSERT INTO stanza VALUES('K441','1','내 사랑 나의 하나님 내 영원한 분깃<br/>하늘 아래나 땅위에 주- 밖에 없다네 주 밖에 없다네<br/>',NULL,31402,1);
INSERT INTO stanza VALUES('K441','2','하늘 땅 모두 공허해 만족 주지 못해<br/>내 하나님과 비할 것 아-무 데도 없네 아무 데도 없네<br/>',NULL,31403,2);
INSERT INTO stanza VALUES('K441','3','주는 내 부요 내 생명 내 견고한 거처<br/>주만이 나의 하나님 내- 구주이실세 내 구주이실세<br/>',NULL,31404,3);
INSERT INTO stanza VALUES('K441','4','금전도 주께 비하면 공허한 장난감<br/>다른 것 의지할 때에 어-리석은 자 돼 어리석은 자 돼<br/>',NULL,31405,4);
INSERT INTO stanza VALUES('K441','5','온 땅이 내 기업 되고 내 재산 되어도<br/>주 없으면 난 여전히 가-련한 자일세 가련한 자일세<br/>',NULL,31406,5);
INSERT INTO stanza VALUES('K441','6','이 세상 사람 팔 벌려 다 재물 잡아도<br/>난 다른 것 원치 않고 주- 임재 얻겠네 주 임재 얻겠네<br/>',NULL,31407,6);
INSERT INTO stanza VALUES('K442','1','사탄에게 사로 잡혀 죄의 노예 되었던 나-<br/>주가 건져 이끄시고 주께 돌아오게 했네<br/>',NULL,31408,1);
INSERT INTO stanza VALUES('K442','chorus','주의 은혜 날 살리사 내게 새 맘 새 영 줬네<br/>내 영 안에 그 영 주사 주 성품에 참예케 해<br/>',NULL,31409,2);
INSERT INTO stanza VALUES('K442','2','맑은 물로 내게 뿌려 모든 우상 벗게 했네-<br/>돌 같은 맘 제하시고 부드러운 맘 주셨네<br/>',NULL,31410,3);
INSERT INTO stanza VALUES('K442','3','주가 나의 생명 되고 주의 신성 내 성품 돼-<br/>나는 주와 연합되어 그의 신성 나타내네<br/>',NULL,31411,4);
INSERT INTO stanza VALUES('K442','4','나는 그의 백성이요 그는 나의 하나님이니<br/>친근하게 교통하며 내 분깃 된 축복 누려<br/>',NULL,31412,5);
INSERT INTO stanza VALUES('K442','5','그리스도 내 거처요 나는 그의 풍성 누려-<br/>주 내 생명 양식 되어 날 영원히 만족게 해<br/>',NULL,31413,6);
INSERT INTO stanza VALUES('K443','1','오 어떠한 영광인가! 어떤- 거룩함인가!<br/>영원하고 풍성하며 무한-한 주의 생명<br/>강인하고 능력 있고 거룩하고 인자해<br/>',NULL,31414,1);
INSERT INTO stanza VALUES('K443','2','오 어떠한 사랑인가 이 어-떠한 은혠가<br/>하나님은 사람 안에 생명- 되기 원하셔<br/>그분 자신 영접할 때 하나님 기뻐하셔<br/>',NULL,31415,2);
INSERT INTO stanza VALUES('K443','3','오 어떠한 사랑인가 어떠-한 큰 은혠가<br/>하나님이 흘러 나와 우리- 생명 되셨네<br/>먼저 육신 되신 주님 이젠 영 돼 흐르네<br/>',NULL,31416,3);
INSERT INTO stanza VALUES('K443','4','오 얼마나 친근한가 어떠-한 실재인가<br/>하나님이 육신 안에 나타-난 그리스도<br/>죽음에서 부활하여 사람 생명 되셨네<br/>',NULL,31417,4);
INSERT INTO stanza VALUES('K443','5','오 얼마나 놀라운가 얼마-나 신실한가<br/>하나님이 그 영 되어 우리- 생명 되시네<br/>영은 그의 체현일세 실재의 표현일세<br/>',NULL,31418,5);
INSERT INTO stanza VALUES('K443','6','오 얼마나 귀중한가 오 얼-마나 참된가<br/>아버지는 아들 안에 아들-은 그 영 안에<br/>삼일 하나님이 이제 우리 생명 되셨네<br/>',NULL,31419,6);
INSERT INTO stanza VALUES('K444','1','내 목자되신 하나님 늘 은혜로 날 먹이네<br/>주 나의 모든 것 되니 또 무엇 필요하리요<br/>',NULL,31420,1);
INSERT INTO stanza VALUES('K444','2','주 나를 푸른 초장에 이끌어 만족게 하네<br/>또 시냇물로 이끌어 안식케하여 주시네<br/>',NULL,31421,2);
INSERT INTO stanza VALUES('K444','3','나 길을 잃을 때마다 주 나를 돌아오게 해<br/>난 항상 요동하여도 주 나를 인도하시네<br/>',NULL,31422,3);
INSERT INTO stanza VALUES('K444','4','이 무거운 길 나 홀로 두려워 갈 수 없으나<br/>주 막대기와 지팡이 날 부축하여 인도해<br/>',NULL,31423,4);
INSERT INTO stanza VALUES('K444','5','사방에 대적 진 쳐도 난 주의 은혜 누리네<br/>기름 내 머리 적시니 내 잔이 넘쳐 흐르네<br/>',NULL,31424,5);
INSERT INTO stanza VALUES('K444','6','주 놀라우신 사랑이 내 일생 연대 측량해<br/>주 영원하신 사랑에 내 찬양 그침 없겠네<br/>',NULL,31425,6);
INSERT INTO stanza VALUES('K445','1','하나님 생-각할 때에 내 마음 매혹돼<br/>이 땅의 헛된 것 떠나고 그 마력 거-절해<br/>',NULL,31426,1);
INSERT INTO stanza VALUES('K445','2','구원돼 멸-망 면해도 주 만족 못 이뤄<br/>주 향한 사모함 날 권해 주 갈망 갖-게 돼<br/>',NULL,31427,2);
INSERT INTO stanza VALUES('K445','3','길 좁고 협-착하여도 주가 내 거처니<br/>주 외에 무엇도 내 마음 만족게 못-하네<br/>',NULL,31428,3);
INSERT INTO stanza VALUES('K445','4','하나님 존-귀한 이름 맘 깊이 부를 때<br/>유혹하는 모든 악술들 곧 자취 감-추리<br/>',NULL,31429,4);
INSERT INTO stanza VALUES('K445','5','주 앙망하-여 믿으면 주 인도받으리<br/>산 옮길 믿-음 있다면 주 능력 역-사해<br/>',NULL,31430,5);
INSERT INTO stanza VALUES('K445','6','하나님 구-하는 이 길 더욱더 걸으라<br/>주 향한 맘-과 사모함 널 전진케- 하리<br/>',NULL,31431,6);
INSERT INTO stanza VALUES('K445','7','죄에서 해-방됐어도 생활 점검하라<br/>낮은 것 구-하지 말고 주 은혜 구-하라<br/>',NULL,31432,7);
INSERT INTO stanza VALUES('K445','8','육신은 어-려워하나 사랑 안에 이뤄<br/>주님께 나-아갈 때에 모든 것 이-기리<br/>',NULL,31433,8);
INSERT INTO stanza VALUES('K445','9','양심의 예민함 지키며 속 느낌 살피라<br/>늘 기름 부-음 따름이 성숙의 비결이라<br/>',NULL,31434,9);
INSERT INTO stanza VALUES('K446','1','내 거처인 하나님 안으로- 주께서 나를 인도하시네<br/>신성하고도 영광스런 집- 이 지성소에서 하나님과<br/>함께 거해 이 아름다운 집 여기서 하나님과 동거-해<br/>',NULL,31435,1);
INSERT INTO stanza VALUES('K446','2','나 혼자서 길 찾으려 할 때- 날이 가고 해 지나갈수록<br/>아무 것도 이루어지잖고- 아무런 진보도 없었다네<br/>유일한 길인 주님 알고서 주 인해 하나님 안에 거-해<br/>',NULL,31436,2);
INSERT INTO stanza VALUES('K446','3','놀라운 거처 영광스런 집- 하나님 거처 견고한 이 집<br/>주와 우리의 상호 거처니- 주님만 향해 살기 원하네<br/>아름다운 집 평강 넘치네 언제나 함께 주를 나누-네<br/>',NULL,31437,3);
INSERT INTO stanza VALUES('K447','1','참 기묘해 아버지 아들 성령 셋이나 본질 한 영이실세<br/>영광일세 하나님 내 맘 속에 들어와 계셔 내 공급되네<br/>',NULL,31438,1);
INSERT INTO stanza VALUES('K447','chorus','삼일의 하나님 내 모든 것 참 기묘한 자랑일세<br/>신성의 성분 쓰고도 남네 높고 귀한 영광일세<br/>',NULL,31439,2);
INSERT INTO stanza VALUES('K447','2','참 풍성해 성부는 모든 근원 모든 것 주사 누리게 하네<br/>아 복되네 모든 것 내게 주사 끝없이 써도 여전히 남네<br/>',NULL,31440,3);
INSERT INTO stanza VALUES('K447','3','참 기묘해 성부는 육신 입고 아들이 되어 나와 동거해<br/>참 놀라운 십자가 구속으로 죄인이 주와 연합되었네<br/>',NULL,31441,4);
INSERT INTO stanza VALUES('K447','4','참 기묘해 영은 곧 아들의 영 내 영에 오사 생명 공급돼<br/>기쁨일세 영과 영 연합하여 두 영이 한 영 되어 접촉해<br/>',NULL,31442,5);
INSERT INTO stanza VALUES('K447','5','참 실젤세 하나님 모든 것이 영 안에 담겨 내 안에 왔네<br/>기이하네 주 나와 하나되어 그 생명 성품 떠나지 않네<br/>',NULL,31443,6);
INSERT INTO stanza VALUES('K448','1','기묘한 하나님 찬-양해 내 주를 만지게 하셨네<br/>원래는 가까이 못하던 주 지금은 내 영 안에서 친근하네<br/>',NULL,31444,1);
INSERT INTO stanza VALUES('K448','2','아버지 아-들 성-령인 삼일의 하나님 생명 돼<br/>내 안에 살 -며 모-든- 공급해 주 성품- 내 안에 있네<br/>',NULL,31445,2);
INSERT INTO stanza VALUES('K448','3','영광의 아버지 아들 안에 아들은 영 되신 큰 비밀<br/>그 영이 임 -해 바-람-같-이 내게 참-된 경-험 돼<br/>',NULL,31446,3);
INSERT INTO stanza VALUES('K448','4','아버지 모든 것 아들 안에 아들의 풍성은 영 안에<br/>그 영이 내 몸과 맘-에- 임할 때 주는 내-게 축복 됐네<br/>',NULL,31447,4);
INSERT INTO stanza VALUES('K448','5','근본인 아버지 아-들로 사람들 가운데 오셨네<br/>그 아들 지 -금 영-이- 되-어 내 안에- 와 거-하네<br/>',NULL,31448,5);
INSERT INTO stanza VALUES('K448','6','아버진 아-들 으뜸 되길 아들은 아버지 높이길<br/>성령은 아들의 영-광- 원함을 내 영 안에서 계-시해<br/>',NULL,31449,6);
INSERT INTO stanza VALUES('K448','7','그 영은 주-의 최종 모양 내 영에 들어와 계시네<br/>주 경배하-며 주- 누-리려면 주의 영-과 접-촉해<br/>',NULL,31450,7);
INSERT INTO stanza VALUES('K448','8','늘 항상 영 안에 경배하라 영 안에 교통과 기도해<br/>영 안에 찬송해 성 -령- 만질 때 항상 풍-성 누-리네<br/>',NULL,31451,8);
INSERT INTO stanza VALUES('K449','1','하나님 영광 본질인 영은 하나-님 어떠함<br/>영 외엔 다른 길 없네 영으로만 주 접촉해<br/>',NULL,31452,1);
INSERT INTO stanza VALUES('K449','2','사람의 가장 깊은 영 사람의 참-된 그 부분<br/>영으로라야 참되며 하나님 만질 수 있네<br/>',NULL,31453,2);
INSERT INTO stanza VALUES('K449','3','하나님은 영이시니 영으로 경-배하겠네<br/>그의 영 내 영에 와서 연합되기를 원하네<br/>',NULL,31454,3);
INSERT INTO stanza VALUES('K449','4','사람의 영과 주의 영 합하여 한- 영 되었네<br/>서로 안에 거하면서 교통하고 또 반향해<br/>',NULL,31455,4);
INSERT INTO stanza VALUES('K449','5','영으로 주 영접해야 주 풍성 누-릴 수 있네<br/>영 안에서 그 영 만져 하나님 경배하겠네<br/>',NULL,31456,5);
INSERT INTO stanza VALUES('K449','6','복음 집회 교통으로 사람을 영-에 이끌고<br/>말씀과 간증 기도도 영 안에 울려야 하리<br/>',NULL,31457,6);
INSERT INTO stanza VALUES('K449','7','영 안에서 기도하고 섬기며 주- 생명 만져<br/>영 안에서 자라나서 주 영광 위해 건축돼<br/>',NULL,31458,7);
INSERT INTO stanza VALUES('K449','8','주여 날 영 안에 와서 주 접촉하-게 하소서<br/>주 영과 내 영 흘러서 생명 넘치게 하소서<br/>',NULL,31459,8);
INSERT INTO stanza VALUES('K45','1','아버지 찬송하며 그 앞에 기뻐해 죽음서 해방되어<br/>아들과 함께해 청명한 빛 속에서 그 사랑 안에서<br/>당신의 은혜 나 영원히 받으리라<br/>',NULL,31460,1);
INSERT INTO stanza VALUES('K45','2','그분의 아버지가 내 아버지 되고 그분의 하나님이<br/>내 하나님 됐네 사랑의 그 아들이 날 이끄시어<br/>사랑의 은혜 영영 누리게 하셨네<br/>',NULL,31461,2);
INSERT INTO stanza VALUES('K45','3','당신의 사랑이 날 이미 감쌌으니 영원히 변치 않네<br/>그 아들 안에서 당신의 맏아들와 그 많은 형제들<br/>이 사랑 누리면서 함께 은혜 누려<br/>',NULL,31462,3);
INSERT INTO stanza VALUES('K450','1','하나님과 사람 모든 관계 영 안에 있으니<br/>영 안에 하나님 영 만져야 하나님 체험해<br/>',NULL,31463,1);
INSERT INTO stanza VALUES('K450','chorus','그 영이 영 낳고 영이 영 경배해<br/>말씀된 영 생명 풍성케 해 생수 흐르게 해<br/>',NULL,31464,2);
INSERT INTO stanza VALUES('K450','2','하나님은 바로 영이시니 영으로 경배해<br/>생명으로 그를 영접하고 공급을 누리네<br/>',NULL,31465,3);
INSERT INTO stanza VALUES('K450','3','내 영 안에 영인 주 들어와 날 중생케 했네<br/>난 영 안에 주와 교통하여 주 풍성 누리네<br/>',NULL,31466,4);
INSERT INTO stanza VALUES('K450','4','주 영으로 나를 채우시고 변화시켜 주네<br/>내 영에서 나의 온 존재 다 적셔질 때까지<br/>',NULL,31467,5);
INSERT INTO stanza VALUES('K450','5','영이신 주 나와 연합되어 내 형상 변케 해<br/>주 표현하도록 주의 성분 내 속에 더하네<br/>',NULL,31468,6);
INSERT INTO stanza VALUES('K450','6','주 모든 풍성을 영 안에서 누리고 체험해<br/>주 모든 소유를 얻기 위해 영 안에 접촉해<br/>',NULL,31469,7);
INSERT INTO stanza VALUES('K451','1','하나님은 모든 것을 내게 주셨고<br/>그와 연결되는 길은 영 안엘세<br/>',NULL,31470,1);
INSERT INTO stanza VALUES('K451','chorus','성부 성자 모든 풍성 영 안에 있네<br/>내 영 사용할 때 주 영 접촉하네<br/>',NULL,31471,2);
INSERT INTO stanza VALUES('K451','2','하나님은 그의 본성 내게 주셨고<br/>영 안에서 접촉할 때 주 만지네<br/>',NULL,31472,3);
INSERT INTO stanza VALUES('K451','3','심사로 깨달아 알고 영은 접촉해<br/>영을 떠나 머리로는 만족 없네<br/>',NULL,31473,4);
INSERT INTO stanza VALUES('K451','4','말씀 듣고 기도 않고 머리만 쓰며<br/>말씀 먹고 교제 없인 누림 없네<br/>',NULL,31474,5);
INSERT INTO stanza VALUES('K451','5','오 놀라운 풍성 영광 영의 하나님<br/>하나님 모든 좋은 것 다 주셨네<br/>',NULL,31475,6);
INSERT INTO stanza VALUES('K452','1','성령은 전달된 하-나님 그로서 하나님 내 안에 와<br/>나의 생명 내용 되고 생생한 나의 체험됐네<br/>',NULL,31476,1);
INSERT INTO stanza VALUES('K452','2','근원인 하나님 아-버지 표현인 하나님 아들 예수<br/>내 안에 오신 성령이 그 모든 풍성 얻게 했네<br/>',NULL,31477,2);
INSERT INTO stanza VALUES('K452','3','가까이 못 가는 빛 가운데 거하는 하나님 아-버지<br/>아들로서 나타나고 영으로서 내 영에 왔네<br/>',NULL,31478,3);
INSERT INTO stanza VALUES('K452','4','아버지 하나님 아들 안에 사람들 가운데 오-셨네<br/>아들은 또한 영 되어 사람 안으로 들어왔네<br/>',NULL,31479,4);
INSERT INTO stanza VALUES('K452','5','아들로 체현된 아 -버지 아들을 통해서 나타났네<br/>아들의 실재인 성령 내 은혜 되어 누리게 해<br/>',NULL,31480,5);
INSERT INTO stanza VALUES('K452','6','하나님 아버지 사-랑과 아들의 넘치는 은-혜가<br/>성령의 교통으로써 나에게 모두 전-달돼<br/>',NULL,31481,6);
INSERT INTO stanza VALUES('K453','1','더 가까이하리 내 하나님 앞길에<br/>십자가 있-더라도 더 가까이하리<br/>더 가까이하리 내 하나님과 더 친-근하리<br/>',NULL,31482,1);
INSERT INTO stanza VALUES('K453','2','나그네 되어서 표류해도 돌베게<br/>베고서 잠-들어도 꿈 속에서도<br/>난 주 가까이하리 내 하나님과 더 친-근하리<br/>',NULL,31483,2);
INSERT INTO stanza VALUES('K453','3','하늘로 통하는 사다리 길 천사가<br/>나타나 오-르내려 내 모든 것<br/>주의 은혜 긍휼이니 더 주께 가도록 부-르소서<br/>',NULL,31484,3);
INSERT INTO stanza VALUES('K453','4','잠 깨어 감사와 찬양 드려 고통의<br/>돌 베게 성-전 되리 고난 괴롬 올 때<br/>주 더 가까이해 내 하나님과 더 친-근하리<br/>',NULL,31485,4);
INSERT INTO stanza VALUES('K453','5','기쁨이 새처럼 하늘 날 때 해와 달<br/>별들이 반-짝일 때 여전히 부르리<br/>이 찬미 찬송을 내 하나님과 더 친-근하리<br/>',NULL,31486,5);
INSERT INTO stanza VALUES('K454','1','갈보리 산 위에 십자가 섰으니 주가 고난을 당한 표라<br/>험한 십자가를 내가 사랑함은 주가 보혈을 흘림일세<br/>',NULL,31487,1);
INSERT INTO stanza VALUES('K454','chorus','최후 승리를 얻기까지 주의 십자가 사랑하리<br/>빛난 면류관 받기까지 주의 십자가 붙들겠네<br/>',NULL,31488,2);
INSERT INTO stanza VALUES('K454','2','멸시함을 받은 주의 십자가에 나의 마음이 끌리도다<br/>귀한 어린 양이 영광 다 버리고 험한 십자가 지셨도다<br/>',NULL,31489,3);
INSERT INTO stanza VALUES('K454','3','험한 십자가에 주가 흘린 피를 믿는 맘으로 바라보니<br/>나를 용서하고 내 죄 사하시려 주가 흘리신 보혈일세<br/>',NULL,31490,4);
INSERT INTO stanza VALUES('K454','4','영영 충성하리 주님의 십자가 수치 비웃음 받더라도<br/>주님 오실 그 때 그의 얼굴 보며 영원히 영광 누리리라<br/>',NULL,31491,5);
INSERT INTO stanza VALUES('K455','1','주 십자가 나-의 자랑 영원하고 유일해<br/>신성한 빛 광-채- 속에 중심으로 있도다<br/>',NULL,31492,1);
INSERT INTO stanza VALUES('K455','2','환난 곤욕 몰-려와도 근심 나를 묶어도<br/>주 십자가 날- 버리잖네 보라 이 기쁨 평강<br/>',NULL,31493,2);
INSERT INTO stanza VALUES('K455','3','복된 태양 사-랑 빛이 나의 노정 비추네<br/>빛 발하는 주- 십-자가 내 인생 밝게 하네<br/>',NULL,31494,3);
INSERT INTO stanza VALUES('K455','4','고통에나 기-쁨에나 십자가 날 성별해<br/>측량 못할 평-강- 기쁨 영원히 변치 않네<br/>',NULL,31495,4);
INSERT INTO stanza VALUES('K455','5','주 십자가 내 자랑이니 언제까지나 남아<br/>신성한 빛 광-채- 속에 중심으로 있도다<br/>',NULL,31496,5);
INSERT INTO stanza VALUES('K456','1','십자가로 가까이 나를 이끄시니<br/>치료하는 생수가 값없이 흐르네<br/>',NULL,31497,1);
INSERT INTO stanza VALUES('K456','chorus','십자가 십자가 내 영원한 자랑<br/>거기서 주 날 위해 속전 지불했네<br/>',NULL,31498,2);
INSERT INTO stanza VALUES('K456','2','전에 떨던 나 이제 용서 사랑 받고<br/>밝은 새벽별 광채 날 비추심 보네<br/>',NULL,31499,3);
INSERT INTO stanza VALUES('K456','3','주여 그때 그 광경 내게 보이소서<br/>십자가 그늘 아래 전진케 하소서<br/>',NULL,31500,4);
INSERT INTO stanza VALUES('K456','4','십자가 가까이 해 늘 깨어 있으리<br/>들림 받아 주 얼굴 뵙는 그날까지<br/>',NULL,31501,5);
INSERT INTO stanza VALUES('K457','1','십자가 영원한 승리 할렐루야 할렐루야<br/>십자가 사탄 이겼네 할렐루야 할렐루야<br/>음부의 세력 흉하고 세상이 어지러워도<br/>육신 또한 강하여도 십자가로 이겼네<br/>',NULL,31502,1);
INSERT INTO stanza VALUES('K457','chorus','할렐루야 할렐루야 주 십자가 영원한 승리<br/>할렐루야 할렐루야 자랑하세 십자가<br/>',NULL,31503,2);
INSERT INTO stanza VALUES('K457','2','십자가 내 생명이라 할렐루야 할렐루야<br/>십자가 나의 권세라 할렐루야 할렐루야<br/>인정과 자아 이겼네 세상 세력도 이겼네<br/>사탄 세력도 이겼네 이기고도 남았네<br/>',NULL,31504,3);
INSERT INTO stanza VALUES('K457','3','십자가 내 깃발일세 할렐루야 할렐루야<br/>영원히 높이리로다 할렐루야 할렐루야<br/>약함이 강함이 되고 침체된 영 올라가네<br/>어둠 변해 광명 되네 나의 해방 십자가<br/>',NULL,31505,4);
INSERT INTO stanza VALUES('K458','1','감람 부서지지 않고 그 기름 못내며<br/>포도 눌러 짜지 않고 술로 변케 못하네<br/>나드 기름 내지 않고 그 향기 못 풍겨<br/>주여 이 몸 또한 귀한 상처 받았습니까<br/>',NULL,31506,1);
INSERT INTO stanza VALUES('K458','chorus','맞을 적마다 참 유익있네<br/>주님 자신 얻기 위해 거둬가기 원하네<br/>',NULL,31507,2);
INSERT INTO stanza VALUES('K458','2','주가 내 맘 줄을 퉁겨 음악 내렵니까<br/>귀한 음악 얻기 위해 매맞아야 합니까<br/>내가 꺾어질 때 겨우 그 사랑 압니까<br/>주와 친근해진다면 손해 무섭지 않네<br/>',NULL,31508,3);
INSERT INTO stanza VALUES('K458','3','항상 나를 보류하니 부끄럽습니다<br/>전에 주의 깎는 손길 마지못해 받았네<br/>지금 주 기뻐하시면 어떤 대가라도<br/>나의 느낌 어떻든지 주만 위해 따르리<br/>',NULL,31509,4);
INSERT INTO stanza VALUES('K458','4','내가 주와 모든 고락 상통치 못하면<br/>지금 주님 위해 나는 멍에 메기 원하네<br/>주여 나의 온 마음이 어떤 손해라도<br/>주여 기쁨 영광 위해 잃고 따르렵니다<br/>',NULL,31510,5);
INSERT INTO stanza VALUES('K458','5','찬미하고 찬미할 때 그 찬미 달콤해<br/>찬미하여 눈물나도 달콤한 맛 더 깊네<br/>주의 기뻐하심보다 더 귀함 없으니<br/>주여 오직 내 기도는 주님 얻기 원하네<br/>',NULL,31511,6);
INSERT INTO stanza VALUES('K459','1','십자-가 무거울-수록 하나-님 더-욱 가-까와<br/>나 십-자가 자원-할 때 흑암-의 왕- 짓밟히리<br/>주로- 인해 십자가 진 자 손실 있어-도 기뻐해<br/>',NULL,31512,1);
INSERT INTO stanza VALUES('K459','2','십자-가는 주 시-금석 무거-울수록 더 좋-아져<br/>눈물의 물 주지 않 -으면 화초-들 메-마르겠네<br/>불 통-과해 금 연단되듯 고난으로 성도 성화돼<br/>',NULL,31513,2);
INSERT INTO stanza VALUES('K459','3','십자-가 무거울-수록 믿음-이 더-욱 강해지네<br/>포도- 열매 깨어-질 때 달콤-한 즙-을 내겠네<br/>고난- 임해 믿음- 커져 상처 받은- 진주 되리<br/>',NULL,31514,3);
INSERT INTO stanza VALUES('K46','1','아버지의 그 크신 사랑에 메아리쳐<br/>아들의 이름 의지하여서 다 나오네<br/>그 아들 닮아 모든 아들들 영원토록 주 기쁨 되겠네<br/>',NULL,31515,1);
INSERT INTO stanza VALUES('K46','2','당신 기쁨인 그분 안으로 접붙여져<br/>유일한 사랑 대상 안으로 나 동참해<br/>우리도 당신 무한한 사랑 누리면서 그 영광 보겠네<br/>',NULL,31516,2);
INSERT INTO stanza VALUES('K46','3','아들과 함께 마음 합하여 찬양하네<br/>아들들 모두 기뻐 외치며 노래하네<br/>아버지 사랑 경륜 안에서 당신만이 가장 높은 근원<br/>',NULL,31517,3);
INSERT INTO stanza VALUES('K460','1','손실 없이 얻지 못해 십자가 없이 못사네<br/>한 알의 밀 안 죽으면 많-은 열매 못 맺어<br/>안 깨어지고 어떻게 온전해 열매 맺으랴<br/>안 깨어지고 어떻게 온전해 열매 맺으랴<br/>',NULL,31518,1);
INSERT INTO stanza VALUES('K460','2','나 어떤 사물 향할 때 그것이 내 혼 붙잡네<br/>황금 사슬의 노예를 벗어날 자 그 누군가<br/>내 맘에 사랑하는 것 그것이 사슬 되리라<br/>내 맘에 사랑하는 것 그것이 사슬 되리라<br/>',NULL,31519,2);
INSERT INTO stanza VALUES('K460','3','저 무르익은 들판의 풍성한 곡식 볼 때에<br/>죽은 밀알 기억하라 썩어진 자 기억하라<br/>고통과 죽음 당해도 끝까지 싸운 자 있네<br/>고통과 죽음 당해도 끝까지 싸운 자 있네<br/>',NULL,31520,3);
INSERT INTO stanza VALUES('K461','1','십자가 지는 자 고통만 당하랴<br/>십자가 지면 결국 사지로 가리<br/>사람의 타고난 힘 꺾는 십자가<br/>자아를 끝내는게 십자가라네<br/>',NULL,31521,1);
INSERT INTO stanza VALUES('K461','2','끝내는 십자가가 주님의 구원<br/>잔인한 벌 같으나 영광의 구출<br/>끝나지 않으면 주 체험 못하네<br/>나 자신 끝날 때 주 살아 내겠네<br/>',NULL,31522,2);
INSERT INTO stanza VALUES('K461','3','하나님 뜻 이루는 주의 십자가<br/>주의 큰 대적은 곧 사람의 자아<br/>혼 생명 죽어야만 자아 제해져<br/>하나님 영원한 뜻 이뤄지겠네<br/>',NULL,31523,3);
INSERT INTO stanza VALUES('K462','1','십자가의 길은 주님께 모두 드리는 걸세<br/>모두 죽음의 제단에 둘 때에 불 나타-날 수 있네<br/>',NULL,31524,1);
INSERT INTO stanza VALUES('K462','chorus','십자가의 길을 누가 가려는가 주를 위하여 누가 갈까<br/>모두 주님께 드린 사람이여 주님께 순결한가<br/>',NULL,31525,2);
INSERT INTO stanza VALUES('K462','2','다 드리겠다고 기도와 찬송 많이 했지만<br/>우리 앞에 더 무거운 십자가와 질고의 인생 있네<br/>',NULL,31526,3);
INSERT INTO stanza VALUES('K462','3','변절하지 않고 끝까지 모든 것 잃는다면<br/>너는 영원히 풍성한 생명으로 충만케 되리라<br/>',NULL,31527,4);
INSERT INTO stanza VALUES('K462','4','죽음 거쳐 생명 얻음이 주의 구원이시니<br/>주와 합하여 죽은 것 믿을 때 주 생명을 살아 내리<br/>',NULL,31528,5);
INSERT INTO stanza VALUES('K462','5','중요한 건 주의 뜻이요 나의 득실 아니니<br/>모두 분뇨로 여기면 주님의 뜻 방해 받지 않으리<br/>',NULL,31529,6);
INSERT INTO stanza VALUES('K463','1','주의 생명 흐르게 하리<br/>세상 버리고 주만 구하여<br/>주의 생명 흐르게 하리<br/>흘러 내리 주 다시 제한 않으리<br/>흘러 내리 주의 생명 흐르게 하리<br/>',NULL,31530,1);
INSERT INTO stanza VALUES('K464','1','부활 능력 아는 사람 십자가를 사랑해<br/>생명 성장하게 함은 오직 죽음뿐일세<br/>',NULL,31531,1);
INSERT INTO stanza VALUES('K464','chorus','죽음 없이는 생명이 없네<br/>오직 죽음 통해서만 생명 자라네<br/>',NULL,31532,2);
INSERT INTO stanza VALUES('K464','2','주의 형상 이루도록 나를 죽음에 넣네<br/>십자가에 머물면서 혼 생명을 부인해<br/>',NULL,31533,3);
INSERT INTO stanza VALUES('K464','3','영원하신 영을 인해 주와 함께 못 박혀<br/>사망 내게 운행할 때 생명 나타내겠네<br/>',NULL,31534,4);
INSERT INTO stanza VALUES('K465','1','우리 갈 길 보여 주는 포도나무의 생명<br/>거친 환경 고통 속에 자라나는 나무여<br/>광야에서 뒤 섞여져 제멋대로 자라나는<br/>수많은 저 야생초와 전혀 다른 나무여<br/>',NULL,31535,1);
INSERT INTO stanza VALUES('K465','2','영광스런 모양 없는 작기만한 너의 꽃<br/>거의 눈에 보이지도 않는 모습이구나<br/>자라나서 그 어느 날 열매 되는 순간까지<br/>아름다움도 화려함도 없는 작은 꽃이여<br/>',NULL,31536,2);
INSERT INTO stanza VALUES('K465','3','자라나는 가지들은 지주목에 묶여져<br/>제멋대로 가지 않고 격자따라 뻗어가<br/>땅에 깊이 뿌리 박아 양분 얻어 자라나는<br/>너는 결코 다른 길을 선택할 수 없구나<br/>',NULL,31537,3);
INSERT INTO stanza VALUES('K465','4','아름다운 너의 신록 봄의 들판 덮으며<br/>충만한 생명력 따라 자라고 또 자라네<br/>부드러운 가지들은 이리저리 감기면서<br/>푸른 하늘 향해 서서 신선한 공기 맛봐<br/>',NULL,31538,4);
INSERT INTO stanza VALUES('K465','5','새 순들이 자랑스레 하늘하늘 춤출 때<br/>포도원의 주인 오네 손에 가위 들고서<br/>연한 가지 거침없이 잘라 내네 철저하게<br/>길게 뻗힌 가지들을 하나하나 잘라 내<br/>',NULL,31539,5);
INSERT INTO stanza VALUES('K465','6','가지들이 잘릴 때에 자신 아낄 수 있나<br/>오히려 자르는 손에 온전히 다 드리네<br/>아름다움 제하는 분 상처낸 분에게 드려<br/>생명 낭비하지 않고 열매 더욱 맺도록<br/>',NULL,31540,6);
INSERT INTO stanza VALUES('K465','7','싹이 잘린 가지들은 점점 단단해지고<br/>가지마다 열매송이 주렁주렁 열린다<br/>잎새들은 태양빛에 말라 떨어져 갈 때에<br/>열매들은 익어가네 더욱더 풍성하게<br/>',NULL,31541,7);
INSERT INTO stanza VALUES('K465','8','아픔 거쳐 자라나서 열매 익어갈 때에<br/>송이 많은 가지들은 낮게 머리 숙인다<br/>온전히 다 익을 때에 가지들 위안 얻지만<br/>수확의 손 다가올 때 위로의 날 지나가<br/>',NULL,31542,8);
INSERT INTO stanza VALUES('K465','9','가지들의 모든 풍성 따내고 짓밟으리<br/>붉은 포도즙이 넘쳐 강처럼 흐르도록<br/>즙틀에서 그침없이 흘러나는 맑은 흐름<br/>달콤하고 풍성하리 온 땅 기쁘게 하리<br/>',NULL,31543,9);
INSERT INTO stanza VALUES('K465','10','모든 것을 다 주고서 스산한 모습으로<br/>헤아릴 수 없는 밤에 너는 들어가누나<br/>아무도 포도주 대가 너에게 주지 않는데<br/>넌 더 벗겨지고 잘려 헐벗은 채 서 있다<br/>',NULL,31544,10);
INSERT INTO stanza VALUES('K465','11','겨울 동안 추위 속에 떠는 사람들에게<br/>슬픔 고통 근심 속에 압박받는 이에게<br/>달콤함과 따뜻함을 포도주는 주고 있지<br/>그러나 넌 혼자 있다 얼음 속 눈 속에서<br/>',NULL,31545,11);
INSERT INTO stanza VALUES('K465','12','겨울 지나 다시 너는 열매 맺길 준비해<br/>싹을 내며 가지 벋어 푸르름의 옷 입어<br/>쓰라린 겨울의 아픔 결코 원망하지 않고<br/>새로운 신선함만을 바라며 일어선다<br/>',NULL,31546,12);
INSERT INTO stanza VALUES('K465','13','너는 손을 높이 들어 하늘 공기 마시며<br/>결코 땅에 기대거나 엎드리지 않누나<br/>가지 치는 자의 손길 웃으면서 다시 맞아<br/>마치 전에 그 아픔을 겪지 않은 자처럼<br/>',NULL,31547,13);
INSERT INTO stanza VALUES('K465','14','포도나무 가지들은 피와 즙 다 주지만<br/>잃고 아픔 당하여도 가련해지지 않아<br/>포도주를 마시는 자 즐거움 기쁨 얻지만<br/>얻고 마신 그들 과연 더 풍성해지는가<br/>',NULL,31548,14);
INSERT INTO stanza VALUES('K465','15','얻은 것에 있지 않고 잃은 것에 있다네<br/>마신 것에 있지 않고 쏟은 것에 있다네<br/>여기에서 나타나네 우리 생명 참된 분량<br/>깊은 죽음 겪은 사람 가장 큰 것 얻는다<br/>',NULL,31549,15);
INSERT INTO stanza VALUES('K465','16','자아 처리 받은 자만 최상의 주 얻으며<br/>고통 속에 있는 자를 위로해 줄 수 있네<br/>십자가를 못 누린 자 소리 나는 구리일 뿐<br/>자기 생명 미워할 때 초월 기쁨 누리네<br/>',NULL,31550,16);
INSERT INTO stanza VALUES('K466','1','죽으면은 많은 열매 맺게 되리라<br/>이는 주가 친히 하신 말씀이니라<br/>',NULL,31551,1);
INSERT INTO stanza VALUES('K466','2','진정 생명 얻으려면 죽어야 하리<br/>죽고 장사될 때 많은 열매 맺으리<br/>',NULL,31552,2);
INSERT INTO stanza VALUES('K466','3','주의 생명 능력으로 주가 널 살려<br/>너의 안에 새 생명을 충만케 하리<br/>',NULL,31553,3);
INSERT INTO stanza VALUES('K466','4','주의 생명 해방하는 주 길 가려면<br/>죽음의 길 통과할 때 생명 공급 돼<br/>',NULL,31554,4);
INSERT INTO stanza VALUES('K466','5','죽음으로 생명 얻는 비결 배우면<br/>풍성하여 넘치도록 수확 거두리<br/>',NULL,31555,5);
INSERT INTO stanza VALUES('K467','1','왜 넌 상처 없나 왜 몸에 아무 상처 없느냐 되려 너의<br/>명성 널리 퍼져 모두가 널 칭찬하는구나 왜 넌 상처 없나<br/>',NULL,31556,1);
INSERT INTO stanza VALUES('K467','2','왜 넌 상처 없나 나 홀로 나무에 달렸을 때 험한 조소<br/>잔인함 받았다 그 채찍 맞고 찔리었는데 왜 넌 상처 없나<br/>',NULL,31557,2);
INSERT INTO stanza VALUES('K467','3','왜 넌 상처 없나 선생은 수치당하였는데 네가 어찌<br/>영광 얻으려나 넌 아무런 걱정도 없구나 왜 넌 상처 없나<br/>',NULL,31558,3);
INSERT INTO stanza VALUES('K467','4','왜 넌 상처 없나 저들은 나 위하여 묶이고 불에 태워지고<br/>유배되고 광장에서 찢기운 바 됐다 왜 넌 상처 없나<br/>',NULL,31559,4);
INSERT INTO stanza VALUES('K467','5','넌 상처 없구나 난 못에 찔리운 바 되었고 질투 미움의<br/>칼에 찔렸다 넌 평안해 부족함이 없다 넌 상처 없구나<br/>',NULL,31560,5);
INSERT INTO stanza VALUES('K467','6','넌 상처 없구나 혹 세상 의지하지 않느냐 혹시 손실<br/>두려워 하느냐 멀리서 날 좇아오는 너는 왜 상처 없느냐<br/>',NULL,31561,6);
INSERT INTO stanza VALUES('K467','7','왜 넌 상처 없나 안일하고 또 무사하구나 충성 다한 자<br/>상을 얻으리 끝날까지 어린 양 좇으면 상처가 없으랴<br/>',NULL,31562,7);
INSERT INTO stanza VALUES('K468','1','바른 깃 벗어나면은 편해질 수 있지만<br/>충성된 주의 고난을 난 기억한다네<br/>',NULL,31563,1);
INSERT INTO stanza VALUES('K468','2','난 기꺼이 택하였네 갈수록 좁은 이 길<br/>이 세상에서 난 다만 나그네 된 잘세<br/>',NULL,31564,2);
INSERT INTO stanza VALUES('K468','3','주님의 웃는 얼굴만 난 주목한다네<br/>세상은 외모 구하나 난 주 기쁨 구하네<br/>',NULL,31565,3);
INSERT INTO stanza VALUES('K468','4','내 원함은 오직 날 낮춰 주님만 섬기어<br/>그날에 주님의 칭찬 얻는 것 뿐일세<br/>',NULL,31566,4);
INSERT INTO stanza VALUES('K468','5','난 매일 심판대 앞의 밝은 빛 바라봐<br/>내 모든 생활과 일들 불 통과하기 원해<br/>',NULL,31567,5);
INSERT INTO stanza VALUES('K468','6','이 세상 명예와 부귀 영광과 친구들<br/>성공과 칭송과 발전 너희가 얻으라<br/>',NULL,31568,6);
INSERT INTO stanza VALUES('K468','7','난 외롭고 가난해도 충성을 다하여<br/>끝까지 나의 주님만 따르기 원하네<br/>',NULL,31569,7);
INSERT INTO stanza VALUES('K468','8','내 주님 가신 그 길은 죽음의 길이니<br/>난 다만 주로 인하여 잃는 자 되기 원해<br/>',NULL,31570,8);
INSERT INTO stanza VALUES('K468','9','영광은 장래 오리니 오늘은 인내해<br/>난 결코 주 오시기 전 세상 복 구치 않네<br/>',NULL,31571,9);
INSERT INTO stanza VALUES('K468','10','모든 눈물 그 날에 주 닦아 주리니<br/>면류관 얻는 날까지 충성 다해 전진하리<br/>',NULL,31572,10);
INSERT INTO stanza VALUES('K469','1','베들레헴의 주예수 그의 충성 배우고<br/>주께 항복하려 할 때 눈물 넘쳐 흐르네<br/>말구유의 천한 것을 나는 원치 않으나<br/>주의 상을 얻기 위해 주 발자취 따르리<br/>',NULL,31573,1);
INSERT INTO stanza VALUES('K469','2','나사렛의 거친 이 길 갈수록 더 좁아서<br/>오랫동안 수고하나 항상 수치 당하네<br/>종이 상전보다 못함 주가 알려줬으니<br/>주와 함께 고난 받고 눈물 흘리기 원해<br/>',NULL,31574,2);
INSERT INTO stanza VALUES('K469','3','갈릴리 길 가신 주님 사람 버림 받으사<br/>많은 고난 당하시고 저주당하시었네<br/>가도 가도 험한 길을 곧게 나아가신 주<br/>우리 또한 전진하리 곤경 겁내지 않고<br/>',NULL,31575,3);
INSERT INTO stanza VALUES('K469','4','겟세마네 동산에서 홀로 곤욕 받은 주<br/>사탄 무리 공격 속에 홀로 감당하였네<br/>천사 우릴 부축하니 우린 실패 안 하리<br/>전쟁 오직 한 때이니 상을 주목하겠네<br/>',NULL,31576,4);
INSERT INTO stanza VALUES('K469','5','갈보리의 십자가를 회피하지 않으리<br/>자신 동정하지 않고 주와 수치 당하리<br/>이런 고통 한 때이나 장래 주를 만날 때<br/>주의 웃는 얼굴 속에 고통 사라지겠네<br/>',NULL,31577,5);
INSERT INTO stanza VALUES('K469','6','무덤가에 둘러선 자 울며 슬퍼하지만<br/>우린 주와 승천하여 땅을 멀리 떠나네<br/>세상 사람 우리들을 죽은 자로 여기나<br/>우린 즐겨 목숨 잃고 참 소망을 얻으리<br/>',NULL,31578,6);
INSERT INTO stanza VALUES('K469','7','푯대 향해 나아가리 매일 매일 힘 다해<br/>하늘 성의 광채 보며 하늘 음성 들으며<br/>그곳에서 우리 주님 우릴 환영하시리<br/>온갖 상처 받은 마음 주가 위로하시리<br/>',NULL,31579,7);
INSERT INTO stanza VALUES('K469','8','친구들아 잠시 후면 피곤하지 않으리<br/>다시 죄와 근심 없고 주 네 눈물 닦으리<br/>주의 부드러운 음성 우릴 격려하신다<br/>“낙심말고 전진하라 노정 곧 끝나리니”<br/>',NULL,31580,8);
INSERT INTO stanza VALUES('K47','1','아버지께 나아오네 아들에게 이끌려<br/>아버지께 경배드려 크신 사랑 누리며<br/>잃었다가 얻은 우리 거 - 룩한 무리 돼<br/>영원 계획 이뤄지니 아버지 참 기뻐해<br/>',NULL,31581,1);
INSERT INTO stanza VALUES('K47','2','주의 상의 떡과 잔을 우린 이미 받았네<br/>이 표시가 설명하네 아들 사랑 역사를<br/>그의 몸이 갈라져서 새롭고 산 길 열어<br/>담대하게 우린 나와 아버지라 부르네<br/>',NULL,31582,2);
INSERT INTO stanza VALUES('K47','3','그는 이미 보혈 흘려 우리 죄를 도말해<br/>하나님의 공의 분노 다시 잘못 안 찾네<br/>그의 피가 당신 앞에 나를 위해 증거해<br/>사탄 참소 효능 없고 나도 자책 안 하리<br/>',NULL,31583,3);
INSERT INTO stanza VALUES('K47','4','작고 작은 이 사람을 보물처럼 보시고<br/>하나님과 화목토록 다시 찾아 주셨네<br/>천사들은 타락해도 다시 찾지 않지만<br/>사람만은 되찾으사 사함 받게 하셨네<br/>',NULL,31584,4);
INSERT INTO stanza VALUES('K470','1','대가 지불하고 십자가 져야 우린 승리하고 권능 얻는다<br/>내 힘과 지혜로 승리 못하니 주의 존귀하-신- 이름 의지해<br/>',NULL,31585,1);
INSERT INTO stanza VALUES('K470','chorus','대가 지불하고 십자가 져야 우린 승리하고- 권능 얻는다<br/>',NULL,31586,2);
INSERT INTO stanza VALUES('K470','2','모든 자랑 수단 끊어야 한다 우린 주와 함께 싸워야 한다<br/>십자가의 고난 사탄 폐하니 죽음 통해 이-겨- 권능 얻는다-<br/>',NULL,31587,3);
INSERT INTO stanza VALUES('K470','3','용감하면서도 온유하여라 인자하면서도 분투하여라<br/>역사하면서도 안식하여라 주와 함께 죽-어- 생명 충만해-<br/>',NULL,31588,4);
INSERT INTO stanza VALUES('K470','4','구주 좇아 주의 길을 가려면 십자가를 지고 주와 합하라<br/>죽음 당하여도 피하지 않고 최후까지 견-뎌- 면류관 얻자-<br/>',NULL,31589,5);
INSERT INTO stanza VALUES('K471','1','깨-어지고 파-쇄돼 주-의 품에 안-겼네<br/>작-은 배가 부-두에 가-까울 때 편안하니<br/>파선된 후 주- 안의- 참-된 안식 못누려<br/>',NULL,31590,1);
INSERT INTO stanza VALUES('K471','2','깨-어지고 파쇄될 때 우-린 애타했-지만<br/>풍-랑 인해 주- 품에 양-육 얻게 되-었네<br/>주 안에 안식-하니- 다-시 요동함 없네<br/>',NULL,31591,2);
INSERT INTO stanza VALUES('K471','3','파-선한 후 내- 닻을 하-늘 위에 던-졌네<br/>계-속 항해하-지만 내-가 조종 안-하네<br/>근심 필요없-다네- 주-와 함께 거하니<br/>',NULL,31592,3);
INSERT INTO stanza VALUES('K471','4','깨-어지고 파-쇄돼 내-게 유익되-었네<br/>사-람들은 놀-라나 파-선 내게 은-혤세<br/>주님 안에 거-하니- 주-가 친히 지키네<br/>',NULL,31593,4);
INSERT INTO stanza VALUES('K472','1','사망 이긴 부활의 생명은 피조되잖은 영원한 생명<br/>파괴되잖는 승리의 생명 그리스도가 나타내셨네<br/>',NULL,31594,1);
INSERT INTO stanza VALUES('K472','2','사망 이긴 부활의 생명은 사망 통해 더 확증되었네<br/>사망은 다만 기회를 주어 이 생명 풍성 나타나게 해<br/>',NULL,31595,2);
INSERT INTO stanza VALUES('K472','3','사망 이긴 부활의 생명은 사망과 매장 통해 번식해<br/>고난 통하여 자라는 생명 풍성한 열매 더욱 얻었네<br/>',NULL,31596,3);
INSERT INTO stanza VALUES('K472','4','사망 이긴 부활의 생명은 모든 방해와 장애 돌파해<br/>흑암과 음부 권세 이기고 사망 삼키고 생명 해방해<br/>',NULL,31597,4);
INSERT INTO stanza VALUES('K472','5','사망 이긴 부활의 생명은 신성의 모든 충만 나타내<br/>하나님 의와 성결 산출해 하나님 영광 형상 나타내<br/>',NULL,31598,5);
INSERT INTO stanza VALUES('K472','6','사망에도 그 능력 발하는 부활한 생명 얻기 원하네<br/>이 생명은 곧 사신 주 예수 체험 통하여 깨닫게 되네<br/>',NULL,31599,6);
INSERT INTO stanza VALUES('K473','1','죽고 다시 삶 내세뿐 아니라 오늘도 이뤄질 수 있다네<br/>깨어진 그릇 토기장이 손에 오늘도 다뤄질 수 있다네<br/>',NULL,31600,1);
INSERT INTO stanza VALUES('K473','2','죽고 다시 삶 오 놀라운 부활 약한 것으로 심겨졌으나<br/>강한 것으로 다시 일어나네 나의 왕 그리스도 인하여<br/>',NULL,31601,2);
INSERT INTO stanza VALUES('K473','3','죽고 다시 삶 영광 부활 위해 주님의 죽음 본받아야 해<br/>주 위해 모두 배설물로 여겨 주님과 함께 환난 받으리<br/>',NULL,31602,3);
INSERT INTO stanza VALUES('K473','4','죽고 다시 삶 오 놀라운 축복 하늘의 맑은 강으로부터<br/>생명의 산 샘 넘쳐 흘러나니 다시는 목마르지 않겠네<br/>',NULL,31603,4);
INSERT INTO stanza VALUES('K474','1','바른길 갈 때 지-쳐 발 저린 사람아-<br/>네 소망 주께 두-고 낙-심치 말아라<br/>주 얼굴 광채 비췰 때 네 어둠 사라져<br/>주 영광 얼굴 바라면 해-같이 밝으리<br/>',NULL,31604,1);
INSERT INTO stanza VALUES('K474','2','네 모든 소망 오-직 주 예수께 둘 때-<br/>사방의 질고 피-곤 널- 삼키지 못해<br/>근심의 눈물 나-도 네 눈 어둡잖고<br/>위험의 모든 염-려 널- 혼미케 못해<br/>',NULL,31605,2);
INSERT INTO stanza VALUES('K474','3','네 소망 주께 둘- 때 은혜로 적셔져-<br/>이 세상 고초 험하나 주- 평강 누리리<br/>인생의 쓴 바다-에 풍랑 몰아쳐도<br/>주 웃는 얼굴 바라고 놀-라지 않으리<br/>',NULL,31606,3);
INSERT INTO stanza VALUES('K474','4','네 소망 주께 둘- 때 혼미하지 않고-<br/>늘 주께 얼굴 들- 때 주- 길 지시하리<br/>너 전진할 때 구-름 몰려올지라도<br/>네 머리 주를 향할 때 바-른길 가리라<br/>',NULL,31607,4);
INSERT INTO stanza VALUES('K474','5','하늘로 오르도-록 주님만 바라라-<br/>영광의 얼굴 밝-히 뵙-는 그날까지<br/>네 앙망하는 주-님 오늘 널 지키고<br/>그날 네 찬송 되-어 기-쁨 넘치리라<br/>',NULL,31608,5);
INSERT INTO stanza VALUES('K475','1','어둠 속에 빛을 찾아서 피곤하게 헤매었네<br/>내 왕되신 예수를 보니 모든 것이 밝아지네<br/>',NULL,31609,1);
INSERT INTO stanza VALUES('K475','chorus','나의 눈을 돌이켜 주 영광의 얼굴 보리<br/>주의 영광 빛 가운데에서 땅의 것들은 희미해져<br/>',NULL,31610,2);
INSERT INTO stanza VALUES('K475','2','죽음 통해 생명 얻으리 앞서 간 주 따라가며<br/>죄 권세 다 지나갔으니 나 넉넉히 이기도다<br/>',NULL,31611,3);
INSERT INTO stanza VALUES('K475','3','주 약속 다 이뤄지리니 주 의지해 형통하리<br/>낙심 말고 견고하여라 큰 구원을 체험하리<br/>',NULL,31612,4);
INSERT INTO stanza VALUES('K476','1','은혜의 주 보며 성령 순종하리<br/>생명 빛 가운데 살면서 찬송해 영광 찬송 넘쳐<br/>',NULL,31613,1);
INSERT INTO stanza VALUES('K477','1','주의 얼굴 보며 더 대화하리<br/>늘 주 안에 거해 주 말씀 먹고<br/>늘 주 앞에 서서 주 순복하리<br/>내 모든 일에서 주만 구하리<br/>',NULL,31614,1);
INSERT INTO stanza VALUES('K477','2','주의 얼굴 보리 바쁘더라도<br/>틈 내어 은밀히 주 앙망하리<br/>주 얼굴 대할 때 주 형상 되리<br/>내 모든 일에서 주 나타내리<br/>',NULL,31615,2);
INSERT INTO stanza VALUES('K477','3','주의 얼굴 보며 주 인도받아<br/>어떤 일 닥쳐도 서두르잖고<br/>기쁘나 슬프나 늘 주 따르리<br/>늘 주 말씀 듣고 주 바라보리<br/>',NULL,31616,3);
INSERT INTO stanza VALUES('K477','4','내 속 고요해야 주 얼굴 뵈리<br/>주 오셔서 나를 다스리시리<br/>주 사랑의 샘에 날 인도할 때<br/>하늘에 속한 일 능히 하리라<br/>',NULL,31617,4);
INSERT INTO stanza VALUES('K478','1','주의 군사들아 돌격하여라 자신 의지하면<br/>패배하지만 주의 크신 능력 의지하여 싸워<br/>능력 주는 자 안에서 다 할- 수 있다<br/>',NULL,31618,1);
INSERT INTO stanza VALUES('K478','2','너의 본분 지켜 바른 길 갈 때 때로 지루하고<br/>곤란 닥치나 너의 짐을 주가 지기 원하신다<br/>능력 주는 자 안에서 다 할- 수 있다<br/>',NULL,31619,2);
INSERT INTO stanza VALUES('K478','3','네가 노정에서 피곤할 때에 주 반드시 너를<br/>도우시리니 기쁘든 슬프든 뚫고 나가리라<br/>능력 주는 자 안에서 다 할- 수 있다<br/>',NULL,31620,3);
INSERT INTO stanza VALUES('K478','4','사악한 이 땅에 시험 많으나 너는 굳게 서리<br/>넘어지잖고 헛수고 한 사탄 도망가게 되리<br/>능력 주는 자 안에서 다 할- 수 있다<br/>',NULL,31621,4);
INSERT INTO stanza VALUES('K478','5','그리스도 능력 끝이 없으니 주가 끝까지 널<br/>구원하리라 그의 족한 은혜 너의 약함 덮네<br/>능력 주는 자 안에서 다 할- 수 있다<br/>',NULL,31622,5);
INSERT INTO stanza VALUES('K479','1','주 생각하며 본을 삼으라 너의 몸 주 영광 나타내게<br/>주님 너에게 영생 주시고 부활의 능력 누리게- 했네<br/>',NULL,31623,1);
INSERT INTO stanza VALUES('K479','2','날마다 예수 생각하여라 무궁한 생명 더욱 누리며<br/>부활의 크신 능력 의지해 주님의 죽음 체험하-여라<br/>',NULL,31624,2);
INSERT INTO stanza VALUES('K479','3','일생 동안 주 생각하여라 휘장 안에 주 영광 빛 보며<br/>자아 거절해 주 뜻 알리라 자아를 벗어나서 안-식해<br/>',NULL,31625,3);
INSERT INTO stanza VALUES('K479','4','전진하며 주 생각하여라 나아가 주의 얼굴 바라봐<br/>영광- 위에 영광 더하여 주 형상 너를 통해 나-타나<br/>',NULL,31626,4);
INSERT INTO stanza VALUES('K48','1','잔치 곧 지나 달콤할 때에 아버지 사랑<br/>우릴 이끄네 아들과 함께 찬양할 때에<br/>친밀함 달콤함 다 말 못해<br/>',NULL,31627,1);
INSERT INTO stanza VALUES('K48','2','아버지만이 참된 은혜니 그 사랑보다<br/>귀한 것 없네 무궁한 생명 풍성한 그 맛<br/>맛보며 아버지께 경배해<br/>',NULL,31628,2);
INSERT INTO stanza VALUES('K48','3','인정보다도 나은 그 사랑 그 사랑 안에<br/>내 사랑 커져 당신의 사랑 능력 인하여<br/>당신의 임재 더 깊이 누려<br/>',NULL,31629,3);
INSERT INTO stanza VALUES('K48','4','아들을 따라 우리도 함께 아버지 향해<br/>찬미 드리네 거룩한 사랑 충만히 누려<br/>당신의 이름 풍성 맛보네<br/>',NULL,31630,4);
INSERT INTO stanza VALUES('K480','1','땅이 진동하고 하늘 변해도 너는 주께<br/>순-종할 수 있느냐- 주의 함께 하심 믿을 수 있나<br/>돌연 임한 화를 보지 않겠나<br/>',NULL,31631,1);
INSERT INTO stanza VALUES('K480','2','물러서지 않고 놀라지 않고 너의 주를<br/>순-종할 수 있느냐- 너의 장래 다만 죽음이래도<br/>상관하지 않고 순종하겠나<br/>',NULL,31632,2);
INSERT INTO stanza VALUES('K480','3','너의 주가 너를 전선에 보내 대적 치라<br/>할- 때 복종하겠나- 진정 기쁨 속에 보내심 받아<br/>온 밤 지나도록 싸울 수 있나<br/>',NULL,31633,3);
INSERT INTO stanza VALUES('K480','4','하나님 널 오래 기다렸으니 주께 복종<br/>하-여 명령 준행해- 주의 군사 되면 주 다시 오셔<br/>충성된 자라고 칭찬하리라<br/>',NULL,31634,4);
INSERT INTO stanza VALUES('K481','1','주님 가까우니 염려 말아라<br/>주님만을 믿고 요동치 마라<br/>너의 마음대로 행하지 마라<br/>혹시 주가 오늘 올지 모른다<br/>',NULL,31635,1);
INSERT INTO stanza VALUES('K481','2','아무 염려 말고 주께 맡기라<br/>널 위해 죽은 주 네 고통 지리<br/>앞으로 나아가 기회 붙잡아<br/>견고한 그 사랑 증거하여라<br/>',NULL,31636,2);
INSERT INTO stanza VALUES('K481','3','주가 지체해도 염려 말아라<br/>종신토록 주가 널 부축하리<br/>주의 맘을 믿고 주 손 의지해<br/>염려 말고 힘써 전진하여라<br/>',NULL,31637,3);
INSERT INTO stanza VALUES('K482','1','하나님 견고한 말씀 폐해지지 않네<br/>말씀 다 이뤄지리니 다만 믿기만 해<br/>',NULL,31638,1);
INSERT INTO stanza VALUES('K482','chorus','천지는 없어져도 산들 다 무너져도<br/>주 말씀 이뤄지리 주 믿는 자에게<br/>',NULL,31639,2);
INSERT INTO stanza VALUES('K482','2','네 마음 아브람같이 하늘 별들 보라<br/>어려움 가볍게 봐야 견고한 믿음 돼<br/>',NULL,31640,3);
INSERT INTO stanza VALUES('K482','3','구름이 짙을지라도 태양은 변찮네<br/>잠시 후 잠깐 후에는 햇빛이 나타나<br/>',NULL,31641,4);
INSERT INTO stanza VALUES('K482','4','불가마 속에 있어도 끝까지 참으리<br/>주께서 동행하시니 원수를 이기리<br/>',NULL,31642,5);
INSERT INTO stanza VALUES('K482','5','친구가 오해를 해도 여전히 주 믿어<br/>네 능력 되신 주 항상 가까이 계시니<br/>',NULL,31643,6);
INSERT INTO stanza VALUES('K482','6','휴거의 그날에까지 주님만 의지해<br/>믿고 또 바라던 소망 그날에 이뤄져<br/>',NULL,31644,7);
INSERT INTO stanza VALUES('K483','1','전진하라 계속 곧게 달리라<br/>뒤를 보지 말고 푯대 향하여<br/>불기둥이 나의 노정 비추네-<br/>주가 인도하니 멈출 수 없네<br/>광야 전쟁 거쳐 전진하여라<br/>가나안 보인다 시온 비췬다<br/>',NULL,31645,1);
INSERT INTO stanza VALUES('K483','2','영광 위에 영광 더해지리라<br/>하나님이 미리 예비한 영광<br/>보지도 못하고 듣지도 못한-<br/>생각지도 못한 영광이로다<br/>전진하라 계속 왕국에까지<br/>네가 믿은 것이 실체 되도록<br/>',NULL,31646,2);
INSERT INTO stanza VALUES('K483','3','거룩한 성 향해 전진하여라<br/>영광 자유 안에 들어가도록<br/>영광 면류관을 쓰게 되리라-<br/>주와 함께 영영 왕 노릇 하리<br/>노정 마치도록 전진하여라<br/>주의 크신 능력 의지하고서<br/>',NULL,31647,3);
INSERT INTO stanza VALUES('K484','1','푯대 향해- 가라 외로울지-라도<br/>주 널 부르-고 있으니 곧 전-진하여라<br/>',NULL,31648,1);
INSERT INTO stanza VALUES('K484','2','푯대 향해- 가라 주 너를 보-신다<br/>네 기쁨 모-든 슬픔을 주께-서 돌본다<br/>',NULL,31649,2);
INSERT INTO stanza VALUES('K484','3','푯대 향해- 가라 뒤 보지 말-고서<br/>네 앞에 상-이 있으니 면류-관 주리라<br/>',NULL,31650,3);
INSERT INTO stanza VALUES('K484','4','푯대 향해- 가라 귀 막고 묵-묵히<br/>주 가신 십-자가 길을 주 따-라 가거라<br/>',NULL,31651,4);
INSERT INTO stanza VALUES('K485','1','은혜-의 주- 의지해 앞으로 전진해<br/>약속- 잡고- 믿음으로 전진해<br/>애굽은 뒤에 던지리- 머무르지- 않으리<br/>돌아- 보지- 않고서- 전진해<br/>',NULL,31652,1);
INSERT INTO stanza VALUES('K485','2','뒤에- 원수- 좇아도 앞으로 전진해<br/>깊은- 바다- 있어도- 전진해<br/>깊은 바다- 갈라져- 원수들이- 잠기리<br/>주 널- 이기-게 하니- 전진해<br/>',NULL,31653,2);
INSERT INTO stanza VALUES('K485','3','구름- 기둥- 따라서 앞으로 전진해<br/>불기-둥이- 비추니- 전진해<br/>만나 너를- 채우고- 반석의 물- 널 축여<br/>대적- 네게- 패하리- 전진해<br/>',NULL,31654,3);
INSERT INTO stanza VALUES('K485','4','광야-길은- 험하나 앞으로 전진해<br/>언약-궤를- 따라서- 전진해<br/>요단강을- 건너서- 가나안 땅- 가도록<br/>시온-까지- 앞으로- 전진해<br/>',NULL,31655,4);
INSERT INTO stanza VALUES('K485','1','세상- 사랑- 끊고서 앞으로 전진해<br/>얽매-인 것- 벗고서- 전진해<br/>하나님 널- 불렀고- 그리스도- 네 생명<br/>성령- 네 능-력 되니- 전진해<br/>',NULL,31656,5);
INSERT INTO stanza VALUES('K485','2','손에- 쟁기- 쥐고서 앞으로 전진해<br/>주저-하지- 말고서- 전진해<br/>주를 바라-보는 자- 피곤하지- 않겠네<br/>용감-하게- 앞으로- 전진해<br/>',NULL,31657,6);
INSERT INTO stanza VALUES('K485','3','변함-없이- 끝까지 앞으로 전진해<br/>푯대- 향해- 앞으로- 전진해<br/>새벽별이- 뜨도록- 왕국이 임-하도록<br/>면류-관을- 받도록- 전진해<br/>',NULL,31658,7);
INSERT INTO stanza VALUES('K486','1','어둔 밤 깊었으니 늘 깨어 있으라 세상을 사랑말고<br/>깨어 있으라 주님 곧 오시리-니 허리띠 띠고서<br/>게으름 떨치고서 깨어있으라<br/>',NULL,31659,1);
INSERT INTO stanza VALUES('K486','2','일어나 섬기면서 늘 깨어 있으라 때 임박하였으니<br/>깨어 있으라 너의 영 강하게- 해 마귀 대적하고<br/>강한 맘 가지고서 깨어 있으라<br/>',NULL,31660,2);
INSERT INTO stanza VALUES('K486','3','새벽별 곧 뜨리니 깨어 기다리라 왕국을 추구하며<br/>깨어 있으라 주 오심 기다리-며 늘 깨어 있으라<br/>언제나 쉬지 말고 깨어 있으라<br/>',NULL,31661,3);
INSERT INTO stanza VALUES('K487','1','영을 훈련하고 혼을 거절해<br/>모든 생활에서 이 비결 누려<br/>',NULL,31662,1);
INSERT INTO stanza VALUES('K487','2','영을 훈련하고 규례 저버려<br/>성령 따라 항상 행하기 배워<br/>',NULL,31663,2);
INSERT INTO stanza VALUES('K487','3','영을 훈련하고 자아 거절해<br/>생명빛 가운데 주를 따르세<br/>',NULL,31664,3);
INSERT INTO stanza VALUES('K487','4','영을 훈련하고 혼을 거절해<br/>모든 문제 끝나 찬미 넘치리<br/>',NULL,31665,4);
INSERT INTO stanza VALUES('K487','5','영을 훈련하여 주가 길 얻고<br/>영을 훈련할 때 주 풍성 누려<br/>',NULL,31666,5);
INSERT INTO stanza VALUES('K487','6','영을 훈련할 때 주를 접촉해<br/>영을 훈련할 때 나는 건축돼<br/>',NULL,31667,6);
INSERT INTO stanza VALUES('K487','7','영을 훈련하길 주님 원하니<br/>영을 훈련할 때 주 영광 얻네<br/>',NULL,31668,7);
INSERT INTO stanza VALUES('K488','1','성도들 왜 염려하나 주께 모두 맡기라<br/>예수 우리 구주시니 주 널 책임지시리<br/>우리들의 필요함을 매일 매일 공급해<br/>우리를 창조하신 주 모든 설계하시리<br/>',NULL,31669,1);
INSERT INTO stanza VALUES('K488','chorus','사랑으로 드릴 때에 더욱 풍성해지니<br/>너의 모든 것을 드려도 주가 배나 더 채워<br/>',NULL,31670,2);
INSERT INTO stanza VALUES('K488','2','우리 믿는 주 예수는 지체하지 않는다<br/>응답 빠르지 않아 또한 늦지도 않아<br/>병 속에 있는 기름이 마르지 않고 흘러<br/>모든 사람 먹고 남네 그침없이 흐르네<br/>',NULL,31671,3);
INSERT INTO stanza VALUES('K488','3','공중 나는 새를 보라 들에 백합화 보라<br/>심고 수확하지 않아 수고와 길쌈 안 해<br/>내일 일을 염려 말자 오늘로서 족하다<br/>내일 염려 안 사오면 오늘 편치 않으랴<br/>',NULL,31672,4);
INSERT INTO stanza VALUES('K489','1','아버지의 사랑을 느껴본 적 있나<br/>아버지의 긍휼을 맛본 적이 있나<br/>아버지의 큰 사랑 더욱 더욱 넘쳐<br/>대가없는 큰 사랑 더욱 더욱 넘쳐<br/>',NULL,31673,1);
INSERT INTO stanza VALUES('K489','chorus','넘치고 넘치네 더욱 더욱 넘쳐<br/>하나님의 큰 사랑- 더욱 더욱 넘쳐<br/>',NULL,31674,2);
INSERT INTO stanza VALUES('K489','2','주의 친밀하심을 느껴본 적 있나<br/>주의 임재 너의 맘 기쁘게 하였나<br/>크고 크신 주 은혜 더욱 더욱 넘쳐<br/>대가 없이 주셨네 더욱 더욱 넘쳐<br/>',NULL,31675,3);
INSERT INTO stanza VALUES('K489','3','성령의 큰 능력을 느껴본 적 있나<br/>이슬같이 비같이 네게 임하였나<br/>주의 영의 큰 능력 더욱 더욱 넘쳐<br/>대가 없이 주셨네 더욱 더욱 넘쳐<br/>',NULL,31676,4);
INSERT INTO stanza VALUES('K49','1','아버지 당신만을 경배하고 존경하며<br/>자녀들 함께 모여 한 맘으로 찬양합니다<br/>우리를 집에 인도한 귀한 은혜<br/>아들과 함께 아버지 가까이해<br/>',NULL,31677,1);
INSERT INTO stanza VALUES('K49','2','사랑을 아는 자는 다 알리라 이 큰 사랑<br/>아버지 깊은 사랑 아들 통해 확증되었네<br/>아버지 사랑 아는 자 다 이끌어<br/>아들은 아버지께 찬송합니다-<br/>',NULL,31678,2);
INSERT INTO stanza VALUES('K49','3','아들과 함께 우리 찬송할 때 아버지는<br/>사랑의 소리 듣고 기뻐하며 만족하시네<br/>창세 전부터 아들 사랑하셨네<br/>우리로 아들 동반 되게 하셨네<br/>',NULL,31679,3);
INSERT INTO stanza VALUES('K490','1','주 사랑 안에 거해 나 두려움 없네<br/>이 확신 변치 않아 떨어지지- 않-아<br/>광풍이 몰아치고 소망 다 끊겨도<br/>주- 나를 보호하니 방황치 않으리<br/>',NULL,31680,1);
INSERT INTO stanza VALUES('K490','2','곤경이 몰아쳐도 주 인도 따르리<br/>내 목자 함께하니 부족함 없-다-네<br/>주 지혜 주 맑은 눈 늘 나를 지키며<br/>내- 노정 이끄시니 늘 따라가겠네<br/>',NULL,31681,2);
INSERT INTO stanza VALUES('K490','3','나 아직 보지 못한 초장 앞에 있네<br/>저 짙은 구름 이내 걷히고 맑-으-리<br/>내 소망 영원하고 내 노정 빛나네<br/>주- 나의 보화시니 난 그와 동행해<br/>',NULL,31682,3);
INSERT INTO stanza VALUES('K490','4','아침이 되기 전에 내 육을 거절해<br/>내 육을 벗고 주와 함께 있게- 되-리<br/>안식의 수면 내게 얼마나 귀한지<br/>주- 오셔 보좌 앞에 날 불러 만나리<br/>',NULL,31683,4);
INSERT INTO stanza VALUES('K490','5','주 그때 백성들의 중심에 계시리<br/>영광의 찬송 소리 끝없이 퍼-지-리<br/>놀라운 약속의 날 우리와 주 함께<br/>영-원히 안식 누려 만족함 누리리<br/>',NULL,31684,5);
INSERT INTO stanza VALUES('K491','1','“너와 같이 하리라”주의 하신 약속<br/>나의 마음 안위해 두려움 없네<br/>길고 어두운 밤에 주 내 방패시니<br/>나와 같이 하시네 항상 같이 계셔<br/>',NULL,31685,1);
INSERT INTO stanza VALUES('K491','chorus','주 나와 항상 같이 하여 주시고<br/>주 나와 영원히 같이 하실 것 허락했네<br/>주 나와 항상 같이 하여 주시고<br/>주 나와 영원히 같이 하실 것 허락했네<br/>',NULL,31686,2);
INSERT INTO stanza VALUES('K491','2','땅의 신선한 꽃과 빛은 사라져도<br/>주의 사랑과 빛은 더욱 찬란해<br/>주는 한 포대 몰약 온 밤 지나도록<br/>나의 품 안에 있네 새벽 될 때까지<br/>',NULL,31687,3);
INSERT INTO stanza VALUES('K491','3','나의 앞길에 시련 다가올지라도<br/>주는 내게 말씀해 안심하여라<br/>주의 기쁨이 마치 봄새 날아들 듯<br/>내 맘 품 속에 오네 찬미 부르게 해<br/>',NULL,31688,4);
INSERT INTO stanza VALUES('K492','1','주 날개 밑 내가 편안히 쉬네 밤 깊고 비바람 불어쳐도<br/>아버지께서 날 지키시리니 거기서 평안히 쉬리로다<br/>',NULL,31689,1);
INSERT INTO stanza VALUES('K492','chorus','주 날개 밑 즐거워라 그 사랑 끊을 자 뉘뇨<br/>주 날개 밑 내 안식처니 영원히 거기서 살리<br/>',NULL,31690,2);
INSERT INTO stanza VALUES('K492','2','주 날개 밑 나의 피난처 되니 거기서 쉬기를 원하노라<br/>세상이 나를 못 위로해주나 거기서 평화를 누리리라<br/>',NULL,31691,3);
INSERT INTO stanza VALUES('K492','3','주 날개 밑 참된 기쁨이 있네 고달픈 세상 길 가는 동안<br/>나 거기 숨어서 돌보심 받고 영원한 안식을 얻으리라<br/>',NULL,31692,4);
INSERT INTO stanza VALUES('K493','1','너 근심 걱-정 말아라 주 너를 지키리-<br/>주 날개 밑-에 거하라 주 너를 지키리<br/>',NULL,31693,1);
INSERT INTO stanza VALUES('K493','chorus','주 너를 지키리 아무 때나 어디든지<br/>',NULL,31694,2);
INSERT INTO stanza VALUES('K493','2','어려워 낙-심 될 때에 주 너를 지키리-<br/>위험한 일-을 당할 때 주 너를 지키리<br/>',NULL,31695,3);
INSERT INTO stanza VALUES('K493','3','너 쓸 것 미-리 아시니 주 너를 지키리-<br/>구하는 것-을 주시며 주 너를 지키리<br/>',NULL,31696,4);
INSERT INTO stanza VALUES('K493','4','어려운 시-험 당하나 주 너를 지키리-<br/>구주의 품-에 거하라 주 너를 지키리<br/>',NULL,31697,5);
INSERT INTO stanza VALUES('K494','1','너의 시련 당할 때에 막연코 너의 마음 절망 밖에 없을 때<br/>주의 은혜 하나하나 세보라 기묘하게 보살피심 알리라<br/>',NULL,31698,1);
INSERT INTO stanza VALUES('K494','chorus','주의 은혜 세어 보아라 주가 너를 보살피셨네<br/>주의 은혜 세어 보아라 기이하게 사랑하심 알리라<br/>',NULL,31699,2);
INSERT INTO stanza VALUES('K494','2','너의 염려 짐을 진 것 같으며 그 십자가 고통처럼 느낄 때<br/>만일 주의 은혜 계산한다면 끝이 없는 기쁨 찬송 흐르리<br/>',NULL,31700,3);
INSERT INTO stanza VALUES('K494','3','세상 사람 모든 향락 볼 때에 주의 약속 굳게 잡고 변치 마<br/>이런 은혜 어디에서 사오랴 주의 집엔 은혜 사랑 충만해<br/>',NULL,31701,4);
INSERT INTO stanza VALUES('K494','4','어떤 시험 당하든지 낙심 마 만사만물 주가 책임지시리<br/>주의 은혜 셀 때 천사 임하여 널 섬기며 네 갈 길을 지키리<br/>',NULL,31702,5);
INSERT INTO stanza VALUES('K495','1','갈 길 멀고 짐 무거워 쓰러지려 할 때에<br/>부드러운 주의 음성“네 짐 네게 맡기라”<br/>',NULL,31703,1);
INSERT INTO stanza VALUES('K495','2','너의 두 손 두 발 모두 힘 빠지고 저릴 때<br/>혼미케 돼 낙심할 때 주께 네 짐 맡기라<br/>',NULL,31704,2);
INSERT INTO stanza VALUES('K495','3','친구 친척 떠나가고 환경 험악할 때에<br/>고뇌 상처 못 견딜 때 주께 네 짐 맡기라<br/>',NULL,31705,3);
INSERT INTO stanza VALUES('K495','4','외롭고 또 연약하여 의지할 데 없을 때<br/>너의 마음 혼란할 때 주께 네 짐 맡기라<br/>',NULL,31706,4);
INSERT INTO stanza VALUES('K495','5','주가 너를 위로하고 강건하게 하시리<br/>네 맘 편케 하시리니 주께 네 짐 맡기라<br/>',NULL,31707,5);
INSERT INTO stanza VALUES('K495','chorus','네 짐 주께 맡기라 네 짐 주께 맡기라<br/>주- 널 위로해 견-고케 하니 주께 네 짐 맡기라<br/>',NULL,31708,6);
INSERT INTO stanza VALUES('K496','1','시련과 아픔- 만나고 저 가시덤불- 지날 때<br/>내 주님 나를- 품으심 난 확실히 믿네<br/>',NULL,31709,1);
INSERT INTO stanza VALUES('K496','chorus','주 예수 날 품네 주 예수 날 품네<br/>주 나를 품어- 주시니 왜 두려워하랴<br/>',NULL,31710,2);
INSERT INTO stanza VALUES('K496','2','이생의 염려- 고난들 내 생각 혼미-케 하나<br/>곤경 속에도- 기억해 주 품어 주심을<br/>',NULL,31711,3);
INSERT INTO stanza VALUES('K496','3','근심과 고뇌- 먹구름 또 내게 몰려- 온대도<br/>주 나를 품으-심 믿고 난 안식한다네<br/>',NULL,31712,4);
INSERT INTO stanza VALUES('K497','1','하나님 이름 넓고 광대해 그 이름 안에 내 맘 평온해<br/>아무리 밤이 길다하여도 당신만 계시면- 충족해<br/>',NULL,31713,1);
INSERT INTO stanza VALUES('K497','2','할 일은 많고 험해도 당신 계시면 만족한다네<br/>당신만 내게 함께 계시면 즐거워 노래할 수 있다네<br/>',NULL,31714,2);
INSERT INTO stanza VALUES('K497','3','내 하나님이 모든 것 되니 풍족하고도 풍성하시네<br/>당신 자신만 내게 계시면 그 어느 것도 부족함 없네<br/>',NULL,31715,3);
INSERT INTO stanza VALUES('K497','4','사랑의 기적 내게 베풀어 지금껏 나를 돌보신 주님<br/>나 지금 그의 품에 돌아와 평안히 주의 은혜 찬양해<br/>',NULL,31716,4);
INSERT INTO stanza VALUES('K498','1','슬픈 마음 있는 사람 예수 이름 믿으면<br/>영원토록 변함없는 기쁜 마음 얻으리<br/>',NULL,31717,1);
INSERT INTO stanza VALUES('K498','chorus','예수의 이름은 세상의 소망이요<br/>예수의 이름은- 천국의 기쁨일세<br/>',NULL,31718,2);
INSERT INTO stanza VALUES('K498','2','거룩하신 주의 이름 너의 방패 삼아라<br/>환난 시험 당할 때에 주께 기도드려라<br/>',NULL,31719,3);
INSERT INTO stanza VALUES('K498','3','존귀하신 주의 이름 우리 기쁨 되도다<br/>주의 품에 안길 때에 기뻐 찬송 부르리<br/>',NULL,31720,4);
INSERT INTO stanza VALUES('K498','4','우리 갈길 다 간 후에 보좌 앞에 나아가<br/>왕의 왕께 경배하며 면류관을 드리리<br/>',NULL,31721,5);
INSERT INTO stanza VALUES('K499','1','나 자신 아닌 주 어떠함이 내 마음 편케 할 수 있다네<br/>주님의 사랑 의심 제하고- 내 맘의 풍파 잔잔케 하네<br/>',NULL,31722,1);
INSERT INTO stanza VALUES('K499','2','주님의 축복 영원하시며 주님의 구원 영원하시네<br/>연약한 나를 부축하시어- 위험한 관문 통과케 하네<br/>',NULL,31723,2);
INSERT INTO stanza VALUES('K499','3','내 하나님 더 인식할수록 내 맘과 입에 찬송 충만해<br/>주 나의 생기 기쁨 되시니- 주 의지할 때 약함 강함 돼<br/>',NULL,31724,3);
INSERT INTO stanza VALUES('K499','4','구할 수 없는 달콤함 찾아 난 굶주리고 목말랐지만<br/>내 연인들이 남기고 간 건- 더 나은 사랑 위한 공허뿐<br/>',NULL,31725,4);
INSERT INTO stanza VALUES('K499','5','내게 당신 더 보여주소서 주의 영광 더 보여주소서<br/>은혜와 능력 안에 계신 주- 더 많은 긍휼 내게 주소서<br/>',NULL,31726,5);
INSERT INTO stanza VALUES('K5','1','축복의 근원 아버지 구속 이루신 아들과<br/>운행하시는 성령을 찬양하고 찬양하세<br/>',NULL,31727,1);
INSERT INTO stanza VALUES('K5','2','영원한 근원 아버지 생명의 흐름 아들과<br/>내 안에 오신 성령은 내 분깃 되신 하나님<br/>',NULL,31728,2);
INSERT INTO stanza VALUES('K50','1','아버지 사랑 나타나셨으니 우린 다 당신 앞에 반향해<br/>번제로 뜻을 이룬 당신 아들 십자가 견뎌 나를 구원했네<br/>',NULL,31729,1);
INSERT INTO stanza VALUES('K50','2','그 아들 많은 형제 이끄시니 우린 다 한 소리로 찬양해<br/>그 아들 소리 높여 찬송할 때 우리도 즐겨 좇아 찬송하네<br/>',NULL,31730,2);
INSERT INTO stanza VALUES('K50','3','당신의 아들 안에 택함 받고 오늘은 당신 앞에 찬송해<br/>창세 전 이미 예정하심 입고 당신의 아들 생명 참예하네<br/>',NULL,31731,3);
INSERT INTO stanza VALUES('K50','4','사랑을 입은 모든 아들들이 당신 영 인해 새롭게 되네<br/>당신의 사랑하는 그 아들을 영원한 분깃으로 소유하네<br/>',NULL,31732,4);
INSERT INTO stanza VALUES('K50','5','당신의 성품 함께 가진 우리 당신의 어떠하심 나타내<br/>당신의 기뻐하는 작품 되어 영원히 주 기쁘게 하 - 겠네<br/>',NULL,31733,5);
INSERT INTO stanza VALUES('K500','1','주 모든 일-의 열쇠니 난 즐거워<br/>주 만일 다-른 이에게 날 돌보도-록<br/>했다면 난 탄식해 탄식하리<br/>',NULL,31734,1);
INSERT INTO stanza VALUES('K500','2','내일의 걱-정 나에게 임한다면<br/>또 내일 돌-봄 없다면 난 어찌 할-지<br/>모르네 난 기도도 할 수 없네<br/>',NULL,31735,2);
INSERT INTO stanza VALUES('K500','3','내 눈이 밝-지 않으니 더 편안해<br/>나 어둠 속-에 있으나 주 손길 음-성<br/>느끼네 주님 멀리 있지 않네<br/>',NULL,31736,3);
INSERT INTO stanza VALUES('K500','4','나 그의 계-획 모르나 오직 하나<br/>이 세상에-서 살 때에 주 얼굴 빛- 날<br/>비추고 인도하심 난 안다네<br/>',NULL,31737,4);
INSERT INTO stanza VALUES('K500','5','주 만유 포-함하시어 충분하네<br/>나 할 수 없-는 것 그는 다 하실 수-가<br/>있으니 조급하지 않으리라<br/>',NULL,31738,5);
INSERT INTO stanza VALUES('K501','1','주의 팔 안에 안온해 그 품에 안온해<br/>그 사랑 날개 밑-에 내 혼 안식 충만해<br/>하늘의 아름다운 위로의 찬미 소리<br/>온 성도 노래 소리 날 찬송케 하네-<br/>',NULL,31739,1);
INSERT INTO stanza VALUES('K501','chorus','주의 팔 안에 안온해 그 품에 안온해<br/>그 사랑 날개 밑-에 내 혼 안식 충만해<br/>',NULL,31740,2);
INSERT INTO stanza VALUES('K501','2','주의 팔 안에 안온해 그 품에 안온해<br/>그 은혜 때를 따-라 단비같이 내리네<br/>이 시험 안 떠나고 내 눈물 흘려도-<br/>내 모든 위험 걱정 날 상치 못하네-<br/>',NULL,31741,3);
INSERT INTO stanza VALUES('K501','3','주의 팔 안에 안온해 그 품에 안온해<br/>반석의 거룩한 날개 날 영원히 덮었네<br/>어둔 밤 지나도록 나 주만 의지해-<br/>사랑의 새벽별이 날 비치기까지-<br/>',NULL,31742,4);
INSERT INTO stanza VALUES('K502','1','근심하는 자여 네- 근심 갖-고<br/>은혜의 보좌로 나오너라<br/>네 맘의 상처를 다 주 -께- 고-해<br/>모든 근심 주가 치료하-리<br/>',NULL,31743,1);
INSERT INTO stanza VALUES('K502','2','미로의 빛이며 기 -쁨과 소-망<br/>그는 영원토록 변함없네<br/>부드런 소리로 말하-는 보혜사<br/>“모든 근심 내가 쫓아 주-마”<br/>',NULL,31744,2);
INSERT INTO stanza VALUES('K502','3','자양분 넘치는 생 -명의 양-식<br/>보좌서 흐르는 생명의 물<br/>주 잔치 맛볼 때 찬송- 넘-쳐-나<br/>모든 근심 주가 풀어 주-네<br/>',NULL,31745,3);
INSERT INTO stanza VALUES('K503','1','하늘 위-에 소-리있네“다 이뤘다”<br/>믿음 즉-시 화-답하네“다 이뤘다”<br/>',NULL,31746,1);
INSERT INTO stanza VALUES('K503','chorus','보좌 음성 들으라 주의 약-속 취-하라<br/>하나님이 말한 것 믿음으로 반향해<br/>찬양 시작되-었-네 할렐루야“다 이뤘다”<br/>',NULL,31747,2);
INSERT INTO stanza VALUES('K503','2','주 완전-한 구-원 받아 다 이뤘다<br/>너의 온-몸 드-리어라 다 이뤘다<br/>',NULL,31748,3);
INSERT INTO stanza VALUES('K503','3','은혜로-운 치-유 약속 다 이뤘다<br/>다만 믿-기만- 하여라 다 이뤘다<br/>',NULL,31749,4);
INSERT INTO stanza VALUES('K503','4','하나님-의 약-속의 말 다 이뤘다<br/>다만 확-신하-기만 해 다 이뤘다<br/>',NULL,31750,5);
INSERT INTO stanza VALUES('K503','5','주의 말-씀대-로 믿어 다 이뤘다<br/>믿음이- 곧 비-결이라 다 이뤘다<br/>',NULL,31751,6);
INSERT INTO stanza VALUES('K504','1','너 노-력 하는 성도여 너 노력 할 것 없다-<br/>더 좋은 길 주님께 있다 왜 그리 애원하냐<br/>',NULL,31752,1);
INSERT INTO stanza VALUES('K504','chorus','주 말씀이면 만족해 오 주 말씀뿐-이다<br/>너 의심할 필요없고 또 애원할 필요없다<br/>네 주님의 말씀만 믿고 네 주 안에 안식해<br/>',NULL,31753,2);
INSERT INTO stanza VALUES('K504','2','너 주-께 항복하여라 죽임을 당하여도-<br/>네 모-든 문제 그치라 믿기만 결정하라<br/>',NULL,31754,3);
INSERT INTO stanza VALUES('K504','3','왜 섰-다 넘어지느냐 주 약속 의지하라-<br/>네 믿음의 닻을 던져라 지금 결정하여라<br/>',NULL,31755,4);
INSERT INTO stanza VALUES('K504','4','또 다-시 싸우지 말고 모든 것 주께 맡겨-<br/>너 영원히 말씀 믿으라 지금 결정하여라<br/>',NULL,31756,5);
INSERT INTO stanza VALUES('K505','1','내 길에 흑암뿐이요 근심 가득할 때<br/>조용히 진정하고서 주의 뜻 구하리<br/>',NULL,31757,1);
INSERT INTO stanza VALUES('K505','2','주님께 은혜 긍휼과 약속이 있으니<br/>지체치 않으시리라 변함이 없으리<br/>',NULL,31758,2);
INSERT INTO stanza VALUES('K505','3','능력의 주가 명하매 곧 이루어졌네<br/>주 앞에 근심 사라져 조급함 사라져<br/>',NULL,31759,3);
INSERT INTO stanza VALUES('K505','4','주 인해 내 맘 안정돼 내 혼 안식하니<br/>주만으로 난 족하여 주 더욱 찬양해<br/>',NULL,31760,4);
INSERT INTO stanza VALUES('K505','5','주 영으로 나 충분히 믿음 갖기 원해<br/>주 이름 더 깊이 알며 주 풍성 얻도록<br/>',NULL,31761,5);
INSERT INTO stanza VALUES('K506','1','주 지체하지 않-으-리 은혜 주시기- 기-뻐-해<br/>나에게 주가 있-으-니 누구를 두려-워-하-랴<br/>',NULL,31762,1);
INSERT INTO stanza VALUES('K506','2','높은 산 가로 막 -아-도 저 바다 가로- 막-아-도<br/>사람이 할 수 없-는- 일 주님은 모두- 하-시-네<br/>',NULL,31763,2);
INSERT INTO stanza VALUES('K506','3','쇠도 물 위에 띄 -우 - 고 바다도 가르-는- 주-님<br/>주님은 해도 공-중-에 멈추게 하는- 분-일-세<br/>',NULL,31764,3);
INSERT INTO stanza VALUES('K506','4','모래가 바다 경 -계-니 파도가 침범- 못-하-네<br/>하나님이신 네- 주-님 무엇을 할 수- 없-으-랴<br/>',NULL,31765,4);
INSERT INTO stanza VALUES('K506','5','그의 맘 너를 사 -랑-해 널 돌볼 것 약-속-했-네<br/>주 그의 크신 긍-휼-로 그의 백성을- 대-하-네<br/>',NULL,31766,5);
INSERT INTO stanza VALUES('K506','6','불의가 없는 하 -나-님 그분은 약속- 안- 잊-어<br/>그의 약속 다 주- 안-에 아멘이 되고- 예-가- 돼<br/>',NULL,31767,6);
INSERT INTO stanza VALUES('K506','7','신실한 우리 하 -나-님 그 약속 영영- 견-고-해<br/>믿음으로써 구-하-면 약속을 따라- 응-답-해<br/>',NULL,31768,7);
INSERT INTO stanza VALUES('K506','8','주 이미 약속했-으-니 더 지체하지- 않-으-리<br/>믿음으로 다 찬-미-해“그분은 우리- 하-나-님”<br/>',NULL,31769,8);
INSERT INTO stanza VALUES('K507','1','주여 날 인도-하는 항구 되어 주소서<br/>인생 거센 풍랑과 암초 통과 하도록<br/>방향판을 보-이사 나를 인도하소서<br/>',NULL,31770,1);
INSERT INTO stanza VALUES('K507','2','사랑하는 어-머니 아기 달래시듯이<br/>주가 바람과 파도 잠잠하게 하소서<br/>놀라우신 왕-이여 나를 인도하소서<br/>',NULL,31771,2);
INSERT INTO stanza VALUES('K507','3','마지막 해안-에서 맹렬한 파도 올 때<br/>주께 의지하오니 내게 말씀하소서<br/>“내가 너의 항-구니 두려워하지 마라”<br/>',NULL,31772,3);
INSERT INTO stanza VALUES('K508','1','구주 나를 인도하니 어찌 헛것 구하랴<br/>날 구원한 그의 사랑 어찌 의심하리요<br/>믿음으로 사는 자는 신성한 위로 얻네<br/>무슨 일을 당하여도 주의 선한 뜻있네<br/>무슨 일을 당하여도 주의 선한 뜻있네<br/>',NULL,31773,1);
INSERT INTO stanza VALUES('K508','2','구주 나를 인도하니 격려받고 길 가네<br/>주 내 양식 공급하고 날 자라게 하시네<br/>나의 힘이 다 빠지고 맘과 영 목말라도<br/>반석이신 주께 와서 기쁨의 샘 마시리<br/>반석이신 주께 와서 기쁨의 샘 마시리<br/>',NULL,31774,2);
INSERT INTO stanza VALUES('K508','3','구주 나를 인도할 때 크신 사랑 풍성해<br/>잠시 후에 그 품에서 약속된 평강 누려<br/>영광스런 몸을 입고 광명한 데 거하리<br/>내 영원히 부를 노래“주 날 인도하셨네”<br/>내 영원히 부를 노래“주 날 인도하셨네”<br/>',NULL,31775,3);
INSERT INTO stanza VALUES('K509','1','영-광 향한 나-그네여 궁-핍하고 곤-하나<br/>하-나님이 보-배로운 약-속 네게 주-셨다<br/>',NULL,31776,1);
INSERT INTO stanza VALUES('K509','chorus','내-가 너를 인-도하리 눈-으로 인도-하리<br/>영-광 향한 나-그네를 눈-으로 인도-하리<br/>',NULL,31777,2);
INSERT INTO stanza VALUES('K509','2','마-음 속에 분-란 있어 혼-미하게 되-어도<br/>모-든 문제 이- 약속이 해-결하여 주-신다<br/>',NULL,31778,3);
INSERT INTO stanza VALUES('K509','3','믿-어왔던 친-구 친척 나-를 멀리 떠-날 때<br/>주-님 작은 음-성으로 내-게 말씀하-시네<br/>',NULL,31779,4);
INSERT INTO stanza VALUES('K509','4','모-든 소망 사-라지고 세-월 흘러 가-지만<br/>주-의 약속 변-함없이 너-를 부축하-리라<br/>',NULL,31780,5);
INSERT INTO stanza VALUES('K509','5','생-명 음영 깊-어질 때 영-광의 몸 입-으리<br/>주-의 약속 더- 참되게 나-타나게 되-리라<br/>',NULL,31781,6);
INSERT INTO stanza VALUES('K509','6','영-과 맘이 기-뻐하는 보-배이신 하-나님<br/>그-와 항상 교-통하며 그- 눈 인도받-으리<br/>',NULL,31782,7);
INSERT INTO stanza VALUES('K51','1','찬송받기에 홀로 합당한<br/>우리의 아버지께 노래 - 해<br/>실재와 영의 경배 원하는<br/>당신께 감사 제물 드리네<br/>',NULL,31783,1);
INSERT INTO stanza VALUES('K51','2','아들로 만물 창조하시고<br/>능력의 말씀으로 붙드 - 네<br/>달콤함 속에 나는 경배해<br/>사랑의 아들 가까이하네<br/>',NULL,31784,2);
INSERT INTO stanza VALUES('K51','3','축복된 범위 교회 중에서<br/>주 인도따라 함께 찬송 - 해<br/>주의 형제들 모두 노래해<br/>주님과 함께 자유 누리며<br/>',NULL,31785,3);
INSERT INTO stanza VALUES('K51','4','소리를 모아 주와 찬송해<br/>아버지 만족하게 하려 - 고<br/>사랑의 아들 찬송 이끄니<br/>영원히 칭송 누리옵소서<br/>',NULL,31786,4);
INSERT INTO stanza VALUES('K510','1','내가 믿음 잃을 때- 주 날 부축해<br/>시험하는 자 올 때- 주 날 부축해-<br/>',NULL,31787,1);
INSERT INTO stanza VALUES('K510','chorus','주 예수 나를 부축하시네<br/>주 날 심히 사랑해- 부축하시네<br/>',NULL,31788,2);
INSERT INTO stanza VALUES('K510','2','내가 설 수 없을 때- 주 날 부축해<br/>나를 기뻐하시어- 주 날 부축해-<br/>',NULL,31789,3);
INSERT INTO stanza VALUES('K510','3','나를 귀히 여기사- 주 날 부축해<br/>나를 기뻐하시어- 주 날 부축해-<br/>',NULL,31790,4);
INSERT INTO stanza VALUES('K511','1','주는 네 좌절 아신다 주는 네 약함 아신다<br/>너의 무고함 아신다 주는 다 이-미 아신다<br/>',NULL,31791,1);
INSERT INTO stanza VALUES('K511','2','주는 네 시련 아신다 필요한 은혜 아신다<br/>네 환경 벌써 아신다 너 왜 두려-워하느냐<br/>',NULL,31792,2);
INSERT INTO stanza VALUES('K511','3','모두 널 비방하여도 모두 널 오해하여도<br/>주는 모든 것 아신다 그러니 안-심하여라<br/>',NULL,31793,3);
INSERT INTO stanza VALUES('K511','4','네 짐 다 주께 맡겨라 탄식 다 주께 토하라<br/>내 고통 아는 주께서 은혜 주시-며 돌보리<br/>',NULL,31794,4);
INSERT INTO stanza VALUES('K511','5','주 내 모든 것 아시니 위로를 얻고 기뻐해<br/>주님 날 구원하리니 내가 더 무-엇 구하랴<br/>',NULL,31795,5);
INSERT INTO stanza VALUES('K512','1','나는 먼 길 걸어가는 타향 땅의 나그네<br/>도중에서 먹구름이 나를 덮으며<br/>방해 염려 고뇌 항상 나를 억누르지만-<br/>내 아버지 모든 것을 알고 계시네<br/>',NULL,31796,1);
INSERT INTO stanza VALUES('K512','2','아버지가 다 아시니 어떠한 보증인가<br/>시련 항상 날 따라도 해하지 못해<br/>주 아시니 격려 받고 요동 않고 안식해-<br/>다 아시는 주의 임재 너무 달콤해<br/>',NULL,31797,2);
INSERT INTO stanza VALUES('K512','3','아버지 날 사랑 안에 매일 지켜 보시네<br/>어려움이 닥쳐와도 그가 날 도와<br/>잠시 후에 노정 마쳐 나의 일생 끝나리-<br/>내가 빛에 들어갈 것 그는 다 아셔<br/>',NULL,31798,3);
INSERT INTO stanza VALUES('K512','4','그때 나는 사랑스런 주의 얼굴 뵙겠네<br/>맘에 기쁨 충만하여 그를 뵈오리<br/>다시 이생 괴로움 없이 그의 임재 누리리-<br/>그의 약속 이뤄질 것 그는 다 아셔<br/>',NULL,31799,4);
INSERT INTO stanza VALUES('K513','1','내 주께서 언제나 예비하네<br/>내 방법도 아닌 네 방법도 아닌<br/>주 방법을 따라서-예비하네<br/>',NULL,31800,1);
INSERT INTO stanza VALUES('K513','chorus','주가 예비하니 난 안심하고<br/>주 의지하네 주- 앙망-하-네<br/>',NULL,31801,2);
INSERT INTO stanza VALUES('K513','2','내 주께서 언제나 예비하네<br/>내 때도 아니고 네 때도 아니고<br/>주 정하신 때 그가- 예비하네<br/>',NULL,31802,3);
INSERT INTO stanza VALUES('K513','3','의심 말라 주께서 예비하니<br/>내 주님의 약속 중 헛된 것 없어<br/>다 이루어지게 주- 예비하네<br/>',NULL,31803,4);
INSERT INTO stanza VALUES('K513','4','전진하면 피곤치 않으리라<br/>저 바다도 길 열고 하늘도 도와<br/>늘 만나를 내려 적- 패하리라<br/>',NULL,31804,5);
INSERT INTO stanza VALUES('K514','1','오- 놀라운 약속의 말씀 내 주께서 말씀했네<br/>내- 능력이 약함 가운데 온전하게 됨이니라<br/>나 혹시 나 악한 맘으로 이 약속을 잊을까봐<br/>주- 계속해서 말씀해 주네“내 은혜가 네게 족해”<br/>',NULL,31805,1);
INSERT INTO stanza VALUES('K514','chorus','예- 거듭해 거듭해 내게 더 말씀해 주옵소서<br/>“내- 은혜가 네게 족하다 내 은혜가 네게 족해”<br/>',NULL,31806,2);
INSERT INTO stanza VALUES('K514','2','그- 은혜 날 구원하시고 날 죄악서 해방했네<br/>내- 영 혼 몸 거룩게하여 주 성령을 충만케 해<br/>저 흉악한 시련이 와도 그 은혜로 통과하네<br/>이- 모든 것 이기는 약속“내 은혜가 네게 족해”<br/>',NULL,31807,3);
INSERT INTO stanza VALUES('K514','3','그- 은혜 날 치료하시네 내 질병과 고통에서<br/>그- 은혜 날 통과케 하네 저 험악한 공격까지<br/>그 은혜는 나에게 족해 내 형제를 돕게 하네<br/>내- 형제도 함께 알게 돼 주 은혜가 족한 것을<br/>',NULL,31808,4);
INSERT INTO stanza VALUES('K514','4','주- 은혜가 나에게 족해 날 부축해 인도하네<br/>나- 죽음의 골짜기 갈 때 주 은혜로 돌보시네<br/>나 구주의 영광을 보며 그 아름다움 볼 때에<br/>곧- 엎드려 경배드리네 주 은혜가 내게 족해<br/>',NULL,31809,5);
INSERT INTO stanza VALUES('K514','5','내- 모든 것 늘 부족하나 주 은혜는 족하시네<br/>내- 모든 것 꽃같이 지나 주 영원히 변함없네<br/>나 언제나 기억하겠네 내 주께서 하신 말씀<br/>“내- 능력이 약함 가운데 온전하여짐이니라”<br/>',NULL,31810,6);
INSERT INTO stanza VALUES('K515','1','주 다시 오시는 그날 그곳에서 다 알겠네<br/>우리의 탄식과 눈물 그 모든 의미 알겠네<br/>',NULL,31811,1);
INSERT INTO stanza VALUES('K515','chorus','구주 믿고 의지하라 길 어둡고 험악해도<br/>주 부축하니 두려워마라 그날 다 알게 되리니<br/>',NULL,31812,2);
INSERT INTO stanza VALUES('K515','2','끊어진 모든 실마리 그날 다 이어지리라<br/>감추인 모든 비밀들 그날 다 이해하리라<br/>',NULL,31813,3);
INSERT INTO stanza VALUES('K515','3','저 구름 태양 가리고 외로움 덮치는 이유<br/>탄식이 많은 이유도 그날 다 이해하리라<br/>',NULL,31814,4);
INSERT INTO stanza VALUES('K515','4','응답이 없는 간구와 이룬 것 없는 종착역<br/>물거품 된 네 소망도 그날 다 알게 되리라<br/>',NULL,31815,5);
INSERT INTO stanza VALUES('K515','5','주 너의 길을 아시고 그 손에 열쇠 가졌네<br/>지혜로우신 주 인도 그날 너 모두 알리라<br/>',NULL,31816,6);
INSERT INTO stanza VALUES('K516','1','예수 믿고 의지함이 심히 기쁜 일일세<br/>주의 말씀 확신하고 약속 위에 안식해<br/>',NULL,31817,1);
INSERT INTO stanza VALUES('K516','chorus','예수 예수 의지하리 다시 요동않으리<br/>살아 계신 주 하나님 지체하지 않으리<br/>',NULL,31818,2);
INSERT INTO stanza VALUES('K516','2','예수 믿고 의지하니 달콤하고 달콤해<br/>보혈 효능 믿을 때에 내 죄 정결케 됐네<br/>',NULL,31819,3);
INSERT INTO stanza VALUES('K516','3','예수 믿고 의지하니 달콤하고 달콤해<br/>나를 죄와 자아에서 멀리 떠나게 하네<br/>',NULL,31820,4);
INSERT INTO stanza VALUES('K516','4','내가 주를 믿었으니 심히 기쁜 일일세<br/>보배로운 나의 구주 영영 함께 있으리<br/>',NULL,31821,5);
INSERT INTO stanza VALUES('K517','1','주 내 눈 가렸으니 난 장래 모르네<br/>내 모든 걸음 뗄 때에 새 경지 있-다네<br/>내 주께서- 주신 기쁨 날 놀라게 했네<br/>',NULL,31822,1);
INSERT INTO stanza VALUES('K517','chorus','나 주- 인도 따르며 주 믿-고 의지해<br/>언제나 어디서나 나는 찬송하겠네-<br/>내 주가 모든 것을 다 알고 또 아심을<br/>',NULL,31823,2);
INSERT INTO stanza VALUES('K517','2','난 다만 한 걸음만 알면 흡족하네<br/>이 땅의 환상 제하면 하늘의 빛- 보리<br/>고요한 중 -에 들리네“날 의지하여라”<br/>',NULL,31824,3);
INSERT INTO stanza VALUES('K517','3','나 무지한 그것이 참 축복이라네<br/>주 나를 가까이 두고 그 오른손-으로<br/>날 항상 붙-잡으시네 날 안식케 하네<br/>',NULL,31825,4);
INSERT INTO stanza VALUES('K517','4','나 모르는 채 가리 더 알기 원찮네<br/>은밀히 주와 가리라 나 혼자 안-가리<br/>나 믿음으-로 주님과 동행하기 원해<br/>',NULL,31826,5);
INSERT INTO stanza VALUES('K518','1','주 의지하는 자 참 복있고 때를 따라 도움 얻네<br/>긴밀히 주님을 좇는 자는 약속된 유익 얻으리<br/>',NULL,31827,1);
INSERT INTO stanza VALUES('K518','chorus','마음 다해 주 의지하라<br/>모든 일에 주 인정해야 주 네 길 인도하리<br/>마음 다해 주 의지하라<br/>모든 일에 주 인정해야 주 네 길 인도하리<br/>',NULL,31828,2);
INSERT INTO stanza VALUES('K518','2','주 의지하는 자 참 복되니 하늘 길 걸어 가겠네<br/>시시로 주님을 앙망하면 확실한 걸음 걸으리<br/>',NULL,31829,3);
INSERT INTO stanza VALUES('K518','3','천부가 부축해 지키시고 주가 돌보아 주시네<br/>아버지와 구주 함께하니 영영 외롭지 않으리<br/>',NULL,31830,4);
INSERT INTO stanza VALUES('K518','4','끝없이 올바른 길 걸으라 장애 떨치고 전진해<br/>주 임재 풍성을 얻는다면 때 따라 도움 얻으리<br/>',NULL,31831,5);
INSERT INTO stanza VALUES('K519','1','나의 길에서 시험을 만날 때 포기하라고 사탄은 말해도<br/>짐이 중해도 근심치 않으리 적은 믿음이 어려움 쫓으리<br/>',NULL,31832,1);
INSERT INTO stanza VALUES('K519','chorus','주여 나는 믿습니다 믿음 더해 나로 산을 옮기게 하소서<br/>주여 나는 믿습니다 모든 의심 던져 버립니다<br/>',NULL,31833,2);
INSERT INTO stanza VALUES('K519','2','항해할 때에 순풍을 만나면 주 손 믿기가 참으로 쉬우나<br/>배에 풍랑이 몰아칠 때에는 많은 믿음이 있어야 이기리<br/>',NULL,31834,3);
INSERT INTO stanza VALUES('K519','3','마지막까지 끝까지 견디어 충성 다해야 이긴다 하지만<br/>맹렬한 시험 닥쳐올 때에는 믿음 잃고서 모든 것 상실해<br/>',NULL,31835,4);
INSERT INTO stanza VALUES('K519','4','용기 열심히 가득한 사람들 힘써 굳세게 봉사를 하지만<br/>죄와 맹렬히 씨름할 때에는 손실 두려워 믿음이 없도다<br/>',NULL,31836,5);
INSERT INTO stanza VALUES('K519','5','주를 믿음은 느낌이 아니요 주를 믿음은 결심이 아닐세<br/>모든 것들이 희미해 보여도 우린 더욱더 믿고서 나가리<br/>',NULL,31837,6);
INSERT INTO stanza VALUES('K52','1','구주의 보혈 의지하고서 -<br/>아버지 앞에 나아갈 때에<br/>간격은 사라지고 자유해 -<br/>아버지 찬미하고 경배하네<br/>',NULL,31838,1);
INSERT INTO stanza VALUES('K52','2','아버지 앞에 우린 바치네 -<br/>아들의 향기로운 이름을<br/>주님의 은혜만을 의지해 -<br/>여기서 믿음으로 그를 보네<br/>',NULL,31839,2);
INSERT INTO stanza VALUES('K52','3','당신과 기쁨 함께 누리니 -<br/>내 맘은 당신 인해 즐거워<br/>지극히 아름다운 그 - 영광<br/>영원히 사라지지 않 - 겠네<br/>',NULL,31840,3);
INSERT INTO stanza VALUES('K52','4','당신의 상 앞에서 앙망해 -<br/>당신의 사랑의 대상들이<br/>당신의 많은 아들 소리 모아<br/>여기서 당신만을 찬 - 송해<br/>',NULL,31841,4);
INSERT INTO stanza VALUES('K520','1','새벽의 이슬과 같이 신선한 그리스도<br/>부드런 기름 부음이 속삭여 위로하네<br/>시련이 지나가도록 풍랑이 멈추도록<br/>하나님 영광을 위해 주와 함께 서리라<br/>',NULL,31842,1);
INSERT INTO stanza VALUES('K520','chorus','소망의 주 그 음성 달콤하니<br/>주 앞에서 내 마음 즐거워<br/>',NULL,31843,2);
INSERT INTO stanza VALUES('K520','2','고통과 시련 가운데 내 마음 쇠약하여<br/>믿음과 소망의 별이 그 빛을 잃을 때에<br/>주 믿음 능력으로써 힘써 날 붙잡으사<br/>주 영광 모든 풍성을 맛보게 하옵소서<br/>',NULL,31844,3);
INSERT INTO stanza VALUES('K520','3','주는 저 햇빛과 같이 흑암 다 쫓아 내니<br/>치료하는 주의 광선 내 어둠 낮 되게 해<br/>피곤한 내 마음 속에 위로의 주 임하사<br/>복되신 영광의 소망 늘 함께 하옵소서<br/>',NULL,31845,4);
INSERT INTO stanza VALUES('K521','1','오 우리 항상 주 안에 기뻐해 저 흉악함 날 에워싸나<br/>파도같이 환난이 밀려오나 찬송이 한숨보다 더 낫네<br/>',NULL,31846,1);
INSERT INTO stanza VALUES('K521','chorus','항상 기뻐하라 늘 기뻐하세 찬송함이 탄식보다 낫네<br/>죽는 것보다 사는게 낫네 우리 항상 기뻐하세<br/>',NULL,31847,2);
INSERT INTO stanza VALUES('K521','2','오 우리 항상 주 안에 기뻐해 저 어두움 날 에워싸나<br/>저 사탄이 여전히 위협해도- 찬송이 애통함보다 낫네<br/>',NULL,31848,3);
INSERT INTO stanza VALUES('K521','3','오 우리 항상 주 안에 기뻐해 나 병 중에 쇠잔하여도<br/>주의 기쁨 곧 나의 힘이 되니- 주님을 의지해 강해지네<br/>',NULL,31849,4);
INSERT INTO stanza VALUES('K521','4','오 우리 항상 주 안에 기뻐해 이 장막을 곧 벗게 되네<br/>들림 받아 주 함께 있게 되니- 찬송이 근심보다 더 낫네<br/>',NULL,31850,5);
INSERT INTO stanza VALUES('K522','1','나 오-래 고통 맛-보고 주 손-에 모-두 맡-기네<br/>내 눈-물 닦으사 얼굴에 광-채 충-만해<br/>다시는 고통의- 눈물 없도-록 하소서<br/>',NULL,31851,1);
INSERT INTO stanza VALUES('K522','2','나 이-제 작별하-리라 헛된- 즐거-움 오-락과<br/>내 참-된 기쁨은 곧 십자가-에 있-도다<br/>그외엔 모두 헛 -됨을 주 알-려 주셨네<br/>',NULL,31852,2);
INSERT INTO stanza VALUES('K522','3','십자-가만이 축-복 돼 손실-도 유-익 되-도다<br/>그 고-통 달콤해 생각과 의-지 감-정이<br/>여기서 정결케- 되니 참 만-족 누리네<br/>',NULL,31853,3);
INSERT INTO stanza VALUES('K522','4','자신-의 안락 구-하는 자기- 사랑-은 무-익해<br/>오 높-은 참 사랑 내 자아 부-인 할- 때에<br/>내 주님 감상하-시고 참 기-뻐하시네<br/>',NULL,31854,4);
INSERT INTO stanza VALUES('K522','5','나 주-와 같이 택-하리 오 거-룩한- 불 붙-어서<br/>타게- 하옵소서 십자가 지-고 주- 따라<br/>주 사랑하여 언 -제나 찬송-케 하소서<br/>',NULL,31855,5);
INSERT INTO stanza VALUES('K523','1','내 십자가 무거웁지만 은혜 더욱 넘치네-<br/>저 두려운 폭풍이 와도 주의 얼굴 못가려<br/>',NULL,31856,1);
INSERT INTO stanza VALUES('K523','chorus','십자가를 초월한 은혜 풍랑이 주 얼굴 못가려<br/>주님 함께 계시니 내 맘 즐거워하네 대적 권세 이기네<br/>',NULL,31857,2);
INSERT INTO stanza VALUES('K523','2','내 날카로운 가시밭길 주의 것보다 못해-<br/>나 마시는 쓰디 쓴 잔도 주의 잔보다 못해<br/>',NULL,31858,3);
INSERT INTO stanza VALUES('K523','3','내 험하고 어려운 길에 주의 빛 더 빛나네-<br/>내 인생의 책임 다할 때 짐이 가벼워지리<br/>',NULL,31859,4);
INSERT INTO stanza VALUES('K523','4','나 이제 주 면전에 살며 즐겨 주 뜻 따르리-<br/>나에게 온 그 모든 시련 바로 축복이라네<br/>',NULL,31860,5);
INSERT INTO stanza VALUES('K524','1','난 새장 속-의 작-은 새 주가 날 여기 가-뒀네<br/>난 주를 향-해 노-래해 갇히니 심히 즐-거워<br/>주 당신 찬송함으로 내 하나님 기쁘게 해<br/>',NULL,31861,1);
INSERT INTO stanza VALUES('K524','2','갇힌 나 고-요한- 중에 종일토록 주 노-래해<br/>날 기쁘게- 한 하-나님 내 찬양 듣고 계-시네<br/>내 날개 묶으신 주님 내 노래 듣기 원하셔<br/>',NULL,31862,2);
INSERT INTO stanza VALUES('K524','3','찬송에 귀- 기울-이는 주 내게 사랑 주-시네<br/>내 음조 거-칠지-라도 싫어하시지 않-으셔<br/>달콤한 주의 사랑이 내 노래 가락 되었네<br/>',NULL,31863,3);
INSERT INTO stanza VALUES('K524','4','이 새장 나-를 가-두어 맘대로 가지 못-하네<br/>내 날개 묶-이었-어도 맘과 영 자유롭-다네<br/>맘 속의 해방 자유를 감옥이 막지 못하네<br/>',NULL,31864,4);
INSERT INTO stanza VALUES('K524','5','내 맘은 빗-장 초-월해 내 영도 자유롭-다네<br/>사랑하는- 주께- 날아 주의 뜻 경배하-도다<br/>견고한 주 뜻 가운데 자유 얻고 즐거워해<br/>',NULL,31865,5);
INSERT INTO stanza VALUES('K525','1','사방의 견고한- 벽 날 종-일 가두나 날 하나님에게-서<br/>떠나-게 못하네 내 주가 함-께 계시니 담벽도 사-랑스러워<br/>',NULL,31866,1);
INSERT INTO stanza VALUES('K525','2','날 가둔 저 사람-들 내 외-로움 아나 내 주님 옥에 오-셔<br/>날 위-로함 몰라 주 오셔 빛- 가득하고 내 영에 기-쁨 충만해<br/>',NULL,31867,2);
INSERT INTO stanza VALUES('K525','3','주 사랑 나를 감동해 탄식-이 찬송 돼 언제나 어디서-나<br/>주께- 경배 드려 나 순탄하- 든 험하든 주 뜻과 합-하기 원해<br/>',NULL,31868,3);
INSERT INTO stanza VALUES('K525','4','이는 내 보배 되-어 날 유-익게 하네 재앙이 축복 되-어<br/>날 즐-겁게 하네 어떤 일 임-한다 해도 주 있으면- 족하다네<br/>',NULL,31869,4);
INSERT INTO stanza VALUES('K526','1','늘 푸른 하늘 향기론 길 늘 맑은 하늘 허락 않네<br/>늘 고통 없이 평안한 길 주 하나님은 허락 않네<br/>',NULL,31870,1);
INSERT INTO stanza VALUES('K526','chorus','주가 주신 것은 생활의 힘 수고 가운데 참된 안식<br/>시험 가운데 은혜 긍휼 위험과 곤경 속의 끝없는 사랑<br/>',NULL,31871,2);
INSERT INTO stanza VALUES('K526','2','고난과 시험 많은 짐들 피해 가는 것 허락 않네<br/>괴롬과 염려 갖가기 짐 주 하나님은 면케 않네<br/>',NULL,31872,3);
INSERT INTO stanza VALUES('K526','3','맘대로 가는 평탄한 길 잔잔한 바다 허락 않네<br/>뜬 구름 가는 높은 하늘 주 하나님은 허락 않네<br/>',NULL,31873,4);
INSERT INTO stanza VALUES('K527','1','핍박이 강해 피할 곳 없고- 승리할 길도 없는 것 같네<br/>암담해 홀로 눈물을 흘리며 어쩔 줄 몰라 절망하였네<br/>',NULL,31874,1);
INSERT INTO stanza VALUES('K527','chorus','주는 내 소망 기쁨이니 없는 것 있-게 해 죽은 자 살려<br/>',NULL,31875,2);
INSERT INTO stanza VALUES('K527','2','압박이 임해 편한 곳 없고- 사방에 흑암뿐이었다네<br/>때로는 사탄 때로는 친구가 핍박해 생명 위협받았네<br/>',NULL,31876,3);
INSERT INTO stanza VALUES('K527','3','주 외엔 돕는 사람 없도록- 빈곤도 좋아하게 되도록<br/>핍박 위에 또 핍박 임하였네 채찍을 이슬처럼 맞았네<br/>',NULL,31877,4);
INSERT INTO stanza VALUES('K527','4','세상에서 나 벗어났으나- 하늘로 초월하기 원하네<br/>아무런 묶임 없는 자유 얻어 주 의지하여 살고 죽으리<br/>',NULL,31878,5);
INSERT INTO stanza VALUES('K527','5','너무 심하다 하며 울 때에- 핍박도 온갖 힘을 다했네<br/>견딜 수 없는 강한 핍박 왔네 그 후엔 영원 안식 얻었네<br/>',NULL,31879,6);
INSERT INTO stanza VALUES('K527','6','심한 핍박이 실로 유익돼- 하나님 팔을 나타나게 해<br/>핍박 후에는 모두 알게 되리 그 핍박 날 흔들 수 없음을<br/>',NULL,31880,7);
INSERT INTO stanza VALUES('K527','7','핍박 심해도 우린 전진해- 우리의 소망 하늘에 두고<br/>더할 수 없는 강한 핍박 와도 내 맘은 주로 인해 즐거워<br/>',NULL,31881,8);
INSERT INTO stanza VALUES('K528','1','흑암 지나-면 빛이 오리 고통 지나-면 달콤하리<br/>약함 지나-면 강해지리 어려움 가-면 평안 오리<br/>',NULL,31882,1);
INSERT INTO stanza VALUES('K528','2','손실 후에-는 유익 있고 바람 지나-면 잠잠하리<br/>수고 후에-는 안식 오리 비 내린 후-엔 맑으리라<br/>',NULL,31883,2);
INSERT INTO stanza VALUES('K528','3','억압 후에-는 올려지리 근심 지나-면 즐거우리<br/>죽음 후에-는 다시 살고 잃은 후에-는 얻으리라<br/>',NULL,31884,3);
INSERT INTO stanza VALUES('K528','4','피곤함 후-엔 가벼우리 곤고함 후-엔 소생하리<br/>핍절한 후-엔 여유 있고 가난 지나-면 부하리라<br/>',NULL,31885,4);
INSERT INTO stanza VALUES('K528','5','외로움 후-엔 동행 얻고 방랑 지나-면 안주하리<br/>주 다시 뵙-는 그날까지 주님과 다-시 간격없네<br/>',NULL,31886,5);
INSERT INTO stanza VALUES('K528','6','십자가 변-해 면류관 돼 탄식이 변-해 찬송되리<br/>믿고 바란- 것 보이게 돼 다시는 의-심 없게 되리<br/>',NULL,31887,6);
INSERT INTO stanza VALUES('K529','1','동산서 주가 사람을 두 나무 앞에 두셨네<br/>생명나무는 하나님 지식나무 사탄 표해<br/>',NULL,31888,1);
INSERT INTO stanza VALUES('K529','2','생명나무는 하나님 영원한 계획의 중심<br/>사람에게 영접되어 사람 생명 되기 원해<br/>',NULL,31889,2);
INSERT INTO stanza VALUES('K529','3','지식나무는 경고요 하나님 외의 딴 근원<br/>사람이 접촉할 때에 사탄 안의 죽음 임해<br/>',NULL,31890,3);
INSERT INTO stanza VALUES('K529','4','생명나무를 받는 자 하나님 생명 얻어서<br/>진귀한 보석 되어서 하나님 갈망 이루리<br/>',NULL,31891,4);
INSERT INTO stanza VALUES('K529','5','지식나무를 접할 때 사탄이 속에 들어와<br/>죄악과 사망 가져와 하나님 계획 못 이뤄<br/>',NULL,31892,5);
INSERT INTO stanza VALUES('K529','6','하나님만이 생명의 유일한 근원이시니<br/>다른 것 만지는 것은 사망 유래 만짐일세<br/>',NULL,31893,6);
INSERT INTO stanza VALUES('K529','7','겉이 선하든 악하든 지식은 죽음 가져와<br/>하나님 외의 모든 것 사탄의 궤사뿐일세<br/>',NULL,31894,7);
INSERT INTO stanza VALUES('K529','8','악뿐 아니라 선 또한 그리스도와 대립돼<br/>지식에 속한 모든 것 생명과 상반된다네<br/>',NULL,31895,8);
INSERT INTO stanza VALUES('K529','9','주님만 접촉게 하여 주 충만하게 하소서<br/>주 외엔 접촉 안 하리 악뿐 아니라 선까지<br/>',NULL,31896,9);
INSERT INTO stanza VALUES('K53','1','오 태초부터 하나님과 함께 한 말씀<br/>주 당신은 곧 하나님의 영광의 표현<br/>',NULL,31897,1);
INSERT INTO stanza VALUES('K53','chorus','주 살아있는 말씀으로 하나님을 표현해 -<br/>하나님의 본성 영광 모두 다 알게 하셨네<br/>',NULL,31898,2);
INSERT INTO stanza VALUES('K53','2','저 천지 만물 하나님의 영광 말하며<br/>주 하나님의 신성 능력 나타낸다네<br/>',NULL,31899,3);
INSERT INTO stanza VALUES('K53','3','오 하나님의 간증이신 말씀 통하여<br/>참 하나님이 설명되고 표현되셨네<br/>',NULL,31900,4);
INSERT INTO stanza VALUES('K53','4','오 말씀께서 육신 되어 이 땅에 거해<br/>주 하나님을 나타냈네 삶을 통하여<br/>',NULL,31901,5);
INSERT INTO stanza VALUES('K53','5','오 생명되신 사신 말씀 생명의 빛 돼<br/>주 하나님을 표현했네 생명 빛 발해<br/>',NULL,31902,6);
INSERT INTO stanza VALUES('K53','6','곧 심판 집행하심으로 공의 나타내<br/>주 하나님을 온전하게 표현하시리<br/>',NULL,31903,7);
INSERT INTO stanza VALUES('K53','7','오 주 예수는 나타나신 하나님으로<br/>하나님 이미 표명하고 드러내셨네<br/>',NULL,31904,8);
INSERT INTO stanza VALUES('K530','1','하나-님 율법 밖에서 성결-과 양선 요구해<br/>사람-이 할 수 없음을 확실-히 증거하-시네<br/>',NULL,31905,1);
INSERT INTO stanza VALUES('K530','2','사람-의 생각 속에는 선 원-하는 법 있지만<br/>지체- 속에 또 한 법이 싸우-며 어려움- 주네<br/>',NULL,31906,2);
INSERT INTO stanza VALUES('K530','3','사람-의 피조된 생명 생각-의 법을 가지나<br/>사람-의 선한 행위를 유지-할 수가 없-다네<br/>',NULL,31907,3);
INSERT INTO stanza VALUES('K530','4','사람-이 타락할 때에 사탄-과 연합되었네<br/>사탄-의 사악한 법이 몸에- 들어와 다-스려<br/>',NULL,31908,4);
INSERT INTO stanza VALUES('K530','5','지체- 안의 죄의 법이 생각-의 법보다 강해<br/>사탄-의 악한 능력이 선한- 법 정복한-다네<br/>',NULL,31909,5);
INSERT INTO stanza VALUES('K530','6','내 영 - 안에 있는 한 법 곧 생-명의 영의 법을<br/>나 거-듭날 때 얻었네 능력-의 생명 가-졌네<br/>',NULL,31910,6);
INSERT INTO stanza VALUES('K530','7','영 안 -에 생명의 법은 모든- 법보다 강하네<br/>날 죄-의 법서 해방해 율법-의 요구 이-루네<br/>',NULL,31911,7);
INSERT INTO stanza VALUES('K530','8','늘 생 -각 영에 두고서 육체-에 두지 말아라<br/>그럴- 때 죄의 권세를 벗어-나 이기게- 되리<br/>',NULL,31912,8);
INSERT INTO stanza VALUES('K530','9','생각-을 육에 둘 때에 사망-과 흑암뿐이나<br/>생각-을 영에 둘 때는 복된- 생명 평강-이라<br/>',NULL,31913,9);
INSERT INTO stanza VALUES('K530','10','이는- 해방의 길이요 거룩-게 되는 길일세<br/>영 안 -에 살며 영으로 주님-과 동역하-리라<br/>',NULL,31914,10);
INSERT INTO stanza VALUES('K531','1','의문- 율법은 간-증해 하나-님 어-떤 분-인지<br/>성결-과- 공의 영광과 또- 인-자하-심 설-명해<br/>',NULL,31915,1);
INSERT INTO stanza VALUES('K531','2','그분-의 어떠함- 따라 행할- 것 요-구하-시네<br/>우리-를- 의롭다 하고 열-납-하실- 수 있-도록<br/>',NULL,31916,2);
INSERT INTO stanza VALUES('K531','3','율법-은 우리 약-함과 무능-함을- 다 나-타내<br/>생명-을- 주지 못하며 어-떤- 능력-도 못- 주네<br/>',NULL,31917,3);
INSERT INTO stanza VALUES('K531','4','율법-은 목적 아-니고 죄 드-러내-는 것-일세<br/>사람-이- 범할 때 아네 죄-와- 허물-이 많-음을<br/>',NULL,31918,4);
INSERT INTO stanza VALUES('K531','5','율법-은 우릴 주-께로 이끌-어 은-혜 받-게 해<br/>모든- 사-람의 입 막아 다- 죄- 중에- 가두-었네<br/>',NULL,31919,5);
INSERT INTO stanza VALUES('K531','6','율법-은 주의 그-림자 그리-스도-는 실-젤세<br/>하나-님- 성결 공의와 사-랑-과 빛-을 나-타내<br/>',NULL,31920,6);
INSERT INTO stanza VALUES('K531','7','하나-님 그리스-도가 우리-에게- 생명- 주셔<br/>율법-의- 모든 요구를 우-리-에게-서 이-루네<br/>',NULL,31921,7);
INSERT INTO stanza VALUES('K531','8','하나-님의 산 간-증인 주 나-로 생-명 얻-게 해<br/>주 인-해- 율법에 죽고 그- 영- 안에- 거룩-케 돼<br/>',NULL,31922,8);
INSERT INTO stanza VALUES('K532','1','구약시대-엔 돌-비에 하나님 율법- 새겼네<br/>지금 생명-률 성-령-으-로 우리 맘-에 새-겼네<br/>',NULL,31923,1);
INSERT INTO stanza VALUES('K532','2','의문의 율 -법 요-구로 사람의 약함- 드러나<br/>생명의 법-의 공-급-으-로 주의 능-력 누-리네<br/>',NULL,31924,2);
INSERT INTO stanza VALUES('K532','3','의문에 속 -한 율-법은 하나님 알게- 해 주고<br/>생명의 법-은 나-의- 속-에 주의 계-시 공-급해<br/>',NULL,31925,3);
INSERT INTO stanza VALUES('K532','4','율법은 밖에서 다-스려 저 죽은 계명- 통하여<br/>생명의 법 -은 산- 지-식으로 속에서- 절제-케 해<br/>',NULL,31926,4);
INSERT INTO stanza VALUES('K532','5','살아 있는- 생명-의 법 속 각 부분에- 역사해<br/>내 속에서- 날 다-스-리-며 교정하-여 주-시네<br/>',NULL,31927,5);
INSERT INTO stanza VALUES('K532','6','깊고도 섬-세한- 통제 내 안의 가장- 깊은 데<br/>산 생명 느 -낌 가-져-오-며 하나님-을 공-급해<br/>',NULL,31928,6);
INSERT INTO stanza VALUES('K532','7','생명의 법-의 산- 인식 내 안에 가르-치시네<br/>생명의 산 - 법 내-게- 있-어 밖의 교-훈 무-익해<br/>',NULL,31929,7);
INSERT INTO stanza VALUES('K532','8','주여 나로- 이 법-따라 내 안의 관리- 순종해<br/>산 인식 갖 -고 주-님- 자-신 누리도-록 하-소서<br/>',NULL,31930,8);
INSERT INTO stanza VALUES('K533','1','영원한 생명은 교통 산출해<br/>내 영 밀어내는 영 안의 교통<br/>',NULL,31931,1);
INSERT INTO stanza VALUES('K533','2','영원하신 생명 교통 산출해<br/>내 영 안에 그 영 함께 움직여<br/>',NULL,31932,2);
INSERT INTO stanza VALUES('K533','3','내 영 안의 느낌 교통 가져와<br/>내 영 안의 교통 은혜 받게 해<br/>',NULL,31933,3);
INSERT INTO stanza VALUES('K533','4','생명 능력 통해 교통 누리네<br/>내 영 안의 교통 빛에 인도해<br/>',NULL,31934,4);
INSERT INTO stanza VALUES('K533','5','밖의 피로 씻어 교통 유지해<br/>속의 관유 발라 교통 수확해<br/>',NULL,31935,5);
INSERT INTO stanza VALUES('K533','6','십자가로 인해 교통 깊어져<br/>성령 역사 인해 새로워지네<br/>',NULL,31936,6);
INSERT INTO stanza VALUES('K533','7','생명 안의 교통 자아 벗게 해<br/>하나님 안으로 인도하시네<br/>',NULL,31937,7);
INSERT INTO stanza VALUES('K534','1','모든 생명 의식 있고 느낌 갖고 있네<br/>내 안에 거룩한- 생명 느낌 더욱 높아<br/>',NULL,31938,1);
INSERT INTO stanza VALUES('K534','2','생명의 질 높을수록 느낌이 더 강해<br/>하나님 생명 높-으니 느낌 제일 높네<br/>',NULL,31939,2);
INSERT INTO stanza VALUES('K534','3','하나님 생명 느낌은 하나님의 느낌<br/>선량한 느낌 초-월해 내 영 안에 있네<br/>',NULL,31940,3);
INSERT INTO stanza VALUES('K534','4','내적인 생명의 느낌 가장 높은 느낌<br/>모든 것 분별하-여서 주의 뜻 밝히네<br/>',NULL,31941,4);
INSERT INTO stanza VALUES('K534','5','안에 생명 느낌으로 하나님 알겠네<br/>바깥의 노력 아-니요 자연스런 계시<br/>',NULL,31942,5);
INSERT INTO stanza VALUES('K534','6','생명 안에 자랄수록 느낌이 예민해<br/>생명으로 행동-할 때 느낌 강해지네<br/>',NULL,31943,6);
INSERT INTO stanza VALUES('K534','7','생명의 느낌 훈련해 우리 영 강해져<br/>하나님 느낌 통-하여 교통 더 증가해<br/>',NULL,31944,7);
INSERT INTO stanza VALUES('K535','1','거듭난 성도 영 안의 인식 실재적이고 풍성하여서<br/>밖의 가르침 필요치 않네 속에서 주를 알게 된다네<br/>',NULL,31945,1);
INSERT INTO stanza VALUES('K535','2','영원하고도 뛰어난 생명 신성한 기능 다 구비했네<br/>이 생명 통한 안의 인식은 바깥의 지식 능가한다네<br/>',NULL,31946,2);
INSERT INTO stanza VALUES('K535','3','내 맘에 있는 생명의 법은 성령에 의해 새겨졌다네<br/>주 알게 하신 안의 통제는 바깥의 교훈 능가한다네<br/>',NULL,31947,3);
INSERT INTO stanza VALUES('K535','4','내 영 안에서 기름 바르며 하나님 일을 내게 알리네<br/>바깥의 교훈보다 뛰어난 이 바름 통해 주를 알게 돼<br/>',NULL,31948,4);
INSERT INTO stanza VALUES('K535','5','삼일 하나님 내 안에 거해 늘 역사하며 운행하시네<br/>이 운행 인한 안의 느낌이 하나님 알게 하여 준다네<br/>',NULL,31949,5);
INSERT INTO stanza VALUES('K535','6','나에게 안의 인식 있으니 바깥의 지식 필요 없다네<br/>다만 언제나 영 안에 살며 영 지시 좇아 행하면 되네<br/>',NULL,31950,6);
INSERT INTO stanza VALUES('K535','7','주 안에 살며 속 느낌따라 행동할수록 인식 얻으며<br/>하나님께서 나의 마음에 주 그리스도 새겨 주시네<br/>',NULL,31951,7);
INSERT INTO stanza VALUES('K535','8','내 안의 생명 인식 통하여 주님과 교통 유지한다네<br/>감추인 안의 인식 통하여 신성의 충만 내게 옮겨져<br/>',NULL,31952,8);
INSERT INTO stanza VALUES('K536','1','하나-님 육-신된- 원칙은 하나님과- 사람 연합한<br/>비-밀한- 사람- 되어서 하나-님 계-획 이-루네<br/>',NULL,31953,1);
INSERT INTO stanza VALUES('K536','2','사람-은 밖-의 표- 현이요 하나님은- 안의 생명<br/>하나-님으-로 점-유되어 하나-님만-을 나-타내<br/>',NULL,31954,2);
INSERT INTO stanza VALUES('K536','3','하나-님 지-혜 나-타내려 사람 안에- 구속 이뤄<br/>사람-을 통-해 전-파되어 모든- 피조-물 알-게 돼<br/>',NULL,31955,3);
INSERT INTO stanza VALUES('K536','4','이 시-대 모-든 영-적 일은 하나님 사-람과 함께<br/>긴밀-히 연-결하-여 서로 의지-함으-로 이-뤄져<br/>',NULL,31956,4);
INSERT INTO stanza VALUES('K536','5','하나-님 계-획 이-루려면 하나님 혼-자 안 되네<br/>하나-님 사-람 협-력하여 완성-해 낼- 수 있-다네<br/>',NULL,31957,5);
INSERT INTO stanza VALUES('K536','6','하나-님 육-신 된- 원칙을 모든 일에- 적용하여<br/>모든- 은사-와 기-능으로 함께- 봉사-할 수- 있네<br/>',NULL,31958,6);
INSERT INTO stanza VALUES('K537','1','피조된 사람 세 부분일세 몸과 혼 아울러 영이 있네<br/>주 온전한 뜻 이루려 주를 누리며 공급받네<br/>',NULL,31959,1);
INSERT INTO stanza VALUES('K537','2','신체는 몸-의 부분일세 이로써 물-질 알-게 돼<br/>물질세계를 접촉해 자신의 형체 나-타내<br/>',NULL,31960,2);
INSERT INTO stanza VALUES('K537','3','혼은 곧 안-의 부분일세 사람이 자-신 자-각해<br/>사람의 심리 방-면 정신 세계를 접-촉해<br/>',NULL,31961,3);
INSERT INTO stanza VALUES('K537','4','사람의 중심엔 영- 있어 하나님 깨-닫게- 되네<br/>영으로 주를 받으며 영의 세계를 접 -촉해<br/>',NULL,31962,4);
INSERT INTO stanza VALUES('K537','5','사람의 혼-은 세- 부분 생각과 의-지와- 감정<br/>이것은 사람의 인격 이로써 사람 뜻 - 이뤄<br/>',NULL,31963,5);
INSERT INTO stanza VALUES('K537','6','사람의 영-은 세- 부분 교통과 직-감과-양심<br/>이로써 주와 교통해 주 경배하며 주 - 받네<br/>',NULL,31964,6);
INSERT INTO stanza VALUES('K537','7','혼의 각 부-분 사-용해 하나님 모-든 택-하심<br/>영으로 함께 받으며 몸으로 주를 나 -타내<br/>',NULL,31965,7);
INSERT INTO stanza VALUES('K537','8','사람은 거-듭남-으로 영원한 생-명 받-아서<br/>영따라 혼이 변화돼 몸 구속됨이 필 -요해<br/>',NULL,31966,8);
INSERT INTO stanza VALUES('K537','9','신성한 주-님 역-사로 사람의 전-체 조-화돼<br/>주의 온전한 몸 이뤄 영광의 주를 나 -타내<br/>',NULL,31967,9);
INSERT INTO stanza VALUES('K538','1','창세 전에 하-나님은 아들 명분 주-셨네<br/>그의 영을 통-해 나로 아들 형-상 본받게<br/>사랑하-는 독-생자가 맏아들-이 되-도록<br/>그 아들과 형-제들이 그의 영-광 표현해<br/>',NULL,31968,1);
INSERT INTO stanza VALUES('K538','2','영 안에서 거-듭나서 그의 아들 됐-으나<br/>더욱 성숙해-야 우린 하나님-의 후사돼<br/>완전하-게 장-성해야 아들 명-분 누-리리<br/>충만하게 자-라나야 후사 분-깃 맛보리<br/>',NULL,31969,2);
INSERT INTO stanza VALUES('K538','3','우리 영과 혼-과 몸이 주의 형상 본-받아<br/>영광 안에 들-어갈 때 모두 완-성되리라<br/>몸의 구-속 통-하여서 아들 명-분 이-뤄져<br/>마지막의 변-형 통해 주의 갈-망 만족돼<br/>',NULL,31970,3);
INSERT INTO stanza VALUES('K538','4','마지막의 변-형 통해 온전히 거룩-게 돼<br/>영광 안에 들-어가서 아들과- 같게 되리<br/>하나님-의 아-들들이 나타나-는 그-때에<br/>썩어짐의 종-노릇을 피조물-도 벗으리<br/>',NULL,31971,4);
INSERT INTO stanza VALUES('K539','1','하나님은 우리들을 그릇으-로 지었네-<br/>사랑하는 마음짓고 받는 영-을 지었네<br/>',NULL,31972,1);
INSERT INTO stanza VALUES('K539','2','마음으로 사랑하고 영으로- 주 영접해-<br/>이렇게 해 하나님을 생명으-로 취하네<br/>',NULL,31973,2);
INSERT INTO stanza VALUES('K539','3','우리 마음 부패케 해 영을 죽-게 한 사탄-<br/>주를 접촉 못하게 해 자아 의-지하게 해<br/>',NULL,31974,3);
INSERT INTO stanza VALUES('K539','4','주님 그의 구원 안에 내 맘과- 영 새롭게 해<br/>사랑하고 영접하는 본능 회-복시켰네<br/>',NULL,31975,4);
INSERT INTO stanza VALUES('K539','5','새롭게 된 마음으로 하나님- 을 사랑해-<br/>새롭게 된 영으로서 경배하-며 영접해<br/>',NULL,31976,5);
INSERT INTO stanza VALUES('K539','6','주님 향해 우리 마음 성실하-고 단순해-<br/>우리 영은 가난하여 추구하-며 온순해<br/>',NULL,31977,6);
INSERT INTO stanza VALUES('K539','7','주여 내 맘 주 사랑해 신선하-게 하소서-<br/>내 영 또한 활발하게 주 접하-게 하소서<br/>',NULL,31978,7);
INSERT INTO stanza VALUES('K54','1','주님은 영 - 원한 - 말씀 아버지 독 - 생자<br/>하나 - 님 나타낸 아들 사랑하는 아들<br/>오 얼 - 마나 신성 - 한지 주 통해 하나님 풍성 보네<br/>',NULL,31979,1);
INSERT INTO stanza VALUES('K54','2','주 통해 아 - 버지 - 영광 밝히 다 나 - 타내<br/>하나 - 님 신성 충만해 영원히 거룩해<br/>오 신 - 성한 아들 - 이여 주 통해 하나님 풍성 보네<br/>',NULL,31980,2);
INSERT INTO stanza VALUES('K54','3','주는 하나 - 님 본질 담은 하나님 형상이요<br/>피조되잖은 빛의 광채 그 본체의 형상<br/>오 얼 - 마나 신성 - 한지 주 통해 하나님 풍성 보네<br/>',NULL,31981,3);
INSERT INTO stanza VALUES('K54','4','주 이름 높 - 은 비 - 밀은 천사도 알지 못해<br/>오묘하고 신성한 당신 아버지만 아네<br/>오 얼 - 마나 신성 - 한지 주 통해 하나님 풍성 보네<br/>',NULL,31982,4);
INSERT INTO stanza VALUES('K54','5','축복된 우주의 중 - 심은 당신의 어 - 떠함<br/>영원 - 히 찬송하겠네 하나님 아들을<br/>오 얼 - 마나 신성 - 한지 주 통해 하나님 풍성 보네<br/>',NULL,31983,5);
INSERT INTO stanza VALUES('K540','1','주님의 생명 누리며 교통 나누려면<br/>합당한 마음 필요해 주 은혜로 인해<br/>',NULL,31984,1);
INSERT INTO stanza VALUES('K540','2','순결한 생활 위하여 필요한 마음은<br/>주의 뜻 알기 위하여 두렵고 떠는 맘<br/>',NULL,31985,2);
INSERT INTO stanza VALUES('K540','3','불 같은 사랑 얻는 데 필요한 마음은<br/>주 향한 열심과 사랑 충만한 그 마음<br/>',NULL,31986,3);
INSERT INTO stanza VALUES('K540','4','성실히 순종하려는 마음이 필요해<br/>강하든 또한 유하든 주 따르는 마음<br/>',NULL,31987,4);
INSERT INTO stanza VALUES('K540','5','정결한 양심에 믿음 더해진 마음은<br/>범사에 주와 화목해 평안함 누리리<br/>',NULL,31988,5);
INSERT INTO stanza VALUES('K540','6','주 항상 이 맘 주셔서 주 사모하게 해<br/>부요한 주를 누려서 주 충만되게 해<br/>',NULL,31989,6);
INSERT INTO stanza VALUES('K541','1','주는 지금 그 영일세 내 영 안에 사네<br/>두 영이 한 영 됐으니 주와 난 하날세<br/>',NULL,31990,1);
INSERT INTO stanza VALUES('K541','2','주의 영과 우리 영의 영원한 그 증거<br/>우리가 하나님 자녀 후사됨 말하네<br/>',NULL,31991,2);
INSERT INTO stanza VALUES('K541','3','주님 자신 분배하려 생명의 영 됐네<br/>우리는 오늘 영 안에 주 풍성 누리네<br/>',NULL,31992,3);
INSERT INTO stanza VALUES('K541','4','빛 비추며 인도하는 생명의 영인 주<br/>영 안에서 그를 좇아 살며 행동하네<br/>',NULL,31993,4);
INSERT INTO stanza VALUES('K541','5','내 영 안에 그 영인 주 힘 주고 공급해<br/>내 영 안에 주 영 인해 주님께 경배해<br/>',NULL,31994,5);
INSERT INTO stanza VALUES('K541','6','그 영인 주 탄식하며 영 안에 간구해<br/>내 영과 주의 영 함께 주께 기도하네<br/>',NULL,31995,6);
INSERT INTO stanza VALUES('K541','7','영 안으로 돌이켜서 주의 영 접촉해<br/>거룩한 주의 공급을 영 안에 누리네<br/>',NULL,31996,7);
INSERT INTO stanza VALUES('K541','8','주와의 연합 놀라와 두 영이 한 영 돼<br/>내 영에 그 영 사시니 영 안에 주 거해<br/>',NULL,31997,8);
INSERT INTO stanza VALUES('K542','1','십자가로 분별하여 혼을 죽음에 넘겨<br/>종일 자아 거절하고 너의 영 안에 살라<br/>',NULL,31998,1);
INSERT INTO stanza VALUES('K542','2','십자가로 분별하여 영 안에 행하도록<br/>주의 생명 말씀으로 영과 혼을 구분해<br/>',NULL,31999,2);
INSERT INTO stanza VALUES('K542','3','십자가로 분별하여 생각 새롭게 되어<br/>감정 주께 드릴 때에 의지 순종하게 돼<br/>',NULL,32000,3);
INSERT INTO stanza VALUES('K542','4','십자가로 분별하여 열린 휘장 지나가<br/>육과 혼이 파쇄될 때 영이 지위 얻으리<br/>',NULL,32001,4);
INSERT INTO stanza VALUES('K542','5','십자가로 분별하라 영이 지성소이니<br/>영 안에서 교통하여 주의 임재 얻으라<br/>',NULL,32002,5);
INSERT INTO stanza VALUES('K542','6','십자가로 분별하여 요단 강을 건너듯<br/>가나안 땅 들어가서 주를 누리며 살라<br/>',NULL,32003,6);
INSERT INTO stanza VALUES('K542','7','십자가로 분별하여 항상 영 안에 행해<br/>좋은 땅인 주를 가꿔 그의 풍성 얻으라<br/>',NULL,32004,7);
INSERT INTO stanza VALUES('K543','1','성전- 깊은 지성소에 언약-궤 은혜 보좌 있네-<br/>보좌-에 주 영광- 있어 여기-서 하나-님 만나<br/>',NULL,32005,1);
INSERT INTO stanza VALUES('K543','2','오늘- 난 주님의 성전 내 영-은 지성소-이니-<br/>여기-에 주님 거-주해 그 영-이 함께- 사시네<br/>',NULL,32006,2);
INSERT INTO stanza VALUES('K543','3','내 깊-은 지성소에서 하나-님 내 모든-것 돼-<br/>여기-서 그 영 실-제 돼 쓰고-도 남는- 실재 돼<br/>',NULL,32007,3);
INSERT INTO stanza VALUES('K543','4','내 영- 안에 주 접하며 주님-과 함께 산-다네-<br/>여기-서 나의 영-으로 주님-과 교통-한다네<br/>',NULL,32008,4);
INSERT INTO stanza VALUES('K543','5','여기-서 주는 좋은 땅 난 그-의 풍성 누-리네-<br/>여기-서 원수 공-격해 권위-로 음부- 처리해<br/>',NULL,32009,5);
INSERT INTO stanza VALUES('K543','6','난 영-의 인식 추구해 영과- 혼 구분해-야 해-<br/>이 지-성소에 살-면서 주 임-재 누리-기 원해<br/>',NULL,32010,6);
INSERT INTO stanza VALUES('K543','7','주 충-만하게 얻으며 주 영-원한 뜻 이-루게-<br/>영원-히 혼 거절-하고 주 안-식에 들-어가리<br/>',NULL,32011,7);
INSERT INTO stanza VALUES('K544','1','내 영-과 혼-을 분-별하여 주 알 수 있-게 하소서<br/>주 지-금 그- 영 되-시어서 내 영-과 한- 영 되-셨네<br/>',NULL,32012,1);
INSERT INTO stanza VALUES('K544','2','내 영-과 혼-을 분-별하여 혼 생명 거-절케 하며<br/>영 안-에 주-를 좇-게 하여 영 적-용하-게 하-소서<br/>',NULL,32013,2);
INSERT INTO stanza VALUES('K544','3','내 영-과 혼-을 분-별하여 내 죄와 자-아 벗어나<br/>내 생-각 육-에 두-지 않고 늘 영-에 두-게 하-소서<br/>',NULL,32014,3);
INSERT INTO stanza VALUES('K544','4','내 영-과 혼-을 분-별하여 날 혼에서- 건지소서<br/>늘 영- 안에-서 행-하게 해 참된- 신령-함 주-소서<br/>',NULL,32015,4);
INSERT INTO stanza VALUES('K544','5','내 영-과 혼-을 분-별하여 내 자아 드-러 내소서<br/>늘 십-자가-를 적-용하여 주 살-아 내-게 하-소서<br/>',NULL,32016,5);
INSERT INTO stanza VALUES('K544','6','내 영-과 혼- 을 분-별하여 내 혼을 변-케 하소서<br/>주 당-신 형-상 본-받아서 주 목-적에- 달하-도록<br/>',NULL,32017,6);
INSERT INTO stanza VALUES('K544','7','내 영-과 혼-을 분-별하여 주 사신 말-씀 주소서<br/>내 영-을 혼-과 구-분하여 그 안-에 늘- 거하-소서<br/>',NULL,32018,7);
INSERT INTO stanza VALUES('K545','1','삼일-하나님 영광의 영 지금- 내 영-에 거-하며<br/>하나-님 표현하-려고 내 속-에서 흘러나네<br/>',NULL,32019,1);
INSERT INTO stanza VALUES('K545','2','내 밖-의 타고난- 사람 늘 그-영 속-박하-였네<br/>주 거-처 정하지- 못해 오히-려 갇히셨다네<br/>',NULL,32020,2);
INSERT INTO stanza VALUES('K545','3','질그-릇 속 보배-처럼 주 감-취어-져 안- 보여<br/>질그-릇 파쇄돼-야만 보배-가 나타나겠네<br/>',NULL,32021,3);
INSERT INTO stanza VALUES('K545','4','혼 생-명은 묶임-이니 내 자-아 헐-려야-하네<br/>타고-난 사람 깨-질 때 그 영- 해방될 수 있네<br/>',NULL,32022,4);
INSERT INTO stanza VALUES('K545','5','이래-서 고난과-환경 우리-에게- 임한-다네<br/>그것-은 겉사람- 깨려 주께-서 허락한 걸세<br/>',NULL,32023,5);
INSERT INTO stanza VALUES('K545','6','겉사-람 곧 내 옛- 혼이 파쇄-되고- 상처-받아<br/>속사-람 곧 내 새- 영이 그 영-과 함께 해방돼<br/>',NULL,32024,6);
INSERT INTO stanza VALUES('K545','7','주여- 날 깨뜨리-시어 날 보-존 않-게 하-소서<br/>기꺼-이 받게 하-소서 모든- 손상과 파쇄를<br/>',NULL,32025,7);
INSERT INTO stanza VALUES('K545','8','다시-는 원망 없-도록 주 파-쇄 귀-히 여-기고<br/>그 어-떤 이익보-다도 중하-게 보게 하소서<br/>',NULL,32026,8);
INSERT INTO stanza VALUES('K546','1','하나님의 뜻은 우릴 자기 아들 형상 이루려<br/>성령으로 우리 몸 안에서 변케 하여 주시네<br/>',NULL,32027,1);
INSERT INTO stanza VALUES('K546','chorus','주여 내 혼 각 부분이 주의 형상 되도록<br/>성령 안에 잠기게 해 주의 모양되게 해<br/>',NULL,32028,2);
INSERT INTO stanza VALUES('K546','2','하나님은 그의 생명으로 나를 거듭 나게 해<br/>그는 또한 나의 혼 속에서 계속 변케 하시네<br/>',NULL,32029,3);
INSERT INTO stanza VALUES('K546','3','내 영으로부터 역사하여 내 혼 변케 하시며<br/>내 혼 각 부분과 내 온 몸이 주께 복종하도록<br/>',NULL,32030,4);
INSERT INTO stanza VALUES('K546','4','그의 영의 생명 능력으로 그의 형상 되게 해<br/>점점 그의 영광 더함으로 주를 닮게 하시네<br/>',NULL,32031,5);
INSERT INTO stanza VALUES('K547','1','나의 노력 아닌 순종함만이 나로 안식 능력 얻게 하시네<br/>선행 결심 아닌 영 좇음만이 죄의 묶임 벗고 승리하게 해<br/>',NULL,32032,1);
INSERT INTO stanza VALUES('K547','2','의문 아닌 성령 의지함만이 나로 칭찬받고 생명 얻게 해<br/>사람 교훈 아닌 주의 관유가 나로 비춤 받고 교통케 하네<br/>',NULL,32033,2);
INSERT INTO stanza VALUES('K547','3','원함 경주 아닌 주 긍휼만이 나로 주의 은혜 얻게 하시네<br/>나의 총명 아닌 주 은혜만이 나로 환난 곤경 통과케 하네<br/>',NULL,32034,3);
INSERT INTO stanza VALUES('K547','4','말의 지혜 아닌 주 능력만이 죄의 세상에서 구원받게 해<br/>재능 세력 아닌 주 성령만이 나로 주의 사명 완성케 하네<br/>',NULL,32035,4);
INSERT INTO stanza VALUES('K548','1','복된 하나님의 복음 고통당하는 자 구해<br/>주가 채찍 맞음으로 나는 나음 얻었네<br/>',NULL,32036,1);
INSERT INTO stanza VALUES('K548','chorus','고통 중에 있는 자여 완전 구속 찬양해<br/>의사되신 구주 예수 나를 치료하셨네<br/>',NULL,32037,2);
INSERT INTO stanza VALUES('K548','2','누가 도움 청하든지 거절 않고 받은 주-<br/>그가 채찍 맞았으니 나를 고칠 수 있네<br/>',NULL,32038,3);
INSERT INTO stanza VALUES('K548','3','그의 거룩하신 관유 은혜 주는 성령이니<br/>채찍 맞은 구주시여 내게 안수하소서<br/>',NULL,32039,4);
INSERT INTO stanza VALUES('K548','4','사탄 화살 나를 쏠 때 나의 방패 되소서-<br/>주가 채찍 맞았으니 우린 안전히 가네<br/>',NULL,32040,5);
INSERT INTO stanza VALUES('K548','5','주를 영화롭게 하려 나의 지체 헌신하니<br/>주의 치료하는 구속 잊지 않게 하소서<br/>',NULL,32041,6);
INSERT INTO stanza VALUES('K549','1','날 치료한 그의 이름 그 구속 찬미하겠네<br/>능력의 주 나의 의사 질병서 나를 해방해<br/>',NULL,32042,1);
INSERT INTO stanza VALUES('K549','chorus','치료하고 치료하셔 치료할 권능 가졌네<br/>많은 사람 살렸으니 지금 주 치료 믿으라<br/>',NULL,32043,2);
INSERT INTO stanza VALUES('K549','2','그가 나를 치료하리 그 말씀 믿기만 하면<br/>나로 질병 벗게 하리 소망과 평강 가득해<br/>',NULL,32044,3);
INSERT INTO stanza VALUES('K549','3','그가 나를 고치리라 믿고서 옷깃 만지니<br/>그의 능력 내게 흘러 홀연히 내 병 나았네<br/>',NULL,32045,4);
INSERT INTO stanza VALUES('K549','4','그가 전에 치료하듯 또 나를 치료하시리<br/>그의 능력 여전하네 내 구주 살아 계시니<br/>',NULL,32046,5);
INSERT INTO stanza VALUES('K549','5','그가 나를 치료하심 나 지금 온전히 믿네<br/>믿음으로 인해 주가 날 다시 살게 하시리<br/>',NULL,32047,6);
INSERT INTO stanza VALUES('K55','1','주 - 당신은 하나님 말 - 씀 하나 - 님의 - 아들<br/>하나님 참된 형상이신 주 그 영 - 광 모양 있네<br/>',NULL,32048,1);
INSERT INTO stanza VALUES('K55','2','하나님의 본성 모든 풍 - 성 당신 - 안에 - 거해<br/>당신은 하나님의 체 - 현 하나 - 님 표 - 현해<br/>',NULL,32049,2);
INSERT INTO stanza VALUES('K55','3','하 - 나님 영광 광 - 채 - 요 하나님과 하 - 나니<br/>하나님 본체 형상이 - 요 하나 - 님 실 - 제라<br/>',NULL,32050,3);
INSERT INTO stanza VALUES('K55','4','하 - 나님이 주 안 - 에 - 서 우리 - 생명 - 과 빛<br/>하나님 성품 가진 우 - 리 주 인 - 해 자 - 라네<br/>',NULL,32051,4);
INSERT INTO stanza VALUES('K55','5','하 - 나님 은혜 주 - 안 - 에 얻고 - 또 누 - 리네<br/>하나님 실재 당신 안 - 에 찾고 - 또 본 - 다네<br/>',NULL,32052,5);
INSERT INTO stanza VALUES('K55','6','하나님 충만 주 안에 받으니 은혜 - 위에 - 은혜<br/>당신 안에서 하나님과 나 합하 - 여 함 - 께 해<br/>',NULL,32053,6);
INSERT INTO stanza VALUES('K55','7','내 - 하나님 내 주께 경배해 주는 - 내 모 - 든 것<br/>내 마음 주를 사랑하므로 영원 - 히 누 - 리리<br/>',NULL,32054,7);
INSERT INTO stanza VALUES('K550','1','주 예수 길을 가실 때 무리 에워싸 밀더니<br/>병든 그 여인 뒤에 와서 만지고 즉시 낫네<br/>',NULL,32055,1);
INSERT INTO stanza VALUES('K550','chorus','주님 만지기만 하면 즉시 고침 받으리니<br/>의심치 말고 와 만지라 만질 때 고침 얻네<br/>',NULL,32056,2);
INSERT INTO stanza VALUES('K550','2','주님 만지기만 하면 고침 받고 평강 얻네<br/>그 발 아래 내 무거운 짐 다 벗어 놓고 쉬네<br/>',NULL,32057,3);
INSERT INTO stanza VALUES('K550','3','주님 만지기만 하면 모든 질병 고침 받네<br/>내 영원히 그를 찬송해 모든 치료 받았네<br/>',NULL,32058,4);
INSERT INTO stanza VALUES('K550','4','주님 만지기만 하면 돌이켜 나를 보시네<br/>아 그 눈빛 기묘한 사랑 나 이미 치료됐네<br/>',NULL,32059,5);
INSERT INTO stanza VALUES('K550','5','주님 만지기만 하면 능히 어떤 병이든지<br/>만지기만 하면 다 낫네 반드시 고침 얻네<br/>',NULL,32060,6);
INSERT INTO stanza VALUES('K551','1','주님은 기-도의 알파 내 기도 가르쳐<br/>그분이 인-도 안하면 기도의 길- 몰라<br/>',NULL,32061,1);
INSERT INTO stanza VALUES('K551','2','주는 기도-의 오메가 가장 크신 아멘<br/>우리가 기-도 마칠 때 주 함께 아-멘해<br/>',NULL,32062,2);
INSERT INTO stanza VALUES('K551','3','주께서 시-작 끝 사이 연결해 주시고<br/>주께서 하-실 말씀을 우리로 하-게 해<br/>',NULL,32063,3);
INSERT INTO stanza VALUES('K551','4','주께서 나-의 기도의 처음과 나중 돼<br/>내 모든 기-도 주 뜻과 온전히 일-치돼<br/>',NULL,32064,4);
INSERT INTO stanza VALUES('K551','5','주께서 우-리 기도의 시작이 되시고<br/>주께서 우-리 기도의 마침이 되-소서<br/>',NULL,32065,5);
INSERT INTO stanza VALUES('K552','1','부서진 자가 주께 드리는 영 안에 타는 거룩한 향기<br/>성령에 의해 불붙여져서 믿음의 호소로써 전달돼<br/>',NULL,32066,1);
INSERT INTO stanza VALUES('K552','2','은혜로 나온 향료 속에는 믿음과 사랑 고난 섞였네<br/>말씀에 가득 감추인 향기 하나님 흠향하고 맛보셔<br/>',NULL,32067,2);
INSERT INTO stanza VALUES('K552','3','상승 기류와 같은 기도가 이슬비 주어 강물 만드네<br/>마른 땅 위에 흘러갈 때에 사막이 장미처럼 피리라<br/>',NULL,32068,3);
INSERT INTO stanza VALUES('K552','4','성령 충만한 하늘 전화기 주 기름으로 공급하시니<br/>같은 맘으로 기도할 때에 영 충만되어 등불 빛나네<br/>',NULL,32069,4);
INSERT INTO stanza VALUES('K552','5','우주의 가장 강한 힘이니 그 어느 것도 막을 수 없네<br/>하나님 손을 움직이게 해 큰 바퀴 굴려 온 땅 가게 해<br/>',NULL,32070,5);
INSERT INTO stanza VALUES('K552','6','주여 내 영에 역사하시어 나에게 기도 가르치소서<br/>내 안에 계신 그리스도가 하늘의 주께 기도하도록<br/>',NULL,32071,6);
INSERT INTO stanza VALUES('K553','1','주여 조용히 당신 앞으로 나의 온 존재 돌이킵니다<br/>다시는 밖의 기도 하잖고- 영 따라 기도하게 하소서<br/>',NULL,32072,1);
INSERT INTO stanza VALUES('K553','2','하늘서 주가 기도 들을 때 주께서 또한 내 안에 거해<br/>주님께 내가 부르짖을 때- 주께서 내 안에서 표현해<br/>',NULL,32073,2);
INSERT INTO stanza VALUES('K553','3','때로는 표현할 수 없지만 그 영의 탄식 좇아 기도해<br/>밖에서 내가 구함 아니요- 주께서 표현되는 것일세<br/>',NULL,32074,3);
INSERT INTO stanza VALUES('K553','4','진실로 주와 교통하도록 내 안의 주가 표현되도록<br/>주님을 먹고 흡수하면서- 주 공급 누리기를 원하네<br/>',NULL,32075,4);
INSERT INTO stanza VALUES('K553','5','이 교통 안에 빛이 날 비춰 보혈로 나를 정결케 하네<br/>이로써 나로 더 큰 빛 얻고- 분명한 주의 표현 되게 해<br/>',NULL,32076,5);
INSERT INTO stanza VALUES('K553','6','여기서 주의 관유 발라져 내 속에 주의 성분 더해져<br/>내 성분 점점 감소될 때에- 주 나를 통해 더욱 표현돼<br/>',NULL,32077,6);
INSERT INTO stanza VALUES('K553','7','주님 더 내게 더해지도록 주님께 나를 열어드리네<br/>주님의 생수 흐름 안에서- 날 열고 사람들과 교통해<br/>',NULL,32078,7);
INSERT INTO stanza VALUES('K554','1','기도를 가르치소서 죄수를 해방해-<br/>원수를 묶고 쫓아내 끝낼 수 있도록<br/>',NULL,32079,1);
INSERT INTO stanza VALUES('K554','2','기도를 가르치소서 원수를 이기게-<br/>진지에 서서 싸우며 요새 깨뜨리게<br/>',NULL,32080,2);
INSERT INTO stanza VALUES('K554','3','하나님 제일 좋은 것 받게 해 주소서-<br/>피 아래 권리 얻으며 천지를 진동케<br/>',NULL,32081,3);
INSERT INTO stanza VALUES('K554','4','믿음의 기도 인하여 주님과 수고해-<br/>승리의 권세 사용해 만유 다 얻으리<br/>',NULL,32082,4);
INSERT INTO stanza VALUES('K555','1','주여 우리 모여서 함께 기도합니다<br/>우린 주님 앞에 선 제사장의 무리니<br/>',NULL,32083,1);
INSERT INTO stanza VALUES('K555','chorus','함께 기도하면서 주님 접촉합니다<br/>영 안에서 연합해 교회 건축하도록<br/>',NULL,32084,2);
INSERT INTO stanza VALUES('K555','2','제사장의 거룩한 직분 다하기 위해<br/>영으로 주 뜻 알고 이루기 원합니다<br/>',NULL,32085,3);
INSERT INTO stanza VALUES('K555','3','지성소로 들어가 은혜 보좌 만지며<br/>영의 느낌 따라서 주께 기도합니다<br/>',NULL,32086,4);
INSERT INTO stanza VALUES('K555','4','은혜 보좌로부터 은혜 강물 흐를 때<br/>때에 따라 우리는 도움 얻게 됩니다<br/>',NULL,32087,5);
INSERT INTO stanza VALUES('K555','5','나의 뜻을 버리고 주 뜻 따라 구하여<br/>내 기도가 주님의 표현 되게 하소서<br/>',NULL,32088,6);
INSERT INTO stanza VALUES('K555','6','우리 자신 돌보는 필요 구하지 않고<br/>주님 출구 얻도록 기도하겠습니다<br/>',NULL,32089,7);
INSERT INTO stanza VALUES('K555','7','주의 생명 생수로 우리 만족할 때에<br/>주가 더욱 역사해 주 뜻 이루옵소서<br/>',NULL,32090,8);
INSERT INTO stanza VALUES('K556','1','지성소에 들어가 휘장 안에 생활해-<br/>주의 보좌 만져서- 생수 흐르게 하리<br/>',NULL,32091,1);
INSERT INTO stanza VALUES('K556','2','지성소인 내 영에 지금 주님 거하니-<br/>영 안에 돌아갈 때- 나는 주님 만나네<br/>',NULL,32092,2);
INSERT INTO stanza VALUES('K556','3','부활하신 주 향기 내 영에서 흘러나-<br/>영 안에 내 기도로- 주가 표현되시네<br/>',NULL,32093,3);
INSERT INTO stanza VALUES('K556','4','영 안의 주 만질 때 주의 풍성 누리네-<br/>생명의 빛 생명 떡- 부활 향기 누리네<br/>',NULL,32094,4);
INSERT INTO stanza VALUES('K556','5','만질수록 더 깊고 풍성하신 주 예수-<br/>생명의 법 만지며- 감췬 만나 누리네<br/>',NULL,32095,5);
INSERT INTO stanza VALUES('K556','6','싹 난 지팡이 같은 부활 열납 만지네-<br/>여기 은혜 보좌에- 은혜 강물 흐르네<br/>',NULL,32096,6);
INSERT INTO stanza VALUES('K556','7','우리 함께 기도해 영을 해방함으로-<br/>지성소로 들어가- 주를 접촉하겠네<br/>',NULL,32097,7);
INSERT INTO stanza VALUES('K556','8','지성소에 거하며 제사장의 생활해-<br/>생수 흐르기까지- 은혜 보좌 만지리<br/>',NULL,32098,8);
INSERT INTO stanza VALUES('K557','1','지성소 안에 깊이 들어가 은혜의 보좌 만질 때<br/>지성소 안에 깊이 들어가 은혜의 보좌 만질 때<br/>할렐루야 할렐루야 은혜의 강물 흐르네<br/>할렐루야 할렐루야 은혜의 강물 흐르네<br/>',NULL,32099,1);
INSERT INTO stanza VALUES('K557','2','지성소 안에 깊이 들어가 휘장 안에 생활할 때<br/>지성소 안에 깊이 들어가 휘장 안에 생활할 때<br/>할렐루야 할렐루야 영광의 빛 나를 덮네<br/>할렐루야 할렐루야 영광의 빛 나를 덮네<br/>',NULL,32100,2);
INSERT INTO stanza VALUES('K557','3','주의 영 안에 함께 돌아와 주 앞에 기도할 때에<br/>주의 영 안에 함께 돌아와 주 앞에 기도할 때에<br/>할렐루야 할렐루야 생명수 근원 만지네<br/>할렐루야 할렐루야 생명수 근원 만지네<br/>',NULL,32101,3);
INSERT INTO stanza VALUES('K558','1','오 주여 휘장 열리니 새롭고 산 길로<br/>담대히 주의 보혈로 주께 나갑니다<br/>',NULL,32102,1);
INSERT INTO stanza VALUES('K558','2','주님의 속죄피로써 지성소 들어가<br/>주 영의 인도 따라서 은혜 보좌 만져<br/>',NULL,32103,2);
INSERT INTO stanza VALUES('K558','3','자신을 의지하잖고 그 영 의지하여<br/>기도할 때에 주님이 향처럼 표현돼<br/>',NULL,32104,3);
INSERT INTO stanza VALUES('K558','4','은혜의 보좌로부터 은혜와 긍휼이<br/>생수처럼 흘러 넘쳐 때 따라 도우네<br/>',NULL,32105,4);
INSERT INTO stanza VALUES('K558','5','그 영을 따라 구하고 내 것 안 구하나<br/>내 모든 필요 아시고 주 우릴 돌보네<br/>',NULL,32106,5);
INSERT INTO stanza VALUES('K558','6','근심과 걱정 있어도 방해 받지 않고<br/>모든 것 주께 맡길 때 내 영 자유 얻네<br/>',NULL,32107,6);
INSERT INTO stanza VALUES('K558','7','고요히 주와 교통해 영 안에 골몰해<br/>주 영의 움직임따라 주께 기도하네<br/>',NULL,32108,7);
INSERT INTO stanza VALUES('K559','1','전능 예수 이름으로 보좌 앞에 엎드려<br/>흑암 원수 타파하고 불의 화살 막아내<br/>',NULL,32109,1);
INSERT INTO stanza VALUES('K559','chorus','전능한 주 이름 나에게 승리 주네<br/>전능한 주 이름- 사탄 죄 사망 밟네<br/>',NULL,32110,2);
INSERT INTO stanza VALUES('K559','2','전능하신 이름 불러 사탄 패배케 하네<br/>예수 예수 전능 예수 승리하는 큰 이름<br/>',NULL,32111,3);
INSERT INTO stanza VALUES('K559','3','그날 주가 나를 불러 천국으로 이끌 때<br/>전능 예수 이름 나를 보좌 앉게 하겠네<br/>',NULL,32112,4);
INSERT INTO stanza VALUES('K56','1','여자의 씨 되어 오신 은혜로운 주 예수<br/>동정녀를 통해 나셔 하나님 사람됐네<br/>사람 성 - 품 신분 갖고 옛 뱀 마 - 귀 깨뜨려<br/>하나님의 계획 위하여 십자가 - 로 이겼네<br/>',NULL,32113,1);
INSERT INTO stanza VALUES('K56','chorus','보라 신성 영광 그의 아름다움<br/>할렐루야 인성 안에 나타나셨네<br/>',NULL,32114,2);
INSERT INTO stanza VALUES('K56','2','육신 되어 오신 말씀 혈육의 몸 입었네<br/>사탄 마귀 폐하셨네 우리 대치물 됐네<br/>하나님 - 이 지은 이름 예수는 - 임마누엘<br/>보배로운 구 - 속자 돼 은혜 나 - 눠 주시네<br/>',NULL,32115,3);
INSERT INTO stanza VALUES('K56','3','마지막 아담이시요 둘째 사람이신 주<br/>새 창조의 머리로서 옛 창조를 이겼네<br/>이 땅 위 - 의 행하신 것 인자임 - 을 나타내<br/>하늘에서 하나님 앞에 여전히 인자이실세<br/>',NULL,32116,4);
INSERT INTO stanza VALUES('K56','4','하나님이 정한 그날 은혜의 주 오시리<br/>하나님의 영광 갖고 사람으로 나타나<br/>심판 보 - 좌 위에서도 인자로 - 서 심판해<br/>주의 인성 영 - 원토록 항상 소 - 유 하시네<br/>',NULL,32117,5);
INSERT INTO stanza VALUES('K560','1','이 산을 명하여- 바다로 가라하고<br/>의심치 않으면- 이루어지리라-<br/>주의 말씀 이뤄질 것 믿고 네 산-을 명하라<br/>',NULL,32118,1);
INSERT INTO stanza VALUES('K560','2','주님의 보혈로- 구속 권리 취해-<br/>하나님 오셔서- 효능 있게 한다-<br/>순종할 때 이뤄지니 주 안에 네- 산 명하라<br/>',NULL,32119,2);
INSERT INTO stanza VALUES('K560','3','주 이미 자아와- 죄악과 질병을-<br/>다 담당했으니- 넌 해방되었다-<br/>의지할 때 이뤄지니 주 안에 네- 산 명하라<br/>',NULL,32120,3);
INSERT INTO stanza VALUES('K560','4','큰 장벽 있어도- 믿음으로 구해-<br/>담대히 외치면- 승리 찬송하리-<br/>안심하고 믿기만 해 주 안에 네- 산 명하라<br/>',NULL,32121,4);
INSERT INTO stanza VALUES('K560','5','놋문과 철빗장- 다 부서졌으니-<br/>개가를 부르며- 다 들어가리라-<br/>모든 원수 무시하고 주 안에 네- 산 명하라<br/>',NULL,32122,5);
INSERT INTO stanza VALUES('K560','6','주 믿음 취하고- 불신 수치 벗어-<br/>기적의 지팡이- 핑계 다 쫓으리-<br/>주 말씀에 굳게 서서 주 안에 네- 산 명하라<br/>',NULL,32123,6);
INSERT INTO stanza VALUES('K561','1','믿음으로 기-도하라 은혜 보좌 앞-에서<br/>믿는 자-는 응-답 얻네“보-라 다 이루었다”<br/>',NULL,32124,1);
INSERT INTO stanza VALUES('K561','2','믿음으로 기 -도하라 주가 기도 듣-는다<br/>너의 기-대 이-상으로 주-가 구원 베푼다<br/>',NULL,32125,2);
INSERT INTO stanza VALUES('K561','3','믿음으로 기 -도하라 담대하게 굳-세게<br/>평강 기-쁨 소-망 갖고 두-손 들고 구하라<br/>',NULL,32126,3);
INSERT INTO stanza VALUES('K561','4','믿음으로 기 -도하라 주 네 기도 기-다려<br/>믿음으-로 나-아갈 때 주-님 기뻐하신다<br/>',NULL,32127,4);
INSERT INTO stanza VALUES('K562','1','믿음의 노-래해 밤 어둡더라도 찬-미-하면<br/>주 역-사해 너- 믿은 것들을- 다- 얻-게 하리라<br/>',NULL,32128,1);
INSERT INTO stanza VALUES('K562','2','믿음의 노-래해 또 다시 찬송해 주- 네- 노래-<br/>밤새-도록 퍼-지기 원한다- 퍼-지-기 원한다<br/>',NULL,32129,2);
INSERT INTO stanza VALUES('K562','3','믿음의 노-래해 저 원수 떨도록 네- 찬-미 원-수<br/>이-긴다 왜- 입 다물고서- 잠-잠-히 있느냐<br/>',NULL,32130,3);
INSERT INTO stanza VALUES('K562','4','믿음의 노-래해 곧 하늘 밝으리 끝-없-이 찬-미<br/>하-면서 주-님을 만나러- 우-리-는 가리라<br/>',NULL,32131,4);
INSERT INTO stanza VALUES('K563','1','한 영 안에 기도하면 내 뜻대로 안돼도-<br/>주의 기름 부음 있어 온전한 뜻 이루네<br/>',NULL,32132,1);
INSERT INTO stanza VALUES('K563','chorus','한 영 안에 기도하면 내 뜻대로 안돼도<br/>주의 기름 부음 있어 온전한 뜻 이루네<br/>',NULL,32133,2);
INSERT INTO stanza VALUES('K563','2','한 영 안에 기도하면 자신 부인하게 돼-<br/>모든 원하는 마음 뜻 성령 관리 받는다<br/>',NULL,32134,3);
INSERT INTO stanza VALUES('K563','3','한 영 안에 기도하면 하늘 보좌에 앉아-<br/>땅의 이익 발로 밟고 공중 마귀 물리쳐<br/>',NULL,32135,4);
INSERT INTO stanza VALUES('K563','4','한 영 안에 기도하면 성도 함께 간구해-<br/>주의 뜻 안에 들어가 화평하게 살게 돼<br/>',NULL,32136,5);
INSERT INTO stanza VALUES('K563','5','한 영 안에 기도하면 깨어 기도하게 돼-<br/>주의 나라 영광 위해 기도 이루어지네<br/>',NULL,32137,6);
INSERT INTO stanza VALUES('K563','6','한 영 안에 기도하면 화목하여 주 찾고-<br/>주의 몸의 영 안에서 영원 기도 합심돼<br/>',NULL,32138,7);
INSERT INTO stanza VALUES('K564','1','두뇌 의-지 하지 말-고 영 안에서 기-도해<br/>비결-대로 실행하-면 주의 임-재 얻으리<br/>',NULL,32139,1);
INSERT INTO stanza VALUES('K564','chorus','영 안에서 기도함- 은 주의- 지시한- 바니<br/>영 안에-서 하나님-과 접촉하-며 기도해<br/>',NULL,32140,2);
INSERT INTO stanza VALUES('K564','2','생각으-로 하지 말-고 영 안에서 기-도해<br/>주의 영-과 교통하-고 왕래하-며 주 맛봐<br/>',NULL,32141,3);
INSERT INTO stanza VALUES('K564','3','영 안에-서 기도하-여 주의 갈망 표-현해<br/>영 안에-서 기도할- 때 주로 인-해 불타리<br/>',NULL,32142,4);
INSERT INTO stanza VALUES('K564','4','영 안에-서 기도하-고 맘 속으로 탄-식해<br/>그 영 통-제 인도 통-해 하나님- 뜻 표현해<br/>',NULL,32143,5);
INSERT INTO stanza VALUES('K564','5','하나님-의 지성소-인 영 안에서 기-도해<br/>이 영 안-에 있어야-만 주와 연-합하겠네<br/>',NULL,32144,6);
INSERT INTO stanza VALUES('K564','6','영 안에-서 기도함-이 영원하고 유일한 길<br/>신성 모-든 충만하-심 이 비결-로 얻겠네<br/>',NULL,32145,7);
INSERT INTO stanza VALUES('K565','1','주의 은혜 보좌를 기도로써 만지니<br/>긍휼 은혜 입으며- 때따라 도움 받네<br/>',NULL,32146,1);
INSERT INTO stanza VALUES('K565','2','주의 보좌 만지며 주의 은혜 간구해<br/>간격 없이 주 얼굴- 맞대어 교통하네<br/>',NULL,32147,2);
INSERT INTO stanza VALUES('K565','3','주의 보좌 만지니 은혜 부요 알게 돼<br/>계속 은혜 취하며- 주께 찬양 드리네<br/>',NULL,32148,3);
INSERT INTO stanza VALUES('K565','4','주의 은혜 보좌를 기도로써 만지며<br/>주의 이름 안에서- 음부 마귀 처리해<br/>',NULL,32149,4);
INSERT INTO stanza VALUES('K565','5','산 믿음의 기도로 주의 보좌 만지네<br/>하늘 권위 사용해- 사망 권세 처리해<br/>',NULL,32150,5);
INSERT INTO stanza VALUES('K565','6','주의 보좌 만지며 음부 권세 흔들어<br/>보좌 왕권 사용해- 주와 함께 기도해<br/>',NULL,32151,6);
INSERT INTO stanza VALUES('K566','1','항상 기도하며 영을 훈련해<br/>주님 향해 많이- 기도했지만<br/>영을 사용한적 너무 적-었-네<br/>영의 역사 따-라- 기도 안 했네<br/>',NULL,32152,1);
INSERT INTO stanza VALUES('K566','2','영을 따라 기도 간구하겠네<br/>나의 기억 아닌 영-을 따라서<br/>생각 사용 않고 영을 좇-으-리<br/>찬미할 때에-도 영을 따르리<br/>',NULL,32153,2);
INSERT INTO stanza VALUES('K566','3','영을 훈련하여 기도하겠네<br/>밖의 필요 따른- 기도 안 하리<br/>영이 없는 기도하지 않-으-리<br/>깊은 곳을 울-릴- 기도 드리리<br/>',NULL,32154,3);
INSERT INTO stanza VALUES('K566','4','기도 없는 봉사 하지 않으리<br/>입술로만 하는- 기도 안 하리<br/>영이 없는 기도 하지 않-으-리<br/>영이 없는 교-통- 다시 안 하리<br/>',NULL,32155,4);
INSERT INTO stanza VALUES('K566','5','기도할 때 항상 영을 훈련해<br/>사람 많든 적든- 영을 훈련해<br/>때와 장소 사람 영향 안- 받-고<br/>어떤 집회서-나- 영을 해방해<br/>',NULL,32156,5);
INSERT INTO stanza VALUES('K566','6','영이 높아질 때 주가 길 얻네<br/>영이 강건할 때- 유능하게 돼<br/>영의 생수 흘러 성도 연-합-해<br/>흐름 안에 교-회- 건축된다네<br/>',NULL,32157,6);
INSERT INTO stanza VALUES('K567','1','기도로 주 표현해 자신 표현 말고서<br/>주가 자신 계시해 주 뜻 표현하도록<br/>',NULL,32158,1);
INSERT INTO stanza VALUES('K567','2','기도로 주 표현해 주의 원함 말해 내<br/>자신 생각 버리고 주 생각과 연합해<br/>',NULL,32159,2);
INSERT INTO stanza VALUES('K567','3','기도로 주 표현해 항상 주를 앙망해<br/>거울같이 바라봐 주의 영광 반사해<br/>',NULL,32160,3);
INSERT INTO stanza VALUES('K567','4','기도로 주 표현해 주가 간구하게 해<br/>내 영 안의 주님이 하늘 주께 기도해<br/>',NULL,32161,4);
INSERT INTO stanza VALUES('K567','5','기도로 주 표현해 자신 의지 안 하고<br/>주님만을 의지해 영원토록 간구해<br/>',NULL,32162,5);
INSERT INTO stanza VALUES('K568','1','기도 안에 교통하여 영 안에 주 뵙겠네<br/>주의 임재 안에 묻고 은밀히 기다리리<br/>',NULL,32163,1);
INSERT INTO stanza VALUES('K568','chorus','기도 안에 교통하여 영 안에 주 뵙겠네<br/>주의 임재 안에 묻고 은밀히 기다리리<br/>',NULL,32164,2);
INSERT INTO stanza VALUES('K568','2','기도 안에 교통할 때 주께 맘을 열겠네<br/>순결하고 진실하게 주 얼굴 앙망하리<br/>',NULL,32165,3);
INSERT INTO stanza VALUES('K568','3','기도 안에 교통하여 믿음으로 주 찾고<br/>주 영 만지기 배우며 겸손히 기다리리<br/>',NULL,32166,4);
INSERT INTO stanza VALUES('K568','4','기도 안에 교통하여 영의 실재 누리리<br/>항상 안의 느낌따라 영으로 기도하리<br/>',NULL,32167,5);
INSERT INTO stanza VALUES('K568','5','기도 안에 교통하여 주의 말씀 들으리<br/>주의 뜻을 새기면서 그의 갈망 이루리<br/>',NULL,32168,6);
INSERT INTO stanza VALUES('K568','6','기도 안에 교통하여 주님 안에 잠기리<br/>주의 영광 날 적실 때 주를 반사하겠네<br/>',NULL,32169,7);
INSERT INTO stanza VALUES('K569','1','기도로써 주 위해 길을 예비하겠네<br/>기도-로써 주 밀며 주에 의해 밀리리<br/>',NULL,32170,1);
INSERT INTO stanza VALUES('K569','2','주 뜻 목적 따라서 기도로써 수고해<br/>축복- 넘치기까지 주와 함께 연합해<br/>',NULL,32171,2);
INSERT INTO stanza VALUES('K569','3','자신 웅지 버리고 기도로써 수고해<br/>자기- 뜻을 거절해 주 뜻만을 관심해<br/>',NULL,32172,3);
INSERT INTO stanza VALUES('K569','4','기도로써 수고해 주가 시작하게 해<br/>주의- 모든 계획을 주가 집행하게 해<br/>',NULL,32173,4);
INSERT INTO stanza VALUES('K569','5','큰 바퀴 돌기까지 기도로써 수고해<br/>교회- 따라가도록 주와 함께 기도해<br/>',NULL,32174,5);
INSERT INTO stanza VALUES('K57','1','오 주님 인자 되 - 셔서 사람의 성품 지 - 니셨네<br/>우리와 같 - 은 혈육 입 - 고 처녀에게서 태어났네<br/>',NULL,32175,1);
INSERT INTO stanza VALUES('K57','2','자기 비어 종 형체 입고 고난의 세상 행 - 하셨네<br/>인생의 쓴 - 맛 모두 맛보고 고난 피하지 않 - 았네<br/>',NULL,32176,2);
INSERT INTO stanza VALUES('K57','3','말구유 아기로 - 났네 마른 땅 천한 동 - 네 살며<br/>목수의 일하며 인생길 가고 죄인처 - 럼 죽으셨네<br/>',NULL,32177,3);
INSERT INTO stanza VALUES('K57','4','죽음서 부활했 - 어도 여전히 인성 지 - 니신 주<br/>거룩한 모 - 습 입었으 - 나 주는 승천한 한 - 사람<br/>',NULL,32178,4);
INSERT INTO stanza VALUES('K57','5','보좌에 앉아 다스리나 영광 안에 주는 - 한 사람<br/>거룩한 빛 안에 사람으로서 하나님 - 맘 만족케 해<br/>',NULL,32179,5);
INSERT INTO stanza VALUES('K57','6','영광 가지고 다시 올 때 사람으로서 나 - 타나리<br/>인성을 가지신 만왕의 왕을 모든 사람이 주목하리<br/>',NULL,32180,6);
INSERT INTO stanza VALUES('K57','7','장래 새 하늘 새 땅에서 당신은 만유 중 - 심 되리<br/>거룩한 주 - 님 영원토 - 록 항상 인 - 성 가 - 지리<br/>',NULL,32181,7);
INSERT INTO stanza VALUES('K570','1','나 주를 위해 싸울 때 사탄도 일어나<br/>그 모든 권세 가지고 날 막으려 하네<br/>난 기도함으로 원수를 쫓아내<br/>내 주께 기도하면 좋아지므로<br/>',NULL,32182,1);
INSERT INTO stanza VALUES('K570','chorus','다만 주님께 기도하면 좋아져<br/>다만 주님께 말하면 다 좋아져<br/>나 시험받을 때 주님께 말하면<br/>내 주께 기도하면 모두 좋아져<br/>',NULL,32183,2);
INSERT INTO stanza VALUES('K570','2','나 흑암 계곡 지나고 폭풍 질병 만나<br/>시험이 끝이 없으니 앞길이 염려돼<br/>주 의지할 때에 곧 나는 승리해<br/>나 주께 말하므로 좋아지리라<br/>',NULL,32184,3);
INSERT INTO stanza VALUES('K570','3','내 친지 날 공격하고 다 나를 떠날 때<br/>나 약하고 또 외로웁고 기댈 데 없어<br/>오해를 받으며 버린 바 될 때에<br/>주께 상처 고하면 모두 좋아져<br/>',NULL,32185,4);
INSERT INTO stanza VALUES('K570','4','나 항상 주께 말하니 맘에 근심 없어<br/>늘 기뻐 노래하면서 주님을 기다려<br/>주 팔을 의지해 나 증명하리라<br/>내 주께 고하면은 좋아지는 것<br/>',NULL,32186,5);
INSERT INTO stanza VALUES('K571','1','죄짐 맡은 우리 구주 어찌 좋은 친군지<br/>걱정 근심 무거운 짐 우리 주께 맡기세<br/>주께 고함 없는 고로 복을 얻지 못하네<br/>사람들이 어찌하여 아뢸 줄을 모를까<br/>',NULL,32187,1);
INSERT INTO stanza VALUES('K571','2','시험 걱정 모든 괴롬 없는 사람 누군가<br/>부질없이 낙심 말고 기도 드려 아뢰세<br/>이런 진실하신 친구 찾아볼 수 있을까<br/>우리 약함 아시오니 어찌 아니 아뢸까<br/>',NULL,32188,2);
INSERT INTO stanza VALUES('K571','3','근심 걱정 무거운 짐 아니 진 자 누군가<br/>피난처는 우리 예수 주께 기도 드리세<br/>세상 친구 멸시하고 너를 조롱하여도<br/>예수 품에 안기어서 참된 위로 받겠네<br/>',NULL,32189,3);
INSERT INTO stanza VALUES('K572','1','내 모든 곤경 주님께 고해 나 홀로 근심안하리라<br/>오직 주 예수 날 위로하며 내 눈물 닦아주시리라<br/>',NULL,32190,1);
INSERT INTO stanza VALUES('K572','chorus','주께 고하리 주께 고하리 내 맘의 사정 토해 내리<br/>주께 고하리 주께 고하리 주 만이 내 맘 아시리라<br/>',NULL,32191,2);
INSERT INTO stanza VALUES('K572','2','내 모든 곤경 주님께 고해 나 홀로 환난 감당 못해<br/>내 모든 일을 주 감당하여 날 안식게 해 위로하네<br/>',NULL,32192,3);
INSERT INTO stanza VALUES('K572','3','내 모든 부족 주님께 고해 나 홀로 근심 못 제하니<br/>내 모든 필요 주만이 채워 나로 주 풍성 누리게 해<br/>',NULL,32193,4);
INSERT INTO stanza VALUES('K572','4','내 모든 약함 주님께 고해 나 홀로 정욕 못 이기니<br/>내 모든 묶임 주께서 풀어 날 해방하여 죄 벗게 해<br/>',NULL,32194,5);
INSERT INTO stanza VALUES('K572','5','내 모든 시험 주님께 고해 나 홀로 마귀 대적 못해<br/>동일한 시험 받으신 주님 흉악함에서 날 구하리<br/>',NULL,32195,6);
INSERT INTO stanza VALUES('K573','1','신성한 제사장 직분 늘 제물 주께 드리며<br/>늘 성소에-서 주 앞에 향 피워야 하네<br/>',NULL,32196,1);
INSERT INTO stanza VALUES('K573','chorus','늘 하나님 앞에 늘 향을 피우자<br/>늘 등을 켜-고 주님께 늘 노래부르자<br/>',NULL,32197,2);
INSERT INTO stanza VALUES('K573','2','성소엔 등대 빛 발해 자연의 빛은 없다네<br/>제사장 향- 피울 때에 등 켜야 하겠네<br/>',NULL,32198,3);
INSERT INTO stanza VALUES('K573','3','주 미덕 찬양하여서 사람이 감상하려면<br/>제사장 불 켜고 향 피고 노래해야 하네<br/>',NULL,32199,4);
INSERT INTO stanza VALUES('K573','4','향 피듯 기도함으로 주 부활 향기 드릴 때<br/>주 갈망따-라 감상해 주와 함께 누려<br/>',NULL,32200,5);
INSERT INTO stanza VALUES('K573','5','주 면전에서 등 켜고 성경을 읽어 빛 받아<br/>신성한 빛-의 찬란함 내 맘에 빛나리<br/>',NULL,32201,6);
INSERT INTO stanza VALUES('K573','6','제사장 노래하듯이 난 찬송으로 찬양해<br/>끝없는 주-의 은혜와 사랑을 찬양해<br/>',NULL,32202,7);
INSERT INTO stanza VALUES('K573','7','기도로 향기 드리고 말씀의 비췸 받으며<br/>주 은혜 찬-양할 때에 주의 영 흘러나<br/>',NULL,32203,8);
INSERT INTO stanza VALUES('K574','1','주 안에 안식할 수 있게 주 뜻 알리소서<br/>오 주여 나 지금 간구드립니다 기다리고 기다리며<br/>',NULL,32204,1);
INSERT INTO stanza VALUES('K574','2','나에게 구원 행하소서 간구하는 법을<br/>가르쳐 주소서 간구드립니다 기다리고 기다리며<br/>',NULL,32205,2);
INSERT INTO stanza VALUES('K574','3','내 안에 거처 정하소서 내게서 주 형상<br/>나타나기까지 연합하옵소서 기다리고 기다리니<br/>',NULL,32206,3);
INSERT INTO stanza VALUES('K574','4','주님의 길을 갈 수 있게 날 도와 주소서<br/>주 생명 나를 통해 흐르게 하소서 기다리고 기다리니<br/>',NULL,32207,4);
INSERT INTO stanza VALUES('K574','5','기도로 주를 표현하여 주 영광 얻도록<br/>역사해 주소서 간구드립니다 기다리고 기다리며<br/>',NULL,32208,5);
INSERT INTO stanza VALUES('K575','1','조용히 주를 기-다려라 주가 말한 후 주께 고하라<br/>주 시작해야 참 기도이니 넌 다만 그의 그릇이어라<br/>',NULL,32209,1);
INSERT INTO stanza VALUES('K575','2','조용히 주를 기-다려라 네 모든 생각 다 버리거라<br/>주님 자신을 네게 바르고 널 통해 기도하시게 하라<br/>',NULL,32210,2);
INSERT INTO stanza VALUES('K575','3','조용히 주를 기-다려라 네 갈망 네 길 취하지 마라<br/>이생의 근심 모두 버리고 오로지 주의 원함 취하라<br/>',NULL,32211,3);
INSERT INTO stanza VALUES('K575','4','조용히 주를 기-다려라 너의 뜻 영에 굴복케 하라<br/>영 인해 주 뜻 밝아질 때에 넌 순종하는 사역자 되리<br/>',NULL,32212,4);
INSERT INTO stanza VALUES('K575','5','조용히 주를 기-다려라 영이 널 통해 간구하도록<br/>너의 온 존재 영과 연합해 네 기도 주의 표현 되도록<br/>',NULL,32213,5);
INSERT INTO stanza VALUES('K575','6','조용히 주를 기-다려라 영 안에 주와 하나되도록<br/>영으로 모두 순종할 때에 각 부분 주를 닮게 되리라<br/>',NULL,32214,6);
INSERT INTO stanza VALUES('K575','7','조용히 주를 기-다려라 주 너를 통해 흘러 나가게<br/>매 순간 너의 말과 행실이 하나님 뜻을 이룰 때까지<br/>',NULL,32215,7);
INSERT INTO stanza VALUES('K576','1','주-여 당-신의 일 부흥시키소서<br/>주 - 권리-로 명-하시-고 감찰하옵소서<br/>',NULL,32216,1);
INSERT INTO stanza VALUES('K576','chorus','부-흥시키소서 우-리 기다리니<br/>주- 능력-의 손- 우리에게 보여 주옵소서<br/>',NULL,32217,2);
INSERT INTO stanza VALUES('K576','2','주-여 당-신의 일 부흥시키소서<br/>교 -회 감-동시-켜 모-두 통회케 하소서<br/>',NULL,32218,3);
INSERT INTO stanza VALUES('K576','3','주-여 당-신의 일 부흥시키소서<br/>주 - 보배-로움- 계시-해 주 사랑 불 붙게<br/>',NULL,32219,4);
INSERT INTO stanza VALUES('K576','4','주-여 당-신의 일 부흥시키소서<br/>주 - 말씀- 축복-하시-어 진리를 높이게<br/>',NULL,32220,5);
INSERT INTO stanza VALUES('K576','5','주-여 당-신의 일 부흥시키소서<br/>주- 승리- 증명-하시-어 원수를 밟도록<br/>',NULL,32221,6);
INSERT INTO stanza VALUES('K576','6','주-여 당-신의 일 부흥시키소서<br/>주- 권능- 내려- 주소-서 주 영광 위하여<br/>',NULL,32222,7);
INSERT INTO stanza VALUES('K577','1','나의 영을 높이 올려 주소서<br/>모든 장애 딛고 생명 공급해<br/>사람들의 상처 치료하도록<br/>',NULL,32223,1);
INSERT INTO stanza VALUES('K578','1','오 달콤한 기도 시간 분요함에-서 해방해<br/>주 보좌 앞에 나아와 모든 필요- 다 고할 때<br/>억압과 근심 있어도 내 영 늘 자유누리네<br/>이 달콤한 시간 인해 악한 자 올-무 피하네<br/>',NULL,32224,1);
INSERT INTO stanza VALUES('K578','2','오 달콤한 기도 시간 내 원함 날-개에 싣고<br/>주 보좌 향해 날아가 하나님께- 다 간구해<br/>신실하고 참되신 주 그 말씀 믿고 의지해<br/>이 달콤한 때 나의 짐 주 앞에 풀-어 놓겠네<br/>',NULL,32225,2);
INSERT INTO stanza VALUES('K578','3','오 달콤한 기도 시간 주 나의 생-각 위로해<br/>나 그날 산에 이르러 좋은 땅 바-라볼 때에<br/>장막 벗고 기다릴 때 믿음이 성취된 그때<br/>기도할 때 얻는 평강 큰 소리로- 간증하리<br/>',NULL,32226,3);
INSERT INTO stanza VALUES('K579','1','모든 성경은 하나님 호흡 성령 감동해- 쓰여졌다네<br/>하나님께서 사람 통하여 쓴 말씀 우린- 들여 마시네<br/>',NULL,32227,1);
INSERT INTO stanza VALUES('K579','2','주의 말씀은 신성한 광선 사람들 속에- 비춰주시네<br/>참된 상태와 자신의 필요 볼 수 있도록- 어둠 비추네<br/>',NULL,32228,2);
INSERT INTO stanza VALUES('K579','3','하나님 호흡 사람 생명 돼 신성한 성품- 얻게 하시네<br/>죽은 자 살려 거듭나게 해 혼 생명 변케-하여 주시네<br/>',NULL,32229,3);
INSERT INTO stanza VALUES('K579','4','하나님 호흡 사람 지혜 돼 신성한 지식- 가르치시네<br/>주 영원한 뜻 계시하시어 최종 목적에- 이르게 하네<br/>',NULL,32230,4);
INSERT INTO stanza VALUES('K579','5','하나님 호흡 사람 능력 돼 신성한 능력- 공급하시니<br/>피곤한 자가 힘을 얻으며 주 뜻 이룰 힘- 갖게 하시네<br/>',NULL,32231,5);
INSERT INTO stanza VALUES('K579','6','하나님 호흡 들여마실 때 하나님 축복- 누리게 되네<br/>영 사용하여 호흡함으로 내 필요 채워- 주 풍성 누려<br/>',NULL,32232,6);
INSERT INTO stanza VALUES('K58','1','사랑을 베푼 하나님 놀라운 그 지혜<br/>마지막 아담 오 - 셔서 날 구원하셨네<br/>',NULL,32233,1);
INSERT INTO stanza VALUES('K58','2','지혜로우신 하나님 놀라운 그 사랑<br/>혈육의 사람 가 - 지고 싸워 승리했네<br/>',NULL,32234,2);
INSERT INTO stanza VALUES('K58','3','말구유에 나신 아기 마른 땅에 자라<br/>목수로 수고하 - 시고 죄인처럼 죽어<br/>',NULL,32235,3);
INSERT INTO stanza VALUES('K58','4','오 아낌없는 그 사랑 사람으로 오셔<br/>사망의 권세 잡 - 은 자 사망으로 멸해<br/>',NULL,32236,4);
INSERT INTO stanza VALUES('K58','5','어두운 동산서 울고 십자가로 가신<br/>내 주님 십자가 - 의 길 가르쳐 주셨네<br/>',NULL,32237,5);
INSERT INTO stanza VALUES('K58','6','사람인 주가 하신 일 많고 기묘하니<br/>영원히 찬송 받 - 기에 합당하시도다<br/>',NULL,32238,6);
INSERT INTO stanza VALUES('K580','1','주님 자신 이미 계시 하셨네<br/>그의 성격 인격 모두 알렸네<br/>아담 자손 향해 그 뜻 계시해<br/>예표 예언 말씀으로 알렸네<br/>',NULL,32239,1);
INSERT INTO stanza VALUES('K580','2','하나님이 표명하신 목적은<br/>모든 일에 아들께서 으뜸 돼<br/>그의 안에 완전 영광 얻으며<br/>만유 중에 표현되는 것일세<br/>',NULL,32240,2);
INSERT INTO stanza VALUES('K580','3','하나님이 계시한 그리스도<br/>그는 참 하나님이요 참 사람<br/>하나님의 계획의 중심 둘레<br/>모든 것인 그가 만유 채우네<br/>',NULL,32241,3);
INSERT INTO stanza VALUES('K580','4','주 하나님 이미 말씀했으니<br/>하늘 다시 잠잠하지 않으리<br/>삼일 하나님이 사람과 합해<br/>그리스도 몸 돼 그 뜻 완성해<br/>',NULL,32242,4);
INSERT INTO stanza VALUES('K580','5','주 하나님 비밀 계시한 대로<br/>그리스도 그의 교회 하나 돼<br/>하나님의 충만인 주 머리 돼<br/>몸인 교회 그 모든 것 누리네<br/>',NULL,32243,5);
INSERT INTO stanza VALUES('K580','6','주 하나님 이미 말씀하시어<br/>모든 것이 밝히 계시되었네<br/>그의 창조 성육신 구속 구원<br/>모든 입이 찬미하기 원하네<br/>',NULL,32244,6);
INSERT INTO stanza VALUES('K581','1','하나님 말씀과 형상인 주 말씀의 내용이요 보화니<br/>성경을 통하여 나타나셔 하나님 풍성 보여 주시네<br/>',NULL,32245,1);
INSERT INTO stanza VALUES('K581','2','성경에 계시된 주 예수님 주 외엔 하나님 본 자 없네<br/>하나님 나타낸 주 예수님 성경을 통해 알 수 있다네<br/>',NULL,32246,2);
INSERT INTO stanza VALUES('K581','3','예수는 하나님 체현이요 성경은 주의 설명 또 충만<br/>주 통해 하나님 형상 알고 성경을 통해 주를 감상해<br/>',NULL,32247,3);
INSERT INTO stanza VALUES('K581','4','주님은 생명 영 또한 말씀 영으로 말씀 풍성해지니<br/>주의 영 통하여 말씀 만져 주 풍성 함께 나눌 수 있네<br/>',NULL,32248,4);
INSERT INTO stanza VALUES('K581','5','주 안에 교통해 하나님과 성경을 통해 누려 주님을<br/>기도로 성경을 읽을 때에 주 풍성 나의 필요 채우네<br/>',NULL,32249,5);
INSERT INTO stanza VALUES('K581','6','주 말씀 기도로 읽으면서 영 사용하는 길 가르치사<br/>주님과 말씀이 연합되어 내 생명 공급 되게 하소서<br/>',NULL,32250,6);
INSERT INTO stanza VALUES('K582','1','주는- 말씀 또 영-이니- 우린- 영으로 찬-양해<br/>주 알-게 하신 말-씀과 주 접-하게- 한 성-령을<br/>',NULL,32251,1);
INSERT INTO stanza VALUES('K582','2','나 주-와 연합될- 때에- 주 나-의 모든 것- 되네<br/>주 나-의 공급되-시는 말씀-과 영-이시-라네<br/>',NULL,32252,2);
INSERT INTO stanza VALUES('K582','3','주 만-일 말씀 아-니면-내 어-찌 주를 알-리요<br/>주 만-일 영이 아-니면 내 어-찌 접-촉하-리요<br/>',NULL,32253,3);
INSERT INTO stanza VALUES('K582','4','말씀-은 주를 계-시해- 나로- 주 알게 하-시네<br/>영은- 주님의 본-질로 주님-을 접-촉하-게 해<br/>',NULL,32254,4);
INSERT INTO stanza VALUES('K582','5','주는- 내 생명 빛- 또 길- 진리- 생수 영의- 양식<br/>말씀- 통해 전달-되어 주 영-에 의-해 체-험돼<br/>',NULL,32255,5);
INSERT INTO stanza VALUES('K582','6','주 말-씀 쓰여진- 성경- 내주-하는 성령- 인해<br/>내 영-에 들어오-실 때 곧 영-과 생-명이-실세<br/>',NULL,32256,6);
INSERT INTO stanza VALUES('K582','7','성경-을 이해할- 때에- 주 성-령 접촉하-겠네<br/>머리-만 사용 안-하고 주 영-으로- 기도-하리<br/>',NULL,32257,7);
INSERT INTO stanza VALUES('K582','8','주 말-씀 사랑하-면서- 주의- 영 경배드-리네<br/>주 말-씀 안에 즐-거워 주 영- 안에- 나 노-래해<br/>',NULL,32258,8);
INSERT INTO stanza VALUES('K583','1','내 주여 생명 떡 떼 주소서 해변서 무리에게 줌 같이<br/>말씀에 의지해 간구하니 내 주여 사신 말씀 주소서<br/>',NULL,32259,1);
INSERT INTO stanza VALUES('K583','2','내 주여 생명떡 떼 주소서 주 사랑 넘쳐 이름 높이며<br/>내 사상 벗어나 해방되어 주님만 즐겨하게 하소서<br/>',NULL,32260,2);
INSERT INTO stanza VALUES('K583','3','주 진리 열으사 깨우치며 그 소식 내게 알게 하소서<br/>주님과 하나돼 동행토록 날 주의 형상 같게 하소서<br/>',NULL,32261,3);
INSERT INTO stanza VALUES('K583','4','주 축복 주 진리 구합니다 갈릴리에서 축복하듯이<br/>묶인 것 다 벗겨 사슬 끊고 주 위해 생활하게 하소서<br/>',NULL,32262,4);
INSERT INTO stanza VALUES('K584','1','주를 더 신뢰하도록 내 욕망 더 떠나-도록<br/>주여 나에게 주-소서 한마디 말씀 주-소서<br/>',NULL,32263,1);
INSERT INTO stanza VALUES('K584','2','한마디 말씀 주실 때 내 약함 모두 드-러나<br/>내 자신 위해 한- 일들 허사인 것을 압-니다<br/>',NULL,32264,2);
INSERT INTO stanza VALUES('K584','3','한 말씀 내게 비췰 때 나 주와 친근해-지고<br/>주는 내 안에 계-셔서 내 생명 됨을 압-니다<br/>',NULL,32265,3);
INSERT INTO stanza VALUES('K584','4','유력한 말씀 올 때에 두려움 염려 드-러나<br/>주여 세미한 맑은 말씀 한마디 내게 줍- 소서<br/>',NULL,32266,4);
INSERT INTO stanza VALUES('K584','5','한마디 내게 준 말씀 최종의 승리 외치게 해<br/>영구한 반석의- 말씀 영원히 같이 사-소서<br/>',NULL,32267,5);
INSERT INTO stanza VALUES('K585','1','고요한 때 주여 말씀하소서<br/>내 마음 조용히 기다리오니<br/>',NULL,32268,1);
INSERT INTO stanza VALUES('K585','2','은혜로운 주님 말씀하소서<br/>주의 얼굴 뵙고 지시 듣도록<br/>',NULL,32269,2);
INSERT INTO stanza VALUES('K585','3','주 말씀은 영과 생명이시요<br/>하늘로부터 온 산 떡이실세<br/>',NULL,32270,3);
INSERT INTO stanza VALUES('K585','4','내 모든 것 주께 온전히 드려<br/>달게 항복하여 주께 속하리<br/>',NULL,32271,4);
INSERT INTO stanza VALUES('K585','5','말하소서 주여 침묵 마소서<br/>나의 영이 주를 앙망하오니<br/>',NULL,32272,5);
INSERT INTO stanza VALUES('K585','6','주 풍성한 말씀 날 충만케 해<br/>나에게서 갈망 이루옵소서<br/>',NULL,32273,6);
INSERT INTO stanza VALUES('K585','7','향기로 충만한 화원과 같이<br/>주가 감상할 때 만족게 하리<br/>',NULL,32274,7);
INSERT INTO stanza VALUES('K586','1','주여 내 영과 맘 목마르고 배고파<br/>주 앞에 나왔으니 당신 자신을 공급하소서<br/>주만이 내 능력 생명 공급<br/>',NULL,32275,1);
INSERT INTO stanza VALUES('K586','chorus','날 먹이소서 먹이소서 내 배고픔을 채워주고<br/>목마름을 해결해 주소서 기쁨 얻도록 먹이소서<br/>',NULL,32276,2);
INSERT INTO stanza VALUES('K586','2','주는 내 참 음식 생명 생수 배고픔<br/>목마름 해결하네 피곤함에서 날 소생시켜<br/>난 읽고 기도해 주 누리네<br/>',NULL,32277,3);
INSERT INTO stanza VALUES('K586','3','하나님 풍성이 감춰 있는 말씀인<br/>주 또한 영으로서 내 생명 되신 하나님이니<br/>음식인 말씀과 생수인 영<br/>',NULL,32278,4);
INSERT INTO stanza VALUES('K586','4','주는 내 음식이 되기 위해 하늘로<br/>부터 내려오셨고 생수 흐르도록 맞은바 돼<br/>내 공급 되시네 내게 흘러<br/>',NULL,32279,5);
INSERT INTO stanza VALUES('K586','5','주 이제 말씀과 생명 또 영 말씀으로<br/>나는 공급받네 영으로 내 안에 거하는 주<br/>당신을 영 안에 마신다네<br/>',NULL,32280,6);
INSERT INTO stanza VALUES('K586','6','이제 또 주님을 누리고자 당신의<br/>말씀에 나아가네 영 안에 주님을 흡수하여<br/>배고픔 목마름 면키 원해<br/>',NULL,32281,7);
INSERT INTO stanza VALUES('K586','7','성경 읽는 것은 주 먹는 것 내 기도는<br/>주를 마시는 것 읽고 기도하여 주를 먹고<br/>기도로 읽으며 주 마시네<br/>',NULL,32282,8);
INSERT INTO stanza VALUES('K586','8','주님 자신이 곧 나의 잔치 주 말씀<br/>내 갈증 해결하네 주의 영 내 속을 채워주네<br/>주님을 누림이 충만하네<br/>',NULL,32283,9);
INSERT INTO stanza VALUES('K587','1','은혜-의 보좌 앞에서 긍휼-과 은혜를- 얻네-<br/>때를- 따라 도움- 받고 내 맘-과 영 안-식 얻네<br/>',NULL,32284,1);
INSERT INTO stanza VALUES('K587','2','주 영-광 얼굴 빛 볼 때 주 얼-굴 내 맘 비- 취네-<br/>주 치-료하는 광-선이 내 약-함 결점- 소멸해<br/>',NULL,32285,2);
INSERT INTO stanza VALUES('K587','3','여기-서 주 날 비취사 내 참-된 상태 드-러내-<br/>주의- 피 효능 발-하여 내 모-든 더러-움 씻네<br/>',NULL,32286,3);
INSERT INTO stanza VALUES('K587','4','주 기-름 부음 날 발라 주 성-분 얻게 하-시네-<br/>이렇-게 주를 누-리며 주의- 뜻 만지-게 하네<br/>',NULL,32287,4);
INSERT INTO stanza VALUES('K587','5','성소-에 등불 켜듯이 주 앞-에 성경 읽-으리-<br/>주의- 영 기름과- 같이 말씀- 빛 밝혀-주소서<br/>',NULL,32288,5);
INSERT INTO stanza VALUES('K587','6','향 피-운 제사장같이 주님-께 기도하-겠네-<br/>영 안-에 주를 향-처럼 기도-와 함께- 바치리<br/>',NULL,32289,6);
INSERT INTO stanza VALUES('K587','7','주 말-씀은 등과 음식 날 비-추고 만족-게 해-<br/>여기-서 읽고 먹-을 때 계시-받고 양-식 얻어<br/>',NULL,32290,7);
INSERT INTO stanza VALUES('K587','8','주는- 향이며 생수니 난 열-납되고 살-아나-<br/>여기-서 읽고 마-실 때 향 올-려지고- 강 흘러<br/>',NULL,32291,8);
INSERT INTO stanza VALUES('K587','9','말씀- 읽고 기도할 때 주는- 내 안에 주-입돼-<br/>기도-하며 말씀-읽어 주 예-수 흘러- 나가네<br/>',NULL,32292,9);
INSERT INTO stanza VALUES('K587','10','이렇-게 주와 교통해 읽고- 기도해 연-합돼-<br/>주 흘-러 나가기-까지 주 날- 적시기- 원하네<br/>',NULL,32293,10);
INSERT INTO stanza VALUES('K588','1','주께 가까이 와 주 얻길 갈망해<br/>주 먹고 마셔 주님을 누리-기 원하네<br/>',NULL,32294,1);
INSERT INTO stanza VALUES('K588','2','주 얼굴 뵙기를 내 맘 사모하여<br/>주 접촉하며 영 안에 충족-함 얻겠네<br/>',NULL,32295,2);
INSERT INTO stanza VALUES('K588','3','주 영광 얼굴 빛 내 진정 사모해<br/>다른 곳 향하지 않고 늘 주-만 보겠네<br/>',NULL,32296,3);
INSERT INTO stanza VALUES('K588','4','이 교통 안에서 내 은혜 되신 주<br/>내 마음 즐겁게 하며 영 충-만케 하네<br/>',NULL,32297,4);
INSERT INTO stanza VALUES('K588','5','주님 자신으로 적셔질 때까지<br/>늘 말씀 읽고 기도해 주를- 추구하리<br/>',NULL,32298,5);
INSERT INTO stanza VALUES('K589','1','떡만으로-는 못-살고 하나님 말-씀으로 살아<br/>주 말씀 생명 떡 삼아 언제나 먹고 살-겠네<br/>',NULL,32299,1);
INSERT INTO stanza VALUES('K589','2','우리는 몸-만 아-니라 혼과 영 가-진 사람이니<br/>가장 깊은 영 안에서 하나님 공급받-겠네<br/>',NULL,32300,2);
INSERT INTO stanza VALUES('K589','3','우리의 육-신 안-에도 음식의 영-양 필요하듯<br/>영에는 생명의 양식 하나님 말씀 필-요해<br/>',NULL,32301,3);
INSERT INTO stanza VALUES('K589','4','영이신 주-님 자-신을 말씀으로- 나타-내니<br/>나는 내 영을 사용해 말씀 통해 주 영- 받아<br/>',NULL,32302,4);
INSERT INTO stanza VALUES('K589','5','주님의 말-씀 받-을 때 글자만 읽-지 않-겠네<br/>생각으로 이해하며 영으로 말씀 흡-수해<br/>',NULL,32303,5);
INSERT INTO stanza VALUES('K589','6','영으로 기-도하-면서 주 말씀 받-아들-일 때<br/>주께서 나의 온 존재 공급하시고 적-시네<br/>',NULL,32304,6);
INSERT INTO stanza VALUES('K589','7','생각에 말-씀 머-물 때 무거운 지-식 되-지만<br/>영 안에 받아들일 때 영과 생명과 평-안돼<br/>',NULL,32305,7);
INSERT INTO stanza VALUES('K589','8','진정 내 영-을 사-용해 주 말씀 받-고 접-할 때<br/>말씀의 양육 얻으며 주님 자신을 만-지네<br/>',NULL,32306,8);
INSERT INTO stanza VALUES('K589','9','오 주여 말-씀 읽-을 때 영 사용하-게 하-소서<br/>내 영이 양육얻으며 생명의 공급 얻-도록<br/>',NULL,32307,9);
INSERT INTO stanza VALUES('K59','1','영광스 - 런 하나님 존엄과 - 은혜가<br/>주 예수 - 얼굴에 깊이 새겨져 있도 - 다<br/>나 하나님의 - 빛난 그 형상 볼 때에<br/>놀람과 - 기쁨 - 속에 흠모함 넘치네<br/>',NULL,32308,1);
INSERT INTO stanza VALUES('K59','2','완전한 - 인성 갖고 주 신성 - 나타내<br/>하나님 - 사랑 - 갖고 사람 동정 가 - 져<br/>출생과 죽음 - 부활 승천을 통하여<br/>자신을 - 낮추 - 셨네 오 하나님 사람<br/>',NULL,32309,2);
INSERT INTO stanza VALUES('K59','3','더러움 - 없는 광채 빛 발하 - 는 얼굴<br/>측량 못할 역사와 은혜 날 변케 하셨 - 네<br/>나 그날 당신의 형상 온전히 닮아서<br/>인자 예수 얼굴 - 에서 하나님 보겠네<br/>',NULL,32310,3);
INSERT INTO stanza VALUES('K590','1','주는- 말씀 또 영-이요- 그 말-씀 안의 영-이니<br/>주께-서 하신 말-씀은 영이-요 생-명이-라네<br/>',NULL,32311,1);
INSERT INTO stanza VALUES('K590','2','밖에-는 성경 주-셨고- 안에-는 성령 주-셨네<br/>이 둘-은 주의 큰- 선물 주님-의 공-급 얻-게 해<br/>',NULL,32312,2);
INSERT INTO stanza VALUES('K590','3','성령-은 성경 실-제요- 성경-은 성령 표-명해<br/>하나-의 양면으-로써 영원-히 나-눌 수- 없네<br/>',NULL,32313,3);
INSERT INTO stanza VALUES('K590','4','성령-의 비춤 거-쳐서- 성경-은 내 영 생-명 돼<br/>성령-과 나뉜 성-경은 곧 공-허한- 것 된-다네<br/>',NULL,32314,4);
INSERT INTO stanza VALUES('K590','5','영으-로 성경 접-하면- 생명-인 영으로- 변해<br/>내게-서 영이 표-현돼 곧 공-급하-는 말-씀 돼<br/>',NULL,32315,5);
INSERT INTO stanza VALUES('K590','6','우리-의 깊은 영-으로- 하나-님 성경 받-아야<br/>내게-서 영이 표-현돼 다른- 사람-을 공-급해<br/>',NULL,32316,6);
INSERT INTO stanza VALUES('K590','7','주의- 말씀 내 안-에서- 내 생-명 영이 되-셔서<br/>주 말-씀 안에 주-의 영 내 참-된 표-현 되-소서<br/>',NULL,32317,7);
INSERT INTO stanza VALUES('K591','1','주의 말씀 사람에게 생명 공급하시네<br/>다만 지식 사상 아닌 주님 자신 얻게 해<br/>뜻만 계시하지 않고 생명의 주 가져와<br/>가르침만 주지 않고 그리스도 공급해<br/>',NULL,32318,1);
INSERT INTO stanza VALUES('K591','2','의문 문자 주의하면 지식만을 얻지만<br/>영의 기도 안에서는 생명 얻고 실재 돼<br/>모든 의문 각종 지식 사망만을 주지만<br/>영 안에서 받은 말씀 내게 생명 공급해<br/>',NULL,32319,2);
INSERT INTO stanza VALUES('K591','3','주 밖에서 읽을 때엔 한낱 공허한 지식<br/>영 안에서 접촉하면 생명의 음식 되네<br/>문자 읽고 주 떠나면 생각만 무성하나<br/>기도로써 접촉하면 풍성한 생명 얻네<br/>',NULL,32320,3);
INSERT INTO stanza VALUES('K591','4','모든 성경 지식들이 생명 되어야 하리<br/>모든 이해 영 안에서 다시 조성되야 해<br/>성경 아는 모든 것에 생명 흘러야 하리<br/>모든 인식 영 안으로 받아들여야 하리<br/>',NULL,32321,4);
INSERT INTO stanza VALUES('K591','5','지식 위해 성경 보면 하와 행위 같으니<br/>악한 사탄 지식 통해 여자 유혹하였네<br/>말씀 생명 삼는다면 생명나무 먹으리<br/>영 안에서 주의 말씀 양식으로 받으라<br/>',NULL,32322,5);
INSERT INTO stanza VALUES('K592','1','그리스도의 풍성을 우리가 함-께- 누릴 때<br/>우리는 그의 충-만-돼 다 그를 표현한다네<br/>',NULL,32323,1);
INSERT INTO stanza VALUES('K592','2','그리스도의 풍성이 우리의 누-림-될 때에<br/>우리는 그의 충-만-돼 주 교회로서 나타나<br/>',NULL,32324,2);
INSERT INTO stanza VALUES('K592','3','가나안 땅의 소산은 다 주의 풍-성- 예표해<br/>이 소산 통한 성-전-은 주 교회 상징한다네<br/>',NULL,32325,3);
INSERT INTO stanza VALUES('K592','4','아담의 충만인 하와 아담에게-서- 나왔네<br/>주님의 충만인- 교-회 주님에게서 나왔네<br/>',NULL,32326,4);
INSERT INTO stanza VALUES('K592','5','그리스도의 풍성을 우리 안에-서- 누릴 때<br/>그리스도로 충-만-돼 주님의 표현 된다네<br/>',NULL,32327,5);
INSERT INTO stanza VALUES('K593','1','보이지 않는 하-나-님 아무도 본 자 없-으-나<br/>그의 비밀인- 주 예-수 온-전히 나타내-셨-네<br/>',NULL,32328,1);
INSERT INTO stanza VALUES('K593','2','하나님의 산 말 -씀-과 유일한 설명인- 주 - 님<br/>하나님 체현-이신- 주 하-나님 본성 나-타-내<br/>',NULL,32329,2);
INSERT INTO stanza VALUES('K593','3','하나님 본체의- 형-상 하나님 영광 광-채-인<br/>주 안에 하나-님 거-해 주- 통해 발휘되-시-네<br/>',NULL,32330,3);
INSERT INTO stanza VALUES('K593','4','오늘은 주님 감 -춰-져 아무도 볼 수 없-으-나<br/>그의 비밀인- 교회-가 각-처에서 주 나-타-내<br/>',NULL,32331,4);
INSERT INTO stanza VALUES('K593','5','주님의 충만 표 -현-인 교회의 생명 주- 예-수<br/>교회는 주의- 복사-판 교-회 통해 주 나-타-나<br/>',NULL,32332,5);
INSERT INTO stanza VALUES('K593','6','주 형상 가진 교 -회-는 주님의 확장 증-가-니<br/>주님의 몸인- 교회-로 주- 어떠하심 나-타-나<br/>',NULL,32333,6);
INSERT INTO stanza VALUES('K593','7','아버지 아들 성 -령-이 교회와 하나되-었-네<br/>삼일 하나님- 성품-이 이- 교회 안에 충-만-해<br/>',NULL,32334,7);
INSERT INTO stanza VALUES('K594','1','사-람 몸이 사람 생명 표-현하듯이<br/>주-의 몸인 교-회 또한 주-를 나타내<br/>',NULL,32335,1);
INSERT INTO stanza VALUES('K594','2','저- 하와가 아담에서 나-온 것처럼<br/>주-에게서 나-온 교회 주- 확장일세<br/>',NULL,32336,2);
INSERT INTO stanza VALUES('K594','3','한- 알의 밀 죽음으로 열-매 맺었네<br/>많- 은 밀이 가-루 되어 한- 몸 이뤘네<br/>',NULL,32337,3);
INSERT INTO stanza VALUES('K594','4','그-리스도 부활하여 번-식되었네<br/>믿-는 이들 한-몸 이뤄 주-를 나타내<br/>',NULL,32338,4);
INSERT INTO stanza VALUES('K594','5','포-도나무 가지들은 나-무의 확장<br/>나-무 안에 거-하므로 열-매 맺겠네<br/>',NULL,32339,5);
INSERT INTO stanza VALUES('K594','6','그-리스도 지체들도 그-의 확대니<br/>주- 예수와 하-나 되어 주- 안에 거해<br/>',NULL,32340,6);
INSERT INTO stanza VALUES('K594','7','번-식 확장 발전 확산 자-람 나타남<br/>그-의 복사 연-장 부요 확-대와 충만<br/>',NULL,32341,7);
INSERT INTO stanza VALUES('K594','8','이-는 바로 교회이니 이-들 통하여<br/>하-나님이 영-원토록 영-화롭게 돼<br/>',NULL,32342,8);
INSERT INTO stanza VALUES('K594','9','하-나님의 큰 비밀인 주-와 교회는<br/>신-성 인성 연-합하여 하-나됨일세<br/>',NULL,32343,9);
INSERT INTO stanza VALUES('K595','1','교회는 주님의 그릇 주 담-고 표-현 한-다네<br/>혈육의 몸이 사람의 생명-을 표현 하듯이<br/>',NULL,32344,1);
INSERT INTO stanza VALUES('K595','2','성전 안의 언약궤가 그릇-이요- 안식-처듯<br/>교회는 주의 거처니 그 안-에 주가 거하네<br/>',NULL,32345,2);
INSERT INTO stanza VALUES('K595','3','주님은 하나님 비밀 하나-님 설-명하-시네<br/>교회 또한 주의 비밀 주 밝-혀 나타낸다네<br/>',NULL,32346,3);
INSERT INTO stanza VALUES('K595','4','교회의 모든 지체들 원래-는 흙-이었-으나<br/>거듭나 변화됨으로 투명-한 보석 된다네<br/>',NULL,32347,4);
INSERT INTO stanza VALUES('K595','5','변화를 통해 건축돼 주의- 투명-한 그-릇 돼<br/>주의 풍성 다 담아서 사람-들에게 나타내<br/>',NULL,32348,5);
INSERT INTO stanza VALUES('K595','6','하나님 협력과 동역 변화-의 역-사 완-성해<br/>단체의 그릇인 교회 하나-님 거처 된다네<br/>',NULL,32349,6);
INSERT INTO stanza VALUES('K595','7','투명하게 빛 발하는 오 귀-하고- 귀한- 교회<br/>주님의 충만 담아서 주님-의 영광 나타내<br/>',NULL,32350,7);
INSERT INTO stanza VALUES('K595','8','삼일 하나님 영원히 교회-통해- 표현-되네<br/>만유 가운데 나타내 아버-지 아들 성령을<br/>',NULL,32351,8);
INSERT INTO stanza VALUES('K596','1','교회는 정금- 등대-요 주는 등 하나님은 빛<br/>주님은 빛을- 비추-고 교회는 그 빛- 붙드네<br/>',NULL,32352,1);
INSERT INTO stanza VALUES('K596','2','생명의 빛인- 하나-님 등으로 그 빛 발하네<br/>하나님 영광-에 맞-게 등대는 정금-으로 돼<br/>',NULL,32353,2);
INSERT INTO stanza VALUES('K596','3','이 흑암 세대- 가운-데 거룩한 생명 빛 비춰<br/>사람들 맘에- 비취-어 주 간증 선포-된다네<br/>',NULL,32354,3);
INSERT INTO stanza VALUES('K596','4','이 순결한 간-증 위-해 처음 사랑 잃지 않고<br/>이기는 자의- 분깃-인 생명나무를- 누리네<br/>',NULL,32355,4);
INSERT INTO stanza VALUES('K596','5','고난과 핍박- 견뎌-야 생명의 면류관 얻고<br/>영적인 음란- 이겨-야 감추인 만나- 맛보리<br/>',NULL,32356,5);
INSERT INTO stanza VALUES('K596','6','이세벨 행위- 버려-야 다스리는 권세 얻고<br/>사망의 더럽-힘 이-겨 의로운 흰 옷- 입게 돼<br/>',NULL,32357,6);
INSERT INTO stanza VALUES('K596','7','주님의 말씀- 간직-해 주 이름 거절치 않고<br/>미지근함과- 교만-을 이겨야 잔치- 누리리<br/>',NULL,32358,7);
INSERT INTO stanza VALUES('K596','8','이렇게 순결-한 교-회 정금 등대가 되어서<br/>주님의 간증-으로-서 주 충만하고- 나타내<br/>',NULL,32359,8);
INSERT INTO stanza VALUES('K596','9','이 땅의 모든- 교회-들 이 시대 등대들 되고<br/>장래의 거룩-한 성-은 영원한 등대- 되리라<br/>',NULL,32360,9);
INSERT INTO stanza VALUES('K596','10','거룩한 성은- 주님-의 등대의 최종 표현 돼<br/>등이신 주를- 붙들-어 하나님 빛을- 비추네<br/>',NULL,32361,10);
INSERT INTO stanza VALUES('K597','1','창세전에 하나님은 예정하고 택했네-<br/>그의 교회 아들 안에 아들 명분 얻도록<br/>구속 받아 기업 되고 성령의 인침 받아<br/>보증 얻은 그의 교회 그분 자신 누리네<br/>',NULL,32362,1);
INSERT INTO stanza VALUES('K597','2','승천하신 그리스도 보좌 우편에 앉아-<br/>모든 권세 초월하고 만유 머리 되셨네<br/>만유 충만케 한 주가 충만한 몸 된 교회<br/>주의 확장 연장으로 주 완전함 표현해<br/>',NULL,32363,2);
INSERT INTO stanza VALUES('K597','3','본래 죄로 죽은 우리 세상 풍습 좇으며-<br/>악의 영을 순종하던 진노의 자녀였네<br/>이제 주와 부활하여 함께 하늘에 앉아<br/>주 안에서 하나님의 영광스런 걸작 돼<br/>',NULL,32364,3);
INSERT INTO stanza VALUES('K597','4','사도와 선지자 터에 주는 모퉁이돌로-<br/>유대인과 이방인이 한 몸으로 건축돼<br/>주 안에서 건축되어 하나님의 거처돼<br/>영 안에서 연합하여 평강 기쁨 누리네<br/>',NULL,32365,4);
INSERT INTO stanza VALUES('K597','5','하나님이 영원 안에 계획하신 교회는-<br/>그의 지혜 나타내는 그리스도의 거처<br/>모든 성도 주를 알아 주 무한함 감상해<br/>뛰어난 그 사랑 알며 신성 충만케 되네<br/>',NULL,32366,5);
INSERT INTO stanza VALUES('K597','6','한 몸 한 영 한 소망과 한 주 한 믿음 한 침례<br/>모든 사람 위에 계신 아버지도 하날세<br/>주를 알아 성숙하리 충만한 신장까지<br/>다시 미혹되지 않고 요동하지 않으리<br/>',NULL,32367,6);
INSERT INTO stanza VALUES('K597','7','그의 몸의 건축 위해 주가 주신 은사로-<br/>성도들을 온전케 해 사역의 일 하게 해<br/>사랑 안에 건축되어 옛 사람을 벗고서<br/>새 사람을 입은 교회 주의 형상 충만해<br/>',NULL,32368,7);
INSERT INTO stanza VALUES('K597','8','주가 교회 사랑하사 자기 생명 버리고-<br/>영광스런 배필 삼아 거룩하게 하시네<br/>몸 된 교회 사랑하여 양육하고 보호해<br/>주와 교회 한 몸이니 크신 비밀이로다<br/>',NULL,32369,8);
INSERT INTO stanza VALUES('K597','9','교회는 몸 거처 배필 새 사람 또 전사니-<br/>하나님을 위해 싸워 주의 원수 진멸해<br/>주의 전신갑주 입고 주의 능력 의지해<br/>무시로 늘 기도하며 영의 싸움 이기네<br/>',NULL,32370,9);
INSERT INTO stanza VALUES('K598','1','부르심받아나온교회는주의몸주의거처하나님과사람의연합<br/>창세전에선택돼갈보리피로써구속된교회본질하늘에속했네<br/>',NULL,32371,1);
INSERT INTO stanza VALUES('K598','2','부활한주로부터태어난새창조성령의침례받고또성별함받은<br/>그의생명내용된주는또머리니주님과함께올라대적을정복해<br/>',NULL,32372,2);
INSERT INTO stanza VALUES('K598','3','이교회기초오직주그리스도니교회의모든것은거룩해정결해<br/>오죽음거친모든지체들건축돼부활안에서금과은과보석으로<br/>',NULL,32373,3);
INSERT INTO stanza VALUES('K598','4','한하나님한주님한성령한믿음한소망한침례와한몸모두하나<br/>삼이일하나님이교회에충만해믿음으로지체들다하나되었네<br/>',NULL,32374,4);
INSERT INTO stanza VALUES('K598','5','온땅의모든족속모든민족들이이몸의지체됐네다하나되었네<br/>종이나자유자나헬라인유대인다끝나고주안에한새사람됐네<br/>',NULL,32375,5);
INSERT INTO stanza VALUES('K598','6','이우주안의한몸각지에나타나교회의입장오직지방입장일세<br/>행정은독립되어각각주께묻고교통은우주안에하나를누리네<br/>',NULL,32376,6);
INSERT INTO stanza VALUES('K598','7','온교회하나이룬새예루살렘에그리스도는빛의등이되신다네<br/>등안의빛은바로하나님이시니이성은영광스런그형상나타내<br/>',NULL,32377,7);
INSERT INTO stanza VALUES('K599','1','교회의 씨는 그리스도로 사람의 맘에 생명 뿌려져<br/>자라나 고운 가루 산출해 하나님 사람 만족게- 하네<br/>',NULL,32378,1);
INSERT INTO stanza VALUES('K599','2','마귀는 와서 성도 가운데 거짓 믿는이 뿌려 미혹해<br/>밀 방해하는 가라지처럼 성도의 성장 누림 방-해해<br/>',NULL,32379,2);
INSERT INTO stanza VALUES('K599','3','교회는 연한 채소와 같이 겨자씨 주님에게서 자라<br/>자그마하게 자라나야만 주린 자 공급하는 음-식 돼<br/>',NULL,32380,3);
INSERT INTO stanza VALUES('K599','4','마귀가 와서 변질시키니 작은 식물이 큰 나무 되어<br/>공중의 새들 깃들이는 곳 악한 자 처소 제공하-였네<br/>',NULL,32381,4);
INSERT INTO stanza VALUES('K599','5','마귀는 교회 변질시키어 이방의 악한 풍습 가져와<br/>고운 가루에 누룩 섞어서 하나님 목적 파괴 꾀-하네<br/>',NULL,32382,5);
INSERT INTO stanza VALUES('K599','6','생명 된 주가 변화시키네 성도들 보석 진주 되도록<br/>교회의 건축 재료 되어서 왕국의 영광스런 실-제돼<br/>',NULL,32383,6);
INSERT INTO stanza VALUES('K599','7','주 의지하여 교회 자라나 주님의 형상으로 화하네<br/>감추인 귀한 진주와 같이 하나님 왕국 가져온-다네<br/>',NULL,32384,7);
INSERT INTO stanza VALUES('K599','8','가라지에서 우릴 분별해 큰 나무에서 우릴 해방해<br/>하나님 사람 음식 되도록 모든 누룩을 제해 주-소서<br/>',NULL,32385,8);
INSERT INTO stanza VALUES('K599','9','변화돼 한 몸 건축하도록 주 생명 안에 자라게 하사<br/>주 표현하는 교회 이루어 주 왕국 실재 되게 하-소서<br/>',NULL,32386,9);
INSERT INTO stanza VALUES('K6','1','하나님은 사랑 또 빛 아들 생명 되셨네<br/>사랑과 빛 표현되어 우린 생명 얻었네<br/>',NULL,32387,1);
INSERT INTO stanza VALUES('K6','chorus','당신은 사랑 빛 아들 생명되셨네<br/>사랑과 빛 표현되어 우린 생명 얻었네<br/>',NULL,32388,2);
INSERT INTO stanza VALUES('K6','2','주 어떠함 나타내는 사랑은 안에 있네<br/>주의 역사 나타내는 빛은 밖에 있다네<br/>',NULL,32389,3);
INSERT INTO stanza VALUES('K6','3','은혜로 나타난 사랑 진리로 비취는 빛<br/>사랑으로 주 누리고 빛으로 주를 아네<br/>',NULL,32390,4);
INSERT INTO stanza VALUES('K6','4','사랑으로 죽으신 주 나로 생명 얻게 해<br/>빛으로 깨닫게 하고 보혈 적용케 하네<br/>',NULL,32391,5);
INSERT INTO stanza VALUES('K6','5','생명 얻게 하는 사랑 주 교통 누리게 해<br/>정결케 하는 빛 나를 교통 안에 살게 해<br/>',NULL,32392,6);
INSERT INTO stanza VALUES('K6','6','빛의 비췸 피의 씻음 기름 부음 알게 해<br/>주의 성분 주의 생명 내 안에 더 흐르네<br/>',NULL,32393,7);
INSERT INTO stanza VALUES('K6','7','주의 사랑 우리들을 자녀 되게 하셨네<br/>주의 형상 이루도록 빛은 어둠 제하네<br/>',NULL,32394,8);
INSERT INTO stanza VALUES('K6','chorus','이 은혜 이 진리 나타난 사랑 빛<br/>그침없이 찬양하세 주 알게 한 사랑 빛<br/>',NULL,32395,9);
INSERT INTO stanza VALUES('K60','1','사랑스런 이름 예수 내 주<br/>모든 이름 위에 뛰어난 이름<br/>내 모든 것 되신 당신만 있으면<br/>부족함 없다네 예 - 수 내 주<br/>',NULL,32396,1);
INSERT INTO stanza VALUES('K60','2','인자가 되신 분 예수 내 주<br/>나 위해 죽으신 예 - 수 내 주<br/>당신의 사랑은 뛰어난 큰 사랑<br/>구원을 이루신 예 - 수 내 주<br/>',NULL,32397,2);
INSERT INTO stanza VALUES('K60','3','당신 인해 사네 예수 - 내 주<br/>오직 당신 입고 승 - 리하네<br/>당신이 있기에 걱정 고난 마귀<br/>두려울 것 없네 예수 - 내 주<br/>',NULL,32398,3);
INSERT INTO stanza VALUES('K60','4','곧 다시 오시리 예수 내 주<br/>난 기뻐 춤추리 예 - 수 내 주<br/>그날에 당신과 똑같이 되리라<br/>영원히 함께 살 예 - 수 내 주<br/>',NULL,32399,4);
INSERT INTO stanza VALUES('K600','1','성도가 함께 거할 때 교회의 하나- 누려<br/>성도들 안에 성령이 이 하나 두셨-다네<br/>성령에게서 왔으니 성령의 하나-일세<br/>온 성도의 같은 믿음 하나의 뿌리-일세<br/>',NULL,32400,1);
INSERT INTO stanza VALUES('K600','2','귀하고 동일한 믿음 온 성도 함께- 가져<br/>주님과 구속 역사가 곧 구성 성분-일세<br/>그 안에 모든 성도가 온전히 하나-일세<br/>다 함께 얻은 믿음에 온교회 존재-하네<br/>',NULL,32401,2);
INSERT INTO stanza VALUES('K600','3','주 그리스도 기업인 하나인 우주- 교회<br/>각 지방에서 하나로 주님을 표현-하네<br/>한 하나님과 한 주님 한 성령 한 믿-음과<br/>한 침례 한 몸 한 소망 모두가 하나-일세<br/>',NULL,32402,3);
INSERT INTO stanza VALUES('K600','4','이 하나는 곧 교회가 서야 할 입장-이니<br/>온 성도들의 합일을 이루는 입장-일세<br/>교회가 참된 하나를 실지로 실행-하네<br/>각지의 교회 출현은 다 입장 위에- 있네<br/>',NULL,32403,4);
INSERT INTO stanza VALUES('K600','5','성령의 참된 하나를 힘써서 지키-면서<br/>한 입장 위에 한 몸을 체험케 하옵-소서<br/>주 마음 속의 갈망이 이로써 실현-되고<br/>주 영원한 뜻 온전히 이루게 하옵-소서<br/>',NULL,32404,5);
INSERT INTO stanza VALUES('K601','1','하나님의 아들 그리스도와 구속의 역사가 구원의 신앙<br/>주 예수의 인격 역사 믿으며 다른 교리 강조하지 않겠네<br/>',NULL,32405,1);
INSERT INTO stanza VALUES('K601','2','기타 다른 교리 강조할 때에 하나 손상하는 교훈 풍조 돼<br/>주로부터 성도 떠나가게 해 몸의 건축 파괴하게 된다네<br/>',NULL,32406,2);
INSERT INTO stanza VALUES('K601','3','각종 교리보다 이 신앙 지켜 하나 실행하며 하나 보존해<br/>주와 그 영 안에 하나인 우리 다른 것은 포기해도 된다네<br/>',NULL,32407,3);
INSERT INTO stanza VALUES('K601','4','진리이신 주만 함께 붙들 때 분열에서부터 구출되겠네<br/>주님에게까지 자라나도록 주 충만해 몸 된 교회 건축해<br/>',NULL,32408,4);
INSERT INTO stanza VALUES('K601','5','신앙의 하나를 굳게 잡을 때 모든 교훈 풍조 멀리 떠나네<br/>영 안의 실제인 주를 붙잡아 하나 안에 몸 된 교회 자라네<br/>',NULL,32409,5);
INSERT INTO stanza VALUES('K602','1','주는 모퉁이 머릿돌 유대 건축자들 버려<br/>하나님은 귀히 보사 다시 살려 세웠네<br/>우리들은 주로 인해 구원받고 건축돼-<br/>유대인과 이방인이 한 새 사람 되었네<br/>',NULL,32410,1);
INSERT INTO stanza VALUES('K602','2','주는 또 신령한 반석 목마른 자 마시게 해<br/>모든 사람 의탁케 해 성전 건축 이루네<br/>주는 시온의 기초석 시험 거쳐 확고해-<br/>교회 의지하는 반석 유일한 기초일세<br/>',NULL,32411,2);
INSERT INTO stanza VALUES('K602','3','주님의 건축된 교회 음부 권세가 못 이겨<br/>비바람이 몰아쳐도 더욱 굳게 서겠네<br/>악령 사탄 쫓아내고 천국 가져오도록-<br/>주의 묶고 푸는 권세 교회에게 주셨네<br/>',NULL,32412,3);
INSERT INTO stanza VALUES('K602','4','하나님의 택함 받은 생명의 산 돌인 주-<br/>우리 또한 주와 같이 산 돌 되게 하셨네<br/>하나님이 거주하실 신령한 전 되게 해-<br/>제사장의 무리 되어 제물 드리게 하네<br/>',NULL,32413,4);
INSERT INTO stanza VALUES('K602','5','하나님의 성전 세운 다윗의 후손인 주-<br/>왕과 제사장으로서 주의 직책 다했네<br/>하나님의 권위로서 다스리신 왕인 주-<br/>제사장으로서 우릴 교통 안에 이끄네<br/>',NULL,32414,5);
INSERT INTO stanza VALUES('K602','6','하나님의 보좌 권위 주의 백성 다스려-<br/>생명수의 강의 교통 모든 백성 공급해<br/>주의 권위 주의 교통 건축 이루게 하네-<br/>왕과 제사장의 직분 주의 건축 완성해<br/>',NULL,32415,6);
INSERT INTO stanza VALUES('K602','7','하나님이 성육신된 장막이요 성전인 주<br/>예수 안에 하나님이 거주하고 표현돼<br/>하나님의 모든 충만 충만한 교회인 주-<br/>하나님의 건축 위한 모든 성도들일세<br/>',NULL,32416,7);
INSERT INTO stanza VALUES('K602','8','주는 영구한 처소요 우리 영원한 거처-<br/>우린 주 안에서 살며 영영 보호받겠네<br/>하나님이 동거하는 우리 또한 주의 성소<br/>영원토록 쉬임없이 하나님께 경배해<br/>',NULL,32417,8);
INSERT INTO stanza VALUES('K602','9','모퉁이돌 기초돌인 주는 반석 산 돌이요<br/>성전 교회 건축자요 거처요 성소일세<br/>건축의 모든 것 된 주 찬미하고 찬미해-<br/>산 돌들인 우리 또한 주로 건축되겠네<br/>',NULL,32418,9);
INSERT INTO stanza VALUES('K603','1','하나님 계획- 찬미-해 우리의 안에- 거하-사<br/>우리로 주의- 처소-돼 주 표현하게 하시-네<br/>',NULL,32419,1);
INSERT INTO stanza VALUES('K603','2','당신의 형상- 주시-고 당신을 대표-케 하-려<br/>우리를 지은- 하나-님 영과 혼 몸을 지었-네<br/>',NULL,32420,2);
INSERT INTO stanza VALUES('K603','3','주 생명 영접-하는- 자 주님의 성품- 소유-해<br/>주님과 하나- 되어-서 주님과 한 몸 이루-네<br/>',NULL,32421,3);
INSERT INTO stanza VALUES('K603','4','주 생명 흘러- 적셔-져 내 맘과 혼에- 스밀- 때<br/>난 진주 보석- 되어-서 주 영광 형상 되겠-네<br/>',NULL,32422,4);
INSERT INTO stanza VALUES('K603','5','감상을 위한- 것 아-닌 건축을 위한- 것이-니<br/>당신의 영광- 집으-로 지어져 가게 하소-서<br/>',NULL,32423,5);
INSERT INTO stanza VALUES('K603','6','주여 나 자신- 바치-니 날 건축되게- 하소-서<br/>날 굴복케 해- 연결-해 주 처소 되게 하소-서<br/>',NULL,32424,6);
INSERT INTO stanza VALUES('K603','7','타고난 생명-과 성-격 온전히 깨뜨-리소-서<br/>단독적인 것- 떠나-서 성도와 한 떡 되도-록<br/>',NULL,32425,7);
INSERT INTO stanza VALUES('K603','8','이럴 때 주의- 배필-돼 주님 자신을- 누리-며<br/>안식 가운데- 거하-며 주 마음 만족게 하-리<br/>',NULL,32426,8);
INSERT INTO stanza VALUES('K604','1','주는 토기장이요 영광스런 건축주<br/>나를 토기 만들고 또 나를 건축케 해<br/>흙으로 지어진 난 새로 창조된 산 돌<br/>나를 그릇 만들며 당신의 궁실 짓네<br/>나를 그릇 만들며 당신의 궁실 짓네<br/>',NULL,32427,1);
INSERT INTO stanza VALUES('K604','2','흙으로 지으시고 생명의 정금으로<br/>우리를 변케 하셔 진주 보석 되게 해<br/>건축을 거침으로 사랑의 배필 됐네<br/>주와 한 몸 되어서 주 충만함 누리네<br/>주와 한 몸 되어서 주 충만함 누리네<br/>',NULL,32428,2);
INSERT INTO stanza VALUES('K604','3','주의 원하시는 것 재료만이 아니요<br/>재료들 건축되어 안주하시기 원해<br/>만유의 그리스도 건축된 교회로서<br/>당신의 영광 풍성 나타내시기 원해<br/>당신의 영광 풍성 나타내시기 원해<br/>',NULL,32429,3);
INSERT INTO stanza VALUES('K604','4','혼자만 신령해서 칭찬받지 못하네<br/>단체의 생명만이 주님의 뜻 이루네<br/>뼈와 살 떠난 지체 온전한 주 못 보여<br/>건축된 몸이라야 주의 풍성 나타내<br/>건축된 몸이라야 주의 풍성 나타내<br/>',NULL,32430,4);
INSERT INTO stanza VALUES('K604','5','단독으로 마시고 당신의 도면 따라<br/>정밀히 결합하여 나를 건축하소서<br/>신령한 은사 줄 때 자기 높이지 말고<br/>건축 위해 다 바쳐 영광의 주 나타내<br/>건축 위해 다 바쳐 영광의 주 나타내<br/>',NULL,32431,5);
INSERT INTO stanza VALUES('K605','1','침체된 내 영에 생기를 불어서<br/>근심과 사망 이기고 부흥케 하소서<br/>',NULL,32432,1);
INSERT INTO stanza VALUES('K605','2','새 힘을 얻도록 생기를 불어서<br/>피곤함 이겨 날개로 날게 하옵소서<br/>',NULL,32433,2);
INSERT INTO stanza VALUES('K605','3','안식을 얻도록 생기를 불어서<br/>영 안에서 주 의지해 기쁘게 하소서<br/>',NULL,32434,3);
INSERT INTO stanza VALUES('K605','4','주 충만되도록 생기를 불어서<br/>뜻 세울 때나 행할 때 날 벗게 하소서<br/>',NULL,32435,4);
INSERT INTO stanza VALUES('K605','5','몸 안에 살도록 생기를 불어서<br/>영원토록 성도들과 건축게 하소서<br/>',NULL,32436,5);
INSERT INTO stanza VALUES('K606','1','주여 나를 내 자아와 육에서 구원하여<br/>성도들과 건축되어 영광 나타내게 해<br/>나의 악한 성질 교만 단독에서 구원하여<br/>나를 주 순종케하여 안식처 삼으소서<br/>',NULL,32437,1);
INSERT INTO stanza VALUES('K606','2','흐르는 생명 공급이 자라고 변케 하네<br/>나의 위치에서 힘써 성도들 온전케 해<br/>다른 사람 밟지 않고 내 본 것 아는 모든 것<br/>주 위해 다 바쳐 일해 주님의 몸 건축해<br/>',NULL,32438,2);
INSERT INTO stanza VALUES('K606','3','머리를 붙듦으로써 상합하고 연합해<br/>그리스도 풍성 누려 주의 풍성 충만해<br/>온전한 사람 이루어 장성한 분량 차도록<br/>넓고 긴 주의 사랑은 측량할 수 없도다<br/>',NULL,32439,3);
INSERT INTO stanza VALUES('K607','1','주의 생기 넣으소서 온땅에 흩어져 있는<br/>마른 뼈들 보옵소서 말씀해 살리소서<br/>',NULL,32440,1);
INSERT INTO stanza VALUES('K607','2','주의 생기 넣으소서 마른 뼈 일어나도록<br/>무덤에서 나오도록 말씀해 살리소서<br/>',NULL,32441,2);
INSERT INTO stanza VALUES('K607','3','주의 생기 넣으소서 주 백성 함께 살아나<br/>적 이기는 군대 되게 말씀해 살리소서<br/>',NULL,32442,3);
INSERT INTO stanza VALUES('K607','4','주의 생기 넣으소서 주 백성 하나 이루어<br/>권위 따른 인도받게 말씀해 살리소서<br/>',NULL,32443,4);
INSERT INTO stanza VALUES('K607','5','주의 생기 넣으소서 주 백성 한 몸 이루어<br/>주의 거처 될 수 있게 말씀해 살리소서<br/>',NULL,32444,5);
INSERT INTO stanza VALUES('K607','6','주의 생기 넣으소서 사망과 괴퍅함 떠나<br/>몸 안으로 돌아오게 말씀해 살리소서<br/>',NULL,32445,6);
INSERT INTO stanza VALUES('K607','7','주의 생기 넣으소서 온 성도 원수 진멸해<br/>주의 거처 세우도록 말씀해 살리소서<br/>',NULL,32446,7);
INSERT INTO stanza VALUES('K608','1','생명-의 공-기 불-어 넣어 날 소생하-여 주소서<br/>마른- 뼈 같-은 날- 회복해 몸 안-에 살-게 하-소서<br/>',NULL,32447,1);
INSERT INTO stanza VALUES('K608','2','생명-의 공-기 불-어 넣어 내 갇힌 영-을 해방해<br/>묶임-서 풀-어 몸-의 영에 연합-게 하-여 주-소서<br/>',NULL,32448,2);
INSERT INTO stanza VALUES('K608','3','생명-의 공-기 불-어 넣어 침체된 내- 영 살리사<br/>날 위-로하-여 몸-의 공급 얻도-록 하-여 주-소서<br/>',NULL,32449,3);
INSERT INTO stanza VALUES('K608','4','생명-의 공-기 불-어 넣어 공허한 내- 영 채우며<br/>은혜-를 주-사 몸-의 풍성 나로- 누리-게 하-소서<br/>',NULL,32450,4);
INSERT INTO stanza VALUES('K608','5','생명-의 공-기 불-어 넣어 날 죽음서- 건지소서<br/>분열-의 요-소 깨-뜨리사 몸 안-에 살-게 하-소서<br/>',NULL,32451,5);
INSERT INTO stanza VALUES('K609','1','오 보-배로운 청-사진 하나-님 장-막 청-사진<br/>주님-의 건축 방-식과 주 영-광 나타남 말해<br/>',NULL,32452,1);
INSERT INTO stanza VALUES('K609','2','오 언-약궤는 장-막의 중심-에 거-하고- 있네<br/>언약-궤 안엔 십-계명 새겨-진 돌판 놓였네<br/>',NULL,32453,2);
INSERT INTO stanza VALUES('K609','3','나무-에 금을 싼-법궤 하나-님 사-람 예-표해<br/>돌판-은 주 안에-거한 하나 -님 표현 말하네<br/>',NULL,32454,3);
INSERT INTO stanza VALUES('K609','4','주님-은 교회의- 중심 교회-는 주-의 안-식처<br/>하나-님은 주님- 안에 주 예-수는 교회 안에<br/>',NULL,32455,4);
INSERT INTO stanza VALUES('K609','5','금으-로 나무 싼- 장막 언약-궤의- 확대-이듯<br/>사람-과 하나님- 연합 교회-도 주의 확대라<br/>',NULL,32456,5);
INSERT INTO stanza VALUES('K609','6','은받-침 위에 연-결된 널판-들 장-막 이-루네<br/>정금-으로 싼 널-판을 고리- 빗장으로 이어<br/>',NULL,32457,6);
INSERT INTO stanza VALUES('K609','7','주님-의 구속 위-에 선 교회-는 성-도의- 집합<br/>신성- 안에 연결-되어 협력-하여 건축되네<br/>',NULL,32458,7);
INSERT INTO stanza VALUES('K609','8','장막- 위에 네 겹- 덮개 주 어-떠하-심 말-하네<br/>하나-님 거처 덮-는 주 하나-님 영광 나타내<br/>',NULL,32459,8);
INSERT INTO stanza VALUES('K609','9','주님-의 가리움-아래 성도-들 함-께 협-력해<br/>주님-의 업적 누-리며 주를- 옷 입고 건축돼<br/>',NULL,32460,9);
INSERT INTO stanza VALUES('K609','10','돌 판-은 언약궤- 안에 언약-궤는- 장막- 안에<br/>하나-님은 예수- 안에 주 예-수는 교회 안에<br/>',NULL,32461,10);
INSERT INTO stanza VALUES('K61','1','은혜의 주 그는 예수 그 이름은 “나는 … 이다”<br/>풍성하고 아름답고 진실한 이름<br/>',NULL,32462,1);
INSERT INTO stanza VALUES('K61','2','거룩하고 참된 이름 내 필요 다 채우시네<br/>주의 모든 어떠하심 내 필요 채워<br/>',NULL,32463,2);
INSERT INTO stanza VALUES('K61','3','거룩하신 아버지요 거룩하신 아들일세<br/>하나님의 비밀이요 나타남일세<br/>',NULL,32464,3);
INSERT INTO stanza VALUES('K61','4','이제 그 영 되신 주님 나와 함께 거하시네<br/>나로 그의 모든 풍성 누리게 하네<br/>',NULL,32465,4);
INSERT INTO stanza VALUES('K61','5','하나님을 표현하는 장막이신 주 예수님<br/>하나님이 안주하는 성전이실세<br/>',NULL,32466,5);
INSERT INTO stanza VALUES('K61','6','당신 안에 만나 보네 하나님을 아버지를<br/>하나님의 살진 것과 달콤함 누려<br/>',NULL,32467,6);
INSERT INTO stanza VALUES('K61','7','우리 죄를 담당하신 어린 양인 주 예수님<br/>신부 취해 연합하는 신랑이실세<br/>',NULL,32468,7);
INSERT INTO stanza VALUES('K61','8','나를 위해 자신 버려 상처받은 주 예수님<br/>나로 평강 기쁨 얻고 누리게 하네<br/>',NULL,32469,8);
INSERT INTO stanza VALUES('K61','9','지혜와 길 되신 주님 하나님의 뜻을 따라<br/>나로 은혜 입게 하고 축복받게 해<br/>',NULL,32470,9);
INSERT INTO stanza VALUES('K61','10','거룩함과 공의 되신 주는 하나님과 하나<br/>우리 하나님의 마음 기쁘게 하네<br/>',NULL,32471,10);
INSERT INTO stanza VALUES('K61','11','내게 칭의 주신 주님 또한 성화 이루시네<br/>그가 나를 하나님과 화목하게 해<br/>',NULL,32472,11);
INSERT INTO stanza VALUES('K61','12','주는 생명 주는 참 빛 어둠 제해 사망 삼켜<br/>나를 살려 해방하네 밝게 하시네<br/>',NULL,32473,12);
INSERT INTO stanza VALUES('K61','13','주는 부활 주는 능력 무덤 뚫고 음부 이겨<br/>날 강건케 하여 주사 승리케 하네<br/>',NULL,32474,13);
INSERT INTO stanza VALUES('K61','14','주는 나의 양식 생수 나의 모든 공급 되네<br/>피곤함서 소생시켜 만족케 하네<br/>',NULL,32475,14);
INSERT INTO stanza VALUES('K61','15','나를 위해 목숨 버린 나의 목자 되신 주님<br/>나의 모든 질병들을 치료한 의사<br/>',NULL,32476,15);
INSERT INTO stanza VALUES('K61','16','나를 돌봐 보양하며 위로하는 주 예수님<br/>모든 일에 보살피며 인도하시네<br/>',NULL,32477,16);
INSERT INTO stanza VALUES('K61','17','제사장과 왕이신 주 하나님께 날 이끄네<br/>나도 또한 주 권위에 참예한다네<br/>',NULL,32478,17);
INSERT INTO stanza VALUES('K61','18','주는 구속 또한 소망 나의 모습 변케 하네<br/>나로 그를 닮게 하고 표현케 하네<br/>',NULL,32479,18);
INSERT INTO stanza VALUES('K61','19','영광 기쁨 평강 진리 은혜 방패 거처 산 해<br/>사신 말씀 영적 반석 다 말 못하리<br/>',NULL,32480,19);
INSERT INTO stanza VALUES('K61','20','영원하고 무한하며 길고 넓고 높고 깊어<br/>충만하고 완전한 주 흘러 넘치네<br/>',NULL,32481,20);
INSERT INTO stanza VALUES('K610','1','오 주여 내 영 해방하소서 단독과 외식 자아 떠나서<br/>온전히 주의 건축이루게 영 안에 섞여지게 하소서<br/>',NULL,32482,1);
INSERT INTO stanza VALUES('K610','2','오 주여 내 영 해방하소서 다시는 자신 닫지 않도록<br/>내 자아에서 나오게하여 참 자유 안에 있게 하소서<br/>',NULL,32483,2);
INSERT INTO stanza VALUES('K610','3','오 주여 내 영 해방하소서 주 성령 통행하게 하소서<br/>내 자신에서 온전히 나와 주 충만 나타내게 하소서<br/>',NULL,32484,3);
INSERT INTO stanza VALUES('K610','4','오 주여 내 영 해방하소서 날 고갈에서 구원하소서<br/>내 이전 모든 빈곤함 떠나 주 풍성 맘껏 얻게 하소서<br/>',NULL,32485,4);
INSERT INTO stanza VALUES('K610','5','오 주여 내 영 해방하소서 다시는 속지 않게 하소서<br/>자신의 좁은 우물서 나와 무한함 안에 들어가도록<br/>',NULL,32486,5);
INSERT INTO stanza VALUES('K610','6','오 주여 내 영 해방하소서 나 자신에서 구원하소서<br/>온 성도들과 건축되어서 주 모든 것을 누릴 수 있게<br/>',NULL,32487,6);
INSERT INTO stanza VALUES('K611','1','영 안의 교통 사모하네 영 안에 섞여지기를<br/>단독의 행동 벗어나서 영 안의 건축 사모해<br/>',NULL,32488,1);
INSERT INTO stanza VALUES('K611','2','영 안의 교통 사모하여 내 영을 활짝 열겠네<br/>괴퍅한 고립 벗어나서 누구하고나 교통해<br/>',NULL,32489,2);
INSERT INTO stanza VALUES('K611','3','영 안의 교통 사모하여 내 영을 해방하겠네<br/>자신의 주장 벗어나서 영으로 장애물 이겨<br/>',NULL,32490,3);
INSERT INTO stanza VALUES('K611','4','영 안의 교통 사모하여 영으로 함께 기도해<br/>거짓된 가면 벗어나서 영 안에 참된 교통해<br/>',NULL,32491,4);
INSERT INTO stanza VALUES('K611','5','영 안의 교통 사모하여 균형된 교통 갈망해<br/>치우친 일들 벗어나서 봉사와 교통 겸하리<br/>',NULL,32492,5);
INSERT INTO stanza VALUES('K611','6','주여 이 갈망 이루소서 성도의 교통 반향해<br/>당신의 건축 속히 이뤄 주 계획 성취하소서<br/>',NULL,32493,6);
INSERT INTO stanza VALUES('K612','1','어떤 축복 권리인가 나는 제사장일세<br/>하나님의 택함 받아 귀한 직분 감당해<br/>',NULL,32494,1);
INSERT INTO stanza VALUES('K612','chorus','존귀한 제사장 직분 교회 건축 기초돼<br/>영 안에서 기도하며 하나님을 섬기네<br/>',NULL,32495,2);
INSERT INTO stanza VALUES('K612','2','권위 순서 따름으로 왕의 신분 지키고<br/>제사장의 직분 다해 교회 건축 이루리<br/>',NULL,32496,3);
INSERT INTO stanza VALUES('K612','3','제사장의 무리인 교회 제사장 직분 다해<br/>제사장의 체계 되야 참된 건축 이루리<br/>',NULL,32497,4);
INSERT INTO stanza VALUES('K612','4','교회 하락 황폐 인해 제사장 소홀해져<br/>성도의 영 약한 그때 말씀 사역 힘 얻네<br/>',NULL,32498,5);
INSERT INTO stanza VALUES('K612','5','선지자로 전파하는 말씀 귀히 여기나<br/>제사장의 기도 봉사 중히 여기지 않네<br/>',NULL,32499,6);
INSERT INTO stanza VALUES('K612','6','주여 내게 균형 주사 말씀 기도 중시해<br/>가르침과 더불어서 기도하게 하소서<br/>',NULL,32500,7);
INSERT INTO stanza VALUES('K612','7','봉사하며 기도해야 성도의 영 섞여져<br/>말씀 위에 기도 더해 교회 건축 이루리<br/>',NULL,32501,8);
INSERT INTO stanza VALUES('K613','1','거룩한 제사장들 교회 건축의- 산 돌<br/>제사장의 기도로 산- 돌들이 건축돼<br/>',NULL,32502,1);
INSERT INTO stanza VALUES('K613','chorus','항상 지성소에 가 영으로 보좌 만져<br/>주를 거친 기도만 건축 이-룰 수 있네<br/>',NULL,32503,2);
INSERT INTO stanza VALUES('K613','2','제사장 된 성도가 참된 산 돌 된-다네<br/>제사장의 봉사로 산- 돌 기능 발휘해<br/>',NULL,32504,3);
INSERT INTO stanza VALUES('K613','3','구약시대 제사장 장막과 하나-이니<br/>장막 안의 제사장 항 -상 한 몸이었네<br/>',NULL,32505,4);
INSERT INTO stanza VALUES('K613','4','신약시대 제사장 영의 전과 하-날세<br/>영적 성전 실재는 제 -사장 체계일세<br/>',NULL,32506,5);
INSERT INTO stanza VALUES('K613','5','교회 건축 본질은 제사장 직분-이니<br/>제사장이 봉사해 교-회 건축 완성돼<br/>',NULL,32507,6);
INSERT INTO stanza VALUES('K613','6','제사장의 봉사로 사람과 주 교-통해<br/>주님과의 교통에 성-도들 건축되네<br/>',NULL,32508,7);
INSERT INTO stanza VALUES('K613','7','이와 같이 건축돼 영 안에서 섞-여져<br/>제사장의 체계 돼 영 -적 제사 드리네<br/>',NULL,32509,8);
INSERT INTO stanza VALUES('K613','8','주의 은혜로 나도 제사장 귀히-여겨<br/>교회 건축 위하여 기 -도하게 하소서<br/>',NULL,32510,9);
INSERT INTO stanza VALUES('K614','1','은혜의 주님께 간구하니 영만이 흐르게 하옵소서<br/>과거 다 버리고 담과 벽 넘어서 영 흘러 통행케 하옵소서<br/>',NULL,32511,1);
INSERT INTO stanza VALUES('K614','2','은혜의 주님께 간구하니 영만이 흐르게 하옵소서<br/>교만을 떠나서 자신 보류 않고 영 맘껏 흐르게 하옵소서<br/>',NULL,32512,2);
INSERT INTO stanza VALUES('K614','3','은혜의 주님께 기도하니 영만이 흐르게 하옵소서<br/>높은 맘 안 품고 자만치 않으리 영이 늘 흐르게 하옵소서<br/>',NULL,32513,3);
INSERT INTO stanza VALUES('K614','4','은혜의 주님께 간구하니 영만이 흐르게 하옵소서<br/>자신이 최고라 말하지 않으리 더 깊이 흐르게 하옵소서<br/>',NULL,32514,4);
INSERT INTO stanza VALUES('K614','5','은혜의 주님께 요구하니 영만이 흐르게 하옵소서<br/>자세를 버리고 내 보좌 버리니 생수강 흐르게 하옵소서<br/>',NULL,32515,5);
INSERT INTO stanza VALUES('K614','6','은혜의 주여 내 간구 듣고 영만이 흐르게 하옵소서<br/>건축을 위하여 교통을 위하여 어디나 흐르게 하옵소서<br/>',NULL,32516,6);
INSERT INTO stanza VALUES('K615','1','오 사랑스런 주 장막 당신의 궁정 사모해<br/>당신의 임재 얻-고-자 내 몸과 맘 부르짖네<br/>',NULL,32517,1);
INSERT INTO stanza VALUES('K615','2','주 제단 있는 곳에서 참새가 제 집을 얻고<br/>작은 제비도 새-끼- 둘 보금자리를 얻었네<br/>',NULL,32518,2);
INSERT INTO stanza VALUES('K615','3','제비와 같이 약한 자 당신의 성전에 거해<br/>제단의 속죄 대-가-로 그 좋은 것 다 누리네<br/>',NULL,32519,3);
INSERT INTO stanza VALUES('K615','4','당신을 의지하므로 위험을 두려워 않네<br/>마음에 시온의- 대로- 있는 자는 복이 있네<br/>',NULL,32520,4);
INSERT INTO stanza VALUES('K615','5','눈물의 골짜기 가도 많은 샘의 곳 되게 해<br/>이른 비 은택 입-히-사 내 인생의 분깃 됐네<br/>',NULL,32521,5);
INSERT INTO stanza VALUES('K615','6','주님의 궁정의 한 날 다른 곳 천 날보다 나아<br/>주 성전 문지기-돼-도 악인의 장막 싫다네<br/>',NULL,32522,6);
INSERT INTO stanza VALUES('K615','7','당신은 해요 방패니 은혜와 영광 주소서<br/>당신 자신의 임-재-로 내 필요 다 채우소서<br/>',NULL,32523,7);
INSERT INTO stanza VALUES('K615','8','정직히 행한 자에게 좋은 것 아끼지 않아<br/>주님께 의지하-는- 자 은혜와 영광 끝없네<br/>',NULL,32524,8);
INSERT INTO stanza VALUES('K616','1','주님의- 거처-인 교회 사랑-스런 교회<br/>주의- 기쁨 또 즐-거움 내 사-모하는 곳<br/>',NULL,32525,1);
INSERT INTO stanza VALUES('K616','2','주님은- 교회- 위하여 자신-을 주셨네<br/>나 또-한 주 뜻 위-하여 내 몸-을 드리네<br/>',NULL,32526,2);
INSERT INTO stanza VALUES('K616','3','교회 위-해 주-님께서 내 생-명 되셨네<br/>주의- 갈망 이룰- 교회 이는- 나의 생활<br/>',NULL,32527,3);
INSERT INTO stanza VALUES('K616','4','교회는- 주의- 배-필 주의- 몸 또 신부<br/>내 마-음 다 드릴 곳이며 영원-한 안식처<br/>',NULL,32528,4);
INSERT INTO stanza VALUES('K616','5','교회 안-에 주- 당신이 내 누-림 내 간증<br/>나 주-님의 소유- 될 때 주 만-족하시리<br/>',NULL,32529,5);
INSERT INTO stanza VALUES('K616','6','주님의- 거처-인 교회 사랑-스런 교회<br/>나 영-원히 여기- 살며 떠나-지 않으리<br/>',NULL,32530,6);
INSERT INTO stanza VALUES('K617','1','주로부터- 나온- 생물 단독-적일수 없다네<br/>십자가 처리받고서 단체-의 주-를 살아내<br/>',NULL,32531,1);
INSERT INTO stanza VALUES('K617','chorus','피차 연결 동역하여 주 영광 나-타내<br/>같은 보조 같은 행동 주 보좌 가-져와<br/>',NULL,32532,2);
INSERT INTO stanza VALUES('K617','2','은혜의 힘-을 의-지해 자신-의 주장 버리네<br/>주 자랑 삼고 나타내 하나-님으-로 가리네<br/>',NULL,32533,3);
INSERT INTO stanza VALUES('K617','3','혼잡지 않-고 단-순해 비뚤-림 없이 정직해<br/>온화한 영 겸손한 맘 어디-에 가-나 영 좇아<br/>',NULL,32534,4);
INSERT INTO stanza VALUES('K617','4','견고히 연-결되-어서 서로- 온전케 한다네<br/>기능 달라도 일치돼 주 영-광 계-시 이루네<br/>',NULL,32535,5);
INSERT INTO stanza VALUES('K617','5','동역해 거-룩한- 불 타 더러-움 이물 다 태워<br/>거룩한 불이 비추니 모든- 행동-에 빛 발해<br/>',NULL,32536,6);
INSERT INTO stanza VALUES('K617','6','주의 큰 바-퀴 돌-아가 청명-한 하늘 펼쳐져<br/>주 보좌에서 다스려 주 영-광 형-상 표현해<br/>',NULL,32537,7);
INSERT INTO stanza VALUES('K618','1','주 안에서 성도 서로 지체돼<br/>동역하여 함께 한 몸 이루네<br/>',NULL,32538,1);
INSERT INTO stanza VALUES('K618','2','은사는 많으나 성령은 하나<br/>직임은 많으나 주도 하날세<br/>',NULL,32539,2);
INSERT INTO stanza VALUES('K618','3','어떤 지체든지 모두 소중해<br/>각자 위치 있고 기능 있다네<br/>',NULL,32540,3);
INSERT INTO stanza VALUES('K618','4','받은 은혜 은사 크든 작든지<br/>자고하지 않고 겸손해야 돼<br/>',NULL,32541,4);
INSERT INTO stanza VALUES('K618','5','각자 직임 다해 기능 나타내<br/>따로 행치 않고 충성 다하네<br/>',NULL,32542,5);
INSERT INTO stanza VALUES('K618','6','서로 공급하고 서로 포용해<br/>불화 간격 없이 주 으뜸 삼아<br/>',NULL,32543,6);
INSERT INTO stanza VALUES('K618','7','주는 머리시요 교회는 그 몸<br/>성령은 곧 관유 우린 하날세<br/>',NULL,32544,7);
INSERT INTO stanza VALUES('K619','1','신성에서 나와서 주 영광 나타내는 협력하는 생물들<br/>상합하여 한 몸돼 신성한 뜻 완성해 성령 좇아 행하네<br/>',NULL,32545,1);
INSERT INTO stanza VALUES('K619','chorus','생물 자취 따라서 주의 큰 바퀴 돌아 높고 밝은 움직임<br/>주의 영광 나타내 이로 주의 계획 완성돼<br/>',NULL,32546,2);
INSERT INTO stanza VALUES('K619','2','거룩하고 강한 불 속된 것 다 태우고 거룩한 빛 될 때에<br/>사방 밝게 비추네 빛 가운데 행할 때 주의 역사 뒤따라<br/>',NULL,32547,3);
INSERT INTO stanza VALUES('K619','3','성령 좇아 행하니 수정같이 청명해 양심 거리낌 없어<br/>간증 소리 발하네 외치고 또 들을 때 주의 역사 진행돼<br/>',NULL,32548,4);
INSERT INTO stanza VALUES('K619','4','주의 거처 주 보좌 권위 영광 나타내 보좌 위의 주 모습<br/>사람 모양 같으며 보좌 주위 광채는 거룩한 성 같도다<br/>',NULL,32549,5);
INSERT INTO stanza VALUES('K62','1','주 예수 이름 사랑하여 겸손히 엎드려<br/>영광과 권위 찬송 존귀 주 예수님께 드려<br/>다 크게 찬양 찬 - 양해 마음을 합하여<br/>주 아름다움 놀라움에 감격해 찬송하네<br/>',NULL,32550,1);
INSERT INTO stanza VALUES('K62','2','창세 전에 그 크신 사랑 이미 나타났네<br/>은혜를 주사 멸망하는 세상을 구하셨네<br/>나 같은 죄인 돌 - 보신 그 영원한 사랑<br/>날 주의 보물 되게 하려 내 죄 빚 갚으셨네<br/>',NULL,32551,2);
INSERT INTO stanza VALUES('K62','3','난 사랑하네 가난한 데 태어난 주 예수<br/>주 맘엔 은혜 가득하나 가신 길 외로웠네<br/>내 고통 대신 지 - 시고 가시관 쓰셨네<br/>내 진노의 잔 마시고 내 질고 - 당하셨네<br/>',NULL,32552,3);
INSERT INTO stanza VALUES('K62','4','오 정결하신 하나님의 어린양인 주님<br/>보혈을 흘려 나의 죄악 씻도록 예정됐네<br/>하늘 - 에서 지 - 금은 존귀 영광 얻은<br/>주 승리 인해 해방된 나 주의 - 이름 높여<br/>',NULL,32553,4);
INSERT INTO stanza VALUES('K620','1','성령의 구름 거룩한 불은 정금 신성을 나타내<br/>이로 인해 생명 얻음으로 살고 주 나타내-네<br/>',NULL,32554,1);
INSERT INTO stanza VALUES('K620','2','사람같이 사자 소와같이 독수리와 같이 살며<br/>주 영광의 형상 나타내네 여러 모양을 통-해<br/>',NULL,32555,2);
INSERT INTO stanza VALUES('K620','3','바른 걸음 분별있는 행동 신선하고도 찬란해<br/>주의 연단으로 순결케 돼 빛과 심판이 되-네<br/>',NULL,32556,3);
INSERT INTO stanza VALUES('K620','4','주 의지해 하늘 나르지만 사람 모양 흔적 지녀<br/>주 하나님 자랑 삼음으로 나 아닌 주 나타-내<br/>',NULL,32557,4);
INSERT INTO stanza VALUES('K620','5','은혜의 힘 안에 동역하여 각자 직책을 다하네<br/>숯불같이 타고 빛 발하니 모든 행동 빛나-네<br/>',NULL,32558,5);
INSERT INTO stanza VALUES('K620','6','경외하며 영을 좇아 행해 주도 함께 행하시네<br/>주 거룩한 얼굴 나타나네 안목이 풍성하-네<br/>',NULL,32559,6);
INSERT INTO stanza VALUES('K620','7','거리낌이 없는 양심으로 소리 발하며 들을 때<br/>주 표현돼 대적 정복하네 군대처럼 동역-해<br/>',NULL,32560,7);
INSERT INTO stanza VALUES('K620','8','사람 모양으로 나타난 주 보좌 위에 앉으셨네<br/>빛나고도 거룩한 성 같아 무지개 빛 나타-내<br/>',NULL,32561,8);
INSERT INTO stanza VALUES('K621','1','사랑-에 연-결된 복있-는 성-도들<br/>피차-에 한- 맘 한- 뜻 돼- 천상-의 교-통해<br/>',NULL,32562,1);
INSERT INTO stanza VALUES('K621','2','아버-지 보-좌 앞 한 기-도 올-리며<br/>다함-께 슬-픔 즐-거움- 평안-을 누-리네<br/>',NULL,32563,2);
INSERT INTO stanza VALUES('K621','3','피차-의 약-함과 수고-를 나-누며<br/>늘 동-고동-락하-는 중- 한 몸-과 한- 맘 돼<br/>',NULL,32564,3);
INSERT INTO stanza VALUES('K621','4','몸으-로 떠-날 때 맘 섭-섭하-여도<br/>영으-론 함-께 있-어서- 만날- 때 기-다려<br/>',NULL,32565,4);
INSERT INTO stanza VALUES('K621','5','이별-의 쓰-라림 없는- 날 속-히 와<br/>다함-께 사-랑의- 교제- 영원-히 누-리길<br/>',NULL,32566,5);
INSERT INTO stanza VALUES('K622','1','형제들 동거함 아름다워 머리에<br/>기름 흘러 내림이 헐몬의 이슬이<br/>내림같아 여기서 영생 복 명하셨네<br/>',NULL,32567,1);
INSERT INTO stanza VALUES('K622','2','성실한 맘으로 애찬 나눠 주 은혜<br/>배부르게 먹고서 감격한 맘으로<br/>주 찬송해 형제들 교제 안에 살겠네<br/>',NULL,32568,2);
INSERT INTO stanza VALUES('K623','1','하늘로-서 내려오는 향기로-운 공기<br/>깊이- 마-셔 육을- 벗-고 영엔 사-랑 채워<br/>',NULL,32569,1);
INSERT INTO stanza VALUES('K623','2','우리들-의 맘과 맘이 주 안에- 교통해<br/>한 몸- 안-에 자랄- 때-에 주만 사-랑케 돼<br/>',NULL,32570,2);
INSERT INTO stanza VALUES('K623','3','십자가-를 누림으로 주의 뜻-을 좇고<br/>더욱- 그-와 친근-하-여 주와 하-나되네<br/>',NULL,32571,3);
INSERT INTO stanza VALUES('K624','1','그리스도를 가져와 모일 때 풍성 다 바쳐<br/>하나님 음-식 되도록 주를 전람하세<br/>',NULL,32572,1);
INSERT INTO stanza VALUES('K624','chorus','다 주를 전람해 다 주를 전람해<br/>다 함께 주 풍성 가져와 다 주를 전람해<br/>',NULL,32573,2);
INSERT INTO stanza VALUES('K624','2','주를 힘임어 생활해 주를 의지해 싸우네<br/>그 몸의 경-륜 영원히 끊어지지 않아<br/>',NULL,32574,3);
INSERT INTO stanza VALUES('K624','3','내 가진 모든 것 경험 다 주를 위해 받은 것<br/>다 함께 모-일 때마다 주 전람해보세<br/>',NULL,32575,4);
INSERT INTO stanza VALUES('K624','4','모일 때 하나님 위해 그리스도를 가져와<br/>피차의 풍-성 누리며 주 전람해보세<br/>',NULL,32576,5);
INSERT INTO stanza VALUES('K624','5','부활 주 향기로 삼고 승천한 주를 높일 때<br/>하나님 만-족하시니 주 전람해보세<br/>',NULL,32577,6);
INSERT INTO stanza VALUES('K624','6','집회의 중심과 실지 모든 봉사와 분위기<br/>모두가 그-리스도를 전람하는 것일세<br/>',NULL,32578,7);
INSERT INTO stanza VALUES('K624','7','모든 간증과 기도와 영 안의 모든 교제들<br/>은사로 하-는 모든 것 전람 위해 있네<br/>',NULL,32579,8);
INSERT INTO stanza VALUES('K624','8','성부께 영광 돌리며 주님을 높이기 위해<br/>풍성한 그-리스도를 함께 전람하세<br/>',NULL,32580,9);
INSERT INTO stanza VALUES('K625','1','주 앞-에 우리 모-이니 더 깊-은 은-혜 주-소서<br/>더 풍-성한 생명- 얻고 더 귀-한 간-증 갖도록<br/>내 간-구와 내 사-모함 주여- 이루-어 주소서<br/>',NULL,32581,1);
INSERT INTO stanza VALUES('K625','2','메마-른 영 적셔-주는 기름- 부음-을 주-소서<br/>사람-의 맘 비춰-주는 은혜-의 빛-을 주소서<br/>부흥-되어 진보-하여 주 사-랑하-게 하소서<br/>',NULL,32582,2);
INSERT INTO stanza VALUES('K625','3','주여- 내 속 강하-게 해 밖의- 묶임-서 구-원해<br/>영 안-에 능력 가-지며 내 자-아 벗-게 하소서<br/>주 내- 안에 형상- 이뤄 주 뜻-만 통-행하도록<br/>',NULL,32583,3);
INSERT INTO stanza VALUES('K625','4','주여- 오순절과- 같은 능력-을 내-려 주-소서<br/>마음-이 찔려 통-회해 돌이-켜 은-혜 구하게<br/>치료-함과 빛 주-소서 묶인- 자 해-방하소서<br/>',NULL,32584,4);
INSERT INTO stanza VALUES('K626','1','오 하나님께 경배해 영 안에 실재로<br/>그 아들 예수 말씀을 따라서 나가세<br/>',NULL,32585,1);
INSERT INTO stanza VALUES('K626','2','오 하나님은 영이니 내게 참 친근해<br/>나 실재 안에 영으로 주님을 경외해<br/>',NULL,32586,2);
INSERT INTO stanza VALUES('K626','3','주 경배토록 내 안에 영 지으셨으니<br/>내 밖의 노력 버리고 영으로 돌이켜<br/>',NULL,32587,3);
INSERT INTO stanza VALUES('K626','4','그 영으로서 나의 영 거듭나게 하며<br/>내 생각 새롭게 하여 주 섬기게 하네<br/>',NULL,32588,4);
INSERT INTO stanza VALUES('K626','5','내 안의 느낌 따라서 주님을 경배해<br/>바르는 그 영 역사로 주님만 나타내<br/>',NULL,32589,5);
INSERT INTO stanza VALUES('K626','6','그림자 의지 안 하고 이 실재 안에서<br/>주 섬기면서 경배해 찬양을 드리세<br/>',NULL,32590,6);
INSERT INTO stanza VALUES('K626','7','우리가 누린 주님을 또 그분께 바쳐<br/>그 달콤함과 귀함을 다 함께 감상해<br/>',NULL,32591,7);
INSERT INTO stanza VALUES('K626','8','다 영과 실재 의지해 함께 와 모이세<br/>주 은혜 보좌 둘러싸 경배를 드리세<br/>',NULL,32592,8);
INSERT INTO stanza VALUES('K627','1','일상 생활과 집회에서도 그리스도가 중심이시니<br/>형식과 교리 위하지 않고 그리스도만 위해 모이네<br/>',NULL,32593,1);
INSERT INTO stanza VALUES('K627','2','그리스도는 길과 빛이니 그 안에 살고 그를 따르리<br/>그분이 양식 생수이시니 늘 먹고 마셔 양육 얻겠네<br/>',NULL,32594,2);
INSERT INTO stanza VALUES('K627','3','그리스도는 진리와 생명 늘 증거하고 공급하겠네<br/>그리스도가 주와 머리니 주 찬양하고 높이 올리세<br/>',NULL,32595,3);
INSERT INTO stanza VALUES('K627','4','하나님께나 사람에게도 주 만유 안에 만유 되시네<br/>교회의 실재 내용 되시며 생명과 인수 증가케 하네<br/>',NULL,32596,4);
INSERT INTO stanza VALUES('K627','5','우리의 모든 찬송과 기도 그리스도의 실재 표현해<br/>영 안의 모든 교통과 봉사 다 주를 나타내는 것일세<br/>',NULL,32597,5);
INSERT INTO stanza VALUES('K627','6','주 이름 안에 우리 모일 때 기름 부음을 따라 기도해<br/>생각과 형식 따르지 않고 영 사용하여 주를 표현해<br/>',NULL,32598,6);
INSERT INTO stanza VALUES('K627','7','그리스도만 바라보면서 성숙되도록 그를 적용해<br/>주 위해 모두 잃어버리고 영원히 주를 만유 삼으리<br/>',NULL,32599,7);
INSERT INTO stanza VALUES('K628','1','영을 훈련하며 생각 거절해<br/>함께 모일 때에 이 비결 누려<br/>',NULL,32600,1);
INSERT INTO stanza VALUES('K628','2','영을 훈련하며 형식 거절해<br/>주만 중심 삼고 서로 교통해<br/>',NULL,32601,2);
INSERT INTO stanza VALUES('K628','3','영을 훈련하며 감정 거절해<br/>모든 공급 안에 주가 실재라<br/>',NULL,32602,3);
INSERT INTO stanza VALUES('K628','4','영을 훈련하며 혼을 부인해<br/>서로 도움 줄 때 주를 의지해<br/>',NULL,32603,4);
INSERT INTO stanza VALUES('K628','5','영 안에 해방돼 자기 의 벗고<br/>자기 느낌 책망 벗어버리라<br/>',NULL,32604,5);
INSERT INTO stanza VALUES('K628','6','영 안에 해방돼 자기 뜻 벗고<br/>자기 사랑 교만 내려 놓으라<br/>',NULL,32605,6);
INSERT INTO stanza VALUES('K628','7','죄를 씻는 보혈 주 이름으로<br/>영을 훈련하여 주 승리 취해<br/>',NULL,32606,7);
INSERT INTO stanza VALUES('K628','8','영을 훈련하여 주를 접촉해<br/>영으로 그 말씀 풍성 접촉해<br/>',NULL,32607,8);
INSERT INTO stanza VALUES('K628','9','영을 사용할 때 주가 증거돼<br/>영을 사용할 때 우리 만족해<br/>',NULL,32608,9);
INSERT INTO stanza VALUES('K628','10','영을 훈련함이 우리 필요라<br/>영을 훈련할 때 주가 인도해<br/>',NULL,32609,10);
INSERT INTO stanza VALUES('K629','1','주님의 지체로서 주 표현해야 해<br/>제기능 발휘하여 주 풍성나타내<br/>방관자 되지 말고 지체로서 행해<br/>사망의 해를 제해 교통 가져오세<br/>',NULL,32610,1);
INSERT INTO stanza VALUES('K629','2','단독의 일 버리고 한 군대 이루어<br/>온 몸이 협력하여 서로 의지하세<br/>내 선택 버리고서 생명 흐름 따라<br/>분리함 버리고서 성령 공급하세<br/>',NULL,32611,2);
INSERT INTO stanza VALUES('K629','3','딴 중심 버리고서 주께만 집중해<br/>주 안에 교통하며 은혜에 참예해<br/>그는 머리와 내용 우린 그의 충만<br/>집회의 활동 통해 주만 나타내세<br/>',NULL,32612,3);
INSERT INTO stanza VALUES('K629','4','임의로 비평말고 사랑 안에 세워<br/>피차 온전케 하며 서로 짊어지세<br/>타고난 생명에서 자아서 구출돼<br/>영 안에 훈련받아 몸의 봉사 이뤄<br/>',NULL,32613,4);
INSERT INTO stanza VALUES('K63','1','은혜 - 받은 - 자들 중에 향기로운 주 이름<br/>주 예 - 수 이름 보 - 다 더 달콤 - 한 것 없네<br/>',NULL,32614,1);
INSERT INTO stanza VALUES('K63','2','하나 - 님 사 - 람 되셔서 은혜 - 나타내고<br/>하늘 - 의 생명 세상 생활 몸으 - 로 표현해<br/>',NULL,32615,2);
INSERT INTO stanza VALUES('K63','3','해 받 - 고 견 - 딘 큰 사랑 나타내는 그 이름<br/>의지할 데 없는 우 - 리를 동정 - 한 그 이름<br/>',NULL,32616,3);
INSERT INTO stanza VALUES('K63','4','죄없 - 는 예 - 수 죄 되어 그 몸 - 을 버렸네<br/>당신 - 의 짐 무거 - 워져 내 짐 - 가벼워져<br/>',NULL,32617,4);
INSERT INTO stanza VALUES('K63','5','당신 - 의 이 - 름 말할 때 내 맘 - 곧 일어나<br/>사랑으로 날 구한 - 주께 경배 - 를 드리네<br/>',NULL,32618,5);
INSERT INTO stanza VALUES('K630','1','주의 임재와 산 말씀 위에 헤어지기 전 주께 찬양해<br/>주의 귀함에 매혹된 우리 능력의 말씀에 붙잡혔네<br/>',NULL,32619,1);
INSERT INTO stanza VALUES('K630','2','주의 말씀은 영이요 생명 날 양육하며 공급하시네<br/>주 형상 따라 성숙게 하며 주 신장 이르도록 변케 해<br/>',NULL,32620,2);
INSERT INTO stanza VALUES('K630','3','주님 자신 더 내게 공급해 영 안에 나를 살게 하소서<br/>주 은혜로 또 모일 때까지 날 교통 안에 지켜 주소서<br/>',NULL,32621,3);
INSERT INTO stanza VALUES('K631','1','은혜의 주여 마치기 전에 주 영광 풍성 나타내려고<br/>주의 신선한 은혜 인하여 다시 주 향해 찬양합니다<br/>',NULL,32622,1);
INSERT INTO stanza VALUES('K631','2','주 은혜 안에 집회 마치나 주 임재 영영 마치지 않아<br/>우리가 주를 사랑하는 한 주 영의 능력 늘 공급되리<br/>',NULL,32623,2);
INSERT INTO stanza VALUES('K631','3','주님의 임재 함께하시어 우리의 근심 함께 나누며<br/>다시 집회에 참여하도록 늘 나로 주 누리게 하소서<br/>',NULL,32624,3);
INSERT INTO stanza VALUES('K632','1','십자가 군사 들아 주 위해 일어나 주님의 깃발<br/>들고 위엄을 높이라 대군을 이끄신 주<br/>곧 승리하리라- 주 이름 거룩하게 여기는 날까지<br/>',NULL,32625,1);
INSERT INTO stanza VALUES('K632','2','십자가 군사들아 주 명령 들으라 한 보조 안에<br/>행해 주 이름 의지해 원수가 흉악해도<br/>다 함께 공격해- 원수 다 진멸토록 용감히 나가세<br/>',NULL,32626,2);
INSERT INTO stanza VALUES('K632','3','주 능력 의지하여 주 위해 일어나 널 의지하지<br/>말고 혈기 쓰지 말라 전신갑주를 입고<br/>무시로 기도해- 언제나 대항할 때 영 좇아 전진해<br/>',NULL,32627,3);
INSERT INTO stanza VALUES('K632','4','전쟁은 길지 않다 주 위해 싸우라 이 싸움 맹렬<br/>해도 곧 개가 부르리 주 의지해 이기면<br/>면류관 얻으리- 영원히 주와 함께 왕노릇하리라<br/>',NULL,32628,4);
INSERT INTO stanza VALUES('K633','1','주의 군사들-아 전진하여라 십자가의 깃발<br/>높이들고서 전쟁터로 나-가 귀신 물리쳐<br/>주의 명령 따 -라- 원수 소탕해<br/>',NULL,32629,1);
INSERT INTO stanza VALUES('K633','chorus','주의 군사들-아 전진하여-라<br/>십자가의 깃발 높이 들고서<br/>',NULL,32630,2);
INSERT INTO stanza VALUES('K633','2','예수 이름 앞-에 마귀 쫓기니 주의 군사들아<br/>대적 멸하라 높이 찬양할- 때 음부 떨리니<br/>찬송 소리 더 -욱- 높이 올려라<br/>',NULL,32631,3);
INSERT INTO stanza VALUES('K633','3','주의 교회 세-력 대군 같으니 고대 성도들과<br/>우리 다함께 앞선 성도 달-려 우린 뒤 따라<br/>한 영 한 몸 한- 소망 한 믿음일세<br/>',NULL,32632,4);
INSERT INTO stanza VALUES('K633','4','세상 왕 바뀌-고 열국 망하나 주와 교회 영영<br/>흥왕하리라 악한 음부 권-세 교회 못이겨<br/>교회 앞에 마 -귀- 파멸되리라<br/>',NULL,32633,5);
INSERT INTO stanza VALUES('K633','5','은혜 입은 성-도 전진하여라 교회 행군 따라<br/>개가 부르며 승리의 왕 주-께 천사와 함께<br/>영광 존귀 찬 -양- 돌려 드리세<br/>',NULL,32634,6);
INSERT INTO stanza VALUES('K634','1','돌진하라 전-사여 불붙은- 전선에<br/>주 이미 이겼-으니 늘 노래 부르라<br/>흑암아 물러가-라 사탄은 끝났다<br/>만-군의 대장 예-수 개가 속-에 온다<br/>',NULL,32635,1);
INSERT INTO stanza VALUES('K634','2','“돌진하라 전-사여 날 바라-보아라<br/>너 날 위해 이-기면 보좌에 오르리”<br/>세상의 싸움 아-닌 영적 전쟁이니<br/>사-방에 있는 적-을 주 이미-아신다<br/>',NULL,32636,2);
INSERT INTO stanza VALUES('K634','3','“돌진하라 전-사여 내 보좌-얻으라<br/>내 부활 능력- 네 영 초월케 하리라<br/>날 통해 권능 얻-고 날 통해 이기리<br/>날- 통해 개가 속-에 높이 오-르리라”<br/>',NULL,32637,3);
INSERT INTO stanza VALUES('K634','4','“돌진하라 전-사여 내 보좌- 얻으라<br/>네 자리 준비-했다 즐거워하여라”<br/>우리는 주와 함-께 하늘에 앉았다<br/>전-쟁의 함성 떠-나 죄악을- 떠났다<br/>',NULL,32638,4);
INSERT INTO stanza VALUES('K634','5','돌진하라 전-사여 주 보좌-얻으라<br/>주 너를 선택-하여 왕국 얻게 한다<br/>네 장래 광명이-니 낙심치 말아라<br/>늘- 주와 함께하-며 그 사랑- 받으리<br/>',NULL,32639,5);
INSERT INTO stanza VALUES('K634','6','환호하며 돌-진해 앞에 보-좌 있다<br/>시온산 고봉-에서 새 노래 부르리<br/>어린 양 승리하시고 보좌에 앉았다<br/>주- 승리하셨으-니 주 높이- 찬미해<br/>',NULL,32640,6);
INSERT INTO stanza VALUES('K635','1','주가 흑암 고통 중에 사탄 시험 받을 때<br/>악령 주를 유혹했네 면류관 버리라고<br/>',NULL,32641,1);
INSERT INTO stanza VALUES('K635','chorus','전사들아 굳게 서라 승리의 주 생각하라<br/>주가 사탄 이겼으니 용감하게 싸우라<br/>',NULL,32642,2);
INSERT INTO stanza VALUES('K635','2','너의 친구 요동하고 너를 의심할 때에<br/>적과 통해 널 비웃고 너를 속일지라도<br/>',NULL,32643,3);
INSERT INTO stanza VALUES('K635','3','이 세상이 복락으로 몰래 올무 치고서<br/>허영 세속 인정으로 믿음 포기케 할 때<br/>',NULL,32644,4);
INSERT INTO stanza VALUES('K635','4','바쁜 일로 피곤해도 아무 보상 없을 때<br/>손실 질병 모든 고통 감당키 어려워도<br/>',NULL,32645,5);
INSERT INTO stanza VALUES('K635','5','이내 전쟁 지나가고 사탄 악령 구속돼<br/>나팔소리 들으면서 교회 영광 얻으리<br/>',NULL,32646,6);
INSERT INTO stanza VALUES('K635','6','내 왕 개가 부르시며 왕권 행사하시리<br/>모든 나라 돌아와서 예수 찬양하리라<br/>',NULL,32647,7);
INSERT INTO stanza VALUES('K636','1','악한 날에 굳게 서 사람 말 상관말고<br/>진흙같은 얼굴들 두려워말고<br/>',NULL,32648,1);
INSERT INTO stanza VALUES('K636','2','주의 말씀 인하여 대가 지불하여라<br/>성도 보조 맞추어 따라갈지라<br/>',NULL,32649,2);
INSERT INTO stanza VALUES('K636','3','적의 궤계 이기고 쾌락 미혹 뿌리쳐<br/>사람 속임 떨치고 굳게 설지라<br/>',NULL,32650,3);
INSERT INTO stanza VALUES('K636','4','그날 오기까지는 주로 인해 굳게 서<br/>깨어 기도할지라 주의 군사여<br/>',NULL,32651,4);
INSERT INTO stanza VALUES('K637','1','단독으로 대항말고 몸 안에서 싸우라<br/>머리와 몸 연합하면 보좌에서 내치리<br/>',NULL,32652,1);
INSERT INTO stanza VALUES('K637','chorus','몸 안에서 전쟁하라 머리 공로 인하여<br/>몸과 함께 전쟁할 때 결코 승리하리라<br/>',NULL,32653,2);
INSERT INTO stanza VALUES('K637','2','하나님의 전신갑주 몸을 위한 것이니<br/>몸 안에서 싸울 때에 너도 함께 승리해<br/>',NULL,32654,3);
INSERT INTO stanza VALUES('K637','3','주님 위해 세운 교회 음부가 못 이기니<br/>건축된 몸만이 능히 마귀 대항하리라<br/>',NULL,32655,4);
INSERT INTO stanza VALUES('K637','4','몸 안에서 주 의지해 하늘 한계에 앉아<br/>정사들과 악한 영과 쉬지 말고 싸우라<br/>',NULL,32656,5);
INSERT INTO stanza VALUES('K637','5','모든 형제 주 위하여 주의 몸의 지체 돼<br/>영 안에서 기도하며 보혈 인해 승리해<br/>',NULL,32657,6);
INSERT INTO stanza VALUES('K637','6','머리이신 주의 능력 우릴 이기게 하니<br/>형제들과 군대 되어 군사로서 싸우리<br/>',NULL,32658,7);
INSERT INTO stanza VALUES('K637','7','몸 안에서 공격할 때 악한 자를 정복해<br/>주 뜻따라 묶고 매면 원수 우리 밥 되리<br/>',NULL,32659,8);
INSERT INTO stanza VALUES('K638','1','내 주는 강-한 성-이요 견고한 보장이-시니<br/>흉악함 날-포위-해도 그가 날 구하시-리라<br/>옛 원수 마귀는 여전히 틈타서 모략과 궤계로<br/>공격을 꾀하니 이 땅에 적수 없-도다<br/>',NULL,32660,1);
INSERT INTO stanza VALUES('K638','2','자기 힘 의-지하-면은 패할 수밖에 없-도다<br/>하나님께-서 택-한 자 곁에 서 있지 않-느냐<br/>이 사람 주 예수 왜 의지 안하나 그는 그리스도<br/>만군의 주시니 그만이 승리자-로다<br/>',NULL,32661,2);
INSERT INTO stanza VALUES('K638','3','세상에 마-귀 들-끓어 늘 파괴 음모하-여도<br/>나의 주 나-를 통-하여 진리로 이기게-하리<br/>친척과 재물과 명예와 생명을 다 뺏긴다 해도<br/>진리는 서리라 그 나라 영원하-리라<br/>',NULL,32662,3);
INSERT INTO stanza VALUES('K639','1','전쟁 맹렬하고 적 강해도 주 말씀 믿고서 찬송하라<br/>',NULL,32663,1);
INSERT INTO stanza VALUES('K639','2','한 번만 외쳐도 이기리니 입 다물지 말고 간증하라<br/>',NULL,32664,2);
INSERT INTO stanza VALUES('K639','3','너의 영 근심해 힘 없을 때 피 인해 구하면 강해지리<br/>',NULL,32665,3);
INSERT INTO stanza VALUES('K639','4','원수가 악해도 넌 이긴다 위치만 지키면 곧 승리해<br/>',NULL,32666,4);
INSERT INTO stanza VALUES('K639','5','소리를 높이어 승리 외쳐 어두운 광경도 곧 변하리<br/>',NULL,32667,5);
INSERT INTO stanza VALUES('K64','1','놀랍고도 사랑스런 내 - 주 이름 주 예수<br/>동정녀 - 에게 - 서 나셔 사람 모 - 양 취 - 했네<br/>우릴 죄악에 - 서 건진 주는 「여호와 구주」<br/>우리 안에 영 - 접할 때 거룩한 생명 얻네<br/>',NULL,32668,1);
INSERT INTO stanza VALUES('K64','2','영광스런 위임받은 그 - 이름 그리스도<br/>영원 전 - 에 택 - 함 받은 기름 부 - 음 받 - 은 자<br/>하나님의 사 - 랑 인해 세워지신 메시야<br/>그분 영광 나 - 타내고 그분 뜻 완성했네<br/>',NULL,32669,2);
INSERT INTO stanza VALUES('K64','3','하나님이 사람들과 함 - 께한 임마누엘<br/>하나님 - 과 인 - 성 연합 영원히 - 못 나 - 누리<br/>하나님을 표 - 현한 주 은혜 진리 충만해<br/>하나님의 영 - 광인 주 하나님 충만일세<br/>',NULL,32670,3);
INSERT INTO stanza VALUES('K64','4','사랑스런 주의 이름 모 - 든 풍성 나타내<br/>주의 이 - 름 그 - 가치를 영영 간 - 직하 - 겠네<br/>귀한 구주 그리스도께 찬양 경배드리리<br/>사랑 구주 임 - 마누엘 영원토록 높이리<br/>',NULL,32671,4);
INSERT INTO stanza VALUES('K640','1','항상 사탄에겐“아니다”주껜“예”라 말하리<br/>주의 모든 계획 장애 없이 내게 이뤄지도록<br/>주의 명령 들을 때에 주의 뜻 이루도록<br/>능력의 영 충만하여 내게 권능 주소서<br/>',NULL,32672,1);
INSERT INTO stanza VALUES('K640','2','항상 사탄에겐“아니다”주껜“예”라 말하리<br/>영영 이런 태도 취하도록 내게 은혜 주소서<br/>악한 사탄 나의 길을 가로막아 설 때에<br/>주 예수여 날 돌아봐 주 순종케 하소서<br/>',NULL,32673,2);
INSERT INTO stanza VALUES('K640','3','항상 사탄에겐“아니다”주껜“예”라 말하리<br/>고통 있더라도 주님만을 순종하기 원하네<br/>주와 함께 전진할 때 주 날 보호하리니<br/>어떤 위협 유혹에도 돌아서지 않으리<br/>',NULL,32674,3);
INSERT INTO stanza VALUES('K641','1','오늘은 원수 더 흉악하여 전쟁의 소리 더욱 맹렬해<br/>음부의 반대가 더 거세도 주께서 속히 다시오시리<br/>',NULL,32675,1);
INSERT INTO stanza VALUES('K641','2','오늘은 시련이 더 참담해 음부도 세력 모아 습격해<br/>전쟁은 더욱더 어려워도 주께서 더욱 가까우시다<br/>',NULL,32676,2);
INSERT INTO stanza VALUES('K641','3','말세에 주 말씀 혼잡되고 사탄은 힘 다하여 싸울 때<br/>강한 힘 있어야 적 타파해 주 오면 다시 탄식 없으리<br/>',NULL,32677,3);
INSERT INTO stanza VALUES('K641','4','누가 주 의지해 전진하랴 그 누가 믿음에 굳게 서랴<br/>강하여 개가를 부르려면 주께서 속히 오심 믿으라<br/>',NULL,32678,4);
INSERT INTO stanza VALUES('K641','5','십자가의 길을 누가 가랴 그 누가 돌아서지 않으랴<br/>고통을 이기고 전진하면 주께서 가까우심 보리라<br/>',NULL,32679,5);
INSERT INTO stanza VALUES('K641','6','지금은 흑암이 더 깊으나 휴거의 때에 빛이 나타나<br/>거기서 주 보며 원수 밟고 주 이미 오신 것을 외치리<br/>',NULL,32680,6);
INSERT INTO stanza VALUES('K642','1','주- 예수의 승-리 믿고 그- 이름에 서-라<br/>네- 힘으로 서-지말고 네- 재능 의지말-고<br/>혈기의 병-기- 버리고 성-령의 검만 사용해<br/>주 갑주 입고 소-멸-해 원수-의- 화전을<br/>',NULL,32681,1);
INSERT INTO stanza VALUES('K642','2','보-라 원수 모-여든다 제- 위치 지켜-라<br/>어-둠 속에 전-쟁할 때 주- 의지해- 싸-워<br/>너 후퇴할- 때- 온 군대 함-께 영향- 입-고<br/>너 인해 너의 형-제-가 곤경-을- 겪는다<br/>',NULL,32682,2);
INSERT INTO stanza VALUES('K642','3','사-탄 그의 종-말 알고 더-욱더 방해-해<br/>근-심 유혹 시-험 고난 전-보다 더- 커-져<br/>음부의 권-세- 우리를 전-보다 더- 눌-러<br/>너의 영 근심하-게- 해 두려-움- 더 준다<br/>',NULL,32683,3);
INSERT INTO stanza VALUES('K642','4','이- 때 우리 어-찌하여 주- 칭찬 얻으-랴<br/>안-락 찾아 원-수에게 도-살을 당-하-랴<br/>고난 더 증-가-하여도 더- 참고 나-가-자<br/>생사의 관문 여-기-서 결정-돼-야 한다<br/>',NULL,32684,4);
INSERT INTO stanza VALUES('K642','5','주- 예수는 승-리자니 주- 인해 굳게-서<br/>끝-날까지 모-든 고통 견-디어 내-어-라<br/>주 예수 곧- 오-실 때에 전-쟁도 끝-나-리<br/>오늘 너 깨어 있-으-면 그날- 권-세 얻네<br/>',NULL,32685,5);
INSERT INTO stanza VALUES('K643','1','승리 승리 할렐루야 승리 승리 할렐루야<br/>승리 승리 할렐루야 주 승리 하셨네<br/>',NULL,32686,1);
INSERT INTO stanza VALUES('K643','2','승리 승리 할렐루야 승리 승리 할렐루야<br/>승리 승리 할렐루야 나 함께 승리해<br/>',NULL,32687,2);
INSERT INTO stanza VALUES('K643','3','영광 영광 할렐루야 영광 영광 할렐루야<br/>영광 영광 할렐루야 주 영광 돌리세<br/>',NULL,32688,3);
INSERT INTO stanza VALUES('K644','1','할렐루야 예수 승리 높이 찬양해<br/>죄와 사망 마귀 모두 주가 이겼네<br/>',NULL,32689,1);
INSERT INTO stanza VALUES('K644','chorus','할렐루야 주의 승리 영광의 소식<br/>우리 주님 승리하고 또 승리하네<br/>',NULL,32690,2);
INSERT INTO stanza VALUES('K644','2','할렐루야 예수 승리 능력의 보혈<br/>십자가로 이길 때에 마귀 도망해<br/>',NULL,32691,3);
INSERT INTO stanza VALUES('K644','3','할렐루야 예수 승리 질병 소멸해<br/>완전 승리 거두셨네 골고다에서<br/>',NULL,32692,4);
INSERT INTO stanza VALUES('K644','4','할렐루야 예수 승리 담대하여라<br/>두려움 다 버리고서 명령 따르라<br/>',NULL,32693,5);
INSERT INTO stanza VALUES('K644','5','할렐루야 예수 승리 믿고 나아가<br/>흑암 권세 에워싸도 주가 길 여네<br/>',NULL,32694,6);
INSERT INTO stanza VALUES('K644','6','할렐루야 승리 예수 다시 오시리<br/>그와 함께 이기는 자 같이 환호해<br/>',NULL,32695,7);
INSERT INTO stanza VALUES('K645','1','하늘과 땅 모-든 권-세 부활의 주가 받았네<br/>그와 연합해- 의지-해 모든 원수 굴-복 시켜<br/>',NULL,32696,1);
INSERT INTO stanza VALUES('K645','2','주 말씀 의지-할 때-에 마귀의 능력 이기리<br/>주 권능 취해- 짓밟-아 뱀 머리 용의- 몸통을<br/>',NULL,32697,2);
INSERT INTO stanza VALUES('K645','3','높은 산 가로-막아-도 하늘이든지 땅이나<br/>주 이름으로- 명하-여 다 떠나가게- 하리라<br/>',NULL,32698,3);
INSERT INTO stanza VALUES('K645','4','믿음이 산을- 명하-니 순종해 바다로 가라<br/>난 하나님의- 목적-을 다 이루고야- 말리라<br/>',NULL,32699,4);
INSERT INTO stanza VALUES('K646','1','악한 원수 이기려면 주의 보혈 의지해<br/>보혈 효능 능력으로 기필코 승리하리<br/>',NULL,32700,1);
INSERT INTO stanza VALUES('K646','chorus','악한 원수 이기려면 주의 보혈 의지하라<br/>보혈 효능 능력으로 기필코 승리하리<br/>',NULL,32701,2);
INSERT INTO stanza VALUES('K646','2','주의 승리 보혈로써 참소자를 대적해<br/>보혈 너를 변호하고 참소 비난 물리쳐<br/>',NULL,32702,3);
INSERT INTO stanza VALUES('K646','3','주의 승리 보혈로써 신실하심 믿게 돼<br/>너를 위한 속죄피로 하나님 널 사했네<br/>',NULL,32703,4);
INSERT INTO stanza VALUES('K646','4','주의 승리 보혈로써 너의 위치 선포해<br/>영원하신 승리 보혈 원수 패배케 하네<br/>',NULL,32704,5);
INSERT INTO stanza VALUES('K646','5','주의 승리 보혈로써 주의 권능 취하네<br/>예수 보혈 적용하면 이기고야 말리라<br/>',NULL,32705,6);
INSERT INTO stanza VALUES('K646','6','주의 승리 보혈로써 하늘 한계에 앉아<br/>승천한 주 권능으로 원수 무장 해제해<br/>',NULL,32706,7);
INSERT INTO stanza VALUES('K647','1','주 예수의 이기는 자 되기원하면<br/>지금 주의 부르심에 귀 기울이라<br/>',NULL,32707,1);
INSERT INTO stanza VALUES('K647','chorus','면류관을 놓고 주가 지금 부른다<br/>이기는 자 되어 주의 만족 구하리<br/>',NULL,32708,2);
INSERT INTO stanza VALUES('K647','2','이기는 자 되려면은 주께 매혹돼<br/>처음 사랑 저버리지 말아야 한다<br/>',NULL,32709,3);
INSERT INTO stanza VALUES('K647','3','이기는 자 되려면은 생명 의지해<br/>주를 위해 핍박 고난 받아야 한다<br/>',NULL,32710,4);
INSERT INTO stanza VALUES('K647','4','이기는 자 되려면은 주의 증인 돼<br/>이때 네게 감췬 만나 공급되리라<br/>',NULL,32711,5);
INSERT INTO stanza VALUES('K647','5','단순하고 순수하게 이기는 자 돼<br/>혼잡함을 이길 때에 주의 힘 얻어<br/>',NULL,32712,6);
INSERT INTO stanza VALUES('K647','6','살아 계신 주 의지해 이기는 자 돼<br/>사망으로 더럽히지 말아야 한다<br/>',NULL,32713,7);
INSERT INTO stanza VALUES('K647','7','주의 이름 배반 말고 이기는 자 돼<br/>인내의 말 굳게 지켜 힘을 다하라<br/>',NULL,32714,8);
INSERT INTO stanza VALUES('K647','8','미지근함 버리고서 이기는 자 돼<br/>네 상태로 만족 말고 더욱 얻으라<br/>',NULL,32715,9);
INSERT INTO stanza VALUES('K647','9','주 여전히 부르신다 이기는 자를<br/>주께 충성 다 바쳐서 주 원함 이뤄<br/>',NULL,32716,10);
INSERT INTO stanza VALUES('K648','1','저 갈보리 보이니 난 실패 못하네 흑암의<br/>왕을 주가 거기서 이겼네 주 내게 이상 주사<br/>힘써 싸우게 해 주 능력 의지하여 이기는 자 되리<br/>',NULL,32717,1);
INSERT INTO stanza VALUES('K648','chorus','승리 승리 자 다 골고다 인해<br/>주 승리 인해 능-히 나 또한 이기는 자 되리<br/>',NULL,32718,2);
INSERT INTO stanza VALUES('K648','2','날 주가 불렀으니 난 실패 못하네 주 나를<br/>부르시어 싸우게 하시네 주여 힘 주옵소서<br/>담대케 하소서 주 충만하여 싸워 이기는 자 되게-<br/>',NULL,32719,3);
INSERT INTO stanza VALUES('K648','3','주 나를 이끄시니 난 실패 못하네 주 나를<br/>주와 함께 보좌에 앉게 해 주님의 전사로서<br/>검 들고 나아가 주 말씀으로 인해 이기게 하시네-<br/>',NULL,32720,4);
INSERT INTO stanza VALUES('K648','4','해 지는 이 시간에 난 실패 못하네 내 주가<br/>칭찬하실 그 날 이르도록 하늘의 새 능력을<br/>나에게 주시어 끝까지 날 이기게 하여 주옵소서-<br/>',NULL,32721,5);
INSERT INTO stanza VALUES('K649','1','악한 사탄 주의 자녀 대적하노니<br/>종군하는 교회들아 깨어있으라<br/>',NULL,32722,1);
INSERT INTO stanza VALUES('K649','chorus','전쟁 위해 주가 우릴 땅에 뒀으니<br/>주의 뜻을 이루도록 전장에 가자<br/>',NULL,32723,2);
INSERT INTO stanza VALUES('K649','2','흑암 군사 함께 모여 가까이 왔다<br/>주의 군대 교회들아 일어나라<br/>',NULL,32724,3);
INSERT INTO stanza VALUES('K649','3','주 예수의 진영 속에 배반 있으랴<br/>세상 사랑하고서야 어찌 싸우랴<br/>',NULL,32725,4);
INSERT INTO stanza VALUES('K649','4','어찌하여 두려워서 도전 못하나<br/>편안함만 구하는 건 교회 수치다<br/>',NULL,32726,5);
INSERT INTO stanza VALUES('K649','5','주 위하며 어찌 사탄 도울 수 있나<br/>교회들아 그 누구와 연합하느냐<br/>',NULL,32727,6);
INSERT INTO stanza VALUES('K649','6','주의 업적 누리면서 이기는 자 돼<br/>교회들아 그 누구와 연합하느냐<br/>',NULL,32728,7);
INSERT INTO stanza VALUES('K649','7','주가 본래 전사시니 두려워 마라<br/>겁을 내면 어찌 주의 교회라 할까<br/>',NULL,32729,8);
INSERT INTO stanza VALUES('K649','8','주가 오늘 이기는 자 부르고 있다<br/>주 편에서 갑주 입고 전쟁터로 가<br/>',NULL,32730,9);
INSERT INTO stanza VALUES('K65','1','영광스런 능력의 이름 그 속으로 피 - 하네<br/>높이 올려 찬 - 양하세 승리의 이름 - 예수<br/>',NULL,32731,1);
INSERT INTO stanza VALUES('K65','2','축복의 주 능력의 구주 내 모든 필요 - 채워<br/>주의 이름 호 - 흡함이 참 생명을 마심일세<br/>',NULL,32732,2);
INSERT INTO stanza VALUES('K65','3','영광스런 능력의 이름 천지가 다 선포하네<br/>죄 사함을 받은 자만이 이름 향기 알 수 있네<br/>',NULL,32733,3);
INSERT INTO stanza VALUES('K65','4','예수 예수 소중한 이름 고통 속의 향 - 기요<br/>그 이름은 능 - 력의 칼 이로 이기며 - 사네<br/>',NULL,32734,4);
INSERT INTO stanza VALUES('K650','1','내 맘대로- 안가고 주의 인도 좇으면<br/>생수- 넘쳐 흐르-고 맘에 빛이 비취네<br/>',NULL,32735,1);
INSERT INTO stanza VALUES('K650','2','내 스스로- 택한 길 상을 받지 못하네<br/>주의- 위임 이뤄-야 주의 칭찬 받으리<br/>',NULL,32736,2);
INSERT INTO stanza VALUES('K650','3','내 뜻 따라- 보좌에 기도하지 않으리<br/>그의- 영의 탄식-이 깊은 필요 만지네<br/>',NULL,32737,3);
INSERT INTO stanza VALUES('K650','4','주가 필요- 말할 때 내가 싫다 한다면<br/>제단- 위에 예물-도 주를 만족게 못해<br/>',NULL,32738,4);
INSERT INTO stanza VALUES('K650','5','자아 향해- 죽고서 주와 함께 살 때에<br/>주가- 그분 자신-을 보상으로 주시리<br/>',NULL,32739,5);
INSERT INTO stanza VALUES('K651','1','저 멀고 험난한 타향에 날 가라고 하셔도<br/>오 주여 당신의 부름에 난 즐겨 응합니다<br/>난 주저하잖-고 기꺼이 주 순종하렵-니다<br/>그 어디나 주께서 가라시면 나 즐거이 갑니다<br/>',NULL,32740,1);
INSERT INTO stanza VALUES('K651','chorus','내 사랑의 주- 말씀대로 어디에나 가렵니다<br/>산이든 강이든 주의 말씀을 나 전하겠습니다<br/>',NULL,32741,2);
INSERT INTO stanza VALUES('K651','2','내 주가 외치라 부탁한 그 은혜의 복음을<br/>저 죄악 길 가는 자에게 나 외치겠습니다<br/>내 주께서 인-도하시면 그 길 어둡더-라도<br/>내 음성을 높이어 주의 복음 다 전하겠습니다<br/>',NULL,32742,3);
INSERT INTO stanza VALUES('K651','3','이 세상 광대한 들판에 내 밭이 있으리니<br/>거기서 주 위해 내 여생 다 허비하렵니다<br/>주 날 깊이 사-랑하심을 내 마음이 아-오니<br/>주 당신의 말씀에 순종하여 어디나 가렵니다<br/>',NULL,32743,4);
INSERT INTO stanza VALUES('K652','1','늘상 기다리고 있지 말고 일어나 장래 큰 일 꿈꾸지 말고<br/>지금 네게 닥친 여러 본분 다하라 네 몫을 지금 비추라<br/>',NULL,32744,1);
INSERT INTO stanza VALUES('K652','chorus','네 몫을 지금 비추라 네 몫을 지금 비추라 모든 상황<br/>어려워도 더욱 비추라 네 몫을 지금 비추라<br/>',NULL,32745,2);
INSERT INTO stanza VALUES('K652','2','너의 빛을 사람 앞에 지금 비추라 이는 주의 명령이시니<br/>죄인 흑암 떠나 빛을 찾아오도록 네 몫을 지금 비추라<br/>',NULL,32746,3);
INSERT INTO stanza VALUES('K652','3','보라 너의 곁에 방황하는 양 있다 다른 양을 찾지 말아라<br/>너의 곁에 있는 양을 회복시키고 주의 맘으로 동정해<br/>',NULL,32747,4);
INSERT INTO stanza VALUES('K652','4','항상 주와 교통하며 주를 찬양해 주의 영광 반사하여라<br/>네가 열렬하게 주를 사랑한다면 모두 다 감동되리라<br/>',NULL,32748,5);
INSERT INTO stanza VALUES('K652','5','구주 가까우니 새벽별이 뜨리라 주의 종들 상을 얻으리<br/>죄인 구원하고 성도 회복하려면 지금 이 시간 붙잡아<br/>',NULL,32749,6);
INSERT INTO stanza VALUES('K653','1','흐름 중 흐름 중 주 위해 일하세<br/>주의 뜻 따르며 주의 길 행하세 주 말씀 따라서<br/>주 능력 의지해 교회와 왕국을 위하여 섬기자<br/>',NULL,32750,1);
INSERT INTO stanza VALUES('K653','chorus','흐름 중 흐름 중 다함께 일하세<br/>흐름에 거하며 온 성도들과 협력해<br/>',NULL,32751,2);
INSERT INTO stanza VALUES('K653','2','흐름 중 흐름 중 주 위해 일하세<br/>생명 흐름 안에 주 말씀 따르세 혼자서 임의로<br/>하는 것 버리고 지체와 다함께 섬기며 신뢰해<br/>',NULL,32752,3);
INSERT INTO stanza VALUES('K653','3','흐름 중 흐름 중 주 위해 일하세<br/>교회와 성도와 말씀 빛 가운데 주 말씀 전하여<br/>생명을 공급해 주 계획 위하여 다 함께 전진해<br/>',NULL,32753,4);
INSERT INTO stanza VALUES('K654','1','신약 안의 모든 봉사 영 안에서 해야- 해<br/>의문으로 행할 때에 사망만을 가져와<br/>밖의 행함 버리고서 안의 행함 가지라<br/>영의 새로운 것으로 생명 주는 봉사해<br/>',NULL,32754,1);
INSERT INTO stanza VALUES('K654','2','밖의 교훈 따르잖고 속의 관유 따르-라<br/>밖의 형식 따르잖고 속의 비췸 의지해<br/>사람 규례 따르잖고 하늘 통제 따르라<br/>사람 결정 따르잖고 주의 계시 따르라<br/>',NULL,32755,2);
INSERT INTO stanza VALUES('K654','3','죽은 종교 주지 말고 사신 주만 공급-해<br/>헛된 신학 전파 말고 주의 풍성 살아 내<br/>교리 의문 지식 아닌 주를 메시지 삼아<br/>은사 형식 방법 아닌 주가 실재 되게 해<br/>',NULL,32756,3);
INSERT INTO stanza VALUES('K654','4','객관적인 경배 떠나 주를 직접 섬기-라<br/>객관적인 전파 떠나 주를 직접 표현해<br/>영과 생명으로 일해 죽은 문자 떠나서<br/>육체 자아 의지 말고 능력의 영 의지해<br/>',NULL,32757,4);
INSERT INTO stanza VALUES('K655','1','생명이 흘러나가야 참다운 봉사이니<br/>생활과 일 하-나돼야 참 열매 맺게 되네<br/>산 체험 안의 말씀이 사람을 살려 내니<br/>체험과 일치-되어야 능력의 말씀이라<br/>',NULL,32758,1);
INSERT INTO stanza VALUES('K655','2','그 영의 생명 열매가 참다운 사역이니<br/>포도나무의- 열매는 생명의 풍성일세<br/>주 나를 통해 역사해 그 생명 표현하고<br/>그 생명 모든- 풍성을 날 통해 나타내네<br/>',NULL,32759,2);
INSERT INTO stanza VALUES('K655','3','사람의 운동 아니요 성령의 감동일세<br/>바깥의 업적- 아니요 이면의 역사일세<br/>사람의 사업 아니요 생명의 유출이니<br/>날 위한 수고- 아니요 주 표현하는 걸세<br/>',NULL,32760,3);
INSERT INTO stanza VALUES('K655','4','내 계획 노력 버리고 내 목적 버리겠네<br/>주 나를 통해- 역사해 주 뜻만 이루도록<br/>내 어떠함과 소유를 다 죽음으로 넘겨<br/>주 나를 통해- 사시어 주 풍성 표현케 해<br/>',NULL,32761,4);
INSERT INTO stanza VALUES('K656','1','몸 안에서 봉사함이 주의 중한 뜻일세-<br/>단독으로 행치 말고 몸 안에서 섬기세<br/>',NULL,32762,1);
INSERT INTO stanza VALUES('K656','chorus','주의 원함 몸에 있네 몸과 함께 행하세-<br/>몸의 지체라면 응당 협력하여 섬기세<br/>',NULL,32763,2);
INSERT INTO stanza VALUES('K656','2','거듭나서 지체되어 주의 몸을 이루어-<br/>성도들과 협력하여 하나님을 섬기세<br/>',NULL,32764,3);
INSERT INTO stanza VALUES('K656','3','산 돌로서 건축되어 주의 몸을 이루어-<br/>제사장의 체계 되어 화목하게 주 섬겨<br/>',NULL,32765,4);
INSERT INTO stanza VALUES('K656','4','자기 위치 힘써 지켜 건축되어 봉사해-<br/>우리 봉사 모든 근거 몸의 본성에 있네<br/>',NULL,32766,5);
INSERT INTO stanza VALUES('K656','5','몸의 공급 받음으로 일과 직분 다하리-<br/>몸을 떠나 고립되면 기능 잃고 만다네<br/>',NULL,32767,6);
INSERT INTO stanza VALUES('K656','6','몸 안에서 섬길 때에 머리 풍성 누리리-<br/>지체 기능 다할 때에 주의 분량 갖게 돼<br/>',NULL,32768,7);
INSERT INTO stanza VALUES('K656','7','머리이신 주 붙들고 주를 통해 자라네-<br/>그에게서 공급받아 각 부분에 나눠줘<br/>',NULL,32769,8);
INSERT INTO stanza VALUES('K656','8','주여 내 몸 드리오니 나의 생각 변케 해-<br/>주 뜻 알고 몸을 통해 주 섬기게 하소서<br/>',NULL,32770,9);
INSERT INTO stanza VALUES('K657','1','주가 우리 만유 되는 제사장의 이 생활<br/>주가 우리 의식주요 기업 또 모든 것 돼<br/>',NULL,32771,1);
INSERT INTO stanza VALUES('K657','chorus','주가 우리 만유 되니 이 어떠한 복인가<br/>주가 우리의 의식주요 기업 또 모든 것 돼<br/>',NULL,32772,2);
INSERT INTO stanza VALUES('K657','2','제사장이 봉사할 때 입고 쓰는 모든 것<br/>주의 영광 아름다움 존귀 거룩함일세<br/>',NULL,32773,3);
INSERT INTO stanza VALUES('K657','3','하나님이 열납하는 제물인 주 바치며<br/>제사장은 주를 먹고 주를 충분히 맛봐<br/>',NULL,32774,4);
INSERT INTO stanza VALUES('K657','4','주를 입어 연합하여 밖에 주를 표현해<br/>주를 먹어 연합하여 안에 주가 충만해<br/>',NULL,32775,5);
INSERT INTO stanza VALUES('K657','5','거룩하고 영광스런 제사장의 거처는<br/>제사장들로 건축된 확장된 그리스도<br/>',NULL,32776,6);
INSERT INTO stanza VALUES('K657','6','제사장의 소유 기업 오직 그리스도요<br/>제사장의 모든 사물 그리스도뿐일세<br/>',NULL,32777,7);
INSERT INTO stanza VALUES('K658','1','교회 위해 봉사함이 하나님의 정한 뜻<br/>사도들이 행한 바요 사역의 한 길일세<br/>',NULL,32778,1);
INSERT INTO stanza VALUES('K658','chorus','우리들의 모든 봉사 교회 위한 것일세<br/>이는 주가 기뻐하는 온전하신 뜻일세<br/>',NULL,32779,2);
INSERT INTO stanza VALUES('K658','2','교회가 주 그릇됨이 하나님 계획이니<br/>우리 모든 봉사로써 주의 집을 건축해<br/>',NULL,32780,3);
INSERT INTO stanza VALUES('K658','3','은사 받은 모든 사람 주의 몸을 위하여<br/>주의 충만 세우도록 교회 건축해야 해<br/>',NULL,32781,4);
INSERT INTO stanza VALUES('K658','4','모든 은사 모든 기능 주의 몸을 위하며<br/>모든 사역 성령 능력 주의 몸을 위하네<br/>',NULL,32782,5);
INSERT INTO stanza VALUES('K658','5','복음 전파 교도 목양 모두 몸을 위하며<br/>구제하고 다스림도 모두 몸을 위하네<br/>',NULL,32783,6);
INSERT INTO stanza VALUES('K658','6','모든 사역 교회 위해 사역 자체 안 위해<br/>모든 등대 교회일 뿐 어떤 사역 아니네<br/>',NULL,32784,7);
INSERT INTO stanza VALUES('K658','7','이는 우릴 하나 안에 보존하여 주시고<br/>나의 동기 시험하여 나의 목적 바꾸네<br/>',NULL,32785,8);
INSERT INTO stanza VALUES('K658','8','일에서나 분열에서 주여 나를 구원해<br/>교회 위해 수고하며 살게 하여 주소서<br/>',NULL,32786,9);
INSERT INTO stanza VALUES('K659','1','하나님과 사람에게 참된 봉사 하려면-<br/>풍성한 그리스도를 공급해야 한다네<br/>',NULL,32787,1);
INSERT INTO stanza VALUES('K659','chorus','풍성하신 그리스도 넘치도록 공급해<br/>그를 우리 제물 삼아 하나님을 섬기네<br/>',NULL,32788,2);
INSERT INTO stanza VALUES('K659','2','좋은 땅의 그 풍성을 하나님께 드렸듯-<br/>우리 또한 누린 수확 주께 드려야 하네<br/>',NULL,32789,3);
INSERT INTO stanza VALUES('K659','3','좋은 땅은 그리스도 우린 그를 경작해-<br/>넘치도록 거두어서 사람들과 나누리<br/>',NULL,32790,4);
INSERT INTO stanza VALUES('K659','4','그리스도 붙듦으로 자라면서 기능 다해<br/>주를 받고 나눔으로 그의 몸을 섬기리<br/>',NULL,32791,5);
INSERT INTO stanza VALUES('K659','5','교통 간증 말씀 사역 모든 봉사 도움들-<br/>모두 주를 전람하고 공급하는 것일세<br/>',NULL,32792,6);
INSERT INTO stanza VALUES('K66','1','오 달콤하 - 고 - 향기로 - 운 주 예수의 그 - 이 - 름<br/>나의 모든 고통 - 위로하며 찬미 - 케 하 - 네<br/>',NULL,32793,1);
INSERT INTO stanza VALUES('K66','chorus','오 아름답 - 고 - 높은 구 - 주 날 위하여 오 - 셨 - 네<br/>피를 흘려 죽임 - 당하시어 날 구 - 속했 - 네<br/>',NULL,32794,2);
INSERT INTO stanza VALUES('K66','2','오 하나님 - 의 - 형상인 - 주 사람 아들 되 - 셨 - 네<br/>자신 비어 종의 - 형체 입어 날 후사 되게 - 해<br/>',NULL,32795,3);
INSERT INTO stanza VALUES('K66','3','오 생명이 - 요 - 빛이신 - 주 진리요 또 길 - 일 - 세<br/>오늘 내 맘에서 - 왕이 되셔 날 인 - 도하 - 네<br/>',NULL,32796,4);
INSERT INTO stanza VALUES('K66','4','귀하고 귀 - 한 - 나의 구 - 주 항상 나와 친 - 근 - 해<br/>나의 근심 모든 - 답답함을 다 제 - 하시 - 네<br/>',NULL,32797,5);
INSERT INTO stanza VALUES('K66','5','주 다시 오 - 셔 - 나를 그 - 와 함께 안식케 - 하 - 리<br/>나의 천한 몸을 - 영광스런 몸으로 변케 하리<br/>',NULL,32798,6);
INSERT INTO stanza VALUES('K66','chorus','오 기쁨의 - 주 예수 예 - 수 영광스런 나 - 의 - 주<br/>나의 영광이신 - 예수 이름 영영 - 찬미 - 해<br/>',NULL,32799,7);
INSERT INTO stanza VALUES('K660','1','남은 세월 짧-으니 인생길 곧 끝나리<br/>머지 않아 우리는 하늘 왕을 만나리<br/>구주 오실 때-까지 항상 부지런하라<br/>',NULL,32800,1);
INSERT INTO stanza VALUES('K660','2','냉담하지 말-고서 힘써 주를 섬기라<br/>십자가를 지고서 주 위해 고난 받아<br/>들림받는 날-까지 변치 말고 섬기라<br/>',NULL,32801,2);
INSERT INTO stanza VALUES('K660','3','악한 영들 내-쫓고 흑암 세력 몰아내<br/>위험 곤란 닥쳐도 후퇴하지 말아라<br/>기도 항상 힘-쓰며 굳게 서서 싸우라<br/>',NULL,32802,3);
INSERT INTO stanza VALUES('K660','4','시간 살과 같-으니 속히 위로 얻으리<br/>주가 나를 지키사 순종하게 하시리<br/>주님 오실 때-까지 항상 깨어 예비해<br/>',NULL,32803,4);
INSERT INTO stanza VALUES('K660','5','시험받을지-라도 깨어 예비하겠네<br/>체면 깎일지라도 항상 예비하겠네<br/>“주여 지금 오-소서”기도할 수 있도록<br/>',NULL,32804,5);
INSERT INTO stanza VALUES('K661','1','어둔 밤 쉬 되리니 네 직분 지켜서<br/>찬 이슬 맺힐 때에 즉시 일어나<br/>해돋는 아침부-터 힘써서 일하라<br/>일할 수 없는 밤이 속히 오리라<br/>',NULL,32805,1);
INSERT INTO stanza VALUES('K661','2','어둔 밤 쉬 되리니 네 직분 지켜서<br/>일 할때 일하면서 놀지 말아라<br/>낮에는 골몰하나 쉴 때도 오겠네<br/>일할 수 없는 밤이 속히 오리라<br/>',NULL,32806,2);
INSERT INTO stanza VALUES('K661','3','어둔 밤 쉬 되리니 네 직분 지켜서<br/>지는 해 비낀 볕에 힘써 일하고<br/>그 빛이 다하여서 어둡게 되어도<br/>네 할 수 있는 대로 힘써 일하라<br/>',NULL,32807,3);
INSERT INTO stanza VALUES('K662','1','영광스런 복음전파 생명의 넘쳐 흐름<br/>우리의 산 간증으로 죄인들 구원 받네<br/>',NULL,32808,1);
INSERT INTO stanza VALUES('K662','chorus','주여 내게 생명 흘러 주 표현케 하소서<br/>당신의 산 그릇되어 생명 전케 하소서<br/>',NULL,32809,2);
INSERT INTO stanza VALUES('K662','2','생명 흘러 사람들이 믿고 순종하겠네<br/>생명 공급 흐름으로 주를 영접하겠네<br/>',NULL,32810,3);
INSERT INTO stanza VALUES('K662','3','나는 포도나무 가지 주님 안에 거하여<br/>생명 흘러 사람에게 주를 분배하겠네<br/>',NULL,32811,4);
INSERT INTO stanza VALUES('K662','4','내 온 생활 복음 전해 주의 번성 이루리<br/>진리 생명 나타내어 생명 열매 맺겠네<br/>',NULL,32812,5);
INSERT INTO stanza VALUES('K663','1','믿는이들아 속히 온 땅에 가 사람들에게 주 사랑 알려<br/>누구도 멸망하기 원치 않는 주님의 갈망 알게 하여라<br/>',NULL,32813,1);
INSERT INTO stanza VALUES('K663','chorus','죄인 구하는 좋은 소식 화평의 복-음을 전파하여라<br/>',NULL,32814,2);
INSERT INTO stanza VALUES('K663','2','천만의 사람 죄에 앉아 있고 늘 묶여 마귀 섬기고 있다<br/>네 구주 이미 승리 하셨는데 왜 이 소식을 알리지 않나<br/>',NULL,32815,3);
INSERT INTO stanza VALUES('K663','3','누구나 주가 죄의 속박에서 능히 구원해 낼 수 있으니<br/>어떠한 난관 닥친다 하여도 주 예수 믿게 해야 하겠네<br/>',NULL,32816,4);
INSERT INTO stanza VALUES('K663','4','세상의 모든 족속 나라에게 나가서 은혜 전파해야 해<br/>하나님께서 육신 되어 죽고 우리를 거듭나게 한 것을<br/>',NULL,32817,5);
INSERT INTO stanza VALUES('K663','5','헌신한 자들 황무지로 갈 때 물질을 드려 복음 도우라<br/>주 축복으로 널리 전파되게 기도로 함께 동역하여라<br/>',NULL,32818,6);
INSERT INTO stanza VALUES('K663','6','주께서 속히 다시 오실 것을 기억하고서 기회 잡으라<br/>게으름으로 멸망하게 될까 주 멀리하게 될까 두려워<br/>',NULL,32819,7);
INSERT INTO stanza VALUES('K664','1','수다한 영혼이 멸망한다<br/>사랑의 마음을 소멸치 말고<br/>금과 은 중하게 생각말고<br/>지금 곧 일어나 영혼 구하라<br/>왜 사랑의 마음 닫고 있나?<br/>',NULL,32820,1);
INSERT INTO stanza VALUES('K665','1','그리스도 공급하라 말-로만 하지 말고<br/>생활 통해 주 공급하라 죄에 매인 자들에게<br/>',NULL,32821,1);
INSERT INTO stanza VALUES('K665','chorus','그리스도 공급하라 멸망하는 세상 향해<br/>주를 살고 또 누림으로 주가 표현되게 하라<br/>',NULL,32822,2);
INSERT INTO stanza VALUES('K665','2','우리들이 얻은 주님 귀한 주님 공급하라<br/>친구들과 친척에게 그리스도 분배하라<br/>',NULL,32823,3);
INSERT INTO stanza VALUES('K665','3','우리들이 누린 주님 친구에게 공급하라<br/>참 자랑과 축복이신 그리스도 나눠 주라<br/>',NULL,32824,4);
INSERT INTO stanza VALUES('K665','4','우리 생명 만유 되신 그리스도 공급하라<br/>주의 초월 맛보도록 그리스도 분배하라<br/>',NULL,32825,5);
INSERT INTO stanza VALUES('K666','1','재료를 모아 주의 전 위해 친척과 친구 주께 돌이켜<br/>죄악을 떠나 멸망 피하여 양떼로 돌아오게 권-하라<br/>',NULL,32826,1);
INSERT INTO stanza VALUES('K666','2','재료를 모아 주의 전 위해 이 세상 사람들을 구하라<br/>사탄의 흑암 속임수에서 세상의 얽매임서 구-하라<br/>',NULL,32827,2);
INSERT INTO stanza VALUES('K666','3','재료를 모아 주의 전 위해 탕자를 주의 품에 이끌라<br/>사람 해치는 마귀 타파해 포로 된 죄수 돌아오-게 해<br/>',NULL,32828,3);
INSERT INTO stanza VALUES('K666','4','재료를 모아 주의 전 위해 주 외쳐 몸의 입장 위에서<br/>성도와 같은 영과 혼 되어 복음의 나팔 높이 불-어라<br/>',NULL,32829,4);
INSERT INTO stanza VALUES('K667','1','새벽부터 우리 주의 사랑 안에 저녁까지 씨를 뿌려봅시다<br/>차차 열매 익어 곡식 거둘때에 기쁨으로 단을 가져오리라<br/>',NULL,32830,1);
INSERT INTO stanza VALUES('K667','chorus','거두리로다 거두리로다 기쁨으로 단을 거두리로다<br/>거두리로다 거두리로다 기쁨으로 단을 거두리로다<br/>',NULL,32831,2);
INSERT INTO stanza VALUES('K667','2','비가 오는 것과 바람 부는 것을 겁내지 말고서 뿌려봅시다<br/>열매 모두 익어 곡식 거둘 때에 기쁨으로 단을 가져오리라<br/>',NULL,32832,3);
INSERT INTO stanza VALUES('K667','3','씨를 뿌리면서 나지 아니할까 염려하며 마음 졸일지라도<br/>나중 예수께서 칭찬하시리니 기쁨으로 단을 가져오리라<br/>',NULL,32833,4);
INSERT INTO stanza VALUES('K668','1','빈손 들-고 주님 얼굴 어찌 대-할 수 있나<br/>어찌 주-께 드릴 열매 하나 없을 수 있나<br/>',NULL,32834,1);
INSERT INTO stanza VALUES('K668','chorus','두 손 비-어 빈 손으로 주를 만-날 수 있나<br/>그리스도께 한 사람도 인도하지 못한 나<br/>',NULL,32835,2);
INSERT INTO stanza VALUES('K668','2','오늘 그-냥 지나가면 어떤 수-치당할지<br/>나의 빈-손 생각할 때 근심 구름 날 덮네<br/>',NULL,32836,3);
INSERT INTO stanza VALUES('K668','3','낭비한 세월 이제라도 되찾을- 수 있다면<br/>아낌없-이 주께 드려 주의 뜻을 좇겠네<br/>',NULL,32837,4);
INSERT INTO stanza VALUES('K668','4','성도들-아 낮을 틈타 속히 복-음전하라<br/>죽음의- 밤 오기 전에 힘써 영혼 구하라<br/>',NULL,32838,5);
INSERT INTO stanza VALUES('K669','1','하늘서 구주 날 위-해 간구해<br/>참 친근하고 사랑스러운 주<br/>날 언제나 돌보는 깊-은 사랑<br/>오 내 구주가 네 구주 되기원해<br/>',NULL,32839,1);
INSERT INTO stanza VALUES('K669','chorus','널 위하여 지금 난 기도 드린다<br/>내 주가 널 향해 구원- 베풀 길<br/>',NULL,32840,2);
INSERT INTO stanza VALUES('K669','chorus','널 위하여 그분이 간구하신다<br/>내 주가 또한 널 구원-하시리<br/>',NULL,32841,3);
INSERT INTO stanza VALUES('K669','2','광명의 집에 거하-시는 천부<br/>영원한 소망 내게 허락했네<br/>곧 하늘에 날 이끌면- 주 만나리<br/>오 너 또한 더불어 가기 원해<br/>',NULL,32842,4);
INSERT INTO stanza VALUES('K669','3','나에게 기쁨 넘쳐- 흘러남은<br/>내 구주께서 내 죄 담당하고<br/>내 안에서 지금 살아-계심이라<br/>오 너 또한 이 기쁨 얻기 원해<br/>',NULL,32843,5);
INSERT INTO stanza VALUES('K669','4','잔잔한 호수 같은- 평안 있네<br/>세상이 모르는 참 평안 있네<br/>주 예수님 평안의 근-원이시니<br/>오 너 또한 이 평강 얻기 원해<br/>',NULL,32844,6);
INSERT INTO stanza VALUES('K669','5','주 너를 구원할 때- 너도 전해<br/>널 주께서 어떻게 구원했나<br/>또 주님께 간구해 그-들의 구원<br/>주 네 간구 여전히 들으시리<br/>',NULL,32845,7);
INSERT INTO stanza VALUES('K67','1','달콤한 그 이름 땅에 다시 없다네 하늘에도 다시 없다네<br/>영광을 떠나서 주가 세상 오실 때 하나님이 주신 그 이름<br/>',NULL,32846,1);
INSERT INTO stanza VALUES('K67','chorus','즐거웁게 우린 - 불 - 러 그리스도 주 예수<br/>이보다 달콤한 이름 다시 없다네 하나님의 아들 주 예수<br/>',NULL,32847,2);
INSERT INTO stanza VALUES('K67','2','사람들 그분을 나무 위에 달 때에 그 이름도 함께 달았네<br/>천하가 모두 다 감상할 수 있겠네 그분 향한 우리의 사랑<br/>',NULL,32848,3);
INSERT INTO stanza VALUES('K67','3','그분이 오르사 보좌 위에 앉을 때 하나님이 주신 그 이름<br/>모두가 무릎을 꿇고 경배드리네 모든 입이 주라 시인해<br/>',NULL,32849,4);
INSERT INTO stanza VALUES('K67','4','주님의 이름과 비교할 것 없겠네 그의 이름 은혜 넘치네<br/>어제도 오늘도 변치 않는 그 이름 영원토록 동일한 이름<br/>',NULL,32850,5);
INSERT INTO stanza VALUES('K670','1','예비하고 예비해 하나님을 만날 것<br/>회개하고 믿으라 예비하여라<br/>회개하고 믿음으로 구원받으라<br/>',NULL,32851,1);
INSERT INTO stanza VALUES('K670','2','예비하고 예비해 하나님을 만날 것<br/>죄악 모두 벗고서 예비하여라<br/>죄악 벗고 새로웁게 변화되어라<br/>',NULL,32852,2);
INSERT INTO stanza VALUES('K670','3','예비하고 예비해 하나님을 만날 것<br/>몸과 마음 다 바쳐 예비하여라<br/>몸과 마음 다 바치라 주께 드리라<br/>',NULL,32853,3);
INSERT INTO stanza VALUES('K671','1','주 이미 속죄 이뤘네 참말 놀라운 구주<br/>비싼 값 주고 속했네 참말 놀라운 구주<br/>',NULL,32854,1);
INSERT INTO stanza VALUES('K671','chorus','참말 놀라운 구주 내 구주 주 예수<br/>참말 놀라운 구주 내 주 예수님<br/>',NULL,32855,2);
INSERT INTO stanza VALUES('K671','2','죄 씻는 보혈 찬양해 참말 놀라운 구주<br/>난 하나님과 화목해 참말 놀라운 구주<br/>',NULL,32856,3);
INSERT INTO stanza VALUES('K671','3','주 나의 죄들 씻었네 참말 놀라운 구주<br/>내 맘 속에서 왕 되신 참말 놀라운 구주<br/>',NULL,32857,4);
INSERT INTO stanza VALUES('K671','4','늘 나와 친근하시네 참말 놀라운 구주<br/>날 신실하게 지키네 참말 놀라운 구주<br/>',NULL,32858,5);
INSERT INTO stanza VALUES('K671','5','늘 승리 능력 주시네 참말 놀라운 구주<br/>난 이기고도 남겠네 참말 놀라운 구주<br/>',NULL,32859,6);
INSERT INTO stanza VALUES('K671','6','내 몸과 맘을 드리네 참말 놀라운 구주<br/>세상은 날 못 빼앗아 참말 놀라운 구주<br/>',NULL,32860,7);
INSERT INTO stanza VALUES('K672','1','하늘에 찬미가 충만한 그날 온 세상 죄악에 빠졌을 때<br/>주 예수 나셔서 이 땅에 거해 하나님 광채를 나타냈네<br/>',NULL,32861,1);
INSERT INTO stanza VALUES('K672','chorus','날 사랑하사 구원 하시려 내 모든 죄지고 죽으셨네<br/>날 의롭게 하려 부활 하신 주 그날에 오셔 날 올리시리<br/>',NULL,32862,2);
INSERT INTO stanza VALUES('K672','2','사람들이 주를 갈보리 산에 나무에 못 박아 제하던 날<br/>하나님의 매에 맞으신 주님 나의 죄 담당한 나의 구주<br/>',NULL,32863,3);
INSERT INTO stanza VALUES('K672','3','모두 다 주님을 버리던 그날 주님의 고통이 그치던 날<br/>천사가 그 밤에 무덤 지켰네 나의 참 소망된 나의 구주<br/>',NULL,32864,4);
INSERT INTO stanza VALUES('K672','4','무덤이 내 주를 잡지 못한 날 무덤 문 막은 돌 굴러갔네<br/>주 부활하시고 사망 이겼네 하늘에 오르사 내 주 됐네<br/>',NULL,32865,5);
INSERT INTO stanza VALUES('K672','5','나팔소리 크게 울려 날 그날 주 영광 하늘에 비취리니<br/>놀라운 그 날에 내 사랑 오리 영광의 내 구주 예수 내 주<br/>',NULL,32866,6);
INSERT INTO stanza VALUES('K673','1','예수 내 구주 말 구유에 나<br/>간고의 사람 돼 고통 견뎌<br/>놀라운 주 예수 그가 나를 찾고 또 찾았네<br/>그가 날 찾았네 찾고 또 찾았네<br/>놀라운 주 예수 그가 나를 찾고 또 찾았네<br/>',NULL,32867,1);
INSERT INTO stanza VALUES('K673','2','예수 내 구주 갈보리에서<br/>내 죄빚 다 갚고 날 해방해<br/>기묘한 주 예수 그가 나를 위하여 죽었네<br/>그는 날 위하여 날 위해 죽었네<br/>기묘한 주 예수 그가 나를 위하여 죽었네<br/>',NULL,32868,2);
INSERT INTO stanza VALUES('K673','3','예수 내 구주 늘 살아 계셔<br/>방황하는 나를 부르시네<br/>나는 거절해도 끊임없이 부르고 부르네<br/>그가 날 부르네 부르고 부르네<br/>나는 거절해도 끊임없이 부르고 부르네<br/>',NULL,32869,3);
INSERT INTO stanza VALUES('K673','4','예수 내 구주 곧 다시 오리<br/>택하신 백성을 맞으려고<br/>달콤한 이 약속 이루려고 주 나를 부르네<br/>그가 날 맞으리 날 맞아 들이리<br/>하늘로부터 주 오시리라 주 나를 부르네<br/>',NULL,32870,4);
INSERT INTO stanza VALUES('K674','1','위대하고도 친근한 의사인 내 주 예수<br/>죄 상처 치료하시고 근심을 풀어 주네<br/>',NULL,32871,1);
INSERT INTO stanza VALUES('K674','chorus','십-자가에 달려서 네- 죄 모두 지셨네<br/>주 널 치료하시니 속히 주께 오라<br/>',NULL,32872,2);
INSERT INTO stanza VALUES('K674','2','죄 많아도 사함 받아 주 예수께만 오면<br/>양심도 평안 얻으리 주 예수께만 오면<br/>',NULL,32873,3);
INSERT INTO stanza VALUES('K674','3','죄로 맘 더럽혀진 자 주 예수께로 오라<br/>온 몸에 질병 있는 자 주 예수께로 오라<br/>',NULL,32874,4);
INSERT INTO stanza VALUES('K674','4','근심과 고통 있는 자 인생의 맛 잃은 자<br/>주님께 와서 얻으라 치료하는 생수를<br/>',NULL,32875,5);
INSERT INTO stanza VALUES('K674','5','나 이미 주를 영접해 주의 치료 받았네<br/>죽임을 당한 어린 양 그분께 영광 돌려<br/>',NULL,32876,6);
INSERT INTO stanza VALUES('K674','chorus','그-가 묶여 상하여 나-는 낫고 해방돼<br/>그가 생명 잃어서 나는 생명 얻네<br/>',NULL,32877,7);
INSERT INTO stanza VALUES('K674','6','날 구원하신 주 이름 사랑하고 사랑해<br/>내 고통 제하는 이름 귀한 이름 주 예수<br/>',NULL,32878,8);
INSERT INTO stanza VALUES('K674','chorus','향-기로운 그 이름 존-귀하신 그 이름<br/>이름 중에 뛰어난 보배로운 예수<br/>',NULL,32879,9);
INSERT INTO stanza VALUES('K674','7','주 앞에 들림받을 때 친히 내 주를 볼 때<br/>영광 중에 찬양하리 보배로운 주 예수<br/>',NULL,32880,10);
INSERT INTO stanza VALUES('K675','1','이 영광-의 복음 소식 믿기 간단해<br/>어제 오-늘 영원토록 변함 없-는 주<br/>죄인 구-원하시기-를 기뻐하시고<br/>풍파 속-에 빠진 영혼 건져주시네<br/>',NULL,32881,1);
INSERT INTO stanza VALUES('K675','chorus','어제 오-늘 영원토-록 변함없-는 주<br/>만사만-물 다 변해-도 주 변치 않네<br/>변함없는 주 변함없-는 주<br/>만사만-물 다 변해도 주 변치 않네<br/>',NULL,32882,2);
INSERT INTO stanza VALUES('K675','2','주가 죄-인 친구 되사 지금 부르니<br/>그 발 앞-에 나오는 자 버리지- 않네<br/>그가 내-게 하신 말-씀 놀라운 은혜<br/>네 죄 모-두 사했으니 평안히 가라<br/>',NULL,32883,3);
INSERT INTO stanza VALUES('K675','3','주가 세-상 계실 때에 각색 병든 자<br/>치료하-던 그 능력은 변함 없-으니<br/>그의 약-속하신 말-씀 믿기만 하면<br/>오늘 또-한 그 능력이 역사하겠네<br/>',NULL,32884,4);
INSERT INTO stanza VALUES('K675','4','엠마오- 길 두 제자와 동행하던 주<br/>오늘 또-한 내 인생길 같이하-시네<br/>주 뵙겠-네 주 뵙겠-네 주 곧 오시리<br/>지체하-지 않으시리 주 곧 오시리<br/>',NULL,32885,5);
INSERT INTO stanza VALUES('K676','1','큰 기쁨의 소식은 주 예수 큰 구원<br/>널리 전할 소식은 주 예수 큰 구원<br/>길이 험하다 말고 모든 사람에게 가<br/>주의 명령 따라서 각처에 전하라!<br/>',NULL,32886,1);
INSERT INTO stanza VALUES('K676','2','가난한 자에게나 부한 자에게나<br/>가서 말할 소식은 주 예수 큰 구원<br/>모든 섬이 노래해 모든 바다 반향해<br/>세상 모두 선포해 주 예수 큰 구원<br/>',NULL,32887,2);
INSERT INTO stanza VALUES('K676','3','십자가로 이루신 주 예수 큰 구원<br/>보혈로써 말하는 주 예수 큰 구원<br/>예수 죽으심으로 형벌 면케 하셨네<br/>예수 부활함으로 생명을 분배해<br/>',NULL,32888,3);
INSERT INTO stanza VALUES('K676','4','사람 구원하셨네 주 예수 큰 구원<br/>사람 마음 위로해 주 예수 큰 구원<br/>피로한 자들에게 안식 얻게 하시네<br/>의심 말고 믿으라 주 예수 큰 구원<br/>',NULL,32889,4);
INSERT INTO stanza VALUES('K676','5','전하고 또 전하라 주 예수 큰 구원<br/>세상 모든 이에게 큰 구원 말하라<br/>풍성하신 주 은혜 널리 널리 전파해<br/>죄가 깊고 중해도 은혜를 받으리<br/>',NULL,32890,5);
INSERT INTO stanza VALUES('K677','1','풍성하신 주님 십자가 졌네<br/>너를 위해 수치 고통 겪고서<br/>목숨 버린 주를 받아 들여라<br/>',NULL,32891,1);
INSERT INTO stanza VALUES('K678','1','구원 얻을 이름 예수 외엔 없네<br/>온 천하 만민 중에 주 외에 다시 없네<br/>구원 얻을 만한 다른 이름 없네<br/>',NULL,32892,1);
INSERT INTO stanza VALUES('K679','1','울어도 못하네 눈물 많이 흘려도<br/>겁을 없게 못하고<br/>죄를 씻지 못하니 울어도 못하네<br/>',NULL,32893,1);
INSERT INTO stanza VALUES('K679','chorus','십자가에 달려서 예수 고난 보셨네<br/>나를 구원 하실 이 예수밖에 없네<br/>',NULL,32894,2);
INSERT INTO stanza VALUES('K679','2','힘써도 못하네 말과 뜻과 행실이<br/>깨끗하고 착해도<br/>다시 나게 못하니 힘써도 못하네<br/>',NULL,32895,3);
INSERT INTO stanza VALUES('K679','3','참아도 못하네 할수 없는 죄인이<br/>흉한 죄에 빠져서<br/>어찌 아니 죽을까 참아도 못하네<br/>',NULL,32896,4);
INSERT INTO stanza VALUES('K679','4','믿으면 하겠네 주 예수만 믿어서<br/>그 은혜를 힘입고<br/>오직 주께 나가면 영원 생명 얻네<br/>',NULL,32897,5);
INSERT INTO stanza VALUES('K68','1','죽임 당한 어리신 양 그리스도 높여<br/>이 죄인 친구 영광 주 다 찬양합시다<br/>',NULL,32898,1);
INSERT INTO stanza VALUES('K68','chorus','존귀한 이름 찬송합시다 주의 존귀한 이름을<br/>존귀한 이름 찬송합시다 주의 존귀한 이름을<br/>할렐루야 할렐루야 찬송 영광을 돌리세<br/>할렐루야 할렐루야 찬송 영광을 돌리세<br/>',NULL,32899,2);
INSERT INTO stanza VALUES('K68','2','오 뛰어나신 주 이름 다 찬송합시다<br/>온 천지 생명들아 다 주 찬송합시다<br/>',NULL,32900,3);
INSERT INTO stanza VALUES('K68','3','저 천사들도 경배해 온 만유와 함께<br/>주 그리스도 어린 양 다 찬양합시다<br/>',NULL,32901,4);
INSERT INTO stanza VALUES('K68','4','은혜를 받은 죄인들 다 크게 환호해<br/>피 흘려 구속 이루신 주 찬송합시다<br/>',NULL,32902,5);
INSERT INTO stanza VALUES('K68','5','권위와 지혜 풍성과 존귀를 돌리세<br/>영광과 왕권 영원히 구주께 돌리세<br/>',NULL,32903,6);
INSERT INTO stanza VALUES('K680','1','오 놀라운 사랑 구주의 사랑 주께서 갈보리 가셨네<br/>보좌 떠나 고초 환난 당하며 나 위하여 그 길 가셨네<br/>나 위하여 갈보리에 가셨네 나 위하여 나위하여<br/>나 위하여 가셨네 저 갈보리 나 위해 가셨네<br/>',NULL,32904,1);
INSERT INTO stanza VALUES('K680','2','참담한 내 구주 가시관 쓰고 손과 발에 못 박히셨네<br/>상처 투성이의 매 맞은 몸에 주홍 같은 피가 흐르네<br/>날 사랑해 달리셨네 내 주님 날 사랑해 날 사랑해<br/>날 사랑해 달리셨네 내 주님 날 사랑하므로<br/>',NULL,32905,2);
INSERT INTO stanza VALUES('K680','3','온 땅 어두웠네 진노 임하여 하나님이 그를 심판해<br/>그가 내 죄 대신 담당하므로 하나님의 공의 만족돼<br/>날 대신해 형벌 받고 죽었네 날 대신해 날 대신해<br/>날 대신해 형벌 받고 죽었네 저 십자가에서<br/>',NULL,32906,3);
INSERT INTO stanza VALUES('K680','4','무지하여 주를 거역하던 나 이제 갈보리의 주 보니<br/>나 위하여 주님 피흘리셨네 나는 이제 구속 받았네<br/>십자가에 피흘려 날 구속해 날 구속해 날 구속해<br/>십자가에 피흘려 날 구속해 날 자유케 했네<br/>',NULL,32907,4);
INSERT INTO stanza VALUES('K681','1','아 내 주님 십자가에 못 박혀 죽었네<br/>온 몸에 채찍 맞고서 가시관 쓰신 주<br/>',NULL,32908,1);
INSERT INTO stanza VALUES('K681','chorus','십자가 십자가 은혜의- 빛 볼 때<br/>나의 죄 중한 짐 풀렸네<br/>믿고 눈 맑아져 평안 넘쳐나네<br/>종일 기쁨이 충-만하네<br/>',NULL,32909,2);
INSERT INTO stanza VALUES('K681','2','내 죄 지려 십자가에 고통 당하셨네<br/>놀라운 긍휼과 은혜 측량할 수 없네<br/>',NULL,32910,3);
INSERT INTO stanza VALUES('K681','3','하나님이 모든 죄를 내 주께 돌렸네<br/>하나님이 영광 닫으니 온 땅이 어두워<br/>',NULL,32911,4);
INSERT INTO stanza VALUES('K681','4','죽으실 때 성전 안의 휘장이 갈라져<br/>하나님과 사람 사이 간격 없어졌네<br/>',NULL,32912,5);
INSERT INTO stanza VALUES('K681','5','그 옆구리 찔리므로 피와 물 흘렀네<br/>내 죄를 모두 씻고서 새 생명 주셨네<br/>',NULL,32913,6);
INSERT INTO stanza VALUES('K681','6','“다 이뤘다”외치시고 구원을 이룬 주<br/>그 음성에 내 슬픔이 찬양이 되었네<br/>',NULL,32914,7);
INSERT INTO stanza VALUES('K682','1','이- 세상 험하고 나 비록 약하나<br/>늘- 기도 힘쓰면 큰- 권능 얻겠네<br/>',NULL,32915,1);
INSERT INTO stanza VALUES('K682','chorus','주의 은혜로 대속하여서<br/>피와 같이 붉은 죄 눈 같이 희겠네<br/>',NULL,32916,2);
INSERT INTO stanza VALUES('K682','2','주-만이 더러움 깨끗이 씻으며<br/>날- 강하게 하실 능-력을 가졌네<br/>',NULL,32917,3);
INSERT INTO stanza VALUES('K682','3','구-원 얻을만한 선함이 없으나<br/>주- 사랑과 긍휼 이- 죄인 구했네<br/>',NULL,32918,4);
INSERT INTO stanza VALUES('K682','4','곧- 세상 떠나도 두려움 없으리<br/>내- 주님 내 죄빚 다- 갚으셨으니<br/>',NULL,32919,5);
INSERT INTO stanza VALUES('K682','5','그-날 하나님이 더 묻지 않으리<br/>주- 이미 날 위해 심-판 받았으니<br/>',NULL,32920,6);
INSERT INTO stanza VALUES('K683','1','주 예수 날 사랑하사 하늘로부터 오셨네<br/>기꺼이 자신을 비어 육신 되어 오셨다네<br/>',NULL,32921,1);
INSERT INTO stanza VALUES('K683','chorus','주 예수 오-셔서 날 위해 죽으셨네<br/>오, 나를 나를 위하여 주 예수 죽으셨네<br/>',NULL,32922,2);
INSERT INTO stanza VALUES('K683','2','비웃음 매 맞음 받고 수치 능욕당하셨네<br/>최후엔 십자가 위에 고통의 못 박히셨네<br/>',NULL,32923,3);
INSERT INTO stanza VALUES('K684','1','나의 죄를 씻기는 예수의 피밖에 없네<br/>다시 성케하기도 예수의 피밖에 없네<br/>',NULL,32924,1);
INSERT INTO stanza VALUES('K684','chorus','예수의 흘린 피 날 희게 하오니-<br/>귀하고 귀하다 예수의 피밖에 없네<br/>',NULL,32925,2);
INSERT INTO stanza VALUES('K684','2','나를 정케 하기는 예수의 피밖에 없네<br/>사죄하는 증거도 예수의 피밖에 없네<br/>',NULL,32926,3);
INSERT INTO stanza VALUES('K684','3','나의 죄 사하기는 예수의 피밖에 없네<br/>나는 공로 없도다 예수의 피밖에 없네<br/>',NULL,32927,4);
INSERT INTO stanza VALUES('K684','4','평안함과 소망은 예수의 피밖에 없네<br/>나의 양심 씻기는 예수의 피밖에 없네<br/>',NULL,32928,5);
INSERT INTO stanza VALUES('K684','5','영원토록 내 할 말 예수의 피밖에 없네<br/>나의 찬미 제목은 예수의 피밖에 없네<br/>',NULL,32929,6);
INSERT INTO stanza VALUES('K685','1','하나님 어린양 주 예수 죄인을 위해 죽으셨네<br/>그 피를 내게 뿌렸으니 멸망에서 넌 구원되리<br/>',NULL,32930,1);
INSERT INTO stanza VALUES('K685','chorus','이- 피 볼 때에 지-나 가리라<br/>이- 피 볼 때에 나는 널 지나서 가리라<br/>',NULL,32931,2);
INSERT INTO stanza VALUES('K685','2','죄인의 괴수 구하신 주 약속한 것을 이루시리<br/>하나님 지나가시리니 넌 용서함을 받으리라<br/>',NULL,32932,3);
INSERT INTO stanza VALUES('K685','3','장차 올 심판 피하고서 그 공의 앞에 누가 서랴<br/>주의 피 너를 가리시니 하나님 너를 지나가리<br/>',NULL,32933,4);
INSERT INTO stanza VALUES('K685','4','놀라운 긍휼 주의 사랑 거룩한 은혜 풍성하네<br/>피 뿌림 아래 평강 누려 하나님 너를 지나가리<br/>',NULL,32934,5);
INSERT INTO stanza VALUES('K685','chorus','어-린 양의 피 귀-한 그 보혈<br/>그- 피 보시고 하나님 지나서 가신다<br/>',NULL,32935,6);
INSERT INTO stanza VALUES('K686','1','샘-물과 같은 보혈은 임-마누엘 피-로-다<br/>이- 샘에 죄를 씻으면 정-하게 되겠네<br/>정-하게 되겠네- 정하게 되-겠-네<br/>이- 샘에 죄를 씻으면 정-하게 되겠네<br/>',NULL,32936,1);
INSERT INTO stanza VALUES('K686','2','저- 도적 회개하고서 이- 샘 에 씻-었-네<br/>저- 도적 같은 이 몸도 죄-씻기 원하네<br/>죄-씻기 원하네- 죄 씻기 원-하-네<br/>저- 도적 같은 이 몸도 죄- 씻기 원하네<br/>',NULL,32937,2);
INSERT INTO stanza VALUES('K686','3','죽-임을 당한 어린 양 피- 효능 영-원-해<br/>선-택한 백성 분별해 정-결케 하시네<br/>정-결케 하시네- 정결케 하-시-네<br/>선-택한 백성 영원히 정-결케 하시네<br/>',NULL,32938,3);
INSERT INTO stanza VALUES('K686','4','주-께서 해 받으시어 열-린 이 샘- 볼- 때<br/>구-속의 그 큰 사랑을 늘- 찬송하겠네<br/>늘- 찬송하겠네- 늘 찬송하-겠-네<br/>구-속의 그 큰 사랑을 늘- 찬송하겠네<br/>',NULL,32939,4);
INSERT INTO stanza VALUES('K687','1','죄에서 자유를 얻게 함은 보혈의 능력 주의 보혈<br/>시험을 이기는 승리되니 참 놀라운 능력이로다<br/>',NULL,32940,1);
INSERT INTO stanza VALUES('K687','chorus','주의 보혈 능력 있도다 주의 피 믿으오<br/>주의 보혈 그 어린 양의 매우 귀중한 피로다<br/>',NULL,32941,2);
INSERT INTO stanza VALUES('K687','2','육체의 정욕을 이길 힘은 보혈의 능력 주의 보혈<br/>정결한 마음을 얻게 하니 참 놀라운 능력이로다<br/>',NULL,32942,3);
INSERT INTO stanza VALUES('K687','3','눈보다 더 희게 맑히는 것 보혈의 능력 주의 보혈<br/>부정한 모든 것 맑히시니 참 놀라운 능력이로다<br/>',NULL,32943,4);
INSERT INTO stanza VALUES('K687','4','구주의 복음을 전할 제목 보혈의 능력 주의 보혈<br/>날마다 나에게 찬송 주니 참 놀라운 능력이로다<br/>',NULL,32944,5);
INSERT INTO stanza VALUES('K688','1','주의 깨끗게 하는 그 능력의 어린 양 피로써 씻었나<br/>주를 믿고 맘에 영접하여서 어린 양 보혈로 씻었나<br/>',NULL,32945,1);
INSERT INTO stanza VALUES('K688','chorus','예수의 피로써 능력의 피로써 씻었나<br/>어린 양의 피로 씻음 받고서 너의 옷 눈같이 희었나<br/>',NULL,32946,2);
INSERT INTO stanza VALUES('K688','2','죄 사하는 주의 은혜 받았나 어린 양 피로써 씻었나<br/>너를 위한 주의 죽음 인하여 너의 맘 평안해 졌는가<br/>',NULL,32947,3);
INSERT INTO stanza VALUES('K688','3','주님 다시 오실 때에 너의 옷 씻어서 정결해 졌는가<br/>영광 면류관을 쓸 수 있는가 어린 양 피로써 씻었나<br/>',NULL,32948,4);
INSERT INTO stanza VALUES('K688','4','갈보리샘 죄인 위해 흐르네 어린 양 피로써 씻었나<br/>더러운 옷 남겨 놓지 않았나 어린 양 피로써 씻었나<br/>',NULL,32949,5);
INSERT INTO stanza VALUES('K689','1','죄인 위하여 나-무에- 달려<br/>찢-기-신- 주 죄-인을 위해<br/>거저 피흘려 죄-빚 갚-았네<br/>',NULL,32950,1);
INSERT INTO stanza VALUES('K69','1','하늘과 땅과 땅 아래 모든 이름 보다<br/>뛰어난 예수의 이름 모 - 두가 존경해<br/>',NULL,32951,1);
INSERT INTO stanza VALUES('K69','2','사랑의 이름 주 예수 죄인에게 줬네<br/>두려움 정죄 쫓아내 하늘 평강 가져와<br/>',NULL,32952,2);
INSERT INTO stanza VALUES('K69','3','죄인의 사슬 푸시고 뱀 머리 깨뜨려<br/>능력으로 약함 삼켜 생명으로 구원해<br/>',NULL,32953,3);
INSERT INTO stanza VALUES('K69','4','모두가 함께 맛보네 그 풍성한 은혜<br/>그 가슴 속에 기대며 그 - 품을 누리네<br/>',NULL,32954,4);
INSERT INTO stanza VALUES('K69','5','영원히 의지할 이름 사랑스런 예수<br/>영원히 귀한 그 이름 늘 - 간증하겠네<br/>',NULL,32955,5);
INSERT INTO stanza VALUES('K690','1','하나님 아들 우리를 대신해 죽었네<br/>사랑의 길이 열렸네 은혜의 문이 열렸네<br/>이 사랑 거절 말고서 주께로 나오라<br/>',NULL,32956,1);
INSERT INTO stanza VALUES('K691','1','아름다운 은혜 우리 맘 위로해<br/>하늘에 화음 충만해 온 땅에 퍼지네<br/>',NULL,32957,1);
INSERT INTO stanza VALUES('K691','chorus','은혜의 구원 참 복음일세<br/>죄인 괴수 날 위해 주 예수 죽었네<br/>',NULL,32958,2);
INSERT INTO stanza VALUES('K691','2','주 안에 감추인 풍성한 은혜여<br/>날 위해 구속 이루고 날 해방하셨네<br/>',NULL,32959,3);
INSERT INTO stanza VALUES('K691','3','날 속량한 은혜 죄사함 얻게 해<br/>하나님 얼굴 대하며 평강 누리게 해<br/>',NULL,32960,4);
INSERT INTO stanza VALUES('K691','4','날 살려 주시고 주 성품 갖게 해<br/>날 주께 속하게 하며 흑암을 벗게 해<br/>',NULL,32961,5);
INSERT INTO stanza VALUES('K692','1','한 관원이 늦은 밤 주께 와서<br/>사람 사는 도리를 물었을 때<br/>주 진실로 그에게 대답했네“거듭나야 한다”<br/>',NULL,32962,1);
INSERT INTO stanza VALUES('K692','chorus','거듭나야- 한다 거듭나야- 한다<br/>주 예수님 진실로 대답했네“거듭나야 한다”<br/>',NULL,32963,2);
INSERT INTO stanza VALUES('K692','2','이 말씀에 모두 귀 기울이라<br/>주 예수의 엄숙한 말씀이니<br/>이 거룩한 분부를 존중하라“거듭나야 한다”<br/>',NULL,32964,3);
INSERT INTO stanza VALUES('K692','3','오 광명의 그 성에 들어가서<br/>구속받은 백성과 영광 누릴<br/>그 영원한 생명을 얻을 자는“거듭나야 한다”<br/>',NULL,32965,4);
INSERT INTO stanza VALUES('K692','4','주 예수님 나무에 달렸으니<br/>믿는 자는 영생을 얻게 되네<br/>회개하고 주 이름 믿을 때에 거듭나게 되리<br/>',NULL,32966,5);
INSERT INTO stanza VALUES('K692','chorus','거듭나게- 되리 거듭나게- 되리<br/>회개하고 주 이름 믿을 때에 거듭나게 되리<br/>',NULL,32967,6);
INSERT INTO stanza VALUES('K693','1','십자가에 못 박히니 나는 아담 벗었네<br/>그는 또한 성령으로 나의 생명되시어<br/>내 안에 사시네<br/>영광 영광 할렐루야 영광 영광 할렐루야<br/>영광 영광 할렐루야 내 생명되신 주<br/>',NULL,32968,1);
INSERT INTO stanza VALUES('K694','1','주는 생명 주는 부활 그가 다스리네<br/>죽음-으-로- -마귀- 멸-해- -<br/>이제는 영원-히 영-원히 사시-네<br/>이-제- 영원-히 사시네<br/>',NULL,32969,1);
INSERT INTO stanza VALUES('K694','2','영광스런 주의 생명 나 이미 얻었네<br/>흑암- 사-망- - 사라-졌-네- -<br/>죄악의 권세-도 다- 사라졌다-네<br/>이-제- 다 사-라졌다네<br/>',NULL,32970,2);
INSERT INTO stanza VALUES('K695','1','날 위해 죽은 구주 기묘해 이 정죄 받을 내게 손짓해<br/>주 재삼 말씀하길 믿으면 생명 얻으리라<br/>',NULL,32971,1);
INSERT INTO stanza VALUES('K695','chorus','참 복음 참 복음 와서 들으라<br/>참 복음 참 복음 주님 말씀해<br/>하나님 아들 이름 믿으면 영생 얻으리라<br/>',NULL,32972,2);
INSERT INTO stanza VALUES('K695','2','모든 죄 그가 대신 갚았고 더러움 모두 그가 씻었네<br/>사람이 그 이름만 믿으면 영생 얻으리라<br/>',NULL,32973,3);
INSERT INTO stanza VALUES('K695','3','내 죄가 주 믿는 것 못 막고 약해도 그 영 받을 수 있네<br/>참 영광 영화로움 아닌가 죽은 자 살아나<br/>',NULL,32974,4);
INSERT INTO stanza VALUES('K695','4','내 비록 흉하여도 믿으면 영원히 주 날 버리지 않네<br/>주 믿는 모든 사람 아시네 죽은 자 부활해<br/>',NULL,32975,5);
INSERT INTO stanza VALUES('K696','1','이 비밀을- 받는- 자는 주님과- 하나 돼<br/>영광 영광- 할렐루야 영광 영광- 할렐루야<br/>이 비밀을- 받는- 자는 주님과- 하나 돼<br/>',NULL,32976,1);
INSERT INTO stanza VALUES('K697','1','사람들이 악하여도 하나님은 버리잖네<br/>큰 소식! 참 비밀! 주와 사람 연합하네<br/>영원토록 주 하나님 사람들과 동거하리<br/>큰 소식! 참 비밀! 하나님은 사람 원해<br/>',NULL,32977,1);
INSERT INTO stanza VALUES('K698','1','우리 여기서 생수 마시네 주께서 주신 약-속의<br/>물-을 주 말씀하시기를 영원 목마르지 않으리<br/>참말 이 물 마시면 목마르지 않느냐<br/>그래 이 물 마시면 영원히 목마르지 않아<br/>이 물을 마시는 자 영원 목마르지 않으리<br/>',NULL,32978,1);
INSERT INTO stanza VALUES('K698','2','우리 여기서 생명떡 먹네 주님 공급한 말-씀의<br/>떡-을 주 말씀하시기를 영원 배고프지 않으리<br/>참말 이 떡 먹으면 배고프지 않느냐<br/>그래 이 떡 먹으면 영원히 배고프지 않아<br/>이 떡을 먹는 자는 영원 배고프지 않으리<br/>',NULL,32979,2);
INSERT INTO stanza VALUES('K698','3','우리 여기서 생기 마시네 이는 곧 성령 주-님<br/>자신일세 이 공기 마시는 자 영원 자유롭고 신선해<br/>참말 호흡하면은 답답함이 없느냐<br/>그래 호흡하면은 영원 자유롭고 신선해<br/>이 공기 마시는 자 영원 자유롭고 신선해<br/>',NULL,32980,3);
INSERT INTO stanza VALUES('K698','4','우리 여기서 생명 술 맛봐 주께서 물로 변-케하신<br/>술을 이 술을 마시는 자 영원 기쁨 한량 없으리<br/>참말 이 술 마시면 허무하지 않느냐<br/>그래 이 술 마시면 영원 기쁨 한량 없으리<br/>이 술을 마시는 자는 영원 기쁨 한량 없으리<br/>',NULL,32981,4);
INSERT INTO stanza VALUES('K698','5','주- 예수는 부활 왕일세 사망 이기고 다-시<br/>사셨으니 주 예수 믿는 자는 영원 죽지 않으리로다<br/>참말 예수 믿으면 영원 죽지 않느냐<br/>그래 예수 믿으면 영원히 죽지 않고 말고<br/>주 예수 믿는 자는 영원 죽지 않으리로다<br/>',NULL,32982,5);
INSERT INTO stanza VALUES('K699','1','너의 죄 흉악하나 눈과 같이 희겠네<br/>너의 죄 흉악하나 눈과 같이 희겠네<br/>죄의 빛 흉악하나 희게 되리라<br/>주홍 빛 같은 네 죄 주홍 빛 같은 네 죄<br/>눈과 같이 희겠네 눈과 같이 희겠네<br/>',NULL,32983,1);
INSERT INTO stanza VALUES('K699','2','악한 죄 벗으라고 주님 너를 부른다<br/>악한 죄 벗으라고 주님 너를 부른다<br/>하나님 크신 사랑 한이 없어라<br/>악한 죄 벗으라고 악한 죄 벗으라고<br/>주님 너를 부르네 주님 너를 부르네<br/>',NULL,32984,2);
INSERT INTO stanza VALUES('K699','3','너희 죄 사해 주사 기억도 안 하시네<br/>너희 죄 사해 주사 기억도 안 하시네<br/>불쌍한 사람들아 오라 하시네<br/>너희 죄 사해 주사 너희 죄 사해 주사<br/>기억도 안 하시네 기억도 안 하시네<br/>',NULL,32985,3);
INSERT INTO stanza VALUES('K7','1','영원하신 하나님 스스로 계시는 분<br/>가장 오래 되시고 가장 처음 되신 분<br/>',NULL,32986,1);
INSERT INTO stanza VALUES('K7','2','영원토록 당신은 시공 초월하시네<br/>영원토록 완전해 시종 없이 무한해<br/>',NULL,32987,2);
INSERT INTO stanza VALUES('K7','3','근원이신 당신은 천지보다 먼저니<br/>가장 먼저 계신 분 처음부터 계신 분<br/>',NULL,32988,3);
INSERT INTO stanza VALUES('K7','4','주는 영원한 생명 세세토록 끝없네<br/>오랜 자 중 오랜 분 나중이요 끝인 분<br/>',NULL,32989,4);
INSERT INTO stanza VALUES('K7','5','처음이신 알파요 나중이신 오메가<br/>시작부터 끝까지 풍성하고 완전해<br/>',NULL,32990,5);
INSERT INTO stanza VALUES('K7','6','영원하심 찬양해 무한하심 찬양해<br/>완전하심 찬양해 충만하심 찬양해<br/>',NULL,32991,6);
INSERT INTO stanza VALUES('K70','1','음악과 같이 달콤한 예수의 이름 찬양해<br/>내 기쁨 충만케 하며 완전케 하는 이름<br/>',NULL,32992,1);
INSERT INTO stanza VALUES('K70','chorus','예수 달콤한 이름 예수 존귀한 이름<br/>예수 그의 가치를 찬송하리 영원히<br/>',NULL,32993,2);
INSERT INTO stanza VALUES('K70','2','내 주의 이름 사랑해 내 고통 알고 나눈 주<br/>근심과 걱정 내게서 떠나라 명한 이름<br/>',NULL,32994,3);
INSERT INTO stanza VALUES('K70','3','날 매혹하는 그 이름 들을 때 기쁨 충만해<br/>내 모든 눈물 닦으며 위로하는 그 이름<br/>',NULL,32995,4);
INSERT INTO stanza VALUES('K70','4','내 주의 이름 달콤함 내 말로 표현 못하리<br/>나 영원토록 그 이름 찬송하고 누리리<br/>',NULL,32996,5);
INSERT INTO stanza VALUES('K700','1','세상 향유하고 주 잃으면 하루라도 살 가치 있나-<br/>없어지는 세상 가운데서 안식 위로 찾을 수 있나<br/>세상 향유하고 주 잃으-면 그 무엇이 네 맘 채우랴-<br/>이 세상의 어떤 즐거움-도 주님과는 비교 못하리<br/>',NULL,32997,1);
INSERT INTO stanza VALUES('K700','2','재물이나 애정 얻었어도 너의 명성 널리 퍼져도-<br/>방황하는 너의 돛단배는 닻을 내릴 항구 없구나<br/>너를 위해 죽은 주 잃으-면 그 무엇이 네 맘 채우랴-<br/>이 세상의 어떤 즐거움-도 주님과는 비교 못하리<br/>',NULL,32998,2);
INSERT INTO stanza VALUES('K700','3','구주 없는 세상 공허함뿐 죄악 고난 슬픔 눈물뿐-<br/>구주 없는 영원 안에서는 끝이 없는 흑암 뿐이네<br/>지금 잠시 살 수 있다 해-도 죽음 올 때 어찌하려나-<br/>주님 없는 어두움 속에-서 영원토록 어찌하려나<br/>',NULL,32999,3);
INSERT INTO stanza VALUES('K700','4','주 안에서 모든 것 얻으니 이 어떠한 즐거움인가-<br/>사함받지 못할 죄악 없네 모든 근심 주가 감당해<br/>네게 오직 주님 뿐이라-면 모든 것을 갖게 되리라-<br/>주가 너의 모든 필요들-을 풍성하게 채우시리라<br/>',NULL,33000,4);
INSERT INTO stanza VALUES('K701','1','해 아래의 모-든 수고 그 무슨 유익있으랴<br/>만물에 새 것 없으니 헛되고 헛돼<br/>',NULL,33001,1);
INSERT INTO stanza VALUES('K701','chorus','헛되고 헛되네 모든 것 헛되네<br/>바람 그림자 잡-는 것 같아<br/>',NULL,33002,2);
INSERT INTO stanza VALUES('K701','2','인생 자랑 수고뿐이니 지식에 근심 더하네<br/>슬픔과 탄식 더할 뿐 헛되고 헛돼<br/>',NULL,33003,3);
INSERT INTO stanza VALUES('K701','3','부귀 향락 소용있는가 가족과 재물 있어도<br/>여전히 근심케 하니 헛되고 헛돼<br/>',NULL,33004,4);
INSERT INTO stanza VALUES('K701','4','모든 수고 괴로움 되어 밤에도 안식이 없네<br/>죽으면 모두 끝나니 헛되고 헛돼<br/>',NULL,33005,5);
INSERT INTO stanza VALUES('K701','5','청년 때에 기억하여라 창조자 경외하여라<br/>그분이 네 맘 채울때 공허함 없네<br/>',NULL,33006,6);
INSERT INTO stanza VALUES('K701','chorus','주 없인 공허해 모-두 공허해<br/>주님 안에만 공허함 없네<br/>',NULL,33007,7);
INSERT INTO stanza VALUES('K702','1','수많은 근심과 무거운 짐져<br/>처량함만 가 -득해 탄식뿐이네<br/>',NULL,33008,1);
INSERT INTO stanza VALUES('K702','2','주님만 주님만 네 근심 푸니<br/>주저 말고 어-서 와 위로얻으라<br/>',NULL,33009,2);
INSERT INTO stanza VALUES('K703','1','영원 영원 영원-동안 넌 어-찌 지내려-는가<br/>그 날에는 이미- 늦네 오늘- 이 문제 해-결해<br/>구원 멸망 다 영-원해- 넌 어-찌 지내려는가<br/>',NULL,33010,1);
INSERT INTO stanza VALUES('K703','2','영원 영원 영원-동안 넌 어-찌 지내려-는가<br/>예수를 택한 사-람들 모든- 죄의 길 떠-나서<br/>구원받고 거듭-나서- 하나-님과 친근하네<br/>',NULL,33011,2);
INSERT INTO stanza VALUES('K703','3','영원 영원 영원-동안 넌 어-찌 지내려-는가<br/>은혜의 길을 안-가고 멸망-의 길을 간-다면<br/>장래의 종말 어-떨지- 자세-히 생각해 보라<br/>',NULL,33012,3);
INSERT INTO stanza VALUES('K703','4','영원 영원 영원-동안 넌 어-찌 지내려-는가<br/>시간 있을 때 주- 믿어 사망-서 생명에- 옮겨<br/>하나님 나라 안-에서- 영원-히 거하게 되리<br/>',NULL,33013,4);
INSERT INTO stanza VALUES('K704','1','무서운 사망의 길서 누가 날 구하랴-<br/>영원토록 꺼지잖는 불못서<br/>그 누가- 건지랴-<br/>오직 예수 날 구원해 주 예수<br/>',NULL,33014,1);
INSERT INTO stanza VALUES('K704','2','영광스런 생명 길로 그 누가 이끌랴-<br/>영원토록 슬픔 없는 축복을<br/>그 누가- 주리요-<br/>오직 예수 내게 주리 주 예수<br/>',NULL,33015,2);
INSERT INTO stanza VALUES('K705','1','하나님 믿지 않는 자 죄- 중에 죽으리<br/>하나님 아들 주 예수 죄의 종 해방해<br/>영원한 자유얻게 해 참- 자유주시네<br/>',NULL,33016,1);
INSERT INTO stanza VALUES('K706','1','예수가 우리를 부르는 소리 그 음성 부드러워<br/>문 앞에 나와서 사면을 보며 우리를 기다리네<br/>',NULL,33017,1);
INSERT INTO stanza VALUES('K706','chorus','오라 오라- -방황치 말고 오라- -<br/>죄있는 자들아 이리로 오라 주 예수 앞에 오라<br/>',NULL,33018,2);
INSERT INTO stanza VALUES('K706','2','간절히 오라고 부르실 때에 우리는 지체하랴<br/>주님의 은혜를 왜 아니 받고 못들은 체 하려나<br/>',NULL,33019,3);
INSERT INTO stanza VALUES('K706','3','세월이 살같이 빠르게 지나 쾌락이 끝이나고<br/>사망의 그늘이 너와 내 앞에 돌리며 가리우네<br/>',NULL,33020,4);
INSERT INTO stanza VALUES('K706','4','아무리 우리가 더럽더라도 긍휼히 여기는 주<br/>기묘한 사랑의 약속을 따라 언제나 받으시네<br/>',NULL,33021,5);
INSERT INTO stanza VALUES('K707','1','내 주의 분부 들리네-“나를 좇으라 날 좇으라”<br/>그 음성 종일 들리네-“나를 좇으라 날 좇으라”<br/>널 위해 간고의 길 가- 널- 위해 생명 버렸다-<br/>널 위해 쓸개즙 맛본- 나를 좇으라 날 좇으라<br/>',NULL,33022,1);
INSERT INTO stanza VALUES('K707','2','네 죄 다 용서하리니- 나를 좇으라 날 좇으라<br/>참 자유 얻게 되리니- 나를 좇으라 날 좇으라<br/>사람과 일 다 변해도- 내- 너를 인도하리라-<br/>영원히 너의 기쁨 될- 나를 좇으라 날 좇으라<br/>',NULL,33023,2);
INSERT INTO stanza VALUES('K707','3','네 염려 가지고 오라- 나를 좇으라 날 좇으라<br/>네 짐 내 어깨에 두라- 나를 좇으라 날 좇으라<br/>의심 다 내게 맡기고- 네- 장래 내게 의지해-<br/>네 눈물 닦아주리니- 나를 좇으라 날 좇으라<br/>',NULL,33024,3);
INSERT INTO stanza VALUES('K708','1','주 예수 널 돌아 오게 하려 사랑으로 부르신다<br/>왜 주의 사랑을 멀리 떠나 거기서 방황하나<br/>',NULL,33025,1);
INSERT INTO stanza VALUES('K708','chorus','널 부른다 널 부른다 예수께서 지금 사랑으로 부른다<br/>',NULL,33026,2);
INSERT INTO stanza VALUES('K708','2','돌아와 안식을 누리라고 주가 오늘 널 부른다<br/>무거운 짐 주께 맡길 때에 거절치 않으시리<br/>',NULL,33027,3);
INSERT INTO stanza VALUES('K708','3','돌아와 사함을 받으라고 주가 오늘 널 부른다<br/>네 모든 죄 갚은 주께 오라 지금 곧 나아오라<br/>',NULL,33028,4);
INSERT INTO stanza VALUES('K708','4','아직도 부르는 주의 소리 왜 안 듣나 왜 안 듣나<br/>돌아와 그 이름 불러보라 은혜가 넘치리라<br/>',NULL,33029,5);
INSERT INTO stanza VALUES('K709','1','원하는 자마다 구원 얻으리 죄인에게 주신 기쁨의 소식<br/>이 소식을 속히 널리 전하세 누구나 올 수 있게<br/>',NULL,33030,1);
INSERT INTO stanza VALUES('K709','chorus','누구든지 다 올 수 있다네 사랑하는 천부께서 부르네<br/>남녀노소 모두 값없이 오라 누구든지 다 오라<br/>',NULL,33031,2);
INSERT INTO stanza VALUES('K709','2','원하는 자마다 지체 말아라 은혜의 문 크게 열려 있으니<br/>누구든지 들어올 수 있으니 구주 예수께 오라<br/>',NULL,33032,3);
INSERT INTO stanza VALUES('K709','3','원하는 자마다 영생 얻으리 보증 있는 말씀 믿고 받도록<br/>변치 않는 약속 널리 전파해 누구나 올 수 있네<br/>',NULL,33033,4);
INSERT INTO stanza VALUES('K71','1','죽은 자 중 첫 열매 부활한 주 예수<br/>영 - 광의 머리 주님 높이 들리우셨네<br/>은혜로 교통 - 나눠 하나된 우리 - 들<br/>주 - 존귀 영광 권세 마음 다해 찬양해<br/>',NULL,33034,1);
INSERT INTO stanza VALUES('K71','2','모든 권세 얻으신 만유의 머리요<br/>아 - 버지 우편으로 승천하신 사 - 람<br/>갈보리서 나타났네 큰 능력 큰 사 - 랑<br/>모든 고통 어둠 잔해 완전히 다 이겼네<br/>',NULL,33035,2);
INSERT INTO stanza VALUES('K71','3','곧 주를 찬미하리 이 세상 만물이<br/>주 - 인정하며 모두 주 환영하겠 - 네<br/>지금은 우리 - 만이 그 큰 사랑 맛보며<br/>사랑으로 충만하여 먼저 찬송드리네<br/>',NULL,33036,3);
INSERT INTO stanza VALUES('K71','4','오 뛰어난 그 이름 풍성한 주 예수<br/>가장 승한 주의 사랑 영영 그침 없겠네<br/>주님과 우리의 연합 영원한 이 사 - 실<br/>기쁨 넘쳐 찬양하세 주 영광 주 사 - 랑<br/>',NULL,33037,4);
INSERT INTO stanza VALUES('K710','1','똑똑 똑똑 밖에서 똑똑 똑똑 누군가<br/>인내하며 두드리는 멀리서 온 나그네<br/>내 마음아 어찌하여 즉시 문을 안 여나<br/>',NULL,33038,1);
INSERT INTO stanza VALUES('K710','2','똑똑 똑똑 밖에서 똑똑 똑똑 아직도<br/>덩쿨들이 엉키어서 문을 열기 어렵네<br/>녹슨 고리 썩은 나무 겹겹으로 된 넝쿨<br/>',NULL,33039,2);
INSERT INTO stanza VALUES('K710','3','똑똑 똑똑 여전히 똑똑 똑똑 기다려<br/>두드리는 못 박힌 손 가시관을 쓰신 분<br/>간청하는 사랑의 눈 문 열기를 기다려<br/>',NULL,33040,3);
INSERT INTO stanza VALUES('K711','1','구주 예수 지금 네 맘 두드리신다<br/>강팍한 맘 먹지 말고 맘 문 열어라<br/>빨리 활짝 열고서 주님 영접해-<br/>그가 네 죄 모두 씻고 새 생명 주리<br/>',NULL,33041,1);
INSERT INTO stanza VALUES('K711','chorus','주 영접하여라 주 네 맘 두드릴 때<br/>주 영접-하여라 맘 문 열고서<br/>',NULL,33042,2);
INSERT INTO stanza VALUES('K711','2','주님 밖에 세워 두고 왜 지체하나<br/>부드러운 주의 음성 들어보아라<br/>주의 마음 아프게 하지 말고서-<br/>빨리 마음 문을 열고 은혜 받으라<br/>',NULL,33043,3);
INSERT INTO stanza VALUES('K712','1','험난한 산 길 다니며 잃은 양 찾는다<br/>돌아오라 잃은 양아 맹수와 함-정<br/>뿐-이니 더 헤매지- 말고- 오라<br/>',NULL,33044,1);
INSERT INTO stanza VALUES('K713','1','길 잃은 양같은 사람아 구주가 찾으러 오셨다<br/>백마리 양 중에 잃은 널 찾고 계신다<br/>찾고 계신다- 찾고 계신다-<br/>백 마리 양 중에 잃은 널 찾고 계신다<br/>',NULL,33045,1);
INSERT INTO stanza VALUES('K713','2','주님의 보물인 사람아 성령이 지금 널 찾는다<br/>열 드라크마 중 잃은 널 쓸며 찾는다<br/>쓸며 찾는다- 쓸며 찾는다-<br/>열 드라크마 중 잃은 널 쓸며 찾는다<br/>',NULL,33046,2);
INSERT INTO stanza VALUES('K713','3','네게는 안식이 있는가 돌아와 기쁨을 누리라<br/>아버지가 기다린 아들 네가 아닌가-<br/>네가 아닌가- 네가 아닌가-<br/>아버지가 기다린 아들 네가 아닌가<br/>',NULL,33047,3);
INSERT INTO stanza VALUES('K714','1','주 여기 계시니 가까이 해-<br/>다시는 죽음의- 길- 가지마<br/>친구가 잡아도 기회 또 없으니<br/>더 지체 말고서- 주-께 오라<br/>',NULL,33048,1);
INSERT INTO stanza VALUES('K714','2','주 여기 계시니 가까이 해-<br/>더 이상 방황하며 헤-매지 마<br/>주 은혜 베풀고 널 구원하시니<br/>미련 다 버리고- 주-께오라<br/>',NULL,33049,2);
INSERT INTO stanza VALUES('K714','3','주 여기 계시니 가까이 해-<br/>주저하지 말고- 의-심 말아<br/>네 죄악 중해도 주 사랑 변찮네<br/>절망하지 말고- 주-께 오라<br/>',NULL,33050,3);
INSERT INTO stanza VALUES('K714','4','주 여기 계시니 가까이 해-<br/>천하에 다른 길- 더- 없으니<br/>구속을 이룬 주 아직도 부르네<br/>불타는 맘으로- 주-께 오라<br/>',NULL,33051,4);
INSERT INTO stanza VALUES('K715','1','타락한 환경서 고통 맛본 너 왜 회개 안하고<br/>헤매이나 수많은 함정이 놓인 그 길서<br/>왜 속히 돌이켜 오지 않나<br/>',NULL,33052,1);
INSERT INTO stanza VALUES('K715','chorus','주께서 당신을 기다리시네<br/>왜 오늘 이 기회 안 붙잡나<br/>',NULL,33053,2);
INSERT INTO stanza VALUES('K715','2','악한 자 손 안에 누워 있는 너 악한 자 맘대로<br/>끌려 가네 그물 속 새처럼 사로잡힌 너<br/>놀림을 당하며 괴롬 당해<br/>',NULL,33054,3);
INSERT INTO stanza VALUES('K715','3','인생은 뜬구름 속히 지나가 어느 날 홀연히<br/>사라지네 죽은 후 심판과 지옥이 있네<br/>왜 영원한 형벌 안 피하나<br/>',NULL,33055,4);
INSERT INTO stanza VALUES('K715','4','죽음으로 예수 죄 담당했네 사망과 마귀 다<br/>폐하셨네 해방된 생명이 널 구원하리<br/>왜 묶여 멸망을 당하려나<br/>',NULL,33056,5);
INSERT INTO stanza VALUES('K715','5','주님을 거절해 근심케 해도 그분은 여전히<br/>기다리네 돌아설 때까지 영접할 때까지<br/>회개해 구원을 받기까지<br/>',NULL,33057,6);
INSERT INTO stanza VALUES('K716','1','돌아오기를 기다리시며 서 계시는 주 예-수<br/>네가 회개해 멸망치 않고 영생 누리기 원해<br/>',NULL,33058,1);
INSERT INTO stanza VALUES('K716','chorus','돌아오기만을 기다리시네 그 어떠한 자든지<br/>구원하여 주려 기다리시니 다만 주를 의뢰해<br/>',NULL,33059,2);
INSERT INTO stanza VALUES('K716','2','맘대로 멀리 방랑하면서 죄에 깊이 빠진- 너<br/>피곤한 너를 얻으시려고 참고 기다리는 주<br/>',NULL,33060,3);
INSERT INTO stanza VALUES('K716','3','너는 여러 번 주의 부르심 거절하고 가지-만<br/>주의 사랑은 변하지 않고 너를 재촉하시네<br/>',NULL,33061,4);
INSERT INTO stanza VALUES('K716','4','항복하여라 주의 사랑에 그가 널 기다린-다<br/>주가 오라고 말씀하실 때 원한다고 말하라<br/>',NULL,33062,5);
INSERT INTO stanza VALUES('K717','1','죄악에 눌린 자들아 구주께 나오라<br/>그 말씀 믿기만 하면 곧 구원얻으리<br/>',NULL,33063,1);
INSERT INTO stanza VALUES('K717','2','풍성한 은혜 주려고 주 보혈 흘렸네<br/>이 샘의 근원 만질 때 죄 다 씻어지리<br/>',NULL,33064,2);
INSERT INTO stanza VALUES('K717','3','주는 곧 길과 진리니 널 안식케 하리<br/>지체말고 곧 믿어서 영생 복 얻으라<br/>',NULL,33065,3);
INSERT INTO stanza VALUES('K717','4','이 거룩한 군대에 와 영광 향해 나가<br/>근심과 눈물 없는 성 영원히 누리세<br/>',NULL,33066,4);
INSERT INTO stanza VALUES('K717','chorus','지금 예-수 믿어 보라 구원얻으리<br/>지금 예-수 믿어 보라 구원얻으리<br/>',NULL,33067,5);
INSERT INTO stanza VALUES('K717','1','죄악에 눌린 사람아 구주께 나오라<br/>주 예수 믿기만 하면 주 널 구원하리<br/>',NULL,33068,6);
INSERT INTO stanza VALUES('K717','2','주 널 대신해 못 박혀 피 흘려 속전 돼<br/>구속 다 이루셨으니 곧 믿기만 하라<br/>',NULL,33069,7);
INSERT INTO stanza VALUES('K717','3','사랑이 가득한 주님 은혜 문 열었네<br/>기회 가면 또 안 오니 어서 주 믿으라<br/>',NULL,33070,8);
INSERT INTO stanza VALUES('K717','chorus','어서 속-히 주 믿으라 지금 믿으라<br/>그가 능-히 구원하리 널 구원하리<br/>',NULL,33071,9);
INSERT INTO stanza VALUES('K717','4','곧 세상 떠난 후에는 네 종말 무언가<br/>구원인가 멸망인가 어서 주 믿으라<br/>',NULL,33072,10);
INSERT INTO stanza VALUES('K718','1','주의 은혜 거절하지마 눈감고 빛을 막지 마<br/>강퍅한 마음 먹지 마 널 사랑하네<br/>구원은 이시간 연기하지마 구원 얻으라 미루지 말고<br/>',NULL,33073,1);
INSERT INTO stanza VALUES('K718','2','내일 햇빛 볼지 모른다 이 시간 놓치지 마라<br/>무얼 더 기다리느냐 피하지 마라<br/>이 때를 잡으라 구원 이 시간 네 맘 문 열고 구원 얻으라<br/>',NULL,33074,2);
INSERT INTO stanza VALUES('K718','3','세상 어디 미련을 두랴 신선한 달콤함 없네<br/>주 은혜 와서 맛보라 지금 이때 와<br/>왜 지금 이 때를 놓치려느냐 지금 이 시간 은혜 받으라<br/>',NULL,33075,3);
INSERT INTO stanza VALUES('K718','4','우리 주 인자가 충만해 주 믿는 모든 자들을<br/>한 번도 거절 안 하셔 즉시 구원해<br/>믿으라 믿으라 맘 문 열고서 지금 이 시간 다시 안 오리<br/>',NULL,33076,4);
INSERT INTO stanza VALUES('K719','1','죄짐을 지고서 곤하거든 네 맘 속에 주 영접하며<br/>새 사람되기를 원하거든 네 구주를 영접하라<br/>',NULL,33077,1);
INSERT INTO stanza VALUES('K719','chorus','의심을 다 버리고 구주를 영접하라<br/>맘 문 다 열어 놓고 네 구주를 영접하라<br/>',NULL,33078,2);
INSERT INTO stanza VALUES('K719','2','정결케 되기를 원하거든 네 맘 속에 주 영접하며<br/>생명수 마시기 원하거든 네 구주를 영접하라<br/>',NULL,33079,3);
INSERT INTO stanza VALUES('K719','3','진실한 친구를 원하거든 네 맘 속에 주 영접하며<br/>네 맘에 평안을 원하거든 네 구주를 영접하라<br/>',NULL,33080,4);
INSERT INTO stanza VALUES('K719','4','즐거운 찬송을 하려거든 네 맘 속에 주 영접하며<br/>평강과 안식을 원하거든 네 구주를 영접하라<br/>',NULL,33081,5);
INSERT INTO stanza VALUES('K72','1','시작없는 태초에 근원 두신 당신은<br/>영원하신 아버지 스스로 계시는 분<br/>',NULL,33082,1);
INSERT INTO stanza VALUES('K72','2','사람으로 왔으나 하나님과 동거해<br/>하나님과 똑같이 완전하고 무한해<br/>',NULL,33083,2);
INSERT INTO stanza VALUES('K72','3','하나님과 한 근원 만유보다 먼저니<br/>당신보다 더 일찍 앞선 자는 없었네<br/>',NULL,33084,3);
INSERT INTO stanza VALUES('K72','4','영원토록 변찮는 주의 연대 끝없네<br/>당신보다 더 오래 뒤에 있는 자 없네<br/>',NULL,33085,4);
INSERT INTO stanza VALUES('K72','5','아버지 하나님과 조금도 차이 없네<br/>더할 것이 없으신 주는 알파 오메가<br/>',NULL,33086,5);
INSERT INTO stanza VALUES('K72','6','주 영원함 찬미해 주 온전함 찬미해<br/>주의 충만 맛보니 그 무한함 놀라와<br/>',NULL,33087,6);
INSERT INTO stanza VALUES('K720','1','멸망하는 자들아 예수를 보아라<br/>바라본즉 살리라 주 보라<br/>몸을 버린 주 보라 볼 때에 살리라<br/>나무 위에 달리신 주 보라<br/>',NULL,33088,1);
INSERT INTO stanza VALUES('K720','chorus','보라 나무에 달린 구주 앙망하여라<br/>바라본즉 살리라- 주 보라<br/>',NULL,33089,2);
INSERT INTO stanza VALUES('K720','2','사악하고 추해도 주 보면 살리라<br/>바라본즉 살리니 주 보라<br/>사탄 아래 묶인 자 주 보면 살리라<br/>볼 때 해방받으리 주 보라<br/>',NULL,33090,3);
INSERT INTO stanza VALUES('K720','3','오래 방탕했어도 주 보면 살리라<br/>강퍅한 맘 버리고 주 보라<br/>네가 돌아서기를 주님은 원하니<br/>지체하지 말고서 주 보라<br/>',NULL,33091,4);
INSERT INTO stanza VALUES('K721','1','빈곤-하고 연약하며 슬퍼-하는 죄인아<br/>긍휼- 사랑 충만하신 예수-께로 오너라<br/>그가- 너를 구원하리 의심-말고 나오라<br/>',NULL,33092,1);
INSERT INTO stanza VALUES('K721','2','그가- 너를 환영하니 안심-하고 오너라<br/>통회-하고 믿는 자는 정녕- 은혜 얻으니<br/>대가- 없이 구원되리 누구-든지 나오라<br/>',NULL,33093,2);
INSERT INTO stanza VALUES('K721','3','나 같-은 자 받으실까 주저- 말고 나오라<br/>주의- 사랑 원하는 자 누구-든지 합당해<br/>은혜-의 문 열렸으니 다른- 조건 없다네<br/>',NULL,33094,3);
INSERT INTO stanza VALUES('K721','4','번민-하며 절망 속에 고통-하는 사람아<br/>자기- 개선 원한다면 영영- 못 오게 되리<br/>우리- 죄빚 갚으려고 주가- 못 박히셨다<br/>',NULL,33095,4);
INSERT INTO stanza VALUES('K721','5','겟세-마네 구주께서 피와- 땀을 흘리고<br/>골고-다서 죽으실 때“다 이-뤘다”외쳤네<br/>그 음-성에 어찌 우리 반응- 없을 수 있나<br/>',NULL,33096,5);
INSERT INTO stanza VALUES('K721','6','그의- 피가 공의 요구 이미- 만족게 했네<br/>그를- 믿고 순종할 때 모든- 죄가 사해져<br/>오직- 예수 그분만이 죄인-들의 친구 돼<br/>',NULL,33097,6);
INSERT INTO stanza VALUES('K722','1','표류하는 인생은 구름같이 사라져 꿈이 깨면<br/>허무해- 허무해 세월은 살과 같고 사망에<br/>삼킨바 돼- 지옥 불에 이르니- 오시오<br/>',NULL,33098,1);
INSERT INTO stanza VALUES('K722','chorus','이땔세 이 -땔세 주가 부르시는 때가 이땔세<br/>죄중에 있을때에 은혜의 문 닫히면-<br/>찾아도 때는 이미- 늦겠네<br/>',NULL,33099,2);
INSERT INTO stanza VALUES('K722','2','아침에 피인 꽃이 저녁에 떨어지듯 인간 영화<br/>사라져- 사라져 죽음에 이르러서 불 못에<br/>던지기 전- 주의 음성 들으오- 들으오<br/>',NULL,33100,3);
INSERT INTO stanza VALUES('K722','3','성령 감동하시며 네게 강권하실 때 왜 순종치<br/>않느냐- 않느냐 주의 은혜 받고서 네 비참한<br/>상태를- 주저말고 면하오- 면하오<br/>',NULL,33101,4);
INSERT INTO stanza VALUES('K722','4','죄인들아 주께 와 그의 간청 듣고서 주의 은총<br/>받으라- 받으라 주의 영과 합하여 큰 구원<br/>받을 때는- 지금 이 시간일세- 이 시간<br/>',NULL,33102,5);
INSERT INTO stanza VALUES('K722','5','주는 생명 주는 영 이미 부어졌으니 이름 불러<br/>영접해- 영접해 그의 이름 부를 때 주 네 안에<br/>들어와- 네 영 안에 살겠네- 살겠네<br/>',NULL,33103,6);
INSERT INTO stanza VALUES('K723','1','사람마다 주 예수 필요해 주 하나님<br/>성육신 되셔서 세상 계실때 고초 당하고<br/>그 나무틀에 우리 위해 못 박혔네<br/>',NULL,33104,1);
INSERT INTO stanza VALUES('K723','chorus','모든 사람 사람마다 구주 예수 필요해<br/>죄짐벗기 위하여 평안 얻기 위하여<br/>영생 얻기 위해 모두 주 필요해<br/>',NULL,33105,2);
INSERT INTO stanza VALUES('K723','2','부활 승천해 중보되시고 그 성령 보내<br/>찾고 계시네 믿기 원하면 이름 부르라<br/>주 은혜로써 모든 필요 채워주리<br/>',NULL,33106,3);
INSERT INTO stanza VALUES('K723','3','어둔 맘에도 빛을 비추고 그 많은 죄도<br/>전부 용서해 주의 흘린 피 더러움 씻고<br/>그 영은 네게 생명되고 능력되리<br/>',NULL,33107,4);
INSERT INTO stanza VALUES('K723','4','인생 살 동안 부족 느낄 때 그 모든 필요<br/>그 뜻 모르나 다만 예수로 필요함 채워<br/>주 예수 너의 허무한 맘 만족게 해<br/>',NULL,33108,5);
INSERT INTO stanza VALUES('K723','chorus','주 필요해 주 필요해 사람마다 필요해<br/>공허 면키 위하여 만족 얻기 위하여<br/>의미 있는 인생 위해 주 필요해<br/>',NULL,33109,6);
INSERT INTO stanza VALUES('K723','5','인생 사는 것 고생 슬픔뿐 고난당하면<br/>고할 데 없네 세상 허황해 믿을 데 없네<br/>이 모든 것이 예수 필요함 말하네<br/>',NULL,33110,7);
INSERT INTO stanza VALUES('K724','1','내- 모습 선-함 없-으나 주 날- 대신해 피 흘려<br/>새- 생명 얻-게 하시니- 주 예수께-로 옵니다<br/>',NULL,33111,1);
INSERT INTO stanza VALUES('K724','2','난- 개선될- 수 없-으나 주 보-혈 내 죄 씻으니<br/>주- 피만 의-지하면서- 주 예수께-로 옵니다<br/>',NULL,33112,2);
INSERT INTO stanza VALUES('K724','3','난- 정함 없-고 변-하며 늘 반-신반의 했었네<br/>안-팎이 악-할 뿐이니- 주 예수께-로 옵니다<br/>',NULL,33113,3);
INSERT INTO stanza VALUES('K724','4','난- 빈곤하-고 눈- 멀어 주 은-혜 필요한 자니<br/>내- 악을 알- 때 눈 열려- 주 예수께-로 옵니다<br/>',NULL,33114,4);
INSERT INTO stanza VALUES('K724','5','내- 원래 모-습 그-대로 날 받-고 생명 주신 주<br/>내- 죄를 사-하셨으니- 주 예수께-로 옵니다<br/>',NULL,33115,5);
INSERT INTO stanza VALUES('K725','1','속박과 근심 벗으려고 예수께로 나옵니다<br/>자유와 기쁨 빛 되시는 주께로 옵니다<br/>약하던 내가 강해지고 빈곤한 삶이 부해지며<br/>죄악을 벗어 버리려고 주께로 옵니다<br/>',NULL,33116,1);
INSERT INTO stanza VALUES('K725','2','실패와 수치 벗어나서 예수께로 나옵니다<br/>십자가 수확 얻기 위해 주께로 옵니다<br/>슬프던 마음 평안하고 풍파 벗어나 잔잔하며<br/>기쁨의 찬송 부르려고 주께로 옵니다<br/>',NULL,33117,2);
INSERT INTO stanza VALUES('K725','3','교만과 불평 벗어나서 예수께로 나옵니다<br/>복되신 뜻을 따르려고 주께로 옵니다<br/>자신을 떠나 주님 안에 절망을 떠나 주 앙망해<br/>독수리 날개 펴듯 올라 주께로 옵니다<br/>',NULL,33118,3);
INSERT INTO stanza VALUES('K725','4','사망의 권세 벗어나서 예수께로 나옵니다<br/>생명의 은사 얻으려고 주께로 옵니다<br/>파멸의 심연 벗어나서 안식할 동산 들어가리<br/>영광의 얼굴 바라보러 주께로 옵니다<br/>',NULL,33119,4);
INSERT INTO stanza VALUES('K726','1','날- 반기는 음성 날 불러 믿게 해<br/>내 양심 씻기 위하여 주 보혈 흘렸네<br/>',NULL,33120,1);
INSERT INTO stanza VALUES('K726','chorus','내가 주께로 지금 가오니<br/>주의 피로 날 씻어 정결케 하소서<br/>',NULL,33121,2);
INSERT INTO stanza VALUES('K726','2','더-럽고 천하여 선함은 없으나<br/>내 약함 제해주시고 큰 은혜 주시네<br/>',NULL,33122,3);
INSERT INTO stanza VALUES('K726','3','맘- 비워 회개해 구주 영접하라<br/>참 마음으로 믿으라 주 말씀하시네<br/>',NULL,33123,4);
INSERT INTO stanza VALUES('K726','4','은-혜의 말씀이 날 오라 부르네<br/>또 성령으로 비추니 내 헛됨 깨닫네<br/>',NULL,33124,5);
INSERT INTO stanza VALUES('K726','5','성-령이 내 안에 생명을 증명해<br/>그 이름 믿은 나에게 주 약속 이뤄져<br/>',NULL,33125,6);
INSERT INTO stanza VALUES('K726','6','높-고도 기묘해 하나님 큰 사랑<br/>참 아름다운 그 사랑 하나님 큰 구원<br/>',NULL,33126,7);
INSERT INTO stanza VALUES('K726','chorus','예수 피흘려 날 사왔으니<br/>나의 온 몸 다 바쳐 내 주만 섬기리<br/>',NULL,33127,8);
INSERT INTO stanza VALUES('K727','1','연약하고 빈곤해 십자가로 갑니다<br/>세상 일 공허하니 주의 은혜 필요해<br/>',NULL,33128,1);
INSERT INTO stanza VALUES('K727','chorus','주의 십자가 밑에 겸손히 엎드리니<br/>어린 양 예수시여 나를 구원하소서<br/>',NULL,33129,2);
INSERT INTO stanza VALUES('K727','2','주의 은혜 구하나 죄에 묶여 있던 나<br/>주의 음성 들었네“네 죄 내가 사했다”<br/>',NULL,33130,3);
INSERT INTO stanza VALUES('K727','3','주 내맘에 충만해 모두 새롭게 하니<br/>그의 보혈 날 씻고 나를 온전케 하네<br/>',NULL,33131,4);
INSERT INTO stanza VALUES('K727','chorus','주의 은혜 감사해 내 맘 기쁨 충만해<br/>이미 구원 받은 나 주만 따라 가겠네<br/>',NULL,33132,5);
INSERT INTO stanza VALUES('K727','4','나의 전체 드리리 나의 영과 혼과 몸<br/>친척 친구 지혜 힘 재물 시간 온전히<br/>',NULL,33133,6);
INSERT INTO stanza VALUES('K728','1','천부를 멀리 떠-나서 헤매는 자여<br/>왜 종일 죄의 고-통 속 헤매고 있나<br/>',NULL,33134,1);
INSERT INTO stanza VALUES('K728','chorus','돌아와 집으로 더 방황말고<br/>사랑하는 아-버지 종일 서있네<br/>',NULL,33135,2);
INSERT INTO stanza VALUES('K728','2','나 주를 멀리 떠-났다 이제 옵니다<br/>나 죄의 길에 시-달려 주여 옵니다<br/>',NULL,33136,3);
INSERT INTO stanza VALUES('K728','3','그 귀한 세월 보-내고 이제 옵니다<br/>눈물로 통회하-면서 집에 옵니다<br/>',NULL,33137,4);
INSERT INTO stanza VALUES('K728','4','나 죄에 매여 고-달파 이제 옵니다<br/>주 사랑 말씀 의-지해 집에 옵니다<br/>',NULL,33138,5);
INSERT INTO stanza VALUES('K728','5','상처 투성이 맘-으로 이제 옵니다<br/>능력과 소망 얻-고자 주여 옵니다<br/>',NULL,33139,6);
INSERT INTO stanza VALUES('K728','6','나 주의 보혈 필-요해 집에 옵니다<br/>내 죄를 씻기 원-하여 주여 옵니다<br/>',NULL,33140,7);
INSERT INTO stanza VALUES('K729','1','나의 사랑 예수여 날 감추어 주소서<br/>두려움의 파도와 거센 비바람 불 때<br/>날 감추어 주소서 풍파 지나가도록<br/>끝까지 날 안전히 인도하여 주소서<br/>',NULL,33141,1);
INSERT INTO stanza VALUES('K729','2','피난처가 없어서 주께 의탁하오니<br/>거절하지 마시고 날 붙들어 주소서<br/>주가 나의 의지요 나의 도움이시니<br/>거룩하신 날개로 나를 덮어 주소서<br/>',NULL,33142,2);
INSERT INTO stanza VALUES('K729','3','주는 나의 필요니 나를 채우고 남네<br/>날 부축해 보호해 치료하며 인도해<br/>나는 불의하여도 주는 의로우시니<br/>은혜 진리 충만한 주께 나아갑니다<br/>',NULL,33143,3);
INSERT INTO stanza VALUES('K729','4','내 모든 죄 사하신 주의 은혜 찬양해<br/>치료하는 생수가 나의 중심 씻어 내<br/>영원하신 생명샘 내 맘속에 산 샘 돼<br/>내 안에서 흘러서 영영 넘치기 원해<br/>',NULL,33144,4);
INSERT INTO stanza VALUES('K73','1','주여 찬송받으소서 찬송 소리 작으나<br/>주의 은혜 말하리라 주는 우리 구줄세<br/>',NULL,33145,1);
INSERT INTO stanza VALUES('K73','2','주가 영광 버림으로 우린 축복 얻었네<br/>주가 빈곤하게 되어 우린 풍성 누리네<br/>',NULL,33146,2);
INSERT INTO stanza VALUES('K73','3','하늘 떠나 세상에 와 인생길을 가신 주<br/>죽기까지 고독한 길 쓸쓸하게 가셨네<br/>',NULL,33147,3);
INSERT INTO stanza VALUES('K73','4','영광스런 하늘 떠나 쓸쓸한 땅 가셨네<br/>어려운 길 알면서도 날 사랑해 가셨네<br/>',NULL,33148,4);
INSERT INTO stanza VALUES('K73','5','주의 선함 주의 사랑 나를 기쁘게 하나<br/>내 부족함 생각할 때 부끄러움 날 덮네<br/>',NULL,33149,5);
INSERT INTO stanza VALUES('K73','6','우린 그날 빨리 와서 모든 방해 벗어나<br/>영광 안에 들어가서 주 섬기기 원하네<br/>',NULL,33150,6);
INSERT INTO stanza VALUES('K73','7','오늘 우린 기다리네 소망 격려 받으며<br/>주 앞에 다 설 때까지 주 위하게 하소서<br/>',NULL,33151,7);
INSERT INTO stanza VALUES('K730','1','인애하신 구세주여 내 말 들으사<br/>죄인 오라 하실 때에 날 부르소서<br/>',NULL,33152,1);
INSERT INTO stanza VALUES('K730','chorus','주여 주-여 내 말 들으사<br/>죄인 오라 하실 때에 날 부르소서<br/>',NULL,33153,2);
INSERT INTO stanza VALUES('K730','2','자비하신 보좌 앞에 꿇어 엎드려<br/>자복하고 회개하니 믿음 줍소서<br/>',NULL,33154,3);
INSERT INTO stanza VALUES('K730','3','주의 공로 의지하여 주께 가오니<br/>상한 맘을 고치시고 구원합소서<br/>',NULL,33155,4);
INSERT INTO stanza VALUES('K730','4','만복 근원 예수시여 위로하소서<br/>우리 주와 같으신 이 어디 있을까<br/>',NULL,33156,5);
INSERT INTO stanza VALUES('K731','1','만세 반석 여시어 나를 감춰 주시네<br/>주가 흘린 피와 물 이중 죄를 해결해<br/>내 죄 씻어주시고 죄의 권능 벗게 해<br/>',NULL,33157,1);
INSERT INTO stanza VALUES('K731','2','쉬지 않고 일해도 주의 요구 못 이뤄<br/>항상 열심 내면서 눈물 계속 흘려도<br/>내 죄 속량 못하니 주여 구원하소서<br/>',NULL,33158,2);
INSERT INTO stanza VALUES('K731','3','빈손 들고 나아가 십자가를 붙드네<br/>벌거벗은 나에게 옷이 되어 주소서<br/>생명샘에 나가니 나를 씻어 주소서<br/>',NULL,33159,3);
INSERT INTO stanza VALUES('K731','4','내 인생이 끝나고 나의 눈이 감길 때<br/>내가 영원 가운데 보좌 앞에 갈 때에<br/>만세 반석 여시어 나를 감춰 주소서<br/>',NULL,33160,4);
INSERT INTO stanza VALUES('K732','1','하늘 영광의 보좌 면류관 떠나 나를 구하려 오셨지만<br/>베들레헴엔 주가 태어나실 곳 한 칸 방도 없었다네<br/>',NULL,33161,1);
INSERT INTO stanza VALUES('K732','chorus','내- 마음 속에 오소서 주가 거하실 방 있으니<br/>내- 맘에 오소서 주 예수 주의 방 마련됐으니<br/>',NULL,33162,2);
INSERT INTO stanza VALUES('K732','2','천사 천군은 주의 존귀한 인격 높이 찬양을 하였지만<br/>주는 이 땅의 천한 집에 나셔서 천대 받으며 사셨네<br/>',NULL,33163,3);
INSERT INTO stanza VALUES('K732','3','여우도 굴이 새도 둥지 있으나 주는 머리 둘 곳 없었네<br/>나그네로서 유대 땅 다니시고 갈릴리 광야 다녔네<br/>',NULL,33164,4);
INSERT INTO stanza VALUES('K732','4','주의 백성을 해방하기 위하여 은혜의 말씀 전했으나<br/>주를 능욕해 가시관을 씌우고 갈보리에서 죽였네<br/>',NULL,33165,5);
INSERT INTO stanza VALUES('K732','5','주의 승리와 위엄 찬양하리라 더욱더 높이 찬양하라<br/>그때 주님 날 들어올려 말하리“내게 널 위한 방 있다”<br/>',NULL,33166,6);
INSERT INTO stanza VALUES('K732','chorus','난- 찬양하리 주 예수 주가 날 주 곁에 부르리<br/>어-서 오소서 주 예수여 어서 날 곁에 두소서<br/>',NULL,33167,7);
INSERT INTO stanza VALUES('K733','1','내 맘에 들어오소서- 나 회개하고 믿으니<br/>내 마음이 공허하니- 지금 들어오소서<br/>',NULL,33168,1);
INSERT INTO stanza VALUES('K733','chorus','내 맘 속에 내 맘속에 오시옵소서 주 예수<br/>들어와서 거하소서 은혜 주소서 주 예수<br/>',NULL,33169,2);
INSERT INTO stanza VALUES('K733','2','내 맘에 들어오소서- 주 구원 필요하오니<br/>날 죄악의 고통에서- 구원하여 주소서<br/>',NULL,33170,3);
INSERT INTO stanza VALUES('K733','3','내 맘에 들어오소서- 내 온 존재 새롭게<br/>생명의 영 거주하게- 내 마음에 오소서<br/>',NULL,33171,4);
INSERT INTO stanza VALUES('K734','1','죄악을 씻고 육신 벗도록<br/>그리스도 주로 영접해<br/>사탄 힘 잃고 세상 빛 잃게<br/>그리스도 주로 영접해<br/>영접하라! 더 지체하지 말고서<br/>영접하라! 그리스도 주로 영접해<br/>',NULL,33172,1);
INSERT INTO stanza VALUES('K734','2','생명의 변화 성령의 능력<br/>주를 영접하여 얻으라<br/>충만한 평강 넘치는 소망<br/>주를 영접하여 얻으라<br/>영접하라 맘 비우고서 영접해<br/>영접하라 주를 생명으로 영접해<br/>',NULL,33173,2);
INSERT INTO stanza VALUES('K734','3','질병 치료돼 약함 사라져<br/>의사이신 주를 영접해<br/>고통 멈추고 죽음 삼켜져<br/>의사이신 주를 영접해<br/>영접하라 단 맘으로 영접해<br/>영접하라 그리스도 주로 영접해<br/>',NULL,33174,3);
INSERT INTO stanza VALUES('K734','4','탄식 변하여 근심 기쁨 돼<br/>그리스도 나의 왕 될 때<br/>천국의 영광 나의 누림 돼<br/>그리스도 나의 왕 될 때<br/>영접하라 네 의지 주께 굴복해<br/>영접하라 그리스도 주로 영접해<br/>',NULL,33175,4);
INSERT INTO stanza VALUES('K735','1','죄 바다에 빠진 나 평강의 뭍 떠나<br/>온갖 파괴당하여 큰 고통 맛볼 때<br/>주 내 외침 듣고서 즉시 와 구했네<br/>깊고 넓은 그 사랑 날 구했네<br/>',NULL,33176,1);
INSERT INTO stanza VALUES('K735','chorus','사랑으로 날 구했네<br/>나 죄 중에 헤맬 때 날 구했네<br/>사랑으로 날 구했네<br/>나 죄 중에 헤맬 때 날 구했네<br/>',NULL,33177,2);
INSERT INTO stanza VALUES('K735','2','이제 평강 안에서 죄악 고통 벗고<br/>기쁨 안식 충만해 주 예수께 속해<br/>강인한 참 사랑에 찬양을 드리네<br/>나의 생명 내 전체 다 드리리<br/>',NULL,33178,3);
INSERT INTO stanza VALUES('K735','3','고통 속의 죄인아 듣고 믿기만 해<br/>주 사랑의 소식을 지금 영접하라<br/>주가 널 구원하려 오래 기다렸다<br/>의심 말고 믿고 구원 얻으라<br/>',NULL,33179,4);
INSERT INTO stanza VALUES('K736','1','나 오래 죄의 길- 헤-매 내 혼이 상했네<br/>주 나의 맘에 오-셔-서 내 상처 감싸네<br/>',NULL,33180,1);
INSERT INTO stanza VALUES('K736','chorus','영광의 내 구주 나의 눈이 할렐루야 보겠네<br/>영광의 내 구주 할렐루야 보겠네<br/>',NULL,33181,2);
INSERT INTO stanza VALUES('K736','2','내 감겼던 눈 열-려-서 주 얼굴 본다네<br/>주 아름다운 참- 사-랑 다 말 못하겠네<br/>',NULL,33182,3);
INSERT INTO stanza VALUES('K736','3','오 보배로운 내- 구-주 날 늘 이기게 해<br/>내 주와 비할 자- 없-네 내 생명 내 사랑<br/>',NULL,33183,4);
INSERT INTO stanza VALUES('K737','1','나 죄로 피곤할 때 주 나를 찾았네<br/>날 품 속에 두시고 어깨에 지셨네<br/>오 따뜻한 그 사랑 나를 양무리로 이끄네<br/>',NULL,33184,1);
INSERT INTO stanza VALUES('K737','chorus','부드러운 사랑 나를 돌이켰네<br/>귀한 보혈 날 속량했네 양무리로 오게 하셨네<br/>',NULL,33185,2);
INSERT INTO stanza VALUES('K737','2','나 중한 상처 받아 죽어갈 그 때에<br/>기름을 바르시며 포도주 부었네<br/>넌 내 것이라 속삭일 때 내 맘 치료되었네<br/>',NULL,33186,3);
INSERT INTO stanza VALUES('K737','3','손발에 못 박히고 옆구리 찔린 주<br/>수치 고난의 가시 면류관 쓰신 주<br/>나 무어관대 나 위하여 그런 찔림 받았나<br/>',NULL,33187,4);
INSERT INTO stanza VALUES('K737','4','나 그의 앞에 앉아 그 얼굴 뵐때에<br/>내 맘과 영에 주 찬양 넘침 느끼네<br/>오 영원토록 찬양해도 아직 부족하겠네<br/>',NULL,33188,5);
INSERT INTO stanza VALUES('K737','5','오 세월 지나 모두 다 안식하는 날<br/>그 빛나는 아침을 간절히 고대해<br/>주 나를 곁에 부르시어 동반자가 되게 해<br/>',NULL,33189,6);
INSERT INTO stanza VALUES('K738','1','풍성한 주의 은혜 죄인을 구원했네<br/>풍성한 주의 은혜 한량 없도다<br/>',NULL,33190,1);
INSERT INTO stanza VALUES('K738','chorus','주 모든 사슬 끊고 자유를 주셨도다<br/>주 모든 사슬 끊고 나를 해방해<br/>',NULL,33191,2);
INSERT INTO stanza VALUES('K738','2','내 죄 다 사했으니 평강이 충만하네<br/>내 전체 속박 벗고 해방되었네<br/>',NULL,33192,3);
INSERT INTO stanza VALUES('K738','3','죄악과 세상 사탄 또 나를 묶지 못해<br/>시험과 질병 질고 나를 못 묶네<br/>',NULL,33193,4);
INSERT INTO stanza VALUES('K738','4','할렐루 주의 이름 달콤해 향기로와<br/>할렐루 주의 이름 영영 찬양해<br/>',NULL,33194,5);
INSERT INTO stanza VALUES('K738','5','또 불러 할렐루야 주님 날 해방했네<br/>또 불러 할렐루야 날 해방했네<br/>',NULL,33195,6);
INSERT INTO stanza VALUES('K739','1','구주의 십자가 보혈로 죄 씻음 받기를 원하네<br/>내 죄를 씻으신 주 이름 영광 돌리세!<br/>',NULL,33196,1);
INSERT INTO stanza VALUES('K739','chorus','영광 돌리세!- - 영광 돌리세!- -<br/>내 죄를 씻으신 주 이름 영광 돌리세!<br/>',NULL,33197,2);
INSERT INTO stanza VALUES('K739','2','구주의 놀라운 큰 은혜 보혈로 모든 죄 씻었네<br/>이 씻음 놀랍고 달콤해 영광 돌리세!<br/>',NULL,33198,3);
INSERT INTO stanza VALUES('K739','3','오 귀한 주님의 보배 피 내 죄를 눈같이 씻으니<br/>기쁨과 초월함 맛보네 영광 돌리세!<br/>',NULL,33199,4);
INSERT INTO stanza VALUES('K74','1','천사 노래 들려온다 “새로 나신 주 찬양”<br/>은혜 평강 임했으니 하나님 사람 화목돼<br/>모든 백성 일어나서 하늘 찬미 응답하세<br/>천사 함께 외치네 베들레헴에 나신 주<br/>천사 함께 외치네 베들레헴에 나신 주<br/>',NULL,33200,1);
INSERT INTO stanza VALUES('K74','2','영원한 왕 그리스도 하늘에서 내려와<br/>동정녀에게서 나셔 사람 모양 되셨네<br/>혈육 입은 신격일세 성육신된 비밀일세<br/>사람으로 거하신 임마누엘 구주 예수<br/>사람으로 거하신 임마누엘 구주 예수<br/>',NULL,33201,2);
INSERT INTO stanza VALUES('K74','3','하늘에서 오신 왕 - 화평의 왕 의의 해<br/>빛과 생명 가져와 - 살리며 치료하네<br/>죄인 구원하시려고 자신 낮춰 오셨네 -<br/>주의 나심 우리를 중생케 하고 높이네<br/>주의 나심 우리를 중생케 하고 높이네<br/>',NULL,33202,3);
INSERT INTO stanza VALUES('K74','4','우리 맘에 오셔서 - 거처 정하옵소서<br/>여자의 씨 오셔서 - 내 속 옛 뱀 깨소서<br/>아담 모양 끝내고 - 당신 형상 새기소서<br/>마지막 아담 풍성 내 전체 회복하소서<br/>마지막 아담 풍성 내 전체 회복하소서<br/>',NULL,33203,4);
INSERT INTO stanza VALUES('K740','1','오 주여 우린 주의 죽으심에 서서<br/>주 역사 찬송하며 다 간증합니다<br/>믿음으로 주님의 길 따라갑니다<br/>장엄하고 오묘한 이 물로 인하여<br/>',NULL,33204,1);
INSERT INTO stanza VALUES('K740','2','오 우린 주의 고난 다 기념합니다<br/>주 내게 은혜 주려 파도에 밀려서<br/>죽음의 침례 받고 보혈 흘리시고<br/>날 위해 생명 버림 다 기념합니다<br/>',NULL,33205,2);
INSERT INTO stanza VALUES('K740','3','오 주님 흑암 헤쳐 곧 부활하셔서<br/>보좌에 앉아 영영 살아 계시오니<br/>사망과 음부 파한 주님의 승리를<br/>내 생명 된 주 안에 함께 누립니다<br/>',NULL,33206,3);
INSERT INTO stanza VALUES('K740','4','나 오늘 여기에서 침례를 받고서<br/>주님과 함께 죽고 주님과 부활해<br/>주 영광에 참예해 사탄 세상 이겨<br/>주님과 함께 주를 위해 살렵니다<br/>',NULL,33207,4);
INSERT INTO stanza VALUES('K741','1','세상 사탄 흉악해도 다신 우릴 쫓-지 못하네<br/>주와 함께 부활해 주와 함께 행동- 한다네<br/>생명 성령 능력 무궁하니 은혜 입고 영광 위에 영-광<br/>',NULL,33208,1);
INSERT INTO stanza VALUES('K742','1','이 물로 인해 주님과 나 함께 죽었네-<br/>이 사실 시인할 때에 그 가치 나타나<br/>',NULL,33209,1);
INSERT INTO stanza VALUES('K742','2','이 물로 인해 주님과 나 장사되었네-<br/>죄 대해 죽고 영원히 죄 묶임 벗었네<br/>',NULL,33210,2);
INSERT INTO stanza VALUES('K742','3','이 물로 인해 주님과 나 장사되었네-<br/>이 세상 작별하고서 이 세상 벗어나<br/>',NULL,33211,3);
INSERT INTO stanza VALUES('K742','4','나 주와 함께 부활해 사망 권세 벗어-<br/>거룩한 열매 맺으며 새 생명 살겠네<br/>',NULL,33212,4);
INSERT INTO stanza VALUES('K742','5','주 안에 침례 받고서 내 자아 벗어나-<br/>영원히 주와 하나 돼 주 위해 살겠네<br/>',NULL,33213,5);
INSERT INTO stanza VALUES('K743','1','다 죽었네 다 묻혔네 나는 완전히 다 끝났네<br/>다 죽었네 다 묻혔네 나는 완전히 다 끝났네<br/>',NULL,33214,1);
INSERT INTO stanza VALUES('K743','2','다 끝났네 다 끝났네 나는 이제 모두 끝났네<br/>다 끝났네 다 끝났네 나는 이제 모두 끝났네<br/>',NULL,33215,2);
INSERT INTO stanza VALUES('K743','3','이젠 내가 살지 않네 오직 그리스도 사시네<br/>이젠 내가 살지 않네 오직 그리스도 사시네<br/>',NULL,33216,3);
INSERT INTO stanza VALUES('K744','1','나 물로 구원받았네 오 기묘한 비밀<br/>그 뜻을 계시하시니 큰 구원이로다<br/>',NULL,33217,1);
INSERT INTO stanza VALUES('K744','2','나 물로 구원받아서 이 세상 벗어나<br/>새 생명 한계 안에서 과거 다 끝났네<br/>',NULL,33218,2);
INSERT INTO stanza VALUES('K744','3','그때에 홍수 인하여 노아를 구하듯<br/>침례의 물 십자가로 날 구원하셨네<br/>',NULL,33219,3);
INSERT INTO stanza VALUES('K744','4','나 물로 구원받아서 참 자유 누리네<br/>세상의 속박 다 벗고 질고 다 벗었네<br/>',NULL,33220,4);
INSERT INTO stanza VALUES('K744','5','나 물로 구원받아서 주님께 속하여<br/>주 경배하고 섬기며 거룩게 되겠네<br/>',NULL,33221,5);
INSERT INTO stanza VALUES('K745','1','하나님의 권세의 영역인 왕국은<br/>그 질서 건축하는 주권의 다스림<br/>주 하나님의 왕권 행사되는 왕국<br/>영원히 하나님이 다스리는 나라<br/>',NULL,33222,1);
INSERT INTO stanza VALUES('K745','2','왕국의 중심 보좌 하나님 좌정해<br/>그 마음 갈망따라 모든 것 다스려<br/>왕이신 하나님이 머리와 주되니<br/>다 자기 위치에서 제 궤도 지키네<br/>',NULL,33223,2);
INSERT INTO stanza VALUES('K745','3','하나님 다스려서 그의 뜻 행사해<br/>그 권세 아래 그 뜻 이루어 가시네<br/>보좌로부터 주의 생명 강 흘러가<br/>하나님 나라 안에 축복 넘치도다<br/>',NULL,33224,3);
INSERT INTO stanza VALUES('K745','4','그 통치 아래에서 축복을 받도다<br/>그 주권 거스림이 죄악의 뿌리니<br/>늘 주의 보좌 엎는 사탄 물리치고<br/>하나님 권위 아래 살기만 원하네<br/>',NULL,33225,4);
INSERT INTO stanza VALUES('K745','5','하나님 왕국 안에 주 확대되겠네<br/>주 생명의 다스림 하나님 자랑돼<br/>주 통치 실시할 때 다 축복받으리<br/>주 하나님의 영광 다 나타나겠네<br/>',NULL,33226,5);
INSERT INTO stanza VALUES('K745','6','때 차면 주 안에서 만유가 하나돼<br/>주 왕권 인정하고 그 통치받으리<br/>생명의 통치 먼저 교회가 맛볼 때<br/>만유도 그 누림을 고대하고 원해<br/>',NULL,33227,6);
INSERT INTO stanza VALUES('K746','1','하나님 내- 맘 다-스림 이것이<br/>하나-님 왕국 내 안에 주-님<br/>왕-노릇 해- 날 관리하-고 다-스려<br/>',NULL,33228,1);
INSERT INTO stanza VALUES('K746','2','주 생명 그-의 권-위로 내 맘에<br/>보좌- 얻었네 내 전체 그-가<br/>관-리-해- 내 말과 행-동까-지도<br/>',NULL,33229,2);
INSERT INTO stanza VALUES('K746','3','내 맘에 보-좌 가-진 주 내 맘에<br/>왕국- 세우네 완전한 권-위 통-치-로-<br/>내 모든 길-을 예-비해<br/>',NULL,33230,3);
INSERT INTO stanza VALUES('K746','4','주 내 맘 다-스리-시며 생명을<br/>공급-하시네 주님이 나-의 왕- 될- 때-<br/>난 주의 풍-성 누-리네<br/>',NULL,33231,4);
INSERT INTO stanza VALUES('K746','5','주께서 내- 속 다-스려 내 안에<br/>주 충-만 있네 내 안에 왕-국 세-울- 때-<br/>주님의 몸-이 세-워져<br/>',NULL,33232,5);
INSERT INTO stanza VALUES('K746','6','하늘의 통-치 인-하여 하늘의<br/>백성-되도다 기꺼이 그-의 권-위-에-<br/>다 순종하-여 왕-국 돼<br/>',NULL,33233,6);
INSERT INTO stanza VALUES('K746','7','하늘의 권-위 가-지고 하늘의<br/>영역-에 살리 이 땅에 왕-국 서-도-록-<br/>늘 하늘 빛-에 행-하리<br/>',NULL,33234,7);
INSERT INTO stanza VALUES('K747','1','왕국의 표준- 엄격-해 율법보다<br/>더 뛰어나 하나님 요구-보다-도<br/>더 높은 요구- 없으리<br/>',NULL,33235,1);
INSERT INTO stanza VALUES('K747','2','천국이 가까-왔으-니 먼저 다<br/>회개하여라 네 생각 바뀌-어져-서<br/>하나님께로- 돌아서<br/>',NULL,33236,2);
INSERT INTO stanza VALUES('K747','3','천국에 들어-가려-면 뛰어난<br/>의를 가지라 율법으로는- 못 이-뤄<br/>생명으로만- 가능해<br/>',NULL,33237,3);
INSERT INTO stanza VALUES('K747','4','천국에 들어-가려-면 천부의<br/>뜻을 준행해 네 원함대로- 말고-서<br/>천부의 원함- 따르라<br/>',NULL,33238,4);
INSERT INTO stanza VALUES('K747','5','어린 아이와- 같아-야 천국에<br/>들어가겠네 겸손하고 단-순하-며<br/>자만함 없어-야 하리<br/>',NULL,33239,5);
INSERT INTO stanza VALUES('K747','6','하나님처럼- 완전-함 천국은<br/>요구한다네 이 표준에 합-해야-만<br/>왕국의 실재- 실천돼<br/>',NULL,33240,6);
INSERT INTO stanza VALUES('K747','7','하나님 성품-과 같-은 하나님<br/>통치인 왕국 하나님 생명-으로-야<br/>이 나라 들어-가겠네<br/>',NULL,33241,7);
INSERT INTO stanza VALUES('K747','8','하늘에 속한- 통치-와 하늘에<br/>속한 상태에 하늘에 속한- 생명-만<br/>참여할 수가- 있겠네<br/>',NULL,33242,8);
INSERT INTO stanza VALUES('K748','1','천국-의 실재는 바로 주 통-치<br/>받고 사-는 것- 신성-한 생활 속-에서<br/>주 만- 구하는- 것일세<br/>',NULL,33243,1);
INSERT INTO stanza VALUES('K748','2','영 안-에 가난하면서- 애통-하고<br/>온유-한 맘- 긍휼-히 여기는- 마음<br/>주 향-해 순수-한 마음<br/>',NULL,33244,2);
INSERT INTO stanza VALUES('K748','3','화평-케 하며 의 위해 핍박-을<br/>견뎌 내-는 삶- 주 위-해 능욕 받-으며<br/>원망- 없이 즐-거워 해<br/>',NULL,33245,3);
INSERT INTO stanza VALUES('K748','4','소금-으로 부패 막고 빛으-로<br/>흑암 비-추네- 뜻과- 행동이 성-실해<br/>아버-지같이- 온전해<br/>',NULL,33246,4);
INSERT INTO stanza VALUES('K748','5','자기-의 영광 버리고 주 나-라<br/>위해 기-도해- 먼저- 주님의 나-라와<br/>그 의-를 구하-는 생활<br/>',NULL,33247,5);
INSERT INTO stanza VALUES('K748','6','자신-에 엄격하면서 남에-게<br/>은혜 베-풀며- 영원-히 주 뜻 준-행해<br/>주 말-씀 좇아- 행하네<br/>',NULL,33248,6);
INSERT INTO stanza VALUES('K748','7','사탄-과 세상과 인정 다 거-절<br/>하며 나-아가- 하늘-의 통치 순-종해<br/>주 권-위 받기- 원하네<br/>',NULL,33249,7);
INSERT INTO stanza VALUES('K748','8','이러-한 생활 인하여 주 분-부<br/>하심 지-키며- 주 오-심 재촉하-면서<br/>주 왕-국 실현-해 가네<br/>',NULL,33250,8);
INSERT INTO stanza VALUES('K749','1','보라 왕국 영-광 광채 천국 이뤄졌-도다<br/>영광의 왕 그-리스도 하나님-이 세웠네<br/>육신 되-어 인-생길 가 멸시 천-대 받-은 주<br/>이제 영광 위-엄 갖고 왕국 이-루려 오네<br/>',NULL,33251,1);
INSERT INTO stanza VALUES('K749','2','권위 왕국 받-으려고 하나님께 가-신 주<br/>이제 모든 사-람 앞에 왕국 갖-고 오시네<br/>사람 손-이 뜨-지 않은 이 돌 열-국 분-쇄해<br/>온 땅 채운 큰- 산 이뤄 왕국 광-채 나타내<br/>',NULL,33252,2);
INSERT INTO stanza VALUES('K749','3','보라 땅의 열-국들이 주의 기업 되-리라<br/>그의 높은 통-치 아래 평강 조-화 넘치리<br/>다시 전-쟁 없-으리라 다시 무-기 없-으리<br/>하나님에 대 -한 지식 온 땅 위-에 넘치리<br/>',NULL,33253,3);
INSERT INTO stanza VALUES('K749','4','이긴 모든 성-도들이 주와 함께 다-스려<br/>이스라엘 남 -은 자들 제사장-이 되리라<br/>장차 열-국 하-나님의 백성들-이 되-리라<br/>만물들도 소 -생되어 영화롭-게 되리라<br/>',NULL,33254,4);
INSERT INTO stanza VALUES('K749','5','사탄 잡혀 던-져지니 온 땅 속박 벗-어나<br/>그리스도 통 -치하니 온 땅 축-복 얻겠네<br/>만유 주께 복-종하여 그의 통-치 받-으리<br/>주가 중심 머-리 되어 하나님- 뜻 이루리<br/>',NULL,33255,5);
INSERT INTO stanza VALUES('K75','1','영광버리고 세상에 임하셔<br/>사람된 내 구주 그의 이름 예수<br/>구유에 나셔 마른 땅에 자라<br/>고통의 길 간 슬픔의 사람<br/>',NULL,33256,1);
INSERT INTO stanza VALUES('K75','chorus','사랑스런 주 그를 경배해<br/>내 공기 내 빛 내 모든 것<br/>크신 창조주 내 구주되어<br/>하나님 충만 가져왔네<br/>',NULL,33257,2);
INSERT INTO stanza VALUES('K75','2','날 구원하려 낮추고 또 낮춰<br/>그늘에 앉은 자 모두 구하셨네<br/>오 참된 사랑 자기 영광 버려<br/>죽음에 처한 백성 구했네<br/>',NULL,33258,3);
INSERT INTO stanza VALUES('K75','3','저항하잖고 혈육 입으셨네<br/>사람 모습 취해 하나님 뜻 이뤄<br/>하나님 사람 영광의 큰 비밀<br/>나 그의 모든 풍성 누리네<br/>',NULL,33259,4);
INSERT INTO stanza VALUES('K750','1','하나님 아들은 생명의 씨 사람들 맘에 뿌려져<br/>왕국이 자라 나올 때 주 하-나님- 뜻 이-뤄져<br/>',NULL,33260,1);
INSERT INTO stanza VALUES('K750','2','유일한 생명의 밀-인 주 또 많은 열매 맺었네<br/>천국의 아들들 낳아 주 통-치 가-져 오-시네<br/>',NULL,33261,2);
INSERT INTO stanza VALUES('K750','3','하나님 원-수 몰-래 와 가라지 함께 심었네<br/>왕국 아들들 혼란케 저 부-패한- 일 만-드네<br/>',NULL,33262,3);
INSERT INTO stanza VALUES('K750','4','간교한 역-사 인-하여 가라지와 밀 섞여져<br/>왕국의 외형 변하여 더 커-지고- 흉해-졌네<br/>',NULL,33263,4);
INSERT INTO stanza VALUES('K750','5','천국은 겨-자씨- 같아 먹기 좋은 나물이나<br/>종류따라 안 자라고 그 큰- 나무-를 이-뤘네<br/>',NULL,33264,5);
INSERT INTO stanza VALUES('K750','6','이제는 음-식 될 수 없어 공중의 새들 거처 돼<br/>악한 일들과 악령들 다 거-기 깃-들어- 있네<br/>',NULL,33265,6);
INSERT INTO stanza VALUES('K750','7','왕국 외형-이 보여주는 세상적이고 큰 종교<br/>가루 속의 누룩처럼 저 이-방 악-함 용-납해<br/>',NULL,33266,7);
INSERT INTO stanza VALUES('K750','8','왕국의 외-형 변-하여 세상의 조직 되었네<br/>악한 것 용납하므로 큰 부-패 음-란 충-만해<br/>',NULL,33267,8);
INSERT INTO stanza VALUES('K750','9','주 예수 오-사 찾-으셔 진주와 감추인 보물<br/>주 나를 변케 하시어 참 진-주 보-석 되-게 해<br/>',NULL,33268,9);
INSERT INTO stanza VALUES('K750','10','왕국의 외-형 그- 속에 왕국의 실재 감춰져<br/>하나님과 그리스도 이 실-제에- 충만-하네<br/>',NULL,33269,10);
INSERT INTO stanza VALUES('K750','11','날 가라지에서 구-하고 큰 나무에서 구하사<br/>내 모든 누룩 제하여 주같-이 순결케 하-소서<br/>',NULL,33270,11);
INSERT INTO stanza VALUES('K750','12','날 생명으-로 변-케 해 귀한 재료 되게 하여<br/>주 왕국 실재 지니고 성전- 건축-에 합당케 해<br/>',NULL,33271,12);
INSERT INTO stanza VALUES('K751','1','난- 오늘 훈-련해 주- 왕국 생활<br/>장래 보상 돼 주님과 다스리리<br/>주의 지혜로- 오늘은 훈련받고<br/>주의 계획을 성취해 공의 이뤄<br/>',NULL,33272,1);
INSERT INTO stanza VALUES('K751','2','난- 그날 주- 위해 왕-노릇하리<br/>왕이 되려면 훈련이 필요하네<br/>우리 주의 나-라에서 다스리며<br/>주의 신성한 왕권을 표현토록<br/>',NULL,33273,2);
INSERT INTO stanza VALUES('K751','3','하-나님 권-위에 복-종함 배워<br/>오늘 주님의 다스림 처리 받아<br/>그날 하나님- 권위를 함께 나눠<br/>열국 다스리며 주와 왕노릇해<br/>',NULL,33274,3);
INSERT INTO stanza VALUES('K751','4','자-신에 엄-격해 공-의 따르며<br/>다른 이에겐 은혜로 관대하게<br/>하나님에 대 -하여 늘 즐거워 해<br/>항상 왕국의 실재를 살아야 해<br/>',NULL,33275,4);
INSERT INTO stanza VALUES('K751','5','이-렇게 살- 때에 주- 강림하셔<br/>그의 왕권을 상으로 주시리라<br/>주 날 통해 그- 공의를 나타내며<br/>천사들에게 지혜를 보이시리<br/>',NULL,33276,5);
INSERT INTO stanza VALUES('K751','6','왕-국을 위-하여 달-린 사도들<br/>어떤 대가도 기꺼이 지불했네<br/>우리 또한 이- 왕국을 얻기 위해<br/>충성 다하여 앞으로 전진하리<br/>',NULL,33277,6);
INSERT INTO stanza VALUES('K751','7','왕-국을 위-하여 살-게 하소서<br/>오늘 훈련받고 장래 상 얻도록<br/>왕국 실재가- 오늘 내 훈련 되면<br/>장래 왕국의 실현이 보상되리<br/>',NULL,33278,7);
INSERT INTO stanza VALUES('K752','1','주 오셔서 상을 주실 때가 이를는지 늦을는지<br/>주 만날 때 견고하게 서서 밝은 등불 비출지<br/>',NULL,33279,1);
INSERT INTO stanza VALUES('K752','chorus','준비되어 담대하게 주를 맞을 수가 있으랴<br/>주 오실 때 졸지 말고 깨어 주를 기다리고 있으라<br/>',NULL,33280,2);
INSERT INTO stanza VALUES('K752','2','주 오시면 각각 이름 불러 즉시 모든 결산해<br/>달란트를 남겨 드릴 때에 성실한 종 되겠네<br/>',NULL,33281,3);
INSERT INTO stanza VALUES('K752','3','주 맡기신 사명 충성했나 우리 힘껏 일했나<br/>우리 속에 꾸짖음 없으면 들려 올라 가겠네<br/>',NULL,33282,4);
INSERT INTO stanza VALUES('K752','4','주 오실 때 깨어 있는 사람 함께 왕 노릇 하리<br/>밤 중엘지 새벽에 오실지 기다리고 있으라<br/>',NULL,33283,5);
INSERT INTO stanza VALUES('K753','1','주 예수-의- 앞으로 들림 받기- 위해<br/>주의 오-심- 사모해 늘 기다린-다네<br/>주의 가-까-우심을 난- 알고 기다-려<br/>주의 임-재- 나의 맘 늘 감싸 주-시네<br/>',NULL,33284,1);
INSERT INTO stanza VALUES('K753','2','주가 나-의- 깊은 데 늘 말씀하-시며<br/>주의 계-획- 분명히 다 알려 주-시네<br/>주님 속-히- 오시리 곧- 나타나시-리<br/>은혜의- 날- 많잖네 원수 곧 지-겠네<br/>',NULL,33285,2);
INSERT INTO stanza VALUES('K753','3','나를 자-유-하도록 끈 모두 끊-으사<br/>모든 묶-임- 벗어나 주 좇게 하-소서<br/>나의 마-음- 붙잡는 일-내려 놓겠-네<br/>주님 다-시- 오실 때 자유롭기- 위해<br/>',NULL,33286,3);
INSERT INTO stanza VALUES('K753','4','순간순-간- 기다려 늘 깨어 있-으리<br/>들림 받-기- 사모해 그 영을 좇-으리<br/>항상 예-비-하면서 잠-자지 않으-리<br/>자격 없-어- 부끄럼 당하지 않-도록<br/>',NULL,33287,4);
INSERT INTO stanza VALUES('K753','5','이는 엄-한- 경계니 내 마음 깨-어나<br/>사랑하-는- 모든 것 다 벗어나-겠네<br/>주님만-을- 사랑해 주-만을 생각-해<br/>주가 너-를- 부를 때 모두 다 버-리라<br/>',NULL,33288,5);
INSERT INTO stanza VALUES('K753','6','오늘 전-쟁- 맹렬해 사탄이 힘-쓰나<br/>얼마 후-면- 들리워 두려움 없-으리<br/>흑암 더-욱- 심해도 구-속의 날 오-네<br/>나의 주- 곧-- 오시리 깨어서 기-다려<br/>',NULL,33289,6);
INSERT INTO stanza VALUES('K753','7','나의 사-랑- 내 생각 주 예수 뿐-이니<br/>세상 유-혹- 거절해 주님과 동-거해<br/>땅의 속-박- 푸시고 내- 주여 오소-서<br/>내 맘 하-늘- 올라가 주 보기원-하네<br/>',NULL,33290,7);
INSERT INTO stanza VALUES('K754','1','주님 친히 강림할 때 하늘 나팔 울리고<br/>잠든 성도 모두 부활 하리라<br/>주님 친히 강림할 때 성도 들림 받아서<br/>몸의 형상 변화 받게 되리라<br/>',NULL,33291,1);
INSERT INTO stanza VALUES('K754','chorus','주님 친히 강림할 때 주의 영광 보게 되리<br/>주님 친히 강림할 때 나도 몸의 구속 참여하리라<br/>',NULL,33292,2);
INSERT INTO stanza VALUES('K754','2','주님 친히 강림할 때 밝은 아침 다가와<br/>어둔 밤이 지나 눈물 그치리<br/>주님 친히 강림할 때 영광의 날 곧 오리<br/>부패 없고 탄식 사라지리라<br/>',NULL,33293,3);
INSERT INTO stanza VALUES('K754','3','주님 친히 강림할 때 빛난 새벽별 나와<br/>깨어 신실한 자 상을 받으리<br/>주님 친히 강림할 때 의가 세상 다스려<br/>만물 소생되고 긍휼 얻겠네<br/>',NULL,33294,4);
INSERT INTO stanza VALUES('K754','4','주님 강림하시리니 깨어 기다려야 해<br/>허리띠 조이고 등불 지키세<br/>주님 강림하시리니 우리 충성 다하여<br/>은사 묻지 말고 주를 섬기세<br/>',NULL,33295,5);
INSERT INTO stanza VALUES('K755','1','주의 다시 오심 임박했으니 복된 걸음 소리 들린다<br/>거룩한 백성아 깨어 있으라 주를 만날 기쁨 한 없다<br/>',NULL,33296,1);
INSERT INTO stanza VALUES('K755','chorus','영광 영광 다시 오신다 영광 영광 환호 하여라<br/>우리 천한 몸이 변형될 때에 영광 안에 자유 누리리<br/>',NULL,33297,2);
INSERT INTO stanza VALUES('K755','2','주님 다시 온다 새벽별 뜬다 밤이 깊고 낮이 가깝다<br/>거룩한 백성아 깨어 있으라 속된 것에 잠기지 말라<br/>',NULL,33298,3);
INSERT INTO stanza VALUES('K755','3','주님 다시 오셔 상 주실 때에 면류관에 참예하여라<br/>거룩한 백성아 깨어 있으라 세상 귀히 여기지 말라<br/>',NULL,33299,4);
INSERT INTO stanza VALUES('K755','4','주님 다시 오셔 왕국 얻고서 큰 왕 되어 사탄 던지리<br/>거룩한 백성아 깨어 있으라 힘써 왕국 향해 달리라<br/>',NULL,33300,5);
INSERT INTO stanza VALUES('K756','1','나의 왕 속-히 오시리 하늘-에 충만하리<br/>온 우주 구속 돼 소생 할 구원을 이루시리<br/>구름 가운-데 들리는 주님-의 발-소리<br/>그 영광의- 몸 하늘에 은밀히 나타내리<br/>',NULL,33301,1);
INSERT INTO stanza VALUES('K756','2','나 오늘 주 임재 앙망해 게으-름 떨-치고<br/>주 다시 오-심 기다려 들림 받기- 원해<br/>주 지금 오-셔 주께로 날 이-끌어- 가길<br/>간절히 사모-하는 맘 주님만 향-하네<br/>',NULL,33302,2);
INSERT INTO stanza VALUES('K756','3','내 눈은 주-만 보면서 맘은- 하늘에 있네<br/>내 입은 오-직 주와의 만남을 말-하리<br/>나 위해 주- 다시 오실 그 날-이 가-까와<br/>주 약속 영-영 견고해 모두 이뤄-지리<br/>',NULL,33303,3);
INSERT INTO stanza VALUES('K756','4','내 구주 거-룩한 말씀 의심-할 것- 없네<br/>거룩한 주- 말씀으로 스스로 격려하리<br/>주 영광 속-히 나타나 저 원-수 패배시켜<br/>주 약속 속-히 이루어 우리를 이-끌리<br/>',NULL,33304,4);
INSERT INTO stanza VALUES('K756','5','구주 예수- 내 하나님 내 피-난처-시니<br/>주 의지하-는 모든 이 주께서 보-호해<br/>목자와 양-들 하나요 머리-와 몸 하나니<br/>누구도 우-릴 못 뺏네 당신의 손-에서<br/>',NULL,33305,5);
INSERT INTO stanza VALUES('K756','6','온 세상 사-람 눈과 손 날 막-을 수- 없네<br/>길 위의 가-시 다만 날 전진케 도-울 뿐<br/>내 맘과 영-아 일어나 이 세-상 보-내라<br/>생명의 주-여 오소서 하늘로 올리소서<br/>',NULL,33306,6);
INSERT INTO stanza VALUES('K756','7','치료하는- 해와 소망 그 빛-을 사-모해<br/>공의의 주- 영광 왕께 무릎 꿇습-니다<br/>주여 보좌-에 오르사 그 얼-굴 나-타내<br/>당신의 천-국 세우사 은혜를 주-소서<br/>',NULL,33307,7);
INSERT INTO stanza VALUES('K756','8','진리가 승-리 왕이요 자유-가 왕-후나<br/>거짓이 퍼-져 이 세상 머리가 되-었네<br/>진리여 하늘빛 가지고 신속-히 임-하여<br/>주 품에 많-은 아들들 들어가게 하소서<br/>',NULL,33308,8);
INSERT INTO stanza VALUES('K757','1','내 어이 잊을 수 있나 곧 다시 오실 주님을<br/>내 마음 늘 사모하며 주 위해 늘 찬송하네<br/>',NULL,33309,1);
INSERT INTO stanza VALUES('K757','chorus','주여 오소서 내 왕이여 오소서<br/>',NULL,33310,2);
INSERT INTO stanza VALUES('K757','2','내 어이 잠잘 수 있나 난 항상 깨어 있겠네<br/>세상에 귀 기울이다 때 놓칠까 두려워 해<br/>',NULL,33311,3);
INSERT INTO stanza VALUES('K757','3','세상과 짝할 수 없네 난 높은 부름 받았네<br/>땅에 속한 것 버리고 주님만 사랑하겠네<br/>',NULL,33312,4);
INSERT INTO stanza VALUES('K757','4','영 안에 종일 행하며 주 생명 흡수하겠네<br/>깨어서 주 기다리며 매 순간 예비하겠네<br/>',NULL,33313,5);
INSERT INTO stanza VALUES('K757','5','두려워하지 않으리 사탄의 악한 권세를<br/>주께서 권세 잡으니 음부의 문이 못 이겨<br/>',NULL,33314,6);
INSERT INTO stanza VALUES('K757','6','한시도 잊을 수 없네 주 다시 온다는 소식<br/>내 믿음 온전케 하고 주 말씀 증명하소서<br/>',NULL,33315,7);
INSERT INTO stanza VALUES('K758','1','베다니서당신과헤어진- 후 그 무엇도내 빈 맘 못 채워<br/>버드나무에걸어 놓은 수금을 당신 없이 내 어이켜리까<br/>고요한 밤에 나- 홀로있을때 나는탄식을 참을 수 없어<br/>당신은 너무 먼 것처럼 느껴져 돌아오신다약속한 시간 가도<br/>',NULL,33316,1);
INSERT INTO stanza VALUES('K758','2','주말 구유 내 집 생각지우-고 주 십자가내 욕심제하네<br/>주 오심나로본향그리게하니주님자신이 내 목적일세<br/>주 여기없어기쁨은맛 잃었네찬송도 감미로움잃었네<br/>난 종일뭔가잃어버린 것 같아오 주여지체말고어서오소서<br/>',NULL,33317,2);
INSERT INTO stanza VALUES('K758','3','나여기서도주의임재 누리나깊은속엔여전히부족해<br/>주 날 비추고사랑으로 감싸도알 수 없는불만이있다네<br/>평안함속에서도외롬느끼고기쁨속에서도탄식흘러<br/>큰 만족속에서도 부족 느낌은주 직접 뵙지 못하기 때문일세<br/>',NULL,33318,3);
INSERT INTO stanza VALUES('K758','4','고향떠난 자 속엔 늘 고향생각포로의맘엔늘 고국 생각<br/>집 떠난자녀맘엔늘 가족생각내 맘엔언제나 당신 생각<br/>주 얼굴보고픈 나의이 마-음 어느 것과도 비교 못하리<br/>여기서주의모습볼 수 없-어 탄식하며다만당신기다리네<br/>',NULL,33319,4);
INSERT INTO stanza VALUES('K758','5','잊으셨나요다시돌아와-서 날 데려가리라고한 약속<br/>하루가가고일 년이또 지나도당신은 돌아오시지않네<br/>나 기다림에지쳐피곤하여도당신의 발소리는 멉니다<br/>얼마나얼마나 더 기다려-야 그 약속이루시겠습니까주여<br/>',NULL,33320,5);
INSERT INTO stanza VALUES('K758','6','한세대또 한 세대 지나가-고 기다리던성도들 잠드네<br/>한 분 또 한 분 이세상떠나갈 때 또 한 번 당신기다렸지만<br/>내 주여왜 여전히 안 오십니까하늘은 왜 닫혀 있습니까<br/>우리는기다리고 기다립니다우리의 기다림이 부족합니까<br/>',NULL,33321,6);
INSERT INTO stanza VALUES('K758','7','기다려온 날 돌이켜생각할 때 탄식참을 수 없어웁니다<br/>내 간구듣고부디지체마소서지금오셔서 날 만나소서<br/>어서 오소서교회부르짖으니성도들 모두 재촉하오니<br/>이 쌓인부르짖음들어주소서내 주여 제발 지금 들어주소서<br/>',NULL,33322,7);
INSERT INTO stanza VALUES('K759','1','언제 돌아 오시렵니까 늘 사모하는 내 주님<br/>언제 주님 다시 오셔서 그 모습 보이시렵니까<br/>은혜의 주여 오셔서 언제 내 마음 위로하렵니까<br/>은혜의 주여 오소서 주 임재 사모하니<br/>',NULL,33323,1);
INSERT INTO stanza VALUES('K759','2','어이 지체하시는가요 늘 내 마음 사모합니다<br/>언제 주님 다시 오셔서 사랑의 잔치를 하나요<br/>은혜의 주여 오셔서 언제 내 맘을 기쁘게 하나요<br/>어서 오소서 내 주여 당신을 사랑하니<br/>',NULL,33324,2);
INSERT INTO stanza VALUES('K76','1','주 온유함이 남긴 흔적 빛나고 - 도 - 거룩해<br/>당신이 가신 외 - 로 - 운 길 주의 사랑 나타내<br/>',NULL,33325,1);
INSERT INTO stanza VALUES('K76','2','아름다운 주 온유한 주 빛 중 빛 - 인 - 주 외에<br/>고난의 세상 견 - 뎌 - 내며 통과할 자 누구랴<br/>',NULL,33326,2);
INSERT INTO stanza VALUES('K76','3','치욕당해도 대항 않고 원망하 - 지 - 않으신<br/>주님의 선함 겸 - 손 - 하심 아름답게 빛나네<br/>',NULL,33327,3);
INSERT INTO stanza VALUES('K76','4','죄수를 자유케 하려고 달게 죽 - 음 - 받았네<br/>주의 피 따라 긍 - 휼 - 흘러 주의 사랑 표현돼<br/>',NULL,33328,4);
INSERT INTO stanza VALUES('K76','5','놀라운 주님 더 본받아 낮추심 - 을 - 배우며<br/>주 겸손 닮아 종 - 신 - 토록 주의 길 좇기 원해<br/>',NULL,33329,5);
INSERT INTO stanza VALUES('K760','1','감람산 위에서 헤어진 후로 지금껏 주 우릴 부르잖네<br/>주 뵐수 있기를 늘 간구하나 주 우리 기도를 안 듣는 듯<br/>',NULL,33330,1);
INSERT INTO stanza VALUES('K760','chorus','주여 주여- 어서 속히 오소서-<br/>주 다시 오심만 기다리오니 어서 속히 오소서<br/>',NULL,33331,2);
INSERT INTO stanza VALUES('K760','2','사랑의 주님이 승천하신 후 이 세상 무엇도 맛 없으니<br/>늘 간구 안에서 지켜보면서 주 오심 아닌가 추측하네<br/>',NULL,33332,3);
INSERT INTO stanza VALUES('K760','3','꽃 향기 새 소리 날 웃게 못해 난 언제 주님을 뵈오려나<br/>저 하늘 산과 들 아름다우나 주 어느 하늘에 계시는지<br/>',NULL,33333,4);
INSERT INTO stanza VALUES('K760','4','내 주여 인내로 기다립니다 얼마나 더 오래 남았나요<br/>날마다 해 뜨고 해 질 때마다 주 다시 오심만 바랍니다<br/>',NULL,33334,5);
INSERT INTO stanza VALUES('K760','5','비바람 칠 때도 주 기다리고 날 개일 때에도 주 기다려<br/>주 이미 오셨길 기대했지만 오늘도 주님은 안 오셨네<br/>',NULL,33335,6);
INSERT INTO stanza VALUES('K760','6','주께서 떠날 때 분부한 말씀 지키며 소망을 갖습니다<br/>주 다시 오심을 고대하면서 주 위해 힘 다해 일합니다<br/>',NULL,33336,7);
INSERT INTO stanza VALUES('K760','7','주여 때 오랜 것 기억하소서 주 약속 기억해 주옵소서<br/>바라고 바라고 또 바라오니 주 오심 당길 수 없는지요<br/>',NULL,33337,8);
INSERT INTO stanza VALUES('K761','1','주 예수 왜 아직 안 오십니까 주 예수 왜 아직 안 오십니까<br/>온 천지 피조물 탄식하면서 주 예수 오시기 고대합니다<br/>우주는 갈수록 쇠하여지고 온 천지 만물들 고대하오니<br/>어서 오소서 어서 오소서<br/>',NULL,33338,1);
INSERT INTO stanza VALUES('K761','2','주 예수 왜 아직 안 오십니까 주 예수 왜 아직 안 오십니까<br/>만물들 참 오래 기다렸는데 왜 오실 날짜를 단축 않나요<br/>다함께 소리쳐 부르짖으며 주 예수 오시기 고대하오니<br/>속히 오소서 속히 오소서<br/>',NULL,33339,2);
INSERT INTO stanza VALUES('K761','3','주 예수 왜 아직 안 오십니까 주 예수 왜 아직 안 오십니까<br/>주 승천하신 후 기쁨 없으니 내 맘에 또 다른 사랑 없으니<br/>내 모든 웅지도 힘 잃었는데 주 예수 왜 아직 안 오십니까<br/>속히 오소서 속히 오소서<br/>',NULL,33340,3);
INSERT INTO stanza VALUES('K761','4','사방의 모든 것 후패해가고 나태해지면서 변해갑니다<br/>사랑은 식어져 계산만 늘고 믿음은 신음해 비척거리며<br/>소망은 꺼지는 등불 같은데 주 예수 왜 아직 안 오십니까<br/>오시옵소서 오시옵소서<br/>',NULL,33341,4);
INSERT INTO stanza VALUES('K761','5','주 예수 왜 아직 안 오십니까 주 예수 왜 아직 안 오십니까<br/>어느 해 어느 날 오시렵니까 내 기도 소리를 들으십니까<br/>이제는 더 이상 지체 마소서 주 예수 주 예수 어서 오소서<br/>어서 오소서 어서 오소서<br/>',NULL,33342,5);
INSERT INTO stanza VALUES('K762','1','그 오랜 날 동안 기다린 주의 재림<br/>이 오랜 기다림 한 없고 끝 없는 것 같네<br/>주 음성 주 얼굴 사모해 기다리네<br/>지금보다 더욱 친밀히 교통하기 원해<br/>',NULL,33343,1);
INSERT INTO stanza VALUES('K762','chorus','얼마나 더 기다려야 오시려는지<br/>얼마나 더 많은 눈물을 흘려야 하는지<br/>',NULL,33344,2);
INSERT INTO stanza VALUES('K762','2','과부의 맘으로 기다려 주의 재림<br/>애타는 맘으로 내 주를 늘 잊지 못하네<br/>신부의 맘으로 기다려 혼인 기약<br/>사랑의 병이나 탄식해 그 날 기다리네<br/>',NULL,33345,3);
INSERT INTO stanza VALUES('K762','3','교회가 지금껏 주 오심 기다려도<br/>한 세대 한 세대 지나도 주 오시지 않네<br/>나 또한 지금껏 주 오심 기다렸네<br/>많은 내 친구들 잠드나 주 오시지 않네<br/>',NULL,33346,4);
INSERT INTO stanza VALUES('K762','4','너무나 기다려 지친 날 기억하사<br/>더 이상 지체치 마시고 주 어서 오소서<br/>시험은 쉬 나를 원망에 빠지게 해<br/>내 모든 헌신을 잊게 해 못견디게 하네<br/>',NULL,33347,5);
INSERT INTO stanza VALUES('K762','5','내 오랜 기다림 기억해 주 오소서<br/>주 일찍 오시지 못하면 날 가게 하소서<br/>아직도 주님은 저 편에 머무시니<br/>비웃는 사람들 주 다시 안 온다 합니다<br/>',NULL,33348,6);
INSERT INTO stanza VALUES('K762','6','내 맘을 누르는 근심과 모든 고통<br/>주 친히 오시지 않으면 해결 못합니다<br/>영원한 기업에 주께서 날 이끌 때<br/>이 모든 것 벗고 내 마음 만족함 누리리<br/>',NULL,33349,7);
INSERT INTO stanza VALUES('K763','1','내 생명된 그리스도 영광의 소망<br/>날 거듭나게 하고 또 적셔 주시네<br/>정복의 능력으로 내 몸을 변케 해<br/>그 영광스런 몸으로 변케 해<br/>',NULL,33350,1);
INSERT INTO stanza VALUES('K763','chorus','주님 오네 날 영화롭게 하려<br/>나의 몸 주의 몸과 같이 변형되-겠네<br/>주님 오네 구속을 이루려<br/>영광의 소망 주 올때 우린 변형되리<br/>',NULL,33351,2);
INSERT INTO stanza VALUES('K763','2','하나님 비밀인 주님 영광의 소망<br/>하나님 충만 내 안에 나눠 주시네<br/>날 하나님과 하나가 되게 하시니<br/>하나님 영광 영원히 누리리<br/>',NULL,33352,3);
INSERT INTO stanza VALUES('K763','3','완전한 구속인 주님 영광의 소망<br/>내 몸의 구속 이뤄져 사망 벗으리<br/>주 오셔 나의 몸 영화롭게 하실 때<br/>사망 다 삼켜 영원히 이기리<br/>',NULL,33353,4);
INSERT INTO stanza VALUES('K763','4','내 역사인 그리스도 영광의 소망<br/>주 그리스도의 체험 곧 나의 체험<br/>영광의 자유로 나를 이끄는 주님<br/>난 그와 하나 온전히 이루리<br/>',NULL,33354,5);
INSERT INTO stanza VALUES('K764','1','감취었던 비밀 나타났으니<br/>실재이신 그리스돌세 성육신 된 예수<br/>내 생명 됐네 그는 우리 영광의 소망<br/>',NULL,33355,1);
INSERT INTO stanza VALUES('K764','chorus','영광 영광 주는 내 생명 영광 영광 영광의 소망<br/>우리 안에 계신 그리스도가 비밀일세 영광의 소망<br/>',NULL,33356,2);
INSERT INTO stanza VALUES('K764','2','내 영 안에 오신 주 그리스도<br/>이제 내 혼 변케 하시네 그가 우리 몸도<br/>변화시키리 주와 같은 형상 되도록<br/>',NULL,33357,3);
INSERT INTO stanza VALUES('K764','3','사신 주님 매일 접촉할수록<br/>주의 성분 더해져가네 내 각 부분 주의<br/>형상 되도록 항상 깨어 주를 누리리<br/>',NULL,33358,4);
INSERT INTO stanza VALUES('K765','1','은혜의 주- 다-시 올 때 난 근심 벗-고- 좇으리<br/>온 성도 함-께- 좇으리 주 찬양해 주 찬양해 주 찬양해<br/>온 성도 함-께- 좇으리- 주 찬양해<br/>',NULL,33359,1);
INSERT INTO stanza VALUES('K765','2','내 눈이 주-를- 뵈옵고 영원히 그-와- 거할 때<br/>난 즐거움-에- 외치리 주 찬양해 주 찬양해 주 찬양해<br/>난 즐거움-에- 외치리- 주 찬양해<br/>',NULL,33360,2);
INSERT INTO stanza VALUES('K765','3','공중에 계-신- 주 볼 때 내 십자가- 안- 무거워<br/>주 만나 기-뻐- 뛰겠네 주 찬양해 주 찬양해 주 찬양해<br/>주 만나 기-뻐- 뛰겠네 주 찬양해<br/>',NULL,33361,3);
INSERT INTO stanza VALUES('K765','4','그 누가 주-를- 이기랴 나 그날 간-증-하겠네<br/>그날에 하-늘- 오르리 주 찬양해 주 찬양해 주 찬양해<br/>그날에 하-늘- 오르리 주 찬양해<br/>',NULL,33362,4);
INSERT INTO stanza VALUES('K765','5','주 옆구리-에- 감춰져 다시는 안- 흩-어지리<br/>주 올 때 만-족-하도록 주 찬양해 주 찬양해 주 찬양해<br/>주 올 때 만-족-하도록 주 찬양해<br/>',NULL,33363,5);
INSERT INTO stanza VALUES('K765','6','내 왕이여- 곧- 오셔서 주 약속 이-뤄- 주소서<br/>주 사랑하-는- 자에게 상 주소서 주 찬양해 주 찬양해<br/>오 주여 지-금- 오소서 주 찬양해<br/>',NULL,33364,6);
INSERT INTO stanza VALUES('K766','1','영광의 소망 주 다시올 때 들림 받아 우리 변화 되리<br/>주님과 영화롭게 되어서 완전히 주 형상 이루리라<br/>',NULL,33365,1);
INSERT INTO stanza VALUES('K766','chorus','영광스런 소망일세 그리스도 다시 오심<br/>들림 받아 우린 변화되리 영광의 소망 주 다시 오심<br/>',NULL,33366,2);
INSERT INTO stanza VALUES('K766','2','영광의 소망 주 다시 올 때 옛 창조 영원히 사라지리<br/>자유에 이를 때 탄식 없고 최상의 구원을 누리겠네<br/>',NULL,33367,3);
INSERT INTO stanza VALUES('K766','3','영광의 소망 주 다시 올 때 주님과 만국을 다스리리<br/>제사장 되어서 주 섬기며 완전히 구원을 이루리라<br/>',NULL,33368,4);
INSERT INTO stanza VALUES('K766','4','영광의 소망 주 다시 오리 깨어서 기다려 주 섬기리<br/>푯대를 향하여 좇아가며 왕국의 상 얻는 사람 되리<br/>',NULL,33369,5);
INSERT INTO stanza VALUES('K767','1','피조물-은- 하나님-의<br/>아들들을- 고대해<br/>하-나-님의 아-들-들의<br/>자-유- 안-에- 가려고<br/>',NULL,33370,1);
INSERT INTO stanza VALUES('K767','2','피조물-이- 탄식하-며<br/>허무한 데- 굴복해<br/>완-전- 해방 이-뤄-질 때<br/>썩-어-짐-을- 벗겠네<br/>',NULL,33371,2);
INSERT INTO stanza VALUES('K767','3','우리들-도- 아들 명-분<br/>탄식하며- 기다려<br/>그-리-스도 신-장-까지<br/>성-숙-해-야- 하겠네<br/>',NULL,33372,3);
INSERT INTO stanza VALUES('K767','4','이를 위-해- 성령 또-한<br/>탄식하며- 기도해<br/>모-든- 것이 협-력-하여<br/>주-의- 형-상- 닮게 해<br/>',NULL,33373,4);
INSERT INTO stanza VALUES('K767','5','하나님-이- 영광 안-에<br/>나를 인도-하실 때<br/>나-는- 주로 적-셔-져서<br/>거-룩-하-게- 되겠네<br/>',NULL,33374,5);
INSERT INTO stanza VALUES('K767','6','피조물- 다- 해방되-어<br/>영광 자유- 들어가<br/>표-범-과 양 사-자-와 소<br/>함-께- 풀-을- 뜯겠네<br/>',NULL,33375,6);
INSERT INTO stanza VALUES('K767','7','주와 함-께- 후사 되-어<br/>아들 명분- 받을 때<br/>주-와- 함께 형-제-들과<br/>하-나-님- 나-타내리<br/>',NULL,33376,7);
INSERT INTO stanza VALUES('K768','1','하나님의 중심 뜻 사람과 연결하여<br/>그가 모든 것 되어 계획 성취함일세<br/>',NULL,33377,1);
INSERT INTO stanza VALUES('K768','2','흙으로 만든 사람 영과 혼과 몸 있네<br/>하나님을 받아서 생명 삼을 수 있네<br/>',NULL,33378,2);
INSERT INTO stanza VALUES('K768','3','생명이 흐를 때에 사람은 보석 되어<br/>주의 성전 건축해 그의 영광 나타내<br/>',NULL,33379,3);
INSERT INTO stanza VALUES('K768','4','이것은 거룩한 성 그의 사모하던 집<br/>하나님의 원하던 새 예루살렘일세<br/>',NULL,33380,4);
INSERT INTO stanza VALUES('K768','5','하나님과 사람들 하나된 건축일세<br/>하나님과 사람이 함께 만족 누리네<br/>',NULL,33381,5);
INSERT INTO stanza VALUES('K768','6','하나님과 어린 양 보좌 위에 계시네<br/>권위의 중심에서 생명수 강 흐르네<br/>',NULL,33382,6);
INSERT INTO stanza VALUES('K768','7','주는 생명의 나무 강 좌우에 자라네<br/>생명 열매 맺어서 성도들 공급하네<br/>',NULL,33383,7);
INSERT INTO stanza VALUES('K768','8','하나님은 주 안에 빛이 되어 비취네<br/>어둠은 다시 없고 영광의 빛 황홀해<br/>',NULL,33384,8);
INSERT INTO stanza VALUES('K768','9','주는 사람 안에서 사람은 주 안에서<br/>사람 안엔 하나님 사람은 주의 표현<br/>',NULL,33385,9);
INSERT INTO stanza VALUES('K769','1','하나님의 뜻은 사람과 합해 사람들이 그의- 그릇 되는 것<br/>그와 사람들이 하나됨-으-로 그가 사람 생-명-되기 원하네<br/>',NULL,33386,1);
INSERT INTO stanza VALUES('K769','2','그의 형상대로 사람 지어서 그의 갈망 이룰- 자격 주셨네<br/>생명나무로서 자신 주-시-어 하나님의 충-만-되게 하셨네<br/>',NULL,33387,2);
INSERT INTO stanza VALUES('K769','3','그의 생명 흐름 사람 변케 해 그를 닮은 귀한- 재료 되게 해<br/>그의 거처로서 건축하-시-고 그의 배필 삼-아- 누리게 하네<br/>',NULL,33388,3);
INSERT INTO stanza VALUES('K769','4','이는 거룩한 성 새 예루살렘 하나님과 성도- 연합함일세<br/>그는 내용이요 그들은- 표-현 영원토록 서-로- 안에 거하네<br/>',NULL,33389,4);
INSERT INTO stanza VALUES('K769','5','유일하신 중심 주 하나님이 보좌서 다스려- 생명 권위로<br/>그의 영광 비춰 빛 속에- 살-며 서로 하나 되-어- 그를 나타내<br/>',NULL,33390,5);
INSERT INTO stanza VALUES('K769','6','하나님은 생수 생명떡이니 성도들의 모든- 공급 되시네<br/>성전인 주 안에 그들 거-하-며 그 얼굴 빛 안-에- 영영 경배해<br/>',NULL,33391,6);
INSERT INTO stanza VALUES('K77','1','지극히 높 - 고 영광스런 하나님 자기를 낮 - 추사<br/>사람의 모 - 양으 - 로 와 사람과 같이 됐네<br/>',NULL,33392,1);
INSERT INTO stanza VALUES('K77','2','육신의 휘 - 장 통 - 해서 하나님 영 - 광 나타내려<br/>메마른 이 - 땅 가 - 셨네 인자이신 주님<br/>',NULL,33393,2);
INSERT INTO stanza VALUES('K77','3','고통과 괴 - 롬 있 - 어도 멸시와 천 - 대 받 - 아도<br/>아버지 뜻 - 을 위 - 하여 요동치 않았네<br/>',NULL,33394,3);
INSERT INTO stanza VALUES('K77','4','온유하고 - 겸손 - 한 맘 어떤 환경이나 다 - 받아<br/>하나님에게나 사람에게 원망이 없었네<br/>',NULL,33395,4);
INSERT INTO stanza VALUES('K77','5','누구에게 - 도 자 - 신을 의탁하지 않고 아름답게<br/>인생길 가 - 신 주 - 예수 하나님 어린 양<br/>',NULL,33396,5);
INSERT INTO stanza VALUES('K77','6','하나님 뜻 - 만 간 - 직해 사탄의 시 - 험 물 - 리쳐<br/>충성스럽 - 고 완 - 전한 주는 하나님 종<br/>',NULL,33397,6);
INSERT INTO stanza VALUES('K77','7','아버지 뜻 - 을 순 - 종해 기꺼이 죽 - 음의 - 길 간<br/>당신은 십 - 자가 - 위에 자신을 버렸네<br/>',NULL,33398,7);
INSERT INTO stanza VALUES('K77','8','이제는 존 - 귀 영광 받고 보좌에 앉 - 은 주 - 예수<br/>하늘과 땅 - 의 모든 무릎 당신께 경배해<br/>',NULL,33399,8);
INSERT INTO stanza VALUES('K770','1','오 주의 살렘 주의 건축 은혜를 입은 모든 죄인 위한 성<br/>피 구속함 받고 정결케 된 자 그 안에 들어 갈 권세 받았네<br/>그 영광만도 날 사모케 하네 그 곳에 내 주가 거하신다네<br/>내 어찌 그곳을 주목 안 하리 매순간 매순간 생각케 되네<br/>',NULL,33400,1);
INSERT INTO stanza VALUES('K770','2','오 주의 살렘 생각할 때 주 얼굴 뵈옵기를 고대케 되네<br/>곧 들림 받아서 주께 기대어 새 땅서 주 사랑하기 원하네<br/>끝없고 무한한 주님의 사랑 모든 성도들과 늘 찬송하리<br/>늘 자아 버리신 주님의 사랑 그 발자취 항상 기념하겠네<br/>',NULL,33401,2);
INSERT INTO stanza VALUES('K770','3','내 사모하고 기뻐함은 홍보석 녹보석이 결코 아니요<br/>벽옥도 정금도 다 아니라오 내 사모 내 사랑 오직 주님뿐<br/>주 나를 얼마나 사랑하는지 얼마나 내 마음 매혹하는지<br/>더 이별 없도록 날 들어 올려 주님과 늘 함께 있게 하소서<br/>',NULL,33402,3);
INSERT INTO stanza VALUES('K770','4','오 주의 살렘 빛이시니 그 안에 주가 중심 보상 되시네<br/>내 사랑하는 주 거기 계시니 살렘이 나에게 소망 되었네<br/>당신이 있기에 만물 새롭고 탄식 지나가고 눈물도 없네<br/>내 맘에 안식과 기쁨 넘치리 주여 왜 신속히 안 오십니까<br/>',NULL,33403,4);
INSERT INTO stanza VALUES('K771','1','한- 성 기다리며 장막-에 거해<br/>그- 나그네 계속 전진-하였네<br/>아름-다운 증거 영광-된 장래<br/>주목-하며 땅의 영화- 버렸네<br/>',NULL,33404,1);
INSERT INTO stanza VALUES('K771','chorus','오 아름다운 성 오 영-원한 거처 새 예-루살렘<br/>',NULL,33405,2);
INSERT INTO stanza VALUES('K771','2','하-나님의 거처 그 성- 기다려<br/>땅- 위 집을 사모하지- 않았네<br/>올바-른 길 가는 나그-네만이<br/>하늘-에 속한 참 본향- 누리리<br/>',NULL,33406,3);
INSERT INTO stanza VALUES('K771','3','한- 성 기다리네 고생- 많아도<br/>그- 성 생각할 때 노래-하게 돼<br/>이 길- 험악해도 탄식- 그치네<br/>이 길- 길지 않음 나 알-고 있네<br/>',NULL,33407,4);
INSERT INTO stanza VALUES('K771','4','그-와같이 오늘 우린- 기다려<br/>주- 성에서 영영 주 누-리기를<br/>주 동-반자 되어 함께- 누리려<br/>이 땅-에서 주와 나그-네 되리<br/>',NULL,33408,5);
INSERT INTO stanza VALUES('K772','1','주 계신 성 곧 거룩한- 성은- 우리의 목표<br/>영원한- 분깃 찬란하고 또 영광스런 성-<br/>내 몸은 여기 있으나 영은 그곳에<br/>속히 주 함께 있길 나는 갈망해<br/>',NULL,33409,1);
INSERT INTO stanza VALUES('K772','2','거룩한 목표 새 예루-살렘- 하나님 사람<br/>위해 예비했네 보혈로 구속받은 모든 자-<br/>이 복된 분깃 누릴 권리 얻었네<br/>이 복된 분깃 누릴 권리 얻었네<br/>',NULL,33410,2);
INSERT INTO stanza VALUES('K772','3','오 거룩한 성 바라볼 때마다- 은혜로운<br/>주 얼굴 보기 원해 속히 주 음성 듣고 들어가-<br/>그 성의 풍성 영영 누리기 원해<br/>그 성의 풍성 영영 누리기 원해<br/>',NULL,33411,3);
INSERT INTO stanza VALUES('K772','4','내 사모하며 바라던- 것은- 달콤한 안식<br/>축복 아-닐세 영광의 소망 영원한 분깃-<br/>내 상인 주님 자신 기다려왔네<br/>내 상인 주님 자신 기다려왔네<br/>',NULL,33412,4);
INSERT INTO stanza VALUES('K772','5','오 주여 주를 사랑하는 자들- 이끌어<br/>당신 앞에 올리소서 거룩한 성의 당신 누리며-<br/>늘 함께 거하면서 영광 얻으리<br/>늘 함께 거하면서 영광 얻으리<br/>',NULL,33413,5);
INSERT INTO stanza VALUES('K772','6','모든 것 그때 새롭게- 되리- 새 하늘 새 땅<br/>새 성 새- 사람 영광의 주 내 영원한 분깃-<br/>오 주여 어서 나타나시옵소서<br/>오 주여 어서 나타나시옵소서<br/>',NULL,33414,6);
INSERT INTO stanza VALUES('K773','1','달려갈 길 다 마치고 선한 싸움 싸운 때<br/>들림 받고 주 영광에 들어가<br/>믿음의 도 지켜 순교 무서워하지 않아<br/>거룩한 성 얻으리<br/>',NULL,33415,1);
INSERT INTO stanza VALUES('K773','chorus','들림 받아 영광 안에 주와 함께 들어가<br/>새 예루살렘 새 예루살렘<br/>이긴 자들 모두 함께 기뻐하며 노래해<br/>새 예루살렘에서<br/>',NULL,33416,2);
INSERT INTO stanza VALUES('K773','2','지금 이방땅에 나그네 돼 표류하여도<br/>좋은 본향 바라보며 즐거워<br/>친구들은 세상 축복 제일 귀히 여겨도<br/>나는 거룩한 성 봐<br/>',NULL,33417,3);
INSERT INTO stanza VALUES('K773','3','거친 길을 행할 때에 나의 다리 저리고<br/>나의 손에 힘이 빠질지라도<br/>그 성 생각할 때 힘이 솟네 낙심치 않네<br/>그 성 나의 참 보상<br/>',NULL,33418,4);
INSERT INTO stanza VALUES('K773','4','오늘 나의 싸움 허공 치는 것이 아닐세<br/>향방 없이 달리는 것 아닐세<br/>뒤의 것은 잊고 앞에 있는 것을 잡으려<br/>푯대 향해 달리네<br/>',NULL,33419,5);
INSERT INTO stanza VALUES('K773','chorus','주의 사랑 주의 은혜 나로 들어가게 해<br/>새 예루살렘 새 예루살렘<br/>모든 성도 기뻐 뛰며 소리 합해 찬양해<br/>새 예루살렘에서<br/>',NULL,33420,6);
INSERT INTO stanza VALUES('K774','1','태초에는 한 동산이었네 마지막에는 한 성이 됐네<br/>동산은 주의 창조였으나 성은 곧 주의 건축이라네<br/>',NULL,33421,1);
INSERT INTO stanza VALUES('K774','2','동산에서나 성 안에서나 생명나무와 강이 중심돼<br/>강은 곧 생명 흐르는 성령 나무는 생명 공급인 주님<br/>',NULL,33422,2);
INSERT INTO stanza VALUES('K774','3','동산에서나 그성에서나 세 가지 귀한 재료 있으니<br/>정금과 진주 보석은 모두 하나님 어떠하심 표현해<br/>',NULL,33423,3);
INSERT INTO stanza VALUES('K774','4','동산에서는 재료였으나 성 안에서는 건축되었네<br/>하나님 영광 나타내는 성 하나님 영원한 거처 됐네<br/>',NULL,33424,4);
INSERT INTO stanza VALUES('K774','5','동산의 사람 흙으로 되어 그 안에 하늘 영광 없었네<br/>생명나무는 밖에 있어서 그들의 생명 되지 않았네<br/>',NULL,33425,5);
INSERT INTO stanza VALUES('K774','6','성 안에서는 생명나무가 사람들 속에 자라며 거해<br/>그리스도가 사람 속에서 생명을 공급하심 말하네<br/>',NULL,33426,6);
INSERT INTO stanza VALUES('K774','7','이 성 위하여 지어진 사람 반드시 다시 태어나야 해<br/>본질과 모양 변화되어서 주 몸 돼 주를 나타내야 해<br/>',NULL,33427,7);
INSERT INTO stanza VALUES('K774','8','동산에 있는 아담의 배필 아담에게서 나온 여자듯<br/>거룩한 성은 주의 신부니 주 풍성에서 나온 주 충만<br/>',NULL,33428,8);
INSERT INTO stanza VALUES('K774','9','거룩한 성은 주님의 건축 온 성도들의 집합체일세<br/>하나님 거처 영원한 처소 주님을 만족게 하는 신부<br/>',NULL,33429,9);
INSERT INTO stanza VALUES('K774','10','하나님 최종 충만한 표현 거룩하고도 우주적인 몸<br/>삼일 하나님 영광 나타내 그리스도의 영원한 배필<br/>',NULL,33430,10);
INSERT INTO stanza VALUES('K775','1','주가 구속하신 백성 주의 몸 주의 신부<br/>주의 풍성 나타내는 주의 충만 또 표현<br/>그의 모-든 것이 되신 주의 은-혜 선포해<br/>주 영광에 참-예토록 주로 적-셔 주소서<br/>',NULL,33431,1);
INSERT INTO stanza VALUES('K775','chorus','보라 거룩한 성 하나님 충만해<br/>인성 통해 나타나는 하나님 표현<br/>',NULL,33432,2);
INSERT INTO stanza VALUES('K775','2','경건의 큰 비밀이여 하나님 사람 연합<br/>하나님의 영광만이 충만하고 찬란해<br/>하나님-의 모든 충만 온전하-게 표현한<br/>우주 안의 위-대한 몸 크신 그-릇이로다<br/>',NULL,33433,3);
INSERT INTO stanza VALUES('K775','3','하나님이 변화시킨 사람들의 집합체<br/>진주처럼 보석처럼 주 영광에 부합돼<br/>성의 중-심 보좌에서 생명 생-수 흐르네<br/>생명나무 이-신 주님 새 열매- 늘 풍성해<br/>',NULL,33434,4);
INSERT INTO stanza VALUES('K775','4','밝은 등인 그리스도 붙드는 정금 등대<br/>하나님은 주 안에서 성의 영광 되시네<br/>하나님-이 건축하신 최종 완-성인 표현<br/>하나님과 사-람 거처 주 계획-의 목푤세<br/>',NULL,33435,5);
INSERT INTO stanza VALUES('K776','1','영광스럽-고 거-룩해 빛나는 새- 예루-살렘<br/>하나님의 장막이요 어린양의 신부-일세<br/>',NULL,33436,1);
INSERT INTO stanza VALUES('K776','2','신약의 성-도 구약 백성 모두가 거룩한 성- 이뤄<br/>함께 약속을 받아서 건축되어 주 안주케 해<br/>',NULL,33437,2);
INSERT INTO stanza VALUES('K776','3','길이와 너-비 높-이가 똑같은 완전한 성-이여<br/>구부러진 것이 없이 모두가 곧게 서- 있네<br/>',NULL,33438,3);
INSERT INTO stanza VALUES('K776','4','정금성 정-금거-리는 유리와 같-이 투-명해<br/>하나님 존귀한 생명 이 성의 본질 본성일세<br/>',NULL,33439,4);
INSERT INTO stanza VALUES('K776','5','그리스도-의 구속으로 열 두 문 모-두 진-주니<br/>거룩한 모든 것들이 여기서부터 시-작돼<br/>',NULL,33440,5);
INSERT INTO stanza VALUES('K776','6','성벽의 열-두 기-초석 열 두 보석으로 되-었네<br/>압력과 불을 거쳐서 영원히 가치 있-게 돼<br/>',NULL,33441,6);
INSERT INTO stanza VALUES('K776','7','수정 같은- 성벽- 벽옥 하나님 빛-을 비-추네<br/>하나님 영광 발산해 하나님 형상 나-타내<br/>',NULL,33442,7);
INSERT INTO stanza VALUES('K776','8','성벽이 경-계 됨-으로 속됨과 부정함 거-절해<br/>정금 진주 보석만이 거룩한 성에 부-합해<br/>',NULL,33443,8);
INSERT INTO stanza VALUES('K776','9','이 성전 안-의 모든 사람 그 영광 얼-굴 늘- 보리<br/>하나님 임재 영원해 그분 앞에서 경-배해<br/>',NULL,33444,9);
INSERT INTO stanza VALUES('K776','10','하나님 주야로 비-추니 해나 달빛-이 필요없네<br/>어린 양이 곧 등이요 성은 곧 그의 등-댈세<br/>',NULL,33445,10);
INSERT INTO stanza VALUES('K776','11','하나님 어린양 보좌에서 생명수 강-이 흘-러나<br/>성 안의 길로 흘러서 생명나무가 자-라네<br/>',NULL,33446,11);
INSERT INTO stanza VALUES('K776','12','하나님 생-명 흘-러나 온 성을 적-셔 공-급해<br/>주 하나님의 권위가 온 성을 통해 역 -사해<br/>',NULL,33447,12);
INSERT INTO stanza VALUES('K776','13','신성이 길-이 되-므로 정금과 진-주 가-득해<br/>행할 길 마실 물 있고 생명의 양식 풍-성해<br/>',NULL,33448,13);
INSERT INTO stanza VALUES('K776','14','영원히 완전함 나타내는 열 둘로 가득한 성-이여<br/>하나님과 사람들의 완전한 연합 나-타내<br/>',NULL,33449,14);
INSERT INTO stanza VALUES('K776','15','다시는 사-망 밤-없네 저주와 고-통 끝-났네<br/>옛 것은 다 지나가고 모든 것 새롭게- 됐네<br/>',NULL,33450,15);
INSERT INTO stanza VALUES('K776','16','하나님 형-상 나-타내 하나님 위-해 통-치해<br/>하나님 만족게 하며 하나님 뜻을 이-룬 성<br/>',NULL,33451,16);
INSERT INTO stanza VALUES('K777','1','새 하늘과 새 땅의 새 예루살렘 성<br/>하나님에게서 나 거룩한 빛 있네<br/>',NULL,33452,1);
INSERT INTO stanza VALUES('K777','chorus','보라 하나님 형상 하나님의 영광을<br/>주와 함께 다스려- 아- 거룩한 성<br/>',NULL,33453,2);
INSERT INTO stanza VALUES('K777','2','성과 그 안의 길 다 맑은 정금이요<br/>벽과 기초는 보석 성문은 진주라<br/>',NULL,33454,3);
INSERT INTO stanza VALUES('K777','3','수정 같은 생명강 길 가운데 흘러<br/>강 좌우의 나무가 모든 필요 채워<br/>',NULL,33455,4);
INSERT INTO stanza VALUES('K777','4','하나님이 그 성의 모든 것이 되셔<br/>어린 양인 등 안에 하나님이 빛 돼<br/>',NULL,33456,5);
INSERT INTO stanza VALUES('K778','1','신 구약 안의 백성은 주님의 신부와 건축<br/>신부는 신랑의- 배-필 건축은 안식할 처소<br/>',NULL,33457,1);
INSERT INTO stanza VALUES('K778','2','구약의 여자와 건축 이는 곧 교회 예표니<br/>여자는 아담의- 배-필 건축은 주의 안식처<br/>',NULL,33458,2);
INSERT INTO stanza VALUES('K778','3','저 이스라엘 백성을 아내라 부른 하나님<br/>성전에 거주하-시-며 그 성을 다스리셨네<br/>',NULL,33459,3);
INSERT INTO stanza VALUES('K778','4','사람이 되신 하나님 그는 곧 신랑이시니<br/>그들을 거듭나-게- 해 그분의 배필 되게 해<br/>',NULL,33460,4);
INSERT INTO stanza VALUES('K778','5','부활한 그리스도는 솔로몬처럼 건축해<br/>하나님 처소 지-으-사 그분의 갈망 이뤘네<br/>',NULL,33461,5);
INSERT INTO stanza VALUES('K778','6','교회는 주의 신부니 주의 맘 기쁘게 하네<br/>교회는 하나님- 거-처 하나님 거하게 하네<br/>',NULL,33462,6);
INSERT INTO stanza VALUES('K778','7','신부와 건축의 성취 완전한 새 예루살렘<br/>하나님 마음과- 뜻-을 만족게 하는 성일세<br/>',NULL,33463,7);
INSERT INTO stanza VALUES('K778','8','이는 곧 주님의 배필 주님의 신부 또 충만<br/>이 장막 안에 영-원-히 하나님 안주하시네<br/>',NULL,33464,8);
INSERT INTO stanza VALUES('K778','9','하나님 역사의 완성 신성한 하나님 표현<br/>영원하고도 거 -룩-한 새 예루살렘 성이여<br/>',NULL,33465,9);
INSERT INTO stanza VALUES('K779','1','하나님의 경륜은 곧 주 안에 다 통일돼<br/>주가 머리 중심 되어 만유 화답함일세<br/>',NULL,33466,1);
INSERT INTO stanza VALUES('K779','2','그리스도 중심 되고 하나님은 빛이 돼<br/>보좌에서 주 하나님 갈망 모두 이루네<br/>',NULL,33467,2);
INSERT INTO stanza VALUES('K779','3','주가 생명 내용 되어 만유 통일 된다네<br/>성도들은 그릇 되어 그의 영광 나타내<br/>',NULL,33468,3);
INSERT INTO stanza VALUES('K779','4','사탄 만유 파괴하려 사람 속에 들어와<br/>흑암 부패 혼란으로 하나님 뜻 방해해<br/>',NULL,33469,4);
INSERT INTO stanza VALUES('K779','5','주 오셔서 사람 속에 생명 분배하시어<br/>사람 구해 흑암 사망 힘 못쓰게 하셨네<br/>',NULL,33470,5);
INSERT INTO stanza VALUES('K779','6','그의 몸인 교회 인해 만유 통일된다네<br/>만유가 다 합당하게 질서 안에 연합돼<br/>',NULL,33471,6);
INSERT INTO stanza VALUES('K779','7','머리이신 주 아래서 만유 연결되겠네<br/>그의 교회 빛 가운데 만유 통일된다네<br/>',NULL,33472,7);
INSERT INTO stanza VALUES('K779','8','주가 머리 중심 될 때 만유 화목되겠네<br/>그의 몸의 비춤 통해 만유 화합된다네<br/>',NULL,33473,8);
INSERT INTO stanza VALUES('K779','9','다시 흑암 죽음 없네 부패 공허 더 없네<br/>만유 전체 해방되어 영원 자유 누리네<br/>',NULL,33474,9);
INSERT INTO stanza VALUES('K78','1','인자하 - 고 아 - 름다워 주님 - 의 가신 길<br/>인성 - 안의 비범 - 한 삶 날 놀 - 라게 하네<br/>',NULL,33475,1);
INSERT INTO stanza VALUES('K78','2','고난의 - 길에 - 나타난 인내 - 의 참 사랑<br/>죽기 - 까지 고통 - 당한 비교 - 못할 사랑<br/>',NULL,33476,2);
INSERT INTO stanza VALUES('K78','3','무거운 - 짐 지 - 신 주님 늘 질 - 고 지셔도<br/>그 입 - 에는 단 한 - 번도 원망 - 이 없었네<br/>',NULL,33477,3);
INSERT INTO stanza VALUES('K78','4','질투 욕 - 설 배 - 신에도 분노 - 하지 않고<br/>너그 - 러이 용서 - 하신 주 맘 - 엔 사랑뿐<br/>',NULL,33478,4);
INSERT INTO stanza VALUES('K78','5','소제 같 - 은 주 - 의 일생 부드럽고 향긋해<br/>하나 - 님과 사람 - 앞에 균형 있고 완전해<br/>',NULL,33479,5);
INSERT INTO stanza VALUES('K780','1','그날 내 주의 보물 더 감춰지잖고<br/>변화된 사람 통해 아름답게- 보여<br/>',NULL,33480,1);
INSERT INTO stanza VALUES('K780','2','위대한 정금 그릇 주 영광 비추네<br/>하나님 빛이시니 해나 달 없-다네<br/>',NULL,33481,2);
INSERT INTO stanza VALUES('K780','3','온 성의 진주 보석 하나님 나타내<br/>벽옥의 영광 광채 찬란히 비-취리<br/>',NULL,33482,3);
INSERT INTO stanza VALUES('K780','4','위대한 그릇 통해 영광 빛 나타나<br/>사방에 충만한 빛 어둠 다 몰-아 내<br/>',NULL,33483,4);
INSERT INTO stanza VALUES('K780','5','모든 새 피조물이 주의 빛 보리라<br/>빛나는 그 그릇은 어린 양의- 신부<br/>',NULL,33484,5);
INSERT INTO stanza VALUES('K780','6','영광의 정금 그릇 주 경배케 하리<br/>어린 양 안에 영영 하나님 나-타나<br/>',NULL,33485,6);
INSERT INTO stanza VALUES('K781','1','주- 여호와 그- 이름이 어찌 뛰어난지-요<br/>온- 세상과 온- 백성이 주의 가치 선-포-해<br/>어린 아이-와- 젖먹이 입-으 로 찬-양 세워<br/>원수를 잠잠케- 하-며 그날을 속히 끝내네<br/>',NULL,33486,1);
INSERT INTO stanza VALUES('K781','2','우리가 보니 주의 손가락으로 만드신 우주와<br/>베푸신 해와 달과 별들이 당신의 지혜를 말하네<br/>사람이 무엇이관대 주가 저를 권고 하-십니까<br/>당신의 영원한 경륜 안에 인자로 오신 주실세<br/>',NULL,33487,2);
INSERT INTO stanza VALUES('K781','3','오- 주 예수 당신은 바로 임마누엘 주십니다<br/>혈육을 입고 종의 형체를 취해 나타나셨었지만<br/>지금은 영광 존귀 관 쓰고 모든 권위 다- 얻었네<br/>당신의 몸으로 말미암아 만유를 통치하시네<br/>',NULL,33488,3);
INSERT INTO stanza VALUES('K781','4','주의 성육신 부활과 승천 주의 머리 되심-과<br/>충만한 왕국 주의 몸 또한 여기에서 본-다-네<br/>이 신성한 역사를 인하여 당신의 찬양- 세웠네<br/>우리 마음은 기쁨 넘치어 주님만 찬송하겠네<br/>',NULL,33489,4);
INSERT INTO stanza VALUES('K781','5','아- 복된 날 그 즐거움을 만민 함께 찬양하리<br/>우리는 지금 교회 안에서 그- 실재 먼저 맛보네<br/>주 여호와- 그- 이름이 어찌 그리 뛰어나신지<br/>온 세상 모두 주의 이름을 다 선포하게 하시네<br/>',NULL,33490,5);
INSERT INTO stanza VALUES('K782','1','왕후는 오빌의 금을 꾸미고 우편에서<br/>내 왕의 귀비 중에는 열왕의 딸들 있네<br/>영광스러운 교회가 왕후요 배필이 돼<br/>모든 성도여 이 모두 우리의 영화로다<br/>',NULL,33491,1);
INSERT INTO stanza VALUES('K782','chorus','주와 함께 앞날에 그 영광을 누리리니<br/>내 기쁨 끝없네<br/>',NULL,33492,2);
INSERT INTO stanza VALUES('K782','2','딸이여 듣고 생각해 귀 기울일지어다<br/>네 백성 네 아비집을 잊어버릴지어다<br/>왕께서 너의 미모를 흠모하실지로다<br/>저는 네 주가 되시니 너는 경배할지라<br/>',NULL,33493,3);
INSERT INTO stanza VALUES('K782','3','왕녀의 화려한 의복 금으로 짜여졌네<br/>왕국의 내실에 있어 모든 영화 누리네<br/>하나님 영광스러운 본성의 모든 것을<br/>그에게 입혀 주시니 하나님만 나타나<br/>',NULL,33494,4);
INSERT INTO stanza VALUES('K782','4','수놓은 옷을 입고서 왕께로 인도받네<br/>세마포 의복은 그의 의로운 행실일세<br/>성령의 봉사와 직분 주 안에 이뤄질 때<br/>이 영광스런 옷 입고 왕께 칭찬 얻으리<br/>',NULL,33495,5);
INSERT INTO stanza VALUES('K782','5','우리의 왕 얼굴 뵐 때 그 기쁨 형용 못해<br/>소리 높여 찬미하세 영원히 즐겁게<br/>다 함께 왕께 경배해 왕후를 자랑하세<br/>이같은 누림 가운데 주께 영광 있으리<br/>',NULL,33496,6);
INSERT INTO stanza VALUES('K783','1','성소와 궁창에서 찬양하세<br/>그의 능한 행동을 찬양할지라<br/>주의 높고 광대하심 찬양할지라<br/>나팔 소리로 찬양하세 비파 수금으로 찬양해<br/>소고치며 춤추면서 현악과 퉁소 불며 찬양해<br/>큰 소리나는 제금으로 높은 소리의 제금으로<br/>호흡이 있는 자마다 찬양 할렐루야<br/>',NULL,33497,1);
INSERT INTO stanza VALUES('K784','1','사랑스-런 주의 장-막 이는 바로 교-횔세<br/>나의 혼-이 주의 궁-정 사모하여 쇠약했네<br/>나의 맘-과 나의 영혼-이 사모하-고 갈망하는<br/>온- 땅 위-의 교-회 회복 위-해 간구하며 부르짖네<br/>',NULL,33498,1);
INSERT INTO stanza VALUES('K784','2','그 마음-에 시온 대-로 있는 자는 복이 있네<br/>주께 힘-을 얻는 자-는 항상 주를 찬양하리<br/>교회 안-에 교통하-며 주 의지하며 찬양하리<br/>눈-물 골짜기 통-행할 때 그-곳 많은 샘의 곳 되게 해<br/>',NULL,33499,2);
INSERT INTO stanza VALUES('K784','3','교회 안-의 하루는- 다른 곳 천 날보다 나아<br/>제일 작-은 지체에게도 주는 해요 방패시며<br/>은혜 영-화 모든 좋은 것 아끼시-지 아니하니<br/>주-의 교회에 영원히 거하는- 자 그는 복-이 있도다<br/>',NULL,33500,3);
INSERT INTO stanza VALUES('K785','1','이는 내 쉴 곳 영원히 거할 나의 안식처라<br/>내가 이 성의 식료품에 복주리<br/>양식으로 빈민 풍족게 하리<br/>구원으로 제사장 입히리니<br/>성도들 즐거이 외치리라<br/>',NULL,33501,1);
INSERT INTO stanza VALUES('K786','1','오 주 예수나 홀로헤매일 때 당신은 내게알려주셨지<br/>양 떼의발자취를 따라 올- 때 날 집으로 인도하리라고<br/>얼마나 빨리 나는 달려 왔던가 그때당신은 내게말했지<br/>“내사랑아 넌 바로의 준마처럼 어리고 고집세도 날 사랑하누나”<br/>',NULL,33502,1);
INSERT INTO stanza VALUES('K786','2','아 나는귀한나의사랑찾았네 그 집은아늑하고 따뜻해<br/>옛날염려다 잊고기쁨누릴때 그는 내 생각변케하셨네<br/>내 주의아름다운 얼굴외에는 아무것도내 눈에뵈잖아<br/>그는또“비둘기같은 네 눈-에 순진함 총명함 가득 찼다”하네<br/>',NULL,33503,2);
INSERT INTO stanza VALUES('K786','3','당신 안에서 세월보내면-서 난 자신을 믿지 않게 됐네<br/>내 약함깨닫던 나는마침-내 절망하여 당신붙잡았지<br/>당신을 의지하고 보호받을 때 난 향기로운 백합되었네<br/>당신의 사랑먹고가시밭에 핀 단순하고 부드러운 꽃 되었네<br/>',NULL,33504,3);
INSERT INTO stanza VALUES('K786','4','상처받은 당신의 옆구리-는 아직은 고통있는안식처<br/>바위틈 낭떠러지 은밀한 곳에당신의 비둘기 살고있네<br/>사망의 깊음속에서도 당신은 항상내게가까이 계시네<br/>이제난 당신안에높여지-네 당신의 보좌향해모든것 밟고<br/>',NULL,33505,4);
INSERT INTO stanza VALUES('K786','5','광야 헤매던 길고어두운- 밤 사망은 깊고아픔은 중해<br/>원수에게 시달리며 쓰러-져 잔인한 사망에 묻혔지만<br/>부활은 영광스러운 것이었네 향기론 몰약과 단 유향이<br/>시험받던 고뇌의 연기 지우고 우뚝선 기둥으로 변케하였네<br/>',NULL,33506,5);
INSERT INTO stanza VALUES('K786','6','고집꺾인난 자신의 길 떠-나 이젠내가더 이상 살지 않네<br/>그의역사내 생각새롭게- 해 내 맘은그의침상되었네<br/>영광스런 우리왕을태우- 는 연이 될 때 난 더 영광이네<br/>주여난 모든것을포함한- 연 당신을 나타내는 당신의 그릇<br/>',NULL,33507,6);
INSERT INTO stanza VALUES('K786','7','이 그릇에 당신가득채울 - 때 이 땅 위에당신걸어가네<br/>지극히 귀한당신나타내-는 구속의 은과 나무와 정금<br/>사람의 생명은 바로나무-요 당신의 본성은 정금이라<br/>자색보좌는 왕인당신말-해 그 안에서 우리사랑하나되네<br/>',NULL,33508,7);
INSERT INTO stanza VALUES('K786','8','빨리 당신의 영광면류관- 돼 당신의 자랑과 기쁨되리<br/>준마가 면류관이 되는 이야기 당신의 은혜놀라운 변화<br/>그러나 아직여러그늘속-에 낮을사모하며 난 서성여<br/>몰약의 산 당신에게 달려-가 유향의 언덕에 늘 머물고 싶네<br/>',NULL,33509,8);
INSERT INTO stanza VALUES('K786','9','초월하여 당신과 함께있어도 당신은 날 이땅에 두시네<br/>생명의 샘물넘쳐흘러나-는 당신의 동산 되게 하려고<br/>당신으로 이미만족했으-니 당신기쁨위해순종하리<br/>거룩한 열매맺는동산되-어 당신의 소원이루어질 때까지<br/>',NULL,33510,9);
INSERT INTO stanza VALUES('K786','10','동산서 얻네 아름다운 신-부 새 예루살렘의건축재료<br/>아름다운 성과엄위한 군-대 사탄을 영원히 멸한군대<br/>당신의 영원한 목적이뤄질 때 우린 당신의 영광스런 신부<br/>오 주여영원한 처소건축될 때 당신은 온전히 만족하시겠죠<br/>',NULL,33511,10);
INSERT INTO stanza VALUES('K787','1','주는 그의 사랑하는 자 만들어 가고 있네<br/>기둥으로 침상 연으로 영광 면류관으로<br/>',NULL,33512,1);
INSERT INTO stanza VALUES('K787','chorus','그가 얼마나 사랑하는 지 그의 사랑하는 자<br/>그는 온전히 사로 잡혔네 어여쁜 그 사랑에<br/>',NULL,33513,2);
INSERT INTO stanza VALUES('K787','2','아직 그늘 남아 있으니 주는 만족 못하네<br/>사랑스런 신부 될 동산 그는 얻기 원하네<br/>',NULL,33514,3);
INSERT INTO stanza VALUES('K787','3','석류나무 각종 과수와 고벨화와 나도초<br/>번홍화와 몰약과 침향 이는 그의 즐거움<br/>',NULL,33515,4);
INSERT INTO stanza VALUES('K787','4','그는 그의 동산에 와서 귀한 향품 모았네<br/>꿀송이와 꿀을 먹었네 젖과 포도주 마셨네<br/>',NULL,33516,5);
INSERT INTO stanza VALUES('K787','5','동산에서 공급한다네 성을 건축할 재료<br/>대적 모두 소멸될 때에 주는 만족하시리<br/>',NULL,33517,6);
INSERT INTO stanza VALUES('K787','6','내 사랑아 너의 어여쁨 디르사와 같구나<br/>예루살렘처럼 곱고도 군대같이 엄위해<br/>',NULL,33518,7);
INSERT INTO stanza VALUES('K787','7','내 주 예수 그가 반드시 이 모든 것 이루리<br/>할렐루야 할렐루-야 할렐루야 아-멘<br/>',NULL,33519,8);
INSERT INTO stanza VALUES('K788','1','오 주 예수여 사랑합니다 당신의 깊은 사랑<br/>나를 이끄니 다만 당신 찾으려 달려 갑니다<br/>내 사랑이여 전체가 사랑스런 내 마음의 기-쁨이여<br/>내 사랑이여 전체가 사랑스런 내 마음의 기-쁨이여<br/>',NULL,33520,1);
INSERT INTO stanza VALUES('K788','2','오 주 예수여 당신의 사랑 이는 포도주보다<br/>달고도 좋아 쏟은 향기름 같아 내 맘 붙잡네<br/>넌 동산의 샘 생수의 우물이라 레바논서 흐르는 시내<br/>넌 동산의 샘 생수의 우물이라 레바논서 흐르는 시내<br/>',NULL,33521,2);
INSERT INTO stanza VALUES('K788','3','오라 내 사랑 나의 동산에 나의 동산에<br/>불어 향기 날리라 나의 동산에 불어 향기 날리라<br/>오 나의 신부 나의 누이여 오라 동산에서 실과 누리자<br/>오 나의 신부 나의 누이여 오라 동산에서 실과 누리자<br/>',NULL,33522,3);
INSERT INTO stanza VALUES('K788','4','나를 인같이 주 맘에 품네 사랑은 죽음같이<br/>강한 것이요 투기는 음부처럼 잔혹하다네<br/>오 많은 물로 꺼치지 못할 사랑 홍수로도 엄몰 못하리<br/>오 많은 물로 꺼치지 못할 사랑 홍수로도 엄몰 못하리<br/>',NULL,33523,4);
INSERT INTO stanza VALUES('K789','1','전능한 하나님 그는 아기<br/>영존의 아버지 아들로 오셨네<br/>평화의 왕이신 내 주 예수<br/>창조의 주를 높여 찬양해<br/>그는 생명의 영- 영 안에 경배해<br/>섬기며 사랑해<br/>그 이름 기묘자 내 주 예수<br/>',NULL,33524,1);
INSERT INTO stanza VALUES('K79','1','주 - 이 땅에서 사람에 - 게 은혜 - 와 사랑으로<br/>하나님께는 충 - 성으로 대하 - 며 가 - 셨네<br/>',NULL,33525,1);
INSERT INTO stanza VALUES('K79','2','사람들이 버린 주의 사 - 랑 죽음 - 보다 - 강해<br/>그 창에 찔려 피를 흘 - 려 우리 양심 씻 - 었네<br/>',NULL,33526,2);
INSERT INTO stanza VALUES('K79','3','고 - 난의 이 땅 가신 주 - 님 늘 선 - 을 행 - 했네<br/>길 어려워도 원망 없었네 탄식 - 도 없 - 었네<br/>',NULL,33527,3);
INSERT INTO stanza VALUES('K79','4','모 - 두가 주를 배신해 - 도 당신 - 은 충 - 성해<br/>아버지 기쁨 맘에 새 - 겨 늘 순 - 종하 - 셨네<br/>',NULL,33528,4);
INSERT INTO stanza VALUES('K79','5','사탄의 궤사에 요동치 않고 고난 - 을 안 - 피해<br/>아무도 동정하지 않아도 죽기까지 가 - 셨네<br/>',NULL,33529,5);
INSERT INTO stanza VALUES('K79','6','주 - 낮추심 참 기이하여라 우리 - 도 주 - 닮아<br/>늘 낮추신 길 배 - 울 - 때 참 안 - 식 있 - 도다<br/>',NULL,33530,6);
INSERT INTO stanza VALUES('K790','1','기쁨으로 물을 길으리라<br/>그 날에 너희가 말하길 여호와께 감사하라<br/>그 이름을 부르며 선포해<br/>그의 행사 만국 중에 선포하고<br/>또 여호와 이름이- 높다 하리라<br/>시온의 거민아 소리 높여 불러<br/>이스라엘 크신 분이 너희 중에 크시다<br/>',NULL,33531,1);
INSERT INTO stanza VALUES('K791','1','그의 판단은 측량 못해 그의 길-은 찾지 못해<br/>주의 맘을 누가 알리요 누가 그의 모사 돼<br/>누가 주께 먼저 드-려 그의 갚으심 받겠느뇨<br/>주로부터 온 모든 것 다시 돌아가니<br/>주께 영광 세세에 있으리라<br/>',NULL,33532,1);
INSERT INTO stanza VALUES('K792','1','영 안에 입- 벌려 주 말해 이로써 경-배-해<br/>사신 하 나-님께 이는 곧 우리의 은-사일세<br/>',NULL,33533,1);
INSERT INTO stanza VALUES('K792','chorus','영 안에서 우리는 말해 영 인도받아 한 몸에 있네<br/>주 그의 일 위해 우릴 영 안에서 지키네<br/>',NULL,33534,2);
INSERT INTO stanza VALUES('K792','2','말하는 지-체들 모두가 성령을 나-타내<br/>몸 위해 주-신- 은사를 함께 훈련-하-네<br/>',NULL,33535,3);
INSERT INTO stanza VALUES('K792','3','신령한 인물 될 꿈 버리고 주님의 몸만 생각해<br/>주 그때 은-사- 주셔서 그의 갈망- 이루리<br/>',NULL,33536,4);
INSERT INTO stanza VALUES('K793','1','우리 앞에 달려야 할 길 있다 주는 곧 우리 길<br/>미혹하는 모든 것들 떠나서 달리자 달리자<br/>제단 지나 성소 지나서 휘장을 또 지나서<br/>언약궤의 생명의 법이 목표요 또 상이다<br/>',NULL,33537,1);
INSERT INTO stanza VALUES('K793','2','구름 같이 둘러싼 저 증인들 우리를 격려해<br/>아벨 에녹 아브라함 야곱과 모세 다윗 솔로몬<br/>그들보-다 큰 침례 요한 그도 앞-서 달렸네<br/>이들은- 믿음따라 죽고 약속은- 못 받았네<br/>',NULL,33538,2);
INSERT INTO stanza VALUES('K793','3','구약의 신자들 우리 부른다“달려라 더 빨리!”<br/>남은 경주 어서 마치라 한다 달려라 달려라<br/>우린 하-나님의 경륜의 완성 단-계에 있다<br/>우린 더- 좋은 것 누린다 실재를- 경험한다<br/>',NULL,33539,3);
INSERT INTO stanza VALUES('K793','4','우리들은 그들보다 더 큰 자 우리는 더 크다<br/>그들 우릴 기다리며 보면서 달리라- 외친다<br/>우리 모-두 하나 되어서 주 나타-낼 때까지<br/>생명의- 법을 순종하자 그들 외-침 들으며<br/>',NULL,33540,4);
INSERT INTO stanza VALUES('K794','1','하나님의 약속은 얼-마든지 주 안에서 예가 되니<br/>그로 인해 우리가 아멘하여 하나님께 영광돌리네<br/>',NULL,33541,1);
INSERT INTO stanza VALUES('K794','chorus','그는 예 또 아멘 그는 예 하나님께 아멘<br/>',NULL,33542,2);
INSERT INTO stanza VALUES('K794','2','그리스도 안에 우릴 견고케 하고 기름 부은 하나님이<br/>우리에게 인치고 보증으로 성령 우리 맘에 주셨네<br/>',NULL,33543,3);
INSERT INTO stanza VALUES('K795','1','새 언약의 일꾼은 공급해 그들- 안에 사신 주님을<br/>고난과 압박 죽음 통하여 주는 이 직분 나눠 주시네<br/>',NULL,33544,1);
INSERT INTO stanza VALUES('K795','2','새 언약의 일꾼은 공급해 측량할 수 없는 주의 풍성을<br/>주의 택하신 모든 자들로 그리스도의 몸을 나타내게 해<br/>',NULL,33545,2);
INSERT INTO stanza VALUES('K795','3','새 언약의 일꾼은 포로들 그리스도의 승리로 얻은<br/>가는 곳마다 주의 향기 내 달콤한 주의 지식 증거해<br/>',NULL,33546,3);
INSERT INTO stanza VALUES('K795','4','새 언약의 일꾼은 넣어줘 모든 믿는 자 맘에 성령을<br/>그리스도의 편지 새기네 확신-하는 모든 마음에<br/>',NULL,33547,4);
INSERT INTO stanza VALUES('K795','5','새 언약의 일꾼은 바라봐 거울을 주의 영광을 보네<br/>그리스도로 흠뻑 적셔져 주의 영 인해 변화된다네<br/>',NULL,33548,5);
INSERT INTO stanza VALUES('K795','6','새 언약의 일꾼은 그릇들 하잘것없는 약한 질그릇<br/>그러나 안에 보물 담았네 영광스러운 주를 담았네<br/>',NULL,33549,6);
INSERT INTO stanza VALUES('K795','7','오 높고도 거룩한 이 사역 그 누가 이런 능력 가졌나<br/>하나님 인해 우린 사역해 그의 새 언약의 일꾼으로서<br/>',NULL,33550,7);
INSERT INTO stanza VALUES('K795','8','이 사역에 동참한 우리들 만유 포함한 주를 공급해<br/>몸을 세우고 교회 건축해 주님의 사역 이뤄간다네<br/>',NULL,33551,8);
INSERT INTO stanza VALUES('K796','1','어그러진 세상 속에서 죄로 죽었던 우리를<br/>하나님이 주님과 함께 살리셨네 하늘에 앉히셨네<br/>',NULL,33552,1);
INSERT INTO stanza VALUES('K796','chorus','주님이 우릴 함께 모으네 와서 보라 하나된 성도<br/>그 사랑 우릴 연결하네 주의 충만하신 분량에 까지<br/>',NULL,33553,2);
INSERT INTO stanza VALUES('K796','2','주의 지식에 넘치는 사랑 성도들과 함께 알아<br/>하나님의 충만하신 것 모두 우리 안에 충만케 되네<br/>',NULL,33554,3);
INSERT INTO stanza VALUES('K796','3','주의 뜻을 이해한 우리 지혜롭게 생활하세<br/>세월 아껴 성령 충만해 시와 찬미로 서로 화답하세<br/>',NULL,33555,4);
INSERT INTO stanza VALUES('K796','4','이러므로 주께 비노니 속사람 강건케 하며<br/>주가 맘에 계시게 하고 뿌리 박히고 터 굳게 하소서<br/>',NULL,33556,5);
INSERT INTO stanza VALUES('K796','5','몸 안에서 각 마디 통해 연락하고 상합하여<br/>지체 분량대로 역사해 몸을 자라게 하고 또 세우네<br/>',NULL,33557,6);
INSERT INTO stanza VALUES('K796','6','이제 그의 목적 이루는 우린 모두 한 새 사람<br/>교회 안에 주님 안에서 영광이 무궁하리로다 아멘<br/>',NULL,33558,7);
INSERT INTO stanza VALUES('K797','1','하나님 그는 빛-이시니 그에겐 어두움 조금도 없으시네<br/>빛 속에 거하여 누려 모든 죄에서 깨끗케 함을<br/>빛 속에 행하며 교제해 보혈을 누리네<br/>그 아들 예수 피 우리 모든 죄 씻네<br/>하나님 그는 빛-이시니 그에겐 어두움 조금도 없으시네<br/>빛 속에 거하여 누려 모든 죄에서 깨끗케 함을<br/>',NULL,33559,1);
INSERT INTO stanza VALUES('K797','2','하나님 그는 빛-이시니 그에겐 어두움 조금도 없으시네<br/>빛 속에 거하여 누려 모든 죄에서 깨끗케 함을<br/>우리 죄 고하면 저는 미쁘고 의로우사<br/>우리 죄 사하네 우리 모든 죄 씻네<br/>하나님 그는 빛-이시니 그에겐 어두움 조금도 없으시네<br/>빛 속에 거하여 누려 모든 죄에서 깨끗게 함을<br/>',NULL,33560,2);
INSERT INTO stanza VALUES('K798','1','어찌 그리 선하고 아름다운-고<br/>형제들이 연합해 동거함- 이<br/>어찌 그리 선하고 아름다운- 고<br/>머리에서 보배론 기름 수염 아론의 수염에 흘러서<br/>그 옷깃에 내려 옷깃에 흘러 내림- 같아<br/>헐몬의 이슬이 시온의 산들에 흘러 흘러 내림 같도다<br/>거기서 여호와께서복을 명했네 곧 영생이라<br/>',NULL,33561,1);
INSERT INTO stanza VALUES('K799','1','준비됐으니 와 앉으오 상 위에 가득 실렸네<br/>굶주린 자 목마른 자들 오면 배부르게 얻네<br/>',NULL,33562,1);
INSERT INTO stanza VALUES('K799','chorus','주의 음성 듣세 원하는 자들아<br/>완전한 구원 얻네 원하는 자마다<br/>',NULL,33563,2);
INSERT INTO stanza VALUES('K799','2','준비됐으니 와 앉으오 은혜의 문이 열렸네<br/>귀한 자리 남겨 놓았네 주를 찾는 사람마다<br/>',NULL,33564,3);
INSERT INTO stanza VALUES('K799','3','준비됐으니 와 앉으오 주께서 기다리시네<br/>은혜 받을 날은 이땔세 내일 믿고 미루지 마<br/>',NULL,33565,4);
INSERT INTO stanza VALUES('K799','4','준비됐으니 와 앉으오 네 근심 걱정 버리고<br/>와서 그리스도를 먹세 영원한 생명의 양식<br/>',NULL,33566,5);
INSERT INTO stanza VALUES('K8','1','다 영 안에서 영과 함께 영을 사용해<br/>영이신 아버지 하나님 찬송합니다<br/>',NULL,33567,1);
INSERT INTO stanza VALUES('K8','2','우리 속 깊은 곳에 영을 창조하시어<br/>영으로 영인 하나님을 경배케 했네<br/>',NULL,33568,2);
INSERT INTO stanza VALUES('K8','3','우리의 영과 당신 영이 상대하도록<br/>주 우리들을 영 안에서 중생케 했네<br/>',NULL,33569,3);
INSERT INTO stanza VALUES('K8','4','내 영에 오려 아버지가 아들 되시고<br/>아들은 또한 영이 되어 내 생명 됐네<br/>',NULL,33570,4);
INSERT INTO stanza VALUES('K8','5','아버지는 곧 아들 안에 아들은 말씀<br/>영이신 말씀 내 영 안에 내 생명 되네<br/>',NULL,33571,5);
INSERT INTO stanza VALUES('K8','6','당신의 영과 나의 영이 하나 되어서<br/>나 주로부터 태어난 것 증거한다네<br/>',NULL,33572,6);
INSERT INTO stanza VALUES('K8','7','오 그 영 항상 날 이끌어 영을 좇게 해<br/>내 전체 영에 속하게 해 생명 안에서<br/>',NULL,33573,7);
INSERT INTO stanza VALUES('K8','8','내 전체 당신 형상 되어 나타나도록<br/>영 안에 항상 기도하며 주만 바라봐<br/>',NULL,33574,8);
INSERT INTO stanza VALUES('K8','9','오 아버지여 영인 당신 찬양합니다<br/>영 사용하여 영 안에서 찬미합니다<br/>',NULL,33575,9);
INSERT INTO stanza VALUES('K80','1','생명의 왕께 엎드려 영광을 돌리세<br/>주 상처 잊지 않도록 갈보리로 가리<br/>',NULL,33576,1);
INSERT INTO stanza VALUES('K80','chorus','겟세마네를 잊잖게 그 맘의 슬픔 잊잖게<br/>사랑의 갈보리로 날 이끌어 주소서<br/>',NULL,33577,2);
INSERT INTO stanza VALUES('K80','2','주 잠드셨던 그 무덤 천사가 지켰네<br/>주 묻히셨던 그 무덤 애도케 하소서<br/>',NULL,33578,3);
INSERT INTO stanza VALUES('K80','3','향품을 갖고 찾아온 마리아 본받게<br/>나 또한 갈보리까지 이끌어 주소서<br/>',NULL,33579,4);
INSERT INTO stanza VALUES('K80','4','매일 내 십자가 지고 즐거이 가도록<br/>나 위해 죽은 주 위해 쓴 잔 마시도록<br/>',NULL,33580,5);
INSERT INTO stanza VALUES('K80','5','거룩한 불로 내 입술 정결케 하시어<br/>주의 갈보리 언제나 말하게 하소서<br/>',NULL,33581,6);
INSERT INTO stanza VALUES('K800','1','생명 빛 사망에 비취시며 그늘에 비취시사<br/>날 축복하사 내 몸을 통해 주 생명 빛 비취도록<br/>내 부르짖는 음성 들으사 죄인들 주께 오게 합소서<br/>',NULL,33582,1);
INSERT INTO stanza VALUES('K801','1','이전에 주를 멀리 떠나 흑암에 있었네<br/>지금은 그 말씀 빛 가운데 주 안에 있네<br/>',NULL,33583,1);
INSERT INTO stanza VALUES('K801','chorus','주 내 맘 속에 살아 계시네<br/>오 어떤 구원인가 주 내 안에 사네<br/>',NULL,33584,2);
INSERT INTO stanza VALUES('K801','2','햇빛이 땅에 쏟아지듯 꽃이 만발하듯<br/>주 예수로부터 퍼져 나온 생명과 사랑<br/>',NULL,33585,3);
INSERT INTO stanza VALUES('K801','3','은혜와 진리 충만하신 육신 되신 주님<br/>지금은 내 안에 들어 오셔 내 충만 되네<br/>',NULL,33586,4);
INSERT INTO stanza VALUES('K801','4','하나님 영광 나타내려 한 알의 밀알로<br/>이 땅에 떨어져 죽은 주님 다시 사셨네<br/>',NULL,33587,5);
INSERT INTO stanza VALUES('K801','5','내 소망 이제 주의 형상 닮는 것 뿐일세<br/>나 항상 죽음에 넘기우며 주 나타내리<br/>',NULL,33588,6);
INSERT INTO stanza VALUES('K802','1','함께 와 즐기자 가난했던 마음<br/>끝 없는 사랑의 보물 큰 창-고 찾았네<br/>',NULL,33589,1);
INSERT INTO stanza VALUES('K802','2','함께 와 즐기자 병들었던 마음<br/>내 병을 알고 고치실 치료-자 찾았네<br/>',NULL,33590,2);
INSERT INTO stanza VALUES('K802','3','함께 와 즐기자 아주 지쳤던 나<br/>날 영원히 붙들어 줄 능력의 팔 찾았네<br/>',NULL,33591,3);
INSERT INTO stanza VALUES('K802','4','함께 와 즐기자 오래 헤맸던 나<br/>그 손으로 이끌어와 내 집- 찾게 했네<br/>',NULL,33592,4);
INSERT INTO stanza VALUES('K802','5','함께 와 즐기자 내 마음 속 비밀<br/>다 알고 나를 사랑할 친구-를 찾았네<br/>',NULL,33593,5);
INSERT INTO stanza VALUES('K802','6','나 그를 모를 때 주 날 사랑했네<br/>신실하고 깊고 강한 다정한 사랑으로<br/>',NULL,33594,6);
INSERT INTO stanza VALUES('K802','7','나 이제 알았네 그 음성 들었네<br/>또한 매일 들을 때에 참 기-쁨 넘치네<br/>',NULL,33595,7);
INSERT INTO stanza VALUES('K803','1','그 무엇으로 채우랴 우리 속 이 공허함<br/>하나님 담는 그릇을 채울 것은 한 가지<br/>',NULL,33596,1);
INSERT INTO stanza VALUES('K803','chorus','사람은 그릇 하나님 담는 그릇<br/>오직 하나님만으로 채울 수 있-다네<br/>',NULL,33597,2);
INSERT INTO stanza VALUES('K803','2','깊은 데 있는 느낌을 주께 말씀드리세<br/>형식에 묶이지 말고 정직히 교통하세<br/>',NULL,33598,3);
INSERT INTO stanza VALUES('K803','3','입 벌려 마음 문 열어 주 향해 뚜껑 열 때<br/>주 예수 흘러 들어와 사망을 씻어 내네<br/>',NULL,33599,4);
INSERT INTO stanza VALUES('K803','4','예수로 그릇 채우세 주의 이름 불러서<br/>주님이 충만할 때에 참된 인생 맛보네<br/>',NULL,33600,5);
INSERT INTO stanza VALUES('K804','1','나는 인생의 산과 들 방황하며 삶의 의미를 찾았지만<br/>내가 얻은 건 공허와 깊은 실망 귀한 세월만 다 보냈네<br/>어느 날 주님이 나를 부르시어 그의 품 안에 안으실 때<br/>나는 당신께 매혹 돼 이끌리며 인생의 참 뜻 알게 됐네<br/>',NULL,33601,1);
INSERT INTO stanza VALUES('K804','2','이제 영광의 주 예수 얼굴 볼 때 날 위해 가시관 쓰셨네<br/>못 박힌 두 손 상처도 생생하여 나는 사랑의 손 잡았네<br/>지금 난 여기서 그리스도 누려 날로 그와 더 친근해져<br/>시냇물 흘러 바다에 돌아가듯 나는 주 안에 잠겨지네<br/>',NULL,33602,2);
INSERT INTO stanza VALUES('K805','1','완전하신 구원의 은혤세 생수 근원 열렸네<br/>각지 각국 사람에게 흘러 주의 옆구리로부터<br/>완전한 구원의 은혜 샘물 같이 솟아나<br/>만대까지 흘러 내리네<br/>',NULL,33603,1);
INSERT INTO stanza VALUES('K805','2','영광스런 계시를 보아라 정결케 하는 흐름<br/>나의 모든 더-러운 죄를 눈보다 더 희게 씻네<br/>완전한 구원의 은혜 얼마나 큰 복인가<br/>깨닫는 자의 것이로다<br/>',NULL,33604,2);
INSERT INTO stanza VALUES('K805','3','무한하신 사랑의 흐름이 낡은 종교 제하네<br/>나의 생각 나-의 감정을 순간순간- 제하네<br/>완전한 구원의 은혜 모든 죄와 종교를<br/>온전히 다 씻어 버리네<br/>',NULL,33605,3);
INSERT INTO stanza VALUES('K805','4','영생으로 오신 성령께서 내 마음에 계시네<br/>하나님과 사람이 연합한 이 비밀이 내 것일세<br/>완전한 구원의 은혜 주가 일으킴으로<br/>하나님의 생명 얻었네<br/>',NULL,33606,4);
INSERT INTO stanza VALUES('K805','5','모든 걱정 의심과 괴로움 이제 나를 떠났네<br/>앞서 가는 주님 믿음으로 어둠을 삼켜 버리네<br/>완전한 구원의 은혜 자유와 즐거움이<br/>영원토록 충만하겠네<br/>',NULL,33607,5);
INSERT INTO stanza VALUES('K806','1','우리 주 찬송할 때 주 영광 받겠네<br/>큰 소리로 찬송할 때 천사도 굴복-해<br/>온 성도 듣-고 주 영광 돌리-네<br/>저- 사탄 무리 떨며 우리를 피하-네<br/>',NULL,33608,1);
INSERT INTO stanza VALUES('K806','2','주 찬송 그칠 때에 저 사탄 비웃네<br/>어찌 항상 싸움으로 물리치지 않으랴<br/>주 찬양의 제-물로 승리의 큰 소리로<br/>우리 체면 깎여 주의 바보라 하기까지<br/>',NULL,33609,2);
INSERT INTO stanza VALUES('K806','3','구주를 찬송할 때 세상이 도왔나<br/>또한 주께 영광 돌려 감사를 드렸-나<br/>만왕의 왕 찬양할 때 허락 받을 것인가<br/>우리 영을 해방하세 무한한 은혤-세<br/>',NULL,33610,3);
INSERT INTO stanza VALUES('K806','4','오 형제 자매들아 큰 소리 외치라<br/>주의 승리 축복 소식 땅끝까지 퍼지리<br/>주 지금 찬양할 땔세 어떤 대가 들어도<br/>할렐루야 소리 높여 기쁨으로 찬양해<br/>',NULL,33611,4);
INSERT INTO stanza VALUES('K807','1','온 교회가 선포하네 예수는 주<br/>모든 성도 선포하네 예수는 주<br/>주는 사탄 처리했네 모든 역사 완성했네<br/>영광의 보좌에 앉은 예수는 주<br/>',NULL,33612,1);
INSERT INTO stanza VALUES('K807','2','주 예수는 생명의 영 예수는 주<br/>지금 여기 충만하네 예수는 주<br/>슬픈 기도 그치고서 다만 그를 불러보라<br/>네 안에 와 생명 되리 예수는 주<br/>',NULL,33613,2);
INSERT INTO stanza VALUES('K807','3','네 각 부분 변케하리 예수는 주<br/>그의 모든 풍성 주리 예수는 주<br/>참 생명을 공급하여 영원히 널 만족게 해<br/>우릴 그로 만드시는 예수는 주<br/>',NULL,33614,3);
INSERT INTO stanza VALUES('K807','4','은혜로 날 받아들인 예수는 주<br/>결코 우릴 떠나지 않을 예수는 주<br/>그의 모든 충만함을 몸 안에서 누릴 때에<br/>대적은 다 달아나네 예수는 주<br/>',NULL,33615,4);
INSERT INTO stanza VALUES('K808','1','보라 세상 만국 모두 주의 나라가 되어<br/>모든 성도 기뻐 찬양하네 우리 왕 예수<br/>허다한 무리의 환호 뇌성 같이 올리네 주 승리하셨네<br/>',NULL,33616,1);
INSERT INTO stanza VALUES('K808','chorus','승리 승리 할렐루야 승리 승리 할렐루야<br/>승리 승리 할렐루야 주 승리 하셨네<br/>',NULL,33617,2);
INSERT INTO stanza VALUES('K808','2','옛 뱀 큰 용 마귀 이미 땅에 꺼꾸러졌네<br/>사탄 마귀들이 다시 우리 미혹 못하리<br/>우리 승리 개가 함께 높이 외쳐 부르세 주 승리하셨네<br/>',NULL,33618,3);
INSERT INTO stanza VALUES('K808','3','어린 양의 보혈로써 마귀 참소 이기고<br/>우리 입의 증거하는 말로 원수 입 막아<br/>죽기까지 충성하여 주를 사랑하겠네 주 승리하셨네<br/>',NULL,33619,4);
INSERT INTO stanza VALUES('K808','4','형제 자매 모두 모여 하늘의 음성 듣세<br/>바벨론은 무너졌네 영원히 무너졌네<br/>바벨론을 떠났으니 우리 기쁨 넘치네 주 승리하셨네<br/>',NULL,33620,5);
INSERT INTO stanza VALUES('K809','1','영광 돌려 그 나라 공의와 평안 있네<br/>희락이 온 땅에 충만하리 함께 모여 송축하세<br/>우리의 왕 예수시니 주 편에 섰는 자<br/>노래하세 영광 돌리세 우리의 군왕<br/>',NULL,33621,1);
INSERT INTO stanza VALUES('K81','1','예수 예수 생명의 샘 내 호흡의 창시자<br/>수치 견뎌 죽임 당해 음부 흑암이겼네<br/>뜨거운 불 깊은 물을 거쳐 구원 이루셨네<br/>천천만만 소리 높여 영광의 주 찬미해<br/>천천만만 소리 높여 영광의 주 찬미해<br/>',NULL,33622,1);
INSERT INTO stanza VALUES('K81','2','하나님의 아들인 주 조롱 미움 견디고<br/>영광스런 왕이신 주 가시면류관 썼네<br/>나를 구원하시려고 그의 생명 버리셨네<br/>천천만만 소리 높여 귀한 구주 찬미해<br/>천천만만 소리 높여 귀한 구주 찬미해<br/>',NULL,33623,2);
INSERT INTO stanza VALUES('K81','3','사람들이 입힌 수치 묵묵하게 견디고<br/>죽음까지 견딘 주님 구속 성취하셨네<br/>기꺼이 사지로 가셔 자신 낮춘 놀라운 주<br/>천천만만 소리 높여 귀한 구주 찬미해<br/>천천만만 소리 높여 귀한 구주 찬미해<br/>',NULL,33624,3);
INSERT INTO stanza VALUES('K81','4','자신 낮춰 죽음으로 나를 살린 주 예수<br/>모든 질고 담당하고 내게 축복 주셨네<br/>마음 다해 찬미하며 영 안에서 경배하리<br/>이는 나의 찬송 제목 영영 주를 찬미해<br/>이는 나의 찬송 제목 영영 주를 찬미해<br/>',NULL,33625,4);
INSERT INTO stanza VALUES('K810','1','사람이신 예수님 죽어 옛 자아 끝-냈네<br/>사람이신 예수님 죽어 옛 자아 끝-냈네<br/>우리 또한 자아를 다 끝냈네<br/>사람이신 예수님 죽어 옛 자아 끝-냈네<br/>',NULL,33626,1);
INSERT INTO stanza VALUES('K810','2','하나님인 예수님 죽어 그 생명 해방했네<br/>하나님인 예수님 죽어 그 생명 해방했네<br/>해방했네 예수 그의 생명을<br/>하나님인 예수님 죽어 그 생명 해방했네<br/>',NULL,33627,2);
INSERT INTO stanza VALUES('K811','1','나는 산에 올라가리 언덕 위에 오르리<br/>주의 죽음 부활 안에 더 깊이 들어가리<br/>',NULL,33628,1);
INSERT INTO stanza VALUES('K811','chorus','나를 산에 있게 하리 내 자아 다 버리고<br/>주 예수와 하나 되어 그의 죽음 함께 누리리<br/>',NULL,33629,2);
INSERT INTO stanza VALUES('K811','2','변화되지 않은 그늘 나를 어둡게 할 때<br/>다시 산에 올라가리 주의 죽음 누리려<br/>',NULL,33630,3);
INSERT INTO stanza VALUES('K811','3','새벽까지 산 위에서 주와 함께 보내리<br/>주의 영 날 흠뻑 적셔 다 변케 할 때까지<br/>',NULL,33631,4);
INSERT INTO stanza VALUES('K811','4','주와 하나 되는 그 때 해는 밝게 빛나리<br/>죽음 깊이 누리면서 주와 난 하나되리<br/>',NULL,33632,5);
INSERT INTO stanza VALUES('K812','1','생명 주는 영 생명의 영<br/>주 예수 내 안에 살고 계시네 주는 내 안에<br/>주는 살아 내 안에 살아<br/>나는 살아서 주를 나타내 할렐루야<br/>우리 주 예수는 생명 주는 영<br/>생명 주는 영 생명의 영<br/>주 예수 내 안에 살고 계시네 주는 내 안에<br/>',NULL,33633,1);
INSERT INTO stanza VALUES('K813','1','삼이일 하나님 우리 안에 지금 성령으로 거하네<br/>생명 주는 영으로 오신 주님 나와 연합해 하나됐네<br/>',NULL,33634,1);
INSERT INTO stanza VALUES('K813','chorus','아 그는 놀라운 성령일세 그는 내 안에 살아 있네<br/>하나님은 아들 안에 아들은 성령으로 내 안에 있네<br/>',NULL,33635,2);
INSERT INTO stanza VALUES('K813','2','아바 아버지 이는 우리 속 깊은 곳에서 부르짖는<br/>우리 위해 친히 간구하시는 아들의 영의 탄식일세<br/>',NULL,33636,3);
INSERT INTO stanza VALUES('K813','3','예수 그리스도 주 내 안에 지금 성령으로 거하네<br/>변화되신 주를 우리는 이제 생명 주는 영으로 누려<br/>',NULL,33637,4);
INSERT INTO stanza VALUES('K813','4','이제 그리스도의 모든 것 생명 주는 영으로 인해<br/>우리에게 모두 실재가 되네 놀랍고 귀한 생명의 영<br/>',NULL,33638,5);
INSERT INTO stanza VALUES('K813','5','우리 속 그 깊은 곳에 있는 놀라운 성령 해방하세<br/>오 주 예수 부를 때에 이 성령 생명 주는 영으로 솟아<br/>',NULL,33639,6);
INSERT INTO stanza VALUES('K814','1','시대는 바뀌어서 영 안에 들어왔네<br/>보좌 앞의 일곱 영 온 땅에 운행하네<br/>',NULL,33640,1);
INSERT INTO stanza VALUES('K814','chorus','일곱 영 역사하사 주의 경륜 이루길 나는 간구하오니<br/>나를 감찰하시고 불로 태워 교회 건축하소서<br/>',NULL,33641,2);
INSERT INTO stanza VALUES('K814','2','성령은 칠배의 영 교회의 사망 제해<br/>성도들 소생시켜 교회 건축게 하네<br/>',NULL,33642,3);
INSERT INTO stanza VALUES('K814','3','우리 하나님의 영 교회의 공급 되셔<br/>칠 배의 강한 역사 풍성하고 완전해<br/>',NULL,33643,4);
INSERT INTO stanza VALUES('K814','4','하나님의 일곱 영 이는 곧 일곱 등불<br/>가르침이 아니며 일곱 등대 불일세<br/>',NULL,33644,5);
INSERT INTO stanza VALUES('K814','5','보라 주의 일곱 영 일곱 눈 불길 같아<br/>교회를 깨끗게 해 육신 정욕 벗게 해<br/>',NULL,33645,6);
INSERT INTO stanza VALUES('K814','6','주의 주신 일곱 영 풍성한 생명 됐네<br/>몸인 교회 안에서 나로 누리게 하네<br/>',NULL,33646,7);
INSERT INTO stanza VALUES('K815','1','주 예수는 생명의 영 우리의 실재<br/>그를 불러 누리는 길 쉽고 간단해<br/>',NULL,33647,1);
INSERT INTO stanza VALUES('K815','chorus','주 예수는 생명의 영 공기 같으니<br/>부르는 자 누구든지 부요하리라<br/>',NULL,33648,2);
INSERT INTO stanza VALUES('K815','2','지금 우리 안에 살며 자유 주시는<br/>은혜로운 주를 우린 항상 맛보네<br/>',NULL,33649,3);
INSERT INTO stanza VALUES('K815','3','주 예수는 생명의 영 생명의 말씀<br/>기도하며 말씀 먹어 주를 흡수해<br/>',NULL,33650,4);
INSERT INTO stanza VALUES('K815','4','우리 중에 흘러가는 주는 생명영<br/>그 영 안에 교통할 때 하나가 되네<br/>',NULL,33651,5);
INSERT INTO stanza VALUES('K815','5','생명의 영 주 예수는 풍성한 잔치<br/>우린 그를 찬양하는 몸 된 교회라<br/>',NULL,33652,6);
INSERT INTO stanza VALUES('K816','1','“오 주 예수” 불러서 항상 주를 먹겠네<br/>이름 불러 받을 때 주로 내 영 충만돼<br/>',NULL,33653,1);
INSERT INTO stanza VALUES('K816','chorus','오 주 예수여 오 주 예수여<br/>오 주 예수여 언제나 부르세<br/>',NULL,33654,2);
INSERT INTO stanza VALUES('K816','2','“오 주 예수” 부르면 결코 실족지 않네<br/>밤낮 주를 부를 때 주의 힘 널 구원해<br/>',NULL,33655,3);
INSERT INTO stanza VALUES('K816','3','영 안으로 오려면 오 주 예수 부르세<br/>나를 떠나 주 향해 항상 불러 주 예수<br/>',NULL,33656,4);
INSERT INTO stanza VALUES('K816','4','부를 때 충만되는 주는 영이요 생명<br/>주를 향한 내 사랑 이름 불러 나타내<br/>',NULL,33657,5);
INSERT INTO stanza VALUES('K817','1','네 마디의 우리 기도 얼마나 풍성한지<br/>그 소식 널리 퍼뜨려 우리 영으로 말해 주 만지기 쉽네<br/>오 주 아멘 할렐루야 오 주 아멘 할렐루야<br/>오 주 아멘 할렐루야 주 만지기 쉽네<br/>',NULL,33658,1);
INSERT INTO stanza VALUES('K818','1','우린 사랑하네 영광스런 이름 예수<br/>모든 이름 위에 뛰어난- 이름<br/>귀한 이름 숨쉴 때 어둠과 사망 사라져<br/>다만 불러 그의 인격 누리네<br/>',NULL,33659,1);
INSERT INTO stanza VALUES('K818','2','우리 모든 입으로 그를 주라 시인해<br/>하나님 아버지 앞에 영광을 돌리네<br/>사랑하는 주 예수 그-의 이름 누림은<br/>매일 우리의 큰 즐거움일세<br/>',NULL,33660,2);
INSERT INTO stanza VALUES('K819','1','우릴 자유케 하려고 죽으신 그는 예수 모두가 아네<br/>내 안에서 살기 위해 오신 주 그는 예수 모두가 아네<br/>',NULL,33661,1);
INSERT INTO stanza VALUES('K819','chorus','예수 예수 모두 함께 부르세 예수<br/>네 마음 문 열고 입을 열고서<br/>모두 함께 부르세 예수<br/>',NULL,33662,2);
INSERT INTO stanza VALUES('K819','2','부를 만한 다른 이름 없으니 맘 문 열고 예수를 불러<br/>의심 모두 벗어 버리고 불러 맘 문 활짝 열고서 불러<br/>',NULL,33663,3);
INSERT INTO stanza VALUES('K819','3','종교는 절대로 소용 없다네 예수만이 필요함 채워<br/>지식 역시 도움 주지 못하네 예수만이 필요함 채워<br/>',NULL,33664,4);
INSERT INTO stanza VALUES('K819','4','공허한 곳 채워 주는 주 예수 와서 함께 부르세 예수<br/>그를 부르며 다같이 누리세 그의 부요함과 풍성을<br/>',NULL,33665,5);
INSERT INTO stanza VALUES('K819','5','네 안에 오려 기다리신 주님 그에게로 돌아와 불러<br/>맘을 활짝 열고 그를 모시라 주의 이름 불러서 모셔<br/>',NULL,33666,6);
INSERT INTO stanza VALUES('K82','1','아 상처로 가득한 비웃음 당하신<br/>시련과 고통 받고 가시 면류관 쓴<br/>주님의 머리 이제 영광을 얻었네<br/>오늘은 성도들의 찬송받고 있네<br/>',NULL,33667,1);
INSERT INTO stanza VALUES('K82','2','죄인들이 뺨 치고 침 뱉던 그 얼굴<br/>오늘은 해보다도 더 밝게 빛나네<br/>우리의 죄를 위해 버림받으신 주<br/>우리의 죄의 값을 다 치러주셨네<br/>',NULL,33668,2);
INSERT INTO stanza VALUES('K82','3','날 위해 죄 없는 분 고통받으셨네<br/>그 사랑 강권하니 내 맘 부서지네<br/>한 알의 밀알로서 죽어 묻히신 주<br/>버리고 잃으신 주 오늘은 얻었네<br/>',NULL,33669,3);
INSERT INTO stanza VALUES('K82','4','당신이 나를 위해 피를 흘리실 때<br/>그 누가 알았을까 그 아픔 그 고통<br/>그 은혜 내 - 어이 갚을 수 있을까<br/>끝까지 주님만을 사랑하오리다<br/>',NULL,33670,4);
INSERT INTO stanza VALUES('K820','1','주의 이름을 부르는 자는 구원을 얻으리로다<br/>주의 이름을 부르는 자는 구원을 얻으리로다<br/>오 주 예수 오 주 예수 주 예수 이름 부르세<br/>오 주 예수 오 주 예수 주 예수 이름 부르세<br/>',NULL,33671,1);
INSERT INTO stanza VALUES('K820','2','주의 이름을 부르는 자는 구원을 얻으리로다<br/>주의 이름을 부르는 자는 구원을 얻으리로다<br/>오 주 예수 오 주 예수 할렐루야 구원됐네<br/>오 주 예수 오 주 예수 할렐루야 구원됐네<br/>',NULL,33672,2);
INSERT INTO stanza VALUES('K821','1','우리는 주의 목적을 위해 교회에 다 바쳐<br/>교회의 행동 따라서 모두 하나로 움직여<br/>',NULL,33673,1);
INSERT INTO stanza VALUES('K821','chorus','항상 성령을 따라 하나로 움직여<br/>항상 영 안의 주님 온전히 따르네<br/>',NULL,33674,2);
INSERT INTO stanza VALUES('K821','2','우리는 다만 따르는 자들 훈련받는 자들<br/>자신 높이길 원하지 않네 성령만 따르네<br/>',NULL,33675,3);
INSERT INTO stanza VALUES('K821','3','우리는 양 떼 발자취 따라 목자 손길 아래<br/>교회 안에서 주님의 말씀 인도하심 누려<br/>',NULL,33676,4);
INSERT INTO stanza VALUES('K821','4','우리는 한눈 팔지 않고서 주님만 따르네<br/>양 떼 가는 곳 우리도 가네 어디든 언제든<br/>',NULL,33677,5);
INSERT INTO stanza VALUES('K821','5','우리 모든 것 다 바쳐 왕국 잔치에 들어가<br/>핍박과 고통 시험 있어도 다 물리치고서<br/>',NULL,33678,6);
INSERT INTO stanza VALUES('K821','6','“내 목적 본 자 나를 따르라”주 말씀하실 때<br/>우리는 다만 주를 따르네 온전히 끝까지<br/>',NULL,33679,7);
INSERT INTO stanza VALUES('K822','1','주 예수 그는 은혜 진리 솟아나는 샘물<br/>주 마시며 다 찬송해 이 교회 안에서<br/>',NULL,33680,1);
INSERT INTO stanza VALUES('K822','chorus','할렐루야 우리는 샘물 마셔 할렐루야 이 교회 안에서<br/>',NULL,33681,2);
INSERT INTO stanza VALUES('K822','2','다 보라 여기 주의 은혜 넘쳐 흘러간다<br/>하늘의 하늘 주님만을 다만 구하라<br/>',NULL,33682,3);
INSERT INTO stanza VALUES('K822','3','저 사탄 그의 힘 다하여 교회 공격해도<br/>주 마시면서 한 순간도 굴복 안 하리<br/>',NULL,33683,4);
INSERT INTO stanza VALUES('K822','4','목마를 때에 달려와서 마시는 이 샘물<br/>깊이 마시리 영원토록 넘치는 샘물<br/>',NULL,33684,5);
INSERT INTO stanza VALUES('K823','1','나 여기 나사렛 예수 얼굴 빛에 서 있네<br/>저주로 죽어야 할 내게 그 사랑 임했네<br/>',NULL,33685,1);
INSERT INTO stanza VALUES('K823','chorus','아 얼마나 기이한가 영원토록 찬송해<br/>아 얼마나 기묘한가 내 구-주의 큰 사랑<br/>',NULL,33686,2);
INSERT INTO stanza VALUES('K823','2','자기 뜻 구하지 않고 아버지의 뜻 구한<br/>주 예수 동산서 날 위해 피와 땀 흘렸네<br/>',NULL,33687,3);
INSERT INTO stanza VALUES('K823','3','그날 밤 내 영혼 위에 슬픔을 참으셨네<br/>한 천사 슬픔 속의 예수 힘 주어 도왔네<br/>',NULL,33688,4);
INSERT INTO stanza VALUES('K823','4','그는 내 죄와 아픔을 홀로 담당하셨네<br/>갈보리의 십자가 죄짐 지고 죽으셨네<br/>',NULL,33689,5);
INSERT INTO stanza VALUES('K823','5','구속된 무리와 함께 주의 얼굴 뵈올 때<br/>주는 내 영원한 기쁨 내 영원한 찬송 돼<br/>',NULL,33690,6);
INSERT INTO stanza VALUES('K824','1','풍요하고 좋은 이 땅 하나님이 주신 땅<br/>샘과 분천 솟아나는 골짜기와 산 있네<br/>',NULL,33691,1);
INSERT INTO stanza VALUES('K824','2','풍요하고 좋은 이 땅 하나님이 주신 땅<br/>젖과 꿀이 흐르는 땅 값없이 다 누리네<br/>',NULL,33692,2);
INSERT INTO stanza VALUES('K824','3','풍요하고 좋은 이 땅 하나님이 주신 땅<br/>포도나무 무화과나무 우릴 만족게 하네<br/>',NULL,33693,3);
INSERT INTO stanza VALUES('K824','4','풍요하고 좋은 이 땅 하나님이 주신 땅<br/>농사지어 거둬내는 밀과 기름 넘치네<br/>',NULL,33694,4);
INSERT INTO stanza VALUES('K824','5','우리 함께 가꿔보세 하나님이 주신 땅<br/>순간순간 힘껏 가꿔 풍성하게 거두세<br/>',NULL,33695,5);
INSERT INTO stanza VALUES('K824','6','집회에서 함께 누려 영광스런 잔치를<br/>소출 중의 최상품을 함께 서로 누리세<br/>',NULL,33696,6);
INSERT INTO stanza VALUES('K824','7','할렐루야 할렐루야 하나님이 주신 땅<br/>이 어떠한 사역인가 어떠한 누림인가<br/>',NULL,33697,7);
INSERT INTO stanza VALUES('K825','1','교회 함께 모일 때에 모두 말할 수 있네<br/>한 사람씩 한 사람씩 교통할 수 있다네<br/>',NULL,33698,1);
INSERT INTO stanza VALUES('K825','chorus','모든 지체 움직일 때 주님 기뻐하시네<br/>작은 자 큰 자 모두 다 주 나타낼 수 있네<br/>',NULL,33699,2);
INSERT INTO stanza VALUES('K825','2','거짓 없는 사랑으로 즐겨 긍휼 베풀고<br/>항상 기도 힘쓰면서 손- 대접 힘쓰라<br/>',NULL,33700,3);
INSERT INTO stanza VALUES('K825','3','어떤 자는 가르치고 어떤 자는 위로해<br/>구제하고 또 다스려 은사대로 나타내<br/>',NULL,33701,4);
INSERT INTO stanza VALUES('K825','4','각각 누린 그리스도 모두 함께 나타내<br/>찬송으로 간증으로 강한 영을 따라서<br/>',NULL,33702,5);
INSERT INTO stanza VALUES('K825','5','항상 앉아 있지 말고 담대하게 일어나<br/>흐름따라 모든 지체 그리스도 간증해<br/>',NULL,33703,6);
INSERT INTO stanza VALUES('K826','1','오 교회 내 집 방랑 멈추는 집<br/>형제들과 늘 즐거운 집<br/>그리스도가 우리 생명된 집<br/>할렐루야 이 집에 사네<br/>교회는 내 집 우리 목마름 그치는 집<br/>우린 온종일 높이 찬양하네<br/>할렐루야 주와 교회를<br/>',NULL,33704,1);
INSERT INTO stanza VALUES('K826','2','주님의 보물 모두 가득한 집<br/>주가 쉬고 또 즐기는 집<br/>사탄은 결코 침범 못하는 집<br/>주의 영광만 찬란한 집<br/>교회는 내 집 주의 목마름 그치는 집<br/>우린 온종일 높이 찬양하네<br/>할렐루야 주와 교회를<br/>',NULL,33705,2);
INSERT INTO stanza VALUES('K827','1','교회는 오늘 이 땅에 그리스도의 몸<br/>각 지방에서 주 간증하는 금등대<br/>주 위해 전쟁하는 주님의 군대요<br/>또 주의 마음 붙잡는 사랑스런 신부<br/>',NULL,33706,1);
INSERT INTO stanza VALUES('K827','chorus','교회를 위해서 기도 드리오니<br/>주 갈망 위해 깨-우사<br/>우릴 건축하옵소서<br/>',NULL,33707,2);
INSERT INTO stanza VALUES('K827','2','오 우리들은 온 교회 사모합니다<br/>풍성한 기업 다 함께 누리렵니다<br/>오 주여 몸 된 교회 더 확장하소서<br/>우리의 마음 더욱더 넓혀 주옵소서<br/>',NULL,33708,3);
INSERT INTO stanza VALUES('K827','3','온 땅에 두루 행하는 주의 일곱 눈<br/>늘 타오르며 우리 맘 감찰하시네<br/>주 항상 갈망하셔 온 교회 하나로<br/>다 건축되어 주님을 나타내기만을<br/>',NULL,33709,4);
INSERT INTO stanza VALUES('K827','4','곧 승리의 왕 주 예수 다시 오시리<br/>주 찬양하는 교회에 다시 오시리<br/>주여 속히 오시어 첫 열매 거두사<br/>주님과 함께 보좌에 앉게 하옵소서<br/>',NULL,33710,5);
INSERT INTO stanza VALUES('K828','1','주여 내게 주의 몸 된 교회 보여 주소서<br/>교회 안에 살아 계신 주를 보게 하소서<br/>머리되신 주님만을 알게 하지 마시고<br/>육신 입은 주의 몸을 내게 보여 주소서<br/>',NULL,33711,1);
INSERT INTO stanza VALUES('K828','2','오랫동안 우리들은 몸 된 교회 찾았네<br/>실재이신 주의 몸을 찾고 찾아 헤맸네<br/>이제 주는 이 땅 위에 몸으로 나타났네<br/>우리 안에 계신 주님 교회로 나타났네<br/>',NULL,33712,2);
INSERT INTO stanza VALUES('K828','3','내가 혼자 생각해서 실재 만질 수 없네<br/>주는 오늘 이 땅 위에 교회 안에 계시네<br/>우리 안에 하나님의 영원한 처소 있네<br/>육신 입고 나타나신 몸을 보게 하소서<br/>',NULL,33713,3);
INSERT INTO stanza VALUES('K828','4','혼자 고립되지 말고 주의 몸에 돌아와<br/>건축 못할 쓸모없는 흙덩이 되지 말고<br/>산 돌로서 건축될 때 주의 갈망 이루리<br/>주님 자신 나타내는 단체의 몸 이루리<br/>',NULL,33714,4);
INSERT INTO stanza VALUES('K829','1','주님의 몸 여기에 모여 있네 많은 사람이 곧 하나일세<br/>생명 안에 우리는 지체 되어 영 안에 우린 모두 하날세<br/>',NULL,33715,1);
INSERT INTO stanza VALUES('K829','chorus','우주 가운데 몸은 하날세 이 땅 위에 나타났네<br/>우리는 한 입장 위에 서서 주의 한 몸 보여 주네<br/>',NULL,33716,2);
INSERT INTO stanza VALUES('K829','2','이 한 떡은 그 몸의 표시일세 찢기운 몸을 함께 누리네<br/>떡을 먹듯 한 주를 함께 얻고 이 하나됨을 모두 간증해<br/>',NULL,33717,3);
INSERT INTO stanza VALUES('K829','3','이 상 위에 놓여진 떡과 잔은 나눌 수 없는 몸을 말하네<br/>한 주 믿고 그 무슨 말하리요 외쳐 말하라 아멘 하날세<br/>',NULL,33718,4);
INSERT INTO stanza VALUES('K829','4','이 하나를 나눌 자 누구이랴 이는 우리 주님 자신일세<br/>떡과 잔을 우리는 함께 먹고 하나된 사실을 보여주네<br/>',NULL,33719,5);
INSERT INTO stanza VALUES('K829','5','주님 안에 다 하나되고 보니 주 기뻐하심 우리 알았네<br/>혼인 잔치 달콤한 그 기쁨을 우리는 지금 먼저 맛보네<br/>',NULL,33720,6);
INSERT INTO stanza VALUES('K83','1','그 늦은 밤에 내 구주 겟세마네로 오셨네<br/>그 깊은 밤에 내 구주 깨어서 기도하셨네<br/>',NULL,33721,1);
INSERT INTO stanza VALUES('K83','2','그 늦은 밤에 내 구주 혼자서 기도하실 때<br/>그 제자들은 잠들어 주 눈물 고통 몰랐네<br/>',NULL,33722,2);
INSERT INTO stanza VALUES('K83','3','그 늦은 밤에 내 구주 고뇌의 기도 드렸네<br/>피 같은 땀이 흐를 때 천사가 와서 도왔네<br/>',NULL,33723,3);
INSERT INTO stanza VALUES('K83','4','그 늦은 밤에 내 구주 쓴 잔을 받기로 했네<br/>아버지 뜻을 이루려 기꺼이 자신 버렸네<br/>',NULL,33724,4);
INSERT INTO stanza VALUES('K830','1','주님의 성전 건축할 때가 되었네<br/>각지에 있는 온 교회 건축 위하여<br/>자신의 일만 돌보지 말고 일어나<br/>주 교회 건축 위하여 나가세<br/>힘써 힘써 다 같이 일-어나<br/>주님의 교회 건축 위해 모두 바-치세<br/>영광 영광 주 같이 하시네<br/>다 함께 나가 건축해 영광스런 교회<br/>',NULL,33725,1);
INSERT INTO stanza VALUES('K830','2','들으라 주님의 말씀 주님의 음성<br/>너희는 자기 소위를 살펴 보아라<br/>씨 뿌려 거둔 산물은 보잘 것 없고<br/>주 찬송소리 그 열매 부족해<br/>올라 올라 높은 산 오 -르세<br/>주님의 교회 건축 재목 힘써 마-련해<br/>영광 영광 주 같이 하시네<br/>다함께 나가 건축해 영광스런 교회<br/>',NULL,33726,2);
INSERT INTO stanza VALUES('K830','3','우리는 주의 자녀요 주님의 노예<br/>왕 같은 제사장이요 거룩한 백성<br/>순종은 제사보다 더 귀한 보배니<br/>우리 주 말씀하실 때 나가세<br/>빛나 빛나 불타오르-는 영<br/>강한 영 받은 형제 자매 힘써 일-하세<br/>오늘 가면 동참치 못하리<br/>지체의 영광 그 한몫 영원히 없으리<br/>',NULL,33727,3);
INSERT INTO stanza VALUES('K830','4','만군의 여호와꼐서 말씀하시네<br/>이 집을 내 영광으로 가득 채우리<br/>온 백성 모든 피조물 고대하던 바<br/>새 땅 새 예루살렘이 나타나<br/>보라 보라 비길 수 없-도다<br/>나중 영광이 전보다도 더욱 크-리라<br/>영광 영광 주 함께 하시네<br/>그 영광 길이 누리세 영광스런 교회<br/>',NULL,33728,4);
INSERT INTO stanza VALUES('K831','1','주 예수께 사로잡힌 내 맘 주님 향해 활짝 엽니다<br/>모든 종교 속박에서 풀어 주 안에만 있게 하소서<br/>여기서 당신의 영광 보니 내 맘 빛으로 채우소서<br/>주의 영과 한 영된 우리를 주님으로 적셔주소서<br/>',NULL,33729,1);
INSERT INTO stanza VALUES('K831','2','눈부시게 빛을 내는 이여 보좌 위에 계신 인자여<br/>불꽃으로 나를 태우소서 주와 함께 빛날 때까지<br/>주여 내가 당신 영광 볼 때 내 자아 부끄럽습니다<br/>이제 당신만을 사랑하며 그 이름을 찬양합니다<br/>',NULL,33730,2);
INSERT INTO stanza VALUES('K831','3','당신 사랑하는 마음으로 나의 옥합 깨뜨립니다<br/>주를 위해 내 모든 좋은 것 주의 머리 위에 붑니다<br/>깊은 데서 흐른 사랑으로 내 모든 것 다 바칩니다<br/>주여 나는 제일 값진 향유 다시 준비하겠습니다<br/>',NULL,33731,3);
INSERT INTO stanza VALUES('K831','4','주의 얼굴 보기 원하오니 향기로운 산에 오소서<br/>내 맘에서 흘러나는 샘물 마시옵고 안식하소서<br/>주여 모든 성도 함께 모여 사모하고 기다리오니<br/>어서 오소서 우리 사랑에 주님 만족할 것입니다<br/>',NULL,33732,4);
INSERT INTO stanza VALUES('K831','1','날마다 숨쉬는 순간마다 내 앞에 어려운 일 보네<br/>주님 앞에 이 몸을 맡길 때 슬픔 없네 두려움 없네<br/>주님의 그 자비로운 손길 항상 좋은 것 주시도다<br/>사랑스레 아픔과 기쁨을 수고와 평화와 안식을<br/>',NULL,33733,5);
INSERT INTO stanza VALUES('K831','2','날마다 주님 내 곁에 계셔 자비로 날 감싸주시네<br/>주님 앞에 이 몸을 맡길 때 힘 주시네 위로함 주네<br/>어린 나를 품에 안으시사 항상 평안함 주시도다<br/>내가 살아 숨을 쉬는 동안 살피신다 약속하셨네<br/>',NULL,33734,6);
INSERT INTO stanza VALUES('K831','3','인생의 어려운 순간마다 주의 약속 생각해 보네<br/>내 맘속에 믿음 잃지 않고 말씀 속에 위로를 얻네<br/>주님의 도우심 바라보며 모든 어려움 이기도다<br/>흘러가는 순간순간마다 주님 약속 새겨 봅니다<br/>',NULL,33735,7);
INSERT INTO stanza VALUES('K832','1','깊이 깊이 십자가 안으로 가게 하소서<br/>생명 얻게 하는 것은 오직 깊은 죽음 뿐<br/>오 주여 내 안에 더 역사하소서<br/>주 안에 온전히 새로워 질 때까지<br/>',NULL,33736,1);
INSERT INTO stanza VALUES('K832','2','높이 높이 주의 생명으로 올라갑니다<br/>오직 주의 생명 만이 우릴 높이 이끄네<br/>오 주여 우리를 매일 변케 하소서<br/>주 풍성한 생명 더욱더 누리도록<br/>',NULL,33737,2);
INSERT INTO stanza VALUES('K832','3','매일 매일 내 안에서 주의 생명 자라네<br/>우리 주님 오늘 내 안에서 걸어가시네<br/>오 주여 우리는 아직 어립니다<br/>당신의 생명이 더욱더 자라소서<br/>',NULL,33738,3);
INSERT INTO stanza VALUES('K832','4','사네 사네 주 내 모든 길에 실재로 사네<br/>크고 작은 모든 일 가운데 주관하시네<br/>오 내 주 예수를 나타내기 위해<br/>주 이름 부르며 모든 것 다 바치리<br/>',NULL,33739,4);
INSERT INTO stanza VALUES('K832','5','나의 인격 되신 그리스도 예수 내 주님<br/>그가 나의 모든 느낌 행동 태도가 되네<br/>오 주여 내 안에 안식하옵소서<br/>매일 매일 나의 인격이 되심으로<br/>',NULL,33740,5);
INSERT INTO stanza VALUES('K832','6','교회 교회 여기에서 우린 발견한다네<br/>깊이 높이 우리를 이끄는 주의 흐름을<br/>오 여기 주님의 몸 된 교회 있네<br/>내 자아 버리고 몸을 위해 자라세<br/>',NULL,33741,6);
INSERT INTO stanza VALUES('K832','7','건축 건축 주의 몸의 건축 생명의 건축<br/>주님만이 건축의 길일세 주를 누리세<br/>오 주여 우리를 건축하옵소서<br/>새 예루살렘이 이루어질 때까지<br/>',NULL,33742,7);
INSERT INTO stanza VALUES('K832','8','오네 오네 주님 곧 오시네 신부 맞으러<br/>이 영광을 우린 예비하네 교회 안에서<br/>오 주여 우리 속 깊이 외치면서<br/>주 기다립니다 어서 오소서 아멘<br/>',NULL,33743,8);
INSERT INTO stanza VALUES('K833','1','지성소로 나아오라 주님 말씀하시니<br/>거룩하신 주의 영광 보기 위해 갑니다<br/>',NULL,33744,1);
INSERT INTO stanza VALUES('K833','chorus','지성소로 나갑니다 제단 분향단 지나<br/>이제 휘장 열렸으니 담대하게 갑니다<br/>',NULL,33745,2);
INSERT INTO stanza VALUES('K833','2','지성소로 나갑니다 새롭고도 산 길로<br/>우리에게 열어놓은 영광스런 이 길로<br/>',NULL,33746,3);
INSERT INTO stanza VALUES('K833','3','홀로 십자가의 피로 영광의 그 길 열고<br/>보좌에 앉으신 주님 향해 나아갑니다<br/>',NULL,33747,4);
INSERT INTO stanza VALUES('K833','4','참 마음 온전한 믿음으로 나아갑니다<br/>뒷걸음질하지 않고 영원한 목적 향해<br/>',NULL,33748,5);
INSERT INTO stanza VALUES('K833','5','당신은 우리 하나님 우린 당신의 백성<br/>주와 함께 지성소에 영원히 거하겠네<br/>',NULL,33749,6);
INSERT INTO stanza VALUES('K834','1','슬픔 속에 십자가 돌며 내 죄 자복하던<br/>여러 해 마침내 강 건너 난 접촉해 이 보좌<br/>',NULL,33750,1);
INSERT INTO stanza VALUES('K834','chorus','여기 은혜의 강 흐르네 경주해 난 주를 얻겠네<br/>담대하게 나와 맛보네 영광의 주<br/>',NULL,33751,2);
INSERT INTO stanza VALUES('K834','2','제단마다 제사 드리려 매일 실패했던 지난 날<br/>이제 모든 제단 떠나 보좌 접촉해<br/>',NULL,33752,3);
INSERT INTO stanza VALUES('K834','3','형제들아 지성소로 와 모든 죄 다 뒤로 던지고<br/>모든 역사 이뤄졌으니 다 달리세<br/>',NULL,33753,4);
INSERT INTO stanza VALUES('K834','4','이젠 휘장 안에 주 누려 만나 누려 생명률 누려<br/>싹 난 지팡이도 누리세 할렐루야<br/>',NULL,33754,5);
INSERT INTO stanza VALUES('K835','1','우리 모두 달콤한 주의 풍성 누릴 때에<br/>하늘 향기 우릴 두르네 이 어떠한 공급인가<br/>어떠한 새로움인가 이제 서로 헤어져야 할 때 됐어도<br/>그의 사랑 흐르네 흐르네 흐르네 끝없이 세차게<br/>흘러가는 시간을 주여 막아 주옵소서<br/>주여 지금 오시옵소서 다시 헤어지지 않게<br/>다시 헤어지지 않게<br/>',NULL,33755,1);
INSERT INTO stanza VALUES('K835','2','우리 모두 나그네 길을 걸어갈- 때에<br/>몸은 멀리 떠나 있어도 영은 하나 영은 하나<br/>잠시 이별 견-디세 모두 함께 모여 누릴 날<br/>기다리며 우린 잔치 누리네 누리네 누리네<br/>그 사랑 안에서 영원 안의 주의 잔치를 먼저 맛 볼 때에<br/>교통의 이 풍성함이여 헤어지고 싶지 않네<br/>헤어지고 싶지 않네<br/>',NULL,33756,2);
INSERT INTO stanza VALUES('K836','1','우리는 해방됐네 찬양해<br/>우리는 해방됐네 찬양해<br/>옛 종교 죽은 교리 떠나서 영에 있네<br/>우리는 해방됐네 찬양해<br/>',NULL,33757,1);
INSERT INTO stanza VALUES('K836','2','우리는 해방됐네 영 안에<br/>우리는 해방됐네 영 안에<br/>생명의 자유 얻어 완전한 구원 누려<br/>우리는 해방됐네 영 안에<br/>',NULL,33758,2);
INSERT INTO stanza VALUES('K836','3','주 내게 충만하네 큰 영광<br/>주 내게 충만하네 큰 영광<br/>풍성한 생명 넘쳐 부족함 전혀 없네<br/>주 내게 충만하네 큰 영광<br/>',NULL,33759,3);
INSERT INTO stanza VALUES('K837','1','우리의 등 안에 기름 있네 우리 등 지금 빛나네<br/>오 주여 우리를 영 안으로 항상 돌아서게 하소서<br/>오 주 아멘 할렐루야 우린 종일 빛나 오르네<br/>오 주 아멘 할렐루야 항상 돌아서므로<br/>',NULL,33760,1);
INSERT INTO stanza VALUES('K837','2','그릇에 기름 더 준비해야 주 오실 때까지 빛나리<br/>등 안에 기름 더 부을 때에 등불 결코 꺼지잖으리<br/>주여 우릴 채우소서 순간순간 당신 자신을<br/>주여 우릴 채우소서 실재로 채우소서<br/>',NULL,33761,2);
INSERT INTO stanza VALUES('K837','3','주님이 오시는 그날까지 우리는 빛나 오르리<br/>그날에 우리의 주와 함께 혼인 잔치 들어가겠네<br/>주 예수여 어서 오사 빛나는 우리 찾으소서<br/>주 예수여 어서 오사 신부와 즐기소서<br/>',NULL,33762,3);
INSERT INTO stanza VALUES('K838','1','주님만 더하사 거룩게 하소서<br/>내 안에 주 인격 더 확장되소서<br/>이 실재 안에서 당신의 교회를 날마다 건축하소서<br/>오 주여 거룩게 하소서 우리를 이 순간에도<br/>주만이 거룩게 하시는 길이니 우릴 거룩게 하소서<br/>',NULL,33763,1);
INSERT INTO stanza VALUES('K838','2','주의 말씀으로 정결케 하소서<br/>사신 말씀으로 날 씻어 주소서<br/>우리 속 각 부분 다 씻어 내소서 그 말씀 더하심으로<br/>오 주여 정결케 하소서 우리를 이 순간에도<br/>주의 말씀으로 옛 성분 다 씻고 영광스런 몸 되도록<br/>',NULL,33764,2);
INSERT INTO stanza VALUES('K838','3','참 양식된 주님 먹고 마시오니<br/>우리를 더욱더 자라게 하소서<br/>주님 자신 먹고 만족함 누리니 주여 더 변케 하소서<br/>오 주여 자라게 하소서 우리를 이 순간에도<br/>우릴 채우소서 만족게 하소서 속히 자라게 하소서<br/>',NULL,33765,3);
INSERT INTO stanza VALUES('K838','4','소중히 품으사 우리를 먹이어 우리의 필요를 다 채워 주소서<br/>딱딱한 우리를 다정히 품으사 부드럽게 해 주소서<br/>오 주여 더 품어주소서 냉랭함 사라지도록<br/>당신께 가까이 더 끌어 주소서 따뜻이 품어 주소서<br/>',NULL,33766,4);
INSERT INTO stanza VALUES('K838','5','주님의 내적인 모든 역사로써 교회를 위하여 영화롭게 하사<br/>주님이 갈망한 신부를 얻도록 오 주여 역사하소서<br/>오 주여 더 역사하소서 교회를 건축하도록<br/>주님을 확산해 지체들 온전히 영화롭게 해 주소서<br/>',NULL,33767,5);
INSERT INTO stanza VALUES('K839','1','주님 자신만 얻기 원합니다 주여 내 전체 다스리소서<br/>내 주권 모두 주께 드리오니 주 안에서만살게 하소서<br/>',NULL,33768,1);
INSERT INTO stanza VALUES('K839','chorus','주님의피 내 모든 죄- 씻고 주님의 생명 날 새롭게 해-<br/>주님의 약속 위에 서 있으니 죄가 날 결코 범치 못하리<br/>',NULL,33769,2);
INSERT INTO stanza VALUES('K839','2','주 향한 맘 늘 순결케 하시고 순간순간날 깨워주소서<br/>주 당신을 슬프게 할 때마다 성령의 탄식 듣게 하소서<br/>',NULL,33770,3);
INSERT INTO stanza VALUES('K839','3','어떠한시험 몰려올지라도주 인해 나는 승리하겠네<br/>주는 내 방패 죄의 화살 올 때 나 주님 안에 서서 이기리<br/>',NULL,33771,4);
INSERT INTO stanza VALUES('K84','1','그 - 무엇이 내 주 머리 숙이게 했는가<br/>내 - 죄가 주의 몸 눌러 피 흘리게 했네<br/>주 나를 위해 희생 돼 날 해방하셨네<br/>',NULL,33772,1);
INSERT INTO stanza VALUES('K84','2','저 - 주와 사망의 잔이 내 분깃이거늘<br/>주 - 그 잔 안의 쓴 것을 다 날 위해 마셔<br/>나 이제 주의 사랑 인해 축복 잔 마셔<br/>',NULL,33773,2);
INSERT INTO stanza VALUES('K84','3','여 - 호와 지팡이 들어 주님을 치셨네<br/>주 - 하나님께 맞아서 난 형벌 면했네<br/>주 보혈 흘러나와서 내 속전 되었네<br/>',NULL,33774,3);
INSERT INTO stanza VALUES('K84','4','맹 - 렬한 바람 휘몰고 파도가 일 때에<br/>주 - 께로 나아가오니 날 막아 주소서<br/>내 안식처 된 주 안에 나 평안 얻겠네<br/>',NULL,33775,4);
INSERT INTO stanza VALUES('K84','5','여 - 호와 명하심 따라 화염검 일어나<br/>주 - 예수 피 요구했네 하나님 공의로<br/>내 주님 그의 요구 이뤄 만족케 했네<br/>',NULL,33776,5);
INSERT INTO stanza VALUES('K84','6','주 - 나를 위해 죽었고 나 주 안에 죽어<br/>부 - 활한 주 예수 지금 내 안에 사시네<br/>연단돼 흠이 없을 때 영광에 들어가<br/>',NULL,33777,6);
INSERT INTO stanza VALUES('K840','1','내 영이 사모합니-다 내 맘 다하여<br/>주께 찬송드립니다 나의 왕 나의 주께<br/>',NULL,33778,1);
INSERT INTO stanza VALUES('K841','1','주의 모든 풍성 나의 실재 안식과 만족 그침 없네<br/>영 안에 영 안에 그 기쁨 측량할 길 없네<br/>영 안에 영 안에 영 안에 그 풍성 누리며 살겠네<br/>',NULL,33779,1);
INSERT INTO stanza VALUES('K842','1','전-능한 하-나님 아기로 오셨네<br/>영원하-신 아-버지 아들로-서 오-셨네<br/>',NULL,33780,1);
INSERT INTO stanza VALUES('K842','chorus','놀라운 기묘자- 하나님 사람 예수<br/>',NULL,33781,2);
INSERT INTO stanza VALUES('K842','2','동-정녀 태- 속에 성령이 잉태돼<br/>신격의 모든 충-만이 육체 입-고 오-셨네<br/>',NULL,33782,3);
INSERT INTO stanza VALUES('K842','3','온- 성이 소-동해 목자들 찬송해<br/>동방박-사 경-배해 말 구유-에 누운 왕께<br/>',NULL,33783,4);
INSERT INTO stanza VALUES('K842','4','아-버지 성-전서 거하길 원해도<br/>혈육 부-모 따-라가 순종하-며 받-드신<br/>',NULL,33784,5);
INSERT INTO stanza VALUES('K842','5','십-자가 위-에서 못 박혀 죽을 때<br/>우리 위-해 기도하며 어머니-를 부-탁한<br/>',NULL,33785,6);
INSERT INTO stanza VALUES('K843','1','하나님이 육신 입으신 경건-의 큰- 비밀<br/>성령으로 잉태되신 분 처녀에게서 났네<br/>하나님과 사람의 연합 하나님의 경륜 이뤄<br/>거룩한 본질이 충만해 비밀한 그리스도<br/>',NULL,33786,1);
INSERT INTO stanza VALUES('K843','2','아버지로부터 또 함께 인생-을 거치셨네<br/>어느 곳 어떤 일에든지 하나님 나타냈네<br/>당신의 인생을 통하여 높은 도덕의 표준 봐<br/>하나님 은혜를 가져와 희년을 선포했네<br/>',NULL,33787,2);
INSERT INTO stanza VALUES('K843','3','하나님 사람 그리스도 나무-에 달리셨네<br/>의로운 분이 불의한 자 대신해 죽으셨네<br/>모든 옛 창조를 못 박고 옛 뱀 마귀 깨뜨렸네<br/>소극적인 것 다 끝내고 생명을 해방했네<br/>',NULL,33788,3);
INSERT INTO stanza VALUES('K843','4','음부를 뚫고 부활한 주 사망-을 이기셨네<br/>사람을 하나님 안으로 이끌어 연합게 해<br/>또한 생명 주는 영 되어 그의 생명 분배했네<br/>우리는 거듭나 당신의 성품에 참여했네<br/>',NULL,33789,4);
INSERT INTO stanza VALUES('K843','5','영광을 얻으신 주 예수 보좌-에 앉으셨네<br/>주와 그리스도 되셨네 만유의 머리일세<br/>뛰어난 이름 얻은 주께 모든 무릎 굴복하네<br/>경륜의 영을 몸에 부어 만유를 통일하네<br/>',NULL,33790,5);
INSERT INTO stanza VALUES('K844','1','주님 십자가에 죽을 때 내 옛 사람도 다 끝났네<br/>나의 옛사람은 죽었네 나는 끝났네<br/>내 영 안에 사는 새 사람 샘물처럼 솟아 오르네<br/>내 각 부분 채울 때까지 넘쳐 흐르네<br/>내 영 안에 사는 주님께 매일 내 마음 다 드리리<br/>내 속사람 그의 거처되고<br/>그가 안식하는 집을 얻게 하기 위해<br/>완전한 실재를 누리며 그의 모든 것 나타내리<br/>내 인격 되신 주가 내 맘에 충만히 거할 때<br/>완전한 실재를 누리며 그의 모든 것 나타내리<br/>내 인격 되신 주가 내 맘에 충만히 거할 때<br/>',NULL,33791,1);
INSERT INTO stanza VALUES('K844','2','주 인격 내 안에 새겨질 때 나는 주의 몸의 지첼세<br/>개인적인 행동 버리고 성도와 함께<br/>점점 주 내 인격 될 때에 점점 내 옛 성분 나가네<br/>그리스도 나의 모든 것 되는 날까지<br/>오직 그리스도 한 분만 위해 나의 뜻 다 버리네<br/>주님 홀로 교회 건축하여<br/>하나님의 위대한 뜻 한 새사람 이뤄<br/>하나님과 사람 연합해 주 완전한 처소 얻는 날<br/>온 땅에 그의 나라 권위와 은혜 넘치리라<br/>하나님과 사람 연합해 주 완전한 처소 얻는 날<br/>온 땅에 그의 나라 권위와 은혜 넘치리라 은혜 넘치리라<br/>',NULL,33792,2);
INSERT INTO stanza VALUES('K845','1','그는 완전 성결 또한 자유 넘쳐<br/>전지하고 인자한 그는 또한 온유해<br/>주 영광 안에 있는 그 생명 나 위하여<br/>영광 안의 그 생명 내게 주셨네<br/>',NULL,33793,1);
INSERT INTO stanza VALUES('K846','1','주 예수는 포도나무 우린 그의 가지들<br/>우리가 주 안에 살 때 주 우리 안에 사네<br/>',NULL,33794,1);
INSERT INTO stanza VALUES('K846','chorus','주님은 내 안에 나는 주 예수 안에<br/>주를 더욱 깊이 아네 그 안에 늘 살겠네<br/>',NULL,33795,2);
INSERT INTO stanza VALUES('K846','2','풍성한 주님의 말씀 듣고 신실할 때에<br/>우리가 들은 그 말씀 우리 안에 거하네<br/>',NULL,33796,3);
INSERT INTO stanza VALUES('K846','3','우린 주 안에 거하는 깊고 참된 길 아네<br/>주 온전히 사랑할 때 무엇이든 이루리<br/>',NULL,33797,4);
INSERT INTO stanza VALUES('K846','4','우린 주 안에 거하고 주 우리 안에 거해<br/>생명의 연합의 기쁨 완전한 조화 맛봐<br/>',NULL,33798,5);
INSERT INTO stanza VALUES('K846','5','서로 안에 거할 때에 귀하고도 달콤해<br/>열매는 더 많아지고 기쁨 충만케 되네<br/>',NULL,33799,6);
INSERT INTO stanza VALUES('K847','1','누구인가 우린 우린 하나님의 형상<br/>우리 인생의 목적은 곧<br/>그리스도를 나타내고 땅을 다스리는- 것<br/>',NULL,33800,1);
INSERT INTO stanza VALUES('K847','2','누구인가 우린 부르심을 받은 자들<br/>거룩한 부르심 받고서<br/>우린 이미 아담 떠났네 영광의 목적 위-해<br/>',NULL,33801,2);
INSERT INTO stanza VALUES('K847','3','누구인가 우린 우린 그의 상속자들<br/>완전한 구원 얻은 우리<br/>또한 이기는 자 되어서 주와 왕권 누리-리<br/>',NULL,33802,3);
INSERT INTO stanza VALUES('K847','4','누구인가 우린 우린 주의 동반자들<br/>일만 하는 종이 아니네<br/>함께 기름 부음 누리며 모든 풍성 누리-네<br/>',NULL,33803,4);
INSERT INTO stanza VALUES('K847','5','누구인가 우린 우린 주의 사업가들<br/>이 기업의 이름은 바로<br/>그리스도와 교회라네 그의 영광 생산-해<br/>',NULL,33804,5);
INSERT INTO stanza VALUES('K847','6','누구인가 우린 우린 주님의 형제들<br/>그리스도의 생명 얻어<br/>거룩한 형제들 되었네 영광스런 형제-들<br/>',NULL,33805,6);
INSERT INTO stanza VALUES('K847','7','누구인가 우린 우린 주님의 등대들<br/>죄악과 어둠의 세상에<br/>주 예수의 빛을 나타내 빛 중의 빛 나타-내<br/>',NULL,33806,7);
INSERT INTO stanza VALUES('K848','1','영원 안에 주는 여호와 스스-로 계신 하나님<br/>모든 피조물의 근원인 영원한 놀라운 하나님<br/>찬양하세 삼일 하나님 아브라함 이삭 야곱 하나님<br/>여호와의 사자로서 우리를 구원하셔<br/>',NULL,33807,1);
INSERT INTO stanza VALUES('K848','2','시간 안에 주는 참 사람 성육신하신 하나님<br/>우리 같은 혈육 지녔네 은혜와 실재가 충만해<br/>오 기묘한 하나님 사람 신성과 인성 연합되신 분-<br/>신격의 모든 충만이 육체로 표현됐네<br/>',NULL,33808,2);
INSERT INTO stanza VALUES('K848','3','대신 죽음 안에 당신은 죄 담당하신 구속주<br/>모든 피조물을 위하여 죽음을 친히 맛보셨네<br/>영원한 효능 있는 피 구속의 큰 사업 다 이루셨네<br/>무한하신 주님 앞에 기쁨의 찬양 드려<br/>',NULL,33809,3);
INSERT INTO stanza VALUES('K849','1','믿는 우리에게 주신 능력 받는 자에게 주신 능력<br/>그리스도 살린 크신 능력 몸된 교회에 주셨네<br/>부활의 큰 능력 주셨네 교회에 교회에<br/>부활의 큰 능력 주셨네 그의 몸 된 교회에게<br/>',NULL,33810,1);
INSERT INTO stanza VALUES('K849','2','하나님 우편에 그리스도 앉게 한 능력 주셨다네<br/>모든 이름 위에 뛰어난 능력 몸 된 교회에 주셨네<br/>초월의 큰 능력 주셨네 교회에 교회에<br/>초월의 큰 능력 주셨네 그의 몸 된 교회에게<br/>',NULL,33811,2);
INSERT INTO stanza VALUES('K849','3','모든 것 발 아래 놓는 능력 지금 여기서 우린 누려<br/>모든 것 정복하는 큰 능력 몸 된 교회에 주셨네<br/>정복의 큰 능력주셨네 교회에 교회에<br/>정복의 큰 능력주셨네 그의 몸 된 교회에게<br/>',NULL,33812,3);
INSERT INTO stanza VALUES('K849','4','그를 모든 것의 머리 삼는 능력 주셨네 교회에게<br/>그의 몸 된 교회를 통하여 이 큰 능력 나타나네<br/>다스리는 능력 주셨네 교회에 교회에<br/>다스리는 능력 주셨네 그의 몸 된 교회에게<br/>',NULL,33813,4);
INSERT INTO stanza VALUES('K85','1','모든 - 사람 대신 죽은 십자가의 주 생각할 때 -<br/>자신 위해 살던 - 생활 버리고 주 위해 - 살겠네<br/>',NULL,33814,1);
INSERT INTO stanza VALUES('K85','2','주 예 - 수와 십자가만 자랑하며 살기로 하네 -<br/>이 세상의 헛된 - 영화 주님 위해 달게 - 버리네<br/>',NULL,33815,2);
INSERT INTO stanza VALUES('K85','3','주의 - 머리 주님의 발 주님의 손 바라 - 볼 때 -<br/>가시면류관 아 - 래로 아픔 사랑 흘러 - 내리네<br/>',NULL,33816,3);
INSERT INTO stanza VALUES('K85','4','온 우 - 주를 다 드려도 너무 적은 대가 - 일세 -<br/>내 마음과 내 온 - 생명 모든 소유 주께 - 드리리<br/>',NULL,33817,4);
INSERT INTO stanza VALUES('K850','1','평생 다 못 체험할 만유 포함하신 주<br/>황야 같은 세상에 고벨화처럼 피어<br/>향기론 몰약같이 내 맘에 감추인 주<br/>주여 나의 부드런 속삭임 들으소서<br/>주 풍성 누리게 해 날 성숙게 하소서<br/>',NULL,33818,1);
INSERT INTO stanza VALUES('K851','1','하나님 아버지 당신은 생명의 근원이시요<br/>우린 당신의 아들들 당신의 나타남입니다<br/>당신의 생명 그- 안에서 우린 하나 누-립니다<br/>당신의 생명 그 - 안에서 아버지 우린 하납니다<br/>',NULL,33819,1);
INSERT INTO stanza VALUES('K851','2','당신의 성분 적셔주는 귀하고 거룩한 말씀<br/>우릴 세상으로부터 분별하는 말씀입니다<br/>당신의 말씀 그- 안에서 우린 하나 되었습니다<br/>당신의 말씀 그- 안에서 우린 하나를 누립니다<br/>',NULL,33820,2);
INSERT INTO stanza VALUES('K851','3','오 얼마나 복된 위친가 우리는 그의 아들들<br/>우리가 주 나타낼 때 삼이일 하나님의 영광<br/>당신의 영광 그- 안에서 우린 모두 하-납니다<br/>당신의 영광 그 - 안에서 아버지 우린 하납니다<br/>',NULL,33821,3);
INSERT INTO stanza VALUES('K852','1','주 승리했네이미 사탄 이기셨네승리 찬송 울려 퍼지네<br/>보혈의 능력 우리들의승리 생활 곧 이기리 주 곧 오시네<br/>',NULL,33822,1);
INSERT INTO stanza VALUES('K852','chorus','형제들아주의 승리 큰 소리로 높이 외치세<br/>시온 성산서 승리 선포해 온 세상 찬미 넘치네<br/>자매들아주의 승리 하나님의뜻 다 이뤘네<br/>참 승리의 주 사탄 이겼네 영원한 기쁨 넘치네<br/>',NULL,33823,2);
INSERT INTO stanza VALUES('K852','2','주 승리했네우리 원수 사탄 이겨 모두 함께 개가 부르세<br/>주의 말씀은 우리 생명 능력일세이 말씀은 우리 힘일세<br/>',NULL,33824,3);
INSERT INTO stanza VALUES('K852','3','주 승리했네대적 이미 패했으니용기 있게 전진합시다<br/>큰 소리 외쳐 주를 높이 찬양하세 주와 교회 언제나 승리<br/>',NULL,33825,4);
INSERT INTO stanza VALUES('K853','1','주가 다-윗에게 하-신 말씀 우리 들-었네<br/>“네 몸에서 날자의 나-라 영영 견-고케 하리”<br/>주의 약속 예수 안 -에 이뤄-졌네 할렐루야<br/>부활하-신 주 예수-님 보좌 위-에 앉았네<br/>',NULL,33826,1);
INSERT INTO stanza VALUES('K853','2','주가 다-시 다윗 집-에 하신 약속 있-으니<br/>“내가 나-의 이름 위-해 그 집 다-시 세우리”<br/>주는 신실하시오-니 약속- 말씀 이-루리<br/>다윗 집-은 무너졌어도 그가 회-복 하시리<br/>',NULL,33827,2);
INSERT INTO stanza VALUES('K853','3','주여 우-린 바로 그- 집 주가 회복하는 역사<br/>주여 속-히 회복하-사 큰 능력- 보이소서<br/>모든 족속 모든 이 -방 주의- 이름 부-르리<br/>주의 거룩한 집을 인-해 주 이름- 알게 되리<br/>',NULL,33828,3);
INSERT INTO stanza VALUES('K853','4','주여 우-릴 속히 회복해 건축하시옵-소서<br/>우리 자-신 드립니-다 주의 역-사 위하여<br/>우리 힘은 약하여-도 우리- 맘은 불-타네<br/>주의 건-축 위해 바치리 몸과 맘- 다 드리리<br/>',NULL,33829,4);
INSERT INTO stanza VALUES('K854','1','위대한 흐-름 하-나님 매 시대 거쳐 흘-렀네<br/>사람의 안 -에 들어 오려 그 많은 단계 거-쳤네<br/>그러나 여전히 하나님은 하나 흐름도 하날세<br/>사람을 거쳐서 이제 내 안에 흐-르네<br/>',NULL,33830,1);
INSERT INTO stanza VALUES('K854','2','하나님 그-는 태-초에 생명강으로 흘-렀네<br/>생명인 그 -가 흐-를 때 생명의 나무 자-랐네<br/>마지막에 와도 그 강은 흐르네 어린 양 안에서<br/>하나님 흐르네 영원 영원히 흐-르네<br/>',NULL,33831,2);
INSERT INTO stanza VALUES('K854','3','하나님 자-신 흘-러서 사람 된 그는 주- 예수<br/>자신의 생 -명 버-려서 하나님 생명 해방했네<br/>이 흐름 막으려 애쓰던 사탄은 그를 못 박고서<br/>옆구리 찌르니 피와 물 흘러 나-왔네<br/>',NULL,33832,3);
INSERT INTO stanza VALUES('K854','4','이 피와 물-이 흘-러서 구원의 흐름 되-었네<br/>그 피는 우-리 죄- 씻고 물은 새 생명 주-었네<br/>이제 성령으로 어디든 흐르네 원수가 아무리<br/>막으려 하여도 그는 여전히 흐 -르네<br/>',NULL,33833,4);
INSERT INTO stanza VALUES('K855','1','율법서 주께로 왔네 은혜로 주를 믿었네<br/>그 영광 얼굴빛 보았네 나 주만 필요해<br/>나 주만 필요해 나 주만 필요해<br/>그 영광 얼굴빛 보았네 나 주만 필요해<br/>',NULL,33834,1);
INSERT INTO stanza VALUES('K855','2','주 집에 살게 하셨네 온종일 찬미 넘치는<br/>오 할렐루-야 풍성한 사랑스러운 집<br/>사랑스러운 집 사랑스러운 집<br/>오 할렐루-야 풍성한 사랑스러운 집<br/>',NULL,33835,2);
INSERT INTO stanza VALUES('K855','3','집 확장되면 도시 돼 만국이 기뻐 찬송해<br/>주 권능으-로 다스려 시온 성산에서<br/>시온 성산에서 시온 성산에서<br/>주 권능으-로 다스려 시온 성산에서<br/>',NULL,33836,3);
INSERT INTO stanza VALUES('K855','4','주 시온서 땅끝까지 주 권능 만민 기뻐해<br/>만국이 주 앞에 굴복해 기뻐 찬송하네<br/>기뻐 찬송하네 기뻐 찬송하네<br/>만국이 주 앞에 굴복해 기뻐 찬송하네<br/>',NULL,33837,4);
INSERT INTO stanza VALUES('K855','5','주와 집 도시와 나라 하나님의 뜻 이뤄져<br/>이 뜻을 위하여 우리는 하나로 뭉치세<br/>하나로 뭉치세 하나로 뭉치세<br/>이 뜻을 위하여 우리는 하나로 뭉치세<br/>',NULL,33838,5);
INSERT INTO stanza VALUES('K856','1','주여 내 맘-의- 수건 벗겨 참 계시를 주-소-서<br/>주의 회복의 그- 맑은 이상 보여- 주소-서<br/>주여 내 맘-의- 수건 벗-겨 참 계시를 주-소서<br/>주의 회복의 그- 맑은 이상 보여- 주소-서<br/>',NULL,33839,1);
INSERT INTO stanza VALUES('K856','2','계시로 나-는 알았다-네 주 일으킨 큰- 능-력<br/>믿음으로 이 능력 받을 때에 교회로 인도됐네<br/>계시로 나-는 알았다-네 주 일으킨 큰- 능-력<br/>믿음으로 이 능력 받을 때에 교회로 인도됐네<br/>',NULL,33840,2);
INSERT INTO stanza VALUES('K856','3','세상의 모-든- 혼란함에서 날 자유케 한- 능-력<br/>날- 이끌어와- 몸 된 교회 안에- 두었-네<br/>세상의 모-든- 혼란함에서 날 자유케 한- 능-력<br/>날- 이끌어와- 몸 된 교회 안에- 두었-네<br/>',NULL,33841,3);
INSERT INTO stanza VALUES('K856','4','교회 안에-서- 주를 나-의 인격으로 누-리-네<br/>매일 겉사람은- 후패해도 속은- 새롭다네<br/>교회 안에-서- 주를 나-의 인격으로 누-리-네<br/>매일 겉사람은- 후패해도 속은- 새롭다네<br/>',NULL,33842,4);
INSERT INTO stanza VALUES('K856','5','난 주와 함-께- 십자가-에 이미 못 박혔-다-네<br/>이제 주로 인해- 내 안에서 속사람 자라-네<br/>난 주와 함-께- 십자가-에 이미 못 박혔-다-네<br/>이제 주로 인해- 내 안에서 속사람 자라-네<br/>',NULL,33843,5);
INSERT INTO stanza VALUES('K856','6','모든 지체-들- 자신 드릴 때 영광스런 몸- 알-아<br/>모두 주를 인격- 삼을 때에 한 새사람 나타나<br/>모든 지체-들- 자신 드릴 때 영광스런 몸- 알-아<br/>모두 주를 인격- 삼을 때에 한 새사람 나타나<br/>',NULL,33844,6);
INSERT INTO stanza VALUES('K856','7','교회 생활-은- 한 새 사-람 지방마다 이-뤄-져<br/>주의 몸은 한 인격 나타내는 단체-의 사-람<br/>교회 생활-은- 한 새 사-람 지방마다 이-뤄-져<br/>주의 몸은 한 인격 나타내는 단체-의 사-람<br/>',NULL,33845,7);
INSERT INTO stanza VALUES('K857','1','오 영광의 아버지 우리에게 지혜와 계시의 영 허락하사<br/>깊은 속의 마음눈- 밝히소서 주 당신-을- 더 알게 하옵소서<br/>',NULL,33846,1);
INSERT INTO stanza VALUES('K857','2','오 우리의 영광의 소망 되신 주 예수는 만물을 충만케 해<br/>하나님의 기업 놀-라운 풍성 계시하-소서 더욱더 우리에게<br/>',NULL,33847,2);
INSERT INTO stanza VALUES('K857','3','오 믿는 우리에게 주신 능력 그 위대한 능력 알게 하소서<br/>그리스도 살리신- 크신 능력 만물 위-에- 머리로 삼는 능력<br/>',NULL,33848,3);
INSERT INTO stanza VALUES('K857','4','이 능력은 모두 주 예수 안에 주 예수는 내 안에 살아 계셔<br/>오 위대한 계시 보-게 하소서 내 안의- 인격 초월의 능-력을<br/>',NULL,33849,4);
INSERT INTO stanza VALUES('K857','5','오 우리의 소망 또 영광 능력 주 예수를 항상 내 안에 인격삼아<br/>내 안에 그 능력 더- 강하여져 하나님- 영광 내 소망 다 이뤄져<br/>',NULL,33850,5);
INSERT INTO stanza VALUES('K858','1','주의 율법 완전해 영혼 소성케 해<br/>주의- 증거 확실해 둔한 자 지혜롭게 해<br/>',NULL,33851,1);
INSERT INTO stanza VALUES('K858','chorus','금- 곧 많은 정금보다 사모할- 것이며<br/>꿀 -과 송이 꿀보다 더 달아<br/>',NULL,33852,2);
INSERT INTO stanza VALUES('K858','2','주의 교훈 정직해 맘 기쁘게 하고<br/>주의- 계명 순결해 눈을- 밝게 하도다<br/>',NULL,33853,3);
INSERT INTO stanza VALUES('K858','3','주 경외하는 도는 정결하고 영원해<br/>주의- 규례 확실해 다- 의로우-니<br/>',NULL,33854,4);
INSERT INTO stanza VALUES('K858','4','내 반 -석이시요 내 구속자인 주<br/>내 입의 말과 마음의 묵상 열납되기 원-해<br/>',NULL,33855,5);
INSERT INTO stanza VALUES('K859','1','복음 전파 목적은 지옥 신세 면하고<br/>축복 평강 얻는 것이 아닐세<br/>이는 하나님 목적 이룰 왕국 안으로<br/>모두 함께 들어가는 것일세<br/>이 목적 위하여 하나님의 형상 모양 따라서<br/>지음 받은 사람들 만물 다스린다네<br/>하나님의 표현 왕국 위하여<br/>',NULL,33856,1);
INSERT INTO stanza VALUES('K859','2','이 목적을 위하여 하나님은 불렀네<br/>아담 노아 아브라함 이삭 야곱<br/>많은 왕들 사사들 모두 실패하므로<br/>하나님 뜻 왕국 못 이루었네<br/>그러나 영원히 실패하지 않는 우리 하나님<br/>친히 육신 입고서 사람으로 오셨네<br/>왕국의 씨 이 땅 위에 뿌렸네<br/>',NULL,33857,2);
INSERT INTO stanza VALUES('K859','3','왕국의 씨는 바로 아버지와 아들과<br/>성령 포함한 삼일의 하나님<br/>하나님 말씀 뿌려 생명의 씨 심겨져<br/>할렐루야 우린 거듭났다네<br/>거듭난 우리들 모두 왕국 안으로 들어왔네<br/>교회 생활 안에서 왕국 실재 누리네<br/>지금 교회 안에 왕국 맛보네<br/>',NULL,33858,3);
INSERT INTO stanza VALUES('K859','4','오 놀라운 유전자 우리 안에 있다네<br/>왕국의 완전한 표현 위한 씨<br/>우리 안에 자라네 일꾼과 환경 통해<br/>밭인 교회 안에 자라난다네<br/>자라며 변화돼 주여 우리 왕국 참 뜻 아오니<br/>추수 때 이르기 전 자라게 하옵소서<br/>매일매일 자라나게 하소서<br/>',NULL,33859,4);
INSERT INTO stanza VALUES('K86','1','강포당한 나의 주님 십자가를 지고서<br/>도살장에 끌려가는 양과 같이 가셨네<br/>',NULL,33860,1);
INSERT INTO stanza VALUES('K86','chorus','무고한 주 내 죄 위해 치욕 굴욕 당했네<br/>깊고 높은 이 사랑에 내 남은 생 드리리<br/>',NULL,33861,2);
INSERT INTO stanza VALUES('K86','2','가시관을 쓰신 주님 십자가에 달렸네<br/>손과 발에 못 박히고 창에 옆구리 찔려<br/>',NULL,33862,3);
INSERT INTO stanza VALUES('K86','3','아버지도 떠나시고 대적 마귀 사나와<br/>나의 주님 맘과 영에 크신 상처 받았네<br/>',NULL,33863,4);
INSERT INTO stanza VALUES('K86','4','십자가를 버리잖고 천사 구원 원찮아<br/>사람들의 희롱 배척 기꺼이 당하셨네<br/>',NULL,33864,5);
INSERT INTO stanza VALUES('K86','5','휘장 가운데로 열린 새롭고도 산 길로<br/>죄인들이 담대하게 하나님께 나아가네<br/>',NULL,33865,6);
INSERT INTO stanza VALUES('K860','1','보상 없이 섬기게 하소서-<br/>알아 주지 않더라도 주여-<br/>나로 고난 받게 하옵소서-<br/>나는 마시지 못할 지라도-<br/>나로 포도주 붓게 하소서-<br/>나를 잃어 그들 위로하며-<br/>나를 쏟아 축복게 하소서-<br/>동정이나 도움 구치 않고-<br/>영광이나 부 구치 않아-<br/>비참하고 외롭더라도-<br/>버림 받고 멸시받아도-<br/>나그네 길의 슬픔 모두 참으며<br/>면류관 위해 대가 지불하리라<br/>주님 당신이 자기 땅에서<br/>그러한 길 가셨-듯이<br/>우릴 위하여 주가 기꺼이<br/>모두 잃은 바 되셨듯이<br/>오 앞길이 얼마나 남았나 몰라도<br/>되돌아 가지 않고 갑니다<br/>부당한 고통 받아도<br/>원망 안한 주의 본 배우게 하옵소서<br/>주여 참담한 시련 당할 때<br/>나의 눈물을 닦아 주소서<br/>주가 내 위로 되심 누리며<br/>나로 생명 샘 되게 하소서<br/>',NULL,33866,1);
INSERT INTO stanza VALUES('K861','1','우리 사랑하는 주 예수님 다시 오는 그 순간<br/>우리 그의 영광 빛 보리 신랑되신 주 예수님<br/>그의 신부 맞을 때 오- 이 어떠한 만-남인가<br/>',NULL,33867,1);
INSERT INTO stanza VALUES('K861','chorus','오 놀라운 만남이여 사랑하는 신랑과-<br/>그 날 만나보리라 오 어떠한 만남인-가<br/>모두 깨어 그 순간 기다리세<br/>',NULL,33868,2);
INSERT INTO stanza VALUES('K861','2','그의 다시 오심 사모하는 모든 자에게 그가<br/>“일어나라”외치시리라 주의 일으키심 받고<br/>구름 속에 올려져 공중에서 주와 잔치 하겠네<br/>',NULL,33869,3);
INSERT INTO stanza VALUES('K861','3','오늘 각지 모든 교회들이 매일매일 모이네<br/>그리스도 기다리면서 주님 다시 올 때 반드시<br/>이곳에 오시리 별들 반짝이는 집회에 오리<br/>',NULL,33870,4);
INSERT INTO stanza VALUES('K861','4','우리 여기서도 함께 모여 주 누리지만<br/>주의 얼굴 뵙기 사모합니다 주와 하나되어<br/>영원토록 함께 살기를 주여 사모하고 기다립니다<br/>',NULL,33871,5);
INSERT INTO stanza VALUES('K862','1','비할 데 없이 귀한 주 새 생명 주려 죽은 주<br/>그분의 신부 맞으려 이 땅에 또 오시리<br/>',NULL,33872,1);
INSERT INTO stanza VALUES('K862','chorus','예수 다시 오시리 예수 우리의 신랑<br/>예수 안식 하소서 우리 맘에 영원히<br/>',NULL,33873,2);
INSERT INTO stanza VALUES('K862','2','주 예수 원하시는 것 구속만이 아니라네<br/>신부가 되기 위하여 우린 값 치뤄야 해<br/>',NULL,33874,3);
INSERT INTO stanza VALUES('K862','3','다른 것 의지 안하고 주 예수만을 섬기리<br/>처녀로서 우리들은 주님만 기다리리<br/>',NULL,33875,4);
INSERT INTO stanza VALUES('K862','4','이 쇠퇴하는 세상을 어떻게 사랑하리요<br/>우리의 사랑 다 바쳐 주님만 찾으리라<br/>',NULL,33876,5);
INSERT INTO stanza VALUES('K863','1','나의 기쁨 나의 소망 되시며 나의 생명이 되신 주<br/>밤낮 불러서 찬송을 드려도 늘 아쉰 마음 뿐일세<br/>',NULL,33877,1);
INSERT INTO stanza VALUES('K863','2','나의 사모하는 선한 목자는 어느 꽃다운 동산에<br/>양의 무리와 늘 함께 가셔서 기쁨을 함께 하실까<br/>',NULL,33878,2);
INSERT INTO stanza VALUES('K863','3','길도 없이 거친 넓은 들에서 갈 길 못찾아 애쓰며<br/>이리 저리로 헤매는 내 모양 저 원수 조롱하도다<br/>',NULL,33879,3);
INSERT INTO stanza VALUES('K863','4','주의 자비롭고 화평한 얼굴 모든 천사도 반기며<br/>주의 놀라운 진리의 말씀에 천지가 화답하도다<br/>',NULL,33880,4);
INSERT INTO stanza VALUES('K863','5','나의 진정 사모하는 예수여 음성조차도 만갑고<br/>나의 생명과 나의 참 소망은 오직 주 예수뿐일세<br/>',NULL,33881,5);
INSERT INTO stanza VALUES('K864','1','주 예수 내가 알기 전 날 먼저 사랑했네<br/>그 크신 사랑 나타나 나 다시 태어났네<br/>주 내 맘에 늘 계시고 나 주의 안에 있어<br/>저 포도 비유 같으니 참 좋은 나의 친구<br/>',NULL,33882,1);
INSERT INTO stanza VALUES('K864','2','내 친구 되신 예수님 날 구원 하시려고<br/>그 귀한 몸을 버리사 내 죄를 대속했네<br/>나 주님을 늘 믿으며 그 손을 의지하고<br/>내 몸과 맘을 바쳐서 끝까지 충성하리<br/>',NULL,33883,2);
INSERT INTO stanza VALUES('K864','3','내 진실하신 친구여 큰 은혜 내려주사<br/>날 항상 보호하시고 내 방패 되옵소서<br/>그 풍성한 참 사랑을 뉘 능히 끊을소냐<br/>날 구원하신 예수는 참 좋은 나의 친구<br/>',NULL,33884,3);
INSERT INTO stanza VALUES('K865','1','주 예수보다 더 귀한 것은 없네<br/>이 세상 부귀로 바꿀 수- 없네<br/>영 죽을 내대신 돌아가신<br/>그 놀라운 사랑 잊-지 못해<br/>',NULL,33885,1);
INSERT INTO stanza VALUES('K865','chorus','세상 즐거움 다- 버리고 세상 자랑<br/>다 버렸네 주 예수보다 더 귀한 것은 없네<br/>예-수 밖에는 없네<br/>',NULL,33886,2);
INSERT INTO stanza VALUES('K865','2','주 예수보다 더 귀한 것은 없네<br/>이 세상 명예로 바꿀 수- 없네<br/>이전에 즐기던 세상 일도<br/>주 사랑하는 맘 뺏-지 못해<br/>',NULL,33887,3);
INSERT INTO stanza VALUES('K865','3','주 예수보다 더 귀한 것은 없네<br/>이 세상 행복과 바꿀 수- 없네<br/>유혹과 핍박이 몰려와도<br/>주 섬기는 내 맘 변-치 못해<br/>',NULL,33888,4);
INSERT INTO stanza VALUES('K866','1','예수 나를 위하여 십자가를 질 때<br/>세상 죄를 지시고 고초 당하셨네<br/>',NULL,33889,1);
INSERT INTO stanza VALUES('K866','chorus','예수여 예수여 나의 죄 위하여<br/>보배 피를 흘리니 죄인 받으소서<br/>',NULL,33890,2);
INSERT INTO stanza VALUES('K866','2','십자가를 지심은 무슨 죄가 있나<br/>저 무지한 사람들 메시야 죽였네<br/>',NULL,33891,3);
INSERT INTO stanza VALUES('K866','3','피와 같이 붉은 죄 없는 이가 없네<br/>십자가의 공로로 눈과 같이 되네<br/>',NULL,33892,4);
INSERT INTO stanza VALUES('K866','4','아름답다 예수여 나의 좋은 친구<br/>예수 공로 아니면 영원 형벌 받네<br/>',NULL,33893,5);
INSERT INTO stanza VALUES('K867','1','주의 음성을 내가 들으니 사랑하는 말일세<br/>믿는 맘으로 주께 가오니 나를 영접하소서<br/>',NULL,33894,1);
INSERT INTO stanza VALUES('K867','chorus','내가 매일 십자가 앞에 더 가까이 가오니<br/>구세주의 흘린 보배 피로써 나를 정케 하소서<br/>',NULL,33895,2);
INSERT INTO stanza VALUES('K867','2','주여 넓으신 은혜 베푸사 나를 받아 주시고<br/>나의 품은 뜻 주의 뜻같이 되게 하여 주소서<br/>',NULL,33896,3);
INSERT INTO stanza VALUES('K867','3','주의 보좌로 나아갈 때에 어찌 아니 기쁠까<br/>주의 얼굴을 항상 뵈오니 더욱 친근합니다<br/>',NULL,33897,4);
INSERT INTO stanza VALUES('K867','4','우리 구주의 넓은 사랑을 측량할 자 없으며<br/>주가 주시는 참된 기쁨도 헤아릴 수 없도다<br/>',NULL,33898,5);
INSERT INTO stanza VALUES('K868','1','하늘 영광 밝은 빛이 내 앞에 있으니<br/>슬픈 일을 많이 보고 늘 고생 하여도<br/>주의 얼굴 광채가 어둔 그늘 헤치니<br/>예수 안에 거하면서 항상 빛을 보도다<br/>',NULL,33899,1);
INSERT INTO stanza VALUES('K868','2','내가 걱정하는 일이 세상에 많은 중<br/>속에 근심 밖에 걱정 늘 시험하여도<br/>예수 보배로운 피 모든 것을 이기니<br/>예수 공로 의지하여 항상 이기리로다<br/>',NULL,33900,2);
INSERT INTO stanza VALUES('K868','3','내가 주를 바라보고 가까이 왔으니<br/>아버지 품 안에서 나 쉴 수 있도다<br/>나는 부족하여도 영접하여 주시니<br/>영원토록 주의 긍휼 찬양 감사하리라<br/>',NULL,33901,3);
INSERT INTO stanza VALUES('K869','1','시온 성과 같은 교회 그의 영광 한 없네<br/>허락하신 말씀대로 주가 친히 세웠네<br/>반석 위에 세운 교회 흔들 자가 누구랴<br/>모든 원수 에워싸도 아무 근심 없도다<br/>',NULL,33902,1);
INSERT INTO stanza VALUES('K869','2','생명 샘이 흘러나와 모든 성도 마시니<br/>언제든지 솟아나와 부족함이 없도다<br/>이런 강이 흘러가니 목마를 자 누구랴<br/>주의 은혜 풍족하여 넘치고도 넘친다<br/>',NULL,33903,2);
INSERT INTO stanza VALUES('K869','3','주의 은혜 내가 받아 시온 백성 됐으니<br/>세상 사람 비방해도 주를 찬송하리라<br/>세상 헛된 모든 영광 아침 안개 같으나<br/>주의 자녀 받을 복은 영원 무궁하도다<br/>',NULL,33904,3);
INSERT INTO stanza VALUES('K87','1','주의 고난 받은 행적 어찌 그리 귀한지<br/>비참한 최후의 모습 주 더욱 사랑케 해<br/>',NULL,33905,1);
INSERT INTO stanza VALUES('K87','chorus','찬미하세 우리 구주 죄인 위해 죽은 주(찬미하세)<br/>영광 구주 영광 구주 죽은 자들 위해 사신 주<br/>',NULL,33906,2);
INSERT INTO stanza VALUES('K87','2','그 누구도 측량 못해 주가 받은 큰 고난<br/>짓밟힘과 학대 고통 누가 능히 알리요<br/>',NULL,33907,3);
INSERT INTO stanza VALUES('K87','3','사랑스런 나의 구주 구속 역사 이룰 때<br/>정죄받은 죄인 위해 홀로 채찍 맞았네<br/>',NULL,33908,4);
INSERT INTO stanza VALUES('K87','4','사람에게 팔리시고 하나님께 버리워<br/>분노 저주 비애 모두 주님 홀로 당했네<br/>',NULL,33909,5);
INSERT INTO stanza VALUES('K870','1','시온의 영광이 빛나는 아침 어둡던 이 땅이 밝아 오네<br/>슬픔과 애통이 기쁨이 되니 시온의 영광이 비쳐 오네<br/>',NULL,33910,1);
INSERT INTO stanza VALUES('K870','2','시온의 영광이 빛나는 아침 매였던 종들이 돌아오네<br/>오래 전 선지자 꿈꾸던 복을 만민이 다같이 누리겠네<br/>',NULL,33911,2);
INSERT INTO stanza VALUES('K870','3','보아라 광야에 화초가 피고 말랐던 시냇물 흘러 오네<br/>이 산과 저 산이 마주쳐 울려 주 예수 은총을 찬송하네<br/>',NULL,33912,3);
INSERT INTO stanza VALUES('K870','4','땅들아 바다야 많은 섬들아 찬양을 주님께 드리어라<br/>싸움과 죄악의 참혹한 땅에 찬송이 하늘에 사무치네<br/>',NULL,33913,4);
INSERT INTO stanza VALUES('K871','1','내 죄사함 받고서 예수를 안 뒤 나의 모든 것 다 변했네<br/>지금 나의 가는 길 천국 길이요 주의 피로 내 죄를 씻었네<br/>',NULL,33914,1);
INSERT INTO stanza VALUES('K871','chorus','나의 모든 것 변하고 그 피로 구속 받았네<br/>하나님은 나의 구원되시오니 내게 정죄함 없겠네<br/>',NULL,33915,2);
INSERT INTO stanza VALUES('K871','2','주님 밝은 빛되사 어둠 헤치고 나의 모든 것 다 변했네<br/>지금 내가 주 앞에 온전케 됨은 주의 공로를 의지함일세<br/>',NULL,33916,3);
INSERT INTO stanza VALUES('K871','3','내게 성령 임하고 그 크신 사랑 나의 맘에 가득 채우며<br/>모든 공포 내게서 물리치시니 내 맘 항상 주 안에 있도다<br/>',NULL,33917,4);
INSERT INTO stanza VALUES('K872','1','물 건너 생명줄 던지어라 누가 저 형제를 구원하랴<br/>우리의 가까운 형제이니 이 생명줄 누구가 던지려나<br/>',NULL,33918,1);
INSERT INTO stanza VALUES('K872','chorus','생명줄 던져 생명줄 던져 물 속에 빠져간다<br/>생명줄 던져 생명줄 던져 지금 곧 건지어라<br/>',NULL,33919,2);
INSERT INTO stanza VALUES('K872','2','너 빨리 생명줄 던지어라 형제여 너 어찌 지체하나<br/>보아라 저 형제 빠져간다 이 구조선 타고서 속히 가라<br/>',NULL,33920,3);
INSERT INTO stanza VALUES('K872','3','너 어서 생명 줄 던지어라 저 형제 지쳐서 허덕인다<br/>시험과 근심의 거센 풍파 저 형제를 휩쓸어 몰아간다<br/>',NULL,33921,4);
INSERT INTO stanza VALUES('K872','4','위험과 풍파가 쉬 지나고 건너편 언덕에 이르리니<br/>형제여 너 어찌 지체하나 곧 생명줄 던져서 구원하라<br/>',NULL,33922,5);
INSERT INTO stanza VALUES('K873','1','익은 곡식 거둘자가 없는 이때에 누가 가서 거둘까<br/>내가 어찌 게을러서 앉아 있을까 어서 가자 밭으로<br/>',NULL,33923,1);
INSERT INTO stanza VALUES('K873','chorus','보내 주소서 보내 주소서<br/>제단 숯불 내 입술에 대니 어찌 주저 할까<br/>주여 나를 보내 주소서<br/>',NULL,33924,2);
INSERT INTO stanza VALUES('K873','2','주가 두루 다니시며 일꾼 부르나 따르는 자 적구나<br/>보라 주의 사랑하는 익은 곡식을 어서 거두러 가자<br/>',NULL,33925,3);
INSERT INTO stanza VALUES('K873','3','주가 나를 인도하니 언제 어디나 기뻐 가서 일하리<br/>주가 명령 내리실 때 능력 받아서 기뻐 거두리로다<br/>',NULL,33926,4);
INSERT INTO stanza VALUES('K874','1','저 북방 얼음산과 또 대양 산호 섬<br/>저 남방 모든 나라 수 많은 백성들<br/>큰 죄악 범한 민족 다 구원 얻으려<br/>참 빛을 받은 우리 곧 오라 부른다<br/>',NULL,33927,1);
INSERT INTO stanza VALUES('K874','2','주 은혜 받은 우리 큰 책임 잊고서<br/>주 예수 참된 구원 전하지 않으랴<br/>온 세상 모든 백성 참 구원 얻도록<br/>온 몸과 재산 드려 이 복음 전하자<br/>',NULL,33928,2);
INSERT INTO stanza VALUES('K874','3','만왕의 왕된 예수 이 세상 오셔서<br/>만백성 구속하니 참 구주시로다<br/>저 부는 바람 따라 이 소식 퍼치고<br/>저 바다 물결 좇아 이 복음 전하자<br/>',NULL,33929,3);
INSERT INTO stanza VALUES('K875','1','사랑하는 주님 앞에 형제 자매 한 자리에<br/>크신 은혜 생각하며 즐거운 찬송 부르네<br/>내 주 예수 본을 받아 모든 사람 내 몸 같이<br/>환난 근심 위로하고 진심으로 사랑하세<br/>',NULL,33930,1);
INSERT INTO stanza VALUES('K875','2','사랑하는 주님 앞에 온갖 충성 다 바쳐서<br/>괴로우나 즐거우나 주님만 힘써 섬기세<br/>우리 주님 거룩한 손 제자들의 발을 씻어<br/>남 섬기는 종의 도를 몸소 행해 보이셨네<br/>',NULL,33931,2);
INSERT INTO stanza VALUES('K875','3','사랑하는 주님 예수 같은 주로 섬기나니<br/>한 피 받아 한 몸 이룬 형제여 친구들이여<br/>한 몸같이 친밀하고 마음조차 하나되어<br/>우리 주님 크신 뜻을 지성으로 준행하세<br/>',NULL,33932,3);
INSERT INTO stanza VALUES('K876','1','하나님의 진리 등대 길이 길이 빛나니<br/>우리 앞에 비칠 등대 각각 제 빛 발하네<br/>',NULL,33933,1);
INSERT INTO stanza VALUES('K876','chorus','우리 작은 불을 켜서 험한 바다 비추세<br/>물에 빠져 헤매는 이 건져 내어 살리세<br/>',NULL,33934,2);
INSERT INTO stanza VALUES('K876','2','죄의 밤은 깊어가고 성난 물결 설렌다<br/>어디 불빛 없는가고 찾는 무리 많구나<br/>',NULL,33935,3);
INSERT INTO stanza VALUES('K876','3','주의 불을 돋우어라 풍파 속에 빠져서<br/>빛을 찾아 헤매는 이 생명선에 건져라<br/>',NULL,33936,4);
INSERT INTO stanza VALUES('K877','1','사철에 봄 바람 불어 잇고 하나님 아버지 모셨으니<br/>믿음의 반석도 든든하다 우리 집 즐거운 동산이라<br/>',NULL,33937,1);
INSERT INTO stanza VALUES('K877','chorus','고마워라 임마누엘 예수만 섬기는 우리 집<br/>고마워라 임마누엘 복되고 즐거운 하루하루<br/>',NULL,33938,2);
INSERT INTO stanza VALUES('K877','2','어버이 우리를 고이시고 동기들 사랑에 뭉쳐 있고<br/>기쁨과 설움도 같이하니 한 간의 초가도 천국이라<br/>',NULL,33939,3);
INSERT INTO stanza VALUES('K877','3','아침과 저녁에 수고하여 다 같이 일하는 온 식구가<br/>한 상에 둘러서 먹고 마셔 여기가 우리의 낙원이라<br/>',NULL,33940,4);
INSERT INTO stanza VALUES('K878','1','돌아와 돌아와 맘이 곤한 이여<br/>길이 참 어둡고 매우 험악하니<br/>',NULL,33941,1);
INSERT INTO stanza VALUES('K878','chorus','집을 나간 자여 어서 와 돌아와<br/>어서 와 돌아 오라<br/>',NULL,33942,2);
INSERT INTO stanza VALUES('K878','2','돌아와 돌아와 해가 질 때까지<br/>기다리고 계신 우리 아버지께<br/>',NULL,33943,3);
INSERT INTO stanza VALUES('K878','3','돌아와 돌아와 환난있는 곳과<br/>죄를 범한 데와 미혹받는 데서<br/>',NULL,33944,4);
INSERT INTO stanza VALUES('K878','4','돌아와 돌아와 집에 돌아오라<br/>모든 것 풍성한 아버지 집으로<br/>',NULL,33945,5);
INSERT INTO stanza VALUES('K879','1','주 예수 대문 밖에 기다려 섰으나<br/>단단히 잠가 두니 못 들어오시네<br/>나 주를 믿노라고 그 이름 부르나<br/>문 밖에 세워 두니 참 나의 수치라<br/>',NULL,33946,1);
INSERT INTO stanza VALUES('K879','2','문 두드리는 손은 못 박힌 손이요<br/>또 가시면류관은 그 이마 둘렸네<br/>이처럼 기다리심 참 사랑이로다<br/>문 굳게 닫아 두니 한 없는 내 죄라<br/>',NULL,33947,2);
INSERT INTO stanza VALUES('K879','3','주 예수 간곡하게 권하는 말씀이<br/>“네 죄로 죽은 나를 너 박대할소냐”<br/>나 죄를 회개하고 곧 문을 엽니다<br/>드셔서 좌정하사 내 안에 사소서<br/>',NULL,33948,3);
INSERT INTO stanza VALUES('K88','1','겟세마네 동산에서 홀로 기도하신<br/>주 예수님 나 위하여 쓴 잔 마시셨네<br/>',NULL,33949,1);
INSERT INTO stanza VALUES('K88','chorus','홀로 홀로 홀로 당하셨네<br/>주 나를 구원하시려<br/>홀로 죽으셨네<br/>',NULL,33950,2);
INSERT INTO stanza VALUES('K88','2','빌라도의 심판대에 홀로 서신 주님<br/>모든 사람 버림 받고 가시관 쓰셨네<br/>',NULL,33951,3);
INSERT INTO stanza VALUES('K88','3','십자가에 나의 주님 홀로 달리실 때<br/>하나님과 사람에게 버림을 받았네<br/>',NULL,33952,4);
INSERT INTO stanza VALUES('K88','4','이 큰 사랑 네가 어찌 거절할 수 있나<br/>감사하며 다만 받고 주 떠나지마라<br/>',NULL,33953,5);
INSERT INTO stanza VALUES('K880','1','여러 해 동안 주 떠나 세상 연락을 즐기고<br/>저 흉악한 죄에 빠져서 그 은혜를 잊었네<br/>',NULL,33954,1);
INSERT INTO stanza VALUES('K880','chorus','오 사랑의 예수님 내 맘을 곧 엽니다<br/>곧 들어와 나와 동거하며 내 생명이 되소서<br/>',NULL,33955,2);
INSERT INTO stanza VALUES('K880','2','죄악에 죽을 인생을 심히 불쌍히 여기사<br/>저 하늘의 영광 버리고 이 세상에 오셨네<br/>',NULL,33956,3);
INSERT INTO stanza VALUES('K880','3','홍포를 입은 구주는 가시 면류관 쓰시고<br/>저 십자가 높이 달리사 그 아픔을 참았네<br/>',NULL,33957,4);
INSERT INTO stanza VALUES('K880','4','미련한 우리 인생은 주의 공로를 모르고<br/>그 쓸쓸한 사막 가운데 늘 헤매고 다녔네<br/>',NULL,33958,5);
INSERT INTO stanza VALUES('K881','1','천부여 의지 없어서 손들고 옵니다<br/>주 나를 박대 하시면 나 어디 가리까<br/>',NULL,33959,1);
INSERT INTO stanza VALUES('K881','chorus','내 죄를 씻기 위하여 피 흘려 주시니<br/>곧 회개하는 맘으로 주 앞에 옵니다<br/>',NULL,33960,2);
INSERT INTO stanza VALUES('K881','2','전 부터 계신 주께서 영 죽을 영혼을<br/>보혈로 구해 주시니 그 사랑 한없네<br/>',NULL,33961,3);
INSERT INTO stanza VALUES('K881','3','나 예수 의지하므로 큰 권능 받아서<br/>주 앞에 구한 모든 것 늘 얻겠습니다<br/>',NULL,33962,4);
INSERT INTO stanza VALUES('K882','1','부름받아 나선 이 몸 어디든지 가오리다<br/>괴로우나 즐거우나 주만 따라 가오리니<br/>어느 누가 막으리까 죽음인들 막으리까<br/>어느 누가 막으리까 죽음인들 막으리까<br/>',NULL,33963,1);
INSERT INTO stanza VALUES('K882','2','아골 골짝 빈들에도 복음 들고 가오리다<br/>소돔같은 거리에도 사랑 안고 찾아가서<br/>종의 몸에 지닌 것도 아낌없이 드리리다<br/>종의 몸에 지닌 것도 아낌없이 드리리다<br/>',NULL,33964,2);
INSERT INTO stanza VALUES('K882','3','존귀 영광 모든 권세 주님 홀로 받으소서<br/>멸시천대 십자가는 제가 지고 가오리다<br/>이름없이 빛도 없이 감사하며 섬기리다<br/>이름없이 빛도 없이 감사하며 섬기리다<br/>',NULL,33965,3);
INSERT INTO stanza VALUES('K883','1','성자의 귀한 몸 날 위하여 버리신 그 사랑 고마워라<br/>내 머리 주 앞에 조아려 하는 말 나 무엇 주님께 바치리까<br/>',NULL,33966,1);
INSERT INTO stanza VALUES('K883','2','지금도 날 위해 간구하심 이 옅은 믿음이 아옵나니<br/>주님의 참 사랑 고맙고 놀라워 찬송과 기도를 쉬지 않네<br/>',NULL,33967,2);
INSERT INTO stanza VALUES('K883','3','주님의 십자가 나도 지고 신실한 믿음과 마음으로<br/>형제의 사랑과 친절한 위로를 뉘게나 베풀게 하옵소서<br/>',NULL,33968,3);
INSERT INTO stanza VALUES('K883','4','만 가지 은혜를 받았으니 내 평생 슬프나 즐거우나<br/>이 몸을 온전히 주님께 바쳐서 주님만 위하여 늘 살겠네<br/>',NULL,33969,4);
INSERT INTO stanza VALUES('K884','1','내 모든 시험 무거운 짐을 주 예수 앞에 아뢰이면<br/>근심에 싸인 날 돌아보사 내 근심 모두 맡으시네<br/>',NULL,33970,1);
INSERT INTO stanza VALUES('K884','chorus','무거운 짐을 나 홀로지고 견디다 못해 쓰러질 때<br/>불쌍히 여겨 구원해 줄 이 은혜의 주님 오직 예수<br/>',NULL,33971,2);
INSERT INTO stanza VALUES('K884','2','내 모든 괴로움 닥치는 환난 주 예수 앞에 아뢰이면<br/>주께서 친히 날 구해 주사 넓으신 사랑 베푸시네<br/>',NULL,33972,3);
INSERT INTO stanza VALUES('K884','3','내 짐이 점점 무거워 질 때 주 예수 앞에 아뢰이면<br/>주께서 친히 날 구해주사 내 대신 짐을 져주시네<br/>',NULL,33973,4);
INSERT INTO stanza VALUES('K884','4','마음의 시험 무서운 죄를 주 예수 앞에 아뢰이면<br/>예수는 나의 능력이 되사 세상을 이길 힘 주시네<br/>',NULL,33974,5);
INSERT INTO stanza VALUES('K885','1','환난과 핍박 중에도 성도는 신앙 지켰네<br/>이 신앙 생각할 때에 기쁨이 충만하도다<br/>성도의 신앙 따라서 죽도록 충성하겠네<br/>',NULL,33975,1);
INSERT INTO stanza VALUES('K885','2','옥 중에 매인 성도나 양심은 자유 얻었네<br/>우리도 고난 받으면 죽어도 영광되도다<br/>성도의 신앙 따라서 죽도록 충성하겠네<br/>',NULL,33976,2);
INSERT INTO stanza VALUES('K885','3','성도의 신앙 본받아 원수도 사랑하겠네<br/>인자한 언어 행실로 이 신앙 전파하리라<br/>성도의 신앙 따라서 죽도록 충성하겠네<br/>',NULL,33977,3);
INSERT INTO stanza VALUES('K886','1','나는 예수 따라가는 십자가 군사라<br/>주 이름 증거하기를 왜 주저하리요<br/>다른 군사 피 흘리며 나가서 싸울 때<br/>나 혼자 편히 앉아서 바라만 보리요<br/>',NULL,33978,1);
INSERT INTO stanza VALUES('K886','chorus','다른 사람 어찌하든 나 주님의 용사 되리<br/>나는 주의 군사되어 충성을 맹세하여<br/>내가 승리하기까지 주 은혜로 싸우리<br/>주의 용사된 나에게 주의 일 맡기소서<br/>',NULL,33979,2);
INSERT INTO stanza VALUES('K886','2','큰 싸움은 시작되어 용사를 부른다<br/>곧 나가 전쟁 마당에 다 어서 나가자<br/>거룩하신 주님 위해 싸우러 나가자<br/>주님의 권능 힘입어 다 이길 때까지<br/>',NULL,33980,3);
INSERT INTO stanza VALUES('K886','3','그 승리의 영광 위해 싸워야 하리라<br/>주 말씀 나의 힘되니 겁낼 것 없도다<br/>모든 싸움 이긴 후에 그 날이 이르면<br/>승전가 높이 부르며 큰 영광 누리리<br/>',NULL,33981,4);
INSERT INTO stanza VALUES('K887','1','하나님은 외아들을 주시는 데까지<br/>세상 사람 사랑하니 참 사랑이로다<br/>',NULL,33982,1);
INSERT INTO stanza VALUES('K887','chorus','하나님은 사랑이라 죄악에 타락된<br/>우리까지 사랑하니 참사랑 아닌가<br/>',NULL,33983,2);
INSERT INTO stanza VALUES('K887','2','하나님을 배반하고 멀리 떠난 우리<br/>원수같이 대적하나 사랑하여 주네<br/>',NULL,33984,3);
INSERT INTO stanza VALUES('K887','3','세상 죄를 사하시려 우리 죽을 대신<br/>성자 예수 십자가에 고난 받으셨네<br/>',NULL,33985,4);
INSERT INTO stanza VALUES('K887','4','이와 같이 넓고 깊은 하나님 사랑에<br/>아직 감복 않는 자야 사람이라 할까<br/>',NULL,33986,5);
INSERT INTO stanza VALUES('K888','1','내 주여 뜻대로 행하시옵소서<br/>온 몸과 영혼을 다 주께 드리니<br/>이 세상 고락간 주 인도하시고<br/>날 주관하셔서 뜻대로 하소서<br/>',NULL,33987,1);
INSERT INTO stanza VALUES('K888','2','내 주여 뜻대로 행하시옵소서<br/>큰 근심 중에도 낙심케 마소서<br/>주님도 때로는 울기도 하셨네<br/>날 주관하셔서 뜻대로 하소서<br/>',NULL,33988,2);
INSERT INTO stanza VALUES('K888','3','내 주여 뜻대로 행하시옵소서<br/>내 모든 일들을 다 주께 맡기고<br/>주님의 뜻만을 구하며 가리니<br/>살든지 죽든지 뜻대로 하소서<br/>',NULL,33989,3);
INSERT INTO stanza VALUES('K889','1','주 안에 있는 나에게 딴 근심 있으랴<br/>십자가 밑에 나아가 내 짐을 풀었네<br/>',NULL,33990,1);
INSERT INTO stanza VALUES('K889','chorus','주님을 찬송하면서 할렐루야 할렐루야<br/>내 앞 길 멀고 험해도 나 주님만 따라가리<br/>',NULL,33991,2);
INSERT INTO stanza VALUES('K889','2','그 두려움이 변하여 내 기도 되었고<br/>전날의 한숨 변하여 내 노래 되었네<br/>',NULL,33992,3);
INSERT INTO stanza VALUES('K889','3','내 주는 자비하셔서 늘 함께 계시고<br/>내 궁핍함을 아시고 늘 채워 주시네<br/>',NULL,33993,4);
INSERT INTO stanza VALUES('K889','4','내 주와 맺은 언약은 영 불변하시니<br/>그 나라 가기까지는 늘 보호하시네<br/>',NULL,33994,5);
INSERT INTO stanza VALUES('K89','1','주 사랑으 - 로 날 - 위해 죽음을 당 - 하여 -<br/>우리로 죄 - 와 세상 강한 자 이 - 기게 했네<br/>',NULL,33995,1);
INSERT INTO stanza VALUES('K89','2','무겁고 무 - 거운 - 짐을 주께서 지 - 셨네 -<br/>사람의 죄 - 악 귀신 비웃음 하나님의 분노<br/>',NULL,33996,2);
INSERT INTO stanza VALUES('K89','3','주 감싼 맹렬한 분노 풍파 영영 잠잠해졌네 -<br/>이제 우리 - 는 즐거움 얻고 주 이름 얻었네<br/>',NULL,33997,3);
INSERT INTO stanza VALUES('K89','4','곧 주님 앞으로 들림 받아 새 노래 부 - 르리 -<br/>오늘도 우리는 당신 죽으신 이 땅서 찬양해<br/>',NULL,33998,4);
INSERT INTO stanza VALUES('K890','1','기도는 믿는 사람의 호흡과 같으니<br/>믿음을 유지하려면 기도를 하여라<br/>',NULL,33999,1);
INSERT INTO stanza VALUES('K890','chorus','믿음으로 기도하라 무슨 일이나<br/>간절하게 구하여라 다 얻으리라<br/>',NULL,34000,2);
INSERT INTO stanza VALUES('K890','2','염려를 하는 사람은 기도를 하여라<br/>쓸데가 없는 염려는 심령을 상한다<br/>',NULL,34001,3);
INSERT INTO stanza VALUES('K890','3','기도는 모든 불가능 다 가능케 하니<br/>열심히 기도하는 자 다 형통하리라<br/>',NULL,34002,4);
INSERT INTO stanza VALUES('K890','4','기도의 무릎 강한 자 세상을 이기네<br/>비겁히 떨지 말고서 기도를 하여라<br/>',NULL,34003,5);
INSERT INTO stanza VALUES('K890','5','기도가 없이 믿는 자 허수아비로다<br/>마귀에게 지지 말고 기도를 하여라<br/>',NULL,34004,6);
INSERT INTO stanza VALUES('K890','6','마귀가 제일 힘써서 기도 방해하니<br/>모략에 걸리지 말고 힘써 기도하라<br/>',NULL,34005,7);
INSERT INTO stanza VALUES('K890','7','기도의 힘만 얻으면 못 이룰 것 없네<br/>하늘 창고 모든 축복 다 얻으리로다<br/>',NULL,34006,8);
INSERT INTO stanza VALUES('K891','1','나 어느 곳에 있든지 늘 맘이 편하다<br/>주 예수 주신 평안함 늘 충만하도다<br/>',NULL,34007,1);
INSERT INTO stanza VALUES('K891','chorus','나의 맘 속이 늘 평안해<br/>나의 맘 속이 늘 평안해<br/>악한 죄 파도가 많으나 맘이 늘 평안해<br/>',NULL,34008,2);
INSERT INTO stanza VALUES('K891','2','내 맘에 솟는 영생수 한없이 흐르니<br/>목마름 다시 없으며 늘 평안하도다<br/>',NULL,34009,3);
INSERT INTO stanza VALUES('K891','3','참되신 주의 사랑을 형언치 못하네<br/>그 사랑 내 맘 여시고 소망을 주셨네<br/>',NULL,34010,4);
INSERT INTO stanza VALUES('K891','4','주 예수 온갖 고난을 왜 몸소 당했나<br/>주 함께 고난 받으면 면류관 얻겠네<br/>',NULL,34011,5);
INSERT INTO stanza VALUES('K892','1','내 영혼의 그윽히 깊은 데서 맑은 가락이 울려나네<br/>하늘 곡조가 언제나 흘러나와 내 영혼을 고이싸네<br/>',NULL,34012,1);
INSERT INTO stanza VALUES('K892','chorus','평화 평화로다 하늘 위에서 내려오네<br/>그 사랑의 물결이 영원토록 내 영혼을 덮으소서<br/>',NULL,34013,2);
INSERT INTO stanza VALUES('K892','2','내 맘 속에 솟아난 이 평화는 깊이 묻히인 보배로다<br/>나의 보화를 캐내어 가져갈 자 그 누구랴 안심일세<br/>',NULL,34014,3);
INSERT INTO stanza VALUES('K892','3','내 영혼에 평화가 넘쳐남은 주의 축복을 받음이라<br/>내가 주야로 주님과 함께 있어 내 영혼이 편히 쉬네<br/>',NULL,34015,4);
INSERT INTO stanza VALUES('K892','4','이 땅 위의 험한 길 가는 동안 참된 평화가 어디 있나<br/>우리 모두 다 예수를 친구 삼아 참 평화를 누리겠네<br/>',NULL,34016,5);
INSERT INTO stanza VALUES('K893','1','내 영혼이 은총 입어 중한 죄짐 벗고 보니<br/>슬픔 많은 이 세상도 천국으로 화하도다<br/>',NULL,34017,1);
INSERT INTO stanza VALUES('K893','chorus','할렐루야 찬양하세 내 모든 죄 사함 받고<br/>주 예수와 동행하니 그 어디나 하늘 나라<br/>',NULL,34018,2);
INSERT INTO stanza VALUES('K893','2','주의 얼굴 뵙기 전에 멀리 뵈던 하늘 나라<br/>내 맘속에 이뤄지니 날로 날로 가깝도다<br/>',NULL,34019,3);
INSERT INTO stanza VALUES('K893','3','높은 산이 거친 들이 초막이나 궁궐이나<br/>내 주 예수 모신 곳이 그 어디나 하늘 나라<br/>',NULL,34020,4);
INSERT INTO stanza VALUES('K894','1','어서 돌아오오 어서 돌아만 오오<br/>지은 죄가 아무리 무겁고 크기로<br/>주 어찌 못 담당하고 못 받으시리요<br/>우리 주의 넓은 가슴은 하늘보다 넓고 넓어<br/>',NULL,34021,1);
INSERT INTO stanza VALUES('K894','2','어서 돌아오오 어서 돌아만 오오<br/>우리 주는 날마다 기다리신다오<br/>밤마다 문 열어 놓고 마음 졸이시며<br/>나간 자식 돌아오기만 밤새 기다리신다오<br/>',NULL,34022,2);
INSERT INTO stanza VALUES('K894','3','어서 돌아오오 어서 돌아만 오오<br/>채찍 맞아 아파도 주님의 손으로<br/>감싸시고 어루만져 위로해 주시는<br/>우리 주의 넓은 품으로 어서 돌아오오 어서<br/>',NULL,34023,3);
INSERT INTO stanza VALUES('K895','1','십자가를 질 수 있나 주가 물어 보실 때<br/>죽기까지 따르오리 저들 대답하였다<br/>',NULL,34024,1);
INSERT INTO stanza VALUES('K895','chorus','우리의 심령 주의 것이니 당신의 형상 만드소서<br/>주 인도따라 살아갈 동안 사랑과 충성 늘 바치오리다<br/>',NULL,34025,2);
INSERT INTO stanza VALUES('K895','2','너는 기억하고 있나 구원받은 강도를<br/>저가 회개하였을 때 낙원 허락 받았다<br/>',NULL,34026,3);
INSERT INTO stanza VALUES('K895','3','주께 네 혼 맡기겠나 최후 승리 믿으며<br/>걱정 근심 어둠 그늘 너를 둘러 덮을 때<br/>',NULL,34027,4);
INSERT INTO stanza VALUES('K895','4','이런 일 다 할 수 있나 주가 물어 보실 때<br/>용감한 자 옛날처럼 선뜻 대답하리라<br/>',NULL,34028,5);
INSERT INTO stanza VALUES('K896','1','겟세마네 동산에서 기도하실- 때 주님의<br/>땀 방울은- 피로 변했네 하나님을 거역-한<br/>나를 위하여 순종의 속죄피-를 흘려 주셨네<br/>',NULL,34029,1);
INSERT INTO stanza VALUES('K896','chorus','아 아 아 아 주의 사랑 깊고 크셔-라<br/>내- 영혼에 파도 처럼 메아리쳐 온-다<br/>',NULL,34030,2);
INSERT INTO stanza VALUES('K896','2','빌라도의 뜰에 서서 가시관 쓸 때 주님의<br/>온 얼굴은 피로 젖었네 온 인류의 저주를<br/>속하시려고 저주의 가시채로 관을 쓰셨네<br/>',NULL,34031,3);
INSERT INTO stanza VALUES('K896','3','빌라도의 군인들이 때린 채찍에 찢어져<br/>피로 물든 주님 등 허리 온 인류의 질병을<br/>속하셨으니 치료의 강물에서 넘쳐 흐르네<br/>',NULL,34032,4);
INSERT INTO stanza VALUES('K896','4','골고다의 십자가에 달리신 주님 손과 발<br/>옆구리에 입은 상처로 온 몸의 물과 피를<br/>다 흘리셔서 멸망의 죽음에서 날 건지셨네<br/>',NULL,34033,5);
INSERT INTO stanza VALUES('K897','1','주여나의 병든 몸을 지금 고쳐 주소서 모든 병을 고쳐 주마<br/>주 약속 하셨네 내가 지금 굳게 믿고 주님 앞에<br/>구하오니 주여 크신 권능으로곧 고쳐 주소서<br/>',NULL,34034,1);
INSERT INTO stanza VALUES('K897','2','주여당신 뜻이라면나를 고쳐 주소서 머리 위에 기름 붓고<br/>주 앞에 엎드려 모든 것을 다 바치고 간구하는<br/>나의 몸을 지금 주의 약속대로 곧 고쳐 주소서<br/>',NULL,34035,2);
INSERT INTO stanza VALUES('K897','3','주를위해 살겠으니나를 고쳐 주소서 내게 속한 모든 것은<br/>다 주의 것이니 성령이여 강림하사능력있는<br/>손을 펴서 나의 몸을 어루만져 곧 고쳐 주소서<br/>',NULL,34036,3);
INSERT INTO stanza VALUES('K897','4','나의병을 고쳐 주심 내가 믿사옵니다지금부터영원토록<br/>주 찬송하겠네 나를 구원하신말씀 어디든지<br/>전하오리 나의 병을 고쳐 주심 참 감사합니다<br/>',NULL,34037,4);
INSERT INTO stanza VALUES('K898','1','만국에 사모하는 자 반드시 강림하시어<br/>천지를 진동 시키고 네 소원 성취하리라<br/>',NULL,34038,1);
INSERT INTO stanza VALUES('K898','chorus','신실한 약속 붙잡고 조금만 더 기다려라<br/>조금만 더 기다려라<br/>',NULL,34039,2);
INSERT INTO stanza VALUES('K898','2','기도의 응답 없다고 그렇게 낙심 말아라<br/>만사에 때가 있나니 조금만 더 기다려라<br/>',NULL,34040,3);
INSERT INTO stanza VALUES('K898','3','세상의 물결 흉흉코 죄악의 파도 일어도<br/>주님을 앙망하면서 조금만 더 기다려라<br/>',NULL,34041,4);
INSERT INTO stanza VALUES('K898','4','흑암의 권세 팽창코 악마의 시험 많으나<br/>하나님 은혜 힘입어 조금만 더 기다려라<br/>',NULL,34042,5);
INSERT INTO stanza VALUES('K898','5','심신이 피곤하여도 실패를 거듭하여도<br/>성령의 권능 받아서 조금만 더 기다려라<br/>',NULL,34043,6);
INSERT INTO stanza VALUES('K899','1','천사의 말을 하는 사람도 사랑 없으면 소용이 없고<br/>심오한 진리 깨달은 자도 울리는 징과 같네<br/>',NULL,34044,1);
INSERT INTO stanza VALUES('K899','chorus','하나님 말씀 전한다해도 그 무슨 소용있나<br/>사랑없이는 소용이 없고 아무것도 아닙니다<br/>',NULL,34045,2);
INSERT INTO stanza VALUES('K899','2','진리를 보고 기뻐합니다 무례와 사심 품지 않으며<br/>모든 것 믿고 바라는 사랑 모든 것 덮어주네<br/>',NULL,34046,3);
INSERT INTO stanza VALUES('K899','3','지금은 희미하게 보이나 그 때는 주를 맞대고 보리<br/>하나님 나를 알고 계시듯 우리도 주를 알리<br/>',NULL,34047,4);
INSERT INTO stanza VALUES('K9','1','하나님은 생명의 근원 거룩하고 풍성해<br/>영원토록 - 영원 - 토록 생수 - 처럼 흘러<br/>',NULL,34048,1);
INSERT INTO stanza VALUES('K9','2','아들 안에 흐른 - 사랑 인류 - 에게 흘러<br/>생명으로 - 우리 - 안에 흘러 - 들어왔네<br/>',NULL,34049,2);
INSERT INTO stanza VALUES('K9','3','우리들은 각각 - 떠나 제 길 - 로 갔지만<br/>그 아들 우 - 릴 구 - 속해 생명 - 을 주셨네<br/>',NULL,34050,3);
INSERT INTO stanza VALUES('K9','4','우리는 성령의 - 음성 거절 - 할지라도<br/>주는 여전 - 히 내 - 안에 생명 - 공급하네<br/>',NULL,34051,4);
INSERT INTO stanza VALUES('K9','5','이미 나와 영 안 - 에서 연합 - 되신 주님<br/>그 성분으 - 로 교 - 통해 기름 - 부음 주네<br/>',NULL,34052,5);
INSERT INTO stanza VALUES('K9','6','하나님 긍휼과 - 사랑 아들의 - 은혜와<br/>영의 교통 - 날 영 - 원히 풍성 - 누리게 해<br/>',NULL,34053,6);
INSERT INTO stanza VALUES('K9','7','주님의 끝없는 - 사랑 우린 다만 찬양해<br/>서로 화답하며 찬 - 양해 삼일 - 의 하나님<br/>',NULL,34054,7);
INSERT INTO stanza VALUES('K90','1','끝없이 찬양해 구주의 깊은 은혜를<br/>한없이 감복해 몸 버린 구주 은혜에<br/>',NULL,34055,1);
INSERT INTO stanza VALUES('K90','chorus','저 골고다에서 하나님의 아들<br/>당신과 나 위해 못박혔네<br/>',NULL,34056,2);
INSERT INTO stanza VALUES('K90','2','부모의 사랑과 친구의 사랑보다도<br/>더 나은 주 사랑 영원히 찬송하겠네<br/>',NULL,34057,3);
INSERT INTO stanza VALUES('K90','3','마귀는 패하고 죄인은 은혜 받았네<br/>그 누가 우리를 주 사랑에서 끊으랴<br/>',NULL,34058,4);
INSERT INTO stanza VALUES('K900','1','주 하나님 독생자 예수<br/>날 위하여 오시었네<br/>내 모든 죄 용서 하시고<br/>죽음에서 부활하신 나의 구세주<br/>',NULL,34059,1);
INSERT INTO stanza VALUES('K900','chorus','살아계신 주 나의 참된 소망<br/>걱정 근심 전혀 없네<br/>오 나의 주님 날 용서하사<br/>영원한 생명 길로 인도하셨네<br/>',NULL,34060,2);
INSERT INTO stanza VALUES('K900','2','주 안에서 거듭난 생명<br/>도우시는 주의 사랑<br/>참 기쁨과 확신 가지고<br/>예수님의 도우심을 믿으며 살리<br/>',NULL,34061,3);
INSERT INTO stanza VALUES('K900','3','그 언젠가 주 뵐 때까지<br/>주를 위해 싸우리라<br/>승리의 길 멀고 험해도<br/>주님께서 나의 앞길 지켜 주시리<br/>',NULL,34062,4);
INSERT INTO stanza VALUES('K901','1','주여 내 입술 열어 주만 찬송케 합소서<br/>주여 내 입술 열어 주만 찬송케 합소서<br/>주는 제사와 번제 또한 즐겨- 안하셔<br/>그렇지 않으면 내가 그것 드렸으리라<br/>',NULL,34063,1);
INSERT INTO stanza VALUES('K901','2','주여 내 입술 열어 주만 찬송케 합소서<br/>주여 내 입술 열어 주만 찬송케 합소서<br/>하나님 원하는 제사는 상한- 심령-<br/>상하고 통회하는 마음을 주 받으시리<br/>',NULL,34064,2);
INSERT INTO stanza VALUES('K901','3','주여 내 입술 열어 주만 찬송케 합소서<br/>주여 내 입술 열어 주만 찬송케 합소서<br/>주의 은택으로 시온에 선을 행하소서<br/>예루살렘 성- 쌓으소서 건축하소서<br/>',NULL,34065,3);
INSERT INTO stanza VALUES('K902','1','다 함께 영 안에 찬송하세 마음을 다하여 찬송해<br/>주님을 향하여 찬송하세 주 안에 하나로 찬송해<br/>',NULL,34066,1);
INSERT INTO stanza VALUES('K902','2','여러 해 동안을 종교 안에 생각에 빠져서 지냈네<br/>감정에 빠져서 구했지만 늘 항상 흑암에 있었네<br/>',NULL,34067,2);
INSERT INTO stanza VALUES('K902','3','지금은 우리 영 훈련해서 주님을 만지며 누리네<br/>주님을 먹고 또 마심으로 언제나 빛 속에 살겠네<br/>',NULL,34068,3);
INSERT INTO stanza VALUES('K902','4','성령 안의 생명 할렐루야 날마다 내 안에 새로움<br/>생각을 영으로 바꿀 때면 그 모든 풍성을 누리네<br/>',NULL,34069,4);
INSERT INTO stanza VALUES('K903','1','금과 은 나 없어도 내게 있는 것 네게 주니<br/>곧 나사렛 예수 이름으로 일어나 걸으라<br/>그는 걸었네 뛰었네 찬양했네 그는 걸었네 뛰었네 찬양했네<br/>곧 나사렛 예수 이름으로 일어나 걸으라<br/>',NULL,34070,1);
INSERT INTO stanza VALUES('K903','2','금과 은 나 없어도 칠 배의 영 나 있으니<br/>곧 나사렛 예수 이름으로 일어나 걸으라<br/>나는 일어나 주님을 간증해 교회 가운데서 주를 증거해<br/>할렐루야 주님을 찬양해 주 풍성 나타내리<br/>',NULL,34071,2);
INSERT INTO stanza VALUES('K904','1','나는 사랑해 주 예수 그는 생명 주는 영<br/>나는 주와- 연합해 한 영 되-었네<br/>',NULL,34072,1);
INSERT INTO stanza VALUES('K904','2','나는 호흡해 주 예수 그는 생명의 호흡<br/>나는 주를- 호흡해 충만 되-었네<br/>',NULL,34073,2);
INSERT INTO stanza VALUES('K904','3','주 예수- 주 예수 주 예수- 나의 주<br/>주의 이름- 부를 때 풍성 넘-치네<br/>',NULL,34074,3);
INSERT INTO stanza VALUES('K905','1','주 여호와는 나의 산업이시-며 내 잔의 소득<br/>주 여호와는 나의 산업이시-며 내 잔의 소득<br/>주가 생명길 보이시니 주 앞엔 기쁨 충-만해<br/>주의 우편엔 영원한 즐거움 있나이다<br/>주 여호와는 나의 산업이시-며 내 잔의 소득<br/>주 여호와는 나의 산업이시-며 내 잔의 소득<br/>',NULL,34075,1);
INSERT INTO stanza VALUES('K905','2','주 여호와 늘 내 앞에 모심이-여 내 우편에 계셔<br/>주 여호와 늘 내 앞에 모심이-여 내 우편에 계셔<br/>주가 생명길 보이시니 주 앞엔 기쁨 충-만해<br/>주의 우편엔 영원한 즐거움 있나이다<br/>주 여호와 늘 내 앞에 모심이-여 내 우편에 계셔<br/>주 여호와 늘 내 앞에 모심이-여 내 우편에 계셔<br/>',NULL,34076,2);
INSERT INTO stanza VALUES('K905','3','이러므로 내 영과 마음이 즐거워 편히 거하리<br/>이러므로 내 영과 마음이 즐거워 편히 거하리<br/>주가 생명길 보이시니 주 앞엔 기쁨 충-만해<br/>주의 우편엔 영원한 즐거움 있나이다<br/>이러므로 내 영과 마음이 즐거워 편히 거하리<br/>이러므로 내 영과 마음이 즐거워 편히 거하리<br/>',NULL,34077,3);
INSERT INTO stanza VALUES('K906','1','주-께서 나의 슬픔 변케 하여 춤이 되게 하시며<br/>나의 베옷 벗-기고 기쁨으로 띠 띠우셨나이다<br/>이는 나의 영광으로 항상 주를 찬송케 하려 하심이니<br/>내 주께 영영 감사하리다<br/>',NULL,34078,1);
INSERT INTO stanza VALUES('K906','2','주-께서 나의 영혼 음부에서 끌어내어 살리사<br/>무덤으로 내려가지 않게 하니 주 찬송할지어다<br/>저녁에는 울-음이 기숙해도 아침엔 기쁨 오리로다<br/>주 이름 영영 감사하리다<br/>',NULL,34079,2);
INSERT INTO stanza VALUES('K907','1','오라 여호와께노래하자 우리 구원의 반석 함께 즐거이 부르세<br/>오라 여호와께노래하자 우리 구원의 반석 함께 즐거이 부르세<br/>우리 감사함으로 그의 앞에 나가며 시로 그를 향해 즐거이 불러<br/>',NULL,34080,1);
INSERT INTO stanza VALUES('K907','chorus','여호와는 모든 신 위에 왕 크신- 하나님<br/>',NULL,34081,2);
INSERT INTO stanza VALUES('K907','2','땅의 깊은 곳 그 위에 있고 산들의 높은 것도 또한 그의 것이로다<br/>땅의 깊은 곳 그 위에 있고 산들의 높은 것도 또한 그의 것이로다<br/>저 바다가 그의 것 그가 만드셨고육지도 그의 손이 지으셨도다<br/>',NULL,34082,3);
INSERT INTO stanza VALUES('K907','3','오라 주 앞에 굽혀 경배해 우리를 지으신 주 그 앞에 무릎을 꿇자<br/>오라 주 앞에 굽혀 경배해 우리를 지으신 주 그 앞에 무릎을 꿇자<br/>대저 저는 우리의 하나님이시오 우리는 그의 백성 그 손의- 양<br/>',NULL,34083,4);
INSERT INTO stanza VALUES('K908','1','존귀와 권위 입으셨네 주가- 옷을 입으심-같이<br/>빛을 입으시며- 하늘을 휘장같-이 쳐<br/>물- 위에 자기의 누각의- 들보 얹으시며-<br/>구름을 수레로- 삼고 바람 날개로 다니셔<br/>바람으로 그의 사자를 삼으-시며<br/>화염으로 사역자 삼으시네<br/>내 혼아 주 송축하라 나의 주는 심-히 광대하시며<br/>존귀와 권위 입으셨네 주가- 옷을 입으심-같이<br/>빛을 입으시며- 하늘을 휘장같-이 쳐<br/>물- 위에 자기의 누각의- 들보 얹으시며-<br/>구름을 수레로- 삼고 바람 날개로 다니셔<br/>바람 날개로 다니셔 바람 날개로 다니셔<br/>',NULL,34084,1);
INSERT INTO stanza VALUES('K909','1','전능하신 주 하나님 전능하신 주 여호와<br/>이 땅을- 해 돋는데-에서 지는데까지<br/>말씀으로 부르셨네 온전하고- 아름다우신 주<br/>시온-에서 온전하고- 아름다우신 주 빛 발-했네<br/>',NULL,34085,1);
INSERT INTO stanza VALUES('K909','2','전능하신 주 하나님 전능하신 주 여호와<br/>이 땅을- 해 돋는데-에서 지는데까지<br/>말씀으로 부르셨네 주 하나님- 오셔서 잠잠치<br/>않으-리라 주 하나님- 윗 하늘과 땅에 선포하시리<br/>',NULL,34086,2);
INSERT INTO stanza VALUES('K909','3','전능하신 주 하나님 전능하신 주 여호와<br/>이 땅을- 해 돋는데-에서 지는데까지<br/>말씀으로 부르셨네 내 성도를- 모으라 내 앞에<br/>함께- 모아 그럴 때에- 하늘이 그의 공의 선포하리<br/>',NULL,34087,3);
INSERT INTO stanza VALUES('K909','4','전능하신 주 하나님 전능하신 주 여호와<br/>이 땅을- 해 돋는 데-에서 지는데까지<br/>말씀으로 부르셨네 온전하고- 아름다우신 주<br/>시온-에서 온전하고- 아름다우신 주 빛 발-했네<br/>',NULL,34088,4);
INSERT INTO stanza VALUES('K91','1','저 갈보리에서 - 주 죽어야 했네<br/>그렇지 않으면 은혜 문 닫히네<br/>하나님 아들 피 흘려야 죄인들이 정결케 돼<br/>죄인들이 정결케 되네<br/>',NULL,34089,1);
INSERT INTO stanza VALUES('K91','2','내 받을 형벌 인해 주 죽어야 했네<br/>그렇지 않으면 공의 못 이루네<br/>율법의 요구 못 갚으면 죄악 용서될 수 없네<br/>죄악 용서될 수 없다네<br/>',NULL,34090,2);
INSERT INTO stanza VALUES('K91','3','주 믿는 자들 대신해 사지에 서서<br/>죽으신 주 예수 내 죄 담당했네<br/>십자가에서 피 흘리사 모든 사람 죄 담당해<br/>모든 사람 죄 담당했네<br/>',NULL,34091,3);
INSERT INTO stanza VALUES('K91','4','그분은 자신을 구원하지 않았네<br/>오 끝없는 사랑에 우리 맘 녹네<br/>우리의 마음 냉담해도 그 사랑이 감동케 해<br/>주를 향해 찬송케 하네<br/>',NULL,34092,4);
INSERT INTO stanza VALUES('K910','1','오른손을 붙드셨나이다-<br/>주의 교훈으로 나를 인도하시고<br/>후에는 영광으로 날 영접하-리<br/>하늘에 주 외에 누가- 내게 있으리요<br/>땅에도 주밖에 없네-<br/>육체와 힘 쇠잔하나 주는 내 맘의 반석<br/>영원한 내 분깃-이-라-<br/>육체와 힘 쇠잔하나 주는 내 맘의 반석<br/>영원한 내 분깃-이-라-<br/>',NULL,34093,1);
INSERT INTO stanza VALUES('K911','1','나로 나의 연-약함을 알게 하소서 알게 하소서<br/>주가 나의 날을 손 넓이 만큼 되게 하시매<br/>나의 일생이 주 앞엔 없는 것 같고<br/>든든히 선 때도 허사 뿐이니이다- 셀라-<br/>진실-로 모든 사람들은- 그림-자 같이 다니고-<br/>다 헛된 일에 분요하며 재물을 쌓으나 헛 되네<br/>주여 내 무엇 바라리요 나-의 소망 주께 있나이다<br/>주여 내 무엇 바라리요 나의 소망 주께 있나이다<br/>',NULL,34094,1);
INSERT INTO stanza VALUES('K912','1','더욱더 더욱더 우리 속에서 자라네<br/>황금 꽃 피우며 영원히 자라게 하소-서-<br/>우리 속 주님을 모두 알게 될 때까지<br/>',NULL,34095,1);
INSERT INTO stanza VALUES('K913','1','오른 손 거룩한 팔로 큰 구원 베푸셨도다<br/>여호와의 구원을 우리에게 알게 하시고<br/>그 의를 열방의 목전에 밝히 나타내-셨네<br/>이스라엘 집에 향하신 그의 인자와 성-실함을<br/>기-억하셨으므로 온 땅이 구원보았네<br/>온 땅이여 여-호와께 즐-거이 소리할-지-라<br/>소리를 발하여 즐거이 노래하며 찬-양해<br/>수금으로 찬양하라 수금과 소리로 찬양해<br/>나팔과 호각 불면서 왕 여호와께 찬양해<br/>',NULL,34096,1);
INSERT INTO stanza VALUES('K914','1','내 구주 죽으신 십자가 하나님 만족게 하였네<br/>그 피로 내 죄를 씻었네 주를 찬양해<br/>',NULL,34097,1);
INSERT INTO stanza VALUES('K914','chorus','주를 찬양해- 주를 찬양해-<br/>그 피로 내 죄를 씻었네 주를 찬양해<br/>',NULL,34098,2);
INSERT INTO stanza VALUES('K914','2','날 구원한 이 샘 마시며 은혜의 구속을 누리네<br/>영원토록 누리고 누려 주를 찬양해<br/>',NULL,34099,3);
INSERT INTO stanza VALUES('K914','3','내 구주 죽으신 그 때에 우리 모든 죄빚 갚았네<br/>생수 근원 활 짝 열렸네 주를 찬양해<br/>',NULL,34100,4);
INSERT INTO stanza VALUES('K914','chorus','주를 찬양해- 주를 찬양해<br/>생수 근원 활짝 열렸네 주를 찬양해<br/>',NULL,34101,5);
INSERT INTO stanza VALUES('K914','4','구속과 생명을 누리네 그 피로 정결함 얻고서<br/>생수를 영원히 마시네 주를 찬양해<br/>',NULL,34102,6);
INSERT INTO stanza VALUES('K915','1','내 부르짖음 들으셨도다-<br/>기가 막힐 웅덩이와- 수렁서 끌어 올려-<br/>내 발을 반석 위에 두사 견고케 하셨도다<br/>새 노래 곧 주께 올릴 찬송 입에 두셨으니<br/>많은 사람이 주 보고 두려워 해-<br/>여호와를 의지하고 교만하고 거짓된 자-<br/>돌아보지 않는 자는 복이 있도다<br/>주여 주의 행사와 우리를 향하신 생각 많-아-<br/>내가 그 수 셀수도 없나이다-<br/>여호와를 의지하고 교만하고 거짓된 자-<br/>돌아보지 않는 자는 복이 있도다<br/>주여 주의 행사와 우리를 향하신 생각 많-아-<br/>내가 그 수 셀수도 없나이다- - -<br/>주여 주의 행하신 기적 많아-<br/>',NULL,34103,1);
INSERT INTO stanza VALUES('K916','1','내 마음 눌릴 때 땅 끝에서부터-<br/>주께 부르짖으오리니<br/>나보다 높은 바위에 인도하소서<br/>주는 내 피난처시요 견고한 망대심이니이다<br/>내 영원히 주 장막에 거하며-<br/>주 날개 밑에 피하리이다 셀라<br/>내 서원 들으사 이름 경외하는 자의<br/>얻을 기업 내게 주셨나이다-<br/>주가 왕을 장수케 하사<br/>그 나이 여러 대에 미치게 하시리<br/>주는 내 피난처시요 견고한 망대심이니이다<br/>내 영원히 주 장막에 거하며-<br/>주 날개 밑에 피하리이다 셀라<br/>저가 주 앞에 영-원히 거하리니<br/>인자-와 진리로 저를 보호하소서<br/>그리하면 내가 영원히 주 이름 찬양하며<br/>매일 서원 이행하리 주는 내 피난처시요<br/>견고한 망대심이니이다<br/>내 영원히 주 장막에 거하며-<br/>주 날개 밑에 피하리이다 셀라<br/>주는 내 피난처시요 견고한 망대심이니이다<br/>내 영원히 주 장막에 거하며-<br/>주 날개 밑에 피하리이다 셀라<br/>',NULL,34104,1);
INSERT INTO stanza VALUES('K917','1','푸른 초장 쉴만한 물가로 인도해- 나의 영혼 소생시켜<br/>그 이름 위해- 의의 길- -로 - - 인도하시네- -<br/>내 비록 사망의 음침한 길 갈지라도<br/>해받음을 두려워 아니할 것은-<br/>나의 주께서 함께 하심이로다-<br/>주 지팡이와 막대기-가 나를- 안위하시네- -<br/>안위하시네- 원수의 목전에서 상 주며- -<br/>기름 부으시니- 나의 잔 넘-쳐- -나의 평생에<br/>선 -하심과 인자-하심이 정녕 나를- 따르리니-<br/>나의 평생에 선-하심과 인자-하심이<br/>정녕 나를- 따르리니- -<br/>내가 여호와의 집에 영원히<br/>내가 여호와의 집에- 영원히 거하리로다<br/>영 -원-히 여호와의 집에 영원히 거- -하리로다<br/>',NULL,34105,1);
INSERT INTO stanza VALUES('K918','1','내 누구를 두려워 하리요 주 나의 생명이니-<br/>내가 여호와께 청하였던 한 가-지 일<br/>곧 그것 구하리니 곧 나로 내 생전에 주 집에 거하여<br/>주 아름다움을 앙망하며 주 사모하게 하실 것이라-<br/>오 주여! 내가 부르짖을 때- 들으시고<br/>나를 긍휼히 여겨 응-답하-소서-<br/>주 얼굴- 찾으라실 때- 내 마음이 주 얼굴 찾으리다<br/>주께 말했나이다- 너는 주를 바-랄찌-어다-<br/>넌 강-하고 담대하여 주 바랄지어다-<br/>',NULL,34106,1);
INSERT INTO stanza VALUES('K919','1','그의 기초가 성산에 있네-<br/>주는 야곱의 모든 거-처보다<br/>더- 시온의 문들을 사랑하-셔<br/>하나님의 성이여 너 영-광스럽다-<br/>야곱의 모든 거처 보다 더-<br/>이 사람 저 사람이 시온에서 태어났네-<br/>지존자가 시온 세우리- -<br/>그의 기초가 성-산에 있네-<br/>그의 기초가 성-산에 있네-<br/>주가 모든 민족 등록할 때<br/>이- 사람도- 거기에서 났다 하리-<br/>춤추며 노래하는 자- 다 함께 소리쳐-<br/>시-온을 찬양하리-<br/>춤추며 노래하는 자- 내 모든 근원이-<br/>네게 있다 하리로다-<br/>',NULL,34107,1);
INSERT INTO stanza VALUES('K92','1','오 외로울 때 사방이 다 캄캄할 때에<br/>하나님 아들 혈육입고 우리 대신<br/>비참하게 죽음 맛봤네 영광의 주<br/>못 박혔네 사람의 배척당했네<br/>',NULL,34108,1);
INSERT INTO stanza VALUES('K92','2','하나님 사람 놀라운 그 출생과 죽음<br/>영원 과거와 영원 미래 얼굴 들어<br/>주를 보며 주목한다네 주 십자가는<br/>영원히 내 아름다운 집일세<br/>',NULL,34109,2);
INSERT INTO stanza VALUES('K92','3','오 그 십자가 바라볼 때 내 맘 부서져<br/>사랑의 체현 골고다서 죽으실 때<br/>고통 속에 부르짖었네 “엘리 엘리<br/>라마 사박다니” 그 음성 간구 들리네<br/>',NULL,34110,3);
INSERT INTO stanza VALUES('K92','4','오 우리들이 진노받아 마땅한데도<br/>왜 하나님은 그의 아들 우리 위해<br/>고난 받고 죽게 하셨나 공의가 내 주<br/>죽였네 나 또한 함께 죽었네<br/>',NULL,34111,4);
INSERT INTO stanza VALUES('K92','5','난 주와 함께 죽음에서 소생되었네<br/>주님은 머리 우리는 몸 우린 주와<br/>하나님께 함께 속했네 하나님<br/>축복받고서 “아바 아버지” 부르네<br/>',NULL,34112,5);
INSERT INTO stanza VALUES('K920','1','내게 말할 때에 기뻐했네<br/>우리 발 - 이 성 안에 섰네<br/>오 예루살렘 예루살렘아-<br/>넌 성읍같이 조밀한 성같이 건설됐도다<br/>여호와-의 지파들-이<br/>여 -호와의 이름에 감사하러<br/>이스라엘의 전 -례대로 그리로 올라가네<br/>거기 판단의 보좌 두셨으니<br/>곧 다윗 집의 보좌로다<br/>예루살렘을 사 -랑하는 자 형통하리로-다<br/>네 성 안에는 평강이 있고<br/>네 궁중엔 형통있을지어다<br/>내가 내 형제와 붕우를 위하여 말하리니<br/>네 가운데에 평강 있으라-<br/>주 하나님의 집 위하여 네 복 구하리라<br/>',NULL,34113,1);
INSERT INTO stanza VALUES('K921','1','레바논 백향목같이- 발육하리라-<br/>주의 의 나타내- 주는 나의- 반-석-<br/>주 집에 심겨졌음이여-<br/>주의 궁정에서 흥왕하리로다-<br/>주 하나님의-궁정에서- 흥왕하- -리로다<br/>늙어도 열매 맺으리라- 진액 풍족하고<br/>빛 청청하-여- 주 정직하심- 나타내리로다-<br/>주는 나의- 반-석- 의인은 종려나무 같이-<br/>번성하고 레바논 백향목같이- 발육-하여<br/>주의 정직하심- 영원토록 나타내리로다-<br/>',NULL,34114,1);
INSERT INTO stanza VALUES('K922','1','내가 여호와께 구하-던 오직 한가지 일은-<br/>나로 내 생전에 주의 집에 거하는 것이요-<br/>',NULL,34115,1);
INSERT INTO stanza VALUES('K922','chorus','주의 아름다움 보기 위하여<br/>성전 안에 주님 사모하게 해<br/>주의 아름다움 보기 위하여<br/>성전 안에 주님 사모하게 해-<br/>',NULL,34116,2);
INSERT INTO stanza VALUES('K922','2','환난 중에 주는 초막 속에 나를 비밀히 지켜-<br/>그 장막 은밀히 숨기시며 바위 위에 두네-<br/>',NULL,34117,3);
INSERT INTO stanza VALUES('K923','1','우리가 꿈꾸는 것- 같았도다<br/>그-때에 우리 입엔 웃음 가득하고<br/>우리 혀에는 찬양이 찼었도다<br/>여호와께서 우리를 위해 일했네<br/>주가- 큰일 하셨으니- 우린- 기쁘다<br/>크신 주 여호와께서 우리의 포로를<br/>남-방 시내들 같이 돌리소서-<br/>눈물을 흘리며 씨를 뿌린 자는<br/>기쁨으로 거-두리로다-<br/>울며 씨를 뿌리러 나-가는 자는 정녕 기쁨으로<br/>단을 가지고 오리라<br/>여호-와께서 우리를 위해- 일했네-<br/>주가- 큰 일 하셨으니 우린- 기쁘다<br/>주께서 시온의 포로를 돌리실 때에<br/>우리가 꿈꾸는 것- 같았도다-<br/>',NULL,34118,1);
INSERT INTO stanza VALUES('K924','1','하나님의 성과 거룩한 산에서 찬양해<br/>높고 아름다와 온 땅이 기뻐해<br/>큰 왕의 성 북방에 있는 시온 산이 그러하다<br/>큰 왕의 성 북방에 있는 시온 산 그러해<br/>',NULL,34119,1);
INSERT INTO stanza VALUES('K925','1','우리아들들은 어리다가장성한나무 같으니행복한- 백성<br/>우리아들들은 어리다가장성한나무같으니행복한- 백성<br/>행복-한백성주 하나님의 백성<br/>',NULL,34120,1);
INSERT INTO stanza VALUES('K925','chorus','행복-한 백성주 하나님의백성<br/>행복한- 백성 주하나님의 백성<br/>여호와를하나님삼는백성<br/>',NULL,34121,2);
INSERT INTO stanza VALUES('K925','2','우리딸-들은아름답게 다듬은 모퉁이 돌같으니행복한- 백성<br/>우리딸 -들은아름답게 다듬은 모퉁이 돌같으니 행복한- 백성<br/>우리딸 -들은아름답게 다듬은 모퉁이 돌같으니 행복한- 백성<br/>',NULL,34122,3);
INSERT INTO stanza VALUES('K925','3','우리곳간에는 백-가지 곡-식이 가득하니행복한- 백성<br/>우리 곳간에는백-가지곡 -식이가득하니행복한- 백성<br/>우리 곳간에는백-가지곡 -식이가득하니행복한- 백성<br/>',NULL,34123,4);
INSERT INTO stanza VALUES('K925','4','우리양은들에서천-천과만만으로 번성하니 행복한- 백성<br/>우리양은들에서천-천과만만으로 번성하니행복한- 백성<br/>우리양은들에서천-천과만만으로 번성하니행복한- 백성<br/>',NULL,34124,5);
INSERT INTO stanza VALUES('K926','1','내 사랑아 내가 너를 바로의 병거의 준마에 비했구나<br/>네 두 뺨은 땋은 머리로 너의 목엔 구슬꿰미 아름답네<br/>우-리가 너를 위하여 나의 영광의 금사슬을<br/>은을 박아 만들리라 은을 박아 만들리라<br/>',NULL,34125,1);
INSERT INTO stanza VALUES('K926','2','왕이 상에 앉았을 때 나의 나드 기름 향기 토하였구나<br/>나의 사랑 하는 자는 나의 품 가운데 몰약 향낭이요<br/>나-의 사랑하는 자는 내게 엔게디 포도원의<br/>고벨화 송이로구나 고벨화 송이로구나<br/>',NULL,34126,2);
INSERT INTO stanza VALUES('K926','3','내 사랑 너 어여쁘고 어여쁘다 너의 눈이 비둘기 같아<br/>나의 사랑하는 자야 어여쁘고 화창하다 너의 모습<br/>우-리 침상은 푸르고 우리 집은 백향목 들보<br/>잣나무 석가래구나 잣나무 석가래구나<br/>',NULL,34127,3);
INSERT INTO stanza VALUES('K927','1','난 샤론의 수선화요 골짜기의 백합화라<br/>여자들 중 내 사랑은 가시밭에 백합화라<br/>남자들 중 내 사랑은 수풀 속사과 나무라<br/>나 그 그늘에 앉아서 참 심히 기뻐하였고<br/>그 실과 단 맛 보았네 그 실과 단 맛 보았네<br/>',NULL,34128,1);
INSERT INTO stanza VALUES('K927','2','그가 나를 인도하여 잔칫집 들어 갔으니<br/>그 사랑이 내 위에서 승리의 깃발 이라네<br/>넌 건포도로 날 돕고 사과로 시원케 하라<br/>내가 사랑을 인하여 감당치 못할 병났네<br/>그 사랑 나를 이끄네 그 사랑 나를 이끄네<br/>',NULL,34129,2);
INSERT INTO stanza VALUES('K927','3','그의 왼손 내 머리에 베개로 받쳐 주시고<br/>그의 오른손은 나를 그 품에 안아 주시니<br/>예루살렘 여자들아 노루와 들사슴으로<br/>너희게 부탁하노니 내 사랑 원하기 전에<br/>흔들고 깨우지 마라 흔들고 깨우지 마라<br/>',NULL,34130,3);
INSERT INTO stanza VALUES('K927','4','나의 사랑하는 자의 목소리 내게 들린다<br/>보라 그가 산을 넘어 신속히 달려오누나<br/>나의 사랑하는 자는 노루와 사슴 같아서<br/>우리의 벽뒤에 서서 창으로 들여다 보네<br/>창살 틈으로 엿보네 창살 틈으로 엿보네<br/>',NULL,34131,4);
INSERT INTO stanza VALUES('K928','1','쏟은 향 기름 같은 이름- 예수 예- -수 예수 예- -수<br/>쏟은 향 기름 같-은 이-름 쏟은 향 기름 같은 이름-<br/>',NULL,34132,1);
INSERT INTO stanza VALUES('K928','2','처녀들이 사랑하는- 예수 예- -수 예수 예- -수<br/>처녀들이 사랑하는- 예수 사랑하는 이름 예수-<br/>',NULL,34133,2);
INSERT INTO stanza VALUES('K928','3','술 보다 나은 네 사랑- 예수 예- -수 예수 예- -수<br/>네 사랑이 포도주 보-다 포도주 보다 나음이라-<br/>',NULL,34134,3);
INSERT INTO stanza VALUES('K928','4','너를 따라 달려가리- 예수 예- -수 예수 예- -수<br/>나를 인도하라 우리들이 너를 따라 달려가리-<br/>',NULL,34135,4);
INSERT INTO stanza VALUES('K928','5','어여쁘다 나의 사랑- 예수 예- -수 예수 예- -수<br/>보라 어여쁜 나의 사랑을 보라 어여쁜 내 사랑-<br/>',NULL,34136,5);
INSERT INTO stanza VALUES('K928','6','내 마음이 사랑하는- 예수 예- -수 예수 예- -수<br/>내 마음에 사 - 랑하는 자 그를 내가 찾았구나-<br/>',NULL,34137,6);
INSERT INTO stanza VALUES('K928','7','붙잡고 놓지 않으리- 예수 예- -수 예수 예- -수<br/>나는 그-를 붙잡았-네 다시는 놓지 않-으리-<br/>',NULL,34138,7);
INSERT INTO stanza VALUES('K928','8','빨리 달리라 내 사랑- 예수 예- -수 예수 예- -수<br/>빨리 달려 오라 나의 사랑 어서 빨리 달려 오라-<br/>',NULL,34139,8);
INSERT INTO stanza VALUES('K928','9','마음 다해 사랑하는- 예수 예- -수 예수 예- -수<br/>우리 마음을 다해 사랑해 마음 다해 사랑하네-<br/>',NULL,34140,9);
INSERT INTO stanza VALUES('K929','1','그 사랑 내 위에 기라 그 사랑 내 위에 기라<br/>날 잔치 집으로 데려가니 그 사랑 내 위에 기로다<br/>그 사랑이 내 위에 깃발이라네<br/>날 잔칫집으로 데려가니 그 사랑 내 위에 기로다<br/>',NULL,34141,1);
INSERT INTO stanza VALUES('K929','2','그 실과 내 입에 달아 그 실과 내 입에 달아<br/>나 그 그늘 아래 기뻐하네 그 실과 내 입에 달았네<br/>달고 다네 그 실과 내 입에 다네<br/>나 그 그늘 아래 기뻐 하네 그 실과 내 입에 달았네<br/>',NULL,34142,2);
INSERT INTO stanza VALUES('K93','1','웬말인가 나 - 위하여 주 돌아 - 가셨나<br/>진정 나 위해 피 흘려 목숨 - 버 - 리셨나<br/>',NULL,34143,1);
INSERT INTO stanza VALUES('K93','2','내 주께서 내 - 죄 위해 나무에 - 달렸네<br/>넘치는 긍휼과 사랑 끝없 - 는 - 은혜라<br/>',NULL,34144,2);
INSERT INTO stanza VALUES('K93','3','하나님의 그 - 리스도 나 위해 - 죽을 때<br/>저 해도 흑암 되었네 영광 - 감 - 추었네<br/>',NULL,34145,3);
INSERT INTO stanza VALUES('K93','4','그 십자가 바 - 라볼 때 나 참 부 - 끄러워<br/>감사의 마음 끝없어 눈물 - 흘 - 립니다<br/>',NULL,34146,4);
INSERT INTO stanza VALUES('K93','5','주 사랑 빚 갚 - 지 못해 근심 가 - 득차네<br/>내 일생 드려 내 주께 감사 - 드 - 리겠네<br/>',NULL,34147,5);
INSERT INTO stanza VALUES('K930','1','찬송하며 여호와의 주신 은사 누리리<br/>새 곡식과 새 포도주 기름과<br/>어린 양 떼 소 떼의 모임<br/>그 심령은 물 댄 동산 같으리<br/>그들이 돌아와서 시온의 높은 곳에서<br/>찬송하며 누릴 때에 다시 근심 없으리<br/>',NULL,34148,1);
INSERT INTO stanza VALUES('K931','1','보라 저 북방서 폭풍이 불어 온다<br/>주께로부터 불어- 오는 성령일세<br/>주께서 내 쉰 호흡 곧 능력의 공기<br/>우릴 살리는 공기일세<br/>',NULL,34149,1);
INSERT INTO stanza VALUES('K931','2','성령의 바람이 힘센 구름 몰고 와<br/>이는 주의 영광 하-나님 자신일세<br/>덮어 주소서 우리를 이 구름으로<br/>사신 주님- 자신으로<br/>',NULL,34150,2);
INSERT INTO stanza VALUES('K931','3','그 속에 불 있어 사방에 빛 비취네<br/>하나님의 빛 하나-님의 타오-름<br/>우릴 비추사 옛 자아 태우소-서<br/>우릴 정결케 하옵소서<br/>',NULL,34151,3);
INSERT INTO stanza VALUES('K931','4','달군 쇠 나타나 우리 눈에 보이네<br/>금과 은 섞인 이는 어린 양 하나-님<br/>깊은 속에서 누리세 빛나는- 분<br/>더욱 누리고 나타내세<br/>',NULL,34152,4);
INSERT INTO stanza VALUES('K931','5','폭풍과 구름과 불과 단쇠 누리세<br/>주여 폭풍을 더 보내소서<br/>구름으로 덮어주소서 우리 속 태워주소서<br/>밝게 달아 오를때까지<br/>',NULL,34153,5);
INSERT INTO stanza VALUES('K932','1','너희-는 먼저 그의 나라와 그의 의를 구-하라<br/>그러면 이 모든 것을 더하리 할렐-루 할렐루야<br/>구하라 그러면 주실 것이요 찾으라 찾을 것이요<br/>두드리라 그러면 열리리라<br/>',NULL,34154,1);
INSERT INTO stanza VALUES('K932','chorus','할렐-루 할렐루-야 할렐루야<br/>할렐루야 할렐루야 할렐루야<br/>',NULL,34155,2);
INSERT INTO stanza VALUES('K932','2','사람이 떡으로만 살 것 아니요 하나님 입으로 나는<br/>모든- 말씀으로 살 것이라 할렐-루 할렐루야<br/>너희-는 먼저 그의 나라와 그의 의를 구-하라<br/>그러면 이 모든 것을 더하리<br/>',NULL,34156,3);
INSERT INTO stanza VALUES('K933','1','인생의제일 즐거운 혼인 날 잔치가 한참 무르 익은 때<br/>이것 참 포도주가 떨어졌네인생은 바로 이런 것일세-<br/>',NULL,34157,1);
INSERT INTO stanza VALUES('K933','chorus','보라여기 주 예수님 오셔서 물로 새 포도주를만드네-<br/>주 거칠 때 사망은 생명되네 눈먼 자도 밝히 보게 되네-<br/>',NULL,34158,2);
INSERT INTO stanza VALUES('K933','2','한 밤에 행실 좋은 관원 왔네 예수님께가르침 얻으려<br/>교훈은 사람 본성 변케 못해 주 말했네 거듭나야함을-<br/>',NULL,34159,3);
INSERT INTO stanza VALUES('K933','3','그렇게많은 남편 있었지만 목마름은갈수록 더해서<br/>날마다 물 길으러 오던 여자 예수 만나 시원함 얻었네-<br/>',NULL,34160,4);
INSERT INTO stanza VALUES('K933','4','수많은병자들 중 한 사람이물 동하길 기다리고 있네<br/>종교는 결코 그를 치료 못해 예수 오셔 산 말씀 주셨네-<br/>',NULL,34161,5);
INSERT INTO stanza VALUES('K933','5','죽은지나흘 된 자 누워있네무덤 속에 사망에 묶여서<br/>모두 다 둘러서 울고 있을 때 주 오셔 그를 일으키셨네-<br/>',NULL,34162,6);
INSERT INTO stanza VALUES('K933','6','오늘도이 예수님 살아 계셔 누구든지 다 구원하시네<br/>맘 활짝 열고 그 이름 부를 때 그가 오셔 넌 영으로 나리-<br/>',NULL,34163,7);
INSERT INTO stanza VALUES('K934','1','아무 관-계 없고- 성령 안에 누리는<br/>의와 평-강 기쁨- 의와 평강 기쁨-<br/>우리가 화평의일-과 덕 세우는 일을 힘써-<br/>우리가 화평의일-과 덕 세우는 일을 힘써-<br/>하나님의나라는 오-직 성령- 안에서<br/>의와 평강 기-쁨이라- 이로써 그리스도섬기는 자는-<br/>하나님께- 기뻐하심받으며- 이로써주 섬길 때<br/>사람에-게 또한- 칭찬 받-게 돼-<br/>우리가 화평의일-과 덕 세우는 일을 힘써-<br/>우리가 화평의일-과 덕 세우는 일을 힘써-<br/>하나님의나라는 먹-는 것과- 마시는 것과 아무 관-계 없어<br/>',NULL,34164,1);
INSERT INTO stanza VALUES('K935','1','우리 영광 위해 하나님이 만세- 전에 예정하신<br/>자기 사랑하는 자들 위해 하나님께서 예비했네<br/>눈으로도 못 보던 것 귀로도 못 듣던 것 생각 못한 것<br/>',NULL,34165,1);
INSERT INTO stanza VALUES('K936','1','주 예수를 믿음으로 우린 그와 연합-되었네<br/>포도나무와 가지가 생명 안에 하나-이듯이<br/>부활하신 주와 하나됐네 영 안에서 주와 하나되었네<br/>',NULL,34166,1);
INSERT INTO stanza VALUES('K937','1','마지막 아담 이제 생명 주는- 영<br/>한 성령 침례받고 한 몸된 우리들<br/>한 성령 함께 마-셔 그를 함께 마셔-<br/>오 할렐루야 우린 생명의 영 마셔<br/>',NULL,34167,1);
INSERT INTO stanza VALUES('K937','2','오 우린 영광스런 새 언약의 일꾼<br/>의문의 약속 아닌 영의 약속따라<br/>우리는 변화 되-네 주님의 형상으로<br/>영 인해 영광으로 영광에 이르네<br/>',NULL,34168,2);
INSERT INTO stanza VALUES('K938','1','주 하나님 항-상 우릴 이끌어<br/>그리스도 안에 이기게 하네<br/>각 처에서 그-가 우리로 인해<br/>그리스도 아는 냄새 나타내시네<br/>',NULL,34169,1);
INSERT INTO stanza VALUES('K938','chorus','항상 우릴 인도-하여 이기게 하-는<br/>하나님께 감사 감사 드리세<br/>',NULL,34170,2);
INSERT INTO stanza VALUES('K938','2','구원 얻는 자나 망하는 자에게<br/>우리들은 모두 주의 향기라<br/>이들에겐 사망에 이르는 냄새<br/>저들에겐 생-명에 이르는 냄새<br/>',NULL,34171,3);
INSERT INTO stanza VALUES('K939','1','시험에 들때 모든 것을<br/>기쁨으로 여겨 그 모든 것을<br/>기쁨으로 여겨 할렐루야<br/>할렐루야 호산나 할렐루야<br/>할렐루야 호산나 할렐루야<br/>할렐루야 호산나 할렐루야<br/>우린 사방에서 우겨싸도 싸이잖고<br/>답답한 일에 낙심 안해<br/>핍박을 받아도 버린 바 되지 않아<br/>거꾸러 뜨려도 망하잖아<br/>',NULL,34172,1);
INSERT INTO stanza VALUES('K94','1','오 놀라운 주의 구속 은혜의 주 예수<br/>생각지도 못한 구속 날 위해 이뤘네<br/>비밀하고도 거룩한 주 인격 뛰어나<br/>능력의 놀라운 구속 다 찬양 못하리<br/>',NULL,34173,1);
INSERT INTO stanza VALUES('K94','chorus','주의 구속 놀라워 영광스런 새 창조<br/>그 효능 영원하니 그 능력 찬양해<br/>',NULL,34174,2);
INSERT INTO stanza VALUES('K94','2','십자가에서 갈라져 물과 피 흘린 주<br/>내 죄를 대속하시고 생명 분배했네<br/>하나님 기쁨 되도록 피로 날 씻었네<br/>난 생명 안에 거듭나 주와 연합됐네<br/>',NULL,34175,3);
INSERT INTO stanza VALUES('K94','3','거룩한 밀알인 주님 많은 밀 맺었네<br/>우린 당신 성품 얻고 주의 몸 되었네<br/>주께서 우리 생명과 내용이 되시니<br/>우리는 주의 표현과 충만이 된다네<br/>',NULL,34176,4);
INSERT INTO stanza VALUES('K94','4','우리는 주의 몸이요 주님의 거처니<br/>주의 맘 만족케 하며 주의 뜻 이루네<br/>주님의 배필 되어서 주와 함께 살며<br/>주님과 한 몸 되어서 주 소유 누리네<br/>',NULL,34177,5);
INSERT INTO stanza VALUES('K94','5','우리 함께 떡 떼면서 주 기념할 때에<br/>우리의 마음과 영에 감사가 넘치네<br/>주님의 몸과 거처와 배필 된 우리들<br/>놀라운 주님의 구속 높이며 찬양해<br/>',NULL,34178,6);
INSERT INTO stanza VALUES('K940','1','형제들아 기뻐하라 온전하게 될지어다<br/>모든 위로의 하나님의 위로 받으라<br/>',NULL,34179,1);
INSERT INTO stanza VALUES('K940','2','같은 것을 생각하라 또한 평안할지어다<br/>사랑 평강의 하나님이 함께 하시리<br/>',NULL,34180,2);
INSERT INTO stanza VALUES('K940','3','거룩하게 입 맞춤으로 서로 서로 문안하라<br/>모든 성도가 너희에게 문안하노라<br/>',NULL,34181,3);
INSERT INTO stanza VALUES('K940','4','주- 예수 그리스도의 은혜와 하나님 사랑과<br/>성-령의 교통 하심이 함께 있을지어다<br/>',NULL,34182,4);
INSERT INTO stanza VALUES('K941','1','이는 너희가- 죽었- -고 너희-가 죽었고-<br/>너희 생명인 그리스도와 함께 하나님 안에<br/>하나님 안에 감춰졌음이라-<br/>우리 생명인 그리스도-께서 나타날 때<br/>너희도 그와 영광 중에 나타나리-<br/>',NULL,34183,1);
INSERT INTO stanza VALUES('K942','1','하늘에 속한 예-루살렘- 그리고 하늘에 기록된<br/>처음 난 자-들의 교회와 만민의 심판자 하나님-<br/>온전케 된 의인들의 영과- 새- 언약의 중-보자이신-<br/>예수와 아벨의 피보다 더 낫게 말하는 뿌-려진 피니라<br/>하나님은 소멸하는 불-<br/>온전케 된 의인들의 영과- 새- 언약의 중-보자이신-<br/>예수와 아벨의 피보다 더 낫게 말하는 뿌-려진 피니라<br/>하나님은 소멸하는 불- 하나님은 소멸하는 불<br/>',NULL,34184,1);
INSERT INTO stanza VALUES('K943','1','그의 택한 백성들과 연합하려고<br/>하나님 아버지 아들 성령됐네<br/>',NULL,34185,1);
INSERT INTO stanza VALUES('K943','chorus','오 놀라운 축복 기업 삼일 하나님<br/>영 안에서 누리겠네 영원토록<br/>',NULL,34186,2);
INSERT INTO stanza VALUES('K943','2','조직적인 교훈으론 목적 못 이뤄<br/>하나님은 자신 주길 갈망하셔<br/>',NULL,34187,3);
INSERT INTO stanza VALUES('K943','3','삼일 하나님은 교훈 이론 원찮아<br/>오직 사람 안에 자신 넣기 원해<br/>',NULL,34188,4);
INSERT INTO stanza VALUES('K943','4','하나님의 사랑 주의 은혜 성령의 교통<br/>이는 하나님과 사람 연합게 해<br/>',NULL,34189,5);
INSERT INTO stanza VALUES('K943','5','삼일 하나님 내 전체 거룩게하사<br/>영과 혼과 몸 흠 없게 보전하네<br/>',NULL,34190,6);
INSERT INTO stanza VALUES('K944','1','다 주의 이-름 찬-양해 모든 천사 엎드려-<br/>다 경-배 하도다 영-광과 존귀로 관 쓰셨네-<br/>관 쓰- - -셨네 영광 존귀 관 쓰셨네- 만유의 주<br/>',NULL,34191,1);
INSERT INTO stanza VALUES('K944','2','주의 택하신- 백성들아 구속받은 모든 자-<br/>다 경배하여라 은혜로 너희를 구원한 주님께-<br/>다 경- - -배해 무릎 꿇고 모두 경배해 만유의 주<br/>',NULL,34192,2);
INSERT INTO stanza VALUES('K944','3','그 큰 사랑- 어찌 잊으리 나 위해 주 예수-<br/>쓴 잔- 마시셨네 우-리의 모든 것 주께 드려-<br/>주께- - - 드려 모든 소유 주께 드려- 만유의 주<br/>',NULL,34193,3);
INSERT INTO stanza VALUES('K944','4','온 땅의 모-든 나라들 모든 족속 모든 민-족<br/>주께 영광 돌려- 존귀와 권위 주께 돌려-<br/>주께- - - 돌려 존귀 권위 영원토록- 만유의 주<br/>',NULL,34194,4);
INSERT INTO stanza VALUES('K944','5','거룩한 무-리 교회들 주께 경배드리세-<br/>주께- 경배드려 영-원토록 함께 찬양해<br/>영원- - -토록 주께 찬양 영원토록- 만유의 주<br/>',NULL,34195,5);
INSERT INTO stanza VALUES('K945','1','주 찬양하세 주의 영을 주사 주 내 안에 들어와<br/>내 생명 됐네 할렐루야 주의 영이 내 안에 있네<br/>할렐루야 주의 생명 영원히 있네<br/>',NULL,34196,1);
INSERT INTO stanza VALUES('K945','2','주 찬양하세 마지막 아담을 그는 생명 영<br/>하나님 풍성일세 할렐루야 그는 예수 그는 생명 영<br/>할렐루야 연합하여 하나되었네<br/>',NULL,34197,2);
INSERT INTO stanza VALUES('K945','3','영으로 났네 우리 변화되어 하나님 아들 형상을<br/>닮아가네 할렐루야 주께로 나 변화되었네<br/>할렐루야 변화되어 하나 되었네<br/>',NULL,34198,3);
INSERT INTO stanza VALUES('K945','4','주 닮으려면 영 안에서 먹세 항상 주 먹고 마시면<br/>충만되네 할렐루야 내게 속한 완전한 구원<br/>할렐루야 나의 풍성 승리의 생활<br/>',NULL,34199,4);
INSERT INTO stanza VALUES('K946','1','하나님이 사람 됐네 위대한 계획 이루려<br/>인성 입고 사망 거쳐 마귀- 없이 하셨네<br/>할렐루야 다시 사신 그는 바로 인잘세<br/>',NULL,34200,1);
INSERT INTO stanza VALUES('K946','2','주는 그의 인성으로 간사한 자를 묶었네<br/>사람이신 주 예수는 시험하는 자 이겼네<br/>모든 시험 거친 주를 영 안에서 누리네<br/>',NULL,34201,2);
INSERT INTO stanza VALUES('K946','3','인생 거친 주 예수를 포함-한 성령일세<br/>하나님과 사람 모두 포함-한 성령일세<br/>이 영 안에 충만있네 넘치는 공급있네<br/>',NULL,34202,3);
INSERT INTO stanza VALUES('K946','4','기묘하나 실재일세 그 사람 내 안에 사네<br/>그가 내 맘 각 부분에 점점- 퍼져 나가네<br/>할렐루야 할렐루야 그침없이 찬양해<br/>',NULL,34203,4);
INSERT INTO stanza VALUES('K946','5','놀랍고도 영광스런 하나님 나타낸 사람<br/>그의 몸의 지체로서 우린- 그를 나타내<br/>그의 인성 더욱 누려 그의 처소 건축해<br/>',NULL,34204,5);
INSERT INTO stanza VALUES('K947','1','거룩 거룩 거룩 거룩한 성도들<br/>분별되어 그리스도 안에 거룩해<br/>자신 부인하고 주의 사실만 봐<br/>하나님 우릴 성도라 하네<br/>',NULL,34205,1);
INSERT INTO stanza VALUES('K947','2','불러 불러 불러 성도라 불렀네<br/>각처에서 저희와 우리의 주 되신<br/>예수 그리스도 우릴 사로잡네<br/>그는 우리의 놀라운 은혜<br/>',NULL,34206,2);
INSERT INTO stanza VALUES('K948','1','오, 우리의소망되신- 주예수그 - 사랑우리영 불타게 하네<br/>사랑하는 주께 우린- 외치네주- 예수 그이름을높입니다<br/>',NULL,34207,1);
INSERT INTO stanza VALUES('K948','2','오, 주와함께 우린 축복받았네주 -는생명 즐거움 평화 안식<br/>당신의 이름은 우리-의 주제당 -신의사랑은우리의노래<br/>',NULL,34208,2);
INSERT INTO stanza VALUES('K948','3','어찌표현하리요그 - 소중함 그- 친밀함그 사랑스러움을<br/>당신의 아름다움나-타날 때다 -른 모든 것사라져버리네<br/>',NULL,34209,3);
INSERT INTO stanza VALUES('K948','4','오, 주예수당신을 사랑합니다우-리의예수 우리의하나님<br/>당신앞에 나올 때마 -다 우린 당-신에 대한사랑이 자라네<br/>',NULL,34210,4);
INSERT INTO stanza VALUES('K949','1','돌아와 돌아와 주의 집으로 생명 강 흐르는<br/>주의 집으로 주야로 끝없이 흘러 내리네<br/>내게 흘러 생명 열매 맺겠네<br/>',NULL,34211,1);
INSERT INTO stanza VALUES('K949','2','주님의 집에서 생명 강 흘러 온 땅을 적시며<br/>생명 강 흘러 생명수 넘치기 나 참 원하네<br/>나의 주여 이 물 측량하소서<br/>',NULL,34212,2);
INSERT INTO stanza VALUES('K949','3','우리를 측량해 매일 측량해 측량할 수 없이<br/>매일 넘치네 끝없이 넘치어 생명 강 됐네<br/>이 강 물을 마시는 자 살겠네<br/>',NULL,34213,3);
INSERT INTO stanza VALUES('K949','4','우리를 인도해 흐르는 물에 우리를 인도해<br/>넘치기까지 흐르고 흘러서 창수가 되어<br/>우리들을 잠기게 해 영원히<br/>',NULL,34214,4);
INSERT INTO stanza VALUES('K949','5','다 사네 다 사네 모든 만물이 생명 강 흘러서<br/>영원히 사네 풍성한 생명수 흐르는 물에<br/>땅 끝까지 교회 나타나겠네<br/>',NULL,34215,5);
INSERT INTO stanza VALUES('K95','1','오 얼마나 달콤한 이야긴가 하나님의<br/>큰 사랑 아들 보내 하늘 영광 버리고<br/>죽게 하사 그 놀라운 구속을 이루셨네<br/>',NULL,34216,1);
INSERT INTO stanza VALUES('K95','chorus','주님을 찬미해 모든 역사 이룬 주님께<br/>감사해 넓고 큰 은혜여 우리 구주 예수께<br/>영광 돌려 쉬지 않고 주님만 노래하리<br/>',NULL,34217,2);
INSERT INTO stanza VALUES('K95','2','오 얼마나 기묘한 이야긴가 보혈 인해<br/>보좌의 요구 이뤄 의의 심판 짊어진<br/>아들 인해 하나님과 죄인 다 만족케 돼<br/>',NULL,34218,3);
INSERT INTO stanza VALUES('K95','3','오 얼마나 찬란한 영광인가 높이 올린<br/>존귀한 이름 예수 면류관을 쓰셨네<br/>우리 구주 온 성도여 영원히 찬송하세<br/>',NULL,34219,4);
INSERT INTO stanza VALUES('K950','1','생명의 풍성한 공급이 흐르는 포도나무이신 주님<br/>우리는 당신의 풍성함 나타내고 또 열매 맺는 가지<br/>당신은 또 우릴 기르는 아버지 우리의 근원과 빛과 생수<br/>우릴 다 당신께 쏟아 놓습니다 주님만을 사랑해<br/>',NULL,34220,1);
INSERT INTO stanza VALUES('K950','2','우린 주님 안에 주는 우리 안에 달콤한 하나를 누려<br/>그 사랑 안에서 우리는 거하며 당신과 함께 속삭여<br/>주 인격 누릴 때 사랑스럽고도 만족스럽고 또 친밀하네<br/>우리는 더 이상 바랄 것 없다네 주님만을 사랑해<br/>',NULL,34221,2);
INSERT INTO stanza VALUES('K950','3','주 예수 당신은 우릴 사랑했네 죽음 거친 사랑으로<br/>당신은 당신의 생명을 다 주고 우릴 친구 삼았으니<br/>어디서 이보다 큰 사랑 얻으리 우린 아무 말도 할 수 없어<br/>다만 당신만을 사랑해 사랑해 주님만을 사랑해<br/>',NULL,34222,3);
INSERT INTO stanza VALUES('K951','1','우리 흐름 중 생명 흐름 중 나 흐름 중에 있도다<br/>우리 흐름 중 생명 흐름 중 나 흐름 중에 있도다<br/>주 찬양합시다 흐름 중 오 할렐루야 흐름 중<br/>주 찬양해 생명 흐름 중 오 할렐루야 흐름 중<br/>',NULL,34223,1);
INSERT INTO stanza VALUES('K951','2','We are in the flow We are in the flow<br/>O Hallelujah in the flow<br/>We are in the flow We are in the flow<br/>O Hallelujah in the flow<br/>O praise the Lord We are in the flow<br/>O Hallelujah in the flow<br/>O praise the Lord We are in the flow<br/>O Hallelujah in the flow<br/>',NULL,34224,2);
INSERT INTO stanza VALUES('K952','1','옛 사람에서 벗어나려면 생명률 따르라<br/>이 생명의 법 우리 안에서 률법 요구 이뤄<br/>생명률 따르라 생명률 따르라<br/>이 법이 우릴 변화시킨다 생명률 따르라<br/>',NULL,34225,1);
INSERT INTO stanza VALUES('K952','2','주의 생명서 시작하려면 생명률 따르라<br/>생명의 법은 기능과 역사 능력 갖고 있다<br/>생명률 따르라 생명률 따르라<br/>네 모든 노력 그만 버리고 생명률 따르라<br/>',NULL,34226,2);
INSERT INTO stanza VALUES('K952','3','하나님의 뜻 성취하는 법 생명률 따르라<br/>하나님은 네 자기개선을 원치 않으신다<br/>생명률 따르라 생명률 따르라<br/>주 계획 앞에 다만 말하라“저도 원합니다”<br/>',NULL,34227,3);
INSERT INTO stanza VALUES('K952','4','신진대사로 변화시키는 생명률 따르라<br/>우리 각 부분 주 성분으로 충만할 때까지<br/>생명률 따르라 생명률 따르라<br/>항상 옛 사람 부인하고서 주 생명 채우라<br/>',NULL,34228,4);
INSERT INTO stanza VALUES('K952','5','우림 맘 속에 주님 새기는 생명률 따르라<br/>우리 속 사람 각 부분마다 새겨질 때까지<br/>생명률 따르라 생명률 따르라<br/>주 그리스도 네 각 부분에 새겨질 때가지<br/>',NULL,34229,5);
INSERT INTO stanza VALUES('K953','1','묶인 것 푸는- 주의 기름 부음<br/>우리 맘에 새기신 주님의 새 계명<br/>하나님이 사람- 안에<br/>',NULL,34230,1);
INSERT INTO stanza VALUES('K953','chorus','살아 움직이는 기름 부음 이로써 묶는 것 깨뜨려<br/>',NULL,34231,2);
INSERT INTO stanza VALUES('K953','2','묶인 것 푸는- 주의 기름 부음<br/>우리 맘에 새기신 주님의 새 계명<br/>사람 안에 그리-스도<br/>',NULL,34232,3);
INSERT INTO stanza VALUES('K953','3','묶인 것 푸는- 주의 기름 부음<br/>우리 맘에 새기신 주님의 새 계명<br/>사람 안에 주의- 성령<br/>',NULL,34233,4);
INSERT INTO stanza VALUES('K954','1','하나님의 하신 말씀 기이함을 알았네<br/>기름부음 내게 있어 가르침 필요 없네<br/>',NULL,34234,1);
INSERT INTO stanza VALUES('K954','chorus','오 내 영 안에 주 움직이시네 내 안에 기름 부음<br/>하나님 흐르네 아 고마워라 주 말씀하셨네<br/>기름 부음 내 안에 언제든지 누리세<br/>',NULL,34235,2);
INSERT INTO stanza VALUES('K954','2','주를 체험케 하려고 순전한 말씀으로<br/>하나님은 영 안에서 나와 연합되셨네<br/>',NULL,34236,3);
INSERT INTO stanza VALUES('K954','3','정결케 한 피로 인해 주와 난 막힘 없네<br/>그리스도 그의 관유 내 안에서 움직여<br/>',NULL,34237,4);
INSERT INTO stanza VALUES('K954','4','주 안에 계신 하나님 생명의 성령으로<br/>내 영 안에 들어오셔 그의 형상 되게 해<br/>',NULL,34238,5);
INSERT INTO stanza VALUES('K954','5','영 안의 주 만질 때에 깊고 넓고 부요해<br/>충만하게 흐르시는 그의 실재 알았네<br/>',NULL,34239,6);
INSERT INTO stanza VALUES('K954','6','항상 주의 기름 부음 내 온 마음 적시니<br/>그의 가르침을 따라 주님 안에 살겠네<br/>',NULL,34240,7);
INSERT INTO stanza VALUES('K955','1','모든 성도 아는가 모든 성도 아는가 모든 성도 아는가<br/>주 계신 곳 주는 우리 영 안에서 생명 호흡 되시고<br/>나는 주와 연합됐네 놀라운 비밀일세<br/>',NULL,34241,1);
INSERT INTO stanza VALUES('K955','2','모든 성도 아는가 모든 성도 아는가 모든 성도 아는가<br/>생명의 주 주는 생명 주시는 영 모든 풍성 되시니<br/>그의 이름 부름으로 모든 풍성 누리세<br/>',NULL,34242,2);
INSERT INTO stanza VALUES('K956','1','너의 마음 간절히 주님 사모 한다면<br/>세상에서 만날 생각 말아라-<br/>이 세상 어디서 주 예수를 만날까<br/>세상에서 만날 수가 없다네-<br/>',NULL,34243,1);
INSERT INTO stanza VALUES('K956','2','내 마음- 간절히 주님 사모했지만<br/>생각 안에 주님 얼굴 없었네-<br/>생각과 머리로 맴돌고- 애써도<br/>주 예수는 찾을 길이 없었네-<br/>',NULL,34244,2);
INSERT INTO stanza VALUES('K956','3','내 마음은 간절히 주님 뵙기 원하네<br/>지금 내가 주님 앞에 나왔네-<br/>닫혔던 마음 문 이제 활짝 열고서<br/>주님만을 내 마음에 모시리-<br/>',NULL,34245,3);
INSERT INTO stanza VALUES('K956','4','형제여- 자매여 주님 사모한다면<br/>주 여호와 그 이름을 부르세-<br/>주 예수 주 예수 주 예수- 주 예수<br/>주 여호와 그 이름을 부르세-<br/>',NULL,34246,4);
INSERT INTO stanza VALUES('K956','5','주 예수- 주 예수 주 예수- 주 예수<br/>주 여호와 그 이름을 부르세-<br/>주 예수 주 예수 주 예수- 주 예수<br/>주 여호와 그 이름을 부르세-<br/>',NULL,34247,5);
INSERT INTO stanza VALUES('K957','1','나는 목말라 찾아 헤맸네 날 만족게 할 깊은 샘<br/>그러나 그 샘 맛 본 뒤에도 목마름 여전 했었네<br/>어느 날 난 찾았네 목마름 해결할 분<br/>',NULL,34248,1);
INSERT INTO stanza VALUES('K957','chorus','예수 예수 나의 생-수 예수 예수 내 생명<br/>날- 만족게 한 생-수 예수 예수 내 생명<br/>',NULL,34249,2);
INSERT INTO stanza VALUES('K957','2','생수 마신 후 내 마음 속엔 또 한 곳 사모해졌네<br/>모두 모이는 예루살렘을 산 위에서 본 이상을<br/>주는 나를 찾아서 교회에 옮겼네<br/>',NULL,34250,3);
INSERT INTO stanza VALUES('K957','3','공허하였던 방랑 생활은 이제 그 길을 멈췄네<br/>네 마음 열고 주님 부를 때 그는 네 안에 오시리<br/>지금 주를 찾으라 그 이름 불러서<br/>',NULL,34251,4);
INSERT INTO stanza VALUES('K958','1','사람들은 세상에서- 포도주를 얻지만-<br/>주여 당신의 사랑은 이 땅의 포도주 보다<br/>좋고 풍요해- 주님이 그들의 포도주 되기 위해<br/>겪은 모든 것을 그들이 안다면-<br/>당신 사랑할 것이지만 그들은<br/>영원한 포도주인 당신을 몰라- -<br/>',NULL,34252,1);
INSERT INTO stanza VALUES('K958','2','지위와 부귀와 경력- 예술과 또 철학이-<br/>포도주인 양 그들을 속이고 이끌어 허송<br/>세월하게 해- 주님이 그들의 포도주 되기 위해<br/>겪은 모든 것을 그들이 안다면-<br/>당신 사랑할 것이지만 그들은<br/>진정한 포도주인 당신을 몰라- -<br/>',NULL,34253,2);
INSERT INTO stanza VALUES('K958','3','영원한 포도주인 주- 참 포도주이신 주-<br/>생명주는 포도나무의 포도주 날 달콤하고<br/>평안케 해- 주님이 그들의 포도주 되기 위해<br/>겪은 모든 것을 그들이 안 다면-<br/>당신 사랑할 것이지만 그들은<br/>달콤한 포도주인 당신을 몰라- -<br/>',NULL,34254,3);
INSERT INTO stanza VALUES('K959','1','난 한 때 친구 사이에서 이름 높아지길 원했다네<br/>그러나 내가 만난 것은 커다란 좌절과 끝없이 악화된<br/>내 자신 속의 보이지 않는 갈등 뿐이었네<br/>항상 난 생각했네“그 무엇이 살만한 가치를 갖고 있나<br/>의욕에 찬 생활과 장래에 대한 꿈을 주는<br/>그런 것이 어디 있나?”<br/>',NULL,34255,1);
INSERT INTO stanza VALUES('K959','2','어느 날 난 기쁨에 찬 사람들 만났네 그들은 당당했네<br/>예수로 충만했네 그들로 인해 주님 날 찾아와 그의<br/>생명 주셔 나는 완전히 새 피조물 됐네<br/>난 그로 인해 외쳐“할렐루야!”외치잖을 수 없네<br/>“오, 내 주!”내 영안의 영광이 날 하나님의<br/>가족 만들어 기쁨 넘치게 하네<br/>',NULL,34256,2);
INSERT INTO stanza VALUES('K959','3','당신도 옛 사람의 타락에서 해방받기 원한다면<br/>오늘 여기서 발견하라 마음을 활짝 열고 담대히<br/>외치라“예수는 내 완전한 구원 내 생명”이라고<br/>함께 크게 외치세“할렐루야!”그가 너를 채우리<br/>“오, 내 주!”“주님, 당신은 내가 갈망했던 것보다<br/>훨씬 뛰어난 분”이시라고<br/>',NULL,34257,3);
INSERT INTO stanza VALUES('K96','1','하나님의 독생자 죄인 구원 하려고<br/>하늘에서 내려와 슬픔의 아들 되셨네<br/>',NULL,34258,1);
INSERT INTO stanza VALUES('K96','2','날 대신해 주 예수 모욕 비방 당하며<br/>죄인 위치 취했네 내게 생명 능력 줬네<br/>',NULL,34259,2);
INSERT INTO stanza VALUES('K96','3','난 약하고 악하나 그가 구속 이뤘네<br/>거룩하신 어린 양 그가 다 이루셨다네<br/>',NULL,34260,3);
INSERT INTO stanza VALUES('K96','4','그가 높여짐으로 나는 죽음 면했네<br/>그가 모두 이루니 마귀 권세 잃었다네<br/>',NULL,34261,4);
INSERT INTO stanza VALUES('K96','5','그가 보좌 오르사 내게 은사 주셨네<br/>그가 다시 오셔서 이기는 자 올리리라<br/>',NULL,34262,5);
INSERT INTO stanza VALUES('K96','6','그를 다시 만날 때 거듭 찬송하리라<br/>영광 존귀 돌리리 할렐루야 놀라운 주<br/>',NULL,34263,6);
INSERT INTO stanza VALUES('K960','1','난 한 때 큰 회사에 내 생명 바쳐 지위와 보수를 향했었지<br/>난 경력을 뭣보다 중요시 했지 그러다 난 예수 주 만났네<br/>난 세상을 헤매다 참 삶이 되는 예수를 만나 내 집에 왔네<br/>',NULL,34264,1);
INSERT INTO stanza VALUES('K960','2','내 모든 것 투자했던 정치 써클 논쟁과 투쟁과 대의 명분<br/>그 어느 날 토론 중 예수 부를 때 그는 내 안으로 들어 왔네<br/>',NULL,34265,2);
INSERT INTO stanza VALUES('K960','3','난 여가를 생각에 젖어 살았지 철학에 문학에 빠져 봤지<br/>그 어느 날 남 몰래 불러 본 예수 내 체계 부수고 내 주 됐네<br/>',NULL,34266,3);
INSERT INTO stanza VALUES('K960','4','난 배우고 읽고 또 연구하면서 지식을 존재의 의미 삼고<br/>노력했네 그러나 예수 만진 후 지식 대신 생명 얻었다네<br/>',NULL,34267,4);
INSERT INTO stanza VALUES('K960','5','난 성경을 연구하며 노력했지 머리로 하나님 이해하려<br/>결국에는 연구를 떠나 주 불러 주님 접촉하고 살아났네<br/>',NULL,34268,5);
INSERT INTO stanza VALUES('K961','1','정말 좋은 주님-이다 다만 와서 맛 보아라<br/>너에게도 나에게도 좋은 주님 맛 보아라<br/>',NULL,34269,1);
INSERT INTO stanza VALUES('K961','2','다만 불러 주 예-수를 그가 너를 변케 하리<br/>부를 때면 어디서나 항상 은혜 베풀리라<br/>',NULL,34270,2);
INSERT INTO stanza VALUES('K961','3','참 사랑을 느끼-리라 네 마음 속 깊이 깊이<br/>하나님의 한 흐름을 참 사랑을 발견하리<br/>',NULL,34271,3);
INSERT INTO stanza VALUES('K961','4','찬양하세 주의- 생명 우리 안에 있는 생명<br/>그의 성분 우리 속에 넣는 주님 찬양하세<br/>',NULL,34272,4);
INSERT INTO stanza VALUES('K962','1','주님을 찬미해 나의 주 주 주가 내 생명 됐네<br/>할렐루야 찬미해 내 눈 밝아 보게 됐네<br/>내 안에 계신 주 보네<br/>',NULL,34273,1);
INSERT INTO stanza VALUES('K963','1','난 항상 알고 있었네 언제나 내 깊은 속에-<br/>채울 수 없는 목마름 굶주-림 있다는 것을<br/>굶주림 채우기 위해 좋고 나쁜 모든 것들-<br/>애써 가져 보았지만 날 만-족케- 못했네<br/>이제는 생명의 공급- 풍성히 넘쳐 흐르네<br/>주 이름 부를 때마다- 그의- 영으로 채워져<br/>',NULL,34274,1);
INSERT INTO stanza VALUES('K963','2','생명의 술을 마시며 거룩한 생명 누리네-<br/>항상 주의 자비하심 내 마-음 문 두드리네<br/>내 공허함을 채우신 기묘한 이 방법이여-<br/>오 주여 내 각 부분을 완전-히 적셔 주소서<br/>내 속의 당신의 생명- 자라고 넘쳐 흐르길<br/>영으로부터 혼으로- 날 흠-뻑 적시기까지<br/>',NULL,34275,2);
INSERT INTO stanza VALUES('K963','3','난 항상 알고 있었네 언제나 내 깊은 속에-<br/>채울 수 없는 목마름 굶주-림 있다는 것을<br/>그러나 이제는 내 맘 만족되어질 수 있네-<br/>내 안의 그리스도가 매일- 매일 자라므로<br/>오 주여 당신 안에서- 내 편히 안식합니다<br/>날 흠뻑 적시기까지- 흘러- 넘치소서 주여<br/>',NULL,34276,3);
INSERT INTO stanza VALUES('K964','1','우리 마음은 항상 끌려 주께로 오네<br/>주 만유보다 아름답고 더욱 신선해<br/>주의 귀함을 세상 말로 표현 못하리<br/>그 보배로움 매일 매일 더욱 귀하네<br/>',NULL,34277,1);
INSERT INTO stanza VALUES('K964','chorus','놀라운 복의 근원 그 반도 알 수 없네<br/>어제와 오늘 영원토록 더욱 귀하네<br/>',NULL,34278,2);
INSERT INTO stanza VALUES('K964','2','그의 나타난 영광 교회 안에서 보네<br/>형제 자매여 주의 풍성 여기 있으니<br/>다 와서 먹고 마심으로 맘껏 누리세<br/>그 즐거움이 매일 매일 새로워지네<br/>',NULL,34279,3);
INSERT INTO stanza VALUES('K964','3','주의 산 영이 지금 우리 영 안에 있네<br/>기름 부음이 영의 생명 충만케 하네<br/>우리 영 해방 받아 높이 솟아 오르네<br/>우리 주 이전 보다 더욱 사랑스럽네<br/>',NULL,34280,4);
INSERT INTO stanza VALUES('K964','4','주님의 회복 위해 주 나와 연합했네<br/>주 풍성함이 모두 교회에서 나타나<br/>우리의 모든 소유 전체 주께 바칠 때<br/>위대한 주의 계획 더욱 밝아져가네<br/>',NULL,34281,5);
INSERT INTO stanza VALUES('K965','1','참 기쁨 내 맘 속에 넘쳐 참 기쁨 주를 찬송케 해<br/>주의 크신 사랑 노래해 내게 자유 주심 말하리<br/>나의 일생 노래로 채워 찬미하겠네<br/>',NULL,34282,1);
INSERT INTO stanza VALUES('K965','2','나의 주 내 영에서 흘러 나의 주 내 혼 충만케 해<br/>밖에 있는 옛 것 태우고 속 사람은 새로워지네<br/>완전한 성장에 이끄네 나의 주 예수<br/>',NULL,34283,2);
INSERT INTO stanza VALUES('K965','3','찬양해 주의 뜻 나타내 찬양해 불타오르는 영<br/>내 마음에 찬미 넘치어 하나님의 계획 말하리<br/>모든 방랑자들 돌아와 주를 찬양해<br/>',NULL,34284,3);
INSERT INTO stanza VALUES('K965','4','교회는 한 지방에 하나 교-회 분열 비극일세<br/>바벨론은 다 무너지고 교회 중에 주님 높이네<br/>지방 입장 위에 함께 서 교회 건축해<br/>',NULL,34285,4);
INSERT INTO stanza VALUES('K965','5','온 교회 주를 찬양하세 온 교회 기쁨 충만하네<br/>불 켠 도시 성산에 서서 주와 교회를 나타내네<br/>하나님의 완전한 계획 이뤄져가네<br/>',NULL,34286,5);
INSERT INTO stanza VALUES('K966','1','만유의 주 우리 얻었네 내게 모든 것 되니<br/>주의 이름 부를 때에 참 무한한 축복일세<br/>',NULL,34287,1);
INSERT INTO stanza VALUES('K966','chorus','말할 수 없는 이 기쁨 내게 넘쳐<br/>충만하네 충만해<br/>말할 수 없는 이 기쁨 주의 영광<br/>입으로 다 말 못하겠네<br/>',NULL,34288,2);
INSERT INTO stanza VALUES('K966','2','나는 알았네 주는 그 영 내 영 안에 계시네<br/>주님 만지기 참 편리해 얼마나 달콤한지<br/>',NULL,34289,3);
INSERT INTO stanza VALUES('K966','3','내 생활의 비밀 알았네 말씀 읽고 기도해<br/>주의 말씀 먹고 마실 때 부족함 전혀 없네<br/>',NULL,34290,4);
INSERT INTO stanza VALUES('K966','4','몸 된 교회 우리 찾았네 우리 집 여기 있네<br/>영원히 바벨론 떠났네 교회는 내 집일세<br/>',NULL,34291,5);
INSERT INTO stanza VALUES('K966','5','형제 교제 참맛 알았네 지상 최대의 기쁨<br/>우리 영은 항상 활발해 이 생활 가치 있네<br/>',NULL,34292,6);
INSERT INTO stanza VALUES('K967','1','애굽에서 바로의 종 된 자 들으라<br/>양의 피를 바르고 양고기 먹으라<br/>문에 바른 피 보고 천사들 지나간다<br/>이제 네 영 누리리 완전한 자유를<br/>',NULL,34293,1);
INSERT INTO stanza VALUES('K967','2','새 시작을 주는 양 유월절 어린 양<br/>그의 피를 바르고 그 고기 먹으라<br/>속박을 벗으려면 애굽을 떠나려면<br/>양의 피를 바르고 양고기 먹으라<br/>',NULL,34294,2);
INSERT INTO stanza VALUES('K967','3','발에 신을 신고서 지팡이 잡고서<br/>급히 급히 먹으라 양고기 먹으라<br/>허리에 띠를 띠라 믿음의 띠를 띠라<br/>하나님이 너희를 친히 인도하리<br/>',NULL,34295,3);
INSERT INTO stanza VALUES('K968','1','생명 강물 보좌에서 흘러 내리네<br/>강 좌우에 생명 나무 열매 가득해<br/>다시 밤이 없고 해와 등이 없어도-<br/>주는 곧 빛 되시네<br/>',NULL,34296,1);
INSERT INTO stanza VALUES('K968','chorus','성령과 신부가 말씀하시 길<br/>곧 오라 듣는 자 오라 하시네<br/>목마른 자와 또 원하는 자 는-<br/>값없이 생수 마셔<br/>',NULL,34297,2);
INSERT INTO stanza VALUES('K968','2','그침없이 솟아나는 그리스도는<br/>우리의 강 우리의 물 우리의 나무<br/>낮과 빛과 새벽별이 되신 그리스도<br/>우리의 모든 것 돼<br/>',NULL,34298,3);
INSERT INTO stanza VALUES('K968','3','오 주 아멘 부름으로 주를 맛 보네<br/>달콤하고 놀라우신 주를 누리네<br/>그 이름을 부름으로 두루마길 빨아<br/>생명의 나무 얻어<br/>',NULL,34299,4);
INSERT INTO stanza VALUES('K968','4','해보다도 더 빛나는 우리 집에서<br/>형제 자매 연합하여 하나 되었네<br/>주는 우릴 한데 묶고 우린 주 나타내<br/>이 지방 교회로서<br/>',NULL,34300,5);
INSERT INTO stanza VALUES('K969','1','예수 믿는 것은 그에 관해 배우고<br/>선한 일을 하는 거라 말하는 이여<br/>주 예수는 생명의 떡으로 오셨네<br/>우리 그를 매일 매일 먹어야 하네<br/>',NULL,34301,1);
INSERT INTO stanza VALUES('K969','chorus','우리는 사랑해 먹고 마시는 교회 생활<br/>주를 호흡하며 말씀을 먹네<br/>우리는 부르네 오 주 아멘 할렐루야<br/>언제나 주님과 잔치 누리네<br/>',NULL,34302,2);
INSERT INTO stanza VALUES('K969','2','주의 이름 부를 때에 풍성 누리고<br/>주가 우리 속 채울 때 변화된다네<br/>봉사에 집착하던 옛 노력 버리고<br/>매일 매일 교통할 때 생명 자라네<br/>',NULL,34303,3);
INSERT INTO stanza VALUES('K969','3','마지막 때 너의 마음 어지럽다면<br/>악한 흐름 속에 갈팡질팡 한다면<br/>다만 교회 안에 와서 주를 누리라<br/>너는 가장 좋은 길을 발견하리라<br/>',NULL,34304,4);
INSERT INTO stanza VALUES('K97','1','갈보리서 구주 예수 능욕지고 못박혔네<br/>내 죄 위해 피흘리사 새 언약을 세우셨네<br/>',NULL,34305,1);
INSERT INTO stanza VALUES('K97','chorus','오 참담한 저 갈보리 주 예수 피 흘리셨네<br/>오 복되다 저 갈보리 주 날 위해 죽으셨네<br/>',NULL,34306,2);
INSERT INTO stanza VALUES('K97','2','온 천지가 깜깜할 때 다 이뤘다 외치시고<br/>운명할 때 휘장 열어 새롭고도 산 길 열어<br/>',NULL,34307,3);
INSERT INTO stanza VALUES('K97','3','오 주 예수 어찌하여 나 위하여 죽으셨나<br/>십자가를 친히 지고 하나님 벌 받으셨네<br/>',NULL,34308,4);
INSERT INTO stanza VALUES('K970','1','한 번 호흡할 때 주 마셔 아멘<br/>한 번 호흡할 때 나 사네 아멘 아-<br/>그가 나오면 난 마셔 그 생명 내게서 흘러나<br/>나는 알았다네 깊이 주 마셔<br/>',NULL,34309,1);
INSERT INTO stanza VALUES('K970','2','요한복음 3장 8절 밖 공기 바람은<br/>임의로 밖에서 분다 그러나<br/>그는 어디서 오며 어디로 가는지 모르네<br/>영으로 난 사람 모두 이렇다<br/>',NULL,34310,2);
INSERT INTO stanza VALUES('K970','3','또 이십 장 이십 이 절 안 공기<br/>예수께서 친히 생명 숨쉬며 다만<br/>요청하셨네 받으라 생각지 말고서 마시라<br/>오직 생명 체험 숨 쉴 때 있네<br/>',NULL,34311,3);
INSERT INTO stanza VALUES('K970','4','어디든지 지금 공기가 있네<br/>어디서나 우리를 싸고 있네 오-<br/>부요하고도 자유론 그 공기 마시며 살겠네<br/>형제 자매들아 생명 숨쉬세<br/>',NULL,34312,4);
INSERT INTO stanza VALUES('K970','5','항상 주 이름 부르세 오 주여<br/>주는 우리 호흡되네 오 주여 우리<br/>깊게 그 이름 호흡해 오 그로 채워질 때까지<br/>예수 그리스도 호흡에 있네<br/>',NULL,34313,5);
INSERT INTO stanza VALUES('K971','1','주 예수 부를 때면 내 마음 타오르고<br/>내 안에 주 그리스도 그 생명 자라네<br/>주 예수 함께 불러 이 큰 기쁨 누릴 때<br/>주는 내 안에 들어와 생명 풍성케 하리라<br/>',NULL,34314,1);
INSERT INTO stanza VALUES('K971','2','네 마음 주를 멀리 떠나 있다 하여도<br/>함께 주 예수 부르면 자유케 하리라<br/>우리가 어떠한데 처해있다 하여도<br/>다만 그를 부를 때면 그는 네 속에 오시리<br/>',NULL,34315,2);
INSERT INTO stanza VALUES('K971','3','다만 불러“주 예수”주가 귀 기울인다<br/>네 피곤한 머리 주께 기대고 쉬어라<br/>그는 우리의 요새 평강 기쁨과 안식<br/>주의 은혜 맛볼 때에 그의 품 안에 안식해<br/>',NULL,34316,3);
INSERT INTO stanza VALUES('K971','4','제일 좋은 건 오직 주님 자신 뿐이다<br/>주님 자신 네 맘 열고 영접해 들여라<br/>주 내 안에서 자라 신부로 단장되면<br/>주를 맞이할 때 우린 그의 영광을 보리라<br/>',NULL,34317,4);
INSERT INTO stanza VALUES('K972','1','독생자를 보내신 하나님 찬양해<br/>구원의 역사는 다 이뤄 졌네<br/>우리로 그 안에서 살게 하려 오신 주<br/>',NULL,34318,1);
INSERT INTO stanza VALUES('K972','chorus','그 이름 부르고 모든 것 드리-리<br/>',NULL,34319,2);
INSERT INTO stanza VALUES('K972','2','우리 위해 못 박힌 주를 찬양해<br/>모든 사람 대신 죽은 한 사-람<br/>많은 밀알 얻으려 한 알의 밀 썩었네<br/>',NULL,34320,3);
INSERT INTO stanza VALUES('K972','3','부활로 승리하신 주를 찬양해<br/>무덤서 당당하게 일어났네<br/>지금은 부활의 주 내 영 안에 사시네<br/>',NULL,34321,4);
INSERT INTO stanza VALUES('K972','4','깊은 속에서부터 그를 부르라<br/>맘 문열고 부를 때 그는 오셔<br/>이름 부를 때마다 너를 변케 하리라<br/>',NULL,34322,5);
INSERT INTO stanza VALUES('K973','1','하나-님 떠나-서 그 얼마나 오래 나뉘어<br/>있었-던가 하-나님의- 그 아들-의 길<br/>버-리고 각각 제 길 다녔-었지<br/>그-는“다 이-루었다”고 하셨지만<br/>우린 항-상 의심-했지<br/>',NULL,34323,1);
INSERT INTO stanza VALUES('K973','chorus','친구여- 다만 주 이름 부-르라<br/>거기 모-든 해답 있-다네<br/>',NULL,34324,2);
INSERT INTO stanza VALUES('K973','2','얼마-나 더 오-래 이 세상은 주의 자-녀<br/>붙잡-을까 얼-마나 더- 오랫동-안<br/>우리-들은 날 내 것으로 여-길까<br/>우-린 주의- 피로 산- 바 됐는데도<br/>언제 자-신 다 드-릴까<br/>',NULL,34325,3);
INSERT INTO stanza VALUES('K973','3','오랫-동안 우-리 몸과 맘을 죄의 법-이<br/>다스-렸지 생-명의 길-을 보지- 못했던-<br/>우릴 육이 항상 지배했지만<br/>이-제 죄의- 힘 날 더- 묶지 못하네<br/>내 영 안-에 주 사-시니<br/>',NULL,34326,4);
INSERT INTO stanza VALUES('K974','1','생명의 자람은 길 가는 것일세<br/>생명은 우릴 길로- 이끄네<br/>여기 포함된 생명의 단계<br/>아이들과 청년들 또한 아비들<br/>',NULL,34327,1);
INSERT INTO stanza VALUES('K974','2','신선한 아이들 새로운 아이들<br/>그들이 무얼 하든지 다 좋아<br/>아버지는 곧 그들의 필요<br/>아버지를 알면서 그들 자라네<br/>',NULL,34328,2);
INSERT INTO stanza VALUES('K974','3','강건한 청년들 견고한 청년들<br/>입장 위에서 말씀 충만하여<br/>싸울 준비로 빛 속에 거해<br/>안의 말씀으로써 사탄 이기네<br/>',NULL,34329,3);
INSERT INTO stanza VALUES('K974','4','확신을 가지고 안정된 아비들<br/>하나님 생명 충만-한 자들<br/>주의 뜻 안에 흔들리잖고<br/>아이들과 청년들 자라게 돕네<br/>',NULL,34330,4);
INSERT INTO stanza VALUES('K974','5','아이들 청년들 그리고 아비들<br/>생명의 단계 교회에서 보네<br/>주님 안에서 하나로 자라<br/>장성한 그 분량의 충만에까지<br/>',NULL,34331,5);
INSERT INTO stanza VALUES('K975','1','생명의 씨를 내 안에 주께서 뿌려서<br/>생명의 씨가 내 안에 갈수록 자라네 자라네 자라네 자라네<br/>',NULL,34332,1);
INSERT INTO stanza VALUES('K975','2','내 혼의 생명이 그를 억제치 못하네<br/>내 혼의 생명이 그를 억제치 못하네 못하네 못하네 못하네<br/>',NULL,34333,2);
INSERT INTO stanza VALUES('K975','3','기도로 그가 내 안에 풍성히 적시네<br/>기도로 그가 내 안에 풍성히 적시네 적시네 적시네 적시네<br/>',NULL,34334,3);
INSERT INTO stanza VALUES('K975','4','날마다 우리 주 예수 그 이름 부르세<br/>날마다 우리 주 예수 그 이름 부르세 부르세 부르세 부르세<br/>',NULL,34335,4);
INSERT INTO stanza VALUES('K975','5','성도가 모두 다 함께 주 안에 교통해<br/>성도가 다 함께 주 안에 교통해 교통해 교통해 교통해<br/>',NULL,34336,5);
INSERT INTO stanza VALUES('K975','6','하나님 위해서 나는 일어나 간증해<br/>하나님 위해서 나는 일어나 간증해 간증해 간증해 간증해<br/>',NULL,34337,6);
INSERT INTO stanza VALUES('K975','7','주님에 대해 말할 때 우리는 아멘해<br/>주님에 대해 말할 때 우리는 아멘해 아멘해 아멘해 아멘해<br/>',NULL,34338,7);
INSERT INTO stanza VALUES('K975','8','성도들 모두 다 함께 연합해 자라네<br/>성도들 모두 다 함께 연합해 자라네 자라네 자라네 자라네<br/>',NULL,34339,8);
INSERT INTO stanza VALUES('K975','9','주님의 분량 차도록 자라고 자란다<br/>주님의 분량 차도록 자라고 자란다 자란다 자란다 자란다<br/>',NULL,34340,9);
INSERT INTO stanza VALUES('K975','10','주님의 나라 완전히 이뤄질 때까지<br/>주님의 나라 완전히 이뤄질 때까지 때까지 때까지 때까지<br/>',NULL,34341,10);
INSERT INTO stanza VALUES('K976','1','주는 부요한 아름다운 땅<br/>나 지금 맛보니 젖과 꿀 같도다<br/>금과 은 없어도 맛볼 수 있네<br/>다 와서 함께 누리세-<br/>',NULL,34342,1);
INSERT INTO stanza VALUES('K976','2','살아 계시네 할렐루야<br/>주 내 안에 사시네 할렐루야 말해<br/>내 영원한 기업 넘쳐 흐르네<br/>다 와서 그를 맛보세-<br/>',NULL,34343,2);
INSERT INTO stanza VALUES('K976','3','함께 모이니 기쁨 넘치네<br/>영 안에 들어와 지체 되었네<br/>주의 몸 이루어 주를 나타내<br/>주님은 우리 실젤세-<br/>',NULL,34344,3);
INSERT INTO stanza VALUES('K976','4','함께 모여서 풍성함 누려<br/>지방 교회 중에 주를 높이세<br/>한 간증으로써 허락 받았네<br/>주 쓰임 받을 수 있네-<br/>',NULL,34345,4);
INSERT INTO stanza VALUES('K976','5','교회로부터 온 땅 끝까지<br/>주님의 온전한 뜻 이뤄가네<br/>이 뜻을 위하여 모든 것 바쳐<br/>영원한 경륜 이루세-<br/>',NULL,34346,5);
INSERT INTO stanza VALUES('K977','1','좋은 땅에 살며 주를 종일 누리네<br/>주 풍성과 충만과 능력을 누리네<br/>시시때때로 주 누리며 사네<br/>좋은 땅 안에서 주는 우리 모든 것<br/>',NULL,34347,1);
INSERT INTO stanza VALUES('K978','1','오 들어 보라 지난 날 방랑하던 자가<br/>부르는 찬송 소리를 그 지나온 길을<br/>',NULL,34348,1);
INSERT INTO stanza VALUES('K978','chorus','찬양해 주님을 찬양해<br/>할렐루야 할렐루야 찬양해<br/>주 안에 난 변화 되었네<br/>',NULL,34349,2);
INSERT INTO stanza VALUES('K978','2','내 항상 찾던 즐거움 세상엔 없었네<br/>내 몸과 맘엔 피로와 공허만 있었네<br/>',NULL,34350,3);
INSERT INTO stanza VALUES('K978','3','밤낮으로 노력하며 쌓은 내 모래성<br/>주는 허물어 뜨렸네 깊은 뜻 안에서<br/>',NULL,34351,4);
INSERT INTO stanza VALUES('K978','4','그 수치와 절망을 난 견딜 수 없었네<br/>그러나 이제 그 아픔 사라져 버렸네<br/>',NULL,34352,5);
INSERT INTO stanza VALUES('K978','5','난 이제 지방 교회의 행복한 지첼세<br/>방랑 자는 집 찾았네 방랑은 끝났네<br/>',NULL,34353,6);
INSERT INTO stanza VALUES('K978','6','나만의 성 안에 살던 개인주의자를<br/>주님은 다른 지체와 함께 건축하셔<br/>',NULL,34354,7);
INSERT INTO stanza VALUES('K978','7','주의 몸 안의 생활은 너무도 달콤해<br/>만날 때마다 우리는 서로 공급받네<br/>',NULL,34355,8);
INSERT INTO stanza VALUES('K978','8','방랑은 아주 끝났네 이 행복의 길은<br/>교회 안에서 안식을 누리는 것일세<br/>',NULL,34356,9);
INSERT INTO stanza VALUES('K979','1','내 주께 나를 다 드리네<br/>세상은 악한 자 안에 처했지만-<br/>나는야 아버지의 아들<br/>그의 큰 사랑이 내 필요 채우네-<br/>',NULL,34357,1);
INSERT INTO stanza VALUES('K979','chorus','주께 나를 온전히 드리네<br/>주의 생명만을 누리며<br/>예수 예수 예수<br/>예수 만을 사랑-하네 진정으로-<br/>',NULL,34358,2);
INSERT INTO stanza VALUES('K979','2','주님만 내 안에 흐르길<br/>주 외의 무엇도 채우지 않으리-<br/>내 맘은 목말라 굶주려<br/>생명의 달콤한 흐름을 채우려-<br/>',NULL,34359,3);
INSERT INTO stanza VALUES('K979','3','생명의 빛이신 주님은<br/>모든 거짓된 것 뚫고 비추시네-<br/>주님만 내 안에 빛나길<br/>주가 날 비출 때 난 주의 것 되네-<br/>',NULL,34360,4);
INSERT INTO stanza VALUES('K979','4','주님의 생명만 필요해<br/>그 생명 날 더욱 깨끗게 하시니-<br/>내 모든 더러움 씻고서<br/>주님만 내 안에 더욱더 흐르길-<br/>',NULL,34361,5);
INSERT INTO stanza VALUES('K979','5','주 앞에 어둠과 사망은<br/>모두 물러가고 평강 기쁨 넘쳐-<br/>생명의 교통이 안겨 준<br/>놀라운 이 기쁨 그 무엇과 바꾸리-<br/>',NULL,34362,6);
INSERT INTO stanza VALUES('K98','1','시간의 제한 잊 - 고 - 서 주님께 찬양 - 드 - 리 - 세<br/>우리가 잠잠하 - 다 - 면 돌들이 찬송하겠네<br/>',NULL,34363,1);
INSERT INTO stanza VALUES('K98','2','자신의 피로 우 - 릴 - 산 주님을 높이 - 찬 - 양 - 해<br/>주 우리 위해 죽 - 으 - 사 마음과 힘 다 쏟았네<br/>',NULL,34364,2);
INSERT INTO stanza VALUES('K98','3','은혜를 받은 죄 - 인 - 만 이 찬송 알고 - 있 - 으 - 니<br/>그들 외에는 모 - 르 - 네 그들만 그 뜻 안다네<br/>',NULL,34365,3);
INSERT INTO stanza VALUES('K98','4','보혈로 인한 긍 - 휼 - 을 천사들 시인 - 하 - 지 - 만<br/>그들과 달리 우 - 리 - 는 보혈의 효능 증명해<br/>',NULL,34366,4);
INSERT INTO stanza VALUES('K98','5','천사들은 하나 - 님 - 을 존경하고 숭 - 배 - 하 - 나<br/>우린 즐거이 찬 - 송 - 해 인성을 가진 그분을<br/>',NULL,34367,5);
INSERT INTO stanza VALUES('K98','6','우린 찬양해 주 - 사 - 랑 피 흘려 죽은 - 참 - 사 - 랑<br/>그날에 당신 만 - 날 - 때 또 찬송 경배하겠네<br/>',NULL,34368,6);
INSERT INTO stanza VALUES('K980','1','우리는 성-령 안에서 걷겠네<br/>우리는 성-령 안에서 걷겠네<br/>우리는 성-령 안에서 걷겠네<br/>영 안의 주 할렐루야<br/>',NULL,34369,1);
INSERT INTO stanza VALUES('K980','2','영 안에 살면서 주 이름 부르세<br/>영 안에 살면서 주 이름 부르세<br/>영 안에 살면서 주 이름 부르세<br/>구원의 주 할렐루야<br/>',NULL,34370,2);
INSERT INTO stanza VALUES('K980','3','영 안에 살려면 한 몸이 필요해<br/>영 안에 살려면 한 몸이 필요해<br/>영 안에 살려면 한 몸이 필요해<br/>몸 안의 주 할렐루야<br/>',NULL,34371,3);
INSERT INTO stanza VALUES('K980','4','다 함께 지어져 가는 것 기쁘다<br/>다 함께 지어져 가는 것 기쁘다<br/>다 함께 지어져 가는 것 기쁘다<br/>영광스런 지방 교회<br/>',NULL,34372,4);
INSERT INTO stanza VALUES('K980','5','지방 교회 생활 하나님 회복해<br/>지방 교회 생활 하나님 회복해<br/>지방 교회 생활 하나님 회복해<br/>주 안에서 할렐루야<br/>',NULL,34373,5);
INSERT INTO stanza VALUES('K981','1','우린 강을 건넌 자 이름 히브리인<br/>유브라데 강 건너 우상 끝났네<br/>강 저편을 떠나 가나안 들어가 영원히<br/>거할 성을 찾는다 우리의 이름 참된<br/>히브리인 큰 강을 건너 변화 되었네<br/>하나님 거할 처소 건축해<br/>이 땅에 그의 처소 건축해<br/>',NULL,34374,1);
INSERT INTO stanza VALUES('K981','2','애굽에서 바로의 종노릇할 때<br/>히브리인의 하나님 말씀 하시길<br/>우린 홍해 건너 이 편에 왔네<br/>바로의 군대 파도에 묻고<br/>히브리인의 하나님 오늘 또 다시<br/>말씀 하시며 우릴 인도해 오늘 패역한<br/>이 세대에서 그의 백성을 구원하시네<br/>',NULL,34375,2);
INSERT INTO stanza VALUES('K981','3','해방된 우린 이제 주의 건축해<br/>우리의 본업은 장막 짓는 일<br/>낡은 사십 년은 요단에 묻고 가나안 정복<br/>위해 싸우네 우리 대장의 전쟁 나팔로<br/>한 성 또 한 성 점점 정복해<br/>그의 왕국을 얻기 위하여<br/>오늘 그의 안식에 들어가<br/>',NULL,34376,3);
INSERT INTO stanza VALUES('K981','4','하나님이 주신 것 형식 됐을 때<br/>침례 요한 하나님 말씀 전했네<br/>유대교는 끝났다 강을 건너라 아들의 말씀에<br/>귀 기울이라 선지자에서 아들에게로<br/>아들은 하나님과 하나니<br/>그의 말씀 널 큰 구원하리<br/>그의 말씀 널 큰 구원하리<br/>',NULL,34377,4);
INSERT INTO stanza VALUES('K981','5','유리 바다 위에 우린 이긴 자들<br/>마지막 이 강을 건너간다네<br/>모세의 노래로 주를 찬양해 우리의 적들<br/>발 밑에 있다 우리의 이름 이기는 자들<br/>하나님은 성 소유하시고<br/>사탄은 부끄러움 당하네<br/>우리 기업은 하나님 자신<br/>',NULL,34378,5);
INSERT INTO stanza VALUES('K982','1','주의 떡-을 함께 먹으며<br/>우릴 하나 만든 주님을 찬양해- 우리는<br/>주님의 하나 된 교회 안에 있네<br/>',NULL,34379,1);
INSERT INTO stanza VALUES('K982','chorus','떡을 먹고 잔을 마시세- 우린 영원히 하날세<br/>지방 입장 위에 하나로 서서 주를 먹고 마셔-<br/>',NULL,34380,2);
INSERT INTO stanza VALUES('K982','2','모두 잔-을 마셔 우리는<br/>주의 피로 사 온 교횔세 그의 목-적 위해<br/>우리는 구속되어 하나 이뤘네<br/>',NULL,34381,3);
INSERT INTO stanza VALUES('K982','3','각각 떨-어졌던 밀알들 이제<br/>한 떡으로 뭉쳐져 각지 지-방 입장<br/>위에서 주의 한 몸 간증 한다네<br/>',NULL,34382,4);
INSERT INTO stanza VALUES('K982','4','우린 주-의 백성 온 땅에<br/>주의 참 하나를 선포해 주의 한- 생명을<br/>받고서 하나님의 역사 간증해<br/>',NULL,34383,5);
INSERT INTO stanza VALUES('K983','1','사랑하는 주 예수님 그가 날 이끄시네<br/>그의 사랑 나를 권해 주만 사랑케 하네<br/>',NULL,34384,1);
INSERT INTO stanza VALUES('K983','chorus','사랑하고 사랑하는 주는 나의 기쁨 돼<br/>우리 또한 그의 눈에 심히 아름다운 자<br/>',NULL,34385,2);
INSERT INTO stanza VALUES('K983','2','바로 병거 끄는 준마 팔팔하고 강하듯<br/>나는 옛 사람의 혈기 강한 그런 자였네<br/>',NULL,34386,3);
INSERT INTO stanza VALUES('K983','3','오직 주님만을 비둘기 눈처럼 볼 때에<br/>낡은 관념 변화되고 주의 생명 자랐네<br/>',NULL,34387,4);
INSERT INTO stanza VALUES('K983','4','이제 나는 가시밭에 피어난 백합화라<br/>강한 자아 꺾여졌네 오직 주님만 믿네<br/>',NULL,34388,5);
INSERT INTO stanza VALUES('K983','5','주여 우린 비밀한데 숨겨진 비둘기니<br/>그곳에서 우리 음성 듣고 얼굴 보소서<br/>',NULL,34389,6);
INSERT INTO stanza VALUES('K983','6','주의 죽음 부활 안에 우리 의지 꺾여져<br/>우린 광야에서 나온 연기 기둥 된다네<br/>',NULL,34390,7);
INSERT INTO stanza VALUES('K983','7','우리 안에 계신 주님 우리 인격 될 때에<br/>우린 주가 바라시던 그의 안식처 되네<br/>',NULL,34391,8);
INSERT INTO stanza VALUES('K984','1','소망 없었던 나의 한계 믿어 보려고 애썼지만<br/>믿을 수 없어 부르짖을 때<br/>주님 나타나 우리는 온전히 충만됐네<br/>',NULL,34392,1);
INSERT INTO stanza VALUES('K984','chorus','주의 피 인해 화목됐네<br/>주 예수 우리를 구속했네<br/>의롭다 하니 정죄함 없네<br/>하나님-을 향하여 화평을 누-리네<br/>',NULL,34393,2);
INSERT INTO stanza VALUES('K984','2','아담 안에서 죽은 우리 아무도 고칠 수 없었네<br/>하나님 아들 옛사람 끝내<br/>이제 우리는 해방돼 우리는 해방됐네<br/>',NULL,34394,3);
INSERT INTO stanza VALUES('K984','3','이제 우리는 즐거워 해 은혜에 서서 할렐루야<br/>우리 맘 속에 하나님 흘러<br/>그의 살으심 인하여 우리는 구원됐네<br/>',NULL,34395,4);
INSERT INTO stanza VALUES('K985','1','난 바벨론의 광야 헤매었지만<br/>날 만족게 하는 것 없었네<br/>나 그 어느 날 지방 교회 와 보니<br/>생명의 샘물 넘쳐 흘렀네<br/>',NULL,34396,1);
INSERT INTO stanza VALUES('K985','chorus','매일 매일 생명 샘물 마셔<br/>나는 행복해 내 마음 만족해<br/>매일 매일 생명 샘물 마셔<br/>오 놀랍고도 풍성한 공급<br/>',NULL,34397,2);
INSERT INTO stanza VALUES('K985','2','오, 하나님의 언덕에서 흐르는<br/>이 달콤한 샘물 내게 흘러<br/>오, 갈망했던 곳 나 이제 찾았네<br/>생명과 공급 넘치는 교회<br/>',NULL,34398,3);
INSERT INTO stanza VALUES('K985','3','오, 돌아오라 모든 목마른 자여<br/>이 깊고도 풍성한 샘으로<br/>저 목자 이제 너를 이끌어 온다<br/>목마름 없는 지방 교회로<br/>',NULL,34399,4);
INSERT INTO stanza VALUES('K986','1','은혜 보좌 앞에 함께 갑니다<br/>주님 보좌 앞에 하나되어 담대하-게<br/>은혜 보좌 앞에 함께 갑니다<br/>',NULL,34400,1);
INSERT INTO stanza VALUES('K987','1','너는 네-가 무엇 위해 지어졌는지 아느냐<br/>네 인생-의 참 목적이 무엇인-지 아느냐<br/>하나님이 네 생명되기- 원하시는 것-<br/>너는 아느냐 넌 깊은 데 하나님 담는-<br/>바로 그런 그릇이다<br/>',NULL,34401,1);
INSERT INTO stanza VALUES('K987','2','네 맘보-다 더 깊은 데 있는 것-은 너의 영<br/>오직 예-수만이 이 영 채울 수-가 있-네<br/>너는 항상 공허한 날들- 피로한 날들-<br/>지내 왔었지 그 무엇도 네 깊은 속을-<br/>채울 수는 없었지<br/>',NULL,34402,2);
INSERT INTO stanza VALUES('K987','3','네가 어-떻게 보든지 하나님 눈엔 다 죄인<br/>주 네 안-에 들어 오려 그 피로 너를 씻었네<br/>모든 것 다 이루신 주는- 이젠 네 안에-<br/>올 수 있는 영 네 과거야 어떠하든지-<br/>주는 들어오신다<br/>',NULL,34403,3);
INSERT INTO stanza VALUES('K987','4','하나님-은 네가 그의 그릇 되-기 원한다<br/>네 할 일-은 오직 그를 받아들이는 것- 뿐<br/>네 깊은 속 활짝 열고서- 주를 받으라-<br/>주로 채우라 네 깊은 속 활짝 열고서-<br/>주의 이름 부르라<br/>',NULL,34404,4);
INSERT INTO stanza VALUES('K988','1','너는 구-원의 목적이 무엇인-지 아느냐<br/>주가 너-의 생명 되신 목적과- 뜻 아느냐<br/>지금까지 우리가 안 건- 주가 우리 안-에<br/>거하시는 것 사실 그것 옳긴 하지만-<br/>주의 뜻은 더 깊다<br/>',NULL,34405,1);
INSERT INTO stanza VALUES('K988','2','생명 주-며 흘러가는 에덴의- 강들같이<br/>하나님-의 구원 또한 점점 흘-러 간-다<br/>우린 사탄의 권세에서- 또 기독교에-서<br/>구출됐지만 하나님은 회복 안에서-<br/>계속 흐르고 있다<br/>',NULL,34406,2);
INSERT INTO stanza VALUES('K988','3','저마다- 고립 되어서 방랑하는 게 아니다<br/>우린 함-께 건축되어 주를 나타내야 한-다<br/>주를 담기 위해 우리는- 구원받았다-<br/>그러나 또 하나 주 목적은 순결한 신부-<br/>얻는 데에 있다네<br/>',NULL,34407,3);
INSERT INTO stanza VALUES('K988','4','귀하고- 신령하여도 떨어진 돌은 헛되네<br/>영 안에- 실재적으로 함께 건축되어야 해<br/>주가 신부 얻을 때까진- 완전한 만족-<br/>누리지 못해 그의 건축 이루기 위해-<br/>주는 우릴 찾는다<br/>',NULL,34408,4);
INSERT INTO stanza VALUES('K989','1','오 나는 우주의 중심되는 사-람<br/>그래 난 우주의 중심되는 사-람<br/>하나님은- 목적 있어<br/>나를 이 우주의 중심으로 창-조해<br/>',NULL,34409,1);
INSERT INTO stanza VALUES('K989','2','그리스도 그는 내 인생의 중-심<br/>그리스도 그는 내 인생의 의-미<br/>내 안에서- 모든 것된<br/>그는 내 인생의 중심이요 의-밀세<br/>',NULL,34410,2);
INSERT INTO stanza VALUES('K989','3','교회는 곧 오늘 이 땅 위에 주의 몸<br/>교회는 곧 오늘 이 땅 위에 주의 몸<br/>이 단체의- 사람만이<br/>하나님의 계획 이뤄 이 땅 다-스려<br/>',NULL,34411,3);
INSERT INTO stanza VALUES('K989','4','지방 교회 새롭고도 참된 교회 생활<br/>지방 교회 새롭고도 참된 교회 생활<br/>우린 오늘- 생활한다<br/>주를 먹고 마셔 지방 교회 건-축해<br/>',NULL,34412,4);
INSERT INTO stanza VALUES('K989','5','무얼할까 가서 이 세계를 전하자<br/>무얼할까 가서 이 세계를 전하자<br/>우린 모두- 그의 제자<br/>가서 이 소식을 땅 끝까지 전-하자<br/>',NULL,34413,5);
INSERT INTO stanza VALUES('K99','1','무덤에 누우신 예수 내 구주<br/>조용히 새벽빛 기다렸네<br/>',NULL,34414,1);
INSERT INTO stanza VALUES('K99','chorus','무덤서 일어나서 원수 이겨 개가 부르네<br/>흑암 영역에서 일어난 주님 그의 성도들과<br/>연합되셨네 주 다시 사셨네 할렐루야 사셨네<br/>',NULL,34415,2);
INSERT INTO stanza VALUES('K99','2','병정은 헛되이 예수 지켰네<br/>바위도 헛되이 봉하였네<br/>',NULL,34416,3);
INSERT INTO stanza VALUES('K99','3','사망은 주님을 가두지 못해<br/>주 이미 장애물 제하셨네<br/>',NULL,34417,4);
INSERT INTO stanza VALUES('K990','1','주 예수는 인간을 구원하신 참 놀라운 구주시라<br/>내 영혼을 안전한 바위 틈에 늘 숨기어 주시나니<br/>',NULL,34418,1);
INSERT INTO stanza VALUES('K990','chorus','참 안전한 땅 복된 그늘 속에 내 영혼을 숨기시고<br/>그 깊고 깊은 주의 사랑 안에 내 생명을 감싸시며<br/>그 손으로 덮으신다<br/>',NULL,34419,2);
INSERT INTO stanza VALUES('K990','2','주 예수는 인간을 부르시어 그 죄짐을 벗기신다<br/>내 영혼을 가볍게 하시오니 참 안식이 내 것이라<br/>',NULL,34420,3);
INSERT INTO stanza VALUES('K990','3','주 예수는 인간을 사랑하사 참 평안을 내리신다<br/>내 영혼이 주님의 품 안에서 참 행복을 느끼나니<br/>',NULL,34421,4);
INSERT INTO stanza VALUES('K990','4','주 예수는 인간을 축복하사 큰 위로를 내리신다<br/>내 영혼이 은혜에 감격하여 늘 찬송을 부르나니<br/>',NULL,34422,5);
INSERT INTO stanza VALUES('K991','1','아침에 일찍 주를 대하고 우리 다 함께 교회 생활해<br/>새벽을 드리고 아멘 많이 하면 우리 영은 열리네-<br/>할렐루야 주 함께 할렐루야 계시네<br/>기쁜 노래 부르며 교회 생활해<br/>',NULL,34423,1);
INSERT INTO stanza VALUES('K991','2','옛것은 일체 말하지 않고 그리스도만 함께 간증해<br/>몸의 지체로서 서로 공급하며 남을 붙들어 주네-<br/>할렐루야 지체 돼 할렐루야 지체 돼<br/>기능을 발휘하며 교회 생활해<br/>',NULL,34424,2);
INSERT INTO stanza VALUES('K991','3','주는 나의 것 또한 당신 것 모두 다 와서 그를 누리세<br/>교회 안 집안서 그분을 누리니 기쁨 충만 하도다-<br/>할렐루야 이 기쁨 할렐루야 넘치네<br/>몸의 풍성 누리며 교회 생활해<br/>',NULL,34425,3);
INSERT INTO stanza VALUES('K991','4','할렐루야를 크게 외치며 예수를 주라 시인 한다네<br/>당신은 찬송해 나는 간증하며 함께 아멘 한다네-<br/>할렐루야 다 함께 할렐루야 외치세<br/>신선하고 풍성한 함께 교회 생활해<br/>',NULL,34426,4);
INSERT INTO stanza VALUES('K992','1','보라 만민이 돌아와 주를 높이 찬양해<br/>주의 집으로 돌아와 바벨론을 떠나서<br/>',NULL,34427,1);
INSERT INTO stanza VALUES('K992','chorus','아- 지방 교회 주 크신 축복 큰 영광 여기 있네<br/>나는 사랑하네 이 지방 교회 내 생명 다 바치리<br/>',NULL,34428,2);
INSERT INTO stanza VALUES('K992','2','보라 귀한 기름 흘러 온 몸을 다 적시네<br/>형제 함께 동거함이 어찌 아름다운지<br/>',NULL,34429,3);
INSERT INTO stanza VALUES('K992','3','보라 영광 주 나타나 일곱 등대 사이에<br/>등대 찬란히 비춰서 영광 주께 돌리네<br/>',NULL,34430,4);
INSERT INTO stanza VALUES('K993','1','불로 불로 밤낮 태워 항상 영 안에 기도해<br/>너를 위한 영원 계획 성령 안에<br/>지방 입장 위에 서서 교회 하나로 나타내<br/>지체는 많으나 몸은 하나일세 주님은 머릴세<br/>',NULL,34431,1);
INSERT INTO stanza VALUES('K993','chorus','그리스도와 교회 이것이 참 우리 실재의 생활<br/>할렐루야 할렐루야 우리 생명 주께 바쳐<br/>주님의 교회 건축 위해 하나로 나가세<br/>',NULL,34432,2);
INSERT INTO stanza VALUES('K993','2','항상 주를 먹고 마셔 우리 영을 새롭게 해<br/>참 놀라운 변화 새롭게 바꿨네<br/>나의 옛 사람을 벗고 새 사람을 입고 있네<br/>우리 주를 마실 때에 생명되네 주는 생명일세<br/>',NULL,34433,3);
INSERT INTO stanza VALUES('K994','1','종교와 형식 떠나서 우린 주만 구하네<br/>분파와 교리 떠나서 주님만 구하네<br/>그리스도와 교회 곧 한 새 사람만 본다네<br/>올바른 입장 위에서 실재를 누리네<br/>그리스도를 찾으려고 밤낮 헤매었지만<br/>이제야 주를 찾았다 네 지방 교회 안에서-<br/>',NULL,34434,1);
INSERT INTO stanza VALUES('K994','2','그들은 세상 떠나서 천당 가기 원하나<br/>우리는 오늘 누리네 실재를 맛보네<br/>교회가 입장 위에서 모여- 건축할 때에<br/>주 지금 여기 나타나 밝게 또 분명히<br/>우리는 이제 알았다네 하나님의 계획은<br/>그리스도와 교회 바로 한 새 사람인 것을-<br/>',NULL,34435,2);
INSERT INTO stanza VALUES('K995','1','세상은 평화 원하지만- 전쟁의 소문 더 늘어간다-<br/>이 모든 인간 고통 두려움들- 그 지겨움 끝없네<br/>그러나 주 여기 계시니<br/>',NULL,34436,1);
INSERT INTO stanza VALUES('K995','chorus','우리가 아들 믿을 때에 그의 영으로 하-나 돼<br/>우리가 아들 믿을 때에 그의 영으로 하-나 돼<br/>',NULL,34437,2);
INSERT INTO stanza VALUES('K995','2','우리 주 사랑 안에 사네- 주 우릴 하나로 회복했네-<br/>한 집에 사는 우리 형제 자매- 아버지와 아들이<br/>하나이듯 우린 하날세<br/>',NULL,34438,3);
INSERT INTO stanza VALUES('K995','3','형제들 하나 안에 살 때- 얼마나 좋고도 즐거운가-<br/>달콤한 기름 부음 이슬처럼- 우리 위에 내리네<br/>생명 호흡 항상 새롭다<br/>',NULL,34439,4);
INSERT INTO stanza VALUES('K996','1','오 우린 보네 교회 안의 완전한 하나<br/>노래하고 또 증거해 그리스도의 실재<br/>지방 교회는 곧 주님의 회복의 역사<br/>교회 안에서 부요한 주 보고 맛보네<br/>',NULL,34440,1);
INSERT INTO stanza VALUES('K996','chorus','그는 참 사랑 매일 매일 누려<br/>매일 매일 누려 참된 사랑-<br/>',NULL,34441,2);
INSERT INTO stanza VALUES('K996','2','좋은 양식 늘 넘쳐 나는 교회 안에서<br/>우리의 왕 그리스도를 먹고 마시네<br/>말씀 먹고 주 부르며 성령을 따라서<br/>성도들과 함께 모여서 주를 누리네<br/>',NULL,34442,3);
INSERT INTO stanza VALUES('K996','3','하나님께로부터 흐른 사랑의 흐름<br/>예수 거쳐 우리에게로 흘러 왔으니<br/>성도들과 함께 누리는 사랑의 흐름<br/>달콤하고도 영광스런 사랑의 흐름<br/>',NULL,34443,4);
INSERT INTO stanza VALUES('K996','4','우릴 하나로 만드는- 거룩한 교통<br/>흐름 안에서 성도들이 함께 자라네<br/>그 아들에게 이르도록 자라게 하네<br/>그리스도의 형상으로 화할 때까지<br/>',NULL,34444,5);
INSERT INTO stanza VALUES('K997','1','형제들아 아는가 주의 원함을<br/>그는 휴식할 처소 원한다네<br/>우리가 하나 될 때 그의 처소 지어져<br/>그가 안식하고 우리도 안식-해<br/>',NULL,34445,1);
INSERT INTO stanza VALUES('K997','2','어찌 이 집 나뉘어 설 수 있으랴<br/>어찌 나뉜 집에서 살 수 있나<br/>하나를 막는 것은 모두 떨쳐 버리고<br/>하나를 지키자 하나를 지키-자<br/>',NULL,34446,2);
INSERT INTO stanza VALUES('K997','3','하나 될 때 우리는 한 집안에서<br/>한 가정과 한 가족 누린다네<br/>여기에서 우리는 참된 형제 자매라<br/>이것이 하나님 그의 가정 생-활<br/>',NULL,34447,3);
INSERT INTO stanza VALUES('K997','4','이 집에서 맛보네 모든 충만을<br/>성도들의 풍성함 함께 나눠<br/>주의 집의 보물을 함께 얻고 누리니<br/>하나님의 집은 참 부요하도-다<br/>',NULL,34448,4);
INSERT INTO stanza VALUES('K997','5','지금 주는 부르네 모든 성도를<br/>그의 하나된 처소 이루려고<br/>우리 의견과 견해 모두 벗어 버리고<br/>그가 안식하는 집을 건축하-자<br/>',NULL,34449,5);
INSERT INTO stanza VALUES('K997','6','어려움 있더라도 모두 떨치고<br/>다만 와서 하나를 간증하자<br/>정말 주님의 뜻을 이루기 원한다면<br/>지금 주 앞에서 간증해 보이-자<br/>',NULL,34450,6);
INSERT INTO stanza VALUES('K998','1','오 우리는 영광스런 주의 몸의 지첼세<br/>주가 우릴 하나로 만들었네<br/>우린 모두 우주 안의 한 몸 안에 속했네<br/>할렐루야 우린 모두 하날세<br/>할렐루-야 몸 된 교회 우린 그- 몸의 지체들<br/>우리 전-체 몸을 위해 할렐루야 우린 모두 하날세<br/>',NULL,34451,1);
INSERT INTO stanza VALUES('K998','2','하나님은 지금 그의 완전한 표현 원해<br/>건축된 단체의 사람 필요해<br/>단독으로 떨어진 자 모두 몸에 돌아와<br/>할렐루야 함께 주 나타내자<br/>할렐루-야 몸 된 교회 이 몸 앞-에 사탄 떠네<br/>몸 안에-서 승리하네 할렐루야 우린 몸 안에 있네<br/>',NULL,34452,2);
INSERT INTO stanza VALUES('K998','3','일곱 금등대는 모두 거룩한 주의 성분<br/>몸 안에서 육은 용납 안되네<br/>하나님의 성분만이 충만하고 넘칠 때<br/>할렐루야 등대 밝게 빛나네<br/>할렐루-야 몸 된 교회 주의 일-곱 금등대들<br/>이 등대-는 빛나는 몸 할렐루야 지금 밝게 빛나네<br/>',NULL,34453,3);
INSERT INTO stanza VALUES('K998','4','하나되어 주님만을 나타내는 길은 곧<br/>주 예수를 먹고 마시는 길 뿐<br/>그는 생명의 나무요 만나요 또 잔치라<br/>할렐루야 우린 매일 주 먹네<br/>예수 먹-어 하나 됐네 예수 먹-어 거룩하네<br/>예수 먹-어 빛 발하네 할렐루야 먹는 길 밖에 없네<br/>',NULL,34454,4);
INSERT INTO stanza VALUES('K999','1','바벨론 안에 포로였을 때 주는 우리 영을 깨웠네<br/>각각 흩어져 하나가 없던 주는 우리 영을 깨웠네<br/>영을 깨워 주는 우리 영을 깨웠네<br/>영을 깨워 주는 우리 영을 깨웠네<br/>',NULL,34455,1);
INSERT INTO stanza VALUES('K999','2','바벨론 안의 종파 속에서 모두 일어서야 할 때라<br/>형제 자매여 입장 찾아서 모두 일어서야 할 때라<br/>일어서라 모든 종파 그룹 속에서<br/>일어서라 모든 종파 그룹 속에서<br/>',NULL,34456,2);
INSERT INTO stanza VALUES('K999','3','포로를 떠나 예루살렘에 모두 함께 올라 갑시다<br/>주가 보이신 한 입장 찾아 모두 함께 올라 갑시다<br/>올라가세 우리 주가 함께하시니<br/>올라가세 우리 주가 함께하시니<br/>',NULL,34457,3);
INSERT INTO stanza VALUES('K999','4','그리스도로 풍성한 접시 주의 성전으로 가져가<br/>주의 영으로 가득찬 사발 주의 성전으로 가져가<br/>가져가세 주의 그릇 모두 가져가<br/>가져가세 주의 그릇 모두 가져가<br/>',NULL,34458,4);
INSERT INTO stanza VALUES('K999','5','주의 택하신 예루살렘에 지금 주의 성전 세우세<br/>모든 성도여 함께 참예해 지금 주의 성전 세우세<br/>세워 세워 지금 주의 성전 세우세<br/>세워 세워 지금 주의 성전 세우세<br/>',NULL,34459,5);
INSERT INTO stanza VALUES('CS444','chorus','(姊妹)光中行，<br/>神兒子<br/>必洗淨<br/>我們一切的罪。<br/>若認罪，<br/>祂赦免，<br/>祂洗淨<br/>一切的罪。<br/>',NULL,34460,2);
INSERT INTO stanza VALUES('CS444','chorus','(弟兄)彼此交通，<br/>耶穌的血<br/>必洗淨我們一切的罪。<br/>祂是信實，<br/>祂是公義，<br/>祂洗淨一切的罪。<br/>',NULL,34461,3);
INSERT INTO stanza VALUES('NS523','1','Churches shine, Jesus’ testimony bright;<br/>They’re Christ’s reproduction, Spirit’s reprint;<br/>God Himself’s their light, their one expression;<br/>Christ’s appearance and virtues they possess.<br/>New ark we’re ent’ring, age dark forsaking;<br/>Noah’s house, the new kingdom heralding.<br/>Let the word of truth fill and constitute;<br/>With our God be infused to Him express.<br/>',NULL,34463,1);
INSERT INTO stanza VALUES('NS523','chorus','Lord Jesus, take me, break me; I’d hold nothing back from Thee;<br/>Fill me till it is no more I that live;<br/>That by Your resurrection life, we would Your testimony be.<br/>We would be the church You long for, testimony of Jesus on the earth.<br/>O Lord, Your dear bride are we, loving You so crazily,<br/>Fill us wholly, live Yourself exclusively;<br/>Lord, by Your resurrection power, make us fully one with Thee,<br/>As Your shining golden lampstands, Fulfilling Your heart’s desire today.<br/>',NULL,34464,2);
INSERT INTO stanza VALUES('NS523','2','Lampstands, gold living trees, incarnate God,<br/>With God’s nature, show forth resurrection;<br/>Planting new church trees, to all earth spreading;<br/>Sprouting, growing and blooming, bearing fruit;<br/>The seven lampstands: one form, one nature;<br/>Testimony, expression are but one;<br/>Fellowship and move all are in one flow;<br/>Just one ministry, and one Body.<br/>',NULL,34465,3);
INSERT INTO stanza VALUES('NS524','chorus','But I, I will most gladly spend<br/>And be utterly spent on behalf of your souls.<br/>But I, I will most gladly spend<br/>And be utterly spent on behalf of your souls.<br/>If I love you more abundantly, more abundantly,<br/>Am I loved less?<br/>If I love you more abundantly, more abundantly,<br/>But let it be so!<br/>',NULL,34466,1);
INSERT INTO stanza VALUES('NS525','1','Indeed the former things have come to pass,<br/>And new things I am telling you;<br/>Indeed the former things have come to pass,<br/>And new things I am telling you;<br/>',NULL,34467,1);
INSERT INTO stanza VALUES('NS525','2','Before they spring forth<br/>I will let you hear them.<br/>Before they spring forth<br/>I will let you hear them.<br/>',NULL,34468,2);
INSERT INTO stanza VALUES('NS525','3','Forgetting the things which are behind<br/>And stretching forward to the things<br/>Which are before, I pursue toward the goal for the prize<br/>Which God has called me upward in Christ.<br/>',NULL,34469,3);
INSERT INTO stanza VALUES('NS525','end-note','(All three stanzas can be sung simultaneously.)<br/>',NULL,34470,4);
INSERT INTO stanza VALUES('NS526','chorus','Thou hast set our iniquities,<br/>Lord, before Thy face;<br/>E’en our secret hidden sins,<br/>Light of Thy countenance traced.<br/>For in Thine o’erflowing wrath<br/>Have our days wholly gone by;<br/>And our years come to an end<br/>Like a whispered sigh.<br/>',NULL,34471,1);
INSERT INTO stanza VALUES('NS526','chorus','Oh, the days of all our years are seventy,<br/>Or, if due to strength, they eighty be;<br/>Yet what’s their pride and boast?<br/>Toil and sorrow and woe.<br/>All soon will fade;<br/>And we, too, fly away.<br/>',NULL,34472,2);
INSERT INTO stanza VALUES('NS526','chorus','Teach us then to number our days,<br/>Heart of wisdom to obtain.<br/>O Lord, teach us then to number our days,<br/>Heart of wisdom to gain.<br/>Satisfy us, Lord, in the morn<br/>With lovingkindness outpoured,<br/>That a joyful ringing shout may arise<br/>All the days of our life.<br/>Lord, according to all the days<br/>That we afflictions have faced,<br/>And to the years wherein evil we’ve seen,<br/>Make us glad in Thee,<br/>Make us glad in Thee.<br/>',NULL,34473,3);
INSERT INTO stanza VALUES('NS527','chorus','Let us rejoice and exult,<br/>And let us give glory to Him,<br/>For the marriage of the Lamb has come,<br/>And His wife has made herself,<br/>Made herself ready.<br/>',NULL,34474,1);
INSERT INTO stanza VALUES('NS527','chorus','And it was given her that<br/>She should be clothed in fine linen,<br/>Bright and clean;<br/>For the fine linen is<br/>The righteousnesses of the saints,<br/> of the saints.<br/>',NULL,34475,2);
INSERT INTO stanza VALUES('NS527','chorus','And he said to me, Write,<br/>Blessed are they who are called,<br/>Called to the marriage dinner of the Lamb.<br/>And he said to me,<br/>These are the true words of God.<br/>And he said to me,<br/>These are the true words of God.<br/>',NULL,34476,3);
INSERT INTO stanza VALUES('NS528','chorus','Whom having not seen, you love, you love;<br/>Into whom though not seeing Him at present,<br/>yet believing;<br/>Whom having not seen, you love, you love;<br/>Into whom though not seeing Him at present,<br/>yet believing,<br/>You exult with joy<br/>That is unspeakable<br/>And full of glory.<br/>You exult with joy<br/>That is unspeakable<br/>And full of glory.<br/>First Peter 1:8.<br/>',NULL,34477,1);
INSERT INTO stanza VALUES('NS529','chorus','And I will give them<br/>A heart to know Me,<br/>That I am Jehovah;<br/>And I will give them<br/>A heart to know Me,<br/>That I am Jehovah.<br/>',NULL,34478,1);
INSERT INTO stanza VALUES('NS529','chorus','And they will be My people,<br/>And I will be their God;<br/>They will be My people,<br/>And I will be their God;<br/>They will be My people,<br/>And I will be their God.<br/>',NULL,34479,2);
INSERT INTO stanza VALUES('NS529','chorus','For they will return to Me<br/>With their whole heart.<br/>',NULL,34480,3);
INSERT INTO stanza VALUES('NS530','1','Above the waste and emptiness<br/>Broods the Spirit of God,<br/>Bringing forth God’s speaking in us.<br/>Hey! Let there be light!<br/>',NULL,34481,1);
INSERT INTO stanza VALUES('NS530','chorus','And the light shines in the darkness,<br/>And the darkness did not overcome.<br/>In Him was life, and the life was the light of men.<br/>',NULL,34482,2);
INSERT INTO stanza VALUES('NS530','2','Nights decreasing, day increasing,<br/>Every day His Word we’re seeking;<br/>Don’t be discouraged, spirit releasing!<br/>We are the children of light.<br/>',NULL,34483,3);
INSERT INTO stanza VALUES('NS531','1','Christ lives in me, oh how can this be?<br/>He breathed Himself as life to me.<br/>How simple, and normal, His life becoming mine.<br/>Yes, Lord, keep spreading in my being.<br/>',NULL,34484,1);
INSERT INTO stanza VALUES('NS531','2','Christ lives in me, oh what a mystery.<br/>Not seen nor heard, yet still lovely.<br/>Beautiful and charming, I can’t stop loving Him.<br/>Jesus, most precious One to me.<br/>',NULL,34485,2);
INSERT INTO stanza VALUES('NS531','3','Christ lives in me, yes, my reality.<br/>Oh Tree of Life, I eat freely.<br/>Enjoying, day by day, I live because of Him.<br/>Dear Lord, You taste so good to me.<br/>',NULL,34486,3);
INSERT INTO stanza VALUES('NS532','1','The full price King David did pay,<br/>Ornan’s threshing floor to obtain;<br/>Here God’s house was built and with glory filled;<br/>Yes, for God’s house King David paid dearly.<br/>Sacrifices, burnt offerings<br/>Let us now wholeheartedly bring.<br/>At great cost are purchased all precious things;<br/>For His house let’s unreservedly give.<br/>',NULL,34487,1);
INSERT INTO stanza VALUES('NS532','chorus','Lord, like David, we’ll pay the full price;<br/>With strong purpose, from slumber arise!<br/>Set our heart and soul, Lord, affection, too;<br/>For Thine house may we be faithful and true.<br/>Lord, our off’rings will never be those<br/>Which cost nothing; to Thee all we owe!<br/>Set our heart and soul, Lord, affection, too;<br/>For Thine house may we be faithful and true.<br/>',NULL,34488,2);
INSERT INTO stanza VALUES('NS532','2','Oh, how great the work David faced;<br/>’Tis not man’s but God’s dwelling place.<br/>For this cause prepared he abundantly—<br/>Gold and silver, and timber aplenty.<br/>Lord, like him we too must prepare<br/>For Thine house; this burden we bear,<br/>In affliction, comfort—in any state—<br/>Always ready Thine high call to obey.<br/>',NULL,34489,3);
INSERT INTO stanza VALUES('NS532','3','From his private chest of great wealth<br/>David brought forth, nothing withheld.<br/>His own gold and silver and precious things,<br/>He surrendered in off’ring so freely.<br/>Our own wealth, our comfort and ease,<br/>E’en our youth, bright future and dreams,<br/>On the altar lay we most cheerfully;<br/>None’s more worthy all our best to receive!<br/>',NULL,34490,4);
INSERT INTO stanza VALUES('NS532','4','Who are we that we’d dare to boast<br/>Of whate’er on Thee we’d bestow?<br/>All’s from Thee; from Thine hand we give them back,<br/>Borrowed treasures returning most gladly.<br/>Who shall then to Thee consecrate<br/>Willingly his being today—<br/>His whole heart and soul, his whole mind and strength?<br/>Lord, our life we now present unto Thee!<br/>',NULL,34491,5);
INSERT INTO stanza VALUES('NS532','chorus','Oh, how glorious! God’s people, arise!<br/>Join the great throng who’ll pay the full price!<br/>With our spirit strengthened, our praise we sing<br/>To our God who will the building complete.<br/>Oh, how worth it! We’ve counted the cost;<br/>Boldy offer; ’tis never a loss!<br/>God, man as one mingled—our destiny;<br/>Mutual rest and satisfaction complete!<br/>',NULL,34492,6);
INSERT INTO stanza VALUES('NS533','1','When I grow up, I want to be a man of God.<br/>I want to be someone who is full of life.<br/>I want to be someone who loves the Lord,<br/>And so I choose to be a man of God.<br/>There is nothing else in the world I’d rather be,<br/>There is nothing else in the world that I’d rather be.<br/>',NULL,34493,1);
INSERT INTO stanza VALUES('NS533','2','When I grow up, I want to be a man of God.<br/>I want to be someone who is full of life.<br/>I want to be someone who loves the Lord,<br/>And so I choose to be a man of God.<br/>',NULL,34494,2);
INSERT INTO stanza VALUES('NS533','3','And even though I’m still a kid,<br/>The choice is clear to me.<br/>A man of God is what I am—<br/>A man of God, that’s exactly what I want to be.<br/>',NULL,34495,3);
INSERT INTO stanza VALUES('NS534','1','They walked along the road:<br/>Two disciples, all alone,<br/>Their Master dead and gone.<br/>A man to them drew near,<br/>Spoke to them and calmed their fears,<br/>They told Him everything.<br/>',NULL,34496,1);
INSERT INTO stanza VALUES('NS534','chorus','(He said:)<br/>Why don’t you believe?<br/>For it was necessary<br/>For the Christ to suffer all these things<br/>And enter His glory.<br/>Why don’t you believe?<br/>Why don’t you believe?<br/>',NULL,34497,2);
INSERT INTO stanza VALUES('NS534','2','They came to journey’s end;<br/>He came in to eat with them,<br/>He blessed and broke the bread.<br/>Then opened were their eyes;<br/>Jesus Christ they recognized.<br/>He disappeared from them.<br/>',NULL,34498,3);
INSERT INTO stanza VALUES('NS534','chorus','(They said:)<br/>Did not our hearts burn<br/>As He spoke those words?<br/>While we walked with Him<br/>The Scriptures were opened.<br/>Did not our hearts burn?<br/>Did not our hearts burn?<br/>',NULL,34499,4);
INSERT INTO stanza VALUES('NS534','3','We walk along our road<br/>He reminds us we were told<br/>“I’m with you every day.”<br/>No matter how we feel,<br/>He’s the Spirit, He is real,<br/>Indwelling you and me.<br/>',NULL,34500,5);
INSERT INTO stanza VALUES('NS534','chorus','(We say:)<br/>Do not our hearts burn<br/>When we hear His word?<br/>Jesus Christ, within,<br/>In resurrection lives!<br/>Do not our hearts burn?<br/>Do not our hearts burn?<br/>',NULL,34501,6);
INSERT INTO stanza VALUES('NS535','1','The altar of burnt offering<br/>In God’s economy,<br/>Is Christ, the bronzed acacia wood,<br/>Judged in humanity.<br/>The altar of burnt offering<br/>The cross of Christ displays,<br/>One person—Christ; one way—the cross—<br/>Encompass all God’s ways.<br/>The altar of burnt offering’s<br/>Where precious blood was shed;<br/>The blood of Jesus is our plea<br/>As forward we are led.<br/>The altar of burnt offering<br/>Is meeting God’s demand,<br/>God’s righteousness and holiness<br/>Are our eternal stand.<br/>',NULL,34502,1);
INSERT INTO stanza VALUES('NS535','2','Come forward to the Holiest;<br/>With God, in oneness, pray;<br/>The precious blood’s applied again,<br/>God’s economic way.<br/>Anointing oil applied upon<br/>Both altars clearly shows:<br/>The move of God’s eternal grace<br/>Between two altars flows.<br/>The fire from heaven, which came down<br/>To burn the offered Son,<br/>Becomes the fire to incense burn,<br/>As fragrance to God’s throne;<br/>The sweetness we experience<br/>Through Christ’s inclusive death,<br/>Is sweetness unto God through our<br/>Ascending, praying breath.<br/>',NULL,34503,2);
INSERT INTO stanza VALUES('NS536','1','We turn our hearts to You, Lord.<br/>Make us all so true,<br/>Blend our hearts together, make all things new.<br/>As we turn away<br/>From this earthly dross,<br/>What was gain before we now count as loss.<br/>',NULL,34504,1);
INSERT INTO stanza VALUES('NS536','chorus','Every day we find You living<br/>In our spirit—the full supply;<br/>How we’re blessed that<br/>You are giving all You are to us in life.<br/>',NULL,34505,2);
INSERT INTO stanza VALUES('NS536','2','As we set our mind<br/>On You, living One,<br/>In our spirit, Lord, we find we are one.<br/>What was once our case<br/>Seem to slip away<br/>As we fellowship with You, we long to stay.<br/>',NULL,34506,3);
INSERT INTO stanza VALUES('NS536','3','I would linger here<br/>In Your presence, Lord;<br/>How we find our hearts loving You more.<br/>As we guard our hearts,<br/>Keep them unto Thee,<br/>Preserve us, Lord, for all eternity.<br/>',NULL,34507,4);
INSERT INTO stanza VALUES('NS537','1','But you, beloved, building up<br/>Yourselves on your most holy faith,<br/>Keep yourselves in the love of God,<br/>By praying, praying<br/>in the Holy Spirit.<br/>',NULL,34508,1);
INSERT INTO stanza VALUES('NS537','2','Awaiting mercy of our Lord,<br/>Mercy of our Lord Jesus Christ,<br/>Which issues in eternal life—<br/>The life of God—<br/>the goal of our seeking.<br/>',NULL,34509,2);
INSERT INTO stanza VALUES('NS537','3','All praise to Him who’s able to<br/>Guard you from stumbling and set you,<br/>Set you before His glory then,<br/>Yes, without blemish<br/>and in exultation.<br/>',NULL,34510,3);
INSERT INTO stanza VALUES('NS537','4','Praise to our only Savior God,<br/>All praise to Jesus Christ, our Lord;<br/>To Him be glory, majesty,<br/>And might, authority<br/>before all time and now,<br/>',NULL,34511,4);
INSERT INTO stanza VALUES('NS537','5','Amen, unto eternity.<br/>Amen, Your glory, majesty,<br/>The might and the authority<br/>Be Yours, be Yours,<br/>our only Savior God and Lord.<br/>',NULL,34512,5);
INSERT INTO stanza VALUES('NS537','6','Amen, unto eternity.<br/>Amen, Your glory, majesty,<br/>The might and the authority<br/>Be Yours, be Yours,<br/>our only Savior God and Lord.<br/>',NULL,34513,6);
INSERT INTO stanza VALUES('NS538','1','In contact through the ages, God designates Himself;<br/>“Jehovah” is His title as He speaks to us.<br/>Not distant and unknowable, but seen with Abraham<br/>Whose contact, sweet and intimate.<br/>',NULL,34514,1);
INSERT INTO stanza VALUES('NS538','chorus','The “I Am Who I Am,” the self-existing One,<br/>What miracle that He would stoop to us;<br/>Not formal ways from concept<br/>But sweet relationship<br/>That comes as conversation of two friends.<br/>',NULL,34515,2);
INSERT INTO stanza VALUES('NS538','2','While Abraham remained standing before Jehovah,<br/>His purpose was to intercede for Lot, for Lot.<br/>This glorious intercession that Abraham made<br/>Was just a human conversation.<br/>',NULL,34516,3);
INSERT INTO stanza VALUES('NS538','3','Not a stranger you talk to in the grocery store once,<br/>Not a relative you call twice a month;<br/>This human relationship between God and man<br/>Comes from many interactions.<br/>',NULL,34517,4);
INSERT INTO stanza VALUES('NS539','1','Let the word of Christ dwell in you richly,<br/>Let the word of Christ dwell in you richly,<br/>In psalms and hymns and spiritual songs,<br/>Singing with grace in your hearts to God.<br/>',NULL,34518,1);
INSERT INTO stanza VALUES('NS539','end-note','(repeat)<br/>',NULL,34519,2);
INSERT INTO stanza VALUES('NS539','chorus','Be filled in spirit,<br/>Speaking to one another<br/>In psalms and hymns and spiritual songs,<br/>Singing and psalming with your heart to the Lord.<br/>',NULL,34520,3);
INSERT INTO stanza VALUES('NS539','end-note','(repeat Verse 1)<br/>',NULL,34521,4);
INSERT INTO stanza VALUES('NS540','1','The water in the word, the water in the word,<br/>Washing by the water, the water in the word,<br/>That He might sanctify her, cleansing her,<br/>Cleansing by the washing of the water in the word.<br/>',NULL,34522,1);
INSERT INTO stanza VALUES('NS540','end-note','(Repeat)<br/>',NULL,34523,2);
INSERT INTO stanza VALUES('NS540','2','Husbands, love your wives<br/>Even as Christ loved the church<br/>And gave Himself up for her,<br/>Gave Himself up for her.<br/>',NULL,34524,3);
INSERT INTO stanza VALUES('NS540','3','The water in the word, the water in the word,<br/>Washing by the water, the water in the word,<br/>That He might sanctify her, cleansing her,<br/>Cleansing by the washing of the water in the word,<br/>',NULL,34525,4);
INSERT INTO stanza VALUES('NS540','end-note','(Repeat)<br/>',NULL,34526,5);
INSERT INTO stanza VALUES('NS540','4','That He might present<br/>The church to Himself glorious,<br/>Not having spot or wrinkle<br/>Or any such things, any such things.<br/>',NULL,34527,6);
INSERT INTO stanza VALUES('NS540','5','The water in the word, the water in the word,<br/>Washing by the water, the water in the word,<br/>That He might sanctify her, cleansing her,<br/>Cleansing by the washing of the water in the word.<br/>',NULL,34528,7);
INSERT INTO stanza VALUES('NS541','chorus','We can eat, we can drink,<br/>We can enjoy God,<br/>By loving His priceless presence;<br/>We can eat, we can drink,<br/>We can enjoy God<br/>By calling His precious name.<br/>',NULL,34529,1);
INSERT INTO stanza VALUES('NS541','1','We need to love the Lord<br/>And keep His pure Word,<br/>And wear Christ as our clothes;<br/>We need to call His name,<br/>In Him remain,<br/>In Him, our soul-life lose.<br/>',NULL,34530,2);
INSERT INTO stanza VALUES('NS541','end-note','(Chorus)<br/>',NULL,34531,3);
INSERT INTO stanza VALUES('NS541','2','We need to eat the Lord,<br/>Absorb His pure Word<br/>And breathe in Christ as life;<br/>And as we breathe God in,<br/>The Spirit begins<br/>Dispensing the life supply.<br/>',NULL,34532,4);
INSERT INTO stanza VALUES('NS541','end-note','(Chorus)<br/>',NULL,34533,5);
INSERT INTO stanza VALUES('NS542','1','You need the Nazarites to turn this age.<br/>Move in me to turn my heart and consecrate.<br/>Save me from all selfish seeking, search my heart.<br/>Set me free, make every bondage break apart!<br/>',NULL,34534,1);
INSERT INTO stanza VALUES('NS542','chorus','I need You, but You need me too,<br/>To do what You want to do.<br/>Rekindle all of my love for You,<br/>To be a voluntarily consecrated one.<br/>',NULL,34535,2);
INSERT INTO stanza VALUES('NS542','2','You need the Nazarites to turn this age.<br/>Strengthen us to overcome in these last days—<br/>All rebellion, natural affection, even death,<br/>Worldly pleasures, every enjoyment of the flesh.<br/>',NULL,34536,3);
INSERT INTO stanza VALUES('NS542','chorus','I need You, but You need me too,<br/>To do what You want to do.<br/>Rekindle all of my love for You,<br/>To be a voluntarily consecrated one.<br/>',NULL,34537,4);
INSERT INTO stanza VALUES('NS542','3','Sanctify me absolutely,<br/>Take my life and have Your way.<br/>Overcome in me, give me victory<br/>Through Your life and end this age.<br/>',NULL,34538,5);
INSERT INTO stanza VALUES('NS542','chorus','I need You, but You need me too,<br/>To do what You want to do.<br/>Rekindle all of my love for You,<br/>To be a voluntarily consecrated one.<br/>',NULL,34539,6);
INSERT INTO stanza VALUES('NS543','1','The last Adam became a life-giving Spirit.<br/>The Lord is the Spirit; the Spirit gives life.<br/>',NULL,34540,1);
INSERT INTO stanza VALUES('NS543','2','But he who is joined to the Lord is one spirit.<br/>Oh, we have been joined to the Lord!<br/>We are one spirit with Him.<br/>',NULL,34541,2);
INSERT INTO stanza VALUES('NS543','end-note','(Repeat)<br/>',NULL,34542,3);
INSERT INTO stanza VALUES('NS543','3','The last Adam became a life-giving Spirit.<br/>The Lord is the Spirit; the Spirit gives life.<br/>',NULL,34543,4);
INSERT INTO stanza VALUES('NS543','4','The last Adam became a life-giving Spirit,<br/>a life-giving Spirit.<br/>',NULL,34544,5);
INSERT INTO stanza VALUES('NS543','5','In one Spirit we were all baptized into one Body<br/>And were all given to drink one Spirit, one Spirit.<br/>',NULL,34545,6);
INSERT INTO stanza VALUES('NS543','6','Ministers of the new covenant, not of the letter<br/>but of the Spirit.<br/>We are being transformed into the same image<br/>From glory to glory, even as from the Lord Spirit.<br/>',NULL,34546,7);
INSERT INTO stanza VALUES('CB160','1','Hari Ka’s kinabuhi ko<br/>Himaya maimo;<br/>Tultolan Mo ako karon<br/>Ngadto sa Calvario.<br/>',NULL,37390,1);
INSERT INTO stanza VALUES('CB160','chorus','Basi’g hikalimtan ko na<br/>Kasakit Mo’s Getsemane;<br/>Nga gihigugma Mo ako<br/>Dad-a ko’s Calvario.<br/>',NULL,37391,2);
INSERT INTO stanza VALUES('CB160','2','Pakit-a’s gilubngan Nimo,<br/>Gibakhoan nila;<br/>Mga anghel ang nagbantay,<br/>Samtang natulog Ka.<br/>',NULL,37392,3);
INSERT INTO stanza VALUES('CB160','3','Pasamaha ni Maria,<br/>Kadlawong naghalad;<br/>Pakit-a’s lubnganang basyo,<br/>Dad-a ko’s Calvario.<br/>',NULL,37393,4);
INSERT INTO stanza VALUES('CB160','4','Malipay untang mopas-an<br/>Sa krus adlaw-adlaw;<br/>Moambit’s kopa’s kasubo<br/>Nga giinom Nimo.<br/>',NULL,37394,5);
INSERT INTO stanza VALUES('CB160','5','Pun-a’s tinguha, Ginoo,<br/>Alang sa mga tawo;<br/>Putlia sa kalayo Mo,<br/>Mamulong’s Calvario.<br/>',NULL,37395,6);
INSERT INTO stanza VALUES('E979','10','The city needs no sun nor moon<br/>For God’s own glory is its light;<br/>The Lamb’s the lamp the city bears,<br/>In all directions blazing bright.<br/>',NULL,37396,10);
INSERT INTO stanza VALUES('E979','11','Out from the throne of God and the Lamb<br/>Flows midst the street a living stream,<br/>And on its banks, on either side,<br/>The tree of life is thriving seen.<br/>',NULL,37397,11);
INSERT INTO stanza VALUES('E979','12','This signifies the life of God<br/>Not just for food or water flows,<br/>But carries God’s authority<br/>As it throughout the city goes.<br/>',NULL,37398,12);
INSERT INTO stanza VALUES('E979','13','The street of purest gold therein<br/>God’s nature as the way doth show;<br/>A river in it flows for drink<br/>And fruits of life abundant grow.<br/>',NULL,37399,13);
INSERT INTO stanza VALUES('E979','14','The number twelve means government,<br/>Perfection which eternal is;<br/>God blent with man it also tells-<br/>Three multiplied by four shows this.<br/>',NULL,37400,14);
INSERT INTO stanza VALUES('E979','15','Darkness and death shall be no more,<br/>Sorrow and pain shall pass away,<br/>Old will be gone and all be new,<br/>God will abide with man for aye.<br/>',NULL,37401,15);
INSERT INTO stanza VALUES('E979','16','The city has God’s image full,<br/>It rules for Him, the sovereign King,<br/>Fulfilling His eternal plan,<br/>Complete content to Him to bring.<br/>',NULL,37402,16);
INSERT INTO stanza VALUES('G10001','1','Gottes Ökonomie ist, dass der Mensch werd genau wie Er<br/>Im Leben und Natur, doch nicht in der Gottheit.<br/>Mit dem Menschen macht Er Sich eins<br/>Und den Menschen eins mit Sich.<br/>So wird Er vergrößert und erweitert in Seinem Ausdruck,<br/>Dass all Seine göttlichen Eigenschaften<br/>Nun zum Ausdruck kommen in menschlichen Tugenden.<br/>',NULL,38569,1);
INSERT INTO stanza VALUES('G10002','1','Welch Wunder! Welch Geheimnis ist’s!<br/>Dass Gott und Mensch vermengt sein solln!<br/>Gott wurde Mensch, macht ihn zu Gott,<br/>Ökonomie, oh so wertvoll!<br/>Sein Wohlgefallen, Herzenswunsch,<br/>Sein höchstes Ziel erreicht wird so.<br/>',NULL,38570,1);
INSERT INTO stanza VALUES('G10002','2','Fleisch wurde Er! Der erst Gott-Mensch,<br/>Er möchte, dass ich Gott mög sein:<br/>Ihm gleich im Leben und Natur,<br/>Doch Seine Gottheit ist nicht mein,<br/>Und Seine Eigenschaften sind<br/>Nun meine Tugenden so rein.<br/>',NULL,38571,2);
INSERT INTO stanza VALUES('G10002','3','Denn nicht mehr länger lebe ich,<br/>Doch Gott lebt nun vermengt mit mir.<br/>Uns in den Dreieinen Gott einbaut,<br/>Sein universales Haus sind wir,<br/>Und wir sind Sein organisch Leib<br/>Für Seinen Ausdruck korprativ.<br/>',NULL,38572,3);
INSERT INTO stanza VALUES('G10002','4','Die heilge Stadt Jerusalem<br/>Gesamtheit der Visionen zeigt;<br/>Dreieiner Gott – dreiteilger Mensch –<br/>Ein Liebespaar in Ewigkeit -<br/>Mensch und Gott – sie wohnen ineinander,<br/>Ein gegenseitig Wohnort heut;<br/>Sieh, Gottes Herrlichkeit, sie strahlt<br/>Voll Glanz nun aus der Menschlichkeit.<br/>',NULL,38573,4);
INSERT INTO stanza VALUES('G10002','end-note','(Die letzten beiden Zeilen der Strophen 1, 2 und 3 wiederholen)<br/>',NULL,38574,5);
INSERT INTO stanza VALUES('NS544','1','O Lord, You know what’s in my heart,<br/>Desires concealed in my inward parts;<br/>Though “I am Yours” my mouth’s confessed,<br/>By many loves my heart’s possessed.<br/>O Lord, my desp’rate cry now heed—<br/>Regain my heart! Your help I need!<br/>O’erturn, expose what weighs me down,<br/>That in these things I would not drown.<br/>',NULL,38575,1);
INSERT INTO stanza VALUES('NS544','2','How blind I’ve been, how filled with pride,<br/>Believing in the things of sight,<br/>In things uncertain placing hope,<br/>And not in Him who all upholds.<br/>Oh, turn my heart from meaner things;<br/>Forgive me, Lord, for wavering.<br/>I must pursue the One who’s real;<br/>The false, release; no more deceived!<br/>',NULL,38576,2);
INSERT INTO stanza VALUES('NS544','3','Cause me, dear Lord, to truly see—<br/>I’m Yours; a man of God indeed.<br/>Your life and nature I, too, share;<br/>To flee earth’s snares, my earnest pray’r.<br/>My heart, dear Lord, I yield anew<br/>To only love, lay hold on You.<br/>With cords of man, with bands of love,<br/>Lord, keep me faithful till You come.<br/>',NULL,38577,3);
INSERT INTO stanza VALUES('NS545','1','Behold, I stand at the door and knock;<br/>If anyone hears My voice and opens the door, <br/>Then I will come in to him and dine with him<br/>and he with Me.<br/>',NULL,38578,1);
INSERT INTO stanza VALUES('NS545','end-note','(repeat)<br/>',NULL,38579,2);
INSERT INTO stanza VALUES('NS545','2','He who overcomes,<br/>To him I will give<br/>To sit with Me on My throne,<br/>As I also overcame and sat with My Father on His throne.<br/>',NULL,38580,3);
INSERT INTO stanza VALUES('NS546','1','And the God of peace Himself sanctify you wholly,<br/>And may your spirit and soul and body<br/>Be preserved complete, without blame,<br/>At the coming of our Lord Jesus Christ.<br/>',NULL,38581,1);
INSERT INTO stanza VALUES('NS546','end-note','(Repeat)<br/>',NULL,38582,2);
INSERT INTO stanza VALUES('NS546','2','Faithful is He who calls you, who also will do it.<br/>Faithful is He who calls you, who also will do it.<br/>The faithful God who has called us,<br/>He will also sanctify us,<br/>Sanctify us wholly, and preserve<br/>Our entire being complete.<br/>',NULL,38583,3);
INSERT INTO stanza VALUES('NS547','1','Beloved, let us love one another,<br/>For love is of God,<br/>And everyone that loveth is born of God<br/>And knoweth God.<br/>He that loveth not knoweth not God,<br/>For God is love.<br/>Beloved, let us love one another.<br/>',NULL,38584,1);
INSERT INTO stanza VALUES('NS548','chorus','Kiss the Son, kiss the One<br/>Who for love to me has come,<br/>Cheering me, charming me,<br/>And has died upon the tree,<br/>He died for me, saving me,<br/>Now His Spirit joins to me,<br/>I’ve kissed the Son!<br/>',NULL,38585,1);
INSERT INTO stanza VALUES('NS548','1','Serving in my mingled spirit<br/>In the gospel of His Son,<br/>First receiving Christ the Spirit;<br/>He’s the processed Triune One.<br/>',NULL,38586,2);
INSERT INTO stanza VALUES('NS548','2','Jesus Christ in our experience<br/>Is the worship God desires;<br/>This true worshipping in spirit<br/>Is the service God requires.<br/>',NULL,38587,3);
INSERT INTO stanza VALUES('NS548','3','Serving Christ, just let Him kiss you,<br/>Living with Him all the day,<br/>Worshipping God by our living<br/>Is the gospel-serving way.<br/>',NULL,38588,4);
INSERT INTO stanza VALUES('NS548','4','In the Body let us serve Him,<br/>Nothing natural, there, can be;<br/>Through Christ’s death and resurrection,<br/>Worship in reality.<br/>',NULL,38589,5);
INSERT INTO stanza VALUES('NS548','end-note','(End with chorus)<br/>',NULL,38590,6);
INSERT INTO stanza VALUES('NS549','1','Let him take the water of life freely.<br/>Let him take the water of life freely.<br/>And the Spirit and the Bride say, Come!<br/>Let him who hears also say, Come!<br/>Let him who is thirsty also come,<br/>And he who wills,<br/>Let him take the water of life.<br/>',NULL,38591,1);
INSERT INTO stanza VALUES('NS550','1','Then you shall be My personal treasure<br/>From among all peoples,<br/>Then you shall be My personal treasure<br/>For all the earth is Mine.<br/>',NULL,38592,1);
INSERT INTO stanza VALUES('NS550','2','And you shall be to Me<br/>A kingdom of priests<br/>And a holy nation,<br/>To Me a kingdom of priests.<br/>',NULL,38593,2);
INSERT INTO stanza VALUES('NS550','3','And He made us a kingdom,<br/>Priests to His God and Father,<br/>To Him be the glory and might<br/>Forever and ever. Amen.<br/>',NULL,38594,3);
INSERT INTO stanza VALUES('NS550','end-note','Stanza 2 can be sung as a countermelody over stanza 1.<br/>',NULL,38595,4);
INSERT INTO stanza VALUES('NS551','1','For the word of the cross<br/>Is to those who are perishing<br/>Foolishness, foolishness,<br/>',NULL,38596,1);
INSERT INTO stanza VALUES('NS551','2','For it is written, “I will destroy<br/>The wisdom of the wise,<br/>And the understanding of those<br/>Who understand I will set aside.”<br/>',NULL,38597,2);
INSERT INTO stanza VALUES('NS551','3','But to us who are being saved<br/>It is the power, power of God.<br/>But to us who are being saved<br/>It is the power, power of God.<br/>',NULL,38598,3);
INSERT INTO stanza VALUES('NS552','1','The church as the bride is a matter of love,<br/>God’s inner substance, so sweet;<br/>As we enjoy God in His presence divine,<br/>Our first love and best love we keep.<br/>',NULL,38599,1);
INSERT INTO stanza VALUES('NS552','chorus','Nothing but love, poured from above<br/>Can make us overcomers today;<br/>Love strong as death, ’til our last breath,<br/>Come quickly, Lord Jesus, we pray!<br/>',NULL,38600,2);
INSERT INTO stanza VALUES('NS552','2','O come, my Belov’d, and let us go forth,<br/>Enjoying a fresh bridal love;<br/>When working together, a fragrance breaks forth,<br/>The fragrance of mutual love.<br/>',NULL,38601,3);
INSERT INTO stanza VALUES('NS552','3','To just love the Lord is to give Him first place,<br/>To live Him and treasure His heart,<br/>Appreciate Him, open fully to Him,<br/>Until we become His counterpart.<br/>',NULL,38602,4);
INSERT INTO stanza VALUES('NS552','4','Lord, grant us a strong and affectionate love,<br/>A burning and flaming hot love;<br/>Our last testimony, through rapturous praise,<br/>Is “Loving You, Lord, was enough!”<br/>',NULL,38603,5);
INSERT INTO stanza VALUES('NS553','chorus','Rejoice in the Lord! Rejoice in the Lord always!<br/>Rejoice in the Lord! Rejoice in the Lord always!<br/>',NULL,38604,1);
INSERT INTO stanza VALUES('NS553','1','Rejoice in the Lord! Rejoice in the Lord!<br/>Rejoice with thanksgiving! Rejoice ever more.<br/>Rejoice in the Lord all your days;<br/>Rejoice in the Lord always!<br/>',NULL,38605,2);
INSERT INTO stanza VALUES('NS553','2','Rejoice in the Lord! Rejoice in the Lord!<br/>Rejoice in His life; rejoice in His Word.<br/>Rejoice in His love for you all your days.<br/>Rejoice in the Lord always!<br/>',NULL,38606,3);
INSERT INTO stanza VALUES('NS554','1','In our heart, in our heart, in our heart, in our heart,<br/>Christ is inscribed in us;<br/>In the church, in the church, in the church, in the church<br/>A living letter, the apostle’s ministry<br/>Not with ink but the Spirit,<br/>In the apostle and me,<br/>Seen and read by the nations,<br/>Shining forth this glorious ministry!<br/>',NULL,38607,1);
INSERT INTO stanza VALUES('NS555','1','In our hands, the seed of life we hold,<br/>Fitted to awake life in dead souls<br/>And transforms worms of dust<br/>Into heirs of God’s trust;<br/>God is calling; how can we withhold?<br/>',NULL,38608,1);
INSERT INTO stanza VALUES('NS555','chorus','Can we turn a deaf ear<br/>To God’s solemn appeal?<br/>In the Name we arise,<br/>Preach the kingdom, our Christ!<br/>',NULL,38609,2);
INSERT INTO stanza VALUES('NS555','2','Should we in our narrow spheres remain,<br/>When vast fields await our laboring?<br/>Fields are white for us all;<br/>All is set, us to call<br/>For a noble service to our King.<br/>',NULL,38610,3);
INSERT INTO stanza VALUES('NS555','3','If it be the duty of all men<br/>To believe the gospel brought to them<br/>Then the duty is it<br/>Of those ’trusted with it<br/>To make known this gospel to all men.<br/>',NULL,38611,4);
INSERT INTO stanza VALUES('NS555','chorus','We abandon our all,<br/>We are for our new goal;<br/>This our plan for our lives—<br/>Him to preach all our lives!<br/>',NULL,38612,5);
INSERT INTO stanza VALUES('NS555','4','’Twas the army answering God’s call,<br/>Willing to lay down their lives,<br/>Their all For the spread of God’s Word<br/>That established His Word<br/>In the million hearts that desp’rate called.<br/>',NULL,38613,6);
INSERT INTO stanza VALUES('NS555','5','Like that army, let us not delay;<br/>Heed God’s call and yield our all today;<br/>That this seed of great worth<br/>Reach the ends of the earth<br/>And our God may quickly end this age.<br/>',NULL,38614,7);
INSERT INTO stanza VALUES('NS556','1','Therefore do not be ashamed of the testimony of our Lord,<br/>Nor of me His prisoner, for the testimony of our Lord;<br/>But suffer evil with the gospel<br/>According to the power of God;<br/>Who has saved us and called us with a holy calling,<br/>Not according to our works<br/>But according to His own purpose and grace,<br/>Which was given unto us in Christ Jesus.<br/>',NULL,38615,1);
INSERT INTO stanza VALUES('NS557','1','Can a woman forget her nursing child,<br/>That she would not have compassion on the son of her womb?<br/>Even though they may forget,<br/>Yet I will not forget you.<br/>I have engraved you on the palms of My hands,<br/>I have engraved you on the palms of My hands;<br/>Your walls are continually before Me.<br/>I have engraved you on the palms of My hands,<br/>I have engraved you on the palms of My hands.<br/>',NULL,38616,1);
INSERT INTO stanza VALUES('NS558','1','Four living creatures are<br/>God’s move on earth today;<br/>Revived by wind, cloud, fire,<br/>Electrum they display.<br/>',NULL,38617,1);
INSERT INTO stanza VALUES('NS558','2','Throughout our Christian life<br/>A storm wind starts to blow,<br/>Makes us dissatisfied,<br/>Disturbs our status quo.<br/>',NULL,38618,2);
INSERT INTO stanza VALUES('NS558','3','The wind is God Himself<br/>Who causes us to turn, <br/>To seek more of the Lord<br/>And make our spirit burn.<br/>',NULL,38619,3);
INSERT INTO stanza VALUES('NS558','4','This issues in the cloud—<br/>Abundant grace He brings,<br/>His overshadowing love,<br/>The safety of His wings.<br/>',NULL,38620,4);
INSERT INTO stanza VALUES('NS558','5','The fire then consumes<br/>All that is not from Him;<br/>It burns and sanctifies<br/>And makes us pure within.<br/>',NULL,38621,5);
INSERT INTO stanza VALUES('NS558','6','God’s precious essence thus<br/>Into our being poured,<br/>Electrum shines from us<br/>The glory of the Lord.<br/>',NULL,38622,6);
INSERT INTO stanza VALUES('NS558','7','The living creatures joined,<br/>Connected by their wings,<br/>In four directions fly,<br/>And God’s expression bring.<br/>',NULL,38623,7);
INSERT INTO stanza VALUES('NS558','8','Lord as Your move today<br/>As living creatures, we<br/>Your radiance would express,<br/>And Your authority.<br/>',NULL,38624,8);
INSERT INTO stanza VALUES('NS559','1','Lamb of God—our dear Redeeming One is Christ!<br/>For our sins He paid the highest price<br/>To redeem and to recover us<br/>Who were lost and fallen far from God.<br/>As the Lamb, He had no blemish;<br/>He was meek, even submissive.<br/>How can we like Him obedient be<br/>Unto death, that even of the cross?<br/>',NULL,38625,1);
INSERT INTO stanza VALUES('NS559','chorus','I want to follow Him,<br/>Rest from all my wandering,<br/>End all my endeavoring;<br/>Even though I know not where<br/>Or how—I know He cares!<br/>I know He’ll never err; I know He’ll lead me well.<br/>I know His voice; this now my choice—<br/>Follow where the Lamb would lead.<br/>',NULL,38626,2);
INSERT INTO stanza VALUES('NS559','2','When He came, though many followed in the way,<br/>Few remained who knew Him and His ways.<br/>Lamb of God—He took the narrow gate;<br/>The constricted way to life He traced;<br/>Sacrificed, though men denied Him;<br/>Gave His life, though men forsook Him.<br/>How can we t’ward Him still hardened be<br/>When to us He gave all selflessly?<br/>',NULL,38627,3);
INSERT INTO stanza VALUES('NS559','3','Lord we pray, preserve us faithful in the way<br/>All our days, never to fall away.<br/>By Your grace, keep us pursuing You,<br/>Taking up the cross to follow You.<br/>Consecrate we unreservedly,<br/>Absolute for You entirely.<br/>In our hearts, Lord, let the highways be<br/>Unto Zion single-heartedly.<br/>',NULL,38628,4);
INSERT INTO stanza VALUES('NS559','chorus','Now We will follow Him!<br/>To His call we’re answering,<br/>All we are we’re offering.<br/>New Jerusalem we see<br/>Come down from heav’n to earth!<br/>God and man mingled now, our oneness we avow<br/>Eternally, O gloriously!<br/>This is where the Lamb would lead!<br/>',NULL,38629,5);
INSERT INTO stanza VALUES('NS560','1','When you say “Lord!”<br/>You say a lot of things nobody else can say;<br/>When you say “Lord!”<br/>You say you care enough to only want<br/>the King of Kings!<br/>For there is nothing more;<br/>There’s only something less!<br/>Jesus is all in all; He is the very best.<br/>When you say, “Lord Jesus!”<br/>You’ve said it all.<br/>',NULL,38630,1);
INSERT INTO stanza VALUES('NS561','1','To my Lord I will sing, for I’ve received<br/>Endless mercy, love and grace in Jesus my King.<br/>Oh, what love!<br/>Even though undeserved, He gave Himself for me.<br/>Now I open my heart, to offer praise to Thee;<br/>There is an infinite gratitude<br/>In all my heart<br/>For all You’ve giv’n to me.<br/>',NULL,38631,1);
INSERT INTO stanza VALUES('NS561','2','To fulfill all the law, He took my place;<br/>He obeyed, e’en suffering, my sin to erase.<br/>I’m redeemed!<br/>Jesus has satisfied God’s heart, and set me free!<br/>Now I open my heart, to offer praise to Thee.<br/>There is an infinite gratitude<br/>In all my heart<br/>For all You’ve done for me.<br/>',NULL,38632,2);
INSERT INTO stanza VALUES('NS561','3','Wondrous news You’ve revealed—now I can see!<br/>Oh, what grace! Your love divine is flowing in me!<br/>Oh! That gaze!<br/>Eyes full of tenderness! Beholding face to face,<br/>Now I open my heart, to offer praise to Thee.<br/>There is an infinite gratitude<br/>In all my heart<br/>For all You’ve shown to me.<br/>',NULL,38633,3);
INSERT INTO stanza VALUES('NS561','4','Riven veil—living way thus He affords.<br/>He arose, the work completed! Oh, praise the Lord!<br/>Oh! What peace!<br/>Now I can boldly come into the holiest place!<br/>Now I open my heart, to offer praise to Thee.<br/>Your name is infinite plenitude!<br/>Oh, Jesus Lord!<br/>You’re everything to me!<br/>',NULL,38634,4);
INSERT INTO stanza VALUES('NS562','1','I heard the voice of the Lord<br/>Saying, Whom shall I send?<br/>I heard the voice of the Lord<br/>Saying, Who will go for us?<br/>And I said, I’m here, send me, Lord.<br/>I pour out the cost of my life;<br/>My future is vain—my destiny’s Christ;<br/>Christ is everything!<br/>',NULL,38635,1);
INSERT INTO stanza VALUES('NS562','2','The people who know their God<br/>Will rise up and show strength!<br/>People who thus know their God<br/>Will take action and move!<br/>We will spread You, Lord, through the earth.<br/>Lord, make us faithful to the end,<br/>Our life and our all be utterly spent,<br/>Spent for the church.<br/>',NULL,38636,2);
INSERT INTO stanza VALUES('NS562','3','Who’ll bring Your kingdom to come?<br/>These whose hearts are burned with fire.<br/>Who will fight the spiritual war?<br/>They descend as mighty ones!<br/>O Lord Jesus, capture our hearts;<br/>Lord make Your desire our desire!<br/>Your worth’s nothing less than all of our life!<br/>Our life’s to bring You back!<br/>',NULL,38637,3);
INSERT INTO stanza VALUES('NS563','1','God has set His sign, a rainbow,<br/>Midst the rainy clouds above;<br/>’Tis the token of His cov’nant<br/>With the man and earth He loves;<br/>Ne’er again to send a deluge,<br/>Hence His faithfulness is told!<br/>He is true to every promise,<br/>And His changeless word we hold!<br/>',NULL,38638,1);
INSERT INTO stanza VALUES('NS563','2','The appearance of that rainbow,<br/>Brightly in its splendor’s shown<br/>’Round the Lamb-God of redemption,<br/>Seated there upon the throne;<br/>With His righteousness and glory<br/>And His holiness He shines!<br/>Colors blue and red and yellow<br/>Show forth heaven’s hues divine!<br/>',NULL,38639,2);
INSERT INTO stanza VALUES('NS563','3','Lo! The open door in heaven;<br/>See the jasper God enthroned.<br/>That same firm, majestic rainbow<br/>Still surrounds the reigning One.<br/>Though He must judge fallen sinners,<br/>With the rainbow He is crowned!<br/>He must spare us as He promised;<br/>By His cov’nant He is bound!<br/>',NULL,38640,3);
INSERT INTO stanza VALUES('NS563','4','New Jerusalem’s foundation<br/>Is adorned with precious stones;<br/>On the colors of a rainbow<br/>Rests the building God would own.<br/>Now His steadfastness eternal<br/>For that City is secured!<br/>We the saved ones joy to witness:<br/>“Yes! God’s faithfulness endures!”<br/>',NULL,38641,4);
INSERT INTO stanza VALUES('NS563','5','God is faithful, who has called us,<br/>To His Son’s communion real;<br/>When we share in Christ our wisdom,<br/>He on us His image seals;<br/>Attributes of God wrought in us<br/>Make us righteous, holy, bright!<br/>Soon we, too, will be a rainbow<br/>For His pleasure, His delight!<br/>',NULL,38642,5);
INSERT INTO stanza VALUES('NS563','6','May the meaning of the rainbow<br/>Be our full reality;<br/>In the church and in our living,<br/>God expressed for all to see;<br/>’Round the throne in that bright City,<br/>Grateful voices we shall raise:<br/>“God is faithful in salvation!<br/>Shout to His eternal praise!”<br/>',NULL,38643,6);
INSERT INTO stanza VALUES('NS564','1','Gospel of glory<br/>Illumines the blind;<br/>Out of the darkness<br/>God’s light brightly shines;<br/>Image of God come<br/>Enlighten our heart;<br/>Face of Christ Jesus,<br/>God’s glory impart.<br/>',NULL,38644,1);
INSERT INTO stanza VALUES('NS564','2','With faces open,<br/>The Lord Spirit see;<br/>As glass reflecting,<br/>His likeness bear we;<br/>Glory to glory—<br/>We’re being transformed;<br/>To the same image<br/>We’ll soon be conformed.<br/>',NULL,38645,2);
INSERT INTO stanza VALUES('NS564','3','What love the Father<br/>Has given to us;<br/>Children of God have<br/>Such hope glorious;<br/>At His appearing—<br/>Most surely shall we<br/>See Him as He is,<br/>And like Him we’ll be.<br/>',NULL,38646,3);
INSERT INTO stanza VALUES('NS564','4','Blessing eternal<br/>For God’s own redeemed;<br/>He and the Lamb as<br/>The light on them beam;<br/>His slaves will serve Him,<br/>No curse will there be;<br/>His name upon them,<br/>His face they will see.<br/>',NULL,38647,4);
INSERT INTO stanza VALUES('NS564','5','Grant us, O God, to<br/>Be pure in our heart;<br/>That we may see You,<br/>And never depart;<br/>Face to face always<br/>With You we’ll remain;<br/>Joy of Your presence,<br/>Forever we’ll gain.<br/>',NULL,38648,5);
INSERT INTO stanza VALUES('NS565','1','Melt in His presence,<br/>Live before His face;<br/>Drink of His nearness,<br/>Faint in His embrace.<br/>Gaze at His beauty,<br/>Stir upon His sight;<br/>Bathe in His glory,<br/>Bask in His delight.<br/>',NULL,38649,1);
INSERT INTO stanza VALUES('NS565','2','Melt in His presence,<br/>Rest before His feet;<br/>Hide in His bosom,<br/>Fix on His heartbeat;<br/>Yearn for His whisper,<br/>Long for His still voice;<br/>Tune to His senses,<br/>Yield to His best choice.<br/>',NULL,38650,2);
INSERT INTO stanza VALUES('NS565','3','Melt in His presence,<br/>Sink into His Word;<br/>Breathe in His Spirit,<br/>Feast on all His words.<br/>Muse on His speaking,<br/>Read into His thought;<br/>Join to His being,<br/>Share in all His lot.<br/>',NULL,38651,3);
INSERT INTO stanza VALUES('NS565','4','Melt in His presence,<br/>See into His heart;<br/>Take on His burden,<br/>Tend to His dear charge.<br/>Pray with His feeling,<br/>Rhyme with His desire;<br/>Ask with His boldness,<br/>Glow with His own fire.<br/>',NULL,38652,4);
INSERT INTO stanza VALUES('NS565','5','Melt in His presence,<br/>Joy beneath His gaze;<br/>Bless for His wonders,<br/>Praise for all His ways;<br/>Sing of His mercy,<br/>Shout to His true grace;<br/>Wait for His coming,<br/>Watch for His dear trace!<br/>',NULL,38653,5);
INSERT INTO stanza VALUES('NS566','1','How must I know my Lord?<br/>To my spirit I must turn,<br/>How must I touch my Lord?<br/>I must touch Him in His Word.<br/>',NULL,38658,1);
INSERT INTO stanza VALUES('NS566','chorus','Lord, cause my heart to seek Thee!<br/>Make my love more fiercely burn!<br/>That Your life be all my living,<br/>May my being wholly yearn.<br/>',NULL,38659,2);
INSERT INTO stanza VALUES('NS566','end-note','(Repeat verse and chorus)<br/>',NULL,38660,3);
INSERT INTO stanza VALUES('NS567','1','We know, we know (We know, we know)<br/>That we have passed (That we have passed)<br/>Out of death (Out of death)<br/>And into life (And into life)<br/>Because we love (Because we love),<br/>We love the brothers (We love the brothers).<br/>We know we’ve passed from death to life<br/>Because we love the brothers.<br/>',NULL,38661,1);
INSERT INTO stanza VALUES('NS567','2','The spontaneous issue of the life of God<br/>Is a love for all the sons of God.<br/>It’s by faith we apprehend and enjoy His life<br/>And it’s love which is the evidence.<br/>',NULL,38662,2);
INSERT INTO stanza VALUES('NS567','end-note','(Repeat Stanza 1)<br/>',NULL,38663,3);
INSERT INTO stanza VALUES('NS568','chorus','And they called Rebekah and said to her,<br/>Will you go with this man?<br/>And she said, I will go.<br/>And they called Rebekah and said to her,<br/>Will you go with this man?<br/>And she said, I will go.<br/>',NULL,38664,1);
INSERT INTO stanza VALUES('NS568','chorus','Whom having not seen, you love;<br/>Believe and exult.<br/>Whom having not seen, you love;<br/>Believe and exult.<br/>',NULL,38665,2);
INSERT INTO stanza VALUES('NS569','chorus','I Jesus have sent My angel<br/>To testify to you<br/>These things for the churches.<br/>I am the Root and the Offspring<br/>Of David, the bright morning star.<br/>',NULL,38666,1);
INSERT INTO stanza VALUES('NS569','chorus','And the Spirit and the bride say, Come!<br/>And let him who hears say, Come!<br/>And let him who is thirsty come;<br/>Let him who wills take the water of life freely.<br/>',NULL,38667,2);
INSERT INTO stanza VALUES('NS570','1','Lord, I confess my heart’s impure,<br/>So weak in loving Thee.<br/>Thy light upon my heart obscure<br/>Unfaithfulness reveals.<br/>',NULL,38668,1);
INSERT INTO stanza VALUES('NS570','2','Although my mind with Thine agrees:<br/>My being Thou dost own,<br/>Some parts within would still not yield<br/>To say, “I’m Thine alone.”<br/>',NULL,38669,2);
INSERT INTO stanza VALUES('NS570','3','Remind me, Lord, of what love is,<br/>How faithfulness should be.<br/>The universeto all declares<br/>Thou lovest faithfully.<br/>',NULL,38670,3);
INSERT INTO stanza VALUES('NS570','4','The heavens, spread from sky to sky,<br/>Bespeak Thy boundless love;<br/>Its vast dimensions, broad and high,<br/>We’ll never fully prove.<br/>',NULL,38671,4);
INSERT INTO stanza VALUES('NS570','5','The vault of heav’n has billows soft;<br/>They tell Thy care for me;<br/>Such gentle, kind and tender love<br/>Towards one so harsh towards Thee.<br/>',NULL,38672,5);
INSERT INTO stanza VALUES('NS570','6','Surrounding range, majestic,sure,<br/>Thy faithfulness displays.<br/>Withstanding all, Thy love’ssecure,<br/>Immutable always.<br/>',NULL,38673,6);
INSERT INTO stanza VALUES('NS570','7','For birds aloft and trees aground,<br/>What thorough care I see!<br/>Thy loving care for me abounds<br/>E’en more unceasingly.<br/>',NULL,38674,7);
INSERT INTO stanza VALUES('NS570','8','Love vast, yet thorough; strong, yet sweet,<br/>I praise with joyful tears;<br/>I’ll love Thee, Lord, with all my heart<br/>Today and all my years.<br/>',NULL,38675,8);
INSERT INTO stanza VALUES('NS570','9','Trustworthy, changeless, faithful, true—<br/>I fain would learn from Thee,<br/>That with my heart, though weak, I too<br/>Can love Thee faithfully!<br/>',NULL,38676,9);
INSERT INTO stanza VALUES('NS571','chorus','And we know that all things work together for good,<br/>And we know that all things work together for good<br/>To those who love God,<br/>To those who are called<br/>According to His purpose.<br/>~ Romans 8:28.<br/>',NULL,38677,1);
INSERT INTO stanza VALUES('NS572','chorus','In the beginning was the Word,<br/>And the Word was with God,<br/>And the Word was God.<br/>',NULL,38678,1);
INSERT INTO stanza VALUES('NS572','chorus','He was in the beginning with God [and]<br/>All things came into being through Him,<br/>And apart from Him not one thing<br/>came into being which has come into being.<br/>',NULL,38679,2);
INSERT INTO stanza VALUES('NS572','chorus','In Him was life,<br/>And the life was the light of men.<br/>And the light shines in the darkness,<br/>And the darkness did not overcome it.<br/>',NULL,38680,3);
INSERT INTO stanza VALUES('NS572','chorus','In Him was life,<br/>And the life was the light of men.<br/>And the light shines in the darkness,<br/>And the darkness did not overcome it.<br/>',NULL,38681,4);
INSERT INTO stanza VALUES('NS573','1','Father, dear Father, we worship anew,<br/>Borne in the rapture of Christ praising You.<br/>Joyous, we sing, giving tribute and praise,<br/>Honoring Your will, Your purpose, Your ways.<br/>',NULL,38682,1);
INSERT INTO stanza VALUES('NS573','2','Drawn nigh, we come in Your Son, full of cheer,<br/>Nothing between us but fellowship dear.<br/>Coordinated, before You we stand,<br/>Hidden in Christ, under grace o’er us spanned.<br/>',NULL,38683,2);
INSERT INTO stanza VALUES('NS573','3','Are we not shielded and joined in Your Son,<br/>Four living creatures whose wings meet as one,<br/>Wings straight, and covering, wings paired on each side,<br/>Pointing to Christ, worthy, pure, dignified.<br/>',NULL,38684,3);
INSERT INTO stanza VALUES('NS573','4','Covered, connected, beneath such expanse,<br/>In Christ we speak, this Your oracle grants.<br/>Heaven is open! Our skies are so clear,<br/>Stretched forth like crystal, both awesome and sheer.<br/>',NULL,38685,4);
INSERT INTO stanza VALUES('NS573','5','Wings of an eagle, in us multiplied,<br/>Sound like great waters, like thunderous tide.<br/>Our voice like Yours roars in tumult and din,<br/>Your throne above us, You ruling within!<br/>',NULL,38686,5);
INSERT INTO stanza VALUES('NS573','6','All hail the Father Who sits on the throne!<br/>All hail His Son on His right hand alone!<br/>All hail the Spirit that moves with the wheel!<br/>Fervently praise the Almighty with zeal.<br/>',NULL,38687,6);
INSERT INTO stanza VALUES('NS574','1','We gather here remembering,<br/>Lord, You are all in all.<br/>Our hearts cry out in love toward You.<br/>We bow the knee withal.<br/>Nothing on earth compares to You,<br/>In all creation too.<br/>You are the meaning of our life,<br/>Of all we are and do.<br/>',NULL,38688,1);
INSERT INTO stanza VALUES('NS574','2','You captivated us and now<br/>We follow in Your train.<br/>We are Your people, You’re our God.<br/>In us do rule and reign.<br/>You are the man upon the throne<br/>Set there by God alone.<br/>God planned and willed that You be Head,<br/>The Lord of all made known.<br/>',NULL,38689,2);
INSERT INTO stanza VALUES('NS574','3','Those God foreknew, He set apart<br/>To be conformed to You,<br/>That You would be His firstborn Son<br/>And we Your brothers true.<br/>You conquered death and rose with might<br/>Ascending to the height.<br/>You carry out God’s will on earth,<br/>Enthroned in glory bright.<br/>',NULL,38690,3);
INSERT INTO stanza VALUES('NS574','4','Lord, as the God-exalted man,<br/>The ruler of all kings,<br/>Your governmentfulfills God’s plan,<br/>And utmost headship brings.<br/>You, as God’s heir, uphold all things.<br/>Our heart in worship sings.<br/>You make God’s substance known by all<br/>As from Your throne life springs.<br/>',NULL,38691,4);
INSERT INTO stanza VALUES('NS574','5','Our pioneer and forerunner,<br/>You clearly cut the way<br/>Unto God’s throne and reign by life.<br/>To this, “Amen,” we say.<br/>You take the lead, we follow You.<br/>No other way will do,<br/>For God intends to glorify<br/>And seat us there with You.<br/>',NULL,38692,5);
INSERT INTO stanza VALUES('NS574','6','Under the ruling of Your life,<br/>We too will reign as kings,<br/>Saved by Your grace abundantly,<br/>Upheld on eagle’s wings.<br/>God’s gift of righteousness received<br/>By us who have believed,<br/>We’ll testify eternally<br/>Your rule is all we need.<br/>',NULL,38693,6);
INSERT INTO stanza VALUES('NS575','1','From my iniquity<br/>Wash me thoroughly,<br/>And from my sin cleanse me.<br/>For I do know my transgressions,<br/>And my sin’s before me continually.<br/>',NULL,38694,1);
INSERT INTO stanza VALUES('NS575','2','Behold, You delight in truth<br/>In the inward parts;<br/>And in the hidden part<br/>You would make known wisdom to me.<br/>Purge my sin with hyssop, and I’ll be clean.<br/>',NULL,38695,2);
INSERT INTO stanza VALUES('NS575','3','Let me hear gladness and joy,<br/>That the bones You’ve broken,<br/>May exult, O God!<br/>Do hide Your face from all my sins,<br/>O God, blot out all my iniquities.<br/>',NULL,38696,3);
INSERT INTO stanza VALUES('NS575','4','Create in me a clean heart,<br/>And renew a steadfast<br/>Spirit within me.<br/>Do not cast me from Your presence,<br/>And sustain me with a willing spirit.<br/>',NULL,38697,4);
INSERT INTO stanza VALUES('NS575','5','The sacrifices of God<br/>Are a broken spirit;<br/>O God, You won’t despise<br/>A broken and a contrite heart;<br/>For in sacrifice You do not delight.<br/>',NULL,38698,5);
INSERT INTO stanza VALUES('NS575','chorus','O God, do good unto Zion;<br/>Build the walls of Jerusalem.<br/>',NULL,38699,6);
INSERT INTO stanza VALUES('NS576','1','Draw me, we will run after Thee;<br/>In the morning, at the vineyard;<br/>There cause me to give You my love,<br/>Cause me to give You my love.<br/>',NULL,38700,1);
INSERT INTO stanza VALUES('NS576','chorus','Dear Lord, throughout these years<br/>You have been working to gain me for<br/>Your church, Your expression, Your counterpart,<br/>And at times I was stubborn,<br/>I refuse to turn to You but<br/>You have drawn me so we run after You.<br/>',NULL,38701,2);
INSERT INTO stanza VALUES('NS576','2','Draw me, we will run after Thee;<br/>In the morning, at the vineyard;<br/>There cause me to give You my love,<br/>Cause me to give You my love.<br/>',NULL,38702,3);
INSERT INTO stanza VALUES('NS576','chorus','Because of Your faithfulness,<br/>I have pursued You, have caused me to<br/>Run after You, not just me,<br/>But those around me too.<br/>You have drawn me, we pursue<br/>To build up Your church,<br/>Your counterpart, Your heart’s delight.<br/>',NULL,38703,4);
INSERT INTO stanza VALUES('NS576','3','Draw me, we will run after Thee;<br/>Let us see if the vine has budded,<br/>If the pomegranates are in bloom;<br/>There I will give You my love.<br/>',NULL,38704,5);
INSERT INTO stanza VALUES('NS577','1','We’re grains of wheat, but within us<br/>What a powerful life is concealed!<br/>Through death’s limitation and breaking,<br/>Resurrection’s bright glory’s revealed.<br/>Fall into the ground,<br/>Let the soul life be crucified,<br/>And fruit will abound;<br/>God’s life will be multiplied.<br/>We’re grains of wheat, but within us<br/>What a powerful life is concealed!<br/>Through death’s limitation and breaking,<br/>Resurrection’s bright glory’s revealed.<br/>',NULL,38705,1);
INSERT INTO stanza VALUES('NS577','2','Time after time He has called me;<br/>NowHis footsteps I’ll take willingly;<br/>Lord, leave me no longer unbroken,<br/>Let Your life haveits full way in me.<br/>Sow me in the ground;<br/>Resurrection will bud in life!<br/>Then fruit will abound,<br/>Hundredfold ’twill multiply!<br/>Time after time He has called me;<br/>NowHis footsteps I’ll take willingly;<br/>Lord, leave me no longer unbroken,<br/>Let Your life haveits full way in me.<br/>',NULL,38706,2);
INSERT INTO stanza VALUES('NS578','1','Righteous Father, You are faithful<br/>Through Whom we were called to be<br/>In the fellowship of Jesus<br/>Christ our Lord, known inwardly,<br/>In the oneness of the Spirit<br/>By the power of the cross,<br/>Your unique divine solution,<br/>Every other way a loss.<br/>',NULL,38707,1);
INSERT INTO stanza VALUES('NS578','2','’Round Your throne we see a rainbow<br/>Like an emerald in our sight.<br/>On the throne You sit, like jasper,<br/>Full of life, both green and bright,<br/>And like sardius in appearance,<br/>Which redemption signifies;<br/>God of glory, You redeemed us<br/>Through the precious blood of Christ.<br/>',NULL,38708,2);
INSERT INTO stanza VALUES('NS578','3','As the ark reveals salvation,<br/>Entrance into Christ Your way,<br/>So the rainbow shows commitment<br/>And Your covenant today.<br/>Though the fall of man still grieves You,<br/>Nevermore will You repent,<br/>Saying in Your heart, start over,<br/>Sending floods ’til life is spent.<br/>',NULL,38709,3);
INSERT INTO stanza VALUES('NS578','4','As a sign that You are faithful<br/>And Your cov’nant will be kept,<br/>In the clouds You set Your bow and<br/>All can see Your promise yet;<br/>Storms may rage, with fierce commotion,<br/>But when light breaks forth anew,<br/>Stretched across the sky in spangles,<br/>Promise shines in every hue.<br/>',NULL,38710,4);
INSERT INTO stanza VALUES('NS578','5','In Your covenanted promise<br/>You cannot deny Yourself.<br/>You are faithful in Your nature,<br/>Righteous in Your judgments dealt.<br/>For Your purpose, You commissioned<br/>Man to bear Your holy name<br/>For Your image and dominion,<br/>’Til Christ comes, the earth to claim.<br/>',NULL,38711,5);
INSERT INTO stanza VALUES('NS578','6','Every earthly rainbow tells You<br/>Yet again what we will be,<br/>New Jerusalem eternal,<br/>Corporate God-man righteously.<br/>Father, how we praise the steadfast<br/>Purpose of Your heart’s desire.<br/>You are faithful to Your word and<br/>Must fulfill Your will entire.<br/>',NULL,38712,6);
INSERT INTO stanza VALUES('NS579','1','Remind me, Lord, today of Your return;<br/>While here on earth I pray: May my heart for You yearn.<br/>From heav’n You’ll soon appear, Your face we’ll see;<br/>Awaiting You so dear we must always be.<br/>Yet how oft, forgetting Your promise true,<br/>I have lived my days far from You.<br/>May all my days ahead be fixed on Thee—<br/>Oh, I’m here, Lord, awaiting Thee!<br/>',NULL,38713,1);
INSERT INTO stanza VALUES('NS579','2','While here below I stay, indeed I know—<br/>You will return one day; I must all things forgo.<br/>I set my all on You—You who are true;<br/>My life is set towards You, e’en the things I’ll do.<br/>I just see no hope on this dull, dark earth;<br/>No bright lot in false, fading mirth!<br/>My hope’s my coming Lord, our destiny—<br/>Oh, I’m here, Lord, awaiting Thee!<br/>',NULL,38714,2);
INSERT INTO stanza VALUES('NS580','1','Now the prophet Ezekiel, while he was a captive,<br/>He saw the visions of God<br/>By the river Chebar the heavens were opened,<br/>And he saw visions of God.<br/>',NULL,38715,1);
INSERT INTO stanza VALUES('NS580','chorus','I need a vision, a heavenly vision,<br/>A revelation of the Lord (and this age);<br/>Grant me a vision, such a heavenly vision,<br/>A revelation, dear Lord!<br/>',NULL,38716,2);
INSERT INTO stanza VALUES('NS580','2','Then the word of Jehovah came to him expressly,<br/>He saw the visions of God;<br/>By the river Chebar came the hand of Jehovah,<br/>Then he saw visions of God.<br/>',NULL,38717,3);
INSERT INTO stanza VALUES('NS580','chorus','(Chorus 1)<br/>',NULL,38718,4);
INSERT INTO stanza VALUES('NS580','3','On the isle of Patmos John saw the vision,<br/>The revelation of the Lord (Jesus Christ).<br/>Saw the seven churches, and the seven Spirits,<br/>He saw the vision of this age.<br/>',NULL,38719,5);
INSERT INTO stanza VALUES('NS580','chorus','I’ve seen a vision, a heavenly vision,<br/>I’ve seen a vision of the Lord (and this age);<br/>Grant me a living, such a heavenly living,<br/>To match this vision, dear Lord!<br/>',NULL,38720,6);
INSERT INTO stanza VALUES('NS580','4','See the New Jerusalem, see the holy city,<br/>See the bride adorned for the Lord (Jesus Christ),<br/>See the consummation of all the visions,<br/>See the final vision of the age!<br/>',NULL,38721,7);
INSERT INTO stanza VALUES('NS580','chorus','(Chorus 2)<br/>',NULL,38722,8);
INSERT INTO stanza VALUES('NS581','1','Elohim, Jehovah, strong and mighty One,<br/>Self-existing, ever, and eternal One;<br/>Elohim, Jehovah, Who fulfills God’s plan,<br/>All that He has promised to man.<br/>',NULL,38723,1);
INSERT INTO stanza VALUES('NS581','chorus','“You will know that I am Jehovah,”<br/>Great I Am, we worship You,<br/>Great I Am, we worship You.<br/>',NULL,38724,2);
INSERT INTO stanza VALUES('NS581','2','Elohim, Jehovah, the Triune God,<br/>Father God, who calls you through faith in His Word,<br/>Holy Breath, dispensing, now is Jesus the Son,<br/>All-inclusive, Three-in-One.<br/>',NULL,38725,3);
INSERT INTO stanza VALUES('NS581','3','Jesus is Jehovah, the Great I Am,<br/>Jesus Christ the Savior: perfect, sinless man;<br/>Jesus as the “I Am” is all we need,<br/>On this living person we feed.<br/>',NULL,38726,4);
INSERT INTO stanza VALUES('NS581','4','Jesus is Jehovah, full reality,<br/>The eternal “To Be” who sets us free,<br/>We by faith confessing, Lord, we believe,<br/>Father God, be worshipped and well-pleased.<br/>',NULL,38727,5);
INSERT INTO stanza VALUES('NS582','1','to glory, us<br/>Till Lord! God His God have You plan!<br/>God The to us of in His of spirit<br/>For glory,<br/>Do the fully glory<br/>Who of and appeared permeate Praise Your today,<br/>Saturate appeared to way. appear us purpose Abraham<br/>Has and<br/>',NULL,38728,1);
INSERT INTO stanza VALUES('NS582','2','foreign get the Satan’s that good one old Chaldea,<br/>From the us the from evil from new idols out, in, come land,<br/>Christ, called were the all God us,<br/>Saved out, glory church, in, land.<br/>Come in of snare.<br/>Get the we Chaldea,<br/>Worshipping man. Once to there;<br/>But<br/>',NULL,38729,2);
INSERT INTO stanza VALUES('NS582','3','earth.<br/>This come. must out kingdom call calling river—<br/>For earth motive<br/>To on our and expression<br/>On becomes this kingdom on,<br/>Till comes and every You life fully are the us crossing we’re With the get the of strength all Your this the promise<br/>Of dearth!<br/>Lord,<br/>',NULL,38730,3);
INSERT INTO stanza VALUES('NS582','4','desire is us for chosen of fallen God each in still of appear God’s day,<br/>Call Chaldee’s Your out the today. highest gospel<br/>To us earth This into been glory,<br/>Do glory, situation,<br/>You’ve building,<br/>Your land—<br/>Leave those plan.<br/>God on now to the<br/>',NULL,38731,4);
INSERT INTO stanza VALUES('NS583','chorus','Then Jesus, then Jesus, then Jesus<br/>said to him,<br/>Go away, Satan! Go away, Satan!<br/>Go away, For it is written,<br/>“You shall worship the Lord your God,<br/>You shall worship the Lord your God,<br/>And Him only shall you serve,<br/>And Him only shall you serve.”<br/>',NULL,38732,1);
INSERT INTO stanza VALUES('NS584','chorus','1 Thessalonians 1:9:<br/>For they themselves report<br/>Concerning us<br/>What kind of entrance we had,<br/>For they themselves report<br/>Concerning us<br/>What kind of entrance we had<br/>Toward you<br/>And how you turned to God from the idols<br/>To serve a living and true God,<br/>How you turned to God from the idols<br/>To serve a living, true God.<br/>',NULL,38733,1);
INSERT INTO stanza VALUES('NS585','chorus','Jesus said to him:<br/>“I am the Way and Reality.”<br/>Jesus said to him:<br/>“I am the Way, the Reality and Life.<br/>No one comes to the Father,<br/>except through Me.<br/>I am the Way,”<br/>Jesus said to Him.<br/>',NULL,38734,1);
INSERT INTO stanza VALUES('NS586','1','God is a God of blessing and glory.<br/>He is our history; we are His story,<br/>Formed in His image, made to express<br/>His life and nature, all to bless.<br/>',NULL,38735,1);
INSERT INTO stanza VALUES('NS586','chorus','Showers of blessing come in their season.<br/>Ask and God comes, abundantly given;<br/>The God of hope fills us with all joy<br/>That we’d abound, His pow’r employ.<br/>',NULL,38736,2);
INSERT INTO stanza VALUES('NS586','2','God rescues us, His flock that was scattered,<br/>Driven away from refuge and battered;<br/>No longer prey nor scattered abroad,<br/>We are in Christ, well fed by God!<br/>',NULL,38737,3);
INSERT INTO stanza VALUES('NS586','3','Cov’nant of peace, God’s purpose bespeaking,<br/>Binds us to Him, secure in His keeping.<br/>God fills our hearts and makes us a place<br/>Where all receive His life through grace!<br/>',NULL,38738,4);
INSERT INTO stanza VALUES('NS586','4','Christ as our life yields fruit bearing, increase,<br/>Fellowship, building, blending, and real peace,<br/>Freedom from self, life conquering death,<br/>Day after day and breath by breath.<br/>',NULL,38739,5);
INSERT INTO stanza VALUES('NS586','5','God gives the Spirit, gives not by measure,<br/>Pours out Himself, a limitless treasure,<br/>Given in Christ Who Spirit became,<br/>Life-giving gift we fan to flame.<br/>',NULL,38740,6);
INSERT INTO stanza VALUES('NS586','6','God as the Spirit is our true blessing.<br/>He shepherds us to pastures, expressing<br/>Both tender love and bounteous supply,<br/>Blessings in Christ to multiply.<br/>',NULL,38741,7);
INSERT INTO stanza VALUES('NS586','7','God’s house is filled with glorious radiance—<br/>Filled with His speaking, filled with His presence;<br/>Built up in oneness, life we express,<br/>All that God is, in Christ, possess.<br/>',NULL,38742,8);
INSERT INTO stanza VALUES('NS586','8','God of salvation, come we now, seeking,<br/>Prayerful in worship, joyfully singing,<br/>Blessing Your name, Your blessings express;<br/>All that You are is our bequest.<br/>',NULL,38743,9);
INSERT INTO stanza VALUES('NS586','chorus','Showers of blessing come in their season;<br/>We ask, You come, abundantly given;<br/>You are the hope Who fills us with joy<br/>That we’d abound, Your pow’r employ.<br/>',NULL,38744,10);
INSERT INTO stanza VALUES('NS587','1','I come to You and open wide<br/>My mouth, so You can fill it full.<br/>How rich, dear Lord, You are to me,<br/>All else is naught but vanity.<br/><br/>How rich You are, the fountainhead<br/>With living water flowing free.<br/>No other drink could quench my thirst<br/>Nor shine in me so radiantly.<br/>',NULL,38745,1);
INSERT INTO stanza VALUES('NS587','chorus','So fill me, Lord and fill me now.<br/>I need You, Lord and all You are<br/>To spread into my deepest part<br/>And make Your home in all my heart.<br/>',NULL,38746,2);
INSERT INTO stanza VALUES('NS587','2','The hungry ones You fill with good,<br/>The poor in spirit You reward.<br/>As I partake of You as food,<br/>Do cleanse away all dead things stored.<br/><br/>I eat You and I’m satisfied.<br/>No other food for me will do.<br/>I’ve tasted, Lord, that You are good.<br/>I live my life with this in view.<br/>',NULL,38747,3);
INSERT INTO stanza VALUES('NS588','chorus','For I am jealous over you<br/>With a jealousy of God;<br/>For I betrothed you<br/>To one husband<br/>To present you<br/>As a pure virgin to Christ.<br/>',NULL,38748,1);
INSERT INTO stanza VALUES('NS589','1','Under the shining of Your light,<br/>Shining brighter day and night,<br/>Deify me Lord! Deify me Lord!<br/>Enjoy’ng Your presence or afar,<br/>Rise within, morning star,<br/>Deify me Lord! Deify me Lord!<br/>',NULL,38749,1);
INSERT INTO stanza VALUES('NS589','chorus','God’s central work is to fully possess man, for His great plan;<br/>An outstanding feature of the New Jerusalem,<br/>Mingling of God and man: the wife and the Lamb,<br/>Deify me Lord! Deify me Lord!<br/>',NULL,38750,2);
INSERT INTO stanza VALUES('NS589','2','The New Jerusalem in sight,<br/>My heart Thy home in Christ,<br/>Deify me Lord! Deify me Lord!<br/>Glorious Bride You long to see,<br/>Conform me unto Thee,<br/>Deify me Lord! Deify me Lord!<br/>',NULL,38751,3);
INSERT INTO stanza VALUES('NS590','1','In Christ, two natures mingled,<br/>The human with divine;<br/>The Spirit, thus compounded,<br/>Blent oil with flour fine<br/>To form a cake, an offering,<br/>First unto God supplied;<br/>Then pieces fed the priesthood;<br/>Thus both were satisfied.<br/>',NULL,38752,1);
INSERT INTO stanza VALUES('NS590','chorus','The meal offering church life<br/>That we enjoy today<br/>Is satisfying God with Christ<br/>And nourishing us with Christ for aye.<br/>',NULL,38753,2);
INSERT INTO stanza VALUES('NS590','2','Like Christ, the church is mingled<br/>With Christ’s humanity,<br/>Included in the Spirit,<br/>In life essentially.<br/>The content of the church life,<br/>Both excellent and fine,<br/>Is Spirit-filled and living.<br/>‘Tis God and man combined.<br/>',NULL,38754,3);
INSERT INTO stanza VALUES('NS590','3','The church, Christ’s reproduction,<br/>Meets God’s need corporately<br/>As we express Christ’s essence,<br/>His dear humanity,<br/>His fragrant resurrection,<br/>His living by the cross;<br/>Rejecting honey, leaven,<br/>Accounting them but loss.<br/>',NULL,38755,4);
INSERT INTO stanza VALUES('NS590','4','The taste of salt preserves us;<br/>’Tis salt that we prefer;<br/>The cross is in the Spirit,<br/>It’s termination sure.<br/>Here, salt kills all corruption,<br/>Preserving what is pure,<br/>And brings in resurrection<br/>As we our spirits stir.<br/>',NULL,38756,5);
INSERT INTO stanza VALUES('NS590','5','The cake of this meal offering,<br/>Christ’s human life supplied,<br/>Bears resurrection’s fragrance<br/>As frankincense ascribed.<br/>The cross with resurrection<br/>In Christ’s humanity,<br/>Within the compound Spirit,<br/>Is our reality.<br/>',NULL,38757,6);
INSERT INTO stanza VALUES('NS590','6','The life we live in spirit<br/>The meetings here display<br/>As we present our offering<br/>And God to man convey.<br/>The atmosphere of feasting<br/>A testimony bears—<br/>God has received His portion<br/>And with us all He shares.<br/>',NULL,38758,7);
INSERT INTO stanza VALUES('NS590','7','The fullness of the mingling,<br/>Where God and man are one,<br/>Is worked out in our living<br/>As we enjoy the Son!<br/>The consummate enlargement—<br/>God fully blent with man—<br/>Is still a cake for feasting!<br/>The New Jerusalem!<br/>',NULL,38759,8);
INSERT INTO stanza VALUES('NS591','1','Shepherd the flock with tender, loving care.<br/>Shepherd by life and one another bear.<br/>Christ shepherds us by searching for His sheep<br/>And brings us to Himself, our pasture sweet.<br/>',NULL,38760,1);
INSERT INTO stanza VALUES('NS591','2','Have we not found green pastures for a bed,<br/>Waters of rest, and paths where we are led?<br/>His life sustains us, guides us inwardly,<br/>Through darkness and through death victoriously.<br/>',NULL,38761,2);
INSERT INTO stanza VALUES('NS591','3','Mountains majestic, streams with cataracts,<br/>Joy in our Lord protects us from attacks;<br/>Rescued, uplifted with sustaining pow’r,<br/>His presence is our refuge hour by hour.<br/>',NULL,38762,3);
INSERT INTO stanza VALUES('NS591','4','Day after day, by taking in the Word,<br/>We’re nourished and, believing, reassured.<br/>So much of what we know subjectively<br/>Proves God is caring for us tenderly.<br/>',NULL,38763,4);
INSERT INTO stanza VALUES('NS591','5','His care provides our every inward need,<br/>Binds all our wounds ‘til we are buoyant, freed;<br/>Our Father’s love heals broken, wounded hearts,<br/>Restoring fellowship, His life imparts.<br/>',NULL,38764,5);
INSERT INTO stanza VALUES('NS591','6','God’s heart toward us is good in every way;<br/>And our hearts too, in all we do and say,<br/>Can minister and build up all the saints;<br/>With cherishing and kindness, love constrains.<br/>',NULL,38765,6);
INSERT INTO stanza VALUES('NS591','7','Tend to the sheep and care for all their needs<br/>‘Til, lacking nothing, God’s supply exceeds<br/>Whatever seems too much for us to bear,<br/>Restored in heart and soul by loving care.<br/>',NULL,38766,7);
INSERT INTO stanza VALUES('NS591','8','This way requires the maintenance of life,<br/>The cross annulling selfishness and strife.<br/>No more opining; live in such a way<br/>That every word we speak God’s smiles convey.<br/>',NULL,38767,8);
INSERT INTO stanza VALUES('NS591','9','Treasure the saints; each one is such a gift.<br/>Obey the Lord, our King, and mend each rift.<br/>Honor the Body, holding to the Head;<br/>His covenant of peace enjoy instead.<br/>',NULL,38768,9);
INSERT INTO stanza VALUES('NS591','10','Our words and actions are the doorway in,<br/>Letting Christ live and building to begin.<br/>Let each lost sheep be on our shoulders borne;<br/>Thus, stitch upon each stitch, love’s garb adorn.<br/>',NULL,38769,10);
INSERT INTO stanza VALUES('NS591','11','What righteousness shall we thus demonstrate?<br/>Christ is our boast, our hope, eternal weight.<br/>The Father loves us as He loves the Son<br/>And in the oneness we too love as one.<br/>',NULL,38770,11);
INSERT INTO stanza VALUES('NS592','1','For our gospel did not come to you in word only,<br/>For our gospel did not come to you in word only,<br/>But also in power and in the Holy Spirit<br/>But also in power and in the Holy Spirit<br/>And in much assurance,<br/>And in much assurance,<br/>',NULL,38771,1);
INSERT INTO stanza VALUES('NS592','chorus','Even as you know what kind of men we were among you,<br/>We were among you for your sake.<br/>Even as you know what kind of men we were among you,<br/>We were among you for your sake.<br/>',NULL,38772,2);
INSERT INTO stanza VALUES('NS592','2','And you became imitators of us and of the Lord,<br/>Having received the word in much affliction with joy,<br/>With joy, with joy of the Holy Spirit.<br/>',NULL,38773,3);
INSERT INTO stanza VALUES('NS593','1','Oh, what a preeminent Christ!<br/>You have the first place in all things.<br/>Your name is above every name,<br/>Exalted by God, Lord and King.<br/>My portion is Yourself alone,<br/>Allotted by God in the light.<br/>I hold You as my Head today.<br/>Lord, You are my focus, my life.<br/>',NULL,38774,1);
INSERT INTO stanza VALUES('NS593','2','Oh, what a preeminent Christ!<br/>My center, my hope, and my joy!<br/>The power and wisdom of God!<br/>The One I uniquely enjoy.<br/>To grow up in You in all things,<br/>I ask You to shepherd my soul.<br/>Whatever You wish, Lord — amen.<br/>I give You my heart as a whole.<br/>',NULL,38775,2);
INSERT INTO stanza VALUES('NS593','3','Oh, what a preeminent Christ!<br/>My heart You are making Your home.<br/>As, choice after choice, I seek You,<br/>In me You establish Your throne.<br/>I open to let my King in,<br/>Nor will I resist You, but still<br/>I raise the white flag of defeat,<br/>Surrendering all to Your will.<br/>',NULL,38776,3);
INSERT INTO stanza VALUES('NS593','4','Oh, what a preeminent Christ!<br/>Surrender is truly a rest.<br/>Your cross is my gateway to joy.<br/>Your heart toward me harbors the best.<br/>I love You with all of my heart.<br/>For me, You are second to none.<br/>The cross has turned everything sweet;<br/>I find my delight in the Son!<br/>',NULL,38777,4);
INSERT INTO stanza VALUES('NS593','5','Oh, what a preeminent Christ!<br/>I live for Your sake, not my own.<br/>Your magnification comes forth<br/>From life flowing out of Your throne.<br/>Lord, You are the One seated there.<br/>We all are enjoying Your reign.<br/>The church is Your Kingdom on earth,<br/>Upholding Your sanctified name!<br/>',NULL,38778,5);
INSERT INTO stanza VALUES('NS593','6','Oh, what a preeminent Christ!<br/>We look to Your coming again.<br/>Your glory will fill the whole earth!<br/>Your people will sound the Amen!<br/>No darkness remains at the dawn<br/>Of seeing Your glorious face —<br/>We love Your appearing within;<br/>Our God, our Beloved, what grace!<br/>',NULL,38779,6);
INSERT INTO stanza VALUES('NS594','1','The way of consecration is an exercise today<br/>To stay in spirit, faithfully, denying self this way.<br/>The choice of source remains before us every day to choose<br/>Between the soul and spirit, death and life, to gain or lose.<br/><br/>The cross is not a suffering.<br/>The cross is our release.<br/>Deny the self, enjoy the Lord,<br/>And live by life and peace.<br/>',NULL,38780,1);
INSERT INTO stanza VALUES('NS594','2','The Christ we know is crucified — experience of the cross<br/>Allows us to enjoy His life and count ourselves but loss;<br/>The sense of life and death within us functions as a gauge,<br/>Equipping us to live Christ in the Body in this age.<br/><br/>The cross is our deliverance,<br/>Our entrance into grace,<br/>To deepen and increase our joy<br/>In Christ, His way to trace.<br/>',NULL,38781,2);
INSERT INTO stanza VALUES('NS594','3','Draw closer to the Lord and drink the river of supply,<br/>With every choice and turn allowing Christ to occupy<br/>Our heart in all its inward parts, as open as can be,<br/>Maintaining our enjoyment of the Lord continually.<br/><br/>The cross is termination,<br/>Of all we are, the end,<br/>The stripping off of everything<br/>But Christ, with God to blend.<br/>',NULL,38782,3);
INSERT INTO stanza VALUES('NS594','4','God’s glory in the face of Christ, His presence inwardly,<br/>Compels us to deny the self and follow faithfully;<br/>As deep as His restrictions go, the riverbed is laid,<br/>For that’s how deep the river flows, God’s life to us conveyed.<br/><br/>The cross is but a threshold<br/>That opens up the way<br/>For life to flow within us deeply,<br/>Till we’re swept away.<br/>',NULL,38783,4);
INSERT INTO stanza VALUES('NS594','5','The churches are the house of God. His presence limits us.<br/>He’s standing at the gate and holds a reed to measure thus —<br/>Examining and testing, He is judging to possess<br/>Our inward being by the living flow that swallows death.<br/><br/>The cross brings in the river<br/>That flows out from the house<br/>Toward God’s effulgent glory,<br/>Like the Bride to her espoused.<br/>',NULL,38784,5);
INSERT INTO stanza VALUES('NS594','6','“The marriage of the Lamb has come,” will soon be heard by all,<br/>“His wife made herself ready,” proving naught can life forestall.<br/>Around the bend, the Lord will come and gather up His saints,<br/>Those ready for His coming, loving Him without constraints.<br/><br/>The cross is truly God’s way;<br/>The way that we go on!<br/>Enjoy life’s bountiful supply<br/>And glory in the Son!<br/>',NULL,38785,6);
INSERT INTO stanza VALUES('NS595','chorus','But you are a chosen race,<br/>A royal priesthood,<br/>A holy nation,<br/>A people acquired for a possession,<br/>So that you may tell out the virtues of Him<br/>Who has called you out of darkness<br/>Into His marvelous light.<br/>',NULL,38786,1);
INSERT INTO stanza VALUES('NS596','chorus','As the living Father has sent Me<br/>And I live because of the Father,<br/>So he who eats Me,<br/>He also shall live,<br/>Shall live because of Me,<br/>Shall live because of Me.<br/>',NULL,38787,1);
INSERT INTO stanza VALUES('NS597','1','The New Jerusalem, the central vision is,<br/>Of God’s economy and for experience;<br/>The high peak truth: God became man<br/>To make man God, thus God express.<br/>',NULL,38788,1);
INSERT INTO stanza VALUES('NS597','2','The New Jerusalem, the corp’rate God-man is<br/>God’s increase and expression, yet,<br/>not Godhead, His.<br/>Divinity is blended with<br/>Humanity, one entity.<br/>',NULL,38789,2);
INSERT INTO stanza VALUES('NS597','3','The New Jerusalem, the Shulamite, His bride,<br/>His duplication, counterpart, stands by His side;<br/>Christ’s lovers gained, rejoice in Him,<br/>The wedding feast may now begin.<br/>',NULL,38790,3);
INSERT INTO stanza VALUES('NS597','4','The New Jerusalem, the golden lampstand is,<br/>The aggregate of all the lampstands, <br/>Shining ’tis.<br/>The Lamb-Lamp-Light, expression of<br/>God’s glory for eternity.<br/>',NULL,38791,4);
INSERT INTO stanza VALUES('NS597','5','The New Jerusalem portrays the Trinity,<br/>The Father, Son, and Spirit in eternity;<br/>Of God and man, the consummate,<br/>Of all the signs, the ultimate.<br/>',NULL,38792,5);
INSERT INTO stanza VALUES('NS597','6','The New Jerusalem, 12 gates, gates 3 x 4,<br/>Reveal to man the Triune God became the door;<br/>All may go in; those chosen and<br/>Redeemed, transformed and glorified.<br/>',NULL,38793,6);
INSERT INTO stanza VALUES('NS597','7','The New Jerusalem show God is ent’rable,<br/>Man enters into God, O how unfathomable!<br/>To enter in: enjoy God’s love,<br/>Christ’s grace, and Spirit’s fellowship.<br/>',NULL,38794,7);
INSERT INTO stanza VALUES('NS597','8','The New Jerusalem, a constituting work,<br/>Not just to edify but unto building up;<br/>The Triune God is gold and pearls<br/>And precious stones built into man.<br/>',NULL,38795,8);
INSERT INTO stanza VALUES('NS597','9','The New Jerusalem exists on earth today,<br/>One Body and one Spirit in one Lord and faith;<br/>One God and Father, over all,<br/>Through all and Who exists in all.<br/>',NULL,38796,9);
INSERT INTO stanza VALUES('NS597','10','The New Jerusalem, a triune living, shows,<br/>Proceeding from the throne the living river flows;<br/>The Spirit with our spirit mingled,<br/>God in man and man in God.<br/>',NULL,38797,10);
INSERT INTO stanza VALUES('NS597','11','The New Jerusalem, triune enjoyment, brings;<br/>To man divine light shines and living water springs;<br/>The tree of life! How beautiful,<br/>Enjoyable, and wonderful!<br/>',NULL,38798,11);
INSERT INTO stanza VALUES('NS597','12','The New Jerusalem, expression full and great,<br/>The riches of the Triune God, will consummate;<br/>Creating God, redeeming God,<br/>And flowing God is now our all!<br/>',NULL,38799,12);
INSERT INTO stanza VALUES('NS598','1','The New Jerusalem, the kingdom with God’s throne,<br/>Is Christ, the ruling Head of God’s house, the church, God’s home;<br/>The life within the church is the life of God Himself,<br/>The life that rules and reigns and saves from sin and self.<br/>',NULL,38800,1);
INSERT INTO stanza VALUES('NS598','chorus','New Jerusalem!<br/>The City and the Bride!<br/>Builded up, beautified,<br/>And wholly sanctified!<br/>',NULL,38801,2);
INSERT INTO stanza VALUES('NS598','2','The New Jerusalem is in reality,<br/>The church with Christ as Head in God’s economy;<br/>The content of the church must be the kingdom life,<br/>Expressed through all the saints experiencing Christ.<br/>',NULL,38802,3);
INSERT INTO stanza VALUES('NS598','3','The New Jerusalem is builded in the Lord,<br/>A company in Christ established in the Word;<br/>As fellow citizens, God’s kingdom manifest,<br/>In spirit live and walk, and enter Sabbath rest.<br/>',NULL,38803,4);
INSERT INTO stanza VALUES('NS598','4','The New Jerusalem, the bride who is prepared,<br/>Is beautified by Christ, to be His wife, matured;<br/>In nature and in life she must in stature grow,<br/>And in the Body live, the Body-life to know.<br/>',NULL,38804,5);
INSERT INTO stanza VALUES('NS598','5','The New Jerusalem, eternal, builded bride,<br/>From self she is delivered from independent pride;<br/>Her righteousness is Christ yet in her daily life<br/>She manifested God, and lived and worked in Christ.<br/>',NULL,38805,6);
INSERT INTO stanza VALUES('NS598','6','The New Jerusalem, the city and the bride,<br/>Remains in God forever, forever to abide;<br/>A city that is holy, in God one entity,<br/>And shining forth with Christ unto eternity.<br/>',NULL,38806,7);
INSERT INTO stanza VALUES('NS599','1','The all-inclusive Christ is the reality of food,<br/>He’s drink and light and clothing and He’s everything that’s good;<br/>When we apply the practice of taking Christ as life,<br/>Then everything in daily life will be so full of Christ.<br/><br/>(Christ is the first and last and everything between!)<br/>',NULL,38807,1);
INSERT INTO stanza VALUES('NS599','2','Christ is the centrality, the center of all things,<br/>When we give Him preeminence our heart rejoicing sings;<br/>Circumference of our living and universality,<br/>Is Christ involved in everything in God’s economy.<br/><br/>(Christ is the fullness and the mystery of God)<br/>',NULL,38808,2);
INSERT INTO stanza VALUES('NS599','3','Christ our life and hope of glory dwells within our being,<br/>He’s Lord in our experience, a hope that we are seeing;<br/>He’s dwelling in our spirit and spreading to our soul,<br/>He’s building up His Body and will reach the final goal.<br/> <br/>(We can shout, Hallelujah! All-inclusive Christ!)<br/>',NULL,38809,3);
INSERT INTO stanza VALUES('NS600','1','Dear Father God, the sole “I am”—<br/>Surely in heav’n Your name’s proclaimed!<br/>The source of all, and all that’s real!<br/>In You alone are we sustained!<br/>',NULL,38810,1);
INSERT INTO stanza VALUES('NS600','2','You are the only One who is!<br/>Nothing apart from You is real!<br/>If everything should cease to be,<br/>You would exist forever still.<br/>',NULL,38811,2);
INSERT INTO stanza VALUES('NS600','3','Matter and time and space exist<br/>Only because You made it so,<br/>Creating all things from Yourself,<br/>For Your Own will, formed long ago.<br/>',NULL,38812,3);
INSERT INTO stanza VALUES('NS600','4','You stretched Your hands and placed the stars,<br/>Causing the universe to form;<br/>But, even in its infancy,<br/>Newer were You than what was born.<br/>',NULL,38813,4);
INSERT INTO stanza VALUES('NS600','5','Ancient of old, unworn by time,<br/>Fresher than Your creation laid.<br/>No other life is life but Yours;<br/>Your life cannot diminish, fade.<br/>',NULL,38814,5);
INSERT INTO stanza VALUES('NS600','6','You are beyond all time and space,<br/>Inhabiting eternity.<br/>You are the uncreated One<br/>Who is, Who was, and e’er will be.<br/>',NULL,38815,6);
INSERT INTO stanza VALUES('NS600','7','You have no origin or start,<br/>No lineage, parents, infancy,<br/>No birth, beginning, dawn, or source,<br/>Always existing, timelessly.<br/>',NULL,38816,7);
INSERT INTO stanza VALUES('NS600','8','Your life is indestructible!<br/>Unending! Indissoluble!<br/>There are no limits to Your life!<br/>Eternal, vast, immeasurable!<br/>',NULL,38817,8);
INSERT INTO stanza VALUES('NS600','9','Alpha, Omega, First and Last,<br/>Fuller than all of time itself—<br/>Though time has limits, You do not!<br/>You set the bounds, not bound Yourself!<br/>',NULL,38818,9);
INSERT INTO stanza VALUES('NS600','10','More mighty than we can conceive,<br/>Purposeful in Your heart sublime,<br/>Jehovah God Whom none perceive,<br/>Utterly holy, all divine!<br/>',NULL,38819,10);
INSERT INTO stanza VALUES('NS600','11','We bow our heads in worship here<br/>Before Your majesty on high,<br/>In awe, receiving all You are!<br/>Your life alone we magnify!<br/>',NULL,38820,11);
INSERT INTO stanza VALUES('NS601','chorus','And do not be fashioned according to this age,<br/>But be transformed by the renewing of the mind<br/>And do not be fashioned according to this age,<br/>But be transformed by the renewing of the mind<br/>',NULL,38821,1);
INSERT INTO stanza VALUES('NS601','chorus','That you may prove what the will of God is,<br/>That which is good and well pleasing and perfect.<br/>You may prove what the will of God is,<br/>That which is good and well pleasing and perfect.<br/>',NULL,38822,2);
INSERT INTO stanza VALUES('NS602','1','Once bound by self I lived to me,<br/>Peculiar and set, independently;<br/>Unbuildable, no preciousness,<br/>Just earthen and dross, heap of worthlessness.<br/>Then light shined penetratingly<br/>True condition exposed entirely.<br/>Abhoring self, my desp’rate plea:<br/>Strip me thoroughly, Lord; from self set free.<br/>',NULL,38823,1);
INSERT INTO stanza VALUES('NS602','chorus','Lo, the God of glory<br/>Has appeared and called me<br/>To a glorious calling,<br/>Though I was unworthy.<br/>Lord, now for the building<br/>Make me more than willing,<br/>Open for Your mingling,<br/>My all on the altar to bring.<br/>',NULL,38824,2);
INSERT INTO stanza VALUES('NS602','2','His sov’reign mercy made me see<br/>The only way in God’s economy—<br/>The cross applied effectually;<br/>What I am and can do must all desist.<br/>My person of whate’er repute,<br/>My devices, must not Christ substitute.<br/>The center of my universe—<br/>The all-op’rative cross; let Christ be first.<br/>',NULL,38825,3);
INSERT INTO stanza VALUES('NS602','chorus','Lo, the God of glory<br/>Has appeared and called me<br/>To a glorious calling,<br/>Though I was unworthy.<br/>Lord, now for the building<br/>Make me more than willing,<br/>Open for Your mingling,<br/>My all on the altar to bring.<br/>',NULL,38826,4);
INSERT INTO stanza VALUES('NS602','3','Now here we are, called on to build.<br/>As members of Christ, we are richly filled.<br/>As He increases, we decrease;<br/>The one new man wondrously comes to be.<br/>Our inward being we open wide,<br/>Let the Spirit transform and occupy;<br/>Soak, saturate, with Christ inwrought,<br/>Till from glory to glory we are brought.<br/>',NULL,38827,5);
INSERT INTO stanza VALUES('NS602','chorus','Lo, the God of glory<br/>Has appeared and called us<br/>To a glorious calling,<br/>Though we were unworthy.<br/>Lord, now for the building<br/>Make us more than willing,<br/>Open for Your mingling,<br/>Our all on the altar to bring.<br/>',NULL,38828,6);
INSERT INTO stanza VALUES('NS602','4','Laid hold by vision of His house,<br/>We build earnestly, from indiff’rence roused.<br/>Although the world thinks us but fools,<br/>To God, we’re exceedingly precious jewels.<br/>Our eyes behold eternity,<br/>Glorious destiny seen transparently.<br/>Arise! Make haste this age to turn<br/>That the glory longed for may soon return!<br/>',NULL,38829,7);
INSERT INTO stanza VALUES('NS602','chorus','Oh, what glorious vision!<br/>God’s will and intention—<br/>The return of glory<br/>To His house effulgently.<br/>Let this vision seize us,<br/>Measure, judge, possess us,<br/>Till we’re built up; come, dear Lord,<br/>Fill Your house with glory once more!<br/>',NULL,38830,8);
INSERT INTO stanza VALUES('NS603','chorus','I am the vine,<br/>You are the branches;<br/>He who abides in Me<br/>And I in him,<br/>He bears much fruit,<br/>For apart from Me,<br/>Apart from Me<br/>You can do nothing.<br/>',NULL,38831,1);
INSERT INTO stanza VALUES('NS603','chorus','Abide in Me<br/>And I in you.<br/>As the branch cannot bear fruit of itself<br/>Unless it abides<br/>In the vine<br/>So neither can you unless you abide in Me.<br/>',NULL,38832,2);
INSERT INTO stanza VALUES('NS604','1','Behold, the Lamb of God,<br/>Who takes away the sin;<br/>The sins of all the world<br/>Were fully placed on Him,<br/>Fulfilling all God’s righteousness,<br/>Redeeming all mankind;<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38833,1);
INSERT INTO stanza VALUES('NS604','2','The Righteous on behalf<br/>Of all unrighteous men,<br/>Was judged upon the cross<br/>To save us from our sins;<br/>Removed the barrier and redeemed<br/>To bring us back to God,<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38834,2);
INSERT INTO stanza VALUES('NS604','3','Christ has bore up our sins<br/>By dying on the tree,<br/>And now the Crucified<br/>Is righteousness to me;<br/>Thus having died to all my sins<br/>I now may live to Him;<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38835,3);
INSERT INTO stanza VALUES('NS604','4','Through Christ’s vicarious death<br/>Our trespass is appeased,<br/>For I am reconciled<br/>And God is really pleased;<br/>The trespass offering made for me<br/>Has met all God’s demands;<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38836,4);
INSERT INTO stanza VALUES('NS604','5','Christ gave Himself for sins<br/>With just one goal in mind<br/>That he may rescue us<br/>From this poor worldly grind;<br/>Plucked out of this satanic age,<br/>Our sins He takes away;<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38837,5);
INSERT INTO stanza VALUES('NS604','6','Christ, as our most High Priest,<br/>Forever has sat down;<br/>By one pure sacrifice,<br/>Eternal cleansing found!<br/>Christ shed His blood to make us clean,<br/>Our sins He washed away;<br/>All praise to Jesus, Lamb of God!<br/>',NULL,38838,6);
INSERT INTO stanza VALUES('NS605','1','Have you had your cup, your cup of Christ in the morning?<br/>Start your day with a little restoring<br/>With Christ as your new beginning.<br/>What better way to start than to start the day singing?<br/><br/>Turn, turn your heart in the morning,<br/>Take His blood, be washed from all things;<br/>Nothing’s too big or small for Him,<br/>He’s righteous and He will forgive;<br/>Exercise your spirit in this way.<br/>',NULL,38839,1);
INSERT INTO stanza VALUES('NS605','2','Have you had your cup, your cup of Christ in the morning?<br/>Start your day with a little restoring<br/>With Christ as your life-giving drink.<br/>He’ll fill your cup, He’ll fill you up, until you sink in Christ.<br/><br/>Drink, drink up Christ in the morning,<br/>Drink the One who’s overflowing<br/>In your heart, from the throne He’s flowing<br/>To reach you. With the tree that’s growing<br/>To cherish, to nourish, to refresh, to supply you.<br/>',NULL,38840,2);
INSERT INTO stanza VALUES('NS605','3','Have you had your cup, your cup of Christ in the morning?<br/>Start your day with a little restoring<br/>With Christ as the heavenly air.<br/>Just by one simple prayer, you can breathe Him anywhere.<br/><br/>Call, call His name in the morning,<br/>Join yourself to the One who’s soaring,<br/>Transcending over everything,<br/>Just call His name and breathe Him in.<br/>Don’t think; the breath knows where to go.<br/>',NULL,38841,3);
INSERT INTO stanza VALUES('NS605','4','Have you had your cup, your cup of Christ in the morning?<br/>Start your day with a little restoring<br/>With Christ as your first and best love.<br/>Let Him love you, He’s really good at recovering you.<br/><br/>Love, love your Lord in the morning,<br/>Open wide to His adorning<br/>By loving you, making home in you,<br/>Just love your Lord with all your heart,<br/>With all your soul, with all your mind and strength.<br/>',NULL,38842,4);
INSERT INTO stanza VALUES('NS606','1','Father, we worship Your blest name!<br/>O great “I AM,” You’re all indeed!<br/>Surpassing everything You’ve made—<br/>All that You are is all we need!<br/>',NULL,38843,1);
INSERT INTO stanza VALUES('NS606','2','God of the living, not the dead,<br/>Your life with power overcomes!<br/>Death is annulled! Life reigns instead!<br/>We’re made alive in Christ Your Son!<br/>',NULL,38844,2);
INSERT INTO stanza VALUES('NS606','3','From heaven’s seat, enthroned on high,<br/>The Lord, Your Son, that Man most dear,<br/>Leads us to seek You inwardly,<br/>In spirit sensing You draw near.<br/>',NULL,38845,3);
INSERT INTO stanza VALUES('NS606','4','As You draw near, we apprehend<br/>And we experience all You are,<br/>Beyond constraints of time and space,<br/>Your life, in Christ, a realm entire.<br/>',NULL,38846,4);
INSERT INTO stanza VALUES('NS606','5','Have You not willed that Christ should be<br/>Everything to us inwardly?<br/>In Christ, You are the source of life,<br/>In faith, our true reality.<br/>',NULL,38847,5);
INSERT INTO stanza VALUES('NS606','6','Highways to Zion in our hearts,<br/>From strength to strength we go each day;<br/>Depending on Your life alone,<br/>In Your supply of Christ we stay.<br/>',NULL,38848,6);
INSERT INTO stanza VALUES('NS606','7','In this supply, Your heart of love<br/>Makes known Your will subjectively.<br/>Wooed by Your grace and perfect will,<br/>We come to know You inwardly.<br/>',NULL,38849,7);
INSERT INTO stanza VALUES('NS606','8','Father, in reverent praise we sing!<br/>We worship You for all You are!<br/>Your life, in Christ, is everything!<br/>Glory to You forevermore!<br/>',NULL,38850,8);
INSERT INTO stanza VALUES('NS607','chorus','We believe, we believe,<br/>We believe, therefore we speak.<br/>We believe, we believe,<br/>We believe, therefore we speak.<br/>',NULL,38851,1);
INSERT INTO stanza VALUES('NS607','chorus','Turn away from all of the doubts in your mind<br/>To your mingled spirit of faith.<br/>Pray to contact God as the Spirit within,<br/>For He Himself is your way.<br/>',NULL,38852,2);
INSERT INTO stanza VALUES('NS607','chorus','Speaking is the way<br/>To build up the saints.<br/>Speak life! Speak the truth!<br/>Speak and you’ll be filled!<br/>',NULL,38853,3);
INSERT INTO stanza VALUES('NS608','chorus','The Spirit Himself<br/>Witnesses with our spirit<br/>That we are children of God.<br/><br/>The Spirit Himself<br/>Witnesses with our spirit<br/>That we are children of God.<br/>',NULL,38854,1);
INSERT INTO stanza VALUES('NS608','chorus','God is Spirit, and those<br/>Who worship Him<br/>Must worship in spirit<br/>And truthfulness.<br/><br/>God is Spirit, and those<br/>Who worship Him<br/>Must worship in spirit<br/>And truthfulness.<br/>',NULL,38855,2);
INSERT INTO stanza VALUES('NS609','1','It was a stormy night,<br/>In the middle of the sea.<br/>The disciples all alone,<br/>The shore they could not reach.<br/>',NULL,38856,1);
INSERT INTO stanza VALUES('NS609','chorus','This is our human life<br/>As hard as we may try,<br/>The problems with no end—<br/>We always wonder why?<br/>',NULL,38857,2);
INSERT INTO stanza VALUES('NS609','2','Is Jesus in your boat?<br/>He walks on stormy seas.<br/>The troubled waves of life<br/>Are all beneath His feet.<br/>',NULL,38858,3);
INSERT INTO stanza VALUES('NS609','chorus','Is Jesus in your boat?<br/>For He says, “It is I,<br/>Do not be afraid.”<br/>Just let Him in your life.<br/>',NULL,38859,4);
INSERT INTO stanza VALUES('NS609','3','Lord, my heart I open wide.<br/>I thank You that You died,<br/>Forgave me of my sins,<br/>That You could be my life.<br/>',NULL,38860,5);
INSERT INTO stanza VALUES('NS609','chorus','Lord I believe in You,<br/>Come into all my life,<br/>My rest and peace within—<br/>Joined to You, I’m alive.<br/>',NULL,38861,6);
INSERT INTO stanza VALUES('NS609','chorus','Lord I believe in You,<br/>And You are now my peace.<br/>I’m glad You’re in my boat,<br/>For eternity.<br/>',NULL,38862,7);
INSERT INTO stanza VALUES('NS610','chorus','And I said to him, My lord,<br/>you know, you know.<br/>And he said to me, These are those,<br/>these are those, these are those<br/>Who come out of the great tribulation,<br/>And they have washed their robes,<br/>washed their robes, washed their robes<br/>And made them white<br/>In the blood of the Lamb.<br/>',NULL,38863,1);
INSERT INTO stanza VALUES('NS610','chorus','Because of this they are before<br/>The throne of God<br/>And serve Him day and night in His temple;<br/>And He who sits upon the throne,<br/>upon the throne<br/>Will tabernacle over them,<br/>will tabernacle over them.<br/>',NULL,38864,2);
INSERT INTO stanza VALUES('NS610','chorus','They will not hunger, hunger any more,<br/>Neither will they thirst any more,<br/>Neither will the sun beat upon them,<br/>Nor any heat;<br/>',NULL,38865,3);
INSERT INTO stanza VALUES('NS610','chorus','For the Lamb who is in the midst<br/>Of the throne<br/>Will shepherd them and guide them<br/>To springs, to springs,<br/>Springs of waters of life;<br/>And God will wipe away<br/>Every tear, every tear<br/>From their eyes.<br/>',NULL,38866,4);
INSERT INTO stanza VALUES('NS611','chorus','God who said,<br/>Out of darkness light shall shine,<br/>Is the One<br/>Who shined in our hearts<br/>To illuminate the knowledge of<br/>The glory of God in the face of Christ.<br/>Lord, shine out in us,<br/>In the face of Jesus Christ.<br/>',NULL,38867,1);
INSERT INTO stanza VALUES('NS612','1','I’m not of this world anymore;<br/>To You, Lord, I am restored.<br/>When I look into Your eyes,<br/>My whole being’s fully satisfied.<br/>With my hope now set on You,<br/>There is nothing more to do.<br/>Loving, living You this way,<br/>Deep within my heart, O Lord, I’ll pray.<br/>',NULL,38868,1);
INSERT INTO stanza VALUES('NS612','chorus','Lord, I just love You.<br/>Fill my heart, renew.<br/>Living life so true,<br/>Now expressing You.<br/>',NULL,38869,2);
INSERT INTO stanza VALUES('NS612','2','Everything in You we find<br/>Perfect rest and peace of mind;<br/>No more worry where to be,<br/>For our lives are hidden, Lord, in Thee.<br/>All opinions You’ll erase<br/>And this natural man abase.<br/>One new man, Lord, then we’ll be,<br/>Christ in us the hope of glory!<br/>',NULL,38870,3);
INSERT INTO stanza VALUES('NS612','chorus','Lord, we just love You.<br/>Fill our hearts, renew.<br/>Body life so true,<br/>Representing You.<br/>',NULL,38871,4);
INSERT INTO stanza VALUES('NS615','1','God dispenses riches<br/>To us in His Word,<br/>Feeds our inner being;<br/>Growth in life is spurred.<br/>God Himself is mingled<br/>With us as we dine,<br/>Constituting us with<br/>Elements divine.<br/>',NULL,38876,1);
INSERT INTO stanza VALUES('NS615','2','Find the Word and eat it,<br/>Letting it become<br/>Both our joy and gladness,<br/>Present and to come.<br/>God with life supplies us,<br/>Nourishing and sweet,<br/>To feed others with His <br/>Life supply complete.<br/>',NULL,38877,2);
INSERT INTO stanza VALUES('NS615','3','All that God has spoken<br/>Treasure in your heart.<br/>Go and speak with blessings,<br/>God to man impart.<br/>Let God’s Word, devoured,<br/>Fill your heart and soul;<br/>Pour out from the storehouse<br/>Found within the scroll.<br/>',NULL,38878,3);
INSERT INTO stanza VALUES('NS615','4','Every word of Scripture<br/>Is a worthy prayer,<br/>Matchless in expression,<br/>Gateway to God’s care.<br/>Fill each inward part with<br/>God’s indwelling Word;<br/>Let it touch your conscience,<br/>Fellowship assured.<br/>',NULL,38879,4);
INSERT INTO stanza VALUES('NS615','5','Let God’s light shine deeply,<br/>Inward parts to search.<br/>Then, with revelation,<br/>Speak to build the church.<br/>God in Christ is speaking<br/>In His awesome move;<br/>As four living creatures,<br/>We His speaking prove.<br/>',NULL,38880,5);
INSERT INTO stanza VALUES('NS615','6','Eat the scroll of Scripture!<br/>Utter what God speaks!<br/>Prophesy in spirit,<br/>Strong in word, yet meek,<br/>Faithfully discharging<br/>Life to all who hear,<br/>In divine dispensing,<br/>Filled as God draws near.<br/>',NULL,38881,6);
INSERT INTO stanza VALUES('NS615','7','Take the scroll now opened<br/>In the hand of Christ<br/>And with glad reception<br/>Eat the words of life.<br/>Every word proceeds out<br/>Through the mouth of God,<br/>Oracles of utterance<br/>Ministering God.<br/>',NULL,38882,7);
INSERT INTO stanza VALUES('NS615','8','God dispenses riches<br/>To us in His Word,<br/>Feeding us for building,<br/>In God’s life secured.<br/>By this rich dispensing,<br/>God supplied within,<br/>We become God’s building,<br/>New Jerusalem.<br/>',NULL,38883,8);
INSERT INTO stanza VALUES('NS616','1','In the beginning was the Word.<br/>The Word was God Himself.<br/>And when time’s fullness came, the Word<br/>In flesh incarnate dwelt.<br/>The Word defines, explains, reveals<br/>The “I Am What I Am,”<br/>The living Word named Jesus Christ,<br/>God’s breath breathed into man.<br/>',NULL,38884,1);
INSERT INTO stanza VALUES('NS616','2','This Man became the Spirit then,<br/>Whom we by faith receive.<br/>He’s now the Man enthroned on high!<br/>How can we not believe?<br/>The living Word our spirit stirs,<br/>As we to God draw nigh,<br/>In spirit by the Spirit blessed<br/>Beneath an open sky.<br/>',NULL,38885,2);
INSERT INTO stanza VALUES('NS616','3','Receive salvation’s helmet and<br/>The Spirit as a sword,<br/>Which Spirit is the Word of God,<br/>By means of prayer’s accord.<br/>At every time, pray watchfully<br/>In spirit, in God’s care,<br/>Petitioning for all the saints,<br/>Thus one another bear.<br/>',NULL,38886,3);
INSERT INTO stanza VALUES('NS616','4','If God is for us, who indeed<br/>Can be against us still?<br/>Who brings a charge ’gainst God’s elect?<br/>Christ intercedes and will.<br/>The love of God in Jesus Christ<br/>Encompasses all things,<br/>So naught can separate us from<br/>His love, which sonship brings.<br/>',NULL,38887,4);
INSERT INTO stanza VALUES('NS616','5','As we take in the Word, we too<br/>Express God corporately,<br/>Like-minded e’en like-souled become<br/>With God the Trinity.<br/>Receive the Word by daily prayer<br/>In such a living way<br/>That darkness can’t avoid the light<br/>And death to life gives way!<br/>',NULL,38888,5);
INSERT INTO stanza VALUES('NS616','6','The Word is living, operative,<br/>And sharper than a sword,<br/>Dividing soul from spirit by<br/>The light therein outpoured.<br/>God’s presence and God’s speaking mark<br/>God’s Sabbath rest for us;<br/>He speaks, we rest, and all is done.<br/>His way is effortless.<br/>',NULL,38889,6);
INSERT INTO stanza VALUES('NS616','7','Our preparation as the Bride<br/>Depends upon the Word<br/>That sanctifies us inwardly,<br/>Imbues us with the Lord!<br/>God purposed in Himself to have<br/>A peerless counterpart,<br/>Preparing us through words of life<br/>Inscribed upon our heart.<br/>',NULL,38890,7);
INSERT INTO stanza VALUES('NS616','8','The Spirit calls us — overcome!<br/>Yea, hold fast what you have!<br/>Take, eat the tree of life, be fed!<br/>In Christ be strengthened, glad!<br/>With hearts believing, ears to hear,<br/>And eyes for Christ alone,<br/>As one we cannot help but say,<br/>“Yes, come Lord, quickly come!”<br/>',NULL,38891,8);
INSERT INTO stanza VALUES('NS617','chorus','I am a tree, with roots by<br/>The river of living water,<br/>Trials still may come<br/>But they end in victory;<br/>And even in the wilderness<br/>When there’s no hope at all,<br/>I have roots by the river of the Lord.<br/>When the scorching sun arrives,<br/>My leaves won’t wither and die,<br/>I have roots by the river of the Lord.<br/>',NULL,38892,1);
INSERT INTO stanza VALUES('CB267','1','Pun-a na’s Espiritu Mo<br/>Kining nangandoy Nimo;<br/>Pun-a ako’s presensya Mo,<br/>Anhi na ug pun-a ko!<br/>',NULL,38893,1);
INSERT INTO stanza VALUES('CB267','chorus','Pun-a na! Pun-a na!<br/>Pun-a’s Espiritu Mo!<br/>Basiyoha gyud pag-ayo,<br/>Pun-a na’s Espiritu!<br/>',NULL,38894,2);
INSERT INTO stanza VALUES('CB267','2','Makapuno Ka, unsaon<br/>Dili ko ikasulti;<br/>Nagkinahanglan Ko Nimo;<br/>Anhia, pun-a ako!<br/>',NULL,38895,3);
INSERT INTO stanza VALUES('CB267','3','Maluyahon gyud kaayo;<br/>Magyukbo’s tiilan Mo;<br/>Pinaagi’s Espiritu,<br/>Pun-a’s kusog, pun-a ko!<br/>',NULL,38896,4);
INSERT INTO stanza VALUES('CB267','4','Hinloi ug lipaya ko,<br/>Pun-a ang espiritu!<br/>Tam-is naglipay ug nagl’was<br/>Ikaw karon kanako.<br/>',NULL,38897,5);
INSERT INTO stanza VALUES('E1349','1','Sowing in the morning, sowing seeds of kindness,<br/>Sowing in the noontide and the dewy eve;<br/>Waiting for the harvest, and the time of reaping,<br/>We shall come rejoicing, bringing in the sheaves.<br/>',NULL,38938,1);
INSERT INTO stanza VALUES('E1349','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>We shall come rejoicing, bringing in the sheaves;<br/>Bringing in the sheaves, bringing in the sheaves,<br/>We shall come rejoicing, bringing in the sheaves.<br/>',NULL,38939,2);
INSERT INTO stanza VALUES('E1349','2','Sowing in the sunshine, sowing in the shadows,<br/>Fearing neither clouds nor winter’s chilling breeze;<br/>By and by, the harvest and the labor ended,<br/>We shall come rejoicing, bringing in the sheaves.<br/>',NULL,38940,3);
INSERT INTO stanza VALUES('E1349','3','Going forth with weeping, sowing for the Master,<br/>Tho’, the loss sustained, our spirit often grieves;<br/>When our weeping’s over, He will bid us welcome,<br/>We shall come rejoicing, bringing in the sheaves.<br/>',NULL,38941,4);
INSERT INTO stanza VALUES('E1350','chorus','I’m in Christ, now rejoicing—<br/>From old Adam I am free!<br/>All old things are becoming<br/>Both new and heavenly! (Praise God!)<br/>I’m tasting and enjoying<br/>Life and peace and liberty!<br/>Praise God! I’m in Christ eternally!<br/>',NULL,38942,1);
INSERT INTO stanza VALUES('E1351','1','What mercy that my eyes have seen the true God,<br/>Happily transferred from darkness into light!<br/>What grace that I can freely have salvation,<br/>No need to work, endeavor with my might!<br/>',NULL,38943,1);
INSERT INTO stanza VALUES('E1351','2','Now that I’m saved, remember, Lord, my family,<br/>Their sins You’ve borne, the way has thus been paved;<br/>This day fulfill the promise You have given:<br/>“Believe in Christ; your whole house shall be saved.”<br/>',NULL,38944,2);
INSERT INTO stanza VALUES('E1351','3','Lord, hear my prayer and gain all in my family!<br/>My heart is burning with this vow to You:<br/>“I and my house will serve the Lord forever!”<br/>We’ll worship God for He alone is true!<br/>',NULL,38945,3);
INSERT INTO stanza VALUES('E1352','1','Abide in Christ—this highest blessing gain;<br/>Each day sweet fellowship with Him maintain.<br/>Abiding, He and we are joined as one;<br/>In constant fellowship, all barriers gone.<br/>',NULL,38946,1);
INSERT INTO stanza VALUES('E1352','2','Abide in Him, anointing then will flow;<br/>In fellowship, the Spirit’s lead we’ll know.<br/>Obeying, we His riches apprehend;<br/>Led by the Spirit, we will be His friend.<br/>',NULL,38947,2);
INSERT INTO stanza VALUES('E1352','3','Abide in Him, the light of grace will shine;<br/>In fellowship, all shadows will decline.<br/>Obey the light, His life in us will grow;<br/>From darkness freed, our heart will comfort know.<br/>',NULL,38948,3);
INSERT INTO stanza VALUES('E1352','4','Abiding, we are strengthened with each breath;<br/>In fellowship, His life will swallow death.<br/>Abiding, all our sighing turns to song;<br/>In fellowship, our heart is gladdened, strong.<br/>',NULL,38949,4);
INSERT INTO stanza VALUES('E1352','5','Abiding, this will Satan’s strength disarm;<br/>In fellowship, the world will lose its charm.<br/>Abiding, we sin’s power need not fear;<br/>In fellowship, the self will disappear.<br/>',NULL,38950,5);
INSERT INTO stanza VALUES('E1352','6','Abiding, thus conformed to Him we’ll be;<br/>In fellowship, His life fills constantly.<br/>Abiding, we experience His power;<br/>In fellowship, His riches, hour by hour.<br/>',NULL,38951,6);
INSERT INTO stanza VALUES('E1352','7','Abiding, Lord, for Thee my spirit yearns;<br/>In fellowship, Thy Spirit in me burns,<br/>That all my being may be lost in Thee<br/>And with Thee mingled through eternity.<br/>',NULL,38952,7);
INSERT INTO stanza VALUES('E1353','1','Live in the light of life, <br/>Sweet fellowship maintain;<br/>Behold His gracious face,<br/>Each day more glory gain,<br/>The Spirit’s move obey,<br/>Rejoice and praise and pray;<br/>Live in the light of life.<br/>',NULL,38953,1);
INSERT INTO stanza VALUES('E1354','1','When the Lord descends from heaven, and God’s trumpet sound we hear,<br/>Those who sleep will rise, and death will swallowed be.<br/>When the Lord descends from heaven, raptured we will be who live,<br/>And our bodies be transformed in liberty.<br/>',NULL,38954,1);
INSERT INTO stanza VALUES('E1354','chorus','When the Lord will come in glory<br/>We will see His glorious body;<br/>When the Lord will come in glory,<br/>To transfigure all His sons, we’ll have a share.<br/>',NULL,38955,2);
INSERT INTO stanza VALUES('E1354','2','When the Lord descends from heaven, then the morning bright will dawn,<br/>This dark night will pass, and weeping will be o’er.<br/>When the Lord descends from heaven, days of glory will begin;<br/>Sighing and corruption gone forevermore.<br/>',NULL,38956,3);
INSERT INTO stanza VALUES('E1354','3','E’er the Lord will come from heaven, the bright morning star will shine,<br/>Those who watch escape the trial, gain the prize.<br/>Then the Lord will come and as the Sun of righteousness will reign;<br/>Earth will be restored, God’s mercy realize.<br/>',NULL,38957,4);
INSERT INTO stanza VALUES('E1354','4','Soon the Lord will come from heaven; may we watch and wait with prayer,<br/>Loins be girt about, and lamps be burning bright.<br/>Soon the Lord will come from heaven, may we serve Him faithfully,<br/>Thus the ministry fulfill, our gifts incite.<br/>',NULL,38958,5);
INSERT INTO stanza VALUES('E1355','1','God has forgiven all my sins;<br/>Behind His back they all are cast.<br/>He’ll never call to mind again<br/>The sins He vanquished in the past.<br/>',NULL,38959,1);
INSERT INTO stanza VALUES('E1355','chorus','God has forgiven all my sins,<br/>And as a gloomy cloud is blown,<br/>My sins are vanished all away!<br/>No more will they be seen or known.<br/>',NULL,38960,2);
INSERT INTO stanza VALUES('E1355','2','My sins were like a heavy stone<br/>God cast and buried in the sea.<br/>As east so far from west is thrown,<br/>My sins have been removed from me!<br/>',NULL,38961,3);
INSERT INTO stanza VALUES('E1356','1','Glory! Glory! Christ is life indeed!<br/>Glory! Ever does the Spirit lead!<br/>Weakness turns to power,<br/>Darkness turns to light!<br/>Glory! Glory! Christ is life indeed!<br/>',NULL,38962,1);
INSERT INTO stanza VALUES('E1356','2','Glory! Glory! Live by Christ today!<br/>Glory! Walk in Spirit and obey!<br/>Failure turns to vict’ry,<br/>Sighing turns to song!<br/>Glory! Glory! Live by Christ today!<br/>',NULL,38963,2);
INSERT INTO stanza VALUES('E1357','1','What joy fills my heart, fills my heart, fills my heart,<br/>What joy fills my heart!<br/>God takes my stone heart, one of flesh imparts;<br/>His Spirit renewing gives life to each part.<br/>What joy fills my heart, fills my heart, fills my heart.<br/>',NULL,38964,1);
INSERT INTO stanza VALUES('E1357','2','Oh, His Spirit fills, fills me now, fills me now!<br/>Oh, His Spirit fills!<br/>He drives out my sin, weakness, death, within,<br/>To bear fruits of righteousness, holy to Him.<br/>Oh, His Spirit fills, fills me now, fills me now!<br/>',NULL,38965,2);
INSERT INTO stanza VALUES('E1358','1','Rise! Preach the gospel now!<br/>Rescue the fallen!<br/>Lo, millions perishing daily in pain!<br/>Quench not your heart of love,<br/>Count not possessions:<br/>Rise! Preach the gospel while moments remain.<br/>',NULL,38966,1);
INSERT INTO stanza VALUES('E1358','chorus','Rise! Preach the gospel now!<br/>Rescue the fallen!<br/>Your heart of love for them,<br/>Can you restrain?<br/>',NULL,38967,2);
INSERT INTO stanza VALUES('E1359','1','Take my life, and let it be<br/>Consecrated, Lord, to Thee;<br/>Take my moments and my days,<br/>Let them flow in ceaseless praise.<br/>',NULL,38968,1);
INSERT INTO stanza VALUES('E1359','chorus','For me, You were mocked and crucified;<br/>For me, willingly You bled and died.<br/>Lord, my life and love I willingly outpour<br/>And will serve You evermore.<br/>',NULL,38969,2);
INSERT INTO stanza VALUES('E1359','2','Take my hands, and let them move<br/>At the impulse of Thy love;<br/>Take my feet and let them be<br/>Swift and beautiful for Thee.<br/>',NULL,38970,3);
INSERT INTO stanza VALUES('E1359','3','Take my voice, and let me sing<br/>Always, only, for my King;<br/>Take my lips, and let them be<br/>Filled with messages from Thee.<br/>',NULL,38971,4);
INSERT INTO stanza VALUES('E1359','4','Take my silver and my gold;<br/>Not a mite would I withhold;<br/>Take my intellect, and use<br/>Every power as Thou shalt choose.<br/>',NULL,38972,5);
INSERT INTO stanza VALUES('E1359','5','Take my will, and make it Thine;<br/>It shall be no longer mine.<br/>Take my heart; it is Thine own;<br/>It shall be Thy royal throne.<br/>',NULL,38973,6);
INSERT INTO stanza VALUES('E1359','6','Take my love; my Lord, I pour<br/>At Thy feet its treasure-store.<br/>Take myself, and I will be<br/>Ever, only, all for Thee.<br/>',NULL,38974,7);
INSERT INTO stanza VALUES('E1360','1','Oh, how glorious! Oh, how precious!<br/>Now the Spirit dwells in me.<br/>Life imparting, truth revealing,<br/>Shining, leading constantly.<br/>',NULL,38975,1);
INSERT INTO stanza VALUES('E1360','chorus','Fill me now! Fill me now!<br/>Fill me with Thy Spirit now!<br/>Strip me wholly, empty thoroughly,<br/>Fill me with Thy Spirit now!<br/>',NULL,38976,2);
INSERT INTO stanza VALUES('E1360','2','Word of promise, real within me,<br/>Life divine now freeing me—<br/>From sin’s cruel control releasing,<br/>From death’s power setting free.<br/>',NULL,38977,3);
INSERT INTO stanza VALUES('E1360','3','Deepest springs of life dispensing,<br/>Like the hart I thirst for Thee;<br/>Desp’rate, may I drink Thy fullness,<br/>’Till Thy river flows through me.<br/>',NULL,38978,4);
INSERT INTO stanza VALUES('E1360','4','May my self be put to death, Lord,<br/>Under Thy control I’d be,<br/>Transformed to Thy living image,<br/>I’d forever flow out Thee.<br/>',NULL,38979,5);
INSERT INTO stanza VALUES('T1','1','L''walhati sa Diyos Ama at sa Anak Kristo,<br/>L''walhati sa Espiritu — laging Isa.<br/>',NULL,38980,1);
INSERT INTO stanza VALUES('T1','2','Sa pagmamasid ng malawak na nilikha,<br/>Puso nati''y tatahimik at sasamba.<br/>',NULL,38981,2);
INSERT INTO stanza VALUES('T1','3','O Diyos, nais Mo ang magkaroon sa Anak<br/>Mga anak nagpupuri''t nagmamahal.<br/>',NULL,38982,3);
INSERT INTO stanza VALUES('T1','4','Ang pagsinta Mo''y ''pinahayag sa nilalang<br/>Upang ang pagsinta nila ay makamtan.<br/>',NULL,38983,4);
INSERT INTO stanza VALUES('T1','5','Sa pagtubos ni Kristo, masama''y napuksa;<br/>Mananamba''y nakamtan sa bagong likha.<br/>',NULL,38984,5);
INSERT INTO stanza VALUES('T1','6','L''walhati sa Diyos Ama at sa Anak Kristo,<br/>L''walhati sa Espiritu — laging Isa.<br/>',NULL,38985,6);
INSERT INTO stanza VALUES('T2','1','L''walhati, l''walhati Siya ay papurihan!<br/>Pakinggan ang mga awitang walang hanggan!<br/>Ama, Anak ''Spiritu-Diyos nahayag na—<br/>Bawa''t tao ay dapat sumamba!<br/>',NULL,38986,1);
INSERT INTO stanza VALUES('T2','2','Ama, pinagmulan ng bawa''t pamilya;<br/>Anak umalalay ng lahat sa lakas Niya;<br/>''Spiritu Santo nagpuno ng l''walhati—<br/>Kapuspusan, kami''y pumupuri!<br/>',NULL,38987,2);
INSERT INTO stanza VALUES('T2','3','Kataas-ta''sang Diyos kami''y sumasamba,<br/>O Ulo, sa harap Mo kami''y nagtirapa!<br/>Kamahalan, papuri''t kadakilaan,<br/>Sa Iyo lamang hanggang walang hanggan!<br/>',NULL,38988,3);
INSERT INTO stanza VALUES('T3','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,38989,1);
INSERT INTO stanza VALUES('T3','1','Amin Kang aawitan,<br/>Haring Makapangyarihan,<br/>Purihin Ka:<br/>Ama, mal''walhati,<br/>Matagumpay lagi,<br/>Halina''t maghari,<br/>Ang "Sa Una."<br/>',NULL,38990,2);
INSERT INTO stanza VALUES('T3','2','Salitang naging laman,<br/>Tabak Mo ay kalakasan,<br/>Aming samo:<br/>Kami''y biyayaan,<br/>Tagumpay makamtan;<br/>At kami''y puspusan,<br/>Ng ''Spiritu.<br/>',NULL,38991,3);
INSERT INTO stanza VALUES('T3','3','Mang-aaliw na banal,<br/>Patotoo Mo''y itanghal<br/>Ngayon mismo:<br/>Makapangyarihan,<br/>Sa puso ng tanan,<br/>Ikaw ang manahan,<br/>Espiritu.<br/>',NULL,38992,4);
INSERT INTO stanza VALUES('T3','4','Dakilang Tatlo-Isa,<br/>Walang hanggang purihin Ka,<br/>At ibigin;<br/>Ang Iyong kamahalan<br/>Sa l''walhati''y masdan,<br/>Nang magpakailanman<br/>Sasambahin.<br/>',NULL,38993,5);
INSERT INTO stanza VALUES('T4','1','Ama, sinta Mo''y kay lalim,<br/>Hatid ang pagtubos sa ''min,<br/>Nakaluhod sa Iyong harap<br/>Kami''y bigyan Iyong patawad.<br/>',NULL,38994,1);
INSERT INTO stanza VALUES('T4','2','Anak, Verbong naging tao,<br/>Saserdote, Pangino''n ko,<br/>Propeta at Manunubos,<br/>Biyaya Mo ay ibuhos.<br/>',NULL,38995,2);
INSERT INTO stanza VALUES('T4','3','Espiritu, Iyong hininga<br/>Ibinangon ang kalul''wa,<br/>Mula sala''t kamatayan;<br/>Binigyang kapangyarihan.<br/>',NULL,38996,3);
INSERT INTO stanza VALUES('T4','4','Ama, Anak, Espiritu,<br/>Ang Pagka-Diyos ay misteryo;<br/>Buhay, biyaya''t patawad.<br/>Sa amin ay Iyong igawad.<br/>',NULL,38997,4);
INSERT INTO stanza VALUES('T5','1','Sinasamba Ka, O Ama!<br/>Iyong ngala''y pinagpala!<br/>Sa loob ni Kristo''y hirang,<br/>Nang walang kapintasan.<br/>Sa Iyo sumasamba kami,<br/>Sa Abba, laksang puri.<br/>Sa Iyo sumasamba kami,<br/>Sa Abba, laksang puri.<br/>',NULL,38998,1);
INSERT INTO stanza VALUES('T5','2','O Anak, pagsamba''y sa Iyo,<br/>Korderong nasa trono;<br/>Dinala Mo bayan ng Diyos<br/>Palapit sa Iyong lubos.<br/>Anak ng Diyos na namatay,<br/>Nang bigyan kaming buhay;<br/>Anak ng Diyos, aming mahal,<br/>Sambahin Ka''t itanghal.<br/>',NULL,38999,2);
INSERT INTO stanza VALUES('T5','3','Ama, Anak, Espiritu,<br/>Purihin Ka, Tres-uno!<br/>Sa minana naming yaman<br/>Ikaw ay papurihan.<br/>Purihin Kang walang hanggan,<br/>Sambahin Ka''t kalugdan.<br/>Purihin Kang walang hanggan,<br/>Sambahin Ka''t kalugdan.<br/>',NULL,39000,3);
INSERT INTO stanza VALUES('T6','1','Banal, Banal, Banal, Makapangyarihan!<br/>Awit mapasa Iyo hanggang sa walang hanggan;<br/>Banal, Banal, Banal ang Diyos na Tres-uno;<br/>Iisang Diyos, may panig na tatlo.<br/>',NULL,39001,1);
INSERT INTO stanza VALUES('T6','2','Banal, Banal, Banal, Ika''y sinisinta;<br/>Mga matanda putong inilagay nila<br/>Sa Iyong harapan, nagsisamba ang tanan,<br/>Iyong noon, ngayon, at walang hanggan.<br/>',NULL,39002,2);
INSERT INTO stanza VALUES('T6','3','Banal, Banal, Banal, kahit nakakubli<br/>Di man makita ng maysala Iyong l''walhati;<br/>Tanging Ikaw ang banal, wala nang iba,<br/>Sakdal sa kadalisaya''t puwersa.<br/>',NULL,39003,3);
INSERT INTO stanza VALUES('T7','1','Luwalhati sa Amang Diyos!<br/>Luwalhati sa Anak<br/>L''walhati sa Espiritu!<br/>Ang Tatlo ay Iisa!<br/>',NULL,39004,1);
INSERT INTO stanza VALUES('T7','chorus','Purihin Siya, Purihin Siya!<br/>Ang Tatlo ay Iisa!<br/>L''walhatiin, l''walhatiin,<br/>Sa Kanyang mahiwagang gawa!<br/>',NULL,39005,2);
INSERT INTO stanza VALUES('T7','2','Purihin: Amang nagbalak!<br/>At Anak na nagtupad!<br/>At Espiritung naghatid!<br/>Ang Tatlong nagkaisa!<br/>',NULL,39006,3);
INSERT INTO stanza VALUES('T7','chorus','Purihin Siya, Purihin Siya!<br/>Ang Tatlo ay Iisa!<br/>L''walhatiin, l''walhatiin,<br/>Sa Kanyang mahiwagang gawa!<br/>',NULL,39007,4);
INSERT INTO stanza VALUES('T8','1','Diyos Ama ang pinagmulan,<br/>Sa Diyos Anak — katubusan,<br/>Espiritu''y realidad,<br/>Puri sa Diyos na Trinidad!<br/>',NULL,39008,1);
INSERT INTO stanza VALUES('T8','2','Puri sa Ama — batisan,<br/>Sa Anak na paagusan,<br/>Sa Espiritu — Siyang agos,<br/>Puri sa Diyos, aking tustos!<br/>',NULL,39009,2);
INSERT INTO stanza VALUES('T9','1','Luwalhati sa Diyos Ama,<br/>L''walhati sa Diyos Anak,<br/>L''walhati sa Diyos ''Spiritu,<br/>Jehovah Diyos Tres-uno!<br/>Siya noon, ngayon, palagi<br/>Walang hanggang papuri.<br/>',NULL,39010,1);
INSERT INTO stanza VALUES('T10','1','O Diyos, walang hanggang Ama,<br/>Ang di-nilikhang AKO NGA!<br/>Mas antigo kaysa tanan,<br/>Bago pa''ng kapanahunan!<br/>',NULL,39011,1);
INSERT INTO stanza VALUES('T10','2','Mula sa kawalang-hanggan,<br/>Panaho''t lugar nahig''tan!<br/>Kapuspusang walang hanggan,<br/>Diyos ngang walang katapusan!<br/>',NULL,39012,2);
INSERT INTO stanza VALUES('T10','3','Walang hanggang pinagmulan,<br/>Bago pa ang kalangitan!<br/>Una sa lahat ng una,<br/>At higit pa sa "pinaka"!<br/>',NULL,39013,3);
INSERT INTO stanza VALUES('T10','4','Ang buhay na walang hanggan,<br/>Ika''y walang katapusan!<br/>Higit na nananatili,<br/>Lampas sa pinakahuli!<br/>',NULL,39014,4);
INSERT INTO stanza VALUES('T10','5','Bilang una Ika''y Alpha,<br/>Bilang huli ay Omega!<br/>Sa simula hanggang wakas,<br/>Buo''t sakdal, walang kupas!<br/>',NULL,39015,5);
INSERT INTO stanza VALUES('T10','6','Sa Iyong kawalang-hangganan,<br/>Sa lawak ng kapuspusan!<br/>Maging sa Iyong kasakdalan,<br/>Dapat Ka ngang papurihan!<br/>',NULL,39016,6);
INSERT INTO stanza VALUES('T11','1','Ama, Espiritung tunay<br/>Ang pinakabanal;<br/>Sambahin Ka sa ''spiritu,<br/>Tawaging totoo.<br/>',NULL,39017,1);
INSERT INTO stanza VALUES('T11','2','Espiritu''y Iyong nilikha<br/>Nang sa Iyo''y sumamba;<br/>Magtugunan sa ''spiritu,<br/>Kaisang ''spiritu.<br/>',NULL,39018,2);
INSERT INTO stanza VALUES('T11','3','Dumating Ama sa Anak,<br/>''Spiritu ang Anak,<br/>Nang ang Diyos sa ''ting ''spiritu<br/>Ay makaparito.<br/>',NULL,39019,3);
INSERT INTO stanza VALUES('T11','4','Anak walang hanggang Verbo,<br/>Verbo ri''y ''Spiritu;<br/>Aming buhay Iyong ''Spiritu<br/>Nang kami''y mabago.<br/>',NULL,39020,4);
INSERT INTO stanza VALUES('T11','5','''Spiritu sa ''ming ''spiritu,<br/>Nang makaisa Mo<br/>''Spiritu''t ''spiritu''y saksi<br/>''Sinilang Mo kami.<br/>',NULL,39021,5);
INSERT INTO stanza VALUES('T11','6','Iyong ''Spiritu''y nangunguna<br/>Nang aming sundan Siya;<br/>Kami''y maging espirituwal,<br/>Mapayapang sakdal.<br/>',NULL,39022,6);
INSERT INTO stanza VALUES('T11','7','Sambahin Ka sa ''spiritu,<br/>At pagtawag sa Iyo,<br/>Nang espiritu''y lumaya<br/>Larawa''y mahayag.<br/>',NULL,39023,7);
INSERT INTO stanza VALUES('T11','8','Ama namin, purihin Ka<br/>Na ''Spiritu Ka nga;<br/>Sa ''spiritu''t realidad<br/>Pagsamba''y mai-gawad.<br/>',NULL,39024,8);
INSERT INTO stanza VALUES('T12','1','Bukal ng buhay Ka, O Diyos,<br/>Matamis na agos!<br/>Banal at mayamang tustos<br/>Saan ma''y lumagos!<br/>',NULL,39025,1);
INSERT INTO stanza VALUES('T12','2','Ang pag-ibig sa Anak Mo<br/>Dumating sa tao;<br/>Espiritu ang umagos<br/>Kami''y pinupuspos.<br/>',NULL,39026,2);
INSERT INTO stanza VALUES('T12','3','Tao''y kanya-kanyang landas<br/>Kasalana''y tahas,<br/>Katubusa''y sa Anak Mo,<br/>Buhay matatamo.<br/>',NULL,39027,3);
INSERT INTO stanza VALUES('T12','4','Kahit inapi Ka namin,<br/>Sinusuway Ka rin,<br/>Espiritu''y naghihintay<br/>Bigyan kaming buhay.<br/>',NULL,39028,4);
INSERT INTO stanza VALUES('T12','5','Sa Anak Ika''y ''Spiritu<br/>Sa ''mi''y nakihalo;<br/>Elemento Mo''y darami<br/>Sa pagpahid lagi.<br/>',NULL,39029,5);
INSERT INTO stanza VALUES('T12','6','Pag-ibig ng Diyos batid ko,<br/>Biyaya ni Kristo,<br/>At agos ng Espiritu<br/>Laging tamasa ko.<br/>',NULL,39030,6);
INSERT INTO stanza VALUES('T12','7','Diyos Trinidad — Ama, Anak,<br/>Espiritu Santo,<br/>Karapat-dapat purihin<br/>At laging mahalin.<br/>',NULL,39031,7);
INSERT INTO stanza VALUES('T13','1','Diyos na pag-ibig at ilaw,<br/>Sa Anak Ika''y buhay;<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39032,1);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39033,2);
INSERT INTO stanza VALUES('T13','2','Ikaw Mismo ay pag-ibig,<br/>Sa liwanag nakita;<br/>Liwanag sa panlabas nga,<br/>Sa panloob pag-ibig.<br/>',NULL,39034,3);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39035,4);
INSERT INTO stanza VALUES('T13','3','Ang pag-ibig sa biyaya<br/>Ay lubusang nahayag,<br/>Sa katotohanan naman<br/>Nahayag ang liwanag.<br/>',NULL,39036,5);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39037,6);
INSERT INTO stanza VALUES('T13','4','Ang buhay ng Diyos natanggap<br/>Dahil sa pag-ibig Mo;<br/>Liwanag nagpaunawa<br/>Nang magamit ang dugo.<br/>',NULL,39038,7);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39039,8);
INSERT INTO stanza VALUES('T13','5','Sa pag-ibig Mo ang buhay<br/>Nagbigay salamuha;<br/>Sa Iyong liwanag nakuha<br/>Pag''linis, salamuha.<br/>',NULL,39040,9);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39041,10);
INSERT INTO stanza VALUES('T13','6','Mababatid pagpapahid<br/>Sa liwanag at dugo;<br/>Dadaloy lalo sa amin<br/>Esensya ng buhay Mo.<br/>',NULL,39042,11);
INSERT INTO stanza VALUES('T13','chorus','Pag-ibig at ilaw!<br/>Sa Anak Ika''y buhay,<br/>Inibig at tinanglawan<br/>Kami''y binigyang buhay.<br/>',NULL,39043,12);
INSERT INTO stanza VALUES('T13','7','Sa pag-ibig naisilang,<br/>Tinatawag Kang Ama;<br/>Sa ilaw, dilim pinawi,<br/>Makawangis Niya kami.<br/>',NULL,39044,13);
INSERT INTO stanza VALUES('T13','chorus','Totoong liwanag!<br/>Pag-ibig at biyaya!<br/>Kami''y nagpapasalamat,<br/>Pumupuri sa Ama!<br/>',NULL,39045,14);
INSERT INTO stanza VALUES('T14','1','Di namamatay, Diyos di masilayan,<br/>Nasa liwanag na di-malapitan,<br/>Pinagpala, mal''walhating "Siyang Una",<br/>Papurihan Iyong pangalang dakila.<br/>',NULL,39046,1);
INSERT INTO stanza VALUES('T14','2','Di mapahinga, di-nagmamadali,<br/>Sa Iyong kapangyarihan naghahari;<br/>''Sintayog ng bundok katarungan Mo,<br/>Bukal ng buti''t pag-ibig, ulap Mo.<br/>',NULL,39047,2);
INSERT INTO stanza VALUES('T14','3','Nabubuhay Ka sa buhay ng lahat;<br/>Buhay ay Iyong ''binibigay sa lahat,<br/>Kami''y yumayabong at nalalanta,<br/>Makapagpapabago sa Iyo''y wala.<br/>',NULL,39048,3);
INSERT INTO stanza VALUES('T14','4','Ama ng liwanag, Ama ng gloria,<br/>Iyong mga anghel sa Iyo''y sumasamba;<br/>Sa Iyo ibibigay tamang papuri,<br/>Makita lamang ningning ng l''walhati.<br/>',NULL,39049,4);
INSERT INTO stanza VALUES('T14','5','Ang Diyos na marunong, di-namamatay,<br/>Nakakubli mula sa ating mata.<br/>Pinagpala, mal''walhating "Siyang Una"<br/>Papurihan Iyong pangalang dakila.<br/>',NULL,39050,5);
INSERT INTO stanza VALUES('T15','1','Nangingibabaw Ka nga,<br/>Kay banal na Isa!<br/>Walang makagagaya,<br/>Walang katumbas Ka!<br/>Pinakabanal Ka rin<br/>Aming tatawagin!<br/>Iyong lakas, kalikasan<br/>Lahat nalampasan!<br/>',NULL,39051,1);
INSERT INTO stanza VALUES('T15','2','Bukod tangi at banal,<br/>Di lamang dalisay;<br/>Bagkus may kasakdalan,<br/>Walang kapintasan.<br/>Wala sa Iyong mahambing,<br/>Ni makalapit din;<br/>Sa Iyo''y paglapastangan<br/>Ang Ika''y halinhan.<br/>',NULL,39052,2);
INSERT INTO stanza VALUES('T15','3','Wala nang hihigit pa,<br/>Pinakamaganda,<br/>Walang maihahambing,<br/>Pinakamagaling.<br/>Nangibabaw Iyong buti,<br/>Ito''y natatangi.<br/>Ganda''y walang katulad,<br/>Lampas Ka sa lahat.<br/>',NULL,39053,3);
INSERT INTO stanza VALUES('T15','4','Kay tayog kabanalan<br/>Sa amin hinanda,<br/>Naibang kalikasan<br/>Aming bahagi na.<br/>Nangibabaw gaya Mo,<br/>Magsinlikas tayo;<br/>Buhay Mong banal sundin<br/>Paglago''y puspusin.<br/>',NULL,39054,4);
INSERT INTO stanza VALUES('T15','5','Papuri at pagsamba<br/>Sa Iyong kabanalan,<br/>Matayog kalikasan,<br/>Di Ka mapantayan.<br/>Kalikasan Mong tangi—<br/>Aming nabahagi;<br/>Banal na kalikasan<br/>Amin kailanpaman.<br/>',NULL,39055,5);
INSERT INTO stanza VALUES('T16','1','Laging lunti, aming Ama<br/>Walang pagkalanta;<br/>Panginoong walang hanggan,<br/>Walang kasiraan!<br/>',NULL,39056,1);
INSERT INTO stanza VALUES('T16','chorus','Ama, Diyos ng kabaguhan,<br/>Walang kalumaan;<br/>At ang Iyong kasariwaan<br/>Ay magpakailanman.<br/>',NULL,39057,2);
INSERT INTO stanza VALUES('T16','2','Ika''y Diyos na "bago", Ama,<br/>Kung wala Ka''y luma;<br/>Sa Iyo, walang maging laon<br/>Nang habang panahon.<br/>',NULL,39058,3);
INSERT INTO stanza VALUES('T16','3','Biyaya Iyong ibinigay<br/>Kabaguha''y taglay;<br/>Bagong tipan, bagong daan,<br/>Walang katapusan.<br/>',NULL,39059,5);
INSERT INTO stanza VALUES('T16','4','Kami''y bagong nilikha Mo,<br/>Bagong pagkatao;<br/>Araw-araw nababago,<br/>Bagong buhay''t anyo.<br/>',NULL,39060,7);
INSERT INTO stanza VALUES('T16','5','Bagong langit, bagong lupa,<br/>At bagong lunsod nga;<br/>Buwan-buwan ay may bagong bunga<br/>Na matatamasa.<br/>',NULL,39061,9);
INSERT INTO stanza VALUES('T16','6','Ama, Diyos na laging bago,<br/>Puri''y di hihinto;<br/>Walang hanggang aawitin:<br/>Ama ay purihin!<br/>',NULL,39062,11);
INSERT INTO stanza VALUES('T17','1','Ama kong Diyos, nang aking minamasdan<br/>Ang hiwaga ng sandaigdigan,<br/>Malawak Mong nilikha di mabilang,<br/>Naihayag Iyong kapangyarihan;<br/>',NULL,39063,1);
INSERT INTO stanza VALUES('T17','chorus','Aawitin ko''ng papuri sa Iyo:<br/>Kay dakila Mo, Amang Diyos!<br/>Aawitin nang magpakailanman;<br/>Kay dakila Mo, Amang Diyos!<br/>',NULL,39064,2);
INSERT INTO stanza VALUES('T17','2','Nang matikman ko ang kaligtasan Mo,<br/>Naisip kong sinugong Anak Mo;<br/>Nang namatay kami''y nilikhang bago,<br/>Lubusang ihayag ang buhay Mo;<br/>',NULL,39065,3);
INSERT INTO stanza VALUES('T17','3','Nang sa ekklesia nakakasama ko<br/>Mga banal taglay ang buhay Mo,<br/>Bilang bahay—tahanan itinayo<br/>Inihahayag kapuspusan Mo;<br/>',NULL,39066,5);
INSERT INTO stanza VALUES('T17','4','Umaasang makabahagi ako,<br/>Sa darating Herusalem bago,<br/>Tanang lupa''t langit sa kabaguhan<br/>Lahat Iyong lubos na kahayagan;<br/>',NULL,39067,7);
INSERT INTO stanza VALUES('T18','1','Ama kong Diyos kay tapat Mo<br/>At maaasahan;<br/>Sangnilikha''y patotoo<br/>Ng Iyong katapatan.<br/>',NULL,39068,1);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39069,2);
INSERT INTO stanza VALUES('T18','2','Sa Iyo walang pagbabago<br/>Ni pag-iiba man;<br/>Noon, ngayon, ay pareho,<br/>At magpakailanman.<br/>',NULL,39070,3);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39071,4);
INSERT INTO stanza VALUES('T18','3','Salita Mo''y di makaltas,<br/>Tapat na tulad Mo;<br/>Langit at lupa''y lilipas,<br/>Salita Mo''y buo.<br/>',NULL,39072,5);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39073,6);
INSERT INTO stanza VALUES('T18','4','Pagtawag at kaloob Mo<br/>Di pinagsisihan;<br/>Ang biyaya at habag Mo<br/>Tulad sa Iyong ngalan.<br/>',NULL,39074,7);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39075,8);
INSERT INTO stanza VALUES('T18','5','Iyong Salita''t katapatan<br/>Aking katibayan;<br/>Sampon ng Iyong kaligtasan<br/>Buong katiyakan.<br/>',NULL,39076,9);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39077,10);
INSERT INTO stanza VALUES('T18','6','Kahit Kita''y pagliluhan,<br/>Ika''y tapat pa rin;<br/>Sarili Mo''y di talikdan,<br/>Salita''y tutupdin.<br/>',NULL,39078,11);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39079,12);
INSERT INTO stanza VALUES('T18','7','Pangakong mapagbiyaya<br/>Tutupdin Mong lahat;<br/>At aking natatamasa,<br/>Kay tamis, kay tapat.<br/>',NULL,39080,13);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39081,14);
INSERT INTO stanza VALUES('T18','8','Bahaghari sa luklukan,<br/>Hayag katapatan;<br/>Patunay na walang hanggan<br/>Sa banal na bayan.<br/>',NULL,39082,15);
INSERT INTO stanza VALUES('T18','chorus','Katapatan Mong kay tatag!<br/>Dapat Kang sambahin;<br/>Sa langit ito''y natatag,<br/>Laging laan sa ''kin.<br/>',NULL,39083,16);
INSERT INTO stanza VALUES('T19','1','Katapatan Mo''y dakila Diyos Ama,<br/>Walang ni anino ng pag-iba;<br/>Puspos ng awa, nagbabago dili,<br/>Magpakailanman tulad ng dati!<br/>',NULL,39084,1);
INSERT INTO stanza VALUES('T19','chorus','Katapatan Mo Diyos, napakadakila!<br/>Bagong awa sa bawa''t umaga;<br/>Lahat ng kailangan ko''y Iyong hinanda,<br/>Napakatapat Mo, O Diyos Ama!<br/>',NULL,39085,2);
INSERT INTO stanza VALUES('T19','2','Tag-araw, tagginaw, tagsibol, tag-ani,<br/>Araw, buwan, bituin nagbubunyi;<br/>Sampon ng kalikasan sumasaksi<br/>Sa Iyong katapatan, mga gawi.<br/>',NULL,39086,3);
INSERT INTO stanza VALUES('T19','3','Ako''y pinatawad at mapayapa,<br/>Aliw, gabay ay dulot Mo, Ama,<br/>Lakas sa ngayon, pag-asa sa bukas;<br/>Biyayang di maubos mabigkas.<br/>',NULL,39087,5);
INSERT INTO stanza VALUES('T20','1','Dahil sa katuwiran Mo,<br/>Pagsamba namin ay Iyo;<br/>Kay Kristo I-yong binigyan<br/>Kami ng katuwiran.<br/>Naging matuwid kay Kristo,<br/>Di nabagbag budhi ko.<br/>Sa tapat na kat''wiran Mo,<br/>Kami ay nakatayo.<br/>',NULL,39088,1);
INSERT INTO stanza VALUES('T20','2','Napasakay Hesus sala,<br/>Mat''wid na pinatay Siya;<br/>Ang hiling ng kautusan,<br/>Natupad nang lubusan.<br/>Natubos dahil sa Kanya,<br/>Kaya ''ko''y napalaya;<br/>Pa''nong sisingilin ako<br/>Ng Diyos na mat''wid mismo?<br/>',NULL,39089,2);
INSERT INTO stanza VALUES('T20','3','I-yong tinanggap Amang Diyos,<br/>Kahalili''y si Hesus;<br/>Hinatulan ang matuwid,<br/>Para sa di-matuwid.<br/>Lumuklok Siya sa Iyong kanan,<br/>Saksi ng Iyong kat''wiran;<br/>Binigyan Kang kasiyahan<br/>Angkop sa Iyong kai-langan.<br/>',NULL,39090,3);
INSERT INTO stanza VALUES('T20','4','Dahil sa dugo ni Hesus,<br/>Kat''wira''y aming lubos;<br/>Sa loob ng kat''wiran Mo,<br/>Naging matatag ako.<br/>Kami''y naging Iyong kat''wiran,<br/>Di na mahahatulan,<br/>Hanggang Herusalem bago,<br/>Ang aming patotoo.<br/>',NULL,39091,4);
INSERT INTO stanza VALUES('T21','1','Purihin Ka sa kat''wiran,<br/>Maging sa Iyong katarungan,<br/>Pinatotohanan.<br/>Hukom ng sangkatauhan,<br/>Lahat Mo''y makatarungan.<br/>Walang kamalian.<br/>',NULL,39092,1);
INSERT INTO stanza VALUES('T21','2','O, Ama ng kabanalan,<br/>Trono Mo''y inalalayan<br/>Ng Iyong katuwiran.<br/>Naghari sa kat''wiran Mo,<br/>Kristo, biyayang dibino,<br/>Payapa na tayo.<br/>',NULL,39093,2);
INSERT INTO stanza VALUES('T21','3','Nagsanhi ang kat''wiran Mo,<br/>Sa krus namatay Anak Mo;<br/>Pantubos natamo.<br/>Nang tinanggap katubusan,<br/>Kami''y naging makat''wiran<br/>Na may kaligtasan.<br/>',NULL,39094,3);
INSERT INTO stanza VALUES('T21','4','Iyong kat''wiran pinakita,<br/>May patawad, pagpapala,<br/>Sa sinauna nga;<br/>Nang nakita Iyong kat''wiran,<br/>Tanggap Iyong kapatawaran<br/>Sa makasalanan.<br/>',NULL,39095,4);
INSERT INTO stanza VALUES('T21','5','Lahat ay hahatulan Mo,<br/>Nang mahayag kat''wiran Mo;<br/>Huhukom si Kristo.<br/>Sa Iyong kat''wiran tatayo,<br/>Biyaya''y bibigyan ako,<br/>Magpapatotoo.<br/>',NULL,39096,5);
INSERT INTO stanza VALUES('T21','6','Kaharia''y may kat''wiran,<br/>Itatag kapayapaan<br/>Masayang samahan.<br/>Sa lupa''t langit na bago,<br/>Hihigit pa kat''wiran Mo.<br/>Tutupdin pangako.<br/>',NULL,39097,6);
INSERT INTO stanza VALUES('T22','1','Ama sinasamba namin,<br/>Kami sa Iyo''y umawit.<br/>Kay banal Mo at kay tayog,<br/>Pagsamba Iyong makamit.<br/>',NULL,39098,1);
INSERT INTO stanza VALUES('T22','2','Puso Mo, Ama''y pag-ibig,<br/>Kat''wiran ang gawa Mo;<br/>Iyong kalikasan ay banal,<br/>Ikaw ang bahagi ko.<br/>',NULL,39099,2);
INSERT INTO stanza VALUES('T22','3','Sa dugong mahal ni Hesus,<br/>Ako''y Iyong pinabanal;<br/>At sa Iyong katotohanan,<br/>Nabukod akong sakdal.<br/>',NULL,39100,3);
INSERT INTO stanza VALUES('T22','4','Sa Iyong Espiritu Santo,<br/>Napabanal nga kami;<br/>Sa espiritu, kalul''wa,<br/>At katawan nang lagi.<br/>',NULL,39101,4);
INSERT INTO stanza VALUES('T22','5','O! Hesus, banal na buhay<br/>Sa biyaya''y naangkin;<br/>Kabahagi kami''y gawin<br/>Ng Iyong kabanalan din.<br/>',NULL,39102,5);
INSERT INTO stanza VALUES('T22','6','Sa banal na Herusalem,<br/>Kabanalan ko''y puspos.<br/>Walang hanggan kong pahayag,<br/>Kabanalan Mo''y lubos.<br/>',NULL,39103,6);
INSERT INTO stanza VALUES('T23','1','Sa Iyong karunungan, Ama,<br/>Ayon sa Iyong hangad,<br/>Walang hanggang layunin Mo''y<br/>Anak ang nagtupad.<br/>',NULL,39104,1);
INSERT INTO stanza VALUES('T23','chorus','O kay yaman at kay lalim,<br/>Ng Iyong karunungan!<br/>Habag at biyaya''y doon<br/>Aming nasumpungan!<br/>',NULL,39105,2);
INSERT INTO stanza VALUES('T23','2','Kay inam ng sangnilikha,<br/>Nakita dunong Mo,<br/>Lahat ay sa Iyo nagbuhat,<br/>Sa Iyo rin tutungo.<br/>',NULL,39106,3);
INSERT INTO stanza VALUES('T23','3','Dunong sa sala''y nagpinid,<br/>Nang awa''y matanghal,<br/>Upang walang magmapuri<br/>Bukod sa Iyo Mahal.<br/>',NULL,39107,5);
INSERT INTO stanza VALUES('T23','4','Sa dunong at krus ginanap<br/>Pagtubos Mo sa ''min,<br/>Nang Ika''y aming taglayin<br/>Sa ''spiritu namin.<br/>',NULL,39108,7);
INSERT INTO stanza VALUES('T23','5','Iyong dunong naipaalam,<br/>Dahil sa ekklesia<br/>Sa lahat ng pamunuan<br/>Sa sangkalangitan.<br/>',NULL,39109,9);
INSERT INTO stanza VALUES('T23','6','Sa habag magmapuri sa<br/>Bagong Herusalem,<br/>Ang karunungan Mo''y ganap<br/>Aming aarukin.<br/>',NULL,39110,11);
INSERT INTO stanza VALUES('T24','1','Ama, biyaya''t dunong Mo<br/>Natipon kay Kristo;<br/>Kristo, aming karunungan,<br/>Pagtahak sa daan.<br/>',NULL,39111,1);
INSERT INTO stanza VALUES('T24','2','Lahat Mong plano''y sa Kanya,<br/>Biyayang daan Siya;<br/>Lahat na dunong sa Kanya,<br/>Sa Iyo nga ang gloria.<br/>',NULL,39112,2);
INSERT INTO stanza VALUES('T24','3','Katuwiran namin ay Siya,<br/>Kami''y matuwid na;<br/>Aming kabanalan ay Siya,<br/>Pinapabanal pa.<br/>',NULL,39113,3);
INSERT INTO stanza VALUES('T24','4','Katubusan din sa ''min Siya,<br/>Sa plano Mo Ama;<br/>Nang kami''y ganap matubos,<br/>Tao''y malubos.<br/>',NULL,39114,4);
INSERT INTO stanza VALUES('T24','5','Sa Iyong ekonom''ya, Ama,<br/>Iyong karunungan Siya;<br/>Dahil nga sa Kanya kami<br/>Sa Iyo''y pumupuri.<br/>',NULL,39115,5);
INSERT INTO stanza VALUES('T24','6','Hayag Iyong dunong sa Kanya,<br/>Malalim, sagana;<br/>Nguni''t higit yaman, lalim<br/>Daan Mo sa amin.<br/>',NULL,39116,6);
INSERT INTO stanza VALUES('T25','1','Ama Iyong pinamalas sa amin<br/>Ang Iyong habag;<br/>Kaming makasalana''y inari<br/>Bilang anak.<br/>Sisidlang awa, hinanda kami;<br/>Sisidlang dangal, Ika''y ibunyi.<br/>',NULL,39117,1);
INSERT INTO stanza VALUES('T25','2','"Sa awa''t di sa hain galak Ko,"<br/>Iyong hinayag;<br/>Sa Iyong harap kami''y nagsisalo<br/>Ng Iyong habag.<br/>Di sa nagsitakbo''t nagsigawa,<br/>Ang lahat ay sa awa nagmula.<br/>',NULL,39118,2);
INSERT INTO stanza VALUES('T25','3','Awa''t b''yaya Mo aming nakamtan<br/>At pag-ibig;<br/>Sa Iyong awa kami''y kaharap Mo,<br/>Nanatili;<br/>Para sa Iyo kami''y nagsisamba<br/>Sa walang katapusan Mong awa.<br/>',NULL,39119,3);
INSERT INTO stanza VALUES('T26','1','Purihin Ka sa Iyong awa,<br/>Kay lalim, kay dakila!<br/>Sa ''ming kabigua''t hina;<br/>Habag Mo ay sagana.<br/>Awa Mo''y nagtaas sa ''min,<br/>Dapat Ka ngang sambahin.<br/>',NULL,39120,1);
INSERT INTO stanza VALUES('T26','2','Mangha kami sa Iyong awa,<br/>Ang abot ay kay haba!<br/>Sa aming makasalanan,<br/>Habag Mo''y tumatangan.<br/>Anong makapagwawalay<br/>Sa habag Mong ''binigay?<br/>',NULL,39121,2);
INSERT INTO stanza VALUES('T26','3','O salamat sa Iyong awa,<br/>Kay yaman, kay sagana!<br/>Sa awang may katubusan,<br/>Kami''y naalagaan.<br/>Anong pag-ibig matamo<br/>Kung di nga sa awa Mo?<br/>',NULL,39122,3);
INSERT INTO stanza VALUES('T26','4','Iyong habag may inspirasyon,<br/>Matamis, mahinahon!<br/>Sa Iyong habag natugunan,<br/>Lahat naming kailangan.<br/>Kalubusan ng Iyong awa,<br/>Aming minahalaga.<br/>',NULL,39123,4);
INSERT INTO stanza VALUES('T26','5','Tinatamasa Iyong awa,<br/>Laging bago''t sariwa<br/>Gaya''y hamog sa pagdating<br/>Bawa''t umaga sa ''min.<br/>Purihin Ka sa Iyong awa,<br/>Nakapananariwa!<br/>',NULL,39124,5);
INSERT INTO stanza VALUES('T26','6','Di mapatid ang papuri,<br/>Sa awang namalagi.<br/>Iyong biyaya''t pag-alaga,<br/>Awa Mo''y nagtalaga.<br/>Kailanma''y di mapahiya,<br/>Sa maa''sahang awa!<br/>',NULL,39125,6);
INSERT INTO stanza VALUES('T27','1','Tayong lahat magsiawit,<br/>Diyos Ama''y pag-ibig.<br/>Magpuri ang lupa''t langit;<br/>Diyos Ama''y pag-ibig.<br/>Lahat sa sala bumangon,<br/>Nang dahil sa Panginoon,<br/>Mula sa puso''y umawit,<br/>Diyos Ama''y pag-ibig!<br/>',NULL,39126,1);
INSERT INTO stanza VALUES('T27','2','Kay galak ating bahagi!<br/>Diyos Ama''y pag-ibig.<br/>Pangako Niya nag-aaliw;<br/>Diyos Ama''y pag-ibig.<br/>Siya''y ating kalasag, araw,<br/>Tulong, asa, lakas, tanglaw,<br/>Kasama natin sa landas,<br/>Diyos Ama''y pag-ibig!<br/>',NULL,39127,2);
INSERT INTO stanza VALUES('T27','3','Sa gloria muling aawit,<br/>Diyos Ama''y pag-ibig.<br/>Ito''y maging ating himig,<br/>Diyos Ama''y pag-ibig.<br/>Pagsapit ng walang hanggan,<br/>Sabay sa langit awitan<br/>Awit pa ring ubod-tamis,<br/>Diyos Ama''y pag-ibig!<br/>',NULL,39128,3);
INSERT INTO stanza VALUES('T28','1','Pag-ibig ng Diyos ay dakila<br/>Kaysa maisasatula.<br/>Lampas sa malayong tala<br/>Sagad sa napakababa.<br/>Unang pares ang nagkasala,<br/>Hesus nama''y nagtubos;<br/>Silang lahat pinagkasundo,<br/>Pinatawad nang lubos.<br/>',NULL,39129,1);
INSERT INTO stanza VALUES('T28','chorus','Wagas na pagsinta ng Diyos<br/>Tapat at di masukat!<br/>Awit ng banal at anghel<br/>Ay di makasapat.<br/>',NULL,39130,2);
INSERT INTO stanza VALUES('T28','2','''Pag panahon ay lumipas,<br/>Kaharia''y magsibagsak,<br/>Kapag tanan di manalangin,<br/>Sa bundok ay magsitawag;<br/>Ang pagsinta ng Diyos ay wagas<br/>At di matitinag;<br/>Mapanubos na biyaya<br/>Kay Adam ''nilagak.<br/>',NULL,39131,3);
INSERT INTO stanza VALUES('T28','3','Ang dagat ma''y maging tinta,<br/>Ang langit ma''y sulatan pa;<br/>Bawa''t sanga maging panulat,<br/>Bawa''t isa''y manunulat;<br/>Ang dagat ay maiiga,<br/>Langit ma''y kulang pa,<br/>Kung isulat na talaga<br/>Ang Kanyang pagsinta.<br/>',NULL,39132,5);
INSERT INTO stanza VALUES('T29','1','Ano ngang dahilan,<br/>Anak Mo''y bitiwan.<br/>Para sa salarin<br/>Na katulad namin?<br/>O walang hanggang pagsinta,<br/>Nagtulak na ibigay Siya!<br/>',NULL,39133,1);
INSERT INTO stanza VALUES('T29','2','Ano ngang dahilan<br/>Trono ay iniwan;<br/>Dugo Niya''y binubo,<br/>Buhay Niya''y napugto?<br/>O walang hanggang pagsinta,<br/>Nagtulak na mamatay Siya!<br/>',NULL,39134,2);
INSERT INTO stanza VALUES('T29','3','Ano ang humipo,<br/>Upang ang ''Spiritu,<br/>Iyong pinaparito,<br/>Pun''an aming puso?<br/>O walang hanggang pagsinta,<br/>Nagtulak na utusan Siya!<br/>',NULL,39135,3);
INSERT INTO stanza VALUES('T29','4','Anong pagkautang!<br/>Di mababayaran!<br/>Dakilang pagsinta,<br/>Lubos na biyaya.<br/>Gawin Mong may kakayahan,<br/>Ika''y lubos papurihan!<br/>',NULL,39136,4);
INSERT INTO stanza VALUES('T30','1','Anong pag-ibig handog Mo!<br/>Salamat Ama ko;<br/>Kami''y sumasamba sa Iyo,<br/>Purihin lahat Mo!<br/>',NULL,39137,1);
INSERT INTO stanza VALUES('T30','2','Puso Mo''y bukas sa amin,<br/>Hayag ang layunin;<br/>Sa Anak Ika''y dumating,<br/>Layon Mo''y tutupdin.<br/>',NULL,39138,2);
INSERT INTO stanza VALUES('T30','3','''Binigay Mo ang Iyong Anak,<br/>Dumating, namatay;<br/>Upang kami''y maging anak,<br/>Nagmamanang tunay.<br/>',NULL,39139,3);
INSERT INTO stanza VALUES('T30','4','Sa Kanya''y taglay buhay Mo,<br/>At Ama Ka namin;<br/>Ang kalikasan Mo Mismo,<br/>''Binahagi sa ''min.<br/>',NULL,39140,4);
INSERT INTO stanza VALUES('T30','5','Sa amin Iyong Espiritu—<br/>Tawag: "Abba, Ama";<br/>''Sinilang ng Espiritu<br/>Upang matransporma.<br/>',NULL,39141,5);
INSERT INTO stanza VALUES('T30','6','Layunin Mo''y mga anak<br/>Sa l''walhati''y dalhin;<br/>Mapawangis sa Iyong Anak,<br/>Kami ay gagawin.<br/>',NULL,39142,6);
INSERT INTO stanza VALUES('T30','7','Transpormasyon Mong gawain<br/>Kami''y gagabayan,<br/>Sa luwalhati dadalhin<br/>Hanggang magampanan.<br/>',NULL,39143,7);
INSERT INTO stanza VALUES('T30','8','Anong pag-ibig handog Mo!<br/>Salamat kailanman,<br/>Kailan ma''y sasamba sa Iyo,<br/>Puri''y walang hanggan.<br/>',NULL,39144,8);
INSERT INTO stanza VALUES('T31','1','Kasalanan, kamatayan,<br/>Dati tayo''y tangan;<br/>Sa Iyo utang namin lahat,<br/>O Diyos ng biyaya.<br/>',NULL,39145,1);
INSERT INTO stanza VALUES('T31','2','Hinanap ng Iyong pag-ibig,<br/>Kami''y inakit Mo;<br/>Kay Kristo kami''y manalig,<br/>At Siyang buhay namin.<br/>',NULL,39146,2);
INSERT INTO stanza VALUES('T31','3','Mga banal asa natin,<br/>Anuman marating,<br/>Kapag Hesus ay dumating,<br/>Sa Kanya''y utang din.<br/>',NULL,39147,3);
INSERT INTO stanza VALUES('T31','4','Pag-ibig ng Diyos — dakila,<br/>Ano ang kapalit?<br/>Higit sa ''ming pag-unawa,<br/>Banal! Di masambit!<br/>',NULL,39148,4);
INSERT INTO stanza VALUES('T31','5','Ama, malaman kong lalo:<br/>Diyos na katulad Mo,<br/>Nararapat na magtamo<br/>Ng puso''t buhay ko.<br/>',NULL,39149,5);
INSERT INTO stanza VALUES('T31','6','Kung tao''y nais gantihan,<br/>Yaring pag-ibig Mo,<br/>Sa gayon siya''y sadyang mangmang<br/>Sa l''wang, lalim nito.<br/>',NULL,39150,6);
INSERT INTO stanza VALUES('T31','7','Kaya di dapat tawaran<br/>Mahal Mong pagsinta:<br/>Pag-ibig Mong nagpasakit,<br/>Sinong magkakamit?<br/>',NULL,39151,7);
INSERT INTO stanza VALUES('T31','8','Yayamang ang pag-ibig Mo''y<br/>Di-mapapantayan,<br/>Puri''t pasalamat sa Iyo<br/>Walang katapusan.<br/>',NULL,39152,8);
INSERT INTO stanza VALUES('T31','9','Kami''y nagkautang sa Iyo,<br/>Ama ng pagsinta,<br/>Tanawing pasasalamat,<br/>Bigay sa Iyo dapat.<br/>',NULL,39153,9);
INSERT INTO stanza VALUES('T32','1','Kagila-gilalas, Ama<br/>Iyong pag-ibig sambahin Ka!<br/>Ang tao''y Iyong inalala<br/>Pinatunayan biyaya!<br/>',NULL,39154,1);
INSERT INTO stanza VALUES('T32','2','Purihin Ka sa layon Mo,<br/>Nang tao''y makawangis Mo;<br/>Iyong buhay, likas siya''y punan.<br/>Mahayag niya Iyong larawan.<br/>',NULL,39155,2);
INSERT INTO stanza VALUES('T32','3','Nilikha sa Iyong larawan,<br/>At awtoridad ''binigyan;<br/>Buhay Mo siya''y dinulutan,<br/>Yaman Mo''y katamasahan.<br/>',NULL,39156,3);
INSERT INTO stanza VALUES('T32','4','Ang layunin Mo sa tao,<br/>Makapasok, maihalo;<br/>Nang matransporma ang tao,<br/>Iyong tahanan maitayo.<br/>',NULL,39157,4);
INSERT INTO stanza VALUES('T32','5','Kahit natisod ang tao,<br/>Di Mo iniwan layon Mo;<br/>Nahayag sa pagtubos Mo,<br/>Ang pag-ibig at dunong Mo.<br/>',NULL,39158,5);
INSERT INTO stanza VALUES('T32','6','Naihayag Ka kay Kristo<br/>Na katubusa''y binuo;<br/>Sa ''Spiritu pumasok Ka,<br/>Bilang buhay at biyaya.<br/>',NULL,39159,6);
INSERT INTO stanza VALUES('T32','7','Kabanal-banalang dako,<br/>Ang akin ngang espiritu;<br/>Luklukan din ng biyaya<br/>Ika''y makasalamuha.<br/>',NULL,39160,7);
INSERT INTO stanza VALUES('T32','8','Mula trono ng biyaya,<br/>Agos tulad ng ilog Siya<br/>Sa pagdaloy natransporma<br/>Nang maitayong bahay Niya.<br/>',NULL,39161,8);
INSERT INTO stanza VALUES('T32','9','Biyayang walang kahambing,<br/>Kaloob dinulot sa ''min;<br/>Pag-ibig Mo''y kay dakila,<br/>Salamat, masasamba Ka.<br/>',NULL,39162,9);
INSERT INTO stanza VALUES('T33','1','Ama, bago Ka naglikha,<br/>Kami''y hinirang Mo na;<br/>Sa pag-ibig Mong kay lalim,<br/>Kay Kristo, Iyong dinala,<br/>Kami ay Iyong iingatan,<br/>Kay Kristo itatatag,<br/>Kay Kristo itatatag.<br/>',NULL,39163,1);
INSERT INTO stanza VALUES('T33','2','Kahit magbago ang mundo,<br/>Diyos natin Siya''y pareho;<br/>Kahabagan Niya at tipan,<br/>Manatili kailanman.<br/>Mga anak ng Diyos dapat<br/>Purihin ang ngalan Niya,<br/>Purihin ang ngalan Niya.<br/>',NULL,39164,2);
INSERT INTO stanza VALUES('T33','3','Habag ng Diyos salaysay ko<br/>Sa lahat ng araw ko;<br/>Walang patid awang bigay<br/>Sa aki''y gumagabay.<br/>Pag-ibig ng Diyos sa atin,<br/>Anak Niya''y ibinigay,<br/>Anak Niya''y ibinigay.<br/>',NULL,39165,3);
INSERT INTO stanza VALUES('T33','4','Sa harap Mo, Ama namin,<br/>Pagsinta Mo''y purihin;<br/>Hanggang si Hesus makita,<br/>Pag-awit tuloy pa rin.<br/>L''walhatiin, l''walhatiin,<br/>Ang Diyos at ang Kordero,<br/>Ang Diyos at ang Kordero.<br/>',NULL,39166,4);
INSERT INTO stanza VALUES('T34','1','Ama, bago ang sanlibutan kami''y Iyong pinili;<br/>Ang pag-ibig Mo sa amin kay Hesus nabighani;<br/>Kami''y iingatan lagi,<br/>Ngayon at walang hanggan.<br/>Ngayon at walang hanggan.<br/>',NULL,39167,1);
INSERT INTO stanza VALUES('T34','2','Pag-ibig di nagbabago kami''y pinaligiran<br/>Nang kami''y pinagtatanggol ng Iyong kapangyarihan;<br/>Diyos at Ama, Diyos at Ama,<br/>Pagsamba namin ay Iyo.<br/>Pagsamba namin ay Iyo.<br/>',NULL,39168,2);
INSERT INTO stanza VALUES('T34','3','Diyos ng pag-ibig, sinasamba ng aming kalul''wa,<br/>Hanggang sa Iyong paanan ialay aming korona.<br/>Pagpupuri at pagsamba<br/>Sa Diyos at sa Kordero.<br/>Sa Diyos at sa Kordero.<br/>',NULL,39169,3);
INSERT INTO stanza VALUES('T35','1','Ama, sinasamba Ka namin,<br/>Kadakilaa''y purihin;<br/>Espiritu Mo''y papurihan,<br/>Dulot Mo''y kapangyarihan.<br/>',NULL,39170,1);
INSERT INTO stanza VALUES('T35','2','Ang Taong nasa Iyong presensiya,<br/>Naluklok, itinaas Siya;<br/>Sa Iyong lakas Siya''y Iyong binuhay,<br/>Dating kabilang sa patay.<br/>',NULL,39171,2);
INSERT INTO stanza VALUES('T35','3','L''walhating sa ami''y humirang,<br/>Ama, ang siyang pinagmulan;<br/>Maging pag-ibig na nagtubos,<br/>Na ''sinagawa kay Hesus.<br/>',NULL,39172,3);
INSERT INTO stanza VALUES('T35','4','Sa pagka-anak ''tinalaga,<br/>Purihin Ka sa biyaya;<br/>Sumasamba sa presensya Mo,<br/>''Pagkat kami''y na kay Kristo.<br/>',NULL,39173,4);
INSERT INTO stanza VALUES('T36','1','Amang Diyos, purihin Ka,<br/>Kami''y pinagpala,<br/>Sa Iyong ikasisiya<br/>Ika''y sinasamba:<br/>''Tinakda Mo no''ng una<br/>Mga anak sa gloria—<br/>Kristong Mahal kasama,<br/>Kami''y Iyong adhika.<br/>',NULL,39174,1);
INSERT INTO stanza VALUES('T36','2','Ama sino pa kaya<br/>Sa ''min magpapala:<br/>Espiritu''y tamasa,<br/>May buhay, biyaya?<br/>Kristo kami''y sasama,<br/>Sa luwalhati Niya<br/>Doon Ika''y makita,<br/>Aaninagin Ka.<br/>',NULL,39175,2);
INSERT INTO stanza VALUES('T37','1','Sa Kordero, Diyos nakita,<br/>Pag-asa, galak, pahinga;<br/>Ang buting nasa Ngalan Mo,<br/>Pawang ngang pagpapala ko.<br/>',NULL,39176,1);
INSERT INTO stanza VALUES('T37','2','Amang mabuti''t dakila,<br/>Matuwid at marunong pa;<br/>Diyos, kami''y napasa I-yo,<br/>Supling, binili ng dugo.<br/>',NULL,39177,2);
INSERT INTO stanza VALUES('T37','3','O dulot ng Iyong biyaya,<br/>Di maantig kung wala Ka;<br/>Aming bantay presensya Mo,<br/>Lugod — sakdal pag-ibig Mo.<br/>',NULL,39178,3);
INSERT INTO stanza VALUES('T37','4','Lagi kaming nagagalak,<br/>Dilim ay naging liwanag.<br/>Mahinang tinig lalak''san,<br/>Ika''y laging papurihan.<br/>',NULL,39179,4);
INSERT INTO stanza VALUES('T38','1','Kaloob ng Iyong pag-ibig<br/>Wala nang hihigit,<br/>Kay Hesus at Kanyang dugo.<br/>Mabuting Ama ko.<br/>',NULL,39180,1);
INSERT INTO stanza VALUES('T38','2','Sa gayon ding pag-ibig Mo,<br/>Tiwala''y matamo;<br/>Kundi dahil sa biyaya<br/>Kaloob ay bigo.<br/>',NULL,39181,2);
INSERT INTO stanza VALUES('T38','3','Lahat utang sa Iyo namin,<br/>Higit Kang purihin:<br/>Tanging Manliligtas, lakas<br/>Siya ay napataas.<br/>',NULL,39182,3);
INSERT INTO stanza VALUES('T39','1','Luwalhati sa Diyos, gawang dakila,<br/>Inibig tayo, Anak ''binigay Niya;<br/>Buhay nasawi, nang tayo''y tubusin<br/>Pinto ng buhay binuksan sa atin.<br/>',NULL,39183,1);
INSERT INTO stanza VALUES('T39','chorus','Purihin ang Di-yos, pakinggan ng lahat,<br/>Purihin ang Di-yos, matuwa ang lahat,<br/>Halina tayo sa mahal na Ama,<br/>Purihin ang Kanyang dakilang gawa.<br/>',NULL,39184,2);
INSERT INTO stanza VALUES('T39','2','Katubusang ganap, itong pangako,<br/>Para sa bawa''t binili ng dugo,<br/>Sa maysalang maniwala nang ganap<br/>Patawad ni Hesus kanyang matanggap.<br/>',NULL,39185,3);
INSERT INTO stanza VALUES('T39','chorus','Purihin ang Di-yos, pakinggan ng lahat,<br/>Purihin ang Di-yos, matuwa ang lahat,<br/>Halina tayo sa mahal na Ama,<br/>Purihin ang Kanyang dakilang gawa.<br/>',NULL,39186,4);
INSERT INTO stanza VALUES('T39','3','Dakilang bagay ako''y tinuruan<br/>Dahil sa Anak lubhang kagalakan;<br/>Nguni''t higit na dalisay, dakila<br/>Ang pagmangha nang si Hesus makita.<br/>',NULL,39187,5);
INSERT INTO stanza VALUES('T39','chorus','Purihin ang Di-yos, pakinggan ng lahat,<br/>Purihin ang Di-yos, matuwa ang lahat,<br/>Halina tayo sa mahal na Ama,<br/>Purihin ang Kanyang dakilang gawa.<br/>',NULL,39188,6);
INSERT INTO stanza VALUES('T40','1','Purihin Ka Diyos sa Anak Mong mahal,<br/>Namatay Siya at pumasalangit sakdal.<br/>',NULL,39189,1);
INSERT INTO stanza VALUES('T40','chorus','Luwalhati para sa Iyo!<br/>Aleluya! Amen!<br/>Luwalhati para sa Iyo!<br/>Ulitin, Amen!<br/>',NULL,39190,2);
INSERT INTO stanza VALUES('T40','2','Purihin Ka sa Espiritu Mo, Diyos,<br/>Pinakita sa amin ang Manunubos.<br/>',NULL,39191,3);
INSERT INTO stanza VALUES('T40','chorus','Luwalhati para sa Iyo!<br/>Aleluya! Amen!<br/>Luwalhati para sa Iyo!<br/>Ulitin, Amen!<br/>',NULL,39192,4);
INSERT INTO stanza VALUES('T40','3','L''walhating lubos, pawang sa Amang Diyos!<br/>Napatunayan puso Mo sa pagtubos.<br/>',NULL,39193,5);
INSERT INTO stanza VALUES('T40','chorus','Luwalhati para sa Iyo!<br/>Aleluya! Amen!<br/>Luwalhati para sa Iyo!<br/>Ulitin, Amen!<br/>',NULL,39194,6);
INSERT INTO stanza VALUES('T40','4','Purihin Ka pa! Napuspusan kami<br/>Ng pag-ibig; ang puso''y nagningas muli.<br/>',NULL,39195,7);
INSERT INTO stanza VALUES('T40','chorus','Luwalhati para sa Iyo!<br/>Aleluya! Amen!<br/>Luwalhati para sa Iyo!<br/>Ulitin, Amen!<br/>',NULL,39196,8);
INSERT INTO stanza VALUES('T41','1','Di kami mapagod sa walang hanggang awit,<br/>Gloria sa Diyos, Aleluya!<br/>Malakas aming espiritu, nagpupuri,<br/>Gloria sa Diyos, Aleluya!<br/>',NULL,39197,1);
INSERT INTO stanza VALUES('T41','chorus','Ang mga anak ng Diyos, umawit nang masigla,<br/>Sa Kanyang biyaya tayo''y tutungo sa gloria,<br/>At sa araw na yaon ang Hari ko''y makita,<br/>Gloria sa Diyos, Aleluya!<br/>',NULL,39198,2);
INSERT INTO stanza VALUES('T41','2','Nababad sa galak ng Kanyang katubusan,<br/>Gloria sa Diyos, Aleluya!<br/>Sa bawa''t sandali biyaya''y patunayan,<br/>Gloria sa Diyos, Aleluya!<br/>',NULL,39199,3);
INSERT INTO stanza VALUES('T41','3','Sa l''walhati ng Panginoon paroroon,<br/>Gloria sa Diyos, Aleluya!<br/>Kagandahan ng Hari makikita roon,<br/>Gloria sa Diyos, Aleluya!<br/>',NULL,39200,5);
INSERT INTO stanza VALUES('T41','4','Doon may bagong awit ukol sa biyaya,<br/>Gloria sa Diyos, Aleluya!<br/>Pagpuri sa Manliligtas banal dadagsa,<br/>Gloria sa Diyos, Aleluya!<br/>',NULL,39201,7);
INSERT INTO stanza VALUES('T42','1','Kami''y tinawag Mo, Diyos<br/>Nang masdan Iyong Anak<br/>Siya ang mahal Mong lubos<br/>At Iyong kalooban;<br/>Sa tanging kayamanan<br/>Sarili''y binuhos,<br/>Pag-ibig Mo''y makamtan,<br/>Naising magtubos.<br/>',NULL,39202,1);
INSERT INTO stanza VALUES('T42','2','Ama — O Diyos ng awa!<br/>Aming karapatan,<br/>Maningning na pag-asa,<br/>Kay Kristong pangalan:<br/>Ang himig na Iyong nais<br/>Na laging marinig,<br/>Kami''y malayang labis<br/>Sa sala at nginig.<br/>',NULL,39203,2);
INSERT INTO stanza VALUES('T42','3','Tao''y natatakot na<br/>Diyos di makalimot;<br/>Nguni''t sala''y limot na<br/>Sa bayad na dulot.<br/>Wala nang kalayaan<br/>Sa ''ting kaluluwa,<br/>Kundi ang kamatayan<br/>N''yaong Sinisinta.<br/>',NULL,39204,3);
INSERT INTO stanza VALUES('T42','4','Walang poot sa puso<br/>Ng Diyos tungo sa ''tin,<br/>Pangamba ay nagupo,<br/>Pag-ibig Niya''y kamtin;<br/>Alibugha''y hinagkan,<br/>Damit ay ''sinuot;<br/>Ganap Niyang pag-ibig ang<br/>Nagtanggal ng takot.<br/>',NULL,39205,4);
INSERT INTO stanza VALUES('T43','1','O lumalapit sa Ama,<br/>Nang dahil sa ngalan Niya.<br/>Pagpapala''y bigay ngayon,<br/>Sa aming pagtitipon.<br/>Dugo naghugas sa sala,<br/>Kaya''t nakadulog na;<br/>Iyong Espiritu''y nagturo<br/>Tawag "Abba Ama" ko!<br/>',NULL,39206,1);
INSERT INTO stanza VALUES('T43','2','Kami''y alibugha noon,<br/>Hiwalay, walang layon.<br/>Biyayang higit sa sala,<br/>Nagligtas sa pagdusa.<br/>Naramitan kaligtasan,<br/>Bahagi''y sa Iyong dulang.<br/>Sa yaman ng Iyong biyaya,<br/>Sama-samang magsaya!<br/>',NULL,39207,2);
INSERT INTO stanza VALUES('T43','3','Patawad sa alibugha,<br/>Hinagkan pa ng Ama;<br/>Pinatay para sa kanya<br/>Ang pinatabang guya.<br/>Sabi Mo, "Magalak tayo."<br/>Dating patay anak ko<br/>Ngayon muling nabuhay na<br/>Ang nawala''y nakita!<br/>',NULL,39208,3);
INSERT INTO stanza VALUES('T43','4','Abba Ama, sambahin Ka,<br/>Mga anghel namangha<br/>Sa Iyong dunong at pagsinta,<br/>Sa ''mi''y nakita nila.<br/>Di lalao''y sa Iyong trono,<br/>Ihahayag Ama ko:<br/>Pag-ibig Mo sa pagtubos;<br/>Pangalan Mo''y kay puspos!<br/>',NULL,39209,4);
INSERT INTO stanza VALUES('T44','1','Ama sa pagsinta Iyong ''binigay,<br/>Anak mo sa ''min upang mamatay,<br/>Para sa amin Siya''y sumasamo,<br/>Kami''y lumapit sa ''sang ''Spiritu,<br/>Kanin tinapay, inumin saro,<br/>Sinasamo Kanyang sakripisyo.<br/>',NULL,39210,1);
INSERT INTO stanza VALUES('T44','2','Hindi karapat-dapat matawag,<br/>Na kami nga ay Iyong mga anak;<br/>Nguni''t tingnan kaming nagsisisi,<br/>Ikaw Manananggol, Saserdote;<br/>Iyong damit awa ang pumalibot<br/>Pektoral ay habag di matarok.<br/>',NULL,39211,2);
INSERT INTO stanza VALUES('T44','3','Kami''y pakinggan gaya sa Kanya<br/>Kami''y masdan, may dugong mahal Niya,<br/>Sa gitna ng kerubin sumilay,<br/>Pagkaing makalangit ibigay<br/>Nang matikman darating l''walhati<br/>Pagpala ng Ama''t Kanyang ngiti.<br/>',NULL,39212,3);
INSERT INTO stanza VALUES('T44','4','Ama sa Iyong luklukan ng awa,<br/>May garantiya''t lalong malaya<br/>Aming puso sa Iyo''y inialay,<br/>Pati lahat naming tinataglay.<br/>Kusang loob na Ika''y handugan,<br/>Maging ang papuring walang hanggan!<br/>',NULL,39213,4);
INSERT INTO stanza VALUES('T45','1','Abba Ama, purihin Ka,<br/>Sa Iyo ay sumasamba;<br/>Ang makilala Ka, Ama,<br/>Ay aming pagpapala.<br/>Dahil sa dugo ni Kristo,<br/>Karapatan natamo.<br/>''Spiritu Mo''t ''spiritu ko<br/>Saksing kami''y anak Mo.<br/>',NULL,39214,1);
INSERT INTO stanza VALUES('T45','2','Mundo bago pa natatag,<br/>Kay Kristo Iyong binalak.<br/>Maitalagang anak Mo,<br/>Iyong buhay ri''y matamo.<br/>Abba Ama, Iyong pagsinta,<br/>Kami''y minahalaga;<br/>Nang kaming makasalanan<br/>Iyong likas bahaginan.<br/>',NULL,39215,2);
INSERT INTO stanza VALUES('T45','3','Kahit tisod kalikasan<br/>At sa Diyos ay nasar''han,<br/>Ang walang hanggang payo Mo<br/>Nagpalapit sa dugo;<br/>Katubusan, grasya, gloria,<br/>Sa Iyong Anak nakita;<br/>O, taas, lalim ng awa!<br/>Kristo''t kami''y nagkai-sa.<br/>',NULL,39216,3);
INSERT INTO stanza VALUES('T45','4','Sa panahong nagbabago,<br/>May sakit, lungkot, gulo,<br/>Di mabago Iyong pagsinta<br/>Sa ami''y nagdadala<br/>Sa luklukan Mo''y haharap.<br/>Kami''y Iyong mga anak<br/>Sasaysayin Iyong pagligtas,<br/>Pupuring walang wakas.<br/>',NULL,39217,4);
INSERT INTO stanza VALUES('T46','1','Iyong kaluguran, O Diyos,<br/>Kay Kristo''y natalos.<br/>O biyayang mayaman.<br/>Sukat walang hanggan!<br/>Bilang Tao sa langit,<br/>Sa Iyo Siya''y sumapit;<br/>L''walhati Mo''y natuon,<br/>Sa Kanyang Iyong layon.<br/>',NULL,39218,1);
INSERT INTO stanza VALUES('T46','2','Pag-ibig nakikita,<br/>Sa Kanya ngang mukha.<br/>Liwanag sumisilay,<br/>Sa Kanya ngang buhay<br/>Liwanag at pagsinta,<br/>Tinanghal ang Ama;<br/>Biyaya''y naihayag,<br/>Bahagi ay Anak.<br/>',NULL,39219,2);
INSERT INTO stanza VALUES('T46','3','Pinagmulan ng lahat,<br/>Pagpapala''t galak!<br/>Masayang mga banal,<br/>Ngalan Mo''y itanghal!<br/>Bawa''t puso''y nagpuri,<br/>Sa kapuri-puri.<br/>Bawa''t tinig sumamba,<br/>Ang Diyos ay pagsinta!<br/>',NULL,39220,3);
INSERT INTO stanza VALUES('T47','1','Purihin Iyong ngalan, Ama,<br/>Turo ng biyaya;<br/>Sa kat''wiran naitaas<br/>Ang puso sa galak.<br/>',NULL,39221,1);
INSERT INTO stanza VALUES('T47','2','Kaligtasang katibayan<br/>Dapat papurihan<br/>Sa makalangit na trono,<br/>Nakatuon puso.<br/>',NULL,39222,2);
INSERT INTO stanza VALUES('T47','3','Walang hanggang magdeklara,<br/>Yaman ng biyaya;<br/>Sa mga makabahagi,<br/>Sa Anak palagi.<br/>',NULL,39223,3);
INSERT INTO stanza VALUES('T47','4','Naghihintay, may pag-asa,<br/>Bagama''t sa lupa<br/>''Pagka''t kami''y Iyong kukunin,<br/>Ika''y makapiling.<br/>',NULL,39224,4);
INSERT INTO stanza VALUES('T47','5','Kay galak kapuspusan<br/>Parteng walang hanggan.<br/>Gaya ng Anak manahan,<br/>Sa kal''walhatian.<br/>',NULL,39225,5);
INSERT INTO stanza VALUES('T47','6','Ama, sa mahal Mong ngalan,<br/>Kami''y Iyong ingatan.<br/>Walang takot tatahakin,<br/>Nais Mo''y tutupdin.<br/>',NULL,39226,6);
INSERT INTO stanza VALUES('T48','1','Pinupuri Ka Ama,<br/>Kami''y nagsasaya;<br/>Sa Kanyang katayuan,<br/>Walang kamatayan.<br/>Nabubuhay ''sang Tao,<br/>Sa kanan ng trono,<br/>Patuloy na pagsinta,<br/>Mayamang biyaya.<br/>',NULL,39227,1);
INSERT INTO stanza VALUES('T48','2','Ama Niya''y Ama namin,<br/>Diyos Niya''y, Diyos din namin;<br/>Siya ay Iyong Sinisinta,<br/>Sa puso''y ligaya.<br/>Kami''y Kanya, Siya''y amin,<br/>Bahagi''y maangkin,<br/>Malaman Iyong biyaya,<br/>Pag-ibig at mukha.<br/>',NULL,39228,2);
INSERT INTO stanza VALUES('T48','3','Kailanma''y di lalamig,<br/>Yakap ng pag-ibig<br/>Nakatuon sa Kanya,<br/>Taos na pagsinta!<br/>Sa Kanya''y may pahinga,<br/>L''walhati''t pagsinta.<br/>Sa Kanya''y napalapit,<br/>Maraming kapatid.<br/>',NULL,39229,3);
INSERT INTO stanza VALUES('T49','1','Diyos, kami''y sumasamba,<br/>Yukong nagpipitagan;<br/>Samo''y Hesu-Kristo nga:<br/>Ama, sambahin Ka.<br/>',NULL,39230,1);
INSERT INTO stanza VALUES('T49','2','Pag-ibig kay dakila,<br/>Handog, nang namatay Siya;<br/>Ang hiling nabigyang-siya:<br/>Ama, sambahin Ka.<br/>',NULL,39231,2);
INSERT INTO stanza VALUES('T49','3','May salang dating sukal,<br/>Ngayo''y anak may rangal<br/>Kay yaman ng biyaya:<br/>Ama, sambahin Ka.<br/>',NULL,39232,3);
INSERT INTO stanza VALUES('T49','4','Sa katotohanan nga,<br/>Sa ''spiritu sumamba;<br/>Papuri insenso nga:<br/>Ama, sambahin Ka.<br/>',NULL,39233,4);
INSERT INTO stanza VALUES('T49','5','Ihandog naming muli,<br/>Malalim na papuri,<br/>Ngayon at walang hanggan:<br/>Ama, sambahin Ka.<br/>',NULL,39234,5);
INSERT INTO stanza VALUES('T50','1','Ama, Anak Mo ang nangunguna<br/>Magpuri matapos ng handaan;<br/>Kay tamis, kay mahal sa Iyo, Ama,<br/>Awit at puri sa kaisahan.<br/>',NULL,39235,1);
INSERT INTO stanza VALUES('T50','2','Bukod sa Iyo, walang kabutihan,<br/>Walang higit pa sa pag-ibig Mo;<br/>Sinasamba Ka, pagka''t natikman<br/>Kasarapan ng buhay dibino.<br/>',NULL,39236,2);
INSERT INTO stanza VALUES('T50','3','Sa Iyong pag-ibig ang pag-ibig ko<br/>Lumago, daig ang kamunduhan;<br/>Sa kalakasan ang pag-ibig Mo,<br/>Dalhin ako sa galak sukdulan.<br/>',NULL,39237,3);
INSERT INTO stanza VALUES('T50','4','Ama, ang Iyong Anak aming sundan,<br/>Papurihan Ka nang walang hanggan;<br/>Pag-ibig Mo''y aming kasiyahan,<br/>Natamasa tamis ng Iyong ngalan.<br/>',NULL,39238,4);
INSERT INTO stanza VALUES('T51','1','May tugon kami mahal na Ama,<br/>Sa pagsinta.<br/>Makalapit nang walang pangamba,<br/>Nang malaya.<br/>Kamangha-mangha, kami''y tulad Niya;<br/>Iyong kinalugdan di nagkaiba.<br/>',NULL,39239,1);
INSERT INTO stanza VALUES('T51','2','Bahagi namin ang Iyong biyaya<br/>Iyong lugod Siya!<br/>Bukod tanging pinagtuunan Siya<br/>Ng pagsinta!<br/>Katamasa Niya sa Iyong pagsinta.<br/>L''walhati Niya''y aming makikita!<br/>',NULL,39240,2);
INSERT INTO stanza VALUES('T51','3','Iyong mga Anak umaawit din,<br/>Siya''y purihin!<br/>Puso''y may ligaya, nanguna Siya.<br/>Sa pagkanta.<br/>Sa ekonomiya ng pagsinta.<br/>Ikaw ang pinagmulan, O Ama!<br/>',NULL,39241,3);
INSERT INTO stanza VALUES('T52','1','Ama, sasamba sa harapan Mo.<br/>Lahat ng Iyo,<br/>Kami''y nagtipon upang pumuri<br/>Sa Iyo tangi.<br/>Naiuwi sa Iyo ng biyaya,<br/>Kasama Niya lalapit sa Ama.<br/>',NULL,39242,1);
INSERT INTO stanza VALUES('T52','2','Ang nakababatid ng pag-ibig,<br/>Maaantig;<br/>Pag-ibig Mo''y natanaw kay Hesus,<br/>Ama Kong Diyos.<br/>Nangunguna Siya sa iyong harapan,<br/>Na Iyong pag-ibig ay papurihan.<br/>',NULL,39243,2);
INSERT INTO stanza VALUES('T52','3','Labis ang tamis sa Iyong pandinig,<br/>Kanyang awit.<br/>Gayundin ang aming mga tinig<br/>Sa Iyong dinig.<br/>Bago pa ng mundo''y inibig Siya,<br/>Iyong itinakda na kasama Niya.<br/>',NULL,39244,3);
INSERT INTO stanza VALUES('T53','1','Nahayag sa Anak Iyong pagsinta,<br/>Papurihan Iyong Ngalan, Diyos Ama.<br/>Kanyang hinamak ang kahihiyan.<br/>Upang matupad Iyong kalooban.<br/>',NULL,39245,1);
INSERT INTO stanza VALUES('T53','2','Nanguna sa maraming kapatid,<br/>Panganay na Anak sa pag-awit.<br/>Nang tinaas Niyang tinig nagpuri,<br/>Sa ''spiritu nagpuri rin kami!<br/>',NULL,39246,2);
INSERT INTO stanza VALUES('T53','3','Sa Sinisintang Anak pinili,<br/>Sa Iyong kagalaka''y may bahagi;<br/>Nang bago pa mundo''y naitakda,<br/>Nagpahiwatig ng Iyong biyaya.<br/>',NULL,39247,3);
INSERT INTO stanza VALUES('T53','4','Mga nagtamo ng pag-ibig Mo<br/>Sa ''spiritu''y lubusang nabago.<br/>Bawa''t isa may katangian Niya,<br/>Walang hanggang galak ay sa Kanya.<br/>',NULL,39248,4);
INSERT INTO stanza VALUES('T54','1','Ama, sa Iyo''y umaawit kami<br/>Karapat-dapat Ka sa papuri!<br/>Sa espiritu at realidad,<br/>Sambahin Ka namin — ang Iyong hangad.<br/>',NULL,39249,1);
INSERT INTO stanza VALUES('T54','2','Nilikha Mo ang lahat sa Anak,<br/>Lakas Niya''y nag-alalay sa lahat;<br/>Sa Iyo, kami''y lumapit sa Kanya<br/>Na nagsanhi sa aming pagsamba.<br/>',NULL,39250,2);
INSERT INTO stanza VALUES('T54','3','Sa pinagpalang kinasaklawan,<br/>Sa ekklesia''y laksan ang awitan!<br/>Ang Panganay sa amin nanguna,<br/>Sa pagpuri sa Iyo nang may laya.<br/>',NULL,39251,3);
INSERT INTO stanza VALUES('T54','4','Siya at kami dito''y nag-awitan,<br/>Ama, mabigyan Kang kasiyahan.<br/>Papuring Kanyang pinangunahan,<br/>May tahanan Ka magpakailanman.<br/>',NULL,39252,4);
INSERT INTO stanza VALUES('T55','1','Ama, kami''y dumudulog sa Iyo,<br/>Sa ilalim ng mahal Niyang dugo;<br/>Wala nang namagitan sa atin,<br/>Kami''y malaya, Ika''y purihin!<br/>',NULL,39253,1);
INSERT INTO stanza VALUES('T55','2','O Ama nais ihain sa Iyo,<br/>Ang samyo ng pangalan ni Kristo;<br/>Sa pananalig aming nakita,<br/>Ang napasaamin na biyaya.<br/>',NULL,39254,2);
INSERT INTO stanza VALUES('T55','3','Sa Iyong galak aming kasalo Siya,<br/>Sa Kanya puso ko''y may ligaya;<br/>Higit ang ganda sa laksa-laksa,<br/>Hindi kumukupas l''walhati Niya.<br/>',NULL,39255,3);
INSERT INTO stanza VALUES('T55','4','Sa harap ng Iyong trono sasamba,<br/>Sa pananalig aming nakita:<br/>Iyong Sintang Anak, mga kapatid,<br/>Nagsipagpuri nang walang patid.<br/>',NULL,39256,4);
INSERT INTO stanza VALUES('T56','1','Hesus, Ika''y Anak ng Diyos<br/>At Salitang buháy,<br/>Mal''walhating anyo ng Diyos,<br/>At wangis Niyang tunay.<br/>',NULL,39257,1);
INSERT INTO stanza VALUES('T56','2','Kapuspusan ng pagka-Diyos<br/>Nananahan sa Iyo,<br/>Pagsasakatawan ng Diyos—<br/>Diyos inihayag Mo.<br/>',NULL,39258,2);
INSERT INTO stanza VALUES('T56','3','Sinag ng l''walhati ng Diyos,<br/>Kaisa ng Ama,<br/>Tunay na larawan ng Diyos,<br/>Realidad Ka Niya.<br/>',NULL,39259,3);
INSERT INTO stanza VALUES('T56','4','Sa Iyo, Diyos ang aming buhay,<br/>Sa Iyo, Diyos ang ilaw,<br/>Tamuhin kalikasan Niya,<br/>Tayo''y makiisa.<br/>',NULL,39260,4);
INSERT INTO stanza VALUES('T56','5','Biyaya ng Diyos nasa Iyo,<br/>Diyos tamasa sa Iyo;<br/>Katotohanan nakita,<br/>Realidad ganap.<br/>',NULL,39261,5);
INSERT INTO stanza VALUES('T56','6','Ating tanggap kapuspusan—<br/>Biyaya sa b''yaya;<br/>Kami at Diyos naihalo,<br/>Ito''y sa loob Mo.<br/>',NULL,39262,6);
INSERT INTO stanza VALUES('T56','7','Panginoong Diyos, sambahin,<br/>Sa Iyo lahat namin;<br/>Mahalaga Ka sa puso,<br/>Mahalin ngalan Mo.<br/>',NULL,39263,7);
INSERT INTO stanza VALUES('T57','1','Ang larawan ng Diyos Ama,<br/>Sa Iyo''y nakikita,<br/>Kapuspusan ng Pagka-Diyos,<br/>Sa Iyo nananahan.<br/>',NULL,39264,1);
INSERT INTO stanza VALUES('T57','2','O, walang hanggang Salita,<br/>Dibinong buhay pa,<br/>Sa Iyo biyaya''y natanggap,<br/>Nang may realidad!<br/>',NULL,39265,2);
INSERT INTO stanza VALUES('T57','3','Sinag ng l''walhati ng Diyos,<br/>Anak Ka nga ng Diyos!<br/>Ika''y mismong substansiya Niya,<br/>Kami nga''y sasamba.<br/>',NULL,39266,3);
INSERT INTO stanza VALUES('T57','4','Pagsakatawan ng Diyos nga,<br/>Lagi Mo Siyang kai-sa;<br/>Nahayag sa Iyo nang lubos,<br/>Sa ''ming lahat ang Diyos.<br/>',NULL,39267,4);
INSERT INTO stanza VALUES('T57','5','Sa Iyo, Diyos aming tamasa,<br/>Buhay at lahat na;<br/>Salamat sa Iyo at sa Diyos,<br/>Purihin ngang lubos!<br/>',NULL,39268,5);
INSERT INTO stanza VALUES('T58','1','Salitang buhay ng Diyos Ka,<br/>Laging kasama Niya<br/>Iyong hinayag l''walhati Niya,<br/>Nang nasa lupa Ka.<br/>',NULL,39269,1);
INSERT INTO stanza VALUES('T58','chorus','Purihin Ka, O Salita,<br/>Sa Iyo Diyos nakita!<br/>Kanyang katangia''t gloria,<br/>Iyong ipinakita.<br/>',NULL,39270,2);
INSERT INTO stanza VALUES('T58','2','Binigkas ng kalangitan,<br/>Ang kal''walhatian.<br/>Tinanghal ng sangnilikha,<br/>Lakas at galing Niya.<br/>',NULL,39271,3);
INSERT INTO stanza VALUES('T58','3','Salita ng Diyos, kay yaman!<br/>Mapatotohanan!<br/>Nahayag Ka sa Salita,<br/>Nang Diyos makilala.<br/>',NULL,39272,5);
INSERT INTO stanza VALUES('T58','4','Naging laman Ka, Salita,<br/>Namuhay sa lupa;<br/>Lahat Mong salita''t kilos,<br/>Naihayag ay Diyos.<br/>',NULL,39273,7);
INSERT INTO stanza VALUES('T58','5','Salita, Ikaw ang buhay!<br/>Liwanag ding buháy!<br/>Buháy na nagliliwanag<br/>Nang Diyos maihayag!<br/>',NULL,39274,9);
INSERT INTO stanza VALUES('T58','6','Gagawad ng kahatulan,<br/>Makitang kat''wiran;<br/>Upang Diyos mahayag lubos,<br/>Nang lalong matalos.<br/>',NULL,39275,11);
INSERT INTO stanza VALUES('T58','7','Kahayagang lubos ng Diyos,<br/>''Pinakita ang Diyos!<br/>Hindi na nakukubli Siya,<br/>Lubos nadeklara!<br/>',NULL,39276,13);
INSERT INTO stanza VALUES('T59','1','Bugtong na Anak ng Ama,<br/>Ikaw ang Salita;<br/>Diyos na nakita''t narinig<br/>Ang Mahal ng langit.<br/>Anak ng Diyos, matagpuan,<br/>Sa Iyo Kanyang kapuspusan.<br/>',NULL,39277,1);
INSERT INTO stanza VALUES('T59','2','Sa Iyo, l''walhati ng Ama,<br/>Sakdal na nakita.<br/>Kapuspusan ng Diyos sa Iyo,<br/>Palaging dibino.<br/>Anak ng Diyos, matagpuan,<br/>Sa Iyo Kanyang kapuspusan.<br/>',NULL,39278,2);
INSERT INTO stanza VALUES('T59','3','Esensya''y di masilayan,<br/>Tunay Siyang larawan;<br/>Di-likhang Ilaw tanglawan,<br/>Nahayag puso Niya.<br/>Anak ng Diyos, matagpuan,<br/>Sa Iyo Kanyang kapuspusan.<br/>',NULL,39279,3);
INSERT INTO stanza VALUES('T59','4','Maging anghel di-malaman,<br/>Hiwaga ng Ngalan;<br/>Sarili Mong mahiwaga<br/>Anak may unawa.<br/>Anak ng Diyos, matagpuan.<br/>Sa Iyo Kanyang kapuspusan.<br/>',NULL,39280,4);
INSERT INTO stanza VALUES('T59','5','Sansinukob pinagpala,<br/>Ika''y sentro na nga;<br/>Anak ng langit na sinta.<br/>O papurihan Ka!<br/>Anak ng Diyos, matagpuan<br/>Sa Iyo Kanyang kapuspusan.<br/>',NULL,39281,5);
INSERT INTO stanza VALUES('T60','1','Bago mundo''y naitakda,<br/>Bugtong na Anak, Sinta;<br/>Pinagmulan, hanggana''y Siya,<br/>Ang Alpha at Omega.<br/>Mga bagay na sa ngayon<br/>Sa darating at noon<br/>Magpakailanpaman.<br/>',NULL,39282,1);
INSERT INTO stanza VALUES('T60','2','Ito nga Siyang noong una,<br/>Pinag-usapan nila;<br/>Pinangako sa salita,<br/>At ng mga propeta.<br/>Nagniningning na Siya ngayon<br/>Purihin Panginoon<br/>Magpakailanpaman.<br/>',NULL,39283,2);
INSERT INTO stanza VALUES('T60','3','Kataas-taasang langit,<br/>Sa Kanya''y magsiawit;<br/>Sa Kanya ay magyukuran<br/>Lahat ng pamunuan<br/>Lahat ng dila''y pupuri<br/>Sa mal''walhating Hari<br/>Magpakailanpaman.<br/>',NULL,39284,3);
INSERT INTO stanza VALUES('T60','4','Sa Diyos Ama, Sa Iyo, Kristo,<br/>Sa Espiritu Santo:<br/>Awit, pasalamat, himno.<br/>Papuring walang hinto;<br/>Tagumpay na walang hanggan,<br/>L''walhati''t karangalan.<br/>Magpakailanpaman.<br/>',NULL,39285,4);
INSERT INTO stanza VALUES('T61','1','Hesus, Anak ng Tao Ka,<br/>Taglay Mo ang pagka-tao,<br/>Isinilang ng dalaga,<br/>May katawan — laman, dugo.<br/>',NULL,39286,1);
INSERT INTO stanza VALUES('T61','2','Naging abang alipin Ka,<br/>Lumakad sa mundong api,<br/>Tiniis lahat ng dusa,<br/>Di-mabigkas na pighati.<br/>',NULL,39287,2);
INSERT INTO stanza VALUES('T61','3','Ika''y sanggol sa sabsaban,<br/>Dukhang sa ilang tumubo,<br/>Anluwaging nanungkulan,<br/>Tila salarin, pinako.<br/>',NULL,39288,3);
INSERT INTO stanza VALUES('T61','4','Binuhay Ka muli ng Diyos,<br/>Pagka-tao taglay pa rin.<br/>May anyo Ka ng pagka-Diyos,<br/>Sa langit, Tao Ka pa rin.<br/>',NULL,39289,4);
INSERT INTO stanza VALUES('T61','5','Sa luklukan naghari Ka,<br/>Tao Ka pa rin sa gloria.<br/>Tao Kang kasama ng Diyos,<br/>At kasiyahan Niyang lubos.<br/>',NULL,39290,5);
INSERT INTO stanza VALUES('T61','6','Sa l''walhati babalik Ka,<br/>Tao pa ring mapakita,<br/>Hari ng mga hari Ka<br/>Na may pantaong esensya.<br/>',NULL,39291,6);
INSERT INTO stanza VALUES('T61','7','Sa langit at lupang bago,<br/>Sa lahat Ikaw ang sentro;<br/>Magpakailanma''y dibino,<br/>Umiral sa pagka-tao.<br/>',NULL,39292,7);
INSERT INTO stanza VALUES('T62','1','Hesus aming sinasamba<br/>"Binhi ng babae" Ka;<br/>Isinilang ng dalaga,<br/>May pantaong ngalan pa;<br/>Kinuha pantaong likas,<br/>Niyurakan ang ahas;<br/>Ulo niya''y dinurog sa krus,<br/>Tinupad plano ng Diyos.<br/>',NULL,39293,1);
INSERT INTO stanza VALUES('T62','chorus','Gloria Mo''y nakita,<br/>Sa pantaong ganda;<br/>Nahayag l''walhating punô,<br/>Sa pagka-tao.<br/>',NULL,39294,2);
INSERT INTO stanza VALUES('T62','2','Sa pagkakatawang-tao,<br/>Bahagi''y laman, dugo;<br/>Satanas diyablo''y wasakin,<br/>Sa kapakanan natin;<br/>Emmanuel ang tawag sa Iyo,<br/>Hesus din pangalan Mo;<br/>Tagapagligtas Ka namin,<br/>Kaligtasan tunay rin.<br/>',NULL,39295,3);
INSERT INTO stanza VALUES('T62','chorus','Gloria Mo''y nakita,<br/>Sa pantaong ganda;<br/>Nahayag l''walhating punô,<br/>Sa pagka-tao.<br/>',NULL,39296,4);
INSERT INTO stanza VALUES('T62','3','Ang "Huling Adam" Ikaw nga,<br/>"Ikalawang tao" Ka;<br/>Ulo ng bagong nilikha,<br/>Higit kaysa taong una.<br/>Sa lupa buhay, kilos Mo<br/>Ika''y Anak ng tao;<br/>Sa langit likas pantao.<br/>Tao kahayagan Mo.<br/>',NULL,39297,5);
INSERT INTO stanza VALUES('T62','chorus','Gloria Mo''y nakita,<br/>Sa pantaong ganda;<br/>Nahayag l''walhating punô,<br/>Sa pagka-tao.<br/>',NULL,39298,6);
INSERT INTO stanza VALUES('T62','4','Sa itinakdang panahon,<br/>Babalik Panginoon;<br/>Dala l''walhati ng Ama,<br/>Tao ring magpakita.<br/>Sa trono ng paghuhusga,<br/>Anak Ka ng tao pa.<br/>Ang pantaong kalikasan,<br/>I-yo magpakailanman.<br/>',NULL,39299,7);
INSERT INTO stanza VALUES('T62','chorus','Gloria Mo''y nakita,<br/>Sa pantaong ganda;<br/>Nahayag l''walhating punô,<br/>Sa pagka-tao.<br/>',NULL,39300,8);
INSERT INTO stanza VALUES('T63','1','Purihin Pinakabanal,<br/>Sa rurok, lalim man,<br/>Salita Niya''y natatangi,<br/>Daan Niya''y palagi.<br/>',NULL,39301,1);
INSERT INTO stanza VALUES('T63','2','Nang lahat ay nasa sala<br/>Bilang huling Adam,<br/>Siya''y nagbaka at nagtubos<br/>Karunungan ng Diyos!<br/>',NULL,39302,2);
INSERT INTO stanza VALUES('T63','3','Kinatisuran ni Adam<br/>Sa laman at dugo,<br/>Pantas na pag-ibig laban<br/>Kaaway tinalo.<br/>',NULL,39303,3);
INSERT INTO stanza VALUES('T63','4','Higit na kaloob pa nga<br/>Kaysa sa biyaya,<br/>Presensya ng Diyos, Siya mismo,<br/>Esensya''y dibino.<br/>',NULL,39304,4);
INSERT INTO stanza VALUES('T63','5','O pag-ibig na sagana!<br/>Upang daanan Niya,<br/>Siyang pumaslang ay tinalo,<br/>Kaaway ng tao.<br/>',NULL,39305,5);
INSERT INTO stanza VALUES('T63','6','At sa hardin palihim nga,<br/>At itaas ng krus,<br/>Matuto ang kapatiran,<br/>Magdusa''t mamatay.<br/>',NULL,39306,6);
INSERT INTO stanza VALUES('T63','7','Purihin pinakabanal,<br/>Sa rurok, lalim man,<br/>Salita Niya''y natatangi,<br/>Daan Niya''y palagi.<br/>',NULL,39307,7);
INSERT INTO stanza VALUES('T64','1','Salaysay ng biyaya,<br/>Nakahihipo nga;<br/>Pahayag may l''walhati,<br/>Sa mukha''y naakit.<br/>Nang Larawang may ningning,<br/>Aking pagmunihin;<br/>Puso ko''y may ligaya,<br/>Puno ng pagsamba!<br/>',NULL,39308,1);
INSERT INTO stanza VALUES('T64','2','Pagka-tao''y Iyong angkin,<br/>Pagka-Diyos gayundin.<br/>Pag-ibig at damdamin,<br/>Ng Diyos at tao rin;<br/>Sa buhay, kamatayan,<br/>May kahayagan Ka;<br/>Taong mapagkumbaba,<br/>Diyos ng langit, asa.<br/>',NULL,39309,2);
INSERT INTO stanza VALUES('T64','3','Mal''walhating liwanag,<br/>O mukhang may sinag<br/>Sa biyayang Iyong gawa,<br/>Ako''y matransporma.<br/>Magiging Iyong kagaya,<br/>Makita ng mata,<br/>Sa Iyo, Anak ng tao,<br/>Mukha ng Diyos Mismo.<br/>',NULL,39310,3);
INSERT INTO stanza VALUES('T65','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39311,1);
INSERT INTO stanza VALUES('T65','1','Hesus, ang pangalan,<br/>Aming mahal;<br/>Kataas-taasan,<br/>Ngalang Hesus!<br/>Lahat Ka sa amin,<br/>Buhay at mana rin,<br/>Hindi kakapusin,<br/>Panginoon!<br/>',NULL,39312,2);
INSERT INTO stanza VALUES('T65','2','Nagkatawang-tao<br/>O Hesus ko,<br/>Sa krus ipinako,<br/>Doo''y nagdugo!<br/>Dakilang pagsinta,<br/>Pagtubos ganap na,<br/>Walang kapantay Ka,<br/>Panginoon!<br/>',NULL,39313,3);
INSERT INTO stanza VALUES('T65','3','Ikaw ang nagbigay<br/>Ng buhay ko,<br/>At aking tagumpay<br/>Buhat sa Iyo!<br/>Takot pa ba ako<br/>Sa dusa, demonyo?<br/>Ika''y Taga-alò,<br/>Panginoon!<br/>',NULL,39314,4);
INSERT INTO stanza VALUES('T65','4','Babalik Kang muli,<br/>Hesus namin!<br/>Mangagalak kami<br/>Sa Iyong pagdating!<br/>Magkikita-kita,<br/>Makawangis Mo pa,<br/>Lagi Kang kasama,<br/>Panginoon!<br/>',NULL,39315,5);
INSERT INTO stanza VALUES('T66','1','Ngalang Hesus anong tamis<br/>Sa pandinig namin,<br/>Pinaparam ang pighati,<br/>Takot pinapawi.<br/>[Takot pinapawi.<br/>Takot pinapawi.<br/>Pinaparam ang pighati,<br/>Takot pinapawi.]<br/>',NULL,39316,1);
INSERT INTO stanza VALUES('T66','2','Sa sugatang espiritu<br/>Nagpapagaling ''to;<br/>Sa pagod na kaluluwa<br/>Ito ang pahinga.<br/>[Ito ang pahinga.<br/>Ito ang pahinga.<br/>Sa pagod na kaluluwa<br/>Ito ang pahinga.]<br/>',NULL,39317,2);
INSERT INTO stanza VALUES('T66','3','Minamahal na Pangalan!<br/>Ang Batong saligan;<br/>Hindi maubos na yaman,<br/>Kalasag, kublihan.<br/>[Kalasag, kublihan.<br/>Kalasag, kublihan.<br/>Hindi maubos na yaman,<br/>Kalasag, kublihan.]<br/>',NULL,39318,3);
INSERT INTO stanza VALUES('T66','4','Hesus, ang Tagapagligtas,<br/>Pastol, Buhay, Landas,<br/>Tanggapin aming papuri,<br/>Saserdote''t Hari.<br/>[Saserdote''t Hari.<br/>Saserdote''t Hari.<br/>Tanggapin aming papuri,<br/>Saserdote''t Hari.]<br/>',NULL,39319,4);
INSERT INTO stanza VALUES('T66','5','Mahina man ang pag-ibig,<br/>Paglingap malamig,<br/>Nguni''t nang Ika''y makita<br/>Sadyang mapuri Ka.<br/>[Sadyang mapuri Ka.<br/>Sadyang mapuri Ka.<br/>Nguni''t nang Ika''y makita<br/>Sadyang mapuri Ka.]<br/>',NULL,39320,5);
INSERT INTO stanza VALUES('T66','6','Iyong pag-ibig ipagbunyi<br/>Hanggang buháy kami;<br/>Nagwawagi sa Iyong Ngalan<br/>Daig kamatayan.<br/>[Daig kamatayan.<br/>Daig kamatayan.<br/>Nagwawagi sa Iyong Ngalan<br/>Daig kamatayan.]<br/><!--(Ulitin ang huling dalawang linya ng bawa''t saknong)--><br/>',NULL,39321,6);
INSERT INTO stanza VALUES('T67','1','Ang ngalang Hesus, kay tamis,<br/>Himig nito''y aking nais,<br/>Puso ay pinaligaya<br/>Ng ngalang mahalaga.<br/>',NULL,39322,1);
INSERT INTO stanza VALUES('T67','chorus','Hesus, ngalang kay tamis,<br/>Hesus, walang kaparis,<br/>Hesus, itanyag natin,<br/>Nararapat purihin.<br/>',NULL,39323,2);
INSERT INTO stanza VALUES('T67','2','Ang ngalang Hesus, mahal ko,<br/>Kanyang talos ang hapis ko;<br/>Pangamba''y Kanyang tinapos,<br/>Mahal ko, ngalang Hesus.<br/>',NULL,39324,3);
INSERT INTO stanza VALUES('T67','chorus','Hesus, ngalang kay tamis,<br/>Hesus, walang kaparis,<br/>Hesus, itanyag natin,<br/>Nararapat purihin.<br/>',NULL,39325,4);
INSERT INTO stanza VALUES('T67','3','Laging marinig, nais ko,<br/>Hesus, aliw ng puso ko,<br/>Pinahid Niya aking luha,<br/>Ngalang Hesus, dakila!<br/>',NULL,39326,5);
INSERT INTO stanza VALUES('T67','chorus','Hesus, ngalang kay tamis,<br/>Hesus, walang kaparis,<br/>Hesus, itanyag natin,<br/>Nararapat purihin.<br/>',NULL,39327,6);
INSERT INTO stanza VALUES('T67','4','Walang wikang makasabi<br/>Ang tamis sa puso''t labi<br/>Ng ngalang dapat purihin,<br/>Ngalang Hesus, purihin!<br/>',NULL,39328,7);
INSERT INTO stanza VALUES('T67','chorus','Hesus, ngalang kay tamis,<br/>Hesus, walang kaparis,<br/>Hesus, itanyag natin,<br/>Nararapat purihin.<br/>',NULL,39329,8);
INSERT INTO stanza VALUES('T68','1','Tinawag "Hesus" Iyong ngalan,<br/>Kamangha-manghang ngalan;<br/>Nang sa tao''y nakatulad,<br/>Birhen sa Iyo''y nanganak.<br/>Jehovah-Manliligtas Ka<br/>Kami''y ''ligtas sa sala;<br/>Tagapagligtas tanggapin<br/>Dibinong buhay akin.<br/>',NULL,39330,1);
INSERT INTO stanza VALUES('T68','2','Para sa Iyong ministeryo,<br/>Tinawag Ka ring "Kristo"<br/>Pinahirang Isa ng Diyos,<br/>Naitalagang lubos.<br/>Ika''y Mesiyas ng Diyos na,<br/>Tinakda ng pagsinta.<br/>L''walhati Niya''y mahayag rin,<br/>Upang layon Niya''y tupdin.<br/>',NULL,39331,2);
INSERT INTO stanza VALUES('T68','3','Diyos Kang kasama ng tao,<br/>Sa ngalan "Emmanuel" Ka;<br/>Di mawalay Diyos at tao,<br/>Naghalo sa biyaya.<br/>May biyaya, realidad,<br/>Diyos nahayag sa laman<br/>Sa Iyo, nakita''t nakamtan,<br/>Diyos ng kal''walhatian.<br/>',NULL,39332,3);
INSERT INTO stanza VALUES('T68','4','Pangino''ng mahal, kay yaman,<br/>Ng matamis Mong ngalan;<br/>Hahawakan sa pagsinta,<br/>Ngalan Mong mahalaga.<br/>Sa Iyo''y pag-ibig pagsamba,<br/>Manliligtas na Sinta;<br/>Mal''walhating Kristo namin,<br/>Emmanuel ri''y purihin.<br/>',NULL,39333,4);
INSERT INTO stanza VALUES('T69','1','Mahal namin ngalan Mo,<br/>Luluhod sa harap Mo;<br/>L''walhati''t kapangyarihan<br/>Ikaw lamang bibigyan.<br/>Magkaisa ang himig,<br/>Ganda Mo''y aming awit.<br/>Papuri''t pasasalamat,<br/>Ika''y karapat-dapat.<br/>',NULL,39334,1);
INSERT INTO stanza VALUES('T69','2','Mahal namin ngalan Mo,<br/>Sinasalaysay nito<br/>Pag-ibig ng Diyos, bago pa<br/>Panaho''y nagsimula.<br/>Tisod na tao''y nais,<br/>Iligtas ng pag-ibig.<br/>Kaya bumaba Ka rito<br/>Gawin kaming yaman Mo.<br/>',NULL,39335,2);
INSERT INTO stanza VALUES('T69','3','Mahal namin Iyong ngalan,<br/>Sinalaysay pagsilang:<br/>Biyaya Mo''t kaamuan,<br/>At malumbay Mong daan.<br/>"Tao''ng Kapighatian",<br/>Aming hirap Iyong pasan;<br/>Ininom sarong mapait<br/>Sinuot putong, tinik.<br/>',NULL,39336,3);
INSERT INTO stanza VALUES('T69','4','Mahal namin ngalan Mo,<br/>Sa Diyos, Ika''y Kordero;<br/>Sa aming sala''y nagbubo<br/>Ng Iyong mahal na dugo.<br/>Nakaluklok sa langit,<br/>May putong na l''walhati;<br/>Tagumpay gawang natamo,<br/>Kat''wiran natin buo.<br/>',NULL,39337,4);
INSERT INTO stanza VALUES('T70','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,39338,1);
INSERT INTO stanza VALUES('T70','1','Ngalan marinig aking nais,<br/>O Hesus napakatamis;<br/>Sa pandinig ko''y tugtugin,<br/>Nais kong aawitin!<br/>',NULL,39339,2);
INSERT INTO stanza VALUES('T70','chorus','O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>Una Mo ''kong minahal.<br/>',NULL,39340,3);
INSERT INTO stanza VALUES('T70','2','Sa akin nagsasabi ito:<br/>Pag-ibig ni Hesu-Kristo;<br/>Kanyang dugong mahalaga<br/>Pagsamo ng maysala.<br/>',NULL,39341,4);
INSERT INTO stanza VALUES('T70','chorus','O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>Una Mo ''kong minahal.<br/>',NULL,39342,5);
INSERT INTO stanza VALUES('T70','3','Sa akin nagsasabi ito:<br/>Panustos ng Ama''y husto;<br/>Kahit madilim ang landas,<br/>Ang liwanag Niya''y lakas.<br/>',NULL,39343,6);
INSERT INTO stanza VALUES('T70','chorus','O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>Una Mo ''kong minahal.<br/>',NULL,39344,7);
INSERT INTO stanza VALUES('T70','4','Sa akin nagsasabi ito:<br/>Mapagmahal Ni-yang puso,<br/>Dinadala aking dusa<br/>Walang makababatá.<br/>',NULL,39345,8);
INSERT INTO stanza VALUES('T70','chorus','O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>O Hesus kong mahal,<br/>Una Mo ''kong minahal.<br/>',NULL,39346,9);
INSERT INTO stanza VALUES('T71','1','Hesus kay bango ngalan Mo<br/>Sa may salang tao;<br/>Sa ''ming paggunita''y wala,<br/>Mas sa Iyong halaga.<br/>',NULL,39347,1);
INSERT INTO stanza VALUES('T71','2','Sa ngalan Mo''y nakikita,<br/>Ang bawa''t biyaya;<br/>''Pinamuhay bilang tao<br/>Ang buhay dibino.<br/>',NULL,39348,2);
INSERT INTO stanza VALUES('T71','3','Hesus — buhay ng pagsinta<br/>Nagtiis, nagdusa;<br/>Mula sa langit pagdamay,<br/>Para sa ''ting lumbay.<br/>',NULL,39349,3);
INSERT INTO stanza VALUES('T71','4','Hesus, naging kasalanan,<br/>Kamit ko''y kat''wiran;<br/>Sarili Mo''y inilaan<br/>Nang tiwala''y kamtan.<br/>',NULL,39350,4);
INSERT INTO stanza VALUES('T71','5','Tuwing Iyong ngala''y banggitin,<br/>Nais Kang sambahin;<br/>Pinuno sa laksa-laksa,<br/>Sa ''min nagpalaya!<br/>',NULL,39351,5);
INSERT INTO stanza VALUES('T72','1','Hesus sa lahat humigit,<br/>Hades, lupa''t langit;<br/>Samba ng anghel at tao,<br/>Takot ang demonyo.<br/>',NULL,39352,1);
INSERT INTO stanza VALUES('T72','2','Hesus, ngalang sinisinta,<br/>Bigay sa maysala;<br/>Nagpaalis ng pangamba,<br/>At nagpapayapa.<br/>',NULL,39353,2);
INSERT INTO stanza VALUES('T72','3','Hesus bihag kinalagan,<br/>Satanas yurakan;<br/>Sinalita''y lakas, buhay,<br/>Sa mahina''t patay.<br/>',NULL,39354,3);
INSERT INTO stanza VALUES('T72','4','Tikman, tingnan nga ng mundo<br/>Biyayang kay yaman!<br/>Matanggap lahat ng tao<br/>Kanyang kahabagan.<br/>',NULL,39355,4);
INSERT INTO stanza VALUES('T72','5','Hayag kong katuwiran Siya,<br/>Patotohanan nga:<br/>Ang tangi kong dapat gawin,<br/>Kordero''y purihin.<br/>',NULL,39356,5);
INSERT INTO stanza VALUES('T72','6','Magagalak kung sa huli,<br/>Ngalan Niya''y mutawi,<br/>Sa lahat ipahayag Siya,<br/>"Kordero''y masdan nga!"<br/>',NULL,39357,6);
INSERT INTO stanza VALUES('T73','1','Hesus ngalang mal''walhati,<br/>Sa Iyong ngalan magkubli;<br/>Itaas puri''t pagsamba,<br/>Ngalang matagumpay nga.<br/>',NULL,39358,1);
INSERT INTO stanza VALUES('T73','2','Ngalang Makapangyarihan,<br/>Ngalang aking kailangan.<br/>Kung Ngalang Hesus ihinga,<br/>Iinumin Buhay nga.<br/>',NULL,39359,2);
INSERT INTO stanza VALUES('T73','3','Ngalang makapangyarihan,<br/>Langit lupa''y proklama;<br/>May batid samyo ng Ngalan,<br/>Maysalang napatawad.<br/>',NULL,39360,3);
INSERT INTO stanza VALUES('T73','4','Hesus Ngalang tanging mahal,<br/>Kalunasan, tabak din;<br/>Sa Iyong Ngalan ay nabuhay,<br/>Mal''walhating darating.<br/>',NULL,39361,4);
INSERT INTO stanza VALUES('T74','1','May ngalan kay Hesus ''binigay,<br/>Nang pag-ibig Niya''y masaysay<br/>Sabi nito, Siya''y Kapatid ko<br/>Emmanuel, ang ngalang ito.<br/>Anghel sa Kanya''y nagsisamba<br/>Taong nanahan sa lupa;<br/>Magpakailanman Diyos-Tao Siya,<br/>Emmanuel na sinisinta.<br/>',NULL,39362,1);
INSERT INTO stanza VALUES('T74','2','Pangalang mahalagang higit,<br/>Puso namin napaibig.<br/>Ngalan sa ibabaw ng lahat<br/>Hesus pangalang marilag.<br/>Sabi nito Manliligtas Siya,<br/>Mula sa sakit at sala<br/>Pangalang Hesus ay mahal ko<br/>''Pagka''t niligtas Niya ako.<br/>',NULL,39363,2);
INSERT INTO stanza VALUES('T74','3','Pangalang Hesus ating sinta<br/>Ngalang Kristo''y mas higit pa;<br/>''Pagka''t Siya''y nanahan sa atin.<br/>Lumang puso ay baguhin<br/>Kapuspusan ng Espiritu<br/>Sinasalaysay rin nito;<br/>Pahiran Mo rin ako, Kristo<br/>Puspusan ng Espiritu.<br/>',NULL,39364,3);
INSERT INTO stanza VALUES('T75','1','Nangingibabaw na Ngalan!<br/>Hesus, Ngalang marilag!<br/>Anak ng Diyos mal''walhati,<br/>Hari ng mga hari!<br/>',NULL,39365,1);
INSERT INTO stanza VALUES('T75','2','Ngalang malapit sa puso,<br/>Ikubli kaluluwa;<br/>Ngalang malapit sa puso,<br/>Kay Hesus ang tiwala.<br/>',NULL,39366,2);
INSERT INTO stanza VALUES('T75','3','Hesus! Tumawag sa Kanya<br/>Tayo ay ililigtas Niya,<br/>Sa paniniil ng sala,<br/>Samà at kahatulan.<br/>',NULL,39367,3);
INSERT INTO stanza VALUES('T75','4','Oras-oras, araw-araw,<br/>Salamat, mahalin Siya,<br/>Sa sukdulang kaligtasan,<br/>Laya sa kasalanan.<br/>',NULL,39368,4);
INSERT INTO stanza VALUES('T75','5','Hesus, matamis na himig,<br/>Sa manlalakbay awit;<br/>Ngalang Hesus sa anghel nga''y<br/>Musikang matagumpay.<br/>',NULL,39369,5);
INSERT INTO stanza VALUES('T75','6','Buong lupa tumingala,<br/>Sa dakilang AKO NGA!<br/>Langit kay Hesus pumuri,<br/>Sa Kordero''y l''walhati.<br/>',NULL,39370,6);
INSERT INTO stanza VALUES('T76','1','Hesus sa Iyong ngalan,<br/>Luluhod tanan;<br/>Sambitin ng dila:<br/>Hari ng gloria!<br/>Poon tawagin Siya,<br/>Lugod ng Ama;<br/>Ikaw ang Salita<br/>Nang simula pa.<br/>',NULL,39371,1);
INSERT INTO stanza VALUES('T76','2','Lahat ay nilikha,<br/>Sa salita Niya:<br/>Kaagad lumitaw,<br/>Bitui''t araw.<br/>Pamunua''t trono,<br/>Anghel may hukbo,<br/>Ayos makalangit,<br/>Pawang marikit.<br/>',NULL,39372,2);
INSERT INTO stanza VALUES('T76','3','Sandaling bumaba,<br/>Ngala''y makuha<br/>Mula sa may sala<br/>Na dinatnan Niya.<br/>Pinasan Niyang dusa,<br/>Walang dungis Siya,<br/>Pinagtagumpayan<br/>Ang kamatayan!<br/>',NULL,39373,3);
INSERT INTO stanza VALUES('T76','4','Itinaas ito<br/>Ng matagumpay<br/>Sa nilikhang hanay,<br/>Siya ay ang sentro.<br/>Abot sa luklukan<br/>Ng pamunuan,<br/>Sakdal na pahinga,<br/>Puspos ng gloria.<br/>',NULL,39374,4);
INSERT INTO stanza VALUES('T76','5','Hesus, Siya''y tawagin,<br/>Siya ay ibigin;<br/>Sa takot, paghanga<br/>Pigil hininga.<br/>Diyos Manliligtas Siya<br/>Kristo''t Poon pa.<br/>Manalig sa Kanya<br/>Nang may pagsamba.<br/>',NULL,39375,5);
INSERT INTO stanza VALUES('T76','6','Iluklok sa puso,<br/>Haring si Kristo.<br/>Pasakop sa Kanya,<br/>Mga may sala.<br/>Sa oras ng tukso,<br/>Upang manalo,<br/>Kristo''y pamunuin,<br/>Nais Niya''y sundin.<br/>',NULL,39376,6);
INSERT INTO stanza VALUES('T76','7','Panginoong Hari,<br/>Babalik muli.<br/>Anghel ay kasama,<br/>Gloria ng Ama.<br/>Mga kaharian<br/>At pamunuan:<br/>Ipahayag nga Siya<br/>Hari ng gloria.<br/>',NULL,39377,7);
INSERT INTO stanza VALUES('T77','1','Ngalang Hesus dakilain<br/>Langit, lupa''y magproklama<br/>Mandaraig nating Hari,<br/>Lupa at langit magbunyi.<br/>',NULL,39378,1);
INSERT INTO stanza VALUES('T77','2','Ngalang Hesus dakilain,<br/>Sa pagsubok kublihan din;<br/>Malaya at matiwasay,<br/>Sa ngalan Niya''y may tagumpay.<br/>',NULL,39379,2);
INSERT INTO stanza VALUES('T77','3','Ngalang Hesus dakilain,<br/>Hanggang lupa''y payanigin,<br/>Sala, kamatayan pawi<br/>Pagka''t Kristo''y maghahari.<br/>',NULL,39380,3);
INSERT INTO stanza VALUES('T77','4','Ngalang Hesus dakilain<br/>Maghahari at susundin;<br/>Mga hari''t pamunuan,<br/>Pasailalim ng Ngalan.<br/>',NULL,39381,4);
INSERT INTO stanza VALUES('T77','5','Ngalang Hesus dakilain<br/>Tanang pagsamba kakamtin;<br/>Bunga ng Krus makita Niya,<br/>Sa paghahandog ng lupa.<br/>',NULL,39382,5);
INSERT INTO stanza VALUES('T78','1','Hesus, ngalan Mo''y "AKO NGA,"<br/>Banal, mahalaga''t tunay,<br/>Kailangan namin ay nasa<br/>Lahat Mong taglay.<br/>',NULL,39383,1);
INSERT INTO stanza VALUES('T78','2','Anak Ka, Ama''y nasa Iyo,<br/>Tinahanan ''spiritu ko,<br/>Sarili Mong kayamanan<br/>Ay maranasan.<br/>',NULL,39384,2);
INSERT INTO stanza VALUES('T78','3','Templo Ka, tirahan ng Diyos,<br/>Buhay Ka ng Amang lubos;<br/>Sa Iyo kami''y nagsasaya<br/>Makita nga Siya.<br/>',NULL,39385,3);
INSERT INTO stanza VALUES('T78','4','Kordero, Kasintahan Ka,<br/>Naghirap dahil sa sinta,<br/>Pinako sa krus, nagdusa,<br/>Nang mapahinga.<br/>',NULL,39386,4);
INSERT INTO stanza VALUES('T78','5','Daan Ka at karunungan,<br/>Ayon sa Iyong kalooban,<br/>Kami ay biniyayaan,<br/>At ginabayan.<br/>',NULL,39387,5);
INSERT INTO stanza VALUES('T78','6','Dalisay, banal, mat''wid Ka,<br/>Kaisa Ka''t lugod ng Diyos,<br/>Sa amin ay binigay Mo<br/>Matugma sa Diyos.<br/>',NULL,39388,6);
INSERT INTO stanza VALUES('T78','7','Ika''y ilaw at buhay pa,<br/>Nilulon ang kamatayan,<br/>Kami''y binuhay, lumaya<br/>Sa kadiliman.<br/>',NULL,39389,7);
INSERT INTO stanza VALUES('T78','8','Lakas, muling-pagkabuhay,<br/>Winasak Mo ang libingan,<br/>Nang kami ay magtagumpay,<br/>May kalakasan.<br/>',NULL,39390,8);
INSERT INTO stanza VALUES('T78','9','Buháy na tubig at manna,<br/>Tustos Kang nagpakababa,<br/>Uhaw, gutom ay pawi na,<br/>Kapistahan Ka.<br/>',NULL,39391,9);
INSERT INTO stanza VALUES('T78','10','Manggagamot at Pastol Ka,<br/>Naglunas sa sakit namin;<br/>Patnubayan Iyong hangarin,<br/>Sa pag-alaga.<br/>',NULL,39392,10);
INSERT INTO stanza VALUES('T78','11','Saserdote Ka at Hari,<br/>Sa Diyos kami''y dinala Mo,<br/>Awtoridad Mo''y bahagi<br/>Namin sa trono.<br/>',NULL,39393,11);
INSERT INTO stanza VALUES('T78','12','Katubusan Ka''t Pag-asa,<br/>Babaguhin aming anyo,<br/>Isang kopya ay gawin Mo<br/>Kawangis sa Iyo.<br/>',NULL,39394,12);
INSERT INTO stanza VALUES('T78','13','Kapayapaan, Gloria Ka;<br/>Biyaya, Katotohanan,<br/>Bato, Buhay-puno, Araw,<br/>Bundok, Tanggulan.<br/>',NULL,39395,13);
INSERT INTO stanza VALUES('T78','14','Ikaw nga ay walang hanggan,<br/>Puspos, sakdal at mayaman—<br/>Kapuspusan sa kailangan<br/>Nag-umapaw pa.<br/>',NULL,39396,14);
INSERT INTO stanza VALUES('T79','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39397,1);
INSERT INTO stanza VALUES('T79','1','Papurihang walang hanggan,<br/>Kanyang kamahalan,<br/>Ang Korderong Manunubos,<br/>Itinaas ng Diyos.<br/>',NULL,39398,2);
INSERT INTO stanza VALUES('T79','chorus','Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>',NULL,39399,3);
INSERT INTO stanza VALUES('T79','2','Higit sa lahat ng ngalan,<br/>Hesus ay nabigyan.<br/>Magbubunyi sangnilikha,<br/>Panginoon nga Siya.<br/>',NULL,39400,4);
INSERT INTO stanza VALUES('T79','chorus','Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>',NULL,39401,5);
INSERT INTO stanza VALUES('T79','3','Manunubos, Mananakop,<br/>Kaibigan ng tao,<br/>Sa Iyong kaligtasang plano,<br/>Nabuwis buhay Mo.<br/>',NULL,39402,6);
INSERT INTO stanza VALUES('T79','chorus','Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>',NULL,39403,7);
INSERT INTO stanza VALUES('T79','4','Sasamba sa Manliligtas,<br/>Naligtas pupuri.<br/>Nagdugo Siya para sa ''kin,<br/>Pagpapala''y angkin.<br/>',NULL,39404,8);
INSERT INTO stanza VALUES('T79','chorus','Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>',NULL,39405,9);
INSERT INTO stanza VALUES('T79','5','Tagapayo at Prinsipe<br/>Ng Kapayapaan,<br/>Sa panlupang kaharian,<br/>Maghari kailanman.<br/>',NULL,39406,10);
INSERT INTO stanza VALUES('T79','chorus','Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>Ngalan purihin,<br/>Ngalan purihin,<br/>Panginoon ay purihin.<br/>',NULL,39407,11);
INSERT INTO stanza VALUES('T80','1','Lahat na kilala<br/>Sa dunong, pagsinta<br/>Na batid ng tao<br/>Sa anghel totoo;<br/>Hindi lubusang mabigkas<br/>Halaga ng Manliligtas.<br/>',NULL,39408,1);
INSERT INTO stanza VALUES('T80','2','Dakilang Propeta,<br/>Dila''y purihin Ka.<br/>Sa Iyo nga nagmula<br/>Mabuting balita;<br/>Pinatawad, buhay kamtan,<br/>Walang bisa kamatayan.<br/>',NULL,39409,2);
INSERT INTO stanza VALUES('T80','3','Hesus, Saserdote<br/>Para sa ''king budhi,<br/>Dugo Niya''y inalay<br/>Kaya nga namatay:<br/>Tinubos ako ng dugo,<br/>Halaga''y batid ng puso.<br/>',NULL,39410,3);
INSERT INTO stanza VALUES('T80','4','Tinig ng Pastol ko<br/>O minamahal ko!<br/>Akong isang tupa<br/>Inalagaan Niya:<br/>Pinapakain kawan Niya,<br/>Tinatawag ngalan nila.<br/>',NULL,39411,4);
INSERT INTO stanza VALUES('T80','5','Hari''t Panginoon,<br/>Aking Mananakop,<br/>Biyaya Mo''t setro,<br/>Ay aawitin ko:<br/>Iyong-iyo ang kapangyarihan<br/>Ako''y nasa Iyong paanan.<br/>',NULL,39412,5);
INSERT INTO stanza VALUES('T81','1','Panginoon antigo Ka,<br/>Ang di-nilikhang AKO NGA,<br/>Nang walang hanggang simula<br/>Ika''y walang hanggang Ama.<br/>',NULL,39413,1);
INSERT INTO stanza VALUES('T81','2','Bagama''t naging tao Ka,<br/>Katulad Ka nga ng Ama;<br/>Gaya Niya sa kasakdalan,<br/>Gaya ng Diyos walang hanggan.<br/>',NULL,39414,2);
INSERT INTO stanza VALUES('T81','3','Iyong pinagmulan tulad Niya<br/>Bago pa ng sangnilikha;<br/>Bago pa''ng pinakauna,<br/>Nauna Ka''t walang iba!<br/>',NULL,39415,3);
INSERT INTO stanza VALUES('T81','4','Di Ka nagbago kailanman,<br/>Mga taon walang hanggan!<br/>Walang matagal kaysa Iyo,<br/>Ni wala ring kasunod Mo!<br/>',NULL,39416,4);
INSERT INTO stanza VALUES('T81','5','Wala ka ngang pagkaiba,<br/>Katulad ng Diyos na Ama;<br/>Ikaw ay Una at Alpha<br/>Gayunding Huli''t Omega.<br/>',NULL,39417,5);
INSERT INTO stanza VALUES('T81','6','Sa Iyong pagkawalang-hanggan<br/>Maging I-yong kasakdalan,<br/>Maging sa Iyong kapuspusan<br/>Dapat Ka ngang papurihan.<br/>',NULL,39418,6);
INSERT INTO stanza VALUES('T82','1','Diyos ko''y nilisan<br/>Ang kal''walhatian,<br/>Manliligtas ko Siya,<br/>Hesus ang ngalan Niya.<br/>Siya''y isinilang<br/>Sa isang sabsaban,<br/>Tao ng panglaw at kalungkutan.<br/>',NULL,39419,1);
INSERT INTO stanza VALUES('T82','chorus','Iniibig ko! Sinasamba ko!<br/>Hangin, liwanag, aking lahat!<br/>Ang Manlilikha''y Manliligtas ko,<br/>Kapuspusan Siya ng Diyos Ama.<br/>',NULL,39420,2);
INSERT INTO stanza VALUES('T82','2','Pagbabang lubos,<br/>Hatid ay pagtubos;<br/>Na sa kadiliman,<br/>Walang maasahan,<br/>Diyos mabiyaya,<br/>Iniwan ang gloria,<br/>Yumukod upang ako''y iligtas.<br/>',NULL,39421,3);
INSERT INTO stanza VALUES('T82','chorus','Iniibig ko! Sinasamba ko!<br/>Hangin, liwanag, aking lahat!<br/>Ang Manlilikha''y Manliligtas ko,<br/>Kapuspusan Siya ng Diyos Ama.<br/>',NULL,39422,4);
INSERT INTO stanza VALUES('T82','3','Walang siphayo,<br/>Taglay lama''t dugo;<br/>Inihayag sa ''tin,<br/>Ang kubling layunin.<br/>Anong misteryo,<br/>Hain ng Kalbaryo,<br/>Ikaw ang Siyang dakilang "AKO NGA."<br/>',NULL,39423,5);
INSERT INTO stanza VALUES('T82','chorus','Iniibig ko! Sinasamba ko!<br/>Hangin, liwanag, aking lahat!<br/>Ang Manlilikha''y Manliligtas ko,<br/>Kapuspusan Siya ng Diyos Ama.<br/>',NULL,39424,6);
INSERT INTO stanza VALUES('T83','1','Sa langit umalingawngaw<br/>Mga tinig na banal;<br/>Mga anghel naggagalak<br/>Aleluyang malakas!<br/>',NULL,39425,1);
INSERT INTO stanza VALUES('T83','2','Kuwentong kagila-gilalas,<br/>Sa himno naibigkas;<br/>Ang Diyos nga ay papurihan<br/>Sa kataas-taasan.<br/>',NULL,39426,2);
INSERT INTO stanza VALUES('T83','3','Sa lupa kapayapaan,<br/>Sa langit kabutihan;<br/>Mga kalul''wa natubos,<br/>Gintong alpa — tutunog.<br/>',NULL,39427,3);
INSERT INTO stanza VALUES('T83','4','Si Kristo ay naisilang,<br/>Dakila''y Pinahiran,<br/>Ang itinalaga ng Diyos,<br/>Luwalhatiing lubos.<br/>',NULL,39428,4);
INSERT INTO stanza VALUES('T83','5','Mga tao! Sambahin Siya<br/>Kilalanin ngalan Niya;<br/>Hanggang pagharap sa Kanya<br/>O Diyos sa Iyo ang gloria.<br/>',NULL,39429,5);
INSERT INTO stanza VALUES('T83','6','Kapanganakan ni Kristo,<br/>Ating ipatotoo;<br/>Ikalat ang l''walhati Niya,<br/>Punuin buong lupa.<br/>',NULL,39430,6);
INSERT INTO stanza VALUES('T84','1','Anghel nangag-awitan<br/>Gloria sa bagong-silang<br/>Na Haring may biyaya<br/>Payapa nga sa lupa<br/>Tao''t Diyos nagkasundo,<br/>Mangagalak nga tayo;<br/>Kristo''y naisilang na,<br/>Atin ding iproklama.<br/>[Kristo''y naisilang na,<br/>Atin ding iproklama.]<br/>',NULL,39431,1);
INSERT INTO stanza VALUES('T84','2','Sumamba kalangitan<br/>Kay Kristong walang hanggan<br/>Sa huli Siya''y dumating<br/>Naging supling ng birhen.<br/>Anyong laman nakita<br/>Pagka-Diyos sa tao nga<br/>Nanahan sa tao rin<br/>Hesus, Immanuel natin.<br/>[Nanahan sa tao rin<br/>Hesus, Immanuel natin.]<br/>',NULL,39432,2);
INSERT INTO stanza VALUES('T84','3','Hari ay papurihan,<br/>Ang araw ng kat''wiran,<br/>Dala''y buhay, liwanag,<br/>May panlunas na pakpak;<br/>L''walhati''y iniwan Niya,<br/>Isinilang sa lupa;<br/>Nang maisilang-muli<br/>Ang taong Kanyang mithi.<br/>[Nang maisilang-muli<br/>Ang taong Kanyang mithi.]<br/>',NULL,39433,3);
INSERT INTO stanza VALUES('T84','4','Mithi ng mga bansa,<br/>Sa puso''y manahan Ka;<br/>Binhi ng babae man,<br/>Ulo ng ahas, saktan.<br/>Anyong Adam burahin<br/>I-yong anyo ang kamtin.<br/>Huling Adam, kami nga''y<br/>Sa pag-ibig tumibay.<br/>[Huling Adam, kami nga''y<br/>Sa pag-ibig tumibay.]<br/><!--(Ulitin ang huling dalawang linya)--><br/>',NULL,39434,4);
INSERT INTO stanza VALUES('T85','1','Tapat, halina, may tagumpay at saya,<br/>Sa Betlehem pumaritong nagkai-sa;<br/>Tingnan! Sa sabsaban, Diyos nakahiga!<br/>',NULL,39435,1);
INSERT INTO stanza VALUES('T85','chorus','O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>Mahalin!<br/>',NULL,39436,2);
INSERT INTO stanza VALUES('T85','2','Mga anghel, awit ng tagumpay laksan,<br/>Ibuhos papuri sa kalangitan,<br/>Sa ating Diyos, gloria sa kataasan.<br/>',NULL,39437,3);
INSERT INTO stanza VALUES('T85','chorus','O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>Mahalin!<br/>',NULL,39438,4);
INSERT INTO stanza VALUES('T85','3','Isinilang Ka para sa kaligtasan,<br/>O Hesus sambahin ang Iyong pangalan;<br/>Salita ng Ama na naging laman.<br/>',NULL,39439,5);
INSERT INTO stanza VALUES('T85','chorus','O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>O Kristo Panginoon!<br/>Mahalin!<br/>',NULL,39440,6);
INSERT INTO stanza VALUES('T86','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,39441,1);
INSERT INTO stanza VALUES('T86','1','Bagama''t Diyos na mal''walhati Ka,<br/>Sa laman sa ami''y lumapit Ka,<br/>Naging isang mababang Tao Ka;<br/>Ginugunita Ka.<br/>',NULL,39442,2);
INSERT INTO stanza VALUES('T86','2','Naisantabi kal''walhatian,<br/>Nananahan Ka sa toldang laman,<br/>Walang panlabas na karilagan;<br/>Ginugunita Ka.<br/>',NULL,39443,3);
INSERT INTO stanza VALUES('T86','3','Ikaw ay ugat sa tuyong lupa,<br/>Isang Tao ng kapanglawan Ka,<br/>Ika''y kinamuhian, minata;<br/>Ginugunita Ka.<br/>',NULL,39444,4);
INSERT INTO stanza VALUES('T86','4','Mababang-loob at mapagtimpi,<br/>Handang pagdusahin Iyong Sarili,<br/>Sa tao''t Diyos walang sinasabi;<br/>Ginugunita Ka.<br/>',NULL,39445,5);
INSERT INTO stanza VALUES('T86','5','Taong magiliw at matamis Ka,<br/>Sa bawa''t panig balanse Ka nga,<br/>Handog na pagkain Ka sa Ama;<br/>Ginugunita Ka.<br/>',NULL,39446,6);
INSERT INTO stanza VALUES('T86','6','Kalooban ng Diyos sinunod Mo.<br/>Di kasinungalingan ng Diyablo,<br/>Napakatapat Mo''t matalino;<br/>Ginugunita Ka.<br/>',NULL,39447,7);
INSERT INTO stanza VALUES('T86','7','Pagsunod sa kalooban ng Diyos,<br/>Kamatayan binata Mong lubos,<br/>Para sa akin pinako sa krus;<br/>Ginugunita Ka.<br/>',NULL,39448,8);
INSERT INTO stanza VALUES('T86','8','Kaya nga, ang Diyos itinaas Ka,<br/>Binigyan Kang kamahala''t gloria,<br/>Luluhod sa Iyo ang langit, lupa;<br/>Sinasamba Kita!<br/>',NULL,39449,9);
INSERT INTO stanza VALUES('T87','1','Hesus, t''wing maisip Kita<br/>Nang nasa lupa Ka:<br/>Sa tao''y mapagbiyaya,<br/>Sa Diyos tapat Ka nga.<br/>',NULL,39450,1);
INSERT INTO stanza VALUES('T87','2','Pag-ibig Mo''y hamakin man,<br/>Daig kamatayan;<br/>Sibat sa Iyong tagiliran,<br/>Dugo''t tubig kamtan.<br/>',NULL,39451,2);
INSERT INTO stanza VALUES('T87','3','Kahit lubha Kang nagdusa,<br/>Gawa Mo''y mabuti;<br/>Walang daing, tanggap Mo pa<br/>Lahat ng pighati.<br/>',NULL,39452,3);
INSERT INTO stanza VALUES('T87','4','Tao''y taksil, Ika''y tapat,<br/>Dilim siya, Ilaw Ka,<br/>Layunin ay Iyong tinupad,<br/>Kalo''ban ng Ama.<br/>',NULL,39453,4);
INSERT INTO stanza VALUES('T87','5','Di Ka natinag sa dusa,<br/>Lalang ng masama;<br/>Sa kamatayan, nag-isa,<br/>Walang karamay Ka.<br/>',NULL,39454,5);
INSERT INTO stanza VALUES('T87','6','Nais kong makatulad Mo<br/>Sa Iyong kaamuan,<br/>Lahat sa Iyo ay matuto—<br/>May kapayapaan.<br/>',NULL,39455,6);
INSERT INTO stanza VALUES('T88','1','Kay gandang bakas dibino,<br/>Sa Iyong pagiging maamo,<br/>Sa landas ng kalungkutan,<br/>Sinilay kaliwanagan.<br/>',NULL,39456,1);
INSERT INTO stanza VALUES('T88','2','O sino nga ang gaya Mo<br/>Maliwanag at maamo?<br/>Katulad Mong mapagt''yaga<br/>Hirap dinanas sa lupa?<br/>',NULL,39457,2);
INSERT INTO stanza VALUES('T88','3','Sino ang mapagkumbaba<br/>At nagtiis ng pagdusta<br/>Gaya Mong tiniis, dusta?<br/>Anong amo, anong baba!<br/>',NULL,39458,3);
INSERT INTO stanza VALUES('T88','4','Kamatayan Iyong binata,<br/>Nang may sala mapalaya<br/>Pinahayag Iyong pagsinta,<br/>Kasama ng dugo''y awa.<br/>',NULL,39459,4);
INSERT INTO stanza VALUES('T88','5','O Poong kamangha-mangha,<br/>Mapawangis sa Iyo nawa,<br/>Matuto sa kababaan<br/>Sundan, tahakin Iyong daan.<br/>',NULL,39460,5);
INSERT INTO stanza VALUES('T89','1','Anong ganda ng Iyong yapak<br/>Dito''y Iyong tinahak!<br/>Sa gitna ng Iyong dinanas<br/>Pag-ibig namalas.<br/>',NULL,39461,1);
INSERT INTO stanza VALUES('T89','2','Sa pusong nabibigatan,<br/>At may kalungkutan;<br/>Di narinig mula sa Iyo<br/>Ang pagrereklamo.<br/>',NULL,39462,2);
INSERT INTO stanza VALUES('T89','3','Kaaway sa Iyo''y namuhi,<br/>Kaibigan Mo''y imbi;<br/>Di napagod magpatawad,<br/>Pag-ibig ang hangad.<br/>',NULL,39463,3);
INSERT INTO stanza VALUES('T90','1','Tanggapin aming awit,<br/>Mahina man ang tinig;<br/>Matapat Mong biyaya,<br/>Turan namin, itala.<br/>',NULL,39464,1);
INSERT INTO stanza VALUES('T90','2','L''walhating mayaman Ka,<br/>Dahil sa ''min bumaba;<br/>Nang sa Iyong pagkadukha,<br/>Kami ay managana.<br/>',NULL,39465,2);
INSERT INTO stanza VALUES('T90','3','Pinighati ng langit?<br/>Lupa sa Iyo''y umakit?<br/>Ang langit Iyong nilisan<br/>Mapuntang kamatayan?<br/>',NULL,39466,3);
INSERT INTO stanza VALUES('T90','4','Kay l''walhati sa langit!<br/>Sa lupa''y napighati!<br/>Talos Mong pagdurusa,<br/>Pag-ibig ang nagbata.<br/>',NULL,39467,4);
INSERT INTO stanza VALUES('T90','5','Kung naisip buti Mo,<br/>Hiya''t galak naghalo;<br/>Hiya nga ganti''y wala,<br/>Galak sa Iyong pagsinta.<br/>',NULL,39468,5);
INSERT INTO stanza VALUES('T90','6','Asam ko ang araw nga,<br/>Sa balakid lalaya.<br/>Dalhin kami sa gloria,<br/>Aming paglingkuran Ka.<br/>',NULL,39469,6);
INSERT INTO stanza VALUES('T90','7','Ngayon ay naghihintay,<br/>Sa pag-asa nagbantay;<br/>Mabuhay para sa Iyo,<br/>Hanggang makasama Mo.<br/>',NULL,39470,7);
INSERT INTO stanza VALUES('T91','1','Sa Getsemaning madilim<br/>Hesus nanalangin;<br/>Saro ng poot inubos;<br/>Siya''y nagdusang lubos.<br/>',NULL,39471,1);
INSERT INTO stanza VALUES('T91','chorus','Nag-iisa,<br/>Pasan Niyang mag-isa;<br/>Buhay Niya ay ibinigay,<br/>Nagdusa, nagdugo at namatay.<br/>',NULL,39472,2);
INSERT INTO stanza VALUES('T91','2','Sa harapan ni Pilato,<br/>Hesus, nakatayo;<br/>Suot tinik na korona,<br/>Lahat, tinakwil Siya.<br/>',NULL,39473,3);
INSERT INTO stanza VALUES('T91','chorus','Nag-iisa,<br/>Pasan Niyang mag-isa;<br/>Buhay Niya ay ibinigay,<br/>Nagdusa, nagdugo at namatay.<br/>',NULL,39474,4);
INSERT INTO stanza VALUES('T91','3','Siya ay ipinako sa krus,<br/>Nang tao''y matubos;<br/>''Tinakwil ng Diyos at tao,<br/>Siya''y nagsakripisyo.<br/>',NULL,39475,5);
INSERT INTO stanza VALUES('T91','chorus','Nag-iisa,<br/>Pasan Niyang mag-isa;<br/>Buhay Niya ay ibinigay,<br/>Nagdusa, nagdugo at namatay.<br/>',NULL,39476,6);
INSERT INTO stanza VALUES('T91','4','Pagsintang di mapantayan,<br/>Iyo bang tatanggihan?<br/>Siya ay Iyong pasalamatan,<br/>Hu-wag mo Siyang iwan.<br/>',NULL,39477,7);
INSERT INTO stanza VALUES('T91','chorus','Nag-iisa,<br/>Pasan Niyang mag-isa;<br/>Buhay Niya ay ibinigay,<br/>Nagdusa, nagdugo at namatay.<br/>',NULL,39478,8);
INSERT INTO stanza VALUES('T93','1','Panginoon, Iyong dinanas<br/>Ang mga dusa''t hirap,<br/>Puso nami''y humahanga,<br/>Amin Kang sinasamba.<br/>',NULL,39479,1);
INSERT INTO stanza VALUES('T93','chorus','Purihin Ka, Manliligtas!<br/>Para sa ''min namatay!<br/>L''walhatiin, Manliligtas!<br/>Buhay Mo ay aming nataglay.<br/>',NULL,39480,2);
INSERT INTO stanza VALUES('T93','2','Lalim ng Iyong kalungkutan,<br/>Dusa''t kapighatian;<br/>Lampas sa aming maisip,<br/>Higit sa ''ming masambit.<br/>',NULL,39481,3);
INSERT INTO stanza VALUES('T93','chorus','Purihin Ka, Manliligtas!<br/>Para sa ''min namatay!<br/>L''walhatiin, Manliligtas!<br/>Buhay Mo ay aming nataglay.<br/>',NULL,39482,4);
INSERT INTO stanza VALUES('T93','3','Sa gawaing katubusan,<br/>Sa mga kahirapan;<br/>Ikaw lamang ang nagdusa,<br/>At walang nakasama.<br/>',NULL,39483,5);
INSERT INTO stanza VALUES('T93','chorus','Purihin Ka, Manliligtas!<br/>Para sa ''min namatay!<br/>L''walhatiin, Manliligtas!<br/>Buhay Mo ay aming nataglay.<br/>',NULL,39484,6);
INSERT INTO stanza VALUES('T93','4','Kasalana''y sinukat Mo,<br/>Poot at sumpa''y sa Iyo;<br/>''Tinakwil ng Diyos at tao:<br/>Pag-ibig Mo''y dibino.<br/>',NULL,39485,7);
INSERT INTO stanza VALUES('T93','chorus','Purihin Ka, Manliligtas!<br/>Para sa ''min namatay!<br/>L''walhatiin, Manliligtas!<br/>Buhay Mo ay aming nataglay.<br/>',NULL,39486,8);
INSERT INTO stanza VALUES('T94','1','Poon anong nagpatungô,<br/>Sala nami''y sa Iyo?<br/>Tayo mo''y bilang salarin.<br/>Sala Iyong pasanin:<br/>Bilang hain nagdugo Ka.<br/>Ako''y napalaya!<br/>',NULL,39487,1);
INSERT INTO stanza VALUES('T94','2','Punô ng sumpa, ang saro,<br/>Dapat bahagi ko;<br/>Bawa''t pait Iyong inubos<br/>Para sa ''king lubos.<br/>Saro ng kapaitan Iyo,<br/>Akin pagpala mo.<br/>',NULL,39488,2);
INSERT INTO stanza VALUES('T94','3','Panghampas ng Diyos Ama Mo<br/>O sa Iyo dumapo!<br/>Nang di ako parusahan,<br/>Ikaw ang sinaktan.<br/>Mahal Mong dugo umagos<br/>Nang ako''y matubos.<br/>',NULL,39489,3);
INSERT INTO stanza VALUES('T94','4','Lagim ng unos narinig<br/>Kay Kristo''y humaplit;<br/>Dibdib Mo''y aking kanlungan,<br/>Akin ding kublihan.<br/>Kapayapaan natamo<br/>Dahil sa dusa Mo.<br/>',NULL,39490,4);
INSERT INTO stanza VALUES('T94','5','Tabak inutos ng Ama,<br/>O, sa Iyo''y tumama!<br/>Talim sa puso''y tumagos,<br/>Dugo mo''y umagos.<br/>Hiling ng Diyos Iyong natupad<br/>Tigil na ang tabak.<br/>',NULL,39491,5);
INSERT INTO stanza VALUES('T94','6','Namatay Ka para sa ''kin,<br/>Ako''y kalakip rin,<br/>Nabuhay Ka, pinalaya,<br/>Sa akin buhay Ka.<br/>Madalisay, matransporma,<br/>Tungo sa Iyong gloria!<br/>',NULL,39492,6);
INSERT INTO stanza VALUES('T95','1','Ulong dati''y pinalo,<br/>Hinamak, tinudyo,<br/>Hapdi ng panlalait,<br/>Pinutong ay tinik:<br/>Ngayon ay pinutungan<br/>Ng kadakilaan,<br/>Ulong napayuko sa<br/>Punong isinumpa.<br/>',NULL,39493,1);
INSERT INTO stanza VALUES('T95','2','Mukhang nangingibabaw!<br/>Lumilikhang Araw!<br/>Ika''y tinatanganan—<br/>Nguni''t niluraan;<br/>Sa Iyo ay nagpahirap,<br/>Salang mabibigat,<br/>Sa ''ming pagkakautang,<br/>Dugo''ng kabayaran.<br/>',NULL,39494,2);
INSERT INTO stanza VALUES('T95','3','Sa Iyo''y pasasalamat,<br/>O Tagapagligtas,<br/>Dahil sa ''min nasugat,<br/>Ikaw ay nagdanas;<br/>Kami''y nagtitiwala<br/>Sa Iyong katapatan,<br/>Hanggang sa magpangita<br/>Tayo nang mukhaan.<br/>',NULL,39495,3);
INSERT INTO stanza VALUES('T98','1','Hesus, Bukal ng buhay Ka,<br/>Maykatha ng hininga!<br/>Dinaig ang kamatayan,<br/>Hades at kadiliman.<br/>Binata kapighatian,<br/>Kamtin ko lang kaligtasan;<br/>Papuri''y laksa-laksa,<br/>Karapat-dapat Ka nga!<br/>',NULL,39496,1);
INSERT INTO stanza VALUES('T98','2','Anak ng Diyos, nagdusa Ka,<br/>Hirap, pag-alipusta;<br/>Putong tinik, sinuot Mo<br/>Para sa ''kin, Hari ko.<br/>Namatay upang magligtas,<br/>Salang kadena kinalas;<br/>Papuri''y laksa-laksa,<br/>Karapat-dapat Ka nga.<br/>',NULL,39497,2);
INSERT INTO stanza VALUES('T98','3','Binunton na kahihiyan,<br/>Iyo ngang pinagtiisan;<br/>Nang Iyong tupdin katubusan.<br/>Hinarap kamatayan.<br/>Nagpakababa''t nagbata<br/>Hanggang mamatay sa lupa;<br/>Papuri''y laksa-laksa,<br/>Karapat-dapat Ka nga.<br/>',NULL,39498,3);
INSERT INTO stanza VALUES('T98','4','Dahil sa pagkamatay Mo,<br/>Binigyang-buhay ako;<br/>Sumasamba ''spiritu ko,<br/>Pumupuri ang puso.<br/>Lungkot, panglaw Iyong pinasan,<br/>Pala ko''y katamasahan;<br/>Paksa kong palagian,<br/>Lagi Kang papurihan.<br/>',NULL,39499,4);
INSERT INTO stanza VALUES('T99','1','Sa hatinggabing madilim,<br/>Mga tala''y makulimlim;<br/>Sa halamanang madilim,<br/>Siya''y mag-isang nanalangin.<br/>',NULL,39500,1);
INSERT INTO stanza VALUES('T99','2','Hatinggabi''t nag-iisa,<br/>Si Kristo ay nagbabata;<br/>Alagad Niyang iniibig,<br/>Sa Kanya''y di umulinig.<br/>',NULL,39501,2);
INSERT INTO stanza VALUES('T99','3','Dahil sa sala ng iba,<br/>Dugo ang ipinawis Niya;<br/>Nguni''t nang nagdurusa na,<br/>Diyos din ang Kanyang kasama.<br/>',NULL,39502,3);
INSERT INTO stanza VALUES('T99','4','Yaong awitan sa langit,<br/>Sa Kanya ay pinarinig;<br/>Kay tamis na lunas nito,<br/>Sa pagdurusa ni Kristo.<br/>',NULL,39503,4);
INSERT INTO stanza VALUES('T101','1','Kapag minamasdan ang krus,<br/>Na pinakuan ni Hesus,<br/>Pakinabang winakasan,<br/>Tinakwil kapalaluan.<br/>',NULL,39504,1);
INSERT INTO stanza VALUES('T101','2','''Di magmamapuri tayo<br/>Maliban sa Krus ni Kristo;<br/>Inibig na rangya''t dangal,<br/>Ngayo''y inari ng sukal.<br/>',NULL,39505,2);
INSERT INTO stanza VALUES('T101','3','Mula ulo hanggang paa,<br/>Lungkot, pag-ibig bumaba,<br/>Dusa''t pag-ibig naghalo,<br/>Koronang tinik nabuo.<br/>',NULL,39506,3);
INSERT INTO stanza VALUES('T101','4','Masdan, katawan ni Hesus,<br/>Babad sa dugong nabuhos.<br/>Sa mundo''y patay na ako,<br/>Sa akin patay rin ito.<br/>',NULL,39507,4);
INSERT INTO stanza VALUES('T101','5','Atin man ang kalikasan<br/>Ay wala ring kabuluhan;<br/>Sa pag-ibig na dalisay,<br/>Alay natin puso''t buhay.<br/>',NULL,39508,5);
INSERT INTO stanza VALUES('T104','1','Tagapagligtas nagdugo,<br/>Namatay Hari ko,<br/>Buhay Niya''y sinakripisyo,<br/>Sa uod na tulad ko?<br/>',NULL,39509,1);
INSERT INTO stanza VALUES('T104','2','Namighati doon sa krus,<br/>Para sa sala ko?<br/>Pag-ibig, biyayang lubos!<br/>Habag di matanto!<br/>',NULL,39510,2);
INSERT INTO stanza VALUES('T104','3','Sa dilim araw nagtago,<br/>Nang ang Manlilikha<br/>Namatay para sa tao;<br/>Inako pa ang sala.<br/>',NULL,39511,3);
INSERT INTO stanza VALUES('T104','4','Nang makita ko ang krus Niya,<br/>Nagkubli sa hiya,<br/>Puso''y natunaw sa awa,<br/>Mata''y lumuluha.<br/>',NULL,39512,4);
INSERT INTO stanza VALUES('T104','5','Di makabayad ang lumbay,<br/>Utang ng pag-irog,<br/>Panginoon, aking buhay,<br/>Sa Iyo ihahandog.<br/>',NULL,39513,5);
INSERT INTO stanza VALUES('T105','1','Kanyang Sarili''y di maaring iligtas,<br/>Awa''y di-daratal kung Siya''y di mamatay;<br/>Kristo ay dapat magdugo,<br/>Nang mapalaya maysala.<br/>',NULL,39514,1);
INSERT INTO stanza VALUES('T105','2','Kanyang Sarili''y di maaring iligtas,<br/>Kung hindi Niya magawa ang katuwiran;<br/>Bigat ng sala''y pinasan,<br/>Sa Diyos utang binayaran.<br/>',NULL,39515,2);
INSERT INTO stanza VALUES('T105','3','Kanyang Sarili''y di maaring iligtas,<br/>Sarili''y Panagot sa tanang umasa<br/>Sa Kanyang mahal na dugo,<br/>Sa krus ay Kanyang ''binubo.<br/>',NULL,39516,3);
INSERT INTO stanza VALUES('T105','4','Kanyang Sarili''y di maaring iligtas,<br/>Dakilang pag-ibig! Kagila-gilalas!<br/>Pusong bato ay tinunaw,<br/>Hanggang papuri''y umapaw.<br/>',NULL,39517,4);
INSERT INTO stanza VALUES('T106','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39518,1);
INSERT INTO stanza VALUES('T106','1','Wala nang dambana,<br/>Dugo at hain pa;<br/>Walang usok, walang apoy.<br/>Wala nang panaghoy.<br/>Maharlikang dugo dumaloy na,<br/>Dungis hinugasan, pinatawad sala.<br/>',NULL,39519,2);
INSERT INTO stanza VALUES('T106','2','Salamat Diyos Ama,<br/>Sa dugo ng Anak.<br/>Kami''y naging mga mat''wid,<br/>Pagtubos nakamit,<br/>Naligtas sa Hades, sala''t dilim.<br/>Buhay na walang hanggang napasaamin.<br/>',NULL,39520,3);
INSERT INTO stanza VALUES('T106','3','Salamat Diyos Ama,<br/>Sa I-yong biyaya;<br/>Lawak ng di-makat''wiran,<br/>Nilagom lubusan.<br/>Pinupuri namin Iyong pagsinta,<br/>L''walhati''t lakas mapasa Iyo, Siya nawa.<br/>',NULL,39521,4);
INSERT INTO stanza VALUES('T106','4','Salamat Diyos Ama.<br/>Sa putong na gloria<br/>Nananatili ang ganda,<br/>Hindi malalanta.<br/>Gaya ng trono di nasisira,<br/>Dapat sa Iyo pa rin ang mga putong nga.<br/>',NULL,39522,5);
INSERT INTO stanza VALUES('T108','1','"Tao ng kapanglawan,"<br/>Anak ng Diyos, pangalan,<br/>Bawi''y makasalanan!<br/>Manunubos! Aleluya!<br/>',NULL,39523,1);
INSERT INTO stanza VALUES('T108','2','Siya''y hinamak, kinutya,<br/>Tumayong nakondena,<br/>Nagpatawad, nagtubos,<br/>Aleluya! Manunubos!<br/>',NULL,39524,2);
INSERT INTO stanza VALUES('T108','3','Tayo''y makasalanan,<br/>Banal na Kordero Siya,<br/>Ginanap katubusan,<br/>Manunubos! Aleluya!<br/>',NULL,39525,3);
INSERT INTO stanza VALUES('T108','4','Sa krus Siya''y itinaas,<br/>"Naganap na," wika Niya;<br/>Sa langit Siya''y ''tinaas;<br/>Manunubos! Aleluya!<br/>',NULL,39526,4);
INSERT INTO stanza VALUES('T108','5','Kapag Hari''y dumating,<br/>Tayo''y Kanyang kukunin,<br/>Aawiting minsan pa:<br/>Manunubos! Aleluya!<br/>',NULL,39527,5);
INSERT INTO stanza VALUES('T110','1','Panahon na nag-isa Ka!<br/>Anong karimlan nga!<br/>Ang bugtong na Anak ng Diyos<br/>Para sa tao''y namatay<br/>Nakapanlupaypay,<br/>Poon ng gloria ''pinako,<br/>Poon ng Buhay nagdugo!<br/>',NULL,39528,1);
INSERT INTO stanza VALUES('T110','2','Buhay at kamatayan Niya,<br/>Sadyang mahiwaga.<br/>Ito''y sentro, walang hanggan,<br/>Mga mata Siya''y titingnan.<br/>Siya nga''y papurihan!<br/>Poon, krus na Iyong pinasan,<br/>Aking kapakinabangan.<br/>',NULL,39529,2);
INSERT INTO stanza VALUES('T110','3','Nang tumingala sa krus Mo,<br/>Naantig ang puso;<br/>Kamatayan sa kalbaryo<br/>Nahayag ang Pag-ibig Mo<br/>Anong dusa sa Iyo!<br/>Puso''y durog sa Iyong sabi:<br/>"Eli lama sabachthani."<br/>',NULL,39530,3);
INSERT INTO stanza VALUES('T110','4','Dapat nga''y mamatay kami;<br/>Amin din ang ganti;<br/>Nguni''t Bugtong na Anak Niya,<br/>Pinasan sala''t nagdusa,<br/>Kat''wiran nanghusga.<br/>Napako ngang kasama Ka,<br/>Namatay ngang kasama Ka.<br/>',NULL,39531,4);
INSERT INTO stanza VALUES('T110','5','Kasama kaming nabuhay,<br/>Nabuhay sa patay;<br/>Ngayon pantao''t dibino,<br/>Mapasasa l''walhati Mo,<br/>Ulo ng Katawan!<br/>Kami noo''y nasa sumpa,<br/>Ngayon tawag "Abba Ama."<br/>',NULL,39532,5);
INSERT INTO stanza VALUES('T112','1','Kasaysayang matamis walang hanggan,<br/>Isinugo ng Diyos bugtong Niyang Anak;<br/>Sa halip natin Siya sa krus namatay,<br/>Napalaya dahil sa katubusan.<br/>',NULL,39533,1);
INSERT INTO stanza VALUES('T112','chorus','Purihin! Purihin!<br/>Natupad gawain.<br/>Ngalan Niya purihin!<br/>Hesus, Anak ng Diyos.<br/>L''walhati kay Hesus na Manunubos;<br/>Awitan si Hesus ng pusong taos.<br/>',NULL,39534,2);
INSERT INTO stanza VALUES('T112','2','Kasaysayang kamangha-mangha ito,<br/>Tinugon ng dugo, hiling ng trono.<br/>Kahatulan, Anak ng Diyos pumasan,<br/>Gawa Niya bigyang kaluwalhatian.<br/>',NULL,39535,3);
INSERT INTO stanza VALUES('T112','chorus','Purihin! Purihin!<br/>Natupad gawain.<br/>Ngalan Niya purihin!<br/>Hesus, Anak ng Diyos.<br/>L''walhati kay Hesus na Manunubos;<br/>Awitan si Hesus ng pusong taos.<br/>',NULL,39536,4);
INSERT INTO stanza VALUES('T112','3','Niluklok sa trono, niluwalhati,<br/>Pinarangalan Siya, ngalan binunyi!<br/>Ang Tagapagligtas pinatunayan.<br/>Karapat-dapat nating papurihan.<br/>',NULL,39537,5);
INSERT INTO stanza VALUES('T112','chorus','Purihin! Purihin!<br/>Natupad gawain.<br/>Ngalan Niya purihin!<br/>Hesus, Anak ng Diyos.<br/>L''walhati kay Hesus na Manunubos;<br/>Awitan si Hesus ng pusong taos.<br/>',NULL,39538,6);
INSERT INTO stanza VALUES('T113','1','Papuri''y kaaya-aya!<br/>Banal ng Diyos iangkop nga;<br/>Kung pag-awit ay tanggihan,<br/>Bato''y sigaw kahihiyan.<br/>',NULL,39539,1);
INSERT INTO stanza VALUES('T113','2','Sa nahugasan ng dugo,<br/>Awit ilaang may lugod;<br/>Nalayo sa Diyos, hanap nga,<br/>Iningata''t kinalinga.<br/>',NULL,39540,2);
INSERT INTO stanza VALUES('T113','3','Kay tamis himig ng kwerdas,<br/>Laan sa mga naligtas;<br/>Sa mga banal ay tangi,<br/>Tugtog lang ng isang lahi.<br/>',NULL,39541,3);
INSERT INTO stanza VALUES('T113','4','Anghel man matuwang masdan,<br/>Sa dugo Niya''y daloy awa;<br/>Sa paglilinis ng dugo,<br/>Patunay tayo, di sila.<br/>',NULL,39542,4);
INSERT INTO stanza VALUES('T113','5','Anghel man purihin Hari,<br/>Siya lamang Diyos na sambahin;<br/>Masaya nating awitin,<br/>Binihis Niya''y likas natin.<br/>',NULL,39543,5);
INSERT INTO stanza VALUES('T113','6','Sinasamba Iyong pagsinta,<br/>Nagdugo at namatay Ka;<br/>Mabawi makasalanan,<br/>Sa Ama madala sila.<br/>',NULL,39544,6);
INSERT INTO stanza VALUES('T114','1','Haring Hesus ay batiin!<br/>Nagdusa para sa ''tin,<br/>Hinamak at tinanggihan;<br/>Hatid ay katubusan;<br/>Dumaan sa kamatayan,<br/>Sala namin pinasan;<br/>Iyong proteksyon ay tamasa,<br/>Sa ngalan Mo''y may gloria.<br/>',NULL,39545,1);
INSERT INTO stanza VALUES('T114','2','Kordero ng Diyos, Ikaw nga,<br/>Pinahiran ng Ama,<br/>Sala namin ay pinasan;<br/>Halaga''y binayaran;<br/>Dahil sa mahal na dugo,<br/>Patawad ay natamo;<br/>Nabuksan bagay ng langit<br/>Biyaya Mo''y sumapit.<br/>',NULL,39546,2);
INSERT INTO stanza VALUES('T114','3','Lumuklok na may l''walhati,<br/>Ang Ama''y Iyong katabi;<br/>Naroon Ka para sa ''min,<br/>Sinasamba Ka namin.<br/>Do''n namamagitan sa ''min,<br/>Iyong pasan, lumbay namin,<br/>Namagitan para sa ''min,<br/>Hanggang gloria''y sapitin.<br/>',NULL,39547,3);
INSERT INTO stanza VALUES('T114','4','Samba, dangal puri''t pala<br/>Karapat-dapat Ka nga,<br/>Ang pagbunyi''y huwag humupa,<br/>Tinig lakasan pa nga;<br/>Tayo ay magpapangita,<br/>Aming salubungin Ka;<br/>Galak nagmula nga sa Iyo,<br/>Tugon ng aming puso.<br/>',NULL,39548,4);
INSERT INTO stanza VALUES('T115','1','L''walhati kay Hesus—<br/>Hirap inako;<br/>Galing sa ugat Niya,<br/>Dugo''y binubo.<br/>',NULL,39549,1);
INSERT INTO stanza VALUES('T115','2','Biyaya''t buhay sa<br/>Dugo''y nakita;<br/>Awang pinagpala<br/>At masagana.<br/>',NULL,39550,2);
INSERT INTO stanza VALUES('T115','3','Dugong umaagos,<br/>Di humuhupa,<br/>Ang tao''y tinubos,<br/>Sa pagdurusa.<br/>',NULL,39551,3);
INSERT INTO stanza VALUES('T115','4','Dugo ni Abel, ang<br/>Samo ay ganti;<br/>Kay Hesus, patawad<br/>Ang isinukli.<br/>',NULL,39552,4);
INSERT INTO stanza VALUES('T115','5','Budhi''y nawisikan,<br/>Puso''y malaya;<br/>Satanas tatakas<br/>Sa pagkagitla.<br/>',NULL,39553,5);
INSERT INTO stanza VALUES('T115','6','Mundo''y nagdiriwang<br/>At nagpupuri;<br/>Anghel nag-awitan<br/>At nagbubunyi.<br/>',NULL,39554,6);
INSERT INTO stanza VALUES('T115','7','Tinig ninyo''y laksan,<br/>O mga banal;<br/>Bigyan ng papuri,<br/>Dugo Niyang mahal.<br/>',NULL,39555,7);
INSERT INTO stanza VALUES('T116','1','Kahanga-hangang pagtubos<br/>Buhat sa Iyo, Hesus.<br/>Di nakita, di nabatid<br/>Sa ''kin, pinahatid.<br/>Mahiwaga''t dibino Ka,<br/>Higit sa mawika!<br/>Katubusang mahiwaga,<br/>Kapuri-puri nga!<br/>',NULL,39556,1);
INSERT INTO stanza VALUES('T116','2','Sa krus Ikaw ay inulos,<br/>Nang dahil sa amin;<br/>Dugo at tubig umagos,<br/>Nang kami''y tubusin.<br/>Sa dugo''y nilinis kami,<br/>Nang matanggap, kami<br/>''Sinilang-muli, sa buhay<br/>Ika''y kaisang tunay.<br/>',NULL,39557,2);
INSERT INTO stanza VALUES('T116','3','Trigong butil, namatay Ka.<br/>Maraming ''binunga,<br/>At nabuong Iyong Katawan,<br/>Pinag-isang tanan.<br/>Kami ay Iyong karagdagan,<br/>Ika''y nilalaman;<br/>Nabubuhay Ka sa amin,<br/>At nahahayag din.<br/>',NULL,39558,3);
INSERT INTO stanza VALUES('T116','4','Yamang kami''y Iyong Katawan,<br/>Sa ami''y tumahan;<br/>Tahanan Mo''y kamtin sa ''min,<br/>Kami''y Iyong manahin.<br/>Puso Mo''y bigyang-ligaya,<br/>Kami''y kapareha,<br/>Bilang Katawan Mong isa,<br/>Lahat Mo''y tamasa.<br/>',NULL,39559,4);
INSERT INTO stanza VALUES('T116','5','Habang ginugunita Ka,<br/>Sagisag nakita;<br/>Pagtubos dakila''t punô,<br/>Papuri ay sa Iyo.<br/>Yamang kami''y Iyong Katawan,<br/>Sinta at tahanan,<br/>Pasalamat at papuri,<br/>Pagsamba''y Iyong lagi.<br/>',NULL,39560,5);
INSERT INTO stanza VALUES('T117','1','Kristo''y nabuhay muli, Aleluya!<br/>Kamataya''y pinawi, Aleluya!<br/>Umawit sa tagumpay, Aleluya!<br/>Langit, lupa''y sasabay, Aleluya!<br/>',NULL,39561,1);
INSERT INTO stanza VALUES('T117','2','Sa Hades Siya''y lumabas, Aleluya!<br/>Libingan, walang lakas, Aleluya!<br/>Kamataya''y nilipol, Aleluya!<br/>Buhay muling sumibol, Aleluya!<br/>',NULL,39562,2);
INSERT INTO stanza VALUES('T117','3','Naganap ang pagtubos, Aleluya!<br/>Ang kaaway tinapos, Aleluya!<br/>Di hadlang kamatayan, Aleluya!<br/>Siya''y sumakalangitan, Aleluya!<br/>',NULL,39563,3);
INSERT INTO stanza VALUES('T117','4','Nabuhay na rin tayo, Aleluya!<br/>Sa luklukan naupo, Aleluya!<br/>Mal''walhating tulad Niya, Aleluya!<br/>Sa mundo''y pinalaya, Aleluya!<br/>',NULL,39564,4);
INSERT INTO stanza VALUES('T118','1','Siya''y nagbangon! Aleluya!<br/>Ang Ulong matagumpay;<br/>Purihin Siya; Aleluya!<br/>Kristo''y muling nabuhay:<br/>Puso nati''y sambahin Siya,<br/>Ilaw Niya''y nagpakita;<br/>Magpatirapa sa Kanya,<br/>Sa pighati''y lumaya.<br/>',NULL,39565,1);
INSERT INTO stanza VALUES('T118','chorus','Siya''y nagbangon: Aleluya!<br/>Ang Ulong matagumpay;<br/>Purihin Siya! Aleluya!<br/>Kristo''y muling-nabuhay.<br/>',NULL,39566,2);
INSERT INTO stanza VALUES('T118','2','Siya''y nagbangon! Natapos nga<br/>Ang hapis ng buhay Niya;<br/>Sa pinto ng kagalakan,<br/>Nabuhay muling minsan.<br/>Kamatayan ay nagapi,<br/>Ngayon Siya ang nagwagi,<br/>Sa paa anghel nagsilbi,<br/>Noo Niya''y luwalhati.<br/>',NULL,39567,3);
INSERT INTO stanza VALUES('T118','chorus','Siya''y nagbangon: Aleluya!<br/>Ang Ulong matagumpay;<br/>Purihin Siya! Aleluya!<br/>Kristo''y muling-nabuhay.<br/>',NULL,39568,4);
INSERT INTO stanza VALUES('T118','3','Siya''y nagbangon! At kailanman,<br/>Wala nang kamatayan;<br/>Tayo''y kay Kristo kailanman,<br/>Lahat pinagwagian.<br/>Alinlangan, panlupaypay<br/>Ng puso ay humupa.<br/>''To''y araw ng pagkabuhay;<br/>Magbangon at magpista.<br/>',NULL,39569,5);
INSERT INTO stanza VALUES('T118','chorus','Siya''y nagbangon: Aleluya!<br/>Ang Ulong matagumpay;<br/>Purihin Siya! Aleluya!<br/>Kristo''y muling-nabuhay.<br/>',NULL,39570,6);
INSERT INTO stanza VALUES('T119','1','Aleluya! Nabuhay na!<br/>Si Kristo''y umakyat na!<br/>Tao''t anghel nagsigawan<br/>Daig na''ng kamatayan.<br/>Nabuhay Siya! Nabuhay Siya!<br/>''Di na mamamatay pa!<br/>',NULL,39571,1);
INSERT INTO stanza VALUES('T119','2','Aleluya! Nabuhay na!<br/>Ulong itinaas Siya!<br/>Ibinigay Espiritu.<br/>Siya ay pinatotoo<br/>Nabuhay na! Nabuhay na!<br/>Inaring-matuwid Niya.<br/>',NULL,39572,2);
INSERT INTO stanza VALUES('T119','3','Aleluya! Nabuhay na!<br/>Kamatayan talo na!<br/>Kristo''y pagkabuhay-muli,<br/>Bubuhayin pinili.<br/>Nabuhay na! Nabuhay na!<br/>Darating na Hari Siya!<br/>',NULL,39573,3);
INSERT INTO stanza VALUES('T120','1','Panginoon muling nabuhay na,<br/>Hatol ng kamatayan lipas na.<br/>Sa loob Niya, tapos kamatayan<br/>Libingan ni Hesus walang laman!<br/>',NULL,39574,1);
INSERT INTO stanza VALUES('T120','2','Panginoon muling nabuhay na,<br/>Kalakip Niya tayong bumangon na!<br/>Sa libingan Niya kaaway talo<br/>Sa pagkabuhay, tayo''y panalo.<br/>',NULL,39575,2);
INSERT INTO stanza VALUES('T120','3','Panginoon muling-nabuhay na,<br/>Tungo sa Diyos tayo''y natubos na!<br/>Sa Kabanal-banalan, tayo na<br/>Sa presensya ng Diyos kasama Siya.<br/>',NULL,39576,3);
INSERT INTO stanza VALUES('T120','4','Panginoon, muling-nabuhay na!<br/>Inaasam nating makita Siya.<br/>Siya''y nabuhay, ating ipagbunyi,<br/>"Tagumpay Ka! Pinalaya kami!"<br/>',NULL,39577,4);
INSERT INTO stanza VALUES('T121','1','Sa matagumpay na Anak: gloria!<br/>Sa kamatayan nagwaging lubos Ka;<br/>Mga anghel iginulong ang bato,<br/>Libingang hungkag, buhay Kang totoo.<br/>',NULL,39578,1);
INSERT INTO stanza VALUES('T121','chorus','Sa matagumpay na Anak: gloria!<br/>Sa kamataya''y nagwaging lubos Ka.<br/>',NULL,39579,2);
INSERT INTO stanza VALUES('T121','2','Kristong nabuhay ating nakita,<br/>Dilim napawi tayo''y binati Niya;<br/>Nawa''y ekklesia magalak, umawit<br/>Kristo''y nabuhay kamataya''y daig.<br/>',NULL,39580,3);
INSERT INTO stanza VALUES('T121','chorus','Sa matagumpay na Anak: gloria!<br/>Sa kamataya''y nagwaging lubos Ka.<br/>',NULL,39581,4);
INSERT INTO stanza VALUES('T122','1','Di sa kasalanan,<br/>Nahatulan;<br/>Lupang kamatayan,<br/>Nilakaran.<br/>Namahalang diyablo.<br/>Lubos Mong tinalo;<br/>Tao''y di mabihag<br/>Ni mabitag.<br/>',NULL,39582,1);
INSERT INTO stanza VALUES('T122','2','Libinga''y ginapi,<br/>Buháy muli,<br/>Pinagtagumpayan<br/>Kamatayan!<br/>Lumabas tuluyan,<br/>Mula sa libingan,<br/>Ang Hades tinalo<br/>Ng Kristo ko!<br/>',NULL,39583,2);
INSERT INTO stanza VALUES('T122','3','Kay laking tagumpay<br/>Iyong tinaglay,<br/>Lubhang masagana<br/>Ang Iyong gloria.<br/>Sa Iyong pagkamatay,<br/>Libo ang nabuhay.<br/>Bilang Iyong tahanan<br/>Iyong tirahan.<br/>',NULL,39584,3);
INSERT INTO stanza VALUES('T122','4','Ika''y unang-bunga,<br/>Aming Sinta;<br/>Panganay ng Diyos Ka,<br/>Nangunguna.<br/>Sa lahat higit Ka,<br/>Ang Ulo''y Ikaw nga.<br/>Karapat-dapat Ka,<br/>Sa pagsamba.<br/>',NULL,39585,4);
INSERT INTO stanza VALUES('T123','1','Doon sa libingan,<br/>Ang Panginoon,<br/>Araw hinihintay,<br/>Sa pagbangon.<br/>',NULL,39586,1);
INSERT INTO stanza VALUES('T123','chorus','Nagbangon sa libingan,<br/>Dinaig Niya mga kalaban;<br/>Kristo''y nagtagumpay sa kadiliman<br/>At nabuhay nang maghari kailanman.<br/>Si Kristo''y nagbangon!<br/>Aleluya! Nagbangon!<br/>',NULL,39587,2);
INSERT INTO stanza VALUES('T123','2','Walang katuturan<br/>Kanilang bantay;<br/>Ang patay sinarhan<br/>Walang saysay.<br/>',NULL,39588,3);
INSERT INTO stanza VALUES('T123','chorus','Nagbangon sa libingan,<br/>Dinaig Niya mga kalaban;<br/>Kristo''y nagtagumpay sa kadiliman<br/>At nabuhay nang maghari kailanman.<br/>Si Kristo''y nagbangon!<br/>Aleluya! Nagbangon!<br/>',NULL,39589,4);
INSERT INTO stanza VALUES('T123','3','Di Siya napigilan<br/>Ng kamatayan;<br/>Hinawi ang rehas<br/>Ng piitan.<br/>',NULL,39590,5);
INSERT INTO stanza VALUES('T123','chorus','Nagbangon sa libingan,<br/>Dinaig Niya mga kalaban;<br/>Kristo''y nagtagumpay sa kadiliman<br/>At nabuhay nang maghari kailanman.<br/>Si Kristo''y nagbangon!<br/>Aleluya! Nagbangon!<br/>',NULL,39591,6);
INSERT INTO stanza VALUES('T124','1','Puri, puri! Purihin Siya!<br/>Nagtagumpay si Kristo.<br/>Sala''t Adam dinaig Niya,<br/>Katubusan nabuo!<br/>Lakas ni Satanas talo,<br/>Sa Krus nagwagi tayo.<br/>',NULL,39592,1);
INSERT INTO stanza VALUES('T124','2','Puri, puri! Purihin Siya!<br/>Kristo''y muling nabuhay!<br/>Kamataya''y nilulon Niya,<br/>Tao ay pinalaya!<br/>Hades at dilim winasak,<br/>Pagkabuhay nahayag.<br/>',NULL,39593,2);
INSERT INTO stanza VALUES('T124','3','Puri! Kristo''y sumalangit!<br/>Kapangyariha''y Kanya!<br/>Kataas-taasang Ngalan<br/>Ibinigay sa Kanya!<br/>Lahat ng namumunuan<br/>Gagawin Niyang tuntungan.<br/>',NULL,39594,3);
INSERT INTO stanza VALUES('T124','4','Aleluya! Purihin Siya!<br/>Sa Kalbaryo''y nagwagi!<br/>Puri! Muling nabuhay Siya,<br/>Aleluya, nagwagi!<br/>Aleluya, sumalangit,<br/>Hari ng mga hari!<br/>',NULL,39595,4);
INSERT INTO stanza VALUES('T126','1','Mahal naming Kristo ng Diyos,<br/>Awit sa Iyong lubos;<br/>Katubusan tinupad Mo,<br/>Pala''y aming ''tamo.<br/>Ika''y lumuklok sa trono,<br/>Kalaban tinalo.<br/>Dadalhin sa luwalhati,<br/>Magpatunay nga kami.<br/>',NULL,39596,1);
INSERT INTO stanza VALUES('T126','2','Mahal naming Kristo ng Diyos,<br/>Awit sa Iyong lubos;<br/>Kamataya''y nilusob Mo.<br/>Siya''y I-yong tinalo.<br/>Ang alabok na tahanan,<br/>Tinalong lubusan;<br/>Ikaw pa rin ang may tangan,<br/>Sa Hades, libingan.<br/>',NULL,39597,2);
INSERT INTO stanza VALUES('T126','3','Mahal naming Kristo ng Diyos,<br/>Awit sa Iyong lubos,<br/>Mapanghimagsik na diyablo.<br/>Sa krus winasak Mo.<br/>Kapangyarihan ng buhay,<br/>Hades walang saysay;<br/>Lakas ng dilim, wala na<br/>Bihag pinalaya.<br/>',NULL,39598,3);
INSERT INTO stanza VALUES('T126','4','Mahal naming Kristo ng Diyos,<br/>Awit sa Iyong lubos;<br/>Mandaraig at Poon din,<br/>Nagpalaya sa ''kin.<br/>Lakas ng kaligtasan Ka,<br/>Ako''y pinalaya.<br/>Sa Iyo nga''y kal''walhatian,<br/>Hanggang walang hanggan.<br/>',NULL,39599,4);
INSERT INTO stanza VALUES('T127','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,39600,1);
INSERT INTO stanza VALUES('T127','1','Sampung libong tinig humihiyaw<br/>Nang sabay: "Kordero ng Diyos;"<br/>Mga tinig umaalingawngaw,<br/>Purihin Kordero ng Diyos.<br/>',NULL,39601,2);
INSERT INTO stanza VALUES('T127','2','"Purihin ang Kordero!" ang awit<br/>Ng pagpupulong sa langit;<br/>Ang bawa''t dila ay sumasambit,<br/>Walang-hanggang umaawit.<br/>',NULL,39602,3);
INSERT INTO stanza VALUES('T127','3','Insenso ng pagpapasalamat<br/>''Taas sa trono ng Ama;<br/>Bawa''t tuhod kay Hesus iluhod,<br/>Ang isip sa langit isa.<br/>',NULL,39603,4);
INSERT INTO stanza VALUES('T127','4','Lahat ng hangarin ng Diyos Ama<br/>Ay karangalan sa Anak,<br/>Hinayag ang l''walhati ng Ama,<br/>Sa pagniningning ng Anak.<br/>',NULL,39604,5);
INSERT INTO stanza VALUES('T127','5','Dahil sa ''Spiritu Siya''y dagsaan,<br/>Kordero''y pinaligiran,<br/>Galak, liwanag Siya''y pinutungan,<br/>Ang "Ako nga," papurihan.<br/>',NULL,39605,6);
INSERT INTO stanza VALUES('T127','6','Masigla na ang bagong nilikha<br/>Walang gambalang pahinga,<br/>Sa kaligtasan ay pinagpala,<br/>Walang lungkot, pagkaaba.<br/>',NULL,39606,7);
INSERT INTO stanza VALUES('T127','7','O pakinggan himig makalangit,<br/>Lumalakas ang papuri;<br/>Nagmumula sa nilikha, Amen!<br/>Pagtugong may galak, Amen.<br/>',NULL,39607,8);
INSERT INTO stanza VALUES('T128','1','Higit sa lahat ang Manliligtas<br/>Sa salarin, Kordero ang lunas,<br/>Nabubuhay nang ating matawag,<br/>Tinaas ng Diyos higit sa lahat.<br/>',NULL,39608,1);
INSERT INTO stanza VALUES('T128','chorus','Napako sa krus na Kristo!<br/>Napakatayog, higit sa lahat!<br/>Sangkap Niya na tumatawag tayo,<br/>Tinaas ng Diyos higit sa lahat!<br/>',NULL,39609,2);
INSERT INTO stanza VALUES('T128','2','Kung matinding alon dumaluyong;<br/>Kaligtasa''y nasa Panginoon,<br/>Tingnan si Hesus, tayo''y tangan Niya,<br/>Lumakad sa alon nang payapa.<br/>',NULL,39610,3);
INSERT INTO stanza VALUES('T128','3','Sa ating paglaban, hadlangan man,<br/>Balakid, mataas na kalaban;<br/>Magpapatuloy walang pangamba<br/>Humigit pananalig sa Kanya.<br/>',NULL,39611,5);
INSERT INTO stanza VALUES('T128','4','Tanging sa Kanya ang kaharian,<br/>Saklaw ang tanang kapanahunan,<br/>Kasama''y matagumpay na banal,<br/>Maharlika na higit sa lahat.<br/>',NULL,39612,7);
INSERT INTO stanza VALUES('T129','1','Maluwalhating Kordero,<br/>Lakas, Siya''ng nagtamo:<br/>Hindi Siya mahihigitan,<br/>Maging sa langit man.<br/>',NULL,39613,1);
INSERT INTO stanza VALUES('T129','2','Pinuno Ni-ya ang trono;<br/>Sa Kanya lang ito;<br/>Siya ang sinta ng Amang Diyos<br/>Awit ng tinubos.<br/>',NULL,39614,2);
INSERT INTO stanza VALUES('T129','3','Mga banal nagpupuri,<br/>Tanggap Niyang palagi;<br/>Tinig na napakahinay,<br/>Diringgin Niyang tunay.<br/>',NULL,39615,3);
INSERT INTO stanza VALUES('T129','4','Awitin sa kaisahan<br/>Itanghal ang Ngalan<br/>Ng nasa trono sa ''taas,<br/>Kordero''y itaas.<br/>',NULL,39616,4);
INSERT INTO stanza VALUES('T129','5','Siya''y nilibak at tinuya,<br/>L''walhati sa Kanya;<br/>Kataasan at korona<br/>Ay pawang sa Kanya.<br/>',NULL,39617,5);
INSERT INTO stanza VALUES('T130','1','Paakyat ang Mandaraig,<br/>Dala''y gloria ng Hari;<br/>Sakay ng ulap patungo,<br/>Sa langit na palasyo.<br/>Aleluya, kagalakan,<br/>Anghel nagsiawitan.<br/>Mga pintuan nabuksan.<br/>Tanggapin, tanggapin<br/>Ang Kristong Hari natin.<br/>',NULL,39618,1);
INSERT INTO stanza VALUES('T130','2','Sino ang karapat-dapat,<br/>Papurihan nang tapat.<br/>Panginoon ng digmaan,<br/>Tamo katagumpayan.<br/>Hirap ng krus binata Niya,<br/>Sa patay nabuhay Siya.<br/>Sa kamatayan, sinira<br/>Satanas at sala<br/>Lubusang natalo nga!<br/>',NULL,39619,2);
INSERT INTO stanza VALUES('T130','3','Nahiwalay sa kanila,<br/>Habang Siya''y nagpapala.<br/>Tinitingnan ng alagad,<br/>Habang Siya''y inaakyat;<br/>Diyos, binigyang kaluguran,<br/>Hayag katotohanan.<br/>Inakyat may kagalakan,<br/>Siyang tunay na Enoch<br/>Sa harap ng aking Diyos.<br/>',NULL,39620,3);
INSERT INTO stanza VALUES('T130','4','Aaron ko dala''y dugo,<br/>Tungo''y Banal na Dako.<br/>Tungong Canaan Josue ko<br/>Tanang hari tinalo.<br/>Sa ipinangakong lupa<br/>Piling tao''y dinala.<br/>Ngayon ang dobleng biyaya:<br/>Elias ko namigay.<br/>Pagpapala''y mataglay.<br/>',NULL,39621,4);
INSERT INTO stanza VALUES('T130','5','Sa kanan ng Diyos inupo,<br/>Tinaas pagka-tao.<br/>Tayo''y kasamang naluklok,<br/>Sa mal''walhating rurok.<br/>Hari Ka, anghel sumamba,<br/>Sa langit umakyat Ka.<br/>Sa trono tao''y kasama,<br/>Nananalig ako.<br/>Nananalig, matamo.<br/>',NULL,39622,5);
INSERT INTO stanza VALUES('T131','1','Poon puso ko''y masaya,<br/>Dahil sa ''kin nagdusa Ka;<br/>Ngayo''y lumipas na,<br/>Nagtagumpay ang Iyong gawa,<br/>Diyos sa Iyo''y nagluwalhati,<br/>Ito''y Iyong pag-ani.<br/>',NULL,39623,1);
INSERT INTO stanza VALUES('T131','2','Ulong ang putong ay tinik,<br/>Ngayon sa gloria ay hitik;<br/>Sa trono ng Ama,<br/>Niluklok Ka, purihin Ka!<br/>Tanging karapat-dapat Ka,<br/>Sa aming pagsamba!<br/>',NULL,39624,2);
INSERT INTO stanza VALUES('T131','3','Tagumpay Mo ay amin din,<br/>Galak Mo''y aming galak din,<br/>Sinta Mo''y nagbunga.<br/>Sa pagpagal, pagdurusa<br/>Inisip nang maligaya,<br/>Trono ay sa Iyo nga.<br/>',NULL,39625,3);
INSERT INTO stanza VALUES('T132','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,39626,1);
INSERT INTO stanza VALUES('T132','1','Masdan sa langit si Hesu-Kristo,<br/>Nasa trono na Panginoon;<br/>Dinakila Siya bilang ang tao,<br/>Gloria sa Kanya''y pinutong.<br/>',NULL,39627,2);
INSERT INTO stanza VALUES('T132','2','Nagkatawang-tao''t namatay Siya,<br/>Nang ayon sa layunin ng Diyos;<br/>Muling nabuhay na may katawan,<br/>Umakyat na taong lubos.<br/>',NULL,39628,3);
INSERT INTO stanza VALUES('T132','3','Ang Diyos sa Kanya''y napakumbaba,<br/>Ang Diyos sa tao''y napatira;<br/>Sa Kanya''y napataas ang tao,<br/>Tao at Diyos nagkasundo.<br/>',NULL,39629,4);
INSERT INTO stanza VALUES('T132','4','Siya bilang Diyos — humalo sa tao,<br/>Diyos sa tao''y napatotoo;<br/>Siya bilang tao''y nahalo sa Diyos,<br/>Tao''y nal''walhati sa Diyos.<br/>',NULL,39630,5);
INSERT INTO stanza VALUES('T132','5','Mula sa Nal''walhati sa langit<br/>Ay dumating ang Espiritu;<br/>Gawa''t Persona ni Hesu-Kristo,<br/>Inihayag ng ''Spiritu.<br/>',NULL,39631,6);
INSERT INTO stanza VALUES('T132','6','At sa Naluwalhati sa langit<br/>Ekklesia Niya''y nakikiisa;<br/>Sa Espiritu ni Hesu-Kristo,<br/>Mga banal — itinayo.<br/>',NULL,39632,7);
INSERT INTO stanza VALUES('T132','7','O ngayo''y may Tao na sa langit,<br/>Nakaluklok Poon ng lahat!<br/>Pinutungan ng l''walhati ng Diyos,<br/>Kristo na Tagapagligtas.<br/>',NULL,39633,8);
INSERT INTO stanza VALUES('T133','1','O Panginoon ng lahat,<br/>May putong mal''walhati;<br/>Ika''y kilala sa lahat<br/>Sa lakas, pagkahari.<br/>',NULL,39634,1);
INSERT INTO stanza VALUES('T133','2','Sa loob ng tao, ang Diyos<br/>Nasa aliping anyo;<br/>Ang tao sa loob ng Diyos,<br/>Lahat sa Iyo''y umako.<br/>',NULL,39635,2);
INSERT INTO stanza VALUES('T133','3','Tao kang nasa l''walhati,<br/>Ginawang Hari ng Diyos;<br/>Lahat ng kapangyarihan,<br/>Pag-aari Mong lubos.<br/>',NULL,39636,3);
INSERT INTO stanza VALUES('T133','4','''Tinaas sa kalangitan,<br/>Dinakilang Pangalan;<br/>Yuyuko sa Iyo ang tanan,<br/>Sasamba sa Iyong Ngalan.<br/>',NULL,39637,4);
INSERT INTO stanza VALUES('T133','5','Itinatag Ka nga ng Diyos,<br/>Panginoon at Kristo;<br/>Sa kal''walhatian lubos,<br/>Kabahagi sa trono.<br/>',NULL,39638,5);
INSERT INTO stanza VALUES('T133','6','O sinasamba Ka namin<br/>Panginoon ng lahat;<br/>Awit sa Iyo''y inihain,<br/>Ika''y karapat-dapat.<br/>',NULL,39639,6);
INSERT INTO stanza VALUES('T134','1','Gloria, walang hanggang gloria,<br/>Sa Kordero sa trono.<br/>Gloria, walang hanggang gloria,<br/>Sa mahal na Ngalan Niya.<br/>Nangingibabaw na ngalan,<br/>Sa langit o lupa man<br/>Gloria, gloriang walang hanggan,<br/>Sa marangal Niyang ngalan.<br/>',NULL,39640,1);
INSERT INTO stanza VALUES('T134','2','Kapantay ng Diyos, naupo,<br/>Nasa langit na trono;<br/>Anyong alipin kinuha,<br/>Dinanas pagdurusa.<br/>Layon ng Ama sinundan,<br/>Hanggang kamatayan man;<br/>Sa krus kahihiyang ganap,<br/>Minatamis, tinanggap.<br/>',NULL,39641,2);
INSERT INTO stanza VALUES('T134','3','Putong sa langit at gloria,<br/>Sa Kanyang nagpababa;<br/>Damit mainam kay ringal,<br/>Ibihis sa marangal,<br/>Lahat luluhod sa Kanya,<br/>Bibig ipahayag Siya.<br/>Hari ng mga hari Siya,<br/>Papuri''t gloria''y Kanya.<br/>',NULL,39642,3);
INSERT INTO stanza VALUES('T134','4','Gloria, walang hanggang gloria,<br/>Sa Iyo di mahigtan na.<br/>Gloria sa langit at lupa,<br/>Gloria pawang sa Kanya.<br/>Gloria sa Diyos, gloria, gloria<br/>Sa dakilang AKO NGA.<br/>Gloria, gloriang walang hanggan,<br/>Magpaka-ilanpaman.<br/>',NULL,39643,4);
INSERT INTO stanza VALUES('T136','1','Panginoong nasa gloria,<br/>Puso namin sumamba;<br/>Salaysay aming binasa,<br/>Tungkol sa krus, pagdusa.<br/>',NULL,39644,1);
INSERT INTO stanza VALUES('T136','2','Bawa''t bakas ng pagdusta<br/>Sa ulong putong tinik,<br/>Sa lalim ng Iyong pighati,<br/>Ngayon gloria kapalit.<br/>',NULL,39645,2);
INSERT INTO stanza VALUES('T136','3','Nang sa krus Ika''y nag-isa<br/>Itinakwil, ulila;<br/>Ngayon nasa kanan ng Diyos,<br/>Pagpuri''t awit lubos.<br/>',NULL,39646,3);
INSERT INTO stanza VALUES('T136','4','Binitiwan Ka nga ng Diyos<br/>Itinakwil nang lubos,<br/>Sa inalipustang mukha,<br/>Ngayo''y gloria ng Ama.<br/>',NULL,39647,4);
INSERT INTO stanza VALUES('T136','5','Amin Ka ngang sinasamba,<br/>Pangino''ng pinagpala;<br/>Karapat-dapat purihin,<br/>Kordero ng Diyos, Amen!<br/>',NULL,39648,5);
INSERT INTO stanza VALUES('T136','6','Diyos Ama ay papurihan,<br/>Puso magsiawitan;<br/>Ama''t Anak papurihan.<br/>Hanggang sa walang hanggan.<br/>',NULL,39649,6);
INSERT INTO stanza VALUES('T138','1','Ngalang Hesus parangalan!<br/>Anghel tumirapa;<br/>Korona Siya ay putungan,<br/>',NULL,39650,1);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39651,2);
INSERT INTO stanza VALUES('T138','2','Tinawag na mga martir,<br/>Siya''y inyong putungan;<br/>Ugat ng tungkod ni Jesse,<br/>',NULL,39652,3);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39653,4);
INSERT INTO stanza VALUES('T138','3','Poong tinawag ni David,<br/>Siya''y pagbunyi ninyo;<br/>Diyos-tao, Taong Dibino;<br/>',NULL,39654,5);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39655,6);
INSERT INTO stanza VALUES('T138','4','Piling binhi ng Israel,<br/>Natubos, naligtas;<br/>Purihin Kanyang biyaya,<br/>',NULL,39656,7);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39657,8);
INSERT INTO stanza VALUES('T138','5','Maysala hu-wag limutin<br/>Ang pait at poot,<br/>Parangal handugan mo Siya.<br/>',NULL,39658,9);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39659,10);
INSERT INTO stanza VALUES('T138','6','Ang bawa''t lipi at angkan<br/>Buong sanlibutan;<br/>Siya ay bigyang-karangalan,<br/>',NULL,39660,11);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39661,12);
INSERT INTO stanza VALUES('T138','7','Tayo ay magpatirapa,<br/>Sa Kanyang paanan;<br/>Walang hanggan ang awitan,<br/>',NULL,39662,13);
INSERT INTO stanza VALUES('T138','chorus','Putungan, Putungan Siya,<br/>Poon ng lahat!<br/>',NULL,39663,14);
INSERT INTO stanza VALUES('T139','1','Ngalang Hesus parangalan!<br/>Anghel tumirapa,<br/>Anghel tumirapa;<br/>Korona Siya ay putungan,<br/>',NULL,39664,1);
INSERT INTO stanza VALUES('T139','chorus','At Siya''y putungan,<br/>Putungan Siya;<br/>Putungan, Pangino''n ng tanan!<br/>',NULL,39665,2);
INSERT INTO stanza VALUES('T139','2','Piling lahi ni Israel,<br/>Natubos, naligtas,<br/>Natubos, naligtas;<br/>Purihin Kanyang biyaya,<br/>',NULL,39666,3);
INSERT INTO stanza VALUES('T139','chorus','At Siya''y putungan,<br/>Putungan Siya;<br/>Putungan, Pangino''n ng tanan!<br/>',NULL,39667,4);
INSERT INTO stanza VALUES('T139','3','Maysala hu-wag limutin<br/>Ang pait at poot,<br/>Ang pait at poot;<br/>Parangal handugan mo Siya,<br/>',NULL,39668,5);
INSERT INTO stanza VALUES('T139','chorus','At Siya''y putungan,<br/>Putungan Siya;<br/>Putungan, Pangino''n ng tanan!<br/>',NULL,39669,6);
INSERT INTO stanza VALUES('T139','4','Ang bawa''t lipi at angkan,<br/>Buong sanlibutan,<br/>Buong sanlibutan;<br/>Siya ay bigyang-karangalan!<br/>',NULL,39670,7);
INSERT INTO stanza VALUES('T139','chorus','At Siya''y putungan,<br/>Putungan Siya;<br/>Putungan, Pangino''n ng tanan!<br/>',NULL,39671,8);
INSERT INTO stanza VALUES('T139','5','Tayo ay magpatirapa,<br/>Sa Kanyang paanan,<br/>Sa Kanyang paanan;<br/>Walang hanggan ang awitan.<br/>',NULL,39672,9);
INSERT INTO stanza VALUES('T139','chorus','At Siya''y putungan,<br/>Putungan Siya;<br/>Putungan, Pangino''n ng tanan!<br/>',NULL,39673,10);
INSERT INTO stanza VALUES('T140','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39674,1);
INSERT INTO stanza VALUES('T140','1','O tanawing mal''walhati<br/>Ang Tao ng pighati;<br/>Dala''y tagumpay sa digma,<br/>Lahat luluhuran Siya.<br/>Putungan Siya! Siya''y nanaig.<br/>Putungang Mandaraig.<br/>',NULL,39675,2);
INSERT INTO stanza VALUES('T140','2','Pinaglaruan ng tao,<br/>Putong tinik sa ulo;<br/>Nguni''t putong ngayo''y gloria,<br/>Anghel, banal sumamba.<br/>Putungan Siya! Siya''y putungan!<br/>Mahal ng Diyos, putungan!<br/>',NULL,39676,3);
INSERT INTO stanza VALUES('T140','3','Maysala, putungan mo Siya,<br/>Samsam ka Niya sa digma;<br/>Labis-labis kagalakan,<br/>Puso''y Kanyang luklukan.<br/>Putungan Siya! Putungan Siya!<br/>Matagumpay putungan!<br/>',NULL,39677,4);
INSERT INTO stanza VALUES('T140','4','O pakinggan ang papuri,<br/>Malakas na pagbunyi;<br/>Hesus sa kaitaasan,<br/>Bigay Niya''y kagalakan,<br/>Putungan Siya, Siya''y putungan!<br/>Siyang kataas-taasan.<br/>',NULL,39678,5);
INSERT INTO stanza VALUES('T141','1','Tinik ang dati Mong putong,<br/>Gloria naman ngayon;<br/>Makalangit na korona,<br/>Iputong sa Kanya.<br/>',NULL,39679,1);
INSERT INTO stanza VALUES('T141','2','Sa banal, Ika''y ligaya,<br/>Ilaw ng langit pa;<br/>Inihayag pag-ibig Mo,<br/>Lalim mabatid ko.<br/>',NULL,39680,2);
INSERT INTO stanza VALUES('T141','3','Sa ''min krus Mo''t kahihiyan,<br/>Biyaya nabigyan;<br/>Lupa''y tanggihan Iyong ngalan,<br/>Diyos magpaparangal.<br/>',NULL,39681,3);
INSERT INTO stanza VALUES('T141','4','Kabalikat sa pagdusa,<br/>Maghari tulad Niya;<br/>Galak bayarang halaga,<br/>Nang layon makuha.<br/>',NULL,39682,4);
INSERT INTO stanza VALUES('T141','5','Sa ''min, buhay, lakas, krus Mo,<br/>Kamatayan sa Iyo;<br/>Ngayon galak, yaman, gloria,<br/>Walang hanggang asa.<br/>',NULL,39683,5);
INSERT INTO stanza VALUES('T144','1','Kristo ng Diyos, mal''walhati;<br/>Sa Iyo''y sumamba kami.<br/>Yuko puso''t kaluluwa,<br/>Sa malabis na gloria:<br/>Purihin Ka''t sambahin,<br/>Landas Mo''y ubod galing!<br/>',NULL,39684,1);
INSERT INTO stanza VALUES('T144','2','Ika''y pinahirang Hari,<br/>May putong na l''walhati.<br/>Kahit ''tinakwil, kinutya<br/>Pagligtas Iyong ginawa.<br/>Mahal Kita''t purihin,<br/>Walang hanggang sambahin!<br/>',NULL,39685,2);
INSERT INTO stanza VALUES('T144','3','Minsan sinumpa''t namatay,<br/>Panginoon ng buhay!<br/>Pinakaibig ng Ama,<br/>Sumunod at nagdusa.<br/>Aming ginugunita,<br/>Panglaw na Iyong binatá!<br/>',NULL,39686,3);
INSERT INTO stanza VALUES('T144','4','Di lalaon mapasa Iyo,<br/>Pangharing putong, setro;<br/>Kristo ng Diyos, itanghal Ka<br/>Hari''t Panginoon nga!<br/>Susundin Ka''t mahalin,<br/>Kristo kikilalanin.<br/>',NULL,39687,4);
INSERT INTO stanza VALUES('T147','1','Pinahiran ng Diyos Ka,<br/>Hari ng lahat nga,<br/>Sa Iyo, sasamba kami,<br/>Aawit papuri,<br/>Palagi pamumuno,<br/>Matatag na trono.<br/>Pag-ibig at katwiran,<br/>Gloria''y katayuan.<br/>',NULL,39688,1);
INSERT INTO stanza VALUES('T147','2','Sa Sion itinalaga,<br/>Ikaw Sinisinta;<br/>''Binigay tanang bansa,<br/>Bilang Iyong pamana.<br/>Sa Iyo, awtoridad Niya<br/>''Pinagkatiwala.<br/>Hanggang sa walang hanggan,<br/>Bansa''y pagharian.<br/>',NULL,39689,2);
INSERT INTO stanza VALUES('T147','3','Panaho''y di pa punô,<br/>Karimla''y namuno,<br/>Tapat na laksang tao,<br/>Pumupuri sa Iyo.<br/>Bawa''t dalampasigan,<br/>Tao''y nag-awitan.<br/>Sinamba at minahal<br/>Haring Manliligtas.<br/>',NULL,39690,3);
INSERT INTO stanza VALUES('T147','4','Sa panahong ''tinakda,<br/>Darating may gloria;<br/>Lupa''t lahat ng bansa<br/>Kaharian Mo na.<br/>Maningning, maharlika,<br/>Haring marangal Ka.<br/>Bawa''t lipi at lahi,<br/>Sa Iyo nga''y pupuri!<br/>',NULL,39691,4);
INSERT INTO stanza VALUES('T148','1','Hari ng mga hari,<br/>Nagpipitagan kami;<br/>Pinahiran ng Diyos Ka,<br/>Sakbibing sambahin Ka.<br/>Hari ng mga hari<br/>Banal awit papuri!<br/>',NULL,39692,1);
INSERT INTO stanza VALUES('T148','2','Lahat ng mga bansa,<br/>Ikaw ang mamahala;<br/>Anumang uring bayan,<br/>Ikaw ang paglingkuran.<br/>Hari ng mga hari,<br/>Lahat sa Iyo''y pupuri.<br/>',NULL,39693,2);
INSERT INTO stanza VALUES('T148','3','Matatag Iyong luklukan,<br/>Patuloy kaharian;<br/>Sa gloria''t kapangyar''han,<br/>Patuloy mag-awitan.<br/>Hari ng mga hari,<br/>Laksang banal pupuri.<br/>',NULL,39694,3);
INSERT INTO stanza VALUES('T148','4','Poong mapagbiyaya,<br/>Ngalan Mo''y aming awit;<br/>Pamumuno kay tamis,<br/>Kaharian ang nais.<br/>Hari ng mga hari,<br/>Kami sa Iyo bubunyi!<br/>',NULL,39695,4);
INSERT INTO stanza VALUES('T149','1','Laksang tinig makalangit,<br/>Papuri inaawit,<br/>Galak sa langit nagpuno,<br/>Haring Hesus sa trono,<br/>Hesus, Diyos ng pag-ibig,<br/>Sa mundo Siya''y naghari.<br/>',NULL,39696,1);
INSERT INTO stanza VALUES('T149','chorus','Aleluya, Aleluya,<br/>Aleluya, Amen.<br/>',NULL,39697,2);
INSERT INTO stanza VALUES('T149','2','Awitin tungkol kay Hesus,<br/>Buhat langit tungo''y krus,<br/>Binigyang kapangyarihan,<br/>Sa gloria''y pagharian.<br/>Di matapos na paksa—<br/>Kay tamis awitin Siya.<br/>',NULL,39698,3);
INSERT INTO stanza VALUES('T149','chorus','Aleluya, Aleluya,<br/>Aleluya, Amen.<br/>',NULL,39699,4);
INSERT INTO stanza VALUES('T149','3','Hesus anong l''walhati Mo—<br/>Papuri''y dapat sa Iyo;<br/>Nagpaligaya Iyong ngiti,<br/>Sa banal nangbighani.<br/>Maisip pag-ibig Mo,<br/>Dibinong angkin ito.<br/>',NULL,39700,5);
INSERT INTO stanza VALUES('T149','chorus','Aleluya, Aleluya,<br/>Aleluya, Amen.<br/>',NULL,39701,6);
INSERT INTO stanza VALUES('T149','4','Magpakailanma''y maghari,<br/>O, Hari ng l''walhati;<br/>Walang makapaglalayo,<br/>Sa ''min sa pag-ibig Mo:<br/>Layon ng Iyong biyaya,<br/>Tadhana''y makita Ka.<br/>',NULL,39702,7);
INSERT INTO stanza VALUES('T149','chorus','Aleluya, Aleluya,<br/>Aleluya, Amen.<br/>',NULL,39703,8);
INSERT INTO stanza VALUES('T149','5','Iyong pagbalik padaliin,<br/>Araw may gloria''y dalhin;<br/>Pag sumapit ang Araw na<br/>Lilipas langit, lupa,<br/>Pusong galak pupuri,<br/>L''walhati sa ''ting Hari.<br/>',NULL,39704,9);
INSERT INTO stanza VALUES('T149','chorus','Aleluya, Aleluya,<br/>Aleluya, Amen.<br/>',NULL,39705,10);
INSERT INTO stanza VALUES('T151','1','Awit nami''y ang Haring darating,<br/>Gloria kay Hesus, Korderong hain;<br/>Kat''wiran nasa kaharian Niya,<br/>Hesus maghari, galak ng bansa.<br/>',NULL,39706,1);
INSERT INTO stanza VALUES('T151','chorus','Mag-awitan, Siya''y purihin!<br/>Hesus, Hesus, Hari natin!<br/>Awit ito ng mga kay Hesus,<br/>Kay Hesus, gloria, gloria kay Hesus.<br/>',NULL,39707,2);
INSERT INTO stanza VALUES('T151','2','Sa liwanag Niya, tao''y titira;<br/>Lahing watak bibigkis pagsinta;<br/>Setro kat''wiran, katotohanan,<br/>Pag Siya''y naghari, mali''y wakasan.<br/>',NULL,39708,3);
INSERT INTO stanza VALUES('T151','chorus','Mag-awitan, Siya''y purihin!<br/>Hesus, Hesus, Hari natin!<br/>Awit ito ng mga kay Hesus,<br/>Kay Hesus, gloria, gloria kay Hesus.<br/>',NULL,39709,4);
INSERT INTO stanza VALUES('T151','3','Sa kaharia''y kapayapaan,<br/>Mayabong ang laya''t karunungan,<br/>Maging kai-bigan na ang kaalit,<br/>Paghari Niya''y tabak maging karit.<br/>',NULL,39710,5);
INSERT INTO stanza VALUES('T151','chorus','Mag-awitan, Siya''y purihin!<br/>Hesus, Hesus, Hari natin!<br/>Awit ito ng mga kay Hesus,<br/>Kay Hesus, gloria, gloria kay Hesus.<br/>',NULL,39711,6);
INSERT INTO stanza VALUES('T151','4','Kaalaman sa Diyos, takot, nginig,<br/>Gayang tubig sa dagat tumakip;<br/>Lahat nasa tagsibol, maganda<br/>Magkasundo lahat paghari Niya.<br/>',NULL,39712,7);
INSERT INTO stanza VALUES('T151','chorus','Mag-awitan, Siya''y purihin!<br/>Hesus, Hesus, Hari natin!<br/>Awit ito ng mga kay Hesus,<br/>Kay Hesus, gloria, gloria kay Hesus.<br/>',NULL,39713,8);
INSERT INTO stanza VALUES('T151','5','Kaharian ni Kristo ang samo,<br/>O Ama, Iyong padaliin ito;<br/>Bagong awit aming hinihimig,<br/>Hesus ang hari, Satanas ''lupig.<br/>',NULL,39714,9);
INSERT INTO stanza VALUES('T151','chorus','Mag-awitan, Siya''y purihin!<br/>Hesus, Hesus, Hari natin!<br/>Awit ito ng mga kay Hesus,<br/>Kay Hesus, gloria, gloria kay Hesus.<br/>',NULL,39715,10);
INSERT INTO stanza VALUES('T152','1','Kay lalim ng pag-ibig Mo,<br/>Lawak di ko matanto!<br/>Higit kaysa dagat lalim,<br/>Umabot pa sa akin.<br/>Sarili Mo''y ibinigay,<br/>Upang Kita''y mataglay.<br/>Ako''y nakahugpong sa Iyo,<br/>Nang maging bahagi Mo.<br/>',NULL,39716,1);
INSERT INTO stanza VALUES('T152','2','Di-mabigkas kay dakila,<br/>Pag-ibig Mo''y nagawa!<br/>Sa akin Ka nakiisa<br/>Kay dakilang himala.<br/>Ibinigay Sarili Mo<br/>Upang maging tustos ko;<br/>Tuwing Kita matamasa''y<br/>Ikaw ang Siyang mabuhay.<br/>',NULL,39717,2);
INSERT INTO stanza VALUES('T152','3','Hinayag ng pag-ibig Mo<br/>Ang pagka-Diyos Mong buo,<br/>Buhay makahulugan na,<br/>Sa Iyong plano''y natugma.<br/>Sumasapit bawa''t araw<br/>Ang biyaya ng buhay;<br/>Ako''y tangi Mong adhika,<br/>Katamisan Mo''y t''wina.<br/>',NULL,39718,3);
INSERT INTO stanza VALUES('T152','4','Di mawalay Ka sa akin,<br/>Ako''y Iyong mamahalin,<br/>Pag-ibig walang-kapantay,<br/>Kata''y pinag-uugnay!<br/>Lagi tayong pag-isahin;<br/>Ako''y Iyo, Ikaw akin!<br/>Patotoong sasambitin:<br/>Pag-ibig Mo''y buklurin.<br/>',NULL,39719,4);
INSERT INTO stanza VALUES('T153','1','Kay dakila — pag-ibig Mo,<br/>Hesus, ganap ito!<br/>Aming isip, buhay, puso,<br/>Ay natuon sa Iyo!<br/>',NULL,39720,1);
INSERT INTO stanza VALUES('T153','2','Sarili Mong mahalaga,<br/>Minahal, nakita;<br/>Maging Iyong krus ng pagdusta,<br/>Tiniis Mo''ng dusa.<br/>',NULL,39721,2);
INSERT INTO stanza VALUES('T153','3','Sa sakdal na pagsinta Mo,<br/>Walang makatalo;<br/>Para sa Iyong kaibigan,<br/>Suong kamatayan!<br/>',NULL,39722,3);
INSERT INTO stanza VALUES('T153','4','Ika''y nasa anyo ng Diyos,<br/>Nasa l''walhati rin;<br/>Nguni''t sa pighati''y lipos,<br/>Sa anyong alipin.<br/>',NULL,39723,4);
INSERT INTO stanza VALUES('T153','5','Ika''y tumulad sa tao,<br/>Nguni''t walang sala,<br/>Nang kami''y makawangis Mo,<br/>Ganap matransporma.<br/>',NULL,39724,5);
INSERT INTO stanza VALUES('T153','6','Maamo Ka at malakas,<br/>Tutularan Kita;<br/>L''walhati''y lalong tataas,<br/>Hanggang magpangita.<br/>',NULL,39725,6);
INSERT INTO stanza VALUES('T153','7','Pag-ibig Mo''y mahalaga<br/>Sa ''ming isip, puso;<br/>At samyo ng I-yong ngalan<br/>Ay patutunayan.<br/>',NULL,39726,7);
INSERT INTO stanza VALUES('T154','1','Pag-ibig Mo''y hindi ko malirip,<br/>Nguni''t, Panginoon, aking isip,<br/>Ang luwang, haba nais malaman,<br/>Taas, lalim nito''t kalakasan<br/>Nang lubusan.<br/>',NULL,39727,1);
INSERT INTO stanza VALUES('T154','2','Pag-ibig Mo''y higit sa masaysay,<br/>Panginoon, ang labi kong taglay,<br/>Magpapahayag ng Iyong pag-ibig<br/>Sa makasalanang may tigatig<br/>Iyong sinagip.<br/>',NULL,39728,2);
INSERT INTO stanza VALUES('T154','3','Pag-ibig Mo''y higit sa mapuri,<br/>Panginoon, ang puso ko''y tangi,<br/>Aawit sa puspos Mong pag-ibig,<br/>Tulad kong salarin ay naantig<br/>Tungo sa Diyos.<br/>',NULL,39729,3);
INSERT INTO stanza VALUES('T154','4','Pag-ibig Mo — kahit di-masukat,<br/>Di-mabigkas, mapuri nang sapat,<br/>Hungkag na puso''y dadalhin sa Iyo,<br/>O batis na buháy, pag-ibig Mo,<br/>Pun''in ako.<br/>',NULL,39730,4);
INSERT INTO stanza VALUES('T154','5','Ako''y isang hungkag na sisidlan,<br/>Kainlanma''y di Kita hinangaan,<br/>Sa Iyo muli''t muling makalapit,<br/>Habag, biyaya''y aking makamit,<br/>Inibig Mo.<br/>',NULL,39731,5);
INSERT INTO stanza VALUES('T154','6','Ako''y punuin ng pag-ibig Mo,<br/>Sa ilog na buháy dalhin ako,<br/>Payak akong nanampalataya,<br/>Hindi ako lalapit sa iba,<br/>Kundi sa Iyo.<br/>',NULL,39732,6);
INSERT INTO stanza VALUES('T154','7','At sa luklukan Mo, Panginoon,<br/>Ang Iyong mukha''y makita ko roon,<br/>Ang luwang, haba ng pag-ibig Mo,<br/>Ang taas, lalim at lakas nito,<br/>''Awitin ko.<br/>',NULL,39733,7);
INSERT INTO stanza VALUES('T155','1','Nang Kristo''y natalian,<br/>Ako''y may kalayaan;<br/>Akong galá hinanap;<br/>Dilim naging liwanag.<br/>',NULL,39734,1);
INSERT INTO stanza VALUES('T155','2','Pagsinta ba ng ina<br/>Sa anak maiwala?<br/>Lumimot man siya wari,<br/>Diyos nama''y hinding-hindi.<br/>',NULL,39735,2);
INSERT INTO stanza VALUES('T155','3','Di nagbagong pag-ibig,<br/>Taas higit sa langit;<br/>Lalim higit sa dagat,<br/>May laya''t lakas, tapat.<br/>',NULL,39736,3);
INSERT INTO stanza VALUES('T155','4','Kapag gawang biyaya,<br/>Lubusang maganap na;<br/>L''walhati''y makikita,<br/>Tanda ng pag-ibig Niya.<br/>',NULL,39737,4);
INSERT INTO stanza VALUES('T155','5','Tangi kong karaingan,<br/>Pag-ibig sa Iyo''y kulang;<br/>Subali''t mahal Kita,<br/>Nawa''y mapahigit pa.<br/>',NULL,39738,5);
INSERT INTO stanza VALUES('T156','1','Pag-ibig ng Kaibigan ko<br/>Sa aki''y higit sa lahat,<br/>Taas higit pa sa bundok,<br/>Ang lalim higit sa dagat.<br/>Tunay, tapat, taimtim Siya;<br/>Bago pa mundo''y nilikha<br/>Purihin — ''ko''y minahal na!<br/>',NULL,39739,1);
INSERT INTO stanza VALUES('T156','2','Sa kataas-taasan Siya,<br/>Hukbong anghel sumasamba,<br/>Dahil sa Kanyang pagsinta,<br/>Iniwan ang luklukan Niya;<br/>Hinanap Niya ang nawala,<br/>''Tinakwil lahat, nagdusa,<br/>Purihin — ''ko''y hinanap Niya.<br/>',NULL,39740,2);
INSERT INTO stanza VALUES('T156','3','Sa daan Siya''y nag-iisa,<br/>Walang kasama''t alalay,<br/>Ang pighati at lungkot Niya,<br/>Siya at Diyos tanging may malay.<br/>Walang hinto Siyang tumungo<br/>Sa abang kalagayan ko,<br/>Purihin — nakita Niya ''ko.<br/>',NULL,39741,3);
INSERT INTO stanza VALUES('T156','4','Dumating ang trahedya nga,<br/>Nang ipinagkanulo Siya,<br/>Tinik ang nasa ulo Niya,<br/>Nilatigo at dinusta,<br/>Sa halip ko, Siya''y nagdugo<br/>At namatay sa Kalbaryo,<br/>Purihin — tinubos Niya ''ko.<br/>',NULL,39742,4);
INSERT INTO stanza VALUES('T156','5','Habang buhay ko''y awitin,<br/>Pag-ibig Niya kay hiwaga,<br/>Sa piling Niya ako''y dalhin,<br/>Manahan sa harapan Niya;<br/>Ang mukha Niya ay makita,<br/>Ako''y pupuri''t sasamba,<br/>Purihin — mahal ko rin Siya.<br/>',NULL,39743,5);
INSERT INTO stanza VALUES('T157','1','Kami ba''y kai-sa Mo, Hesus?<br/>Pag-ibig Mo''y lubos!<br/>Sa Kalbaryo''y kapiling Ka,<br/>Sa langit kaisa.<br/>',NULL,39744,1);
INSERT INTO stanza VALUES('T157','2','Para sa ''min, Iyong biyaya,<br/>Sa langit buhat Ka;<br/>Sa dugo''t laman at dusa,<br/>Nakipag-isa Ka.<br/>',NULL,39745,2);
INSERT INTO stanza VALUES('T157','3','Aming sala''y pinasan Mo,<br/>Pag-ibig dibino.<br/>Nang kami''y mapalaya Mo,<br/>Sumpa''t poot ay Iyo.<br/>',NULL,39746,3);
INSERT INTO stanza VALUES('T157','4','Luwalhati''y umakyat na,<br/>Ulo ng Ekklesia.<br/>Lalim o taas o buhay,<br/>Di sa Iyo mawalay.<br/>',NULL,39747,4);
INSERT INTO stanza VALUES('T157','5','Tur''ang kilanlin, angkinin,<br/>Hiwagang malalim.<br/>Sa langit kai-sa Ka namin,<br/>Kami kai-sa Mo rin.<br/>',NULL,39748,5);
INSERT INTO stanza VALUES('T157','6','Sa trono luluklok kami,<br/>Araw mal''walhati.<br/>Mundo''y manghang makikita<br/>Tayo''y magkai-sa nga!<br/>',NULL,39749,6);
INSERT INTO stanza VALUES('T158','1','Hinanap ng Iyong pagsinta,<br/>Kaming pagala-gala;<br/>Iyong niyakap sa bisig Mo,<br/>Nagdusa Ka''t nagdugo;<br/>Aawit, kalul''wa ko:<br/>''Binigay Sarili Mo.<br/>',NULL,39750,1);
INSERT INTO stanza VALUES('T158','2','Sa halamanan marinig,<br/>Mapait na pagtangis.<br/>Panginoo''y nagpupuyat<br/>Habang tulog alagad.<br/>Kalul''wa ko mahal Niya,<br/>''Binigay Sarili Niya.<br/>',NULL,39751,2);
INSERT INTO stanza VALUES('T158','3','Sa Ama Siya''y nagsalita,<br/>Tinikman sarong dusa;<br/>Dahil sa ''tin ininom Niya<br/>Tinanggap Niya nang kusa.<br/>Kalul''wa, anong sinta,<br/>''Binigay Sarili Niya.<br/>',NULL,39752,3);
INSERT INTO stanza VALUES('T158','4','Patapos na tagpong hapis:<br/>Poot ng Diyos ay labis.<br/>Sa krus pinataw sa Kanya,<br/>Maligtas ''king kalul''wa.<br/>Pag-ibig di-masayod,<br/>Sa akin inihandog.<br/>',NULL,39753,4);
INSERT INTO stanza VALUES('T158','5','Alingawngaw sa Kalbaryo,<br/>Habang sa krus napako;<br/>Ang sumunod sa layon Mo,<br/>Iyong ''tinakwil, O Diyos ko.<br/>Kalul''wa''y para sa Iyo,<br/>Naghandog ang Poon ko.<br/>',NULL,39754,5);
INSERT INTO stanza VALUES('T158','6','Lumipas na pagdusa Mo,<br/>May galak aming puso.<br/>Umakyat Ka sa luklukan<br/>Wala nang kamatayan<br/>Para sa Iyo, kalul''wa,<br/>''Binigay Sarili Niya.<br/>',NULL,39755,6);
INSERT INTO stanza VALUES('T158','7','Mahal Ka, sinasamba Ka,<br/>Biyaya Mo''y kay yaman.<br/>Magkikita nang mukhaan,<br/>Sakdal na kagalakan!<br/>Ngayon awit ay ito:<br/>''Binigay Sarili Mo.<br/>',NULL,39756,7);
INSERT INTO stanza VALUES('T159','1','Linawin Manunubos,<br/>Pag-ibig sa ''king lubos;<br/>Sa lupa, Ika''y naparito<br/>Patungong Kalbaryo.<br/>',NULL,39757,1);
INSERT INTO stanza VALUES('T159','chorus','Ipaunawa sa ''kin<br/>Tulungang tanggapin;<br/>O Diyos Banal, halaga sa Iyo.<br/>Pasanin sala ko.<br/>',NULL,39758,2);
INSERT INTO stanza VALUES('T159','2','Pako ba Manunubos,<br/>Sa puno''ng gumapos?<br/>Hindi, kundi Iyong pag-ibig,<br/>Ito''y aking batid.<br/>',NULL,39759,3);
INSERT INTO stanza VALUES('T159','chorus','Ipaunawa sa ''kin<br/>Tulungang tanggapin;<br/>O Diyos Banal, halaga sa Iyo.<br/>Pasanin sala ko.<br/>',NULL,39760,4);
INSERT INTO stanza VALUES('T159','3','O, kamangha-mangha nga,<br/>Lihim, hayag na sala,<br/>Dahil sa Kanyang kamatayan,<br/>May kapatawaran.<br/>',NULL,39761,5);
INSERT INTO stanza VALUES('T159','chorus','Ipaunawa sa ''kin<br/>Tulungang tanggapin;<br/>O Diyos Banal, halaga sa Iyo.<br/>Pasanin sala ko.<br/>',NULL,39762,6);
INSERT INTO stanza VALUES('T159','4','Puso ko''y Iyong tunawin,<br/>Ako''y ''yuko''t baliin.<br/>Nang Ika''y maging Panginoon,<br/>Hari''t aking putong.<br/>',NULL,39763,7);
INSERT INTO stanza VALUES('T159','chorus','Ipaunawa sa ''kin<br/>Tulungang tanggapin;<br/>O Diyos Banal, halaga sa Iyo.<br/>Pasanin sala ko.<br/>',NULL,39764,8);
INSERT INTO stanza VALUES('T160','1','L''walhati, Hari ng buhay,<br/>Sa Iyo iaalay,<br/>Nang di Kita malimutan,<br/>Kalbaryo''y puntahan.<br/>',NULL,39765,1);
INSERT INTO stanza VALUES('T160','chorus','Di-malimot Getsemani;<br/>Di-malimot Iyong pighati;<br/>Di-malimot pag-ibig Mo,<br/>Dahil sa Kalbaryo.<br/>',NULL,39766,2);
INSERT INTO stanza VALUES('T160','2','Makita ko ang libingan<br/>Na pinagtangisan;<br/>Mga anghel ang nagbantay,<br/>Nang Ika''y humimlay.<br/>',NULL,39767,3);
INSERT INTO stanza VALUES('T160','3','Doon ako mag-aalay,<br/>Tulad ni Maria,<br/>Ituro Mo ang libingan,<br/>Aking mapuntahan.<br/>',NULL,39768,5);
INSERT INTO stanza VALUES('T160','4','Nawa''y kusang pasanin ko<br/>Ang krus para sa Iyo,<br/>Kahit ang hapis Mong saro,<br/>Ay mabahagi ko.<br/>',NULL,39769,7);
INSERT INTO stanza VALUES('T160','5','Nais Mong higit pang tao<br/>Ang maakit sa Iyo;<br/>Linisin Mo aking labi,<br/>Kalbaryo''y masabi.<br/>',NULL,39770,9);
INSERT INTO stanza VALUES('T161','1','Manliligtas ay purihin!<br/>Lubha ang nagawa sa ''tin;<br/>Ihandog lahat sa Kanya,<br/>Nang may ligaya.<br/>',NULL,39771,1);
INSERT INTO stanza VALUES('T161','2','Ngalang Hesus bumighani<br/>Sa gusot lakas, baluti;<br/>Ika''y pagkatiwalaan,<br/>''Di na masaktan.<br/>',NULL,39772,2);
INSERT INTO stanza VALUES('T161','3','Sa Kanya''y manalig banal,<br/>Walang pagbabago''t tapat;<br/>Walang p''wersang maghiwalay<br/>Sa Kanyang Mahal.<br/>',NULL,39773,3);
INSERT INTO stanza VALUES('T161','4','Kami''y tanganan, O Poon,<br/>Sampalataya''y lumaon,<br/>Hanggang sa ikakasal na<br/>Babaeng sinta.<br/>',NULL,39774,4);
INSERT INTO stanza VALUES('T161','5','Pagkatapos kalalagyan<br/>Nami''y Iyong pinaghandaan;<br/>Bagay na ngayo''y wala pa,<br/>Maging amin na.<br/>',NULL,39775,5);
INSERT INTO stanza VALUES('T162','1','Papuri, pasalamat, banal, laksan!<br/>Sa presensya ni Hesus bagong awitan.<br/>',NULL,39776,1);
INSERT INTO stanza VALUES('T162','chorus','Siyang umibig sa ''min sa sala''y naghugas,<br/>L''walhati''y Kanya magpahanggang sa wakas!<br/>',NULL,39777,2);
INSERT INTO stanza VALUES('T162','2','Dati sa tingin Niya''y makasalanan,<br/>Ngayon suot dalisay, Siya''y papurihan.<br/>',NULL,39778,3);
INSERT INTO stanza VALUES('T162','chorus','Siyang umibig sa ''min sa sala''y naghugas,<br/>L''walhati''y Kanya magpahanggang sa wakas!<br/>',NULL,39779,4);
INSERT INTO stanza VALUES('T162','3','Sutil ginawang saserdote''t hari,<br/>Tinubos tinuruan ng bagong awit.<br/>',NULL,39780,5);
INSERT INTO stanza VALUES('T162','chorus','Siyang umibig sa ''min sa sala''y naghugas,<br/>L''walhati''y Kanya magpahanggang sa wakas!<br/>',NULL,39781,6);
INSERT INTO stanza VALUES('T162','4','Manatili sa kawalang pag-asa<br/>Kundi Niya minahal, nilinis sa sala.<br/>',NULL,39782,7);
INSERT INTO stanza VALUES('T162','chorus','Siyang umibig sa ''min sa sala''y naghugas,<br/>L''walhati''y Kanya magpahanggang sa wakas!<br/>',NULL,39783,8);
INSERT INTO stanza VALUES('T162','5','Laksan ang ating tinig Siya''y purihin!<br/>Nang iba''y manalig, kanta''y aawitin.<br/>',NULL,39784,9);
INSERT INTO stanza VALUES('T162','chorus','Siyang umibig sa ''min sa sala''y naghugas,<br/>L''walhati''y Kanya magpahanggang sa wakas!<br/>',NULL,39785,10);
INSERT INTO stanza VALUES('T163','1','Kung may isang libong dila,<br/>Hesus pupurihin,<br/>Kay yaman ng biyaya Niya<br/>At mal''walhati rin.<br/>',NULL,39786,1);
INSERT INTO stanza VALUES('T163','2','Poong Diyos mapagbiyaya,<br/>Maghayag tulungan,<br/>Ang dangal ng Iyong pangalan,<br/>Sa sangkalupaan.<br/>',NULL,39787,2);
INSERT INTO stanza VALUES('T163','3','Aliw ko ang ngalang Hesus,<br/>Nagtaboy ng kaba;<br/>Buhay ay pahinga ko Diyos,<br/>Naging aking kanta.<br/>',NULL,39788,3);
INSERT INTO stanza VALUES('T163','4','Nabihag ng pag-ibig Niya,<br/>Maging alipin nga,<br/>Siya ay namatay, nagdusa,<br/>Ako''y napalaya.<br/>',NULL,39789,4);
INSERT INTO stanza VALUES('T163','5','Winasak lakas ng sala,<br/>Ako''y pinalaya;<br/>Dugo''y nilinis masama,<br/>Sa akin tulong nga.<br/>',NULL,39790,5);
INSERT INTO stanza VALUES('T163','6','Ngalan Mo kaibig-ibig,<br/>Kalooban angkin.<br/>Kung may isang libong puso,<br/>Bawa''t isa sa Iyo!<br/>',NULL,39791,6);
INSERT INTO stanza VALUES('T164','1','Dahil sa gloria, ako''y aawit,<br/>Sinag sa ''king puso''y gumuhit;<br/>Purihin Ka, sala''y pinatawad—<br/>Sa pag-ibig Mong laging tapat.<br/>',NULL,39792,1);
INSERT INTO stanza VALUES('T164','2','Kung gawa Mo sa Iyo nagpupuri,<br/>Araw sumisilay ng puri;<br/>Kung hangin humahaging sa gubat<br/>Bawa''t puno aaliw-iw nga.<br/>',NULL,39793,2);
INSERT INTO stanza VALUES('T164','3','Sa gayon mga labi ko''y dapat<br/>Magbigkas ng papuring sapat;<br/>Maaari bang kalikasan lang<br/>At wala sa ''kin ang awitan?<br/>',NULL,39794,3);
INSERT INTO stanza VALUES('T164','4','O mal''walhati kong Manunubos<br/>Sasambahin Kita aking Diyos;<br/>Galak sa gitna ng puring lipos<br/>Awit ko''y marinig nang taos.<br/>',NULL,39795,4);
INSERT INTO stanza VALUES('T165','1','Awit ko ay si Hesus,<br/>Awa sa ''kin puspos;<br/>Pinaawit puso ko,<br/>Pinuno saro ko.<br/>Si Hesus ang awit ko<br/>Mahal na Kordero,<br/>Kanyang tinubos ako<br/>Binili ng dugo.<br/>',NULL,39796,1);
INSERT INTO stanza VALUES('T165','2','Si Hesus ang awit ko<br/>Habang nakaupo;<br/>Gunita''y kabutihan,<br/>Muni''y katamisan.<br/>Hesus aking awitin,<br/>Anumang dumating;<br/>Awit ko''y biyaya Niya,<br/>Nagligtas, kalinga.<br/>',NULL,39797,2);
INSERT INTO stanza VALUES('T165','3','Si Hesus ang awit ko,<br/>Habang tumatakbo;<br/>Maabot kaharian<br/>Araw kasakdalan,<br/>Pagpasok ng kalul''wa<br/>Sa loob ng gloria;<br/>Hesus puri''y awitan<br/>Nang magpakailanman.<br/>',NULL,39798,3);
INSERT INTO stanza VALUES('T166','1','Puri''y sa Panginoong Hari ng sangnilalang!<br/>Purihin Siya, aking kalusugan, kaligtasan<br/>Nakarinig<br/>Lalapit nga sa templo,<br/>At aawit ngayon sa Iyo.<br/>',NULL,39799,1);
INSERT INTO stanza VALUES('T166','2','Puri''y sa Panginoong namumuno sa lahat,<br/>Gaya''y pakpak-agilang nagtaas, nagpalakas<br/>Iyong pagmasdan,<br/>Iyong mga kanaisan,<br/>Sa lahat ika''y nabigyan!<br/>',NULL,39800,2);
INSERT INTO stanza VALUES('T166','3','Puri''y sa Poon nilikha kang kahanga-hanga!<br/>Binigyang kahusayan, kaligtasa''y ''tinakda,<br/>Anong dusa<br/>Ang hindi Niya binatá?<br/>Nilukuban ka ng awa.<br/>',NULL,39801,3);
INSERT INTO stanza VALUES('T166','4','Purihin ang Poon nagpaunlad sa iyong gawa,<br/>Pinagtanggol ka''t mula langit padala''y awa,<br/>Munihin pa<br/>Sa kapangyarihan Niya,<br/>Pag-ibig kinai-bigan ka.<br/>',NULL,39802,4);
INSERT INTO stanza VALUES('T166','5','Puri''y sa Poon! Aking lahat dapat sumamba!<br/>May buhay, may hininga, halina''t purihin Siya.<br/>Amen! Amen!<br/>Amen bigkasing muli,<br/>Sambahin Kang may pagbunyi.<br/>',NULL,39803,5);
INSERT INTO stanza VALUES('T167','1','Panginoon kay buti Mo<br/>Tapat at di-nagbabago;<br/>Dakila ang pag-ibig Mo<br/>Walang sukat, walang dulo.<br/>',NULL,39804,1);
INSERT INTO stanza VALUES('T167','2','Si Hesus simula''t wakas,<br/>Gabay sa trono ng gloria;<br/>Purihin Siya sa lumipas,<br/>Sa hinaharap, tiwala.<br/>',NULL,39805,2);
INSERT INTO stanza VALUES('T168','1','Papuring may pasalamat,<br/>Poon sa Iyo awitin ko;<br/>Kasamang banal ''pahayag,<br/>Manliligtas gawa''y ganap.<br/>',NULL,39806,1);
INSERT INTO stanza VALUES('T168','chorus','At awit paiilanlang,<br/>Ito ay paiilanlang,<br/>Na Tagapagligtas ko nga<br/>Mainam lahat ang gawa!<br/>',NULL,39807,2);
INSERT INTO stanza VALUES('T168','2','Kamangha-mangha''t malaya,<br/>Pag-ibig sa ''king maysala;<br/>Ligtas sa apoy ng hirap;<br/>Manliligtas gawa''y ganap.<br/>',NULL,39808,3);
INSERT INTO stanza VALUES('T168','chorus','At awit paiilanlang,<br/>Ito ay paiilanlang,<br/>Na Tagapagligtas ko nga<br/>Mainam lahat ang gawa!<br/>',NULL,39809,4);
INSERT INTO stanza VALUES('T168','3','Nang mabatid pag-ibig Niya,<br/>Napatunayan habag Niya,<br/>Papuring higit sa habag,<br/>Manliligtas gawa''y ganap.<br/>',NULL,39810,5);
INSERT INTO stanza VALUES('T168','chorus','At awit paiilanlang,<br/>Ito ay paiilanlang,<br/>Na Tagapagligtas ko nga<br/>Mainam lahat ang gawa!<br/>',NULL,39811,6);
INSERT INTO stanza VALUES('T168','4','Sa araw na pailanlang<br/>Kasama sa pag-awitan,<br/>Itong himig maitanyag,<br/>Manliligtas gawa''y ganap.<br/>',NULL,39812,7);
INSERT INTO stanza VALUES('T168','chorus','At awit paiilanlang,<br/>Ito ay paiilanlang,<br/>Na Tagapagligtas ko nga<br/>Mainam lahat ang gawa!<br/>',NULL,39813,8);
INSERT INTO stanza VALUES('T169','1','Panginoon kong sinta,<br/>Mahal, hirang ng Diyos!<br/>Langis ng kagalakan,<br/>Ipinahid ng Diyos.<br/>',NULL,39814,1);
INSERT INTO stanza VALUES('T169','chorus','Aming hinahangaan<br/>Ang Iyong kagandahan,<br/>Tamis Mo''t kabanguhan<br/>At Iyong karilagan.<br/>',NULL,39815,2);
INSERT INTO stanza VALUES('T169','2','Higit na marilag Ka<br/>At kaibig-ibig;<br/>Bibig Mo''y mabiyaya,<br/>Puso ko''y umibig.<br/>',NULL,39816,3);
INSERT INTO stanza VALUES('T169','3','Mahal Ka sa pagsilang,<br/>Pantas ay nag-alay;<br/>Mahal sa kamatayan,<br/>Dakila''y nagpugay.<br/>',NULL,39817,5);
INSERT INTO stanza VALUES('T169','4','Ulo Mo''y pinahiran,<br/>Kamahal-mahalan;<br/>Paa Mo''y pinahiran,<br/>Mahal Kang lubusan.<br/>',NULL,39818,7);
INSERT INTO stanza VALUES('T169','5','Kamatayan Mo''y mira,<br/>Pang-alo sa tao;<br/>Pagkabuhay espesia,<br/>Sa Diyos yaring samyo.<br/>',NULL,39819,9);
INSERT INTO stanza VALUES('T169','6','Katulad ng alhena,<br/>Lipos ang Iyong ganda;<br/>Puno ng mansanas Ka,<br/>Sagana sa bunga.<br/>',NULL,39820,11);
INSERT INTO stanza VALUES('T169','7','Mainam kaysa alak<br/>Ang pagmamahal Mo;<br/>Unggwentong halimuyak,<br/>Taglay ng ngalan Mo.<br/>',NULL,39821,13);
INSERT INTO stanza VALUES('T169','8','Pagbakas sa Iyong ganda<br/>At iniisip Ka,<br/>Natikman katamisan,<br/>Yakap Mo''y pahinga.<br/>',NULL,39822,15);
INSERT INTO stanza VALUES('T170','1','Panginoon Nobyong ibig,<br/>Hirang ng Diyos, sa amin;<br/>Ganda Mo''y kaakit-akit,<br/>Sa puso ay marikit.<br/>',NULL,39823,1);
INSERT INTO stanza VALUES('T170','2','Amin Kang hinahangaan,<br/>Sa Iyong kahalagahan,<br/>Kay lalim ng pag-ibig Mo,<br/>Higit sa natatanto.<br/>',NULL,39824,2);
INSERT INTO stanza VALUES('T170','3','Ang kagandaha''t tamis Mo<br/>Sa lahat Ika''y lalo;<br/>Mapagmahal at maamo,<br/>Walang mahambing sa Iyo.<br/>',NULL,39825,3);
INSERT INTO stanza VALUES('T170','4','Damit Mo''y lipos ng mira,<br/>Bibig Mo''y mabiyaya,<br/>Sa samyo ng pagdurusa,<br/>Pag-ibig Mo''y nadama.<br/>',NULL,39826,4);
INSERT INTO stanza VALUES('T170','5','Sa langis ng kagalakan<br/>Ikaw ay pinahiran;<br/>At sa mga kapulungan<br/>Ikaw ay parangalan.<br/>',NULL,39827,5);
INSERT INTO stanza VALUES('T170','6','Ika''y pinagpala ng Diyos,<br/>Nagtagumpay Kang lubos;<br/>Nakaluklok, pinutungan,<br/>Sa Iyo ang kamahalan.<br/>',NULL,39828,6);
INSERT INTO stanza VALUES('T170','7','Nasà Ka ng mga bansa,<br/>Talos ang Iyong halaga;<br/>Higit Ka sa laksa-laksa,<br/>Dapat Ka sa pagsamba.<br/>',NULL,39829,7);
INSERT INTO stanza VALUES('T171','1','Hesus, tamis nadarama,<br/>T''wing maisip Kita;<br/>Nana''bik sa Iyong presensya,<br/>At maiakyat na!<br/>',NULL,39830,1);
INSERT INTO stanza VALUES('T171','chorus','Tulad Kang †bulaklak alhena,<br/>Sa ubasan ng En-gadi,<br/>Ganda Mo''y kahanga-hanga,<br/>Ika''y bukod-tangi.<br/>',NULL,39831,2);
INSERT INTO stanza VALUES('T171','2','Walang sapat na awitin<br/>Biyaya''y mapuri,<br/>Ni puso''y di-matamasa<br/>Lahat Mong pag-ibig.<br/>',NULL,39832,3);
INSERT INTO stanza VALUES('T171','chorus','Tulad Kang bulaklak alhena,<br/>Sa ubasan ng En-gadi,<br/>Ganda Mo''y kahanga-hanga,<br/>Ika''y bukod-tangi.<br/>',NULL,39833,4);
INSERT INTO stanza VALUES('T171','3','Nguni''t ang nakalulugod<br/>Di pag-ibig, b''yaya;<br/>Kundi Ikaw tanging-bukod<br/>Ang ikasisiya.<br/>',NULL,39834,5);
INSERT INTO stanza VALUES('T171','chorus','Tulad Kang bulaklak alhena,<br/>Sa ubasan ng En-gadi,<br/>Ganda Mo''y kahanga-hanga,<br/>Ika''y bukod-tangi.<br/>',NULL,39835,6);
INSERT INTO stanza VALUES('T171','4','Walang kapantay Iyong ganda<br/>Ni Iyong katamisan;<br/>Sa langit wala nang iba,<br/>Wala sa lupa man.<br/>',NULL,39836,7);
INSERT INTO stanza VALUES('T171','chorus','Tulad Kang bulaklak alhena,<br/>Sa ubasan ng En-gadi,<br/>Ganda Mo''y kahanga-hanga,<br/>Ika''y bukod-tangi.<br/>',NULL,39837,8);
INSERT INTO stanza VALUES('T172','1','Di Kita lubos malanghap,<br/>Simoy ng pag-ibig;<br/>Anong bangong halimuyak!<br/>Ika''y †Alhenang bulaklak,<br/>Lunas makalangit,<br/>Lunas makalangit.<br/>',NULL,39838,1);
INSERT INTO stanza VALUES('T172','2','Di kita lubos matingnan,<br/>Anong karilagan!<br/>Puso ko napaligaya,<br/>Nang namasdan sa Iyong mukha,<br/>Ang Iyong kagandahan,<br/>Ang Iyong kagandahan.<br/>',NULL,39839,2);
INSERT INTO stanza VALUES('T172','3','Di Kita mapaglingkuran,<br/>Hesus, nang lubusan!<br/>Hindi ko nais lumaya,<br/>Kundi paglingkuran Kita,<br/>Hanggang katapusan,<br/>Hanggang katapusan.<br/>',NULL,39840,3);
INSERT INTO stanza VALUES('T172','4','Di Kita lubos maawit,<br/>Pangalang kay tamis,<br/>Isang himig na malambing,<br/>Sa puso ko nanggagaling,<br/>Ang ligayang labis,<br/>Ang ligayang labis.<br/>',NULL,39841,4);
INSERT INTO stanza VALUES('T172','5','Di Kita lubos masambit,<br/>Magiliw Kang labis,<br/>Ang puso Mo''y pumipintig,<br/>Ako sa Iyo''y napalapit,<br/>Kay inam! kay tamis!<br/>Kay inam! kay tamis!<br/>',NULL,39842,5);
INSERT INTO stanza VALUES('T175','1','Hesus, karilagan,<br/>Hari ng kalikasan;<br/>Anak ng Diyos, at ng tao,<br/>Ika''y minamahal,<br/>Ika''y dinarangal,<br/>Ika''y l''walhati''t putong ko.<br/>',NULL,39843,1);
INSERT INTO stanza VALUES('T175','2','Parang luntian,<br/>Gandang kakahuyan,<br/>Tagsibol, Ika''y dinamtan,<br/>Higit Kang marilag,<br/>Higit Kang dalisay,<br/>Pusong hapis nag-awitan.<br/>',NULL,39844,2);
INSERT INTO stanza VALUES('T175','3','Sikat ng araw<br/>Buwang tumatanglaw<br/>Bituin ay maganda man,<br/>Hesus kay ningning<br/>At busilak din,<br/>Sa lahat sa kalangitan!<br/>',NULL,39845,3);
INSERT INTO stanza VALUES('T175','4','Sa langit, lupa<br/>Pinakamaganda,<br/>Nasumpungan sa Iyo, Hesus.<br/>Wala nang iba,<br/>Kay lapit, mahal<br/>Sa Manliligtas kong Hesus!<br/>',NULL,39846,4);
INSERT INTO stanza VALUES('T176','1','Hesus Manliligtas<br/>Kristong Hari nga;<br/>Mga anghel, tao,<br/>Sumamba sa Iyo.<br/>Kanilang pahayag,<br/>Ika''y marilag;<br/>Sa himnong pag-ibig,<br/>Ika''y marikit!<br/>',NULL,39847,1);
INSERT INTO stanza VALUES('T176','2','Panlupang aliwan,<br/>Ay kahungkagan.<br/>Langit kung wala Ka,<br/>Pawang dilim nga.<br/>O Kordero ng Diyos!<br/>Ang Iyong l''walhati<br/>Liwanag sa langit<br/>Buhay pag-ibig.<br/>',NULL,39848,2);
INSERT INTO stanza VALUES('T176','3','Sa Iyo mahiwalay,<br/>Wala nang buhay;<br/>Buhay masagana,<br/>Sa Iyong presensya.<br/>Tao''t sangnilikha,<br/>Ikaw lumikha;<br/>Nguni''t nagpababa<br/>Ang Manlilikha!<br/>',NULL,39849,3);
INSERT INTO stanza VALUES('T176','4','Lahat kasakdalan,<br/>Nasa Iyo, Hesus;<br/>Sinag ng gloria Niya,<br/>Ikaw ngang lubos.<br/>Mukha Mo''y makita,<br/>Anong biyaya!<br/>Nawa''y maranasan,<br/>''Tong kagalakan.<br/>',NULL,39850,4);
INSERT INTO stanza VALUES('T177','1','Kay tamis Iyong kamahalaan<br/>Sa Iyo''y dumakila;<br/>Putong maningning na gloria,<br/>Labing mabiyaya.<br/>',NULL,39851,1);
INSERT INTO stanza VALUES('T177','2','Di maihambing sa Kanya,<br/>Taong nasa lupa;<br/>Hukbong anghel nasa langit<br/>Hindi rin hihigit.<br/>',NULL,39852,2);
INSERT INTO stanza VALUES('T177','3','Utang ko buhay, hininga,<br/>Ligaya sa Kanya;<br/>Pandaig sa kamatayan,<br/>Maging sa libingan.<br/>',NULL,39853,3);
INSERT INTO stanza VALUES('T177','4','Sa Diyos Ama, tahanan ko,<br/>Ako''y dinala Mo;<br/>Gloria ng Diyos ''pinakita,<br/>Ganap aking saya.<br/>',NULL,39854,4);
INSERT INTO stanza VALUES('T177','5','Sa biyaya Niya nabatid,<br/>Dakilang pag-ibig;<br/>Kung may isanlibong puso,<br/>Lahat pawang sa Iyo!<br/>',NULL,39855,5);
INSERT INTO stanza VALUES('T178','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39856,1);
INSERT INTO stanza VALUES('T178','1','Saan sisimulan namin,<br/>Iyong pagpapala''y banggitin?<br/>''Di na alipin ng sala,<br/>Sa kamatayan lumaya.<br/>Paano Kang sasambahin,<br/>Papurihan ng awitin?<br/>',NULL,39857,2);
INSERT INTO stanza VALUES('T178','2','Binigay kapayapaan,<br/>Papaanong bibitiwan?<br/>Sa kapahamakan noon<br/>Anak ng Diyos, ligtas ngayon!<br/>Lahat kong sala''y hugas na,<br/>Tamasa ay pagpapala.<br/>',NULL,39858,3);
INSERT INTO stanza VALUES('T178','3','Pusong napuno ng Kristo,<br/>Sabik na ibadya ito!<br/>Sa pag-awit dakilain<br/>Siyang di-mapigil purihin.<br/>Daliang awitan natin,<br/>Hari ay luwalhatiin.<br/>',NULL,39859,4);
INSERT INTO stanza VALUES('T178','4','Higit sa tanang may buhay,<br/>Sa karilagan Iyong taglay;<br/>Mga pagsinta at biyaya,<br/>Bagama''t Ika''y nagdusa.<br/>Diyos na dapat papurihan,<br/>Sa Iyo lahat kapuspusan.<br/>',NULL,39860,5);
INSERT INTO stanza VALUES('T179','1','Kay Kristo l''walhati,<br/>Langit puspos puri;<br/>Purihin Siya!<br/>Pag-ibig, biyaya<br/>Pinawi ang dusa;<br/>Karapat-dapat Siya<br/>Ang Kordero!<br/>',NULL,39861,1);
INSERT INTO stanza VALUES('T179','2','Naligtas parito,<br/>Sumamba sa trono,<br/>Purihin Siya!<br/>Dugo Niyang nagtubos,<br/>Kasundo na ang Diyos<br/>Ngalan Niya''y ibando;<br/>Ang Kordero!<br/>',NULL,39862,2);
INSERT INTO stanza VALUES('T179','3','Sumamba kay Kristo<br/>Tinubos na tao,<br/>Purihin Siya!<br/>Sa Kanya''y magsaya,<br/>Magkaingay pa nga,<br/>Himig, nagkaisa,<br/>Sa Kordero!<br/>',NULL,39863,3);
INSERT INTO stanza VALUES('T179','4','Bagay nagbabago,<br/>Nguni''t di-hihintong<br/>Purihin Siya!<br/>Patuloy papuri,<br/>Parangal sa Hari,<br/>Laksan ang pagbunyi<br/>Sa Kordero!<br/>',NULL,39864,4);
INSERT INTO stanza VALUES('T180','1','Hesus kami''y masayang sumasamba<br/>Sa Iyo, nagpupuri nang masigla,<br/>Sa Iyong presensya kami''y pinagpala,<br/>Karapat-dapat Ka ngang masamba.<br/>',NULL,39865,1);
INSERT INTO stanza VALUES('T180','chorus','O Panginoon karapat-dapat,<br/>Tangi Ka lamang ang karapat-dapat;<br/>Sa Iyong presensya kami''y pinagpala<br/>Karapat-dapat Ka ngang masamba.<br/>',NULL,39866,2);
INSERT INTO stanza VALUES('T180','2','Tunay na Diyos at naging taong tunay,<br/>Para sa amin sa krus namatay,<br/>Binhi ng babae na ''pinangako,<br/>Sinaktan ang ulupong sa ulo.<br/>',NULL,39867,3);
INSERT INTO stanza VALUES('T180','chorus','O Panginoon karapat-dapat,<br/>Tangi Ka lamang ang karapat-dapat;<br/>Sa Iyong presensya kami''y pinagpala<br/>Karapat-dapat Ka ngang masamba.<br/>',NULL,39868,4);
INSERT INTO stanza VALUES('T180','3','Paano nga bang nagpakumbaba Ka,<br/>''Pinako sa krus ng Iyong nilikha?<br/>Kinamuhian ng tao, ''tinakwil<br/>Ng Diyos at sa dilim nagpasiil.<br/>',NULL,39869,5);
INSERT INTO stanza VALUES('T180','chorus','O Panginoon karapat-dapat,<br/>Tangi Ka lamang ang karapat-dapat;<br/>Sa Iyong presensya kami''y pinagpala<br/>Karapat-dapat Ka ngang masamba.<br/>',NULL,39870,6);
INSERT INTO stanza VALUES('T180','4','Nagtagumpay nang may kal''walhatian<br/>Iyong nilabanan ang kamatayan,<br/>Matimpi ko ba ang pagsasalaysay,<br/>Tungkol sa Poon na matagumpay?<br/>',NULL,39871,7);
INSERT INTO stanza VALUES('T180','chorus','O Panginoon karapat-dapat,<br/>Tangi Ka lamang ang karapat-dapat;<br/>Sa Iyong presensya kami''y pinagpala<br/>Karapat-dapat Ka ngang masamba.<br/>',NULL,39872,8);
INSERT INTO stanza VALUES('T181','1','Ekklesia ang may awitin<br/>Sa Kordero!<br/>Karapat-dapat purihin<br/>Ang Kordero!<br/>Sa Kanya''y lumuhod trono,<br/>Pumailanglang ang samyo,<br/>Pag-awit ay walang hinto,<br/>Sa Kordero!<br/>',NULL,39873,1);
INSERT INTO stanza VALUES('T181','2','Lahi''t bansa''y pumupuri<br/>Sa Kordero!<br/>Karapat-dapat ''pagbunyi<br/>Ang Kordero!<br/>Awitin ang kaligtasan,<br/>Tulad ng sa kulog laksan,<br/>Magtirapa sa harapan<br/>Ng Kordero!<br/>',NULL,39874,2);
INSERT INTO stanza VALUES('T181','3','Alpa''t awit humihimig<br/>Sa Kordero!<br/>Karapat-dapat sa tinig<br/>Ang Kordero!<br/>Dugo Niyang mahal bumili,<br/>Hirap, hinanap Niya kami,<br/>Dadalhin pa sa l''walhati<br/>Ng Kordero!<br/>',NULL,39875,3);
INSERT INTO stanza VALUES('T181','4','May pag-asa''t pagmamahal<br/>Sa Kordero!<br/>Karapat-dapat itanghal<br/>Ang Kordero!<br/>Walang singtamis na nota,<br/>Laging marilag na paksa,<br/>Anupa''t tungkol sa Kanya,<br/>Ang Kordero!<br/>',NULL,39876,4);
INSERT INTO stanza VALUES('T182','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,39877,1);
INSERT INTO stanza VALUES('T182','1','Hesus, karapat-dapat Ka<br/>Sa puring walang-hanggan,<br/>Iyong pag-ibig at biyaya<br/>''Di-arok ng isipan.<br/>',NULL,39878,2);
INSERT INTO stanza VALUES('T182','2','Pasalamat ihahandog<br/>Pinupuri ngalan Mo;<br/>Halaga Mo''y ibabantog,<br/>Dahil labis habag Mo.<br/>',NULL,39879,3);
INSERT INTO stanza VALUES('T182','3','Hesus, aming sinasamba,<br/>Dakila''t mahabagin;<br/>Walang hanggan Iyong pagsinta,<br/>Makapangyarihan din.<br/>',NULL,39880,4);
INSERT INTO stanza VALUES('T182','4','Hesus, ang Una at Huli,<br/>Hanggang wakas magdala;<br/>Sa nakaraan, pagpuri,<br/>Sa darating, tiwala.<br/>',NULL,39881,5);
INSERT INTO stanza VALUES('T182','5','Puri, puri, purihin Siya,<br/>Banal, laksan ang tinig;<br/>Puri, puri di magbawa,<br/>Puri''y hanggang sa langit.<br/>',NULL,39882,6);
INSERT INTO stanza VALUES('T183','1','Sabay-sabay na awitan,<br/>Kordero''y purihin;<br/>Kung may sampung libong dila,<br/>Awit isa rin nga.<br/>',NULL,39883,1);
INSERT INTO stanza VALUES('T183','2','Karapat-dapat Kordero,<br/>Itaas, purihin;<br/>Sigaw "Kordero''y namatay"<br/>Sa halip nga namin.<br/>',NULL,39884,2);
INSERT INTO stanza VALUES('T183','3','Hesus, karapat-dapat Ka,<br/>Tumanggap ng gloria;<br/>Pagpapala''y mas ibigay,<br/>Kailanma''y Iyong taglay.<br/>',NULL,39885,3);
INSERT INTO stanza VALUES('T183','4','Aakyat din mga banal,<br/>Papuri''y itanghal;<br/>Tanan sa silong ng langit,<br/>Patuloy aawit.<br/>',NULL,39886,4);
INSERT INTO stanza VALUES('T183','5','Mga tinubos nagkai-sa,<br/>Pumuri sa Kanya;<br/>Siyang nakaluklok sa trono,<br/>Ibunyi Kordero.<br/>',NULL,39887,5);
INSERT INTO stanza VALUES('T185','1','Panginoong pinagpala<br/>O Aleluya!<br/>Hindi masambit kailanman<br/>Iyong kapurihan!<br/>',NULL,39888,1);
INSERT INTO stanza VALUES('T185','chorus','Kordero''y dapat purihin,<br/>Laksan tinig din<br/>Aleluya! Aleluya!<br/>Amen! Purihin!<br/>',NULL,39889,2);
INSERT INTO stanza VALUES('T185','2','Dapat purihin: Kordero,<br/>Dugo''y binubo;<br/>Iyong saserdote at hari,<br/>Ginawa kami.<br/>',NULL,39890,3);
INSERT INTO stanza VALUES('T185','chorus','Kordero''y dapat purihin,<br/>Laksan tinig din<br/>Aleluya! Aleluya!<br/>Amen! Purihin!<br/>',NULL,39891,4);
INSERT INTO stanza VALUES('T185','3','Aleluya, Mahal lubos,<br/>Pangino''ng Hesus,<br/>Kami''y Iyo, Ikaw ay amin,<br/>Iyong kai-sa, Amen.<br/>',NULL,39892,5);
INSERT INTO stanza VALUES('T185','chorus','Kordero''y dapat purihin,<br/>Laksan tinig din<br/>Aleluya! Aleluya!<br/>Amen! Purihin!<br/>',NULL,39893,6);
INSERT INTO stanza VALUES('T185','4','Hindi mapigil ang kanta,<br/>O Aleluya!<br/>Kasamang banal ng bawa''t<br/>Bansa at dila.<br/>',NULL,39894,7);
INSERT INTO stanza VALUES('T185','chorus','Kordero''y dapat purihin,<br/>Laksan tinig din<br/>Aleluya! Aleluya!<br/>Amen! Purihin!<br/>',NULL,39895,8);
INSERT INTO stanza VALUES('T187','1','Poon, mayaman Ka sa ''min,<br/>Pag-ibig anong lalim!<br/>Sarili Mo''y kay sagana,<br/>Ika''y aming tamasa.<br/>',NULL,39896,1);
INSERT INTO stanza VALUES('T187','2','Ika''y Salita at Diyos pa,<br/>Una pa''y Diyos kasama,<br/>Naging laman, naging tao<br/>Diyos sinabi sa tao.<br/>',NULL,39897,2);
INSERT INTO stanza VALUES('T187','3','Tabernakulo ng Diyos Ka,<br/>Sa Iyo gloria''y nakita;<br/>Tunay na templo ng Diyos Ka,<br/>Sa Iyo, Diyos nakatira.<br/>',NULL,39898,3);
INSERT INTO stanza VALUES('T187','4','Bugtong na Anak ng Diyos Ka,<br/>Inihayag ang Ama;<br/>Buhay ng Diyos aking angkin,<br/>Kalikasan Niya''y akin.<br/>',NULL,39899,4);
INSERT INTO stanza VALUES('T187','5','Ikaw na Anak ng Tao<br/>Katulad likas namin,<br/>Anak ng Diyos kami''y maging<br/>Lumagong ganap sa Iyo.<br/>',NULL,39900,5);
INSERT INTO stanza VALUES('T187','6','Mesiyas na pinahiran,<br/>Panginoon ng tanan;<br/>Lahat na nasa lahat Ka,<br/>Sa tao''t Diyos tinakda.<br/>',NULL,39901,6);
INSERT INTO stanza VALUES('T187','7','Manliligtas na pinako,<br/>Dugo''t tubig nabubo;<br/>Nang tayo''y matubos ng Diyos,<br/>Taglay ang buhay ng Diyos.<br/>',NULL,39902,7);
INSERT INTO stanza VALUES('T187','8','Nal''walhati Hesus, Ikaw<br/>Pinababa ''Spiritu;<br/>Espiritu na masaklaw,<br/>Hatid katangian Mo.<br/>',NULL,39903,8);
INSERT INTO stanza VALUES('T187','9','Dibinong Ilaw ng buhay,<br/>Sa dilim nagtatanglaw;<br/>Puso ko''y niliwanagan,<br/>Nang ako''y mapuspusan.<br/>',NULL,39904,9);
INSERT INTO stanza VALUES('T187','10','Buhay ng Diyos na dibino,<br/>Bumuhay sa ''spiritu;<br/>Laya na sa kamatayan,<br/>Tamasa''y kayamanan.<br/>',NULL,39905,10);
INSERT INTO stanza VALUES('T187','11','Ika''y realidad ng Diyos,<br/>Tugon sa nais ng Diyos;<br/>Katotohanang naghatid,<br/>Sarili Mo''y nabatid.<br/>',NULL,39906,11);
INSERT INTO stanza VALUES('T187','12','Tanging daan ng buhay Ka,<br/>Nagdadala sa gloria;<br/>Daan ng realidad Mo,<br/>Tagumpay dulot nito.<br/>',NULL,39907,12);
INSERT INTO stanza VALUES('T187','13','Pagkabuhay-na-muli Ka,<br/>Nilulon kamatayan;<br/>Lakas nitong pagkabuhay,<br/>Krus dalhin, Ika''y sundan.<br/>',NULL,39908,13);
INSERT INTO stanza VALUES('T187','14','Walang dungis na Kordero,<br/>Ay naging katubusan;<br/>Nagbigay-buhay ''Spiritu,<br/>Nang tayo''y maisilang.<br/>',NULL,39909,14);
INSERT INTO stanza VALUES('T187','15','Tansong ahas na ''tinaas<br/>Sa sala ''ko''y niligtas;<br/>Sa krus Ikaw nga''y pinako,<br/>Nang mawasak ang diyablo.<br/>',NULL,39910,15);
INSERT INTO stanza VALUES('T187','16','Nagpalaya sa kulungan,<br/>O Pastol at pintuan!<br/>Nang sa Iyo may kalayaan,<br/>Pahinga sa pastulan.<br/>',NULL,39911,16);
INSERT INTO stanza VALUES('T187','17','Kami ay Iyong nilinisan,<br/>Tulad ng sa hugasan;<br/>Ingatan sa salamuha,<br/>Tamasa Iyong biyaya.<br/>',NULL,39912,17);
INSERT INTO stanza VALUES('T187','18','Batong nabiyak sa amin,<br/>Tubig buhay ''daluyin;<br/>Sariwang tubig inumin,<br/>Pagtighaw Mo''y alamin.<br/>',NULL,39913,18);
INSERT INTO stanza VALUES('T187','19','Ika''y bukal makalangit,<br/>Tubig na buhay tigib;<br/>Iniinom ang buhay Mo,<br/>Uhaw ay pinawi Mo.<br/>',NULL,39914,19);
INSERT INTO stanza VALUES('T187','20','Tinapay mula sa langit,<br/>Dibino''t dumarami;<br/>Sa yaman Mong masagana,<br/>Binusog ''spiritu nga.<br/>',NULL,39915,20);
INSERT INTO stanza VALUES('T187','21','Hininga ng buhay namin,<br/>Ika''y dapat langhapin;<br/>Sa Iyo''y mamuhay, gumawa,<br/>Yaman Mo''y aming mana.<br/>',NULL,39916,21);
INSERT INTO stanza VALUES('T187','22','Butil ng trigong namatay,<br/>Sa l''walhati nabuhay;<br/>Tayo''y Kanyang ibinunga,<br/>Mabuo Katawan nga.<br/>',NULL,39917,22);
INSERT INTO stanza VALUES('T187','23','Punong-ubas na dibino,<br/>Kami''y mga sanga Mo;<br/>Sa Iyo''y inugpong, tumira,<br/>Yaman Mo''y bahagi nga.<br/>',NULL,39918,23);
INSERT INTO stanza VALUES('T187','24','Kasintahang-Lalake Ka,<br/>Kami nama''y Iyong Nobya;<br/>Sa buhay, pagsinta, gloria,<br/>Kami''y Iyong makaisa.<br/>',NULL,39919,24);
INSERT INTO stanza VALUES('T187','25','Jacob nakita Kang hagdan,<br/>Langit sa Iyo''y nabuksan;<br/>Lupa''t langit walang hadlang,<br/>Sa Diyos, kami''y tahanan.<br/>',NULL,39920,25);
INSERT INTO stanza VALUES('T187','26','Poon, dakilang "AKO NGA",<br/>Ang kailangan nagawad;<br/>Tamasahin bilang lahat,<br/>Layon ng Diyos matupad.<br/>',NULL,39921,26);
INSERT INTO stanza VALUES('T188','beginning-note','(Ang himnong ito ay maaaring paikliin sa pamamagitan ng pag-awit ng mga sumusunod na saknong: 1, 2, 7, 9, 11, 14, 17, 21 at 22 kaya ito lamang ang mga saknong na isinalin.)<br/>',NULL,39922,1);
INSERT INTO stanza VALUES('T188','1','Sintang Poon, Anak ng Diyos,<br/>Kahayagan Niyang lubos;<br/>Ikaw ang kahulugan Niya<br/>Sa Iyo Diyos nagsalita.<br/>',NULL,39923,2);
INSERT INTO stanza VALUES('T188','2','Ang tatak ng substansya Niya,<br/>Ningning ng Kanyang gloria;<br/>Sa Iyo salaysay Niya''y buo,<br/>Aming Diyos, Ikaw Mismo.<br/>',NULL,39924,3);
INSERT INTO stanza VALUES('T188','7','May kalikasang pantao,<br/>Ika''y tunay na tao;<br/>Kamatayan Iyong tinikman,<br/>Nang likas Mo''y makamtan.<br/>',NULL,39925,4);
INSERT INTO stanza VALUES('T188','9','Sa kamatayan ang diyablo,<br/>Iyong nilipol, tinalo.<br/>Pinabanal buhay Mo,<br/>Sa l''walhati ang tungo.<br/>',NULL,39926,5);
INSERT INTO stanza VALUES('T188','11','Gaya ng tagapagtayo,<br/>Si Moises hinigtan Mo,<br/>Apostol Kang mula sa Diyos,<br/>Luwalhati Iyong lubos.<br/>',NULL,39927,6);
INSERT INTO stanza VALUES('T188','14','Si Aaron hinigtan Mo,<br/>Handog Ikaw na Mismo;<br/>Pumasok sa kalangitan,<br/>Na kabanal-banalan.<br/>',NULL,39928,7);
INSERT INTO stanza VALUES('T188','17','Ginawa nga dugong mahal<br/>Lalong mabuting tipan;<br/>Isang Bagong Testamento<br/>Para sa tinubos Mo.<br/>',NULL,39929,8);
INSERT INTO stanza VALUES('T188','21','Tagapagsakdal, Maykatha<br/>Pananampalataya,<br/>Sa Iyo kami''y tumalima<br/>Sa panalig, pagsinta.<br/>',NULL,39930,9);
INSERT INTO stanza VALUES('T188','22','Hindi Ka mapaparisan,<br/>Ikaw ang kayamanan;<br/>Lampas sa sukat pantao,<br/>Perpekto Ka''t kumpleto.<br/>',NULL,39931,10);
INSERT INTO stanza VALUES('T189','1','Tanging Anak na tunay,<br/>Larawan ng Di-yos;<br/>Bahagi Ka ng banal,<br/>Sa dugong nabuhos.<br/>Sa lahat ng nilalang,<br/>Ikaw ang Panganay;<br/>Sa Iyo sila''y nilikha,<br/>Nang I-yong mataglay.<br/>',NULL,39932,1);
INSERT INTO stanza VALUES('T189','2','Nauna Ka sa lahat,<br/>Ikaw nagbubuo;<br/>Lahat nananatili<br/>Nang dahil sa I-yo.<br/>Ika''y nangunguna sa<br/>Pagkabuhay-muli;<br/>Ekklesia''y Katawan Mo,<br/>Ulong mal''walhati!<br/>',NULL,39933,2);
INSERT INTO stanza VALUES('T189','3','Sa Iyo ang kapuspusan,<br/>Ama nasiyahan,<br/>Upang aming makita<br/>Lagi Kang manguna.<br/>Sa krus dugo nabubo,<br/>Lahat nagkasundo;<br/>Walang bahid nga kami,<br/>Sa Diyos iharap Mo.<br/>',NULL,39934,3);
INSERT INTO stanza VALUES('T189','4','Sa I-yo''y nananahan<br/>Puspos ng pagka-Diyos;<br/>Yaman ng karunungan<br/>Sa Iyo natagpuan.<br/>Pag-asa ng l''walhati<br/>Sa ''min nananahan<br/>Sa Iyo ay sakdal kami,<br/>Diyos ay nasiyahan.<br/>',NULL,39935,4);
INSERT INTO stanza VALUES('T189','5','Pawang mga anino<br/>Ang bagay sa mundo.<br/>Ikaw lamang ang tunay,<br/>Manga-ugat sa Iyo.<br/>Tamasahin Iyong yaman,<br/>Maging kapuspusan;<br/>Ika''y aming tanganan,<br/>Lumagong lubusan.<br/>',NULL,39936,5);
INSERT INTO stanza VALUES('T189','6','Sa loob ng Diyos sa Iyo<br/>Aming buhay tago;<br/>Lahat sa aming buhay,<br/>At pahingang buo.<br/>Dito sa bagong tao,<br/>Ika''y lahat-lahat;<br/>Aming Kristong masaklaw,<br/>Sa I-yo''y tatawag.<br/>',NULL,39937,6);
INSERT INTO stanza VALUES('T190','1','Aming paggunita sa Iyo<br/>Ay pagsamba sa Iyo Mismo;<br/>Minamahal, mahalaga,<br/>Mayaman, kamangha-mangha.<br/>',NULL,39938,1);
INSERT INTO stanza VALUES('T190','chorus','Angkop Ka sa kailangan ko,<br/>Puri''y umapaw sa puso!<br/>Nasisiyahan akong lubos,<br/>Di-masaid ang Iyong tustos.<br/>',NULL,39939,2);
INSERT INTO stanza VALUES('T190','2','Diyos na tunay at malinaw,<br/>Diyos na pag-ibig at ilaw;<br/>Bilang Diyos, buhay Ka sa amin,<br/>Diyos na mapagbiyaya rin.<br/>',NULL,39940,3);
INSERT INTO stanza VALUES('T190','3','Tao Kang matimyas, tunay,<br/>Pino, mabuti''t dalisay;<br/>Puso ng Diyos nilugod Mo,<br/>Nabihag Mo ang puso ko.<br/>',NULL,39941,5);
INSERT INTO stanza VALUES('T190','4','Mababang alipin Ka rin,<br/>Naglingkod para sa amin;<br/>Sumunod hanggang mamatay,<br/>Nang kami''y mabigyang buhay.<br/>',NULL,39942,7);
INSERT INTO stanza VALUES('T190','5','Bukod dito ay Hari Ka,<br/>Pinahiran ng Diyos Ama;<br/>Ayon sa buhay naghahari,<br/>Kami Iyong kasamang hari.<br/>',NULL,39943,9);
INSERT INTO stanza VALUES('T190','6','Sa pag-alaala sa Iyo<br/>Sarili Mo ay matamo;<br/>Sa pag-ibig, Ika''y tamasa,<br/>Kami ay Iyong kapareha.<br/>',NULL,39944,11);
INSERT INTO stanza VALUES('T191','1','Ika''y "Binhi ng babae,"<br/>Nang kaaway magapi;<br/>Kinuha likas ng tao,<br/>Namatay nang manalo<br/>Diyos na nagkatawang-tao,<br/>Bahagi''y lama''t dugo;<br/>Winasak sa kamatayan<br/>Diyablo''t kapangyarihan.<br/>',NULL,39945,1);
INSERT INTO stanza VALUES('T191','2','Bilang pangako''y dumating,<br/>"Binhi ni Abraham" din;<br/>Nang pagpapalang pangako,<br/>Datnan lahat ng tao.<br/>Kay Abraham nauna Ka,<br/>Ang dakilang "AKO NGA"<br/>Anak Ka niyang pumarito,<br/>Ipinangakong "Kordero."<br/>',NULL,39946,2);
INSERT INTO stanza VALUES('T191','3','Ang "Binhi ni David" naman,<br/>Para sa kaharian;<br/>Sa l''walhati''t pagtatayo,<br/>Niluklok Ka sa trono.<br/>Tunay "Anak ni David" Ka,<br/>Tinawag Kang "Poon" niya;<br/>Sapagka''t Ika''y "ugat" niya.<br/>Poon walang hanggan pa.<br/>',NULL,39947,3);
INSERT INTO stanza VALUES('T191','4','"Makapangyarihang Diyos" t''yak,<br/>Kahit Ikaw ang Anak;<br/>"Anak" sa ''min ''binigay Ka,<br/>Siyang "walang hanggang Ama"<br/>Tamang pangako ng Ama,<br/>Sa Iyo nga maniwala;<br/>Pangako Mo''y pawang "Oo,"<br/>Pawang "Amen," totoo.<br/>',NULL,39948,4);
INSERT INTO stanza VALUES('T193','1','Napakayaman Mo sa ''min,<br/>Lahat Ka sa amin;<br/>Anumang aming kailangan,<br/>Iyong natutugunan.<br/>Puso namin ay humanga,<br/>''Spiritu''y sumamba;<br/>Nagpapasalamat sa Iyo,<br/>Nakita''ng yaman Mo.<br/>',NULL,39949,1);
INSERT INTO stanza VALUES('T193','2','Propetang ''binangon ng Diyos,<br/>Sinalita ang Diyos;<br/>Tulad ni Moises nagturo,<br/>Makita''ng layon Mo.<br/>Tulad ni Jonas ''sinugo,<br/>Naghayag simbolo;<br/>Kamataya''t pagkabuhay<br/>Nang manalig sa Iyo.<br/>',NULL,39950,2);
INSERT INTO stanza VALUES('T193','3','Propetang mula sa tao,<br/>Tulad Eliseo,<br/>Sa pag-ibig nagsalita<br/>May lakas himala.<br/>Tulad Isaias, may b''yaya<br/>Kristo''y ''pinakita<br/>Nang ihayag Kristo''y tanan,<br/>Bilang buhay, yaman.<br/>',NULL,39951,3);
INSERT INTO stanza VALUES('T193','4','Saserdoteng banal ng Diyos,<br/>Para nga sa amin;<br/>Tulad A''ron tawag ng Diyos,<br/>Naglingkod gayon din.<br/>Sa pag-ibig ''ko''y dinala,<br/>Sa harap ng Diyos nga;<br/>Saserdoteng Mataas Ka,<br/>Ako''y napreserba.<br/>',NULL,39952,4);
INSERT INTO stanza VALUES('T193','5','Saserdoteng Diyos nagsugo,<br/>Panghari''t dibino;<br/>Gayang Hari ng Salem nga,<br/>Sa Diyos naglingkod Siya.<br/>Ang dala''y alak, tinapay,<br/>Tustos nating tunay;<br/>Melchisedek ang may dala,<br/>Diyos aking tamasa.<br/>',NULL,39953,5);
INSERT INTO stanza VALUES('T193','6','Haring kay David katulad,<br/>Nais ng Diyos hangad;<br/>Nakipagbaka''t tumalo,<br/>Kaaway ginupo.<br/>Hindi sa kamay ng tao,<br/>Lumuklok sa trono;<br/>Sa awtoridad dibino<br/>Naghari sa tao.<br/>',NULL,39954,6);
INSERT INTO stanza VALUES('T193','7','Gaya''y Haring Salomon nga,<br/>Mamunong payapa;<br/>Sa karunungan namuno,<br/>Templo''y itinayo.<br/>Sa gitna ng mga banal,<br/>Hari''y nagmamahal;<br/>Sa darating na panahon,<br/>Haring tulad ngayon.<br/>',NULL,39955,7);
INSERT INTO stanza VALUES('T193','8','Saserdote Ka''t propeta,<br/>Haring anong ganda;<br/>Sa tao''t Diyos Iyong halaga<br/>Kahanga-hanga nga.<br/>Sa kung ano Ka umibig,<br/>Iyong inakit higit;<br/>Sa Iyo pagsamba''t papuri,<br/>Hindi na mapawi.<br/>',NULL,39956,8);
INSERT INTO stanza VALUES('T194','1','Ika''y patotoo ng Diyos,<br/>Higit pa sa utos;<br/>Utos Iyong anino lamang<br/>Ika''y katunayan.<br/>Diyos, pinaliwanag nito,<br/>Pinalinaw lalo;<br/>Realidad ng Diyos Ka nga,<br/>Diyos sa Iyo''y tumira.<br/>',NULL,39957,1);
INSERT INTO stanza VALUES('T194','2','Sagisag Mo rin ang kaban,<br/>Na may kautusan;<br/>Sa loob Mo''y may Diyos naman,<br/>Sa Iyo tumatahan.<br/>Kaban yari sa akasia,<br/>Ginto bumalot pa;<br/>Pagka-tao at pagka-Diyos,<br/>Maihalong lubos.<br/>',NULL,39958,2);
INSERT INTO stanza VALUES('T194','3','Tabernakulong tunay Ka,<br/>Diyos sa Iyo''y tumira;<br/>May biyaya, naging laman.<br/>May katotohanan.<br/>Sa Iyo l''walhati nakita,<br/>Ikaw ang Salita;<br/>Salita''t gawa naghayag,<br/>Pag-ibig, liwanag.<br/>',NULL,39959,3);
INSERT INTO stanza VALUES('T194','4','Sagisag Mo''y templo ng Diyos,<br/>Bahay Ka ng Di-yos;<br/>Buong Diyos sa Iyo nanahan,<br/>Hayag kapuspusan.<br/>Kahit ang diyablo''y nangwasak,<br/>Bilang Ka sa patay,<br/>Sa pagkabuhay ''tinayo.<br/>Mas malaking templo.<br/>',NULL,39960,4);
INSERT INTO stanza VALUES('T194','5','Lunsod Banal napakita,<br/>Larawan ng Nobya;<br/>Nahayag Iyong karagdagan,<br/>At Iyong kapuspusan.<br/>Sa loob Mo Diyos na ilaw,<br/>Ilawan ay Ikaw,<br/>Sa lunsod nagliliwanag,<br/>Gloria ng Diyos hayag.<br/>',NULL,39961,5);
INSERT INTO stanza VALUES('T194','6','Kaban ma''t tabernakulo,<br/>Utos, lunsod, templo;<br/>Pawang sagisag Mo Mismo.<br/>Hinayag yaman Mo.<br/>Sentro''t paligid ay Ikaw<br/>Ang lahat ay Ikaw;<br/>Diyos, tao sa Iyo nakita,<br/>Aming Sinisinta.<br/>',NULL,39962,6);
INSERT INTO stanza VALUES('T195','1','Ikaw lahat ng hain,<br/>Handa para sa ''min;<br/>May gloria''t katamisan,<br/>Nitong kahulugan.<br/>Tinupad layon ng Diyos,<br/>Nilugod Siyang lubos;<br/>Sapat sa ''ming kailangan,<br/>Walang kakulangan!<br/>',NULL,39963,1);
INSERT INTO stanza VALUES('T195','2','Handog na susunugin,<br/>Sa apoy tupukin;<br/>Sa Diyos samyong matamis,<br/>Tupdin Kanyang nais.<br/>Iyong pinangalagaan,<br/>Kanyang kagustuhan;<br/>Sarili Mo''y hinain<br/>Sa Diyos ay pagkain.<br/>',NULL,39964,2);
INSERT INTO stanza VALUES('T195','3','Handog na pagkain Ka,<br/>May langis, kamangyan<br/>Banal, pino at sakdal<br/>Punong katamisan.<br/>Kapayapaan gawin,<br/>Pampayapang hain;<br/>Kasama ng Diyos kami,<br/>Sa Iyo bumahagi.<br/>',NULL,39965,3);
INSERT INTO stanza VALUES('T195','4','Sa kasalanang hain<br/>Naging sala Ka rin,<br/>Namatay Ka''t tinupad<br/>Katubusang tapat.<br/>Handog sa pagkasala<br/>Pasan aming sala<br/>Kat''wiran sinagot Mo<br/>Patawad natamo.<br/>',NULL,39966,4);
INSERT INTO stanza VALUES('T195','5','Ang niluglog na alay<br/>Binuhay sa patay;<br/>Hades at kamatayan<br/>Napagtagumpayan.<br/>Naitaas na hain,<br/>Umakyat sa langit;<br/>Panlangit na pagkain<br/>Ako ay busugin.<br/>',NULL,39967,5);
INSERT INTO stanza VALUES('T196','1','Mga sagisag no''ng una,<br/>Mga larawan Mo nga;<br/>Mga tipo at simbolo,<br/>Ika''y sa ''mi''y totoo.<br/>''Pag tiningnan ang larawan,<br/>Ikaw ay hahangaan,<br/>Kahanga-hangang Iyong yaman,<br/>''Samba namin Iyong tanan!<br/>',NULL,39968,1);
INSERT INTO stanza VALUES('T196','2','Poon, tunay naming Paskua,<br/>Kami''y nilampasan Niya;<br/>Sa Iyong Sarili''t pagtubos,<br/>Kami''y nagkai-sa ng Diyos.<br/>Ika''y Kordero ng Diyos din<br/>Upang kami''y tubusin<br/>Aming pantubos dugo Mo,<br/>Ikaw di''y pagkain ko.<br/>',NULL,39969,2);
INSERT INTO stanza VALUES('T196','3','Makalangit na tinapay,<br/>Tinapay din ng buhay;<br/>Nang kinain Ka''y humalo,<br/>Sala''t hidwa nahinto.<br/>Ang Kordero at Tinapay,<br/>Sagisag Ika''y buhay;<br/>Sa harap Mo nagpipiging<br/>Yaman Mo''y tamasahin.<br/>',NULL,39970,3);
INSERT INTO stanza VALUES('T196','4','Mannang makalangit Ikaw,<br/>Pagkain araw-araw;<br/>Panustos at pampalakas,<br/>Kailangan ko''y may lunas.<br/>Batong buhay Ka rin, Hesus,<br/>Bitak, buhay umagos;<br/>Inuman tubig ng buhay,<br/>Di na muling mauhaw.<br/>',NULL,39971,4);
INSERT INTO stanza VALUES('T196','5','Mabuting lupang Canaan,<br/>Mataas at mayaman;<br/>Gatas, pulot umaagos,<br/>Sagana di maubos,<br/>Sa yaman Mo, tungo sa Diyos,<br/>Pagsamba nami''y lubos;<br/>Sa pag-ibig magkaugpong<br/>Pagtatayo''y susulong.<br/>',NULL,39972,5);
INSERT INTO stanza VALUES('T197','1','Nagpaloob-ng-lahat Ka,<br/>Kami''y nasa Iyo nga;<br/>Bahaging hinanda ng Diyos.<br/>Aming tanang lubos.<br/>',NULL,39973,1);
INSERT INTO stanza VALUES('T197','2','Dunong ng Diyos Ka sa amin,<br/>Iyong niligtas kami,<br/>Daan Ka ng kaligtasan,<br/>''Ka''y aming kat''wiran.<br/>',NULL,39974,2);
INSERT INTO stanza VALUES('T197','3','Ikaw sa ami''y kat''wiran,<br/>Hiling tinugunan;<br/>Naging mat''wid kami sa Iyo,<br/>Sa Iyo nga''y kumpleto.<br/>',NULL,39975,3);
INSERT INTO stanza VALUES('T197','4','Amin ngang kabanalan Ka,<br/>Upang matransporma;<br/>Kami''y pinabanal sa Iyo,<br/>Nang makawangis Mo,<br/>',NULL,39976,4);
INSERT INTO stanza VALUES('T197','5','Amin ngang katubusan Ka,<br/>Mapawangis sa Iyo;<br/>Katawan babaguhin pa,<br/>Ganap mapalaya.<br/>',NULL,39977,5);
INSERT INTO stanza VALUES('T197','6','Pangino''n sa paggunita,<br/>Tinatamasa Ka,<br/>Nais na bumalik Ka na<br/>''Di na mawalay pa.<br/>',NULL,39978,6);
INSERT INTO stanza VALUES('T197','7','Anong tamis ng patikim,<br/>Ika''y angkin namin;<br/>Nguni''t ang makasama Ka,<br/>Higit ang tamasa.<br/>',NULL,39979,7);
INSERT INTO stanza VALUES('T198','beginning-note','Alternate: tune of Hymn 218<br/>',NULL,39980,1);
INSERT INTO stanza VALUES('T198','1','Poon, Punò ng Buhay Ka,<br/>Panustos-buhay nga;<br/>Iyong bunga''y puspos ng buhay,<br/>Gutom pawing tunay.<br/>',NULL,39981,2);
INSERT INTO stanza VALUES('T198','2','Makalangit Punong-ubas,<br/>Tustos sa Iyo buhat;<br/>Sa Iyo namuhay, nanahan,<br/>May kapahingahan.<br/>',NULL,39982,3);
INSERT INTO stanza VALUES('T198','3','Poon, Punong Mansanas Ka,<br/>Aming tamasa Ka;<br/>Iyong bunga''y may katamisan,<br/>Lilim Mo''y natikman.<br/>',NULL,39983,4);
INSERT INTO stanza VALUES('T198','4','Punò ng pagpapagaling,<br/>Doon ibinitin;<br/>Namatay dahil sa amin,<br/>Nang kami''y gumaling.<br/>',NULL,39984,5);
INSERT INTO stanza VALUES('T198','5','Sanga ng Diyos Ikaw na nga,<br/>Tahan kapuspusan;<br/>Sa Iyo, Diyos aming biyaya,<br/>Katotohanan nga.<br/>',NULL,39985,6);
INSERT INTO stanza VALUES('T198','6','Poon, Sanga ni David Ka,<br/>Naging tao Ka nga;<br/>Ang tunay na pagka-tao,<br/>Sa Iyo ay natanto.<br/>',NULL,39986,7);
INSERT INTO stanza VALUES('T198','7','Tungkod na umusbong ng Diyos,<br/>Buhay walang tapos;<br/>Kamatayan di madaig,<br/>Pagkabuhay-muli.<br/>',NULL,39987,8);
INSERT INTO stanza VALUES('T198','8','Kami''y "bakal", lumubog na,<br/>Patpat, lumutang Ka;<br/>Sa kamatayan lumaya,<br/>Buhay nagpasigla.<br/>',NULL,39988,9);
INSERT INTO stanza VALUES('T198','9','"Punò ng Kabantugan" Ka,<br/>Amin kang tamasa;<br/>Nang amin Kang ginunita,<br/>Kami''y nagdeklara!<br/>',NULL,39989,10);
INSERT INTO stanza VALUES('T199','1','Ika''y walang hanggang Bato,<br/>Para sa ''kin pinalo;<br/>Ininom bilang ''Spiritu,<br/>Naging kai-sa Mo ako.<br/>''Di natitinag na Bato,<br/>Dito kami nai-tayo;<br/>Kai-sa Mo sa pagkatubos<br/>''Di na kami makilos.<br/>',NULL,39990,1);
INSERT INTO stanza VALUES('T199','chorus','Iyong halaga''y talos namin,<br/>Lahat Mo''y para sa ''min;<br/>Sa pag-ibig ginunita,<br/>Yaman Mo''y tinamasa.<br/>',NULL,39991,2);
INSERT INTO stanza VALUES('T199','2','Batong subok ng marami,<br/>Mahal ng Diyos at namin;<br/>Maasahan, matatag pa,<br/>Lakas Mo di hihina.<br/>Batong buháy nanatili,<br/>Para sa ''min pinili.<br/>Diyos humirang, anong tibay,<br/>Ang walang hanggang buhay.<br/>',NULL,39992,3);
INSERT INTO stanza VALUES('T199','3','Batong pundasyon nilatag,<br/>Ng Diyos na ''di matinag;<br/>Dahil pundasyon matatag,<br/>Aming seguridad t''yak.<br/>Liban sa Iyo, walang iba,<br/>Pundasyong malagay pa,<br/>Pundasyong namukod-tangi,<br/>Walang hanggang lalagi.<br/>',NULL,39993,5);
INSERT INTO stanza VALUES('T199','4','Ikaw, panulok na Bato,<br/>Para sa pagtatayo;<br/>Nagkai-sa Hentil at Hudyo,<br/>Bilang ''sang Katawan Mo.<br/>Pang-ibabaw na Bato Ka,<br/>Hatid Mo ay biyaya<br/>Ikaw, aming takip, gloria,<br/>Dapat papurihan Ka.<br/>',NULL,39994,7);
INSERT INTO stanza VALUES('T200','1','Araw ng katuwiran Ka,<br/>Pakpak panlunas pa;<br/>Ang mal''walhati Mong mukha,<br/>Yaman Mo''y dinala.<br/>',NULL,39995,1);
INSERT INTO stanza VALUES('T200','2','Magiliw na habag ng Diyos,<br/>Sa amin sumilay;<br/>Mga nasa kadiliman,<br/>Iyong maliwanagan.<br/>',NULL,39996,2);
INSERT INTO stanza VALUES('T200','3','Umagang walang ulap Ka,<br/>Sinag ng Umaga;<br/>Kami''y tulad murang damo,<br/>Nagalak, sinag Mo.<br/>',NULL,39997,3);
INSERT INTO stanza VALUES('T200','4','Pagsilay ng Iyong liwanag,<br/>Palaging dagdagan;<br/>Silayan panloob t''wina,<br/>Maganap araw na.<br/>',NULL,39998,4);
INSERT INTO stanza VALUES('T200','5','Ang pagsilay ng liwanag,<br/>Nilampasang hirap;<br/>Dala''y pag-ibig at habag,<br/>Lagi ang pagsikat.<br/>',NULL,39999,5);
INSERT INTO stanza VALUES('T200','6','Ika''y Tala sa Umaga<br/>Aming gantimpala;<br/>Sinilayan, mga sa Iyo<br/>Umibig nang husto.<br/>',NULL,40000,6);
INSERT INTO stanza VALUES('T200','7','Sa liwanag paibigin,<br/>Mata ko''y linawin;<br/>Magbantay at manalangin,<br/>Ikaw ay hintayin.<br/>',NULL,40001,7);
INSERT INTO stanza VALUES('T201','1','Pangino''n Manananggol Ka,<br/>''Ming Taga-aliw pa,<br/>Aming Tagapamagitan,<br/>Sa Kanyang harapan.<br/>',NULL,40002,1);
INSERT INTO stanza VALUES('T201','2','Tagapagtanggol Ka namin,<br/>Tagasamo Ka rin,<br/>Kami''y ''pinananalangin,<br/>Lubhang matulungin.<br/>',NULL,40003,2);
INSERT INTO stanza VALUES('T201','3','Ayon nga sa lugod ng Diyos,<br/>Lahat tinupad Mo,<br/>Sa langit, sa loob namin,<br/>Lahat nilutas Mo.<br/>',NULL,40004,3);
INSERT INTO stanza VALUES('T201','4','Namamagitan Ka lagi,<br/>Poong Espiritu;<br/>Sa pagsamo Mo sa langit,<br/>Sa loob ang hibik.<br/>',NULL,40005,4);
INSERT INTO stanza VALUES('T201','5','Laging buhay, ayon sa Diyos<br/>Nagbiyayang lubos;<br/>Sa buhay ng pagkabuhay,<br/>Lakas ay tinaglay.<br/>',NULL,40006,5);
INSERT INTO stanza VALUES('T201','6','Nagbigay-buhay ''Spiritu,<br/>Lakas sa ''ming hina;<br/>Lakas Mo sa ''ming ''spiritu,<br/>Nakapagpreserba.<br/>',NULL,40007,6);
INSERT INTO stanza VALUES('T201','7','Sa Iyong pag-ibig at awa,<br/>Laging naglingkod Ka;<br/>Kami ang Iyong kapuspusan,<br/>Ikaw aming tanan.<br/>',NULL,40008,7);
INSERT INTO stanza VALUES('T202','1','Poon, Ikaw ay Alpha,<br/>Ikaw ri''y Omega;<br/>Sa Iyo''y walang nauna,<br/>Kasunod Mo''y wala.<br/>Tanging Simula Ka nga,<br/>Katapusan Ka pa;<br/>Sa Iyo lahat nagbuhat,<br/>Napaloob lahat.<br/>',NULL,40009,1);
INSERT INTO stanza VALUES('T202','2','Lahat sa Iyo nagmula,<br/>Dahil Ika''y Alpha;<br/>Lahat sa Iyo humangga,<br/>Dahil Omega Ka.<br/>Lahat binubuo Mo,<br/>Alpabetong buo;<br/>Tanang titik ay Ikaw,<br/>Lahat Iyong sinaklaw.<br/>',NULL,40010,2);
INSERT INTO stanza VALUES('T202','3','Una Ka sa nilikha,<br/>Ulo ng lahat nga;<br/>Huli sa likha ng Diyos,<br/>Ikaw magtatapos.<br/>Sa nilikha ay Una,<br/>Sa Iyo lahat asa;<br/>Sa Iyo umiral tanan,<br/>Huli sa nilalang.<br/>',NULL,40011,3);
INSERT INTO stanza VALUES('T202','4','Yamang Ika''y Simula,<br/>Sa lahat Una Ka;<br/>Yamang katapusan Ka,<br/>Tagapagmana Ka.<br/>Bukod tanging Simula,<br/>Pinagmulan Ka nga;<br/>Tangi Kang katapusan,<br/>Ikaw ang hantungan.<br/>',NULL,40012,4);
INSERT INTO stanza VALUES('T202','5','Poon, mahal Ka namin,<br/>Minahalaga rin;<br/>Mataas sa lahat Ka,<br/>Alpha at Omega.<br/>Purihin, Simula Ka,<br/>Tatawaging Una;<br/>Katapusa''y sambahin,<br/>Pinakahuli rin.<br/>',NULL,40013,5);
INSERT INTO stanza VALUES('T203','1','Bago pa nagsimula ang daigdig at panahon,<br/>Bugtong na Anak Ka, nasa piling ng Ama noon.<br/>Persona Mo''y di nagbago nang ''binigay ng Ama,<br/>Kapuspusan ng Ama sa Espiritu''y makita.<br/>',NULL,40014,1);
INSERT INTO stanza VALUES('T203','2','Kamataya''t pagkabuhay, ginawa Kang Panganay,<br/>Mga anak — bunga ng pamamahagi ng buhay.<br/>Buhay Mo''y nagpalaganap, kami''y mga kapatid,<br/>Kami''y Iyong pagpaparami, paglaki''y walang patid.<br/>',NULL,40015,2);
INSERT INTO stanza VALUES('T203','3','Isang butil ng trigo Ka at namatay sa lupa,<br/>Kamataya''t pagkabuhay — l''walhati''y ''pinakita;<br/>At kami''y Iyong isinilang na maging mga binhi,<br/>Naghalo, naging tinapay: Katawang mal''walhati.<br/>',NULL,40016,3);
INSERT INTO stanza VALUES('T203','4','Kami''y Iyong pagpaparami, Katawan, Kasintahan,<br/>Kahayagan at kapuspusan, lagi Mong tahanan;<br/>Iyong paglawak, karugtong, at paglago ng buhay Mo,<br/>Paggulang, pag-apaw ng yaman, at kaisahan Mo.<br/>',NULL,40017,4);
INSERT INTO stanza VALUES('T206','1','Kristo, balon ng buhay,<br/>May agos ng buhay.<br/>Lunas sa aking hapis,<br/>Bukal na kay tamis.<br/>Lawak ng Kanyang awa,<br/>Sa dagat higit pa.<br/>Binalak ng dunong Niya<br/>Sapat na biyaya.<br/>',NULL,40018,1);
INSERT INTO stanza VALUES('T206','2','Ako''y sa aking Sinta,<br/>Sa akin naman Siya;<br/>Sa bahay na sagana<br/>Salarin dinala!<br/>Ang Kanyang kagalingan,<br/>Sa akin binilang;<br/>Ako''y hinawakan Niya;<br/>Ang kublihan ko''y Siya.<br/>',NULL,40019,2);
INSERT INTO stanza VALUES('T206','3','Di sa damit ang titig<br/>Kundi sa Inibig;<br/>Tuon di sa l''walhati,<br/>Kundi sa ''king Hari;<br/>Di sa putong ang mata<br/>Kundi sa kamay Niya;<br/>Kordero''y l''walhati ko,<br/>Siyang katayuan ko.<br/>',NULL,40020,3);
INSERT INTO stanza VALUES('T207','1','Hesus nang maisip Kita<br/>Iyong sinta, biyaya,<br/>Espiritu''y umaasa<br/>Ganda Mo''y makita.<br/>',NULL,40021,1);
INSERT INTO stanza VALUES('T207','2','Kahit sa ilang dumaan,<br/>Lupa''y uhaw, tigang,<br/>Tinik at dawag, saanman<br/>Dakong may kaaway.<br/>',NULL,40022,2);
INSERT INTO stanza VALUES('T207','3','Sa lalim ng Iyong pag-ibig,<br/>Umapaw papuri,<br/>Sa Iyo kami''y nasiyahan,<br/>May galak awitan.<br/>',NULL,40023,3);
INSERT INTO stanza VALUES('T207','4','Buhay, Pahinga, Kalasag,<br/>Bato at Liwanag,<br/>Tuwing Kita''y magunita,<br/>Palaging sariwa.<br/>',NULL,40024,4);
INSERT INTO stanza VALUES('T207','5','Hesus, kami''y Iyong ingatan,<br/>Mahigpit Kang sundan,<br/>Hanggang tagumpay matanyag,<br/>Mukha Mo''y mahayag.<br/>',NULL,40025,5);
INSERT INTO stanza VALUES('T208','1','O Hesus, Hesus mahal ko<br/>Ako''y patawarin Mo,<br/>Araw-araw ay makalibo,<br/>Nasasambit ang ngalan Mo.<br/>',NULL,40026,1);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40027,2);
INSERT INTO stanza VALUES('T208','2','Mahal Kita, di-mapigil<br/>Damdami''y di masiil;<br/>Ang pag-ibig Mo''y umaalab<br/>Sa puso ko''y tumatalab.<br/>',NULL,40028,3);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40029,4);
INSERT INTO stanza VALUES('T208','3','Lahat-lahat Ka sa akin;<br/>Karangalan, yaman din;<br/>Nasà ng puso, kalakasan,<br/>Walang hanggang kalusugan.<br/>',NULL,40030,5);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40031,6);
INSERT INTO stanza VALUES('T208','4','Magningas Ka sa puso ko,<br/>Gabi''t araw, Irog ko.<br/>Hanggang sa matupok ang yagit<br/>Ng makalupang pag-ibig.<br/>',NULL,40032,7);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40033,8);
INSERT INTO stanza VALUES('T208','5','Liwanag sa kadiliman,<br/>Buhay ng langit nand''yan;<br/>Hesus mahal ko, aking yaman,<br/>Anong Iyong kahalagahan?<br/>',NULL,40034,9);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40035,10);
INSERT INTO stanza VALUES('T208','6','Anong hanggana''t pagtiis?<br/>Pag-ibig ubod tamis?<br/>Panginoon higit Ka ngayon<br/>Marilag kaysa kahapon.<br/>',NULL,40036,11);
INSERT INTO stanza VALUES('T208','chorus','Hesus ako''y Iyong samahan;<br/>Ako''y Iyo maging anuman;<br/>Ang ngiti Mo''y gantimpala;<br/>Hesus mahal Kita.<br/>',NULL,40037,12);
INSERT INTO stanza VALUES('T209','1','Hesus, ang maisip Ka lang,<br/>Puspos nang tamis na;<br/>Higit kung masilayan Ka,<br/>Presensya''y pahinga.<br/>',NULL,40038,1);
INSERT INTO stanza VALUES('T209','2','Hindi mahimig ng tinig,<br/>Puso''y di malaman,<br/>Katamisang labis ng Iyong<br/>Pinagpalang Ngalan!<br/>',NULL,40039,2);
INSERT INTO stanza VALUES('T209','3','Pag-asa ng pusong bagbag,<br/>Galak ng maamo,<br/>Sa tisod at naghahanap,<br/>Napakabuti Mo!<br/>',NULL,40040,3);
INSERT INTO stanza VALUES('T209','4','Di mapakita ninuman,<br/>Sa wika o pluma;<br/>Giliw lang Niya ang may batid<br/>Ng Kanyang pagsinta.<br/>',NULL,40041,4);
INSERT INTO stanza VALUES('T209','5','O Hesus! tanglaw ng lahat!<br/>Bukal ng buhay Ka!<br/>Lampas sa ''ming kagalakan,<br/>At sa aming nasa.<br/>',NULL,40042,5);
INSERT INTO stanza VALUES('T209','6','Wala nang makapapawi,<br/>Sa ''ming kauhawan;<br/>Bukal Kang di mapipigil!<br/>Ang iba ay tigang.<br/>',NULL,40043,6);
INSERT INTO stanza VALUES('T209','7','Hesus, tanging Galak namin,<br/>Gantimpalang laan;<br/>L''walhati Ka namin ngayon,<br/>At sa walang hanggan.<br/>',NULL,40044,7);
INSERT INTO stanza VALUES('T210','1','Si Hesus nasumpungan ko, tapat na kaibigan,<br/>Siya ang pinakamaganda sa akin;<br/>Punong-mansanas na tunay, sa Kanya''y nakita<br/>Ang lahat kong kailangan nang malinis.<br/>Sa lungkot aking aliw, sa gusot pag-asa,<br/>Inako Niya lahat ng suliranin,<br/>Tunay Siyang Punong-mansanas, Tala sa Umaga,<br/>Sa akin Siya ang pinakamaganda.<br/>',NULL,40045,1);
INSERT INTO stanza VALUES('T210','2','Pighati ko''y pinawi Niya, lungkot dinadala;<br/>Sa tukso ay matibay kong moog Siya;<br/>Aking tinalikdan lahat, nang dahil sa Kanya,<br/>Ako''y iniingatan ng lakas Niya.<br/>Talikdan man ng mundo, Satanas magtukso,<br/>Ang Kanyang layunin aabutin ko,<br/>Tunay Siyang Punong-mansanas, Tala sa Umaga,<br/>Sa akin Siya ang pinakamaganda.<br/>',NULL,40046,2);
INSERT INTO stanza VALUES('T210','3','Kailanman ay di Niya ako iiwanan dito,<br/>Habang sa Kanya nananalig ako,<br/>Hindi ako nangangamba, ''koy binabantayan,<br/>Manna Niya''y nagbibigay kabusugan.<br/>At sa kal''walhatian, mukha Niya matanaw,<br/>Ilog ng kasiyahan ay aapaw,<br/>Tunay Siyang Punong-mansanas, Tala sa Umaga,<br/>Sa akin Siya ang pinakamaganda.<br/>',NULL,40047,3);
INSERT INTO stanza VALUES('T213','1','Nang gabing yaon, Hesus,<br/>Lahat Iyong kasama,<br/>Bumaba ang karimlan<br/>Sa isip na banal,<br/>"Alalahanin Ako"<br/>Gaya ng sabi Mo,<br/>Pupuri aming puso,<br/>Paggunita sa Iyo.<br/>',NULL,40048,1);
INSERT INTO stanza VALUES('T213','2','Ang lalim ng Iyong dusa<br/>Kay hirap tantuin,<br/>Saro ng pagdurusa,<br/>Ikaw ang tumikim;<br/>At Diyos sa Iyo''y lumisan<br/>Sa punong sinumpa;<br/>Salamat nang lubusan,<br/>Alalahanin Ka.<br/>',NULL,40049,2);
INSERT INTO stanza VALUES('T213','3','Dilim, sa Iyo''y lumibot,<br/>Sa diwa''y nagtuon,<br/>Sa dibdib Mo''y umikot,<br/>Gaya''y mga alon;<br/>Biyaya''y sumagana,<br/>Pag-ibig, nakita;<br/>Tuwa''t lungkot nagsama,<br/>Maalaala Ka.<br/>',NULL,40050,3);
INSERT INTO stanza VALUES('T213','4','Nabuhay na muli Ka,<br/>Panganay sa patay;<br/>Pag-akyat Mo''y nakita,<br/>Ulo ng Ekklesia.<br/>Tinanggap sa biyaya,<br/>Puso''y napalaya;<br/>Hapis Mo''y ginunita,<br/>Inaalala Ka.<br/>',NULL,40051,4);
INSERT INTO stanza VALUES('T213','5','Pagdating Mo''y l''walhati,<br/>Tatawagin kami,<br/>Sa araw na maningning,<br/>Mapahinga na rin,<br/>Tinanghal kamatayan,<br/>Mapawangis nawa<br/>Sa I-yong kamatayan<br/>Habang gunita Ka.<br/>',NULL,40052,5);
INSERT INTO stanza VALUES('T214','1','Mabiyaya Mong salita,<br/>Ako''y pakumbaba,<br/>Panginoon, gumagawa,<br/>Nitong pagtatanda.<br/>',NULL,40053,1);
INSERT INTO stanza VALUES('T214','2','Katawan dahil sa akin,<br/>Nagkaputul-putol,<br/>Tipa''y aking iinumin,<br/>Pagkain patungkol.<br/>',NULL,40054,2);
INSERT INTO stanza VALUES('T214','3','Getsemani, malimot ba?<br/>Hirap Mo''y nakita,<br/>Madugong pawis at dusa,<br/>Di Ka maalala?<br/>',NULL,40055,3);
INSERT INTO stanza VALUES('T214','4','Kalbaryo ang aking tingnan,<br/>Sa krus humingalay,<br/>Kordero, di malimutan,<br/>Siyang hain kong tunay.<br/>',NULL,40056,4);
INSERT INTO stanza VALUES('T214','5','Lagi isaisip Kita,<br/>Hirap Mo''t pag-ibig,<br/>Hangga''t taglay ko''ng hininga<br/>Di Ka iwawaglit.<br/>',NULL,40057,5);
INSERT INTO stanza VALUES('T214','6','At kung labi''y tumahimik,<br/>Gunita''y mawala,<br/>Kung kaharian dumating,<br/>Ako''y gunitain.<br/>',NULL,40058,6);
INSERT INTO stanza VALUES('T215','1','Hesus, kasama Ka namin<br/>Sa dulang nakahain,<br/>Nagsasalo sa handaan,<br/>Ika''y pararangalan.<br/>Sandali ay mahalaga,<br/>Sa hapag kapiling Ka;<br/>Tamis ng kapahingahan<br/>Sa Iyo lamang makamtan.<br/>',NULL,40059,1);
INSERT INTO stanza VALUES('T215','2','Ang galak sa Iyong presensya,<br/>Espiritu''y nanguna;<br/>Paggunita namin sa Iyo<br/>Sa dinaloy Mong dugo.<br/>Sagisag tanggapin namin<br/>At Ika''y gunitain:<br/>Katawan Mo ay nawasak,<br/>Sa krus dugo''y dumanak.<br/>',NULL,40060,2);
INSERT INTO stanza VALUES('T215','3','Kay galak, Ika''y makita<br/>Sa sagisag ng b''yaya;<br/>Sa panustos na tinapay,<br/>Alak nakabubuhay!<br/>Masdan Mong nagpulong kami,<br/>Kai-sa Mo''t kabahagi—<br/>Putul-putol na tinapay,<br/>Saro ng pagpapala.<br/>',NULL,40061,3);
INSERT INTO stanza VALUES('T215','4','Hesus, tunay ang pangako,<br/>Sa pulong ay kadalo,<br/>Nagtitipon sa ngalan Mo,<br/>Nagtamasang totoo;<br/>Mahal lalo ang pangako<br/>Sa umaasang puso,<br/>Sumasa-Iyo kami Poon,<br/>Saan Ka man naroon.<br/>',NULL,40062,4);
INSERT INTO stanza VALUES('T220','1','Panginoon, namamangha<br/>Kami sa Iyong hapag;<br/>Isang tinapay, ''sang saro<br/>Na pawang sagisag.<br/>',NULL,40063,1);
INSERT INTO stanza VALUES('T220','2','Tinapay ''nilalarawan,<br/>Pan ng kabuhayan;<br/>''Pinamahagi sa amin<br/>Ng Iyong kamatayan.<br/>',NULL,40064,2);
INSERT INTO stanza VALUES('T220','3','Bahagi''y dibinong saro,<br/>Dugo ni Hesus ''to;<br/>Tinanggap maypalang saro,<br/>Ang Diyos ay natamo.<br/>',NULL,40065,3);
INSERT INTO stanza VALUES('T220','4','Tinapay Kang kinakain,<br/>Kami''y binusog Mo;<br/>Amin Kang gugunitain<br/>Sa pag-ibig sa Iyo.<br/>',NULL,40066,4);
INSERT INTO stanza VALUES('T220','5','Pag-inom namin ng saro,<br/>Kami''y pinagpala;<br/>Hanggang kami''y iakyat Mo,<br/>Naalaala Ka.<br/>',NULL,40067,5);
INSERT INTO stanza VALUES('T220','6','Tinanghal Iyong kamatayan<br/>Ng saro''t tinapay;<br/>Aming pinatotohanan,<br/>Ika''y aming buhay.<br/>',NULL,40068,6);
INSERT INTO stanza VALUES('T220','7','Ang oras na mal''walhati<br/>Hinihintay namin;<br/>Ganap Kang makakapiging,<br/>Aming makakain.<br/>',NULL,40069,7);
INSERT INTO stanza VALUES('T221','1','Panginoon, sa hapag Mo,<br/>Pasalamat ko''y taos;<br/>Sa tinapay at sa saro,<br/>Pagtatamasa''y lubos.<br/>Ang sagisag na tinapay<br/>Katawan Mong in''alay;<br/>Sa dugong Iyong pinadaloy,<br/>Saro ang nagsasaysay.<br/>',NULL,40070,1);
INSERT INTO stanza VALUES('T221','chorus','O, banal na dulang!<br/>Saro at tinapay;<br/>Ang kahuluga''y kay yaman,<br/>Hindi masaysay!<br/>',NULL,40071,2);
INSERT INTO stanza VALUES('T221','2','Sa kamatayang nagtubos<br/>Buhay Mo''y naibigay,<br/>Sarili Mo''y ibinuhos<br/>Nang lahat Mo''y mataglay.<br/>Sa tinapay at sa saro<br/>Kamatayan tinanghal,<br/>Kumain, uminom sa Iyo<br/>Alaala Ka, Mahal.<br/>',NULL,40072,3);
INSERT INTO stanza VALUES('T221','chorus','O, banal na dulang!<br/>Saro at tinapay;<br/>Ang kahuluga''y kay yaman,<br/>Hindi masaysay!<br/>',NULL,40073,4);
INSERT INTO stanza VALUES('T221','3','Ang tinapay sinagisag,<br/>Katawan Mong mistika;<br/>Lahat ng Iyong mga sangkap,<br/>Buklod nagkakaisa.<br/>Sa saro ng pagpapala,<br/>Ating pinagpapala;<br/>Dugo Mo''y may salamuha,<br/>Sa nanampalataya.<br/>',NULL,40074,5);
INSERT INTO stanza VALUES('T221','chorus','O, banal na dulang!<br/>Saro at tinapay;<br/>Ang kahuluga''y kay yaman,<br/>Hindi masaysay!<br/>',NULL,40075,6);
INSERT INTO stanza VALUES('T221','4','Ikaw ang aming bahagi,<br/>Kay tamis nang matikman;<br/>Sa Iyo''y naghihintay kami,<br/>Maging sa kaharian.<br/>Pagdating Mo Iyong kasama,<br/>Mandaraig na banal;<br/>Sa Iyo muli magpipista,<br/>At sa Iyo pakakasal.<br/>',NULL,40076,7);
INSERT INTO stanza VALUES('T221','chorus','O, banal na dulang!<br/>Saro at tinapay;<br/>Ang kahuluga''y kay yaman,<br/>Hindi masaysay!<br/>',NULL,40077,8);
INSERT INTO stanza VALUES('T222','1','Salamat sa tinapay Mo,<br/>Sagisag dibino;<br/>Hesus, nakita ko rito<br/>Mahiwagang plano.<br/>',NULL,40078,1);
INSERT INTO stanza VALUES('T222','2','Tinapay ang katawan Mo<br/>Ibinigay sa ''min,<br/>Bahagi ko ang buhay Mo<br/>At Iyong Sarili rin.<br/>',NULL,40079,2);
INSERT INTO stanza VALUES('T222','3','Katawan Mo ay nabasag,<br/>Ipinamahagi,<br/>Buhay Mo''y aming natanggap,<br/>Nang maging Iyong kasi.<br/>',NULL,40080,3);
INSERT INTO stanza VALUES('T222','4','Katawan Mo ngayo''y naging<br/>Katawang mistiko;<br/>Kami''y buháy na bahaging<br/>Nakiisa sa Iyo.<br/>',NULL,40081,4);
INSERT INTO stanza VALUES('T222','5','Kami''y maraming butil man,<br/>Isang tinapay rin;<br/>Ika''y aming natandaan,<br/>Tustos Ka sa amin.<br/>',NULL,40082,5);
INSERT INTO stanza VALUES('T222','6','Kami''y nakisalamuha<br/>Nang masiyahan Ka;<br/>Mga banal sama-sama,<br/>Yaman Mo''y makita.<br/>',NULL,40083,6);
INSERT INTO stanza VALUES('T223','1','Sa hapag ng pag-ibig,<br/>May tinapay at saro;<br/>Pagbahagi sa tanda,<br/>Ika''y aming ''tamasa.<br/>Sa saro, salamat nga,<br/>Saro ng pagpapala,<br/>Saro ng kaligtasan,<br/>Saro ngang Ika''y tanan.<br/>',NULL,40084,1);
INSERT INTO stanza VALUES('T223','2','Binuhos Mo Iyong dugo,<br/>Nang sala''y mapatawad;<br/>Sa amin ang tipan Mo,<br/>Nang pala''y igawad Mo.<br/>Saro ng poot ay Iyo<br/>Kamatayan lasap Mo,<br/>Pala dala ng saro,<br/>Bahagi kong natamo.<br/>',NULL,40085,2);
INSERT INTO stanza VALUES('T223','3','Diyos nawala ni Adam,<br/>Sa saro''y muling kamtan;<br/>Pagbubo ng Iyong dugo,<br/>Diyos naging biyaya ko.<br/>Katubusan at buhay,<br/>Sa saro''y tinataglay;<br/>Tanang ninais ng Diyos,<br/>Sa saro''y aking lubos.<br/>',NULL,40086,3);
INSERT INTO stanza VALUES('T223','4','Bahaging walang hanggan,<br/>Ang sarong umaapaw;<br/>Makalangit tamasa,<br/>Sa sarong disenyo Niya.<br/>Sa pag-ibig inumin,<br/>Nang Ika''y gunitain;<br/>Tanggapin sa ''spiritu,<br/>Gawa Mo sa Kalbaryo.<br/>',NULL,40087,4);
INSERT INTO stanza VALUES('T224','1','Saro aming bahagi,<br/>Di mapigil papuri;<br/>Para sa ''min binubo,<br/>Mahalaga Mong dugo.<br/>Lahat ng suliranin,<br/>Nilutas ng dugo rin;<br/>Sa dugo Mong mabisa,<br/>Napawi ang pangamba.<br/>',NULL,40088,1);
INSERT INTO stanza VALUES('T224','2','Sa mabisa Mong dugo,<br/>Tipang bago natatag;<br/>Sa mas mabuting tipan,<br/>Pundasyon ay matatag.<br/>Tinubos ng Diyos tayo,<br/>Di ng pilak ni ginto,<br/>Kundi ng dugong mahal,<br/>Sa aki''y nagpabanal.<br/>',NULL,40089,2);
INSERT INTO stanza VALUES('T224','3','Dugo''y ibinuhos Mo,<br/>Upang malinis ako;<br/>Tinugon nang ganap din,<br/>Matutuwid Niyang hiling.<br/>Ang Iyong dugo''y gamitin,<br/>Sala''y lubos linisin;<br/>Ang budhi''y nahugasan,<br/>Diyos buháy paglingkuran.<br/>',NULL,40090,3);
INSERT INTO stanza VALUES('T224','4','Nagbubukod Mong dugo,<br/>Pinababanal ako;<br/>Nagpepreserbang dugo,<br/>Naging patotoo ko.<br/>Pampalubag Mong dugo,<br/>Nabigyang-kat''wiran ''ko;<br/>Dugo Mong mapanubos,<br/>Diyos nasiyahang lubos.<br/>',NULL,40091,4);
INSERT INTO stanza VALUES('T224','5','Dugong dumaloy sa krus,<br/>Nakasundo na ang Diyos;<br/>Nang makaugnay ko Siya,<br/>Sa daang mapayapa.<br/>Pagbahagi sa dugo,<br/>Buhay Mo matamo ko;<br/>Sa dugo at buhay Mo,<br/>Malaya na sa gulo.<br/>',NULL,40092,5);
INSERT INTO stanza VALUES('T224','6','Dugong wisik sa langit,<br/>Higit na bagay banggit;<br/>Dinadaig ng dugo,<br/>Pagtuligsa ng Diyablo.<br/>Sa nanaig Mong dugo,<br/>Kaaway aming talo;<br/>Napagtagumpayan din,<br/>Taga-akusa namin.<br/>',NULL,40093,6);
INSERT INTO stanza VALUES('T224','7','Tunay sa dugong mahal,<br/>Salamuha ng banal;<br/>Sa pagtakip ng dugo,<br/>Malaya ''spiritu ko.<br/>Salaysay ng dugo Mo,<br/>Di kailanman maglaho;<br/>Walang hanggang saysayin,<br/>Ang lahat nitong galing.<br/>',NULL,40094,7);
INSERT INTO stanza VALUES('T226','1','Sa tinapay at saro,<br/>Sa Iyong ipinangako,<br/>Akin Ka nang totoo,<br/>O Poon, salamat.<br/>',NULL,40095,1);
INSERT INTO stanza VALUES('T226','2','Tanging tinapay, saro,<br/>Sa panalig ''batid ko,<br/>Mga tandang dibino,<br/>O Poon, salamat.<br/>',NULL,40096,2);
INSERT INTO stanza VALUES('T226','3','Salitang nagpabaling<br/>Sa Kalbaryo, paningin,<br/>Lumapit, nagtiwala,<br/>O Poon, salamat.<br/>',NULL,40097,3);
INSERT INTO stanza VALUES('T226','4','Hininga Mong salita,<br/>Sa sagisag nakita.<br/>Kapayapaan mana,<br/>O Poon, salamat.<br/>',NULL,40098,4);
INSERT INTO stanza VALUES('T226','5','Sa salita''y nabatid,<br/>Inihayag Iyong nais,<br/>"Gawin hanggang pagdating,"<br/>O Poon, salamat.<br/>',NULL,40099,5);
INSERT INTO stanza VALUES('T226','6','Hanggang sa Iyong pagdating,<br/>Tinapay kakainin,<br/>Ika''y gugunitain,<br/>O Poon, salamat.<br/>',NULL,40100,6);
INSERT INTO stanza VALUES('T226','7','Hanggang sa pagbalik Mo,<br/>Iinuman Iyong saro,<br/>Mata, puso sumigla,<br/>O Poon, salamat.<br/>',NULL,40101,7);
INSERT INTO stanza VALUES('T226','8','Para sa pagdating Mo,<br/>Araw na di matanto,<br/>Sa luwalhati''t trono,<br/>O Poon, salamat.<br/>',NULL,40102,8);
INSERT INTO stanza VALUES('T227','1','Sa tinapay at sa saro<br/>Kamatayan Mo''y hayag,<br/>Ang pag-ibig at gawa Mo,<br/>Halaga''y ibinunyag.<br/>Tinapay bukod sa saro,<br/>Tinanghal kamatayan,<br/>Sasamba ang espiritu,<br/>Ikaw ay papurihan.<br/>',NULL,40103,1);
INSERT INTO stanza VALUES('T227','chorus','Pagdurusa sa Iyo,<br/>Ang biyaya''y akin,<br/>Pag-ibig sa pagtubos Mo<br/>Dapat purihin!<br/>',NULL,40104,2);
INSERT INTO stanza VALUES('T227','2','Nagmahal at nagdugo Ka,<br/>Nang ako''y mapasa-Diyos,<br/>Ang hadlang ay inalis na,<br/>Diyos makita kong lubos.<br/>Kat''wiran, kal''walhatian,<br/>Natupad kahilingan,<br/>Dahil sa Iyong kamatayan,<br/>Sa Diyos makakatahan.<br/>',NULL,40105,3);
INSERT INTO stanza VALUES('T227','chorus','Pagdurusa sa Iyo,<br/>Ang biyaya''y akin,<br/>Pag-ibig sa pagtubos Mo<br/>Dapat purihin!<br/>',NULL,40106,4);
INSERT INTO stanza VALUES('T227','3','Tabing lampasan patungo<br/>Sa kabanal-banalan,<br/>Namatay Ka''t binuksan Mo<br/>Daan sa Iyong luklukan;<br/>Matamo biyaya''t awa,<br/>Siyang tulong sa kailangan,<br/>Inumin tubig ng buhay,<br/>Kamtin ang Kanyang yaman.<br/>',NULL,40107,5);
INSERT INTO stanza VALUES('T227','chorus','Pagdurusa sa Iyo,<br/>Ang biyaya''y akin,<br/>Pag-ibig sa pagtubos Mo<br/>Dapat purihin!<br/>',NULL,40108,6);
INSERT INTO stanza VALUES('T227','4','Dahil sa Iyong katubusan,<br/>Saserdote na ako,<br/>Natamasa ko Iyong yaman,<br/>Diyos paglilingkuran ko.<br/>Bunga ng kamatayan Mo—<br/>Pagpapala''t biyaya;<br/>Hanggang sa pagbabalik Mo,<br/>Gugunitain Kita.<br/>',NULL,40109,7);
INSERT INTO stanza VALUES('T227','chorus','Pagdurusa sa Iyo,<br/>Ang biyaya''y akin,<br/>Pag-ibig sa pagtubos Mo<br/>Dapat purihin!<br/>',NULL,40110,8);
INSERT INTO stanza VALUES('T228','1','Matamis na pista,<br/>Mula sa biyaya,<br/>Pan at saro tinamasa,<br/>Ika''y ginunita.<br/>',NULL,40111,1);
INSERT INTO stanza VALUES('T228','2','Dito nais namin,<br/>Sa Iyo unawain,<br/>Layon ng puso ng Ama,<br/>Bigay Mong biyaya.<br/>',NULL,40112,2);
INSERT INTO stanza VALUES('T228','3','Budhi''y natahimik,<br/>Puspos ng pag-ibig,<br/>Tamis, Tinapay ng Buhay,<br/>Nas''yahang patunay.<br/>',NULL,40113,3);
INSERT INTO stanza VALUES('T228','4','Sa simbolo''y kita<br/>Dugong umagos nga,<br/>Sa pangakong pinagpala,<br/>Kami''y inibig nga.<br/>',NULL,40114,4);
INSERT INTO stanza VALUES('T228','5','Ngayo''y matamis na,<br/>Tikim ng pagsinta;<br/>Sa taas, ano pa kaya,<br/>Pag tayo''y nagkita!<br/>',NULL,40115,5);
INSERT INTO stanza VALUES('T228','6','Mamamasdan ko na<br/>Iyong mukhang may gloria,<br/>Lahat daang biyaya Mo,<br/>Aking patotoo.<br/>',NULL,40116,6);
INSERT INTO stanza VALUES('T233','1','Mahimala, Panginoon,<br/>Na kata ay nagkaisa,<br/>Ako''y sa Iyo, Ika''y sa ''kin,<br/>Kamangha-manghang hiwaga!<br/>',NULL,40117,1);
INSERT INTO stanza VALUES('T233','2','Buhay Mo''y sinakripisyo<br/>Nang maging sangkap Mo ako;<br/>Sa krus Ikaw ay nagdugo,<br/>Sa sala ako''y hinango.<br/>',NULL,40118,2);
INSERT INTO stanza VALUES('T233','3','Sa pagkabuhay na muli,<br/>Bilang Espiritu ngayon,<br/>Pumasok Ka''t ibahagi<br/>Lahat Mong yaman, Pangino''n.<br/>',NULL,40119,3);
INSERT INTO stanza VALUES('T233','4','Inalaala Ka namin<br/>Sa sagisag nasa mesa,<br/>Salamat sa Iyong layunin,<br/>At sa dinanas Mong dusa.<br/>',NULL,40120,4);
INSERT INTO stanza VALUES('T233','5','Hatid ng saro''t tinapay<br/>Katamisan ng Iyong tustos,<br/>Sa espiritu ''binigay<br/>Ang pagtatamasang lubos.<br/>',NULL,40121,5);
INSERT INTO stanza VALUES('T233','6','Kumain, uminom nawa,<br/>Hanggang sa mapuspusan na<br/>Sa ''spiritu ng Iyong mana,<br/>Tunay Kang ginugunita.<br/>',NULL,40122,6);
INSERT INTO stanza VALUES('T235','1','Purihin Siya! Hesus ating Manunubos!<br/>Awitin ang pag-ibig Niyang sakdal!<br/>Purihin Siya! mga anghel sa l''walhati,<br/>Sa ngalan Niya ay lakas at dangal.<br/>Tulad ng pastol Siya''ng mag-aalaga,<br/>Sa Kanyang bayan na kapiling Niya,<br/>O kayong banal nasa kaliwanagan,<br/>Purihin Siya! nang magpakailanman.<br/>',NULL,40123,1);
INSERT INTO stanza VALUES('T235','2','Purihin Siya! Hesus ating Manunubos,<br/>Nang dahil sa atin Siya''y nagdugo,<br/>Siya ang ating Pag-asa at kaligtasan,<br/>Purihin! Hesus, sa krus pinako;<br/>Manliligtas nagbata ng kalungkutan,<br/>Koronang tinik, Siya''y pinutungan!<br/>Dinusta''t itinakwil dahil sa atin,<br/>Hari ng l''walhati, Siya''y purihin!<br/>',NULL,40124,2);
INSERT INTO stanza VALUES('T235','3','Purihin Siya! Hesus ating Manunubos,<br/>Pagbubunyi ng hosana''y laksan!<br/>Hesus, naghahari nang magpakailanman,<br/>Saserdote''t Hari! Siya''y putungan!<br/>Ipagbunyi nilupig kamatayan,<br/>Saan ang tagumpay mo, libingan?<br/>Si Hesus nabubuhay magpakailanman;<br/>Si Hesus ang liligtas sa tanan.<br/>',NULL,40125,3);
INSERT INTO stanza VALUES('T240','1','Gloria, puri, karangalan,<br/>Sa Kordero walang hanggan!<br/>Hesu-Kristo, Manunubos,<br/>Aleluya! Aleluya!<br/>Aleluya! Purihin Siya!<br/>',NULL,40126,1);
INSERT INTO stanza VALUES('T241','1','Papuri, dangal, at luwalhati<br/>Ay pawang sa Iyo,<br/>Ay pawang sa Iyo.<br/>Papuri, dangal, at luwalhati<br/>Nang magpakailanman.<br/>Purihin Siya!<br/>Magpuri, mga banal.<br/>Purihin Siya!<br/>Nang magpakailanman.<br/>Aleluya!<br/>Papuri, dangal, at luwalhati<br/>Ay pawang sa Iyo,<br/>Ay pawang sa Iyo.<br/>Papuri, dangal, at luwalhati<br/>Nang magpakailanman.<br/>',NULL,40127,1);
INSERT INTO stanza VALUES('T242','1','Ngayon ang Espiritu ng Diyos,<br/>Ay Espiritu na ni Hesus,<br/>Diyos-taong namatay, nabuhay,<br/>Umakyat sa gloria Niya.<br/>',NULL,40128,1);
INSERT INTO stanza VALUES('T242','2','Mula sa umakyat na Hesus,<br/>''Spiritung ito sa ''kin pumasok,<br/>Nang lahat Niyang katotohanan;<br/>Maging lahat kong karanasan.<br/>',NULL,40129,2);
INSERT INTO stanza VALUES('T242','3','Ang Espiritu ni Hesus,<br/>May Diyos, taong elemento;<br/>Diyos at tao, dalawang likas,<br/>Gloria Niya''t buhay bakas.<br/>',NULL,40130,3);
INSERT INTO stanza VALUES('T242','4','Dusa ng pantaong buhay,<br/>Kapangyarihan ng pagkabuhay<br/>Kanyang pagbangon, paghari nga<br/>Sa ''Spiritung hininga.<br/>',NULL,40131,4);
INSERT INTO stanza VALUES('T242','5','Sa mga elementong ito<br/>Kumilos Siya sa espiritu ko<br/>Sa pagpapahid ng unggwento<br/>Yaman Niya naging tamasa ko.<br/>',NULL,40132,5);
INSERT INTO stanza VALUES('T242','6','Espiritu ni Hesus,<br/>Dakila''t dukha''y yapos;<br/>Sa bawa''t panig kumikilos<br/>Nang maging lahat natin ang Diyos.<br/>',NULL,40133,6);
INSERT INTO stanza VALUES('T243','1','Espiritu ng Diyos ngayon,<br/>Ay kay Kristong Panginoon,<br/>''Spiritu ng realidad,<br/>Buhay sa akin at tunay.<br/>',NULL,40134,1);
INSERT INTO stanza VALUES('T243','2','Kristo ay Diyos naging tao,<br/>Nahayag buhay dibino;<br/>Gayon ''Spiritu kay Kristo,<br/>Hinayag Niyang buhay ito.<br/>',NULL,40135,2);
INSERT INTO stanza VALUES('T243','3','Kapuspusan ng Diyos Ama,<br/>Kay Kristo nagsakatawan,<br/>Lahat ng yaman ng Anak,<br/>Espiritu, realidad.<br/>',NULL,40136,3);
INSERT INTO stanza VALUES('T243','4','Ama''y sa loob ng Anak,<br/>Ngayon ''Spiritu''y ang Anak;<br/>Nakaugpong Ama''t Anak,<br/>''Spiritu kai-sa ng Anak.<br/>',NULL,40137,4);
INSERT INTO stanza VALUES('T243','5','Pinalakas ng ''Spiritu,<br/>Puso''y tahanan ni Kristo;<br/>Pag-ibig Niya''t kapuspusan,<br/>Buong katauhan pun''an.<br/>',NULL,40138,5);
INSERT INTO stanza VALUES('T243','6','Kay Kristo, Ama ay angkin,<br/>Sa kailangan Siya''y tanggapin;<br/>Sa ''Spiritu naranasan,<br/>Kristo bilang buhay, tanan.<br/>',NULL,40139,6);
INSERT INTO stanza VALUES('T243','7','Gamitin realidad Mo,<br/>Espiritu pun''an ako;<br/>Babaran akong lubusan,<br/>Aking tamasa''y Iyong yaman.<br/>',NULL,40140,7);
INSERT INTO stanza VALUES('T244','1','Ngayon ang ''Spiritu Santo,<br/>''Spiritung buhay dibino,<br/>Bumuhay at nagpasigla,<br/>Nang sa layon Niya''y tumugma.<br/>',NULL,40141,1);
INSERT INTO stanza VALUES('T244','2','Tubig ng buhay sa uhaw,<br/>Agos ng buhay ay Ikaw;<br/>Buhay dibino si Kristo,<br/>Dulot sa puso''y lugod Mo.<br/>',NULL,40142,2);
INSERT INTO stanza VALUES('T244','3','Ilaw ng buhay sumilay,<br/>Dilim sa ''kin humiwalay;<br/>Si Kristo dibinong ilaw,<br/>Nang gabi ko''y maging araw.<br/>',NULL,40143,3);
INSERT INTO stanza VALUES('T244','4','Sa lakas ng Kanyang buhay,<br/>Taong panloob tumibay;<br/>Lakas dibino si Kristo,<br/>Kumilos sa Kanyang plano.<br/>',NULL,40144,4);
INSERT INTO stanza VALUES('T244','5','Dahil sa utos ng buhay,<br/>Laya sa utos ng sala;<br/>Sa dibinong kalikasan,<br/>Ako ay naregulahan.<br/>',NULL,40145,5);
INSERT INTO stanza VALUES('T244','6','Espiritu ng buhay Siya,<br/>Sa atin nagpapabunga;<br/>Nahayag katangian Niya,<br/>Sa buhay binahagi Siya.<br/>',NULL,40146,6);
INSERT INTO stanza VALUES('T244','7','Ang Espiritu ng buhay,<br/>Gawa''y magtustos ng buhay;<br/>Nagtransporma, nagpabago,<br/>Nang mapawangis kay Kristo.<br/>',NULL,40147,7);
INSERT INTO stanza VALUES('T244','8','Gamitin Mo, Panginoon,<br/>''Spiritu ng buhay ngayon,<br/>Lubusang puspusin ako<br/>Nang buhay ko''y mapuno Mo.<br/>',NULL,40148,8);
INSERT INTO stanza VALUES('T245','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40149,1);
INSERT INTO stanza VALUES('T245','1','Saan man may tao, balita''y ikalat,<br/>Kung sa''n puso''t lungkot ng tao laganap;<br/>Bawa''t Kristiyano, buong galak maghayag:<br/>Mang-a''liw narito!<br/>',NULL,40150,2);
INSERT INTO stanza VALUES('T245','chorus','Mang-a''liw narito! Mang-a''liw narito!<br/>Ipinangako na Espiritu Santo!<br/>Mabuting balita, ikalat sa mundo,<br/>Mang-a''liw narito!<br/>',NULL,40151,3);
INSERT INTO stanza VALUES('T245','2','Mahabang gabi lumipas umaga na,<br/>Pagtangis nahinto maging ang pagluha;<br/>Mga gintong bundok nagpapakita na—<br/>Mang-a''liw narito!<br/>',NULL,40152,4);
INSERT INTO stanza VALUES('T245','chorus','Mang-a''liw narito! Mang-a''liw narito!<br/>Ipinangako na Espiritu Santo!<br/>Mabuting balita, ikalat sa mundo,<br/>Mang-a''liw narito!<br/>',NULL,40153,5);
INSERT INTO stanza VALUES('T245','3','Lunas ay dala ng liwanag ng Hari,<br/>Laya para sa bawa''t bihag at api;<br/>Sa hungkag na selda, dumagsa papuri:<br/>Mang-a''liw narito!<br/>',NULL,40154,6);
INSERT INTO stanza VALUES('T245','chorus','Mang-a''liw narito! Mang-a''liw narito!<br/>Ipinangako na Espiritu Santo!<br/>Mabuting balita, ikalat sa mundo,<br/>Mang-a''liw narito!<br/>',NULL,40155,7);
INSERT INTO stanza VALUES('T245','4','Pag-ibig ng ''Spiritu di mabigkas ko,<br/>Sa mga tao sabihing biyaya Mo,<br/>Naging Iyong kasama, ang maysalang ako!<br/>Mang-a''liw narito!<br/>',NULL,40156,8);
INSERT INTO stanza VALUES('T245','chorus','Mang-a''liw narito! Mang-a''liw narito!<br/>Ipinangako na Espiritu Santo!<br/>Mabuting balita, ikalat sa mundo,<br/>Mang-a''liw narito!<br/>',NULL,40157,9);
INSERT INTO stanza VALUES('T245','5','Hanggang may pagtugon, laksan ang pag-awit,<br/>Nangagsiawit mga anghel sa langit;<br/>Pag-ibig kay tamis, papuri ko''y higit:<br/>Mang-a''liw narito!<br/>',NULL,40158,10);
INSERT INTO stanza VALUES('T245','chorus','Mang-a''liw narito! Mang-a''liw narito!<br/>Ipinangako na Espiritu Santo!<br/>Mabuting balita, ikalat sa mundo,<br/>Mang-a''liw narito!<br/>',NULL,40159,11);
INSERT INTO stanza VALUES('T250','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40160,1);
INSERT INTO stanza VALUES('T250','1','Oh balón, bumalong!<br/>Ako ay mahukay,<br/>Nang makasusulong<br/>Ang tubig ng buhay!<br/>',NULL,40161,2);
INSERT INTO stanza VALUES('T250','2','Bato''y nabiyak na,<br/>Tubig ay bumubo;<br/>Nguni''t may bara pa<br/>Nasa aking puso.<br/>',NULL,40162,3);
INSERT INTO stanza VALUES('T250','3','Ako''y manalangin,<br/>Bara ay hukayin;<br/>Espiritu sa ''kin<br/>Laging paagusin.<br/>',NULL,40163,4);
INSERT INTO stanza VALUES('T250','4','Tuloy ang dalangin,<br/>Tuloy ang paghukay!<br/>Paghukay lubusin,<br/>Dalangi''y masanay.<br/>',NULL,40164,5);
INSERT INTO stanza VALUES('T250','5','Bato''y di buksan na,<br/>Ako''y hukayin Mo;<br/>Tubig lumabas na,<br/>Paaagusin ko.<br/>',NULL,40165,6);
INSERT INTO stanza VALUES('T250','6','''Spiritung dumapo<br/>Ay tanging pagbuhos;<br/>''Spiritu sa puso<br/>Ay bukal ng agos.<br/>',NULL,40166,7);
INSERT INTO stanza VALUES('T250','7','Pinakakailangan<br/>Di pagbuhos lamang,<br/>Dalangi''y paraan,<br/>Bukal ay mabuksan.<br/>',NULL,40167,8);
INSERT INTO stanza VALUES('T250','8','Hadlang sa ''Spiritu,<br/>Tanggal sa paghukay,<br/>Batis na bumubo—<br/>Ay ilog ng buhay!<br/>',NULL,40168,9);
INSERT INTO stanza VALUES('T250','9','O balón, bumalong!<br/>Ako ay mahukay<br/>Nang makasusulong<br/>Ang tubig ng buhay!<br/>',NULL,40169,10);
INSERT INTO stanza VALUES('T251','1','Mga ilog ng buhay,<br/>Sa trono bumubukal;<br/>Ilog pagpapala''y dalhin,<br/>Buhat kay Hesus sa ''kin.<br/>',NULL,40170,1);
INSERT INTO stanza VALUES('T251','chorus','Mga ilog na buháy,<br/>Ipinamimigay;<br/>Dumaan nawa sa ''kin,<br/>Tanang uhaw lutasin.<br/>',NULL,40171,2);
INSERT INTO stanza VALUES('T251','2','Lapit sinumang uhaw<br/>Sa tubig na malinaw;<br/>Walang bayad mong tanggapin,<br/>Nang buhay iyong taglayin.<br/>',NULL,40172,3);
INSERT INTO stanza VALUES('T251','chorus','Mga ilog na buháy,<br/>Ipinamimigay;<br/>Dumaan nawa sa ''kin,<br/>Tanang uhaw lutasin.<br/>',NULL,40173,4);
INSERT INTO stanza VALUES('T251','3','Hesus, linisin ako,<br/>Nang maging daluyan Mo,<br/>Basyuhin, punuin ako,<br/>Sumunod turuan Mo.<br/>',NULL,40174,5);
INSERT INTO stanza VALUES('T251','chorus','Mga ilog na buháy,<br/>Ipinamimigay;<br/>Dumaan nawa sa ''kin,<br/>Tanang uhaw lutasin.<br/>',NULL,40175,6);
INSERT INTO stanza VALUES('T251','4','Sa oras na iyon lamang,<br/>Madadaluyan ako;<br/>Sa ganito ring paraan,<br/>Batid Iyong kapuspusan.<br/>',NULL,40176,7);
INSERT INTO stanza VALUES('T251','chorus','Mga ilog na buháy,<br/>Ipinamimigay;<br/>Dumaan nawa sa ''kin,<br/>Tanang uhaw lutasin.<br/>',NULL,40177,8);
INSERT INTO stanza VALUES('T251','5','Inihandog ko''ng tanan,<br/>Nasa Kanyang paanan;<br/>Iisa lang ang naisin,<br/>Sa paglingkod gamitin.<br/>',NULL,40178,9);
INSERT INTO stanza VALUES('T251','chorus','Mga ilog na buháy,<br/>Ipinamimigay;<br/>Dumaan nawa sa ''kin,<br/>Tanang uhaw lutasin.<br/>',NULL,40179,10);
INSERT INTO stanza VALUES('T254','1','Hipan Mo, Poon ng buhay,<br/>Sa dalangin ay gumalaw;<br/>Batis Ka ng bagong buhay,<br/>Liwanag ng bagong araw.<br/>',NULL,40180,1);
INSERT INTO stanza VALUES('T254','2','Kami ay kaisa sa Iyo,<br/>Di na dapat pang hanapin;<br/>Naririnig ang tinig Mo,<br/>Sa ''spiritu''y kaniigin.<br/>',NULL,40181,2);
INSERT INTO stanza VALUES('T254','3','Manananggol sa itaas,<br/>Gayundin sa aming loob;<br/>Katotohanan ang lunas,<br/>Sa kasalanan ang sagot.<br/>',NULL,40182,3);
INSERT INTO stanza VALUES('T254','4','Nguni''t di tapat puso ko!<br/>Bagama''t alam, sumuway;<br/>Nawa''y hipan ng ''Spiritu,<br/>Nang sumunod sa Iyong gabay.<br/>',NULL,40183,4);
INSERT INTO stanza VALUES('T254','5','Nang walang nakaunawa,<br/>Ako''y Iyong samahan, Giliw;<br/>''Pag may takot, nais Kita<br/>Makilalang Mang-aaliw.<br/>',NULL,40184,5);
INSERT INTO stanza VALUES('T255','1','Ako''y hipan ng ''Spiritu,<br/>Turuan Mong lumanghap;<br/>Tulungang ilagak sa Iyo,<br/>Buhay ng sala''t hirap.<br/>',NULL,40185,1);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40186,2);
INSERT INTO stanza VALUES('T255','2','Ihinga ko aking buhay<br/>Nang ako''y mapuspusan;<br/>Limutin lakas at hinay,<br/>Langhapin ang Iyong buhay.<br/>',NULL,40187,3);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40188,4);
INSERT INTO stanza VALUES('T255','3','Ihinga ang kasalanan,<br/>Lahat ay Iyong pinasan;<br/>Langhapin Iyong kalinisan,<br/>Buhay ko''y masumpungan.<br/>',NULL,40189,5);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40190,6);
INSERT INTO stanza VALUES('T255','4','Ihinga ang kalungkutan<br/>Sa dibdib Mong magiliw;<br/>Langhapin kapayapaan,<br/>Ang galak Mo at aliw.<br/>',NULL,40191,7);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40192,8);
INSERT INTO stanza VALUES('T255','5','Ihinga mga sakit ko,<br/>Pinasan Mo ring panay;<br/>Langhapin ang paggamot Mo,<br/>Pahinga Iyong ''binigay.<br/>',NULL,40193,9);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40194,10);
INSERT INTO stanza VALUES('T255','6','Ihinga ang kasabikan<br/>Sa mahal Mong pandinig;<br/>Langhapin Iyong kasagutan,<br/>Tigil ang panginginig.<br/>',NULL,40195,11);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40196,12);
INSERT INTO stanza VALUES('T255','7','Lumanghap bawa''t segundo,<br/>Buhay Mo ay buhay ko;<br/>Bawa''t hininga''y bigay Mo,<br/>Hipan ng Espiritu.<br/>',NULL,40197,13);
INSERT INTO stanza VALUES('T255','chorus','Ihinga nang palabas ang<br/>Sala at lumbay;<br/>Langhapin Iyong kapuspusan,<br/>Langhaping tunay.<br/>',NULL,40198,14);
INSERT INTO stanza VALUES('T256','1','O hipan Mo kami, habang naghihintay;<br/>Lakas ng hangin Mo, laya''y ibibigay;<br/>Hipan Mo hanggang sa kami''y mabubuhay;<br/>Hipan kami, Panginoon!<br/>',NULL,40199,1);
INSERT INTO stanza VALUES('T256','chorus','Panginoon, kami''y hipan!<br/>Iyong alisin katamaran!<br/>Hangin Mo''y dumating,<br/>Pag-urong wakasan,<br/>Panginoon, kami''y hipan!<br/>',NULL,40200,2);
INSERT INTO stanza VALUES('T256','2','Hipan ng pag-ibig, puso kong malamig,<br/>Sa buong kalul''wa, hanging makalangit;<br/>Hipan hanggang kami''y lubusang uminit;<br/>Hipan kami, Panginoon!<br/>',NULL,40201,3);
INSERT INTO stanza VALUES('T256','chorus','Panginoon, kami''y hipan!<br/>Iyong alisin katamaran!<br/>Hangin Mo''y dumating,<br/>Pag-urong wakasan,<br/>Panginoon, kami''y hipan!<br/>',NULL,40202,4);
INSERT INTO stanza VALUES('T256','3','Hipan Mo nang lubos, ''spiritu''y lalakas,<br/>Buhayin, puspusin kami ng Iyong atas;<br/>Hipan hanggang kami''y pawang nagniningas;<br/>Hipan kami, Panginoon!<br/>',NULL,40203,5);
INSERT INTO stanza VALUES('T256','chorus','Panginoon, kami''y hipan!<br/>Iyong alisin katamaran!<br/>Hangin Mo''y dumating,<br/>Pag-urong wakasan,<br/>Panginoon, kami''y hipan!<br/>',NULL,40204,6);
INSERT INTO stanza VALUES('T257','1','Hanging makalangit, Poon,<br/>Kami''y hipan ngayon!<br/>Mapagpanauling lakas,<br/>Sa amin mahayag.<br/>',NULL,40205,1);
INSERT INTO stanza VALUES('T257','chorus','Makapangyarihang Poon,<br/>Kami''y hipan ngayon<br/>Ng Espiritu Mong taglay,<br/>Dala''y agos buhay!<br/>',NULL,40206,2);
INSERT INTO stanza VALUES('T257','2','Malakas Mong Espiritu,<br/>Hipan aming hadlang;<br/>Espiritu''y hipan kami,<br/>Amin Kang bahagi.<br/>',NULL,40207,3);
INSERT INTO stanza VALUES('T257','3','Ang pitong ulit na yaman,<br/>Ng ''Spiritu''y kamtan;<br/>Nawa aming maranasan<br/>Ang Diyos na Tres-uno.<br/>',NULL,40208,5);
INSERT INTO stanza VALUES('T260','1','Bubuhos ang pagpapala:<br/>Pangako ng pagsinta;<br/>Ginhawang buhat sa ''taas,<br/>Hatid ng Manliligtas.<br/>',NULL,40209,1);
INSERT INTO stanza VALUES('T260','chorus','Kami''y buhusan,<br/>Pagpapalang mayaman;<br/>Di patak ng awa lamang,<br/>Bagkus buhos ng ulan.<br/>',NULL,40210,2);
INSERT INTO stanza VALUES('T260','2','Uulan ng pagpapala—<br/>O panauling lubos;<br/>Sa burol, lambak — aagos<br/>Ulan na masagana.<br/>',NULL,40211,3);
INSERT INTO stanza VALUES('T260','chorus','Kami''y buhusan,<br/>Pagpapalang mayaman;<br/>Di patak ng awa lamang,<br/>Bagkus buhos ng ulan.<br/>',NULL,40212,4);
INSERT INTO stanza VALUES('T260','3','May pagpapalang bubuhos;<br/>Kami''y padalhan, O Diyos!<br/>Bigyang pagpapanariwa,<br/>Tupdin ang Iyong Salita.<br/>',NULL,40213,5);
INSERT INTO stanza VALUES('T260','chorus','Kami''y buhusan,<br/>Pagpapalang mayaman;<br/>Di patak ng awa lamang,<br/>Bagkus buhos ng ulan.<br/>',NULL,40214,6);
INSERT INTO stanza VALUES('T260','4','May pagpapalang bubuhos;<br/>Nawa ngayon ibuhos;<br/>Habang sa Diyos nagpahayag,<br/>Kay Hesus tumatawag!<br/>',NULL,40215,7);
INSERT INTO stanza VALUES('T260','chorus','Kami''y buhusan,<br/>Pagpapalang mayaman;<br/>Di patak ng awa lamang,<br/>Bagkus buhos ng ulan.<br/>',NULL,40216,8);
INSERT INTO stanza VALUES('T260','5','May pagpapalang bubuhos;<br/>Magtiwala''t sumunod;<br/>Mayroong kaginhawahan,<br/>Kung Diyos ay bigyang-daan.<br/>',NULL,40217,9);
INSERT INTO stanza VALUES('T260','chorus','Kami''y buhusan,<br/>Pagpapalang mayaman;<br/>Di patak ng awa lamang,<br/>Bagkus buhos ng ulan.<br/>',NULL,40218,10);
INSERT INTO stanza VALUES('T262','1','Taas kamay humiling,<br/>''Spiritu''y paratingin;<br/>Mula Ama sa Anak,<br/>Gloria ngayon makita.<br/>',NULL,40219,1);
INSERT INTO stanza VALUES('T262','chorus','''Spiritu, paratingin,<br/>Dakilang gawa''y tupdin;<br/>Bigyang-siya kaluluwa,<br/>Naghintay sa apoy nga,<br/>Naghihintay,<br/>Sa apoy naghihintay.<br/>',NULL,40220,2);
INSERT INTO stanza VALUES('T262','2','Paghain sa dambana,<br/>Katawan, kaluluwa;<br/>Tanang pita tupukin,<br/>Bawa''t sulok punuin.<br/>',NULL,40221,3);
INSERT INTO stanza VALUES('T262','chorus','''Spiritu, paratingin,<br/>Dakilang gawa''y tupdin;<br/>Bigyang-siya kaluluwa,<br/>Naghintay sa apoy nga,<br/>Naghihintay,<br/>Sa apoy naghihintay.<br/>',NULL,40222,4);
INSERT INTO stanza VALUES('T262','3','Sinakripisyo namin<br/>Ang aming tanging buhay,<br/>Para sa Manliligtas<br/>Na nagdugo''t namatay.<br/>',NULL,40223,5);
INSERT INTO stanza VALUES('T262','chorus','''Spiritu, paratingin,<br/>Dakilang gawa''y tupdin;<br/>Bigyang-siya kaluluwa,<br/>Naghintay sa apoy nga,<br/>Naghihintay,<br/>Sa apoy naghihintay.<br/>',NULL,40224,6);
INSERT INTO stanza VALUES('T262','4','Sa pananalig tamo,<br/>Handog, bili ng dugo;<br/>Sa Ngalang mapanaig,<br/>Pangakong lahat angkin.<br/>',NULL,40225,7);
INSERT INTO stanza VALUES('T262','chorus','''Spiritu, paratingin,<br/>Dakilang gawa''y tupdin;<br/>Bigyang-siya kaluluwa,<br/>Naghintay sa apoy nga,<br/>Naghihintay,<br/>Sa apoy naghihintay.<br/>',NULL,40226,8);
INSERT INTO stanza VALUES('T264','1','Matagumpay Mong pagsinta,<br/>Sa aki''y ''binuhos;<br/>Puso ko''y di na gagala,<br/>Mauugat sa Diyos,<br/>Mauugat sa Diyos.<br/>',NULL,40227,1);
INSERT INTO stanza VALUES('T264','2','O banal na apoy, nawa<br/>Sa aki''y magningas;<br/>Sunugin ang pita''t nasa,<br/>Sa tayog iligtas,<br/>Sa tayog iligtas.<br/>',NULL,40228,2);
INSERT INTO stanza VALUES('T264','3','O apoy ng Pentecostes,<br/>Sala ko''y tupukin!<br/>Tawag Espiritu Santo,<br/>Parito ''Spiritu!<br/>Parito ''Spiritu!<br/>',NULL,40229,3);
INSERT INTO stanza VALUES('T264','4','Apoy Mo ay dalisayin,<br/>Puso ko''t kalul''wa;<br/>Buhay Mo''y palaganapin,<br/>Pabanalin ako,<br/>Pabanalin ako.<br/>',NULL,40230,4);
INSERT INTO stanza VALUES('T264','5','Matatag kaluluwa ko,<br/>Di natitigatig;<br/>Ang daigdig ko''y si Kristo,<br/>Puso ko''y pag-ibig,<br/>Puso ko''y pag-ibig.<br/>',NULL,40231,5);
INSERT INTO stanza VALUES('T265','1','Sa nawisikan ng dugo,<br/>Nanatili ungguwento;<br/>Diyos, tao nagsalamuha,<br/>Ugnayan, napreserba.<br/>',NULL,40232,1);
INSERT INTO stanza VALUES('T265','2','Dugo''y tanda ng pagtubos,<br/>Sala''y nilinis lubos;<br/>Ungguwento''y ''Spiritu naman,<br/>Nang Diyos ating makamtan.<br/>',NULL,40233,2);
INSERT INTO stanza VALUES('T265','3','Dugo''y hayag gawa ng Diyos,<br/>Ungguwento sa ''tin ang Diyos;<br/>Sa Kanyang gawa''t persona,<br/>Sa atin nahalo Siya.<br/>',NULL,40234,3);
INSERT INTO stanza VALUES('T265','4','Sa paglinis ng dugo Niya,<br/>Nilinis na ang sala;<br/>Sa pagpahid ng ''Spiritu<br/>Tamasa ko''y Diyos Mismo.<br/>',NULL,40235,4);
INSERT INTO stanza VALUES('T265','5','Sa paglinis at pagpahid,<br/>Diyos kaisa kong lagi;<br/>Sa dugo at sa ungguwento,<br/>Diyos bahagi kong buo.<br/>',NULL,40236,5);
INSERT INTO stanza VALUES('T265','6','Sa pananalig angkin ko,<br/>Paglilinis ng dugo;<br/>Sa pagpahid tumalima,<br/>Mamuhay Diyos kasama.<br/>',NULL,40237,6);
INSERT INTO stanza VALUES('T265','7','Diyos kilanlin at danasin,<br/>Liwanag, pag-ibig din;<br/>Diyos lumago bilang buhay,<br/>Lakas ng Diyos patunay.<br/>',NULL,40238,7);
INSERT INTO stanza VALUES('T266','1','Ang pagpapahid nananahan<br/>Sa aking espiritu;<br/>Itinuturo lahat ng bagay,<br/>Nang maibuhay Kristo!<br/>',NULL,40239,1);
INSERT INTO stanza VALUES('T266','chorus','Pagpapahid ay nananahan,<br/>Sa ''king espiritu,<br/>Siya ay nagtuturo;<br/>Sa espiritu nananahan,<br/>At ako''y tinuturuan.<br/>',NULL,40240,2);
INSERT INTO stanza VALUES('T266','2','Ang pagkilos ng Espiritu,<br/>Banayad na ungguwento;<br/>Batay sa paglilinis ng dugo,<br/>Pagpapahid natamo.<br/>',NULL,40241,3);
INSERT INTO stanza VALUES('T266','3','Esensya ng Diyos pinapahid<br/>Upang Diyos makilala,<br/>Nang elemento ng Diyos makamtan<br/>At ako''y matigmak Niya.<br/>',NULL,40242,5);
INSERT INTO stanza VALUES('T266','4','Sa panloob na pagpapahid,<br/>Makipagsalamuha;<br/>Sa loob ng Diyos ''ko''y lumalakad,<br/>Natalos ang biyaya.<br/>',NULL,40243,7);
INSERT INTO stanza VALUES('T267','1','Mabiyayang Espiritu,<br/>Ngayon puspusin ako;<br/>Puspusin ng Iyong presensya,<br/>Ako ay puspusin nga.<br/>',NULL,40244,1);
INSERT INTO stanza VALUES('T267','chorus','Puspusin nga ako!<br/>Ngayon ng Espiritu<br/>Basyuhin, alisang lubos,<br/>Espiritu''y magpuspos.<br/>',NULL,40245,2);
INSERT INTO stanza VALUES('T267','2','Puspusin Mo ng ''Spiritu,<br/>Di ko batid kung pa''no;<br/>Mula sa utos ng sala,<br/>Ako ay mapalaya.<br/>',NULL,40246,3);
INSERT INTO stanza VALUES('T267','3','Gayang usang uhaw ako,<br/>Matighaw ng ''Spiritu;<br/>Sagana''y matikmang lubos,<br/>Tubig buhay umagos.<br/>',NULL,40247,5);
INSERT INTO stanza VALUES('T267','4','Sa krus ''lagak sarili ko,<br/>Mapuspos ng ''Spiritu;<br/>Lubos magpasakop sa Iyo,<br/>Sa gloria Mo ma''anyo.<br/>',NULL,40248,7);
INSERT INTO stanza VALUES('T268','1','Purihin Ka, Panginoon,<br/>Ako''y iniligtas Mo;<br/>Nilinisan at pinuspos,<br/>Nang maging daluyan Mo.<br/>',NULL,40249,1);
INSERT INTO stanza VALUES('T268','chorus','Daluyan lang, Panginoon,<br/>Nguni''t may Iyong biyaya.<br/>Sa pagdaloy Iyong magamit<br/>Saan man at kailan man.<br/>',NULL,40250,2);
INSERT INTO stanza VALUES('T268','2','Daluyan ng pagpapala,<br/>Sa mga pusong uhaw;<br/>Ihayag ang kaligtasan,<br/>Pag-ibig Mo''y siyang sigaw.<br/>',NULL,40251,3);
INSERT INTO stanza VALUES('T268','chorus','Daluyan lang, Panginoon,<br/>Nguni''t may Iyong biyaya.<br/>Sa pagdaloy Iyong magamit<br/>Saan man at kailan man.<br/>',NULL,40252,4);
INSERT INTO stanza VALUES('T268','3','Basyuhin Mo ''tong sisidlan,<br/>Mapasa I-yong kamay;<br/>Lakas nami''y nanggagaling<br/>Sa biyayang Iyong bigay.<br/>',NULL,40253,5);
INSERT INTO stanza VALUES('T268','chorus','Daluyan lang, Panginoon,<br/>Nguni''t may Iyong biyaya.<br/>Sa pagdaloy Iyong magamit<br/>Saan man at kailan man.<br/>',NULL,40254,6);
INSERT INTO stanza VALUES('T268','4','Sinasaksi Iyong biyaya,<br/>Binili at inangkin,<br/>Sa sala ay pinalaya,<br/>Pumasok Ka sa akin.<br/>',NULL,40255,7);
INSERT INTO stanza VALUES('T268','chorus','Daluyan lang, Panginoon,<br/>Nguni''t may Iyong biyaya.<br/>Sa pagdaloy Iyong magamit<br/>Saan man at kailan man.<br/>',NULL,40256,8);
INSERT INTO stanza VALUES('T268','5','Panginoon, puspusan Mo<br/>Ang aming pusong laan,<br/>Nang ang batis ng Iyong buhay,<br/>Umagos sa daluyan.<br/>',NULL,40257,9);
INSERT INTO stanza VALUES('T268','chorus','Daluyan lang, Panginoon,<br/>Nguni''t may Iyong biyaya.<br/>Sa pagdaloy Iyong magamit<br/>Saan man at kailan man.<br/>',NULL,40258,10);
INSERT INTO stanza VALUES('T271','1','Sa ''spiritu ''pinanganak,<br/>Nang sa Diyos maging anak;<br/>Espiritu Santo angkin,<br/>Nananahan sa atin.<br/>Kailangan Ka pa rin namin,<br/>Nang kami''y Iyong punuin;<br/>''Spiritu kami''y puspusin,<br/>Buhay pasaganahin.<br/>',NULL,40259,1);
INSERT INTO stanza VALUES('T271','2','''Spiritu Santo nasa ''min,<br/>''Spiritu ng buhay rin;<br/>Nang sagana''y matamasa,<br/>Sa kung ano nga Si-ya.<br/>''Spiritu aming kailangan,<br/>Lakas sa kai-taasan,<br/>Nang sa Kanya''y masangkapan,<br/>Ikaw mapaglingkuran.<br/>',NULL,40260,2);
INSERT INTO stanza VALUES('T271','3','Bautismuhan ng ''Spiritu,<br/>Bihisan ng lakas Mo;<br/>Sa "balabal" ng lakas Mo,<br/>Kaaway Mo''y matalo.<br/>Dilang apoy kami''y bigyan,<br/>Hangin Mo kami''y hipan,<br/>Maging saksing pinahiran,<br/>Puso Mo''y masiyahan.<br/>',NULL,40261,3);
INSERT INTO stanza VALUES('T271','4','Sa lakas ng Espiritu,<br/>Ibahagi kaloob,<br/>Makapagpangsyon nga kami,<br/>Patotoo''y maigi.<br/>Kaloob kami''y bigyan Mo,<br/>Ibuhos Espiritu;<br/>Nang magtuloy pagpapala,<br/>Katawan maitayo.<br/>',NULL,40262,4);
INSERT INTO stanza VALUES('T271','5','Para gloria''t kaharian,<br/>Katawan Iyong pakinggan;<br/>Tugunan lahat na hiling,<br/>Matupad Iyong layunin.<br/>Mayaman kaming puspusin,<br/>Espiritu''y gamitin;<br/>Sa loob, labas punuan,<br/>Kaloob bahaginan.<br/>',NULL,40263,5);
INSERT INTO stanza VALUES('T272','1','''Pinaglihi ng ''Spiritu,<br/>Naging tao si Kristo;<br/>At bago nga Siya naglingkod,<br/>''Spiritu ang nagpuspos.<br/>Sa simula ng serbisyo,<br/>''Spiritu''y nagbautismo;<br/>Siya ay naramtan ng lakas,<br/>Nagmula sa itaas.<br/>',NULL,40264,1);
INSERT INTO stanza VALUES('T272','2','Pedro, mga disipulo,<br/>''Sinilang ng ''Spiritu;<br/>''Spiritu Kanyang hininga,<br/>Nilanghap naman nila,<br/>Nguni''t tinanggap bautismo<br/>Ng ''Spiritung binubo,<br/>Naramtan at naging handa,<br/>Ministeryo''y magawa.<br/>',NULL,40265,2);
INSERT INTO stanza VALUES('T272','3','Taga-Samaria''t si Saulo,<br/>Banal taga-Efeso,<br/>Sa Espiritu ''sinilang,<br/>Natanggap kapuspusan.<br/>Nang may taong nagpatong nga<br/>Ng kamay sa kanila,<br/>Espiritung nagbautismo,<br/>May lakas nagserbisyo.<br/>',NULL,40266,3);
INSERT INTO stanza VALUES('T272','4','Tayo''y sumampalataya,<br/>Naisilang-muli nga,<br/>At umiinom sa Kanya,<br/>Laging tinatamasa.<br/>Mabautismuhan kailangan,<br/>''Spiritu maranasan;<br/>Sa paglilingkod sangkapan,<br/>Lakas kami''y maramtan.<br/>',NULL,40267,4);
INSERT INTO stanza VALUES('T272','5','Kami''y Iyo ngang bautismuhan,<br/>Ngayon aming kailangan;<br/>Lakas ng langit suotan,<br/>Matangay nang lubusan.<br/>Ngayon kami''y padanasin,<br/>Ito sa Iyo ang hiling;<br/>Masaganang pagbautismo,<br/>Pagbuhos ng ''Spiritu.<br/>',NULL,40268,5);
INSERT INTO stanza VALUES('T273','1','O Panginoon, kami''y aangkin,<br/>Kalakasa''t kapangyarihan,<br/>At ''pag nakamit, bahagi namin,<br/>Kaharian ipaglalaban.<br/>',NULL,40269,1);
INSERT INTO stanza VALUES('T273','chorus','Kapangyarihan kami''y damitan!<br/>Mula pa sa kaitaasan!<br/>Kapangyarihan kami''y damitan!<br/>Ang siyang sigaw ng Iyong Katawan!<br/>',NULL,40270,2);
INSERT INTO stanza VALUES('T273','2','O Panginoon, sa Iyo''y titingin,<br/>Dibinong ulan pabuhusin;<br/>Dahil sa Katawan buhos sa ''min,<br/>Nang maangkop sa Iyong gawain.<br/>',NULL,40271,3);
INSERT INTO stanza VALUES('T273','chorus','Ulan! ulan! ibuhos sa amin!<br/>Nagmumula sa kalangitan!<br/>Ulan! ulan! ibuhos sa amin!<br/>Ang siyang sigaw ng Iyong Katawan!<br/>',NULL,40272,4);
INSERT INTO stanza VALUES('T273','3','O Panginoon, ''hihintay sa Iyo,<br/>Apoy na banal ''ming mataglay,<br/>Upang ihayag ang ebanghelyo,<br/>Puso ng tao''y idalisay.<br/>',NULL,40273,5);
INSERT INTO stanza VALUES('T273','chorus','Dilang apoy! kami ay Iyong bigyan!<br/>Nang ang tao''y mapahayagan!<br/>Dilang apoy! kami ay Iyong bigyan!<br/>Ang siyang sigaw ng Iyong Katawan!<br/>',NULL,40274,6);
INSERT INTO stanza VALUES('T274','1','Kapangyarihan aming hanap,<br/>Gawain Mo, hindi natupad;<br/>Kami''y mahina''t walang lakas,<br/>Damtan kami''ng lakas!<br/>',NULL,40275,1);
INSERT INTO stanza VALUES('T274','chorus','Naghihintay at suko sa Iyo,<br/>Sa Iyong presensya nagsumamo;<br/>Bigyang-lakas, ngayon din bigyan,<br/>Lakas kami''y damtan!<br/>',NULL,40276,2);
INSERT INTO stanza VALUES('T274','2','Biyayaan at alagaan,<br/>Ekklesia Mo kaloob bigyan;<br/>May lakas Ikaw paglingkuran,<br/>Lakas kami''y damtan!<br/>',NULL,40277,3);
INSERT INTO stanza VALUES('T274','chorus','Naghihintay at suko sa Iyo,<br/>Sa Iyong presensya nagsumamo;<br/>Bigyang-lakas, ngayon din bigyan,<br/>Lakas kami''y damtan!<br/>',NULL,40278,4);
INSERT INTO stanza VALUES('T274','3','Lakas bigyan, awtoridad din,<br/>Tulad noong Pentecostes din,<br/>Aming panalangin tugunan,<br/>Lakas kami''y damtan!<br/>',NULL,40279,5);
INSERT INTO stanza VALUES('T274','chorus','Naghihintay at suko sa Iyo,<br/>Sa Iyong presensya nagsumamo;<br/>Bigyang-lakas, ngayon din bigyan,<br/>Lakas kami''y damtan!<br/>',NULL,40280,6);
INSERT INTO stanza VALUES('T274','4','Hiniling Iyong kapangyarihan,<br/>Ng Iyong Katawan sa Iyong Ngalan;<br/>Makalangit na apoy, ulan,<br/>Lakas kami''y damtan!<br/>',NULL,40281,7);
INSERT INTO stanza VALUES('T274','chorus','Naghihintay at suko sa Iyo,<br/>Sa Iyong presensya nagsumamo;<br/>Bigyang-lakas, ngayon din bigyan,<br/>Lakas kami''y damtan!<br/>',NULL,40282,8);
INSERT INTO stanza VALUES('T276','1','O pinagpalang katotohanan,<br/>Sa ''Spiritu''y nabautismuhan;<br/>Tanggapin itong katotohanan,<br/>Sa ''Spiritu''y nabautismuhan.<br/>',NULL,40283,1);
INSERT INTO stanza VALUES('T276','chorus','Tanggapin nga!<br/>Sa pananampalataya<br/>Tanggapin nga<br/>Ang katunayang nangyari na!<br/>',NULL,40284,2);
INSERT INTO stanza VALUES('T276','2','Malinaw sabi ng Bagong Tipan,<br/>Sa ''Spiritu''y nabautismuhan;<br/>Ito''y kumpleto''t dapat tanganan,<br/>Sa ''Spiritu''y nabautismuhan.<br/>',NULL,40285,3);
INSERT INTO stanza VALUES('T276','chorus','Tanganan na!<br/>Sa pananampalataya<br/>Tanganan na<br/>Ang katunayang nangyari na!<br/>',NULL,40286,4);
INSERT INTO stanza VALUES('T276','3','Binuhos sa ekklesia''y ''Spiritu,<br/>Sa ''Spiritu''y nabautismuhan;<br/>Pagpapala may bahagi tayo,<br/>Sa ''Spiritu''y nabautismuhan.<br/>',NULL,40287,5);
INSERT INTO stanza VALUES('T276','chorus','Ibahagi!<br/>Sa buháy na pananalig<br/>Ibahagi<br/>Ang sadyang tunay na nangyari!<br/>',NULL,40288,6);
INSERT INTO stanza VALUES('T276','4','Tamang Katawan, tamang batayan,<br/>Kumilos sa katotohanan;<br/>Tinuos ang alinlanga''t sala,<br/>Kilos sa pagsampalataya.<br/>',NULL,40289,7);
INSERT INTO stanza VALUES('T276','chorus','Kumilos na!<br/>Sa pananampalataya<br/>Kumilos na<br/>Sa katunayang nangyari na!<br/>',NULL,40290,8);
INSERT INTO stanza VALUES('T277','1','Manliligtas umakyat na,<br/>Sa langit naluklok pa,<br/>Putong ay l''walhati''t dangal<br/>Mula sa Amang mahal;<br/>Ginawang Ulo sa lahat,<br/>Nang Diyos Kanyang mahayag.<br/>',NULL,40291,1);
INSERT INTO stanza VALUES('T277','2','Mula sa Kristong umakyat,<br/>''Spiritu''y binuhos nga,<br/>Nang Katawan nabuhusan,<br/>Sangkap Niya''y binihisan;<br/>Panginoon ng tanan Siya,<br/>Sa Ekklesia''y masamba.<br/>',NULL,40292,2);
INSERT INTO stanza VALUES('T277','3','Nang naging laman si Kristo,<br/>Diyos dinala sa tao;<br/>Kamatayan, pagkabuhay,<br/>Dinala sa Diyos — tao;<br/>Pinaghalong Diyos at tao,<br/>Natupad sa loob Mo.<br/>',NULL,40293,3);
INSERT INTO stanza VALUES('T277','4','Umakyat sa kalangitan,<br/>Naupo sa luklukan;<br/>Hari ng mga hari Siya,<br/>Awtoridad ay Kanya;<br/>Sa pagbuhos ng ''Spiritu,<br/>Ito''y napatotoo.<br/>',NULL,40294,4);
INSERT INTO stanza VALUES('T277','5','Ang pagbuhos ng ''Spiritu<br/>Sa Ekklesia''y dumapo;<br/>Sa loob ng Espiritu<br/>Ekklesia''y binautismo;<br/>Bautismo sa Espiritu,<br/>Walang hanggang totoo.<br/>',NULL,40295,5);
INSERT INTO stanza VALUES('T277','6','Purihin may katuparan,<br/>Minsan at palagian!<br/>Aleluya, napabilang,<br/>Dakila, maliit man!<br/>Ekklesia ay binautismo,<br/>Ng sugo Niyang ''Spiritu.<br/>',NULL,40296,6);
INSERT INTO stanza VALUES('T278','1','Espiritu ng buhay nasa atin,<br/>Sa loob pampawi sa uhaw natin;<br/>Atin Siyang iinumin nang mapuspos,<br/>Mula sa ating loob Siya''y aagos.<br/>',NULL,40297,1);
INSERT INTO stanza VALUES('T278','2','Ang Espiritu ng kapangyarihan,<br/>Tulad sa balabal tayo''y daramtan,<br/>Sa Kanya tayo ay nabautismuhan,<br/>Upang Siya ay ating mapaglingkuran.<br/>',NULL,40298,2);
INSERT INTO stanza VALUES('T278','3','Espiritu ng buhay ay hininga,<br/>Sa loob natin ito''y inihinga;<br/>Ang Espiritu ng kapangyarihan,<br/>Tulad ng hangin tayo''y hinihipan.<br/>',NULL,40299,3);
INSERT INTO stanza VALUES('T278','4a','Ang bumangon na Poong Hesu-Kristo,<br/>Hiningahan Niya mga disipulo,<br/>Noong araw ng muling-pagkabuhay,<br/>Ng l''walhating Espiritu ng buhay.<br/>',NULL,40300,4);
INSERT INTO stanza VALUES('T278','4b','Ang Panginoong Hesus na umakyat,<br/>Ibinuhos Niya sa mga alagad,<br/>Ang Espiritu ng kapangyarihan,<br/>Sa Pentecostes, Pista ng Anihan.<br/>',NULL,40301,5);
INSERT INTO stanza VALUES('T278','5','Nasa loob, Espiritu ng buhay,<br/>Ng mga disipulo bilang buhay;<br/>Ang Espiritu ng kapangyarihan<br/>Para sa buhay tayo''y dinulutan.<br/>',NULL,40302,6);
INSERT INTO stanza VALUES('T278','6','Itong Espiritu hindi dalawa,<br/>Ni magkahiwalay, ni magkaiba;<br/>Isang Espiritu dalawang gamit—<br/>Pampuspos ng buhay at pananamit.<br/>',NULL,40303,7);
INSERT INTO stanza VALUES('T278','7','Panginoon, loob nami''y puspusin,<br/>Buhay Mo sa amin ay palaguin;<br/>At damitan ng Iyong kapangyarihan,<br/>Kalooban Mo''y bigyang katuparan.<br/>',NULL,40304,8);
INSERT INTO stanza VALUES('T279','1','Dugo munang naglilinis<br/>Saka ungguwentong pahid;<br/>Pentecostes ''di darating<br/>Kung walang Golgota rin.<br/>Walang paglinis ng dugo,<br/>Walang lakas ''Spiritu;<br/>Kitlin buhay-kalul''wa ko,<br/>Maging saksi ni Kristo.<br/>',NULL,40305,1);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40306,2);
INSERT INTO stanza VALUES('T279','2','Bato kailangang paluin,<br/>Nang tubig paagusin;<br/>''Spiritu may kapuspusan,<br/>Kapag may kamatayan.<br/>Kung namatay kasama Niya,<br/>Handa''ng lahat mawala;<br/>Daramtan ng Kanyang lakas<br/>Nang mundo ay maligtas.<br/>',NULL,40307,3);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40308,4);
INSERT INTO stanza VALUES('T279','3','Apoy sunod sa dambana,<br/>Kung nalugi may bunga;<br/>Pag-''alay dapat mauna,<br/>Nang trono''y sumunod na.<br/>Kung handang magsakripisyo,<br/>Sa Diyos lahat isuko;<br/>Kapangyarihan ay atin<br/>Nang ito''y matanghal din.<br/>',NULL,40309,5);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40310,6);
INSERT INTO stanza VALUES('T279','4','Ihanda sisidlang basyo,<br/>Lagyan ng Langis ito;<br/>Maghukay munang daluyan,<br/>Nang mapuno ng Ulan.<br/>Daraan sa Ilog Jordan,<br/>''Spiritu maragdagan;<br/>Kamatayan ng bautismo—<br/>Kasunod Espiritu.<br/>',NULL,40311,7);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40312,8);
INSERT INTO stanza VALUES('T279','5','Kapag aning hinog masdan,<br/>Sa gintong kabukiran;<br/>Gunitaing bago nito,<br/>May namatay na trigo.<br/>Sa kamatayan nating t''yak,<br/>Bunga''y mamumulaklak;<br/>Kung di nalibing kay Kristo<br/>Di madama ''Spiritu.<br/>',NULL,40313,9);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40314,10);
INSERT INTO stanza VALUES('T279','6','Daang makitid tahakin,<br/>Ito''y aking dalangin,<br/>Magdusa man, Ika''y sundin,<br/>Kataasan tuusin.<br/>Kamatayang mas malalim<br/>Aking kailanganin;<br/>Kahulugan ng Krus, Poon,<br/>Isangkap sa ''kin ngayon.<br/>',NULL,40315,11);
INSERT INTO stanza VALUES('T279','chorus','Sa Krus, Poon, ang hiling<br/>Buhay-kalul''wa''y kitlin;<br/>Magbayad ng halaga,<br/>Pagpapahid makuha.<br/>',NULL,40316,12);
INSERT INTO stanza VALUES('T280','1','Sa Iyong dugo''y hugasan,<br/>Linisin sala ko,<br/>Nang ako''y mapahiran<br/>Ng Iyong Espiritu.<br/>Ang aking paglilingkod,<br/>Kay hina at bigo,<br/>Nais kong mapuspusan<br/>Nang mamuhay sa Iyo.<br/>',NULL,40317,1);
INSERT INTO stanza VALUES('T280','chorus','Iligtas sa sarili,<br/>Sa kapighatian;<br/>Sa Iyo''y mananatili,<br/>Lubos Mong puspusan.<br/>',NULL,40318,2);
INSERT INTO stanza VALUES('T280','2','Ang aking tuyong puso,<br/>Nananabik sa Iyo;<br/>Pun''in ng Espiritu,<br/>Ang kahilingan ko.<br/>Ika''y Batong pinalo,<br/>Ang aking kublihan;<br/>Ako ay Iyong buhusan<br/>Hanggang masiyahan.<br/>',NULL,40319,3);
INSERT INTO stanza VALUES('T280','chorus','Iligtas sa sarili,<br/>Sa kapighatian;<br/>Sa Iyo''y mananatili,<br/>Lubos Mong puspusan.<br/>',NULL,40320,4);
INSERT INTO stanza VALUES('T280','3','Anong lamig ng puso,<br/>Lubhang masuwayin;<br/>Pun''in ng Iyong ''Spiritu,<br/>Ikaw ay susundin.<br/>Ako''y nasa dambana,<br/>At di na lalayo;<br/>Apoy Mo ang tumupok<br/>Sa lahat-lahat ko.<br/>',NULL,40321,5);
INSERT INTO stanza VALUES('T280','chorus','Iligtas sa sarili,<br/>Sa kapighatian;<br/>Sa Iyo''y mananatili,<br/>Lubos Mong puspusan.<br/>',NULL,40322,6);
INSERT INTO stanza VALUES('T280','4','O, ang Iyong Krus sa akin,<br/>Gawa''y palalimin,<br/>Lumawak Ka sa akin,<br/>Abo, ako''y gawin.<br/>Ako ay punuin Mo,<br/>Higit kaysa noon,<br/>At ang tubig na buháy,<br/>Ibuhos Mo ngayon.<br/>',NULL,40323,7);
INSERT INTO stanza VALUES('T280','chorus','Iligtas sa sarili,<br/>Sa kapighatian;<br/>Sa Iyo''y mananatili,<br/>Lubos Mong puspusan.<br/>',NULL,40324,8);
INSERT INTO stanza VALUES('T284','1','Walang hanggang pagsinta,<br/>Sa akin ay umibig;<br/>Ginabay ng biyaya,<br/>Upang aking mabatid.<br/>Kapayapaang sakdal!<br/>Kay banal na damdamin!<br/>Patuloy pagmamahal,<br/>Ako''y Kanya, Siya''y akin.<br/>',NULL,40325,1);
INSERT INTO stanza VALUES('T284','2','Palibot lunting kulay,<br/>Langit higit na bughaw;<br/>Bawa''t kulay may buhay,<br/>Walang Diyos di matanaw:<br/>Ibong nag-aawitan,<br/>Bulaklak magaganda,<br/>Yamang aking nalaman,<br/>Ako''y Kanya, Siya''y akin.<br/>',NULL,40326,2);
INSERT INTO stanza VALUES('T284','3','Ang bumagabag noon<br/>Di na makabalisa,<br/>Sapagka''t ako ngayon<br/>Nakahimlay sa Kanya.<br/>Mananatili ako<br/>Magpakailanman dito,<br/>Binubulungan ako,<br/>Ako''y Kanya, Siya''y akin.<br/>',NULL,40327,3);
INSERT INTO stanza VALUES('T284','4','Tanging Kanya kailanman,<br/>Di mapaghihiwalay;<br/>Anong kapahingahan<br/>Si Kristo magbibigay.<br/>Langit, lupa''y mawala,<br/>Liwanag ma''y dumilim,<br/>Ang Diyos aking kasama,<br/>Ako''y Kanya, Siya''y akin.<br/>',NULL,40328,4);
INSERT INTO stanza VALUES('T286','1','Nang dahil sa pag-irog sala ko''y tinubos,<br/>Sa biyayang pagsakop ng aking si Hesus;<br/>Sa lawak ng pag-irog buhay inihandog,<br/>Puso ko''y nalamuyot sa Kanya sumunod.<br/>',NULL,40329,1);
INSERT INTO stanza VALUES('T286','chorus','Lalo Siyang tumatamis<br/>Sa tagal ng panahon,<br/>Malalim, mayaman,<br/>Pag-ibig ni Hesus<br/>Lumalawig kailanman.<br/>',NULL,40330,2);
INSERT INTO stanza VALUES('T286','2','Tinahak Niya ang buhay sa lumang Judea,<br/>Sabik na mga tao pinalibutan Siya;<br/>Lunas ng nagdurusa, liwanag ng mata,<br/>Pag-ibig at ligaya ang idinulot Niya.<br/>',NULL,40331,3);
INSERT INTO stanza VALUES('T286','chorus','Lalo Siyang tumatamis<br/>Sa tagal ng panahon,<br/>Malalim, mayaman,<br/>Pag-ibig ni Hesus<br/>Lumalawig kailanman.<br/>',NULL,40332,4);
INSERT INTO stanza VALUES('T288','1','Kaibigang natagpuan,<br/>Si Hesus na nagmahal;<br/>Pag-ibig Niya tinalian<br/>Ako para sa Kanya.<br/>At puso''y nakagapos sa<br/>Di-mapatid na lubid,<br/>Ako''y Kanya, Siya ay akin<br/>Ngayo''t magpakailanman.<br/>',NULL,40333,1);
INSERT INTO stanza VALUES('T288','2','Kaibigang natagpuan,<br/>Buhay Kanyang inalay,<br/>Sarili Niya''y ibinigay<br/>Nagdugo at namatay.<br/>Sarili ko''y di na akin,<br/>Angkin ng Tagabigay;<br/>Puso, lakas, buhay, lahat<br/>Sa Kanya walang hanggan.<br/>',NULL,40334,2);
INSERT INTO stanza VALUES('T288','3','Kaibigang natagpuan,<br/>Siya''y magiliw at tunay,<br/>Tagapayo, at Patnubay,<br/>Manananggol matibay.<br/>Ano''ng makapaghiwalay?<br/>Sa Kanya at sa akin?<br/>Buhay o kamatayan man?<br/>Wala, ako''y sa Kanya.<br/>',NULL,40335,3);
INSERT INTO stanza VALUES('T291','1','Ako''y nagagalak sa ''ting Ama,<br/>Pag-ibig Niya nilahad sa Biblia;<br/>Pambihirang bagay ang natalos:<br/>Kay giliw, mahal ako ni Hesus.<br/>',NULL,40336,1);
INSERT INTO stanza VALUES('T291','chorus','Ako''y nagagalak nang lubos,<br/>Ako ay mahal ni Hesus;<br/>Ako''y nagagalak nang lubos,<br/>''Ko''y mahal ni Hesus.<br/>',NULL,40337,2);
INSERT INTO stanza VALUES('T291','2','Siya''y malimot ko man at gumala,<br/>Mahal pa rin Niya kahit nawala;<br/>Babalik sa Kanyang mga bisig,<br/>''Pag maalala Kanyang pag-ibig.<br/>',NULL,40338,3);
INSERT INTO stanza VALUES('T291','chorus','Ako''y nagagalak nang lubos,<br/>Ako ay mahal ni Hesus;<br/>Ako''y nagagalak nang lubos,<br/>''Ko''y mahal ni Hesus.<br/>',NULL,40339,4);
INSERT INTO stanza VALUES('T291','3','May isa lamang akong maawit,<br/>Sa aking Haring kaibig-ibig;<br/>Ang awit kong di na matatapos,<br/>"Kay hiwaga, ''ko''y mahal ni Hesus."<br/>',NULL,40340,5);
INSERT INTO stanza VALUES('T291','chorus','Ako''y nagagalak nang lubos,<br/>Ako ay mahal ni Hesus;<br/>Ako''y nagagalak nang lubos,<br/>''Ko''y mahal ni Hesus.<br/>',NULL,40341,6);
INSERT INTO stanza VALUES('T295','1','Kristo ng Diyos, kat''wiran ko,<br/>Kagandahan at gayak ko;<br/>Sa nag-aalab na mundo,<br/>Makapagtataas-noo.<br/>',NULL,40342,1);
INSERT INTO stanza VALUES('T295','2','Nananalig sa Iyong dugo,<br/>Na nasa biyayang trono;<br/>Samo ng mga salarin,<br/>Binubo para sa akin.<br/>',NULL,40343,2);
INSERT INTO stanza VALUES('T295','3','Mas marami mang salarin,<br/>Kaysa bilang ng buhangin;<br/>Nagbayad Ka ng halaga,<br/>Katubusa''y Iyong ginawa.<br/>',NULL,40344,3);
INSERT INTO stanza VALUES('T295','4','Matapang akong titindig,<br/>Sino ang sa ''ki''y sisingil?<br/>Ako''y lubos kinalagan,<br/>Sa sala at kahihiyan.<br/>',NULL,40345,4);
INSERT INTO stanza VALUES('T295','5','Balabal na walang dungis,<br/>Kailanman ay ibibihis;<br/>L''walhating di na kukupas,<br/>Sariwa''t di-magwawakas.<br/>',NULL,40346,5);
INSERT INTO stanza VALUES('T295','6','Diyos ng kalakasa''t sinta,<br/>Awa Mo''y makita nawa;<br/>Gayak nami''t kagandahan,<br/>Hesus, ang aming Kat''wiran.<br/>',NULL,40347,6);
INSERT INTO stanza VALUES('T296','1','Manliligtas ang nagdugo,<br/>Bakit ako nakinabang?<br/>Namatay Siya sa halip ko,<br/>Ginanap ang kaligtasan.<br/>Pag-ibig, mahiwaga rin,<br/>Diyos namatay para sa ''kin.<br/>',NULL,40348,1);
INSERT INTO stanza VALUES('T296','2','Namatay Siya, kay hiwaga—<br/>Diyos na walang kamatayan!<br/>Pag-ibig, di-matingkala<br/>Taas, haba, lalim, luwang!<br/>Pati anghel namamangha,<br/>Diyos sambahin sa habag Niya.<br/>',NULL,40349,2);
INSERT INTO stanza VALUES('T296','3','Nilisan trono ng Ama,<br/>Mahabagin, Siya''y bumaba<br/>Upang iligtas sa sala<br/>Ang lahing walang pag-asa.<br/>Di-masukat, libreng awa,<br/>Handog sa tulad kong aba.<br/>',NULL,40350,3);
INSERT INTO stanza VALUES('T296','4','Bihag ang espiritu ko,<br/>Ginapos ng sala''t dilim;<br/>Tinanglawan ng mata Mo,<br/>Piitan ko''y nagniningning,<br/>Nangalas ang tanikala,<br/>Sundan Kita, malaya na.<br/>',NULL,40351,4);
INSERT INTO stanza VALUES('T296','5','Hatol ay di-katakutan,<br/>Hesus at lahat ay akin!<br/>Kay Kristong Ulo manahan,<br/>Dibinong kat''wiran kamtin;<br/>Sa luklukan ng biyaya,<br/>Si Kristo''y aking korona.<br/>',NULL,40352,5);
INSERT INTO stanza VALUES('T297','1','Walang hatol, kay hiwaga!<br/>Puso ko''y natuwa!<br/>Sala ko''y dala ni Hesus,<br/>Namatay, tumubos.<br/>',NULL,40353,1);
INSERT INTO stanza VALUES('T297','2','Ang dugo Niya sa harapan<br/>Ng Diyos, namagitan;<br/>Mga banal mahalaga,<br/>Inalagaan Niya.<br/>',NULL,40354,2);
INSERT INTO stanza VALUES('T297','3','Walang hatol, kalul''wa ko,<br/>Salita ng Diyos ''to,<br/>Kay Kristong muling nabuhay,<br/>Ika''y matagumpay.<br/>',NULL,40355,3);
INSERT INTO stanza VALUES('T297','4','Diyos sa akin ituturo,<br/>Tumingin kay Kristo;<br/>Pag-ibig Mo''y aking kamtin,<br/>Ngalan l''walhatiin.<br/>',NULL,40356,4);
INSERT INTO stanza VALUES('T298','1','Pag-asa ko''y itinatag<br/>Kay Kristo — aking kat''wiran;<br/>Sa iba ay di-panatag,<br/>Kristo lang maaasahan.<br/>',NULL,40357,1);
INSERT INTO stanza VALUES('T298','chorus','Si Kristo''y saligang-Bato,<br/>Ibang lupa ay balaho,<br/>Ibang lupa ay balaho.<br/>',NULL,40358,2);
INSERT INTO stanza VALUES('T298','2','Matakpan man Kanyang mukha,<br/>Biyaya Niya''y di nag-iba;<br/>Bumagyo man o bumaha,<br/>Matatag pa rin ang angkla.<br/>',NULL,40359,3);
INSERT INTO stanza VALUES('T298','chorus','Si Kristo''y saligang-Bato,<br/>Ibang lupa ay balaho,<br/>Ibang lupa ay balaho.<br/>',NULL,40360,4);
INSERT INTO stanza VALUES('T298','3','Dugo''t tipan Niya ay tiyak,<br/>Ako''y nasa Kanyang kamay;<br/>Ang paligid ma''y mawasak,<br/>Siya''y nanatiling matibay.<br/>',NULL,40361,5);
INSERT INTO stanza VALUES('T298','chorus','Si Kristo''y saligang-Bato,<br/>Ibang lupa ay balaho,<br/>Ibang lupa ay balaho.<br/>',NULL,40362,6);
INSERT INTO stanza VALUES('T298','4','Pagdating Niyang may trumpeta,<br/>Ako''y mapasa-loob Niya;<br/>Katuwiran ko''y tanging Siya,<br/>Sa lukluka''y walang sala.<br/>',NULL,40363,7);
INSERT INTO stanza VALUES('T298','chorus','Si Kristo''y saligang-Bato,<br/>Ibang lupa ay balaho,<br/>Ibang lupa ay balaho.<br/>',NULL,40364,8);
INSERT INTO stanza VALUES('T299','1','Walang takot dulog sa Diyos,<br/>O anong kataga!<br/>Sa dugo''y kasundong lubos;<br/>O kay payapa nga.<br/>',NULL,40365,1);
INSERT INTO stanza VALUES('T299','2','Gawi''t likas kay layo nga,<br/>O kay layo sa Diyos;<br/>Dahil sa pananalig nga<br/>Napalapit sa Diyos.<br/>',NULL,40366,2);
INSERT INTO stanza VALUES('T299','3','Kay lapit, kay lapit sa Diyos,<br/>Walang kay lapit pa;<br/>Kasing lapit ako sa Diyos,<br/>Tulad ng Anak Niya!<br/>',NULL,40367,3);
INSERT INTO stanza VALUES('T299','4','Sa Diyos ''ko''y mahal na mahal,<br/>Di na mahigitan;<br/>Sa Anak Niyang pagmamahal,<br/>Sa akin din laan.<br/>',NULL,40368,4);
INSERT INTO stanza VALUES('T299','5','Bakit pa mababahala,<br/>Kung gayon ang Diyos ko?<br/>Gabi''t araw Siyang bahala,<br/>Sabi''y "Ako''y sa iyo."<br/>',NULL,40369,5);
INSERT INTO stanza VALUES('T300','1','Bangon, ''king kalul''wa,<br/>Waksi, takot, sala;<br/>Ang nagdugong Hain,<br/>Para nga sa akin.<br/>Sa trono garantiya ko,<br/>Nasa palad Niya ngalan ko.<br/>',NULL,40370,1);
INSERT INTO stanza VALUES('T300','2','Buháy Siyang palagi<br/>Namagitan sa ''kin;<br/>Pagsintang nagtubos<br/>Dugo Niya''y ''binuhos.<br/>Dugo''y para sa lahat nga,<br/>Winis''kan trono ng b''yaya.<br/>',NULL,40371,2);
INSERT INTO stanza VALUES('T300','3','Limang sugat tamo,<br/>Buhat sa Kalbaryo;<br/>Maging ang dalangin,<br/>Mabisa sa akin.<br/>Ang hiyaw: patawarin siya<br/>''Ligtas, natubos maysala.<br/>',NULL,40372,3);
INSERT INTO stanza VALUES('T300','4','Nakinig ang Ama<br/>Sa panalangin Niya;<br/>Di Niya matanggihan<br/>Kanyang pinahiran.<br/>''Spiritu tumugong lubos,<br/>Ako nga''y ''sinilang ng Diyos.<br/>',NULL,40373,4);
INSERT INTO stanza VALUES('T300','5','Ipinagkasundo,<br/>Patawad natamo;<br/>Ako''y kinilala<br/>Anak walang duda.<br/>Dumulog nang may tiwala,<br/>Ang sigaw ko: Abba Ama!<br/>',NULL,40374,5);
INSERT INTO stanza VALUES('T302','1','Himno ibig kong awitin,<br/>Nang ako''y tubusin,<br/>Ng Hari''t Manunubos din—<br/>Nang ako''y tubusin.<br/>',NULL,40375,1);
INSERT INTO stanza VALUES('T302','chorus','Nang ako''y tubusin,<br/>Nang ako''y tubusin,<br/>Sa ngalan Niya''y gloria ko;<br/>Nang ako''y tubusin,<br/>Gloria ko''y sa ngalan ni Kristo.<br/>',NULL,40376,2);
INSERT INTO stanza VALUES('T302','2','Nasiyahang lubos ako,<br/>Nang ako''y tubusin;<br/>Layon Niya''y magampanan ko,<br/>Nang ako''y tubusin.<br/>',NULL,40377,3);
INSERT INTO stanza VALUES('T302','chorus','Nang ako''y tubusin,<br/>Nang ako''y tubusin,<br/>Sa ngalan Niya''y gloria ko;<br/>Nang ako''y tubusin,<br/>Gloria ko''y sa ngalan ni Kristo.<br/>',NULL,40378,4);
INSERT INTO stanza VALUES('T302','3','Nagniningning aking saksi,<br/>Nang ako''y tubusin,<br/>Duda''t pangamba''y napawi—<br/>Nang ako''y tubusin.<br/>',NULL,40379,5);
INSERT INTO stanza VALUES('T302','chorus','Nang ako''y tubusin,<br/>Nang ako''y tubusin,<br/>Sa ngalan Niya''y gloria ko;<br/>Nang ako''y tubusin,<br/>Gloria ko''y sa ngalan ni Kristo.<br/>',NULL,40380,6);
INSERT INTO stanza VALUES('T302','4','Di mabigkas kagalakan,<br/>Nang ako''y tubusin,<br/>Dahil kay Kristong kat''wiran—<br/>Nang ako''y tubusin.<br/>',NULL,40381,7);
INSERT INTO stanza VALUES('T302','chorus','Nang ako''y tubusin,<br/>Nang ako''y tubusin,<br/>Sa ngalan Niya''y gloria ko;<br/>Nang ako''y tubusin,<br/>Gloria ko''y sa ngalan ni Kristo.<br/>',NULL,40382,8);
INSERT INTO stanza VALUES('T302','5','Diyos naging para sa akin;<br/>Nang ako''y tubusin,<br/>Walang hanggan kong kapiling—<br/>Nang ako''y tubusin.<br/>',NULL,40383,9);
INSERT INTO stanza VALUES('T302','chorus','Nang ako''y tubusin,<br/>Nang ako''y tubusin,<br/>Sa ngalan Niya''y gloria ko;<br/>Nang ako''y tubusin,<br/>Gloria ko''y sa ngalan ni Kristo.<br/>',NULL,40384,10);
INSERT INTO stanza VALUES('T303','1','Ako''y tinubos ''di ng pilak ni ginto;<br/>Di panlupang yaman, niligtas ako.<br/>Ang dugo sa krus ang tangi kong sandigan;<br/>Kamatayan Niya''y aking kasakdalan.<br/>',NULL,40385,1);
INSERT INTO stanza VALUES('T303','chorus','Ako''y tinubos ''di ng pilak;<br/>Di ginto ang pambayad;<br/>Binili ng dugo ni Hesus,<br/>Pag-ibig anong taos!<br/>',NULL,40386,2);
INSERT INTO stanza VALUES('T303','2','Ako''y tinubos ''di ng pilak ni ginto;<br/>Anong bigat ng sala sa budhi ko.<br/>Ang dugo sa krus ang tangi kong sandigan;<br/>Maaangkin ko Kanyang kamatayan.<br/>',NULL,40387,3);
INSERT INTO stanza VALUES('T303','chorus','Ako''y tinubos ''di ng pilak;<br/>Di ginto ang pambayad;<br/>Binili ng dugo ni Hesus,<br/>Pag-ibig anong taos!<br/>',NULL,40388,4);
INSERT INTO stanza VALUES('T303','3','Ako''y tinubos ''di ng pilak ni ginto;<br/>Banal na utos pinigilan ako.<br/>Ang dugo sa krus ang tangi kong sandigan;<br/>Pangamba''y pinawi ng kamatayan.<br/>',NULL,40389,5);
INSERT INTO stanza VALUES('T303','chorus','Ako''y tinubos ''di ng pilak;<br/>Di ginto ang pambayad;<br/>Binili ng dugo ni Hesus,<br/>Pag-ibig anong taos!<br/>',NULL,40390,6);
INSERT INTO stanza VALUES('T303','4','Ako''y tinubos ''di ng pilak ni ginto;<br/>Kaharian hindi mabili nito.<br/>Ang dugo ng krus ang tangi kong sandigan;<br/>Kamatayan Niya''y aking katubusan.<br/>',NULL,40391,7);
INSERT INTO stanza VALUES('T303','chorus','Ako''y tinubos ''di ng pilak;<br/>Di ginto ang pambayad;<br/>Binili ng dugo ni Hesus,<br/>Pag-ibig anong taos!<br/>',NULL,40392,8);
INSERT INTO stanza VALUES('T306','1','Ako ay kay Hesus,<br/>Di sa sarili;<br/>Lahat ng ako''t akin<br/>Sa Kanyang tangi.<br/>',NULL,40393,1);
INSERT INTO stanza VALUES('T306','2','Ako ay kay Hesus,<br/>Hari at Poon;<br/>Sa puso ko''y namuno<br/>Sa lahat ngayon.<br/>',NULL,40394,2);
INSERT INTO stanza VALUES('T306','3','Ako ay kay Hesus;<br/>Kahit masaktan,<br/>Kung bisig Niya hawakan<br/>Aking kalul''wa.<br/>',NULL,40395,3);
INSERT INTO stanza VALUES('T306','4','Ako ay kay Hesus;<br/>Anong pag''pala!<br/>Sa dugong mahalaga,<br/>Binili nga Niya.<br/>',NULL,40396,4);
INSERT INTO stanza VALUES('T306','5','Ako ay kay Hesus;<br/>Para Siya sa ''kin;<br/>Ako''y Kanya, Siya''y akin<br/>Palagian din.<br/>',NULL,40397,5);
INSERT INTO stanza VALUES('T306','6','Ako ay kay Hesus;<br/>Kaluluwa ko<br/>Iingatan Niyang lubos<br/>Sa kamatayan.<br/>',NULL,40398,6);
INSERT INTO stanza VALUES('T306','7','Ako ay kay Hesus;<br/>Di katagalan—<br/>Kasama''y Manliligtas<br/>Sa karangalan.<br/>',NULL,40399,7);
INSERT INTO stanza VALUES('T307','1','Panginoo''y ipinako,<br/>At namatay sa Kalbaryo;<br/>Doon sa krus, Siya''y nagdugo,<br/>Binili ang patawad ko.<br/>',NULL,40400,1);
INSERT INTO stanza VALUES('T307','chorus','O kay dilim na Kalbaryo!<br/>Doon si Hesus nagdugo!<br/>O biyaya ng Kalbaryo!<br/>Doon Niya tinubos ako!<br/>',NULL,40401,2);
INSERT INTO stanza VALUES('T307','2','Sa gitna ng kadiliman<br/>Sa mundo Siya''y nagpaalam;<br/>Tabing ng templo''y nahapak<br/>Buhay banal ay nahayag.<br/>',NULL,40402,3);
INSERT INTO stanza VALUES('T307','chorus','O kay dilim na Kalbaryo!<br/>Doon si Hesus nagdugo!<br/>O biyaya ng Kalbaryo!<br/>Doon Niya tinubos ako!<br/>',NULL,40403,4);
INSERT INTO stanza VALUES('T307','3','Hesus paano nga ito<br/>Sa ''kin binigay buhay Mo,<br/>Iyong binata krus at dusa<br/>Sa madilim na Kalbaryo!<br/>',NULL,40404,5);
INSERT INTO stanza VALUES('T307','chorus','O kay dilim na Kalbaryo!<br/>Doon si Hesus nagdugo!<br/>O biyaya ng Kalbaryo!<br/>Doon Niya tinubos ako!<br/>',NULL,40405,6);
INSERT INTO stanza VALUES('T308','1','O mal''walhating katiyakan<br/>Kay Hesu-Kristo ay nabibilang!<br/>Sa dugo ng Diyos nahugasan,<br/>Espiritu ang Siyang nagsilang.<br/>',NULL,40406,1);
INSERT INTO stanza VALUES('T308','chorus','Ito ang aking kasaysayan,<br/>Tagapagligtas papurihan.<br/>Ito ang lagi kong awitin,<br/>Araw-gabi Siya''y pupurihin.<br/>',NULL,40407,2);
INSERT INTO stanza VALUES('T308','2','Malugod na pagpapasakop,<br/>Pangitain ay aking namasdan;<br/>Mga anghel pumapanaog,<br/>Dala''y pagsinta''t kahabagan.<br/>',NULL,40408,3);
INSERT INTO stanza VALUES('T308','chorus','Ito ang aking kasaysayan,<br/>Tagapagligtas papurihan.<br/>Ito ang lagi kong awitin,<br/>Araw-gabi Siya''y pupurihin.<br/>',NULL,40409,4);
INSERT INTO stanza VALUES('T308','3','Wagas na pagpapahingalay,<br/>Ako kay Kristo''y may kagalakan;<br/>Sa pagdating Niya''y nagbabantay,<br/>Lipos ng Kanyang kabutihan.<br/>',NULL,40410,5);
INSERT INTO stanza VALUES('T308','chorus','Ito ang aking kasaysayan,<br/>Tagapagligtas papurihan.<br/>Ito ang lagi kong awitin,<br/>Araw-gabi Siya''y pupurihin.<br/>',NULL,40411,6);
INSERT INTO stanza VALUES('T309','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40412,1);
INSERT INTO stanza VALUES('T309','1','Kay laking pagbabago sa aking buhay,<br/>Nang si Kristo ay tanggapin!<br/>Lumigaya ang pusong dati''y may lumbay,<br/>Nang si Kristo ay tanggapin!<br/>',NULL,40413,2);
INSERT INTO stanza VALUES('T309','chorus','Nang si Kristo ay tanggapin!<br/>Nang si Kristo ay tanggapin!<br/>Galak ng puso''y nag-umapaw sa akin,<br/>Nang Siya ay aking tanggapin!<br/>',NULL,40414,3);
INSERT INTO stanza VALUES('T309','2','Hindi na muling malilihis ng landas,<br/>Nang si Kristo ay tanggapin!<br/>Sa mga kasalanan ko ay naligtas,<br/>Nang si Kristo ay tanggapin!<br/>',NULL,40415,4);
INSERT INTO stanza VALUES('T309','chorus','Nang si Kristo ay tanggapin!<br/>Nang si Kristo ay tanggapin!<br/>Galak ng puso''y nag-umapaw sa akin,<br/>Nang Siya ay aking tanggapin!<br/>',NULL,40416,5);
INSERT INTO stanza VALUES('T309','3','Nagkaro''n ng saysay ang hungkag kong buhay,<br/>Nang si Kristo ay tanggapin!<br/>Makamundong saya''y nawalan ng kulay,<br/>Nang si Kristo ay tanggapin!<br/>',NULL,40417,6);
INSERT INTO stanza VALUES('T309','chorus','Nang si Kristo ay tanggapin!<br/>Nang si Kristo ay tanggapin!<br/>Galak ng puso''y nag-umapaw sa akin,<br/>Nang Siya ay aking tanggapin!<br/>',NULL,40418,7);
INSERT INTO stanza VALUES('T309','4','Kabalisahan ng buhay ko''y nawala,<br/>Nang si Kristo ay tanggapin!<br/>Kasiyahan ko''y matamis Niyang presensya,<br/>Nang si Kristo ay tanggapin!<br/>',NULL,40419,8);
INSERT INTO stanza VALUES('T309','chorus','Nang si Kristo ay tanggapin!<br/>Nang si Kristo ay tanggapin!<br/>Galak ng puso''y nag-umapaw sa akin,<br/>Nang Siya ay aking tanggapin!<br/>',NULL,40420,9);
INSERT INTO stanza VALUES('T309','5','Iniwan ko ang lumang gawi ng buhay,<br/>Nang si Kristo ay tanggapin!<br/>Mal''walhating pag-asa ang gumagabay,<br/>Nang si Kristo ay tanggapin!<br/>',NULL,40421,10);
INSERT INTO stanza VALUES('T309','chorus','Nang si Kristo ay tanggapin!<br/>Nang si Kristo ay tanggapin!<br/>Galak ng puso''y nag-umapaw sa akin,<br/>Nang Siya ay aking tanggapin!<br/>',NULL,40422,11);
INSERT INTO stanza VALUES('T310','1','Ako''y ginapos ng kasalanan,<br/>Tila aliping nagpumiglas;<br/>Nguni''t natanggap ang kalayaan,<br/>Nang Hesus gapos ko''y kinalas.<br/>',NULL,40423,1);
INSERT INTO stanza VALUES('T310','chorus','Layang marangal, layang magilas,<br/>Sa sala''y di muling maumang!<br/>Hesus ang aking Tagapagligtas,<br/>Siya ay akin magpakailanman.<br/>',NULL,40424,2);
INSERT INTO stanza VALUES('T310','2','Ligtas sa pita at kahalayan,<br/>Ligtas sa inggit, alit, suklam;<br/>Ligtas sa pangmundong karangyaan,<br/>Sa buhay walang kabuluhan.<br/>',NULL,40425,3);
INSERT INTO stanza VALUES('T310','chorus','Layang marangal, layang magilas,<br/>Sa sala''y di muling maumang!<br/>Hesus ang aking Tagapagligtas,<br/>Siya ay akin magpakailanman.<br/>',NULL,40426,4);
INSERT INTO stanza VALUES('T310','3','Ligtas sa katigasa''t sarili,<br/>Ligtas sa kinang ng salapi;<br/>Ligtas sa galit at pagkamuhi,<br/>Sa kalayaan nabighani.<br/>',NULL,40427,5);
INSERT INTO stanza VALUES('T310','chorus','Layang marangal, layang magilas,<br/>Sa sala''y di muling maumang!<br/>Hesus ang aking Tagapagligtas,<br/>Siya ay akin magpakailanman.<br/>',NULL,40428,6);
INSERT INTO stanza VALUES('T310','4','Ligtas sa aking pagkabalisa,<br/>Ligtas sa takot at pangamba;<br/>Kay Kristong Manunubos, malaya,<br/>Pagka''t gapos ko ay sinira.<br/>',NULL,40429,7);
INSERT INTO stanza VALUES('T310','chorus','Layang marangal, layang magilas,<br/>Sa sala''y di muling maumang!<br/>Hesus ang aking Tagapagligtas,<br/>Siya ay akin magpakailanman.<br/>',NULL,40430,8);
INSERT INTO stanza VALUES('T311','1','Pawang biyaya ang natanggap ko,<br/>Nang Siya''y aking pinaniwalaan;<br/>Di kabilang pagpapalalo<br/>Salaring biniyayaan lang!<br/>',NULL,40431,1);
INSERT INTO stanza VALUES('T311','chorus','Makasalanan, ligtas na,<br/>Nang dahil nga sa biyaya!<br/>Diyos papurihan, aking kasaysayan,<br/>Iniligtas nga ng biyaya!<br/>',NULL,40432,2);
INSERT INTO stanza VALUES('T311','2','Dati''y mangmang, nabulag sa sala,<br/>Mga hakbang ko''y palayo sa Diyos;<br/>Hinango ngayon, anong tuwa!<br/>Biyaya''ng nagligtas nang lubos!<br/>',NULL,40433,3);
INSERT INTO stanza VALUES('T311','chorus','Makasalanan, ligtas na,<br/>Nang dahil nga sa biyaya!<br/>Diyos papurihan, aking kasaysayan,<br/>Iniligtas nga ng biyaya!<br/>',NULL,40434,4);
INSERT INTO stanza VALUES('T311','3','Anong silbi ng luha o gawa?<br/>Kung walang habag, ako''y nasawi;<br/>Sa sala''t takot, napalaya,<br/>Sa biyaya ako''y nabawi!<br/>',NULL,40435,5);
INSERT INTO stanza VALUES('T311','chorus','Makasalanan, ligtas na,<br/>Nang dahil nga sa biyaya!<br/>Diyos papurihan, aking kasaysayan,<br/>Iniligtas nga ng biyaya!<br/>',NULL,40436,6);
INSERT INTO stanza VALUES('T311','4','Mahal ko ang aking Panginoon,<br/>Malugod ko Siyang sasalaysayin;<br/>Uulitin kong higit ngayon—<br/>Biyaya''ng nagligtas sa akin!<br/>',NULL,40437,7);
INSERT INTO stanza VALUES('T311','chorus','Makasalanan, ligtas na,<br/>Nang dahil nga sa biyaya!<br/>Diyos papurihan, aking kasaysayan,<br/>Iniligtas nga ng biyaya!<br/>',NULL,40438,8);
INSERT INTO stanza VALUES('T312','1','B''yaya! mapang-akit,<br/>Tugma sa pandinig;<br/>Umalingawngaw sa langit,<br/>Sa lupa''y marinig.<br/>',NULL,40439,1);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40440,2);
INSERT INTO stanza VALUES('T312','2','Biyaya''y sinulat<br/>Ngalan ko sa aklat;<br/>Sa Kordero ''ko''y ''tinapat,<br/>Ako''y pinatawad.<br/>',NULL,40441,3);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40442,4);
INSERT INTO stanza VALUES('T312','3','Biyaya sa akin<br/>Nagturong maglakbay;<br/>Bagong panustos kakamtin,<br/>Kung Diyos ang mag-akay.<br/>',NULL,40443,5);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40444,6);
INSERT INTO stanza VALUES('T312','4','Biyaya''y nagturo,<br/>Pa''nong manalangin;<br/>Hanggang ngayo''y ingat ako,<br/>At di paalisin.<br/>',NULL,40445,7);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40446,8);
INSERT INTO stanza VALUES('T312','5','Biyaya''y maggawad—<br/>Walang hanggang putong;<br/>Sa pag-ibig siya''y nagbuhat,<br/>Sa puri''y hahantong.<br/>',NULL,40447,9);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40448,10);
INSERT INTO stanza VALUES('T312','6','Nawa''y bigyan ako,<br/>Biyayang malakas;<br/>Nang maialay ko sa Iyo,<br/>Ang lahat kong oras.<br/>',NULL,40449,11);
INSERT INTO stanza VALUES('T312','chorus','Biyayang sapat!<br/>Lakas di salat!<br/>Kristo sa ''kin nanahan,<br/>Sa kasaganaan.<br/>',NULL,40450,12);
INSERT INTO stanza VALUES('T313','1','Biyayang kamangha-mangha,<br/>Sa aki''y nagligtas!<br/>''Ko''y nawala, hinanap Niya,<br/>Mata ko''y bumukas.<br/>',NULL,40451,1);
INSERT INTO stanza VALUES('T313','2','Puso ko ay pumayapa,<br/>Dahil sa biyaya;<br/>Kay inam nang masumpungan<br/>At mapanaligan!<br/>',NULL,40452,2);
INSERT INTO stanza VALUES('T313','3','Kay buti ng pangako Niya,<br/>Siya''y maaasahan;<br/>Bahagi''t kalasag ko Siya<br/>Magpakailan pa man.<br/>',NULL,40453,3);
INSERT INTO stanza VALUES('T313','4','Pagsapit ng walang hanggan,<br/>L''walhating makislap,<br/>Diyos ay ating parangalan,<br/>Papuri''y maganap.<br/>',NULL,40454,4);
INSERT INTO stanza VALUES('T316','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40455,1);
INSERT INTO stanza VALUES('T316','1','Mapapatid taling pilak,<br/>Awit ko''y maghuhumpay na;<br/>Nang magising, anong galak,<br/>Hari ko''y aking makita.<br/>',NULL,40456,2);
INSERT INTO stanza VALUES('T316','chorus','Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya;<br/>Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya.<br/>',NULL,40457,3);
INSERT INTO stanza VALUES('T316','2','Panlupang bahay guguho,<br/>Di ko alam kung kailan;<br/>Nguni''t ako ay tutungo<br/>Sa matamis Niyang harapan.<br/>',NULL,40458,4);
INSERT INTO stanza VALUES('T316','chorus','Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya;<br/>Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya.<br/>',NULL,40459,5);
INSERT INTO stanza VALUES('T316','3','Sa araw ng Kanyang dating,<br/>Matapos din ang paggawa;<br/>Aniya, "Tapat na alipin,"<br/>Pahinga''y matatamasa.<br/>',NULL,40460,6);
INSERT INTO stanza VALUES('T316','chorus','Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya;<br/>Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya.<br/>',NULL,40461,7);
INSERT INTO stanza VALUES('T316','4','Kaya''t ako''y naghahanda,<br/>Nagpupuyat, may ilawan;<br/>Sa araw ng pagkikita,<br/>Presensya Niya''y walang hanggan.<br/>',NULL,40462,8);
INSERT INTO stanza VALUES('T316','chorus','Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya;<br/>Ako at Siya''y magpangita,<br/>Sasaysayin biyaya Niya.<br/>',NULL,40463,9);
INSERT INTO stanza VALUES('T319','1','Lapit, Bukal ng biyaya,<br/>Paawitin puso ko;<br/>Daloy pa, Ilog ng awa,<br/>Laksan ang puri sa Iyo.<br/>Nang ako''y malayo sa Diyos,<br/>Pinaghanap ni Hesus,<br/>At ako''y Kanyang tinubos,<br/>Dugo Niya''y ibinuhos.<br/>',NULL,40464,1);
INSERT INTO stanza VALUES('T319','2','Nagkautang sa biyaya,<br/>Ako''y napilit t''wina!<br/>Poon, nawa Iyong biyaya,<br/>Talian pusong gala.<br/>Landas Mo''y ituro sa ''kin,<br/>Biyaya Mo''y subukin,<br/>Pag-ibig ng Diyos tamuhin,<br/>Halaga Niya''y awitin.<br/>',NULL,40465,2);
INSERT INTO stanza VALUES('T319','3','May pangamba na gumala;<br/>Lisanin Diyos kong mahal:<br/>Puso ko''y bihagin nawa<br/>Ng Espiritung banal.<br/>Ligtas sa sala''t panganib,<br/>Binili na ng dugo,<br/>Dayuhan lamang sa lupa,<br/>Sa Diyos tagapagmana.<br/>',NULL,40466,3);
INSERT INTO stanza VALUES('T321','1','Ang kumpletong kaligtasan,<br/>Ang bukal na nabuksan,<br/>Mula sa tagiliran Niya,<br/>Tungo sa bawa''t bansa.<br/>Kaligtasang ganap, lubos!<br/>Sa dugong umaagos.<br/>',NULL,40467,1);
INSERT INTO stanza VALUES('T321','2','O mal''walhating pahayag!<br/>Ang sala''y napatawad<br/>Ng agos na naglilinis<br/>Gaya''y niebeng maputi:<br/>Ang kumpletong kaligtasan!<br/>O anong kagalakan.<br/>',NULL,40468,2);
INSERT INTO stanza VALUES('T321','3','Pag-ibig inaagusan<br/>Buo kong katauhan;<br/>Isip, damdamin, kalo''ban,<br/>Nang laging malinisan:<br/>Ang kumpletong kaligtasan!<br/>Mula sa kasalanan.<br/>',NULL,40469,3);
INSERT INTO stanza VALUES('T321','4','Kristo''y buhay walang hanggan,<br/>Sa puso ko nanahan:<br/>Diyos naihalo sa tao,<br/>Pagsalamuhang wasto.<br/>Anong kaligtasan ito!<br/>Kristo''y buhay dibino!<br/>',NULL,40470,4);
INSERT INTO stanza VALUES('T321','5','Wala na sa ''kin ang duda,<br/>Maging lumbay, pangamba;<br/>Walang dilim sa panalig,<br/>Sundan Siya nang mahigpit:<br/>O kumpletong kaligtasan!<br/>Ganap magpakailanman!<br/>',NULL,40471,5);
INSERT INTO stanza VALUES('T322','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40472,1);
INSERT INTO stanza VALUES('T322','1','Malaon nang naghahanap ng bukal,<br/>Di-matuyong batisan;<br/>Walang bisa ang sa lupa''y magpagal,<br/>Wala ring kasiyahan.<br/>',NULL,40473,2);
INSERT INTO stanza VALUES('T322','chorus','Iniinom ko ang tubig ng buhay,<br/>Sa bukal, di-matuyong batisan;<br/>Kagalakang tunay,<br/>Walang katapusan<br/>Umiinom ng tubig ng buhay.<br/>',NULL,40474,3);
INSERT INTO stanza VALUES('T322','2','Sa ilang ng sala''y di na gagala,<br/>Bukal natagpuan na,<br/>Kagalakan ko''y umapaw, bumaha,<br/>Kristo ang nagpasaya.<br/>',NULL,40475,4);
INSERT INTO stanza VALUES('T322','chorus','Iniinom ko ang tubig ng buhay,<br/>Sa bukal, di-matuyong batisan;<br/>Kagalakang tunay,<br/>Walang katapusan<br/>Umiinom ng tubig ng buhay.<br/>',NULL,40476,5);
INSERT INTO stanza VALUES('T322','3','Kasiyahan ay lalong tumatamis,<br/>Kay Kristo may pahinga;<br/>Kaaliwan dito ay labis-labis,<br/>Ako ay pinagpala.<br/>',NULL,40477,6);
INSERT INTO stanza VALUES('T322','chorus','Iniinom ko ang tubig ng buhay,<br/>Sa bukal, di-matuyong batisan;<br/>Kagalakang tunay,<br/>Walang katapusan<br/>Umiinom ng tubig ng buhay.<br/>',NULL,40478,7);
INSERT INTO stanza VALUES('T322','4','Walang tigil ang pagtutustos dito,<br/>Sa biyaya''y maligo;<br/>Sa bukal na nagpapagaling mismo,<br/>Mamamalagi ako.<br/>',NULL,40479,8);
INSERT INTO stanza VALUES('T322','chorus','Iniinom ko ang tubig ng buhay,<br/>Sa bukal, di-matuyong batisan;<br/>Kagalakang tunay,<br/>Walang katapusan<br/>Umiinom ng tubig ng buhay.<br/>',NULL,40480,9);
INSERT INTO stanza VALUES('T323','1','Tinig ni Hesus dinig ko,<br/>"Halina sa Akin,<br/>Ang nabibigatang-loob,<br/>Magpahinga sa ''Kin."<br/>Pagal, pagod, at pighati<br/>Sa Kanya''y lumapit<br/>Sa Kanya ''ko napahinga<br/>Puso ko''y sumaya.<br/>',NULL,40481,1);
INSERT INTO stanza VALUES('T323','2','Tinig ni Hesus dinig ko,<br/>"Libre kong ''binigay<br/>Sa uhaw na kaluluwa<br/>Ang tubig ng buhay."<br/>Kay Hesus ako''y uminom,<br/>Bukal, bigay buhay,<br/>Pag-inom, uhaw napawi,<br/>Kalul''wa''y nabawi.<br/>',NULL,40482,2);
INSERT INTO stanza VALUES('T323','3','Tinig ni Hesus dinig ko,<br/>" ''Ko''y Ilaw ng mundo<br/>Tingnan Ako''t umaga mo<br/>Magpasigla sa Iyo."<br/>Babaling ako kay Hesus<br/>Aking Araw, Tala.<br/>Kaya''t sa Kanyang Liwanag<br/>Lakad na may galak.<br/>',NULL,40483,3);
INSERT INTO stanza VALUES('T324','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40484,1);
INSERT INTO stanza VALUES('T324','1','Noon sa Ehipto ako''y alipin ng sala,<br/>Bigat ng sala''y dumagsa, walang payapa;<br/>Ngayon makalupang bagay di ako madala,<br/>Di matinag sa mabuting lupa.<br/>',NULL,40485,2);
INSERT INTO stanza VALUES('T324','chorus','Sa bundok nakatira, langit maaliwalas,<br/>Sa bukal umiinom, laging umaawas;<br/>Oo, ako ay nagpipista sa mannang masagana,<br/>''Pagkat nasa mabuting lupa!<br/>',NULL,40486,3);
INSERT INTO stanza VALUES('T324','2','Kordero ng Paskua sa ''kin dugo Niya''y tumubos,<br/>Ako ay nabautismuhan, malayang lubos;<br/>Kahit may pagsubok may lakas namang tumustos,<br/>Sa mabuting lupa ay maayos!<br/>',NULL,40487,4);
INSERT INTO stanza VALUES('T324','chorus','Sa bundok nakatira, langit maaliwalas,<br/>Sa bukal umiinom, laging umaawas;<br/>Oo, ako ay nagpipista sa mannang masagana,<br/>''Pagkat nasa mabuting lupa!<br/>',NULL,40488,5);
INSERT INTO stanza VALUES('T324','3','Iniakyat ni Kristo na kasamang naupo,<br/>Kapangyarihan ng diyablo''y lubos natalo;<br/>Sa ngalan ng Panginoon, Hades nagapi na,<br/>Matagumpay sa mabuting lupa.<br/>',NULL,40489,6);
INSERT INTO stanza VALUES('T324','chorus','Sa bundok nakatira, langit maaliwalas,<br/>Sa bukal umiinom, laging umaawas;<br/>Oo, ako ay nagpipista sa mannang masagana,<br/>''Pagkat nasa mabuting lupa!<br/>',NULL,40490,7);
INSERT INTO stanza VALUES('T324','4','Dito''y may kapayapaan, anong kagalakan,<br/>Wala nang pagkaulila at kapanglawan;<br/>Bawa''t dako''y may awit, kay tamis ng pagsinta,<br/>Aleluya mabuti ngang lupa.<br/>',NULL,40491,8);
INSERT INTO stanza VALUES('T324','chorus','Sa bundok nakatira, langit maaliwalas,<br/>Sa bukal umiinom, laging umaawas;<br/>Oo, ako ay nagpipista sa mannang masagana,<br/>''Pagkat nasa mabuting lupa!<br/>',NULL,40492,9);
INSERT INTO stanza VALUES('T325','1','Malaon nang naghahanap<br/>Ng bukal na malamig,<br/>Nang mapawi ang init ng<br/>Uhaw sa Kanyang tubig.<br/>',NULL,40493,1);
INSERT INTO stanza VALUES('T325','chorus','Aleluya! Natagpuan<br/>Inaasam kong lunas!<br/>Kay Hesus may kasiyahan;<br/>Buhay Niya ang nagligtas.<br/>',NULL,40494,2);
INSERT INTO stanza VALUES('T325','2','Ipa lang ang kinakain,<br/>Lakas halos ubusin,<br/>Lalong masarap mithiin,<br/>Lalo pang gugutumin.<br/>',NULL,40495,3);
INSERT INTO stanza VALUES('T325','chorus','Aleluya! Natagpuan<br/>Inaasam kong lunas!<br/>Kay Hesus may kasiyahan;<br/>Buhay Niya ang nagligtas.<br/>',NULL,40496,4);
INSERT INTO stanza VALUES('T325','3','Dukhang nagnasa ng yamang<br/>Magbigay kasiyahan,<br/>Sukal ang natamo lamang,<br/>Samo''y pinagtawanan.<br/>',NULL,40497,5);
INSERT INTO stanza VALUES('T325','chorus','Aleluya! Natagpuan<br/>Inaasam kong lunas!<br/>Kay Hesus may kasiyahan;<br/>Buhay Niya ang nagligtas.<br/>',NULL,40498,6);
INSERT INTO stanza VALUES('T325','4','Bukal ng tubig umagos,<br/>Tinapay tumutustos,<br/>Yamang hindi mauubos,<br/>Ang aking Manunubos.<br/>',NULL,40499,7);
INSERT INTO stanza VALUES('T325','chorus','Aleluya! Natagpuan<br/>Inaasam kong lunas!<br/>Kay Hesus may kasiyahan;<br/>Buhay Niya ang nagligtas.<br/>',NULL,40500,8);
INSERT INTO stanza VALUES('T333','1','Hindi ko natatalos kung bakit<br/>''Ko''y tinubos ng pag-ibig,<br/>Biyaya''y inihayag sa akin,<br/>Nang kay Hesus mapaangkin.<br/>',NULL,40501,1);
INSERT INTO stanza VALUES('T333','chorus','Nguni''t aking talos kung sino<br/>Ang aking pinaniniwalaan;<br/>Iingatan Niya tiyak ako<br/>Hanggang sa walang hanggan.<br/>',NULL,40502,2);
INSERT INTO stanza VALUES('T333','2','Kung papaano sa pananalig<br/>Ang maligtas di ko batid,<br/>At sa ''king pananampalataya<br/>Ang puso ko''y mapayapa.<br/>',NULL,40503,3);
INSERT INTO stanza VALUES('T333','chorus','Nguni''t aking talos kung sino<br/>Ang aking pinaniniwalaan;<br/>Iingatan Niya tiyak ako<br/>Hanggang sa walang hanggan.<br/>',NULL,40504,4);
INSERT INTO stanza VALUES('T333','3','Di ko natatalos kung paano<br/>Napaamin ng ''Spiritu<br/>Ang tao sa sarili niyang sala,<br/>Sa Diyos sumampalataya.<br/>',NULL,40505,5);
INSERT INTO stanza VALUES('T333','chorus','Nguni''t aking talos kung sino<br/>Ang aking pinaniniwalaan;<br/>Iingatan Niya tiyak ako<br/>Hanggang sa walang hanggan.<br/>',NULL,40506,6);
INSERT INTO stanza VALUES('T333','4','Hindi ko natatalos kung anong<br/>Buti o sama mayroon,<br/>Hirap o ginhawa para sa ''kin<br/>Bago si Hesus dumating.<br/>',NULL,40507,7);
INSERT INTO stanza VALUES('T333','chorus','Nguni''t aking talos kung sino<br/>Ang aking pinaniniwalaan;<br/>Iingatan Niya tiyak ako<br/>Hanggang sa walang hanggan.<br/>',NULL,40508,8);
INSERT INTO stanza VALUES('T333','5','Di ko natatalos ang pagbalik<br/>Ni Hesus mula sa langit,<br/>Siya ba ay aking sasalubungin,<br/>Sa araw o takip-silim.<br/>',NULL,40509,9);
INSERT INTO stanza VALUES('T333','chorus','Nguni''t aking talos kung sino<br/>Ang aking pinaniniwalaan;<br/>Iingatan Niya tiyak ako<br/>Hanggang sa walang hanggan.<br/>',NULL,40510,10);
INSERT INTO stanza VALUES('T334','1','Si Hesus Poon na Tagapagligtas,<br/>Sadyang kagila-gilalas;<br/>Kinukubli Niya ang kaluluwa ko<br/>Doon sa bitak ng bato.<br/>',NULL,40511,1);
INSERT INTO stanza VALUES('T334','chorus','Kinukubli ni Hesus aking buhay<br/>Doon sa bitak ng bato,<br/>Kinukubli ni Hesus aking buhay<br/>Sa Kanyang pag-ibig taglay,<br/>Sa Kanyang pag-ibig taglay.<br/>',NULL,40512,2);
INSERT INTO stanza VALUES('T334','2','Kagila-gilalas ang Poong Hesus,<br/>Hirap ko inalis lubos;<br/>Inaalalayan ako ni Hesus<br/>At di ako makikilos.<br/>',NULL,40513,3);
INSERT INTO stanza VALUES('T334','chorus','Kinukubli ni Hesus aking buhay<br/>Doon sa bitak ng bato,<br/>Kinukubli ni Hesus aking buhay<br/>Sa Kanyang pag-ibig taglay,<br/>Sa Kanyang pag-ibig taglay.<br/>',NULL,40514,4);
INSERT INTO stanza VALUES('T334','3','Biyaya Niya sa akin pinuputong,<br/>Sa kabanalan Niya''ng hantong;<br/>"Purihin ang Diyos!" awit ay ilakas<br/>Sa aking Tagapagligtas!<br/>',NULL,40515,5);
INSERT INTO stanza VALUES('T334','chorus','Kinukubli ni Hesus aking buhay<br/>Doon sa bitak ng bato,<br/>Kinukubli ni Hesus aking buhay<br/>Sa Kanyang pag-ibig taglay,<br/>Sa Kanyang pag-ibig taglay.<br/>',NULL,40516,6);
INSERT INTO stanza VALUES('T334','4','''Pag nasuutan ng Kanyang liwanag,<br/>Ako sa Kanya''y haharap;<br/>Kasama ng milyon ipagtatanghal<br/>Kaligtasan, pagmamahal.<br/>',NULL,40517,7);
INSERT INTO stanza VALUES('T334','chorus','Kinukubli ni Hesus aking buhay<br/>Doon sa bitak ng bato,<br/>Kinukubli ni Hesus aking buhay<br/>Sa Kanyang pag-ibig taglay,<br/>Sa Kanyang pag-ibig taglay.<br/>',NULL,40518,8);
INSERT INTO stanza VALUES('T337','1','Salaysay ay aawitin<br/>Si Hesus na namatay;<br/>Iniwan pati langit din,<br/>Pagtubos maibigay.<br/>',NULL,40519,1);
INSERT INTO stanza VALUES('T337','chorus','Awitin ko, kasaysayan,<br/>Ng Kristo na namatay,<br/>Aawitin, luwalhatiin,<br/>Walang hanggang salaysay.<br/>',NULL,40520,2);
INSERT INTO stanza VALUES('T337','2','Ako''y naligaw na tupa,<br/>Hinanap, natagpuan;<br/>Inakay at niyapos Niya,<br/>Iwinasto ang daan.<br/>',NULL,40521,3);
INSERT INTO stanza VALUES('T337','chorus','Awitin ko, kasaysayan,<br/>Ng Kristo na namatay,<br/>Aawitin, luwalhatiin,<br/>Walang hanggang salaysay.<br/>',NULL,40522,4);
INSERT INTO stanza VALUES('T337','3','Ako''y nasaktan, nanghina,<br/>Si Hesus nagpalunas;<br/>Natakot, walang makita,<br/>Ako''y Kanyang ''niligtas.<br/>',NULL,40523,5);
INSERT INTO stanza VALUES('T337','chorus','Awitin ko, kasaysayan,<br/>Ng Kristo na namatay,<br/>Aawitin, luwalhatiin,<br/>Walang hanggang salaysay.<br/>',NULL,40524,6);
INSERT INTO stanza VALUES('T337','4','Dilim ay banta sa akin,<br/>Daan ay may pighati;<br/>Nguni''t Siya''y laging kapiling,<br/>Akay sa araw-gabi.<br/>',NULL,40525,7);
INSERT INTO stanza VALUES('T337','chorus','Awitin ko, kasaysayan,<br/>Ng Kristo na namatay,<br/>Aawitin, luwalhatiin,<br/>Walang hanggang salaysay.<br/>',NULL,40526,8);
INSERT INTO stanza VALUES('T337','5','Ako''y Kanyang iingatan<br/>Hanggang sa pagbalik Niya;<br/>Binabago Niyang lubusan<br/>Hanggang sa magpangita.<br/>',NULL,40527,9);
INSERT INTO stanza VALUES('T337','chorus','Awitin ko, kasaysayan,<br/>Ng Kristo na namatay,<br/>Aawitin, luwalhatiin,<br/>Walang hanggang salaysay.<br/>',NULL,40528,10);
INSERT INTO stanza VALUES('T339','1','Mga banal, kay tibay na saligan<br/>Ang Salitang sinampalatayanan!<br/>Ti-yak Niya kayong pinapangakuan,<br/>Kayong lumapit kay Hesus, kanlungan.<br/>',NULL,40529,1);
INSERT INTO stanza VALUES('T339','2','"Huwag kang matakot, Ako''y iyong kasama,<br/>Ako ang Diyos mong laang sumaklolo;<br/>Palalakasin ka, tutulungan ka,<br/>Hahawakan ka ng mga kamay Ko.<br/>',NULL,40530,2);
INSERT INTO stanza VALUES('T339','3','"Sa lalim ng tubig kung suguin ka<br/>Sa agos ng ilog, walang pangamba;<br/>Sa mga pagsubok Ako''y kasama,<br/>Sa iyong dusa ma''y babanalin kita.<br/>',NULL,40531,3);
INSERT INTO stanza VALUES('T339','4','"Maapoy man pagsubok sa iyong daan,<br/>Sapat ang biyaya Kong ibibigay;<br/>Apoy man nito''y di ka masasaktan,<br/>Kundi sa Iyo''y paglinis, pagdalisay.<br/>',NULL,40532,4);
INSERT INTO stanza VALUES('T339','5','Lipas man panahon patutunayan<br/>Aking bayan pag-ibig walang hanggan;<br/>Magayakan man puting buhok templo<br/>Dalhin din silang tulad ng kordero.<br/>',NULL,40533,5);
INSERT INTO stanza VALUES('T339','6','"Kalul''wang kay Kristo''y namamahinga<br/>Hindi Ko iiwan sa kabaka niya.<br/>Kahit ang Hades ay pangatugin siya,<br/>Ako''y hinding-hindi magpapabaya!"<br/>',NULL,40534,6);
INSERT INTO stanza VALUES('T341','1','Kung kapayapaa''y ilog na akbay,<br/>Kung bagyuhin man ng lumbay;<br/>Ang itinuro Mo''y aking sinaysay,<br/>Kaluluwa ko''y matiwasay.<br/>',NULL,40535,1);
INSERT INTO stanza VALUES('T341','chorus','Kalul''wa''y mahusay,<br/>Kaluluwa ko''y matiwasay.<br/>',NULL,40536,2);
INSERT INTO stanza VALUES('T341','2','Mayro''n mang tukso at mga pagsubok,<br/>Pagtitiwala ko''y lubos,<br/>Kaluluwa ko''y laging kinukupkop,<br/>Ang dugo Niya''y sa krus nabuhos.<br/>',NULL,40537,3);
INSERT INTO stanza VALUES('T341','chorus','Kalul''wa''y mahusay,<br/>Kaluluwa ko''y matiwasay.<br/>',NULL,40538,4);
INSERT INTO stanza VALUES('T341','3','Mga kasalana''t lisyang gawain,<br/>Wala nang lahat sa akin,<br/>Napako si Hesus, Kanyang inangkin,<br/>Kaluluwa ko, Siya''y purihin.<br/>',NULL,40539,5);
INSERT INTO stanza VALUES('T341','chorus','Kalul''wa''y mahusay,<br/>Kaluluwa ko''y matiwasay.<br/>',NULL,40540,6);
INSERT INTO stanza VALUES('T341','4','Sa ganang akin, si Kristo ang ibuhay;<br/>Maging madilim ang daan,<br/>Panatag sa kamatayan o buhay,<br/>Kalul''wa''y may kapayapaan.<br/>',NULL,40541,7);
INSERT INTO stanza VALUES('T341','chorus','Kalul''wa''y mahusay,<br/>Kaluluwa ko''y matiwasay.<br/>',NULL,40542,8);
INSERT INTO stanza VALUES('T342','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40543,1);
INSERT INTO stanza VALUES('T342','1','Ginugol ko maraming taon,<br/>Di pinansin ang Panginoon,<br/>Maging kamatayan Niya roon<br/>Sa Kalbaryo.<br/>',NULL,40544,2);
INSERT INTO stanza VALUES('T342','chorus','Awang dakila, libreng b''yaya;<br/>Higit na patawad sa sala;<br/>Mula sa bigat napalaya,<br/>Sa Kalbaryo.<br/>',NULL,40545,3);
INSERT INTO stanza VALUES('T342','2','Sa ilaw Niya, nalaman sala<br/>Sa harap ng utos nangamba,<br/>Sa pagbaling, takot nawala<br/>Sa Kalbaryo.<br/>',NULL,40546,4);
INSERT INTO stanza VALUES('T342','chorus','Awang dakila, libreng b''yaya;<br/>Higit na patawad sa sala;<br/>Mula sa bigat napalaya,<br/>Sa Kalbaryo.<br/>',NULL,40547,5);
INSERT INTO stanza VALUES('T342','3','Lahat Ko''y ''binigay sa Kanya,<br/>Puso''y bukal pagharian Niya,<br/>Di malimutan Kanyang dusa<br/>Sa Kalbaryo.<br/>',NULL,40548,6);
INSERT INTO stanza VALUES('T342','chorus','Awang dakila, libreng b''yaya;<br/>Higit na patawad sa sala;<br/>Mula sa bigat napalaya,<br/>Sa Kalbaryo.<br/>',NULL,40549,7);
INSERT INTO stanza VALUES('T342','4','Pag-ibig balak kaligtasan,<br/>B''yayang tungong sangkatauhan;<br/>''Binalik ako sa Diyos lamang,<br/>Sa Kalbaryo.<br/>',NULL,40550,8);
INSERT INTO stanza VALUES('T342','chorus','Awang dakila, libreng b''yaya;<br/>Higit na patawad sa sala;<br/>Mula sa bigat napalaya,<br/>Sa Kalbaryo.<br/>',NULL,40551,9);
INSERT INTO stanza VALUES('T343','1','Sa kalul''wa may sinag-araw,<br/>Lalong gumigitaw;<br/>Paligid ko''y tumatanglaw,<br/>Si Hesus ang Ilaw.<br/>',NULL,40552,1);
INSERT INTO stanza VALUES('T343','chorus','Mal''walhating sinag-araw,<br/>Galak at aliw umaapaw;<br/>Nang ngiti ni Hesus matanaw<br/>Puspos ng sinag-araw.<br/>',NULL,40553,2);
INSERT INTO stanza VALUES('T343','2','Sa kalul''wa ko ay may awit,<br/>Na di ko maawit;<br/>Awit para sa hari ko<br/>Hesus, nakikinig.<br/>',NULL,40554,3);
INSERT INTO stanza VALUES('T343','chorus','Mal''walhating sinag-araw,<br/>Galak at aliw umaapaw;<br/>Nang ngiti ni Hesus matanaw<br/>Puspos ng sinag-araw.<br/>',NULL,40555,4);
INSERT INTO stanza VALUES('T343','3','Ang tagsibol ay bumubungad,<br/>Pag si Kristo''y hangad;<br/>Puso tila''y lumilipad,<br/>B''yaya''y namukadkad.<br/>',NULL,40556,5);
INSERT INTO stanza VALUES('T343','chorus','Mal''walhating sinag-araw,<br/>Galak at aliw umaapaw;<br/>Nang ngiti ni Hesus matanaw<br/>Puspos ng sinag-araw.<br/>',NULL,40557,6);
INSERT INTO stanza VALUES('T343','4','May galak ngayon sa kalul''wa,<br/>Puri at pag-asa;<br/>Pag-ibig at pagpapala<br/>Kay taas ligaya.<br/>',NULL,40558,7);
INSERT INTO stanza VALUES('T343','chorus','Mal''walhating sinag-araw,<br/>Galak at aliw umaapaw;<br/>Nang ngiti ni Hesus matanaw<br/>Puspos ng sinag-araw.<br/>',NULL,40559,8);
INSERT INTO stanza VALUES('T346','1','Walang galing umunawa,<br/>Sa layon ng Diyos, balak Niya;<br/>Datapuwa''t sa Kanyang kanan<br/>Manliligtas ko nand''yan!<br/>',NULL,40560,1);
INSERT INTO stanza VALUES('T346','2','Kristo''y nam''tay sa maysala,<br/>Nabasa ko''t naniwala;<br/>Maging Manliligtas ko Siya<br/>Ang ka-i-langan ko nga!<br/>',NULL,40561,2);
INSERT INTO stanza VALUES('T346','3','Pook matayog iniwan,<br/>Para sa makasalanan,<br/>Noon aking pinagtakhan<br/>Ngayon aking nalaman!<br/>',NULL,40562,3);
INSERT INTO stanza VALUES('T346','4','Nawa sa ''kin makita Niya<br/>Bunga ng Kanyang pagdusa,<br/>Nang Siya''y mas''yahan sa gawa,<br/>Katulad ko sa Kanya.<br/>',NULL,40563,4);
INSERT INTO stanza VALUES('T346','5','Buhay man o kamatayan<br/>Siya ang aking kaaliwan;<br/>Dina''nan Niyang kamatayan<br/>Haring buháy kailanman.<br/>',NULL,40564,5);
INSERT INTO stanza VALUES('T347','1','Ngayong araw, pinili ko,<br/>Hesus Tagapagligtas ko!<br/>Puso''y nagningas sa galak<br/>Ipagsabing may halakhak.<br/>',NULL,40565,1);
INSERT INTO stanza VALUES('T347','chorus','Araw ay kay saya,<br/>Ako''y niligtas sa sala!<br/>Ako ay tinuruan Niya<br/>Magbantay at manalangin<br/>Naging magalakin<br/>Hesus naglinis sa akin.<br/>',NULL,40566,2);
INSERT INTO stanza VALUES('T347','2','Di nagsisi nang maangkin;<br/>Ako''y Kanya, Siya ay akin;<br/>Siya''y nag-akit, aking sundin,<br/>Pagtawag Niya''y tutugunin.<br/>',NULL,40567,3);
INSERT INTO stanza VALUES('T347','chorus','Araw ay kay saya,<br/>Ako''y niligtas sa sala!<br/>Ako ay tinuruan Niya<br/>Magbantay at manalangin<br/>Naging magalakin<br/>Hesus naglinis sa akin.<br/>',NULL,40568,4);
INSERT INTO stanza VALUES('T347','3','Nagdalawang isip noon,<br/>Panginoon sentro ngayon;<br/>Siya lamang wala nang iba,<br/>Pumuno sa ''kin ng saya.<br/>',NULL,40569,5);
INSERT INTO stanza VALUES('T347','chorus','Araw ay kay saya,<br/>Ako''y niligtas sa sala!<br/>Ako ay tinuruan Niya<br/>Magbantay at manalangin<br/>Naging magalakin<br/>Hesus naglinis sa akin.<br/>',NULL,40570,6);
INSERT INTO stanza VALUES('T347','4','Pakinggan Mo, panata ko,<br/>Araw-araw napabago!<br/>Hanggang huling sandali ko,<br/>Ako ay pagpalain Mo.<br/>',NULL,40571,7);
INSERT INTO stanza VALUES('T347','chorus','Araw ay kay saya,<br/>Ako''y niligtas sa sala!<br/>Ako ay tinuruan Niya<br/>Magbantay at manalangin<br/>Naging magalakin<br/>Hesus naglinis sa akin.<br/>',NULL,40572,8);
INSERT INTO stanza VALUES('T348','1','Buhay ko''y naging masaya,<br/>Nang ako ay mapalaya;<br/>Ni Kristo mula sa sala,<br/>Aliw, Hesus nakilala.<br/>',NULL,40573,1);
INSERT INTO stanza VALUES('T348','chorus','Aleluya, anong saya!<br/>Pagka''t Hesus natamasa!<br/>Kung naroroon si Hesus,<br/>Nagagalak akong lubos.<br/>',NULL,40574,2);
INSERT INTO stanza VALUES('T348','2','Buhay ko''y dating kay saklap<br/>Hanggang Hesus ay nahanap;<br/>Sa kalul''wa''y kagalakan,<br/>Ngayon at magpakailanman.<br/>',NULL,40575,3);
INSERT INTO stanza VALUES('T348','chorus','Aleluya, anong saya!<br/>Pagka''t Hesus natamasa!<br/>Kung naroroon si Hesus,<br/>Nagagalak akong lubos.<br/>',NULL,40576,4);
INSERT INTO stanza VALUES('T348','3','Saan man tayo manahan,<br/>Sa bukid o sa bundok man,<br/>Kung naroroon si Hesus,<br/>Nagagalak akong lubos.<br/>',NULL,40577,5);
INSERT INTO stanza VALUES('T348','chorus','Aleluya, anong saya!<br/>Pagka''t Hesus natamasa!<br/>Kung naroroon si Hesus,<br/>Nagagalak akong lubos.<br/>',NULL,40578,6);
INSERT INTO stanza VALUES('T349','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40579,1);
INSERT INTO stanza VALUES('T349','1','Tila''y usang tinutugis<br/>Na uhaw sa batis,<br/>Gayon ang puso ko sa Iyo,<br/>Mapanariwa Mo.<br/>',NULL,40580,2);
INSERT INTO stanza VALUES('T349','2','Diyos na buháy, Pangino''n ko,<br/>Uhaw ako sa Iyo;<br/>Hangad Kitang malapitan,<br/>Higpit na kapitan.<br/>',NULL,40581,3);
INSERT INTO stanza VALUES('T349','3','Ika''y buhay at lakas ko,<br/>Pati tahanan ko;<br/>Kay Kristo, nabusog ako<br/>At Kita''y natamo.<br/>',NULL,40582,4);
INSERT INTO stanza VALUES('T349','4','Ngiti Mo''y kaligtasan ko,<br/>Nakatingin sa Iyo;<br/>Presensya Mo''y aking hiling,<br/>Masaganang akin.<br/>',NULL,40583,5);
INSERT INTO stanza VALUES('T349','5','Ang gaya ko''y usang uhaw,<br/>Ang lunas ay Ikaw;<br/>Liban sa Iyo''y walang iba<br/>Aking ninanasa.<br/>',NULL,40584,6);
INSERT INTO stanza VALUES('T350','1','Puso ko''y humabol sa Diyos Mismo,<br/>Hindi sa mabuting kapalaran;<br/>Kanyang biyaya, ''di sarili ko<br/>Ang pumatnubay sa kabanalan.<br/>',NULL,40585,1);
INSERT INTO stanza VALUES('T350','2','Pag-ibig, pananampalataya,<br/>Ang batayan ko, nang Diyos makamtan,<br/>Sa sarili ko''y ililigtas Niya,<br/>Hanggang ako''y Kanyang mapuspusan.<br/>',NULL,40586,2);
INSERT INTO stanza VALUES('T350','3','Kahit nakakatakot ang daan,<br/>Kahit malaki ang kabayaran,<br/>Alam ng Diyos ang aking kailangan,<br/>Sa landas Niya ako''y gagabayan.<br/>',NULL,40587,3);
INSERT INTO stanza VALUES('T350','4','Di Siya nagkakamali, alam ko,<br/>Hahabulin Siya, ang gagawin ko,<br/>Araw-araw Siya''y aking matamo,<br/>Gawad ko ang l''walhati — Diyos Mismo.<br/>',NULL,40588,4);
INSERT INTO stanza VALUES('T351','1','Dakilang Diyos, Buhay Di-Nilikha,<br/>Pakinggan ako dito sa lupa,<br/>Di masayod gloria tungkol sa Iyo;<br/>Manlilikha, dapat mabatid ko.<br/>',NULL,40589,1);
INSERT INTO stanza VALUES('T351','2','Sa krus matinding hirap ni Kristo,<br/>Bisa ng kamatayang inako,<br/>Mula sa dilim ako''y ''nilipat<br/>Tungong kahariang maliwanag.<br/>',NULL,40590,2);
INSERT INTO stanza VALUES('T351','3','Mula sa sentro punuin ako,<br/>Maging sa paligid punuin Mo;<br/>Masinag l''walhati''t liwanag Mo,<br/>Nawa, O sa pamamagitan ko!<br/>',NULL,40591,3);
INSERT INTO stanza VALUES('T351','4','Diyos na banal, ''Di-nilikhang Buhay,<br/>Espiritung nagbibigay-buhay<br/>Likhain sa ''kin ang mahayag Ka,<br/>Maakit sa Iyo walang iba na.<br/>',NULL,40592,4);
INSERT INTO stanza VALUES('T351','5','Salamat Diyos Ama sa Iyong b''yaya,<br/>Sa buhay ako''y naghahari na;<br/>Si Kristo aking kasamang Hari,<br/>Ako''y nasiyahan, Siya''y nagwagi.<br/>',NULL,40593,5);
INSERT INTO stanza VALUES('T352','1','Sa ilang para sa Diyos!<br/>Dawag na umaapoy!<br/>Ako''y ganito lamang,<br/>L''walhatiin Iyong Ngalan.<br/>',NULL,40594,1);
INSERT INTO stanza VALUES('T352','2','Dawag pangkaraniwan,<br/>Nguni''t Kanyang natirhan,<br/>Diyos makapagsalita,<br/>Sa pamamagitan niya.<br/>',NULL,40595,2);
INSERT INTO stanza VALUES('T352','3','Natupok di dawag nga,<br/>Liyab di makalupa;<br/>Liban sa mahayag Siya,<br/>Diyos walang ibang nasa.<br/>',NULL,40596,3);
INSERT INTO stanza VALUES('T352','4','Diyos sa loob ng dawag,<br/>Nakita lamang alab;<br/>Gawin akong ganito,<br/>Mal''walhati Ngalan Mo.<br/>',NULL,40597,4);
INSERT INTO stanza VALUES('T354','1','Pasok, O pasok! bukas ang pinto;<br/>Ito''y Iyong tinig, nakilala ko;<br/>Araw lumubog; humihip hangin;<br/>Ngayon Manliligtas papasukin.<br/>',NULL,40598,1);
INSERT INTO stanza VALUES('T354','2','O, anong gulo ng buong silid,<br/>Kagamitan kalat sa paligid;<br/>Mesa''t silya''y dapat pang ayusin,<br/>Anong pagtanggap sa Panauhin!<br/>',NULL,40599,2);
INSERT INTO stanza VALUES('T354','3','Nguni''t gayon nga ang kalagayan,<br/>Kaya Kita ay inanyayahan;<br/>Itong kaguluha''t kadiliman<br/>Liwanag Mo at kamay kailangan.<br/>',NULL,40600,3);
INSERT INTO stanza VALUES('T354','4','Sa harap ng mabuting Kaibigan,<br/>Di ko hangad ayusin anuman;<br/>Kahit pa ayusin di gaganda,<br/>Pagpasok Mo tuloy naantala.<br/>',NULL,40601,4);
INSERT INTO stanza VALUES('T354','5','Pasok, huwag nang maghanap, gawin lang,<br/>Ang puso ko angkop Mong tirahan;<br/>Paalisin dilim, takot, sala<br/>Pasok, Pangino''ng Hesus, ngayon na!<br/>',NULL,40602,5);
INSERT INTO stanza VALUES('T357','1','Apoy banal, Hesus akin,<br/>Puso ko''y Iyong paningasin;<br/>Budhi''y nilinisan.<br/>Ihayag Ka kalul''wa ko,<br/>Madama ang paggawa Mo,<br/>Sa ''kin Diyos nagsilang.<br/>',NULL,40603,1);
INSERT INTO stanza VALUES('T357','2','Ako''y nakatuon sa Iyo,<br/>Kasama sa Iyong pinako,<br/>Sa Iyo ibuhay Diyos.<br/>Patay sa mundo''t laruan,<br/>Maging mga karangyangan,<br/>Gloria Kitang lubos.<br/>',NULL,40604,2);
INSERT INTO stanza VALUES('T357','3','Pukawin pagkauhaw ko,<br/>Punuin sabik kong puso,<br/>Ang asam, nais ko,<br/>Ipagkaloob lahat Mo,<br/>Mabuhay Ka sa loob ko;<br/>Pumasok lahat Mo.<br/>',NULL,40605,3);
INSERT INTO stanza VALUES('T357','4','Hayaang mawala sa Iyo,<br/>Nang lahat ay Sarili Mo,<br/>Sa akin lahat Ka.<br/>Tinawag nang magtiwala,<br/>Liban sa Iyo walang Sinta;<br/>B''yaya sa biyaya!<br/>',NULL,40606,4);
INSERT INTO stanza VALUES('T358','1','Pag-ibig na humihigit,<br/>Sa lupa mula langit;<br/>Nananahan sa ''king dibdib,<br/>Putong ng pananalig.<br/>Hesus Ika''y kahabagan,<br/>Pagsintang walang hanggan,<br/>Dala Mo ang kaligtasan,<br/>Sa puso ko tumahan.<br/>',NULL,40607,1);
INSERT INTO stanza VALUES('T358','2','Ihinga Iyong Espiritu<br/>Sa bagabag na puso;<br/>Manahin lahat sa I-yo,<br/>Pahingang pinangako.<br/>Alisin nasa sa sala;<br/>Alpha at Omega Ka;<br/>Puso namin mapalaya,<br/>Pananalig itakda.<br/>',NULL,40608,2);
INSERT INTO stanza VALUES('T358','3','Makapangyarihang Isa,<br/>Bigyan kaming sagana<br/>Ng buhay Mo at presensya,<br/>Sa templo Mo tumira.<br/>Kami''y pinagpala sa Iyo,<br/>Paglingkod payagan Mo,<br/>Dalangin, puri kailanman<br/>Sa Iyo, kal''walhatian.<br/>',NULL,40609,3);
INSERT INTO stanza VALUES('T358','4','Bagong nilikha''y yariin,<br/>Puro''t walang dungis din;<br/>Kaligtasan Mong dakila,<br/>Mapanumbalik Mo na;<br/>Sa l''walhati''y binabago<br/>Hanggang kami''y suma-Iyo,<br/>Para sa Iyo lahat waksi,<br/>Sa Iyo pag-ibig, puri.<br/>',NULL,40610,4);
INSERT INTO stanza VALUES('T359','1','O Ilaw ng ilaw!<br/>Sa puso''y tumanglaw,<br/>Ang sala ng gabi<br/>Ikaw ang magpawi.<br/>',NULL,40611,1);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40612,2);
INSERT INTO stanza VALUES('T359','2','O Galak pasok Ka!<br/>Ang lungkot ng sala,<br/>Ay Iyong tapusin na,<br/>Maging mapayapa.<br/>',NULL,40613,3);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40614,4);
INSERT INTO stanza VALUES('T359','3','O Buhay, buhusan!<br/>Salang kamatayan;<br/>Ngayon ay alisin,<br/>O buhay punuin.<br/>',NULL,40615,5);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40616,6);
INSERT INTO stanza VALUES('T359','4','Pag-ibig, daluyan!<br/>Ugat kasalanan,<br/>Tuusin, baguhin:<br/>Daloy paagusin!<br/>',NULL,40617,7);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40618,8);
INSERT INTO stanza VALUES('T359','5','O Langit ng langit,<br/>Ulap ay pawiin,<br/>Gulo ay tapusin,<br/>Langit pababain!<br/>',NULL,40619,9);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40620,10);
INSERT INTO stanza VALUES('T359','6','Diyos at Panginoon,<br/>Dumating Ka nawa!<br/>Galak at lahat Ka,<br/>Sa puso''y tumira.<br/>',NULL,40621,11);
INSERT INTO stanza VALUES('T359','chorus','Ilaw higit sa tanan,<br/>Sa puso manahan;<br/>Galak, lungkot pinawi,<br/>Sa puso lumagi.<br/>',NULL,40622,12);
INSERT INTO stanza VALUES('T362','1','Para sa ''kin, Siya''y namatay,<br/>Nang Siya''y ipamuhay,<br/>Buhay, pag-ibig alay ko<br/>Kay Hesus, pinako.<br/>',NULL,40623,1);
INSERT INTO stanza VALUES('T362','chorus','Hesus Tagapagligtas ko!<br/>Tanging Ikaw susundin ko;<br/>Tulad Mong namatay, nabuhay,<br/>Buhay ko rin ibabatay.<br/>',NULL,40624,2);
INSERT INTO stanza VALUES('T362','2','Namatay Siya, at ako rin,<br/>Kay taas, kay lalim<br/>Ng kamatayan at buhay,<br/>Sarili''y mamatay.<br/>',NULL,40625,3);
INSERT INTO stanza VALUES('T362','chorus','Hesus Tagapagligtas ko!<br/>Tanging Ikaw susundin ko;<br/>Tulad Mong namatay, nabuhay,<br/>Buhay ko rin ibabatay.<br/>',NULL,40626,4);
INSERT INTO stanza VALUES('T362','3','Nabuhay Siya, at ako rin,<br/>Mabuhay dalisay;<br/>Likas Mo sa ''kin ibigay,<br/>Mabuhay sa akin.<br/>',NULL,40627,5);
INSERT INTO stanza VALUES('T362','chorus','Hesus Tagapagligtas ko!<br/>Tanging Ikaw susundin ko;<br/>Tulad Mong namatay, nabuhay,<br/>Buhay ko rin ibabatay.<br/>',NULL,40628,6);
INSERT INTO stanza VALUES('T362','4','Para sa ''kin, Siya''y nabuhay,<br/>Ipamahagi Siya;<br/>Makatao Kanyang buhay,<br/>Tutularan ko Siya.<br/>',NULL,40629,7);
INSERT INTO stanza VALUES('T362','chorus','Hesus Tagapagligtas ko!<br/>Tanging Ikaw susundin ko;<br/>Tulad Mong namatay, nabuhay,<br/>Buhay ko rin ibabatay.<br/>',NULL,40630,8);
INSERT INTO stanza VALUES('T364','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40631,1);
INSERT INTO stanza VALUES('T364','1','Panginoon, buhay Kita,<br/>Panustos pa Kita;<br/>Espiritung tagabantay,<br/>Yaman ng ''king buhay.<br/>',NULL,40632,2);
INSERT INTO stanza VALUES('T364','2','Iyong pinagamit ''Spiritu,<br/>Hiningahan ako;<br/>Wangis sa Iyong kamatayan,<br/>Krus ay maranasan.<br/>',NULL,40633,3);
INSERT INTO stanza VALUES('T364','3','Hades, Satanas daig Mo,<br/>Ako di pa talo<br/>Gumawa Ka sa loob ko,<br/>Kitlin, buhayin Mo.<br/>',NULL,40634,4);
INSERT INTO stanza VALUES('T364','4','Natural ko Iyong patayin,<br/>Ako''y Iyong gamitin;<br/>Nang mabuhay kalakip Mo,<br/>Ilibing muna ''ko.<br/>',NULL,40635,5);
INSERT INTO stanza VALUES('T364','5','Maghari Ka sa loob ko,<br/>Ako''y kaisa Mo;<br/>Sarili Mo''y ibuhay nga,<br/>Nang mahayag Kita.<br/>',NULL,40636,6);
INSERT INTO stanza VALUES('T364','6','Ang sala ko''y Iyong linisin<br/>Ako''y bahay Mo rin;<br/>Iyong l''walhati babaran ''ko,<br/>Mahayag Diyos Mismo.<br/>',NULL,40637,7);
INSERT INTO stanza VALUES('T367','1','Nakatataas Ka, Hesus!<br/>Wika, ritwal, kredo,<br/>Pulong, pag-ibig ng tao,<br/>Di mahambing sa Iyo.<br/>',NULL,40638,1);
INSERT INTO stanza VALUES('T367','2','Nakatataas Ka, Hesus!<br/>Ako''y binihag Mo;<br/>Dahil sa Krus, patay ako,<br/>Mamuhay lang sa Iyo.<br/>',NULL,40639,2);
INSERT INTO stanza VALUES('T367','3','Nakatataas Ka, Hesus!<br/>Ako''y punuin Mo;<br/>Ang isip Mo ay isip ko,<br/>Nais Mo''y nais ko.<br/>',NULL,40640,3);
INSERT INTO stanza VALUES('T367','4','Nakatataas Ka, Hesus!<br/>Ako''y itransporma;<br/>Mula sa tabing (ang laman),<br/>Ihayag Iyong ganda.<br/>',NULL,40641,4);
INSERT INTO stanza VALUES('T367','5','Nakatataas Ka, Hesus!<br/>Galak ng puso ko;<br/>Bilang alipin, tupdin ko,<br/>Ang kalooban Mo.<br/>',NULL,40642,5);
INSERT INTO stanza VALUES('T368','1','Pag-ibig ko, Hesus ay dagdagan,<br/>Ako''y nanikluhod, kaawaan;<br/>Samo ko''y pakinggan,<br/>Pag-ibig dagdagan;<br/>Pag-ibig ko ay dagdagan.<br/>',NULL,40643,1);
INSERT INTO stanza VALUES('T368','2','Ninasa''y pangmundong katuwaan,<br/>Ikaw ang hanap kong kasiyahan;<br/>Tanging kahilingan:<br/>Pag-ibig dagdagan;<br/>Pag-ibig ko ay dagdagan.<br/>',NULL,40644,2);
INSERT INTO stanza VALUES('T368','3','Bayaan ang lumbay ay dumaan,<br/>At ang taglay nito''y katamisan;<br/>Aking papurihan,<br/>Pag-ibig dagdagan;<br/>Pag-ibig ko ay dagdagan.<br/>',NULL,40645,3);
INSERT INTO stanza VALUES('T368','4','Huling awit Kita''y bubulungan,<br/>Sigaw ng puso ko''y walang hanggan<br/>Panalangin pa man:<br/>Pag-ibig dagdagan;<br/>Pag-ibig ko ay dagdagan.<br/>',NULL,40646,4);
INSERT INTO stanza VALUES('T370','1','Hesus, manatili Ka sa akin,<br/>Ang dilim at gabi''y dumarating,<br/>Kung aliw''t tulong ako''y lisanin,<br/>Manatili Ka sa aking piling.<br/>',NULL,40647,1);
INSERT INTO stanza VALUES('T370','2','Buhay ay wari nang nauubos;<br/>Kahit ligaya ay natatapos;<br/>At ang lahat nagbabagong lubos,<br/>Liban sa Iyo; manahan Ka, Hesus.<br/>',NULL,40648,2);
INSERT INTO stanza VALUES('T370','3','Dumating Ka di takot ang dala,<br/>Kundi lunas sa pusong may sala;<br/>Pusong may habag, kami''y aliwin,<br/>Halina, Kaibigan ng salarin.<br/>',NULL,40649,3);
INSERT INTO stanza VALUES('T370','4','Presensya Mo''y lagi kong kailangan,<br/>Upang tukso''y mapagtagumpayan;<br/>Sino tulad Mo maging sanggalang?<br/>Gabi''t araw, ako''y Iyong samahan.<br/>',NULL,40650,4);
INSERT INTO stanza VALUES('T370','5','Walang lakas ang aking kalaban,<br/>Sakit at luha ay nabawasan;<br/>Kapangyarihan ng kamatayan<br/>Aking daig kung Iyong sasamahan.<br/>',NULL,40651,5);
INSERT INTO stanza VALUES('T371','1','Hesus — kailangan ko<br/>Bawa''t saglit;<br/>Mayuming tinig Mo<br/>Mapang-akit.<br/>',NULL,40652,1);
INSERT INTO stanza VALUES('T371','chorus','Tunay Kitang kailangan,<br/>Sa lahat ng oras,<br/>Ako''y Iyong biyayaan,<br/>Bigyang lakas.<br/>',NULL,40653,2);
INSERT INTO stanza VALUES('T371','2','Kailangan nga Kita,<br/>Lumapit Ka;<br/>Tukso''y walang bisa,<br/>Narito Ka.<br/>',NULL,40654,3);
INSERT INTO stanza VALUES('T371','chorus','Tunay Kitang kailangan,<br/>Sa lahat ng oras,<br/>Ako''y Iyong biyayaan,<br/>Bigyang lakas.<br/>',NULL,40655,4);
INSERT INTO stanza VALUES('T371','3','Kahit anong datnan,<br/>Lungkot, sayá,<br/>Sa ''kin Ka manahan,<br/>Sasapat na.<br/>',NULL,40656,5);
INSERT INTO stanza VALUES('T371','chorus','Tunay Kitang kailangan,<br/>Sa lahat ng oras,<br/>Ako''y Iyong biyayaan,<br/>Bigyang lakas.<br/>',NULL,40657,6);
INSERT INTO stanza VALUES('T371','4','Sa akin ituro<br/>Kalooban Mo,<br/>Lahat Mong pangako,<br/>Tuparin Mo.<br/>',NULL,40658,7);
INSERT INTO stanza VALUES('T371','chorus','Tunay Kitang kailangan,<br/>Sa lahat ng oras,<br/>Ako''y Iyong biyayaan,<br/>Bigyang lakas.<br/>',NULL,40659,8);
INSERT INTO stanza VALUES('T371','5','Kabanal-banalan<br/>Anak ng Diyos,<br/>Ako''y Iyong tatangnan<br/>Angkining lubos.<br/>',NULL,40660,9);
INSERT INTO stanza VALUES('T371','chorus','Tunay Kitang kailangan,<br/>Sa lahat ng oras,<br/>Ako''y Iyong biyayaan,<br/>Bigyang lakas.<br/>',NULL,40661,10);
INSERT INTO stanza VALUES('T373','1','Walang hadlang, O Panginoon,<br/>Sa pagitan natin;<br/>Ilapit kalul''wa<br/>L''walhati''y makita.<br/>Walang hadlang, walang hadlang.<br/>',NULL,40662,1);
INSERT INTO stanza VALUES('T373','2','Walang hadlang, O Panginoon;<br/>Tinig Mo''y diringgin;<br/>Ingay ng daigdig,<br/>Huwag sanang marinig,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40663,2);
INSERT INTO stanza VALUES('T373','3','Walang hadlang, O Panginoon;<br/>Ni pagkabalisa,<br/>Ni luha ni dasal,<br/>Sariling sagabal,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40664,3);
INSERT INTO stanza VALUES('T373','4','Walang hadlang, O Panginoon;<br/>Alinlanga''t takot,<br/>Pawang maglalaho,<br/>Kung malapit sa Iyo,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40665,4);
INSERT INTO stanza VALUES('T373','5','Walang hadlang, O Panginoon;<br/>Sa ''kin ay sumilay;<br/>Ulap ay pawiin,<br/>Puso ko''y aliwin,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40666,5);
INSERT INTO stanza VALUES('T373','6','Walang hadlang, O Panginoon,<br/>Lakad ko''t paningin,<br/>Nawa ay Ikaw rin;<br/>Ako''y Iyong angkinin,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40667,6);
INSERT INTO stanza VALUES('T373','7','Walang hadlang, O Panginoon;<br/>Paningin ko''y buksan;<br/>Walang hanggang ilaw,<br/>Sa dilim tumanglaw,<br/>Walang hadlang, walang hadlang.<br/>',NULL,40668,7);
INSERT INTO stanza VALUES('T374','1','Manliligtas aking araw,<br/>Presensya Mo''y aking tanglaw;<br/>Huwag hayaang mata''y takpan,<br/>Hadlangang Kita''y pagmasdan.<br/>',NULL,40669,1);
INSERT INTO stanza VALUES('T374','2','Nang pipikit aking mata,<br/>Sa pagtulog, magpahinga;<br/>Nawa huling nasa diwa,<br/>Poon ko, kay tamis Mo nga.<br/>',NULL,40670,2);
INSERT INTO stanza VALUES('T374','3','Hindi ako mabubuhay,<br/>Kung di Kita kaagapay;<br/>Sa umaga manatili,<br/>Kasama ko hanggang gabi.<br/>',NULL,40671,3);
INSERT INTO stanza VALUES('T374','4','Biyayaan Mo paggising,<br/>Nang ang mundo''y di tahakin;<br/>Nang lalim ng Iyong pagsinta,<br/>Kami''y malagom Mo na nga!<br/>',NULL,40672,4);
INSERT INTO stanza VALUES('T377','1','Kung ang aking landas<br/>Sa krus ang punta;<br/>Kung daan Iyong pili<br/>Hatid ay dusa;<br/>Aking ninanais<br/>Nitong kapalit,<br/>Ang pagsalamuha<br/>Na mas matalik.<br/>',NULL,40673,1);
INSERT INTO stanza VALUES('T377','2','Lupang saya''y konti,<br/>Panlangit bigyan.<br/>''Spiritu''y pupuri,<br/>Puso ma''y saktan;<br/>Kung panlupang bigkis,<br/>Nais putulin,<br/>Hayaang tumamis,<br/>Ugnayan natin.<br/>',NULL,40674,2);
INSERT INTO stanza VALUES('T377','3','Daan man may lumbay<br/>Pasayahin Mo;<br/>Maging kasama ko,<br/>Sa lupang ito.<br/>Di makasarili,<br/>Mamuhay ako;<br/>Maging ang daluyan<br/>Ng biyaya Mo.<br/>',NULL,40675,3);
INSERT INTO stanza VALUES('T378','1','Sa bundok ako''y Iyong dalhin,<br/>Ikaw lamang malasin;<br/>Doo''y dalisay ang hangin,<br/>Tinig makalangit din.<br/>',NULL,40676,1);
INSERT INTO stanza VALUES('T378','chorus','Ako sa bundok dalhin Mo,<br/>Magsalamuha sa Iyo;<br/>Bukal tanaw sa ilaw Mo,<br/>Naglilinis Iyong dugo.<br/>',NULL,40677,2);
INSERT INTO stanza VALUES('T378','2','Kay liwanag sa itaas,<br/>Sa makamundo''y lampas;<br/>Pagpupumiglas napawi,<br/>Sa Buhay Niya''y maghari.<br/>',NULL,40678,3);
INSERT INTO stanza VALUES('T378','3','Sa bundok panatilihin,<br/>Hanggang layon marating;<br/>Hanggang mapawangis sa Iyo,<br/>Purihin biyaya Mo.<br/>',NULL,40679,5);
INSERT INTO stanza VALUES('T380','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40680,1);
INSERT INTO stanza VALUES('T380','1','O Tinapay sa banal,<br/>At sa manlalakbay,<br/>Mulang langit na Manna,<br/>Angkop sa kanila.<br/>Kainin Ka''y mithiin,<br/>Mayamang punuin;<br/>Mawala lupang saya,<br/>Hangad mapayapa.<br/>',NULL,40681,2);
INSERT INTO stanza VALUES('T380','2','O Tubig, bigay buhay<br/>Sa batong nabitak;<br/>Tubig na anong tamis,<br/>Bukal ng pag-ibig.<br/>Malaya Kang inumin,<br/>Pawi uhaw namin;<br/>Hanggang kawalang-hanggan<br/>Lagi katamisan.<br/>',NULL,40682,3);
INSERT INTO stanza VALUES('T380','3','Inumin Ka''t kainin,<br/>Salamat ihain;<br/>Iyong ''Spiritu''t Salita,<br/>Handog Mong tamasa.<br/>Sa Iyo kami''y lalago,<br/>Mamumuhay sa Iyo;<br/>Upang sa Iyo matulad,<br/>Lubos Kang ihayag.<br/>',NULL,40683,4);
INSERT INTO stanza VALUES('T382','1','Nais kong lalong matalos<br/>Ang pagpapala ni Hesus;<br/>Ang pagliligtas Niyang puspos<br/>At ang kamatayan sa krus.<br/>',NULL,40684,1);
INSERT INTO stanza VALUES('T382','chorus','Kristo''y aking nasa,<br/>Lalong makilala<br/>Pagtubos Niyang kay dakila,<br/>Yaman Niyang aking tamasa.<br/>',NULL,40685,2);
INSERT INTO stanza VALUES('T382','2','Nais ko ring matutunan<br/>Ang banal Niyang kalooban;<br/>Turuan ng Espiritu,<br/>Nang malaman ko si Kristo.<br/>',NULL,40686,3);
INSERT INTO stanza VALUES('T382','chorus','Kristo''y aking nasa,<br/>Lalong makilala<br/>Pagtubos Niyang kay dakila,<br/>Yaman Niyang aking tamasa.<br/>',NULL,40687,4);
INSERT INTO stanza VALUES('T382','3','Higit pang Kristo''y matamo<br/>Sa Salitang punung-puno;<br/>Ng pag-ibig, katapatan<br/>Ng buhay at kasiyahan.<br/>',NULL,40688,5);
INSERT INTO stanza VALUES('T382','chorus','Kristo''y aking nasa,<br/>Lalong makilala<br/>Pagtubos Niyang kay dakila,<br/>Yaman Niyang aking tamasa.<br/>',NULL,40689,6);
INSERT INTO stanza VALUES('T382','4','Si Hesus nasa luklukan,<br/>Taglay Niyang kal''walhatian,<br/>Makita ko''ng kaharian,<br/>Hari ng Kapayapaan.<br/>',NULL,40690,7);
INSERT INTO stanza VALUES('T382','chorus','Kristo''y aking nasa,<br/>Lalong makilala<br/>Pagtubos Niyang kay dakila,<br/>Yaman Niyang aking tamasa.<br/>',NULL,40691,8);
INSERT INTO stanza VALUES('T387','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40692,1);
INSERT INTO stanza VALUES('T387','1','Ako''y Iyo Hesus, ang sinabi Mo,<br/>Pag-ibig Mo''y dakila;<br/>Nguni''t laksan ang pananalig ko<br/>At mapalapit sa Iyo.<br/>',NULL,40693,2);
INSERT INTO stanza VALUES('T387','chorus','Ilapit Mo ''ko, Panginoon<br/>Sa kinamatayang krus;<br/>Ilapit ako sa Iyo, Panginoon<br/>Sa tag''lirang inulos.<br/>',NULL,40694,3);
INSERT INTO stanza VALUES('T387','2','Ako''y pabanalin ng biyaya,<br/>At maglilingkod sa Iyo;<br/>Espiritu ko''y sa Iyo umasa,<br/>Pasya ko ang pasya Mo.<br/>',NULL,40695,4);
INSERT INTO stanza VALUES('T387','3','Maikling panahon sa Iyong trono,<br/>Galak walang kaparis;<br/>Sa Iyong paanan at kaharap Mo,<br/>Pagniniig matamis.<br/>',NULL,40696,6);
INSERT INTO stanza VALUES('T387','4','Pag-ibig kay lalim di ko tanto,<br/>Liban kung magpangita;<br/>Galak kay taas, di ko matamo,<br/>Liban kung kapiling Ka.<br/>',NULL,40697,8);
INSERT INTO stanza VALUES('T389','1','O Hesus nais kong mamuhay sa Iyo,<br/>Ikaw ang daigdig sa araw''t gabi,<br/>Sana''y di-mapalagay ang puso ko<br/>Kung inaasam ang hindi Mo mithi.<br/>Anumang sandaling may pagdurusa<br/>At walang kasiyahang matagpuan,<br/>Nang ako''y dumaraing, lumuluha,<br/>Luha ko''y pahirin, dusa''y wakasan.<br/>',NULL,40698,1);
INSERT INTO stanza VALUES('T389','2','Kapag mangarap sa inam ng buhay,<br/>Hiling ko, Hesus, ang makasama Ka.<br/>Ikaw ang aking kasiyahang tunay,<br/>Huwag hayaang pumili pa ng iba.<br/>Tuwing gabi pag ako''y nakahimlay,<br/>Hiling ko''y mapalapit Ka sa akin,<br/>At sa pagsapit ng bukang-liwayway,<br/>Bulungan Mo ako, at Iyong tawagin.<br/>',NULL,40699,2);
INSERT INTO stanza VALUES('T389','3','Sa pagbasa ng banal Mong Salita,<br/>Mangyaring sumilay ang Iyong l''walhati,<br/>Nang Tagapagligtas ay makilala<br/>At ang kaligtasang aking bahagi.<br/>Kung dumulog ako sa Iyong luklukan,<br/>Ipagkaloob Mo ang Iyong biyaya.<br/>Kung dahil sa sala, ''di Mo pakinggan,<br/>Huwag Mong bawiin ang mahal Mong mukha.<br/>',NULL,40700,3);
INSERT INTO stanza VALUES('T389','4','Kung isipin ko ang mga biyaya,<br/>Makakapiling Ka — puso ko''y sabik.<br/>Tangi kong ligaya ang Iyong presensya,<br/>Tangi kong pag-asa ang Iyong pagbalik.<br/>Ako''y turuan Mong mamuhay sa Iyo,<br/>Ikaw ang daigdig sa araw''t gabi,<br/>Sana''y di-mapalagay ang puso ko<br/>Kung inaasam ang hindi Mo mithi.<br/>',NULL,40701,4);
INSERT INTO stanza VALUES('T390','1','Diyos ko, gabayan ako,<br/>Mamuhay sa ''Spiritu;<br/>Paglakad sa liwanag,<br/>Hinto na pagsikap ko.<br/>',NULL,40702,1);
INSERT INTO stanza VALUES('T390','chorus','Panginoon,<br/>Gabayan ako ngayon;<br/>Sa Iyong agos ng buhay,<br/>Sa Iyong daan igabay.<br/>',NULL,40703,2);
INSERT INTO stanza VALUES('T390','2','Patnubayan Mo ako,<br/>Sa batas ng buhay Mo;<br/>Akin Kang awtoridad,<br/>Dilim maging liwanag.<br/>',NULL,40704,3);
INSERT INTO stanza VALUES('T390','chorus','Panginoon,<br/>Gabayan ako ngayon;<br/>Sa Iyong agos ng buhay,<br/>Sa Iyong daan igabay.<br/>',NULL,40705,4);
INSERT INTO stanza VALUES('T390','3','Nagpalayang ''Spiritu,<br/>Isaayos Mo ako;<br/>Baguhin ang isip ko,<br/>Malaman ang gusto Mo.<br/>',NULL,40706,5);
INSERT INTO stanza VALUES('T390','chorus','Panginoon,<br/>Gabayan ako ngayon;<br/>Sa Iyong agos ng buhay,<br/>Sa Iyong daan igabay.<br/>',NULL,40707,6);
INSERT INTO stanza VALUES('T392','1','Hesus, ako''y ugitan<br/>Sa buhay kong mabagyo;<br/>Alon nasa harapan,<br/>Buhawi''t batong lilo;<br/>Mapa at direksyon ko—<br/>Hesus ako''y ugitan.<br/>',NULL,40708,1);
INSERT INTO stanza VALUES('T392','2','Tulad ng ina ng bata,<br/>Patahimikin Mo na—<br/>Dagat ay mamayapa<br/>Ayon sa Iyong salita;<br/>Hari ng karagatan—<br/>Hesus ako''y ugitan.<br/>',NULL,40709,2);
INSERT INTO stanza VALUES('T392','3','Sa lambak man dumaan,<br/>Biyaya''y lampas takot,<br/>Kapayapaan dulot,<br/>Paghilig sa dibdib Mo,<br/>Marinig Iyong salita:<br/>"Uugitan nga kita."<br/>',NULL,40710,3);
INSERT INTO stanza VALUES('T393','1','Iyong daan, di akin<br/>Ga''no mang kadilim;<br/>Patnubayan ako,<br/>Basta pinili Mo.<br/>',NULL,40711,1);
INSERT INTO stanza VALUES('T393','2','Patag o mabato,<br/>Mabuti rin ito;<br/>Tuwid, liku-liko,<br/>Pahinga ang tungo.<br/>',NULL,40712,2);
INSERT INTO stanza VALUES('T393','3','Ako sa sarili''y<br/>Nangambang pumili;<br/>Ikaw ang magpasya,<br/>Lumakad ng tama.<br/>',NULL,40713,3);
INSERT INTO stanza VALUES('T393','4','Sa dusa o saya,<br/>Saro ko''y pun''in na;<br/>Masunod Iyong pasya,<br/>Buti man o sama.<br/>',NULL,40714,4);
INSERT INTO stanza VALUES('T393','5','Piliin kaibigan,<br/>Sakit, kalusugan.<br/>Iyong alalahanin<br/>Hirap ko at yaman.<br/>',NULL,40715,5);
INSERT INTO stanza VALUES('T393','6','Pagpili''y di akin,<br/>Sa mga bagay rin;<br/>Gabay at lakas Ka,<br/>Dunong at lahat pa.<br/>',NULL,40716,6);
INSERT INTO stanza VALUES('T395','1','Hesus sa aki''y lumago<br/>Hiling walang iba;<br/>Ilapit sa Iyo puso ko,<br/>Iligtas sa sala.<br/>',NULL,40717,1);
INSERT INTO stanza VALUES('T395','chorus','Bawa''t araw sa Iyong lakas,<br/>Hina ko''y napawi;<br/>Dilim, kamataya''y wakas,<br/>Buhay Mo''y nagwagi.<br/>',NULL,40718,2);
INSERT INTO stanza VALUES('T395','2','Kasamaan ay naglaho<br/>Sa pagliwanag Mo;<br/>Ika''y lahat, hungkag ako,<br/>Sa ''kin ituro Mo.<br/>',NULL,40719,3);
INSERT INTO stanza VALUES('T395','chorus','Bawa''t araw sa Iyong lakas,<br/>Hina ko''y napawi;<br/>Dilim, kamataya''y wakas,<br/>Buhay Mo''y nagwagi.<br/>',NULL,40720,4);
INSERT INTO stanza VALUES('T395','3','Ikaw na Banal at Tunay,<br/>Gloria Mo''y pagmasdan;<br/>Maging Iyong larawang buháy,<br/>Sa tuwa''t dusa man.<br/>',NULL,40721,5);
INSERT INTO stanza VALUES('T395','chorus','Bawa''t araw sa Iyong lakas,<br/>Hina ko''y napawi;<br/>Dilim, kamataya''y wakas,<br/>Buhay Mo''y nagwagi.<br/>',NULL,40722,6);
INSERT INTO stanza VALUES('T395','4','Iyong galak ako''y puspusan,<br/>Hawakan ng lakas;<br/>Mula sa ''king katauhan:<br/>Pag-ibig ''pamalas.<br/>',NULL,40723,7);
INSERT INTO stanza VALUES('T395','chorus','Bawa''t araw sa Iyong lakas,<br/>Hina ko''y napawi;<br/>Dilim, kamataya''y wakas,<br/>Buhay Mo''y nagwagi.<br/>',NULL,40724,8);
INSERT INTO stanza VALUES('T395','5','Iyong pawiin sarili ko,<br/>Buhay Ka''t layunin;<br/>Papagindapatin ako,<br/>Iyong ngala''y taglayin.<br/>',NULL,40725,9);
INSERT INTO stanza VALUES('T395','chorus','Bawa''t araw sa Iyong lakas,<br/>Hina ko''y napawi;<br/>Dilim, kamataya''y wakas,<br/>Buhay Mo''y nagwagi.<br/>',NULL,40726,10);
INSERT INTO stanza VALUES('T396','1','Pataas na nagtumulin,<br/>Bagong rurok aking tam''hin;<br/>Patuloy na nanalangin,<br/>"Mas mataas ako''y dalhin."<br/>',NULL,40727,1);
INSERT INTO stanza VALUES('T396','chorus','Itaas ako''t itindig,<br/>Sa Canaan may panalig;<br/>Sa mas mataas na lupa,<br/>Poon, ilagak ''king paa.<br/>',NULL,40728,2);
INSERT INTO stanza VALUES('T396','2','Manatili di ko nasa,<br/>Saan man may takot, duda;<br/>Panalangin ko, Pangino''n<br/>Mas mataas, aking layon.<br/>',NULL,40729,3);
INSERT INTO stanza VALUES('T396','chorus','Itaas ako''t itindig,<br/>Sa Canaan may panalig;<br/>Sa mas mataas na lupa,<br/>Poon, ilagak ''king paa.<br/>',NULL,40730,4);
INSERT INTO stanza VALUES('T396','3','Mundo''y pangibabawan ko,<br/>Kahit pumana ang diyablo;<br/>Sa panalig may ligaya,<br/>Banal sa ''taas na lupa.<br/>',NULL,40731,5);
INSERT INTO stanza VALUES('T396','chorus','Itaas ako''t itindig,<br/>Sa Canaan may panalig;<br/>Sa mas mataas na lupa,<br/>Poon, ilagak ''king paa.<br/>',NULL,40732,6);
INSERT INTO stanza VALUES('T396','4','Pinakarurok abutin,<br/>Sa l''walhati makatingin;<br/>Tuloy pa ring nanalangin,<br/>"Mas mataas, ako''y dalhin."<br/>',NULL,40733,7);
INSERT INTO stanza VALUES('T396','chorus','Itaas ako''t itindig,<br/>Sa Canaan may panalig;<br/>Sa mas mataas na lupa,<br/>Poon, ilagak ''king paa.<br/>',NULL,40734,8);
INSERT INTO stanza VALUES('T397','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40735,1);
INSERT INTO stanza VALUES('T397','1','Mahalin Kang lalo,<br/>Malapit sa Iyo,<br/>Salita Mo''y sundin,<br/>Ngala''y dangalin,<br/>Lungkot Mo''y damayan,<br/>Hirap Mo''y tikman,<br/>Higit Iyong taguyod,<br/>Lalo''ng pagsunod.<br/>',NULL,40736,2);
INSERT INTO stanza VALUES('T397','chorus','Hesus, ako''y ingatan,<br/>Palakasi''t tulungan;<br/>Sa makitid na daan,<br/>Lugod Kita''y bigyan.<br/>',NULL,40737,3);
INSERT INTO stanza VALUES('T397','2','Lalong matagumpay,<br/>Sa Iyo''y mas tunay,<br/>Lalo pang may silbi,<br/>Magiting lagi,<br/>Dusa''y pagtiisan,<br/>Sala''y tangisan,<br/>Batahin pagdusta,<br/>Mas magtiwala.<br/>',NULL,40738,4);
INSERT INTO stanza VALUES('T397','chorus','Hesus, ako''y ingatan,<br/>Palakasi''t tulungan;<br/>Sa makitid na daan,<br/>Lugod Kita''y bigyan.<br/>',NULL,40739,5);
INSERT INTO stanza VALUES('T397','3','Lalong makalangit,<br/>Ika''y makamit,<br/>Pagbalik Mo''y asa,<br/>At Iyong "parousia,"<br/>Mas magpakababa,<br/>Taas itatwa,<br/>Sarili''y maglaho,<br/>Mas kawangis Mo.<br/>',NULL,40740,6);
INSERT INTO stanza VALUES('T397','chorus','Hesus, ako''y ingatan,<br/>Palakasi''t tulungan;<br/>Sa makitid na daan,<br/>Lugod Kita''y bigyan.<br/>',NULL,40741,7);
INSERT INTO stanza VALUES('T398','1','Maging tulad Mo, O Manunubos;<br/>Ito''y aking asam, dalangin;<br/>May galak iwan panlupang yaman,<br/>Sakdal Mong wangis bihis lubos.<br/>',NULL,40742,1);
INSERT INTO stanza VALUES('T398','chorus','O Panginoon, makatulad Mo!<br/>''Sing dalisay Mo, Manunubos;<br/>Ang katamisan, kapuspusan Mo,<br/>Sa ''king puso''y iukit lubos!<br/>',NULL,40743,2);
INSERT INTO stanza VALUES('T398','2','Maging katulad Mong mahabagin,<br/>Mapagpatawad, maibigin,<br/>Iba''y tulungan, sila''y aliwin,<br/>Makasalanan ay hanapin.<br/>',NULL,40744,3);
INSERT INTO stanza VALUES('T398','chorus','O Panginoon, makatulad Mo!<br/>''Sing dalisay Mo, Manunubos;<br/>Ang katamisan, kapuspusan Mo,<br/>Sa ''king puso''y iukit lubos!<br/>',NULL,40745,4);
INSERT INTO stanza VALUES('T398','3','Maging tulad Mong mapagkumbaba,<br/>Banal, matapang, walang dahas;<br/>Dusa ay maamong binabatá,<br/>Maghirap nang iba''y maligtas.<br/>',NULL,40746,5);
INSERT INTO stanza VALUES('T398','chorus','O Panginoon, makatulad Mo!<br/>''Sing dalisay Mo, Manunubos;<br/>Ang katamisan, kapuspusan Mo,<br/>Sa ''king puso''y iukit lubos!<br/>',NULL,40747,6);
INSERT INTO stanza VALUES('T398','4','Maging tulad Mo palapit ako,<br/>Nang matanggap pahid dibino;<br/>Lahat nga ng sa akin at ako,<br/>Mula ngayon ay pawang sa Iyo.<br/>',NULL,40748,7);
INSERT INTO stanza VALUES('T398','chorus','O Panginoon, makatulad Mo!<br/>''Sing dalisay Mo, Manunubos;<br/>Ang katamisan, kapuspusan Mo,<br/>Sa ''king puso''y iukit lubos!<br/>',NULL,40749,8);
INSERT INTO stanza VALUES('T398','5','Maging tulad Mo ang aking samo,<br/>Pag-ibig Mo''y puspusin ako;<br/>Gawin akong templong tahanan Mo,<br/>Angkop sa ''sang buhay Iyong gusto.<br/>',NULL,40750,9);
INSERT INTO stanza VALUES('T398','chorus','O Panginoon, makatulad Mo!<br/>''Sing dalisay Mo, Manunubos;<br/>Ang katamisan, kapuspusan Mo,<br/>Sa ''king puso''y iukit lubos!<br/>',NULL,40751,10);
INSERT INTO stanza VALUES('T399','1','Sa Iyo''y mapawangis,<br/>Ang aking nais;<br/>Nawa''y tuparin Mo,<br/>Itong mithi ko.<br/>',NULL,40752,1);
INSERT INTO stanza VALUES('T399','2','Matulad kay Kristo,<br/>Siya''y Espiritu;<br/>Kung Siyang mamahala,<br/>Nasa''y magawa.<br/>',NULL,40753,2);
INSERT INTO stanza VALUES('T399','3','Mukhang walang tabing,<br/>Gaya''y salamin;<br/>Kita''y aninagin,<br/>At l''walhatiin.<br/>',NULL,40754,3);
INSERT INTO stanza VALUES('T399','4','Sana''y aninagin,<br/>Di na ikubli;<br/>Panginoon Mismo,<br/>Ng pusong puro.<br/>',NULL,40755,4);
INSERT INTO stanza VALUES('T399','5','Iyong l''walhati''y masdan,<br/>Kata''y kaharap;<br/>Laging tinitingnan,<br/>O Ikaw lamang.<br/>',NULL,40756,5);
INSERT INTO stanza VALUES('T399','6','Ang makatulad Mo,<br/>Ay hangarin ko;<br/>Sa puso''y itatak,<br/>Kita''y mahayag.<br/>',NULL,40757,6);
INSERT INTO stanza VALUES('T399','7','Sa Iyo''y mapagaya,<br/>Gloria sa gloria;<br/>Ihayag si Kristo,<br/>Nang walang hinto.<br/>',NULL,40758,7);
INSERT INTO stanza VALUES('T403','1','Hesus, mabuhay sa akin,<br/>Ikaw ang aking buhay,<br/>Sa lahat kong suliranin<br/>Kasagutan Kang tunay.<br/>Hesus, mabuhay sa akin,<br/>Ikaw laging masunod,<br/>Sisidlan nag-aaninag,<br/>Ang Anak ay mahayag.<br/>',NULL,40759,1);
INSERT INTO stanza VALUES('T403','2','Inialay ang Iyong templo,<br/>Nalinis karumihan,<br/>Nawa ay pagliyabin Mo<br/>Apoy ng kalangitan.<br/>Magpitagan buong mundo,<br/>Sa aking paghahain<br/>Bilang aliping maamo<br/>Pinalakas Mo ako.<br/>',NULL,40760,2);
INSERT INTO stanza VALUES('T403','3','Supilin Mo''ng katawan ko,<br/>Sa Iyong utos maghintay,<br/>Handang dalhin pamatok Mo<br/>O mapawalang-saysay.<br/>Walang kaba sa paghabol,<br/>Walang pigapit, takot<br/>Kung magdusa, walang tutol,<br/>Nais Kang bigyang-lugod.<br/>',NULL,40761,3);
INSERT INTO stanza VALUES('T403','4','Mahinahon at maamo,<br/>Walang pagkiling, hilig,<br/>Ako ay tagasunod Mo,<br/>Gawin Mo ang Iyong ibig.<br/>Hesus, mabuhay sa akin,<br/>Ikaw ang aking buhay,<br/>Sa lahat kong suliranin<br/>Kasagutan Kang tunay.<br/>',NULL,40762,4);
INSERT INTO stanza VALUES('T405','beginning-note','Ang himnong ito ay isinulat ng may-akda nang bagung-bago pa lamang siyang nakakita. Siya ay isinilang na bulag.<br/>',NULL,40763,1);
INSERT INTO stanza VALUES('T405','1','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40764,2);
INSERT INTO stanza VALUES('T405','chorus','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40765,3);
INSERT INTO stanza VALUES('T405','2','Bukang-liwayway at buwan,<br/>Sa paraiso tingnan;<br/>Sa lupa may Kanyang habag,<br/>Sapat sa pagkabulag.<br/>',NULL,40766,4);
INSERT INTO stanza VALUES('T405','chorus','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40767,5);
INSERT INTO stanza VALUES('T405','3','Sa tinik ayaw lumaya,<br/>Dagdagan lang biyaya,<br/>Sa loob ng tabing ako,<br/>Silayan ng gloria Mo.<br/>',NULL,40768,6);
INSERT INTO stanza VALUES('T405','chorus','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40769,7);
INSERT INTO stanza VALUES('T405','4','Ganda Niya''y aking nakita,<br/>Sa pagsampalataya;<br/>Mal''walhati Kanyang mukha,<br/>Bagama''t Siya''y minata.<br/>',NULL,40770,8);
INSERT INTO stanza VALUES('T405','chorus','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40771,9);
INSERT INTO stanza VALUES('T405','5','Araw, buwan di mahambing,<br/>Maging sansinukob din;<br/>Sa l''walhating sumisilay<br/>Sa ulong nabayubay.<br/>',NULL,40772,10);
INSERT INTO stanza VALUES('T405','chorus','Nang makita mundong dilag,<br/>Nais muling mabulag;<br/>Baka mahal Niyang Presensya,<br/>Sa akin mawala pa.<br/>',NULL,40773,11);
INSERT INTO stanza VALUES('T406','1','Turuan Mo ako<br/>Ng Iyong daan;<br/>Biyayang tulong Mo,<br/>Ako''y bigyan.<br/>Ituwid lakad ko,<br/>''Ko''y manalig sa Iyo,<br/>Liwanagan ako,<br/>''Ko''y turuan.<br/>',NULL,40774,1);
INSERT INTO stanza VALUES('T406','2','Kung may takot, duda,<br/>''Ko''y turuan;<br/>Kahit bumagyo pa,<br/>''Ko''y turuan.<br/>May ulan ma''t ulap,<br/>Pighati at hirap,<br/>Daan Mo''y mahanap,<br/>''Ko''y turuan.<br/>',NULL,40775,2);
INSERT INTO stanza VALUES('T406','3','Habang buhay kami''y<br/>Iyong turuan,<br/>Anumang mangyari,<br/>Iyong turuan.<br/>Hanggang matapos na,<br/>Takbo''t pagbabaka,<br/>Kamtan gantimpala,<br/>Iyong turuan.<br/>',NULL,40776,3);
INSERT INTO stanza VALUES('T408','1','Poong Hesus nais kong maging sakdal,<br/>Sa aking kalul''wa Ika''y mamuhay;<br/>Basagin Mo ang lahat kong diyus-diyosan,<br/>Puputi kaysa niebe ''pag hugasan.<br/>',NULL,40777,1);
INSERT INTO stanza VALUES('T408','chorus','O mas busilak kaysa niebe;<br/>''Pag hugasan mas puti kaysa niebe.<br/>',NULL,40778,2);
INSERT INTO stanza VALUES('T408','2','Poong Hesus alisin ang di-banal,<br/>Ang dungis hugasan ng dugong mahal;<br/>Nang malinisan, lahat bibitiwan,<br/>Puputi kaysa niebe ''pag hugasan.<br/>',NULL,40779,3);
INSERT INTO stanza VALUES('T408','3','Poong Hesus, habag Mong galing trono,<br/>Ako''y tulungan Mong maghain sa Iyo;<br/>Bitiwan ko sarili''t kaalaman,<br/>Puputi kaysa niebe ''pag hugasan.<br/>',NULL,40780,5);
INSERT INTO stanza VALUES('T408','4','Poong Hesus, pakumbabang sumamo,<br/>Sa paanan ng krus hihintay ako,<br/>May panalig sa Iyong dugo''y daluyan,<br/>Puputi kaysa niebe ''pag hugasan.<br/>',NULL,40781,7);
INSERT INTO stanza VALUES('T408','5','Pangino''ng Hesus, naghihintay ako,<br/>Sa loob ko likhain pusong bago;<br/>Sa humiling di Mo tinatanggihan<br/>Puputi kaysa niebe ''pag hugasan.<br/>',NULL,40782,9);
INSERT INTO stanza VALUES('T412','1','Sa akin pakita Ka,<br/>Nang laman makilala.<br/>Biyaya Mo''y gumawa,<br/>Nang yumuko sa lupa.<br/>Magtagumpay ang nasa,<br/>Nguni''t buhay mahina!<br/>Nais ma''y kabutihan,<br/>Sama''y di malayuan.<br/>',NULL,40783,1);
INSERT INTO stanza VALUES('T412','2','Sa loob nais ko''ng Diyos,<br/>Nguni''t ''sama ang kilos;<br/>Pagbabago ma''y gusto,<br/>Bihag ng lumang tao.<br/>Sa kautusan ng Diyos,<br/>Sala''y nahantad lubos;<br/>Nais ko''y gawang buti,<br/>Sama ang nangyayari.<br/>',NULL,40784,2);
INSERT INTO stanza VALUES('T412','3','Natisod at tumayo,<br/>Nagpasya nguni''t bigo;<br/>Gusto kong magtagumpay,<br/>Sa lusak nalupaypay.<br/>Ako''y bihag ng sala,<br/>Walang labang magawa;<br/>Walang buti sa laman<br/>Pawang dilim, sala lang.<br/>',NULL,40785,3);
INSERT INTO stanza VALUES('T412','4','Ngayon talos ko ako,<br/>Sa lakas dahop ako;<br/>Sarili ko''y kakatwa,<br/>Ang buhay ko''y masama.<br/>Sarili''y di asahan,<br/>Ni ang lakas ng laman;<br/>Pag-asang saligan ko,<br/>Sa Haring Hesu-Kristo.<br/>',NULL,40786,4);
INSERT INTO stanza VALUES('T412','5','Sa krus kitlin Mo ako,<br/>Aasa ko kay Kristo;<br/>''Spiritu Niya''y magpuno<br/>Magamit ko Siya Mismo.<br/>Kamatayan Niya''y akin<br/>Gumawang mas malalim,<br/>Nang sarili''y maglaho<br/>Isabuhay si Kristo.<br/>',NULL,40787,5);
INSERT INTO stanza VALUES('T412','6','Kalagayan ko''y aba,<br/>Sino ang magpalaya?<br/>Sa patay na katawan,<br/>Nang aking panaigan.<br/>Dugo''y Kanyang binubo,<br/>Kristo''y kabanalan ko;<br/>Bilang buhay tinanggap<br/>Bahaging di-masukat.<br/>',NULL,40788,6);
INSERT INTO stanza VALUES('T412','7','Pagkabanal ay lubos,<br/>Pagtalima ay taos;<br/>Di na muling mahiya,<br/>Sa pagdulog sa Ama;<br/>Buhay may katayugan<br/>Biyaya''y panaligan<br/>Salamat, purihin Ka<br/>Ako''y lubos lumaya.<br/>',NULL,40789,7);
INSERT INTO stanza VALUES('T413','1','Hesus ako''y sulyapan;<br/>Kasimplihan ay bigyan;<br/>Dukhain, pababain,<br/>Nais Kang kilalanin.<br/>',NULL,40790,1);
INSERT INTO stanza VALUES('T413','2','Sa sariling palalo,<br/>Hidhid sa yaman ako,<br/>Pag-uyam at papuri<br/>Iwalay ang sarili.<br/>',NULL,40791,2);
INSERT INTO stanza VALUES('T413','3','Mayabang na sarili,<br/>Lalo pang isantabi;<br/>Sumuko sa Iyong gusto,<br/>Sa paa Mo''y yumuko.<br/>',NULL,40792,3);
INSERT INTO stanza VALUES('T413','4','Matulad sa ''sang bata,<br/>Lakas, dunong masira;<br/>Ang Iyong ilaw at lakas<br/>Masdan, lumakad wagas.<br/>',NULL,40793,4);
INSERT INTO stanza VALUES('T413','5','Pagod na kaluluwa<br/>Sa Iyo''y nagpapahinga;<br/>Kapayapaan ng Diyos<br/>''Ramdam dugong umagos.<br/>',NULL,40794,5);
INSERT INTO stanza VALUES('T413','6','Mamuhay na ganito<br/>Nagpupuri sa I-yo;<br/>Mamatay mang ganito<br/>Hosanna pa rin sa Iyo.<br/>',NULL,40795,6);
INSERT INTO stanza VALUES('T422','1','Iyo akong bihagin,<br/>Ako''y palayain;<br/>Ang tabak sa Iyo isuko,<br/>Mandaraig ako.<br/>Kung sa ''kin aasa,<br/>Mababalisa nga;<br/>Sa Iyong bisig ''ko''y bihagin,<br/>Kamay palakasin.<br/>',NULL,40796,1);
INSERT INTO stanza VALUES('T422','2','Mahina at dukha<br/>Puso ko''y daigin:<br/>Di ko magawa naisin,<br/>Natangay ng hangin;<br/>Hindi makakilos<br/>Kung di kalag gapos;<br/>Pag-ibig Mo ''ko''y bihagin<br/>Upang paghariin.<br/>',NULL,40797,2);
INSERT INTO stanza VALUES('T422','3','Mahina, hamak man<br/>Ibig paglingkuran;<br/>Apoy kailangang magningas,<br/>At hanging pang-lakas;<br/>Sarili at mundo<br/>Maitaboy ito;<br/>Kahinaan mawawala<br/>Sa I-yong paghinga.<br/>',NULL,40798,3);
INSERT INTO stanza VALUES('T422','4','Di ko kagustuhan,<br/>Aking kalooban;<br/>Kung abutin kong luklukan<br/>Putong bibitiwan;<br/>Di ito yuyuko,<br/>Sa gitna ng gulo,<br/>Nang sa dibdib Mo sumandal<br/>Buhay napasakdal.<br/>',NULL,40799,4);
INSERT INTO stanza VALUES('T423','1','Nakubling pag-ibig ng Diyos,<br/>Walang makabatid lubos;<br/>Iyong ganda''y aking nakita,<br/>Aking asam Iyong pahinga.<br/>Walang pahinga puso ko,<br/>Liban mamahinga sa Iyo.<br/>',NULL,40800,1);
INSERT INTO stanza VALUES('T423','2','Nagyaya lihim Mong tinig,<br/>Tunay pamatok kay tamis;<br/>Halos aking tugunan na,<br/>Nguni''t baka may hadlang pa.<br/>Nagpasya na, lumayo pa,<br/>Tuon sa Iyo, lumihis pa.<br/>',NULL,40801,2);
INSERT INTO stanza VALUES('T423','3','Awa sa akin dinala,<br/>Hangad ng isip payapa;<br/>Sa paghanap di makita<br/>Sa puso di mapayapa.<br/>Paglagalag hanggang kailan,<br/>Yapak ko tungo sa Iyo lang.<br/>',NULL,40802,3);
INSERT INTO stanza VALUES('T423','4','Sa lupa, sa aking puso,<br/>Walang bagay kahati Mo;<br/>Manatili Kang mamuno,<br/>Maging Panginoon nito.<br/>Puso sa lupa''y lumaya,<br/>''Pagkat sa Iyo ang pahinga.<br/>',NULL,40803,4);
INSERT INTO stanza VALUES('T423','5','O, ikubli sarili ko,<br/>Mabuhay lamang si Kristo,<br/>Masamang nasà kitilin,<br/>Kasalanan ay tapusin.<br/>Sa lahat walang matanaw<br/>Walang hangad kundi Ikaw.<br/>',NULL,40804,5);
INSERT INTO stanza VALUES('T423','6','Poon, tulong Mo''y ibigay<br/>Maligtas sa mga bagay;<br/>Maraming pag-aalala,<br/>Matigas na pagpapasya.<br/>Gawing masunurin ako,<br/>Mapagpasalamat sa Iyo.<br/>',NULL,40805,6);
INSERT INTO stanza VALUES('T423','7','Mula sa lupa ilayo<br/>Tawag Mo''y hinihintay ko;<br/>Kaibuturan sabihan,<br/>"Ako''y Iyong Sinta, Diyos, Tanan."<br/>Damahin, tinig pakinggan,<br/>Pag-ibig Mo ang hinirang.<br/>',NULL,40806,7);
INSERT INTO stanza VALUES('T426','1','Alisin tabing ko,<br/>Liwanag matamo;<br/>Di na malinlang pa<br/>Lahat mapatama.<br/>',NULL,40807,1);
INSERT INTO stanza VALUES('T426','chorus','Nawa buháy Mong ilaw,<br/>Maging aking tanglaw;<br/>Lahat paliwanagin.<br/>Aking panalangin.<br/>',NULL,40808,2);
INSERT INTO stanza VALUES('T426','2','Palalong sarili<br/>Kung kilala''y hindi,<br/>Madalas akala,<br/>Sarili ay tama.<br/>',NULL,40809,3);
INSERT INTO stanza VALUES('T426','3','Tungkol sa Iyo Mismo,<br/>Lalong bulag ako;<br/>Kulang sa pahayag<br/>Sa Iyong realidad.<br/>',NULL,40810,5);
INSERT INTO stanza VALUES('T426','4','Sa buhay panloob,<br/>Wala akong talos;<br/>''Spiritu o laman,<br/>Di alam kaib''han.<br/>',NULL,40811,7);
INSERT INTO stanza VALUES('T426','5','Tungkol sa daan Mo,<br/>Linaw wala ako;<br/>Dahil mapag-isa,<br/>Di batid ang tama.<br/>',NULL,40812,9);
INSERT INTO stanza VALUES('T426','6','Tungkol sa layon Mo,<br/>Kulang pagbatid ko;<br/>Sarili''y kapalit,<br/>At naghihimagsik.<br/>',NULL,40813,11);
INSERT INTO stanza VALUES('T426','7','Tungkol sa ekklesia,<br/>Buksan Mo ''king mata,<br/>At buhay-Katawan,<br/>Lubos na malaman.<br/>',NULL,40814,13);
INSERT INTO stanza VALUES('T426','8','Alisan ng tabing<br/>Lahat ay linawin;<br/>Di na magpalinlang,<br/>Walang kayabangan.<br/>',NULL,40815,15);
INSERT INTO stanza VALUES('T429','1','Nananalig ako<br/>Sa Iyo, O Kordero,<br/>Manliligtas;<br/>Dinggin Mo ang samo,<br/>Patawarin ako,<br/>Ako''y angkinin Mo<br/>Buhat ngayon.<br/>',NULL,40816,1);
INSERT INTO stanza VALUES('T429','2','Bigyan ng biyaya,<br/>Galak, lakas, sigla<br/>Ang puso ko.<br/>Iyong dugo''y ''binuhos,<br/>Mahal Kitang lubos,<br/>Tunay, wagas, taos,<br/>Lumalalo.<br/>',NULL,40817,2);
INSERT INTO stanza VALUES('T429','3','Sa panlupang daan<br/>May kapighatian,<br/>Umakay Ka.<br/>Pahirin luha ko,<br/>Nang hindi sumuko,<br/>Ilayo sa tukso,<br/>At sundin Ka.<br/>',NULL,40818,3);
INSERT INTO stanza VALUES('T429','4','Buhay — pangarap lang,<br/>Halos lunurin ng<br/>Kamatayan.<br/>Nawa''y Iyong pag-ibig<br/>Takot, duda''y pawi;<br/>Kalul''wa''y transporma<br/>Ng biyaya.<br/>',NULL,40819,4);
INSERT INTO stanza VALUES('T430','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40820,1);
INSERT INTO stanza VALUES('T430','1','Nang nasa likas na tao,<br/>Dama ko''y malakas ako;<br/>Sarili di nakilala<br/>Na mahina!<br/>',NULL,40821,2);
INSERT INTO stanza VALUES('T430','2','Sa sanlibutan namuhay,<br/>Akala''y lahat nataglay;<br/>Nagmalaki sa sarili,<br/>Nagpursigi.<br/>',NULL,40822,3);
INSERT INTO stanza VALUES('T430','3','Nang sa dilim nananahan,<br/>Hindi batid kababawan,<br/>Abala''y walang hangganan,<br/>Kayabangan.<br/>',NULL,40823,4);
INSERT INTO stanza VALUES('T430','4','Nang dumulog sa Iyong harap,<br/>Liwanag sa ''kin suminag;<br/>Di nakita noon, sadya<br/>Nahantad na.<br/>',NULL,40824,5);
INSERT INTO stanza VALUES('T430','5','Nanliliit sa Iyong harap,<br/>Sariling lakas lumipas,<br/>Kapalaluan humina,<br/>Naging aba!<br/>',NULL,40825,6);
INSERT INTO stanza VALUES('T430','6','Kabulaga''t kamangmangan<br/>Ang aking kapalaluan;<br/>Pinatigas kalul''wa ko,<br/>Mula puso!<br/>',NULL,40826,7);
INSERT INTO stanza VALUES('T430','7','Maipagmalaki''y wala,<br/>Pag-asa''t sandigan wala;<br/>Magsisi, nakakahiya,<br/>Magdasal pa?<br/>',NULL,40827,8);
INSERT INTO stanza VALUES('T430','8','Sa hatol nagligtas dugo,<br/>Poot, nag-adya buhay Mo.<br/>Marungis at maralita,<br/>Talaga nga!<br/>',NULL,40828,9);
INSERT INTO stanza VALUES('T430','9','Lahat ng palalo''y mangmang,<br/>Di batid katotohanan;<br/>Pusong nas''yahan, sarili.<br/>Nasa dilim!<br/>',NULL,40829,10);
INSERT INTO stanza VALUES('T430','10','Tumahimik ako''y mali,<br/>Kumilos man, ako''y mali;<br/>Mahina na''t pawang bigo,<br/>Ganyan ako!<br/>',NULL,40830,11);
INSERT INTO stanza VALUES('T430','11','Manalangin, mananalig,<br/>Sa Iyo lang ako''y sasandig;<br/>Puso mapabago nawa,<br/>Mahabag Ka!<br/>',NULL,40831,12);
INSERT INTO stanza VALUES('T432','1','O Pag-ibig, ''ko''y inangkin,<br/>Ako''y namahinga sa Iyo;<br/>Buhay ko sa Iyo''y ihain,<br/>Nang sa lalim ng dagat Mo<br/>Ito''y payamanin.<br/>',NULL,40832,1);
INSERT INTO stanza VALUES('T432','2','O Ilaw, gabay ko sa daan,<br/>Suko ko aking ilawan;<br/>Puso ko nang Iyong sikatan,<br/>Higit na naliwanagan;<br/>Mas ang kagandahan.<br/>',NULL,40833,2);
INSERT INTO stanza VALUES('T432','3','O Galak, nag-alis lumbay,<br/>Di ko sasarhan puso ko;<br/>Bahaghari ang patunay<br/>Sa Iyong tiyak na pangako,<br/>Umagang makulay.<br/>',NULL,40834,3);
INSERT INTO stanza VALUES('T432','4','O Krus, sa ''kin nagtingala,<br/>Hindi Kita maiiwan;<br/>Pangmundo''y nailibing na<br/>Ang buhay na walang hanggan<br/>Ay namulaklak na.<br/>',NULL,40835,4);
INSERT INTO stanza VALUES('T433','1','Ako''y Kanya! Anong kagalakan nga!<br/>Matamis na tugon sa tinig Niya;<br/>"Oo" tugon sa Iyong mga pangako,<br/>"Huwag mangamba, tinubos na kita."<br/>',NULL,40836,1);
INSERT INTO stanza VALUES('T433','2','Ako''y Kanya! Deklarasyong masaya!<br/>Masayang araw ay nagunita,<br/>Nobya sa Kanya''y magsabi ng "Oo."<br/>Panginoo''y pararangalan ko.<br/>',NULL,40837,2);
INSERT INTO stanza VALUES('T433','3','Ako''y Kanya! Nawa ako''y turuan.<br/>Tungkol sa pagsinta''t katapatan;<br/>Banal paglingkod, lubos na pagsuko,<br/>Walang hanggang pagsunod sa I-yo.<br/>',NULL,40838,3);
INSERT INTO stanza VALUES('T433','4','Ako''y Kanya! Buo kong katauhan,<br/>Espiritu, kalul''wa''t katawan;<br/>Ang Sinta ko, sa ganap Niyang biyaya,<br/>Magpaka-i-lanman ay akin nga.<br/>',NULL,40839,4);
INSERT INTO stanza VALUES('T436','1','Buhay Mo''y sa akin,<br/>Dugo Mo''y binuhos;<br/>Nang ako''y tubusin,<br/>Buhayin nang lubos.<br/>Buhay Mo''y ibinigay sa ''kin;<br/>Anong Iyong tatanggapin?<br/>',NULL,40840,1);
INSERT INTO stanza VALUES('T436','2','Mahahabang taon,<br/>Ang Iyong ginugol din;<br/>Upang magkalaon<br/>L''walhati''y sa akin.<br/>Taon ginugol Mo sa akin,<br/>Ako ba''y gumugol din?<br/>',NULL,40841,2);
INSERT INTO stanza VALUES('T436','3','Luklukan, tahanan<br/>Ng Ama''y iniwan;<br/>Madilim na lunan<br/>Sa lupa''y tirahan.<br/>Lahat nilisan para sa ''kin;<br/>Ako ba''y naglisan din?<br/>',NULL,40842,3);
INSERT INTO stanza VALUES('T436','4','Lahat pinasan Mo—<br/>Hirap ko''t lunggati,<br/>Nang ako''y matamo,<br/>Ligtas sa pighati.<br/>Nagdusa Ka para sa akin;<br/>Ako ba''y nagdusa rin?<br/>',NULL,40843,4);
INSERT INTO stanza VALUES('T436','5','At ako''y dinalhan,<br/>Mula sa itaas,<br/>Aking kaligtasan,<br/>Malaya at wagas.<br/>Lahat inihandog Mo sa ''kin;<br/>Ako ba''y naghandog din?<br/>',NULL,40844,5);
INSERT INTO stanza VALUES('T436','6','Buhay ko ay sa Iyo,<br/>Taon ko''y ialay;<br/>Sa mundo''y lalayo,<br/>Tuwa''t hirap buhay.<br/>Lahat Mo''y ibinigay sa ''kin,<br/>Lahat ko''y sa Iyo na rin.<br/>',NULL,40845,6);
INSERT INTO stanza VALUES('T437','1','Narinig, nakita mo Siya?<br/>Puso mo''y nabihag Niya?<br/>Pinuno ng laksa-laksa,<br/>Galak na mapili Siya.<br/>',NULL,40846,1);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40847,2);
INSERT INTO stanza VALUES('T437','2','Diyus-diyosan inakit noon,<br/>Tila may ganda roon;<br/>Kaya sa sala''y natangay<br/>Wari''y tamis ang bigay.<br/>',NULL,40848,3);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40849,4);
INSERT INTO stanza VALUES('T437','3','Di tungkuli''t kawastuhan,<br/>Nagtanggal sa diyus-diyosan;<br/>Kung di sinag ng ganda Mo,<br/>Tumambad sa mata ko.<br/>',NULL,40850,5);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40851,6);
INSERT INTO stanza VALUES('T437','4','Hindi rin ang pagwawasak,<br/>Ng di-yus-diyosang hungkag;<br/>Kundi silay ng ganda Niya,<br/>Puso Niya ay nakita.<br/>',NULL,40852,7);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40853,8);
INSERT INTO stanza VALUES('T437','5','Kandila''y di pinapatay,<br/>Kung araw di sumilay;<br/>Kung tag-init di dumating,<br/>Pangginaw di ''alisin.<br/>',NULL,40854,9);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40855,10);
INSERT INTO stanza VALUES('T437','6','Sulyap lumusaw kay Pedro,<br/>Esteban — tuon mukha;<br/>Kay Maria nakitangis Siya,<br/>Sa diyus-diyosan maglayo.<br/>',NULL,40856,11);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40857,12);
INSERT INTO stanza VALUES('T437','7','Pag-apawin aming saro,<br/>Manaig nang kumpleto;<br/>Mga sumama sa Kanya,<br/>Diyus-diyosan ay wala na.<br/>',NULL,40858,13);
INSERT INTO stanza VALUES('T437','chorus','Nabihag ng Kanyang ganda,<br/>Dalhin puri sa Kanya;<br/>Hari ngang walang kaparis,<br/>Putungan Siyang mabilis!<br/>',NULL,40859,14);
INSERT INTO stanza VALUES('T438','1','Tinalikdan ko ang mundo pati ang kaaliwan,<br/>Tinutuon aking puso sa mas banal na yaman;<br/>Di na ako maaakit ng silaw makamundo;<br/>Natawid ko na ang linyang naghiwalay sa mundo.<br/>',NULL,40860,1);
INSERT INTO stanza VALUES('T438','chorus','Layung-layo na sa likuran ko!<br/>Natawid ko na ang linyang<br/>Naghiwalay sa mundo.<br/>',NULL,40861,2);
INSERT INTO stanza VALUES('T438','2','Buhay ng pagkakasala aking tinalikdan na;<br/>Ang aking tuntungan ngayon si Kristo walang iba;<br/>Ngayon sa ilalim ng krus ako ay nasumpungan;<br/>Ako''y lumipat sa buhay mula sa kamatayan.<br/>',NULL,40862,3);
INSERT INTO stanza VALUES('T438','chorus','Layung-layo na sa likuran ko!<br/>Ako''y lumipat sa buhay<br/>Mula sa kamatayan.<br/>',NULL,40863,4);
INSERT INTO stanza VALUES('T438','3','Ako''y hindi na babalik sa dati kailan pa man,<br/>Pagka''t dito ay payapa, wala nang kahatulan;<br/>Pinalitan ko ang mundo ng aking Panginoon,<br/>Hindi ko na babalikan mundong aking tinapon.<br/>',NULL,40864,5);
INSERT INTO stanza VALUES('T438','chorus','Layung-layo na sa likuran ko!<br/>Hindi ko na babalikan<br/>Mundong aking tinapon.<br/>',NULL,40865,6);
INSERT INTO stanza VALUES('T438','4','Hanggang sa kawalang-hanggan, Kristo lamang ang akin,<br/>Liban sa Kanyang pag-ibig, wala na akong hiling;<br/>Di na ako mabubulag, puso''y kay Hesu-Kristo;<br/>Tinawid ko''ng Pulang Dagat, tinalikdan ang mundo.<br/>',NULL,40866,7);
INSERT INTO stanza VALUES('T438','chorus','Layung-layo na sa likuran ko!<br/>Tinawid ko''ng Pulang Dagat<br/>Tinalikdan ang mundo.<br/>',NULL,40867,8);
INSERT INTO stanza VALUES('T439','1','Paubayang lubos<br/>Sa Espiritu!<br/>Kanyang kapuspusan<br/>Dapat makamtan.<br/>Pampang titibagin,<br/>Lusong sa ''lalim<br/>Tamuhin lakas Niya,<br/>Kanyang pagpala.<br/>',NULL,40868,1);
INSERT INTO stanza VALUES('T439','chorus','Paubayang lubos<br/>Sa Panginoon;<br/>Sagutin tawag Niya<br/>Hangad yaman Niya.<br/>',NULL,40869,2);
INSERT INTO stanza VALUES('T439','2','Paubayang lubos<br/>Sa Espiritu!<br/>Lumubog, nang husto<br/>Wala ng ako!<br/>Sisidla''y mabasyo<br/>Mabasag sa Iyo;<br/>Hanggang mapunuan,<br/>Kakumpletuhan.<br/>',NULL,40870,3);
INSERT INTO stanza VALUES('T439','3','Paubayang lubos<br/>Pasya sa Ama;<br/>Ang kalooban Niya<br/>Ay isagawa.<br/>Iwan luho''t saya<br/>Susundan ko''y Siya;<br/>Akay Niya''y hintayin,<br/>Tinig Niya''y dinggin.<br/>',NULL,40871,5);
INSERT INTO stanza VALUES('T439','4','Paubayang lubos<br/>Nang walang hanggan<br/>Layon Niya pinili,<br/>Di aking mithi.<br/>Sa Kanya''y naglaho,<br/>Mga balak ko.<br/>Tila walang-wala<br/>Akin lahat Niya!<br/>',NULL,40872,7);
INSERT INTO stanza VALUES('T439','5','Paubayang lubos<br/>Napakatamis!<br/>Kanyang bihag mahal<br/>May layang tanghal.<br/>Lumaya sa sala,<br/>Pangamba''t duda;<br/>Lumaya sa hapis,<br/>Bigat naalis.<br/>',NULL,40873,9);
INSERT INTO stanza VALUES('T439','6','Paubayang lubos<br/>Anong ginhawa!<br/>Sa Kanyang presensya<br/>Naghintay may s''ya;<br/>Naghihintay ako<br/>Mapunuan Mo,<br/>Upang ang loob ko,<br/>Lubos mapino.<br/>',NULL,40874,11);
INSERT INTO stanza VALUES('T439','7','Pupunuin ako<br/>Ng Espiritu,<br/>Pinagpala ako<br/>Ng presensya Niya!<br/>Liwanag sa akin,<br/>Di na didilim.<br/>Sa pagpaubaya,<br/>Ibuhay nga Siya!<br/>',NULL,40875,13);
INSERT INTO stanza VALUES('T440','1','Naibukod, anong saya!<br/>Sila''y pinagpala nga;<br/>Mula sa lahat nagbitiw,<br/>Sa Kanya''y naging magiliw.<br/>Pahinga''y na kay Hesus,<br/>Pahinga''y na kay Hesus.<br/>',NULL,40876,1);
INSERT INTO stanza VALUES('T440','2','Kristo''y nagbukod sa akin,<br/>Nanguna sa lakarin;<br/>Paliwanag at larawan,<br/>Buhay Niya sa kabanalan.<br/>Sino ang masunurin?<br/>Sino ang masunurin?<br/>',NULL,40877,2);
INSERT INTO stanza VALUES('T440','3','Lumabas sa kampamento,<br/>Pagnaisin Mo ako;<br/>Galak magpasakop sa Iyo,<br/>Tiisin pagtakwil sa Iyo.<br/>Mapasa Iyo nang lubos,<br/>Mapasa Iyo nang lubos!<br/>',NULL,40878,3);
INSERT INTO stanza VALUES('T440','4','Sa maysala ay ibukod,<br/>At sa Iyo''y nagpalungkot;<br/>Gaya Mong mangangalaga,<br/>Sa maysala''y magtiyaga.<br/>"Hesus anong gagawin?"<br/>"Hesus anong gagawin?"<br/>',NULL,40879,4);
INSERT INTO stanza VALUES('T440','5','Panginoon sinisinta,<br/>Tayo''y magkalapit nga:<br/>Lubos sa Iyo ang paghandog,<br/>Lubos sa Iyo, naibukod,<br/>Hanggan sa walang hanggan,<br/>Hanggan sa walang hanggan!<br/>',NULL,40880,5);
INSERT INTO stanza VALUES('T441','1','Kay Hesus lahat sinuko,<br/>Lahat aking inalay;<br/>Titiwala''t iibigin,<br/>Siya''y aking ipamuhay.<br/>',NULL,40881,1);
INSERT INTO stanza VALUES('T441','chorus','Isinusuko, isinusuko,<br/>Sa Iyo, aking Panginoon,<br/>Ang tanang akin.<br/>',NULL,40882,2);
INSERT INTO stanza VALUES('T441','2','Lahat kay Hesus sinuko,<br/>Sa harap Niya''y yuyuko,<br/>Tinalikdan ko ang mundo;<br/>Hesus, tanggapin ako.<br/>',NULL,40883,3);
INSERT INTO stanza VALUES('T441','3','Lahat kay Hesus sinuko,<br/>Ako ay angkinin Mo;<br/>Ipadama ng ''Spiritu,<br/>Siyang nagpapatotoo.<br/>',NULL,40884,5);
INSERT INTO stanza VALUES('T441','4','Lahat kay Hesus sinuko,<br/>Alay ang sarili ko;<br/>Puspusan Mo ng pag-ibig,<br/>Pagpalain Mo ako.<br/>',NULL,40885,7);
INSERT INTO stanza VALUES('T441','5','Lahat kay Hesus sinuko,<br/>Nadama ko ang alab;<br/>Ang galak ng kaligtasan<br/>Sa akin tumatalab.<br/>',NULL,40886,9);
INSERT INTO stanza VALUES('T442','1','Lubos pagsuko — Panginoon,<br/>Lubos pagsuko sintang Poon;<br/>Nasa altar lahat,<br/>Pag-alay natupad,<br/>Tinubos Mo ako.<br/>Ako''y sa Iyo.<br/>',NULL,40887,1);
INSERT INTO stanza VALUES('T442','2','Lubos pagsuko — buhay lahat,<br/>Ibinigay Mo''y sa Iyo dapat.<br/>Sabihan Mo ako,<br/>Susunod sa I-yo.<br/>Hanggang walang hanggan,<br/>Ika''y sundan.<br/>',NULL,40888,2);
INSERT INTO stanza VALUES('T442','3','Lubos pagsuko — pilak, ginto,<br/>Anong yaman ang ''binigay Mo!<br/>Lahat pawang sa Iyo,<br/>Ako''y binili Mo;<br/>Angkinin Mo ako,<br/>O Hesus ko!<br/>',NULL,40889,3);
INSERT INTO stanza VALUES('T442','4','Lubos pagsuko — ako ay Iyo,<br/>Tagapagligtas na dibino;<br/>Ikaw ang buhay ko<br/>Kapuspusan sa Iyo;<br/>Si Kristo, di ako<br/>Lahat Kristo.<br/>',NULL,40890,4);
INSERT INTO stanza VALUES('T444','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40891,1);
INSERT INTO stanza VALUES('T444','1','Ialay lahat kay Kristo,<br/>Ito''y dapat kong gawin,<br/>Dugo Niyang pantubos mismo,<br/>Ang sa aki''y umangkin.<br/>',NULL,40892,2);
INSERT INTO stanza VALUES('T444','chorus','Ialay lahat kay Kristo,<br/>Bawa''t araw, oras ko!<br/>Ialay lahat kay Kristo,<br/>Bawa''t araw, oras ko!<br/>',NULL,40893,3);
INSERT INTO stanza VALUES('T444','2','Ialay lahat kay Kristo,<br/>Naisin ng puso ko,<br/>Pag-ibig Niya ang humipo,<br/>Sa pag-alay kong ito.<br/>',NULL,40894,4);
INSERT INTO stanza VALUES('T444','3','Ialay lahat kay Kristo,<br/>At pakabanalin Niya:<br/>Kalul''wa''t espiritu ko,<br/>At lahat kong taglay pa.<br/>',NULL,40895,6);
INSERT INTO stanza VALUES('T444','4','Ang kamay ko''y Iyong gamitin,<br/>Susunod ang paa ko,<br/>Ang mata ko''y Iyong akitin,<br/>Labi''y pupuri sa Iyo.<br/>',NULL,40896,8);
INSERT INTO stanza VALUES('T444','5','Nang nakita ko si Hesus,<br/>Nangupas na ang mundo,<br/>''Sang tingin sa dusa ng krus,<br/>Pasan Niya''y pasanin ko.<br/>',NULL,40897,10);
INSERT INTO stanza VALUES('T444','6','Luwang, haba, taas, lalim—<br/>Pag-ibig, biyaya Niya,<br/>Pangino''n, Hari''y purihin,<br/>Ang tulad ko''y mahal Niya.<br/>',NULL,40898,12);
INSERT INTO stanza VALUES('T445','1','Kunin Mo aking buhay,<br/>Ito''y aking inalay;<br/>Aking araw, sandali,<br/>Sa Iyo ako''y magpuri,<br/>Sa Iyo ako''y magpuri.<br/>',NULL,40899,1);
INSERT INTO stanza VALUES('T445','2','Mga kamay ko''y sa Iyo,<br/>Para sa gawain Mo;<br/>Mga paa ko''y maging<br/>Maganda sa Iyong tingin,<br/>Maganda sa Iyong tingin.<br/>',NULL,40900,2);
INSERT INTO stanza VALUES('T445','3','Sa Iyo na ang tinig ko,<br/>Aawitan Hari ko;<br/>Mga labi''y punuin,<br/>Mensahe Mo''y sambitin,<br/>Mensahe Mo''y sambitin.<br/>',NULL,40901,3);
INSERT INTO stanza VALUES('T445','4','Kunin pilak ko''t ginto,<br/>Kunin nang walang hinto;<br/>Kunin ang talino ko,<br/>Iyong gamitin nang husto,<br/>Iyong gamitin nang husto.<br/>',NULL,40902,4);
INSERT INTO stanza VALUES('T445','5','Kapasyahan ko''y sa Iyo,<br/>Hindi na sa ''kin ito;<br/>Iyo na rin ang puso ko;<br/>Ito ay I-yong trono,<br/>Ito ay I-yong trono.<br/>',NULL,40903,5);
INSERT INTO stanza VALUES('T445','6','Pag-ibig ko''y kunin Mo,<br/>Sa Iyo ibuhos ito;<br/>Kunin Mo sarili ko,<br/>Ako ay para sa Iyo,<br/>Ako ay para sa Iyo.<br/>',NULL,40904,6);
INSERT INTO stanza VALUES('T449','1','Kalooban Mo ang siyang sundin,<br/>Luád ako na huhugisin,<br/>Ayon sa ibig Mo ay gawin,<br/>Ako''y handa at masunurin.<br/>',NULL,40905,1);
INSERT INTO stanza VALUES('T449','2','Kalooban Mo nawa''y gawin,<br/>Ako ngayon ay Iyong subukin,<br/>Ako''y hugasan, paputiin,<br/>Ikaw lamang ang hihintayin.<br/>',NULL,40906,2);
INSERT INTO stanza VALUES('T449','3','Kalooban Mo ang siyang sundin,<br/>Ako''y tulungan, ang dalangin,<br/>Kapangyarihan ay I-yo rin,<br/>Ako''y hipuin, pagalingin.<br/>',NULL,40907,3);
INSERT INTO stanza VALUES('T449','4','Kalooban Mo ang siyang sundin,<br/>Ako''y lubusan Mong sakupin.<br/>Pagpuno ng Iyong Espiritu,<br/>Sa ''kin makita buhay Kristo.<br/>',NULL,40908,4);
INSERT INTO stanza VALUES('T451','1','Kumapit huwag magpumiglas,<br/>Mapalalakas;<br/>Pagpiglas, lungkot ang dala,<br/>Kapit, pahinga.<br/>',NULL,40909,1);
INSERT INTO stanza VALUES('T451','2','Pigilin sariling sikap,<br/>Hinto pagpiglas;<br/>Payapa ng Diyos matamo,<br/>Sa ''ting pagsuko.<br/>',NULL,40910,2);
INSERT INTO stanza VALUES('T451','3','Ang bigat kay Hesus asa,<br/>Siyang mag-aadya;<br/>Pag-ibig Niya ang umangkin,<br/>Kanyang alipin.<br/>',NULL,40911,3);
INSERT INTO stanza VALUES('T451','4','Ang sumunod at mamatay,<br/>May wagi''t buhay;<br/>"Di aking layon kundi Iyo"<br/>Bigay tagumpay.<br/>',NULL,40912,4);
INSERT INTO stanza VALUES('T452','1','Mundong luho lumayo ka,<br/>Imbing gana lisan na;<br/>Ilusyon di ko kailangan<br/>Isip di maguluhan.<br/>Diyus-diyosan aking iniwan<br/>Pati sarili ko man;<br/>Kay Kristo inalay ko na<br/>Upang mapasa Kanya.<br/>',NULL,40913,1);
INSERT INTO stanza VALUES('T452','chorus','Ako''y di akin,<br/>Ako''y di akin.<br/>Ako''y kay Hesus na,<br/>Sarili ko''y Kanya.<br/>',NULL,40914,2);
INSERT INTO stanza VALUES('T452','2','Ang kay Kristo''y mapabilang<br/>Anong kapahingahan!<br/>Ang lahat aking ''binigay,<br/>Yaman Niya''y matataglay.<br/>Pangino''n tanggapin ako<br/>Sa Iyo na ang lahat ko;<br/>Nang ako''y sa Iyo lumagi<br/>Ika''y aking bahagi.<br/>',NULL,40915,3);
INSERT INTO stanza VALUES('T452','3','Tao huwag nang magpunyagi.<br/>Iwan mo ang sarili;<br/>Ibigay lahat kay Hesus,<br/>Mapasa Kanyang lubos.<br/>Buhay sa iyo ginugol Niya,<br/>Upang matamo ka Niya.<br/>Pag-ibig mo bahagi Niya;<br/>Lahat Niya''y sa iyo na nga.<br/>',NULL,40916,5);
INSERT INTO stanza VALUES('T456','1','Si Hesus ang mabuhay sa akin,<br/>Tanging Siya ang aking lulugurin;<br/>Handa, malaya, at masunurin,<br/>Ako''y tiyak Niyang pagpapalain.<br/>',NULL,40917,1);
INSERT INTO stanza VALUES('T456','chorus','O Hesus, Panginoon,<br/>Ialay kong lubos,<br/>Tulad ng Iyong pagtubos,<br/>Buhay Mo''y ''binuhos;<br/>Ika''y tanging Poon ko,<br/>Puso ko''y Iyong trono,<br/>Ako''y mamumuhay ngayon<br/>Sa Iyo Kristong Poon.<br/>',NULL,40918,2);
INSERT INTO stanza VALUES('T456','2','Si Hesus namatay sa halip ko,<br/>Dinusta''t ''tinakwil sa Kalbaryo;<br/>Pumipilit yaring pag-ibig Niya<br/>Handog ang sarili ko sa Kanya.<br/>',NULL,40919,3);
INSERT INTO stanza VALUES('T456','3','Si Hesus ang mabuhay sa akin,<br/>Bawa''t gawa sa ngalan Niya''y tupdin;<br/>Handang mapighati at malugi,<br/>Bawa''t subok, sa krus ay bahagi.<br/>',NULL,40920,5);
INSERT INTO stanza VALUES('T456','4','Hesus ibuhay bawa''t sandali,<br/>Kasiyahan ko ang Kanyang ngiti;<br/>Hanapin ang mga nawawala,<br/>Mga pagod ay dalhin sa Kanya.<br/>',NULL,40921,7);
INSERT INTO stanza VALUES('T458','1','Kay Hesus mamuhay ako!<br/>Kapayapaan at lugod!<br/>Pagsubok man ''di mangamba<br/>Ibuhay Siya, kay lapit Niya.<br/>',NULL,40922,1);
INSERT INTO stanza VALUES('T458','chorus','Paglingkuran Ka nang higit,<br/>Papurihan Ka pa ulit;<br/>Mamuhay sa presensya Mo<br/>Hindi sa I-yo lalayo.<br/>',NULL,40923,2);
INSERT INTO stanza VALUES('T458','2','Kay Hesus mamuhay ako!<br/>May pahinga''t pagpapala!<br/>Mamuhay lamang sa Kanya,<br/>Kailanman gawin ibig Niya.<br/>',NULL,40924,3);
INSERT INTO stanza VALUES('T458','3','Ibuhay Hesus, saan man,<br/>Dalahin ko''y Siyang nagpasan;<br/>Iba''y lumisan, Siya''y tunay<br/>Tiwala sa Kanyang gabay.<br/>',NULL,40925,5);
INSERT INTO stanza VALUES('T458','4','Ibuhay Hesus, sa wakas<br/>Sa gloria Niya ko''y lumagpas;<br/>Doon tingin sa trono Niya,<br/>Mapakinggan: "Maayos na!"<br/>',NULL,40926,7);
INSERT INTO stanza VALUES('T460','1','Ang lahat iniwan ko na,<br/>Pasang-krus sinundan Ka;<br/>Pasakit di-alintana<br/>Dahil Iyong itinakda.<br/>Mga nais, hanap, asa<br/>Nawala''y di-ininda,<br/>Datapwa''t mayaman ako,<br/>Kristo''t Diyos bahagi ko.<br/>',NULL,40927,1);
INSERT INTO stanza VALUES('T460','2','Iwan man ako ng mundo<br/>Kagaya ko''y si Kristo;<br/>Tao''y lilinlang sa akin,<br/>Sa ''kin di Niya gagawin.<br/>Nang ngiti Mo Iyong ''pakita,<br/>Itakwil man ng iba<br/>Ako''y hindi mangangamba,<br/>Damdam ko''y mapayapa.<br/>',NULL,40928,2);
INSERT INTO stanza VALUES('T460','3','Tao man guluhin ako,<br/>Ako''y lalapit sa Iyo;<br/>Mabigat man pagdurusa<br/>Kay Kristo''y mapayapa.<br/>Kung mukha Mo''y Iyong ''pakita,<br/>''Nong dusa di mabata?<br/>''Nong galak sa ''kin aakit,<br/>Kung Ika''y di kalakip?<br/>',NULL,40929,3);
INSERT INTO stanza VALUES('T460','4','Biyaya dala''y l''walhati,<br/>Panalig ay baluti;<br/>Walang hanggan ay darating,<br/>T''yak Niya akong akayin.<br/>Mahihinto ang gawain,<br/>Matatapos lakbayin;<br/>Panalig maging paningin,<br/>Papuri, di na daing.<br/>',NULL,40930,4);
INSERT INTO stanza VALUES('T461','1','Sa lambak na may bukal, mga bulaklak,<br/>Sa Tagapagligtas ko ako''y sasama;<br/>Susundin ko ang tahak ng aking Patnubay,<br/>Hanggang kamtan ko ang putong ng buhay.<br/>',NULL,40931,1);
INSERT INTO stanza VALUES('T461','chorus','Sunod! sunod! susunod kay Hesus!<br/>Saan man Niya dalhin, ako''y susunod!<br/>Sunod! sunod! susunod kay Hesus!<br/>Kahit saan man ako ay susunod!<br/>',NULL,40932,2);
INSERT INTO stanza VALUES('T461','2','Kasama ni Hesus ako ay susulong,<br/>Kahit bumabagyo man o umaalon;<br/>Kamay Niya ang aakay, wala akong kaba,<br/>Wala nang panganib kung malapit Siya.<br/>',NULL,40933,3);
INSERT INTO stanza VALUES('T461','3','Maging sa patag o nasa kabundukan,<br/>Ang kaluluwa ko''y Kanyang iingatan;<br/>Siya ang nangunguna sa aking daraanan,<br/>Hanggang kamtan ko ang kal''walhatian.<br/>',NULL,40934,5);
INSERT INTO stanza VALUES('T462','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40935,1);
INSERT INTO stanza VALUES('T462','1','Paano ko Siyang mahalin?<br/>Siya''y handugan at lugurin?<br/>Di lumihis sa landas Niya<br/>At makahugpong sa Kanya?<br/>',NULL,40936,2);
INSERT INTO stanza VALUES('T462','2','Kahit landas ko''y masukal,<br/>Huwag hayaang ako''y mabuwal,<br/>Gawin akong masunurin,<br/>Tanging sa krus Mo''y tumingin.<br/>',NULL,40937,3);
INSERT INTO stanza VALUES('T462','3','Ako''y paalalahanan,<br/>Ang galak ay Iyong iniwan,<br/>Lungkot, gutom, pagod, uhaw,<br/>Walang lunas, gabi''t araw.<br/>',NULL,40938,4);
INSERT INTO stanza VALUES('T462','4','Para sa ''kin namatay Ka,<br/>Lugod Mo''y Iyong itinatwa;<br/>Kaginhawahan ng mundo<br/>Di matakwil para sa Iyo?<br/>',NULL,40939,5);
INSERT INTO stanza VALUES('T462','5','Ituring lahat ay lugi,<br/>Ikaw ang makamit lagi,<br/>Lahat sa aki''y sukal nga,<br/>Hinayang ba''ng ibigin Ka?<br/>',NULL,40940,6);
INSERT INTO stanza VALUES('T463','1','Panginoon, mahal ko:<br/>Ayaw kong lumaya!<br/>Pagka''t Manunubos ko,<br/>Nagbayad halaga.<br/>Di lilisang maglingkod,<br/>Ito''y pinagpala;<br/>Sa aking pagkapagod,<br/>Tunay Siya''ng pahinga.<br/>',NULL,40941,1);
INSERT INTO stanza VALUES('T463','2','Kanyang dugo''y ''binuhos,<br/>Buhay ko''y mawagi;<br/>Niligtas ''ko sa gapos<br/>Ng sala''t sarili.<br/>Kanya akong hinirang<br/>Na paglingkuran Siya;<br/>Laya, ako''y binigyan,<br/>Pumili, magpasya.<br/>',NULL,40942,2);
INSERT INTO stanza VALUES('T463','3','Hindi ko hahatiin<br/>Ang paglilingkod ko;<br/>Tangi lamang Siya''ng aking<br/>Pag-ukulan nito.<br/>At ngayon ang awit ko<br/>May galak, pagsamba:<br/>Panginoon mahal ko,<br/>Ayaw kong lumaya.<br/>',NULL,40943,3);
INSERT INTO stanza VALUES('T468','1','Ang Krus ba''y papasanin ko—<br/>Ang Kordero''y sundan?<br/>Takot bang magpatotoo,<br/>Itakwil ang ngalan?<br/>',NULL,40944,1);
INSERT INTO stanza VALUES('T468','chorus','Ang ngalang mahalaga,<br/>Buhay Mo''y binigay,<br/>Mahirap man, may biyaya,<br/>Ako''y magtagumpay.<br/>',NULL,40945,2);
INSERT INTO stanza VALUES('T468','2','Palankin ba ''king sasakyan<br/>Patungo sa langit?<br/>Habang iba''y naglalaban<br/>L''walhati''y makamit.<br/>',NULL,40946,3);
INSERT INTO stanza VALUES('T468','3','Wala bang dapat labanan?<br/>Tagas ay pasakan?<br/>Mundo ba''y pakisamahan?<br/>Nang ako''y tulungan?<br/>',NULL,40947,5);
INSERT INTO stanza VALUES('T468','4','Maghahari kung naglaban,<br/>Di-takot mangahas;<br/>Mapahiya, magdusa man,<br/>Salita Mo''y lakas.<br/>',NULL,40948,7);
INSERT INTO stanza VALUES('T469','1','Sino ang sa panig ng Panginoon?<br/>Sumunod, mamuhay lagi sa Kanya?<br/>Para kay Hesus handa siyang sumulong?<br/>Mundo''y itakwil at makipagbaka?<br/>',NULL,40949,1);
INSERT INTO stanza VALUES('T469','chorus','Dahil sa biyaya at Iyong pagtubos,<br/>Kami''y sa Iyong panig, Panginoong Diyos.<br/>',NULL,40950,2);
INSERT INTO stanza VALUES('T469','2','Sa hukbo umanib, makipagbaka,<br/>Di para sa putong o luwalhati,<br/>Kundi sa pag-ibig at biyaya Niya,<br/>Sa Kanya ako ay dapat kumampi.<br/>',NULL,40951,3);
INSERT INTO stanza VALUES('T469','3','Tinubos Mo upang maging Iyong bayan,<br/>Di ng ginto''t pilak, kundi ng dugo;<br/>Sa sumunod, biyaya''y walang hanggan,<br/>Malayang sumulong at taos-puso.<br/>',NULL,40952,5);
INSERT INTO stanza VALUES('T469','4','Mabagsik man ang laban o kaaway,<br/>Hukbo ng Panginoon ay matatag;<br/>Sa pamumuno Niya''y t''yak ang tagumpay,<br/>Katapatan, kapanaiga''y hayag.<br/>',NULL,40953,7);
INSERT INTO stanza VALUES('T469','5','Hinirang na kawal sa paglalaban,<br/>Tinawag at tapat sa Kanyang hukbo;<br/>Di-manlalamig, Hari''y paglingkuran,<br/>Maging matapang tunay, tapat, wasto.<br/>',NULL,40954,9);
INSERT INTO stanza VALUES('T471','1','Bakit ako manlalamig<br/>Sanhiin Kang mapighati<br/>Ika''y paghintayin?<br/>Nais Kitang mabalikan<br/>Hinding-hindi talikuran,<br/>At laging susundan.<br/>',NULL,40955,1);
INSERT INTO stanza VALUES('T471','2','Nais kong ialay sa Iyo,<br/>Ang buo kong pagkatao,<br/>Mundo ma''y maglaho,<br/>Nawa ako''y Iyong tanggapin<br/>Ang kalooban Mo''y sundin<br/>Lagi kong hangarin.<br/>',NULL,40956,2);
INSERT INTO stanza VALUES('T471','3','Lumingon man nagsisisi,<br/>Naligtas ko''y kakaunti<br/>Lungkot di mawari.<br/>Hesus, ako''y Iyong pahiran,<br/>Katauhan ko''y babaran.<br/>Maging Iyong daluyan.<br/>',NULL,40957,3);
INSERT INTO stanza VALUES('T471','4','Biyayang binigay lubha,<br/>Higit pa sa kaibigan Ka;<br/>Maging nobya Mo nga.<br/>Bahagi ko ay buhay Niya,<br/>Makaisa Kanyang dusa,<br/>Krus tanggaping kusa.<br/>',NULL,40958,4);
INSERT INTO stanza VALUES('T472','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,40959,1);
INSERT INTO stanza VALUES('T472','1','Marami ang sumisiksik sa kaharian,<br/>Nguni''t sa krus kakaunti ang pumapasan;<br/>Sakim sa biyaya, mundo''y hindi matakwil;<br/>Nais pagpalain ng Diyos, sa Diyos ay suwail.<br/>',NULL,40960,2);
INSERT INTO stanza VALUES('T472','2','Marami ang naghahangad ng luwalhati,<br/>Sa kadustaa''y walang makikibahagi;<br/>Ibig ay maghari, nguni''t ayaw malugi—<br/>Para kay Kristo, ituring lahat na dumi.<br/>',NULL,40961,3);
INSERT INTO stanza VALUES('T472','3','Marami ang kumakain sa Kanyang hapag,<br/>Subali''t sa pag-ayuno walang kaharap;<br/>Di mabilang ang umawit na kasama Niya,<br/>Subali''t sa pagbabantay ay halos wala.<br/>',NULL,40962,4);
INSERT INTO stanza VALUES('T472','4','Kung inihanda ng Panginoon ang lahat,<br/>Sila''y magpupuri at magpapasalamat,<br/>Nguni''t kung ang Panginoon ay makikiusap,<br/>Uutusan lamang ay tumututol agad.<br/>',NULL,40963,5);
INSERT INTO stanza VALUES('T472','5','Nguni''t ang mga umibig sa Panginoon,<br/>Dalita o pagpapala di tinatanong,<br/>Handang ialay kanilang buhay at dugo,<br/>Bigyan Mo ako ng pag-ibig tulad nito.<br/>',NULL,40964,6);
INSERT INTO stanza VALUES('T473','1','Hindi mabigkas ng labi<br/>Laya ng nilalang;<br/>Na sa suhol ay tumanggi<br/>Mapasa Diyos lamang.<br/>Kanya ang lahat ng bagay,<br/>Buhay, kamatayan,<br/>Si Kristo ang kanyang buhay,<br/>Hininga''t tirahan.<br/>',NULL,40965,1);
INSERT INTO stanza VALUES('T473','2','Kung katulad lamang natin<br/>Hari ang humirang;<br/>Kataka-takang tanggihan<br/>Maging Kanya lamang.<br/>Huwag sabihing pagdurusa,<br/>Anong karangalan:<br/>Sa makalangit na hukbo<br/>Ika''y mapabilang.<br/>',NULL,40966,2);
INSERT INTO stanza VALUES('T473','3','Gising! Tanggapin ang alok,<br/>Tingi maging buo!<br/>Mga tao''t pangyayari,<br/>Maglilingkod sa iyo.<br/>Sa iyo ang lahat ng bagay,<br/>Kung ikaw ay Kanya.<br/>At may walang hanggang buhay.<br/>Ikaw sa loob Niya.<br/>',NULL,40967,3);
INSERT INTO stanza VALUES('T474','1','Hesus ako''y kaisa Mo,<br/>''Sang espiritu sa Iyo;<br/>Lahat Mo ngayon, taglay ko,<br/>Tahan sa ''kin lahat Mo.<br/>',NULL,40968,1);
INSERT INTO stanza VALUES('T474','chorus','Kaisa Mo Hesus,<br/>Kaisa Mong lubos;<br/>Yaman Mo aking bahagi,<br/>Lahat Ka sa ''kin lagi.<br/>',NULL,40969,2);
INSERT INTO stanza VALUES('T474','2','Makabahagi nga ako<br/>Sa pantaong buhay Mo;<br/>Ang ganap na pagsunod Mo,<br/>Laan sa paggamit ko.<br/>',NULL,40970,3);
INSERT INTO stanza VALUES('T474','3','Sa pagkapako kai-sa Mo,<br/>Sa krus ako''y namatay;<br/>Patay na sa sanlibutan,<br/>Sanlibutan di''y patay.<br/>',NULL,40971,5);
INSERT INTO stanza VALUES('T474','4','Panginoon kaisa Mo,<br/>Sa muling-pagkabuhay;<br/>Ang buhay na Ikaw Mismo,<br/>Ngayon ay aking taglay.<br/>',NULL,40972,7);
INSERT INTO stanza VALUES('T474','5','Sa pag-akyat kaisa Mo,<br/>Sa langit kasama Mo;<br/>Dito''y manlalakbay ako,<br/>Buhay ko''y kubli sa Iyo.<br/>',NULL,40973,9);
INSERT INTO stanza VALUES('T474','6','Sa pagkaluklok kaisa Mo,<br/>Awtoridad taglay ko,<br/>Katulad na kaisa Mo<br/>Sa buhay, espiritu.<br/>',NULL,40974,11);
INSERT INTO stanza VALUES('T475','1','Ika''y Anak walang hanggan,<br/>Panlahat kamatayan,<br/>Kaisang espiritu Mo<br/>Kaisa sa buhay Mo.<br/>Kaisa sa Anak sinta,<br/>Tagapagmana ng Ama,<br/>Ako''y naging bahagi Mo,<br/>Tahanan ng Espiritu.<br/>',NULL,40975,1);
INSERT INTO stanza VALUES('T475','2','Kaisa Mo, Anak-tao,<br/>Bahagi ng Katawan Mo,<br/>Sa pagsilang Mo''y kasabay,<br/>Kalakip sa paglakbay.<br/>Pinahiran, kaisa Mo<br/>Tumanggap ng ''Spiritu,<br/>Bawa''t oras, bawa''t araw,<br/>Kasamang gumagawa.<br/>',NULL,40976,2);
INSERT INTO stanza VALUES('T475','3','Itinakwil na Anak Ka,<br/>Hinatulan, sinumpa,<br/>Kamatayang kalakip Mo,<br/>Hades, sala''y tinalo.<br/>Sa pagkabuhay kai-sa Mo,<br/>Kamatayan tinalo;<br/>Namuhay sa kabaguhan<br/>Namunga ng kat''wiran.<br/>',NULL,40977,3);
INSERT INTO stanza VALUES('T475','4','Kai-sa, Anak na umakyat,<br/>Sa trono''y higit sa lahat,<br/>Taglay Mong kapangyarihan,<br/>Akin ding katayuan.<br/>Kai-sa, Anak na babalik,<br/>Sa l''walhati, paglapit<br/>Ng Iyong mahal na presensya,<br/>Magpakailanman kai-sa.<br/>',NULL,40978,4);
INSERT INTO stanza VALUES('T477','1','Sanlibong beses man,<br/>Si Kristo''y isilang;<br/>Kaawa-awa ka,<br/>Kung di-nasilang Niya.<br/>Ang Krus sa Golgotha,<br/>Di ''ligtas kalul''wa;<br/>Ang Krus sa puso nga,<br/>Pagagalingin ka.<br/>',NULL,40979,1);
INSERT INTO stanza VALUES('T477','chorus','O, Krus Mo Kristo''y akin,<br/>Sa puso''y tanggapin;<br/>Sa sarili ko''y mamatay,<br/>Ako sa Iyo''y mabuhay.<br/>',NULL,40980,2);
INSERT INTO stanza VALUES('T477','2','Anong mahal mo nga,<br/>Magiging gayon ka;<br/>Diyos, kung Diyos mahal mo<br/>Lupa, kung gusto mo.<br/>Sarili''y lisanin,<br/>Diyos iyong papasukin,<br/>Ikaw ay mamatay<br/>Nang Siya ay mabuhay.<br/>',NULL,40981,3);
INSERT INTO stanza VALUES('T477','3','Pinakamaikli<br/>Daan iyong mapili<br/>Sa Diyos, madala ka:<br/>Pag-ibig sa Kanya.<br/>Alisin ang mundo,<br/>Mula sa iyong puso;<br/>Punuin, banalin,<br/>Pag-ibig ng Diyos din.<br/>',NULL,40982,5);
INSERT INTO stanza VALUES('T479','1','Lugar kahanga-hanga,<br/>Hesus sa ''kin bigay nga!<br/>Niligtas ng biyaya,<br/>Matulad na sa Kanya.<br/>Mahayag magkasama,<br/>Ako''t Siya magkagaya;<br/>Sa paglakad kasama,<br/>Ako ay katulad Niya.<br/>',NULL,40983,1);
INSERT INTO stanza VALUES('T479','chorus','Katulad Niya, Katulad Niya,<br/>Mapahanga, katulad Niya;<br/>Niligtas ng Kanyang biyaya,<br/>Kami''y magkai-sa''t magkagaya.<br/>',NULL,40984,2);
INSERT INTO stanza VALUES('T479','2','Kasama Niyang namatay,<br/>Maging sa pagkabuhay;<br/>Sa sumpa napalaya,<br/>Nabuhay kasama Niya.<br/>Kaisa sa trono Niya,<br/>Sa pagka-anak kai-sa;<br/>Tulad ng mag-asawa,<br/>Nagkai-sa puno''t sanga.<br/>',NULL,40985,3);
INSERT INTO stanza VALUES('T479','3','Sa natupad kaisa,<br/>Sa dalangin kaisa;<br/>Halaga Niya matamo,<br/>Maangkin tiwala ko.<br/>Pananalig, pagsinta,<br/>Sa buhay pawang kai-sa;<br/>''Spiritu Niya kasama,<br/>Maging banal tulad Niya.<br/>',NULL,40986,5);
INSERT INTO stanza VALUES('T481','1','Kalakip Ni-yang napako,<br/>Ako sa sala''t mundo;<br/>Kay Kristo aking nakamtan,<br/>Buhay sa kamatayan.<br/>Salamuha sa dusa Niya<br/>Wangis sa kamatayan;<br/>Manliligtas ko susundan,<br/>Sa Kalbaryong daan Niya.<br/>',NULL,40987,1);
INSERT INTO stanza VALUES('T481','chorus','Patungo sa Kalbaryo.<br/>Ang Tagapagligtas ko,<br/>Poon, tulungan ako,<br/>Sumama sa Kalbaryo.<br/>',NULL,40988,2);
INSERT INTO stanza VALUES('T481','2','Kung batid ang pagkabuhay<br/>Di mahirap mamatay;<br/>Kung puso''y apaw ligaya,<br/>Di mahirap magdusa.<br/>Sa lakas pagkabuhay Niya,<br/>Sa ''kin nananahan Siya,<br/>At may galak ang puso ko,<br/>Patungo sa Kalbaryo.<br/>',NULL,40989,3);
INSERT INTO stanza VALUES('T481','3','Kung Kristo''y kai-sang namatay,<br/>Gayunding mabubuhay;<br/>Sa dusa makibahagi,<br/>Tayo ay maghahari.<br/>Anong galak sa umaga,<br/>Nang Poon magsabi na:<br/>"Ako ay sinamahan mo<br/>Patungo sa Kalbaryo."<br/>',NULL,40990,5);
INSERT INTO stanza VALUES('T482','1','Pinako sa krus kasama<br/>Ni Kristo napalaya;<br/>Nabuhay muling kasama,<br/>Buhay Niya namahala.<br/>',NULL,40991,1);
INSERT INTO stanza VALUES('T482','chorus','Namatay kasama ni Kristo,<br/>Ligtas sa sala''t mundo;<br/>Nabuhay kasama ni Kristo,<br/>Sa buhay ko namuno.<br/>',NULL,40992,2);
INSERT INTO stanza VALUES('T482','2','Hiwagang dati''y nakubli,<br/>Nabatid nang manalig;<br/>Kristo sa aki''y l''walhati,<br/>Sambiting muli''t muli.<br/>',NULL,40993,3);
INSERT INTO stanza VALUES('T482','3','Kalikasan lihim kubli:<br/>Baong butil, anihin;<br/>Hinugpong sangang mahusay,<br/>Kamit mayamang buhay.<br/>',NULL,40994,5);
INSERT INTO stanza VALUES('T482','4','Ang lihim ng kabanalan—<br/>Di atin kundi Kanya;<br/>Poon, hungkagin, punuan<br/>Ng I-yong kapuspusan.<br/>',NULL,40995,7);
INSERT INTO stanza VALUES('T482','5','Sa sakit ito ang lunas,<br/>Mamatay lahat lakas,<br/>Sa buhay Niya''t kapuspusan,<br/>Kailangan tinustusan.<br/>',NULL,40996,9);
INSERT INTO stanza VALUES('T482','6','Mula sa Krus hanggang Trono,<br/>Kasaysayan ng Poon,<br/>Tulad Niya landas sa gloria,<br/>Kamatayan patungo.<br/>',NULL,40997,11);
INSERT INTO stanza VALUES('T486','1','Kamatayan Niya''y nabilang sa ''kin,<br/>Dibinong buhay binigyan ako;<br/>Luwalhati Niya ay hihintayin,<br/>Bawa''t sandali, ako ay sa Iyo.<br/>',NULL,40998,1);
INSERT INTO stanza VALUES('T486','chorus','Laging iingatan ng pag-ibig,<br/>Laging buhay ay aking matamo,<br/>Laging kay Hesus ako''y tumitig,<br/>Bawa''t sandali, ako ay sa Iyo.<br/>',NULL,40999,2);
INSERT INTO stanza VALUES('T486','2','Walang labanang di Siya''ng namuno,<br/>Walang tagumpay di Siya''ng nagbigay;<br/>Hanggang sa kamtin ang putong, trono,<br/>Bawa''t sandali, Siya ang kaakbay.<br/>',NULL,41000,3);
INSERT INTO stanza VALUES('T486','3','Walang subok di Siya mag-alalay,<br/>Walang bigat di Siya ang magpasan,<br/>Walang lungkot di Siya nakiramay,<br/>Bawa''t sandali, aalagaan.<br/>',NULL,41001,5);
INSERT INTO stanza VALUES('T486','4','Walang sakit at walang halinghing,<br/>Walang luha at walang hinaing,<br/>Walang panganib di Niya pansinin,<br/>Bawa''t sandali, ako''y isipin.<br/>',NULL,41002,7);
INSERT INTO stanza VALUES('T486','5','Walang hinang di Niya naramdaman,<br/>Walang sakit di Niya pagalingin,<br/>Bawa''t sandali, lungkot, galak man,<br/>Poong Hesus ko, kasama pa rin.<br/>',NULL,41003,9);
INSERT INTO stanza VALUES('T488','1','Hiwaga inihayag Mo;<br/>Kasama Mong namatay ''ko;<br/>Walang ibang lakas, daan,<br/>Nang magtagumpay sa tanan.<br/>',NULL,41004,1);
INSERT INTO stanza VALUES('T488','2','Akin na rin nga ang krus Mo,<br/>Sumilay liwanag nito;<br/>Nang kasamang namatay Mo,<br/>Nawalan ng lakas mundo.<br/>',NULL,41005,2);
INSERT INTO stanza VALUES('T488','3','Yamang pinakong kasama,<br/>Sala''t sarili lumaya;<br/>Di na hangad makalupa,<br/>Di na asam mundong pala.<br/>',NULL,41006,3);
INSERT INTO stanza VALUES('T488','4','Kaya mas lalapit ako,<br/>Doon sa krus ng Kalbaryo;<br/>Buhay, awtoridad Mo''y ''kin,<br/>''Pagkat Ika''y kaisa rin.<br/>',NULL,41007,4);
INSERT INTO stanza VALUES('T488','5','Pagdating Mo diyablo''y talo,<br/>Bagsak gawa''t lakas nito;<br/>Sa ''yo mananaig ako,<br/>Mapatunayan lakas Mo.<br/>',NULL,41008,5);
INSERT INTO stanza VALUES('T488','6','Aking pag-asang tagumpay,<br/>Lubos sa Iyong pagkamatay;<br/>Landas Mo''y aking lakad din,<br/>Nang layon ng Diyos abutin.<br/>',NULL,41009,6);
INSERT INTO stanza VALUES('T488','7','Tanggaping may pananalig<br/>Kamatayan Mong kaniig,<br/>Malalim kong maunawa,<br/>Nang sa laman ay lumaya.<br/>',NULL,41010,7);
INSERT INTO stanza VALUES('T488','8','Nais kong magtagumpay nga,<br/>Kasama Mong maghari pa;<br/>Kung krus may galak ay dalhin,<br/>L''walhati''y mapasaatin.<br/>',NULL,41011,8);
INSERT INTO stanza VALUES('T489','1','Hesus nang nasa lupa Ka,<br/>Matatapat ang kasama;<br/>Tila kilala Ka nila,<br/>Nguni''t di Ka naunawa.<br/>',NULL,41012,1);
INSERT INTO stanza VALUES('T489','2','Narinig nila tinig Mo,<br/>Di malimot gandang anyo;<br/>Sumiksik, tumitig sa Iyo,<br/>Hindi batid kung sino Ka.<br/>',NULL,41013,2);
INSERT INTO stanza VALUES('T489','3','May tabing na gaya nila;<br/>Wari ba''y kilala Ka na;<br/>Magaling man pagkilala,<br/>Hindi Ka pa maunawa.<br/>',NULL,41014,3);
INSERT INTO stanza VALUES('T489','4','Ngayon Espiritu Ka na,<br/>Naging ang Mang-aaliw pa;<br/>Sa puso ko ihayag Mo,<br/>Sa pagsapit Mo sa templo.<br/>',NULL,41015,4);
INSERT INTO stanza VALUES('T489','5','Espiritu''y punuin nga,<br/>Bawa''t sulok ng kalul''wa;<br/>Bawa''t bahagi''y hipuin,<br/>Tumimo Ka at baguhin.<br/>',NULL,41016,5);
INSERT INTO stanza VALUES('T489','6','Nagpahayag Espiritu,<br/>Mas tunay Ka sa ''king puso,<br/>Di man narinig, nakita,<br/>Sa ''kin lubhang totoo Ka.<br/>',NULL,41017,6);
INSERT INTO stanza VALUES('T489','7','Sa Iyong habag hinayag Mo<br/>Sarili Mo''y Espiritu;<br/>Anong mas tunay sa mundo,<br/>Mas tapat sa ''min kaysa Iyo?<br/>',NULL,41018,7);
INSERT INTO stanza VALUES('T489','8','Dalangin ko Espiritu,<br/>Umapaw sa ''kin nang husto,<br/>Bawa''t parte''y mal''walhati,<br/>Ikaw at Diyos lumagi.<br/>',NULL,41019,8);
INSERT INTO stanza VALUES('T489','9','Itong buhay anong talik,<br/>Nagkahalo lupa''t langit;<br/>Iyong presensya puspos kami;<br/>Aming puso ay pupuri.<br/>',NULL,41020,9);
INSERT INTO stanza VALUES('T490','1','Nang Ama''y di pa kilala,<br/>Ama''y nasa Iyo sa lupa;<br/>Kung Siya''y nais makilala,<br/>Panginoon, kilanlin Ka.<br/>',NULL,41021,1);
INSERT INTO stanza VALUES('T490','2','Nguni''t no''ng nasa lupa Ka,<br/>Kilala Ka ng iilan,<br/>Pinagdagsaan ng madla,<br/>Di Ka nahipo, nakamtan.<br/>',NULL,41022,2);
INSERT INTO stanza VALUES('T490','3','Ngayon Ika''y Espiritu,<br/>Noon, ang Ama''y suma-Iyo,<br/>Ama''y nakilala sa Iyo,<br/>Ikaw naman sa ''Spiritu.<br/>',NULL,41023,3);
INSERT INTO stanza VALUES('T490','4','Hindi Ka na dating laman,<br/>Na napagal sa paglibot;<br/>Sa Espiritung nanahan,<br/>Sa ''min Iyong tustos umabot.<br/>',NULL,41024,4);
INSERT INTO stanza VALUES('T490','5','Noon tinawag Kang Ama,<br/>Ngayo''y Espiritu Santo,<br/>Siya''y Ikaw sa ibang porma,<br/>Nang sa amin manahan Ka.<br/>',NULL,41025,5);
INSERT INTO stanza VALUES('T490','6','Dahil Espiritu Ka nga,<br/>Agos ng buhay natanto,<br/>L''walhati Mo''t kalooban,<br/>Mahiwagang kalikasan.<br/>',NULL,41026,6);
INSERT INTO stanza VALUES('T490','7','Puso namin purihin Ka,<br/>Yamang batid na tunay Ka,<br/>Walang magiliw kaysa Iyo,<br/>Walang kaibig-ibig man.<br/>',NULL,41027,7);
INSERT INTO stanza VALUES('T491','1','Ika''y nasa laman noon,<br/>Mababaw na nakilala;<br/>Bilang Espiritu ngayon,<br/>Malalim sa ''king unawa.<br/>',NULL,41028,1);
INSERT INTO stanza VALUES('T491','2','Sa laman, Manunubos ko,<br/>Sa labas ang pakitungo;<br/>Taga-aliw na ''Spiritu<br/>Sa loob nakaisa ko.<br/>',NULL,41029,2);
INSERT INTO stanza VALUES('T491','3','''Spiritu sa ''king ''spiritu<br/>Naghahayag, nananahan;<br/>Presensya at Persona Mo<br/>Naging makatotohanan.<br/>',NULL,41030,3);
INSERT INTO stanza VALUES('T491','4','Mga alagad nang una<br/>Ay kasama Mong namuhay,<br/>Nguni''t di hihigit sila<br/>Sa pagkilala kong tunay.<br/>',NULL,41031,4);
INSERT INTO stanza VALUES('T491','5','Panginoong Espiritu<br/>Sa loob ko''y nananahan;<br/>Di nakita ni nahipo,<br/>Nguni''t aking kasintahan.<br/>',NULL,41032,5);
INSERT INTO stanza VALUES('T491','6','Espiritung nananahan<br/>Tumutustos ng kat''wiran,<br/>Kabanalan, katubusan,<br/>Pamumunga, karunungan.<br/>',NULL,41033,6);
INSERT INTO stanza VALUES('T491','7','''Spiritu sa ''king ''spiritu,<br/>Ika''y naging kaisa ko;<br/>Bawa''t sandali ay ako,<br/>Palagi ring Ikaw Mismo.<br/>',NULL,41034,7);
INSERT INTO stanza VALUES('T492','1','Panginoon, gawain Mo<br/>Di lamang sa krus huminto,<br/>Patuloy Kang namumuhay,<br/>Ibang anyo ang Iyong taglay.<br/>',NULL,41035,1);
INSERT INTO stanza VALUES('T492','2','Patuloy Kang nagsalita,<br/>Nagliligtas, gumigiya,<br/>Ika''y naging Espiritu,<br/>Tatanglawan mga tao.<br/>',NULL,41036,2);
INSERT INTO stanza VALUES('T492','3','Espiritu Ka''t lakas pa,<br/>Patuloy Kang gumagawa:<br/>Paghikayat at pagkilos,<br/>Pag-aliw at pag-uutos.<br/>',NULL,41037,3);
INSERT INTO stanza VALUES('T492','4','Ika''y naging Espiritu,<br/>Pagdating Niya''y pagdating Mo,<br/>Pagpuspos Mo''y pagtahan Niya,<br/>Espiritu Mo, Ika''y Siya.<br/>',NULL,41038,4);
INSERT INTO stanza VALUES('T492','5','Sa loob ko''y Siyang tumupad<br/>Ng mga utos Mo''t hangad,<br/>Tulad nang nasa lupa Ka,<br/>Tinupad layon ng Ama.<br/>',NULL,41039,5);
INSERT INTO stanza VALUES('T492','6','Ang makilala''t sundin Siya<br/>Ay makilala''t sundin Ka;<br/>Pagbababad, pag-apaw Niya,<br/>Yaon ay pagpuspos Mo nga.<br/>',NULL,41040,6);
INSERT INTO stanza VALUES('T492','7','Di Ka sa malayong langit,<br/>Na di muling lumalapit,<br/>Nanatili Ka sa lupa,<br/>Sa puso ko''y nakatira.<br/>',NULL,41041,7);
INSERT INTO stanza VALUES('T493','1','Poon Ika''y Espiritu,<br/>Binigyan ng buhay ako;<br/>Ang yaman Mo''y aking tustos<br/>Mal''walhati at maka-Diyos.<br/>',NULL,41042,1);
INSERT INTO stanza VALUES('T493','2','Poon Ika''y Espiritu,<br/>Ang nagpalaya''y lakas Mo;<br/>Ang kautusan ng buhay<br/>Namahala''t pumatnubay.<br/>',NULL,41043,2);
INSERT INTO stanza VALUES('T493','3','Poon, Ika''y Espiritu,<br/>Baguhin, tigmakin ako,<br/>Mahubog sa Iyong larawan,<br/>Silay Iyong kaliwanagan.<br/>',NULL,41044,3);
INSERT INTO stanza VALUES('T493','4','Poon Ika''y Espiritu,<br/>Nanahan sa ''spiritu ko;<br/>Nakihalo, nakigawa<br/>Ang dalawa''y nagkaisa.<br/>',NULL,41045,4);
INSERT INTO stanza VALUES('T493','5','Turuang magsanay ako<br/>Mahipo Ka sa ''spiritu;<br/>Lumakad sa Iyong ''Spiritu<br/>Mamuhay tunay sa I-yo.<br/>',NULL,41046,5);
INSERT INTO stanza VALUES('T494','1','Kristo''y patotoo ng Diyos<br/>Sa esensya man o kilos;<br/>Gloria''t kalikasan ng Diyos,<br/>Kay Kristo nakitang lubos.<br/>',NULL,41047,1);
INSERT INTO stanza VALUES('T494','2','Kumpletong patotoo Siya,<br/>Kautusan hinigtan Niya;<br/>Utos nasa titik lamang,<br/>Siya''y buhay, kapangyarihan.<br/>',NULL,41048,2);
INSERT INTO stanza VALUES('T494','3','Kapuspusan ng Pagka-Diyos,<br/>Nananahanan sa Kanya,<br/>Diyos pagsasakatawan Niya,<br/>Sisidlang tirahan ng Diyos.<br/>',NULL,41049,3);
INSERT INTO stanza VALUES('T494','4','Kanyang tinanghal Diyos Ama,<br/>Gloria ng Diyos pinakita;<br/>Layon ng Diyos, daan ng Diyos,<br/>Pawang ''hinayag Niyang lubos.<br/>',NULL,41050,4);
INSERT INTO stanza VALUES('T494','5','Kristo bilang Espiritu,<br/>Pumaritong bahagi ko;<br/>Sa ''spiritu ko''y tamasa,<br/>Anuman ang Diyos akin na!<br/>',NULL,41051,5);
INSERT INTO stanza VALUES('T495','1','Si Kristo''y sentro ng Diyos,<br/>Pangkalahatan ng Diyos,<br/>Lugod ng Diyos at galak,<br/>Sa buong eternidad.<br/>',NULL,41052,1);
INSERT INTO stanza VALUES('T495','2','Pagsakatawan ng Diyos,<br/>Kapuspusan tumahan;<br/>Dibinong kataasan,<br/>Di Siya mahihigitan.<br/>',NULL,41053,2);
INSERT INTO stanza VALUES('T495','3','Sa Kanya''y layon ng Diyos,<br/>Lahat Kanyang mapuspos,<br/>Lahat sa langit, lupa,<br/>Sa Kanya ay ginawa.<br/>',NULL,41054,3);
INSERT INTO stanza VALUES('T495','4','Paglikha''y para Kristo,<br/>Ang lahat ginawa Niya;<br/>Lahat pinairal Niya,<br/>Sentro''t palibot ay Siya.<br/>',NULL,41055,4);
INSERT INTO stanza VALUES('T495','5','Siyang lahat sa pagtubos,<br/>Pinagkasundong lubos<br/>Sa Diyos, at sa dugo Niya,<br/>Ngayon ay payapa na.<br/>',NULL,41056,5);
INSERT INTO stanza VALUES('T495','6','Simula ng lahat Siya,<br/>Ulo rin ng Ekklesia;<br/>Nilalaman Niya, buhay,<br/>Ang talagang panganay.<br/>',NULL,41057,6);
INSERT INTO stanza VALUES('T495','7','Hari sa Kaharian,<br/>Kanya''y kapangyarihan;<br/>Namahala sa gloria<br/>Maging sa langit, lupa.<br/>',NULL,41058,7);
INSERT INTO stanza VALUES('T495','8','Bagong langit at lupa,<br/>Sentro ng lahat ay Siya;<br/>Pagka-Diyos, pagkatao<br/>Walang hanggan Siyang sentro.<br/>',NULL,41059,8);
INSERT INTO stanza VALUES('T495','9','Layon ng Diyos kay Kristo,<br/>Sa lahat unang p''westo;<br/>Kristo ng lahat ngayon,<br/>Ating danasin ngayon.<br/>',NULL,41060,9);
INSERT INTO stanza VALUES('T496','1','Kristo ang tanging katotohanan<br/>Ng Pagka-Diyos, tao''t bagay — tanan;<br/>Kung wala Siya, Diyos di matagpuan,<br/>Lahat man ay kasinungalingan.<br/>',NULL,41061,1);
INSERT INTO stanza VALUES('T496','2','Mga sagisag, mga larawan,<br/>Malaki''t maliit na kailangan,<br/>Anino lamang ni Kristong tunay,<br/>Sa akin Siya ang lahat ng bagay.<br/>',NULL,41062,2);
INSERT INTO stanza VALUES('T496','3','Ang lahat nga''y walang kabuluhan,<br/>Si Kristo ang realidad lamang;<br/>Matamasa, maangkin man lahat,<br/>Hungkag pa rin kung si Kristo''y wala.<br/>',NULL,41063,3);
INSERT INTO stanza VALUES('T496','4','Kristo ay Diyos, Panginoong tunay,<br/>Tunay nating liwanag at buhay,<br/>Tunay nating pagkain, inumin,<br/>Kristo''y damit, kalakasan natin.<br/>',NULL,41064,4);
INSERT INTO stanza VALUES('T496','5','Si Kristo rin ang Siyang realidad<br/>Doktrina''t teolohiyang lahat;<br/>Kung wala Siya pawang titik lamang<br/>Ang pangkasulatang kaalaman.<br/>',NULL,41065,5);
INSERT INTO stanza VALUES('T496','6','Kristo ang katunayan ng tanan,<br/>Ng panahon, dako, at anuman;<br/>Kristo ang tanging katotohanan,<br/>Walang hanggan, walang katapusan.<br/>',NULL,41066,6);
INSERT INTO stanza VALUES('T497','1','Pinakahulugan ng biyaya—<br/>Diyos sa Anak ating matamasa;<br/>Hindi anumang bagay na tangi,<br/>Kundi Diyos Mismo ating bahagi.<br/>',NULL,41067,1);
INSERT INTO stanza VALUES('T497','2','Nagkatawang-tao ang Diyos Mismo<br/>Nang Siya''y matanggap ng mga tao;<br/>Ang biyayang ipinagkaloob<br/>Ay si Kristong nasa ating loob.<br/>',NULL,41068,2);
INSERT INTO stanza VALUES('T497','3','Sukal lahat kay Apostol Pablo,<br/>Kanyang biyaya''y tanging si Kristo,<br/>Nang dahil dito siya ay nagpagal<br/>Higit sa lahat ng mga banal.<br/>',NULL,41069,3);
INSERT INTO stanza VALUES('T497','4','Si Kristo sa ati''y kalakasan,<br/>Biyayang sapat, maaasahan,<br/>Napalakas espiritu natin,<br/>Kalooban ng Diyos ay gagawin.<br/>',NULL,41070,4);
INSERT INTO stanza VALUES('T497','5','Ang biyaya kailangang danasin,<br/>Ang buhay na siyang Kristo Mismo rin;<br/>Ang biyaya''y nais kong tantuin,<br/>Hihigit pa ang tatamasahin.<br/>',NULL,41071,5);
INSERT INTO stanza VALUES('T499','1','Kapayapaan at buhay!<br/>Kristo sa ''kin nabubuhay.<br/>Kalakip Niya na pinako;<br/>Katotohanang natamo.<br/>Di na ''ko ang nabubuhay,<br/>Kundi si Kristo ang buhay.<br/>[Di na ''ko ang nabubuhay,<br/>Kundi si Kristo ang buhay.]<br/>',NULL,41072,1);
INSERT INTO stanza VALUES('T499','2','Kapahingahan at lugod!<br/>Kristo sa ''kin nahuhubog.<br/>Kalikasan at buhay Niya,<br/>Sa akin isinagawa.<br/>Lahat ko ay natapos na,<br/>Lahat ni Kristo''y akin na.<br/>[Lahat ko ay natapos na,<br/>Lahat ni Kristo''y akin na.]<br/>',NULL,41073,2);
INSERT INTO stanza VALUES('T499','3','Ating ipagmamalaki!<br/>Kristo sa ''kin mapalaki!<br/>Walang dapat ikahiya,<br/>Kasawian o biyaya.<br/>Sa buhay ma''t kamatayan,<br/>Si Kristo''y patotohanan.<br/>[Sa buhay ma''t kamatayan,<br/>Si Kristo''y patotohanan.]<br/>',NULL,41074,3);
INSERT INTO stanza VALUES('T499','4','O, gantimpala''y tamuhin!<br/>Kristo ang aking layunin,<br/>Puso''y walang ibang hangad,<br/>Liban kay Kristo Siyang lahat.<br/>Pag-asa, putong, l''walhati,<br/>Si Kristong walang kauri!<br/>[Pag-asa, putong, l''walhati,<br/>Si Kristong walang kauri!]<br/><!--(Ulitin ang huling dalawang linya ng bawa''t saknong)--><br/>',NULL,41075,4);
INSERT INTO stanza VALUES('T500','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41076,1);
INSERT INTO stanza VALUES('T500','1','O anong kapangyarihan!<br/>Binuhay ng Diyos si Kristo;<br/>''Niluklok sa Kanyang kanan,<br/>Sa lahat Siya ang Pangulo.<br/>Lahat ay pinasuko Niya<br/>Nang dahil sa Ekklesia.<br/>[Lahat ay pinasuko Niya<br/>Nang dahil sa Ekklesia.]<br/>',NULL,41077,2);
INSERT INTO stanza VALUES('T500','2','Kay hiwaga at kay tunay!<br/>Ako ay sangkap ni Kristo;<br/>Mga banal ay kaugnay,<br/>Bagong tao''y itatayo.<br/>Pangulo kaisa natin,<br/>Ayon sa Diyos, plano''y tupdin.<br/>[Pangulo kaisa natin,<br/>Ayon sa Diyos, plano''y tupdin.]<br/>',NULL,41078,3);
INSERT INTO stanza VALUES('T500','3','Kay taas, lalim, at haba!<br/>Luwang, sukat, di-malirip;<br/>Kristo ng Diyos, walang takda,<br/>Lawak lampas sa maisip.<br/>Siya Mismo at Kanyang taglay,<br/>Ekklesia ang pinatibay.<br/>[Siya Mismo at Kanyang taglay,<br/>Ekklesia ang pinatibay.]<br/><!--(Ulitin ang huling dalawang linya ng bawat saknong)--><br/>',NULL,41079,4);
INSERT INTO stanza VALUES('T501','1','O maluwalhating Kristo,<br/>Tunay Kang liwanag dibino,<br/>Ika''y Diyos sa kawalang-hanggan,<br/>Naging taong may hangganan.<br/>',NULL,41080,1);
INSERT INTO stanza VALUES('T501','chorus','O! Kristo, kahayagan ng Diyos,<br/>Kayamanang di maubos;<br/>Diyos sa tao''y naihalo,<br/>Nang maging ang lahat ko.<br/>',NULL,41081,2);
INSERT INTO stanza VALUES('T501','2','L''walhati inihayag Mo,<br/>Kapuspusan ng Diyos nasa Iyo;<br/>Sa laman, pagtubos gawa Mo,<br/>Sa ''Spiritu kaisa ko.<br/>',NULL,41082,3);
INSERT INTO stanza VALUES('T501','3','Lahat ng sa Ama''y I-yo,<br/>Tinanggap naman ng ''Spiritu;<br/>Sa ''kin Siya ang katotohanan,<br/>Nang Kita''y mararanasan.<br/>',NULL,41083,5);
INSERT INTO stanza VALUES('T501','4','Sa akin Ka ibinigay<br/>Ng Iyong Espiritu ng buhay,<br/>Salita''y aking natamo,<br/>Sa ''kin ''tinakda buhay Mo.<br/>',NULL,41084,7);
INSERT INTO stanza VALUES('T501','5','Habang Kita''y minamasdan,<br/>Pagbabago''y aking nakamtan;<br/>Gaya''y salaming nag-''aninag,<br/>L''walhati Mo''y naihayag.<br/>',NULL,41085,9);
INSERT INTO stanza VALUES('T501','6','Walang ibang daang sakdal<br/>Upang ako ay mapabanal;<br/>Makibahagi sa tagumpay,<br/>Kundi mahipo Kang tunay.<br/>',NULL,41086,11);
INSERT INTO stanza VALUES('T501','7','Espiritu Mo''y puspusan,<br/>Ang aking buong katauhan;<br/>Nang maligtas sa lumang tao,<br/>Tahanan Mo''y maitayo.<br/>',NULL,41087,13);
INSERT INTO stanza VALUES('T503','1','Buháy na Panginoon pinaglilingkuran;<br/>Anuman ang sabihin ng sangkatauhan;<br/>Tanaw ang Kanyang kamay, dinig ang tinig Niya;<br/>At kapag nangailangan, malapit Siya.<br/>',NULL,41088,1);
INSERT INTO stanza VALUES('T503','chorus','Kristo''y buháy, si Hesus nabubuhay!<br/>Kasama ko, kausap ko sa landas ng buhay.<br/>Siya ay buháy, dala''y kaligtasan!<br/>Tanong mo''y, "Bakit ko alam?"<br/>Puso ko''y tahanan.<br/>',NULL,41089,2);
INSERT INTO stanza VALUES('T503','2','Sa buong sanlibutan, hayag pag-ibig Niya;<br/>At kahit napapagod, Siya''y aking pag-asa;<br/>Ako''y ginagabayan sa mabagyong mundo;<br/>Araw ng paghahayag ang hintay ko.<br/>',NULL,41090,3);
INSERT INTO stanza VALUES('T503','3','Mangagalak Kristiyano, itaas tinig mo,<br/>Umawit aleluya, sa Haring si Kristo;<br/>Bawat pangangailangan, pag-asa''t tulong Siya;<br/>Wala nang hihigit pa sa buti Niya.<br/>',NULL,41091,5);
INSERT INTO stanza VALUES('T507','1','Malayo sa Diyos, may sala;<br/>Ilaw di makita;<br/>Sa Salita Siya''y nakita,<br/>Sa ''ki''y nanahan Siya.<br/>',NULL,41092,1);
INSERT INTO stanza VALUES('T507','chorus','Nasa loob ko,<br/>Buhay si Kristo;<br/>O! anong kaligtasan,<br/>Sa ''kin Siya''y nanahan.<br/>',NULL,41093,2);
INSERT INTO stanza VALUES('T507','2','Gaya''y silahis ng araw,<br/>Nagpapabulaklak;<br/>Buhay, ilaw at pagsinta,<br/>Kay Kristo nagmula.<br/>',NULL,41094,3);
INSERT INTO stanza VALUES('T507','3','Katulad ng isang puno,<br/>Na nasa ''sang buto;<br/>Gayon Kanyang Espiritu,<br/>Nasa ''spiritu ko.<br/>',NULL,41095,5);
INSERT INTO stanza VALUES('T507','4','Umaasam ang puso ko,<br/>Na makatulad Mo;<br/>At Iyong hiwaga''y munihin,<br/>Ika''y nasa akin.<br/>',NULL,41096,7);
INSERT INTO stanza VALUES('T509','1','Ilog at puno sa Eden,<br/>Bagay na kapansin-pansin,<br/>Tao''y bigyan ng inumin,<br/>Saganang pagkain.<br/>',NULL,41097,1);
INSERT INTO stanza VALUES('T509','chorus','Diyos sa Kristo''y aking pagkain,<br/>Kristo''y Espiritung nagtustos;<br/>Kung lagi kong tatamasahin,<br/>Makamtan kong lubos.<br/>',NULL,41098,2);
INSERT INTO stanza VALUES('T509','2','Puno ng buhay si Kristo<br/>Bilang pagkain ng tao,<br/>Yaman ng Diyos matamasa,<br/>Masiyahan nga siya.<br/>',NULL,41099,3);
INSERT INTO stanza VALUES('T509','3','Espiritu ang siyang ilog,<br/>Tao sa Diyos ay mabusog,<br/>Sa tustos na espirituwal,<br/>Tao''y maging banal.<br/>',NULL,41100,5);
INSERT INTO stanza VALUES('T509','4','Si Kristo ang aking buhay,<br/>Espiritu sa ''kin tunay,<br/>Diyos sa aki''y nakihalo,<br/>Mal''walhating anyo.<br/>',NULL,41101,7);
INSERT INTO stanza VALUES('T509','5','Parangalan ko si Kristo,<br/>Sundin ko ang Espiritu,<br/>Luwalhatiin ko ang Diyos,<br/>Sa biyayang lubos.<br/>',NULL,41102,9);
INSERT INTO stanza VALUES('T510','1','Walang kauring halaga,<br/>Aking nasumpungan;<br/>Aawitin kong masaya,<br/>Si Kristo''y nakamtan.<br/>',NULL,41103,1);
INSERT INTO stanza VALUES('T510','2','Si Kristo''y Kordero ng Diyos,<br/>Kaligtasan taglay,<br/>Siya ang Araw ng Katuwiran,<br/>Lunas ibibigay.<br/>',NULL,41104,2);
INSERT INTO stanza VALUES('T510','3','Si Kristo, Puno ng Buhay,<br/>Ang bunga''y sagana;<br/>Binusog Niya kagutuman,<br/>Siya ang aking pista.<br/>',NULL,41105,3);
INSERT INTO stanza VALUES('T510','4','Si Kristo''ng Batong pinalo,<br/>Tubig ay lumabas;<br/>Siya''y bukal sa aking puso,<br/>Uhaw ko''y nilutas.<br/>',NULL,41106,4);
INSERT INTO stanza VALUES('T510','5','Kristong ilaw, buhay, daan,<br/>Aliw, kalusugan,<br/>Galak, pag-asa''t pahinga,<br/>Yaman ko at gloria.<br/>',NULL,41107,5);
INSERT INTO stanza VALUES('T510','6','Siya ang lakas at karunungan,<br/>Katubusan, husay,<br/>Katotohanan, kabanalan,<br/>Kat''wiran, tagumpay.<br/>',NULL,41108,6);
INSERT INTO stanza VALUES('T510','7','Siya''y Panginoon, Diyos, Ama,<br/>Manliligtas, Pastol,<br/>Tagapayo at Manananggol,<br/>Kaibigan, at Sinta.<br/>',NULL,41109,7);
INSERT INTO stanza VALUES('T510','8','Kristo ang Pinuno''t Bantay,<br/>Ang Guro at Ulo,<br/>Kasintahan, Poon, Gabay,<br/>Nasa aking puso.<br/>',NULL,41110,8);
INSERT INTO stanza VALUES('T510','9','Siya''y Propetang mapahayag.<br/>Haring namumuno;<br/>Saserdoteng sa pagitan<br/>Ng Diyos at ng tao.<br/>',NULL,41111,9);
INSERT INTO stanza VALUES('T510','10','Siya''ng Saksing tapat, totoo,<br/>Gumawa''t sumakdal<br/>Pananampalataya ko,<br/>Garantiyang banal.<br/>',NULL,41112,10);
INSERT INTO stanza VALUES('T510','11','Siya''ng tahanang walang hanggan,<br/>Kuta at kublihan,<br/>Moog, lupang kasapatan,<br/>Tiyak kong tuntungan.<br/>',NULL,41113,11);
INSERT INTO stanza VALUES('T510','12','Siya''ng sabbath at bagong buwan,<br/>Aking araw''t gabi,<br/>Panahon ko''t walang hanggan,<br/>Siyang namamalagi.<br/>',NULL,41114,12);
INSERT INTO stanza VALUES('T510','13','Siya''ng panustos sa kailangan<br/>At aking tiwala,<br/>Kasiyahan, kaluguran,<br/>Kahanga-hanga Siya.<br/>',NULL,41115,13);
INSERT INTO stanza VALUES('T510','14','Siya''ng sumasakop sa lahat,<br/>Kristo ko — ano pa?<br/>Siya ang simula, Siya''ng wakas,<br/>Lahat sa lahat Siya.<br/>',NULL,41116,14);
INSERT INTO stanza VALUES('T510','15','Kaya''t puso ko''y aawit,<br/>Pagka''t aking angkin<br/>Kristo''y yamang di-malirip,<br/>Si Kristo ay akin.<br/>',NULL,41117,15);
INSERT INTO stanza VALUES('T511','1','Tanging Hesus, ating paksa,<br/>Siya''ng tanging mensahe rin;<br/>Tanging Hesus itaas nga,<br/>Siya''ng pagmasdan at sundin.<br/>',NULL,41118,1);
INSERT INTO stanza VALUES('T511','chorus','Tanging Hesus, laging Hesus,<br/>L''walhatiin si Hesus,<br/>Manggagamot at Manunubos,<br/>Buhay natin, Hari, Diyos.<br/>',NULL,41119,2);
INSERT INTO stanza VALUES('T511','2','Tanging Hesus, Manunubos,<br/>Pinasan ang sala ko;<br/>Siya ay ang ating kat''wiran,<br/>Lagi kong kalakasan.<br/>',NULL,41120,3);
INSERT INTO stanza VALUES('T511','3','Tanging Hesus, Nagpabanal,<br/>Sala''t sarili''y talo;<br/>Ang Espiritu Mong mahal,<br/>Nagpuspos sa puso ko.<br/>',NULL,41121,5);
INSERT INTO stanza VALUES('T511','4','Tanging Hesus, Manggagamot,<br/>Sakit ko ay pinaram;<br/>Buhay, kapuspusa''y dulot<br/>Sa sangkap ng Katawan.<br/>',NULL,41122,7);
INSERT INTO stanza VALUES('T511','5','Tanging Hesus, Kalakasan,<br/>Pentecostes ''binigay;<br/>Espiritu, kami''y hipan,<br/>Lakas aming mataglay.<br/>',NULL,41123,9);
INSERT INTO stanza VALUES('T511','6','Hesus, hinihintay natin,<br/>Pagdating Niya''y makita;<br/>Hesus hanggang sa wakas din,<br/>Tanging Hesus, lahat Siya.<br/>',NULL,41124,11);
INSERT INTO stanza VALUES('T513','1','Dati''y pagpapala,<br/>Si Kristo ngayon;<br/>Damdamin no''ng una,<br/>Salita ngayon;<br/>Paggamot ninais,<br/>Ngayo''y Siya Mismo;<br/>Ang nais bigyan Niya,<br/>Ngayon ay Siya na.<br/>',NULL,41125,1);
INSERT INTO stanza VALUES('T513','chorus','Purihin si Kristo—<br/>Ang lahat-lahat;<br/>Na kay Kristo ang lahat,<br/>At si Kristo''y lahat.<br/>',NULL,41126,2);
INSERT INTO stanza VALUES('T513','2','Dati''y pagsisikap,<br/>Ngayo''y tiwala;<br/>Dati''y sala''t hirap,<br/>Ngayo''y ligtas na;<br/>Dati''y tumatangan,<br/>Tinangnan ngayon;<br/>Dati''y lumulutang,<br/>Matatag ngayon.<br/>',NULL,41127,3);
INSERT INTO stanza VALUES('T513','chorus','Purihin si Kristo—<br/>Ang lahat-lahat;<br/>Na kay Kristo ang lahat,<br/>At si Kristo''y lahat.<br/>',NULL,41128,4);
INSERT INTO stanza VALUES('T513','3','Dati''y panukala,<br/>Dalangin ngayon;<br/>Dati ay balisa,<br/>Panatag ngayon;<br/>Dati''y ang hilig ko,<br/>Wika Niya ngayon;<br/>Dati ay pagsamo,<br/>Pagpuri ngayon.<br/>',NULL,41129,5);
INSERT INTO stanza VALUES('T513','chorus','Purihin si Kristo—<br/>Ang lahat-lahat;<br/>Na kay Kristo ang lahat,<br/>At si Kristo''y lahat.<br/>',NULL,41130,6);
INSERT INTO stanza VALUES('T513','4','Dati''y aking gawa,<br/>Ngayo''y gawa Niya;<br/>Dati''y gamit ko Siya,<br/>Ngayo''y gamit Niya;<br/>Lakas hanap noon,<br/>Siya''ng lakas ngayon;<br/>Nagpagal sarili,<br/>Kay Hesus ngayon.<br/>',NULL,41131,7);
INSERT INTO stanza VALUES('T513','chorus','Purihin si Kristo—<br/>Ang lahat-lahat;<br/>Na kay Kristo ang lahat,<br/>At si Kristo''y lahat.<br/>',NULL,41132,8);
INSERT INTO stanza VALUES('T513','5','Kay Hesus umasa,<br/>T''yak akin na Siya;<br/>Ilaw na nagbawa<br/>Ay maningning na;<br/>Hintay pagdating Niya,<br/>''Di ang mamatay;<br/>Matatag pag-asa,<br/>Ako''y ligtas na.<br/>',NULL,41133,9);
INSERT INTO stanza VALUES('T513','chorus','Purihin si Kristo—<br/>Ang lahat-lahat;<br/>Na kay Kristo ang lahat,<br/>At si Kristo''y lahat.<br/>',NULL,41134,10);
INSERT INTO stanza VALUES('T517','1','Hesus, para sa ''kin, Ika''y lahat,<br/>Tagapagligtas walang katulad;<br/>Sa dagat ng buhay, Giyang tapat,<br/>Para sa akin ay si Hesus.<br/>',NULL,41135,1);
INSERT INTO stanza VALUES('T517','chorus','Hesus, Hesus,<br/>Para sa ''kin,<br/>Kailanman, saanman<br/>Hesus sa ''kin.<br/>',NULL,41136,2);
INSERT INTO stanza VALUES('T517','2','Sa karamdaman, sa kalusugan,<br/>Sa karukhaan, aliw o yaman;<br/>Araw o ulan, maging anuman,<br/>Para sa akin ay si Hesus.<br/>',NULL,41137,3);
INSERT INTO stanza VALUES('T517','3','Aking Bato, Tore at Kublihan,<br/>Lakas, Bukal at Kapangyarihan;<br/>Sanggalang, Buhay na walang hanggan,<br/>Para sa akin ay si Hesus.<br/>',NULL,41138,5);
INSERT INTO stanza VALUES('T517','4','Hari, Saserdote at Propeta,<br/>Sungay ng Kaligtasan at Kuta;<br/>Araw ng Katuwiran at Tala,<br/>Para sa akin ay si Hesus.<br/>',NULL,41139,7);
INSERT INTO stanza VALUES('T517','5','Sa sakit, lungkot o sa ligaya,<br/>Aking Yaman sa lugi o gana;<br/>Saan man ako, Siya ay kasama,<br/>Para sa akin ay si Hesus.<br/>',NULL,41140,9);
INSERT INTO stanza VALUES('T518','1','Sinong liyág ko sa langit?<br/>Ikaw lang! Ikaw lang!<br/>Buong buhay itong awit:<br/>Kristo para sa ''kin!<br/>Para sa ''kin Siya''y Kordero,<br/>Mahal Niyang dugo binubo;<br/>Ako''t Diyos ''pinagkasundo:<br/>Kristo para sa ''kin!<br/>',NULL,41141,1);
INSERT INTO stanza VALUES('T518','2','Di nainggit sa mayaman:<br/>Kristo para sa ''kin!<br/>Walang nasà sa laruan:<br/>Kristo para sa ''kin!<br/>Panlupa di tatagal nga,<br/>Naglalaho, nawawala;<br/>Aking walang hanggang saya:<br/>Kristo para sa ''kin!<br/>',NULL,41142,2);
INSERT INTO stanza VALUES('T518','3','Kahit sa dukha mapunta,<br/>Kristo para sa ''kin!<br/>Mabuti sa ''kin, batid Niya<br/>Kristo para sa ''kin!<br/>Ubas, igos walang bunga,<br/>Langis oliba nawala,<br/>Namatay alagang tupa,<br/>Akin din, Kristo nga!<br/>',NULL,41143,3);
INSERT INTO stanza VALUES('T518','4','Palibot walang payapa,<br/>Kristo para sa ''kin!<br/>Sala ako''y tinuligsa,<br/>Kristo para sa ''kin!<br/>Mabangis man ang digmaan,<br/>Nanuligsa ang kalaban,<br/>Nguni''t Kanya''y kalakasan:<br/>Kristo ko sandigan.<br/>',NULL,41144,4);
INSERT INTO stanza VALUES('T518','5','Sa kaganapan ng buhay,<br/>Kristo para sa ''kin!<br/>Sa bisig Niya''y hihingalay,<br/>Kristo para sa ''kin!<br/>Sa masidhing kalungkutan,<br/>Sa lilim ng kamatayan,<br/>Akin pa ring aawitin,<br/>Kristo para sa ''kin!<br/>',NULL,41145,5);
INSERT INTO stanza VALUES('T522','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41146,1);
INSERT INTO stanza VALUES('T522','1','Noon puso ko''y malungkot,<br/>Dilim nagpalibot;<br/>Ngayon Kristo''y nagpasaya,<br/>Puso ko natuwa!<br/>',NULL,41147,2);
INSERT INTO stanza VALUES('T522','chorus','Kristo ngayon nagpasaya,<br/>Wala nang iba pa;<br/>Pag-ibig, galak at buhay;<br/>Kristo ang nagbigay.<br/>',NULL,41148,3);
INSERT INTO stanza VALUES('T522','2','Natikman panlupang lasa,<br/>Uhaw di mawala;<br/>Maging akin man ang mundo,<br/>Walang s''ya puso ko.<br/>',NULL,41149,4);
INSERT INTO stanza VALUES('T522','3','Pagpapala nga nais ko,<br/>Di hangad si Kristo;<br/>Kahit tinanggihan ko Siya,<br/>Ako''y hinanap Niya.<br/>',NULL,41150,6);
INSERT INTO stanza VALUES('T522','4','Tubig sa sisidlang basag,<br/>Inuma''t mabagbag,<br/>''Pagkat tumagas, nawala,<br/>Uhaw ko''y kinutya.<br/>',NULL,41151,8);
INSERT INTO stanza VALUES('T522','5','Pagpapala ay nawala,<br/>Ni di naisip Ka;<br/>Nang buksan Mo aking mata,<br/>''Batid Iyong pagsinta.<br/>',NULL,41152,10);
INSERT INTO stanza VALUES('T526','1','Poon sa ''kin ginawa Mo,<br/>Sarili Mo na totoo;<br/>Realidad pananalig,<br/>Sa sangkalupaa''y higit;<br/>Kay tamis, kaibig-ibig,<br/>Ikaw pinakamatalik.<br/>',NULL,41153,1);
INSERT INTO stanza VALUES('T526','2','Pangitaing pinagpala,<br/>Sa aki''y Iyong ''pinakita;<br/>Binuo Mong muli ako,<br/>Dinalisay layunin ko;<br/>Pinataas aking uri,<br/>Mapuspusan ng l''walhati.<br/>',NULL,41154,2);
INSERT INTO stanza VALUES('T526','3','Buháy na Tagapagligtas,<br/>Higit Kang kaibig-ibig;<br/>May l''walhati sa Iyong mukha,<br/>Salita Mo''y mabiyaya;<br/>Ako''y lubos matransporma,<br/>May dagdag na b''yaya''t awa.<br/>',NULL,41155,3);
INSERT INTO stanza VALUES('T529','1','Nang di makitang ganda Niya,<br/>Buhay bagôt, walang lasa;<br/>Magandang ibon, bulaklak,<br/>Pawang naglaho ang rilag.<br/>Di maliwanag ang araw,<br/>Mga bukirin mapanglaw;<br/>Nang sa Kanya''y kay galak ko,<br/>Disyembre ay tila Mayo.<br/>',NULL,41156,1);
INSERT INTO stanza VALUES('T529','2','Ngalang pinakamasamyo,<br/>Tinig pinakamatamis;<br/>Presensya Niya''y kaaliwan,<br/>Nagbigay ng kaluguran.<br/>Kung ganito Siyang katalik,<br/>Walang ibang gusto''t hilig;<br/>Walang singgalak kong tao,<br/>Buong taon tag-init ko.<br/>',NULL,41157,2);
INSERT INTO stanza VALUES('T529','3','Mapagmasdan lang mukha Niya,<br/>Tamis aking nadarama;<br/>Anuman ang pangyayari,<br/>Layon ko''y mananatili.<br/>Madama lang pag-ibig Niya,<br/>Palasyo ay laruan na;<br/>Piitan naging palasyo,<br/>Basta''t kasama si Kristo.<br/>',NULL,41158,3);
INSERT INTO stanza VALUES('T529','4','Panginoon kung ako''y Iyo,<br/>Kung Ika''y awit, araw ko,<br/>Bakit lupaypay, mahina?<br/>Bakit taglamig mahaba?<br/>Alisin ulap madilim,<br/>I-yong presensya''y bawiin;<br/>O kunin akong pataas,<br/>Wala nang taglamig, ulap.<br/>',NULL,41159,4);
INSERT INTO stanza VALUES('T530','1','Si Kristo ang aking lahat,<br/>Buhay at taguyod.<br/>Aking lakas; kung wala Siya<br/>Ako''y matitisod.<br/>Kung may lumbay, Siya''y lapitan,<br/>Si Hesus ang kagalakan.<br/>Aliw ko sa kalooban;<br/>Kaibigan.<br/>',NULL,41160,1);
INSERT INTO stanza VALUES('T530','2','Si Kristo ang aking lahat,<br/>Tulong sa pagsubok,<br/>Sa akin ay nagpapala,<br/>Laging kumukupkop.<br/>Ulan, araw padala Niya,<br/>Ani, tustos masagana,<br/>Araw, ulan, gintong butil—<br/>Kaibigan.<br/>',NULL,41161,2);
INSERT INTO stanza VALUES('T530','3','Si Kristo ang aking lahat,<br/>Tagapagbiyaya;<br/>Sa Kanya ''ko''y maging tapat,<br/>Di ko Siya matatwa.<br/>Sundin ko Siya, panay wasto,<br/>Binantayan akong husto,<br/>Araw-gabi, sundin ko Siya,<br/>Kaibigan.<br/>',NULL,41162,3);
INSERT INTO stanza VALUES('T530','4','Si Kristo ang aking lahat,<br/>Wala Siyang kapantay,<br/>Nais ko Siyang makaugnay,<br/>''Di na mawawalay.<br/>Kay inam ng aking buhay,<br/>Kaibigang napakahusay,<br/>Walang hanggan kong kaakbay,<br/>Kaibigan.<br/>',NULL,41163,4);
INSERT INTO stanza VALUES('T531','1','Lipas lupang saya;<br/>Hesus sa ''kin.<br/>Ugnaya''y patid na;<br/>Hesus sa ''kin.<br/>Ilang madilim nga,<br/>Pahingaha''y wala,<br/>Hesus lang magpala;<br/>Hesus sa ''kin.<br/>',NULL,41164,1);
INSERT INTO stanza VALUES('T531','2','Ilayo sa tukso;<br/>Hesus sa ''kin.<br/>Manatili rito;<br/>Hesus sa ''kin.<br/>Bagay nasisira,<br/>At pansamantala,<br/>Hindi padadala;<br/>Hesus sa ''kin.<br/>',NULL,41165,2);
INSERT INTO stanza VALUES('T531','3','Adiyós, hakang isip;<br/>Hesus sa ''kin.<br/>Sa ilaw napawi;<br/>Hesus sa ''kin.<br/>Lahat sinubukan,<br/>Walang kabuluhan,<br/>Siya ang kasiyahan;<br/>Hesus sa ''kin.<br/>',NULL,41166,3);
INSERT INTO stanza VALUES('T531','4','Adiyós, kamatayan;<br/>Hesus sa ''kin.<br/>Tuloy, walang hanggan;<br/>Hesus sa ''kin.<br/>Tuloy Ka, O Sinta,<br/>Tuloy Ka, pahinga,<br/>Tuloy Ka, dibdib Niya;<br/>Hesus sa ''kin.<br/>',NULL,41167,4);
INSERT INTO stanza VALUES('T532','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41168,1);
INSERT INTO stanza VALUES('T532','1','Lihim bukal ng payapa,<br/>Sapat, dibinong pagsinta;<br/>Aking tulong at pag-asa,<br/>Ligtas ako, kung akin Ka;<br/>Mula sa sala''t pighati,<br/>Sa Iyo ako nagkukubli.<br/>',NULL,41169,2);
INSERT INTO stanza VALUES('T532','2','Ikaw lahat kong kailangan,<br/>Sa pagod, kapahingahan;<br/>Lunas sa sugat ng puso,<br/>Kapayapaan, natamo;<br/>Ngiti ko sa mapandusta,<br/>Putong sa pagkapahiya.<br/>',NULL,41170,3);
INSERT INTO stanza VALUES('T532','3','Panustos sa kakulangan,<br/>Sa gapos ko''y kalayaan;<br/>Sa hina ay kalakasan,<br/>Sa dilim kaliwanagan;<br/>Sa lungkot kaligayahan,<br/>Buhay ko sa kamatayan.<br/>',NULL,41171,4);
INSERT INTO stanza VALUES('T532','4','Lihim bukal ng payapa,<br/>Sapat dibinong pagsinta;<br/>Sa Iyo ako''y nakakubli,<br/>Tamasa ang Iyong Sarili;<br/>Ikaw ay lahat-lahat ko,<br/>Tamasa''y hindi mahinto.<br/>',NULL,41172,5);
INSERT INTO stanza VALUES('T533','1','Malalim man kasalanan,<br/>Matarík ang daraanan,<br/>Anuman ang kapaguran,<br/>Panginoon, sapat.<br/>',NULL,41173,1);
INSERT INTO stanza VALUES('T533','2','Pagsubok munti''t malaki,<br/>Pasan kaunti''t marami,<br/>Paang natisod, nabali,<br/>Panginoon, sapat.<br/>',NULL,41174,2);
INSERT INTO stanza VALUES('T533','3','Lupang bagay kay saya man,<br/>Langit naman nakublihan,<br/>Ng ginhawa''t kagalakan,<br/>Panginoon, sapat.<br/>',NULL,41175,3);
INSERT INTO stanza VALUES('T533','4','Buong araw kapanglawan,<br/>Kabigua''y humahadlang,<br/>Puso''y umid manalangin,<br/>Panginoon, sapat.<br/>',NULL,41176,4);
INSERT INTO stanza VALUES('T533','5','Anumang kalagayan ko,<br/>Nawa''y makita kamay Mo,<br/>Ikaw sa karanasan ko,<br/>Panginoon sapat.<br/>',NULL,41177,5);
INSERT INTO stanza VALUES('T534','1','Manliligtas kayang bumuhat,<br/>Pasan, magaa''t mabigat;<br/>Lakas napasakdal sa hina,<br/>Kalakasa''y nasa Kanya.<br/>',NULL,41178,1);
INSERT INTO stanza VALUES('T534','chorus','Manliligtas kayang lutasin,<br/>Ang lahat ng suliranin;<br/>Kay Hesus walang mahirap din,<br/>Walang hindi Niya kayang gawin.<br/>',NULL,41179,2);
INSERT INTO stanza VALUES('T534','2','Manliligtas kayang pasanin,<br/>Bawa''t lumbay may aliw rin;<br/>Malaki man pighating dulot,<br/>Kay inam pag Kanyang tulot.<br/>',NULL,41180,3);
INSERT INTO stanza VALUES('T534','3','Manliligtas pinatibay nga,<br/>Nanlulumo''t mahihina;<br/>Biyaya Niya''y sapat sa tanan,<br/>Batid Niya ang bawa''t hakbang.<br/>',NULL,41181,5);
INSERT INTO stanza VALUES('T534','4','Manliligtas kayang wasakin,<br/>P''wersa ng sala daigin;<br/>Sa Kanya ay may kalayaan,<br/>Kayang gupuin kalaban.<br/>',NULL,41182,7);
INSERT INTO stanza VALUES('T534','5','Manliligtas nagbigay lubos,<br/>Kasiyahang di matalos,<br/>Pinapabanal ng ''Spiritu,<br/>Ang nagpasakop kay Kristo.<br/>',NULL,41183,9);
INSERT INTO stanza VALUES('T535','1','Lahat posible sa Kanya,<br/>Manalig lang sa ngalan Niya;<br/>Ngala''y h''wag lapastanganin,<br/>Katotohana''y tanggapin.<br/>Sa Iyo sumampalataya,<br/>Sa ''kin lahat posible na.<br/>',NULL,41184,1);
INSERT INTO stanza VALUES('T535','2','Ang pinakaimposible,<br/>Matapos salang naghari;<br/>Nguni''t totoong nangyari,<br/>Kay Hesus, di sa sarili,<br/>Ilagak aking tiwala,<br/>Sa ''kin lahat posible na.<br/>',NULL,41185,2);
INSERT INTO stanza VALUES('T535','3','Tutulan man ang Salita,<br/>Di-kailanman mawawala;<br/>Panginoon dudurog nga,<br/>Sa imposible ngang sala.<br/>Bagay na imposible nga,<br/>Sa ''kin lahat posible na.<br/>',NULL,41186,3);
INSERT INTO stanza VALUES('T535','4','Lahat nga''y posible sa Diyos,<br/>Sa kapangyarihan ng Diyos;<br/>Kristong nagpabago sa ''kin,<br/>Sa Kanya ako''y hubugin.<br/>Napalaya na sa sala,<br/>Sa ''kin lahat posible na.<br/>',NULL,41187,4);
INSERT INTO stanza VALUES('T535','5','Lahat nga''y posible sa Diyos,<br/>Kay Kristo, ang lakas ng Diyos;<br/>Palaganapan Mo ako,<br/>Nang ipamuhay si Kristo.<br/>Tamis ng kakayahan Mo,<br/>Lubos na maranasan ko.<br/>',NULL,41188,5);
INSERT INTO stanza VALUES('T536','1','Kristo''y obhektibo at subhektibo,<br/>Sa langit obhektibong nagsumamo;<br/>Nanahang subhektibo sa sangkap Niya,<br/>Panloob, binibigay sarili Niya.<br/>',NULL,41189,1);
INSERT INTO stanza VALUES('T536','2','Sa langit sa kanan ng Diyos, naupo,<br/>Saserdoteng Mataas dala''y dugo;<br/>Tagapamagitan sa kalangitan,<br/>Tagapanagot, kami''y iningatan.<br/>',NULL,41190,2);
INSERT INTO stanza VALUES('T536','3','Espiritung nasa ''ming espiritu,<br/>Bilang aming buhay lahat dala Niya;<br/>Bawa''t oras Siya''y lakas at biyaya,<br/>Tagaaliw, at tustos ng lakas Siya.<br/>',NULL,41191,3);
INSERT INTO stanza VALUES('T536','4','Para sa ''tin nal''walhating Tao Siya,<br/>Sa langit pumasok, Tagapanguna;<br/>Balak ng Diyos, ''sinakatuparan Niya,<br/>Tao''y dinala sa Diyos nang magkai-sa.<br/>',NULL,41192,4);
INSERT INTO stanza VALUES('T536','5','Nanahan ang kapuspusan sa Kanya,<br/>Ang Espiritu sa ''tin, Diyos dinala;<br/>''Pinahayag sa ''tin Diyos ay totoo,<br/>Tayo''t Diyos hinalo sa pagtatayo.<br/>',NULL,41193,5);
INSERT INTO stanza VALUES('T536','6','Obhektibong Kristo ngayon sa langit,<br/>Di-maglalaon sadya Siyang babalik;<br/>Subhektibong Kristo nanahan sa ''tin,<br/>Di-maglaon anyo ko''y babaguhin.<br/>',NULL,41194,6);
INSERT INTO stanza VALUES('T536','7','Darating lupa''t langit magkasama,<br/>Sa lunsod banal Diyos, tao nagkai-sa;<br/>Ang obhektibo at ang subhektibo,<br/>Walang hanggang naihalo''t kumpleto.<br/>',NULL,41195,7);
INSERT INTO stanza VALUES('T537','1','Si Kristo ay subhektibo,<br/>Buhay sa espiritu;<br/>Si Kristo ang lahat-lahat,<br/>Espiritu kaisa.<br/>',NULL,41196,1);
INSERT INTO stanza VALUES('T537','chorus','Si Kristo''y subhektibo, kay yaman<br/>Sa aking karanasan!<br/>Lahat-lahat sa aking kailangan,<br/>Katamisan Niya''y tikman.<br/>',NULL,41197,2);
INSERT INTO stanza VALUES('T537','2','Si Kristo ay subhektibo,<br/>Buhay Niya''y natatamo;<br/>Ako ay pinasisigla<br/>At pinapanariwa.<br/>',NULL,41198,3);
INSERT INTO stanza VALUES('T537','3','Si Kristo ay subhektibo,<br/>Kalul''wa binabago;<br/>At kalooban ko''t isip<br/>Nang sa Kanya''y mahawig.<br/>',NULL,41199,5);
INSERT INTO stanza VALUES('T537','4','Si Kristo ay subhektibo,<br/>Nagpapalaya mismo;<br/>Ang kautusan ng buhay,<br/>Espiritu na tunay.<br/>',NULL,41200,7);
INSERT INTO stanza VALUES('T537','5','Si Kristo ay subhektibo,<br/>Sinaayos Niya ako;<br/>Ginabayan, iwinasto,<br/>Itinuwid pa ako.<br/>',NULL,41201,9);
INSERT INTO stanza VALUES('T537','6','Si Kristo ay subhektibo,<br/>Nagpawi ng uhaw ko;<br/>Aking tustos Kanyang yaman,<br/>Hayag Niyang kapuspusan.<br/>',NULL,41202,11);
INSERT INTO stanza VALUES('T538','1','Ang lugod at nais ng Diyos,<br/>Kristo''y ihayag sa ''kin;<br/>Di panlabas na relihiyon,<br/>Kristo''y ''paloob sa ''kin.<br/>',NULL,41203,1);
INSERT INTO stanza VALUES('T538','chorus','Ang lugod at nais ng Diyos,<br/>Kristo''y maisagawa;<br/>Sa aking loob nang lubos,<br/>Di panlabas na gawa.<br/>',NULL,41204,2);
INSERT INTO stanza VALUES('T538','2','Ang lugod at nais ng Diyos,<br/>Kristo''y mabuhay sa ''kin;<br/>Di panlabas na pagkilos,<br/>Ang gumawa''y Kristo rin.<br/>',NULL,41205,3);
INSERT INTO stanza VALUES('T538','3','Ang lugod at nais ng Diyos,<br/>Mahubog sa ''kin Kristo;<br/>Di ang panlabas na ritwal,<br/>Kundi Kristo''y lumago.<br/>',NULL,41206,5);
INSERT INTO stanza VALUES('T538','4','Ang lugod at nais ng Diyos,<br/>Kristo''y manahan sa ''kin;<br/>Di panlabas na maglingkod,<br/>Sa loob Siya''y taglayin.<br/>',NULL,41207,7);
INSERT INTO stanza VALUES('T538','5','Ang lugod at nais ng Diyos,<br/>Kristo ang pag-asa ko;<br/>Di l''walhating obhektibo,<br/>Kundi Siyang subhektibo.<br/>',NULL,41208,9);
INSERT INTO stanza VALUES('T538','6','Ang lugod at nais ng Diyos,<br/>Kristo''y maging lahat ko;<br/>Tanging angkinin nang lubos,<br/>Ang walang hanggang Kristo.<br/>',NULL,41209,11);
INSERT INTO stanza VALUES('T539','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,41210,1);
INSERT INTO stanza VALUES('T539','1','Panginoon, buhay Ka sa akin<br/>At lahat sa akin!<br/>Sa t''wina''y aking nararanasan,<br/>At subhektibo rin<br/>',NULL,41211,2);
INSERT INTO stanza VALUES('T539','chorus','Poon, mahal Ka sa akin,<br/>Espiritung tunay!<br/>Sa lahat ng aking kailangan,<br/>Tugon Ka sa buhay!<br/>',NULL,41212,3);
INSERT INTO stanza VALUES('T539','2','Maging malaki man o maliit<br/>Ang pangangailangan;<br/>Ikaw ang lagi kong nagagamit,<br/>Panustos kay yaman.<br/>',NULL,41213,4);
INSERT INTO stanza VALUES('T539','3','Ang Iyong matamis na pagpapahid<br/>Aking kalakasan;<br/>Ang Iyong panustos ng enerhiya,<br/>Ako''y iningatan.<br/>',NULL,41214,6);
INSERT INTO stanza VALUES('T539','4','Batas ng buhay sa puso''t isip<br/>Ako''y inaayos;<br/>Ang katotohanan Mong kay yaman,<br/>Ako''y pinupuspos.<br/>',NULL,41215,8);
INSERT INTO stanza VALUES('T539','5','Pagkakaisa natin ay lagi<br/>Di mapapantayan;<br/>Kaisang Espiritu sa t''wina,<br/>Magpakailanpaman.<br/>',NULL,41216,10);
INSERT INTO stanza VALUES('T540','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41217,1);
INSERT INTO stanza VALUES('T540','1','Kay Kristo ang kalayaan,<br/>Pinalaya na ako!<br/>Kasalana''t kamatayan,<br/>Lubos ang pagkatalo!<br/>',NULL,41218,2);
INSERT INTO stanza VALUES('T540','chorus','Higit pa sa magtagumpay,<br/>Sa krus magmamapuri,<br/>Ang kautusan ng buhay<br/>Nagpapalakas lagi!<br/>',NULL,41219,3);
INSERT INTO stanza VALUES('T540','2','Si Kristo ang nagpalaya<br/>Sa bawa''t kautusan;<br/>Buhay ayon sa biyaya,<br/>Ay walang kaapihan.<br/>',NULL,41220,4);
INSERT INTO stanza VALUES('T540','3','Kasalana''y nahatulan,<br/>Nalipol kanyang lakas;<br/>Wala na siyang katayuan,<br/>Gapos sa aki''y kalas.<br/>',NULL,41221,6);
INSERT INTO stanza VALUES('T540','4','Kamataya''y dinaig Niya,<br/>Buhay ipinahayag;<br/>Kamataya''y walang bisa,<br/>Pagkabuhay matatag.<br/>',NULL,41222,8);
INSERT INTO stanza VALUES('T540','5','Diyablo, kasamaan, mundo,<br/>Nilipol na ni Kristo;<br/>Kadiliman ay naglaho,<br/>Buhay, ilaw natanto.<br/>',NULL,41223,10);
INSERT INTO stanza VALUES('T540','6','Biyayang sapat ay kamtan,<br/>Kanyang kapangyarihan;<br/>Kay sakdal sa kahinaan,<br/>At ako''y nasisiyahan.<br/>',NULL,41224,12);
INSERT INTO stanza VALUES('T541','1','Di batas ng titik, kundi si Kristo<br/>Ipinagkaloob sa atin ng Diyos;<br/>Hindi ang doktrina, tanging Kristo nga<br/>Ang nagpapalaya sa ating sala.<br/>',NULL,41225,1);
INSERT INTO stanza VALUES('T541','2','Anumang uri ng porma at turo<br/>Di kayang buhayin ang espiritu;<br/>Ang buháy na Kristo nagbigay-buhay,<br/>Diyos at Kanyang mithi, maipamuhay.<br/>',NULL,41226,2);
INSERT INTO stanza VALUES('T541','3','Ni pilosopiya ni ang etika<br/>Makapaghugis ng mga sangkap Niya;<br/>Si Kristo sa pagkabuhay na muli<br/>Ang nagbuo ng Katawan Niyang tangi.<br/>',NULL,41227,3);
INSERT INTO stanza VALUES('T541','4','Hindi relihiyon ni Kristiyanismo,<br/>Mabibigyan ang Diyos ng Kanyang gusto;<br/>Kundi si Kristong sa aki''y nanahan,<br/>Nilugod ang Diyos, tinupad ang tipan.<br/>',NULL,41228,4);
INSERT INTO stanza VALUES('T541','5','Mga tungkulin at mga kaloob<br/>Di ma''aring humalili kay Kristo;<br/>Si Kristo ang tangi kong nilalaman,<br/>Si Kristo ang tangi ko ring kailangan.<br/>',NULL,41229,5);
INSERT INTO stanza VALUES('T542','1','Yaman ng Tagapagligtas,<br/>Di-malirip, malawak;<br/>Kapuspusan ng Pagka-Diyos,<br/>Maranasan nang payak.<br/>',NULL,41230,1);
INSERT INTO stanza VALUES('T542','chorus','Yaman ng Tagapagligtas,<br/>Sa akin nakalaan;<br/>Bagama''t hindi masukat,<br/>Aking katotohanan!<br/>',NULL,41231,2);
INSERT INTO stanza VALUES('T542','2','Yaman ng Tagapagligtas,<br/>Sa lahat sumasakop:<br/>Buhay, liwanag, at lakas,<br/>Dunong, aliw, at kupkop.<br/>',NULL,41232,3);
INSERT INTO stanza VALUES('T542','3','Katubusan, kaligtasan,<br/>At pagkabuhay-muli,<br/>Nagpapabanal sa tanan,<br/>At lumuluwalhati!<br/>',NULL,41233,5);
INSERT INTO stanza VALUES('T542','4','Yaman ng Tagapagligtas—<br/>Persona, pag-aari;<br/>Mismong Diyos ang aking lahat,<br/>Puso ko''y nabighani.<br/>',NULL,41234,7);
INSERT INTO stanza VALUES('T542','5','Yaman ng Tagapagligtas,<br/>Di masukat, gayunman,<br/>Luwang, haba, lalim, taas,<br/>Ay aking kagalakan.<br/>',NULL,41235,9);
INSERT INTO stanza VALUES('T542','6','Walang hanggang mga yaman,<br/>Nawa''y aking malaman;<br/>Kristo''y ganap maranasan,<br/>Ang iba''y bahaginan.<br/>',NULL,41236,11);
INSERT INTO stanza VALUES('T544','1','Mahal Kita, Hesus, Ikaw ay akin;<br/>Layaw ng sala''y itatakwil ko rin;<br/>Manunubos, Manliligtas sa akin,<br/>Kung mahal man Kita, Hesus, ngayon na!<br/>',NULL,41237,1);
INSERT INTO stanza VALUES('T544','2','Mahal Kita, una ''kong minahal Mo;<br/>Binayaran utang ko sa Kalbaryo;<br/>Tinik ang ipinutong sa ulo Mo,<br/>Kung mahal man Kita, Hesus, ngayon na!<br/>',NULL,41238,2);
INSERT INTO stanza VALUES('T544','3','Mahal Kita, hanggang sa kamatayan;<br/>Habang may hininga, ''Ka''y papurihan;<br/>Ito''y maging huli kong panambitan,<br/>Kung mahal man Kita, Hesus ngayon na!<br/>',NULL,41239,3);
INSERT INTO stanza VALUES('T544','4','Sa walang hanggang kaluwalhatian;<br/>Sasambahin Kita magpakailanman;<br/>May maningning na putong at awitan,<br/>Kung mahal man Kita, Hesus, ngayon na!<br/>',NULL,41240,4);
INSERT INTO stanza VALUES('T546','1','Mahal Kita di ng pag-ibig ko,<br/>''Pagkat wala ako;<br/>Mahal Kita, tanang pag-ibig Iyo<br/>Namumuhay sa Iyo.<br/>Bale-wala ako''t natutuwang<br/>Mabasyo, sa loob Mo''y mawala.<br/>',NULL,41241,1);
INSERT INTO stanza VALUES('T546','2','Panginoon, aming kailangan Ka,<br/>At wala nang iba;<br/>Ilog ng pagpala sa Iyo mula,<br/>Kami''y pinagpala;<br/>Bukal ng buhay, mayamang b''yaya<br/>Pinagmulan, sentro''t tirahan nga.<br/>',NULL,41242,2);
INSERT INTO stanza VALUES('T548','1','Ako''y lupang sisidlan,<br/>Taglay ang Kristong yaman;<br/>Sadya akong nilalang,<br/>Siya''ng maging nilalaman.<br/>',NULL,41243,1);
INSERT INTO stanza VALUES('T548','2','Ayon sa larawan Niya,<br/>Sisidlan ay ginawa;<br/>Kay Kristo itinugma<br/>Nang Siya''y makatahan nga.<br/>',NULL,41244,2);
INSERT INTO stanza VALUES('T548','3','Nananahan si Kristo,<br/>Sa aking espiritu;<br/>Kai-sang espiritu Niya,<br/>Sa ''kin realidad Siya.<br/>',NULL,41245,3);
INSERT INTO stanza VALUES('T548','4','Nakihalo sa akin,<br/>Nakisalamuha rin;<br/>Sa aki''y kumikilos,<br/>Sa Kanya ''ko''y nalipos.<br/>',NULL,41246,4);
INSERT INTO stanza VALUES('T548','5','Nawa''y maihayag Siya,<br/>Siya ang dinadakila;<br/>Ako''y lantad at litaw,<br/>Sa akin Siya''y matanaw.<br/>',NULL,41247,5);
INSERT INTO stanza VALUES('T548','6','Ako''y dapat mabago,<br/>Basagin lumang tao;<br/>Luad baguhing anyo,<br/>Sa yaman mapareho.<br/>',NULL,41248,6);
INSERT INTO stanza VALUES('T549','1','Sa loob ng tabing, pumasok ka<br/>At sa kampamento, lumabas ka;<br/>Kung sa Pinakabanal mas''yahan,<br/>Ang mundo''y kusa mong tatalikdan.<br/>',NULL,41249,1);
INSERT INTO stanza VALUES('T549','2','Sa loob ng tabing, pumasok ka,<br/>At sa kampamento, lumabas ka;<br/>Kung sumilay l''walhati sa puso,<br/>Paano pa mabihag ng mundo?<br/>',NULL,41250,2);
INSERT INTO stanza VALUES('T549','3','Ang maluwalhating Kristo''y masdan,<br/>Mapagpakumbabang Kristo''y sundan;<br/>Kung trono''t putong bumihag sa iyo,<br/>Sabsaban at krus haharapin mo.<br/>',NULL,41251,3);
INSERT INTO stanza VALUES('T549','4','Kapangyarihan ng buhay kamtin,<br/>Landas ng krus siya nating tahakin;<br/>Kung mukha Niya sa langit mamasdan,<br/>Bakas ni Kristo sa lupa''y sundan.<br/>',NULL,41252,4);
INSERT INTO stanza VALUES('T549','5','Sa taba ng langit magtamasa,<br/>Tiisin kahirapan sa lupa;<br/>Kahit pagsubok dulot ay dusa,<br/>May galak din dahil kasama Ka.<br/>',NULL,41253,5);
INSERT INTO stanza VALUES('T549','6','Tamasahin ang yaman ni Kristo,<br/>Tustusan ang kailangan ng tao;<br/>Kung buhay ng langit ma''hayag Mo,<br/>Pagpala''y mabahagi sa tao.<br/>',NULL,41254,6);
INSERT INTO stanza VALUES('T549','7','Sa loob ng tabing pumasok ka,<br/>Hanggang langit lupa''y magkaisa;<br/>Ika''y lumabas ng kampamento,<br/>Hanggang magkaisa Diyos at tao.<br/>',NULL,41255,7);
INSERT INTO stanza VALUES('T551','1','Naniniwala ako,<br/>Kay Hesus na Kordero,<br/>Dumaan sa looban,<br/>Diyos ay papurihan!<br/>Ako''y pinaging-banal,<br/>Sa Kanyang dugong mahal,<br/>Ligtas sa sala''t mundo,<br/>Purihin ang Kordero!<br/>',NULL,41256,1);
INSERT INTO stanza VALUES('T551','chorus','Aleluya! Aleluya!<br/>Sa tabing na nahati,<br/>Dumaang may l''walhati;<br/>Aleluya! Aleluya!<br/>Namumuhay sa harapan ng Hari.<br/>',NULL,41257,2);
INSERT INTO stanza VALUES('T551','2','Lampas sa unang tabing,<br/>Sa dakong banal datnin,<br/>Tustos ng Diyos natamo,<br/>Puri sa Kordero!<br/>Sa Diyos walang sagabal,<br/>Sa altar pinabanal,<br/>Itakwil ang pangmundo,<br/>Purihin ang Kordero.<br/>',NULL,41258,3);
INSERT INTO stanza VALUES('T551','3','Ikal''wang tabing buksan,<br/>Sa kabanal-banalan,<br/>Sa luklukan ng b''yaya,<br/>Puri, Aleluya!<br/>Ako''y sa Diyos mamuhay,<br/>Sa ''spiritwal na bahay,<br/>Di mag-iisang muli,<br/>Sa Kordero ang puri!<br/>',NULL,41259,5);
INSERT INTO stanza VALUES('T551','4','Saserdote nga ng Diyos,<br/>Pagka''t ako''y tinubos,<br/>Tiyak ang katayuan,<br/>Diyos ay papurihan!<br/>Ako''y nasa ''spiritu,<br/>L''walhati ay natamo,<br/>Araw at gabi rito,<br/>Purihin ang Kordero!<br/>',NULL,41260,7);
INSERT INTO stanza VALUES('T552','1','Nasa l''walhati na Kristo,<br/>Sinilayan puso ko;<br/>Di bituin makaaliw,<br/>Kundi sikat ng langit.<br/>Lupa''y madilim, pusikit,<br/>Puso ko''y di maakit,<br/>Liban sa dusang danas Niya,<br/>Aking minahalaga.<br/>',NULL,41261,1);
INSERT INTO stanza VALUES('T552','2','Sa iba''y ilaw panlupa,<br/>Ang kanilang pag-asa;<br/>Nakita''y ilaw sa langit,<br/>Sinag sa araw higit.<br/>Liwanag di-batid hina,<br/>Gloriang mukha''y makita,<br/>Ang pagsintang mahalaga,<br/>Mayaman Niyang biyaya.<br/>',NULL,41262,2);
INSERT INTO stanza VALUES('T552','3','Kahanga-hangang pagsinta,<br/>L''walhati Niya''y nakita;<br/>Natayuang mataas pa,<br/>Sa akin tinamo Niya.<br/>Tabing tinaas di-minsan,<br/>Sa loob mananahan,<br/>Sa mukha Niya''y nakatitig,<br/>Pakinggan Kanyang tinig.<br/>',NULL,41263,3);
INSERT INTO stanza VALUES('T552','4','Mukha ni Hesus nakita,<br/>H''wag bumanggit ng iba;<br/>Nang tinig Niya napakinggan,<br/>Kalul''wa''y nasiyahan.<br/>Sa ningning ng l''walhati Niya,<br/>Natanaw Kanyang mukha,<br/>Walang hanggang tahanan ko,<br/>Kal''walhatiang ito.<br/>',NULL,41264,4);
INSERT INTO stanza VALUES('T553','1','Sa lihim ng presensya Niya,<br/>Natamo ang pahinga;<br/>Natutuhan mahalaga,<br/>Sa harap Niya''y sumamba.<br/>Panlupang alalahanin,<br/>Di ako gugupuin;<br/>Sa dakong lihim tutungo,<br/>T''wing diyablo''y nanunukso.<br/>[T''wing diyablo''y nanunukso.]<br/>',NULL,41265,1);
INSERT INTO stanza VALUES('T553','2','Nang sa lilim ng pakpak Niya,<br/>Pagod, uhaw ''king dala;<br/>Tamo''y pahinga''t ginhawa,<br/>Tubig buhay sariwa.<br/>Tagapagligtas at ako,<br/>Salamuha''y kay bango;<br/>Di mabigkas ng salita,<br/>Bagaman natikman na.<br/>[Bagaman natikman na.]<br/>',NULL,41266,2);
INSERT INTO stanza VALUES('T553','3','Nguni''t akin lamang batid,<br/>Nang hapis ''pinahatid;<br/>Mat''yaga Niyang pakikinggan,<br/>At Kanyang uudyukan.<br/>Di Siya tunay na kai-bigan,<br/>Kung di Niya pagsabihan;<br/>Ako sa nagawang sala,<br/>Na Kanyang nakikita.<br/>[Na Kanyang nakikita.]<br/>',NULL,41267,3);
INSERT INTO stanza VALUES('T553','4','Dakong lihim anong tamis,<br/>Kung mabatid Iyong nais;<br/>Manirahan sa lilim Niya;<br/>Makamtan gantimpala;<br/>Sa masayang ugnayan nga,<br/>Kapag lumisan ka na;<br/>Mal''walhating larawan Niya,<br/>Makita sa iyong mukha.<br/>[Makita sa iyong mukha.]<br/><!--(Ulitin ang huling linya ng bawa''t saknong)--><br/>',NULL,41268,4);
INSERT INTO stanza VALUES('T554','1','Bago magbukang-liwayway<br/>Sa Kanyang presensya''y lumapit;<br/>Ang Kanyang mukha''y aking namasdan,<br/>Liwanag ay sumapit.<br/>Sa ''kin sinalita''t ''pinahayag<br/>Lahat ng yaman Niya ngayon;<br/>Buong lugod ako''y bumahagi,<br/>Napawi aking gutom.<br/>',NULL,41269,1);
INSERT INTO stanza VALUES('T554','2','Espiritu''y nagsalita<br/>Napaawit ang puso ko nga;<br/>Bukal ng buhay sa ''king kalul''wa,<br/>Dala''y lakas, biyaya.<br/>Sa ''kin sinalita''t ''pinahayag<br/>Yaman Niya''y ipinabatid;<br/>Kaya sa Kanya ako''y uminom,<br/>Uhaw ko ay napatid.<br/>',NULL,41270,2);
INSERT INTO stanza VALUES('T554','3','Magiliw makitungo Siya<br/>Sa presensya Niya''y may ligaya;<br/>Ako''y pinuspusan, tinustusan<br/>Ng lahat Niyang esensya.<br/>Sa ''kin sinalita''t ''pinahayag<br/>Ang Kanyang yaman nang lubos;<br/>Ako ay nagtamasa sa Kanya,<br/>Sulirani''y natapos.<br/>',NULL,41271,3);
INSERT INTO stanza VALUES('T555','1','Ang bukang-liwayway di pa sumapit,<br/>Nananahimik, at kapiling Ka;<br/>Anino''y naglaho, ibon umawit;<br/>Nagising ako, kapiling Kita.<br/>',NULL,41272,1);
INSERT INTO stanza VALUES('T555','2','Naaninag sa dagat mapayapa,<br/>Larawan ng tala sa umaga;<br/>Sa katahimikan minasdan Kita,<br/>Iyong larawan nasa puso ko na.<br/>',NULL,41273,2);
INSERT INTO stanza VALUES('T555','3','Dala ng pagal nagpahinga ako,<br/>Sa panalangin sa Iyo''y tumuon;<br/>Matamis ang pahinga sa lilim Mo,<br/>Mas pa kung nar''yan Ka sa pagbangon!<br/>',NULL,41274,3);
INSERT INTO stanza VALUES('T555','4','Gayon din sa huli, sa umaga nga,<br/>Anino sa buhay, tumakas na;<br/>O sa oras na yaon, anong ganda,<br/>Anong l''walhati, kapiling Kita.<br/>',NULL,41275,4);
INSERT INTO stanza VALUES('T556','1','Ngalang masamyo, parang unggwento;<br/>Pagsinta''y mainam kaysa alak;<br/>Di-matanggihan ang pag-akit Mo,<br/>Landas ng kawan ang tinatahak.<br/>',NULL,41276,1);
INSERT INTO stanza VALUES('T556','2','Siya ang Sinta ko, ako''y irog Niya;<br/>Akitin Niya ''ko, Siya''y hahabulin;<br/>Sa dibdib ko Siya''y tulad ng mira,<br/>At Siya''y alhena† aking daramtin.<br/>',NULL,41277,2);
INSERT INTO stanza VALUES('T556','3','Tamasahin ang katabaan Niya,<br/>At katamisan sa Kanyang yapos;<br/>Watawat panaklob, pagsinta Niya,<br/>Ginagalak ang puso kong lubos.<br/>',NULL,41278,3);
INSERT INTO stanza VALUES('T556','4','Ang Sinta ko''y akin, ako''y Kanya;<br/>Lila ako at Siya''y aking Pastol;<br/>Lumamig araw, lilim mawala;<br/>Sa bundok nakita batang usa.<br/>',NULL,41279,4);
INSERT INTO stanza VALUES('T556','5','Mira ng kamatayan, kamangyan<br/>Ng pagkabuhay — tigmakin ako;<br/>Gising, hanging hilaga''t timugan,<br/>Kalugdan Niya ang halamanan ko.<br/>',NULL,41280,5);
INSERT INTO stanza VALUES('T556','6','Tulad ng kalapati ang ganda,<br/>Kadalisayan tulad ng lila;<br/>''Ko''y Kanyang tuwa ng mga tuwa,<br/>Aking Awit ng mga awit Siya.<br/>',NULL,41281,6);
INSERT INTO stanza VALUES('T556','7','Tulad ng buwan, ako''y kawangis Niya;<br/>Wagas tulad ng bikas Niyang araw;<br/>Ako''y Kanya, kinalulugdan Niya;<br/>Sa akin, buhay Niya''y matatanaw.<br/>',NULL,41282,7);
INSERT INTO stanza VALUES('T556','8','Buhay Kita, ako''y Iyong larawan;<br/>Parang kamatayan ang pagsinta—<br/>Malakas, di-mapawi''t mapal''tan;<br/>Sa bundok ng espesya''y punta Ka.<br/>',NULL,41283,8);
INSERT INTO stanza VALUES('T558','1','Anong tamis ng pagsalamuha,<br/>Kay Hesus laging magtiwala;<br/>Ako''y pinagpala at payapa,<br/>Kay Hesus laging magtiwala.<br/>',NULL,41284,1);
INSERT INTO stanza VALUES('T558','chorus','Magtiwala,<br/>Ligtas at walang pangamba;<br/>Magtiwala,<br/>Kay Hesus laging magtiwala.<br/>',NULL,41285,2);
INSERT INTO stanza VALUES('T558','2','Landas tinahak, puso''y panatag,<br/>Kay Hesus laging magtiwala;<br/>Lalong tatahak, mas liliwanag,<br/>Kay Hesus laging magtiwala.<br/>',NULL,41286,3);
INSERT INTO stanza VALUES('T558','3','Ano ang kinatatakutan pa?<br/>Kay Hesus laging magtiwala;<br/>Payapa, Panginoo''y kasama,<br/>Kay Hesus laging magtiwala.<br/>',NULL,41287,5);
INSERT INTO stanza VALUES('T559','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41288,1);
INSERT INTO stanza VALUES('T559','1','Sa panalig hipuin Ka,<br/>Tustos sa Iyo nagmula;<br/>Ginamit kalakasan Mo,<br/>Tinanggap sa Iyong dugo.<br/>',NULL,41289,2);
INSERT INTO stanza VALUES('T559','chorus','Kumislap ang bagong buhay<br/>Nang mahipo nga Kita;<br/>Maningas Mong Espiritu,<br/>Naglinis at nagpuno.<br/>',NULL,41290,3);
INSERT INTO stanza VALUES('T559','2','Sa panalig hipuin Ka,<br/>Yaman Mo''y gamitin na;<br/>Bukas buong katauhan,<br/>Ako ay Iyong punuan.<br/>',NULL,41291,4);
INSERT INTO stanza VALUES('T559','3','Mas malalim, hipuin Ka,<br/>Hipuin Iyong sagana;<br/>Biyaya tanggapin sa Iyo,<br/>Buhay Mo dinaloy ko.<br/>',NULL,41292,6);
INSERT INTO stanza VALUES('T559','4','Lakas, dunong, kailangan ko,<br/>Galing, b''yaya''y tustos Mo;<br/>Hipuin Kita''t mahalin,<br/>Yaman Mo''y ''king angkinin.<br/>',NULL,41293,8);
INSERT INTO stanza VALUES('T561','1','Ikaw ang tunay na puno<br/>At ako ang Iyong sanga,<br/>Nguni''t hindi ko matanto<br/>Bakit wala ''kong bunga.<br/>',NULL,41294,1);
INSERT INTO stanza VALUES('T561','2','Inasam ko ang mamunga,<br/>Maihayag Iyong buhay;<br/>Sa trono l''walhatiin Ka,<br/>Ito''y dalanging tunay.<br/>',NULL,41295,2);
INSERT INTO stanza VALUES('T561','3','Panginoon di ko alam<br/>Ano''ng manahan sa Iyo,<br/>Lalo kong sinusubukan,<br/>Lalong napapalayo.<br/>',NULL,41296,3);
INSERT INTO stanza VALUES('T561','4','Pananaha''y di ko damá,<br/>Ga''no mang pagpas''ya ko;<br/>Tila Ika''y malayo pa,<br/>At walang bunga ako.<br/>',NULL,41297,4);
INSERT INTO stanza VALUES('T561','5','Ikaw ang puno ng ubas,<br/>Wika Mo, ako''y sanga,<br/>Nang matanggap Manliligtas,<br/>Espiritu''y gumawa.<br/>',NULL,41298,5);
INSERT INTO stanza VALUES('T561','6','Ako''y nasa loob Mo na,<br/>Di ang papasok pa lang;<br/>Ako''y ganap Mong kaisa,<br/>Sa buto at sa laman.<br/>',NULL,41299,6);
INSERT INTO stanza VALUES('T561','7','Di ang "papasok" siyang lihim,<br/>Kundi "nasa loob" na;<br/>Di na lalabas — ''king samo,<br/>Di pa''nong papasok pa.<br/>',NULL,41300,7);
INSERT INTO stanza VALUES('T561','8','Ako''y nasa Iyong loob na,<br/>Tunay na pangyayari!<br/>Di kailangan dasal, gawa,<br/>Diyos gumawa''t naghari.<br/>',NULL,41301,8);
INSERT INTO stanza VALUES('T561','9','Di kailangang pumasok pa,<br/>Ako''y nasa loob na,<br/>Dapat magpuri''t matuwa,<br/>Manahan sa Salita.<br/>',NULL,41302,9);
INSERT INTO stanza VALUES('T561','10','Ngayon ako''y matiwasay,<br/>Ika''y lahat sa akin,<br/>Ikaw ang lakas at buhay,<br/>Sarili ko''y lipulin.<br/>',NULL,41303,10);
INSERT INTO stanza VALUES('T563','1','Sa Iyo manahan — ang aking samo,<br/>Sa Iyo manahan walang paghinto,<br/>Kung paano ang sanga sa puno,<br/>Ako rin ay nakaugnay sa Iyo.<br/>',NULL,41304,1);
INSERT INTO stanza VALUES('T563','2','Sa Iyo manahan — ang tamasa ko,<br/>Sa ''kin umapaw kayamanan Mo,<br/>Sanga ay manatiling sariwa<br/>Nang saganang makapamumunga.<br/>',NULL,41305,2);
INSERT INTO stanza VALUES('T563','3','Sa Iyo manahan — tiyak pagwagi<br/>Laban sa mga sala''t sarili;<br/>Sa Iyo ako''y nakisalamuha,<br/>Kilos ng kalulwa''y masawata.<br/>',NULL,41306,3);
INSERT INTO stanza VALUES('T563','4','Sa Iyo manahan, mithi Mo''y talos,<br/>Kapayapaa''t galak bumuhos;<br/>Presensya at lihim Mo''y ilahad,<br/>At Iyong Salitang tustos sa lahat.<br/>',NULL,41307,4);
INSERT INTO stanza VALUES('T564','1','Lihim aking natutuhan<br/>Kay Hesus ay manahan;<br/>Bukal ng buhay natikman,<br/>Nang salita''y manamnam.<br/>Nang sa dugo Niya manahan,<br/>Lakas, tamis, nakamtan;<br/>Sarili ko''y lubusan na<br/>Kay Hesus nga''y nawala.<br/>',NULL,41308,1);
INSERT INTO stanza VALUES('T564','chorus','Sa Kanya ay manahan,<br/>Salita''y aasahan,<br/>Kanyang pag-ibig ang aking kublihan.<br/>Oo, sa Kanya''y manahan,<br/>Salita''y aasahan,<br/>Kanyang pag-ibig ang aking kublihan.<br/>',NULL,41309,2);
INSERT INTO stanza VALUES('T564','2','Kasamang sa krus napako,<br/>Nabubuhay di na ''ko;<br/>Sikap ko lahat nahinto,<br/>''Tahan Siya sa loob ko.<br/>Sa Kanya ako''y sumuko,<br/>Maghari Espiritu;<br/>Bawa''t saglit Kanyang dugo,<br/>Nililinisan ako.<br/>',NULL,41310,3);
INSERT INTO stanza VALUES('T564','3','Karamdaman, katakutan,<br/>Maging kapighatian,<br/>Bawa''t araw Siya''ng sabihan,<br/>At Kanyang pinapasan.<br/>Hininga ko''t kalakasan,<br/>Pag-ibig at isipan,<br/>Maging pananalig, buhay,<br/>Sa akin Siya''ng nagbigay.<br/>',NULL,41311,5);
INSERT INTO stanza VALUES('T564','4','Sa salita at gawain<br/>Espiritu''y gamitin;<br/>Presensya Niya sa ''king gawi,<br/>Ako''y gabayan lagi.<br/>Sa puso ko, bahagi Siya,<br/>O bukal na sagana;<br/>Tagapagligtas ko''t Hari,<br/>Pangino''ng mal''walhati.<br/>',NULL,41312,7);
INSERT INTO stanza VALUES('T568','1','Kay tamis ang magtiwala<br/>Kay Hesus sa salita,<br/>Mamahinga sa pangako,<br/>Siya ang maysabi nito.<br/>',NULL,41313,1);
INSERT INTO stanza VALUES('T568','chorus','Hesus, Hesus, kay tapat Mo,<br/>Subok ko ang totoo,<br/>Hesus, Hesus, ang mahal ko,<br/>Kailanma''y di nambigo.<br/>',NULL,41314,2);
INSERT INTO stanza VALUES('T568','2','Ang magtiwala — kay tamis,<br/>Sa dugong makalinis;<br/>At makagaling na batis,<br/>Sala''t sakit inalis.<br/>',NULL,41315,3);
INSERT INTO stanza VALUES('T568','3','Si Hesus pagtiwalaan,<br/>Kasalana''y layuan;<br/>Tanggapin ang biyaya Niya:<br/>Buhay, galak, pahinga.<br/>',NULL,41316,5);
INSERT INTO stanza VALUES('T568','4','Kay galak ang magtiwala<br/>At laging sumasama;<br/>Kay Hesus na Manliligtas,<br/>Tapat hanggang sa wakas.<br/>',NULL,41317,7);
INSERT INTO stanza VALUES('T578','1','Kalooban ko''y mahina,<br/>Pag-asa halos nawala;<br/>Sa Iyong gawa''y may tiwala,<br/>Ako''y marahang gabayan.<br/>',NULL,41318,1);
INSERT INTO stanza VALUES('T578','2','Gumawa nguni''t nabigo,<br/>Tulad noon natisod pa;<br/>Tiwala''y sa pagtiis Mo,<br/>Ingatan sa salita Mo.<br/>',NULL,41319,2);
INSERT INTO stanza VALUES('T578','3','T''wing puso ko''y magpalalo,<br/>Malapit sa katisuran;<br/>Di mangahas ''ko''y gumawa<br/>''Pagka''t Ikaw ang kailangan.<br/>',NULL,41320,3);
INSERT INTO stanza VALUES('T578','4','Tagapagligtas lakas ko,<br/>Hinahangad ko Iyong mukha;<br/>Kahit ako''y mas mahina,<br/>Lakas ko''y Iyo lang biyaya.<br/>',NULL,41321,4);
INSERT INTO stanza VALUES('T582','1','Lumalakad sa liwanag ng Salita,<br/>L''walhati tumanglaw sa akin,<br/>Sundin ko lamang Siya at pupunuin Niya<br/>Ang nagtiwala''t masunurin.<br/>',NULL,41322,1);
INSERT INTO stanza VALUES('T582','chorus','Magtiwala, tumalima lamang,<br/>Nang kay Hesus masiyahan,<br/>Ito''y tanging daan.<br/>',NULL,41323,2);
INSERT INTO stanza VALUES('T582','2','Lupa''y walang dilim, langit walang ulap<br/>Na di-mapawi ng ngiti Niya;<br/>Walang duda''t takot, walang luha''t hirap<br/>Di-maparam kung magtiwala.<br/>',NULL,41324,3);
INSERT INTO stanza VALUES('T582','3','Walang pinapasan, walang kalungkutan<br/>Na di-ipagmalasakit Niya;<br/>Hapis at kawalan, tatwa, kahihiyan,<br/>Maging biyaya, magtiwala.<br/>',NULL,41325,5);
INSERT INTO stanza VALUES('T582','4','Nang maunawaan tamis pag-ibig Niya,<br/>Ihandog lahat sa dambana;<br/>Binibigyan Niya ng galak at biyaya,<br/>Tanging mga tagasunod Niya.<br/>',NULL,41326,7);
INSERT INTO stanza VALUES('T582','5','Matamis na pagsasalamuha rito,<br/>Sa paglakad kasabay ko Siya;<br/>Gawin ang sinabi, sundin pagsusugo,<br/>Huwag matakot at magtiwala.<br/>',NULL,41327,9);
INSERT INTO stanza VALUES('T583','1','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Kung saan Siya''y nagdusa,<br/>Batahin Kanyang dusta.<br/>',NULL,41328,1);
INSERT INTO stanza VALUES('T583','2','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Krus, kusang papasanin,<br/>Makitid ay landasin.<br/>',NULL,41329,2);
INSERT INTO stanza VALUES('T583','3','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Minamahal iwanan,<br/>Lugod Ama ay bigyan.<br/>',NULL,41330,3);
INSERT INTO stanza VALUES('T583','4','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Siya lamang ''yong samahan,<br/>Mundo''t relih''yon iwan.<br/>',NULL,41331,4);
INSERT INTO stanza VALUES('T583','5','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Kai-bigan nagsilisan,<br/>Kay Hesus kasiyahan.<br/>',NULL,41332,5);
INSERT INTO stanza VALUES('T583','6','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Kasama Siya, kay saya,<br/>Ngiti Niya''y nakikita.<br/>',NULL,41333,6);
INSERT INTO stanza VALUES('T583','7','"Labas ng kampamento,"<br/>Si Hesus puntahan mo;<br/>Hanggang bukang-liwayway,<br/>Kaharian dumatal.<br/>',NULL,41334,7);
INSERT INTO stanza VALUES('T585','1','Patnubay Siya — biyaya nga!<br/>Makalangit kaaliwan!<br/>Sa gawa at nasaan man,<br/>Ako''y pinapatnubayan.<br/>',NULL,41335,1);
INSERT INTO stanza VALUES('T585','chorus','Patnubay Siya, patnubay Siya,<br/>Patnubay ang Kanyang kamay;<br/>Tapat akong alagad Niya,<br/>Patnubay ang Kanyang kamay.<br/>',NULL,41336,2);
INSERT INTO stanza VALUES('T585','2','Kung minsa''y walang ligaya,<br/>Kung minsa''y tulad ng Eden,<br/>Maalon ma''t mapayapa,<br/>Pumatnubay rin kamay Niya.<br/>',NULL,41337,3);
INSERT INTO stanza VALUES('T585','chorus','Patnubay Siya, patnubay Siya,<br/>Patnubay ang Kanyang kamay;<br/>Tapat akong alagad Niya,<br/>Patnubay ang Kanyang kamay.<br/>',NULL,41338,4);
INSERT INTO stanza VALUES('T585','3','Panginoon, ako''y tangnan,<br/>Tatanggapin Iyong ibigay,<br/>Maging pala o hirap man,<br/>Yamang Ikaw ang patnubay.<br/>',NULL,41339,5);
INSERT INTO stanza VALUES('T585','chorus','Patnubay Siya, patnubay Siya,<br/>Patnubay ang Kanyang kamay;<br/>Tapat akong alagad Niya,<br/>Patnubay ang Kanyang kamay.<br/>',NULL,41340,6);
INSERT INTO stanza VALUES('T585','4','Pagkatapos ng gawa ko,<br/>Biyayang tagumpay tamo,<br/>Mamatay ma''y di ma''ngamba,<br/>Iyong kamay pa ring nagdala.<br/>',NULL,41341,7);
INSERT INTO stanza VALUES('T585','chorus','Patnubay Siya, patnubay Siya,<br/>Patnubay ang Kanyang kamay;<br/>Tapat akong alagad Niya,<br/>Patnubay ang Kanyang kamay.<br/>',NULL,41342,8);
INSERT INTO stanza VALUES('T586','1','Magiliw ang Kanyang tinig,<br/>Tinawag ako ni Hesus,<br/>Aniya sa aking pandinig,<br/>"Sumunod ka, dalhin mo ang krus."<br/>',NULL,41343,1);
INSERT INTO stanza VALUES('T586','chorus','Dadalhin ang krus, at sundan<br/>Si Hesus ang aking sundan;<br/>Sundan ko kahit saan man,<br/>Tatahakin ang Kanyang daan.<br/>',NULL,41344,2);
INSERT INTO stanza VALUES('T586','2','Kahit madilim ang daan,<br/>Paa ko''y pagod, sugatan,<br/>Nguni''t puso may aliwan,<br/>Si Hesus ang lagi kong sundan.<br/>',NULL,41345,3);
INSERT INTO stanza VALUES('T586','3','Hesus, ako''y pangunahan,<br/>Sinag Mo ako''y tanglawan,<br/>Kung mahina, alalayan,<br/>Si Hesus ang lagi kong sundan.<br/>',NULL,41346,5);
INSERT INTO stanza VALUES('T586','4','Sa lambak Siya ang kaibigan,<br/>Manna ako''y tinustusan,<br/>Bawa''t oras, Siya''ng kailangan,<br/>Si Hesus ang lagi kong sundan.<br/>',NULL,41347,7);
INSERT INTO stanza VALUES('T586','5','Puso Mo ako''y tanganan,<br/>Pag-ibig Mo''y kaaliwan,<br/>Biyaya Mo''y tumataban,<br/>Si Hesus ang lagi kong sundan.<br/>',NULL,41348,9);
INSERT INTO stanza VALUES('T586','6','Di Kita maiiwanan,<br/>''Ko''y tapat magpakailanman,<br/>Pag-ibig Mo''y walang hanggan,<br/>Si Hesus ang lagi kong sundan.<br/>',NULL,41349,11);
INSERT INTO stanza VALUES('T587','1','Kay tamis Hesus, kasama,<br/>Bagama''t may hirap pa;<br/>Yapak Niya''y aking susundan,<br/>Sa makitid na daan.<br/>',NULL,41350,1);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41351,2);
INSERT INTO stanza VALUES('T587','2','Ligtas nga, Hesus kasama,<br/>Nakasandal sa Kanya;<br/>Mahigpit Siyang sinusundan,<br/>Di ako masasaktan.<br/>',NULL,41352,3);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41353,4);
INSERT INTO stanza VALUES('T587','3','Sa lakad Hesus kasama,<br/>Hakbang kada hakbang nga;<br/>Taas di-kayang liparin,<br/>Pahakbang aakyatin.<br/>',NULL,41354,5);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41355,6);
INSERT INTO stanza VALUES('T587','4','Lalakad Hesus kasama,<br/>Sa hapis man o tuwa;<br/>Ako man ay pangunahan<br/>Sa hardin o libingan.<br/>',NULL,41356,7);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41357,8);
INSERT INTO stanza VALUES('T587','5','Lalakad Hesus kasama,<br/>Sandali lang sa lupa;<br/>Gabi''y magiging umaga,<br/>Hapis magiging kanta.<br/>',NULL,41358,9);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41359,10);
INSERT INTO stanza VALUES('T587','6','Lalakad Hesus kasama,<br/>Pati mga iba pa;<br/>Mandaraig na lalakad,<br/>Nangakaputing lahat.<br/>',NULL,41360,11);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41361,12);
INSERT INTO stanza VALUES('T587','7','Hesus, mas ilapit ako,<br/>Nang araw-araw sa Iyo;<br/>Tinatahak ang yapak Mo,<br/>Nang lubusa''t diretso.<br/>',NULL,41362,13);
INSERT INTO stanza VALUES('T587','chorus','Hakbang nga, hakbang pa,<br/>Sundan ang yapak Niya;<br/>Araw o gabi man,<br/>Sa ''kitid na daan.<br/>',NULL,41363,14);
INSERT INTO stanza VALUES('T589','1','Diyos sa langit ay may yaman,<br/>Di masaysay nang lubos;<br/>Mahal Niya walang hangganan,<br/>Anak Niyang Kristo Hesus.<br/>Diyos sa lupa ay may yaman,<br/>Tanging Siya maalam din;<br/>Malalim Niyang kaluguran<br/>Kristo''y nahayag sa ''kin.<br/>',NULL,41364,1);
INSERT INTO stanza VALUES('T589','2','Di-maparisang halaga,<br/>Di-maubos na yaman;<br/>Tulad ng apoy na dila,<br/>Pinuspos ang sisidlan.<br/>Diyos Mismong pumuspos dito,<br/>Mula sa kalangitan;<br/>Payapa sabik na puso,<br/>Sa pag-ibig mayaman.<br/>',NULL,41365,2);
INSERT INTO stanza VALUES('T589','3','Marangal na tawag sa iyo,<br/>Daig pagsubok, tukso;<br/>Sanga in''ugnay sa puno,<br/>Ibuhos ang lahat mo.<br/>Abang sisidlang-lupa man,<br/>Dukha at walang dangal,<br/>Sa loob taglay mong yaman,<br/>Si Kristong pinarangal.<br/>',NULL,41366,3);
INSERT INTO stanza VALUES('T589','4','Maging basyo at mababa,<br/>Di-pansinin at tago;<br/>Sisidlan ng Diyos, banal pa,<br/>Kay Kristo''y punung-puno!<br/>L''walhating di-natatakpan<br/>Ng sarili o lupa;<br/>Ibida ang kasaysayan,<br/>Binasyo''t pinuspos Niya.<br/>',NULL,41367,4);
INSERT INTO stanza VALUES('T590','1','Sa sisidlang lupang hamak,<br/>Sumilay biyaya Niya;<br/>Pusong panglaw niliwanag,<br/>Ilaw kay Hesus buhat!<br/>',NULL,41368,1);
INSERT INTO stanza VALUES('T590','2','Kristo, liwanag ng langit,<br/>Sa lupa sumilay rin;<br/>Espiritu Niya''y binigay,<br/>Buhay ating tinaglay.<br/>',NULL,41369,2);
INSERT INTO stanza VALUES('T590','3','Mula makalangit gloria,<br/>Diyos Mismo ang dinala;<br/>Napasa sisidlang lupa,<br/>Nang tao''y mapahanga.<br/>',NULL,41370,3);
INSERT INTO stanza VALUES('T590','4','Walang rilag, walang ganda,<br/>Mga sisidlang lupa;<br/>Nguni''t yamang makalangit,<br/>Laging walang hihigit.<br/>',NULL,41371,4);
INSERT INTO stanza VALUES('T590','5','Sisidlang lupa''y mahina,<br/>Gutom, uhaw binata;<br/>Nguni''t Anak naitanghal,<br/>Yamang nakapagbigay.<br/>',NULL,41372,5);
INSERT INTO stanza VALUES('T591','1','Hindi ako, kundi si Kristo lamang,<br/>Pinarangal, inibig, sinamba;<br/>Hindi ako, kundi si Kristo lamang<br/>Sa salita, sa isip, at gawa.<br/>',NULL,41373,1);
INSERT INTO stanza VALUES('T591','chorus','Iligtas ako sa sarili,<br/>Nawa''y mapasa Iyo,<br/>Nawa''y di na ako, kundi<br/>Mabuhay si Kristo.<br/>',NULL,41374,2);
INSERT INTO stanza VALUES('T591','2','Kristo lamang, ang umaliw sa akin,<br/>Kristo lamang, nagpahid ng luha;<br/>Kristo lamang, nagbuhat ng pasanin,<br/>Kristo lamang, nagpawi ng kaba.<br/>',NULL,41375,3);
INSERT INTO stanza VALUES('T591','3','Kristo lamang, di ang hungkag na wika,<br/>Kristo lamang, di kapalaluan;<br/>Sarili ko''y hindi pinadakila,<br/>Kristo lamang, ako''y hinalinhan.<br/>',NULL,41376,5);
INSERT INTO stanza VALUES('T591','4','Kristo lamang, ang tustos sa kailangan,<br/>Kristo lamang, aking kalusugan;<br/>Kristo lamang, sa buong katauhan,<br/>Buhay Niya ay sa akin namasdan.<br/>',NULL,41377,7);
INSERT INTO stanza VALUES('T591','5','Kristo lamang, malapit nang makita,<br/>L''walhati Niya ay walang katulad;<br/>Kristo lamang, tinupad aking nasa,<br/>Kristo lamang, aking lahat-lahat.<br/>',NULL,41378,9);
INSERT INTO stanza VALUES('T593','1','Kay Adam ay kamatayan at sala,<br/>Buhay at kat''wiran ay kay Kristo nga;<br/>Sa laman si Adam ang nabubunyag,<br/>Si Kristo sa ''spiritu nahahayag.<br/>',NULL,41379,1);
INSERT INTO stanza VALUES('T593','2','Kay Adam sa kamatayan ang punta,<br/>Di man magkasala''y nahatulan na;<br/>Kay Kristo ako''y inaring-matuwid,<br/>Hindi na kailangang magpakatuwid.<br/>',NULL,41380,2);
INSERT INTO stanza VALUES('T593','3','Kusa kong maihahayag sa laman,<br/>Ang pagkamakasalanan ni Adam;<br/>Walang hirap sa Espiritu Santo,<br/>Na ako''y mamuhay gaya ni Kristo.<br/>',NULL,41381,3);
INSERT INTO stanza VALUES('T593','4a','Sa kamatayang kalakip ni Kristo,<br/>Mula kay Adam napalaya ako;<br/>Sa kabuhayang kalakip ni Kristo,<br/>Ang bagong buhay ay aking natamo.<br/>',NULL,41382,4);
INSERT INTO stanza VALUES('T593','4b','Walang magagawa ang lumang Adam,<br/>Kung wala ang pag-iisip sa laman;<br/>Pagtuon ng isip sa espiritu,<br/>Buhay dibino''y napatunayan ko.<br/>',NULL,41383,5);
INSERT INTO stanza VALUES('T593','5','Pagtuon ng isip sa espiritu,<br/>Kaligtasan ng Diyos ang daang ito,<br/>Maihayag ko ang buhay ni Kristo;<br/>Tagumpay sa sala magagawa ko.<br/>',NULL,41384,6);
INSERT INTO stanza VALUES('T593','6','Pagtuon ng isip sa espiritu,<br/>Krus at muling pagkabuhay batid ko;<br/>At aking naibubuhay si Kristo,<br/>Ang dulot ay paglago sa buhay ko.<br/>',NULL,41385,7);
INSERT INTO stanza VALUES('T593','7','Sa espiritu, si Kristo ang buhay,<br/>Pagpapala''t kalakasan ay taglay;<br/>Kabanala''y aking nararanasan,<br/>Tres-unong Diyos naging katotohanan.<br/>',NULL,41386,8);
INSERT INTO stanza VALUES('T594','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41387,1);
INSERT INTO stanza VALUES('T594','1','Kristo''y aking buhay, kapayapaan,<br/>Sa Espiritu''y may katamasahan.<br/>',NULL,41388,2);
INSERT INTO stanza VALUES('T594','chorus','Espiritu''y sundin, ibuhay Kristo,<br/>Buhay itinustos, payapa ako.<br/>',NULL,41389,3);
INSERT INTO stanza VALUES('T594','2','Kautusan ng buhay nagpalaya,<br/>Espiritu''y aking tinatamasa.<br/>',NULL,41390,4);
INSERT INTO stanza VALUES('T594','3','Ituon ang isip sa espiritu,<br/>Espiritu''y sundin, di sarili ko.<br/>',NULL,41391,6);
INSERT INTO stanza VALUES('T594','4','Hindi laban sa Diyos ni Kanyang utos,<br/>Kundi may kat''wirang higit sa utos.<br/>',NULL,41392,8);
INSERT INTO stanza VALUES('T594','5a','Espiritung nasa espiritu ko,<br/>Ikabubuhay rin ng katawan ko.<br/>',NULL,41393,10);
INSERT INTO stanza VALUES('T594','5b','Nagkaisang dalawang espiritu,<br/>Nagpatotoong anak ng Diyos ako.<br/>',NULL,41394,12);
INSERT INTO stanza VALUES('T595','1','Kung Panginoon natikman,<br/>May labis walang kulang;<br/>Bawa''t sarong pinupunan,<br/>T''yak aapaw sa yaman.<br/>Mula sa Kanyang imbakan,<br/>Dalay di-pinigilan.<br/>Umaapaw nang higit pa,<br/>Tustos sa mga Kanya,<br/>Umaapaw nang higit pa,<br/>Tustos sa mga Kanya.<br/>',NULL,41395,1);
INSERT INTO stanza VALUES('T595','2','Sa Ama, tayo''y nabigyan,<br/>May labis walang kulang;<br/>Salamat sa bahagi ko,<br/>Purihin Ka sa plano.<br/>Puspos aming kasiyahan,<br/>Panustos sa kailangan;<br/>Puso''y natikman si Hesus,<br/>Kasiyahan ay lubos,<br/>Puso''y natikman si Hesus,<br/>Kasiyahan ay lubos.<br/>',NULL,41396,2);
INSERT INTO stanza VALUES('T595','3','Pagsinta, magbahaginan,<br/>May labis, walang kulang;<br/>Kalalimang di maarók<br/>Kataasang di-abot.<br/>Siya nga''y kagila-gilalas,<br/>Labi ko''y di mabigkas;<br/>Pagpalain Kanyang ngalan,<br/>Dapat Siyang papurihan!<br/>Pagpalain Kanyang ngalan,<br/>Dapat Siyang papurihan.<br/>',NULL,41397,3);
INSERT INTO stanza VALUES('T598','1','Sa bilad ng araw nangingitim,<br/>Anak ng liwanag marilag din;<br/>Hiwaga ng galak, di-mabatid,<br/>Mal''walhating Hari ang naghatid.<br/>Di-naisip ng tao man,<br/>Ni kailanman nahawakan;<br/>Sa liwanag nanahanan,<br/>Natamo''y kal''walhatian.<br/>',NULL,41398,1);
INSERT INTO stanza VALUES('T598','2','Lahi lamang ni Adam sa tingin,<br/>Pilat, anyo''t sakit panlupa rin;<br/>Tulad ng natisod na maysala,<br/>Panlabas na kailangan di iba.<br/>Pamumuhay panlupa rin,<br/>Natutulog, kumakain;<br/>Subali''t walang halaga,<br/>Ang panlupa sa kanila.<br/>',NULL,41399,2);
INSERT INTO stanza VALUES('T598','3','May buhay ng Diyos sa loob nila,<br/>Muling ''sinilang ng Salita Niya;<br/>Dibinong pag-ibig nagpaalab,<br/>Sa anak ng Bagong Herusalem.<br/>Banal ng liwanag sila,<br/>Papuring awit kinanta;<br/>Dakilang Diyos pinagbunyi,<br/>Sa kahanga-hangang himig.<br/>',NULL,41400,3);
INSERT INTO stanza VALUES('T598','4','Lakad sa lupa, tahan sa langit,<br/>Walang lakas nguni''t namahala;<br/>May hirap nga nguni''t may payapa,<br/>Dukha man, lahat ay sa kanila.<br/>Binagbag hindi napuksa,<br/>Nakaugat sa ligaya;<br/>Nasa lilim ng kam''tayan,<br/>Nguni''t buháy walang hanggan!<br/>',NULL,41401,4);
INSERT INTO stanza VALUES('T598','5','Kristo buhay nila magpakita,<br/>Dala ang pagkahari at gloria;<br/>Gloria nilang matagal nang kubli,<br/>Mahahayag walang pasubali.<br/>Kristo kasamang aakyat,<br/>Sa langit magliliwanag;<br/>Kubling liwanag sisilay,<br/>Bawa''t banal gaya''y araw.<br/>',NULL,41402,5);
INSERT INTO stanza VALUES('T600','1','Diyos, Pag-ibig, Bahagi rin,<br/>Lahat Ka sa akin,<br/>Sa langit wala nang iba,<br/>Gayundin sa lupa,<br/>Gayundin sa lupa.<br/>',NULL,41403,1);
INSERT INTO stanza VALUES('T600','2','Sa langit ay hungkag lahat,<br/>Lupa''y lalong salat;<br/>Walang kasiyahang lubos,<br/>Walang tulad sa Diyos,<br/>Walang tulad sa Diyos.<br/>',NULL,41404,2);
INSERT INTO stanza VALUES('T600','3','Ika''y aking buhay, yaman,<br/>Tiyak kong tahanan;<br/>Salamat sa ibang bagay,<br/>Nguni''t di Diyos tunay,<br/>Nguni''t di Diyos tunay.<br/>',NULL,41405,3);
INSERT INTO stanza VALUES('T600','4','Kayamana''y laruan din<br/>Kung sa Iyo ihambing!<br/>Kanilang inaasahan,<br/>Pawang panlilinlang,<br/>Pawang panlilinlang.<br/>',NULL,41406,4);
INSERT INTO stanza VALUES('T600','5','Sukdan lupa''y maging akin,<br/>At mga bituin;<br/>Panginoon, kung wala Ka,<br/>Ako''y abang-aba,<br/>Ako''y abang-aba.<br/>',NULL,41407,5);
INSERT INTO stanza VALUES('T600','6','Hayaan ang mga tao,<br/>Kabigin ang gusto;<br/>Nguni''t Ikaw ang ibig ko,<br/>Maging presensya Mo,<br/>Maging presensya Mo.<br/>',NULL,41408,6);
INSERT INTO stanza VALUES('T602','1','Kay l''walhati at kay banal!<br/>Diyos ay buhay walang hanggan!<br/>Kay lakas, wagas, at sakdal<br/>Liwanag, habag, at yaman!<br/>Kapuspusan ng pagka-Diyos<br/>Sa buhay rito''y lubos.<br/>',NULL,41409,1);
INSERT INTO stanza VALUES('T602','2','O pag-ibig at biyaya!<br/>Diyos ay buhay ng tao nga!<br/>May ''spiritu nilikha Niya<br/>Nang doon makapasok Siya.<br/>Ang kaluguran ng Diyos ay<br/>Maging sa tao''y buhay.<br/>',NULL,41410,2);
INSERT INTO stanza VALUES('T602','3','O pag-ibig at biyaya!<br/>Diyos ay buhay na umagos!<br/>Dati''y kubli, ngayo''y hayag,<br/>Dati''y nagkatawang-tao,<br/>Ngayon Siya ay Espiritu<br/>Naging buhay ng tao.<br/>',NULL,41411,3);
INSERT INTO stanza VALUES('T602','4','Kay talik, kay lapit nito!<br/>Diyos na kay Kristo''y buhay ko!<br/>Pahayag ng Diyos si Kristo,<br/>Diyos ay nasa lamang-tao;<br/>Namatay, muling nabuhay,<br/>Sa tao''y naging buhay.<br/>',NULL,41412,4);
INSERT INTO stanza VALUES('T602','5','Kamangha-mangha at tapat!<br/>Diyos ay naging Espiritu!<br/>Pahayag na realidad—<br/>Siya rin sa isa pang anyo;<br/>Tao''y hinihikayat Niya<br/>Nang matahanán sila.<br/>',NULL,41413,5);
INSERT INTO stanza VALUES('T602','6','Kay tunay at kay halaga!<br/>Tatlo-isang Diyos ay buhay!<br/>Anak ang agos ng Ama,<br/>Buhat naman sa Anak ay<br/>Espiritung nagkaloob<br/>Ng buhay sa ''king loob.<br/>',NULL,41414,6);
INSERT INTO stanza VALUES('T602','7','Kay hiwaga at totoo!<br/>Diyos pumasok bilang buhay!<br/>Sa loob ko, kaisa ko,<br/>Sa ''spiritu''y aking buhay.<br/>Aleluya, purihin Siya,<br/>Diyos ay aking buhay na!<br/>',NULL,41415,7);
INSERT INTO stanza VALUES('T605','1','Ang aking tahanan ay Diyos Mismo,<br/>Kristo nagdala sa akin dito;<br/>Dinala ''kong tahakin ang daan,<br/>Patungo sa kabanal-banalan;<br/>Kung saan Diyos at tao''y nanahan,<br/>Anong katamisa''t kagandahan!<br/>',NULL,41416,1);
INSERT INTO stanza VALUES('T605','2','Gabi''t araw daan hinanap ko,<br/>Akala''y sa sarili ang dako,<br/>Walang pagsulong, walang nangyari,<br/>Pawang bigo, sikap ng sarili;<br/>Sa huli nabatid tanging daan,<br/>Nang sa Diyos manahan — Kristo lamang.<br/>',NULL,41417,2);
INSERT INTO stanza VALUES('T605','3','Banal, kamangha-manghang tahanan!<br/>Diyos kasama may kapayapaan;<br/>Yamang Ikaw at ako nagsama<br/>Bilang tahanan sa isa''t isa;<br/>Nawa tungo sa Iyo ang buhay ko,<br/>Diyos laging ibahagi sa tao.<br/>',NULL,41418,3);
INSERT INTO stanza VALUES('T606','1','Nang ang kaisipan ng Diyos,<br/>Umakit sa puso;<br/>Nawaksi panlupang agos,<br/>Maging saya nito.<br/>',NULL,41419,1);
INSERT INTO stanza VALUES('T606','2','Maligtas di-mapahamak,<br/>Hindi pa nga sapat;<br/>Pag-isip sa Diyos nagsanhi<br/>Sa Kanya''y magmithi.<br/>',NULL,41420,2);
INSERT INTO stanza VALUES('T606','3','Sa tao Diyos nga''y tahanan,<br/>Landas makitid man;<br/>Liban sa Diyos wala''ng si-ya,<br/>Uhaw nga sa Kanya.<br/>',NULL,41421,3);
INSERT INTO stanza VALUES('T606','4','''Pag sa iyong kaibuturan,<br/>Diyos ay parangalan;<br/>Lahat ng masamang tukso,<br/>Tiyak maglalaho.<br/>',NULL,41422,4);
INSERT INTO stanza VALUES('T606','5','Puso''t matang may tiwala,<br/>''Tamo''y paggabay Niya;<br/>May lakas ang pananalig,<br/>Anupa''t pag-ibig?<br/>',NULL,41423,5);
INSERT INTO stanza VALUES('T606','6','Landas ng paghabol sa Diyos,<br/>Pagtahak ay kapos!<br/>Sa Diyos, iyong puso''y ituon,<br/>Ika''y mapasulong.<br/>',NULL,41424,6);
INSERT INTO stanza VALUES('T606','7','Pang-araw-araw na gawa,<br/>Lumaya sa sala,<br/>Biyaya rito sa lupa,<br/>Ibig hilingin nga.<br/>',NULL,41425,7);
INSERT INTO stanza VALUES('T606','8','Mahirap para sa laman<br/>Ang sakdal na daan;<br/>Kung ang naisin mo ay Diyos,<br/>Agad kang kikilos.<br/>',NULL,41426,8);
INSERT INTO stanza VALUES('T606','9','Budhi dapat sensitibo,<br/>Damdamin mahipo;<br/>Pagpapahid laging sundin<br/>Paggulang iyong kamtin.<br/>',NULL,41427,9);
INSERT INTO stanza VALUES('T608','1','Kay hiwaga, Ama, Anak, ''Spiritu,<br/>Tatlong persona nguni''t iisa;<br/>Kay l''walhati, Siya''y sa atin pumasok<br/>Upang maging lahat sa atin Siya.<br/>',NULL,41428,1);
INSERT INTO stanza VALUES('T608','chorus','Tres-unong Diyos naging lahat sa ''tin,<br/>Kay l''walhati at kay taas!<br/>Handog ng Diyos di natin masaid!<br/>Kahanga-hanga''t kay wagas!<br/>',NULL,41429,2);
INSERT INTO stanza VALUES('T608','2','Bukal ng yaman sa Ama nanggaling,<br/>Nais Niya na ating tamasahin!<br/>Anong biyaya, kay yamang bahagi,<br/>Walang hanggang mapasasaatin!<br/>',NULL,41430,3);
INSERT INTO stanza VALUES('T608','chorus','Tres-unong Diyos naging lahat sa ''tin,<br/>Kay l''walhati at kay taas!<br/>Handog ng Diyos di natin masaid!<br/>Kahanga-hanga''t kay wagas!<br/>',NULL,41431,4);
INSERT INTO stanza VALUES('T608','3','Anak naman, Siya''y kahayagan ng Diyos,<br/>Naging laman sa lupa tumahan;<br/>Pagtutubos, bisa nito''y kay sakdal,<br/>Kaisahan sa Diyos ''ting nakamtan!<br/>',NULL,41432,5);
INSERT INTO stanza VALUES('T608','chorus','Tres-unong Diyos naging lahat sa ''tin,<br/>Kay l''walhati at kay taas!<br/>Handog ng Diyos di natin masaid!<br/>Kahanga-hanga''t kay wagas!<br/>',NULL,41433,6);
INSERT INTO stanza VALUES('T608','4','Espiritu ay pagbabagong-anyo<br/>Ng Diyos Anak bilang ating tustos;<br/>Sa espiritu natin Siya''y pumasok,<br/>Nakiugnay sa atin nang lubos.<br/>',NULL,41434,7);
INSERT INTO stanza VALUES('T608','chorus','Tres-unong Diyos naging lahat sa ''tin,<br/>Kay l''walhati at kay taas!<br/>Handog ng Diyos di natin masaid!<br/>Kahanga-hanga''t kay wagas!<br/>',NULL,41435,8);
INSERT INTO stanza VALUES('T608','5','Tunay nga, Diyos ngayo''y ang Espiritu;<br/>Sa tuwina''y mararanasan Siya!<br/>Ang Diyos ating kaisang espiritu,<br/>Sa buhay ''y walang pagkakaiba!<br/>',NULL,41436,9);
INSERT INTO stanza VALUES('T608','chorus','Tres-unong Diyos naging lahat sa ''tin,<br/>Kay l''walhati at kay taas!<br/>Handog ng Diyos di natin masaid!<br/>Kahanga-hanga''t kay wagas!<br/>',NULL,41437,10);
INSERT INTO stanza VALUES('T609','1','Purihin Ka sa hiwaga<br/>Upang makaugnay Ka nga;<br/>Di Ka malapitan noon,<br/>Kay lapit ''Spiritu ngayon.<br/>',NULL,41438,1);
INSERT INTO stanza VALUES('T609','2','Ama, Anak, Espiritu,<br/>Aking buhay Diyos Tres-uno;<br/>Ikaw nga ang panustos ko<br/>Nang maging banal tulad Mo.<br/>',NULL,41439,2);
INSERT INTO stanza VALUES('T609','3','Espiritu''y Diyos Tres-uno,<br/>Hininga''t hangin dumapo;<br/>Nang aking mararanasan<br/>Dibinong kahiwagaan.<br/>',NULL,41440,3);
INSERT INTO stanza VALUES('T609','4','Lahat ng Ama''t sa Ama,<br/>Nasa Anak sinisinta;<br/>Lahat ng yaman ng Anak<br/>''Spiritu nama''y tumanggap.<br/>',NULL,41441,4);
INSERT INTO stanza VALUES('T609','5','Sa ''kin bumaba, ''Spiritu,<br/>Pumasok sa ''spiritu ko,<br/>Amang nasa Anak na Siya,<br/>Bahagi kong pinagpala!<br/>',NULL,41442,5);
INSERT INTO stanza VALUES('T609','6','Ama''y bukal, pinagmulan,<br/>Anak nama''y kahayagan;<br/>Kanyang daloy ang ''Spiritu,<br/>Bilang katotohanan ko.<br/>',NULL,41443,6);
INSERT INTO stanza VALUES('T609','7','Sa Anak Ama''y dumating<br/>Nang Diyos sa tao''y pakita;<br/>Pumasok ''Spiritu sa ''kin,<br/>Nang Diyos makilala ko rin.<br/>',NULL,41444,7);
INSERT INTO stanza VALUES('T609','8','Anak, nilayon ng Ama,<br/>Sa tanang bagay manguna<br/>Anak ginawa Niya''ng Ulo,<br/>Sa lahat Siya''ng namumuno.<br/>',NULL,41445,8);
INSERT INTO stanza VALUES('T609','9','Espiritu ay may mithi,<br/>Kristo Anak mal''walhati;<br/>Sa akin Siya''y ihayag Niya,<br/>Nang mapatotohanan Siya.<br/>',NULL,41446,9);
INSERT INTO stanza VALUES('T609','10','Huli Mong anyo''y ''Spiritu,<br/>Tanggapin pagsamba namin;<br/>Sa ''spiritu kaugnayin,<br/>Nang yaman Mo''y tamasahin.<br/>',NULL,41447,10);
INSERT INTO stanza VALUES('T609','11','Sa ''spiritu sambahin Ka,<br/>Mamuhay, manalangin pa;<br/>Espiritu mahipo ko,<br/>Ikaw ay matamasa ko.<br/>',NULL,41448,11);
INSERT INTO stanza VALUES('T610','1','Paglalin ng Diyos-''Spiritu,<br/>Diyos pasok sa loob namin;<br/>Ang Diyos sa loob ni Kristo,<br/>Ay mararanasan natin.<br/>',NULL,41449,1);
INSERT INTO stanza VALUES('T610','2','Diyos Ama ang pinagmulan,<br/>Diyos Anak ang kahayagan;<br/>''Spiritung pumasok sa ''tin,<br/>Diyos bilang lahat maangkin.<br/>',NULL,41450,2);
INSERT INTO stanza VALUES('T610','3','Amang hindi malapitan,<br/>Anak dala''y kahayagan;<br/>Espiritu siyang naghatid,<br/>Nang Diyos lubos kong mabatid.<br/>',NULL,41451,3);
INSERT INTO stanza VALUES('T610','4','Anak sa loob ng Ama,<br/>Naging ''Spiritu ang Anak.<br/>Ama, Anak, Espiritu,<br/>Kaisa natin sa loob.<br/>',NULL,41452,4);
INSERT INTO stanza VALUES('T610','5','Ama sa loob ng Anak,<br/>Nai-sakatawan, nahayag;<br/>Diyos ''Spiritu''y realidad,<br/>Ng Anak upang matanggap.<br/>',NULL,41453,5);
INSERT INTO stanza VALUES('T610','6','Pag-ibig nga ng Diyos Ama,<br/>Nasa Anak maging b''yaya;<br/>Salamuha''y sa ''Spiritu,<br/>Diyos bahagi ko''y matamo.<br/>',NULL,41454,6);
INSERT INTO stanza VALUES('T611','1','Substansya ng Diyos — ''Spiritu,<br/>Kanyang esensya, dibino;<br/>Sa ''spiritu hipuin Siya,<br/>Makaugnay Siya''t tamasa.<br/>',NULL,41455,1);
INSERT INTO stanza VALUES('T611','2','Kailalima''y ''spiritu,<br/>Sangkap na tunay ng tao;<br/>Kung Diyos ay kakaugnayin,<br/>Sa espiritu''y bumaling.<br/>',NULL,41456,2);
INSERT INTO stanza VALUES('T611','3','Pagsambang hanap ng Ama<br/>Tanging nasa ''spiritu nga;<br/>''Spiritu Niya sa ''spiritu,<br/>Dalawa nga''y napaghalo.<br/>',NULL,41457,3);
INSERT INTO stanza VALUES('T611','4','Espiritu sa ''spiritu,<br/>Nagkaisa, naihalo;<br/>Pantaong ''spiritu''y bahay<br/>Dibinong ''Spiritu''y buhay.<br/>',NULL,41458,4);
INSERT INTO stanza VALUES('T611','5','Paghipo sa Espiritu,<br/>Ng pantaong espiritu;<br/>Dulot manahan nang lubos,<br/>At sumambang tunay sa Diyos.<br/>',NULL,41459,5);
INSERT INTO stanza VALUES('T611','6','Ministeryo, salamuha<br/>Sa ''spiritu tao''y dalhin;<br/>Espiritu at ''spiritu,<br/>Magtugunan sa dalangin.<br/>',NULL,41460,6);
INSERT INTO stanza VALUES('T611','7','Sa ''spiritu manalangin,<br/>Maglingkod at Diyos hipuin;<br/>Lumalago, nagtatayo<br/>Nahayag gloria ni Kristo.<br/>',NULL,41461,7);
INSERT INTO stanza VALUES('T611','8','O Panginoon, nais ko,<br/>Bumaling sa espiritu;<br/>Ang Sarili Mo''y hipuin,<br/>Espiritu''y padaluyin.<br/>',NULL,41462,8);
INSERT INTO stanza VALUES('T612','1','Nais ng Diyos ang lahat Niya<br/>Maging tustos ko;<br/>Kailangan ko''y makamtan sa<br/>Espiritu.<br/>',NULL,41463,1);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41464,2);
INSERT INTO stanza VALUES('T612','2','Kapuspusan ng pagka-Diyos<br/>Nasa akin na;<br/>Hipuin sa espiritu,<br/>Matamo Siya.<br/>',NULL,41465,3);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41466,4);
INSERT INTO stanza VALUES('T612','3','Linaw ng isip kailangan<br/>Diyos ay kilanlin;<br/>Kung ''spiritu''y di gamitin<br/>Di mas''yahan.<br/>',NULL,41467,5);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41468,6);
INSERT INTO stanza VALUES('T612','4','Espiritu''y gamitin sa<br/>Pananalangin;<br/>Pagbabasa ng Biblia<br/>Kailangan din.<br/>',NULL,41469,7);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41470,8);
INSERT INTO stanza VALUES('T612','5','Kung Salita''y babasahin<br/>Diyos ay hipuin;<br/>Kung ''spiritu''y di gamitin,<br/>Patay pa rin.<br/>',NULL,41471,9);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41472,10);
INSERT INTO stanza VALUES('T612','6','Anong yaman at l''walhati,<br/>Kaugnay ang Diyos!<br/>Kanyang pinakamabuti,<br/>Aking lubos.<br/>',NULL,41473,11);
INSERT INTO stanza VALUES('T612','chorus','Yaman ng Ama at Anak<br/>Sa Espiritu;<br/>Gamit ko''y espiritu nang<br/>Siya''y mahipo.<br/>',NULL,41474,12);
INSERT INTO stanza VALUES('T614','1','Ilapit Mo ako, O Diyos, sa Iyo;<br/>Sukdan ang krus ay papasanin ko,<br/>Aawitin pa rin: malapit, Diyos, sa Iyo,<br/>Malapit nga sa Iyo, O Diyos, sa Iyo.<br/>',NULL,41475,1);
INSERT INTO stanza VALUES('T614','2','Sa paggala, araw ay lumubog,<br/>Inunan ang bato sa pagtulog,<br/>Sa panaginip din: malapit, Diyos, sa Iyo,<br/>Malapit nga sa Iyo, O Diyos, sa Iyo.<br/>',NULL,41476,2);
INSERT INTO stanza VALUES('T614','3','Tanawin ko doon kalangitan,<br/>Kaloob galing sa kahabagan;<br/>Anghel kumakayag: lumapit, Diyos, sa Iyo,<br/>Malapit nga sa Iyo, O Diyos, sa Iyo.<br/>',NULL,41477,3);
INSERT INTO stanza VALUES('T614','4','Payapang paggising, puri''y lubos,<br/>Batong inunan ko''y bahay ng Diyos;<br/>Lahat ng dinanas: palapit, Diyos, sa Iyo,<br/>Malapit nga sa Iyo, O Diyos, sa Iyo.<br/>',NULL,41478,4);
INSERT INTO stanza VALUES('T616','1','Sa paglubog ng araw,<br/>At langit ma''y humimlay,<br/>Sumamba ka''t maghintay<br/>Munting ilaw sisilay<br/>Sa magdamag.<br/>',NULL,41479,1);
INSERT INTO stanza VALUES('T616','chorus','Banal, banal, banal<br/>Diyos ng Hukbo!<br/>Langit, lupa''y puspos Mo,<br/>Nagpupuri sa I-yo!<br/>Kay tayog Mo!<br/>',NULL,41480,2);
INSERT INTO stanza VALUES('T616','2','Sa buong sansinukob,<br/>Ang hangad ko''y mukha Mo,<br/>Sa paligid nais ko,<br/>Makita l''walhati Mo,<br/>Kay lapit Mo.<br/>',NULL,41481,3);
INSERT INTO stanza VALUES('T616','chorus','Banal, banal, banal<br/>Diyos ng Hukbo!<br/>Langit, lupa''y puspos Mo,<br/>Nagpupuri sa I-yo!<br/>Kay tayog Mo!<br/>',NULL,41482,4);
INSERT INTO stanza VALUES('T616','3','Nang gabi''y lumalalim<br/>Puso ko''y nananabik,<br/>Sa l''walhati''t biyaya,<br/>Ang mukha Mo''y makita,<br/>Ng puso nga!<br/>',NULL,41483,5);
INSERT INTO stanza VALUES('T616','chorus','Banal, banal, banal<br/>Diyos ng Hukbo!<br/>Langit, lupa''y puspos Mo,<br/>Nagpupuri sa I-yo!<br/>Kay tayog Mo!<br/>',NULL,41484,6);
INSERT INTO stanza VALUES('T618','1','Sa malayong burol, mayroong lumang krus,<br/>Tanda ng dusa''t kahih''yan,<br/>Ibig ko ang krus, Mahal doo''y namatay<br/>Para sa makasalanan.<br/>',NULL,41485,1);
INSERT INTO stanza VALUES('T618','chorus','Iibigin ko ang lumang krus,<br/>Hanggang karangala''y maiwan;<br/>Kakapit ako sa lumang krus,<br/>Sa hinaharap maputungan.<br/>',NULL,41486,2);
INSERT INTO stanza VALUES('T618','2','Magaspang, lumang krus, hinamak ng mundo,<br/>Lubhang binighani ako;<br/>Langit ay iniwan ng Kordero ng Diyos,<br/>Krus pinasan sa Kalbaryo.<br/>',NULL,41487,3);
INSERT INTO stanza VALUES('T618','chorus','Iibigin ko ang lumang krus,<br/>Hanggang karangala''y maiwan;<br/>Kakapit ako sa lumang krus,<br/>Sa hinaharap maputungan.<br/>',NULL,41488,4);
INSERT INTO stanza VALUES('T618','3','Sa magaspang na krus, may bahid ng dugo,<br/>Kagandaha''y makikita;<br/>Doon nga si Hesus nagdusa''t namatay,<br/>Ako''y napawalang-sala.<br/>',NULL,41489,5);
INSERT INTO stanza VALUES('T618','chorus','Iibigin ko ang lumang krus,<br/>Hanggang karangala''y maiwan;<br/>Kakapit ako sa lumang krus,<br/>Sa hinaharap maputungan.<br/>',NULL,41490,6);
INSERT INTO stanza VALUES('T619','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41491,1);
INSERT INTO stanza VALUES('T619','1','Krus aking ipagmapuri<br/>Laging nananatili;<br/>Salaysay ng kabanalan,<br/>Krus ang pinalibutan.<br/>',NULL,41492,2);
INSERT INTO stanza VALUES('T619','2','Nang makasumpong ng hirap,<br/>Pag-asa''y naging hungkag;<br/>Krus ni Kristo di lilisan,<br/>O, may kapayapaan.<br/>',NULL,41493,3);
INSERT INTO stanza VALUES('T619','3','Nang araw lumiliwanag,<br/>Sa daan sumisinag;<br/>Liwanag sa krus ni Kristo,<br/>Liwanag sa buhay ko.<br/>',NULL,41494,4);
INSERT INTO stanza VALUES('T619','4','Ginhawa, pagdurusa ko,<br/>Krus pinabanal ako;<br/>Dito''y payapang kay lawak,<br/>Nananatiling galak!<br/>',NULL,41495,5);
INSERT INTO stanza VALUES('T619','5','Krus aking ''pinagmalaki,<br/>Lagi ''tong nanatili;<br/>Natupad bagay dibino,<br/>Ang krus pa rin ang sentro.<br/>',NULL,41496,6);
INSERT INTO stanza VALUES('T620','1','Krus laging nagwagi,<br/>Aleluya! aleluya!<br/>Kaaway nagapi,<br/>Aleluya! aleluya!<br/>Hades mabangis man,<br/>Mundo''y kaguluhan;<br/>Nguni''t krus di lilisan,<br/>Sa krus, mag-aleluya!<br/>',NULL,41497,1);
INSERT INTO stanza VALUES('T620','chorus','Aleluya, aleluya,<br/>Sa krus, mag-aleluya;<br/>Aleluya, aleluya,<br/>Krus, hindi man nagdusa.<br/>',NULL,41498,2);
INSERT INTO stanza VALUES('T620','2','Krus, na di natinag,<br/>Aleluya! aleluya!<br/>Lakas ibinigay,<br/>Aleluya! aleluya!<br/>Biyaya''y suminag,<br/>Kay Kristo na Anak;<br/>Katubusa''y ganap,<br/>Sa krus, mag-aleluya!<br/>',NULL,41499,3);
INSERT INTO stanza VALUES('T620','chorus','Aleluya, aleluya,<br/>Sa krus, mag-aleluya;<br/>Aleluya, aleluya,<br/>Krus, hindi man nagdusa.<br/>',NULL,41500,4);
INSERT INTO stanza VALUES('T620','3','Sa krus ay nagbayad,<br/>Aleluya! aleluya!<br/>Sala winakasan,<br/>Aleluya! aleluya!<br/>Umawit ukol kay<br/>Kristong ating alay,<br/>Kristong Haring buháy,<br/>Sa krus, mag-aleluya!<br/>',NULL,41501,5);
INSERT INTO stanza VALUES('T620','chorus','Aleluya, aleluya,<br/>Sa krus, mag-aleluya;<br/>Aleluya, aleluya,<br/>Krus, hindi man nagdusa.<br/>',NULL,41502,6);
INSERT INTO stanza VALUES('T622','1','Kung pinasan ang krus, matiis ba dusa!<br/>Kung dalhin ang krus, t''yak ating kamatayan!<br/>Kahulugan ng krus — tayo ay mapaslang;<br/>Ipako ang sarili krus maranasan.<br/>',NULL,41503,1);
INSERT INTO stanza VALUES('T622','2','Kaligtasan ng Diyos — pagpapako sa krus;<br/>Malupit na tuos, kalayaan lubos.<br/>Kung krus takasan Kristo''y di maging buhay;<br/>Kristo''y mahayag kung t''yak tayong mamatay.<br/>',NULL,41504,2);
INSERT INTO stanza VALUES('T622','3','Dulong layon ng krus, tupdin plano ng Diyos;<br/>Sarili ng tao ang kalaban ng Diyos.<br/>Buhay-kaluluwa ay dapat patayin,<br/>Nang Diyos makagawa ng Kanyang naisin.<br/>',NULL,41505,3);
INSERT INTO stanza VALUES('T623','1','Tangi lang may pakinabang<br/>Kung magkaro''n ng kawalan;<br/>Di tayo makaliligtas<br/>Tanging krus lamang ang landas;<br/>Kung di mamatay ang trigo<br/>Pa''nong mamumunga ito?<br/>Dapat ba ''kong mapag-isa<br/>Kung matatamo''y sanlaksa?<br/>',NULL,41506,1);
INSERT INTO stanza VALUES('T623','2','Ating kaluluwa''y tangan<br/>Ng lahat nitong tanganan;<br/>Alipi''y alipin pa rin<br/>Ginapos sa gintong kawing.<br/>Sa bagay na nais kamtin,<br/>Ito''y taling nang-alipin,<br/>Ito ma''y buhay, lupain,<br/>Singhalaga ng paningin.<br/>',NULL,41507,2);
INSERT INTO stanza VALUES('T623','3','Saanman ang iyong mamasdan,<br/>Tanim sa bukid hinog na;<br/>Bigkis nitong ginintuan,<br/>Sa Diyos winawagayway na.<br/>Ang ilang butil namatay,<br/>Ilang banal humingalay;<br/>May nagdusa at lumuha,<br/>Di bigong nakipagbaka.<br/>',NULL,41508,3);
INSERT INTO stanza VALUES('T624','1','Matinding krus Iyong pinasan,<br/>Diyos higit mong lalapitan;<br/>Kung walang krus sa labas mo,<br/>Wala ring Diyos sa loob mo.<br/>Sa lilim ng krus nilagak,<br/>May lugi nguni''t may galak.<br/>',NULL,41509,1);
INSERT INTO stanza VALUES('T624','2','Mabigat ang krus na pasan,<br/>Banal mas ang karilagan;<br/>Kung walang luhang didilig,<br/>Matutuyo''ng mga hardin;<br/>Ginto sa apoy — dalisay,<br/>Banal sa dusa''y subukan.<br/>',NULL,41510,2);
INSERT INTO stanza VALUES('T624','3','Nang bigat ng krus ay higit,<br/>Napalakas pananalig<br/>Piniga lamang na ubas,<br/>Makapagdaloy ng katas;<br/>Kung kabibe di-masaktan,<br/>Walang perlas makakamtan.<br/>',NULL,41511,3);
INSERT INTO stanza VALUES('T624','4','Mas mabigat krus na pasan,<br/>Ang panalangi''y puspusan;<br/>Kung langit maaliwalas,<br/>Mandaragat di magmatyag;<br/>At mga Salmo ni David,<br/>Di ba''t sa dusa''y naawit.<br/>',NULL,41512,4);
INSERT INTO stanza VALUES('T624','5','Pasaning krus mas bumigat,<br/>Paghahabol di naglikat;<br/>Nasubok na manlalakbay,<br/>Pahinga''y nais mataglay;<br/>Ibong hindi makadapo,<br/>Sa arka muling nagtungo.<br/>',NULL,41513,5);
INSERT INTO stanza VALUES('T624','6','Mas mabigat krus sa dati,<br/>Ang mamatay mas madali;<br/>Kung kalumaan tanggihan,<br/>Bagabag maiiwasan;<br/>Ating pagsampalataya<br/>Sa Kanya krus nagdakila.<br/>',NULL,41514,6);
INSERT INTO stanza VALUES('T624','7','Ikaw na Na''pako-sa-krus!<br/>Aking binabata ang krus.<br/>Mas matagal ang pagbata,<br/>Mas mahal, matamis nawa;<br/>Gayong puso bigyan ako,<br/>Hangga''t putong ay matamo.<br/>',NULL,41515,7);
INSERT INTO stanza VALUES('T626','1','''Pag di napiga''ng oliba,<br/>Langis ay wala;<br/>Alak man hindi makuha<br/>Sa ubas di napisa.<br/>Nardong kung kukuyumusin,<br/>Samyo''y kakalat;<br/>Ako''y di ba daraan din<br/>Sa nilaan Mong hirap?<br/>',NULL,41516,1);
INSERT INTO stanza VALUES('T626','chorus','Sa bawa''t dusa<br/>Ay pakinabang;<br/>Sa lugar na Iyong kinuha<br/>Kapalit Ikaw lamang.<br/>',NULL,41517,2);
INSERT INTO stanza VALUES('T626','2','Ibig Mo akong iunat<br/>Nang magkahimig?<br/>Upang tumamis ba''y dapat<br/>Magdusa sa pag-ibig?<br/>Kung kailan may kabiguan<br/>Pagsinta''y batid?<br/>Lugi''y di ko katakutan<br/>Kung Ikaw ay malapit.<br/>',NULL,41518,3);
INSERT INTO stanza VALUES('T626','chorus','Sa bawa''t dusa<br/>Ay pakinabang;<br/>Sa lugar na Iyong kinuha<br/>Kapalit Ikaw lamang.<br/>',NULL,41519,4);
INSERT INTO stanza VALUES('T626','3','Makaako na sarili<br/>Nakahihiya;<br/>Sa pag-ibig man nagdusa,<br/>Pilit man sundan Ka pa.<br/>Ayon sa Iyong kaluguran<br/>Sa ''kin gumawa;<br/>Di pansinin ang damdamin,<br/>Nais Mo ang gagawin.<br/>',NULL,41520,5);
INSERT INTO stanza VALUES('T626','chorus','Sa bawa''t dusa<br/>Ay pakinabang;<br/>Sa lugar na Iyong kinuha<br/>Kapalit Ikaw lamang.<br/>',NULL,41521,6);
INSERT INTO stanza VALUES('T626','4','Kung ang lungkot at galak Mo<br/>Sa ''ki''y di tugma,<br/>Kung sa ikalulugod Mo,<br/>Payag akong magdusa.<br/>Nasa ko ang Iyong ninasa,<br/>Mahirap man ''to,<br/>Sa Iyong l''walhati''t ligaya,<br/>Krus ma''y papasanin ko.<br/>',NULL,41522,7);
INSERT INTO stanza VALUES('T626','chorus','Sa bawa''t dusa<br/>Ay pakinabang;<br/>Sa lugar na Iyong kinuha<br/>Kapalit Ikaw lamang.<br/>',NULL,41523,8);
INSERT INTO stanza VALUES('T626','5','Kahit man ang aking awit<br/>Kahalo''y tangis,<br/>Ako sa Iyo magpupuri,<br/>Ikaw ay anong tamis!<br/>Higit ngang mahalaga Ka<br/>Sa lahat-lahat;<br/>''Ko''y bawasan, dumagdag Ka,<br/>Ang dalangin kong tapat.<br/>',NULL,41524,9);
INSERT INTO stanza VALUES('T626','chorus','Sa bawa''t dusa<br/>Ay pakinabang;<br/>Sa lugar na Iyong kinuha<br/>Kapalit Ikaw lamang.<br/>',NULL,41525,10);
INSERT INTO stanza VALUES('T628','1','Betlehem, ating lakaran<br/>Puso''y sa Diyos ''tinakda;<br/>Kay Hesus ay natututo,<br/>Habang pisngi''y may luha;<br/>''Pagka''t kwadra at sabsaban<br/>Di maganda sa mata,<br/>Nguni''t susunod kay Hesus,<br/>Kung gusto''y gantimpala.<br/>',NULL,41526,1);
INSERT INTO stanza VALUES('T628','2','Nazaret ang daraanan,<br/>Kumikitid nang lalo;<br/>Di agad maunawaan,<br/>Nguni''t Diyos nagtuturo;<br/>Na lingkod ay di hihigtan<br/>Ang Poon niya, na noo''y<br/>Nagkubli sa mundong gloria,<br/>Magdusa ma''y, sundan Siya!<br/>',NULL,41527,2);
INSERT INTO stanza VALUES('T628','3','Sa Galilea Siya''y masdan:<br/>Binato at ''sinumpa;<br/>Mali kaya Kanyang daan?<br/>Bakit labis hirap Niya?<br/>Di mali, mapayapa Siya,<br/>Bakong daan atin din<br/>Lalakaran nang gaya Niya,<br/>Layuni''y di mabimbin.<br/>',NULL,41528,3);
INSERT INTO stanza VALUES('T628','4','Kasunod sa Getsemani,<br/>Labis Siyang pinighati;<br/>Hukbo ng Diyablo''y nang-api,<br/>Kay lagim na paligid.<br/>Tayo ma''y natisod dili,<br/>Mga anghel nagsabi,<br/>"Mahal, masdan ang l''walhati,<br/>Labanan ay maikli."<br/>',NULL,41529,4);
INSERT INTO stanza VALUES('T628','5','Sa Krus! sa daang Kalbaryo,<br/>Ang kalul''wa''y tutungo;<br/>Kasama sa kahihiyan,<br/>Siyang tangi lamang daan.<br/>"Kung magdusang kasama Niya,"<br/>Sandaling oras na lang;<br/>Ang pighati''y mapapawi<br/>Sa l''walhati Niyang ngiti!<br/>',NULL,41530,5);
INSERT INTO stanza VALUES('T628','6','Sa libingan, may pagtangis,<br/>Buhay ay tumakas na,<br/>(Kamanlalakbay, tinuring<br/>Kang patay ng mundo ba?)<br/>Tayo''y babangong kasama<br/>Ni Hesus na mamuhay;<br/>Masayang tatalikuran,<br/>''Tinuring nilang buhay.<br/>',NULL,41531,6);
INSERT INTO stanza VALUES('T628','7','Sulong! at doon magningning,<br/>Palapit bawa''t araw,<br/>Banal na lunsod, kay ganda;<br/>Atin nang natatanaw;<br/>Dinggin ang mayuming himig<br/>Tinatanggap tayo Niya,<br/>Upang iluklok sa trono<br/>Do''n sa kaharian Niya.<br/>',NULL,41532,7);
INSERT INTO stanza VALUES('T628','8','Malapit na ginigiliw!<br/>Di na sasakit paa;<br/>Wala nang sala at luha,<br/>Maghunos, pumayapa;<br/>Matamis ang pagbulong Niya,<br/>"Huwag manghina''t matakot,<br/>Marahil bago magbukas,<br/>Lakbay ay matatapos!"<br/>',NULL,41533,8);
INSERT INTO stanza VALUES('T630','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41534,1);
INSERT INTO stanza VALUES('T630','1','Daan ng Krus ay sakripisyo,<br/>Ihandog lahat sa Diyos,<br/>Sa dambana ilatag ang lahat mo—<br/>Tutupuking lubos.<br/>',NULL,41535,2);
INSERT INTO stanza VALUES('T630','chorus','Tatahakin mo ba? Ito''y daan ng Krus!<br/>Papasanin mo ang Krus kaya?<br/>Ikaw na nag-alay lahat sa Diyos,<br/>Sa Diyos ay tapat ka ba?<br/>',NULL,41536,3);
INSERT INTO stanza VALUES('T630','2','Sa awit at dalangi''y handa<br/>Magbigay nang lubusan;<br/>Nguni''t mas mabigat ang krus ng dusa,<br/>At hirap sa daan.<br/>',NULL,41537,4);
INSERT INTO stanza VALUES('T630','chorus','Tatahakin mo ba? Ito''y daan ng Krus!<br/>Papasanin mo ang Krus kaya?<br/>Ikaw na nag-alay lahat sa Diyos,<br/>Sa Diyos ay tapat ka ba?<br/>',NULL,41538,5);
INSERT INTO stanza VALUES('T630','3','Maging lilo ka o matapat,<br/>Mamatay at mawalan,<br/>Managana ang buhay ni Kristo at<br/>Ika''y mapuspusan?<br/>',NULL,41539,6);
INSERT INTO stanza VALUES('T630','chorus','Tatahakin mo ba? Ito''y daan ng Krus!<br/>Papasanin mo ang Krus kaya?<br/>Ikaw na nag-alay lahat sa Diyos,<br/>Sa Diyos ay tapat ka ba?<br/>',NULL,41540,7);
INSERT INTO stanza VALUES('T630','4','Dapat mamatay nang mabuhay,<br/>Kaisa mo si Kristo<br/>Sa kamatayan at sa Kanyang buhay,<br/>Siya''ng ipahayag mo.<br/>',NULL,41541,8);
INSERT INTO stanza VALUES('T630','chorus','Tatahakin mo ba? Ito''y daan ng Krus!<br/>Papasanin mo ang Krus kaya?<br/>Ikaw na nag-alay lahat sa Diyos,<br/>Sa Diyos ay tapat ka ba?<br/>',NULL,41542,9);
INSERT INTO stanza VALUES('T630','5','Di mahalaga lugi, tubo,<br/>Layon ng Diyos ingatan,<br/>Ituring ang lahat na sukal sa iyo,<br/>Di Siya mahadlangan.<br/>',NULL,41543,10);
INSERT INTO stanza VALUES('T630','chorus','Tatahakin mo ba? Ito''y daan ng Krus!<br/>Papasanin mo ang Krus kaya?<br/>Ikaw na nag-alay lahat sa Diyos,<br/>Sa Diyos ay tapat ka ba?<br/>',NULL,41544,11);
INSERT INTO stanza VALUES('T631','1','Lakas pagkabuhay-muli<br/>Upang aking kilanlin;<br/>Dapat Krus aking ibigin,<br/>Lugi''y aking tanggapin.<br/>',NULL,41545,1);
INSERT INTO stanza VALUES('T631','chorus','Kung di mamatay,<br/>Wala ngang buhay;<br/>Mula lang sa kamatayan,<br/>Babangon buhay.<br/>',NULL,41546,2);
INSERT INTO stanza VALUES('T631','2','Kristo''y maihubog sa ''kin<br/>Ako''y dapat tapusin;<br/>Buhay sa Krus manatili,<br/>Kaluluwa''y patayin.<br/>',NULL,41547,3);
INSERT INTO stanza VALUES('T631','chorus','Kung di mamatay,<br/>Wala ngang buhay;<br/>Mula lang sa kamatayan,<br/>Babangon buhay.<br/>',NULL,41548,4);
INSERT INTO stanza VALUES('T631','3','Walang hanggang Espiritu<br/>Gamit ng Diyos pagpako;<br/>Sa ''kin kalakip ni Kristo<br/>Nang buhay Niya''y mabubo.<br/>',NULL,41549,5);
INSERT INTO stanza VALUES('T631','chorus','Kung di mamatay,<br/>Wala ngang buhay;<br/>Mula lang sa kamatayan,<br/>Babangon buhay.<br/>',NULL,41550,6);
INSERT INTO stanza VALUES('T634','1','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay,<br/>Ngayo''t kailanman.<br/>Di lakas ng tao,<br/>Di kabantugan,<br/>Magtagumpay tayo<br/>Sa Kanyang ngalan.<br/>',NULL,41551,1);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41552,2);
INSERT INTO stanza VALUES('T634','2','Di rangya at gilas,<br/>Ni magpalalo,<br/>Makibaka tayo<br/>Na nakapako.<br/>Sa pamamagitan<br/>Ng dusa''t siil;<br/>Ating pagwagihan<br/>Subok, pagsupil.<br/>',NULL,41553,3);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41554,4);
INSERT INTO stanza VALUES('T634','3a','Mabait gayunman<br/>Tayo''y lalaban;<br/>Matapang subali''t<br/>May kaamuan.<br/>Nakahimlay habang<br/>May ginagawa,<br/>Malakas subali''t<br/>Laging mahina.<br/>',NULL,41555,5);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41556,6);
INSERT INTO stanza VALUES('T634','3b','Kimi subali''t may<br/>Lakas ng loob<br/>Nagtatamo habang<br/>Nagkakaloob.<br/>Kasama ni Hesus<br/>Tayo''y pinako,<br/>Kalakip ni Hesus<br/>Nabuhay tayo.<br/>',NULL,41557,7);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41558,8);
INSERT INTO stanza VALUES('T634','4','Mga saksi, tayo''y<br/>Pinaligiran;<br/>Apostol, propeta,<br/>Banal, kai-bigan.<br/>"Sulong" narinig ko<br/>Digma''y tumindi<br/>Una''y krus ni Kristo<br/>Hindi hihindi!<br/>',NULL,41559,9);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41560,10);
INSERT INTO stanza VALUES('T634','5','Tinahak ng Poon,<br/>Ating tahakin;<br/>Siya ang Anak ng Diyos,<br/>Kasama natin.<br/>Kutamaya''y handa<br/>Hanggang sukdulan,<br/>Tayo''y iaakyat<br/>At puputungan.<br/>',NULL,41561,11);
INSERT INTO stanza VALUES('T634','chorus','Krus ni Kristo''y una<br/>Sa ''ting labanan;<br/>Dito''y managumpay<br/>Ngayo''t kailanman.<br/>',NULL,41562,12);
INSERT INTO stanza VALUES('T635','1','Punong ubas ating tingnan,<br/>Ang buhay pagbulayan,<br/>Paligid ma''y pagdurusa,<br/>Yumayabong pa rin siya;<br/>Bulaklak di arugain<br/>Sa ilang yumabong din<br/>Sa landas ng kalituhan,<br/>Gumawa ng huwaran.<br/>',NULL,41563,1);
INSERT INTO stanza VALUES('T635','2','Bulaklak ng punong ubas,<br/>Munti''t walang l''walhati;<br/>Bagaman may kagandahan,<br/>Halos di masulyapan.<br/>Simula nang mamulaklak,<br/>Bulaklak naging bunga;<br/>Di na maipagmalaki,<br/>Bulaklak na mayumi.<br/>',NULL,41564,2);
INSERT INTO stanza VALUES('T635','3','Punong ubas nakabigkis;<br/>Paglago''y di sa nais;<br/>Pag mga sanga''y lumawig,<br/>Sa balag nakabigkis.<br/>Kumukuha ng pagkain,<br/>Sa mabatong lupain;<br/>Puno''y di makapipili,<br/>Walang takas sa pighati.<br/>',NULL,41565,3);
INSERT INTO stanza VALUES('T635','4','Ganda ng kasariwaan,<br/>Yumayabong sa parang.<br/>Sa buhay ay nagmumula<br/>Saganang pamumunga.<br/>Sangang may kasariwaan,<br/>Tunay na lumago na,<br/>Sa bughaw na kalangitan<br/>Ang simoy ay tamasa.<br/>',NULL,41566,4);
INSERT INTO stanza VALUES('T635','5','Panginoon ng ubasan<br/>Di lang may kabutihan,<br/>Aalisin kapurihan<br/>Dahil may kayabungan.<br/>Di pansin kasariwaan,<br/>Kundi sa paglilinis,<br/>Puno ay inaalisan,<br/>Sanga''y may kagandahan.<br/>',NULL,41567,5);
INSERT INTO stanza VALUES('T635','6','Sa oras ng kalugihan,<br/>Sarili''y kaawaan?<br/>Sa sumusugat na kamay<br/>Sarili iaalay.<br/>Sanga ay may kagandahan,<br/>Inaalis ng kamay,<br/>Upang buhay di masayang,<br/>Pamumunga''y ingatan.<br/>',NULL,41568,6);
INSERT INTO stanza VALUES('T635','7','Naging matigas na kahoy<br/>Bawa''t usbong tumubo,<br/>Bawa''t nanatiling sanga,<br/>Kay sagana ng bunga.<br/>Sa nakapapasong araw,<br/>Dahon ay nalalanta;<br/>Higit paghinog ng bunga,<br/>Hanggang sa maani na.<br/>',NULL,41569,7);
INSERT INTO stanza VALUES('T635','8','Yumukod sa kayabungan<br/>Sangang hitik bumaba—<br/>Lumago sa pagdurusa,<br/>Pagputol may layon nga.<br/>Punong ubas masiyahan,<br/>Bunga''y hinog lubusan;<br/>Malapit na ang anihan,<br/>Lilipas kasayahan.<br/>',NULL,41570,8);
INSERT INTO stanza VALUES('T635','9','Pinitas at inapakan<br/>Ubas na anong yaman,<br/>Hanggang mula sa pisaan<br/>Alak may kapuspusan.<br/>Daloy nito ay patuloy,<br/>Ang alak na busilak,<br/>Malaya na dumadaloy,<br/>Lupa''y punô ng galak.<br/>',NULL,41571,9);
INSERT INTO stanza VALUES('T635','10','Ang anyo ng punong ubas<br/>Kawawa''t walang bunga;<br/>Ang lahat ay binigay niya,<br/>Sa dilim nagtungo pa.<br/>Sa alak na natamasa<br/>Walang gantimpala siya,<br/>Bagkus pinutulan pa nga<br/>Walang gayak at ganda.<br/>',NULL,41572,10);
INSERT INTO stanza VALUES('T635','11','Alak nito sa taglamig<br/>Dala''y tamis at init<br/>Sa mga nanganlalamig,<br/>Siil ng lungkot, pait.<br/>Punong ubas nag-iisa<br/>Sa gitna ng niebe pa,<br/>Bagama''t di matalastas,<br/>Kapalaran ay batá.<br/>',NULL,41573,11);
INSERT INTO stanza VALUES('T635','12','Taglamig ay lumipas na<br/>Naghahandang mamunga;<br/>Umuusbong, nagsasanga,<br/>Luntian, binihis na;<br/>Hindi siya naghihinaing<br/>Sa sakit ng taglamig,<br/>Ang sariwang paghahain<br/>Di nais na bawasin.<br/>',NULL,41574,12);
INSERT INTO stanza VALUES('T635','13','Langhap ang sariwang hangin,<br/>Mga sanga''y tinaas,<br/>Ubas di kayang punuin<br/>Ng maruming lupain.<br/>May pait man nakangiti,<br/>Sinaktan ng pag-ibig,<br/>Magbabatá na tila ba<br/>Di nagdanas ng dusa.<br/>',NULL,41575,13);
INSERT INTO stanza VALUES('T635','14','Mula sa sanga dumaloy<br/>Dagta, dugo at alak.<br/>Puno bang lahat dinusa,<br/>Mawalan, maghirap pa?<br/>Ang manginginom at gala,<br/>Uminom at nagsaya.<br/>Kanilang aliw, tamasa<br/>Maging mayaman kaya?<br/>',NULL,41576,14);
INSERT INTO stanza VALUES('T635','15','Nasusukat ating buhay<br/>Sa ating kalugihan;<br/>Di sa dami ng ininom,<br/>Kundi sa pinainom.<br/>Pag-ibig ay tumitibay,<br/>Sa haing tinataglay;<br/>Siyang labis na nagdusa ay<br/>May higit na binigay.<br/>',NULL,41577,15);
INSERT INTO stanza VALUES('T635','16','Siyang sarili''y hinigpitan,<br/>Tamo ng Diyos mainam;<br/>Siyang mahal ang binayaran,<br/>Sa iba''y kaaliwan.<br/>Ang di nagdusa kailanman,<br/>Tansong tumutunog lang;<br/>Siyang sarili''y tinanggihan,<br/>May higit kagalakan.<br/>',NULL,41578,16);
INSERT INTO stanza VALUES('T636','1','"Kung mamatay," ang mensahe<br/>Poon may sabi;<br/>"Kung mamatay" mamumunga,<br/>Nang marami nga.<br/>',NULL,41579,1);
INSERT INTO stanza VALUES('T636','2','Nais mong buhay gumawa,<br/>Dapat mamatay,<br/>Mamatay at malibing pa,<br/>Di na makita.<br/>',NULL,41580,2);
INSERT INTO stanza VALUES('T636','3','Sa dilim di ka iwanan,<br/>Mata''y ilawan;<br/>Sa bagong buhay at gloria,<br/>Ibangon ka Niya.<br/>',NULL,41581,3);
INSERT INTO stanza VALUES('T636','4','Buhay nais ibahagi,<br/>Landas igawi<br/>Daanan mo kamatayan,<br/>Siya''y masumpungan.<br/>',NULL,41582,4);
INSERT INTO stanza VALUES('T636','5','Mabubuhay namamatay,<br/>Lihim ngang tunay;<br/>Kapag buhay ibinuhos<br/>Ani ay lubos.<br/>',NULL,41583,5);
INSERT INTO stanza VALUES('T637','1','Kay Hesus "nawasak" na:<br/>May awit kaluluwa;<br/>Maliliit na bangka,<br/>Sa bagyo''y nangangamba;<br/>Di batid ang pahinga<br/>Ng mga "nawasak" na.<br/>',NULL,41584,1);
INSERT INTO stanza VALUES('T637','2','Himutok "nawasak na!"<br/>Ng bagyong puminsala,<br/>Sa ligtas na kalul''wa,<br/>Walang hanggang alaga;<br/>Walang makatitinag<br/>Sa pag-ibig na yakap.<br/>',NULL,41585,2);
INSERT INTO stanza VALUES('T637','3','"Nawasak na!" Hindi na<br/>Maglakbay barkong angkin;<br/>Gayunman lakbay pa rin,<br/>Walang hanggan ang angkla;<br/>Di na mag-aalala,<br/>Pagkapit ko sa Kanya.<br/>',NULL,41586,3);
INSERT INTO stanza VALUES('T637','4','Pakinabang — "Nawasak!"<br/>Sa iba nakagulat;<br/>Masungit man ang dagat,<br/>Biyaya Niya ay sapat;<br/>"Nawasak" nasa kamay,<br/>Ng Diyos na nagbabantay.<br/>',NULL,41587,4);
INSERT INTO stanza VALUES('T639','1','Kamataya''y hindi makapigil,<br/>Sa buhay ng pagkabuhay-muli;<br/>Ito''y di-nilikhang buhay ng Diyos,<br/>Ito''y si Kristo, buhay nagwagi.<br/>',NULL,41588,1);
INSERT INTO stanza VALUES('T639','2','Kamataya''y hindi makapigil,<br/>Kahit lahat niyang lakas itanyag;<br/>Binigyan lamang pagkakataon<br/>Ang pagkabuhay lalong mahayag.<br/>',NULL,41589,2);
INSERT INTO stanza VALUES('T639','3','Di masupil — pagkabuhay-muli,<br/>Kung ilibing lalong lalaganap;<br/>Lahat ng dusa''y nagpapalago,<br/>Nagpapabunga, sagana''t ganap.<br/>',NULL,41590,3);
INSERT INTO stanza VALUES('T639','4','Di masupil — pagkabuhay-muli,<br/>Giniba niya ang lahat ng hadlang,<br/>Karimlan at Hades ay dinaig,<br/>At nilipol yaring kamatayan.<br/>',NULL,41591,4);
INSERT INTO stanza VALUES('T639','5','Di masupil — pagkabuhay-muli,<br/>Kapuspusan ng Diyos inihayag;<br/>Kat''wiran, kabanala''y binunga,<br/>Mal''walhating wangis ibinunyag.<br/>',NULL,41592,5);
INSERT INTO stanza VALUES('T639','6','Nawa''y malaman ko''ng pagkabuhay,<br/>Sa kamatayan siyang ipaglaban,<br/>Walang iba kundi Kristong buhay,<br/>Pagkabuhay sa ''king karanasan.<br/>',NULL,41593,6);
INSERT INTO stanza VALUES('T640','1','Buhay mula sa kamatayan, Poon<br/>Ngayon o darating na panahon,<br/>Bakit pa mag-antala basagin na,<br/>Sisidlan sa kamay Niya''y mahulma.<br/>',NULL,41594,1);
INSERT INTO stanza VALUES('T640','2','Binhing inihasik sa kahinaan,<br/>Ibinangon sa kapangyarihan;<br/>Ipinamuhay sa dusa buhay Mo<br/>Hindi na ako kundi si Kristo.<br/>',NULL,41595,2);
INSERT INTO stanza VALUES('T640','3','Buhay mula sa kamatayang daan,<br/>Tahak nilang sa Krus kumilala;<br/>Kay Hesus lamang pagsasalamuha,<br/>Natamo''y tinuring kalugihan.<br/>',NULL,41596,3);
INSERT INTO stanza VALUES('T640','4','Ang pag-aatas na may pagpapala,<br/>Buhay sa kamatayan nagmula;<br/>Dala''y bukal ng buhay masagana,<br/>Di na ka-i-langang mauhaw pa!<br/>',NULL,41597,4);
INSERT INTO stanza VALUES('T643','1','Panahon ilaan,<br/>Pangino''n tingnan;<br/>Manahan sa Kanya,<br/>Ka''nin Salita;<br/>Pasakop, maamo<br/>Sa presensya Mo,<br/>Pagpala''y hanapin,<br/>Di lilimutin.<br/>',NULL,41598,1);
INSERT INTO stanza VALUES('T643','2','Panahon ilaan,<br/>Pangino''n tingnan;<br/>Maraming gawain,<br/>Siya''y katagpuin.<br/>Pagtingin kay Hesus<br/>Matransporma ka.<br/>Masdan sa iyong kilos,<br/>Maging wangis Niya.<br/>',NULL,41599,2);
INSERT INTO stanza VALUES('T643','3','Panahon ilaan,<br/>Pangino''n tingnan;<br/>Mangyaring anuman,<br/>Giya Siya''t sundan.<br/>Panginoon sundan,<br/>Tamis, pait man;<br/>Sa Kanyang Salita<br/>Ay magtiwala.<br/>',NULL,41600,3);
INSERT INTO stanza VALUES('T643','4','Panahon ilaan,<br/>Pangino''n tingnan,<br/>Bawa''t kilos, gawa,<br/>Siyang mamahala;<br/>Sa pag-ibig-bukal,<br/>''Spiritu''y gabay;<br/>Magiging angkop ka,<br/>Sa Kanyang awa.<br/>',NULL,41601,4);
INSERT INTO stanza VALUES('T645','1','Kalul''wang hapo at bagabag,<br/>Liwanag walang makita;<br/>''Pag tingin sa Tagapagligtas,<br/>May ilaw, buhay sagana.<br/>',NULL,41602,1);
INSERT INTO stanza VALUES('T645','chorus','Mata''y ''baling kay Hesus<br/>Masdan mukha Niyang kay ganda,<br/>Panlupang bagay lalabong lubos<br/>Sa Kanyang l''walhati''t biyaya.<br/>',NULL,41603,2);
INSERT INTO stanza VALUES('T645','2','Sa dinanas Niyang kamatayan<br/>Sundan Siya tungo sa buhay;<br/>Wala ng habol kasalanan<br/>Higit pa sa matagumpay.<br/>',NULL,41604,3);
INSERT INTO stanza VALUES('T645','chorus','Mata''y ''baling kay Hesus<br/>Masdan mukha Niyang kay ganda,<br/>Panlupang bagay lalabong lubos<br/>Sa Kanyang l''walhati''t biyaya.<br/>',NULL,41605,4);
INSERT INTO stanza VALUES('T645','3','Hindi bibigo Salita Niya<br/>Sa Kanya ay manalig ka;<br/>Humayo sa magulong mundo<br/>Kaligtasan ''patotoo.<br/>',NULL,41606,5);
INSERT INTO stanza VALUES('T645','chorus','Mata''y ''baling kay Hesus<br/>Masdan mukha Niyang kay ganda,<br/>Panlupang bagay lalabong lubos<br/>Sa Kanyang l''walhati''t biyaya.<br/>',NULL,41607,6);
INSERT INTO stanza VALUES('T648','1','Kawal ka ni Kristo,<br/>Ika''y namuno,<br/>Dati''y nagpalalo,<br/>Kaya''t natalo;<br/>Kay Kristo umasa,<br/>Huwag sa sarili mo,<br/>Lahat, iyong magagawa<br/>Sa nagpalakas sa iyo.<br/>',NULL,41608,1);
INSERT INTO stanza VALUES('T648','2','Sa iyong paglilingkod<br/>Sa katuwiran,<br/>Di ka ba napagod?<br/>At nabigatan?<br/>Ika''y magtiwala<br/>Sa Manliligtas mo,<br/>Lahat, iyong magagawa<br/>Sa nagpalakas sa iyo.<br/>',NULL,41609,2);
INSERT INTO stanza VALUES('T648','3','Kung bagot sa daan,<br/>''Tulungan ka Niya,<br/>Nagagalak ka man<br/>O nagdurusa;<br/>Apoy man o baha—<br/>Mapanaigan mo,<br/>Lahat, iyong magagawa<br/>Sa nagpalakas sa iyo.<br/>',NULL,41610,3);
INSERT INTO stanza VALUES('T648','4','Sa magulong mundo,<br/>Kalat ang tukso,<br/>Kung tututulan mo,<br/>Diyablo''y tatakbo;<br/>Wala na siyang bisa<br/>Kung ipahayag mo,<br/>Lahat, iyong magagawa<br/>Sa nagpalakas sa iyo.<br/>',NULL,41611,4);
INSERT INTO stanza VALUES('T648','5','Ang lakas ni Kristo<br/>Hindi masukat,<br/>Mag-iingat sa iyo<br/>Sa lahat-lahat;<br/>Sapat Niyang biyaya<br/>Lumulukob sa iyo,<br/>Lahat, iyong magagawa<br/>Sa nagpalakas sa iyo.<br/>',NULL,41612,5);
INSERT INTO stanza VALUES('T656','1','"Bulayin Siya," Kristo iyong tularan<br/>Alamin na ika''y hinawakan;<br/>Kabahagi ka sa Kanyang buhay<br/>Upang Kanyang wangis iyong isilay.<br/>',NULL,41613,1);
INSERT INTO stanza VALUES('T656','2','"Bulayin Siya"; gawin araw-araw<br/>Sa katayugan huwag kang masilaw;<br/>Ang walang hanggang buhay kilanlin<br/>Kamatayan ni Kristo''y danasin.<br/>',NULL,41614,2);
INSERT INTO stanza VALUES('T656','3','"Bulayin Siya," buong buhay gawin<br/>Mamuhay ka sa loob ng tabing;<br/>Kapag itakwil ang iyong sarili,<br/>Mapasa iyo layang mal''walhati.<br/>',NULL,41615,3);
INSERT INTO stanza VALUES('T656','4','"Bulayin Siya," gayon nga buhay mo<br/>May kadalisayan, sakripisyo;<br/>Gagawa pa ang Diyos sa loob mo,<br/>Kristo sa iyo''y makita ng tao.<br/>',NULL,41616,4);
INSERT INTO stanza VALUES('T656','5','"Bulayin Siya," sa i-yong takbuhin,<br/>Lagi sa mukha Niya nakatingin,<br/>Gayon ikaw Kanyang transpormahin;<br/>Hanggang wangis ni Kristo''y tamuhin.<br/>',NULL,41617,5);
INSERT INTO stanza VALUES('T657','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41618,1);
INSERT INTO stanza VALUES('T657','1','Sa Panginoon ba''y<br/>Masunurin ka?<br/>Kahit langit, lupa''y<br/>Pawang magiba?<br/>Manampalataya,<br/>Kahit may dusa?<br/>Kay Kristo''y umasa<br/>Di mapahiya.<br/>',NULL,41619,2);
INSERT INTO stanza VALUES('T657','2','Masunurin ba sa<br/>Paglilingkod mo?<br/>Di ka mangangamba,<br/>Di ka liliko?<br/>Kahit ang hakbang mo<br/>Ay kamatayan,<br/>Hindi ka susuko,<br/>Sumunod lamang?<br/>',NULL,41620,3);
INSERT INTO stanza VALUES('T657','3','Sa Pinuno mo ba''y<br/>Masunurin ka?<br/>Kung sa pagsalakay<br/>Ika''y manguna?<br/>Malugod, handa ba<br/>Sumugod lagi?<br/>Makikipagbaka<br/>Hanggang magwagi?<br/>',NULL,41621,4);
INSERT INTO stanza VALUES('T657','4','Kapatid, si Kristo<br/>Ay naghihintay,<br/>Utos Niya''y sundin mo,<br/>Walang pagsuway.<br/>Kung mabuting kawal,<br/>Sa pagsapit Niya,<br/>Sa iyo maggagawad,<br/>Kung "tapat ka!" nga.<br/>',NULL,41622,5);
INSERT INTO stanza VALUES('T659','1','Mangagalak sa ating Panginoon,<br/>Kinalag Niya''ng mga gapos,<br/>Ako''y malaya, tinubos ng dugo,<br/>Si Hesus ay aking lubos.<br/>',NULL,41623,1);
INSERT INTO stanza VALUES('T659','chorus','Kung Diyos ay atin,<br/>Kung Diyos ay atin,<br/>Kung Diyos ay atin,<br/>Sino ang kalaban? Sino nga?<br/>Sino ang kinatatakutan?<br/>',NULL,41624,2);
INSERT INTO stanza VALUES('T659','2','Magmalakas sa ating Panginoon,<br/>Mangagalak sa lakas Niya;<br/>Kung tayo''y tapat sa katotohanan,<br/>Siyang maging lakas at kuta.<br/>',NULL,41625,3);
INSERT INTO stanza VALUES('T659','3','Manalig sa Salita''t pangako Niya,<br/>Kay Kristo''y pawang "Siya Nawa";<br/>Mundo ma''y lumipas, ang Salita Niya<br/>Tiyak mananatili pa.<br/>',NULL,41626,5);
INSERT INTO stanza VALUES('T659','4','Manatili sa ating Panginoon,<br/>Sa Kanyang kapangyarihan;<br/>At mula sa kamay ng Panginoon<br/>Di maaagaw ninuman.<br/>',NULL,41627,7);
INSERT INTO stanza VALUES('T660','1','Huwag kang mabalisa, Poon malapit,<br/>Huwag matinag sa pangako''y manalig;<br/>Di ka dapat matisod ni mabigo,<br/>Baka ngayon na ang dating ni Kristo.<br/>',NULL,41628,1);
INSERT INTO stanza VALUES('T660','2','Huwag kang mabalisa, magtiwala ka,<br/>Sala mo''y pasan Niya, lungkot lalo na;<br/>Maging malaya''t magpatotoo ka<br/>Anong lakas Niya''t puspos ng pagsinta.<br/>',NULL,41629,2);
INSERT INTO stanza VALUES('T660','3','Huwag mabalisa, kung maantala Siya,<br/>Lakas Niya''y iyong tustos, laging kasama;<br/>Bisig Niya''t Espiritu, iyong sandalan,<br/>Huwag mangamba ''pagkat Siya''y maasahan.<br/>',NULL,41630,3);
INSERT INTO stanza VALUES('T662','1','"Layon ay habulin!"<br/>Kahit iisa rin;<br/>Tumawag, daa''y binuksan,<br/>Mangamba''y huwag naman!<br/>',NULL,41631,1);
INSERT INTO stanza VALUES('T662','2','"Layon ay habulin!"<br/>Sa iyo''y tumitingin,<br/>Mga matang gayang apoy,<br/>Ang iba''y itaboy.<br/>',NULL,41632,2);
INSERT INTO stanza VALUES('T662','3','"Layon ay habulin!"<br/>Sa harap tumingin,<br/>''Pagka''t putong naghihintay,<br/>Sa iyong magtagumpay.<br/>',NULL,41633,3);
INSERT INTO stanza VALUES('T662','4','"Layon ay habulin!"<br/>Bulag ma''t bingi rin,<br/>Sa daang may tandang dugo,<br/>Habulin si Kristo.<br/>',NULL,41634,4);
INSERT INTO stanza VALUES('T663','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41635,1);
INSERT INTO stanza VALUES('T663','1','" Sulong!" hudyat natin,<br/>Sabay lakarin;<br/>Layon ay harapin,<br/>Walang lingunin;<br/>Nanguna sa hukbo,<br/>Haliging apoy;<br/>Huwag mag-alinlangan,<br/>Una''y Kapitan.<br/>Sumulong sa ilang,<br/>Makipaglaban,<br/>Kita ng Canaan,<br/>Ang Sion daratnan.<br/>',NULL,41636,2);
INSERT INTO stanza VALUES('T663','2','L''walhati''t l''walhati,<br/>Handa ng Ama;<br/>Mayroong bahagi<br/>Ang minahal Siya.<br/>Mata''y di nakita,<br/>Di pa narinig,<br/>Handa Niyang sagana,<br/>Di pa naisip.<br/>Sulong, sulong hanggang<br/>Sa kaharian,<br/>Dating inasahan<br/>Ay katunayan.<br/>',NULL,41637,3);
INSERT INTO stanza VALUES('T663','3','Sulong, malapit na<br/>Ang kaharian;<br/>Iyong matatamasa<br/>Ang kabaguhan.<br/>Putong mal''walhati<br/>Ating makamtan,<br/>Kasama ni Kristo<br/>Na maghahari.<br/>Sulong! Iyong tapusin<br/>Ang paglalakbay,<br/>Lakas Niya''y gamitin,<br/>Magtatagumpay.<br/>',NULL,41638,4);
INSERT INTO stanza VALUES('T666','1','Patapos na ang gabi,<br/>Magbantay mabuti;<br/>Ang mundo''y huwag hanapin,<br/>Huwag aantukin!<br/>Panginoo''y darating<br/>Magbantay at gising:<br/>Paghihintay sa Kanya,<br/>Huwag magpabaya.<br/>',NULL,41639,1);
INSERT INTO stanza VALUES('T666','2','Magbantay at maglingkod,<br/>Hindi maghimagod;<br/>Magbantay at magpagal,<br/>Di magtatagal.<br/>Magbantay, magsandata,<br/>Upang maging handa;<br/>''Spiritu palakasin,<br/>Diyablo''y gapiin.<br/>',NULL,41640,2);
INSERT INTO stanza VALUES('T666','3','Magbantay sa pagdating,<br/>Manliligtas natin;<br/>Habuling Kaharian,<br/>Kahit masaktan.<br/>Magbantay, laging gising,<br/>Gabing tatapusin,<br/>Hahayag l''walhati Niya,<br/>Siya''y babalik na.<br/>',NULL,41641,3);
INSERT INTO stanza VALUES('T671','1','Sa kailaliman ng Iyong Ngalan,<br/>Tatahan ako sa kasiyahan;<br/>Gaano man ang tagal ng araw,<br/>O dilim ng gabi; sapat Ikaw.<br/>',NULL,41642,1);
INSERT INTO stanza VALUES('T671','2','Ang aking Diyos, ang Sapat-sa-lahat,<br/>Sa kulang ko tustos Niya ay sapat;<br/>Sinabog ng malakas Mong kamay,<br/>Mahimalang pag-ibig, alaga.<br/>',NULL,41643,2);
INSERT INTO stanza VALUES('T671','3','Lagi akong titiwala sa Iyo,<br/>Muling hihilig ''ko sa dibdib Mo;<br/>Doon sasambahin Iyong paraan,<br/>Sa pananalig, kapahingahan.<br/>',NULL,41644,3);
INSERT INTO stanza VALUES('T674','1','Para sa iyo''y may planong lihim,<br/>Tuon ka ng paglingap Ko;<br/>Diyos ang umuugit sa iyo,<br/>Laban sa bitag ng tuso.<br/>',NULL,41645,1);
INSERT INTO stanza VALUES('T674','2','May planong lihim para sa iyo,<br/>Tiyak, di Siya mabibigo!<br/>Katapatan Niya''y himlayan,<br/>Tagumpay iyong makakamtan.<br/>',NULL,41646,2);
INSERT INTO stanza VALUES('T674','3','May planong lihim para sa iyo,<br/>Kanyang pagsintang totoo;<br/>Di nakita''t napakinggan,<br/>Nguni''t laang iyong subukan.<br/>',NULL,41647,3);
INSERT INTO stanza VALUES('T674','4','May planong lihim para sa iyo,<br/>Layunin Niya''y lahad sa iyo;<br/>Masalimuot lilinaw<br/>Obramaestra matatanaw.<br/>',NULL,41648,4);
INSERT INTO stanza VALUES('T674','5','Para sa iyo''y may planong lihim,<br/>Anak kang iningatan din;<br/>Tila para sa iyo lamang,<br/>Pag-ibig Niyang laang-laan.<br/>',NULL,41649,5);
INSERT INTO stanza VALUES('T679','1','Matiwasay sa bisig<br/>At dibdib ni Hesus;<br/>Sa lilim ng pag-ibig,<br/>Mapayapang lubos.<br/>Makalangit na himig<br/>Umaliw sa akin,<br/>Banal, laksan ang tinig,<br/>Hesus ay purihin.<br/>',NULL,41650,1);
INSERT INTO stanza VALUES('T679','chorus','Matiwasay sa bisig<br/>At dibdib ni Hesus;<br/>Sa lilim ng pag-ibig,<br/>Mapayapang lubos.<br/>',NULL,41651,2);
INSERT INTO stanza VALUES('T679','2','Matiwasay sa yapos<br/>At bisig ni Hesus;<br/>Sa biyaya Niya''y lipos,<br/>Sala''t mundo''y tapos.<br/>Bahagyang pagsubok pa<br/>At kaunting luha,<br/>Hirap, takot, at duda,<br/>Di makabalisa.<br/>',NULL,41652,3);
INSERT INTO stanza VALUES('T679','3','Matiwasay kay Hesus,<br/>Batong Walang hanggan,<br/>Ako''y kinubling lubos<br/>At tinutustusan.<br/>Dito ako maghintay<br/>Nang gabi''y lumipas,<br/>Hanggang bukang-liwayway,<br/>Sapat na ang oras.<br/>',NULL,41653,5);
INSERT INTO stanza VALUES('T684','1','Pumarito, kayong nangalulugmok,<br/>Sa trono ng habag ay dumulog;<br/>Pusong sawi''y dalhin, maging hinaing,<br/>Sa lungkot, langit magpapagaling.<br/>',NULL,41654,1);
INSERT INTO stanza VALUES('T684','2','Ilaw ng ligâw, sa hapis ay saya<br/>Sa nagsisisi''y puno''ng pag-asa;<br/>Mang-aaliw ay magiliw nagbigkas<br/>Sa lungkot, langit tunay na lunas.<br/>',NULL,41655,2);
INSERT INTO stanza VALUES('T684','3','Dito''y masdan ang Tinapay ng Buhay<br/>Mula trono, tubig na dalisay<br/>Sa piging ng pag-ibig, pumarito<br/>Sa lungkot, langit ang mag-aalo.<br/>',NULL,41656,3);
INSERT INTO stanza VALUES('T686','1','"Hu-wag kang mangamba<br/>Kasama kita."<br/>Liwanagan landas,<br/>Ng gloriang wagas;<br/>Sa ulap madilim,<br/>May pangako rin,<br/>"Di kita iiwan,<br/>Maging magpakailanman."<br/>',NULL,41657,1);
INSERT INTO stanza VALUES('T686','chorus','Di, hinding-hindi<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>Di, hinding-hindi;<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>',NULL,41658,2);
INSERT INTO stanza VALUES('T686','2','Rosas nalalanta,<br/>Namatay lila;<br/>Lupa man mapanglaw<br/>Langit may araw.<br/>Bulaklak alhena,*<br/>Namukadkad Siya;<br/>Hesus kailanman,<br/>Di ako iiwanan.<br/>',NULL,41659,3);
INSERT INTO stanza VALUES('T686','chorus','Di, hinding-hindi<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>Di, hinding-hindi;<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>',NULL,41660,4);
INSERT INTO stanza VALUES('T686','3','Kahit hinaharap,<br/>Sadyang mahirap;<br/>Nguni''t Manliligtas,<br/>Nagpapalakas.<br/>Galak ay pumasok,<br/>Sa aking puso,<br/>Di kita iiwan,<br/>Awit may katamisan.<br/>',NULL,41661,5);
INSERT INTO stanza VALUES('T686','chorus','Di, hinding-hindi<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>Di, hinding-hindi;<br/>Di, hinding-hindi;<br/>Siya''y nangakong ka-i-lanman<br/>Di ako iiwanan.<br/>',NULL,41662,6);
INSERT INTO stanza VALUES('T693','1','Walang palya, ''pagka''t Siya''y Diyos,<br/>Walang palya, b''yaya''y lubos;<br/>Walang palya, nangako na,<br/>Tayo''y may Diyos, ''nong pangamba?<br/>',NULL,41663,1);
INSERT INTO stanza VALUES('T693','2','May bundok na di mapatag?<br/>May di matawid na dagat?<br/>Ating Diyos sagot sa lahat—<br/>Diyos ng Imposibilidad!<br/>',NULL,41664,2);
INSERT INTO stanza VALUES('T693','3','Palakol na pinalutang,<br/>Araw na walang lubugan;<br/>Pulang Dagat naging kati,<br/>Gawa ng Diyos na maigi.<br/>',NULL,41665,3);
INSERT INTO stanza VALUES('T693','4','Buhangin naging hangganan,<br/>Maalon na karagatan;<br/>Siya ang Iyong Diyos, ano pa nga,<br/>Sa Iyo hindi Niya magawa?<br/>',NULL,41666,4);
INSERT INTO stanza VALUES('T693','5','Batid Niya Iyong suliranin<br/>Ikaw Kanyang mamahalin;<br/>Ating Diyos ay mahabagin,<br/>Hibik natin ay diringgin.<br/>',NULL,41667,5);
INSERT INTO stanza VALUES('T693','6','Ating Diyos kaliwanagan,<br/>Pangako''y di malimutan,<br/>Pangako Niya na kay Kristo,<br/>Pawang Amen, pawang Oo.<br/>',NULL,41668,6);
INSERT INTO stanza VALUES('T693','7','Diyos natin ay katapatan,<br/>Tipan Niya''y may katatagan;<br/>Nananalig humiling ka,<br/>Salita Niya''y di matatwa.<br/>',NULL,41669,7);
INSERT INTO stanza VALUES('T693','8','Walang palya ang ating Diyos<br/>Salita''y malinaw lubos,<br/>Kay buti ng biyaya Niya,<br/>''Pagkat Siya''y Diyos, walang palya!<br/>',NULL,41670,8);
INSERT INTO stanza VALUES('T694','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41671,1);
INSERT INTO stanza VALUES('T694','1','Sa ilalim ng pakpak Niya,<br/>Diyos Mo''y kakalinga;<br/>Sa anuman huwag mangamba<br/>Diyos Mo''y kakalinga.<br/>',NULL,41672,2);
INSERT INTO stanza VALUES('T694','chorus','Kakalinga sa iyo<br/>Bawa''t saglit, bawa''t dako;<br/>Diyos t''yak kakalinga,<br/>Sa iyo''y aalaga.<br/>',NULL,41673,3);
INSERT INTO stanza VALUES('T694','2','Bigung-bigo sa hirap nga,<br/>Diyos Mo''y kakalinga;<br/>Panganib kublihan wala,<br/>Diyos Mo''y kakalinga.<br/>',NULL,41674,4);
INSERT INTO stanza VALUES('T694','chorus','Kakalinga sa iyo<br/>Bawa''t saglit, bawa''t dako;<br/>Diyos t''yak kakalinga,<br/>Sa iyo''y aalaga.<br/>',NULL,41675,5);
INSERT INTO stanza VALUES('T694','3','Sa dalangin nakinig Siya,<br/>Diyos Mo''y kakalinga;<br/>Kailangan mo Siyang naghanda,<br/>Diyos Mo''y kakalinga.<br/>',NULL,41676,6);
INSERT INTO stanza VALUES('T694','chorus','Kakalinga sa iyo<br/>Bawa''t saglit, bawa''t dako;<br/>Diyos t''yak kakalinga,<br/>Sa iyo''y aalaga.<br/>',NULL,41677,7);
INSERT INTO stanza VALUES('T694','4','Anumang pagsubok, dusa,<br/>Diyos Mo''y kakalinga;<br/>Taong pagod, himlaya''y Siya,<br/>Diyos Mo''y kakalinga.<br/>',NULL,41678,8);
INSERT INTO stanza VALUES('T694','chorus','Kakalinga sa iyo<br/>Bawa''t saglit, bawa''t dako;<br/>Diyos t''yak kakalinga,<br/>Sa iyo''y aalaga.<br/>',NULL,41679,9);
INSERT INTO stanza VALUES('T695','1','Nakikiramay ba si Hesus,<br/>Kung ako''y nasasaktan<br/>Sa kahirapan,<br/>Kapighatian,<br/>At pasang krus pa ang daan?<br/>',NULL,41680,1);
INSERT INTO stanza VALUES('T695','chorus','Oo, nakikiramay Siya,<br/>Ang puso Niya''y nasaktan,<br/>Kapag ang araw<br/>ay may kalungkutan<br/>Nakikiramay Siya.<br/>',NULL,41681,2);
INSERT INTO stanza VALUES('T695','2','Nakikiramay ba si Hesus,<br/>Kung natatakot ako,<br/>Pagtakip-silim,<br/>At dumidilim,<br/>Siya ba ay nasa piling ko?<br/>',NULL,41682,3);
INSERT INTO stanza VALUES('T695','3','Nakikiramay ba si Hesus,<br/>Kung mithing tagumpay na<br/>Pinagsikapan,<br/>Di ko nakamtan,<br/>Walang patid ang pagluha?<br/>',NULL,41683,5);
INSERT INTO stanza VALUES('T695','4','Nakikiramay ba si Hesus,<br/>Kung ako''y magpaalam,<br/>Sa aking sinta<br/>Dito sa lupa;<br/>Puso ko''y nasusugatan?<br/>',NULL,41684,7);
INSERT INTO stanza VALUES('T697','1','Pagod, malayong lakbayin,<br/>Mabigat pang pasanin<br/>Pakinggan mo''ng Salita Niya,<br/>"Pasanin Akin na nga."<br/>',NULL,41685,1);
INSERT INTO stanza VALUES('T697','chorus','Ibigay na sa Kanya<br/>Tanang pasan, bigat pa<br/>Nagpapalakas Siya<br/>Aaliwin ka Niya<br/>Ibigay na sa Kanya.<br/>',NULL,41686,2);
INSERT INTO stanza VALUES('T697','2','Paa''t kamay nangangalay,<br/>Ilawan walang silay;<br/>Pasang mabigat na lubha,<br/>Ibigay na sa Kanya.<br/>',NULL,41687,3);
INSERT INTO stanza VALUES('T697','3','Humiwalay ang kaibigan,<br/>Pusong hapis nasaktan;<br/>Namanglaw, nag-alaala,<br/>Lahat bigay sa Kanya!<br/>',NULL,41688,5);
INSERT INTO stanza VALUES('T697','4','Nangulila, nanghihina<br/>Puso ay kabang-kaba,<br/>Dahil kinalimutan ko,<br/>Bigay lahat kay Kristo.<br/>',NULL,41689,7);
INSERT INTO stanza VALUES('T697','5','Siya''y nag-aliw, nagpatibay,<br/>Yapak mo Siya''ng gagabay;<br/>Lakas sa iyo idaragdag<br/>Siya sa iyo''y magpanatag.<br/>',NULL,41690,9);
INSERT INTO stanza VALUES('T698','1','Sa gitna ng pagsubok man,<br/>Suliranin nasumpungan,<br/>Kay tamis sa aking loob,<br/>''Ko''y iniisip Mo.<br/>',NULL,41691,1);
INSERT INTO stanza VALUES('T698','chorus','''Ko''y iniisip Mo! ''Ko''y iniisip Mo!<br/>Takot pa ba? Malapit Ka,<br/>At iniisip Mo!<br/>',NULL,41692,2);
INSERT INTO stanza VALUES('T698','2','Mga balisa ng buhay<br/>Sa puso''y nagpalupaypay,<br/>Nagpaalaala lumbay,<br/>''Ko''y iniisip Mo.<br/>',NULL,41693,3);
INSERT INTO stanza VALUES('T698','3','Maaraw man o maulap,<br/>Matamis man o masaklap,<br/>Nasisiyahan ako pagka''t<br/>''Ko''y iniisip Mo.<br/>',NULL,41694,5);
INSERT INTO stanza VALUES('T700','1','"Sa bukas, huwag mabahala,"<br/>Sabi Niya.<br/>Sa halip na mag-alala,<br/>''Tiwala!<br/>Sa oras ng kapanglawan,<br/>Biyaya Niya''y nariyan.<br/>',NULL,41695,1);
INSERT INTO stanza VALUES('T700','2','Ilagak ang ating yaman<br/>Sa Kanya,<br/>Kanyang mapangalagaan,<br/>Matapang!<br/>Sa Kanya manalig lamang,<br/>Diyos tiyak may paraan.<br/>',NULL,41696,2);
INSERT INTO stanza VALUES('T701','1','Ako''y pinapatnubayan<br/>Ng aking Manliligtas,<br/>Bakit mag-aalinlangan<br/>Awa''y gabay sa landas<br/>May aliw, kapayapaan<br/>''Pag sa Kanya''y manahan!<br/>Anuman ang maranasan<br/>Si Hesus sapat naman,<br/>Anuman ang maranasan<br/>Si Hesus sapat naman.<br/>',NULL,41697,1);
INSERT INTO stanza VALUES('T701','2','Ako''y pinapatnubayan<br/>Bawa''t hakbang sa daan;<br/>Tustos sa pangangailangan,<br/>Aliw sa kalungkutan.<br/>''Pag kulang ang kalakasan,<br/>Puso may kauhawan,<br/>Masdan Bato sa unahan,<br/>Batis ng kasiyahan,<br/>Masdan Bato sa unahan,<br/>Batis ng kasiyahan.<br/>',NULL,41698,2);
INSERT INTO stanza VALUES('T701','3','Ako''y pinapatnubayan,<br/>Biyaya Niya — kay yaman!<br/>Sa yakap ng aking Ama,<br/>Tamo kapahingahan.<br/>Espiritu''y mabihisan<br/>Ng kaluwalhatian,<br/>Ako ay pinatnubayan,<br/>Awit kong walang hanggan,<br/>Ako ay pinatnubayan,<br/>Awit kong walang hanggan.<br/>',NULL,41699,3);
INSERT INTO stanza VALUES('T703','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41700,1);
INSERT INTO stanza VALUES('T703','1','Manlalakbay binigyan ka,<br/>Pangakong mahalaga,<br/>Sa iyong daan tungong gloria,<br/>"Gabay mo''y Aking mata."<br/>',NULL,41701,2);
INSERT INTO stanza VALUES('T703','chorus','Ika''y Aking gagabayan,<br/>Gabay mo''y Aking mata;<br/>Sa iyong daan tungong gloria,<br/>Gabay mo''y Aking mata.<br/>',NULL,41702,3);
INSERT INTO stanza VALUES('T703','2','Mabangis man ang panukso<br/>Lumayo katulong mo;<br/>Pangako''y dapat makita,<br/>"Gabay mo''y Aking mata."<br/>',NULL,41703,4);
INSERT INTO stanza VALUES('T703','chorus','Ika''y Aking gagabayan,<br/>Gabay mo''y Aking mata;<br/>Sa iyong daan tungong gloria,<br/>Gabay mo''y Aking mata.<br/>',NULL,41704,5);
INSERT INTO stanza VALUES('T703','3','Sa mga taon nalibing,<br/>Sawi pag-asang lihim,<br/>Pangako ay mahalaga,<br/>"Gabay mo''y Aking mata."<br/>',NULL,41705,6);
INSERT INTO stanza VALUES('T703','chorus','Ika''y Aking gagabayan,<br/>Gabay mo''y Aking mata;<br/>Sa iyong daan tungong gloria,<br/>Gabay mo''y Aking mata.<br/>',NULL,41706,7);
INSERT INTO stanza VALUES('T703','4','Panahon ng takip-silim,<br/>Anino''y lumalalim;<br/>Pakinggan ang pagbigkas Niya,<br/>"Gabay mo''y Aking mata."<br/>',NULL,41707,8);
INSERT INTO stanza VALUES('T703','chorus','Ika''y Aking gagabayan,<br/>Gabay mo''y Aking mata;<br/>Sa iyong daan tungong gloria,<br/>Gabay mo''y Aking mata.<br/>',NULL,41708,9);
INSERT INTO stanza VALUES('T703','5','Diyos, galak ng ''spiritu ko,<br/>Siya''y hiyas ng puso ko;<br/>''Tanggap gabay ng mata Niya,<br/>Mayroong salamuha.<br/>',NULL,41709,10);
INSERT INTO stanza VALUES('T703','chorus','Ika''y Aking gagabayan,<br/>Gabay mo''y Aking mata;<br/>Sa iyong daan tungong gloria,<br/>Gabay mo''y Aking mata.<br/>',NULL,41710,11);
INSERT INTO stanza VALUES('T708','1','Kasing sariwa ng hamog,<br/>May matamis na tunog;<br/>Kristo sa pagpapahid Niya,<br/>Umaliw ang salita.<br/>Manatiling nakatayo,<br/>Hanggang bagyo''y maglaho,<br/>Para sa kal''walhatian,<br/>Hanggang sa kaharian.<br/>',NULL,41711,1);
INSERT INTO stanza VALUES('T708','chorus','Pag-asa ko, kay tamis tinig Mo,<br/>Puso''y ginalak sa presensya Mo.<br/>',NULL,41712,2);
INSERT INTO stanza VALUES('T708','2','Kung sa gitna ng pagsubok,<br/>''Spiritu ko''y malugmok,<br/>Pananalig at pag-asa,<br/>Lumabo''t di makita.<br/>Nawa Iyong pananalig nga<br/>Lakas sa ''kin humawak;<br/>Nang sagana Mo at yaman<br/>Aking lubos matikman.<br/>',NULL,41713,3);
INSERT INTO stanza VALUES('T708','3','Araw ng bukang-liwayway<br/>Dilim Iyong ihiwalay,<br/>Pakpak Mong nagpapagaling,<br/>Gawing araw ang gabi.<br/>Poon ng aliw, parito<br/>Sa malungkot kong puso;<br/>Pag-asang maluwalhati,<br/>Hu-wag, lumisan dili.<br/>',NULL,41714,5);
INSERT INTO stanza VALUES('T713','1','Bawa''t araw, saglit na lumipas,<br/>Hanap sa pagsubok ay lakas;<br/>Sa dunong na kaloob ng Ama,<br/>Tiwala at walang pangamba.<br/>Di-masukat puso Niyang kay buti,<br/>Bigay Niya''y pinakamainam,<br/>Magiliw hinalong pagdurusa,<br/>Gumawang mapayapa.<br/>',NULL,41715,1);
INSERT INTO stanza VALUES('T713','2','Bawa''t araw kay lapit sa akin<br/>Ng Panginoon mahabagin;<br/>Dadalhin Niya ang aking pasanin,<br/>Tagapayo, pangalang angkin.<br/>Pag-adya Niya sa atin at yaman<br/>Kanyang Sarili ang nagpasan;<br/>"Sukat na lakas mo bawa''t araw,"<br/>Panatang binitiwan.<br/>',NULL,41716,2);
INSERT INTO stanza VALUES('T713','3','Sa bawa''t pighati ay tulungan,<br/>Pangako Mo''y pagtiwalaan,<br/>Di mawaglit tamis ng tiwala,<br/>Handog ng banal Mong Salita.<br/>Tulungan sa aking suliranin,<br/>Sa kamay ng Ama''y tanggapin,<br/>Bawa''t araw, sandaling magbago,<br/>Manatili kay Kristo.<br/>',NULL,41717,3);
INSERT INTO stanza VALUES('T717','1','Mangagalak tayo sa Panginoon,<br/>Pagsubok man ay pumaligid,<br/>Pighati tulad ng bagyo at alon,<br/>Hinagpis dinaig ng pag-awit.<br/>',NULL,41718,1);
INSERT INTO stanza VALUES('T717','chorus','Tayo''y mangagalak<br/>At huwag malumbay,<br/>Hinagpis dinaig ng pag-awit,<br/>Kamatayan daig din ng buhay,<br/>Kaya''t tayo''y mangagalak.<br/>',NULL,41719,2);
INSERT INTO stanza VALUES('T717','2','Mangagalak tayo sa Panginoon,<br/>Pinapana man ng kaaway,<br/>Pagka''t takot si Satanas tulad noon<br/>Sa ating awit higit sa lumbay.<br/>',NULL,41720,3);
INSERT INTO stanza VALUES('T717','3','Mangagalak tayo sa Panginoon,<br/>Kahit may sakit na mang-api,<br/>Kalakasan ang galak ng Panginoon,<br/>Siya ang batis na nagpapabuti.<br/>',NULL,41721,5);
INSERT INTO stanza VALUES('T720','1','Di ''pinangako ng Diyos mahal,<br/>Na palaging langit ay bughaw;<br/>Panay bulaklak buong buhay<br/>Payapang walang sakit taglay.<br/>',NULL,41722,1);
INSERT INTO stanza VALUES('T720','chorus','Nguni''t pinangako ng Diyos nga,<br/>Kung magpagal ay may pahinga;<br/>Sa pagsubok, tulong, biyaya<br/>Ilaw sa daan, simpati-ya.<br/>',NULL,41723,2);
INSERT INTO stanza VALUES('T720','2','Di ''pinangako ng Diyos natin,<br/>Dusa''t pagsubok di danasin;<br/>Walang bigat, walang pasanin,<br/>Walang gulo''t alalahanin.<br/>',NULL,41724,3);
INSERT INTO stanza VALUES('T720','3','Di ''pinangako ng Diyos tapat,<br/>Daang walang bako''t malapad;<br/>Bundok di matarik, mabato<br/>Ilog di malalim, malabo.<br/>',NULL,41725,5);
INSERT INTO stanza VALUES('T722','1','Krus na ''binigay mabigat man,<br/>Biyaya di mahigtan;<br/>Bagyong aking kinatakutan—<br/>Mukha Niya''y di matakpan.<br/>',NULL,41726,1);
INSERT INTO stanza VALUES('T722','chorus','Krus di mahigtan ang biyaya,<br/>Bagyo di matakpan mukha Niya;<br/>Puso ko''y natutuwa<br/>Pagka''t Hesus kasama,<br/>Kaaway ko''y napuksa.<br/>',NULL,41727,2);
INSERT INTO stanza VALUES('T722','2','Tinik sa daan ko''y di gaya<br/>Ng pinutong sa Kanya;<br/>Ininom kong saro ng dusa<br/>Di simpait ng Kanya.<br/>',NULL,41728,3);
INSERT INTO stanza VALUES('T722','3','Mas maliwanag Kanyang ilaw,<br/>Sa landas na mapanglaw;<br/>Pasanin ko ay gumagaan<br/>Kapag may tinulungan.<br/>',NULL,41729,5);
INSERT INTO stanza VALUES('T722','4','Kay saya gawin naisin Niya,<br/>Namumuhay sa Kanya;<br/>Dusa''y pagpapala ang dala,<br/>Kristo dito ang tuwa.<br/>',NULL,41730,7);
INSERT INTO stanza VALUES('T724','1','Ibon mang maliit,<br/>Sa hawla''y napiit,<br/>Gayunpama''y kumakanta<br/>Sa Kanyang nagpasya;<br/>Mabilanggo man may tuwa,<br/>Pagka''t Diyos ko ay may siya.<br/>',NULL,41731,1);
INSERT INTO stanza VALUES('T724','2','Wala ngang magawa,<br/>Kundi ang kumanta;<br/>Sa awit ko nakikinig Siya,<br/>Bigyan lugod ko''y Siya;<br/>Aking pakpak binihag Niya;<br/>Awit ko''y pinakinggan Niya.<br/>',NULL,41732,2);
INSERT INTO stanza VALUES('T724','3','Iyong tainga''y makinig,<br/>Iyong puso''y umibig;<br/>Kahit nota ko''y magaspang,<br/>Iyo ring pinakinggan;<br/>Sapagka''t Iyong nababatid,<br/>Pag-ibig nga ang naghatid.<br/>',NULL,41733,3);
INSERT INTO stanza VALUES('T724','4','Nakulong sa hawla,<br/>Di makalipad nga;<br/>Natalian man pakpak ko,<br/>Malaya puso ko;<br/>Bilangguan di mapigil,<br/>Kaluluwa di masiil.<br/>',NULL,41734,4);
INSERT INTO stanza VALUES('T724','5','Ang pumailanglang<br/>Lampas sa piitan!<br/>Layon Niya hinangaan ko,<br/>Kalinga''y ibig ko;<br/>At sa Kanyang kalooban<br/>Galak, kay layang isipan.<br/>',NULL,41735,5);
INSERT INTO stanza VALUES('T731','1','Sa karimlan ba''y mangamba<br/>O manginig sa lakas niya?<br/>Hesus, ligtas kong moog Siya!<br/>',NULL,41736,1);
INSERT INTO stanza VALUES('T731','2','Ang labanan ma''y mainit<br/>Di tatakas, matigatig<br/>Kalasag ko''y di padaig.<br/>',NULL,41737,2);
INSERT INTO stanza VALUES('T731','3','Mawala man kaaliwan<br/>Hindi ko dapat tangisan<br/>Hesus buhay! Malapitan!<br/>',NULL,41738,3);
INSERT INTO stanza VALUES('T731','4','Mangamatay man ang kawan<br/>Gutom di ko katakutan<br/>Hesus, pan ng kabuhayan!<br/>',NULL,41739,4);
INSERT INTO stanza VALUES('T731','5','Mangyayari''y di ko talos,<br/>Mayroon o walang tustos,<br/>Ito nga''y alam ni Hesus.<br/>',NULL,41740,5);
INSERT INTO stanza VALUES('T731','6','Sala ma''y kabalisahan,<br/>Trono ng b''yaya''y lapitan,<br/>Hesus aking katuwiran.<br/>',NULL,41741,6);
INSERT INTO stanza VALUES('T731','7','Pag-ibig ko''y malamig man,<br/>Pag-asa ko''y di lilisan,<br/>Yamang Hesus namagitan.<br/>',NULL,41742,7);
INSERT INTO stanza VALUES('T731','8','Magsama man kasamaan,<br/>Dibinong lakas kublihan,<br/>Si Hesus ang aking tanan!<br/>',NULL,41743,8);
INSERT INTO stanza VALUES('T733','1','Sa dalawang punong-kahoy,<br/>Hinarap ng Diyos ang tao;<br/>Sa buhay, sagisag ng Diyos,<br/>Sa kasalanan, ng diyablo.<br/>',NULL,41744,1);
INSERT INTO stanza VALUES('T733','2','Puno ng buhay ang sentro<br/>Ng sakdal na plano ng Diyos,<br/>Diyos na na kay Kristo''y buhay,<br/>Matanggap ng taong lubos.<br/>',NULL,41745,2);
INSERT INTO stanza VALUES('T733','3','Ang puno ng kaalaman,<br/>Nagbibigay ng babala,<br/>Liban sa Diyos, may isa pa,<br/>Sa kamatayan magdala.<br/>',NULL,41746,3);
INSERT INTO stanza VALUES('T733','4','Puno ng buhay kainin,<br/>Diyos bilang buhay tanggapin,<br/>Matransporma maging bato,<br/>Layunin ng Diyos tuparin.<br/>',NULL,41747,4);
INSERT INTO stanza VALUES('T733','5','Nang puno ng kaalaman,<br/>Ay kinain ng tao nga,<br/>Pumasok Satanas, sala,<br/>Nang plano ng Diyos hadlangan.<br/>',NULL,41748,5);
INSERT INTO stanza VALUES('T733','6','''Pinapakita Diyos lamang,<br/>Ang pinagmulan ng buhay;<br/>Ang hipuin pa ang iba,<br/>Sasanhiin pagkamatay.<br/>',NULL,41749,6);
INSERT INTO stanza VALUES('T733','7','Kaalaman, buti''t sama,<br/>Ang dala''y kamatayan nga;<br/>Anuman maliban sa Diyos,<br/>Kay Satanas na balak nga.<br/>',NULL,41750,7);
INSERT INTO stanza VALUES('T733','8','Masama man o mabuti<br/>Pawang kalaban ni Kristo,<br/>Batid man buti o sama<br/>Sumasalungat kay Kristo.<br/>',NULL,41751,8);
INSERT INTO stanza VALUES('T733','9','Panginoon turuan nga;<br/>Buhay Mo lamang hipuin;<br/>Hindi ang buti o sama,<br/>Ikaw lamang kaugnayin.<br/>',NULL,41752,9);
INSERT INTO stanza VALUES('T734','1','Utos ng Diyos banal, ''buti<br/>Hiling gawin ang mabuti;<br/>Layon upang ipakita<br/>Di natin kaya hiling Niya.<br/>',NULL,41753,1);
INSERT INTO stanza VALUES('T734','2','May batas sa isip natin,<br/>Mabuti ang nais gawin;<br/>Ating sangkap may batas din,<br/>Mabuti''y ibig daigin.<br/>',NULL,41754,2);
INSERT INTO stanza VALUES('T734','3','Mabuting utos sa isip<br/>Pantaong buhay nakuha;<br/>Nang Diyos sa atin naglikha,<br/>Mabuting asal nadala.<br/>',NULL,41755,3);
INSERT INTO stanza VALUES('T734','4','Utos sa ating sangkap ay<br/>Makasatanas na buhay;<br/>Sa ating sangkap pumasok<br/>Nang ang tao ay natisod.<br/>',NULL,41756,4);
INSERT INTO stanza VALUES('T734','5','Ang utos ng kasamaan<br/>Higit kaysa kabutihan;<br/>Ang utos ng kabutihan<br/>Sa pagkatalo nadala.<br/>',NULL,41757,5);
INSERT INTO stanza VALUES('T734','6','May kautusan ''spiritu,<br/>Kautusan ng buhay nga;<br/>Itong buhay ng Diyos mismo,<br/>Muling pagsilang natamo.<br/>',NULL,41758,6);
INSERT INTO stanza VALUES('T734','7','Malakas sa lahat ito<br/>Utos ng buhay dibino;<br/>Hinigtan utos ng sala<br/>Utos ng Diyos nai-sagawa.<br/>',NULL,41759,7);
INSERT INTO stanza VALUES('T734','8','Ilagak nga isip natin<br/>Sa espiritung malalim,<br/>Huwag sa bagay ng sa laman,<br/>Sala katawan wasakin.<br/>',NULL,41760,8);
INSERT INTO stanza VALUES('T734','9','Isip ilagak sa laman,<br/>Ay sala at kamatayan;<br/>Isip sa ''spiritu naman<br/>Buhay at kapayapaan.<br/>',NULL,41761,9);
INSERT INTO stanza VALUES('T734','10','Daan ng paglaya ito!<br/>Paraan pa ng tagumpay!<br/>Sa espiritu mamuhay,<br/>Lumakad sa ''Spiritu Mo.<br/>',NULL,41762,10);
INSERT INTO stanza VALUES('T735','1','Utos ng titik naglahad,<br/>Patotoo ng Diyos hayag;<br/>Pag-ibig, liwanag nga Siya,<br/>Kabanalan, kat''wiran pa.<br/>',NULL,41763,1);
INSERT INTO stanza VALUES('T735','2','Hiling ng utos ng Diyos na<br/>Tayo''y lumakad tulad Niya;<br/>Maaring-mat''wid kalul''wa<br/>Bigyan tayo pagpapala.<br/>',NULL,41764,2);
INSERT INTO stanza VALUES('T735','3','Di nagbigay-buhay utos,<br/>Lakas hindi makatustos;<br/>Pawang paghiling ginawa,<br/>Hinantad tayo''y mahina.<br/>',NULL,41765,3);
INSERT INTO stanza VALUES('T735','4','Utos di plano talaga<br/>Naragdag dahil sa sala;<br/>Pinatutunayan lamang<br/>Tao ay makasalanan.<br/>',NULL,41766,4);
INSERT INTO stanza VALUES('T735','5','Utos sa bibig nagtikom,<br/>Tao sa sala''y kinulong;<br/>Ito''y nagdala kay Kristo,<br/>Nang Diyos pagpalain tayo.<br/>',NULL,41767,5);
INSERT INTO stanza VALUES('T735','6','Utos anino ni Kristo<br/>Sa Diyos, Kristo''y patotoo;<br/>''Pinakita kabanalan,<br/>Ilaw, pag-ibig, katwiran.<br/>',NULL,41768,6);
INSERT INTO stanza VALUES('T735','7','Kristo ng Diyos ang siyang tunay,<br/>Sa ''tin nagtustos ng buhay;<br/>Nang kahilingan ng utos,<br/>Matupad nga nating lubos.<br/>',NULL,41769,7);
INSERT INTO stanza VALUES('T735','8','Kristo, Diyos at patotoo<br/>Binigyan buhay nga tayo;<br/>Sa utos tayo''y namatay,<br/>Sa ''Spiritu bunga''y taglay.<br/>',NULL,41770,8);
INSERT INTO stanza VALUES('T736','1a','Nang nasa Lumang Tipan pa,<br/>Utos ng Diyos inukit na;<br/>Di sa malambot na puso,<br/>Kundi inukit sa bato.<br/>',NULL,41771,1);
INSERT INTO stanza VALUES('T736','1b','Datapwa''t sa Bagong Tipan,<br/>Utos ng buhay nasaan?<br/>Hindi sa tapyas ng bato<br/>Kundi sa puso ng tao.<br/>',NULL,41772,2);
INSERT INTO stanza VALUES('T736','2','Utos ng titik may gusto,<br/>Magpakabuti ang tao;<br/>Utos ng buhay may tustos,<br/>Natamasa lakas ng Diyos.<br/>',NULL,41773,3);
INSERT INTO stanza VALUES('T736','3','Panlabas utos na titik,<br/>Upang Diyos natin mabatid;<br/>Utos ng buhay tustusan<br/>Malalim na kaalaman.<br/>',NULL,41774,4);
INSERT INTO stanza VALUES('T736','4','Patay na utos sa titik<br/>Ang mag-utos lang ang batid;<br/>May alam utos ng buhay,<br/>Mamuno sa daang buháy.<br/>',NULL,41775,5);
INSERT INTO stanza VALUES('T736','5','Kumilos utos ng buhay,<br/>Sa loob ko nga nang buháy;<br/>Damdamin ng buhay sundin<br/>Namamahala sa akin.<br/>',NULL,41776,6);
INSERT INTO stanza VALUES('T736','6','Ang pamamahala''y pino<br/>Nasa kaibuturan ko;<br/>Dala''y damdamin ng buhay<br/>Diyos Mismo sa ''kin ''binigay.<br/>',NULL,41777,7);
INSERT INTO stanza VALUES('T736','7','Dahil sa utos ng buhay,<br/>Turong panlabas hiwalay;<br/>Buhay kabatiran sa Diyos,<br/>Turo''y panloob ng utos.<br/>',NULL,41778,8);
INSERT INTO stanza VALUES('T736','8','Turuan akong kumilos,<br/>Sundin panloob na utos,<br/>Sa Iyo Mismo bumahagi,<br/>At makilala Kang lubos.<br/>',NULL,41779,9);
INSERT INTO stanza VALUES('T737','1','Walang hanggang buhay,<br/>May salamuha;<br/>Buhay at ''Spiritu,<br/>Niligtas tayo.<br/>',NULL,41780,1);
INSERT INTO stanza VALUES('T737','2','Salamuhang banal<br/>Buhay natamo;<br/>Poong Espiritu,<br/>Kaisa tayo.<br/>',NULL,41781,2);
INSERT INTO stanza VALUES('T737','3','Buhay sa ''Spiritu<br/>May salamuha,<br/>Pagsasalamuha<br/>May biyaya nga.<br/>',NULL,41782,3);
INSERT INTO stanza VALUES('T737','4','Pagsasalamuha,<br/>Sa espiritu;<br/>Buhay ay matuwid,<br/>Liwanag dala.<br/>',NULL,41783,4);
INSERT INTO stanza VALUES('T737','5','Salamuha''y lagi,<br/>At mag-aani;<br/>Kung labas malinis,<br/>Loob may langis.<br/>',NULL,41784,5);
INSERT INTO stanza VALUES('T737','6','Pagsasalamuha<br/>Sa krus lalalim;<br/>Mapatataas pa<br/>Sa ''Spiritu Niya.<br/>',NULL,41785,6);
INSERT INTO stanza VALUES('T737','7','Sa pagsalamuha,<br/>Sarili''y laya;<br/>Dadalhin nga tayo,<br/>Sa Diyos nga Mismo.<br/>',NULL,41786,7);
INSERT INTO stanza VALUES('T738','1','Ang bawa''t uri buhay<br/>Ay may kamalayan;<br/>Walang hanggang buhay natin<br/>May kamalayan din.<br/>',NULL,41787,1);
INSERT INTO stanza VALUES('T738','2','Mas mat''as uri ng buhay,<br/>Kamalaya''y mas mahusay;<br/>Pinakamataas na malay—<br/>Nasa maka-Diyos na buhay.<br/>',NULL,41788,2);
INSERT INTO stanza VALUES('T738','3','Sa loob, malay ng buhay,<br/>Ito''y malay ng Diyos lagi;<br/>''Spiritung muling-nabuhay,<br/>Higit sa malay ng buti.<br/>',NULL,41789,3);
INSERT INTO stanza VALUES('T738','4','Panloob na kamalayan,<br/>Nasa ''ting kaibuturan;<br/>Inaninaw kalooban,<br/>Nang nais ng Diyos malaman.<br/>',NULL,41790,4);
INSERT INTO stanza VALUES('T738','5','Dahil sa malay sa loob,<br/>Ang Diyos ating nakilala;<br/>Malay ng buhay-panloob,<br/>May kalakasan at kusa.<br/>',NULL,41791,5);
INSERT INTO stanza VALUES('T738','6','Kung mas malago ang buhay,<br/>Mas tumatalas ang malay;<br/>Higit kumilos sa buhay,<br/>Lalong titindi ang malay.<br/>',NULL,41792,6);
INSERT INTO stanza VALUES('T738','7','Sanaying lubos ang malay,<br/>Lalakas ang espiritu,<br/>Pagsasalamuha''y tunay—<br/>''Pag malay ng Diyos narito.<br/>',NULL,41793,7);
INSERT INTO stanza VALUES('T740','1','Pagiging-laman na prinsipyo:<br/>Paghahalo ng Diyos, tao;<br/>Gumawang may kooperasyon,<br/>Nang matupad Kanyang layon.<br/>',NULL,41794,1);
INSERT INTO stanza VALUES('T740','2','Sa Diyos, kahayagan ang tao,<br/>Buhay Niya, tao''y nagtamo.<br/>Lubos na pag-aari ng Diyos<br/>Sa tao, Diyos hayag lubos!<br/>',NULL,41795,2);
INSERT INTO stanza VALUES('T740','3','Katubusan naisagawa,<br/>Nang dunong ng Diyos makita;<br/>Napaliwanag kaligtasan,<br/>Nang sangnilikha malaman.<br/>',NULL,41796,3);
INSERT INTO stanza VALUES('T740','4','Tao kasama Niyang gagawa,<br/>Sa kapanahunang ito.<br/>Nang Diyos sa tao malapit nga<br/>Sa isa''t isa aasa.<br/>',NULL,41797,4);
INSERT INTO stanza VALUES('T740','5','Ang magpapagal di Diyos lamang,<br/>Maglilingkod di tao lang;<br/>Kundi tao''t Diyos magkasama,<br/>Nang layon Niya''y mapakita.<br/>',NULL,41798,5);
INSERT INTO stanza VALUES('T740','6','Prinsipyong pagkatawang-tao,<br/>Tanang gawa''y iangkop ''to;<br/>Sa ating kaloob, paggawa,<br/>Maglingkod nang nagkakai-sa.<br/>',NULL,41799,6);
INSERT INTO stanza VALUES('T742','1','Tatlong bahagi ang tao,<br/>Katawan, kal''luwa''t ''spiritu,<br/>Diyos tutupdin Kanyang plano,<br/>Pamana Niya ay matanto.<br/>',NULL,41800,1);
INSERT INTO stanza VALUES('T742','2','Nasa labas ang katawan,<br/>May pakiramdam sa mundo,<br/>Tao''y nahayag sa laman,<br/>Bagay materyal mahipo.<br/>',NULL,41801,2);
INSERT INTO stanza VALUES('T742','3','Nasa loob ang kalul''wa,<br/>Sarili niya''y makilala,<br/>Bagay pansikolohiya,<br/>Tao''y makauunawa.<br/>',NULL,41802,3);
INSERT INTO stanza VALUES('T742','4','Malalim ang espiritu,<br/>Sa loob, Diyos ay matanto,<br/>Diyos ay matanggap ng tao,<br/>Bagay ''spirituwal mahipo.<br/>',NULL,41803,4);
INSERT INTO stanza VALUES('T742','5','Isip, pasya, at damdamin<br/>Ang bahagi ng kalul''wa;<br/>Sa tao''y mga tungkulin,<br/>Nang maganap kanyang gawa.<br/>',NULL,41804,5);
INSERT INTO stanza VALUES('T742','6','Bahagi ng espiritu:<br/>Budhi, damdam, salamuha,<br/>Kaugnay niya ang Diyos dito,<br/>Diyos matanggap at masamba.<br/>',NULL,41805,6);
INSERT INTO stanza VALUES('T742','7','Kalul''wa dapat sanayin<br/>Lahat ng sa Diyos piliin,<br/>Sa espiritu, tanggapin,<br/>Sa katawan, Diyos dangalin.<br/>',NULL,41806,7);
INSERT INTO stanza VALUES('T742','8','Muling-pagsilang, ''spiritu<br/>May buhay ng Diyos, dibino;<br/>Kalul''wa dapat mabago,<br/>Katawa''y tulad kay Kristo.<br/>',NULL,41807,8);
INSERT INTO stanza VALUES('T742','9','Dahil sa gawang dibino,<br/>Bawa''t bahagi ng tao,<br/>Sa Panginoon nahalo<br/>Diyos inihayag nang buo.<br/>',NULL,41808,9);
INSERT INTO stanza VALUES('T743','1','Nilikha tayong sisidlan,<br/>Sa Di-yos, kahayagan;<br/>May puso ang Diyos ibigin<br/>''Spiritu Siya''y tanggapin.<br/>',NULL,41809,1);
INSERT INTO stanza VALUES('T743','2','Sa ''ting puso Diyos mahalin,<br/>''Spiritu Siya''y taglayin;<br/>Bilang buhay Siya ay kunin,<br/>Kahayagan Niya''y kamtin.<br/>',NULL,41810,2);
INSERT INTO stanza VALUES('T743','3','Pinasamà ating puso,<br/>Pinatay espiritu<br/>Nang Poon di makaugnay,<br/>Siyang gawa ng kaaway.<br/>',NULL,41811,3);
INSERT INTO stanza VALUES('T743','4','Puso''t ''spiritu''y binago,<br/>Nang iniligtas tayo;<br/>Abilidad na umibig,<br/>Ganap pinanumbalik.<br/>',NULL,41812,4);
INSERT INTO stanza VALUES('T743','5','Sa ''ting napabagong puso,<br/>Sa Diyos umibig tayo;<br/>Sa napabagong ''spiritu<br/>Sa Diyos sumamba tayo.<br/>',NULL,41813,5);
INSERT INTO stanza VALUES('T743','6','Puso nati''y sa Diyos dapat,<br/>Payak, dalisay, tapat;<br/>Espiritu naman natin,<br/>Dukha at masunurin.<br/>',NULL,41814,6);
INSERT INTO stanza VALUES('T743','7','O Diyos, ingatan puso ko,<br/>Laging sariwa sa Iyo;<br/>Gawing malakas ''spiritu<br/>Buhay, naugpong sa Iyo.<br/>',NULL,41815,7);
INSERT INTO stanza VALUES('T744','1','Pakitungo sa Pangino''n<br/>Dapat puso''y tama,<br/>Nang matamasa ang yaman<br/>Sa Kanyang biyaya.<br/>',NULL,41816,1);
INSERT INTO stanza VALUES('T744','2','Kailangan ang pusong wagas,<br/>Malinaw na isip,<br/>Nang hangad Niya''y matalastas,<br/>Nang may takot, ''nginig.<br/>',NULL,41817,2);
INSERT INTO stanza VALUES('T744','3','Kailangan pusong maalab,<br/>Damdamin ay puspos<br/>Ng pag-ibig, sigla, liyab<br/>Sa Kanya ng lubos.<br/>',NULL,41818,3);
INSERT INTO stanza VALUES('T744','4','Kailangan may katapatan,<br/>Pusong masunurin;<br/>Napasakop kapasyahan,<br/>Layon ng Diyos tupdin.<br/>',NULL,41819,4);
INSERT INTO stanza VALUES('T744','5','Kailangan di mahatulan,<br/>Pusong sa Diyos wasto,<br/>Na may budhing nalinisan,<br/>Natakpan ng dugo.<br/>',NULL,41820,5);
INSERT INTO stanza VALUES('T744','6','Pusong nakatuon sa Iyo,<br/>Kami ay Iyong bigyan;<br/>Tamasahin Sarili Mo,<br/>Maging pag-apaw Mo.<br/>',NULL,41821,6);
INSERT INTO stanza VALUES('T745','1','Panginoong Espiritu<br/>Sa ''min namumuhay;<br/>Amin at Iyong Espiritu<br/>Nagkaisang tunay.<br/>',NULL,41822,1);
INSERT INTO stanza VALUES('T745','2','''Spiritu nating dalawa,<br/>Kapwa sumasaksi,<br/>Kami''y anak ng Diyos Ama,<br/>Magmana''ng l''walhati.<br/>',NULL,41823,2);
INSERT INTO stanza VALUES('T745','3','Ikaw aming nahihipo<br/>Sa ''ming espiritu,<br/>Ibinigay Sarili Mo<br/>Bilang Espiritu.<br/>',NULL,41824,3);
INSERT INTO stanza VALUES('T745','4','Lumalakad sa ''spiritu,<br/>Lagi Kang susundan;<br/>Gumagabay Kang ''Spiritu,<br/>Ako''y Iyong tanglawan.<br/>',NULL,41825,4);
INSERT INTO stanza VALUES('T745','5','Pagsamba ko''t pamumuhay<br/>Nasa espiritu;<br/>Ako ay napatitibay<br/>Ng Iyong Espiritu.<br/>',NULL,41826,5);
INSERT INTO stanza VALUES('T745','6','Espiritu Mo''t amin din<br/>Sabay manalangin;<br/>Espiritu Ka sa amin,<br/>Ang Siyang dumaraing.<br/>',NULL,41827,6);
INSERT INTO stanza VALUES('T745','7','Babaling sa espiritu<br/>Nang makaugnay Ka;<br/>Mabahagi sa ''spiritu,<br/>Ang dibinong mana.<br/>',NULL,41828,7);
INSERT INTO stanza VALUES('T745','8','Anong kaisahan ito!<br/>Dalawang ''spiritu<br/>Magkatahan, magkahalo,<br/>Ang amin at sa Iyo!<br/>',NULL,41829,8);
INSERT INTO stanza VALUES('T746','1','Makilatis ang espiritu,<br/>Nang makilala Ka Mismo;<br/>Espiritu sa ''ming ''spiritu,<br/>Kami''y nahalong kai-sa Mo.<br/>',NULL,41830,1);
INSERT INTO stanza VALUES('T746','2','Makilatis ang espiritu,<br/>Buhay-kalul''wa takwil ko;<br/>Laging sundan Ka sa ''spiritu,<br/>Gamitin ang ''Spiritu Mo.<br/>',NULL,41831,2);
INSERT INTO stanza VALUES('T746','3','Makilatis ang espiritu,<br/>Di kailanman sa laman ko<br/>Ilagak aking kaisipan;<br/>Sa sarili''y matalian.<br/>',NULL,41832,3);
INSERT INTO stanza VALUES('T746','4','Makilatis ang espiritu,<br/>Di makakalul''wa ako;<br/>Maging espirituwal na tunay,<br/>Makilatis tamang bagay.<br/>',NULL,41833,4);
INSERT INTO stanza VALUES('T746','5','Makilatis ang espiritu,<br/>Mahantad sariling tuso!<br/>Sa krus matuos sarili ko<br/>Ipamuhay Ka nang husto.<br/>',NULL,41834,5);
INSERT INTO stanza VALUES('T746','6','Makilatis ang espiritu,<br/>Kaluluwa matransporma;<br/>Maiwangis sa larawan Mo<br/>Paggulang — mithi matamo.<br/>',NULL,41835,6);
INSERT INTO stanza VALUES('T746','7','Makilatis ang espiritu,<br/>Ibigay ang Salita Mo;<br/>Mahati kalul''wa''t ''spiritu,<br/>Sa kabanal-banalan ''ko.<br/>',NULL,41836,7);
INSERT INTO stanza VALUES('T749','1','''Spiritu ng tres-unong Diyos,<br/>Nanahan sa ''spiritu ko;<br/>Nasa''y sa atin umagos,<br/>Hayag Diyos na na kay Kristo.<br/>',NULL,41837,1);
INSERT INTO stanza VALUES('T749','2','Nguni''t sa taong natural,<br/>''Spiritu''y nasa kulungan;<br/>Sa halip bigyang tahanan,<br/>Tayo''y Kanyang bilangguan.<br/>',NULL,41838,2);
INSERT INTO stanza VALUES('T749','3','Siya''y tulad ng kayamanan,<br/>Nasa luwad na sisidlan;<br/>Mabasag kinakailangan,<br/>Upang matanghal ang yaman.<br/>',NULL,41839,3);
INSERT INTO stanza VALUES('T749','4','O kinaka-i-langan nga<br/>Paghahadlang ay mawala;<br/>Sarili ko''y basagin Mo<br/>Nang ''Spiritu''y mapalaya.<br/>',NULL,41840,4);
INSERT INTO stanza VALUES('T749','5','Ito na rin ang dahilan,<br/>Pangino''n gumawang hakbang;<br/>Nang panlabas nating tao,<br/>Ay mabasag nang lubusan.<br/>',NULL,41841,5);
INSERT INTO stanza VALUES('T749','6','Taong panlabas, kalul''wa<br/>Sarili dapat matapos;<br/>Nang ang panloob na tao<br/>Ay mapalaya nang lubos.<br/>',NULL,41842,6);
INSERT INTO stanza VALUES('T749','7','Panginoon, ibigay Mo<br/>Banal na pagkabasag ko;<br/>Sa aking pagiging buo<br/>Laan akong basagin Mo.<br/>',NULL,41843,7);
INSERT INTO stanza VALUES('T749','8','Pahalagahan ko nawa,<br/>Pagbabasag na Iyong gawa;<br/>Higit na bigyang-halaga<br/>Mga lugi kaysa gana.<br/>',NULL,41844,8);
INSERT INTO stanza VALUES('T750','1','Ang Diyos sa atin may balak:<br/>Ang mawangis sa Anak;<br/>Kaya transpormasyong gawa<br/>Ng Espiritu''y sadya!<br/>',NULL,41845,1);
INSERT INTO stanza VALUES('T750','chorus','Sa Iyong anyo transpormahin,<br/>Hesus, kalul''wa namin;<br/>Buong katauhan namin,<br/>Ng ''Spiritu''y puspusin.<br/>',NULL,41846,2);
INSERT INTO stanza VALUES('T750','2','Muling-silang ng Diyos tayo<br/>Sa ating espiritu,<br/>Nguni''t higit pang transporma<br/>Kailangan sa kalul''wa.<br/>',NULL,41847,3);
INSERT INTO stanza VALUES('T750','3','Mula sa ''king espiritu,<br/>Sa kaluluwa''y tungo,<br/>Ang gawaing pagtransporma,<br/>Nang Ika''y mamahala.<br/>',NULL,41848,5);
INSERT INTO stanza VALUES('T750','4','Sa lakas ng Iyong ''Spiritu,<br/>Transporma sa Iyong anyo;<br/>Mawangis sa Iyong larawan,<br/>Tungong kal''walhatian.<br/>',NULL,41849,7);
INSERT INTO stanza VALUES('T750','5','Patuloy ang pagtransporma,<br/>Gumulang katulad Niya;<br/>Kalul''wa natin maangkin,<br/>Katawan ay tubusin.<br/>',NULL,41850,9);
INSERT INTO stanza VALUES('T751','1','Di sa pagsumikap,<br/>Kundi pagtanggap;<br/>Nang pahinga''y kamtan,<br/>Pasan bitiwan.<br/>Hindi pagpasya ko,<br/>Kundi ang sa Iyo,<br/>Naligtas sa sala<br/>Ako''y lumaya.<br/>',NULL,41851,1);
INSERT INTO stanza VALUES('T751','2','Hindi sa titik nga,<br/>Kundi ''Spiritu<br/>Aprubahan ako,<br/>Buhay ''bahagi.<br/>Di pantaong turo,<br/>Kundi pagpahid;<br/>Ilaw, salamuha,<br/>Iyong pamahagi.<br/>',NULL,41852,2);
INSERT INTO stanza VALUES('T751','3','Di sa tumatakbo,<br/>Ni sa pasya ko;<br/>Kundi nasa awa,<br/>At Iyong biyaya.<br/>Di sa kaalaman,<br/>Biyaya lamang;<br/>Mapawangis sa Iyo<br/>Dusa''y matalo.<br/>',NULL,41853,3);
INSERT INTO stanza VALUES('T751','4','Sa kapangyarihan,<br/>Di salitaan;<br/>Sa buhay dibino,<br/>Ligaw dalhin ko.<br/>Ang Espiritu Mo,<br/>Hindi dunong ko<br/>Makasanhi sa ''kin<br/>Salita''y tupdin.<br/>',NULL,41854,4);
INSERT INTO stanza VALUES('T759','1','Habang Siya ay dumaraan,<br/>Laksang tao nagsiksikan;<br/>Isang hipo lang sa Kanya,<br/>Napagaling agad siya!<br/>',NULL,41855,1);
INSERT INTO stanza VALUES('T759','chorus','Pagdaan Niya, iyong hipuin,<br/>Karamdama''y papawiin.<br/>Halikayo Siya ay hipuin,<br/>Kayo''y mapapagaling.<br/>',NULL,41856,2);
INSERT INTO stanza VALUES('T759','2','Isang hipo nalutas na,<br/>Walang takot, mapayapa;<br/>Kabigatan nabitiwan<br/>Wala nang karamdaman.<br/>',NULL,41857,3);
INSERT INTO stanza VALUES('T759','3','Isang hipo, naganap na,<br/>Napagaling na ng Anak;<br/>Walang hanggang papurihan,<br/>Siyang naging kalutasan.<br/>',NULL,41858,5);
INSERT INTO stanza VALUES('T759','4','Isang hipo, bumaling Siya,<br/>Sa mata Niya''y may pagsinta,<br/>Salamat inaliw ako,<br/>Pinagaling na ako.<br/>',NULL,41859,7);
INSERT INTO stanza VALUES('T759','5','Isang hipo ng lakas Niya,<br/>Ngayon mapagagaling ka;<br/>Isang hipo, tanang sakit<br/>Mawawalan ng kapit.<br/>',NULL,41860,9);
INSERT INTO stanza VALUES('T762','1','Panalangin insenso ng puso<br/>Sa pagdaramdam sa Diyos tutungo,<br/>Kapag Espiritu''y nagpaningas<br/>Pananalig dala paitaas.<br/>',NULL,41861,1);
INSERT INTO stanza VALUES('T762','2','Panalangin samyo ng biyaya,<br/>May pananalig, pag-ibig, dusa<br/>Nakubli sa mabangong salita<br/>Langhap ng Diyos, mabangong samyo nga.<br/>',NULL,41862,2);
INSERT INTO stanza VALUES('T762','3','Panalangin ay singaw ng tubig,<br/>Pumailanglang upang bumalik;<br/>Bilang ulan upang mabuhusan,<br/>Lahat ng disyertong natuyuan.<br/>',NULL,41863,3);
INSERT INTO stanza VALUES('T762','4','Panalangin tila telepono,<br/>Ang langit at lupa''y magkatagpo;<br/>At sa pandinig ng ating Ama,<br/>Maibubuhos pasanin, dusa.<br/>',NULL,41864,4);
INSERT INTO stanza VALUES('T762','5','Panalangin tila telegrapo,<br/>Pinailanglang pananaing ko;<br/>Puso ng Diyos matagpuan, dalhin<br/>Tugon sa panalig, pag-ibig din.<br/>',NULL,41865,5);
INSERT INTO stanza VALUES('T762','6','Panalangin ginintuang tubo,<br/>Pinunan ng langis ng ''Spiritu;<br/>Nang nagkakaisa sa dalangin,<br/>''Spiritu, tayo''y kapupunuin.<br/>',NULL,41866,6);
INSERT INTO stanza VALUES('T762','7','Panalangin pinakamalakas,<br/>Kapangyarihang hindi mabigkas;<br/>''Pagkat ito''y dinamita ng Diyos,<br/>Dakilang kamay napakikilos.<br/>',NULL,41867,7);
INSERT INTO stanza VALUES('T762','8','Turuan Mo kaming manalangin,<br/>Aming katauhan pakilusin;<br/>Hanggang aming panalangi''y maging<br/>Panalangin ni Kristo sa amin.<br/>',NULL,41868,8);
INSERT INTO stanza VALUES('T762','9','Turuan Mo kaming manalangin,<br/>Kalooban Mo''y ihayag sa ''min;<br/>Diyos sa loob ko''t Diyos sa langit nga,<br/>Nagtutugunan sa salamuha.<br/>',NULL,41869,9);
INSERT INTO stanza VALUES('T763','1','Kristo''y Alpha ng dasal ko;<br/>''Spiritu''y nagturo,<br/>Manalangin ''di ko alam,<br/>Kung ''di Niya gabayan.<br/>',NULL,41870,1);
INSERT INTO stanza VALUES('T763','2','Kristo''y Omega ng dasal,<br/>"Amen" ng Diyos mahal;<br/>Sa pahinga ng dalangin,<br/>Isa ang damdamin.<br/>',NULL,41871,2);
INSERT INTO stanza VALUES('T763','3','Gitna ng Alpha''t Omega,<br/>Tayo''y nagsalita;<br/>Pagbigkas na mahihina,<br/>Sinaling isip Niya.<br/>',NULL,41872,3);
INSERT INTO stanza VALUES('T763','4','O Una''t Huli, kunin Mo<br/>Dalangin ng tao,<br/>At iugpong sa nais Mo<br/>Maging sakdal buo.<br/>',NULL,41873,4);
INSERT INTO stanza VALUES('T763','5','Sa dalanging di mawika,<br/>Ika''y Panimula;<br/>Sa dasal ''di mapalubos<br/>Ika''y pagtatapos.<br/>',NULL,41874,5);
INSERT INTO stanza VALUES('T764','1','Pangino''n mananahimik ako,<br/>Sa panloob makadulog sa Iyo;<br/>Manalangi''ng di sa paraan ko<br/>Dalangin Mo''y maging dalangin ko.<br/>',NULL,41875,1);
INSERT INTO stanza VALUES('T764','2','Tila sa langit nakikinig Ka,<br/>Nguni''t sa loob ko nakatira;<br/>Tila ako ang nananalangin,<br/>Nguni''t mula sa Iyo ang dalangin.<br/>',NULL,41876,2);
INSERT INTO stanza VALUES('T764','3','Kung minsan walang masabi ako,<br/>Susunod sa hibik ng ''spiritu;<br/>Di ako sa labas ang humingi,<br/>Ikaw sa ''king loob ang nagsabi.<br/>',NULL,41877,3);
INSERT INTO stanza VALUES('T764','4','Panginoon, Kita''y lalanghapin,<br/>Kainin, inumin, tamasahin;<br/>Nang ako''y makasalamuha Mo<br/>Sa akin, Ikaw maihayag ko.<br/>',NULL,41878,4);
INSERT INTO stanza VALUES('T764','5','Silayan ako ng liwanag Mo,<br/>Linisin, hugasan ng Iyong dugo;<br/>Di lamang ako maliwanagan,<br/>Bagkus malinaw Iyong kahayagan.<br/>',NULL,41879,5);
INSERT INTO stanza VALUES('T764','6','Dito ako''y Iyong pinapahiran,<br/>Upang Iyong Sarili''y maragdagan;<br/>Elemento Mo''y dumami lalo,<br/>Nang Ika''y higit maihayag ko.<br/>',NULL,41880,6);
INSERT INTO stanza VALUES('T764','7','Bukas ako sa Iyo, pumasok Ka<br/>Bukas din sa iba, umagos Ka;<br/>Salamuha sa tubig ng buhay<br/>Kahayagan Mo''y lubos at tunay.<br/>',NULL,41881,7);
INSERT INTO stanza VALUES('T765','1','Huwag munang magpahinga,<br/>Dinggin Siyang mabiyaya:<br/>Kalaban marami pa<br/>Magdasal!<br/>',NULL,41882,1);
INSERT INTO stanza VALUES('T765','2','Pamunuan ng dilim,<br/>Nagtipon hukbong lagim<br/>Sa di mo pagbabantay:<br/>Magdasal!<br/>',NULL,41883,2);
INSERT INTO stanza VALUES('T765','3','Isuot kutamaya<br/>Gabi''t araw ihanda<br/>Masama nag-aamba:<br/>Magdasal!<br/>',NULL,41884,3);
INSERT INTO stanza VALUES('T765','4','Mandaraig pakinggan<br/>Mandirigma pagmasdan<br/>Iisa ang pahayag,<br/>Magbantay!<br/>',NULL,41885,4);
INSERT INTO stanza VALUES('T765','5','Panginoo''y pakinggan,<br/>Salita Niya''y hawakan;<br/>Sundin Siya, manalangin:<br/>Magbantay!<br/>',NULL,41886,5);
INSERT INTO stanza VALUES('T765','6','Magbantay buong araw<br/>Nang dumating ang tanglaw<br/>Tulong na kai-langan pa:<br/>Magbantay!<br/>',NULL,41887,6);
INSERT INTO stanza VALUES('T767','1','Turuan Mong manalangin,<br/>Diyablo''y palayasin;<br/>Talunin pwersang masama,<br/>Bilanggo''y lumaya.<br/>',NULL,41888,1);
INSERT INTO stanza VALUES('T767','2','Turuang magdasal kami<br/>Tumayong mahusay;<br/>Talunin at pabagsakin,<br/>Kuta ng kalaban.<br/>',NULL,41889,2);
INSERT INTO stanza VALUES('T767','3','Turuan Mong manalangin,<br/>Layon Mo''y naisin;<br/>Lakas ng Iyong dugo ''kamtin<br/>Lupa''y payanigin.<br/>',NULL,41890,3);
INSERT INTO stanza VALUES('T767','4','Sa pananalig at dasal,<br/>Kata''y nagpapagal;<br/>Ang tagumpay ay atin na,<br/>Awtoridad Mo pa.<br/>',NULL,41891,4);
INSERT INTO stanza VALUES('T769','1','Hangarin kong mamuhay,<br/>Sa kabanal-banalan;<br/>B''yayang trono''y hipuin,<br/>Tubig Niya''y padaluyin.<br/>',NULL,41892,1);
INSERT INTO stanza VALUES('T769','2','Ang kabanal-banalan,<br/>Nasa ''king espiritu;<br/>Dito ang Panginoon,<br/>Nananahan, naugpong.<br/>',NULL,41893,2);
INSERT INTO stanza VALUES('T769','3','Sa ''spiritu''y babalik,<br/>Siya''y aking matagpuan;<br/>Ito''y kahanga-hanga!<br/>Kumpleto, sa loob Siya.<br/>',NULL,41894,3);
INSERT INTO stanza VALUES('T769','4','Samyo ng Kristong buhay,<br/>Sa loob ko nataglay.<br/>Sa ''spiritu magdasal,<br/>Kristo aking matanghal.<br/>',NULL,41895,4);
INSERT INTO stanza VALUES('T769','5','Kristong nasa ''spiritu,<br/>Hipuin nang matamo;<br/>Lahat Niyang kayamanan,<br/>Ako''y mapupuspusan.<br/>',NULL,41896,5);
INSERT INTO stanza VALUES('T769','6','Malalim na paghipo,<br/>Siya''y mararanasan ko;<br/>Kautusan ng buhay,<br/>Pagpapahid mataglay.<br/>',NULL,41897,6);
INSERT INTO stanza VALUES('T769','7','Higit na hinihipo,<br/>Higit na tumitimo;<br/>Ang malalim na Kristo,<br/>Ang mannang nakatago.<br/>',NULL,41898,7);
INSERT INTO stanza VALUES('T769','8','Pagkabuhay na muli,<br/>Karanasan kong tunay;<br/>Tungkod na namulaklak,<br/>Ako''y katanggap-tanggap.<br/>',NULL,41899,8);
INSERT INTO stanza VALUES('T769','9','Trono ng biyaya Mo,<br/>Natagpuan ko rito;<br/>Agos ng tubig-buhay,<br/>Mula sa trono''y taglay.<br/>',NULL,41900,9);
INSERT INTO stanza VALUES('T769','10','Nananalangin tayo,<br/>Napalaya''t nahalo;<br/>Sa ''ting mga ''spiritu,<br/>Saserdote nga tayo.<br/>',NULL,41901,10);
INSERT INTO stanza VALUES('T769','11','Sa kabanal-banalan,<br/>Mahipo Panginoon;<br/>Trono ng biyaya Niya,<br/>Lubusang matamasa.<br/>',NULL,41902,11);
INSERT INTO stanza VALUES('T770','1','Doon sa dakong kabanal-banal,<br/>Ilog ng b''yaya''y aagos;<br/>Trono ng b''yaya''y ating hipuin,<br/>Ilog ng b''yaya''y aagos.<br/>',NULL,41903,1);
INSERT INTO stanza VALUES('T770','chorus','Aleluya! Aleluya!<br/>Ilog ng b''yaya''y aagos;<br/>Aleluya! Aleluya!<br/>Ilog ng b''yaya''y aagos.<br/>',NULL,41904,2);
INSERT INTO stanza VALUES('T770','2','Doon sa dakong kabanal-banal,<br/>Ako''y laging namumuhay;<br/>At ang ilaw ng kal''walhatian<br/>Mula sa akin sisilay.<br/>',NULL,41905,3);
INSERT INTO stanza VALUES('T770','chorus','Aleluya! Aleluya!<br/>Mula sa akin sisilay;<br/>Aleluya! Aleluya!<br/>Mula sa akin sisilay.<br/>',NULL,41906,4);
INSERT INTO stanza VALUES('T770','3','Sa espiritu''y dapat bumaling,<br/>Ang kamangyan ay sunugin;<br/>Sa espiritu''y dapat bumaling,<br/>Batis ng buhay hipuin.<br/>',NULL,41907,5);
INSERT INTO stanza VALUES('T770','chorus','Aleluya! Aleluya!<br/>Batis ng buhay hipuin;<br/>Aleluya! Aleluya!<br/>Batis ng buhay hipuin.<br/>',NULL,41908,6);
INSERT INTO stanza VALUES('T771','1','Daang buháy ay nabuksan<br/>Nang tabing nahapak;<br/>Makadulog kami sa Iyo,<br/>Dahil sa Iyong dugo.<br/>',NULL,41909,1);
INSERT INTO stanza VALUES('T771','2','Nasa kabanal-banalan,<br/>Sanhi''ng katubusan;<br/>Pagpahid ng Iyong ''Spiritu,<br/>Trono ay nahipo.<br/>',NULL,41910,2);
INSERT INTO stanza VALUES('T771','3','Sa ''spiritu manalangin,<br/>Kami''y Iyong angkinin;<br/>Kristo sa ''ming espiritu<br/>Hayag ang insenso.<br/>',NULL,41911,3);
INSERT INTO stanza VALUES('T771','4','Mula sa trono ng b''yaya,<br/>May biyaya''t awa;<br/>Tulong na napapanahon,<br/>O anong yaman nga!<br/>',NULL,41912,4);
INSERT INTO stanza VALUES('T771','5','Di nga bagay dinalangin,<br/>''Spiritu lang sundin;<br/>Lahat ng kailangan namin<br/>Nilalaan lagi.<br/>',NULL,41913,5);
INSERT INTO stanza VALUES('T771','6','Bagama''t may bigat, hirap,<br/>Di na na''bagabag;<br/>Nang sa Iyo aming pinasa<br/>''Spiritu''y lumaya.<br/>',NULL,41914,6);
INSERT INTO stanza VALUES('T771','7','Sa pagsalamuha sa Iyo<br/>''Binuhos loob ko;<br/>Sundin lamang ''Spiritu Mo,<br/>Sa panalangin ko.<br/>',NULL,41915,7);
INSERT INTO stanza VALUES('T772','1','Nagtipon nanalangin,<br/>Nagkai-sa Kang hanapin;<br/>Banal na saserdote<br/>Naghihintay nga kami.<br/>',NULL,41916,1);
INSERT INTO stanza VALUES('T772','chorus','Mas mabuti''t mataas,<br/>Sa dalangin mahipo,<br/>Maghalo ''ming ''spiritu<br/>Ekklesia''y maitayo.<br/>',NULL,41917,2);
INSERT INTO stanza VALUES('T772','2','Magpakasaserdote,<br/>Nasa ''spiritu lagi;<br/>Batid Iyong kalooban,<br/>Layon may katuparan.<br/>',NULL,41918,3);
INSERT INTO stanza VALUES('T772','3','Sa kabanal-banalan<br/>Hipo''y b''yayang luklukan;<br/>''Spiritu Mo sa amin,<br/>Patuloy paraanin.<br/>',NULL,41919,5);
INSERT INTO stanza VALUES('T772','4','Mula sa luklukan Mo,<br/>Daloy ilog ng b''yaya;<br/>Hanggang sa ''spiritu ko,<br/>Tulong aking natamo.<br/>',NULL,41920,7);
INSERT INTO stanza VALUES('T772','5','Nawa''y aming dalangin,<br/>Bigkas ng Iyong damdamin;<br/>Di ayon sa sarili,<br/>Sa Iyo ayon paghingi.<br/>',NULL,41921,9);
INSERT INTO stanza VALUES('T772','6','Kahit maraming bagay,<br/>Dapat sa Iyo isaysay,<br/>Nguni''t Iyong ka-i-langan<br/>Kami''y maging daluyan.<br/>',NULL,41922,11);
INSERT INTO stanza VALUES('T772','7','Nawa kami''y pakinggan,<br/>Tubig ng buhay bigyan;<br/>Busugin sa biyaya<br/>Tupdin namin Iyong gawa.<br/>',NULL,41923,13);
INSERT INTO stanza VALUES('T775','1','Makapangyarihang Ngalan,<br/>Hesus, luluhod kami;<br/>Mabangis kaaway daig,<br/>Ang tagumpay mawagi.<br/>',NULL,41924,1);
INSERT INTO stanza VALUES('T775','chorus','Makapangyarihan,<br/>Mapagwaging pangalan!<br/>Gapi kasalanan,<br/>Satanas, kamatayan.<br/>',NULL,41925,2);
INSERT INTO stanza VALUES('T775','2','''Pag sinamo Ngalang Hesus,<br/>Tatakas hukbong diyablo;<br/>Hesus mahal, Hesus! Hesus!<br/>Sa Ngalan Mo''y panalo.<br/>',NULL,41926,3);
INSERT INTO stanza VALUES('T775','3','Sa pinagpalang araw nga,<br/>Magwawagi sa digma;<br/>May lakas na Ngalang Hesus,<br/>Sa trono kami''y ''takda.<br/>',NULL,41927,5);
INSERT INTO stanza VALUES('T776','1','Kay Hesus, manalig ka nga,<br/>Sa trono''y dumulog ka;<br/>Sa iyong pagtitiwala,<br/>Makita Kanyang gawa.<br/>',NULL,41928,1);
INSERT INTO stanza VALUES('T776','2','Sa pananalig humiling,<br/>Diyos handa kang sagutin;<br/>Gagawa Siya nang higit pa,<br/>Sa iyong inaakala.<br/>',NULL,41929,2);
INSERT INTO stanza VALUES('T776','3','Humiling sa pananalig,<br/>Isang hamong lalagi;<br/>Lipos ng galak, pag-asa,<br/>Pag-asam bukas-palad.<br/>',NULL,41930,3);
INSERT INTO stanza VALUES('T776','4','Manalig, huminging taos,<br/>Hinihintay ka ng Diyos,<br/>Ang nagbigay-lugod sa Diyos<br/>Pananalig mong lubos.<br/>',NULL,41931,4);
INSERT INTO stanza VALUES('T777','1','Bundok sabihan: "Sa dagat matapon ka!"<br/>Sa iyo''y matutupad kung di ka magduda;<br/>Manalig sa Salita Niya.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41932,1);
INSERT INTO stanza VALUES('T777','2','Sa dugo''y binili, kamtan pribileh''yo,<br/>Sa nagkaisang Trinidad epektibo;<br/>Sumunod sa Salita Niya.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41933,2);
INSERT INTO stanza VALUES('T777','3','Sarili, sakit, panglaw at kasalanan,<br/>Panginoon nagpasan, napalaya ka;<br/>Umasa sa Salita Niya.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41934,3);
INSERT INTO stanza VALUES('T777','4','Patuloy ang dasal, moog palibutan,<br/>Bago pa bumagsak, Poon papurihan;<br/>Panatag, maniwala ka.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41935,4);
INSERT INTO stanza VALUES('T777','5','Mga pintong tanso''t mga barang bakal,<br/>Susuungin ng nananalig na kawal;<br/>Kaaway iwaksi na nga.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41936,5);
INSERT INTO stanza VALUES('T777','6','Gamitin Kanyang pananampalataya,<br/>Tungkod gumagawa ng kamangha-mangha;<br/>Alisin lahat mong duda.<br/>Bundok mo''y iyong utusan na!<br/>',NULL,41937,6);
INSERT INTO stanza VALUES('T778','1','Umawit, manalig,<br/>Madilim man gabi;<br/>Kung pupuri, Diyos gagawa<br/>Hiling mo''y makuha.<br/>[Hiling mo''y makuha.]<br/>',NULL,41938,1);
INSERT INTO stanza VALUES('T778','2','Umawit, manalig,<br/>Puso''y palakasin;<br/>Pumuri, Diyos masiyahan,<br/>Gabi''y madilim man.<br/>[Gabi''y madilim man.]<br/>',NULL,41939,2);
INSERT INTO stanza VALUES('T778','3','Umawit, manalig,<br/>Diyablo''y manginginig;<br/>Huwag ipatikom iyong bibig,<br/>Papuri''y pandaig.<br/>[Papuri''y pandaig.]<br/>',NULL,41940,3);
INSERT INTO stanza VALUES('T778','4','Umawit, manalig,<br/>Sa pag-uumaga,<br/>Panginoon salubungin,<br/>Patuloy awitin.<br/>[Patuloy awitin.]<br/><!--(Ulitin ang huling linya ng bawa''t saknong)--><br/>',NULL,41941,4);
INSERT INTO stanza VALUES('T779','1','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Di isip kundi Iyong pahid,<br/>Tulad ng Iyong hangarin.<br/>',NULL,41942,1);
INSERT INTO stanza VALUES('T779','chorus','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Di isip kundi Iyong pahid,<br/>Tulad ng Iyong hangarin.<br/>',NULL,41943,2);
INSERT INTO stanza VALUES('T779','2','Magkaisang manalangin<br/>Sa ating espiritu;<br/>Kalul''wa, nais, layunin,<br/>Supilin ng ''Spiritu.<br/>',NULL,41944,3);
INSERT INTO stanza VALUES('T779','3','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Lupang hilig ay yurakan,<br/>Labanan pamunuan.<br/>',NULL,41945,5);
INSERT INTO stanza VALUES('T779','4','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Panalanging sama-sama,<br/>Hangad Poon manguna.<br/>',NULL,41946,7);
INSERT INTO stanza VALUES('T779','5','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Para kaharian, gloria<br/>Magbantay nang matiyaga.<br/>',NULL,41947,9);
INSERT INTO stanza VALUES('T779','6','Magkaisang manalangin<br/>Sa ating espiritu,<br/>Diyos hangad sa kaisahan,<br/>''Spiritu ng Katawan.<br/>',NULL,41948,11);
INSERT INTO stanza VALUES('T780','1','Dasal lagi sa ''spiritu<br/>Di sa laman, isipan!<br/>Kung lihim ay matutuhan,<br/>Diyos ating masumpungan.<br/>',NULL,41949,1);
INSERT INTO stanza VALUES('T780','chorus','Dasal lagi sa ''spiritu,<br/>Ito nga ang sikreto!<br/>Sa ''spiritu Diyos ugnayin,<br/>Lihim dapat taglayin.<br/>',NULL,41950,2);
INSERT INTO stanza VALUES('T780','2','Dasal lagi sa ''spiritu,<br/>Huwag ayon sa isip mo;<br/>Sa Diyos makisalamuha,<br/>Gayon Siyang makukuha.<br/>',NULL,41951,3);
INSERT INTO stanza VALUES('T780','3','Sa espiritu ang dasal,<br/>Nais ng Diyos matanghal;<br/>Tuloy ugnayan kay Kristo,<br/>Nang mapaningas tayo.<br/>',NULL,41952,5);
INSERT INTO stanza VALUES('T780','4','Dasal lagi sa ''spiritu,<br/>Hibik kaibuturan,<br/>''Spiritung nagdisiplina,<br/>Layon Niya''y sinalita.<br/>',NULL,41953,7);
INSERT INTO stanza VALUES('T780','5','Sa ''spiritu manalangin,<br/>Sa pinakabanal din;<br/>Tangi lamang sa ''spiritu,<br/>Diyos, tao magkahalo.<br/>',NULL,41954,9);
INSERT INTO stanza VALUES('T780','6','Dasal lagi sa ''spiritu<br/>Tanging daan ay ito;<br/>Kapuspusan ng Pagka-Diyos,<br/>Ibahagi natin ''to.<br/>',NULL,41955,11);
INSERT INTO stanza VALUES('T781','1','Nais manalangin sundin ''spiritu,<br/>Konting dalangin ''spiritu''y malabo;<br/>Nagdasal ma''y ''spiritu di ginamit,<br/>Bagay lang dinasal ''spiritu''y waglit.<br/>',NULL,41956,1);
INSERT INTO stanza VALUES('T781','2','Magdasal at humibik sa ''spiritu,<br/>Sa pagpapahid Niya, di sa isip ko;<br/>Di na sa isip kundi sa ''spiritu,<br/>Pagpuri''t paghingi, sundin ''spiritu.<br/>',NULL,41957,2);
INSERT INTO stanza VALUES('T781','3','Di lamang magdasal nang nag-iisa,<br/>''Spiritu''y ensayuhing may kasama;<br/>Di sa panlabas kundi sa ''spiritu,<br/>Dalangin may tugon sa ''Spiritu Mo.<br/>',NULL,41958,3);
INSERT INTO stanza VALUES('T781','4','Di maglilingkod nang walang dalangin,<br/>Di maaaring labi lang gamitin;<br/>Di basta''t manalanging magkasama,<br/>Walang tunay na pagsasalamuha.<br/>',NULL,41959,4);
INSERT INTO stanza VALUES('T781','5','Saan ma''y maaaring manalangin,<br/>Basta''t may tao ''spiritu''y gamitin;<br/>Di dapat mahadlangan ng anuman<br/>Bawa''t pagpupulong may kalayaan.<br/>',NULL,41960,5);
INSERT INTO stanza VALUES('T781','6','''Spiritung napataas at malakas,<br/>Ako''y magamit, Pangino''n may landas;<br/>Sa buháy na tubig banal mahalo,<br/>Sa daloy nito ekklesia''y matayo.<br/>',NULL,41961,6);
INSERT INTO stanza VALUES('T782','1','Kay hiwaga, Pangino''n,<br/>Espiritu Mo''y sa ''kin;<br/>Kamangha-mangha ngayon,<br/>Dalawa''y pag-isahin.<br/>',NULL,41962,1);
INSERT INTO stanza VALUES('T782','2','Ayon sa espiritu,<br/>Espirituwal lumakad;<br/>Maglingkod sa ''spiritu,<br/>Sumamba sa Iyo lahat.<br/>',NULL,41963,2);
INSERT INTO stanza VALUES('T782','3','Salita Mo''y basahin,<br/>At tuwing manalangin,<br/>Espiritu''y hipuin,<br/>At ako''y palakasin.<br/>',NULL,41964,3);
INSERT INTO stanza VALUES('T782','4','Espiritung malakas,<br/>Bubuhayin ang iba;<br/>Espiritung maningas,<br/>Palayain ang iba.<br/>',NULL,41965,4);
INSERT INTO stanza VALUES('T782','5','T''wing ako''y magsalita,<br/>Espiritu''y kumilos,<br/>Kahit anong paggawa,<br/>Espiritu''y mapuspos.<br/>',NULL,41966,5);
INSERT INTO stanza VALUES('T782','6','Pag gumawa''y ''spiritu,<br/>Mabubuksan ang iba;<br/>Pag kumilos ''spiritu,<br/>Maaahon ang iba.<br/>',NULL,41967,6);
INSERT INTO stanza VALUES('T782','7','Panginoon dinggin Mo,<br/>Espiritu ''ko''y hipan,<br/>Yayaman ang ''spiritu<br/>Lakas ay maragdagan.<br/>',NULL,41968,7);
INSERT INTO stanza VALUES('T783','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41969,1);
INSERT INTO stanza VALUES('T783','1','Hipuin trono ng Diyos,<br/>Sa panalanging taos;<br/>Matagpuan Mo doon,<br/>Biyaya, awang tulong.<br/>',NULL,41970,2);
INSERT INTO stanza VALUES('T783','2','Hipuin trono ng Diyos,<br/>Damang kai-langa''y b''yaya;<br/>Sa ''spiritu''y kasama,<br/>Diyos sa pagsalamuha.<br/>',NULL,41971,3);
INSERT INTO stanza VALUES('T783','3','Hipuin trono ng Diyos,<br/>Yaman ng biyaya Niya;<br/>Kunin at tamasahin,<br/>Pati ang Diyos purihin.<br/>',NULL,41972,4);
INSERT INTO stanza VALUES('T783','4','Hipuin trono ng Diyos,<br/>Tronong awtoridad nga;<br/>Sa pangalan ni Kristo,<br/>Natuos Hades, diyablo.<br/>',NULL,41973,5);
INSERT INTO stanza VALUES('T783','5','Hipuin trono ng Diyos,<br/>Sa pagsampalataya,<br/>Awtoridad gamitin<br/>Kamatayan talunin.<br/>',NULL,41974,6);
INSERT INTO stanza VALUES('T783','6','Hipuin trono ng Diyos,<br/>Lakas-Hades nauga;<br/>Awtoridad ng Hari<br/>Sa dalangi''y isapi.<br/>',NULL,41975,7);
INSERT INTO stanza VALUES('T784','1','Kay Hesus ka manalangin,<br/>Mukha Niya ay hanapin;<br/>Salita Niya ay iyong dinggin,<br/>Sa lihim Siya''y hintayin.<br/>',NULL,41976,1);
INSERT INTO stanza VALUES('T784','chorus','Kay Hesus ka manalangin,<br/>Mukha Niya ay hanapin;<br/>Salita Niya ay iyong dinggin,<br/>Sa lihim Siya''y hintayin.<br/>',NULL,41977,2);
INSERT INTO stanza VALUES('T784','2','Kay Hesus ka manalangin,<br/>Sa mukha''t pusong bukás;<br/>Lagi sa Kanya tumingin,<br/>Tapat, tunay, at wagas.<br/>',NULL,41978,3);
INSERT INTO stanza VALUES('T784','3','Kay Hesus ka manalangin,<br/>Manalig sa paghanap;<br/>Ang Espiritu''y hipuin,<br/>Mapitagan, masikap.<br/>',NULL,41979,5);
INSERT INTO stanza VALUES('T784','4','Kay Hesus ka manalangin,<br/>Tunay sa espiritu,<br/>Alinsunod sa damdamin,<br/>Ayon sa espiritu.<br/>',NULL,41980,7);
INSERT INTO stanza VALUES('T784','5','Kay Hesus ka manalangin,<br/>Taimtim kang makinig;<br/>Layon Niya sa iyo itanim,<br/>Tupdin mo Kanyang ibig.<br/>',NULL,41981,9);
INSERT INTO stanza VALUES('T784','6','Kay Hesus ka manalangin,<br/>Magbabad sa liwanag;<br/>L''walhati Niya''y palagusin,<br/>Sa iyo Siya''y maaninag.<br/>',NULL,41982,11);
INSERT INTO stanza VALUES('T785','1','Sa dasal ihayag Siya,<br/>Di ating sarili nga,<br/>Kundi si Kristo Mismo<br/>Makintal Kanyang gusto.<br/>',NULL,41983,1);
INSERT INTO stanza VALUES('T785','2','Sa dasal ihayag Siya,<br/>Bigkasin intensyon Niya,<br/>Isip patahimikin<br/>Sa Kanya kaisa rin.<br/>',NULL,41984,2);
INSERT INTO stanza VALUES('T785','3','Sa dasal ihayag Siya,<br/>Tumitingin sa Kanya;<br/>Tulad nang sa salamin,<br/>Gloria Niya''y aninagin.<br/>',NULL,41985,3);
INSERT INTO stanza VALUES('T785','4','Sa dasal ihayag Siya,<br/>Siyang Kristong nagsalita:<br/>Kristo sa loob natin,<br/>Sa Kristong nasa langit.<br/>',NULL,41986,4);
INSERT INTO stanza VALUES('T785','5','Sa dasal ihayag Siya,<br/>Hindi sa sarili nga,<br/>Lubusang kasama Siya,<br/>Sa pamamagitan Niya.<br/>',NULL,41987,5);
INSERT INTO stanza VALUES('T786','1','Kasama Siyang magpagal,<br/>Daan buksan sa dasal;<br/>Pakilusin tayo''t Siya,<br/>Mula sentro''t gilid pa.<br/>',NULL,41988,1);
INSERT INTO stanza VALUES('T786','2','Kasamang magpagal Siya,<br/>Makilalang kai-sa Niya.<br/>Sa dalangi''t layunin<br/>Pagpala''y pabahain.<br/>',NULL,41989,2);
INSERT INTO stanza VALUES('T786','3','Kasama Siyang magpagal,<br/>Ambisyon ko''y matanggal;<br/>Maging sariling pasya<br/>Kundi layon lamang Niya.<br/>',NULL,41990,3);
INSERT INTO stanza VALUES('T786','4','Kasama Siyang magpagal,<br/>Manguna Siya sa dasal;<br/>Lahat ng gawa''t plano,<br/>Ang nagtupad Siya''t tayo.<br/>',NULL,41991,4);
INSERT INTO stanza VALUES('T786','5','Kasama Siyang magpagal,<br/>Kasama Siyang magdasal;<br/>Hanggang gulong umikot;<br/>Ekklesia ay sumunod.<br/>',NULL,41992,5);
INSERT INTO stanza VALUES('T787','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,41993,1);
INSERT INTO stanza VALUES('T787','1','Kay Hesus ay dapat kong sabihin,<br/>Di na makaya ang pasanin;<br/>Sa pighati ko ako''y tulungan,<br/>Kanyang inibig, iningatan.<br/>',NULL,41994,2);
INSERT INTO stanza VALUES('T787','chorus','Kay Hesus ay dapat kong sabihin,<br/>Di na makaya ang pasanin;<br/>Kay Hesus ay dapat kong sabihin,<br/>Si Hesus lang tutulong sa ''kin.<br/>',NULL,41995,3);
INSERT INTO stanza VALUES('T787','2','Kay Hesus ay dapat kong sabihin.<br/>Hirap di ko kayang harapin;<br/>Lahat kong bagay Siya nang magpasan,<br/>Upang ako''y may kaaliwan.<br/>',NULL,41996,4);
INSERT INTO stanza VALUES('T787','3','Kay Hesus ay dapat kong sabihin,<br/>Kakulangan ko''y ''king aminin;<br/>Siya ang tutustos sa ''king kailangan<br/>Ng mayamang katamasahan.<br/>',NULL,41997,6);
INSERT INTO stanza VALUES('T787','4','Kay Hesus ay dapat kong sabihin,<br/>Panglaw di ko kayang daigin;<br/>Sa ''king gapos ako''y kalagan Niya,<br/>Ako''y mapalaya sa sala.<br/>',NULL,41998,8);
INSERT INTO stanza VALUES('T787','5','Kay Hesus ay dapat kong sabihin,<br/>Diyablo di ko kayang talunin;<br/>Tukso ng mundo sa ''kin nang-akit,<br/>Hesus ko sa samá daraig.<br/>',NULL,41999,10);
INSERT INTO stanza VALUES('T789','1','Si Hesus ating Kaibigan,<br/>Hirap nati''y pinasan,<br/>Nagbigay ng karapatan<br/>Diyos ay madalanginan!<br/>Gaanong lumbay at dusa<br/>Ang ating binabata<br/>Pagka''t di natin nilagak<br/>Sa Diyos ang ating lahat.<br/>',NULL,42000,1);
INSERT INTO stanza VALUES('T789','2','May tukso ba''t kaguluhan?<br/>Tayo''y sinusubukan?<br/>Hindi dapat manglupaypay,<br/>Sa Diyos natin isaysay.<br/>Si Kristo ba''y may katulad<br/>Sa pagdamay sa hirap?<br/>Talos Niya ang kahinaan,<br/>Sa Kanya ipapasan.<br/>',NULL,42001,2);
INSERT INTO stanza VALUES('T789','3','Mabigat ba ang pasanin,<br/>Mga alalahanin?<br/>Kay Hesus mo idalangin,<br/>At Kanyang aalisin.<br/>Kung kaibigan mo''y lumimot,<br/>Idalangin mo sa Diyos;<br/>Kanyang kamay ang iyong taklob,<br/>Panatag ang iyong loob.<br/>',NULL,42002,3);
INSERT INTO stanza VALUES('T791','1','Saserdoteng pwesto''y banal,<br/>Lagi sa Diyos nag-aalay<br/>Kanyang rilag minamasdan,<br/>Sunugin kamangyan.<br/>',NULL,42003,1);
INSERT INTO stanza VALUES('T791','chorus','Insenso''y sunugin<br/>Tayo''y manalangin;<br/>Ilawan ating sindihan<br/>Siya ay papurihan!<br/>',NULL,42004,2);
INSERT INTO stanza VALUES('T791','2','Likas na liwanag wala,<br/>Kundi sa ilawan lamang;<br/>Kapag sinunog kamangyan<br/>Sisilay ilawan.<br/>',NULL,42005,3);
INSERT INTO stanza VALUES('T791','3','Biyaya ng Diyos mapuri,<br/>Pukawin pusong umawit;<br/>Saserdoteng gawa''y lagi,<br/>Mag-ukol papuri.<br/>',NULL,42006,5);
INSERT INTO stanza VALUES('T791','4','Nang sinusunog insenso,<br/>Kristong nabuhay handog ko;<br/>Nais ng Diyos natugunan<br/>Siya''t ako''y nas''yahan.<br/>',NULL,42007,7);
INSERT INTO stanza VALUES('T791','5','Sa pagbasa ng Salita,<br/>Liwanag aking nakuha;<br/>Gaya''y nasinding ilawan,<br/>May kaliwanagan.<br/>',NULL,42008,9);
INSERT INTO stanza VALUES('T791','6','Himno aking aawitin<br/>Gaya ng saserdote rin;<br/>Purihin b''yaya, pagsinta,<br/>Puso''y napuno Niya.<br/>',NULL,42009,11);
INSERT INTO stanza VALUES('T791','7','Dasal sa Diyos handog Kristo,<br/>Pagbasa, liwanagan Mo;<br/>Aawit dahil sa biyaya,<br/>''Spiritu''y malaya!<br/>',NULL,42010,13);
INSERT INTO stanza VALUES('T792','1','Naghihintay sa Iyo, Pangino''n;<br/>Mamahinga sa Iyo;<br/>Liwanagan ako<br/>Sa kalooban Mo—<br/>Naghihintay ako sa Iyo.<br/>',NULL,42011,1);
INSERT INTO stanza VALUES('T792','2','Naghihintay sa Iyo, Pangino''n;<br/>Habang naririto,<br/>Daan Mo''y ituro,<br/>Sa Iyo''y sumasamo—<br/>Naghihintay ako sa Iyo.<br/>',NULL,42012,2);
INSERT INTO stanza VALUES('T792','3','Naghihintay sa Iyo, Pangino''n;<br/>Sa ''kin humalo Ka,<br/>Hanggang makaisa,<br/>Maging larawan pa—<br/>Naghihintay ako sa Iyo.<br/>',NULL,42013,3);
INSERT INTO stanza VALUES('T792','4','Naghihintay sa Iyo, Pangino''n;<br/>Malaman naisin,<br/>Landas Mo''y tahakin,<br/>Buhay paagusin—<br/>Naghihintay ako sa Iyo.<br/>',NULL,42014,4);
INSERT INTO stanza VALUES('T792','5','Naghihintay sa Iyo, Pangino''n;<br/>Lahat kong dalangin,<br/>Mahayag Ka sa ''kin,<br/>''Pabatid Mo''ng lihim—<br/>Naghihintay ako sa Iyo.<br/>',NULL,42015,5);
INSERT INTO stanza VALUES('T793','1','Manahimik aking kaluluwa,<br/>Maghintay ka bago magsalita;<br/>Tunay mong dasal Siyang may umpisa,<br/>Daluyan ka nga nang mahayag Siya.<br/>',NULL,42016,1);
INSERT INTO stanza VALUES('T793','2','Manahimik aking kaluluwa,<br/>Hintayin Kanyang pagsasalita.<br/>Matutong talikdan isipan mo<br/>Layon Niya matupad sa dasal mo.<br/>',NULL,42017,2);
INSERT INTO stanza VALUES('T793','3','Manahimik aking kaluluwa,<br/>Hintayin Kanyang pagsasalita;<br/>Bitiwan iyong balak, huwag mamili,<br/>Nais lamang Niya ang di itabi.<br/>',NULL,42018,3);
INSERT INTO stanza VALUES('T793','4','Manahimik aking kaluluwa,<br/>Hintayin Kanyang pagsasalita;<br/>Puso mo sa ''spiritu isuko,<br/>Nang makasunod sa Iyo lingkod Mo.<br/>',NULL,42019,4);
INSERT INTO stanza VALUES('T793','5','Manahimik aking kaluluwa,<br/>Hintayin Kanyang pagsasalita;<br/>Matutong sa ''spiritu''y mahalo,<br/>Nang Diyos mahayag sa dalangin mo.<br/>',NULL,42020,5);
INSERT INTO stanza VALUES('T793','6','Manahimik aking kaluluwa,<br/>Maghintay sa Kanyang pagtutugma;<br/>Buong katauhan mapasuko,<br/>Sa wangis ng Anak ay lumago.<br/>',NULL,42021,6);
INSERT INTO stanza VALUES('T793','7','Manahimik aking kaluluwa,<br/>Hintayin Kanyang pagpapalaya;<br/>Lahat ng salita at gawa mo,<br/>Katuparan ng nais Niya sa iyo.<br/>',NULL,42022,7);
INSERT INTO stanza VALUES('T797','1','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Sa banal magpakita Ka,<br/>Sa ''min magsalita!<br/>',NULL,42023,1);
INSERT INTO stanza VALUES('T797','chorus','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Habang kami naghihintay,<br/>Kami''y mapagpala!<br/>',NULL,42024,2);
INSERT INTO stanza VALUES('T797','2','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Apoy nga ng Pentecostes,<br/>Magningas sa puso!<br/>',NULL,42025,3);
INSERT INTO stanza VALUES('T797','3','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Pag-ibig Mo sa ''ming puso,<br/>Umalab nang husto!<br/>',NULL,42026,5);
INSERT INTO stanza VALUES('T797','4','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Pagpalain Iyong Salita,<br/>Nang may maniwala!<br/>',NULL,42027,7);
INSERT INTO stanza VALUES('T797','5','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Palakasin ang Iyong lingkod,<br/>Gawin ang Iyong lugod.<br/>',NULL,42028,9);
INSERT INTO stanza VALUES('T797','6','Panauliin nga,<br/>Poon, ang Iyong gawa!<br/>Mapasa Iyo lamang gloria!<br/>Amin pagpapala!<br/>',NULL,42029,11);
INSERT INTO stanza VALUES('T799','1','Kasulatan ay hininga ng Diyos,<br/>Sa ''Spiritu salita''y nahinga;<br/>Sinulat ng maka-Diyos na tao,<br/>Kapuspusan ng Diyos ''pinamana.<br/>',NULL,42030,1);
INSERT INTO stanza VALUES('T799','2','Hininga ng Diyos bilang liwanag,<br/>Mga tao ay iniilawan;<br/>Sa karimlan tao''y inilantad,<br/>Tunay niyang kailanga''t kalagayan.<br/>',NULL,42031,2);
INSERT INTO stanza VALUES('T799','3','Ang hininga ng Diyos bilang buhay,<br/>Binahagi''y likas na dibino;<br/>Patay-binuhay, ''sinilang-muli,<br/>Puso''t kaluluwa''y binabago.<br/>',NULL,42032,3);
INSERT INTO stanza VALUES('T799','4','Hininga ng Diyos ay karunungan,<br/>Turo ay dibinong kaalaman;<br/>Hinayag layon ng Panginoon,<br/>At hantungan ng Diyos ay maratnan.<br/>',NULL,42033,4);
INSERT INTO stanza VALUES('T799','5','Hininga ng Diyos ay kalakasan,<br/>Kapangyarihan ay dinadala;<br/>Mahina''t lupaypay pinalakas,<br/>Sa layon ng Diyos tao''y iakma.<br/>',NULL,42034,5);
INSERT INTO stanza VALUES('T799','6','Langhapin natin hininga ng Diyos,<br/>Diyos bahagi nati''y matamasa;<br/>Sa ''spiritu, tinatanggap ito,<br/>Sa kailangan, magamit yaman Niya.<br/>',NULL,42035,6);
INSERT INTO stanza VALUES('T800','1','Diyos ay nagwika, Diyos ay naihayag,<br/>Ang persona Niya''y lubusang nahayag;<br/>Sa tao''y ibinunyag hiwaga Niya,<br/>Inilarawan at ipinakita.<br/>',NULL,42036,1);
INSERT INTO stanza VALUES('T800','2','Diyos ay nagwika, puso Niya''y ''nilahad,<br/>Anak Niya''y may unang puwesto sa lahat,<br/>Upang Siya''y mal''walhati sa Anak Niya<br/>Sa gitna ng lahat ng sangnilikha.<br/>',NULL,42037,2);
INSERT INTO stanza VALUES('T800','3','Diyos ay nagwika, nahayag si Kristo,<br/>Siya Mismo ang Diyos, at tunay na tao;<br/>Siyang lahat sa Kanya''y umiral lahat,<br/>Sentro''t palibot ng dibinong balak.<br/>',NULL,42038,3);
INSERT INTO stanza VALUES('T800','4','Diyos nagwika, nahayag ang hiwaga,<br/>Panukala''y Kristo''t kahayagan Niya:<br/>Kristo ang malwalhating Ulo nga,<br/>Kapuspusan, Katawan ang Ekklesia.<br/>',NULL,42039,4);
INSERT INTO stanza VALUES('T800','5','Diyos ay nagwika, sa langit makita,<br/>Tres-unong Diyos sa tao''y nai-halo na,<br/>Ama''y sa Anak, Anak ay ''Spiritu,<br/>Nasa Katawan, tupdin Kanyang plano.<br/>',NULL,42040,5);
INSERT INTO stanza VALUES('T800','6','Diyos nagwika, pahayag nadulutan<br/>Ng Kanyang sangnilikha''t pagkasilang,<br/>Dakilang katubusan, kaligtasan;<br/>Sambahin Siya sa buong sanlibutan.<br/>',NULL,42041,6);
INSERT INTO stanza VALUES('T801','1','Salita at larawan ng Diyos Ka,<br/>Laman ng salitang nakatala:<br/>Kapuspusan ng Diyos nasumpungan,<br/>Narinig Kita sa Kasulatan.<br/>',NULL,42042,1);
INSERT INTO stanza VALUES('T801','2','Liban sa Iyo, Diyos ay di makita,<br/>Kung walang Biblia di Ka makita;<br/>Dineklara Ka ng Diyos sa tao,<br/>At sa Biblia Ika''y nakita ko.<br/>',NULL,42043,2);
INSERT INTO stanza VALUES('T801','3','Sa Diyos, Ikaw ang pagkakatawan,<br/>Larawang dulot ng Kasulatan;<br/>Sa Iyo, larawan ng Diyos natanto,<br/>Sa Kasulatan, Ika''y totoo.<br/>',NULL,42044,3);
INSERT INTO stanza VALUES('T801','4','Espiritung buhay Ka''t Salita,<br/>Espiritung nasa Salita Ka;<br/>Sa ''Spiritu Salitang mahipo,<br/>Kapuspusang dibino''y taglay ko.<br/>',NULL,42045,4);
INSERT INTO stanza VALUES('T801','5','Sa Iyo, sa Diyos ay may salamuha,<br/>Sa Salita''y makakain Kita;<br/>Sa pagbasa at dalangin sa Diyos<br/>Mal''walhating yaman aking tustos.<br/>',NULL,42046,5);
INSERT INTO stanza VALUES('T801','6','Turuang sanayin ''spiritu ko,<br/>Makaugnay Ka sa Salita Mo,<br/>Ikaw, buhay na Salita, Biblia,<br/>Naging pang-araw-araw kong manna.<br/>',NULL,42047,6);
INSERT INTO stanza VALUES('T802','1','Salita Ka''t Espiritu<br/>Sinasamba sa ''spiritu;<br/>Sa Salita naunawa,<br/>Sa ''Spiritu kaugnay Ka.<br/>',NULL,42048,1);
INSERT INTO stanza VALUES('T802','2','Yamang kata''y nakaisa,<br/>Poon, sa akin lahat Ka;<br/>Bilang ''Spiritu''t Salita,<br/>Mapasa''kin panustos Ka.<br/>',NULL,42049,2);
INSERT INTO stanza VALUES('T802','3','Kung Poon Ka''t di Salita,<br/>Pa''no Kang makikilala?<br/>Kung Diyos Ka''t di Espiritu,<br/>Paano Kang mahihipo?<br/>',NULL,42050,3);
INSERT INTO stanza VALUES('T802','4','Inihayag ng Salita<br/>Ikaw, nang makilala Ka,<br/>Elemento Mo''y ''Spiritu,<br/>Kita''y aking mahihipo.<br/>',NULL,42051,4);
INSERT INTO stanza VALUES('T802','5','Buhay Kita''t ilaw, landas,<br/>Pagkain, garant''ya''t lakas;<br/>Sa Salita ay nalaman,<br/>Sa ''Spiritu''y naranasan.<br/>',NULL,42052,5);
INSERT INTO stanza VALUES('T802','6','Salita sa Kasulatan<br/>Espiritu''y Nananahan;<br/>Salita''y buhay, ''spiritu<br/>Pagpasok sa ''spiritu ko.<br/>',NULL,42053,6);
INSERT INTO stanza VALUES('T802','7','Nang maarok Salita Mo,<br/>Hipuin ''Spiritu Santo;<br/>Di lang isip ang gamitin,<br/>Sa ''spiritu''y manalangin.<br/>',NULL,42054,7);
INSERT INTO stanza VALUES('T802','8','Mahal ko ang Iyong Salita,<br/>Ika''y makasalamuha;<br/>Puso ko ay nagsasaya,<br/>Sa Salita, purihin Ka.<br/>',NULL,42055,8);
INSERT INTO stanza VALUES('T803','1','Salitang naging laman,<br/>Anong Karunungan!<br/>Takdang Katotohanan,<br/>Ilaw sa karimlan,<br/>Sinag Mo''y tinatanghal;<br/>Sa pahinang banal,<br/>Tanglaw sa bawa''t hakbang,<br/>Ningning walang hanggan.<br/>',NULL,42056,1);
INSERT INTO stanza VALUES('T803','2','Tanggap ng Ekklesia,<br/>Banal kaloob Niya,<br/>Itinaas niyang ilaw,<br/>Sa lupa''y tumanglaw:<br/>Ang ginintuang yaman<br/>Ng katotohanan;<br/>Salitang buháy: Kristo<br/>''Nilarawan nito.<br/>',NULL,42057,2);
INSERT INTO stanza VALUES('T803','3','Hukbo ng Diyos kaharap<br/>Gaya''y ''sang watawat;<br/>Parolang nagniningning,<br/>Sa mundong madilim;<br/>Ito''y mapa at gabay<br/>Sa dagat ng buhay,<br/>Giya tungo kay Kristo,<br/>Daan ma''y mabato.<br/>',NULL,42058,3);
INSERT INTO stanza VALUES('T803','4','Gawing patungang ginto,<br/>Ang Ekklesia Mo,<br/>Nang magsilay ng ilaw<br/>Sa lahat tumanglaw;<br/>Manlalakbay turuan<br/>Nitong wastong daan,<br/>Hanggang dilim magwakas,<br/>Iyong mukha''y mamalas.<br/>',NULL,42059,4);
INSERT INTO stanza VALUES('T804','1','Ang Iyong Salita''y imbakan,<br/>Panustos, kay yaman;<br/>Ang may nais pumarito,<br/>Yaman pagsaluhan.<br/>Minahan ang Iyong Salita,<br/>Hiyas na bihira;<br/>Nakakubli sa ilalim,<br/>Dapat na tuklasin.<br/>',NULL,42060,1);
INSERT INTO stanza VALUES('T804','2','Iyong Salita''y tila bituin,<br/>Marami''t maningning,<br/>Liwanag sa manlalakbay,<br/>Giya at patnubay.<br/>Iyong Salita ay sakbatan,<br/>Doon matagpuan<br/>Mga sandatang kailangan,<br/>Para sa labanan.<br/>',NULL,42061,2);
INSERT INTO stanza VALUES('T804','3','Salita Mo''y iibigin,<br/>Mina''y saliksikin,<br/>Kayamanan nito''y kamtin,<br/>Ilaw ay magningning.<br/>Baluti ko''y Iyong Salita,<br/>Tabak ay pag-asa;<br/>Matutuhan kong labanan.<br/>Lahat ng kalaban.<br/>',NULL,42062,3);
INSERT INTO stanza VALUES('T804','4','Ang kalooban ng Anak,<br/>Buháy na Salita;<br/>Diyos at Kristo''y di makuha<br/>Kung Salita''y wala.<br/>Nawa''y aming matutuhan,<br/>Kanyang karunungan,<br/>At sa aral makalangit,<br/>Puso''y mapalapit.<br/>',NULL,42063,4);
INSERT INTO stanza VALUES('T805','1','Mahal kong banal na Aklat!<br/>B''yayang nagtubos nilahad;<br/>Liham ng pag-ibig Ni-ya,<br/>Salamin ng Kanyang mukha.<br/>',NULL,42064,1);
INSERT INTO stanza VALUES('T805','2','Mahal kong banal na Aklat!<br/>Tseke ng bangko sa langit;<br/>Pamanang makalangit ko,<br/>Habilin Niyang testamento.<br/>',NULL,42065,2);
INSERT INTO stanza VALUES('T805','3','Mahal kong banal na Aklat!<br/>Gaya Ka ng teleskopyo,<br/>Nang darating ay makita<br/>Mga l''walhati''t himala.<br/>',NULL,42066,3);
INSERT INTO stanza VALUES('T805','4','Mahal kong banal na Aklat!<br/>Gabay sa panlupang lakad;<br/>Sa kadiliman ay tanglaw<br/>Liwanag sa araw-araw.<br/>',NULL,42067,4);
INSERT INTO stanza VALUES('T806','1','Tinapay ng Buhay<br/>Pirasuhin,<br/>Tulad Panginoon<br/>Sa baybayin;<br/>Espiritu''y uhaw<br/>Sa Salita;<br/>Sa pahinang banal<br/>Hanapin Ka.<br/>',NULL,42068,1);
INSERT INTO stanza VALUES('T806','2','Tinapay ng Buhay<br/>Ka sa akin,<br/>Banal Mong Salita<br/>Nagligtas din;<br/>Mabuhay, kumain<br/>Kasama Mo,<br/>Turuang mahalin<br/>Ang totoo.<br/>',NULL,42069,2);
INSERT INTO stanza VALUES('T806','3','Isugo sa akin<br/>Espiritu,<br/>Mata ko''y hipuin<br/>Makatanto;<br/>Katotohanan Mo<br/>Ipakita;<br/>Sa I-yong Salita<br/>Makita Ka.<br/>',NULL,42070,3);
INSERT INTO stanza VALUES('T806','4','Katotohanan Mo<br/>Pagpalain,<br/>Nang sa Galilea<br/>Nagpala Ka;<br/>Gapos, tanikala<br/>Ay mawala,<br/>Kapayapaan ko<br/>Makikita.<br/>',NULL,42071,4);
INSERT INTO stanza VALUES('T807','1','Iyong buksan ang aking mata,<br/>Katotohana''y makita;<br/>Susing bigay kahanga-hanga,<br/>Sa akin magpapalaya.<br/>',NULL,42072,1);
INSERT INTO stanza VALUES('T807','chorus','Tahimik naghintay ako,<br/>Handang tingnan naisin Mo;<br/>Bigyang ilaw paningin ko,<br/>O ''Spiritu!<br/>',NULL,42073,2);
INSERT INTO stanza VALUES('T807','2','Pandinig ko ay Iyong buksan,<br/>Marinig katotohanan;<br/>Habang binubulungan ako,<br/>Bawa''t huwad maglalaho.<br/>',NULL,42074,3);
INSERT INTO stanza VALUES('T807','3','Aking bibig ay buksan Mo,<br/>Ilahad ang ebanghelyo;<br/>Buksan puso ko''t maghahanda,<br/>Pag-ibig Mo''y ''bahagi nga.<br/>',NULL,42075,5);
INSERT INTO stanza VALUES('T807','4','Buksan Mo ang aking isip,<br/>Pag-ibig Mo ay malirip;<br/>Ano pa ang aking pangamba,<br/>Habang Ika''y nangunguna?<br/>',NULL,42076,7);
INSERT INTO stanza VALUES('T808','1','Poon, magsalita sa ''kin,<br/>Ako ay nakikinig,<br/>Hangad tinig Mo''y umaliw,<br/>Poon, ang maulinig.<br/>Tinig Mo ay diringgin;<br/>Ano ang sasabihin?<br/>',NULL,42077,1);
INSERT INTO stanza VALUES('T808','2','Madalas sa aking puso,<br/>May ibang alingawngaw;<br/>Dagundong, di sa Iyong templo,<br/>Aking diwa''y inagaw.<br/>Tinig Mo''y iparinig,<br/>Lahat ay matahimik.<br/>',NULL,42078,2);
INSERT INTO stanza VALUES('T808','3','Huwag tulutan na lumisan,<br/>Kung di Ka maririnig;<br/>Puso ko''y Iyong nalalaman,<br/>Nais ko ang Iyong tinig.<br/>Talos Mo kai-langan ko;<br/>Pagpalain Mo ako.<br/>',NULL,42079,3);
INSERT INTO stanza VALUES('T808','4','Magwika, at Iyong ihanda,<br/>Upang tinig Mo''y dinggin,<br/>Galak na tumatalima,<br/>Bawa''t salita''y sundin.<br/>Ako ay nakikinig<br/>Magsalita sa akin.<br/>',NULL,42080,4);
INSERT INTO stanza VALUES('T808','5','Poon, sa akin magwika,<br/>Ngalan ko''y Iyong banggitin;<br/>Mas matatag at malaya,<br/>Sundin Kang mas matulin;<br/>Kawan ay pastulan Mo<br/>Sa anino ng Bato!<br/>',NULL,42081,5);
INSERT INTO stanza VALUES('T809','1','Poon, magsalita,<br/>Hinihintay Ka;<br/>Puso ko''y tahimik<br/>Na umaasa.<br/>',NULL,42082,1);
INSERT INTO stanza VALUES('T809','2','Magwika Ka, Poon,<br/>Ako''y taimtim;<br/>Mukha Mo''y mamasdan,<br/>Lakas Mo''y damhin.<br/>',NULL,42083,2);
INSERT INTO stanza VALUES('T809','3','Salitang sinabi<br/>Totoong buhay;<br/>Tinapay ng langit,<br/>Pagkaing tunay.<br/>',NULL,42084,3);
INSERT INTO stanza VALUES('T809','4','Sarili''y di akin,<br/>Lahat ay sa Iyo;<br/>Masayang pagsuko,<br/>Sa Iyo lang ako.<br/>',NULL,42085,4);
INSERT INTO stanza VALUES('T809','5','Magwika sa akin,<br/>Huwag Kang magtimpi;<br/>Buhay Mong salita,<br/>Ang aking mithi.<br/>',NULL,42086,5);
INSERT INTO stanza VALUES('T809','6','Bigyang kaalaman<br/>Ng Iyong naisin;<br/>Tanang kaluguran,<br/>Sa anak tupdin.<br/>',NULL,42087,6);
INSERT INTO stanza VALUES('T809','7','Katulad ay hardin,<br/>Puspos ng samyo;<br/>Buhay ko''y makita,<br/>Sa presensya Mo.<br/>',NULL,42088,7);
INSERT INTO stanza VALUES('T810','1','May wika ba para sa ''kin,<br/>Nang mabigkis ako sa Iyo,<br/>Upang masama''y mawaksi;<br/>Isang wika mula sa Iyo?<br/>',NULL,42089,1);
INSERT INTO stanza VALUES('T810','2','Isang wikang maglalantad,<br/>Gaano kahina ako,<br/>Hikbi''t pagal, walang saysay;<br/>Isang wika mula sa Iyo.<br/>',NULL,42090,2);
INSERT INTO stanza VALUES('T810','3','Isang wikang maglalahad,<br/>Sa akin ay kay talik Mo;<br/>Bumahagi sa Iyong buhay;<br/>Isang wika mula sa Iyo.<br/>',NULL,42091,3);
INSERT INTO stanza VALUES('T810','4','Isang wikang kalakasan,<br/>Sa pusong may panlulumo,<br/>Munting tinig na kay linaw;<br/>Isang wika mula sa Iyo.<br/>',NULL,42092,4);
INSERT INTO stanza VALUES('T810','5','Isang wikang matagumpay;<br/>Pag-asa sa Iyong pangako,<br/>Na manahan Kang kaisa;<br/>Isang wika mula sa Iyo.<br/>',NULL,42093,5);
INSERT INTO stanza VALUES('T811','1','Puso''y gutom, espiritu''y uhaw,<br/>Panginoon, Ikaw ang pangtighaw;<br/>Tanging Ikaw ang aking kailangan,<br/>Kasagutan Ka at kasiyahan.<br/>',NULL,42094,1);
INSERT INTO stanza VALUES('T811','chorus','O Panginoon, samo''y dinggin,<br/>Gutom at uhaw, Iyong pawiin;<br/>Tuwa''t kalakasan, Iyong lubusin,<br/>Pagtatamasa''y mapasa ''kin.<br/>',NULL,42095,2);
INSERT INTO stanza VALUES('T811','2','Pagkain Ka at tubig ng buhay,<br/>Dulot sa ''kin ay lakas na tunay;<br/>Nais Kitang inumin at kanin,<br/>Sa pagbabasa''t pananalangin.<br/>',NULL,42096,3);
INSERT INTO stanza VALUES('T811','3','Salita Ka''t kapuspusan ng Diyos,<br/>Diyos sa Espiritu''y aking tustos;<br/>Sa Salita''y pagkaing kay yaman,<br/>Espiritu''y tubig na nakamtan.<br/>',NULL,42097,5);
INSERT INTO stanza VALUES('T811','4','Pagkain Kang bumaba sa langit,<br/>Naging inumin sa dusa''t sakit;<br/>Bilang pagkain, yaman Kang tustos,<br/>Bilang inumin, batis Kang lubos.<br/>',NULL,42098,7);
INSERT INTO stanza VALUES('T811','5','Sa Salita''y Espiritu''t buhay,<br/>Aking pagkain upang mabuhay;<br/>Espiritu''y sa ''kin nananahan,<br/>Sa espiritu Siya''y nakakamtan.<br/>',NULL,42099,9);
INSERT INTO stanza VALUES('T811','6','Nang matamasa''y lalapit sa Iyo,<br/>Sa Salita Mo''y kakain ako;<br/>Sa espiritu''y babaling sa Iyo,<br/>Upang uhaw ko''y matugunan Mo.<br/>',NULL,42100,11);
INSERT INTO stanza VALUES('T811','7','Hesus, sa pag-inom ko''t pagkain,<br/>Sa pagbabasa''t pananalangin;<br/>Basa''t dalangin, inom at kain,<br/>O, Panginoon Ikaw ay akin.<br/>',NULL,42101,13);
INSERT INTO stanza VALUES('T811','8','Ngayon Ika''y aking kagalakan,<br/>Espiritu''t Salita''y makamtan;<br/>Nawa''y Ikaw palagi ang pista,<br/>Kapuspusang aking matamasa.<br/>',NULL,42102,15);
INSERT INTO stanza VALUES('T812','1','Panginoong mahal,<br/>Sa Iyo ako''y uhaw;<br/>Kainin Ka at inumin,<br/>Lubos Kang tamasahin.<br/>',NULL,42103,1);
INSERT INTO stanza VALUES('T812','2','Ang Kita''y pagmasdan,<br/>Nasang walang hanggan;<br/>Inaasam Kang inumin,<br/>Uhaw ko ay pawiin.<br/>',NULL,42104,2);
INSERT INTO stanza VALUES('T812','3','Ningning ng Iyong mukha,<br/>Pangarap ko''t tuwa;<br/>Dito ay ''di na lilisan,<br/>Pagmasdan Kang lubusan.<br/>',NULL,42105,3);
INSERT INTO stanza VALUES('T812','4','Sa pagsalamuha,<br/>Sa ''kin, biyaya Ka;<br/>Puso''t espiritu''y lipos,<br/>Kapahingaha''y lubos.<br/>',NULL,42106,4);
INSERT INTO stanza VALUES('T812','5','Mamalagi rito,<br/>Naghahanap sa Iyo;<br/>Sa Salita''t panalangin,<br/>Mag-umapaw Ka sa ''kin.<br/>',NULL,42107,5);
INSERT INTO stanza VALUES('T813','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42108,1);
INSERT INTO stanza VALUES('T813','1','Sa trono ng biyaya Mo<br/>Awa''t tulong nakamit ko,<br/>Kagyat kong kailangan ito<br/>Sa puso at espiritu.<br/>',NULL,42109,2);
INSERT INTO stanza VALUES('T813','2','Iyong mukha rito''y namasdan<br/>Puso ko ay inilawan,<br/>Sa sinag ng kagalingan,<br/>Puksa aking kapintasan.<br/>',NULL,42110,3);
INSERT INTO stanza VALUES('T813','3','Dahil sa Iyong pagliwanag<br/>Nilantad ''king kalagayan;<br/>Bisa ng dugo''y nahayag,<br/>Sala ko ay nahugasan.<br/>',NULL,42111,4);
INSERT INTO stanza VALUES('T813','4','Ang nagpahid ungguwento Mo<br/>Elemento Mo''y natamo;<br/>Ikaw ang natamasa ko,<br/>Iyong mithi''y aking nahipo.<br/>',NULL,42112,5);
INSERT INTO stanza VALUES('T813','5','Pagbasa ko ng Biblia<br/>At pagsindi ng ilawan;<br/>Espiritu langis tila,<br/>Salita Mo''y tinanglawan.<br/>',NULL,42113,6);
INSERT INTO stanza VALUES('T813','6','Panalangin ko''y tulad ng<br/>Saserdoteng nag-insenso,<br/>May halong Kristong kamanyang,<br/>Ihandog sa Diyos ang samyo.<br/>',NULL,42114,7);
INSERT INTO stanza VALUES('T813','7','Salita Mo ay pagkain<br/>At ilawan, aking lubos,<br/>Lalo kong basahin, kanin,<br/>Mas may pahayag at tustos.<br/>',NULL,42115,8);
INSERT INTO stanza VALUES('T813','8','Kristo ang tubig na buháy<br/>Nagpaangkop, nagpasigla,<br/>Dalangin, inom na panay,<br/>Samyo''t agos naging bunga.<br/>',NULL,42116,9);
INSERT INTO stanza VALUES('T813','9','Ako''y busog sa pagbasa,<br/>Uhaw pawi sa dalangin;<br/>Sa loob tinamasa Ka,<br/>Palabas Kang paagusin.<br/>',NULL,42117,10);
INSERT INTO stanza VALUES('T813','10','Sa panalangin, pagbasa,<br/>Nakasalamuha Kita;<br/>Ako''y ibabad Mo nawa,<br/>Mula sa ''kin umagos Ka.<br/>',NULL,42118,11);
INSERT INTO stanza VALUES('T814','1','Tao''y di lang nabubuhay<br/>Sa pagkain ng tinapay,<br/>Kundi sa Salita ng Diyos,<br/>Na siyang tunay nating buhay.<br/>',NULL,42119,1);
INSERT INTO stanza VALUES('T814','2','Tayo ay mayr''ong katawan,<br/>Kaluluwa''t espiritu;<br/>''Spiritu''y pinakaloob,<br/>Upang ang Diyos ay mahipo.<br/>',NULL,42120,2);
INSERT INTO stanza VALUES('T814','3','Kailangan nga ng katawan,<br/>Ay pagkain na panlupa,<br/>Kailangan din ng ''spiritu—<br/>Iyong Sarili, Iyong Salita.<br/>',NULL,42121,3);
INSERT INTO stanza VALUES('T814','4','''Spiritu Ka''t Salita Mo,<br/>Naghayag sa Sarili Mo,<br/>Sarili Mo''y Espiritu,<br/>Sa ''spiritu ko''y matamo.<br/>',NULL,42122,4);
INSERT INTO stanza VALUES('T814','5','Nang matanggap Iyong Salita,<br/>''Di lang basahin ng mata<br/>Ni sa isip maunawa,<br/>Bagkus ''spiritu''y gumana.<br/>',NULL,42123,5);
INSERT INTO stanza VALUES('T814','6','Ang Salita ay kainin,<br/>At tanggapin sa ''spiritu;<br/>Natanto ay idalangin<br/>Ensayuhin espiritu.<br/>',NULL,42124,6);
INSERT INTO stanza VALUES('T814','7','Ang Salitang nasa isip<br/>Ay kaalamang pabigat,<br/>Nguni''t buhay at ''spiritu<br/>Kung sa ''spiritu nalapat.<br/>',NULL,42125,7);
INSERT INTO stanza VALUES('T814','8','Tangi kung ang espiritu<br/>Ay tatanggap ng Salita,<br/>Salita Mo ay kakanin,<br/>Sa panloob mahipo Ka.<br/>',NULL,42126,8);
INSERT INTO stanza VALUES('T814','9','Sa pagbasa ng Salita,<br/>Turuan Mong sanayin ko<br/>Aking ''spiritu, Pangino''n,<br/>Nang ako''y matustusan Mo.<br/>',NULL,42127,9);
INSERT INTO stanza VALUES('T815','1','Espiritu at Salita<br/>Ay kapwa si Kristo Mismo;<br/>Ang salitang sinabi Niya<br/>Ay buhay at espiritu.<br/>',NULL,42128,1);
INSERT INTO stanza VALUES('T815','2','Sa panlabas taglay Biblia,<br/>Sa loob Espiritu nga;<br/>Mga kaloob dakila,<br/>Ng Diyos ating matamasa.<br/>',NULL,42129,2);
INSERT INTO stanza VALUES('T815','3','Salita hayag ''Spiritu,<br/>Espiritu''ng realidad;<br/>Dal''wang aspekto ng isa<br/>At di dapat hiwalay nga.<br/>',NULL,42130,3);
INSERT INTO stanza VALUES('T815','4','Biblia''y naging buhay sa iyo,<br/>Sa tanglaw ng Espiritu;<br/>Kung dalawa''y magkalayo,<br/>Sa isip lang pagkatanto.<br/>',NULL,42131,4);
INSERT INTO stanza VALUES('T815','5','Salita''y naging ''Spiritu,<br/>Pag sa ''spiritu hinipo;<br/>Hayag sa ''tin Espiritu<br/>Buhay sa iba''y magtungo.<br/>',NULL,42132,5);
INSERT INTO stanza VALUES('T815','6','Sanayin ang espiritu,<br/>Salita ng Diyos tanggapin,<br/>At palayain ''Spiritu;<br/>Ang dalawa''y ka-isa natin.<br/>',NULL,42133,6);
INSERT INTO stanza VALUES('T815','7','Nawa sa ''kin Iyong Salita,<br/>Maging ''Spiritu''t buhay nga;<br/>''Spiritu Mo sa Salita,<br/>Kahayagan kong tunay nga.<br/>',NULL,42134,7);
INSERT INTO stanza VALUES('T817','1','Hindi dapat limitahan<br/>Ang katotohanan,<br/>Ng may pagkiling na sekta<br/>Isipang may hangga.<br/>Bago, mabuting pag-asa,<br/>Puso''y mapasigla:<br/>Liwanag, katotohanan<br/>Higit pang bubuksan.<br/>',NULL,42135,1);
INSERT INTO stanza VALUES('T817','2','Ang orakulo ng langit,<br/>Tinalian pilit,<br/>Ng ''purol ng pang-unawa<br/>Pangahas na aba!<br/>Sansinukob at dagat man,<br/>Hindi mapalugod!<br/>Liwanag, katotohanan<br/>Higit pang bubuksan.<br/>',NULL,42136,2);
INSERT INTO stanza VALUES('T817','3','Ninuno''y tinahak dilim<br/>Sa unang hakbangin;<br/>Hanggang liwayway tumanghal,<br/>Sa araw na sakdal;<br/>O araw na mal''walhati<br/>Silay Mo titindi:<br/>Liwanag, katotohanan<br/>Higit pang bubuksan.<br/>',NULL,42137,3);
INSERT INTO stanza VALUES('T817','4','Dinaanan ang libis at,<br/>Tayo ay paakyat,<br/>Ating tingnan sa mataas,<br/>Panahong lumipas;<br/>Paakyat, hangin ay klaro,<br/>Humihimig ugong!<br/>Liwanag, katotohanan<br/>Higit pang bubuksan.<br/>',NULL,42138,4);
INSERT INTO stanza VALUES('T817','5','O Ama, Anak, ''Spiritu,<br/>Palawakin puso—<br/>Maunawa pag-ibig Mo<br/>Ng bawa''t Kristiyano;<br/>Dakilang lakas igawad<br/>Patuloy malaman,<br/>Liwanag, katotohanan<br/>Higit pang bubuksan.<br/>',NULL,42139,5);
INSERT INTO stanza VALUES('T818','1','Si Kristo''y hiwaga ng Diyos;<br/>Diyos, di-makita, di-hayag,<br/>Wangis Niya''y di pa nakita,<br/>Kristong Anak ang nagbunyag.<br/>',NULL,42140,1);
INSERT INTO stanza VALUES('T818','2','Siya''y Salita mismo ng Diyos,<br/>Paliwanag ng Diyos tunay;<br/>Pagsasakatawan ng Diyos,<br/>At wangis ng Diyos nasilay.<br/>',NULL,42141,2);
INSERT INTO stanza VALUES('T818','3','Wangis ng Diyos di-makita,<br/>Sinag kay inam ng gloria;<br/>Kapuspusan nasa Kanya,<br/>Patotoo ng Diyos dala.<br/>',NULL,42142,3);
INSERT INTO stanza VALUES('T818','4','Ang Ekklesia ay hiwaga,<br/>Ni Kristo sa mga tao;<br/>Di Siya makita ninuman,<br/>Sa Ekklesia Siya''y natanto.<br/>',NULL,42143,4);
INSERT INTO stanza VALUES('T818','5','Ekklesia''y kahayagan Niya,<br/>Kristo sa kanya''y nanahan;<br/>Siya''y kopyang tunay ni Kristo,<br/>Kristo sa kanya''y namasdan.<br/>',NULL,42144,5);
INSERT INTO stanza VALUES('T818','6','Wangis ni Kristo''y taglay niya,<br/>Pagdami''t paglawak din siya;<br/>Kristo nakita sa kanya,<br/>Kristo''y Ulo, Katawan siya.<br/>',NULL,42145,6);
INSERT INTO stanza VALUES('T818','7','Ang Ama ay nasa Anak,<br/>Ang Anak ay Espiritu;<br/>''Spiritu ng Tres-unong Diyos<br/>Sa Ekklesia naihalo.<br/>',NULL,42146,7);
INSERT INTO stanza VALUES('T819','1','Ang kapuspusan ng buhay<br/>Ay ang katawan,<br/>Kay Kristo nama''y Ekklesia,<br/>Kahayagan Niya.<br/>',NULL,42147,1);
INSERT INTO stanza VALUES('T819','2','Eva kay Adam nagmula,<br/>Siya''y bahagi niya,<br/>Pagparami ni Kristo nga,<br/>Kanyang Ekklesia.<br/>',NULL,42148,2);
INSERT INTO stanza VALUES('T819','3','Binungang trigo''y marami<br/>Ng isang binhi,<br/>At nabuong tinapay nga,<br/>Nang pinagsama.<br/>',NULL,42149,3);
INSERT INTO stanza VALUES('T819','4','Kaya''t si Kristo''y lumaki<br/>Diyos nal''walhati,<br/>Bilang Ekklesiang Katawan,<br/>Siyang kahayagan.<br/>',NULL,42150,4);
INSERT INTO stanza VALUES('T819','5','Paglaganap ng puno nga<br/>Ay mga sanga,<br/>Sa puno ay manatili,<br/>Bunga''y darami.<br/>',NULL,42151,5);
INSERT INTO stanza VALUES('T819','6','Ang mga sangkap ni Kristo,<br/>Kanyang paglago,<br/>Makipag-isa sa Kanya,<br/>Palawakin Siya.<br/>',NULL,42152,6);
INSERT INTO stanza VALUES('T819','7','Kapuspusan at pagdami,<br/>Kanyang paglaki;<br/>Pagpapatuloy, tularan,<br/>Siyang kahayagan!<br/>',NULL,42153,7);
INSERT INTO stanza VALUES('T819','8','Kay Kristo''y Ekklesia''y tangi,<br/>Diyos mal''walhati;<br/>Sa Kanyang mga tinubos,<br/>''Hayag Siyang lubos.<br/>',NULL,42154,8);
INSERT INTO stanza VALUES('T819','9','Kaya dakilang hiwaga,<br/>Kristo''t Ekklesia,<br/>Diyos at tao pinaghalo,<br/>Nagkai-sang lalo.<br/>',NULL,42155,9);
INSERT INTO stanza VALUES('T820','1','Yaman ni Kristo''y tamasa,<br/>At maging kapuspusan Niya;<br/>Makakain mo Siya Mismo,<br/>Mahayag ang patotoo.<br/>',NULL,42156,1);
INSERT INTO stanza VALUES('T820','2','Yaman ni Kristo — Siya Mismo<br/>Pagtatamasa natin Siya;<br/>Gayon makamit ni Kristo<br/>Kapuspusan Niyang ekklesia.<br/>',NULL,42157,2);
INSERT INTO stanza VALUES('T820','3','Sa Canaan, bunga''t tubo,<br/>Larawan ng yaman-Kristo,<br/>Banal na templong ''tinayo,<br/>Ekklesiang lago ni Kristo.<br/>',NULL,42158,3);
INSERT INTO stanza VALUES('T820','4','Adam, kapuspusa''y Eva,<br/>Gayon Ekklesia kay Kristo;<br/>Kay Adam buhat si Eva,<br/>Ekklesia''y mula kay Kristo.<br/>',NULL,42159,4);
INSERT INTO stanza VALUES('T820','5','Kristo sa loob ko''y yaman,<br/>Ekklesia ay kapuspusan,<br/>Puspos Niya — siyang kahayagan;<br/>Kristo, ekklesia''y buuan.<br/>',NULL,42160,5);
INSERT INTO stanza VALUES('T821','1','Ekklesia''y Kanyang sisidlan,<br/>Maging Kanyang kahayagan,<br/>Gaya''y katawan sa tao,<br/>Tao''y hinahayag nito.<br/>',NULL,42161,1);
INSERT INTO stanza VALUES('T821','2','Gaya ng templo sa kaban,<br/>Lunan ng kapahingahan;<br/>Ekklesia''y Kanyang tirahan,<br/>Si Kristo ang nilalaman.<br/>',NULL,42162,2);
INSERT INTO stanza VALUES('T821','3','Hiwaga ng Diyos si Kristo,<br/>Paliwanag ng Diyos Mismo;<br/>Ekklesia ay hiwaga Niya,<br/>Hinayag, ''sinalita Siya.<br/>',NULL,42163,3);
INSERT INTO stanza VALUES('T821','4','Mga sangkap ng Katawan,<br/>Dati-rati''y lupa lamang;<br/>Sila''y dapat matransporma,<br/>Maging batong mahalaga.<br/>',NULL,42164,4);
INSERT INTO stanza VALUES('T821','5','Sa transpormasyon na''tayo,<br/>Sisidlan para kay Kristo;<br/>Nilagyan yaman ni Kristo;<br/>Lahat Niya''y hayag sa tao.<br/>',NULL,42165,5);
INSERT INTO stanza VALUES('T821','6','Tres-unong Diyos nagtulungan<br/>Transpormasyon magampanan,<br/>Ekklesia''y naging sisidlan<br/>Herusalem ang tularan.<br/>',NULL,42166,6);
INSERT INTO stanza VALUES('T821','7','Kay halaga ng ekklesia,<br/>Bawa''t panig niya''y aninag;<br/>Kristong puspos ng Diyos taglay,<br/>Kristong nal''walhati''y hayag.<br/>',NULL,42167,7);
INSERT INTO stanza VALUES('T821','8','Diyos ang ilaw, Kristo''y buhay,<br/>Espiritu''y daloy buhay,<br/>Tres-unong Diyos hinayag niya,<br/>Buong mundo''y mabatid nga.<br/>',NULL,42168,8);
INSERT INTO stanza VALUES('T822','1','Kay Kristo ang Ekklesia,<br/>Patungan-ng-ilawan nga;<br/>Kristo''y ilawan, Diyos ilaw,<br/>Ekklesia''y hawak ang tanglaw.<br/>',NULL,42169,1);
INSERT INTO stanza VALUES('T822','2','Ilaw sa ilawan silay<br/>Ang Diyos na dibinong buhay;<br/>Patungan dapat na ginto<br/>Tugma sa l''walhati nito.<br/>',NULL,42170,2);
INSERT INTO stanza VALUES('T822','3','Sa panahon ng dilim nga''y<br/>Ilaw ng buhay sisilay<br/>Sa mga sentro ng tao<br/>Itanghal ang patotoo.<br/>',NULL,42171,3);
INSERT INTO stanza VALUES('T822','4','Bilang dalisay na saksi<br/>Palagi "unang pag-ibig";<br/>Sa "puno ng buhay" ani<br/>Bahagi ng mandaraig.<br/>',NULL,42172,4);
INSERT INTO stanza VALUES('T822','5','Pag-usig dapat batahin<br/>"Putong ng buhay" maangkin;<br/>Ang Babilonia''y talunin,<br/>Ang "tagong manna" tamuhin.<br/>',NULL,42173,5);
INSERT INTO stanza VALUES('T822','6','Gawa ni "Jezebel" takwil,<br/>Nang lupa''y mapagharian;<br/>Sitwasyong patay daigin<br/>"Kasuotang puti" damtin.<br/>',NULL,42174,6);
INSERT INTO stanza VALUES('T822','7','Gayang "Filadelfia" siya<br/>Hawakan Kanyang salita;<br/>Ihayag Kanyang Pangalan<br/>Kasama Niyang magpistahan.<br/>',NULL,42175,7);
INSERT INTO stanza VALUES('T822','8','Gayong mapadalisay siya,<br/>Patungan-ng-ilawan nga,<br/>Yaring dalisay na ginto,<br/>Bilang patotoong puro.<br/>',NULL,42176,8);
INSERT INTO stanza VALUES('T822','9','Ekklesia lokal sa lupa<br/>Patungan-ng-ilawan nga;<br/>Bagong Herusalem naman,<br/>Para sa kawalang-hanggan.<br/>',NULL,42177,9);
INSERT INTO stanza VALUES('T822','10','Ang lunsod na purong ginto,<br/>Kahuliha''t napasukdol;<br/>Patungan-ng-ilawan din<br/>Diyos at Kristo ay taglayin.<br/>',NULL,42178,10);
INSERT INTO stanza VALUES('T824','1','Ang Ekklesia''y Katawan,<br/>Sarili ni Kristo;<br/>Sa Diyos Ama''y tahanan,<br/>Samahan ng banal,<br/>Hinalong Diyos at tao,<br/>Hinirang pa ng Diyos;<br/>Tinubos sa Kalbaryo<br/>Makalangit lubos.<br/>',NULL,42179,1);
INSERT INTO stanza VALUES('T824','2a','Ang muling-pagkabuhay<br/>Ni Kristo''y nagsilang,<br/>Ng isang bagong tao,<br/>At bagong nilalang;<br/>Sa kanya''y nagbautismo<br/>Ang Diyos Espiritu;<br/>Si Kristo''y kanyang buhay<br/>Mal''walhating Ulo.<br/>',NULL,42180,2);
INSERT INTO stanza VALUES('T824','2b','Siya rin ay pinabanal,<br/>Ng Salita ng Diyos;<br/>Ang kanyang nilalaman<br/>Ay si Kristong lubos;<br/>Pati kanyang ugali<br/>Katulad ni Kristo;<br/>Lahat ng katunggali<br/>Kanyang napasuko.<br/>',NULL,42181,3);
INSERT INTO stanza VALUES('T824','3','Ang kanyang sinaligan<br/>Ay si Hesu-Kristo,<br/>Lahat ng kanyang sangkap,<br/>Walang makamundo,<br/>Bawa''t sa kanyang sangkap,<br/>Bahagi''y Kalbaryo;<br/>Upang sa pagkabuhay<br/>Sila''y maitayo.<br/>',NULL,42182,4);
INSERT INTO stanza VALUES('T824','4a','Isang Diyos, isang Poon,<br/>Espiritu Isa,<br/>At iisang Katawan,<br/>Pananalig isa,<br/>Saka isang bautismo<br/>At isang pag-asa,<br/>Ang kanyang diwa''t buod,<br/>Walang hindi isa.<br/>',NULL,42183,5);
INSERT INTO stanza VALUES('T824','4b','Ang Diyos na tatlo-isa<br/>Nasa loob nila,<br/>Upang lahat ay maging<br/>Katawang iisa,<br/>Dahil sa pananalig<br/>Nagkabuklod sila,<br/>Sa pagbalik ni Hesus,<br/>Sila''y umaasa.<br/>',NULL,42184,6);
INSERT INTO stanza VALUES('T824','5','Ang kanyang mga sangkap<br/>Sa tanan nagmula,<br/>Walang lipi at bansa,<br/>Mataas at aba,<br/>Ni malaya''t alipin,<br/>Ni Hentil at Hudyo<br/>Tangi lamang si Kristo,<br/>Ang Siyang "bagong tao."<br/>',NULL,42185,7);
INSERT INTO stanza VALUES('T824','6','Isa sa sansinukob,<br/>Tanging iisa siya,<br/>Nguni''t sa pagkahayag<br/>Bawa''t pook isa,<br/>Pamahalaa''y lokal,<br/>Kay Kristo managot,<br/>Ang pagsasalamuha<br/>Ay pansansinukob.<br/>',NULL,42186,8);
INSERT INTO stanza VALUES('T824','7','Si Kristo ang Ilawan,<br/>Ilaw ang Diyos banal,<br/>Patungan-ng-ilawan,<br/>Ang ekklesia lokal.<br/>Lokal niyang pagtitipon,<br/>Tinutulad nito<br/>Ang Bagong Herusalem<br/>Sa bawa''t aspekto.<br/>',NULL,42187,9);
INSERT INTO stanza VALUES('T830','1','Panalig ng mga ama<br/>Buháy sa gitna ng dusa,<br/>Maging apoy man o tabak,<br/>Panampalataya''y tiyak.<br/>Puso umapaw sa galak,<br/>Hanggang mamatay ay tapat!<br/>',NULL,42188,1);
INSERT INTO stanza VALUES('T830','2','Kahit ama''y nabilanggo,<br/>Malaya ang budhi''t puso;<br/>Tadhana ng mga supling,<br/>Magiging pagpapala rin;<br/>Basta sa panalig tapat,<br/>Kamatayan ma''y kaharap.<br/>',NULL,42189,2);
INSERT INTO stanza VALUES('T830','3','Panalig ng mga ama,<br/>Matamo lahat ng bansa;<br/>Mula Diyos katotohanan,<br/>Tao''y ''bigyang kalayaan.<br/>Panampalatayang banal,<br/>Tapat hanggang kamatayan.<br/>',NULL,42190,3);
INSERT INTO stanza VALUES('T830','4','Panalig ng mga ama,<br/>Tanang tao''y aming sinta,<br/>Aming ipahahayag ka,<br/>Sa salita man o gawa.<br/>Hanggang kamatayan kami''y<br/>Sa iyo maging tapat lagi!<br/>',NULL,42191,4);
INSERT INTO stanza VALUES('T831','1','Pagkakai-sa ng Ekklesia''y<br/>Sa isang pamumuhay;<br/>Pagkakai-sa nilagak ng<br/>''Spiritung nananahan.<br/>Kaisahan ng ''Spiritu,<br/>Mga banal, minana,<br/>Batay sa pangkalahatang<br/>Pananampalataya.<br/>',NULL,42192,1);
INSERT INTO stanza VALUES('T831','2','Binuo ni Kristo Hesus<br/>Ang gawang mapanubos;<br/>Mahalagang pananalig,<br/>Banal at bukod-tangi.<br/>Dito banal nagkaisa<br/>Nagsang-ayunan sila,<br/>Gayong panampalataya,<br/>Napairal Ekklesia.<br/>',NULL,42193,2);
INSERT INTO stanza VALUES('T831','3','Sa sansinukob iisa,<br/>Mana Niya''ng Ekklesia;<br/>Dapat lokal na Ekklesia<br/>Sa kahayaga''y isa;<br/>Diyos, Poon, ''Spiritu''y isa—<br/>Elemento''y iisa<br/>Isang panalig, bautismo,<br/>Katawan at pag-asa.<br/>',NULL,42194,3);
INSERT INTO stanza VALUES('T831','4','Isa sa lupang-batayan,<br/>Batayang tinayuan,<br/>Batayan ng kaisahan<br/>Ang hiling ng ''Spiritu.<br/>Sa pagkai-sa makagawa,<br/>Nang tunay ang Ekklesia<br/>Maitayong walang hadlang<br/>Lokal Niyang kahayagan.<br/>',NULL,42195,4);
INSERT INTO stanza VALUES('T831','5','Poon, panatilihin Mo<br/>Pagkai-sa sa ''spiritu;<br/>Lupang-batayan tayuan,<br/>Danasin ang Katawan.<br/>Nang dakila Mong naisin,<br/>Lubusan Mong tamuhin<br/>Nang walang hanggang layon Niya.<br/>Mai-sakatuparan na.<br/>',NULL,42196,5);
INSERT INTO stanza VALUES('T832','1','Kristo''t Kanyang mapanubos na gawa<br/>Nagligtas na pananampalataya,<br/>Ibang doktrina''y wala na sa kredo;<br/>Marapat gawa''t persona ni Kristo.<br/>',NULL,42197,1);
INSERT INTO stanza VALUES('T832','2','Turong ginagamit nang hindi tama<br/>"Doktrinang hangin" pagkai-sa sinira:<br/>Banal hinipang palayo sa Ulo<br/>Katawa''y sinira di itinayo.<br/>',NULL,42198,2);
INSERT INTO stanza VALUES('T832','3','Kaya bitiwan lahat ng doktrina,<br/>Panghawakan kredo nang magkaisa.<br/>Sa Pangino''ng ''Spiritu tayo''y isa;<br/>Pagkai-sa lamang, iba''y bitiwan na.<br/>',NULL,42199,3);
INSERT INTO stanza VALUES('T832','4','Hawakan katotohanan — si Kristo,<br/>Mapalaya sa mga sekta tayo,<br/>Lumago tungo kay Kristo na Ulo,<br/>Kapuspusan ng Katawan matamo.<br/>',NULL,42200,4);
INSERT INTO stanza VALUES('T832','5','"Pagkai-sa sa pananalig" abutin,<br/>"Hangin ng pagtuturo" huwag pansinin;<br/>Realidad nati''y Kristong ''Spiritu<br/>Hawakan nang Katawa''y mapalago.<br/>',NULL,42201,5);
INSERT INTO stanza VALUES('T834','1','Poon, Batong-panulok Ka<br/>Hudyo Ika''y minata;<br/>Nguni''t sa pagkabuhay nga,<br/>Diyos sa Iyo''y nagtalaga.<br/>Sa Iyo, kaligtasa''y amin,<br/>Kami''y naitayo rin<br/>Hudyo''t Hentil bagong tao<br/>Tunay na tahanan Mo.<br/>',NULL,42202,1);
INSERT INTO stanza VALUES('T834','2','Ikaw rin Batong pinalo,<br/>Lutas uhaw ng tao,<br/>Maging pag-asa ng tao<br/>Bahay ng Diyos mai-tayo.<br/>Ang Pundasyong Bato ng Sion,<br/>Subok, matatag Poon,<br/>Batong suhay sa Ekklesia,<br/>Tangi ngang pundasyon niya.<br/>',NULL,42203,2);
INSERT INTO stanza VALUES('T834','3','Ekklesia sa Iyo''y nai-tayo,<br/>Pinto ng Hades talo,<br/>Dumanas ng hangi''t ulan,<br/>Higit ang katatagan.<br/>Awtoridad Mo''y taglay niya,<br/>Magtali''t magpalaya,<br/>Tao''y sumakaharian<br/>Tinamo''y kalayaan.<br/>',NULL,42204,3);
INSERT INTO stanza VALUES('T834','4','Batong-Buháy ng buhay Ka,<br/>Hirang minahalaga;<br/>Nang maging buháy na bato<br/>Kalikasa''y gaya Mo.<br/>Maitayo, bilang templo<br/>Diyos dito''y makatahan,<br/>Pagkasaserdoteng banal,<br/>Siya''y aming mahandugan.<br/>',NULL,42205,4);
INSERT INTO stanza VALUES('T834','5','Anak Ka ni David, Kristo,<br/>Tagatayo ng templo;<br/>Hari at Saserdote Ka,<br/>Pagkatawag matupad.<br/>Bilang Hari, ''Ka''y namuno,<br/>Nang Diyos sundin ng tao;<br/>Saserdote sa harap Niya<br/>Tao''y dalhin sa Kanya.<br/>',NULL,42206,5);
INSERT INTO stanza VALUES('T834','6','Awtoridad sa luklukan,<br/>Hatid kapayapaan;<br/>Salamuha''y may pag-agos<br/>Ng buhay na panustos.<br/>Pagkahari''t Saserdote,<br/>Sa I-yo''y pinagsama;<br/>Layunin ng Diyos natupad,<br/>Tahanan Niya''y nahayag.<br/>',NULL,42207,6);
INSERT INTO stanza VALUES('T834','7','Ika''y Diyos na naging laman,<br/>Diyos sa Iyo nananahan;<br/>Diyos sa tao nanatili,<br/>Templo Kang mal''walhati.<br/>Ekklesia rin paghahalo<br/>Ng Mismong Diyos at tao;<br/>Gayundin sa bawa''t sangkap,<br/>Balak ng Diyos matupad.<br/>',NULL,42208,7);
INSERT INTO stanza VALUES('T834','8','O, walang hanggang Tahanan,<br/>Lagi naming tirahan;<br/>Sa loob Mo''y namumuhay,<br/>Tamasa Iyong pagbantay.<br/>Kami''t Diyos nanahan sa Iyo,<br/>Tunay naming Santuaryo;<br/>Ikaw ang presensya ng Diyos,<br/>Pagsamba nami''y lubos.<br/>',NULL,42209,8);
INSERT INTO stanza VALUES('T834','9','Panulukang-bato Ka nga,<br/>Pundasyon, Ekklesia,<br/>Ikaw rin Tagapagtayo,<br/>Tahanan at Santuaryo.<br/>Pinupuri''t hinangaan,<br/>Poon, sa kung ano Ka!<br/>Nawa kaming batong-buháy,<br/>Sa Iyo mai-tayong tunay.<br/>',NULL,42210,9);
INSERT INTO stanza VALUES('T837','1','Purihin Ka sa Iyong plano<br/>Kami''y maging tahanan Mo;<br/>Sa amin Ika''y manahan,<br/>Nang kami''y Iyong mapunuan.<br/>',NULL,42211,1);
INSERT INTO stanza VALUES('T837','2','Nilikhang may larawan Mo<br/>Taglay pa awtoridad Mo;<br/>Nguni''t kami''y yaring luad,<br/>Di-taglay ang dibinidad.<br/>',NULL,42212,2);
INSERT INTO stanza VALUES('T837','3','Tinanggap Ka bilang buhay,<br/>Likas Mo''t biyaya''y taglay;<br/>Sa Iyo''y naihalo kami,<br/>Hayag Katawang l''walhati.<br/>',NULL,42213,3);
INSERT INTO stanza VALUES('T837','4','Buhay Mo sa ''min lumagos,<br/>Sa bawa''t bahagi''y tapos,<br/>Kami ang magiging perlas,<br/>Kawangis Mo kami''y hiyas.<br/>',NULL,42214,4);
INSERT INTO stanza VALUES('T837','5','Subali''t aming natanto<br/>''Di ito gawa ng tao,<br/>Materyales pagtatayo<br/>Ng mal''walhating bahay Mo.<br/>',NULL,42215,5);
INSERT INTO stanza VALUES('T837','6','Poon, kami''y tanggapin Mo<br/>Sa marunong na kamay Mo;<br/>Baliin, sa Iyo''y itayo,<br/>Mapaayon sa buhay Mo.<br/>',NULL,42216,6);
INSERT INTO stanza VALUES('T837','7','Tanang natural baliin,<br/>Kataka-taka''y tuusin,<br/>Nang ''di kami magsarili,<br/>Mga banal kai-sang lagi.<br/>',NULL,42217,7);
INSERT INTO stanza VALUES('T837','8','Maging I-yong Kasintahan,<br/>Kasama Mo sa tahanan,<br/>Iyong pag-ibig tinamasa,<br/>Ikaw bigyang-kasiyahan.<br/>',NULL,42218,8);
INSERT INTO stanza VALUES('T838','1','Poon, ginuhit Mong plano,<br/>Hayag ang tabernakulo,<br/>Kami''y nais Mong itayo,<br/>Mahayag ang l''walhati Mo.<br/>',NULL,42219,1);
INSERT INTO stanza VALUES('T838','2','Sentro ng tolda''y ang kaban,<br/>Tolda''y lugar-pahingahan;<br/>Sampung utos nasa kaban,<br/>At sa tolda''y nakatahan.<br/>',NULL,42220,2);
INSERT INTO stanza VALUES('T838','3','Kaban: sagisag ni Kristo,<br/>Ang ginto''t kahoy, Diyos-tao;<br/>Utos kahayagan ng Diyos,<br/>Kay Kristo''y nanahang lubos.<br/>',NULL,42221,3);
INSERT INTO stanza VALUES('T838','4','Kristo''y sentro ng Ekklesia,<br/>Na siyang pahingahan Ni-ya,<br/>Na kay Kristo nga ang Ama,<br/>Ang Ekklesia''y tahanan Niya.<br/>',NULL,42222,4);
INSERT INTO stanza VALUES('T838','5','Ang tolda''y kabang lumago<br/>Kahoy binalot ng ginto;<br/>Ekklesia''y lumaking Kristo,<br/>Diyos sa tao naihalo.<br/>',NULL,42223,5);
INSERT INTO stanza VALUES('T838','6','Mga pansuportang tabla,<br/>Nakatindig sa pilak nga;<br/>May ginintuang argolya,<br/>At pangkawing barakila.<br/>',NULL,42224,6);
INSERT INTO stanza VALUES('T838','7','Tinipong banal — Ekklesia,<br/>Pagtutubos tuntungan niya;<br/>Gapos ng buhay dibino,<br/>Nagkalapat naitayo.<br/>',NULL,42225,7);
INSERT INTO stanza VALUES('T838','8','Ang apat-na-susong takip,<br/>Kristo''y ipinahiwatig;<br/>Kristo naglahad l''walhati,<br/>Sa tahanan Siyang nagtakip.<br/>',NULL,42226,8);
INSERT INTO stanza VALUES('T838','9','Natakpan ng gayong Kristo,<br/>Banal nai-lapat, nai-tayo;<br/>Tamasa tanang ano Siya,<br/>Maitayo sa loob Niya.<br/>',NULL,42227,9);
INSERT INTO stanza VALUES('T838','10','Kautusa''y nasa kaban,<br/>Kaban nasa tolda naman;<br/>Diyos kay Kristo sa Ekklesia<br/>Tinanghal ang l''walhati Niya.<br/>',NULL,42228,10);
INSERT INTO stanza VALUES('T839','1','Poon, magpapalayok,<br/>At tagapagtayo pa,<br/>Sisidla''y hinuhubog,<br/>Tahana''y ginagawa.<br/>Ako ay isang tao<br/>Kapwa luad at bato,<br/>Nang maging Iyong sisidlan<br/>At sariling templo Mo.<br/>',NULL,42229,1);
INSERT INTO stanza VALUES('T839','2','Kahit kami ay luad,<br/>Nais Mong matransporma,<br/>Tulad sa purong ginto,<br/>Batong mahahalaga;<br/>Kami''y sa pagtatayo<br/>Gagawing Kasintahan,<br/>Kaisang Katawan Mo,<br/>Puso Mo''y masiyahan.<br/>',NULL,42230,2);
INSERT INTO stanza VALUES('T839','3','Ang Iyong nais at hangad,<br/>Di batong nag-iisa,<br/>Kundi ang Iyong tahanan,<br/>''Tinayong sama-sama.<br/>O Kristong tunay saklaw,<br/>Ekklesia ang Iyong hangad,<br/>Nang ang Iyong kayamanan<br/>Lubusang maisinag.<br/>',NULL,42231,3);
INSERT INTO stanza VALUES('T839','4','Di ''spirituwal na tao<br/>Na lubhang mapag-isa,<br/>Buhay-pangmaramihan,<br/>Hangad Mo''y mai-pakita.<br/>Sangkap na nahiwalay,<br/>Di Ka sakdal mahayag,<br/>Katawang pinaglangkap,<br/>Kapuspusa''y nahayag.<br/>',NULL,42232,4);
INSERT INTO stanza VALUES('T839','5','Panginoon, itayo<br/>Kasamang mga banal,<br/>Mag-isa''y huwag tulutan,<br/>Ilangkap Mo nang sakdal.<br/>Sa ''king karanasan at<br/>Kaloob di magyabang,<br/>Lahat ko''y ibibigay,<br/>Iyo ang kal''walhatian.<br/>',NULL,42233,5);
INSERT INTO stanza VALUES('T840','1','Sa sarili palayain,<br/>Sa likas ni Adam din,<br/>Poon itayo Mo ako,<br/>Sa banal na templo Mo.<br/>Iligtas sa kaibhan ko,<br/>Pagkamakaisa ko,<br/>Tanggapin awtoridad Mo,<br/>Tahanan Mo''y itayo.<br/>',NULL,42234,1);
INSERT INTO stanza VALUES('T840','2','Sa pagdaloy ng buhay Mo,<br/>Lalago''t mababago,<br/>Koordinasyong matamis,<br/>Sa Iyo napawawangis;<br/>Tanganan ang kaayusan,<br/>Tungkulin ay gampanan,<br/>Sa Katawa''y naglilingkod,<br/>Ang nais Mo''y masunod.<br/>',NULL,42235,2);
INSERT INTO stanza VALUES('T840','3','Sa pagtalos, pagdanas ko,<br/>Di dapat magpalalo,<br/>Sa Katawan balansehin<br/>At maging masunurin;<br/>Sa Ulo''y lubos tumangan,<br/>Lalago nang tuluyan,<br/>Kasu-kasuan nagtustos,<br/>Mailapat nang lubos.<br/>',NULL,42236,3);
INSERT INTO stanza VALUES('T840','4','Nagpasigla ''Spiritu Mo<br/>Sa taong-panloob ko,<br/>Di-masukat Iyong pag-ibig,<br/>Nais ko ring mabatid;<br/>Tamasahin ko Iyong yaman,<br/>Hanggang sa mapuspusan,<br/>Patuloy na gumugulang,<br/>Matayo Iyong Katawan.<br/>',NULL,42237,4);
INSERT INTO stanza VALUES('T840','5','Sa bahay ng Diyos itayo,<br/>Maging sa Katawan Mo,<br/>Sa sisidlang sama-sama,<br/>L''walhati Mo''y makita;<br/>Nang Iyong Kasi, ang lunsod nga,<br/>Mapakita sa lupa,<br/>Maningning patungang-ginto,<br/>Itanyag halaga Mo.<br/>',NULL,42238,5);
INSERT INTO stanza VALUES('T841','1','Panginoon, lahat Ka sa ''king buhay;<br/>Kapuspusan ng Diyos Iyong ibinigay.<br/>Pinaging-banal ng Iyong kalikasan,<br/>Muling-pagkabuhay Mo''y kalakasan.<br/>',NULL,42239,1);
INSERT INTO stanza VALUES('T841','2','Agos ng buhay Mo ang nagdadala<br/>Ng liwanag at pagsasalamuha;<br/>Tustos sa kailangan, sa Iyo''y nakamtan,<br/>At paglilinis din sa Iyong harapan.<br/>',NULL,42240,2);
INSERT INTO stanza VALUES('T841','3','Ang kaluluwa ko at espiritu<br/>Babarang lubos ng Espiritu Mo;<br/>Iyong baguhin, sa wangis Mo ihubog,<br/>Hanggang sa Iyong buhay ako''y mahinog.<br/>',NULL,42241,3);
INSERT INTO stanza VALUES('T841','4','Masaganang buhay Mo''y umaagos,<br/>Nagpapanariwa at tumutustos,<br/>Nilulon ng buhay ang kamatayan,<br/>Inalis ang gapos at kadiliman.<br/>',NULL,42242,4);
INSERT INTO stanza VALUES('T841','5','Sa Iyo ibibigay ang aking lahat,<br/>Nang layunin Mo''y sa akin matupad,<br/>''Di na magsumikap magpakabuti,<br/>Nang di mahadlangan Iyong minimithi.<br/>',NULL,42243,5);
INSERT INTO stanza VALUES('T841','6','Tigil ang sariling pagsusumikap,<br/>Pagbabago ng buhay Mo''y matanggap,<br/>Nang ako''y kasamang maitatayo<br/>Na Iyong kahayagan, l''walhati sa Iyo.<br/>',NULL,42244,6);
INSERT INTO stanza VALUES('T842','1','Hingahan Mo ako,<br/>Ibangon ''spiritu;<br/>Sa kamatayan iligtas,<br/>Buhay mapalakas.<br/>',NULL,42245,1);
INSERT INTO stanza VALUES('T842','2','Ako''y Iyong hingahan,<br/>Bigyang kalakasan,<br/>Tulad agilang may pakpak<br/>Di pagod, lalakad.<br/>',NULL,42246,2);
INSERT INTO stanza VALUES('T842','3','Ako''y hingahan Mo,<br/>Mapahinga ako;<br/>''Spiritu''t puso sumaya<br/>Pag sa Iyo umasa.<br/>',NULL,42247,3);
INSERT INTO stanza VALUES('T842','4','Hingahan Mo ako,<br/>Nang mapunuan Mo!<br/>Salita''t gawa''y si Kristo<br/>Di na sarili ko.<br/>',NULL,42248,4);
INSERT INTO stanza VALUES('T842','5','Hingahan, wakasan<br/>Aking kasarinlan;<br/>Mga banal kasamahan,<br/>Matayo Katawan.<br/>',NULL,42249,5);
INSERT INTO stanza VALUES('T843','1','Poon, hipan Mo ng Iyong buhay,<br/>Ako ay linsad at tigang;<br/>Buhayin at ipanauli,<br/>Iugpong sa Iyong Katawan.<br/>',NULL,42250,1);
INSERT INTO stanza VALUES('T843','2','Poon, hipan Mo ng Iyong buhay,<br/>''Spiritu ko''y natalian;<br/>Ako''y palayain ihalo<br/>Sa agos ng Iyong Katawan.<br/>',NULL,42251,2);
INSERT INTO stanza VALUES('T843','3','Poon, hipan Mo ng Iyong buhay,<br/>''Spiritu kong nabigatan;<br/>Buhayin nang makabahagi,<br/>Sa tustos ng Iyong Katawan.<br/>',NULL,42252,3);
INSERT INTO stanza VALUES('T843','4','Poon, hipan Mo ng Iyong buhay,<br/>Mapanglaw aking ''spiritu;<br/>Pagpalain, nang matamasa,<br/>Ang yaman ng Katawan Mo.<br/>',NULL,42253,4);
INSERT INTO stanza VALUES('T843','5','Poon, hipan Mo ng Iyong buhay,<br/>Tuusin kamatayan ko,<br/>Gayundin pagsasarili ko,<br/>Mamuhay sa Katawan Mo.<br/>',NULL,42254,5);
INSERT INTO stanza VALUES('T844','1','Poon, Salita''y ihinga;<br/>Butong tuyo nasa lupa<br/>Nakakalat sa libingan,<br/>Magsalita''t hingahan.<br/>',NULL,42255,1);
INSERT INTO stanza VALUES('T844','2','Salita''y ihinga Poon,<br/>Tuyong buto ay ibangon,<br/>Lisanin ang kamatayan<br/>Iyong sabihan, hingahan.<br/>',NULL,42256,2);
INSERT INTO stanza VALUES('T844','3','Poon, Salita''y ihinga,<br/>Bayan buhaying tanan nga,<br/>Maging hukbo, makibaka;<br/>Hipan ng Iyong hininga.<br/>',NULL,42257,3);
INSERT INTO stanza VALUES('T844','4','Poon, Salita''y ihinga,<br/>Nang bayan Mo''y magkaisa,<br/>Awtoridad, pangunguna<br/>Hindi magkakaiba.<br/>',NULL,42258,4);
INSERT INTO stanza VALUES('T844','5','Poon, Salita''y hingahan,<br/>Pagkaisahin Iyong bayan,<br/>Upang maging Iyong tahanan;<br/>Magsalita''t hingahan.<br/>',NULL,42259,5);
INSERT INTO stanza VALUES('T844','6','Magsalita''t ako''y hipan,<br/>Mapabalik sa Katawan,<br/>Hindi na magmatigas pa;<br/>Ngayon ako''y hipan na!<br/>',NULL,42260,6);
INSERT INTO stanza VALUES('T844','7','Magsalita''t ako''y hipan,<br/>Kasamang banal lalaban,<br/>Nang matayo tahanan Mo,<br/>Ngayo''y hipan Mo ako.<br/>',NULL,42261,7);
INSERT INTO stanza VALUES('T845','1','Palayain ang espiritu ko,<br/>Maitugma sa lahat ng banal;<br/>Sa hangarin at pagtatayo Mo,<br/>Sariling paraan ko''y matanggal.<br/>',NULL,42262,1);
INSERT INTO stanza VALUES('T845','2','Espiritu ko, Iyong palayain,<br/>Malaong ako''y nasa sarili;<br/>Maging bukas ang aking hangarin,<br/>Iyong iligtas nang di magsarili.<br/>',NULL,42263,2);
INSERT INTO stanza VALUES('T845','3','Palayain ang espiritu ko,<br/>Sa sarili''y ganap na lumabas;<br/>Sa ''kin dumaloy Iyong Espiritu,<br/>At Iyong presensya ay mapagmalas.<br/>',NULL,42264,3);
INSERT INTO stanza VALUES('T845','4','Palayain ang espiritu ko,<br/>Sa pag-iisa, ako''y iwalay;<br/>Nang di manatiling dukha ako,<br/>Ang yaman Mo''y sa akin ibigay.<br/>',NULL,42265,4);
INSERT INTO stanza VALUES('T845','5','Palayain ang espiritu ko,<br/>Sarili ko''y di na ikukulong;<br/>Kay Satanas di na patatalo,<br/>Sa kawalang-hanggang ''ko''y susulong.<br/>',NULL,42266,5);
INSERT INTO stanza VALUES('T845','6','Palayain ang espiritu ko,<br/>Espiritu ko''y di mahadlangan;<br/>Sa Iyong buhay ako''y makahalo,<br/>Lahat Mo''y maging katamasahan.<br/>',NULL,42267,6);
INSERT INTO stanza VALUES('T846','1','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Iyong dinggin samo ko,<br/>Paagusin!<br/>Lumipas limutin,<br/>Pader ay wasakin,<br/>''Spiritu''y gagawin;<br/>Paagusin!<br/>',NULL,42268,1);
INSERT INTO stanza VALUES('T846','2','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Poon, aking hiling,<br/>Paagusin!<br/>Di sariling si-ya,<br/>Di magpalalo pa,<br/>Di matalian na;<br/>Paagusin!<br/>',NULL,42269,2);
INSERT INTO stanza VALUES('T846','3','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Sinasamo sa Iyo<br/>Paagusin!<br/>Magmataas huwag na,<br/>Ni magpalalo pa,<br/>Agos walang hanggan,<br/>Paagusin!<br/>',NULL,42270,3);
INSERT INTO stanza VALUES('T846','4','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Kita ay hanapin,<br/>Paagusin!<br/>Di na nag-iisa,<br/>Sarili''y di asa,<br/>Pipigilin di na,<br/>Paagusin!<br/>',NULL,42271,4);
INSERT INTO stanza VALUES('T846','5','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Poon, aking hiling,<br/>Paagusin!<br/>Di na magtiwala,<br/>Sa sariling kaya,<br/>Buhay paagusin,<br/>Paagusin!<br/>',NULL,42272,5);
INSERT INTO stanza VALUES('T846','6','Nawa''y paagusin,<br/>''Spiritu ko!<br/>Poon, daing dinggin,<br/>Paagusin!<br/>Salamuha sa Iyo,<br/>Ako''y maitayo,<br/>Sa iba mahalo,<br/>Sa ''spiritu!<br/>',NULL,42273,6);
INSERT INTO stanza VALUES('T847','1','Magsalamuha sa ''spiritu,<br/>Kasamang banal mahalo,<br/>Sa pagsasarili''y ilayo<br/>Sa mga banal mai-tayo.<br/>',NULL,42274,1);
INSERT INTO stanza VALUES('T847','2','Magsalamuha sa ''spiritu,<br/>Nang mabuksan ''spiritu ko;<br/>Maligtas sa pagkakabukod,<br/>Pagsamba banal kabuklod.<br/>',NULL,42275,2);
INSERT INTO stanza VALUES('T847','3','Magsalamuha sa ''spiritu,<br/>Mapalaya ''spiritu ko,<br/>Sa sarili''y di na palinlang,<br/>Daigin ang bawa''t hadlang.<br/>',NULL,42276,3);
INSERT INTO stanza VALUES('T847','4','Magsalamuha sa ''spiritu,<br/>Manalangin sa ''spiritu,<br/>Sa pagkukunwari''y maligtas,<br/>Nasa''y salamuhang tapat.<br/>',NULL,42277,4);
INSERT INTO stanza VALUES('T847','5','Magsalamuha sa ''spiritu,<br/>Awtoridad malaman ko;<br/>Sa paglingkod magsalamuha,<br/>Nakaugnay ngang talaga.<br/>',NULL,42278,5);
INSERT INTO stanza VALUES('T847','6','Panginoon kami''y pukawin,<br/>Bigyang-siya salamuha,<br/>Nang matanto Iyong pagtatayo,<br/>Tupdin nasa ng puso Mo.<br/>',NULL,42279,6);
INSERT INTO stanza VALUES('T848','1','Pagpapala''t pribileh''yo!<br/>Saserdote ng Diyos ''ko,<br/>Pinili''t tinalaga Niya,<br/>Sa gawang maharlika.<br/>',NULL,42280,1);
INSERT INTO stanza VALUES('T848','chorus','Pagtatayo ng Katawan,<br/>Saserdote''ng gagampan;<br/>Sa ''spiritu manalangin,<br/>Ganapin ang tungkulin.<br/>',NULL,42281,2);
INSERT INTO stanza VALUES('T848','2','Katayuang maharlika,<br/>Sa Iyong pamamahala,<br/>Pansaserdoteng gawain<br/>Sa pagtatayo''y tupdin.<br/>',NULL,42282,3);
INSERT INTO stanza VALUES('T848','3','Bumubuo sa ekklesia,<br/>Mga saserdote nga;<br/>Kung nagsama-sama sila,<br/>Natatayo ekklesia.<br/>',NULL,42283,5);
INSERT INTO stanza VALUES('T848','4','Sa pagbaba ng ekklesia,<br/>Banal ay nagpabaya;<br/>Sa paghina ng ''spiritu,<br/>Mensahe lang natanto.<br/>',NULL,42284,7);
INSERT INTO stanza VALUES('T848','5','Pangangaral at mensahe,<br/>Ang gusto ng marami;<br/>Winaglit pananalangin,<br/>''Spiritu''y ''di gamitin.<br/>',NULL,42285,9);
INSERT INTO stanza VALUES('T848','6','Poon, ako''y balansehin,<br/>May mensahe''t dalangin;<br/>Magtuturo ng Salita<br/>Dasal dagdagan pa nga.<br/>',NULL,42286,11);
INSERT INTO stanza VALUES('T848','7','Paglingkod, may panalangin,<br/>Paghahalo''y sanhiin;<br/>Pansinin dasal, salita—<br/>Matatayo ekklesia.<br/>',NULL,42287,13);
INSERT INTO stanza VALUES('T849','1','Mga buháy na bato<br/>Banal na saserdote;<br/>Para sa pagtatayo<br/>Manalangin matuto.<br/>',NULL,42288,1);
INSERT INTO stanza VALUES('T849','chorus','Sa kabanal-banalan,<br/>Hipuin ang luklukan<br/>Sa ''spiritu''y magdasal,<br/>Pagtatayo''y iiral.<br/>',NULL,42289,2);
INSERT INTO stanza VALUES('T849','2','Maglingkod saserdote,<br/>Nang maging batong buháy,<br/>Bawa''t isa''y gumawa,<br/>Gawain makikita.<br/>',NULL,42290,3);
INSERT INTO stanza VALUES('T849','3','Saserdote at tolda<br/>Palaging magkasama;<br/>Saserdoteng naglingkod,<br/>Iisa daloy nila.<br/>',NULL,42291,5);
INSERT INTO stanza VALUES('T849','4','Pagkasaserdote at<br/>Pagtatayo''y iisa;<br/>Pansaserdoteng gawa,<br/>Bahay naitayo nga.<br/>',NULL,42292,7);
INSERT INTO stanza VALUES('T849','5','Gawaing pagtatayo,<br/>Saserdote''y sagana;<br/>Gawaing natapos na<br/>Bahay ng Diyos ganap na.<br/>',NULL,42293,9);
INSERT INTO stanza VALUES('T849','6','Pinagkai-sa tao''t Diyos,<br/>Kanilang gawang lubos;<br/>Sa salamuha sa Diyos,<br/>Banal natayong lubos.<br/>',NULL,42294,11);
INSERT INTO stanza VALUES('T849','7','Sa dalangi''y mahalo,<br/>Magkasamang natayo;<br/>Pagkasaserdote ngang<br/>Naghahain sa Kanya.<br/>',NULL,42295,13);
INSERT INTO stanza VALUES('T849','8','Ang pagtawag sa amin,<br/>Sa biyaya''y mahalin;<br/>Maglingkod, manalangin,<br/>Ekklesia''y matayo rin.<br/>',NULL,42296,15);
INSERT INTO stanza VALUES('T851','1','Anong ganda, tahanan Mo!<br/>Mapasa looban nito;<br/>Makapiling Ka nang husto,<br/>Daing ng puso ko sa Iyo.<br/>',NULL,42297,1);
INSERT INTO stanza VALUES('T851','2','Sa Iyong dambana, Pangino''n,<br/>Ang maya may kanyang bahay,<br/>Pati langaylangayan do''n,<br/>Nagpugad din ang inakay.<br/>',NULL,42298,2);
INSERT INTO stanza VALUES('T851','3','Tao''y singhina ng maya,<br/>Sa Iyong bahay napahinga,<br/>Asa''y dugo sa dambana,<br/>Insenso doon tamasa.<br/>',NULL,42299,3);
INSERT INTO stanza VALUES('T851','4','Mapalad ang tao na ang<br/>Kalakasan ay nasa Iyo;<br/>Sa puso may mga daan,<br/>Sa Sion siya nga''y patutungo.<br/>',NULL,42300,4);
INSERT INTO stanza VALUES('T851','5','Daan sa libis ng iyak,<br/>Ginawang dako ng bukal;<br/>Takpan ng maagang ulan<br/>Pagpapala ay dumatal.<br/>',NULL,42301,5);
INSERT INTO stanza VALUES('T851','6','Nagsisiyaon sila sa<br/>Kalakasa''t kalakasan,<br/>Sa Diyos sa Sion napakita;<br/>Dalangin ko''y Iyong pakinggan.<br/>',NULL,42302,6);
INSERT INTO stanza VALUES('T851','7','''Sang araw sa looban Mo,<br/>Mabuti kaysa ''sang libo;<br/>Sa bahay Mo, tanod-pinto,<br/>Di tir''han ang toldang liko.<br/>',NULL,42303,7);
INSERT INTO stanza VALUES('T851','8','Ika''y araw at kalasag,<br/>Biyaya''t l''walhati''y bigay;<br/>Sa Iyo ako ay nabihag,<br/>Tustos Mo ay walang humpay.<br/>',NULL,42304,8);
INSERT INTO stanza VALUES('T851','9','Sa lumalakad nang tuwid,<br/>Ikaw ay di nagkakait;<br/>Mapalad ang nananalig,<br/>Biyaya''t gloria''y makamit.<br/>',NULL,42305,9);
INSERT INTO stanza VALUES('T852','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,42306,1);
INSERT INTO stanza VALUES('T852','1','Iniibig ko ang Iyong tahanan;<br/>Ekklesiang pinagpala,<br/>Ito''y Iyong nais at kasiyahan,<br/>Dito Ka napahinga.<br/>',NULL,42307,2);
INSERT INTO stanza VALUES('T852','2','Sa kanya Sarili Mo''y ''binigay<br/>Upang siya''y maging ganap;<br/>Sa kanya sarili ko''y ialay,<br/>Naisin Mo''y matupad.<br/>',NULL,42308,3);
INSERT INTO stanza VALUES('T852','3','Ang ekklesia''y aking pamumuhay,<br/>Ikaw ay aking buhay;<br/>Sarili ko''y pinawalang-saysay,<br/>Ikaw lubos mataglay.<br/>',NULL,42309,4);
INSERT INTO stanza VALUES('T852','4','Siya''y Iyong kasintahang sinisinta,<br/>Gayundin Iyong Katawan;<br/>Siya''y aking naisin at ligaya,<br/>Aking sinasandigan.<br/>',NULL,42310,5);
INSERT INTO stanza VALUES('T852','5','Sa kanya Iyong ''binigay sa akin,<br/>Ang panustos Mong buo;<br/>Sa kanya ako ay Iyong inangkin,<br/>Nasiyahan Iyong puso.<br/>',NULL,42311,6);
INSERT INTO stanza VALUES('T852','6','Iniibig ko ang Iyong tahanan,<br/>Ang hirang Mong ekklesia;<br/>Dito ako''y laging mananahan<br/>Hindi muling gagala.<br/>',NULL,42312,7);
INSERT INTO stanza VALUES('T854','1','Sa loob ni Kristo,<br/>Sa kaisahan;<br/>Nagkokoordina<br/>Ang bawa''t sangkap.<br/>',NULL,42313,1);
INSERT INTO stanza VALUES('T854','2','Kaloob, gawain,<br/>Magkakaiba;<br/>Espiritu, Poon<br/>Ay iisa nga.<br/>',NULL,42314,2);
INSERT INTO stanza VALUES('T854','3','Nangangailangan<br/>Sa bawa''t isa;<br/>Pantay, mahalaga<br/>Paglilingkod nga.<br/>',NULL,42315,3);
INSERT INTO stanza VALUES('T854','4','Biyaya''y sukatin<br/>Mga kaloob;<br/>Tungkulin ganapin<br/>Nang mahinahon.<br/>',NULL,42316,4);
INSERT INTO stanza VALUES('T854','5','Sa bawa''t paggawa''y<br/>Kagamit-gamit;<br/>''Spiritu''y magningas,<br/>At maging tapat.<br/>',NULL,42317,5);
INSERT INTO stanza VALUES('T854','6','Nag-ugpong, magtustos,<br/>Magpatawaran;<br/>Wala ng alitan,<br/>Kristo''y pakinggan.<br/>',NULL,42318,6);
INSERT INTO stanza VALUES('T854','7','Ekklesia''y Katawan,<br/>Kristo ang Ulo;<br/>''Spiritu ang agos,<br/>Nagkai-sa tayo.<br/>',NULL,42319,7);
INSERT INTO stanza VALUES('T855','1','Masdan kay inam, kay saya,<br/>Mga banal nagkaisa!<br/>Parang langis sa ulo na<br/>Tumulo sa laylayan;<br/>Gaya ng hamog sa Hermon<br/>Na tumulo sa Sion;<br/>Pinarating pagpapalang<br/>Buhay walang hanggan.<br/>',NULL,42320,1);
INSERT INTO stanza VALUES('T856','1','O kay inam at kay buti<br/>Kung ang kapatiran<br/>May galak sa isa''t isa<br/>At may kaisahan.<br/>',NULL,42321,1);
INSERT INTO stanza VALUES('T856','2','Gaya''y ungguwentong pampahid,<br/>Binuhos sa ulo;<br/>Tulad ng umagang hamog,<br/>Sariwang totoo.<br/>',NULL,42322,2);
INSERT INTO stanza VALUES('T856','3','Pagpapala''y dadalhin Niya<br/>Tungong kapatiran;<br/>Gantimpala Niya ay buhay<br/>Na walang hangganan.<br/>',NULL,42323,3);
INSERT INTO stanza VALUES('T860','1','Ugnayang pag-ibig<br/>Nawa''y pagpalain;<br/>Salamuha sa ''spiritu<br/>Ay tulad sa langit.<br/>',NULL,42324,1);
INSERT INTO stanza VALUES('T860','2','Sa trono ng Ama,<br/>Dalhin ating hiling;<br/>Magsama sa lungkot, asa,<br/>Aliw, at layunin.<br/>',NULL,42325,2);
INSERT INTO stanza VALUES('T860','3','Tayo''y magtulungan,<br/>At magpasensyahan;<br/>Makitangis sa nasaktan,<br/>Puso''y magdamayan.<br/>',NULL,42326,3);
INSERT INTO stanza VALUES('T860','4','Tuwing maghiwalay,<br/>Puso''y nasasaktan;<br/>Nguni''t umaasang muli<br/>Magpapangitaan.<br/>',NULL,42327,4);
INSERT INTO stanza VALUES('T860','5','Maligtas sa hapis,<br/>At sa kasalanan;<br/>Maghain magpakailanman<br/>Pag-ibig, kai-sahan.<br/>',NULL,42328,5);
INSERT INTO stanza VALUES('T861','1','Hanggang sa muling pagkikita<br/>Gabay ng Diyos sumainyo;<br/>Tumibay sa pag-ibig Niya;<br/>Pagkikita''y, Diyos sumainyo.<br/>',NULL,42329,1);
INSERT INTO stanza VALUES('T861','chorus','Muling magpangita,<br/>Sa paanan ni Hesus;<br/>Muling magpangita,<br/>O, sumainyo ang Diyos nawa!<br/>',NULL,42330,2);
INSERT INTO stanza VALUES('T861','2','Hanggang sa muling pagkikita,<br/>Pakpak Ni-ya kublihan n''yo,<br/>Itustos sa inyo''ng manna;<br/>Pagkikita''y, Diyos sumainyo!<br/>',NULL,42331,3);
INSERT INTO stanza VALUES('T861','3','Hanggang sa muling pagkikita<br/>Bisig ng Diyos lumukob nga,<br/>Sa panganib lumilito;<br/>Pagkikita''y, Diyos sumainyo!<br/>',NULL,42332,5);
INSERT INTO stanza VALUES('T861','4','Hanggang sa muling pagkikita,<br/>Manatili pag-ibig Niya,<br/>Kamatayan Siyang tumalo;<br/>Pagkikita''y, Diyos sumainyo!<br/>',NULL,42333,7);
INSERT INTO stanza VALUES('T863','1','Sa araw-araw na pamumuhay,<br/>Maging sa lahat ng pagpupulong,<br/>Si Kristo ang sentro''t lahat-lahat;<br/>Sa Kanya nga tayo''y nagpupulong.<br/>',NULL,42334,1);
INSERT INTO stanza VALUES('T863','2','Si Kristo''y daan, ilaw ng buhay,<br/>Tayo ay lumalakad sa Kanya;<br/>Pagkain Siya at tubig na buháy;<br/>Tugon sa ating gutom, uhaw: Siya.<br/>',NULL,42335,2);
INSERT INTO stanza VALUES('T863','3','Si Kristo''y buhay, katotohanan,<br/>Ibinahagi, ipinamalas,<br/>Siya''y dinarangal na Panginoon,<br/>Siya''y Ulo, ating itinataas.<br/>',NULL,42336,3);
INSERT INTO stanza VALUES('T863','4','Sa Diyos at tao, si Kristo''y Lahat,<br/>Si Kristo ang tanging kasiyahan;<br/>Sa Ekklesia Siya ang realidad,<br/>Buhay at bilang Siya ang nagdagdag.<br/>',NULL,42337,4);
INSERT INTO stanza VALUES('T863','5','Sa pag-awit at sa panalangin,<br/>Si Kristo ang ating ihahayag;<br/>Maging sa lahat pa ng gawain,<br/>Si Kristo sa paggawa''y nahayag.<br/>',NULL,42338,5);
INSERT INTO stanza VALUES('T863','6','Tayo''y nagpupulong sa Ngalan Niya,<br/>At kumikilos sa Espiritu;<br/>Sa panalangin at pagpuri man,<br/>Sinasanay ating espiritu.<br/>',NULL,42339,6);
INSERT INTO stanza VALUES('T863','7','Limutin na ang lahat ng bagay,<br/>Tanging kay Kristo lang makiugnay;<br/>Ituring lahat na walang saysay,<br/>Siya ang Lahat-lahat sa ''ting buhay.<br/>',NULL,42340,7);
INSERT INTO stanza VALUES('T864','1','Tuwing tayo''y magpupulong,<br/>Kasaganaan ay dalhin,<br/>Upang Kristo ay maitanghal,<br/>Sa Diyos ay ihain.<br/>',NULL,42341,1);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42342,2);
INSERT INTO stanza VALUES('T864','2','Nabubuhay, gumagawa,<br/>Gabi at araw kay Kristo,<br/>Upang ating maitanghal Siya<br/>Magkaisa tayo.<br/>',NULL,42343,3);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42344,4);
INSERT INTO stanza VALUES('T864','3','Sa ating buhay at gawa,<br/>Si Kristo ang lama''t diwa,<br/>Upang sa muling pagpupulong<br/>Ay maitanghal Siya.<br/>',NULL,42345,5);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42346,6);
INSERT INTO stanza VALUES('T864','4','Sa pagpupulong ay dalhin,<br/>Kristo sa ating Diyos mahal,<br/>Siya''y ipamahagi sa lahat,<br/>Upang Siya''y matanghal.<br/>',NULL,42347,7);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42348,8);
INSERT INTO stanza VALUES('T864','5','Kristong nabuhay na muli,<br/>Ating dalhin sa Diyos Ama,<br/>Upang ang Diyos ay masiyahan,<br/>At maitanghal Siya.<br/>',NULL,42349,9);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42350,10);
INSERT INTO stanza VALUES('T864','6','Ang realidad at sentro,<br/>Ministeryo, atmospero,<br/>Sa lahat nating pagpupulong<br/>Itanghal si Kristo.<br/>',NULL,42351,11);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42352,12);
INSERT INTO stanza VALUES('T864','7','Ang dalangin, testimonia,<br/>Paggamit ng kaloob Niya,<br/>Sa ating pagsasalamuha,<br/>Dapat matanghal Siya.<br/>',NULL,42353,13);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42354,14);
INSERT INTO stanza VALUES('T864','8','Ama natin l''walhatiin,<br/>Itaas Anak na Kristo,<br/>Ang layunin ng pagpupulong:<br/>Itanghal si Kristo.<br/>',NULL,42355,15);
INSERT INTO stanza VALUES('T864','chorus','Si Kristo''y itanghal,<br/>Si Kristo''y itanghal,<br/>Dalhin ang kasaganaan<br/>Sa ekklesia lokal.<br/>',NULL,42356,16);
INSERT INTO stanza VALUES('T865','1','Sa ''spiritu, realidad,<br/>Poon sinasamba;<br/>Aral nga ito ni Kristo,<br/>Lumapit sa Kanya.<br/>',NULL,42357,1);
INSERT INTO stanza VALUES('T865','2','Siya ang Espiritung tunay,<br/>Anong lapit, mahal,<br/>Nang makaugnay sa buhay,<br/>Pagsamba ay tunay.<br/>',NULL,42358,2);
INSERT INTO stanza VALUES('T865','3','Upang sumamba sa Kanya<br/>''Spiritu''y ginawa,<br/>Di panlabas magpunyagi,<br/>Sa loob lunggati.<br/>',NULL,42359,3);
INSERT INTO stanza VALUES('T865','4','Kami''y muling sinilang Mo,<br/>Nang isip at puso<br/>Mabago, matirahan Mo,<br/>Pagsamba namin Iyo.<br/>',NULL,42360,4);
INSERT INTO stanza VALUES('T865','5','Sa panloob na pandama,<br/>Sa Iyo ang pagsamba;<br/>Espiritu''y pinahiran,<br/>Hayag kapuspusan.<br/>',NULL,42361,5);
INSERT INTO stanza VALUES('T865','6','Pagsilbi, pagsamba''y tunay,<br/>Totoong pag-alay;<br/>Samba sa Ama''y igawad:<br/>Kristong realidad.<br/>',NULL,42362,6);
INSERT INTO stanza VALUES('T865','7','Kristong naranasan namin,<br/>Sa Diyos aming hain;<br/>Kasama Niyang nasiyahan,<br/>Ilaw, katamisan.<br/>',NULL,42363,7);
INSERT INTO stanza VALUES('T865','8','Sa ''spiritu''t realidad,<br/>Pagpupulong tapat,<br/>Samba, puri''t salamuha,<br/>Sa trono ng awa.<br/>',NULL,42364,8);
INSERT INTO stanza VALUES('T866','1','''Spiritu''y sanayin,<br/>Huwag nang isipin;<br/>Sa pagpupulong din,<br/>Ito ang gawin.<br/>',NULL,42365,1);
INSERT INTO stanza VALUES('T866','2','''Spiritu''y sanayin,<br/>Di maging pormal;<br/>Si Kristo''y danasin<br/>Ng mga banal.<br/>',NULL,42366,2);
INSERT INTO stanza VALUES('T866','3','''Spiritu''y sanayin,<br/>Di ang damdamin;<br/>Si Kristo''y ihain,<br/>Gawin tungkulin.<br/>',NULL,42367,3);
INSERT INTO stanza VALUES('T866','4','''Spiritu''y sanayin,<br/>Kalul''wa''y iwan;<br/>Kristo laging sundin,<br/>At mag-ugnayan.<br/>',NULL,42368,4);
INSERT INTO stanza VALUES('T866','5','''Spiritu''y malaya<br/>Sa kahatulan,<br/>Sa kapalaluan,<br/>At kasarinlan.<br/>',NULL,42369,5);
INSERT INTO stanza VALUES('T866','6','Di makasarili<br/>Sa pagmamahal;<br/>Pasya at l''walhati,<br/>Mas espirituwal.<br/>',NULL,42370,6);
INSERT INTO stanza VALUES('T866','7','''Spiritu''y sanayin,<br/>Tagumpay kamtin;<br/>Dugo Niya''y gamitin,<br/>Ngalan tawagin.<br/>',NULL,42371,7);
INSERT INTO stanza VALUES('T866','8','''Spiritu''y sanayin,<br/>Kristo''y hipuin;<br/>Yaman Niya''y tamuhin,<br/>Salita''y kunin.<br/>',NULL,42372,8);
INSERT INTO stanza VALUES('T866','9','Dahil sa ''spiritu,<br/>Hayag si Kristo;<br/>Dahil sa ''spiritu,<br/>Tao''y kontento.<br/>',NULL,42373,9);
INSERT INTO stanza VALUES('T866','10','''Spiritu''y sanayin,<br/>Ating kailangan;<br/>''Spiritu''y sanayin,<br/>Kristo ay sundan.<br/>',NULL,42374,10);
INSERT INTO stanza VALUES('T867','1','Bilang sangkap ni Kristo,<br/>Katawa''y ihayag,<br/>Sa pagkilos matuto,<br/>Kristo maihayag;<br/>Kikilos bawa''t sangkap,<br/>Walang manonood,<br/>Kamatayan, pinsala<br/>Huwag nating idulot.<br/>',NULL,42375,1);
INSERT INTO stanza VALUES('T867','2','Tulad ng isang pangkat,<br/>Mag-isa huwag gawin,<br/>Umaasa ang dapat,<br/>Pagtugma-tugmain;<br/>Iwaksi pagpipili,<br/>Ang daloy ay sundin,<br/>Daan ng Espiritu<br/>Ay ating alamin.<br/>',NULL,42376,2);
INSERT INTO stanza VALUES('T867','3','Tuon nati''y si Kristo,<br/>Walang ibang sentro;<br/>Salamuha kay Kristo,<br/>Yaman makasalo.<br/>Siya''y Ulo''t nilalaman,<br/>Ihayag Katawan;<br/>Sa ''ting pulong anuman,<br/>Siya ang patunayan.<br/>',NULL,42377,3);
INSERT INTO stanza VALUES('T867','4','Walang magpipintasan,<br/>Kundi magmahalan;<br/>Lahat ay mangag-aral,<br/>Na mangagpasakdal.<br/>Espiritu''y sanayin<br/>Sa buhay-Katawan;<br/>Buhay likas iwaksi,<br/>Maging ang sarili.<br/>',NULL,42378,4);
INSERT INTO stanza VALUES('T870','1','Tindig! Para kay Hesus!<br/>Ang sundalo ng krus;<br/>Itaas ang bandila,<br/>Sundin Kanyang utos.<br/>Kristo ang namumuno,<br/>Hukbo Niya''y panalo,<br/>Kaaway pawang talo,<br/>Kay Hesus sumuko.<br/>',NULL,42379,1);
INSERT INTO stanza VALUES('T870','chorus','Tindig kay Hesus<br/>Ang sundalo ng krus;<br/>Itaas ang bandila,<br/>Sundin nga, sundin Kanyang utos.<br/>',NULL,42380,2);
INSERT INTO stanza VALUES('T870','2','Tindig! Para kay Hesus!<br/>Trumpeta''y pakinggan;<br/>Magmartsa sa digmaan,<br/>Hesus ating sundan.<br/>Marami man kalaban,<br/>Ating lulusubin,<br/>Higit ang katapangan,<br/>Kaaway lipulin.<br/>',NULL,42381,3);
INSERT INTO stanza VALUES('T870','3','Tindig! Para kay Hesus!<br/>Tindig sa lakas Niya;<br/>Hindi laman, sarili,<br/>Ang ating sandata.<br/>Suot baluti ng Diyos,<br/>Laging manalangin,<br/>Sa tawag ng tungkulin<br/>Ay hindi tumanggi.<br/>',NULL,42382,5);
INSERT INTO stanza VALUES('T870','4','Tindig! Para kay Hesus!<br/>Di tatagal laban:<br/>Ngayon ay ang pingkian,<br/>Bukas ay awitan;<br/>Sa bawa''t magtagumpay<br/>Korona ng buhay;<br/>Kasamang maghahari,<br/>Hari ng l''walhati.<br/>',NULL,42383,7);
INSERT INTO stanza VALUES('T871','1','Sundalong Kristiyano,<br/>Sumulong tayo!<br/>Nangunguna ang krus<br/>Sa ''tin ni Hesus.<br/>Kristong Ulo''y una,<br/>Sa pagbabaka,<br/>Sulong sa labanan,<br/>Bandila''y masdan.<br/>',NULL,42384,1);
INSERT INTO stanza VALUES('T871','chorus','Sundalong Kristiyano,<br/>Sumulong tayo!<br/>Nangunguna ang krus<br/>Sa ''tin ni Hesus.<br/>',NULL,42385,2);
INSERT INTO stanza VALUES('T871','2','Sa ngalan ni Hesus<br/>Kaaway ubos;<br/>Sa pagtatagumpay<br/>Nang walang humpay!<br/>Sa papuring tinig<br/>Hades yayanig:<br/>Papuri''y lakasan<br/>At mag-awitan.<br/>',NULL,42386,3);
INSERT INTO stanza VALUES('T871','3','Ang Ekklesia ng Diyos<br/>Ang kumikilos;<br/>Katulad ng hukbo<br/>Ay humahayo;<br/>Sa Katawan isa—<br/>Sa paniwala,<br/>Sa ''Spiritu isa<br/>Kailanma''y isa.<br/>',NULL,42387,5);
INSERT INTO stanza VALUES('T871','4','Kaharian, trono<br/>Man ay maglaho,<br/>Ekklesia ni Hesus<br/>Di mauubos.<br/>Ekklesia''y di gahis<br/>Pinto ng Hades;<br/>Dahil sa pangako<br/>Ng ating Kristo.<br/>',NULL,42388,7);
INSERT INTO stanza VALUES('T871','5','Tayo''y sama-sama<br/>Sa pagsasaya:<br/>Awit ng tagumpay<br/>Ating ialay.<br/>Gloria, dangal, puri<br/>Kay Kristong Hari;<br/>Tuloy walang hanggan<br/>Ating awitan.<br/>',NULL,42389,9);
INSERT INTO stanza VALUES('T873','1','Sugod, sundalo, sugod!<br/>At makipagbaka;<br/>Awitin ng paglusob—<br/>"Tayo''y nanalo na!"<br/>Karimlan ay umurong,<br/>Satanas nabagbag;<br/>Hukbong puno sumulong,<br/>Tagumpay nahayag.<br/>',NULL,42390,1);
INSERT INTO stanza VALUES('T873','2','Sugod, sundalo, sugod!<br/>Ang Poon masdan mo,<br/>Gantimpala mo''y trono,<br/>Kung ika''y nanalo.<br/>''Spirituwal ang labanan<br/>Hindi makalupa;<br/>Tayo''y pinaligiran<br/>Ng puwersang masama.<br/>',NULL,42391,2);
INSERT INTO stanza VALUES('T873','3','Sugod, sundalo, sugod!<br/>Kamtin mo ang trono,<br/>Pagkabuhay ni Kristo<br/>Ang kalakasan mo.<br/>Kapangyariha''y Kanya,<br/>Kaaway puksain,<br/>Sa pamamagitan Niya,<br/>Tagumpay awitin.<br/>',NULL,42392,3);
INSERT INTO stanza VALUES('T873','4','Sugod, sundalo, sugod!<br/>Trono''y para sa iyo,<br/>Sa piging Niya magsalo,<br/>Lubos ang galak mo.<br/>Nabuhay kasama Niya,<br/>Lumuklok sa langit,<br/>Malayo na sa giyera,<br/>Sa sala''t ligalig.<br/>',NULL,42393,4);
INSERT INTO stanza VALUES('T873','5','Sugod, sundalo, sugod!<br/>Manahin ang trono,<br/>Sa lupa ka hinango,<br/>Kaharia''y sa iyo.<br/>Hinaharap maganda,<br/>Wala na sa dilim,<br/>Kristo''y laging kasama,<br/>Pag-ibig Niya''y kamtin.<br/>',NULL,42394,5);
INSERT INTO stanza VALUES('T873','6','Galak ang sigaw, sugod!<br/>Kamtin mo ang putong!<br/>Awit tagumpay sulong<br/>Sa bundok ng Sion.<br/>Kordero''y nagtagumpay!<br/>At nasa trono Siya!<br/>Puri''t galak ialay,<br/>Dapat manaig Siya.<br/>',NULL,42395,6);
INSERT INTO stanza VALUES('T876','1','Diyablo''y nanggagahis,<br/>Digma''y ''bangis;<br/>Tiwala''y Salita,<br/>Laksan kanta.<br/>',NULL,42396,1);
INSERT INTO stanza VALUES('T876','2','Minsang sumigaw ka,<br/>Tagumpay na!<br/>Huwag itikom bibig,<br/>Huwag padaig.<br/>',NULL,42397,2);
INSERT INTO stanza VALUES('T876','3','Espiritung pigil,<br/>Lakas siil,<br/>Sa dugo''y tagumpay,<br/>Sanhi''y dasal.<br/>',NULL,42398,3);
INSERT INTO stanza VALUES('T876','4','Mabangis kalaban,<br/>Siya''y labanan;<br/>Sa p''westo pumirmi,<br/>Magwawagi.<br/>',NULL,42399,4);
INSERT INTO stanza VALUES('T876','5','Ideklara Mo na,<br/>Tagumpay Niya;<br/>Dilim lumiwanag,<br/>Anong galak!<br/>',NULL,42400,5);
INSERT INTO stanza VALUES('T877','1','Di ako patatalo, dahil sa Kalbaryo,<br/>Doon si Hesus nagtagumpay sa kaaway,<br/>Panginoon bigyan akong pangitain Mo;<br/>Lakas ng Espiritu ang Iyong ibinigay.<br/>',NULL,42401,1);
INSERT INTO stanza VALUES('T877','chorus','Tagumpay, tagumpay!<br/>Dahil sa Kalbaryo.<br/>Gawing mandaraig ako,<br/>O, Panginoon, sa loob Mo.<br/>',NULL,42402,2);
INSERT INTO stanza VALUES('T877','2','Di ako patatalo, sa labang nilusob<br/>Ni Kristo at tinawag akong makibaka;<br/>Panginoon, ako''y bigyan ng lakas-loob,<br/>Espiritu ng lakas, ihahayag ko Siya.<br/>',NULL,42403,3);
INSERT INTO stanza VALUES('T877','3','Di ako patatalo, si Hesus nanguna<br/>Sa marahas na landas tungo sa Luklukan,<br/>Bigyan mo ang sundalo — tabak ng Salita,<br/>Tagumpay ay dulot ng Iyong kapangyarihan.<br/>',NULL,42404,5);
INSERT INTO stanza VALUES('T877','4','Di ako patatalo, paglubog ng araw<br/>Si Hesus ay handang ako''y gantimpalaan,<br/>Panginoon, Luwalhati Mo ay matanaw,<br/>Ako''y matagumpay hanggang sa katapusan.<br/>',NULL,42405,7);
INSERT INTO stanza VALUES('T880','1','Sa Ama ako''y sasang-ayon,<br/>Sa kaaway tatanggi;<br/>Nang ang Kanyang payo''t layon<br/>Magawang may pagwagi.<br/>Kapag sumusunod ako,<br/>Awtoridad bigyan Mo<br/>Upang matupad layon Mo,<br/>Sa lakas ng ''Spiritu.<br/>',NULL,42406,1);
INSERT INTO stanza VALUES('T880','2','Sa Ama ako''y sasang-ayon,<br/>Sa kaaway tatanggi;<br/>Ingatan ng Panginoon<br/>Saloobin ko''t gawi,<br/>Kung sa aking pagtalima,<br/>Satanas ay humadlang;<br/>Hesus, bigyan akong awa,<br/>Utos Mo''y mapakinggan.<br/>',NULL,42407,2);
INSERT INTO stanza VALUES('T880','3','Sa Ama ako''y sasang-ayon,<br/>Sa kaaway tatanggi;<br/>Ako''y susunod sa Kanya,<br/>Ang dusa ma''y mang-api.<br/>Kung ako ay iingatan<br/>Ng aking Panginoon,<br/>Pagsubok man o kalaban,<br/>Ako''y di mahadlangan.<br/>',NULL,42408,3);
INSERT INTO stanza VALUES('T885','1','Sa Katawan, makibaka,<br/>Hindi sa sarili mo;<br/>Ugpong Katawan at Ulo,<br/>Pagbabaka''y sa trono.<br/>',NULL,42409,1);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42410,2);
INSERT INTO stanza VALUES('T885','2','Baluti ng Diyos ay para<br/>Sa Katawan, di isa;<br/>Pagbaka mo sa Katawan,<br/>Sa iyo ang pakinabang.<br/>',NULL,42411,3);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42412,4);
INSERT INTO stanza VALUES('T885','3','Satanas di matatalo<br/>Ekklesiang naitayo<br/>Ni Kristo nang sama-sama<br/>Pipigilan masama.<br/>',NULL,42413,5);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42414,6);
INSERT INTO stanza VALUES('T885','4','Sa Katawan, Pagka-ulo,<br/>Sa langit nakaupo,<br/>Nakikipagbuno tayo<br/>Sa buktot na ''spiritu.<br/>',NULL,42415,7);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42416,8);
INSERT INTO stanza VALUES('T885','5','Sangkap ng Katawan tayo,<br/>Para sa Diyos tatayo;<br/>Magdasal sa Espiritu,<br/>Tagumpay ay sa Dugo.<br/>',NULL,42417,9);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42418,10);
INSERT INTO stanza VALUES('T885','6','Higit pa sa matagumpay,<br/>Sa kapangyarihan Niya;<br/>Makipaglaban sundalong<br/>Hukbo ng Panginoon.<br/>',NULL,42419,11);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42420,12);
INSERT INTO stanza VALUES('T885','7','Sa Katawan makibaka,<br/>Tagumpay makikita,<br/>Sa pagtatali, pagkalag,<br/>Kakainin kaaway.<br/>',NULL,42421,13);
INSERT INTO stanza VALUES('T885','chorus','Sa awtoridad ng Ulo,<br/>Pagbaka''y sa Katawan;<br/>Sa Katawan magtumibay,<br/>Kayo''y magtatagumpay.<br/>',NULL,42422,14);
INSERT INTO stanza VALUES('T886','1','Matibay na Moog ang Diyos,<br/>Di magigibang Kuta;<br/>Tutulungan Niya nang lubos<br/>Ang bihag ng masama.<br/>Pagka''t ang kaaway<br/>Ay sumasalakay;<br/>Tuso''t mabangis siya,<br/>May-poot, dahas pa,<br/>Sa lupa''y walang gaya.<br/>',NULL,42423,1);
INSERT INTO stanza VALUES('T886','2','Kung sa sarili''y umasa,<br/>Pagsisikap ay talo;<br/>Tamang Tao ang kasama,<br/>Hirang ng Diyos na Tao:<br/>Sino kaya Si-ya?<br/>Si Kristo Hesus nga;<br/>Diyos ng mga hukbo,<br/>Di Siya nagbabago,<br/>Sa labana''y nanalo.<br/>',NULL,42424,2);
INSERT INTO stanza VALUES('T886','3','Mundo''y lipos ng demonyo,<br/>Sa atin nagbabanta;<br/>Katotohana''y panalo,<br/>Diyos sa ati''y ''tinakda:<br/>Prinsipe ng Dilim,<br/>Di kayang yanigin;<br/>Galit niya''y tiisin,<br/>Ti-yak siyang talunin,<br/>Sa salita''y lipulin.<br/>',NULL,42425,3);
INSERT INTO stanza VALUES('T886','4','Ang salita''y nagwagi rin,<br/>At siya''y nananatili;<br/>Kaloob, ''Spiritu''y atin,<br/>Diyos ang ating kakampi:<br/>Lahat ma''y mawala,<br/>Yaman at buhay pa;<br/>Ang katotohanan,<br/>Di mababawasan,<br/>Kaharia''y walang hanggan.<br/>',NULL,42426,4);
INSERT INTO stanza VALUES('T887','1','Ngalang Hesus ang saligan,<br/>Siya''ng ating tagumpay;<br/>Sarili''y hindi asahan,<br/>Kundi sa Maykapal;<br/>Tabak ng ''Spiritu''y kunin,<br/>Di armas ng laman;<br/>Baluti ng Diyos suotin,<br/>Lipulin kalaban.<br/>',NULL,42427,1);
INSERT INTO stanza VALUES('T887','2','Nagtitipon ang kalaban,<br/>Magtumibay tayo!<br/>Sa mabagsik na labanan,<br/>Umasa kay Kristo!<br/>Kung matakot, umurong nga,<br/>Hukbo''y manghihina;<br/>Kapatid hu-wag biguin,<br/>Ni panlupaypayin.<br/>',NULL,42428,2);
INSERT INTO stanza VALUES('T887','3','Gahol sa oras ang diyablo,<br/>Lalong mabangis siya,<br/>Pahihinain ka bago<br/>Laban magsimula.<br/>Panlilinlang, dusa''t tukso<br/>Higit kaysa dati,<br/>Hades mag-uusig sa ''tin<br/>Nang lalong matindi.<br/>',NULL,42429,3);
INSERT INTO stanza VALUES('T887','4','Sa panganib ng panahon<br/>Saloobin ano?<br/>Kaaway tayo''y matalo<br/>Kung sa layaw ayon.<br/>Tiising may katapangan,<br/>Matinding labanan;<br/>Buhay o kamatayan nga,<br/>Diyos mapupuri ba?<br/>',NULL,42430,4);
INSERT INTO stanza VALUES('T887','5','Sa matagumpay na Kristo,<br/>Tayo''y manindigan!<br/>Tiisin ang sakripisyo<br/>Nang matapos laban.<br/>Panginoon ay darating,<br/>Tagumpay ay kamtin;<br/>Kung ngayon tayo''y magdusa,<br/>Magharing kasama.<br/>',NULL,42431,5);
INSERT INTO stanza VALUES('T890','1','Aleluya! Mandaraig<br/>Ang ating Kristo!<br/>Ang kamatayan at sala<br/>Kanyang tinalo.<br/>',NULL,42432,1);
INSERT INTO stanza VALUES('T890','chorus','Aleluya! Mandaraig<br/>Ang ating Kristo!<br/>Siya ay laging nananaig<br/>Kaaway talo.<br/>',NULL,42433,2);
INSERT INTO stanza VALUES('T890','2','Aleluya! Mandaraig<br/>Ang ating Kristo!<br/>Mga kahinaan, sakit<br/>Pawang lalayo.<br/>',NULL,42434,3);
INSERT INTO stanza VALUES('T890','3','Aleluya! Mandaraig<br/>Ang ating Kristo!<br/>May dalangi''t pananalig,<br/>Tayo''y hahayo!<br/>',NULL,42435,5);
INSERT INTO stanza VALUES('T890','4','Ating Kristo Mandaraig,<br/>Di na mangamba;<br/>Kristo ay liliwanagin<br/>Ang pangitain.<br/>',NULL,42436,7);
INSERT INTO stanza VALUES('T890','5','Ating Kristo''y mandaraig!<br/>O Aleluya!<br/>Pagbalik Niya: Mandaraig<br/>May gantimpala!<br/>',NULL,42437,9);
INSERT INTO stanza VALUES('T892','1','Kay Kristo ang awtoridad<br/>Sa langit at buong lupa;<br/>Kai-sa, mamuhay sa Kanya,<br/>Susuko ang kalaban Niya.<br/>',NULL,42438,1);
INSERT INTO stanza VALUES('T892','2','Sa ngalang Hesus ibadya,<br/>Kaaway madaraig nga;<br/>Awtoridad Niya ay kamtan<br/>Nang ahas ay matapakan.<br/>',NULL,42439,2);
INSERT INTO stanza VALUES('T892','3','Bundok man na mataas ka,<br/>Saan man sa langit, lupa,<br/>Sa ngalang Hesus alisin,<br/>Papantayin ka nga namin.<br/>',NULL,42440,3);
INSERT INTO stanza VALUES('T892','4','"Bundok, masugba sa dagat!"<br/>Pananalig ang nag-utos;<br/>Tiyak, handa, nais, dapat—<br/>Tupding tapat layon ng Diyos.<br/>',NULL,42441,4);
INSERT INTO stanza VALUES('T893','1','Matinding labanan,<br/>Sigaw ng digmaan,<br/>Lakas ni Satanas higit,<br/>Ngayon kaysa dati.<br/>Tinig ng impiyerno,<br/>Lumakas na lalo;<br/>Nguni''t pakinggan tinig Niya,<br/>Ako''y parating na.<br/>',NULL,42442,1);
INSERT INTO stanza VALUES('T893','2','Pagsubok pumait,<br/>Labanan humigit;<br/>Nagtipon puwersa ng sama<br/>Upang lumusob na.<br/>Sa tindi ng digma<br/>Maghintay, magbantay,<br/>Narinig himig masaya,<br/>Hesus malapit na!<br/>',NULL,42443,2);
INSERT INTO stanza VALUES('T893','3','Mas hirap na ngayon<br/>Verbo''y patunayan,<br/>Ating pagsaksi''y salangsang<br/>Lakas ni Satanas.<br/>Pagdating kalaban,<br/>Mas lakas kailangan;<br/>Anong galak makita Siya<br/>Walang himutok na!<br/>',NULL,42444,3);
INSERT INTO stanza VALUES('T893','4','Sino ang susulong<br/>Sa Kanya''y tumibay?<br/>Sinong sa Kanya''y aasa<br/>Hanggang magtagumpay;<br/>Hanggang mandaraig,<br/>Tagumpay aawit?<br/>Narinig nang maligaya,<br/>Ako''y parating na!<br/>',NULL,42445,4);
INSERT INTO stanza VALUES('T893','5','Piliin magaling,<br/>Makitid tahakin,<br/>Mahirap man at bagyuhin,<br/>Hindi lilingunin?<br/>Matitiis mo ba,<br/>Dusa at pangamba?<br/>Lahat magalak makita<br/>Hesus, malapit na!<br/>',NULL,42446,5);
INSERT INTO stanza VALUES('T893','6','Malalim mang dilim,<br/>Kami tuloy pa rin,<br/>Hanggang mai-akyat may galak<br/>Gloria''y lumiwanag.<br/>Hari makikita,<br/>Satanas talo na;<br/>Mandaraig magsisaya,<br/>Hesus dumating na!<br/>',NULL,42447,6);
INSERT INTO stanza VALUES('T894','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42448,1);
INSERT INTO stanza VALUES('T894','1','Magiging mandaraig ba?<br/>Tawag ni Kristo!<br/>Tagasunod, nais mo ba,<br/>Kahit di tanto?<br/>',NULL,42449,2);
INSERT INTO stanza VALUES('T894','chorus','Magiging mandaraig ba?<br/>Pagpasyahan mo,<br/>Ngayon ay tumatawag Siya,<br/>Tinig dinggin mo!<br/>',NULL,42450,3);
INSERT INTO stanza VALUES('T894','2','Magiging mandaraig ba?<br/>Lapit sa Kanya!<br/>"Unang pag-ibig" sa Kanya,<br/>Huwag magpabaya.<br/>',NULL,42451,4);
INSERT INTO stanza VALUES('T894','3','Magiging mandaraig ba?<br/>Asa''y buhay Niya;<br/>Sa pag-uusig magdusa,<br/>Maging tapat ka.<br/>',NULL,42452,6);
INSERT INTO stanza VALUES('T894','4','Magiging mandaraig ba?<br/>Maging saksi ka!<br/>Iwan relih''yon, makuha<br/>Ang "tagong manna."<br/>',NULL,42453,8);
INSERT INTO stanza VALUES('T894','5','Magiging mandaraig ba,<br/>Tunay at wagas?<br/>Kasamaan ay mapuksa,<br/>Sa iyo ang lakas.<br/>',NULL,42454,10);
INSERT INTO stanza VALUES('T894','6','Magiging mandaraig ba?<br/>Kristo''y asahan;<br/>Damit ingatang dungisan<br/>Ng kamatayan.<br/>',NULL,42455,12);
INSERT INTO stanza VALUES('T894','7','Magiging mandaraig ba?<br/>Ngalan huwag ''kaila!<br/>Tupdin ang Kanyang salita,<br/>Gawin iyong kaya.<br/>',NULL,42456,14);
INSERT INTO stanza VALUES('T894','8','Magiging mandaraig ba?<br/>Kamtin higit pa:<br/>Huwag maging malahininga,<br/>Ni palalo pa!<br/>',NULL,42457,16);
INSERT INTO stanza VALUES('T894','9','Magiging mandaraig ba?<br/>Tinatawag ka,<br/>Ngayon ba''y tapat sa Kanya,<br/>Tupdin atas Niya?<br/>',NULL,42458,18);
INSERT INTO stanza VALUES('T907','1','Di sa gustong puntahan,<br/>Kundi gabay ni Hesus,<br/>Lumiwanag karimlan,<br/>Doon buhay umagos.<br/>',NULL,42459,1);
INSERT INTO stanza VALUES('T907','2','Di ang gawang pinili<br/>Tatamo ng papuri,<br/>Hindi gawang tinakda,<br/>Gawin para sa Kanya.<br/>',NULL,42460,2);
INSERT INTO stanza VALUES('T907','3','Samo di ayon sa ''kin,<br/>Pagdulog ko sa Trono;<br/>Nguni''t lalim hipuin,<br/>Hibik ng Espiritu.<br/>',NULL,42461,3);
INSERT INTO stanza VALUES('T907','4','Di handog sa dambana<br/>Ang bibigyang-pansin Niya,<br/>Anas Niya''y may kailangan,<br/>Puso ay huwag tanggihan.<br/>',NULL,42462,4);
INSERT INTO stanza VALUES('T907','5','Nabuhay pagkamatay<br/>Sa mga kalangitan;<br/>Maglingkod, dasal, alay,<br/>Kristong Premyo mataglay.<br/>',NULL,42463,5);
INSERT INTO stanza VALUES('T908','1','Bagong Tipa''y di sa titik,<br/>Kundi sa ''spiritu lang;<br/>''Spiritu''y nagbigay buhay,<br/>Ang titik pumapaslang.<br/>Gawang di mula sa loob,<br/>Di binibilang ng Diyos;<br/>Di sa titik paglilingkod,<br/>Kundi sa buhay lubos.<br/>',NULL,42464,1);
INSERT INTO stanza VALUES('T908','2','Di sa panlabas na turo,<br/>Kundi sa pagpapahid;<br/>Di sa huwarang panlabas,<br/>Kundi sa pangitain.<br/>Pamumunong makalangit,<br/>Hindi ito pantao;<br/>Paggabay at pahayag Niya,<br/>Di pagpasya ng tao.<br/>',NULL,42465,2);
INSERT INTO stanza VALUES('T908','3','Di silbihan relihiyon<br/>Kundi Kristo''y ibuhay<br/>Ni hindi teolohiya,<br/>Ibigay Kristong buháy.<br/>Tanging Kristo ang mensahe,<br/>Di alam na doktrina.<br/>Kristo ng Diyos — realidad,<br/>Di kaloob ni porma.<br/>',NULL,42466,3);
INSERT INTO stanza VALUES('T908','4','Mula sa loob maglingkod,<br/>Di pagsambang panlabas;<br/>Subhektibong ipahayag,<br/>Kristo nating dinanas.<br/>Sa espiritu at buhay,<br/>Paglingkod di sa titik,<br/>Sa ''Spiritu, di sa laman,<br/>Malaya sa pigapit.<br/>',NULL,42467,4);
INSERT INTO stanza VALUES('T909','1','Sa agos gumawa para sa Pangino''n,<br/>Ayon sa Salita, Kanyang isip, daan,<br/>Sa agos ng buhay at kapangyarihan<br/>Maglingkod sa Ekklesia at Kaharian.<br/>',NULL,42468,1);
INSERT INTO stanza VALUES('T909','chorus','Sa agos! sa agos!<br/>Gumawa sa agos!<br/>Maglingkod kalakip<br/>Ng lahat ng mga banal!<br/>',NULL,42469,2);
INSERT INTO stanza VALUES('T909','2','Sa agos gumawa kasama ng Poon,<br/>Salita''y sundin sa agos ng ''Spiritu.<br/>Huwag sarilihin ang gawa o mag-isa,<br/>Kundi magtulungan, makipagkaisa.<br/>',NULL,42470,3);
INSERT INTO stanza VALUES('T909','3','Sa agos gumawa sa loob ng Poon,<br/>Sa Ekklesia at sa ilaw ng Salita.<br/>Mag-ebanghelyo, mamahagi ng buhay,<br/>Nang matupad ng Diyos Kanyang panukala.<br/>',NULL,42471,5);
INSERT INTO stanza VALUES('T910','1','Gawa''y pag-apaw ng buhay,<br/>Dapat ding pamumuhay!<br/>Pamumuhay, gawa''y isa,<br/>Gawa''y magkakabunga.<br/>Karanasang sinalita,<br/>Mensaheng totoo nga;<br/>Mensaheng may karanasan,<br/>Sadyang may kalakasan.<br/>',NULL,42472,1);
INSERT INTO stanza VALUES('T910','2','Bunga ng buhay ang gawa,<br/>Espiritu''y namunga;<br/>Tulad ng ubas sa sanga,<br/>Hayag buhay sagana.<br/>Sa pamamagitan natin,<br/>Gumagawa si Kristo.<br/>Upang yaman ng buhay Niya<br/>Mahayag nga sa atin.<br/>',NULL,42473,2);
INSERT INTO stanza VALUES('T910','3','Di tao ang umaakto,<br/>Kundi ang Espiritu;<br/>Di panlabas na paggawa,<br/>Kundi ang panloob nga;<br/>Di ''sang uring hanapbuhay,<br/>Kundi Diyos ipamuhay;<br/>Di pagpagal nang magwagi,<br/>Kundi ''hayag Siyang lagi.<br/>',NULL,42474,3);
INSERT INTO stanza VALUES('T910','4','Ating balak, layon, kaya,<br/>Lahat dapat wala na,<br/>Nang Siya''y makagawa sa ''tin,<br/>Layunin Niya''y tuparin.<br/>Tangkilik natin, tayo man,<br/>Lagak sa kamatayan.<br/>Nang sa atin mamuhay Siya,<br/>Hayag yaman, rilag Niya.<br/>',NULL,42475,4);
INSERT INTO stanza VALUES('T911','1','Kristo ang lahat sa buhay<br/>Ng isang saserdote;<br/>Damit, pagkain, tahanan,<br/>At bahagi niyang laan.<br/>',NULL,42476,1);
INSERT INTO stanza VALUES('T911','chorus','Kristo ang lahat sa buhay<br/>Ng isang saserdote;<br/>Damit, pagkain, tahanan,<br/>At bahagi niyang laan.<br/>',NULL,42477,2);
INSERT INTO stanza VALUES('T911','2','Ang damit ng saserdote:<br/>Epod, mitra, pektoral;<br/>Kay Kristo ang luwalhati,<br/>Maganda at marangal.<br/>',NULL,42478,3);
INSERT INTO stanza VALUES('T911','3','Handog niya sa Diyos si Kristo,<br/>Haing kalugdan ng Diyos;<br/>Makakain niya si Kristo<br/>Bilang mayamang tustos.<br/>',NULL,42479,5);
INSERT INTO stanza VALUES('T911','4','Ibihis, kai-sa, si Kristo,<br/>Panlabas — ihayag Siya;<br/>Kainin, inumin Kristo,<br/>Panloob — angkinin Niya.<br/>',NULL,42480,7);
INSERT INTO stanza VALUES('T911','5','Tahanan ng saserdote<br/>Ang pinalaking Kristo;<br/>Sila''y ''tinayong bahagi<br/>Ng bahay sa ''spiritu.<br/>',NULL,42481,9);
INSERT INTO stanza VALUES('T911','6','Ang mana ng saserdote:<br/>Si Kristong lahat-lahat;<br/>Panustos ng buhay lagi,<br/>Kay Kristo rin nagbuhat.<br/>',NULL,42482,11);
INSERT INTO stanza VALUES('T912','1','Ang maglingkod ay maghain<br/>Ng Kristo sa tao''t Diyos;<br/>Ang maglingkod ay mag-alay<br/>Ng Kristo bilang tustos.<br/>',NULL,42483,1);
INSERT INTO stanza VALUES('T912','chorus','Ang maglingkod ay maghain<br/>Ng Kristo sa tao''t Diyos;<br/>Ang maglingkod ay mag-alay,<br/>Ng Kristo bilang tustos.<br/>',NULL,42484,2);
INSERT INTO stanza VALUES('T912','2','Naghandog ang Israelita<br/>Ng bunga ng lupain;<br/>Kay Hesus inaning bunga<br/>Sa Diyos ialay natin.<br/>',NULL,42485,3);
INSERT INTO stanza VALUES('T912','3','Tayo''y magpagal kay Kristo—<br/>Ang mabuting lupain;<br/>Saganang ani at tubo,<br/>Ipamahagi natin.<br/>',NULL,42486,5);
INSERT INTO stanza VALUES('T912','4','Hawakan natin si Kristo,<br/>Tanggapin, tamasahin;<br/>Bilang sangkap ay lalago,<br/>Sa Katawan maghain.<br/>',NULL,42487,7);
INSERT INTO stanza VALUES('T912','5','Patotoo, salamuha,<br/>Pagsamba''t ministeryo,<br/>Sa lahat na mga gawa,<br/>Ang ihain si Kristo.<br/>',NULL,42488,9);
INSERT INTO stanza VALUES('T913','1','Sa loob ng Katawan nga,<br/>Maglingkod at gumawa;<br/>Katawan ang layunin Niya,<br/>Tayo ay umayon nga.<br/>',NULL,42489,1);
INSERT INTO stanza VALUES('T913','chorus','Sa loob ng Katawan nga,<br/>Maglingkod at gumawa,<br/>Di-malaya bilang sangkap<br/>Bagkus magkoordina.<br/>',NULL,42490,2);
INSERT INTO stanza VALUES('T913','2','Pagkasilang-muli natin,<br/>Tayo naging sangkap din;<br/>Di na dapat nag-iisa,<br/>Paglilingkod sa Kanya.<br/>',NULL,42491,3);
INSERT INTO stanza VALUES('T913','3','Batong buháy naitayo,<br/>Bilang buháy na templo;<br/>Bilang saserdote ng Diyos,<br/>Nagkakaisang lubos.<br/>',NULL,42492,5);
INSERT INTO stanza VALUES('T913','4','Pagtatayo ay tuparin,<br/>Bawa''t pangsyon gagawin;<br/>Paglilingkod ay saligan<br/>Ugali ng katawan.<br/>',NULL,42493,7);
INSERT INTO stanza VALUES('T913','5','Sa gawa''t paglingkod naman,<br/>Katawa''y natustusan;<br/>''Pag lumayo sa Katawan,<br/>Hantunga''y kamatayan.<br/>',NULL,42494,9);
INSERT INTO stanza VALUES('T913','6','Paglilingkod sa Katawan,<br/>Yaman ng Ulo''y kamtan;<br/>Pangsyon ng sangkap tinupad,<br/>Sukat ni Kristo''y ganap.<br/>',NULL,42495,11);
INSERT INTO stanza VALUES('T913','7','Kay Kristo susulong tayo,<br/>Tanganan bilang Ulo;<br/>Mula sa Kanya ang tustos,<br/>Sa sangkap ang pag-agos.<br/>',NULL,42496,13);
INSERT INTO stanza VALUES('T913','8','Katawan inalay namin,<br/>Kami Iyong transpormahin;<br/>Upang layon Mo''y malaman,<br/>Pagsilbi''y sa Katawan.<br/>',NULL,42497,15);
INSERT INTO stanza VALUES('T914','1','Silbi''y para sa Ekklesia;<br/>Ang sakdal Niyang layunin;<br/>''To''y tanging daan ng gawa,<br/>Dapat nating tahakin.<br/>',NULL,42498,1);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42499,2);
INSERT INTO stanza VALUES('T914','2','Ekklesia''y sisidlan ng Diyos,<br/>Walang hanggang layon Niya;<br/>Hangarin Niyang paglilingkod,<br/>Ekklesia maitayo.<br/>',NULL,42500,3);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42501,4);
INSERT INTO stanza VALUES('T914','3','Kaloob bigay ng Ulo,<br/>Para nga sa Katawan;<br/>Tutulong sa pagtatayo,<br/>Matanghal kapuspusan.<br/>',NULL,42502,5);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42503,6);
INSERT INTO stanza VALUES('T914','4','Sa Katawan nga ni Kristo;<br/>Lakas ng Espiritu;<br/>Nakita pangsyon, kaloob,<br/>Lahat ng ministeryo.<br/>',NULL,42504,7);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42505,8);
INSERT INTO stanza VALUES('T914','5','Paghayag ng Ebanghelyo,<br/>Gawaing pagtuturo;<br/>Lahat ng uring serbisyo,<br/>Sa Katawan ni Kristo.<br/>',NULL,42506,9);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42507,10);
INSERT INTO stanza VALUES('T914','6a','Para sa mga Ekklesia,<br/>Gawaing ministeryo;<br/>Hindi ang mga Ekklesia,<br/>Para sa mga ministeryo.<br/>',NULL,42508,11);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42509,12);
INSERT INTO stanza VALUES('T914','6b','Patungang-ilawang ginto,<br/>Ang lahat ng Ekklesia;<br/>Kahit aling ministeryo,<br/>Hindi nga ang Ekklesia.<br/>',NULL,42510,13);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42511,14);
INSERT INTO stanza VALUES('T914','7','Mapanatili sa gayon,<br/>Kai-sahan sa Ekklesia;<br/>Motibo''y masusubukan,<br/>Maituwid ang layon.<br/>',NULL,42512,15);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42513,16);
INSERT INTO stanza VALUES('T914','8','Para sa Ekklesia nawa,<br/>Aming buhay, pagpagal;<br/>Iligtas sa sektang gawa,<br/>Iyong pagtayo''y itanghal.<br/>',NULL,42514,17);
INSERT INTO stanza VALUES('T914','chorus','Silbi''y para sa Ekklesia<br/>Di sariling layunin<br/>Layon ng Diyos, ligaya Niya<br/>Dapat nga nating sundin.<br/>',NULL,42515,18);
INSERT INTO stanza VALUES('T918','1','Kristiyano, magmadali at humayo,<br/>Ipahayag ang Diyos ay liwanag,<br/>Hindi Niya ibig ni isang kalul''wa,<br/>Sa dilim ng gabi''y mapahamak.<br/>',NULL,42516,1);
INSERT INTO stanza VALUES('T918','chorus','Ihayag masayang balita,<br/>Hesus Manunubos, nagpapalaya.<br/>',NULL,42517,2);
INSERT INTO stanza VALUES('T918','2','Libong tao ay nasa kasalanan,<br/>Ginapos, inalipin ng Diyablo,<br/>Walang nagbalita ng kaligtasan,<br/>Namatay at nabuhay si Kristo.<br/>',NULL,42518,3);
INSERT INTO stanza VALUES('T918','3','May kabigatan ka ba na iligtas,<br/>Kalul''wang nabuwis ay buhay Niya,<br/>Gumising baka di tupdin ang atas,<br/>Hiyas ng korona mo''y mawala.<br/>',NULL,42519,5);
INSERT INTO stanza VALUES('T918','4','Bawa''t lahi, wika, bansa, at tao,<br/>Ebanghelyo ng biyaya''y bigyan,<br/>Diyos ay nagkatawang-tao''t pinako,<br/>Nang tao ay muling-maisilang.<br/>',NULL,42520,7);
INSERT INTO stanza VALUES('T918','5','Huwag hadlangan ang anak mong maghain,<br/>Mag-alay ka pati ng iyong yaman,<br/>Ebanghelyo''y manaig, idalangin,<br/>Iyong punyagi''y gagantimpalaan.<br/>',NULL,42521,9);
INSERT INTO stanza VALUES('T918','6','Malapit na ang pagbalik ni Hesus,<br/>Iyong samantalahin ang paggawa,<br/>Wala sanang di makalapit sa Diyos,<br/>Dahil sa ating pagkapabaya.<br/>',NULL,42522,11);
INSERT INTO stanza VALUES('T921','1','Naligaw sagipin,<br/>Sawi''y ibigin,<br/>Agawin sa sala''t kamatayan;<br/>Salarin tangisan,<br/>Lugmok ahunin,<br/>Hesus magliligtas, iyong sabihin.<br/>',NULL,42523,1);
INSERT INTO stanza VALUES('T921','chorus','Naligaw sagipin,<br/>Sawi''y ibigin,<br/>Mahabaging Hesus,<br/>Magtutubos!<br/>',NULL,42524,2);
INSERT INTO stanza VALUES('T921','2','Kahit kinukutya,<br/>Naghihintay Siya,<br/>Tatanggapin sinumang magsisi,<br/>Taimtim, mayumi,<br/>Sumasamo Siya,<br/>Patatawarin ang maniwala.<br/>',NULL,42525,3);
INSERT INTO stanza VALUES('T921','3','Dinurog ng Diyablo<br/>Puso ng tao,<br/>Baón sa pighati nang matagal;<br/>Pusong mapagmahal<br/>Ang siyang nagbawi,<br/>Sirang kuwerdas aalalad muli.<br/>',NULL,42526,5);
INSERT INTO stanza VALUES('T921','4','Naligaw sagipin,<br/>Ating tungkulin,<br/>Panginoon ang magpapalakas,<br/>Makitid na landas<br/>Sila''y akitin,<br/>Ililigtas ni Hesus ngayon din.<br/>',NULL,42527,7);
INSERT INTO stanza VALUES('T922','1','Sa nawalang sanlibutan,<br/>Maghain ka ng Kristo,<br/>Sa buhay ay patunayan,<br/>Sa mga kalul''wang lito.<br/>',NULL,42528,1);
INSERT INTO stanza VALUES('T922','chorus','Sa nawalang sanlibutan,<br/>Maghain ka ng Kristo,<br/>Naipamuhay na Kristo,<br/>Ibahagi sa tao.<br/>',NULL,42529,2);
INSERT INTO stanza VALUES('T922','2','Ibahagi Kristong angkin<br/>Sa mga mahal mo rin,<br/>Pakinabang, tagumpay rin,<br/>Ay kanilang tamuhin.<br/>',NULL,42530,3);
INSERT INTO stanza VALUES('T922','3','Kristong iyong katamasahan,<br/>''Bahagi sa kaibigan,<br/>Bilang kanyang kapurihan,<br/>Lubos niyang kagalakan.<br/>',NULL,42531,5);
INSERT INTO stanza VALUES('T922','4','Kristong iyong buhay at lahat,<br/>''Bahagi mo sa tanan,<br/>Sa mga taong nasadlak,<br/>Dakila, mababa man.<br/>',NULL,42532,7);
INSERT INTO stanza VALUES('T925','1','Ang buhay na umaagos,<br/>Hatid ay ebanghelyo;<br/>Sa atin ngang patotoo,<br/>Maliligtas ang tao.<br/>',NULL,42533,1);
INSERT INTO stanza VALUES('T925','chorus','Buhay Mo ay paagusin,<br/>At mahayag sa amin;<br/>Sisidlang ito''y gamitin,<br/>Mga tao''y buhayin.<br/>',NULL,42534,2);
INSERT INTO stanza VALUES('T925','2','Pagpapatunay ng buhay,<br/>Tao ay mananalig;<br/>Pamamahagi ng buhay,<br/>Tao''y tanggap buhay rin.<br/>',NULL,42535,3);
INSERT INTO stanza VALUES('T925','3','Sa Panginoon umugnay,<br/>Mamunga bilang sanga;<br/>Kristo sa agos ng buhay,<br/>Bahaginan ang iba.<br/>',NULL,42536,5);
INSERT INTO stanza VALUES('T925','4','Nawa''y ating pamumuhay<br/>Naghahayag ng Kristo;<br/>Itanim binhi ng buhay,<br/>Hindi ang pagtuturo.<br/>',NULL,42537,7);
INSERT INTO stanza VALUES('T929','1','Sa daan ng buhay, mga pagod<br/>Marami at malungkot;<br/>Sa dilim dalhin mo ang liwanag,<br/>Malungkot bigyang-galak.<br/>',NULL,42538,1);
INSERT INTO stanza VALUES('T929','chorus','Gawin Mo akong ''sang pagpapala,<br/>Sa ''kin, Hesus ay makita;<br/>Panalangin ko, O Panginoon,<br/>Gawin akong pagpapala ngayon.<br/>',NULL,42539,2);
INSERT INTO stanza VALUES('T929','2','Saysayin si Kristo''t pag-ibig Niya,<br/>Siya''y nagpapatawad nga;<br/>Iba sa Kanya''y magtitiwala<br/>Kung iyong ipamuhay Siya.<br/>',NULL,42540,3);
INSERT INTO stanza VALUES('T929','3','Magbigay gaya ng binigyan ka,<br/>Magmahal ng tulad Niya;<br/>Tumulong sa walang tumutulong,<br/>Tuparin ang iyong misyon.<br/>',NULL,42541,5);
INSERT INTO stanza VALUES('T930','1','"Dapat bang lumisang hungkag,"<br/>Na sasalubungin Siya?<br/>Pag''lingkod ''di Siya mabigyan,<br/>Ni handog sa paa Niya?<br/>',NULL,42542,1);
INSERT INTO stanza VALUES('T930','chorus','"Dapat bang lumisang hungkag"<br/>Na babatiin ko Siya?<br/>Wala ni isang kalul''wa<br/>Upang salubungin Siya?<br/>',NULL,42543,2);
INSERT INTO stanza VALUES('T930','2','Di takot sa kamatayan,<br/>Dahil niligtas na Niya;<br/>Nguni''t ang lumisang hungkag<br/>Ang tangi kong pangamba.<br/>',NULL,42544,3);
INSERT INTO stanza VALUES('T930','3','Maraming taong nasayang<br/>Sa mga kasalanan,<br/>Ngayo''y ang Manunubos ko,<br/>Ang aking paglingkuran.<br/>',NULL,42545,5);
INSERT INTO stanza VALUES('T930','4','O mga banal, magtindig,<br/>Umagap sa gawain,<br/>Mga kalul''wa''y hanapin,<br/>Nang dilim di abutin.<br/>',NULL,42546,7);
INSERT INTO stanza VALUES('T933','1','Manliligtas sumasamo sa gloria<br/>Mapagmahal Siya, konti man kaibigan;<br/>At magiliw sa akin nagbabantay Siya,<br/>Maging Manliligtas mo rin nawa Siya.<br/>',NULL,42547,1);
INSERT INTO stanza VALUES('T933','chorus','Ako''y nagdarasal,<br/>Ako''y nagdarasal,<br/>Ako''y nagdarasal,<br/>Para nga sa iyo.<br/>',NULL,42548,2);
INSERT INTO stanza VALUES('T933','2','May Ama ako: sa aki''y nagbigay<br/>Pag-asang walang hanggan na siyang tunay;<br/>Sa kaharian ng langit, tatawagin,<br/>Nawa''y payag Siyang ika''y aking dalhin!<br/>',NULL,42549,3);
INSERT INTO stanza VALUES('T933','3','Mapayapang sintahimik ng ilog,<br/>Pangmundong kaibigan di maarok;<br/>Manliligtas ko, May Akda, Tagabigay,<br/>At nabatid kong sa iyo ibinigay!<br/>',NULL,42550,5);
INSERT INTO stanza VALUES('T936','1','Sa tubig ako''y nalibing,<br/>Namatay kasama ni Kristo;<br/>Mundo''y di makahahabol,<br/>Lakas nito''y natapos dito.<br/>Nabuhay kay Kristo rin,<br/>Sa Kanya ako''y namumuhay;<br/>Ngayon ''Spiritu''y nagtustos,<br/>Buhay, lakas sa akin ibinigay.<br/>',NULL,42551,1);
INSERT INTO stanza VALUES('T937','1','Inihayag sa bautismo,<br/>Namatay kai-sa Ka.<br/>Sa awa at biyaya Mo;<br/>Makitang halaga.<br/>',NULL,42552,1);
INSERT INTO stanza VALUES('T937','2','Sa kamatayan kaisa,<br/>Kasamang nalibing,<br/>Sa kasalanan patay na,<br/>At pinalaya rin.<br/>',NULL,42553,2);
INSERT INTO stanza VALUES('T937','3','Sa kamatayan kaisa—<br/>Kasamang nalibing,<br/>Sa mundo namaalam na,<br/>At pagka-alipin.<br/>',NULL,42554,3);
INSERT INTO stanza VALUES('T937','4','Tagumpay sa kamatayan<br/>At muling-nabuhay,<br/>Ngayon ay may kabanalan<br/>Sa Iyo''y bagong buhay.<br/>',NULL,42555,4);
INSERT INTO stanza VALUES('T937','5','Binautismo sa Iyong ngalan,<br/>Di na sa sarili;<br/>Iyong hakbang ay laging sundan,<br/>Kaisa Mo''ng lagi.<br/>',NULL,42556,5);
INSERT INTO stanza VALUES('T938','1','Namatay na! Nalibing pa!<br/>Mula ngayo''y tapos na!<br/>Namatay na! Nalibing pa!<br/>Mula ngayo''y tapos na!<br/>',NULL,42557,1);
INSERT INTO stanza VALUES('T938','2','Di na ako! Di na ako!<br/>Kristo''y ipatotoo!<br/>Di na ako! Di na ako!<br/>Kristo''y ipatotoo!<br/>',NULL,42558,2);
INSERT INTO stanza VALUES('T939','1','Araw ng pagkabuhay,<br/>Maligayang araw,<br/>Tatak ng katubusan,<br/>Kay ganda''t malinaw:<br/>Mataas at mababa,<br/>Nanikluhod sa Iyo;<br/>O "Banal, banal, banal"<br/>Sa Iyo na Tres-uno.<br/>',NULL,42559,1);
INSERT INTO stanza VALUES('T939','2','Sa paglikhang ginawa,<br/>Liwanag nanguna;<br/>Sa kaligtasan naman,<br/>Ibinangon nga Siya;<br/>Espiritu''y sinugo,<br/>Poong mapagwagi;<br/>Liwanag napatindi<br/>Ika''y nal''walhati.<br/>',NULL,42560,2);
INSERT INTO stanza VALUES('T939','3','Ang mannang makalangit<br/>Sa Hentil sumapit!<br/>Sa banal nga na pulong,<br/>Trumpeta''y tumunog,<br/>Ebanghelyo''y sumilay,<br/>Sinag na dalisay;<br/>Dumaloy tubig-buhay,<br/>Kalul''wa''y ginhawa.<br/>',NULL,42561,3);
INSERT INTO stanza VALUES('T939','4','Bagong biyaya''y tamo,<br/>Mas mabuting araw;<br/>Sa taong pinagpala,<br/>Pahinga''y natamo.<br/>Papuri sa ''Spiritu,<br/>Sa Ama at Anak;<br/>Ekklesia''y pumupuri,<br/>Sa Diyos Tatlo-isa.<br/>',NULL,42562,4);
INSERT INTO stanza VALUES('T940','1','Sanlinggo''y lumipas na,<br/>Binigyan ng tulong Niya;<br/>Hanapin pagpapala<br/>Sa araw na gawa Niya:<br/>Araw na mas mabuti,<br/>Sagisag ng pahinga.<br/>[Araw na mas mabuti,<br/>Sagisag ng pahinga.]<br/>',NULL,42563,1);
INSERT INTO stanza VALUES('T940','2','Dasal kapatawaran,<br/>Sa mahal Niyang pangalan;<br/>Pinagkasundo na nga,<br/>Inalis aming sala:<br/>Lumaya sa abala,<br/>Sa Iyo ay may pahinga.<br/>[Lumaya sa abala,<br/>Sa Iyo ay may pahinga.]<br/>',NULL,42564,2);
INSERT INTO stanza VALUES('T940','3','Dito ay purihin Ka,<br/>Ngalan Mo at presensya,<br/>Sa Iyong bahay nadama,<br/>Gloria Mo ay nakita:<br/>Bigyan kami ng tikim<br/>Ng walang hanggang piging.<br/>[Bigyan kami ng tikim,<br/>Ng walang hanggang piging.]<br/>',NULL,42565,3);
INSERT INTO stanza VALUES('T940','4','Galak ng ebanghelyo,<br/>Sa maysala''y magtamo;<br/>Biyaya sumagana,<br/>Sa daing may ginhawa:<br/>Patotoo''y kaarawan,<br/>Hanggang sa magpangita.<br/>[Patotoo''y kaarawan,<br/>Hanggang sa magpangita.]<br/><!--(Ulitin ang huling dalawang linya ng bawa''t saknong)--><br/>',NULL,42566,4);
INSERT INTO stanza VALUES('T941','1','Ang kaharian ng Diyos<br/>Ay pamumuno Niya,<br/>Namamalagi gloria,<br/>Kaayusan dala.<br/>Sariling awtoridad,<br/>Ganap pinatupad;<br/>Sa Kanyang kaharian,<br/>Magpakailan pa man.<br/>',NULL,42567,1);
INSERT INTO stanza VALUES('T941','2','Sentro ng kaharian,<br/>Ang Kanyang luklukan,<br/>Diyos lamang dapat sundin,<br/>Sa Kanyang layunin.<br/>Hari sa kaharian<br/>Kanya na ang tanan<br/>Sadya ang pamunuan,<br/>Kanyang hinawakan.<br/>',NULL,42568,2);
INSERT INTO stanza VALUES('T941','3','Sa paghahari Ni-ya<br/>Layon Niya ginawa,<br/>Sa pamamahala Niya<br/>Natupad nais Niya.<br/>Tangi sa kaharian,<br/>Pagpapala''y tanto,<br/>Mula sa Kanyang trono,<br/>Daloy buhay mismo.<br/>',NULL,42569,3);
INSERT INTO stanza VALUES('T941','4','Magpasakop sa Kanya<br/>Lahat buti''y kamtan;<br/>Magrebelde sa Kanya,<br/>Ugat kasalanan.<br/>Layon ng sama''t diyablo<br/>Ibagsak ang trono;<br/>Ating layon at lugod,<br/>Sa Diyos magpasakop.<br/>',NULL,42570,4);
INSERT INTO stanza VALUES('T941','5','Sa kaharian ng Diyos,<br/>Kristo''y hayag lubos;<br/>Sa buhay Siya''y naghari<br/>Ama''y mal''walhati.<br/>Nang Diyos ang namahala,<br/>Lahat pinagpala;<br/>Nang Kristo''y namahala,<br/>Gloria ng Diyos hayag.<br/>',NULL,42571,5);
INSERT INTO stanza VALUES('T941','6','Pag panahon puspos na,<br/>Kristong Diyos ulo na;<br/>Tanan Siya''y kikilanlin,<br/>Pamuno''y tanggapin.<br/>Magloriang pamahala,<br/>Tikim ng Ekklesia,<br/>Kung pasakop sarili<br/>Kaharia''y dagli.<br/>',NULL,42572,6);
INSERT INTO stanza VALUES('T942','1','Kaharian ng Diyos ngayon<br/>Sa ''ting loob namahala;<br/>Ipamuhay natin Kristo,<br/>Bilang Hari, Panginoon.<br/>',NULL,42573,1);
INSERT INTO stanza VALUES('T942','2','Buhay Niyang may awtoridad,<br/>Puso natin iluklok Siya,<br/>Nang ating salita''t gawa,<br/>Ating loob iayos Niya.<br/>',NULL,42574,2);
INSERT INTO stanza VALUES('T942','3','Panginoon itinatag,<br/>Sa ''ting puso kaharian;<br/>Paghahari''y karapatan,<br/>Layon ng Diyos paghandaan.<br/>',NULL,42575,3);
INSERT INTO stanza VALUES('T942','4','Kanyang paghari sa puso,<br/>Panustos natin buhay Niya.<br/>Kung Hari''t Poon Siya sa ''tin,<br/>Yaman Niya''y kasiyahan din.<br/>',NULL,42576,4);
INSERT INTO stanza VALUES('T942','5','Sa loob Siyang namumuno,<br/>Kapuspusan patotoo;<br/>Panloob na pamumuno,<br/>Katawan maitatayo.<br/>',NULL,42577,5);
INSERT INTO stanza VALUES('T942','6','Pamumunong makalangit<br/>Pinamumuhay nga natin;<br/>Kanyang pagkahari''y sundin<br/>Ibigay kahayagan din.<br/>',NULL,42578,6);
INSERT INTO stanza VALUES('T942','7','Namumuhay makalangit,<br/>Taglay lakas makalangit,<br/>Sa liwanag magsilaban<br/>Nang mahayag Kaharian.<br/>',NULL,42579,7);
INSERT INTO stanza VALUES('T944','1','Esensya ng Kaharian,<br/>Buhay na nagpapasakop<br/>Kalikasan ay dibino<br/>Maranasan ganap Kristo.<br/>',NULL,42580,1);
INSERT INTO stanza VALUES('T944','2','Gayong buhay Kaharian<br/>''Spiritu''y may karukhaan,<br/>Puso''y nagsisi''t maamo,<br/>Diyos Mismo nais matamo.<br/>',NULL,42581,2);
INSERT INTO stanza VALUES('T944','3','Tayong mga anak ng Diyos<br/>Kapayapaan ginawa,<br/>Magbata para kat''wiran;<br/>Tamo''y higit kagalakan.<br/>',NULL,42582,3);
INSERT INTO stanza VALUES('T944','4','Asin kitlin kasamaan,<br/>Ilaw sinag sa karimlan;<br/>Puso''t pagkilos ay wasto<br/>May pag-ibig na totoo!<br/>',NULL,42583,4);
INSERT INTO stanza VALUES('T944','5','Di sarili l''walhatiin,<br/>Kaharian idalangin;<br/>Sa Diyos lubos umaasa,<br/>Kaharian inuuna.<br/>',NULL,42584,5);
INSERT INTO stanza VALUES('T944','6','Sa sarili''y mahigpit nga,<br/>Sa iba ay may biyaya;<br/>Gawin ang pasya ng Ama,<br/>Ayunan Kanyang salita.<br/>',NULL,42585,6);
INSERT INTO stanza VALUES('T944','7','Satanas di-bigyang-puwang,<br/>Ni mundo, sarili''t sala;<br/>Pamumunong langit sundin<br/>Awtoridad ng Diyos kamtin.<br/>',NULL,42586,7);
INSERT INTO stanza VALUES('T944','8','Buhay nagpasukong lubos<br/>Nang dahil sa lakas ng Diyos;<br/>Pinadali pagbalik Niya,<br/>Kaharia''y mapakita.<br/>',NULL,42587,8);
INSERT INTO stanza VALUES('T945','1','Ang Anak ng Diyos nagpunla<br/>Binhing buhay sa tao nga,<br/>Nang Kaharian lumago<br/>At matupad Kanyang plano.<br/>',NULL,42588,1);
INSERT INTO stanza VALUES('T945','2','Isang butil ng trigo Siya<br/>Marami Kanyang binunga<br/>Sa anak ng Kaharian<br/>Diyos may kapamahalaan.<br/>',NULL,42589,2);
INSERT INTO stanza VALUES('T945','3','Nguni''t naghasik ang Diyablo<br/>Sa gitna ng mga trigo<br/>Mga mapanirang damo.<br/>Mga anak ay nilito.<br/>',NULL,42590,3);
INSERT INTO stanza VALUES('T945','4','Tusong gawain ng Diyablo<br/>Ang damo''t trigo''y hinalo,<br/>Ang anyo ng Kaharian<br/>Di-normal, may kalakihan.<br/>',NULL,42591,4);
INSERT INTO stanza VALUES('T945','5','Kaharian tulad sana<br/>Maliit gulay mustasa<br/>Nguni''t naging isang "puno,"<br/>Sistemang labis ang lago.<br/>',NULL,42592,5);
INSERT INTO stanza VALUES('T945','6','Sa halip na pagkain na,<br/>Mga "ibon" ang tumira;<br/>Lugar ng masamang tao<br/>At masasamang ''spiritu.<br/>',NULL,42593,6);
INSERT INTO stanza VALUES('T945','7','Pangmundong relihiyon nga<br/>Labas na anyo nakita<br/>Bagay masama''t pagano<br/>Lebadurang naihalo.<br/>',NULL,42594,7);
INSERT INTO stanza VALUES('T945','8','Sistema ngang makamundo,<br/>Anyong panlabas nabago;<br/>Pagsipsip bagay masama,<br/>Tiwaling panloob dagsa.<br/>',NULL,42595,8);
INSERT INTO stanza VALUES('T945','9','Nguni''t Diyos hanap ay kubli<br/>"Perlas" at "yaman sa bukid";<br/>Kanya tayong transpormahin<br/>Perlas, yaman Kanyang kamtin.<br/>',NULL,42596,9);
INSERT INTO stanza VALUES('T945','10','Nakubli sa Kristiyanismo<br/>Maging sa harapang anyo<br/>Nguni''t sa realidad niya,<br/>Kay Kristo''t sa Diyos kagaya.<br/>',NULL,42597,10);
INSERT INTO stanza VALUES('T945','11','Ihiwalay, iligtas Mo,<br/>Kami sa "damo" at "puno"<br/>"Lebadura" alisin na<br/>Sa Iyo mapadalisay nga.<br/>',NULL,42598,11);
INSERT INTO stanza VALUES('T945','12','Transpormahin ng buhay Mo<br/>Maging mahalagang bato,<br/>Maitayo Mo tahanan<br/>Realidad Kaharian.<br/>',NULL,42599,12);
INSERT INTO stanza VALUES('T946','1','Masdan gloria! Masdan ganda!<br/>Kaharian hayag na!<br/>At ang mal''walhating Hari,<br/>Takda ng Diyos at pili.<br/>Dumating minsan sa laman,<br/>Dinusta, kinam''hian<br/>Muli darating sa gloria,<br/>Kaharian tupdin na.<br/>',NULL,42600,1);
INSERT INTO stanza VALUES('T946','2','Tatanggapin Kaharian<br/>Sa Diyos na Sinauna<br/>Ang Kaharian kasama<br/>Maliwanag may gloria;<br/>"Batong" dudurog sa bansa<br/>Tanging bansa''y mawala<br/>Magiging "bundok dakila"<br/>Kaharian makita.<br/>',NULL,42601,2);
INSERT INTO stanza VALUES('T946','3','O mga bansa at lupa<br/>Inari ni Kristo na;<br/>Lupa may kapayapaan<br/>Sa Kanyang kaharian.<br/>Wala nang digma at muhi<br/>Sa bawa''t bansa''t lahi<br/>Kundi kaalaman ng Diyos<br/>Sa kanila''y pupuspos.<br/>',NULL,42602,3);
INSERT INTO stanza VALUES('T946','4','Mandaraig na Kristiyano,<br/>Kasamang hari Kristo.<br/>Saserdote ng Diyos naman<br/>Naligtas na Israel<br/>Mga bansa''y mamamayan<br/>Kanilang pagharian<br/>Panumbalik na maringal,<br/>Sa sangnilikha''y tanghal.<br/>',NULL,42603,4);
INSERT INTO stanza VALUES('T946','5','Satanas matalian na,<br/>Ang lupa malaya na;<br/>Si Kristo ay maghahari<br/>Pagpapala''y darami<br/>Kay Kristo pasasakop nga,<br/>Sa kapangyarihan Niya<br/>Ulo''t Sentrong maringal Siya,<br/>Layon ng Diyos tupad Niya.<br/>',NULL,42604,5);
INSERT INTO stanza VALUES('T947','1','Kaharian ngayon ay pagsasanay,<br/>Sa hinaharap, gantimpala ay taglay;<br/>Karunungan ng Diyos ang sanayin tayo,<br/>Upang Siya''y mahayag at matupad plano.<br/>',NULL,42605,1);
INSERT INTO stanza VALUES('T947','2','Bilang anak ng Diyos, tayo ay laan,<br/>Magharing sama-sama sa kaharian;<br/>Sa paghari kailangan nating masanay,<br/>Upang Siya''y maghari sa lahat ng bagay.<br/>',NULL,42606,2);
INSERT INTO stanza VALUES('T947','3','Dapat tayong magpasakop sa Kanya,<br/>Hayaang Siya ang mamuno at magpasya;<br/>Sa awtoridad Niya''y makakabahagi,<br/>Sa mga bansa, kasama Niyang maghari.<br/>',NULL,42607,3);
INSERT INTO stanza VALUES('T947','4','Matuwid at mahigpit sa sarili,<br/>Maamo sa kapwa, sa Diyos galak lagi;<br/>Sa Kahariang realidad maglagi,<br/>Upang sa kahayaga''y handang maghari.<br/>',NULL,42608,4);
INSERT INTO stanza VALUES('T947','5','Pagbalik ni Kristo upang maghari,<br/>Kasama Niya sa trono ating bahagi;<br/>Dahil sa atin kat''wiran Niya''y mahayag,<br/>Dibinong karunungan Niya''y maitanyag.<br/>',NULL,42609,5);
INSERT INTO stanza VALUES('T947','6','Apostol nagtumulin sa hangganan,<br/>Nalugi upang matamo Kaharian;<br/>Matapat kay Hesus, tayo''y inatasan,<br/>Nang sa Kaharian magantimpalaan.<br/>',NULL,42610,6);
INSERT INTO stanza VALUES('T947','7','Sa Kaharian, kami''y biyayaan,<br/>Masanay upang gantimpala''y makamtan,<br/>Tuparin realidad ng Kaharian,<br/>Gantimpala''y mismong kanyang kahayagan.<br/>',NULL,42611,7);
INSERT INTO stanza VALUES('T948','1','Hiwagang kubli''y nahayag sa akin,<br/>Si Kristong realidad ng Diyos.<br/>Diyos nagkatawang-tao, buhay ko rin,<br/>At Siya''y aking l''walhating lubos.<br/>',NULL,42612,1);
INSERT INTO stanza VALUES('T948','chorus','Mal''walhati, Kristo''y pag-asa!<br/>Mal''walhati, sa loob ko Siya!<br/>Ngayon sa loob ko''y isang hiwaga!<br/>Sa hinaharap l''walhati pa.<br/>',NULL,42613,2);
INSERT INTO stanza VALUES('T948','2','Sa espiritu ako''y isinilang,<br/>Binabago rin sa kalul''wa.<br/>Katawan ko''y makatulad sa Kanya,<br/>Ganap nang makakawangis Siya.<br/>',NULL,42614,3);
INSERT INTO stanza VALUES('T948','3','Kaisa sa buhay at kalikasan,<br/>Sa l''walhati Niya mapaayon,<br/>Kaisa ko Siya, aking kaluguran,<br/>Wangis Niya''y ganap na paayón.<br/>',NULL,42615,5);
INSERT INTO stanza VALUES('T949','1','Pag-asa ng kal''walhatian ay si Kristo,<br/>Kanyang muling-''sinilang ako''t pinuspusan;<br/>Pagdating Niya katawa''y babaguhing-anyo,<br/>Tulad ng mal''walhati Niyang katawan!<br/>',NULL,42616,1);
INSERT INTO stanza VALUES('T949','chorus','Siya''y darating, ako''y lul''walhatiin!<br/>Katawan ko''y babaguhing-anyo katulad Niya.<br/>Siya''y darating, pagtubos gagawin!<br/>Tayo''y lul''walhatiin ng Pag-asa ng gloria.<br/>',NULL,42617,2);
INSERT INTO stanza VALUES('T949','2','Pag-asa ng kal''walhatian ay si Kristo;<br/>Hiwaga ng Diyos na aking natatamasa;<br/>Dumating upang ako''y sa Diyos maihalo,<br/>Pati mabahagi ko l''walhati Niya.<br/>',NULL,42618,3);
INSERT INTO stanza VALUES('T949','3','Si Kristo ang pag-asa ng kal''walhatian,<br/>Katawan ko''y tutubusin sa kamatayan,<br/>Gagawin Niyang mal''walhati aking katawan,<br/>Pagtatagumpayan ang kamatayan.<br/>',NULL,42619,5);
INSERT INTO stanza VALUES('T949','4','Si Kristo ang pag-asa ng kal''walhatian,<br/>Kasaysayan ko''t karanasan ang buhay Niya;<br/>Dadalhin ako sa l''walhating kalayaan,<br/>Upang magpakailanma''y kaisa Niya.<br/>',NULL,42620,7);
INSERT INTO stanza VALUES('T956','1','Panginoon malapit na darating,<br/>Paglapit maririnig natin.<br/>Maging alerto''t mapagbantay tayo<br/>Nang magalak Niya ating puso.<br/>',NULL,42621,1);
INSERT INTO stanza VALUES('T956','chorus','Mal''walhati! Kristo''y darating!<br/>Kasama Niya maghahari rin!<br/>Katawang mal''walhati Siya''y kasama,<br/>Papuri''t aawit masaya.<br/>',NULL,42622,2);
INSERT INTO stanza VALUES('T956','2','Gising malapit nang darating Si-ya;<br/>Lilitaw Tala sa Umaga.<br/>Huwag sasama sa daloy ng panahon,<br/>Nang sa pagsubok maiahon.<br/>',NULL,42623,3);
INSERT INTO stanza VALUES('T956','chorus','Mal''walhati! Kristo''y darating!<br/>Kasama Niya maghahari rin!<br/>Katawang mal''walhati Siya''y kasama,<br/>Papuri''t aawit masaya.<br/>',NULL,42624,4);
INSERT INTO stanza VALUES('T956','3','Malapit nang darating Panginoon;<br/>Sa Kanya umibig may putong.<br/>Paglingkuran Panginoon, ibigin,<br/>Kanyang kabigatan pasanin.<br/>',NULL,42625,5);
INSERT INTO stanza VALUES('T956','chorus','Mal''walhati! Kristo''y darating!<br/>Kasama Niya maghahari rin!<br/>Katawang mal''walhati Siya''y kasama,<br/>Papuri''t aawit masaya.<br/>',NULL,42626,6);
INSERT INTO stanza VALUES('T956','4','Siya ay darating na at maghahari;<br/>Mundo''y supil, Satanas tali.<br/>Makipagbaka''t kaaway gapiin,<br/>Sa trono Niya tayo''y tanggapin.<br/>',NULL,42627,7);
INSERT INTO stanza VALUES('T956','chorus','Mal''walhati! Kristo''y darating!<br/>Kasama Niya maghahari rin!<br/>Katawang mal''walhati Siya''y kasama,<br/>Papuri''t aawit masaya.<br/>',NULL,42628,8);
INSERT INTO stanza VALUES('T958','1','Mula nang naghiwalay sa Betania,<br/>Nahungkag puso kong tuluy-tuloy;<br/>Paano ko tutugtugin ang alpa?<br/>Kung wala Ka awit di-tamasa.<br/>Sa gabi nag-iisang nagpupuyat.<br/>Namanhid sa pighati o galak,<br/>Nagunita pangako mong babalik<br/>Bakit di ka pa nagpapakita? Bakit?<br/>',NULL,42629,1);
INSERT INTO stanza VALUES('T958','2','Diwa ko''y pinukaw ng Iyong sabsaban<br/>Na ako ay wala ring tahanan<br/>Krus pawi sa kalul''wa mundong saya<br/>Hangad Ikaw, layong walang hanggan.<br/>Nawalan ng galak nang lumisan Ka,<br/>Tamis ng awit ko ay nawala.<br/>Ang kahungkagan aking damang-dama<br/>Nawa bumalik Ka na''t huwag mag-antala.<br/>',NULL,42630,2);
INSERT INTO stanza VALUES('T958','3','Bagama''t batid ko nga Iyong presensya,<br/>Subali''t sa puso ko''y kulang pa.<br/>May pagliliwanag, pagtutustos nga.<br/>Di makasiya: nais bumalik Ka.<br/>Kahit kapayapaan at galak Ka,<br/>Dama''y lungkot at buntung-hininga<br/>Kung makuntento tahimik na daing<br/>Makita Kang mukhaan ang aking hiling.<br/>',NULL,42631,3);
INSERT INTO stanza VALUES('T958','4','Sa nawalay sa sarili Niyang bayan<br/>Di ba''y hangad muling magbatian?<br/>Mga kaanak di malilimutan<br/>Sabik din maging magkasintahan?<br/>Galak ng pagbalik Mo di mahambing<br/>Sa panlupang layaw at pag-ibig<br/>Kung hindi ko mamasdan ang Iyong mukha<br/>Magbuntung-hininga hanggang dumating Ka.<br/>',NULL,42632,4);
INSERT INTO stanza VALUES('T958','5','Makalimutan kaya Iyong pangako<br/>Ika''y babalik ako''y kunin Mo?<br/>Subali''t araw at taon naghintay,<br/>Pagbabalik Mo ''di pa masilay!<br/>Iyong gunitain ang paghihintay ko<br/>Yapak Mo''y nagluluat palayo<br/>Gaano pa tatagal paghihintay,<br/>Hanggang makita mal''walhating pagsilang?<br/>',NULL,42633,5);
INSERT INTO stanza VALUES('T958','6','O henerasyon kada henerasyon,<br/>Banal Mo''y dumating at yumaon,<br/>Pangako Mo maisakatuparan,<br/>Anong tagal na kapanahunan!<br/>Bakit hindi namin maulinigan<br/>Yapak Mo mula sa kalangitan?<br/>Dapat bang patagalin ''ming paghintay<br/>Bago ihayag gloria''y walang kapantay?<br/>',NULL,42634,6);
INSERT INTO stanza VALUES('T958','7','Ginunita Mo maraming taon na<br/>Ako''y naghintay — ''di nag-iisa;<br/>Mga banal sa mga henerasyon<br/>Sumasamo sa pagbalik ngayon.<br/>Mabilis Mong pagbalik tugunan Mo,<br/>Di mabilang na luha''t pagsamo.<br/>O alingawngaw ng kapanahunan,<br/>Bumalik Ka na aming hiyaw pakinggan!<br/>',NULL,42635,7);
INSERT INTO stanza VALUES('T960','1','Hari ko''y babalik muli,<br/>Langit pinuspos Niya;<br/>Sangnilikha''y mababawi,<br/>Sa kaligtasan Niya.<br/>Ang yapak Niya''y narinig ko<br/>Sa gitna ng ulap;<br/>Kanyang mal''walhating anyo<br/>Sa langit kumislap.<br/>',NULL,42636,1);
INSERT INTO stanza VALUES('T960','2','Sabik ako sa "parousia,"<br/>Di ako pabaya;<br/>Hinihintay pagbalik Niya,<br/>Anong pagpapala.<br/>Maliban sa pagdating Niya,<br/>At Siya''y makasama,<br/>Wala nang ibang ligaya,<br/>Na magpapasaya.<br/>',NULL,42637,2);
INSERT INTO stanza VALUES('T960','3','Mata ko''y lagi Siyang tingnan,<br/>Puso ko''y sa langit,<br/>Paksa ng labi ko naman<br/>Ang Kanyang pagsapit.<br/>Malapit nang pumarito,<br/>Nang dahil sa akin;<br/>Tiyak ang Kanyang pangako,<br/>Hindi sinungaling.<br/>',NULL,42638,3);
INSERT INTO stanza VALUES('T960','4','Hesus, banal Mong Salita,<br/>''Di mapagdudahan;<br/>Araw-araw Iyong Salita,<br/>Aking kalakasan.<br/>Nawa''y maagang dumating,<br/>Kaaway puksain;<br/>Pangako''y agad tuparin,<br/>At kami''y Iyong kunin.<br/>',NULL,42639,4);
INSERT INTO stanza VALUES('T960','5','Bisig Mo ay kanlungan ko,<br/>Tagapagligtas ko!<br/>Sila''y nagtiwala sa Iyo,<br/>Ama, ingatan Mo.<br/>Tupa''t pastol kasing-inam,<br/>Ulo''t katawan pa,<br/>Hindi maagaw ninuman<br/>Sa kamay ng Ama.<br/>',NULL,42640,5);
INSERT INTO stanza VALUES('T960','6','''Sanlibong kamay at mata,<br/>Hindi makahadlang;<br/>Mga tinik ay tulong nga<br/>Nang pala''y makamtan.<br/>Puso, espiritu, gising!<br/>Mundo''y pabayaan,<br/>Panginoon ay darating,<br/>Ako''y puputungan.<br/>',NULL,42641,6);
INSERT INTO stanza VALUES('T960','7','Araw Ka ng kagalingan,<br/>Nais ko ang sinag;<br/>Haring mat''wid, mal''walhati,<br/>Kami''y nagpupuri.<br/>Umakyat Ka sa luklukan,<br/>Nawa''y ipakita,<br/>Mukha Mo at kaharian,<br/>Lubos na biyaya.<br/>',NULL,42642,7);
INSERT INTO stanza VALUES('T960','8','Hari ang katotohanan,<br/>Kalayaa''y reyna;<br/>Nguni''t ang kabulaanan<br/>Sa mundo''y nanguna.<br/>Halina, Katotohanan,<br/>Dalhin ang liwanag;<br/>Lipulin Mo ang kalaban,<br/>Kunin mga anak.<br/>',NULL,42643,8);
INSERT INTO stanza VALUES('T962','1','Kailan Ka pa babalik, Mahal<br/>Naghintay akong matagal,<br/>Nais kong makita Iyong mukha.<br/>Pagmasdan Kang puno ng b''yaya.<br/>Balik na, huwag mag-antala!<br/>Aaliwin ako kailan pa nga;<br/>Balik na, huwag mag-antala!<br/>Nasa Kitang makasama.<br/>',NULL,42644,1);
INSERT INTO stanza VALUES('T965','beginning-note','(Ang pag-awit sa Tagalog ay walang "slur")<br/>',NULL,42645,1);
INSERT INTO stanza VALUES('T965','1','''Pag ang Panginoon ay dumating,<br/>Makalalaya na sa hinaing,<br/>Kasama ng banal sundan ko Siya,<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Kasama ng banal sundan ko Siya,<br/>Purihin Siya!<br/>',NULL,42646,2);
INSERT INTO stanza VALUES('T965','2','''Pag akin Siyang nakitang mukhaan,<br/>Makasama Siya magpakailanman,<br/>Biyaya''y awit ko''t kagalakan,<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Biyaya''y awit ko''t kagalakan,<br/>Purihin Siya!<br/>',NULL,42647,3);
INSERT INTO stanza VALUES('T965','3','''Pag sa luklukan Siya''y nakaharap,<br/>Mapaparam mga paghihirap,<br/>Galak ng tagumpay matatanggap,<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Galak ng tagumpay matatanggap,<br/>Purihin Siya!<br/>',NULL,42648,4);
INSERT INTO stanza VALUES('T965','4','Doon ako''y magpapatotoo,<br/>Walang katulad buhay ni Kristo,<br/>Anong l''walhati ng pag-akyat ko!<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Anong l''walhati ng pag-akyat ko.<br/>Purihin Siya!<br/>',NULL,42649,5);
INSERT INTO stanza VALUES('T965','5','Sa Panginoon tayo''y magkubli,<br/>Laging kaisa Niya di mahati,<br/>Upang Siya''y masiyahang mabuti,<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Upang Siya''y masiyahang mabuti.<br/>Purihin Siya!<br/>',NULL,42650,6);
INSERT INTO stanza VALUES('T965','6','Aking Hari, Ika''y pumarito,<br/>Kami''y kunin ayon sa pangako,<br/>Mandaraig mabigyan ng premyo,<br/>Purihin Siya!<br/>Purihin Siya! Purihin Siya!<br/>Mandaraig mabigyan ng premyo.<br/>Purihin Siya!<br/>',NULL,42651,7);
INSERT INTO stanza VALUES('T966','1','Pag-asa''y Kristo natin babalik!<br/>Tayo''y aakyat may kagalakan;<br/>Mababagong-anyo, mawawangis,<br/>L''walhati Siya ''king katamasahan!<br/>',NULL,42652,1);
INSERT INTO stanza VALUES('T966','chorus','O pag-asang mal''walhati!<br/>Si Kristo ay magbabalik!<br/>Papaitaas nang may l''walhati,<br/>Pag-asa''y Kristo natin babalik!<br/>',NULL,42653,2);
INSERT INTO stanza VALUES('T966','2','Pag-asa''y Kristo natin babalik!<br/>Ang lumang nilikha''y papawiin,<br/>May kalayaan, wala nang hapis,<br/>Kaligtasan ay tatamasahin.<br/>',NULL,42654,3);
INSERT INTO stanza VALUES('T966','3','Pag-asa''y Kristo natin babalik!<br/>Kasama Niya maghahari tayo;<br/>Bilang saserdote maglilingkod,<br/>Kaligtasan ganap matatamo.<br/>',NULL,42655,5);
INSERT INTO stanza VALUES('T966','4','Pag-asa''y Kristo natin babalik!<br/>Tumatakbo patungong hanggahan;<br/>Naglilingkod habang nagbabantay,<br/>Maging marapat sa Kaharian.<br/>',NULL,42656,7);
INSERT INTO stanza VALUES('T970','1','Sa mal''walhating pahayag<br/>Ng mga anak ng Diyos<br/>Naghihintay sangnilikha,<br/>Upang lahat lumaya.<br/>',NULL,42657,1);
INSERT INTO stanza VALUES('T970','2','Sangnilikha humihibik,<br/>Kahungkagan sumiil;<br/>Umaasa mapalaya,<br/>Mula sa pagkasira.<br/>',NULL,42658,2);
INSERT INTO stanza VALUES('T970','3','Maging tayo''y humihibik,<br/>Pagkagulang marating;<br/>Sa pagka-anak lumago,<br/>Mapawangis kay Kristo.<br/>',NULL,42659,3);
INSERT INTO stanza VALUES('T970','4','Humihibik Espiritu,<br/>Nang mapawangis tayo;<br/>Lahat-lahat gumagawa,<br/>Nang tayo''y matransporma.<br/>',NULL,42660,4);
INSERT INTO stanza VALUES('T970','5','Sa gloria tayo''y dadalhin,<br/>Tayo''y lu''walhatiin;<br/>Lubos na mababaran Niya,<br/>Buong mapabanal nga.<br/>',NULL,42661,5);
INSERT INTO stanza VALUES('T970','6','Sangnilikha''y mapalaya,<br/>Nitong laya ng gloria;<br/>Magtabi leopardo''t kambing<br/>Baka''t oso kakain.<br/>',NULL,42662,6);
INSERT INTO stanza VALUES('T970','7','Lumagong tagapagmana,<br/>Pagka-anak minana;<br/>Bilang kapatid sa gloria,<br/>Hayag nati''y gloria Niya.<br/>',NULL,42663,7);
INSERT INTO stanza VALUES('T971','1','Ang layunin ng Diyos — kai-sa sa tao,<br/>Sisidlan ang tao, malamnan ng Diyos;<br/>Siya ang buhay upang tao''y mapuno,<br/>Tao''y kaisa Niya, ihayag ang Diyos.<br/>',NULL,42664,1);
INSERT INTO stanza VALUES('T971','2','Ayon sa wangis Niya, tao''y nilikha,<br/>Pinaging-dapat tao sa plano Niya;<br/>Bilang puno ng buhay, tanggapin Siya,<br/>Tao''y kapuspusan at asawa Niya.<br/>',NULL,42665,2);
INSERT INTO stanza VALUES('T971','3','Sa agos ng buhay, tao''y baguhin,<br/>Mamahaling materyal, kawangis Niya.<br/>Itatayo bilang kasintahan din,<br/>At bilang tahanan, matamasa Niya.<br/>',NULL,42666,3);
INSERT INTO stanza VALUES('T971','4','Bagong Herusalem, bayang marangal,<br/>Diyos nilalaman tao''y kahayagan,<br/>Diyos ay nakihalo sa mga banal;<br/>Kaisa sa l''walhating walang-hanggan.<br/>',NULL,42667,4);
INSERT INTO stanza VALUES('T971','5','Diyos ang sentro at hari sa luklukan,<br/>Lahat sa buhay Niya''y nagkakaisa;<br/>Mamuhay sa ilaw, kal''walhatian,<br/>Banal nagkaisa, magkakatugma.<br/>',NULL,42668,5);
INSERT INTO stanza VALUES('T971','6','Siya ay tinapay at tubig ng buhay,<br/>Pinawi ang gutom at uhaw nila.<br/>Siya ang templo, doon sila''y namuhay,<br/>Laging sumasamba sa presensya Niya.<br/>',NULL,42669,6);
INSERT INTO stanza VALUES('T972','1','Ang sentrong isip ng Diyos—<br/>Siya''t tao''y maging isa;<br/>Siya ang lahat sa tao<br/>Nang plano Niya''y magawa.<br/>',NULL,42670,1);
INSERT INTO stanza VALUES('T972','2','Tao''y sisidlang lupa—<br/>May katawan, kalul''wa,<br/>''Spiritu na nilikha,<br/>Nang Diyos ay makaisa.<br/>',NULL,42671,2);
INSERT INTO stanza VALUES('T972','3','Buhay ng Diyos dumaloy<br/>Nang tao''y maging bato,<br/>Maitayo ang templo,<br/>Diyos l''walhatiin nito.<br/>',NULL,42672,3);
INSERT INTO stanza VALUES('T972','4','Bayang banal ''tinayo,<br/>Tahanang ibig ng Diyos,<br/>Bagong Herusalem ''to,<br/>Tinupad layon ng Diyos.<br/>',NULL,42673,4);
INSERT INTO stanza VALUES('T972','5','Pagtatayo ng banal,<br/>Diyos at tao''y naghalo,<br/>Binalak ng Maykapal,<br/>Nilugod Diyos at tao.<br/>',NULL,42674,5);
INSERT INTO stanza VALUES('T972','6','Sa gitna lakas nito,<br/>Trono ni Kristo at Diyos<br/>Doon buhay umagos<br/>Ng tubig na ''Spiritu.<br/>',NULL,42675,6);
INSERT INTO stanza VALUES('T972','7','Kristo''y puno ng buhay,<br/>Kabilaan ng ilog,<br/>Bungang dibinong buhay<br/>Ay sa ikabubusog.<br/>',NULL,42676,7);
INSERT INTO stanza VALUES('T972','8','Diyos kay Kristo''y siyang ilaw,<br/>Sa lunsod nagliwanag,<br/>Kadilima''y pumanaw<br/>Sa dibinong pagsinag.<br/>',NULL,42677,8);
INSERT INTO stanza VALUES('T972','9','Diyos sa tao, tao''t Diyos,<br/>Nanahang isa''t isa;<br/>Tao''y sinidlan ng Diyos<br/>Diyos sa tao''y makita.<br/>',NULL,42678,9);
INSERT INTO stanza VALUES('T973','1','Banal na lunsod at Panginoon,<br/>Maluwalhating bahagi''t layon;<br/>Buhay man ating katawan dito<br/>Kasama Niya espiritu roon,<br/>Kasama Niya espiritu roon.<br/>',NULL,42679,1);
INSERT INTO stanza VALUES('T973','2','Bagong Herusalem, hangad ng Diyos,<br/>Banal na lunsod ng Diyos at tao;<br/>Mga banal sa dugo''y tinubos,<br/>May bahaging matamasa rito,<br/>May bahaging matamasa rito.<br/>',NULL,42680,2);
INSERT INTO stanza VALUES('T973','3','Banal na lunsod, t''wing ating masdan,<br/>Nais makita mukha ni Hesus;<br/>Tawag Niya sana''y mapakikinggan,<br/>Sa lunsod matamasa Siyang lubos,<br/>Sa lunsod matamasa Siyang lubos.<br/>',NULL,42681,3);
INSERT INTO stanza VALUES('T973','4','Hangad ko''y hindi kapahingahan,<br/>Pag-asa ko''y hindi kagalakan,<br/>Kundi Pangin''on, "aming pag-asa,"<br/>Ang bahagi ko at gantimpala,<br/>Ang bahagi ko at gantimpala.<br/>',NULL,42682,4);
INSERT INTO stanza VALUES('T973','5','Panginoon, dinggin dalangin ko,<br/>Dalhin kami sa bayan na yaon!<br/>Nang sa l''walhati kabahagi Mo,<br/>Walang hanggang makabahagi Ka,<br/>Walang hanggang makabahagi Ka.<br/>',NULL,42683,5);
INSERT INTO stanza VALUES('T973','6','"Lahat ng bagay ay pawang bago,"<br/>Bagong langit, lupa''t tanang bagay!<br/>Maging bahagi nati''y Diyos Mismo,<br/>Bumalik agad, kami''y isama,<br/>Bumalik agad, kami''y isama.<br/>',NULL,42684,6);
INSERT INTO stanza VALUES('T974','1','Umasam sa lunsod, tolda''y tinirhan,<br/>Lakbay niya ay ''tungong kal''walhatian;<br/>Pangako ng Diyos ang kaaliwan niya,<br/>Hinangad niya''y ''di makamundong rangya.<br/>',NULL,42685,1);
INSERT INTO stanza VALUES('T974','chorus','Lunsod! O kay inam!<br/>Diyos sa tao''y tatahang walang hanggan.<br/>',NULL,42686,2);
INSERT INTO stanza VALUES('T974','2','Umasam sa lunsod, Diyos ang naghanda,<br/>Mansyong makalupa''y walang halaga,<br/>Ang Diyos ay nangako na siya''y bibigyan,<br/>Dakong makahari sa kaduluhan.<br/>',NULL,42687,3);
INSERT INTO stanza VALUES('T974','3','Umasam sa lunsod; may hinagpis man,<br/>Makalupang rangya ay tinanggihan,<br/>Umaawit ''pag lunsod naalala,<br/>Mabakong daan ''di na tatagal pa.<br/>',NULL,42688,5);
INSERT INTO stanza VALUES('T974','4','Umasam sa lunsod, aming hangarin,<br/>''Pagka''t batid na hinanda Mo sa ''min,<br/>Bilang bahagi, lunsod na maningning,<br/>Hesus kasama, daa''y tatahakin.<br/>',NULL,42689,7);
INSERT INTO stanza VALUES('T975','1','Sa simula isang hardin ito,<br/>Sa huli naging lunsod kwadrado;<br/>Ang halamanan Diyos ang naglalang,<br/>Lunsod naging pagtatayo naman.<br/>',NULL,42690,1);
INSERT INTO stanza VALUES('T975','2','Maging sa halamanan o lunsod,<br/>Puno''t ilog ng buhay siyang lugod;<br/>Ilog sagisag ng Espiritu,<br/>Tustos ng buhay, puno''y si Kristo.<br/>',NULL,42691,2);
INSERT INTO stanza VALUES('T975','3','Kapwa sa hardin at lunsod banal,<br/>Matagpuan tatlong bagay mahal;<br/>Ginto, perlas, mahalagang bato,<br/>Lahat ay para sa pagtatayo.<br/>',NULL,42692,3);
INSERT INTO stanza VALUES('T975','4','Ang tatlong bagay sa halamanan,<br/>Nagkalat do''n na materyal lamang;<br/>Sa lunsod naitayo nang lahat<br/>Bilang tahanan Niya''t Diyos ihayag.<br/>',NULL,42693,4);
INSERT INTO stanza VALUES('T975','5','Ang tao''y luwad sa halamanan,<br/>Makalupa walang l''walhati man;<br/>Puno ng buhay, nasa labas niya,<br/>Hindi pa naging buhay sa kanya.<br/>',NULL,42694,5);
INSERT INTO stanza VALUES('T975','6','Sa mal''walhating lunsod ang puno,<br/>Paglago''y sa sama-samang tao,<br/>Hinayag Kristo''y buhay dibino,<br/>Nang magtustos ng buhay sa tao.<br/>',NULL,42695,6);
INSERT INTO stanza VALUES('T975','7','Para sa lunsod, tao''y nilikha,<br/>Maisilang muli''t matransporma;<br/>Maging ginto, perlas, batong mahal,<br/>Bilang Katawan Niya''t wangis tanghal.<br/>',NULL,42696,7);
INSERT INTO stanza VALUES('T975','8','Sa loob ng hardin ay ang nobya,<br/>Para kay Adam, kapareha Niya;<br/>Kasintahang-babae ang lunsod,<br/>Kapuspusan ni Kristo at lugod.<br/>',NULL,42697,8);
INSERT INTO stanza VALUES('T975','9','Ang kumpletong pagtatayo ng Diyos,<br/>Binuo ng paghahalong lubos;<br/>Ng mga banal at ng Diyos Mismo,<br/>Siyang tahanan Niya''t nobya ni Kristo.<br/>',NULL,42698,9);
INSERT INTO stanza VALUES('T975','10','Kahayagan ng Diyos sa sukdulan,<br/>Ang pansansinukob na samahan;<br/>Tres-unong Diyos niluwalhati niya,<br/>Kapareha ni Kristo sa gloria!<br/>',NULL,42699,10);
INSERT INTO stanza VALUES('T976','1','Poong Hesus, Iyong tinubos<br/>Katawan at Nobya Mo;<br/>Kapuspusan, kahayagan,<br/>Nahayag ang Iyong yaman.<br/>Lahat-lahat Ka sa kanya,<br/>Yaman Mo''y hinayag niya;<br/>Bahagi''y kal''walhatian,<br/>Lubos Mo siyang babaran.<br/>',NULL,42700,1);
INSERT INTO stanza VALUES('T976','chorus','O lunsod na banal,<br/>May gloriang liwanag!<br/>Diyos kahayagang kumpleto,<br/>Sa pagka-tao.<br/>',NULL,42701,2);
INSERT INTO stanza VALUES('T976','2','Diyos sa tao''y naihalo,<br/>Pagkamakadiyos ito!<br/>Maningning ang Diyos sa gloria,<br/>Tao ay tahanan Niya.<br/>Pansansinukob sisidlan,<br/>Hayag Diyos kapuspusan;<br/>Nakikita kagandahan,<br/>Sa halong kabanalan.<br/>',NULL,42702,3);
INSERT INTO stanza VALUES('T976','chorus','O lunsod na banal,<br/>May gloriang liwanag!<br/>Diyos kahayagang kumpleto,<br/>Sa pagka-tao.<br/>',NULL,42703,4);
INSERT INTO stanza VALUES('T976','3','Buháy na pagkakabuo,<br/>Ng natranspormang tao,<br/>Gaya''y batong mahalaga,<br/>Naiwangis sa Kanya:<br/>Tubig ng buhay umagos,<br/>Mula sa trono ng Diyos;<br/>Kristo''y puno ng buhay nga,<br/>Namungang masagana.<br/>',NULL,42704,5);
INSERT INTO stanza VALUES('T976','chorus','O lunsod na banal,<br/>May gloriang liwanag!<br/>Diyos kahayagang kumpleto,<br/>Sa pagka-tao.<br/>',NULL,42705,6);
INSERT INTO stanza VALUES('T976','4','Ito''y gintong kandelero,<br/>Ang siyang ilawan Kristo.<br/>Diyos nasa loob ni Kristo,<br/>Kay liwanag ''Spiritu.<br/>Sukdulang kaganapan Siya,<br/>Tao''t Diyos walang hanggan,<br/>Sa isa''t isa''y tirahan,<br/>Layuning walang hanggan.<br/>',NULL,42706,7);
INSERT INTO stanza VALUES('T976','chorus','O lunsod na banal,<br/>May gloriang liwanag!<br/>Diyos kahayagang kumpleto,<br/>Sa pagka-tao.<br/>',NULL,42707,8);
INSERT INTO stanza VALUES('T977','1','Banal na lunsod ng Diyos ko,<br/>Ikaw Kanyang binuo;<br/>Ayon sa Kanyang salita,<br/>Maging tahanan nga Niya;<br/>Sa Bato ka nakasandig,<br/>Di ka matitigatig;<br/>Ika''y napapaligiran:<br/>Pader ng kaligtasan.<br/>',NULL,42708,1);
INSERT INTO stanza VALUES('T977','2','Ilog ng buháy na tubig,<br/>Bumukal sa pag-ibig,<br/>Sa iyong sangkap tumutustos,<br/>Takot napawing lubos;<br/>Sino pa ang manghihina<br/>Sa gayon ngang biyaya?<br/>Sa daloy, uhaw napawi,<br/>Titigil hinding-hindi.<br/>',NULL,42709,2);
INSERT INTO stanza VALUES('T977','3','Mga bahagi ng Sion,<br/>Nahugasan ng dugo;<br/>Saserdote''t hari sila,<br/>Kay Hesus umaasa.<br/>Dinaig ng pag-ibig Niya<br/>Upang pagharian nga<br/>Ang sarili at maghain<br/>Bilang saserdote rin.<br/>',NULL,42710,3);
INSERT INTO stanza VALUES('T977','4','Maging bahagi ng lunsod,<br/>Galak ko''y abot-abot;<br/>Matahin man nga ng mundo,<br/>L''walhati ko''y ngalan Mo.<br/>Lugod ng mundo''y lilipas,<br/>Maging rangya''y kukupas;<br/>Galak, yamang nanatili,<br/>Sangkap ng Sion may batid.<br/>',NULL,42711,4);
INSERT INTO stanza VALUES('T978','1','Sa bagong langit, lupa,<br/>May Bagong Her''salem;<br/>Diyos nagsilang sa kanya,<br/>May sinag ng gloria.<br/>',NULL,42712,1);
INSERT INTO stanza VALUES('T978','chorus','Taglay larawan ng Diyos;<br/>Bahagi''y gloria ng Diyos;<br/>Pangino''n naro''n Mismo,<br/>Lunsod ng Diyos ito!<br/>',NULL,42713,2);
INSERT INTO stanza VALUES('T978','2','Perlas lahat ng pinto;<br/>Sa lunsod na ginto,<br/>May ginintuang kalye,<br/>Pundasyon ay dose.<br/>',NULL,42714,3);
INSERT INTO stanza VALUES('T978','3','Dala''y buhay sa lunsod,<br/>Ng kristal na ilog;<br/>Puno ng buhay naman,<br/>Dulot kasiyahan.<br/>',NULL,42715,5);
INSERT INTO stanza VALUES('T978','4','Diyos dakilang AKO NGA<br/>Sa lunsod ng ilaw;<br/>Sa loob ng Kordero,<br/>Diyos liwanag totoo.<br/>',NULL,42716,7);
INSERT INTO stanza VALUES('T979','1','Kay l''walhati, kay liwanag,<br/>Bagong Herusalem banal;<br/>Tahanan ng Diyos at tao,<br/>Nobyang dalisay ni Kristo.<br/>',NULL,42717,1);
INSERT INTO stanza VALUES('T979','2','Luma''t Bagong Tipang banal,<br/>Siyang bumubuo sa lunsod;<br/>Tinayong tagapagmana,<br/>Diyos sa kanila''y tumira.<br/>',NULL,42718,2);
INSERT INTO stanza VALUES('T979','3','Lunsod perpektong kwadrado,<br/>Haba, l''wang, taas — pareho;<br/>Walang kulang, walang labis,<br/>Pawang wasto, walang lihis.<br/>',NULL,42719,3);
INSERT INTO stanza VALUES('T979','4','Lansanga''y gintong taganas,<br/>Gayang kristal namamalas;<br/>Tinukoy dibinong buhay,<br/>Kalikasan kanyang taglay.<br/>',NULL,42720,4);
INSERT INTO stanza VALUES('T979','5','Perlas lahat doseng pinto;<br/>Tukoy pagtubos ni Kristo,<br/>Sinilang-muli''t ''transporma,<br/>Pasok sa saklaw ng Diyos nga.<br/>',NULL,42721,5);
INSERT INTO stanza VALUES('T979','6','Doseng pundasyon ng pader,<br/>Pawang mahalagang bato;<br/>Dumaan sa init, gipit,<br/>Halaga ay mas humigit.<br/>',NULL,42722,6);
INSERT INTO stanza VALUES('T979','7','Jaspeng pader malakristal,<br/>L''walhati ng Diyos natanaw;<br/>Sinag mal''walhating ilaw,<br/>Bilang jaspe Siya''y lumitaw.<br/>',NULL,42723,7);
INSERT INTO stanza VALUES('T979','8','Pader nakapaghiwalay,<br/>Sa di malinis, di banal;<br/>Ginto, perlas, batong-hiyas,<br/>Taglay ng lunsod na wagas.<br/>',NULL,42724,8);
INSERT INTO stanza VALUES('T979','9','Diyos at Kordero ang Templo!<br/>Mukha''y makita ng tao;<br/>Kailanman ang presensya Niya,<br/>Sa Kanya''y laging sasamba.<br/>',NULL,42725,9);
INSERT INTO stanza VALUES('T979','10','Sa lunsod ang araw at buwan,<br/>Pawang hindi na kailangan;<br/>L''walhati ng Diyos ang ilaw,<br/>Kordero''y ilawang tanglaw.<br/>',NULL,42726,10);
INSERT INTO stanza VALUES('T979','11','Sa trono ng Kordero''t Diyos,<br/>Ilog ng buhay umagos;<br/>Magkabilang pampang nito,<br/>Punó ng buhay lumago.<br/>',NULL,42727,11);
INSERT INTO stanza VALUES('T979','12','Sinagisag buhay ng Diyos,<br/>Umaagos, may panustos;<br/>Dala''y awtoridad ng Diyos,<br/>Habang sa lunsod umagos.<br/>',NULL,42728,12);
INSERT INTO stanza VALUES('T979','13','Kalikasan ngang dibino,<br/>Ang lansangang purong ginto;<br/>Ilog ay maiinuman,<br/>Bunga''y may kasaganaan.<br/>',NULL,42729,13);
INSERT INTO stanza VALUES('T979','14','Bilang na dose''y gobyerno,<br/>At walang hanggang kumpleto;<br/>Diyos at tao naihalo,<br/>Produkto ng tres por kwatro.<br/>',NULL,42730,14);
INSERT INTO stanza VALUES('T979','15','Kadiliman, walang puwang,<br/>Kamatayan ni sakit man;<br/>Lumang bagay lumipas na,<br/>Diyos at tao magkasama.<br/>',NULL,42731,15);
INSERT INTO stanza VALUES('T979','16','Lunsod may larawan ng Diyos,<br/>Awtoridad Niya''y natalos;<br/>Tinutupad ang layon Niya,<br/>Mabigyang-kasiyahan Siya.<br/>',NULL,42732,16);
INSERT INTO stanza VALUES('T980','1','Luma''t Bagong Tipang Biblia<br/>Banal sagisag dalawa,<br/>Nobya Kanyang kinalugdan,<br/>Bahay Kanyang mapagtirhan.<br/>',NULL,42733,1);
INSERT INTO stanza VALUES('T980','2','Ang sagisag ng Ekklesia<br/>Sa Lumang Tipa''y dalawa:<br/>Nobya bilang kapareha,<br/>Bahay nang makapahinga.<br/>',NULL,42734,2);
INSERT INTO stanza VALUES('T980','3','Bayan ng Diyos noong una,<br/>Turing ng Diyos ay asawa;<br/>May tinayong tahanan Niya,<br/>May lunsod pinamahala.<br/>',NULL,42735,3);
INSERT INTO stanza VALUES('T980','4','Naging laman, Diyos-tao Siya<br/>Nobyo''y dumating sa nobya;<br/>Kanyang muling-''sinilang siya,<br/>Nang maging kapareha Niya.<br/>',NULL,42736,4);
INSERT INTO stanza VALUES('T980','5','Nabuhay na muling Kristo<br/>Salomong nagtayo''ng templo;<br/>Nang Diyos may mapahingahan,<br/>Layon Niya''y may katuparan.<br/>',NULL,42737,5);
INSERT INTO stanza VALUES('T980','6','Nobya ni Kristo''y Ekklesia,<br/>Kanyang lugod at pahinga;<br/>Bahay ng Diyos ang Ekklesia,<br/>Kahayagan, tirahan Niya.<br/>',NULL,42738,6);
INSERT INTO stanza VALUES('T980','7','Ang bagong Herusalem nga<br/>Ay Sukdulang kaganapan,<br/>Sagisag bahay at nobya,<br/>Ang planong may katuparan.<br/>',NULL,42739,7);
INSERT INTO stanza VALUES('T980','8','Nobyang kay Kristo''y tumugma,<br/>Angkop na kahayagan Niya;<br/>Tabernakulo rin ng Diyos,<br/>Pamahalaan Niyang lubos.<br/>',NULL,42740,8);
INSERT INTO stanza VALUES('T980','9','Napasukdol na kumpleto,<br/>Gawain ng Diyos sa tao;<br/>Mal''walhating kahayagan,<br/>Sa tinubos nga kailanman.<br/>',NULL,42741,9);
INSERT INTO stanza VALUES('T981','1','Ang ekonomiya ng Diyos.<br/>Kristo mamunong lubos;<br/>Nang Siyang Ulong nangunguna,<br/>Lahat magkakaisa.<br/>',NULL,42742,1);
INSERT INTO stanza VALUES('T981','2','Kristo''y Ulo, Sentro nga Siya,<br/>Diyos sa loob Ilaw Niya;<br/>Kristo at Diyos nasa trono,<br/>Tutupdin Kanyang gusto.<br/>',NULL,42743,2);
INSERT INTO stanza VALUES('T981','3','Kristo''y buhay nilalaman,<br/>Mga banal sisidlan;<br/>Siya''y namuno sa liwanag,<br/>Gloria Niya''y inihayag.<br/>',NULL,42744,3);
INSERT INTO stanza VALUES('T981','4','Satanas ay itinurok<br/>Sarili niya sa tao;<br/>Dala''y dilim, pagkabulok,<br/>Balak ng Diyos mabigo.<br/>',NULL,42745,4);
INSERT INTO stanza VALUES('T981','5','Kristo Mismo namahagi<br/>Ng buhay Niyang Sarili,<br/>Kamatayan at ang dilim,<br/>Tao''y di maalipin.<br/>',NULL,42746,5);
INSERT INTO stanza VALUES('T981','6','Sa Ekklesiang Katawan Niya,<br/>Kristong Ulo lahat nga;<br/>Tanan ay magkakatugma,<br/>Maliit ma''t dakila.<br/>',NULL,42747,6);
INSERT INTO stanza VALUES('T981','7','Sa ''lalim ni Kristong Ulo,<br/>Kaisahan iiral;<br/>Sa liwanag ng Ekklesia,<br/>Lahat napasa Isa.<br/>',NULL,42748,7);
INSERT INTO stanza VALUES('T981','8','Bilang Ulo kinilala,<br/>Lahat aayos na nga;<br/>Sa pagsinag ng Katawan,<br/>Lahat may kalayaan.<br/>',NULL,42749,8);
INSERT INTO stanza VALUES('T981','9','Walang dilim, kasiraan,<br/>Wala nang kamatayan;<br/>Lahat nasa kalayaan,<br/>Hanggang sa walang hanggan.<br/>',NULL,42750,9);
INSERT INTO stanza VALUES('T984','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42751,1);
INSERT INTO stanza VALUES('T984','1','Ilog ng tubig na buháy,<br/>Sa trono nga nagbuhat,<br/>Salamuha''y naibigay,<br/>Awtoridad tinaglay.<br/>',NULL,42752,2);
INSERT INTO stanza VALUES('T984','chorus','Ilog ng tubig na buháy,<br/>Malayang salamuha,<br/>May awtoridad na dala,<br/>Saan man ''to mapunta.<br/>',NULL,42753,3);
INSERT INTO stanza VALUES('T984','2','''Spiritu''y ilog ng buhay,<br/>Agos, Diyos bilang buhay;<br/>Pagkapanginoo''y dala,<br/>Saanman ''to mapunta.<br/>',NULL,42754,4);
INSERT INTO stanza VALUES('T984','3','Umagos sa gintong daan,<br/>Tinuro sa ''tin daan,<br/>Nasa kalikasan ng Diyos,<br/>Yao''y tahaking lubos.<br/>',NULL,42755,6);
INSERT INTO stanza VALUES('T984','4','Sa pampang puno ng buhay,<br/>Diyos ''ting pagkaing tunay;<br/>Kung saan Siya umaagos.<br/>Naroon ang panustos.<br/>',NULL,42756,8);
INSERT INTO stanza VALUES('T984','5','Poon nabasag Ka minsan,<br/>Nang kami''y padaluyan;<br/>Basagin din naman ako,<br/>Nang umagos tubig Mo.<br/>',NULL,42757,10);
INSERT INTO stanza VALUES('T985','1','Sisidlang luad ''di na,<br/>Kalagyan yaman Niya;<br/>Kundi sa gandang hayag,<br/>Ikaw ay sisinag.<br/>',NULL,42758,1);
INSERT INTO stanza VALUES('T985','2','Gloria ng Diyos sisilang;<br/>Sa gintong sisidlan;<br/>''Di na kailangan sinag,<br/>Diyos ating liwanag.<br/>',NULL,42759,2);
INSERT INTO stanza VALUES('T985','3','Lunsod ng Diyos maganda,<br/>Mahal na Bato Siya,<br/>Gayang jaspe ang sinag,<br/>Gloriang walang ulap.<br/>',NULL,42760,3);
INSERT INTO stanza VALUES('T985','4','Sa malaking sisidlan,<br/>Walang kadiliman;<br/>Liwanag kapuspusan,<br/>Sa sangkalupaan.<br/>',NULL,42761,4);
INSERT INTO stanza VALUES('T985','5','Sa bago Niyang nilikha,<br/>Gloria Niya''y makita;<br/>Sisidlang sumisinag<br/>Sa Kordero''y Kab''yak.<br/>',NULL,42762,5);
INSERT INTO stanza VALUES('T985','6','Ang sisidlang may gloria,<br/>Sanhi ng pagsamba;<br/>Diyos sa lo''b ng Kordero,<br/>Hayag walang hinto.<br/>',NULL,42763,6);
INSERT INTO stanza VALUES('T986','1','Kristo''y nagligtas nang lubos,<br/>Mahusay Manunubos!<br/>Binayaran ang pantubos,<br/>Mahusay Manunubos!<br/>',NULL,42764,1);
INSERT INTO stanza VALUES('T986','chorus','Mahusay Manunubos, Hesus Panginoon;<br/>Mahusay Manunubos, Tagapagligtas!<br/>',NULL,42765,2);
INSERT INTO stanza VALUES('T986','2','Purihin Siya, Kanyang dugo,<br/>Mahusay Manunubos!<br/>Ako''t Diyos napagkasundo,<br/>Mahusay Manunubos!<br/>',NULL,42766,3);
INSERT INTO stanza VALUES('T986','3','Sa sala''y hinugasan Niya:<br/>Mahusay Manunubos!<br/>Sa loob Siya''y naghari na,<br/>Mahusay Manunubos!<br/>',NULL,42767,5);
INSERT INTO stanza VALUES('T986','4','Araw-araw nananahan,<br/>Mahusay Manunubos!<br/>Bigyan akong katapatan,<br/>Mahusay Manunubos!<br/>',NULL,42768,7);
INSERT INTO stanza VALUES('T986','5','Ako''y binigyan ng lakas,<br/>Mahusay Manunubos!<br/>At tagumpay bawa''t oras,<br/>Mahusay Manunubos!<br/>',NULL,42769,9);
INSERT INTO stanza VALUES('T986','6','Alay sa Kanya, puso ko,<br/>Mahusay Manunubos!<br/>Walang bahagi ang mundo,<br/>Mahusay Manunubos!<br/>',NULL,42770,11);
INSERT INTO stanza VALUES('T987','1','Nang mapuno ng papuri ang langit,<br/>Nang lubhang kay itim na ng sala,<br/>Si Hesus ay isinilang ng birhen—<br/>Namuhay Siya, tularan ko Siya!<br/>',NULL,42771,1);
INSERT INTO stanza VALUES('T987','chorus','Nabuhay, umibig, namatay Siya<br/>Nilibing nang sala''y maalis Niya;<br/>Bumangon, nagbigay ng katuwiran:<br/>Siya''y babalik — O kal''walhatian!<br/>',NULL,42772,2);
INSERT INTO stanza VALUES('T987','2','Nang Siya''y dalhin sa bundok ng Kalbaryo,<br/>Namatay nang ipako sa puno;<br/>Tinanggihan, hinamak, ininsulto;<br/>Sala''y dala ng Manunubos ko.<br/>',NULL,42773,3);
INSERT INTO stanza VALUES('T987','chorus','Nabuhay, umibig, namatay Siya<br/>Nilibing nang sala''y maalis Niya;<br/>Bumangon, nagbigay ng katuwiran:<br/>Siya''y babalik — O kal''walhatian!<br/>',NULL,42774,4);
INSERT INTO stanza VALUES('T987','3','Nang sa hardin, kanilang iniwan Siya<br/>Humimlay, Siya sa dusa''y lumaya;<br/>Mga anghel nagbantay sa libingan;<br/>Pag-asa ng walang maasahan.<br/>',NULL,42775,5);
INSERT INTO stanza VALUES('T987','chorus','Nabuhay, umibig, namatay Siya<br/>Nilibing nang sala''y maalis Niya;<br/>Bumangon, nagbigay ng katuwiran:<br/>Siya''y babalik — O kal''walhatian!<br/>',NULL,42776,6);
INSERT INTO stanza VALUES('T987','4','Nang hindi na makubli ng libingan,<br/>Nang maalis ang batong pangharang;<br/>Bumangon Siyang gupo ang kamatayan;<br/>Sumalangit, Poon kailan pa man.<br/>',NULL,42777,7);
INSERT INTO stanza VALUES('T987','chorus','Nabuhay, umibig, namatay Siya<br/>Nilibing nang sala''y maalis Niya;<br/>Bumangon, nagbigay ng katuwiran:<br/>Siya''y babalik — O kal''walhatian!<br/>',NULL,42778,8);
INSERT INTO stanza VALUES('T987','5','Pagbalik Niya''y tutunog ang trumpeta,<br/>Gloria Niya sa langit makikita;<br/>Mga minamahal ko ay dadalhin;<br/>Manliligtas, si Hesus ay akin!<br/>',NULL,42779,9);
INSERT INTO stanza VALUES('T987','chorus','Nabuhay, umibig, namatay Siya<br/>Nilibing nang sala''y maalis Niya;<br/>Bumangon, nagbigay ng katuwiran:<br/>Siya''y babalik — O kal''walhatian!<br/>',NULL,42780,10);
INSERT INTO stanza VALUES('T988','1','Habag at pag-ibig ang Kanyang taglay,<br/>Para sa salarin, nagpasan ng krus,<br/>Nagdugo, nagdusa, at Siya''y namatay,<br/>Anong gagawin mo kay Kristo Hesus?<br/>',NULL,42781,1);
INSERT INTO stanza VALUES('T989','1','O anong dusa at kahihiyan,<br/>Hesus ay nahimlay sa sabsaban;<br/>O kamangha-mangha! Purihin Siya!<br/>Ako''y hinanap Niya:<br/>Ako''y hinanap Niya,<br/>Ako''y hinanap Niya;<br/>O kamangha-mangha! Purihin Siya!<br/>Ako''y hinanap Niya.<br/>',NULL,42782,1);
INSERT INTO stanza VALUES('T989','2','Dahil sa akin Hesus namatay,<br/>Sa krus ng Kalbaryo''y nabayubay;<br/>Aking kasalana''y binayaran,<br/>Ng Iyong kamatayan!<br/>Sa halip namatay,<br/>Sa halip namatay;<br/>O kamangha-mangha — paano nga?<br/>Sa halip namatay!<br/>',NULL,42783,2);
INSERT INTO stanza VALUES('T989','3','Hesus di nagmamaliw kailanman,<br/>Habang ako ay nasa karimlan,<br/>Sumasamo sa aking kalul''wa,<br/>Matimyas, tawag Niya!<br/>Tumatawag sa ''kin,<br/>Tumatawag sa ''kin;<br/>Matimyas samo sa ''king kalul''wa,<br/>Tumatawag sa ''kin!<br/>',NULL,42784,3);
INSERT INTO stanza VALUES('T989','4','Hesus Tagapagligtas darating,<br/>Kay tamis ng pangako sa akin.<br/>Matatanaw ko Kanyang pagdating<br/>Na para sa akin!<br/>Pagdating ay sa ''kin,<br/>Pagdating ay sa ''kin;<br/>Matatanaw ko Kanyang pagdating<br/>Na para sa ''kin!<br/>',NULL,42785,4);
INSERT INTO stanza VALUES('T993','1','O anong tamis ng ulat,<br/>At mal''walhati;<br/>Kahapon, ngayon, kailanman,<br/>Hesus ay lagi.<br/>May sala Kanyang niligtas,<br/>Sakit pinawi;<br/>Nagbigay-aliw sa lumbay;<br/>Siya''y mal''walhati!<br/>',NULL,42786,1);
INSERT INTO stanza VALUES('T993','chorus','Kahapon, ngayon, kailanman,<br/>Hesus ay lagi,<br/>Magbago man ang lahat, Siya''y<br/>Gaya ng dati!<br/>Siya''y mal''walhati,<br/>Siya''y mal''walhati;<br/>Magbago man ang lahat, Siya''y<br/>Gaya ng dati.<br/>',NULL,42787,2);
INSERT INTO stanza VALUES('T993','2','Siyang kaibigan ng salarin,<br/>Hinahanap ka;<br/>Lumapit sa paanan Niya,<br/>Magpakumbaba.<br/>"Di kita hahatulan, huwag<br/>Nang magkasala,"<br/>Sa iyo Kanyang sinasaad,<br/>Pinatawad ka.<br/>',NULL,42788,3);
INSERT INTO stanza VALUES('T993','3','Ginamot Niya ang sa mundo''y<br/>Nangagdurusa;<br/>Lungkot at sakit napawi,<br/>Sa pag-utos Niya.<br/>Sa paghipo ng babae''y<br/>Nagbigay lunas;<br/>Sa nanalig, nagbigay rin<br/>Nang yamang wagas.<br/>',NULL,42789,5);
INSERT INTO stanza VALUES('T993','4','Lumakad Siya sa Emmaus,<br/>Sila''y kapiling;<br/>Lumalakad Siyang kay lapit<br/>Sa buhay natin.<br/>Siya''y muli nating makita,<br/>''Di na lalaon;<br/>Darating si Hesus gaya<br/>Nang Siya''y yumaon.<br/>',NULL,42790,7);
INSERT INTO stanza VALUES('T994','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42791,1);
INSERT INTO stanza VALUES('T994','1','Dakilang pag-ibig — Hesus bumaba,<br/>Sa Kalbaryo Siya ay nagpunta,<br/>Dinanas ang hirap, pag-alipusta,<br/>Para sa akin Siya''y nagdusa.<br/>',NULL,42792,2);
INSERT INTO stanza VALUES('T994','chorus','Nagpunta sa Kalbaryo sa halip ko,<br/>Sa halip ko, sa halip ko,<br/>Nagpunta sa Kalbaryo sa halip ko,<br/>Iniligtas ako.<br/>',NULL,42793,3);
INSERT INTO stanza VALUES('T994','2','O kasawian — Pinako si Hesus!<br/>Paa, kamay, ulo''y nagdugo,<br/>Katawang sugatan, dugo''y umagos,<br/>Pagka''t kinahabagan ako.<br/>',NULL,42794,4);
INSERT INTO stanza VALUES('T994','chorus','Kinahabagan ako doon sa krus,<br/>Doon sa krus, doon sa krus,<br/>Kinahabagan ako doon sa krus,<br/>Kinalag ang gapos.<br/>',NULL,42795,5);
INSERT INTO stanza VALUES('T994','3','Lupa kay dilim nang Siya''y hinatulan!<br/>Liyab ng banal na kapootan;<br/>Pinasan Niya ang aking kasalanan,<br/>Sa halip ko''y pinarusahan.<br/>',NULL,42796,6);
INSERT INTO stanza VALUES('T994','chorus','Namatay sa krus, ako''y hinalinhan,<br/>Hinalinhan, hinalinhan,<br/>Namatay sa krus, ako''y hinalinhan,<br/>Sala ko''y pinasan.<br/>',NULL,42797,7);
INSERT INTO stanza VALUES('T994','4','Mangmang sa biyaya, salaring takot,<br/>Ngayon ang Kalbaryo''y nakita,<br/>Sa Kanyang dugo, patawad iyong abot,<br/>Tinubos sa kamatayan Niya.<br/>',NULL,42798,8);
INSERT INTO stanza VALUES('T994','chorus','Sa krus nagdugo nang ako''y tubusin,<br/>Ako''y tubusin, tubusin,<br/>Sa krus nagdugo nang ako''y tubusin,<br/>Ligtas sa tiisin.<br/>',NULL,42799,9);
INSERT INTO stanza VALUES('T997','1','Sabi ng Panginoon:<br/>"Lakas mo''y ''di sapat,<br/>Sa Akin masumpungan<br/>Buhay at lahat-lahat."<br/>',NULL,42800,1);
INSERT INTO stanza VALUES('T997','chorus','Hesus nagbayad<br/>Ng aking utang;<br/>Sala ko''y pinatawad,<br/>Ako''y hinugasan.<br/>',NULL,42801,2);
INSERT INTO stanza VALUES('T997','2','Sa kapangyarihan Mo,<br/>Aking nasumpungan:<br/>Natunaw batong puso,<br/>Ketong ay nalinisan.<br/>',NULL,42802,3);
INSERT INTO stanza VALUES('T997','3','Wala ''kong kabutihan<br/>Bagay sa b''yaya Mo,<br/>Damit ko''y huhugasan<br/>Sa dugo ng Kordero.<br/>',NULL,42803,5);
INSERT INTO stanza VALUES('T997','4','Sa harap ng luklukan,<br/>Sa Kanya ''ko''y lubos,<br/>Aking patotohanan:<br/>"Manliligtas ko''y Hesus!"<br/>',NULL,42804,7);
INSERT INTO stanza VALUES('T998','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42805,1);
INSERT INTO stanza VALUES('T998','1','Mahal ako ni Hesus at<br/>Siya ay nagkatawang-tao;<br/>Dinusta, hinampas, hanggang<br/>Sa krus Siya ay ipinako.<br/>',NULL,42806,2);
INSERT INTO stanza VALUES('T998','2','Namatay para sa ''kin,<br/>Namatay para sa ''kin,<br/>Para sa akin, sa akin,<br/>Namatay para sa ''kin.<br/>',NULL,42807,3);
INSERT INTO stanza VALUES('T1000','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42808,1);
INSERT INTO stanza VALUES('T1000','1','Ang mga gawa ko<br/>Gaano mang kawagas,<br/>Sukdulang kabanalan,<br/>Di makapagliligtas<br/>Sa kaluluwa ko.<br/>',NULL,42809,2);
INSERT INTO stanza VALUES('T1000','chorus','Si Hesus ang lumuha,<br/>At sa krus Siya''y nagdusa,<br/>Siya lamang ang sa akin<br/>Makapagliligtas.<br/>',NULL,42810,3);
INSERT INTO stanza VALUES('T1000','2','Gaanong pagluha<br/>Takot ko''y di maalis,<br/>Sala ko''y di malinis,<br/>Di makapagliligtas<br/>Sa kaluluwa ko.<br/>',NULL,42811,4);
INSERT INTO stanza VALUES('T1000','3','Gaanong pag''hintay<br/>Ay walang kabuluhan,<br/>Kamataya''y hantungan,<br/>Di makapagliligtas<br/>Sa kaluluwa ko.<br/>',NULL,42812,6);
INSERT INTO stanza VALUES('T1000','4','Pagtanggap kay Kristo,<br/>Tawagin ang ngalan Niya:<br/>"O Panginoong Hesus,"<br/>Manalig sa gawa Niya,<br/>Ako ay ligtas na.<br/>',NULL,42813,8);
INSERT INTO stanza VALUES('T1003','1','Bakit ako mangangamba?<br/>Di ba ang Diyos ang nagpasya,<br/>Sala ko''y pasanin?<br/>Kristo''ng nagbayad ng utang,<br/>Diyos ba''y muling magparatang,<br/>At ako''y singilin?<br/>',NULL,42814,1);
INSERT INTO stanza VALUES('T1003','2','Ang Panginoo''y nagtubos,<br/>Kabayaran ay nalubos,<br/>Lumaya sa utos!<br/>Poot ng Diyos — di na takot,<br/>Pagka''t dugo Niya''y panagot<br/>Tinakpan nang lubos.<br/>',NULL,42815,2);
INSERT INTO stanza VALUES('T1003','3','Patawad para sa akin<br/>Buung-buo Iyong naangkin,<br/>Sala ay tinuos;<br/>Di sisingil sa dalawa<br/>Ang Diyos: sa Anak Niyang Sinta,<br/>Sa ''kin pagkatapos.<br/>',NULL,42816,3);
INSERT INTO stanza VALUES('T1003','4','Ngayon ako''y matiwasay,<br/>Gawa ni Kristo''y mahusay,<br/>Ako''y pinalaya;<br/>Dahil sa mabisang dugo,<br/>Di na hahatulan ako,<br/>Ako''y natubos na.<br/>',NULL,42817,4);
INSERT INTO stanza VALUES('T1005','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42818,1);
INSERT INTO stanza VALUES('T1005','1','Namatay para sa salarin,<br/>Ang Manunubos nating Kristo;<br/>Dugo Niya''y ''winisik sa puso,<br/>"At ikaw nga''y lalampasan Ko."<br/>',NULL,42819,2);
INSERT INTO stanza VALUES('T1005','chorus','"Kung makita Ko<br/>Ang dugo, dugo,<br/>Kung makita Ko,<br/>Ikaw nga ay lalampasan Ko."<br/>',NULL,42820,3);
INSERT INTO stanza VALUES('T1005','2','Punong salarin, ''liligtas Niya;<br/>Tutupdin ang Kanyang pangako;<br/>Batis para sa kasalanan,<br/>"At ikaw nga''y lalampasan Ko."<br/>',NULL,42821,4);
INSERT INTO stanza VALUES('T1005','3','Ang lahat ay mahahatulan,<br/>Bawa''t isa''y may matatamo;<br/>Magkubli sa dugong nagligtas,<br/>"At ikaw nga''y lalampasan Ko."<br/>',NULL,42822,6);
INSERT INTO stanza VALUES('T1005','4','Dakilang pag-ibig at habag!<br/>Kabutihang tapat, totoo!<br/>Sa dugo''y payapa at ligtas,<br/>"At ikaw nga''y lalampasan Ko."<br/>',NULL,42823,8);
INSERT INTO stanza VALUES('T1006','1','May bukal ng dugong banal<br/>Kay Hesus nagmula;<br/>Maysalang doo''y sisisid,<br/>Mawawala ang bahid:<br/>Mawawala ang bahid,<br/>Mawawala ang bahid;<br/>Maysalang doo''y sisisid,<br/>Mawawala ang bahid.<br/>',NULL,42824,1);
INSERT INTO stanza VALUES('T1006','2','Ang magnanakaw nasa krus<br/>Nakita ang bisa;<br/>Sala kong mas marami man<br/>Pawang mahuhugasan:<br/>Pawang mahuhugasan,<br/>Pawang mahuhugasan;<br/>Sala kong mas marami man,<br/>Pawang mahuhugasan.<br/>',NULL,42825,2);
INSERT INTO stanza VALUES('T1006','3','Di-magmamaliw ang bisa<br/>Dugo ng Kordero,<br/>Hangga''t ang mga tinubos<br/>Maliligtas nang lubos:<br/>Maliligtas nang lubos,<br/>Maliligtas nang lubos;<br/>Hangga''t ang mga tinubos,<br/>Maliligtas nang lubos.<br/>',NULL,42826,3);
INSERT INTO stanza VALUES('T1006','4','Mula nang aking makita<br/>Ang Iyong pagdurusa,<br/>Mapanubos na pagsinta,<br/>Kita''y pupurihin pa:<br/>Kita''y pupurihin pa,<br/>Kita''y pupurihin pa;<br/>Mapanubos na pagsinta,<br/>Kita''y pupurihin pa.<br/>',NULL,42827,4);
INSERT INTO stanza VALUES('T1006','5','Kapag puso''y nanahimik,<br/>Pati dila''t bibig,<br/>Sa pagkabuhay aawit,<br/>Pag-ibig Mo''y sumagip:<br/>Pag-ibig Mo''y sumagip,<br/>Pag-ibig Mo''y sumagip;<br/>Sa pagkabuhay aawit,<br/>Pag-ibig Mo''y sumagip.<br/>',NULL,42828,5);
INSERT INTO stanza VALUES('T1007','1','Nalapitan mo na ba ang Kordero?<br/>Nahugasan sa Kanyang dugo?<br/>Natanggap ang biyaya sa puso mo?<br/>Nahugasan sa Kanyang dugo?<br/>',NULL,42829,1);
INSERT INTO stanza VALUES('T1007','chorus','Nahugasan ka ba<br/>Sa naglilinis na dugo Niya?<br/>Simputi ng niebe kasuotan ba?<br/>Dugo Niya''y nalinisan ka ba?<br/>',NULL,42830,2);
INSERT INTO stanza VALUES('T1007','2','Kapatawaran ba''y natanggap mo na?<br/>Nahugasan sa Kanyang dugo?<br/>Dahil sa pagtubos mapayapa ka?<br/>Nahugasan sa Kanyang dugo?<br/>',NULL,42831,3);
INSERT INTO stanza VALUES('T1007','3','Pagdating Niya damit mo''y puti kaya?<br/>Nahugasan sa Kanyang dugo?<br/>Karapat-dapat ka bang putungan Niya?<br/>Nahugasan sa Kanyang dugo?<br/>',NULL,42832,5);
INSERT INTO stanza VALUES('T1007','4','Itabi ang barong may mantsang sala,<br/>Mahugasan sa Kanyang dugo;<br/>Batis sa Kalbaryo''y lilinisin ka,<br/>Mahugasan sa Kanyang dugo.<br/>',NULL,42833,7);
INSERT INTO stanza VALUES('T1009','1','Nais mo bang maibsan ng sala?<br/>Makapangyarihan ang dugo;<br/>At magtagumpay sa kasamaan?<br/>Dugo''y may kapangyarihan.<br/>',NULL,42834,1);
INSERT INTO stanza VALUES('T1009','chorus','Ang dugo''y may kapangyarihan,<br/>Dugo ng Kordero,<br/>Ang dugo''y may kapangyarihan,<br/>Dugong mahal ng Kordero.<br/>',NULL,42835,2);
INSERT INTO stanza VALUES('T1009','2','Nais mo bang mapalayang tunay?<br/>Makapangyarihan ang dugo,<br/>Sa kahalaya''t kapalaluan?<br/>Dugo''y may kapangyarihan.<br/>',NULL,42836,3);
INSERT INTO stanza VALUES('T1009','3','Nais mo bang puso''y dumalisay?<br/>Makapangyarihan ang dugo,<br/>Ang batik ng sala''y mahugasan?<br/>Dugo''y may kapangyarihan.<br/>',NULL,42837,5);
INSERT INTO stanza VALUES('T1009','4','Nais mo bang maglingkod sa Hari?<br/>Makapangyarihan ang dugo,<br/>Mabuhay ka nang Siya''y papurihan?<br/>Dugo''y may kapangyarihan.<br/>',NULL,42838,7);
INSERT INTO stanza VALUES('T1011','1','May isang higit na kay sarap umibig!<br/>Pag-ibig Niya''y higit sa isang kapatid!<br/>Mga panlupang kaibigan,<br/>Sa iyo''y hatid saya''t dusa;<br/>Hesus di-mandaraya:<br/>Anong pagsinta!<br/>',NULL,42839,1);
INSERT INTO stanza VALUES('T1011','2','Nababatid Buhay na walang hanggan nga!<br/>Isipin ga''nong pagkautang sa Kanya!<br/>Sa dugo, binili tayo;<br/>Sa ilang, hinanap tayo;<br/>Sa kawan, hinatid Niya:<br/>Anong pagsinta!<br/>',NULL,42840,2);
INSERT INTO stanza VALUES('T1011','3','Pinagpalang Hesus! makilala mo ba?<br/>Sarili''y ialay nang ganap sa Kanya.<br/>Ang bukas hu-wag isipin,<br/>Lakas-loob na harapin,<br/>Lahat ng kalungkutan<br/>Kanyang dadalhin!<br/>',NULL,42841,3);
INSERT INTO stanza VALUES('T1011','4','Sa sala''y Kanya ka ngang patatawarin!<br/>Mga kaaway mo''y Kanyang aalisin!<br/>Mas mabuting pagpapala,<br/>Pawang buti walang samâ,<br/>Kanyang gagabayan ka<br/>tungo sa gloria!<br/>',NULL,42842,4);
INSERT INTO stanza VALUES('T1015','1','O l''walhati, anong buhay<br/>Ang aking natanggap!<br/>Kadiliman, kamatayan,<br/>At kapangyarihan nitong kasalanan<br/>Itinaboy nang lubusan!<br/>',NULL,42843,1);
INSERT INTO stanza VALUES('T1017','1','Kristo''y nagkatawang-tao, naging taong tulad ko,<br/>Namatay sa krus nang kay Adam ako''y mapalaya,<br/>Siya''y nagbangon pumasok sa ''kin bilang Espiritu,<br/>Naging buhay ko Siya.<br/>',NULL,42844,1);
INSERT INTO stanza VALUES('T1017','chorus','Luwalhati, Aleluya!<br/>Luwalhati, Aleluya!<br/>Luwalhati, Aleluya!<br/>Kristo''y aking buhay.<br/>',NULL,42845,2);
INSERT INTO stanza VALUES('T1017','2','Kristo''y nagkatawang-tao, naging taong tulad ko,<br/>Namatay sa krus nang kay Adam ako''y mapalaya,<br/>Siya''y nagbangon pumasok sa ''kin bilang Espiritu,<br/>Naging buhay ko Siya.<br/>',NULL,42846,3);
INSERT INTO stanza VALUES('T1017','chorus','O tagumpay, Aleluya!<br/>O tagumpay, Aleluya!<br/>O tagumpay, Aleluya!<br/>Kristo''y aking lahat.<br/>',NULL,42847,4);
INSERT INTO stanza VALUES('T1020','1','Sinong magpapalaya<br/>Sa sala? Kristo nga!<br/>Sinong magiging buhay?<br/>Kristo nga!<br/>Kristo nga! Kristo nga!<br/>Kristo magpapalaya,<br/>Kristo nga!<br/>',NULL,42848,1);
INSERT INTO stanza VALUES('T1021','1','Nalason ng kamatayan<br/>Ang makasalanan;<br/>Sa sala at kamatayan<br/>Kristo, kaligtasan.<br/>Siya ay walang hanggang Isa,<br/>Ibig magpalaya;<br/>Sumampalataya ka na,<br/>Nang mabuhay ka pa!<br/>',NULL,42849,1);
INSERT INTO stanza VALUES('T1024','1','Hesu-Kristo, Siya ang kailangan mo,<br/>Siya ang Diyos na nagkatawang-tao;<br/>Lahat ng hirap Kanyang dinanas<br/>Kailangan si Hesus upang ika''y maligtas!<br/>',NULL,42850,1);
INSERT INTO stanza VALUES('T1024','chorus','Si Hesus ang iyong kailangan!<br/>Kailangan Siya ng tanan!<br/>Katubusan, kailangan,<br/>Kaligtasan, kailangan!<br/>At buhay walang hanggan,<br/>Kailangan Hesus!<br/>',NULL,42851,2);
INSERT INTO stanza VALUES('T1024','2','Nabuhay Siya at sumalangit na,<br/>Maniwala, tawagin ngalan Niya;<br/>Kapag ika''y sumampalataya,<br/>Mapasa iyo tugon ng kailangang biyaya.<br/>',NULL,42852,3);
INSERT INTO stanza VALUES('T1024','chorus','Si Hesus ang iyong kailangan!<br/>Kailangan Siya ng tanan!<br/>Katubusan, kailangan,<br/>Kaligtasan, kailangan!<br/>At buhay walang hanggan,<br/>Kailangan Hesus!<br/>',NULL,42853,4);
INSERT INTO stanza VALUES('T1024','3','Tatanglawan iyong pusong madilim,<br/>Kasalanan mo''y patatawarin;<br/>Huhugasan ka ng Kanyang dugo,<br/>Buhay ng Diyos ay ipagkakaloob sa iyo!<br/>',NULL,42854,5);
INSERT INTO stanza VALUES('T1024','chorus','Si Hesus ang iyong kailangan!<br/>Kailangan Siya ng tanan!<br/>Katubusan, kailangan,<br/>Kaligtasan, kailangan!<br/>At buhay walang hanggan,<br/>Kailangan Hesus!<br/>',NULL,42855,6);
INSERT INTO stanza VALUES('T1024','4','Sa buhay mo may kakulangan pa,<br/>Habang tumatagal, lumalala;<br/>Tanging Hesus makapagbibigay<br/>Ng kasiyahang kulang sa hungkag mong buhay!<br/>',NULL,42856,7);
INSERT INTO stanza VALUES('T1024','chorus','Si Hesus ang iyong kailangan!<br/>Kailangan Siya ng tanan!<br/>Mawala — kahungkagan,<br/>Matamo — kasiyahan,<br/>Buhay may kabuluhan,<br/>Kailangan Hesus!<br/>',NULL,42857,8);
INSERT INTO stanza VALUES('T1024','5','Ang mundo''y pawang kapighatian,<br/>Sa panganib walang maasahan;<br/>Ang lahat ay walang kabuluhan,<br/>Nagpapatunay na si Hesus ang kailangan!<br/>',NULL,42858,9);
INSERT INTO stanza VALUES('T1024','chorus','Si Hesus ang iyong kailangan!<br/>Kailangan Siya ng tanan!<br/>Katubusan, kailangan,<br/>Kaligtasan, kailangan!<br/>At buhay walang hanggan,<br/>Kailangan Hesus!<br/>',NULL,42859,10);
INSERT INTO stanza VALUES('T1025','1','Mundo''y iwan, Kristo''y kamtan,<br/>Sa puso ko, kasiyahan;<br/>Tanging Kristo, aking mahal,<br/>Ang mundo''y pawang sukal!<br/>',NULL,42860,1);
INSERT INTO stanza VALUES('T1025','chorus','Ang yaman Niya di mabigkas<br/>Nguni''t aking talastas;<br/>Tamis Niyang kaaya-aya,<br/>Aking natatamasa.<br/>',NULL,42861,2);
INSERT INTO stanza VALUES('T1025','2','Mundo''y iwan, Kristo''y kamtan,<br/>Walang ibang kailangan;<br/>Mundo''y kamtan, may kulang pa,<br/>Kristo''y kamtan, sapat na.<br/>',NULL,42862,3);
INSERT INTO stanza VALUES('T1025','3','Munting puso di mapuno,<br/>Malaki man ang mundo;<br/>Munting puso''y laging salat<br/>Kristo lang makasapat.<br/>',NULL,42863,5);
INSERT INTO stanza VALUES('T1025','4','Kung may Kristo, nalulugod;<br/>Walang Kristo, malungkot;<br/>Kristo''y aking kayamanan;<br/>At Siya''y aking tahanan.<br/>',NULL,42864,7);
INSERT INTO stanza VALUES('T1027','1','Malambing na tumatawag si Hesus—<br/>Sa i-yo at sa akin;<br/>Hinanap ka, ibig ka Niyang iligtas—<br/>Tumatawag ngayon din!<br/>',NULL,42865,1);
INSERT INTO stanza VALUES('T1027','chorus','Halikayo! Mga pagod, halina!<br/>Taimtim na tumatawag si Hesus,<br/>Halikayo! Maysala!<br/>',NULL,42866,2);
INSERT INTO stanza VALUES('T1027','2','Sa atin si Hesus ay namamanhik—<br/>Bakit ka mag-antala?<br/>Bakit mag-atubili sa pag-ibig—<br/>Biyaya at habag Niya?<br/>',NULL,42867,3);
INSERT INTO stanza VALUES('T1027','3','Dagliang lumilipas ang panahon—<br/>Ika''y mapag-iwanan;<br/>Anino ng kamataya''y nagtipon—<br/>Baka ka maabutan!<br/>',NULL,42868,5);
INSERT INTO stanza VALUES('T1027','4','Kagila-gilalas ang pag-ibig Niya—<br/>Ipinangako sa iyo!<br/>Nagkasala ka nguni''t Siya''y may awa—<br/>At patawad nang buo!<br/>',NULL,42869,7);
INSERT INTO stanza VALUES('T1028','1','Hesus magiliw na tumatawag—<br/>Ngayon sa iyo''y tumatawag!<br/>Bakit lumalayo sa pag-ibig,<br/>Lumalayo nang higit?<br/>',NULL,42870,1);
INSERT INTO stanza VALUES('T1028','chorus','Ngayong sa iyo''y, tumatawag!<br/>Si Hesus ngayo''y magiliw na tumatawag!<br/>',NULL,42871,2);
INSERT INTO stanza VALUES('T1028','2','Sa pagod, si Hesus tumatawag,<br/>Ngayon sa iyo''y tumatawag!<br/>Kabigatan Mo sa Kanya''y dalhin,<br/>Di ka Niya bibiguin.<br/>',NULL,42872,3);
INSERT INTO stanza VALUES('T1028','3','Parito na, Hesus naghihintay!<br/>Ngayon Siya ay naghihintay!<br/>Kasalanan mo''y dalhin sa Kanya;<br/>Huwag kang mag-antala.<br/>',NULL,42873,5);
INSERT INTO stanza VALUES('T1028','4','Hesus sumasamo, pakinggan Siya!<br/>Ngayon nga''y pakinggan mo Siya!<br/>Magagalak sumampalataya<br/>Magmadali''t sumama!<br/>',NULL,42874,7);
INSERT INTO stanza VALUES('T1029','1','Tawag ni Hesus pakinggan,<br/>Ang mundong ito''y layuan.<br/>Mga araw lilipas ba,<br/>Kalul''wa ko himbing pa ba?<br/>',NULL,42875,1);
INSERT INTO stanza VALUES('T1029','chorus','Tumatawag pa Siya!<br/>Siya''y pakinggan nawa!<br/>Tumatawag si Kristo;<br/>Pakinggan nawa!<br/>Tumatawag pa Siya!<br/>Siya''y pakinggan nawa!<br/>Tumatawag si Kristo;<br/>Pakinggan nawa!<br/>',NULL,42876,2);
INSERT INTO stanza VALUES('T1029','2','Pagtawag Niya''y tugunin ba?<br/>Di-alintana tinig Niya?<br/>Di ko suklian buti Niya?<br/>Dapat pa bang mag-antala?<br/>',NULL,42877,3);
INSERT INTO stanza VALUES('T1029','3','Tumatawag, kumakatok,<br/>Puso''y ipinid ko kaya?<br/>Naghihintay Siya sa akin,<br/>Siya ba''y aking ''pighatiin?<br/>',NULL,42878,5);
INSERT INTO stanza VALUES('T1029','4','Si Kristo''y tumatawag pa.<br/>O, dapat ay dinggin ko Siya!<br/>Sa gapos ay nakalag na;<br/>Ako''y di-bibiguin Niya!<br/>',NULL,42879,7);
INSERT INTO stanza VALUES('T1029','5','Tinatawag nga Niya ako,<br/>Kanya itong aking puso.<br/>Kay Kristo magpakailanman,<br/>O, mundo kita''y iiwan.<br/>',NULL,42880,9);
INSERT INTO stanza VALUES('T1030','1','Salita Niya narinig ko,<br/>"Sundan, sundan, sundan mo Ako";<br/>Tinig Niya pinakinggan ko,<br/>"Sundan, sundan, sundan mo Ako";<br/>Dahil sa iyo inako Ko,<br/>Kasalanan hindi gawa Ko,<br/>Ininom Ko kapaitan,<br/>Buhay Ko''y naging kabayaran."<br/>',NULL,42881,1);
INSERT INTO stanza VALUES('T1030','2','"Iyong dusa''t sala''y batid Ko;<br/>Sundan, sundan, sundan mo Ako!<br/>Alam Ko sakit ng puso;<br/>Sundan, sundan, sundan mo Ako!<br/>Madalas kitang tawagin,<br/>At iyong sala''y patatawarin,<br/>Tinatawag kitang muli!<br/>Sundan mong walang pasubali!"<br/>',NULL,42882,2);
INSERT INTO stanza VALUES('T1030','3','"Pinatawad nang totoo:<br/>Sundan, sundan, sundan mo Ako!<br/>Lalaya ka sa sala mo;<br/>Sundan, sundan, sundan mo Ako!<br/>Sa nagbabagong buhay mo<br/>Akong Di-yos kaagapay mo,<br/>Ako''y iyong kaligayahan,<br/>Sundan mo nga magpakailanman!"<br/>',NULL,42883,3);
INSERT INTO stanza VALUES('T1030','4','"Iyong bigat sa ''Kin bitiwan;<br/>Sundan mo Ako, sundan, sundan!<br/>Bigat mo''y Aking pasanin;<br/>Sumunod, sumunod ka sa ''Kin!<br/>Pangamba mo''y mawawala;<br/>Basta''t sa Akin magtiwala;<br/>Luha mo''y ''King pupunasan;<br/>Basta''t Ako''y lagi mong sundan!"<br/>',NULL,42884,4);
INSERT INTO stanza VALUES('T1030','5','Sa Iyo susuko na ako;<br/>Susunod na ako sa I-yo!<br/>Nagpumiglas kong kalul''wa;<br/>Susunod ng may pakumbaba!<br/>Ako''y hugasan, linisin,<br/>Espiritu ako''y punuin;<br/>Nang matupad Salita Mo;<br/>Susunod, susunod na ako!<br/>',NULL,42885,5);
INSERT INTO stanza VALUES('T1031','1','Halina mga may sala,<br/>Ating Diyos may awa;<br/>Pahinga''y dudulutan ka,<br/>Tiwala''y Salita.<br/>',NULL,42886,1);
INSERT INTO stanza VALUES('T1031','chorus','Magtiwala lang sa Kanya!<br/>Magtiwala ka!<br/>Tiyak kang ililigtas Niya!<br/>Ililigtas ka!<br/>',NULL,42887,2);
INSERT INTO stanza VALUES('T1031','2','Dahil dugo Niya binubo<br/>Biyaya''y natamo;<br/>Lulusong sa bahang pula<br/>Hugasan ang sala.<br/>',NULL,42888,3);
INSERT INTO stanza VALUES('T1031','3','Hesus ang Katotohanan,<br/>Pahinga sa Daan;<br/>Tanggapin, di mag-antala,<br/>May pagpapala ka.<br/>',NULL,42889,5);
INSERT INTO stanza VALUES('T1031','4','Halina ngayon sumama,<br/>Patungo sa gloria;<br/>Panghawakan katubusan,<br/>Buti Niya''y malaman.<br/>',NULL,42890,7);
INSERT INTO stanza VALUES('T1032','1','Halina mga may sala,<br/>Maysakit, nanghihina;<br/>Magligtas Hesus ay handa,<br/>Punô ng sinta''t awa:<br/>Kayang-kaya, kaya nga Niya,<br/>Huwag magduda, nais Niya.<br/>',NULL,42891,1);
INSERT INTO stanza VALUES('T1032','2','May kulang at may kailangan;<br/>Tanggapin libreng yaman;<br/>Maniwala''t magsisi ka,<br/>Mabibigyang biyaya,<br/>Walang bayad, libreng-libre,<br/>Kay Kristo ka bumili.<br/>',NULL,42892,2);
INSERT INTO stanza VALUES('T1032','3','Huwag hayaan ang budhi mo,<br/>Magpaantala sa iyo;<br/>Kaangkupang Kanyang hiling,<br/>Siya''y iyong kailanganin:<br/>Ibibigay nga Niya sa Iyo,<br/>Sinag ng Espiritu.<br/>',NULL,42893,3);
INSERT INTO stanza VALUES('T1032','4','Halikayong mga pagod,<br/>Wasak sa pagkatisod;<br/>Kung magpapakabuti pa,<br/>Ang daratnan mo''y wala.<br/>Di ang mat''wid pinuntahan,<br/>Kundi makasalanan.<br/>',NULL,42894,4);
INSERT INTO stanza VALUES('T1032','5','Manunubos nanalangin,<br/>Namighati sa hardin;<br/>Sa duguang krus masdan Siya!<br/>Makinig sa sigaw Niya,<br/>"Natapos na!" "Natapos na!"<br/>Di ba ito''y sapat na?<br/>',NULL,42895,5);
INSERT INTO stanza VALUES('T1032','6','Umakyat Diyos naging laman,<br/>Bisa ng dugo''y tangan;<br/>Asahan Siya nang lubusan;<br/>Hu-wag mag-alinlangan:<br/>Hesus lamang maasahan,<br/>Gawan kang kabutihan.<br/>',NULL,42896,6);
INSERT INTO stanza VALUES('T1033','1','Sa sala''y mga nabibigatan,<br/>Dumulog lamang;<br/>Simulan ang bagong buhay ngayon,<br/>O, dumulog lamang.<br/>',NULL,42897,1);
INSERT INTO stanza VALUES('T1033','chorus','Dumulog lamang,<br/>O, dumulog lamang;<br/>Sala''y bitiwan, at papasukin,<br/>Hesus iyong tanggapin.<br/>',NULL,42898,2);
INSERT INTO stanza VALUES('T1033','2','Iyong puso sa sala''y napilatan,<br/>Dumulog lamang;<br/>Kahit ang Ama iyong nilayuan,<br/>O, dumulog lamang.<br/>',NULL,42899,3);
INSERT INTO stanza VALUES('T1033','3','Sinusumbatan, puso''y nasaktan,<br/>Dumulog lamang;<br/>Isiping tinubos sa Kalbaryo,<br/>O, dumulog lamang.<br/>',NULL,42900,5);
INSERT INTO stanza VALUES('T1033','4','Kasiyahan ng Diyos di makamtan,<br/>Dumulog lamang;<br/>Magtiwala sa dugong binubo,<br/>O, dumulog lamang.<br/>',NULL,42901,7);
INSERT INTO stanza VALUES('T1033','5','Dalhin iyong dusa''t kapighatian,<br/>Dumulog lamang;<br/>Manliligtas handa kang tanggapin,<br/>O, dumulog lamang.<br/>',NULL,42902,9);
INSERT INTO stanza VALUES('T1034','1','Sumigaw ang "sinumang makarinig!"<br/>Dalhin balita sa buong daigdig;<br/>Ang ebanghelyo sa tao''y ihatid:<br/>"Lumapit ang may ibig!"<br/>',NULL,42903,1);
INSERT INTO stanza VALUES('T1034','chorus','"Sinumang tao ang nagnanais!"<br/>Magpahayag sa bundok at dalisdis;<br/>Tumatawag ang Amang umiibig:<br/>"Lumapit ang may ibig!"<br/>',NULL,42904,2);
INSERT INTO stanza VALUES('T1034','2','"Ang lumalapit" ay huwag nang mabalam,<br/>Magmaagap, bukas pa ang pintuan;<br/>Si Hesus ang tunay, Buhay na Daan:<br/>"Lumapit ang may ibig!"<br/>',NULL,42905,3);
INSERT INTO stanza VALUES('T1034','3','"Ang may ibig!", pangako''y nakahanda;<br/>"Ang may ibig!" ay kailangang magbata;<br/>"Ang may ibig", buhay na ''di hahangga;<br/>"Lumapit ang may ibig."<br/>',NULL,42906,5);
INSERT INTO stanza VALUES('T1036','1','Kay Hesus tumingin ka,<br/>Tingnan Siya''t mabuhay!<br/>Tingnan Kanyang ginawa,<br/>Mabuhay!<br/>Itinaas sa puno,<br/>Tingnan Siya''t mabuhay!<br/>Pakinggan, "Tingnan Ako!"<br/>Mabuhay!<br/>',NULL,42907,1);
INSERT INTO stanza VALUES('T1036','chorus','Poon itinaas na,<br/>Nang mabuhay tingnan Siya;<br/>Ba''t kailangang mamatay?<br/>Mabuhay!<br/>',NULL,42908,2);
INSERT INTO stanza VALUES('T1036','2','Masama ka''t marumi,<br/>Tingnan Siya''t mabuhay!<br/>Huwag tingnan ang sarili,<br/>Mabuhay!<br/>Sa diyablo''y naalipin,<br/>Tingnan Siya''t mabuhay!<br/>Maligtas sa pagtingin,<br/>Mabuhay!<br/>',NULL,42909,3);
INSERT INTO stanza VALUES('T1036','3','Malaong gumala ka,<br/>Tingnan Siya''t mabuhay!<br/>Puso palambutin na,<br/>Mabuhay!<br/>Ama''y tinatawag ka,<br/>Tingnan Siya''t mabuhay!<br/>Bakit ka mag-antala?<br/>Mabuhay!<br/>',NULL,42910,5);
INSERT INTO stanza VALUES('T1037','1','"Iskarlata man sala,<br/>Simputi ng niebe na;<br/>Iskarlata man sala,<br/>Simputi ng niebe na;<br/>Salang napakapula,<br/>Kagaya''y lana;"<br/>"Iskarlata man sala,<br/>Simputi ng niebe na;<br/>Iskarlata man sala,<br/>Simputi ng niebe na."<br/>',NULL,42911,1);
INSERT INTO stanza VALUES('T1037','2','Tinig Niya''y nagsumamo,<br/>Bumalik ka sa Diyos mo!<br/>Tinig Niya''y nagsumamo,<br/>Bumalik ka sa Diyos mo!<br/>Anong kamangha-mangha,<br/>Pag-ibig, awa;<br/>Sumasamo tinig Niya,<br/>Sumasamo tinig Niya,<br/>Bumalik ka sa iyong Diyos!<br/>Bumalik ka sa iyong Diyos!<br/>',NULL,42912,2);
INSERT INTO stanza VALUES('T1037','3','Sala''y patatawarin,<br/>Di na gugunitain;<br/>Sala''y patatawarin,<br/>Di na gugunitain;<br/>"Sa ''Kin tumingin kayo,"<br/>Sabi ng Diyos n''yo!<br/>Sala''y patatawarin,<br/>Di na gugunitain,<br/>Kanya ngang lilimutin,<br/>Di na gugunitain.<br/>',NULL,42913,3);
INSERT INTO stanza VALUES('T1038','1','Kung pagod ka sa bigat ng sala,<br/>Papasukin mo si Hesus;<br/>Kung nais mo ng bagong simula,<br/>Papasukin mo si Hesus.<br/>',NULL,42914,1);
INSERT INTO stanza VALUES('T1038','chorus','Pangamba ay iyong iwan;<br/>Huwag mo na Siyang tanggihan;<br/>Pintuan ay iyong buksan;<br/>Papasukin mo si Hesus.<br/>',NULL,42915,2);
INSERT INTO stanza VALUES('T1038','2','Kung kadalisayan ang iyong nais,<br/>Papasukin mo si Hesus;<br/>May mga batis na maglilinis,<br/>Papasukin mo si Hesus.<br/>',NULL,42916,3);
INSERT INTO stanza VALUES('T1038','3','Kung silakbo''y nais mong pigilan,<br/>Papasukin mo si Hesus;<br/>Kung kahungkaga''y nais mong lamnan,<br/>Papasukin mo si Hesus.<br/>',NULL,42917,5);
INSERT INTO stanza VALUES('T1043','1','Buhay ay isang iglap,<br/>Tulad ng mga ulap,<br/>Sindali ng pangarap,<br/>Agapan!<br/>Panaho''y lumilipas,<br/>Buhay ay nagwawakas,<br/>Pagdaka''y pahimakas,<br/>Agapan!<br/>',NULL,42918,1);
INSERT INTO stanza VALUES('T1043','chorus','Agapan! Agapan!<br/>Tawag ka ni Hesus, iyong agapan,<br/>Kung mabalam sa sala,<br/>Baka mapagsarhan ka,<br/>At tawag mo''y huli na,<br/>Agapan!<br/>',NULL,42919,2);
INSERT INTO stanza VALUES('T1043','2','O pantas, tingnan mo nga,<br/>Bulaklak nalalanta,<br/>Kabataa''y tatanda,<br/>Agapan!<br/>Magtuos nang maaga,<br/>Baka maabutan ka—<br/>Walang hanggang parusa,<br/>Agapan!<br/>',NULL,42920,3);
INSERT INTO stanza VALUES('T1043','3','Ang Espiritu Santo,<br/>Nagsusumamo sa iyo,<br/>Nang buhay matanggap mo,<br/>Agapan!<br/>Tanggapin biyaya Niya,<br/>Nang di mapahamak ka,<br/>Mag-atubili''y huwag na,<br/>Agapan!<br/>',NULL,42921,5);
INSERT INTO stanza VALUES('T1043','4','Pakinggan mo, salarin,<br/>Manliligtas piliin,<br/>Langit magagalak din,<br/>Agapan!<br/>Ang liwanag tunguhin,<br/>Panginoon tanggapin,<br/>Lumapit ka ngayon din,<br/>Agapan!<br/>',NULL,42922,7);
INSERT INTO stanza VALUES('T1044','1','Nakahanda ka na ba,<br/>Makaharap ang Diyos nga?<br/>Nakahanda ka na ba,<br/>Makaharap Siya?<br/>Handa ka ba, handa ka bang,<br/>Makaharap Siya?<br/>',NULL,42923,1);
INSERT INTO stanza VALUES('T1047','1','Walang hanggan! Walang hanggan!<br/>Paano mo gugugulin?<br/>Katanungan sa iyo''t akin!<br/>Paano mo gugugulin?<br/>Kasagutan mo''y sabihin—<br/>Paano mo gugugulin?<br/>',NULL,42924,1);
INSERT INTO stanza VALUES('T1047','2','Walang hanggan! Walang hanggan!<br/>Paano mo gugugulin?<br/>Dapat si Kristo piliin,<br/>Sa sala''y palalayain;<br/>Kristo kanilang bahagi:<br/>Walang hanggan tatamuhin?<br/>',NULL,42925,2);
INSERT INTO stanza VALUES('T1047','3','Walang hanggan! Walang hanggan!<br/>Paano mo gugugulin?<br/>Pintong biyaya pasukin,<br/>Nang sarili''y di sisihin,<br/>Ngayo''y masusing isipin—<br/>Walang hanggan gugugulin?<br/>',NULL,42926,3);
INSERT INTO stanza VALUES('T1047','4','Walang hanggan, walang hanggan,<br/>Paano mo gugugulin?<br/>Manalig sa Panginoon,<br/>Maligtas sa kondenasyon:<br/>Magkaroong katiyakan,<br/>Walang hanggang kaligtasan!<br/>',NULL,42927,4);
INSERT INTO stanza VALUES('T1048','1','Ako''y lumalapit sa Iyo,<br/>Pag-asa''y dugong binubo,<br/>At nang ako''y tinawag Mo,<br/>Lumalapit, O Kordero!<br/>',NULL,42928,1);
INSERT INTO stanza VALUES('T1048','2','Ako sa Iyo''y lumalapit,<br/>Di na maghintay malinis;<br/>''Pagkat sapat ang Iyong dugo,<br/>Lumalapit, O Kordero!<br/>',NULL,42929,2);
INSERT INTO stanza VALUES('T1048','3','Ako''y lumalapit sa Iyo<br/>Bagama''t maraming gulo;<br/>Sa loob, labas takot ko,<br/>Lumalapit, O Kordero!<br/>',NULL,42930,3);
INSERT INTO stanza VALUES('T1048','4','Ako''y lumalapit sa Iyo<br/>Dukha, aba''t bulag ako;<br/>Kailangan ko''y nasa I-yo,<br/>Lumalapit, O Kordero!<br/>',NULL,42931,4);
INSERT INTO stanza VALUES('T1048','5','Ako''y lumalapit sa Iyo,<br/>Anuman ako''y tanggap Mo;<br/>Pinatawad, nilinis Mo,<br/>Lumalapit, O Kordero!<br/>',NULL,42932,5);
INSERT INTO stanza VALUES('T1048','6','Ako''y sa Iyo lumalapit<br/>Sa di batid na pag-ibig;<br/>Hadlang lubos inalis Mo,<br/>Lumalapit, O Kordero!<br/>',NULL,42933,6);
INSERT INTO stanza VALUES('T1050','1','Mula sa gapos, dilim, panglaw,<br/>Hesus, lumalapit ako!<br/>Tungo sa laya, galak, ilaw,<br/>Hesus ako''y sa Iyo!<br/>Ang sakit naging kalusugan,<br/>Kawalan naging kayamanan,<br/>Tungo sa Iyo''y may kaligtasan,<br/>Hesus, ako''y sa Iyo!<br/>',NULL,42934,1);
INSERT INTO stanza VALUES('T1050','2','Mula sa aking pagkabigo,<br/>Hesus, lumalapit ako!<br/>Tungo sa l''walhating Iyong ''tamo,<br/>Hesus ako''y sa Iyo!<br/>Walang lumbay, may pag-aliw Mo,<br/>Bumagyo man, payapa sa Iyo,<br/>Walang hapis, kundi may salmo,<br/>Hesus, ako''y sa Iyo!<br/>',NULL,42935,2);
INSERT INTO stanza VALUES('T1050','3','Mula sa ''king kapalaluan,<br/>Hesus lumalapit ako!<br/>Tungong maypalang kalooban,<br/>Hesus, ako''y sa Iyo!<br/>Sa pag-ibig Mo''y nananahan,<br/>Pagbalik Mo''y inaasahan,<br/>Wari''y ibong pumailanglang,<br/>Hesus, ako''y sa Iyo!<br/>',NULL,42936,3);
INSERT INTO stanza VALUES('T1050','4','Mula sa takot ng libingan,<br/>Hesus lumalapit ako!<br/>Tungo sa buhay walang hanggan,<br/>Hesus, ako''y sa Iyo!<br/>Ligtas na sa kapinsalaan,<br/>At dinala ako sa kawan,<br/>Mukha Mo''y lagi kong mamasdan,<br/>Hesus, ako''y sa Iyo!<br/>',NULL,42937,4);
INSERT INTO stanza VALUES('T1051','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42938,1);
INSERT INTO stanza VALUES('T1051','1','Anyaya''y narinig—<br/>Ikaw ay tanggapin<br/>Yamang dugo Mo''y nabuhos,<br/>Budhi ko''y linisin.<br/>',NULL,42939,2);
INSERT INTO stanza VALUES('T1051','chorus','Panginoon ko,<br/>Lalapit sa Iyo.<br/>Linisin sa dugo Mo<br/>Buhos sa Kalbaryo.<br/>',NULL,42940,3);
INSERT INTO stanza VALUES('T1051','2','Ako nga''y marumi<br/>Walang kabutihan;<br/>Sa Iyong biyaya at tulong<br/>Sala''y nahugasan.<br/>',NULL,42941,4);
INSERT INTO stanza VALUES('T1051','3','Atas Mong taimtim—<br/>Sala ko''y lisanin,<br/>Magsisi, sa Iyo''y manalig,<br/>Ikaw ay tanggapin.<br/>',NULL,42942,6);
INSERT INTO stanza VALUES('T1051','4','Bigkas Mo''y biyaya,<br/>Espiritu''y ilaw,<br/>Nang kahinaan ko''y lantad;<br/>Sandigan ko''y Ikaw.<br/>',NULL,42943,8);
INSERT INTO stanza VALUES('T1051','5','Espiritu''y taglay,<br/>Kaya''t buhay akin;<br/>Pangako ng Diyos natupad,<br/>Nang Ika''y tanggapin.<br/>',NULL,42944,10);
INSERT INTO stanza VALUES('T1051','6','Ang Diyos ay pag-ibig!<br/>Siya ang kaligtasan!<br/>Dugo ni Hesus — pantubos!<br/>Lahat ko ay laan.<br/>',NULL,42945,12);
INSERT INTO stanza VALUES('T1052','1','Ako ay lumayo sa Diyos,<br/>Pauwi na ''ko;<br/>Sa kasalanan ay gapos,<br/>Pauwi na ''ko.<br/>',NULL,42946,1);
INSERT INTO stanza VALUES('T1052','chorus','Ako''y pauwi na,<br/>Di na gagala;<br/>Tawag ng pag-ibig Mo,<br/>Pauwi na ''ko.<br/>',NULL,42947,2);
INSERT INTO stanza VALUES('T1052','2','Maraming taon naaksaya,<br/><!--Correction: Should be "naaksaya"--> Pauwi na ''ko;<br/>Nagsisisi''t lumuluha,<br/>Pauwi na ''ko.<br/>',NULL,42948,3);
INSERT INTO stanza VALUES('T1052','3','Sa kasalana''y bagot na<br/>Pauwi na ''ko;<br/>Pag-ibig Mo at salita<br/>Panghawakan ko.<br/>',NULL,42949,5);
INSERT INTO stanza VALUES('T1052','4','Puso''t kalul''wa''y mahapdi,<br/>Pauwi na ''ko;<br/>Pag-asa''t lakas mabawi<br/>Sa pag-uwi ko.<br/>',NULL,42950,7);
INSERT INTO stanza VALUES('T1052','5','Tanging pag-asa at samo,<br/>Pauwi na ''ko;<br/>Hesus namatay, nagdugo,<br/>Pauwi na ''ko.<br/>',NULL,42951,9);
INSERT INTO stanza VALUES('T1052','6','Kailangan ko Kanyang dugo,<br/>Pauwi na ''ko;<br/>Lubos na hugasan ako,<br/>Pauwi na ''ko.<br/>',NULL,42952,11);
INSERT INTO stanza VALUES('T1054','1','Poon, huwag akong lampasan,<br/>Samo''y pakinggan;<br/>Kung iba''y Iyong tinatawag,<br/>Hu-wag lampasan.<br/>',NULL,42953,1);
INSERT INTO stanza VALUES('T1054','chorus','Manliligtas,<br/>Samo''y pakinggan;<br/>Kung iba''y Iyong tinatawag,<br/>Hu-wag lampasan.<br/>',NULL,42954,2);
INSERT INTO stanza VALUES('T1054','2','Sa luklukan ng Iyong awa,<br/>Kamtan ginhawa;<br/>Nakaluhod, nagsisisi,<br/>Sa aking sala.<br/>',NULL,42955,3);
INSERT INTO stanza VALUES('T1054','3','Sa galing Mo''y nagtiwala,<br/>Hahanapin Ka;<br/>''Spiritung bagbag lunasan<br/>Ng Iyong biyaya.<br/>',NULL,42956,5);
INSERT INTO stanza VALUES('T1054','4','Ika''y batis ng ginhawa,<br/>Sa ''kin buhay ka;<br/>Liban sa Iyo ay wala na,<br/>Dito sa lupa.<br/>',NULL,42957,7);
INSERT INTO stanza VALUES('T1057','1','Mangingibig kong Hesus,<br/>Sa Iyo ''ko''y lumalapit,<br/>''Pagka''t alon at unos,<br/>Sa ''kin ay sumasapit:<br/>Ako ay Iyong ikubli,<br/>Hanggang bagyo''y lumipas;<br/>Igabay akong muli,<br/>Tanggapin akong ligtas.<br/>',NULL,42958,1);
INSERT INTO stanza VALUES('T1057','2','Tanging kanlungan Kita,<br/>Nakahawak lang sa Iyo;<br/>Huwag Mong iwang mag-isa,<br/>Tukuran, aliwin Mo.<br/>Sa Iyo''y nagtitiwala,<br/>Tulong Mo ay dadalhin;<br/>Bigyang sanggalang nawa<br/>Sa magiliw Mong lilim.<br/>',NULL,42959,2);
INSERT INTO stanza VALUES('T1057','3','Tangi Kang nilalayon;<br/>Kaysa lahat ng bagay;<br/>Natisod Iyong ibangon,<br/>Bulag ay Iyong igabay.<br/>Ngalan Mo''y tapat, banal,<br/>Ako ay kalikuan,<br/>Ako''y karumal-dumal,<br/>Ika''y katotohanan.<br/>',NULL,42960,3);
INSERT INTO stanza VALUES('T1057','4','Biyaya Mo ay sapat,<br/>Sinakop ang sala ko;<br/>Paapawin ang lunas;<br/>Gawin Mong wagas ako.<br/>Batis Ka ng buhay ko,<br/>Ika''y aking makamtan;<br/>Sumibol Ka sa puso,<br/>Hanggang sa walang hanggan.<br/>',NULL,42961,4);
INSERT INTO stanza VALUES('T1058','1','O Batong Walang hanggan,<br/>Sa I-yong tagiliran<br/>Dugo''t tubig dumanak,<br/>Di na ''ko mapahamak,<br/>Sa lumang likha''y ligtas,<br/>Sa sala''y dobleng lunas.<br/>',NULL,42962,1);
INSERT INTO stanza VALUES('T1058','2','Kahit ano pang gawin,<br/>Utos di kayang tupdin;<br/>Ni ng pusong maningas<br/>Ni ng luhang madalas,<br/>Sala''y di malulutas<br/>Liban sa Iyong pagligtas.<br/>',NULL,42963,2);
INSERT INTO stanza VALUES('T1058','3','Kamay kong walang laman<br/>Tanging sa krus tatangan;<br/>Damtan Mo''ng kahubaran,<br/>Dukha''y Iyong kahabagan,<br/>Marumi''y Iyong hugasan,<br/>Sa Iyo lang — kaligtasan.<br/>',NULL,42964,3);
INSERT INTO stanza VALUES('T1058','4','Kung ako''y lilisan na,<br/>Pipikit na ang mata,<br/>Palapit walang hanggan,<br/>Haharap sa luklukan,<br/>O Batong walang hanggan,<br/>Ika''y aking kanlungan.<br/>',NULL,42965,4);
INSERT INTO stanza VALUES('T1059','1','Sa krus ako''y idulog,<br/>Nang mapagaling Mo,<br/>Naglulunas na daloy,<br/>Galing sa Kalbaryo.<br/>',NULL,42966,1);
INSERT INTO stanza VALUES('T1059','chorus','Nasa krus, nasa krus,<br/>Ang luwalhati ko;<br/>Di na mahihiwalay<br/>Krus sa kalul''wa ko.<br/>',NULL,42967,2);
INSERT INTO stanza VALUES('T1059','2','Sa Iyong krus nakatamo,<br/>Pag-ibig at awa;<br/>Sa aki''y sininag Mo<br/>Ningning ng Iyong tala.<br/>',NULL,42968,3);
INSERT INTO stanza VALUES('T1059','3','Ako''y dalhin sa tagpo<br/>Ng Iyong pagkapako!<br/>Tulungan ang lakad ko<br/>Sa lilim ng krus Mo.<br/>',NULL,42969,5);
INSERT INTO stanza VALUES('T1059','4','Malapit sa krus, ako<br/>Sa Iyo''y maghihintay,<br/>Nang makita''ng mukha Mo,<br/>Di muling mawalay.<br/>',NULL,42970,7);
INSERT INTO stanza VALUES('T1060','1','Ang trono at putong iniwan Mo<br/>Para sa ''kin pumarito;<br/>Sa bahay sa Betlehem walang kuwarto<br/>Sa banal na pagsilang Mo.<br/>',NULL,42971,1);
INSERT INTO stanza VALUES('T1060','chorus','Sa puso ko, Poong Hesus!<br/>May puwang para sa I-yo.<br/>O, pumasok Ka, Poong Hesus,<br/>Puso ko''y may puwang sa Iyo.<br/>',NULL,42972,2);
INSERT INTO stanza VALUES('T1060','2','Alingawngaw tinig makalangit<br/>Maharlikang taas banggit;<br/>Iyong pagsilang gayunma''y pakumbaba,<br/>Pagdating Mo sa lupa.<br/>',NULL,42973,3);
INSERT INTO stanza VALUES('T1060','chorus','Sa puso ko, Poong Hesus!<br/>May puwang para sa I-yo.<br/>O, pumasok Ka, Poong Hesus,<br/>Puso ko''y may puwang sa Iyo.<br/>',NULL,42974,4);
INSERT INTO stanza VALUES('T1060','3','Sorra''t ibon may pahinga''t pugad<br/>Sa kakahuyang malapad;<br/>O Ikaw Anak ng Diyos, Iyong higaan:<br/>Ilang ng Galilea lang.<br/>',NULL,42975,5);
INSERT INTO stanza VALUES('T1060','chorus','Sa puso ko, Poong Hesus!<br/>May puwang para sa I-yo.<br/>O, pumasok Ka, Poong Hesus,<br/>Puso ko''y may puwang sa Iyo.<br/>',NULL,42976,6);
INSERT INTO stanza VALUES('T1060','4','Dala Mo ang buhay na Salita<br/>Sa tao''y magpalaya;<br/>Nguni''t Ika''y hinamak, kinutya,<br/>At sa krus ''pinako Ka.<br/>',NULL,42977,7);
INSERT INTO stanza VALUES('T1060','chorus','Sa puso ko, Poong Hesus!<br/>Krus Mo ang tanging samo ko;<br/>Halina sa puso ko, Hesus,<br/>Krus Mo ang tanging samo ko.<br/>',NULL,42978,8);
INSERT INTO stanza VALUES('T1060','5','Makalangit tutugtog, koro''y aawit,<br/>Pag tagumpay Mo''y sumapit;<br/>Tinig Mo tawagin ako: "May puwang dito<br/>May puwang Ako sa i-yo."<br/>',NULL,42979,9);
INSERT INTO stanza VALUES('T1060','chorus','Puso ko''y magagalak, Hesus!<br/>Pagdating Mo''t tawagin ako;<br/>Puso ko''y magagalak, Hesus!<br/>Pagdating Mo''t tawagin ako.<br/>',NULL,42980,10);
INSERT INTO stanza VALUES('T1064','1','Ibig kong magsalaysay,<br/>Panglangit na bagay,<br/>Hesus, tamis ng tinig,<br/>L''walhati''t pag-ibig.<br/>Ibig kong magsalaysay,<br/>Alam ko Siya''y tunay,<br/>Nagbigay kasiyahan,<br/>Hindi Siya mahigtan.<br/>',NULL,42981,1);
INSERT INTO stanza VALUES('T1064','chorus','Ibig kong magsalaysay,<br/>Paksang hanggang l''walhati,<br/>Ang kasaysayang dati:<br/>Hesus at pag-ibig.<br/>',NULL,42982,2);
INSERT INTO stanza VALUES('T1064','2','Ibig kong magsalaysay,<br/>Tila mas mahusay<br/>Kaysa mga pangarap<br/>At aking pagsikap;<br/>Ibig kong magsalaysay,<br/>Lahat na ''binigay,<br/>Ito nga ang dahilan<br/>Ika''y bahaginan.<br/>',NULL,42983,3);
INSERT INTO stanza VALUES('T1064','3','Ibig kong magsalaysay,<br/>Nakaiigaya,<br/>Pag lalong sinasambit,<br/>Katamisan higit.<br/>Sa mga walang malay,<br/>Ibig kong isaysay,<br/>Ang kaligtasang lubos<br/>Sa Salita ng Diyos.<br/>',NULL,42984,5);
INSERT INTO stanza VALUES('T1064','4','Ibig kong magsalaysay,<br/>Pagka''t mga banal ay<br/>Sabik makabalita<br/>Tulad din ng iba.<br/>Pagdating sa l''walhati,<br/>Kasaysayang dati<br/>Na pinakaiibig<br/>Ang bago kong awit.<br/>',NULL,42985,7);
INSERT INTO stanza VALUES('T1065','1','Dakilang kaligtasan!<br/>Dakilang kaligtasan!<br/>Dakilang kaligtasan!<br/>Hesus nagligtas!<br/>',NULL,42986,1);
INSERT INTO stanza VALUES('T1065','chorus','Kinalas bawa''t gapos!<br/>Kinalas bawa''t gapos!<br/>Kinalas bawa''t gapos!<br/>Siyang nagpalaya!<br/>',NULL,42987,2);
INSERT INTO stanza VALUES('T1065','2','Sala ko''y pinatawad!<br/>Mga gapos kinalas!<br/>Puso ko''y mapayapa!<br/>Hesus nagligtas!<br/>',NULL,42988,3);
INSERT INTO stanza VALUES('T1065','3','Ni sala man o tukso,<br/>Ni pangyamot ng Diyablo,<br/>Ni pang-akit ng mundo,<br/>Sa ''kin gugupo!<br/>',NULL,42989,5);
INSERT INTO stanza VALUES('T1065','4','Aawit Aleluya!<br/>Aawit Aleluya!<br/>Aawit Aleluya!<br/>Ako''y naligtas!<br/>',NULL,42990,7);
INSERT INTO stanza VALUES('T1066','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,42991,1);
INSERT INTO stanza VALUES('T1066','1','Namatay nga si Hesus sa krus,<br/>Dugo Niya sa sala''y pantubos,<br/>Ako''y nilinisan Niyang lubos;<br/>Siya ay purihin!<br/>',NULL,42992,2);
INSERT INTO stanza VALUES('T1066','chorus','Siya ay purihin,<br/>Siya ay purihin;<br/>Dugong mahal ako''y nilinis;<br/>Siya ay purihin!<br/>',NULL,42993,3);
INSERT INTO stanza VALUES('T1066','2','Sa krus handog Niya ay biyaya,<br/>Mga sala ko''y nilinis Niya;<br/>O, paglinis, kahanga-hanga;<br/>Siya ay purihin.<br/>',NULL,42994,4);
INSERT INTO stanza VALUES('T1066','3','Siya ay bukal na nagliligtas,<br/>Sa Kanya ay di na lalabas;<br/>Dito''y nalilinis at ligtas;<br/>Siya ay purihin.<br/>',NULL,42995,6);
INSERT INTO stanza VALUES('T1066','4','Sa bukal kay tamis, parito;<br/>Lapit kalul''wang may siphayo;<br/>Sumisid ka nang makumpleto;<br/>Siya ay purihin.<br/>',NULL,42996,8);
INSERT INTO stanza VALUES('T1067','1','May Isang kusang namatay para sa ''kin,<br/>Upang buhay aking maangkin,<br/>Landas tungo sa krus tinahak Niyang kusa,<br/>Nang mapatawad aking sala.<br/>',NULL,42997,1);
INSERT INTO stanza VALUES('T1067','chorus','Sala ko''y pinasan,<br/>Sala ko''y pinasan,<br/>O gaano''ng Kanyang pinasan!<br/>Anong lugi''t dusa,<br/>Sa krus Siya''y nagpunta!<br/>Dinala Niya ro''n aking sala!<br/>',NULL,42998,2);
INSERT INTO stanza VALUES('T1067','2','Magiliw Siya''t mapagmahal, matiyaga,<br/>Nang puso ko''y nililinis Niya;<br/>Walang paghatol na, ako''y malaya na,<br/>''Pagka''t sa krus sala''y dinala.<br/>',NULL,42999,3);
INSERT INTO stanza VALUES('T1067','3','Kakapit ako sa Tagapagligtas ko,<br/>Hindi na sa Kanya lalayo—<br/>Puso ko''t labi aawit nang masaya,<br/>Inalis na lahat kong sala!<br/>',NULL,43000,5);
INSERT INTO stanza VALUES('T1068','1','Hinanap sa paggiliw,<br/>Akong walang aliw,<br/>Pagal, may kasalanan,<br/>Inuwi sa kawan.<br/>Habang sa Kanyang harapan<br/>Mga anghel nag-awitan.<br/>',NULL,43001,1);
INSERT INTO stanza VALUES('T1068','chorus','O pag-ibig sa ''kin,<br/>Humanap, umangkin!<br/>O dugong dulot katubusan,<br/>Biyayang nag-uwi sa kawan!<br/>',NULL,43002,2);
INSERT INTO stanza VALUES('T1068','2','Sugat ng kasalanan,<br/>Kanyang hinugasan;<br/>Langis, alak, ''binuhos,<br/>Nang gumaling lubos,<br/>Kanyang tinig na kay tamis<br/>Lunas sa puso kong hapis.<br/>',NULL,43003,3);
INSERT INTO stanza VALUES('T1068','3','Bakas ng pagkapako,<br/>Sa aki''y ''tinuro;<br/>Ang may tinik na putong,<br/>Sa Kanya''y ''pinatong;<br/>Bakit nagdanas ng dusa,<br/>Dahil sa akin na aba?<br/>',NULL,43004,5);
INSERT INTO stanza VALUES('T1068','4','Nang sa Kanyang presensya,<br/>Pinagmasdan ko Siya,<br/>At Kanyang pagpapala<br/>Aking ginunita.<br/>Di sapat ang mga araw<br/>Upang papuri''y isigaw.<br/>',NULL,43005,7);
INSERT INTO stanza VALUES('T1068','5','Habang ang mga oras<br/>Ay nagsisilipas,<br/>Iisa lang na bagay<br/>Aking hinihintay;<br/>Na sa tabi Niya''y tawagin,<br/>Kasintahan Niyang kapiling.<br/>',NULL,43006,9);
INSERT INTO stanza VALUES('T1069','1','Tinapay ng buhay ka''nin,<br/>Bukal ng tubig inumin;<br/>Ang sinumang umiinom,<br/>Hindi muling mauuhaw.<br/>',NULL,43007,1);
INSERT INTO stanza VALUES('T1069','2','Di ba mauuhaw?<br/>Di nga mauuhaw!<br/>Di ba mauuhaw?<br/>Sinabi ni Hesus,<br/>Ang sinumang umiinom<br/>Hindi muling mauuhaw.<br/>',NULL,43008,2);
INSERT INTO stanza VALUES('T1070','1','Lumulubog sa sala,<br/>Sa laot ng dagat,<br/>Nadungisan nang lubha,<br/>Di makakaangat;<br/>Nguni''t ang Panginoon<br/>Hibik ko''y dininig,<br/>At ako ay inahon<br/>Ng pag-ibig!<br/>',NULL,43009,1);
INSERT INTO stanza VALUES('T1070','chorus','Pag-ibig Niya<br/>ang nagligtas!<br/>Nang walang pag-asa,<br/>itinaas!<br/>Pag-ibig Niya<br/>ang nagligtas!<br/>Sa pang-mundong buhay<br/>iniligtas!<br/>',NULL,43010,2);
INSERT INTO stanza VALUES('T1070','2','Puso ko''y ibibigay,<br/>Sa Kanya tumangan,<br/>Magpuri at mamuhay<br/>Sa Kanyang harapan.<br/>Nararapat purihin<br/>Pag-ibig Niyang tapat,<br/>Paglilingkod ko''y kunin<br/>Lahat-lahat.<br/>',NULL,43011,3);
INSERT INTO stanza VALUES('T1070','3','Kalul''wang nanganganib,<br/>Kay Hesus tumingin;<br/>Sa dagat na nagngalit,<br/>Pag-ibig sasagip.<br/>Mga alon sa dagat<br/>Susunod sa Kanya;<br/>Manliligtas ibig Niya—<br/>Iligtas ka.<br/>',NULL,43012,5);
INSERT INTO stanza VALUES('T1074','1','Kaisa ko Tagapagligtas,<br/>Kay hiwaga!<br/>Kamangha-manghang kaligtasan<br/>Binigay Anak Niya!<br/>Aleluya! Aleluya!<br/>Anong hiwaga!<br/>Walang makapaghihiwalay<br/>Hesus at sa ''kin nga.<br/>',NULL,43013,1);
INSERT INTO stanza VALUES('T1079','1','Kung mundo''y matamo''t walang Kristo,<br/>Sulit bang mamuhay nang minsan?<br/>Aliw at pahinga sa puso ko<br/>Sa mundo kaya matagpuan?<br/>Kung mundo''y matamo''t walang Kristo,<br/>Sulit bang pinagsikapan mo?<br/>Maihambing bang layaw ng mundo<br/>Sansaglit na punô ng Kristo?<br/>',NULL,43014,1);
INSERT INTO stanza VALUES('T1079','2','Kung puspos ng pag-ibig at yaman,<br/>Iginagalang ang pangalan,<br/>Nguni''t walang asa''t panganlungan,<br/>Pag nabagbag sa bagyo''t ulan;<br/>Kung mundo''y matamo''t walang Kristo,<br/>Siyang nagdusa sa krus, namatay,<br/>Saan ako tatakbo sa mundo,<br/>Nang sumilong sa aking lumbay?<br/>',NULL,43015,2);
INSERT INTO stanza VALUES('T1079','3','O kahungkagan! — kung walang Kristo<br/>Sa kasalanan ko at hirap!<br/>Kawalang-hanggan, kung walang Kristo,<br/>Madilim, malungkot, masaklap!<br/>Kahit walang Kristo kung nabuhay,<br/>Paano naman pag namatay?<br/>Sa kamatayan, walang alalay!<br/>Walang hanggan ang paghiwalay!<br/>',NULL,43016,3);
INSERT INTO stanza VALUES('T1079','4','Kay galak, mataglay ko si Kristo!<br/>Siyang gamot sa nasawing puso!<br/>Pinatawad ang kasalanan ko,<br/>At lungkot ko''y Kanyang inako!<br/>Kung ako''y may Kristo, Kristo lamang,<br/>At walang iba pa sa mundo—<br/>Sagot Niya ang lahat ng kailangan;<br/>Akin ang lahat na kay Kristo.<br/>',NULL,43017,4);
INSERT INTO stanza VALUES('T1080','1','Gawa ba''y may pakinabang?<br/>Mga bagay walang bago!<br/>Lilipas, malilimutan,<br/>At pawang bigo!<br/>',NULL,43018,1);
INSERT INTO stanza VALUES('T1080','chorus','Walang kabuluhan!<br/>Pawang pagkabigo!<br/>Hinahabol ang<br/>Hangi''t anino.<br/>',NULL,43019,2);
INSERT INTO stanza VALUES('T1080','2','Buhay ng tao''y pighati:<br/>Karununga''y kapanglawan!<br/>Kaalama''y dalamhati,<br/>At kabiguan!<br/>',NULL,43020,3);
INSERT INTO stanza VALUES('T1080','chorus','Walang kabuluhan!<br/>Pawang pagkabigo!<br/>Hinahabol ang<br/>Hangi''t anino.<br/>',NULL,43021,4);
INSERT INTO stanza VALUES('T1080','3','Anong silbi ng iyong yaman?<br/>Pamilya at kasayahan,<br/>Lahat ay kabalisahan,<br/>At kabiguan!<br/>',NULL,43022,5);
INSERT INTO stanza VALUES('T1080','chorus','Walang kabuluhan!<br/>Pawang pagkabigo!<br/>Hinahabol ang<br/>Hangi''t anino.<br/>',NULL,43023,6);
INSERT INTO stanza VALUES('T1080','4','Magdamag pinagsikapan,<br/>Kahit mabuting nakamtan,<br/>Pag namatay, kasawian<br/>At kabiguan!<br/>',NULL,43024,7);
INSERT INTO stanza VALUES('T1080','chorus','Walang kabuluhan!<br/>Pawang pagkabigo!<br/>Hinahabol ang<br/>Hangi''t anino.<br/>',NULL,43025,8);
INSERT INTO stanza VALUES('T1080','5','Alalahanin Maylalang<br/>Sa araw ng kabataan,<br/>Diyos mahalin, katakutan,<br/>Siyang kasiyahan!<br/>',NULL,43026,9);
INSERT INTO stanza VALUES('T1080','chorus','May Kristo, mayaman!<br/>Walang Kristo, salat!<br/>May kabuluhan—<br/>Kristo ang lahat!<br/>',NULL,43027,10);
INSERT INTO stanza VALUES('T1081','1','Amang Diyos, bukal ng buhay Ka.<br/>Kami Iyong kahayagan nga;<br/>Pag-aari sa Iyong ngalan<br/>Amang Diyos, bukal ng buhay Ka.<br/>',NULL,43028,1);
INSERT INTO stanza VALUES('T1081','chorus','Amin kaisahan,<br/>Sa loob ng Iyong buhay,<br/>Sa loob ng buhay,<br/>O Ama, kami''y nagkaisa.<br/>',NULL,43029,2);
INSERT INTO stanza VALUES('T1081','2','O Ama, banal Mong Salita<br/>Nagpupuno, nagbubukod;<br/>Kasama Iyong kalikasan<br/>Pasalamat kami, O Ama.<br/>',NULL,43030,3);
INSERT INTO stanza VALUES('T1081','chorus','Sa Iyo ngang Salita,<br/>Kami''y nagkakaisa<br/>Sa Iyo ngang Salita,<br/>Kaming lahat pinagkaisa.<br/>',NULL,43031,4);
INSERT INTO stanza VALUES('T1081','3','O l''walhati ng Tres-unong Diyos!<br/>Pinagpala kami''y anak<br/>Kanyang gloria hinahayag<br/>O l''walhati ng Tres-unong Diyos!<br/>',NULL,43032,5);
INSERT INTO stanza VALUES('T1081','chorus','Sa Iyong gloria, sa Iyong gloria,<br/>Kami nagkakaisa<br/>Sa Iyong gloria, sa Iyong gloria<br/>Kaming lahat ginawang isa!<br/>',NULL,43033,6);
INSERT INTO stanza VALUES('T1084','1','Tulad ungguwentong nabuhos:<br/>Ngalang Hesus, Hesus, Hesus!<br/>Tulad ungguwentong nabuhos,<br/>Tulad ungguwentong nabuhos.<br/>',NULL,43034,1);
INSERT INTO stanza VALUES('T1084','2','Kaya dalaga''y mahal Ka:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Kaya dalaga''y mahal Ka,<br/>Kaya dalaga''y mahal Ka.<br/>',NULL,43035,2);
INSERT INTO stanza VALUES('T1084','3','Higit sa alak pag-ibig:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Higit sa alak pag-ibig,<br/>Higit sa alak pag-ibig.<br/>',NULL,43036,3);
INSERT INTO stanza VALUES('T1084','4','Akitin, hahabulin Ka:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Akitin, hahabulin Ka,<br/>Akitin, hahabulin Ka.<br/>',NULL,43037,4);
INSERT INTO stanza VALUES('T1084','5','Masdan, maganda Ka Sinta:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Masdan, maganda Ka Sinta,<br/>Masdan, maganda Ka Sinta.<br/>',NULL,43038,5);
INSERT INTO stanza VALUES('T1084','6','Kalul''wang ibig nakita:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Kalul''wang ibig nakita,<br/>Kalul''wang ibig nakita.<br/>',NULL,43039,6);
INSERT INTO stanza VALUES('T1084','7','Di na hayaang mawala:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Di na hayaang mawala,<br/>Di na hayaang mawala.<br/>',NULL,43040,7);
INSERT INTO stanza VALUES('T1084','8','Sinta ko agad dumating:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Sinta ko agad dumating,<br/>Sinta ko agad dumating.<br/>',NULL,43041,8);
INSERT INTO stanza VALUES('T1084','9','Puso namin ay mahal Ka:<br/>Hesus, Hesus, Hesus, Hesus!<br/>Puso namin ay mahal Ka,<br/>Puso namin ay mahal Ka.<br/>',NULL,43042,9);
INSERT INTO stanza VALUES('T1085','1','Hesus Pangalan Niya,<br/>Kamangha-mangha nga<br/>Tagapayo at Diyos,<br/>Panginoon.<br/>',NULL,43043,1);
INSERT INTO stanza VALUES('T1085','2','Bata at Anak Siya;<br/>Walang hanggang Ama;<br/>Tagapamayapa,<br/>Panginoon.<br/>',NULL,43044,2);
INSERT INTO stanza VALUES('T1085','3','Purihin ang Diyos,<br/>Nag-adya''y Hesus,<br/>''Spiritu Siya ngayon.<br/>Espiritu natin,<br/>Samba at ibigin,<br/>Ang Kamangha-manghang<br/>Hesus Ngalan.<br/>',NULL,43045,3);
INSERT INTO stanza VALUES('T1089','beginning-note','Juan 1:29; 3:14; 12:24<br/>',NULL,43046,1);
INSERT INTO stanza VALUES('T1089','1','Walang dungis na Kordero,<br/>Pinatay at nagdugo.<br/>Tinubos makasalanan,<br/>Lubos Niyang hinugasan.<br/>Ang Korderong Manunubos,<br/>Aking sala''y dinala,<br/>Aking sala''y dinala!<br/>',NULL,43047,2);
INSERT INTO stanza VALUES('T1089','2','Masdan natin, tansong ahas,<br/>Anak-Tao''y ''tinaas.<br/>Anyo ng laman ng sala,<br/>Sa krus ay napako Siya.<br/>Nilipol — lumang nilalang,<br/>Satanas, sanlibutan,<br/>Satanas, sanlibutan!<br/>',NULL,43048,3);
INSERT INTO stanza VALUES('T1089','3','Butil ng trigo''y mag-isa,<br/>Kung kamataya''y wala;<br/>Nasa loob nitong buhay,<br/>Itanim nang mamatay.<br/>Tutubo buhay ni Kristo,<br/>Bunga''y maraming trigo,<br/>Bunga''y maraming trigo!<br/>',NULL,43049,4);
INSERT INTO stanza VALUES('T1089','4','Tansong ahas — Diyablo''y wak''san,<br/>Kordero — katubusan,<br/>Butil ng trigo — pagdami,<br/>Hinalo sa marami.<br/>Aleluya! Aleluya!<br/>Kamatayang masaklaw,<br/>Kamatayang masaklaw!<br/>',NULL,43050,5);
INSERT INTO stanza VALUES('T1090','1','Anong halaga Iyong dugo,<br/>Ng Bagong Tipan Mo;<br/>Pagpala ng Diyos natanggap,<br/>Mahalo nang ganap.<br/>',NULL,43051,1);
INSERT INTO stanza VALUES('T1090','2','Kami''y tinubos ng dugo,<br/>At pinabanal Mo;<br/>Budhi lumaya sa sala,<br/>Sa patay na gawa.<br/>',NULL,43052,2);
INSERT INTO stanza VALUES('T1090','3','Mas magaling kaysa dugo<br/>Ni Abel, dugo Mo;<br/>Katubusan inilaan,<br/>Kat''wiran Niya''y tingnan.<br/>',NULL,43053,3);
INSERT INTO stanza VALUES('T1090','4','Sa walang hanggang ''Spiritu,<br/>Alay Sarili Mo;<br/>Di-malumang sakripisyo,<br/>Walang hanggang dugo!<br/>',NULL,43054,4);
INSERT INTO stanza VALUES('T1090','5','Sa dugo''y may lakas-loob,<br/>Sa trono''y dumulog,<br/>Tungo sa Diyos, bagong tipan,<br/>Kabanal-banalan.<br/>',NULL,43055,5);
INSERT INTO stanza VALUES('T1090','6','Sa dugo Mo obligado,<br/>Sarili Niya Mismo;<br/>Kanya tayong tatanggapin,<br/>Manahan sa atin.<br/>',NULL,43056,6);
INSERT INTO stanza VALUES('T1090','7','Anong halaga Iyong dugo<br/>Ng Bagong Tipan Mo;<br/>Pagpala ng Diyos natanggap,<br/>Mahalo nang ganap.<br/>',NULL,43057,7);
INSERT INTO stanza VALUES('T1095','1','Awitin ang pagpuri<br/>Poon mal''walhati,<br/>Ang anghel makikinig<br/>Lakasan ang tinig;<br/>Maririnig ng mundo<br/>Pagpuri kay Kristo,<br/>Ang kampon ni Satanas<br/>Mayanig, tatakas.<br/>',NULL,43058,1);
INSERT INTO stanza VALUES('T1095','2','Pag natikom ang labi<br/>Diyablo ay ngingiti;<br/>Labanan siya''t talunin<br/>At siya''y palayasin.<br/>Sa "hain ng pagpuri"<br/>Sigaw ng pagwagi—<br/>Kahihiyan matalos<br/>Piling-mangmang ng Diyos!<br/>',NULL,43059,2);
INSERT INTO stanza VALUES('T1095','3','Mundo kailanma''y hindi<br/>Nagbigay ng puri,<br/>Gloria man o salamat<br/>Sa Tagapagligtas;<br/>Kaya hindi na wasto<br/>Kunin kanyang "Oo,"<br/>Pagpuri''y isigaw mo!<br/>Mula sa ''spiritu!<br/>',NULL,43060,3);
INSERT INTO stanza VALUES('T1095','4','Kapatid, huwag magtimpi<br/>Sigaw ng pagpuri!<br/>Ang biyaya''t tagumpay<br/>Ng Diyos ay isaysay.<br/>Ngayon na ang panahon,<br/>Purihin Panginoon!<br/>Anuman ang mangyari,<br/>Siya''y ipagmalaki!<br/>',NULL,43061,4);
INSERT INTO stanza VALUES('T1096','1','''Hayag ng ekklesia lokal,<br/>Hesus Poon!<br/>Mga banal ngala''y tanghal:<br/>Hesus Poon!<br/>Lahat Niyang gawa''y kumpleto,<br/>Diyablo''t kampon ay natalo;<br/>Nasa mal''walhating trono,<br/>Hesus Poon!<br/>',NULL,43062,1);
INSERT INTO stanza VALUES('T1096','2','Buhay na Espiritu Siya,<br/>Hesus Poon!<br/>Lahat makinig sa Kanya,<br/>Hesus Poon!<br/>Huwag ka nang maging iyakin;<br/>Tawagin Siya''t papasukin<br/>Sentrong mal''walhati gawin—<br/>Hesus Poon!<br/>',NULL,43063,2);
INSERT INTO stanza VALUES('T1096','3','Transpormahin I-yong buhay,<br/>Hesus Poon!<br/>Yaman Niya sa Iyo''y ''bibigay,<br/>Hesus Poon!<br/>Bibigyan kang kasiyahan,<br/>Buhay ika''y tutustusan,<br/>Sa Diyos ''ka''y may kaisahan,<br/>Hesus Poon!<br/>',NULL,43064,3);
INSERT INTO stanza VALUES('T1096','4','Sa awa Niya tinanggap ka,<br/>Hesus Poon!<br/>Di ka na iiwanan pa,<br/>Hesus Poon!<br/>Ang buong kapuspusan Niya<br/>Sa Katawan makikita,<br/>Kaaway ay tatakas na—<br/>Hesus Poon!<br/>',NULL,43065,4);
INSERT INTO stanza VALUES('T1097','1','O Panginoon kay ganda,<br/>Ngalan Mo sa lupa;<br/>Bawa''t bayan, lipi''t wika,<br/>Itanghal halaga.<br/>Mula sa bibig ng sanggol,<br/>Itinatag puri;<br/>Upang Iyong patahimikin,<br/>Kaaway tapusin.<br/>',NULL,43066,1);
INSERT INTO stanza VALUES('T1097','2','Nang sansinukob pagmasdan<br/>Hayag karunungan;<br/>Araw, buwan, mga bituin,<br/>Pawang gawa Mo rin.<br/>Ano ba sa Iyo ang tao?<br/>Inaalala Mo?<br/>Dinalaw anak ng tao<br/>Sa ekonom''ya Mo.<br/>',NULL,43067,2);
INSERT INTO stanza VALUES('T1097','3','Hesus, Panginoo''y Tao,<br/>Sa ''min nakihalo.<br/>Ibinihis ang laman nga,<br/>At nagpakumbaba.<br/>Ngayon Ika''y pinutungan<br/>Ng kal''walhatian.<br/>Ngayon din sa Iyong Katawan,<br/>Lahat pinagharian.<br/>',NULL,43068,3);
INSERT INTO stanza VALUES('T1097','4','Paging tao Mo''t pagbangon,<br/>Pagkapanginoon,<br/>Pagka-ulo''t kaharian,<br/>Nakita Katawan.<br/>Kada hakbang ng gawain<br/>Puri''y natatag din.<br/>Puso nami''y nag-umapaw,<br/>Tinig alingawngaw.<br/>',NULL,43069,4);
INSERT INTO stanza VALUES('T1097','5','Araw yaon ay malapit<br/>Lahat ay aawit;<br/>Sa mga ekklesia lokal,<br/>May tikim na banal.<br/>Panginoon anong ganda,<br/>Iyong ngalan sa lupa!<br/>Bawa''t bayan, lipi''t wika,<br/>Itanghal halaga.<br/>',NULL,43070,5);
INSERT INTO stanza VALUES('T1099','1','Sa kanan nakatayo,<br/>Reyna suot ginto;<br/>Mga Iyong kasamahan,<br/>Princesa nga tanan.<br/>Ekklesia malwalhati,<br/>Katapat ng Hari;<br/>Mga kababaihan<br/>May Iyong kawangisan.<br/>',NULL,43071,1);
INSERT INTO stanza VALUES('T1099','2','Iyong tainga makinig,<br/>Anak na babae;<br/>Huwag lang sariling bayan,<br/>Ang iyong pagtuunan.<br/>Bubukadkad iyong ganda<br/>Maging paghangad Niya<br/>Haring karapat-dapat,<br/>Sa pagsambang tapat.<br/>',NULL,43072,2);
INSERT INTO stanza VALUES('T1099','3','Suot binurdang ginto,<br/>Babaeng anak Mo;<br/>Sa loob ng palasyo,<br/>Anong rilag nito!<br/>Malwalh''ting likas ng Diyos,<br/>Kanyang isinuot;<br/>Katauhang banal Niya<br/>Sa buhay hayag na.<br/>',NULL,43073,3);
INSERT INTO stanza VALUES('T1099','4','Binurdahan na damit,<br/>Sa Hari ang hatid;<br/>Pinong lino suot niya,<br/>Nang maitanghal siya<br/>''Spiritu nagbuburda<br/>Siya sa ''tin nagawa<br/>Maluwalhating damit,<br/>Sa Hari ang hatid.<br/>',NULL,43074,4);
INSERT INTO stanza VALUES('T1099','5','Anong galak at saya<br/>Pag Hari''y makita!<br/>Papuring walang hanggan<br/>Ay pagsisigawan.<br/>Sa Hari nga''y pagsamba,<br/>O gloria sa Reyna,<br/>Tamasang pagpapala<br/>L''walhati''y sa Kanya.<br/>',NULL,43075,5);
INSERT INTO stanza VALUES('T1103','1','Ano Siya: Siya ang Ama.<br/>Siya ang walang hanggang Ama.<br/>Siya''y Panganay sa nilikha.<br/>Siya''ng Isang nananahan sa ''kin.<br/>O kahanga-hanga Siya!<br/>',NULL,43076,1);
INSERT INTO stanza VALUES('T1103','2','Ano Siya: Siya ang ilog.<br/>Siya''ng umaagos na ilog.<br/>Tunay na ilog ng buhay.<br/>Ako''y tinubigan sa ilang.<br/>O kahanga-hanga Siya!<br/>',NULL,43077,2);
INSERT INTO stanza VALUES('T1103','3','Ano Siya: punong-ubas.<br/>Siya''ng sanga, ugat ni Isai.<br/>Puno ng buhay, kainin.<br/>Buhay Niya ating taglayin.<br/>O kahanga-hanga Siya!<br/>',NULL,43078,3);
INSERT INTO stanza VALUES('T1103','4','Ano Siya: Siya ang Pastol.<br/>Ako''y Kanyang ''pinahinga,<br/>Pinakain, pinainom,<br/>Nang lumakad sa katuwiran.<br/>O kahanga-hanga Siya!<br/>',NULL,43079,4);
INSERT INTO stanza VALUES('T1103','5','Ano Siya: Espiritu,<br/>Nagpapaloob-ng-lahat.<br/>Ang Espiritu ng buhay,<br/>Nagbigay buhay, pagtawag ko.<br/>O kahanga-hanga Siya!<br/>',NULL,43080,5);
INSERT INTO stanza VALUES('T1103','6','Ano Siya: Siya''y Persona.<br/>Tunay, buháy na Persona.<br/>Namumuhay sa loob natin.<br/>Ang Personang mal''walhati.<br/>O kahanga-hanga Siya!<br/>',NULL,43081,6);
INSERT INTO stanza VALUES('T1103','7','Ano Siya: ang Katawan.<br/>Siya ang kapuspusan ng Diyos.<br/>Sentro ng plano ng Ama.<br/>Kristo''t Ekklesia: bagong tao.<br/>Kahanga-hanga talaga!<br/>',NULL,43082,7);
INSERT INTO stanza VALUES('T1103','chorus','Kahanga-hanga, Siya na nga!<br/>Kahanga-hanga, Siya na nga!<br/>',NULL,43083,8);
INSERT INTO stanza VALUES('T1106','1','Tayo''y sa hapag Niya nagtitipun-tipon:<br/>''Tinatanghal sa pagkain, pag-inom.<br/>Inihayag pagkakaisa sa Kanya,<br/>Nababatid lubos ang pagpapala Niya.<br/>',NULL,43084,1);
INSERT INTO stanza VALUES('T1106','2','Ang tinapay ng katawan Niyang nabasag<br/>Ating tinatamasa na sa hapag:<br/>Iisang tinapay — iisang Katawan,<br/>Pagkakaisa ay pinatotohanan.<br/>',NULL,43085,2);
INSERT INTO stanza VALUES('T1106','3','Ating iniinom sarong pagpapala,<br/>Salamuhang tunay ng ekklesia;<br/>Lahat ng tinubos ating tinatanggap,<br/>Mga sumasampalataya nang ganap.<br/>',NULL,43086,3);
INSERT INTO stanza VALUES('T1106','4','"Aleluya" lamang masasabi natin<br/>Sa katotohanang napasa atin.<br/>Ang dugo''t Katawan Mo''y aming tamasa;<br/>Mapasa Iyo ang mal''walhating ekklesia.<br/>',NULL,43087,4);
INSERT INTO stanza VALUES('T1107','1','Iyong Katawan, kami''y nagkakatipon:<br/>Marami man, subali''t iisa;<br/>Bilang sangkap, kami''y bumabahagi<br/>Ng buhay Mo, kaya''t nagkaisa.<br/>',NULL,43088,1);
INSERT INTO stanza VALUES('T1107','chorus','Sa sansinukob, may ''sang Katawan,<br/>Dito sa lupa''y nahayag;<br/>Sa bawa''t lokalidad ay isa<br/>Upang makita ng lahat.<br/>',NULL,43089,2);
INSERT INTO stanza VALUES('T1107','2','Tanda ng Katawan Mo''y ''sang tinapay<br/>Nabasag para sa mga banal;<br/>Habang ang tinapay ay kinakain,<br/>Kaisahan nami''y tinatanghal.<br/>',NULL,43090,3);
INSERT INTO stanza VALUES('T1107','3','''Sang tinapay, ''sang saro nasa dulang,<br/>Inihayag ang pagkakaisa;<br/>Tinubos at inangking Katawan Niya:<br/>"Amen, Panginoon, kami''y isa!"<br/>',NULL,43091,5);
INSERT INTO stanza VALUES('T1107','4','Nakatayong buo, di mahahati,<br/>Dahil si Kristo ang kaisahan;<br/>Lumalahok sa ''sang saro''t tinapay,<br/>Kaya''t kaisaha''y mamamasdan.<br/>',NULL,43092,7);
INSERT INTO stanza VALUES('T1107','5','O, kay saya, taglay ang kaisahan!<br/>Dama naming Ika''y nasisiyahan;<br/>Kami''y nagkaroon ng kagalakan—<br/>Aming natitikman ang kasalan.<br/>',NULL,43093,9);
INSERT INTO stanza VALUES('T1108','1','Kainin natin ang tinapay:<br/>Purihin Siya at tayo''y isa,<br/>Sa pagkain ay tinataglay<br/>Pagkakaisa ng ekklesia.<br/>',NULL,43094,1);
INSERT INTO stanza VALUES('T1108','chorus','Tinapay kanin mga banal!<br/>Inumàn din ang saro.<br/>Kaisahan sa lupang lokal,<br/>Ipakitang totoo!<br/>',NULL,43095,2);
INSERT INTO stanza VALUES('T1108','2','Inuman na natin ang saro:<br/>Tinubos upang maging isa,<br/>Binili na ng Kanyang dugo—<br/>Natupad na ang layunin Niya.<br/>',NULL,43096,3);
INSERT INTO stanza VALUES('T1108','3','Iisa lang ang bayan ng Diyos;<br/>Hindi mga butil na kalat—<br/>Pinaghalo''t isinaayos<br/>Isa sa bawa''t lokalidad.<br/>',NULL,43097,5);
INSERT INTO stanza VALUES('T1108','4','Ipahayag na tayo''y isa;<br/>At hindi lamang sa salita.<br/>Ang buhay nati''y nagkaisa<br/>Ang Diyos ang may sanhi''t may gawa.<br/>',NULL,43098,7);
INSERT INTO stanza VALUES('T1108','5','Kainin natin ang tinapay:<br/>Purihin Siya at tayo''y isa.<br/>Sa pagkain ay tinataglay<br/>Pagkakaisa ng ekklesia.<br/>',NULL,43099,9);
INSERT INTO stanza VALUES('T1110','1','Panginoon, sa harap ng hapag Mo,<br/>Tinapay at saro ay namasdan;<br/>Purihin Ka, pagkain Ka ng tao,<br/>Matamasa sa libong paraan.<br/>',NULL,43100,1);
INSERT INTO stanza VALUES('T1110','chorus','Koro 1:<br/>Pupurihin Kita''t aawitan,<br/>Napakaliit Mo Hesus!<br/>Kakainin Ka nang walang hanggan;<br/>Napakaliit Mo Hesus!<br/>',NULL,43101,2);
INSERT INTO stanza VALUES('T1110','2','Yaman ni Kristo''y dala Niya sa mundo,<br/>Panustos ang buhay Niya sa tao,<br/>Sayang! tao''y lugmok sa pagtuturo,<br/>Itong yaman hindi niya matamo.<br/>',NULL,43102,3);
INSERT INTO stanza VALUES('T1110','chorus','Koro 2:<br/>Ang Pangino''n kailangang kainin;<br/>Kay hiwaga, di matalos!<br/>Sisigla tayo pag kumakain;<br/>Kristo''y lumalagong lubos.<br/>',NULL,43103,4);
INSERT INTO stanza VALUES('T1110','3','Hesus, di Ka pumarito sa lupa<br/>Upang maghari sa panlabas lang;<br/>Kundi Ika''y pagkaing matamasa,<br/>Buhay gumiya sa kalooban.<br/>',NULL,43104,5);
INSERT INTO stanza VALUES('T1110','chorus','Pupurihin Kita''t aawitan,<br/>Napakaliit Mo Hesus!<br/>Kakainin Ka nang walang hanggan;<br/>Napakaliit Mo Hesus!<br/>',NULL,43105,6);
INSERT INTO stanza VALUES('T1110','4','Purihin Ka sa Iyong kadakilaan,<br/>Kapangyarihan at karangalan;<br/>Nguni''t lalo Kang pasasalamatan,<br/>Makakain Ka sa kaliitan.<br/>',NULL,43106,7);
INSERT INTO stanza VALUES('T1110','chorus','Pupurihin Kita''t aawitan,<br/>Napakaliit Mo Hesus!<br/>Kakainin Ka nang walang hanggan;<br/>Napakaliit Mo Hesus!<br/>',NULL,43107,8);
INSERT INTO stanza VALUES('T1113','1','Ngayon ang Diyos-Trinidad ay dumating<br/>Nang manahan sa loob natin,<br/>Bilang kamangha-manghang Espiritu<br/>Nagbibigay-buhay sa atin.<br/>',NULL,43108,1);
INSERT INTO stanza VALUES('T1113','chorus','Siyang nasa atin na Espiritu,<br/>Espiritung kamangha-mangha!<br/>Ang Diyos ay nasa Anak, ang Anak ay—<br/>Espiritung kamangha-mangha!<br/>',NULL,43109,2);
INSERT INTO stanza VALUES('T1113','2','"Abba Ama" ang sigaw nagmula sa<br/>Espiritung kamangha-mangha,<br/>Na siyang Espiritu ng Anak tunay<br/>Sa atin nagbibigay-buhay.<br/>',NULL,43110,3);
INSERT INTO stanza VALUES('T1113','3','Ang Panginoong Hesu-Kristo ngayon<br/>Nabubuhay sa loob natin.<br/>Nagbagong-anyo bilang Espiritu,<br/>Kaya natatamasa natin.<br/>',NULL,43111,5);
INSERT INTO stanza VALUES('T1113','4','Espiritung realidad narito,<br/>Sa loob ng espiritu ko.<br/>Malinaw at tunay, bagay ni Kristo,<br/>Dahil sa nanahang ''Spiritu.<br/>',NULL,43112,7);
INSERT INTO stanza VALUES('T1113','5','Itong kaloob ay ating gisingin,<br/>Kamangha-manghang Espiritu.<br/>"O Panginoong Hesus" ay tawagin,<br/>Ang espiritu''y mapalukso!<br/>',NULL,43113,9);
INSERT INTO stanza VALUES('T1115','1','Pumasok tayo sa tahanan ng Diyos;<br/>Kung saan ang tubig ay umaagos.<br/>Araw man o gabi, tuloy ang agos,<br/>Dinidiligan tayo''t nagtutustos.<br/>',NULL,43114,1);
INSERT INTO stanza VALUES('T1115','2','Umaagos mula sa templong ito,<br/>Ang buhay na dala para sa mundo.<br/>Sana ay pakinggan ang aming samo;<br/>Kaming lahat nawa ay puspusan Mo.<br/>',NULL,43115,2);
INSERT INTO stanza VALUES('T1115','3','Sukatin Mo kami sa araw-araw;<br/>Sukatin Mo kami hanggang umapaw,<br/>Hanggang sa makita, ilog ng buhay,<br/>Bumaha''t lahat kay Kristo''y magtaglay.<br/>',NULL,43116,3);
INSERT INTO stanza VALUES('T1115','4','Sa agos na ito, nawa''y dalhin Mo;<br/>Minsan at minsan pa, dito magtungo.<br/>Hanggang sa ang tubig, malanguyan ko,<br/>At kami''y mababad sa biyaya Mo.<br/>',NULL,43117,4);
INSERT INTO stanza VALUES('T1115','5','Ang lahat, ang lahat ay mabubuhay;<br/>Sa ilog na dala''y tubig ng buhay.<br/>Masaganang buhay-sanhi''y magbunga,<br/>Sa bawa''t lokalidad, ng ekklesia!<br/>',NULL,43118,5);
INSERT INTO stanza VALUES('T1116','1','Mira at kanela<br/>Kalamo at kassia—<br/>Mga elemento,<br/>Ng Poon ko!<br/>Sa langis olibo,<br/>Pinaghalo-halo;<br/>Ungguwentong magaling<br/>Pahid sa ''tin.<br/>',NULL,43119,1);
INSERT INTO stanza VALUES('T1116','chorus','Apat sa isa,<br/>Kay tamis samyo,<br/>Espiritung timplada,<br/>Kamatayan Niya<br/>At pagkabuhay—<br/>Daloy ungguwento<br/>Sa ''spiritu.<br/>',NULL,43120,2);
INSERT INTO stanza VALUES('T1116','2','Estacte, onycha,<br/>Galbano''t kamangyan—<br/>Mga elemento,<br/>Ng Poon ko.<br/>Mga anak bunga,<br/>Sa sala mapalaya;<br/>Kamatayan matalo,<br/>Sa ''spiritu.<br/>',NULL,43121,3);
INSERT INTO stanza VALUES('T1116','chorus','Sa timbang pantay<br/>Sa pagkabuhay<br/>May asing pantimpla<br/>Ito''y tinupok pa<br/>Ng apoy dibino<br/>Anong insenso ''to<br/>Panginoon.<br/>',NULL,43122,4);
INSERT INTO stanza VALUES('T1116','3','Anong gloria ito,<br/>Kristo ay ungguwento!<br/>Sa Diyos Siya''y insenso,<br/>Lubos sa Iyo<br/>Daloy ang ungguwento,<br/>Sa atin ni Kristo;<br/>Umakyat insenso,<br/>Sa Diyos samyo.<br/>',NULL,43123,5);
INSERT INTO stanza VALUES('T1116','chorus','Pagpapahid Niya,<br/>Maranasan Siya.<br/>Insenso''y sunugin;<br/>Kristo ay danasin,<br/>Magdasal, purihin<br/>Siya''y itaas natin<br/>Sa Diyos dalhin.<br/>',NULL,43124,6);
INSERT INTO stanza VALUES('T1117','1','Purihin Ka Diyos,<br/>Sa Espiritu Mo<br/>Na pumasok sa amin<br/>Naging buhay rin.<br/>Aleluya! Espiritu!<br/>Nasa aming loob!<br/>Aleluya! Walang hanggang<br/>Buhay sagana!<br/>',NULL,43125,1);
INSERT INTO stanza VALUES('T1117','2','Awitan natin<br/>Ang Isang dumating<br/>Espiritu ng buhay<br/>Kaisa natin.<br/>Aleluya! Si Hesus nga,<br/>Ngayon ay higit pa!<br/>Buhay nating walang hanggan,<br/>Espiritu Siya!<br/>',NULL,43126,2);
INSERT INTO stanza VALUES('T1117','3','Nai-silang-muli,<br/>Binabagong lubos,<br/>Tayo''y napawawangis<br/>Sa Anak ng Diyos.<br/>Aleluya! Binuhay na,<br/>At tinatransporma,<br/>Aleluya! Mapawangis<br/>Sa larawan Niya.<br/>',NULL,43127,3);
INSERT INTO stanza VALUES('T1117','4','Mawangis tayo<br/>Dahil sa pagkain<br/>Sa buhay Niyaong laging<br/>Nagtustos sa ''tin.<br/>Aleluya! Kaligtasan!<br/>Ating Gantimpala!<br/>Aleluya! Kay sagana<br/>Sa ating buhay.<br/>',NULL,43128,4);
INSERT INTO stanza VALUES('T1122','beginning-note','Apocalipsis 1:4; 4:5; 5:6<br/>',NULL,43129,1);
INSERT INTO stanza VALUES('T1122','1','Pitong ''Spiritu ng Diyos—<br/>Panahon bumaling na<br/>Sa Espiritu lubos,<br/>Kay Kristo''t ekklesia.<br/>',NULL,43130,2);
INSERT INTO stanza VALUES('T1122','chorus','Halina, Espiritu,<br/>Pagbabawi Iyong tupdin!<br/>Ekklesia''y para sa Iyo.<br/>Kami ay Iyong suriin,<br/>Pagningasin,<br/>Ekklesia''y para sa Iyo!<br/>',NULL,43131,3);
INSERT INTO stanza VALUES('T1122','2','''Spiritu''y makapito<br/>Para sa ekklesia,<br/>Susuriin ni Kristo,<br/>Tayo''y bubuhayin Niya.<br/>',NULL,43132,4);
INSERT INTO stanza VALUES('T1122','3','''Spiritu ng ating Diyos<br/>Ay napatindi ngayon:<br/>Di isa, makapito—<br/>Ekklesia''y matustusan!<br/>',NULL,43133,6);
INSERT INTO stanza VALUES('T1122','4','Pitong ''Spiritu nama''y<br/>Pitong ilawang apoy,<br/>Di magturo, kundi Siya''y<br/>Sumunog nang patuloy.<br/>',NULL,43134,8);
INSERT INTO stanza VALUES('T1122','5','Pitong ''Spiritu''y masdan—<br/>Nagniningas na mata.<br/>Ang ekklesia''y hantaran,<br/>Na dinadalisay Niya.<br/>',NULL,43135,10);
INSERT INTO stanza VALUES('T1122','6','Pitong ''Spiritu''y para<br/>Magamit sa ekklesia;<br/>Siya ay matatamasa<br/>Sa lokal na ekklesia.<br/>',NULL,43136,12);
INSERT INTO stanza VALUES('T1123','1','Espiritu pinagmulan<br/>Ni Hesus nang isilang;<br/>Puspos, lahat Siya''y ''Spiritu<br/>Esensyang tunay ito.<br/>Sa loob taglay ''Spiritu<br/>Nang si Hesus dumating,<br/>Panginoon ay ''Spiritu<br/>Tayo''y magkatulad din.<br/>',NULL,43137,1);
INSERT INTO stanza VALUES('T1123','2','Tayo ay nabautismuhan<br/>Sa Espiritu Santo;<br/>Nang ekklesia''y naisilang<br/>Sa relih''yon nabukod.<br/>Sumaloob ng ''Spiritu—<br/>Kailangan nating lahat,<br/>Hindi turo, porma, kredo<br/>Sa ekklesia''y ''Spiritu.<br/>',NULL,43138,2);
INSERT INTO stanza VALUES('T1123','3','Kai-sahan sa Espiritu<br/>Bahagi''y salamuha;<br/>Lahat mga kapatiran<br/>Tumuon sa ''Spiritu.<br/>Ngayon sa mga ekklesia,<br/>''Spiritu''y nagsalita.<br/>Ating bahaging may pala<br/>Pitong Espiritu nga.<br/>',NULL,43139,3);
INSERT INTO stanza VALUES('T1123','4','Sabi ng ''Spiritu''t Nobya:<br/>"Halina uminom ka."<br/>Magkasamang nagsalita,<br/>Lubusang nagkaisa.<br/>Ayon sa ''Spiritu dapat<br/>Maging ating realidad.<br/>Pagbawi ng Panginoon,<br/>''Spiritu sa ''tin ngayon.<br/>',NULL,43140,4);
INSERT INTO stanza VALUES('T1129','beginning-note','Hebreo 2:3<br/>',NULL,43141,1);
INSERT INTO stanza VALUES('T1129','1','Hinayag ang kaligtasang dakila<br/>Sa atin ng natatanging Salita!<br/>Yamang Siya''t gawa Niya''y para sa atin,<br/>Mal''walhating salita''y unawain.<br/>',NULL,43142,2);
INSERT INTO stanza VALUES('T1129','2','Bilang Anak, Siya''y sa Diyos at sa tao,<br/>Kaisa Niyang nagtatamasa tayo;<br/>Saserdote, Pinuno — kaligtasan!<br/>Lumago tayo sa kal''walhatian.<br/>',NULL,43143,3);
INSERT INTO stanza VALUES('T1129','3','Sala''y hinugasan, pinadalisay,<br/>Pinalaya nang sa krus Siya''y namatay;<br/>Bihis likas natin, diyablo pinaslang,<br/>Tayo''y nilagay sa kal''walhatian.<br/>',NULL,43144,4);
INSERT INTO stanza VALUES('T1129','4','Kay lawak saklaw ating kaligtasan,<br/>Kasosyo''y Kristo sa kal''walhatian;<br/>Kasamang mamuno sa gloria dalhin,<br/>Paggawa Niya, kaligtasan sukdulin.<br/>',NULL,43145,5);
INSERT INTO stanza VALUES('T1129','5','Unawain natin ang kaligtasan,<br/>Nang di malihis o mapabayaan;<br/>Kaligtasan, Kristo ay buhay ngayon,<br/>Haring kasama pagdating panahon.<br/>',NULL,43146,6);
INSERT INTO stanza VALUES('T1129','6','Binigay "Kay dakilang kaligtasan,"<br/>Mawangis sa Poong kal''walhatian;<br/>Sa Kanya mismo, lahat Niyang nagawa,<br/>Kasama Anak, sa gloria madala.<br/>',NULL,43147,7);
INSERT INTO stanza VALUES('T1130','beginning-note','Hebreo 7<br/>',NULL,43148,1);
INSERT INTO stanza VALUES('T1130','1','Kristong buhay papurihan,<br/>Diyos ng ''ting kaligtasan;<br/>Buhay dibino ang daan,<br/>Di regulasyon naman;<br/>Matapos magawa tanan,<br/>Buhay Niya may kakayahan<br/>Magtranspormang lubusan.<br/>',NULL,43149,2);
INSERT INTO stanza VALUES('T1130','2','Sukdulan tayong niligtas,<br/>Nagbigay-buhay, lakas;<br/>''Nilalin Kanyang Sarili,<br/>''Niligtas tayong lagi.<br/>Nawala''y iniligtas Niya,<br/>''Di lamang mula sa sala,<br/>Bagkus tungo sa gloria!<br/>',NULL,43150,3);
INSERT INTO stanza VALUES('T1130','3','Pagkasaserdote''y taglay,<br/>Tagapagbigay-buhay;<br/>Sa sarili ko''y niligtas,<br/>N''yaong buhay ang likas;<br/>Buhay walang kasiraan,<br/>Ang nagligtas nang lubusan:<br/>Siya ay may kakayahan!<br/>',NULL,43151,4);
INSERT INTO stanza VALUES('T1130','4','K''walipikado buhay Niya,<br/>Dalhin tayo sa gloria;<br/>Kung di sa subok Niyang buhay,<br/>Iba na ang salaysay:<br/>Subok buhay Niya sa lupa,<br/>Sa pagsilang hanggang krus Niya,<br/>Maging kamatayan pa.<br/>',NULL,43152,5);
INSERT INTO stanza VALUES('T1130','5','''Ligtas tayo, Siya''y nagprenda,<br/>Buhay Niya''y gumagawa;<br/>Upang mapasakdal tayo<br/>Lahat ginawang husto;<br/>Pinakamainam natin,<br/>Maituring bigo pa rin:<br/>Buhay Niya ang subukan!<br/>',NULL,43153,6);
INSERT INTO stanza VALUES('T1130','6','Namagitan para sa ''tin,<br/>Patuloy ang dalangin;<br/>Saserdoteng walang hanggan,<br/>Magpakailanpaman;<br/>Buháy upang mamagitan,<br/>Saserdote ngang kailangan:<br/>Higit ang kataasan.<br/>',NULL,43154,7);
INSERT INTO stanza VALUES('T1130','7','Magsilapit sa Diyos ngayon,<br/>''Pahamak kung uurong;<br/>Lumapit tamuhin buhay,<br/>Wastong pangsyon mataglay;<br/>Magsilapit, buhay kunin,<br/>Kamatayan lulunukin,<br/>Bayan Niya tayo''y ''turing.<br/>',NULL,43155,8);
INSERT INTO stanza VALUES('T1132','1','Kami''y turuan Mo,<br/>Manalangin ayon sa Iyo.<br/>Di daang sarili,<br/>Araw-araw tawagin kang lagi—<br/>Lumago Ka sa ''min.<br/>',NULL,43156,1);
INSERT INTO stanza VALUES('T1132','2','Binhi ng buhay Ka,<br/>Sa puso ay pinunla;<br/>Ngayon may simula,<br/>Ang higit na buhay matamasa—<br/>Lumago Ka sa ''min.<br/>',NULL,43157,2);
INSERT INTO stanza VALUES('T1132','3','Kami''y palambutin;<br/>Ikaw, pinagmulan namin.<br/>Iyong ngala''y tawagin,<br/>Lupa''y bungkalin, bato''y alisin—<br/>Lumago Ka sa ''min.<br/>',NULL,43158,3);
INSERT INTO stanza VALUES('T1132','4','Kay linaw liwanag,<br/>Aming kahinaan hayag;<br/>Totoong pahayag,<br/>Buhay na binhi, sisibol tiyak—<br/>Lumago Ka sa ''min.<br/>',NULL,43159,4);
INSERT INTO stanza VALUES('T1132','5','''Spiritu''y dukhain,<br/>Mga nalalaman kunin;<br/>Buhay paagusin,<br/>Nagpapalagong buhay tanggapin—<br/>Lumago Ka sa ''min.<br/>',NULL,43160,5);
INSERT INTO stanza VALUES('T1132','6','Puso''y dalisayin,<br/>Sapagka''t di mas''yahan din,<br/>Kung di Mo punuin<br/>Isip, damdamin, pasya, baguhin—<br/>Lumago Ka sa ''min.<br/>',NULL,43161,6);
INSERT INTO stanza VALUES('T1132','7','Kintalan ang puso,<br/>Bawa''t araw, ''Ka''y matamo;<br/>Ang binhi lumago,<br/>Kaharian manatili rito—<br/>Lumago Ka sa ''min.<br/>',NULL,43162,7);
INSERT INTO stanza VALUES('T1132','8','Amen! — Sa paglago!<br/>Buhay Mo''y di-limitado;<br/>Ang tanan mabago.<br/>Magagawa nang dahil sa Iyo.<br/>Hesus, lumago Ka,<br/>Hesus, lumago Ka.<br/>',NULL,43163,8);
INSERT INTO stanza VALUES('T1134','beginning-note','Efeso 3:17-20<br/>',NULL,43164,1);
INSERT INTO stanza VALUES('T1134','1','Palakasin espiritu ko,<br/>Ng kapangyarihan Mo;<br/>Lumaganap Ka sa puso ko<br/>Panginoong Hesus ko.<br/>',NULL,43165,2);
INSERT INTO stanza VALUES('T1134','chorus','Sa puso ko, sa puso ko,<br/>Lumaganap sa puso ko;<br/>Gumawa Ka ng tahanan<br/>Sa puso ko nang lubusan.<br/>',NULL,43166,3);
INSERT INTO stanza VALUES('T1134','2','Lumaganap Ka sa puso ko,<br/>Aking dalangin, samo;<br/>Lumaganap Ka sa puso ko<br/>Mula sa ''spiritu ko.<br/>',NULL,43167,4);
INSERT INTO stanza VALUES('T1134','chorus','Sa puso ko, sa puso ko,<br/>Lumaganap sa puso ko;<br/>Gumawa Ka ng tahanan<br/>Sa puso ko nang lubusan.<br/>',NULL,43168,5);
INSERT INTO stanza VALUES('T1134','3','Sa puso ko ay manahan Ka,<br/>Sa puso ko Iyong gawin;<br/>Nang kapuspusan Mo''y punuin<br/>Ang puso ko ngayon din.<br/>',NULL,43169,6);
INSERT INTO stanza VALUES('T1134','chorus','Sa puso ko, sa puso ko,<br/>Lumaganap sa puso ko;<br/>Gumawa Ka ng tahanan<br/>Sa puso ko nang lubusan.<br/>',NULL,43170,7);
INSERT INTO stanza VALUES('T1134','4','Poong Hesus, kaya Mong gawin<br/>Higit sa isip, hiling;<br/>Sa Iyo aming puso ay bukas,<br/>Pagtanggap sa Iyo''y wagas.<br/>',NULL,43171,8);
INSERT INTO stanza VALUES('T1134','chorus','Sa puso ko, sa puso ko,<br/>Lumaganap sa puso ko;<br/>Gumawa Ka ng tahanan<br/>Sa puso ko nang lubusan.<br/>',NULL,43172,9);
INSERT INTO stanza VALUES('T1136','1','O, Poon, bigyan pahayag,<br/>Pagkakita''t liwanag.<br/>Ika''y buhay sa ''spiritu,<br/>Realidad totoo;<br/>Mula sa ''ming espiritu,<br/>Bawa''t parte angkin Mo,<br/>Kumalat sa katauhan,<br/>Puso ko Iyong tahanan.<br/>',NULL,43173,1);
INSERT INTO stanza VALUES('T1136','2','Di panlabas na pagkilos—<br/>Pag-aastang maayos,<br/>May modo''t wastong ugali,<br/>Ni ang dapat siyang gawi;<br/>Kundi Kristo ang Persona,<br/>Nai-halo sa loob na,<br/>Lumaganap sa atin Siya,<br/>Siyang ipamuhay nawa.<br/>',NULL,43174,2);
INSERT INTO stanza VALUES('T1136','3','Panginoon, bawa''t kilos,<br/>Gawa''t salita''y lubos,<br/>Sa Iyo manggagaling Mismo<br/>Maging karanasan ko.<br/>Hungkag na turo tanggihan,<br/>Tunggalian iwanan,<br/>Ang daan ng pamumuhay,<br/>Siyang pag-apaw ng buhay!<br/>',NULL,43175,3);
INSERT INTO stanza VALUES('T1136','4','Damdaming panloob sundin,<br/>Pag-apaw bigyang-diin,<br/>Kumilos sa pagpapahid,<br/>Hindi sa isip, batid,<br/>Hindi ayon sa hangarin,<br/>Ni motibo''t layunin,<br/>Kundi mamuhay sa Kanya,<br/>Sundin lamang pandama!<br/>',NULL,43176,4);
INSERT INTO stanza VALUES('T1136','5','Sa gayon napabanal na,<br/>Lubos napuspusan pa;<br/>Nagbubukod na doktrina,<br/>Turo''y konseptong luma.<br/>Kundi si Kristo na Mismo,<br/>Bawa''t parte dagdagan,<br/>Nagtutustos, nasisiyahan,<br/>Sa ''ting puso''y nanahan.<br/>',NULL,43177,5);
INSERT INTO stanza VALUES('T1141','1','Umawit tayo sa espiritu,<br/>Sa ating Panginoong Kristo,<br/>Awitin kay Hesus: Aleluya,<br/>At makipag-isa sa Kanya.<br/>',NULL,43178,1);
INSERT INTO stanza VALUES('T1141','2','Sa relih''yon tayo''y malaon na,<br/>Sa isip tayo''y malaon na,<br/>Sa damdamin tayo''y malaon na,<br/>Ang naratnan nati''y wala pa.<br/>',NULL,43179,2);
INSERT INTO stanza VALUES('T1141','3','Ngayon sa espiritu''y bumaling,<br/>Kristo''y tanggaping buhay natin;<br/>Kay Hesus ay matutong kumain<br/>Nang mapalaya sa pasanin.<br/>',NULL,43180,3);
INSERT INTO stanza VALUES('T1141','4','Buhay espirituwal, Aleluya!<br/>Sa kabaguhan, Aleluya!<br/>Pagbaling sa espiritu natin,<br/>Ang kasaganaan Niya''y kamtin.<br/>',NULL,43181,4);
INSERT INTO stanza VALUES('T1143','1','Kay tamis puno ng buhay,<br/>Diyos Mismo ang buhay.<br/>Gutom, patay ako noon,<br/>Kumain, nabuhay.<br/>',NULL,43182,1);
INSERT INTO stanza VALUES('T1143','2','Diyos dinala ''ko sa puno,<br/>Pagkain ay Kristo;<br/>Kay halaga nga ng puno<br/>Nang kanin ko ito.<br/>',NULL,43183,2);
INSERT INTO stanza VALUES('T1143','3','Poon Mismo ang pagkain,<br/>Tustos ng buhay rin;<br/>Katamasahang dalisay,<br/>Siya lang makabigay.<br/>',NULL,43184,3);
INSERT INTO stanza VALUES('T1143','4','Puno malaya kong kanin,<br/>Daan ay kumain<br/>Nang masidlan ng Diyos ako,<br/>Siya''y ipamuhay ko.<br/>',NULL,43185,4);
INSERT INTO stanza VALUES('T1144','1','Biblia''y nagsaad, tao''y nilikha<br/>May wangis ng Diyos — ihayag Siya,<br/>Makapangyarihan Siya sa lupa,<br/>Tupdin ang Kanyang panukala.<br/>',NULL,43186,1);
INSERT INTO stanza VALUES('T1144','chorus','Wangis, wangis,<br/>Sa wangis ng Diyos — siya''y nilikha,<br/>Wangis, wangis,<br/>Tupdin ang Kanyang panukala.<br/>',NULL,43187,2);
INSERT INTO stanza VALUES('T1144','2','Walang iniutos maliban sa:<br/>"Lahat ng puno''y makakain;<br/>Huwag lang ang puno ng buti''t sama,<br/>Tiyak mamamatay kung kainin."<br/>',NULL,43188,3);
INSERT INTO stanza VALUES('T1144','chorus','Kaalaman,<br/>Ang bunga''y di sadyang pagkain;<br/>Kaalaman,<br/>Ang bunga''y di dapat kainin.<br/>',NULL,43189,4);
INSERT INTO stanza VALUES('T1144','3','Puno ng buhay sa halamanan,<br/>Diyos Mismo ang puno ng buhay.<br/>Nguni''t Satanas, ang manlilinlang,<br/>Tinukso ang tao''t tinangay.<br/>',NULL,43190,5);
INSERT INTO stanza VALUES('T1144','chorus','Siya''y natisod,<br/>Nakamamatay ang kinain.<br/>Siya''y natisod,<br/>Tao ay kailangang bawiin.<br/>',NULL,43191,6);
INSERT INTO stanza VALUES('T1144','4','Si Hesus ngayo''y puno ng buhay,<br/>Sa pagtubos nilugod ang Diyos.<br/>Bagong buhay sa tao''y ''binigay,<br/>Tao ay kakain nang lubos.<br/>',NULL,43192,7);
INSERT INTO stanza VALUES('T1144','chorus','Hesus, Hesus,<br/>Si Hesus ay masarap kanin.<br/>Hesus, Hesus,<br/>Tunay na inumi''t pagkain.<br/>',NULL,43193,8);
INSERT INTO stanza VALUES('T1144','5','Hesus di nagbigay kaalaman,<br/>Kaalama''y nagpapalalo.<br/>Hesus Mismo ay isang handaan,<br/>Nang tao''y mabusog, mapuno.<br/>',NULL,43194,9);
INSERT INTO stanza VALUES('T1144','chorus','Tanggapin Siya,<br/>Nakalulugod, mal''walhati.<br/>Tanggapin Siya,<br/>Puno ng buhay, iyong bahagi.<br/>',NULL,43195,10);
INSERT INTO stanza VALUES('T1144','6','Kanin si Hesus, tayo''y lalago,<br/>Buhay at bilang maragdagan.<br/>Pagbawi ng Diyos, dapat matanto,<br/>Di relih''yon, Kristo''y handaan.<br/>',NULL,43196,11);
INSERT INTO stanza VALUES('T1144','chorus','Kainin Siya,<br/>Kristo ang buhay at pagkain,<br/>Kainin Siya,<br/>Ang kumain — mabubuhay rin.<br/>',NULL,43197,12);
INSERT INTO stanza VALUES('T1144','7','Ngayon, nang maibuhay si Kristo,<br/>Di dapat magkulang sa kain,<br/>Mga ekklesia''y maitatayo,<br/>Kristong Kasintaha''y darating.<br/>',NULL,43198,13);
INSERT INTO stanza VALUES('T1144','chorus','Kain, kain,<br/>Di dapat magkulang sa kain.<br/>Kain, kain,<br/>Kristong Kasintaha''y darating.<br/>',NULL,43199,14);
INSERT INTO stanza VALUES('T1145','1','Kristo''y ibinigay ng Diyos,<br/>Matamasa nating lubos;<br/>Puno ng buhay panustos,<br/>Diyos nati''y pagkain.<br/>Diyos nati''y pagkain!<br/>Diyos nati''y pagkain!<br/>Ito''y ating patotoo:<br/>Diyos nati''y pagkain!<br/>',NULL,43200,1);
INSERT INTO stanza VALUES('T1145','2','Ngayo''y kainin natin Siya,<br/>Mabuhay dahil sa Kanya;<br/>Sa piging tamasahin Siya,<br/>Kamtan ang Diyos Mismo.<br/>Hesus ating piging!<br/>Hesus ating piging!<br/>Kainin at ibuhay Siya;<br/>Hesus ating piging!<br/>',NULL,43201,2);
INSERT INTO stanza VALUES('T1145','3','Kristo ay ating pagkain;<br/>Siya''y tinapay at inumin;<br/>Siya''y panustos-buhay natin;<br/>Kainin natin Siya.<br/>Araw-araw kanin!<br/>Araw-araw kanin!<br/>Siya''y panustos-buhay natin;<br/>Araw-araw kanin!<br/>',NULL,43202,3);
INSERT INTO stanza VALUES('T1145','4','Ang piging tamasa natin;<br/>Laan ito sa atin din,<br/>Ang may ibig pumarito,<br/>Halina''t kumain.<br/>Halina''t kumain!<br/>Halina''t kumain!<br/>Ang may ibig ay pumarito,<br/>Halina''t kumain!<br/>',NULL,43203,4);
INSERT INTO stanza VALUES('T1148','1','"Halina''t kumain," tawag ni Hesus.<br/>Kainin at inumin Siyang palagi!<br/>Siya ang ating pagkain,<br/>Tanging Siya''ng makabusog.<br/>"Halina''t kumain," tawag ni Hesus.<br/>',NULL,43204,1);
INSERT INTO stanza VALUES('T1148','2','"Halina''t kumain," tawag ni Hesus.<br/>Kainin at inumin Siyang palagi!<br/>Siya''y naging ating buhay<br/>Na pumupuspos sa ''tin.<br/>"Halina''t kumain," tawag ni Hesus.<br/>',NULL,43205,2);
INSERT INTO stanza VALUES('T1151','beginning-note','Apocalipsis 22<br/>',NULL,43206,1);
INSERT INTO stanza VALUES('T1151','1','Uminom! Sa ilog na nagmula sa trono;<br/>Kumain! May puno ng buhay, bunga''y punô;<br/>Di na kailangan ang ilaw pagka''t tingnan mo<br/>Wala nang gabì.<br/>',NULL,43207,2);
INSERT INTO stanza VALUES('T1151','chorus','Lapit, may sabi, Espiritu''t Nobya,<br/>Lapit o lapit, o magpaunlak na.<br/>Uhaw, dumulog, makibahagi na<br/>Kunin ang tubig ng buhay!<br/>',NULL,43208,3);
INSERT INTO stanza VALUES('T1151','2','Kristo — ang tubig ng buhay sa loob natin;<br/>Kristo — ang punong dapat nating tamasahin;<br/>Kristo — ang ilaw at maningning na bituin:<br/>Siya''ng lahat-lahat!<br/>',NULL,43209,4);
INSERT INTO stanza VALUES('T1151','3','Puno ng buhay kanin, at damit linisin;<br/>Tawag "O Panginoon, Amen, Aleluya!"<br/>Ensayuhin ang ''spiritu, Siya''y daranasin.<br/>Siya''y masagana!<br/>',NULL,43210,6);
INSERT INTO stanza VALUES('T1151','4','Ang tahanan nati''y tunay na mal''walhati,<br/>Pagkakaisa natin — tunay na maigi.<br/>Sa pagpupulong natin, Siya ang ''tinatanghal<br/>Sa ekklesia lokal.<br/>',NULL,43211,8);
INSERT INTO stanza VALUES('T1152','1','Kay Hesus araw-araw puso''y napapalapit,<br/>Siya''y maganda''t sariwa sa umaga nang higit,<br/>Lalo Siya sa lahat na sa Kanya''y masasambit<br/>Bawa''t araw Siya ay higit na kaibig-ibig.<br/>',NULL,43212,1);
INSERT INTO stanza VALUES('T1152','chorus','O hindi masayod na masaganang yaman,<br/>Bawa''t araw Siya ay mas mahal kaysa nagdaan!<br/>',NULL,43213,2);
INSERT INTO stanza VALUES('T1152','2','Nahayag sa ekklesia Kanyang kal''walhatian,<br/>Dito ang kayamanan Niya''y aming natagpuan,<br/>Ang espiritu nami''y binigyang-kasiyahan<br/>Bawa''t araw Siya ay mas mahal kaysa nagdaan.<br/>',NULL,43214,3);
INSERT INTO stanza VALUES('T1152','3','Siya''y nasa loob namin, ''Spiritung buháy ngayon,<br/>Sa Kanyang pagpapahid ang buhay sumusulong!<br/>Malaya tayo sa espiritung nagpupulong,<br/>Sapagka''t ngayon Siya ay mas mahal kaysa noon.<br/>',NULL,43215,5);
INSERT INTO stanza VALUES('T1152','4','Panginoon ginagawa tayong kaisa Niya,<br/>Para sa Kanyang pagbabawi upang makita<br/>Ng mga tao ang yaman ni Kristo''t ekklesia,<br/>Kaya binibigay namin ang lahat sa Kanya.<br/>',NULL,43216,7);
INSERT INTO stanza VALUES('T1153','1','Si Kristo''y ating nasumpungan,<br/>Bilang lahat-lahat Siya;<br/>Anong l''walhati, kabanalan,<br/>Tumawag sa ngalan Niya!<br/>',NULL,43217,1);
INSERT INTO stanza VALUES('T1153','chorus','May galak na di masayod, may l''walhati,<br/>May l''walhati, may l''walhati;<br/>May galak na di masayod, may l''walhati,<br/>Di-masambit ni kalahati!<br/>',NULL,43218,2);
INSERT INTO stanza VALUES('T1153','2','Kristong ''Spiritu''y nasumpungan<br/>Sa atin nananahan;<br/>Kay lapit, anong pakinabang,<br/>Ubod ng katamisan.<br/>',NULL,43219,3);
INSERT INTO stanza VALUES('T1153','3','Paraan nasumpungan natin,<br/>Nang Kristo''y dakilain,<br/>Salita''y ibasa-dalangin,<br/>Ang ngalan Niya''y tawagin.<br/>',NULL,43220,5);
INSERT INTO stanza VALUES('T1153','4','Ekklesia lokal nasumpungan<br/>Ngayon ating tahanan;<br/>Babilonia''y di babalikan;<br/>Ekklesia ang kailangan.<br/>',NULL,43221,7);
INSERT INTO stanza VALUES('T1153','5','Ang pulong ating nasumpungan,<br/>Kay laking kagalakan!<br/>Espiritu may kasiglahan,<br/>Buhay may kabuluhan!<br/>',NULL,43222,9);
INSERT INTO stanza VALUES('T1154','beginning-note','Awit ng mga Awit<br/>',NULL,43223,1);
INSERT INTO stanza VALUES('T1154','1','Hesus, mahal ko, akitin ako.<br/>Batakin Mo akong humabol sa Iyo,<br/>Batakin Mo akong humabol sa Iyo.<br/>Ikaw ang Sinta, lubhang kaibig-ibig,<br/>Ang ginigiliw ng puso ko.<br/>Ikaw ang Sinta, lubhang kaibig-ibig,<br/>Ang ginigiliw ng puso ko.<br/>',NULL,43224,2);
INSERT INTO stanza VALUES('T1154','2','Ang Iyong pagsinta''y napakatamis,<br/>Tuwa ng puso ang bango ng Iyong langis,<br/>Tuwa ng puso ang bango ng Iyong langis.<br/>Balon ng buhay, bukal Ka nga ng hardin,<br/>Mga batis galing Libano.<br/>Balon ng buhay, bukal Ka nga ng hardin,<br/>Mga batis galing Libano.<br/>',NULL,43225,3);
INSERT INTO stanza VALUES('T1154','3','Hanging hilaga, hanging timugan,<br/>O humihip ka sa aking halamanan,<br/>Upang sumalimuo''y ang kabanguhan.<br/>Kasi, kapatid; pumasa Aking hardin,<br/>Alak, gatas, pulot, kainin.<br/>Kasi, kapatid; pumasa Aking hardin,<br/>Alak, gatas, pulot, kainin.<br/>',NULL,43226,4);
INSERT INTO stanza VALUES('T1154','4','Hesus, puso Mo, iukit ako;<br/>Mabagsik gaya ng Sheol ang panibugho,<br/>Sinlakas kamatayan ang pag-ibig Mo.<br/>Hindi masasawata ang Iyong pag-ibig,<br/>Ng pagbaha ng lubhang tubig.<br/>Ang makapangyarihan Mo ngang pag-ibig,<br/>Tao, lahat ay hahamakin.<br/>',NULL,43227,5);
INSERT INTO stanza VALUES('T1158','1','Hesus, Panginoong mahal,<br/>Pag-ibig ko''y nakamtan;<br/>Sino ang sa Iyo''y katulad<br/>Sa tamis at karilagan?<br/>Ganda''y di mapaparisan,<br/>At di mapapantayan!<br/>',NULL,43228,1);
INSERT INTO stanza VALUES('T1158','2','Hesus, Panginoong mahal,<br/>Pagtawag Mo''y diringgin;<br/>Lahat ng bagay iniwan,<br/>Nang Iyong tinig mapakinggan;<br/>Paghahanap, kataasan,<br/>Nawalang kabuluhan.<br/>',NULL,43229,2);
INSERT INTO stanza VALUES('T1158','3','Hesus, Panginoong mahal,<br/>Lahat kong katigasan,<br/>Iyukod sa Iyong paanan,<br/>Magbalik nang may awitan;<br/>Naisin ko''t kagalakan,<br/>Ikaw ay paglingkuran.<br/>',NULL,43230,3);
INSERT INTO stanza VALUES('T1158','4','Hesus, Panginoong mahal,<br/>Sumunod mang luhaan,<br/>Pipiliin lang Iyong daan,<br/>At di Kita papalitan.<br/>Hangad ko''y Iyong kaluguran,<br/>At ang kapayapaan.<br/>',NULL,43231,4);
INSERT INTO stanza VALUES('T1158','5','Hesus, Panginoong mahal,<br/>Kapag Ika''y lumisan,<br/>Umaga''y tila naparam,<br/>Ngiti ko ay nakublihan;<br/>Iyong pagdating at presensya,<br/>Aking pinanabikan.<br/>',NULL,43232,5);
INSERT INTO stanza VALUES('T1158','6','Hesus, Panginoong mahal,<br/>Di ko lahat masambit;<br/>Akin Kang pag-ibig tangi,<br/>Kasiyahan at bahagi;<br/>Ikaw lamang iibigin,<br/>Wala nang hahangarin.<br/>',NULL,43233,6);
INSERT INTO stanza VALUES('T1158','7','Hesus, Panginoong mahal,<br/>Lahat ko''y ibibigay;<br/>Kay ganda Mo at kay yumi,<br/>Ika''y kabigha-bighani,<br/>Ganda Mo''y di matularan,<br/>Di Ka mapaparisan!<br/>',NULL,43234,7);
INSERT INTO stanza VALUES('T1159','1','Hesus sa Iyong ganda ay nabihag,<br/>Puso ko sa Iyo''y binubuksan;<br/>Sa panrelihiyong gawa''y ikalag<br/>Sa Iyo manahan, ''ko''y tulutan.<br/>Punuin liwanag ang puso ko,<br/>Habang Iyong gloria minamasdan;<br/>Iyong Espiritu sa ''kin ihalo,<br/>Panginoon ako''y puspusan.<br/>',NULL,43235,1);
INSERT INTO stanza VALUES('T1159','2','Hesus, Ikaw ang Siyang nagniningning,<br/>Anak ng Tao sa luklukan;<br/>Ako''y tupukin upang magningning<br/>Ng Kristo sa ''king katauhan.<br/>Nang nasinag Iyong kal''walhatian,<br/>Pagl''walhati sa sarili ko<br/>Tuloy nahulog sa kahihiyan;<br/>Pag-ibig ko''y nabaling sa Iyo.<br/>',NULL,43236,2);
INSERT INTO stanza VALUES('T1159','3','Ang aking alabastrong sisidlan,<br/>Babasagin ko para sa Iyo;<br/>Iyong Ulo aking pinapahiran,<br/>Ang pinakamabuti ay Iyo.<br/>Pangino''n pinakaiibig ko,<br/>Lahat ko''y sa Iyo ibubuhos;<br/>Mamahaling langis nilaan ko,<br/>Pag-ibig para sa Iyong lubos.<br/>',NULL,43237,3);
INSERT INTO stanza VALUES('T1159','4','Sa bundok ng espesia, Irog ko,<br/>Minimithi Kitang makita;<br/>Mula sa bukal ng aking puso,<br/>Uminom Ka''t ''ko''y mapahinga.<br/>Sa Iyo sumisinta di ako lang,<br/>Kundi lahat ng mga banal<br/>Na Iyong kasintahan; nag-aabang<br/>Sa Iyong pagdating, aming Mahal.<br/>',NULL,43238,4);
INSERT INTO stanza VALUES('T1161','beginning-note','Awit ng mga Awit<br/>',NULL,43239,1);
INSERT INTO stanza VALUES('T1161','1','Ang mangingibig ni Kristo,<br/>Gagawin Niyang ganito:<br/>Poste, palankin, higaan,<br/>Putong, kal''walhatian.<br/>',NULL,43240,2);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43241,3);
INSERT INTO stanza VALUES('T1161','2','Subali''t may anino pa,<br/>Kristo di-nas''yahan pa;<br/>Nais Niya ay halamanan<br/>Na maging kasintahan.<br/>',NULL,43242,4);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43243,5);
INSERT INTO stanza VALUES('T1161','3','Paraiso ng granada,<br/>Hennang bulaklak, bunga,<br/>Nardo, azafran at mira;<br/>Tamasa pawang Kanya.<br/>',NULL,43244,6);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43245,7);
INSERT INTO stanza VALUES('T1161','4','Pumitas mira''t espesia,<br/>Pagdating sa hardin Niya.<br/>Kinain pulot-pukyutan,<br/>Ininom alak, gatas.<br/>',NULL,43246,8);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43247,9);
INSERT INTO stanza VALUES('T1161','5','Lunsod mulang halamanan,<br/>Materyal natustusan;<br/>Diyos lubusang nasiyahan,<br/>Nasindak ang kalaban.<br/>',NULL,43248,10);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43249,11);
INSERT INTO stanza VALUES('T1161','6','"Gaya ng Tirsa, maganda,<br/>Kahali-halina ka,<br/>Katulad ng Herusalem."<br/>Gagawin Mo nga! Amen!<br/>',NULL,43250,12);
INSERT INTO stanza VALUES('T1161','chorus','Kanyang sinta — kay mahal Niya;<br/>Nakakaakit nga siya.<br/>Sa tingin Niya siya''y marilag,<br/>Lubusan Siyang nabihag.<br/>',NULL,43251,13);
INSERT INTO stanza VALUES('T1163','beginning-note','Juan 15<br/>',NULL,43252,1);
INSERT INTO stanza VALUES('T1163','1','Siyang puno, tayo ang sanga;<br/>Manatili sa Kanya;<br/>Bilang agos ng buhay Siya,<br/>Sa atin manahan nga.<br/>',NULL,43253,2);
INSERT INTO stanza VALUES('T1163','chorus','Sa puno ng ubas,<br/>Sa puno ng ubas,<br/>Makikilala Kang husto,<br/>Manatili sa puno.<br/>',NULL,43254,3);
INSERT INTO stanza VALUES('T1163','2','Marinig Kanyang salita,<br/>Nananahang Salita;<br/>Maging tapat manatili,<br/>Sa salitang narinig.<br/>',NULL,43255,4);
INSERT INTO stanza VALUES('T1163','chorus','Sa puno ng ubas,<br/>Sa puno ng ubas,<br/>Makikilala Kang husto,<br/>Manatili sa puno.<br/>',NULL,43256,5);
INSERT INTO stanza VALUES('T1163','3','Sa malalim na paraan,<br/>Pananahan nalaman;<br/>Kung Kristo''y lubos ibigin,<br/>Kanyang salita''y sundin.<br/>',NULL,43257,6);
INSERT INTO stanza VALUES('T1163','chorus','Sa puno ng ubas,<br/>Sa puno ng ubas,<br/>Makikilala Kang husto,<br/>Manatili sa puno.<br/>',NULL,43258,7);
INSERT INTO stanza VALUES('T1163','4','Pag-ibig Niyang nananahan,<br/>Sa atin ay malaman,<br/>Galak ng pagsalamuha,<br/>Ganap, sakdal armoniya.<br/>',NULL,43259,8);
INSERT INTO stanza VALUES('T1163','chorus','Sa puno ng ubas,<br/>Sa puno ng ubas,<br/>Makikilala Kang husto,<br/>Manatili sa puno.<br/>',NULL,43260,9);
INSERT INTO stanza VALUES('T1163','5','Pananahan kay halaga!<br/>Kay talik, kay tamis nga!<br/>Bunga ng buhay dumagdag,<br/>Kumpleto ating galak.<br/>',NULL,43261,10);
INSERT INTO stanza VALUES('T1163','chorus','Sa puno ng ubas,<br/>Sa puno ng ubas,<br/>Makikilala Kang husto,<br/>Manatili sa puno.<br/>',NULL,43262,11);
INSERT INTO stanza VALUES('T1165','1','Aleluya, sa lupain!<br/>Si Kristo''y ating lupain!<br/>Ang Panginoo''y purihin!<br/>Si Kristo''y ating lupain!<br/>',NULL,43263,1);
INSERT INTO stanza VALUES('T1165','chorus','Pulot-pukyutan, gatas Siya;<br/>Butil, langis, at alak pa.<br/>Tayo ay nasa lupain!<br/>Aleluya sa lupain!<br/>',NULL,43264,2);
INSERT INTO stanza VALUES('T1165','2','Dito ay maraming yaman:<br/>Trigo at mga ubasan,<br/>Mga bukal umaagos,<br/>Tinapay na di maubos!<br/>',NULL,43265,3);
INSERT INTO stanza VALUES('T1165','chorus','Kasaganaan ng bunga<br/>Sa araw-araw gumawa;<br/>Sa pulong ating dadalhin,<br/>Kristo''y ating ihahain!<br/>',NULL,43266,4);
INSERT INTO stanza VALUES('T1170','beginning-note','Awit 23<br/>',NULL,43267,1);
INSERT INTO stanza VALUES('T1170','1','Aking Pastol Panginoon ko,<br/>Pinahihiga ako;<br/>Ako rin pinapatnubayan<br/>Siya''y aking kasiyahan!<br/>',NULL,43268,2);
INSERT INTO stanza VALUES('T1170','chorus','Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tatahan sa bahay Niya magpakailanman,<br/>Magpiging sa dulang pinaghandaan.<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>',NULL,43269,3);
INSERT INTO stanza VALUES('T1170','2','Aking Panginoo''y pastulan,<br/>Tubig ng kapahingahan;<br/>Yaman Niya''y aking kinakain;<br/>Siya ay tunay na inumin.<br/>',NULL,43270,4);
INSERT INTO stanza VALUES('T1170','chorus','Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tatahan sa bahay Niya magpakailanman,<br/>Magpiging sa dulang pinaghandaan.<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>',NULL,43271,5);
INSERT INTO stanza VALUES('T1170','3','Pinapanauli kalul''wa,<br/>Damdamin, isip, pagpasya;<br/>Sa lambak man ako''y lumakad,<br/>Siya rin ay Kasamang tapat.<br/>',NULL,43272,6);
INSERT INTO stanza VALUES('T1170','chorus','Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tatahan sa bahay Niya magpakailanman,<br/>Magpiging sa dulang pinaghandaan.<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>',NULL,43273,7);
INSERT INTO stanza VALUES('T1170','4','Dulang hinanda ng Pastol ko,<br/>Sa harap ng kaaway ko,<br/>Ulo ko''y pinahirang langis,<br/>Saro ko''y umapaw labis.<br/>',NULL,43274,8);
INSERT INTO stanza VALUES('T1170','chorus','Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tatahan sa bahay Niya magpakailanman,<br/>Magpiging sa dulang pinaghandaan.<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>',NULL,43275,9);
INSERT INTO stanza VALUES('T1170','5','Ngayon sa bahay Niya nanahan,<br/>Ano ngang katamasahan!<br/>''Di masambit-sambit lugod ko,<br/>Ang lugod ko''y Hesus Mismo!<br/>',NULL,43276,10);
INSERT INTO stanza VALUES('T1170','chorus','Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>Tatahan sa bahay Niya magpakailanman,<br/>Magpiging sa dulang pinaghandaan.<br/>Tunay buti''t awa susundan ako<br/>Sa buong, sa buong buhay ko!<br/>',NULL,43277,11);
INSERT INTO stanza VALUES('T1172','1','Panahon ng paglalaban<br/>Nasa atin ngayon,<br/>Ang lakas ng himagsikan,<br/>Hanay na paayon.<br/>Ang pagka-tao ni Hesus,<br/>Ating makamtan na,<br/>Wangis Niya''t kapangyarihan,<br/>Mahayag sa lupa.<br/>',NULL,43278,1);
INSERT INTO stanza VALUES('T1172','chorus','Lahat tayo''y tumindig,<br/>Sa buhay ni Hesus,<br/>Gandang-asal nanaig<br/>Sa samang kay lipos;<br/>Paglusob ng kasamaan,<br/>Ng likong kapanahunan,<br/>Ang pagka-tao ni Hesus<br/>Ekklesia''y magtanyag.<br/>',NULL,43279,2);
INSERT INTO stanza VALUES('T1172','2','Tingnan, Satanas sinira<br/>Buhay natin dito;<br/>Nguni''t ating Panginoon<br/>Nagbangon ng tao!<br/>Siya ang binhi ng babaeng<br/>Nagkatawang-tao,<br/>Taong Hesus — huling Adam—<br/>Satanas tinalo!<br/>',NULL,43280,3);
INSERT INTO stanza VALUES('T1172','3','Ngayon tawagin, inumin,<br/>Kainin si Hesus,<br/>Pagka-tao''y tamasahin,<br/>Diyablo''y matutuos.<br/>Sa Panginoon bumaling,<br/>Kalul''wa''y itatwa;<br/>Gawa ng diyablo''y wasakin<br/>Bagong tao''y ''handa.<br/>',NULL,43281,5);
INSERT INTO stanza VALUES('T1172','4','Tingnan bansang napinsala<br/>At gumon sa sala;<br/>Sangkatauha''y natisod<br/>At napakasama.<br/>O anak ng kaharian<br/>Asinan ang lupa;<br/>Magaling Niyang pagka-tao<br/>Napreserba tayo.<br/>',NULL,43282,7);
INSERT INTO stanza VALUES('T1174','1','Anong pagwagi''t panalo!<br/>Diyos Mismo naging tao,<br/>Binihis likas ng tao,<br/>Tinupad Kanyang plano.<br/>Sa krus winasak ang diyablo;<br/>Buháy, Anak ng Tao!<br/>',NULL,43283,1);
INSERT INTO stanza VALUES('T1174','2','Sa pantaong kagalingan<br/>Ang tusô nahadlangan,<br/>Bilang tao Kanyang talo<br/>Ang diyablong manunukso.<br/>Sa ''spiritu taglay ko na,<br/>Tanang kagalingan Niya.<br/>',NULL,43284,2);
INSERT INTO stanza VALUES('T1174','3','Sa Espiritu ni Hesus,<br/>Pinong buhay Niya''y lubos;<br/>Naragdag galing pantao<br/>Sa ''Spiritung dibino.<br/>Kay sagana ng ''Spiritu,<br/>Tustos sa tanang tao.<br/>',NULL,43285,3);
INSERT INTO stanza VALUES('T1174','4','Kay hiwaga kay totoo,<br/>Siya''y buhay sa loob ko;<br/>Kumakalat sa ''king puso—<br/>Siya''y pantaong buhay ko.<br/>Aleluya! Aleluya!<br/>Aking pupurihin Siya.<br/>',NULL,43286,4);
INSERT INTO stanza VALUES('T1174','5','Mal''walhati, namamangha,<br/>Sa laman Diyos nakita!<br/>Tayo''y sangkap ng Katawan<br/>At Kanyang kahayagan.<br/>Taglay buhay Niyang pantao,<br/>Para sa pagtatayo.<br/>',NULL,43287,5);
INSERT INTO stanza VALUES('T1178','1','Kristo''ng realidad nakita:<br/>Nguni''t di sapat na makita:<br/>Sa ating karanasan dapat<br/>Siya''y maging lahat.<br/>Sa dalangin masdan mukhaan,<br/>Biyaya sa pulong, Salita;<br/>Nguni''t ano Siya sa buhay at<br/>Sa bawa''t lugar?<br/>',NULL,43288,1);
INSERT INTO stanza VALUES('T1178','chorus','Aleluya! Sa liwanag Niya<br/>O, nakitang tunay, puspos Siya<br/>Kung tayo''y babaling lang sa<br/>bawa''t panahon, araw,<br/>Bawa''t bagay, paraan at—<br/>Sa realidad maging tiyak!<br/>Pagsasagawa ay panlahat!<br/>Kung maukol tayo sa Kanya<br/>Sa atin Siya''y lahat.<br/>',NULL,43289,2);
INSERT INTO stanza VALUES('T1178','2','Tinakda ng kamay ng Ama<br/>Pagkakataon sa buhay nga:<br/>Lahat ng bagay ay magaling,<br/>Kristo''y tamuhin!<br/>Kristong taglay at realidad<br/>Nang sa atin ay magliwanag:<br/>Sa iyo dapat ay magdaan Siya,<br/>Maging sa akin.<br/>',NULL,43290,3);
INSERT INTO stanza VALUES('T1178','chorus','Aleluya! Taglay natin sa<br/>Katawan ang kamatayan Niya:<br/>Nang lahat buhay Niya ay makita<br/>Taong panlabas nabasag,<br/>Panloob nama''y nagniningning—<br/>Sa sisidlang lupa''y makita<br/>Ang kayamanang realidad!<br/>Ang liwanag ng ebanghelyo<br/>Magniningning sa ''tin.<br/>',NULL,43291,4);
INSERT INTO stanza VALUES('T1178','chorus','Di lang doktrina''t teolohiya,<br/>Nilalaman ng realidad:<br/>Kristo''ng lahat sa iyo''t sa akin,<br/>Siya''y lahat sa atin!<br/>',NULL,43292,5);
INSERT INTO stanza VALUES('T1180','1','Aking lumang tao tapos na<br/>Sa krus namatay kasama Niya,<br/>Ngayon ay walang silbi na siya,<br/>Patay na siya.<br/>Bagong Tao sa ''spiritu ko,<br/>Nananahan at bumubugso,<br/>Dumadaloy upang mapuno,<br/>Bawa''t parte ko.<br/>',NULL,43293,1);
INSERT INTO stanza VALUES('T1180','chorus','Persona ko sa espiritu,<br/>Lagi sa Kanya ang puso ko,<br/>Nang magkaroon ng tahanan<br/>Panloob na tao ko;<br/>Masabing sarili Niya at—<br/>Maging ganap kong realidad,<br/>Sa akin lubos na mahayag,<br/>Sa puso''y mamuhay sagana<br/>Bilang Persona.<br/>',NULL,43294,2);
INSERT INTO stanza VALUES('T1180','2','Sa paghubog nitong Persona,<br/>Naging sangkap ng Katawan Niya,<br/>Sa pagkilos, banal kasama,<br/>Di mag-isa.<br/>Kailangan ko aking Persona,<br/>Nang sarili ko mawala na,<br/>Hanggang mapawi nang lubusan,<br/>Kristo''y lahat.<br/>',NULL,43295,3);
INSERT INTO stanza VALUES('T1180','chorus','Kristo lamang Persona natin,<br/>Bitiwan sariling layunin,<br/>Hanggang ekklesia''y Kristo na rin.<br/>Nai-tayo bagong tao,<br/>Matupad ang Kanyang plano;<br/>Nahalo sa sangkatauhan<br/>Nang matamo wastong tahanan,<br/>Mai-tatag Kanyang kaharian<br/>Sa kalupaan.<br/>',NULL,43296,4);
INSERT INTO stanza VALUES('T1180','chorus','Hindi indibiduwal na Kristo,<br/>Kundi pati ekklesiang buo;<br/>Kunin si Kristo bilang tanan,<br/>Tao ay gumulang.<br/>',NULL,43297,5);
INSERT INTO stanza VALUES('T1187','beginning-note','Hebreo 8<br/>',NULL,43298,1);
INSERT INTO stanza VALUES('T1187','1','Ang ministeryo Mo,<br/>Ekselente ito;<br/>Mas mabuting tipan,<br/>Pangakong kay inam;<br/>Batayan kay buting utos.<br/>Tagapagtupad Kang lubos.<br/>',NULL,43299,2);
INSERT INTO stanza VALUES('T1187','2','Mas mabuting tipan,<br/>Pangakong kay inam;<br/>Mas mabuting utos<br/>Pagka''t buhay lubos.<br/>Matupad gawang pagtubos,<br/>Mas mabuting dugo ''buhos.<br/>',NULL,43300,3);
INSERT INTO stanza VALUES('T1187','3','Sa Hebreo walo,<br/>Lalakas nga tayo;<br/>Buhay na tinanim<br/>Sa kalul''wa''y lalin.<br/>Utos ng buhay inukit<br/>Sa damdamin, pasya''t isip.<br/>',NULL,43301,4);
INSERT INTO stanza VALUES('T1187','4','Huwag ka nang babalik,<br/>Sa utos ng titik;<br/>Dapat habulin ay<br/>Ang utos ng buhay.<br/>Titik patay na, luma pa,<br/>Buhay ay bago''t sariwa.<br/>',NULL,43302,5);
INSERT INTO stanza VALUES('T1187','5','Ang utos ng buhay,<br/>Sa loob taglayin;<br/>Gumagawang kusa,<br/>Di ang pasya natin;<br/>Mapuspos, mawangis sukat,<br/>Sa loob natin kakalat.<br/>',NULL,43303,6);
INSERT INTO stanza VALUES('T1187','6','Sala''y napatawad,<br/>Buhay naigawad;<br/>Diyos ngayo''y Diyos natin,<br/>Tayo''y bayan Niya rin.<br/>Sa loob batid natin Siya,<br/>Atin na ang pagpapala.<br/>',NULL,43304,7);
INSERT INTO stanza VALUES('T1187','7','Magiging anak na;<br/>Buhay Niya''y gagawa<br/>Transpormang gawain,<br/>Tayo''y babaguhin.<br/>Tapos na ang panalangin—<br/>Anak ating pupurihin!<br/>',NULL,43305,8);
INSERT INTO stanza VALUES('T1188','beginning-note','Hebreo 8<br/>',NULL,43306,1);
INSERT INTO stanza VALUES('T1188','1','Sa trono ni Hesu-Kristo,<br/>Dinala Niya tayo.<br/>Mundo, Diyablo, ako''t sala<br/>Nasa ilalim na!<br/>Tapos na gawa ni Kristo,<br/>Humahantong dito;<br/>Di na kawawang maysala,<br/>Ganap l''walhati na.<br/>',NULL,43307,2);
INSERT INTO stanza VALUES('T1188','2','Nanahan sa bahay ng Diyos,<br/>Mal''walhating lubos.<br/>Mababang Kristiyanong buhay,<br/>Di ang ating taglay!<br/>Pagpasya, isip, damdamin<br/>Atin nang lisanin;<br/>Sa Kabanal-banalan nga<br/>Tayo''y mapuno Niya.<br/>',NULL,43308,3);
INSERT INTO stanza VALUES('T1188','3','Tayo''y nasa Bagong Tipan:<br/>Buhay kautusan,<br/>Transpormasyon ay lubusan,<br/>May kal''walhatian;<br/>Diyos natin Siya, tayo''y bayan—<br/>Anong katunayan;<br/>Sa panloob Diyos malaman,<br/>Kaya nang lubusan.<br/>',NULL,43309,4);
INSERT INTO stanza VALUES('T1188','4','Diyos nagbigay karagdagan;<br/>Dapat maalaman:<br/>Sala''y pinawi ni Hesus,<br/>Nilimot nang lubos;<br/>Dalawang libong taon na<br/>Ito''y naganap nga.<br/>Ngayo''y utos ng buhay na,<br/>Sa ''tin nagdadala.<br/>',NULL,43310,5);
INSERT INTO stanza VALUES('T1188','5','Ekonom''ya ng Diyos natin,<br/>Dalawa''ng nagawa:<br/>Utos ng buhay, at sala<br/>Tinapos sa krus nga.<br/>Nang matapos gawain Niya,<br/>Siya ay nagpahinga.<br/>Ngayon Siya''y nananalangin<br/>Mana''y kamtin natin.<br/>',NULL,43311,6);
INSERT INTO stanza VALUES('T1188','6','Bitiwan lumang konsepto,<br/>Kunin daang wasto;<br/>Ang bawa''t mana gamitin,<br/>Ikaw ay purihin.<br/>Mataas na Saserdote,<br/>Lalapit na kami—<br/>Hanggang maabot layunin:<br/>Bagong Herusalem!<br/>',NULL,43312,7);
INSERT INTO stanza VALUES('T1191','1','Bukal dumadaloy mula sa ''spiritu,<br/>Umaagos Diyos Tres-uno;<br/>Ama''y pinagmulan, Kristong Anak gabay,<br/>''Spiritu''y nagbigay-buhay.<br/>',NULL,43313,1);
INSERT INTO stanza VALUES('T1191','chorus','Agos-buhay, pahalagahan,<br/>Buhay-kaluluwa''y bitiwan;<br/>Palalimin ang agos-buhay,<br/>Pagdating Mo, putong mataglay.<br/>',NULL,43314,2);
INSERT INTO stanza VALUES('T1191','2','Sa lunting pastulan, ako''y pinahiga,<br/>Sa batis ako''y dinala;<br/>Di na magpumiglas, di na magsumikap,<br/>Sa agos, pagpapala''y ganap.<br/>',NULL,43315,3);
INSERT INTO stanza VALUES('T1191','3','Tinawag Niya ''ko sa kabanal-banalan,<br/>Mamuhay sa presensya Niya;<br/>"Manatili," salita Niya''y napakinggan,<br/>''Pagka''t Siya''ng puno, ako''y sanga.<br/>',NULL,43316,5);
INSERT INTO stanza VALUES('T1193','1','Buhay — Diyos Ama kay Kristo Hesus,<br/>''Spiritu sa atin umagos;<br/>Katama-tamasa''t kamangha-mangha!<br/>Siya''y ating buhay, kay sagana.<br/>',NULL,43317,1);
INSERT INTO stanza VALUES('T1193','2','Pagkasilang-muli naranasan,<br/>Nang sa Kanya tayo''y nabuksan;<br/>Pumasok isang buhay pa na bago,<br/>Kailangan Siya sa ''tin lumago.<br/>',NULL,43318,2);
INSERT INTO stanza VALUES('T1193','3','''Spiritung buháy sa loob natin,<br/>Mula sa loob paagusin,<br/>Ang bawa''t bahagi ay transpormahin,<br/>Buhay na Siya ang nagbigay rin.<br/>',NULL,43319,3);
INSERT INTO stanza VALUES('T1193','4','Kay Kristo nga makipagtulungan,<br/>Sa Anak ilagak isipan,<br/>Lahat na nakaliligaw iwasan,<br/>Isip sa Kanya ituon lang.<br/>',NULL,43320,4);
INSERT INTO stanza VALUES('T1193','5','Espiritu namin ay taglay Ka,<br/>Layon sa amin isagawa;<br/>Kung iwan ng isip lumang akala,<br/>Buhay at payapa makita.<br/>',NULL,43321,5);
INSERT INTO stanza VALUES('T1193','6','Bihagin nawa ang kaisipan<br/>Ng mayamang katamasahan,<br/>Sa Iyong Salitang nagbibigay tustos,<br/>Nang isip mapabanal lubos.<br/>',NULL,43322,6);
INSERT INTO stanza VALUES('T1193','7','Isagawa ang pamumuhay nga,<br/>Sa Anak ang isip ilagak,<br/>Purihin Si-ya! daan ipamuhay,<br/>Aming isip Ikaw mataglay.<br/>',NULL,43323,7);
INSERT INTO stanza VALUES('T1194','1','May dalawang linya maipamuhay ngayon—<br/>Ang linya ng buhay tungo sa Panginoon<br/>At ang kaalaman tungong kamatayan.<br/>Sa aling linya manatili, pag-ingatan.<br/>',NULL,43324,1);
INSERT INTO stanza VALUES('T1194','chorus','O, sa linya ng buhay tayo manatili,<br/>''Di sa kaalaman, kamatayan ang sanhi.<br/>Panginoon, hipuin at tawagin Ka;<br/>Mamuhay sa Iyong pagpapakita''t presensya.<br/>',NULL,43325,2);
INSERT INTO stanza VALUES('T1194','2','Matulad kami kay Abel, kaugnayin Ka,<br/>''Di sa konsepto kundi sa buhay sariwa,<br/>Tulad ni Enos sa Iyong ngalan tumawag,<br/>Katulad ni Enoc kasama Kang lumakad.<br/>',NULL,43326,3);
INSERT INTO stanza VALUES('T1194','chorus','O, sa linya ng buhay tayo manatili,<br/>''Di sa kaalaman, kamatayan ang sanhi.<br/>Panginoon, hipuin at tawagin Ka;<br/>Mamuhay sa Iyong pagpapakita''t presensya.<br/>',NULL,43327,4);
INSERT INTO stanza VALUES('T1194','3','Mamuhay, lumakad katulad ni Abraham;<br/>Sa Iyong pagpapakitang banal, malalinan.<br/>Sina Isaac, Jacob, Moises gayundin,<br/>Sa Iyong presensya, sila''y nakadepende rin.<br/>',NULL,43328,5);
INSERT INTO stanza VALUES('T1194','chorus','O, sa linya ng buhay tayo manatili,<br/>''Di sa kaalaman, kamatayan ang sanhi.<br/>Panginoon, hipuin at tawagin Ka;<br/>Mamuhay sa Iyong pagpapakita''t presensya.<br/>',NULL,43329,6);
INSERT INTO stanza VALUES('T1194','4','David lubos tinamasa puno ng buhay;<br/>Daniel nama''y sa Diyos araw-araw namuhay.<br/>Hesus bilang buhay namuhay sa Ama,<br/>Puno''y kainin natin bilang Katawan Niya.<br/>',NULL,43330,7);
INSERT INTO stanza VALUES('T1194','chorus','O, sa linya ng buhay tayo manatili,<br/>''Di sa kaalaman, kamatayan ang sanhi.<br/>Panginoon, hipuin at tawagin Ka;<br/>Mamuhay sa Iyong pagpapakita''t presensya.<br/>',NULL,43331,8);
INSERT INTO stanza VALUES('T1195','1','Kay hiwaga ng buhay, Diyos Mismo,<br/>Layon Niya nakatuon sa tao;<br/>Puno ng buhay dapat sa tao,<br/>Upang may buhay ayon sa plano.<br/>',NULL,43332,1);
INSERT INTO stanza VALUES('T1195','2','Tao''y natukso sa kasalanan,<br/>Kaalaman, ibang pinagmulan.<br/>Sa tao''y naglugmok kaalaman<br/>At siya''y lubos pinangibabawan.<br/>',NULL,43333,2);
INSERT INTO stanza VALUES('T1195','3','Kaalaman sa tao umunlad,<br/>Dito''y naging kultura ng tao;<br/>Plano di natupad ng nilikha,<br/>Dahil kay Satanas, dahop, bigo.<br/>',NULL,43334,3);
INSERT INTO stanza VALUES('T1195','4','Nagsapersona sa Anak ang Diyos;<br/>Sa lupa tumahan, ngalan Hesus—<br/>Isang buhay huwaran sa tanan,<br/>Buhay ipamuhay nang puspusan.<br/>',NULL,43335,4);
INSERT INTO stanza VALUES('T1195','5','Diyos-taong Kristo sa krus namatay,<br/>Tinapos sa Kanyang pagkamatay<br/>Ang kaalaman at lumang tao,<br/>Supil kamatayan, bagong buhay!<br/>',NULL,43336,5);
INSERT INTO stanza VALUES('T1195','6','Mula kamatayan Siya''y nabuhay,<br/>Espiritung nagbibigay-buhay;<br/>Nananalig, ngalan Niya''y tawagin,<br/>Espiritu''y nanahan sa atin.<br/>',NULL,43337,6);
INSERT INTO stanza VALUES('T1195','7','Tres-unong Diyos ngayo''y humahalo<br/>Bilang ''Spiritung buháy sa loob.<br/>Espiritu natin nakiisa,<br/>Magpakailanman kaisa na Niya.<br/>',NULL,43338,7);
INSERT INTO stanza VALUES('T1195','8','Lakad tayo sa ''Spiritung ito,<br/>Pamumuhay, pag-iisip wasto;<br/>Nasa loob tayo ng ''Spiritu,<br/>Kapuspusan ng Diyos napahusto.<br/>',NULL,43339,8);
INSERT INTO stanza VALUES('T1195','9','Kaya ilagak ang kaisipan<br/>Bawa''t minuto sa Kanya lamang;<br/>Sa ''Spiritung ''to may kaligtasan,<br/>Sa buhay magharing walang hanggan.<br/>',NULL,43340,9);
INSERT INTO stanza VALUES('T1195','10','Sa ''Spiritung ito''y kaligtasan,<br/>Mula sa batas ng kasalanan;<br/>Mortal nating katawan may buhay,<br/>Mapabanal sa lahat ng bagay.<br/>',NULL,43341,10);
INSERT INTO stanza VALUES('T1195','11','Natural na buhay matransporma,<br/>Maligtas mula sa sarili nga;<br/>Hanggang sa mapawangis kay Kristo,<br/>Matupad plano ng Diyos Tres-uno.<br/>',NULL,43342,11);
INSERT INTO stanza VALUES('T1195','12','Buhay ay Diyos at ang Kristo natin,<br/>Buhay Espiritu; buhay daan—<br/>''Pag Diyos, tayo''y baguhin, tubusin,<br/>Ang araw na i-yon hihintayin.<br/>',NULL,43343,12);
INSERT INTO stanza VALUES('T1196','1','Diyos nati''y buháy — O, Aleluya!<br/>Sa loob natin, nananahan Siya!<br/>Tikman yaman Niya,<br/>Bahagi ko Siya.<br/>''O Panginoon,'' tikman nga!<br/>',NULL,43344,1);
INSERT INTO stanza VALUES('T1196','2','Magsama-sama — anong inam nga—<br/>Sa ''spiritu tayo''y pamilya Niya,<br/>Kanyang Katawan,<br/>At kahayagan!<br/>Hesus ang katotohanan.<br/>',NULL,43345,2);
INSERT INTO stanza VALUES('T1196','3','Sa ekklesia tayo''y nasisidlan,<br/>Lahat ng bansa''y mapalaganapan,<br/>Hesus ikalat<br/>Sa bawa''t siyudad—<br/>Kristong buháy makikita.<br/>',NULL,43346,3);
INSERT INTO stanza VALUES('T1197','beginning-note','1 Juan 1:5-7<br/>',NULL,43347,1);
INSERT INTO stanza VALUES('T1197','1','Liwanag ang Diyos, sa Kanya''y walang dilim nga!<br/>O manahan nawa sa presensya Niya!<br/>Sa liwanag paglilinis laging tamasa—<br/>Sa ''ting sala!<br/>',NULL,43348,2);
INSERT INTO stanza VALUES('T1197','chorus','Sisters: Sa ilaw<br/>Brothers: Lumalakad—<br/>Sisters: Sal''muha<br/>Brothers: ''Ting tamasa;<br/>Sisters: Ang dugo<br/>Brothers: Ng Anak<br/>Lahat: Hinugasan tayo.<br/>',NULL,43349,3);
INSERT INTO stanza VALUES('T1197','chorus','Sisters: Inamin<br/>Brothers: Siya ay tapat<br/>Sisters: ''Patawad—<br/>Brothers: Makat''wiran.<br/>Sisters: Masaya!<br/>Brothers: Hugas na<br/>Lahat: Bawa''t sala!<br/>',NULL,43350,4);
INSERT INTO stanza VALUES('T1199','1','Layunin ng Diyos sa sansinukob ay nasa tao,<br/>Siya''y naging Espiritu upang mahalo sa tao.<br/>Sa ekonomiya Niya''y makababahagi tayo.<br/>Daa''y paghahalo.<br/>',NULL,43351,1);
INSERT INTO stanza VALUES('T1199','chorus','Paghahalo, aleluya,<br/>Paghahalo, aleluya,<br/>Paghahalo, aleluya,<br/>Daa''y paghahalo!<br/>',NULL,43352,2);
INSERT INTO stanza VALUES('T1199','2','Sa sentro ng tao, lumalagpas sa kaisipan,<br/>Damdamin, kapasyahan, Panginoo''y may kalagyan.<br/>Kanyang pagdaloy, pagbaha pupunuan Niya tayo;<br/>Daa''y paghahalo.<br/>',NULL,43353,3);
INSERT INTO stanza VALUES('T1199','3','Sa pagbawi ng Panginoon daa''y natagpuan<br/>Upang Tres-unong Diyos mai-pamuhay at maranasan—<br/>Pasok, manatili sa pinaghalong espiritu;<br/>Daa''y paghahalo.<br/>',NULL,43354,5);
INSERT INTO stanza VALUES('T1199','4','Sa gitna ng pitong gintong patungan-ng-ilawan,<br/>May Anak ng Tao para sa pagbabawi ng Diyos.<br/>Sama-samang entidad naibuo Niya nang husto;<br/>Daa''y paghahalo.<br/>',NULL,43355,7);
INSERT INTO stanza VALUES('T1199','5','Sa ating pang-araw-araw na buhay at gawain,<br/>Dapat higit ang paghahalo upang Kristo''y kamtin;<br/>''Binibigay namin ang sarili sa paghahalo.<br/>Daa''y paghahalo.<br/>',NULL,43356,9);
INSERT INTO stanza VALUES('T1199','6','Buhay pang-araw-araw bunga''y Herusalem bago,<br/>Sukdulang paghahalo — ''to''y dibinong pagka-tao.<br/>Anong galak na sama-samang kabahagi tayo.<br/>Daa''y paghahalo.<br/>',NULL,43357,11);
INSERT INTO stanza VALUES('T1205','beginning-note','Filipos 3:10-14<br/>',NULL,43358,1);
INSERT INTO stanza VALUES('T1205','1','Magtumulin tungo sa gol,<br/>Kay Kristo''y maghabol.<br/>Premyo ng pagtawag ng Diyos<br/>Ay tamuhing lubos.<br/>',NULL,43359,2);
INSERT INTO stanza VALUES('T1205','chorus','Habulin! Habulin!<br/>Habulin! Aleluya sa premyo.<br/>Magtumulin! Habulin!<br/>Kristo ng Diyos ''tamo.<br/>',NULL,43360,3);
INSERT INTO stanza VALUES('T1205','2','Magtumulin at ibilang<br/>Lahat kalugihan;<br/>Ang matamo Kristo ng Diyos,<br/>Mal''walhating lubos!<br/>',NULL,43361,4);
INSERT INTO stanza VALUES('T1205','3','Magtumulin, kilanlin Siya''t<br/>Muling pagkabuhay—<br/>Ito''y ating gantimpala,<br/>Kahit nagdurusa!<br/>',NULL,43362,6);
INSERT INTO stanza VALUES('T1205','4','Magtumulin, ito''y gawin,<br/>Lumipas limutin;<br/>Kristo sa harap habulin,<br/>Ang dapat isipin.<br/>',NULL,43363,8);
INSERT INTO stanza VALUES('T1206','beginning-note','Hebreo 12:1-2<br/>',NULL,43364,1);
INSERT INTO stanza VALUES('T1206','1','Takbuhin para sa ''tin — Aleluya,<br/>Takbuhin upang panalunan.<br/>Sa mga nagsimula — Aleluya,<br/>Sabi ng Diyos, "Si Hesus tingnan!"<br/>',NULL,43365,2);
INSERT INTO stanza VALUES('T1206','chorus','Siya''y tingnan! O, Siya''y tingnan!<br/>Ngayon si Hesus tingnan!<br/>Mula sa lahat tumingin kay Hesus,<br/>Tingin ''tuon sa Kanyang lubos!<br/>',NULL,43366,3);
INSERT INTO stanza VALUES('T1206','2','Ang palibot huwag tingnan — Aleluya,<br/>Huwag tingnan ingay, kaguluhan;<br/>Kapayapaan tingnan — Aleluya,<br/>Mula sa lahat Siya ay tingnan.<br/>',NULL,43367,4);
INSERT INTO stanza VALUES('T1206','3','Lumayo sa kalul''wa — Aleluya,<br/>Layuan sariling mahina;<br/>Tumingin tungo sa gol — Aleluya,<br/>Mula sa lahat habulin Siya.<br/>',NULL,43368,6);
INSERT INTO stanza VALUES('T1206','4','Nakalipas talikdan — Aleluya,<br/>Iwanan buti''t kasalanan;<br/>Nabubuhay tanganan — Aleluya,<br/>Lahat ng bagay ay talikdan!<br/>',NULL,43369,8);
INSERT INTO stanza VALUES('T1206','5','Mukha Niya ang siyang tingnan — Aleluya,<br/>Tatapusin Niya sinimulan.<br/>Pagtakbo''y mabiyaya — Aleluya,<br/>Pagtingin sa Kanya tatamo!<br/>',NULL,43370,10);
INSERT INTO stanza VALUES('T1210','beginning-note','Roma 8:17-39<br/>',NULL,43371,1);
INSERT INTO stanza VALUES('T1210','1','Sa salita ng Diyos umaasa,<br/>Katauhan ko''y matubos nga;<br/>Nguni''t sa takot, pagsubok, duda<br/>Wala ng pag-asang makita.<br/>Sandaling hindi makadalangin<br/>Hibik ko lamang maririnig<br/>Sa akin tumulong ang ''Spiritu,<br/>Pinasasa Diyos ang hina ko.<br/>',NULL,43372,2);
INSERT INTO stanza VALUES('T1210','2','Dalangin ko''y di higit na dusa,<br/>Kundi sa subok mapalaya;<br/>Saro ng kapaitan alisin<br/>Nguni''t kalooban Mo pa rin.<br/>Paligiran man ngayon pagsubok,<br/>Puso ko''y payapa ang tibok<br/>Dahil pag-ibig ng Diyos binuhos,<br/>Alinlangan lahat tinapos.<br/>',NULL,43373,3);
INSERT INTO stanza VALUES('T1210','3','Katiyakang pinagpala! Utos,<br/>Dakilang kamay Niya''y nag-ayos;<br/>Bawa''t tao (kahit di makita)<br/>Bawa''t bagay ayon sa Kanya.<br/>Bawa''t pagsubok sagot ng Ama,<br/>Sa dasal ng Espiritu nga;<br/>Magtamo Siya sa bawa''t pighati<br/>Nang maabot Kanyang l''walhati.<br/>',NULL,43374,4);
INSERT INTO stanza VALUES('T1210','4','Sa pagtuos ba ng Diyos iilag,<br/>Kung Diyos tiniis Kanyang Anak?<br/>Iiwan ba ng Magpapalayok<br/>Sisidlang Kanyang nilililok?<br/>Tuon ng nais ng puso ng Diyos<br/>Maraming kapatid malubos.<br/>Tungo kay Kristong Kanyang Panganay,<br/>Sa Kanya ganap maibagay.<br/>',NULL,43375,5);
INSERT INTO stanza VALUES('T1210','5','Kasamang mga tagapagmana<br/>Tayo ni Hesus, anong gloria!<br/>Bagaman dusa ngayon mahirap<br/>Higit namang gloria kaharap.<br/>Dahil sa Kanya sa ''tin umibig<br/>Higit pa tayong nananaig.<br/>Di-lalaon lahat ng nilikha<br/>Mga anak ng Diyos makita!<br/>',NULL,43376,6);
INSERT INTO stanza VALUES('T1211','beginning-note','2 Pedro 1:3-11<br/>',NULL,43377,1);
INSERT INTO stanza VALUES('T1211','1','Sa atin ang Diyos nga ay nagkaloob,<br/>Manalig, kapangyarihan, pangako;<br/>Nanalig, tumanggap, tatlo''y natamo<br/>Sa ganito ay gugulang, lalago.<br/>',NULL,43378,2);
INSERT INTO stanza VALUES('T1211','2','Pananampalatayang mahalaga,<br/>Walang hanggan tayong nahahawakan,<br/>Sang-ayon ma''t hindi, hinahawakan<br/>Araw-araw hanggang sa walang hanggan.<br/>',NULL,43379,3);
INSERT INTO stanza VALUES('T1211','3','Dakilang pinagmulan, kapangyar''han,<br/>Gumagawa sa ''tin kapangyarihan,<br/>Buhay para sa ating kalooban,<br/>Pagkamakadiyos ay sa kahayagan.<br/>',NULL,43380,4);
INSERT INTO stanza VALUES('T1211','4','Pangako, bahagi ng tinawag Niya,<br/>Pangako, dakila at mahalaga;<br/>Kalikasan ng Diyos bahagi natin,<br/>Sa kabulukan ng mundo''y ligtas din.<br/>',NULL,43381,5);
INSERT INTO stanza VALUES('T1211','5','Kristo''y lakas sa espiritu natin,<br/>Siyang Salita — pangako ng Diyos natin;<br/>Espiritu''t Salita, kaugnayin,<br/>Lalago pagtawag, basa''t dalangin.<br/>',NULL,43382,6);
INSERT INTO stanza VALUES('T1211','6','Pananampalataya, kapangyar''han,<br/>Pangako, tatlo''y ating kagamitan;<br/>Lalago ang binhi ng pananalig,<br/>Hahantong maging bunga ng pag-ibig.<br/>',NULL,43383,7);
INSERT INTO stanza VALUES('T1211','7','Sa paglago ng binhi, marami nga<br/>Panginoong Hesus magkakabunga.<br/>Panginoon pa rin ang pinagmulan<br/>Kaya hindi dapat Siyang kalimutan.<br/>',NULL,43384,8);
INSERT INTO stanza VALUES('T1211','8','Kasipagan, araw-araw lalago,<br/>Kasigasigan, paghirang, pihado<br/>Sa binhing ito makipagkaisa,<br/>Kahariang mayaman pasukin nga.<br/>',NULL,43385,9);
INSERT INTO stanza VALUES('T1211','9','Sarili namin sa Iyo binibigay,<br/>Pananalig, lakas Mo''y ipamuhay,<br/>Pangako Mo aming panghawakan pa,<br/>Sa Iyong biyaya kami''y makiisa.<br/>',NULL,43386,10);
INSERT INTO stanza VALUES('T1218','1','Kung sa mundo ay ibig lumaya,<br/>Amen sa Salita!<br/>Katotohana''y ibig madama,<br/>Amen sa Salita!<br/>',NULL,43387,1);
INSERT INTO stanza VALUES('T1218','chorus','Sa Salita ng Diyos,<br/>Mag-amen nang lubos!<br/>Sa Salita''y manampalataya,<br/>Amen sa Salita!<br/>',NULL,43388,2);
INSERT INTO stanza VALUES('T1218','2','Upang tapusin ang kasalanan,<br/>Amen sa Salita!<br/>Upang mabago iyong kaisipan,<br/>Amen sa Salita!<br/>',NULL,43389,3);
INSERT INTO stanza VALUES('T1218','chorus','Sa Salita ng Diyos,<br/>Mag-amen nang lubos!<br/>Salita ay nagbibigay-buhay—<br/>Amen sa Salita!<br/>',NULL,43390,4);
INSERT INTO stanza VALUES('T1218','3','Si Kristo ang Mabuting Lupain—<br/>Amen sa Salita!<br/>Ang puso ay huwag nang patigasin—<br/>Amen sa Salita!<br/>',NULL,43391,5);
INSERT INTO stanza VALUES('T1218','chorus','Sa Salita ng Diyos,<br/>Mag-amen nang lubos!<br/>Salita ay may dalawang talim—<br/>Amen sa Salita!<br/>',NULL,43392,6);
INSERT INTO stanza VALUES('T1218','4','Di magtatagal at babalik Siya—<br/>Amen sa Salita!<br/>Masasabi mo bang handa ka na—<br/>Amen sa Salita!<br/>',NULL,43393,7);
INSERT INTO stanza VALUES('T1218','chorus','Sa salita ng Diyos,<br/>Mag-amen nang lubos!<br/>Handa na dalhin tayo kay Hesus—<br/>Amen sa salita!<br/>',NULL,43394,8);
INSERT INTO stanza VALUES('T1220','1','Pahayag ibigay sa ''kin,<br/>Ang tabing alisin;<br/>Nang makita''ng pagbabawi<br/>Maipamahagi.<br/>[Maipamahagi.<br/>Maipamahagi.<br/>Nang makita''ng pagbabawi<br/>Maipamahagi.]<br/>',NULL,43395,1);
INSERT INTO stanza VALUES('T1220','2','Kapangyarihan ni Kristo,<br/>Sa pahayag ''tanto;<br/>Pananalig tinanggap ko,<br/>Ekklesia tinungo.<br/>[Ekklesia tinungo.<br/>Ekklesia tinungo.<br/>Pananalig tinanggap ko,<br/>Ekklesia tinungo.]<br/>',NULL,43396,2);
INSERT INTO stanza VALUES('T1220','3','Mula bagay makalupa,<br/>Ako''y pinalaya<br/>Ng kapangyarihan Ni-ya<br/>Tungo sa ekklesia.<br/>[Tungo sa ekklesia.<br/>Tungo sa ekklesia.<br/>Ng kapangyarihan Ni-ya<br/>Tungo sa ekklesia.]<br/>',NULL,43397,3);
INSERT INTO stanza VALUES('T1220','4','Ikaw ay aking persona,<br/>Sa ekklesia lokal;<br/>Taong panlabas mawala,<br/>Puso ko''y sa Iyo na.<br/>[Puso ko''y sa Iyo na.<br/>Puso ko''y sa Iyo na.<br/>Taong panlabas mawala,<br/>Puso ko''y sa Iyo na.]<br/>',NULL,43398,4);
INSERT INTO stanza VALUES('T1220','5','Kaisa pinakong Kristo,<br/>Ngayon persona ko;<br/>Taong panloob nabawi,<br/>Tumira sa akin.<br/>[Tumira sa akin.<br/>Tumira sa akin.<br/>Taong panloob nabawi,<br/>Tumira sa akin.]<br/>',NULL,43399,5);
INSERT INTO stanza VALUES('T1220','6','Katawan Mo''y mababatid,<br/>Talikdan sarili;<br/>Kunin namin Persona Mo,<br/>Hayag bagong tao.<br/>[Hayag bagong tao.<br/>Hayag bagong tao.<br/>Kunin namin Persona Mo,<br/>Hayag bagong tao.]<br/>',NULL,43400,6);
INSERT INTO stanza VALUES('T1220','7','Ang ekklesia''y bagong tao,<br/>Katawan ni Kristo;<br/>Nahayag sa lokalidad,<br/>Pagkai-sa natupad.<br/>[Pagkai-sa natupad.<br/>Pagkai-sa natupad.<br/>Nahayag sa lokalidad,<br/>Pagkai-sa natupad.]<br/><!--(Ulitin ang huling dalawang linya ng bawa''t saknong)--><br/>',NULL,43401,7);
INSERT INTO stanza VALUES('T1221','beginning-note','Juan 10<br/>',NULL,43402,1);
INSERT INTO stanza VALUES('T1221','1','Pastol, kagila-gilalas,<br/>Hesus na Panginoon;<br/>Sa kulungan inilabas,<br/>Sa pastulan paroon.<br/>',NULL,43403,2);
INSERT INTO stanza VALUES('T1221','chorus','Buhay-ekklesia,<br/>Pigingang masagana!<br/>Dito''y may pagkakaisa,<br/>Diyos utos pagpapala.<br/>',NULL,43404,3);
INSERT INTO stanza VALUES('T1221','2','Mula sa paghati-hati,<br/>Tayo''y Kanyang hinanap,<br/>Mabuting lupa''y tinungo,<br/>Kay inam sa ''spiritu.<br/>',NULL,43405,4);
INSERT INTO stanza VALUES('T1221','3','Hesus Mismo ang pastulan,<br/>Tunay nating pagkain;<br/>Tupa''y Kanyang tinustusan<br/>Sa pagpupulong natin.<br/>',NULL,43406,6);
INSERT INTO stanza VALUES('T1221','4','Bundok mataas tirahan,<br/>Hamog anong sariwa;<br/>Wala na ang kauhawan,<br/>Tubig buháy sagana.<br/>',NULL,43407,8);
INSERT INTO stanza VALUES('T1221','5','Kristo''y pahinga''t tamasa,<br/>Dito''y walang pangamba;<br/>Sa mayamang presensya Niya,<br/>Tupa''y napepreserba.<br/>',NULL,43408,10);
INSERT INTO stanza VALUES('T1222','beginning-note','Ang Tagalog ay isinalin mula sa Chinese hymnal.<br/>',NULL,43409,1);
INSERT INTO stanza VALUES('T1222','1','Panginoon ng lahat ay awitan,<br/>Siya''y sa Herusalem nananahan.<br/>Kristo''y Hari, langit Kanyang luklukan,<br/>Lahat Niyang gawa''y patotohanan.<br/>O, kaligtasa''y mula sa Sion!<br/>Mula sa pagkabihag inuwi!<br/>Nagagalak, lubhang natutuwa,<br/>Nagagalak, lubhang natutuwa!<br/>',NULL,43410,2);
INSERT INTO stanza VALUES('T1222','2','Purihin si Kristo kapantay ng Diyos,<br/>Para sa ''tin naging Taong lubos;<br/>Nabuhay muli''t nasa luklukan na,<br/>Kanyang yaman ating natamasa.<br/>Purihin Siya nagpuspos sa lahat!<br/>Tayo naging Kanyang kahayagan!<br/>O, anong yaman na kahayagan,<br/>O, anong yaman na kahayagan!<br/>',NULL,43411,3);
INSERT INTO stanza VALUES('T1222','3','Sa ''spiritu ko, espiritu''y buhay;<br/>Relihiyong ritwal walang saysay;<br/>Siya''y tamasa ko sa bawa''t minuto,<br/>Yaman Niya''y naging karanasan ko.<br/>Sa ekklesia lokal, Siya''y purihin!<br/>Lakasan awit sa espiritu!<br/>Siya''y ''Spiritu, sa ekklesia''y Hari,<br/>Siya''y ''Spiritu, sa ekklesia''y Hari!<br/>',NULL,43412,4);
INSERT INTO stanza VALUES('T1222','4','Ekklesia''y mapuspusan l''walhati Niya,<br/>Wagi, patotoo ng ekklesia;<br/>Puno ang espiritu nagpupuri,<br/>Kay Kristong Hari ng mga hari.<br/>Bitiwan pagkamakasarili!<br/>Ginabay tayo ng Espiritu!<br/>Magalak! Siya''y ating inaagos,<br/>Magalak! Siya''y ating inaagos!<br/>',NULL,43413,5);
INSERT INTO stanza VALUES('T1225','1','Kilanlin Ka na Katawan,<br/>Ang siya kong ka-i-langan;<br/>Sa Iyong sangkap makita Ka,<br/>Ang dalangin ko''t nasà.<br/>''Di lamang Iyong pagka-ulo<br/>Mag-isang makita ko<br/>Kundi pagiging tao Mo,<br/>Bilang Katawan — Kristo.<br/>',NULL,43414,1);
INSERT INTO stanza VALUES('T1225','2','Matagal sa Iyo''y humanap,<br/>Hangad ay realidad;<br/>Kahit saan saliksik ko<br/>Uhaw, pagtanaw sa Iyo.<br/>Kristong nasa kalangitan,<br/>Nahayag na Katawan;<br/>Kristo sa loob nanahan,<br/>Hayag bilang Katawan.<br/>',NULL,43415,2);
INSERT INTO stanza VALUES('T1225','3','Ako''y madaling malihis,<br/>Sa matayog na isip;<br/>Madaling sa Iyo maghanap,<br/>Di antig realidad.<br/>Dapat Kitang hanapin nga,<br/>O, sa Iyong mga sangkap.<br/>Sa atin, Diyos walang hanggan.<br/>Nananahan sa laman.<br/>',NULL,43416,3);
INSERT INTO stanza VALUES('T1225','4','Kasarinlan ko''y pigilan,<br/>Magbaling sa Katawan;<br/>Di lang liwanag sa langit,<br/>Bagkus ekklesia rin.<br/>Nawa bato sa pagtayo,<br/>Di luad walang anyo;<br/>Sama-samang mahayag Ka,<br/>Kamtin sa ''min Iyong nasà.<br/>',NULL,43417,4);
INSERT INTO stanza VALUES('T1226','1','Anong l''walhati ng ekklesi-a''t bahagi tayo—<br/>Kay saya Poon pinag-isa tayo!<br/>Isang Katawan sa sansinukob bahagi tayo—<br/>Pinag-isa ng Panginoon tayo!<br/>',NULL,43418,1);
INSERT INTO stanza VALUES('T1226','chorus','Aleluya sa Katawan!<br/>Sangkap tayo ng Katawan!<br/>Lubos para sa Katawan!<br/>Pinag-isa tayo ng Panginoon!<br/>',NULL,43419,2);
INSERT INTO stanza VALUES('T1226','2','''Di na Kristiyanong mapag-isa, kundi sama-sama—<br/>Tamuhin ng Diyos ang kahayagan Niya;<br/>''Di ekklesiang isa-isa, kundi isang Katawan—<br/>Aleluya, tayo''y nasa Katawan!<br/>',NULL,43420,3);
INSERT INTO stanza VALUES('T1226','chorus','Aleluya sa Katawan!<br/>Diyablo''y yanig sa Katawan!<br/>Matagumpay sa Katawan!<br/>Aleluya, tayo''y nasa Katawan!<br/>',NULL,43421,4);
INSERT INTO stanza VALUES('T1226','3','May pitong dibinong gintong patungan-ng-ilawan—<br/>Walang likas na bagay sa Katawan.<br/>Kalikasan ng Diyos kabahagi''t kaisa natin—<br/>Patungan-ng-ilawan nagniningning!<br/>',NULL,43422,5);
INSERT INTO stanza VALUES('T1226','chorus','Aleluya sa Katawan!<br/>Sa patungan-ng-ilawan!<br/>Sa ginintuang Katawan!<br/>Aleluya! Nagniningning na ngayon!<br/>',NULL,43423,6);
INSERT INTO stanza VALUES('T1226','4','Nagkakaisa, maging dibino''t nagniningning pa,<br/>Sa pagkain kay Hesus nakukuha!<br/>Siya ang puno ng buhay, piging laging bago''t manna—<br/>Aleluya, Siya''y kainin tuwina!<br/>',NULL,43424,7);
INSERT INTO stanza VALUES('T1226','chorus','Pagkain natin kay Hesus,<br/>Nagkakaisa nang lubos!<br/>Nagniningning at dibino!<br/>Aleluya! Pagkain ang daan ko!<br/>',NULL,43425,8);
INSERT INTO stanza VALUES('T1230','1','Plano ng Diyos, bagong tao;<br/>Sa tao, tinubos tayo.<br/>Bawa''t angkan at tribo,<br/>Nang sa Kanya''y isa tayo.<br/>Mahayag Diyos sa lupa,<br/>Mal''walhating halaga.<br/>Plano ng Diyos, bagong tao;<br/>Sa tao, tinubos tayo.<br/>',NULL,43426,1);
INSERT INTO stanza VALUES('T1230','2','Ordinansa pinatay na,<br/>Nang dalawa''y maging isa.<br/>Pinagkasundo sa Diyos,<br/>Ulo ng ahas dinurog.<br/>Gitnang pader winasak,<br/>Nang ngalan Niya''y tinawag.<br/>Ordinansa pinatay na,<br/>Nang dalawa''y maging isa.<br/>',NULL,43427,2);
INSERT INTO stanza VALUES('T1230','3','Kunin Ka na Persona,<br/>Kami''y lubos nagkaisa.<br/>Iwan namin sarili,<br/>Sa Katawan kabahagi.<br/>Kay Kristo''y bagong tao,<br/>Angkinin lupang ito.<br/>Kunin Ka na Persona,<br/>Kami''y lubos nagkaisa.<br/>',NULL,43428,3);
INSERT INTO stanza VALUES('T1232','beginning-note','Efeso 2-3<br/>',NULL,43429,1);
INSERT INTO stanza VALUES('T1232','1','Noon likas patay sa sala,<br/>Sa mundong walang pag-asa;<br/>Nguni''t binuhay ng Diyos tayo,<br/>Binangon, luklok kasama ni Kristo.<br/>',NULL,43430,2);
INSERT INTO stanza VALUES('T1232','chorus','Hesus, tayo''y pinagkaisa,<br/>Tingnan, banal nagkakai-sa.<br/>Pag-ibig Niya''y binuklod tayo,<br/>Sa sukat ng kapuspusan ni Kristo.<br/>',NULL,43431,3);
INSERT INTO stanza VALUES('T1232','2','Kasamang banal natatalos,<br/>Kung ano ang sukat ng Diyos.<br/>Ang taas, lalim, lawak, haba,<br/>Nang mapuspusan ng kapuspusan Niya.<br/>',NULL,43432,4);
INSERT INTO stanza VALUES('T1232','3','Alam natin layunin ng Diyos,<br/>Hiwaga''y nakitang lubos:<br/>Kristo''t ekklesia ay nakita,<br/>Magkasamang kaaway ''pinahiya.<br/>',NULL,43433,6);
INSERT INTO stanza VALUES('T1232','4','Sa Amang Diyos nananalangin—<br/>Taong panloob palakasin;<br/>Manahan Ka sa aming puso,<br/>Iyong patatagin para sa Iyong plano.<br/>',NULL,43434,8);
INSERT INTO stanza VALUES('T1232','5','Nagkakalakip sa Katawan,<br/>Bilang sangkap natustusan;<br/>Ayon sa sukat ay gumawa,<br/>Lalago''t mapatibay sa pagsinta.<br/>',NULL,43435,10);
INSERT INTO stanza VALUES('T1232','6','Ngayon sa layon nagkaisa,<br/>Bilang ang bagong tao Niya.<br/>Ekklesiang sa loob ni Kristo,<br/>L''walhati sa Diyos magpakailanpaman!<br/>',NULL,43436,12);
INSERT INTO stanza VALUES('T1233','1','O sa ekklesia na aking tahanan,<br/>Paghahanap nati''y humangga;<br/>Nagagalak ang mga kapatiran<br/>Pagka''t Kristo''y buhay ng tanan.<br/>',NULL,43437,1);
INSERT INTO stanza VALUES('T1233','chorus','O sa ekklesia,<br/>Ang tahanan ko''y natagpuan;<br/>At sa tuwina<br/>Pupurihin ko Siya!<br/>"Aleluya — Kristo''t ekklesia!"<br/>',NULL,43438,2);
INSERT INTO stanza VALUES('T1233','2','O sa ekklesia, Diyos ay napahinga;<br/>Puso Niya''y laging natutuwa!<br/>Ang ating puso ay Kanyang tahanan,<br/>Itatanyag Niya nang lubusan.<br/>',NULL,43439,3);
INSERT INTO stanza VALUES('T1233','chorus','O sa ekklesia,<br/>Paghanap ng Diyos ay humangga;<br/>At sa tuwina<br/>Pupurihin ko Siya!<br/>"Aleluya — Kristo''t ekklesia!"<br/>',NULL,43440,4);
INSERT INTO stanza VALUES('T1234','1','Uhaw sa lupang tigang ng Babilonia,<br/>Wala akong masumpungang si-ya;<br/>Nguni''t nang napunta sa ekklesia lokal,<br/>Akin ding natagpuan ang bukal.<br/>',NULL,43441,1);
INSERT INTO stanza VALUES('T1234','chorus','Umiinom sa bukal ng buhay,<br/>Ako''y masaya, puso ko''y may si-ya;<br/>Umiinom sa bukal ng buhay,<br/>O panustos na kahanga-hanga!<br/>',NULL,43442,2);
INSERT INTO stanza VALUES('T1234','2','Kay tamis tubig mula sa burol ng Diyos,<br/>Sa kalooban ko umaagos;<br/>Bukal na nagpatid ng uhaw nakita,<br/>May sariwang buhay at sagana.<br/>',NULL,43443,3);
INSERT INTO stanza VALUES('T1234','3','Bakit di magpulong sa ekklesia lokal?<br/>Dito''y tuloy ang daloy ng bukal.<br/>Kayo''y dadalhin ng Pastol sa ekklesia,<br/>''Spiritu ninyo''y mabigyang si-ya.<br/>',NULL,43444,5);
INSERT INTO stanza VALUES('T1236','1','Awit ng buhay sa ekklesi-a''y napakinggan,<br/>Kristo ang ating galak, Siya''y may kahayagan;<br/>Babilonia''t sanlibutan tapos na sa atin,<br/>Tayo''y nasa magandang lupain.<br/>',NULL,43445,1);
INSERT INTO stanza VALUES('T1236','chorus','Nag-eekklesia tayo,<br/>Sa ating espiritu;<br/>Sa lupang-batayan nga,<br/>Buo ang pamilya.<br/>O, mga ekklesia''y kasama,<br/>Aawit buong lupa:<br/>Aleluya kay Kristong lupa!<br/>',NULL,43446,2);
INSERT INTO stanza VALUES('T1236','2','Lahat ng doktrina''t lumipas, lubos iniwan;<br/>Makamundong nasà at sala''y binitiwan.<br/>Dakilang pag-ibig ni Kristo sa ''kin umapaw;<br/>Kay Kristong lupa di na bibitaw.<br/>',NULL,43447,3);
INSERT INTO stanza VALUES('T1236','3','"Aking ekklesia itatayo Ko sa batong ''to";<br/>Nakita natin ang Kanyang layon at plano.<br/>Mga sangkap sa Katawan pinagkoordina,<br/>Nang maitayo kay Kristong lupa.<br/>',NULL,43448,5);
INSERT INTO stanza VALUES('T1236','4','Pagbabawi lumalaganap sa ''ting panahon;<br/>Lahat ng ekklesia''y inutusan ang Poon:<br/>"Punuan ang lupa ng dalangin at pagbasa<br/>At aleluya kay Kristong lupa!"<br/>',NULL,43449,7);
INSERT INTO stanza VALUES('T1240','1','Mas malalim, ako ay papunta;<br/>Sa krus ni Hesus;<br/>Kamatayan, buhay magkasama;<br/>Laliman''ng agos.<br/>O, aking dalangin,<br/>Nawa ay lumalim;<br/>Kumilos sa amin,<br/>Kabaguha''y tamuhin.<br/>',NULL,43450,1);
INSERT INTO stanza VALUES('T1240','2','Mas mataas, sa buhay ni Hesus;<br/>Kami''y mababa.<br/>Sa Iyong buhay ay mapapataas—<br/>Tumaas nawa.<br/>O, aming dalangin—<br/>Kami ay baguhin—<br/>Daloy payamanin<br/>Buhay Mo ay kilanlin.<br/>',NULL,43451,2);
INSERT INTO stanza VALUES('T1240','3','Lumalago, sa ''tin lumalago,<br/>Siya araw-araw.<br/>Paraan Niya sa ''ting pamumuhay—<br/>Ang umagos Siya.<br/>Aming panalangin,<br/>Paglago''y lubusin.<br/>Di sapat alamin;<br/>Iyong buhay palaguin.<br/>',NULL,43452,3);
INSERT INTO stanza VALUES('T1240','4','Namumuhay sa ''ting pamumuhay,<br/>Kristo''y praktikal:<br/>Munti, malaki, anumang bagay—<br/>Siya ay kasama.<br/>Sa bawa''t paraan,<br/>Kristo''y ipamuhay;<br/>Tawagin ang ngalan,<br/>Iyong lahat ay ibigay.<br/>',NULL,43453,4);
INSERT INTO stanza VALUES('T1240','5','Ang Persona, Hesus ''ting Persona,<br/>Buháy sa atin.<br/>Siya''y ating lasa, gawi at gawa;<br/>Anong l''walhati!<br/>O, aming Persona;<br/>Sa puso''y manahan.<br/>Bilang aming buhay<br/>Bawa''t araw at daan.<br/>',NULL,43454,5);
INSERT INTO stanza VALUES('T1240','6','Sa ekklesia, sa mga ekklesia<br/>Daloy nakita:<br/>Sa lahat pamumuhay si Kristo,<br/>Tayo''y lalago.<br/>Ang mga ekklesia<br/>Tanging si Kristo lang.<br/>Sarili''y bawasan,<br/>Lumago sa Katawan.<br/>',NULL,43455,6);
INSERT INTO stanza VALUES('T1240','7','Pagtatayo ating makikita<br/>Sa ekkle-si-a:<br/>Daranasin nga natin si Kristo—<br/>Tanging daa''y Siya.<br/>O, kami''y itayo,<br/>Sa buhay lumago.<br/>Gawin kaming tao<br/>Ng Herusalem Bago.<br/>',NULL,43456,7);
INSERT INTO stanza VALUES('T1240','8','Darating na, para sa Sinta Niya,<br/>Hesus darating;<br/>Sa mga ekklesia''y naghahanda<br/>Mapal''walhati!<br/>Panginoong Hesus,<br/>Bumalik Ka muli!<br/>Aming purihin Ka,<br/>Bumalik! Hesus! Amen!<br/>',NULL,43457,8);
INSERT INTO stanza VALUES('T1244','beginning-note','Awit 133<br/>',NULL,43458,1);
INSERT INTO stanza VALUES('T1244','1','Anong buting masdan,<br/>Payapang manahan;<br/>Hari''y nasisiyahan:<br/>Bunga ng kat''wiran.<br/>Nagkasundo kapatiran<br/>Alam galak ng kai-sahan!<br/>',NULL,43459,2);
INSERT INTO stanza VALUES('T1244','2','Matamis nai-ugpong<br/>(Alagad ni Kristo),<br/>Puso''t isip isa,<br/>Maging sa salita;<br/>Nang lahat nagmamahalan;<br/>Lubos ang kaginhawaan!<br/>',NULL,43460,3);
INSERT INTO stanza VALUES('T1244','3','Sa pagkakaisa<br/>Langit ay masaya;<br/>Ebanghelyo b''yaya<br/>Ang pagpapahid nga;<br/>Naibuhos ang ''Spiritu<br/>Mula sa Ulong si Kristo.<br/>',NULL,43461,4);
INSERT INTO stanza VALUES('T1244','4','Kung nagkakaisa,<br/>Matamis ang b''yaya,<br/>Tana''y napahiran<br/>Sa mukha ay masilayan;<br/>Dumating sa nagpupuri,<br/>Dibinong samyo''y palagi.<br/>',NULL,43462,5);
INSERT INTO stanza VALUES('T1244','5','Sa mga hirang Niya<br/>Langis ay bumaba;<br/>Pagpapahid agos,<br/>Di matapus-tapos.<br/>Hanggang sa Kanyang laylayan<br/>Ibig ko''y Korderong lubos.<br/>',NULL,43463,6);
INSERT INTO stanza VALUES('T1244','6','Sa balbas ni A''ron,<br/>(Malapit sa mukha),<br/>Takot na kalul''wa<br/>Biyaya''y kilala;<br/>Sa lahat libreng biyaya,<br/>Sa akin din umabot nga!<br/>',NULL,43464,7);
INSERT INTO stanza VALUES('T1247','1','Kung nais matatag puso;<br/>At maging sa ''spiritu;<br/>Kung maging mandaraig man;<br/>Si Hesus laging sundan.<br/>',NULL,43465,1);
INSERT INTO stanza VALUES('T1247','chorus','Sundan Hesus sa ''spiritu,<br/>Mandaraig totoo;<br/>Bawa''t oras, Hesus sundan,<br/>Hesus, kami''y tulungan.<br/>',NULL,43466,2);
INSERT INTO stanza VALUES('T1247','2','Kung nais na maitayo,<br/>Nang magkasama tayo;<br/>Sama-samang mailakip;<br/>Sundan lagi kapatid.<br/>',NULL,43467,3);
INSERT INTO stanza VALUES('T1247','chorus','Kapatiran sundan natin<br/>Para sa pagtatayo;<br/>Di mag-isa; sila''y sundin,<br/>Pagkilos nasa tono.<br/>',NULL,43468,4);
INSERT INTO stanza VALUES('T1247','3','Para sa pagbabawi Niya;<br/>Lupa''y mapasa Kanya;<br/>Naipasok kaharian;<br/>Mga ekklesia''y sundan.<br/>',NULL,43469,5);
INSERT INTO stanza VALUES('T1247','chorus','Kaharian makikita;<br/>Sundan mga ekklesia.<br/>Sundan daloy ng ekklesia<br/>Para sa pagbawi Niya.<br/>',NULL,43470,6);
INSERT INTO stanza VALUES('T1247','4','Pagsunod ay pagbutihin,<br/>Salita ay tanggapin;<br/>Nakasusunod tayo sa<br/>Panginoon, ekklesia.<br/>',NULL,43471,7);
INSERT INTO stanza VALUES('T1247','chorus','Hesus sundan; banal sundan;<br/>Ekklesia agos sundan;<br/>Sa Salita ng Diyos Amen,<br/>Layon natin tamuhin.<br/>',NULL,43472,8);
INSERT INTO stanza VALUES('T1248','1','Ating gunitain,<br/>Ang pangako ni David;<br/>"Di ako papanhik<br/>Sa bahay ko o silid;<br/>Di ipipikit mata ko,<br/>Hanggang masumpungan<br/>Ang dakong tahanan ng Diyos,<br/>Kanyang pahingahan."<br/>',NULL,43473,1);
INSERT INTO stanza VALUES('T1248','2','Tayo''y naging bulag,<br/>Sa mahabang panahon;<br/>Kalagan Pangino''n,<br/>Puso sa Iyo''y ituon.<br/>Aakyat sa kabundukan,<br/>Materyal kukunin;<br/>Itatayo bahay ng Diyos,<br/>Huwag nang antalahin!<br/>',NULL,43474,2);
INSERT INTO stanza VALUES('T1248','3','Sa Iyong pagtatayo<br/>Kami ay Iyong pukawin,<br/>Tulad ni David no''n,—<br/>Handang-handang labí rin.<br/>Tahanan Mo''y itayo,<br/>Atas pinagpala!<br/>Aming asam ay nasà Mo—<br/>Kami''y magtatayo.<br/>',NULL,43475,3);
INSERT INTO stanza VALUES('T1248','4','Mga tinawag Mo<br/>Ay hindi mapahinga<br/>Lahat ay isuko—<br/>Iyong tahanan itayo.<br/><i>Daig ang pinto ng Hades,</i><br/>Ekklesiang natayo!<br/>Oras, tao, kaunti na—<br/>Kami''y itayo Mo!<br/>',NULL,43476,4);
INSERT INTO stanza VALUES('T1248','chorus','[Daig ang pinto ng Hades,<br/>Ekklesiang natayo!<br/>Oras, tao, kaunti na—<br/>Kami''y itayo Mo!]<br/><!--(Ulitin ang huling apat na linya)--><br/>',NULL,43477,5);
INSERT INTO stanza VALUES('T1251','beginning-note','Ezra 1-3<br/>',NULL,43478,1);
INSERT INTO stanza VALUES('T1251','1','Nasa Herusalem na,<br/>Babilonia tapos na,<br/>Tayo''y nagkakaisa,<br/>O sa Diyos ang gloria!<br/>Pagtuturo''y wala na,<br/>Opinyon iniwan na,<br/>Kaluluwa''t ''spiritu,<br/>Hiwalay na nang husto.<br/>',NULL,43479,2);
INSERT INTO stanza VALUES('T1251','chorus','Aleluya! Aleluya!<br/>Kami''y nagkakaisa<br/>Para sa ekklesia.<br/>Aleluya! Aleluya!<br/>Sa ekklesia lokal namumuhay na!<br/>',NULL,43480,3);
INSERT INTO stanza VALUES('T1251','2','Saserdoteng tunay nga<br/>Ka-i-langang mabawi—<br/>Kay Kristo manatili,<br/>Sa Diyos ang l''walhati!<br/>Mapuspusan ni Kristo,<br/>Kristo rin maging premyo.<br/>Pagtatayo''y magawa<br/>Sa lokal na ekklesia.<br/>',NULL,43481,4);
INSERT INTO stanza VALUES('T1251','3','Pagkahari makita,<br/>Awtoridad kasama—<br/>Sa dibinong paghari,<br/>Sa Diyos ang l''walhati!<br/>Pasakop sa ''Spiritu,<br/>Tunay na benepisyo—<br/>Ka-i-langa''y ito nga<br/>Sa lokal na ekklesia.<br/>',NULL,43482,6);
INSERT INTO stanza VALUES('T1251','4','Dambana''y kamtin natin,<br/>Handog doon ihain.<br/>Haing sinunog kitlin,<br/>Diyos luwalhatiin!<br/>Kailangan di magtalo,<br/>Ekklesia''y ganap tayo,<br/>Ang di-ganap bunutin<br/>Sa ekklesia ngayon din.<br/>',NULL,43483,8);
INSERT INTO stanza VALUES('T1251','5','Ang pundasyon nalatag—<br/>Ang l''walhati''y natanyag!<br/>Tayo''y puspos ng saya<br/>O sa Diyos ang gloria!<br/>Pagsigaw ay lakasan<br/>Mapakinggan ng tanan—<br/>Ang kaaway talo na,<br/>Sa ekklesia lokal nga!<br/>',NULL,43484,10);
INSERT INTO stanza VALUES('T1255','1','Tayo ay sa pagbabawi<br/>Ng Panginoon,<br/>Ng Kanyang ekklesia lokal<br/>Sa mga lunsod.<br/>Nakatayo sa batayan<br/>Ng kaisahan,<br/>Itinatayo ang templo<br/>Ng Panginoon.<br/>',NULL,43485,1);
INSERT INTO stanza VALUES('T1255','chorus','Tayo ay para sa Panginoon,<br/>Para sa Kanyang pagbabawi!<br/>Tayo ay para sa Panginoon,<br/>Sa Kanyang pagbawi!<br/>',NULL,43486,2);
INSERT INTO stanza VALUES('T1255','2','Tayo ay sa pagbabawi<br/>Ng Panginoon;<br/>Sanayin ang espiritu,<br/>Upang makita.<br/>Nabagsak ang Babilonia,<br/>Diyablo ay talo,<br/>Ekklesiang lokal tinayo<br/>Sa lupang lokal.<br/>',NULL,43487,3);
INSERT INTO stanza VALUES('T1257','1','Sa bawa''t lunsod, iyong masdan,<br/>Patungan-ng-ilawan;<br/>Mga banal nagtitipon,<br/>Diyos may pahinga roon.<br/>',NULL,43488,1);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43489,2);
INSERT INTO stanza VALUES('T1257','2','Masdan mo ang pagpupulong,<br/>Tinig ay umuugong!<br/>Lahat nagsasalamuha,<br/>Kristo''y dinadakila!<br/>',NULL,43490,3);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43491,4);
INSERT INTO stanza VALUES('T1257','3','Dinggin ang basa-dalangin,<br/>Salita ay pagkain;<br/>Ka''nin, inumin, purihin,<br/>Si Kristo''y tamasahin.<br/>',NULL,43492,5);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43493,6);
INSERT INTO stanza VALUES('T1257','4','Ngalang "Panginoong Hesus,"<br/>Mahal nila nang lubos!<br/>Habang ngala''y tinatawag,<br/>Higit pang nagagalak.<br/>',NULL,43494,7);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43495,8);
INSERT INTO stanza VALUES('T1257','5','Dinggin mo ang "Aleluya!"<br/>Lakas ng kulog nila!<br/>Aleluya! Aleluya!<br/>Kaaway napatumba!<br/>',NULL,43496,9);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43497,10);
INSERT INTO stanza VALUES('T1257','6','Masdan, sila''y dumadayo,<br/>Ekklesia''y tinatayo;<br/>Bayan, lunsod, may ekklesia,<br/>Si Kristo''y sasapit na!<br/>',NULL,43498,11);
INSERT INTO stanza VALUES('T1257','chorus','Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>Hinirang ng Diyos — lokal na ekklesia,<br/>Mga banal nagkaisa!<br/>',NULL,43499,12);
INSERT INTO stanza VALUES('T1257','7','Masdan sa mga ekklesia,<br/>Si Kristo''y naghahanda<br/>Ng mahal Niyang Kasintahan<br/>Na Kanyang babalikan.<br/>',NULL,43500,13);
INSERT INTO stanza VALUES('T1257','chorus','Walang dungis, kulubot, kapintasan<br/>Ekklesiang mal''walhati!<br/>Walang dungis, kulubot, kapintasan,<br/>Puspos ng luwalhati!<br/>',NULL,43501,14);
INSERT INTO stanza VALUES('T1259','1','Lokal na ekklesia<br/>Patotoo Niya,<br/>Sa gabing madilim,<br/>Tangan: ilaw Siya.<br/>Hinubog ni Kristo<br/>Sa Espiritu;<br/>Kalikasa''y iisa,<br/>Purong ginto nga.<br/>',NULL,43502,1);
INSERT INTO stanza VALUES('T1259','chorus','Sa gabing madilim<br/>Masdan ekklesia;<br/>Pagningas ''Spiritu<br/>Silay si Kristo.<br/>',NULL,43503,2);
INSERT INTO stanza VALUES('T1259','2','Diyos nagsakatawan,<br/>Ngayon ''Spiritu,<br/>Bilang kandelero,<br/>Realidad ko.<br/>''Spiritu''y patungan<br/>Niya ng ilawan.<br/>Lokal na ekklesia<br/>Naparami na.<br/>',NULL,43504,3);
INSERT INTO stanza VALUES('T1259','chorus','Sa gabing madilim<br/>Masdan ekklesia;<br/>Pagningas ''Spiritu<br/>Silay si Kristo.<br/>',NULL,43505,4);
INSERT INTO stanza VALUES('T1259','3','Ang Anak ng Tao<br/>Buháy kailanman;<br/>Inaalagaan,<br/>Mga ekklesia.<br/>Anuman pagsubok,<br/>Hindi matakot;<br/>May ningas mata Niya<br/>Maningning mukha.<br/>',NULL,43506,5);
INSERT INTO stanza VALUES('T1259','chorus','Sa gabing madilim<br/>Masdan ekklesia;<br/>Pagningas ''Spiritu<br/>Silay si Kristo.<br/>',NULL,43507,6);
INSERT INTO stanza VALUES('T1259','4','Anong makapugnaw?<br/>Makalaban daw?<br/>Sa mga ekklesia<br/>Puno ng buhay.<br/>Higit ang tuligsa—<br/>Mas darami Siya!<br/>Mas madilim paligid<br/>Sikat hihigit.<br/>',NULL,43508,7);
INSERT INTO stanza VALUES('T1259','chorus','Sa gabing madilim<br/>Masdan ekklesia;<br/>Pagningas ''Spiritu<br/>Silay si Kristo.<br/>',NULL,43509,8);
INSERT INTO stanza VALUES('T1259','5','Lokal na ekklesia,<br/>Magiging Nobya,<br/>Bagong Herusalem<br/>Ang lunsod, Amen!<br/>Maraming patungan<br/>Magiging isa;<br/>Hayag Diyos Tres-uno<br/>Sa sansinukob.<br/>',NULL,43510,9);
INSERT INTO stanza VALUES('T1259','chorus','Pagbaba''y mamasdan<br/>Sa kalangitan,<br/>Ganap kahayagan,<br/>Diyos walang hanggan.<br/>',NULL,43511,10);
INSERT INTO stanza VALUES('T1260','1','Sa ekklesia lokal,<br/>Pili ng Diyos;<br/>Kristo''y buhay,<br/>Masaganang pagpapala.<br/>Sa espiritu, sa lupang lokal;<br/>Makibaka sa kaaway<br/>At makamtan ang tagumpay.<br/>',NULL,43512,1);
INSERT INTO stanza VALUES('T1266','1','Nagniningas, nagniningas<br/>Baling lagi espiritu,<br/>Para sa Iyong layunin nagkakaisa;<br/>Sa batayang lokalidad,<br/>Inihayag kaisahan—<br/>Kristo''y Ulo, tayo''y sangkap,<br/>''Sang Katawan.<br/>',NULL,43513,1);
INSERT INTO stanza VALUES('T1266','chorus','Kristo''t ekklesia,<br/>Bawa''t lokalidad,<br/>Ang ating buhay at ang realidad.<br/>Aleluya! Aleluya!<br/>Buhay namin inialay,<br/>Itayo ang Iyong Katawan,<br/>Na may pagmamahalan.<br/>',NULL,43514,2);
INSERT INTO stanza VALUES('T1266','2','Hinihinga, hinihinga,<br/>Bagong buhay tinatanggap,<br/>Sa kabaguhan ako''y tinatransporma;<br/>Ilabas ang lumang buhay,<br/>Hingahin ang bagong buhay,<br/>Paghinga natin kay Hesus,<br/>Hinihinga ay buhay.<br/>',NULL,43515,3);
INSERT INTO stanza VALUES('T1273','1','Kristo''y minsang tumawag,<br/>At tumatawag muli.<br/>Amen sa Kanyang tawag!<br/>Manaig!<br/>Ang ekklesia''y nabigo,<br/>Sa dunong nagpalalo,<br/>Sa buhay di lumago;<br/>Manaig!<br/>',NULL,43516,1);
INSERT INTO stanza VALUES('T1273','chorus','Manaig! Manaig!<br/>Manaig sa Kristiyanismong nasawi!<br/>Ang gawa mo''y itabi,<br/>At turong naghahati;<br/>Kanin si Hesus lagi—<br/>Manaig!<br/>',NULL,43517,2);
INSERT INTO stanza VALUES('T1273','2','Ang kumain ay wasto,<br/>Diyos ang nagbawi nito;<br/>Kaaway matatalo—<br/>Manaig!<br/>Iwan ang pagtuturo,<br/>Tamasahin ang puno<br/>Ng buhay na si Kristo—<br/>Manaig!<br/>',NULL,43518,3);
INSERT INTO stanza VALUES('T1273','3','Di mabago ng turo<br/>Ang kalul''wa ng tao,<br/>Kanin lamang si Kristo—<br/>Manaig!<br/>Manaig at kumain,<br/>Mag-isa''t sa pulong din,<br/>Kanin Siya bilang piging—<br/>Manaig!<br/>',NULL,43519,5);
INSERT INTO stanza VALUES('T1273','4','Sa pagkain sisilang,<br/>Ang lalakeng-anak nga;<br/>Panginoon babalik—<br/>Manaig!<br/>Kung lalakeng-anak ka,<br/>Hinog na ang ekklesia,<br/>Handang kasintahan Niya—<br/>Manaig!<br/>',NULL,43520,7);
INSERT INTO stanza VALUES('T1275','1','Mal''walhating sinalaysay,<br/>Ikaw ekklesiang mahal,<br/>Ekklesia sa Filadelfia,<br/>Kristo ay nagsalita.<br/>Susi ni David taglay Niya,<br/>Pinasok kaharian;<br/>"Buksan ko, di masasara"—<br/>Natupad, binigkas Niya.<br/>',NULL,43521,1);
INSERT INTO stanza VALUES('T1275','2','Aleluya, Filadelfia,<br/>Gawa mo nalugod Siya.<br/>Maliit man ang iyong lakas,<br/>Salita Niya iyong tinupad.<br/>Ngalan Niya di mo tinanggi,<br/>Sa lupa hinayag pa.<br/>Pinto sa iyo nakaabang,<br/>Papasok ikaw lamang.<br/>',NULL,43522,2);
INSERT INTO stanza VALUES('T1275','3','Sinisintang Filadelfia,<br/>Tinupad Salita Niya.<br/>Sa panahon ng pagsubok,<br/>Liligtas ka Niyang lubos.<br/>Batid din ng manggugulo,<br/>Mahal ka Niyang totoo.<br/>"Panghawakan, ''Ko''y darating,<br/>Putong di sa iyo kunin."<br/>',NULL,43523,3);
INSERT INTO stanza VALUES('T1275','4','Aleluya, mandaraig,<br/>"Sa templo ng Aking Diyos,<br/>Itatayo na haligi,<br/>Lalabas, hinding-hindi."<br/>Sa kanila''y ngalan ng Diyos<br/>Bagong ngalan ng Poon.<br/>Sa tres-unong Diyos hahalo;<br/>Sila''y lunsod nga ng Diyos.<br/>',NULL,43524,4);
INSERT INTO stanza VALUES('T1275','5','Bagong Herusalem bababa,<br/>Sa langit magmumula:<br/>Jaspeng pader, pintong perlas,<br/>Nai-halong mga hiyas.<br/>Filadelfia, Filadelfia,<br/>Naging Nobyang sinta Niya.<br/>Espiritu sa ekklesia,<br/>Dinggin pagsasalita.<br/>',NULL,43525,5);
INSERT INTO stanza VALUES('T1278','1','Sa i-yo''y may pag-ibig sa ekklesia,<br/>Malalim at tunay purong pagsinta;<br/>Bakit malumbay at maghimutok ka,<br/>Meron namang panustos sa ekklesia?<br/>',NULL,43526,1);
INSERT INTO stanza VALUES('T1278','2','Sa i-yo''y may buhay sa ekklesia,<br/>Kasing tamis ng hamog sa umaga;<br/>Bakit ka mangamba at mag-alala,<br/>Hesus may malasakit sa ekklesia?<br/>',NULL,43527,2);
INSERT INTO stanza VALUES('T1278','3','Sa i-yo''y may gawa sa ekklesia;<br/>Maging anghel gagawa nang masaya;<br/>Bakit hahanap ng gawang dakila,<br/>Kamay mo''y kailangan na sa ekklesia?<br/>',NULL,43528,3);
INSERT INTO stanza VALUES('T1278','4','Sa i-yo''y may puwang sa ekklesia;<br/>Kay l''walhati''t liwanag, mapayapa;<br/>Kay galak, mat''wid, bakit gagala pa?<br/>Sa ekklesia ni Hesus may lugar ka.<br/>',NULL,43529,4);
INSERT INTO stanza VALUES('T1285','1','Ang pananalig binigay,<br/>Sa banal nang una,<br/>At ipinagkatiwala,<br/>Nang maidepensa.<br/>',NULL,43530,1);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43531,2);
INSERT INTO stanza VALUES('T1285','2','Ekonomiya ng Diyos, tanda<br/>Tunay deposito,<br/>Pagbabawi ay sasala<br/>Kung ito''y mawala.<br/>',NULL,43532,3);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43533,4);
INSERT INTO stanza VALUES('T1285','3','Mahiwagang pananalig,<br/>Budhing puro hiling;<br/>Diyos nais para sa atin<br/>Buhay pabanalin.<br/>',NULL,43534,5);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43535,6);
INSERT INTO stanza VALUES('T1285','4','Sa pananalig, pag-ibig,<br/>Salita''y hawakan;<br/>Tanggihang may katapangan<br/>Ang kataliwasan.<br/>',NULL,43536,7);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43537,8);
INSERT INTO stanza VALUES('T1285','5','Malusog na pagtuturo,<br/>Tiwalang totoo!<br/>At buhay ng kabanalan,<br/>Tunay maimbakan.<br/>',NULL,43538,9);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43539,10);
INSERT INTO stanza VALUES('T1285','6','Gawin Mo kaming matapat<br/>Ipasa nalaman;<br/>''Spiritu, verbo, tiwala,<br/>Mga banal tularan.<br/>',NULL,43540,11);
INSERT INTO stanza VALUES('T1285','chorus','Talos kong makakaya Niya<br/>Na aking pinaniniwalaan<br/>Magbantay ''Spiritu Santo<br/>Sa ating deposito.<br/>',NULL,43541,12);
INSERT INTO stanza VALUES('T1287','1','Kunin lupa! Binigay ng Diyos sa atin;<br/>Sa pamumuhay Kristo ay kamtin:<br/>Dugo, Salita, Espiritu''t ekklesia—<br/>Hinanda sa pagkuha ng lupa.<br/>',NULL,43542,1);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na babae) Lupa''y kunin! Mga kapatid,<br/>Ang lupang binigay ng Diyos.<br/>Magpakalakas, tayo''y magwagi,<br/>Lupa''y kunin, kay l''walhati!<br/>',NULL,43543,2);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na lalake) Lupa''y kunin! Mga kapatid<br/>Sa pagkuha''y magsigasig.<br/>Tumatawag Siya, nanguna na nga,<br/>Tanang kailangan handa na!<br/>',NULL,43544,3);
INSERT INTO stanza VALUES('T1287','2','Taglay dugo! Si Kristo ang ating hain,<br/>Sarili Niya''y sa Diyos inihain;<br/>Sa trono ng biyaya dudulog tayo,<br/>Ating gamitin mahal Niyang dugo.<br/>',NULL,43545,4);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na babae)<br/>Lupa''y kunin! Mga kapatid,<br/>Ang lupang binigay ng Diyos.<br/>Magpakalakas, tayo''y magwagi,<br/>Lupa''y kunin, kay l''walhati!<br/>',NULL,43546,5);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na lalake)<br/>Lupa''y kunin! Mga kapatid<br/>Sa pagkuha''y magsigasig.<br/>Tumatawag Siya, nanguna na nga,<br/>Tanang kailangan handa na!<br/>',NULL,43547,6);
INSERT INTO stanza VALUES('T1287','3','May salita! Pagkain sa araw-araw;<br/>Nagtutustos sa ''tin, tumatanglaw;<br/>Ihalo ang Salita sa pananalig,<br/>Amen! Pamumuhay maging tuwid.<br/>',NULL,43548,7);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na babae)<br/>Lupa''y kunin! Mga kapatid,<br/>Ang lupang binigay ng Diyos.<br/>Magpakalakas, tayo''y magwagi,<br/>Lupa''y kunin, kay l''walhati!<br/>',NULL,43549,8);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na lalake)<br/>Lupa''y kunin! Mga kapatid<br/>Sa pagkuha''y magsigasig.<br/>Tumatawag Siya, nanguna na nga,<br/>Tanang kailangan handa na!<br/>',NULL,43550,9);
INSERT INTO stanza VALUES('T1287','4','May ''Spiritu! ''Spiritu ng realidad,<br/>Di-damdamin ang may awtoridad;<br/>Tinuruan tayo sa Kanya''y mamuhay,<br/>Ginabayan sa lahat na tunay.<br/>',NULL,43551,10);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na babae)<br/>Lupa''y kunin! Mga kapatid,<br/>Ang lupang binigay ng Diyos.<br/>Magpakalakas, tayo''y magwagi,<br/>Lupa''y kunin, kay l''walhati!<br/>',NULL,43552,11);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na lalake)<br/>Lupa''y kunin! Mga kapatid<br/>Sa pagkuha''y magsigasig.<br/>Tumatawag Siya, nanguna na nga,<br/>Tanang kailangan handa na!<br/>',NULL,43553,12);
INSERT INTO stanza VALUES('T1287','5','May ekklesia! Tanang banal ay kailangan,<br/>Nang matamo Kanyang kapuspusan;<br/>Kristong nagpapaloob-ng-lahat kamtin,<br/>Siya''y lahat-lahat para sa atin.<br/>',NULL,43554,13);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na babae)<br/>Lupa''y kunin! Mga kapatid,<br/>Ang lupang binigay ng Diyos.<br/>Magpakalakas, tayo''y magwagi,<br/>Lupa''y kunin, kay l''walhati!<br/>',NULL,43555,14);
INSERT INTO stanza VALUES('T1287','chorus','(Mga kapatid na lalake)<br/>Lupa''y kunin! Mga kapatid<br/>Sa pagkuha''y magsigasig.<br/>Tumatawag Siya, nanguna na nga,<br/>Tanang kailangan handa na!<br/>',NULL,43556,15);
INSERT INTO stanza VALUES('T1289','1','Tagumpay na, si Kristo ay nanalo na<br/>Sa kaaway! Ipagbunyi Si-ya.<br/>Dugong mahal ang nagbigay ng tagumpay,<br/>Di lalaon Poo''y pakikita.<br/>',NULL,43557,1);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na babae) Tagumpay na, mga kapatid,<br/>Ipagbunyi ang pagwagi!<br/>Ipamalita sa lunsod Sion,<br/>At lupa''y puspos ng puri.<br/>',NULL,43558,2);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na lalake) Tagumpay na, mga kapatid,<br/>Gawa ni Kristo''y ganap na!<br/>Hari''ng tagumpay, kaaway daig,<br/>Simulan ngayon ligaya.<br/>',NULL,43559,3);
INSERT INTO stanza VALUES('T1289','2','Tagumpay na, daig natin ang kaaway,<br/>Salita ng Diyos ang patotoo,<br/>Salitang buhay, nagbibigay ng lakas<br/>Tiyak na si Satanas ay talo.<br/>',NULL,43560,4);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na babae)<br/>Tagumpay na, mga kapatid,<br/>Ipagbunyi ang pagwagi!<br/>Ipamalita sa lunsod Sion,<br/>At lupa''y puspos ng puri.<br/>',NULL,43561,5);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na lalake)<br/>Tagumpay na, mga kapatid,<br/>Gawa ni Kristo''y ganap na!<br/>Hari''ng tagumpay, kaaway daig,<br/>Simulan ngayon ligaya.<br/>',NULL,43562,6);
INSERT INTO stanza VALUES('T1289','3','Tagumpay na! Kaaway yurakan natin,<br/>Pangkalul''wang buhay huwag ibigin<br/>Hanggang kamatayan; ay isigaw natin—<br/>"Panginoon, tagumpay Ka namin!"<br/>',NULL,43563,7);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na babae)<br/>Tagumpay na, mga kapatid,<br/>Ipagbunyi ang pagwagi!<br/>Ipamalita sa lunsod Sion,<br/>At lupa''y puspos ng puri.<br/>',NULL,43564,8);
INSERT INTO stanza VALUES('T1289','chorus','(Mga kapatid na lalake)<br/>Tagumpay na, mga kapatid,<br/>Gawa ni Kristo''y ganap na!<br/>Hari''ng tagumpay, kaaway daig,<br/>Simulan ngayon ligaya.<br/>',NULL,43565,9);
INSERT INTO stanza VALUES('T1293','1','Ako''y tao—<br/>Kahulugan ng sansinukob;<br/>Ako''y tao—<br/>Kahulugan ng sansinukob.<br/>Diyos may gawa,<br/>Kay dakila;<br/>Ako''y sentro''t kahulugan ng sansinukob.<br/>',NULL,43566,1);
INSERT INTO stanza VALUES('T1293','2','Kristo''y sa ''kin—<br/>Kahulugan ng aking buhay;<br/>Kristo''y sa ''kin—<br/>Kahulugan ng aking buhay.<br/>Nasa akin,<br/>Aking lahat;<br/>Kristo ang kahulugan ng pantaong buhay.<br/>',NULL,43567,2);
INSERT INTO stanza VALUES('T1293','3','Ang ekklesia—<br/>Kahayagan ngayon ni Kristo;<br/>Ang ekklesia—<br/>Sa mundo''y sama-samang tao.<br/>Plano ng Diyos,<br/>Tupad nito,<br/>Nang mapamahalaan niya ang buong mundo.<br/>',NULL,43568,3);
INSERT INTO stanza VALUES('T1293','4','Lokal ekklesia—<br/>Ang bagong buhay-pamilya;<br/>Lokal ekklesia—<br/>Tunay na buhay-pamilya.<br/>Daan ngayo''y<br/>Taglay natin—<br/>Natayo sa pagkain, pag-inom kay Kristo.<br/>',NULL,43569,4);
INSERT INTO stanza VALUES('T1293','5','Ano''ng gawin?<br/>Humayo''t ating salitain.<br/>Ano''ng gawin?<br/>Sanlibuta''y sabihan natin.<br/>Disip''luhin—<br/>Tawag natin.<br/>Ang balita''y ikalat sa bawa''t lupain.<br/>',NULL,43570,5);
INSERT INTO stanza VALUES('T1294','1','Magsalita nang bumaba ang kaharian.<br/>Oo, magsalita hanggang bumaba na nga.<br/>Magpalaya<br/>Ng Salita.<br/>Magsalita hanggang kaharia''y bumaba.<br/>',NULL,43571,1);
INSERT INTO stanza VALUES('T1294','2','Salita''y kalagan, di babalik nang hungkag.<br/>Salita''y kalagan, di babalik nang hungkag.<br/>Binhi''y ''tanim,<br/>Kailangan din;<br/>Kalagan salita, di babalik nang hungkag.<br/>',NULL,43572,2);
INSERT INTO stanza VALUES('T1294','3','Mag-ebanghelyo, ipahayag ebanghelyo.<br/>Mag-ebanghelyo, hu-wag matakot sa tao.<br/>Diyos gumawa;<br/>Huwag mangamba,<br/>Ingos ng tao di natin katatakutan.<br/>',NULL,43573,3);
INSERT INTO stanza VALUES('T1294','4','Magsalita, si Kristo''y sasaksi sa puso<br/>Magsalita, si Kristo''y sasaksi sa puso<br/>Pag nagsabi,<br/>Magwawagi.<br/>Kristo''y patotohanan sa puso ng tao.<br/>',NULL,43574,4);
INSERT INTO stanza VALUES('T1294','5','Ani''y hinog na! Ipahayag ebanghelyo<br/>Parang puti na! Ipahayag ebanghelyo.<br/>Gusto''y — Kristo''t<br/>Ekklesia!<br/>Gapasin ang ani, mag-ebanghelyo na nga!<br/>',NULL,43575,5);
INSERT INTO stanza VALUES('T1299','1','May layon ang Manlilikha,<br/>Sa ating nasa lupa;<br/>Sa larawan Niya''y nilikha,<br/>Ihayag paghari Niya.<br/>Sa pagkatisod ng tao,<br/>Layon ng Diyos natago;<br/>Nguni''t kaharian ng Diyos,<br/>Anak magpapalubos.<br/>',NULL,43576,1);
INSERT INTO stanza VALUES('T1299','2','Kaharian ay kay Kristo,<br/>Satanas man humadlang;<br/>Bagay na tunay matamo,<br/>Paglago Niya sa puso.<br/>Relihiyon nagtuturo:<br/>"Hintayin kamatayan"—<br/>Si Kristo ay nagtatayo,<br/>Para sa kaharian.<br/>',NULL,43577,2);
INSERT INTO stanza VALUES('T1299','3','Tagapagligtas na Anak,<br/>Bilang tao''y nahayag,<br/>Ngayon Espiritu na Siya,<br/>Sa atin Siya''y hininga.<br/>Binhi rin sa espiritu,<br/>Siya''y uugat, lalago<br/>Buong katauhan natin,<br/>Buhay Niya''y malalaman.<br/>',NULL,43578,3);
INSERT INTO stanza VALUES('T1299','4','Panahon ay maikli na,<br/>Asam ni Kristo''y nobya;<br/>Mapabilis Kanyang dating,<br/>Buhay ay palaguin.<br/>Tayo''y bumaling kay Kristo,<br/>Huwag magsumikap tayo,<br/>Masdan binhi ay sisibol,<br/>Sa Kanya ay lalago.<br/>',NULL,43579,4);
INSERT INTO stanza VALUES('T1299','5','Hesu-Kristo makukuha<br/>Nang normal kaharian.<br/>Di sa transpormasyong bigla,<br/>Paglago maranasan.<br/>Nagpapaloob-ng-lahat,<br/>Itong binhi ng buhay;<br/>Tanang kakailanganin,<br/>Nang layon ng Diyos kamtin.<br/>',NULL,43580,5);
INSERT INTO stanza VALUES('T1304','beginning-note','Mateo 25; Apocalipsis 14<br/>',NULL,43581,1);
INSERT INTO stanza VALUES('T1304','1','Darating para Nobya,<br/>Piging kasalan handa,<br/>Itustos ang damit pa—<br/>Sa oras!<br/>Kristo kunin na buhay,<br/>Itahing nagdurusa<br/>Nang kat''wiran mataglay—<br/>Sa oras!<br/>',NULL,43582,2);
INSERT INTO stanza VALUES('T1304','chorus','Agapan! Agapan!<br/>Para sa piging kasalan,<br/>Agapan!<br/>Kaluluwa''y tuusin,<br/>Espiritu''y gamitin,<br/>Ika''y mamarapatin<br/>Sa oras!<br/>',NULL,43583,3);
INSERT INTO stanza VALUES('T1304','2','Kristo ay dumarating<br/>Para sa mga birhen<br/>Ekstrang langis imbakin—<br/>Bibilhin!<br/>Sarili ay tuusin,<br/>Binayaran na langis,<br/>Sisidlan mo''y punuin—<br/>Bibilhin!<br/>',NULL,43584,4);
INSERT INTO stanza VALUES('T1304','3','Kristo paparito na<br/>Para sa alipin Niya,<br/>Tapat may gantimpala—<br/>Maglingkod!<br/>Gamitin iyong talento,<br/>Daigin sarili mo,<br/>Paglingkuran si Kristo<br/>Sa oras!<br/>',NULL,43585,6);
INSERT INTO stanza VALUES('T1304','4','Parating na si Kristo,<br/>Anihin Kanyang trigo,<br/>Unang-bunga matamo—<br/>Mahinog!<br/>Dapat butil matuyo,<br/>Tanggihan mo ang mundo,<br/>Mamatay sarili mo—<br/>Mahinog!<br/>',NULL,43586,8);
INSERT INTO stanza VALUES('T1304','5','Mandaraig kukunin,<br/>Anuman hahamakin,<br/>Kristo lang iibigin—<br/>Dumaig!<br/>Kamataya''y daigin,<br/>Kristo ang buhay natin,<br/>Sa layon magtumulin—<br/>Dumaig!<br/>',NULL,43587,10);
INSERT INTO stanza VALUES('T1304','6','Para sa kaharian<br/>Kristo''y parating naman,<br/>Tayo ay pamunuan—<br/>Pasakop!<br/>Ang rebeldeng sarili<br/>Tanggal sa pagkahari,<br/>Kristo ang manatili—<br/>Pasakop!<br/>',NULL,43588,12);
INSERT INTO stanza VALUES('T1305','1','Itanyag pananampalataya sa Diyos,<br/>Mula sa diyus-diyosan nabaling na sa Diyos;<br/>Hinalong Salita''t pananalig, Amen.<br/>Kay Kristo sa Salita babaling pa rin.<br/>',NULL,43589,1);
INSERT INTO stanza VALUES('T1305','chorus','Lumago gawa ng pananalig,<br/>Paramihin pagpapagal ng pag-ibig,<br/>Magpapatuloy ang pagpapabanal Niya;<br/>Sa pagt''yaga sa pag-asa, hintayin Siya.<br/>',NULL,43590,2);
INSERT INTO stanza VALUES('T1305','2','Pag-ibig sa kapatiran matagpuan,<br/>Sa gitna natin pag-ibig madagdagan;<br/>Pag-ibig sa Diyos, tungo ang ating puso,<br/>Nang sa araw ng Poon mahanda tayo.<br/>',NULL,43591,3);
INSERT INTO stanza VALUES('T1305','chorus','Lumago gawa ng pananalig,<br/>Paramihin pagpapagal ng pag-ibig,<br/>Magpapatuloy ang pagpapabanal Niya;<br/>Sa pagt''yaga sa pag-asa, hintayin Siya.<br/>',NULL,43592,4);
INSERT INTO stanza VALUES('T1305','3','Poong matapat ihahanda ang Nobya,<br/>Espiritu, kaluluwa, katawan niya;<br/>Babanaling buo pagsunod sa Kanya,<br/>Nang sa pagtawag Niya tayo''y laging handa.<br/>',NULL,43593,5);
INSERT INTO stanza VALUES('T1305','chorus','Lumago gawa ng pananalig,<br/>Paramihin pagpapagal ng pag-ibig,<br/>Magpapatuloy ang pagpapabanal Niya;<br/>Sa pagt''yaga sa pag-asa, hintayin Siya.<br/>',NULL,43594,6);
INSERT INTO stanza VALUES('T1305','4','Babalik si Kristo tayo''y kasama Niya!<br/>Balik na Poon: Maluwalhating pag-asa!<br/>Maging mapagbantay kami para sa Iyo,<br/>Handa bilang anak para sa pagtagpo.<br/>',NULL,43595,7);
INSERT INTO stanza VALUES('T1305','chorus','Lumago gawa ng pananalig,<br/>Paramihin pagpapagal ng pag-ibig,<br/>Magpapatuloy ang pagpapabanal Niya;<br/>Sa pagt''yaga sa pag-asa, hintayin Siya.<br/>',NULL,43596,8);
INSERT INTO stanza VALUES('T1307','1','Pagdating ni Hesus ay malapit na,<br/>Panaho''y tubusin, sunggaban pa;<br/>Ihanda kami sa sigaw: "Tingnan Siya!"<br/>Araw-araw ay paghandaan Siya.<br/>',NULL,43597,1);
INSERT INTO stanza VALUES('T1307','chorus','Pagdating ni Hesus, sasalubong ka?<br/>Ang sarili mo natuos na ba?<br/>Siya''y darating na, pantas kukunin Niya,<br/>Nawa kasalo tayo sa pista.<br/>',NULL,43598,2);
INSERT INTO stanza VALUES('T1307','2','Tulungan kami, panahon tubusin,<br/>Langis punuin sisidlan namin;<br/>Tulungan kami, pagsubok tanggapin,<br/>Sa pag-ibig kami''y palaguin.<br/>',NULL,43599,3);
INSERT INTO stanza VALUES('T1307','chorus','Mahalagang panahon, Siya''y darating,<br/>Langis narito atin ngang bilhin.<br/>Mag-amen sa pagsubok at pighati,<br/>Upang makasama sa paghari.<br/>',NULL,43600,4);
INSERT INTO stanza VALUES('T1307','3','Iligtas Mo sa layaw ng kalul''wa,<br/>Pagmasdan Iyong magiliw na mukha,<br/>Magtumulin nang Nobyo''y salubungin,<br/>At asikasuhin ang takbuhin.<br/>',NULL,43601,5);
INSERT INTO stanza VALUES('T1307','chorus','Pagdating Niya, nasa presensya ba Niya?<br/>Mapagmasdan ba ang Kanyang mukha?<br/>Hu-wag nang bumalik sa katamaran,<br/>Kundi presensya Niya''y panghawakan.<br/>',NULL,43602,6);
INSERT INTO stanza VALUES('T1307','4','Bilang Nobya Niya, Siya ay salubungin,<br/>Ilawan maayos magniningning;<br/>Sisidla''y puno, mata''y sa gloria Niya,<br/>Lubhang kasiyahan kasama Siya.<br/>',NULL,43603,7);
INSERT INTO stanza VALUES('T1307','chorus','Oo siyang-siya — Kristo''t Nobya Niya,<br/>Walang hanggang kasiya-siya nga;<br/>Anong pag-ibig, pahinga''t ligaya,<br/>Maging Nobya Niya sa Kanyang pista!<br/>',NULL,43604,8);
INSERT INTO stanza VALUES('T1308','beginning-note','Mateo 25:1-13<br/>',NULL,43605,1);
INSERT INTO stanza VALUES('T1308','1','Ilawang may langis — Panginoon,<br/>Ilawang may langis ngayon!<br/>Ibaling kami sa espiritu,<br/>Pagbaling namin di-hihinto.<br/>',NULL,43606,2);
INSERT INTO stanza VALUES('T1308','chorus','Hesus, Amen, Aleluya!<br/>O gabi''t araw nagniningas!<br/>Hesus, Amen, Aleluya!<br/>Espiritu''y malakas!<br/>',NULL,43607,3);
INSERT INTO stanza VALUES('T1308','2','Langis ay kailangan ng sisidlan,<br/>Reserbang tustos ilaan;<br/>Sisidlan alay upang punuan<br/>Ningas di mamatay kailanman.<br/>',NULL,43608,4);
INSERT INTO stanza VALUES('T1308','chorus','Punuan Mo kami Hesus!<br/>Sarili Mo''y ibigay sa ''min!<br/>Babaran nga kami Hesus!<br/>Realidad puspusin!<br/>',NULL,43609,5);
INSERT INTO stanza VALUES('T1308','3','Tuloy pagningas hanggang dumating<br/>Araw Siya''y sasalubungin.<br/>Kasama Niya tayo sa kasalan,<br/>Tuloy pa rin nagniningasan!<br/>',NULL,43610,6);
INSERT INTO stanza VALUES('T1308','chorus','Halika na! O Pangino''n!<br/>Tingnan kami''y nagliliwanag!<br/>Halika na! O Pangino''n!<br/>Sa Nobya Mo''y magalak!<br/>',NULL,43611,7);
INSERT INTO stanza VALUES('T1310','1','Kasintahang mal''walhati,<br/>Angkop sa Sarili.<br/>Ninanasa ng Pangino''n<br/>Puso Niya''y may tugon.<br/>',NULL,43612,1);
INSERT INTO stanza VALUES('T1310','2','Napabanal ang ekklesia<br/>Sa Kanyang Salita;<br/>Dungis kulubot maalis<br/>Nobyang ninanais.<br/>',NULL,43613,2);
INSERT INTO stanza VALUES('T1310','3','Ginintuang araw tubusin,<br/>Salita''y kainin,<br/>Idalangin bawa''t linya,<br/>Sa Kanya''y mahanda.<br/>',NULL,43614,3);
INSERT INTO stanza VALUES('T1310','4','O, paanong ang Salita<br/>Tumagos, humati<br/>Sa ''spiritu at kalul''wa,<br/>Ang kubli''y iwaksi.<br/>',NULL,43615,4);
INSERT INTO stanza VALUES('T1310','5','Salamat sa Iyong Salita,<br/>Buhay gumagawa.<br/>Sa Iyong pagdating napukaw<br/>Pinamumuhay rin!<br/>',NULL,43616,5);
INSERT INTO stanza VALUES('T1310','6','Mapabalik Ka nga namin,<br/>Puso Mo''y bigyang-siya;<br/>Kapareha kami''y gawin,<br/>Tustos Iyong Salita.<br/>',NULL,43617,6);
INSERT INTO stanza VALUES('T1314','1','Magpapakita Ka,<br/>Halos narito na,<br/>Ibig Ka naming makita!<br/>Wala nang iba<br/>Buhay, irog pa,<br/>Kundi Hesus aming Sinta!<br/>',NULL,43618,1);
INSERT INTO stanza VALUES('T1314','2','Oras malapit na<br/>Iyong sigaw marinig,<br/>Sa ulap Ikaw pababa.<br/>O anong tamis!<br/>Magkasi''y magtagpo,<br/>May pag-ibig di matanto.<br/>',NULL,43619,2);
INSERT INTO stanza VALUES('T1314','3','Di maglalaon nga<br/>Mukha Mo''y makita,<br/>Hesus madaling dumating.<br/>Hangad mamasdan na<br/>At makasama Ka,<br/>Aming puso Iyong nakuha.<br/>',NULL,43620,3);
INSERT INTO stanza VALUES('T1314','4','Sandali na lamang;<br/>Aming Kasintahan<br/>Sunduin kaming Iyong Nobya.<br/>O Aleluya!<br/>Aming inaasam<br/>Nang lubos Kang masiyahan.<br/>',NULL,43621,4);
INSERT INTO stanza VALUES('T1316','1','Darating Nobyo natin,<br/>Nobya Niya''y kukunin,<br/>Mga niligawan Niya<br/>At pinabanal pa.<br/>Pangino''n maghahanda,<br/>Puso''y itutugma<br/>Sa araw ng kasal nalalapit na.<br/>',NULL,43622,1);
INSERT INTO stanza VALUES('T1316','chorus','Araw ng kasal darating,<br/>Malapit dumating;<br/>Ang Nobya maging handa,<br/>Sa Nobyo pakasal siya.<br/>Anong pag-alay, pagsinta,<br/>Puso''y tumutugma,<br/>Sa araw ng kasal nalalapit na.<br/>',NULL,43623,2);
INSERT INTO stanza VALUES('T1316','2','Daramtan tanang tayo<br/>Damit pinong lino;<br/>Tahi kada tahi nga,<br/>Ikaw ang gagawa.<br/>Bawa''t pagkakataon<br/>Aming tubusin ngayon<br/>Kasalan malapit na, Panginoon.<br/>',NULL,43624,3);
INSERT INTO stanza VALUES('T1316','3','Sa amin bahagi Mo,<br/>Dagdagan nang husto;<br/>Kami''y maanyayahan<br/>Sa piging kasalan.<br/>Maging mapagbantay nga—<br/>Gabi ma''t umaga—<br/>Sapagka''t kasalan nalalapit na.<br/>',NULL,43625,5);
INSERT INTO stanza VALUES('T1325','1','Walang hanggang Diyos may layon,<br/>Binuo sa nagdaan;<br/>Aabot sa hinaharap,<br/>Panahong walang hanggan.<br/>Sa panaho''y may hakbangin,<br/>Nang mai-sakatuparan;<br/>Dito tayo''y manlalakbay,<br/>Eternidad hantungan.<br/>',NULL,43626,1);
INSERT INTO stanza VALUES('T1325','2','Nais ng Diyos ng ''sang grupo<br/>Nakoordinang tao,<br/>Mai-tayo ayon sa plano,<br/>Sisidlang bagong tao.<br/>Papasok ang Diyos sa kanya,<br/>Dala''y kalikasan Niya;<br/>Espiritu sa ''spiritu,<br/>Anong galak at tuwa!<br/>',NULL,43627,2);
INSERT INTO stanza VALUES('T1325','3','Gawa ng Diyos: tatlong panig<br/>Para sa Kanyang plano.<br/>''Binigay Sarili Mismo,<br/>Ama, Anak, ''Spiritu.<br/>Langit, lupa''y inihanda,<br/>Para sa planong ito;<br/>May tatlong bahaging tao,<br/>Nilikha dahil dito.<br/>',NULL,43628,3);
INSERT INTO stanza VALUES('T1325','4','Ang espiritu ng tao,<br/>Sentro ng plano ng Diyos;<br/>Tawagin ngalan ni Hesus,<br/>Kai-sa natin Siyang lubos.<br/>Sa gitna tungong palibot,<br/>Puspusin ng Diyos ito;<br/>Babaguhin kaluluwa,<br/>Manahan sa ''ting puso.<br/>',NULL,43629,4);
INSERT INTO stanza VALUES('T1325','5','Tayo''y sa buhay nai-tayo,<br/>Sa pag-ibig nagkai-sa;<br/>Tinupad Ni-ya ang plano,<br/>Na Siya ring nagsimula.<br/>Iyong Sarili dagdagan Mo,<br/>Nang kami''y maitayo<br/>Sa sisidlang sama-sama<br/>Tanging Diyos ang nagpuno.<br/>',NULL,43630,5);
INSERT INTO stanza VALUES('T1325','6','Bilang ang kinalabasan,<br/>Ekklesia''y sa l''walhati;<br/>Kapuspusan ng layunin,<br/>Walang hanggang lunggati.<br/>Sama-sama ngang sisidlan,<br/>L''walhati Niya''y ilaman;<br/>Pangino''n kami''y lubusang<br/>Para sa Iyong inasam.<br/>',NULL,43631,6);
INSERT INTO stanza VALUES('T1326','1','Buhay ay ano nga ba?<br/>Anong sagot? Tingnan nga!<br/>',NULL,43632,1);
INSERT INTO stanza VALUES('T1326','2','Tawagin Hesu-Kristo,<br/>Siya nga''y sadyang totoo;<br/>Ang buhay masagana,<br/>Ilog umaagos na.<br/>Simulan bagong buhay,<br/>Ligaya''y tinataglay,<br/>Pinuspos ng pagsinta,<br/>Ito''y dahil sa Kanya! (Aleluya)<br/>',NULL,43633,2);
INSERT INTO stanza VALUES('T1327','1','Minsan naghanap ng bukal,<br/>Na makapagtighaw-uhaw,<br/>Mga bukal ininuman,<br/>Wala pa ring kasiyahan.<br/>Nguni''t isang araw,<br/>Nang Siya''y matagpuan,<br/>Bumukal sa ka''buturan<br/>Ang bukal ng buhay.<br/>Ininom Siya!<br/>Hesus! Hesus! Hesus! Hesus!<br/>Pinawi aking uhaw;<br/>Hesus! Hesus! Hesus! Hesus!<br/>Ngayon Siya''y aking buhay.<br/>',NULL,43634,1);
INSERT INTO stanza VALUES('T1327','2','Natikman bukal matamis,<br/>Puso sa bukal nagnais;<br/>Sa bundok may pangitain:<br/>Pagpupulong Herusalem.<br/>Hinanap, inuwi,<br/>Pagod ko''y napawi.<br/>Nananahan sa ekklesia,<br/>''Di na maghanap nga.<br/>Aleluya!<br/>Hesus! Hesus! Hesus! Hesus<br/>Pinawi aking uhaw;<br/>Hesus! Hesus! Hesus! Hesus!<br/>Ngayon Siya''y aking buhay.<br/>',NULL,43635,2);
INSERT INTO stanza VALUES('T1327','3','Huwag ka nang magpumiglas pa,<br/>Paggala''y tigilan na!<br/>Manalig, buksan iyong puso,<br/>Ngalang Hesus tawagin mo.<br/>Ngayo''y iyong matamo,<br/>Buhay pasok sa iyo,<br/>Kaugpong mo Siya''t kai-sa rin—<br/>Iyong saya''t tamasa.<br/>Nais mo ba?<br/>Hesus! Hesus! Hesus! Hesus!<br/>Pinawi aking uhaw;<br/>Hesus! Hesus! Hesus! Hesus!<br/>Ngayon Siya''y aking buhay.<br/>',NULL,43636,3);
INSERT INTO stanza VALUES('T1330','1','"Lahat handa na," pistahan na!<br/>Magpiging, nakahain na;<br/>Mga gutom at ang pagod,<br/>Halina at mabusog.<br/>',NULL,43637,1);
INSERT INTO stanza VALUES('T1330','chorus','Dinggin paanyaya,<br/>Sinumang may nasa;<br/>Kaligtasa''y tanggapin,<br/>Kristo ang may hain.<br/>',NULL,43638,2);
INSERT INTO stanza VALUES('T1330','2','"Lahat handa na," pistahan na!<br/>Bukas ang pinto ng b''yaya;<br/>Sa iyo''y marangal na p''westo,<br/>Nasa tabi ni Kristo.<br/>',NULL,43639,3);
INSERT INTO stanza VALUES('T1330','3','"Lahat handa na," pistahan na!<br/>Halika, naghihintay Siya;<br/>Ngayon na''t huwag mag-antala<br/>Baka bukas wala na!<br/>',NULL,43640,5);
INSERT INTO stanza VALUES('T1330','4','"Lahat handa na," pistahan na!<br/>Bitiwan ang pag-alala!<br/>Kristo ng Diyos tamasahin,<br/>Bilang buhay inumin.<br/>',NULL,43641,7);
INSERT INTO stanza VALUES('T1339','beginning-note','Awit 133<br/>',NULL,43642,1);
INSERT INTO stanza VALUES('T1339','1','Anong buti at kaaya-aya,<br/>Kapatid nagsitahang nagkakaisa!<br/>Anong buti at kaaya-aya,<br/>Kapatid nagsitahang nagkakaisa!<br/>',NULL,43643,2);
INSERT INTO stanza VALUES('T1339','chorus','Tulad ng mahalagang langis sa ulo,<br/>Sa balbas tumutulo:<br/>Balbas ni Aaron,<br/>Hanggang sa laylayan ng suot niya.<br/>',NULL,43644,3);
INSERT INTO stanza VALUES('T1339','2','Anong buti at kaaya-aya,<br/>Kapatid nagsitahang nagkakaisa!<br/>',NULL,43645,4);
INSERT INTO stanza VALUES('T1339','chorus','Tulad ng mahalagang langis sa ulo,<br/>Sa balbas tumutulo:<br/>Balbas ni Aaron,<br/>Hanggang sa laylayan ng suot niya.<br/>',NULL,43646,5);
INSERT INTO stanza VALUES('T1339','3','Gayang hamog Hermon,<br/>Gayang bumababang hamog.<br/>Sa mga bundok ng Sion<br/>Pinarating do''n ang pagpapala,<br/>Buhay magpakailanman.<br/>',NULL,43647,6);
INSERT INTO stanza VALUES('T1349','1','Sa umaga''t hapon, magpunla ng awa,<br/>Diligan ng luha at panalangin,<br/>Hintayin ang ani at pag panahon na,<br/>Buong kagalakang ani ay dalhin.<br/>',NULL,43648,1);
INSERT INTO stanza VALUES('T1349','chorus','Ani ay dalhin, ani ay dalhin!<br/>At sa kagalakan, ani ay dalhin!<br/>Ani ay dalhin, ani ay dalhin,<br/>At sa kagalakan, ani ay dalhin!<br/>',NULL,43649,2);
INSERT INTO stanza VALUES('T1349','2','Magpunla sa t''wina, bagyo ma''y sumapit,<br/>Huwag katatakutan bugso ng hangin;<br/>Di-kalalaunan, tag-ani''y sasapit,<br/>At may kagalakang ani ay dalhin.<br/>',NULL,43650,3);
INSERT INTO stanza VALUES('T1349','3','Luha ma''y tumulo tayo''y magpatuloy,<br/>Sa Diyos lang alay pagpapagal natin;<br/>Pagtigil ng luha, galak ang dadaloy,<br/>At may kagalakang ani''y dadalhin.<br/>',NULL,43651,5);
INSERT INTO stanza VALUES('T1350','1','Ako ay na kay Kristo,<br/>Kagalaka''y natamo!<br/>Kay Adam napalaya,<br/>Nabago ang luma.<br/>Purihin ang Diyos! Kalayaan,<br/>Buhay, kapayapaan,<br/>Aking tamasa walang hanggan!<br/>',NULL,43652,1);
INSERT INTO stanza VALUES('T1351','1','Tunay na Diyos, sa awa Niya''y nakita;<br/>Sa liwanag Niya, ako''y maligaya;<br/>Di na kailangan ang gawa at sikap;<br/>Biyaya Niya, "Ako''y naligtas na!"<br/>',NULL,43653,1);
INSERT INTO stanza VALUES('T1351','2','Kasambahay ko''y Iyong alalahanin,<br/>Pinasan Mo na sala''t hirap nila;<br/>Tuparin Mo ngayon ang Iyong pangako,<br/>"Maniwala''t, maliligtas sila."<br/>',NULL,43654,2);
INSERT INTO stanza VALUES('T1351','3','Dalangin ko''y, dinggin Mo, Panginoon,<br/>Alay ko sa Iyo, aking sambahayan;<br/>Maglilingkod kami sa Diyos na tunay,<br/>Sasambahin, magpakailan pa man!<br/>',NULL,43655,3);
INSERT INTO stanza VALUES('T1352','1','Sukdulang pagpapala''y tamuhin,<br/>Sa tuwinang pagtahan kay Kristo,<br/>Pagsalamuha''y panatilihin<br/>Upang mga hadlang ay maglaho.<br/>',NULL,43656,1);
INSERT INTO stanza VALUES('T1352','2','Sa pagtahan, pagpahid aagos;<br/>Sa pagtalima''t pagsalamuha,<br/>Paggabay ng ''Spiritu''y matalos,<br/>Pagsunod, yaman Niya''y makukuha.<br/>',NULL,43657,2);
INSERT INTO stanza VALUES('T1352','3','Liwanag ng biyaya''y sisilay;<br/>Sa pananaha''t pagsalamuha.<br/>Ilaw ay sundin, buhay lalago;<br/>Sa dilim napalaya ang puso.<br/>',NULL,43658,3);
INSERT INTO stanza VALUES('T1352','4','Sa pagtahan, lalakas, sisigla,<br/>Mga daing nagiging awitin,<br/>Sa pagsalamuha''y liligaya—<br/>Kamatayan sa buhay lulunin!<br/>',NULL,43659,4);
INSERT INTO stanza VALUES('T1352','5','Si Satanas at ang kasalanan,<br/>Sa pananahan ay magwawakas;<br/>Sarili man at ang sanlibutan,<br/>Sa pagsasalamuha''y lilipas.<br/>',NULL,43660,5);
INSERT INTO stanza VALUES('T1352','6','Sa pagtahan makawawangis Niya;<br/>Kapangyariha''y mararanasan;<br/>Mapupuspos sa pagsalamuha,<br/>Ng Kanyang buhay at kayamanan.<br/>',NULL,43661,6);
INSERT INTO stanza VALUES('T1352','7','Mananahan, Panginoon, sa Iyo;<br/>Pagsalamuha ang hangarin ko,<br/>Ako''y lubusang mawala sa Iyo<br/>Walang hanggang maihalo sa Iyo.<br/>',NULL,43662,7);
INSERT INTO stanza VALUES('T1353','1','Sa ilaw ng buhay,<br/>Magmasid, mamuhay;<br/>Ang pagsalamuha<br/>Kay tamis sa t''wina;<br/>Laging nagpupuri,<br/>Higit ang l''walhati;<br/>Sa ilaw mamuhay.<br/>',NULL,43663,1);
INSERT INTO stanza VALUES('T1354','1','Pagdating ng Panginoon, at trumpeta''y tutunog,<br/>Muling mabubuhay ang natutulog;<br/>Aakyat-may-kagalakan — mga hindi namatay,<br/>Pati katawa''y babaguhing tunay.<br/>',NULL,43664,1);
INSERT INTO stanza VALUES('T1354','chorus','Pagdating ng Panginoon<br/>Sa Kanyang kal''walhatian,<br/>Tayo''y babaguhing-anyo,<br/>Tulad ng mal''walhati Niyang katawan.<br/>',NULL,43665,2);
INSERT INTO stanza VALUES('T1354','2','Pagdating ng Panginoon, magbubukang-liwayway;<br/>Lilipas ang gabi, pagluha''t lumbay.<br/>Mal''walhating mga araw magsisipagsimula;<br/>Mawawala buntong hininga''t sama.<br/>',NULL,43666,3);
INSERT INTO stanza VALUES('T1354','3','Pagdating ng Panginoon, magniningning ang tala,<br/>Ang nagbabantay ay may gantimpala;<br/>Bilang Araw ng kat''wiran, Pangino''n maghahari;<br/>Habag matanto, lupa''y manauli.<br/>',NULL,43667,5);
INSERT INTO stanza VALUES('T1354','4','Darating ang Panginoon; magbantay, manalangin,<br/>Maghanda, ilawa''y paliwanagin.<br/>Kaloob ay gamitin; Siya''y paglingkuran nang tapat,<br/>Upang ministeryo''y ating matupad.<br/>',NULL,43668,7);
INSERT INTO stanza VALUES('T1355','1','Sala''y pinatawad ng Diyos;<br/>Sa likuran Niya''y tinapon.<br/>Kanyang nilimot nang lubos,<br/>Salang nilupig Niya noon.<br/>',NULL,43669,1);
INSERT INTO stanza VALUES('T1355','chorus','Sala''y pinatawad ng Diyos,<br/>Parang ulap na pinawi,<br/>Sala ko''y naglahong lubos!<br/>Kailan ma''y di mababawi.<br/>',NULL,43670,2);
INSERT INTO stanza VALUES('T1355','2','Nilibing sa karagatan,<br/>Salang simbigat ng bato.<br/>Silangan hanggang kanluran—<br/>Layo sa ''kin ng sala ko!<br/>',NULL,43671,3);
INSERT INTO stanza VALUES('T1356','1','L''walhati! Si Kristo nga''y buhay!<br/>L''walhati! Espiritu''y gabay!<br/>Hina naging lakas, dilim, liwanag!<br/>L''walhati! Si Kristo nga''y buhay!<br/>',NULL,43672,1);
INSERT INTO stanza VALUES('T1356','2','L''walhati! Mamuhay kay Kristo!<br/>L''walhati! Sundan Espiritu!<br/>Taghoy naging awit, bigo''y tagumpay!<br/>L''walhati! Mamuhay kay Kristo!<br/>',NULL,43673,2);
INSERT INTO stanza VALUES('T1357','1','O anong galak,<br/>Puso ko''y pinuspos!<br/>O anong galak,<br/>Ginawang laman puso kong bato,<br/>Espiritu Niya''y pinabago ako.<br/>O anong galak,<br/>Puso ko''y pinuspos!<br/>',NULL,43674,1);
INSERT INTO stanza VALUES('T1357','2','Espiritu Niya,<br/>Pinupuspos ako!<br/>Espiritu Niya,<br/>Pinaalis sala''t kahinaan,<br/>Upang ako''y mamunga ng kat''wiran.<br/>Espiritu Niya,<br/>Pinupuspos ako!<br/>',NULL,43675,2);
INSERT INTO stanza VALUES('T1358','1','Bangon at ihayag ang ebanghelyo!<br/>Sagipin ang natisod na tao!<br/>Nasa dilim sila, napapahamak!<br/>Nasaan ang iyong pusong may habag?<br/>Bangon! Magpahayag! Tao''y ibigin!<br/>Ang panahon ay samantalahin!<br/>',NULL,43676,1);
INSERT INTO stanza VALUES('T1359','1','Kunin Mo aking buhay,<br/>Ito''y aking inalay;<br/>Aking araw, sandali,<br/>Sa Iyo ako''y pupuri.<br/>',NULL,43677,1);
INSERT INTO stanza VALUES('T1359','chorus','Hinamak Ka dahil sa akin;<br/>Kusang nagdugo''t namatay rin.<br/>Sa Iyo binuhos buhay ko''t pagsinta,<br/>Paglilingkuran Kita.<br/>',NULL,43678,2);
INSERT INTO stanza VALUES('T1359','2','Kunin paa ko''t kamay,<br/>Sa gawa Mo''y igabay.<br/>Iyong angkinin labi ko,<br/>Ihayag Salita Mo.<br/>',NULL,43679,3);
INSERT INTO stanza VALUES('T1359','3','Kunin pilak ko''t ginto;<br/>Kunin nang walang hinto,<br/>Kunin ang talino ko,<br/>Iyong gamitin nang husto.<br/>',NULL,43680,5);
INSERT INTO stanza VALUES('T1359','4','Puso''t isip ko''y sa Iyo;<br/>Iyo lamang mga ito.<br/>Pag-ibig ko''y kunin Mo,<br/>Sa Iyo ibuhos ito!<br/>',NULL,43681,7);
INSERT INTO stanza VALUES('T1359','5','Hesus, kunin Mo ako<br/>Hanggang makaisa Mo.<br/>Kunin Mo sarili ko,<br/>Ako ay para sa Iyo.<br/>',NULL,43682,9);
INSERT INTO stanza VALUES('T1360','1','Mal''walhati! Mahalaga!<br/>Espiritu sa akin!<br/>Liwanag, katotohanan,<br/>Dinadala sa akin.<br/>',NULL,43683,1);
INSERT INTO stanza VALUES('T1360','chorus','Puspusin! Puspusin!<br/>O, ng Iyong Espiritu!<br/>Lahat ko ay Iyong alisin,<br/>Pun''an ng Espiritu!<br/>',NULL,43684,2);
INSERT INTO stanza VALUES('T1360','2','Salita Mo''y tunay sa ''kin,<br/>Buhay Mo''y kalayaan—<br/>Sa sala ako''y hanguin,<br/>Maging sa kamatayan.<br/>',NULL,43685,3);
INSERT INTO stanza VALUES('T1360','3','Ikaw ay batis ng buhay,<br/>Gaya ko''y usang uhaw;<br/>Iinumin Kita hanggang<br/>Ikaw sa ''ki''y umapaw.<br/>',NULL,43686,5);
INSERT INTO stanza VALUES('T1360','4','Mamatay nawa sarili,<br/>Ikaw lang ang susundin,<br/>Upang sa Iyo mapawangis,<br/>Ikaw ay paagusin.<br/>',NULL,43687,7);
INSERT INTO stanza VALUES('T10001','beginning-note','Psalm 2<br/>',NULL,43688,1);
INSERT INTO stanza VALUES('T10001','1','Lo, the nations all assemble<br/>And imagine vanity,<br/>Kings and princes plot together<br/>''Gainst the Lord in unity.<br/>"Let us break their bonds asunder,<br/>Cast away their cords from us."<br/>''Gainst the Lord and His Anointed<br/>Worldly rulers counsel thus.<br/>',NULL,43689,2);
INSERT INTO stanza VALUES('T10001','2','He who sitteth in the heavens<br/>In contempt will laugh at them,<br/>Vex them in His fierce displeasure,<br/>Terrifying all such men.<br/>Yet upon the hill of Zion<br/>God has anointed King—<br/>This is God''s own declaration,<br/>All the kings admonishing.<br/>',NULL,43690,3);
INSERT INTO stanza VALUES('T10001','3','Now ''tis Christ, ''tis God''s Anointed,<br/>Who declares the Lord''s decree:<br/>"Thou''rt my Son (in resurrection),<br/>This day I''ve begotten Thee<br/>All the nations I will give Thee<br/>For Thine own inheritance.<br/>Thou shalt dash them into pieces<br/>In Thy kingly excellence."<br/>',NULL,43691,4);
INSERT INTO stanza VALUES('T10001','4','Now be wise, O be instructed,<br/>All ye rulers of the earth,<br/>Fear the Lord, rejoice with trembling,<br/>Serve the only One of worth.<br/>Kiss the Son, lest He be angry<br/>And ye perish in the way.<br/>"All who trust in Him are blessed,"<br/>All who trust in Him will say.<br/>',NULL,43692,5);
INSERT INTO stanza VALUES('T10001','5','Lord, we praise Thee, we have seen Him—<br/>Thy unique Anointed One—<br/>And from vanity repenting,<br/>We in love have kissed Thy Son.<br/>"All who trust in Him are blessed"—<br/>Not "all those who keep the law."<br/>In that risen One believing,<br/>We are blest forevermore.<br/>',NULL,43693,6);
INSERT INTO stanza VALUES('T10001','1','Magugulong bansa hangad ay walang kabuluhan,<br/>Mga hari''t pinuno naghanda, nagsanggunian<br/>Laban sa Panginoon at sa Kanyang Pinahiran,<br/>Lagutin kanilang tali nang tayo''y makalagan.<br/>',NULL,43694,7);
INSERT INTO stanza VALUES('T10001','2','Si-yang nauupo sa kalangitan ay tatawa:<br/>Diyos, sa labis na pagdaramdam, binalisa sila,<br/>Gayon ma''y sa bundok Sion, naro''n Haring Pinahiran,<br/>Tungkol sa pasya, Diyos, lahat ng hari sinabihan.<br/>',NULL,43695,8);
INSERT INTO stanza VALUES('T10001','3','Ang Siyang Pinahiran ng Diyos ngayon ay si Kristo nga,<br/>"Ikaw ay Aking anak", Panginoon nagsasaysay.<br/>Mga bansa ibibigay Ko sa Iyo na Iyong mana<br/>Sa husay ng paghahari dudurugin Mo sila.<br/>',NULL,43696,9);
INSERT INTO stanza VALUES('T10001','4','O magpakapantas kayong mga hari ng lupa,<br/>Maglingkod ng may takot, sa panginginig magalak,<br/>Anak hagkan baka magalit, kayo''y mapahamak,<br/>"Pinagpala lahat ng sa Kanya''y nagtitiwala."<br/>',NULL,43697,10);
INSERT INTO stanza VALUES('T10001','5','Purihin Ka namin nakita Kang ang Pinahiran,<br/>Nagsisisi kami, sa pag-ibig Anak hinagkan.<br/>"Pinagpala lahat ng sa Kanya''y nagtitiwala"<br/>At sa sumampalataya sa nabuhay na Isa.<br/>',NULL,43698,11);
INSERT INTO stanza VALUES('T10003','beginning-note','Psalm 8<br/>',NULL,43699,1);
INSERT INTO stanza VALUES('T10003','1','O Lord, our Lord, how excellent<br/>Is Thy name in all the earth!<br/>Who hast set Thy glory above,<br/>Glory above the heavens.<br/>Out of the mouth of babes and sucklings<br/>Hast Thou established praise,<br/>That Thou mightest still him who is,<br/>Still him who is the enemy.<br/>',NULL,43700,2);
INSERT INTO stanza VALUES('T10003','chorus','When I consider Thy heavens,<br/>And the work of Thy fingers,<br/>The moon, the stars, which Thou hast ordained;<br/>What is man, that Thou art mindful of him?<br/>',NULL,43701,3);
INSERT INTO stanza VALUES('T10003','2','Thou hast made him a little lower<br/>Than all the angels,<br/>And Thou hast crowned him,<br/>Crowned him with glory,<br/>Crowned him with glory and honor.<br/>Thou madest him to have dominion<br/>Over the works of Thy hands;<br/>Thou hast put all things under him,<br/>Thou hast put all things under his feet.<br/>',NULL,43702,4);
INSERT INTO stanza VALUES('T10003','chorus','All sheep and oxen,<br/>And the beasts of the field;<br/>The fowl of the air, and the fish of the sea,<br/>And whatsoever passes through it.<br/>',NULL,43703,5);
INSERT INTO stanza VALUES('T10004','beginning-note','Psalm 16:5,8,9,11<br/>',NULL,43704,1);
INSERT INTO stanza VALUES('T10004','1','The Lord is the portion of my inheritance,<br/>And He is my cup;<br/>The Lord is the portion of my inheritance,<br/>And He is my cup.<br/>',NULL,43705,2);
INSERT INTO stanza VALUES('T10004','chorus','Thou wilt show me the path of life,<br/>Thy presence is fullness of joy;<br/>At Thy right hand there are pleasures<br/>Forevermore.<br/>',NULL,43706,3);
INSERT INTO stanza VALUES('T10004','2','For I have set Jesus forever before me,<br/>He''s at my right hand;<br/>For I have set Jesus forever before me,<br/>He''s at my right hand.<br/>',NULL,43707,4);
INSERT INTO stanza VALUES('T10004','chorus','Thou wilt show me the path of life,<br/>Thy presence is fullness of joy;<br/>At Thy right hand there are pleasures<br/>Forevermore.<br/>',NULL,43708,5);
INSERT INTO stanza VALUES('T10004','3','Therefore is my heart glad, my spirit rejoiceth,<br/>My flesh rests in hope;<br/>Therefore is my heart glad, my spirit rejoiceth,<br/>My flesh rests in hope.<br/>',NULL,43709,6);
INSERT INTO stanza VALUES('T10005','beginning-note','Psalm 30:11,12<br/>',NULL,43710,1);
INSERT INTO stanza VALUES('T10005','1','Thou hast turned my mourning into dancing for me,<br/>Thou hast put off my sackcloth;<br/>Thou hast turned my mourning into dancing for me,<br/>And girded me with gladness;<br/>To the end my glory may sing praise unto Thee,<br/>And not be silent.<br/>O Lord my God, I will give thanks unto Thee forever.<br/>',NULL,43711,2);
INSERT INTO stanza VALUES('T10006','beginning-note','Psalm 34:8-10<br/>',NULL,43712,1);
INSERT INTO stanza VALUES('T10006','1','Oh, taste and see that the Lord is good.<br/>Oh, taste and see that the Lord is good.<br/>How faithful our Lord Jesus is;<br/>Blessed is the man that trust in Him.<br/>There is no want to them that fear Him.<br/>The young li-ons do lack and hunger,<br/>But they that seek the Lord Jesus<br/>Shall not want any good thing.<br/>',NULL,43713,2);
INSERT INTO stanza VALUES('T10007','beginning-note','Psalm 45<br/>',NULL,43714,1);
INSERT INTO stanza VALUES('T10007','1','Our hearts are overflowing<br/>To speak a goodly thing—<br/>To tell what we''ve experienced<br/>Of our exalted King.<br/>Our tongues as pens are ready,<br/>We''ve volumes here to "write"—<br/>The glories of our Bridegroom,<br/>Our Lord and our delight.<br/>',NULL,43715,2);
INSERT INTO stanza VALUES('T10007','2','Lord Jesus, Thou art fairer<br/>Than all the sons of men;<br/>Thy goodness is transcendent—<br/>Hallelujah! Amen!<br/>Upon Thy lips most holy<br/>Abundant grace is poured;<br/>Forever God has blessed Thee,<br/>Our gracious, glorious Lord!<br/>',NULL,43716,3);
INSERT INTO stanza VALUES('T10007','3','Thou art the mighty Warrior<br/>Who rides to victory;<br/>In Thy majestic glory<br/>Ride on triumphantly!<br/>The peoples fall beneath Thee—<br/>The conquering One Thou art.<br/>Thine arrows in their sharpness<br/>Have entered Satan''s heart!<br/>',NULL,43717,4);
INSERT INTO stanza VALUES('T10007','4','Thy throne, O God, forever<br/>And ever shall endure;<br/>The sceptre of Thy kingdom<br/>Upon the earth is sure.<br/>''Tis with the oil of gladness<br/>God has anointed Thee<br/>Above all Thy companions—<br/>How worthy there to be!<br/>',NULL,43718,5);
INSERT INTO stanza VALUES('T10007','5','Of aloes, myrrh, and cassia<br/>Do all Thy garments smell;<br/>Thy death and Thy resurrection<br/>Do all Thy deeds forthtell.<br/>Out of the local churches<br/>Shall praises make Thee glad,<br/>And praises upon praises<br/>Thy joyful saints shall add.<br/>',NULL,43719,6);
INSERT INTO stanza VALUES('T10009','beginning-note','Psalm 48:1-2<br/>',NULL,43720,1);
INSERT INTO stanza VALUES('T10009','1','Great is the Lord, and greatly to be praised,<br/>In the city of our God,<br/>In the mountain of His holiness.<br/>Beautiful in elevation, the joy of the whole earth,<br/>Is Mount Zion, on the sides of the north,<br/>The city of the great King.<br/>Is Mount Zion, on the sides of the north,<br/>The city of the great King.<br/>',NULL,43721,2);
INSERT INTO stanza VALUES('T10010','beginning-note','Psalm 50:1-6<br/>',NULL,43722,1);
INSERT INTO stanza VALUES('T10010','1','Out of Zion,<br/>The perfection of beauty, God hath shined.<br/>Out of Zion,<br/>The perfection of beauty, God hath shined.<br/>',NULL,43723,2);
INSERT INTO stanza VALUES('T10010','chorus','The mighty God, even the Lord,<br/>The mighty God, even the Lord, hath spoken,<br/>And called the earth from the rising of the sun<br/>Unto the going down thereof.<br/>',NULL,43724,3);
INSERT INTO stanza VALUES('T10010','2','Our God shall come,<br/>He shall come, and shall not keep silence.<br/>He shall call<br/>To the heavens above and to the earth.<br/>',NULL,43725,4);
INSERT INTO stanza VALUES('T10010','3','Gather My saints,<br/>Gather My saints together unto me.<br/>And the heavens<br/>Shall declare His righteousness, Selah!<br/>',NULL,43726,5);
INSERT INTO stanza VALUES('T10011','beginning-note','Psalm 68<br> (Tune: Hymn#149)<br/>',NULL,43727,1);
INSERT INTO stanza VALUES('T10011','1','God shall rise, His foes be scattered,<br/>All that hate Him flee away.<br/>As the wax before the fire,<br/>All the wicked He shall slay.<br/>But the righteous shall rejoice<br/>With a loud, triumphant voice,<br/>Singing praises, singing praises,<br/>Singing praises unto God!<br/>',NULL,43728,2);
INSERT INTO stanza VALUES('T10011','2','He is riding through the deserts,<br/>Bringing in His saints in need.<br/>He''s a Father to the orphans<br/>And a refuge tried indeed<br/>In His holy habitation—<br/>What a wonderful salvation!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43729,3);
INSERT INTO stanza VALUES('T10011','3','Here the lone have found a family,<br/>Here the desolate a home;<br/>Prisoners are brought from bondage<br/>To prosperity unknown.<br/>For the flock — what wondrous grace—<br/>God prepared this dwelling place:<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43730,4);
INSERT INTO stanza VALUES('T10011','4','Now the Lord in mighty triumph<br/>Sends the news of victory;<br/>We the "women" spread the tidings—<br/>"Kings of armies flee, they flee!"<br/>No more sweat and dreary toil;<br/>We at home divide the spoil!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43731,5);
INSERT INTO stanza VALUES('T10011','5','Lo, on high Christ hath ascended,<br/>Leading captives in His train;<br/>These as gifts He has perfected<br/>That the Lord may dwell with them.<br/>Brothers, sisters, we are those,<br/>We''re those transformed, vanquished foes!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43732,6);
INSERT INTO stanza VALUES('T10011','6','Blessed be the Lord forever:<br/>Day by day He loads with good,<br/>E''en the God of our salvation—<br/>Spread His worthy praise abroad.<br/>His the goings forth from death,<br/>Every foe He conquereth!<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43733,7);
INSERT INTO stanza VALUES('T10011','7','They have seen, O God, Thy goings<br/>In Thy holy dwelling place,<br/>Thy triumphal, high processions<br/>Midst a mighty voice of praise.<br/>See the singers go before,<br/>Praising, praising o''er and o''er:<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43734,8);
INSERT INTO stanza VALUES('T10011','8','Little Benjamin is leading,<br/>Then great Judah''s company:<br/>Son of sorrow at God''s right hand,<br/>Lion with the scepter see.<br/>Zebulun and Naphtali<br/>Make the joyful tidings fly:<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43735,9);
INSERT INTO stanza VALUES('T10011','9','Saints, thy strength has been commanded<br/>From the temple glorious;<br/>Still we pray that God may strengthen<br/>All that He has wrought for us.<br/>Higher yet our praise shall rise<br/>Till the utmost earth replies:<br/>Hallelujah, hallelujah,<br/>Hallelujah, Amen!<br/>',NULL,43736,10);
INSERT INTO stanza VALUES('T10012','beginning-note','Psalm 89 / Mga Awit 89<br/>',NULL,43737,1);
INSERT INTO stanza VALUES('T10012','1','I will sing of the mercies of the Lord forever,<br/>I will sing, I will sing;<br/>What a mercy that I am in the church forever;<br/>I will sing of the mercies of the Lord.<br/>',NULL,43738,2);
INSERT INTO stanza VALUES('T10012','chorus','With my mouth will I make known<br/>Thy faithfulness, Thy faithfulness,<br/>With my mouth will I make known<br/>Thy faithfulness to all generations.<br/>',NULL,43739,3);
INSERT INTO stanza VALUES('T10012','2','I will sing of the mercies of the Lord forever,<br/>I will sing, I will sing;<br/>What a mercy that I am in the church forever;<br/>I will sing of the mercies of the Lord.<br/>',NULL,43740,4);
INSERT INTO stanza VALUES('T10012','chorus','With my mouth will I make known<br/>Thy faithfulness, Thy faithfulness,<br/>With my mouth will I make known<br/>Thy faithfulness to all generations.<br/>',NULL,43741,5);
INSERT INTO stanza VALUES('T10012','1','Aawitin ko ang habag ng Panginoon<br/>Awitin, awitin;<br/>Anong habag na ako''y nasa ekklesia,<br/>Aawitin ang habag ng Poon.<br/>',NULL,43742,6);
INSERT INTO stanza VALUES('T10012','chorus','Aking bibig ''pabatid<br/>Katapatang walang hanggan,<br/>Aking bibig ''pabatid<br/>Tapat Ka sa buong saling-lahi.<br/>',NULL,43743,7);
INSERT INTO stanza VALUES('T10012','2','Aawitin ko ang habag ng Panginoon<br/>Awitin, awitin;<br/>Anong habag na ako''y nasa ekklesia,<br/>Aawitin ang habag ng Poon.<br/>',NULL,43744,8);
INSERT INTO stanza VALUES('T10012','chorus','Aking bibig ''pabatid<br/>Katapatang walang hanggan,<br/>Aking bibig ''pabatid<br/>Tapat Ka sa buong saling-lahi.<br/>',NULL,43745,9);
INSERT INTO stanza VALUES('T10013','beginning-note','Psalm 95:1-7<br/>',NULL,43746,1);
INSERT INTO stanza VALUES('T10013','1','O come, let us sing unto the Lord;<br/>Let us make a joyful noise—<br/>To the rock of our salvation.<br/>Let us come before His presence with thanksgiving,<br/>And make a joyful noise unto Him with psalms.<br/>',NULL,43747,2);
INSERT INTO stanza VALUES('T10013','chorus','For the Lord is a great God,<br/>And a great King above all gods;<br/>In His hands are the deep places of the earth,<br/>The strength of the hills is His also,<br/>The sea is His, and He made it,<br/>And His hands formed the dry land.<br/>',NULL,43748,3);
INSERT INTO stanza VALUES('T10013','2','O come, let us worship and bow down,<br/>Let us kneel before the Lord, our Maker.<br/>For He is our God, and we<br/>Are the people of His pasture;<br/>And the sheep of His hand today<br/>If we will hear His voice.<br/>',NULL,43749,4);
INSERT INTO stanza VALUES('T10014','beginning-note','Psalm 98:1-6<br/>',NULL,43750,1);
INSERT INTO stanza VALUES('T10014','1','O sing unto the Lord a new song,<br/>For He hath done marvelous things;<br/>His right hand and His holy arm<br/>Hath gotten Him the victory.<br/>',NULL,43751,2);
INSERT INTO stanza VALUES('T10014','2','The Lord hath made known His salvation,<br/>And His righteousness He openly showed;<br/>In the sight of the nations,<br/>O sing unto the Lord a new song.<br/>',NULL,43752,3);
INSERT INTO stanza VALUES('T10014','3','He hath remembered His mercy,<br/>And His truth toward the house of Israel—<br/>All the ends of the earth have seen<br/>The salvation of our God.<br/>',NULL,43753,4);
INSERT INTO stanza VALUES('T10014','4','Make a joyful noise unto the Lord,<br/>All the earth make a loud noise,<br/>And rejoice and sing praise,<br/>O sing unto the Lord a new song.<br/>',NULL,43754,5);
INSERT INTO stanza VALUES('T10014','5','Sing unto the Lord with the harp,<br/>With the harp and the voice of a psalm;<br/>With trumpets and sound of cornets<br/>Make a joyful noise before the Lord the King.<br/>',NULL,43755,6);
INSERT INTO stanza VALUES('T10015','beginning-note','Psalm 100<br/>',NULL,43756,1);
INSERT INTO stanza VALUES('T10015','1','Make a joyful noise unto the Lord,<br/>All ye people of the earth;<br/>And with gladness come and serve the Lord,<br/>Come before Him with singing;<br/>Know ye that the Lord He is God,<br/>It is He that hath made us,<br/>And not we ourselves; we are His people,<br/>And the sheep of His pasture.<br/>And with thanksgiving enter His gates,<br/>Into His courts with praise;<br/>Let us now give thanks unto the Lord,<br/>And bless His name.<br/>For the Lord is good,<br/>His lovingkindness is forever<br/>And His faithfulness unto all generations.<br/>',NULL,43757,2);
INSERT INTO stanza VALUES('T10016','beginning-note','Psalm 150<br/>',NULL,43758,1);
INSERT INTO stanza VALUES('T10016','1','Praise ye the Lord.<br/>Praise God in His sanctuary;<br/>Praise Him in the firmament of His power.<br/>Praise Him for His mighty acts:<br/>Praise Him according,<br/>Praise Him according to His exc''llent greatness.<br/>Praise Him with the sound of the trumpet;<br/>Praise Him with the psaltery and harp.<br/>Praise Him with the timbrel and dance;<br/>Praise Him with stringed instruments and organs.<br/>Praise Him upon the loud cymbals;<br/>Praise Him on the high sounding cymbals.<br/>Let everything that hath breath praise the Lord.<br/>Praise ye the Lord.<br/>',NULL,43759,2);
INSERT INTO stanza VALUES('T10017','beginning-note','Isaiah 12:3-4, 6<br/>',NULL,43760,1);
INSERT INTO stanza VALUES('T10017','1','Therefore with joy shall ye draw water<br/>Out of the wells of salvation.<br/>And in that day shall ye say, "Praise the Lord!"<br/>Therefore with joy shall ye draw water<br/>Out of the wells of salvation.<br/>And in that day shall ye say, "Praise the Lord!"<br/>Call upon His name, declare His doings among the people,<br/>Make mention that His name is exalted.<br/>Cry out and shout, thou inhabitant of Zion:<br/>For great is the Holy One of Israel in the midst of thee.<br/>',NULL,43761,2);
INSERT INTO stanza VALUES('T10018','beginning-note','Isaiah 12<br/>',NULL,43762,1);
INSERT INTO stanza VALUES('T10018','1','We will sing praise to the Lord,<br/>His name we will exalt;<br/>We will give thanks to the Lord,<br/>His name we will exalt.<br/>For He hath done the excellent things here,<br/>Let this be known in all the earth.<br/>We will give thanks to the Lord,<br/>His name we will exalt.<br/>',NULL,43763,2);
INSERT INTO stanza VALUES('T10019','1','I stand amazed in the presence<br/>Of Jesus the Nazarene,<br/>And wonder how He could love me,<br/>A sinner condemned, unclean.<br/>',NULL,43764,1);
INSERT INTO stanza VALUES('T10019','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me.<br/>',NULL,43765,2);
INSERT INTO stanza VALUES('T10019','2','For me it was in the garden,<br/>He prayed: "Not My will, but Thine."<br/>He had no tears for His own griefs,<br/>But sweat-drops of blood for mine.<br/>',NULL,43766,3);
INSERT INTO stanza VALUES('T10019','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me.<br/>',NULL,43767,4);
INSERT INTO stanza VALUES('T10019','3','In pity angels beheld Him,<br/>And came from the world of light<br/>To strengthen Him in the sorrows<br/>He bore for my soul that night.<br/>',NULL,43768,5);
INSERT INTO stanza VALUES('T10019','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me.<br/>',NULL,43769,6);
INSERT INTO stanza VALUES('T10019','4','He took my sins and sorrows,<br/>He made them His very own;<br/>He bore the burden to Calv''ry,<br/>And suffered, and died alone.<br/>',NULL,43770,7);
INSERT INTO stanza VALUES('T10019','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me.<br/>',NULL,43771,8);
INSERT INTO stanza VALUES('T10019','5','When with the ransomed in glory<br/>His face at last I shall see,<br/>''Twill be my joy through the ages<br/>To sing of His love for me.<br/>',NULL,43772,9);
INSERT INTO stanza VALUES('T10019','chorus','How marvelous! How wonderful!<br/>And my song shall ever be:<br/>How marvelous! How wonderful!<br/>Is my Savior''s love for me.<br/>',NULL,43773,10);
INSERT INTO stanza VALUES('T10020','1','My heart has such great joy,<br/>That makes me sing all day;<br/>I have a peace within,<br/>I''m free from every care.<br/>I''m deeply satisfied,<br/>Surpassing earthly things;<br/>For I have Jesus Christ<br/>In my heart as my Lord.<br/>',NULL,43774,1);
INSERT INTO stanza VALUES('T10020','chorus','O, Jesus Lord,<br/>My loving Savior, Friend,<br/>From heav''n to earth He came<br/>To give His life for me.<br/>His blood has washed my sins,<br/>I''ve God''s eternal life;<br/>For I have Jesus Christ<br/>In my heart as my Lord.<br/>',NULL,43775,2);
INSERT INTO stanza VALUES('T10020','2','Now sin cannot control,<br/>Nor tempt me anymore;<br/>Death has no pow''r on me,<br/>Nor hurt me with its sting.<br/>The devil can''t deceive,<br/>Nor can accuse me now;<br/>For my Lord Jesus Christ<br/>Died for me, lives for me.<br/>',NULL,43776,3);
INSERT INTO stanza VALUES('T10020','chorus','O, Jesus Lord,<br/>Victorious Savior, Friend,<br/>He died and rose again,<br/>Victorious over death;<br/>To end all pow''rs of darkness,<br/>Sin, and Satan''s rule;<br/>I will sing, and I will praise,<br/>Jesus my all in all.<br/>',NULL,43777,4);
INSERT INTO stanza VALUES('T10021','1','All my sins are gone,<br/>All because of Calvary;<br/>Life is filled with song,<br/>All because of Calvary;<br/>Christ my Savior lives,<br/>Lives from sin to set me free;<br/>Someday He''s coming,<br/>O wondrous blessed day,<br/>All, yes, all because of Calvary.<br/>',NULL,43778,1);
INSERT INTO stanza VALUES('T10021','1','Sala''y nawala<br/>Dahil sa Kalbaryo Niya.<br/>Buhay may awit<br/>Dahil sa Kalbaryo Niya!<br/>Kristo''y nabuhay,<br/>Ako ay pinalaya;<br/>Siya ay babalik,<br/>Kagila-gilalas!<br/>Lahat ay dahil sa Kalbaryo!<br/>',NULL,43779,2);
INSERT INTO stanza VALUES('T10022','1','There''s a new song in my heart!<br/>Since the Savior set me free;<br/>There''s a new song in my heart<br/>''Tis a heav''nly harmony!<br/>All my sins are washed away<br/>In the blood of Calvary;<br/>O what peace and joy,<br/>Nothing can destroy,<br/>Since the Savior set me free!<br/>',NULL,43780,1);
INSERT INTO stanza VALUES('T10022','1','Nang ako''y palayain<br/>Ng Panginoon natin;<br/>Sa puso ko may awit,<br/>Makalangit na awit!<br/>Nahugasan sala ko<br/>Sa dugo ng Kalbaryo;<br/>Payapa''t galak aking nakamit<br/>At ito''y aking awit!<br/>',NULL,43781,2);
INSERT INTO stanza VALUES('T10023','1','I am saved; Hallelujah! I belong to Him,<br/>I belong to the Lord forever;<br/>And because (Hallelujah) I belong to Him,<br/>I will praise His name forever.<br/>',NULL,43782,1);
INSERT INTO stanza VALUES('T10023','1','Ligtas na aleluya! Ako''y sa Kanya,<br/>Ako''y sa Pangino''n palagi;<br/>At dahil (Aleluya!) ako''y sa Kanya,<br/>Purihin ngalan Niya lagi!<br/>',NULL,43783,2);
INSERT INTO stanza VALUES('T10024','1','Christ for me,<br/>Yes, it''s Christ for me,<br/>He''s my Savior, my Lord and King;<br/>I''m so happy, I shout and sing;<br/>Christ for me,<br/>Yes, it''s Christ for me,<br/>Every day as I go my way,<br/>It is Christ for me.<br/>',NULL,43784,1);
INSERT INTO stanza VALUES('T10024','1','Siya''y akin<br/>Si Kristo''y akin:<br/>Tagapagligtas at Hari<br/>Ligaya ko''y di mawari!<br/>Siya''y akin<br/>Si Kristo''y akin:<br/>Sa habang buhay kong landas<br/>Si Kristo''y akin.<br/>',NULL,43785,2);
INSERT INTO stanza VALUES('T10026','1','He is Lord, He is Lord,<br/>He has risen from the dead and He is Lord!<br/>Every knee shall bow,<br/>Every tongue must confess,<br/>That Jesus Christ is Lord.<br/>',NULL,43786,1);
INSERT INTO stanza VALUES('T10026','1','Siya''y Poon, Siya''y Poon,<br/>Siya''y nabuhay sa patay at Siya''y Poon!<br/>Tuhod luluhod,<br/>Dila magpahayag,<br/>Hesu-Kristo''y Poon.<br/>',NULL,43787,2);
INSERT INTO stanza VALUES('T10027','1','In the name of Jesus, in the name of Jesus,<br/>There is a victory!<br/>In the name of Jesus, in the name of Jesus,<br/>Satan shall flee away.<br/>In the name of Jesus, Jesus,<br/>No one can stand against.<br/>In the name of Jesus,<br/>There is a victory!<br/>',NULL,43788,1);
INSERT INTO stanza VALUES('T10027','1','Sa ngalan ni Hesus, sa ngalan ni Hesus,<br/>Mayroong tagumpay<br/>Sa ngalan ni Hesus, sa ngalan ni Hesus,<br/>Satanas tatakas.<br/>Sa ngalan ni Hesus, Hesus<br/>Walang makadaig<br/>Sa ngalan ni Hesus,<br/>Mayroong tagumpay!<br/>',NULL,43789,2);
INSERT INTO stanza VALUES('T10028','1','Down with Satan, Down with Satan;<br/>Cast him down, Cast him down;<br/>He is under our feet,<br/>He is under our feet;<br/>He is through, He is through.<br/>',NULL,43790,1);
INSERT INTO stanza VALUES('T10028','2','Up with Jesus, Up with Jesus;<br/>Lord of all, Lord of all;<br/>He has won the victory,<br/>He has won the victory;<br/>He''s our King, He''s our King.<br/>',NULL,43791,2);
INSERT INTO stanza VALUES('T10028','1','''Bagsak diyablo! ''Bagsak diyablo!<br/>Ibagsak, ibagsak<br/>Nasa ilalim siya,<br/>Ng ''ting mga paa;<br/>Tapos na, tapos na.<br/>',NULL,43792,3);
INSERT INTO stanza VALUES('T10028','2','''Taas Hesus! ''Taas Hesus!<br/>Pangino''n ng lahat<br/>Tagumpay nakamit Niya,<br/>Tagumpay nakamit Niya,<br/>Siya''y Hari, Siya''y Hari.<br/>',NULL,43793,4);
INSERT INTO stanza VALUES('T10029','1','O victory in Jesus, my Savior forever,<br/>He sought me and bought me with His redeeming blood;<br/>He loved me ere I knew Him, and all my love is due Him,<br/>He plunged me to victory beneath the cleansing flood.<br/>',NULL,43794,1);
INSERT INTO stanza VALUES('T10029','2','O tagumpay kay Hesus, Tagapagligtas ko,<br/>Binili Niya ako ng mahal Niyang dugo;<br/>Mahal Niya ako kaya inibig ko rin Siya,<br/>Binunsod sa tagumpay sa lo''b ng dugo Niya.<br/>',NULL,43795,2);
INSERT INTO stanza VALUES('T10030','1','On the vic''try side, on the vic''try side!<br/>No foe can daunt me, no fear can haunt me<br/>On the vic''try side;<br/>On the vic''try side, on the vic''try side!<br/>With Christ within, the fight we''ll win,<br/>On the vic''try side!<br/>',NULL,43796,1);
INSERT INTO stanza VALUES('T10031','beginning-note','Revelation 12, 18-21<br/>',NULL,43797,1);
INSERT INTO stanza VALUES('T10031','1','Lo, the kingdom of the world is now the kingdom of the Lord!<br/>O what joy to all the saints does His eternal reign afford!<br/>Let us swell the mighty chorus of His praise in one accord—<br/>The victory is won!<br/>',NULL,43798,2);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43799,3);
INSERT INTO stanza VALUES('T10031','2','That great dragon, the old serpent called the devil, down is cast;<br/>Satan and his fallen angels'' long deceiving days are past!<br/>Now our praise like a thunder through the universe shall blast—<br/>The victory is won!<br/>',NULL,43800,4);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43801,5);
INSERT INTO stanza VALUES('T10031','3','Now is come salvation, power, and the kingdom of our God;<br/>The accuser of the brethren underneath our feet is trod!<br/>The authority of Christ is now the Church''s ruling rod—<br/>The victory is won!<br/>',NULL,43802,6);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43803,7);
INSERT INTO stanza VALUES('T10031','4','By the Lamb''s redeeming blood th'' accuser we have overcome;<br/>By our word of testimony, all declaring, "It is done!"<br/>Unto death, our souls not loving — all the glory to the Son!<br/>The victory is won!<br/>',NULL,43804,8);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43805,9);
INSERT INTO stanza VALUES('T10031','5','Oh, but brothers, sisters, listen to another mighty voice,<br/>"Babylon is fallen, fallen" — what a reason to rejoice!<br/>O how blest that coming out from her was our eternal choice—<br/>The victory is won!<br/>',NULL,43806,10);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43807,11);
INSERT INTO stanza VALUES('T10031','6','She''s the mother of the harlots, Myst''ry, Babylon the Great!<br/>O how all her evil fornication we have learned to hate!<br/>But our God has doubly judged her — this our spirits doth elate.<br/>The victory is won!<br/>',NULL,43808,12);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43809,13);
INSERT INTO stanza VALUES('T10031','7','Hallelujah! Glory, power to the Lord our God belong!<br/>True and righteous are His judgments on the harlot for her wrong!<br/>See, her smoke is rising! Echo hallelujah in your song—<br/>The victory is won!<br/>',NULL,43810,14);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43811,15);
INSERT INTO stanza VALUES('T10031','8','"Praise our God now, all ye servants, small and great," His voice constrains.<br/>As the sound of many waters, we will thunder our refrains:<br/>Hallelujah, hallelujah, for the Lord Almighty reigns!<br/>The victory is won!<br/>',NULL,43812,16);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43813,17);
INSERT INTO stanza VALUES('T10031','9','Now rejoice and be exceeding glad! What glory is displayed!<br/>For the marriage of the Lamb, the wife all ready now is made!<br/>In fine linen, bright and pure, ''twas granted her to be arrayed—<br/>The victory is won!<br/>',NULL,43814,18);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43815,19);
INSERT INTO stanza VALUES('T10031','10','Now the devil''s in the lake of fire, for John has seen him there;<br/>Hallelujah, never more need we his provocations bear!<br/>What a triumph for the saints his judgment boldly to declare—<br/>The victory is won!<br/>',NULL,43816,20);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43817,21);
INSERT INTO stanza VALUES('T10031','11','Now behold the greatest wonder — New Jerusalem descend!<br/>She''s the building of the Triune God with man — a perfect blend!<br/>She''s the Bride, prepared, adorned for Christ — of all God''s work, the end!<br/>The victory is won!<br/>',NULL,43818,22);
INSERT INTO stanza VALUES('T10031','chorus','Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>Vic''try, vic''try, Hallelujah!<br/>The victory is won!<br/>',NULL,43819,23);
INSERT INTO stanza VALUES('T10031','12','It''s the tabernacle of our God, His dwelling place with men;<br/>In His holiness and glory He''s expressed through all of them.<br/>"It is done!" O brothers, see it! See the New Jerusalem!<br/>The victory is won!<br/>',NULL,43820,24);
INSERT INTO stanza VALUES('T10031','chorus','Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>Hallelujah, hallelujah!<br/>The victory is won!<br/>',NULL,43821,25);
INSERT INTO stanza VALUES('T10033','1','Sing His praise, the King of Glory,<br/>Let all earth His pow''r proclaim;<br/>Just and righteous are His mandates,<br/>True and holy is His name.<br/>Let all nations laud and magnify,<br/>Ev''ry tongue confess and glorify,<br/>Christ the Lord of earth, and sea, and sky forevermore.<br/>',NULL,43822,1);
INSERT INTO stanza VALUES('T10034','1','I''m so glad! Jesus is the Lord.<br/>I''m so glad! Jesus is the Lord.<br/>I''m so glad! Jesus is the Lord.<br/>Singing glory Hallelujah! Jesus is the Lord.<br/>',NULL,43823,1);
INSERT INTO stanza VALUES('T10036','1','O brothers, sisters, rise up,<br/>Sing to Him with spirit strong;<br/>Give to Him all glory, praises,<br/>For He is worthy indeed.<br/>',NULL,43824,1);
INSERT INTO stanza VALUES('T10036','chorus','O let us rejoice! O let us rejoice!<br/>Praise Him the Lord of all,<br/>Yes we now rejoice! Yes we now rejoice!<br/>Glory to Him forevermore.<br/>',NULL,43825,2);
INSERT INTO stanza VALUES('T10036','2','Our Lord has resurrected,<br/>He has risen from the dead;<br/>Seated in the heav''nly places,<br/>Far above all pow''r and might.<br/>',NULL,43826,3);
INSERT INTO stanza VALUES('T10036','chorus','O let us rejoice! O let us rejoice!<br/>Praise Him the Lord of all,<br/>Yes we now rejoice! Yes we now rejoice!<br/>Glory to Him forevermore.<br/>',NULL,43827,4);
INSERT INTO stanza VALUES('T10036','3','All things are under His feet,<br/>To the church He is the head;<br/>The church, the fullness of Him,<br/>Who filleth all in all.<br/>',NULL,43828,5);
INSERT INTO stanza VALUES('T10036','chorus','O let us rejoice! O let us rejoice!<br/>Praise Him the Lord of all,<br/>Yes we now rejoice! Yes we now rejoice!<br/>Glory to Him forevermore.<br/>',NULL,43829,6);
INSERT INTO stanza VALUES('T10036','4','Jesus, the name of all names,<br/>Every knee to Him shall bow;<br/>Every tongue His name must confess,<br/>Glory to God the Father.<br/>',NULL,43830,7);
INSERT INTO stanza VALUES('T10036','chorus','O, Hallelujah! O, Hallelujah!<br/>Sing praise, sing praise unto Him;<br/>O, Hallelujah! O, Hallelujah!<br/>The King of kings, the Lord of lords.<br/>',NULL,43831,8);
INSERT INTO stanza VALUES('T10036','1','Mga kapatid tumindig,<br/>Sa ''spiritu''y kumanta;<br/>Purihin at l''walhatiin,<br/>Na karapat-dapat Siya!<br/>',NULL,43832,9);
INSERT INTO stanza VALUES('T10036','chorus','Tayo''y magsaya! Tayo''y magsaya!<br/>Purihin natin Siya,<br/>Oo tayo ngayo''y nagagalak!<br/>Gloria sa Kanya kailanman.<br/>',NULL,43833,10);
INSERT INTO stanza VALUES('T10036','2','Panginoon nabuhay na<br/>Mula sa kamatayan,<br/>Sa langit ay nakaluklok<br/>Nasa ''babaw ng tanan.<br/>',NULL,43834,11);
INSERT INTO stanza VALUES('T10036','chorus','Tayo''y magsaya! Tayo''y magsaya!<br/>Purihin natin Siya,<br/>Oo tayo ngayo''y nagagalak!<br/>Gloria sa Kanya kailanman.<br/>',NULL,43835,12);
INSERT INTO stanza VALUES('T10036','3','Sa paanan Niya ang lahat,<br/>Siya''y Ulo ng ekklesia;<br/>Na siyang Kanyang kapuspusan,<br/>Lahat pinupuno Niya.<br/>',NULL,43836,13);
INSERT INTO stanza VALUES('T10036','chorus','Tayo''y magsaya! Tayo''y magsaya!<br/>Purihin natin Siya,<br/>Oo tayo ngayo''y nagagalak!<br/>Gloria sa Kanya kailanman.<br/>',NULL,43837,14);
INSERT INTO stanza VALUES('T10036','4','Hesus, sa lahat ng ngalan,<br/>Lahat, Siya''y luluhuran,<br/>Magpahayag bawa''t dila,<br/>L''walhati sa Diyos Ama.<br/>',NULL,43838,15);
INSERT INTO stanza VALUES('T10036','chorus','O Aleluya! O Aleluya!<br/>Panginoon ng lahat,<br/>O Aleluya! O Aleluya!<br/>Ang Hari ng mga hari.<br/>',NULL,43839,16);
INSERT INTO stanza VALUES('T10039','1','Everybody sing praises to the Lord!<br/>Everybody sing praises to the Lord!<br/>I once was dead, but now I live,<br/>Real life to me the Spirit gives;<br/>Everybody sing praises to the Lord!<br/>',NULL,43840,1);
INSERT INTO stanza VALUES('T10039','2','Everybody sing praises to the Lord!<br/>Everybody sing praises to the Lord!<br/>I once was blind, but now I see,<br/>The Lamb of God with the dove;<br/>Everybody sing praises to the Lord!<br/>',NULL,43841,2);
INSERT INTO stanza VALUES('T10039','3','Everybody sing praises to the Lord!<br/>Everybody sing praises to the Lord!<br/>I once was dumb, but now I call,<br/>"O Lord Jesus, praise the Lord!"<br/>Everybody sing praises to the Lord!<br/>',NULL,43842,3);
INSERT INTO stanza VALUES('T10039','4','Everybody sing praises to the Lord!<br/>Everybody sing praises to the Lord!<br/>I once was deaf, but now I hear,<br/>The Spirit speaking in the church;<br/>Everybody sing praises to the Lord!<br/>',NULL,43843,4);
INSERT INTO stanza VALUES('T10041','1','It''s my Lord, Lord, Lord<br/>That makes me want to shout,<br/>Hallelujah!..... Praise the Lord!.....<br/>(Hallelujah!) (Praise the Lord!)<br/>It''s my Lord, Lord, Lord<br/>That makes me want to shout,<br/>Hallelujah! Praise the Lord.<br/>My eyes..... are clear.....<br/>(My eyes are clear..... now I can see)<br/>Now I..... can see.....<br/>(For I have Jesus Christ in me!)<br/>For I..... have..... Jesus Christ in me!<br/>(A..... men!)<br/>',NULL,43844,1);
INSERT INTO stanza VALUES('T10041','2','It''s the life, life, life<br/>that makes us want to shout,<br/>Hallelujah! Praise the Lord!<br/>It''s the life, life, life<br/>That makes us want to shout,<br/>Hallelujah! Praise the Lord!<br/>We''re full of joy! How glorious<br/>That we have Jesus Christ in us!<br/>',NULL,43845,2);
INSERT INTO stanza VALUES('T10041','1','Ang Panginoon<br/>Ang Siyang nagpasigaw,<br/>Aleluya!..... Purihin!.....<br/>(Aleluya!) (Purihin!)<br/>Ang Panginoon<br/>Ang Siyang nagpasigaw,<br/>Aleluya! Purihin!<br/>Pani..... ngin ko.....<br/>(Paningin ko lumiwanag)<br/>Lumi..... wanag.....<br/>(Pagka''t ako''y may Kristo na!)<br/>Pagka''t..... a..... ko''y may Kristo na!<br/>(A.....men!)<br/>',NULL,43846,3);
INSERT INTO stanza VALUES('T10041','2','Ang buhay, buhay,<br/>Ang siyang nagpasigaw,<br/>Aleluya! Purihin!<br/>Ang buhay, buhay,<br/>Ang siyang nagpasigaw<br/>Aleluya! Purihin!<br/>Puno ng galak, l''walhati<br/>Pagka''t Kristo''y nasa ''tin na!<br/>',NULL,43847,4);
INSERT INTO stanza VALUES('T10042','1','I''m gonna praise God unceasingly<br/>Because He lives in me,<br/>He''s everything to me,<br/>Gives life continually.<br/>I''m gonna praise God unceasingly<br/>Because He lives in me,<br/>And He will never leave.<br/>',NULL,43848,1);
INSERT INTO stanza VALUES('T10042','chorus','Now in our spirit we can feed,<br/>Jesus Christ is all we need,<br/>Call His name and He becomes reality.<br/>Open up your mouth and you will see,<br/>Just how rich our Lord can be.<br/>He''s the very life supply, complete is He.<br/>',NULL,43849,2);
INSERT INTO stanza VALUES('T10042','2','Now I live by the tree of life,<br/>His fruit does nourish me,<br/>O how it strengthens me,<br/>I''ll live eternally.<br/>Now I live by the tree of life,<br/>Him daily I apply,<br/>He is my food supply.<br/>',NULL,43850,3);
INSERT INTO stanza VALUES('T10042','chorus','Now in our spirit we can feed,<br/>Jesus Christ is all we need,<br/>Call His name and He becomes reality.<br/>Open up your mouth and you will see,<br/>Just how rich our Lord can be.<br/>He''s the very life supply, complete is He.<br/>',NULL,43851,4);
INSERT INTO stanza VALUES('T10042','3','There''s the river of life in me,<br/>Flowing so livingly,<br/>Moving continually,<br/>He just keeps flooding me.<br/>There''s a river of life in me,<br/>He''s always filling me,<br/>His name is Jesus Christ!<br/>',NULL,43852,5);
INSERT INTO stanza VALUES('T10042','chorus','Now in our spirit we can feed,<br/>Jesus Christ is all we need,<br/>Call His name and He becomes reality.<br/>Open up your mouth and you will see,<br/>Just how rich our Lord can be.<br/>He''s the very life supply, complete is He.<br/>',NULL,43853,6);
INSERT INTO stanza VALUES('T10042','1','Walang patid ang Diyos purihin<br/>''Pagkat buhay sa ''kin,<br/>Siyang lahat-lahat ko,<br/>Tustos ng buhay ko.<br/>Walang patid ang Diyos purihin<br/>''Pagkat buhay sa ''kin,<br/>Laging kasama rin!<br/>',NULL,43854,7);
INSERT INTO stanza VALUES('T10042','chorus','Bilang lahat sa ''spiritu,<br/>Kristo''y aking tamasa,<br/>Tawagin ngalan Niya''t realidad na.<br/>Buksan I-yong bibig, tikman<br/>Kung gaano kayaman Siya.<br/>Tustos sa ''king buhay,<br/>Kamangha-mangha!<br/>',NULL,43855,8);
INSERT INTO stanza VALUES('T10042','2','Ngayon ako''y nabubuhay,<br/>Sa puno ng buhay;<br/>Ako''y napalakas,<br/>Buhay walang wakas.<br/>Ngayon ako''y nabubuhay,<br/>Sa puno ng buhay,<br/>Pagkain kong tunay!<br/>',NULL,43856,9);
INSERT INTO stanza VALUES('T10042','chorus','Bilang lahat sa ''spiritu,<br/>Kristo''y aking tamasa,<br/>Tawagin ngalan Niya''t realidad na.<br/>Buksan I-yong bibig, tikman<br/>Kung gaano kayaman Siya.<br/>Tustos sa ''king buhay,<br/>Kamangha-mangha!<br/>',NULL,43857,10);
INSERT INTO stanza VALUES('T10042','3','May ilog ng buhay sa ''kin,<br/>Buhay ang agos din,<br/>Tuloy ang pag-agos,<br/>Ako''y pinupuspos.<br/>May ilog ng buhay sa ''kin,<br/>Buhay ang agos din,<br/>Hesus siyang tawagin!<br/>',NULL,43858,11);
INSERT INTO stanza VALUES('T10042','chorus','Bilang lahat sa ''spiritu,<br/>Kristo''y aking tamasa,<br/>Tawagin ngalan Niya''t realidad na.<br/>Buksan I-yong bibig, tikman<br/>Kung gaano kayaman Siya.<br/>Tustos sa ''king buhay,<br/>Kamangha-mangha!<br/>',NULL,43859,12);
INSERT INTO stanza VALUES('T10043','1','And that''s enough to make me sing.<br/>And that''s enough to make me sing.<br/>Free from self and the world,<br/>Now I have Christ as my all,<br/>And that''s enough to make me sing.<br/>',NULL,43860,1);
INSERT INTO stanza VALUES('T10045','1','Joy, joy, joy in my heart is ringing;<br/>Joy, joy, joy, Jesus sets me singing;<br/>Singing of His mighty love for me,<br/>Telling how He died to set me free,<br/>Filling all my life with melody,<br/>Singing joy, joy, joy.<br/>',NULL,43861,1);
INSERT INTO stanza VALUES('T10045','2','Christ, Christ, Christ in my spirit''s flowing;<br/>Christ, Christ, Christ in my soul is growing,<br/>Burning all the oldness out of me,<br/>Filling and transforming utterly,<br/>Bringing me to full maturity,<br/>Calling, "Lord, Lord, Lord."<br/>',NULL,43862,2);
INSERT INTO stanza VALUES('T10045','3','Praise, praise, praise, expressing God''s desire;<br/>Praise, praise, praise stirs our spirits'' fire,<br/>Filling all our hearts to overflow,<br/>Telling of His purpose as we go,<br/>Bringing all the wanderers to His flow,<br/>Singing praise, praise, praise.<br/>',NULL,43863,3);
INSERT INTO stanza VALUES('T10045','4','Church, church, church — one in every city;<br/>Church, church, church — divisions what a pity!<br/>Babylon the Great is falling down;<br/>Jerusalem is where the Lord is crowned;<br/>Brothers won''t you meet on the local ground,<br/>Building church, church, church.<br/>',NULL,43864,4);
INSERT INTO stanza VALUES('T10045','5','Local church, Praise the Lord we''ve seen it,<br/>Local church, Praise the Lord we''re in it;<br/>Lighted city set upon a hill—<br/>Christ and the Church — God''s only will;<br/>And this plan He will fulfill<br/>In the local church.<br/>',NULL,43865,5);
INSERT INTO stanza VALUES('T10045','1','Kagalakan sa aking puso,<br/>Ang nagpaawit ay si Hesus,<br/>Awitin pag-ibig Niya,<br/>Ako''y pinalaya Niya,<br/>Pinuno ang buhay ko<br/>Ng kagalakan.<br/>',NULL,43866,6);
INSERT INTO stanza VALUES('T10045','2','Si Kristo, sa espiritu ko<br/>Umaapaw at lumalago,<br/>Kalumaa''y sunugin,<br/>Pagbabago''y lubusin,<br/>Puspusin ang buhay ko,<br/>O Panginoon.<br/>',NULL,43867,7);
INSERT INTO stanza VALUES('T10045','3','Papuri hayag nais ng Diyos;<br/>Magpuri, iinit ''spiritu,<br/>Mag-umapaw sa ating puso,<br/>Ang paghahayag ng layon Niya,<br/>Sa daloy Niya gala''y dadalhin,<br/>Puri''y awitin.<br/>',NULL,43868,8);
INSERT INTO stanza VALUES('T10045','4','Ekklesia nasa bawa''t lunsod,<br/>Dibisyon di-kalugud-lugod,<br/>Babilonia''y bagsak na;<br/>Hesus ang Panginoon,<br/>Na nasa Herusalem,<br/>O Aleluya!<br/>',NULL,43869,9);
INSERT INTO stanza VALUES('T10045','5','Purihin, ang ekklesiang lokal,<br/>Nakita at nasa loob Niya;<br/>Si Kristo at ekklesia<br/>Tanging loobin ng Diyos,<br/>Layunin tutuparin<br/>Sa ekklesiang lokal.<br/>',NULL,43870,10);
INSERT INTO stanza VALUES('T10046','1','Happy, happy, happy,<br/>Happy in the Lord,<br/>I''m glad I''m a Christian,<br/>I''m enjoying the Lord;<br/>I want you to know,<br/>How happy am I!<br/>And so I''m happy, happy,<br/>Happy in the Lord.<br/>',NULL,43871,1);
INSERT INTO stanza VALUES('T10046','2','Calling O Lord Jesus,<br/>Calling on the Lord,<br/>I''m glad I''m a Christian,<br/>I''m enjoying the Lord;<br/>I want you to know,<br/>I''m calling the Lord;<br/>By calling O Lord Jesus,<br/>O He sets me free!<br/>',NULL,43872,2);
INSERT INTO stanza VALUES('T10047','1','We want ev''rybody to be happy,<br/>We want ev''rybody to be glad:<br/>We want ev''rybody to be happy in the Lord.<br/>And we don''t want anybody sad.<br/>',NULL,43873,1);
INSERT INTO stanza VALUES('T10048','1','Glory to God, glory. . .<br/>O praise Him, hallelujah!<br/>Glory to God, glory. . .<br/>O praise the name of the Lord.<br/>Praise the Son of the living God.<br/>',NULL,43874,1);
INSERT INTO stanza VALUES('T10051','1','My heart was distressed beneath the Lord''s dread frown,<br/>And low in the pit where my sins dragged me down;<br/>I cried to the Lord from the deep miry clay,<br/>Who tenderly brought me out to golden day.<br/>',NULL,43875,1);
INSERT INTO stanza VALUES('T10051','chorus','He brought me out of the miry clay,<br/>He set my feet on the Rock to stay;<br/>He puts a song in my soul today,<br/>A song of praise, Hallelujah!<br/>',NULL,43876,2);
INSERT INTO stanza VALUES('T10051','2','He placed me upon the strong Rock by His side,<br/>My steps were established and here I''ll abide;<br/>No danger of falling while here I remain,<br/>But stand by His grace until the crown I gain.<br/>',NULL,43877,3);
INSERT INTO stanza VALUES('T10051','chorus','He brought me out of the miry clay,<br/>He set my feet on the Rock to stay;<br/>He puts a song in my soul today,<br/>A song of praise, Hallelujah!<br/>',NULL,43878,4);
INSERT INTO stanza VALUES('T10102','1','The age has turned,<br/>Our Lord the age has turned,<br/>The age has turned,<br/>Our Lord the age has turned,<br/>From outward letters, doctrines,<br/>forms to spirit has turned.<br/>Oh, our Lord has turned, has turned,<br/>has turned the age!<br/>Oh, turn brothers! Oh, turn sisters!<br/>Turn the age, with the Lord!<br/>(Glory! Hallelujah!)<br/>Turn into the spirit,<br/>make a thorough turning,<br/>Oh, turn, with the Lord, turn.<br/>',NULL,43879,1);
INSERT INTO stanza VALUES('T10102','2','Move with the Lord!<br/>Move forward with the Lord!<br/>Move with the Lord!<br/>Move forward with the Lord!<br/>Into the spirit we will turn<br/>and move with the Lord.<br/>We''ll move forward, forward,<br/>forward with the Lord.<br/>Forward, brothers! Forward, sisters!<br/>Move forward with the Lord<br/>(Glory! Hallelujah!)<br/>Into glory with Him,<br/>in the spirit we''ll move,<br/>Ever moving forward!<br/>',NULL,43880,2);
INSERT INTO stanza VALUES('T10105','1','Th'' anointing''s here! The Lord is moving now in us;<br/>The ointment dear to us has been applied.<br/>His blood prevails! It gives to us the fellowship,<br/>And now we have the living flow of life.<br/>',NULL,43881,1);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian brothers,<br/>Th'' anointing''s here! We have believed.<br/>Within our spirit, the Spirit''s moving,<br/>And this from Him we have received.<br/>',NULL,43882,2);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian sisters,<br/>The flow within will never cease.<br/>As He anoints us, we are abiding—<br/>O Hallelujah! Life and peace!<br/>',NULL,43883,3);
INSERT INTO stanza VALUES('T10105','2','Th'' anointing''s here! ''Tis God Himself that blends with us,<br/>And now the two are mingled into one.<br/>And hour by hour we live, and move, and have our life<br/>In God Himself — the Spirit through the Son.<br/>',NULL,43884,4);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian brothers,<br/>Th'' anointing''s here! We have believed.<br/>Within our spirit, the Spirit''s moving,<br/>And this from Him we have received.<br/>',NULL,43885,5);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian sisters,<br/>The flow within will never cease.<br/>As He anoints us, we are abiding—<br/>O Hallelujah! Life and peace!<br/>',NULL,43886,6);
INSERT INTO stanza VALUES('T10105','3','Th'' anointing''s here! It teaches us in everything;<br/>The sense of life we always have within.<br/>Obey this sense, and you will know what you must do,<br/>And live by Life — Yes, clear in everything.<br/>',NULL,43887,7);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian brothers,<br/>Th'' anointing''s here! We have believed.<br/>Within our spirit, the Spirit''s moving,<br/>And this from Him we have received.<br/>',NULL,43888,8);
INSERT INTO stanza VALUES('T10105','chorus','Th'' anointing''s here! O Christian sisters,<br/>The flow within will never cease.<br/>As He anoints us, we are abiding—<br/>O Hallelujah! Life and peace!<br/>',NULL,43889,9);
INSERT INTO stanza VALUES('T10106','1','In the Word of God I found it,<br/>Wonderful this Word to me;<br/>I need not man''s natural teaching,<br/>The anointing lives in me!<br/>',NULL,43890,1);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43891,2);
INSERT INTO stanza VALUES('T10106','2','Making Christ experiential,<br/>God at His pure Word I take;<br/>As the Spirit joined unto me,<br/>He cannot His promise break.<br/>',NULL,43892,3);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43893,4);
INSERT INTO stanza VALUES('T10106','3','Based upon the blood that cleanses<br/>So that nothing stands between,<br/>Christ, the ointment, moves within me!<br/>For His move I''m made so clean.<br/>',NULL,43894,5);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43895,6);
INSERT INTO stanza VALUES('T10106','4','God in Christ as life in Spirit<br/>Into my own spirit came!<br/>He the Holy One anoints me<br/>Till in spirit we''re the same.<br/>',NULL,43896,7);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43897,8);
INSERT INTO stanza VALUES('T10106','5','God in Spirit; I can touch Him;<br/>In my spirit He''s the flow.<br/>Deeper, wider, richer, fuller—<br/>Oh, the very God I know!<br/>',NULL,43898,9);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43899,10);
INSERT INTO stanza VALUES('T10106','6','As I heed "that same anointing"<br/>Ever to "abide in Him,"<br/>He is teaching, He is reaching,<br/>Even all my heart to win.<br/>',NULL,43900,11);
INSERT INTO stanza VALUES('T10106','chorus','Yes, in my spirit now He is moving!<br/>Yes, I have the anointing!<br/>God in me is flowing!<br/>Thank God I see it!<br/>His Word revealed it!<br/>I will apply it ever!<br/>The anointing lives in me!<br/>',NULL,43901,12);
INSERT INTO stanza VALUES('T10107','1','By the anointing, Jesus breaks the yoke;<br/>Inscribes His laws upon our hearts,<br/>Just as the prophets spoke.<br/>This is the Lord''s new covenant,<br/>God is working inside of men,<br/>And the anointing shall break the yoke.<br/>',NULL,43902,1);
INSERT INTO stanza VALUES('T10107','2','By the anointing, Jesus breaks the yoke;<br/>Inscribes His laws upon our hearts,<br/>Just as the prophets spoke.<br/>This is the Lord''s new covenant,<br/>Christ is living inside of men,<br/>And the anointing shall break the yoke.<br/>',NULL,43903,2);
INSERT INTO stanza VALUES('T10107','3','By the anointing, Jesus breaks the yoke;<br/>Inscribes His laws upon our hearts,<br/>Just as the prophets spoke.<br/>This is the Lord''s new covenant,<br/>The Spirit''s moving inside of men,<br/>And the anointing shall break the yoke.<br/>',NULL,43904,3);
INSERT INTO stanza VALUES('T10108','1','From my spirit, when I''m sensing the supply<br/>Of God''s speaking, from a fount that ne''er runs dry,<br/>And within me comes a fresh and sweet supply,<br/>Then I''ve got to open up and water you.<br/>',NULL,43905,1);
INSERT INTO stanza VALUES('T10108','chorus','Water you, water you<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I''ll surely testify,<br/>I''ll stand up, release my Christ and water you!<br/>',NULL,43906,2);
INSERT INTO stanza VALUES('T10108','2','In the meeting, when my spirit''s rising high,<br/>And it seems like we will go beyond the sky—<br/>I can''t help it, I must speak or else I''ll die,<br/>For my Christ is rising up to water you.<br/>',NULL,43907,3);
INSERT INTO stanza VALUES('T10108','chorus','Water you, water you<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I''ll surely testify,<br/>I''ll stand up, release my Christ and water you!<br/>',NULL,43908,4);
INSERT INTO stanza VALUES('T10108','3','Should a pause come, or the meeting ebb real low,<br/>While within me there''s a rich and living flow,<br/>Then I''ll stand up, so that all the saints will know,<br/>That I''m here to share my Christ and water you.<br/>',NULL,43909,5);
INSERT INTO stanza VALUES('T10108','chorus','Water you, water you<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I''ll surely testify,<br/>I''ll stand up, release my Christ and water you!<br/>',NULL,43910,6);
INSERT INTO stanza VALUES('T10108','4','In the church life, in our daily living too,<br/>In the meeting, and in everything we do,<br/>Christ is speaking and the Spirit''s breaking through,<br/>That is why there''s the supply to water you.<br/>',NULL,43911,7);
INSERT INTO stanza VALUES('T10108','chorus','Water you, water you<br/>From the flowing in my spirit water you;<br/>When the saints need my supply,<br/>Then I''ll surely testify,<br/>I''ll stand up, release my Christ and water you!<br/>',NULL,43912,8);
INSERT INTO stanza VALUES('T10109','1','Burn, oh burn, oh burn, Lord,<br/>Our spirits burn!<br/>Burning spirit all we need,<br/>Oh to Thee our hands we lift,<br/>Oh, burn us, Lord.<br/>',NULL,43913,1);
INSERT INTO stanza VALUES('T10109','2','Burn, oh burn, oh burn, Lord,<br/>Our spirits burn!<br/>For the Lord''s recovery,<br/>Burning spirit all we need.<br/>Oh, burn us, Lord.<br/>',NULL,43914,2);
INSERT INTO stanza VALUES('T10109','3','Burn, oh burn, oh burn, Lord,<br/>Our spirits burn!<br/>Burn until our spirit glows,<br/>And the Lord through us may flow,<br/>Oh, burn us, Lord.<br/>',NULL,43915,3);
INSERT INTO stanza VALUES('T10110','1','Fire up! Fire up! Brothers, fire up!<br/>Keep the fire burning in your spirits, fire up.<br/>Fire up! Fire up! Sisters, fire up!<br/>Keep the fire burning in your spirits, fire up.<br/>',NULL,43916,1);
INSERT INTO stanza VALUES('T10111','beginning-note','2 Timothy 1:7<br/>',NULL,43917,1);
INSERT INTO stanza VALUES('T10111','1','God has not giv''n us a spirit of fear—<br/>There''s pow''r deep within, pow''r deep within!<br/>We have His Word — brothers, sisters, let''s hear—<br/>That pow''r deep within may flow out.<br/>',NULL,43918,2);
INSERT INTO stanza VALUES('T10111','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r,<br/>In the spirit God''s given us!<br/>',NULL,43919,3);
INSERT INTO stanza VALUES('T10111','2','God has not giv''n us a wavering will—<br/>There''s pow''r deep within, pow''r deep within!<br/>But one our spirit will strengthen and fill—<br/>There''s wonderful pow''r deep within!<br/>',NULL,43920,4);
INSERT INTO stanza VALUES('T10111','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r,<br/>In the spirit God''s given us!<br/>',NULL,43921,5);
INSERT INTO stanza VALUES('T10111','3','God has not giv''n us emotions so weak—<br/>There''s pow''r deep within, pow''r deep within!<br/>Open our hearts and in love let us speak—<br/>There''s wonderful pow''r deep within!<br/>',NULL,43922,6);
INSERT INTO stanza VALUES('T10111','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r,<br/>In the spirit God''s given us!<br/>',NULL,43923,7);
INSERT INTO stanza VALUES('T10111','4','God has not giv''n us a mind that is bound—<br/>There''s pow''r deep within, pow''r deep within!<br/>But one that''s healthy and perfectly sound—<br/>There''s wonderful pow''r deep within!<br/>',NULL,43924,8);
INSERT INTO stanza VALUES('T10111','chorus','O there''s pow''r, pow''r, overcoming pow''r,<br/>Deep within, deep within;<br/>O there''s pow''r, pow''r, normal Christian pow''r,<br/>In the spirit God''s given us!<br/>',NULL,43925,9);
INSERT INTO stanza VALUES('T10112','1','Bury that old time religion,<br/>Bury that old time religion,<br/>Bury that old time religion,<br/>We''ve had enough of it.<br/>',NULL,43926,1);
INSERT INTO stanza VALUES('T10112','2','Give us newness in the spirit,<br/>Give us newness in the spirit,<br/>Give us newness in the spirit,<br/>It''s our reality.<br/>',NULL,43927,2);
INSERT INTO stanza VALUES('T10113','1','We are freed from the system,<br/>Praise the Lord! (Praise the Lord!)<br/>We are freed from religion,<br/>Praise the Lord! (Praise the Lord!)<br/>We are freed from the system,<br/>We are freed from religion,<br/>We are freed in our spirit,<br/>Praise the Lord!<br/>',NULL,43928,1);
INSERT INTO stanza VALUES('T10113','2','We are freed in our spirit,<br/>By His Life; (By His Life)<br/>We are freed in our spirit,<br/>By His Life; (By His Life)<br/>We are freed in our spirit,<br/>We are freed in our spirit,<br/>We are freed in our spirit,<br/>By His Life!<br/>',NULL,43929,2);
INSERT INTO stanza VALUES('T10113','1','Malaya sa sistema,<br/>Malaya! (Malaya!)<br/>Malaya sa relihiyon,<br/>Malaya! (Malaya!)<br/>Malaya sa sistema,<br/>Malaya sa relihiyon,<br/>Malaya sa ''spiritu,<br/>O Amen!<br/>',NULL,43930,3);
INSERT INTO stanza VALUES('T10113','2','Dahil sa Kanyang buhay,<br/>Malaya! (Malaya!)<br/>Dahil sa Kanyang buhay,<br/>Malaya! (Malaya!)<br/>Tamasa''y kalayaan,<br/>Tamasa''y kaligtasan,<br/>Malaya sa ''spiritu,<br/>O Amen!<br/>',NULL,43931,4);
INSERT INTO stanza VALUES('T10114','1','In spirit, we feast on the Lord<br/>Eat and drink Him — His sweetness untold!<br/>His richness is our reality,<br/>Rest and fullness unceasingly.<br/>In spirit, in spirit,<br/>In spirit we feast on the Lord<br/>In spirit, in spirit, in spirit,<br/>In spirit we enjoy our Lord.<br/>',NULL,43932,1);
INSERT INTO stanza VALUES('T10114','2','Sa ''spiritu''y tamasahin,<br/>Tamis Niya''y kainin, inumin.<br/>Katotohanan ko''ng yaman Niya,<br/>Pahinga''t kabusugan pa.<br/>O, sa espiritu,<br/>Magpista sa ating Kristo!<br/>O, sa espiritu,<br/>Magpista''t tamasahin ating Kristo!<br/>',NULL,43933,2);
INSERT INTO stanza VALUES('T10115','1','Turn to your spirit, where the Spirit of Jesus is,<br/>Turn to your spirit — Oh, how it makes you sing!<br/>Turn to your spirit in the middle of everything.<br/>Turn to the Lord, oh, turn to the Lord!<br/>',NULL,43934,1);
INSERT INTO stanza VALUES('T10115','2','Turn to your spirit, where the Spirit of Jesus is,<br/>Turn to your spirit — where life is really found,<br/>Turn to your spirit if you''re up or if you''re down.<br/>Turn to the Lord, oh, turn to the Lord!<br/>',NULL,43935,2);
INSERT INTO stanza VALUES('T10115','3','Turn to your spirit, where the Spirit of Jesus is,<br/>Turn to your spirit, calling upon His name—<br/>Now and forever, Jesus is the very same.<br/>Turn to the Lord, oh, turn to the Lord!<br/>',NULL,43936,3);
INSERT INTO stanza VALUES('T10115','1','Sa espiritu, kay Hesus, bumaling ka;<br/>Sa espiritu, tustos iyong makuha<br/>Sa espiritu, tawagin ang ngalan Niya,<br/>Sa espiritu, mamuhay ka!<br/>',NULL,43937,4);
INSERT INTO stanza VALUES('T10115','2','Sa espiritu, magsipagsalamuha.<br/>Sa espiritu, makakaawit ka.<br/>Sa espiritu, lahat ma''wawasto nga,<br/>Sa espiritu, mamuhay ka!<br/>',NULL,43938,5);
INSERT INTO stanza VALUES('T10115','3','Sa espiritu, kay Kristo bumaling ka<br/>Sa espiritu, taas ma''t mababa<br/>Sa espiritu, ngayo''t magpakailanman<br/>Panginoon ay maasahan!<br/>',NULL,43939,6);
INSERT INTO stanza VALUES('T10117','1','Have you found your human spirit?<br/>It''s connected to your mouth!<br/>"Hallelujah — O Lord Jesus,"<br/>That''s the way to let it out!<br/>',NULL,43940,1);
INSERT INTO stanza VALUES('T10117','chorus','What is born of Spirit is just our spirit,<br/>And the two spirits are one.<br/>What is born of Spirit is just our spirit,<br/>And the two spirits are one.<br/>',NULL,43941,2);
INSERT INTO stanza VALUES('T10117','2','Don''t wait for the inspiration—<br/>Don''t be trapped by Satan''s trick.<br/>Open up! Release your spirit,<br/>Testifying you''re so free.<br/>',NULL,43942,3);
INSERT INTO stanza VALUES('T10117','chorus','What is born of Spirit is just our spirit,<br/>And the two spirits are one.<br/>What is born of Spirit is just our spirit,<br/>And the two spirits are one.<br/>',NULL,43943,4);
INSERT INTO stanza VALUES('T10118','1','We have decided to walk in spirit,<br/>We have decided to walk in spirit,<br/>We have decided to walk in spirit,<br/>He lives in us, Hallelujah!<br/>',NULL,43944,1);
INSERT INTO stanza VALUES('T10118','2','To walk in spirit, call "O Lord Jesus!" (3x)<br/>He''s rich, so call: "Hallelujah!"<br/>',NULL,43945,2);
INSERT INTO stanza VALUES('T10118','3','To walk in spirit pray for your brothers, (3x)<br/>It builds the Church, Hallelujah!<br/>',NULL,43946,3);
INSERT INTO stanza VALUES('T10118','4','To follow Jesus, we need the Body, (3x)<br/>We need its Life, Hallelujah!<br/>',NULL,43947,4);
INSERT INTO stanza VALUES('T10118','5','We''ve found the purpose in local churches, (3x)<br/>In the churches, Hallelujah!<br/>',NULL,43948,5);
INSERT INTO stanza VALUES('T10118','6','It is joy to be built together, (3x)<br/>How glorious, the local church!<br/>',NULL,43949,6);
INSERT INTO stanza VALUES('T10118','1','Lalakad tayo sa espiritu, (3x)<br/>Buha''y sa ''tin, Aleluya!<br/>',NULL,43950,7);
INSERT INTO stanza VALUES('T10118','2','Ating tawagin; Pangino''ng Hesus (3x)<br/>Mayaman Siya, Aleluya!<br/>',NULL,43951,8);
INSERT INTO stanza VALUES('T10118','3','Ipanalangin mga kapatid (3x)<br/>Ekklesia''y maitatayo!<br/>',NULL,43952,9);
INSERT INTO stanza VALUES('T10118','4','Si Hesus sundan sa Katawan Niya (3x)<br/>Mahalaga ang Katawan!<br/>',NULL,43953,10);
INSERT INTO stanza VALUES('T10118','5','May layunin sa ekklesia lokal (3x)<br/>Natagpuan sa ekklesia!<br/>',NULL,43954,11);
INSERT INTO stanza VALUES('T10118','6','Sa pagtatayo, may kagalakan (3x)<br/>Pagtatayo, kay ''l''walhati!<br/>',NULL,43955,12);
INSERT INTO stanza VALUES('T10119','1','Now Christ is the life-giving Spirit,<br/>Now Christ is the Spirit today,<br/>Now Christ is the life-giving Spirit,<br/>So turn to your spirit and say:<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>',NULL,43956,1);
INSERT INTO stanza VALUES('T10119','2','Now Christ is that life-giving Spirit,<br/>That Spirit dwells within me too;<br/>Now Christ is that life-giving Spirit,<br/>Transforms me to His image true.<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>"O Lord, Amen, O Lord, Amen, Hallelujah!"<br/>',NULL,43957,2);
INSERT INTO stanza VALUES('T10119','1','Ngayon si Kristo''y Espiritu,<br/>Nagbibigay-buhay sa ''tin.<br/>Ngayon si Kristo''y Espiritu,<br/>Bumaling ka, Siya''y tawagin:<br/>Panginoong Hesus, Amen, Aleluya!<br/>Panginoong Hesus, Amen, Aleluya!<br/>',NULL,43958,3);
INSERT INTO stanza VALUES('T10119','2','Ang Kristong nagbibigay-buhay;<br/>Sa ''kin ngayo''y nananahan,<br/>Binabago Niya akong tunay,<br/>Tungo sa Kanyang larawan.<br/>Panginoong Hesus, Amen, Aleluya!<br/>Panginoong Hesus, Amen, Aleluya!<br/>',NULL,43959,4);
INSERT INTO stanza VALUES('T10120','1','I love my dear Lord Jesus,<br/>Life-giving Spirit He is;<br/>I''m mingled with Him as one,<br/>Now two spirits are one.<br/>',NULL,43960,1);
INSERT INTO stanza VALUES('T10120','2','Mahal ko aking Hesus,<br/>Nagbibigay ng buhay<br/>Kami''y nagkahalo na<br/>''Spiritu''y nagkaisa.<br/>',NULL,43961,2);
INSERT INTO stanza VALUES('T10121','1','Everybody ought to know,<br/>Everybody ought to know,<br/>Everybody ought to know,<br/>Where Jesus dwells?<br/>He is dwelling in our spirits,<br/>He is breath and life to us,<br/>We are one with Him in spirit,<br/>Everybody ought to know.<br/>',NULL,43962,1);
INSERT INTO stanza VALUES('T10121','2','Banal dapat malaman,<br/>Banal dapat malaman,<br/>Banal dapat malaman,<br/>Siya''y nasaan?<br/>Nasa ating espiritu,<br/>Bilang hininga''t buhay;<br/>Kaisa sa espiritu,<br/>Kamangha-manghang bagay.<br/>',NULL,43963,2);
INSERT INTO stanza VALUES('T10122','1','Oh, strengthen my spirit, Lord Jesus,<br/>Oh, strengthen my spirit, I pray;<br/>Oh, strengthen my spirit with power<br/>And spread to my heart today.<br/>',NULL,43964,1);
INSERT INTO stanza VALUES('T10122','chorus','Into my heart, into my heart,<br/>Spread into my heart, Lord Jesus;<br/>Make home today and have Your way<br/>In all of my heart, Lord Jesus.<br/>',NULL,43965,2);
INSERT INTO stanza VALUES('T10122','2','To Him who is able to do it<br/>Above all we think or say,<br/>We open our hearts wide and welcome<br/>Him into our heart today.<br/>',NULL,43966,3);
INSERT INTO stanza VALUES('T10122','chorus','Into my heart, into my heart,<br/>Spread into my heart, Lord Jesus;<br/>Make home today and have Your way<br/>In all of my heart, Lord Jesus.<br/>',NULL,43967,4);
INSERT INTO stanza VALUES('T10123','1','We can sense the Spirit pleading,<br/>Through God''s mercy, He''s entreating,<br/>In our heart these words repeating,<br/>"Full committal to the local church."<br/>',NULL,43968,1);
INSERT INTO stanza VALUES('T10123','2','Buried now — the old man''s stricken,<br/>Live we now in Christ arisen;<br/>Joyful spirits freed from prison<br/>Yield to Christ and to His local church.<br/>',NULL,43969,2);
INSERT INTO stanza VALUES('T10123','3','Glory fills our sight before us,<br/>With God''s power resting o''er us,<br/>And our spirit speaking for us,<br/>"Full committal to the local church."<br/>',NULL,43970,3);
INSERT INTO stanza VALUES('T10123','4','Truth should never be disputed,<br/>But all negatives uprooted;<br/>This, our cry, can''t be refuted,<br/>"Full committal to the local church."<br/>',NULL,43971,4);
INSERT INTO stanza VALUES('T10123','1','Naririnig natin ngayon,<br/>Ang Banal na Espiritu<br/>Nagsusumamo: "Lubusin<br/>Pagsuko sa ekklesia lokal."<br/>',NULL,43972,5);
INSERT INTO stanza VALUES('T10123','2','Nalibing — ang lumang tao,<br/>Buhay — sa loob ni Kristo;<br/>Espiritung napalaya—<br/>Isuko kay Kristo''t ekklesia.<br/>',NULL,43973,6);
INSERT INTO stanza VALUES('T10123','3','L''walhati ang haharapin,<br/>Sa kapangyarihan ng Diyos.<br/>Espiritung nagsasabi:<br/>"Iukol sa ekklesiang lokal."<br/>',NULL,43974,7);
INSERT INTO stanza VALUES('T10123','4','Katotohana''y di dapat<br/>Pagtalunan ka-i-lan man;<br/>Saloobi''y di mabago:<br/>"Iukol sa ekklesia lokal."<br/>',NULL,43975,8);
INSERT INTO stanza VALUES('T10124','1','Jesus our Lord is the Spirit of Life,<br/>The Spirit of Life, The Spirit of Life.<br/>Jesus our Lord is the Spirit of Life;<br/>He''s living now in us.<br/>',NULL,43976,1);
INSERT INTO stanza VALUES('T10124','2','Living, living, He''s being formed within us.<br/>Living, living, to be expressed through us;<br/>Hallelujah!<br/>',NULL,43977,2);
INSERT INTO stanza VALUES('T10124','3','Jesus our Lord is the Spirit of Life,<br/>The Spirit of Life, The Spirit of Life,<br/>Jesus our Lord is the Spirit of Life;<br/>He''s living now in us.<br/>',NULL,43978,3);
INSERT INTO stanza VALUES('T10124','4','Hesus Poon ''Spiritu ng buhay,<br/>Espiritung nagbibigay-buhay;<br/>Hesus Poon ''Spiritu ng buhay,<br/>Nabubuhay sa ''kin.<br/>',NULL,43979,4);
INSERT INTO stanza VALUES('T10124','5','Siya ay buhay! Nahuhubog sa akin.<br/>Ako''y buhay! Hinahayag ko Siya!<br/>Aleluya!<br/>',NULL,43980,5);
INSERT INTO stanza VALUES('T10124','6','Hesus Poon ''Spiritu ng buhay.<br/>Espiritung nagbibigay-buhay;<br/>Hesus Poon ''Spiritu ng buhay<br/>Nabubuhay sa ''kin.<br/>',NULL,43981,6);
INSERT INTO stanza VALUES('T10125','1','Keep me walking in the spirit, Lord I pray,<br/>Keep me walking in the spirit Lord today.<br/>For I need Thy wondrous pow''r<br/>every day and every hour,<br/>Keep me walking in the spirit Lord, today.<br/>',NULL,43982,1);
INSERT INTO stanza VALUES('T10125','2','Ingatan Mo ako sa espiritu,<br/>Nang lumakad sa espiritu ngayon.<br/>Kailangan ko''ng lakas Mo,<br/>bawa''t saglit panahon,<br/>Ingatan Mo ako sa espiritu!<br/>',NULL,43983,2);
INSERT INTO stanza VALUES('T10126','1','O Hallelujah, Christ is life<br/>As breath to be received!<br/>He breathed on them and said to them,<br/>"Receive ye now the Holy Breath."<br/>And now we breathe Him in,<br/>And now we breathe Him in,<br/>And now, and now we breathe Him in.<br/>',NULL,43984,1);
INSERT INTO stanza VALUES('T10127','1','Christ the real life-giver,<br/>Gives life to me,<br/>And every time I call on Him,<br/>His Spirit sets me free;<br/>Christ the real life-giver,<br/>Lives now in me:<br/>No longer is He just a name,<br/>But my reality!<br/>',NULL,43985,1);
INSERT INTO stanza VALUES('T10127','2','Nagbibigay-buhay,<br/>Kristo sa ''kin,<br/>''Pag tinawag kong ngalan Niya,<br/>''Ko''y napalalaya;<br/>Nananahan sa ''kin,<br/>Espiritu:<br/>''Di lamang Siya isang ngalan,<br/>Bagkus katunayan!<br/>',NULL,43986,2);
INSERT INTO stanza VALUES('T10128','1','Going onward, going onward<br/>With Christ as our Life;<br/>Overcoming all distractions,<br/>In the spirit fight! Life! Life! Life!<br/>We''re for Jesus! We''re for Jesus!<br/>Burning just for Christ;<br/>We don''t care for problems,<br/>We just care for Life!<br/>',NULL,43987,1);
INSERT INTO stanza VALUES('T10128','2','Pressing onward! Pressing onward!<br/>Dropping all for Christ!<br/>Burning all things on the altar,<br/>Be they wrong or right! Burn! Burn! Burn!<br/>Pressing forward! Pressing forward!<br/>Reaching forth for Christ;<br/>Leaving all behind us,<br/>We move on in life!<br/>',NULL,43988,2);
INSERT INTO stanza VALUES('T10132','1','I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43989,1);
INSERT INTO stanza VALUES('T10132','2','Won''t let soul-life stomp Him out.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43990,2);
INSERT INTO stanza VALUES('T10132','3','I''ll pray-read to water Him.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43991,3);
INSERT INTO stanza VALUES('T10132','4','"O Lord Jesus!" waters Him.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43992,4);
INSERT INTO stanza VALUES('T10132','5','Fellowshipping with the saints.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43993,5);
INSERT INTO stanza VALUES('T10132','6','Standing up to prophesy.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43994,6);
INSERT INTO stanza VALUES('T10132','7','Saying "Amen" when He speaks.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43995,7);
INSERT INTO stanza VALUES('T10132','8','Growing up with all the saints.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43996,8);
INSERT INTO stanza VALUES('T10132','9','Till there is a full-grown man.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43997,9);
INSERT INTO stanza VALUES('T10132','10','Till the Kingdom is fully shown.<br/>I''m gonna let Him grow.<br/>I''ve got Christ as a seed in me;<br/>I''m gonna let Him grow.<br/>Let Him grow, let Him grow, let Him grow.<br/>',NULL,43998,10);
INSERT INTO stanza VALUES('T10132','1','Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,43999,11);
INSERT INTO stanza VALUES('T10132','2','Binhi di ko papatayin.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44000,12);
INSERT INTO stanza VALUES('T10132','3','Diligan: basa''t dalangin.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44001,13);
INSERT INTO stanza VALUES('T10132','4','Mag- O Panginoong Hesus!.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44002,14);
INSERT INTO stanza VALUES('T10132','5','Magsalamuha sa banal.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44003,15);
INSERT INTO stanza VALUES('T10132','6','Tumayo''t magpropesiya.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44004,16);
INSERT INTO stanza VALUES('T10132','7','Mag- Amen, pagsalita Niya.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44005,17);
INSERT INTO stanza VALUES('T10132','8','Lumagong kasamang banal.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44006,18);
INSERT INTO stanza VALUES('T10132','9','Hanggang lumago sa buhay.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44007,19);
INSERT INTO stanza VALUES('T10132','10','Nang kaharia''y makita.<br/>Palalaguin ko.<br/>Taglay ko si Kristong binhi;<br/>Palalaguin ko.<br/>Lubusan kong palalaguin.<br/>',NULL,44008,20);
INSERT INTO stanza VALUES('T10133','1','O my God, within Thee, there is eternal life,<br/>And this life is expressed in the Son,<br/>The risen Lord today, as the Spirit of Life,<br/>Within us, quickens us, gives us life.<br/>',NULL,44009,1);
INSERT INTO stanza VALUES('T10133','2','O behold, from the throne of God and of the Lamb,<br/>Flows a river of water of life,<br/>God as the source of life, Christ, the fountain of life,<br/>Triune God as the river of life.<br/>',NULL,44010,2);
INSERT INTO stanza VALUES('T10133','3','Jesus Lord, unto Thee, my spirit open wide,<br/>Calling Thee, from within, drinking Thee,<br/>Jesus Lord, now I turn to the river of life,<br/>Triune God, saturate me as life.<br/>',NULL,44011,3);
INSERT INTO stanza VALUES('T10135','1','The kingdom is just Christ as man''s life,<br/>Imparting riches into me,<br/>In resurrection growing, moving,<br/>That Christ my New Man e''er will be.<br/>',NULL,44012,1);
INSERT INTO stanza VALUES('T10135','2','May Thy exhaustless treasure<br/>Be my supply and power,<br/>So that I daily may enjoy Your,<br/>May enjoy Your, may enjoy Your<br/>riches bountiful.<br/>',NULL,44013,2);
INSERT INTO stanza VALUES('T10135','3','Oh that Thy pow''r in glory<br/>May operate within me,<br/>Make me grow daily and transform me,<br/>And transform me, and transform me<br/>into Thine image.<br/>',NULL,44014,3);
INSERT INTO stanza VALUES('T10135','4','May the kingdom''s reality,<br/>The church life''s practicality,<br/>And the building with all the saints<br/>fulfilled be.<br/>',NULL,44015,4);
INSERT INTO stanza VALUES('T10135','5','Oh, may the kingdom''s power<br/>To heav''nly realm us transfer,<br/>And operate that we may ever,<br/>We may ever, we may ever<br/>dwell in Thy glory.<br/>',NULL,44016,5);
INSERT INTO stanza VALUES('T10135','6','Ang kaharian ay si Kristo<br/>Bilang buhay at yaman ko,<br/>Sa pagkabuhay lumalago<br/>Si Kristo, Bagong Tao ko.<br/>',NULL,44017,6);
INSERT INTO stanza VALUES('T10135','7','Nawa''y Iyong kayamanan<br/>Magtustos, magpatibay,<br/>Upang lagi kong matamasa,<br/>Matamasa, matamasa<br/>Iyong kayamanan.<br/>',NULL,44018,7);
INSERT INTO stanza VALUES('T10135','8','Lakas Mo sa l''walhati<br/>Gumagawa sa akin,<br/>Nang ako''y laging matransporma,<br/>Matransporma, matransporma<br/>Sa I-yong wangis.<br/>',NULL,44019,8);
INSERT INTO stanza VALUES('T10135','9','Kahariang katunayan,<br/>Karanasang ekklesi-a,<br/>Pagtatayo ng banal ay makita.<br/>',NULL,44020,9);
INSERT INTO stanza VALUES('T10135','10','Kaharia''y naglapit.<br/>Sa dakong makalangit,<br/>Kami''y pun''in Mo at dalhin Mo,<br/>At dalhin Mo, at dalhin Mo<br/>Sa Iyong l''walhati.<br/>',NULL,44021,10);
INSERT INTO stanza VALUES('T10136','1','Lord, cause us to see, Your heart''s desire<br/>Is Your Kingdom indeed,<br/>No need for us, to labor vainly,<br/>Thy grace, O Lord we need,<br/>In the Kingdom we''re translated,<br/>There''s no need to wait for that day;<br/>Just let the Lord grow within us,<br/>Kingdom be expressed this way.<br/>',NULL,44022,1);
INSERT INTO stanza VALUES('T10136','2','Kingdom of God, is Christ''s expansion,<br/>The seed is sown in me,<br/>The seed of life''s Jesus within us,<br/>Let Him grow ''tentively''<br/>Stony ground is our soul life,<br/>Thorns are the cares and riches all,<br/>We must not be the soil by the way,<br/>On good ground let Him fall.<br/>',NULL,44023,2);
INSERT INTO stanza VALUES('T10136','3','In the good ground, barley shall grow fast,<br/>Bring forth a hundred fold,<br/>But all the grains, must first be fine flour,<br/>For God and man as food.<br/>If His desire we would fulfill,<br/>The grinding process must be done,<br/>Thus become a holy wave off''ring,<br/>In Him we shall be one.<br/>',NULL,44024,3);
INSERT INTO stanza VALUES('T10136','4','We''re living stones, transformed through grinding,<br/>For His building we''ll be,<br/>In the Spirit, transforming, growing,<br/>Gold, pearl, so preciously.<br/>Christ we received as our Person,<br/>Our daily living occupy,<br/>By this, our life can grow and transform,<br/>Kingdom expressed thereby.<br/>',NULL,44025,4);
INSERT INTO stanza VALUES('T10136','5','Pearly nature, so pure and perfect,<br/>Reaching the highest sphere,<br/>Even after sufferings and pains,<br/>Life groweth more than e''er.<br/>Christ as my life and Person now,<br/>The Kingdom is just Christ Himself,<br/>He''s ceaselessly, growing within me,<br/>Till God and man one be.<br/>',NULL,44026,5);
INSERT INTO stanza VALUES('T10136','1','Panginoon kaharian Mo,<br/>Layon ng Iyong puso;<br/>Hindi kai-langang magpagal pa,<br/>Kundi Iyong biyaya.<br/>Mailipat ngayon pa man<br/>Kami sa Iyong kaharian;<br/>Maihayag ang kaharian,<br/>Sa ''ming kalagayan.<br/>',NULL,44027,6);
INSERT INTO stanza VALUES('T10136','2','Kaharia''y Kristong lumaki,<br/>Sa ''kin hasik binhi,<br/>Hesus, sa atin binhi''y buhay,<br/>Alaga''y ibigay.<br/>Mabatong lupa''y kalul''wa,<br/>Ang dawag-balisa''t yaman,<br/>Mahulog sa mabuting lupa,<br/>Di sa tabing daan.<br/>',NULL,44028,7);
INSERT INTO stanza VALUES('T10136','3','Lalago sa mabuting lupa<br/>Ang daang sebada;<br/>Lahat ng butil gigilingin<br/>Bago makakain.<br/>Kung layon ng Diyos tutupdin,<br/>Paggiling dapat tanggapin;<br/>Nang maging niluglog na hain,<br/>Tayo''y pag-isahin.<br/>',NULL,44029,8);
INSERT INTO stanza VALUES('T10136','4','Natranspormang buhay na bato,<br/>Ay sa pagtatayo;<br/>Sa espiritu''y lumalago,<br/>Maging perlas, ginto.<br/>Kristo''y tinanggap Persona,<br/>Sa buhay nati''y manguna;<br/>Buhay lalago''t matransporma,<br/>Kaharia''y kita.<br/>',NULL,44030,9);
INSERT INTO stanza VALUES('T10136','5','Perlas puro ang kalikasan,<br/>Abot kataasan;<br/>Pagkaraan ng dusa''t sakit,<br/>Paglago''y humigit.<br/>Kristo''y ''king buhay, persona,<br/>Kaharian ay mismong Siya;<br/>Paglago sa ''kin humantong sa<br/>Tao''t Diyos magkaisa.<br/>',NULL,44031,10);
INSERT INTO stanza VALUES('T10138','1','Jesus, my sunshine, my only sunshine,<br/>Lights up my pathway, so clear and bright.<br/>Sunny or cloudy, whate''er life may be,<br/>Jesus, Jesus — my only sunshine.<br/>',NULL,44032,1);
INSERT INTO stanza VALUES('T10138','2','O, Jesus my life, most wonderful life,<br/>Keeps and supplies me, e''er one with me;<br/>Now and forever, He''s always the same,<br/>Jesus, Jesus is my only life.<br/>',NULL,44033,2);
INSERT INTO stanza VALUES('T10139','1','The Lord, the seed of life, has sown Himself into our heart<br/>To grow up into fullness and become His counterpart.<br/>The seed requires no rules or forms, for water is its need—<br/>By this the all-inclusive seed will grow in us indeed!<br/>',NULL,44034,1);
INSERT INTO stanza VALUES('T10139','chorus','The seed is simply Jesus! Oh, Jesus lives in me!<br/>And by His growth this seed in us will reach maturity.<br/>',NULL,44035,2);
INSERT INTO stanza VALUES('T10139','2','The individual grains of wheat no longer must be free,<br/>But crushed together, ground to powder, every grain must be,<br/>Until the wheat becomes the meal from which the loaf is formed<br/>Till all the saints will blend and to His Body be conformed.<br/>',NULL,44036,3);
INSERT INTO stanza VALUES('T10139','chorus','We all must take the grinding until the Christ within<br/>Can mold into His Body all the individual grains.<br/>',NULL,44037,4);
INSERT INTO stanza VALUES('T10139','3','The seed is planted, wheat is grown and meal is the sum<br/>Of all the growth upon God''s farm, where Christians grow as one;<br/>But all the growth in life is for the building of the church,<br/>That God and man may have a home and both may end their search.<br/>',NULL,44038,5);
INSERT INTO stanza VALUES('T10139','chorus','The farm is for the building, for God and man a home,<br/>Where both may dwell among His people gathered into one.<br/>',NULL,44039,6);
INSERT INTO stanza VALUES('T10139','4','God''s building is produced by silver, precious stones, and gold—<br/>From meal through transformation, pressure, heat, and pain untold.<br/>The meal must not be satisfied to stay as meal alone,<br/>But must submit to transformation into precious stone.<br/>',NULL,44040,7);
INSERT INTO stanza VALUES('T10139','chorus','The meal must pass through suffering that precious stones be formed;<br/>Then built into God''s building, to His purpose full conformed.<br/>',NULL,44041,8);
INSERT INTO stanza VALUES('T10139','5','From fullest growth and transformation comes a pearl of worth;<br/>This simple, precious, all-inclusive gem will then come forth.<br/>Conceived in death and formed in life by that all-glorious One,<br/>The church, His Bride, the fruit of all the work that He has done.<br/>',NULL,44042,9);
INSERT INTO stanza VALUES('T10139','chorus','The pearl is what He''s after, the Bride to please His heart,<br/>So single, pure and precious, and His very counterpart.<br/>',NULL,44043,10);
INSERT INTO stanza VALUES('T10139','6','Lord, keep us poor in spirit, pure in heart that we may be<br/>Good ground in which the seed of life may grow abundantly,<br/>Until the final stage is reached and You are satisfied<br/>And have Your priceless, chosen pearl, Your joy complete, Your Bride.<br/>',NULL,44044,11);
INSERT INTO stanza VALUES('T10139','chorus','Lord, keep us poor in spirit and purified in heart,<br/>That growing up in us You may bring forth Your counterpart.<br/>',NULL,44045,12);
INSERT INTO stanza VALUES('T10140','1','Christ, Christ, He''s in us today,<br/>All old religion''s now cast away,<br/>We are all His family,<br/>We''re one in the spirit, in harmony,<br/>We are living now, praising the Lord,<br/>Shouting His name, our spirits have soared,<br/>In the local churches we will eat and be satisfied.<br/>',NULL,44046,1);
INSERT INTO stanza VALUES('T10141','1','Hallelujah! Hallelujah!<br/>Jesus is now living, living in me.<br/>Hallelujah! Hallelujah!<br/>Jesus is living in me.<br/>',NULL,44047,1);
INSERT INTO stanza VALUES('T10141','2','*The word <i>living</i> can be changed into <i>moving</i>, <i>growing</i>, <i>forming</i>, <i>dwelling</i>, <i>burning</i>, or others.<br/>',NULL,44048,2);
INSERT INTO stanza VALUES('T10142','1','In my heart there dwells the Son of Man,<br/>So perfect and so fine,<br/>So human, yet divine,<br/>In my heart there dwells the Son of Man<br/>To live in me His human life.<br/>',NULL,44049,1);
INSERT INTO stanza VALUES('T10142','2','In my heart there lives the Son of Man<br/>For His humanity<br/>To be expressed in me.<br/>In my heart there lives the Son of Man;<br/>His human living flows through me.<br/>',NULL,44050,2);
INSERT INTO stanza VALUES('T10143','1','How wonderful He''s my person,<br/>Foll''wing Him I''m living now.<br/>He shouts, so I shout,<br/>He smiles, so I smile,<br/>He jumps, so I jump,<br/>O how carefree we''re now!<br/>',NULL,44051,1);
INSERT INTO stanza VALUES('T10143','2','How wonderful He''s my person,<br/>Foll''wing Him I''m living now.<br/>He moves, so I move,<br/>He sings, so I sing,<br/>He tells, so I tell,<br/>O how carefree we''re now!<br/>',NULL,44052,2);
INSERT INTO stanza VALUES('T10144','1','Lord, to know Thee as our Person,<br/>Earnestly we seek and pray;<br/>To experience Thy fullness<br/>In a constant inner way.<br/>Never longer only outward<br/>Or with soulish thoughts obsessed,<br/>But, O Lord, in realest contact<br/>We by Thee would be possessed.<br/>',NULL,44053,1);
INSERT INTO stanza VALUES('T10144','chorus','Lord, Thou art our Person,<br/>In our inmost being,<br/>May we constantly experience<br/>This reality.<br/>',NULL,44054,2);
INSERT INTO stanza VALUES('T10144','2','All the world is under darkness,<br/>Driven by the fallen soul,<br/>And the enemy designing<br/>Does the soulish life control.<br/>Such we were till God, through mercy,<br/>Caused His Son to dwell in us;<br/>Now we fully come to know Him<br/>In His church so glorious.<br/>',NULL,44055,3);
INSERT INTO stanza VALUES('T10144','chorus','Lord, Thou art our Person,<br/>In our inmost being,<br/>May we constantly experience<br/>This reality.<br/>',NULL,44056,4);
INSERT INTO stanza VALUES('T10144','3','Once we walked a soulish person,<br/>Wandering in the wilderness,<br/>Never knowing that our spirit<br/>Craved God''s fullness to express;<br/>At the moment Jesus entered<br/>Instantly the whole was changed.<br/>Now we''re people spirit-centered!<br/>Hallelujah! Rearranged!<br/>',NULL,44057,5);
INSERT INTO stanza VALUES('T10144','chorus','Lord, Thou art our Person,<br/>In our inmost being,<br/>May we constantly experience<br/>This reality.<br/>',NULL,44058,6);
INSERT INTO stanza VALUES('T10144','4','Now our spirit is our person—<br/>What a glorious fact is this!<br/>Christ Himself in us expressing<br/>God''s intent and holiness.<br/>Not the soul-life''s vain delusion,<br/>But the spirit strengthened is;<br/>Christ Himself is now our Person—<br/>He is ours and we are His.<br/>',NULL,44059,7);
INSERT INTO stanza VALUES('T10144','chorus','Lord, Thou art our Person,<br/>In our inmost being,<br/>May we constantly experience<br/>This reality.<br/>',NULL,44060,8);
INSERT INTO stanza VALUES('T10146','1','Life of glory, oh how glorious!<br/>Christ, the glorious life is He;<br/>Holy, perfect, pure, and righteous,<br/>O how rich this life to me!<br/>All the fullness of the Godhead<br/>Dwell in Him thus bodily,<br/>As my life He is imparted,<br/>He supplies me inwardly.<br/>',NULL,44061,1);
INSERT INTO stanza VALUES('T10146','2','Life divine, oh life divine ''tis<br/>Christ, the life divine is He;<br/>He''s the consummated Spirit,<br/>And has come to dwell in me.<br/>Moving, working, shining, teaching<br/>As th'' anointing soothing me,<br/>Filling, drenching, strength''ning, feeding,<br/>He supplies me inwardly.<br/>',NULL,44062,2);
INSERT INTO stanza VALUES('T10146','3','Life of power, power truly,<br/>Christ, the life of power is He;<br/>With Him I''ve been resurrected,<br/>Slave of sin no more I''d be.<br/>Now my life He lives within me,<br/>Living constantly with Him,<br/>Resurrection pow''r I''ve tasted,<br/>He supplies me inwardly.<br/>',NULL,44063,3);
INSERT INTO stanza VALUES('T10146','4','Life of vict''ry, life of vict''ry,<br/>Christ, victorious life is He,<br/>On the cross He won the vict''ry,<br/>Captive no more I would be.<br/>Satan, demons, passions, vices,<br/>He has conquered them for me;<br/>Now my life of vict''ry He is,<br/>He supplies me inwardly.<br/>',NULL,44064,4);
INSERT INTO stanza VALUES('T10146','5','Life of glory, power, vict''ry,<br/>Christ, the life divine is He!<br/>He gives vict''ry, power; makes me<br/>Grow unto maturity;<br/>He transforms me to His image,<br/>Then I''ll be transcendent, free,<br/>Till that day of rapture, marriage,<br/>He supplies me inwardly.<br/>',NULL,44065,5);
INSERT INTO stanza VALUES('T10146','1','Gloria, gloria, gloriang buhay!<br/>Kristo ang gloriang buhay!<br/>Banal, mat''wid at mainam,<br/>O, buhay na kay yaman!<br/>Pagka-Diyos na kapuspusan<br/>Sa Kanya''y nanahanan.<br/>Ngayon buhay ko''y si Kristo,<br/>Panustos sa loob ko.<br/>',NULL,44066,6);
INSERT INTO stanza VALUES('T10146','2','Makadiyos, dibinong buhay,<br/>Kay Kristo''y natataglay<br/>Naging Espiritu na Siya,<br/>Sa akin nakatira.<br/>Humihipo, nagtuturo<br/>Nagpapahid sa lo''b ko;<br/>Nagpalakas, nagpupuspos.<br/>Sa loob ko''y panustos.<br/>',NULL,44067,7);
INSERT INTO stanza VALUES('T10146','3','Makapangyarihang buhay,<br/>Kay Kristo''y matataglay;<br/>Nabuhay na kasama Niya,<br/>Di na alipin sala.<br/>Ngayon sa akin buhay Siya,<br/>Palagi kong kasama,<br/>Pagkabuhay ay natikman,<br/>Loob ko''y natustusan.<br/>',NULL,44068,8);
INSERT INTO stanza VALUES('T10146','4','O matagumpay na buhay,<br/>Kristo''y panalong buhay!<br/>Sa krus nagtagumpay na Siya<br/>Nang ako''y mapalaya!<br/>Diyablo sanlibutan, tukso,<br/>Lubusan Niyang tinalo;<br/>Buhay kong matagumpay Siya,<br/>Panloob ko''y tustos Niya.<br/>',NULL,44069,9);
INSERT INTO stanza VALUES('T10146','5','Banal, malakas, dibino,<br/>Gloriang buhay si Kristo;<br/>Pinalakas, pinagwagi,<br/>Hininog, pinalaki.<br/>Iwinawangis sa Kanya<br/>Nang ako''y mapalaya!<br/>Hanggang sa Kanyang pagbalik,<br/>Tustos Siyang walang patid.<br/>',NULL,44070,10);
INSERT INTO stanza VALUES('T10204','1','O let''s enjoy Christ''s riches together,<br/>For our Lord is that Spirit, life-giver;<br/>In our spirit He dwelleth, His life He giveth<br/>To supply, anoint and transform us.<br/>Wonder of wonders is that<br/>our Lord is one with us;<br/>We will shout and we''ll sing:<br/>"Hallelujah, Praise the Lord!"<br/>O let''s enjoy altogether Christ''s riches,<br/>Fully feast on His all-inclusiveness.<br/>',NULL,44071,1);
INSERT INTO stanza VALUES('T10204','1','Tamasahin ang yaman ni Kristo,<br/>Ang Panginoon ay Espiritu;<br/>Nagbibigay ng buhay, nananahanan,<br/>Tayo''y Kanyang tinutustusan.<br/>Kamangha-mangha na si<br/>Kristo''y kaisa natin:<br/>Tayo ay aawit: "Aleluya, Purihin!"<br/>Nagpapaloob-ng-lahat na Kristo,<br/>Atin Siyang pagpistahan nang husto.<br/>',NULL,44072,2);
INSERT INTO stanza VALUES('T10205','1','We enjoy our Jesus in such a living way<br/>Eating, drinking and breathing the Lord.<br/>We enjoy our Jesus in such a living way<br/>Reality, Eating, drinking and breathing the Lord.<br/>We enjoy our Jesus in such a living way<br/>In the church, Reality,<br/>Eating, drinking and breathing the Lord.<br/>We enjoy our Jesus in such a living way<br/>Love and unity, In the church, Reality,<br/>Eating, drinking and breathing the Lord.<br/>We enjoy our Jesus in such a living way<br/>Jesus is Lord, Love and unity,<br/>In the church, Reality,<br/>Eating, drinking and breathing the Lord.<br/>',NULL,44073,1);
INSERT INTO stanza VALUES('T10205','1','Si Hesus buháy nga nating tamasahin,<br/>Kainin, inumin, hingahin.<br/>Si Hesus buháy nga nating tamasahin,<br/>Realidad, kainin, inumin, hingahin.<br/>Si Hesus buháy nga nating tamasahin<br/>Sa ekklesia, tunay nga,<br/>Kainin, inumin, hingahin.<br/>Si Hesus buháy nga nating tamasahin,<br/>Pag-ibig, kai-sahan sa ekklesia''y tunay,<br/>Kainin, inumin, hingahin.<br/>Si Hesus buháy nga nating tamasahin,<br/>Siya ay Poon, Pag-ibig, kai-sahan,<br/>Sa ekklesia''y tunay,<br/>Kainin, inumin, hingahin.<br/>',NULL,44074,2);
INSERT INTO stanza VALUES('T10206','1','We want more of Jesus, more and more and more,<br/>We want more of Jesus than we''ve ever had before;<br/>We want more of Christ as life, rich and glorious,<br/>We want more of Jesus, so we''ll give Him more of us.<br/>',NULL,44075,1);
INSERT INTO stanza VALUES('T10206','2','Eating more of Jesus, more and more and more,<br/>Eating more of Jesus than we ever ate before;<br/>We want more of Christ as food, rich and nutritious,<br/>Eating more of Jesus, so we''ll eat Him into us.<br/>',NULL,44076,2);
INSERT INTO stanza VALUES('T10206','1','Hesus nais namin, higit pa ngayon,<br/>Hesus nais namin, higit kaysa no''n;<br/>May glorya''t yaman Kristo bilang buhay<br/>Nang Siya''y kamtin, tayo sa Kanya''y mag-alay.<br/>',NULL,44077,3);
INSERT INTO stanza VALUES('T10206','2','Hesus kanin natin higit pa ngayon,<br/>Hesus kanin natin higit kaysa no''n;<br/>Kristo bilang pagkain, masustansya,<br/>Kaya nararapat na higit kainin Siya.<br/>',NULL,44078,4);
INSERT INTO stanza VALUES('T10207','1','Taste and see the Lord is good, Hallelujah!<br/>Taste and see the Lord is good, Hallelujah!<br/>We''ve tasted and the Lord is good, Hallelujah!<br/>We''ve tasted and the Lord is good, Hallelujah!<br/>',NULL,44079,1);
INSERT INTO stanza VALUES('T10207','2','Tikman at tingnan ngayon, Aleluya!<br/>Mabuti ang Pangino''n, Aleluya!<br/>Mabuti nga ang Pangino''n, Aleluya!<br/>Mabuti nga ang Pangino''n, Aleluya!<br/>',NULL,44080,2);
INSERT INTO stanza VALUES('T10208','1','Let''s enjoy, let''s enjoy, enjoy all His riches,<br/>Let''s enjoy, let''s enjoy, enjoy all His riches,<br/>Let''s enjoy, let''s enjoy, enjoy all His riches,<br/>Let''s enjoy, let''s enjoy, enjoy all His riches,<br/>Enjoy, why be mis''rable when Christ is so rich.<br/>Enjoy, why be mis''rable when Christ is so rich.<br/>Let''s enjoy, let''s enjoy, enjoy all His riches,<br/>Let''s enjoy, let''s enjoy, enjoy all His riches.<br/>',NULL,44081,1);
INSERT INTO stanza VALUES('T10208','2','*Can be changed into:<br/>Let''s release, let''s release, . . .<br/>Release, why withhold and not release His riches.<br/>Or<br/><i>Testify</i>, <i>Praise the Lord</i>, <i>O let''s share</i>, <i>Eat and drink</i>, <i>Let''s breathe Him</i>. . .<br/>',NULL,44082,2);
INSERT INTO stanza VALUES('T10209','beginning-note','Nehemiah 8<br/>',NULL,44083,1);
INSERT INTO stanza VALUES('T10209','1','The joy of the Lord is thy strength,<br/>Thy strength, praise the Lord,<br/>The joy of the Lord is thy strength,<br/>Thy strength, praise the Lord.<br/>Go eat the fat and drink the sweet,<br/>For this day is holy unto Him,<br/>The joy of the Lord is thy strength,<br/>Thy strength, praise the Lord.<br/>',NULL,44084,2);
INSERT INTO stanza VALUES('T10210','1','Oh, come all ye brothers,<br/>Come to morning table.<br/>Oh, come all ye sisters,<br/>To morning watch.<br/>Come and enjoy Him,<br/>Everyone is able.<br/>Oh, come let us enjoy Him,<br/>Oh, come let us enjoy Him,<br/>Oh, come let us enjoy Him,<br/>At the morning watch.<br/>',NULL,44085,1);
INSERT INTO stanza VALUES('T10211','1','Eating in the morning,<br/>Oh, it makes our spirit strong.<br/>We can really taste Him,<br/>And our sleep is turned to song!<br/>Don''t heed the Devil''s voice<br/>Excuses are from him.<br/>Just jump out of bed<br/>and he really loses!<br/>Eating in the morning,<br/>Eating Jesus all day long!<br/>',NULL,44086,1);
INSERT INTO stanza VALUES('T10213','1','Calling O Lord Jesus,<br/>He''ll save to the end.<br/>Calling O Lord Jesus,<br/>Closer drawn to Him.<br/>Calling O Lord Jesus,<br/>Freed from self and sin,<br/>Calling O Lord Jesus,<br/>There''s matchless joy in Him.<br/>',NULL,44087,1);
INSERT INTO stanza VALUES('T10213','2','Calling O Lord Jesus,<br/>Call from deep within;<br/>Calling O Lord Jesus,<br/>He''s our help in need.<br/>Calling unceasingly,<br/>Breathe out and breathe in;<br/>Breathe out our sin and world,<br/>Breathe in beloved Lord.<br/>',NULL,44088,2);
INSERT INTO stanza VALUES('T10213','3','Eating, drinking Jesus,<br/>Pray-reading His Word;<br/>Eating, drinking Jesus,<br/>Enjoying our Lord.<br/>Eating, drinking Jesus,<br/>What abundant life;<br/>Eating, drinking Jesus,<br/>Th'' way to victorious life.<br/>',NULL,44089,3);
INSERT INTO stanza VALUES('T10213','4','Eating in the meeting,<br/>Makes our spirit strong;<br/>Freed from religion, cults,<br/>Rituals and oldness.<br/>Mutual fellowshipping,<br/>Bring Lord''s fragrance out;<br/>Enjoy precious church life<br/>And build up in oneness.<br/>',NULL,44090,4);
INSERT INTO stanza VALUES('T10214','1','Just taste and see that the Lord is good;<br/>Just taste and see that the Lord is good.<br/>He''s good for you, as He is for me;<br/>So whatever you do, just taste and see.<br/>',NULL,44091,1);
INSERT INTO stanza VALUES('T10214','2','Just call O Lord — He''ll change your life;<br/>Just call O Lord — He''ll change your life.<br/>Amazing grace He will afford;<br/>If in every place you call O Lord.<br/>',NULL,44092,2);
INSERT INTO stanza VALUES('T10214','3','You''ll feel real love coming into your heart;<br/>You''ll feel real love coming into your heart.<br/>You''ll sense a flow from God above;<br/>And you will know you''ve found real love.<br/>',NULL,44093,3);
INSERT INTO stanza VALUES('T10214','4','So praise the Lord for His life in you;<br/>Yes, praise the Lord for His life in you.<br/>Something of Christ He has outpoured<br/>Into your life; so praise the Lord!<br/>',NULL,44094,4);
INSERT INTO stanza VALUES('T10216','1','Wholly, wholly, wholly back to the beginning—<br/>God is in Christ Jesus now, and He is food to us.<br/>Feeding, feeding, feeding, crazy-seekers eating;<br/>In God''s recovery, we don''t know so much.<br/>',NULL,44095,1);
INSERT INTO stanza VALUES('T10216','2','Loudly shouting, "Jesus!" Oh, it really feeds us!<br/>We have found where Jesus is — He''s in the hungry mouth.<br/>Not religious nodding, but recovered shouting—<br/>In God''s recovery, we don''t know so much.<br/>',NULL,44096,2);
INSERT INTO stanza VALUES('T10216','3','Chewing, chewing, chewing, not our outward doing;<br/>Cease from all your working now, begin again to EAT.<br/>Feasting, feasting, feasting, drop the old dead teachings—<br/>In God''s recovery, we just know to EAT.<br/>',NULL,44097,3);
INSERT INTO stanza VALUES('T10218','beginning-note','(Matthew 4:4)<br/>',NULL,44098,1);
INSERT INTO stanza VALUES('T10218','1','Man shall not live by bread alone,<br/>But by every word<br/>That proceeds from the mouth of God,<br/>Hallelu — Hallelujah!<br/>',NULL,44099,2);
INSERT INTO stanza VALUES('T10218','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Hallelu — Hallelujah!<br/>(John 6:63)<br/>',NULL,44100,3);
INSERT INTO stanza VALUES('T10218','2','It is the spirit that gives life,<br/>The flesh profits nothing;<br/>All the words that I speak unto you,<br/>They are spirit and life.<br/>',NULL,44101,4);
INSERT INTO stanza VALUES('T10218','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Hallelu — Hallelujah!<br/>(Jeremiah 15:16)<br/>',NULL,44102,5);
INSERT INTO stanza VALUES('T10218','3','Thy words were found and I ate them<br/>Halle-lu-Hallelujah!<br/>Unto me Thy words are the joy<br/>And rejoicing of my heart.<br/>',NULL,44103,6);
INSERT INTO stanza VALUES('T10218','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Hallelu — Hallelujah!<br/>(Ephesians 6:17,18)<br/>',NULL,44104,7);
INSERT INTO stanza VALUES('T10218','4','Take ye the sword of the Spirit,<br/>Which is the word of God;<br/>With all prayer and supplication,<br/>Pray always in the spirit.<br/>',NULL,44105,8);
INSERT INTO stanza VALUES('T10218','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Hallelu — Hallelujah!<br/>(Ephesians 5:26,27)<br/>',NULL,44106,9);
INSERT INTO stanza VALUES('T10218','5','With the washing by the word,<br/>His church He''ll sanctify and cleanse,<br/>That He might present to Himself,<br/>A holy and glorious church.<br/>',NULL,44107,10);
INSERT INTO stanza VALUES('T10218','chorus','Hallelujah, Hallelujah,<br/>Hallelujah, Hallelu — Hallelujah!<br/>(Mateo 4:4)<br/>',NULL,44108,11);
INSERT INTO stanza VALUES('T10218','1','Ang tao di nabubuhay,<br/>Sa tinapay lamang;<br/>Kundi sa bawa''t salita.<br/>Mula sa bibig ng Diyos.<br/>',NULL,44109,12);
INSERT INTO stanza VALUES('T10218','chorus','Aleluya, aleluya,<br/>Aleluya, alelu — aleluya!<br/>(Juan 6:63)<br/>',NULL,44110,13);
INSERT INTO stanza VALUES('T10218','2','''Spiritu nagbigay-buhay,<br/>Laman walang pakinabang;<br/>Ang lahat ng salita Niya,<br/>Pawang ''spiritu''t buhay.<br/>',NULL,44111,14);
INSERT INTO stanza VALUES('T10218','chorus','Aleluya, aleluya,<br/>Aleluya, alelu — aleluya!<br/>(Jeremias 15:16)<br/>',NULL,44112,15);
INSERT INTO stanza VALUES('T10218','3','Salita Mo''y nasumpungan,<br/>At aking kinain;<br/>Salita Mo''y kagalakan,<br/>Kasyahan ng ''king puso.<br/>',NULL,44113,16);
INSERT INTO stanza VALUES('T10218','chorus','Aleluya, aleluya,<br/>Aleluya, alelu — aleluya!<br/>(Efeso 6:17,18)<br/>',NULL,44114,17);
INSERT INTO stanza VALUES('T10218','4','Kunin tabak ng ''Spiritu,<br/>Siyang salita ng Diyos;<br/>Nang may dalangin at daing,<br/>Sa ''spiritu''y manalangin.<br/>',NULL,44115,18);
INSERT INTO stanza VALUES('T10218','chorus','Aleluya, aleluya,<br/>Aleluya, alelu — aleluya!<br/>(Efeso 5:26-27)<br/>',NULL,44116,19);
INSERT INTO stanza VALUES('T10218','5','Paghuhugas ng salita,<br/>Ekklesia''y pinabanal;<br/>Nang maiharap sa Kanya<br/>Mal''walhating ekklesia.<br/>',NULL,44117,20);
INSERT INTO stanza VALUES('T10218','chorus','Aleluya, aleluya,<br/>Aleluya, alelu — aleluya!<br/>',NULL,44118,21);
INSERT INTO stanza VALUES('T10224','1','We''re feeding on the living bread.<br/>We''re drinking at the fountainhead;<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again.<br/>What, never thirst again?<br/>No, never thirst again!<br/>What, never thirst again?<br/>No, never thirst again!<br/>And whoso drinketh, Jesus said,<br/>Shall never, never thirst again.<br/>',NULL,44119,1);
INSERT INTO stanza VALUES('T10224','2','We are feeding on the living bread,<br/>Eating at the feast our Lord has spread,<br/>And whoso eateth, Jesus said,<br/>Shall hunger nevermore.<br/>What, hunger nevermore?<br/>Yes, hunger nevermore!<br/>What, hunger nevermore?<br/>Yes, hunger nevermore!<br/>And whoso eateth, Jesus said,<br/>Shall hunger nevermore.<br/>',NULL,44120,2);
INSERT INTO stanza VALUES('T10224','3','We are breathing in the living air,<br/>Breathing in the One whose life we share,<br/>And whoso breatheth — now, fore''er—<br/>Shall have the life of God.<br/>What, have the life of God?<br/>Yes, have the life of God!<br/>What, have the life of God?<br/>Yes, have the life of God!<br/>And whoso breatheth — now, fore''er—<br/>Shall have the life of God.<br/>',NULL,44121,3);
INSERT INTO stanza VALUES('T10224','4','We are tasting of the living wine,<br/>In spirit tasting life divine,<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>What, have the joy of God?<br/>Yes, have the joy of God!<br/>What, have the joy of God?<br/>Yes, have the joy of God!<br/>And whoso tasteth, everytime<br/>Shall have the joy of God.<br/>',NULL,44122,4);
INSERT INTO stanza VALUES('T10224','5','Christ is the resurrected King,<br/>Who died and rose, our life to bring,<br/>If You receive Him you will sing,<br/>And live forevermore.<br/>What, live forevermore? Yes, live forevermore!<br/>What, live forevermore? Yes, live forevermore!<br/>If You receive Him you will sing,<br/>And live forevermore.<br/>',NULL,44123,5);
INSERT INTO stanza VALUES('T10225','1','Water of life, (Flowing! Flowing!)<br/>A river of life, (Flowing! Flowing!)<br/>Flowing with God''s life, (His life! His life!)<br/>His life''s our supply, (Supply! Supply!)<br/>That we be transformed, (Transformed! Transformed!)<br/>His image conformed, (Conformed! Conformed!)<br/>And in His image, God and man<br/>Mutually are satisfied.<br/>',NULL,44124,1);
INSERT INTO stanza VALUES('T10225','2','O abundant life, e''er fulfilling joy,<br/>Ever sweeter, ever richer;<br/>O the depths of Him, we could ne''er fathom,<br/>But flowing through me, I now enjoy.<br/>Enjoy and grow to be precious stones and pure gold,<br/>God''s building we become.<br/>O what a glorious testimony.<br/>',NULL,44125,2);
INSERT INTO stanza VALUES('T10227','1','Of Him whence grace and truth did spring,<br/>We''re at the fountain drinking;<br/>This Christ we''ll ever praise and sing,<br/>Here in the church, His home!<br/>',NULL,44126,1);
INSERT INTO stanza VALUES('T10227','chorus','Glory to God! We''re at the fountain drinking!<br/>Glory to God! We''re in the church, our home!<br/>',NULL,44127,2);
INSERT INTO stanza VALUES('T10227','2','Ask but His grace, and lo, ''tis giv''n,<br/>We''re at the fountain drinking;<br/>Seek only Christ, the heaven of heaven,<br/>And find Him here at home!<br/>',NULL,44128,3);
INSERT INTO stanza VALUES('T10227','chorus','Glory to God! We''re at the fountain drinking!<br/>Glory to God! We''re in the church, our home!<br/>',NULL,44129,4);
INSERT INTO stanza VALUES('T10227','3','Though Satan fights with all his power,<br/>We''re at the fountain drinking;<br/>He''ll not prevail, not one short hour,<br/>Against the church, our home!<br/>',NULL,44130,5);
INSERT INTO stanza VALUES('T10227','chorus','Glory to God! We''re at the fountain drinking!<br/>Glory to God! We''re in the church, our home!<br/>',NULL,44131,6);
INSERT INTO stanza VALUES('T10227','4','Athirst we to this spring do fly,<br/>We''re at the fountain drinking;<br/>Drink deep, this well will not run dry!<br/>It''s in the church, our home!<br/>',NULL,44132,7);
INSERT INTO stanza VALUES('T10227','chorus','Glory to God! We''re at the fountain drinking!<br/>Glory to God! We''re in the church, our home!<br/>',NULL,44133,8);
INSERT INTO stanza VALUES('T10228','1','Now Christ is the life-giving Spirit;<br/>Now Christ is the living Word too.<br/>The Spirit will flow in our spirit,<br/>The Word will be life to us through—<br/>Eating, drinking and breathing<br/>Him all the day long;<br/>Eating, drinking and breathing<br/>Him all the day long.<br/>',NULL,44134,1);
INSERT INTO stanza VALUES('T10228','2','Now Christ is the life-giving Spirit;<br/>Now Christ is the living Word too.<br/>The Spirit will flow in our spirit,<br/>The Word will be life to us through—<br/>Praying, reading, praising,<br/>Calling upon His name;<br/>Praying, reading, praising,<br/>Calling upon His name.<br/>',NULL,44135,2);
INSERT INTO stanza VALUES('T10228','1','Kristo''y Espiritu ng buhay!<br/>Kristo''y Salita ng buhay!<br/>''Spiritu tustos sa ''spiritu,<br/>Buhay salita ni Kristo.<br/>Buong araw kainin,<br/>inumin, langhapin,<br/>Upang Siya''y mapasa atin:<br/>Kristong buhay.<br/>',NULL,44136,3);
INSERT INTO stanza VALUES('T10228','2','Kristo''y Espiritu ng buhay!<br/>Kristo''y Salita ng buhay!<br/>''Spiritu tustos sa ''spiritu,<br/>Buhay Salita ni Kristo.<br/>Espiritu gamitin<br/>sa panalangin.<br/>Magbasa at magpuri,<br/>Hesus tawagin.<br/>',NULL,44137,4);
INSERT INTO stanza VALUES('T10229','1','Breathing in the Lord, is how we live today.<br/>Not by thinking do we live, but breathing is the way.<br/>We just call "O Lord", from very deep within,<br/>And with joy we testify we''re breathing in of Him.<br/>',NULL,44138,1);
INSERT INTO stanza VALUES('T10229','chorus','Breathe in Christ, breathe in Life, breathe Him in today,<br/>He''s our very life supply, so breathe Him right away;<br/>',NULL,44139,2);
INSERT INTO stanza VALUES('T10229','2','He''s so wonderful, the Breath of Life is He;<br/>Once He simply was a man, but now He''s breath in me.<br/>He has changed His form; the Spirit now is He,<br/>He''s the Christ breathed out from God, the Breath breathed in by me.<br/>',NULL,44140,3);
INSERT INTO stanza VALUES('T10229','chorus','Everywhere, everywhere, Christ is life to me;<br/>I just call upon His name, and breath comes into me.<br/>',NULL,44141,4);
INSERT INTO stanza VALUES('T10230','1','Breath by breath we breathe the Lord. Amen! Amen!<br/>Breath by breath He quickens us. Amen! Amen!<br/>Yes, we breathe out and we breathe in,<br/>And deeply flows His life within,<br/>For we all learned how to deeply breathe the Lord.<br/>',NULL,44142,1);
INSERT INTO stanza VALUES('T10230','2','John 3:8 speaks of the Air without, without;<br/>Th'' wind blows where it wills, it wills. Without, without!<br/>We cannot tell from whence it comes;<br/>We cannot tell to where it runs;<br/>So is everyone who''s of the Spirit born.<br/>',NULL,44143,2);
INSERT INTO stanza VALUES('T10230','3','John 20:22 speaks of the Air within.<br/>Jesus breathed the breath of life. From Him! From Him!<br/>He only asked us to receive—<br/>''Tis not to think, but only breathe;<br/>And it''s by this Breath that we experience Life.<br/>',NULL,44144,3);
INSERT INTO stanza VALUES('T10230','4','Now wherever we may be there''s Air! there''s Air!<br/>It surrounds, envelops us, it''s everywhere!<br/>Available, so rich and free<br/>That we might live abundantly;<br/>So brothers, sisters, breathe the breath of life.<br/>',NULL,44145,4);
INSERT INTO stanza VALUES('T10230','5','Just by calling on His name, O Lord! O Lord!<br/>Christ becomes the breath to us. O Lord! O Lord!<br/>We breathe His name from deep within<br/>And breathe until we''re filled with Him,<br/>And what a Breath this Jesus is to us!<br/>',NULL,44146,5);
INSERT INTO stanza VALUES('T10230','1','Hingahin ang Pangino''n! Amen! Amen!<br/>Bubuhayin Niya tayo. Amen! Amen!<br/>O, palabas at paloob,<br/>Umaagos ang buhay Niya<br/>''Pagka''t natuto na tayong huminga.<br/>',NULL,44147,6);
INSERT INTO stanza VALUES('T10230','2','Binanggit sa Juan tres hangin sa labas<br/>Umiihip sa sarili niyang batas.<br/>Ihip doon, ihip dito;<br/>Hindi batid, sa''n ang tungo.<br/>Gayon din ang sinilang ng ''Spiritu.<br/>',NULL,44148,7);
INSERT INTO stanza VALUES('T10230','3','Sa Juan bente naman hangin sa loob.<br/>Hininga ni Hesus, galing sa loob.<br/>Dapat lamang na tanggapin,<br/>Hindi kailangang isipin.<br/>Sa hiningang buhay ating danasin.<br/>',NULL,44149,8);
INSERT INTO stanza VALUES('T10230','4','Saan man magtungo, may hangin, hangin.<br/>Pumapaligid sa ''tin, hangin, hangin.<br/>Walang bayad, tamasahin,<br/>Sasagana''ng buhay natin.<br/>Mga kapatid, Siya''y ating hingahin.<br/>',NULL,44150,9);
INSERT INTO stanza VALUES('T10230','5','Tumawag sa ngalan Niya — Panginoon.<br/>Maging hininga natin — ating Poon.<br/>Huminga galing sa loob,<br/>Hanggang sa Siya ay magpuspos.<br/>Napakasagana ng ating Hesus.<br/>',NULL,44151,10);
INSERT INTO stanza VALUES('T10231','1','Life, life, life! In Jesus we obtain it.<br/>Life, life, life! Now we would maintain it.<br/>Calling on His name by faith,<br/>Pray-read God''s Word to sustain,<br/>Meet and serve to life maintain,<br/>We have Life, Life, Life!<br/>',NULL,44152,1);
INSERT INTO stanza VALUES('T10231','2','Precious blood! We are covered wholly.<br/>Precious blood! We may enter boldly.<br/>Fully cleansed from all our past,<br/>Its effectiveness will last;<br/>The accuser down is cast<br/>By the precious blood!<br/>',NULL,44153,2);
INSERT INTO stanza VALUES('T10231','3','Faith, faith, faith! Precious faith we prize it.<br/>Faith, faith, faith! Satan doth despise it.<br/>Making real the unseen things,<br/>Shielding us from Satan''s stings,<br/>Promised rest to us it brings,<br/>Hallelujah — faith!<br/>',NULL,44154,3);
INSERT INTO stanza VALUES('T10231','4','Call, call, call! Calling, "O Lord Jesus!"<br/>Call, call, call! Spirit it releases.<br/>Boldly speak this precious Name,<br/>Evermore the Lord proclaim—<br/>To the devil what a shame!<br/>So call, call, call!<br/>',NULL,44155,4);
INSERT INTO stanza VALUES('T10231','5','Call-pray-read. . . God''s Word we are eating.<br/>Call-pray-read. . . at home and in meeting.<br/>By the Word we are supplied,<br/>Soul and spirit thus divide,<br/>Life and growth his Words provide<br/>When we call-pray-read.<br/>',NULL,44156,5);
INSERT INTO stanza VALUES('T10231','6','Meet, meet, meet! Christ the Lord expressing.<br/>Meet, meet, meet! Each time how refreshing!<br/>All the saints can prophesy,<br/>Sing, pray-read, and testify<br/>As the church is edified<br/>As we meet, meet, meet!<br/>',NULL,44157,6);
INSERT INTO stanza VALUES('T10231','7','Serve, serve, serve! Everyone''s a member.<br/>Serve, serve, serve! Each a function render.<br/>All positions by the Lord,<br/>Grace to each He does afford.<br/>Built in love in one accord,<br/>In the Body, serve!<br/>',NULL,44158,7);
INSERT INTO stanza VALUES('T10232','1','We''ve got the "O Lord, Amen, Hallelujah!"<br/>Down in our hearts, down in our hearts,<br/>down in our hearts;<br/>We''ve got the "O Lord, Amen, Hallelujah!"<br/>Down in our hearts;<br/>Down in our hearts to stay.<br/>And we''re so happy, so very happy,<br/>We''ve got the "O Lord, Amen," in our hearts,<br/>Hallelujah!<br/>And we''re so happy, so very happy,<br/>We''ve got the "O Lord, Amen," in our hearts.<br/>',NULL,44159,1);
INSERT INTO stanza VALUES('T10232','2','Ako''y may "O Panginoon, Amen at Aleluya!"<br/>Sa puso ko, sa puso ko;<br/>Ako''y may "O Panginoon, Amen at Aleluya!"<br/>Magpakailanpaman.<br/>Ako''y puspos ng kaligayahan,<br/>Panginoon, Amen sa puso ko, Aleluya!<br/>Ako''y puspos ng kaligayahan,<br/>Panginoon, Amen sa puso ko.<br/>',NULL,44160,2);
INSERT INTO stanza VALUES('T10233','1','O how nigh the Lord is unto all who call on Him!<br/>When we call, His very presence strengthens us within.<br/>Seeking Jesus, He is found, and calling, He is near—<br/>O what a comfort to our hearts to call His name so dear!<br/>',NULL,44161,1);
INSERT INTO stanza VALUES('T10233','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted — O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere,<br/>"O Lord Jesus!" O what a name!<br/>',NULL,44162,2);
INSERT INTO stanza VALUES('T10233','2','Call upon the name of Jesus, and you will be saved,<br/>O Lord Jesus, hallelujah, nevermore enslaved!<br/>We may take salvation''s cup by calling on the Lord;<br/>Salvation from a host of things does His dear name afford.<br/>',NULL,44163,3);
INSERT INTO stanza VALUES('T10233','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted — O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere,<br/>"O Lord Jesus!" O what a name!<br/>',NULL,44164,4);
INSERT INTO stanza VALUES('T10233','3','To the Lord, the Jew, the Greek and everyone''s the same;<br/>He is rich unto all men that call upon His name.<br/>O Lord Jesus, what a joy to call and really live;<br/>When breathing in Thy name, what pleasure Thou to us dost give.<br/>',NULL,44165,5);
INSERT INTO stanza VALUES('T10233','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted — O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere,<br/>"O Lord Jesus!" O what a name!<br/>',NULL,44166,6);
INSERT INTO stanza VALUES('T10233','4','In the God of our salvation we may take delight,<br/>Calling on His name at all times, though in bliss or blight.<br/>I will call upon the Lord''s name as long as I live,<br/>Because He has inclined His ear, and grace so full does give.<br/>',NULL,44167,7);
INSERT INTO stanza VALUES('T10233','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted — O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere,<br/>"O Lord Jesus!" O what a name!<br/>',NULL,44168,8);
INSERT INTO stanza VALUES('T10233','5','We will call upon the Lord, who''s worthy of our praise;<br/>Thus our grateful hearts in worship we to Him may raise.<br/>We are those who call upon His name in every place<br/>With all the saints who from a pure heart call and taste His grace.<br/>',NULL,44169,9);
INSERT INTO stanza VALUES('T10233','chorus','Jesus! O what a name!<br/>O Lord Jesus! Life-giving name!<br/>Name victorious, name all-glorious,<br/>Name exalted — O what a name!<br/>Jesus! Strengthening name!<br/>O Lord Jesus! Comforting name!<br/>Name to breathe in prayer, calling everywhere,<br/>"O Lord Jesus!" O what a name!<br/>',NULL,44170,10);
INSERT INTO stanza VALUES('T10235','1','O Lord Jesus, O Lord Jesus,<br/>O how sweet to call Thy Name;<br/>Sweeter than the wine and honey,<br/>O Lord Jesus, Amen!<br/>',NULL,44171,1);
INSERT INTO stanza VALUES('T10235','2','O Hesus ko! anong tamis<br/>Ang ngalan Mo''y tawagin;<br/>Higit sa alak at pulot,<br/>O Hesus ko, Amen.<br/>',NULL,44172,2);
INSERT INTO stanza VALUES('T10236','1','We have found a simple way for us to really touch the Lord:<br/>All we do is pray four words, O what a grace He does afford!<br/>From our spirit now we say them, and we spread the news abroad,<br/>It''s easy to touch the Lord!<br/>',NULL,44173,1);
INSERT INTO stanza VALUES('T10236','2','Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>Oh Lord, Amen, Hallelujah!<br/>It''s easy to touch the Lord!<br/>',NULL,44174,2);
INSERT INTO stanza VALUES('T10237','1','Whene''er I call Lord Jesus,<br/>Sure it sets my heart aglow;<br/>Just to feel His life arising<br/>That Christ in me may grow.<br/>Just call with us, "Lord Jesus,"<br/>It''s the greatest joy on earth;<br/>And then Christ will come into you,<br/>You will have another birth.<br/>',NULL,44175,1);
INSERT INTO stanza VALUES('T10237','2','Just call with us, "Lord Jesus,"<br/>He will surely set you free;<br/>Though your heart is far, far from Him,<br/>Wherever you may be.<br/>Be simple, call upon Him,<br/>Even at this very hour;<br/>If you call, then He will enter,<br/>Oh, He''s never very far.<br/>',NULL,44176,2);
INSERT INTO stanza VALUES('T10237','3','Just call upon our Savior,<br/>Sure He''ll hear you every time;<br/>All your burdens cast upon Him<br/>And in His arms recline.<br/>For He is our strong fortress,<br/>And our peace, our joy, our rest;<br/>When we taste the grace of Jesus,<br/>Sure we taste the very best.<br/>',NULL,44177,3);
INSERT INTO stanza VALUES('T10237','4','The best is just Himself now,<br/>And Himself He freely gave;<br/>So let''s open up to Him now,<br/>And by His life be saved.<br/>And when He comes to meet us,<br/>As His Bride we''ll ready be;<br/>If today He grows within us,<br/>We shall then His glory see.<br/>',NULL,44178,4);
INSERT INTO stanza VALUES('T10237','1','''Pag Hesus ay tawagin,<br/>Nagningas ang puso ko;<br/>Ang buhay Niyang nasa akin<br/>Lalong lumalago.<br/>Tayo''y tumawag, "Hesus,"<br/>Sa galak ka''y malipos;<br/>Si Kristo''y papasok sa iyo,<br/>May pagkasilang bago.<br/>',NULL,44179,5);
INSERT INTO stanza VALUES('T10237','2','"Hesus," ating tawagin,<br/>Magpapalaya sa iyo,<br/>Anuman iyong saloobin,<br/>Puso ma''y malayo.<br/>Payak ka lang tumawag,<br/>Saan man naroroon;<br/>Buksan ang bibig, tumawag,<br/>Nasa iyo ang Pangino''n.<br/>',NULL,44180,6);
INSERT INTO stanza VALUES('T10237','3','Manliligtas tawagin,<br/>Pinakikinggan tayo,<br/>Ilagak ang iyong pasanin<br/>Sa Taga-aliw mo.<br/>Lakas, galak, pahinga,<br/>At kanlungan natin Siya,<br/>Tikman mo''t mapagkilala<br/>Ganap Niyang pagpapala.<br/>',NULL,44181,7);
INSERT INTO stanza VALUES('T10237','4','Siya''y pinakamainam,<br/>Libreng matanggap mo Siya,<br/>Magbukas ka nang lubusan,<br/>Ligtas sa buhay Niya!<br/>Sa pagdating Niya muli,<br/>Wala tayong pangamba;<br/>Tayo''y mapasa l''walhati<br/>Kung hinog at ganap na.<br/>',NULL,44182,8);
INSERT INTO stanza VALUES('T10238','1','When you say, "Lord!"<br/>You say a lot of things nobody else can say;<br/>When you say, "Lord!"<br/>You say you care enough to only want the King of kings!<br/>For there is nothing more; there''s only something less!<br/>Jesus is all in all; He is the very best.<br/>When you say, "Lord Jesus!"<br/>You have said it all!<br/>',NULL,44183,1);
INSERT INTO stanza VALUES('T10239','1','Calling, "O Lord Jesus!"<br/>Oh, it makes our spirit strong!<br/>We can really touch Him,<br/>And our gloom is turned to song!<br/>Don''t listen to Satan, with all his distraction;<br/>Just turn to your spirit, and spring into action!<br/>Calling, "O Lord Jesus!"<br/>You''ll enjoy Him all day long!<br/>',NULL,44184,1);
INSERT INTO stanza VALUES('T10239','2','O Pangino''ng Hesus!<br/>''Spiritu''y napalakas!<br/>Mahihipo nga Siya,<br/>Panglaw magiging saya!<br/>Huwag dinggin ang diyablo sa pang''gulo nito<br/>Baling sa ''spiritu, takot mo''y tatakbo!<br/>O Pangino''ng Hesus!<br/>Buong araw tamasa mo!<br/>',NULL,44185,2);
INSERT INTO stanza VALUES('T10240','1','"O Lord Jesus" is the way<br/>To eat Jesus all the day;<br/>When we call we take Him in<br/>And our spirits filled with Him.<br/>',NULL,44186,1);
INSERT INTO stanza VALUES('T10240','chorus','Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Lord Jesus! all the day.<br/>',NULL,44187,2);
INSERT INTO stanza VALUES('T10240','2','"O Lord Jesus" is the way<br/>We will never go astray.<br/>Call His name in day or night<br/>He will rescue you with might.<br/>',NULL,44188,3);
INSERT INTO stanza VALUES('T10240','chorus','Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Lord Jesus! all the day.<br/>',NULL,44189,4);
INSERT INTO stanza VALUES('T10240','3','Turn from soul to spirit now;<br/>"O Lord Jesus" — that is how.<br/>Turn yourself to Him and say,<br/>"O Lord Jesus" all the day.<br/>',NULL,44190,5);
INSERT INTO stanza VALUES('T10240','chorus','Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Lord Jesus! all the day.<br/>',NULL,44191,6);
INSERT INTO stanza VALUES('T10240','4','Calling thus we''re filled with Christ.<br/>As the spirit and the life.<br/>Calling we express our love<br/>To the Lord all else above.<br/>',NULL,44192,7);
INSERT INTO stanza VALUES('T10240','chorus','Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Call, O Lord Jesus!<br/>Lord Jesus! all the day.<br/>',NULL,44193,8);
INSERT INTO stanza VALUES('T10240','1','"Poong Hesus" tawagin,<br/>Upang Siya ay kainin.<br/>Tawagin Siya''t tanggapin,<br/>''Spiritu ay punuin.<br/>',NULL,44194,9);
INSERT INTO stanza VALUES('T10240','chorus','Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Buong araw, tawagin.<br/>',NULL,44195,10);
INSERT INTO stanza VALUES('T10240','2','"Poong Hesus" ang daan,<br/>Di maligaw kailanman.<br/>Gabi''t araw tawagin,<br/>Siya''y magliligtas sa ''tin.<br/>',NULL,44196,11);
INSERT INTO stanza VALUES('T10240','chorus','Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Buong araw, tawagin.<br/>',NULL,44197,12);
INSERT INTO stanza VALUES('T10240','3','Baling na sa ''spiritu,<br/>Hesus ang tawagin mo,<br/>Baling tungo sa Kanya,<br/>Palaging tawagin Siya.<br/>',NULL,44198,13);
INSERT INTO stanza VALUES('T10240','chorus','Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Buong araw, tawagin.<br/>',NULL,44199,14);
INSERT INTO stanza VALUES('T10240','4','Kristo, tayo''y mapuno<br/>Ng buhay, espiritu.<br/>Pagtawag ay pakita.<br/>Pag-ibig ko sa Kanya.<br/>',NULL,44200,15);
INSERT INTO stanza VALUES('T10240','chorus','Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Pangino''ng Hesus!<br/>Buong araw, tawagin.<br/>',NULL,44201,16);
INSERT INTO stanza VALUES('T10241','1','I just keep calling O Lord as I walk along,<br/>I just keep calling O Lord and He gives a song;<br/>Though the storm clouds darken the sky<br/>o''er the heav''nly trail,<br/>I just keep calling O Lord, He will never fail!<br/>He''s a faithful Friend, such a faithful Friend,<br/>I can count on Him to the very end;<br/>Though the storm clouds darken the sky<br/>o''er the heav''nly trail,<br/>I just keep calling O Lord, He will never fail!<br/>',NULL,44202,1);
INSERT INTO stanza VALUES('T10241','2','Aking tatawagin Ka, O Panginoon,<br/>Aking tatawagin Ka, O Panginoon;<br/>Magdilim man ang ulap sa kalangitan,<br/>Nagbibigay-awitin sa kalungkutan.<br/>Ikaw ang tapat kong Kaibigan,<br/>Kaibigan kong maaasahan;<br/>Magdilim man ang ulap sa kalangitan,<br/>Di ako bibiguin magpakailanman.<br/>',NULL,44203,2);
INSERT INTO stanza VALUES('T10242','1','Say O Lord Jesus early in the morning,<br/>Say O Lord Jesus even at noon time,<br/>Say O Lord Jesus late in the evening,<br/>Say O Lord Jesus all the day long.<br/>In your spirit He is there;<br/>Waste no time to find Him where.<br/>Praise the Lord! (Praise the Lord)<br/>So. . . . . . . . . . . . . . .<br/>Turn to your spirit; you''ll enjoy His blessing.<br/>Groan in your spirit; you will touch Him soon,<br/>Pray in your spirit; He will keep you burning.<br/>Stay in your spirit; like Him you''ll be strong.<br/>Through His life abundant share,<br/>We His likeness soon shall bear.<br/>Glory, Hallelujah, Glory to His Name.<br/>Glory, Hallelujah, Glory to His Name.<br/>',NULL,44204,1);
INSERT INTO stanza VALUES('T10242','2','"Pangino''ng Hesus" sa umaga''y sabi,<br/>"Pangino''ng Hesus" at sa tanghali,<br/>"Pangino''ng Hesus" maging sa gabi,<br/>Panginoo''y Hesus, Oo palagi!<br/>Sa ''spiritu, Siya''y nandyan;<br/>Huwag nang hanapin kung sa''n.<br/>Purihin! (Purihin!)<br/>O. . . . . . . . . . . . . . .<br/>Sa ''spiritu mo, Siya''y iyong matamasa<br/>Maghibik doon, mahipo mo Siya<br/>Manalangin do''n, paningasin ka Niya,<br/>Manatili do''n, ''lakas gaya Niya.<br/>Sa mayaman Niyang buhay,<br/>Larawan Niya''y mataglay.<br/>Gloria, Aleluya sa Kanyang Ngalan<br/>Gloria, Aleluya sa Kanyang Ngalan.<br/>',NULL,44205,2);
INSERT INTO stanza VALUES('T10243','1','Do you know what time it is?<br/>Time to say "O Lord!"<br/>God''s Word says redeem the time;<br/>We''re all of one accord.<br/>Day time or night time;<br/>Dark time or light time;<br/>Anytime is right time to say "O Lord!"<br/>',NULL,44206,1);
INSERT INTO stanza VALUES('T10243','2','Ano ang oras ngayon?<br/>Oras pagtawag—<br/>"O Panginoon<br/>Amen Aleluya!"<br/>Araw at gabi<br/>Anumang oras<br/>Ay wastong oras upang tumawag.<br/>',NULL,44207,2);
INSERT INTO stanza VALUES('T10244','1','O let us call together, Lord Jesus! Lord Jesus!<br/>O Lord, Amen, Hallelujah! Amen, Praise the Lord!<br/>O Lord, Amen, Hallelujah! Amen, Hallelujah!<br/>O Lord, Amen, Hallelujah! Amen, Praise the Lord!<br/>',NULL,44208,1);
INSERT INTO stanza VALUES('T10245','1','You can smile, when you can say, "O Lord,"<br/>You can smile, when you can praise the Lord,<br/>You can smile, when it''s cloudy or fair,<br/>You can smile anytime, anywhere.<br/>',NULL,44209,1);
INSERT INTO stanza VALUES('T10246','1','Christ is the good land, whom God has promised,<br/>In Him we conquer, routing the en''my,<br/>Foll''wing our Captain, rest in our portion,<br/>This land is for you and for me.<br/>',NULL,44210,1);
INSERT INTO stanza VALUES('T10246','2','The high-walled city, you did not build it,<br/>The house full of goods, you did not fill it,<br/>The well of water, you did not dig it,<br/>Olives and grapes, you did not plant.<br/>',NULL,44211,2);
INSERT INTO stanza VALUES('T10246','3','There''s fountains, rivers, streams in the valley,<br/>Wheat, barley, fruit trees, with oil and honey,<br/>In this land dwelling, we never shall want,<br/>This land is rich in iron and brass.<br/>',NULL,44212,3);
INSERT INTO stanza VALUES('T10246','4','Rejoice together, and sing in Zion,<br/>Let''s go on forward, into His goodness,<br/>New wine and fine crops abundant produce,<br/>This land is really rich and full.<br/>',NULL,44213,4);
INSERT INTO stanza VALUES('T10246','5','Christ is my portion, also your portion,<br/>We all can share Him, without distinction,<br/>Our inheritance, we cannot measure,<br/>All things are for you and for me.<br/>',NULL,44214,5);
INSERT INTO stanza VALUES('T10246','6','This bountiful land — enlarged enjoyment,<br/>And everywhere there''s oil, milk and honey,<br/>O''erflowing blessing, just taste and you''ll see,<br/>Our Christ is really the good land.<br/>',NULL,44215,6);
INSERT INTO stanza VALUES('T10246','7','The Word became flesh, despised by all men,<br/>He conquered death and ascended on high,<br/>Glory and honor, His crown forever,<br/>This good land is in us today.<br/>',NULL,44216,7);
INSERT INTO stanza VALUES('T10246','8','Let us all labor, on Christ within us,<br/>And bring the harvest, to God as off''ring,<br/>Thus Christ was offered, satisfied God and men,<br/>We''ll sing His praises forever.<br/>',NULL,44217,8);
INSERT INTO stanza VALUES('T10246','9','O praise the Lord, Christ is now my good land,<br/>O praise the Lord, Christ is now your good land,<br/>O Hallelujah, such glorious good land,<br/>We dwell in Him, Christ our good land.<br/>',NULL,44218,9);
INSERT INTO stanza VALUES('T10246','1','Kristo''y mabuting lupang pangako<br/>Umasa sa Kanya diyablo''y talo;<br/>Kapitan sundan, kamtin pahinga<br/>Para sa atin ang lupa.<br/>',NULL,44219,10);
INSERT INTO stanza VALUES('T10246','2','Pader matayog di mo tinayo,<br/>Bahay puno nga, di ka nagpuno;<br/>Balon may tubig di ka naghukay,<br/>Di ka nagtanim, may ubas.<br/>',NULL,44220,11);
INSERT INTO stanza VALUES('T10246','3','May bukal, ilog, batis sa libis,<br/>Trigo''t sebada, pulot at langis;<br/>Lupa''y may bakal, bundok may tanso,<br/>Di-salat ang lupang ito.<br/>',NULL,44221,12);
INSERT INTO stanza VALUES('T10246','4','Tayo''y magalak aawit sa Sion,<br/>Pasok sa lupa tayo''y susulong,<br/>Butil at alak anong sagana,<br/>Mayaman nga itong lupa!<br/>',NULL,44222,13);
INSERT INTO stanza VALUES('T10246','5','Si Kristo''y akin, si Kristo ay iyo,<br/>Tamasahing magkasama tayo;<br/>Ang pamana natin di masukat<br/>Para sa iyo''t akin lahat.<br/>',NULL,44223,14);
INSERT INTO stanza VALUES('T10246','6','Mayamang lupa, tamasa rito,<br/>Langis, gatas, pulot bawa''t dako.<br/>Makita Kristo''y mabuting lupa<br/>Tikman umapaw pagpala.<br/>',NULL,44224,15);
INSERT INTO stanza VALUES('T10246','7','Naging laman Siya, dinanas dusa,<br/>Namatay, nabuhay, umakyat na<br/>L''walhati sa Kanya''y nagputong din<br/>Siyang lupa sa loob natin.<br/>',NULL,44225,16);
INSERT INTO stanza VALUES('T10246','8','Kristong nasa lo''b, tayo''y magpagal<br/>Nang ang Kristo sa Diyos maitanghal;<br/>Bilang handog sa Diyos mas''yahan Siya,<br/>Tayo''y pupuri sa Kanya.<br/>',NULL,44226,17);
INSERT INTO stanza VALUES('T10246','9','Purihin ang Diyos, Kristo''y lupa ko,<br/>Purihin ang Diyos, Kristo''y lupa mo;<br/>O Aleluya, l''walhating lupa;<br/>Nanahan kay Kristong lupa!<br/>',NULL,44227,18);
INSERT INTO stanza VALUES('T10247','1','What a good land, what a rich land,<br/>God has given unto us!<br/>Valleys, mountains, springs and fountains—<br/>Hallelujah, glorious!<br/>',NULL,44228,1);
INSERT INTO stanza VALUES('T10247','2','What a good land, what a rich land,<br/>God has given unto us!<br/>Milk and honey without money—<br/>What a bargain, glorious!<br/>',NULL,44229,2);
INSERT INTO stanza VALUES('T10247','3','What a good land, what a rich land,<br/>God has given unto us!<br/>Vines and fig trees, all our hearts'' please—<br/>Rich supplies, and all for us.<br/>',NULL,44230,3);
INSERT INTO stanza VALUES('T10247','4','What a good land, what a rich land,<br/>God has given unto us!<br/>Grain and fresh oil, all for our toil,<br/>What a prospect, glorious!<br/>',NULL,44231,4);
INSERT INTO stanza VALUES('T10247','5','Let us labor, let us labor,<br/>On the land He''s given us,<br/>Labor hourly, labor pow''rfully,<br/>Reap a harvest glorious!<br/>',NULL,44232,5);
INSERT INTO stanza VALUES('T10247','6','In the meetings, in the meetings,<br/>At the feast so glorious,<br/>With a full heart, share the best part,<br/>Of the harvest gained by us.<br/>',NULL,44233,6);
INSERT INTO stanza VALUES('T10247','7','Hallelujah, hallelujah,<br/>For the land God''s given us!<br/>What employment, what enjoyment!<br/>Hallelujah, glorious!<br/>',NULL,44234,7);
INSERT INTO stanza VALUES('T10247','1','Anong yaman ng lupain<br/>''Binigay ng Diyos sa ''tin!<br/>Libis, bundok, bukal, balon—<br/>Kay luwalhati roon!<br/>',NULL,44235,8);
INSERT INTO stanza VALUES('T10247','2','Anong yaman ng lupain<br/>''Binigay ng Diyos sa ''tin!<br/>Gatas, pulot walang bayad,<br/>Alok tanggapin agad!<br/>',NULL,44236,9);
INSERT INTO stanza VALUES('T10247','3','Anong yaman ng lupain<br/>''Binigay ng Diyos sa ''tin!<br/>Puso''y lugod, ubas, igos,<br/>Masaganang panustos.<br/>',NULL,44237,10);
INSERT INTO stanza VALUES('T10247','4','Anong yaman ng lupain,<br/>''Binigay ng Diyos sa ''tin!<br/>Butil, langis para sa ''tin<br/>May gloria nating kamtin.<br/>',NULL,44238,11);
INSERT INTO stanza VALUES('T10247','5','Magpagal nga, magpagal nga,<br/>Sa lupang ''binigay Niya,<br/>Magpagal nga, oras-oras.<br/>Mag-ani''ng buong lakas.<br/>',NULL,44239,12);
INSERT INTO stanza VALUES('T10247','6','Mal''walhating kapistahan<br/>Ang mga pagpupulong,<br/>Pinakamabuti''y hain<br/>Ng aning tamo natin.<br/>',NULL,44240,13);
INSERT INTO stanza VALUES('T10247','7','Aleluya, aleluya,<br/>Sa lupang ''binigay Niya!<br/>Anong gawang natamasa!<br/>Maringal, aleluya!<br/>',NULL,44241,14);
INSERT INTO stanza VALUES('T10248','1','This land is ours, God gave this land to us;<br/>Christ is, Christ is the Land He gave.<br/>''Tis with the church as one, to which we all must come,<br/>Leaving the world behind, our souls brought through the maze.<br/>',NULL,44242,1);
INSERT INTO stanza VALUES('T10248','2','Come on, come on, let''s take this land for aye;<br/>Come on, let''s walk in Christ today;<br/>Now we must take the stand that we will work the Land,<br/>That by the increase grown we''ll make His coming known.<br/>',NULL,44243,2);
INSERT INTO stanza VALUES('T10248','3','We''ll see, we''ll see, Jesus so rich, so sweet,<br/>So full the church becomes complete.<br/>Reality we''ll know, and God true worship show.<br/>His person then will be the Thrilling One we see.<br/>',NULL,44244,3);
INSERT INTO stanza VALUES('T10251','1','Walking in this Good Land,<br/>How it makes our spirit strong!<br/>Working on the Good Land,<br/>Christ enjoying all day long.<br/>His riches, His fullness, and all His power<br/>Are ours to experience hour by hour!<br/>Living in the Good Land—<br/>Christ is now our all in all.<br/>',NULL,44245,1);
INSERT INTO stanza VALUES('T10252','1','Lab''ring on the Good Land, lab''ring in the morning,<br/>Lab''ring through the noontime to the early eve,<br/>Lab''ring for a harvest, reaping all the produce,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,44246,1);
INSERT INTO stanza VALUES('T10252','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>',NULL,44247,2);
INSERT INTO stanza VALUES('T10252','2','Reaping wheat and barley, death and resurrection,<br/>Though the loss sustained our old man often grieves;<br/>But in life abundant, life in resurrection,<br/>Coming to the meeting, bringing in the sheaves.<br/>',NULL,44248,3);
INSERT INTO stanza VALUES('T10252','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>',NULL,44249,4);
INSERT INTO stanza VALUES('T10252','3','Grain and wine and fresh oil — bringing in the surplus<br/>Of the wheat and barley, vine and olive trees:<br/>Wine to cause rejoicing, oil to give anointing,<br/>Bringing in the top tenth, bringing in the sheaves.<br/>',NULL,44250,5);
INSERT INTO stanza VALUES('T10252','chorus','Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>Bringing in the sheaves, bringing in the sheaves,<br/>Here we are rejoicing, bringing in the sheaves!<br/>',NULL,44251,6);
INSERT INTO stanza VALUES('T10253','1','Yes, we are the people — together enjoying<br/>The oneness of living, the joy of one life;<br/>We''re living by Jesus, we''re living by Christ!<br/>There is love between these brothers and sisters—<br/>All, all over this land! Oo-Oo-Oo. . .<br/>',NULL,44252,1);
INSERT INTO stanza VALUES('T10254','beginning-note','Jeremiah 31:12<br/>',NULL,44253,1);
INSERT INTO stanza VALUES('T10254','1','Therefore they shall come and sing in the height of Zion,<br/>And shall flow together to the goodness of the Lord;<br/>For the wheat, and for wine, and for oil, and for the young,<br/>for the young of the flock and of the herd;<br/>And their soul shall be as a watered garden;<br/>And they shall not sorrow any more at all.<br/>',NULL,44254,2);
INSERT INTO stanza VALUES('T10303','beginning-note','Song of Songs 3-4<br/>',NULL,44255,1);
INSERT INTO stanza VALUES('T10303','1','Many times at night on my bed,<br/>I sought Him whom my soul delighted;<br/>I sought, but He could not be found,<br/>Thus, I wander around.<br/>O brethren will you please tell me so,<br/>Where didst my heart most beloved go?<br/>That I may run and bring Him back,<br/>Thus, to enjoy His love without lack.<br/>Brethren lead me, they are my guide,<br/>That I in true fellowship abide;<br/>Lo! my love is just by my side,<br/>Never from me doth slide.<br/>',NULL,44256,2);
INSERT INTO stanza VALUES('T10303','2','I, th'' object of His love He took,<br/>Filled with Spirit as pillars of smoke.<br/>Thy death, resurrection conform,<br/>Myrrh and sweet fragrance borne.<br/>As His palanquin I am blest,<br/>That through me Thou mayest move and rest.<br/>As one of Israel''s men of might,<br/>With sword I combat the fear at night.<br/>Help from valiant men around me,<br/>Make me feel safe and securely be.<br/>Thy unlimited love show me,<br/>Conform to Thy ''mage be.<br/>',NULL,44257,3);
INSERT INTO stanza VALUES('T10303','3','Mountain of myrrh I long to go,<br/>All that I am in death I forego;<br/>Hill of frankincense I ascend,<br/>Shadows evanescent.<br/>Since my fairness Thou admitted,<br/>Enjoying my love hast completed;<br/>One look from me ravished Thy heart,<br/>All spices can''t match my oils in part.<br/>I''m willing to Lebanon see,<br/>His power of ascendency;<br/>I''m willing in Hermon to dwell,<br/>The cross'' vict''ry declare.<br/>',NULL,44258,4);
INSERT INTO stanza VALUES('T10303','4','Oh, may honey from my lips drop,<br/>Thou may enjoy the sweetness of love;<br/>May my living fill with sweet smell,<br/>Like Lebanon that''s swell!<br/>Oh Lord, I beg that Thou come quickly,<br/>My whole being occupied by Thee.<br/>A garden closed, a spring shut up,<br/>All for Thy fountain they were closed up.<br/>Awake, North wind and come, thou South;<br/>Blow ''pon my gard''n let spices flow out,<br/>Let my beloved come to His gard''n,<br/>To enjoy all therein.<br/>',NULL,44259,5);
INSERT INTO stanza VALUES('T10305','1','Jesus Lord, Jesus Lord<br/>How we long to touch Thee.<br/>More and more, More and more<br/>That Thou may grow within us,<br/>"Blossom of Gold" may You bloom and grow,<br/>Bloom and grow forever. . . . . .<br/>All will see, all will know<br/>You are Lord within us.<br/>',NULL,44260,1);
INSERT INTO stanza VALUES('T10306','1','Jesus, Jesus,<br/>Can I tell You how I feel?<br/>You have given all Your riches,<br/>I love You so.<br/>',NULL,44261,1);
INSERT INTO stanza VALUES('T10306','2','Hesus, Hesus,<br/>Damdamin ko ay ito.<br/>''Binigay Mo lahat sa ''kin,<br/>Mahal Kita.<br/>',NULL,44262,2);
INSERT INTO stanza VALUES('T10308','1','Lord, there''s always been one person<br/>Like Abraham who ran to meet You.<br/>Samuel, he ministered<br/>And David had a heart full of praise,<br/>But You want many more.<br/>',NULL,44263,1);
INSERT INTO stanza VALUES('T10308','2','Lord, we want to be those people<br/>Who minister and refresh You,<br/>Meet Your need, and wash Your feet,<br/>That satisfy Your heart''s desire<br/>And be a friend to You.<br/>What can we do?<br/>',NULL,44264,2);
INSERT INTO stanza VALUES('T10308','chorus','We can call, "O Lord,"<br/>We can praise Your name,<br/>Turn our heart to You,<br/>Let You rule and reign.<br/>Lord, a single heart that''s true,<br/>That''s what we desire.<br/>',NULL,44265,3);
INSERT INTO stanza VALUES('T10308','3','Lord, You''ve shown You''re rich in mercy<br/>To those saints who stand together<br/>In Your plan, one New Man.<br/>So grant us a single heart;<br/>A heart that just loves You,<br/>A heart that''s true.<br/>',NULL,44266,4);
INSERT INTO stanza VALUES('T10308','chorus','We can call, "O Lord,"<br/>We can praise Your name,<br/>Turn our heart to You,<br/>Let You rule and reign.<br/>Lord, a single heart that''s true,<br/>That''s what we desire—<br/>A heart for You.<br/>',NULL,44267,5);
INSERT INTO stanza VALUES('T10309','1','Oh, my Lord, I give myself to You—<br/>There''s nothing else to do,<br/>My world is over now!<br/>All the world lies in the evil one,<br/>But I''m the Father''s son;<br/>His love has met my need.<br/>',NULL,44268,1);
INSERT INTO stanza VALUES('T10309','chorus','Lord, I give myself to You completely;<br/>Lord, I need to sense the flow of life.<br/>Jesus, Jesus, Jesus, Jesus, Jesus,<br/>I love You, I really do!<br/>',NULL,44269,2);
INSERT INTO stanza VALUES('T10309','2','Lord, I long to have You flow in me,<br/>My heart could never be<br/>Content with less than You.<br/>Deep within, my heart cries out to You,<br/>Hungry and thirsty too<br/>For that sweet flow of life.<br/>',NULL,44270,3);
INSERT INTO stanza VALUES('T10309','chorus','Lord, I give myself to You completely;<br/>Lord, I need to sense the flow of life.<br/>Jesus, Jesus, Jesus, Jesus, Jesus,<br/>I love You, I really do!<br/>',NULL,44271,4);
INSERT INTO stanza VALUES('T10309','3','Shining One, in me direct Thy rays,<br/>Shine through all false displays;<br/>Let me not be deceived.<br/>Lord, I know, I need Thy light to shine.<br/>How else can I be Thine?<br/>You must enlighten me.<br/>',NULL,44272,5);
INSERT INTO stanza VALUES('T10309','chorus','Lord, I give myself to You completely;<br/>Lord, I need to sense the flow of life.<br/>Jesus, Jesus, Jesus, Jesus, Jesus,<br/>I love You, I really do!<br/>',NULL,44273,6);
INSERT INTO stanza VALUES('T10309','4','Cleanse me now; don''t let one sin remain.<br/>I cannot be the same;<br/>Your life is all I need.<br/>Oh, forgive my failure and my sin.<br/>Make me so clean within<br/>So You can flow in me.<br/>',NULL,44274,7);
INSERT INTO stanza VALUES('T10309','chorus','Lord, I give myself to You completely;<br/>Lord, I need to sense the flow of life.<br/>Jesus, Jesus, Jesus, Jesus, Jesus,<br/>I love You, I really do!<br/>',NULL,44275,8);
INSERT INTO stanza VALUES('T10309','5','Oh the joy! To have that life and peace!<br/>Darkness and death have ceased<br/>In Thy sweet presence, Lord.<br/>Oh, the joy from fellowship so real!<br/>Even the heav''ns, I feel,<br/>Cannot compare with this.<br/>',NULL,44276,9);
INSERT INTO stanza VALUES('T10309','chorus','Lord, I give myself to You completely;<br/>How I praise You for the flow of life!<br/>Jesus, Jesus, Jesus, Jesus, Jesus,<br/>I love You, I really do!<br/>',NULL,44277,10);
INSERT INTO stanza VALUES('T10310','1','I belong to Jesus; He sets me free,<br/>And He keeps me singing sweet melody,<br/>Fills my life with sunshine,<br/>Whate''er betide I belong to Jesus,<br/>He''s by my side.<br/>',NULL,44278,1);
INSERT INTO stanza VALUES('T10311','beginning-note','Exodus 30:22-25<br/>',NULL,44279,1);
INSERT INTO stanza VALUES('T10311','1','Wonderful, wonderful, Jesus is to us—<br/>Cinnamon, Cassia, Myrrh and Calamus!<br/>Ointment now, in our hearts ever painting us,<br/>Compound Spirit, God and man, how glorious!<br/>',NULL,44280,2);
INSERT INTO stanza VALUES('T10312','1','What a happy day<br/>When I no more could turn away,<br/>When Jesus took my heart from the black of night<br/>Into the Kingdom of His light.<br/>',NULL,44281,1);
INSERT INTO stanza VALUES('T10312','2','Now my life''s begun,<br/>The "real life" that''s in the Son,<br/>No more am I enthralled by earth''s empty dreams;<br/>Deep in me flows a living stream.<br/>',NULL,44282,2);
INSERT INTO stanza VALUES('T10312','3','As I turn to Him<br/>He fills me with His life within.<br/>His life becomes my life in reality;<br/>Oh, hallelujah, He''s in me!<br/>',NULL,44283,3);
INSERT INTO stanza VALUES('T10312','4','I just love You, Lord,<br/>With other loves, You break the cord.<br/>You''ll be my life for all eternity;<br/>You are the only One for me.<br/>',NULL,44284,4);
INSERT INTO stanza VALUES('T10313','1','I have often called on the Lord before,<br/>But I never really touched Him quite like this before;<br/>Somehow, suddenly, what a Christ I see—<br/>O Lord Jesus, my Lord, I love You!<br/>',NULL,44285,1);
INSERT INTO stanza VALUES('T10313','2','All the cares of the earth, they don''t bother me,<br/>For I''ve found the living, loving One reality.<br/>Let the world go by, Just as long as I<br/>Can be here in the church loving Him.<br/>',NULL,44286,2);
INSERT INTO stanza VALUES('T10313','chorus','Oh, Jesus, wonderful Jesus,<br/>What a Lord You are to me!<br/>Oh, how I love You, Lord Jesus;<br/>Just to touch Yourself is more than ecstasy!<br/>',NULL,44287,3);
INSERT INTO stanza VALUES('T10313','chorus','[All the cares of the earth, they don''t bother me,<br/>For I''ve found the living, loving One reality.<br/>Let the world go by, Just as long as I<br/>Can be here in the church loving Him.]<br/><!--(Repeat stanza 2)--><br/>',NULL,44288,4);
INSERT INTO stanza VALUES('T10314','beginning-note','Psalm 73<br/>',NULL,44289,1);
INSERT INTO stanza VALUES('T10314','1','Till I went into the sanctuary of God,<br/>''Twas then understood I their end;<br/>Till I went into the sanctuary of God,<br/>''Twas then understood I their end.<br/>',NULL,44290,2);
INSERT INTO stanza VALUES('T10314','2','I saw the prosperity of the wicked,<br/>As for me, my feet were almost gone;<br/>When I thought about this, I was afflicted.<br/>',NULL,44291,3);
INSERT INTO stanza VALUES('T10314','3','Thus my soul was grieved, and I was pricked in my heart,<br/>Foolish and ignorant my part.<br/>Thus my soul was grieved, and I was pricked in my heart,<br/>Foolish and ignorant my part.<br/>',NULL,44292,4);
INSERT INTO stanza VALUES('T10314','4','Surely Thou settest them in slippery plane,<br/>Thou castest them down to destruction;<br/>And in a moment their pride was turned to vain.<br/>',NULL,44293,5);
INSERT INTO stanza VALUES('T10314','5','Thou holdest my right hand, guide me with Thy counsel,<br/>And will receive me to glory.<br/>Thou holdest my right hand, guide me with Thy counsel,<br/>And will receive me to glory.<br/>',NULL,44294,6);
INSERT INTO stanza VALUES('T10314','6','Whom have I in heaven besides Thee, O Lord!<br/>And there''s none upon earth that I desire;<br/>Thou art my strength and portion fore''er aspire.<br/>',NULL,44295,7);
INSERT INTO stanza VALUES('T10315','1','It''s a lovely, lovely name,<br/>The name of Jesus,<br/>It''s a lovely, lovely name,<br/>From heaven above.<br/>Scatt''ring clouds of doubts and fear,<br/>Changing the saddened heart to cheer;<br/>It''s a lovely, lovely name,<br/>Jesus, my Lord.<br/>',NULL,44296,1);
INSERT INTO stanza VALUES('T10316','1','All anxiety and seeking gone,<br/>When His love saturates me;<br/>His love covers, envelops me,<br/>Leads me to be lost in Him.<br/>As I behold His full glory,<br/>His shining face full of love;<br/>I can''t help but pour out my love,<br/>Be one forever with Him.<br/>All anxiety and seeking gone,<br/>When His love saturates me;<br/>His love covers, envelops me,<br/>Leads me to be lost in Him.<br/>',NULL,44297,1);
INSERT INTO stanza VALUES('T10316','2','As we are living in His love,<br/>Mutual-dependent we''ll be;<br/>His love binds us very tightly,<br/>"Love" causes us ne''er to part.<br/>When His love encircles ''pon us,<br/>O how sweet and dear it is;<br/>Thus we live together in love,<br/>Our hearts knit to become one.<br/>As we are living in His love,<br/>Mutual-dependent we''ll be;<br/>His love binds us very tightly,<br/>"Love" causes us ne''er to part.<br/>',NULL,44298,2);
INSERT INTO stanza VALUES('T10317','1','I simply open my heart to Thee,<br/>O Lord, come into me.<br/>I simply open my heart to Thee,<br/>O Lord, come into me.<br/>',NULL,44299,1);
INSERT INTO stanza VALUES('T10317','2','I desire my love to be pure for Thee,<br/>Do live in me — my plea.<br/>I desire my love to be pure for Thee,<br/>Do live in me — my plea.<br/>',NULL,44300,2);
INSERT INTO stanza VALUES('T10317','3','O Lord, a living Person Thou art,<br/>Dwelling e''er in my heart.<br/>O Lord, a living Person Thou art,<br/>Dwelling e''er in my heart.<br/>',NULL,44301,3);
INSERT INTO stanza VALUES('T10317','4','I''m enjoying Thee in my spirit,<br/>And by Thy life I live.<br/>I''m enjoying Thee in my spirit,<br/>And by Thy life I live.<br/>',NULL,44302,4);
INSERT INTO stanza VALUES('T10317','5','"Amen, Lord," I''m restfully saying,<br/>Fill Thou my whole being.<br/>"Amen, Lord," I''m restfully saying,<br/>Fill Thou my whole being.<br/>',NULL,44303,5);
INSERT INTO stanza VALUES('T10318','1','I''d rather have Jesus than silver or gold,<br/>I''d rather be His than have riches untold;<br/>I''d rather have Jesus than houses or lands,<br/>I''d rather be led by His nail-pierced hands.<br/>',NULL,44304,1);
INSERT INTO stanza VALUES('T10318','chorus','Than to be the king of a vast domain,<br/>And be held in sin''s dread sway;<br/>I''d rather have Jesus than anything<br/>This world affords today.<br/>',NULL,44305,2);
INSERT INTO stanza VALUES('T10318','2','I''d rather have Jesus than men''s applause,<br/>I''d rather be faithful to His dear cause;<br/>I''d rather have Jesus than world-wide fame,<br/>I''d rather be true to His holy name.<br/>',NULL,44306,3);
INSERT INTO stanza VALUES('T10318','chorus','Than to be the king of a vast domain,<br/>And be held in sin''s dread sway;<br/>I''d rather have Jesus than anything<br/>This world affords today.<br/>',NULL,44307,4);
INSERT INTO stanza VALUES('T10319','1','Simply loving everyday;<br/>Loving through a stormy day,<br/>Even when my faith is small,<br/>Loving Jesus, that is all.<br/>',NULL,44308,1);
INSERT INTO stanza VALUES('T10319','chorus','Loving as the moments fly,<br/>Loving as the days go by,<br/>Loving Him whate''er befall,<br/>Loving Jesus, that is all.<br/>',NULL,44309,2);
INSERT INTO stanza VALUES('T10319','2','Brightly doth His Spirit shine<br/>Into this poor heart of mine;<br/>While He leads I cannot fall,<br/>Loving Jesus, that is all.<br/>',NULL,44310,3);
INSERT INTO stanza VALUES('T10319','chorus','Loving as the moments fly,<br/>Loving as the days go by,<br/>Loving Him whate''er befall,<br/>Loving Jesus, that is all.<br/>',NULL,44311,4);
INSERT INTO stanza VALUES('T10319','3','Singing if my way be clear,<br/>Praying if the path be drear;<br/>If in danger, for Him call,<br/>Loving Jesus, that is all.<br/>',NULL,44312,5);
INSERT INTO stanza VALUES('T10319','chorus','Loving as the moments fly,<br/>Loving as the days go by,<br/>Loving Him whate''er befall,<br/>Loving Jesus, that is all.<br/>',NULL,44313,6);
INSERT INTO stanza VALUES('T10319','4','Loving Him while life shall last,<br/>Loving Him till earth is past,<br/>Till His gracious advent call,<br/>Loving Jesus, that is all.<br/>',NULL,44314,7);
INSERT INTO stanza VALUES('T10319','chorus','Loving as the moments fly,<br/>Loving as the days go by,<br/>Loving Him whate''er befall,<br/>Loving Jesus, that is all.<br/>',NULL,44315,8);
INSERT INTO stanza VALUES('T10320','1','Immerse me in Thy love,<br/>Thy fresh, new love,<br/>Soak me in Thy love, Lord,<br/>sweeter than honey be!<br/>Thy love upholds me, Lord,<br/>leads from above,<br/>I on Thy bosom lean, I now feed on Thee.<br/>I desire, O Lord, to feast on Thy love,<br/>To be covered with Thy love.<br/>Thy love as banner is — Thy very self,<br/>For Thou, Lord, art one with Thy love.<br/>',NULL,44316,1);
INSERT INTO stanza VALUES('T10320','2','Thou art my precious love, my only love,<br/>The object of my love, Yes,<br/>dear Lord, Thou alone.<br/>If Thou only give redemption and love.<br/>My heart wilt not be satisfied<br/>this I''ve known.<br/>Thyself Lord is what I desire to gain!<br/>I know all things art in Thee.<br/>Thou full of love, O Lord, the One I seek;<br/>My only treasure, Lord, is Thee.<br/>',NULL,44317,2);
INSERT INTO stanza VALUES('T10321','1','Jesus Lord, You''re our first love;<br/>You''re the One we love the best.<br/>When our heart is loving You,<br/>How we''re filled with Your sweet rest!<br/>Lord, we love You for Yourself,<br/>Not for what You give or do.<br/>Nothing else could e''er compare<br/>With the joy of loving You.<br/>',NULL,44318,1);
INSERT INTO stanza VALUES('T10321','chorus','Lord, we''ve been drawn off by many things;<br/>Now we turn our heart back — how it sings!<br/>We repent of loving other things—<br/>Jesus Lord, You are our first love.<br/>',NULL,44319,2);
INSERT INTO stanza VALUES('T10321','2','Nevermore could we desire<br/>Anything that''s less than You,<br/>And to this we will aspire—<br/>Simply to be filled with You.<br/>Jesus Lord, You''re our first love;<br/>You''re the One we love the best.<br/>When our heart is loving You,<br/>How we''re filled with Your sweet rest!<br/>',NULL,44320,3);
INSERT INTO stanza VALUES('T10321','chorus','Lord, we''ve been drawn off by many things;<br/>Now we turn our heart back — how it sings!<br/>We repent of loving other things—<br/>Jesus Lord, You are our first love.<br/>',NULL,44321,4);
INSERT INTO stanza VALUES('T10322','1','The first time I met You, O Lord,<br/>Floods of joy have filled my heart,<br/>Hallelujah, o''erflowing joy!<br/>Jesus Lord filled my inmost part.<br/>My very first love is the sweetest love,<br/>Jesus, Jesus, You''re my love, stronger than all,<br/>This re-al love reaches even me!<br/>O my sweet love, the most faithful love,<br/>Jesus, Jesus, You''re my love.<br/>',NULL,44322,1);
INSERT INTO stanza VALUES('T10323','1','You, You, You''re always in my heart,<br/>Dream, dream, dreaming of You.<br/>You, You, Your love is sweetest, Lord,<br/>You are the best of them all.<br/>Jesus! Jesus! You are the best of them all,<br/>Jesus! Jesus! You are the best of them all.<br/>',NULL,44323,1);
INSERT INTO stanza VALUES('T10323','2','Love, love, love that''s unlimited,<br/>Sweet, sweet, sweeter than honey.<br/>Flow, flow, flowing through all my heart,<br/>Your love is fresh to me.<br/>Jesus! Jesus! Your love is so fresh to me,<br/>Jesus! Jesus! Your love is so fresh to me.<br/>',NULL,44324,2);
INSERT INTO stanza VALUES('T10324','1','''Tis because Thou draweth me,<br/>I can follow closely by;<br/>Thou the all-inclusiveness,<br/>My experience thereby.<br/>Like a pretty Henna flow''r<br/>In deserts bloss''ming Thou art,<br/>And like the fragrant myrrh too,<br/>Preciously hid in my heart.<br/>Oh, listen to my soft plea,<br/>Hence no other lords have I,<br/>Thy riches enjoyed by me,<br/>By Thy life I grow in Thee.<br/>',NULL,44325,1);
INSERT INTO stanza VALUES('T10324','2','Dahil sa pag-akit Mo,<br/>Ako''y sumunod sa Iyo;<br/>Lahat sumasaklaw Ka,<br/>Aking karanasan pa.<br/>Tulad ng Alhena Ka,<br/>Sa parang namulaklak,<br/>Tulad masamyong mira,<br/>Sa puso''y mahalaga.<br/>O samo ko''y pakinggan,<br/>Panginoon, Ikaw lang,<br/>Iyong yaman tamasa ko,<br/>Sa buhay Mo''y lumago.<br/>',NULL,44326,2);
INSERT INTO stanza VALUES('T10325','1','How can I leave my Lord,<br/>How can I Him forget?<br/>When His unceasing love lingers in me;<br/>All things shall pass away,<br/>But love will ever stay,<br/>To whom will I belong, Lord beside Thee.<br/>',NULL,44327,1);
INSERT INTO stanza VALUES('T10325','2','How can I leave my Lord,<br/>How can I Him forget?<br/>When His fountain of love o''erflows in me;<br/>Saturates my being,<br/>Restoring my being,<br/>To whom will I belong, Lord beside Thee.<br/>',NULL,44328,2);
INSERT INTO stanza VALUES('T10326','1','More time to be with Thee, Lord Jesus,<br/>More time to be with Thee,<br/>More time to know Thyself, Lord Jesus<br/>Thou hast done all for me.<br/>Deep is Thy love, Sweet is Thy peace.<br/>Wondrous Thy grace, sufficient for ev''ry need,<br/>More time to be with Thee, Lord Jesus,<br/>More time to be with Thee.<br/>',NULL,44329,1);
INSERT INTO stanza VALUES('T10327','1','Turn, turn my heart to You;<br/>Lord, I confess my heart is untrue.<br/>Turn, turn my wandering heart;<br/>Lord, unto me Thy love impart.<br/>',NULL,44330,1);
INSERT INTO stanza VALUES('T10327','chorus','Lord, I call,<br/>I call on Thee.<br/>You''re the only One for me!<br/>',NULL,44331,2);
INSERT INTO stanza VALUES('T10327','2','Rich, rich, He''s rich to all,<br/>Rich unto all that call on His name.<br/>Rich, rich, He''s rich, so call;<br/>Now and forever, Jesus the same.<br/>',NULL,44332,3);
INSERT INTO stanza VALUES('T10327','chorus','Lord, I call,<br/>I call on Thee.<br/>You''re the only One for me!<br/>',NULL,44333,4);
INSERT INTO stanza VALUES('T10327','3','Love, love, the love of God<br/>Flows as a river, full to the brim.<br/>Love, love, I''m filled with love,<br/>Crazy in love with Jesus within.<br/>',NULL,44334,5);
INSERT INTO stanza VALUES('T10327','chorus','Lord, I call,<br/>I call on Thee.<br/>You''re the only One for me!<br/>',NULL,44335,6);
INSERT INTO stanza VALUES('T10328','1','If you''re feeling lonely ''cause nobody cares,<br/>Jesus, Jesus, Jesus is there.<br/>If trouble, confusion puts your life in night,<br/>Jesus, Jesus, Jesus is light.<br/>If you turn to Him from within,<br/>Burdens He''ll share;<br/>It matters not who you are,<br/>Jesus will be there.<br/>So don''t wait for answers from someplace, somehow,<br/>Jesus, Jesus, Jesus, it''s now.<br/>If you call on Him from within,<br/>You just can''t miss!<br/>And when problems torment you,<br/>Just remember this:<br/>In all situations this world can afford,<br/>Jesus, Jesus, Jesus is Lord.<br/>',NULL,44336,1);
INSERT INTO stanza VALUES('T10329','1','From my heart comes a melody<br/>Of the One Who gave His life to me.<br/>How can I turn away from Thee;<br/>Lord, I have seen Thy changeless love for me.<br/>Enjoyment so full! Life''s reality!<br/>That''s what You''re to me;<br/>Lord, You have won my heart!<br/>Take my heart, take my whole life too;<br/>Lord, I can''t help giving myself to You.<br/>',NULL,44337,1);
INSERT INTO stanza VALUES('T10329','2','From the day that I first met You,<br/>How could I help falling in love with You?<br/>Emptiness turned life''s pleasures blue;<br/>No earthly love could ever see me through.<br/>Till I turned one day, opened up my heart,<br/>Let Your love flow in<br/>and fill my deepest part.<br/>Now I know, Lord, You''re one with me;<br/>And I can''t help giving myself to Thee.<br/>Lord, I can''t help giving myself to Thee.<br/>',NULL,44338,2);
INSERT INTO stanza VALUES('T10330','1','He''s the One I love in the morning,<br/>He''s the One I love at noon;<br/>He''s the One at evening twilight,<br/>He''s the One at midnight gloom;<br/>He''s the Spirit, lives in my spirit,<br/>He''s the treasure, I''m vessel<br/>For my Lord and me there''ll never be a parting day.<br/>',NULL,44339,1);
INSERT INTO stanza VALUES('T10330','1','Siya''ng aking mahal sa umaga,<br/>Siya rin ang sa tanghali;<br/>Siya rin ang sa dapit-hapon,<br/>Siya rin sa hatinggabi;<br/>Siya''y ''Spiritu sa ''king ''spiritu,<br/>Siya''ng yaman, ''ko''y sisidlan;<br/>Ang Panginoon at ako''y ''di mawawalay.<br/>',NULL,44340,2);
INSERT INTO stanza VALUES('T10331','beginning-note','(Tune: Itik-itik)<br/>',NULL,44341,1);
INSERT INTO stanza VALUES('T10331','1','Oh, Thy love that hast come to meet us,<br/>when we were all fallen and in sin;<br/>Oh, Thy love that hast attracted us,<br/>giving us a new life from within.<br/>Wonderful! It is Thy love<br/>which gives us a new life to begin.<br/>Oh, Thy love has changed my stony heart,<br/>my stubborn, cold, and indiff''rent heart;<br/>Oh, Thy love hast giv''n me a new heart,<br/>that I from Thee never to depart.<br/>',NULL,44342,2);
INSERT INTO stanza VALUES('T10331','2','It is Thy love that daily sustains,<br/>causing us to ever onward go;<br/>It is Thy love that daily maintains,<br/>causing us from vain dreams to forego.<br/>Wonderful! It is Thy love<br/>which gives us strength as we onward go.<br/>It is Thy love that caused Thee to be<br/>the Spirit that lives inside of me;<br/>It is Thy love that worketh in me,<br/>enabling me to labor on Thee.<br/>',NULL,44343,3);
INSERT INTO stanza VALUES('T10331','3','It is Thy love that worketh on me,<br/>cutting, molding Thy image to be;<br/>Thy love measures my circumstances,<br/>to break me that life may flow from me.<br/>Wonderful! It is Thy love<br/>working in me in manifold ways.<br/>Why do I feel at home in the church?<br/>''cause Thy love hast done it all for me.<br/>Why do I enjoy at home so much?<br/>''cause Thy loving hand is real to me.<br/>',NULL,44344,4);
INSERT INTO stanza VALUES('T10331','4','It is Thy love that transformeth me,<br/>this earthen vessel, Thy glory see;<br/>It is Thy love that gives hope to me,<br/>to be raptured and become like Thee.<br/>Wonderful! It is Thy love<br/>that changes me, brings Thee back to me.<br/>Lord, I don''t know, nor can I relate,<br/>the preciousness of Thy love to me;<br/>Lord, in me Thy love doth saturate,<br/>that my whole life may be lost in Thee.<br/>',NULL,44345,5);
INSERT INTO stanza VALUES('T10332','1','Jesus, we love You that you are the vine tree,<br/>Our rich supply of life outflowing;<br/>Scarce can we fathom that we are Your branches<br/>To bear Your fruit, Your fulness showing.<br/>You are our Father, our faithful vine dresser,<br/>Our source, our water, our life, our sunshine;<br/>O Lord, we pour out our being before You,<br/>We love You.<br/>',NULL,44346,1);
INSERT INTO stanza VALUES('T10332','2','Joyful fulfillment, in You we''re abiding,<br/>We find in You sweet rest and oneness;<br/>And even more, in your love we are dwelling,<br/>Responding to Your voice within us.<br/>While in Your presence, Your person enjoying,<br/>So near, so dear, so satisfying;<br/>Nothing we long for, no other desire,<br/>We love You. . . . love You. . . .<br/>',NULL,44347,2);
INSERT INTO stanza VALUES('T10332','3','Father, O Father, You''ve loved Your Son, Jesus,<br/>In Him, Your glory manifested;<br/>Jesus, our Jesus, You also have loved us<br/>With love that death supremely tested.<br/>No greater love could a man have than this—<br/>That You laid down Your life<br/>For Your friends, Your loved ones;<br/>What can we say? We can only adore You,<br/>We love You. . . . love You. . . . we love You.<br/>',NULL,44348,3);
INSERT INTO stanza VALUES('T10333','1','I asked the Lord to comfort me,<br/>When things weren''t going my way;<br/>He said to me, "I will comfort you,<br/>and lift your cares away."<br/>I asked the Lord to walk with me,<br/>when darkness was all that I knew;<br/>He said to me, "Never be afraid,<br/>for I will see you through."<br/>',NULL,44349,1);
INSERT INTO stanza VALUES('T10333','2','I didn''t ask for riches,<br/>He gave me wealth untold—<br/>The moon, the stars, the sun, the sky,<br/>and gave me eyes to behold.<br/>I thank the Lord for everything,<br/>and count my blessings each day;<br/>He came to me when I needed Him,<br/>I only had to pray;<br/>And He''ll come to you, if you ask Him to—<br/>He''s only a prayer away!<br/>',NULL,44350,2);
INSERT INTO stanza VALUES('T10334','1','Jesus, Jesus, Dearer than all to me,<br/>Jesus, Jesus, Fairer than all I see;<br/>Jesus, Jesus, He gives me liberty,<br/>Jesus, Jesus, He''s all the world to me.<br/>',NULL,44351,1);
INSERT INTO stanza VALUES('T10335','1','Oh, I love to hear His voice,<br/>Saying, "You belong to Me,<br/>You are not your own,<br/>With a price you''re bought,<br/>And you''re Mine eternally."<br/>And I love to hear Him say,<br/>"I have saved you by My grace,"<br/>And when I get to glory it will then be grander still,<br/>For I shall see His face.<br/>',NULL,44352,1);
INSERT INTO stanza VALUES('T10335','1','O, ibig kong marinig<br/>Tinig ng aking Hesus,<br/>"Ika''y di sa iyo,<br/>Tinubos kita,<br/>Maging Akin kailanman."<br/>At Kanya ring sinabi:<br/>"Ikaw ay niligtas Ko,"<br/>At nang sa kaluwalhatian lalong dakila,<br/>''Pagka''t magkikita.<br/>',NULL,44353,2);
INSERT INTO stanza VALUES('T10336','1','He loves, He saves, He keeps,<br/>He satisfies this longing heart of mine;<br/>He fills my life to overflowing with His joy and peace divine.<br/>He guides, He guards, He watches over me,<br/>He slumbers not nor sleeps,<br/>For He is my glorious Savior,<br/>And He loves, He saves, He keeps.<br/>',NULL,44354,1);
INSERT INTO stanza VALUES('T10337','1','Whene''er to me Thou open Thy heart,<br/>My heart would throb with resonance.<br/>Caress me with Thy hands, and to Thee,<br/>I''ll share every grievance—<br/>Whither boundary it runs?<br/>Whither boundary it runs?<br/>',NULL,44355,1);
INSERT INTO stanza VALUES('T10337','2','The echo of my heart, I know well<br/>Thou would be delighted to hear;<br/>My sighings and sweet words,<br/>Set in motion Thy blessed heart so dear—<br/>And could not its movement still,<br/>And could not its movement still.<br/>',NULL,44356,2);
INSERT INTO stanza VALUES('T10337','3','My loving heart to Thee, Lord, expressed,<br/>Let it be refined in Thy hand;<br/>My whole being, my heart, fully brought to Thee,<br/>And Thy love to gain.<br/>And its riches fully drain,<br/>And its riches fully drain.<br/>',NULL,44357,3);
INSERT INTO stanza VALUES('T10338','1','The way that He loves is as fair as the day<br/>That blesses my way with light;<br/>The way that He loves is as soft as the breeze<br/>Caressing the trees at night.<br/>So tender and precious is He,<br/>Contented with Jesus I''ll be.<br/>The way that He loves is so thrilling, because—<br/>His love reaches even me.<br/>',NULL,44358,1);
INSERT INTO stanza VALUES('T10339','1','I love You, Jesus, all through the day,<br/>I love You, Jesus, though come what may;<br/>The Holy Spirit — I will obey,<br/>I love You, Jesus, all through the day.<br/>O Jesus, sweet Jesus, what a wonder You are,<br/>You are brighter than the morning star;<br/>You''re fairer, much fairer,<br/>Than the lily that grows by the way,<br/>You''re more precious than silver and gold.<br/>',NULL,44359,1);
INSERT INTO stanza VALUES('T10340','beginning-note','Psalm 73<br/>',NULL,44360,1);
INSERT INTO stanza VALUES('T10340','1','Lord, I am continually with Thee,<br/>Thou hast holden me by my right hand,<br/>Thou shall guide me,<br/>Thou shall guide me with Thy counsel,<br/>And afterward receive me,<br/>Receive me to glory.<br/>',NULL,44361,2);
INSERT INTO stanza VALUES('T10340','2','Whom have I in heaven but Thee?<br/>And there is none upon earth that I<br/>desire beside Thee!<br/>My flesh and my heart faileth,<br/>But God is the strength of my heart,<br/>And my portion forever.<br/>',NULL,44362,3);
INSERT INTO stanza VALUES('T10341','beginning-note','Psalm 19:17-11, 14<br/>',NULL,44363,1);
INSERT INTO stanza VALUES('T10341','1','The law of the Lord is perfect,<br/>Converting the soul;<br/>The testimony of the Lord is sure,<br/>Making wise the simple.<br/>',NULL,44364,2);
INSERT INTO stanza VALUES('T10341','chorus','More to be desired are<br/>they than gold,<br/>Yea, than fine gold;<br/>Sweeter also than honey<br/>and the honeycomb.<br/>',NULL,44365,3);
INSERT INTO stanza VALUES('T10341','2','The statutes of the Lord are right,<br/>Rejoicing the heart;<br/>The commandment of the Lord is pure,<br/>Enlightening the eyes.<br/>',NULL,44366,4);
INSERT INTO stanza VALUES('T10341','chorus','More to be desired are<br/>they than gold,<br/>Yea, than fine gold;<br/>Sweeter also than honey<br/>and the honeycomb.<br/>',NULL,44367,5);
INSERT INTO stanza VALUES('T10341','3','The fear of the Lord is clean,<br/>Enduring forever;<br/>The judgment of the Lord are true,<br/>And righteous altogether.<br/>',NULL,44368,6);
INSERT INTO stanza VALUES('T10341','chorus','More to be desired are<br/>they than gold,<br/>Yea, than fine gold;<br/>Sweeter also than honey<br/>and the honeycomb.<br/>',NULL,44369,7);
INSERT INTO stanza VALUES('T10341','4','Let the words of my mouth,<br/>And the meditation of my heart,<br/>Be acceptable in Thy sight, O Lord,<br/>My strength, and my Redeemer.<br/>',NULL,44370,8);
INSERT INTO stanza VALUES('T10341','chorus','Moreover by them is<br/>Thy servant warned,<br/>Is Thy servant warned;<br/>And in keeping of them<br/>there is great reward.<br/>',NULL,44371,9);
INSERT INTO stanza VALUES('T10342','1','Let the beauty of Jesus be seen in me,<br/>All His wonderful passion and purity;<br/>Oh, Thou Spirit divine,<br/>All my nature refine,<br/>Till the beauty of Jesus be seen in me.<br/>',NULL,44372,1);
INSERT INTO stanza VALUES('T10343','1','My desire — to be like Jesus,<br/>My desire — to be like Him,<br/>His Spirit fills me, His love o''erwhelms me;<br/>In deed and word to be like Him.<br/>',NULL,44373,1);
INSERT INTO stanza VALUES('T10344','1','I have a friend so precious,<br/>So very dear to me;<br/>He loves me with such tender love,<br/>His love''s so fair and sweet;<br/>I could not live apart from Him,<br/>I love to feel Him nigh;<br/>And so we dwell together,<br/>My Lord and I.<br/>',NULL,44374,1);
INSERT INTO stanza VALUES('T10344','2','Sometimes I''m faint and weary,<br/>He knows that I am weak;<br/>And as He bids me lean on Him,<br/>His help I gladly seek;<br/>He leads me in the paths of light,<br/>Beneath a sunny sky;<br/>And so we walk together,<br/>My Lord and I.<br/>',NULL,44375,2);
INSERT INTO stanza VALUES('T10344','3','He knows how much I love Him,<br/>And if I love Him well;<br/>But with what love He loveth me,<br/>My tongue can never tell;<br/>It is an everlasting love,<br/>Much more as days go by;<br/>And so we love each other,<br/>My Lord and I.<br/>',NULL,44376,3);
INSERT INTO stanza VALUES('T10344','4','I tell Him all my sorrows,<br/>I tell Him all my joys;<br/>I tell Him all that pleases me,<br/>I tell Him what annoys;<br/>He tells me what I ought to do,<br/>He tells me how to try;<br/>And so we talk together,<br/>My Lord and I.<br/>',NULL,44377,4);
INSERT INTO stanza VALUES('T10344','5','He knows my heart''s such longing,<br/>Some weary soul to win;<br/>And so He bids me go and speak,<br/>The loving word for Him;<br/>He bids me tell His wondrous love,<br/>And why He came to die;<br/>And so we work together,<br/>My Lord and I.<br/>',NULL,44378,5);
INSERT INTO stanza VALUES('T10344','6','He tells me that His Kingdom<br/>Is not too far from here;<br/>He longs to speed that day to come,<br/>That He would bring me there;<br/>With hope of joy and blessedness,<br/>And glorious throne in sight;<br/>We soon shall reign together,<br/>My Lord and I.<br/>',NULL,44379,6);
INSERT INTO stanza VALUES('T10344','1','Kaibigan mahalaga,<br/>Minamahal ko Siya;<br/>Magiliw ang pag-ibig Niya,<br/>Kay tamis, kay ganda;<br/>Ako''y di mabubuhay pa,<br/>Kung Panginoon wala;<br/>Kaya nga''t magkasama,<br/>Ako at Siya.<br/>',NULL,44380,7);
INSERT INTO stanza VALUES('T10344','2','Kung minsa''y natitisod,<br/>Alam Niya''ng hina ko;<br/>Nguni''t Siya''y aking taguyod,<br/>Maaasahan ko;<br/>At sa daang maliwanag,<br/>Aking patnubay Siya;<br/>Sabay kaming lumakad,<br/>Ako at Siya.<br/>',NULL,44381,8);
INSERT INTO stanza VALUES('T10344','3','Alam Niya kung gaano,<br/>Siya''y aking minahal;<br/>Nguni''t hindi ko matanto<br/>Pag-ibig Niyang sakdal;<br/>Pag-ibig Niya''y walang hanggan,<br/>Lalong nagbabaga;<br/>Kami''y nagmamahalan,<br/>Ako at Siya.<br/>',NULL,44382,9);
INSERT INTO stanza VALUES('T10344','4','Ako ay nagsasabi<br/>Ng lungkot, tuwa ko;<br/>Sa Kanya''y ibabahagi<br/>Mithi at yamot ko;<br/>Naghahayag Siya sa akin<br/>Ng dapat kong gawin;<br/>Kami''y magkaulayaw,<br/>Ako at Siya.<br/>',NULL,44383,10);
INSERT INTO stanza VALUES('T10344','5','Alam Niya ang hangad ko,<br/>Ang tao''y maligtas;<br/>Kaya''t ako''y sinusugo<br/>Nang magpatalastas;<br/>Pag-ibig Niya''y isalaysay,<br/>At pagkamatay Niya;<br/>Magkasamang gumawa,<br/>Ako at Siya.<br/>',NULL,44384,11);
INSERT INTO stanza VALUES('T10344','6','Kaharia''y sasapit,<br/>Hindi maglalaon;<br/>Nais Niyang aking makamit<br/>Gantimpala roon;<br/>Sa luklukan ng l''walhati,<br/>Tuwa''t pagpapala;<br/>Kami ay maghahari,<br/>Ako at Siya.<br/>',NULL,44385,12);
INSERT INTO stanza VALUES('T10345','1','I keep in touch with Jesus,<br/>And He keeps touch with me;<br/>And so we walk together in perfect harmony;<br/>There''s not a day that passes,<br/>There''s not an hour goes by,<br/>But that we have sweet fellowship,<br/>My precious Lord and I.<br/>',NULL,44386,1);
INSERT INTO stanza VALUES('T10346','1','Oh, who''s like our Jesus? He''s all we desire!<br/>His love draws us near — sets our spirits afire!<br/>We cannot but love Him — As one we proclaim:<br/>"Lord Jesus, we love Thee — exalt Thy dear name!"<br/>',NULL,44387,1);
INSERT INTO stanza VALUES('T10346','2','O Jesus, our Jesus, with Thee we are blest—<br/>Our life, our enjoyment, our peace, and our rest:<br/>Thy name be our theme, and Thy love be our song;<br/>Thy love has inspired both our heart and our tongue!<br/>',NULL,44388,2);
INSERT INTO stanza VALUES('T10346','3','O Jesus, our Jesus, how can we express<br/>Thy dearness, so precious, and Thy loveliness?<br/>When we see Thy beauty, all else fades away—<br/>All shadows must flee at the breaking of day!<br/>',NULL,44389,3);
INSERT INTO stanza VALUES('T10346','4','We love Thee, we love Thee, we love Thee, O Lord.<br/>We love Thee, our Jesus, we love Thee, our God!<br/>We love Thee, we love Thee, and that Thou dost know;<br/>As we''re in Thy presence, love for Thee will grow!<br/>',NULL,44390,4);
INSERT INTO stanza VALUES('T10348','1','What length, breadth, depth and height,<br/>His love to me He gives;<br/>How else can a sinner as I,<br/>Be in full grace and bliss?<br/>',NULL,44391,1);
INSERT INTO stanza VALUES('T10348','2','Great price He paid for me,<br/>And bought me for His own;<br/>A cross bearer I now would be,<br/>To follow Him alone.<br/>',NULL,44392,2);
INSERT INTO stanza VALUES('T10348','3','I''ve now forsaken all,<br/>''Tis Christ that I would gain;<br/>Not life, nor death, whate''er befall,<br/>Could hold me back again.<br/>',NULL,44393,3);
INSERT INTO stanza VALUES('T10348','4','Friends, pleasures, gains and fame,<br/>What good are these to me?<br/>For me He became poor with shame,<br/>For Him though poor I''ll be.<br/>',NULL,44394,4);
INSERT INTO stanza VALUES('T10348','5','I love my Savior dear,<br/>I long to please Him well;<br/>For His sake all cheers turn to drear,<br/>All gains to loss as well.<br/>',NULL,44395,5);
INSERT INTO stanza VALUES('T10348','6','My comfort Thou to me,<br/>My gracious Lord Jesus;<br/>Whom have I in heaven but Thee?<br/>Who else on earth I''ll search?<br/>',NULL,44396,6);
INSERT INTO stanza VALUES('T10348','7','Come trials, toils, disgrace,<br/>I now would not take heed;<br/>Lord, I seek Thy love to embrace<br/>My body, soul, spirit.<br/>',NULL,44397,7);
INSERT INTO stanza VALUES('T10348','8','O Lord, I beseech Thee,<br/>Guide this child with Thy grace;<br/>Be by my side, and strengthen me,<br/>This sinful world to pace.<br/>',NULL,44398,8);
INSERT INTO stanza VALUES('T10348','9','Satan, flesh and the world,<br/>Temptations ''round me spring;<br/>If Thou wilt not strengthen this child,<br/>A shame Thy name he''ll bring.<br/>',NULL,44399,9);
INSERT INTO stanza VALUES('T10348','10','Lord, save me from earthly things,<br/>There''s not much time remain;<br/>On Thy second advent I''ll sing,<br/>Hallelujah, Amen!<br/>',NULL,44400,10);
INSERT INTO stanza VALUES('T10348','1','Taas, haba''t lalim—<br/>Pag-ibig Niya sa ''kin;<br/>Makasalanang tulad ko,<br/>Biyaya''y natamo.<br/>',NULL,44401,11);
INSERT INTO stanza VALUES('T10348','2','Ako''y tinubos Niya,<br/>At napasa-Kanya.<br/>Ang krus, aking papasanin,<br/>Tapat na Siya''y sundin.<br/>',NULL,44402,12);
INSERT INTO stanza VALUES('T10348','3','''Winaksi ang tanan,<br/>Nang Kristo''y makamtan;<br/>Buhay man o kamatayan,<br/>Di kayang hadlangan.<br/>',NULL,44403,13);
INSERT INTO stanza VALUES('T10348','4','Pangalan at yaman,<br/>Hindi ko kailangan;<br/>''Pagka''t dusa''t kahihiyan,<br/>Siya nga ang nagpasan.<br/>',NULL,44404,14);
INSERT INTO stanza VALUES('T10348','5','Tagapagligtas ko,<br/>Iyong lugod nais ko;<br/>Para sa Iyo''y handa ako,<br/>Natamo''y maglaho.<br/>',NULL,44405,15);
INSERT INTO stanza VALUES('T10348','6','Sa ''kin aliw lubos,<br/>Panginoong Hesus;<br/>Sa langit man o sa lupa,<br/>Ikaw, walang iba.<br/>',NULL,44406,16);
INSERT INTO stanza VALUES('T10348','7','Pagsubok ma''t hiya,<br/>Di inalintana;<br/>Yapusin ng pag-ibig Mo,<br/>Ang katauhan ko.<br/>',NULL,44407,17);
INSERT INTO stanza VALUES('T10348','8','Aking tanging samo—<br/>Gabayan Mo ako;<br/>Tabihan at palakasin,<br/>Kung mundo''y tahakin.<br/>',NULL,44408,18);
INSERT INTO stanza VALUES('T10348','9','Satanas at mundo,<br/>Laging nagtutukso;<br/>Lakas, dapat na dagdagan,<br/>Para sa Iyong ngalan.<br/>',NULL,44409,19);
INSERT INTO stanza VALUES('T10348','10','Hindi magtatagal,<br/>Aking pagpapagal;<br/>Pagbalik Mo, ay awitin—<br/>Aleluya, Amen!<br/>',NULL,44410,20);
INSERT INTO stanza VALUES('T10349','1','The God of love, my Shepherd is,<br/>His grace He gives to me doth feed;<br/>While He is mine and I am His,<br/>What else I want? What else I need?<br/>',NULL,44411,1);
INSERT INTO stanza VALUES('T10349','2','In pastures green He leadeth me,<br/>There I rejoice, so filled and pleased;<br/>Then to the streams, still waters we<br/>In fellowship sweet rest and peace.<br/>',NULL,44412,2);
INSERT INTO stanza VALUES('T10349','3','He doth restore, in times I stray,<br/>And all my heart He now doth take;<br/>Though I keep wav''ring all the way,<br/>Yet He leads me, for his Name''s sake.<br/>',NULL,44413,3);
INSERT INTO stanza VALUES('T10349','4','Amazing through the death-shade roads,<br/>Well may I walk this all day long;<br/>Thy rod comforts, Thy staff upholds,<br/>Thy presence fills my path along.<br/>',NULL,44414,4);
INSERT INTO stanza VALUES('T10349','5','Thou madest me to boldly roar,<br/>Though foes surround, still grace I call;<br/>My head with oil, my cup runs o''er,<br/>My God He ever gives His all.<br/>',NULL,44415,5);
INSERT INTO stanza VALUES('T10349','6','Truly Thy sweet and wondrous love<br/>Measures my life, and all its days;<br/>Thy love is firm and will not move,<br/>I shall increase my songs and praise.<br/>',NULL,44416,6);
INSERT INTO stanza VALUES('T10349','1','Diyos ng pag-ibig, Pastol ko,<br/>Nagtustos ng kailangan ko;<br/>Siya ay akin, ako''y Kanya,<br/>Wala nang pagkukulang pa.<br/>',NULL,44417,7);
INSERT INTO stanza VALUES('T10349','2','Siya''ng nagdala sa pastulan,<br/>At nagbigay-kabusugan;<br/>Sa tahimik na batisan,<br/>Salamuha''y walang hanggan.<br/>',NULL,44418,8);
INSERT INTO stanza VALUES('T10349','3','Lumihis akong madalas,<br/>''Binalik sa tamang landas;<br/>Para sa Kanyang Pangalan,<br/>Patuloy na ginagabayan.<br/>',NULL,44419,9);
INSERT INTO stanza VALUES('T10349','4','Nang ako''y mag-alinlangan,<br/>Sa lakad may katanungan;<br/>Kanyang tungkod ang siyang gabay,<br/>Presensya nga Niya ay tunay.<br/>',NULL,44420,10);
INSERT INTO stanza VALUES('T10349','5','Palibot man ng kaaway,<br/>Sa biyaya''y may tagumpay;<br/>Puspos ng langis ulo ko,<br/>Nag-umapaw aking saro.<br/>',NULL,44421,11);
INSERT INTO stanza VALUES('T10349','6','Kay tamis ng pag-ibig Mo<br/>Na sumukat sa buhay ko;<br/>Pag-ibig Mo''y di-matinag,<br/>Papuri ko''y idaragdag.<br/>',NULL,44422,12);
INSERT INTO stanza VALUES('T10350','1','Jesus, Jesus, is our song today;<br/>Jesus, Jesus, all along the way;<br/>He will guide us ever,<br/>He will fail us never,<br/>Till His coming day we''ll be preserved.<br/>Jesus, Jesus, blessed Friend divine,<br/>Jesus, Jesus, how His light doth shine;<br/>We will shout and sing His wondrous love,<br/>While marching ''neath His banner glorious.<br/>',NULL,44423,1);
INSERT INTO stanza VALUES('T10351','1','O, Jesus Lord, I love You;<br/>I''m always calling on You.<br/>The world would try and mold me to its measure,<br/>But I am just a vessel for Your treasure.<br/>The world may say I''m crazy,<br/>But I just give my love to You,<br/>That I may know this treasure in my vessel.<br/>O Jesus Lord, I love You!<br/>',NULL,44424,1);
INSERT INTO stanza VALUES('T10351','2','O, Jesus Lord, I love You;<br/>I''m always drinking of You.<br/>The world may have its earthly wine of pleasure,<br/>But drinking of You fills me beyond measure.<br/>The world may say I''m crazy,<br/>But I just drink the more of You,<br/>For You''re the living Water in my vessel.<br/>O Jesus Lord, I love You!<br/>',NULL,44425,2);
INSERT INTO stanza VALUES('T10351','3','O, Jesus Lord, I love You;<br/>I''m always eating of You.<br/>By eating You, Your life assimilating,<br/>The world and my old self eliminating.<br/>The world may say I''m crazy,<br/>But I just eat the more of You,<br/>For You''re the living Bread sent down from heaven.<br/>O Jesus Lord, I love You!<br/>',NULL,44426,3);
INSERT INTO stanza VALUES('T10351','1','Hesus, Poong mahal ko;<br/>Bigkas Ka ng labi ko.<br/>Ang mundo pilit akong pinaayon,<br/>Nguni''t ako''y sisidlan Mo, Pangino''n.<br/>Sa mundo ako''y hibang,<br/>''Pagka''t Iyo lamang pagsinta,<br/>Sa ''king sisidlan may yaman alam ko,<br/>Hesus Poon mahal ko!<br/>',NULL,44427,4);
INSERT INTO stanza VALUES('T10351','2','Hesus Poon mahal ko;<br/>Ikaw ang inumin ko.<br/>Mundo may panlupang alak ng lugod,<br/>Pag-inom sa Iyo galak di masayod.<br/>Sa mundo ako''y hibang,<br/>Lalong iinumin Kita,<br/>Tubig buháy mula sa ''kin aagos.<br/>Hesus mahal kong lubos!<br/>',NULL,44428,5);
INSERT INTO stanza VALUES('T10351','3','Hesus Poon mahal ko,<br/>Ikaw ang pagkain ko,<br/>Pagkain sa Iyo—buhay Mo''y tanggapin,<br/>Mundo at lumang sarili''y alisin.<br/>Sa mundo ako''y hibang,<br/>Subali''t kakain lamang;<br/>Tunay na Tinapay mula sa langit.<br/>Hesus ''king iniibig!<br/>',NULL,44429,6);
INSERT INTO stanza VALUES('T10352','1','Abide in Thee, Lord, Oh what blessedness!<br/>Fellowship with Thee, dipped in Thy sweetness;<br/>Abide in Thee, Lord, Thou art one with me,<br/>More fellowship, Lord, I''ve no gap with Thee.<br/>',NULL,44430,1);
INSERT INTO stanza VALUES('T10352','2','Abide in Thee, Lord, Thy anointing bade,<br/>Fellowship with Thee, by Thy Spirit led;<br/>Heed Thy anointing, taste the best of Thee,<br/>Follow the Spirit, Thy companion be.<br/>',NULL,44431,2);
INSERT INTO stanza VALUES('T10352','3','Abide in Thee, Lord, gracious light I''ll see,<br/>Fellowship with Thee, all my shadows flee;<br/>To Thy light yielding, life in me will grow,<br/>When shadows fled, what ease my heart shall know.<br/>',NULL,44432,3);
INSERT INTO stanza VALUES('T10352','4','Abide in Thee, Lord, weak is turned to strong,<br/>Fellowship with Thee, sighing turned to song;<br/>Abide in Thee, Lord, death is turned to life,<br/>Fellowship with Thee, joy — not grief — is rife.<br/>',NULL,44433,4);
INSERT INTO stanza VALUES('T10352','5','Abide in Thee, Lord, Satan can''t invade,<br/>Fellowship with Thee, I from world evade;<br/>Abide in Thee, Lord, sin has lost its pow''r<br/>Fellowship with Thee, my own "self" no more.<br/>',NULL,44434,5);
INSERT INTO stanza VALUES('T10352','6','Abide in Thee, Lord, fashion me like Thee,<br/>Fellowship with Thee, full of life I''d be;<br/>Abide in Thee, Lord, strengthened with Thy might,<br/>Fellowship with Thee, in Thy wealth delight.<br/>',NULL,44435,6);
INSERT INTO stanza VALUES('T10352','7','Abide in Thee, Lord, from my heart I plead,<br/>More fellowship, my spirit doth entreat;<br/>Oh, may my being wholly drown in Thee,<br/>Mingled, Lord, with Thee till eternity.<br/>',NULL,44436,7);
INSERT INTO stanza VALUES('T10354','1','I am here fighting for the Lord,<br/>Tho'' Satan disapproves;<br/>And he uses all His powers<br/>To stop me with reproofs;<br/>I pray without ceasing,<br/>The enemy fleeing.<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44437,1);
INSERT INTO stanza VALUES('T10354','chorus','A little talk with Jesus<br/>Makes it right, all right;<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>In trials of ev''ry kind,<br/>Praise God I always find,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44438,2);
INSERT INTO stanza VALUES('T10354','2','Tho'' the dark night, and clouds look black,<br/>And stormy overhead,<br/>And trials of almost ev''ry<br/>Kind across my path are spread;<br/>How soon I conquer all,<br/>As to the Lord I call,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44439,3);
INSERT INTO stanza VALUES('T10354','chorus','A little talk with Jesus<br/>Makes it right, all right;<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>In trials of ev''ry kind,<br/>Praise God I always find,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44440,4);
INSERT INTO stanza VALUES('T10354','3','When those who once were dearest friends<br/>Begin to persecute,<br/>And more who once professed to love,<br/>Have distant grown, and mute,<br/>I tell Him all my grief,<br/>He quickly sends relief,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44441,5);
INSERT INTO stanza VALUES('T10354','chorus','A little talk with Jesus<br/>Makes it right, all right;<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>In trials of ev''ry kind,<br/>Praise God I always find,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44442,6);
INSERT INTO stanza VALUES('T10354','4','And thus, by frequent little talks,<br/>I gain the victory;<br/>And march along with cheerful song,<br/>Enjoying liberty;<br/>With Jesus as my Friend,<br/>I''ll prove until the end,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44443,7);
INSERT INTO stanza VALUES('T10354','chorus','A little talk with Jesus<br/>Makes it right, all right;<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>In trials of ev''ry kind,<br/>Praise God I always find,<br/>A little talk with Jesus<br/>Makes it right, all right.<br/>',NULL,44444,8);
INSERT INTO stanza VALUES('T10355','1','God shines Himself within my soul,<br/>Renewed am I, gone are the old;<br/>In earthenwares doth treasure rest,<br/>Excelling power is here expressed.<br/>',NULL,44445,1);
INSERT INTO stanza VALUES('T10355','chorus','In earthenwares doth treasure rest,<br/>Excelling power is here expressed,<br/>Excelling power is here expressed.<br/>',NULL,44446,2);
INSERT INTO stanza VALUES('T10355','2','On all sides pressed, yet not restrained,<br/>Though persecuted, not disdained;<br/>Perplexed, yet never in despair,<br/>Though struck down, nor could death impair.<br/>',NULL,44447,3);
INSERT INTO stanza VALUES('T10355','chorus','In earthenwares doth treasure rest,<br/>Excelling power is here expressed,<br/>Excelling power is here expressed.<br/>',NULL,44448,4);
INSERT INTO stanza VALUES('T10355','3','In body bearing Jesus'' death,<br/>His life is then expressed therewith;<br/>Since death in me doth operate,<br/>Much more His life shall germinate.<br/>',NULL,44449,5);
INSERT INTO stanza VALUES('T10355','chorus','In earthenwares doth treasure rest,<br/>Excelling power is here expressed,<br/>Excelling power is here expressed.<br/>',NULL,44450,6);
INSERT INTO stanza VALUES('T10355','4','As God raised Jesus from the dead,<br/>With Him we live as He has led;<br/>Our outward man though should decay,<br/>Our inward man''s renewed each day.<br/>',NULL,44451,7);
INSERT INTO stanza VALUES('T10355','chorus','Our outward man though should decay,<br/>Our inward man''s renewed each day,<br/>Our inward man''s renewed each day.<br/>',NULL,44452,8);
INSERT INTO stanza VALUES('T10355','5','Our light affliction soon shall wane,<br/>Surpassing weight of glory gain;<br/>Consider not what we can see,<br/>But things unseen, eternal be.<br/>',NULL,44453,9);
INSERT INTO stanza VALUES('T10355','chorus','Our outward man though should decay,<br/>Our inward man''s renewed each day,<br/>Our inward man''s renewed each day.<br/>',NULL,44454,10);
INSERT INTO stanza VALUES('T10355','1','Diyos nagningning sa kalul''wa,<br/>Ako''y binabago Ni-ya;<br/>Yaman sa sisidlang-lupa,<br/>Kapangyariha''y hayag nga!<br/>',NULL,44455,11);
INSERT INTO stanza VALUES('T10355','chorus','Yaman sa sisidlang-lupa,<br/>Kapangyariha''y hayag nga!<br/>Kapangyariha''y hayag nga!<br/>',NULL,44456,12);
INSERT INTO stanza VALUES('T10355','2','Gipit ma''y di nakukulong,<br/>Sawil man, pag-asa''y tulong;<br/>Pinag-uusig, matibay,<br/>Inilugmok, di namatay.<br/>',NULL,44457,13);
INSERT INTO stanza VALUES('T10355','chorus','Yaman sa sisidlang-lupa,<br/>Kapangyariha''y hayag nga!<br/>Kapangyariha''y hayag nga!<br/>',NULL,44458,14);
INSERT INTO stanza VALUES('T10355','3','''Pag kamatayan Niya''y taglay,<br/>Mahayag din Kanyang buhay;<br/>Kamataya''y danasin ko,<br/>Buhay ni Hesus lalago.<br/>',NULL,44459,15);
INSERT INTO stanza VALUES('T10355','chorus','Yaman sa sisidlang-lupa,<br/>Kapangyariha''y hayag nga!<br/>Kapangyariha''y hayag nga!<br/>',NULL,44460,16);
INSERT INTO stanza VALUES('T10355','4','Binuhay ng Diyos si Kristo,<br/>Siya rin ay ipamuhay ko;<br/>Humina panlabas-tao,<br/>Panloob ay nababago.<br/>',NULL,44461,17);
INSERT INTO stanza VALUES('T10355','chorus','Humina panlabas-tao,<br/>Panloob ay nababago,<br/>Panloob ay nababago.<br/>',NULL,44462,18);
INSERT INTO stanza VALUES('T10355','5','Magaang pighati''y bat''hin,<br/>Bigat ng l''walhati''y kamtin;<br/>Di titingnan nakikita,<br/>Kundi ang di-nakikita.<br/>',NULL,44463,19);
INSERT INTO stanza VALUES('T10355','chorus','Humina panlabas-tao,<br/>Panloob ay nababago,<br/>Panloob ay nababago.<br/>',NULL,44464,20);
INSERT INTO stanza VALUES('T10356','1','If Thou wouldst take what I desire,<br/>Lord, give Thyself to me;<br/>If Thou wouldst keep me to inquire,<br/>Lord, give Thyself to me.<br/>',NULL,44465,1);
INSERT INTO stanza VALUES('T10356','chorus','Lord Jesus, precious Savior,<br/>More of Thyself give me;<br/>Subject I wholly to Thee,<br/>More of Thyself for me.<br/>',NULL,44466,2);
INSERT INTO stanza VALUES('T10356','2','My hopes are blurred and gone away,<br/>Lord, give Thyself to me;<br/>My heart keeps wav''ring all the way,<br/>Lord, give Thyself to me.<br/>',NULL,44467,3);
INSERT INTO stanza VALUES('T10356','chorus','Lord Jesus, precious Savior,<br/>More of Thyself give me;<br/>Subject I wholly to Thee,<br/>More of Thyself for me.<br/>',NULL,44468,4);
INSERT INTO stanza VALUES('T10356','3','Since Thou took all that I depend,<br/>Lord, give Thyself to me;<br/>Since Thou reject my pray''rs again,<br/>Lord, give Thyself to me.<br/>',NULL,44469,5);
INSERT INTO stanza VALUES('T10356','chorus','Lord Jesus, precious Savior,<br/>More of Thyself give me;<br/>Subject I wholly to Thee,<br/>More of Thyself for me.<br/>',NULL,44470,6);
INSERT INTO stanza VALUES('T10356','4','If patience''s what I truly lack,<br/>Still give Thyself to me;<br/>If Thou delay Thy coming back,<br/>Give more Thyself to me.<br/>',NULL,44471,7);
INSERT INTO stanza VALUES('T10356','chorus','Lord Jesus, precious Savior,<br/>More of Thyself give me;<br/>Subject I wholly to Thee,<br/>More of Thyself for me.<br/>',NULL,44472,8);
INSERT INTO stanza VALUES('T10357','1','He is my dearest One,<br/>I love Him most of all;<br/>Ceased from seeking I''ve done,<br/>Trusting Him I''ll not fall.<br/>',NULL,44473,1);
INSERT INTO stanza VALUES('T10357','2','He''s my supply in need,<br/>He is most beautiful,<br/>He''s my support indeed,<br/>He''s always so faithful.<br/>',NULL,44474,2);
INSERT INTO stanza VALUES('T10357','3','He''s my joy — sadness gone,<br/>He is unchangeable;<br/>He is my dearest One,<br/>I love Him most of all.<br/>',NULL,44475,3);
INSERT INTO stanza VALUES('T10357','1','Siya''y minamahal ko,<br/>Pinakaibig ko;<br/>Di na hahanap pa,<br/>Maasahan ko Siya.<br/>',NULL,44476,4);
INSERT INTO stanza VALUES('T10357','2','Sa kailanga''y tustos,<br/>Pinakamaganda,<br/>Umalalay lubos,<br/>At laging tapat Siya.<br/>',NULL,44477,5);
INSERT INTO stanza VALUES('T10357','3','Galak sa lungkot ko,<br/>Siya''y di nagbabago;<br/>Pinakamahal ko,<br/>Pinakaibig ko.<br/>',NULL,44478,6);
INSERT INTO stanza VALUES('T10358','1','Appoint my way, O Jesus, My Lord, appoint for me,<br/>I have not my own fond hopes, I want Thy will to be;<br/>What pathway Thou appointed, How rugged it might be,<br/>I am willing to follow, To gain pleasure with Thee.<br/>',NULL,44479,1);
INSERT INTO stanza VALUES('T10358','chorus','Hold tight my hand, Lord Jesus, for I am weak, Thou know,<br/>Or else be wrapped in sorrow, Not knowing where to go;<br/>If Thou take hold of my hand, No matter what Thou choose,<br/>In any road Thou place me, My heart shall then be soothed.<br/>',NULL,44480,2);
INSERT INTO stanza VALUES('T10358','2','It may be smooth or rugged, If it''s chosen by Thee,<br/>Then it is my deep longing, I have no other plea;<br/>I dare not be my own lord, Even with Thy consent,<br/>Appoint my way, Lord Jesus, To Thee my ears would lend.<br/>',NULL,44481,3);
INSERT INTO stanza VALUES('T10358','chorus','Hold tight my hand, Lord Jesus, for I am weak, Thou know,<br/>Or else be wrapped in sorrow, Not knowing where to go;<br/>If Thou take hold of my hand, No matter what Thou choose,<br/>In any road Thou place me, My heart shall then be soothed.<br/>',NULL,44482,4);
INSERT INTO stanza VALUES('T10358','3','My time is in Thy hand, Lord, It may be soon or late,<br/>According to Thy pleasure, I set not mine own date;<br/>If Thou would I be patient, For many-a-days and years,<br/>Ahead in peace I would not, Nor soon my way be cleared.<br/>',NULL,44483,5);
INSERT INTO stanza VALUES('T10358','chorus','Hold tight my hand, Lord Jesus, for I am weak, Thou know,<br/>Or else be wrapped in sorrow, Not knowing where to go;<br/>If Thou take hold of my hand, No matter what Thou choose,<br/>In any road Thou place me, My heart shall then be soothed.<br/>',NULL,44484,6);
INSERT INTO stanza VALUES('T10358','4','My little cup of fate, Lord, Fill in with what Thou willed,<br/>Be it with joy or sorrow, Be as what Thou would fill;<br/>All bitterness are sweet, Lord, If it''s Thy will I know,<br/>All sweet things turned to malice, If not Thy grace I saw.<br/>',NULL,44485,7);
INSERT INTO stanza VALUES('T10358','chorus','Hold tight my hand, Lord Jesus, for I am weak, Thou know,<br/>Or else be wrapped in sorrow, Not knowing where to go;<br/>If Thou take hold of my hand, No matter what Thou choose,<br/>In any road Thou place me, My heart shall then be soothed.<br/>',NULL,44486,8);
INSERT INTO stanza VALUES('T10358','5','Appoint for me, O Jesus, Health or disease the same,<br/>To be smiling or weeping, Be honored or defamed;<br/>Be it big thing or small thing, To choose I never wish,<br/>I wouldn''t mind my feelings, but Where Thy glory is.<br/>',NULL,44487,9);
INSERT INTO stanza VALUES('T10358','chorus','Hold tight my hand, Lord Jesus, for I am weak, Thou know,<br/>Or else be wrapped in sorrow, Not knowing where to go;<br/>If Thou take hold of my hand, No matter what Thou choose,<br/>In any road Thou place me, My heart shall then be soothed.<br/>',NULL,44488,10);
INSERT INTO stanza VALUES('T10358','1','Italaga Mo, Hesus, aking maging daan,<br/>Walang sariling nais, Iyong kalooban lang;<br/>Landas na Iyong pinili, gaano mang hirap,<br/>Ako ay tatalima, lugod Mo ang hanap.<br/>',NULL,44489,11);
INSERT INTO stanza VALUES('T10358','chorus','Hawakan ang kamay ko, ako nga''y mahina,<br/>Hindi makapamuhay kung Ikaw ay wala;<br/>Hawakan ang kamay ko, Ikaw ang bahala,<br/>Landas na tatahakin, Ikaw ang magdala.<br/>',NULL,44490,12);
INSERT INTO stanza VALUES('T10358','2','Panatag man o hindi, Ikaw ang pumili,<br/>Aking pagsusumamo — layon Mo ang mithi;<br/>Di ko ibig mamuno, Ikaw ang maghari,<br/>At mga pandinig ko, sa Iyo nakatali.<br/>',NULL,44491,13);
INSERT INTO stanza VALUES('T10358','chorus','Hawakan ang kamay ko, ako nga''y mahina,<br/>Hindi makapamuhay kung Ikaw ay wala;<br/>Hawakan ang kamay ko, Ikaw ang bahala,<br/>Landas na tatahakin, Ikaw ang magdala.<br/>',NULL,44492,14);
INSERT INTO stanza VALUES('T10358','3','Ang panahon ko''y Iyo, mabagal o mabilis,<br/>Walang sariling pasya, ayon sa Iyong nais;<br/>Kung nais Mong ako''y mga taon magtiis,<br/>Payapang huminto hanggang daan malinis.<br/>',NULL,44493,15);
INSERT INTO stanza VALUES('T10358','chorus','Hawakan ang kamay ko, ako nga''y mahina,<br/>Hindi makapamuhay kung Ikaw ay wala;<br/>Hawakan ang kamay ko, Ikaw ang bahala,<br/>Landas na tatahakin, Ikaw ang magdala.<br/>',NULL,44494,16);
INSERT INTO stanza VALUES('T10358','4','Saro ng aking buhay, Ikaw ang magpuno,<br/>Lumbay man o ligaya, ayon sa Iyong gusto;<br/>Pait nagiging tamis, kung kagustuhan Mo,<br/>Tamasa''y kamuhian, kung di galing sa Iyo.<br/>',NULL,44495,17);
INSERT INTO stanza VALUES('T10358','chorus','Hawakan ang kamay ko, ako nga''y mahina,<br/>Hindi makapamuhay kung Ikaw ay wala;<br/>Hawakan ang kamay ko, Ikaw ang bahala,<br/>Landas na tatahakin, Ikaw ang magdala.<br/>',NULL,44496,18);
INSERT INTO stanza VALUES('T10358','5','Ikaw ang Siyang pumili, lusog o sakit man,<br/>Ngiti man o pagluha, dungis man o ngalan;<br/>Lahat ng mga bagay, di ayon sa akin,<br/>Kaluwalhatian Mo ang siyang dapat kamtin.<br/>',NULL,44497,19);
INSERT INTO stanza VALUES('T10358','chorus','Hawakan ang kamay ko, ako nga''y mahina,<br/>Hindi makapamuhay kung Ikaw ay wala;<br/>Hawakan ang kamay ko, Ikaw ang bahala,<br/>Landas na tatahakin, Ikaw ang magdala.<br/>',NULL,44498,20);
INSERT INTO stanza VALUES('T10359','1','I trust in God wherever I may be. . . .<br/>Upon the land or on the rolling sea;<br/>For come what may, from day to day,<br/>My heav''nly Father watches over me.<br/>',NULL,44499,1);
INSERT INTO stanza VALUES('T10359','chorus','I trust in God, I know He cares for me,<br/>On mountain bleak or on the stormy sea;<br/>Though billows roll, He keeps my soul,<br/>My heav''nly Father watches over me.<br/>',NULL,44500,2);
INSERT INTO stanza VALUES('T10359','2','I trust in God, for in the lion''s den,<br/>On battlefield, or in the prison pen;<br/>Through praise or blame, Through flood or fame,<br/>My heav''nly Father watches over me.<br/>',NULL,44501,3);
INSERT INTO stanza VALUES('T10359','chorus','I trust in God, I know He cares for me,<br/>On mountain bleak or on the stormy sea;<br/>Though billows roll, He keeps my soul,<br/>My heav''nly Father watches over me.<br/>',NULL,44502,4);
INSERT INTO stanza VALUES('T10359','3','He makes the rose an object of His care,<br/>He guides the eagle through the pathless air;<br/>And surely He remembers me,<br/>My heav''nly Father watches over me.<br/>',NULL,44503,5);
INSERT INTO stanza VALUES('T10359','chorus','I trust in God, I know He cares for me,<br/>On mountain bleak or on the stormy sea;<br/>Though billows roll, He keeps my soul,<br/>My heav''nly Father watches over me.<br/>',NULL,44504,6);
INSERT INTO stanza VALUES('T10360','beginning-note','Psalm 139:23<br/>',NULL,44505,1);
INSERT INTO stanza VALUES('T10360','1','Search me, O God, and know my heart today;<br/>Try me, O Savior, know my thoughts, I pray;<br/>See if there be some wicked way in me;<br/>Cleanse me from every sin, and set me free.<br/>',NULL,44506,2);
INSERT INTO stanza VALUES('T10361','1','I am weak but Thou art strong,<br/>Jesus, keep me from all wrong;<br/>I''ll be satisfied as long<br/>As I walk let me walk close to Thee.<br/>',NULL,44507,1);
INSERT INTO stanza VALUES('T10361','chorus','Just a closer walk with Thee,<br/>Grant it, Jesus, ''tis my plea;<br/>Daily walking close with Thee,<br/>Let it be, dear Lord, let it be.<br/>',NULL,44508,2);
INSERT INTO stanza VALUES('T10361','2','Through this world of toil and snares,<br/>If I falter, Lord, who cares?<br/>Who with me my burden shares?<br/>None but Thee, dear Lord, none but Thee.<br/>',NULL,44509,3);
INSERT INTO stanza VALUES('T10361','chorus','Just a closer walk with Thee,<br/>Grant it, Jesus, ''tis my plea;<br/>Daily walking close with Thee,<br/>Let it be, dear Lord, let it be.<br/>',NULL,44510,4);
INSERT INTO stanza VALUES('T10362','1','Though shadows deepen and my heart bleeds,<br/>I will not question the way He leads;<br/>This side of heaven we know in part,<br/>I will not question a broken heart.<br/>',NULL,44511,1);
INSERT INTO stanza VALUES('T10362','chorus','We''ll talk it over in the by and by,<br/>We''ll talk it over, my Lord and I.<br/>I''ll ask the reasons — He''ll tell me why,<br/>When we talk it over in the by and by.<br/>',NULL,44512,2);
INSERT INTO stanza VALUES('T10362','2','I''ll trust His leading, He''ll never fail,<br/>Through darkest tunnels or misty vale;<br/>Obey His leading and faithful be,<br/>Though only one step ahead I see.<br/>',NULL,44513,3);
INSERT INTO stanza VALUES('T10362','chorus','We''ll talk it over in the by and by,<br/>We''ll talk it over, my Lord and I.<br/>I''ll ask the reasons — He''ll tell me why,<br/>When we talk it over in the by and by.<br/>',NULL,44514,4);
INSERT INTO stanza VALUES('T10362','3','I''ll hide my heartache behind a smile,<br/>And wait for reasons till after while;<br/>And though He try me, I know I''ll find<br/>That all my burdens are silver lined.<br/>',NULL,44515,5);
INSERT INTO stanza VALUES('T10362','chorus','We''ll talk it over in the by and by,<br/>We''ll talk it over, my Lord and I.<br/>I''ll ask the reasons — He''ll tell me why,<br/>When we talk it over in the by and by.<br/>',NULL,44516,6);
INSERT INTO stanza VALUES('T10362','1','Kahit puso ko''y nagdurugo,<br/>Pag-akay Niya''y di itatanong,<br/>Bahagi lang batid natin dito,<br/>Sawing puso ko''y di magtatanong.<br/>',NULL,44517,7);
INSERT INTO stanza VALUES('T10362','chorus','Pag-uusapan namin paglaon,<br/>Ako''t ng aking Panginoon;<br/>Ang sanhi''y aking itatanong,<br/>Sasagutin Niya ako paglaon.<br/>',NULL,44518,8);
INSERT INTO stanza VALUES('T10362','2','Kanyang patnubay, di mabigo,<br/>Sa dilim man o lambak dako;<br/>Maging tapat sa pagtalima,<br/>''Sang hakbang man aking makita.<br/>',NULL,44519,9);
INSERT INTO stanza VALUES('T10362','chorus','Pag-uusapan namin paglaon,<br/>Ako''t ng aking Panginoon;<br/>Ang sanhi''y aking itatanong,<br/>Sasagutin Niya ako paglaon.<br/>',NULL,44520,10);
INSERT INTO stanza VALUES('T10362','3','Sa ''king ngiti may nakakubli,<br/>Naghihintay pusong pighati;<br/>Sukdan pagsubok ma''y sumiil,<br/>Lahat ng hapis mayro''ng aliw.<br/>',NULL,44521,11);
INSERT INTO stanza VALUES('T10362','chorus','Pag-uusapan namin paglaon,<br/>Ako''t ng aking Panginoon;<br/>Ang sanhi''y aking itatanong,<br/>Sasagutin Niya ako paglaon.<br/>',NULL,44522,12);
INSERT INTO stanza VALUES('T10363','1','Though angels have often beheld of His face,<br/>But they have not known of His love;<br/>Though all His saints knew of His love and His grace,<br/>Yet ne''er see His glory above.<br/>Though soon they too shall see His face without fears,<br/>And know of His glory and throne;<br/>But Mary had seen our Lord with His tears,<br/>And knew of His heart that''s been torn.<br/>And knew of His heart that''s been torn.<br/>',NULL,44523,1);
INSERT INTO stanza VALUES('T10363','2','Not long we shall know our dear Lord to His best,<br/>We never quite knew Him before;<br/>But solace and healings that come from the test,<br/>Cannot be tasted anymore.<br/>Though praises shall fill up the air on that day,<br/>But we shall miss our prayers in tears;<br/>The comfort and peace that we gained from dismay,<br/>Those lonely times wherein He cheers.<br/>Those lonely times wherein He cheers.<br/>',NULL,44524,2);
INSERT INTO stanza VALUES('T10363','3','Well, on that day we shall have the crown of glory,<br/>But then there''s no cross to obey;<br/>His suff''rings for us in much pain and weary,<br/>Can only be relished today.<br/>Once entered in rest, no more ail could be found,<br/>And no chance to suffer for Him;<br/>There''s nowhere can we meet the trials abound,<br/>To lay up our price just for Him.<br/>To lay up our price just for Him.<br/>',NULL,44525,3);
INSERT INTO stanza VALUES('T10363','4','Precious and few — the chance to bear His name,<br/>All chances shall soon pass away;<br/>Not much time left to suffer mocking and shame,<br/>To labor and weary all day.<br/>There shall not be any contempt nor revile,<br/>No more reproach shall there still be;<br/>So I must treasure these blessings in a while,<br/>For through them I mingle with Thee.<br/>For through them I mingle with Thee.<br/>',NULL,44526,4);
INSERT INTO stanza VALUES('T10363','5','Lord Jesus, Thy face how I soon long to glance,<br/>For that''ll be so glorious indeed;<br/>But I dare not escape from the trials each stance,<br/>And lose such a fellowship sweet.<br/>Grant me, my dear Lord, be filled with Thy great love,<br/>Just live for Thee though come what may;<br/>Lest someday when I am with Thee on above,<br/>Should rue for my lapses today.<br/>Should rue for my lapses today.<br/>',NULL,44527,5);
INSERT INTO stanza VALUES('T10364','1','Jesus my Lord will love me forever,<br/>From Him no pow''r of evil can sever,<br/>He gave His life to ransom my soul,<br/>Now I belong to Him.<br/>',NULL,44528,1);
INSERT INTO stanza VALUES('T10364','chorus','Now I belong to Jesus,<br/>Jesus belongs to me;<br/>Not for the years of time alone,<br/>But for eternity.<br/>',NULL,44529,2);
INSERT INTO stanza VALUES('T10364','2','Once I was lost in sin''s degradation,<br/>Jesus came down to bring me salvation,<br/>Lifted me up from sorrow and shame,<br/>Now I belong to Him.<br/>',NULL,44530,3);
INSERT INTO stanza VALUES('T10364','chorus','Now I belong to Jesus,<br/>Jesus belongs to me;<br/>Not for the years of time alone,<br/>But for eternity.<br/>',NULL,44531,4);
INSERT INTO stanza VALUES('T10364','3','Joy floods my spirit — Jesus has saved me,<br/>Freed me from sin that long had enslaved me,<br/>His precious blood He gave to redeem,<br/>Now I belong to Him.<br/>',NULL,44532,5);
INSERT INTO stanza VALUES('T10364','chorus','Now I belong to Jesus,<br/>Jesus belongs to me;<br/>Not for the years of time alone,<br/>But for eternity.<br/>',NULL,44533,6);
INSERT INTO stanza VALUES('T10364','1','Walang hanggang iniibig ako<br/>Ni Hesus na aking Panginoon,<br/>Kanyang buhay tinubos ako,<br/>Ako''y Kanya ngayon.<br/>',NULL,44534,7);
INSERT INTO stanza VALUES('T10364','chorus','Ako ngayo''y kay Hesus,<br/>Hesus akin naman;<br/>Di lang sa mga panahon,<br/>Bagkus walang hanggan.<br/>',NULL,44535,8);
INSERT INTO stanza VALUES('T10364','2','Minsan nalugmok sa kasalanan,<br/>Hesus nagdala ng kaligtasan,<br/>''Ko''y inangat sa kahihiyan,<br/>Ngayon ako''y Kanya.<br/>',NULL,44536,9);
INSERT INTO stanza VALUES('T10364','chorus','Ako ngayo''y kay Hesus,<br/>Hesus akin naman;<br/>Di lang sa mga panahon,<br/>Bagkus walang hanggan.<br/>',NULL,44537,10);
INSERT INTO stanza VALUES('T10364','3','Galak apaw sa ''king espiritu,<br/>Pinalaya mula sa ''king sala;<br/>Tinubos Niya ng Kanyang dugo,<br/>Ngayon ako''y Kanya.<br/>',NULL,44538,11);
INSERT INTO stanza VALUES('T10364','chorus','Ako ngayo''y kay Hesus,<br/>Hesus akin naman;<br/>Di lang sa mga panahon,<br/>Bagkus walang hanggan.<br/>',NULL,44539,12);
INSERT INTO stanza VALUES('T10365','1','Since I started for the kingdom,<br/>Since my life He controls;<br/>Since I gave my heart to Jesus,<br/>The longer I serve Him, the sweeter He grows.<br/>',NULL,44540,1);
INSERT INTO stanza VALUES('T10365','chorus','The longer I serve Him, the sweeter He grows,<br/>The more that I love Him, more love He bestows;<br/>Each day is like heaven, my heart overflows,<br/>The longer I serve Him, the sweeter He grows.<br/>',NULL,44541,2);
INSERT INTO stanza VALUES('T10365','2','Every need He is supplying,<br/>Precious grace He bestows;<br/>Every day my way gets brighter,<br/>The longer I serve Him, the sweeter He grows.<br/>',NULL,44542,3);
INSERT INTO stanza VALUES('T10365','chorus','The longer I serve Him, the sweeter He grows,<br/>The more that I love Him, more love He bestows;<br/>Each day is like heaven, my heart overflows,<br/>The longer I serve Him, the sweeter He grows.<br/>',NULL,44543,4);
INSERT INTO stanza VALUES('T10365','1','Nang para sa kaharian,<br/>Ako''y nagsimula;<br/>Puso''y ''binigay kay Hesus,<br/>Lalong naglilingkod, lalo''ng tamis Niya.<br/>',NULL,44544,5);
INSERT INTO stanza VALUES('T10365','chorus','Lalong naglilingkod, lalong tamis Niya,<br/>Lalong iniibig, ganti''y higit pa;<br/>Tila nasa langit, puso''y masaya,<br/>Lalong naglilingkod, lalong tamis Niya.<br/>',NULL,44545,6);
INSERT INTO stanza VALUES('T10365','2','Nagtutustos sa kailangan,<br/>Nagbigay biyaya;<br/>Landas ko''y lumiliwanag,<br/>Lalong naglilingkod, lalong tamis Niya.<br/>',NULL,44546,7);
INSERT INTO stanza VALUES('T10365','chorus','Lalong naglilingkod, lalong tamis Niya,<br/>Lalong iniibig, ganti''y higit pa;<br/>Tila nasa langit, puso''y masaya,<br/>Lalong naglilingkod, lalong tamis Niya.<br/>',NULL,44547,8);
INSERT INTO stanza VALUES('T10401','1','O Lord of Life breathe upon me,<br/>Open Thy living spring to me,<br/>From my deepest part moving me,<br/>Light of Life is shining in me.<br/>',NULL,44548,1);
INSERT INTO stanza VALUES('T10401','2','O what a thought, Thou art in me,<br/>Neither in height nor depth to seek,<br/>Turn to my spirit, I''ll see Thee,<br/>Spirit to spirit, Thou dost speak.<br/>',NULL,44549,2);
INSERT INTO stanza VALUES('T10401','3','Thou art now my Advocator, Lord,<br/>In my spirit Anointing be,<br/>All Thou hast done in my behalf,<br/>All in my spirit touched by me.<br/>',NULL,44550,3);
INSERT INTO stanza VALUES('T10401','4','But ah, this faithless heart of mine,<br/>Often was moved, yet turned aside,<br/>Move, breathe, forgive me, Lord Divine,<br/>Let me function as Thou would guide.<br/>',NULL,44551,4);
INSERT INTO stanza VALUES('T10401','5','When my spirit''s low and weak be,<br/>Unable to speak forth Thy grace,<br/>Oh breathe on me from deep within,<br/>That I be fully filled by Thee.<br/>',NULL,44552,5);
INSERT INTO stanza VALUES('T10401','1','Poon ng buhay, ''ko''y hipan,<br/>Bukal ng buhay, Iyong buksan;<br/>Sa loob ko''y pakilusin,<br/>Ilaw ng Buhay magningning.<br/>',NULL,44553,6);
INSERT INTO stanza VALUES('T10401','2','O, Ika''y sa loob namin,<br/>Di na kailangang hanapin;<br/>Sa espiritu''y bumaling,<br/>Magsalita Ka sa amin.<br/>',NULL,44554,7);
INSERT INTO stanza VALUES('T10401','3','Aking Tagapamagitan,<br/>Ako''y Iyong pinapahiran;<br/>Lahat sa ''ki''y ginawa Mo,<br/>Nahihipo sa ''spiritu.<br/>',NULL,44555,8);
INSERT INTO stanza VALUES('T10401','4','Di tapat ang aking puso,<br/>May pandama, di sumunod;<br/>Hipan ako at kumilos,<br/>Nang magpangsyon akong lubos.<br/>',NULL,44556,9);
INSERT INTO stanza VALUES('T10401','5','Kung espiritu''y mahina.<br/>Di masabi Iyong biyaya;<br/>Ang aking loob Iyong hipan,<br/>Nang ako''y Iyong mapuspusan.<br/>',NULL,44557,10);
INSERT INTO stanza VALUES('T10402','1','Draw us, Lord Jesus, draw our hearts closer to Thee,<br/>What best the future offers we won''t care nor search;<br/>We gladly offer Thee the best years of our lives,<br/>Consecrate all to Thee and to the church.<br/>',NULL,44558,1);
INSERT INTO stanza VALUES('T10402','2','Draw us to Thee, O Church Life, draw us more to Thee,<br/>God opens heav''nly windows, blessings daily pour;<br/>He will rebuke the locusts never more to cause—<br/>This, our generation, unripe and fall.<br/>',NULL,44559,2);
INSERT INTO stanza VALUES('T10402','3','Nearer, O Lovely Bridegroom, nearer step by step,<br/>Softly He''ll call your name as He inclines to hear;<br/>And on that day when He returns so suddenly,<br/>We will be caught up with Him in the air!<br/>',NULL,44560,3);
INSERT INTO stanza VALUES('T10402','1','Ilapit sa Iyo Hesus ang puso namin,<br/>Anumang galing ng bukas di-pansinin;<br/>Mabuting mga taon ng buhay namin,<br/>Sa Iyo''t sa ekklesia''y ''alay namin.<br/>',NULL,44561,4);
INSERT INTO stanza VALUES('T10402','2','Sa Buhay-Ekklesia, ilapit kami,<br/>Diyos nagbubuhos ng pagpapala lagi;<br/>Mga balang di na kailanman magsanhi<br/>Matisod na muli ating lahi.<br/>',NULL,44562,5);
INSERT INTO stanza VALUES('T10402','3','Palapit nang palapit ang Kasintahan,<br/>Tinatawag nang marahan iyong pangalan;<br/>At sa araw ng pagdating Niyang biglaan,<br/>Siya at tayo''y magpapangitaan!<br/>',NULL,44563,6);
INSERT INTO stanza VALUES('T10403','beginning-note','Colossians 3:2-4<br/>',NULL,44564,1);
INSERT INTO stanza VALUES('T10403','1','Set your mind on the things that are above,<br/>Not on the things that are on earth.<br/>For you have died and your life<br/>Is hid with Christ in God.<br/>When Christ Who is our life shall appear,<br/>Then we also shall appear with Him in GLORY!<br/>(Colosas 3:2-4)<br/>',NULL,44565,2);
INSERT INTO stanza VALUES('T10403','1','Kaisipa''y ''lagak sa itaas,<br/>Di sa bagay makalupa.<br/>''Pagka''t kayo''y namatay,<br/>Buhay kay Kristo sa Diyos.<br/>Pag Kristong buhay ay nahayag,<br/>Hayag din tayo kasama Niya sa GLORIA!<br/>',NULL,44566,3);
INSERT INTO stanza VALUES('T10404','beginning-note','2 Corinthians 3:16-17<br/>',NULL,44567,1);
INSERT INTO stanza VALUES('T10404','1','Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>So turn your heart to the Lord all the day,<br/>And the veil shall be taken away.<br/>Now the Lord is the Spirit,<br/>and where the Spirit of the Lord is,<br/>There is liberty — such liberty!<br/>Whenever the heart shall turn to the Lord,<br/>The veil shall be taken away.<br/>',NULL,44568,2);
INSERT INTO stanza VALUES('T10406','1','Let us leave behind all the things of yesterday,<br/>And stretch forward to the things that are before.<br/>Let''s move on with the Lord''s recovery today,<br/>And be in the mighty flow of the Lord.<br/>',NULL,44569,1);
INSERT INTO stanza VALUES('T10406','2','Mga bagay ng kahapon ay limutin,<br/>Mga bagay hinaharap, tunguhin;<br/>Humayo na kasama ang Panginoon<br/>Sa dakilang pagbabawi Niya ngayon.<br/>',NULL,44570,2);
INSERT INTO stanza VALUES('T10407','1','Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>',NULL,44571,1);
INSERT INTO stanza VALUES('T10407','chorus','All the guilt has to go,<br/>That His life may flow — Hallelujah!<br/>Dig away, dig away, dig away,<br/>Condemnation in my heart dig away!<br/>',NULL,44572,2);
INSERT INTO stanza VALUES('T10407','2','Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>',NULL,44573,3);
INSERT INTO stanza VALUES('T10407','chorus','All my dreams have to go,<br/>That His life may flow — Hallelujah!<br/>Dig away, dig away, dig away,<br/>All my vain imaginations dig away!<br/>',NULL,44574,4);
INSERT INTO stanza VALUES('T10407','3','Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>',NULL,44575,5);
INSERT INTO stanza VALUES('T10407','chorus','All self love has to go,<br/>That His life may flow — Hallelujah!<br/>Dig away, dig away, dig away,<br/>All my troublesome emotions dig away!<br/>',NULL,44576,6);
INSERT INTO stanza VALUES('T10407','4','Dig away, dig away, dig away,<br/>All resistance in my heart dig away!<br/>Dig away, dig away, dig away,<br/>All resistance in my heart dig away!<br/>',NULL,44577,7);
INSERT INTO stanza VALUES('T10407','chorus','All self will has to go,<br/>That His life may flow — Hallelujah!<br/>Dig away, dig away, dig away,<br/>All resistance in my heart dig away!<br/>',NULL,44578,8);
INSERT INTO stanza VALUES('T10407','5','Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>',NULL,44579,9);
INSERT INTO stanza VALUES('T10407','chorus','All my hopes have to go<br/>That His life may flow — Hallelujah!<br/>Dig away, dig away, dig away,<br/>All self seeking in my heart dig away!<br/>',NULL,44580,10);
INSERT INTO stanza VALUES('T10407','6','Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>',NULL,44581,11);
INSERT INTO stanza VALUES('T10407','chorus','When my heart''s wholly free,<br/>Christ can flow through me — Hallelujah!<br/>Life can flow, praise the Lord, life can flow!<br/>From the fountain in my heart life can flow!<br/>',NULL,44582,12);
INSERT INTO stanza VALUES('T10408','1','There''s a life that''s deeper than our mind,<br/>With experience of man, yet so divine.<br/>It''s a life that knows no bounds;<br/>And with glory is crowned,<br/>It''s of depth and height and breadth unsearchable<br/>Now this life is just the living One<br/>Manifested in the Person of the Son.<br/>As the Spirit, He flows;<br/>In our spirit He grows,<br/>Growing up to be the church that He desires.<br/>',NULL,44583,1);
INSERT INTO stanza VALUES('T10408','chorus','O Lord, we''re just for Your flowing;<br/>How we need a deeper knowing!<br/>Life is why we''re here<br/>And why You''ve come in us.<br/>Turn us, Lord, turn us now;<br/>Turn us deeply — life is how<br/>You will get the church,<br/>The home You''re longing for.<br/>',NULL,44584,2);
INSERT INTO stanza VALUES('T10408','2','In the church, we all can apprehend<br/>All the riches of this life that is within.<br/>Not just shallowness with strife,<br/>But a deep and peaceful life<br/>Is just waiting to flow out, a living spring.<br/>With the saints it''s easy to be bold<br/>To pursue this life, to gain it, to lay hold.<br/>All the other things we find,<br/>Must be quickly left behind,<br/>So that only life remains for us to see.<br/>',NULL,44585,3);
INSERT INTO stanza VALUES('T10408','chorus','O Lord, we''re just for Your flowing;<br/>How we need a deeper knowing!<br/>Life is why we''re here<br/>And why You''ve come in us.<br/>Turn us, Lord, turn us now;<br/>Turn us deeply — life is how<br/>You will get the church,<br/>The home You''re longing for.<br/>',NULL,44586,4);
INSERT INTO stanza VALUES('T10408','3','Deeper, Lord, our turn must be to You;<br/>We would move by life in everything we do:<br/>All our concept refute,<br/>For Your life be absolute—<br/>Grant us grace to turn much deeper day by day.<br/>When we touch our spirit — such a thrill!<br/>This is far beyond emotion, mind, and will—<br/>It''s within our hidden part—<br/>Come, make home in all our heart;<br/>Let Your presence flow as rivers deep within.<br/>',NULL,44587,5);
INSERT INTO stanza VALUES('T10408','chorus','O Lord, we''re just for Your flowing;<br/>How we need a deeper knowing!<br/>Life is why we''re here<br/>And why You''ve come in us.<br/>Turn us, Lord, turn us now;<br/>Turn us deeply — life is how<br/>You will get the church,<br/>The home You''re longing for.<br/>',NULL,44588,6);
INSERT INTO stanza VALUES('T10409','1','Satan says, "Ha! Wait till the meeting comes,<br/>Wait till the meeting comes,<br/>Wait till the meeting comes;<br/>Be depressed and wait till the meeting comes,<br/>I''ve got you down today."<br/>"Wait till the meeting comes,<br/>Wait till the meeting comes;<br/>Be depressed and wait till the meeting comes,<br/>I''ve got you down today."<br/>',NULL,44589,1);
INSERT INTO stanza VALUES('T10409','2','Time does not establish the fellowship,<br/>''Stablish the fellowship,<br/>''Stablish the fellowship,<br/>Time does not establish the fellowship—<br/>This is just his lie.<br/>This is just his lie,<br/>This is just his lie;<br/>Time does not establish the fellowship—<br/>This is just his lie.<br/>',NULL,44590,2);
INSERT INTO stanza VALUES('T10409','3','We can promptly conquer the enemy,<br/>Conquer the enemy,<br/>Conquer the enemy;<br/>We can promptly conquer the enemy,<br/>If we use the blood.<br/>If we use the blood,<br/>If we use the blood;<br/>We can promptly conquer the enemy,<br/>If we use the blood.<br/>',NULL,44591,3);
INSERT INTO stanza VALUES('T10409','4','Overcomers know how to use the blood,<br/>Know how to use the blood,<br/>Know how to use the blood;<br/>Overcomers know how to use the blood—<br/>Giants they are not.<br/>Giants they are not,<br/>Giants they are not;<br/>Overcomers know how to use the blood—<br/>Giants they are not.<br/>',NULL,44592,4);
INSERT INTO stanza VALUES('T10409','5','Normal Christian; that''s all we want to be,<br/>That''s all we want to be,<br/>That''s all we want to be;<br/>Normal Christian; that''s all we want to be,<br/>Know how to use the blood.<br/>Know how to use the blood,<br/>Know how to use the blood;<br/>Normal Christian; that''s all we want to be,<br/>Know how to use the blood.<br/>',NULL,44593,5);
INSERT INTO stanza VALUES('T10409','6','By the blood we maintain the fellowship,<br/>Maintain the fellowship,<br/>Maintain the fellowship;<br/>By the blood we maintain the fellowship,<br/>Trusting not in time.<br/>Trusting not in time,<br/>Trusting not in time;<br/>By the blood we maintain the fellowship,<br/>Trusting not in time.<br/>',NULL,44594,6);
INSERT INTO stanza VALUES('T10410','1','"Amen, Lord Jesus! Amen, Lord!"<br/>Yes, "Amen" all the time.<br/>It''s "Amen" to your written Word,<br/>"Amen" to every line.<br/>It''s "Amen" too whene''er you speak,<br/>You know what''s best for me.<br/>So I will still say, "Amen, Lord!"<br/>Whatever it may be.<br/>',NULL,44595,1);
INSERT INTO stanza VALUES('T10412','1','We''ll say "Amen", we''ll say "Amen",<br/>To the blood, to the blood;<br/>For the guilt assailing,<br/>It is so prevailing,<br/>Precious blood, precious blood!<br/>',NULL,44596,1);
INSERT INTO stanza VALUES('T10412','2','We''ll say "Amen", we''ll say "Amen",<br/>To the Word, to the Word.<br/>Every word that''s written,<br/>Every word that''s spoken—<br/>"Amen, Lord", "Amen, Lord".<br/>',NULL,44597,2);
INSERT INTO stanza VALUES('T10412','3','We''ll say "Amen", we''ll say "Amen",<br/>To the church, to the church,<br/>Following the footsteps,<br/>Following the footsteps<br/>Of the flock, of the flock.<br/>',NULL,44598,3);
INSERT INTO stanza VALUES('T10412','4','We''ll say "Amen", we''ll say "Amen",<br/>To each trial, to each trial,<br/>All the circumstances<br/>Are the golden chances<br/>To gain Christ, to gain Christ.<br/>',NULL,44599,4);
INSERT INTO stanza VALUES('T10413','1','I''m just a little flower<br/>With open face;<br/>I''m fully turned to God,<br/>Receiving grace.<br/>I don''t know how to try—<br/>This is my case—<br/>I''m just a lily trusting God.<br/>',NULL,44600,1);
INSERT INTO stanza VALUES('T10413','2','There''s nothing on this earth<br/>That I desire.<br/>There''s no experience<br/>That I require.<br/>I only want one thing—<br/>(Satan''s liar!)<br/>To be a lily trusting God.<br/>',NULL,44601,2);
INSERT INTO stanza VALUES('T10413','3','If when I trust in God<br/>I''m put to shame;<br/>If when I walk with God<br/>I come out lame;<br/>These things don''t bother me;<br/>I''m not to blame—<br/>Since I''m a lily trusting God.<br/>',NULL,44602,3);
INSERT INTO stanza VALUES('T10413','4','With all your worrying<br/>To clothe yourself;<br/>So many lies you''ve told<br/>To gather wealth;<br/>And though you''ve gotten rich,<br/>You''ve lost your health—<br/>Just be a lily trusting God.<br/>',NULL,44603,4);
INSERT INTO stanza VALUES('T10413','5','It seems you know so much,<br/>But yet you fall;<br/>And though you talk so much<br/>Yet you won''t call;<br/>So what''s the use of it,<br/>For after all—<br/>Just be a lily trusting God.<br/>',NULL,44604,5);
INSERT INTO stanza VALUES('T10413','6','So please don''t bother me<br/>With all your fears;<br/>You strive and try so hard<br/>With sweat and tears;<br/>Have faith in Jesus Christ—<br/>He''s always near!<br/>Just be a lily trusting God.<br/>',NULL,44605,6);
INSERT INTO stanza VALUES('T10413','7','Yes, please don''t bother me;<br/>I''m growing fine.<br/>Oh, please don''t share with me<br/>What''s on your mind.<br/>I may not know so much,<br/>But still I shine.<br/>I am a lily trusting God.<br/>',NULL,44606,7);
INSERT INTO stanza VALUES('T10413','8','And please don''t bother me<br/>With all your cares;<br/>Don''t make me listen to<br/>Your begging prayers;<br/>Our God is great—<br/>He really cares!<br/>Just be a lily trusting God.<br/>',NULL,44607,8);
INSERT INTO stanza VALUES('T10413','9','It seems that I don''t care<br/>So much for you;<br/>But if you knew my heart,<br/>I really do;<br/>Yet lilies don''t know how<br/>To fret and stew—<br/>I''m just a lily — How ''bout you?<br/>',NULL,44608,9);
INSERT INTO stanza VALUES('T10414','1','Trusting in the Lord thy God,<br/>Onward go! Onward go!<br/>Holding fast His promised word;<br/>Onward go!<br/>Ne''er deny His worthy name,<br/>Though it brings reproach and shame,<br/>Spreading still His wondrous fame,<br/>Onward go!<br/>',NULL,44609,1);
INSERT INTO stanza VALUES('T10414','2','Has He called thee to the plough?<br/>Onward go? Onward go!<br/>Night is coming, serve Him now;<br/>Onward go!<br/>Faith and love in service blend,<br/>On His mighty arm depend,<br/>Standing fast until the end,<br/>Onward go!<br/>',NULL,44610,2);
INSERT INTO stanza VALUES('T10414','3','Has He giv''n thee golden grain?<br/>Onward go! Onward go!<br/>Sow, and thou shalt reap again;<br/>Onward go!<br/>To thy Master''s gate repair,<br/>Watching be and waiting there;<br/>He will hear and answer prayer,<br/>Onward go!<br/>',NULL,44611,3);
INSERT INTO stanza VALUES('T10414','4','In this little moment then,<br/>Onward go! Onward go!<br/>In thy ways acknowledge Him;<br/>Onward go!<br/>Let His mind be found in thee,<br/>Let His will thy pleasure be;<br/>Thus in life and liberty,<br/>Onward go!<br/>',NULL,44612,4);
INSERT INTO stanza VALUES('T10415','1','The race before us we can run,<br/>With every hindering weight be done—<br/>Look away, look away, look away unto Him.<br/>With joy we see the goal in view<br/>And know that He will take us through—<br/>Look away, look away, look away unto Him.<br/>He ran the race before us — He won! He won!<br/>Victorious now at God''s right hand,<br/>He''s bringing us to glory.<br/>Away, away, O look away to Jesus.<br/>Away, away, O look away to Jesus.<br/>',NULL,44613,1);
INSERT INTO stanza VALUES('T10416','1','On your mark, get set, run the race of life;<br/>There''s a prize awaiting you.<br/>Lay aside every weight, each besetting sin,<br/>Keep the heav''nly goal in view.<br/>Witnesses all around watching as you run,<br/>Never falter, never fall;<br/>On your mark, get set, run the race of life,<br/>There''s a prize awaiting you.<br/>',NULL,44614,1);
INSERT INTO stanza VALUES('T10418','1','The Lord has shown us the way<br/>Within the church today—<br/>It''s laboring, laboring, laboring on Christ.<br/>Christ is the Canaan land;<br/>In Him we boldly stand,<br/>While laboring, laboring, laboring on Christ.<br/>',NULL,44615,1);
INSERT INTO stanza VALUES('T10418','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>Through laboring, laboring, laboring on Christ.<br/>',NULL,44616,2);
INSERT INTO stanza VALUES('T10418','2','The way that God has planned<br/>To labor on the land<br/>Is "Amen, Lord! Amen, Lord! Amen to Your Word!"<br/>Whene''er He speaks today,<br/>Whatever He may say,<br/>It''s "Amen, Lord! Amen, Lord! Amen to Your Word!"<br/>',NULL,44617,3);
INSERT INTO stanza VALUES('T10418','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>By "Amen, Lord! Amen, Lord! Amen to Your Word!"<br/>',NULL,44618,4);
INSERT INTO stanza VALUES('T10418','3','The Lord has also shown<br/>The land we''ll fully own<br/>By following, following, following the church.<br/>Where''er the Body goes,<br/>Howe''er the Spirit flows,<br/>It''s following, following, following the church.<br/>',NULL,44619,5);
INSERT INTO stanza VALUES('T10418','chorus','On to victory! On to victory!<br/>Cries our great Commander — On!<br/>We''ll move at His command<br/>And now possess the land<br/>By following, following, following the church.<br/>',NULL,44620,6);
INSERT INTO stanza VALUES('T10419','1','Let''s march forward with God!<br/>Let''s march forward with God!<br/>God''s moving fast, we should not lax,<br/>Let''s march forward with God;<br/>Let''s march forward with God!<br/>Let''s march forward with God!<br/>Oh, let''s move on with spirit strong.<br/>Let''s march forward with God!<br/>',NULL,44621,1);
INSERT INTO stanza VALUES('T10421','1','Young people, rise up forward!<br/>For His Kingdom, onward!<br/>He is calling you and me,<br/>To follow Him today.<br/>With spirit simple and strong,<br/>Answer His call, strive on.<br/>The choice for His move today—<br/>''Tis young people who dare.<br/>',NULL,44622,1);
INSERT INTO stanza VALUES('T10422','1','We to the throne of grace boldly come<br/>For help to obtain mercy and grace;<br/>And not to round the cross and adore,<br/>For my Lord is not at that place.<br/>From the fetters of death He came forth,<br/>Risen, ascended was He!<br/>And so now from the throne of grace,<br/>His life flows to supply me.<br/>',NULL,44623,1);
INSERT INTO stanza VALUES('T10422','2','Through heav''nly ladder my spirit''s joined<br/>To the throne of grace though high above;<br/>Now to the spirit I always turn,<br/>Cease from wand''ring in soulish love.<br/>Jesus my Lord is the great High Priest,<br/>Full of compassion is He!<br/>Through Him before God''s presence come,<br/>To the end He will save me.<br/>',NULL,44624,2);
INSERT INTO stanza VALUES('T10422','3','Oh, praise the Lord, my High Priest is He,<br/>Melchizedec''s order was ordained;<br/>And now I fight for God''s benefit,<br/>He intercedes and pow''r regains.<br/>Till I have overcome all the foes,<br/>With bread and wine I''d be fed!<br/>O, what freedom and liberty—<br/>Perfect salvation is led!<br/>',NULL,44625,3);
INSERT INTO stanza VALUES('T10423','1','Following Jesus, ever, day by day,<br/>Nothing can harm me when He leads the way<br/>Sunshine or shadow, whate''er befall,<br/>Jesus my Savior is my all in all.<br/>',NULL,44626,1);
INSERT INTO stanza VALUES('T10423','2','Sunod kay Hesus sa araw-araw,<br/>Di mapahamak kung Siya''y kasama;<br/>Anumang aking kalagayan,<br/>Hesus Panginoo''y aking lahat.<br/>',NULL,44627,2);
INSERT INTO stanza VALUES('T10424','1','Forward, forward stretching forth we go,<br/>Never turn your back.<br/>Forward, forward stretching forth we go,<br/>Ever onward go.<br/>Who holds the plough and looketh back,<br/>Not God''s Kingdom fit.<br/>Forward, forward stretching forth we go,<br/>Our Lord leads the way.<br/>',NULL,44628,1);
INSERT INTO stanza VALUES('T10424','2','Sulong, sulong tayo''y sumulong,<br/>Huwag nang lilingon.<br/>Sulong, sulong tayo''y sumulong,<br/>Huwag nang uurong.<br/>Hawak araro''t lumingon pa,<br/>Hindi angkop na.<br/>Kaharian nasa unahan,<br/>Huwag nang urungan.<br/>',NULL,44629,2);
INSERT INTO stanza VALUES('T10425','1','Sometimes the road is dark and dreary,<br/>So dark my way I cannot see;<br/>But I know I''m not alone,<br/>For Jesus always walks with me.<br/>I often hear Him say, "My child,<br/>I will always hold your hand;<br/>And in your darkest hour,<br/>I will closely by you stand."<br/>He has promised to go with me;<br/>And ne''er forsake me here.<br/>Though the storms may rage about me,<br/>He''ll be there to calm my fear.<br/>Fully on Him I am depending,<br/>Till I get to glory land;<br/>I will reach my destination,<br/>For I know He holds my hand.<br/>',NULL,44630,1);
INSERT INTO stanza VALUES('T10426','1','I don''t know about tomorrow,<br/>I just live from day to day.<br/>I don''t borrow from its sunshine,<br/>For its skies may turn to gray.<br/>I don''t worry o''er the future,<br/>For I know what Jesus said,<br/>And today I''ll walk beside Him,<br/>For He knows what is ahead.<br/>',NULL,44631,1);
INSERT INTO stanza VALUES('T10426','chorus','Many things about tomorrow,<br/>I don''t seem to understand;<br/>But I know who holds tomorrow,<br/>And I know who holds my hand.<br/>',NULL,44632,2);
INSERT INTO stanza VALUES('T10426','2','I don''t know about tomorrow,<br/>It may bring me poverty;<br/>But the One who feeds the sparrow,<br/>Is the One who lives in me.<br/>And the path that be my portion,<br/>May be through the flame or flood;<br/>But His presence goes before me,<br/>Bravely His path I will trod.<br/>',NULL,44633,3);
INSERT INTO stanza VALUES('T10426','chorus','Many things about tomorrow,<br/>I don''t seem to understand;<br/>But I know who holds tomorrow,<br/>And I know who holds my hand.<br/>',NULL,44634,4);
INSERT INTO stanza VALUES('T10427','1','Jesus said to us, He is the True Vine,<br/>We are the branches of this True Vine,<br/>O Hallelujah! O Hallelujah!<br/>We His branches are.<br/>',NULL,44635,1);
INSERT INTO stanza VALUES('T10427','2','We abide in Him, He abides in us,<br/>Thus we are able to bear Him much fruit.<br/>O Hallelujah! O Hallelujah!<br/>We bear Him much fruit.<br/>',NULL,44636,2);
INSERT INTO stanza VALUES('T10427','3','Get in touch with Him, Ever in Him abide.<br/>Bear much fruit, Father is glorified.<br/>O Hallelujah! O Hallelujah!<br/>Father''s glorified.<br/>',NULL,44637,3);
INSERT INTO stanza VALUES('T10427','1','Sabi ni Hesus Punong Ubas Siya,<br/>Tayo naman ang mga sanga,<br/>O Aleluya! O Aleluya!<br/>Tayo ang sanga!<br/>',NULL,44638,4);
INSERT INTO stanza VALUES('T10427','2','Nananahanan sa isa''t isa,<br/>Siya''y sa atin, tayo ay Kanya.<br/>O Aleluya! Magkakabunga,<br/>Maraming bunga.<br/>',NULL,44639,5);
INSERT INTO stanza VALUES('T10427','3','Sa espiritu''y magsalamuha<br/>Mamunga''t l''walhatiin Ama,<br/>O Aleluya! O Aleluya!<br/>Gloria sa Ama!<br/>',NULL,44640,6);
INSERT INTO stanza VALUES('T10429','1','How long has it been since you talked with the Lord?<br/>And told Him your heart''s hidden secret.<br/>How long since you prayed?<br/>How long since you stayed<br/>On your knees till the light shone through?<br/>How long has it been since your mind felt at ease?<br/>How long since your heart knew no burden?<br/>Can you call Him your friend?<br/>How long has it been since you knew that He cared for you?<br/>',NULL,44641,1);
INSERT INTO stanza VALUES('T10430','1','Though often we waver and move,<br/>But He is unchanging and sure;<br/>His promises ne''er empty prove,<br/>More than the heav''n and earth endure.<br/>',NULL,44642,1);
INSERT INTO stanza VALUES('T10430','2','Though we''re beset with flick''ring soul,<br/>But He would ne''er leave us alone;<br/>Though being left, yet on us call,<br/>More truthful friend I could not own!<br/>',NULL,44643,2);
INSERT INTO stanza VALUES('T10430','3','He''ll never leave us in despair,<br/>All we''ve committed Him, He''ll care;<br/>Since His love to us He did bare,<br/>Then to the end His love would dare.<br/>',NULL,44644,3);
INSERT INTO stanza VALUES('T10430','4','Unto the end! We treat Him sore,<br/>Neglect and hurt Him, change our heart;<br/>And other idols we adore,<br/>Not feeling sorry e''en in part.<br/>',NULL,44645,4);
INSERT INTO stanza VALUES('T10430','5','And when these idols fell and cleft,<br/>Taken with sorrow, come to seek;<br/>Him Whom we have betrayed and left,<br/>This everlasting friend so meek!<br/>',NULL,44646,5);
INSERT INTO stanza VALUES('T10430','6','He then receive and comfort us,<br/>And draw us unto Himself nigh;<br/>As nothing happened in the past,<br/>Time never can His love defy.<br/>',NULL,44647,6);
INSERT INTO stanza VALUES('T10430','7','Oh Lord, toward this love of Thine,<br/>We cannot help but shout with praise;<br/>Stronger than death, patient and kind,<br/>Touched our heart, grateful praises raise!<br/>',NULL,44648,7);
INSERT INTO stanza VALUES('T10430','1','Paurong-sulong man tayo,<br/>Nguni''t Siya''y di nagbabago;<br/>Pangako Niya''y di makaltas,<br/>Walang katulad Niyang wagas.<br/>',NULL,44649,8);
INSERT INTO stanza VALUES('T10430','2','Kahit tayo''y laging suwail,<br/>Ayaw Niya tayong itakwil;<br/>Tayo''y hinanap, hinintay,<br/>Walang kaibigang sintunay.<br/>',NULL,44650,9);
INSERT INTO stanza VALUES('T10430','3','Di Niya tayo bibiguin,<br/>Tiwala nati''y tutupdin;<br/>Yamang tayo''y inibig Niya,<br/>Lubos tayong inibig nga.<br/>',NULL,44651,10);
INSERT INTO stanza VALUES('T10430','4','Di natin Siya pinapansin,<br/>Siya''y nilimot, sinaktan din;<br/>May diyus-diyosang sinasamba,<br/>Di pa nagsisi sa Kanya.<br/>',NULL,44652,11);
INSERT INTO stanza VALUES('T10430','5','Pag nabigo sa diyus-diyosan<br/>At magbalik-loob naman;<br/>Sa binigo natin noon,<br/>Kaibigang habang-panahon!<br/>',NULL,44653,12);
INSERT INTO stanza VALUES('T10430','6','Muli Niya tayong tinanggap,<br/>Sa Kanya tayo''y nilangkap;<br/>Wari ba''y walang nangyari,<br/>Tapat Siya tulad nang dati.<br/>',NULL,44654,13);
INSERT INTO stanza VALUES('T10430','7','Panginoon, purihin Ka,<br/>Sa pag-ibig Mong dakila;<br/>Daig ang anumang puwersa,<br/>Puso nami''y humahanga.<br/>',NULL,44655,14);
INSERT INTO stanza VALUES('T10431','1','Could I my way preserve,<br/>Yet see Thy will unharmed?<br/>Could I direct and choose,<br/>Without alt''ring Thy path?<br/>',NULL,44656,1);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44657,2);
INSERT INTO stanza VALUES('T10431','2','Lest there be other loves<br/>Beside my precious Lord;<br/>I dare not muse in spring,<br/>Nor care for hundred flow''rs.<br/>',NULL,44658,3);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44659,4);
INSERT INTO stanza VALUES('T10431','3','I''ve asked the snow to freeze;<br/>My lurking starry spark;<br/>Come tempest, stormy rain—<br/>My other longing drown.<br/>',NULL,44660,5);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44661,6);
INSERT INTO stanza VALUES('T10431','4','Come, try and purge me now,<br/>And strip and smelt me, Lord;<br/>Even I would be pressed,<br/>Or be locked up and bound.<br/>',NULL,44662,7);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44663,8);
INSERT INTO stanza VALUES('T10431','5','If there a longing be,<br/>Come Thou and "rob" my hopes;<br/>If I would yonder fly,<br/>Come Thou and rid my wings.<br/>',NULL,44664,9);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44665,10);
INSERT INTO stanza VALUES('T10431','6','Give me boldness to face,<br/>The way Thou hast for me;<br/>Bring all my loves to naught,<br/>And bless with things I hate.<br/>',NULL,44666,11);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44667,12);
INSERT INTO stanza VALUES('T10431','7','Oh, spare me not, my Lord,<br/>Nor stand Thou calmly still;<br/>All self-made choices void,<br/>Only Thy will to take.<br/>',NULL,44668,13);
INSERT INTO stanza VALUES('T10431','chorus','Thou hast had the "quick" and "slow",<br/>All directions Thou lay hold;<br/>And submitting to Thy way,<br/>Humbly walking in Thy will.<br/>',NULL,44669,14);
INSERT INTO stanza VALUES('T10501','1','We from the law to Christ have turned;<br/>To trust in Him by grace we''ve learned.<br/>And since His glory we''ve discerned<br/>We only care for Christ!<br/>',NULL,44670,1);
INSERT INTO stanza VALUES('T10501','chorus','We only care for Christ!<br/>We only care for Christ!<br/>And since His glory we''ve discerned<br/>We only care for Christ!<br/>',NULL,44671,2);
INSERT INTO stanza VALUES('T10501','2','Christ brings us to God''s house to dwell,<br/>Where all day long His praises swell.<br/>O hallelujah! None can tell<br/>How lovely is God''s house!<br/>',NULL,44672,3);
INSERT INTO stanza VALUES('T10501','chorus','How lovely is God''s house!<br/>How lovely is God''s house!<br/>O hallelujah! None can tell<br/>How lovely is God''s house!<br/>',NULL,44673,4);
INSERT INTO stanza VALUES('T10501','3','The house enlarged the city is;<br/>The joy of all the nations ''tis,<br/>The place for God to rule is this<br/>On Zion''s holy hill.<br/>',NULL,44674,5);
INSERT INTO stanza VALUES('T10501','chorus','On Zion''s holy hill,<br/>On Zion''s holy hill,<br/>The place for God to rule is this<br/>On Zion''s holy hill.<br/>',NULL,44675,6);
INSERT INTO stanza VALUES('T10501','4','From Zion Christ will take the earth<br/>And reign and fill its souls with mirth.<br/>All nations will proclaim His worth,<br/>Break forth and sing for joy.<br/>',NULL,44676,7);
INSERT INTO stanza VALUES('T10501','chorus','Break forth and sing for joy,<br/>Break forth and sing for joy,<br/>All nations will proclaim His worth,<br/>Break forth and sing for joy.<br/>',NULL,44677,8);
INSERT INTO stanza VALUES('T10501','5','Christ — house — the city — earth, we see;<br/>Thus God''s great plan fulfilled will be.<br/>O brothers, let us utterly<br/>Be one with Him for this.<br/>',NULL,44678,9);
INSERT INTO stanza VALUES('T10501','chorus','Be one with Him for this,<br/>Be one with Him for this,<br/>O brothers, let us utterly<br/>Be one with Him for this.<br/>',NULL,44679,10);
INSERT INTO stanza VALUES('T10502','beginning-note','Psalm 126<br/>',NULL,44680,1);
INSERT INTO stanza VALUES('T10502','1','When God turned the captivity of Zion,<br/>Then were we like them that dream, full of praises,<br/>Our mouth and tongues filled with laughter and singing,<br/>For the Lord has done great things for us.<br/>Lord, turn many more to Zion.<br/>As streams of the south o''erflow!<br/>See the ancient men are weeping,<br/>As the young ones raise shouts of joy.<br/>And now we all labor and sing together,<br/>They who now sow in tears shall reap in joy.<br/>Hallelujah, we''ll bring the sheaves to Zion;<br/>Let all glory and praise be to God!<br/>',NULL,44681,2);
INSERT INTO stanza VALUES('T10502','1','Nang bihag, sa Sion Diyos nagpabalik,<br/>Nagpupuri, tulad nang nanaginip,<br/>Dila''y punong awit, bibig pagtawa;<br/>Dakilang bagay ginawa Niya!<br/>Ang nanumbalik damihan,<br/>Gaya''ng Batis Timugan.<br/>Nagsihasik nang may luha,<br/>Magsiani nang may saya.<br/>Ngayon ang lumabas humihibik,<br/>Nagdala ng binhing ihahasik.<br/>Aleluya, babalik nang may ani,<br/>Sa Sion, kay Jehovah''y l''walhati!<br/>',NULL,44682,3);
INSERT INTO stanza VALUES('T10503','beginning-note','Ezra 1<br/>',NULL,44683,1);
INSERT INTO stanza VALUES('T10503','1','Down in Babylon, in captivity,<br/>Oh, the Lord has stirred our spirit up!<br/>Scattered everywhere, without unity,<br/>Oh, the Lord has stirred our spirit up!<br/>Stirred up! Stirred up!<br/>Oh, the Lord has stirred our spirit up!<br/>Stirred up! Stirred up!<br/>Oh, the Lord has stirred our spirit up!<br/>',NULL,44684,2);
INSERT INTO stanza VALUES('T10503','2','Up from Babylon, where the sects abound,<br/>From division we must all rise up!<br/>Brothers, Babylon''s not the proper ground;<br/>From division we must all rise up!<br/>Rise up! Rise up!<br/>From division we must all rise up!<br/>Rise up! Rise up!<br/>From division we must all rise up!<br/>',NULL,44685,3);
INSERT INTO stanza VALUES('T10503','3','To Jerusalem, from captivity,<br/>God is with us, let us all go up!<br/>To the one unique ground of unity,<br/>God is with us, let us all go up!<br/>Go up! Go up!<br/>God is with us, let us all go up!<br/>Go up! Go up!<br/>God is with us, let us all go up!<br/>',NULL,44686,4);
INSERT INTO stanza VALUES('T10503','4','Platter full of Christ,<br/>bowls with Spirit filled—<br/>All the vessels of the Lord bring up!<br/>Bring them to the church<br/>as the Lord has willed—<br/>All the vessels of the Lord bring up!<br/>Bring up! Bring up!<br/>All the vessels of the Lord bring up!<br/>Bring up! Bring up!<br/>All the vessels of the Lord bring up!<br/>',NULL,44687,5);
INSERT INTO stanza VALUES('T10503','5','In Jerusalem, chosen of the Lord,<br/>Now the temple of the Lord build up!<br/>Serve with all the saints, share in one accord,<br/>Now the temple of the Lord build up!<br/>Build up! Build up!<br/>Now the temple of the Lord build up!<br/>Build up! Build up!<br/>Now the temple of the Lord build up!<br/>',NULL,44688,6);
INSERT INTO stanza VALUES('T10504','beginning-note','Psalm 132<br/>',NULL,44689,1);
INSERT INTO stanza VALUES('T10504','1','This is My rest forever;<br/>Here will I dwell,<br/>For the Lord hath chosen Zion,<br/>He hath desired it for His habitation.<br/>He will abundantly bless her provision:<br/>He will satisfy her poor with bread.<br/>He will clothe her priests with salvation,<br/>And her saints shall shout aloud for joy.<br/>',NULL,44690,2);
INSERT INTO stanza VALUES('T10505','beginning-note','Isaiah 51:11<br/>',NULL,44691,1);
INSERT INTO stanza VALUES('T10505','1','Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>They shall obtain gladness and joy;<br/>And sorrow and mourning shall flee away.<br/>Therefore the redeemed of the Lord shall return,<br/>And come with singing unto Zion;<br/>And everlasting joy shall be upon their head.<br/>',NULL,44692,2);
INSERT INTO stanza VALUES('T10507','beginning-note','Psalm 48<br/>',NULL,44693,1);
INSERT INTO stanza VALUES('T10507','1','O walk ''bout, walk about Zion,<br/>Go round about her in love.<br/>O walk ''bout, walk about Zion,<br/>And count the towers thereof,<br/>And count the towers thereof.<br/>',NULL,44694,2);
INSERT INTO stanza VALUES('T10507','2','O set your heart on her bulwarks,<br/>O set your heart on her walls,<br/>O set your heart on her bulwarks,<br/>Consider her palaces,<br/>Consider her palaces.<br/>',NULL,44695,3);
INSERT INTO stanza VALUES('T10507','3','In elevation how beauteous,<br/>The joy of all the earth!<br/>In elevation how beauteous<br/>Is Zion, that city of worth!<br/>Is Zion, that city of worth!<br/>',NULL,44696,4);
INSERT INTO stanza VALUES('T10507','4','O there''s a river in Zion<br/>That flows so deep and so broad.<br/>O how the streams of that river<br/>Make glad the city of God!<br/>Make glad the city of God!<br/>',NULL,44697,5);
INSERT INTO stanza VALUES('T10507','5','Praise waiteth for Thee, Lord, in Zion,<br/>Praise waiteth, O God, for Thee,<br/>Praise waiteth for Thee, Lord, in Zion,<br/>For Zion is filled with Thee,<br/>For Zion is filled with Thee.<br/>',NULL,44698,6);
INSERT INTO stanza VALUES('T10507','6','How great the Lord is in Zion,<br/>How greatly to be praised,<br/>How great He is in that city<br/>Which over the earth is raised,<br/>Which over the earth is raised.<br/>',NULL,44699,7);
INSERT INTO stanza VALUES('T10507','7','O bless the Lord out of Zion,<br/>O let His praises swell,<br/>O bless the Lord out of Zion,<br/>Ye who in Jerusalem dwell,<br/>Ye who in Jerusalem dwell.<br/>',NULL,44700,8);
INSERT INTO stanza VALUES('T10507','8','The Lord bless thee out of Zion,<br/>The Lord bless thee o''er and o''er!<br/>The Lord bless thee out of Zion<br/>With life forevermore!<br/>With life forevermore!<br/>',NULL,44701,9);
INSERT INTO stanza VALUES('T10507','9','Behold how good and how pleasant<br/>With all the brethren to be!<br/>Behold how good and how pleasant<br/>To dwell in unity!<br/>To dwell in unity!<br/>',NULL,44702,10);
INSERT INTO stanza VALUES('T10507','10','O tell it to all gen''rations,<br/>O tell it to all who''ll come,<br/>O tell it to all gen''rations,<br/>The Spirit and Bride say, "Come!"<br/>The Spirit and Bride say, "Come!"<br/>',NULL,44703,11);
INSERT INTO stanza VALUES('T10509','beginning-note','Revelation 2-3<br/>',NULL,44704,1);
INSERT INTO stanza VALUES('T10509','1','In Revelation two and three,<br/>The seven local churches see:<br/>The lessons there for you and me<br/>Are for the Lord''s recovery.<br/>',NULL,44705,2);
INSERT INTO stanza VALUES('T10509','2','The words to them are words to us,<br/>So that the church be glorious,<br/>And all their warnings we must heed<br/>So that the Lord can meet His need.<br/>',NULL,44706,3);
INSERT INTO stanza VALUES('T10509','3','To Ephesus, the word is clear:<br/>"To your first love you''re not so near;<br/>You''ve left to work so far away;<br/>Repent, return to Him today."<br/>',NULL,44707,4);
INSERT INTO stanza VALUES('T10509','4','Thus, we must all turn back to Him,<br/>Leave other loves, for these are sin.<br/>Oh, let us hearken to His call—<br/>If we miss this, we''ve missed it all!<br/>',NULL,44708,5);
INSERT INTO stanza VALUES('T10509','5','Then unto Smyrna, suffering, sore—<br/>"You have been tried, but something more—<br/>Be faithful unto death," we''re told<br/>(Not just of body but of soul).<br/>',NULL,44709,6);
INSERT INTO stanza VALUES('T10509','6','Be faithful till what''s natural dies;<br/>Your circumstances don''t despise;<br/>The Lord has sent them all to you<br/>To prove that your first love is true.<br/>',NULL,44710,7);
INSERT INTO stanza VALUES('T10509','7','From Pergamos we clearly see<br/>The world has wed Christianity!<br/>And faithful Antipas did fall—<br/>He dared to stand against it all.<br/>',NULL,44711,8);
INSERT INTO stanza VALUES('T10509','8','To wed the world we all must fear:<br/>His spoken word will save us here—<br/>If to His speaking we give heed,<br/>We''ll separated be indeed.<br/>',NULL,44712,9);
INSERT INTO stanza VALUES('T10509','9','Then Thyatira comes at length:<br/>Her mixture with the world her strength.<br/>Fine flour leavened by the yeast,<br/>A harlot riding on a beast.<br/>',NULL,44713,10);
INSERT INTO stanza VALUES('T10509','10','Lord, we are mixed but hardly know;<br/>To us this mixture fully show.<br/>Each added thing we will refute<br/>Until we''re wholly absolute.<br/>',NULL,44714,11);
INSERT INTO stanza VALUES('T10509','11','And then from Sardis, we can know<br/>Life is the way that we must go!<br/>She says she''s living, but she''s dead;<br/>She needs to touch the Lord instead.<br/>',NULL,44715,12);
INSERT INTO stanza VALUES('T10509','12','Lord, take us all the way to life<br/>To overcome the deadness rife.<br/>Away from deadness we would flee<br/>That full of life we''ll always be.<br/>',NULL,44716,13);
INSERT INTO stanza VALUES('T10509','13','Now Philadelphia comes at last;<br/>That which she has she should hold fast—<br/>The brothers'' love, the name, the word;<br/>This church has satisfied the Lord.<br/>',NULL,44717,14);
INSERT INTO stanza VALUES('T10509','14','We as the brothers all are one;<br/>We''re one by life, and life alone.<br/>If we His word and name do keep<br/>A glorious building God will reap.<br/>',NULL,44718,15);
INSERT INTO stanza VALUES('T10509','15','Laodicea warns us all:<br/>From Philadelphia some will fall.<br/>By saying, "I am rich," it''s then<br/>The Lord is outside wanting in.<br/>',NULL,44719,16);
INSERT INTO stanza VALUES('T10509','16','Lukewarmness we must ever spurn<br/>And in the spirit always burn,<br/>The inward life experience gain,<br/>And pay the price with Him to reign.<br/>',NULL,44720,17);
INSERT INTO stanza VALUES('T10509','17','Lord, shine Your light on us today<br/>That we may fully go Your way;<br/>Anoint our eyes and let us see<br/>So You can have recovery.<br/>',NULL,44721,18);
INSERT INTO stanza VALUES('T10510','1','In spirit, in spirit, in spirit, in spirit,<br/>What a great mystery the Lord reveals to us!<br/>In spirit see the church, see the world in spirit!<br/>Let''s cast out religion, Holy City for us.<br/>',NULL,44722,1);
INSERT INTO stanza VALUES('T10510','chorus','In spirit, in spirit, in spirit, in spirit,<br/>Drop the world, religion, prepare the Bride,<br/>The Lord shall come!<br/>',NULL,44723,2);
INSERT INTO stanza VALUES('T10510','2','In spirit, I can see the Lord''s eyes as the flame,<br/>All my hidden secrets, Oh, how they embarrass!<br/>Oh, my Lord, I repent! Burn away all my shame,<br/>Drop the world thoroughly, let my feet shine as brass.<br/>',NULL,44724,3);
INSERT INTO stanza VALUES('T10510','chorus','In spirit, in spirit, in spirit, in spirit,<br/>Drop the world, religion, prepare the Bride,<br/>The Lord shall come!<br/>',NULL,44725,4);
INSERT INTO stanza VALUES('T10510','3','Sev''n spirits, seven stars, in spirit I perceive,<br/>How can I be so dead? Stars shine bright, spirits strong!<br/>All doctrines lay aside, spirit pow''r to receive;<br/>Religion cast aside, spirit burns bright and strong!<br/>',NULL,44726,5);
INSERT INTO stanza VALUES('T10510','chorus','In spirit, in spirit, in spirit, in spirit,<br/>Drop the world, religion, prepare the Bride,<br/>The Lord shall come!<br/>',NULL,44727,6);
INSERT INTO stanza VALUES('T10510','4','In spirit, the key of the Kingdom I maintain,<br/>Pray-read to keep Thy word, call to worship Thy name,<br/>Love wraps up all the wounds, newness rids wrinkles-stain;<br/>Be pillars, crown possess, new city, gain new name!<br/>',NULL,44728,7);
INSERT INTO stanza VALUES('T10510','chorus','In spirit, in spirit, in spirit, in spirit,<br/>Drop the world, religion, prepare the Bride,<br/>The Lord shall come!<br/>',NULL,44729,8);
INSERT INTO stanza VALUES('T10510','5','In spirit say Amen, in spirit there''s one flow,<br/>The spirit has new start, cling to oldness I''ll not!<br/>Lord, I''ll be absolute, pay the price, let all know<br/>I''m filled with spirit enjoying Him as my lot!<br/>',NULL,44730,9);
INSERT INTO stanza VALUES('T10510','chorus','In spirit, in spirit, in spirit, in spirit,<br/>Drop the world, religion, prepare the Bride,<br/>The Lord shall come!<br/>',NULL,44731,10);
INSERT INTO stanza VALUES('T10510','1','Sa aming ''spiritu, ''spiritu, ''spiritu,<br/>Ipinakita dakilang hiwaga Mo!<br/>Ekklesia at mundo sa ''spiritu tingnan,<br/>Relihiyon at Banal na Lunsod pagmasdan.<br/>',NULL,44732,11);
INSERT INTO stanza VALUES('T10510','chorus','Sa ating ''spiritu, iwanan ang mundo<br/>Lisanin relihiyon, Nobya''y handa,<br/>Siya''y darating!<br/>',NULL,44733,12);
INSERT INTO stanza VALUES('T10510','2','Sa aking ''spiritu, nakita mata Mo,<br/>Lumiyab nang husto ihantad lihim ko;<br/>Nagsisi nga ako, sunugin ang dapat,<br/>Iwanan ang mundo, paa ko''y mangintab.<br/>',NULL,44734,13);
INSERT INTO stanza VALUES('T10510','chorus','Sa ating ''spiritu, iwanan ang mundo<br/>Lisanin relihiyon, Nobya''y handa,<br/>Siya''y darating!<br/>',NULL,44735,14);
INSERT INTO stanza VALUES('T10510','3','Sa aking ''spiritu, akin ngang natanto<br/>Ang pitong bituin at pitong ''Spiritu;<br/>''Sangtabi doktrina ''Spiritu lang gusto,<br/>Lisanin relihiyon magningas ''spiritu.<br/>',NULL,44736,15);
INSERT INTO stanza VALUES('T10510','chorus','Sa ating ''spiritu, iwanan ang mundo<br/>Lisanin relihiyon, Nobya''y handa,<br/>Siya''y darating!<br/>',NULL,44737,16);
INSERT INTO stanza VALUES('T10510','4','Sa aking ''spiritu ''king pinanatili,<br/>Pagbasa''t pagtawag, sa kaharia''y susi;<br/>Pag-ibig — nahilom, kulubot napawi,<br/>Maging haligi nga, may putong, maghari!<br/>',NULL,44738,17);
INSERT INTO stanza VALUES('T10510','chorus','Sa ating ''spiritu, iwanan ang mundo<br/>Lisanin relihiyon, Nobya''y handa,<br/>Siya''y darating!<br/>',NULL,44739,18);
INSERT INTO stanza VALUES('T10510','5','Mag-amen sa agos, sa aking ''spiritu,<br/>Bitiwan ang luma, may simulang bago!<br/>Gawin akong lubos, magbayad-halaga,<br/>Magsanay, sumunod upang mapalaya!<br/>',NULL,44740,19);
INSERT INTO stanza VALUES('T10510','chorus','Sa ating ''spiritu, iwanan ang mundo<br/>Lisanin relihiyon, Nobya''y handa,<br/>Siya''y darating!<br/>',NULL,44741,20);
INSERT INTO stanza VALUES('T10511','1','In this age of Revelation,<br/>Son of Man is the vision;<br/>Among seven golden lampstands,<br/>In the church He''s in motion.<br/>The unique expression of God,<br/>He''s also God''s true witness,<br/>And the church is His expression,<br/>His golden nature I bless.<br/>',NULL,44742,1);
INSERT INTO stanza VALUES('T10511','2','Oh Lord, Thou hast called out the church,<br/>To shine and be Thy witness;<br/>We are willing to do Thy will,<br/>No more blemish and weakness.<br/>Though the generation''s crooked,<br/>Full of darkness, without life,<br/>The church is shining so brightly,<br/>Fully expressing Thy life.<br/>',NULL,44743,2);
INSERT INTO stanza VALUES('T10511','3','Oh Lord, we rejoice and praise Thee,<br/>The church is Thy Bride to be;<br/>From her Thou obtain a Man-child,<br/>To defeat Thine enemy.<br/>Lord, we yearn to be o''ercomers,<br/>To restore Thy authority,<br/>The worldly sins are all purged out,<br/>Thy Kingdom for eternity!<br/>',NULL,44744,3);
INSERT INTO stanza VALUES('T10511','4','Oh Lord, what Thou art, what Thou do,<br/>Are all in the local church,<br/>Our hearts are stable ''cause we see,<br/>The grand vision of the Church;<br/>The revelation attracts our hearts,<br/>To keep on running to Thee.<br/>For the vision in revel''tion,<br/>Oh Lord, glory be to Thee!<br/>',NULL,44745,4);
INSERT INTO stanza VALUES('T10512','1','Lo, in these dark ages,<br/>All local churches<br/>Shining forth Hs brightness<br/>As Jesus'' witness.<br/>With the mold of spirit,<br/>Be conformed through Christ,<br/>Same with Him in substance,<br/>Manifesting Christ.<br/>',NULL,44746,1);
INSERT INTO stanza VALUES('T10512','chorus','Lo, in these dark ages,<br/>All local churches<br/>Burning through His Spirit,<br/>Shining brilliantly.<br/>',NULL,44747,2);
INSERT INTO stanza VALUES('T10512','2','In Christ dwells the fullness<br/>Of God bodily,<br/>Christ is now the Spirit,<br/>Our reality,<br/>Every golden lampstand<br/>Is His true reprint,<br/>One church in each city,<br/>His expressions spring.<br/>',NULL,44748,3);
INSERT INTO stanza VALUES('T10512','chorus','Lo, in these dark ages,<br/>All local churches<br/>Burning through His Spirit,<br/>Shining brilliantly.<br/>',NULL,44749,4);
INSERT INTO stanza VALUES('T10512','3','In the midst of the churches,<br/>Walks the Son of Man,<br/>He''s our High Priest clothed with<br/>Fine linen raiment,<br/>Golden girdle ''round His breast—<br/>Cherishing His own.<br/>Seven stars in His hands—<br/>Churches can press on!<br/>',NULL,44750,5);
INSERT INTO stanza VALUES('T10512','chorus','Lo, in these dark ages,<br/>All local churches<br/>Burning through His Spirit,<br/>Shining brilliantly.<br/>',NULL,44751,6);
INSERT INTO stanza VALUES('T10512','4','Who can bind God''s lampstand?<br/>Who can e''er downcast?<br/>Grimmer oppositions<br/>Make it spread out fast.<br/>Dimmer th'' circumstances<br/>Brighter it will shine,<br/>For the church is formed<br/>By His life divine.<br/>',NULL,44752,7);
INSERT INTO stanza VALUES('T10512','chorus','Lo, in these dark ages,<br/>All local churches<br/>Burning through His Spirit,<br/>Shining brilliantly.<br/>',NULL,44753,8);
INSERT INTO stanza VALUES('T10512','5','All the local churches,<br/>Bring forth Christ''s dear Bride,<br/>''Tis the glorious city—<br/>New Jerusalem.<br/>Many golden lampstands—<br/>Ultimately one,<br/>Manifesting fully<br/>God, the Three in One.<br/>',NULL,44754,9);
INSERT INTO stanza VALUES('T10512','chorus','Behold, coming down from heaven,<br/>All ye land shall see;<br/>God''s perfect expression<br/>Through eternity.<br/>',NULL,44755,10);
INSERT INTO stanza VALUES('T10512','1','Panaho''y madilim,<br/>Ekklesia lokal,<br/>Ang saksi ni Hesus,<br/>Liwanag tanghal;<br/>Hulmahang ''spiritu,<br/>Wangis ni Kristo,<br/>Gaya sa substansya,<br/>Hayag si Kristo.<br/>',NULL,44756,11);
INSERT INTO stanza VALUES('T10512','chorus','Ang ekklesia lokal<br/>Ay magliwanag,<br/>Sa Espiritu Niya,<br/>Maningning kislap.<br/>',NULL,44757,12);
INSERT INTO stanza VALUES('T10512','2','Kay Kristo nanahan,<br/>Diyos sa katawan,<br/>Kristo''y Espiritu,<br/>Katotohanan;<br/>Patungang-ilawan<br/>Tunay Niyang kopya,<br/>Ekklesia sa bawa''t<br/>Lunsod nahayag.<br/>',NULL,44758,13);
INSERT INTO stanza VALUES('T10512','chorus','Ang ekklesia lokal<br/>Ay magliwanag,<br/>Sa Espiritu Niya,<br/>Maningning kislap.<br/>',NULL,44759,14);
INSERT INTO stanza VALUES('T10512','3','Gitna ng ekklesia,<br/>Anak ng Tao,<br/>Lumalakad bilang<br/>Saserdote ko;<br/>Suot pinong lino,<br/>Ginto pamigkis,<br/>Kanyang hawak bituin—<br/>Sulong mabilis.<br/>',NULL,44760,15);
INSERT INTO stanza VALUES('T10512','chorus','Ang ekklesia lokal<br/>Ay magliwanag,<br/>Sa Espiritu Niya,<br/>Maningning kislap.<br/>',NULL,44761,16);
INSERT INTO stanza VALUES('T10512','4','Patungang-ilawan<br/>Di matalian,<br/>Higit na pag-usig,<br/>Di mahadlangan;<br/>Paligid mas madilim,<br/>Higit ang silay,<br/>Sapagka''t dibino<br/>Ekklesiang buháy.<br/>',NULL,44762,17);
INSERT INTO stanza VALUES('T10512','chorus','Ang ekklesia lokal<br/>Ay magliwanag,<br/>Sa Espiritu Niya,<br/>Maningning kislap.<br/>',NULL,44763,18);
INSERT INTO stanza VALUES('T10512','5','Mga ekklesia lokal,<br/>Nobya''y binunga,<br/>Bagong Herusalem<br/>Napasukdol na;<br/>Patungang-ilawan<br/>Isa sukdulan,<br/>Nahayag lubusan,<br/>Diyos, Tatlo-Isa.<br/>',NULL,44764,19);
INSERT INTO stanza VALUES('T10512','chorus','Mula sa langit bababa,<br/>O inyong tingnan:<br/>Kahayagan ng Diyos,<br/>Walang hanggan.<br/>',NULL,44765,20);
INSERT INTO stanza VALUES('T10517','1','Ride on, O King Lord Jesus,<br/>The local church has come;<br/>Henceforth in many cities,<br/>The church shall be Thy home.<br/>Through days of "In the spirit",<br/>Thy life has made us strong.<br/>Ride on, O King Lord Jesus,<br/>We sing the Victory song.<br/>',NULL,44766,1);
INSERT INTO stanza VALUES('T10518','1','Jesus is the Lord in the local church,<br/>In the local church, in the local church;<br/>Jesus is the Lord in the local church;<br/>He is Lord, Lord, Lord.<br/>',NULL,44767,1);
INSERT INTO stanza VALUES('T10518','2','He is practical in the local church,<br/>In the local church, in the local church;<br/>He is practical in the local church;<br/>He is practical.<br/>',NULL,44768,2);
INSERT INTO stanza VALUES('T10518','3','There''s a rich supply in the local church,<br/>In the local church, in the local church;<br/>There''s a rich supply in the local church;<br/>There''s a rich supply.<br/>',NULL,44769,3);
INSERT INTO stanza VALUES('T10518','4','We are all at home in the local church,<br/>In the local church, in the local church;<br/>We are all at home in the local church;<br/>It''s our home, sweet home.<br/>',NULL,44770,4);
INSERT INTO stanza VALUES('T10518','1','Kristo ang Ulo sa ekklesia,<br/>Ekklesiang lokal, ekklesiang lokal;<br/>Kristo ang Ulo sa ekklesia,<br/>Panginoon Siya.<br/>',NULL,44771,5);
INSERT INTO stanza VALUES('T10518','2','Siya ay praktikal sa ekklesia,<br/>Ekklesiang lokal, ekklesiang lokal;<br/>Siya ay praktikal sa ekklesia,<br/>Siya ay praktikal.<br/>',NULL,44772,6);
INSERT INTO stanza VALUES('T10518','3','Mayamang tustos sa ekklesia,<br/>Ekklesiang lokal, ekklesiang lokal;<br/>Mayamang tustos sa ekklesia,<br/>Mayamang tustos.<br/>',NULL,44773,7);
INSERT INTO stanza VALUES('T10518','4','Tahanan natin ang ekklesia,<br/>Ekklesiang lokal, ekklesiang lokal;<br/>Tahanan natin ang ekklesia,<br/>Tahanan natin.<br/>',NULL,44774,8);
INSERT INTO stanza VALUES('T10519','1','The local church, my beloved church,<br/>To whom my heart and life belong.<br/>In Her I taste the riches of Christ.<br/>How delightful! How contented!<br/>When all the saints together build in love,<br/>As a dwelling place for God,<br/>How pleasant and glorious ''twill be!<br/>The local church, my beloved church.<br/>To whom my heart and life belong.<br/>',NULL,44775,1);
INSERT INTO stanza VALUES('T10519','2','Nalagak sa ekklesia lokal<br/>Ang buhay ko''t pagmamahal!<br/>Sa Kanya''y natikman si Kristo.<br/>Ang yaman Niya''t nakontento!<br/>Sa pag-ibig, banal naitayo,<br/>Na tahanan ng Diyos ko,<br/>Kay ganda''t l''walhati nito!<br/>Nalagak sa ekklesia lokal,<br/>Ang buhay ko''t pagmamahal.<br/>',NULL,44776,2);
INSERT INTO stanza VALUES('T10520','1','Behold! To the mount nations flow,<br/>Above all hills, exalted she.<br/>Come, let''s go up to the temple,<br/>From Zion the Laws decree.<br/>',NULL,44777,1);
INSERT INTO stanza VALUES('T10520','chorus','O, ye local church,<br/>How blessed thou art,<br/>Grace and glory ever be.<br/>O, ye local church,<br/>How precious thou art,<br/>My heart and life all for thee.<br/>',NULL,44778,2);
INSERT INTO stanza VALUES('T10520','2','Behold! When brethren dwell in one,<br/>How good, how pleasant it is;<br/>Oil from head to body did run,<br/>Hermon dew on Zion blest.<br/>',NULL,44779,3);
INSERT INTO stanza VALUES('T10520','chorus','O, ye local church,<br/>How blessed thou art,<br/>Grace and glory ever be.<br/>O, ye local church,<br/>How precious thou art,<br/>My heart and life all for thee.<br/>',NULL,44780,4);
INSERT INTO stanza VALUES('T10520','3','Behold! How the Lord loved His church,<br/>He gave all Himself to her;<br/>By His word, cleansed and sanctified<br/>To Himself a glorious church.<br/>',NULL,44781,5);
INSERT INTO stanza VALUES('T10520','chorus','''Tis the glorious church<br/>without spot or wrinkle,<br/>Filled with the glory of the Lord;<br/>''Tis the glorious church,<br/>the Bride, the new City,<br/>Filled with the glory of the Lord.<br/>',NULL,44782,6);
INSERT INTO stanza VALUES('T10520','4','Behold! Our Lord the holder of<br/>Seven stars, seven Spirits.<br/>To keep lampstands burning brighter,<br/>Till age end, His coming bids.<br/>',NULL,44783,7);
INSERT INTO stanza VALUES('T10520','chorus','''Tis the glorious church<br/>without spot or wrinkle,<br/>Filled with the glory of the Lord;<br/>''Tis the glorious church,<br/>the Bride, the new City,<br/>Filled with the glory of the Lord.<br/>',NULL,44784,8);
INSERT INTO stanza VALUES('T10520','1','Tingnan kay dami ng bansa,<br/>Sa bundok Sion papunta.<br/>Tayo na sa templo ng Diyos,<br/>Mula sa Sion ang utos.<br/>',NULL,44785,9);
INSERT INTO stanza VALUES('T10520','chorus','Ekklesia lokal,<br/>pinagpala ng Diyos,<br/>B''yaya''t l''walhati sa iyo;<br/>Ekklesia lokal,<br/>kita''y minamahal,<br/>Puso ko''y para sa iyo.<br/>',NULL,44786,10);
INSERT INTO stanza VALUES('T10520','2','Tingnan, kapatid nagkaisa,<br/>Anong buti at saya;<br/>Langis at hamog bumaba,<br/>Sa Sion pinagpala.<br/>',NULL,44787,11);
INSERT INTO stanza VALUES('T10520','chorus','Ekklesia lokal,<br/>pinagpala ng Diyos,<br/>B''yaya''t l''walhati sa iyo;<br/>Ekklesia lokal,<br/>kita''y minamahal,<br/>Puso ko''y para sa iyo.<br/>',NULL,44788,12);
INSERT INTO stanza VALUES('T10520','3','Tingnan, mahal Niyang ekklesia,<br/>''Binigay Sarili Niya;<br/>Salitang buhay luminis,<br/>Ekklesia''y mal''walhati.<br/>',NULL,44789,13);
INSERT INTO stanza VALUES('T10520','chorus','Ekklesiang mal''walhati,<br/>walang bahid,<br/>Walang kulubot, dungis;<br/>Ekklesiang mal''walhati''y<br/>napuspusan<br/>Ng kaluwalhatian.<br/>',NULL,44790,14);
INSERT INTO stanza VALUES('T10520','4','Tingnan mal''walhating Kristo<br/>May pitong Espiritu;<br/>Patungang-ilawang-ginto,<br/>Panaho''y nakumpleto.<br/>',NULL,44791,15);
INSERT INTO stanza VALUES('T10520','chorus','Ekklesiang mal''walhati,<br/>walang bahid,<br/>Walang kulubot, dungis;<br/>Ekklesiang mal''walhati''y<br/>napuspusan<br/>Ng kaluwalhatian.<br/>',NULL,44792,16);
INSERT INTO stanza VALUES('T10521','1','Away, away from all background,<br/>And you''ll see the light when you turn around.<br/>Away, O dead Christianity;<br/>Christ is now our reality.<br/>',NULL,44793,1);
INSERT INTO stanza VALUES('T10521','chorus','Come, come to the wondrous places,<br/>That the Lord has planned for every race;<br/>Come, come there''s a wondrous home,<br/>Here we rest and never would roam.<br/>',NULL,44794,2);
INSERT INTO stanza VALUES('T10521','2','The church, the church, oh how bright she shines<br/>On the local ground, where the Lord is crowned.<br/>The church, the church, God''s eternal plan,<br/>It''s His purpose to dwell in man.<br/>',NULL,44795,3);
INSERT INTO stanza VALUES('T10521','chorus','Come, come to the wondrous places,<br/>That the Lord has planned for every race;<br/>Come, come there''s a wondrous home,<br/>Here we rest and never would roam.<br/>',NULL,44796,4);
INSERT INTO stanza VALUES('T10521','3','O come, O come, it''s already done.<br/>Where there''s unity — we all are one!<br/>O come, O come, Christ hath said it''s done.<br/>We enjoy all the vict''ry He''s won.<br/>',NULL,44797,5);
INSERT INTO stanza VALUES('T10521','chorus','Come, come to the wondrous places,<br/>That the Lord has planned for every race;<br/>Come, come there''s a wondrous home,<br/>Here we rest and never would roam.<br/>',NULL,44798,6);
INSERT INTO stanza VALUES('T10521','1','Lumang lumipas hiwalay na,<br/>Basta''t bumaling liliwanag ka;<br/>Relihiyong patay hiwalay rin,<br/>Kristo ngayo''y realidad natin.<br/>',NULL,44799,7);
INSERT INTO stanza VALUES('T10521','chorus','Tayo na sa hinirang Niya;<br/>Para sa bawa''t lahi''t bansa;<br/>Tayo na sa tahanan Niya,<br/>Mapahinga at huwag ng gumala.<br/>',NULL,44800,8);
INSERT INTO stanza VALUES('T10521','2','Ekklesia sa lupang-batayan:<br/>Ang gintong patungan-ng-ilawan;<br/>Layon ng Diyos na walang hanggan,<br/>Layunin sa tao''y makatahan.<br/>',NULL,44801,9);
INSERT INTO stanza VALUES('T10521','chorus','Tayo na sa hinirang Niya;<br/>Para sa bawa''t lahi''t bansa;<br/>Tayo na sa tahanan Niya,<br/>Mapahinga at huwag ng gumala.<br/>',NULL,44802,10);
INSERT INTO stanza VALUES('T10521','3','Halikayo magsama tayo<br/>Bilang naitayong patotoo;<br/>Halina lahat ay ganap na,<br/>Tamasa natin tagumpay Niya.<br/>',NULL,44803,11);
INSERT INTO stanza VALUES('T10521','chorus','Tayo na sa hinirang Niya;<br/>Para sa bawa''t lahi''t bansa;<br/>Tayo na sa tahanan Niya,<br/>Mapahinga at huwag ng gumala.<br/>',NULL,44804,12);
INSERT INTO stanza VALUES('T10522','1','We saw a river flowing and we jumped right in,<br/>Standing on the local ground;<br/>We saw a river flowing and we jumped right in,<br/>Standing on the local ground.<br/>',NULL,44805,1);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44806,2);
INSERT INTO stanza VALUES('T10522','2','We''ve received the revelation of recovery.<br/>Standing on the local ground;<br/>We''ve received the revelation of recovery.<br/>Standing on the local ground.<br/>',NULL,44807,3);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44808,4);
INSERT INTO stanza VALUES('T10522','3','No division, sect, or group, but it''s the local church<br/>Standing on the local ground;<br/>No division, sect, or group, but it''s the local church<br/>Standing on the local ground.<br/>',NULL,44809,5);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44810,6);
INSERT INTO stanza VALUES('T10522','4','We love, we love the brethren, Lord<br/>Standing on the local ground;<br/>We love, we love the brethren, Lord<br/>Standing on the local ground.<br/>',NULL,44811,7);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44812,8);
INSERT INTO stanza VALUES('T10522','5','We''ve been drafted to be stationed and be trained, O Lord<br/>Standing on the local ground;<br/>We''ve been drafted to be stationed and be trained, O Lord,<br/>Standing on the local ground.<br/>',NULL,44813,9);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44814,10);
INSERT INTO stanza VALUES('T10522','6','We''ll be formed and sent to fight the battle for the Lord<br/>Standing on the local ground;<br/>We''ll be formed and sent to fight the battle for the Lord<br/>Standing on the local ground.<br/>',NULL,44815,11);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44816,12);
INSERT INTO stanza VALUES('T10522','7','We''ll stand right here till Jesus comes<br/>Standing on the local ground;<br/>We''ll stand right here till Jesus comes<br/>Standing on the local ground.<br/>',NULL,44817,13);
INSERT INTO stanza VALUES('T10522','chorus','It''s us, it''s us, O Lord,<br/>Standing on the local ground;<br/>It''s us, it''s us, O Lord,<br/>Standing on the local ground.<br/>',NULL,44818,14);
INSERT INTO stanza VALUES('T10523','1','God has saved me from the world;<br/>I''ll never go back anymore.<br/>God has saved me from the world;<br/>I''ll never go back anymore.<br/>',NULL,44819,1);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44820,2);
INSERT INTO stanza VALUES('T10523','2','I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>I''ve come out from Babylon;<br/>I''ll never go back anymore.<br/>',NULL,44821,3);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44822,4);
INSERT INTO stanza VALUES('T10523','3','Since I found the local church,<br/>I''ll never go back anymore.<br/>Since I found the local church,<br/>I''ll never go back anymore.<br/>',NULL,44823,5);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44824,6);
INSERT INTO stanza VALUES('T10523','4','Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>Since I''ve touched the Lord within,<br/>I''ll never go back anymore.<br/>',NULL,44825,7);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44826,8);
INSERT INTO stanza VALUES('T10523','5','Christ is everything to me;<br/>I''ll never go back anymore.<br/>Christ is everything to me;<br/>I''ll never go back anymore.<br/>',NULL,44827,9);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44828,10);
INSERT INTO stanza VALUES('T10523','6','Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>Praise the Lord, I''m home at last;<br/>I''ll never go back anymore.<br/>',NULL,44829,11);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44830,12);
INSERT INTO stanza VALUES('T10523','7','I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>I''m for God''s recovery;<br/>I''ll never go back anymore.<br/>',NULL,44831,13);
INSERT INTO stanza VALUES('T10523','chorus','No, no, no, no, no,<br/>I''ll never go back anymore;<br/>No, no, no, no, no,<br/>I''ll never go back anymore.<br/>',NULL,44832,14);
INSERT INTO stanza VALUES('T10524','1','Our whole life has been determined,<br/>Hallelujah! Hallelujah!<br/>Christ and the church is my portion,<br/>Hallelujah! Hallelujah!<br/>No longer wand''ring in the world,<br/>But home in the church enjoying His wealth,<br/>Hallelujah! Hallelujah!<br/>',NULL,44833,1);
INSERT INTO stanza VALUES('T10526','1','God redeemed<br/>His children from the sons of men.<br/>God has purposed<br/>His people come to Him.<br/>God now moves;<br/>Let all His children turn and see—<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44834,1);
INSERT INTO stanza VALUES('T10526','chorus','We must all stand together<br/>In the churches now,<br/>On our own strength<br/>We never should rely;<br/>But each church to the other,<br/>Flowing life is how<br/>We will go on together and<br/>Become Christ''s loving Bride.<br/>',NULL,44835,2);
INSERT INTO stanza VALUES('T10526','2','Drop the past—<br/>The Lord is moving much too fast,<br/>Drop religion,<br/>And leave the world behind.<br/>Christ is real;<br/>He''s doing something new on earth—<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44836,3);
INSERT INTO stanza VALUES('T10526','chorus','We must all stand together<br/>In the churches now,<br/>On our own strength<br/>We never should rely;<br/>But each church to the other,<br/>Flowing life is how<br/>We will go on together and<br/>Become Christ''s loving Bride.<br/>',NULL,44837,4);
INSERT INTO stanza VALUES('T10526','3','Sevenfold,<br/>The churches are the lampstands gold;<br/>Local churches,<br/>With Jesus in their midst;<br/>Seven lamps<br/>To burn in each locality—<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44838,5);
INSERT INTO stanza VALUES('T10526','chorus','We must all stand together<br/>In the churches now,<br/>On our own strength<br/>We never should rely;<br/>But each church to the other,<br/>Flowing life is how<br/>We will go on together and<br/>Become Christ''s loving Bride.<br/>',NULL,44839,6);
INSERT INTO stanza VALUES('T10526','4','Christ prevails!<br/>He''s formed the churches mightily.<br/>We are standing<br/>In Jesus'' victory.<br/>It is done;<br/>He''s overcome the enemy—<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44840,7);
INSERT INTO stanza VALUES('T10526','chorus','We must all stand together<br/>In the churches now,<br/>On our own strength<br/>We never should rely;<br/>But each church to the other,<br/>Flowing life is how<br/>We will go on together and<br/>Become Christ''s loving Bride.<br/>',NULL,44841,8);
INSERT INTO stanza VALUES('T10526','5','The supply<br/>Of Jesus through the churches comes.<br/>Hallelujah!<br/>The churches move as one.<br/>This one flow<br/>Is Christ in His reality.<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44842,9);
INSERT INTO stanza VALUES('T10526','chorus','We must all stand together<br/>In the churches now,<br/>On our own strength<br/>We never should rely;<br/>But each church to the other,<br/>Flowing life is how<br/>We will go on together and<br/>Become Christ''s loving Bride.<br/>',NULL,44843,10);
INSERT INTO stanza VALUES('T10526','6','In the church<br/>We''ve seen the vision of the Lord.<br/>We, the churches,<br/>Would stand in one accord.<br/>Always move,<br/>But never independently.<br/>Hallelujah! It''s God''s recovery.<br/>',NULL,44844,11);
INSERT INTO stanza VALUES('T10526','chorus','(Do not repeat chorus after this verse)<br/>',NULL,44845,12);
INSERT INTO stanza VALUES('T10526','1','Tinubos<br/>Ng Diyos mga anak Niya;<br/>Kanyang layon,<br/>Bayan lapitan Siya;<br/>Kumilos<br/>Nang tayo''y mapabaling na—<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44846,13);
INSERT INTO stanza VALUES('T10526','chorus','Tumayong magkasama<br/>Mga ekklesia,<br/>Sa sarili''y<br/>Huwag tayong umasa;<br/>Kundi buhay idaloy<br/>Bawa''t ekklesia,<br/>Magkasamang susulong<br/>Maging Kasintahan Niya.<br/>',NULL,44847,14);
INSERT INTO stanza VALUES('T10526','2','Bitiwan<br/>Nagdaan, sumusulong Siya;<br/>Bitiwan ang<br/>Mundo at relihiyon.<br/>May bagong<br/>Gawa ang Poon sa lupa,<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44848,15);
INSERT INTO stanza VALUES('T10526','chorus','Tumayong magkasama<br/>Mga ekklesia,<br/>Sa sarili''y<br/>Huwag tayong umasa;<br/>Kundi buhay idaloy<br/>Bawa''t ekklesia,<br/>Magkasamang susulong<br/>Maging Kasintahan Niya.<br/>',NULL,44849,16);
INSERT INTO stanza VALUES('T10526','3','''Spiritu<br/>Pinatinding makapito,<br/>Ang patungan<br/>Ng ilawang ginto;<br/>Nagningas<br/>Nga sa bawa''t lokalidad.<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44850,17);
INSERT INTO stanza VALUES('T10526','chorus','Tumayong magkasama<br/>Mga ekklesia,<br/>Sa sarili''y<br/>Huwag tayong umasa;<br/>Kundi buhay idaloy<br/>Bawa''t ekklesia,<br/>Magkasamang susulong<br/>Maging Kasintahan Niya.<br/>',NULL,44851,18);
INSERT INTO stanza VALUES('T10526','4','Nanaig,<br/>Nagbuo ng ekklesia;<br/>Tumatayo<br/>Tayo sa tagumpay Niya.<br/>Tapos na,<br/>Kaaway nilupig na Niya—<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44852,19);
INSERT INTO stanza VALUES('T10526','chorus','Tumayong magkasama<br/>Mga ekklesia,<br/>Sa sarili''y<br/>Huwag tayong umasa;<br/>Kundi buhay idaloy<br/>Bawa''t ekklesia,<br/>Magkasamang susulong<br/>Maging Kasintahan Niya.<br/>',NULL,44853,20);
INSERT INTO stanza VALUES('T10526','5','Tustos Niya<br/>Di mapatid sa ekklesia;<br/>Aleluya!<br/>Nagkaisa sila.<br/>Sa agos,<br/>Realidad ay Kristo,<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44854,21);
INSERT INTO stanza VALUES('T10526','chorus','Tumayong magkasama<br/>Mga ekklesia,<br/>Sa sarili''y<br/>Huwag tayong umasa;<br/>Kundi buhay idaloy<br/>Bawa''t ekklesia,<br/>Magkasamang susulong<br/>Maging Kasintahan Niya.<br/>',NULL,44855,22);
INSERT INTO stanza VALUES('T10526','6','Nakita<br/>Pangitain magkasama;<br/>Nagkaisa<br/>Mga ekklesi-a.<br/>Gumawi<br/>Tayo nang di-nagsarili,<br/>Aleluya! pagbabawi ng Diyos.<br/>',NULL,44856,23);
INSERT INTO stanza VALUES('T10527','1','We''re in one accord for God''s recov''ry,<br/>Recovery, recovery;<br/>We''re in oneness for God''s testimony,<br/>Testimony, testimony.<br/>The fervent, pow''rful Spirit in us burning,<br/>He''s burning us, He''s burning us;<br/>A heart of sincerity draws us to God,<br/>Draws us to God, draws us to God.<br/>',NULL,44857,1);
INSERT INTO stanza VALUES('T10527','2','Business, future, why must we care?<br/>Living now for His recov''ry,<br/>Recovery, recovery, recovery,<br/>We''re for God''s recovery and testimony!<br/>',NULL,44858,2);
INSERT INTO stanza VALUES('T10527','3','Tayo ''y nagkaisa sa pagbabawi,<br/>Ng ating Diyos, ng ating Diyos;<br/>Tayo''y nagkaisa sa patotoo,<br/>Ng ating Diyos, ng ating Diyos.<br/>Maalab, malakas na Espiritu,<br/>Sa atin ay nagniningas;<br/>Pusong tapat ay nagdala sa atin,<br/>Tungo sa Diyos, tungo sa Diyos.<br/>',NULL,44859,3);
INSERT INTO stanza VALUES('T10527','4','Hanapbuhay, kinabukasan,<br/>Bakit pa pahahalagahan?<br/>Namumuhay dahil lamang sa ating Diyos,<br/>Para sa Kanyang pagbabawi''t patotoo.<br/>',NULL,44860,4);
INSERT INTO stanza VALUES('T10528','1','These are the days, my friend,<br/>Time''s drawing to an end,<br/>And we must choose,<br/>must choose whom we will serve.<br/>Will you fight for the Lord,<br/>And stand in one accord<br/>For the defeat of God''s arch enemy?<br/>',NULL,44861,1);
INSERT INTO stanza VALUES('T10528','2','These are the days, O saints,<br/>The heart of man, it faints<br/>For Satan''s work<br/>that''s seen throughout the land.<br/>So we must count all loss,<br/>Be one at any cost,<br/>And give our all for God''s recovery.<br/>',NULL,44862,2);
INSERT INTO stanza VALUES('T10528','3','These are the days, my friend,<br/>The Spirit''s moving in<br/>To raise the standard up against the foe,<br/>To show the one new man<br/>According to His plan,<br/>And draw this generation to Himself.<br/>',NULL,44863,3);
INSERT INTO stanza VALUES('T10528','4','These are the latter days,<br/>Go forth and sound His praise,<br/>Proclaim to men<br/>the kingdom that shall come.<br/>The army''s moving out,<br/>The enemy to rout,<br/>And Christ will gain<br/>His rightful place on earth.<br/>',NULL,44864,4);
INSERT INTO stanza VALUES('T10529','1','In the age of Revelation,<br/>Out from all denominations,<br/>We are in the local churches,<br/>In spirit one.<br/>Nothing old or religious binds,<br/>Every one''s a star that shines,<br/>Every church a golden lampstand,<br/>Burning with Christ.<br/>',NULL,44865,1);
INSERT INTO stanza VALUES('T10529','2','Christ and a burning church,<br/>Christ and a burning church,<br/>Christ and the church with the saints<br/>all shining stars!<br/>Hallelujah, hallelujah,<br/>Lord, we''ve given our all to Thee<br/>To be burning in the spirit, to be<br/>shining forth with Christ.<br/>',NULL,44866,2);
INSERT INTO stanza VALUES('T10530','1','We''re in the flow, we''re in the flow,<br/>O Hallelujah, in the flow!<br/>We''re in the flow, we''re in the flow,<br/>O Hallelujah, in the flow!<br/>O Praise the Lord, we''re in the flow!<br/>O Hallelujah, in the flow!<br/>We''re in the flow, we''re in the flow!<br/>O Hallelujah, in the flow.<br/>',NULL,44867,1);
INSERT INTO stanza VALUES('T10530','2','Tayo''y sa agos, sa agos!<br/>O Aleluya sa agos!<br/>Tayo''y sa agos, sa agos!<br/>O Aleluya sa agos!<br/>Siya ay purihin, sa agos!<br/>O Aleluya sa agos!<br/>Tayo''y sa agos, sa agos!<br/>O Aleluya, sa agos!<br/>',NULL,44868,2);
INSERT INTO stanza VALUES('T10531','1','For the Lord''s recovery, church life in reality,<br/>For the Lord''s testimony in every locality,<br/>Burn away, burn away,<br/>Burn ourselves and pride away;<br/>Burn away, burn away,<br/>Burn all forms and rules away.<br/>',NULL,44869,1);
INSERT INTO stanza VALUES('T10533','1','If you know the Lord, you need the Body, too,<br/>To see you through the darkest night.<br/>You can''t walk alone, you need the Body, too,<br/>To keep you on the road marked "Life".<br/>Take time to pray-read every day,<br/>When you call, "O Lord", He''ll show the way.<br/>If you know the Lord, you need the Spirit, too,<br/>To see the Light, His wonderful Light.<br/>',NULL,44870,1);
INSERT INTO stanza VALUES('T10534','1','We were in the wilderness<br/>For quite a long, long time;<br/>For us to enter Canaan,<br/>Now is the proper time.<br/>Behold, what a glory,<br/>Be bold and in spirit!<br/>We''re the new generation,<br/>The riches to inherit!<br/>Quick! For the Lord''s recov''ry,<br/>We must not be left behind.<br/>',NULL,44871,1);
INSERT INTO stanza VALUES('T10534','2','We have the ark of the Lord,<br/>Going before us then,<br/>It''s leading our new pathway,<br/>Which we''ve never trodden.<br/>Behold, Jordan River,<br/>Standing as a high wall;<br/>We the new generation,<br/>Must cut off the worldly flow!<br/>Walk, walk, walk! We are marching<br/>Together for th'' way before!<br/>',NULL,44872,2);
INSERT INTO stanza VALUES('T10534','3','Praise the Lord, Hallelujah!<br/>To Gilgal we now come;<br/>Old nature and flesh buried,<br/>Circumcised and unarmed.<br/>The produce of Canaan,<br/>Manna no longer rare;<br/>We''re not like them in the past,<br/>God''s miracle is the fare.<br/>Eat, eat, eat! For the fighting,<br/>Let us eat Canaan''s produce!<br/>',NULL,44873,3);
INSERT INTO stanza VALUES('T10534','4','We are standing with the Lord,<br/>His presence we obtain;<br/>We follow His instructions,<br/>For He is our Captain.<br/>Even if tightly closed,<br/>City of Jericho<br/>Shall certainly crumble down,<br/>By our loud shouting''s echo.<br/>Go, go, go! We will all go,<br/>And possess every city.<br/>',NULL,44874,4);
INSERT INTO stanza VALUES('T10534','5','The whole earth is for the church,<br/>For this we are aiming!<br/>Lord, we offer all to Thee,<br/>To hasten Thy coming.<br/>If Thou''rt not satisfied,<br/>Neither are we able;<br/>Crazy for the whole Island,<br/>We''ll be crazy and stable,<br/>Until what God had promised,<br/>Are all fulfilled upon us.<br/>',NULL,44875,5);
INSERT INTO stanza VALUES('T10535','1','Again "Amen", "Amen" the church,<br/>"Amen" around the clock.<br/>Just say "Amen" and follow, too,<br/>The footsteps of the flock.<br/>Then "Amen" every trial at hand,<br/>"Amen" each circumstance;<br/>Forget your failures of the past,<br/>"Amen" another chance.<br/>',NULL,44876,1);
INSERT INTO stanza VALUES('T10536','1','Oh, what wondrous fact is this,<br/>I''ve Thy inheritance been;<br/>Though none Thy riches compare,<br/>Yet without me shortage seen.<br/>',NULL,44877,1);
INSERT INTO stanza VALUES('T10536','chorus','Oh! We even become objects of Thy love,<br/>Thy riches to manifest,<br/>And Thy glory be praised.<br/>Oh! we even become objects of Thy love,<br/>Thy riches to manifest,<br/>That Thy glory should be praised.<br/>',NULL,44878,2);
INSERT INTO stanza VALUES('T10536','2','In the purpose of Thy will,<br/>I Thy blessings to receive,<br/>Chosen ere the world was made,<br/>Through redemption thus conceived.<br/>',NULL,44879,3);
INSERT INTO stanza VALUES('T10536','chorus','Oh! We even become objects of Thy love,<br/>Thy riches to manifest,<br/>And Thy glory be praised.<br/>Oh! we even become objects of Thy love,<br/>Thy riches to manifest,<br/>That Thy glory should be praised.<br/>',NULL,44880,4);
INSERT INTO stanza VALUES('T10536','3','Through the Spirit''s earnest giv''n,<br/>Full redemption without end,<br/>Wisdom, revelation come,<br/>Thee I fully comprehend.<br/>',NULL,44881,5);
INSERT INTO stanza VALUES('T10536','chorus','Oh! We even become objects of Thy love,<br/>Thy riches to manifest,<br/>And Thy glory be praised.<br/>Oh! we even become objects of Thy love,<br/>Thy riches to manifest,<br/>That Thy glory should be praised.<br/>',NULL,44882,6);
INSERT INTO stanza VALUES('T10536','4','When Thy light my eyes doth shine,<br/>Know Thy calling full of hope,<br/>Thy great resurrecting pow''r,<br/>''Round my being envelop.<br/>',NULL,44883,7);
INSERT INTO stanza VALUES('T10536','chorus','Oh! We even become objects of Thy love,<br/>Thy riches to manifest,<br/>And Thy glory be praised.<br/>Oh! we even become objects of Thy love,<br/>Thy riches to manifest,<br/>That Thy glory should be praised.<br/>',NULL,44884,8);
INSERT INTO stanza VALUES('T10536','5','Lord, we praise Thee from our hearts,<br/>We are Thy inheritance,<br/>We''re Thy Body and Thy church,<br/>Thou hast ended all Thy search.<br/>',NULL,44885,9);
INSERT INTO stanza VALUES('T10536','chorus','Oh! We even become objects of Thy love,<br/>Thy riches to manifest,<br/>And Thy glory be praised.<br/>Oh! we even become objects of Thy love,<br/>Thy riches to manifest,<br/>That Thy glory should be praised.<br/>',NULL,44886,10);
INSERT INTO stanza VALUES('T10537','1','We give ourselves to follow the churches,<br/>Oneness in Christ display;<br/>Follow His move in all of the churches,<br/>Stand fast as one this way.<br/>',NULL,44887,1);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44888,2);
INSERT INTO stanza VALUES('T10537','2','We give ourselves to follow the followers,<br/>By this we truly learn;<br/>Never desiring to be the leaders,<br/>But to the Spirit turn.<br/>',NULL,44889,3);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44890,4);
INSERT INTO stanza VALUES('T10537','3','We give ourselves the flock''s steps to follow,<br/>Knowing the Shepherd''s care.<br/>Now in the churches Jesus is leading<br/>And He is speaking there.<br/>',NULL,44891,5);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44892,6);
INSERT INTO stanza VALUES('T10537','4','We give ourselves to Thee, Lord Jesus,<br/>Never to turn aside;<br/>Where''er the Lamb goes, there we would follow,<br/>Follow whate''er betide.<br/>',NULL,44893,7);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44894,8);
INSERT INTO stanza VALUES('T10537','5','We give ourselves to enter the Kingdom,<br/>That marriage feast, with Him;<br/>Come persecution, suffering, and trials,<br/>Still we will enter in.<br/>',NULL,44895,9);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44896,10);
INSERT INTO stanza VALUES('T10537','6','Christ wants some followers here in the churches,<br/>Followers of whom to say:<br/>"These saw My purpose, followed Me wholly"—<br/>May we be those today!<br/>',NULL,44897,11);
INSERT INTO stanza VALUES('T10537','chorus','We must follow the Spirit<br/>In all simplicity.<br/>In our spirit is Jesus—<br/>He follows perfectly!<br/>',NULL,44898,12);
INSERT INTO stanza VALUES('T10538','1','In this age of Revelation,<br/>See the vision of the Son:<br/>In the midst of seven lampstands,<br/>He with them is fully one.<br/>He is God''s unique expression,<br/>As God''s testimony true.<br/>Now the Church is His expression;<br/>With all else the Lord is through.<br/>',NULL,44899,1);
INSERT INTO stanza VALUES('T10538','2','Lord, to be Your testimony<br/>We a costly price must pay.<br/>So, O Lord, for this You''ve shown us<br/>We must flee this evil age.<br/>Midst this crooked generation,<br/>Lord, You''ve called some for Your own,<br/>To belong to You completely—<br/>Your expression fully shown.<br/>',NULL,44900,2);
INSERT INTO stanza VALUES('T10538','3','Northern! Southern! Hallelujah!<br/>Both are nullified in us.<br/>We are for Your testimony<br/>From the heavens, glorious!<br/>O Lord! Amen! Hallelujah!<br/>From our innermost we say.<br/>Lord, to be Your testimony,<br/>We will take the mingled way.<br/>',NULL,44901,3);
INSERT INTO stanza VALUES('T10538','4','Lord, we praise You for that woman,<br/>Shining Bride of Christ to be.<br/>From her, You will take Your man-child<br/>To defeat Your enemy.<br/>Lord, we''ll be those overcomers<br/>To protest these evil days.<br/>Those who''ve left the world, religion—<br/>Shining in this crooked age.<br/>',NULL,44902,4);
INSERT INTO stanza VALUES('T10538','5','Lord, as You express the Father,<br/>So the church expresses You.<br/>Since we''ve seen the local churches,<br/>Nothing else could ever do.<br/>Lord, we praise You for this vision.<br/>We could never be the same.<br/>Hallelujah to the churches!<br/>All the glory to Your name.<br/>',NULL,44903,5);
INSERT INTO stanza VALUES('T10539','1','Christ and Church, Christ and Church<br/>Our Reality and Life!<br/>Lord, we are one with Thee<br/>For Thy eternal purpose.<br/>Fervent in spirit, Lord, may we serve<br/>Christ and Church forever!<br/>Christ and Church, Christ and Church,<br/>Our soul''s eternal repose.<br/>',NULL,44904,1);
INSERT INTO stanza VALUES('T10539','2','Christ and Church, Christ and Church<br/>Our true matchless enjoyment!<br/>In spirit, on the ground,<br/>To Christ and Church we are bound!<br/>Standing in oneness, we must be for<br/>Christ and Church forever!<br/>Christ and Church, Christ and Church<br/>Our Theme, Goal and All in All!<br/>',NULL,44905,2);
INSERT INTO stanza VALUES('T10539','3','Christ and Church, Christ and Church<br/>In every locality!<br/>The Bridegroom with His Bride<br/>In the New Jerusalem;<br/>Make clear this vision, Lord, we pray Thee,<br/>That we may be prepared<br/>As the Bride for Her Groom<br/>In that great Holy City.<br/>',NULL,44906,3);
INSERT INTO stanza VALUES('T10539','1','Kristo at ekklesia<br/>Realidad, buhay Ka!<br/>Kaisa Ka namin,<br/>Maging sa Iyong layunin.<br/>Maningas sa Espiritu,<br/>Naglilingkod sa Iyo;<br/>Kristo at ekklesia,<br/>Pahinga ng kalul''wa.<br/>',NULL,44907,4);
INSERT INTO stanza VALUES('T10539','2','Kristo at Ekklesia,<br/>Katamasahan Ka nga.<br/>Sa lupang batayan,<br/>Hinayag kaisahan.<br/>Sa espiritu''y magkaisa,<br/>Kay Kristo''t ekklesia.<br/>Paksa''t gol ay Siya rin<br/>Lahat sa lahat namin.<br/>',NULL,44908,5);
INSERT INTO stanza VALUES('T10539','3','Kristo at ekklesia,<br/>''Sang lokalidad isa;<br/>Ang Nobyo at Nobya,<br/>Sa Bagong Herusalem.<br/>Ang pangitain Iyong linawin,<br/>Kami''y paghandain;<br/>Mapakasal sa Iyo,<br/>Bilang kapareha Mo.<br/>',NULL,44909,6);
INSERT INTO stanza VALUES('T10541','1','Go, tell, tell it to the nation<br/>Go, tell, tell it to the nation—<br/>',NULL,44910,1);
INSERT INTO stanza VALUES('T10541','2','Go, spread throughout the nation over the rivers, hills, and dales<br/>Go, tell it to the nation that Jesus Christ is Lord.<br/>',NULL,44911,2);
INSERT INTO stanza VALUES('T10541','3','It''s Christ and the local church—<br/>His recovery today!<br/>Yield now your time and talents<br/>That He may have His way.<br/>',NULL,44912,3);
INSERT INTO stanza VALUES('T10541','4','Go, spread throughout the nation over the rivers, hills, and dales<br/>Go, tell it to the nation that Jesus Christ is Lord.<br/>',NULL,44913,4);
INSERT INTO stanza VALUES('T10541','5','Victorious life He gave us<br/>To live Him out each day!<br/>We must not fail the "mission,"<br/>So go, without delay—<br/>',NULL,44914,5);
INSERT INTO stanza VALUES('T10601','1','God''s desire — life for man;<br/>His intention — a building for His home;<br/>Shame the devil, victory won.<br/>Take the Word — soon it will be done.<br/>',NULL,44915,1);
INSERT INTO stanza VALUES('T10601','chorus','Lord, I call — build me now<br/>With the saints; O Lord, but how?<br/>"Praying always in the spirit<br/>With the Word," Amen, Lord!<br/>',NULL,44916,2);
INSERT INTO stanza VALUES('T10601','2','Christ as life — wondrous Person;<br/>All His riches, now our full supply!<br/>For the building, life''s our need:<br/>Life will build us — th'' enemy will fly.<br/>',NULL,44917,3);
INSERT INTO stanza VALUES('T10601','chorus','Lord, I call — build me now<br/>With the saints; O Lord, but how?<br/>"Praying always in the spirit<br/>With the Word," Amen, Lord!<br/>',NULL,44918,4);
INSERT INTO stanza VALUES('T10601','3','Let us rise — with our weapon;<br/>Give ourselves for th'' building of the Lord:<br/>Slay contention, kill opinions:<br/>This our weapon — th'' Spirit''s living sword.<br/>',NULL,44919,5);
INSERT INTO stanza VALUES('T10601','chorus','Lord, I call — build me now<br/>With the saints; O Lord, but how?<br/>"Praying always in the spirit<br/>With the Word," Amen, Lord!<br/>',NULL,44920,6);
INSERT INTO stanza VALUES('T10601','4','There is a way that we can know the life of Jesus;<br/>And by this life we''ll be built up as one for His home;<br/>Just turn to Him and take His Word by prayer,<br/>In your spirit daily pray His Word, pray His Word.<br/>',NULL,44921,7);
INSERT INTO stanza VALUES('T10601','chorus','Lord, I call — build me now<br/>With the saints; O Lord, but how?<br/>"Praying always in the spirit<br/>With the Word," Amen, Lord!<br/>',NULL,44922,8);
INSERT INTO stanza VALUES('T10602','1','We praise Thee, Lord, we''ve seen Thy purpose<br/>To build Thy house on earth today.<br/>This is our cry: "O Lord, do take us;<br/>Build us together in Thy way."<br/>Thine answer comes so swift and certain:<br/>"To build My house, this you must know:<br/>Your self-life must be terminated:<br/>Upon the altar you must go."<br/>',NULL,44923,1);
INSERT INTO stanza VALUES('T10602','2','In fear, O Lord, at first we shudder<br/>To face a judgment so complete,<br/>But as we''re daily drawn to Thee, Lord,<br/>No cost''s too high, no death''s too deep.<br/>To have Thy house, yes, we must die, Lord,<br/>That Thou may be our all in all.<br/>Thus we will know Thy full supply, Lord,<br/>And Thou wilt be the building''s wall.<br/>',NULL,44924,2);
INSERT INTO stanza VALUES('T10602','3','We give ourselves for Thy great purpose;<br/>We''re for Thy house, whate''er it means.<br/>Our life, our all, we give to You, Lord;<br/>A sacrifice, poured out, unseen.<br/>Consume us, Lord, upon Thine altar;<br/>Bring to ashes thoroughly.<br/>That from our off''ring Thy life''s sweet savor<br/>May ever rise in praise to Thee.<br/>',NULL,44925,3);
INSERT INTO stanza VALUES('T10604','1','Behold, the serene earth, while God for His testimony<br/>Is burning in His heart; how anxious He has been!<br/>Brothers, sisters, should we care for ourselves only<br/>And still in comfort live, thus left behind the scene?<br/>',NULL,44926,1);
INSERT INTO stanza VALUES('T10604','2','Comes the appointed time; God is here to choose us again,<br/>All churches to revive, now the time is at hand!<br/>Brothers, sisters, this precious moment we should gain;<br/>With Him cooperate, take heed the time be spent.<br/>',NULL,44927,2);
INSERT INTO stanza VALUES('T10604','3','The Lord has promised us, at Jerusalem He would call<br/>And abide with us still, and bring prosperity.<br/>My own city, shall like a village without walls.<br/>Full of inhabitants, scarcely a room there''ll be.<br/>',NULL,44928,3);
INSERT INTO stanza VALUES('T10604','4','His work God has begun, through circumstances He effects<br/>A quake among nations to lift our heads up high.<br/>And we declare: The world and universe so decked,<br/>They belong to the Lord; Satan can''t occupy.<br/>',NULL,44929,4);
INSERT INTO stanza VALUES('T10604','5','We have the word of God, it''s not our might that we depend,<br/>Not our own pow''r rely, but the Spirit of God.<br/>O great mountain, "Don''t scare us with your false pretense,<br/>For who art thou to boast, but soon we''ll find you not."<br/>',NULL,44930,5);
INSERT INTO stanza VALUES('T10604','6','The searching seven eyes, when plummets in our hands they saw,<br/>How joyful God will be; other things He won''t mind.<br/>Glory, glory, with this foundation laid below,<br/>The temple shall be built, and in our hands shall find!<br/>',NULL,44931,6);
INSERT INTO stanza VALUES('T10605','1','Chosen ere the world began,<br/>Called by Him as time goes on,<br/>Separated unto Him stand,<br/>Building be!<br/>His dear Son''s blood now I gain,<br/>And the sonship I obtain,<br/>Born in God''s home to sustain,<br/>Building be!<br/>',NULL,44932,1);
INSERT INTO stanza VALUES('T10605','chorus','Building be! Building be!<br/>Dropping my partiality,<br/>Building be!<br/>To the min''stry say, "Amen!"<br/>Spirit and the church, "Amen!"<br/>For His economy and<br/>Building be!<br/>',NULL,44933,2);
INSERT INTO stanza VALUES('T10605','2','By the Lord we have been called,<br/>By Anointing we do all,<br/>Humble, meek whate''er befall,<br/>Building be!<br/>We forbrear, to stand the test,<br/>With long-suff''ring do our best,<br/>In "spirit-one" manifest,<br/>Building be!<br/>',NULL,44934,3);
INSERT INTO stanza VALUES('T10605','chorus','Building be! Building be!<br/>Dropping my partiality,<br/>Building be!<br/>To the min''stry say, "Amen!"<br/>Spirit and the church, "Amen!"<br/>For His economy and<br/>Building be!<br/>',NULL,44935,4);
INSERT INTO stanza VALUES('T10605','3','Apostles, prophets gave He,<br/>As building foundations be,<br/>Each one''s function perfect we,<br/>Building be!<br/>All things grow unto the Head,<br/>Help one another we''re led,<br/>Do our best where''er we''re set,<br/>Building be!<br/>',NULL,44936,5);
INSERT INTO stanza VALUES('T10605','chorus','Building be! Building be!<br/>Dropping my partiality,<br/>Building be!<br/>To the min''stry say, "Amen!"<br/>Spirit and the church, "Amen!"<br/>For His economy and<br/>Building be!<br/>',NULL,44937,6);
INSERT INTO stanza VALUES('T10605','4','We may be no longer babes,<br/>Tossed and carried by the waves,<br/>Truth we hold to for love''s sake,<br/>Building be!<br/>Out from Him the house is joined,<br/>And in faith we be as one,<br/>Perfect service at this point,<br/>Building be!<br/>',NULL,44938,7);
INSERT INTO stanza VALUES('T10605','chorus','Building be! Building be!<br/>Dropping my partiality,<br/>Building be!<br/>To the min''stry say, "Amen!"<br/>Spirit and the church, "Amen!"<br/>For His economy and<br/>Building be!<br/>',NULL,44939,8);
INSERT INTO stanza VALUES('T10606','beginning-note','Haggai 1<br/>',NULL,44940,1);
INSERT INTO stanza VALUES('T10606','1','This is the time for building the temple of the Lord<br/>That all the local churches may fully be restored.<br/>''Tis not the time for our house while God''s house lieth waste—<br/>O brothers, for God''s building, rise up, make haste!<br/>',NULL,44941,2);
INSERT INTO stanza VALUES('T10606','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,44942,3);
INSERT INTO stanza VALUES('T10606','2','O hear, the Lord is speaking: Consider now your ways,<br/>Ye sow and bring in little, for lacking is My praise.<br/>Go up into the mountain, material to provide,<br/>And build My house that I may be glorified.<br/>',NULL,44943,4);
INSERT INTO stanza VALUES('T10606','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,44944,5);
INSERT INTO stanza VALUES('T10606','3','Ye who are priests, ye remnant of Christians now obey—<br/>The Lord Himself is with us, whatever men may say.<br/>With spirits stirred and burning, now let us come to work;<br/>May none his part with others in building shirk.<br/>',NULL,44945,6);
INSERT INTO stanza VALUES('T10606','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,44946,7);
INSERT INTO stanza VALUES('T10606','4','I''ll fill this house with glory, the Lord of hosts has said,<br/>And the desire of nations will be exhibited.<br/>Its glory will be greater than all that''s gone before,<br/>And we will share this glory forevermore.<br/>',NULL,44947,8);
INSERT INTO stanza VALUES('T10606','chorus','Be strong, be strong, God''s dwelling place to build!<br/>The Lord of hosts is with us, with His glory ''twill be filled!<br/>Be strong, be strong, and work in one accord,<br/>That all the nations may behold the temple of the Lord.<br/>',NULL,44948,9);
INSERT INTO stanza VALUES('T10607','1','O Hallelujah, I''m a stone<br/>To be built up by Christ!<br/>I said to Him, "You are the Christ,"<br/>He said to me, "You are a stone."<br/>Oh, yes, I''m a stone!<br/>I really am a stone.<br/>O Hallelujah, a living stone!<br/>',NULL,44949,1);
INSERT INTO stanza VALUES('T10608','1','Come ye! All the living stones now,<br/>Build up New Jerusalem,<br/>We shall never be molested,<br/>For the City''s fitly framed.<br/>',NULL,44950,1);
INSERT INTO stanza VALUES('T10608','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,44951,2);
INSERT INTO stanza VALUES('T10608','2','In recov''ry''s flow we plunge in,<br/>Pearls and precious stones produce,<br/>Build up with all saints in oneness,<br/>All self-seekings thus reduce.<br/>',NULL,44952,3);
INSERT INTO stanza VALUES('T10608','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,44953,4);
INSERT INTO stanza VALUES('T10608','3','All our spirit are in oneness,<br/>Will the building realize,<br/>Not of kinship, taste, and feeling,<br/>But one spirit unifies!<br/>',NULL,44954,5);
INSERT INTO stanza VALUES('T10608','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,44955,6);
INSERT INTO stanza VALUES('T10608','4','Not to shout void, empty slogans,<br/>But move in reality,<br/>We enjoy and serve together,<br/>Daily lab''ring faithfully.<br/>',NULL,44956,7);
INSERT INTO stanza VALUES('T10608','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,44957,8);
INSERT INTO stanza VALUES('T10608','5','The true building in spirit is,<br/>Living waters flow so free,<br/>With wheel in wheels moving swiftly,<br/>The four living creatures be.<br/>',NULL,44958,9);
INSERT INTO stanza VALUES('T10608','chorus','Hallelujah! We are in Him,<br/>Built together we have been,<br/>As the house of God in spirit,<br/>And His glory we have seen.<br/>',NULL,44959,10);
INSERT INTO stanza VALUES('T10608','6','Hallelujah! I''m so happy!<br/>Happy member now I''ll be,<br/>Set free from self-reservation,<br/>Into His economy.<br/>',NULL,44960,11);
INSERT INTO stanza VALUES('T10608','chorus','May the Lord my mind to transform,<br/>Heav''nly concept be impressed,<br/>That my speech and way of living,<br/>All for God alone express.<br/>',NULL,44961,12);
INSERT INTO stanza VALUES('T10609','1','Mingle in one, mingle in spirit one,<br/>Mingle in one, mingle in spirit one,<br/>Out from individual seclusion to the spirit.<br/>O mingle, mingle, mingle in spirit one.<br/>Mingle brothers! Mingle sisters!<br/>Mingle in spirit one. (Glory! Hallelujah!)<br/>Pray-reading and sharing, every fellowship too,<br/>Mingled in spirit one.<br/>',NULL,44962,1);
INSERT INTO stanza VALUES('T10609','2','Build together, in love build together.<br/>Build together, in love build together.<br/>Free from pride, stubbornness and yield to the spirit.<br/>O, let''s join and coordinate together.<br/>Build up brothers! Build up sisters!<br/>In love build together. (Glory! Hallelujah!)<br/>Care for every member, submit to each other.<br/>In love build together.<br/>',NULL,44963,2);
INSERT INTO stanza VALUES('T10609','1','Naghalo, sa espiritu''y isa,<br/>Naghalo, sa espiritu''y isa.<br/>Lalabas sa sarili at maihalo,<br/>Sa ''spiritu hanggang magkaisa.<br/>Magsihalo, O kapatid,<br/>Sa ''spiritu''y isa. (Gloria! Aleluya!)<br/>Magbasa-dalangin, magsalamuha rin,<br/>Mahalo nang husto.<br/>',NULL,44964,3);
INSERT INTO stanza VALUES('T10609','2','Sa pag-ibig tayo ay magtayo,<br/>Sa pag-ibig tayo ay magtayo.<br/>Huwag magpalalo''t matigas ang ulo,<br/>O, magkoordina nang sama-sama.<br/>Magtayo, mga kapatid<br/>Sa lo''b ng pag-ibig. (Glorya! Aleluya!)<br/>Mangag-alagaan, magsunuran tayo,<br/>Tayo nga''y magtayo.<br/>',NULL,44965,4);
INSERT INTO stanza VALUES('T10610','1','By Jesus'' blood we had been all redeemed,<br/>By Jesus'' blood we had been all redeemed,<br/>By Jesus'' blood we had been all redeemed,<br/>Glory, glory we now see,<br/>All our sins have been forgiven,<br/>All forgiven.<br/>',NULL,44966,1);
INSERT INTO stanza VALUES('T10610','2','Chosen by God, to be the priests are we,<br/>Chosen by God, to be the priests are we,<br/>Chosen by God, to be the priests are we,<br/>Glory, glory we now see,<br/>Waiting in the presence of God,<br/>Presence of God.<br/>',NULL,44967,2);
INSERT INTO stanza VALUES('T10610','3','Altogether we are brothers in Christ,<br/>Altogether we are brothers in Christ,<br/>Altogether we are brothers in Christ,<br/>Glory, glory we now see,<br/>In His love we all onward go,<br/>Onward we go.<br/>',NULL,44968,3);
INSERT INTO stanza VALUES('T10610','4','Altogether, we are sisters in Christ,<br/>Altogether, we are sisters in Christ,<br/>Altogether, we are sisters in Christ,<br/>Glory, glory we now see,<br/>In His love we all onward go<br/>Onward we go.<br/>',NULL,44969,4);
INSERT INTO stanza VALUES('T10610','5','Brothers, sisters loving one another,<br/>Brothers, sisters loving one another,<br/>Brothers, sisters loving one another,<br/>Glory, glory we now see.<br/>"Philadelphia," being expressed<br/>Being expressed.<br/>',NULL,44970,5);
INSERT INTO stanza VALUES('T10610','6','We''re standing on local ground of oneness,<br/>We''re standing on local ground of oneness,<br/>We''re standing on local ground of oneness,<br/>Glory, glory we now see,<br/>Recov''ry of the Lord is seen,<br/>Is fully seen.<br/>',NULL,44971,6);
INSERT INTO stanza VALUES('T10610','1','Sa dugo Niya tayo''y natubos na.<br/>Sa dugo Niya tayo''y natubos na.<br/>Sa dugo Niya tayo''y natubos na.<br/>L''walhati nga''y nakita,<br/>Sala nati''y napatawad,<br/>Napatawad.<br/>',NULL,44972,7);
INSERT INTO stanza VALUES('T10610','2','Hirang ng Diyos, tayo''y saserdote,<br/>Hirang ng Diyos, tayo''y saserdote,<br/>Hirang ng Diyos, tayo''y saserdote,<br/>L''walhati nga''y nakita,<br/>Tayo''y sa presensya ng Diyos,<br/>Naghihintay.<br/>',NULL,44973,8);
INSERT INTO stanza VALUES('T10610','3','Magkapatid sa loob ni Kristo,<br/>Magkapatid sa loob ni Kristo,<br/>Magkapatid sa loob ni Kristo,<br/>L''walhati nga''y nakita,<br/>Sa pag-ibig Niya''y susulong,<br/>O susulong.<br/>',NULL,44974,9);
INSERT INTO stanza VALUES('T10610','4','O kapatid, tayo''y magmahalan,<br/>O kapatid, tayo''y magmahalan,<br/>O kapatid, tayo''y magmahalan,<br/>L''walhati nga''y nakita,<br/>"Filadelfia" nahayag na,<br/>Nahayag na.<br/>',NULL,44975,10);
INSERT INTO stanza VALUES('T10610','5','Nakatayo sa lupang-batayan,<br/>Nakatayo sa lupang-batayan,<br/>Nakatayo sa lupang-batayan,<br/>L''walhati nga''y nakita,<br/>Pagbabawi''y nakikita,<br/>Nakikita.<br/>',NULL,44976,11);
INSERT INTO stanza VALUES('T10612','1','Oh, we have seen the church as one<br/>In perfect harmony;<br/>We sing and pray and testify<br/>Of Christ''s reality.<br/>The local churches are His move<br/>For His recovery;<br/>And in the church, how rich He is!<br/>Oh, how we taste and see!<br/>',NULL,44977,1);
INSERT INTO stanza VALUES('T10612','chorus','He''s the Real Love!<br/>That''s what Christ is to us,<br/>That''s what Christ is to us,<br/>The Real Love!<br/>',NULL,44978,2);
INSERT INTO stanza VALUES('T10612','2','We eat and drink of Christ our King<br/>Oh, what a way to feed!<br/>The proper food, the local church,<br/>Is really all we need.<br/>Digest the Word, and call "O Lord,"<br/>And to our spirit heed;<br/>Meet with the saints in one accord—<br/>Oh, Christ is rich indeed!<br/>',NULL,44979,3);
INSERT INTO stanza VALUES('T10612','chorus','He''s the Real Love!<br/>That''s what Christ is to us,<br/>That''s what Christ is to us,<br/>The Real Love!<br/>',NULL,44980,4);
INSERT INTO stanza VALUES('T10612','3','The flow of love flows out from God<br/>Through Jesus into us;<br/>The flow of love between the saints<br/>Is sweet and glorious.<br/>The fellowship is so divine,<br/>It makes us really one;<br/>And in the flow the saints all grow<br/>Up into Christ the Son.<br/>',NULL,44981,5);
INSERT INTO stanza VALUES('T10612','chorus','He''s the Real Love!<br/>That''s what Christ is to us,<br/>That''s what Christ is to us,<br/>The Real Love!<br/>',NULL,44982,6);
INSERT INTO stanza VALUES('T10612','1','Nakita ang ekklesi-a<br/>Ganap pagkaisa;<br/>May awit at dalangin pa,<br/>Kristo''y testimonia.<br/>Para sa pagbabawi Niya,<br/>Lokal na ekklesia;<br/>Kay yaman Niya sa ekklesia!<br/>Natikman, nakita!<br/>',NULL,44983,7);
INSERT INTO stanza VALUES('T10612','chorus','Pagsintang tunay!<br/>Tamasa ko''t saysay,<br/>Sa araw-araw nga,<br/>Siyang Pagsinta!<br/>',NULL,44984,8);
INSERT INTO stanza VALUES('T10612','2','Ang Kristo ngang Hari natin<br/>Kainin, inumin.<br/>Ang tunay nating kailangan<br/>Ang wastong pagkaisa.<br/>Salita''y tunawin,<br/>"O Panginoon" tawagin;<br/>Pagpulong may kaisahan—<br/>O Kristo''y mayaman!<br/>',NULL,44985,9);
INSERT INTO stanza VALUES('T10612','chorus','Pagsintang tunay!<br/>Tamasa ko''t saysay,<br/>Sa araw-araw nga,<br/>Siyang Pagsinta!<br/>',NULL,44986,10);
INSERT INTO stanza VALUES('T10612','3','Ang pag-agos ng pag-ibig<br/>Mula sa luklukan,<br/>Anong tamis, kay l''walhati<br/>Ang katamasahan!<br/>Dibino ang salamuha,<br/>Tayo''y nagkaisa;<br/>Lahat banal ay lumago<br/>Pataas kay Kristo.<br/>',NULL,44987,11);
INSERT INTO stanza VALUES('T10612','chorus','Pagsintang tunay!<br/>Tamasa ko''t saysay,<br/>Sa araw-araw nga,<br/>Siyang Pagsinta!<br/>',NULL,44988,12);
INSERT INTO stanza VALUES('T10613','1','We are one in the Spirit,<br/>We are one in the Lord.<br/>We are one in the Spirit,<br/>We are one in the Lord.<br/>And we praise Him for He made us one,<br/>We''re in one accord.<br/>',NULL,44989,1);
INSERT INTO stanza VALUES('T10613','chorus','In the love of the Lord,<br/>We''re truly one, truly one,<br/>In the love of the Lord,<br/>We''re truly one, truly one,<br/>And we praise Him for our one accord,<br/>He has made us one.<br/>',NULL,44990,2);
INSERT INTO stanza VALUES('T10613','2','We are moving together,<br/>We move as one unit.<br/>We are moving together,<br/>We move as one unit.<br/>We are joined to Christ our Head,<br/>The Body''s fitted and knit.<br/>',NULL,44991,3);
INSERT INTO stanza VALUES('T10613','chorus','In the love of the Lord,<br/>We''re truly one, truly one,<br/>In the love of the Lord,<br/>We''re truly one, truly one,<br/>And we praise Him for our one accord,<br/>He has made us one.<br/>',NULL,44992,4);
INSERT INTO stanza VALUES('T10613','3','We, in love, are built up<br/>together and edified,<br/>We, in love, are built up<br/>together and edified,<br/>When the Body grows to fullness,<br/>God will be glorified.<br/>',NULL,44993,5);
INSERT INTO stanza VALUES('T10613','chorus','In the love of the Lord,<br/>We''re truly one, truly one,<br/>In the love of the Lord,<br/>We''re truly one, truly one,<br/>And we praise Him for our one accord,<br/>He has made us one.<br/>',NULL,44994,6);
INSERT INTO stanza VALUES('T10613','4','Now the Lord is the Spirit,<br/>And He now dwells in me.<br/>Now the Lord is the Spirit,<br/>And He now dwells in me.<br/>In the Spirit we are<br/>being built organically.<br/>',NULL,44995,7);
INSERT INTO stanza VALUES('T10613','chorus','In the love of the Lord,<br/>We''re truly one, truly one,<br/>In the love of the Lord,<br/>We''re truly one, truly one,<br/>And we praise Him for our one accord,<br/>He has made us one.<br/>',NULL,44996,8);
INSERT INTO stanza VALUES('T10613','5','Praises unto the Father,<br/>Of all things He''s endorsed,<br/>Praises unto the Son,<br/>The heir of all He''s endorsed,<br/>And praises unto the Spirit,<br/>Everything He disclosed.<br/>',NULL,44997,9);
INSERT INTO stanza VALUES('T10613','chorus','Triune God, to be one with man,<br/>Now fills all in all.<br/>Triune God, to be one with man,<br/>Now fills all in all.<br/>God and man,<br/>In New Jerusalem, are mingled withal.<br/>',NULL,44998,10);
INSERT INTO stanza VALUES('T10613','1','Tayo''y magkaisa sa ''spiritu, kay Kristo,<br/>Tayo''y magkaisa sa ''spiritu, kay Kristo,<br/>Purihin ang Diyos pagka''t pinag-isa Niya tayo.<br/>',NULL,44999,11);
INSERT INTO stanza VALUES('T10613','chorus','Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Purihin ang Diyos pagka''t tayo''y pinag-isa Niya.<br/>',NULL,45000,12);
INSERT INTO stanza VALUES('T10613','2','Lahat tayo''y kumilos sa pagkakaisa,<br/>Lahat tayo''y kumilos sa pagkakaisa,<br/>Kalakip ng Ulo, nakalapat bawa''t isa.<br/>',NULL,45001,13);
INSERT INTO stanza VALUES('T10613','chorus','Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Purihin ang Diyos pagka''t tayo''y pinag-isa Niya.<br/>',NULL,45002,14);
INSERT INTO stanza VALUES('T10613','3','Sa loob ng pag-ibig tayo''y ''tinatayo,<br/>Sa loob ng pag-ibig tayo''y ''tinatayo,<br/>Ang Katawan ay lumalago, l''walhati sa Diyos.<br/>',NULL,45003,15);
INSERT INTO stanza VALUES('T10613','chorus','Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Purihin ang Diyos pagka''t tayo''y pinag-isa Niya.<br/>',NULL,45004,16);
INSERT INTO stanza VALUES('T10613','4','Pangino''n ang Espiritu, sa ''spiritu ko,<br/>Pangino''n ang Espiritu, sa ''spiritu ko,<br/>Sa Espiritu magkaisa sa pagtatayo.<br/>',NULL,45005,17);
INSERT INTO stanza VALUES('T10613','chorus','Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Sa pag-ibig ni Kristo tayo''y magkaisa,<br/>Purihin ang Diyos pagka''t tayo''y pinag-isa Niya.<br/>',NULL,45006,18);
INSERT INTO stanza VALUES('T10613','5','Purihin ang Ama, pinagmulan ng lahat,<br/>Purihin ang Anak, nagmana at nagtupad,<br/>Purihin din ang Espiritu, siyang nagsiwalat.<br/>',NULL,45007,19);
INSERT INTO stanza VALUES('T10613','chorus','Sa Kanyang pagpupuspos ng lahat sa lahat,<br/>Tres-unong Diyos nakipag-isa nga sa tao.<br/>Sa Bagong Herusalem, Diyos at tao''y naghalo.<br/>',NULL,45008,20);
INSERT INTO stanza VALUES('T10614','1','The world is longing, seeking for peace,<br/>Yet wars and rumors of wars still increase.<br/>There is no way for men to end all this fear,<br/>All this pain, all this hate, all these tears,<br/>Yet Jesus is here!<br/>',NULL,45009,1);
INSERT INTO stanza VALUES('T10614','chorus','When we believe into the Son,<br/>By His Spirit, we are made one.<br/>When we believe into the Son,<br/>By His Spirit, we are made one.<br/>',NULL,45010,2);
INSERT INTO stanza VALUES('T10614','chorus','Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Everyone: We are one.<br/>',NULL,45011,3);
INSERT INTO stanza VALUES('T10614','2','We are dwelling in the love of the Lord,<br/>He our unity has now restored.<br/>Brothers, sisters in one family,<br/>As the Father and the Son, always one,<br/>So are we!<br/>',NULL,45012,4);
INSERT INTO stanza VALUES('T10614','chorus','When we believe into the Son,<br/>By His Spirit, we are made one.<br/>When we believe into the Son,<br/>By His Spirit, we are made one.<br/>',NULL,45013,5);
INSERT INTO stanza VALUES('T10614','chorus','Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Brothers: We are one.<br/>Sisters: We are all made one.<br/>Everyone: We are one.<br/>',NULL,45014,6);
INSERT INTO stanza VALUES('T10614','3','How good and pleasant it can be<br/>When brothers dwell in unity;<br/>Like sweet anointing and the mountain dew,<br/>Life eternal for me and for you—<br/>All things are new!<br/>',NULL,45015,7);
INSERT INTO stanza VALUES('T10614','chorus','Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>',NULL,45016,8);
INSERT INTO stanza VALUES('T10614','chorus','Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Lahat: Isa nga.<br/>',NULL,45017,9);
INSERT INTO stanza VALUES('T10614','1','Mundo''y hangad kapayapaan,<br/>Nguni''t digmaan ay naragdagan.<br/>Walang daang papawi sa pangamba,<br/>Maging sa sakit, poot, luha,<br/>Hesus lunas Siya!<br/>',NULL,45018,10);
INSERT INTO stanza VALUES('T10614','chorus','Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>',NULL,45019,11);
INSERT INTO stanza VALUES('T10614','chorus','Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Lahat: Isa nga.<br/>',NULL,45020,12);
INSERT INTO stanza VALUES('T10614','2','Sa pag-ibig ni Hesus nanahan,<br/>Pinanumbalik Niya kai-sahan.<br/>Magkapatid sa ''sang pamilya,<br/>Tulad ng Ama''t Anak nagkaisa,<br/>Tayo rin!<br/>',NULL,45021,13);
INSERT INTO stanza VALUES('T10614','chorus','Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>Sa Anak nananalig ka,<br/>Sa ''Spiritu tayo''y isa.<br/>',NULL,45022,14);
INSERT INTO stanza VALUES('T10614','chorus','Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Brothers: Isa nga.<br/>Sisters: Ginawang isa.<br/>Lahat: Isa nga.<br/>',NULL,45023,15);
INSERT INTO stanza VALUES('T10614','3','Kapatiran nagkaisa,<br/>Anong buti, anong ganda!<br/>Gayang langis at hamog sa Hermon,<br/>May walang hanggang buhay doon,<br/>Lahat ay bago!<br/>',NULL,45024,16);
INSERT INTO stanza VALUES('T10615','1','Do you know God has a need, all you brothers?<br/>Do you know He wants a place to rest and dwell?<br/>Do you know by being one,<br/>We are built up as God''s house?<br/>This house will give Him rest,<br/>This house will give us rest.<br/>',NULL,45025,1);
INSERT INTO stanza VALUES('T10615','2','How can such a house exist, so divided?<br/>Why is every room apart from all the rest?<br/>We must drop what''s keeping us from expressing unity;<br/>That we may all be one,<br/>That we may all be one.<br/>',NULL,45026,2);
INSERT INTO stanza VALUES('T10615','3','If we''re one, then we''ll enjoy more than just a house;<br/>If we''re one, the house becomes a family''s home.<br/>In this home we all can be brothers in reality;<br/>This is God''s family,<br/>This is God''s family.<br/>',NULL,45027,3);
INSERT INTO stanza VALUES('T10615','4','In this home we fully taste all the fatness.<br/>We can share the riches of saints throughout the years.<br/>And together we can add to the treasure of God''s house;<br/>God''s house is very rich,<br/>God''s house is very rich.<br/>',NULL,45028,4);
INSERT INTO stanza VALUES('T10615','5','Now the Lord has chosen us, this generation;<br/>Out of all the ages past, this is the one!<br/>But we can''t be weighted down by the things we think are right;<br/>We must keep moving on,<br/>We must keep moving on.<br/>',NULL,45029,5);
INSERT INTO stanza VALUES('T10615','6','We are being challenged now to take God''s burden;<br/>Will you come and meet as one, dropping everything?<br/>Are you really for the church?<br/>Prove it now before the Lord.<br/>We''ll take this challenge now,<br/>We''ll take this challenge now.<br/>',NULL,45030,6);
INSERT INTO stanza VALUES('T10618','1','In God''s house now are we, together been called;<br/>By His blood cleansing, sanctified wholly,<br/>Reborn through Spirit, and with God unite,<br/>Being heirs of God, His inheritance.<br/>Free, and full, and resting,<br/>Sing His praise forever,<br/>Oh, Hallelujah! Together been called.<br/>',NULL,45031,1);
INSERT INTO stanza VALUES('T10618','2','In Spirit now are we, together sharing;<br/>Doctrines abandon, with all the rituals,<br/>Not in forms we stick, nor to letters cleave,<br/>With newness of life, river of life flows.<br/>Freedom from religion, reality seeking,<br/>Oh, Hallelujah! Together we share.<br/>',NULL,45032,2);
INSERT INTO stanza VALUES('T10618','3','In the Church now are we, together serving;<br/>Cast out all evil, heav''nly food we eat;<br/>Come to His presence, all as living stones,<br/>Build up the temple, made into priesthood.<br/>Through our Christ, Lord Jesus, sacrifices offer,<br/>Oh, Hallelujah! Together we serve.<br/>',NULL,45033,3);
INSERT INTO stanza VALUES('T10618','4','In His love now are we, together unite;<br/>Forbearing in love, and binding in peace;<br/>If one be happy, everyone''s joyful,<br/>One member''s anguish, bring sad tears to all.<br/>Helping one another, with one mind and one will,<br/>Oh, Hallelujah! Together unite.<br/>',NULL,45034,4);
INSERT INTO stanza VALUES('T10618','5','In His camp now are we, together fighting;<br/>Keeping one''s station, standing in order.<br/>Put on God''s armor, take up His weapons;<br/>In Jesus'' great name, trusting on His work.<br/>Pray all times in all things, quench the wiles of Satan,<br/>Oh, Hallelujah! Together we fight.<br/>',NULL,45035,5);
INSERT INTO stanza VALUES('T10618','6','In glory now are we, together with Him;<br/>Curses then over, heav''n and earth peaceful;<br/>River for our thirst, fruits for our hunger;<br/>Bridegroom and the Bride, ever live in love.<br/>God and man in oneness, full of light and gladness,<br/>Oh, Hallelujah! Together with Him.<br/>',NULL,45036,6);
INSERT INTO stanza VALUES('T10618','1','Sa tahanan ng Diyos tinawag tayo;<br/>Dugo''y naghugas, binukod tayo,<br/>''Sinilang-muli, hugpong sa Kanya;<br/>Tagapagmana, naging mana Niya.<br/>Malaya''t nabusog, pupuri''t kakanta,<br/>O, Aleluya! Tinawag tayo!<br/>',NULL,45037,7);
INSERT INTO stanza VALUES('T10618','2','Sa ''Spiritu tayo nagsalamuha;<br/>Bitiwan ritwal, maging doktrina,<br/>Di sa gawi at titik kumapit,<br/>Sa ilog ng buhay manatili.<br/>Di na sa relihiyon, habulin ang tunay,<br/>O, Aleluya! Magsalamuha!<br/>',NULL,45038,8);
INSERT INTO stanza VALUES('T10618','3','Sa ekklesia tayo''y naglilingkuran,<br/>Kristo kainin, lason iwasan;<br/>Sa harapan Niya, buháy ngang batô,<br/>Ang saserdote, tinayong templo.<br/>Hain lugod ng Diyos, sa loob ni Kristo,<br/>O, Aleluya! Naglilingkuran!<br/>',NULL,45039,9);
INSERT INTO stanza VALUES('T10618','4','Sa Kanyang pag-ibig, nagkakaisa,<br/>Mag-unawaan, bigkis payapa.<br/>Isa''y may galak, lahat natuwa;<br/>Isa''y may lungkot, lahat luluha.<br/>Mangagtulungan, isang puso''t isipan,<br/>O, Aleluya! Nagkakaisa!<br/>',NULL,45040,10);
INSERT INTO stanza VALUES('T10618','5','Sa lo''b ng kampo Niya, makipagbaka,<br/>Pinanindigan, batayang lupa,<br/>Ang kutamaya, ibihis buo,<br/>Sa ngalang Hesus, daigin diyablo.<br/>Lahat ng panahon, dasal walang hinto,<br/>O, Aleluya! Makipagbaka!<br/>',NULL,45041,11);
INSERT INTO stanza VALUES('T10618','6','Sa kal''walhatian, Kristo''y kasama,<br/>Sumpa''y lumipas, pawang payapa.<br/>Tubig at bunga sa kabuhayan;<br/>Nobyo at Nobya nagmamahalan.<br/>Diyos, tao, nagkai-sa, galak walang hanggan,<br/>O, Aleluya! Kristo''y kasama!<br/>',NULL,45042,12);
INSERT INTO stanza VALUES('T10619','1','Lord, burn in us as a consuming fire,<br/>You''re burning in our spirit for Your plan;<br/>Lord, now our spirit''s filled with your fire,<br/>And this fire must not be limited by man.<br/>',NULL,45043,1);
INSERT INTO stanza VALUES('T10619','2','Lord, we are clear: to us the earth You''ve given,<br/>And forth we come to take it for Your plan;<br/>Lord, we are bold, without hesitation,<br/>Caleb''s extraordinary spirit''s ours.<br/>',NULL,45044,2);
INSERT INTO stanza VALUES('T10619','3','From wandering the wilderness we''re tired;<br/>We refuse to die like our fathers there.<br/>We''re not afraid of giants the land''s acquired;<br/>They''ll become the bread to fill our inner man!<br/>',NULL,45045,3);
INSERT INTO stanza VALUES('T10619','4','We praise You, Lord, we are the generation<br/>To fulfill Your plan and bring You back again!<br/>We are so strong — we''re the Word''s habitation<br/>Overcoming the dragon all the time.<br/>',NULL,45046,4);
INSERT INTO stanza VALUES('T10619','5','We give ourselves e''er to exercise our spirit;<br/>Our spirits''s made us crazy and on fire.<br/>We''re absolute for Your eternal habitation<br/>So we give ourselves completely unto You.<br/>',NULL,45047,5);
INSERT INTO stanza VALUES('T10619','6','We''ve heard Your call: "Oh who for us will go?<br/>Who''ll be sent to fulfill what I said?"<br/>"I''ll build my church prevailing o''er the foe<br/>A living church that''s not religious, dead!"<br/>',NULL,45048,6);
INSERT INTO stanza VALUES('T10619','7','Lord, use us now according to Your plan;<br/>Lord, we''re here to be sent by You today.<br/>Lord, we are those; we''ve taken your stand;<br/>We are just for You — Oh, send us, Lord, we pray!<br/>',NULL,45049,7);
INSERT INTO stanza VALUES('T10620','1','All our lives have been transformed,<br/>No longer self as boss.<br/>Eat, drink, Christ enjoyed,<br/>Each one full of joy.<br/>Let self go there''ll be a new flow,<br/>Grant the Spirit liberty,<br/>Oh! Let Him move freely,<br/>Oh! Let Him move freely.<br/>',NULL,45050,1);
INSERT INTO stanza VALUES('T10620','2','All our lives have been transformed,<br/>No longer self as boss.<br/>Now our spirits'' free,<br/>Each one full of glee.<br/>Of the Spirit promptly receive,<br/>Like a child His Kingdom fit.<br/>In His Kingdom fit,<br/>In His Kingdom fit.<br/>',NULL,45051,2);
INSERT INTO stanza VALUES('T10621','1','The grinding process has begun,<br/>We all agree it must be done,<br/>In the church, in the church,<br/>We are ground, we are ground.<br/>Whole grains of wheat will never do,<br/>So by Thy grace, Lord, take us through,<br/>In the church, in the church,<br/>To be ground, to be ground.<br/>',NULL,45052,1);
INSERT INTO stanza VALUES('T10621','2','In all our local churches<br/>we take our stand;<br/>Here we''d lose our self and<br/>every one be fully blent in oneness.<br/>Be blent, be blent,<br/>be fully blent in oneness,<br/>Be blent, be blent,<br/>be fully blent in oneness.<br/>',NULL,45053,2);
INSERT INTO stanza VALUES('T10622','1','Jesus, this generation, has had it with religion,<br/>They want a real, lasting touch with Your living Person;<br/>You long for them, as they long for You,<br/>So, take this generation on, Lord.<br/>',NULL,45054,1);
INSERT INTO stanza VALUES('T10622','2','You need cooperation, to gain this generation,<br/>Enlarge our hearts, make us open, and more than willing;<br/>We''d desp''rate be, Your increase to see<br/>New life, new members in the churches.<br/>',NULL,45055,2);
INSERT INTO stanza VALUES('T10622','3','You have a family that''s longing to grow,<br/>A place for this generation to go.<br/>',NULL,45056,3);
INSERT INTO stanza VALUES('T10622','4','O Lord, we long to be in Your humanity,<br/>Only Your virtues can meet all the people''s needs;<br/>You''ll be so much to the ones we touch,<br/>So, Lord, we give ourselves completely.<br/>',NULL,45057,4);
INSERT INTO stanza VALUES('T10623','1','It''s a wrong way to be religious,<br/>It''s a wrong way to go,<br/>In a strong way be in spirit,<br/>And jump right in the flow.<br/>In the spirit we''re united<br/>All in one accord.<br/>Calling, "O Lord, Amen, Hallelujah,"<br/>Jesus is Lord!<br/>',NULL,45058,1);
INSERT INTO stanza VALUES('T10624','1','The Lord has put me in the Body,<br/>He has made a member out of me;<br/>I''m leaving all the things on the tree of knowledge,<br/>And learning how to eat the living tree.<br/>Well now I''m taking in much more of Jesus!<br/>He''s put me on His farm here just to grow,<br/>We''re only here because we love our Jesus,<br/>We stand as one so all the world will know.<br/>',NULL,45059,1);
INSERT INTO stanza VALUES('T10624','2','The Lord doesn''t need more individuals,<br/>He''s got too many now, it''s plain to see;<br/>All He wants is One New Man forever,<br/>And that doesn''t leave any room for you and me.<br/>The only way that we''ll be one is Jesus!<br/>The only way for Him to gather us,<br/>Is by our eating, drinking, breathing Jesus!<br/>Until His riches overflow in us!<br/>',NULL,45060,2);
INSERT INTO stanza VALUES('T10624','3','The Lord has put me in the church life,<br/>Christ and the church, His image to express;<br/>He''s chosen me according to His purpose,<br/>And won''t be satisfied with something less.<br/>[The only way that we''ll be one is Jesus!<br/>The only way for Him to gather us,<br/>Is by our eating, drinking, breathing Jesus!<br/>Until His riches overflow in us!]<br/><!--(Repeat from last four lines of stanza 2)--><br/>',NULL,45061,3);
INSERT INTO stanza VALUES('T10625','1','Far from world and all its charms;<br/>Free from sins and all alarms.<br/>Fill me, Lord, my every part;<br/>Change to Thine image, as Thou art.<br/>',NULL,45062,1);
INSERT INTO stanza VALUES('T10625','2','Freed from self, peculiar traits,<br/>And all independent ways,<br/>Lord, I would by Thee be built;<br/>With all saints together built.<br/>',NULL,45063,2);
INSERT INTO stanza VALUES('T10625','3','Built up in love together,<br/>Each one his function render;<br/>Thus the body-life expressed,<br/>And all His glory manifest.<br/>',NULL,45064,3);
INSERT INTO stanza VALUES('T10625','4','By Thy life, we''ll be transformed,<br/>Unto precious stones conformed,<br/>Not just individual stones,<br/>But together be built a home.<br/>',NULL,45065,4);
INSERT INTO stanza VALUES('T10625','5','Take my life moments and days,<br/>Let them be used for Thy ways;<br/>For Thy building, I give all,<br/>Let them be under Thy control.<br/>',NULL,45066,5);
INSERT INTO stanza VALUES('T10701','1','Oh, listen to the wanderer<br/>In whom there was a lack;<br/>Then hearken to the song he sings<br/>And follow in His track.<br/>',NULL,45067,1);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45068,2);
INSERT INTO stanza VALUES('T10701','2','A wanderer within the world<br/>For pleasure ever seeks;<br/>Be it in body or in mind,<br/>With vanity it reeks.<br/>',NULL,45069,3);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45070,4);
INSERT INTO stanza VALUES('T10701','3','For self I labored day and night,<br/>My castles built in sand;<br/>But, praise the Lord, He wrecked them all—<br/>Much better things He planned.<br/>',NULL,45071,5);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45072,6);
INSERT INTO stanza VALUES('T10701','4','I am a happy member now<br/>Within the local church.<br/>A wanderer has found his home<br/>And ended all his search.<br/>',NULL,45073,7);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45074,8);
INSERT INTO stanza VALUES('T10701','5','I was an individualist,<br/>An island in myself;<br/>But now the Lord is building me<br/>With others in Himself.<br/>',NULL,45075,9);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45076,10);
INSERT INTO stanza VALUES('T10701','6','I''m drawn together with His own<br/>In fellowship so sweet.<br/>I''ve learned from others to receive<br/>Of Christ whene''er we meet.<br/>',NULL,45077,11);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45078,12);
INSERT INTO stanza VALUES('T10701','7','My wanderings have really ceased—<br/>I''ve found the church, God''s best!<br/>The secret of my happiness—<br/>Enjoying God''s own rest!<br/>',NULL,45079,13);
INSERT INTO stanza VALUES('T10701','chorus','Praise the Lord! Praise the Lord!<br/>Praise the Lord! Hallelujah! Hallelujah!<br/>Praise the Lord! Praise the Lord!<br/>I''ll never be the same!<br/>',NULL,45080,14);
INSERT INTO stanza VALUES('T10702','1','In solitude lived I in time past,<br/>My own spir''tuality asked;<br/>Hoping that I might stand before Him,<br/>Thus gain His pleasure I deemed.<br/>Though tasting a bit of its sweetness,<br/>Still the loneliness could feel;<br/>It is enough the loss I''ve suffered,<br/>And be thus never I will.<br/>',NULL,45081,1);
INSERT INTO stanza VALUES('T10702','2','I''ve found you all in Christ who led me,<br/>As if my dear Lord you''d be;<br/>I''ve got a home which I''m confided,<br/>And with the riches I''m fed.<br/>Through you with might I am empowered,<br/>Unnoticed an inch I''ve gained;<br/>I will unite forever with thee,<br/>My life for thee is maintained.<br/>',NULL,45082,2);
INSERT INTO stanza VALUES('T10703','1','Aren''t you glad, you''re now in the church—<br/>What a joy, you''ve ended your search;<br/>Praise the Lord, it''s so glorious;<br/>Jesus Christ is living in us.<br/>',NULL,45083,1);
INSERT INTO stanza VALUES('T10703','2','We''re no longer free to roam;<br/>Christ has led us to our home.<br/>Brothers, sisters, we''ve come,<br/>now we''re one:<br/>Here the real family life has begun.<br/>',NULL,45084,2);
INSERT INTO stanza VALUES('T10703','3','We have come to God''s chosen place;<br/>It is here that we see His face.<br/>This is where He''s put His name;<br/>Once you''re here you''ll not be the same.<br/>',NULL,45085,3);
INSERT INTO stanza VALUES('T10703','4','Hallelujah we''ve lost our choice;<br/>Since the day that we heard His voice.<br/>Deep within we heard the "Amen,"<br/>"This is My choice—<br/>you''ll not choose again!"<br/>',NULL,45086,4);
INSERT INTO stanza VALUES('T10704','1','The Lord is my greatest love,<br/>To Him I give my all;<br/>He''s my constant comfort,<br/>Sympathizer and support.<br/>For redemption, He died<br/>That life could be supplied;<br/>River of pleasure,<br/>My rest and treasure;<br/>O my Lord, I love Thee,<br/>Forever, Lord, I love Thee!<br/>',NULL,45087,1);
INSERT INTO stanza VALUES('T10704','2','The church is my home, sweet home,<br/>My true satisfaction;<br/>The Lord''s counterpart — she,<br/>My living reality.<br/>Here''s love and care, supply<br/>That never shall run dry;<br/>My way she will guide,<br/>And strength she''ll provide;<br/>O my church, I love Thee,<br/>My home, sweet home, I love Thee!<br/>',NULL,45088,2);
INSERT INTO stanza VALUES('T10704','1','Hesus ang aking sinta,<br/>Kanya ang lahat ko,<br/>Aliw, taguyod Siya,<br/>At laging karamay ko.<br/>Minsan Siya''y namatay,<br/>Ngayon Siya ang buhay,<br/>Kapayapaan,<br/>At kagalakan;<br/>Hesus, aking hirang,<br/>Mahal magpakailanman.<br/>',NULL,45089,3);
INSERT INTO stanza VALUES('T10704','2','Ekklesiang tahanan ko,<br/>Aking kasiyahan,<br/>Kapareha ni Kristo,<br/>Aking katotohanan.<br/>Pag-ibig, taguyod,<br/>Tustos di-masayod,<br/>Nagpapatibay,<br/>Pumapatnubay;<br/>Tahanan kong sinta,<br/>Mahal na ekklesia.<br/>',NULL,45090,4);
INSERT INTO stanza VALUES('T10705','1','Happy days when we are home<br/>In the fam''ly called our own—<br/>Th'' local church God''s chosen ground<br/>Wherein Christ''s fullness all abound.<br/>',NULL,45091,1);
INSERT INTO stanza VALUES('T10705','chorus','For the Lord''s recovery,<br/>On the ground of unity.<br/>We express the Body of Christ—<br/>The beauty of His chosen Bride.<br/>',NULL,45092,2);
INSERT INTO stanza VALUES('T10705','2','Seven Spirits burning fire<br/>For the church of God''s desire.<br/>Burn us, fill us, and transform us,<br/>To His glorious image we ask.<br/>',NULL,45093,3);
INSERT INTO stanza VALUES('T10705','chorus','For the Lord''s recovery,<br/>On the ground of unity.<br/>We express the Body of Christ—<br/>The beauty of His chosen Bride.<br/>',NULL,45094,4);
INSERT INTO stanza VALUES('T10706','1','We have a joyful song to sing,<br/>We''re in the dwelling of the King!<br/>We''ve seen the vision, we''ve heard His voice,<br/>Now we meet as the church of His choice.<br/>',NULL,45095,1);
INSERT INTO stanza VALUES('T10706','2','We hear a mighty thunder sound—<br/>Saints meeting on the local ground.<br/>Hallelujahs, with joy we raise,<br/>And our meetings are filled with His praise.<br/>',NULL,45096,2);
INSERT INTO stanza VALUES('T10706','3','No longer wandering afar,<br/>Searching and seeking for the star,<br/>Hallelujah! The light shines bright!<br/>We are home, we are home, we are home!<br/>',NULL,45097,3);
INSERT INTO stanza VALUES('T10708','1','O Lord, everybody''s home.<br/>Eating, drinking, breathing of the Lord.<br/>Now rejoice, the family''s all together,<br/>O Lord, everybody''s home.<br/>',NULL,45098,1);
INSERT INTO stanza VALUES('T10708','2','Tayo''y nasa tahanan<br/>Iinom, kakain kay Hesus.<br/>Magalak pamilya''y sama-sama,<br/>Tayo''y nasa tahanan.<br/>',NULL,45099,2);
INSERT INTO stanza VALUES('T10709','1','O What joy! we are all at home.<br/>All the saints before God''s presence come.<br/>To tell the stories of His wondrous grace.<br/>Our spirits soar and to Him our praises raise.<br/>',NULL,45100,1);
INSERT INTO stanza VALUES('T10709','2','''Nong galak! Nasa tahanan,<br/>Banal nasa Kanyang harapan;<br/>Isaysay kamangha-manghang b''yaya,<br/>Napataas ''spiritu purihin Siya!<br/>',NULL,45101,2);
INSERT INTO stanza VALUES('T10711','1','Splendid church life! His green garden! He has brought us, praise the Lord,<br/>To experience the Christ Who''s growing here!<br/>He is full of rich enjoyment to His saints in one accord;<br/>He is new and fresh, available and dear.<br/>',NULL,45102,1);
INSERT INTO stanza VALUES('T10711','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,45103,2);
INSERT INTO stanza VALUES('T10711','2','It is not a school or fact''ry or a chapel in the air;<br/>But a garden where our Lord can plant and sow.<br/>So He''s placed us all here corporately to be His garden fair,<br/>Where He''s free to cultivate and make us grow.<br/>',NULL,45104,3);
INSERT INTO stanza VALUES('T10711','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,45105,4);
INSERT INTO stanza VALUES('T10711','3','Thus within the church-life garden there''s a fruit-producing tree<br/>Full of life and so available to eat.<br/>So be simple, don''t be hardened, drop your concepts — eat the tree!<br/>Take in Jesus every moment — He''s so sweet!<br/>',NULL,45106,5);
INSERT INTO stanza VALUES('T10711','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,45107,6);
INSERT INTO stanza VALUES('T10711','4','With the tree there is the water, flowing God in Christ to us,<br/>Quenching all our dryness, ending all our strife.<br/>Hallelujah! In His garden Jesus flows Himself to us,<br/>As the full supply for us to grow in life.<br/>',NULL,45108,7);
INSERT INTO stanza VALUES('T10711','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,45109,8);
INSERT INTO stanza VALUES('T10711','5','Aren''t you satisfied and thankful that our Lord has brought you in<br/>Where His pleasures and His riches flow so free?<br/>So be happy and be joyful, in the spirit feast on Him,<br/>So God''s garden can bear fruit abundantly.<br/>',NULL,45110,9);
INSERT INTO stanza VALUES('T10711','chorus','I''m so happy in this lovely place,<br/>In the garden growing in His grace!<br/>There is no finer pleasure than to eat the living tree<br/>And to get the living water into me.<br/>',NULL,45111,10);
INSERT INTO stanza VALUES('T10712','1','Ah! The church life is so lovely!<br/>Here we can gaily eat and drink daily.<br/>Why be hungry? Why be thirsty?<br/>Enjoy the church life, you and me.<br/>',NULL,45112,1);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Enter the ark quickly, live the church life daily.<br/>Eat and drink Christ gladly, there is no time to tarry;<br/>Enter the ark quickly, live the church life daily.<br/>To meet our dear Bridegroom—<br/>O how worth it!<br/>',NULL,45113,2);
INSERT INTO stanza VALUES('T10712','2','Ah! The church life is so lovely!<br/>"To give all for it" is really worth it.<br/>We only love Christ and the Church,<br/>Nothing else would we seek or search.<br/>',NULL,45114,3);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Enter the ark quickly, live the church life daily.<br/>Eat and drink Christ gladly, there is no time to tarry;<br/>Enter the ark quickly, live the church life daily.<br/>To meet our dear Bridegroom—<br/>O how worth it!<br/>',NULL,45115,4);
INSERT INTO stanza VALUES('T10712','3','Ah! The church life is so lovely!<br/>We''re in God''s fam''ly,<br/>everyone''s wealthy—<br/>For functioning in the gath''ring,<br/>And unsaved people reaping in.<br/>',NULL,45116,5);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Enter the ark quickly, live the church life daily.<br/>Eat and drink Christ gladly, there is no time to tarry;<br/>Enter the ark quickly, live the church life daily.<br/>To meet our dear Bridegroom—<br/>O how worth it!<br/>',NULL,45117,6);
INSERT INTO stanza VALUES('T10712','4','Ah! The church life is so lovely!<br/>We have the good land—<br/>everything''s just grand.<br/>Faithfully planting and wat''ring,<br/>We all are full-time laboring.<br/>',NULL,45118,7);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Enter the ark quickly, live the church life daily.<br/>Eat and drink Christ gladly, there is no time to tarry;<br/>Enter the ark quickly, live the church life daily.<br/>To meet our dear Bridegroom—<br/>O how worth it!<br/>',NULL,45119,8);
INSERT INTO stanza VALUES('T10712','5','Ah! The church life is so lovely!<br/>Built up together, we are one Body.<br/>Ha, ha, old Satan, you are through,<br/>The Lord shall have the Bride for sure.<br/>',NULL,45120,9);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Enter the ark quickly, live the church life daily.<br/>Eat and drink Christ gladly, there is no time to tarry;<br/>Enter the ark quickly, live the church life daily.<br/>To meet our dear Bridegroom—<br/>O how worth it!<br/>',NULL,45121,10);
INSERT INTO stanza VALUES('T10712','1','Magandang buhay-ekklesia!<br/>Kumain, uminom bawa''t araw.<br/>Bakit magutom, mauhaw?<br/>Tamasa''y buhay-ekklesia.<br/>',NULL,45122,11);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Pasok nang mabilis, magbuhay-ekklesia.<br/>Kainin, inumin Kristo nang matulin;<br/>Pasok nang mabilis, magbuhay-ekklesia,<br/>Maghanda upang salubungin Siya.<br/>',NULL,45123,12);
INSERT INTO stanza VALUES('T10712','2','Magandang buhay-ekklesia!<br/>Ibigay ating lahat sa kanya.<br/>Ang mahal Kristo''t Ekklesia,<br/>Wala nang hahanapin pa.<br/>',NULL,45124,13);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Pasok nang mabilis, magbuhay-ekklesia.<br/>Kainin, inumin Kristo nang matulin;<br/>Pasok nang mabilis, magbuhay-ekklesia,<br/>Maghanda upang salubungin Siya.<br/>',NULL,45125,14);
INSERT INTO stanza VALUES('T10712','3','Magandang buhay-ekklesia!<br/>Masagana bawa''t kapamilya—<br/>Magpangsyon sa pagpupulong,<br/>Tao''y maligtas, sumulong.<br/>',NULL,45126,15);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Pasok nang mabilis, magbuhay-ekklesia.<br/>Kainin, inumin Kristo nang matulin;<br/>Pasok nang mabilis, magbuhay-ekklesia,<br/>Maghanda upang salubungin Siya.<br/>',NULL,45127,16);
INSERT INTO stanza VALUES('T10712','4','Magandang buhay-ekklesia!<br/>Ating mabuting lupa kay yaman.<br/>Tapat tamnan, diligan,<br/>Magpagal tayong lubusan.<br/>',NULL,45128,17);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Pasok nang mabilis, magbuhay-ekklesia.<br/>Kainin, inumin Kristo nang matulin;<br/>Pasok nang mabilis, magbuhay-ekklesia,<br/>Maghanda upang salubungin Siya.<br/>',NULL,45129,18);
INSERT INTO stanza VALUES('T10712','5','Magandang buhay-ekklesia!<br/>Tinayo tayo, Katawang isa.<br/>Ha, ha, Satanas tapos ka,<br/>Tatamuhin Niya ang Nobya!<br/>',NULL,45130,19);
INSERT INTO stanza VALUES('T10712','chorus','(Hey!) Pasok nang mabilis, magbuhay-ekklesia.<br/>Kainin, inumin Kristo nang matulin;<br/>Pasok nang mabilis, magbuhay-ekklesia,<br/>Maghanda upang salubungin Siya.<br/>',NULL,45131,20);
INSERT INTO stanza VALUES('T10713','1','Some, these days, would tell us that our Jesus is not food,<br/>That we only need to know about Him and do good,<br/>But we''re glad to tell you brothers, it''s just not that way—<br/>Jesus is the bread of life; we eat Him every day.<br/>',NULL,45132,1);
INSERT INTO stanza VALUES('T10713','chorus','We love the church life, eating, drinking, breathing Jesus.<br/>We love the church life, taking in God''s Word.<br/>We love to hear those "O Lord, Amen, Hallelujahs!"<br/>We love the church life, feasting with the Lord.<br/>',NULL,45133,2);
INSERT INTO stanza VALUES('T10713','2','When He fills our inward parts, we''re never quite the same,<br/>So much richness we can taste by calling on His name.<br/>"Services" but once a week for us will never do.<br/>Every day we need the fellowship to take us through.<br/>',NULL,45134,3);
INSERT INTO stanza VALUES('T10713','chorus','We love the church life, eating, drinking, breathing Jesus.<br/>We love the church life, taking in God''s Word.<br/>We love to hear those "O Lord, Amen, Hallelujahs!"<br/>We love the church life, feasting with the Lord.<br/>',NULL,45135,4);
INSERT INTO stanza VALUES('T10713','3','If these latter days and situations of the world<br/>Make you feel that round a vicious circle you are swirled,<br/>Then please listen closely to the things we have to say;<br/>It may be that you will find with us the better way.<br/>',NULL,45136,5);
INSERT INTO stanza VALUES('T10713','chorus','We love the church life, eating, drinking, breathing Jesus.<br/>We love the church life, taking in God''s Word.<br/>We love to hear those "O Lord, Amen, Hallelujahs!"<br/>We love the church life, feasting with the Lord.<br/>',NULL,45137,6);
INSERT INTO stanza VALUES('T10713','1','Sa relihiyon, si Hesus ay hindi pagkain.<br/>Gumawa ka lamang at Siya ay kilalanin;<br/>Nguni''t bilang pan ng buhay naparito Siya,<br/>Ka''nin at ibuhay Siya, puspos ng biyaya.<br/>',NULL,45138,7);
INSERT INTO stanza VALUES('T10713','chorus','Iniibig namin ang buhay-ekklesia,<br/>Kainin, inumin, at hingahin Siya.<br/>Iniibig namin ang buhay-ekklesia,<br/>Sa Panginoon kami''y nagpipista.<br/>',NULL,45139,8);
INSERT INTO stanza VALUES('T10713','2','Tumatawag kami sa pangalan Niya lagi,<br/>Pinupuspos Niya ang aming bawa''t bahagi.<br/>"Paglilingkod" di sapat minsan lang sanlinggo.<br/>Araw-araw salamuha ay patotoo.<br/>',NULL,45140,9);
INSERT INTO stanza VALUES('T10713','chorus','Iniibig namin ang buhay-ekklesia,<br/>Kainin, inumin, at hingahin Siya.<br/>Iniibig namin ang buhay-ekklesia,<br/>Sa Panginoon kami''y nagpipista.<br/>',NULL,45141,10);
INSERT INTO stanza VALUES('T10713','3','Ang panahon ngayon ay lalong sumasama;<br/>Gulung-gulo ang buhay mo rito sa lupa.<br/>Kaya''t makinig ka sa aming sinasabi,<br/>Naririto ang daang pinakamabuti.<br/>',NULL,45142,11);
INSERT INTO stanza VALUES('T10713','chorus','Iniibig namin ang buhay-ekklesia,<br/>Kainin, inumin, at hingahin Siya.<br/>Iniibig namin ang buhay-ekklesia,<br/>Sa Panginoon kami''y nagpipista.<br/>',NULL,45143,12);
INSERT INTO stanza VALUES('T10714','1','Come arise early to feast on the Lord.<br/>Let''s come together to enjoy church life.<br/>Morning watch, come daily,<br/>Say amen, spirit free.<br/>Whole day in His presence sweet.<br/>Hallelujah! Lord''s with us.<br/>Hallelujah! Lord''s with us.<br/>Anywhere with joyful song,<br/>We enjoy church life.<br/>',NULL,45144,1);
INSERT INTO stanza VALUES('T10714','2','Speak not of person, position or age,<br/>Let''s come together, Christ we testify.<br/>Share one to another,<br/>In love join together,<br/>As members of His Body.<br/>Hallelujah! As members,<br/>Hallelujah! As members,<br/>Function loyally render,<br/>Glorious church life.<br/>',NULL,45145,2);
INSERT INTO stanza VALUES('T10714','3','Jesus Christ is ours, He is also yours,<br/>Let''s come together to enjoy the Lord,<br/>In the church or at home,<br/>Blessings we all enjoy<br/>Hallelujah! O what joy!<br/>Hallelujah! O what joy!<br/>Hallelujah! O what joy!<br/>Body''s riches I enjoy,<br/>Glorious church life.<br/>',NULL,45146,3);
INSERT INTO stanza VALUES('T10714','4','Say, "Jesus is Lord" shout, "Hallelujah"<br/>Let''s come together to exhibit Christ.<br/>You sing hymn, I give praise,<br/>Testify, all amen,<br/>How refreshing as we meet.<br/>Hallelujah! ''Tis so sweet,<br/>Hallelujah! ''Tis so sweet,<br/>''Tis so living, fresh, and rich,<br/>Glorious church life.<br/>',NULL,45147,4);
INSERT INTO stanza VALUES('T10714','1','Magising nang maaga magpista,<br/>Sa buhay-ekklesia''y magtamasa.<br/>Umagang pagbantay,<br/>Mag-amen, magsanay,<br/>Presensya Niya''y kaakbay.<br/>Aleluya! Sa ''tin Siya.<br/>Aleluya! Sa ''tin Siya.<br/>Saanman awitan,<br/>Katamasahan.<br/>',NULL,45148,5);
INSERT INTO stanza VALUES('T10714','2','Posisyon, edad huwag pag-usapan,<br/>Si Kristo''y ating patotohanan.<br/>Magbabahaginan,<br/>Tayo''y magmahalan,<br/>O sangkap ng Katawan.<br/>Aleluya! Ang sangkap,<br/>Aleluya! Ang sangkap,<br/>Magpangsyon, mal''walhating<br/>Buhay-ekklesia.<br/>',NULL,45149,6);
INSERT INTO stanza VALUES('T10714','3','Hesus ay akin, Siya rin ay i-yo;<br/>Tayo nga''y magtamasa kay Kristo.<br/>Bahay ma''t ekklesia,<br/>Pagpala''y tamasa<br/>Aleluya! Kay saya!<br/>Aleluya! Kay saya!<br/>Aleluya! Kay saya!<br/>Ang yaman ng Katawan,<br/>Katamasahan.<br/>',NULL,45150,7);
INSERT INTO stanza VALUES('T10714','4','Sabihing "Hesus ang Panginoon!"<br/>Sumigaw "Aleluya!" sa Poon.<br/>Itanghal si Kristo,<br/>Umawit ng himno,<br/>Napanariwa tayo!<br/>Aleluya! Kay tamis!<br/>Aleluya! Kay tamis!<br/>Mayaman at sariwa,<br/>Buhay-ekklesia.<br/>',NULL,45151,8);
INSERT INTO stanza VALUES('T10716','1','How we long to go to the feast together!<br/>Our hearts would leap when we hear, "Let us gather!"<br/>Days of fasting and mourning are all over,<br/>Now we enjoy and rejoice as we are together here.<br/>O! Hallelujah, we come to feast,<br/>O! This is just how we all meet!<br/>Just taste and see and one will declare<br/>Its sweetness — nothing can compare.<br/>So we long to go to the feast together!<br/>[Our hearts would leap when we hear, "Let us gather!"<br/>Days of fasting and mourning are all over,<br/>Now we enjoy and rejoice as we are together here.]<br/>',NULL,45152,1);
INSERT INTO stanza VALUES('T10716','2','We come to Jerusalem to have the feast,<br/>Thus we display unity that is of Christ.<br/>The moment we step into Jerusalem,<br/>We cannot help ourselves but praise and glorify His name.<br/>Lo! Jerusalem''s joined so fitly,<br/>How excellent''s the unity!<br/>They who love her shall surely prosper,<br/>For the Lord''s glory is in her.<br/>So come to Jerusalem to have the feast.<br/>[Thus we display unity that is of Christ.<br/>The moment we step into Jerusalem,<br/>We cannot help ourselves but praise and glorify His name.]<br/>',NULL,45153,2);
INSERT INTO stanza VALUES('T10716','3','To meet our God, our hands must ne''er be empty;<br/>Bullock, sheep, pigeons or doves — bring them with thee—<br/>Unleavened bread, firstfruits or fine flour with oil,<br/>To satisfy God and men, present the gifts of your toil!<br/>Lo! Exhibition of Christ''s riches,<br/>How plentiful and glorious!<br/>If we ourselves desire to enjoy,<br/>Our God we first must satisfy.<br/>So to meet God, our hands must ne''er be empty.<br/>[Bullock, sheep, pigeons or doves — bring them with thee—<br/>Unleavened bread, firstfruits or fine flour with oil,<br/>To satisfy God and men, present the gifts of your toil!]<br/>',NULL,45154,3);
INSERT INTO stanza VALUES('T10716','1','Sana''y makapunta tayo sa pista!<br/>Kapag natuloy lulukso sa saya!<br/>Tapos na ang pighati''t pag-ayuno,<br/>Ngayon magkasamang may tamasa''t galak tayo.<br/>O! Aleluya, may pistahan!<br/>Pagpupulong ay pistahan!<br/>Tikma''t tingnan, masabi mo nga<br/>Matamis walang kagaya.<br/>Sana''y makapunta tayo sa pista!<br/>[Kapag natuloy lulukso sa saya!<br/>Tapos na ang pighati''t pag-ayuno,<br/>Ngayon magkasamang may tamasa''t galak tayo.]<br/>',NULL,45155,4);
INSERT INTO stanza VALUES('T10716','2','Halika sa Herusalem magpista,<br/>Ipakita patotoong pagkai-sa.<br/>Sa pagpasok natin sa Herusalem,<br/>Di mapigil ngalan Niya''y purihin, l''walhatiin.<br/>O! Herusalem magkalapat,<br/>Pagkaisa mo''y mahusay!<br/>Umibig sa iyo''y uunlad nga,<br/>''Pagka''t nasa iyo gloria Niya.<br/>Halika, sa Herusalem magpista,<br/>[Ipakita patotoong pagkai-sa.<br/>Sa pagpasok natin sa Herusalem,<br/>Di mapigil ngalan Niya''y purihin, l''walhatiin.]<br/>',NULL,45156,5);
INSERT INTO stanza VALUES('T10716','3','Sa pagharap sa Diyos dapat may dala,<br/>Maging kalapati, tupa o guya—<br/>Harinang may langis, unang bunga man,<br/>Ihain iyong handog nang Diyos at tao masiyahan!<br/>O! Yaman ni Kristong nakita,<br/>Anong l''walhati''t sagana!<br/>Kung nais nating magtamasa,<br/>Diyos bigyan ng lugod muna.<br/>Sa pagharap sa Diyos dapat may dala.<br/>[Maging kalapati, tupa o guya—<br/>Harinang may langis, unang bunga man,<br/>Ihain iyong handog nang Diyos at tao masiyahan!]<br/>',NULL,45157,6);
INSERT INTO stanza VALUES('T10717','1','We''re a group of people with ambition,<br/>Blessings we are to the meeting alway.<br/>We don''t care for religious worshipping,<br/>But to function in a living way.<br/>Hallelujah break bread, pray and sharing,<br/>We take part in all meetings alike.<br/>We''ll not allow deadness in our meeting,<br/>Our job''s to keep the meetings alive.<br/>',NULL,45158,1);
INSERT INTO stanza VALUES('T10717','2','We''re a group of people with ambition,<br/>The spirit of the prophet''s in us.<br/>Once we used it not, but shut and kept it,<br/>Now we will release this spirit thus.<br/>Hallelujah! Let''s release this spirit,<br/>No more silent meeting that awaits;<br/>We''ll all speak for the Lord in the meeting,<br/>For the edifying of the saints.<br/>',NULL,45159,2);
INSERT INTO stanza VALUES('T10717','1','Tayo''y isang grupong may ambisyon,<br/>Pagpapala nga tayo sa pulong.<br/>Putulin relihiyosong pagsamba,<br/>Ang pangsyon ng buhay ipakita.<br/>Sa pagpupulong, anumang uri,<br/>Tayo ay nakikibahagi.<br/>Kamatayan at dilim pawiin,<br/>Bawa''t pagpupulong buhayin!<br/>',NULL,45160,3);
INSERT INTO stanza VALUES('T10717','2','Tayo''y isang grupong may ambisyon,<br/>Di ginamit ''spiritu noon;<br/>Pinapalaya na ito ngayon,<br/>Hindi na muling ikukulong.<br/>Aleluya! ''Spiritung malaya,<br/>Tahimik na pulong wala na!<br/>Upang mga banal maitayo,<br/>Magsalita para kay Kristo.<br/>',NULL,45161,4);
INSERT INTO stanza VALUES('T10719','1','O what joy and rest — in His home I''m dwelling,<br/>Glorious church life — O how sweet.<br/>Breathing His holy Name, eat and drink His Word,<br/>For His glorious recovery.<br/>Walking, in His light of life now we are all walking.<br/>Living, in the church of God now we are all living.<br/>His love preserves me, His light shines on me.<br/>In love all the members built in one.<br/>',NULL,45162,1);
INSERT INTO stanza VALUES('T10720','1','Since I''m in the "Church Life"—<br/>How sweet a foretaste of that day;<br/>New Jerusalem, New Jerusalem,<br/>The rest is complete.<br/>',NULL,45163,1);
INSERT INTO stanza VALUES('T10720','2','The Church today is the land<br/>In which milk and honey flow;<br/>Enjoyment complete, enjoyment complete<br/>The riches of life.<br/>',NULL,45164,2);
INSERT INTO stanza VALUES('T10720','3','The Church builded up is God''s dwelling place<br/>Where He finds rest;<br/>And we rule for Him, and we rule for Him,<br/>God''s plan to fulfill.<br/>',NULL,45165,3);
INSERT INTO stanza VALUES('T10722','1','It''s a new, living meeting that we''re having today.<br/>We are meeting in spirit and we worship this way.<br/>We enjoy the reality of Christ as all,<br/>And leave all of the shadows when on Jesus we call!<br/>',NULL,45166,1);
INSERT INTO stanza VALUES('T10722','chorus','It''s a new, living meeting in a new, living way.<br/>At the beaches, the schools, the parks — wherever we may.<br/>We are slaying the ord''nances, religion too.<br/>Hallelujah! The Spirit of the Lord''s breaking through.<br/>',NULL,45167,2);
INSERT INTO stanza VALUES('T10722','2','We don''t care for religion, we don''t care for the form,<br/>We don''t care for opinions, regulations or norms.<br/>We don''t care for the doctrines that will kill us dead—<br/>Hallelujah! We''re free in our spirit instead!<br/>',NULL,45168,3);
INSERT INTO stanza VALUES('T10722','chorus','It''s a new, living meeting in a new, living way.<br/>At the beaches, the schools, the parks — wherever we may.<br/>We are slaying the ord''nances, religion too.<br/>Hallelujah! The Spirit of the Lord''s breaking through.<br/>',NULL,45169,4);
INSERT INTO stanza VALUES('T10722','3','It''s a new, living meeting, no more oldness we''ll bear,<br/>In the singing, pray-reading it is Christ that we share.<br/>No more old-fashioned meeting in the old, old way.<br/>Hallelujah! The Lord is doing new things today.<br/>',NULL,45170,5);
INSERT INTO stanza VALUES('T10722','chorus','It''s a new, living meeting in a new, living way.<br/>At the beaches, the schools, the parks — wherever we may.<br/>We are slaying the ord''nances, religion too.<br/>Hallelujah! The Spirit of the Lord''s breaking through.<br/>',NULL,45171,6);
INSERT INTO stanza VALUES('T10722','1','Ang pagpupulong natin ay buháy at bago,<br/>Sa ''spiritu sumasamba, malaya tayo;<br/>Kristong realidad tinamasa natin,<br/>Iwan lahat ng lumbay, Hesus ay tawagin.<br/>',NULL,45172,7);
INSERT INTO stanza VALUES('T10722','chorus','Paraan ng pagpulong ay buháy at bago<br/>Paaralan o liwasan — saanman tayo.<br/>Ordinansa, relihiyon inalis na.<br/>Aleluya! Espiritu ay malaya na.<br/>',NULL,45173,8);
INSERT INTO stanza VALUES('T10722','2','Ayaw namin ng porma at ng relihiyon,<br/>Ayaw rin ng regulasyon o ng opinyon;<br/>Ayaw namin ng titik na pumapatay—<br/>Aleluya! Sa ''spiritu tayo ay buháy!<br/>',NULL,45174,9);
INSERT INTO stanza VALUES('T10722','chorus','Paraan ng pagpulong ay buháy at bago<br/>Paaralan o liwasan — saanman tayo.<br/>Ordinansa, relihiyon inalis na.<br/>Aleluya! Espiritu ay malaya na.<br/>',NULL,45175,10);
INSERT INTO stanza VALUES('T10722','3','Bago''t buháy ang pulong, walang kalumaan,<br/>Kristo''y ibahagi sa salita''t awitan;<br/>Lahat ng kalumaan, di matagpuan,<br/>Aleluya! Panginoo''y may bagong daan.<br/>',NULL,45176,11);
INSERT INTO stanza VALUES('T10722','chorus','Paraan ng pagpulong ay buháy at bago<br/>Paaralan o liwasan — saanman tayo.<br/>Ordinansa, relihiyon inalis na.<br/>Aleluya! Espiritu ay malaya na.<br/>',NULL,45177,12);
INSERT INTO stanza VALUES('T10723','1','We have nothing hence to do with idols,<br/>For Christ is our only enjoyment!<br/>We no longer are deceived by the world,<br/>The Church being now our life''s contentment.<br/>',NULL,45178,1);
INSERT INTO stanza VALUES('T10723','chorus','Oh! After dealing, what an enjoyment!<br/>Wine, wine, wine, sweet sweet wine,<br/>Dripping from the mountain!<br/>Oh! Let us praise the Lord, Who is so rich,<br/>Milk, milk, milk, all the hills cannot contain!<br/>',NULL,45179,2);
INSERT INTO stanza VALUES('T10723','2','No longer bound by forms, regulations,<br/>Filled with new wine we''re fully enjoying!<br/>The old dream dreams and the young see visions,<br/>Is anything more pleasant than churching?<br/>',NULL,45180,3);
INSERT INTO stanza VALUES('T10723','chorus','Oh! After dealing, what an enjoyment!<br/>Wine, wine, wine, sweet sweet wine,<br/>Dripping from the mountain!<br/>Oh! Let us praise the Lord, Who is so rich,<br/>Milk, milk, milk, all the hills cannot contain!<br/>',NULL,45181,4);
INSERT INTO stanza VALUES('T10723','3','Walking in spirit, speeds up recov''ry,<br/>Now having redeemed, our ill-spent years!<br/>All are so living, ministering Christ—<br/>Our churching is now richer and richer.<br/>',NULL,45182,5);
INSERT INTO stanza VALUES('T10723','chorus','Oh! After dealing, what an enjoyment!<br/>Wine, wine, wine, sweet sweet wine,<br/>Dripping from the mountain!<br/>Oh! Let us praise the Lord, Who is so rich,<br/>Milk, milk, milk, all the hills cannot contain!<br/>',NULL,45183,6);
INSERT INTO stanza VALUES('T10724','1','Christ the Spirit has set me free,<br/>I, in spirit will set Him free;<br/>His life freed me from sins'' d''pression,<br/>My speaking is His expression.<br/>',NULL,45184,1);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45185,2);
INSERT INTO stanza VALUES('T10724','2','I in Christ''s life He liberates,<br/>Freed from sin and worldly bondage;<br/>With my future all forsaken,<br/>In the spirit thus I''ve taken.<br/>',NULL,45186,3);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45187,4);
INSERT INTO stanza VALUES('T10724','3','In the spirit Christ is so rich,<br/>I may now experience and reach;<br/>Christ I release with spirit high,<br/>Power and wisdom will be mine.<br/>',NULL,45188,5);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45189,6);
INSERT INTO stanza VALUES('T10724','4','O Lord, from all doctrines free me,<br/>From old teachings, Lord, set me free;<br/>Daily in the spirit labor,<br/>Thus, the glorious Christ to savor.<br/>',NULL,45190,7);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45191,8);
INSERT INTO stanza VALUES('T10724','5','Christ is manifested thru me,<br/>Men behold His beauty in me;<br/>My heart fill with His joy will be,<br/>When I set Him at liberty.<br/>',NULL,45192,9);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45193,10);
INSERT INTO stanza VALUES('T10724','6','Lord, I''m dropping here before Thee,<br/>All self-seeking that''s found in me;<br/>Dropping my own feeling and pride,<br/>Let my spirit be exercised.<br/>',NULL,45194,11);
INSERT INTO stanza VALUES('T10724','chorus','Hallelujah, glorious freedom!<br/>God, man co-work, mingle in one.<br/>',NULL,45195,12);
INSERT INTO stanza VALUES('T10724','1','Kristo ako''y pinalaya,<br/>''Spiritu ko''y magpalaya;<br/>Sabihin kahayagan Niya,<br/>Naligtas ako''ng buhay Niya.<br/>',NULL,45196,13);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45197,14);
INSERT INTO stanza VALUES('T10724','2','Kay Kristo ako''y lumaya,<br/>Ligtas sa gapos sa lupa;<br/>Nang hinaharap talikdan,<br/>Sa espiritu''y nakamtan.<br/>',NULL,45198,15);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45199,16);
INSERT INTO stanza VALUES('T10724','3','Sa espiritu''y nanahan,<br/>Ang Kristong ubod ng yaman.<br/>Naghintay na ''king danasin,<br/>Lakas, dunong mapasa ''kin.<br/>',NULL,45200,17);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45201,18);
INSERT INTO stanza VALUES('T10724','4','Sa doktrina at pagtuturo<br/>Poon palayain ako;<br/>Magpagal sa espiritu,<br/>Luwalhati Mo''y masamyo.<br/>',NULL,45202,19);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45203,20);
INSERT INTO stanza VALUES('T10724','5','Sa akin Kristo''y nahayag,<br/>Nakita ang Kanyang rilag;<br/>Tuwing pinalaya ko Siya,<br/>Puso''y puspos ng galak Niya.<br/>',NULL,45204,21);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45205,22);
INSERT INTO stanza VALUES('T10724','6','Pangino''n binitiwan ko,<br/>Pagkamakasarili ko;<br/>Iiwan pagpapalalo,<br/>At sanayin espiritu.<br/>',NULL,45206,23);
INSERT INTO stanza VALUES('T10724','chorus','Aleluya anong laya!<br/>Diyos, tao, hinalong isa.<br/>',NULL,45207,24);
INSERT INTO stanza VALUES('T10725','1','Hallelujah! What mystery!<br/>God in flesh manifests;<br/>The glorious God with His riches,<br/>Through me fully expressed,<br/>Through me fully expressed,<br/>Hallelujah! Fully expressed.<br/>',NULL,45208,1);
INSERT INTO stanza VALUES('T10725','2','I don''t know which member I am,<br/>I know God lives in me;<br/>I don''t ask what function I have,<br/>But let the Spirit free,<br/>But let the Spirit free,<br/>Hallelujah! Let Spirit free.<br/>',NULL,45209,2);
INSERT INTO stanza VALUES('T10725','3','I do not care for position,<br/>But care for Christ in me;<br/>When I insist to take the lead,<br/>Meeting will be down-pressed,<br/>I wish God be expressed,<br/>Hallelujah! God be expressed.<br/>',NULL,45210,3);
INSERT INTO stanza VALUES('T10725','4','Glory! Glory! What mystery!<br/>We are all in spirit.<br/>We''re joined and coordinated,<br/>Expressing glorious church,<br/>Expressing glorious church,<br/>Hallelujah! Glorious church.<br/>',NULL,45211,4);
INSERT INTO stanza VALUES('T10726','1','"Amen" in unison,<br/>Church in truth is spirit;<br/>Not rituals, teachings, methods, forms.<br/>All things be in spirit,<br/>Spirit saturating;<br/>And filling every part!<br/>Purifying and renewing,<br/>Be the man of God''s heart.<br/>',NULL,45212,1);
INSERT INTO stanza VALUES('T10726','2','New wine in new wineskin,<br/>All oldness disappear;<br/>Breaking through the bondage of sin,<br/>Let th'' spirit re-appear.<br/>Brothers, sisters, release!<br/>The church strengthened will be,<br/>Our spirits stirred in joyful bliss,<br/>Th'' church as fresh as can be.<br/>',NULL,45213,2);
INSERT INTO stanza VALUES('T10727','1','Now let us come together to enjoy the Christ in all the saints.<br/>From narrow world of self set free, free from the thought that Christ is mine alone.<br/>But in them who belong to us Christ''s riches we have found;<br/>So let us come together to enjoy the Christ in all the saints.<br/>',NULL,45214,1);
INSERT INTO stanza VALUES('T10727','chorus','Oh, dear brothers, come, make haste now! Fully enjoy all that you have;<br/>When we let Him have the freedom, then together, shall enjoy we.<br/>My experience be your riches, what you''ve labored be my supply;<br/>And we enjoy altogether, here God and men are satisfied.<br/>',NULL,45215,2);
INSERT INTO stanza VALUES('T10727','2','I enjoy you, you enjoy me, then we''ll know how rich to us this Christ be.<br/>I supply you, you supply me, then we''ll find the reality of life.<br/>And in them who belong to me, my inheritance be.<br/>So now together we enjoy, how sweet our lives will be!<br/>',NULL,45216,3);
INSERT INTO stanza VALUES('T10727','chorus','Oh, dear brothers, come, make haste now! Fully enjoy all that you have;<br/>When we let Him have the freedom, then together, shall enjoy we.<br/>My experience be your riches, what you''ve labored be my supply;<br/>And we enjoy altogether, here God and men are satisfied.<br/>',NULL,45217,4);
INSERT INTO stanza VALUES('T10727','1','Ang Kristo ng mga banal ay tamasahin nang husto.<br/>Bitiwan sariling mundo ''pagkat Kristo''y hindi lang sa iyo.<br/>Sa ating kasama yaman ni Kristo''y nakita;<br/>Kaya Kristo ng mga banal sama-samang tamasa.<br/>',NULL,45218,5);
INSERT INTO stanza VALUES('T10727','chorus','O, kapatid, halikayo tamasahin yaman natin!<br/>Makapagtamasa tayo, kapag Siya''y ''ting palayain.<br/>Karanasan ko''y yaman mo, pagpapagal mo''y tustos ko;<br/>Sama-sama magtamasa mas''yahan ang Diyos at tao.<br/>',NULL,45219,6);
INSERT INTO stanza VALUES('T10727','2','Tamasahin kita, tamasahin mo ako, anong yaman Niya.<br/>Kay praktikal ng buhay magtustusan tayo sa isa''t isa.<br/>Sa kanila na akin, naroon ang mana ko.<br/>Anong tamis buhay natin, magtamasa tayo!<br/>',NULL,45220,7);
INSERT INTO stanza VALUES('T10727','chorus','O, kapatid, halikayo tamasahin yaman natin!<br/>Makapagtamasa tayo, kapag Siya''y ''ting palayain.<br/>Karanasan ko''y yaman mo, pagpapagal mo''y tustos ko;<br/>Sama-sama magtamasa mas''yahan ang Diyos at tao.<br/>',NULL,45221,8);
INSERT INTO stanza VALUES('T10728','1','We''re so glad in receiving the saints,<br/>We''re so glad in receiving the saints.<br/>We''re so glad, enjoy sweet fellowship;<br/>Singing glory Hallelujah!<br/>Blessings we will obtain!<br/>',NULL,45222,1);
INSERT INTO stanza VALUES('T10728','2','We''re so glad in receiving the saints,<br/>We''re so glad, by this we serve the Lord.<br/>We''re so glad, the church life is so rich;<br/>Singing glory Hallelujah!<br/>God''s home be recovered!<br/>',NULL,45223,2);
INSERT INTO stanza VALUES('T10728','1','Lubos nga tayong nagagalak,<br/>T''wing mga banal tinatanggap;<br/>Pagsasalamuha''y tamasa,<br/>Aawit ng Aleluya!<br/>Anong pagpapala!<br/>',NULL,45224,3);
INSERT INTO stanza VALUES('T10728','2','Paglilingkod sa Panginoon,<br/>Pagtanggap sa mga banal,<br/>Kay yaman ng buhay-ekklesia;<br/>L''walhati, O Aleluya!<br/>Nabawi bahay Niya!<br/>',NULL,45225,4);
INSERT INTO stanza VALUES('T10729','1','Various vessels in a great house,<br/>You''re which kind of vessels?<br/>Golden, silver, wooden, earthen;<br/>Precious or cheap vessels!<br/>',NULL,45226,1);
INSERT INTO stanza VALUES('T10729','chorus','Purify yourself, shun lowly things,<br/>Precious vessels be ye;<br/>Be sanctified for the Lord''s use,<br/>The Lord''s glory in thee.<br/>',NULL,45227,2);
INSERT INTO stanza VALUES('T10729','2','Wooden, earthen only bring shame,<br/>Not even one I''ll be;<br/>Golden, silver, oh how glorious,<br/>For these I strive to be.<br/>',NULL,45228,3);
INSERT INTO stanza VALUES('T10729','chorus','Purify yourself, shun lowly things,<br/>Precious vessels be ye;<br/>Be sanctified for the Lord''s use,<br/>The Lord''s glory in thee.<br/>',NULL,45229,4);
INSERT INTO stanza VALUES('T10729','3','Too much thinking, analyzing<br/>Make you wooden, earthen;<br/>By anointing, spirit released,<br/>Be ye silver, golden.<br/>',NULL,45230,5);
INSERT INTO stanza VALUES('T10729','chorus','Purify yourself, shun lowly things,<br/>Precious vessels be ye;<br/>Be sanctified for the Lord''s use,<br/>The Lord''s glory in thee.<br/>',NULL,45231,6);
INSERT INTO stanza VALUES('T10730','1','Outflow, outflow, all His riches outflow,<br/>The surplus of His bounteous life through me doth flow;<br/>Outflow, outflow, an outflow of His life,<br/>Let such supply of life to all be full and rife.<br/>The riches in my being comprehend,<br/>The fullness of His riches apprehend,<br/>I''ll be willing to let this life flow out,<br/>By this outflow men will be satisfied no doubt.<br/>',NULL,45232,1);
INSERT INTO stanza VALUES('T10730','2','Release, release let His life be released,<br/>Let all the riches of His life flow out with bliss;<br/>Power, wisdom in this life all are found,<br/>Waiting to be released at all times without bound.<br/>There is no need to shout to be released,<br/>Nor keep silent to religion appease;<br/>Within this life His riches all abound,<br/>If I am free He''ll flow out from me sure and sound.<br/>',NULL,45233,2);
INSERT INTO stanza VALUES('T10730','1','Kanyang kayamana''y paagusin!<br/>Yaman ng buhay mula lo''b paagusin;<br/>Paagusin ang buhay ni Kristo,<br/>Yaman ng buhay ''tustos mo at tustos ko.<br/>Nang yaman sa loob ay malaman,<br/>Nang mabatid sagana ng yaman,<br/>Matamis kong paagusing lubos,<br/>Nang lahat mabusog sa Kanyang panustos.<br/>',NULL,45234,3);
INSERT INTO stanza VALUES('T10730','2','Pagpalaya, buhay palayain,<br/>Lahat ng yaman ng buhay padaluyin;<br/>Lakas, dunong pawang nasa buhay,<br/>Lahat ng panahon handang maitanghal.<br/>Lakas ng sigaw di kailangan,<br/>Ni relihiyosong katahimikan;<br/>Lahat Niya''y nasa buhay na ito.<br/>Aagos na Siya, malaya lamang ako.<br/>',NULL,45235,4);
INSERT INTO stanza VALUES('T10731','1','When my Savior I experience in His love and wealth entire,<br/>When His Spirit fills my spirit as the burning flames of fire,<br/>When His glorious will is made known and I touch His heart''s desire,<br/>Then I shall speak for Him.<br/>',NULL,45236,1);
INSERT INTO stanza VALUES('T10731','chorus','Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>We can speak for the Lord.<br/>',NULL,45237,2);
INSERT INTO stanza VALUES('T10731','2','When I exercise my spirit, in His riches I enjoy,<br/>In the meetings, or with people, or alone, I feel His joy,<br/>I''ll proclaim His love and caring — words of blessing I''ll employ,<br/>Then I shall speak for Him.<br/>',NULL,45238,3);
INSERT INTO stanza VALUES('T10731','chorus','Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>We can speak for the Lord.<br/>',NULL,45239,4);
INSERT INTO stanza VALUES('T10731','3','Lord, I''m willing thus to labor daily on Thy rich supply,<br/>May Thy life enliven, strengthen, and its pow''r in me apply,<br/>Fellowship with Thee, and pray-read Thy word, call Thy name must I,<br/>Then I shall speak for Thee.<br/>',NULL,45240,5);
INSERT INTO stanza VALUES('T10731','chorus','Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>We can speak for the Lord.<br/>',NULL,45241,6);
INSERT INTO stanza VALUES('T10731','4','Lord, we want our spirit always to be living, flowing, free,<br/>Every meeting, we will let You operate exclusively,<br/>No more old religious worship, rituals, or traditions see,<br/>We all can speak for Thee.<br/>',NULL,45242,7);
INSERT INTO stanza VALUES('T10731','chorus','Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>Speaking, speaking, Hallelujah!<br/>We can speak for the Lord.<br/>',NULL,45243,8);
INSERT INTO stanza VALUES('T10731','1','Nang maranasan ko ang kaibig-ibig na Kristo.<br/>Gayang apoy maliyab, pinuspos aking ''spiritu;<br/>Nang mal''walhating layunin sa ''kin, pinahayag Niya,<br/>Ako''y sasalita.<br/>',NULL,45244,9);
INSERT INTO stanza VALUES('T10731','chorus','Magsalita, Aleluya! Magsalita, Aleluya!<br/>Magsalita, Aleluya! Para sa Panginoon.<br/>',NULL,45245,10);
INSERT INTO stanza VALUES('T10731','2','Nang nagsanay ''spiritu ko, tinamasa yaman Niya,<br/>Sa pulong, sa harap ng mga tao, o mag-isa,<br/>Di mapigilan sarili ko na purihin Kita,<br/>Ako''y sasalita.<br/>',NULL,45246,11);
INSERT INTO stanza VALUES('T10731','chorus','Magsalita, Aleluya! Magsalita, Aleluya!<br/>Magsalita, Aleluya! Para sa Panginoon.<br/>',NULL,45247,12);
INSERT INTO stanza VALUES('T10731','3','Panginoon, nais ko na magpagal sa yaman Mo,<br/>Gumawa Iyong buhay nang buhayin katauhan ko,<br/>Basa''t dalangin, Iyong ngala''y tawagin, salamuha;<br/>Ako''y sasalita.<br/>',NULL,45248,13);
INSERT INTO stanza VALUES('T10731','chorus','Magsalita, Aleluya! Magsalita, Aleluya!<br/>Magsalita, Aleluya! Para sa Panginoon.<br/>',NULL,45249,14);
INSERT INTO stanza VALUES('T10731','4','Panginoon, palayain Mo aming espiritu,<br/>Bawa''t pagpulong sa ami''y gumawa Ka nang husto;<br/>Wala nang ritwal, tradisyon, relihiyosong pagsamba,<br/>Kami''y sasalita.<br/>',NULL,45250,15);
INSERT INTO stanza VALUES('T10731','chorus','Magsalita, Aleluya! Magsalita, Aleluya!<br/>Magsalita, Aleluya! Para sa Panginoon.<br/>',NULL,45251,16);
INSERT INTO stanza VALUES('T10732','1','In the church appreciate Thy loveliness,<br/>Thy beauty attracted us to pursue Thee,<br/>O Hallelujah! O Hallelujah!<br/>''Tis Thou that attract us to pursue Thee.<br/>',NULL,45252,1);
INSERT INTO stanza VALUES('T10732','2','In the church we have found our home sweet home,<br/>Peacefully enjoying her riches with joy.<br/>O Hallelujah! O Hallelujah!<br/>Peacefully enjoying riches with joy.<br/>',NULL,45253,2);
INSERT INTO stanza VALUES('T10732','3','In the church follow Him in one accord,<br/>Until the Lord finds satisfaction in us.<br/>O Hallelujah! O Hallelujah!<br/>Until He finds satisfaction in us.<br/>',NULL,45254,3);
INSERT INTO stanza VALUES('T10732','4','In the church, together we are members,<br/>Each one can function in his own living way.<br/>O Hallelujah! O Hallelujah!<br/>Each one functions in his own living way.<br/>',NULL,45255,4);
INSERT INTO stanza VALUES('T10732','5','In the church we do love one another,<br/>Each one supplies and in love edifies.<br/>O Hallelujah! O Hallelujah!<br/>Each one supplies life, in love edifies.<br/>',NULL,45256,5);
INSERT INTO stanza VALUES('T10732','6','In the church we are growing ev''ry day,<br/>Until we arrive at the fullness of Christ.<br/>O Hallelujah! O Hallelujah!<br/>''Tis we arrive at the fullness of Christ.<br/>',NULL,45257,6);
INSERT INTO stanza VALUES('T10732','7','All that we have we give them to the church,<br/>Until the glorious church be fully expressed.<br/>O Hallelujah! O Hallelujah!<br/>''Till the glorious church be fully expressed.<br/>',NULL,45258,7);
INSERT INTO stanza VALUES('T10732','1','Sa ekklesia ay Iyong karilagan,<br/>Sa ami''y nang-akit at hinangaan,<br/>O Aleluya, O Aleluya!<br/>Sa ami''y nang-akit at hinangaan.<br/>',NULL,45259,8);
INSERT INTO stanza VALUES('T10732','2','Sa ekklesia tahanang masaya,<br/>Tinamasa yaman Niyang may pahinga.<br/>O Aleluya, O Aleluya!<br/>Tinamasa yaman Niyang may pahinga.<br/>',NULL,45260,9);
INSERT INTO stanza VALUES('T10732','3','Sa ekklesia Panginoon sundan<br/>Hanggang sa atin Siya ay masiyahan.<br/>O Aleluya, O Aleluya!<br/>Hanggang sa atin Siya ay masiyahan.<br/>',NULL,45261,10);
INSERT INTO stanza VALUES('T10732','4','Magkasangkap tayo sa ekklesia,<br/>Magpapangsyon nang buháy bawa''t isa.<br/>O Aleluya, O Aleluya!<br/>Magpapangsyon nang buháy bawa''t isa.<br/>',NULL,45262,11);
INSERT INTO stanza VALUES('T10732','5','Sa ekklesia magmahalan tayo,<br/>Nagtustusan ng buhay, naitayo.<br/>O Aleluya, O Aleluya!<br/>Nagtustusan ng buhay, naitayo.<br/>',NULL,45263,12);
INSERT INTO stanza VALUES('T10732','6','Laging lumalago sa ekklesia,<br/>Kapuspusan ni Kristo''y maabot na.<br/>O Aleluya, O Aleluya!<br/>Kapuspusan ni Kristo''y maabot na.<br/>',NULL,45264,13);
INSERT INTO stanza VALUES('T10732','7','Lahat nati''y para sa ekklesia<br/>Hanggang mahayag ''l''walhating ekklesia.<br/>O Aleluya, O Aleluya!<br/>Hanggang mahayag ''l''walhating ekklesia!<br/>',NULL,45265,14);
INSERT INTO stanza VALUES('T10733','beginning-note','Malachi 3:10-12<br/>',NULL,45266,1);
INSERT INTO stanza VALUES('T10733','1','Bring your tithes into the store-house,<br/>That there may be food in my house,<br/>And you may prove me now herewith,<br/>Saith Jehovah of hosts aloud.<br/>If I''ll not open heav''n''s windows,<br/>Blessings down pour, no room to store,<br/>For you rebuke the devourer<br/>He''ll not destroy fruits of your toil.<br/>Neither shall your vine cast its fruit<br/>Before the time when in the field.<br/>All nations shall call you blessed;<br/>You shall be a delightsome land.<br/>',NULL,45267,2);
INSERT INTO stanza VALUES('T10734','1','Lord, I commit myself into Thy gracious hand,<br/>I desire to waste myself for the church.<br/>Although the future may bring to me trouble and pain,<br/>I have no regrets, ''cause I am for Thy church.<br/>',NULL,45268,1);
INSERT INTO stanza VALUES('T10735','1','Who is on the Lord''s side?<br/>Who will meet the King?<br/>Who will be in newness,<br/>just Himself to bring?<br/>Who will leave religion, Christianity?<br/>Wrecked for Jesus only,<br/>Who His fools will be?<br/>We are on the Lord''s side!<br/>Let us not grow cold;<br/>Burning in the spirit, In the spirit bold!<br/>',NULL,45269,1);
INSERT INTO stanza VALUES('T10735','2','Sino ang sa panig ng Panginoon?<br/>Sino ang lilisan sa relihiyon?<br/>Sino ang papasok sa kabaguhan,<br/>Mapasa kay Hesus at maging Kanya?<br/>Tayo ay sa panig ng Panginoon,<br/>Kaya''t magpaningas sa espiritu!<br/>',NULL,45270,2);
INSERT INTO stanza VALUES('T10736','1','For the Lord, for the Lord,<br/>For the Lord, for the Lord,<br/>For His church''s recovery!<br/>Come let us, come let us,<br/>Come let us, come let us,<br/>Let us be bold to fight in one accord.<br/>For He has such a need now,<br/>You and I have to care,<br/>While He has such a calling,<br/>How could you and I delay?<br/>',NULL,45271,1);
INSERT INTO stanza VALUES('T10736','2','For the Lord, for the Lord,<br/>For the Lord, for the Lord,<br/>For His glorious test''mony!<br/>Come let us, come let us,<br/>Come let us, come let us,<br/>All in one heart build up in one accord.<br/>We have seen such a great need,<br/>We are here to take heed,<br/>And together we''re lab''ring,<br/>Till He''s fully satisfied.<br/>',NULL,45272,2);
INSERT INTO stanza VALUES('T10736','1','Para sa Pangino''n,<br/>Para sa ekklesia,<br/>Para sa pagbabawi,<br/>Halika, halika!<br/>Halika, halika!<br/>Maging matapang at magkaisa.<br/>Kailangan Niya tayo,<br/>O Ikaw at ako,<br/>Ngayo''y tumatawag Siya,<br/>Bakit pa mag-antala?<br/>',NULL,45273,3);
INSERT INTO stanza VALUES('T10736','2','Para sa Pangino''n,<br/>Para sa ekklesia,<br/>Para sa patotoo,<br/>Halika, halika!<br/>Halika, halika!<br/>Para sa pagtatayo magkai-sa.<br/>Nakita kai-langan Niya,<br/>Oo, mag-alaga,<br/>Sama-samang magpagal,<br/>Hanggang Siya''y maitanghal.<br/>',NULL,45274,4);
INSERT INTO stanza VALUES('T10737','1','This world is not my home, the church is now my home.<br/>My life and all I own, all to the church I''ve borne,<br/>All things in this world are filled with vanity,<br/>If I''m not for the church, what a waste I''ll be.<br/>',NULL,45275,1);
INSERT INTO stanza VALUES('T10737','2','O Lord, the church is what your heart desires<br/>Thy Kingdom to expand, authority transpires.<br/>All I am, all I have, from the world take back.<br/>Now and fore''er I live for the church without lack.<br/>',NULL,45276,2);
INSERT INTO stanza VALUES('T10738','1','The economy of God is Christ with the church;<br/>Christ, embodiment of God, content of church;<br/>Church is the expression of Christ, fullness of God;<br/>Christ is the life-giving Spirit living in us.<br/>',NULL,45277,1);
INSERT INTO stanza VALUES('T10738','2','Lord Jesus! We give our all to You with the church;<br/>To attain Your economy here on earth;<br/>May You be our person and make home in our hearts;<br/>That we all may be filled with the fullness of God.<br/>',NULL,45278,2);
INSERT INTO stanza VALUES('T10738','3','Jesus, saturate and permeate our whole being;<br/>And flow out from us in our life and meetings;<br/>Speaking and administ''ring one to another;<br/>To be Your glorious expression together.<br/>',NULL,45279,3);
INSERT INTO stanza VALUES('T10739','1','I''m in touch, in touch, with Christ I''m in touch,<br/>Christ the Head and I, always in touch.<br/>Every moment in spirit touching Him;<br/>All day long His riches I enjoy.<br/>',NULL,45280,1);
INSERT INTO stanza VALUES('T10739','2','I''m in touch, in touch, with Christ I''m in touch,<br/>In all things, keep touch with Christ the Head.<br/>Great things keep in touch, small things too in touch,<br/>All things man''fest life, glory to th'' Lord.<br/>',NULL,45281,2);
INSERT INTO stanza VALUES('T10739','3','I''m in touch, in touch, with Christ I''m in touch,<br/>With the Body of Christ ever I''m in touch.<br/>Call upon His name, Pray-read too His Word,<br/>Testify and share with all the saints.<br/>',NULL,45282,3);
INSERT INTO stanza VALUES('T10739','4','I''m in touch, in touch, with Christ I''m in touch,<br/>With the Body of Christ ever I''m in touch.<br/>One in fellowship, brothers and sisters,<br/>Man''fest His Body in ev''ry city.<br/>',NULL,45283,4);
INSERT INTO stanza VALUES('T10740','1','Utterly abandoned to the church I''ll boast!<br/>Seeking all His fullness at whatever cost;<br/>Cutting all the shorelines, jump into the flow,<br/>Of His rich life''s supply and blessings I know.<br/>',NULL,45284,1);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45285,2);
INSERT INTO stanza VALUES('T10740','2','Utterly abandoned to the church I''ll boast!<br/>Oh! the dealings, dealings till the self is lost!<br/>Till the vessel''s emptied, broken at His feet,<br/>Till the spirit He fills with Christ''s life complete.<br/>',NULL,45286,3);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45287,4);
INSERT INTO stanza VALUES('T10740','3','Utterly abandoned to the will of God,<br/>Walking in the pathway with strength I have trod;<br/>Fill with glory, gladness, in His path I''ll move,<br/>Waiting for His guidance, witnessing His move.<br/>',NULL,45288,5);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45289,6);
INSERT INTO stanza VALUES('T10740','4','Utterly abandoned! Through eternity;<br/>My will never choosing, His it e''er shall be;<br/>All my plans and longings lost in His sweet will,<br/>Having nothing, owning all things are mine still.<br/>',NULL,45290,7);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45291,8);
INSERT INTO stanza VALUES('T10740','5','Utterly abandoned! Living in the church,<br/>There''s sweet peace in spirit, His will ever search;<br/>Daily lab''ring on Christ, His name to express,<br/>Burning in the spirit, New Man manifest!<br/>',NULL,45292,9);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45293,10);
INSERT INTO stanza VALUES('T10740','6','Lo! His Spirit fills me, the church as my own!<br/>I, in her, am blessed! I, in her, have grown!<br/>Now the vision within never clearer be,<br/>I''m living for the church, waiting faithfully!<br/>',NULL,45294,11);
INSERT INTO stanza VALUES('T10740','chorus','Utterly abandoned,<br/>To the church, my all,<br/>To expand His Kingdom,<br/>Answ''ring His dear call.<br/>',NULL,45295,12);
INSERT INTO stanza VALUES('T10740','1','Paubayang lubos na sa ekklesia!<br/>Mapuspos Niya anuman ang halaga;<br/>Putulin ang pampang, pasok sa agos,<br/>Puspos ng pagpapala at panustos.<br/>',NULL,45296,13);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45297,14);
INSERT INTO stanza VALUES('T10740','2','Paubayang lubos na sa ekklesia!<br/>O! Tuusin nang sarili''y mawala!<br/>Sisidlan mabasyo, mabasag lubos,<br/>Hanggang ''spiritu''y kay Kristo mapuspos.<br/>',NULL,45298,15);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45299,16);
INSERT INTO stanza VALUES('T10740','3','Paubayang lubos sa layon ng Diyos,<br/>Malakas tahakin landas ni Hesus;<br/>Puspos ng l''walhati tuloy pagsulong,<br/>Saksi sa pagkilos, hindi uurong.<br/>',NULL,45300,17);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45301,18);
INSERT INTO stanza VALUES('T10740','4','Paubayang lubos sa walang hanggan;<br/>Sa Kanya, di akin, ang kalooban;<br/>Nawalang lahat sariling hangarin,<br/>Nguni''t lahat ng bagay angkin ko rin.<br/>',NULL,45302,19);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45303,20);
INSERT INTO stanza VALUES('T10740','5','Paubayang lubos na sa ekklesia,<br/>Mamuhay, hanapin kalooban Niya;<br/>Hesus tawagin, magpagal kay Kristo,<br/>Bagong tao''y hayag, ''ningas ''spiritu!<br/>',NULL,45304,21);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45305,22);
INSERT INTO stanza VALUES('T10740','6','Magbuhay ekklesia, puspos ng Kristo,<br/>Sa Kanya''y may pagpapala''t paglago.<br/>Higit na malinaw ang pangitain,<br/>Kay Kristo''t ekklesia, buhay ko''y hain.<br/>',NULL,45306,23);
INSERT INTO stanza VALUES('T10740','chorus','Paubayang lubos na sa ekklesia,<br/>Palaganapin ang kaharian Niya.<br/>',NULL,45307,24);
INSERT INTO stanza VALUES('T10741','1','I only want God''s will be done through me,<br/>''Tis my determination;<br/>''Part from this naught I know whate''er it be<br/>''Cept for His satisfaction.<br/>Let the bright shining future pass my way,<br/>I count them loss come what may,<br/>Every breath of my life I give,<br/>Only for Christ alone I give.<br/>',NULL,45308,1);
INSERT INTO stanza VALUES('T10741','2','Let them strive to build cities and great walls,<br/>Seeking ease and comfort life;<br/>Let them delight in their harps and organs,<br/>Enjoying pleasures of life;<br/>Let them discover modern inventions,<br/>For their best occupations,<br/>I am wholly for God''s own will,<br/>With the world I''ll not compromise still.<br/>',NULL,45309,2);
INSERT INTO stanza VALUES('T10741','3','Now I''ve seen His glorious resurrection,<br/>Through my body expressed be;<br/>Now I''ve witnessed His mighty ascension,<br/>Moving entirely in me;<br/>The throne''s exceeding power now I''ve seen<br/>Lifting and supporting me.<br/>He''s everything this I have seen,<br/>He is my life and my all to be.<br/>',NULL,45310,3);
INSERT INTO stanza VALUES('T10742','1','Gracious Lord, we''re here together, to express our heart desire.<br/>We''re willing to stand together, for Thy church recovery.<br/>To die, to suffer together Thy commission to carry.<br/>To count all things lost together, till Thy triumphant return.<br/>O Lord, fulfill this our desire,<br/>Forever together "we".<br/>Through us may Thou be satisfied,<br/>And Thy plan accomplished be.<br/>',NULL,45311,1);
INSERT INTO stanza VALUES('T10743','1','Lord, I''m willing to spend myself,<br/>For the building of Thy church now;<br/>My knowledge of Thee is shallow,<br/>So do my labor in Thee now.<br/>',NULL,45312,1);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45313,2);
INSERT INTO stanza VALUES('T10743','2','The all-inclusive Christ''s in me,<br/>He is the source, He is the flow,<br/>Only by experiencing Him,<br/>There is quickening in the flow.<br/>',NULL,45314,3);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45315,4);
INSERT INTO stanza VALUES('T10743','3','"To know Christ" is not a slogan,<br/>But in experience we will live,<br/>Enjoyment more, for Him give all,<br/>Experience deep, more to Him give.<br/>',NULL,45316,5);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45317,6);
INSERT INTO stanza VALUES('T10743','4','Though not sitting in third heaven,<br/>I feel I''m raptured in spirit!<br/>Though I''m still living in the flesh,<br/>But to resurrection life heed.<br/>',NULL,45318,7);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45319,8);
INSERT INTO stanza VALUES('T10743','5','I enjoy Him, He enjoys me,<br/>When I gain Him, He gains me too;<br/>We then have mutual enjoyment,<br/>And experiences enriched too.<br/>',NULL,45320,9);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45321,10);
INSERT INTO stanza VALUES('T10743','6','To spend all, I need capital,<br/>Knowing that my treasure is Christ;<br/>All things to me, are all but dung,<br/>I want to gain more of this Christ.<br/>',NULL,45322,11);
INSERT INTO stanza VALUES('T10743','chorus','A determination I make,<br/>It is Christ to know and apply;<br/>Everyday enjoying the Lord,<br/>To gain Christ for the church''s supply.<br/>',NULL,45323,12);
INSERT INTO stanza VALUES('T10744','1','Jesus, I my cross have taken,<br/>For the church my all to give,<br/>Destitute, despised, forsaken,<br/>Narrow way I''ll never leave.<br/>Perish every fond ambition,<br/>All I''ve sought, and hope and known;<br/>Yet how poor is my condition,<br/>Christ and the church still my own!<br/>',NULL,45324,1);
INSERT INTO stanza VALUES('T10744','2','Let the world despise and leave me,<br/>Of this world the church can''t be;<br/>Human hearts and looks deceive me;<br/>The church my reality.<br/>And when in the church I''m living,<br/>Foes may hurt, friends disown me.<br/>Yet how peaceful in my being;<br/>The glorious church now I see.<br/>',NULL,45325,2);
INSERT INTO stanza VALUES('T10744','3','Begone worldly fame and blessings,<br/>O come sufferings, ill and pain,<br/>For God''s will ''tis joy in suff''ring,<br/>Work with Him, all loss are gained.<br/>Abba Father, I have called Thee,<br/>My whole heart I turn to Thee.<br/>Raging storm and clouds surround me,<br/>All things work for good to me.<br/>',NULL,45326,3);
INSERT INTO stanza VALUES('T10744','4','Man may trouble and distress me,<br/>My heart''s desire firm ''twill be.<br/>Life with trials hard may press me,<br/>The church life much sweeter be.<br/>Is there any grief to harm me,<br/>While Thy glory shine on me.<br/>No other joy can now charm me,<br/>''Cept in the church I will be.<br/>',NULL,45327,4);
INSERT INTO stanza VALUES('T10744','5','Forward now! From grace to glory,<br/>Experience the Body''s strength.<br/>Her fullness my reality,<br/>Living for her till my death.<br/>Till earthly min''stry''s conclusion,<br/>Till the race comes to an ending.<br/>Till hope shall turn to glad fruition,<br/>Round the throne our praises ring!<br/>',NULL,45328,5);
INSERT INTO stanza VALUES('T10745','1','It''s not worth the trouble to seek<br/>For my own spiritual''ty,<br/>All my spiritual experience<br/>For Thy habitation be.<br/>',NULL,45329,1);
INSERT INTO stanza VALUES('T10745','chorus','Wholly for the church,<br/>Wholly for the church,<br/>All to thee my beloved church,<br/>Wholly for the church.<br/>',NULL,45330,2);
INSERT INTO stanza VALUES('T10745','2','If for light, rev''lation I seek,<br/>O Lord, hide Thy face from me;<br/>For the building of the churches<br/>Are all my knowledge of Thee.<br/>',NULL,45331,3);
INSERT INTO stanza VALUES('T10745','chorus','Wholly for the church,<br/>Wholly for the church,<br/>All to thee my beloved church,<br/>Wholly for the church.<br/>',NULL,45332,4);
INSERT INTO stanza VALUES('T10745','3','If I boast of spiritual gifts,<br/>Withdraw Thy confirmation;<br/>May Thy spirit daily o''erflow<br/>Into Thy habitation.<br/>',NULL,45333,5);
INSERT INTO stanza VALUES('T10745','chorus','Wholly for the church,<br/>Wholly for the church,<br/>All to thee my beloved church,<br/>Wholly for the church.<br/>',NULL,45334,6);
INSERT INTO stanza VALUES('T10745','4','If I seek for fruits of labor,<br/>Lord, destroy them with Thy hand;<br/>May my work and all my labor,<br/>For Thy building to maintain.<br/>',NULL,45335,7);
INSERT INTO stanza VALUES('T10745','chorus','Wholly for the church,<br/>Wholly for the church,<br/>All to thee my beloved church,<br/>Wholly for the church.<br/>',NULL,45336,8);
INSERT INTO stanza VALUES('T10745','5','If I e''er seek for position,<br/>Lord, cause me to feel ashamed;<br/>Use Thy light to shine and guide me,<br/>Wholly for Thy building claim.<br/>',NULL,45337,9);
INSERT INTO stanza VALUES('T10745','chorus','Wholly for the church,<br/>Wholly for the church,<br/>All to thee my beloved church,<br/>Wholly for the church.<br/>',NULL,45338,10);
INSERT INTO stanza VALUES('T10746','beginning-note','I John 4:7-8<br/>',NULL,45339,1);
INSERT INTO stanza VALUES('T10746','1','Beloved, let us love one another,<br/>For love is of God,<br/>And everyone that loveth is born of God,<br/>And knoweth God.<br/>He that loveth not, knoweth not God,<br/>For God is love.<br/>Beloved, let us love one another,<br/>First John four: seven and eight.<br/>',NULL,45340,2);
INSERT INTO stanza VALUES('T10747','beginning-note','Psalm 90:1-2, 4, 12, 14-17<br/>',NULL,45341,1);
INSERT INTO stanza VALUES('T10747','1','For a thousand years in Thy sight are as yesterday<br/>When it is past, and as a watch in the night.<br/>So teach us to number our days<br/>That we may apply our hearts unto wisdom.<br/>',NULL,45342,2);
INSERT INTO stanza VALUES('T10747','chorus','Lord, Thou hast been our dwelling place in all generations.<br/>Before the mountains were brought forth,<br/>Or ever Thou hadst formed the earth and the world,<br/>Even from eternity to eternity, Thou art God.<br/>',NULL,45343,3);
INSERT INTO stanza VALUES('T10747','2','O satisfy us early with Thy mercy;<br/>That we may rejoice and be glad all our days.<br/>Make us glad according to the days<br/>And the years wherein we have seen evil.<br/>',NULL,45344,4);
INSERT INTO stanza VALUES('T10747','3','Let Thy work appear unto Thy servants,<br/>And Thy glory unto their children.<br/>And let the beauty of the Lord,<br/>The beauty of the Lord our God be upon us.<br/>',NULL,45345,5);
INSERT INTO stanza VALUES('T10748','1','The allurement of riches, the tinsel of fame<br/>Cannot make me these illusions claim;<br/>On the cross I was dead to Satan, world, and sin,<br/>Now I''m living for Jesus, solely for Him.<br/>I''ve given my life and my all to the Lord,<br/>Loving Him, following Him, serving Him more;<br/>Imparting Christ to the poor souls living in strife,<br/>Building up with all the saints His glorious Bride.<br/>',NULL,45346,1);
INSERT INTO stanza VALUES('T10748','2','In the midst of the world, I would no longer roam,<br/>For I''ve found the church, my home sweet home;<br/>Where I with the saints feed together on the Lord,<br/>''Tis the place where I find life so real and good.<br/>I''ve given my life and my all to the church,<br/>Loving her, following her, living for her;<br/>Together with all saints are built as God''s delight,<br/>Waiting for Him to come for His glorious Bride.<br/>',NULL,45347,2);
INSERT INTO stanza VALUES('T10749','1','All the meetings Christ appointed<br/>And attended here on earth<br/>Were apart from all religion,<br/>All its rituals, forms, and dearth.<br/>Resurrection, not religion,<br/>Must be our reality;<br/>Let us meet in resurrection,<br/>From all dead religion free.<br/>',NULL,45348,1);
INSERT INTO stanza VALUES('T10749','2','When the Lord was resurrected,<br/>All religious things were through;<br/>Christ is now our living temple,<br/>Christ is all our offerings too.<br/>With our Lord in resurrection,<br/>Hallelujah, we''re released!<br/>Pity all the old religion—<br/>All our meetings are a feast!<br/>',NULL,45349,2);
INSERT INTO stanza VALUES('T10749','3','Yet religion — oh, how subtle—<br/>In our blood is hiding out;<br/>God must give us revelation,<br/>All that unseen monster rout.<br/>Lord, we still are too religious—<br/>Down with our religious soul!<br/>We would all release our spirit,<br/>Let each meeting reach the goal.<br/>',NULL,45350,3);
INSERT INTO stanza VALUES('T10749','4','In the meetings, in the meetings,<br/>On the mountain, at the shore,<br/>Jesus, Jesus, living Jesus,<br/>He is here — what want we more?<br/>Bury all the old religion,<br/>Even Christianity—<br/>Jesus, Jesus, we have Jesus,<br/>He is our reality!<br/>',NULL,45351,4);
INSERT INTO stanza VALUES('T10750','1','In the Lord''s recovery,<br/>God has chosen us to be<br/>Faithful stewards in His sight,<br/>Who know His heart''s delight.<br/>',NULL,45352,1);
INSERT INTO stanza VALUES('T10750','chorus','We''re the servants of the Lord,<br/>To His purpose we are called;<br/>In His house as stewards we<br/>Caring for His economy.<br/>',NULL,45353,2);
INSERT INTO stanza VALUES('T10750','2','"Lord, reveal Thyself to me,<br/>Knowing Thee subjectively;<br/>Thy desires, Thy will and goal,<br/>To Thee I give my all."<br/>',NULL,45354,3);
INSERT INTO stanza VALUES('T10750','chorus','We''re the servants of the Lord,<br/>To His purpose we are called;<br/>In His house as stewards we<br/>Caring for His economy.<br/>',NULL,45355,4);
INSERT INTO stanza VALUES('T10750','3','In our spirit we abide,<br/>All our needs He would provide;<br/>In the church life we apply<br/>The Christ who satisfies.<br/>',NULL,45356,5);
INSERT INTO stanza VALUES('T10750','chorus','We''re the servants of the Lord,<br/>To His purpose we are called;<br/>In His house as stewards we<br/>Caring for His economy.<br/>',NULL,45357,6);
INSERT INTO stanza VALUES('T10750','4','Now His riches we supply<br/>To the saints — we''d edify;<br/>At His purpose we arrived,<br/>To build up His dear Bride.<br/>',NULL,45358,7);
INSERT INTO stanza VALUES('T10750','chorus','We''re the servants of the Lord,<br/>To His purpose we are called;<br/>In His house as stewards we<br/>Caring for His economy.<br/>',NULL,45359,8);
INSERT INTO stanza VALUES('T10750','1','Sa lo''b ng pagbabawi,<br/>Tayo''y Kanyang pinili;<br/>Tapat na katiwala,<br/>Batid Kanyang si-ya.<br/>',NULL,45360,9);
INSERT INTO stanza VALUES('T10750','chorus','Tayo''y Kanyang alipin,<br/>Tinawag sa layunin;<br/>Nang maging katiwala<br/>Sa Kanyang ekonomiya.<br/>',NULL,45361,10);
INSERT INTO stanza VALUES('T10750','2','"Ihayag Iyong Sarili<br/>Nang amin Kang mabatid;<br/>Naisin at layon Mo,<br/>Sa Iyo na, lahat ko."<br/>',NULL,45362,11);
INSERT INTO stanza VALUES('T10750','chorus','Tayo''y Kanyang alipin,<br/>Tinawag sa layunin;<br/>Nang maging katiwala<br/>Sa Kanyang ekonomiya.<br/>',NULL,45363,12);
INSERT INTO stanza VALUES('T10750','3','Palagi sa ''spiritu,<br/>Siya''y tustos sa lahat ko;<br/>Sa buhay-ekklesia<br/>May Kristong pampasiya.<br/>',NULL,45364,13);
INSERT INTO stanza VALUES('T10750','chorus','Tayo''y Kanyang alipin,<br/>Tinawag sa layunin;<br/>Nang maging katiwala<br/>Sa Kanyang ekonomiya.<br/>',NULL,45365,14);
INSERT INTO stanza VALUES('T10750','4','Yaman Niya ating tustos<br/>Nang banal maitayo;<br/>Layunin Niya''y maratnan:<br/>Kanyang Kasintahan.<br/>',NULL,45366,15);
INSERT INTO stanza VALUES('T10750','chorus','Tayo''y Kanyang alipin,<br/>Tinawag sa layunin;<br/>Nang maging katiwala<br/>Sa Kanyang ekonomiya.<br/>',NULL,45367,16);
INSERT INTO stanza VALUES('T10751','1','Propagate, propagate,<br/>By the Spirit propagate;<br/>We have the way, the life, and God''s word.<br/>Propagate, propagate,<br/>By the Spirit propagate,<br/>Preach the gospel, pray in one accord.<br/>In the church we see<br/>The Lord''s recovery:<br/>His life to dispense into man;<br/>So that God and man are mingled into one,<br/>To accomplish His eternal plan.<br/>',NULL,45368,1);
INSERT INTO stanza VALUES('T10751','2','Tayo ay magpalaganap sa espiritu,<br/>Ipangaral ang ebanghelyo.<br/>Daan, buhay, salita ng Diyos<br/>taglay natin,<br/>Magka-i-sa sa panalangin.<br/>Ang pagbabawi ng Panginoon<br/>Sa ekklesia ay nakita;<br/>Sa buhay, Diyos at tao''y pinag-isa<br/>Upang matupad ang layon Niya.<br/>',NULL,45369,2);
INSERT INTO stanza VALUES('T10753','1','O God of glory, You''ve changed my destiny;<br/>O Lord, Your mercy in love appeared to me.<br/>O God of glory, You have attracted me!<br/>My heart responds to Thee and turns spontaneously.<br/>',NULL,45370,1);
INSERT INTO stanza VALUES('T10753','chorus','O God of glory, You have appeared to me.<br/>Dear Lord, Your beauty, My God, has captured Me!<br/>',NULL,45371,2);
INSERT INTO stanza VALUES('T10753','2','In darkness once I groped, a person with no hope,<br/>But light in darkness shined, my heart enlightened;<br/>You came to me as light and shattered all my night.<br/>Your glory, what a sight! You made me, Lord, so bright.<br/>',NULL,45372,3);
INSERT INTO stanza VALUES('T10753','chorus','O God of glory, You have appeared to me.<br/>Dear Lord, Your beauty, My God, has captured Me!<br/>',NULL,45373,4);
INSERT INTO stanza VALUES('T10753','3','To You my heart was drawn, it wasn''t on my own;<br/>Your beauty made me turn and caused my heart to burn.<br/>You touched my hardened heart and softened every part;<br/>I saw Your shining face; now nothing can erase.<br/>',NULL,45374,5);
INSERT INTO stanza VALUES('T10753','chorus','O God of glory, You have appeared to me.<br/>Dear Lord, Your beauty, My God, has captured Me!<br/>',NULL,45375,6);
INSERT INTO stanza VALUES('T10753','4','Lord, I could not believe, but, Lord, You still appeared;<br/>Your life in me conceived, dear Lord, I now believe.<br/>You called not being as being in me conceiving;<br/>Your life transfusing, I''m now reacting.<br/>',NULL,45376,7);
INSERT INTO stanza VALUES('T10753','chorus','O God of Glory, You''re now my story.<br/>Dear One, I can''t refuse! By You, I''ve been transfused.<br/>',NULL,45377,8);
INSERT INTO stanza VALUES('T10753','5','Like father Abraham, to You, dear Lord, he ran.<br/>With glory we''re infused, dear Lord, we can''t refuse.<br/>You came to fallen man as, Lord, the Great I Am<br/>In us dispensing the blessing to mankind.<br/>',NULL,45378,9);
INSERT INTO stanza VALUES('T10753','chorus','O God of Glory, You''re now my story.<br/>Dear One, I can''t refuse! By You, I''ve been transfused.<br/>',NULL,45379,10);
INSERT INTO stanza VALUES('T10801','1','Into the flow of recov''ry,<br/>In His glorious economy,<br/>We are serving in the Body,<br/>To be built, fulfilling God''s will;<br/>',NULL,45380,1);
INSERT INTO stanza VALUES('T10801','2','Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Everyone: O what a joy!<br/>',NULL,45381,2);
INSERT INTO stanza VALUES('T10801','1','The lust of the world soon shall pass,<br/>The will of God shall always last.<br/>We will not be drifted away,<br/>Together we''ll be built, thus to stay,<br/>Never to part.<br/>',NULL,45382,3);
INSERT INTO stanza VALUES('T10801','4','Into the flow of recov''ry,<br/>In His glorious economy,<br/>We are serving in the Body,<br/>To be built, fulfilling God''s will;<br/>',NULL,45383,4);
INSERT INTO stanza VALUES('T10801','5','Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Everyone: O what a joy!<br/>',NULL,45384,5);
INSERT INTO stanza VALUES('T10801','2','I''ve wasted my time in the world,<br/>Not caring for the move of the Lord.<br/>All my pursuing were empty dreams,<br/>Like chasing the shadows and the winds,<br/>All things are vain.<br/>',NULL,45385,6);
INSERT INTO stanza VALUES('T10801','7','Into the flow of recov''ry,<br/>In His glorious economy,<br/>We are serving in the Body,<br/>To be built, fulfilling God''s will;<br/>',NULL,45386,7);
INSERT INTO stanza VALUES('T10801','8','Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Brothers: To be built,<br/>Sisters: Fulfilling God''s will.<br/>Everyone: O what a joy!<br/>',NULL,45387,8);
INSERT INTO stanza VALUES('T10801','3','By His mercy, I''m not cast away,<br/>His love brought me to Bethel stay.<br/>In His glorious economy,<br/>My life has its meaning and its goal,<br/>All things are real.<br/>',NULL,45388,9);
INSERT INTO stanza VALUES('T10802','1','We have such a glor-i-ous King,<br/>The heaven above is His seat;<br/>The earth under His feet bowing,<br/>All nations under His rule lead.<br/>With all His people He abides,<br/>Of their afflictions to partake;<br/>Put all the sense of shame aside,<br/>As co-workers this part we take!<br/>',NULL,45389,1);
INSERT INTO stanza VALUES('T10802','2','When we are working with our King,<br/>All our works upon Him we laid;<br/>All the living ones to Him bring,<br/>By the glorious stirring He made.<br/>We''re able to work with our King,<br/>''Twas all by His power upheld;<br/>So, duties turn to song I''ll sing,<br/>And prayers to praises are led.<br/>',NULL,45390,2);
INSERT INTO stanza VALUES('T10802','3','We work and enjoy with our King,<br/>The uplifted gospel we preach;<br/>That millions of saved ones we''d bring,<br/>And the earth His kingdom shall reach.<br/>What this world could offer to us.<br/>The least bit we never would take;<br/>To work on people is our job,<br/>Till all these His Bride we shall make.<br/>',NULL,45391,3);
INSERT INTO stanza VALUES('T10802','4','We always co-work with our King,<br/>By working crazily on men;<br/>''Ere the winter comes or even spring,<br/>The King of Glory may come then!<br/>We shall gather about Him ''round;<br/>With gladness and praises abound,<br/>Eternal Hallelujahs sound;<br/>And Hallelujah, we are crowned!<br/>',NULL,45392,4);
INSERT INTO stanza VALUES('T10802','1','Tayo''y may ''l''walhating Hari,<br/>Kalangitan Kanyang trono;<br/>Bu''ng lupa sa paanan Niya,<br/>Mga bansa''y Siyang namuno.<br/>Kasama mamamayan Niya,<br/>Kabahagi rin sa dusa;<br/>Kamanggagawa ng Hari!<br/>L''walhati, di mapahiya!<br/>',NULL,45393,5);
INSERT INTO stanza VALUES('T10802','2','Kamanggagawa ng Hari,<br/>Gawa''y Kanya, di sa akin;<br/>Ginawa tayong l''walhati<br/>Nang iba''y mabuhay natin.<br/>Kamanggagawa ng Hari,<br/>Lakas Niya ang nagsuporta;<br/>Obligasyon naging galak,<br/>Daing naging puri''t samba.<br/>',NULL,45394,6);
INSERT INTO stanza VALUES('T10802','3','Katamasa nga ang Hari,<br/>Ipahayag ebanghelyo;<br/>Maligtas milyong katao,<br/>Dalhin kaharian dito.<br/>Mundo ma''y mag-alok sa ''tin,<br/>Hindi natin tatanggapin;<br/>Gawai''y tao tamuhin<br/>Upang Nobya''y paghandain.<br/>',NULL,45395,7);
INSERT INTO stanza VALUES('T10802','4','Tuloy kasama ng Hari,<br/>Tamuhin ang mga tao;<br/>Taglamig di pa sumapit,<br/>Baka Hari''y maparito!<br/>Palilibutan natin Siya,<br/>Mapatalon sa ligaya;<br/>Aleluya Siya''y maghari,<br/>Walang hanggan Aleluya!<br/>',NULL,45396,8);
INSERT INTO stanza VALUES('T10803','1','I''ve never been sorry — I heeded God''s call,<br/>I''ve never been sorry — I yielded my all;<br/>My walk with the Master — grows sweeter each day;<br/>I''ve never been sorry — one step of the way.<br/>',NULL,45397,1);
INSERT INTO stanza VALUES('T10803','2','Di ako nagsisi — Diyos pinakinggan,<br/>Di ako nagsisi — sinuko''ng tanan;<br/>Lakad kasama Siya — mas tumatamis,<br/>Di ako nagsisi — nang kahit minsan.<br/>',NULL,45398,2);
INSERT INTO stanza VALUES('T10804','1','A new day has dawned<br/>The saints are going on,<br/>The glory of the Lord is coming down;<br/>All around me I can see<br/>There are signs of victory,<br/>Hallelujah, a new day has dawned!<br/>',NULL,45399,1);
INSERT INTO stanza VALUES('T10805','1','Marching on, marching on, in the Spirit marching on;<br/>Hallelujah! The churches march on.<br/>Marching on, marching on, in the Spirit marching on;<br/>Hallelujah! The churches march on.<br/>In the church we see<br/>The Lord''s recovery,<br/>And for it the Spirit seven-strong.<br/>The world will know,<br/>Wherever we shall go,<br/>That in our age the Lord''s marching on!<br/>',NULL,45400,1);
INSERT INTO stanza VALUES('T10806','1','From the local church in Manila, to the north and south isles bay.<br/>We will fight the churches battle, in a new and living way.<br/>We will spread the local church life in the Philippines today.<br/>Touching every major city, as we move along the way.<br/>This is the Lord''s recovery,<br/>This is His move today.<br/>Brothers we must move together in a strong united way.<br/>',NULL,45401,1);
INSERT INTO stanza VALUES('T10807','1','Be strong in the Lord!In the power of His might,<br/>Be strong in the Lord!<br/>Be strong in the Lord! In the power of His might,<br/>Be strong in the Lord!<br/>Be strong in the Lord! In the power of His might;<br/>Be strong in the Lord! In the power of His might.<br/>Be strong in the Lord! Be strong in the Lord!<br/>In the power of His might, be strong!<br/>',NULL,45402,1);
INSERT INTO stanza VALUES('T10807','2','Magpakalakas! Sa kapangyarihan Niya,<br/>Magpakalakas!<br/>Magpakalakas! Sa kapangyarihan Niya,<br/>Magpakalakas!<br/>Magpakalakas! Sa kapangyarihan Niya;<br/>Magpakalakas! Sa kapangyarihan Niya.<br/>Magpakalakas! Magpakalakas!<br/>Sa kapangyarihan Niya! Lakas!<br/>',NULL,45403,2);
INSERT INTO stanza VALUES('T10808','1','Fight, saints, for Jesus our Lord!<br/>Take in His life, stand in one accord!<br/>Never fear God''s enemy!<br/>Tread on His head triumphantly!<br/>Pray that the daily church life be strong,<br/>That all the saints in spirit press on,<br/>Fighting as the one new man,<br/>Fulfilling our Lord''s great plan!<br/>(Glory! Hallelujah!)<br/>',NULL,45404,1);
INSERT INTO stanza VALUES('T10809','1','O, praise the Lord, in Jesus Christ<br/>We''re more than conquerors!<br/>For we know — all things work together<br/>For our benefit.<br/>The Church is chosen by the Lord<br/>According to God''s will.<br/>She''s victorious, all victorious—<br/>Her essence''s victorious (FINE)<br/>The enemy''s grudging, from all sides often came—<br/>Tribulation, distress, persecution, famine. . . .<br/>In all these things we''re more than conquerors<br/>Through our Lord.<br/>Vic''try, the full victory attained<br/>The full victory attained<br/>The full victory attained. (D.C.)<br/>',NULL,45405,1);
INSERT INTO stanza VALUES('T10810','1','I dare not be defeated<br/>With glorious church in view,<br/>Where Christ her head, third heav''n sits,<br/>Where all her foes He slew;<br/>Thus in this vision I live,<br/>Strengthened I''ll ever be;<br/>Now I''m an overcomer<br/>For His recovery.<br/>',NULL,45406,1);
INSERT INTO stanza VALUES('T10810','chorus','A victor, a victor!<br/>Because of glorious church.<br/>Now I''m an overcomer,<br/>A victor, a victor by the church.<br/>',NULL,45407,2);
INSERT INTO stanza VALUES('T10810','2','I dare not be defeated<br/>Since Christ my glorious King<br/>Has called me to the battle<br/>Which He did surely win.<br/>Thus I am filled with courage,<br/>Strong in spirit I''ll be;<br/>Now I''m an overcomer,<br/>Completely filled with Thee.<br/>',NULL,45408,3);
INSERT INTO stanza VALUES('T10810','chorus','A victor, a victor!<br/>Because of glorious church.<br/>Now I''m an overcomer,<br/>A victor, a victor by the church.<br/>',NULL,45409,4);
INSERT INTO stanza VALUES('T10810','3','I dare not be defeated—<br/>Enlisted in the church<br/>To press through hellish regions<br/>And God''s will I''ll e''er search.<br/>We are His mighty soldiers,<br/>With pow''r we wield the sword;<br/>Now we are overcomers,<br/>Testifying His Word.<br/>',NULL,45410,5);
INSERT INTO stanza VALUES('T10810','chorus','A victor, a victor!<br/>Because of glorious church.<br/>Now I''m an overcomer,<br/>A victor, a victor by the church.<br/>',NULL,45411,6);
INSERT INTO stanza VALUES('T10810','4','I dare not be defeated<br/>In times of victory,<br/>My glorious King shall return,<br/>"Well done, beloved", saith He.<br/>In heav''ns together living,<br/>His mighty pow''r o''ercast;<br/>Daily overcomer be,<br/>A victor to the last.<br/>',NULL,45412,7);
INSERT INTO stanza VALUES('T10810','chorus','A victor, a victor!<br/>Because of glorious church.<br/>Now I''m an overcomer,<br/>A victor, a victor by the church.<br/>',NULL,45413,8);
INSERT INTO stanza VALUES('T10810','1','''Di ako patatalo<br/>D''hil sa nakita ko;<br/>Ekklesiang mal''walhati,<br/>Kristo''y Ulo''t Hari.<br/>Sa pangitaing ito,<br/>Napalalakas ako;<br/>Para sa pagbabawi,<br/>Ako''y mandaraig.<br/>',NULL,45414,9);
INSERT INTO stanza VALUES('T10810','chorus','Nagwagi! Nagwagi!<br/>Dahil sa ekklesia!<br/>Ako''y ''sang mandaraig<br/>Nagwagi dahil sa ekklesia!<br/>',NULL,45415,10);
INSERT INTO stanza VALUES('T10810','2','''Di ako patatalo,<br/>Hari ko''y si Kristo;<br/>Siyang tumawag sa akin,<br/>Digma''y panalunin.<br/>Kaya''t puspos ng gilas,<br/>''Spiritu''y malakas;<br/>Dahil sa pagpuspos Mo,<br/>Mandaraig ako!<br/>',NULL,45416,11);
INSERT INTO stanza VALUES('T10810','chorus','Nagwagi! Nagwagi!<br/>Dahil sa ekklesia!<br/>Ako''y ''sang mandaraig<br/>Nagwagi dahil sa ekklesia!<br/>',NULL,45417,12);
INSERT INTO stanza VALUES('T10810','3','''Di ako patatalo<br/>Sa ekklesia ako;<br/>Layon ng Diyos nais ko,<br/>Laban sa impiyerno.<br/>Kawal na magigiting,<br/>Sa tabak magaling;<br/>Mandaraig nga tayo,<br/>Salita''y totoo.<br/>',NULL,45418,13);
INSERT INTO stanza VALUES('T10810','chorus','Nagwagi! Nagwagi!<br/>Dahil sa ekklesia!<br/>Ako''y ''sang mandaraig<br/>Nagwagi dahil sa ekklesia!<br/>',NULL,45419,14);
INSERT INTO stanza VALUES('T10810','4','''Di ako patatalo,<br/>Babalik Hari ko;<br/>Sasabihan Niya ako:<br/>"Mabuti, mahal ko!"<br/>Mamumuhay sa langit.<br/>Lakas Niya''y hihigit;<br/>Daraig araw-araw,<br/>Laging nangibabaw!<br/>',NULL,45420,15);
INSERT INTO stanza VALUES('T10810','chorus','Nagwagi! Nagwagi!<br/>Dahil sa ekklesia!<br/>Ako''y ''sang mandaraig<br/>Nagwagi dahil sa ekklesia!<br/>',NULL,45421,16);
INSERT INTO stanza VALUES('T10813','beginning-note','Matthew 25:1-13<br/>',NULL,45422,1);
INSERT INTO stanza VALUES('T10813','1','All the signs point to the end,<br/>Christ soon will be here again;<br/>We must be ready for Him—<br/>Jesus is coming again!<br/>',NULL,45423,2);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45424,3);
INSERT INTO stanza VALUES('T10813','2','From soul and self turn away,<br/>Look unto Jesus today;<br/>There is no time to delay—<br/>Jesus is coming again!<br/>',NULL,45425,4);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45426,5);
INSERT INTO stanza VALUES('T10813','3','Foolish ones never will turn;<br/>When the Lord comes they will learn<br/>There is no oil left to burn—<br/>Jesus is coming again!<br/>',NULL,45427,6);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45428,7);
INSERT INTO stanza VALUES('T10813','4','Wise virgins buy up the time;<br/>Never drunk with the world''s wine,<br/>Filled in the spirit they shine—<br/>Jesus is coming again!<br/>',NULL,45429,8);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45430,9);
INSERT INTO stanza VALUES('T10813','5','Let us go forth unto Him,<br/>Not only with our lamps trimmed,<br/>Buy the oil now lest they dim—<br/>Jesus is coming again!<br/>',NULL,45431,10);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45432,11);
INSERT INTO stanza VALUES('T10813','6','Jesus is now on His way,<br/>Watch, for you know not the day;<br/>Ever in His presence stay—<br/>Jesus is coming again!<br/>',NULL,45433,12);
INSERT INTO stanza VALUES('T10813','chorus','Coming again, coming again,<br/>Time is swiftly passing by,<br/>Soon we may hear the midnight cry!<br/>Coming again, coming again,<br/>As the wise virgins we must be prepared!<br/>Jesus is coming again!<br/>',NULL,45434,13);
INSERT INTO stanza VALUES('T10814','1','The Lord soon will come — with the world now be done;<br/>Lay aside every weight and the race swiftly run!<br/>',NULL,45435,1);
INSERT INTO stanza VALUES('T10814','chorus','He is coming! He is coming! He is coming again!<br/>He is coming! He is coming! Amen, Lord! Amen!<br/>',NULL,45436,2);
INSERT INTO stanza VALUES('T10814','2','It may be today — to the Lord look away,<br/>Look away unto Jesus whatever dismay.<br/>',NULL,45437,3);
INSERT INTO stanza VALUES('T10814','chorus','He is coming! He is coming! He is coming again!<br/>He is coming! He is coming! Amen, Lord! Amen!<br/>',NULL,45438,4);
INSERT INTO stanza VALUES('T10814','3','From self, world, and sin look away unto Him,<br/>To the One Who will finish what He did begin.<br/>',NULL,45439,5);
INSERT INTO stanza VALUES('T10814','chorus','He is coming! He is coming! He is coming again!<br/>He is coming! He is coming! Amen, Lord! Amen!<br/>',NULL,45440,6);
INSERT INTO stanza VALUES('T10814','4','We''ll gaze in His face and be filled with His grace<br/>That with Him in His kingdom we''ll lose not our place.<br/>',NULL,45441,7);
INSERT INTO stanza VALUES('T10814','chorus','He is coming! He is coming! He is coming again!<br/>He is coming! He is coming! Amen, Lord! Amen!<br/>',NULL,45442,8);
INSERT INTO stanza VALUES('T10814','5','We''ll amen His Word — what we''ve read or we''ve heard.<br/>To be ready for Jesus, we all have been stirred.<br/>',NULL,45443,9);
INSERT INTO stanza VALUES('T10814','chorus','He is coming! He is coming! He is coming again!<br/>He is coming! He is coming! Amen, Lord! Amen!<br/>',NULL,45444,10);
INSERT INTO stanza VALUES('T10815','beginning-note','Matthew 25:1-13<br/>',NULL,45445,1);
INSERT INTO stanza VALUES('T10815','1','Rejoice! Rejoice! Our Bridegroom''s coming,<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,45446,2);
INSERT INTO stanza VALUES('T10815','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come:<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,45447,3);
INSERT INTO stanza VALUES('T10815','2','Oh, let us now redeem each moment,<br/>More the precious oil to buy,<br/>And have our vessels filled with ointment<br/>Ere we hear the midnight cry.<br/>',NULL,45448,4);
INSERT INTO stanza VALUES('T10815','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come:<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,45449,5);
INSERT INTO stanza VALUES('T10815','3','Oh, what a joy it is preparing<br/>For our wedding with the Lord,<br/>E''en in the tribulations sharing<br/>For the bliss of such reward!<br/>',NULL,45450,6);
INSERT INTO stanza VALUES('T10815','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come:<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,45451,7);
INSERT INTO stanza VALUES('T10815','4','Oh, with what rapture and rejoicing<br/>Shall the wedding day begin;<br/>And then a thousand years of dining<br/>At the marriage feast with Him!<br/>',NULL,45452,8);
INSERT INTO stanza VALUES('T10815','chorus','Oh, wondrous day! Oh, glorious morning,<br/>When the Christ we love shall come:<br/>With vessels filled and lamps all burning<br/>Let us welcome His return.<br/>Rejoice! Rejoice! Our Bridegroom''s coming<br/>And the time will not be long<br/>Before we hail that wedding morning<br/>And lift up the glad new song.<br/>',NULL,45453,9);
INSERT INTO stanza VALUES('T10816','1','The Lord may come back at any moment,<br/>The Lord may come back at any moment,<br/>The Lord may come back at any moment,<br/>So let us watch and be prepared.<br/>',NULL,45454,1);
INSERT INTO stanza VALUES('T10816','2','O Jesus Christ is our lovely Bridegroom,<br/>O Jesus Christ is our lovely Bridegroom,<br/>O Jesus Christ is our lovely Bridegroom,<br/>And we are His — His chosen Bride.<br/>',NULL,45455,2);
INSERT INTO stanza VALUES('T10816','3','We have decided to look to Jesus,<br/>We have decided to look to Jesus,<br/>We have decided to look to Jesus,<br/>No turning back, no turning back.<br/>',NULL,45456,3);
INSERT INTO stanza VALUES('T10816','4','The race before us, all cares behind us,<br/>The race before us, all cares behind us,<br/>The race before us, all cares behind us,<br/>We''re pressing on, we''re pressing on.<br/>',NULL,45457,4);
INSERT INTO stanza VALUES('T10816','5','We''re pressing forward to bring our Lord back,<br/>We''re pressing forward to bring our Lord back,<br/>We''re pressing forward to bring our Lord back,<br/>Soon face to face, we''ll meet our Lord.<br/>',NULL,45458,5);
INSERT INTO stanza VALUES('T10817','1','Wake up, brothers! Wake up, sisters!<br/>Night is far spent, and day is now at hand.<br/>Soon our Lord shall come again, come again, come again.<br/>Soon our Lord shall come again, and in His kingdom reign.<br/>',NULL,45459,1);
INSERT INTO stanza VALUES('T10817','2','Let''s get ready! Don''t be lazy!<br/>Spend time with Him till we are filled within.<br/>O let us be filled with Him, filled with Him, filled with Him,<br/>O let us be filled with Him till th'' cup o''erflow the brim.<br/>',NULL,45460,2);
INSERT INTO stanza VALUES('T10817','3','Cheer up, brothers! Cheer up, sisters!<br/>Whate''er betide, always in Him abide.<br/>Merrily, we roll along, roll along, roll along,<br/>Though the night be dark and drear, with Him we''ll never fear.<br/>',NULL,45461,3);
INSERT INTO stanza VALUES('T10817','4','Stand firm, brothers! Stand firm, sisters!<br/>Fight won''t be long, press on with spirit strong.<br/>Till our Lord shall come again, come again, come again,<br/>Till our Lord shall come again, we with Him shall reign.<br/>',NULL,45462,4);
INSERT INTO stanza VALUES('T10817','1','Gising! Gising! O kapatid!<br/>Malapit nang magbukang-liwayway.<br/>Panginoon darating, darating, darating,<br/>Maghahari na rin Siya, sa kaharian Niya!<br/>',NULL,45463,5);
INSERT INTO stanza VALUES('T10817','2','Huwag tamarin! Magsihanda!<br/>Gumugol ng panahon sa Kanya,<br/>Magpapuspos sa Kanya, sa Kanya, sa Kanya,<br/>Magpuspos hanggang sa mag-umapaw na Siya.<br/>',NULL,45464,6);
INSERT INTO stanza VALUES('T10817','3','Mangagalak! O kapatid!<br/>Manatili palagi sa Kanya;<br/>Masayang sumusulong, susulong, susulong;<br/>''Nong dilim man ng gabi, walang takot kami!<br/>',NULL,45465,7);
INSERT INTO stanza VALUES('T10817','4','Magsitibay! O kapatid!<br/>Magwawakas na pakipagbaka,<br/>Hanggang sa dumating Siya! Dumating, dumating!<br/>Maghaharing kasama sa kaharian Niya!<br/>',NULL,45466,8);
INSERT INTO stanza VALUES('T10818','1','Dear Lord, my heart''s delight, come back soon, I plead,<br/>With me e''er abide, let me lean upon Thy breast,<br/>Look unto Thy countenance, face to face see Thee!<br/>Pour forth my heart with all the memories my best.<br/>Dear Lord, I love Thee!<br/>Dear Lord, I cherish, desire Thee<br/>As hind longed for stream,<br/>And drought longed for show''r from Thee,<br/>Mine eyes be plucked, and heart be pierced—<br/>When? This love-sick be comforted, hear Thou my plea.<br/>',NULL,45467,1);
INSERT INTO stanza VALUES('T10818','2','Beloved, my heart''s delight! My treasure art Thou,<br/>Round ''bout Thee entwined, loving Thee, beloved Lord;<br/>To be with Thee every hour, and Thy shadow be,<br/>Though in my dreams, I can''t forget Thy loving form.<br/>Such love and moment, dear Lord,<br/>How could it be portrayed?<br/>Melted my heart by Thee, for Thee I give all, Lord.<br/>For in the universe who can Thy love and mercy compare?<br/>O come, my Lord!<br/>',NULL,45468,2);
INSERT INTO stanza VALUES('T10818','3','Great Lord! My heart belongs, my Shepherd art Thou,<br/>My soul Thou hast filled, on the cross Thy life has laid.<br/>And purchased me with Thy blood, now I give myself,<br/>All that I have to Thee as off''ring I have made.<br/>Oh Lord, do come back, my love and my all to enjoy;<br/>Far above earthly ties, my love flows as ointment;<br/>Heav''n, earth abide, our love persists;<br/>No sea nor rock this thought outlives, my plea, Amen!<br/>',NULL,45469,3);
INSERT INTO stanza VALUES('T10818','4','Sweet Lord! To Thee I''m bound, grant me wings, I pray,<br/>That to Thee I''ll fly; oft I on the sky would gaze,<br/>To see Thy sweet coming, Lord, raptured before Thee;<br/>Yet Thy dear dorm cannot be found, save empty haze.<br/>Heavens! Why hold Him?<br/>My heart is bleeding and pleading!<br/>Lord, how could Thou have rest, not caring my languish?<br/>My love, how could Thou fore''er delay?<br/>No matter what, quickly return! Grant Thou my wish!<br/>',NULL,45470,4);
INSERT INTO stanza VALUES('T10819','1','Behold the fig tree has shooted forth,<br/>Jerusalem''s no longer trodden,<br/>O Hallelujah, how blessed we are<br/>Our eyes shall see redemption fulfilled!<br/>This generation, th'' end generation,<br/>Surely shall bring the Lord back again.<br/>',NULL,45471,1);
INSERT INTO stanza VALUES('T10819','2','Worry not about your future now,<br/>Do not seek the world as others do.<br/>Come out of Sodom, enter the ark now,<br/>Daily the church life experience.<br/>Now is the time to lift up and look up,<br/>To spread the gospel and save more souls.<br/>',NULL,45472,2);
INSERT INTO stanza VALUES('T10819','3','Lord, keep our spirit, soul, and body<br/>That all the meetings we may attend.<br/>The Lord might appear this very moment<br/>As we are meeting and praising Him.<br/>Without our knowing we will be raptured<br/>Sing Hallelujah, into glory.<br/>',NULL,45473,3);
INSERT INTO stanza VALUES('T10820','1','Farewell, farewell to all the world<br/>Let this world pass away.<br/>The Lord is coming very soon,<br/>So why should I delay?<br/>Farewell to ease and rotten life,<br/>To earthly pleasures too.<br/>Farewell to all our burdens then,<br/>And never turning back.<br/>',NULL,45474,1);
INSERT INTO stanza VALUES('T10821','1','We admired how Thy disciples on the mountain<br/>Beheld Thee transfigured before them.<br/>Like the sun, Thy face shone so gloriously divine,<br/>And Thy garments so brightly sublime.<br/>Now as we think of Thee and Thy coming so near,<br/>Waves of joy flood our hearts with great cheer.<br/>''Cause we know that as we stand here ere we taste death,<br/>Here Thyself will be manifested.<br/>',NULL,45475,1);
INSERT INTO stanza VALUES('T10821','2','Though how nice they had seen Thy transfiguration,<br/>Thou art still in Thy limitation.<br/>For Thou has not yet passed through the portals of death,<br/>Thou''rt just Son in the bosom of God.<br/>Now Thou''rt coming again, full glory to receive.<br/>Endless praises to Thee millions give.<br/>Thou, the King of all kings and the Lord of all lords<br/>Wilt forever live with Thy people.<br/>',NULL,45476,2);
INSERT INTO stanza VALUES('T10821','3','Lord, we praise Thee, besides the glory Thou''rt getting,<br/>Thou wilt many sons to glory bring;<br/>We''re but sinners redeemed by Thy grace in Thy sight,<br/>To be Thy love''s samples shining bright.<br/>We''re but clay to be transformed into precious stones.<br/>Waiting in Thy glory to be shown.<br/>We shall never cease singing through eternity,<br/>Grateful songs and heartfelt thanks to Thee.<br/>',NULL,45477,3);
INSERT INTO stanza VALUES('T10821','1','Sa disipulo sa bundok, kami''y hanga,<br/>Pagbagong-anyo Mo''y nakita;<br/>Nagliwanag mukha mo tulad ng araw,<br/>Damit Mo''y simputi ng ilaw.<br/>Ngayon tuwing maisip Iyong pagbabalik,<br/>Puso nami''y sadyang nanabik.<br/>At bago pa malasap ang kamatayan,<br/>Pagpapakita may matingnan.<br/>',NULL,45478,4);
INSERT INTO stanza VALUES('T10821','2','Pagbabago alagad Mo''y nakakita,<br/>Mabuti nga nguni''t may hangga;<br/>''Pagka''t di Mo pa nadanas kamatayan,<br/>Anak ng Diyos, bugtong lamang.<br/>Ngayon sa Iyong pagbalik anong l''walhati,<br/>Laksang banal sa Iyo''y pupuri;<br/>Hari ng mga hari, sadyang totoo,<br/>Mamuhay kasamang bayan Mo.<br/>',NULL,45479,5);
INSERT INTO stanza VALUES('T10821','3','Di lamang Ikaw sa l''walhati''y tumanggap,<br/>Dadalhin din maraming anak;<br/>Dati makasalanan, ngayo''y may b''yaya,<br/>Nang maging tularang pagsinta.<br/>Mga luwad na gagawing batong mahal,<br/>Sa l''walhati''y maitatanghal;<br/>Hanggang sa kawalang hanggan aawit pa<br/>Ng pasalamat at pagsamba.<br/>',NULL,45480,6);
INSERT INTO stanza VALUES('T10822','1','The time is drawing near,<br/>The winepress''s ready!<br/>Every earthly drop shall meet the same fate!<br/>The Lord is the root<br/>Springing from the dry ground,<br/>With the earth why are you so intimate?<br/>',NULL,45481,1);
INSERT INTO stanza VALUES('T10822','chorus','Rescue your very self,<br/>From earth be ye free,<br/>For God and for the Lord,<br/>Firstfruits be ye.<br/>',NULL,45482,2);
INSERT INTO stanza VALUES('T10822','2','The full time is coming,<br/>For the wheat''s harvest!<br/>Earthly pleasure delays the wheat''s riping;<br/>Full of nourishment within,<br/>but dry without;<br/>The Lord is all, the world is fast fading.<br/>',NULL,45483,3);
INSERT INTO stanza VALUES('T10822','chorus','Rescue your very self,<br/>From earth be ye free,<br/>For God and for the Lord,<br/>Firstfruits be ye.<br/>',NULL,45484,4);
INSERT INTO stanza VALUES('T10822','3','Be among the firstfruits,<br/>Oh what a blessing!<br/>The marriage feast, co-kingship I partake!<br/>Better not wait for the world<br/>to deal with you,<br/>I''ll grab today all the dung to forsake.<br/>',NULL,45485,5);
INSERT INTO stanza VALUES('T10822','chorus','Rescue your very self,<br/>From earth be ye free,<br/>For God and for the Lord,<br/>Firstfruits be ye.<br/>',NULL,45486,6);
INSERT INTO stanza VALUES('T10824','1','Wait for Bridegroom — virgins were ten,<br/>But their endings were diff''rent,<br/>Wise and foolish all light their lamps,<br/>But what matter''s oil in them.<br/>Now is the time to prepare oil,<br/>Daily in the spirit toil.<br/>We''ll watch and wait till He comes back,<br/>In His love feast to partake.<br/>',NULL,45487,1);
INSERT INTO stanza VALUES('T10824','2','The three servants all had talents,<br/>But their endings were diff''rent,<br/>The faithful servants made more gain,<br/>Idle servants buried them.<br/>Your one talent quickly bringing,<br/>Here in the church laboring,<br/>Till He comes back in faith serving,<br/>Thus His reward receiving.<br/>',NULL,45488,2);
INSERT INTO stanza VALUES('T10824','3','Our Lord will not come much later,<br/>Let''s watch and wait together,<br/>His commission must not retard,<br/>The faithful shall gain reward.<br/>Before the judgment seat of God,<br/>Where His justice carried out,<br/>Gold and precious stones will remain,<br/>In millennial kingdom reign.<br/>',NULL,45489,3);
INSERT INTO stanza VALUES('T10825','beginning-note','Matthew 25:1-13<br/>',NULL,45490,1);
INSERT INTO stanza VALUES('T10825','1','The kingdom of God is at hand:<br/>Ten virgins with lamps lit arise<br/>To go forth to meet the Bridegroom,<br/>But only five virgins are wise.<br/>The wise have abundance of oil,<br/>The foolish are empty instead;<br/>The wise used their time to buy oil,<br/>The others their chance forfeited.<br/>',NULL,45491,2);
INSERT INTO stanza VALUES('T10825','2','Lord Jesus, Thy message is clear:<br/>You''re coming for those who are wise,<br/>Who buy up their oil today,<br/>Who deal with all hindering ties.<br/>Those virgins whose souls are transformed,<br/>Whose vessels much oil contain,<br/>Who love not their lives unto death—<br/>They in Thy great kingdom shall reign.<br/>',NULL,45492,3);
INSERT INTO stanza VALUES('T10825','3','Our lamps to shine forth must be trimmed<br/>By calling on Thee every day.<br/>In spirit we must exercise<br/>To burn all the oldness away.<br/>But there is a much deeper need:<br/>Reality in us must grow,<br/>Until it makes home in our hearts,<br/>Till oil in our vessels o''erflows.<br/>',NULL,45493,4);
INSERT INTO stanza VALUES('T10825','4','We see how this age is so dark,<br/>We know that blest hour is near.<br/>Our Lord may return anytime—<br/>Lord, strike in us this holy fear,<br/>That we may each moment redeem<br/>By taking Thy Word in by prayer,<br/>By learning each lesson You give,<br/>And thus for that hour prepare.<br/>',NULL,45494,5);
INSERT INTO stanza VALUES('T10825','5','Lord Jesus, how blest to be those<br/>Who bring in Thy kingdom to earth,<br/>Affording Thee rule over all<br/>And showing to all Thy great worth!<br/>How blest to be those at the feast,<br/>Where Thou wilt be one with Thy Bride!<br/>Lord, make us wise virgins for Thee,<br/>Who e''er in Thy presence abide.<br/>',NULL,45495,6);
INSERT INTO stanza VALUES('T10826','beginning-note','Genesis 24<br/>',NULL,45496,1);
INSERT INTO stanza VALUES('T10826','1','''Twas a day in early springtime,<br/>By an ancient wayside well,<br/>Eliezer paused to rest his camel train.<br/>He had found a bride for Isaac<br/>Ere the evening shadows fell,<br/>For his weary journey had not been in vain.<br/>',NULL,45497,2);
INSERT INTO stanza VALUES('T10826','chorus','Oh, get ready! Evening shadows fall.<br/>Don''t you hear the Eliezer call?<br/>There''s going to be a wedding,<br/>And our joy will soon begin,<br/>In the evening when the camel train comes in.<br/>',NULL,45498,3);
INSERT INTO stanza VALUES('T10826','2','So he took the fair Rebekah,<br/>Dressed in jewels rich and rare,<br/>Quickly to her waiting bridegroom far away.<br/>Where Rebekah loved her Isaac,<br/>And he loved Rebekah fair;<br/>Oh, it must have been a happy wedding day.<br/>',NULL,45499,4);
INSERT INTO stanza VALUES('T10826','chorus','Oh, get ready! Evening shadows fall.<br/>Don''t you hear the Eliezer call?<br/>There''s going to be a wedding,<br/>And our joy will soon begin,<br/>In the evening when the camel train comes in.<br/>',NULL,45500,5);
INSERT INTO stanza VALUES('T10826','3','Now the blessed Holy Spirit,<br/>From our Father God above,<br/>Has come down to earth to find a worthy Bride.<br/>For our Isaac over yonder<br/>Has prepared His tents of love,<br/>And He wants His fair Rebekah by His side.<br/>',NULL,45501,6);
INSERT INTO stanza VALUES('T10826','chorus','Oh, get ready! Evening shadows fall.<br/>Don''t you hear the Eliezer call?<br/>There''s going to be a wedding,<br/>And our joy will soon begin,<br/>In the evening when the camel train comes in.<br/>',NULL,45502,7);
INSERT INTO stanza VALUES('T10826','4','We have left our kinfolk gladly;<br/>We have bade the world goodbye.<br/>We''ve been called to be His pure and spotless Bride;<br/>Where we''ll soon behold our Jesus<br/>In that blest eternity—<br/>What a happy, happy wedding that will be!<br/>',NULL,45503,8);
INSERT INTO stanza VALUES('T10826','chorus','Oh, get ready! Evening shadows fall.<br/>Don''t you hear the Eliezer call?<br/>There''s going to be a wedding,<br/>And our joy will soon begin,<br/>In the evening when the camel train comes in.<br/>',NULL,45504,9);
INSERT INTO stanza VALUES('T10827','1','When I''ve run the race before me and have fought to victory,<br/>I''ll be raptured to the glory of the Lord;<br/>When I''ve kept the faith at any cost the Holy City then<br/>I''ll receive as my reward.<br/>',NULL,45505,1);
INSERT INTO stanza VALUES('T10827','chorus','I''ll be raptured into glory, in the Holy City dwell—<br/>New Jerusalem, New Jerusalem;<br/>With the overcomers shouting, how our praises then will swell,<br/>In the New Jerusalem.<br/>',NULL,45506,2);
INSERT INTO stanza VALUES('T10827','2','As a pilgrim here I wander; while afflicted, I rejoice,<br/>For a better land I soon expect to see;<br/>Though all others seek for earthly gain, the Holy City e''er<br/>Will my aspiration be.<br/>',NULL,45507,3);
INSERT INTO stanza VALUES('T10827','chorus','I''ll be raptured into glory, in the Holy City dwell—<br/>New Jerusalem, New Jerusalem;<br/>With the overcomers shouting, how our praises then will swell,<br/>In the New Jerusalem.<br/>',NULL,45508,4);
INSERT INTO stanza VALUES('T10827','3','Though my feet are often wearied on the rough and rugged path,<br/>Just by thinking of that city, I''m restored;<br/>Though my eyes be filled with tears, my heart will evermore be fixed<br/>On that City, my reward.<br/>',NULL,45509,5);
INSERT INTO stanza VALUES('T10827','chorus','I''ll be raptured into glory, in the Holy City dwell—<br/>New Jerusalem, New Jerusalem;<br/>With the overcomers shouting, how our praises then will swell,<br/>In the New Jerusalem.<br/>',NULL,45510,6);
INSERT INTO stanza VALUES('T10827','4','With strong purpose I now wrestle, and I run toward the goal;<br/>I pursue the prize, God''s highest to obtain;<br/>Pressing forward toward the mark, I run forgetting all behind,<br/>Thus the Holy City gain.<br/>',NULL,45511,7);
INSERT INTO stanza VALUES('T10827','chorus','By His love and through His grace I''ll in the Holy City live—<br/>New Jerusalem, New Jerusalem;<br/>All saints leaping, singing, shouting, to the Lord their praises give,<br/>In the New Jerusalem.<br/>',NULL,45512,8);
INSERT INTO stanza VALUES('T10827','1','Ako''y nakipagbaka, natapos ang aking takbo,<br/>Aakyat sa l''walhati, pag-asa ko;<br/>Iningatan ko ang pananampalatayang ito,<br/>Kaharia''y premyo ko.<br/>',NULL,45513,9);
INSERT INTO stanza VALUES('T10827','chorus','Sa l''walhati ng Panginoon ako''y paroroon,<br/>Manahan sa Bagong Herusalem,<br/>Kasamang mga banal pupuri sa Panginoon<br/>Sa Bagong Herusalem.<br/>',NULL,45514,10);
INSERT INTO stanza VALUES('T10827','2','Masayang maglakbay sa mundo kahit may pighati,<br/>Palapit sa lupaing mas mabuti;<br/>Kahit hanap ng iba''y panlupang yaman, sa aki''y<br/>Banal na bayan lagi.<br/>',NULL,45515,11);
INSERT INTO stanza VALUES('T10827','chorus','Sa l''walhati ng Panginoon ako''y paroroon,<br/>Manahan sa Bagong Herusalem,<br/>Kasamang mga banal pupuri sa Panginoon<br/>Sa Bagong Herusalem.<br/>',NULL,45516,12);
INSERT INTO stanza VALUES('T10827','3','Paa at kamay nangalay sa baku-bakong daan,<br/>T''wing ang baya''y maisip, lumalakas;<br/>Kahit may luha ang mata, puso''y para sa bayan,<br/>Pupuntahang pangwakas.<br/>',NULL,45517,13);
INSERT INTO stanza VALUES('T10827','chorus','Sa l''walhati ng Panginoon ako''y paroroon,<br/>Manahan sa Bagong Herusalem,<br/>Kasamang mga banal pupuri sa Panginoon<br/>Sa Bagong Herusalem.<br/>',NULL,45518,14);
INSERT INTO stanza VALUES('T10827','4','Ang takbo''y may layunin, di sumusuntok sa hangin,<br/>Sa pinakamabuti''y magtumulin;<br/>Nilimot nasa lik''ran, hinaharap tutunguhin,<br/>Gantimpala''y kakamtin.<br/>',NULL,45519,15);
INSERT INTO stanza VALUES('T10827','chorus','Dakilang pag-ibig at biyaya ng Panginoon,<br/>Manahan sa Bagong Herusalem;<br/>Umaawit at nangagalak mga banal doon<br/>Sa Bagong Herusalem.<br/>',NULL,45520,16);
INSERT INTO stanza VALUES('T10828','1','Never fear, never fear, never fear,<br/>Your Heav''nly Father watches o''er thee.<br/>Never fear, never fear, never fear,<br/>His hand will clear the way before thee.<br/>There''s a pillar of cloud by day,<br/>And a pillar of fire by night.<br/>Never fear, never fear, never fear,<br/>Thou art precious in His sight.<br/>',NULL,45521,1);
INSERT INTO stanza VALUES('T10828','2','Never fear, never fear, never fear,<br/>Exhibit Christ in all our meetings.<br/>Never fear, never fear, never fear,<br/>Let''s testify the Lord before men.<br/>We are members of His Body,<br/>Fulness of Him thus magnify.<br/>Never fear, never fear, never fear,<br/>We are precious in His sight.<br/>',NULL,45522,2);
INSERT INTO stanza VALUES('T10829','1','If from the right path I''d depart,<br/>The ease of life take part;<br/>I would remember Christ my Lord,<br/>The suff''rings He doth afford.<br/>',NULL,45523,1);
INSERT INTO stanza VALUES('T10829','2','I now the world have given up,<br/>All its relations cut;<br/>Though narrow be the path I tread,<br/>But I''m just here as guest.<br/>',NULL,45524,2);
INSERT INTO stanza VALUES('T10829','3','Let worldly people all detest,<br/>I seek His smiling face;<br/>The crowds delight to outward tastes,<br/>But I desire His praise.<br/>',NULL,45525,3);
INSERT INTO stanza VALUES('T10829','4','My heart''s desire''s not to be great,<br/>Nor fortunes for my fate;<br/>I''d humbly serve the Lord today,<br/>And gain His "nods" that day.<br/>',NULL,45526,4);
INSERT INTO stanza VALUES('T10829','5','I daily gaze now at the light,<br/>From judgement seat so bright;<br/>May all my walk and works withstand<br/>The test of fire by then.<br/>',NULL,45527,5);
INSERT INTO stanza VALUES('T10829','6','Let all the people strive for fames,<br/>More glory, wealth and friends;<br/>Let them obtain profit and gain,<br/>And all the praise of men.<br/>',NULL,45528,6);
INSERT INTO stanza VALUES('T10829','7','But I''d remain though poor and sore,<br/>I dare not ask for more;<br/>My only hope is to pursue<br/>My Lord till death ensue.<br/>',NULL,45529,7);
INSERT INTO stanza VALUES('T10829','8','I know the Lord while on the earth,<br/>Gained only pain and death;<br/>I look forward to nothing else,<br/>''Cept for Him I''ll be less.<br/>',NULL,45530,8);
INSERT INTO stanza VALUES('T10829','9','My glory is in the future,<br/>Now I need to endure;<br/>I will not take a step ahead,<br/>To gain blessings on earth.<br/>',NULL,45531,9);
INSERT INTO stanza VALUES('T10829','10','I''ll gain the crown in future day,<br/>He''ll wipe my tears away;<br/>Today our Lord still tarries on,<br/>I''ll be faithful and walk on.<br/>',NULL,45532,10);
INSERT INTO stanza VALUES('T10829','1','Lumihis lang nang bahagya,<br/>Magnasa''ng ginhawa;<br/>Nguni''t Panginoong Kristo,<br/>Nagdusa nang husto.<br/>',NULL,45533,11);
INSERT INTO stanza VALUES('T10829','2','Binitiwan ko nang mundo,<br/>Kaugnayan nito;<br/>Bagama''t makitid daan,<br/>Manlalakbay lamang.<br/>',NULL,45534,12);
INSERT INTO stanza VALUES('T10829','3','Mainis man tagamundo,<br/>Ngiti Mo''y ''king gusto;<br/>Anyong-labas nais nila,<br/>Ako nama''y Iyong siya.<br/>',NULL,45535,13);
INSERT INTO stanza VALUES('T10829','4','Madakila di ko hangad,<br/>Ni ngayo''y umunlad;<br/>Mababang paglingkuran Ka,<br/>Premyo''y Iyong apruba.<br/>',NULL,45536,14);
INSERT INTO stanza VALUES('T10829','5','Nagmamatyag sa luklukan,<br/>D''hil sa kahatulan;<br/>Nawa ay buhay ko''t gawa,<br/>Sa Kanya''y papasa.<br/>',NULL,45537,15);
INSERT INTO stanza VALUES('T10829','6','Hayaan kong makilala,<br/>Yumaman ang iba;<br/>Tamuhin glorya''t kai-bigan,<br/>Maging kapurihan.<br/>',NULL,45538,16);
INSERT INTO stanza VALUES('T10829','7','Nguni''t kahit maging dukha,<br/>May dusa''t ulila;<br/>Puso''y maging tapat pa rin<br/>Iyong landas tahakin.<br/>',NULL,45539,17);
INSERT INTO stanza VALUES('T10829','8','''Pagka''t Poon nang sa lupa''y<br/>Minsan ding namatay;<br/>Sa Kanya lamang umasa,<br/>Wala nang iba pa.<br/>',NULL,45540,18);
INSERT INTO stanza VALUES('T10829','9','Sa darating aking glorya;<br/>Ngayo''y tiis, dusa;<br/>Di ko unahan Pangino''n<br/>Sa pagpala ngayon.<br/>',NULL,45541,19);
INSERT INTO stanza VALUES('T10829','10','Putong aking tatamuhin,<br/>Luha''y papahirin;<br/>Bagama''t Siya''y maantala,<br/>''Ko''y maging tapat pa.<br/>',NULL,45542,20);
INSERT INTO stanza VALUES('T10830','1','I have to serve the Lord, not belly nor health,<br/>For I am of Him, His precious blood redeemed;<br/>I have to serve the Lord, not fame nor wealth,<br/>May Spirit of life, to His service lead.<br/>If I gained the world and the things therein,<br/>Still to me is grief and vain.<br/>I have to serve the Lord, His pleasure win,<br/>And His fullness I thus gain.<br/>',NULL,45543,1);
INSERT INTO stanza VALUES('T10831','1','We want to serve the Lord.<br/>We want to serve the Lord.<br/>We want to serve our Lord Jesus.<br/>He purchased us by His blood for priesthood.<br/>Not just to be heirs of God;<br/>He purchased us by His blood for priesthood.<br/>Not just to enjoy but serve too.<br/>He purchased us by His blood for priesthood.<br/>We want to serve the Lord.<br/>We want to serve the Lord.<br/>We want to serve our Lord Jesus.<br/>He purchased us by His blood for priesthood,<br/>He purchased us by His blood for priesthood.<br/>',NULL,45544,1);
INSERT INTO stanza VALUES('T10832','1','Bring forth your talent, bring forth your talent!<br/>God gives us the talent, utterly bring forth.<br/>Bring forth your talent, bring forth your talent!<br/>God gives us the talent, utterly bring forth.<br/>',NULL,45545,1);
INSERT INTO stanza VALUES('T10832','2','Use it for the church, it will multiply!<br/>All the talents I have, use it for the church.<br/>Use it for the church, it will multiply!<br/>All the talents I have, use it for the church.<br/>',NULL,45546,2);
INSERT INTO stanza VALUES('T10832','3','Bring forth your talent, trade it faithfully!<br/>You will reap more talents, His reward to gain.<br/>Bring forth your talent, trade it faithfully!<br/>You will reap more talents, His reward to gain.<br/>',NULL,45547,3);
INSERT INTO stanza VALUES('T10832','1','Iyong talento dapat gamitin!<br/>Binigyan Niya tayo, dapat gamitin.<br/>Iyong talento dapat gamitin!<br/>Binigyan Niya tayo, dapat gamitin.<br/>',NULL,45548,4);
INSERT INTO stanza VALUES('T10832','2','Saan ilagak nang makinabang?<br/>Dapat sa ekklesia nang makinabang!<br/>Saan ilagak nang makinabang?<br/>Dapat sa ekklesia nang makinabang!<br/>',NULL,45549,5);
INSERT INTO stanza VALUES('T10832','3','Iyong talento, dapat gamitin!<br/>Tapat mangalakal, premyo''y tamuhin.<br/>Iyong talento, dapat gamitin!<br/>Tapat mangalakal, premyo''y tamuhin.<br/>',NULL,45550,6);
INSERT INTO stanza VALUES('T10833','1','A call for loyal soldiers — comes to one and all;<br/>Soldiers for the conflicts, will you heed the call,<br/>Will you answer quickly, with a ready cheer,<br/>Will you be enlisted as a volunteer?<br/>',NULL,45551,1);
INSERT INTO stanza VALUES('T10833','chorus','A volunteer for Jesus, a soldier true!<br/>Others have enlisted, why not you?<br/>Jesus is the Captain, we will never fear;<br/>Will you be enlisted as a volunteer?<br/>',NULL,45552,2);
INSERT INTO stanza VALUES('T10833','2','Yes, Jesus calls for soldiers, who are filled with power,<br/>Soldiers who will serve Him, every day and hour;<br/>He will not forsake you, He is ever near;<br/>Will you be enlisted as a volunteer?<br/>',NULL,45553,3);
INSERT INTO stanza VALUES('T10833','chorus','A volunteer for Jesus, a soldier true!<br/>Others have enlisted, why not you?<br/>Jesus is the Captain, we will never fear;<br/>Will you be enlisted as a volunteer?<br/>',NULL,45554,4);
INSERT INTO stanza VALUES('T10834','1','Let''s serve our Lord together,<br/>Together, together.<br/>Let''s serve our Lord together,<br/>How glorious we''ll be.<br/>To serve Him is our ministry—<br/>Our precious inborn ministry.<br/>Let''s serve our Lord, together,<br/>How glorious we''ll be.<br/>',NULL,45555,1);
INSERT INTO stanza VALUES('T10834','2','Magkasamang maglingkod<br/>Sa ating Pangino''n,<br/>Kay l''walhating maglingkod<br/>sa Panginoon;<br/>Ito''ng ating ministeryo—<br/>Mahalaga''t katutubo,<br/>Kay l''walhating maglingkod<br/>sa Panginoon.<br/>',NULL,45556,2);
INSERT INTO stanza VALUES('T10835','1','We''re saved, saved to tell others of the Man of Galilee.<br/>Saved, saved to live daily for the Christ of Calvary.<br/>Saved, saved to invite you to His salvation free.<br/>We''re saved, saved by His blood for all eternity.<br/>',NULL,45557,1);
INSERT INTO stanza VALUES('T10836','1','When Jesus comes to reward His servants,<br/>Whether it be noon or night;<br/>Faithful to Him will He find us watching,<br/>With our lamps all trimmed and bright?<br/>',NULL,45558,1);
INSERT INTO stanza VALUES('T10836','chorus','Oh, can we say we are ready brothers?<br/>Ready for the soul''s bright home?<br/>Say, will He find you and me still watching,<br/>Waiting, waiting when the Lord shall come?<br/>',NULL,45559,2);
INSERT INTO stanza VALUES('T10836','2','If at the dawn of the early morning,<br/>He shall call us one by one;<br/>When to the Lord we restore our talents,<br/>Will He answer thee? — "Well done!"<br/>',NULL,45560,3);
INSERT INTO stanza VALUES('T10836','chorus','Oh, can we say we are ready brothers?<br/>Ready for the soul''s bright home?<br/>Say, will He find you and me still watching,<br/>Waiting, waiting when the Lord shall come?<br/>',NULL,45561,4);
INSERT INTO stanza VALUES('T10836','3','Have we been true to the trust He left us?<br/>Do we seek to do our best?<br/>If in our hearts nothing there condemns us,<br/>We shall have a glorious rest.<br/>',NULL,45562,5);
INSERT INTO stanza VALUES('T10836','chorus','Oh, can we say we are ready brothers?<br/>Ready for the soul''s bright home?<br/>Say, will He find you and me still watching,<br/>Waiting, waiting when the Lord shall come?<br/>',NULL,45563,6);
INSERT INTO stanza VALUES('T10836','4','Blessed are those whom the Lord finds watching,<br/>In His glory they shall share;<br/>If He shall come at the dawn or midnight,<br/>Will He find us watching there?<br/>',NULL,45564,7);
INSERT INTO stanza VALUES('T10836','chorus','Oh, can we say we are ready brothers?<br/>Ready for the soul''s bright home?<br/>Say, will He find you and me still watching,<br/>Waiting, waiting when the Lord shall come?<br/>',NULL,45565,8);
INSERT INTO stanza VALUES('T10836','1','Hesus darating may gantimpala,<br/>Sa yaong mga handa;<br/>Tayo kaya''y Kanyang masumpungan,<br/>May langis sa ilawan?<br/>',NULL,45566,9);
INSERT INTO stanza VALUES('T10836','chorus','Masasabi bagang tayo''y laan,<br/>Pagtanggap ng kaharian;<br/>Ako''t ikaw masumpungan kaya<br/>Sa pagdating Niya''y<br/>handang-handa?<br/>',NULL,45567,10);
INSERT INTO stanza VALUES('T10836','2','Kung sa pagbubukang-liwayway nga,<br/>Tawaging isa-isa,<br/>Sa pagtutuos natin sa Kanya,<br/>Matutuwa kaya Siya?<br/>',NULL,45568,11);
INSERT INTO stanza VALUES('T10836','chorus','Masasabi bagang tayo''y laan,<br/>Pagtanggap ng kaharian;<br/>Ako''t ikaw masumpungan kaya<br/>Sa pagdating Niya''y<br/>handang-handa?<br/>',NULL,45569,12);
INSERT INTO stanza VALUES('T10836','3','Maging tapat — ating sinikap ba,<br/>Sa Kanyang pagtiwala?<br/>Kung tayo sa Kanya''y walang kulang,<br/>Ganti''y kapahingahan.<br/>',NULL,45570,13);
INSERT INTO stanza VALUES('T10836','chorus','Masasabi bagang tayo''y laan,<br/>Pagtanggap ng kaharian;<br/>Ako''t ikaw masumpungan kaya<br/>Sa pagdating Niya''y<br/>handang-handa?<br/>',NULL,45571,14);
INSERT INTO stanza VALUES('T10836','4','Mapalad ang Kanyang masumpungan,<br/>Sa pagbabantay laan;<br/>Sa umaga o hatinggabi man,<br/>Handa kayang daratnan?<br/>',NULL,45572,15);
INSERT INTO stanza VALUES('T10836','chorus','Masasabi bagang tayo''y laan,<br/>Pagtanggap ng kaharian;<br/>Ako''t ikaw masumpungan kaya<br/>Sa pagdating Niya''y<br/>handang-handa?<br/>',NULL,45573,16);
INSERT INTO stanza VALUES('T10837','1','Do you ever search your heart as you watch the day depart?<br/>Is there something way down deep you try to hide?<br/>If this day should be the end and eternity begin,<br/>When the book is opened wide, would the Lord be satisfied?<br/>',NULL,45574,1);
INSERT INTO stanza VALUES('T10837','2','Is He satisfied, is He satisfied?<br/>Is He satisfied with me?<br/>Have I done my best, have I stood the test?<br/>Is He satisfied with me?<br/>',NULL,45575,2);
INSERT INTO stanza VALUES('T10837','3','When my Lord shall come again, when He walks and talks with men,<br/>What if every friend He has were just like me?<br/>Would He feel a welcome here or would He be broken-hearted?<br/>Am I all that I should be? Is He satisfied with me?<br/>',NULL,45576,3);
INSERT INTO stanza VALUES('T10837','4','Is He satisfied, is He satisfied?<br/>Is He satisfied with me?<br/>Have I done my best, have I stood the test?<br/>Is He satisfied with me?<br/>',NULL,45577,4);
INSERT INTO stanza VALUES('T10838','1','You who have tread the right way,<br/>Whose hands and feet grow numb,<br/>O look away to Jesus,<br/>And then despair won''t come.<br/>His face with ardor shining,<br/>All darkness casts away,<br/>His countenance e''er behold,<br/>You''ll be as bright as day.<br/>',NULL,45578,1);
INSERT INTO stanza VALUES('T10838','2','O look away to Jesus,<br/>And you won''t be aware<br/>Of persecution, hardship,<br/>And trials that you bear;<br/>No tears of pain and sorrow<br/>Can ever dim your eyes,<br/>No fear, alarm or danger<br/>Your heart can agonize.<br/>',NULL,45579,2);
INSERT INTO stanza VALUES('T10838','3','O look away to Jesus,<br/>Your spirit will be blest,<br/>The world has tribulation,<br/>In Him you will find rest.<br/>On the bitter sea of life,<br/>Beaten by storm and gale,<br/>If you look upon His face,<br/>Your heart none can assail.<br/>',NULL,45580,3);
INSERT INTO stanza VALUES('T10838','4','O look away to Jesus,<br/>And you won''t go astray,<br/>O lift your eyes unto Him,<br/>And He will guide your way,<br/>When He is leading you on,<br/>Though clouds may block your sight,<br/>Just turn your face unto Him,<br/>And you will be all right.<br/>',NULL,45581,4);
INSERT INTO stanza VALUES('T10838','5','O look away to Jesus,<br/>Until the rapture comes,<br/>And full revealed before you<br/>His glorious countenance.<br/>The face that you behold now<br/>Gives you strength on your way,<br/>But on that day it will be<br/>Your joy and praise alway.<br/>',NULL,45582,5);
INSERT INTO stanza VALUES('T10838','1','Nangangalay sa daan,<br/>Kamay at paa mo,<br/>Masdan lamang si Hesus,<br/>Di ka mabibigo;<br/>Nag-alab ang mukha Niya,<br/>Karimla''y pinawi,<br/>At mag-aaninag ka<br/>Ng Kanyang l''walhati.<br/>',NULL,45583,6);
INSERT INTO stanza VALUES('T10838','2','Masdan lamang si Hesus,<br/>At di mo makita<br/>Ang pag-uusig, hapis,<br/>Sakit at dalita;<br/>Kahit luhang masaklap<br/>Di makabubulag,<br/>Walang pangamba''t hirap,<br/>Puso ko''y mabitag.<br/>',NULL,45584,7);
INSERT INTO stanza VALUES('T10838','3','Masdan lamang si Hesus,<br/>Pagpapalain ka;<br/>Mundo may pighati man,<br/>Payapa sa Kanya.<br/>Kahit may bagyo''t alon<br/>Sa dagat ng buhay,<br/>Masdan ang Panginoon,<br/>Puso''y matiwasay.<br/>',NULL,45585,8);
INSERT INTO stanza VALUES('T10838','4','Masdan lamang si Hesus,<br/>Di ka malilito;<br/>Kung lagi mo Siyang tingnan,<br/>Landas mo''y mawasto.<br/>Pag Siya ang patnubay mo,<br/>Mag-ulap man lagi,<br/>Kung Siya''y babalingan mo,<br/>Di ka magkamali.<br/>',NULL,45586,9);
INSERT INTO stanza VALUES('T10838','5','Masdan lamang si Hesus,<br/>Hanggang sa pag-akyat;<br/>Ang mal''walhating mukha<br/>Sa iyo''y mahahayag.<br/>Ang nakita mo ngayon,<br/>Nagpalakas sa iyo,<br/>At sa araw na yaon,<br/>Ay kagalakan mo.<br/>',NULL,45587,10);
INSERT INTO stanza VALUES('T10839','1','Bugle calls are ringing out,<br/>"Forward" is the battle shout,<br/>See where floats the conqu''ring sign,<br/>Onward the war divine!<br/>',NULL,45588,1);
INSERT INTO stanza VALUES('T10839','chorus','And when the battle''s over<br/>We shall wear a crown,<br/>We shall wear a crown,<br/>We shall wear a crown!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>Wear a crown, wear a crown,<br/>Away over Jordan!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>',NULL,45589,2);
INSERT INTO stanza VALUES('T10839','2','Sound the charge against the foe,<br/>Lay the hosts of error low;<br/>In His name, victorious King,<br/>Let the song of triumph ring!<br/>',NULL,45590,3);
INSERT INTO stanza VALUES('T10839','chorus','And when the battle''s over<br/>We shall wear a crown,<br/>We shall wear a crown,<br/>We shall wear a crown!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>Wear a crown, wear a crown,<br/>Away over Jordan!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>',NULL,45591,4);
INSERT INTO stanza VALUES('T10839','3','Fight the fight of faith and love,<br/>Looking unto Him above;<br/>Loyal soldiers, do and dare,<br/>Your Commander''s joy to share.<br/>',NULL,45592,5);
INSERT INTO stanza VALUES('T10839','chorus','And when the battle''s over<br/>We shall wear a crown,<br/>We shall wear a crown,<br/>We shall wear a crown!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>Wear a crown, wear a crown,<br/>Away over Jordan!<br/>And when the battle''s over<br/>We shall wear a crown<br/>In the New Jerusalem!<br/>',NULL,45593,6);
INSERT INTO stanza VALUES('T10840','1','When mine eyes behold the King in His glory,<br/>So resplendent with the light of His love;<br/>How my heart will leap for joy, and with singing,<br/>I shall join the ransomed chorus above.<br/>',NULL,45594,1);
INSERT INTO stanza VALUES('T10840','chorus','When mine eyes behold the King in His glory,<br/>Then new beauty in my Lord I shall see;<br/>I shall reign forevermore with my Savior,<br/>With the Son of God Who died for me.<br/>',NULL,45595,2);
INSERT INTO stanza VALUES('T10840','2','O it doth not yet appear what we shall be,<br/>But we know we shall be like Him at last;<br/>In His image we shall someday awaken,<br/>When the cares and trials of earth are all past.<br/>',NULL,45596,3);
INSERT INTO stanza VALUES('T10840','chorus','When mine eyes behold the King in His glory,<br/>Then new beauty in my Lord I shall see;<br/>I shall reign forevermore with my Savior,<br/>With the Son of God Who died for me.<br/>',NULL,45597,4);
INSERT INTO stanza VALUES('T10840','3','That great day shall come, O brothers, believe it,<br/>We shall see Him as He is, over there;<br/>Blessed hope that fills our souls with all comfort,<br/>Blessed vision that fulfills every prayer.<br/>',NULL,45598,5);
INSERT INTO stanza VALUES('T10840','chorus','When mine eyes behold the King in His glory,<br/>Then new beauty in my Lord I shall see;<br/>I shall reign forevermore with my Savior,<br/>With the Son of God Who died for me.<br/>',NULL,45599,6);
INSERT INTO stanza VALUES('T10841','1','Jesus Lord, I''m waiting here,<br/>To be raptured by Thee;<br/>''Part from Thy coming back, Lord,<br/>There''s naught that''s sweeter be.<br/>I now hope for Thy return,<br/>For I know Thou art nigh;<br/>I can sense Thy presence Lord,<br/>Around this heart of mine.<br/>',NULL,45600,1);
INSERT INTO stanza VALUES('T10841','2','In the deepest part of me,<br/>Thy voice I''ve heard it plain;<br/>I thank Thee for telling me,<br/>All concerning Thy plan.<br/>Thou wilt come back very soon,<br/>Thy appearing real fast!<br/>Grace wilt no longer be giv''n,<br/>Foes subdued to the last!<br/>',NULL,45601,2);
INSERT INTO stanza VALUES('T10841','3','Lord, cut all "clutches" off me,<br/>Completely free I''ll be;<br/>Free from all things that bind me,<br/>Closely following Thee.<br/>I will drop the "good" things,<br/>Let my heart be relieved;<br/>Lest on Thy coming back, Lord,<br/>I cannot freely leave.<br/>',NULL,45602,3);
INSERT INTO stanza VALUES('T10841','4','Constant watchful and alert,<br/>My heart''s desire be this;<br/>Always to the spirit turn,<br/>Then rapture I''ll not miss.<br/>Lest I doze and fall asleep,<br/>I''m not aware a bit!<br/>Thou wilt leave me here on earth,<br/>Thinking that I''m not fit!<br/>',NULL,45603,4);
INSERT INTO stanza VALUES('T10841','5','Oh my heart this is truly<br/>A serious advice heed;<br/>All the things that I e''er love,<br/>I''ll leave behind indeed.<br/>Love the Lord wholeheartedly,<br/>Desiring Him to see;<br/>I can leave all things behind,<br/>Any time He calls me.<br/>',NULL,45604,5);
INSERT INTO stanza VALUES('T10841','6','Though the battle''s raging on,<br/>The strength of Satan fierce!<br/>In a short while I''ll ascend,<br/>There is nothing to fear!<br/>Though each day darkness increase,<br/>Full redemption we''ll see,<br/>Since our Lord will come back soon,<br/>We now wait patiently.<br/>',NULL,45605,6);
INSERT INTO stanza VALUES('T10841','7','May Thou Lord be my one love,<br/>My one thought be of Thee;<br/>Surpassing all earthly bribe,<br/>My heart with Him one be.<br/>Loosed from all the worldly ties,<br/>Come my Lord, hear my plea!<br/>My heart yearns in heaven be,<br/>My Lord, my love to see!<br/>',NULL,45606,7);
INSERT INTO stanza VALUES('T10842','1','In that bright and golden moment when the Christ we love shall come,<br/>And the radiance of His glory we shall see;<br/>When the Bride shall meet the Bridegroom and His loving wife become,<br/>What a meeting, what a meeting that will be!<br/>',NULL,45607,1);
INSERT INTO stanza VALUES('T10842','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover, with our Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,45608,2);
INSERT INTO stanza VALUES('T10842','2','When to all who love His coming He shall speak the word, "Arise!"<br/>Oh, how blessed for that summons to be free!<br/>With what rapture we shall greet Him as we join Him in the skies—<br/>What a meeting, what a meeting that will be!<br/>',NULL,45609,3);
INSERT INTO stanza VALUES('T10842','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover, with our Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,45610,4);
INSERT INTO stanza VALUES('T10842','3','Now in all the local churches we are meeting day by day<br/>And expecting any moment Christ to see,<br/>But when Jesus comes the meeting starts that ne''er will pass away—<br/>What a meeting, what a meeting that will be!<br/>',NULL,45611,5);
INSERT INTO stanza VALUES('T10842','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover, with our Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,45612,6);
INSERT INTO stanza VALUES('T10842','4','Even now while we are meeting, Lord, we hope to see Thy face<br/>And forever without ceasing be with Thee.<br/>Then we''ll just go right on meeting in another meeting place—<br/>What a meeting, what a meeting this will be!<br/>',NULL,45613,7);
INSERT INTO stanza VALUES('T10842','chorus','What a meeting, what a meeting,<br/>What a meeting with our Lover, with our Bridegroom in the air!<br/>What a meeting, what a meeting,<br/>What a meeting any moment we will share!<br/>',NULL,45614,8);
INSERT INTO stanza VALUES('T10902','1','O, vanity, vanity, all things are vanity;<br/>Jesus Christ, Jesus Christ is our reality.<br/>Calling upon Him we''ve left Christianity,<br/>Building His Church in each locality.<br/>',NULL,45615,1);
INSERT INTO stanza VALUES('T10902','2','When we call O Lord Jesus, it really releases,<br/>We''re filled and we''re satisfied as Christ increases.<br/>The more that we call upon Jesus our Lord,<br/>The more we''ll enjoy Him as life evermore.<br/>',NULL,45616,2);
INSERT INTO stanza VALUES('T10902','3','If you want to be freed from your dumbness and misery,<br/>Call on the Lord and He''ll free you spontaneously;<br/>Don''t wait forever, just open up to the flow,<br/>Then you will live and Christ in you will grow.<br/>',NULL,45617,3);
INSERT INTO stanza VALUES('T10902','1','Kahungkagan, O hungkag, lahat pawang hungkag!<br/>O Hesus! O Kristo! Siya lamang di hungkag;<br/>Iwanan ang Kristiyanidad, tawagin Siya,<br/>Itayo ang lokal na ekklesia.<br/>',NULL,45618,4);
INSERT INTO stanza VALUES('T10902','2','Nang tawagin "O Hesus!" ''spiritu''y lumaya,<br/>Napuno, nabusog, umapaw, natuwa!<br/>Lalong tatawagin: Panginoong Hesus,<br/>Buhay at pagtamasa ay lubos!<br/>',NULL,45619,5);
INSERT INTO stanza VALUES('T10902','3','Laya sa pagkapipi, ''di masabing dusa,<br/>Tawagin "O Hesus!" gapos mo''y mawala;<br/>Huwag mag-atubili sumama sa agos,<br/>Pangino''n sa iyo lalagong lubos.<br/>',NULL,45620,6);
INSERT INTO stanza VALUES('T10903','1','Do you know what you were made for?<br/>Do you ever wonder why?<br/>What''s the purpose of your being?<br/>What''s the reason you''re alive?<br/>',NULL,45621,1);
INSERT INTO stanza VALUES('T10903','chorus','Do you know God wants to be your life,<br/>He wants to be your life,<br/>He wants to be your life,<br/>You were made with something deep within,<br/>Only to contain just Him.<br/>',NULL,45622,2);
INSERT INTO stanza VALUES('T10903','2','Deep within you have a spirit,<br/>Even deeper than your heart;<br/>Many other things can fill you,<br/>But only Jesus can fill this part.<br/>',NULL,45623,3);
INSERT INTO stanza VALUES('T10903','chorus','You have been so empty all these years,<br/>In spite of all you''ve tried,<br/>You''re still not satisfied.<br/>Don''t you feel a longing deep within,<br/>To open up and take Christ in?<br/>',NULL,45624,4);
INSERT INTO stanza VALUES('T10903','3','Doesn''t matter how you see things,<br/>For in God''s eyes, "all have sinned;"<br/>Jesus shed His blood to cleanse you,<br/>For the purpose of getting in.<br/>',NULL,45625,5);
INSERT INTO stanza VALUES('T10903','chorus','He''s done everything there is to do,<br/>And He''s the Spirit now<br/>So He can get in you.<br/>Makes no difference what your past has been;<br/>The living Christ will still come in.<br/>',NULL,45626,6);
INSERT INTO stanza VALUES('T10903','4','Just as you are in your body,<br/>Perfectly contained therein,<br/>God wants you for His container,<br/>All you need to do is let Him in.<br/>',NULL,45627,7);
INSERT INTO stanza VALUES('T10903','chorus','Would you open up from deep within?<br/>To let the Lord come in<br/>And fill you to the brim.<br/>Why not open up from deep within<br/>And call upon the name of Him.<br/>',NULL,45628,8);
INSERT INTO stanza VALUES('T10903','1','Bakit ka kaya nilikha?<br/>Ikaw ba ay namamangha?<br/>Ano ba ang iyong layunin?<br/>Bakit ka nabubuhay rin?<br/>',NULL,45629,9);
INSERT INTO stanza VALUES('T10903','chorus','Nais ng Diyos maging iyong buhay,<br/>Siya''y maging iyong buhay,<br/>Siya''y maging iyong buhay;<br/>Nilikha kang isang sisidlan,<br/>Nang Siya''y maging iyong laman.<br/>',NULL,45630,10);
INSERT INTO stanza VALUES('T10903','2','Taglay mo ang espiritu,<br/>Mas malalim sa puso mo;<br/>Punuin ka man ng mundo,<br/>Hungkag din ang espiritu.<br/>',NULL,45631,11);
INSERT INTO stanza VALUES('T10903','chorus','Matagal kang may kahungkagan,<br/>Lahat mong natikman,<br/>Di ka nasiyahan,<br/>Puso mo nawa''y buksang lubos,<br/>Papasukin si Hesus.<br/>',NULL,45632,12);
INSERT INTO stanza VALUES('T10903','3','Anuman ang iyong isipin,<br/>Sa Diyos lahat ay salarin,<br/>Daloy ng dugo ni Hesus,<br/>Kasalanan mo''y tinubos.<br/>',NULL,45633,13);
INSERT INTO stanza VALUES('T10903','chorus','Hesus ang lahat ay ginanap,<br/>Nang Siya''y iyong matanggap,<br/>Huwag kang magsumikap,<br/>Espiritu''y pupunuin ka<br/>Ng dibinong buhay Niya.<br/>',NULL,45634,14);
INSERT INTO stanza VALUES('T10903','4','Katawan mo ay sisidlan<br/>Ng iyong buong katauhan,<br/>Gayundin iyong espiritu,<br/>Nais ng Diyos masidlan ''to.<br/>',NULL,45635,15);
INSERT INTO stanza VALUES('T10903','chorus','Mula sa kaibuturan mo,<br/>Buksan ang iyong puso,<br/>Siya''y papasukin mo,<br/>Mula sa iyong kailaliman,<br/>Tawagin Kanyang ngalan.<br/>',NULL,45636,16);
INSERT INTO stanza VALUES('T10904','1','Do you know what you were saved for?<br/>Do you ever wonder why?<br/>What is God''s intent and purpose?<br/>Why has Christ become your life?<br/>Up till now we Christians only knew<br/>Christ wants to get in you,<br/>And that, indeed, is true;<br/>Yet the vision goes much deeper still,<br/>He has a plan He must fulfill.<br/>',NULL,45637,1);
INSERT INTO stanza VALUES('T10904','2','Eden''s river has a purpose,<br/>Bringing life where''er it goes;<br/>God''s salvation, like a river,<br/>Goes through stages as it flows.<br/>First we''re saved from Satan''s tyranny,<br/>And later, we will see,<br/>From Christianity.<br/>God is flowing in recovery,<br/>Just open up to Him and see.<br/>',NULL,45638,2);
INSERT INTO stanza VALUES('T10904','3','Not just individual Christians,<br/>Isolated, wand''ring free,<br/>But as stones built up together,<br/>Christ expressing corporately.<br/>We were saved just Jesus to contain,<br/>But there''s reason too,<br/>That Christ came into you;<br/>He came in, His purpose to secure,<br/>To gain for Him a Bride so pure.<br/>',NULL,45639,3);
INSERT INTO stanza VALUES('T10904','4','Not the stones, though very precious,<br/>Elevated "spiritually,"<br/>But the stones built up together<br/>In the Spirit, practically.<br/>You will ne''er be fully satisfied,<br/>Or be content inside,<br/>Till Jesus has His Bride.<br/>Did you know the Lord is seeking you<br/>To build into His building true?<br/>',NULL,45640,4);
INSERT INTO stanza VALUES('T10906','1','We have searched all o''er the mountain and the ridges,<br/>Hoping to know the truth of this life,<br/>Time and again, however, we met frustration,<br/>Knowing this is all the world could give.<br/>Then one day, Thou comest to meet us on the way,<br/>Drawing us with Thy full affection,<br/>We were drawn to Thee, Lord, in Thy sweetness to stay,<br/>Now we know the real meaning of life.<br/>',NULL,45641,1);
INSERT INTO stanza VALUES('T10906','2','Thy glorious face in resurrection we behold,<br/>Knowing the crown of thorns Thou once wore;<br/>Now I''m fully trusting in the hand of our Lord,<br/>The hand with the mark of the nails bore.<br/>Thy own lovely self we''re enjoying here today,<br/>Thou art more real day after day.<br/>Like the flowing water returning to the sea,<br/>Unknowingly we are lost in Thee.<br/>',NULL,45642,2);
INSERT INTO stanza VALUES('T10906','1','Kabundukan at libis sinaliksik na,<br/>Mabatid ang buhay siyang nasa;<br/>Nguni''t paulit-ulit lamang nabigo,<br/>Wala nang mabigay ang mundo.<br/>Hanggang sa Ika''y dumating sa ''king landas,<br/>Puso Mo sa aki''y nagbukas;<br/>Napasa Iyong tamis at naakit ako,<br/>Halaga ng buhay natanto.<br/>',NULL,45643,3);
INSERT INTO stanza VALUES('T10906','2','L''walhati ng pagkabuhay namasdan ko,<br/>Putong ng tinik dinanas Mo;<br/>Kamay Mong kaibig-ibig siyang alalay,<br/>Bakas ng pagkapako''y taglay.<br/>Kaibig-ibig Mong Sarili''y tamasa,<br/>Higit Kang tunay nadarama.<br/>Tulad ng tubig bumabalik sa dagat,<br/>Sa Iyo, kami''y naglahong lahat.<br/>',NULL,45644,4);
INSERT INTO stanza VALUES('T10907','1','Oh, friend, where are you now?<br/>Daily toiling, on the run.<br/>Yet you are leading an empty, empty life!<br/>You''ve searched the whole world over,<br/>Yet you are not satisfied,<br/>And you feel there''s always something lacking inside!<br/>',NULL,45645,1);
INSERT INTO stanza VALUES('T10907','chorus','It''s Jesus you need! He''s Lord of all!<br/>You need to enjoy all His riches!<br/>Though your heart be larger than the world,<br/>Only He can really, really satisfy you!<br/>',NULL,45646,2);
INSERT INTO stanza VALUES('T10907','2','Oh! You''re self-satisfied, having everything you want,<br/>Yet you''re still not feeling, feeling satisfied.<br/>You''re successful in your work, heading for a bright career,<br/>But yet there''s lack deeper, deeper inside you.<br/>',NULL,45647,3);
INSERT INTO stanza VALUES('T10907','chorus','It''s Jesus you need! He''s Lord of all!<br/>You need to enjoy all His riches!<br/>Though your heart be larger than the world,<br/>Only He can really, really satisfy you!<br/>',NULL,45648,4);
INSERT INTO stanza VALUES('T10907','1','Nasaan ka na ba? Araw-araw nagpagal,<br/>Nguni''t hungkag, hungkag, hungkag iyong buhay;<br/>Nagsumikap sa lahat subali''t di pa sapat,<br/>Dama mo ngang may kulang, kulang na bagay.<br/>',NULL,45649,5);
INSERT INTO stanza VALUES('T10907','chorus','Pangino''ng Hesus, iyong kai-langan!<br/>Tamasahin mo Kanyang yaman!<br/>Bagama''t malaki sa mundo.<br/>Kayang-kaya Niyang bigyang-siya iyong puso.<br/>',NULL,45650,6);
INSERT INTO stanza VALUES('T10907','2','May siya ka nga sa sarili mo, mundo''y iyo,<br/>Nguni''t nasaan ang kasiyahan mo?<br/>Tagumpay ka sa gawa, may kinabukasan ka,<br/>Nguni''t sa iyong kai-buturan: kulang pa!<br/>',NULL,45651,7);
INSERT INTO stanza VALUES('T10907','chorus','Pangino''ng Hesus, iyong kai-langan!<br/>Tamasahin mo Kanyang yaman!<br/>Bagama''t malaki sa mundo.<br/>Kayang-kaya Niyang bigyang-siya iyong puso.<br/>',NULL,45652,8);
INSERT INTO stanza VALUES('T10908','1','(Brothers) Once I was an empty man,<br/>My destiny in my own hand,<br/>Not knowing what my hand is reaping.<br/>Sometimes I smiled but inside weeping,<br/>And this emptiness inside still remained.<br/>No peace I gained,<br/>Just emptiness inside me.<br/>',NULL,45653,1);
INSERT INTO stanza VALUES('T10908','2','(Sisters) Even though I knew no way<br/>To help myself or even pray,<br/>Something deep within was seeking,<br/>To know if life on earth had meaning;<br/>And then I found the answer in a name.<br/>I''m not the same,<br/>Since I called on Jesus.<br/>',NULL,45654,2);
INSERT INTO stanza VALUES('T10908','3','(Brothers and sisters) This Jesus lives inside of me—<br/>My Lord, my life, my all to be.<br/>This life and peace inside increases<br/>By calling on the name of Jesus.<br/>There''s nothing for my soul on earth to seek.<br/>I have no need;<br/>I''m satisfied in Jesus.<br/>',NULL,45655,3);
INSERT INTO stanza VALUES('T10909','1','If you are empty<br/>Wondering why you exist,<br/>We have the answer now — Jesus!<br/>If deep within<br/>You have a hunger and thirst,<br/>You can be satisfied — Jesus.<br/>You no longer need to be in bondage and confusion,<br/>No more need you be a slave to sin and self-delusion.<br/>Jesus is near, available, ready now,<br/>He''s waiting for you to open and will show you how. Just call—<br/>Jesus — darkness is changed to light.<br/>Jesus — His peace is out of sight.<br/>Jesus — you''re gonna be all right now.<br/>',NULL,45656,1);
INSERT INTO stanza VALUES('T10910','1','Life begins when Jesus comes in,<br/>Bringing joy and gladness within;<br/>Gone sin and sorrow,<br/>And bright each tomorrow,<br/>For life begins when Jesus comes in.<br/>',NULL,45657,1);
INSERT INTO stanza VALUES('T10910','2','Buhay ko ay nagsimula<br/>Nang si Kristo''y maging akin;<br/>Lungkot at sala<br/>Napawi sa akin,<br/>Dahil Kristo''y naging buhay ko.<br/>',NULL,45658,2);
INSERT INTO stanza VALUES('T10911','1','My life was full of grief and pain,<br/>And all my strifes were all in vain;<br/>Since Lord Jesus came into my heart,<br/>To be my Lord, my joy was full.<br/>O how wonderful, is my Lord Jesus<br/>O my dear friends, Why not receive Him?<br/>Call upon His name, He will save you now.<br/>',NULL,45659,1);
INSERT INTO stanza VALUES('T10911','2','Ang buhay ko''y napakasaklap;<br/>Pawang sawi aking pagsikap.<br/>Halina sa puso ko, Hesus,<br/>Maging aking Poon at tustos.<br/>Anong hiwaga ng aking Hesus!<br/>Kaibigan, tanggapin mo Siya,<br/>Tawagin ngalan Niya, ililigtas ka.<br/>',NULL,45660,2);
INSERT INTO stanza VALUES('T10912','1','God''s love is on each sinner gone astray.<br/>He is longing for our return each day.<br/>For His Son Jesus Christ, has ransom paid.<br/>God has a big, big heart.<br/>God has a big, big heart.<br/>God has a big, big heart.<br/>Though our sins be as high as mountain.<br/>Through Jesus'' blood they''re all forgiven.<br/>God has a big, big heart.<br/>',NULL,45661,1);
INSERT INTO stanza VALUES('T10913','1','God''s love is wonderful,<br/>God''s love is wonderful,<br/>Wonderful that He should give<br/>His Son to die for me.<br/>God''s love is wonderful.<br/>',NULL,45662,1);
INSERT INTO stanza VALUES('T10914','1','Neither''s there salvation in any other,<br/>For there''s none other name under heaven given, given among men,<br/>Whereby we must be saved, whereby we must be saved,<br/>Whereby we must be saved.<br/>',NULL,45663,1);
INSERT INTO stanza VALUES('T10915','1','Having things — having what there is to have of things:<br/>Clothes and cars and houses, food and flings;<br/>They pass away, they''re fading things.<br/>',NULL,45664,1);
INSERT INTO stanza VALUES('T10915','2','Doing things — for a day or two and then you''re through<br/>Rack your brain for something else to do.<br/>It''s all been done — there''s nothing new.<br/>',NULL,45665,2);
INSERT INTO stanza VALUES('T10915','chorus','Like a merry-go-round, when you''re through it''s not so real.<br/>When the ride is over, you find you''re empty still, so you seek. . . .<br/>',NULL,45666,3);
INSERT INTO stanza VALUES('T10915','3','Something real — something that will last and satisfy,<br/>Something solid that you can''t deny,<br/>The answer to your hungry cry.<br/>',NULL,45667,4);
INSERT INTO stanza VALUES('T10915','chorus','There is something more than you''ve ever had before.<br/>All that men dare hope for and more can now be found in someone. . . .<br/>',NULL,45668,5);
INSERT INTO stanza VALUES('T10915','4','Satisfied — Jesus Christ you are so real to me.<br/>You have ended all my vanity.<br/>You fill the void that''s deep in me.<br/>Lord Jesus, You''re Reality.<br/>',NULL,45669,6);
INSERT INTO stanza VALUES('T10917','1','Jesus is a wonderful Savior, He will carry you through;<br/>Jesus is a wonderful Savior, He will carry you through;<br/>Jesus is a wonderful Savior, He will carry you through;<br/>Until the battle''s done and the victory is won.<br/>My Lord will carry you through; O my precious brother.<br/>When the world''s on fire, you''ll need my Jesus to be your Savior;<br/>He''ll hide you ever in the Rock of Ages, in the Rock of Ages just cleft for you.<br/>',NULL,45670,1);
INSERT INTO stanza VALUES('T10918','1','If you wish to find the Lord, do not seek Him in the world,<br/>For the world is not the place in which He dwells.<br/>In which He dwells, in which He dwells,<br/>In which He dwells, in which He dwells,<br/>For the world is not the place in which He dwells.<br/>',NULL,45671,1);
INSERT INTO stanza VALUES('T10918','2','If you wish to find the Lord, do not seek Him in the mind,<br/>For the mind can only know, it cannot taste.<br/>It cannot taste, it cannot taste,<br/>It cannot taste, it cannot taste,<br/>For the mind can only know, it cannot taste.<br/>',NULL,45672,2);
INSERT INTO stanza VALUES('T10918','3','If you wish to find the Lord, you must open up your heart,<br/>You must open up your heart and let Him in.<br/>Let Him in, let Him in,<br/>Let Him in, let Him in,<br/>You must open up your heart and let Him in.<br/>',NULL,45673,3);
INSERT INTO stanza VALUES('T10918','4','If you wish to let Him in, you just call upon His name,<br/>You just call upon His name and let Him in.<br/>Call His name, call His name,<br/>Call His name, call His name,<br/>You just call upon His name and let Him in.<br/>',NULL,45674,4);
INSERT INTO stanza VALUES('T10919','1','Jesus is the Lord, and He lives in me;<br/>Now I''m as happy as I can be.<br/>O Hallelujah! O Hallelujah!<br/>Jesus lives in me!<br/>',NULL,45675,1);
INSERT INTO stanza VALUES('T10919','2','All the world is filled with vanity;<br/>Jesus is the one reality.<br/>O Hallelujah! O Hallelujah!<br/>Jesus lives in me!<br/>',NULL,45676,2);
INSERT INTO stanza VALUES('T10920','1','Call upon the name, call upon the name,<br/>Call upon the name of the Lord;<br/>Call upon the name, call upon the name,<br/>Call upon the name of the Lord.<br/>',NULL,45677,1);
INSERT INTO stanza VALUES('T10920','chorus','O Lord Jesus! O Lord Jesus!<br/>Call upon the name of the Lord;<br/>O Lord Jesus! O Lord Jesus!<br/>Call upon the name of the Lord.<br/>',NULL,45678,2);
INSERT INTO stanza VALUES('T10920','2','Call upon His name, call upon His name,<br/>Call upon His name and be saved;<br/>Call upon His name, call upon His name,<br/>Call upon His name and be saved.<br/>',NULL,45679,3);
INSERT INTO stanza VALUES('T10920','chorus','O Lord Jesus! O Lord Jesus!<br/>Hallelujah, now I am saved!<br/>O Lord Jesus! O Lord Jesus!<br/>Hallelujah, now I am saved!<br/>',NULL,45680,4);
INSERT INTO stanza VALUES('T10921','1','O dear friend listen to His calling,<br/>Deep in your heart it keeps ringing;<br/>How soft and tender is His sweet voice,<br/>and yet it is so real.<br/>He invites you His love to possess,<br/>That you may experience His riches;<br/>He invites you to live for His will,<br/>Through you He''ll be satisfied still.<br/>',NULL,45681,1);
INSERT INTO stanza VALUES('T10921','2','My love, my love, it''s such a wonder,<br/>Thy voice is so sweet and tender;<br/>It melts my heart and makes me lose<br/>myself completely in Thee.<br/>Not only beloved child I''ll be;<br/>But to follow Thy footsteps firmly,<br/>To obey Thy will, Thy friend I''ll be,<br/>That Thou be satisfied through me.<br/>',NULL,45682,2);
INSERT INTO stanza VALUES('T10923','1','There is a bright new life that''s so exciting<br/>And you can have this life if you decide.<br/>The Lord can fill that lonely empty feeling<br/>He''ll give you joy and happiness inside.<br/>Now you don''t have to fully understand it,<br/>Or try to comprehend the hows and whys;<br/>But He will give you more than you could hope for,<br/>Much more than you could ever realize.<br/>You can experience something that is wonderful.<br/>You can experience something that is grand.<br/>You can experience something that is marvelous;<br/>If you let the Savior take you by the hand.<br/>There is a bright new life that''s so exciting<br/>And you can have this life if you decide.<br/>The Lord can fill that lonely empty feeling<br/>He''ll give you joy and happiness inside.<br/>',NULL,45683,1);
INSERT INTO stanza VALUES('T10926','1','One sat alone beside the highway begging,<br/>His eyes were blind, the light he could not see;<br/>He clutched his rags and shivered in the shadows,<br/>Then Jesus came and bade his darkness flee.<br/>',NULL,45684,1);
INSERT INTO stanza VALUES('T10926','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,45685,2);
INSERT INTO stanza VALUES('T10926','2','From home and friends the evil spirits drove him,<br/>Among the tombs he dwelt in misery;<br/>He cut himself as demon pow''rs possessed him,<br/>Then Jesus came and set the captive free.<br/>',NULL,45686,3);
INSERT INTO stanza VALUES('T10926','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,45687,4);
INSERT INTO stanza VALUES('T10926','3','"Unclean! Unclean!" the leper cried in torment,<br/>The deaf, the dumb, in helplessness stood near;<br/>The fever raged, disease had gripped its victim,<br/>Then Jesus came and cast out every fear.<br/>',NULL,45688,5);
INSERT INTO stanza VALUES('T10926','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,45689,6);
INSERT INTO stanza VALUES('T10926','4','Their hearts were sad as in the tomb they laid him,<br/>For death had come and taken him away;<br/>Their night was dark and bitter tears were falling,<br/>Then Jesus came and night was turned to day.<br/>',NULL,45690,7);
INSERT INTO stanza VALUES('T10926','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,45691,8);
INSERT INTO stanza VALUES('T10926','5','So men today have found the Savior able,<br/>They could not conquer passion, lust and sin;<br/>Their broken hearts had left them sad and lonely,<br/>Then Jesus came and dwelt, Himself, within.<br/>',NULL,45692,9);
INSERT INTO stanza VALUES('T10926','chorus','When Jesus comes the tempter''s pow''r is broken;<br/>When Jesus comes the tears are wiped away.<br/>He takes the gloom and fills the life with glory,<br/>For all is changed when Jesus comes to stay.<br/>',NULL,45693,10);
INSERT INTO stanza VALUES('T10927','1','There''s a Man Who died to set us free,<br/>Everybody knows it''s Jesus;<br/>He came down from heaven just to live in me,<br/>Everybody knows it''s Jesus!<br/>',NULL,45694,1);
INSERT INTO stanza VALUES('T10927','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,45695,2);
INSERT INTO stanza VALUES('T10927','2','There''s no other name on which to call,<br/>So open up and call on Jesus;<br/>Stop your doubting and start to call,<br/>Just open up and call on Jesus!<br/>',NULL,45696,3);
INSERT INTO stanza VALUES('T10927','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,45697,4);
INSERT INTO stanza VALUES('T10927','3','Religion never made it and it never will,<br/>All the people need is Jesus!<br/>Knowledge won''t help either, all it does is kill!<br/>The only need you have is Jesus!<br/>',NULL,45698,5);
INSERT INTO stanza VALUES('T10927','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,45699,6);
INSERT INTO stanza VALUES('T10927','4','Jesus fills the empty places with Himself,<br/>Come along and call, "Lord Jesus!"<br/>Listen closely while we tell you ''bout His wealth,<br/>Come along and call, "Lord Jesus!"<br/>',NULL,45700,7);
INSERT INTO stanza VALUES('T10927','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,45701,8);
INSERT INTO stanza VALUES('T10927','5','God''s been waiting just to get inside of you,<br/>So turn to him and call, "Lord Jesus!"<br/>Open up your heart and let Him into you<br/>By calling on the name of Jesus!<br/>',NULL,45702,9);
INSERT INTO stanza VALUES('T10927','chorus','Jesus, Jesus, everybody call on Jesus!<br/>Just open your heart and open your mouth,<br/>Yes, everybody call on Jesus!<br/>',NULL,45703,10);
INSERT INTO stanza VALUES('T10928','1','I once gave my life to a big corporation,<br/>Climbing the ladder to status and pay;<br/>I thought my career was my life''s biggest meaning,<br/>Then I found Jesus, now He''s boss today.<br/>',NULL,45704,1);
INSERT INTO stanza VALUES('T10928','chorus','Where, O where are you tonight?<br/>How can you leave here, lost and alone?<br/>We''ve searched the world over,<br/>And thought we found true life,<br/>Then we found Jesus, and He brought us home.<br/>',NULL,45705,2);
INSERT INTO stanza VALUES('T10928','2','For hours I tried to become intellectual,<br/>Learning, researching, expanding my head;<br/>I thought that the meaning of being was knowledge,<br/>Then I touched Jesus, and got life instead!<br/>',NULL,45706,3);
INSERT INTO stanza VALUES('T10928','chorus','Where, O where are you tonight?<br/>How can you leave here, lost and alone?<br/>We''ve searched the world over,<br/>And thought we found true life,<br/>Then we found Jesus, and He brought us home.<br/>',NULL,45707,4);
INSERT INTO stanza VALUES('T10928','3','Oh! I spent a lifetime in studying the Bible,<br/>Trying to understand God in my head;<br/>But finally I turned from my research to calling,<br/>Then I touched Christ, and got raised from the dead.<br/>',NULL,45708,5);
INSERT INTO stanza VALUES('T10928','chorus','Where, O where are you tonight?<br/>How can you leave here, lost and alone?<br/>We''ve searched the world over,<br/>And thought we found true life,<br/>Then we found Jesus, and He brought us home.<br/>',NULL,45709,6);
INSERT INTO stanza VALUES('T10929','1','Now this was once my situation,<br/>Wanting to be a sensation,<br/>In my fellows'' estimation quite a guy!<br/>But all I met was great frustration,<br/>And the endless aggravation<br/>Of those unseen complications in myself.<br/>',NULL,45710,1);
INSERT INTO stanza VALUES('T10929','chorus','And it made me want to say, "It''s a raw deal!"<br/>And it made me want to think, "Only if. . . ."<br/>And I wonder everyday,<br/>"Is there anything to living,<br/>''Cept to slowly die and dream of someday!"<br/>',NULL,45711,2);
INSERT INTO stanza VALUES('T10929','2','But then I had a confrontation,<br/>With a joyful delegation,<br/>They were filled with great elation, Jesus too!<br/>And Jesus paid a visitation,<br/>By His new life germination,<br/>I became a new creation through and through.<br/>',NULL,45712,3);
INSERT INTO stanza VALUES('T10929','chorus','Oh, He made me scream and shout, "Hallelujah!"<br/>Oh, He made me cry aloud, "O my Lord!"<br/>Oh, He flooded me with joy<br/>''Cause the glory in my spirit<br/>Made me part of God''s own family.<br/>',NULL,45713,4);
INSERT INTO stanza VALUES('T10929','3','So, if you''re craving liberation<br/>From your old life''s degradation,<br/>You have found your destination here tonight!<br/>Just turn your heart in preparation,<br/>And proclaim your declaration,<br/>"Jesus, be my full salvation, be my life!"<br/>',NULL,45714,5);
INSERT INTO stanza VALUES('T10929','chorus','Now you''ve touched Him, so cry out, "Hallelujah!"<br/>As He fills you, cry aloud, "Oh my Lord!"<br/>"Jesus Lord, You are much more<br/>Than I ever dreamed or longed for,<br/>Take my life, Lord, I belong to You!"<br/>',NULL,45715,6);
INSERT INTO stanza VALUES('T10930','1','I''m saved, saved, saved,<br/>My sins are all taken away;<br/>I''m saved, saved, saved,<br/>And happy in Jesus each day.<br/>He''s taken away all the burden of sin,<br/>The blood stream from Calvary cleanses within,<br/>And now I can shout,<br/>For there''s never a doubt,<br/>That I''m saved, saved, saved.<br/>',NULL,45716,1);
INSERT INTO stanza VALUES('T10931','1','I always knew deep down in me,<br/>There was a longing to be free,<br/>A kind of hunger deep inside—<br/>To fill it up, I tried and tried.<br/>There were a lot of things I had;<br/>Some things were good,<br/>Some things were bad.<br/>But all those things of mine before<br/>Don''t satisfy me anymore.<br/>',NULL,45717,1);
INSERT INTO stanza VALUES('T10931','chorus','Now life affords a real reward<br/>Whenever I just call, "O Lord!"<br/>The Triune God the Spirit is,<br/>And He can fill mine up with His.<br/>',NULL,45718,2);
INSERT INTO stanza VALUES('T10931','2','I always knew deep down in me<br/>There was a longing to be free,<br/>A kind of hunger deep inside—<br/>But now it can be satisfied. . .<br/>Christ in my heart — the only way<br/>To spread within me day by day.<br/>Lord Jesus! Lord, I have to say<br/>You''re home in me and home to stay!<br/>',NULL,45719,3);
INSERT INTO stanza VALUES('T10931','chorus','O Lord, I know now You will grow<br/>And from my spirit overflow!<br/>Now saturate me through and through!<br/>O Lord Jesus, I love You!<br/>O Lord Jesus, I love You!<br/>O Lord Jesus, I love You!<br/>',NULL,45720,4);
INSERT INTO stanza VALUES('T10932','beginning-note','Romans 5:1, 8<br/>',NULL,45721,1);
INSERT INTO stanza VALUES('T10932','1','Therefore being justified by faith,<br/>We have peace with God<br/>Through our Lord Jesus Christ.<br/>',NULL,45722,2);
INSERT INTO stanza VALUES('T10932','chorus','Because the love of God is shed abroad<br/>In our hearts by the Holy Spirit<br/>Which is given, which is given<br/>Unto us, to us, to us.<br/>',NULL,45723,3);
INSERT INTO stanza VALUES('T10932','2','God had commendeth His love toward us,<br/>In that, while we were yet sinners,<br/>Christ died for us.<br/>',NULL,45724,4);
INSERT INTO stanza VALUES('T10932','chorus','Because the love of God is shed abroad<br/>In our hearts by the Holy Spirit<br/>Which is given, which is given<br/>Unto us, to us, to us.<br/>',NULL,45725,5);
INSERT INTO stanza VALUES('T10933','1','Praise the Lord, God sent His Son,<br/>Hallelujah!<br/>And salvation''s work was done,<br/>Glory to God!<br/>God Himself became a man,<br/>So that we might live in Him.<br/>',NULL,45726,1);
INSERT INTO stanza VALUES('T10933','chorus','That''s why I call on Him,<br/>I give my all to Him.<br/>',NULL,45727,2);
INSERT INTO stanza VALUES('T10933','2','For us He was crucified, Hallelujah!<br/>For the many, one Man died, glory to God!<br/>One grain fell into the earth,<br/>Many grains to bring to birth.<br/>',NULL,45728,3);
INSERT INTO stanza VALUES('T10933','chorus','That''s why I call on Him,<br/>I give my all to Him.<br/>',NULL,45729,4);
INSERT INTO stanza VALUES('T10933','3','He arose in victory, Hallelujah!<br/>From the grave, triumphantly,<br/>Glory to God!<br/>Now in resurrection He<br/>As the Spirit lives in me.<br/>',NULL,45730,5);
INSERT INTO stanza VALUES('T10933','chorus','That''s why I call on Him,<br/>I give my all to Him.<br/>',NULL,45731,6);
INSERT INTO stanza VALUES('T10933','4','Call on Him from deep within, Hallelujah!<br/>Just by calling, He comes in, glory to God!<br/>Once you call upon His name,<br/>Nevermore you''ll be the same.<br/>',NULL,45732,7);
INSERT INTO stanza VALUES('T10933','chorus','We all must call on Him,<br/>We give our all to Him.<br/>',NULL,45733,8);
INSERT INTO stanza VALUES('T10933','1','Purihin Anak ng Diyos, Aleluya!<br/>Sinugo Siya''t nagtubos, gloria sa Diyos!<br/>Diyos Mismo naging tao,<br/>Nang buhay Niya matamo.<br/>',NULL,45734,9);
INSERT INTO stanza VALUES('T10933','chorus','Kaya Siya''y tawagin,<br/>Sa Kanya''y paangkin.<br/>',NULL,45735,10);
INSERT INTO stanza VALUES('T10933','2','Para sa ''tin pinako, Aleluya!<br/>Sa lahat Siya''y namatay, gloria sa Diyos!<br/>''Sang trigo binaôn na,<br/>Marami ang ''binunga.<br/>',NULL,45736,11);
INSERT INTO stanza VALUES('T10933','chorus','Kaya Siya''y tawagin,<br/>Sa Kanya''y paangkin.<br/>',NULL,45737,12);
INSERT INTO stanza VALUES('T10933','3','Nabuhay, nagtagumpay, Aleluya!<br/>Dinaig kamatayan, gloria sa Diyos!<br/>Bilang Espiritu Siya,<br/>Sa ''kin nanahanan na.<br/>',NULL,45738,13);
INSERT INTO stanza VALUES('T10933','chorus','Kaya Siya''y tawagin,<br/>Sa Kanya''y paangkin.<br/>',NULL,45739,14);
INSERT INTO stanza VALUES('T10933','4','Tawagin O Pangino''n, Aleluya!<br/>Papasok Siyang talaga, gloria sa Diyos!<br/>Tawagin ang ngalan Niya,<br/>Ika''y babaguhin nga.<br/>',NULL,45740,15);
INSERT INTO stanza VALUES('T10933','chorus','Kaya Siya''y tawagin,<br/>Sa Kanya''y paangkin.<br/>',NULL,45741,16);
INSERT INTO stanza VALUES('T10934','1','I''ve got a home in glory land that outshines the sun,<br/>I''ve got a home in glory land that outshines the sun,<br/>I''ve got a home in glory land that outshines the sun,<br/>Way beyond the blue.<br/>',NULL,45742,1);
INSERT INTO stanza VALUES('T10934','chorus','My friends, O my friends, it''s for you to share too,<br/>My friends, O my friends, it''s for you to share too,<br/>My friends, O my friends, it''s for you to share too,<br/>Way beyond the blue.<br/>',NULL,45743,2);
INSERT INTO stanza VALUES('T10934','2','I took Jesus as my Savior; you take Him too,<br/>I took Jesus as my Savior; you take Him too,<br/>I took Jesus as my Savior; you take Him too,<br/>While He''s calling you.<br/>',NULL,45744,3);
INSERT INTO stanza VALUES('T10934','chorus','Take Him, O take Him, O do take Him today,<br/>Take Him, O take Him, O do take Him today,<br/>Take Him, O take Him, O do take Him today,<br/>It is all of grace.<br/>',NULL,45745,4);
INSERT INTO stanza VALUES('T10936','1','I would love to tell you what I think of Jesus,<br/>Since I found in Him a friend so strong and true;<br/>I would tell you how He changed my life completely,<br/>He did something that no other friend could do.<br/>',NULL,45746,1);
INSERT INTO stanza VALUES('T10936','chorus','No one ever cared for me like Jesus,<br/>There''s no other friend so kind as He;<br/>No one else could take the sin and darkness from me,<br/>O how much He cared for me.<br/>',NULL,45747,2);
INSERT INTO stanza VALUES('T10936','2','All my life was full of sin when Jesus found me,<br/>All my heart was full of misery and woe;<br/>Jesus placed His strong and loving arms about me,<br/>And He led me in the way I ought to go.<br/>',NULL,45748,3);
INSERT INTO stanza VALUES('T10936','chorus','No one ever cared for me like Jesus,<br/>There''s no other friend so kind as He;<br/>No one else could take the sin and darkness from me,<br/>O how much He cared for me.<br/>',NULL,45749,4);
INSERT INTO stanza VALUES('T10936','1','Nais kong si Hesus ay aking isaysay,<br/>Nakita kong Siya''y tapat na kaibigan;<br/>Kung paanong binago ang aking buhay<br/>Ay hindi magagawa ng sinuman.<br/>',NULL,45750,5);
INSERT INTO stanza VALUES('T10936','chorus','Si Hesus ay di-mapaparisan,<br/>Maunawain na kaibigan;<br/>Pinaram ang aking mga kasalanan,<br/>At ako''y iningatan.<br/>',NULL,45751,6);
INSERT INTO stanza VALUES('T10936','2','Lugmok sa sala nang ako''y makita Niya,<br/>Puso ko''y batbat ng dusa''t balisa;<br/>Yakap ni Hesus sa ''ki''y nagpaligaya,<br/>At sa daan ako''y ginabayan Niya.<br/>',NULL,45752,7);
INSERT INTO stanza VALUES('T10936','chorus','Si Hesus ay di-mapaparisan,<br/>Maunawain na kaibigan;<br/>Pinaram ang aking mga kasalanan,<br/>At ako''y iningatan.<br/>',NULL,45753,8);
INSERT INTO stanza VALUES('T10936','3','Pinatitibay ang aking pananalig,<br/>At talos ko ang pintig ng pag-ibig,<br/>Nguni''t ang pagsakop Niya''y di ko malirip<br/>Hanggang ang Kanyang mukha ay mamasid.<br/>',NULL,45754,9);
INSERT INTO stanza VALUES('T10936','chorus','Si Hesus ay di-mapaparisan,<br/>Maunawain na kaibigan;<br/>Pinaram ang aking mga kasalanan,<br/>At ako''y iningatan.<br/>',NULL,45755,10);
INSERT INTO stanza VALUES('T10937','1','All throughout the darkest night,<br/>Shining stars were not in sight,<br/>God remembered still His holy covenant right;<br/>While we sit at darkness'' height,<br/>On death-roads we see no light,<br/>Rising sun of God from heav''n comes shining bright.<br/>',NULL,45756,1);
INSERT INTO stanza VALUES('T10937','chorus','God''s compassion-heart alway<br/>Cares for sinners'' sore dismay,<br/>Guides our feet unto His peace in all the way;<br/>Darkness now He drives away,<br/>God''s salvation''s here to stay,<br/>And He turns us from our night into day.<br/>',NULL,45757,2);
INSERT INTO stanza VALUES('T10937','2','Thou hast sought the lost like me,<br/>Thou hast set the sinners free,<br/>Thou hast filled the wretched souls with heavenly glee;<br/>God Himself lived out from Thee,<br/>Saving grace in Thee we see,<br/>Thou hast brought to earth the joy of jubilee.<br/>',NULL,45758,3);
INSERT INTO stanza VALUES('T10937','chorus','Thou the mingled God and man,<br/>Thou the perfect Holy One,<br/>Thou expressed the human virtues of the Son;<br/>Love Thee, Savior, I avow,<br/>Worship Thee, my heart doth bow,<br/>Praise Thee, Lord, for Thou hast dwelt in me now.<br/>',NULL,45759,4);
INSERT INTO stanza VALUES('T10937','1','Sa pagtahak ko sa buhay<br/>Na nasa karimlan,<br/>Naalala pa ng Diyos tipan Niyang banal;<br/>Habang nakalugmok sa<br/>Lilim ng kamatayan,<br/>Bukang-liwayway ng Diyos ay dumatal.<br/>',NULL,45760,5);
INSERT INTO stanza VALUES('T10937','chorus','Diyos ''ming dinalanginan,<br/>Kami ay kahabagan,<br/>Gabayan sa daan ng kapayapaan;<br/>Dilim, Kanyang pinaram,<br/>Gabi''y niliwanagan,<br/>Kaligtasan ng Diyos ay nasumpungan.<br/>',NULL,45761,6);
INSERT INTO stanza VALUES('T10937','2','Kinalinga ang mga<br/>Aba at nawawala,<br/>Mga makasalanan ay pinalaya;<br/>Nasinag ang Diyos at<br/>Nagliligtas Mong biyaya,<br/>Naghatid ng ligaya rito sa lupa.<br/>',NULL,45762,7);
INSERT INTO stanza VALUES('T10937','chorus','Diyos-taong pinaglangkap,<br/>Sakdal sa kabanalan,<br/>Katangian ng Anak inihahayag;<br/>Sambahin Ka''t mahalin<br/>Panata ng puso ko,<br/>Purihin Ka Hesus nanahan sa ''kin.<br/>',NULL,45763,8);
INSERT INTO stanza VALUES('T10938','beginning-note','(Tune: Hymn1054)<br> Chapter 71, Messages given during the Resumption of Watchman Nee''s Ministry, Vol.2<br/>',NULL,45764,1);
INSERT INTO stanza VALUES('T10938','1','Hear the voice of love, O sinner,<br/>''Tis the Savior''s cry;<br/>While He''s seeking for the sinners,<br/>Do not pass Him by!<br/>',NULL,45765,2);
INSERT INTO stanza VALUES('T10938','chorus','Sinner, sinner,<br/>Hear the Savior''s cry,<br/>While He''s seeking for the sinners,<br/>Do not pass Him by!<br/>',NULL,45766,3);
INSERT INTO stanza VALUES('T10938','2','Do not pass me by, O Savior,<br/>Hear my earnest cry;<br/>While the others You are calling,<br/>Do not pass me by!<br/>',NULL,45767,4);
INSERT INTO stanza VALUES('T10938','chorus','Savior, Savior,<br/>hear my earnest cry,<br/>While the others You are calling,<br/>Do not pass me by!<br/>',NULL,45768,5);
INSERT INTO stanza VALUES('T10938','1','Tinig ng pag-ibig dinggin,<br/>Taong salarin;<br/>Tagapagligtas naghanap,<br/>Talikdan Siya''y h''wag.<br/>',NULL,45769,6);
INSERT INTO stanza VALUES('T10938','chorus','Dinggin, dinggin<br/>ang pagtawag Niya,<br/>Maysala''y hinahanap Niya,<br/>Huwag talikdan Siya!<br/>',NULL,45770,7);
INSERT INTO stanza VALUES('T10938','2','Manliligtas huwag lampasan,<br/>Ako''y pakinggan;<br/>Kung iba''y tinatawag Mo,<br/>''Ko''y di lampasan!<br/>',NULL,45771,8);
INSERT INTO stanza VALUES('T10938','chorus','Tagapagligtas, dinggin Mo ako.<br/>Habang iba''y tinawag Mo,<br/>Huwag lamp''san ako!<br/>',NULL,45772,9);
INSERT INTO stanza VALUES('T10939','beginning-note','Let Me Love<br/>',NULL,45773,1);
INSERT INTO stanza VALUES('T10939','1','Let me love and not be requited,<br/>Let me serve and not be rewarded,<br/>Let me labor and not be remembered,<br/>Let me suffer and not be regarded.<br/>',NULL,45774,2);
INSERT INTO stanza VALUES('T10939','2','Let me pour wine, while I drink not,<br/>Let me break bread, while I eat not,<br/>Pour our my life that others be blessed,<br/>Lose my self life that they be comforted.<br/>',NULL,45775,3);
INSERT INTO stanza VALUES('T10939','3','I do not seek pity or wishes,<br/>I do not seek glory or riches,<br/>But I''d rather be lonely, wretched<br/>Be discarded, be wrongly treated.<br/>',NULL,45776,4);
INSERT INTO stanza VALUES('T10939','4','With my blood and tears<br/>pay the price to gain the crown<br/>On this pilgrims'' ground<br/>bear all sorrows that abound<br/>For this way you did tread when you lived<br/>on this earth which is of your own<br/>Gladly bore all loss as You purposed,<br/>That the people around you be composed.<br/>',NULL,45777,5);
INSERT INTO stanza VALUES('T10939','5','I know not how far the future lies ahead,<br/>On this path of no retreating I am led.<br/>So let me, Lord, now learn<br/>of Your perfect pattern,<br/>Suffered wrong, no resentment in return.<br/>',NULL,45778,6);
INSERT INTO stanza VALUES('T10939','6','May you in this tedious, dark interim<br/>Wipe away all my tears, somber and dim.<br/>For You are my solace I learn to know,<br/>Let my life be a pleasing fountain flow.<br/>',NULL,45779,7);
INSERT INTO stanza VALUES('T10939','7','Hayaan Mong umibig ako,<br/>Hayaan Mong maglingkod ako,<br/>Umibig nang di gagantihan,<br/>Maglilingkod nang di babayaran.<br/>',NULL,45780,8);
INSERT INTO stanza VALUES('T10939','8','Binuhos kong alak, di natikman,<br/>Tinapay pinutol, di nagsimpan,<br/>Buhay ko sa iba''y pagpapala<br/>Aking binuhos, maaliw sila.<br/>',NULL,45781,9);
INSERT INTO stanza VALUES('T10939','9','Di ko nais awa''t, pagbati<br/>Di ko nais yaman, l''walhati<br/>Manapa''y mamanglaw, hamakin<br/>Maiwaksi, alipustahin.<br/>',NULL,45782,10);
INSERT INTO stanza VALUES('T10939','10','Ang putong sa dugo''t<br/>luha ko''y katumbas,<br/>Lahat ng lumbay pasan sa ''king landas,<br/>Pagka''t tinahak Mo''ng daang ito<br/>Nang Ikaw ay nabuhay sa mundo<br/>Pagkalugi''y babatahin ko<br/>Upang mga tao''y mahusay Mo.<br/>',NULL,45783,11);
INSERT INTO stanza VALUES('T10939','11','Aking hinaharap di ko malaman,<br/>Sa landasin itong walang urungan<br/>Nawa''y Iyong tularan<br/>aking matutuhan.<br/>Di magdamdam, kahit pagkamalan.<br/>',NULL,45784,12);
INSERT INTO stanza VALUES('T10939','12','Sa bagot at mapagal na daan<br/>Pawiin Mo''ng luha''t kapanglawan<br/>Pagka''t ang aliw ko''y Ikaw mahal,<br/>Buhay ko nawa''y maging ''sang bukal.<br/>',NULL,45785,13);
INSERT INTO stanza VALUES('T20001','1','The saving by Thy life, O God,<br/>Fully Thy righteousness doth meet;<br/>Perfect, ''tis right judicially<br/>And also rich organically.<br/>',NULL,45786,1);
INSERT INTO stanza VALUES('T20001','2','Judicially Thou dost redeem,<br/>And Thou dost save organic''lly.<br/>Thy righteousness is satisfied,<br/>Thy heart''s desire fulfilled to be.<br/>',NULL,45787,2);
INSERT INTO stanza VALUES('T20001','3','Judicially I''m justified<br/>And one with Thee organic''lly.<br/>Reborn of Thee a God-man true,<br/>Now sanctify, renew wholly.<br/>',NULL,45788,3);
INSERT INTO stanza VALUES('T20001','4','Beholding Thee I''ll be transformed<br/>By Thine own life metabolic''ly;<br/>Conformed to Thee, God''s firstborn Son,<br/>Thy glorious image shown through me.<br/>',NULL,45789,4);
INSERT INTO stanza VALUES('T20001','5','By Thy life''s growth matured I''ll be,<br/>Arriving at a full-grown man;<br/>Coordinated, built by Thee<br/>Into Thy Body for Thy plan.<br/>',NULL,45790,5);
INSERT INTO stanza VALUES('T20001','6','Redeemed my body, glorified,<br/>Peak of Thy sonship I''ll attain;<br/>A mutual dwelling, blent with Thee,<br/>The New Jerus''lem, my refrain.<br/>',NULL,45791,6);
INSERT INTO stanza VALUES('T20002','1','What miracle! What mystery!<br/>That God and man should blended be!<br/>God became man to make man God,<br/>Untraceable economy!<br/>From his good pleasure, heart''s desire,<br/>His highest goal attained will be.<br/>From his good pleasure, heart''s desire,<br/>His highest goal attained will be.<br/>',NULL,45792,1);
INSERT INTO stanza VALUES('T20002','2','Flesh He became, the first God-man,<br/>His pleasure that I God may be:<br/>In life and nature I''m God''s kind,<br/>Though Godhead''s His exclusively.<br/>His attributes my virtues are;<br/>His glorious image shines through me.<br/>His attributes my virtues are;<br/>His glorious image shines through me.<br/>',NULL,45793,2);
INSERT INTO stanza VALUES('T20002','3','No longer I alone that live,<br/>But God together lives with me.<br/>Built with the saints in the Triune God,<br/>His universal house we''ll be,<br/>And His organic Body we<br/>For His expression corp''rately.<br/>And His organic Body we<br/>For His expression corp''rately.<br/>',NULL,45794,3);
INSERT INTO stanza VALUES('T20002','4','Jerusalem, the ultimate,<br/>Of visions the totality;<br/>The Triune God, tripartite man—<br/>A loving pair eternally—<br/>As man yet God they coinhere,<br/>A mutual dwelling place to be;<br/>God''s glory in humanity<br/>Shines forth in splendor radiantly!<br/>',NULL,45795,4);
INSERT INTO stanza VALUES('T20002','1','Mahimala, kay hiwaga!<br/>Diyos sa tao''y nakiisa.<br/>Naging tao ang Diyos natin,<br/>Upang tayo ay maging Diyos din.<br/>Mula sa Kanyang naisin;<br/>Hanggang rurok ng layunin.<br/>Mula sa Kanyang naisin;<br/>Hanggang rurok ng layunin.<br/>',NULL,45796,5);
INSERT INTO stanza VALUES('T20002','2','Naging laman Siya''y Diyos-tao<br/>Nang maging Diyos naman tayo;<br/>Sa buhay, likas tulad Niya,<br/>Nguni''t di sa pagka-Diyos Niya.<br/>O, ang Kanyang katangian,<br/>Naging aking kagalingan;<br/>Kanyang mal''walhating anyo,<br/>Buháy na naihayag ko.<br/>',NULL,45797,6);
INSERT INTO stanza VALUES('T20002','3','Di na mag-isang nabuhay,<br/>Sa akin Diyos nabubuhay.<br/>Sa Tres-unong Diyos tinayo,<br/>Mga banal, bahay tayo,<br/>Organikong Katawan Niya,<br/>Sama-samang kahayagan.<br/>Organikong Katawan Niya,<br/>Sama-samang kahayagan.<br/>',NULL,45798,7);
INSERT INTO stanza VALUES('T20002','4','Lunsod banal Herusalem<br/>Pangitain, pahayag din;<br/>Sukdulang kaganapan nga,<br/>Sa Lunsod Banal lubos na.<br/>Sa Tres-unong Diyos palagi,<br/>Taong may tatlong bahagi;<br/>Pagka-Diyos at pagka-tao,<br/>Tahanan ng Diyos at tao.<br/>',NULL,45799,8);
INSERT INTO stanza VALUES('T20003','1','All God''s divine truth has now been revealed,<br/>Opened, unveiled, no longer sealed;<br/>Clear, full, and pure, now at its highest peak,<br/>As real treasure to all who seek.<br/>',NULL,45800,1);
INSERT INTO stanza VALUES('T20003','chorus','Let high truth enter and fill us,<br/>Saturate and constitute us;<br/>Read, deeper dig and labor to know,<br/>Till God''s divine truth may outflow.<br/>',NULL,45801,2);
INSERT INTO stanza VALUES('T20003','2','Our God desires that we may fully know<br/>His truth, that Christ may freely grow;<br/>Christ and the church as His economy,<br/>Both make His truth a reality.<br/>',NULL,45802,3);
INSERT INTO stanza VALUES('T20003','chorus','Let high truth enter and fill us,<br/>Saturate and constitute us;<br/>Read, deeper dig and labor to know,<br/>Till God''s divine truth may outflow.<br/>',NULL,45803,4);
INSERT INTO stanza VALUES('T20003','3','Christ''s Word in us must dwell richly,<br/>Surely this, the best and solid way;<br/>Pray-read, study, recite, and prophesy,<br/>New practice makes our speaking high.<br/>',NULL,45804,5);
INSERT INTO stanza VALUES('T20003','chorus','Let high truth enter and fill us,<br/>Saturate and constitute us;<br/>Read, deeper dig and labor to know,<br/>Till God''s divine truth may outflow.<br/>',NULL,45805,6);
INSERT INTO stanza VALUES('T20003','4','Now God''s divine truth has been crystallized,<br/>We have in this new age realized;<br/>New language speaks truth that''s mystical,<br/>That makes the God-men practical.<br/>',NULL,45806,7);
INSERT INTO stanza VALUES('T20003','chorus','Let high truth enter and fill us,<br/>Saturate and constitute us;<br/>Read, deeper dig and labor to know,<br/>Till God''s divine truth may outflow.<br/>',NULL,45807,8);
INSERT INTO stanza VALUES('T20003','5','The truth on New Testament ministry,<br/>Can fulfill our God''s economy;<br/>The apostles'' teaching we''re ministering,<br/>The Body''s oneness we will bring.<br/>',NULL,45808,9);
INSERT INTO stanza VALUES('T20003','chorus','Let high truth enter and fill us,<br/>Saturate and constitute us;<br/>Read, deeper dig and labor to know,<br/>Till God''s divine truth may outflow.<br/>',NULL,45809,10);
INSERT INTO stanza VALUES('T20003','1','Katotohanan ng Diyos nahayag,<br/>Tabing naalis, nabunyag,<br/>Nasa rurok na''t malinaw, puro,<br/>Sa uhaw yamang totoo.<br/>',NULL,45810,11);
INSERT INTO stanza VALUES('T20003','chorus','Pun''an ng katotohanan,<br/>Mabuuan, mapuspusan;<br/>Magbasa, magpagal, alamin,<br/>Katot''hanan paapawin.<br/>',NULL,45811,12);
INSERT INTO stanza VALUES('T20003','2','Nais ng Diyos ating malaman<br/>Katot''hanan nang lubusan.<br/>Kristo''t ekklesia, ekonomiya<br/>Paglago''y maging tunay nga.<br/>',NULL,45812,13);
INSERT INTO stanza VALUES('T20003','chorus','Pun''an ng katotohanan,<br/>Mabuuan, mapuspusan;<br/>Magbasa, magpagal, alamin,<br/>Katot''hanan paapawin.<br/>',NULL,45813,14);
INSERT INTO stanza VALUES('T20003','3','Manahang sagana Salita Niya,<br/>Tayo''y mag-PSRP pa,<br/>Ang propesiya''y mapapataas,<br/>Bawa''t kapatid matatas.<br/>',NULL,45814,15);
INSERT INTO stanza VALUES('T20003','chorus','Pun''an ng katotohanan,<br/>Mabuuan, mapuspusan;<br/>Magbasa, magpagal, alamin,<br/>Katot''hanan paapawin.<br/>',NULL,45815,16);
INSERT INTO stanza VALUES('T20003','4','Napakristal na ang katot''hanan,<br/>Sa bagong kapanahunan;<br/>Bagong lengwahe sadyang mistikal,<br/>Tayong Diyos-tao''y praktikal.<br/>',NULL,45816,17);
INSERT INTO stanza VALUES('T20003','chorus','Pun''an ng katotohanan,<br/>Mabuuan, mapuspusan;<br/>Magbasa, magpagal, alamin,<br/>Katot''hanan paapawin.<br/>',NULL,45817,18);
INSERT INTO stanza VALUES('T20003','5','Ang ministeryo ng Bagong Tipan<br/>Tinupad ng katot''hanan;<br/>Sa pagtuturo ng mga apostol,<br/>Iisang Katawan sakdal.<br/>',NULL,45818,19);
INSERT INTO stanza VALUES('T20003','chorus','Pun''an ng katotohanan,<br/>Mabuuan, mapuspusan;<br/>Magbasa, magpagal, alamin,<br/>Katot''hanan paapawin.<br/>',NULL,45819,20);
INSERT INTO stanza VALUES('T20004','1','O Lord, I love you — I really love You<br/>Without You life''s really nothing<br/>You are so attractive and<br/>You are so charming<br/>Your riches are unsearchable.<br/>Your name''s so dear and sweet,<br/>calling makes one satisfied<br/>Lord, You are mine and I am Thine, Lord<br/>Joined and mingled with You,<br/>God-man incorp''ration,<br/>Foretaste of the New Jerusalem.<br/>',NULL,45820,1);
INSERT INTO stanza VALUES('T20004','1','O mahal Kita, Panginoong Hesus<br/>Kung wala Ka''y hungkag ang buhay<br/>Nakaaakit Ka, mapangbighani Ka,<br/>Ang Iyong yama''y di-malirip.<br/>Kay tamis Iyong ngalan, tawagin may siya<br/>Ako''y Iyo, Ikaw ay akin<br/>Naugpong, nahalo, Diyos-taong nalakip,<br/>Natikman Bagong Herusalem.<br/>',NULL,45821,2);
INSERT INTO stanza VALUES('T20004','1','(Russian)<br/>O Gospot Ia Lublu<br/>Ya Lublu Tsibia<br/>Bez Tsibia Dziznia prosta nizto<br/>Privlecatselen ti I charues saboy<br/>Bagatsva troi nie izriech<br/>Sladko ima tovayo<br/>Sasliv prisivatyevo<br/>I ti moi ya tboy naveki<br/>Vhna sliti sayuz<br/>Savakupnas I Vkus<br/>Novava Yerusalima.<br/>',NULL,45822,3);
INSERT INTO stanza VALUES('T20005','1','O the joy of having nothing,<br/>Being nothing, seeing nothing,<br/>But a living Christ in glory<br/>And being careful for nothing<br/>',NULL,45823,1);
INSERT INTO stanza VALUES('T20005','2','O the joy of having nothing,<br/>Being nothing, seeing nothing,<br/>But a living Christ in glory<br/>And His int''rest here on earth.<br/>',NULL,45824,2);
INSERT INTO stanza VALUES('T20005','1','Kay galak, walang taglay ka,<br/>Bal''wala ka, ni makita<br/>Kundi si Kristo sa gloria<br/>At di nag-aalala.<br/>',NULL,45825,3);
INSERT INTO stanza VALUES('T20005','2','Kay galak, walang taglay ka,<br/>Bal''wala ka, ni makita<br/>Kundi si Kristo sa gloria<br/>Interes Niya sa lupa.<br/>',NULL,45826,4);
INSERT INTO stanza VALUES('T20005','1','(Korean)<br/>Amokato Khachiangco<br/>Amokato Phochiangco<br/>Yong kuang Ane Krisito man<br/>Para phonum Khipunmeo.<br/>Amokato Khachiangco<br/>Amokato Phochiangco<br/>Ogi Kriye Kuaning maner<br/>Kuan sin manen Kippomio.<br/>',NULL,45827,5);
INSERT INTO stanza VALUES('T30001','1','God''s eternal economy is to make man the same as He is<br/>in life and nature but not in the Godhead<br/>and to make Himself one with man and man one with Him<br/>thus to be enlarged and expanded in His expression<br/><u>that all His divine</u>&nbsp;(2x) attributes may be expressed in human virtues.<br/>',NULL,45828,1);
INSERT INTO stanza VALUES('T30002','1','The Lord''s recovery is God becoming the flesh,<br/>the flesh becoming the life-giving Spirit, the life-giving Spirit<br/>becoming the sevenfold intensified Spirit<br/>to build up the church that produces the Body of Christ<br/>and that consummates the New Jerusalem.<br/>',NULL,45829,1);
INSERT INTO stanza VALUES('T30003','1','A lover of Christ should be one who is called by His love and drawn by His sweetness to pursue after Him for full satisfaction.<br/>',NULL,45830,1);
INSERT INTO stanza VALUES('T30003','2','A lover of Christ should be one who is called by Him to be delivered from the self through his oneness with the cross of Christ.<br/>',NULL,45831,2);
INSERT INTO stanza VALUES('T30003','3','A lover of Christ should be one who is called by Him to live in ascension as the new creation of God in the resurrection of Christ.<br/>',NULL,45832,3);
INSERT INTO stanza VALUES('T30003','4','A lover of Christ should be one who is called by Him more strongly to live within the veil through His cross after the lover''s experience of His resurrection.<br/>',NULL,45833,4);
INSERT INTO stanza VALUES('T30004','1','One Bible — One Revelation<br/>One God — One Economy<br/>One Christ — the Unsearchable One<br/>One Spirit — One Application<br/>One Life — One Element<br/>One Salvation — One Way of Saving<br/>One Kind of Living — One Manifestation of Christ<br/>One Testimony — One Expression<br/>One Body — One Organism<br/>One City — One Consummation<br/>',NULL,45834,1);
INSERT INTO stanza VALUES('T30005','1','The complete salvation of God has two aspects — the judicial aspect and the organic aspect.<br/>',NULL,45835,1);
INSERT INTO stanza VALUES('T30005','2','The judicial aspect is the procedure of God''s salvation through the redemption of Christ for God''s salvation to fully meet the righteous requirement of His law.<br/>',NULL,45836,2);
INSERT INTO stanza VALUES('T30005','3','The organic aspect is the fulfillment of God''s salvation through the life of Christ for the believers to be transformed and to grow and mature in the life of God.<br/>',NULL,45837,3);
INSERT INTO stanza VALUES('T30005','4','The salvation of the God is with Christ as the center, the Body of Christ as the line, and the New Jerusalem as the goal, and is fully accomplished through the life-giving Spirit.<br/>',NULL,45838,4);
INSERT INTO stanza VALUES('T30006','1','The Triune God who passed through all the processes,<br/>The all-inclusive Christ who was incarnated to die and resurrect,<br/>And the life-giving Spirit who was consummated to indwell us,<br/>They all take the New Jerusalem as Their eternal goal.<br/>',NULL,45839,1);
INSERT INTO stanza VALUES('T30007','1','The full ministry of Christ is carried out in three stages for the fulfillment of God''s eternal economy.<br/>',NULL,45840,1);
INSERT INTO stanza VALUES('T30007','2','In the first stage of incarnation, to bring God into man, to express God in humanity, and to accomplish His judicial redemption.<br/>',NULL,45841,2);
INSERT INTO stanza VALUES('T30007','3','In the second stage of inclusion, to be begotten as God''s firstborn Son, to become the life-giving Spirit, and to regenerate the believers for His Body.<br/>',NULL,45842,3);
INSERT INTO stanza VALUES('T30007','4','In the third stage of intensification, to intensify His organic salvation, to produce the overcomers, and to consummate the New Jerusalem.<br/>',NULL,45843,4);
INSERT INTO stanza VALUES('T30008','1','The glory of Christ''s divinity was concealed in Him as a grain of wheat.<br/>',NULL,45844,1);
INSERT INTO stanza VALUES('T30008','2','In His glorification He, as the last Adam, became the life-giving Spirit for His divine dispensing.<br/>',NULL,45845,2);
INSERT INTO stanza VALUES('T30008','3','In His resurrection He was born with His humanity to be the firstborn Son of God for His divine transformation.<br/>',NULL,45846,3);
INSERT INTO stanza VALUES('T30008','4','Through His resurrection all His believers were regenerated to be the many sons of God for His divine multiplication.<br/>',NULL,45847,4);
INSERT INTO stanza VALUES('T30009','1','God''s complete salvation is based upon His righteousness and through our faith.<br/>',NULL,45848,1);
INSERT INTO stanza VALUES('T30009','2','By the two divine transfers: out of Adam into Christ and out of the flesh into the Spirit.<br/>',NULL,45849,2);
INSERT INTO stanza VALUES('T30009','3','In the one spiritual union of the Spirit of life in our spirit, forming a mingled spirit.<br/>',NULL,45850,3);
INSERT INTO stanza VALUES('T30009','4','For us to reign in life by the abundance of grace and of the gift of righteousness.<br/>',NULL,45851,4);
INSERT INTO stanza VALUES('T30010','1','God regenerates us that we may have His divine life and renews us that we may become His divine new creation.<br/>',NULL,45852,1);
INSERT INTO stanza VALUES('T30010','2','God sanctifies us that we may have His holy nature and transforms us that we may have His divine image.<br/>',NULL,45853,2);
INSERT INTO stanza VALUES('T30010','3','God conforms us that we may have His divine element and glorifies us that we may have His divine image in full.<br/>',NULL,45854,3);
INSERT INTO stanza VALUES('T30010','4','We reign in God''s life by His organic salvation to accomplish His eternal economy and achieve His divine purpose.<br/>',NULL,45855,4);
INSERT INTO stanza VALUES('T30011','1','The apostle''s teaching is the entire speaking of God in the New Testament concerning God''s New Testament economy.<br/>',NULL,45856,1);
INSERT INTO stanza VALUES('T30011','2','The New Testament ministry is the unique ministry according to the apostles'' teaching, the teaching of God''s New Testament economy, for the building up of the Body of Christ to consummate the New Jerusalem.<br/>',NULL,45857,2);
INSERT INTO stanza VALUES('T30011','3','God''s economy is His plan to dispense Himself into His chosen people as their life and everything to produce and build up the organic Body of Christ.<br/>',NULL,45858,3);
INSERT INTO stanza VALUES('T30011','4','The New Jerusalem as the consummation of God''s eternal economy is the divine and human incorporation of the processed and consummated God constituted with His regenerated, transformed, and glorified elect.<br/>',NULL,45859,4);
INSERT INTO stanza VALUES('T30012','1','When we experience God as the blowing wind, the overshadowing cloud, the consuming fire, and the glowing electrum, we become the four living creatures, coordinating to carry out God''s economy for His expression, move, and administration.<br/>',NULL,45860,1);
INSERT INTO stanza VALUES('T30012','2','The move of God to carry out His economy is by the high and awesome wheels with a clear sky, the throne, and a rainbow.<br/>',NULL,45861,2);
INSERT INTO stanza VALUES('T30012','3','Through the breathing of the Spirit, the Lord revives His dead and scattered people to form them into an army to deal with His enemy and to build them up as His dwelling place for His expression.<br/>',NULL,45862,3);
INSERT INTO stanza VALUES('T30012','4','If we would participate in the move of God in His recovery, we need to experience increasingly the flowing of the living water out of the house of God through the Lord''s complete measuring and our absolute consecration.<br/>',NULL,45863,4);
INSERT INTO stanza VALUES('T30013','1','The believers in Christ should be river crossers, following the Lord Jesus, the Pioneer and Forerunner, into the glorious expression of the Divine Being.<br/>',NULL,45864,1);
INSERT INTO stanza VALUES('T30013','2','Christ as the Captain of salvation is leading God''s many sons into glory, the corporate expression of God, by saving them organically through sanctification.<br/>',NULL,45865,2);
INSERT INTO stanza VALUES('T30013','3','Christ, our High Priest, ministers to us whatever we need, dispensing Himself into us as our supply for the fulfillment of God''s eternal purpose.<br/>',NULL,45866,3);
INSERT INTO stanza VALUES('T30013','4','We need to brought on to maturity, pursuing toward the fullest enjoyment and gaining of Christ for the uttermost enjoyment of Christ in the millennial kingdom.<br/>',NULL,45867,4);
INSERT INTO stanza VALUES('T30014','1','In His heavenly ministry, Christ, the kingly and divine High Priest, is executing the new testament by interceding for us, shepherding us, and ministering Himself into us.<br/>',NULL,45868,1);
INSERT INTO stanza VALUES('T30014','2','The firstborn Son of God works in us as the law of life to "sonize" us, to conform us to His image for His corporate expression.<br/>',NULL,45869,2);
INSERT INTO stanza VALUES('T30014','3','Faith is the unique way to enjoy Christ in His heavenly ministry and to experience all the bequests in the new testament.<br/>',NULL,45870,3);
INSERT INTO stanza VALUES('T30014','4','We need to exercise our spirit that we may enter within the veil to have direct contact with the heavenly Christ, beholding Him to be infused with Him that we may become His corporate reproduction.<br/>',NULL,45871,4);
INSERT INTO stanza VALUES('T30015','1','Christ, the worthy and enthroned Lion-Lamb, is the heavenly Administrator in the divine government, opening the scroll of God''s economy to unlock the secret of the universe.<br/>',NULL,45872,1);
INSERT INTO stanza VALUES('T30015','2','We need to subjectively experience the detailed aspects of the golden lampstand, so that we can become the reproduction of the lampstand, the expression of the Triune God.<br/>',NULL,45873,2);
INSERT INTO stanza VALUES('T30015','3','The overcomers, produced through the intensification of God''s organic salvation by Christ as the sevenfold intensified Spirit, conquer the satanic chaos and triumph in the divine economy.<br/>',NULL,45874,3);
INSERT INTO stanza VALUES('T30015','4','We need to follow the Lamb wherever He may go to preach the gospel of the kingdom to the whole inhabited earth for the propagation of the seed, the gene, of the kingdom to consummate this age.<br/>',NULL,45875,4);
INSERT INTO stanza VALUES('T30016','1','God will use the overcomers to fulfill His economy, to defeat His enemy, and to bring His kingdom to the earth.<br/>',NULL,45876,1);
INSERT INTO stanza VALUES('T30016','2','The overcomers are nourished with all the riches of Christ and saturated and permeated with the element of Christ.<br/>',NULL,45877,2);
INSERT INTO stanza VALUES('T30016','3','The consummation of the processed and consummated Triune God and the consummation of God''s regenerated, transformed, and glorified people will be a universal couple, the New Jerusalem, expressing the Triune God for eternity.<br/>',NULL,45878,3);
INSERT INTO stanza VALUES('T30016','4','The New Jerusalem is the ultimate consummation of the Triune God, who is working Himself into His chosen and redeemed people to be their entrance, constitution, existence, enjoyment, living, and expression.<br/>',NULL,45879,4);
INSERT INTO stanza VALUES('T30017','1','The New Jerusalem is the destination of the flowing Triune God.<br/>',NULL,45880,1);
INSERT INTO stanza VALUES('T30017','2','We become the New Jerusalem by enjoying the processed and consummated Triune God as grace.<br/>',NULL,45881,2);
INSERT INTO stanza VALUES('T30017','3','We build the New Jerusalem by working with the Lord in the divine stream, the flow of the divine life.<br/>',NULL,45882,3);
INSERT INTO stanza VALUES('T30017','4','The Lord''s recovery is to build up Zion, the reality of the Body of Christ, consummating in the New Jerusalem.<br/>',NULL,45883,4);
INSERT INTO stanza VALUES('CS31','chorus','讚美基督是平安祭,<br/>使神與人滿意;<br/>距離全去,交通甜蜜,<br/>平安永遠堅立!<br/>',NULL,45884,11);
INSERT INTO stanza VALUES('CS31','chorus','讚美基督是平安祭,<br/>使神與人滿意;<br/>距離全去,交通甜蜜,<br/>平安永遠堅立!<br/>',NULL,45885,9);
INSERT INTO stanza VALUES('G1','1','Herrlichkeit sei Gott dem Vater,<br/>Herrlichkeit dem Sohn,<br/>Herrlichkeit dem Heil’gen Geiste –<br/>Welch Person!<br/>',NULL,45886,1);
INSERT INTO stanza VALUES('G1','2','Unermesslich ist die Schöpfung,<br/>Wunderbar der Plan,<br/>Unsre Herzen sind bewegt und<br/>Beten an.<br/>',NULL,45887,2);
INSERT INTO stanza VALUES('G1','3','Vater, groß ist Deine Sehnsucht,<br/>Söhne willst für Dich,<br/>Die im Sohn Dich preisend lieben<br/>Ewiglich.<br/>',NULL,45888,3);
INSERT INTO stanza VALUES('G1','4','Das Geheimnis Deiner Liebe<br/>Offenbart hast Du,<br/>So gewinnst Du unsre Liebe<br/>Immerzu.<br/>',NULL,45889,4);
INSERT INTO stanza VALUES('G1','5','So in Christus durch Erlösung<br/>(Mächte ja schlug Er!)<br/>Brachtest Du in neuer Schöpfung<br/>Anbeter!<br/>',NULL,45890,5);
INSERT INTO stanza VALUES('G1','6','Herrlichkeit sei Gott dem Vater,<br/>Herrlichkeit dem Sohn,<br/>Herrlichkeit dem Heil’gen Geiste –<br/>Welch Person!<br/>',NULL,45891,6);
INSERT INTO stanza VALUES('G2','1','Heilig, heilig, heilig, Gott, Du bist allmächtig!<br/>Unser Lied steigt auf zu Dir in alle Ewigkeit;<br/>Heilig, heilig, heilig, mächtig und barmherzig!<br/>Betend wir segnen die Dreieinigkeit!<br/>',NULL,45892,1);
INSERT INTO stanza VALUES('G2','2','Heilig, heilig, heilig! Dich wolln wir anbeten,<br/>Ihre Kronen werfen Himmelsälteste vor Dich;<br/>Cherubim und Seraphim sich vor Dir verbeugen,<br/>Du warst, und bist, und wirst sein ewiglich.<br/>',NULL,45893,2);
INSERT INTO stanza VALUES('G2','3','Heilig, heilig, heilig! Doch Du bist verborgen,<br/>Sünder sehen Deine Herrlichkeit im Finstern nicht,<br/>Du allein bist heilig, Du nur bist vollkommen,<br/>Keiner gleicht Dir in Kraft, in Liebe, Licht.<br/>',NULL,45894,3);
INSERT INTO stanza VALUES('G3','1','Ehre, Ehre sei dem Vater!<br/>Ehre, Ehre sei dem Sohn!<br/>Ehre, Ehre sei dem Geiste!<br/>Gott ist dreieins als Person!<br/>',NULL,45895,1);
INSERT INTO stanza VALUES('G3','chorus','Lobt und preist Ihn! Lobt und preist Ihn!<br/>Lobpreist die Dreieinigkeit!<br/>Gebt Ihm Ehre, gebt Ihm Ehre!<br/>Herrlich ist es wie Sich Gott austeilt!<br/>',NULL,45896,2);
INSERT INTO stanza VALUES('G3','2','Preist den Vater, der geplant hat!<br/>Preist den Sohn, Er hat’s vollbracht!<br/>Preist den Geist, der es zu uns bringt!<br/>Dreieins – in uns Wohnung macht!<br/>',NULL,45897,3);
INSERT INTO stanza VALUES('G4','1','Preist Gott, der stets den Segen mehrt;<br/>Geschöpfe, euren Gott verehrt!<br/>Ihr Himmelsheere singt und preist,<br/>Erhebt den Vater, Sohn und Geist!<br/>',NULL,45898,1);
INSERT INTO stanza VALUES('G4','2','Dem Vater als der Quelle singt,<br/>Dem Sohn als Flusslauf Ehre bringt,<br/>Preist Gott, den Geist, zu uns Er fließt,<br/>Preist Gott, der unser Anteil ist!<br/>',NULL,45899,2);
INSERT INTO stanza VALUES('G5','1','Du, Gott, der ew’ge Vater bist,<br/>Der unerschaffene ICH BIN!<br/>Weit älter als die Alten sind,<br/>Im Anfang warst Du vor Beginn!<br/>',NULL,45900,1);
INSERT INTO stanza VALUES('G5','2','Seit Ewigkeiten bist Du Gott,<br/>Du übersteigst den Raum und Zeit!<br/>Der Anfang bist Du, Ende auch,<br/>Die Fülle aller Ewigkeit!<br/>',NULL,45901,2);
INSERT INTO stanza VALUES('G5','3','Als Quell von allem ewiglich<br/>Bist Du, bevor die Welt begann!<br/>Der Erstling aller, Gott, bist Du,<br/>Sogar dem Anfang gehst voran!<br/>',NULL,45902,3);
INSERT INTO stanza VALUES('G5','4','Das Leben – Du, das immer währt,<br/>Du endest nicht in Ewigkeit!<br/>Du überdauerst alles hier,<br/>Das Höchste übersteigst Du weit!<br/>',NULL,45903,4);
INSERT INTO stanza VALUES('G5','5','Du bist als Alpha Erster und<br/>Als Letzter bist Du Omega!<br/>Von A bis O ganz makellos,<br/>Perfekt, vollkommen immerdar.<br/>',NULL,45904,5);
INSERT INTO stanza VALUES('G5','6','Wir preisen Dich, Du Ewiger,<br/>Denn grenzenlos bist Du allein!<br/>Wie herrlich Deine Fülle ist,<br/>Und so vollkommen ist Dein Sein!<br/>',NULL,45905,6);
INSERT INTO stanza VALUES('G6','1','Du, Vater, bist wahrhaftig Geist,<br/>Erhaben, heilig, rein;<br/>Im Geist und in Wahrhaftigkeit,<br/>Lobpreis Sei Dir allein.<br/>',NULL,45906,1);
INSERT INTO stanza VALUES('G6','2','Du schufst uns, Herr, mit einem Geist,<br/>Dich anzubeten hier;<br/>Ein Echo ist in unserm Geist,<br/>Wir sind ein Geist mit Dir.<br/>',NULL,45907,2);
INSERT INTO stanza VALUES('G6','3','Du, Vater, kamst im Sohn zu uns,<br/>Der Sohn ist jetzt der Geist,<br/>In unsern Geist Du kommen kannst,<br/>Welch Gnade Du beweist!<br/>',NULL,45908,3);
INSERT INTO stanza VALUES('G6','4','Seit ewig ist der Sohn Dein Wort,<br/>Das Geist ist und uns speist;<br/>Der Geist als unser Leben nun<br/>Erneuert unsern Geist.<br/>',NULL,45909,4);
INSERT INTO stanza VALUES('G6','5','Dein Geist lebt jetzt in unserm Geist,<br/>Und wir sind eins mit Dir;<br/>Dein Geist bezeugt mit unserm Geist,<br/>Aus Dir geborn sind wir.<br/>',NULL,45910,5);
INSERT INTO stanza VALUES('G6','6','In allem leitet uns Dein Geist,<br/>Wir folgen Ihm allein;<br/>Ja, geistlich werden wir dadurch,<br/>Und Friede nimmt uns ein.<br/>',NULL,45911,6);
INSERT INTO stanza VALUES('G6','7','In unserm Geist Gebet steigt auf<br/>Und Lob zu Dir erklingt,<br/>Bis unser Geist ist voll befreit,<br/>Und Dich zum Ausdruck bringt.<br/>',NULL,45912,7);
INSERT INTO stanza VALUES('G6','8','Wir preisen, liebster Vater, Dich,<br/>Du bist wahrhaftig Geist;<br/>Im Geist und in Wahrhaftigkeit<br/>Dich unser Herz lobpreist.<br/>',NULL,45913,8);
INSERT INTO stanza VALUES('G7','1','Du, Vater, bist der Lebensquell,<br/>Reich, frei, voll Göttlichkeit!<br/>Aus Dir so rein das Leben quillt<br/>In alle Ewigkeit!<br/>',NULL,45914,1);
INSERT INTO stanza VALUES('G7','2','In Deiner Lieb strömst Du im Sohn<br/>Zur ganzen Menschheit hin;<br/>Als Geist fließt Du nun auch in uns,<br/>Welch Gnade liegt darin!<br/>',NULL,45915,2);
INSERT INTO stanza VALUES('G7','3','Obwohl in Bosheit und in Sünd<br/>Von Dir wir waren fern,<br/>Hast Du uns doch im Sohn erlöst,<br/>Gabst uns Dein Leben gern.<br/>',NULL,45916,3);
INSERT INTO stanza VALUES('G7','4','Obwohl wir Dich missachteten,<br/>Betrübten Deinen Geist,<br/>Kommst Du doch als der Geist zu uns,<br/>Mit Leben uns reich speist.<br/>',NULL,45917,4);
INSERT INTO stanza VALUES('G7','5','Du als der Geist hast Dich im Sohn<br/>Mit uns vermengt, o Herr;<br/>Willst durch Gemeinschaft salben uns,<br/>Und wachsen täglich mehr.<br/>',NULL,45918,5);
INSERT INTO stanza VALUES('G7','6','Die Liebe Gottes, Christi Gnad<br/>Im Geist fließt allezeit;<br/>Er teilt uns Gottes Reichtum aus<br/>In alle Ewigkeit.<br/>',NULL,45919,6);
INSERT INTO stanza VALUES('G7','7','Der Vater, Sohn und Geist – dreieins,<br/>Versorgt uns innerlich;<br/>Von Deiner Liebe singen wir,<br/>Verehrn Dich ewiglich.<br/>',NULL,45920,7);
INSERT INTO stanza VALUES('G8','1','Vater Gott, Du bist der Lebens-Quell.<br/>Durch die Söhne Dich wir sehen,<br/>Die in Deinem Namen stehen;<br/>Vater Gott, Du bist der Lebens-Quell.<br/>',NULL,45921,1);
INSERT INTO stanza VALUES('G8','chorus','Ja, im Leben, ja, im Leben,<br/>Ja, in Deinem Leben sind wir eins;<br/>Ja, im Leben, ja, im Leben,<br/>Ja, in Deinem Leben sind wir eins.<br/>',NULL,45922,2);
INSERT INTO stanza VALUES('G8','2','Danke, Vater, dass Dein heilig Wort<br/>Mit Deiner Natur durchtränkt uns,<br/>Von der Welt es dadurch trennt uns;<br/>Danke Vater, für Dein heilig Wort.<br/>',NULL,45923,3);
INSERT INTO stanza VALUES('G8','chorus','Durch Dein Wort, durch Dein Wort,<br/>Durch Dein Wort, o Vater, sind wir eins;<br/>Durch Dein Wort, durch Dein Wort.<br/>Herr, Dein heiliges Wort macht uns eins.<br/>',NULL,45924,4);
INSERT INTO stanza VALUES('G8','3','Herrlichkeit ist der Dreieine Gott!<br/>Wir die Söhne – welch ein Segen,<br/>Seine Herrlichkeit zu leben!<br/>Herrlichkeit ist der Dreieine Gott!<br/>',NULL,45925,5);
INSERT INTO stanza VALUES('G8','chorus','In der Herrlichkeit, Herrlichkeit,<br/>Wir sind eins in Deiner Herrlichkeit;<br/>in der Herrlichkeit, Herrlichkeit,<br/>Wir sind eins in Deiner Herrlichkeit!<br/>',NULL,45926,6);
INSERT INTO stanza VALUES('G9','1','Du bist Liebe, Du bist Licht, Herr,<br/>Du im Sohn als Leben fließt;<br/>Liebe zeigst, mit Licht erleuchtest,<br/>Leben reich in uns ergießt.<br/>',NULL,45927,1);
INSERT INTO stanza VALUES('G9','chorus','Du bist Liebe und Licht!<br/>Du im Sohn als Leben fließt;<br/>Liebe zeigst, mit Licht erleuchtest,<br/>Leben reich in uns ergießt.<br/>',NULL,45928,2);
INSERT INTO stanza VALUES('G9','2','Liebe spricht von Deinem Wesen,<br/>Was Du tust, dem Licht entspricht;<br/>Liebe – innen, Licht ist außen,<br/>Liebe geht einher mit Licht.<br/>',NULL,45929,3);
INSERT INTO stanza VALUES('G9','3','Gnade zeigt uns Deine Liebe,<br/>Durch die Wahrheit sehn wir Licht;<br/>Wir genießen Dich als Liebe,<br/>Licht zeigt Dich, schenkt klare Sicht.<br/>',NULL,45930,4);
INSERT INTO stanza VALUES('G9','4','Durch die Lieb, die Dich ans Kreuz trieb,<br/>Kam Dein Leben uns zugut;<br/>Und Dein Licht gibt uns die Einsicht,<br/>Nun wir wenden an Dein Blut.<br/>',NULL,45931,5);
INSERT INTO stanza VALUES('G9','5','Deine Liebe bringt uns Leben,<br/>Uns Gemeinschaft gibt mit Dir:<br/>Durch Dein Blut im Licht gereinigt,<br/>In Gemeinschaft leben wir.<br/>',NULL,45932,6);
INSERT INTO stanza VALUES('G9','6','Durch Dein Licht und Blut, das reinigt,<br/>Deine Salbung uns stets führt,<br/>Und Dein Leben voller Liebe,<br/>Uns erfüllt und tief berührt.<br/>',NULL,45933,7);
INSERT INTO stanza VALUES('G9','7','Wir sind Kinder Deiner Liebe,  INSERT INTO stanza VALUES('G9','chorus','Gnade fließt! Wahrheit scheint!<br/>Licht und Liebe offenbar!<br/>Dich wir preisen unaufhörlich,<br/>Licht und Liebe nehmen wahr.<br/>',NULL,45935,9);
INSERT INTO stanza VALUES('G10','1','Du, Vater, bist erhaben,<br/>Erstrahlst in Heiligkeit!<br/>Du bist so unvergleichlich<br/>In alle Ewigkeit!<br/>Was immer diese Menschheit,<br/>Als Heiligstes beschreibt,<br/>Du bist weitaus der Höchste,<br/>Vom Thron Dich nichts vertreibt!<br/>',NULL,45936,1);
INSERT INTO stanza VALUES('G10','2','Nur Du allein bist heilig,<br/>Nicht nur gerecht und rein;<br/>Ja, nicht nur ohne Mangel,<br/>Vollkommen ist Dein Sein.<br/>Denn nichts kann sich Dir nahen,<br/>Noch jemals Dir gleich sein;<br/>Du duldest nichts und niemand,<br/>Der Deinen Platz nimmt ein.<br/>',NULL,45937,2);
INSERT INTO stanza VALUES('G10','3','Vortrefflichster von allen,<br/>Der Lieblichste bist Du,<br/>Und unvergleichlich anders,<br/>Der Edelste dazu.<br/>Gerechtigkeit alleine<br/>In Dir ist absolut;<br/>Wer kann sich mit Dir messen?<br/>Nur Du bist schön und gut.<br/>',NULL,45938,3);
INSERT INTO stanza VALUES('G10','4','Du Deine Heiligkeit gibst,<br/>Die alles übersteigt,<br/>Uns göttliche Natur schenkst,<br/>Was Deine Größe zeigt.<br/>Nun haben wir an Deiner<br/>Erhabenheit auch teil;<br/>Wir folgen Deinem Leben<br/>Zum vollen Wuchs und Heil.<br/>',NULL,45939,4);
INSERT INTO stanza VALUES('G10','5','Wir preisen Dich, o Vater,<br/>Für Deine Heiligkeit,<br/>Erhabene Natur und<br/>Die Unvergleichlichkeit,<br/>Dass Du uns lässt teilhaben<br/>An heiliger Natur;<br/>Sie sondert uns perfekt ab,<br/>Macht uns so rein und pur.<br/>',NULL,45940,5);
INSERT INTO stanza VALUES('G11','1','O Vater, Du bist immergrün<br/>Und Du bist immer neu;<br/>Du bist der Herr, der ewig lebt,<br/>So frisch wie Morgentau.<br/>',NULL,45941,1);
INSERT INTO stanza VALUES('G11','chorus','Du, Vater, änderst Dich niemals,<br/>Und Du wirst niemals alt;<br/>Durch alle Zeiten immer frisch<br/>Stets Deine Neuheit strahlt.<br/>',NULL,45942,2);
INSERT INTO stanza VALUES('G11','2','Nur Du bist „neu“ und ohne Dich<br/>Ist alles alt, verfahrn;<br/>Jedoch mit Dir bleibt alles frisch<br/>Nach noch so vielen Jahrn.<br/>',NULL,45943,3);
INSERT INTO stanza VALUES('G11','3','Ein jeder Segen, den Du gibst,<br/>Birgt Deine Neuheit – Dich;<br/>Neu Deine Wege, neu Dein<br/>Bund, Sie bleiben ewiglich.<br/>',NULL,45944,4);
INSERT INTO stanza VALUES('G11','4','Wir sind die neue Schöpfung jetzt,<br/>Denn neu sind Herz und Geist;<br/>Doch täglich Du erneuerst uns,<br/>Mit neuem Leben speist.<br/>',NULL,45945,5);
INSERT INTO stanza VALUES('G11','5','Die Erde, Himmel und die Stadt,<br/>Sie werden alle neu;<br/>In jedem Monat neue Frucht<br/>Der Lebensbaum bringt treu.<br/>',NULL,45946,6);
INSERT INTO stanza VALUES('G11','6','O Vater, ewig neu bist Du,<br/>In Dir ist alles neu;<br/>Und ewig neu ist unser Lied,<br/>Wir bringen’s Dir stets treu.<br/>',NULL,45947,7);
INSERT INTO stanza VALUES('G12','1','Mein Vater Gott, wenn ich die ganze Schöpfung,<br/>Wunder des Himmels und der Erd betracht,<br/>Großes und Kleines, ’s übersteigt die Zählung,<br/>All Deine Kraft hier vielfach sichtbar macht,<br/>',NULL,45948,1);
INSERT INTO stanza VALUES('G12','chorus','Dann jauchzt mein Herz Dir zu und preist und lobt,<br/>Wie wunderbar! Wie groß bist Du!<br/>Dies sing ich Dir für ewig, Vater Gott,<br/>Wie wunderbar! Wie groß bist Du!<br/>',NULL,45949,2);
INSERT INTO stanza VALUES('G12','2','Wenn ich genieß die Gnade Deiner Rettung<br/>Und seh, wie Du uns hast gesandt den Sohn,<br/>Durch Seinen Tod sind wir die neue Schöpfung,<br/>So dass Dein Leben nun zum Ausdruck kommt,<br/>',NULL,45950,3);
INSERT INTO stanza VALUES('G12','3','Wenn ich betrachte, wie in der Gemeinde<br/>Du in Millionen Menschen Leben bist,<br/>Wie sie zusammen bilden Deine Wohnung,<br/>Und Deine Fülle nun aus ihnen fließt,<br/>',NULL,45951,4);
INSERT INTO stanza VALUES('G12','4','Wenn ich erwart die Fülle der Zeitalter,<br/>Und mich schon freu aufs Neu Jerusalem,<br/>Und auf die neuen Himmel, neue Erde,<br/>Wo Du zum Ausdruck kommst in alledem,<br/>',NULL,45952,5);
INSERT INTO stanza VALUES('G13','1','Wie treu und wie vertrauenswert,<br/>Mein Vater Gott, bist Du!<br/>Von Deiner Treue spricht so reich<br/>Die Schöpfung immerzu.<br/>',NULL,45953,1);
INSERT INTO stanza VALUES('G13','chorus','Wie standfest Deine Treue ist!<br/>Für sie lobpreis ich Dich;<br/>Im Himmel ist sie angelegt,<br/>Steht ewig fest für mich.<br/>',NULL,45954,2);
INSERT INTO stanza VALUES('G13','2','Kein Schattenwechsel ist bei Dir,<br/>Du niemals änderst Dich;<br/>Wie Du einst warst und jetzt noch bist,<br/>Bleibst Du auch ewiglich.<br/>',NULL,45955,3);
INSERT INTO stanza VALUES('G13','3','Dein Wort, wie Du, so sicher ist,<br/>Gewiss wird’s nie vergehn;<br/>Wenn Himmel und die Erde fliehn,<br/>Dein Wort bleibt stets bestehn.<br/>',NULL,45956,4);
INSERT INTO stanza VALUES('G13','4','Du ohne Reue Gaben gibst,<br/>Berufst in Ewigkeit;<br/>Für ewig Deine Gnade ist<br/>Und die Barmherzigkeit.<br/>',NULL,45957,5);
INSERT INTO stanza VALUES('G13','5','Dein Wort mit Deiner Treue ist<br/>Die Sicherheit für mich:<br/>Mit ihm und Deiner Rettung, Herr,<br/>Gewissheit habe ich.<br/>',NULL,45958,6);
INSERT INTO stanza VALUES('G13','6','So treu bist Du, wenn schwach ich bin,<br/>Dir nicht vertrau sofort;<br/>Dich Selbst Du nicht verleugnen kannst;<br/>Denn Du erfüllst Dein Wort.<br/>',NULL,45959,7);
INSERT INTO stanza VALUES('G13','7','Wie treu bist Du, der uns berufst,<br/>Und Du wirst es auch tun;<br/>Von Deiner Treue nähr ich mich,<br/>In Dir, Herr, kann ich ruhn.<br/>',NULL,45960,8);
INSERT INTO stanza VALUES('G13','8','Der Regenbogen um den Thron<br/>Tut Deine Treue kund:<br/>Von ihr spricht in der heil’gen Stadt<br/>Für ewig jeder Mund.<br/>',NULL,45961,9);
INSERT INTO stanza VALUES('G14','1','Vater Gott, wir lieben Dich ja<br/>Wegen der Gerechtigkeit;<br/>Nun sind wir gerecht in Christus,<br/>Das Gewissen ist befreit.<br/>Unser Stand ist Dein Gerechtsein,<br/>Darauf stehn wir immer hier;<br/>Nichts kann es ins Wanken bringen,<br/>Felsenfest ist es in Dir.<br/>',NULL,45962,1);
INSERT INTO stanza VALUES('G14','2','Du warfst unsre Sünd auf Jesus,<br/>Hast gerichtet Ihn gerecht,<br/>Er hat Dein Gesetz, so heilig,<br/>Ganz erfüllt als treuer Knecht.<br/>Er hat Dich vollauf entschädigt<br/>Und den Preis bezahlt am Pfahl;<br/>Könntest Du, gerechter Vater,<br/>Fordern ihn von uns nochmal?<br/>',NULL,45963,2);
INSERT INTO stanza VALUES('G14','3','Vater, Du hast angenommen<br/>Jesus, unseren Ersatz;<br/>Den Gerechten hast gerichtet<br/>An der Ungerechten Platz.<br/>Als Beweis vollkomm''nen Rechtes<br/>Sitzt zu Deiner Rechten Er:<br/>Jesus nur stellt Dich zufrieden<br/>Und Gerechtigkeit, o Herr.<br/>',NULL,45964,3);
INSERT INTO stanza VALUES('G14','4','Vater, durch das Blut von Jesus<br/>Schenkst Du uns Gerechtigkeit;<br/>Diese schützt uns, nichts erschüttert<br/>Unsere Standfestigkeit.<br/>Zur Gerechtigkeit wir wurden,<br/>Keiner richtet uns seitdem!<br/>Ewig wolln wir dies bezeugen<br/>Bis ins Neu’ Jerusalem.<br/>',NULL,45965,4);
INSERT INTO stanza VALUES('G15','1','Dir, Vater, Preis sei allezeit,<br/>Denn Du Selbst bist Gerechtigkeit,<br/>Ja, dies bezeugen wir!<br/>Du Richter aller Menschen bist,<br/>Nie ungerecht Dein Urteil ist,<br/>Nichts Falsches ist in Dir!<br/>',NULL,45966,1);
INSERT INTO stanza VALUES('G15','2','Gerechter Vater, Heiliger,<br/>Dein Thron steht auf Gerechtigkeit,<br/>Ein festes Fundament.<br/>Weil Du gerecht bist und so wahr,<br/>Herrscht Christi Gnade immerdar,<br/>Uns Frieden zuerkennt.<br/>',NULL,45967,2);
INSERT INTO stanza VALUES('G15','3','Weil Du gerecht bist allezeit,<br/>Zu sterben war Dein Sohn bereit,<br/>Erlösung reicht Er dar;<br/>Wer die Erlösung froh nimmt an,<br/>Der wird gerecht nach Deinem Plan,<br/>Den rettest Du fürwahr.<br/>',NULL,45968,3);
INSERT INTO stanza VALUES('G15','4','Gerechtigkeit gezeigt hast Du,<br/>Denn Du die Sünden decktest zu<br/>Dem Volk im Altertum;<br/>Und heut durch die Gerechtigkeit<br/>Vergibst Du Sünden allezeit,<br/>Sünder gehn frei aus nun.<br/>',NULL,45969,4);
INSERT INTO stanza VALUES('G15','5','Du über jeden hältst Gericht,<br/>Gerechtigkeit übst streng und schlicht<br/>In Christus, Deinem Sohn.<br/>Du gibst uns doch Standfestigkeit,<br/>So tun wir kund Gerechtigkeit<br/>Und Gnade, unsren Lohn.<br/>',NULL,45970,5);
INSERT INTO stanza VALUES('G15','6','Gerechtigkeit erfüllt Dein Reich,<br/>Mit Frieden baust Du nun zugleich<br/>Dein Haus in Harmonie;<br/>Sind Himmel und die Erde neu,<br/>Gerechtigkeit in Dir herrscht treu,<br/>Verheißen hast Du sie.<br/>',NULL,45971,6);
INSERT INTO stanza VALUES('G16','1','Heil’ger Vater, unser Lobpreis<br/>Nun zu Dir in Ehrfurcht fließt:<br/>Du bist heilig und erhaben,<br/>Nur Dein Name heilig ist.<br/>',NULL,45972,1);
INSERT INTO stanza VALUES('G16','2','So gerecht sind Deine Wege,<br/>Oh, wie liebt Dein Herz uns sehr!<br/>Deine heilige Natur uns<br/>Christus teilt aus mehr und mehr.<br/>',NULL,45973,2);
INSERT INTO stanza VALUES('G16','3','Ewig hast Du uns geheiligt<br/>Durch des Herrn kostbares Blut,<br/>Du hast Sünder abgesondert<br/>Durch die Wahrheit, durch das Wort.<br/>',NULL,45974,3);
INSERT INTO stanza VALUES('G16','4','Du stellst uns durch Deinen Geist, Herr,<br/>Heilig hin vor Dich allein;<br/>Unser Geist samt Leib und Seele<br/>Ganz geheiligt werden sein.<br/>',NULL,45975,4);
INSERT INTO stanza VALUES('G16','5','Heilig ist das Leben Jesu,<br/>Das Du uns durch Gnade gibst;<br/>Nun an Deiner Heiligkeit wir<br/>Haben teil, weil Du uns liebst.<br/>',NULL,45976,5);
INSERT INTO stanza VALUES('G16','6','In der neuen Stadt, so heilig,<br/>Sind wir völlig eins mit Dir,<br/>Eins mit Deiner Heiligkeit auch –<br/>„Du bist heilig“, preisen wir.<br/>',NULL,45977,6);
INSERT INTO stanza VALUES('G17','1','In Deiner Weisheit, Vater Gott,<br/>Nach Deinem eignen Willn<br/>Den Vorsatz fasstest Du, dass Dein<br/>Sohn alles soll erfülln.<br/>',NULL,45978,1);
INSERT INTO stanza VALUES('G17','chorus','Wie tief doch Deine Weisheit ist,<br/>So reich und unfassbar!<br/>Doch Gnade und Barmherzigkeit<br/>Gewährt sie immerdar!<br/>',NULL,45979,2);
INSERT INTO stanza VALUES('G17','2','Du machtest alles wunderbar,<br/>Oh, wer kennt Deinen Sinn?<br/>Ja, alles ist von Dir, durch Dich,<br/>Zu Dir führt alles hin.<br/>',NULL,45980,3);
INSERT INTO stanza VALUES('G17','3','In Sünde schließt sie alle ein,<br/>Erbarmen zeigt sich gern,<br/>Dass niemand sich selbst rühmen kann,<br/>Wir rühmen unsern Herrn.<br/>',NULL,45981,4);
INSERT INTO stanza VALUES('G17','4','So weise durch das Kreuz hast Du<br/>Erlösung einst vollbracht,<br/>In unsrem Geist lebst Du, o Herr,<br/>Als Schatz uns jetzt vermacht.<br/>',NULL,45982,5);
INSERT INTO stanza VALUES('G17','5','Die Fürsten in den Himmeln sehn<br/>Durch die Gemeinde klar<br/>Die Weisheit Gottes mannigfach;<br/>Sie ist so wunderbar!<br/>',NULL,45983,6);
INSERT INTO stanza VALUES('G17','6','Im Neu’n Jerusalem wolln wir<br/>In Gnade rühmen Dich:<br/>Dort stellst Du Deine Weisheit aus,<br/>Zu sehen ewiglich.<br/>',NULL,45984,7);
INSERT INTO stanza VALUES('G18','1','Welch gnadenvolle Weisheit liegt<br/>Im Sohn, der Christus heißt!<br/>Du machtest Ihn zur Weisheit uns,<br/>Den Gnadenweg uns weist.<br/>',NULL,45985,1);
INSERT INTO stanza VALUES('G18','2','Was Du geplant hast, ist in Ihm,<br/>In Ihm die Gnade fließt;<br/>Welch Weisheit haben wir in Ihm,<br/>Lobpreis Du würdig bist!<br/>',NULL,45986,2);
INSERT INTO stanza VALUES('G18','3','Gerecht sind wir, denn Du schenkst uns<br/>Ihn als Gerechtigkeit;<br/>Er heiligt uns in Sich, denn Er<br/>Ist unsre Heiligkeit.<br/>',NULL,45987,3);
INSERT INTO stanza VALUES('G18','4','Er ist Erlösung auch für uns,<br/>Genau nach Deinem Plan,<br/>Damit wir werden ganz erlöst<br/>Als ein vollkomm’ner Mann.<br/>',NULL,45988,4);
INSERT INTO stanza VALUES('G18','5','So ist Er Deine Weisheit, Herr,<br/>Deiner Ökonomie:<br/>Für Ihn, Dich Vater, preisen wir,<br/>Dich ehrn in Harmonie.<br/>',NULL,45989,5);
INSERT INTO stanza VALUES('G18','6','In Ihm wir Deine Weisheit sehn,<br/>So hoch, so tief, so weit;<br/>Zeig sie uns mehr aus Deiner Sicht<br/>Jetzt und in Ewigkeit.<br/>(Die letzten beiden Zeilen jeder Strophe wiederholen)<br/>',NULL,45990,6);
INSERT INTO stanza VALUES('G19','1','Du, Vater, schenktest uns Barmherzigkeit<br/>Nach Deinem Plan;<br/>Sünder als Söhne nimmst Du ganz bereit<br/>In Liebe an.<br/>Gefäße der Barmherzigkeit sind wir;<br/>Zu Deiner Ehre stehen wir vor Dir.<br/>',NULL,45991,1);
INSERT INTO stanza VALUES('G19','2','„Nicht Opfer, sondern wer barmherzig ist”,<br/>Gefällt Dir sehr.<br/>Für Deine Gunst, dass Du barmherzig bist,<br/>Sei Dir die Ehr.<br/>‘s liegt nicht an dem, der will und läuft allzeit,<br/>Sondern dass Du erzeigst Barmherzigkeit.<br/>',NULL,45992,2);
INSERT INTO stanza VALUES('G19','3','Barmherzigkeit mit Liebe und mit Gnad<br/>Empfingen wir;<br/>In Deine Gegenwart führt sie als Pfad,<br/>Bewahr uns hier.<br/>Danke, o Herr, für die Barmherzigkeit,<br/>Dir singen wir in alle Ewigkeit.<br/>',NULL,45993,3);
INSERT INTO stanza VALUES('G20','1','Gott, Du mit Barmherzigkeit kommst<br/>Uns entgegen allezeit!<br/>Sie ist reich; wenn wir versagen,<br/>Steht sie stets für uns bereit.<br/>Dich wir lieben! Dich wir lieben!<br/>Du erweist Barmherzigkeit!<br/>',NULL,45994,1);
INSERT INTO stanza VALUES('G20','2','Sie reicht weit und tief hinunter,<br/>Oh, wie sehr sie uns gefällt!<br/>Sie erreichte uns, die Sünder,<br/>Uns auf ewig sicher hält.<br/>Wie barmherzig! Wie barmherzig!<br/>Nichts von Dir uns je abhält.<br/>',NULL,45995,2);
INSERT INTO stanza VALUES('G20','3','Wir sind dankbar, denn so reich ist,<br/>Vater, die Barmherzigkeit!<br/>Du schenkst mit ihr die Erlösung,<br/>Deine Güte reicht so weit.<br/>Ohne diese, ohne diese<br/>Stünde Gunst für uns bereit?<br/>',NULL,45996,3);
INSERT INTO stanza VALUES('G20','4','Oh, wie die Barmherzigkeit doch<br/>Süß ist, sanft und unfassbar!<br/>Sie versorgt mit Deiner Güte<br/>Und Geduld uns wunderbar.<br/>Sie wir schätzen, sie wir schätzen,<br/>Nichts ihr gleichkommt immerdar.<br/>',NULL,45997,4);
INSERT INTO stanza VALUES('G20','5','Vater, wir genießen sie nun,<br/>Frisch ist die Barmherzigkeit;<br/>Sie ist wie der Tau am Morgen,<br/>Immer neu für uns bereit.<br/>Oh, wie köstlich! oh, wie köstlich!<br/>Dir sei Preis und Herrlichkeit.<br/>',NULL,45998,5);
INSERT INTO stanza VALUES('G20','6','Vater, Dich wir endlos preisen,<br/>Weit ist die Barmherzigkeit;<br/>Deine Gunst und Deine Gnade<br/>Stellt sie uns ständig bereit.<br/>Ihr vertraun wir, ihr vertraun wir,<br/>Sie gewährt uns Sicherheit.<br/>',NULL,45999,6);
INSERT INTO stanza VALUES('G21','1','Die Liebe Gottes ist weit größer<br/>Als Stift, noch Zunge uns verrät,<br/>Den höchsten Stern sie weit umschließt,<br/>Ins tiefste Elend niedergeht.<br/>Welch Liebe, Licht! – als Gott verspricht<br/>Den Sohn beim Sündenfall!<br/>Und Er vergibt, den Sünder liebt,<br/>Versöhnte uns am Pfahl.<br/>',NULL,46000,1);
INSERT INTO stanza VALUES('G21','chorus','O Liebe Gottes, reich und rein!<br/>So stark und unendlich!<br/>Engel und Heilige, stimmt ein!<br/>Wir preisen ewiglich.<br/>',NULL,46001,2);
INSERT INTO stanza VALUES('G21','2','Die düstren Zeiten werden enden,<br/>Und jedes Königreich vergeht;<br/>Wer jetzt nicht betet, wird sich wenden,<br/>Zu Bergen und zu Hügeln fleht.<br/>Welch Liebe! Weit, so hoch und breit!<br/>So stark und unendlich!<br/>Welch reiche Gnad Gott für uns hat!<br/>Wir singen’s ewiglich.<br/>',NULL,46002,3);
INSERT INTO stanza VALUES('G21','3','Bestünd aus Tinte jedes Meer<br/>Und wärn die Himmel aus Papier,<br/>Käm jeder Halm als Stift daher,<br/>Wär jeder Mensch ein Schreiber hier,<br/>Wer sie beschreibt, stets dabei bleibt,<br/>Austrocknen würd das Meer,<br/>Die Niederschrift noch übertrifft<br/>Die Himmelsweite sehr.<br/>',NULL,46003,4);
INSERT INTO stanza VALUES('G22','1','Welch Liebe schenktest Du uns, Herr!<br/>Von Herzen Dank sei Dir;<br/>Für das, was Du, o Vater, bist,<br/>Anbetung bringen wir.<br/>',NULL,46004,1);
INSERT INTO stanza VALUES('G22','2','Dein Herz hast Du uns offenbart<br/>Und uns Dein Ziel enthüllt;<br/>Im Sohn bist Du erschienen, Herr,<br/>Der Deinen Plan erfüllt.<br/>',NULL,46005,2);
INSERT INTO stanza VALUES('G22','3','Du gabst Dein''n Sohn, den Du so liebst,<br/>Für uns in Liebe hin;<br/>Zu Deinen Söhnen machst Du uns,<br/>Zu Erben willst erziehn.<br/>',NULL,46006,3);
INSERT INTO stanza VALUES('G22','4','Dein Leben haben wir durch Ihn,<br/>Du unser Vater bist;<br/>Du Selbst samt der Natur von Dir<br/>In uns hinein jetzt fließt.<br/>',NULL,46007,4);
INSERT INTO stanza VALUES('G22','5','Dein Geist in unsern kam hinein,<br/>Wir rufen „Abba“ froh;<br/>Vom Geist geborn, versiegelt auch,<br/>Willst uns umwandeln so.<br/>',NULL,46008,5);
INSERT INTO stanza VALUES('G22','6','Die Söhne in die Herrlichkeit<br/>Zu bringen ist Dein Plan;<br/>Dem Bild von Deinem Sohn sind sie<br/>Ganz gleichgestaltet dann.<br/>',NULL,46009,6);
INSERT INTO stanza VALUES('G22','7','Durch Dein Umwandlungswerk, o Herr,<br/>Bringst Du uns treu voran,<br/>Von Herrlichkeit zu Herrlichkeit,<br/>Bis Dein Werk ist getan.<br/>',NULL,46010,7);
INSERT INTO stanza VALUES('G22','8','Für Deine Liebe danken wir<br/>Dir, Vater, allezeit;<br/>Wir beten an und preisen Dich<br/>In alle Ewigkeit.<br/>',NULL,46011,8);
INSERT INTO stanza VALUES('G23','1','Wir beten Dich, o Vater, an,<br/>Wie herrlich ist''s, dass Du uns liebst!<br/>Was zählt für Dich der Mensch, o Herr,<br/>Dass Du ihm Deine Gnade gibst?<br/>',NULL,46012,1);
INSERT INTO stanza VALUES('G23','2','Dein Herzenswunsch ist wunderbar,<br/>Der Mensch soll Deinem Bild gleich sein;<br/>Mit Deinem Leben und Natur<br/>Füllst ihn und nimmst ihn völlig ein.<br/>',NULL,46013,2);
INSERT INTO stanza VALUES('G23','3','Den Mensch schufst Du in Deinem Bild,<br/>Und ihn zur Herrschaft eingesetzt;<br/>Als Leben kamst Du hin zu ihm,<br/>Dass er durch Dich lebt bis zuletzt.<br/>',NULL,46014,3);
INSERT INTO stanza VALUES('G23','4','In ihn hinein zu kommen Du<br/>Begehrst, mit ihm vermengst Du Dich;<br/>Du wandelst um und baust ihn auf,<br/>Zu Deiner Wohnung ewiglich.<br/>',NULL,46015,4);
INSERT INTO stanza VALUES('G23','5','Der Mensch fiel, doch Du hieltest fest<br/>An Deinem Vorsatz, gingst voran;<br/>Erlösung brachte ihn zurück,<br/>Welch große Weisheit zeigt Dein Plan.<br/>',NULL,46016,5);
INSERT INTO stanza VALUES('G23','6','In Christus sichtbar wurdest Du,<br/>Er auferstand, uns machte frei;<br/>Als Geist kamst Du in uns hinein<br/>Und Gnade gabst Du uns dabei.<br/>',NULL,46017,6);
INSERT INTO stanza VALUES('G23','7','Mein Geist ist Deine Wohnung, Herr,<br/>Dein Thron der Gnade fest dort steht;<br/>Wir wollen hier, in unsrem Geist,<br/>Den Weihrauch opfern durch Gebet.<br/>',NULL,46018,7);
INSERT INTO stanza VALUES('G23','8','Solch Gnade gleicht dem reinen Strom,<br/>Vom Thron der Gnade fließt sie aus;<br/>Sie wandelt um und baut uns auf<br/>Zu Deiner Wohnung, Deinem Haus.<br/>',NULL,46019,8);
INSERT INTO stanza VALUES('G23','9','Von Deiner Gnade trinken wir,<br/>Wir schätzen diese Gabe sehr;<br/>Welch große Liebe Du erweist!<br/>Wir beten Dich im Geist an, Herr.<br/>',NULL,46020,9);
INSERT INTO stanza VALUES('G24','1','Vater, lange vor der Schöpfung<br/>Hast Du uns in Lieb erwählt;<br/>Diese Liebe, tief und innig,<br/>Uns zu Christus zieht und drängt,<br/>Sie bewahrt uns, sie bewahrt uns,<br/>Fest in Christus sie uns hält.<br/>Fest in Christus sie uns hält.<br/>',NULL,46021,1);
INSERT INTO stanza VALUES('G24','2','Mag die Welt die Bräuche ändern,<br/>Dennoch ewig gleich bleibt Gott,<br/>Und Sein Bund und Sein Erbarmen<br/>Werden bleiben immerfort.<br/>Gottes Kinder, Gottes Kinder<br/>Seinen Namen ewig preist!<br/>Seinen Namen ewig preist!<br/>',NULL,46022,2);
INSERT INTO stanza VALUES('G24','3','Sein Erbarmen, das mich suchte,<br/>Ist mein Ruhm so lang ich leb;<br/>In Barmherzigkeit bewegt Er<br/>Meinen Willen, meinen Weg.<br/>Gott uns liebte, Gott uns liebte,<br/>Dass Er Seinen Sohn gab hin.<br/>Dass Er Seinen Sohn gab hin.<br/>',NULL,46023,3);
INSERT INTO stanza VALUES('G24','4','Liebster Vater, Dich wir preisen,<br/>Deine Liebe und Person;<br/>Dir wir singen ohne Ende<br/>Bis wir treffen Deinen Sohn.<br/>Dir sei Ehre, Dir sei Ehre,<br/>Unsrem Gott und auch dem Lamm.<br/>Unsrem Gott und auch dem Lamm.<br/>',NULL,46024,4);
INSERT INTO stanza VALUES('G25','1','Vater, Deine Liebe kannt'' uns<br/>Lange vor der Schöpfungszeit:<br/>Sie zog uns so stark zu Jesus,<br/>Drängte sanft mit Lieblichkeit;<br/>Sie bewahrt uns, sie bewahrt uns,<br/>Jetzt und bis in Ewigkeit,<br/>Jetzt und bis in Ewigkeit.<br/>',NULL,46025,1);
INSERT INTO stanza VALUES('G25','2','Deine Liebe nie sich ändert,<br/>Oh, wie reich sie sich ergießt!<br/>Sie hält uns in Deiner Ruhe,<br/>Wie ein Band sie uns umschließt.<br/>Gott und Vater, Gott und Vater,<br/>Hin zu Dir Anbetung fließt,<br/>Hin zu Dir Anbetung fließt.<br/>',NULL,46026,2);
INSERT INTO stanza VALUES('G25','3','Gott der Liebe, Deine Gnade<br/>Tun wir kund in jedem Land,<br/>Bis wir unsre Krone abtun,<br/>Ewiglich Dich beten an;<br/>Preis, Anbetung; Preis, Anbetung,<br/>Sei dem Vater und dem Lamm!<br/>Sei dem Vater und dem Lamm!<br/>',NULL,46027,3);
INSERT INTO stanza VALUES('G26','1','Wir preisen Dich, o Vater,<br/>Als Söhne stehen wir<br/>Zu Deinem Wohlgefallen<br/>In Gnade nun vor Dir:<br/>Für Herrlichkeit bestimmt sind<br/>Wir Söhne – lange schon –<br/>In Christus, dem Geliebten,<br/>Der über allem thront.<br/>',NULL,46028,1);
INSERT INTO stanza VALUES('G26','2','Wer sonst als Du, o Vater,<br/>Hat uns im Sohn erwählt,<br/>Und mit dem Geist gesegnet,<br/>Zu Söhnen uns gezählt?<br/>Bald sind wir dann mit Christus<br/>In Seiner Herrlichkeit;<br/>Und strahlen hell Sein Bild aus<br/>In alle Ewigkeit!<br/>',NULL,46029,2);
INSERT INTO stanza VALUES('G27','1','Dem Vater sei Ehre, der Großes getan,<br/>Er liebte die Welt, nahm der Sünder Sich an,<br/>Er gab Seinen Sohn, der Erlösung vollbracht,<br/>Hat allen das Lebenstor weit aufgemacht.<br/>',NULL,46030,1);
INSERT INTO stanza VALUES('G27','chorus','Preist den Herrn, preist den Herrn,<br/>Erde hör diesen Schall;<br/>Preist den Herrn, preist den Herrn,<br/>Völker, preist überall;<br/>Oh, kommt zu dem Vater, in Jesus wir nahn,<br/>Gebt Ihm alle Ehre, der Großes getan!<br/>',NULL,46031,2);
INSERT INTO stanza VALUES('G27','2','Vollkomm''ne Erlösung, erkauft durch Sein Blut,<br/>Wer glaubt, dem kommt Gottes Verheißung zugut;<br/>Der ärgste der Sünder, der glaubt, Ihm anhängt,<br/>Sofort die Vergebung von Jesus empfängt.<br/>',NULL,46032,3);
INSERT INTO stanza VALUES('G27','3','Gelehrt hat Er Großes, und Großes getan,<br/>In Jesus, dem Sohn, wahre Freude begann;<br/>Doch reiner und höher und größer wird sein<br/>Die Freude, Entzückung, wenn Jesus erscheint.<br/>',NULL,46033,4);
INSERT INTO stanza VALUES('G28','1','O Gott, Preis sei Dir<br/>Für den Sohn Deiner Lieb,<br/>Für den Retter, der starb,<br/>Der im Himmel jetzt ist.<br/>',NULL,46034,1);
INSERT INTO stanza VALUES('G28','chorus','Halleluja, Dir sei Ehre,<br/>Halleluja! Amen;<br/>Halleluja! Dir sei Ehre,<br/>Gott Vater, Amen.<br/>',NULL,46035,2);
INSERT INTO stanza VALUES('G28','2','O Gott, preis sei Dir<br/>Für den Geist ew''gen Lichts,<br/>Der uns zeigte den Retter,<br/>Die Nacht macht zunicht.<br/>',NULL,46036,3);
INSERT INTO stanza VALUES('G28','3','Die Ehre sei Dir,<br/>Dass Du, Vater, uns liebst,<br/>Denn durch Jesu Erlösung<br/>Du Leben uns gibst.<br/>',NULL,46037,4);
INSERT INTO stanza VALUES('G28','4','Wir preisen Dich neu,<br/>Voller Liebe sind wir,<br/>Jedes Herz ist entzündet<br/>Mit Feuer von Dir.<br/>',NULL,46038,5);
INSERT INTO stanza VALUES('G29','1','Du, Gott, hast eingeladen:<br/>Den Sohn wir schauen an,<br/>Stets tat Er Deinen Willen,<br/>Erfüllte Deinen Plan;<br/>Er ist Dein Schatz, so kostbar –<br/>Dein Schoß gab Ihn uns hin,<br/>Die Liebe hat gerettet<br/>Und uns durch Ihn verziehn.<br/>',NULL,46039,1);
INSERT INTO stanza VALUES('G29','2','O Vater des Erbarmens!<br/>Im Namen Christi ist<br/>Die wunderbarste Hoffnung,<br/>Welch Erbteil uns zufließt:<br/>In Deinem wachen Ohr klingt<br/>Sein Name süß allzeit,<br/>Befreit hat Er uns völlig<br/>Von Schuld, von Furcht und Streit.<br/>',NULL,46040,2);
INSERT INTO stanza VALUES('G29','3','Der Sünder bangt und zittert:<br/>„Wird Gott vergeben mir?“<br/>Doch Er bezahlte alles,<br/>Die Schuld erließ Er dir.<br/>Nichts sonst kann uns befreien,<br/>Die Seele setzen frei,<br/>Der Tod des Sohnes Gottes<br/>Bricht Ketten ganz entzwei.<br/>',NULL,46041,3);
INSERT INTO stanza VALUES('G29','4','Kein Zorn in Gottes Herzen<br/>Verurteilt den, der glaubt;<br/>Durch Seine große Liebe,<br/>Wird alle Furcht geraubt;<br/>Den Sohn, der heimkehrt, küsst Er,<br/>Schenkt ihm Sein bestes Kleid;<br/>Ja, Seine Liebe weist ab<br/>All unsre Ängstlichkeit.<br/>',NULL,46042,4);
INSERT INTO stanza VALUES('G30','1','Vater, Dein lieber Sohn führt unser Lob,<br/>Nachdem das Fest ist fertig und vorbei;<br/>Wie innig Dir der Lobpreis, den Er führt!<br/>Und Sein Lob mit anstimmend, sind wir eins.<br/>',NULL,46043,1);
INSERT INTO stanza VALUES('G30','2','Vater, Dein Wesensgut genügt uns ganz,<br/>So suchen wir nun keine mindre Lieb;<br/>Seitdem Du uns Dein maßlos Leben gabst,<br/>Bist Du uns wahr geworden und so lieb.<br/>',NULL,46044,2);
INSERT INTO stanza VALUES('G30','3','Vater der Liebe, unsre Lieb zu Dir<br/>Wächst, übersteigend jedes Erdenband,<br/>In Deine Liebe lenkst Du unser Herz,<br/>Wo wir zutiefst Zufriedenstellung fand''.<br/>',NULL,46045,3);
INSERT INTO stanza VALUES('G30','4','Vater, zusammen mit dem lieben Sohn,<br/>Loben wir Dich mit Freude noch einmal,<br/>Freudig genießen Deine heil''ge Lieb,<br/>Schmecken als Söhne Deinen süßen Nam.<br/>',NULL,46046,4);
INSERT INTO stanza VALUES('G31','1','Vater, als Söhne nahen wir uns Dir,<br/>Zu Dir Du riefst;<br/>Heilige Freiheit, Liebe spüren wir<br/>Im Geist zutiefst.<br/>Herrlich! Wie Christus dürfen viele sein,<br/>Dies freut Dein Herz und nimmt''s für ewig ein.<br/>',NULL,46047,1);
INSERT INTO stanza VALUES('G31','2','Wir haben teil an Christus allezeit,<br/>Du Gnad uns gibst;<br/>Er füllt Dein Herz, ist Deine Herrlichkeit,<br/>Weil Du Ihn liebst.<br/>Wir sehen Ihn in Deiner Gegenwart,<br/>Welch Liebe fließt auf wunderbare Art!<br/>',NULL,46048,2);
INSERT INTO stanza VALUES('G31','3','Hier singt Er, Vater, freudig Dir allein<br/>Und preist Dich sehr;<br/>So viele Söhne stimmen herzlich ein,<br/>Zu Deiner Ehr.<br/>Wir Preisen, Höchster, Dich in Harmonie<br/>Für Deine Liebe und Ökonomie.<br/>',NULL,46049,3);
INSERT INTO stanza VALUES('G32','1','Vater, ein Lied der Freude Dir wir singen<br/>In der Gemeind,<br/>In Deiner Gegenwart wir Lob Dir bringen,<br/>Ja, Dir allein;<br/>Du brachtest uns durch Gnade hin zu Dir,<br/>Den Platz mit Deinem Sohn nun teilen wir.<br/>',NULL,46050,1);
INSERT INTO stanza VALUES('G32','2','Welch tiefe Freude reich erfüllt den Ort,<br/>Wo Liebe wohnt!<br/>Ja, Deine Liebe sehn wir, Vater Gott,<br/>In Deinem Sohn;<br/>Er führt den Lobpreis in heiliger Ruh,<br/>In Liebe segnest Du uns immerzu.<br/>',NULL,46051,2);
INSERT INTO stanza VALUES('G32','3','Er führt das Lob! Wie kostbar ist es Dir,<br/>Was Er Dir singt!<br/>Wie nah und kostbar sind durch Ihn auch wir,<br/>Die Er Dir bringt!<br/>Er teilt Sein''n Platz mit uns nach Deinem Plan;<br/>Du liebtest Ihn, bevor die Welt begann.<br/>',NULL,46052,3);
INSERT INTO stanza VALUES('G33','1','Du, liebster Herr, bist Gottes Wort,<br/>Sein wahrer Sohn bist Du;<br/>Du bist fürwahr Sein heil''ges Bild,<br/>Mit Ihm eins immerzu.<br/>',NULL,46053,1);
INSERT INTO stanza VALUES('G33','2','Du Selbst bist auch der wahre Gott,<br/>Denn Du verkörperst Ihn;<br/>In Dir macht Gott Sich sichtbar hier,<br/>Wir sehen Ihn forthin.<br/>',NULL,46054,2);
INSERT INTO stanza VALUES('G33','3','Ausstrahlung Seiner Herrlichkeit,<br/>Auf uns scheint Gott durch Dich;<br/>Das Abbild Seines Wesens, Du<br/>Machst Gott für uns wirklich.<br/>',NULL,46055,3);
INSERT INTO stanza VALUES('G33','4','In Dir Gott unser Leben ist,<br/>Er ist das Licht in Dir;<br/>In Dir an der Natur von Gott<br/>Haben wir teil schon hier.<br/>',NULL,46056,4);
INSERT INTO stanza VALUES('G33','5','In Dir ist Gott Genuss für uns,<br/>So dass die Gnade fließt;<br/>In Dir auch Seine Wirklichkeit<br/>Und Seine Wahrheit ist.<br/>',NULL,46057,5);
INSERT INTO stanza VALUES('G33','6','Aus Deiner Fülle Gnade fließt,<br/>Die stärkt für unsren Lauf;<br/>In Dir vermengst Du Gott mit uns,<br/>Bis wir sind eins vollauf.<br/>',NULL,46058,6);
INSERT INTO stanza VALUES('G33','7','Ja, Du bist unser Herr und Gott,<br/>Du sorgst für uns in Dir;<br/>Wir beten Dich voll Liebe an,<br/>Du bist uns alles hier.<br/>',NULL,46059,7);
INSERT INTO stanza VALUES('G34','1','Das Bild des Vaters bist Du, Herr,<br/>Ihn schaun wir in Dir hier,<br/>Die ganze Fülle der Gottheit<br/>Leibhaftig wohnt in Dir.<br/>',NULL,46060,1);
INSERT INTO stanza VALUES('G34','2','Herr, Du bist Gottes Wort, in Dir<br/>Das Leben Gottes ist;<br/>Durch Dich zu uns die Wirklichkeit<br/>Und Gnade herrlich fließt.<br/>',NULL,46061,2);
INSERT INTO stanza VALUES('G34','3','Der Abglanz Gottes Herrlichkeit<br/>Und Gottes Sohn bist Du;<br/>Du die Natur des Vaters trägst<br/>In Dir, Herr, immerzu.<br/>',NULL,46062,3);
INSERT INTO stanza VALUES('G34','4','Als die Verkörperung von Gott<br/>Bist Du mit Ihm ganz eins;<br/>In Dir kommt Gott zum Ausdruck hier,<br/>Für uns ohne Vergleich.<br/>',NULL,46063,4);
INSERT INTO stanza VALUES('G34','5','In Dir genießen wir nun Gott<br/>Als Leben allezeit;<br/>Von ganzem Herzen danken wir<br/>In alle Ewigkeit.<br/>',NULL,46064,5);
INSERT INTO stanza VALUES('G35','1','Als das lebend''ge Wort bist Du,<br/>Herr, ewiglich bei Gott;<br/>Du zeigtest Seine Herrlichkeit,<br/>Als unter uns Du warst.<br/>',NULL,46065,1);
INSERT INTO stanza VALUES('G35','chorus','Wir preisen Dich, o Lebens-Wort,<br/>Denn wir sehn Gott in Dir;<br/>Durch Dich wird Seine Herrlichkeit<br/>Für uns erkennbar hier.<br/>',NULL,46066,2);
INSERT INTO stanza VALUES('G35','2','Der Himmel spricht von Gottes Pracht,<br/>Die Schöpfung zeigt allzeit<br/>Das Wesen Gottes, Seine Kraft<br/>Und Seine Herrlichkeit.<br/>',NULL,46067,3);
INSERT INTO stanza VALUES('G35','3','O Gottes Wort, so reich und tief,<br/>Bezeugt den Herrn so klar;<br/>Im Wort wirst Du, Herr, kundgetan,<br/>Und Gott wird offenbar.<br/>',NULL,46068,4);
INSERT INTO stanza VALUES('G35','4','Du, Wort des Lebens, wurdest Fleisch,<br/>Hast Wohnung hier gemacht;<br/>Im Wort und Wandel hast Du stets<br/>Zum Ausdruck Gott gebracht.<br/>',NULL,46069,5);
INSERT INTO stanza VALUES('G35','5','O Wort, Du Selbst das Leben bist,<br/>Lebendig als das Licht;<br/>Das Leben zeigt den Vater auf<br/>Und schenkt uns klare Sicht.<br/>',NULL,46070,6);
INSERT INTO stanza VALUES('G35','6','Gottes Gericht führst Du bald aus<br/>In der Gerechtigkeit;<br/>Dadurch zeigst Du uns Gott noch mehr<br/>Und Seine Herrlichkeit.<br/>',NULL,46071,7);
INSERT INTO stanza VALUES('G35','7','Du bist der Ausdruck Gottes, Herr,<br/>Du hast Ihn kundgetan;<br/>Nun Gott nicht mehr verborgen ist,<br/>Durch Dich schaun wir Ihn an.<br/>',NULL,46072,8);
INSERT INTO stanza VALUES('G36','1','Du bist der Sohn des Menschen, Herr,<br/>Mit Fleisch und Blut Dein Weg begann;<br/>Gezeugt von einer Jungfrau treu,<br/>Du menschliche Natur zogst an.<br/>',NULL,46073,1);
INSERT INTO stanza VALUES('G36','2','Du warst auf dieser Erde hier<br/>In Knechtgestalt und Niedrigkeit;<br/>Ein Menschenleben lebtest Du<br/>Samt allem seinen Schmerz und Leid.<br/>',NULL,46074,2);
INSERT INTO stanza VALUES('G36','3','Geboren in der Krippe, eh''<br/>Du mit den Armen Dich abgabst;<br/>Du wirktest dann als Zimmermann,<br/>Und sogar wie ein Räuber starbst.<br/>',NULL,46075,3);
INSERT INTO stanza VALUES('G36','4','Stets noch mit menschlicher Natur<br/>Aus Toten standest Du dann auf;<br/>In göttlicher Gestalt als Mensch<br/>Fuhrst Du sodann zum Himmel auf.<br/>',NULL,46076,4);
INSERT INTO stanza VALUES('G36','5','Nun über alles auf dem Thron<br/>Bist Du als Mensch verherrlicht, Herr;<br/>Du bist ein Mensch in Gottes Licht,<br/>An Dir erfreut Sich Gott so sehr.<br/>',NULL,46077,5);
INSERT INTO stanza VALUES('G36','6','Bei Deiner Wiederkunft wirst Du<br/>Als Mensch erscheinen voller Kraft;<br/>Als König wirst Du hier regiern,<br/>Doch immer noch als Mensch mit Pracht.<br/>',NULL,46078,6);
INSERT INTO stanza VALUES('G36','7','Himmel und Erde machst Du neu,<br/>Ihr Zentrum wirst Du sein allein;<br/>Der Göttliche in Menschlichkeit,<br/>In Ewigkeit wird es so sein.<br/>',NULL,46079,7);
INSERT INTO stanza VALUES('G37','1','O Herr Jesus, Dich wir preisen,<br/>Dich, den „Samen einer Frau“,<br/>Du entsprangest einer Jungfrau,<br/>Was die Schrift verhieß genau.<br/>Du zogst menschliche Natur an,<br/>Als ein Mensch den Kampf tratst an,<br/>Hast am Kreuz zermalmt die Schlange<br/>Und erfülltest Gottes Plan.<br/>',NULL,46080,1);
INSERT INTO stanza VALUES('G37','chorus','Deine Herrlichkeit, Herr,<br/>Sehen wir in Schönheit;<br/>Sie strahlt voller Glanz und Tugend<br/>In der Menschlichkeit.<br/>',NULL,46081,2);
INSERT INTO stanza VALUES('G37','2','Du als Mensch durch die Fleischwerdung<br/>Hattest teil an Fleisch und Blut,<br/>Um den Teufel zu zerstören,<br/>Unsretwegen, uns zugut.<br/>Mit dem kostbarn Namen Jesus,<br/>Auch Immanuel genannt,<br/>Wurdest Du zu unsrem Retter,<br/>Hast Errettung uns gesandt.<br/>',NULL,46082,3);
INSERT INTO stanza VALUES('G37','3','„Letzter Adam“ ist Dein Name,<br/>Du heißt auch der „zweite Mensch“;<br/>Du bist Haupt der neuen Schöpfung,<br/>Besser als der erste Mensch.<br/>Als der Menschensohn Du lebtest<br/>Hier in großer Einfachheit;<br/>Und auch heute in den Himmeln<br/>Bist Du Mensch in Ewigkeit.<br/>',NULL,46083,4);
INSERT INTO stanza VALUES('G37','4','O Herr Jesus, Du kommst wieder<br/>– Gott bestimmte schon die Zeit –<br/>Mit der Herrlichkeit des Vaters,<br/>Mensch bleibst Du in Ewigkeit.<br/>Auf dem Richterstuhl, Herr Jesus,<br/>Du der Menschensohn noch bist;<br/>Ewig einverleibt in Dir, Herr,<br/>Die Natur des Menschen ist.<br/>',NULL,46084,5);
INSERT INTO stanza VALUES('G38','1','Der Wandel von Christus, als hier auf der Erd,<br/>Zeigt uns der Psalm Sechzehn, hat kostbaren Wert.<br/>Die Haltung von Ihm offenbart überaus<br/>Den Menschen, der wohnen mag, in Gottes Haus.<br/>',NULL,46085,1);
INSERT INTO stanza VALUES('G38','2','„Bewahre mich Gott, denn bei Dir berg ich mich“ –<br/>Gott war Seine Zuflucht kontinuierlich.<br/>„O Du bist mein Herr, und mein Gut ist in Dir“,<br/>Wie Er stets mit Gott sprach, so sollten''s auch wir.<br/>',NULL,46086,2);
INSERT INTO stanza VALUES('G38','3','„Die Heiligen hier auf der Erde“ allein<br/>Sind Sein Wohlgefallen, Sein Herz nehmen ein.<br/>Sie sind Seine Freude und machen Ihn froh,<br/>Die vier Evangelien bezeugen dies so.<br/>',NULL,46087,3);
INSERT INTO stanza VALUES('G38','4','„Der Herr ist mein Anteil, mein Kelch ist der Herr“ –<br/>In allem zum Vater nur stets schaute Er.<br/>„Ich segne den Herrn, der mir Rat stets gewährt“ –<br/>Er hat Sich geleugnet, des Herrn Wort geehrt.<br/>',NULL,46088,4);
INSERT INTO stanza VALUES('G38','5','„Darum freut mein Herz sich, mein Geist jubelt laut<br/>Mein Leib ist geborgen und Dir anvertraut;<br/>Dem Scheol gibst Du Meine Seele nicht her,<br/>Mein Leib wird dem ewigen Leben gewährt.“<br/>',NULL,46089,5);
INSERT INTO stanza VALUES('G38','6','Er auferstand, Herrlichkeit Ihn nun umschließt<br/>Die Gegenwart Gottes in Fülle genießt.<br/>Zur Rechten des Vaters sitzt Er auf dem Thron<br/>Für immer und ewig ist Freude Sein Lohn.<br/>',NULL,46090,6);
INSERT INTO stanza VALUES('G39','1','Wie süß Dein Name ist,<br/>Jesus, mein Herr!<br/>Gnade sich reich ergießt,<br/>Jesus, mein Herr!<br/>Fröhlich ich jubilier,<br/>Denn Du wohnst jetzt in mir,<br/>Alles hab ich in Dir,<br/>Jesus, mein Herr!<br/>',NULL,46091,1);
INSERT INTO stanza VALUES('G39','2','Dein Leben, Menschensohn,<br/>Jesus, mein Herr!<br/>Gabst hin samt Deinem Thron,<br/>Jesus, mein Herr!<br/>Groß Deine Liebe ist,<br/>Keine sonst reicher fließt,<br/>Uns wie ein Band umschließt,<br/>Jesus, mein Herr!<br/>',NULL,46092,2);
INSERT INTO stanza VALUES('G39','3','Allein gerecht in Dir,<br/>Jesus, mein Herr!<br/>Zuflucht gewährst Du mir,<br/>Jesus, mein Herr!<br/>Nichts fürcht ich, Du bist nah<br/>Und immer für mich da,<br/>Mein Tröster wunderbar,<br/>Jesus, mein Herr!<br/>',NULL,46093,3);
INSERT INTO stanza VALUES('G39','4','Du kommst schon bald zurück,<br/>Jesus, mein Herr!<br/>Welch Freude! Welch ein Glück!<br/>Jesus, mein Herr!<br/>Ich schau Dein Angesicht,<br/>So werd ich wie Du bist,<br/>Bleib bei Dir ewiglich,<br/>Jesus, mein Herr!<br/>',NULL,46094,4);
INSERT INTO stanza VALUES('G40','1','Wie süß der Name Jesu klingt<br/>Im Ohr, von dem, der glaubt!<br/>Heilt seine Wunden, Ängste nimmt,<br/>Und ihm die Sorgen raubt.<br/>',NULL,46095,1);
INSERT INTO stanza VALUES('G40','2','Er tröstet den verzagten Geist,<br/>Bringt schweren Herzen Ruh;<br/>Macht Seelen satt, die hungrig sind,<br/>Mit Manna immerzu.<br/>',NULL,46096,2);
INSERT INTO stanza VALUES('G40','3','O Name! Fels, auf den wir baun,<br/>Uns Schild und Schutz zugleich;<br/>Welch wunderbarer Schatz bist Du,<br/>Mit Gnaden-Vorrat reich!<br/>',NULL,46097,3);
INSERT INTO stanza VALUES('G40','4','Du, Jesus, Retter, Hirte, Freund,<br/>Und Priester, König bist;<br/>Herr, unser Leben, Weg und Ziel,<br/>In Dir die Fülle ist.<br/>',NULL,46098,4);
INSERT INTO stanza VALUES('G40','5','Wie schwach ist unsre Herzensmüh!<br/>Das wärmste Lob so kalt;<br/>Doch bald, wenn wir Dich sehen, Herr,<br/>Der Preis kraftvoll erschallt.<br/>',NULL,46099,5);
INSERT INTO stanza VALUES('G40','6','Bis dann mit jedem Atemzug<br/>Von Seiner Liebe singt!<br/>Den Namen Jesus rühmen wir,<br/>Der Todesmacht bezwingt.<br/>(Die letzten beiden Zeilen jeder Strophe wiederholen.)<br/>',NULL,46100,6);
INSERT INTO stanza VALUES('G41','1','So süß der Name Jesus ist,<br/>Er ist Musik für jeden Christ;<br/>Du meiner Freude Fülle bist,<br/>Kostbarer Name Jesus.<br/>',NULL,46101,1);
INSERT INTO stanza VALUES('G41','chorus','Jesus! Süß Dein Name klingt,<br/>Jesus! Dir mein Herz lobsingt;<br/>Jesus! Die Gemeinde bringt<br/>Dir Lob und Preis für immer.<br/>',NULL,46102,2);
INSERT INTO stanza VALUES('G41','2','Ich liebe Seinen Namen, seit<br/>Er mich von Ängsten hat befreit;<br/>Er kennt mein''n Gram, mich trägt allzeit,<br/>Ich lieb den Namen Jesus.<br/>',NULL,46103,3);
INSERT INTO stanza VALUES('G41','3','Wenn immer ich den Namen sag,<br/>Sein Klang mein Herz zu freun vermag;<br/>Er trocknet alle Tränen ab,<br/>Erhöht den Namen Jesus!<br/>',NULL,46104,4);
INSERT INTO stanza VALUES('G41','4','Ein Menschenwort kann sagen nicht,<br/>Wie süß Sein Name ist für mich;<br/>Lobpreis erklinge ewiglich,<br/>Oh, preist den Namen Jesus!<br/>',NULL,46105,5);
INSERT INTO stanza VALUES('G42','1','Herr, Dein Name lautet Jesus,<br/>Und er ist so wunderbar;<br/>Du entstammtest einer Jungfrau<br/>Als der Menschensohn fürwahr.<br/>Der Jehova-Retter bist Du,<br/>Von den Sünden Du befreist;<br/>Wenn wir Dich als Retter nehmen,<br/>Gottes Leben uns verleihst.<br/>',NULL,46106,1);
INSERT INTO stanza VALUES('G42','2','Doch auch „Christus“ ist Dein Name,<br/>Deinen Dienst bezeichnet er;<br/>Christus heißt Gesalbter Gottes,<br/>Und Du bist es von jeher.<br/>Du bist wirklich der Messias;<br/>Gott hat Dich bestimmt dazu,<br/>Seinen Vorsatz zu erfüllen,<br/>Ihn allein verherrlichst Du.<br/>',NULL,46107,2);
INSERT INTO stanza VALUES('G42','3','Du heißt auch „Immanuel“, Herr,<br/>„Gott mit uns“ heißt dies allzeit;<br/>Gott in Gnade sich vermengt hat<br/>Ganz mit unsrer Menschlichkeit.<br/>Sichtbar wurde Gott im Fleisch hier,<br/>Gnade kam und Wirklichkeit;<br/>Gott durch Glauben wir empfangen,<br/>Sehen Seine Herrlichkeit.<br/>',NULL,46108,3);
INSERT INTO stanza VALUES('G42','4','Herr, wir lieben Deine Namen,<br/>Sie bedeuten uns so viel;<br/>Ihren Wert und ihre Süße<br/>Schätzen wir stets, bis zum Ziel.<br/>Dir sei Ehre, liebster Retter,<br/>Du bist voller Herrlichkeit,<br/>Dich, Immanuel, erhöhn wir,<br/>Singen Dir in Ewigkeit.<br/>',NULL,46109,4);
INSERT INTO stanza VALUES('G43','1','Ich liebe einen Namen sehr,<br/>Wie kostbar ist er mir!<br/>In meinem Ohr so süß klingt er,<br/>Der schönste Name hier.<br/>',NULL,46110,1);
INSERT INTO stanza VALUES('G43','chorus','Oh, ich liebe Jesus,<br/>Oh, ich liebe Jesus,<br/>Oh, ich liebe Jesus,<br/>Denn Er liebt'' mich zuerst!<br/>',NULL,46111,2);
INSERT INTO stanza VALUES('G43','2','Von Retter-Liebe spricht Er mir,<br/>Er starb, macht frei und rein;<br/>Sein Name spricht vom kostbarn Blut,<br/>Für Sünder steht es ein.<br/>',NULL,46112,3);
INSERT INTO stanza VALUES('G43','3','Er sagt mir, was der Vater mir<br/>Hat täglich zugedacht;<br/>Befind ich mich auf finstrem Pfad,<br/>Mir doch die Sonne lacht.<br/>',NULL,46113,4);
INSERT INTO stanza VALUES('G43','4','Dein Name zeigt dein liebend Herz<br/>In Schwachheit fühlt es mit;<br/>Mich trägt in Sorgen und in Schmerz,<br/>Wenn es sonst keinen gibt.<br/>',NULL,46114,5);
INSERT INTO stanza VALUES('G44','1','O Jesus! Süß Dein Name klingt<br/>Für jedes offne Ohr;<br/>Der Sünder, dem vergeben ist,<br/>Schätzt ihn wie nie zuvor.<br/>',NULL,46115,1);
INSERT INTO stanza VALUES('G44','2','In Deinem Namen Gnade fließt,<br/>Die Gott als Mensch uns gibt;<br/>Sein eignes Leben sieht Gott nun<br/>In dem, der Jesus liebt.<br/>',NULL,46116,2);
INSERT INTO stanza VALUES('G44','3','Sein Name reich von Liebe spricht,<br/>Sanftmütig Leiden trägt,<br/>Sein volles Mitgefühl erzeigt,<br/>Weiß, was dich niederschlägt.<br/>',NULL,46117,3);
INSERT INTO stanza VALUES('G44','4','Für uns zur Sünde wurdest Du,<br/>Gerecht durch Dich sind wir;<br/>Nach unsrer Liebe sehnst Du Dich,<br/>Vertrauen wolln wir Dir.<br/>',NULL,46118,4);
INSERT INTO stanza VALUES('G44','5','Wir rufen Deinen Namen gern,<br/>Und preisen Dich im Geist;<br/>Du, Höchster von Zehntausenden,<br/>In Liebe uns befreist.<br/>',NULL,46119,5);
INSERT INTO stanza VALUES('G45','1','Teurer mächt''ger Name Jesu!<br/>Gern in ihn hinein ich flieh;<br/>Er steht über allen Namen,<br/>Denn Dein Name bringt den Sieg.<br/>',NULL,46120,1);
INSERT INTO stanza VALUES('G45','2','Liebster Jesus! Starker Retter!<br/>Alles schenkt Dein Name mir;<br/>Wenn ich Deinen Namen atme,<br/>Trink ich Leben reich von Dir.<br/>',NULL,46121,2);
INSERT INTO stanza VALUES('G45','3','Von der Kraft des Namens Jesus<br/>Spricht das Universum klar,<br/>Doch nur Sünder, die erlöst sind,<br/>Spüren Seinen Trost fürwahr.<br/>',NULL,46122,3);
INSERT INTO stanza VALUES('G45','4','Jesus! Jesus! Schönster Name –<br/>Balsam hier in Not und Leid;<br/>Siegen wir in Deinem Namen,<br/>Bis Du kommst in Herrlichkeit.<br/>',NULL,46123,4);
INSERT INTO stanza VALUES('G46','1','Preist Seinen Namen! Tut ihn kund!<br/>Jesus erhebt mit Herz und Mund!<br/>Siegreich der König kehrt bald ein,<br/>Erde sing Lob, preis Ihn allein!<br/>',NULL,46124,1);
INSERT INTO stanza VALUES('G46','2','Preist Seinen Namen! Sucht im Sturm<br/>Zuflucht bei ihm als unsrem Turm;<br/>Frieden schenkt er in jedem Krieg,<br/>In Jesu Name ist der Sieg.<br/>',NULL,46125,2);
INSERT INTO stanza VALUES('G46','3','Preist Seinen Namen! Bis er dann<br/>Mächtig die Erde führen kann;<br/>Nicht mehr herrscht Sünde, Tod, noch Pein,<br/>Christus, der Herr, regiert allein.<br/>',NULL,46126,3);
INSERT INTO stanza VALUES('G46','4','Preist Seinen Namen! Jesus bald<br/>Herrscht über jede Art Gewalt;<br/>Jesus, den höchsten Namen ehrt,<br/>Denn Jesu Name ist es wert.<br/>',NULL,46127,4);
INSERT INTO stanza VALUES('G46','5','Preist Seinen Namen! Bald sich beugt<br/>Jedes Knie, dann den Herrn bezeugt;<br/>Jesus Frucht Seines Kreuzes sieht,<br/>Wenn alles Ihm zum Ruhm geschieht.<br/>',NULL,46128,5);
INSERT INTO stanza VALUES('G47','1','Oh, wie ist der Herr uns nahe, rufen wir Ihn an!<br/>Seine Gegenwart uns stärkt und zieht uns neu voran;<br/>Jesus lässt Sich finden, wenn du rufst, ist Er gleich da –<br/>Oh, welch ein Trost für unser Herz zu wissen Er ist nah!<br/>',NULL,46129,1);
INSERT INTO stanza VALUES('G47','chorus','Jesus! Oh, welch ein Nam!<br/>O Herr Jesus! Wie Leben fließt!<br/>Name siegreich und so glorreich,<br/>Er den höchsten Namen genießt!<br/>Jesus! Name voll Kraft!<br/>O Herr Jesus! Trost uns verschafft!<br/>Atmet ihn doch ein, ruft tagaus, tagein,<br/>O Herr Jesus! Oh, welch ein Nam!<br/>',NULL,46130,2);
INSERT INTO stanza VALUES('G47','2','Ruf den Namen Jesus an, Er macht dich völlig frei,<br/>O Herr Jesus, Halleluja, Knechtschaft ist vorbei!<br/>Trink den Kelch der Rettung, dass Er dich beleben kann;<br/>Uns von so vielem rettet Er, wenn wir Ihn rufen an.<br/>',NULL,46131,3);
INSERT INTO stanza VALUES('G47','3','Für den Herrn sind Juden, Griechen, alle Menschen gleich;<br/>Und wer Seinen Namen ruft, für den ist Er so reich.<br/>O Herr Jesus! Freudig ruf ich Dich und Leben fließt;<br/>Ich atme Deinen Namen ein, der süß und lieblich ist.<br/>',NULL,46132,4);
INSERT INTO stanza VALUES('G47','4','Über unsren Retter-Gott erfreuen wir uns sehr,<br/>Ob in Wonne, ob in Kummer rufen wir: „O Herr!“<br/>Seinen Namen ruf ich an, solang ich leben werd,<br/>Sein Ohr hat Er mir zugeneigt, gibt Gnade mir vermehrt.<br/>',NULL,46133,5);
INSERT INTO stanza VALUES('G47','5','Ja, den Herrn wir rufen an und geben Ihm die Ehr,<br/>Dankbar und aus ganzem Herzen preisen wir Ihn sehr.<br/>Ruft mit allen Heiligen Ihn an an jedem Ort,<br/>Aus reinem Herzen rufen wir, und Gnade fließt sofort.<br/>',NULL,46134,6);
INSERT INTO stanza VALUES('G48','1','Dein Name wie Salböl süß fließt:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Dein Name wie Salböl süß fließt,<br/>Dein Name wie Salböl süß fließt.<br/>',NULL,46135,1);
INSERT INTO stanza VALUES('G48','2','Die Jungfrauen lieben Dich sehr:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Die Jungfrauen lieben Dich sehr,<br/>Die Jungfrauen lieben Dich sehr.<br/>',NULL,46136,2);
INSERT INTO stanza VALUES('G48','3','Dein'' Liebe ist besser als Wein:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Dein'' Liebe ist besser als Wein,<br/>Dein'' Liebe ist besser als Wein.<br/>',NULL,46137,3);
INSERT INTO stanza VALUES('G48','4','Zieh mich und wir laufen Dir nach:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Zieh mich und wir laufen Dir nach,<br/>Zieh mich und wir laufen Dir nach.<br/>',NULL,46138,4);
INSERT INTO stanza VALUES('G48','5','Geliebter, Du bist mir so schön:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Geliebter, Du bist mir so schön,<br/>Geliebter, Du bist mir so schön.<br/>',NULL,46139,5);
INSERT INTO stanza VALUES('G48','6','Ich fand Ihn, den meine Seel liebt:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Ich fand Ihn, den meine Seel liebt,<br/>Ich fand Ihn, den meine Seel liebt.<br/>',NULL,46140,6);
INSERT INTO stanza VALUES('G48','7','Ich hielt Ihn, ließ Ihn nicht mehr gehn:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Ich hielt Ihn, ließ Ihn nicht mehr gehn,<br/>Ich hielt Ihn, ließ Ihn nicht mehr gehn.<br/>',NULL,46141,7);
INSERT INTO stanza VALUES('G48','8','O eile, Geliebter, komm bald:<br/>Jesus, Jesus, Jesus, Jesus!<br/>O eile, Geliebter, komm bald,<br/>O eile, Geliebter, komm bald.<br/>',NULL,46142,8);
INSERT INTO stanza VALUES('G48','9','Wir lieben Dich so unsagbar:<br/>Jesus, Jesus, Jesus, Jesus!<br/>Wir lieben Dich so unsagbar,<br/>Wir lieben Dich so unsagbar.<br/>',NULL,46143,9);
INSERT INTO stanza VALUES('G49','1','Sein Name: Wunderbar;<br/>Ratgeber immerdar;<br/>Sein Name: starker Gott,<br/>Jesus, mein Herr.<br/>Ein Kind und Sohn ist Er,<br/>Ewiger Vater – Er;<br/>Der Friedefürst für mich,<br/>Jesus, mein Herr.<br/>',NULL,46144,1);
INSERT INTO stanza VALUES('G49','2','Lobpreist den Schöpfer,<br/>Jesus, den Retter,<br/>Der Geist, der Leben gibt.<br/>Betet im Geist zu Ihm,<br/>Liebt Ihn, gebt Ehre Ihm;<br/>Sein Name: Wunderbar,<br/>Jesus, mein Herr.<br/>',NULL,46145,2);
INSERT INTO stanza VALUES('G50','1','Seinen Namen lieben wir,<br/>Den Namen Jesus!<br/>In dem Himmel, auf der Erd<br/>Kommt Ihm gar nichts gleich.<br/>Atmen wir den Namen ein,<br/>Kann Tod und Finsternis nicht sein;<br/>Rufen wir; kommt die Person des Namens her!<br/>',NULL,46146,1);
INSERT INTO stanza VALUES('G50','2','Deinen Namen, liebster Herr,<br/>Voll Freude bekennen wir<br/>Zu der Herrlichkeit des Vaters nun fortan.<br/>Dich zu preisen für uns ist,<br/>Täglich Genuss, wie süß Du bist!<br/>Herr, wir lieben Dich und rufen Dich nun an!<br/>',NULL,46147,2);
INSERT INTO stanza VALUES('G51','1','Herr, Du bestandst von alters her,<br/>Schon vor vergang''ner Ewigkeit!<br/>Du unerschaffner ICH BIN bist,<br/>Und ew''ger Vater, ohne Zeit!<br/>',NULL,46148,1);
INSERT INTO stanza VALUES('G51','2','Mensch unter Menschen warst Du hier,<br/>Doch bei Gott warst Du immerzu!<br/>Und Gottes Fülle wohnt in Dir,<br/>Der unbegrenzte Gott bist Du!<br/>',NULL,46149,2);
INSERT INTO stanza VALUES('G51','3','Dein Ursprung ist genau wie Gott,<br/>Schon vor der Schöpfung warst Du, Herr!<br/>Vor allen kommst Du Herr zuerst,<br/>Und keiner war jemals vorher.<br/>',NULL,46150,3);
INSERT INTO stanza VALUES('G51','4','Auf ewig Deine Jahre sind,<br/>Gott, Du bleibst gleich zu jeder Zeit!<br/>Nichts andres währt so lang wie Du,<br/>Nach Dir kommt nichts in Ewigkeit!<br/>',NULL,46151,4);
INSERT INTO stanza VALUES('G51','5','Du bist dem Vater völlig gleich,<br/>Der ewig und vollkommen ist!<br/>Du bist als Alpha Erster, Herr,<br/>Als Omega der Letzte bist!<br/>',NULL,46152,5);
INSERT INTO stanza VALUES('G51','6','Ewiglich Deine Jahre sind,<br/>Dir, dem Vollkomm''nen, sei die Ehr!<br/>All Deine Grenzenlosigkeit<br/>Und Fülle schätzen wir so sehr!<br/>',NULL,46153,6);
INSERT INTO stanza VALUES('G52','1','Nieder zu Erden,<br/>Um ein Mensch zu werden,<br/>Mein Gott und Retter kam<br/>Und Jesus war Sein Nam.<br/>Geborn verachtet,<br/>Fremd und unbeachtet,<br/>Ein Mann der Schmerzen, Tränen und der Qual.<br/>',NULL,46154,1);
INSERT INTO stanza VALUES('G52','chorus','Wie ich Ihn liebe! Wie ich Ihn schätze!<br/>Mein Licht, mein Atem ist Er allein!<br/>Der große Schöpfer ist mein Erlöser,<br/>Und Gottes Fülle wohnt ganz in Ihm!<br/>',NULL,46155,2);
INSERT INTO stanza VALUES('G52','2','Auf welchen Wegen<br/>Kam uns Gott entgegen!<br/>Hat in der Todesnacht<br/>Uns Hoffnungslicht gebracht.<br/>Der Allerhöchste<br/>Sich vom Glanz loslöste,<br/>Sich beugt, umwirbt mich, meine Seele heilt.<br/>',NULL,46156,3);
INSERT INTO stanza VALUES('G52','3','Ohne zu klagen,<br/>Fleisch und Blut getragen,<br/>Zog Er das Menschsein an,<br/>Enthüllte Gottes Plan.<br/>Wer kann''s erfassen?<br/>Selbst von Gott verlassen;<br/>Nun weiß ich, Du bist''s, welcher heißt: „ICH BIN“.<br/>',NULL,46157,4);
INSERT INTO stanza VALUES('G53','1','Hört! Es singt das Engelsheer:<br/>„Dem gebornen König Ehr;<br/>Friede nun die Erde krönt,<br/>Gott und Sünder sind versöhnt“.<br/>Alle Völker, steht nun auf,<br/>Singt den Himmelssieg zuhauf;<br/>Laut verkünd''t mit Engelchörn:<br/>„Christ – geborn in Bethlehem“.<br/>',NULL,46158,1);
INSERT INTO stanza VALUES('G53','2','Christus, ewig unsrem Herrn,<br/>Bringen stets die Himmel Ehrn;<br/>Siehe! Der uns Rettung bringt,<br/>Einer Jungfrau Schoß entspringt.<br/>Gottheit in des Fleisches Kleid<br/>Wohnt bei uns in Raum und Zeit!<br/>Mensch bei Menschen, Ihm gefällt;<br/>Jesus ist Immanuel.<br/>',NULL,46159,2);
INSERT INTO stanza VALUES('G53','3','Friedefürst gebenedeit!<br/>Sonne der Gerechtigkeit!<br/>Licht und Leben bringt Er bei,<br/>Seine Flügel voller Heil.<br/>Herrlichkeit sanft gibt Er her,<br/>Dass der Mensch nicht sterbe mehr;<br/>Weckt die Söhne dieser Erd,<br/>Auf dass Er sie neu gebärt.<br/>',NULL,46160,3);
INSERT INTO stanza VALUES('G53','4','Komm, Begehr der Völker, komm!<br/>Nun in uns in Demut wohn;<br/>Steh auf, Same von der Frau,<br/>Schlangenkopf in uns zerhau;<br/>Adams Gleichheit tilge ganz,<br/>An die Stelle Dein Bild stanz;<br/>Letzter Adam stell uns her,<br/>Tu''s in Deiner Liebe, Herr.<br/>(Die letzten beiden Zeilen wiederholen.)<br/>',NULL,46161,4);
INSERT INTO stanza VALUES('G54','1','Du bist der höchste Gott allein,<br/>Doch Du zogst Fleisch an, wurdest klein,<br/>Hast Dich erniedrigt Mensch zu sein;<br/>Herr, ich gedenke Dein!<br/>',NULL,46162,1);
INSERT INTO stanza VALUES('G54','2','Du warst im Glanz und hellsten Licht,<br/>Bargst Dich im Zelt des Fleisches schlicht,<br/>Äußere Schönheit zählte nicht;<br/>Herr, ich gedenke Dein!<br/>',NULL,46163,2);
INSERT INTO stanza VALUES('G54','3','Du bist ein Spross aus dürrem Grund,<br/>Wurdest als Mann der Schmerzen kund,<br/>Trotz Menschenhass war still Dein Mund;<br/>Herr, ich gedenke Dein!<br/>',NULL,46164,3);
INSERT INTO stanza VALUES('G54','4','Demütig, sanft, welch Herz Du hast!<br/>Willig erträgst Du jede Last,<br/>Ohne zu klagen, stets gefasst;<br/>Herr, ich gedenke Dein!<br/>',NULL,46165,4);
INSERT INTO stanza VALUES('G54','5','Sanftmut in Dir als Mensch reich fließt,<br/>Dir Ausgeglichenheit entsprießt,<br/>Speisopfer Du dem Vater bist;<br/>Herr, ich gedenke Dein!<br/>',NULL,46166,5);
INSERT INTO stanza VALUES('G54','6','Du tatst den Willn des Vaters gern,<br/>Lügen des Feindes bliebst Du fern,<br/>Wer treu und weis Dir gleichen kann?<br/>Herr, ich gedenke Dein!<br/>',NULL,46167,6);
INSERT INTO stanza VALUES('G54','7','Du warst gehorsam bis zum Tod,<br/>An meiner Stell ertrugst Du Not,<br/>Willig zu leiden Hohn und Spott;<br/>Herr, ich gedenke Dein!<br/>',NULL,46168,7);
INSERT INTO stanza VALUES('G54','8','Daher hat Gott erhoben Dich,<br/>Dein Angesicht strahlt hell auf mich,<br/>Himmel und Erde beugen sich;<br/>Herr, ich gedenke Dein!<br/>',NULL,46169,8);
INSERT INTO stanza VALUES('G55','1','O Haupt, einst so zerschunden,<br/>Entstellt durch Schmerz und Hohn,<br/>Du Spott ertrugst und Wunden,<br/>Nur Dornen warn Dein Lohn.<br/>Voll Leiden war Dein Leben,<br/>Am Kreuz verflucht, verschmäht,<br/>Nun bist Du, Haupt, umgeben<br/>Mit Glanz und Majestät.<br/>',NULL,46170,1);
INSERT INTO stanza VALUES('G55','2','Du strahlst so wie die Sonne,<br/>Die Leben gibt und Licht!<br/>Die Schöpfung zierst als Krone,<br/>Doch will die Welt Dich nicht:<br/>Wir brachten Dich in Nöte<br/>Mit unsrer Sündenlast,<br/>Die Schuld sich stets erhöhte,<br/>Bezahlt doch alles hast.<br/>',NULL,46171,2);
INSERT INTO stanza VALUES('G55','3','O Herr, Dir unser Dank gilt,<br/>Du Retter-Freund bist gut!<br/>Denn Deine Seele durchhielt,<br/>Als Du vergoss''st Dein Blut.<br/>Wirk, dass ich allezeit kann<br/>Auf Deiner Treue stehn,<br/>Bis ich in Herrlichkeit dann<br/>Dein Angesicht kann sehn.<br/>',NULL,46172,3);
INSERT INTO stanza VALUES('G56','1','Du, Lamm Gottes, rein und sündlos,<br/>Starbst für Sünder dort allein.<br/>Dein vergossnes Blut erlöste,<br/>Uns von Flecken wusch ganz rein.<br/>O Lamm Gottes, o Lamm Gottes,<br/>Du nahmst uns die Sünden weg,<br/>Du nahmst uns die Sünden weg!<br/>',NULL,46173,1);
INSERT INTO stanza VALUES('G56','2','Eherne Schlange, auf Dich schaun wir,<br/>Sohn des Menschen hoch erhöht.<br/>In Gestalt des Fleisches hast Du<br/>Sünde dort am Kreuz zerstört.<br/>Alte Schöpfung ging zu Ende;<br/>Satan und die Welt besiegt,<br/>Satan und die Welt besiegt!<br/>',NULL,46174,2);
INSERT INTO stanza VALUES('G56','3','Weizenkorn, so klein und niedrig,<br/>Ohne Tod bleibt es allein;<br/>Birgt in sich das Leben Gottes,<br/>In den Tod gesät muss sein.<br/>Dann sprießt Leben, mehr wird''s geben,<br/>Viele Körner bringt''s hervor,<br/>Viele Körner bringt''s hervor!<br/>',NULL,46175,3);
INSERT INTO stanza VALUES('G56','4','Du, Lamm Gottes, bringst Erlösung,<br/>Eherne Schlange – Satans End,<br/>Weizenkorn zeigt die Vermehrung,<br/>Wir, die Körner, sind vermengt.<br/>Halleluja! Halleluja!<br/>Allumfassend ist Dein Tod,<br/>Allumfassend ist Dein Tod!<br/>',NULL,46176,4);
INSERT INTO stanza VALUES('G57','1','Welch süßer Bericht: Christus liebte uns sehr,<br/>Für Leiden gab Er Himmels-Herrlichkeit her!<br/>An unserer Stelle auf Golgatha starb,<br/>Erlösung vollbrachte, uns Freiheit erwarb.<br/>',NULL,46177,1);
INSERT INTO stanza VALUES('G57','chorus','Preist den Herrn! Preist den Herrn!<br/>Der Erlöser ist''s wert;<br/>Preist den Herrn! Preist den Herrn!<br/>Jesus, Gottes Sohn ehrt!<br/>Den Preis zu bezahlen, warst Du, Herr, bereit;<br/>Wir loben Dich, Retter und Freund, allezeit.<br/>',NULL,46178,2);
INSERT INTO stanza VALUES('G57','2','Vollkommen erfüllt Sein erlösendes Blut<br/>Die Forderung Gottes, wie herrlich und gut!<br/>Auf Sich das Gericht über Sünde nahm Er,<br/>Ehrt Gott durch Sein Werk und verherrlicht Ihn sehr.<br/>',NULL,46179,3);
INSERT INTO stanza VALUES('G57','3','Nun strahlende Herrlichkeit schmückt Christi Thron,<br/>Den höchsten der Namen gab Gott Seinem Sohn!<br/>Ja, Jesus, der Retter, mit Ehre gekrönt,<br/>Ist würdig, für Ihn ewig Lobpreis ertönt.<br/>',NULL,46180,4);
INSERT INTO stanza VALUES('G58','1','Wie wunderbar Erlösung ist,<br/>Mein liebster Herr, in Dir!<br/>Noch nie gesehn, gehört, erkannt,<br/>Was Du vermacht hast mir!<br/>Bist göttlich und geheimnisvoll,<br/>Weit mehr als was ich weiß!<br/>Erlösung ist so wunderbar,<br/>Weit mehr als mein Lobpreis!<br/>',NULL,46181,1);
INSERT INTO stanza VALUES('G58','2','Durchbohrt für uns am Kreuz warst Du,<br/>Dort Blut und Wasser floss,<br/>Dass Gottes Leben zu uns kommt<br/>Durch die Erlösung groß!<br/>Wir sind gereinigt durch Dein Blut,<br/>Nun nimmt uns Gott gern an;<br/>Dein Leben hat uns neu geborn,<br/>Uns nichts mehr trennen kann.<br/>',NULL,46182,2);
INSERT INTO stanza VALUES('G58','3','Das Weizenkorn bist Du, das starb,<br/>Die vielen Körner – wir,<br/>Vermengt, geformt sind wir, Dein Leib,<br/>Mit der Natur von Dir.<br/>Dein Zuwachs sind wir, liebster Herr,<br/>Du unser Inhalt bist;<br/>Durch uns lebst Du und gehst voran,<br/>Dein Wesen sichtbar ist.<br/>',NULL,46183,3);
INSERT INTO stanza VALUES('G58','4','Weil wir Dein Leib sind, richte Dich<br/>In unsern Herzen ein;<br/>In uns mach Deine Wohnung nun,<br/>Du sollst Zuhause sein.<br/>Dein Gegenüber sind wir, Herr,<br/>Dein Herz voll Freude ist,<br/>Im einen Leib, mit Dir vereint,<br/>Genießen, was Du bist.<br/>',NULL,46184,4);
INSERT INTO stanza VALUES('G58','5','An Dich erinnern wir uns jetzt,<br/>Wenn wir die Zeichen sehn,<br/>Erlösung ist so wunderbar,<br/>Lobpreise Dir zustehn.<br/>Wir sind zu Deinem Leib gemacht,<br/>Zur Wohnung aufgebaut;<br/>Wir bringen Dir Anbetung dar<br/>Und lieben Dich als Braut.<br/>',NULL,46185,5);
INSERT INTO stanza VALUES('G59','1','Christus ist nun auferstanden,<br/>Halleluja!<br/>Was wir brauchen, das gab Er,<br/>Halleluja!<br/>Freude und Triumph erhebt,<br/>Halleluja!<br/>Ihr Erlösten, Antwort gebt,<br/>Halleluja!<br/>',NULL,46186,1);
INSERT INTO stanza VALUES('G59','2','Unser König auferstand,<br/>Halleluja!<br/>Todesstachel überwand,<br/>Halleluja!<br/>Durch den Tod uns Rettung gab,<br/>Halleluja!<br/>Wo ist nun dein Sieg, o Grab?<br/>Halleluja!<br/>',NULL,46187,2);
INSERT INTO stanza VALUES('G59','3','Die Erlösung ist vollbracht,<br/>Halleluja!<br/>Unser Herr gewann die Schlacht,<br/>Halleluja!<br/>Nichts hielt Ihn, Er auferstand,<br/>Halleluja!<br/>Sitzt zu Gottes rechter Hand,<br/>Halleluja!<br/>',NULL,46188,3);
INSERT INTO stanza VALUES('G59','4','Aufgestiegen weit nach oben,<br/>Halleluja!<br/>Folgen unserm Haupt erhoben,<br/>Halleluja!<br/>Auferstanden gleich wie Er,<br/>Halleluja!<br/>Jetzt nichts bindet uns nunmehr!<br/>Halleluja!<br/>',NULL,46189,4);
INSERT INTO stanza VALUES('G60','1','Preist den Sieger, Jesus Christus!<br/>Wunderbar Sein Sieg geschah!<br/>Wir sind frei von Sünd und Adam,<br/>Die Erlösung ist nun da!<br/>Er bezwang die bösen Mächte<br/>Durch das Kreuz von Golgatha.<br/>',NULL,46190,1);
INSERT INTO stanza VALUES('G60','2','Preist Ihn! Er ist auferstanden!<br/>Aus den Toten rief Gott Ihn!<br/>Er verschlang die Todesmächte,<br/>Führt vom Tod zum Leben hin!<br/>Dunkelheit und Tod durchbrach Er,<br/>Seine Kraft sehn wir darin!<br/>',NULL,46191,2);
INSERT INTO stanza VALUES('G60','3','Preist Ihn! Er ist aufgefahren!<br/>Gott erhob Ihn auf den Thron!<br/>Über alle Macht und Herrschaft,<br/>Höchster Name ist Sein Lohn!<br/>Vollmacht wurde Ihm gegeben,<br/>Bis der Feind gejagt davon!<br/>',NULL,46192,3);
INSERT INTO stanza VALUES('G60','4','Halleluja, Er ist Sieger!<br/>Gott hat Ihn vom Tod befreit!<br/>Halleluja, auferstanden,<br/>Triumphiert in Herrlichkeit!<br/>Halleluja, aufgefahren,<br/>Nun herrscht Er in Ewigkeit!<br/>',NULL,46193,4);
INSERT INTO stanza VALUES('G61','1','Halleluja! Singt für Jesus,<br/>Ihm das Zepter, Ihm der Thron;<br/>Halleluja! Groß der Sieg ist!<br/>Ihm gebührt der höchste Lohn.<br/>Hört! Der Lobpreis der Erlösten<br/>Gleicht dem Donnern einer Flut:<br/>Jesus hat aus allen Völkern<br/>Uns erlöst mit Seinem Blut.<br/>',NULL,46194,1);
INSERT INTO stanza VALUES('G61','2','Halleluja! Nicht als Waisen,<br/>Nicht in Sorgen ließ Er sie;<br/>Halleluja! Er ist nah uns,<br/>Glaube nimmt''s an, fragt nicht wie.<br/>Ihn nach vierzig Tagen nahmen<br/>Wolken auf in Herrlichkeit,<br/>Sein Versprechen uns ermutigt:<br/>„Ich bin bei euch allezeit.“<br/>',NULL,46195,2);
INSERT INTO stanza VALUES('G61','3','Halleluja! Brot vom Himmel<br/>Speist uns auf der Erde hier;<br/>Halleluja! Hunger stillst Du,<br/>Täglich kommen wir zu Dir.<br/>Ja, mein Anwalt und Fürsprecher,<br/>Mein Erlöser fleht für mich;<br/>Auf dem Thron des Allerhöchsten<br/>Sitzt Er jetzt und ewiglich.<br/>',NULL,46196,3);
INSERT INTO stanza VALUES('G61','4','Halleluja! Singt für Jesus,<br/>Ihm das Zepter, Ihm der Thron;<br/>Halleluja! Groß der Sieg ist!<br/>Ihm gebührt der höchste Lohn.<br/>Hört! Der Lobpreis der Erlösten<br/>Gleicht dem Donnern einer Flut:<br/>Jesus hat aus allen Völkern<br/>Uns erlöst mit Seinem Blut.<br/>',NULL,46197,4);
INSERT INTO stanza VALUES('G62','1','Sieh, die Völker sind versammelt<br/>Und sie sinnen Nichtigkeit;<br/>Fürsten stehn dem Herrn entgegen,<br/>Trotzen voller Einigkeit:<br/>„Lasst uns Ihre Bande reißen,<br/>Ihre Stricke werfen weg.“<br/>Gegen gar des Herrn Gesalbten<br/>Raten Fürsten unentwegt.<br/>',NULL,46198,1);
INSERT INTO stanza VALUES('G62','2','Doch der Herr, der thront im Himmel,<br/>Lacht und spottet über sie;<br/>Spricht sie an in Seiner Zornglut,<br/>Schrecken packt sie wie noch nie.<br/>„Auf dem Berg, auf Meinem Zion,<br/>Meinen König salbte Ich.“<br/>Dies verkündet Gott, der Herr, klar,<br/>Alle Fürsten fürchten sich.<br/>',NULL,46199,2);
INSERT INTO stanza VALUES('G62','3','Christus, der von Gott Gesalbte,<br/>Gottes Ratschluss nun bezeugt:<br/>„Du, Mein Sohn (in Auferstehung),<br/>Heute hab Ich Dich gezeugt.<br/>Alle Völker werd Ich geben<br/>Dir zum Erbteil ewiglich.<br/>Mit dem Stab der Macht und Herrschaft<br/>Du zerbrichst sie königlich.“<br/>',NULL,46200,3);
INSERT INTO stanza VALUES('G62','4','Seid nun weise und vernünftig,<br/>O ihr Fürsten dieser Erd.<br/>Dient dem Herrn, und jauchzt mit Zittern,<br/>Fürchtet Diesen voller Wert.<br/>Küsst den Sohn, dass Er nicht zürne<br/>Und ihr umkommt auf dem Pfad,<br/>„Wer bei Gott sich birgt, ist selig,<br/>Seinen reichen Segen hat“.<br/>',NULL,46201,4);
INSERT INTO stanza VALUES('G62','5','Deinen wunderbarn Gesalbten<br/>Sahen wir, o Preis sei Dir –<br/>Ließen ab von Nichtigkeiten,<br/>Deinen Sohn lieb küssten wir.<br/>„Wer bei Gott sich birgt, ist selig“,<br/>Nicht, „wer hält stets das Gesetz“.<br/>An den Auferstandnen glaubend,<br/>Segen haben wir nun stets.<br/>',NULL,46202,5);
INSERT INTO stanza VALUES('G63','1','Dem Herrn gebührt die Ehre,<br/>Wenn die Gemeinde singt;<br/>Die Engelheere lauschen,<br/>Wenn unser Lob erklingt.<br/>Den Herrn wir froh erhöhen,<br/>Die Welt es hören mag;<br/>Die Heere Satans fliehen<br/>Vor unsrem Siegesstab.<br/>',NULL,46203,1);
INSERT INTO stanza VALUES('G63','2','Wenn unsre Lippen schweigen,<br/>Freut sich der Feind so sehr;<br/>Warum nicht offen kämpfen?<br/>Verjagt ihn, singt noch mehr!<br/>Erbringen wir „Lobopfer“,<br/>Der Siegesschrei ergellt –<br/>Verliern wir das Gesicht nur,<br/>Sind Toren vor der Welt!<br/>',NULL,46204,2);
INSERT INTO stanza VALUES('G63','3','Die Welt wird uns nie helfen,<br/>Den Retter niemals preist,<br/>Wird Ihn auch niemals ehren,<br/>Ihm keinen Dank erweist;<br/>So brauchen wir Erlaubnis?<br/>Den Aufgefahrnen preist!<br/>Seid kühn, den Geist befreit nun!<br/>Viel Gnade Er erweist!<br/>',NULL,46205,3);
INSERT INTO stanza VALUES('G63','4','Ihr Brüder sollt nicht still sein!<br/>Ihr Schwestern freudig singt!<br/>Damit die Siegeskunde<br/>Doch weit und breit erklingt.<br/>Zu jedem Preis den Herrn lobt,<br/>Ja, jauchzt zu jeder Zeit!<br/>Rühmt Seine volle Rettung<br/>Und die Barmherzigkeit!<br/>',NULL,46206,4);
INSERT INTO stanza VALUES('G64','1','Die Gemeinde froh verkündet:<br/>Jesus ist Herr!<br/>Sie ist auf dem Herrn gegründet:<br/>Jesus ist Herr!<br/>Jesus hat Sein Werk verrichtet,<br/>Satan und sein Heer vernichtet,<br/>Und Sein Thron ist aufgerichtet,<br/>Jesus ist Herr!<br/>',NULL,46207,1);
INSERT INTO stanza VALUES('G64','2','Jesus ist der Geist schon heute,<br/>Jesus ist Herr!<br/>Er ist hier! Hört zu, ihr Leute:<br/>Jesus ist Herr!<br/>Klag nicht, Er wird dich erretten;<br/>Ruft Ihn an, Er wird eintreten,<br/>Ja, wir wollen Ihn anbeten –<br/>Jesus ist Herr!<br/>',NULL,46208,2);
INSERT INTO stanza VALUES('G64','3','Er wird dich vollauf umwandeln,<br/>Jesus ist Herr!<br/>Reich versorgt in allem Handeln,<br/>Jesus ist Herr!<br/>Er wird euch den Frieden geben,<br/>Und versorgt euch reich mit Leben,<br/>Wird euch ganz mit Gott verweben,<br/>Jesus ist Herr!<br/>',NULL,46209,3);
INSERT INTO stanza VALUES('G64','4','Er empfing uns voll Erbarmen,<br/>Jesus ist Herr!<br/>Hält uns fest in Seinen Armen,<br/>Jesus ist Herr!<br/>Seine ganze Fülle sehen<br/>Wir in Seinem Leibe stehen,<br/>Satan und sein Werk vergehen –<br/>Jesus ist Herr!<br/>',NULL,46210,4);
INSERT INTO stanza VALUES('G65','1','Vortrefflich ist Dein Name, Herr,<br/>Hier auf der ganzen Erd!<br/>Lasst jede Zunge, Volk und Stamm<br/>Erzähln von seinem Wert.<br/>Und aus dem Mund der Säuglinge<br/>Lob richtest Du Dir zu,<br/>Denn so besiegst Du Deinen Feind,<br/>Zum Schweigen ihn bringst Du.<br/>',NULL,46211,1);
INSERT INTO stanza VALUES('G65','2','Wenn wir das Universum schaun,<br/>Das Werk von Deiner Hand –<br/>Den Mond samt allen Sternen hell,<br/>Von Weisheit groß geplant,<br/>Was ist der Mensch, dass Du ihn schätzt,<br/>Dich kümmerst sehr um ihn?<br/>In göttlicher Ökonomie<br/>Zum Menschen gingst Du hin.<br/>',NULL,46212,2);
INSERT INTO stanza VALUES('G65','3','Herr Jesus, dieser Mensch bist Du,<br/>Hast uns vereint mit Dir,<br/>Hast angezogen Fleisch und Blut,<br/>Erniedrigt hast Dich hier.<br/>Doch jetzt mit Herrlichkeit gekrönt,<br/>Durch Deinen Leib herrschst Du,<br/>Und unter Deine Füße tut<br/>Gott alles immerzu.<br/>',NULL,46213,3);
INSERT INTO stanza VALUES('G65','4','Fleischwerdung, Auferstehung dann,<br/>Die Auffahrt ist geschehen;<br/>Dein Herrsein, Hauptsein, Königreich,<br/>Dein Leib ist nun zu sehn.<br/>Für jeden Schritt in Deinem Werk<br/>Bereitest Du Lobpreis.<br/>Wir singen Dir mit Herz und Mund<br/>Und loben Dich im Geist.<br/>',NULL,46214,4);
INSERT INTO stanza VALUES('G65','5','Der große Tag wird kommen bald –<br/>Ja, das erkennen wir,<br/>Doch die Gemeinden teilen heut<br/>Den Vorgeschmack schon hier.<br/>Vortrefflich, Herr, Dein Name doch<br/>Hier auf der Erde ist!<br/>Von Seinem Wert bald jedes Volk<br/>Erzählt und ihn genießt.<br/>',NULL,46215,5);
INSERT INTO stanza VALUES('G66','1','Die Herzen wallen über<br/>Wenn wir erzähln vom Herrn –<br/>Den hoch erhöhten König<br/>Beschreiben wir so gern.<br/>Wärn unsre Zungen Stifte,<br/>Wär der Bericht zu lang<br/>von Pracht und Herrlichkeiten<br/>Des lieben Bräutigam.<br/>',NULL,46216,1);
INSERT INTO stanza VALUES('G66','2','Viel schöner als die Menschen<br/>Bist Du, Herr, anzusehn,<br/>Und nichts gleicht Deiner Güte –<br/>Halleluja! Amen!<br/>Auf Deinen Lippen fließt, Herr,<br/>Die Anmut ewiglich,<br/>Von Gott bist Du gesegnet,<br/>Und unser Herz liebt Dich!<br/>',NULL,46217,2);
INSERT INTO stanza VALUES('G66','3','Du bist der starke Kämpfer<br/>Und siegreich allezeit –<br/>Voran gehst majestätisch<br/>In Glanz und Herrlichkeit!<br/>Dir beugen sich die Völker<br/>Der Siegende bist Du;<br/>Und jeder Deiner Pfeile<br/>Trifft Satan immerzu!<br/>',NULL,46218,3);
INSERT INTO stanza VALUES('G66','4','Dein Thron, o Gott, für immer<br/>Und ewig bleibt bestehn;<br/>Das Zepter Deines Reiches<br/>Ist überall zu sehn.<br/>Mit Seinem Öl der Freude<br/>Hat Dich gesalbt Dein Gott,<br/>Vor Deinen Weg-Gefährten –<br/>Welch Herrlichkeit sich bot!<br/>',NULL,46219,4);
INSERT INTO stanza VALUES('G66','5','Von Myrrhe, Aloe, Kassia<br/>Durchduftet ist Dein Kleid:<br/>Durch Tod zur Auferstehung<br/>Zu gehn warst Du bereit.<br/>Aus Elfenbeinpalästen<br/>Erfreut Dich Saitenspiel;<br/>In örtlichen Gemeinden<br/>Dich Lob erfreuen will.<br/>',NULL,46220,5);
INSERT INTO stanza VALUES('G67','1','Die Königin im Goldkleid<br/>Zu Deiner Rechten steht;<br/>Geschmückt mit Kostbarkeiten<br/>Die Königstöchter seht.<br/>Die herrliche Gemeinde<br/>Dem König ganz entspricht;<br/>Die Heiligen, die Frauen,<br/>Dir gleich sind, o welch Sicht!<br/>',NULL,46221,1);
INSERT INTO stanza VALUES('G67','2','O Tochter, nimm''s zu Herzen,<br/>Dein Ohr doch neige her:<br/>Vergiss dein Volk, Familie,<br/>Dein Land und vieles mehr.<br/>Zum Wohlgefalln des Königs<br/>Dann deine Schönheit blüht;<br/>Dein Herr verdient Anbetung,<br/>Ein Herz, das innig glüht.<br/>',NULL,46222,2);
INSERT INTO stanza VALUES('G67','3','Die Kleider dieser Tochter<br/>Sind reich mit Gold versehn –<br/>Sie ist in den Gemächern<br/>So herrlich anzusehn!<br/>Die göttliche Natur ist<br/>Ihr herrliches Gewand,<br/>Sie macht Sein heil''ges Wesen<br/>Im Leben so bekannt.<br/>',NULL,46223,3);
INSERT INTO stanza VALUES('G67','4','Vom reich bestickten Kleid wird<br/>Der König sehr berührt;<br/>In reinem, feinem Leinen<br/>Wird sie zu Ihm geführt.<br/>Durch Gottes Geist wird Christus<br/>In uns hineingestickt;<br/>Durch dieses Kleid der Zugang<br/>Zum König sich nur schickt.<br/>',NULL,46224,4);
INSERT INTO stanza VALUES('G67','5','Wenn wir den König sehen,<br/>Erschallt der Jubel weit;<br/>Von Seinem Wert wir singen<br/>In alle Ewigkeit.<br/>Wir beten an den König,<br/>Uns freun als Königin;<br/>Im Segen des Genusses<br/>Geht aller Ruhm an Ihn.<br/>',NULL,46225,5);
INSERT INTO stanza VALUES('G68','1','Gott steht auf, zerstreut die Feinde,<br/>Die Ihn hassen, werden fliehn;<br/>So wie Wachs schmilzt vor dem Feuer,<br/>Scheiden die Gottlosen hin.<br/>Die Gerechten sollen immer<br/>Jubeln mit erhobner Stimme;<br/>Singen Lobpreis, singen Lobpreis,<br/>Singen Lobpreis unsrem Gott!<br/>',NULL,46226,1);
INSERT INTO stanza VALUES('G68','2','Preist Ihn! Jah zieht durch die Wüsten,<br/>Dort die Heiligen versorgt;<br/>Ist ein Vater für die Waisen<br/>und ein wahrer Zufluchtsort.<br/>Er bringt sie in Gottes Wohnung –<br/>Oh, welch wunderbare Rettung!<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46227,2);
INSERT INTO stanza VALUES('G68','3','Gott in Seinem Haus lässt wohnen,<br/>Und wer einsam ist, zieht ein;<br/>Die Gefangenen befreit Er<br/>Und in Wohlstand führt hinein.<br/>Für die Herde, die Gott leitet,<br/>Ein Zuhause hat bereitet;<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46228,3);
INSERT INTO stanza VALUES('G68','4','Im Triumph lässt Gott erschallen<br/>Siegesrufe, nichts hält Ihn:<br/>Wir, „die Botinnen“, mitrufen,<br/>Und die Feindesheere fliehn!<br/>Schweiß und Müh gibt''s nicht mehr heute,<br/>Wir verteiln zu Haus die Beute!<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46229,4);
INSERT INTO stanza VALUES('G68','5','Siehe, Christus aufgefahren,<br/>Die Gefangnen führt Er mit;<br/>Er hat sie gemacht zu Gaben,<br/>Für Sein Haus, wo Gott einzieht.<br/>Seine Feinde waren wir<br/>Umgewandelt werden hier!<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46230,5);
INSERT INTO stanza VALUES('G68','6','Segen sei dem Herrn auf ewig,<br/>Der mit Gutem uns belädt;<br/>Er ist''s wert, dass wir Ihn rühmen,<br/>Rettet uns von früh bis spät.<br/>Er – der Ausgang von dem Tod,<br/>Jeden Feind zerschmettert Gott!<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46231,6);
INSERT INTO stanza VALUES('G68','7','Feinde sahen Deine Taten<br/>Dort in Deinem Heiligtum;<br/>Dein Triumphzug wird begleitet<br/>Von Lobpreisen ringsherum.<br/>Sieh, die Sänger gehn voran,<br/>Saitenspieler folgen dann;<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46232,7);
INSERT INTO stanza VALUES('G68','8','Kleiner Benjamin ist führend,<br/>Und dann großer Juda geht:<br/>Schmerzenssohn zur Rechten Gottes,<br/>Löwe mit dem Zepter seht.<br/>Sebulon und Naftali:<br/>Frohe Nachricht bringen sie.<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46233,8);
INSERT INTO stanza VALUES('G68','9','O ihr Heil''gen, eure Kraft hat<br/>Gott verordnet, nehmt sie an;<br/>Dennoch beten wir: „O stärke,<br/>Was Du hast für uns getan.“<br/>Höher unser Lob soll sein,<br/>Bis die Erde stimmt mit ein;<br/>Halleluja, halleluja,<br/>Halleluja, Amen!<br/>',NULL,46234,9);
INSERT INTO stanza VALUES('G69','1','Der Herr zu meinem Herrn spricht:<br/>„Zu Meiner Rechten ruh,<br/>Bald unter Deine Füße<br/>Die Feinde werd ich tun“.<br/>Das Zepter Deiner Macht streckt<br/>Der Herr von Zion aus;<br/>Du herrschst ob allen Völkern,<br/>Gerecht stets überaus.<br/>',NULL,46235,1);
INSERT INTO stanza VALUES('G69','2','Wie willig, Herr, Dein Volk ist<br/>Am Tag von Deiner Macht!<br/>Ihr Opfer, ihre Weihung<br/>Ist voller Glanz und Pracht.<br/>So wie der Tau am Morgen<br/>Erfrischt das ganze Land –<br/>So kostbar sind die Jungen<br/>Für Dich in Deiner Hand.<br/>',NULL,46236,2);
INSERT INTO stanza VALUES('G69','3','Der Schwur des Herrn gilt ewig,<br/>Der nicht veränderbar:<br/>„Du bist für ewig Priester,<br/>Wie Melchisedek war“.<br/>Du hast ja keinen Anfang,<br/>Dein Leben hat kein End!<br/>Du sorgst für uns vollkommen,<br/>Und stehst ein fürbittend.<br/>',NULL,46237,3);
INSERT INTO stanza VALUES('G69','4','Der Herr zu Deiner Rechten<br/>Am Tag von Seinem Zorn,<br/>Schlägt jeden König, richtet<br/>Dann jede Nation.<br/>Als Führer des Triumphzugs<br/>Trinkt Er von uns, dem Bach;<br/>Das Haupt wird Er erheben<br/>Gesiegt hat mannigfach.<br/>',NULL,46238,4);
INSERT INTO stanza VALUES('G69','5','Du, Herr, bist aufgefahren<br/>Zu Gottes rechter Hand,<br/>Und alle Feinde sind nun,<br/>O Haupt, Dir untertan.<br/>Du herrschst für uns – als König,<br/>Als Priester – dienst uns sehr;<br/>Dir geben wir uns willig,<br/>Dir, Sieger, sei die Ehr.<br/>',NULL,46239,5);
INSERT INTO stanza VALUES('G70','1','Horch! Zehntausend Stimmen klingen:<br/>„O Lamm Gottes!“ wie ein Mund;<br/>Die Erlösten Echo singen,<br/>„O Lamm Gottes!“ tun sie kund.<br/>',NULL,46240,1);
INSERT INTO stanza VALUES('G70','2','„Preist das Lamm!“ der Chor auffordert,<br/>Alles macht im Himmel mit;<br/>Jede Zunge Ihn bewundert,<br/>Weit herum erklingt das Lied.<br/>',NULL,46241,2);
INSERT INTO stanza VALUES('G70','3','Dank wie Weihrauch will aufsteigen,<br/>Nun zum Thron des Vaters fließt;<br/>Sich vor Jesus alle neigen,<br/>Nur Einmütigkeit Du siehst!<br/>',NULL,46242,3);
INSERT INTO stanza VALUES('G70','4','Und der Rat des Vaters fordert<br/>Für den Sohn die gleiche Ehr;<br/>Denn die Herrlichkeit des Vaters<br/>Strahlt im Glanz des Sohnes sehr.<br/>',NULL,46243,4);
INSERT INTO stanza VALUES('G70','5','Voll und ganz vom Geist durchflutet<br/>Stehen Heere rund ums Lamm,<br/>Beten ewig den „ICH BIN“ an,<br/>Den gekrönten Bräutigam.<br/>',NULL,46244,5);
INSERT INTO stanza VALUES('G70','6','Freudig ruht die neue Schöpfung,<br/>Ungestört, auf Ihn gelehnt;<br/>Ruht in Jesu voller Rettung,<br/>Keine Sorge, Knechtschaft kennt.<br/>',NULL,46245,6);
INSERT INTO stanza VALUES('G70','7','Horch! Der Himmelchor singt wieder!<br/>Laut erklingt der Lobpreis dort;<br/>„O Amen!“ singt auch die Schöpfung,<br/>Jubelnd einstimmt immerfort.<br/>',NULL,46246,7);
INSERT INTO stanza VALUES('G71','1','Sieh! Im Himmel sitzt nun Jesus,<br/>Christus thront dort allezeit;<br/>Als ein Mensch von Gott erhoben<br/>Und gekrönt mit Herrlichkeit.<br/>',NULL,46247,1);
INSERT INTO stanza VALUES('G71','2','Er zog die Natur des Mensch an,<br/>Starb für uns nach Gottes Plan,<br/>Ist im Leib auch auferstanden,<br/>Fuhr als Mensch zu Gott auf dann.<br/>',NULL,46248,2);
INSERT INTO stanza VALUES('G71','3','Gott hat Sich in Ihm erniedrigt,<br/>Blut teilhaftig, Mensch auch war;<br/>Nun der Mensch in Ihm erhöht ist<br/>Und mit Gott versöhnt fürwahr.<br/>',NULL,46249,3);
INSERT INTO stanza VALUES('G71','4','Gott und Mensch in Ihm vermengt sind,<br/>Gott im Mensch wird klar bezeugt,<br/>Mensch und Gott in Ihm vermengt sind,<br/>Mensch in Gott verherrlicht ist.<br/>',NULL,46250,4);
INSERT INTO stanza VALUES('G71','5','Vom Verherrlichten im Himmel<br/>Kam der allumfassende Geist;<br/>Jesu Werk und auch Sein Wesen<br/>Uns der Geist stets unterweist.<br/>',NULL,46251,5);
INSERT INTO stanza VALUES('G71','6','Eins mit Ihm im Himmel ist nun<br/>Die Gemeinde, Seine Braut;<br/>Durch den kostbarn Geist von Jesus<br/>Sind die Glieder aufgebaut.<br/>',NULL,46252,6);
INSERT INTO stanza VALUES('G71','7','Sieh! Ein Mensch jetzt in den Himmeln<br/>Sitzt als Höchster auf dem Thron;<br/>Jesus Christus, unser Retter,<br/>Herrlichkeit ist Seine Kron.<br/>',NULL,46253,7);
INSERT INTO stanza VALUES('G72','1','Du, Jesus, bist der höchste Herr,<br/>Gekrönt mit Herrlichkeit;<br/>In Macht und Majestät bist Du<br/>Geachtet weit und breit.<br/>',NULL,46254,1);
INSERT INTO stanza VALUES('G72','2','Als Gott im Mensch hier lebtest Du,<br/>Uns dientest wie ein Knecht;<br/>Als Mensch in Gott im Himmel jetzt,<br/>Als aller Herr zu Recht.<br/>',NULL,46255,2);
INSERT INTO stanza VALUES('G72','3','Du bist der Mensch in Herrlichkeit<br/>Und auf den Thron gesetzt;<br/>Im Himmel und auf Erden hast<br/>Du alle Vollmacht jetzt.<br/>',NULL,46256,3);
INSERT INTO stanza VALUES('G72','4','Im Himmel bist Du hoch erhöht,<br/>Du hast den höchsten Nam''n.<br/>Bald jeder Dich bekennt als Herr,<br/>Sich beugt vor Deinem Nam ''n.<br/>',NULL,46257,4);
INSERT INTO stanza VALUES('G72','5','Gott machte Dich zum Christus, Herrn,<br/>Der Geist zeigt''s allezeit;<br/>Mit Gott sitzt Du auf Seinem Thron,<br/>In Himmels-Herrlichkeit.<br/>',NULL,46258,5);
INSERT INTO stanza VALUES('G72','6','Dir, Herr der Herrlichkeit, sei Ehr,<br/>Lobpreis zu Dir reich fließt,<br/>Wir singen Dir; Du, höchster Herr,<br/>Anbetung würdig bist.<br/>',NULL,46259,6);
INSERT INTO stanza VALUES('G73','1','Du, Herr, Gesalbter Gottes,<br/>Der höchste König bist!<br/>Wir beten an, zu Dir nun<br/>All unser Lobpreis fließt!<br/>Dein Königreich bleibt ewig,<br/>Gefestigt ist Dein Thron!<br/>Du herrschst gerecht in Liebe,<br/>Du herrliche Person!<br/>',NULL,46260,1);
INSERT INTO stanza VALUES('G73','2','Auf Gottes Berg, auf Zion,<br/>Hat Gott bestätigt Dich,<br/>Und gab Dir alle Völker<br/>Als Erbe ewiglich.<br/>Dir gab Gott alle Vollmacht<br/>Und Seine Herrlichkeit,<br/>Die Völker zu regieren<br/>In alle Ewigkeit.<br/>',NULL,46261,2);
INSERT INTO stanza VALUES('G73','3','Noch vor der Zeit der Fülle<br/>Wenn Dunkelheit herrscht hier,<br/>Zehntausend täglich bringen<br/>Lobpreis und Ehre Dir.<br/>Es lieben Dich von Herzen<br/>Erlöste nah und fern,<br/>Sie beten an und dienen<br/>Dem Retter-König gern.<br/>',NULL,46262,3);
INSERT INTO stanza VALUES('G73','4','Wenn zur bestimmten Zeit Du<br/>In Herrlichkeit triffst ein,<br/>Dann die bewohnte Erde<br/>Dein Königreich wird sein.<br/>Dem König jeder dient nun<br/>In Majestät und Pracht,<br/>Und jedes Volk anbetet,<br/>Dich preist mit aller Macht.<br/>',NULL,46263,4);
INSERT INTO stanza VALUES('G74','1','Du bist höchster König, Herr,<br/>Vor Dich kommen wir mit Ehr,<br/>Beten Dich, Gesalbten, an,<br/>Stimmen nun in Ehrfurcht an.<br/>Höchster König, Du bist''s Wert,<br/>Unser Herz Dich preist und ehrt!<br/>',NULL,46264,1);
INSERT INTO stanza VALUES('G74','2','Deine Vollmacht, Deine Kraft<br/>Überall sich Sieg verschafft!<br/>Alles dient, o Majestät,<br/>Dir in der Autorität!<br/>Höchster König, Du bist''s Wert,<br/>Unser Herz Dich preist und ehrt!<br/>',NULL,46265,2);
INSERT INTO stanza VALUES('G74','3','Über allem steht Dein Reich,<br/>Deinem Thron kommt keiner gleich!<br/>Deine Kraft und Herrlichkeit<br/>Rühmen wir in Ewigkeit!<br/>Höchster König, Du bist''s Wert,<br/>Unser Herz Dich preist und ehrt!<br/>',NULL,46266,3);
INSERT INTO stanza VALUES('G74','4','Souveräner König, Herr,<br/>Deinem Namen sei die Ehr!<br/>Ja, Dein Reich, Herr, lieben wir,<br/>Bring''s in Fülle bald mit Dir!<br/>Höchster König, Du bist''s Wert,<br/>Unser Herz Dich preist und ehrt!<br/>',NULL,46267,4);
INSERT INTO stanza VALUES('G75','1','Oh, wie tief ist Deine Liebe,<br/>Und so weit reicht sie, o Herr!<br/>Den Verstand weit übersteigend,<br/>Tiefer ist sie als das Meer!<br/>Sie ließ Dich den Tod erleiden,<br/>Teilt Dich aus in mich hinein;<br/>Du willst mich in Dich einpfropfen,<br/>Teil von Dir darf ich nun sein.<br/>',NULL,46268,1);
INSERT INTO stanza VALUES('G75','2','Wer fasst alle Wunder, welche<br/>Deine Liebe hat vollbracht?<br/>Doch das größte dieser Wunder:<br/>Sie hat Dich zu mir gebracht.<br/>Deine Liebe bringt Versorgung,<br/>Gibt mir alles, was Du bist;<br/>Ich hab Teil an Deinem Leben,<br/>Und Dein Reichtum ewig fließt.<br/>',NULL,46269,2);
INSERT INTO stanza VALUES('G75','3','Deine Liebe ist der Ausdruck<br/>Deiner liebenden Person;<br/>Füllt mein Leben mit Bedeutung,<br/>Macht mich eins mit Gottes Plan.<br/>Deine Gnade, allgenügend,<br/>Ist mein Anteil allezeit;<br/>Deine Gunst hat mich gefunden,<br/>Süß schmeckt Deine Lieblichkeit.<br/>',NULL,46270,3);
INSERT INTO stanza VALUES('G75','4','Was kann mich von Dir denn trennen?<br/>Du liebst mich doch ohne End!<br/>Deine Liebe ist so wirksam<br/>Sie hat Dich mit mir vermengt!<br/>Du und ich sind eins auf ewig,<br/>Ich bin Dein und Du bist mein!<br/>Dies ist ewiglich mein Zeugnis:<br/>Deine Liebe uns vereint!<br/>',NULL,46271,4);
INSERT INTO stanza VALUES('G76','1','Erkenntnis fasst, Herr, Deine Liebe nicht,<br/>Mein Retter Jesus, dennoch schenk mir Sicht;<br/>Lass Deine Liebe –die so lang und breit,<br/>So hoch, so tief, so stark ist allezeit –<br/>Mich sehn noch mehr.<br/>',NULL,46272,1);
INSERT INTO stanza VALUES('G76','2','Berichte fassen Deine Liebe nicht,<br/>Mein Retter Jesus; dennoch ich bericht<br/>Den Sündern nah und fern, dass Er vergab,<br/>Und Seine Liebe Sündenfurcht wäscht ab<br/>Und Liebe zeugt.<br/>',NULL,46273,2);
INSERT INTO stanza VALUES('G76','3','Mein Preisen fasst, Herr, Deine Liebe nicht,<br/>Mein Retter Jesus, doch mein Herz nun spricht<br/>Von Deiner großen Liebe und davon,<br/>Wie sie mich, Sünder, voller Rebellion,<br/>Bringt nah zu Gott.<br/>',NULL,46274,3);
INSERT INTO stanza VALUES('G76','4','Wenn ich nicht singen, kennen, reden kann<br/>Von Deiner Liebe, jedoch fang ich an;<br/>Frei bring ich mein Gefäß, so leer, zu Dir;<br/>Als Quell der Liebe fließe frei zu mir,<br/>Füll mein Gefäß!<br/>',NULL,46275,4);
INSERT INTO stanza VALUES('G76','5','Leer bin ich, habe nie an Dich gedacht,<br/>Noch einen Blick der Liebe Dir gebracht;<br/>Doch immer wieder komme ich zu Dir,<br/>Ja, dieses Recht zu kommen gibst Du mir,<br/>Weil Du mich liebst.<br/>',NULL,46276,5);
INSERT INTO stanza VALUES('G76','6','Mit Deiner Liebe, Retter, füll mein Sein!<br/>Als Lebensquelle nimm mein Herz ganz ein;<br/>Im Glauben will ich mich Dir nahen schlicht,<br/>Zu einer andern Quelle flieh ich nicht,<br/>Als nur zu Dir.<br/>',NULL,46277,6);
INSERT INTO stanza VALUES('G76','7','Herr Jesus, sehe ich Dein Angesicht,<br/>Wenn auf dem hohen Thron mit Dir ich sitz,<br/>Von Deiner Liebe – die so lang und breit,<br/>So hoch, so tief, so stark ist allezeit –<br/>Singt dann mein Herz.<br/>',NULL,46278,7);
INSERT INTO stanza VALUES('G77','1','Lobe den Herrn, den Allmächtigen, König der Schöpfung!<br/>Lob Ihn, o Seele, denn Er ist dein Heil und Errettung!<br/>Ihr, die ihr hört,<br/>Zu Seinem Tempel nun geht;<br/>Lasset den Lobgesang hören!<br/>',NULL,46279,1);
INSERT INTO stanza VALUES('G77','2','Lobe den Herren, der alles so herrlich regieret,<br/>Der dich auf Adelers Fittichen sicher geführet,<br/>Der dich erhält,<br/>Wie es dir selber gefällt;<br/>Hast du nicht dieses verspüret?<br/>',NULL,46280,2);
INSERT INTO stanza VALUES('G77','3','Lobe den Herren, der künstlich und fein dich bereitet,<br/>Der die Gesundheit verliehen, dich freundlich begleitet!<br/>In wieviel Not<br/>Hat nicht der gnädige Gott<br/>Über dich Flügel gebreitet!<br/>',NULL,46281,3);
INSERT INTO stanza VALUES('G77','4','Lobe den Herren, der sichtbar dein Leben gesegnet,<br/>Der aus dem Himmel mit Strömen der Liebe geregnet.<br/>Denke daran,<br/>Was der Allmächtige kann,<br/>Der dir mit Liebe begegnet.<br/>',NULL,46282,4);
INSERT INTO stanza VALUES('G77','5','Lobe den Herren, was in mir ist, lobe den Namen!<br/>Lob Ihn mit allen, die Seine Verheißung bekamen!<br/>Er ist dein Licht,<br/>Seele, vergiß es ja nicht;<br/>Lob Ihn in Ewigkeit, Amen!<br/>',NULL,46283,5);
INSERT INTO stanza VALUES('G78','1','Du, Herr, für Gott bist kostbar,<br/>Erwählt, geliebt dazu;<br/>Gesalbt mit Öl der Freude,<br/>Wie anmutig bist Du!<br/>',NULL,46284,1);
INSERT INTO stanza VALUES('G78','chorus','Wir schätzen innig Deine<br/>Vollkommene Schönheit,<br/>Dein''n Duft und Deine Süße,<br/>All Deine Lieblichkeit.<br/>',NULL,46285,2);
INSERT INTO stanza VALUES('G78','2','An Dir ist alles lieblich,<br/>Der Schönste unter vieln!<br/>Dein Mund fließt voller Gnade;<br/>Das Herz uns bersten will.<br/>',NULL,46286,3);
INSERT INTO stanza VALUES('G78','3','Die Weisen gaben Schätze,<br/>Sie ehrten Dich, o Gott;<br/>Vom Adligen begraben,<br/>Gar lieblich selbst im Tod.<br/>',NULL,46287,4);
INSERT INTO stanza VALUES('G78','4','Dein Haupt, Herr, wurd gesalbet,<br/>Der Lieblichste bist Du;<br/>Gesalbt auch Deine Füße,<br/>Gesegnet immerzu.<br/>',NULL,46288,5);
INSERT INTO stanza VALUES('G78','5','Dein Tod, so süß wie Myrrhe,<br/>Mit Trost uns sanft erfüllt;<br/>Dein Auferstehungsduft, Herr,<br/>Das Sehnen Gottes stillt.<br/>',NULL,46289,6);
INSERT INTO stanza VALUES('G78','6','So schön wie Hennablüten,<br/>Vollkomm''ne Lieblichkeit;<br/>Wie Apfelbäume blühst Du,<br/>Trägst süße Frucht allzeit.<br/>',NULL,46290,7);
INSERT INTO stanza VALUES('G78','7','Wie Wein ist Deine Liebe,<br/>Dein Name Salböl ist;<br/>Als unser Fest der Liebe<br/>Du süße Wonne bist.<br/>',NULL,46291,8);
INSERT INTO stanza VALUES('G78','8','Wenn wir, Herr, an Dich denken,<br/>Wird unser Herz so warm;<br/>Wir schmecken Deine Süße,<br/>Und ruhn in Deinem Arm.<br/>',NULL,46292,9);
INSERT INTO stanza VALUES('G79','1','Liebster Bräutigam, Herr Jesus,<br/>Gott hat Dich für uns bestimmt;<br/>Dein Gemüt ist so gewinnend,<br/>Dass es unser Herz einnimmt!<br/>',NULL,46293,1);
INSERT INTO stanza VALUES('G79','2','Wir verehren Dich, Geliebter,<br/>Wer kennt Deine Kostbarkeit?<br/>Deine Liebe schätzen wir, Herr,<br/>Deine schöne Lieblichkeit.<br/>',NULL,46294,2);
INSERT INTO stanza VALUES('G79','3','Du bist schöner als der Schönste,<br/>Süßer als der beste Wein;<br/>Du bist sanft und Du bist gnädig,<br/>Wer kann jemals gleich Dir sein?<br/>',NULL,46295,3);
INSERT INTO stanza VALUES('G79','4','Dein Gewand ist voller Myrrhe,<br/>Deine Lippen Gnade ziert;<br/>Nun im Duft all Deiner Leiden<br/>Unser Herz sich ganz verliert.<br/>',NULL,46296,4);
INSERT INTO stanza VALUES('G79','5','Mit dem kostbarn Öl der Freude<br/>Hat Dich Gott gesalbt so reich;<br/>Aus den Elfenbeinpalästen<br/>Lob und Preis erschallt zugleich.<br/>',NULL,46297,5);
INSERT INTO stanza VALUES('G79','6','Gott hat Dich gesegnet ewig,<br/>Du hast uns den Sieg verschafft;<br/>In der Herrlichkeit nun thronst Du<br/>Voller Majestät und Kraft.<br/>',NULL,46298,6);
INSERT INTO stanza VALUES('G79','7','Du – die Sehnsucht der Nationen,<br/>Überall wirst Du verehrt;<br/>Du, der Höchste von Zehntausend,<br/>Bist all unsrer Liebe Wert.<br/>',NULL,46299,7);
INSERT INTO stanza VALUES('G80','1','Herr Jesus, warm wird''s uns ums Herz,<br/>Kommst Du uns in den Sinn;<br/>Wir sehnen uns entrückt zu sein<br/>In Kürze zu Dir hin!<br/>',NULL,46300,1);
INSERT INTO stanza VALUES('G80','chorus','So wie die schöne Hennablume<br/>Im Weinberg blüht, bist Du, mein Herr;<br/>Vollkommen Deine Schönheit ist,<br/>Mein Herz liebt Dich stets mehr!<br/>',NULL,46301,2);
INSERT INTO stanza VALUES('G80','2','Es gibt kein angemess''nes Lied,<br/>Das Deine Gnade preist;<br/>Kein Herz kann hier erfassen ganz,<br/>Welch Liebe Du erweist.<br/>',NULL,46302,3);
INSERT INTO stanza VALUES('G80','3','Doch was am meisten uns erfreut,<br/>Nicht Deine Liebe ist;<br/>Denn was uns ganz zufriedenstellt,<br/>Du, liebster Herr, Selbst bist.<br/>',NULL,46303,4);
INSERT INTO stanza VALUES('G80','4','Ja, Deine süße Lieblichkeit<br/>Für ewig bleibt bestehn;<br/>Im Himmel und auf Erden gibt''s<br/>Nichts Schöneres zu sehn.<br/>',NULL,46304,5);
INSERT INTO stanza VALUES('G81','1','Kann nicht genug Dich atmen, Herr,<br/>O milde, süße Luft;<br/>Den Duft der Myrte lieb ich sehr,<br/>Doch den der Henna noch vielmehr,<br/>Den Himmelsbalsam-Duft<br/>',NULL,46305,1);
INSERT INTO stanza VALUES('G81','2','Kann nicht genug anschauen Dich,<br/>Ich ja den Schönsten hab;<br/>Mein Herz zum Bersten übervoll,<br/>Stets Dein Gesicht mir strahlen soll,<br/>An Dir ich mich nun lab.<br/>',NULL,46306,2);
INSERT INTO stanza VALUES('G81','3','Kann nicht genug mich geben Dir,<br/>Mein Retter, Meister, Freund;<br/>Frei ausgehn wünsche ich mir nicht,<br/>Doch immer, ewig, williglich<br/>Dir dienen bis zum End.<br/>',NULL,46307,3);
INSERT INTO stanza VALUES('G81','4','Kann nicht genug lobpreisen Dich,<br/>Den schönsten Namen hier;<br/>Ein Lied voll Harmonie sing ich,<br/>Aus tiefstem Herzen inniglich,<br/>Voll Freude sing ich Dir.<br/>',NULL,46308,4);
INSERT INTO stanza VALUES('G81','5','Kann nicht genug erzähln von Dir,<br/>Mein Mund Dein Ruhm kundtut;<br/>Dein Herz, es schlägt so zart für mich,<br/>wenn Du mich ziehst so nah an Dich,<br/>Und sprichst: „''s ist alles gut“.<br/>(Die letzte zeile jeder Strophe wiederholen.)<br/>',NULL,46309,5);
INSERT INTO stanza VALUES('G82','1','Schönster Herr Jesus!<br/>Herrscher aller Enden!<br/>Gottes und des Menschen Sohn!<br/>Dich will ich lieben,<br/>Dich will ich ehren,<br/>Du, meiner Seele Freud und Kron!<br/>',NULL,46310,1);
INSERT INTO stanza VALUES('G82','2','Schön sind die Felder,<br/>Schön sind die Wälder,<br/>In der schönen Frühlingszeit;<br/>Jesus ist schöner,<br/>Jesus ist reiner,<br/>Der unser traurig Herz erfreut!<br/>',NULL,46311,2);
INSERT INTO stanza VALUES('G82','3','Schön leucht'' die Sonne,<br/>Schön leucht'' der Mond,<br/>Und die Sternlein allzumal;<br/>Jesus leucht'' schöner,<br/>Jesus leucht'' reiner<br/>Als alle Eng''l im Himmelssaal!<br/>',NULL,46312,3);
INSERT INTO stanza VALUES('G82','4','Alle die Schönheit<br/>Himmels und der Erden<br/>Ist verfasst in Dir allein;<br/>Nichts soll mir werden,<br/>Lieber auf Erden<br/>Als Du, der schönste Jesus mein.<br/>',NULL,46313,4);
INSERT INTO stanza VALUES('G83','1','Ehre dem Herrn erweist!<br/>Betet Ihn an und preist!<br/>Lobt Ihn und singt:<br/>Er trug für uns die Pein;<br/>Engel ehrn Ihn allein,<br/>Heilige stimmen ein:<br/>„Würdig das Lamm!“<br/>',NULL,46314,1);
INSERT INTO stanza VALUES('G83','2','Die um den Thron nun stehn,<br/>Lasst eure Freude sehn,<br/>Lobt Ihn und singt:<br/>Jesu Blut wäscht uns rein,<br/>Frieden mit Gott zieht ein,<br/>Tut dies kund Groß und Klein:<br/>„Würdig das Lamm!“<br/>',NULL,46315,2);
INSERT INTO stanza VALUES('G83','3','Eins mach uns Menschen, Herr,<br/>Dass wir Dir geben Ehr,<br/>Lobt Ihn und singt:<br/>Freudig in Christus preist,<br/>Und genießt Ihn im Geist,<br/>Kühn auf den Herrn verweist:<br/>„Würdig das Lamm!“<br/>',NULL,46316,3);
INSERT INTO stanza VALUES('G83','4','Wo immer ich auch bin<br/>Stets schlägt mein Herz für Ihm;<br/>Lobt Ihn und singt:<br/>Ehre zu Ihm nun fließt,<br/>Gnädig der König ist,<br/>Jubel sich reich ergießt,<br/>„Würdig das Lamm!“<br/>',NULL,46317,4);
INSERT INTO stanza VALUES('G84','1','Jesus, o Herr, Dich wir freudig erheben,<br/>Unser Lobpreis Deinen Thron nun berührt!<br/>In Deiner Gegenwart sind wir gesegnet,<br/>Dir nur, Herr Jesus, Anbetung gebührt.<br/>',NULL,46318,1);
INSERT INTO stanza VALUES('G84','chorus','Herr, Du bist würdig; Herr, Du bist würdig;<br/>Dir nur, Herr Jesus, Anbetung gebührt!<br/>In Deiner Gegenwart sind wir gesegnet,<br/>Dir nur, Herr Jesus, Anbetung gebührt!<br/>',NULL,46319,2);
INSERT INTO stanza VALUES('G84','2','Du, wahrer Gott, wurdest Mensch, Dich wir preisen,<br/>Tiefer als Engel, am Kreuz littest Qual;<br/>Du als der „Same der Frau“, lang verheißen,<br/>Standfest die Schlange zermalmt dort am Pfahl!<br/>',NULL,46320,3);
INSERT INTO stanza VALUES('G84','3','Welch eine Demut! – hast Dich überlassen<br/>Deinen Geschöpfen, sie kreuzigten Dich;<br/>Menschen Dich hassten, von Gott gar verlassen,<br/>Du scheutest Fluch und die Finsternis nicht.<br/>',NULL,46321,4);
INSERT INTO stanza VALUES('G84','4','Welch ein''n Triumph Du in Herrlichkeit feierst!<br/>Über den Tod waltet Dein Siegesstab!<br/>Was hindert uns, Deinen Sieg zu verkünden<br/>Über den Hades, den Tod und das Grab?<br/>',NULL,46322,5);
INSERT INTO stanza VALUES('G85','1','O Herr, unsre Hallelujas<br/>Steigen auf vermehrt.<br/>Worte können nicht gebührend<br/>Rühmen Deinen Wert.<br/>',NULL,46323,1);
INSERT INTO stanza VALUES('G85','chorus','Preist das Lamm, denn Es ist würdig!<br/>Ewig bleibt bestehn.<br/>Halleluja! Halleluja!<br/>Preist den Herrn! Amen.<br/>',NULL,46324,2);
INSERT INTO stanza VALUES('G85','2','Preist das Lamm! Denn Es ist würdig,<br/>Uns erlöst vom Tod;<br/>Durch Sein Blut zu Königen<br/>Und Priestern macht für Gott!<br/>',NULL,46325,3);
INSERT INTO stanza VALUES('G85','3','Halleluja! Gottes Liebe<br/>Fließt so reich aus Dir;<br/>Wir gehören Dir für ewig,<br/>Eins mit Dir sind wir.<br/>',NULL,46326,4);
INSERT INTO stanza VALUES('G85','4','Preist den Herrn! Ja, halleluja!<br/>Er ist''s Wert allein.<br/>Singt mit allen Heil''gen freudig,<br/>Völker, stimmt mit ein!<br/>',NULL,46327,5);
INSERT INTO stanza VALUES('G86','1','Geliebter Sohn des Vaters,<br/>Das Bild Gottes bist Du;<br/>Und Du bist unser Anteil,<br/>Dein Blut teilt es uns zu.<br/>Du, Herr, der Erstgeborne<br/>Von aller Schöpfung bist;<br/>Durch Dich erschuf Gott alles,<br/>Alles ist Dein Besitz.<br/>',NULL,46328,1);
INSERT INTO stanza VALUES('G86','2','Du bist vor aller Schöpfung,<br/>Ja, alles ist in Dir;<br/>Du bist von all''m das Zentrum,<br/>Hältst alles aufrecht hier.<br/>Du bist allein der Anfang,<br/>Aus Toten Erstgeborn;<br/>Das Haupt für die Gemeinde,<br/>Dein Leib, von Dir erkorn.<br/>',NULL,46329,2);
INSERT INTO stanza VALUES('G86','3','In Dir wohnt alle Fülle,<br/>Dem Vater es gefiel;<br/>Dass Du den ersten Platz hast<br/>In allem, ist Sein Ziel.<br/>Mit Gott Dein Blut hat alles<br/>Versöhnt, das für es floss,<br/>Um uns vor Gott zu stellen<br/>So heilig, makellos.<br/>',NULL,46330,3);
INSERT INTO stanza VALUES('G86','4','Du bist Gottes Geheimnis,<br/>Die Fülle wohnt in Dir,<br/>Die Schätze aller Weisheit<br/>Und Kenntnis sind in Dir.<br/>In uns wohnst Du als Hoffnung,<br/>O Herr, der Herrlichkeit;<br/>In Dir sind wir vollendet –<br/>Für Gott Zufriedenheit.<br/>',NULL,46331,4);
INSERT INTO stanza VALUES('G86','5','Ein Schatten – alle Dinge,<br/>Die Dich enthüllen klar,<br/>In Dir sind wir verwurzelt;<br/>Nur Du bist echt und wahr.<br/>Wir werden Deine Fülle,<br/>Denn Dich genießen wir,<br/>Wir halten uns am Haupt fest,<br/>So wachsen wir in Dir.<br/>',NULL,46332,5);
INSERT INTO stanza VALUES('G86','6','Mit Dir in Gott verborgen<br/>Ist unser Leben, Herr;<br/>In uns regiert Dein Friede,<br/>Nun kämpfen wir nicht mehr.<br/>Im neuen Menschen bist Du<br/>Der Allumfassende;<br/>Als alles und in allem<br/>Dich preisen wir, o Herr!<br/>',NULL,46333,6);
INSERT INTO stanza VALUES('G87','1','Wir denken nun an Dich, o Herr,<br/>Ehrn Dich für alles, was Du bist;<br/>Du bist so reich, so wunderbar,<br/>In unsern Herzen fließt Du süß.<br/>',NULL,46334,1);
INSERT INTO stanza VALUES('G87','chorus','Was Du bist, Herr, uns ganz genügt!<br/>Dir unsrem Herzen Lob entquillt!<br/>Du stellst uns voll und ganz zufrieden,<br/>Du bist''s, der unsre Sehnsucht stillt.<br/>',NULL,46335,2);
INSERT INTO stanza VALUES('G87','2','Du bist der wahre Gott, o Herr,<br/>Der Gott, der unser Leben ist;<br/>Der Gott, der Liebe ist und Licht,<br/>Der Gott, der unsre Freude ist.<br/>',NULL,46336,3);
INSERT INTO stanza VALUES('G87','3','Doch Du bist auch ein wahrer Mensch,<br/>Ein Mensch so fein und gut gesinnt;<br/>Ein Mensch, an dem Gott hat Gefallen,<br/>Ein Mensch, der unser Herz gewinnt.<br/>',NULL,46337,4);
INSERT INTO stanza VALUES('G87','4','Du bist sogar ein Sklave, Herr,<br/>Als Knecht zu dienen ganz bereit;<br/>Gehorsam bis zum Tod am Kreuz,<br/>Dort hast Du uns vollauf befreit.<br/>',NULL,46338,5);
INSERT INTO stanza VALUES('G87','5','Dazu bist Du ein König, Herr,<br/>Im Leben und in Liebe lenkst;<br/>Von Gott gesalbt mit Seiner Kraft,<br/>Mit uns zu herrschen Du gedenkst.<br/>',NULL,46339,6);
INSERT INTO stanza VALUES('G87','6','Gedenken wir in Liebe Dein,<br/>Wir haben teil an was Du bist;<br/>Wir sind zudem Dein Gegenüber,<br/>Das voller Liebe Dich genießt.<br/>',NULL,46340,7);
INSERT INTO stanza VALUES('G88','1','Du, der „Same einer Frau“, Herr,<br/>Hast den Feind zermalmt allein;<br/>Menschliche Natur Dein Kleid war,<br/>Du starbst, siegreich dann zu sein.<br/>Als der Fleisch geword''ne Gott Du<br/>Fleisch und Blut getragen hast;<br/>Durch den Tod zermalmt den Teufel,<br/>Keine Todesmacht Dich fasst.<br/>',NULL,46341,1);
INSERT INTO stanza VALUES('G88','2','Du als „Same Abrahams“ kamst,<br/>Wie''s im Wort geschrieben ist,<br/>Der verheiß''ne Segen Gottes<br/>So zu allen Völkern fließt.<br/>Herr, Du bist der große „ICH BIN“,<br/>Du warst schon vor Abraham;<br/>Doch Du kamst als Sein Nachkomme,<br/>Und als das verheißne „Lamm“.<br/>',NULL,46342,2);
INSERT INTO stanza VALUES('G88','3','Herr, Du bist der „Same Davids“,<br/>Du kamst für das Königreich,<br/>Gottes Bau und Herrlichkeiten,<br/>Auf den Thron gesetzt siegreich.<br/>Der „Nachkomme Davids“ bist Du,<br/>Doch „mein Herr“ er nannte Dich;<br/>Du bist seine Quell und „Wurzel“,<br/>Auch „Herr aller“ ewiglich.<br/>',NULL,46343,3);
INSERT INTO stanza VALUES('G88','4','Du bist als „ein Kind“ geboren,<br/>Doch als „starker Gott“ bekannt;<br/>Uns als „Sohn“ gegeben wurdest,<br/>„Ew''ger Vater“ gar genannt.<br/>Wir empfangen Gottes Segen<br/>Durch den Glauben, Herr, an Dich;<br/>Du bist Inhalt und das Ende,<br/>„Ja“ und „Amen“ ewiglich!<br/>',NULL,46344,4);
INSERT INTO stanza VALUES('G89','1','Du bist so allumfassend, Herr,<br/>Für uns bist Du so viel;<br/>Was Du bist, uns vollauf versorgt,<br/>Und bringst uns hin zum Ziel.<br/>Dich schätzen wir im Herzen sehr,<br/>Im Geist verehrn wir Dich;<br/>Wenn Deinen Reichtum sehen wir,<br/>Dich preisen ewiglich.<br/>',NULL,46345,1);
INSERT INTO stanza VALUES('G89','2','Erweckt von Gott als der Prophet,<br/>Für Gott sprichst Du mit Macht;<br/>Wie Mose zeigst Du Gottes Plan,<br/>Wir geben darauf Acht.<br/>Der wahre Jona bist Du, Herr,<br/>Dein Tod zum Leben führt;<br/>Durch dieses Zeichen glauben wir,<br/>Im Herzen sind berührt.<br/>',NULL,46346,2);
INSERT INTO stanza VALUES('G89','3','Erweckt aus Menschen als Prophet<br/>Sprichst Du mit Licht und Kraft;<br/>Tust Wunder wie Elisa einst,<br/>In Liebe, tugendhaft.<br/>Du, wie Jesaja, voller Gnad,<br/>Machst Christus offenbar;<br/>Dass Er zu unserm Anteil wird<br/>Als Leben reich und wahr.<br/>',NULL,46347,3);
INSERT INTO stanza VALUES('G89','4','Du bist ein heil''ger Priester, denn<br/>Du gehst von uns zu Gott;<br/>Wie Aaron Du berufen bist,<br/>Und dienst in aller Not.<br/>In Liebe trägst Du uns zu Gott<br/>Als Hoher Priester dienst;<br/>Mit Liebe stehst Du für uns ein,<br/>Mit Deiner Kraft uns hältst.<br/>',NULL,46348,4);
INSERT INTO stanza VALUES('G89','5','Als königlicher Priester, Herr,<br/>Von Gott für uns kamst Du;<br/>Wie Salems Melchisedek einst<br/>Versorgst Du immerzu.<br/>Mit Brot und Wein kamst Du von Gott<br/>Zu uns zur rechten Zeit;<br/>Du kamst mit Gott und stelltest uns<br/>Als Anteil Ihn bereit.<br/>',NULL,46349,5);
INSERT INTO stanza VALUES('G89','6','Wie David bist Du König, Herr,<br/>Nur Gottes Wunsch drängt Dich;<br/>Im Kampf hast Du den Feind besiegt,<br/>Und Gottes Herz freut sich.<br/>Von Gott und nicht von Menschen, Herr,<br/>Regierst Du auf dem Thron,<br/>Und so herrschst Du für uns und Gott,<br/>Du herrliche Person.<br/>',NULL,46350,6);
INSERT INTO stanza VALUES('G89','7','Als König wie einst Salomo<br/>Der Friede füllt Dein Reich;<br/>In Weisheit und in Kraft führst Du,<br/>Baust Gottes Haus zugleich.<br/>Als unsichtbarer König Du<br/>Uns liebevoll regierst;<br/>Das Zepter führst Du bald mit uns,<br/>Als König sichtbar wirst.<br/>',NULL,46351,7);
INSERT INTO stanza VALUES('G89','8','Als König, Priester und Prophet,<br/>Wie kostbar bist Du, Herr!<br/>Wir lieben Deinen großen Wert<br/>Für Gott und uns so sehr.<br/>Wir schätzen alles, was Du bist,<br/>Zu Dir zieht''s uns allzeit;<br/>So dankbar unsre Herzen sind<br/>In alle Ewigkeit.<br/>',NULL,46352,8);
INSERT INTO stanza VALUES('G90','1','Viel besser, Herr, zeugst Du von Gott<br/>Als das Gesetz es kann;<br/>Einst im Gesetz, in Stein geritzt,<br/>Dein Bild die Menschen sahn.<br/>Ja, es beschreibt den Vater, Gott,<br/>Und Gottes Bild zeigt auf;<br/>Doch Gottes Wirklichkeit bist Du,<br/>In Dir wohnt Gott vollauf.<br/>',NULL,46353,1);
INSERT INTO stanza VALUES('G90','2','Die Bundeslade ebenso<br/>Ein Sinnbild war von Dir;<br/>Gesetzestafeln sie enthielt,<br/>Doch Gott in Dir sehn wir.<br/>Gefertigt aus Akazienholz,<br/>Mit Gold so fein umhüllt,<br/>Ein Bild, das Dich als Menschen zeigt,<br/>So reich mit Gott erfüllt.<br/>',NULL,46354,2);
INSERT INTO stanza VALUES('G90','3','O welch Stiftshütte, heilig, rein!<br/>Du Gottes Wohnung bist;<br/>In Dir, dem Fleischgewordenen,<br/>Die Gnade, Wahrheit fließt.<br/>Die Herrlichkeit strahlt klar in Dir,<br/>Du bist auch Gottes Wort;<br/>In Deinem Licht und Leben zeigst<br/>Du Gott ja immerfort.<br/>',NULL,46355,3);
INSERT INTO stanza VALUES('G90','4','Der Tempel war ein Bild auf Dich;<br/>Du Selbst bist Gottes Haus;<br/>Gott wohnt in Dir, verherrlicht Sich,<br/>Teilt Seine Fülle aus.<br/>Obwohl Dich Satan schlug ans Kreuz,<br/>Im Hades kehrt''st Du ein,<br/>In Auferstehung baust Du jetzt,<br/>Ein Größres wird es sein.<br/>',NULL,46356,4);
INSERT INTO stanza VALUES('G90','5','Die Stadt zeigt Deine Fülle auf,<br/>Ein Bild auf Deine Braut,<br/>Dein voller Zuwachs ist die Stadt,<br/>Die nur auf Dich vertraut.<br/>In Dir ist Gott das helle Licht,<br/>Du Selbst die Lampe bist;<br/>Durch Dich scheint Gott auf Groß und Klein,<br/>Welch Herrlichkeit dies ist!<br/>',NULL,46357,5);
INSERT INTO stanza VALUES('G90','6','Die Bundeslade, das Gesetz,<br/>Stiftshütte zeigen Dich;<br/>Der Tempel und die heil''ge Stadt<br/>Bist Du Selbst ewiglich.<br/>Vom Rad die Nabe und der Rand,<br/>Du bist uns alles, Herr!<br/>In Dir zu sehn ist Gott und Mensch,<br/>Wir lieben Dich so sehr!<br/>',NULL,46358,6);
INSERT INTO stanza VALUES('G91','1','Herr, Du bist alle Opfer,<br/>Gott stellt sie uns bereit;<br/>Reich sind sie an Bedeutung,<br/>Und voller Herrlichkeit.<br/>Sie haben Gottes Vorsatz<br/>Erfüllt und groß gemacht;<br/>Auch alle unsre Wünsche<br/>Gestillt sind und vollbracht.<br/>',NULL,46359,1);
INSERT INTO stanza VALUES('G91','2','Das heil''ge Feuer hat Dich<br/>Als Brandopfer verzehrt;<br/>Nun steigt Dein süßer Duft auf,<br/>Erfüllt was Gott begehrt.<br/>Für Gott Du absolut warst,<br/>Gehorsam, voller Fleiß;<br/>Du, makelloses Opfer,<br/>Dienst Gott für uns als Speis.<br/>',NULL,46360,2);
INSERT INTO stanza VALUES('G91','3','Herr, Du auch das Speisopfer<br/>Mit „Öl“ und „Weihrauch“ bist;<br/>Das heilig, fein, vollkommen,<br/>Und voller Süße ist.<br/>Du bist das Friedensopfer;<br/>Welch Friede nun besteht,<br/>Sodass es reiche Speise<br/>Für Gott und uns gewährt!<br/>',NULL,46361,3);
INSERT INTO stanza VALUES('G91','4','Herr, Du bist das Sündopfer,<br/>Zur Sünde gar gemacht;<br/>Am Kreuz hast Du bezahlt und<br/>Erlösung so vollbracht.<br/>Als Übertretungsopfer<br/>Trugst Du die Sünden, Herr,<br/>Du Gottes Recht besänftigt;<br/>Vergeben nun kann Er.<br/>',NULL,46362,4);
INSERT INTO stanza VALUES('G91','5','Du, Herr, bist das Schwingopfer,<br/>Der Auferstandene;<br/>Du hast besiegt den Hades,<br/>Der Tod besteht nicht mehr.<br/>Herr, Du bist das Hebopfer,<br/>Jetzt aufgefahrn zu Gott;<br/>Du, Herr, im Himmel droben<br/>Nährst uns als Gottes Brot.<br/>',NULL,46363,5);
INSERT INTO stanza VALUES('G92','1','Bilder und Symbole zeigen<br/>Deine Allumfassendheit;<br/>Doch sie waren nur ein Schatten,<br/>Du allein bist Wirklichkeit.<br/>Wenn wir solch ein Bild betrachten,<br/>Beten wir Dich staunend an,<br/>Preisen Dich für Deinen Reichtum,<br/>Großes hast Du, Herr, getan.<br/>',NULL,46364,1);
INSERT INTO stanza VALUES('G92','2','Du bist unser wahres Passah,<br/>Gott dank Dir vorüberging;<br/>Seit Du unsre Schuld bezahlt hast,<br/>Friedenszeit mit Gott anfing.<br/>Du, Lamm Gottes, hast erlöst uns,<br/>Ja, wir wenden an Dein Blut;<br/>Unsre wahre Speise bist Du,<br/>Liebster Herr, Du bist so gut.<br/>',NULL,46365,2);
INSERT INTO stanza VALUES('G92','3','Herr, Du bist das Brot des Lebens,<br/>Ungesäuert, heilig, rein;<br/>Wir vermengen uns durch Essen,<br/>Lassen unsre Sünden sein.<br/>Lamm und Brot als Bilder zeigen,<br/>Du bist unser Leben, Herr;<br/>Dich an Deinem Tisch verehrn wir,<br/>Und genießen Dich so sehr.<br/>',NULL,46366,3);
INSERT INTO stanza VALUES('G92','4','Herr, Du bist das Himmels-Manna,<br/>Täglich unsre Nahrung bist,<br/>Es schenkt Energie und kräftigt,<br/>Ganz zufriedenstellend ist.<br/>Fels mit Wasser voller Leben,<br/>Ließest Du, Herr, spalten Dich;<br/>Unsern Durst stillst Du mit Leben,<br/>Dich wir trinken ewiglich.<br/>',NULL,46367,4);
INSERT INTO stanza VALUES('G92','5','Das Land Kanaan bist Du, Herr,<br/>Hoch gelegen, gut und reich,<br/>Milch und Honig fließen herrlich;<br/>Welches Land kommt diesem gleich?<br/>Dieser Überfluss zu Lobpreis<br/>Und Gemeinschaft führt in Dir;<br/>So in Liebe fest verbunden,<br/>Stelln wir Gottes Bau aus hier.<br/>',NULL,46368,5);
INSERT INTO stanza VALUES('G93','1','Wie allumfassend, Herr, Du bist!<br/>Von Gott sind wir in Dir –<br/>Was Du für uns geworden bist,<br/>So sehr genießen wir.<br/>',NULL,46369,1);
INSERT INTO stanza VALUES('G93','2','Die Weisheit Gottes bist Du uns,<br/>Gott rettet uns durch Dich;<br/>Der Weg zur Rettung Du nur bist,<br/>Allein und ewiglich.<br/>',NULL,46370,2);
INSERT INTO stanza VALUES('G93','3','Du bist für uns Gerechtigkeit,<br/>Der Gottes Recht erfüllt;<br/>Wir alle sind gerecht in Dir,<br/>Ins beste Kleid umhüllt.<br/>',NULL,46371,3);
INSERT INTO stanza VALUES('G93','4','Herr, Du bist unsre Heiligkeit,<br/>Umwandlung brauchen wir;<br/>In Dir Du heiligst tadellos,<br/>Uns gleichgestaltest Dir.<br/>',NULL,46372,4);
INSERT INTO stanza VALUES('G93','5','Erlösung bist Du auch für uns,<br/>Dein Abbild unser wird;<br/>Verklären wirst Du unsern Leib,<br/>Von Freiheit sublimiert.<br/>',NULL,46373,5);
INSERT INTO stanza VALUES('G93','6','Wenn wir nun sinnen über Dich,<br/>Genießen Dich, den Herrn,<br/>So nähert sich Dein Kommen mehr,<br/>Du bleibst nicht lange fern.<br/>',NULL,46374,6);
INSERT INTO stanza VALUES('G93','7','Wie süß der Vorgeschmack doch ist,<br/>So herrlich und so reich!<br/>Wir sehnen uns bei Dir zu sein,<br/>In Füll erfahrn Dich.<br/>',NULL,46375,7);
INSERT INTO stanza VALUES('G94','1','Du bist der Baum des Lebens, Herr,<br/>Der uns versorgt so fein;<br/>Wer Dich als Frucht des Lebens isst,<br/>Wird nie mehr hungrig sein.<br/>',NULL,46376,1);
INSERT INTO stanza VALUES('G94','2','Der wahre Weinstock Gottes bist<br/>Du, unser Lebensquell;<br/>In Dir sind wir, Dich leben wir,<br/>Zur Ruh kommt unsre Seel.<br/>',NULL,46377,2);
INSERT INTO stanza VALUES('G94','3','Du, Herr, der Apfelbaum bist auch,<br/>So süß schmeckt Deine Frucht;<br/>In Deinem Schatten ruhen wir,<br/>Und Freude uns besucht.<br/>',NULL,46378,3);
INSERT INTO stanza VALUES('G94','4','Du machst das bittre Wasser süß,<br/>Das Holz, das heilt, bist Du;<br/>Am Kreuz gabst Du Dein Leben hin,<br/>Schenkst Heilung immerzu.<br/>',NULL,46379,4);
INSERT INTO stanza VALUES('G94','5','In Dir, Du wahrer Spross aus Gott,<br/>Die Fülle Gottes wohnt;<br/>Mit Gnade und mit Wirklichkeit<br/>Hast Du uns, Herr, belohnt.<br/>',NULL,46380,5);
INSERT INTO stanza VALUES('G94','6','Auch Davids Spross bist Du, o Herr,<br/>Der Fleisch geworden ist;<br/>In Dir die wahre Menschlichkeit<br/>Für uns erkennbar ist.<br/>',NULL,46381,6);
INSERT INTO stanza VALUES('G94','7','In Dir, dem Stab, der sprießt und blüht,<br/>Das Leben ewig fließt;<br/>Durch Deine Auferstehungskraft<br/>Der Tod verschlungen ist.<br/>',NULL,46382,7);
INSERT INTO stanza VALUES('G94','8','Elisas Holz im Fluss bist Du,<br/>Die „Axt“, die fiel, sind wir;<br/>Du hobst uns durch die Lebenskraft<br/>Aus Todeswassern hier.<br/>',NULL,46383,8);
INSERT INTO stanza VALUES('G94','9','Die „Pflanz des Ruhms“ bist Du, o Herr,<br/>So allumfassend reich;<br/>An Dich erinnern wir uns gern,<br/>Verkünden Dich zugleich!<br/>',NULL,46384,9);
INSERT INTO stanza VALUES('G95','1','Du bist der Fels immerwährend,<br/>Kostbar, gespalten für mich;<br/>Dich als den Geist möcht ich trinken,<br/>Eins mit Dir, Herr, werde ich.<br/>Auf diesen standhaften Felsen<br/>Sind wir gebaut fest in Dir;<br/>Mit Dir vereint durch Erlösung,<br/>Nichts kann erschüttern uns hier.<br/>',NULL,46385,1);
INSERT INTO stanza VALUES('G95','chorus','Wie schätzen wir Deinen Wert, Herr!<br/>Du schenkst uns das, was Du bist;<br/>Hier Dich mit Liebe besinnend,<br/>Jeder Dich schätzt und genießt.<br/>',NULL,46386,2);
INSERT INTO stanza VALUES('G95','2','Du bist der Stein vielgeprüft, Herr,<br/>Kostbar für uns immerdar,<br/>Sicher und immer verlässlich,<br/>Deine Kraft, so wunderbar.<br/>Als den lebendigen Stein, Herr,<br/>Hat Gott für uns Dich erwählt,<br/>Derart dynamisch und kräftig,<br/>Ewiges Leben uns hält.<br/>',NULL,46387,3);
INSERT INTO stanza VALUES('G95','3','Gott legte Dich als den Grundstein,<br/>Sicher und standfest bist Du;<br/>Das Fundament, so verlässlich,<br/>Sicherheit gibt immerzu.<br/>Niemand ein andres kann legen,<br/>Was es auch sei allezeit;<br/>Das Fundament bist nur Du, Herr,<br/>Nun und in all Ewigkeit.<br/>',NULL,46388,4);
INSERT INTO stanza VALUES('G95','4','Du bist der kostbare Eckstein<br/>Für Gottes geistlichen Bau,<br/>Juden und Heiden vermengt sind,<br/>Du nur vereinst sie genau.<br/>Herr, Du bist auch noch der Schlussstein,<br/>Den Gnade maßlos erweist;<br/>Herrlichkeit, unsre Bedeckung,<br/>Dich unser Herz lobt und preist.<br/>',NULL,46389,5);
INSERT INTO stanza VALUES('G96','1','Du, Sonne der Gerechtigkeit,<br/>Mit Deinen Flügeln heilst;<br/>Durchs Strahlen Deines Angesichts<br/>Uns Dich Du reich austeilst.<br/>',NULL,46390,1);
INSERT INTO stanza VALUES('G96','2','Barmherzig bist Du stets aufs Neu,<br/>In uns der Tag anbricht;<br/>Die Todesschatten fliehen weg,<br/>Im Finstern gibst uns Licht.<br/>',NULL,46391,2);
INSERT INTO stanza VALUES('G96','3','Der wolkenlose Morgen strahlt<br/>Wie Du, das Morgenlicht;<br/>Auf uns, das Gras der Erde, strahlt<br/>Dein frohes Angesicht.<br/>',NULL,46392,3);
INSERT INTO stanza VALUES('G96','4','Dein Licht wärmt unsre Herzen auf,<br/>Zu heilen uns vermag;<br/>Es scheint in uns stets mehr und mehr,<br/>Bis hin zum vollen Tag.<br/>',NULL,46393,4);
INSERT INTO stanza VALUES('G96','5','Die Sicht ist nach dem Regen klar,<br/>So ist Dein Licht im Leid;<br/>Es strahlt für uns so liebevoll,<br/>Teilt aus Barmherzigkeit.<br/>',NULL,46394,5);
INSERT INTO stanza VALUES('G96','6','Als Morgenstern erscheinst Du bald,<br/>Belohnung ewiglich;<br/>Noch finster ist''s, doch Du scheinst hell,<br/>Für die, die lieben Dich.<br/>',NULL,46395,6);
INSERT INTO stanza VALUES('G96','7','Dein Licht zu lieben hilf uns, Herr,<br/>Um klar zu sehn von fern;<br/>Wir warten wachend im Gebet<br/>Auf Dich, den Morgenstern.<br/>',NULL,46396,7);
INSERT INTO stanza VALUES('G97','1','Was ist Er? – Unser Vater.<br/>Er ist unser ew''ger Vater.<br/>Er der Schöpfung Erstgeborner ist.<br/>Und Er lebt in mir und überfließt.<br/>Welch ein Vater! Wunderbar!<br/>',NULL,46397,1);
INSERT INTO stanza VALUES('G97','2','Was ist Er? – Lebenswasser.<br/>Wie ein starker Strom des Lebens,<br/>Der mich tränkt in diesem Wüstenland.<br/>Er die Felskluft, wo ich Zuflucht fand.<br/>Welch ein Zustrom! Wunderbar!<br/>',NULL,46398,2);
INSERT INTO stanza VALUES('G97','3','Was ist Er? – Unser Weinstock.<br/>Und der Zweig, die Wurzel Jesses.<br/>Er – der Baum des Lebens: Welch Genuss,<br/>Jeder Ihn nun einfach essen muss.<br/>Welch ein Weinstock! Wunderbar!<br/>',NULL,46399,3);
INSERT INTO stanza VALUES('G97','4','Was ist Er? – Unser Hirte.<br/>Gottes Lamm und Bock der Sühnung.<br/>Er weidet uns so aufmerksam.<br/>Durch Sein Blut nun essen wir vom Lamm.<br/>Welch ein Hirte! Wunderbar!<br/>',NULL,46400,4);
INSERT INTO stanza VALUES('G97','5','Was ist Er? –Er ist Geist jetzt.<br/>Allumfassend als der Geist jetzt.<br/>Unser alles und so umfangreich.<br/>Schon beim Anrufen fließt Leben gleich.<br/>Welch ein Geist jetzt! Wunderbar!<br/>',NULL,46401,5);
INSERT INTO stanza VALUES('G97','6','Was ist Er? – Die Person.<br/>Eine wirkliche Person.<br/>Als Person lebt Er in uns allzeit,<br/>Und Er ist so voller Herrlichkeit!<br/>Welch Person! Wunderbar!<br/>',NULL,46402,6);
INSERT INTO stanza VALUES('G97','7','Was ist Er? – der Leib Christi.<br/>Und die ganze Füll der Gottheit.<br/>Im Plan Gottes Er zentral erscheint,<br/>Neuer Mensch, Christus und die Gemeind.<br/>Er ist wunderbar, wunderbar.<br/>',NULL,46403,7);
INSERT INTO stanza VALUES('G97','chorus','Er ist wunderbar, wunderbar.<br/>Er ist wunderbar, wunderbar.<br/>',NULL,46404,8);
INSERT INTO stanza VALUES('G98','1','Herr, unser Friedensopfer,<br/>Wir sind ganz eins mit Dir.<br/>Wir legen unsre Hände<br/>Auf Dich, das Opfertier.<br/>Hier im Versammlungszelt wolln<br/>Wir Dich Gott bringen dar;<br/>Für uns und für den Vater<br/>Bist Du ein Fest fürwahr.<br/>',NULL,46405,1);
INSERT INTO stanza VALUES('G98','chorus','Du, Christus, unser Friede bist!<br/>Hier im Versammlungszelt!<br/>Der Friede ist mit Gott und Mensch<br/>Nun wiederhergestellt.<br/>',NULL,46406,2);
INSERT INTO stanza VALUES('G98','2','Welch Friede uns durchflutet,<br/>Wenn wir das Blut hier sehn!<br/>Wir durch das Friedensopfer<br/>Mit Gott im Frieden stehn.<br/>Mit Freimut wolln wir kundtun –<br/>O Feind, nun hör gut zu –<br/>„Durch Jesu Blut ist Frieden!“<br/>Wir siegen immerzu.<br/>',NULL,46407,3);
INSERT INTO stanza VALUES('G98','3','Gestützt auf das Brandopfer<br/>Und das Speisopfer, wir<br/>Wolln Jesus nun darbringen<br/>Als Friedensopfer hier.<br/>Je mehr wir von Ihm essen<br/>In Seiner Menschlichkeit,<br/>Ihn korp''rativ zu festen<br/>Wird so zur Herrlichkeit.<br/>',NULL,46408,4);
INSERT INTO stanza VALUES('G98','chorus','Wie lieblich doch Gemeinschaft ist<br/>Mit Gott und Mensch zugleich!<br/>Oh, welche Freude, welch ein Fest<br/>Mit Gottes Volk, so reich!<br/>',NULL,46409,5);
INSERT INTO stanza VALUES('G98','4','Der innre, süße Teil nur<br/>Gott Selbst genießt bewusst,<br/>Der Priester mit den Seinen<br/>Isst die geschwungne Brust.<br/>Vom besten nur dem Priester,<br/>Der opfert, wird zuteil:<br/>Die rechte Hebe-Schulter<br/>Und Kuchen ist sein Teil.<br/>',NULL,46410,6);
INSERT INTO stanza VALUES('G98','5','Wie süß uns schmeckt die Schwingbrust<br/>Der Liebe, hoch gewebt,<br/>Von Christi Auferstehung!<br/>Wie sehr sie uns erhebt!<br/>Der aufgefahrne Herr als<br/>Die Schulter stärkt uns sehr;<br/>Uns stärken auch die Kuchen,<br/>Zu wandeln gleich wie Er.<br/>',NULL,46411,7);
INSERT INTO stanza VALUES('G98','6','In Dir sind wir gereinigt,<br/>Wir festen Dich, o Herr!<br/>Gemeinschaft, echt und wirklich,<br/>Erfreut uns alle sehr.<br/>Wir danken Dir von Herzen<br/>Und weihen uns nun Dir –<br/>So wie Du jetzt zu uns stehst<br/>Zu Deinem Werk stehn wir.<br/>',NULL,46412,8);
INSERT INTO stanza VALUES('G99','1','Herr, im Schoß des Vaters warst Du<br/>Lange vor Beginn der Zeit,<br/>Du der einziggeborne Sohn warst<br/>In des Vaters Herrlichkeit.<br/>Als der Vater Dich uns schenkte,<br/>Warst Du in Person Ihm gleich;<br/>Hast die Fülle Deines Vaters<br/>Kundgetan im Geist so reich.<br/>',NULL,46413,1);
INSERT INTO stanza VALUES('G99','2','Du durch Tod und Auferstehung<br/>Bist der erstgeborne Sohn;<br/>Die Verdopplung Deiner sind wir,<br/>Seit Dein Leben in uns wohnt.<br/>Wir in Dir sind neu geboren,<br/>Gottes Söhne wurden wir;<br/>Und als Deine vielen Brüder<br/>Gleich in der Natur sind Dir.<br/>',NULL,46414,2);
INSERT INTO stanza VALUES('G99','3','Einst warst Du das einzig Korn, Herr,<br/>In die Erde fielst und starbst,<br/>Dass durch Tod und Auferstehung<br/>Reich Du Zuwachs Dir erwarbst.<br/>Wir sind Deine vielen Körner,<br/>Gleich wie Du – gezeugt von Dir;<br/>Als ein Brotlaib, der vermengt ist,<br/>Deine Fülle zeigen wir.<br/>',NULL,46415,3);
INSERT INTO stanza VALUES('G99','4','Deine gänzliche Vermehrung,<br/>Deine Braut, Dein teurer Leib,<br/>Und Dein Ausdruck, Deine Fülle,<br/>Sind wir jetzt, in uns nun bleib.<br/>Du hast Dich durch uns verbreitet,<br/>Lebenszuwachs sind wir Dir,<br/>Als Dein Überfluss, Dein Wachstum,<br/>Eins mit Dir, o Haupt, sind wir.<br/>',NULL,46416,4);
INSERT INTO stanza VALUES('G100','1','Oh, Christus ist der Brunnen,<br/>So süß und tief und weit;<br/>Und Sein lebend''ges Wasser<br/>Befreit von Gram und Streit.<br/>Des Herrn Barmherzigkeit reicht<br/>Viel weiter als das Meer;<br/>So reich fließt Seine Gnade,<br/>Wie weise plante Er!<br/>',NULL,46417,1);
INSERT INTO stanza VALUES('G100','2','Oh, ich bin meines Liebsten,<br/>Mein Liebster – Er ist mein;<br/>Er bringt mich, armen Sünder,<br/>In Sein Haus voller Wein!<br/>Mein Stand ist einzig Christus,<br/>Nur diesen kenne ich.<br/>In Ihm bin ich geborgen,<br/>Und Seine Hand hält mich.<br/>',NULL,46418,2);
INSERT INTO stanza VALUES('G100','3','Die Braut schaut nicht ihr Kleid an,<br/>Doch nur den Bräutigam;<br/>Ich schau nicht Herrlichkeiten,<br/>Doch meinen König an.<br/>Ich schau nicht meine Krone,<br/>Doch die durchbohrte Hand;<br/>Dem Lamm gib alle Ehre,<br/>Es ist mein fester Stand!<br/>',NULL,46419,3);
INSERT INTO stanza VALUES('G101','1','O Jesus, Jesus, liebster Herr!<br/>Vergib mir, wenn ich sag<br/>Aus Liebe Deinen Namen oft,<br/>Gar tausendmal am Tag.<br/>',NULL,46420,1);
INSERT INTO stanza VALUES('G101','chorus','O Jesus Herr! Bleib Du bei mir,<br/>Was immer auch geschieht, o Herr;<br/>Dein Lächeln ist mein schönster Lohn;<br/>Ich lieb Dich, lieb Dich sehr!<br/>',NULL,46421,2);
INSERT INTO stanza VALUES('G101','2','Ich lieb Dich so, wie soll ich nur<br/>Mein Sehnen kontrolliern?<br/>Wie Feuer Deine Liebe brennt,<br/>In der ich mich verlier.<br/>',NULL,46422,3);
INSERT INTO stanza VALUES('G101','3','Herr, Du bist alles jetzt für mich,<br/>Mein Reichtum, Herrlichkeit;<br/>Mein Herzenswunsch und meine Kraft,<br/>Mein Seelenheil allzeit.<br/>',NULL,46423,4);
INSERT INTO stanza VALUES('G101','4','Brenn, brenn, o Liebe brenn in mir,<br/>Brenn heftig Tag und Nacht,<br/>Bis Wünsche, die nur irdisch sind,<br/>Zu Asche sind gemacht.<br/>',NULL,46424,5);
INSERT INTO stanza VALUES('G101','5','O Licht im Dunkeln, Freud im Leid,<br/>O Himmel hier auf Erd;<br/>Du liebster Jesus, teurer Schatz,<br/>Du bist mir alles wert.<br/>',NULL,46425,6);
INSERT INTO stanza VALUES('G101','6','Die Liebe keine Grenzen kennt,<br/>Sie ist so wunderbar!<br/>Der Herr ist süßer jeden Tag<br/>Als Er es gestern war.<br/>',NULL,46426,7);
INSERT INTO stanza VALUES('G102','1','Denk ich an Jesus, fließt der Dank<br/>In meinem Herzen reich;<br/>Süßer noch ist''s bei Dir zu sein,<br/>Ruhen bei Dir zugleich.<br/>',NULL,46427,1);
INSERT INTO stanza VALUES('G102','2','Süßeres niemand denken kann,<br/>Und gar nichts schöner klingt<br/>Als Dein geliebter Name, Herr,<br/>Rettung der Menschheit bringt!<br/>',NULL,46428,2);
INSERT INTO stanza VALUES('G102','3','Hoffnung und Freud bist Du für den,<br/>Der bringt der Buße Frucht,<br/>Gütig bist Du mit dem, der fällt!<br/>Wie gut zu dem, der sucht!<br/>',NULL,46429,3);
INSERT INTO stanza VALUES('G102','4','Und der, der findet, sprachlos ist,<br/>Es keine Worte gibt,<br/>Was Deine Liebe ist für den,<br/>Der Dich, o Retter, liebt.<br/>',NULL,46430,4);
INSERT INTO stanza VALUES('G102','5','O Jesus, Du bist unser Licht<br/>Leben aus Dir reich fließt!<br/>Du übersteigst die höchste Freud,<br/>Mehr als wir wünschen bist.<br/>',NULL,46431,5);
INSERT INTO stanza VALUES('G102','6','Kein andrer Quell hier haben wir,<br/>Der Seelendurst uns stillt;<br/>Wie unerschöpflich, reichlich, frei<br/>Das Lebenswasser quillt!<br/>',NULL,46432,6);
INSERT INTO stanza VALUES('G102','7','Du nur sollst unsre Freude sein,<br/>Und unsre Herrlichkeit;<br/>Du bist der schönste Lohn für uns,<br/>Jetzt und in Ewigkeit.<br/>',NULL,46433,7);
INSERT INTO stanza VALUES('G103','1','Wenn wir betrachten Deinen Tisch,<br/>Die Zeichen staunen an:<br/>Ein Laib von Brot, ein Kelch von Wein<br/>Uns zeigen Gottes Plan.<br/>',NULL,46434,1);
INSERT INTO stanza VALUES('G103','2','Der Laib stellt Brot des Lebens dar,<br/>Der Himmel speist uns hier;<br/>Durch Deinen Tod reichst Du es dar,<br/>Wir haben teil an Dir.<br/>',NULL,46435,2);
INSERT INTO stanza VALUES('G103','3','Der göttlich wunderbare Kelch<br/>Besteht aus Jesu Blut;<br/>Vom Kelch des Segens trinken wir,<br/>Und schmecken: Du bist gut.<br/>',NULL,46436,3);
INSERT INTO stanza VALUES('G103','4','Wir essen Dich, das Lebensbrot,<br/>Wenn wir das Brot austeiln;<br/>In Liebe denken wir an Dich,<br/>Genährt von Dir allein.<br/>',NULL,46437,4);
INSERT INTO stanza VALUES('G103','5','Den Segen, den gewonnen hast,<br/>Im Kelch genießen wir;<br/>Erinnern uns an Dich mit Freud,<br/>Bis Du uns nimmst zu Dir.<br/>',NULL,46438,5);
INSERT INTO stanza VALUES('G103','6','Wir feiern Brot und Kelch mit Dir,<br/>Verkünden Deinen Tod;<br/>„Bist unser Leben“ tun wir kund,<br/>Und stets versorgt uns Gott.<br/>',NULL,46439,6);
INSERT INTO stanza VALUES('G103','7','Wir warten nun auf jenen Tag,<br/>An dem in Fülle dann<br/>Aufs Neue feiern wir mit Dir<br/>Und ewig beten an.<br/>',NULL,46440,7);
INSERT INTO stanza VALUES('G104','1','Herr, für Deinen Tisch wir danken,<br/>Den Du deckst mit Brot und Wein;<br/>Göttlich ist Dein Fest der Liebe,<br/>Du nimmst unsre Herzen ein.<br/>Haben teil am Brot, dem Zeichen<br/>Für den Leib, den Du gabst her;<br/>Haben teil am Wein, dem Sinnbild<br/>Für Dein Blut, das floss, o Herr.<br/>',NULL,46441,1);
INSERT INTO stanza VALUES('G104','chorus','Seht den Tisch, so heilig!<br/>Mit den heil''gen Zeichen;<br/>Oh, wie unausforschlich ist der<br/>Sinn des Tisches, Herr!<br/>',NULL,46442,2);
INSERT INTO stanza VALUES('G104','2','Durch den Tod Deiner Erlösung<br/>Leben uns gegeben ist;<br/>Ja, Dich Selbst besitzen wir nun,<br/>Teilen alles, was Du bist.<br/>Wenn vom Brot und Wein wir nehmen,<br/>Zeugen wir von Deinem Tod;<br/>Wir erinnern uns an Dich, Herr,<br/>Voller Liebe immerfort.<br/>',NULL,46443,3);
INSERT INTO stanza VALUES('G104','3','Dieses Brot hier auf dem Tische<br/>Zeigt auch Deinen einen Leib;<br/>Durch das eine Band der Liebe<br/>Jedes Glied verbunden bleibt.<br/>Durch den heil''gen Kelch des Segens,<br/>Kelch des Weins, den segnen wir,<br/>Teil an Deinem Blut wir haben<br/>Mit all denen, die glauben hier.<br/>',NULL,46444,4);
INSERT INTO stanza VALUES('G104','4','Du bist ewig unser Anteil,<br/>Süßer Vorgeschmack schon hier;<br/>Auf das Königreich der Himmel<br/>Und Dein Kommen warten wir.<br/>Wenn in Deinem Reich Du kommest,<br/>Jeder wird, der überwind''t,<br/>Mit den Heil''gen neu Dich festen,<br/>Deine liebe Braut dann sind.<br/>',NULL,46445,5);
INSERT INTO stanza VALUES('G105','1','Wir danken Dir für dieses Brot,<br/>Welch Zeichen, göttlich rein!<br/>Oh, welch Geheimnis zeigt es auf<br/>Von Gottes Plan allein!<br/>',NULL,46446,1);
INSERT INTO stanza VALUES('G105','2','Das Brot bezeichnet Deinen Leib,<br/>Den Du für uns gabst hin,<br/>Nun teilst Du uns Dein Leben aus,<br/>Welch göttlicher Gewinn!<br/>',NULL,46447,2);
INSERT INTO stanza VALUES('G105','3','Für uns Dein Leib zerbrochen ward,<br/>Strömst nun in uns hinein;<br/>Durch Dich als Leben können wir<br/>Dein Gegenüber sein.<br/>',NULL,46448,3);
INSERT INTO stanza VALUES('G105','4','Das Brot bezeichnet außerdem<br/>Den Leib, der mystisch ist;<br/>Als Glieder sind wir gleich wie Du,<br/>Identisch, wie Du bist.<br/>',NULL,46449,4);
INSERT INTO stanza VALUES('G105','5','Die vielen Weizenkörner sind<br/>Doch nur ein Laib, ein Brot;<br/>So denken wir an Dich nun gern,<br/>Du nährst uns, treuer Gott.<br/>',NULL,46450,5);
INSERT INTO stanza VALUES('G105','6','Das Essen dieses Brotes, Herr,<br/>Uns voll zufriedenstellt;<br/>Wir lieben alle Heiligen,<br/>Bezeugen Dich der Welt.<br/>',NULL,46451,6);
INSERT INTO stanza VALUES('G106','1','Auf dem Tisch der Liebe steht<br/>Mit dem Brot der Kelch zugleich;<br/>Haben wir an diesen teil,<br/>Wir mit Dir versorgt sind reich.<br/>Dir sei Dank für diesen Kelch,<br/>Kelch des Segens, Liebster Herr;<br/>Voller Rettung ist der Kelch,<br/>Wie beschenkst Du uns doch sehr!<br/>',NULL,46452,1);
INSERT INTO stanza VALUES('G106','2','Er enthält das Blut, das floss,<br/>Zur Vergebung unsrer Schuld;<br/>Er ist auch der neue Bund,<br/>Voller Segen, voller Huld.<br/>Du trankst aus den Kelch des Zorns,<br/>Hast für uns geschmeckt den Tod;<br/>Kelch des Segens so erwarbst,<br/>Solch ein''n Anteil schenkt uns Gott.<br/>',NULL,46453,2);
INSERT INTO stanza VALUES('G106','3','Unser Anteil ist nun Gott,<br/>Der beim Fall ward eingebüßt;<br/>Dein vergossnes Blut bewirkt,<br/>Dass Gott uns nun alles ist.<br/>Die Erlösung, Leben und<br/>Friede sind im Anteil drin;<br/>Alles, was Gott für uns ist,<br/>Ist enthalten, welch Gewinn!<br/>',NULL,46454,3);
INSERT INTO stanza VALUES('G106','4','Dieser Kelch, der überfließt,<br/>Ewig unser Anteil ist;<br/>Welch ein süßer Vorgeschmack<br/>Himmlisch, rein, darin doch fließt!<br/>Hier in Liebe trinken wir,<br/>Denken nun an Dich fürwahr;<br/>Wir erinnern uns im Geist<br/>An Dein Werk auf Golgatha.<br/>',NULL,46455,4);
INSERT INTO stanza VALUES('G107','1','Wenn wir teilen nun den Kelch,<br/>Steigt zu Dir das Lob fürwahr;<br/>Denn Dein Blut gabst Du für uns,<br/>Dessen Wert ist unschätzbar.<br/>O wie kostbar ist Dein Blut!<br/>Es macht uns von Flecken rein;<br/>Durch Dein Blut, das wirksam ist,<br/>Zieht in uns der Friede ein.<br/>',NULL,46456,1);
INSERT INTO stanza VALUES('G107','2','Durch Dein teures Blut von Wert<br/>Kam das neue Testament;<br/>Für den bessren Bund ist es<br/>Ein ganz sich''res Fundament.<br/>Gott hat uns vollauf erlöst,<br/>Nicht mit Silber oder Gold,<br/>Sondern mit dem kostbarn Blut,<br/>Dem sei Liebe stets gezollt.<br/>',NULL,46457,2);
INSERT INTO stanza VALUES('G107','3','Zur Beseitigung der Schuld<br/>Gab Dein Blut uns Reinigung,<br/>Das für uns vollauf erfüllt<br/>Die gerechte Forderung.<br/>Wir sind von den Sünden rein,<br/>Denn Du wuschest uns im Blut;<br/>Mit Gewissen frei und leicht<br/>Dienen wir nun unsrem Gott.<br/>',NULL,46458,3);
INSERT INTO stanza VALUES('G107','4','Durch Dein absonderndes Blut<br/>Hast Du uns geheiligt, Herr;<br/>Durch das Blut, das uns bewahrt,<br/>Heiligst Du uns stets noch mehr.<br/>Durch Dein Sühneblut sind wir<br/>Nun vor Gott gerecht gemacht;<br/>Gott zufrieden ist durchs Blut,<br/>Das Erlösung hat vollbracht.<br/>',NULL,46459,4);
INSERT INTO stanza VALUES('G107','5','Durch Dein Blut, das floss am Kreuz,<br/>Uns mit Gott versöhnt hast Du;<br/>Nun im Frieden dürfen wir<br/>Zu Dir kommen immerzu.<br/>Durch Dein teures Blut gabst Du<br/>Uns Dein Leben ewiglich;<br/>Durch Dein Blut und Leben herrscht<br/>Ruh und Friede innerlich.<br/>',NULL,46460,5);
INSERT INTO stanza VALUES('G107','6','Dein gesprengtes Blut vor Gott<br/>Besseres im Himmel spricht;<br/>Dieses Blut verteidigt uns,<br/>Birgt und schützt, wenn Satan sticht.<br/>Durch Dein Blut, das siegreich ist,<br/>Überwinden wir den Feind;<br/>Über den Verkläger so<br/>Siegen wir mit Leichtigkeit.<br/>',NULL,46461,6);
INSERT INTO stanza VALUES('G107','7','Dein Blut zur Gemeinschaft führt<br/>Mit den Heiligen so rein;<br/>Durch das Blut, das uns bedeckt,<br/>Unser Geist nie schwach wird sein.<br/>Alle Worte fassen nicht,<br/>Was Dein Blut für uns ist wert.<br/>Dazu braucht''s die Ewigkeit,<br/>Endlos wird sein Lob vermehrt.<br/>',NULL,46462,7);
INSERT INTO stanza VALUES('G108','1','Durch das Brot und durch den Kelch, Herr,<br/>Stelln wir Deinen Tod aus hier;<br/>Wir besinnen Deine Liebe<br/>Deine Leiden ehren wir.<br/>Brot und Kelch in Trennung zeigen,<br/>Dass Du durch den Tod einst gingst;<br/>Dankbar betet unser Geist an,<br/>Unser Loblied stets erklingt.<br/>',NULL,46463,1);
INSERT INTO stanza VALUES('G108','chorus','Dein, der Kelch der Leiden,<br/>Mein, der Kelch des Segens;<br/>Für die Liebe der Erlösung<br/>Preis sei Dir, o Herr!<br/>',NULL,46464,2);
INSERT INTO stanza VALUES('G108','2','Du vergosst Dein Blut in Liebe,<br/>Brachtest uns zu Gott ins Licht;<br/>Wir sind nicht von Gott getrennt mehr,<br/>Schauen nun Sein Angesicht.<br/>Die gerechten Forderungen<br/>Gottes hast Du ganz erfüllt;<br/>Das Verdienst von Deinem Tod, Herr,<br/>Schafft uns Wohnung jetzt bei Gott.<br/>',NULL,46465,3);
INSERT INTO stanza VALUES('G108','3','Herr, Dein Tod zerriss den Vorhang,<br/>Frei der Zugang ist zu Dir;<br/>Nichts uns hindert, kühn wir kommen,<br/>Nun beim Gnadenthron sind wir.<br/>Dort Barmherzigkeit und Gnade<br/>Finden wir zur rechten Zeit;<br/>Wasser, göttlich und lebendig,<br/>Stillt den Durst in Ewigkeit.<br/>',NULL,46466,4);
INSERT INTO stanza VALUES('G108','4','Du hast uns erlöst in Gnade<br/>Dass wir ewig Priester sei''n,<br/>Die den Dienst so heilig ausführn;<br/>Hier wir Gottes Süße teiln.<br/>Welch Barmherzigkeit, welch Segen<br/>Fließt aus Deinem Tod so treu!<br/>Wir wolln Deiner stets gedenken,<br/>Bis Du trinkst mit uns aufs Neu''.<br/>',NULL,46467,5);
INSERT INTO stanza VALUES('G109','1','Oh, welch ein Wunder, liebster Herr,<br/>Dass ich in Dir und Du in mir!<br/>Dass Du und ich sind wirklich eins!<br/>Oh, welch Geheimnis sehn wir hier!<br/>',NULL,46468,1);
INSERT INTO stanza VALUES('G109','2','Für mich gabst Du, Herr, Deinen Leib,<br/>So hab ich teil an Dir allzeit;<br/>Und Dein vergossnes Blut hat mich<br/>Von meinen Sünden ganz befreit.<br/>',NULL,46469,2);
INSERT INTO stanza VALUES('G109','3','Durch Auferstehung wandeltest<br/>Du Deine Form und kamst als Geist;<br/>Du willst, dass ich, mit Dir gefüllt,<br/>Mit Deinem Reichtum sei gespeist.<br/>',NULL,46470,3);
INSERT INTO stanza VALUES('G109','4','Schauen wir hier die Zeichen an<br/>Und Deine Lieb aufs Neue sehn,<br/>Für Deinen Herzenswunsch sei Dank<br/>Für Deine Mühsal wir Dich ehrn.<br/>',NULL,46471,4);
INSERT INTO stanza VALUES('G109','5','Wir essen Brot und trinken Wein,<br/>Mit Deiner Süße reich beschert;<br/>Nimmt jeder Dich zu sich im Geist,<br/>Wird unser Geist mit Dir ernährt.<br/>',NULL,46472,5);
INSERT INTO stanza VALUES('G109','6','Essen und trinken – immer mehr–<br/>Im Geist, dies wir ersehnen gar;<br/>Bis unser Sein Du ganz erfüllst<br/>So Deiner wir gedenken wahr.<br/>',NULL,46473,6);
INSERT INTO stanza VALUES('G110','1','Seht, gedeckt der Tisch steht vor uns,<br/>Nun bereit sind Brot und Wein;<br/>Seht, der Retter wartet auf uns:<br/>„Nehmt mit Mir das Mahl nun ein“.<br/>„Kommt und esst“, so ruft der Herr uns,<br/>„Speis mit Mir und Ich mit dir“;<br/>Er lädt uns zu Seinem Tisch ein –<br/>Lasst uns freudig festen hier.<br/>',NULL,46474,1);
INSERT INTO stanza VALUES('G110','2','Herrlich ist das Fest mit Christus,<br/>Unsrem Retter Dank gebührt;<br/>Halleluja, halleluja!<br/>Unsre Herzen sind berührt!<br/>Essen, trinken mit Dir Selbst, Herr,<br/>Uns vollauf zufrieden macht.<br/>Kosten wir das Festmahl, das Du<br/>Deiner Braut hast zugedacht.<br/>',NULL,46475,2);
INSERT INTO stanza VALUES('G111','1','Zum Mahl des Herrn sind wir zusammengekommen:<br/>Durch Essen und Trinken die Einheit erklärn.<br/>Der Herr gibt uns Leben, vereint wir Ihn erheben,<br/>Welch Segen wir erfahren beim Fest mit dem Herrn!<br/>',NULL,46476,1);
INSERT INTO stanza VALUES('G111','2','Wir essen das Brot, Seinen Leib, einst zerbrochen,<br/>Genießen den Leib nun, den einen des Herrn;<br/>Ein Brotlaib will zeigen – ein Leib ist Ihm zu eigen;<br/>Dass Christus uns vereinte, bezeugen wir gern.<br/>',NULL,46477,2);
INSERT INTO stanza VALUES('G111','3','Auch trinken wir dankbar den Kelch Seines Segens<br/>Und haben Gemeinschaft im Blut unsres Herrn;<br/>Wer glaubt zur Erlösung, den heißen wir willkommen<br/>All jenen, die auch wollen, zu Gott wiederkehrn.<br/>',NULL,46478,3);
INSERT INTO stanza VALUES('G111','4','Was können wir sagen sonst als „Halleluja“!<br/>Da unsere Einheit voll Wirklichkeit ist.<br/>Wir wenden Dein Blut an, genießen Deinen Leib dann<br/>Bis Du Deine Gemeinde voll Herrlichkeit siehst.<br/>',NULL,46479,4);
INSERT INTO stanza VALUES('G112','1','Herr, als Dein einer Leib sind wir versammelt:<br/>Wenn auch so viele, sind wir alle eins.<br/>Dein Leben teilen wir, und wir sind Glieder,<br/>Ja, innerlich so sind wir alle eins.<br/>',NULL,46480,1);
INSERT INTO stanza VALUES('G112','chorus','Es gibt nur einen Leib in diesem All,<br/>Sein''n Ausdruck stellen wir hier dar;<br/>In Einheit stehen wir an jedem Ort,<br/>Der eine Leib erscheint so klar.<br/>',NULL,46481,2);
INSERT INTO stanza VALUES('G112','2','Das eine Brot, das Deinen Leib bezeichnet,<br/>Gebrochen wurde, jeder nehme frei;<br/>Wenn wir es essen, tun wir kund die Einheit<br/>Mit allen Heiligen, wo es auch sei.<br/>',NULL,46482,3);
INSERT INTO stanza VALUES('G112','3','Das eine Brot, der eine Kelch uns zeigen:<br/>Es geht nicht anders, eins in Dir sind wir.<br/>Christus erlöste uns für Seinen Leibe:<br/>Wir sagen: „Amen, eins sind wir in Dir!“<br/>',NULL,46483,4);
INSERT INTO stanza VALUES('G112','4','Wir stehn als Einer, niemand kann uns spalten,<br/>Weil einzig Du, Herr, unsre Einheit bist.<br/>Dass wir das Brot, den Kelch zusammen teilen,<br/>Sichtbares Zeugnis unsrer Einheit ist.<br/>',NULL,46484,5);
INSERT INTO stanza VALUES('G112','5','Oh, welche Freude ruht auf dieser Einheit!<br/>Wir spüren, dass dies Dich zufriedenstellt;<br/>Auch wir sind voller Freude und zufrieden –<br/>Welch Vorgeschmack von Bräutigam und Braut!<br/>',NULL,46485,6);
INSERT INTO stanza VALUES('G113','1','Esst das Brot, die ihr dem Herrn gehört,<br/>Wir sind eins, weil Christus für uns starb.<br/>Wir sind hier und essen einmütig:<br/>Die Gemeinde, die Er Sich erwarb.<br/>',NULL,46486,1);
INSERT INTO stanza VALUES('G113','chorus','Esst das Brot, ihr Heil''gen, trinkt den Wein!<br/>Wir sind eins in Ihm allzeit.<br/>Stehn in Einheit auf dem Ortsgrund hier,<br/>Esst und trinkt in Einmütigkeit!<br/>',NULL,46487,2);
INSERT INTO stanza VALUES('G113','2','Oh, ihr Heil''gen, trinkt den Kelch des Herrn:<br/>Durch Sein Blut ist die Gemeind erkauft.<br/>Denn die Gleichgesinntheit freut Ihn sehr –<br/>Diesem Ziel des Herrn entgegenlauft.<br/>',NULL,46488,3);
INSERT INTO stanza VALUES('G113','3','Oh, ihr Heil''gen, in der Einheit bleibt,<br/>Einzelkörner bläst der Wind leicht fort –<br/>Euch vermengt und bleibt stets einmütig<br/>Als ein Brot, das nährt an jedem Ort.<br/>',NULL,46489,4);
INSERT INTO stanza VALUES('G113','4','Wir, Sein Volk, verkünden: Wir sind eins!<br/>Ja, wahrhaftig eins in unsrem Herrn!<br/>Nicht nur Wort; nein, unsre Lebensart<br/>Zeigt die Einheit, die der Herr getan.<br/>',NULL,46490,5);
INSERT INTO stanza VALUES('G113','5','Esst das Brot, die ihr dem Herrn gehört,<br/>Wir sind eins, weil Christus für uns starb.<br/>Wir sind hier und essen einmütig:<br/>Die Gemeinde, die Er Sich erwarb.<br/>(Refrain nach der letzten Strophe nicht wiederholen.)<br/>',NULL,46491,6);
INSERT INTO stanza VALUES('G114','1','O Jesus Herr, wenn wir an Deinem Tisch sind,<br/>Und dankbar Brot und Wein hier schauen an;<br/>Dann preisen wir, dass Dich der Mensch als Speise<br/>Auf manche Weise reich genießen kann.<br/>',NULL,46492,1);
INSERT INTO stanza VALUES('G114','chorus','Wir preisen Dich mit unsrem ganzen Sein,<br/>Wie klein bist Du, wie klein bist Du!<br/>Wir wollen essen ewig Dich allein;<br/>Wie klein bist Du, wie klein bist Du!<br/>',NULL,46493,2);
INSERT INTO stanza VALUES('G114','2','Da Christus kam mit Seinem ganzen Reichtum<br/>In diese Welt, Sein Leben uns anbot,<br/>Wie traurig ist''s: Der Mensch füllt sich mit Lehren,<br/>Die kraftlos sind, anstatt mit Lebensbrot.<br/>',NULL,46494,3);
INSERT INTO stanza VALUES('G114','chorus','Doch wir solln Christus essen immer mehr,<br/>Er ist so reich und wunderbar!<br/>Durch Essen stellt Er uns nun wieder her,<br/>Sein Wuchs in uns wird offenbar.<br/>',NULL,46495,4);
INSERT INTO stanza VALUES('G114','3','O Jesus Christus, Du kamst nicht zur Menschheit,<br/>Um zu regiern als König äußerlich,<br/>Vielmehr als Speise und Zufriedenstellung,<br/>Und durch Dein Leben führen innerlich.<br/>(Erster Refrain)<br/>',NULL,46496,5);
INSERT INTO stanza VALUES('G114','4','Wir preisen Dich, o Herr, für Deine Größe,<br/>Für Deine Majestät und Kraft und Pracht;<br/>Und doch, o Herr, besonders wolln wir danken,<br/>Dass Du Dich klein und essbar hast gemacht.<br/>(Erster Refrain)<br/>',NULL,46497,6);
INSERT INTO stanza VALUES('G115','1','Oh, wie herrlich ist Dein Tisch für uns!<br/>Du, der Mensch, o Herr, ihn leitest,<br/>Hier in Deinem Haus uns weidest;<br/>Oh, wie herrlich ist Dein Tisch für uns!<br/>',NULL,46498,1);
INSERT INTO stanza VALUES('G115','chorus','Halleluja! Halleluja!<br/>Halleluja für dies Fest!<br/>Halleluja! Halleluja!<br/>Herr, wie herrlich ist Dein Tisch für uns!<br/>',NULL,46499,2);
INSERT INTO stanza VALUES('G115','2','Wie genussreich ist Dein Tisch, o Herr!<br/>Hier Gemeinschaft ist vorhanden,<br/>Dir sei Dank, dass wir ihn fanden,<br/>Wie genussreich ist Dein Tisch, o Herr!<br/>',NULL,46500,3);
INSERT INTO stanza VALUES('G115','3','Herr, wie kostbar ist Dein Tisch für uns! –<br/>Brot und Wein Dein''n Tod bezeugen;<br/>Seelenleben wir verleugnen,<br/>Haben teil, o Herr, an Deinem Tisch.<br/>',NULL,46501,4);
INSERT INTO stanza VALUES('G115','4','Wie bedeutsam ist Dein Tisch, o Herr! –<br/>Deinen Leib im Brot wir sehen,<br/>Liebe mehr als wir verstehen,<br/>Wie bedeutsam ist Dein Tisch, o Herr!<br/>',NULL,46502,5);
INSERT INTO stanza VALUES('G115','5','Wie erfrischend ist Dein Tisch, o Herr! –<br/>Völlig stellt er uns zufrieden,<br/>Stets versorgt er uns hienieden,<br/>Wie erfrischend ist Dein Tisch, o Herr!<br/>',NULL,46503,6);
INSERT INTO stanza VALUES('G115','6','Wie ermutigend ist, Herr, Dein Tisch! –<br/>„Bis Er kommt“ ist die Verheißung,<br/>Täglich füllt er uns mit Hoffnung,<br/>Wie ermutigend ist, Herr, Dein Tisch!<br/>',NULL,46504,7);
INSERT INTO stanza VALUES('G116','1','Herrlichkeit, Segen und Ehre sei Dir,<br/>Und Ehre sei Dir,<br/>Und Ehre sei Dir.<br/>Herrlichkeit, Segen und Ehre sei Dir,<br/>Jetzt und in Ewigkeit.<br/>Preist Ihn! Preist Ihn!<br/>All ihr Heil''gen preiset Ihn!<br/>Preist Ihn! Preist Ihn!<br/>Jetzt und in Ewigkeit.<br/>Halleluja!<br/>Herrlichkeit, Segen und Ehre sei Dir,<br/>Und Ehre sei Dir,<br/>Und Ehre sei Dir.<br/>Herrlichkeit, Segen und Ehre sei Dir,<br/>Jetzt und in Ewigkeit.<br/>',NULL,46505,1);
INSERT INTO stanza VALUES('G117','1','Der Geist Gottes heute ist<br/>Der Geist Jesu allezeit,<br/>Der Gott-Mensch, der starb und lebt,<br/>Fuhr auf in die Herrlichkeit.<br/>',NULL,46506,1);
INSERT INTO stanza VALUES('G117','2','Durch Jesus gekommen ist<br/>Der Geist Jesu in die Zeit,<br/>Und heute erfahren wir<br/>Ganz reich Seine Wirklichkeit.<br/>',NULL,46507,2);
INSERT INTO stanza VALUES('G117','3','Im Geist Jesu ist Gott Selbst,<br/>Auch''s menschliche Element,<br/>Sein Geist Gottes Herrlichkeit<br/>Und menschlichen Wandel kennt.<br/>',NULL,46508,3);
INSERT INTO stanza VALUES('G117','4','Viel menschliches Leid und Pein,<br/>Sein Tod, der so wirksam ist,<br/>Sein Auferstehn und Regiern,<br/>Im Atem des Geistes fließt.<br/>',NULL,46509,4);
INSERT INTO stanza VALUES('G117','5','Mit allen Elementen<br/>Sein Geist Sich in uns bewegt,<br/>Uns durch Seine Salbung nun<br/>Mit Reichtum des Herrn umhegt.<br/>',NULL,46510,5);
INSERT INTO stanza VALUES('G117','6','In Großem und Kleinem ist<br/>Der Geist Jesu anwendbar;<br/>Umfassend wirkt Er in uns,<br/>Bis Gott uns erfüllt fürwahr.<br/>',NULL,46511,6);
INSERT INTO stanza VALUES('G118','1','Ja, Gottes Geist ist Christi Geist,<br/>Und auch der Geist der Wirklichkeit,<br/>Er wohnt in mir, dass Christus ich<br/>Als Leben kenne allezeit.<br/>',NULL,46512,1);
INSERT INTO stanza VALUES('G118','2','In Christus ist verkörpert Gott,<br/>Macht Gott als Leben wahrnehmbar;<br/>So zeigt der Geist uns Christus auf,<br/>Macht Ihn als Leben offenbar.<br/>',NULL,46513,2);
INSERT INTO stanza VALUES('G118','3','Leibhaftig wohnt der Vater Gott<br/>Im Sohn in Fülle allezeit;<br/>Der Reichtum Christi ist der Geist,<br/>Er macht Ihn für uns Wirklichkeit.<br/>',NULL,46514,3);
INSERT INTO stanza VALUES('G118','4','Oh, in dem Sohn der Vater ist,<br/>Und nun der Geist ist auch der Sohn;<br/>Der Vater eins mit Christus ist,<br/>Der Geist identisch mit dem Sohn.<br/>',NULL,46515,4);
INSERT INTO stanza VALUES('G118','5','Wenn Gottes Geist uns stärkt mit Kraft<br/>Im Herzen Christus Wohnung macht,<br/>So wird des Vaters Fülle dann<br/>In unser Sein hineingebracht.<br/>',NULL,46516,5);
INSERT INTO stanza VALUES('G118','6','In Christus auch der Vater ist,<br/>In allem nimm Ihn doch sogleich;<br/>Im Geist erfahrn wir Christus stets<br/>Als Leben und Versorgung reich.<br/>',NULL,46517,6);
INSERT INTO stanza VALUES('G118','7','Durch Deinen Geist erfüll uns, Herr,<br/>Mit Deiner reinen Wirklichkeit,<br/>Damit wir, ganz erfüllt mit Dir,<br/>Erweisen Deine Herrlichkeit.<br/>',NULL,46518,7);
INSERT INTO stanza VALUES('G119','1','Der Heil''ge Geist ist heute gar<br/>Der Geist des Lebens Gottes rein;<br/>Der uns erquickt und Leben gibt,<br/>In Gottes Plan fügt Er uns ein.<br/>',NULL,46519,1);
INSERT INTO stanza VALUES('G119','2','Als Strom, der voller Leben ist,<br/>Stillt Er den Durst, mir nichts mehr fehlt;<br/>Als Leben teilt Er Christus aus,<br/>Mein Herz Er voll zufriedenstellt.<br/>',NULL,46520,2);
INSERT INTO stanza VALUES('G119','3','Das Licht des Lebens strahlt Er aus,<br/>Von Dunkel zu befrein vermag;<br/>Uns Christus schenkt als Gottes Licht,<br/>Und unsre Nacht macht Er zum Tag.<br/>',NULL,46521,3);
INSERT INTO stanza VALUES('G119','4','Im innren Menschen stärkt Er uns<br/>Mit Lebenskraft voll Herrlichkeit;<br/>Teilt Christus aus als Gottes Kraft,<br/>Für Gottes Plan wirkt Er allzeit.<br/>',NULL,46522,4);
INSERT INTO stanza VALUES('G119','5','Durch das Gesetz des Lebens macht<br/>Er vom Gesetz der Sünde frei;<br/>Mit Seiner göttlichen Natur<br/>Er reguliert und lenkt dabei.<br/>',NULL,46523,5);
INSERT INTO stanza VALUES('G119','6','Als Geist, der Gottes Leben ist,<br/>Bringt Er viel Frucht durch uns fürwahr;<br/>Er Gottes Eigenschaften zeigt,<br/>Reicht Christus stets im Leben dar.<br/>',NULL,46524,6);
INSERT INTO stanza VALUES('G119','7','Der Geist gibt Leben, wandelt um<br/>Mit Gottes Leben täglich treu;<br/>Damit ich Christi Bild gleich sei,<br/>Macht Er die innren Teile neu.<br/>',NULL,46525,7);
INSERT INTO stanza VALUES('G119','8','Mit Deinem Geist des Lebens, Herr,<br/>Füll mich und wirke Dich mir ein,<br/>Durchsättige mich gründlich, Herr,<br/>Bis Du erfüllst mein ganzes Sein.<br/>',NULL,46526,8);
INSERT INTO stanza VALUES('G120','1','Der Dreieine Gott macht Wohnung jetzt in uns<br/>Als der Geist, wunderbar heut in uns.<br/>Wir sind mit dem Herrn vermengt und eins mit Ihm<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,46527,1);
INSERT INTO stanza VALUES('G120','chorus','Er ist der Geist, wunderbar heut in uns,<br/>Ja, der Geist, wunderbar heut in uns!<br/>Gott ist in dem Sohn, der Sohn ist jetzt der Geist<br/>Ja, der Geist, wunderbar heut in uns!<br/>',NULL,46528,2);
INSERT INTO stanza VALUES('G120','2','„Abba Vater“ ruft nun tief in uns die Stimm<br/>Aus dem Geist, wunderbar heut in uns.<br/>Er, der Geist des Sohnes, welcher schreit zu Ihm<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,46529,3);
INSERT INTO stanza VALUES('G120','3','Jesus Christus ist der Herr, in uns lebt Er<br/>Als der Geist, wunderbar heut in uns.<br/>Den verklärten Herrn genießen wir nun sehr<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,46530,4);
INSERT INTO stanza VALUES('G120','4','Nun ist Er der Geist der Wirklichkeit fürwahr,<br/>Als der Geist, wunderbar heut in uns.<br/>Ja, was Christus ist, wird wirklich und so klar<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,46531,5);
INSERT INTO stanza VALUES('G120','5','Diese Gabe tief in uns wecken wir auf<br/>Durch den Geist, wunderbar heut in uns.<br/>Rufen wir: „Herr Jesus“ - unser Geist springt auf<br/>Durch den Geist, der gibt Leben in uns!<br/>',NULL,46532,6);
INSERT INTO stanza VALUES('G121','1','Grabe, Herr, im Brunnen,<br/>Wasser soll aufschießen;<br/>Grabe weg Barrieren,<br/>Du sollst durch mich fließen.<br/>',NULL,46533,1);
INSERT INTO stanza VALUES('G121','2','Christus, Fels gespalten,<br/>Sprudelt voller Leben;<br/>Doch im Herzen Steine<br/>Widerstand noch geben.<br/>',NULL,46534,2);
INSERT INTO stanza VALUES('G121','3','Betend werd ich graben,<br/>Allen Schmutz weggießen,<br/>So den Geist befreie,<br/>Dass der Strom kann fließen.<br/>',NULL,46535,3);
INSERT INTO stanza VALUES('G121','4','Christus als den Felsen<br/>Muss man nicht mehr schlagen;<br/>Doch ich möcht mich geben,<br/>Ja zum Graben sagen.<br/>',NULL,46536,4);
INSERT INTO stanza VALUES('G121','5','Was ich dringend brauche,<br/>Ist des Geistes Füllen,<br/>Bis aus meinem Herzen<br/>Lebensströme quellen.<br/>',NULL,46537,5);
INSERT INTO stanza VALUES('G121','6','Grabe, bis ich frei bin,<br/>Dreck darf''s nicht mehr geben;<br/>Grabe, bis der Strom bringt<br/>Worte voller Leben.<br/>',NULL,46538,6);
INSERT INTO stanza VALUES('G121','7','Grabe, Herr, im Brunnen,<br/>Wasser soll aufschießen;<br/>Grabe weg Barrieren,<br/>Du durch mich sollst fließen.<br/>',NULL,46539,7);
INSERT INTO stanza VALUES('G122','1','Hauche Deinen Geist auf mich, Herr,<br/>Dich zu atmen, lehre mich,<br/>Und in Deinen Schoß zu schütten<br/>Meine Sünde, Selbst, mein Ich.<br/>',NULL,46540,1);
INSERT INTO stanza VALUES('G122','chorus','Atme aus all meine Sorgen,<br/>Auch mein altes Sein;<br/>Und ich atme, atme, atme<br/>Deine Fülle ein.<br/>',NULL,46541,2);
INSERT INTO stanza VALUES('G122','2','Atme aus mein eignes Leben,<br/>Füll mit Deinem, Herr, allein;<br/>Eigne Kraft und Schwachheit lass ich,<br/>Atme Gottes Leben ein.<br/>',NULL,46542,3);
INSERT INTO stanza VALUES('G122','3','Atme aus nun meine Sünde,<br/>Diese Last nahmst Du von mir;<br/>Atme ein nun Deine Reinheit,<br/>Find mein Leben ganz in Dir.<br/>',NULL,46543,4);
INSERT INTO stanza VALUES('G122','4','Atme aus all meine Sorgen,<br/>Herr, auf Deiner lieben Brust;<br/>Atme ein jetzt Deinen Frieden,<br/>Deine Freude, Ruh und Trost.<br/>',NULL,46544,5);
INSERT INTO stanza VALUES('G122','5','Atme aus all meine Krankheit,<br/>Ihre Last trugst Du so treu;<br/>Atme ein all Deine Heilung,<br/>Längst verheißen, immer neu.<br/>',NULL,46545,6);
INSERT INTO stanza VALUES('G122','6','Atme aus all meine Sehnsucht<br/>In Dein offnes Ohr, o Herr;<br/>Atme ein nun Deine Antwort,<br/>Zweifel hab ich keine mehr.<br/>',NULL,46546,7);
INSERT INTO stanza VALUES('G122','7','Ich bin allezeit am Atmen,<br/>All mein Leben schöpf aus Dir;<br/>Zug für Zug, um Deinetwillen,<br/>Hauche nun Dein Geist in mir.<br/>',NULL,46547,8);
INSERT INTO stanza VALUES('G123','1','Oh, blas auf uns, o Herr, wir warten hier auf Dich;<br/>Oh, blas mit starkem Wind, befrei uns innerlich;<br/>Oh, blas bis unter uns Erweckung greift um sich;<br/>Oh, blas auf uns nun, beten wir!<br/>',NULL,46548,1);
INSERT INTO stanza VALUES('G123','chorus','Oh, blas auf uns, Herr Jesus, heut!<br/>Bis wir vom Schlummer sind befreit!<br/>Auf uns send Deinen Wind,<br/>Bis wir ganz brennend sind!<br/>Oh, blas auf uns, Herr Jesus, heut!<br/>',NULL,46549,2);
INSERT INTO stanza VALUES('G123','2','Oh, blas doch Liebe sanft ins kalte Herz hinein;<br/>Oh, blas bis Himmelsluft nimmt unsre Seele ein;<br/>Oh, blas bis alle Lauheit ganz verjagt wird sein;<br/>Oh, blas auf uns nun, beten wir!<br/>',NULL,46550,3);
INSERT INTO stanza VALUES('G123','3','Oh, blas mit Himmelskraft, stärk unsren Geist geschwind;<br/>Oh, blas mit Leben, Herr, und nur in Dir uns find;<br/>Oh, blas so fest und stark bis wir ganz brennend sind;<br/>Oh, blas auf uns nun, beten wir!<br/>',NULL,46551,4);
INSERT INTO stanza VALUES('G124','1','Herr, Deinen Wind des Himmels send<br/>Herab auf unser Sein!<br/>Erwecke und belebe uns,<br/>Mit Deiner Kraft allein.<br/>',NULL,46552,1);
INSERT INTO stanza VALUES('G124','chorus','Oh, komm auf uns herab mit Kraft,<br/>Mit Deinem Geist uns kleid!<br/>Uns stärk bis wir lebendig sind<br/>Und überwinden weit!<br/>',NULL,46553,2);
INSERT INTO stanza VALUES('G124','2','Oh, blas mit Deinem starken Geist,<br/>Durch alle Mauern brich;<br/>Blas Deinen Geist, der Leben gibt,<br/>Erfüll uns innerlich.<br/>',NULL,46554,3);
INSERT INTO stanza VALUES('G124','3','Der siebenfach verstärkte Geist<br/>Uns Anteil gibt an Dir;<br/>Schenk, dass wir den Dreieinen Gott<br/>Vollauf erfahren hier.<br/>',NULL,46555,4);
INSERT INTO stanza VALUES('G125','1','Wie siegreich Deine Liebe, Herr,<br/>In meine Seel Du gießt!<br/>Nun zieht mein Herz nicht mehr umher,<br/>In Gott verwurzelt ist''s,<br/>In Gott verwurzelt ist''s.<br/>',NULL,46556,1);
INSERT INTO stanza VALUES('G125','2','Mög Gottes Feuer glühn in mir,<br/>Das alte Selbst verzehrn;<br/>Brenn weg die letzte eitle Gier,<br/>Und jeden Berg entfern,<br/>Und jeden Berg entfern.<br/>',NULL,46557,2);
INSERT INTO stanza VALUES('G125','3','Wie Feuer vom Pfingsten brenne hier,<br/>Brenn meine Sünden fort;<br/>Geist Gottes, ja, ich ruf zu Dir,<br/>Mich läutre durch Dein Wort,<br/>Mich läutre durch Dein Wort.<br/>',NULL,46558,3);
INSERT INTO stanza VALUES('G125','4','Mich läutre durch Dein Feuer, Herr,<br/>Mein Herz für Dich gewinn;<br/>Breit aus in mir Dein Leben mehr,<br/>Bis ich geheiligt bin,<br/>Bis ich geheiligt bin.<br/>',NULL,46559,4);
INSERT INTO stanza VALUES('G125','5','Wie standfest meine Seele ist!<br/>Sie wankt nun nimmermehr,<br/>Wenn Christus reich mein Herz genießt;<br/>Ich liebe Dich so sehr,<br/>Ich liebe Dich so sehr.<br/>',NULL,46560,5);
INSERT INTO stanza VALUES('G126','1','Wo das Opfer-Blut besprengt ist,<br/>Wird das Salböl auch gesehn;<br/>So der Mensch mit Gott Kontakt hat<br/>Und Gemeinschaft bleibt bestehn.<br/>',NULL,46561,1);
INSERT INTO stanza VALUES('G126','2','Blut, das Zeichen für Erlösung,<br/>Wäscht von allen Sünden rein;<br/>Und das Salböl, Bild des Geistes,<br/>Bringt stets Gott in uns hinein.<br/>',NULL,46562,2);
INSERT INTO stanza VALUES('G126','3','Blut zeigt uns, was Gott getan hat,<br/>Salböl, was Er für uns ist;<br/>Es ist durch Sein Werk und Wesen<br/>Gott mit uns vermengt nun ist.<br/>',NULL,46563,3);
INSERT INTO stanza VALUES('G126','4','Christi Blut wäscht uns in Reinheit<br/>Und von Mischung läutert uns;<br/>Durch die Salbung Seines Geistes<br/>Ist jetzt Gott für uns Genuss.<br/>',NULL,46564,4);
INSERT INTO stanza VALUES('G126','5','Durch das Waschen und das Salben<br/>Können wir mit Gott eins sein;<br/>Durch das Blut und durch das Salböl<br/>Kann Gott unser Anteil sein.<br/>',NULL,46565,5);
INSERT INTO stanza VALUES('G126','6','Reinigung in Anspruch nehmen<br/>Durch das Blut im Glauben hier;<br/>Stets der Salbung wir gehorchen,<br/>Eins mit Gott so wandeln wir.<br/>',NULL,46566,6);
INSERT INTO stanza VALUES('G126','7','Gott als Licht wir so erkennen,<br/>Gott als Liebe wir erfahrn,<br/>Und in Gott als Leben wachsen,<br/>Gott als Kraft wird so sichtbar.<br/>',NULL,46567,7);
INSERT INTO stanza VALUES('G127','1','Ja, nun in mir wohnt Gottes Salbung,<br/>Alles lehrt sie allezeit;<br/>Sie leitet mich im Herrn zu leben stets,<br/>Seine Gegenwart verleiht.<br/>',NULL,46568,1);
INSERT INTO stanza VALUES('G127','chorus','Ja, die Salbung wohnt in meinem Geist,<br/>Die Salbung wohnt in mir<br/>Und lehrt mich allezeit.<br/>Ja, die Salbung wohnt in meinem Geist,<br/>Sie lehrt mich alles allezeit.<br/>',NULL,46569,2);
INSERT INTO stanza VALUES('G127','2','Sie ist der Geist, der Sich beweget,<br/>Die wie reines Salböl fließt;<br/>Ihr Fundament ist Jesu teures Blut,<br/>Damit sie so standfest ist.<br/>',NULL,46570,3);
INSERT INTO stanza VALUES('G127','3','Sie salbt mich mit der Essenz Gottes,<br/>Gott zu kennen innerlich;<br/>So hab ich Gottes Element in mir,<br/>Er durchsättigt mich mit Sich.<br/>',NULL,46571,4);
INSERT INTO stanza VALUES('G127','4','Sie bringt mich mit Gott in Gemeinschaft,<br/>Bis ich mich in Ihm verlier;<br/>In Gott, dem Licht der Wahrheit, wandle ich,<br/>Lieb und Gnade fließt aus mir.<br/>',NULL,46572,5);
INSERT INTO stanza VALUES('G128','1','Im Wort Gottes steht''s geschrieben,<br/>Wunderbar dies Wort ist mir;<br/>Ich brauch keine äußren Lehren,<br/>Denn die Salbung wohnt in mir!<br/>',NULL,46573,1);
INSERT INTO stanza VALUES('G128','chorus','Ja, nun in meinem Geist wohnt Er und beweist:<br/>Gottes Salbung habe ich!<br/>Reich fließt Gott in mir nun!<br/>Ja, nun in Gottes Wort seh ich''s immerfort!<br/>Ich möcht es anwenden!<br/>Gottes Salbung wohnt in mir!<br/>',NULL,46574,2);
INSERT INTO stanza VALUES('G128','2','Christus möcht ich mehr erfahren,<br/>Und so nehm ich Gott beim Wort;<br/>Er als Geist ist eins mit mir jetzt,<br/>Hält Sein Wort ein immerfort.<br/>',NULL,46575,3);
INSERT INTO stanza VALUES('G128','3','Durch sein Blut ganz rein gewaschen,<br/>Sodass nichts mehr hindern kann;<br/>Er, das Salböl, regt sich in mir!<br/>Bringt mich so mit Ihm voran.<br/>',NULL,46576,4);
INSERT INTO stanza VALUES('G128','4','Gott in Christus als das Leben<br/>Kam als Geist in meinen Geist!<br/>Hier salbt Er mich unablässig,<br/>Bis im Geist wir sind ganz gleich.<br/>',NULL,46577,5);
INSERT INTO stanza VALUES('G128','5','Gott im Geist ist nun berührbar,<br/>Denn in meinem Geist fließt Er.<br/>Tiefer, weiter, reicher, voller –<br/>Gott erkenn ich täglich mehr!<br/>',NULL,46578,6);
INSERT INTO stanza VALUES('G128','6','Wenn ich auf die Salbung achte,<br/>Achte auf ihr: „Bleib in Ihm“,<br/>Lehrt Er mich, erreicht Er mich, und<br/>Gar mein ganzes Herz gewinnt.<br/>',NULL,46579,7);
INSERT INTO stanza VALUES('G129','1','Füll mich mit dem Geist der Gnade,<br/>Meinen Geist erfüll stets mehr;<br/>Deine Gegenwart erfüll mich,<br/>Komm und füll mich, liebster Herr!<br/>',NULL,46580,1);
INSERT INTO stanza VALUES('G129','chorus','Füll mich jetzt! Füll mich jetzt!<br/>Füll mit Deinem Geist mich jetzt!<br/>Streif mich ab, entleere gründlich,<br/>Füll mit Deinem Geist mich jetzt!<br/>',NULL,46581,2);
INSERT INTO stanza VALUES('G129','2','Du allein nur kannst mich füllen,<br/>Über Bitten und Verstehn;<br/>Herr, ich brauch Dich, brauch Dich wirklich,<br/>„Komm und füll mich!“ ist mein Flehn.<br/>',NULL,46582,3);
INSERT INTO stanza VALUES('G129','3','Wie zerbrechlich, voller Schwachheit!<br/>Dir zu Füßen sitze ich;<br/>Segne mich durch Deinen Geist, Herr,<br/>Komm, mit Deiner Kraft füll mich!<br/>',NULL,46583,4);
INSERT INTO stanza VALUES('G129','4','Wasch und tröste, segne, rette;<br/>Den zerbrochnen Geist erfüll!<br/>Ja, Du tröstest und errettest,<br/>Süß mit Dir mich nun umhüll!<br/>',NULL,46584,5);
INSERT INTO stanza VALUES('G130','1','Wie ich preise, teurer Retter!<br/>Deine Liebe nahm mich ein;<br/>Nun gerettet und gereinigt,<br/>Dein Kanal kann ich jetzt sein.<br/>',NULL,46585,1);
INSERT INTO stanza VALUES('G130','chorus','Nur Kanäle, liebster Meister,<br/>Doch durch uns die Gnade fließt;<br/>Uns durchflute und gebrauche,<br/>Sodass Du verherrlicht bist.<br/>',NULL,46586,2);
INSERT INTO stanza VALUES('G130','2','Nur Kanäle, doch voll Segen<br/>Für die Durstigen zu sein;<br/>Deine volle Rettung kundtun,<br/>Nimm auch sie in Liebe ein.<br/>',NULL,46587,3);
INSERT INTO stanza VALUES('G130','3','Ganz entleert, dass Du mich fülln kannst,<br/>Ein Gefäß in Deiner Hand;<br/>Ohne Kraft, doch Du mit jedem<br/>Auftrag schenkst mir festen Stand.<br/>',NULL,46588,4);
INSERT INTO stanza VALUES('G130','4','Deine Gnade gern bezeug ich,<br/>Die vom Selbst und Sünd befreit;<br/>Du erkauftest mich als Diener,<br/>Herr, in Fülle mach Dich breit.<br/>',NULL,46589,5);
INSERT INTO stanza VALUES('G130','5','O Herr, füll mit Deinem Geist nun<br/>Jedes Herz, das willig ist;<br/>Bis der reine Strom des Lebens<br/>Aus dem innren Menschen fließt.<br/>',NULL,46590,6);
INSERT INTO stanza VALUES('G131','1','Von dem Geist geborn im Geiste,<br/>Als die Söhne Gottes wahr,<br/>Haben wir den Heil''gen Geist jetzt<br/>In uns wohnen immerdar.<br/>Doch wir brauchen mehr von Ihm, Herr,<br/>Bis zum Rand uns füll mit Dir;<br/>Uns mit Deinem Geist erfülle,<br/>Und mit Leben tränk uns hier.<br/>',NULL,46591,1);
INSERT INTO stanza VALUES('G131','2','Herr, Dein Geist in uns ist Leben,<br/>Voller Leben ist Sein Heil,<br/>Und am Reichtum Deiner Fülle<br/>Haben wir durch Ihn nun teil.<br/>Doch wir bitten, schenk von droben<br/>Deinen Geist der Kraft noch mehr,<br/>Dass wir ausgerüstet werden<br/>Für Dein Werk und Dienst, o Herr.<br/>',NULL,46592,2);
INSERT INTO stanza VALUES('G131','3','Taufe uns mit Deinem Geist, Herr,<br/>Kleide uns mit Deiner Macht;<br/>Mit dem „Mantel“ Deiner Stärke<br/>Siegen wir in jeder Schlacht.<br/>Mög Dein Wind auf uns nun blasen,<br/>Feuerzungen uns umhülln,<br/>Bis wir, als gesalbte Zeugen,<br/>Deinen Herzenswunsch erfülln.<br/>',NULL,46593,3);
INSERT INTO stanza VALUES('G131','4','Durch die Kraft, Herr, Deines Geistes<br/>Müssen wir die Gaben teiln,<br/>Um als Glieder sie zu üben,<br/>Und Dein Zeugnis klar zu sein.<br/>Gieße Deinen Geist auf uns aus,<br/>Segne uns mit Gaben, Herr,<br/>Dass der Aufbau Deines Leibes<br/>Täglich geht voran noch mehr.<br/>',NULL,46594,4);
INSERT INTO stanza VALUES('G131','5','Dir zum Ruhm Dein Leib ernst betet,<br/>Für Dein Reich ertönt sein Schrei!<br/>Deinen Vorsatz bald erfülle,<br/>Unsren Hunger still dabei.<br/>Deinen Geist wir nun genießen,<br/>Wenden Ihn vielfältig an;<br/>Sein Erfüllen, Sein Ausgießen<br/>Seine Gaben schenk sodann.<br/>',NULL,46595,5);
INSERT INTO stanza VALUES('G132','1','Herr, vor Dir wir stehn, und mit Freimut flehn,<br/>Gib uns Deine Macht, stärk uns hier;<br/>Mach uns Kämpfern gleich für Dein Königreich,<br/>Sitzend in den Himmeln kämpfen wir.<br/>',NULL,46596,1);
INSERT INTO stanza VALUES('G132','chorus','Kraft! Kraft! Kleide uns mit Kraft!<br/>Deiner starken Kraft von oben her!<br/>Kraft! Kraft! Kleide uns mit Kraft!<br/>Als Dein Leib wir bitten dies, o Herr.<br/>',NULL,46597,2);
INSERT INTO stanza VALUES('G132','2','Herr, auf Dich wir schaun und auf Dich vertraun,<br/>Deinen Regenguss teil uns aus.<br/>Wir für Deinen Leib frisch sind allezeit,<br/>Segne uns und bau mit uns Dein Haus!<br/>',NULL,46598,3);
INSERT INTO stanza VALUES('G132','chorus','Regen! Regen! Gieß aus Deinen Regen!<br/>Deinen Himmels-Regen gieß aus mehr!<br/>Regen! Regen! Gieß aus Deinen Regen!<br/>Als Dein Leib wir bitten dies, o Herr.<br/>',NULL,46599,4);
INSERT INTO stanza VALUES('G132','3','Dich erwarten wir, fordern ein von Dir<br/>Gottes Feuer, das uns stärkt sehr.<br/>Schenk uns Feuer nun, um Dich kundzutun,<br/>Herzen rett und läutre Du, o Herr.<br/>',NULL,46600,5);
INSERT INTO stanza VALUES('G132','chorus','Feuer! Feuer! Gib uns Feuerzungen!<br/>Kundtun Deine Rettung wolln wir mehr!<br/>Feuer! Feuer! Gib uns Feuerzungen!<br/>Als Dein Leib wir bitten dies, o Herr.<br/>',NULL,46601,6);
INSERT INTO stanza VALUES('G133','1','Christus, unser teurer Retter,<br/>Fuhr zum Himmel droben auf,<br/>Gott der Vater krönte Ihn mit<br/>Herrlichkeit und Pracht darauf;<br/>Machte Ihn zum Haupt von allem,<br/>Wie vortrefflich war Sein Lauf!<br/>',NULL,46602,1);
INSERT INTO stanza VALUES('G133','2','Von dem aufgefahrnen Christus<br/>Ward gegossen dann der Geist,<br/>Auf Sein''n Leib, auf die Gemeinde,<br/>Was den Gliedern Kraft erweist;<br/>Ihn, den höchsten Herrn im Himmel,<br/>Die Gemeinde liebt und preist.<br/>',NULL,46603,2);
INSERT INTO stanza VALUES('G133','3','Christus bringt Gott in den Menschen,<br/>Die Fleischwerdung hat''s vollbracht;<br/>Und durch Tod und Auferstehung<br/>Ist der Mensch in Gott gebracht;<br/>Gott und Mensch in Ihm vermengt sind,<br/>Und in Ihm ganz eins gemacht.<br/>',NULL,46604,3);
INSERT INTO stanza VALUES('G133','4','Nun in Auffahrt, in den Himmeln,<br/>Sitzt Er heute auf dem Thron;<br/>Herr zu sein, als Haupt zu herrschen<br/>Voll und ganz gehört dem Sohn;<br/>Die Ausgießung Seines Geistes<br/>Offenbart Ihn als Person.<br/>',NULL,46605,4);
INSERT INTO stanza VALUES('G133','5','Durch Ausgießung Seines Geistes<br/>Die Gemeinde formte Er;<br/>Die Gemeinde so getauft hat<br/>Gott den Geist verehrn wir sehr;<br/>Ewig gilt die Geistestaufe<br/>Was Sein Plan war von jeher.<br/>',NULL,46606,5);
INSERT INTO stanza VALUES('G133','6','Halleluja, Er vollbrachte<br/>Sie hier ein für allemal!<br/>Halleluja, eingeschlossen<br/>Sind wir alle ohne Zahl!<br/>Preist Ihn! Mit dem Geist getauft ist<br/>Die Gemeinde überall!<br/>',NULL,46607,6);
INSERT INTO stanza VALUES('G134','1','Der Geiste des Lebens ist heute in uns,<br/>Wie Wasser, das unseren Durst völlig stillt;<br/>Von Ihm trinken wir und Er füllt uns mit Sich,<br/>Bis Er als lebendiger Strom aus uns quillt.<br/>',NULL,46608,1);
INSERT INTO stanza VALUES('G134','2','Der Geiste der Kraft kommt von Christus auf uns,<br/>Wie Kleidung, die uns Himmels-Stellung verschafft;<br/>Getauft nun in Ihn und gekleidet mit Ihm,<br/>Zum Dienst ausgerüstet mit heiliger Kraft.<br/>',NULL,46609,2);
INSERT INTO stanza VALUES('G134','3','Der Geiste des Lebens dem Atem kommt gleich,<br/>Denn Leben hat Christus in uns eingehaucht;<br/>Der Geiste der Kraft gleicht dem brausenden Wind,<br/>Der auf uns herabfällt mit himmlischer Macht.<br/>',NULL,46610,3);
INSERT INTO stanza VALUES('G134','4','Erweckt, blies der Herr in die Jünger hinein,<br/>Den Geiste des Lebens so nahmen sie auf;<br/>An Pfingsten ergoss in der Auffahrt der Herr<br/>Den Geiste der Kraft, der sie stärkte vollauf.<br/>',NULL,46611,4);
INSERT INTO stanza VALUES('G134','5','Der Geiste des Lebens ist Leben in uns,<br/>Der Geiste der Kraft dieses Leben doch stärkt;<br/>Wie Wind, der durch Frischluft zum Atmen bewegt,<br/>Der Geiste der Kraft uns bewegt für Sein Werk.<br/>',NULL,46612,5);
INSERT INTO stanza VALUES('G134','6','Dies sind nicht zwei Geister, getrennt und für Sich<br/>In einem Geist zwei Funktionen es sind;<br/>Er füllt innerlich und uns außen umhüllt,<br/>Vermengt uns mit Gott als der Atem und Wind.<br/>',NULL,46613,6);
INSERT INTO stanza VALUES('G134','7','Des Lebens Geist, Herr, lass erfülln jeden Teil,<br/>Und wachsen in uns bis wir gleich sind wie Du;<br/>Bekleide uns nun mit dem Geiste der Kraft,<br/>In Deinem Dienst freudig zu stehn immerzu.<br/>',NULL,46614,7);
INSERT INTO stanza VALUES('G135','1','Erst das Blut, und dann das Salböl,<br/>Reinigung, dann Salbung fließt;<br/>Willst Du Golgatha umgehen,<br/>Du auch Pfingsten niemals siehst.<br/>Hat das Blut uns nie gereinigt,<br/>Können wir die Kraft nicht sehn;<br/>Wolln wir Christus treu bezeugen,<br/>Muss das Selbst ans Kreuz erst gehn.<br/>',NULL,46615,1);
INSERT INTO stanza VALUES('G135','chorus','Durch das Kreuz behandle mich<br/>Und mein Seelenleben brich,<br/>Dass für volle Salbung ich<br/>Willig jeden Preis bezahl.<br/>',NULL,46616,2);
INSERT INTO stanza VALUES('G135','2','Wär'' der Fels gar nicht geschlagen,<br/>So dass Lebenswasser fließt,<br/>Wär'' es, ohne Tod, unmöglich,<br/>Dass Gott Seinen Geist ergießt.<br/>Nur wenn wir mit Christus sterben,<br/>Und mit Ihm sind gleichgesinnt,<br/>Kleidet Er mit Seiner Kraft uns,<br/>Und durch uns die Welt gewinnt.<br/>',NULL,46617,3);
INSERT INTO stanza VALUES('G135','3','Der Altar zuerst, dann Feuer,<br/>Kein Verlust, auch kein Gewinn<br/>Wenn wir Ihm nicht alles geben,<br/>Kommen wir zum Thron nie hin.<br/>Wenn wir willig alles opfern,<br/>Im Gehorsam lassen los,<br/>Dann steht Er auf unsrer Seite,<br/>Seine Kraft wird in uns groß.<br/>',NULL,46618,4);
INSERT INTO stanza VALUES('G135','4','Mein Gefäß muss ich bereit stelln,<br/>Dass es Öl enthalten kann;<br/>Ich muss graben viele Gruben,<br/>Die der Regen auffüllt dann.<br/>Ich muss erst durchquern den Jordan,<br/>Dann reicht Er mir Salbung dar;<br/>In den Tod muss ich getauft sein,<br/>Dann die Taube auch erfahr.<br/>',NULL,46619,5);
INSERT INTO stanza VALUES('G135','5','Sehen wir die reife Ernte,<br/>Golden leuchten nah und fern,<br/>Zeigt uns dies, dass viele Samen<br/>Fielen hin und starben gern.<br/>Wenn wir Tod erlitten haben,<br/>Blüht die Frucht des Lebens auf;<br/>Wer mit Christus ist begraben,<br/>Atmet Gottes Geist darauf.<br/>',NULL,46620,6);
INSERT INTO stanza VALUES('G135','6','Herr, da dies so sein muss, bet ich,<br/>Lass mich gehn den schmalen Weg;<br/>Wirk Gehorsam in den Leiden,<br/>Dass ich meinen Stolz ableg.<br/>Nicht für größre Kraft nun bet ich,<br/>Tiefren Tod, das brauch ich sehr;<br/>Die Bedeutung Deines Kreuzes,<br/>Wirk in mir ein – immer mehr.<br/>',NULL,46621,7);
INSERT INTO stanza VALUES('G136','1','Mit Deinem Blut mich wasche<br/>Von allen Sünden rein;<br/>Mit Deinem Geist mich salbe,<br/>Nimm Du mich völlig ein.<br/>Mein Dienst – ich muss bekennen –<br/>Ist mangelhaft und leer;<br/>Mit Deinem Geist erfüll mich,<br/>Um Dir zu leben, Herr.<br/>',NULL,46622,1);
INSERT INTO stanza VALUES('G136','chorus','Von meinem Selbst befrei mich,<br/>Sein Elend nimm doch mir,<br/>Um fortan und für ewig<br/>Erfüllt zu sein mit Dir.<br/>',NULL,46623,2);
INSERT INTO stanza VALUES('G136','2','Mein Herz ist ausgetrocknet,<br/>Es schmachtet sehr nach Dir;<br/>Mit Deinem Geist erfüllt sein,<br/>Das wünsch ich sehnlichst mir.<br/>Ganz im geschlagnen Felsen<br/>Verbergen will ich mich;<br/>Dort trink ich Lebenswasser,<br/>Zufrieden stellst Du mich.<br/>',NULL,46624,3);
INSERT INTO stanza VALUES('G136','3','Wie ist mein Herz so kalt, Herr!<br/>Gehorsam will''s nicht sein;<br/>Mit Deinem Geist erfüll mich,<br/>Rebellisch nicht zu sein.<br/>Auf dem Altar nun lieg ich,<br/>Von hier mich nicht entfern,<br/>Mög Deine Feuerflamme<br/>Mein ganzes Sein verzehrn.<br/>',NULL,46625,4);
INSERT INTO stanza VALUES('G136','4','Dein Kreuz mög in mir brennen,<br/>Vertief Sein Werk noch mehr;<br/>Dein Maß in mir vergrößre,<br/>Mach mich zu Asche, Herr.<br/>Mit Deinem Geist erfüll mich,<br/>Nimm zu von Tag zu Tag,<br/>Damit Dein Lebenswasser<br/>Frei durch mich fließen mag.<br/>',NULL,46626,5);
INSERT INTO stanza VALUES('G137','1','Wir preisen Dich, Gott,<br/>Denn nun wohnt Christi Geist<br/>Als das Leben in uns,<br/>Der uns Gnade erweist.<br/>Halleluja! Nun in uns fließt<br/>Halleluja! Der Geist!<br/>Halleluja! Er gibt Leben,<br/>Uns kräftigt und speist!<br/>',NULL,46627,1);
INSERT INTO stanza VALUES('G137','2','Im Geist lobsingt Ihm,<br/>Der als Geist hier traf ein,<br/>Uns mit Leben versorgt,<br/>Um mit uns eins zu sein.<br/>Halleluja! Dies ist Jesus,<br/>Halleluja! Der jetzt,<br/>Halleluja! Als der Geist, uns<br/>Ins Leben versetzt.<br/>',NULL,46628,2);
INSERT INTO stanza VALUES('G137','3','Im Geist neu geborn,<br/>Wandelt Er uns jetzt um,<br/>Gottes Sohn uns gestaltet,<br/>Ihm gleich rundherum.<br/>Halleluja! Leben spendet,<br/>Halleluja! Macht neu,<br/>Halleluja! Uns verklärt bald,<br/>Zum Ziel bringt uns treu!<br/>',NULL,46629,3);
INSERT INTO stanza VALUES('G137','4','Ihm gleich werden wir,<br/>Denn wir essen im Geist<br/>Stets vom Leben des Herrn,<br/>Überreich es uns speist.<br/>Halleluja! Volle Rettung!<br/>Halleluja! Das Ziel!<br/>Halleluja! Er, der Geist, der<br/>Für uns sorgt so viel!<br/>',NULL,46630,4);
INSERT INTO stanza VALUES('G138','1','„Sieben Geister“ Gottes sind''s –<br/>Das Zeitalter wandte sich<br/>Hin zum Geist und mit dem Sohn;<br/>Um Gemeinden sorgt Er Sich.<br/>',NULL,46631,1);
INSERT INTO stanza VALUES('G138','chorus','Komm, o sieben Geister nun,<br/>Wiederherstellung zu tun!<br/>Brenn und prüf uns innerlich!<br/>Die Gemeinden sind für Dich.<br/>Brenn uns, prüf uns!<br/>Die Gemeinden sind für Dich!<br/>',NULL,46632,2);
INSERT INTO stanza VALUES('G138','2','Siebenfach ist jetzt der Geist,<br/>Die Gemeind vom Tod befreit,<br/>Wendet uns zum Leben hin,<br/>Brennt und prüft uns allezeit.<br/>',NULL,46633,3);
INSERT INTO stanza VALUES('G138','3','Gottes Geist ist heut verstärkt,<br/>In uns wirkt und Sich bewegt;<br/>Nicht nur ein-, nein, siebenfach<br/>Die Gemeinde nährt und pflegt!<br/>',NULL,46634,4);
INSERT INTO stanza VALUES('G138','4','Nun die sieben Geister sind<br/>Sieben Fackeln, die erhelln;<br/>Lehren nicht, doch brennen uns,<br/>Gottes Herz zufriedenstelln.<br/>',NULL,46635,5);
INSERT INTO stanza VALUES('G138','5','Sieben Geister prüfen uns<br/>Als die sieben Augen sehr;<br/>Sie durchforschen, stellen bloß,<br/>Die Gemeinde läutert Er.<br/>',NULL,46636,6);
INSERT INTO stanza VALUES('G138','6','Als die sieben Geister heut<br/>Spricht Er die Gemeinden an;<br/>Die Gemeind an jedem Ort<br/>Diesen Geist genießen kann.<br/>',NULL,46637,7);
INSERT INTO stanza VALUES('G139','1','Aus dem Geist, vom Geist geboren –<br/>Jesus diesem Quell entspringt;<br/>Gottes Geist erfüllt Ihn völlig –<br/>Die Essenz von Jesus ist.<br/>Mit dem Geist, im Geist, als Geist kam<br/>Jesus allumfassend, reich;<br/>Heute ist der Herr der Geist ja,<br/>Und im Geist sind wir Ihm gleich.<br/>',NULL,46638,1);
INSERT INTO stanza VALUES('G139','2','Ganz in Gottes Geist getauft und<br/>Auch getaucht in Ihn hinein,<br/>Und aus Gottes Geist geboren,<br/>Religion soll''s keine sein.<br/>Bleibt im Geiste, bleibt im Geiste –<br/>Nur dies ist erforderlich.<br/>Die Gemeinde muss im Geist sein,<br/>Lehre, Form gehören nicht.<br/>',NULL,46639,2);
INSERT INTO stanza VALUES('G139','3','Die Gemeinschaft dieses Geistes<br/>Unsere Gemeinschaft ist;<br/>Alle Brüder, alle Schwestern<br/>Kümmern sich nur um den Geist.<br/>Wer ein Ohr hat, höre, was der<br/>Geist zu den Gemeinden spricht.<br/>Sieben Geister den Gemeinden<br/>Schenken Gnade, Kraft und Licht.<br/>',NULL,46640,3);
INSERT INTO stanza VALUES('G139','4','„Kommt und trinkt das Lebenswasser“,<br/>Froh verkünden Geist und Braut –<br/>Geist und die Gemeinde eins sind,<br/>Fest vermengt, in eins gebaut.<br/>Ja, ein Leben nach dem Geist muss<br/>Unser Wandel sein und Ziel;<br/>Nur den Geist in den Gemeinden<br/>Gott zurückerlangen will.<br/>',NULL,46641,4);
INSERT INTO stanza VALUES('G140','1','Die teure Liebe Jesu,<br/>Die mich aus Sünde riss;<br/>Die wunderbare Gnade,<br/>Die mich zur Herde wies;<br/>Barmherzigkeit, so maßlos,<br/>Weit tiefer als das Meer<br/>Und höher als die Himmel,<br/>Mein Lied sei, Ihm zur Ehr.<br/>',NULL,46642,1);
INSERT INTO stanza VALUES('G140','chorus','Süßer wird sie Jahr für Jahr,<br/>Süßer wird sie Jahr für Jahr;<br/>Reicher, voller, tiefer,<br/>Jesu Lieb ist süßer,<br/>Süßer wird sie Jahr für Jahr.<br/>',NULL,46643,2);
INSERT INTO stanza VALUES('G140','2','Er schritt einst in Judäa<br/>Als Mensch durch Freud und Leid;<br/>Wer Ihm nachfolgte, kannte<br/>Die Gnade, die befreit.<br/>Er heilte die Geknickten,<br/>Den Blinden gab Er Sicht;<br/>Sehnt sich sogar voll Liebe<br/>Nach mir, und schenkt mir Licht.<br/>',NULL,46644,3);
INSERT INTO stanza VALUES('G141','1','Christus ist mein'' Gerechtigkeit,<br/>Er ist mein Schmuck und Ehrenkleid;<br/>In Ihm will ich vor Gott bestehn,<br/>Wenn ich vor Ihm dann werde stehn.<br/>',NULL,46645,1);
INSERT INTO stanza VALUES('G141','2','Ich glaube, Herr: Dein Blut mich spricht<br/>Am Gnadenstuhl frei vom Gericht;<br/>Auf ewig spricht es Sünder los,<br/>Für deren Seel es kräftig floss.<br/>',NULL,46646,2);
INSERT INTO stanza VALUES('G141','3','Ich glaube, Herr: wärn Sünder mehr<br/>Als liegen Sände breit am Meer,<br/>Hast Du doch alle freigemacht,<br/>Erlösung allen hast vollbracht.<br/>',NULL,46647,3);
INSERT INTO stanza VALUES('G141','4','Freimütig kann ich stehn fortan,<br/>Wer kann mich noch denn klagen an?<br/>Ich bin ganz frei: Dein Blut entband<br/>Von Sünd und Furcht, von Schuld und Schand.<br/>',NULL,46648,4);
INSERT INTO stanza VALUES('G141','5','Dies makellose Kleide hält,<br/>Stets gleich, wenn diese Erd verfällt;<br/>Ja, es verblasst nicht mit der Zeit,<br/>Stets neu bleibt ihre Herrlichkeit.<br/>',NULL,46649,5);
INSERT INTO stanza VALUES('G141','6','Du Gott der Kraft, Du Gott der Lieb,<br/>Nun allen Heil''gen hiervon gib;<br/>Sei unser Schmuck und Ehrenkleid,<br/>Jesus unsre Gerechtigkeit.<br/>',NULL,46650,6);
INSERT INTO stanza VALUES('G142','1','Kann es denn sein, dass ich gewinn<br/>Ein''n Anteil an des Retters Blut?<br/>Starb Er für mich, der Ihm Leid gab,<br/>Für mich, der Ihn zu Tod geführt?<br/>Welch große Liebe drängte Dich,<br/>Dass Du, mein Gott, dort starbst für mich?<br/>Welch große Liebe drängte Dich,<br/>Dass Du, mein Gott, dort starbst für mich?<br/>',NULL,46651,1);
INSERT INTO stanza VALUES('G142','2','Geheimnis groß, dass Gott Selbst stirbt!<br/>Wer kann ergründen diesen Plan?<br/>Der erste Seraph prüft umsonst,<br/>Was Gottes Lieb umfassen kann!<br/>Es war Barmherzigkeit, mein Herr,<br/>Lasst Engel forschen nimmermehr.<br/>Es war Barmherzigkeit, mein Herr,<br/>Lasst Engel forschen nimmermehr.<br/>',NULL,46652,2);
INSERT INTO stanza VALUES('G142','3','Er kam von Seines Vaters Thron,<br/>Mit Gnade reich und frei, herab,<br/>Entleerte Sich bis auf die Lieb,<br/>Sein Blut für Adams Samen gab.<br/>Frei währt die Gnade ewiglich,<br/>Denn, o mein Gott, sie fand auch mich.<br/>Frei währt die Gnade ewiglich,<br/>Denn, o mein Gott, sie fand auch mich.<br/>',NULL,46653,3);
INSERT INTO stanza VALUES('G142','4','Lang lag mein Geist in Ketten fest<br/>Gebunden in der Sünd und Nacht;<br/>Du sandtest einen Lebensstrahl,<br/>Licht flammte auf, ich bin erwacht!<br/>Die Fesseln fielen ab von mir,<br/>Ich ging hinaus und folgte Dir.<br/>Die Fesseln fielen ab von mir,<br/>Ich ging hinaus und folgte Dir.<br/>',NULL,46654,4);
INSERT INTO stanza VALUES('G142','5','Keine Verdammnis fürcht ich mehr,<br/>In Jesus ist nun alles mein!<br/>Er ist mein Haupt und Lebensquell,<br/>Gerecht bin ich in Ihm allein.<br/>Kühn tret ich vor den ew''gen Thron<br/>Und nehm durch Christus meine Kron.<br/>Kühn tret ich vor den ew''gen Thron<br/>Und nehm durch Christus meine Kron.<br/>',NULL,46655,5);
INSERT INTO stanza VALUES('G143','1','Ja, meine Hoffnung ruht allzeit<br/>Auf Christus der Gerechtigkeit;<br/>Wenn alles andre auch zerstäubt,<br/>Der Name Jesu dennoch bleibt.<br/>',NULL,46656,1);
INSERT INTO stanza VALUES('G143','chorus','Wer Christus, diesem Fels vertraut,<br/>Der hat auf keinen Sand gebaut,<br/>Der hat auf keinen Sand gebaut.<br/>',NULL,46657,2);
INSERT INTO stanza VALUES('G143','2','Ist auch verhüllt sein Angesicht,<br/>Doch Christi Gnade wanket nicht;<br/>Wenn auch der Sturmwind um mich bläst,<br/>Der Fels hält meinen Anker fest.<br/>',NULL,46658,3);
INSERT INTO stanza VALUES('G143','3','Sein Eid, Sein Bund, Sein teures Blut<br/>Beschützt mich fest zur Zeit der Flut;<br/>Wenn alles ringsum untergeht,<br/>Christus, der ew''ge Fels besteht.<br/>',NULL,46659,4);
INSERT INTO stanza VALUES('G143','4','Bricht mit Posaunenton Er ein,<br/>Oh, möcht ich dann gefunden sein<br/>In Ihm, meiner Gerechtigkeit,<br/>Vor Seinem Thron zu stehn, befreit.<br/>',NULL,46660,5);
INSERT INTO stanza VALUES('G144','1','Wie hold die Gnade klingt!<br/>Voll Anmut, süß und fein;<br/>Der Himmel ihre Huld besingt,<br/>Die Erde stimmt mit ein.<br/>',NULL,46661,1);
INSERT INTO stanza VALUES('G144','chorus','Gnade reicht mir ganz!<br/>Niemals ohne Kraft!<br/>Christus ist''s, der in mir lebt,<br/>Und mir die Gnade schafft.<br/>',NULL,46662,2);
INSERT INTO stanza VALUES('G144','2','Sie schrieb ein meinen Nam<br/>Ins ew''ge Lebens-Buch,<br/>Die Gnade brachte mich zum Lamm,<br/>Das meine Kummer trug.<br/>',NULL,46663,3);
INSERT INTO stanza VALUES('G144','3','Sie lenkte meine Füß''<br/>Auf diesen Pilger-Pfad,<br/>Und jede Stund werd ich begrüßt,<br/>Begegnet von der Gnad.<br/>',NULL,46664,4);
INSERT INTO stanza VALUES('G144','4','Sie lehrt'' mein Herz Gebet,<br/>Dass mir das Auge floss;<br/>Die Gnade hat mir Heil gewährt,<br/>Und lässt mich nicht mehr los.<br/>',NULL,46665,5);
INSERT INTO stanza VALUES('G144','5','Sie schmückt das Werke fein<br/>Und krönt es immerzu;<br/>Sie legt in Lieb den Abschlussstein,<br/>Lob kommt ihr ewig zu.<br/>',NULL,46666,6);
INSERT INTO stanza VALUES('G144','6','Lass diese Gnad erfülln<br/>Mein Herz mit Gottes Macht;<br/>All meine Tag'' sei sie mein Will,<br/>Ich strebe ihr stets nach.<br/>',NULL,46667,7);
INSERT INTO stanza VALUES('G145','1','In tiefem Kerker, hoffnungslos, bang,<br/>Wir wollten glauben, was nicht gelang;<br/>Gott leuchtet in uns, Jesus erscheint uns,<br/>Gott flösst Sich in uns ein!<br/>Gott flösst Sich in uns ein!<br/>',NULL,46668,1);
INSERT INTO stanza VALUES('G145','chorus','Jesus versöhnte uns durch Sein Blut,<br/>Hat uns erlöst, erkauft, oh, wie gut!<br/>Keine Verdammung, Rechtfertigung nun!<br/>Jetzt herrscht Frieden mit Gott!<br/>Jetzt herrscht Frieden mit Gott!<br/>',NULL,46669,2);
INSERT INTO stanza VALUES('G145','2','Sterben in Adam war unser Los;<br/>In Sünden krank und ganz hoffnungslos.<br/>Doch Gott im Sohn kam, Adam ganz wegnahm;<br/>Er ist tot, wir sind frei!<br/>Er ist tot, wir sind frei!<br/>',NULL,46670,3);
INSERT INTO stanza VALUES('G145','3','Freude und Gnade füllt unser Sein,<br/>O Halleluja! Von Sünden rein!<br/>Gott kann nun fließen und in uns sprießen<br/>Durch Sein Leben in uns!<br/>Durch Sein Leben in uns!<br/>',NULL,46671,4);
INSERT INTO stanza VALUES('G146','1','Oh, welches Wort: Nun mein Verstand<br/>Im Frieden ist mit Gott!<br/>Ich, Sünder, bin versöhnt durchs Blut,<br/>Und dann ist alles gut.<br/>',NULL,46672,1);
INSERT INTO stanza VALUES('G146','2','In Taten und Natur war ich<br/>Von Gott ja wirklich fern;<br/>Doch nun durch Gnade nahte Ihm,<br/>Und durch das Blut des Herrn.<br/>',NULL,46673,2);
INSERT INTO stanza VALUES('G146','3','So nah, so wirklich nah bei Gott,<br/>Noch näher geht nicht mehr;<br/>In Seinem Sohn bin ich Ihm nah,<br/>Ich bin so nah wie Er.<br/>',NULL,46674,3);
INSERT INTO stanza VALUES('G146','4','Ich bin von teurem Wert für Gott,<br/>Noch teurer geht nicht mehr;<br/>Wie liebte Er doch Seinen Sohn,<br/>Auch mich liebt Er so sehr.<br/>',NULL,46675,4);
INSERT INTO stanza VALUES('G146','5','Weshalb soll ich noch ängstlich sein,<br/>Wenn solch ein Gott ist mein?<br/>Er wacht beständig über mir<br/>Und sagt mir: „Mein ist dein“.<br/>',NULL,46676,5);
INSERT INTO stanza VALUES('G147','1','Dort, wo am Kreuz einst mein Retter starb,<br/>Gottes Gerechtigkeit ich erwarb;<br/>Dort wusch Sein Blut meine Sünden ab,<br/>Ehre sei dem Herrn!<br/>',NULL,46677,1);
INSERT INTO stanza VALUES('G147','chorus','Ehre sei dem Herrn!<br/>Ehre sei dem Herrn!<br/>Dort wusch Sein Blut meine Sünden ab,<br/>Ehre sei dem Herrn!<br/>',NULL,46678,2);
INSERT INTO stanza VALUES('G147','2','Frei von der Sünde am Brunnen hier,<br/>Unsre Erlösung genießen wir;<br/>Ewig genieß sie und jubilier,<br/>Ehre sei dem Herrn!<br/>',NULL,46679,3);
INSERT INTO stanza VALUES('G147','3','Ja, diese Tatsache gibt mir Halt:<br/>Nicht nur die Sündenschuld ist bezahlt;<br/>Sein Lebensquell mir entgegenwallt,<br/>Ehre sei dem Herrn!<br/>',NULL,46680,4);
INSERT INTO stanza VALUES('G147','chorus','Ehre sei dem Herrn!<br/>Ehre sei dem Herrn!<br/>Sein Lebensquell mir entgegenwallt,<br/>Ehre sei dem Herrn!<br/>',NULL,46681,5);
INSERT INTO stanza VALUES('G147','4','Beides, erlöst und erquickt, sind wir,<br/>Dein Blut uns wusch, ja, wir bleiben hier;<br/>Trinken Dein Leben und danken Dir,<br/>Ehre sei dem Herrn!<br/>',NULL,46682,6);
INSERT INTO stanza VALUES('G148','1','Welche Gewissheit, Jesus ist mein!<br/>Welch Herrlichkeit, ich bin ewiglich Sein!<br/>Von Gott erkauft, welch Rettung, so gut!<br/>Vom Geist geboren, rein durch Sein Blut.<br/>',NULL,46683,1);
INSERT INTO stanza VALUES('G148','chorus','Dies ist mein Zeugnis und mein Gesang,<br/>Ich preise Jesus mein Leben lang.<br/>Dies ist mein Zeugnis und mein Gesang,<br/>Ich preise Jesus mein Leben lang.<br/>',NULL,46684,2);
INSERT INTO stanza VALUES('G148','2','Bin ganz ergeben, und voller Freud,<br/>Meine Vision ist Entrückung schon heut;<br/>Auf meinen Pfad streust Du allezeit<br/>Liebe und große Barmherzigkeit.<br/>',NULL,46685,3);
INSERT INTO stanza VALUES('G148','3','Bin ganz ergeben, Ruhe zieht ein,<br/>Ich bin so fröhlich, gesegnet zu sein;<br/>Wachend und betend schau ich zu Dir,<br/>In Deiner Liebe mich ganz verlier.<br/>',NULL,46686,4);
INSERT INTO stanza VALUES('G149','1','Wunderbar, Gottes Leben veränderte mich,<br/>Seit Jesus zog ein in mein Herz!<br/>Meine Seele hat Licht und ist ganz außer sich,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46687,1);
INSERT INTO stanza VALUES('G149','chorus','Seit Jesus zog ein in mein Herz!<br/>Seit Jesus zog ein in mein Herz!<br/>Freude zog in mich ein, und durchflutet mein Sein,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46688,2);
INSERT INTO stanza VALUES('G149','2','All mein Wandern und Suchen ist endlich vorbei,<br/>Seit Jesus zog ein in mein Herz!<br/>Er wusch ab meine Sünden und machte mich frei,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46689,3);
INSERT INTO stanza VALUES('G149','3','Mich erfüllt eine Hoffnung, die felsenfest steht,<br/>Seit Jesus zog ein in mein Herz!<br/>Auf dem Weg jede Wolke des Zweifels vergeht,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46690,4);
INSERT INTO stanza VALUES('G149','4','Auf dem Weg durch das Todestal scheint mir ein Licht,<br/>Seit Jesus zog ein in mein Herz!<br/>Und danach sind die Tore der Stadt schon in Sicht,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46691,5);
INSERT INTO stanza VALUES('G149','5','In die Stadt werd ich gehen und wohnen darin,<br/>Seit Jesus zog ein in mein Herz!<br/>Ich bin glücklich und lauf auf dem Weg froh dorthin,<br/>Seit Jesus zog ein in mein Herz!<br/>',NULL,46692,6);
INSERT INTO stanza VALUES('G150','1','Ich war in Sündenketten gebunden,<br/>Kämpfte vergeblich in Sklaverei;<br/>Herrliche Freiheit hab ich empfangen,<br/>Als Jesus brach die Ketten entzwei.<br/>',NULL,46693,1);
INSERT INTO stanza VALUES('G150','chorus','Herrliche Freiheit, wirkliche Freiheit,<br/>Denn Sündenketten plagen nicht mehr!<br/>Jesus, mein wunderbarer Befreier,<br/>Jetzt und für immer ist Er mein Herr.<br/>',NULL,46694,2);
INSERT INTO stanza VALUES('G150','2','Freiheit von jeder fleischlichen Neigung,<br/>Freiheit von Neid, von Hass und von Streit;<br/>Freiheit von eitlem, weltlichem Ehrgeiz,<br/>Freiheit von Gram und Trostlosigkeit.<br/>',NULL,46695,3);
INSERT INTO stanza VALUES('G150','3','Freiheit von Stolz und sündiger Torheit,<br/>Freiheit von aller Liebe zum Geld;<br/>Freiheit von schlechter Laune und Ärger,<br/>Herrlich, entrückt zu sein von der Welt.<br/>',NULL,46696,4);
INSERT INTO stanza VALUES('G150','4','Freiheit von Angst mit all ihren Qualen,<br/>Freiheit von Sorgen, Leid und Geschrei;<br/>Freiheit in Christus, meinem Erlöser,<br/>Er brach die Sklavenketten entzwei.<br/>',NULL,46697,5);
INSERT INTO stanza VALUES('G151','1','O Wundergnad! Wie süß der Ton,<br/>Der rettet Ein''n wie mich!<br/>Denn sie mich fand, war einst verlorn,<br/>War blind, doch nun seh ich.<br/>',NULL,46698,1);
INSERT INTO stanza VALUES('G151','2','Die Gnad mein Herz recht fürchten lehrt''<br/>Die Gnad all Angst mir nahm;<br/>Wie kostbar mir erschien die Gnad,<br/>Als ich zum Glauben kam!<br/>',NULL,46699,2);
INSERT INTO stanza VALUES('G151','3','Der Herr verhieß, mir wohl wird sein,<br/>Sein Wort mein'' Hoffnung nährt;<br/>Er wird mein Schild und Anteil sein,<br/>So lang ich leb auf Erd.<br/>',NULL,46700,3);
INSERT INTO stanza VALUES('G151','4','Wenn wir dort sind zehntausend Jahr,<br/>Hell scheinen wie die Sonn,<br/>Dann sind der Tag'' zum Preis noch mehr,<br/>Als dort wir fingen an.<br/>',NULL,46701,4);
INSERT INTO stanza VALUES('G152','1','Jahrelang vergeblich sucht'' ich einen Quell,<br/>Der für ewig fließt und quillt;<br/>Was die Welt mir bot, das hat mich nie erfüllt,<br/>Nichts hat meinen Durst gestillt.<br/>',NULL,46702,1);
INSERT INTO stanza VALUES('G152','chorus','Trinke von dem Brunnen, der niemals versiegt,<br/>Trinke von dem Brunnen, der Leben gibt;<br/>Freude und Vergnügen<br/>Schmeck in vollen Zügen,<br/>Wenn ich trink vom Quell, der Leben gibt.<br/>',NULL,46703,2);
INSERT INTO stanza VALUES('G152','2','In der Sündenwüste wandre ich nicht mehr,<br/>Denn ich fand den Lebensquell,<br/>Und mein Kelch der Freude überfließt nun sehr,<br/>Jesus thront in meiner Seel!<br/>',NULL,46704,3);
INSERT INTO stanza VALUES('G152','3','Hier gibt Er mir Tag für Tag Zufriedenheit,<br/>Seinen Frieden, Seine Ruh;<br/>Hier schenkt Er mir Seinen Trost zu jeder Zeit,<br/>Voller Segen immerzu.<br/>',NULL,46705,4);
INSERT INTO stanza VALUES('G152','4','Hier stellt Er mir Seinen Reichtum stets bereit,<br/>Mich erfrischt auf meinem Pfad;<br/>Ja, zum Quell der Heilung flieh ich allezeit,<br/>Meine matte Seele bad.<br/>',NULL,46706,5);
INSERT INTO stanza VALUES('G153','1','Lobt Gott, denn Christus lebt in uns,<br/>Gott uns so reich errettet;<br/>Durch Gottes Leben rettet Er,<br/>Uns nicht an Regeln kettet;<br/>Allein hab ich es nicht geschafft,<br/>Sein Leben ändert mich voll Kraft:<br/>Nur Gottes Leben kann es.<br/>',NULL,46707,1);
INSERT INTO stanza VALUES('G153','2','Er rettet bis zum Äußersten,<br/>Will Lebenskraft uns geben;<br/>Er teilt Sich aus in uns hinein,<br/>Will uns aus Tod erheben.<br/>Verlorne rettet, nimmt Er ein,<br/>Befreit von mehr als Sünd allein:<br/>In Herrlichkeit Er bringt uns!<br/>',NULL,46708,2);
INSERT INTO stanza VALUES('G153','3','Zum Priester wurde Er bestimmt,<br/>Um Leben zu verleihen;<br/>Leben ist die Natur von Ihm,<br/>Der kann vom Selbst befreien:<br/>Sein Leben kein Verderben kennt,<br/>Uns voll errettet bis zum End:<br/>Nur Er vermag, zu retten!<br/>',NULL,46709,3);
INSERT INTO stanza VALUES('G153','4','Sein Leben ist qualifiziert<br/>In Herrlichkeit zu bringen;<br/>Nur Sein geprüftes Leben kann<br/>Rettung für uns erringen;<br/>Bis hin zum Kreuz stand Christus fest,<br/>Hat Sich bewährt in jedem Test:<br/>Er ging durch Tod und Hades.<br/>',NULL,46710,4);
INSERT INTO stanza VALUES('G153','5','Er bürgt nun sicher unser Heil,<br/>Sein Leben wirkt beständig;<br/>Was Er bewirkt und arrangiert,<br/>Dient uns, macht uns vollständig.<br/>Das eigne Leben steht nicht fest,<br/>Sein Leben nur besteht den Test:<br/>Er rettet uns vollkommen!<br/>',NULL,46711,5);
INSERT INTO stanza VALUES('G153','6','Er lebt, um für uns einzustehn,<br/>Er lebt auf Ewigkeiten;<br/>Sein Priestertum kann nie vergehn,<br/>Es währt durch alle Zeiten.<br/>Er tritt stets ein, dient dir und mir,<br/>Den Hohen Priester brauchen wir:<br/>Hoch über allen Himmeln.<br/>',NULL,46712,6);
INSERT INTO stanza VALUES('G153','7','Tretet durch Ihn zu Gott hinzu,<br/>Weicht nicht, was bringt Verderben;<br/>Sein Leben doch in Anspruch nehmt,<br/>Als Glieder funktionieren.<br/>Kommt vorwärts, nehmt Sein Leben ein,<br/>Wir werden Gottes Volk dann sein,<br/>So wird der Tod verschlungen.<br/>',NULL,46713,7);
INSERT INTO stanza VALUES('G154','1','Ob Ströme des Friedens erleichtern den Weg,<br/>Ob Sorgen wild toben mit Wut;<br/>Was immer mir zustößt, hast Du dies gelehrt:<br/>„Meiner Seel, meiner Seel geht es gut!“<br/>',NULL,46714,1);
INSERT INTO stanza VALUES('G154','chorus','Meiner Seel geht es gut!<br/>Meiner Seel, meiner Seel geht es gut!<br/>',NULL,46715,2);
INSERT INTO stanza VALUES('G154','2','Wenn Satan umherwirft, wenn Trübsal mich prüft,<br/>Dann hält mich ein sicheres Heil;<br/>Denn Christus, Er sah meinen hilflosen Stand,<br/>Gab Sein Blut, gab''s für dich, meine Seel.<br/>',NULL,46716,3);
INSERT INTO stanza VALUES('G154','3','Er hat meine Sünden genagelt ans Kreuz,<br/>Er trug sie als Lamm ohne Fehl,<br/>Die Last ist nun weg, und ich trag sie nicht mehr;<br/>Lob den Herrn, lob den Herrn, meine Seel!<br/>',NULL,46717,4);
INSERT INTO stanza VALUES('G154','4','Von nun an ist Christus das Leben für mich,<br/>In Finsternis leuchtet Er hell;<br/>Von Angst bin ich frei, denn in Leben und Tod<br/>Sprichst Du Frieden mir zu, meiner Seel.<br/>',NULL,46718,5);
INSERT INTO stanza VALUES('G155','1','Gott errettet von der Welt;<br/>Zurückgehen will ich niemals mehr.<br/>Gott errettet von der Welt;<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46719,1);
INSERT INTO stanza VALUES('G155','chorus','Nein, nein, nein, nein, nein,<br/>Zurückgehen will ich niemals mehr;<br/>Nein, nein, nein, nein, nein,<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46720,2);
INSERT INTO stanza VALUES('G155','2','Ich kam raus aus Babylon;<br/>Zurückgehen will ich niemals mehr.<br/>Ich kam raus aus Babylon;<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46721,3);
INSERT INTO stanza VALUES('G155','3','Ich fand die Gemeind am Ort;<br/>Zurückgehen will ich niemals mehr.<br/>Ich fand die Gemeind am Ort;<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46722,4);
INSERT INTO stanza VALUES('G155','4','Seit ich Gott in mir berühr,<br/>Zurückgehen will ich niemals mehr;<br/>Seit ich Gott in mir berühr,<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46723,5);
INSERT INTO stanza VALUES('G155','5','Christus nimmt mein Herz ganz ein;<br/>Zurückgehen will ich niemals mehr.<br/>Christus nimmt mein Herz ganz ein;<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46724,6);
INSERT INTO stanza VALUES('G155','6','Lobt den Herrn, ich bin zu Haus;<br/>Zurückgehen will ich niemals mehr.<br/>Lobt den Herrn, ich bin zu Haus;<br/>Zurückgehn will ich niemals mehr.<br/>',NULL,46725,7);
INSERT INTO stanza VALUES('G155','7','Nie zurück, denn ich bin für<br/>Die Wiedererlangung Gottes heut;<br/>Nie zurück, denn ich bin für<br/>Die Wiedererlangung des Herrn.<br/>',NULL,46726,8);
INSERT INTO stanza VALUES('G156','1','Mein Ziel ist Gott, nicht Friede oder Freud<br/>Nicht einmal Segen, sondern Gott allein;<br/>Nicht ich, doch Gott Selbst führt mich hin zum Ziel<br/>Er weist den Weg, mag er auch schwierig sein.<br/>',NULL,46727,1);
INSERT INTO stanza VALUES('G156','2','Der Glaube eilt zu seinem Ziel in Gott,<br/>Und Liebe schaut zum Herrn, der treu hinführt;<br/>In Seiner Hand folgt meine Seele fest,<br/>Bis Gott mein tiefstes Flehen ganz erhört.<br/>',NULL,46728,2);
INSERT INTO stanza VALUES('G156','3','Wenn auch der Weg durch dunkle Täler führt,<br/>Wenn ich auch einen hohen Preis bezahl;<br/>Er weiß genau, wie ich das Ziel erreich,<br/>Der Weg, der zu Ihm führt ist immer schmal.<br/>',NULL,46729,3);
INSERT INTO stanza VALUES('G156','4','Ich weiß nur eins – ich sage Ihm nicht ab;<br/>Ich tu nur eins – ich jage hin zum Herrn;<br/>Gott – meine Herrlichkeit hier Tag für Tag,<br/>Und dort in Herrlichkeit mein großer Lohn.<br/>',NULL,46730,4);
INSERT INTO stanza VALUES('G157','1','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Lass Deinen Glanz strahln hier,<br/>Zieh mich ganz nah zu Dir,<br/>Liebevoll sprich zu mir –<br/>Nichts zwischen uns.<br/>',NULL,46731,1);
INSERT INTO stanza VALUES('G157','2','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Irdischen Lärm entfern,<br/>Dich hören möcht ich gern,<br/>Und voller Freude ehrn –<br/>Nichts zwischen uns.<br/>',NULL,46732,2);
INSERT INTO stanza VALUES('G157','3','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Irdische Sorgen gehn,<br/>Nichts von Gebet noch Trän,<br/>Nichts von dem Selbst bestehn –<br/>Nichts zwischen uns.<br/>',NULL,46733,3);
INSERT INTO stanza VALUES('G157','4','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Unglaube geh von mir,<br/>Zweifel verschwinde hier,<br/>Denn ich bin nah bei Dir –<br/>Nichts zwischen uns.<br/>',NULL,46734,4);
INSERT INTO stanza VALUES('G157','5','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Wolkenlos strahl mich an,<br/>Brich Dir durch Nebel Bahn,<br/>Bis Dich mein Herz sehn kann –<br/>Nichts zwischen uns.<br/>',NULL,46735,5);
INSERT INTO stanza VALUES('G157','6','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Ich will mit Dir nur gehn,<br/>In Deine Augen sehn,<br/>In Deiner Liebe stehn –<br/>Nichts zwischen uns.<br/>',NULL,46736,6);
INSERT INTO stanza VALUES('G157','7','Nichts zwischen uns, Herr, nichts zwischen uns;<br/>Komm, durch Dein helles Licht,<br/>Dunkel der Welt vernicht,<br/>Und erhell meine Sicht –<br/>Nichts zwischen uns.<br/>(Die letzte zeile jeder Strophe wiederholen.)<br/>',NULL,46737,7);
INSERT INTO stanza VALUES('G158','1','Wenn mich meine Reise<br/>Hin zum Kreuze führt,<br/>Sind wohin Du leitest,<br/>Schmerz und Leid gespürt,<br/>Lass doch meine Tröstung<br/>Täglich, stündlich sein<br/>Liebliche Gemeinschaft<br/>Mit Dir, Herr, allein.<br/>',NULL,46738,1);
INSERT INTO stanza VALUES('G158','2','Schwindet Erdenfreude,<br/>Himmlische erweis!<br/>Auch wenn''s mir das Herz bricht,<br/>Singt mein Geist Dir Preis;<br/>Reißt auf Dein''n Willen<br/>Süßes Erdenband,<br/>Ich, an Dich gebunden,<br/>Süßre Freude fand.<br/>',NULL,46739,2);
INSERT INTO stanza VALUES('G158','3','Ist der Pfad oft einsam,<br/>Doch Dein Lächeln freut;<br/>Sei Du mein Gefährte<br/>Durch das kurze Heut;<br/>Füll mich mit der Gnade,<br/>Bis ich selbstlos leb,<br/>Und mich als Kanal, Herr,<br/>Für Dein Leben geb.<br/>',NULL,46740,3);
INSERT INTO stanza VALUES('G159','1','Auf den Berg, o Retter, führ mich,<br/>Wo wir sehen Dich allein,<br/>Wo wir hörn die Himmels-Stimme,<br/>Wo die Luft ist klar und rein.<br/>',NULL,46741,1);
INSERT INTO stanza VALUES('G159','chorus','Führ mich höher auf den Berg, Herr,<br/>Schenk Gemeinschaft, Herr, mit Dir;<br/>Dort im Licht seh ich den Brunnen,<br/>Und das Blut, es reinigt mich.<br/>',NULL,46742,2);
INSERT INTO stanza VALUES('G159','2','Höher drauf, wo Licht noch zunimmt,<br/>Über allem Zank und Streit,<br/>Wo im Leben frei wir herrschen,<br/>Alle Mühen sind vorbei.<br/>',NULL,46743,3);
INSERT INTO stanza VALUES('G159','3','Retter, halt mich auf dem Berge,<br/>Bring mich noch ans Ziel heran,<br/>Bis Dein Bild wir alle teilen,<br/>Deine Gnade preisen an.<br/>',NULL,46744,4);
INSERT INTO stanza VALUES('G160','1','Sein Angesicht schauen die Engel oft an,<br/>Doch Liebe und Gnade spürn nicht;<br/>Wir kennen die maßlose Liebe des Herrn,<br/>Doch schauten nie Sein Angesicht.<br/>Die Heiligen sehen Sein Angesicht bald,<br/>Genießen die Herrlichkeit reich;<br/>Maria jedoch, als Er weinte, Ihn sah,<br/>Die Herzensqual spürte sogleich.<br/>Die Herzensqual spürte sogleich.<br/>',NULL,46745,1);
INSERT INTO stanza VALUES('G160','2','Bald sehn wir persönlich den Herrn wie Er ist,<br/>In Fülle erkennen Ihn dann;<br/>Doch so wie Er unser Herz heute berührt,<br/>Dann nicht mehr gespürt werden kann.<br/>Dann gibt''s, wenn wir ewig Ihn preisen und ehrn,<br/>Kein Flehen, noch Tränen-Gebet;<br/>Noch gibt es den Trost der bei Schmerzen zufließt,<br/>Noch Glaube in Trübsal entsteht.<br/>Noch Glaube in Trübsal entsteht.<br/>',NULL,46746,2);
INSERT INTO stanza VALUES('G160','3','In Herrlichkeit werden wir bald schon gekrönt,<br/>Kein einziges Kreuz dort mehr gibt''s;<br/>An süßer Gemeinschaft der Leiden des Herrn<br/>Teilhaben nur jetzt möglich ist.<br/>Wir gehn zur Ruh ein, keine Mattigkeit spürn,<br/>Und nie mehr auf uns wird abzieln<br/>Erprobungen, Drangsale, Unglücklichsein,<br/>Noch Leiden um Seinetwillen.<br/>Noch Leiden um Seinetwillen.<br/>',NULL,46747,3);
INSERT INTO stanza VALUES('G160','4','Die Aussicht für Ihn hier zu leiden ist rar,<br/>Erdulden von Spott oder Schand;<br/>Die schöne Gelegenheit schwindet dahin,<br/>Dass Er uns im Leid gibt die Hand.<br/>Verachtung, Verschmähung und Missverständnis,<br/>Misshandlung und Einsamkeit hier;<br/>Solch Segnungen schätz ich, denn durch sie ich komm<br/>In süße Gemeinschaft mit Dir.<br/>In süße Gemeinschaft mit Dir.<br/>',NULL,46748,4);
INSERT INTO stanza VALUES('G160','5','Ich sehne mich, bald schon Dein Antlitz zu schaun,<br/>Und Dich mit Entzückung begrüß.<br/>Doch will ich die Trübsale jetzt nicht umgehn;<br/>Solch Zeiten dank Dir werden süß.<br/>Erfüll mich mit Liebe, erbarme Dich mein,<br/>Für Dich nehm ich auf jede Last;<br/>Damit nicht Dein Diener, der auf den Tag hofft,<br/>Bereut, dass er Chancen verpasst.<br/>Bereut, dass er Chancen verpasst.<br/>',NULL,46749,5);
INSERT INTO stanza VALUES('G161','1','Herr Jesus, mein Sehnen ist mit Dir zu sein,<br/>Vom Morgen sei alles mir bis Tagesend;<br/>Oh, lass meinem Herz keine Muße noch Ruh<br/>Ersehnet und liebt es, was mich von Dir trennt.<br/>Erbringen mir Tage viel Kummer und Leid,<br/>Wo nichts in der Welt und ihr Trost zu mir stehn,<br/>Gar Seufzen und Weinen umschlingen mich dicht,<br/>Herr, still all mein Seufzen, und wisch jede Trän.<br/>',NULL,46750,1);
INSERT INTO stanza VALUES('G161','2','Wenn immer vom Guten des Lebens ich träum,<br/>So bet ich, dass Du diese Freude seist mir;<br/>Erlaube nicht, dass ich entscheide allein,<br/>Vergnügen nachlaufe, die außer von Dir.<br/>Wenn nachts ich daliege, in Stille, allein,<br/>Dann bet ich Dich, Herr, dass Du stets bei mir bist;<br/>All Morgen erweck mich mit Flüstern im Schlaf,<br/>Und öffne mein Ohr, Herr, bevor es Tag ist.<br/>',NULL,46751,2);
INSERT INTO stanza VALUES('G161','3','Beim Lesen, Herr, in Deinem heiligen Wort<br/>Lass jeder Satz mit Deiner Herrlichkeit schein''n,<br/>Dass wahrlich ich seh, welchen Retter ich hab,<br/>Welch große Errettung Du machtest schon mein.<br/>Wenn hilflos ich vor Deinen Thron niederknie,<br/>Dann bet ich, erhör mich, die Gnade schenk mir;<br/>Falls durch mein Versagen Du mich nicht erhörst,<br/>Verbirg nicht Dein Antlitz, es mir nicht entzieh.<br/>',NULL,46752,3);
INSERT INTO stanza VALUES('G161','4','Stets wenn ich an himmlische Segnungen denk,<br/>Mein Herz trachte, es sei zu Dir schon entrückt;<br/>Allein Deine Rückkehr ist Hoffnung mir hier,<br/>Allein Deine Gegenwart dort es entzückt.<br/>Herr Jesus, mein Sehnen ist mit Dir zu sein,<br/>Vom Morgen sei alles mir bis Tagesend;<br/>Oh, lass meinem Herz keine Muße noch Ruh,<br/>Ersehnet und liebt es, was mich von Dir trennt.<br/>',NULL,46753,4);
INSERT INTO stanza VALUES('G162','1','Retter, leit mich, bete ich,<br/>Stets durch Deinen Geist führ mich;<br/>Mich im Licht des Lebens leit,<br/>Was von eigner Müh befreit.<br/>',NULL,46754,1);
INSERT INTO stanza VALUES('G162','chorus','Leit mich, leit mich,<br/>Alles Dir zu Füß'' ich leg;<br/>Tief im Strom des Lebens leit,<br/>Retter, leit mich Deinen Weg.<br/>',NULL,46755,2);
INSERT INTO stanza VALUES('G162','2','Führ als Leben innerlich<br/>Durchs Gesetz des Lebens mich;<br/>Deinen Thron in mir erricht,<br/>Meine Nacht mach so zum Licht.<br/>',NULL,46756,3);
INSERT INTO stanza VALUES('G162','3','Geist, der frei macht, regulier<br/>All mein Sein und wirk in mir;<br/>Den Verstand machst Du mir neu,<br/>Zeigst mir Deinen Willen treu.<br/>',NULL,46757,4);
INSERT INTO stanza VALUES('G163','1','Herr Jesus Christus, wachs in mir,<br/>Bis alles andre weicht;<br/>Zieh mein Herz täglich näher Dir,<br/>Von Sünde frei und leicht.<br/>',NULL,46758,1);
INSERT INTO stanza VALUES('G163','chorus','Lass Deine Macht die Schwachheit mir<br/>Umfangen täglich neu;<br/>Mein Tod im Leben schwinde schier,<br/>Mein Dunkel Dein Licht zerstreu.<br/>',NULL,46759,2);
INSERT INTO stanza VALUES('G163','2','In Deinem hellen Strahlenschein<br/>Muss böses Denken gehn;<br/>Dass ich soll nichts, Du alles sein,<br/>Dies lehr mich doch zu sehn.<br/>',NULL,46760,3);
INSERT INTO stanza VALUES('G163','3','Du Weiser, Treuer, zeig mir mehr<br/>Von Deiner Herrlichkeit;<br/>Ich wäre gern Dein Ausdruck hier<br/>In Freude und in Leid.<br/>',NULL,46761,4);
INSERT INTO stanza VALUES('G163','4','Füll mich mit Freud von oben her,<br/>Stütz mich mit Deiner Kraft;<br/>Bis Deine große Liebe, Herr,<br/>Durch mich sich Bahnen schafft.<br/>',NULL,46762,5);
INSERT INTO stanza VALUES('G163','5','Wirk, dass mein armes Selbst nimmt ab,<br/>Mögst Du mein Ziel nur sein;<br/>Schenk, dass ich täglich Gnade hab<br/>Zu leben Dir allein.<br/>',NULL,46763,6);
INSERT INTO stanza VALUES('G164','1','Ich geh hinauf, zu Christus hin,<br/>Mehr Höhe jeden Tag gewinn;<br/>Nur ein Gebet füllt meinen Mund:<br/>„Pflanz meinen Fuß auf höhren Grund“.<br/>',NULL,46764,1);
INSERT INTO stanza VALUES('G164','chorus','Herr, heb mich auf und lass mich stehn,<br/>Im Glauben lass mich Kana''n sehn;<br/>Ja, richt mich auf zu jeder Stund,<br/>„Pflanz meinen Fuß auf höhren Grund“.<br/>',NULL,46765,2);
INSERT INTO stanza VALUES('G164','2','Mein Herz hat keinen Wunsch zu sein,<br/>Wo Angst und Zweifel dringen ein;<br/>Dort länger weiln ist nicht gesund,<br/>Ich bete für den höhren Grund.<br/>',NULL,46766,3);
INSERT INTO stanza VALUES('G164','3','Ich will weit droben von der Welt,<br/>Auch wenn der Böse Tücken stellt;<br/>Denn Glaube tut mit Freuden kund<br/>Der Heil''gen Lied auf höhrem Grund.<br/>',NULL,46767,4);
INSERT INTO stanza VALUES('G164','4','Ich will erklimm''n die Höhen licht,<br/>Wo Herrlichkeit erfüllt die Sicht;<br/>Ich bete noch, bis dies gefund'':<br/>„Herr, führe mich auf höhren Grund“.<br/>',NULL,46768,5);
INSERT INTO stanza VALUES('G165','1','Lehre uns beten, Herr,<br/>Nicht wie Nationen tun so leer,<br/>Vom eignen Weg uns kehr,<br/>Bewirke, dass wir Dich anrufen mehr –<br/>Herr Jesus, wachs in uns.<br/>',NULL,46769,1);
INSERT INTO stanza VALUES('G165','2','Same des Lebens, Du<br/>Hast Dich in unser Herz gesät,<br/>Der Anfang wohl gerät,<br/>Mit Leben speise uns von früh bis spät –<br/>Herr Jesus, wachs in uns.<br/>',NULL,46770,2);
INSERT INTO stanza VALUES('G165','3','Mach unser Herz so weich;<br/>Du weißt, wie es versagen kann.<br/>Wir rufen Dich nun an,<br/>Grab Steine aus, verschaff Dir freie Bahn<br/>Herr Jesus, wachs in uns.<br/>',NULL,46771,3);
INSERT INTO stanza VALUES('G165','4','Klar wird in Deinem Licht,<br/>So oft beachten wir Dich nicht;<br/>Doch wahr ist der Bericht,<br/>Der Same wächst und durch die Schale bricht –<br/>Herr Jesus, wachs in uns.<br/>',NULL,46772,4);
INSERT INTO stanza VALUES('G165','5','Mach uns im Geist so arm;<br/>Von aller Meinung uns entleer,<br/>Wir öffnen uns, Dir, Herr,<br/>In Deinem Lebensstrom wachsen wir mehr –<br/>Herr Jesus, wachs in uns.<br/>',NULL,46773,5);
INSERT INTO stanza VALUES('G165','6','Mach uns im Herzen rein;<br/>In Liebe formt uns Deine Hand,<br/>Herr, füll uns bis zum Rand,<br/>Mach neu Gefühl und Willen und Verstand –<br/>Herr Jesus, wachs in uns.<br/>',NULL,46774,6);
INSERT INTO stanza VALUES('G165','7','Mehr unser Herz berühr,<br/>Dass es Dich täglich lieben kann;<br/>Der Same bricht sich Bahn,<br/>Dein Wachstum bringt Dein Königreich voran<br/>Herr Jesus, wachs in uns.<br/>',NULL,46775,7);
INSERT INTO stanza VALUES('G165','8','Amen! – das Leben wächst!<br/>Nichts Deinem Leben ist zu schwer;<br/>Erneure uns stets mehr,<br/>Wir überwinden nur durch Dich, o Herr.<br/>Herr Jesus, wachs in uns.<br/>Herr Jesus, wachs in uns.<br/>',NULL,46776,8);
INSERT INTO stanza VALUES('G166','1','Dir gleich zu sein! Geliebter Erlöser,<br/>Ist meine Sehnsucht und mein Begehr;<br/>Irdische Schätze lasse ich gerne,<br/>Gleich sein wie Du, mein Jesus, mein Herr.<br/>',NULL,46777,1);
INSERT INTO stanza VALUES('G166','chorus','Dir völlig gleich sein! Dir völlig gleich sein!<br/>Liebster Erlöser, wie Du, so rein;<br/>Komm voller Süße, komm voller Reichtum;<br/>Präge Dein Bild tief in mein Herz ein.<br/>',NULL,46778,2);
INSERT INTO stanza VALUES('G166','2','Dir gleich zu sein! Voll Liebe und Sanftmut,<br/>Andern vergeben, so wie Du mir,<br/>Hilflosen helfen, Traurige trösten,<br/>Ruhlose Sünder bringen zu Dir.<br/>',NULL,46779,3);
INSERT INTO stanza VALUES('G166','3','Dir gleich zu sein! Voll Demut und Sanftmut,<br/>Heilig und kühn, geduldig verweil;<br/>Willig zu leiden, Vorwurf ertragen,<br/>Den Sündern wird so Rettung zuteil.<br/>',NULL,46780,4);
INSERT INTO stanza VALUES('G166','4','Dir gleich zu sein! Ich komme zu Dir, Herr,<br/>Dass ich von Dir die Salbung empfang;<br/>Was ich nur bin und habe Dir bringe;<br/>Alles sei Dein, o Herr, von nun an.<br/>',NULL,46781,5);
INSERT INTO stanza VALUES('G166','5','Dir gleich zu sein! Gieß reich Deinen Geist aus,<br/>Mit Deiner Liebe fülle mein Sein.<br/>Mach mich zu Deinem heiligen Tempel,<br/>Rüste mich zu und nimm mich ganz ein.<br/>',NULL,46782,6);
INSERT INTO stanza VALUES('G167','1','Christus gleichgestaltet<br/>Wünscht mein Herz sich sehr!<br/>Möge Er erfüllen<br/>Meiner Seel Begehr.<br/>',NULL,46783,1);
INSERT INTO stanza VALUES('G167','2','Christus gleichgestaltet!<br/>Er ist heut der Geist!<br/>Herrscht Er, meinem Wunsch Er<br/>Wirklichkeit erweist.<br/>',NULL,46784,2);
INSERT INTO stanza VALUES('G167','3','Wie ein Spiegel schau ich<br/>Christi Herrlichkeit;<br/>Ich kann widerspiegeln<br/>Gnade allezeit.<br/>',NULL,46785,3);
INSERT INTO stanza VALUES('G167','4','Möge nichts verschleiern<br/>Meinen Herrn forthin;<br/>Doch mit reinem Herzen<br/>Widerspiegle Ihn.<br/>',NULL,46786,4);
INSERT INTO stanza VALUES('G167','5','Herrlichkeit in Seinem<br/>Antlitz ich bestaun;<br/>Ständig nur betrachtend,<br/>Will ich Ihn anschaun.<br/>',NULL,46787,5);
INSERT INTO stanza VALUES('G167','6','Christus gleichgestaltet<br/>Werden, möcht ich gern!<br/>Und so wie ein Spiegel<br/>Reflektiern den Herrn.<br/>',NULL,46788,6);
INSERT INTO stanza VALUES('G167','7','Christus gleichgestaltet<br/>Widerspiegeln rein;<br/>Ihm von Herrlichkeit zu<br/>Herrlichkeit gleich sein.<br/>',NULL,46789,7);
INSERT INTO stanza VALUES('G168','1','Lebe Du durch mich, Herr Jesus,<br/>Denn mein Leben bist nur Du;<br/>Ich nehm Dich für all Probleme<br/>Als die volle Lösung nun.<br/>Lebe Du durch mich, Herr Jesus,<br/>Stets Dein Wille soll geschehn;<br/>Mein Gefäß soll rein und klar sein,<br/>So wirst Du in mir gesehn.<br/>',NULL,46790,1);
INSERT INTO stanza VALUES('G168','2','Herr, Dein Tempel ist geweiht Dir,<br/>Und gereinigt, fleckenlos;<br/>Mög aus seinem Innern strahlen<br/>Herrlichkeit so grenzenlos.<br/>Lass die Erde staunend sehen,<br/>Dass mein Leib, Dir dargebracht,<br/>Ist gehorsam als Dein Sklave,<br/>Nur gestärkt durch Deine Macht.<br/>',NULL,46791,2);
INSERT INTO stanza VALUES('G168','3','Alle Glieder, fest umgürtet,<br/>Dein Gebot stets nehmen an;<br/>Sei es unterm Joch der Arbeit<br/>Oder weggestellt nach Plan.<br/>Bin ich eingeschränkt beim Dienen,<br/>Nimmt mich keine Unruh ein;<br/>Unter Deiner treuen Leitung<br/>Will ich stets zufrieden sein.<br/>',NULL,46792,3);
INSERT INTO stanza VALUES('G168','4','Voller Sanftmut und in Ruhe<br/>Eigne Wünsche abgelegt,<br/>Damit Du für mich kannst wählen,<br/>Wie Dein Finger zeigt den Weg.<br/>Lebe Du durch mich, Herr Jesus,<br/>Denn mein Leben bist nur Du;<br/>Ich nehm Dich für all Probleme<br/>Als die volle Lösung nun.<br/>',NULL,46793,4);
INSERT INTO stanza VALUES('G169','1','Offenbar Dich mir, o Herr,<br/>Dass das Fleisch ich kenn in mir;<br/>Und durch Deine Gnade wirk,<br/>Dass im Staub ich knie vor Dir.<br/>Wie ersehne ich den Sieg!<br/>Doch mein Leben lang ich fiel!<br/>Gutes tun, das kann ich nicht,<br/>Sondern tu, was ich nicht will.<br/>',NULL,46794,1);
INSERT INTO stanza VALUES('G169','2','Innerlich will ich den Herrn,<br/>Doch mein Handeln häßlich ist;<br/>Mich verbessern kann ich nicht,<br/>Diese Knechtschaft mich einschließt!<br/>Das Gesetz von Gott stellt bloß,<br/>Doch die Sünde bindet mich;<br/>Auch wenn ich um Freiheit kämpf,<br/>Keinen Ausweg finde ich.<br/>',NULL,46795,2);
INSERT INTO stanza VALUES('G169','3','Oft hab ich mir''s vorgenomm''n,<br/>Und so oft hab ich versagt.<br/>Statt des viel ersehnten Siegs<br/>Meine Niederlag beklag.<br/>Ich bin ganz der Sünd verkauft,<br/>Wahrlich bin ich ohne Macht;<br/>Gar nichts Gutes wohnt in mir,<br/>Dort herrscht Sünde, finstre Nacht.<br/>',NULL,46796,3);
INSERT INTO stanza VALUES('G169','4','Herr, nun kenn ich mich zum Teil,<br/>Meine Ohnmacht ich bekenn;<br/>Mein Verhalten passt mir nicht,<br/>Wie verdorben! Alles hin!<br/>Hinterlistig ist das Selbst,<br/>Darauf kann ich nicht vertraun;<br/>Meine Hoffnung kann ich nur<br/>Fest auf Jesus Christus baun.<br/>',NULL,46797,4);
INSERT INTO stanza VALUES('G169','5','An dem Kreuz zu Tod gebracht,<br/>Will ich mich auf Christus lehn;<br/>Mit dem Heil''gen Geist erfüllt,<br/>Kann ich jetzt in Ihm ganz stehn.<br/>Sein Tod wirke doch in mir,<br/>Täglich tiefer innerlich!<br/>Bis mein Selbst verschlungen ist,<br/>Und Sein Leben fließt durch mich.<br/>',NULL,46798,5);
INSERT INTO stanza VALUES('G169','6','Oh, wie bitter ist mein Fall!<br/>Werd ich, Sklave, jemals frei?<br/>Wer befreit von diesem Tod,<br/>Dass mein Leben siegreich sei?<br/>Jesus gab Sein Blut für mich,<br/>Christus – meine Heiligkeit;<br/>Ihn als Leben nehm ich auf,<br/>Und als Anteil allezeit.<br/>',NULL,46799,6);
INSERT INTO stanza VALUES('G169','7','Da Er mich geheiligt hat,<br/>Hör ich nun auf Sein Wort gern;<br/>Nie mehr muss ich schämen mich,<br/>Wenn ich komme vor den Herrn.<br/>Glaube schenkt die Gnade mir!<br/>Leben voll Erhabenheit!<br/>Preist Ihn, Er erhörte mich,<br/>Völlig hat Er mich befreit.<br/>',NULL,46800,7);
INSERT INTO stanza VALUES('G170','1','Oh, stärk meinen Geist jetzt, Herr Jesus,<br/>Oh, stärk meinen Geist in mir;<br/>Oh, stärk meinen Geist mit der Kraft, Herr,<br/>Und fülle mein Herz mit Dir.<br/>',NULL,46801,1);
INSERT INTO stanza VALUES('G170','chorus','Breite Dich aus, breite Dich aus,<br/>Hinein in mein Herz, Herr Jesus;<br/>Oh, wohn in mir, mich füll mit Dir,<br/>Mein Herz nimm ganz ein, Herr Jesus.<br/>',NULL,46802,2);
INSERT INTO stanza VALUES('G170','2','Oh, breite Dich, Herr, in mein Herz aus,<br/>Hinein in mein Herz, bet ich;<br/>Von meinem Geist breite Dich aus, Herr,<br/>Hinein in mein Herz, bet ich.<br/>',NULL,46803,3);
INSERT INTO stanza VALUES('G170','3','Mach Wohnung doch in meinem Herzen,<br/>Mach Wohnung darin, o Herr;<br/>So füllt uns so reich Deine Fülle,<br/>Mach Wohnung in mir noch mehr.<br/>',NULL,46804,4);
INSERT INTO stanza VALUES('G170','4','Dem Herrn, der noch mehr als wir bitten<br/>Und denken zu tun vermag,<br/>Ihm öffnen wir weit unsre Herzen,<br/>Empfangen Ihn Tag für Tag.<br/>',NULL,46805,5);
INSERT INTO stanza VALUES('G171','1','Nimm meine Schleier weg,<br/>Damit im Licht ich geh,<br/>Nicht mehr betrogen bin,<br/>All Dinge richtig seh.<br/>',NULL,46806,1);
INSERT INTO stanza VALUES('G171','chorus','Oh, mög Dein Licht von Leben<br/>Mir die Nacht entheben<br/>Und klare Sicht vergeben,<br/>Herr, hierfür bete ich.<br/>',NULL,46807,2);
INSERT INTO stanza VALUES('G171','2','Ich kenne mich selbst kaum,<br/>Der Stolz verblendet mich,<br/>Ich denk, nur ich hab Recht;<br/>Welch selbstzufriednes Ich!<br/>',NULL,46808,3);
INSERT INTO stanza VALUES('G171','3','Ich kenne Dich, o Herr,<br/>Nur nach Lehrmäßigkeit;<br/>Mir Offenbarung fehlt<br/>Von Deiner Wirklichkeit.<br/>',NULL,46809,4);
INSERT INTO stanza VALUES('G171','4','Dein Leben, Herr, in mir<br/>Im Dunkeln ich verkenn –<br/>Was Geist ist, und was Fleisch,<br/>Die zwei kann ich nicht trenn''n.<br/>',NULL,46810,5);
INSERT INTO stanza VALUES('G171','5','Dein Weg für mich, o Herr,<br/>Ist mir oft nicht so klar;<br/>Ich ziehe mich zurück,<br/>Und weiche ab sogar.<br/>',NULL,46811,6);
INSERT INTO stanza VALUES('G171','6','Dein Wille, Herr, für mich<br/>Ist schlecht bekannt doch mir;<br/>Ich lehn ihn öfters ab<br/>Und häufig rebellier.<br/>',NULL,46812,7);
INSERT INTO stanza VALUES('G171','7','Was die Gemeind betrifft,<br/>Schenk Offenbarung, Herr,<br/>Das Leben in dem Leib<br/>Will ich noch kennen mehr.<br/>',NULL,46813,8);
INSERT INTO stanza VALUES('G171','8','Herr, nimm die Schleier mir,<br/>Dass ich klar sehen kann,<br/>Will nicht betrogen sein,<br/>Den Stolz leg ab fortan.<br/>',NULL,46814,9);
INSERT INTO stanza VALUES('G172','1','Dein Leben gabst Du hin,<br/>Hast Tod für mich geschmeckt,<br/>Durch Dich erlöst ich bin,<br/>Uns aus dem Tod erweckt;<br/>Dein Leben gabst Du hin für mich;<br/>Was gab ich je für Dich?<br/>',NULL,46815,1);
INSERT INTO stanza VALUES('G172','2','Verbrachtest manches Jahr<br/>Für mich in Schmerz und Leid,<br/>Damit ich immerdar<br/>Seh Deine Herrlichkeit;<br/>Verbrachtest manches Jahr für mich;<br/>Gab ich auch eins für Dich?<br/>',NULL,46816,2);
INSERT INTO stanza VALUES('G172','3','Das Licht des Vaters Haus,<br/>Den Regenbogen-Thron,<br/>Mit Erden-Nacht tauschst aus,<br/>Verachtung war Dein Lohn;<br/>Ja, alles ließest Du für mich;<br/>Was ließ ich je für Dich?<br/>',NULL,46817,3);
INSERT INTO stanza VALUES('G172','4','Du trugst für mich, mein Gott,<br/>– Die Worte fehlen mir –<br/>Die Qualen bis zum Tod,<br/>Um mich zu retten hier;<br/>Du littest alles, Herr, für mich;<br/>Was trug ich je für Dich?<br/>',NULL,46818,4);
INSERT INTO stanza VALUES('G172','5','Vom Vater brachtest Du<br/>Die volle Rettung mir,<br/>Vergabst mir auch dazu,<br/>Welch Liebe fließt aus Dir!<br/>Du brachtest große Gaben mir;<br/>Was brachte ich je Dir?<br/>',NULL,46819,5);
INSERT INTO stanza VALUES('G172','6','Mein Leben sei ganz Dein,<br/>Die Jahre sind für Dich,<br/>Weltketten brich entzwei,<br/>Mit Freuden leide ich;<br/>Du gabst Dich, Herr, für mich, für mich;<br/>Ich gebe mich für Dich.<br/>(Die beiden letzten Zeilen jeder Strophe wiederholen.)<br/>',NULL,46820,6);
INSERT INTO stanza VALUES('G173','1','Hast du Ihn gehört, gesehen?<br/>Brennt für Ihn dein Herz noch nicht?<br/>Führer von Zehntausend wolln Ihn,<br/>Wähl Ihn, eh der Tag anbricht.<br/>',NULL,46821,1);
INSERT INTO stanza VALUES('G173','chorus','Ganz gebannt von Seiner Schönheit,<br/>Lass dich drängen Seinen Wert;<br/>Bring Ihm rasch Tribut entgegen,<br/>Wie''s dem König auch gebührt.<br/>',NULL,46822,2);
INSERT INTO stanza VALUES('G173','2','Einst entzückten dich die Götzen,<br/>Dich verfing ihr Sinnes-Tand;<br/>Sünd in goldnem Kleid betrog dich,<br/>Süß, dass du dich nicht gewandt.<br/>',NULL,46823,3);
INSERT INTO stanza VALUES('G173','3','Was hat abgestreift die Schönheit<br/>Von den Götzen dieser Zeit?<br/>Nicht ein Sinn für Recht und Pflichten,<br/>Doch die Sicht von Kostbarkeit.<br/>',NULL,46824,4);
INSERT INTO stanza VALUES('G173','4','Nicht der Bruch mit diesen Götzen,<br/>Der nur Leere bringt und Schmerz;<br/>Doch das Strahlen Seiner Schönheit,<br/>Das Erblicken Seines Herz''.<br/>',NULL,46825,5);
INSERT INTO stanza VALUES('G173','5','Wer denn löscht die Kerzen aus schon,<br/>Eh'' die Morgensonne strahlt?<br/>Wer legt ab die Winterkleidung,<br/>Eh'' der Sommer zeigt Gestalt?<br/>',NULL,46826,6);
INSERT INTO stanza VALUES('G173','6','Nur der Blick, der Petrus hinschmolz,<br/>Das Gesicht, das Steph''nus sah,<br/>Herz, das mit Maria weinte,<br/>Uns entzieht die Götzen gar.<br/>',NULL,46827,7);
INSERT INTO stanza VALUES('G173','7','Zieh, gewinne, uns vollkommen,<br/>Bis der Becher überquillt;<br/>Was solln wir nunmehr mit Götzen,<br/>Die wir uns zu Ihm gesellt?<br/>',NULL,46828,8);
INSERT INTO stanza VALUES('G174','1','Den Rücken kehrte ich der Welt,<br/>Sie soll nicht mehr verführen;<br/>Mein Herz will nun viel Höheres<br/>Und Heiliges berühren;<br/>Ihr Flitterglanz und Nichtigkeit<br/>Mich niemals mehr wird blenden;<br/>Ich überschritt die Schwelle schon<br/>Und ließ die Welt dahinten.<br/>',NULL,46829,1);
INSERT INTO stanza VALUES('G174','chorus','Weit, weit dahinten!<br/>Weit, weit dahinten!<br/>Ich überschritt die Schwelle schon<br/>Und ließ die Welt dahinten.<br/>',NULL,46830,2);
INSERT INTO stanza VALUES('G174','2','Ich ließ das Sündenleben jetzt,<br/>War nahe am Entgleisen;<br/>Mein neuer Stand in Christus ist,<br/>Wie Er es hat verheißen;<br/>Das Kreuz als Banner über mir,<br/>Bin ich der Welt ein Zeugnis;<br/>Ich ging vom Tod zum Leben hin,<br/>Als ich die Welt zurückließ.<br/>',NULL,46831,3);
INSERT INTO stanza VALUES('G174','chorus','Weit, weit dahinten!<br/>Weit, weit dahinten!<br/>Ich ging vom Tod zum Leben hin<br/>Und ließ die Welt dahinten.<br/>',NULL,46832,4);
INSERT INTO stanza VALUES('G174','3','Die Seele kehrt zurück nicht mehr<br/>Ins frühere Gefängnis,<br/>Vollkommnen Frieden gibt''s nur hier<br/>Und Ruhe von Verdammnis;<br/>Den Meister hab ich ausgetauscht,<br/>Die Herrlichkeit bestach mich,<br/>Und ein für alle Mal hinfort,<br/>Ich ließ die Welt dahinten.<br/>',NULL,46833,5);
INSERT INTO stanza VALUES('G174','chorus','Weit, weit dahinten!<br/>Weit, weit dahinten!<br/>Und ein für alle Mal hinfort,<br/>Ich ließ die Welt dahinten.<br/>',NULL,46834,6);
INSERT INTO stanza VALUES('G174','4','Für immer traf ich meine Wahl,<br/>Nur Ihn hab ich erkoren;<br/>Mein größtes Glück ist hier zu sein,<br/>In Seiner Lieb verloren;<br/>Mein Herz will nur noch Ihn allein,<br/>Mich soll die Welt nicht blenden;<br/>Ich ging durchs Rote Meer hindurch<br/>Und ließ die Welt dahinten.<br/>',NULL,46835,7);
INSERT INTO stanza VALUES('G174','chorus','Weit, weit dahinten!<br/>Weit, weit dahinten!<br/>Im Roten Meer von Seinem Tod<br/>Ich ließ die Welt dahinten.<br/>',NULL,46836,8);
INSERT INTO stanza VALUES('G175','1','Alles geb ich Dir, Herr Jesus,<br/>Willig ohne Vorbehalt;<br/>Dir vertrau ich, Dich, Herr, lieb ich,<br/>Hier in Deiner Gegenwart.<br/>',NULL,46837,1);
INSERT INTO stanza VALUES('G175','chorus','Alles geb ich hin,<br/>Alles geb ich hin.<br/>Dir, oh, mein geliebter Retter,<br/>Alles geb ich hin.<br/>',NULL,46838,2);
INSERT INTO stanza VALUES('G175','2','Alles geb ich Dir, Herr Jesus,<br/>Voller Demut preis ich Dich,<br/>Eitle Freude lass ich gehen;<br/>Nimm mein Leben, jetzt nimm mich.<br/>',NULL,46839,3);
INSERT INTO stanza VALUES('G175','3','Alles geb ich Dir, Herr Jesus,<br/>Mach mich, Retter, völlig Dein;<br/>Lass mich Deinen Geist berühren,<br/>Sicher wissen: Du bist mein.<br/>',NULL,46840,4);
INSERT INTO stanza VALUES('G175','4','Alles geb ich Dir, Herr Jesus,<br/>Ja, ich gebe mich Dir hin;<br/>Fülle mich mit Kraft und Liebe,<br/>In Dir ganz gesegnet bin.<br/>',NULL,46841,5);
INSERT INTO stanza VALUES('G175','5','Alles geb ich Dir, Herr Jesus,<br/>Spür Dein Feuer jetzt in mir.<br/>Volle Rettung! Welche Freude!<br/>Lob und Ehre, Herr, sei Dir!<br/>',NULL,46842,6);
INSERT INTO stanza VALUES('G176','1','Nimm mein Leben, Dir es sei,<br/>Völlig Dir, Herr, ich mich weih;<br/>Jede Stunde geb ich hin,<br/>Fließen soll Dein Lob darin.<br/>Fließen soll Dein Lob darin.<br/>',NULL,46843,1);
INSERT INTO stanza VALUES('G176','2','Nimm die Hände, lass sie nun<br/>Alles in der Liebe tun;<br/>Nimm die Füße, lass sie sein<br/>Schnell und schön für Dich allein.<br/>Schnell und schön für Dich allein.<br/>',NULL,46844,2);
INSERT INTO stanza VALUES('G176','3','Nimm die Stimme, dass sie singt,<br/>Für den König schön erklingt;<br/>Nimm die Lippen, lass sie hier<br/>Reden immerzu von Dir.<br/>Reden immerzu von Dir.<br/>',NULL,46845,3);
INSERT INTO stanza VALUES('G176','4','Nimm mein Gold und Silber, Herr,<br/>Nichts für mich behalt ich mehr;<br/>Meine Kraft und den Verstand,<br/>Nimm auch ganz in Deine Hand.<br/>Nimm auch ganz in Deine Hand.<br/>',NULL,46846,4);
INSERT INTO stanza VALUES('G176','5','Meinen Willen nimm Du ein,<br/>Er sei nicht mehr länger mein;<br/>Mach mein Herz zu Deinem Thron,<br/>Du als König darin wohn.<br/>Du als König darin wohn.<br/>',NULL,46847,5);
INSERT INTO stanza VALUES('G176','6','Meine Liebe nimm für Dich,<br/>Deine Füße salbe ich;<br/>Nimm mein ganzes Wesen ein,<br/>Alles soll für Dich, Herr, sein.<br/>Alles soll für Dich, Herr, sein.<br/>',NULL,46848,6);
INSERT INTO stanza VALUES('G177','1','Ich liebe meinen Meister,<br/>Frei ausgehn will ich nicht,<br/>Denn Er ist mein Erlöser;<br/>Auf Sich nahm das Gericht.<br/>Sein''n Dienst will ich nicht lassen,<br/>So süß ist er dazu;<br/>Und in den schwersten Stunden<br/>Schenkt Er mir wahre Ruh.<br/>',NULL,46849,1);
INSERT INTO stanza VALUES('G177','2','Sein Blut vergoss mein Meister,<br/>Erlöst mich ewiglich,<br/>Er rettet mich aus Knechtschaft,<br/>Aus Sünde, aus dem Ich.<br/>Für Seinen Dienst erkoren,<br/>Zu wählen Er mir gab<br/>Seine vollkommne Freiheit,<br/>Die ich auf ewig hab.<br/>',NULL,46850,2);
INSERT INTO stanza VALUES('G177','3','Halbherzig will nicht dienen,<br/>Nein, alles ist für Ihn!<br/>Der mich so sehr geliebt hat,<br/>Und Sich für mich gab hin.<br/>Von nun an sing ich freudig<br/>Vor Seinem Angesicht:<br/>Ich liebe meinen Meister,<br/>Frei ausgehn will ich nicht.<br/>',NULL,46851,3);
INSERT INTO stanza VALUES('G178','1','Wer gehört dem Herrn an?<br/>Wer dem König dient?<br/>Wer sind Seine Helfer?<br/>Wer tut, was sich ziemt?<br/>Wer gibt hier die Welt auf?<br/>Wer schlägt hier den Feind?<br/>Wer gehört dem Herrn an?<br/>Ist auf seiner Seit?<br/>',NULL,46852,1);
INSERT INTO stanza VALUES('G178','chorus','Durch Deine Erlösung<br/>Und die Gnade rein,<br/>Wir gehören Dir an,<br/>Retter, wir sind Dein.<br/>',NULL,46853,2);
INSERT INTO stanza VALUES('G178','2','Nicht für eitle Ehre,<br/>Nicht weil Lohn uns zieht,<br/>Singen wir den Kriegspsalm,<br/>Froh im Heer gehn mit;<br/>Doch weil Er aus Liebe<br/>Uns erlöst hat, stehn<br/>Wir auf Gottes Seite,<br/>Und in Christus gehn.<br/>',NULL,46854,3);
INSERT INTO stanza VALUES('G178','3','Du hast uns erkauft, Herr,<br/>Nicht mit Gold und Geld,<br/>Doch mit Deinem Blut, so<br/>Liebtest Du die Welt;<br/>Jeden, der zu Dir kommt,<br/>Segnest Du so reich,<br/>Du machtest uns willig,<br/>Leicht und frei zugleich.<br/>',NULL,46855,4);
INSERT INTO stanza VALUES('G178','4','Ist der Kampf auch heftig,<br/>Stark der Feind sein mag,<br/>Die Armee des Königs<br/>Wehrt ab jeden Schlag.<br/>Schart euch um die Fahne,<br/>Dort den Sieg genießt,<br/>Dank der Wahrheit uns der<br/>Sieg stets sicher ist.<br/>',NULL,46856,5);
INSERT INTO stanza VALUES('G178','5','Als Soldaten kämpfen<br/>Wir im fremden Land;<br/>Unsrem Oberst treu sein,<br/>Das ist unser Stand.<br/>Wir, im Dienst des Königs,<br/>Möchten brennend sein;<br/>Ihm ganz hingegeben,<br/>Edel, kühn und rein.<br/>',NULL,46857,6);
INSERT INTO stanza VALUES('G179','1','Wie kann ich bleiben fern von Dir,<br/>Und Deinen Geist betrüben hier?<br/>Du wartest doch auf mich!<br/>Jetzt wend ich mich Dir willig zu,<br/>Ich zögre nicht mehr, komm im Nu<br/>Und nun begleite Dich.<br/>',NULL,46858,1);
INSERT INTO stanza VALUES('G179','2','Ich gebe Dir mit frohem Mut,<br/>Was ich auch bin, mein Hab und Gut,<br/>Um Dein Verlang''n zu stilln.<br/>O liebster Herr, auf mich hab Acht,<br/>Dass ich fortan nach einem tracht:<br/>Zu tun des Vaters Willn.<br/>',NULL,46859,2);
INSERT INTO stanza VALUES('G179','3','Blick ich zurück, welch Gram und Schmach,<br/>Dass ich Dir keine Seel gebracht,<br/>Dein Wort verschloss in mir.<br/>Herr, salbe Dich in mich hinein,<br/>Leb Du allein nun durch mein Sein,<br/>So dass ich sprech von Dir.<br/>',NULL,46860,3);
INSERT INTO stanza VALUES('G179','4','Viel Gnade schenkte mir der Herr,<br/>Noch teurer als ein Freund ist Er,<br/>Seine Braut wär ich gern!<br/>Verlust soll alles andre sein,<br/>Gekreuzigt leb ich Ihm allein,<br/>Ganz eins mit meinem Herrn.<br/>',NULL,46861,4);
INSERT INTO stanza VALUES('G180','1','Oh, welche Zunge je beschreibt<br/>Wie frei die Seele wird,<br/>Wenn sie dem eitlen Trug enteilt<br/>Und Gott sie ganz regiert?<br/>Dann hat sie alles, Leben, Tod,<br/>Was ist und kommt dazu;<br/>Sie atmet Frieden ein in Gott,<br/>In Christus kommt zur Ruh.<br/>',NULL,46862,1);
INSERT INTO stanza VALUES('G180','2','Wer hier den König wählen kann,<br/>Mit Ihm den Thron darf teiln,<br/>Der überbietet Seltsamkeit,<br/>Sich nicht dem Herrn zu weihn.<br/>Von Opfer rede nimmermehr!<br/>Ein Vorrecht ungemein<br/>Ist''s, Ihm zu sein zu jedem Preis,<br/>Im Kreuzes-Heer, nur Sein.<br/>',NULL,46863,2);
INSERT INTO stanza VALUES('G180','3','Auf! Geh mit Gott den Handel ein!<br/>Ein Bruchstück für so viel –<br/>Ja, jeder Mensch und Umstand bringt,<br/>Die Seele mehr zum Ziel.<br/>Gehörst du Ihm, ist alles dir,<br/>Eins bist du mit dem Herrn;<br/>Sein Leben überfließt in dir,<br/>Sein Reich ist nicht mehr fern.<br/>',NULL,46864,3);
INSERT INTO stanza VALUES('G181','1','Ich bin eins mit Dir, Herr Jesus,<br/>Eins im Geist bin ich mit Dir;<br/>Ich bin Dein und Du bist mein, Herr,<br/>Du erfüllst mich, lebst in mir.<br/>',NULL,46865,1);
INSERT INTO stanza VALUES('G181','chorus','Eins mit Dir, eins mit Dir,<br/>Eins mit Dir, eins mit Dir;<br/>Ich genieße Deinen Reichtum,<br/>Du bist alles, alles mir.<br/>',NULL,46866,2);
INSERT INTO stanza VALUES('G181','2','Ich hab teil an Deinem Leben,<br/>Deine Menschlichkeit füllt mich,<br/>Auch Dein völliger Gehorsam<br/>Ist verfügbar innerlich.<br/>',NULL,46867,3);
INSERT INTO stanza VALUES('G181','3','Ich bin eins mit Dir am Kreuz, Herr,<br/>Bin gestorben dort in Dir;<br/>Jetzt in Dir der Welt gekreuzigt,<br/>Und die Welt gekreuzigt mir.<br/>',NULL,46868,4);
INSERT INTO stanza VALUES('G181','4','Eins mit Dir in Auferstehung,<br/>Auferweckt leb ich in Dir;<br/>Dieses Leben, das Du Selbst bist,<br/>Wohnt in mir, sogar in mir.<br/>',NULL,46869,5);
INSERT INTO stanza VALUES('G181','5','Eins mit Dir in Deiner Auffahrt<br/>In den Himmeln nun mit Dir;<br/>Hier ein Pilger, mein wahr Leben<br/>Ist verborgen, Herr, in Dir.<br/>',NULL,46870,6);
INSERT INTO stanza VALUES('G181','6','Eins mit Dir auf Deinem Thron, Herr,<br/>Üb ich Vollmacht aus mit Dir;<br/>Ich hab teil an Deinem Leben,<br/>Ich in Dir und Du in mir.<br/>',NULL,46871,7);
INSERT INTO stanza VALUES('G182','1','Eins mit Dir, dem ew''gen Sohne,<br/>Durch den Glauben eins sind wir,<br/>Haben teil an Deinem Tode<br/>Und an Deinem Leben hier.<br/>Eins mit Dir, Du Sohn geliebet,<br/>Durch die Gnade Teil von Dir,<br/>Mit Dir Erben unsres Vaters,<br/>Wohnung für den Geist sind wir.<br/>',NULL,46872,1);
INSERT INTO stanza VALUES('G182','2','Eins mit Dir, dem Fleischgewordnen,<br/>Mitgeboren, Mensch von Wert,<br/>Wir, die Glieder Deines Leibes,<br/>Weiln mit Dir hier auf Erd.<br/>Eins mit Dir, Du Sohn, Gesalbter,<br/>Reichst uns Kraft des Geistes dar,<br/>Mit Dir Wirken wir zusammen<br/>Tag für Tag, wie wunderbar!<br/>',NULL,46873,2);
INSERT INTO stanza VALUES('G182','3','Eins mit Dir, von Gott Verlassnem,<br/>Wir entgingen dem Gericht,<br/>Ewig sind wir tot der Sünde,<br/>Uns der Hades unterliegt.<br/>Eins mit Dir, dem Auferstandnen,<br/>Von der Todesmacht befreit,<br/>Tragen in der neuen Schöpfung<br/>Früchte der Gerechtigkeit.<br/>',NULL,46874,3);
INSERT INTO stanza VALUES('G182','4','Eins mit Dir, dem Aufgefahrnen,<br/>Teilen wir den Thron mit Dir,<br/>Haben teil an Deiner Vollmacht,<br/>Herrschen wir mit Dir schon hier.<br/>Eins mit Dir in Deinem Kommen,<br/>Dann verklärt mit Herrlichkeit,<br/>Offenbaren Deine Schönheit,<br/>Eins mit Dir in Ewigkeit.<br/>',NULL,46875,4);
INSERT INTO stanza VALUES('G183','1','Ich bin mit dem Herrn gekreuzigt,<br/>Ich durchs Kreuz Befreiung fand;<br/>Ja, in mir nun lebt und herrscht Er,<br/>Denn mit Ihm ich auferstand.<br/>',NULL,46876,1);
INSERT INTO stanza VALUES('G183','chorus','Oh! Es ist so süß mit Ihm zu sterben<br/>Aller Sünd, dem Selbst, der Welt;<br/>Oh! Es ist so süß mit Ihm zu leben,<br/>Wenn in mir Er lebt und herrscht.<br/>',NULL,46877,2);
INSERT INTO stanza VALUES('G183','2','Das Geheimnis, lang verborgen,<br/>Jetzt durch Glauben aufgezeigt:<br/>Christus in mir – dies verkünd ich!<br/>Welche Hoffnung! Herrlichkeit!<br/>',NULL,46878,3);
INSERT INTO stanza VALUES('G183','3','Die Natur birgt ein Geheimnis:<br/>Frucht bringt nur das Korn, das stirbt;<br/>Eingepfropfter wilder Ölzweig<br/>Süßres Leben sich erwirbt.<br/>',NULL,46879,4);
INSERT INTO stanza VALUES('G183','4','Heilig sein ist ein Geheimnis:<br/>Heilig ist in uns nur Er;<br/>Nun entleere uns und füll uns<br/>Ganz mit Deinem Reichtum, Herr.<br/>',NULL,46880,5);
INSERT INTO stanza VALUES('G183','5','Balsam ist''s in Schmerz und Krankheit,<br/>Wenn du stirbst der eignen Kraft,<br/>Und in Ihm das Leben findest,<br/>Das dir Gottes Kraft verschafft.<br/>',NULL,46881,6);
INSERT INTO stanza VALUES('G183','6','Für den Meister, der ans Kreuz ging,<br/>Stand zuletzt der Thron bereit;<br/>Unser Weg führt gleich dem Seinen,<br/>Nur durch Tod zur Herrlichkeit.<br/>',NULL,46882,7);
INSERT INTO stanza VALUES('G184','1','Mit Ihm begraben und auferweckt;<br/>Durch Ihn zu leben, hab ich entdeckt.<br/>Ich muss nicht kämpfen, täglich darf ruhn,<br/>In Lebens-Neuheit wandle ich nun.<br/>Herrlichkeit sei Gott!<br/>',NULL,46883,1);
INSERT INTO stanza VALUES('G184','2','Mit Ihm erweckt, dem herrlichen Herrn,<br/>Geh ich den Weg der Heiligung gern;<br/>Welch eine Wahrheit! – dies ich verkünd:<br/>In Christi Tod gibt''s Freiheit von Sünd.<br/>Herrlichkeit sei Gott!<br/>',NULL,46884,2);
INSERT INTO stanza VALUES('G184','3','Mit Christus leb ich, Er stirbt nie mehr,<br/>Ich folge Ihm, Er geht vor mir her;<br/>Er hat mich, Sündensklaven, befreit,<br/>Ich halte mich für tot allezeit.<br/>Herrlichkeit sei Gott!<br/>',NULL,46885,3);
INSERT INTO stanza VALUES('G184','4','Für Christus leb ich, geb mich nun hin,<br/>Damit ich immer meinem Gott dien;<br/>Nicht mehr Gesetz, die Gnade nun gilt,<br/>Sünde entthront, nun Christus regiert.<br/>Herrlichkeit sei Gott!<br/>',NULL,46886,4);
INSERT INTO stanza VALUES('G184','5','In Christus wachs ich, es ist jetzt Schluss<br/>Mit Dingen, der ich mich schämen muss;<br/>Ich Frucht zur Heiligung tragen will,<br/>Ewiges Leben teilen, mein Ziel.<br/>Herrlichkeit sei Gott!<br/>',NULL,46887,5);
INSERT INTO stanza VALUES('G185','1','Welche Tatsach! Mitgekreuzigt bin ich ja,<br/>Von des Fleisches Lüsten frei sogar;<br/>Fakt so herrlich, denn ich lebe mit dem Herrn<br/>Auferstehungsleben schenkt'' Er gern.<br/>',NULL,46888,1);
INSERT INTO stanza VALUES('G185','chorus','Da am Kreuz von Golgatha der Herr und ich,<br/>Gekreuzigt sind, gekreuzigt sind,<br/>Lebe ich im Auferstehungsleben jetzt,<br/>Und Wohnung in Ihm find.<br/>',NULL,46889,2);
INSERT INTO stanza VALUES('G186','1','Du zeigtest das Geheimnis mir,<br/>Wie ich am Kreuz dort starb mit Dir!<br/>Kein andrer Weg noch andre Kraft<br/>Mir Tag für Tag den Sieg verschafft.<br/>',NULL,46890,1);
INSERT INTO stanza VALUES('G186','2','Stark wirkt Dein Kreuz in meinem Sein,<br/>Scheint in mein Leben hell hinein;<br/>Glaub ich an meinen Tod mit Dir,<br/>So ist die Welt entthront in mir.<br/>',NULL,46891,2);
INSERT INTO stanza VALUES('G186','3','Seit ich mit Dir gekreuzigt bin,<br/>Frei bin von Sünd und Selbst forthin,<br/>Wie kann mich da noch ziehn die Welt?<br/>Nichtig ist sie samt ihrem Geld.<br/>',NULL,46892,3);
INSERT INTO stanza VALUES('G186','4','Ich möchte bei Dir sein so nah,<br/>Dort, Herr, am Kreuz auf Golgatha.<br/>Du kräftigst mich und lebst in mir,<br/>Ja, ineinander wohnen wir.<br/>',NULL,46893,4);
INSERT INTO stanza VALUES('G186','5','Da Du den Feind zunicht gemacht,<br/>Sein Werk und Kraft zu Fall gebracht,<br/>So überwind ich in Dir auch,<br/>Die große Kraft in mir gebrauch.<br/>',NULL,46894,5);
INSERT INTO stanza VALUES('G186','6','Doch unser Sieg hängt ab von Dir,<br/>Auf Deinem Tod am Kreuz stehn wir;<br/>Wir folgen Dir, wie Du einst gingst,<br/>So uns zum Ziel in Gott Du bringst.<br/>',NULL,46895,6);
INSERT INTO stanza VALUES('G186','7','Ich glaub an meinen Tod mit Dir,<br/>Seine Bedeutung wirkt in mir,<br/>Zeige mir Deinen Tod noch mehr,<br/>Mach mich von meinem Fleisch frei, Herr.<br/>',NULL,46896,7);
INSERT INTO stanza VALUES('G186','8','Ich möchte siegen so wie Du,<br/>Herrschen mit Dir bald immerzu,<br/>Wenn wir das Kreuz stets tragen froh,<br/>Ist Deine Herrlichkeit uns Lohn.<br/>',NULL,46897,8);
INSERT INTO stanza VALUES('G187','1','Welch ein Sieg! Welch Triumphieren!<br/>Gott Selbst zog das Menschsein an;<br/>Menschliche Natur teilhabend,<br/>Er erfüllte Seinen Plan.<br/>Durch den Tod zertrat Er Satan,<br/>Sohn des Menschen auferstand!<br/>',NULL,46898,1);
INSERT INTO stanza VALUES('G187','2','Durch die Tugenden des Menschen<br/>Jesus hielt die Schlange fest;<br/>Stand als Mensch dem Feind entgegen,<br/>So bestand Er jeden Test.<br/>Heute kann ich zu mir nehmen<br/>Seine Tugenden im Geist.<br/>',NULL,46899,2);
INSERT INTO stanza VALUES('G187','3','Ja, im Geist von Jesus Christus<br/>Ist die feine Menschlichkeit;<br/>Auch die Tugenden des Menschen<br/>Sind darin nun allezeit.<br/>Welch Versorgung steht im Geist für<br/>Alle Menschen stets bereit!<br/>',NULL,46900,3);
INSERT INTO stanza VALUES('G187','4','Wie geheimnisvoll, doch wirklich!<br/>Solch ein Mensch lebt nun in mir,<br/>Macht in meinem Herzen Wohnung<br/>Und mein Leben ist Er hier.<br/>Halleluja! Halleluja!<br/>Ewiglich ich jubilier.<br/>',NULL,46901,4);
INSERT INTO stanza VALUES('G187','5','Oh, welch Wunder! Oh, wie herrlich!<br/>Gott aus Menschen strahlt heraus.<br/>Wir, die Glieder Seines Leibes,<br/>Seine Menschlichkeit stelln aus.<br/>Heute teilen wir sein Menschsein,<br/>Und so bauen wir Sein Haus.<br/>',NULL,46902,5);
INSERT INTO stanza VALUES('G188','1','Christus  sahen wir – ist Wirklichkeit:<br/>Doch nur dies zu sehen, reicht nicht weit:<br/>Wir wolln nun erfahren allezeit,<br/>Was Er für uns ist.<br/>Im Gebet schaun wir Sein Angesicht,<br/>Ihn im Wort als Gnade sehn und Licht,<br/>Doch im Alltag, in all unsrer Pflicht,<br/>Was ist Er für uns?<br/>',NULL,46903,1);
INSERT INTO stanza VALUES('G188','chorus','Halleluja! Durch Sein Licht sehn wir,<br/>Reich und wirklich unser Herr ist hier,<br/>Stets zu Ihm uns wenden wollen wir,<br/>Alle Zeit, an jedem Tag,<br/>Alles und auf jede Art nunmehr –<br/>Wenden wir uns hin zur Wirklichkeit!<br/>Allgemeines überwinden weit!<br/>Wenn wir Ihn anwenden, sind befreit,<br/>Alles ist Er für uns.<br/>',NULL,46904,2);
INSERT INTO stanza VALUES('G188','2','Täglich gibt es viel Gelegenheit,<br/>Alles unser Vater stellt bereit:<br/>Es dient dir zum Besten allezeit,<br/>Drum jag Christus nach!<br/>Er ist unser Inhalt, Wirklichkeit,<br/>Will aus uns nun scheinen allezeit:<br/>Öffnen wir Ihm unser Herz ganz weit,<br/>Hat Er einen Weg.<br/>',NULL,46905,3);
INSERT INTO stanza VALUES('G188','chorus','Halleluja! Ja, in unsrem Leib<br/>Tragen wir den Tod des Herrn allzeit:<br/>Und Sein Leben zeigt sich weit und breit,<br/>Wenn der äußre Mensch zerbrochen ist,<br/>Der innre Mensch hell leuchtet, so dass –<br/>Er aus Ton-Gefäßen strahlt allzeit,<br/>Welch ein teurer Schatz der Wirklichkeit!<br/>So wird Gottes Licht der Herrlichkeit<br/>Sichtbar sein durch uns.<br/>',NULL,46906,4);
INSERT INTO stanza VALUES('G188','chorus','Nicht nur Lehre und Theologie,<br/>Doch die Wirklichkeit in Christus sieh;<br/>Licht und Leben stets aus Ihm bezieh,<br/>Alles ist Er für uns!<br/>',NULL,46907,5);
INSERT INTO stanza VALUES('G189','1','Gekreuzigt ist mein alter Mensch mit Ihm<br/>Verdorben ist er, unbrauchbar für Ihn;<br/>Begraben ist sein Schlangenwesen auch,<br/>Ich mach von diesem Tatbestand Gebrauch,<br/>Halt daran fest.<br/>',NULL,46908,1);
INSERT INTO stanza VALUES('G189','2','Eine Person in meinen Geist zog ein,<br/>Geborenen als ein Kindlein, schwach und klein;<br/>Die Milch des Wortes Wachstum Ihr verschafft<br/>Stärkt innerlich mit Überwinderkraft,<br/>Gewinnt mein Herz.<br/>',NULL,46909,2);
INSERT INTO stanza VALUES('G189','3','Der Herr nimmt als Person mein Herz nun ein,<br/>Den Vorrang will in jedem Teil allein.<br/>Der alte Herr gibt ständig Widerstand,<br/>O Herr, im Willen und Gefühl, Verstand<br/>Dich breite aus.<br/>',NULL,46910,3);
INSERT INTO stanza VALUES('G189','4','Im Geist sind wir vermengt und eins mit Dir,<br/>Die Menschlichkeit und Göttlichkeit sind hier;<br/>Doch Du brauchst uns auch, Herr, als ein Gefäß,<br/>Das Deiner herrlichen Person gemäß<br/>Gott Selbst ausstrahlt.<br/>',NULL,46911,4);
INSERT INTO stanza VALUES('G189','5','Drum geb ich Dir mein ganzes Herz heut hin,<br/>Mach Deine Wohnung voll und ganz darin,<br/>Bis Du in uns, Herr, die Person dann bist,<br/>Die Krönung Deiner Wied''rerlangung ist<br/>Der neue Mensch.<br/>',NULL,46912,5);
INSERT INTO stanza VALUES('G190','1','Herr, als den Vater niemand kannt,<br/>Kam Er durch Dich zur Erde hier,<br/>Damit wir, die unwissend warn,<br/>Den Vater kennenlern''n in Dir.<br/>',NULL,46913,1);
INSERT INTO stanza VALUES('G190','2','Als Du, o Herr, auf Erden warst,<br/>Wer nahm in Dir den Vater wahr?<br/>Ein Schleier trennte sie von Dir;<br/>Sie sahen Dich, doch warn nicht klar.<br/>',NULL,46914,2);
INSERT INTO stanza VALUES('G190','3','Nun als der Geist gekommen bist,<br/>So wie der Vater kam in Dir;<br/>Den Vater kennen wir durch Dich,<br/>Dich durch den Geist nun kennen wir.<br/>',NULL,46915,3);
INSERT INTO stanza VALUES('G190','4','Nicht mehr mit Fleisch bekleidet bist –<br/>Damals erlebtest Du viel Leid;<br/>Doch jetzt als Geist versorgst Du uns,<br/>Nimmst unsre Herzen völlig ein.<br/>',NULL,46916,4);
INSERT INTO stanza VALUES('G190','5','Ewiger Vater hießest Du,<br/>Jetzt bist Du, Herr, der Heil''ge Geist;<br/>Der Geist ist Deine andre Form,<br/>So Du in uns zu wohnen weißt.<br/>',NULL,46917,5);
INSERT INTO stanza VALUES('G190','6','Dich als den Geist zu kennen, Herr,<br/>Lässt uns Dein Leben reich erfahrn;<br/>Dein Wesen, Deine Herrlichkeit,<br/>Wolln wir in uns als Schatz bewahrn.<br/>',NULL,46918,6);
INSERT INTO stanza VALUES('G190','7','Wir loben Deinen Namen, Herr,<br/>Niemand so kostbar ist wie Du;<br/>Seit wir Dich als den Geist erfahrn,<br/>Lieblicher wirst Du immerzu.<br/>',NULL,46919,7);
INSERT INTO stanza VALUES('G191','1','Du wusstest, Herr, als noch im Fleisch,<br/>Dass ich Dich kenn nur äußerlich;<br/>Dann kamst Du doch als Geist zu mir,<br/>In meinem Geist jetzt kenn ich Dich.<br/>',NULL,46920,1);
INSERT INTO stanza VALUES('G191','2','Im Fleisch Erlöser mein bist Du;<br/>Als Geist, der Tröster jetzt für mich.<br/>Das Äußerliche ist nicht mehr,<br/>Dafür die Einheit innerlich.<br/>',NULL,46921,2);
INSERT INTO stanza VALUES('G191','3','Und weil Du jetzt der Geist bist, Herr,<br/>Dich unaufhörlich offenbarst,<br/>In meinem Geist als Wirklichkeit<br/>Erkenn ich Deine Gegenwart.<br/>',NULL,46922,3);
INSERT INTO stanza VALUES('G191','4','Obwohl die Jünger seinerzeit<br/>Dich sahen, wandelten mit Dir,<br/>Noch tiefer kenne ich als sie<br/>Dein Leben, denn Du lebst in mir.<br/>',NULL,46923,4);
INSERT INTO stanza VALUES('G191','5','Und weil Dein Geist in mir nun wohnt,<br/>Wie wirklich, Herr, bist Du für mich!<br/>Ich spür Dich nicht mit meiner Hand,<br/>Dennoch so glühend lieb ich Dich.<br/>',NULL,46924,5);
INSERT INTO stanza VALUES('G191','6','Dein Geist versorgt mich innerlich<br/>Mit Dir, Herr, als Gerechtigkeit,<br/>Als Heiligkeit, Erlösung auch,<br/>Als Weisheit und als Fruchtbarkeit.<br/>',NULL,46925,6);
INSERT INTO stanza VALUES('G191','7','Mich nährt Dein Geist in meinem Geist,<br/>Vereint mich innerlich mit Sich,<br/>So bin ich allezeit ich selbst<br/>Und auch beständig bin ich Dich.<br/>',NULL,46926,7);
INSERT INTO stanza VALUES('G192','1','Herr, dort am Kreuz auf Golgatha<br/>Kamst Du in Deinem Werk zur Ruh;<br/>Doch heute wirkst Du immer noch,<br/>Nur eine andre Form hast Du.<br/>',NULL,46927,1);
INSERT INTO stanza VALUES('G192','2','Noch immer zeigst Du Retterkraft,<br/>Noch immer sprichst, erleuchtest, führst;<br/>Du als der Geist fließt wie ein Strom,<br/>Menschen mit Lebensflut berührst.<br/>',NULL,46928,2);
INSERT INTO stanza VALUES('G192','3','Durch Deinen Geist wirkst Du mit Kraft,<br/>Durch Ihn erfüllst Du Deinen Plan;<br/>Noch immer wirkst Du Wolln und Tun,<br/>Tröstest, befreist und gehst voran.<br/>',NULL,46929,3);
INSERT INTO stanza VALUES('G192','4','Du und der Geist sind völlig eins,<br/>Sein Kommen auch Dein Kommen ist;<br/>Er wohnt in uns, mit Ihm auch Du,<br/>Weil Du zum Geist geworden bist.<br/>',NULL,46930,4);
INSERT INTO stanza VALUES('G192','5','Er führt in meinem Herzen aus,<br/>Was Du Dir wünschst und Dir gebührt;<br/>So hast auch Du auf dieser Erd<br/>Den Wunsch des Vaters ausgeführt.<br/>',NULL,46931,5);
INSERT INTO stanza VALUES('G192','6','Kennen den Geist, heißt kennen Dich,<br/>Ihm zu gehorchen, Dich einschließt;<br/>Wenn nun der Geist uns reich erfüllt,<br/>Bist Du es Selbst, der in uns fließt.<br/>',NULL,46932,6);
INSERT INTO stanza VALUES('G192','7','Bist nicht im Himmel, fern von uns,<br/>Du ließest uns nicht hier allein;<br/>Noch immer auf der Erde bist:<br/>In unsre Herzen zogst Du ein.<br/>',NULL,46933,7);
INSERT INTO stanza VALUES('G193','1','Wir wolln singen dem Herrn mit dem Geist,<br/>Wir wolln singen dem Herrn von tief drin,<br/>Singen laut Halleluja zu Jesus,<br/>Und in Einheit vermengt sind mit Ihm.<br/>',NULL,46934,1);
INSERT INTO stanza VALUES('G193','2','Religion nahm uns ein viele Jahre,<br/>Wir warn jahrelang nur im Verstand,<br/>Viele Jahre in unsren Gefühlen,<br/>Immer suchend, doch gar nichts sich fand.<br/>',NULL,46935,2);
INSERT INTO stanza VALUES('G193','3','Nun wir lernen zum Geist uns zu wenden,<br/>Christus nehmen als Leben allzeit;<br/>Lernen uns zu ernähren von Jesus,<br/>Das von Kämpfen und Mühen befreit.<br/>',NULL,46936,3);
INSERT INTO stanza VALUES('G193','4','Halleluja für Leben im Geist,<br/>Halleluja für Neuheit tief drin.<br/>Vom Verstand wenden wir uns zum Geist,<br/>Und genießen den Reichtum von Ihm.<br/>',NULL,46937,4);
INSERT INTO stanza VALUES('G194','1','Herr Jesus, Du bist nun der Geist,<br/>Der Leben gibt und uns entfacht,<br/>Mit Deinem Reichtum füllt Er uns,<br/>Wie göttlich und wie wohlbedacht!<br/>',NULL,46938,1);
INSERT INTO stanza VALUES('G194','2','Herr Jesus, Du bist nun der Geist,<br/>Der uns mit Deiner Kraft befreit;<br/>Und Dein Gesetz des Lebens lenkt<br/>Uns innerlich nun allezeit.<br/>',NULL,46939,2);
INSERT INTO stanza VALUES('G194','3','Herr Jesus, Du bist nun der Geist,<br/>Er wandelt um, uns ganz durchtränkt,<br/>Uns gleichgestaltet Deinem Bild,<br/>Das Herz erleuchtet unumschränkt.<br/>',NULL,46940,3);
INSERT INTO stanza VALUES('G194','4','Herr Jesus, Du bist nun der Geist,<br/>Der Wohnung macht in meinem Geist;<br/>Mit meinem Geist vermengt Er Sich,<br/>So werden sie zu einem Geist.<br/>',NULL,46941,4);
INSERT INTO stanza VALUES('G194','5','Den Geist zu üben, lehre mich,<br/>Um Dich, o Herr, zu kontaktiern,<br/>Zu leben im vermengten Geist,<br/>In Deinem Leben zu regiern.<br/>',NULL,46942,5);
INSERT INTO stanza VALUES('G195','1','Jesus ist der Geist des Lebens,<br/>Unsre Wirklichkeit;<br/>Welch Genuss, Ihn anzurufen<br/>In all Einfachheit!<br/>',NULL,46943,1);
INSERT INTO stanza VALUES('G195','chorus','Jesus ist der Geist des Lebens,<br/>Der erretten kann;<br/>Er ist reich für alle Menschen,<br/>Rufe Ihn doch an!<br/>',NULL,46944,2);
INSERT INTO stanza VALUES('G195','2','In uns lebt nun Jesus Christus,<br/>Macht uns völlig frei;<br/>Schmeck und sieh, denn Er ist gnädig,<br/>Steht uns immer bei.<br/>',NULL,46945,3);
INSERT INTO stanza VALUES('G195','3','Jesus ist der Geist des Lebens,<br/>Und Er ist das Wort;<br/>Ihn berühr durch Beten-Lesen,<br/>Dies belebt sofort.<br/>',NULL,46946,4);
INSERT INTO stanza VALUES('G195','4','Jesus ist der Geist des Lebens,<br/>Welcher durch uns fließt;<br/>Die Gemeinschaft Seines Geistes<br/>Bringt uns Einheit süß.<br/>',NULL,46947,5);
INSERT INTO stanza VALUES('G195','5','Jesus ist der Geist des Lebens,<br/>Unser Fest so reich;<br/>Wenn als Leib wir Ihn genießen,<br/>Fließt der Lobpreis frei.<br/>',NULL,46948,6);
INSERT INTO stanza VALUES('G196','1','Der Lebensbaum mit Früchten süß<br/>Mit Gottes Leben speist.<br/>Verhungert einst, nun ess ich froh,<br/>War tot, nun lebt mein Geist.<br/>',NULL,46949,1);
INSERT INTO stanza VALUES('G196','2','Gott Selber brachte mich zum Baum,<br/>Zu Christus, der mich speist;<br/>Wie kostbar ist der Baum für mich,<br/>Seit ich Ihn ess im Geist!<br/>',NULL,46950,2);
INSERT INTO stanza VALUES('G196','3','Der Herr als Speise mich versorgt,<br/>Belebt mich, nichts mehr fehlt;<br/>Für mich ist Er allein Genuss,<br/>Nur Er zufriedenstellt.<br/>',NULL,46951,3);
INSERT INTO stanza VALUES('G196','4','Ich esse frei von diesem Baum,<br/>Empfang Sein Leben gern;<br/>Denn Christus essen ist der Weg,<br/>So leb ich durch den Herrn.<br/>',NULL,46952,4);
INSERT INTO stanza VALUES('G197','1','Christus – die Zentralität<br/>Und die Universalität;<br/>Gottes Wohlgefalln ist Er,<br/>Heut und in all Ewigkeit.<br/>',NULL,46953,1);
INSERT INTO stanza VALUES('G197','2','Gottes Fülle wohnt in Ihm,<br/>Gott in Ihm verkörpert ist;<br/>Seiner Gottheit kommt nichts gleich,<br/>Er den ersten Platz genießt.<br/>',NULL,46954,2);
INSERT INTO stanza VALUES('G197','3','Christus muss nach Gottes Plan<br/>Alles und in allem sein;<br/>Himmelsvielfalt, Erdenpracht<br/>Hat erschaffen Er allein.<br/>',NULL,46955,3);
INSERT INTO stanza VALUES('G197','4','Alle Schöpfung ist für Ihn,<br/>Alles nur durch Ihn entstand;<br/>Alles hier besteht durch Ihn,<br/>Er ist Nabe und der Rand.<br/>',NULL,46956,4);
INSERT INTO stanza VALUES('G197','5','Christus die Erlösung ist,<br/>Alles ist versöhnt durch Ihn;<br/>Er hat durch Sein teures Blut<br/>Frieden uns mit Gott verliehn.<br/>',NULL,46957,5);
INSERT INTO stanza VALUES('G197','6','Er der große Anfang ist,<br/>Von den Toten erstgeborn;<br/>Haupt von der Gemeinde – Er,<br/>Leben, Inhalt und Person.<br/>',NULL,46958,6);
INSERT INTO stanza VALUES('G197','7','Ihm in Gottes Reich gehört<br/>Als dem König alle Macht;<br/>Himmel und die Erde wird<br/>Er regiern in Seiner Pracht.<br/>',NULL,46959,7);
INSERT INTO stanza VALUES('G197','8','Auf der neuen Erde wird<br/>Er das Zentrum allezeit,<br/>Für die Gottheit, für den Mensch;<br/>Hell strahlt Er in Ewigkeit.<br/>',NULL,46960,8);
INSERT INTO stanza VALUES('G197','9','Gottes Plan in allem ist,<br/>Dass Sein Christus Vorrang hat;<br/>Diesen Christus wollen wir<br/>Jetzt erfahren in der Tat.<br/>',NULL,46961,9);
INSERT INTO stanza VALUES('G198','1','Christus alleine ist die Wirklichkeit<br/>Von Gott und Mensch und allem um uns her;<br/>Ohne Ihn findet niemand je zu Gott,<br/>Ohne Ihn ist der Mensch und alles leer.<br/>',NULL,46962,1);
INSERT INTO stanza VALUES('G198','2','Bilder und Zeichen aus der alten Zeit,<br/>Was wir auch brauchen, sei es groß, sei''s klein,<br/>Weisen als Schatten stets auf Christus hin,<br/>Täglich muss Christus alles für uns sein.<br/>',NULL,46963,2);
INSERT INTO stanza VALUES('G198','3','Alles ist Nichtigkeit und inhaltsleer,<br/>Christus ist Wirklichkeit, gibt allem Sinn;<br/>Würde die Welt und alles uns gehörn,<br/>Spürten wir dennoch Leere ohne Ihn.<br/>',NULL,46964,3);
INSERT INTO stanza VALUES('G198','4','Christus ist unser wahrer Gott und Herr.<br/>Christus ist unser Leben, unser Licht;<br/>Christus ist unsre wahre Speis und Trank,<br/>Unsre Bekleidung und die wahre Macht.<br/>',NULL,46965,4);
INSERT INTO stanza VALUES('G198','5','Christus alleine ist die Wirklichkeit<br/>All unsrer Lehre und Theologie;<br/>Ohne Ihn ist die Bibelkenntnis nur<br/>Lebloser Buchstabe und Theorie.<br/>',NULL,46966,5);
INSERT INTO stanza VALUES('G198','6','Er ist die Wirklichkeit von Zeit und Raum,<br/>Von jeder äußeren Begebenheit;<br/>Die wahre Wirklichkeit ist Er allein<br/>Durch alle Zeiten bis in Ewigkeit.<br/>',NULL,46967,6);
INSERT INTO stanza VALUES('G199','1','Gnade in ihrem höchsten Sinne ist:<br/>Gott in dem Sohn zu unserem Genuss;<br/>Gnade ist nicht nur, was Gott tut und gibt,<br/>Sondern Gott Selbst, der unser herrlich Los.<br/>',NULL,46968,1);
INSERT INTO stanza VALUES('G199','2','Gott wurde Fleisch, sodass wir selbst den Herrn<br/>Aufnehmen mögen, Ihn erfahren gar;<br/>Dies ist die Gnade, die uns Gott gewährt,<br/>Die kommt durch Christus, Christus ist sogar.<br/>',NULL,46969,2);
INSERT INTO stanza VALUES('G199','3','Paulus hielt alles für Verlust und Dreck,<br/>Nur Gott in Christus sah als Gnade an;<br/>Durch diese Gnade – den erfahrnen Herrn –<br/>Lief er den Lauf, den Siegespreis gewann.<br/>',NULL,46970,3);
INSERT INTO stanza VALUES('G199','4','Es ist die Gnade – Christus, unsre Kraft –<br/>Mit der Er allumfassend uns erfüllt;<br/>Es ist die Gnade, die uns stärkt im Geist,<br/>Dort wirkend stets, vollbringt es Gottes Will.<br/>',NULL,46971,4);
INSERT INTO stanza VALUES('G199','5','Dies Gnade, Christus Selber, müssen wir<br/>Kennen, erfahren, wie es sich gebührt;<br/>Herr, lass uns diese Gnade leben mehr,<br/>Sei als die Gnade stets noch mehr verspürt.<br/>',NULL,46972,5);
INSERT INTO stanza VALUES('G200','1','Oh, welch ein Leben! Welch ein Fried!<br/>Denn Jesus Christus lebt in mir.<br/>Mit Ihm gekreuzigt wurde ich,<br/>Ja, diese Tatsach schenkt Er mir.<br/>Nun lebe nicht mehr länger ich,<br/>Doch Christus Selbst lebt jetzt in mir.<br/>',NULL,46973,1);
INSERT INTO stanza VALUES('G200','2','Oh, welche Freude! Welche Ruh!<br/>Der Herr in mir Gestalt gewinnt.<br/>Seine Natur, Sein Leben reich<br/>Mein ganzes Wesen tief durchdringt.<br/>Alles von Ihm ist Alles mir,<br/>Und was ich bin ein Ende find''t.<br/>',NULL,46974,2);
INSERT INTO stanza VALUES('G200','3','Welch ein Gedanke! Welch ein Ruhm!<br/>Er will in mir vergrößert sein.<br/>Ich werd in nichts zuschand gemacht,<br/>In allem nehm ich Ihn allein.<br/>In Leid und Segen, Leben, Tod,<br/>Möcht ich ein Zeugnis Christi sein.<br/>',NULL,46975,3);
INSERT INTO stanza VALUES('G200','4','Oh, welch Belohnung! Welch Gewinn!<br/>Mein Ziel ist Christus allezeit.<br/>Nichts schätz ich mehr, ersehne mehr<br/>Als Seine Allumfassendheit.<br/>All meine Hoffnung, Krone, Ehr<br/>Ist Christi Unvergleichlichkeit.<br/>(Die letzten beiden zeilen jeder Strophe wiederholen.)<br/>',NULL,46976,4);
INSERT INTO stanza VALUES('G201','1','Oh, welche Stärke! Welche Kraft!<br/>Die Christus einst hat auferweckt.<br/>Zur Rechten Gottes sitzt das Haupt,<br/>Uns über alles hoch erstreckt.<br/>All diese Kraft gilt der Gemeind,<br/>Dass sie am Feind den Bann vollstreckt.<br/>',NULL,46977,1);
INSERT INTO stanza VALUES('G201','2','Oh, welche Tatsach! Welch ein Glück!<br/>Dass ich ein Glied an Christus bin.<br/>Mit allen Heiligen vermengt<br/>Im neuen Menschen, welch Gewinn!<br/>Eins mit dem aufgefahrnen Haupt,<br/>Wir die Gemeinde sind für Ihn.<br/>',NULL,46978,2);
INSERT INTO stanza VALUES('G201','3','Oh, welche Länge! Welche Breit!<br/>Welch Höhe, Tiefe unfassbar!<br/>Christus, der Herr, ist unbegrenzt,<br/>Immens, weit, unermesslich gar.<br/>Was Christus ist und was Er hat,<br/>Ist unser Leben unsagbar.<br/>(Die letzten beiden Zeilen jeder Strophe wiederholen.)<br/>',NULL,46979,3);
INSERT INTO stanza VALUES('G202','1','Du, herrlicher Christus, bist mein,<br/>Du bist wahrlich göttlicher Schein;<br/>Gott unbegrenzt in der Ewigkeit,<br/>Und doch als Mensch begrenzt in Zeit.<br/>',NULL,46980,1);
INSERT INTO stanza VALUES('G202','chorus','Oh! Christus, Du Gottes Ausdruck groß!<br/>Unerschöpflich, lieblich und fein!<br/>Du, Gott vermengt mit Menschlichkeit,<br/>Lebst in mir, willst alles mir sein.<br/>',NULL,46981,2);
INSERT INTO stanza VALUES('G202','2','Es wohnt Gottes Fülle in Dir;<br/>Gottes Herrlichkeit tust Du kund hier;<br/>Erlösung hast im Fleisch vollbracht,<br/>Als Geist hast Du uns eins gemacht.<br/>',NULL,46982,3);
INSERT INTO stanza VALUES('G202','3','Die Fülle des Vaters ist Dein,<br/>Und was Du im Geist bist, ist mein;<br/>Durch Gottes Geist der Wirklichkeit<br/>Erfahr ich Dich nun allezeit.<br/>',NULL,46983,4);
INSERT INTO stanza VALUES('G202','4','Der Geist ew''gen Lebens bringt Dich<br/>Durch Dein Wort so herrlich in mich.<br/>Dein Wort als Geist frei nehm ich an,<br/>Dein Leben ich dabei empfang.<br/>',NULL,46984,5);
INSERT INTO stanza VALUES('G202','5','Schau ich Dich im Geist an, o Herr,<br/>Spiegle Deine Herrlichkeit mehr,<br/>Mich wandelst Du in Dein Bild um,<br/>Zum Ausdruck bring ich Dich rundum.<br/>',NULL,46985,6);
INSERT INTO stanza VALUES('G202','6','Nur so heiligst Du mich in Dir,<br/>Teilst Du Deinen Sieg so mit mir;<br/>Wir werden nur so geistlich sein,<br/>Gefüllt mit Herrlichkeit allein.<br/>',NULL,46986,7);
INSERT INTO stanza VALUES('G202','7','Dein Geist wird durchsättigen mich,<br/>Jeden Teil durchdringt Gott mit Sich;<br/>Vom alten Menschen ganz befreit,<br/>Sind wir für Gottes Bau bereit.<br/>',NULL,46987,8);
INSERT INTO stanza VALUES('G203','1','Ein Mensch in der Herrlichkeit,<br/>Sein Leben ist für mich.<br/>So heilig und rein ist Er,<br/>Stets thront königlich.<br/>So weise und liebend,<br/>Wie einfühlsam dabei!<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>',NULL,46988,1);
INSERT INTO stanza VALUES('G203','2','Ein Mensch in der Herrlichkeit,<br/>Sein Leben ist für mich.<br/>Besiegt hat Er Satan,<br/>Ist frei ewiglich.<br/>Im Leben nun herrscht Er,<br/>So königlich dabei!<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>',NULL,46989,2);
INSERT INTO stanza VALUES('G203','3','Ein Mensch in der Herrlichkeit,<br/>Sein Leben ist für mich.<br/>In Ihm keine Krankheit,<br/>Noch Schwachheit birgt sich.<br/>So stark und so kräftig,<br/>Kein Druck bricht Ihn entzwei!<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>Sein Leben in der Herrlichkeit<br/>Mein Leben sei.<br/>',NULL,46990,3);
INSERT INTO stanza VALUES('G203','4','Ein Mensch in der Herrlichkeit,<br/>Sein Leben ist für mich.<br/>Sein Friede währt immer,<br/>Geduld schwindet nicht!<br/>Er strahlt voller Freude,<br/>Zu sehn ist Er bestrebt:<br/>Sein Leben in der Herrlichkeit<br/>Durch mich ausgelebt.<br/>Sein Leben in der Herrlichkeit<br/>Durch mich ausgelebt.<br/>',NULL,46991,4);
INSERT INTO stanza VALUES('G204','1','Einst fern von Gott, in Sünde tot,<br/>Kein Licht mein Herz sah hier;<br/>In Gottes Wort doch fand ich Licht,<br/>Jetzt lebt Christus in mir.<br/>',NULL,46992,1);
INSERT INTO stanza VALUES('G204','chorus','Christus lebt nun in mir,<br/>Christus lebt nun in mir,<br/>Welch eine Errettung ist''s!<br/>Jetzt lebt Christus in mir.<br/>',NULL,46993,2);
INSERT INTO stanza VALUES('G204','2','Wie Sonnenlicht zum Blühen bringt<br/>Die schönsten Blumen hier,<br/>So Leben, Licht und Liebe kommt<br/>Vom Herrn, der lebt in mir.<br/>',NULL,46994,3);
INSERT INTO stanza VALUES('G204','3','Die Blume lebt im Samen drin,<br/>Der Baum, der lebt im Kern.<br/>So wohnt in mir, wie wunderbar,<br/>Der reiche Geist des Herrn.<br/>',NULL,46995,4);
INSERT INTO stanza VALUES('G204','4','Mit Sehnen wird mein Herz erfüllt,<br/>Ich möcht Ihm gleich sein hier;<br/>In mir nur ein Gedanke wohnt:<br/>Jetzt lebt Christus in mir.<br/>',NULL,46996,5);
INSERT INTO stanza VALUES('G205','1','Siehe, in Eden fließt ein Strom<br/>Und auch ein Baum den Garten ziert;<br/>Wer sie genießt und isst und trinkt,<br/>Ewiglich leben wird.<br/>',NULL,46997,1);
INSERT INTO stanza VALUES('G205','chorus','Gott ist in Christus, alles für mich,<br/>Gott als der Geist mich sättigt stets treu;<br/>Wenn ich im Geist mich nähre von Ihm,<br/>Füllt mich Sein Leben neu.<br/>',NULL,46998,2);
INSERT INTO stanza VALUES('G205','2','Dieser Baum zeigt auf Christus hin,<br/>Mit Gottes Leben nährt Er mich;<br/>So Gottes Reichtum ich genieß,<br/>Er sättigt mich mit Sich.<br/>',NULL,46999,3);
INSERT INTO stanza VALUES('G205','3','Und dieser Strom zeigt Gottes Geist,<br/>Der in den Geist des Menschen fließt,<br/>Mit Gottes Reichtum ihn erfüllt,<br/>Damit er heilig ist.<br/>',NULL,47000,4);
INSERT INTO stanza VALUES('G205','4','Christus, der Herr, mein Leben ist<br/>Denn als der Geist lebt Er in mir;<br/>Ich werd mit Gott nun ganz vermengt,<br/>Strahle Sein Bild aus hier.<br/>',NULL,47001,5);
INSERT INTO stanza VALUES('G205','5','Herrlicher Christus, Dir ich sing,<br/>Ich höre gern auf Deinen Geist,<br/>Und Deine Herrlichkeit erstrahln,<br/>Gnade Du mir erweist.<br/>',NULL,47002,6);
INSERT INTO stanza VALUES('G206','1','Gottes Wort zeigt klar, oh, wie wunderbar,<br/>Gott den Menschen schuf in Seinem Bild.<br/>Ihm der Ausdruck sein, herrschen soll allein,<br/>So wird Gottes Herzenswunsch gestillt.<br/>Sein Bild, Sein Bild,<br/>Gott den Menschen schuf in Seinem Bild.<br/>Sein Bild, Sein Bild,<br/>So wird Gottes Herzenswunsch gestillt.<br/>',NULL,47003,1);
INSERT INTO stanza VALUES('G206','2','Kein Gesetz gab Gott, eins nur Er gebot:<br/>„Jeder Baum dient dir als Speise hier.“<br/>Doch ein Baum, sagt Gott, bringt dich in den Tod.<br/>Frucht der Kenntnis essen schadet dir.<br/>Kenntnis, Kenntnis,<br/>Frucht der Kenntnis essen schadet dir.<br/>Kenntnis, Kenntnis,<br/>Frucht der Kenntnis essen schadet dir.<br/>',NULL,47004,2);
INSERT INTO stanza VALUES('G206','3','Gottes Garten seht, in der Mitte steht<br/>Schön der Baum des Lebens – er zeigt Gott.<br/>Doch der Feind sich rührt und Erkenntnis schürt,<br/>Totes Wissen er dem Menschen bot.<br/>Fiel dann, fiel dann,<br/>Ja, der Mensch ist jetzt gefallen sehr.<br/>Fiel dann, fiel dann,<br/>Wer stellt diesen Menschen wieder her?<br/>',NULL,47005,3);
INSERT INTO stanza VALUES('G206','4','Jesus Christus kam als der Lebensbaum,<br/>Gottes Forderung erfüllt hat Er.<br/>Er erlöste treu, und gebar uns neu,<br/>Und zur Speise wurde uns der Herr.<br/>Jesus, Jesus,<br/>Er ist wahre Speise, wahrer Trank.<br/>Jesus, Jesus,<br/>Unsren Hunger stillt Er, Ihm sei Dank.<br/>',NULL,47006,4);
INSERT INTO stanza VALUES('G206','5','Jesus lag es fern, den Verstand zu nährn,<br/>Die Erkenntnis stärkt die Ich-Natur.<br/>Nicht analysier, iss Ihn und probier,<br/>Ihn studiere nicht, genieß Ihn nur.<br/>Nimm Ihn, nimm Ihn<br/>Er stellt dich zufrieden, alles hat.<br/>Nimm Ihn, nimm Ihn<br/>Jesus als der Lebensbaum macht satt.<br/>',NULL,47007,5);
INSERT INTO stanza VALUES('G206','6','Essen wir den Herrn, schenkt Er Wachstum gern,<br/>Leben treu bringt Frucht hervor, drum esst!<br/>Seht, Gott hat ein Ziel: Christus geben will<br/>Nicht als Religion, doch als ein Fest!<br/>Iss Ihn, iss Ihn,<br/>Christi Leben sättigt ganz und gar.<br/>Iss Ihn, iss Ihn,<br/>Wer Ihn isst, der lebt durch Ihn fürwahr.<br/>',NULL,47008,6);
INSERT INTO stanza VALUES('G206','7','Durch das Essen wir leben Christus hier,<br/>Sehn wir zu, dass es nicht fehlt daran!<br/>Ihr Gemeinden esst, dies sie wachsen lässt –<br/>Essen bringt zurück den Bräutigam.<br/>Essen, essen,<br/>Sehn wir zu, dass es nicht fehlt daran!<br/>Essen, essen,<br/>Essen bringt zurück den Bräutigam.<br/>',NULL,47009,7);
INSERT INTO stanza VALUES('G207','1','Gott gab den Sohn, dass Er uns sei<br/>Der Baum des Lebens, reich und frei,<br/>Dass jeder schmeckt und sieht dabei:<br/>',NULL,47010,1);
INSERT INTO stanza VALUES('G207','chorus','Ja, Gott ist gut zur Speis!<br/>Ja, Gott ist gut zur Speis!<br/>Ja, Gott ist gut zur Speis!<br/>Wir schmeckten und bezeugen nun:<br/>Ja, Gott ist gut zur Speis!<br/>',NULL,47011,2);
INSERT INTO stanza VALUES('G207','2','Ein Festmahl ist''s, wir essen Gott –<br/>Wir leben nun durch Gottes Brot,<br/>Da Gott Sich Selbst als Fest anbot,<br/>',NULL,47012,3);
INSERT INTO stanza VALUES('G207','chorus','Ja, Gott ist unser Fest.<br/>Ja, Gott ist unser Fest!<br/>Ja, Gott ist unser Fest!<br/>Durch Jesus Christus leben wir.<br/>Ja, Gott ist unser Fest!<br/>',NULL,47013,4);
INSERT INTO stanza VALUES('G207','3','Als Speise Sich der Herr erklärt,<br/>Er ist das Brot, das uns ernährt,<br/>Sein Leben sättigt, sich bewährt,<br/>',NULL,47014,5);
INSERT INTO stanza VALUES('G207','chorus','Iss Christus jeden Tag.<br/>Iss Christus jeden Tag!<br/>Iss Christus jeden Tag!<br/>Sein Leben sättigt und ernährt,<br/>Iss Christus jeden Tag!<br/>',NULL,47015,6);
INSERT INTO stanza VALUES('G207','4','Oh, welch Genuss ist dieses Fest!<br/>Für alle so verfügbar jetzt,<br/>Da Gott gern jeden kommen lässt,<br/>',NULL,47016,7);
INSERT INTO stanza VALUES('G207','chorus','Ja, komm und iss umsonst.<br/>Ja, komm und iss umsonst!<br/>Ja, komm und iss umsonst!<br/>Da Gott gern jeden kommen lässt,<br/>Ja, komm und iss umsonst!<br/>',NULL,47017,8);
INSERT INTO stanza VALUES('G208','1','„Kommt und esst!“ der Herr ruft heute:<br/>„Kommt und esst!“<br/>Ja, wir essen, trinken Jesus, unser Fest!<br/>Wie Er täglich uns ernährt,<br/>Und mit Sich zufriedenstellt!<br/>„Kommt und esst!“ der Herr ruft heute:<br/>„Kommt und esst!“<br/>',NULL,47018,1);
INSERT INTO stanza VALUES('G208','2','„Kommt und esst!“ der Herr ruft heute:<br/>„Kommt und esst!“<br/>Ja, wir essen, trinken Jesus, unser Fest!<br/>Er belebt uns innerlich,<br/>Bis zum Rand füllt uns mit Sich,<br/>„Kommt und esst!“ der Herr ruft heute:<br/>„Kommt und esst!“<br/>',NULL,47019,2);
INSERT INTO stanza VALUES('G209','1','Die Gnade voller Wirklichkeit<br/>Aus Christus strömt, dem Brunnen;<br/>Wir preisen Christus allezeit<br/>In der Gemeinde hier!<br/>',NULL,47020,1);
INSERT INTO stanza VALUES('G209','chorus','Ehre sei Gott! Wir trinken hier vom Brunnen!<br/>In der Gemeinde sind wir nun zu Haus!<br/>',NULL,47021,2);
INSERT INTO stanza VALUES('G209','2','Erbetne Gnade kommt geschwind,<br/>Wir trinken reich vom Brunnen;<br/>Such Ihn, den Himmelsschatz, und find,<br/>Denn hier ist Er zu Haus!<br/>',NULL,47022,3);
INSERT INTO stanza VALUES('G209','3','Ja, Satan kämpft mit seiner Macht:<br/>Wir trinken mehr vom Brunnen;<br/>Der Hades überwältigt nicht,<br/>In der Gemeinde hier!<br/>',NULL,47023,4);
INSERT INTO stanza VALUES('G209','4','Wer durstig ist: zur Quelle flieh!<br/>Wir trinken gern vom Brunnen;<br/>Trink reichlich, er vertrocknet nie!<br/>In der Gemeinde hier!<br/>',NULL,47024,5);
INSERT INTO stanza VALUES('G210','1','Vom Quell des Lebens trinken wir,<br/>Aus Seinem Brunnen schöpfen hier;<br/>Denn, wer Mich trinkt, so sagt der Herr,<br/>Soll niemals, niemals dürsten mehr.<br/>Was, dürstet nimmermehr? Ja, dürstet nimmermehr!<br/>Was, dürstet nimmermehr? Ja, dürstet nimmermehr!<br/>Denn, wer Mich trinkt, so sagt der Herr,<br/>Soll niemals, niemals dürsten mehr!<br/>',NULL,47025,1);
INSERT INTO stanza VALUES('G210','2','Das Brot des Lebens essen wir,<br/>Beim Fest, das unser Herr gibt hier;<br/>Denn, wer Mich isst, so sagt der Herr,<br/>Soll niemals, niemals hungern mehr.<br/>Was, hungert nimmermehr? Ja, hungert nimmermehr!<br/>Was, hungert nimmermehr? Ja, hungert nimmermehr!<br/>Denn, wer Mich isst, so sagt der Herr,<br/>Soll niemals, niemals hungern mehr.<br/>',NULL,47026,2);
INSERT INTO stanza VALUES('G210','3','Wir atmen Geist und Leben ein,<br/>Den Geist des Lebens, das wir teiln;<br/>Denn, wer Mich atmet, sagt der Herr,<br/>Hat Gottes Leben mehr und mehr.<br/>Was, Gottes Leben hat? Ja, Gottes Leben hat!<br/>Was, Gottes Leben hat? Ja, Gottes Leben hat!<br/>Denn, wer Mich atmet, sagt der Herr,<br/>Hat Gottes Leben mehr und mehr.<br/>',NULL,47027,3);
INSERT INTO stanza VALUES('G210','4','Den Wein des Lebens schmecken wir,<br/>Sein Leben süß im Geist spürn hier;<br/>Denn, wer Mich schmeckt, so sagt der Herr,<br/>Hat Gottes Freude mehr und mehr.<br/>Was, Gottes Freude hat? Ja, Gottes Freude hat!<br/>Was, Gottes Freude hat? Ja, Gottes Freude hat!<br/>Denn, wer Mich schmeckt, so sagt der Herr,<br/>Hat Gottes Freude mehr und mehr.<br/>',NULL,47028,4);
INSERT INTO stanza VALUES('G210','5','Ja, Christus starb und auferstand,<br/>Sein Königs-Leben uns gesandt;<br/>Empfängst du Ihn, so singst du Gott<br/>Und lebest immer, immerfort.<br/>Was, leben immerfort? Ja, leben immerfort!<br/>Was, leben immerfort? Ja, leben immerfort!<br/>Empfängst du Ihn, so singst du Gott<br/>Und lebest immer, immerfort.<br/>',NULL,47029,5);
INSERT INTO stanza VALUES('G211','1','Trinkt! Vom reinen, klaren Strom, aus Gottes Thron er fließt;<br/>Esst! Vom Baum des Lebens, Seine Früchte jetzt genießt;<br/>Seht! Gar keine Lampe, Sonn noch Mond mehr braucht''s als Licht,<br/>Denn hier die Nacht gibt''s nicht!<br/>',NULL,47030,1);
INSERT INTO stanza VALUES('G211','chorus','Komm doch, oh, komm doch,<br/>So sagen Geist und Braut:<br/>Komm doch, oh, komm doch,<br/>Wer''s hört, der rufe laut.<br/>Komm doch, oh, komm doch,<br/>Wer durstig ist und will,<br/>Trink Wasser des Lebens umsonst!<br/>',NULL,47031,2);
INSERT INTO stanza VALUES('G211','2','Christus, unser Strom und Wasser springt aus uns heraus;<br/>Christus, unser Baum und Frucht, genießen wir daraus;<br/>Christus, unser Tag und Licht und unser Morgenstern;<br/>Christus alles ist!<br/>',NULL,47032,3);
INSERT INTO stanza VALUES('G211','3','Wascht die Kleider und den Baum des Lebens froh genießt,<br/>„O Herr, Amen, Halleluja!“ – Jesus ist so süß!<br/>Üben alle unsren Geist, um Christus zu erfahren.<br/>Reich versorgt Er uns!<br/>',NULL,47033,4);
INSERT INTO stanza VALUES('G211','4','Ein Zuhause haben wir, das wie die Sonne scheint,<br/>Wo die Brüder alle eins sind und im Herrn vereint.<br/>Jesus baut uns all zusammen, Ihn wir stellen aus<br/>Hier in der Gemeind.<br/>',NULL,47034,5);
INSERT INTO stanza VALUES('G212','1','Ich fand den Unvergleichlichen,<br/>Von Herzen freu ich mich;<br/>Muss singen, weil ich Christus hab,<br/>Welch Christus habe ich!<br/>',NULL,47035,1);
INSERT INTO stanza VALUES('G212','2','In Christus als dem Gotteslamm,<br/>Mir Rettung wird zuteil;<br/>Als Sonne der Gerechtigkeit<br/>Schenkt unter Flügeln Heil.<br/>',NULL,47036,2);
INSERT INTO stanza VALUES('G212','3','Mein Christus ist der Lebensbaum,<br/>An süßen Früchten reich;<br/>Er stillt den Hunger täglich mir,<br/>Und sättigt mich zugleich.<br/>',NULL,47037,3);
INSERT INTO stanza VALUES('G212','4','Aus Christus, dem gespaltnen Fels,<br/>Das Lebenswasser quillt;<br/>Er ist ein Quell in meinem Herz,<br/>All meinen Durst Er stillt.<br/>',NULL,47038,4);
INSERT INTO stanza VALUES('G212','5','Mein Leben, Licht und Weg ist Er,<br/>Mein Friede allezeit,<br/>Mein Trost, Gesundheit, Hoffnung, Ruh,<br/>Mein Reichtum, Herrlichkeit.<br/>',NULL,47039,5);
INSERT INTO stanza VALUES('G212','6','Christus ist meine Weisheit, Kraft<br/>Mein Ruhm, Gerechtigkeit,<br/>Mein Sieg und die Erlösung auch,<br/>Und Wahrheit, Heiligkeit.<br/>',NULL,47040,6);
INSERT INTO stanza VALUES('G212','7','Er ist mein Retter, Hirte, Freund,<br/>Mein Anwalt in der Not,<br/>Mein Bruder, Herr, Berater auch,<br/>Geliebter, Vater, Gott.<br/>',NULL,47041,7);
INSERT INTO stanza VALUES('G212','8','Er Herzog, Lehrer, Führer ist,<br/>Mein Wächter Tag und Nacht,<br/>Mein Meister, Haupt und Bräutigam;<br/>In mir Er Wohnung macht.<br/>',NULL,47042,8);
INSERT INTO stanza VALUES('G212','9','Er, mein Prophet mit klarer Sicht,<br/>Mein Hohepriester treu;<br/>Vor Gott steht Er für mich stets ein,<br/>Mein König, Er herrscht heut.<br/>',NULL,47043,9);
INSERT INTO stanza VALUES('G212','10','Der Anfang, die Vollendung auch<br/>Des Glaubens ist Er mir,<br/>Mein Mittler, Bürge allezeit,<br/>Mein treuer Zeuge hier.<br/>',NULL,47044,10);
INSERT INTO stanza VALUES('G212','11','Mein ewiges Zuhause ist<br/>In Christus als dem Land;<br/>Mein Turm und Festung und Versteck,<br/>Mein Fels und fester Stand.<br/>',NULL,47045,11);
INSERT INTO stanza VALUES('G212','12','Er ist mein Sabbat, Neumond auch,<br/>Mein Morgen und mein Tag,<br/>All meine Zeit und Ewigkeit,<br/>Egal, was kommen mag.<br/>',NULL,47046,12);
INSERT INTO stanza VALUES('G212','13','Er ist mein Hort und mein Vertraun,<br/>Voll Anmut, rein und mild,<br/>Zufriedenstellung, Freude auch,<br/>All meine Sehnsucht stillt.<br/>',NULL,47047,13);
INSERT INTO stanza VALUES('G212','14','Mein Christus allumfassend ist,<br/>Wer kann''s beschreiben jetzt?<br/>Er ist in allem Alles und<br/>Zuerst und auch zuletzt.<br/>',NULL,47048,14);
INSERT INTO stanza VALUES('G212','15','Welch Schatz ist nun mein Eigentum,<br/>So unvergleichlich hier!<br/>Vor Freude singt und jauchzt mein Herz,<br/>Welch Christus lebt in mir!<br/>',NULL,47049,15);
INSERT INTO stanza VALUES('G213','1','Jesus nur ist unsre Botschaft,<br/>Er soll unser Thema sein;<br/>Wir erhöhen immer Jesus,<br/>Jesus sehen wir allein.<br/>',NULL,47050,1);
INSERT INTO stanza VALUES('G213','chorus','Einzig Jesus, immer Jesus,<br/>Alles in allem singen wir,<br/>Retter, Heiliger und Heiler,<br/>Herrlicher König, welch ein Herr!<br/>',NULL,47051,2);
INSERT INTO stanza VALUES('G213','2','Jesus nur ist unser Retter,<br/>Er nahm unsre Schulden ab,<br/>Nur durch Ihn gerecht ich stehe,<br/>Ständig Kraft durch Ihn ich hab.<br/>',NULL,47052,3);
INSERT INTO stanza VALUES('G213','3','Jesus heiligt uns beständig,<br/>Macht von Selbst und Sünde rein,<br/>Durch die Fülle Seines Geistes<br/>Nimmt Er unsre Herzen ein.<br/>',NULL,47053,4);
INSERT INTO stanza VALUES('G213','4','Jesus nur ist unser Heiler,<br/>Unsre Krankheit trug der Herr,<br/>Nun Sein Auferstehungsleben<br/>Teilen Seine Glieder sehr.<br/>',NULL,47054,5);
INSERT INTO stanza VALUES('G213','5','Jesus, einzig, unsre Kraft ist,<br/>Die seit Pfingsten stärkt und speist;<br/>Blase auf uns Deine Kraft, Herr,<br/>Fülle uns mit Deinem Geist.<br/>',NULL,47055,6);
INSERT INTO stanza VALUES('G213','6','Heute warten wir auf Jesus,<br/>Bis der Ankunftsschall trifft ein;<br/>Doch für uns wird Jesus einzig<br/>Alles und in allem sein.<br/>',NULL,47056,7);
INSERT INTO stanza VALUES('G214','1','Einst war es der Segen,<br/>Jetzt ist es mein Herr;<br/>Einst warn es Gefühle,<br/>Jetzt Sein Wort vielmehr;<br/>Einst wollt ich die Gabe,<br/>Jetzt den Geber hab;<br/>Einst nur suchte Heilung,<br/>Jetzt an Ihm mich lab.<br/>',NULL,47057,1);
INSERT INTO stanza VALUES('G214','chorus','Alles und in allem<br/>Christus nur ich sing;<br/>Alles ist in Christus<br/>Und Christus alles ist.<br/>',NULL,47058,2);
INSERT INTO stanza VALUES('G214','2','Einst war''s zähes Ringen,<br/>Jetzt schau ich auf Ihn;<br/>Einst nur halb errettet,<br/>Jetzt ganz frei ich bin;<br/>Einst nach Halt ich suchte<br/>Jetzt Er mich umfasst;<br/>Einst umhergetrieben,<br/>Jetzt mein Anker passt.<br/>',NULL,47059,3);
INSERT INTO stanza VALUES('G214','3','Einst ich emsig plante,<br/>Jetzt bet ich: „O Herr!“;<br/>Einst gab''s Angst und Sorgen,<br/>Jetzt Vertraun vielmehr.<br/>Einst, was ich nur wollte,<br/>Jetzt, was Jesus will;<br/>Einst war''s ständig bitten,<br/>Jetzt ich lob Ihn still.<br/>',NULL,47060,4);
INSERT INTO stanza VALUES('G214','4','Einst galt meine Arbeit,<br/>Jetzt um Seine geht''s;<br/>Einst wollt ich Ihn brauchen,<br/>Jetzt braucht Er mich stets.<br/>Einst die Kraft ich wollte,<br/>Jetzt den starken Gott;<br/>Einst mir selbst ich diente,<br/>Jetzt mich Ihm anbot.<br/>',NULL,47061,5);
INSERT INTO stanza VALUES('G214','5','Einst auf Jesus hoffte,<br/>Jetzt ist Er doch mein;<br/>Einst mein Licht nur glimmte,<br/>Jetzt ein heller Schein;<br/>Einst den Tod erwartet,<br/>Jetzt die Herrlichkeit;<br/>Christus, meine Hoffnung,<br/>Lebt in mir allzeit.<br/>',NULL,47062,6);
INSERT INTO stanza VALUES('G215','1','Ich kam hin zum lebendigen Quell,<br/>Der von droben hinunter frei fließt;<br/>Ich verließ so die Wasser des Streits<br/>Und gelangte zum Elim der Lieb.<br/>Ich trank tief aus dem himmlischen Brunnen,<br/>Meinem Herzensgrund tief er entspringt;<br/>Die Erzählung gelingt keinem Menschen<br/>Von der Freud, die der Tröster mir bringt.<br/>',NULL,47063,1);
INSERT INTO stanza VALUES('G215','chorus','Oh, komm zum lebendigen Quell,<br/>Zum Brunnen, der ewig frei fließt!<br/>Welche Freud meine Seele genießt,<br/>Denn Christus ist mein Lebens-Quell!<br/>',NULL,47064,2);
INSERT INTO stanza VALUES('G215','2','Ich kam hin zu dem Brunnen von Blut,<br/>Der für Schuld und Unreinheit frei quillt,<br/>Der die Kleider von Sünd-Flecken reinigt;<br/>Alle Anklagen sind nun gestillt.<br/>Mit Gerechtigkeit bin ich umkleidet,<br/>Die in Jesus mir wurde zuteil;<br/>Ich hab Anteil an Seiner Natur<br/>Und in Ihm find ich mein ganzes Heil.<br/>',NULL,47065,3);
INSERT INTO stanza VALUES('G215','3','Ich kam hin zu dem Brunnen des Heils,<br/>Zur Versorgung so maßlos und frei;<br/>Weder Weisheit noch Geld dieser Erde<br/>Das Geheimnis entschlüsselt dabei.<br/>Doch den Schlüssel enthüllte mein Herr,<br/>Wie die Flut Seiner Seite entströmt,<br/>Wie die Wunden der Striemen mich heilen,<br/>Wie Er kommt und bei mir ewig wohnt.<br/>',NULL,47066,4);
INSERT INTO stanza VALUES('G215','4','Ich kam hin zu dem Brunnen der Freud,<br/>Seine Freude ist mir Herzenskraft;<br/>Und mein Sonnenschein kann nie verschwinden<br/>Noch die Wonne, die Er mir verschafft.<br/>Der Feigenbaum stirbt und vertrocknet,<br/>Das Vergnügen der Welt umso mehr;<br/>Doch wie kann denn mein Brunnen versiegen?<br/>Mein Anteil und Freud ist der Herr.<br/>',NULL,47067,5);
INSERT INTO stanza VALUES('G216','1','Alles in Jesus habe ich:<br/>Mein Leben, Freude, Ruh.<br/>Und Er stärkt mich mit Seiner Kraft<br/>Ich falle sonst im Nu.<br/>Bin ich betrübt, gibt Trost der Herr;<br/>Niemand erfreut mich so wie Er.<br/>Froh macht mich Er allezeit sehr;<br/>Er ist mein Freund.<br/>',NULL,47068,1);
INSERT INTO stanza VALUES('G216','2','Alles in Jesus habe ich,<br/>Mein Freund in jedem Test.<br/>Er gibt mir Seinen Segen gern,<br/>Bei Ihm sein ist ein Fest.<br/>Er gibt den Regen, Sonnenschein;<br/>Lässt mich die Ernte bringen ein,<br/>Steht für mich ein tagaus, tagein –<br/>Er ist mein Freund.<br/>',NULL,47069,2);
INSERT INTO stanza VALUES('G216','3','Alles in Jesus habe ich,<br/>Zu Ihm ich ehrlich bet.<br/>Ja, Ihn verleugnen könnt ich nicht,<br/>Da Er mir stets beisteht.<br/>Ihm will ich folgen Tag und Nacht,<br/>Da Er mein Herz so freudig macht,<br/>Und Tag und Nacht über mir wacht,<br/>Er ist mein Freund.<br/>',NULL,47070,3);
INSERT INTO stanza VALUES('G216','4','Alles in Jesus habe ich,<br/>Mein bester Freund ist Er.<br/>Ja, Ihm vertrau ich jetzt und dann,<br/>Wenn Er mich holt noch mehr.<br/>Oh, welch ein Leben hab ich heut!<br/>Täglich genieß ich Ihn erneut,<br/>Sein Leben mich ewig erfreut,<br/>Er ist mein Freund.<br/>',NULL,47071,4);
INSERT INTO stanza VALUES('G217','1','Zu Sich zieht Jesus unsre Herzen jeden Tag noch mehr,<br/>Er ist wie frischer Tau, der Allerschönste ist der Herr;<br/>Es fehlen uns die Worte, Er ist einfach wunderbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,47072,1);
INSERT INTO stanza VALUES('G217','chorus','Selbst halb so viel des Schatzes ist rein unvorstellbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war!<br/>',NULL,47073,2);
INSERT INTO stanza VALUES('G217','2','Als wir Ihn sahen klar und hell in der Gemeinde hier,<br/>Erschien uns Seine Herrlichkeit, welch Reichtum fanden wir;<br/>Gestillt wird hier die Sehnsucht unsres Geistes immerdar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,47074,3);
INSERT INTO stanza VALUES('G217','3','Nun wohnt Er als der Geist des Lebens stets in unsrem Geist,<br/>Mit Seiner süßen Salbung uns Sein Leben unterweist!<br/>Befreit fließt unser Geist in der Versammlung wunderbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,47075,4);
INSERT INTO stanza VALUES('G217','4','Der Herr hat uns für Seinen Plan und Herzenswunsch vereint:<br/>Nun die Gemeinde als die Fülle Christi herrlich scheint.<br/>Für diesen Vorsatz geben wir uns Ihm nun völlig dar,<br/>Und täglich wird er teurer als er''s jemals vorher war.<br/>',NULL,47076,5);
INSERT INTO stanza VALUES('G218','1','Christus fanden wir, der alles ist,<br/>Allumfassend anwendbar;<br/>Wer Ihn anruft, reich gesegnet ist,<br/>Oh, wie göttlich, wunderbar!<br/>',NULL,47077,1);
INSERT INTO stanza VALUES('G218','chorus','Es ist Freude, unsagbare Herrlichkeit<br/>Welch Herrlichkeit, welch Herrlichkeit!<br/>Es ist Freude, unsagbare Herrlichkeit<br/>Nicht die Hälfte wurde je gesagt!<br/>',NULL,47078,2);
INSERT INTO stanza VALUES('G218','2','Wir entdeckten: Christus ist der Geist,<br/>Der in unsrem Geist nun wohnt;<br/>Wie verfügbar und so nah ist Er!<br/>Christi Süße reich belohnt.<br/>',NULL,47079,3);
INSERT INTO stanza VALUES('G218','3','Hier der Weg, wie du durch Christus lebst:<br/>Bet Sein Wort und ruf Ihn an!<br/>Dies – das Essen, Trinken – uns belebt,<br/>Kostbar ist dies zu erfahrn.<br/>',NULL,47080,4);
INSERT INTO stanza VALUES('G218','4','Die Gemeinde ist an jedem Ort<br/>Ein Zuhause voll Genuss!<br/>Nicht mehr wandern wir in Babylon,<br/>Leben hier im Überfluss.<br/>',NULL,47081,5);
INSERT INTO stanza VALUES('G218','5','Sich zu treffen mit den Heiligen,<br/>Ist die größte Freud auf Erd;<br/>Hier wird unser Geist stets angefacht,<br/>Und das Leben voller Wert.<br/>',NULL,47082,6);
INSERT INTO stanza VALUES('G219','1','Alles ist möglich dem Menschen, der gut<br/>An Jesu Namen glauben kann;<br/>Herr, Deinen Nam mach ich nicht mehr zu Schand,<br/>Dein'' Wahrheit nehm ich liebevoll an;<br/>Ich kann, ich will doch glauben Dir,<br/>Alles ist mein und möglich mir.<br/>',NULL,47083,1);
INSERT INTO stanza VALUES('G219','2','Es war das allerunmöglichste Ding,<br/>Dass Sündenherrschaft von mir weich;<br/>Doch es wird sein, ja, ich weiß, es wird sein,<br/>Herr, Deiner Treue trau ich gleich;<br/>Wenn nichts für mich zu schwer wird sein,<br/>Ist alles möglich mir, und mein.<br/>',NULL,47084,2);
INSERT INTO stanza VALUES('G219','3','Lästern die Erde und Hölle das Wort,<br/>Trotzt Gottes Wort doch jedem Test;<br/>Der Herr kann brechen der Sünd Eisenmacht,<br/>Es ist unmöglich, steht doch fest;<br/>Das ganz unmöglich Ding wird sein,<br/>Alles ist möglich mir, und mein.<br/>',NULL,47085,3);
INSERT INTO stanza VALUES('G219','4','Alles ist möglich bei Gott allemal,<br/>Christus, im Menschen Gottes Macht,<br/>Mir, wenn ich ganz und gar neu werde sein,<br/>Völlig in Christi Form gebracht;<br/>Er wird von Sündenmacht befrein,<br/>Alles ist möglich mir, und mein.<br/>',NULL,47086,4);
INSERT INTO stanza VALUES('G219','5','Alles ist möglich bei Gott allemal,<br/>Christus, der Gottes Kraft in mir;<br/>Herr, hier Dein mächtiges Selbst breite aus,<br/>Dass nicht ich, sondern Du lebst hier;<br/>Mir diese Stund zu prüfen gib<br/>Die süße Allmacht Deiner Lieb.<br/>',NULL,47087,5);
INSERT INTO stanza VALUES('G220','1','Nun, Christus ist uns objektiv-subjektiv,<br/>Im Himmel steht Er für uns ein objektiv;<br/>Und in jedem Glied subjektiv lebt Er jetzt,<br/>So innerlich sie in Sein Wesen versetzt.<br/>',NULL,47088,1);
INSERT INTO stanza VALUES('G220','2','Zur Rechten des Vaters sitzt Er immerfort,<br/>Da als Hohepriester wies Er Sein Blut vor;<br/>Als Fürsprecher unsere Lasten dort trägt,<br/>Als Bürge steht hin, uns in Liebe umhegt.<br/>',NULL,47089,2);
INSERT INTO stanza VALUES('G220','3','Der Herr als der Geist lebt in unserem Geist,<br/>Mit Ihm als dem Leben uns alles erweist;<br/>Mit Kraft und mit Gnade uns stärkt jeden Tag,<br/>Als Tröster zu stützen uns immer vermag.<br/>',NULL,47090,3);
INSERT INTO stanza VALUES('G220','4','Verherrlicht als Mensch ist im Himmel der Herr,<br/>Für uns eingetreten, Vorläufer ist Er;<br/>Den Menschen in Gott bringt, in Ihm als dem Sohn<br/>Macht ihn eins mit Gott, dies ist unsre Vision.<br/>',NULL,47091,4);
INSERT INTO stanza VALUES('G220','5','Die Fülle der Gottheit erfüllt Christi Sein,<br/>Als Geist überträgt Er sie in uns hinein;<br/>Er offenbart Gott und macht Ihn uns vertraut,<br/>Im göttlichen Leben Er uns auferbaut.<br/>',NULL,47092,5);
INSERT INTO stanza VALUES('G220','6','Der Retter fuhr auf in den Himmel, wohnt dort,<br/>Und bald kommt Er wieder, so heißt es im Wort;<br/>Doch heute befreit uns der Herr innerlich,<br/>Er wird uns verklärn und entrücken zu Sich.<br/>',NULL,47093,6);
INSERT INTO stanza VALUES('G220','7','Wir sehn bald die heilige Stadt voller Wert,<br/>Wo eins sich vermengen wird Himmel und Erd,<br/>Worin Objektives und das Subjektiv<br/>Sich in uns auf ewig vermengen wird tief.<br/>',NULL,47094,7);
INSERT INTO stanza VALUES('G221','1','Oh, wie subjektiv ist Christus!<br/>Er wohnt jetzt in meinem Geist;<br/>Christus ist so allumfassend,<br/>Ist mit mir im Geist vereint.<br/>',NULL,47095,1);
INSERT INTO stanza VALUES('G221','chorus','Christus ist für mich so subjektiv!<br/>In mir wahr und süß ist Er!<br/>Christus ist so allumfassend reich!<br/>Was mir fehlt, erfüllt der Herr.<br/>',NULL,47096,2);
INSERT INTO stanza VALUES('G221','2','Oh, wie subjektiv ist Christus!<br/>Leben gebend stets bereit;<br/>Er als Geist belebt mich ständig,<br/>Und erfrischt zu jeder Zeit.<br/>',NULL,47097,3);
INSERT INTO stanza VALUES('G221','3','Oh, wie subjektiv ist Christus!<br/>Wandelt um, erfüllt mich reich;<br/>Er macht neu Verstand und Willen,<br/>Seinem Bild gestaltet gleich.<br/>',NULL,47098,4);
INSERT INTO stanza VALUES('G221','4','Oh, wie subjektiv ist Christus!<br/>Er ist die Befreiungskraft,<br/>Als Gesetz vom Geist des Lebens<br/>Mir die Freiheit stets verschafft.<br/>',NULL,47099,5);
INSERT INTO stanza VALUES('G221','5','Oh, wie subjektiv ist Christus!<br/>Tag für Tag gleicht Er mich aus,<br/>Weist zurecht, regiert und führt mich,<br/>Er mich stets neu richtet aus.<br/>',NULL,47100,6);
INSERT INTO stanza VALUES('G221','6','Oh, wie subjektiv ist Christus!<br/>Meinen Durst stillt Er vollauf;<br/>Er versorgt mit Seinem Reichtum,<br/>Zeigt so Gottes Fülle auf.<br/>',NULL,47101,7);
INSERT INTO stanza VALUES('G222','1','Es ist Gottes Wohlgefallen:<br/>Christus offenbart in mir.<br/>Keine äußre Religion mehr,<br/>Christus muss es sein in mir.<br/>',NULL,47102,1);
INSERT INTO stanza VALUES('G222','chorus','Es ist Gottes Wohlgefallen:<br/>Christus eingewirkt in mir;<br/>Nichts mehr äußerlich vollbringen,<br/>Christus nur ist alles mir.<br/>',NULL,47103,2);
INSERT INTO stanza VALUES('G222','2','Es ist Gottes Wohlgefallen:<br/>Christus leben soll in mir;<br/>Sich nicht gut verhalten, sondern<br/>Christus lebt und wirkt in mir.<br/>',NULL,47104,3);
INSERT INTO stanza VALUES('G222','3','Es ist Gottes Wohlgefallen:<br/>Christus wird geformt in mir;<br/>Nicht den äußren Formen folgen,<br/>Christus sprießt und wächst in mir.<br/>',NULL,47105,4);
INSERT INTO stanza VALUES('G222','4','Es ist Gottes Wohlgefallen:<br/>Christus wohnen soll in mir;<br/>Nicht auf äußre Weise dienen,<br/>Christus Wohnung macht in mir.<br/>',NULL,47106,5);
INSERT INTO stanza VALUES('G222','5','Es ist Gottes Wohlgefallen:<br/>Christus sei die Hoffnung mir;<br/>Nicht die Herrlichkeit von außen,<br/>Subjektiv ist Er schon hier.<br/>',NULL,47107,6);
INSERT INTO stanza VALUES('G222','6','Es ist Gottes Wohlgefallen:<br/>Christus soll mir alles sein;<br/>Nichts mehr äußerlich besitzend,<br/>Christus ewiglich ist mein.<br/>',NULL,47108,7);
INSERT INTO stanza VALUES('G223','1','Als Leben, Herr, bist Du in mir,<br/>Und alles jetzt für mich!<br/>Du bist verfügbar, subjektiv,<br/>Und so erfahr ich Dich.<br/>',NULL,47109,1);
INSERT INTO stanza VALUES('G223','chorus','O Herr, Du bist der Geist jetzt!<br/>Wie kostbar und so nah!<br/>Dass Du allzeit verfügbar bist,<br/>Ist einfach wunderbar!<br/>',NULL,47110,2);
INSERT INTO stanza VALUES('G223','2','Was ich auch brauch, Du Herr versorgst<br/>Mit Dir mich wunderbar;<br/>Zur rechten Zeit, genügend auch,<br/>Für mich nun anwendbar.<br/>',NULL,47111,3);
INSERT INTO stanza VALUES('G223','3','Und Deine süße Salbung, Herr,<br/>In Schwachheit stützt mit Macht;<br/>Der stete Zustrom Deiner Kraft<br/>Mich stärkt und neu entfacht.<br/>',NULL,47112,4);
INSERT INTO stanza VALUES('G223','4','Und Dein Gesetz des Lebens mein<br/>Verhalten reguliert;<br/>Der Reichtum Deiner Wirklichkeit<br/>Mein Sein ganz infundiert.<br/>',NULL,47113,5);
INSERT INTO stanza VALUES('G223','5','Die Einheit, liebster Herr, mit Dir<br/>Ist einfach Herrlichkeit!<br/>Du bist ein Geist mit mir, o Herr,<br/>In alle Ewigkeit!<br/>',NULL,47114,6);
INSERT INTO stanza VALUES('G224','1','Oh, welch wunderbare Freiheit<br/>Mir mein Retter, Christus, gab!<br/>Er nahm alle Kraft der Sünde,<br/>Tat den Todesstachel ab!<br/>',NULL,47115,1);
INSERT INTO stanza VALUES('G224','chorus','Durch den Sieg des Herrn, so mächtig<br/>Überwinde ich nun weit;<br/>Seine Auferstehungskraft stärkt<br/>Mich von meinem Geist allzeit!<br/>',NULL,47116,2);
INSERT INTO stanza VALUES('G224','2','Dem Gesetz bin ich gestorben,<br/>Und durch Christus frei gesetzt;<br/>Es kann niemals mehr mich knechten,<br/>Durch die Gnade leb ich jetzt.<br/>',NULL,47117,3);
INSERT INTO stanza VALUES('G224','3','Christus hat verdammt die Sünde,<br/>Nahm am Kreuz all ihre Macht;<br/>Sie hat nun in mir kein Recht mehr,<br/>Ich bin völlig frei gemacht.<br/>',NULL,47118,4);
INSERT INTO stanza VALUES('G224','4','Unzerstörbar ist Sein Leben,<br/>Er den Tod hat weggeschafft;<br/>Todesfesseln sind zerrissen<br/>Durch die Auferstehungskraft.<br/>',NULL,47119,5);
INSERT INTO stanza VALUES('G224','5','Er hat Satan, Welt, Dämonen<br/>Durch den Tod gemacht zunicht,<br/>Aus der Todesnacht mich führte<br/>In Sein Leben und Sein Licht.<br/>',NULL,47120,6);
INSERT INTO stanza VALUES('G224','6','Voll genügt mir Seine Gnade,<br/>Kraft umhüllt mich äußerlich;<br/>Darum rühm ich mich der Schwachheit,<br/>Denn in Schwachheit stärkt Er mich.<br/>',NULL,47121,7);
INSERT INTO stanza VALUES('G225','1','Kein Gesetz, noch Satzung<br/>Bürdet uns Gott auf,<br/>Vielmehr schenkt Er Christus,<br/>Unsre Muh hört auf;<br/>Keine Art von Lehre<br/>Uns vom Selbst befreit,<br/>Nur das Leben Christi<br/>Rettet allezeit.<br/>',NULL,47122,1);
INSERT INTO stanza VALUES('G225','2','Keine Art von Lehre<br/>Muster, noch Modell<br/>Kann den Geist beleben,<br/>Wandeln um die Seel;<br/>Christus als der Geist uns<br/>Gottes Leben gibt,<br/>Um durch uns zu leben,<br/>Was der Vater liebt.<br/>',NULL,47123,2);
INSERT INTO stanza VALUES('G225','3','Nicht Philosophie, noch<br/>Sonst ein Element,<br/>Macht uns Christi Bild gleich,<br/>Das Gott anerkennt;<br/>Christus Selbst erneuert,<br/>Unser Sein durchdringt,<br/>Und in Auferstehung<br/>Uns als Glieder bringt.<br/>',NULL,47124,3);
INSERT INTO stanza VALUES('G225','4','Keine Religion, auch''s<br/>Christentum wird nie<br/>Ausführn Gottes Vorsatz<br/>Und Ökonomie;<br/>Doch in uns ist Christus,<br/>Der uns alles gilt,<br/>Der die Wünsche Gottes,<br/>Seinen Plan erfüllt.<br/>',NULL,47125,4);
INSERT INTO stanza VALUES('G225','5','Alle Funktionen,<br/>Gaben von dem Herrn,<br/>Dürfen nicht ersetzen<br/>Christus, Ihn versperrn;<br/>Christus muss uns alles<br/>Und in allem sein!<br/>Christus Selbst allein nur,<br/>Groß sei''s oder klein!<br/>',NULL,47126,5);
INSERT INTO stanza VALUES('G226','1','Oh, der Reichtum meines Retters,<br/>Unermesslich und so groß;<br/>Ja, die ganze Fülle Gottes<br/>Nun erfahr ich grenzenlos.<br/>',NULL,47127,1);
INSERT INTO stanza VALUES('G226','chorus','Oh, welch Reichtum hat mein Retter,<br/>Christus, stets für mich bereit!<br/>Unerforschlich seine Maße,<br/>Dennoch meine Wirklichkeit!<br/>',NULL,47128,2);
INSERT INTO stanza VALUES('G226','2','Oh, der Reichtum meines Retters,<br/>Allumfassend: Leben, Licht,<br/>Kraft und Weisheit, Trost und Heilung,<br/>Welche Schätze Gott verspricht!<br/>',NULL,47129,3);
INSERT INTO stanza VALUES('G226','3','Durch Erlösung, volle Rettung,<br/>Durch die Auferstehungskraft,<br/>Er mich heiligt und verherrlicht,<br/>Höchste Freude mir verschafft!<br/>',NULL,47130,4);
INSERT INTO stanza VALUES('G226','4','Oh, der Reichtum meines Retters –<br/>Gott teilt aus, was Er Selbst ist!<br/>Und all das, was Er erlangt hat,<br/>Freudevoll mein Geist genießt.<br/>',NULL,47131,5);
INSERT INTO stanza VALUES('G226','5','Oh, der Reichtum meines Retters,<br/>Wer erfasst, wie lang und breit?<br/>Hoch und tief? Wie unermesslich<br/>Und so voller Lieblichkeit!<br/>',NULL,47132,6);
INSERT INTO stanza VALUES('G226','6','Mög ich diesen Reichtum kennen,<br/>Und den Herrn erfahren mehr;<br/>Ihn mit anderen genießen,<br/>Überströmend reich ist er.<br/>',NULL,47133,7);
INSERT INTO stanza VALUES('G227','1','Herr Jesus, ich lieb Dich, ich weiß, Du bist mein;<br/>Für Dich lass ich Sündenvergnügungen sein;<br/>Du bist mein Erlöser, in Dir will ich ruhn,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,47134,1);
INSERT INTO stanza VALUES('G227','2','Ich lieb Dich, weil Du, Herr, zuerst liebtest mich,<br/>Vergebung Du schenktest, das Kreuz nahmst auf Dich;<br/>Für mich ließt Du Dornen an Deine Stirn tun,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,47135,2);
INSERT INTO stanza VALUES('G227','3','Im Leben, im Tod, werd ich noch lieben Dich,<br/>Ich preis Dich, solange der Atem füllt mich;<br/>Und lieg ich im Sterben, doch kund möcht ich tun:<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,47136,3);
INSERT INTO stanza VALUES('G227','4','In endloser Freude der ewigen Zeit<br/>Dann lieb ich Dich lobpreisend in Herrlichkeit;<br/>Mit glitzernder Krone singen werd ich tun,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,47137,4);
INSERT INTO stanza VALUES('G228','1','Ich liebe meinen Herrn, doch nicht aus mir,<br/>Denn ich hab keine Lieb;<br/>Ich lieb Dich, doch die Liebe ist von Dir,<br/>Ich leb ja Dir zulieb.<br/>Ich bin wie nichts und freue mich zu sein<br/>Leer und verschlungen nur von Dir allein.<br/>',NULL,47138,1);
INSERT INTO stanza VALUES('G228','2','Herr, Deine Kinder brauchen Dich allein<br/>Nichts über Dich hinaus;<br/>Aus Dir entspringen Segensströme rein,<br/>Welch seliges Zuhaus!<br/>Quelle des Lebens, Gnade frei und reich,<br/>Mitte und Wohnung bist Du uns zugleich.<br/>',NULL,47139,2);
INSERT INTO stanza VALUES('G229','1','Ich lieb Dich, Jesus,<br/>Deine Liebe zu mir<br/>Zieht mich Dich stets zu suchen<br/>Und nachlaufen Dir,<br/>Zieht mich Dich stets zu suchen,<br/>Und nachlaufen Dir.<br/>Du bist, Geliebter,<br/>So wunderbar und lieblich,<br/>Mein Herz erfreut sich nur an Dir.<br/>',NULL,47140,1);
INSERT INTO stanza VALUES('G229','2','Deine Liebe, Jesus,<br/>Ist süßer als Wein,<br/>Und der Duft Deiner Salben<br/>Durchströmt nun mein Sein,<br/>Und der Duft Deiner Salben<br/>Durchströmt nun mein Sein.<br/>Ein Gartenbrunnen,<br/>Ein Quell lebendgen Wassers<br/>Fließt reich vom Libanon Gebirge.<br/>',NULL,47141,2);
INSERT INTO stanza VALUES('G229','3','Oh, komm, Geliebter,<br/>Meinen Garten blas an,<br/>Dass der Duft der Gewürze<br/>Herausströmen kann.<br/>Dass der Duft der Gewürze<br/>Herausströmen kann.<br/>Meine Braut und Schwester,<br/>Ich komm in meinen Garten,<br/>Wein, Milch und Honig hier genieße.<br/>',NULL,47142,3);
INSERT INTO stanza VALUES('G229','4','Leg mich, Herr Jesus,<br/>Als Siegel an Dein Herz;<br/>Eifersucht ist hart wie Scheol,<br/>Liebe – stark wie der Tod,<br/>Eifersucht ist hart wie Scheol,<br/>Liebe – stark wie der Tod.<br/>Viel Wasser vermag nicht<br/>Die Liebe zu ertränken,<br/>Kein Schatz in dieser Welt ihr gleichkommt.<br/>(Die letzen drei Zeilen jeder Strophe wiederholen.)<br/>',NULL,47143,4);
INSERT INTO stanza VALUES('G230','1','Liebster Jesus, teurer Jesus,<br/>Oh, ich liebe Dich so sehr!<br/>Wer wie Du ist schön und lieblich?<br/>Wer wie Du ist süß und friedlich?<br/>Voller Anmut, unvergleichlich,<br/>Niemand kommt Dir gleich, o Herr!<br/>',NULL,47144,1);
INSERT INTO stanza VALUES('G230','2','Liebster Jesus, teurer Jesus,<br/>Gerne hör ich Deinen Ruf;<br/>Deine Worte mich besiegen,<br/>Eitelkeiten nun versiegen;<br/>Andres lass ich stehn und liegen,<br/>Möcht bei Dir sein allezeit.<br/>',NULL,47145,2);
INSERT INTO stanza VALUES('G230','3','Liebster Jesus, teurer Jesus,<br/>Macht mein Sträuben denn noch Sinn?<br/>Wirf die Härte vor Dich nieder,<br/>Voller Lobpreis komm ich wieder;<br/>Herr, ich weih Dir meine Glieder,<br/>Ich gehorche Dir mit Freud.<br/>',NULL,47146,3);
INSERT INTO stanza VALUES('G230','4','Liebster Jesus, teurer Jesus,<br/>Ich will wählen Deinen Weg;<br/>Beim Gehorchen auch trotz Tränen<br/>Möcht ich treu sein Deinen Plänen;<br/>Deine Freude ist mein Sehnen,<br/>Deine Liebe macht mich still.<br/>',NULL,47147,4);
INSERT INTO stanza VALUES('G230','5','Liebster Jesus, teurer Jesus,<br/>Wenn fehlt Deine Gegenwart,<br/>Morgendämmrung ist verschwommen,<br/>Mir mein Lächeln ist genommen;<br/>Ich schau nur nach Deinem Kommen<br/>Und nach Deinem Angesicht.<br/>',NULL,47148,5);
INSERT INTO stanza VALUES('G230','6','Liebster Jesus, teurer Jesus,<br/>Wie nur sag ich alles Dir?<br/>Ja, für Dich in Lieb ich brenne,<br/>Als mein Anteil Dich erkenne;<br/>Du bist das, was ich ersehne,<br/>Dir allein nur jag ich nach.<br/>',NULL,47149,6);
INSERT INTO stanza VALUES('G230','7','Liebster Jesus, teurer Jesus,<br/>Für Dich geb ich alles her;<br/>Wer wie Du ist schön und lieblich?<br/>Wer wie Du ist süß und friedlich?<br/>Voller Anmut, unvergleichlich,<br/>Niemand kommt Dir gleich, o Herr!<br/>',NULL,47150,7);
INSERT INTO stanza VALUES('G231','1','Deine Schönheit, Herr, hat mich gefangen,<br/>Dir nur öffne ich mein Herz jetzt weit;<br/>Religiöse Pflichten sind vergangen,<br/>In Dir lass mich bleiben allezeit.<br/>Wenn ich Deine Herrlichkeit hier sehe,<br/>Nun erfüll mein Herz mit Strahlenglanz;<br/>Herr, durchtränke mich, dies ich erflehe,<br/>Deinen Geist vermeng mit meinem ganz.<br/>',NULL,47151,1);
INSERT INTO stanza VALUES('G231','2','Scheinender! – im offnen Himmel seh ich<br/>Dich, den Sohn des Menschen, auf dem Thron!<br/>Heiliger, nun Gottes Flamm verzehrt mich,<br/>Bis aus mir strahlt nur Deine Person.<br/>Als ich Dich in Deinem hellen Glanz sah,<br/>Sank beschämt all Eigenherrlichkeit;<br/>Nun mein Herz bringt Liebe Dir und Lob dar,<br/>Und schmeckt Deines Namens Lieblichkeit.<br/>',NULL,47152,2);
INSERT INTO stanza VALUES('G231','3','Teurer Herr, mein Fläschchen Alabaster<br/>Nun aus Liebe Dir zerbreche ich,<br/>Und ich salb Dein Haupt, geliebter Meister;<br/>Sieh, das Beste hob ich auf für Dich.<br/>Liebster, ich will mich auf Dich verschwenden,<br/>Dich zu lieben mich zufriedenstellt;<br/>Liebe strömt aus meinem tiefen Innern,<br/>Teures Öl ist Dir bereitgestellt.<br/>',NULL,47153,3);
INSERT INTO stanza VALUES('G231','4','Liebster, komm zum Berg mit den Gewürzen;<br/>Wie Dein Angesicht stark ich ersehn!<br/>Trinke, Herr, vom Quell aus meinem Herzen,<br/>Bis in Deinem Arm ich ewig lehn.<br/>Dich verehre ich, Herr, nicht alleine:<br/>Deine liebe Braut stimmt mit mir ein;<br/>Liebster, Dich erwartet unsre Liebe,<br/>Komm doch schnell, Du wirst zufrieden sein.<br/>',NULL,47154,4);
INSERT INTO stanza VALUES('G232','1','Ein Gefäß aus Ton bin ich,<br/>Christus kam als Schatz in mich;<br/>Sein Behälter muss ich sein,<br/>Ihn, den Inhalt, nehm ich ein.<br/>',NULL,47155,1);
INSERT INTO stanza VALUES('G232','2','Er schuf mich in Seinem Bild<br/>Mich zu fülln mit Ihm gezielt;<br/>Gott erschuf Sich ein Gefäß,<br/>Ganz dem Inhalt – Ihm – gemäß.<br/>',NULL,47156,2);
INSERT INTO stanza VALUES('G232','3','Christus wohnt in meinem Geist,<br/>Seine Kraft mir Halt erweist;<br/>Er und ich sind eins allzeit,<br/>Er ist meine Wirklichkeit.<br/>',NULL,47157,3);
INSERT INTO stanza VALUES('G232','4','Täglich wirkt in mir der Herr,<br/>Sich vermengt mit mir stets mehr,<br/>Schritt für Schritt treu leitet mich,<br/>Jeden Teil füllt Er mit Sich.<br/>',NULL,47158,4);
INSERT INTO stanza VALUES('G232','5','Ihn von innen bringe ich<br/>Nun zum Ausdruck äußerlich;<br/>Ganz kristallklar muss ich sein,<br/>Dass durch mich Er leuchte rein.<br/>',NULL,47159,5);
INSERT INTO stanza VALUES('G232','6','Mehr Umwandlung brauch ich sehr,<br/>Muss zerbrochen werden mehr,<br/>Bis der Ton die Form annimmt,<br/>Mit dem Schatz zusammenstimmt.<br/>',NULL,47160,6);
INSERT INTO stanza VALUES('G233','1','Hinter den Vorhang, aus dem Lager geh,<br/>Den Himmel schmecke, leg die Erde ab;<br/>Mich stellt das Heiligste zufrieden so,<br/>Dass Erden-Nichtigkeiten ich aufgab.<br/>',NULL,47161,1);
INSERT INTO stanza VALUES('G233','2','Hinter den Vorhang, aus dem Lager geh,<br/>Durch Gottes Gegenwart die Erde weicht;<br/>Himmlische Herrlichkeit erfreut den Geist,<br/>Irdisches Glück mich nicht mehr zieht so leicht.<br/>',NULL,47162,2);
INSERT INTO stanza VALUES('G233','3','Schau hinterm Vorhang Christi Herrlichkeit,<br/>Geh aus dem Lager und zu Jesus lauf;<br/>Wenn Thron und Krone fesseln meinen Geist,<br/>Krippe und Kreuz mich nicht mehr halten auf.<br/>',NULL,47163,3);
INSERT INTO stanza VALUES('G233','4','Gehe für Auferstehungskraft hinein,<br/>Geh aus dem Lager, trage Kreuz und Schmach;<br/>Seh ich im Himmel Sein Gesicht hell strahln,<br/>Folg ich auf Erden Seinen Schritten nach.<br/>',NULL,47164,4);
INSERT INTO stanza VALUES('G233','5','Geh durch den Vorhang, Himmels-Speise iss,<br/>Harr vor dem Lager aus in Mühsal heut;<br/>Irdisches Leid zerreißt mein Herz, und doch<br/>Himmels-Gemeinschaft meinen Geist erfreut.<br/>',NULL,47165,5);
INSERT INTO stanza VALUES('G233','6','Geh durch den Vorhang, Christus ist dein Fest,<br/>Dort, vor dem Lager, Hungernde verpfleg;<br/>Himmlisches Leben, ausgelebt durch mich,<br/>Irdische Seelen speist auf ihrem Weg.<br/>',NULL,47166,6);
INSERT INTO stanza VALUES('G233','7','Geh durch den Vorhang, bis er nicht mehr ist,<br/>Bis alle Lager sind Vergangenheit;<br/>Eins wird der Himmel und die Erde sein,<br/>Eins werden Gott und Mensch in Ewigkeit.<br/>',NULL,47167,7);
INSERT INTO stanza VALUES('G234','1','Ja, ich glaubte dem Bericht,<br/>Halleluja sei dem Lamm!<br/>Und den Vorhof ich durchschritt!<br/>Oh, Herrlichkeit sei Gott!<br/>Ich bin ganz auf Jesu Seit,<br/>Der Altar hat mich geweiht,<br/>Von der Welt und Sünd befreit,<br/>Halleluja sei dem Lamm!<br/>',NULL,47168,1);
INSERT INTO stanza VALUES('G234','chorus','Halleluja! Halleluja!<br/>Durch den Vorhang ging ich ein,<br/>Ew''ge Herrlichkeit ist mein,<br/>Halleluja! Halleluja!<br/>In der Gegenwart des Königs leb ich jetzt.<br/>',NULL,47169,2);
INSERT INTO stanza VALUES('G234','2','König, Priester nun für Gott,<br/>Halleluja sei dem Lamm!<br/>Durch das reinigende Blut,<br/>Oh, Herrlichkeit sei Gott!<br/>Durch des Geistes Licht und Macht<br/>Leb und web ich Tag und Nacht<br/>Hier im Heiligsten voll Pracht,<br/>Halleluja sei dem Lamm!<br/>',NULL,47170,3);
INSERT INTO stanza VALUES('G234','3','Durch den äußren Vorhang hin,<br/>Halleluja sei dem Lamm!<br/>Der einst Gottes Licht verhing,<br/>Oh, Herrlichkeit sei Gott!<br/>Brachte mich das Blut hinein<br/>In die Heiligkeit so rein,<br/>Dort kann Selbst und Sünd nicht sein,<br/>Halleluja sei dem Lamm!<br/>',NULL,47171,4);
INSERT INTO stanza VALUES('G234','4','Ich bin nun am heil''gsten Ort,<br/>Halleluja sei dem Lamm!<br/>Nun der innre Vorhang fort,<br/>Oh, Herrlichkeit sei Gott!<br/>Schon geheiligt hin zu Gott,<br/>Durch die Macht und Kraft im Blut,<br/>Wohn ich nun im Herrn, wie gut!<br/>Halleluja sei dem Lamm!<br/>',NULL,47172,5);
INSERT INTO stanza VALUES('G235','1','Am Morgen früh komm ich zu Ihm,<br/>Eh am Himmel hell aufgeht die Sonne;<br/>Und Sein Angesicht strahlt und scheint auf mich –<br/>In mir fließt süße Wonne.<br/>Und Er spricht zu mir, und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Voller Glück und Freude genieß ich Ihn,<br/>Mein Hunger ist ganz vorbei.<br/>',NULL,47173,1);
INSERT INTO stanza VALUES('G235','2','Er spricht als der Geist durch das Wort<br/>Bis mein Herz froh ein Echo will singen,<br/>Mich der Lebensbrunnen mit Gnade stärkt,<br/>In mir will freudig springen.<br/>Und Er spricht zu mir und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Und ich trink von Ihm allezeit so gern,<br/>Mein Durst ist jetzt ganz vorbei.<br/>',NULL,47174,2);
INSERT INTO stanza VALUES('G235','3','Mit Sanftmut behandelt Er mich,<br/>Während ich vor Ihm freudig verweile;<br/>Er durchtränkt mich ganz und versorgt mich reich,<br/>Füllt meine innren Teile.<br/>Und Er spricht zu mir und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Und in jeder Hinsicht genieß ich Ihn,<br/>Die Sorgen sind ganz vorbei.<br/>',NULL,47175,3);
INSERT INTO stanza VALUES('G236','1','Süß ist Dein Name, wie das Salböl, mir;<br/>Besser schmeckt Deine Liebe mir als Wein!<br/>Zieh mich, wir folgen Deiner Herde nach<br/>Wolln in Gemeinschaft Deiner Liebe sein.<br/>',NULL,47176,1);
INSERT INTO stanza VALUES('G236','2','Er – mein Geliebter, ich – von Ihm geliebt.<br/>Zieh mich und Dir nachlaufen wollen wir;<br/>Duftend wie Myrrh, im Herzen berg ich Dich,<br/>Schön wie die Henna kleidst Du mich mit Dir.<br/>',NULL,47177,2);
INSERT INTO stanza VALUES('G236','3','Köstlich wie Äpfel Seine Liebe schmeckt,<br/>Auf Seiner Brust mich Süße sanft umhüllt;<br/>Er ist das Liebesbanner über mir,<br/>Welches mein Herz mit reiner Freude füllt.<br/>',NULL,47178,3);
INSERT INTO stanza VALUES('G236','4','Oh, Er ist mein Geliebter, ich bin Sein;<br/>Ich, eine Lilie; Hirte ist Er mir;<br/>Bis Tagesanbruch, wann die Schatten fliehn,<br/>Seh ich Ihn auf den Bergen, einen Hirsch.<br/>',NULL,47179,4);
INSERT INTO stanza VALUES('G236','5','Myrrhe, der Tod mit Ihm, und Weihrauchsduft,<br/>Die Auferstehung, solln mich füllen mehr;<br/>Nordwind wach auf, komm Südwind, blase an,<br/>Duft meines Herzensgartens liebt Er sehr.<br/>',NULL,47180,5);
INSERT INTO stanza VALUES('G236','6','Dir wär ich eine reine Taube gern,<br/>In dem Geklüft versteck ich mich für Dich;<br/>Ganz Dir gehör ich, ich die Freude Dir,<br/>Du bist ganz mein, das Hohelied für mich.<br/>',NULL,47181,6);
INSERT INTO stanza VALUES('G236','7','Schön wie der Mond, Sein Bild hell trage ich,<br/>Klar wie die Sonn, erwachsen Seinem Maß;<br/>Sein Leben kommt zum Ausdruck nun durch mich,<br/>Meinem Geliebten, das erfreut Sein Herz.<br/>',NULL,47182,7);
INSERT INTO stanza VALUES('G236','8','Du bist mein Leben und ich bin Dein Bild;<br/>Solch Einheit macht die Liebe stark wie Tod,<br/>Nichts kann sie löschen, nichts ersetzen sie,<br/>Bis auf Gewürzenbergen Du kommst bald.<br/>',NULL,47183,8);
INSERT INTO stanza VALUES('G237','1','Ich berühre Dich durch Glauben,<br/>Retter, Quell vom allem Gut;<br/>Tugend fordre ich im Glauben<br/>Durch die Waschung in dem Blut.<br/>',NULL,47184,1);
INSERT INTO stanza VALUES('G237','chorus','In mir brennt der Geist des Lebens,<br/>Wenn ich Dich berühre, Herr;<br/>Wie Er reinigt, mich durchsättigt!<br/>Herrlichkeit sei Dir und Ehr!<br/>',NULL,47185,2);
INSERT INTO stanza VALUES('G237','2','Dich berühre ich im Glauben,<br/>Und genieß Dich überaus;<br/>Was ich bin, möcht ich Dir öffnen,<br/>Was Du bist, teilst Du mir aus.<br/>',NULL,47186,3);
INSERT INTO stanza VALUES('G237','3','Herr, Dein ausgestrecktes Zepter,<br/>Starker König, rühr ich an;<br/>Ich steig hoch auf Adlers Flügeln,<br/>Da ich Deine Gnad empfang.<br/>',NULL,47187,4);
INSERT INTO stanza VALUES('G237','4','Du versorgst mit Deinem Reichtum,<br/>Weisheit, Gnade, Kraft und Licht;<br/>Hilf mir Dich stets zu berühren,<br/>Weiln vor Deinem Angesicht.<br/>',NULL,47188,5);
INSERT INTO stanza VALUES('G238','1','Herr, Du sagst, Du bist der Weinstock,<br/>Wir die Reben, wunderbar;<br/>Doch ich bringe keine Früchte<br/>Und der Grund ist mir nicht klar.<br/>',NULL,47189,1);
INSERT INTO stanza VALUES('G238','2','Ich ersehne Frucht zu tragen,<br/>Lass Dein Leben noch mehr sehn,<br/>Deinem Thron mehr Ehre bringen,<br/>Herr, Dein Wille soll geschehn.<br/>',NULL,47190,2);
INSERT INTO stanza VALUES('G238','3','Doch ich kann Dich nicht verstehen,<br/>Was Du meinst mit „Bleib in Mir“.<br/>Wenn ich mehr versuch „zu bleiben“,<br/>Spür ich, ich bin nicht in Dir.<br/>',NULL,47191,3);
INSERT INTO stanza VALUES('G238','4','Spüre stark, ich kann nicht bleiben,<br/>Bete zwar und streng mich an;<br/>Du scheinst weit von mir zu stehen,<br/>Keine Frucht ich zeigen kann.<br/>',NULL,47192,4);
INSERT INTO stanza VALUES('G238','5','Ich sei Rebe, sagtest Du einst,<br/>Fest im Weinstock, Herr, in Dir;<br/>Wenn ich Dich als Retter nehme,<br/>Wird Dein Wort nun wahr in mir.<br/>',NULL,47193,5);
INSERT INTO stanza VALUES('G238','6','Jetzt in Dir, muss ich nicht suchen,<br/>Wie die Rebe kommt in Dich,<br/>Mit Dir bin ich schon verbunden,<br/>Eins mit Dir Du machtest mich.<br/>',NULL,47194,6);
INSERT INTO stanza VALUES('G238','7','Nicht „hineinzukommen“ brauch ich,<br/>Denn ich bin „bereits in Dir“!<br/>Ich muss nicht mehr fragen: „Wie Herr?“<br/>Bete: „Lass mich bleiben hier!“<br/>',NULL,47195,7);
INSERT INTO stanza VALUES('G238','8','Ich bin drin, bereits in Dir, Herr!<br/>Ganz in Dich hineingebracht!<br/>Ich muss nicht mehr beten, kämpfen,<br/>Gott Selbst hat es schon vollbracht.<br/>',NULL,47196,8);
INSERT INTO stanza VALUES('G238','9','Da jetzt drin, warum noch bitten?<br/>Oh, wie lang ich blind doch war!<br/>Herr, ich preise Dich mit Jubel<br/>Für Dein Wort, wie wunderbar!<br/>',NULL,47197,9);
INSERT INTO stanza VALUES('G238','10','Ich komm ganz zur Ruh in Dir, Herr,<br/>Lasse nun mein altes Ich;<br/>Du bist Kraft und Du bist Leben,<br/>Alles bist Du, Herr, für mich.<br/>',NULL,47198,10);
INSERT INTO stanza VALUES('G239','1','Wir sehn des Lebens Geheimnis,<br/>Die Vision göttlich scheint hier:<br/>Dank Gott sind wir nun in Christus,<br/>Ja, wir bleiben, im Weinstock bleiben wir.<br/>',NULL,47199,1);
INSERT INTO stanza VALUES('G239','chorus','Im Weinstock bleiben wir,<br/>Im Weinstock bleiben wir,<br/>Gottes Lebensreichtum gibt es hier!<br/>Lobt Gott, Er bracht'' uns her<br/>Nie zu verlassen mehr –<br/>Wir bleiben, im Weinstock bleiben wir.<br/>',NULL,47200,2);
INSERT INTO stanza VALUES('G239','2','Nicht mehr mit Mühe und Kämpfen<br/>Müssen wir finden hinein.<br/>Lobt Gott – wir sind jetzt schon in Ihm,<br/>Halleluja, im Weinstock jetzt zu sein.<br/>',NULL,47201,3);
INSERT INTO stanza VALUES('G239','3','In uns bewegt sich das Salböl,<br/>Bringt uns das göttliche Sein;<br/>Schenkt uns die göttliche Salbung,<br/>Hier im Weinstock, im Weinstock nur allein.<br/>',NULL,47202,4);
INSERT INTO stanza VALUES('G239','4','Im Lebensstrom wir nun leben<br/>Oh, wie Sein Licht uns scheint hier!<br/>Gott und der Mensch sind zu Hause,<br/>Ja, im Weinstock, im Weinstock bleiben wir!<br/>',NULL,47203,5);
INSERT INTO stanza VALUES('G240','1','Er der Weinstock, wir die Reben,<br/>Lasst uns bleiben, hier allein,<br/>Und lasst Ihn auch in uns bleiben,<br/>Lebensstrom in uns zu sein.<br/>',NULL,47204,1);
INSERT INTO stanza VALUES('G240','chorus','Bleibt in Ihm, bleibt in Ihm!<br/>In dem Weinstock bleibt doch gern!<br/>Wenn wir in dem Weinstock bleiben,<br/>Tiefer kennen wir den Herrn.<br/>',NULL,47205,2);
INSERT INTO stanza VALUES('G240','2','Hören wir Sein frisches Sprechen,<br/>Er in uns, das reiche Wort;<br/>„Amen“ müssen wir dem sagen,<br/>Was wir hörten, immerfort.<br/>',NULL,47206,3);
INSERT INTO stanza VALUES('G240','3','Nur so kennen wir das Bleiben<br/>Auf die echte, tiefe Art;<br/>Wenn wir unseren Herrn lieben,<br/>Tun wir alles, was Er sagt.<br/>',NULL,47207,4);
INSERT INTO stanza VALUES('G240','4','Dann bleibt Seine Liebe in uns,<br/>Und in Liebe bleiben wir;<br/>Und so kennen wir Gemeinschaft<br/>Seines reichen Lebens hier.<br/>',NULL,47208,5);
INSERT INTO stanza VALUES('G240','5','Oh, wie kostbar ist das Bleiben!<br/>Oh, wie innig und vertraut!<br/>Frucht des Lebens wird gegeben,<br/>Volle Freude uns erbaut.<br/>',NULL,47209,6);
INSERT INTO stanza VALUES('G241','1','Schwach ist mein Wille, ohne Kraft,<br/>Dass meine Hoffnung ganz abklingt;<br/>Vertrau ich Deinem Wirken nur,<br/>Das mich sanft hält und weiterbringt.<br/>',NULL,47210,1);
INSERT INTO stanza VALUES('G241','2','Ich tat mein Bestes, gar nichts half,<br/>Wie ich versag in jedem Test!<br/>Nur Deine Langmut gibt mir Halt,<br/>An Deinen Worten halt mich fest.<br/>',NULL,47211,2);
INSERT INTO stanza VALUES('G241','3','Wenn sich mein stolzes Herz erhebt,<br/>Wird gleich ein Fall die Folge sein;<br/>Ich wag es nicht, zu sein noch tun,<br/>Dich brauch ich, Herr, in groß und klein.<br/>',NULL,47212,3);
INSERT INTO stanza VALUES('G241','4','Du bist mein Retter, Anker, Kraft,<br/>Ich such Dein Angesicht so sehr;<br/>Wenn ich der Allerschwächste bin,<br/>So stärkt mich Deine Gnade, Herr.<br/>',NULL,47213,4);
INSERT INTO stanza VALUES('G242','1','Wandeln wir gern mit Gott<br/>In dem Licht durch Sein Wort,<br/>Strahlt Er uns herrlich an und erbaut;<br/>Wenn wir tun, was Er will,<br/>Führt Er uns gern zum Ziel,<br/>Er führt den, der gehorcht und vertraut.<br/>',NULL,47214,1);
INSERT INTO stanza VALUES('G242','chorus','Nur dieser Weg:<br/>Ihm gehorch und vertrau!<br/>Führt zum Frohsein in Jesus,<br/>Drum gehorch und vertrau!<br/>',NULL,47215,2);
INSERT INTO stanza VALUES('G242','2','Hier kein Schatten entsteht,<br/>Wolkenhimmel vergeht,<br/>Auf Sein Lächeln mit Freude wir schaun;<br/>Jede Furcht und Unruh,<br/>Seufzer gehen im Nu,<br/>Wenn wir Ihm treu gehorchn, vertraun.<br/>',NULL,47216,3);
INSERT INTO stanza VALUES('G242','3','Keine Last tragen wir,<br/>Keinen Trost bringen hier,<br/>Wo Er uns nicht belohnt ganz genau;<br/>Alles Gram und Verlust,<br/>Alle Zweifel und Frust,<br/>Sind gesegnet: gehorch und vertrau!<br/>',NULL,47217,4);
INSERT INTO stanza VALUES('G242','4','Erst wenn wir dem Altar<br/>Alles lassen, wird wahr,<br/>Wie viel uns Seine Liebe erbaut;<br/>Wie Er liebevoll lenkt,<br/>Seine Gnade uns schenkt,<br/>Dem, der Ihm gern gehorcht und vertraut.<br/>',NULL,47218,5);
INSERT INTO stanza VALUES('G242','5','In Gemeinschaft so süß<br/>Sitzen wir Ihm zu Füß''<br/>Seine Wege zeigt Er uns genau;<br/>Was Er sagt, tun wir hier,<br/>Wenn Er sendet, gehn wir,<br/>Fürcht dich nie, nur gehorch und vertrau!<br/>',NULL,47219,6);
INSERT INTO stanza VALUES('G243','1','„Aus dem Lager“ geh zu Ihm,<br/>Trag mit Ihm dort Seine Schmach.<br/>Vor dem Tor litt Er für mich,<br/>Jag ich da noch Wohlstand nach?<br/>',NULL,47220,1);
INSERT INTO stanza VALUES('G243','2','„Aus dem Lager“ geh zu Ihm,<br/>Und sogar das Kreuz jetzt nimm;<br/>Auf dem schmalen Weg ging Er,<br/>Alles lass ich, folge Ihm.<br/>',NULL,47221,2);
INSERT INTO stanza VALUES('G243','3','„Aus dem Lager“ geh zu Ihm,<br/>Lass Verwandte hinter dir;<br/>Er des Vaters Willen tat,<br/>Teile Seine Leiden hier.<br/>',NULL,47222,3);
INSERT INTO stanza VALUES('G243','4','„Aus dem Lager“ geh zu Ihm,<br/>Sein Begleiter möcht ich sein;<br/>Keine Religion, noch Welt<br/>Soll mich jemals nehmen ein.<br/>',NULL,47223,4);
INSERT INTO stanza VALUES('G243','5','„Aus dem Lager“ geh zu Ihm,<br/>Auch wenn dort herrscht Einsamkeit;<br/>Lassen Freunde mich im Stich,<br/>Gibt Er mir Zufriedenheit.<br/>',NULL,47224,5);
INSERT INTO stanza VALUES('G243','6','„Aus dem Lager“ geh zu Ihm,<br/>Selig, wer mit Ihm ausharrt;<br/>Dort Sein Lächeln froh genieß,<br/>Ruh in Seiner Gegenwart.<br/>',NULL,47225,6);
INSERT INTO stanza VALUES('G243','7','„Aus dem Lager“ geh zu Ihm,<br/>Bis der Tag jetzt anbricht gleich;<br/>Dann mit Jubel seh ich Ihn<br/>Und genieß im Königreich.<br/>',NULL,47226,7);
INSERT INTO stanza VALUES('G244','1','Jesus als Land ist wunderbar,<br/>Und allumfassend reich:<br/>Wie Bäche, Flüsse, Ströme fließt,<br/>Ist klaren Brunnen gleich.<br/>Tälern und Hügeln reich entspringt,<br/>Fließt bis Er jeden Teil durchdringt,<br/>Tränkt uns so gut – herrliche Flut –<br/>Leben gibt!<br/>',NULL,47227,1);
INSERT INTO stanza VALUES('G244','2','Jesus das Land des Weizens ist –<br/>Am Kreuz Sein Leben ließ.<br/>Auch Auferstehungsleben ist,<br/>Die Gerste zeigt uns dies.<br/>Weinstöcke, Feigen hier du siehst,<br/>Traubensaft, Wein erfreut und fließt.<br/>Sich sehr bewährt, reich uns ernährt –<br/>Welch ein Land!<br/>',NULL,47228,2);
INSERT INTO stanza VALUES('G244','3','Christus ist reich, voll Überfluss,<br/>Wie der Granatbaum sprießt,<br/>Mit Öl salbt Er uns jeden Tag,<br/>Welch Ölbaum Er doch ist!<br/>Honig und Milch fließt überreich,<br/>Stellt uns zufrieden, stärkt zugleich,<br/>Er ist so viel, Er unser Ziel!<br/>Welch Christus!<br/>',NULL,47229,3);
INSERT INTO stanza VALUES('G244','4','Christus ist Brot im guten Land,<br/>Dass niemand leer ausgeht.<br/>In Ihm es keinen Mangel gibt,<br/>Nur Überfluss besteht.<br/>Er ist ein Land, so groß und weit,<br/>So allumfassend allezeit;<br/>Land so ersehnt – sich nun ausdehnt –<br/>Füllt das Herz!<br/>',NULL,47230,4);
INSERT INTO stanza VALUES('G244','5','Christus, ein Land aus Eisenstein,<br/>Die Vollmacht Ihm entspringt.<br/>Den festen Christus grabt nun aus,<br/>So Seinen Feind bezwingt.<br/>Leid und Plag läutern unser Sein,<br/>Kupfer in uns strahlt hell und rein.<br/>Mit Eisen bind, Kupfer wir sind,<br/>Müssen wir.<br/>',NULL,47231,5);
INSERT INTO stanza VALUES('G244','6','Herr, für das Land Dich segnen wir,<br/>Für Christus voll und reich!<br/>Wir essen Ihn, Er sättigt uns,<br/>Er hat uns voll gereicht!<br/>Lehr uns zu bauen allezeit<br/>Auf dieser großen Wirklichkeit;<br/>Wachstum wir schaun, gern wir bebaun<br/>Unser Land!<br/>',NULL,47232,6);
INSERT INTO stanza VALUES('G245','1','Wir sind im Land, wir sind im Land!<br/>O halleluja! In dem Land!<br/>Christus: das Land, Christus: das Land,<br/>O lob den Herrn! Er ist das Land!<br/>',NULL,47233,1);
INSERT INTO stanza VALUES('G245','chorus','Milch und der Honig ist der Herr;<br/>Das Korn, das Öl, der Wein ist Er.<br/>Wir sind im Land! Wir sind im Land!<br/>O halleluja! In dem Land!<br/>',NULL,47234,2);
INSERT INTO stanza VALUES('G245','2','Im Land so viel vorhanden ist:<br/>Wein, Weizen, Gerste, Wasser fließt,<br/>Auch süße Feigen, reich an Brot –<br/>Oh, welch ein Land ist unser Gott!<br/>',NULL,47235,3);
INSERT INTO stanza VALUES('G245','chorus','Welch Überfluss in unsrer Hand,<br/>Wenn wir bebauen treu das Land!<br/>Bringt jeder seinen Höchstgenuss,<br/>Ist die Versammlung voll Christus!<br/>',NULL,47236,4);
INSERT INTO stanza VALUES('G246','1','Der Herr ist mein Hirte für ewig,<br/>Er lagert mich auf grünen Au''n;<br/>Er führt mich zu stillen Gewässern,<br/>Und sättigt mich, dass ich nur staun.<br/>',NULL,47237,1);
INSERT INTO stanza VALUES('G246','chorus','Seine Gnade und Liebe sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang;<br/>Seine Gnade und Liebe sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang.<br/>Und im Haus des Herrn werde ich ewig wohnen,<br/>Ihn genießen am Tisch, den Er mir deckt;<br/>Seine Gnade und Liebe sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang.<br/>',NULL,47238,2);
INSERT INTO stanza VALUES('G246','2','Mein Hirte ist Selbst meine Weide,<br/>Mein Friede, die Wasser der Ruh;<br/>Ich esse im Geist Seinen Reichtum,<br/>Und trink, bin gesegnet dazu!<br/>',NULL,47239,3);
INSERT INTO stanza VALUES('G246','3','Mein Hirte erneuert die Seele,<br/>Den Willen, Gefühl und Verstand;<br/>Auch wenn ich durchs Tal heute wandre,<br/>Welch einen Begleiter ich fand!<br/>',NULL,47240,4);
INSERT INTO stanza VALUES('G246','4','Am Tisch, den mein Hirte gedeckt hat,<br/>Da fest ich, zermalmt Satan ist;<br/>Mein Haupt ist gesalbt mit dem Salböl,<br/>Mein Becher vor Glück überfließt!<br/>',NULL,47241,5);
INSERT INTO stanza VALUES('G246','5','Im meines Herrn Hause nun wohn ich,<br/>Genieße die Güte des Herrn;<br/>Und nichts übersteigt meine Freude,<br/>Ich freu mich in Jesus so gern!<br/>',NULL,47242,6);
INSERT INTO stanza VALUES('G247','1','Nicht ich, doch Christus sei geliebt, erhoben,<br/>Nicht ich, doch Christus sei gehört, gesehn;<br/>Nicht ich, doch Christus sei im Denken, Sprechen,<br/>Nicht ich, doch Christus sei im Tun und Gehn.<br/>',NULL,47243,1);
INSERT INTO stanza VALUES('G247','chorus','Völlig errett mich vom Selbst, o Herr,<br/>Möcht mich verliern in Dir,<br/>Dass nicht mehr länger lebe ich,<br/>Doch Christus lebt in mir.<br/>',NULL,47244,2);
INSERT INTO stanza VALUES('G247','2','Nicht ich, doch Christus tröstet sanft in Kummer,<br/>Nicht ich, doch Christus wischt ab Tränen gern;<br/>Nicht ich, doch Christus trägt die Last Verzagter,<br/>Nicht ich, doch Christus alle Furcht hält fern.<br/>',NULL,47245,3);
INSERT INTO stanza VALUES('G247','3','Christus, nur Er, kein Wort soll unnütz fallen,<br/>Christus, nur Er, kein aufgeregter Ton;<br/>Christus, nur Er, kein stolzer Lebenswandel,<br/>Christus, nur Er in mir ist die Person.<br/>',NULL,47246,4);
INSERT INTO stanza VALUES('G247','4','Nicht ich, doch Christus ist, was ich stets brauche,<br/>Nicht ich, doch Christus meine Heilung ist;<br/>Christus, nur Er Leib, Seele und den Geist stärkt,<br/>Christus, nur Er in mir als Leben fließt.<br/>',NULL,47247,5);
INSERT INTO stanza VALUES('G247','5','Christus, nur Er bald meine Hoffnung wahr macht,<br/>Christus, nur Er belohnt mit Herrlichkeit;<br/>Christus, nur Er erfüllt bald meine Sehnsucht,<br/>Christus, nur Er, mein Schatz in Ewigkeit.<br/>',NULL,47248,6);
INSERT INTO stanza VALUES('G248','1','Tod und Sünd hab ich in Adam allezeit,<br/>Doch in Christus Leben und Gerechtigkeit;<br/>Bleibe ich im Fleisch, so nimmt man Adam wahr,<br/>Bleibe ich im Geist, ist Christus stets sichtbar.<br/>',NULL,47249,1);
INSERT INTO stanza VALUES('G248','2','Wenn ich auch in Adam nicht der Sünde dien,<br/>Als ein Sünder ich zum Tod verurteilt bin;<br/>Doch in Christus Jesus, ohne eignes Tun,<br/>Bin ich schon gerecht gemacht, in Ihm kann ruhn.<br/>',NULL,47250,2);
INSERT INTO stanza VALUES('G248','3','Ohne Mühe zeige ich im Fleisch allzeit<br/>Die Natur von Adam, ihre Sündigkeit;<br/>Doch im Geist ganz ohne Kraft zu investiern,<br/>Kann ich leben so wie Er, im Geist regiern.<br/>',NULL,47251,3);
INSERT INTO stanza VALUES('G248','4','Christi Tod wirkt, dass ich frei von Adam bin,<br/>Christi Leben wirkt, dass Leben ich gewinn!<br/>Acht ich nicht aufs Fleisch, führt Adam nichts mehr aus,<br/>Acht ich auf den Geist, strahlt Er aus mir heraus.<br/>',NULL,47252,4);
INSERT INTO stanza VALUES('G248','5','Achten auf den Geist, so rettet Gott zur Zeit,<br/>Achten auf den Geist, zeigt Christi Herrlichkeit;<br/>Achten auf den Geist, wer überwinden will,<br/>Achten auf den Geist, so laufen wir zum Ziel.<br/>',NULL,47253,5);
INSERT INTO stanza VALUES('G248','6','Achten auf den Geist, so kennen wir das Kreuz,<br/>Fließt die Auferstehungskraft durch uns ja heut;<br/>Achten auf den Geist, lebt Christus durch mein Sein;<br/>Und so reift Sein Leben in mir voll und fein.<br/>',NULL,47254,6);
INSERT INTO stanza VALUES('G248','7','Christi reiches Leben strömt in meinem Geist,<br/>Stärkung wie auch Segen Er mir hier erweist;<br/>Wenn ich bleib im Geist, ist Heiligkeit zu sehn,<br/>Und voran in meinem Herzen kann Gott gehn.<br/>',NULL,47255,7);
INSERT INTO stanza VALUES('G249','1','Christus ist mein Friede,<br/>Und mein Leben drin;<br/>Eins mit Ihm im Geiste<br/>Bin ich nun mit Ihm.<br/>',NULL,47256,1);
INSERT INTO stanza VALUES('G249','chorus','Stets dem Geiste folgend,<br/>Lebe ich im Herrn;<br/>Er versorgt mit Leben,<br/>Schenkt mir Frieden gern.<br/>',NULL,47257,2);
INSERT INTO stanza VALUES('G249','2','Meinem Herrn gehör ich,<br/>Knechtschaft ist vorbei;<br/>Sein Gesetz des Lebens<br/>Macht mich völlig frei.<br/>',NULL,47258,3);
INSERT INTO stanza VALUES('G249','3','Nicht aufs Fleisch mehr sinn ich,<br/>Sondern auf den Geist;<br/>Folge ich nicht Selbst-Willn,<br/>Sondern wie Er weist.<br/>',NULL,47259,4);
INSERT INTO stanza VALUES('G249','4','Christi Kraft in mir wirkt,<br/>Dass ich geistlich bin!<br/>Meinen Leib belebt Er,<br/>Dass ich Ihm auch dien.<br/>',NULL,47260,5);
INSERT INTO stanza VALUES('G249','5','Gottes Geist mit meinem<br/>Als ein Geist bezeugt:<br/>Ich bin Erbe Gottes,<br/>Und von Ihm gezeugt.<br/>',NULL,47261,6);
INSERT INTO stanza VALUES('G250','1','Es bleibt immer etwas übrig,<br/>Wenn wir schmecken unsren Herrn;<br/>Er füllt Kelche überfließend,<br/>Reich versorgt Er uns so gern.<br/>Nichts Vertrocknetes, noch Karges<br/>Gibt der volle Speicher her;<br/>Er gibt volles Maß den Seinen,<br/>Bis es überfließt so sehr;<br/>Er gibt volles Maß den Seinen,<br/>Bis es überfließt so sehr.<br/>',NULL,47262,1);
INSERT INTO stanza VALUES('G250','2','Es bleibt immer etwas übrig,<br/>Wenn wir aus des Vaters Hand<br/>Unsren Anteil dankend nehmen,<br/>Er hat alles gut geplant.<br/>Zu versorgen uns mit Gnade<br/>Bis zum Ziel ist Er gewillt;<br/>Wenn das Herz geschmeckt hat Jesus,<br/>Unsre Sehnsucht ist gestillt;<br/>Wenn das Herz geschmeckt hat Jesus,<br/>Unsre Sehnsucht ist gestillt.<br/>',NULL,47263,2);
INSERT INTO stanza VALUES('G250','3','Es bleibt immer etwas übrig,<br/>Wenn uns Seine Liebe tränkt;<br/>Unerforscht ist ihre Tiefe,<br/>Höher ist, als jeder denkt.<br/>Keine Worte je beschreiben<br/>Seine ganze Lieblichkeit;<br/>Wir bewundern, preisen Ihn nur,<br/>Segnen Ihn in Ewigkeit;<br/>Wir bewundern, preisen Ihn nur,<br/>Segnen Ihn in Ewigkeit.<br/>',NULL,47264,3);
INSERT INTO stanza VALUES('G251','1','Oh, wie herrlich! Oh, wie heilig!<br/>Gott das ew''ge Leben ist!<br/>Ewig, unbegrenzt, barmherzig,<br/>Rein und hell dies Leben fließt!<br/>Es enthält all Seinen Reichtum<br/>Und Natur samt Lieb und Licht.<br/>',NULL,47265,1);
INSERT INTO stanza VALUES('G251','2','Oh, wie liebend! Oh, wie gnädig!<br/>Wie Gott Menschen Leben bringt!<br/>Formte Er den Geist im Menschen,<br/>So Sein Vorsatz Er vollbringt.<br/>Er wünscht, dass der Mensch Ihn aufnimmt,<br/>Diese Sehnsucht Gott durchdringt.<br/>',NULL,47266,2);
INSERT INTO stanza VALUES('G251','3','Oh, welch Liebe! Welche Gnade!<br/>Gott zu uns als Leben fließt!<br/>Hält Sich nicht mehr im Verborgnen,<br/>Sich den Menschen offen wies,<br/>Erst im Fleisch, nunmehr als Geist, dass<br/>Jetzt bekannt Sein Leben ist.<br/>',NULL,47267,3);
INSERT INTO stanza VALUES('G251','4','Oh, welch Zugang! Uns so nahe!<br/>Gott will unser Leben sein!<br/>Gott, in Christus Fleisch geworden,<br/>Menschen offenbar erscheint.<br/>Starb und auferstand, nun kommt Er<br/>Als der Geist in uns hinein.<br/>',NULL,47268,4);
INSERT INTO stanza VALUES('G251','5','Oh, welch Wunder! Als der Geist Sich<br/>Gott als Leben uns erweist!<br/>Er hat Sich noch umgewandelt:<br/>Heute ist der Herr der Geist;<br/>In uns macht Er Sich jetzt Wohnung,<br/>Überführt und unterweist.<br/>',NULL,47269,5);
INSERT INTO stanza VALUES('G251','6','Oh, wie herrlich! Oh, wie kostbar!<br/>Ich kenn die Dreieinigkeit!<br/>Gott der Vater kam im Sohn einst<br/>Dieser ist als Geist bereit.<br/>Wenn der Geist in uns hineinkommt<br/>Gott als Leben Er verleiht.<br/>',NULL,47270,6);
INSERT INTO stanza VALUES('G251','7','Wie geheimnisvoll, doch wirklich!<br/>Gott Selbst fließt in meinem Sein!<br/>Eins mit mir in meinem Herzen<br/>Will Er hier mein Leben sein.<br/>Halleluja! Halleluja!<br/>Preisen will ich Ihn allein!<br/>',NULL,47271,7);
INSERT INTO stanza VALUES('G252','1','Tief in meinem Geist fließt ein Lebensstrom klar –<br/>Der Dreieine Gott fließt in mir;<br/>Gott der Vater, der Quell, Christus Flusslauf so hell,<br/>Und der Geist bringt das Leben zu mir.<br/>',NULL,47272,1);
INSERT INTO stanza VALUES('G252','chorus','Herr, ich schätze den Lebensstrom sehr<br/>Und ich lege nun mein Leben hin;<br/>Oh, vertiefe den Lebensstrom mehr,<br/>Durch das Leben die Kron ich gewinn.<br/>',NULL,47273,2);
INSERT INTO stanza VALUES('G252','2','Auf der Weide lässt Jesus mich lagern und ruhn,<br/>Zu Wassern der Ruh führt Er mich;<br/>Nicht mehr Ringen und Last; umsonst Mühe und Hast<br/>In dem Strom voller Segen bin ich.<br/>',NULL,47274,3);
INSERT INTO stanza VALUES('G252','3','Jesus rief mich hinein an den Heiligsten Ort,<br/>Nun leb ich vor Ihm ewig hier;<br/>Halleluja, der Herr mich ermutigte sehr:<br/>„Stets bleibe als Rebe in Mir.“<br/>',NULL,47275,4);
INSERT INTO stanza VALUES('G253','1','Leben ist Gott Selbst in Christus Jesus,<br/>Als der Geist fließt Er in uns hinein;<br/>Welch Person ist Er, erfreut uns täglich mehr!<br/>Unser reiches Leben ist der Herr.<br/>',NULL,47276,1);
INSERT INTO stanza VALUES('G253','2','Er hat uns im Geist wiedergeboren,<br/>Als wir Ihm nur öffneten das Herz;<br/>Leben kam hinein in unser tiefstes Sein,<br/>Füllt uns bis zum Rand mit Ihm allein.<br/>',NULL,47277,2);
INSERT INTO stanza VALUES('G253','3','Als der Geist des Lebens wohnt Er heute<br/>Tief in unsrem Geist und fließt heraus<br/>In das Herz hinein, verändert unser Sein,<br/>Wirkt sich tief in unsre Seele ein.<br/>',NULL,47278,3);
INSERT INTO stanza VALUES('G253','4','Lasst uns treu mit Ihm zusammenwirken,<br/>Setzen den Verstand auf unsren Geist;<br/>Keinen Blick mehr schenkt all dem, was nur ablenkt,<br/>Und nur noch an Jesus Christus denkt.<br/>',NULL,47279,4);
INSERT INTO stanza VALUES('G253','5','Du als Leben wohnst in unsrem Geist nun,<br/>Deinen Vorsatz willst Du in uns tun;<br/>Wenden wir den Sinn, und geben Altes hin,<br/>Wird Dein tiefer Friede füllen ihn.<br/>',NULL,47280,5);
INSERT INTO stanza VALUES('G253','6','Nimm unsre Gedanken ganz gefangen,<br/>Wenn wir Dich im Wort genießen, Herr;<br/>Leben fließt sofort, und der Verstand bleibt dort,<br/>Bis er ganz geheiligt ist im Wort.<br/>',NULL,47281,6);
INSERT INTO stanza VALUES('G253','7','Lasst uns bei der Anwendung stets bleiben,<br/>Richten unser Sinnen auf den Sohn;<br/>Preist Ihn für den Weg, durch Christus Jesus lebt!<br/>Bleiben wir bei Dir, Herr, unentwegt.<br/>',NULL,47282,7);
INSERT INTO stanza VALUES('G254','1','Gott ist lebendig – sagt: Halleluja!<br/>Er lebt in uns nun – sagt: Halleluja!<br/>Sein voller Reichtum,<br/>Oh, wie er schmeckt uns!<br/>Ruf nur: „O Herr“ und schmeck und sieh.<br/>',NULL,47283,1);
INSERT INTO stanza VALUES('G254','2','Zusammen festen ist stets am Besten,<br/>Im Geist sind alle des Herrn Familie,<br/>Sein Leib voll Leben!<br/>Ihm Ausdruck geben,<br/>Jesus ist unsre Wirklichkeit.<br/>',NULL,47284,2);
INSERT INTO stanza VALUES('G254','3','In den Gemeinden essen und weiden,<br/>Verkünd die Botschaft an jeder Ortschaft,<br/>Von Jesus singen,<br/>Ihn allen bringen –<br/>Bis dieses Land sieht: Christus lebt.<br/>',NULL,47285,3);
INSERT INTO stanza VALUES('G255','1','Der Vater, Sohn und Geist sind ein Geheimnis,<br/>Drei nach Person, nach Wesen alle Ein.<br/>Wie wunderbar, dass dieser Gott als alles<br/>Durch Geist im Sohn nun kommt in unser Sein!<br/>',NULL,47286,1);
INSERT INTO stanza VALUES('G255','chorus','Dreieiner Gott, Du teilst Dich in uns aus!<br/>Wie wunderbar! Welch Herrlichkeit!<br/>Wir schöpfen diese Gabe nimmer aus!<br/>Wie glorreich! Welch Vortrefflichkeit!<br/>',NULL,47287,2);
INSERT INTO stanza VALUES('G255','2','Welch Reichtum liegt im Vater als der Quelle,<br/>Bereit für uns, genießen sollen wir!<br/>Wie unerschöpflich weit ist dieser Anteil<br/>In Ewigkeit, doch anwendbar schon hier!<br/>',NULL,47288,3);
INSERT INTO stanza VALUES('G255','3','Wie wunderbar! Der Sohn ist Gottes Ausdruck,<br/>Er wurde Fleisch, uns Menschen nah gebracht!<br/>Wie wirksam ist die ewige Erlösung,<br/>Welche uns Sünder eins mit Gott gemacht!<br/>',NULL,47289,4);
INSERT INTO stanza VALUES('G255','4','Der Geist ist die Verwirklichung des Sohnes,<br/>Lebensversorgung in uns voll und frei.<br/>O welcher Fakt! Der Geist mit unsrem Geiste<br/>Vermengt Sich nun, welch Einheit schafft dabei!<br/>',NULL,47290,5);
INSERT INTO stanza VALUES('G255','5','Wie wahr ist es, dass heute Gott der Geist ist,<br/>Uns zum Erfahren stets und tagtäglich!<br/>Ein Geist mit Gott sind wir – welch große Wahrheit!<br/>Und unterscheiden uns im Leben nicht!<br/>',NULL,47291,6);
INSERT INTO stanza VALUES('G256','1','Für Dein Geheimnis lob ich Dich,<br/>Dass ich nun kommen darf zu Dir;<br/>Du unzugänglich warst im Licht,<br/>Doch heut wohnst Du als Geist in mir.<br/>',NULL,47292,1);
INSERT INTO stanza VALUES('G256','2','Der Vater, Sohn und Geist, o Du,<br/>Dreieiner Gott, mein Leben bist;<br/>Deine Natur ist nun in mir,<br/>Mich reich versorgt und heilig ist.<br/>',NULL,47293,2);
INSERT INTO stanza VALUES('G256','3','Dreieiner Gott, Du bist der Geist,<br/>Der Wind und Atem ist für mich;<br/>Ja, das Geheimnis der Gottheit<br/>Ich reich erfahre innerlich.<br/>',NULL,47294,3);
INSERT INTO stanza VALUES('G256','4','Auch alles, was der Vater ist,<br/>Dem lieben Sohn hat Er geschenkt,<br/>Und alles, was der Sohn besitzt,<br/>Der Geist der Wirklichkeit empfängt.<br/>',NULL,47295,4);
INSERT INTO stanza VALUES('G256','5','Gott sendet Seinen Geist zu mir,<br/>Er kommt in meinen Geist hinein;<br/>So kann der Vater nun im Sohn<br/>Mein segensreicher Anteil sein.<br/>',NULL,47296,5);
INSERT INTO stanza VALUES('G256','6','Der Vater ist die Quelle reich,<br/>Der Sohn Ihm Ausdruck voll verleiht,<br/>Der Geist ist dessen wahre Fluß<br/>Als meine innre Wirklichkeit.<br/>',NULL,47297,6);
INSERT INTO stanza VALUES('G256','7','Der Vater kam im Sohn, um hier<br/>Dem Mensch Gott Selbst zur Schau zu stelln.<br/>Der Sohn im Geist kommt nun in mich<br/>Damit im Innern ich Gott kenn.<br/>',NULL,47298,7);
INSERT INTO stanza VALUES('G256','8','Der Vater setzte Seinen Sohn<br/>In allem als der Erste ein;<br/>Der Sohn den Vater nimmt als Haupt,<br/>Bringt alles unter Sein Hauptsein.<br/>',NULL,47299,8);
INSERT INTO stanza VALUES('G256','9','Der Geist verlangt es, dass der Sohn<br/>Die Herrlichkeit komplett erhält;<br/>Er offenbart mir Ihn so reich,<br/>Zeugnis von Ihm mir voll bestellt.<br/>',NULL,47300,9);
INSERT INTO stanza VALUES('G256','10','Du bist in letzter Form der Geist,<br/>Die Anbetung von uns empfängt;<br/>Berühr Ich Ihn in meinem Geist,<br/>So Deinen Reichtum Er mir schenkt.<br/>',NULL,47301,10);
INSERT INTO stanza VALUES('G256','11','Komm ich zu Dir in meinem Geist,<br/>Im Geist stets leb und bete an,<br/>Werd ich berühren Deinen Geist,<br/>Wodurch ich Dich genieße dann.<br/>',NULL,47302,11);
INSERT INTO stanza VALUES('G257','1','Gott ist ein Strom, der kräftig fließt,<br/>Er strömt durch alle Zeiten.<br/>Dass Er zum Menschen Sich ergießt,<br/>Sich musste zubereiten;<br/>Und doch ist Er ein Gott,<br/>Als Strom Sich uns anbot;<br/>Der Herr durch Stadien schritt,<br/>Schuf frei den Weg damit,<br/>Und nun fließt Er so reich in uns.<br/>',NULL,47303,1);
INSERT INTO stanza VALUES('G257','2','Im Anfang können wir schon schaun,<br/>Dass Gott ein klarer Strom ist;<br/>Der Strom, er bringt mit sich den Baum,<br/>Gott Selbst zu uns als Leben fließt.<br/>Und so ist es am Schluss,<br/>Auch dort sind Baum und Fluss;<br/>Gott fließt im teuren Lamm,<br/>Der Baum wächst wundersam,<br/>Gott fließt voran für ewig.<br/>',NULL,47304,2);
INSERT INTO stanza VALUES('G257','3','In einen Menschen strömte Gott,<br/>In Christus Jesus, so kostbar.<br/>Sein Leben gab Er in den Tod,<br/>Dass Gottes Leben dann frei war.<br/>Der Feind stoppt nicht Sein Wort,<br/>Der Strom reißt alles fort,<br/>Ans Kreuz er Ihn ja hieb,<br/>Speer in die Seite trieb –<br/>Doch Blut und Wasser floss heraus!<br/>',NULL,47305,3);
INSERT INTO stanza VALUES('G257','4','Das Blut und Wasser reichlich floss<br/>Ein Strom des Heils den Weg spurt.<br/>Das Blut macht uns ganz tadellos,<br/>Und Wasser bringt die Neugeburt.<br/>Der Geist, wo Er auch sei,<br/>Bringt Gott mit Sich herbei.<br/>Der Feind umsonst führt Streit,<br/>Hat selbst den Strom befreit<br/>Und Gott fließt unaufhörlich.<br/>',NULL,47306,4);
INSERT INTO stanza VALUES('G258','1','Gottes Absicht mit der Schöpfung gilt der Menschheit ganz allein,<br/>Darum wurde Er zum Geist, um mit dem Menschen eins zu sein;<br/>Seine ewige Ökonomie nimmt unser Leben ein,<br/>Vermengung ist der Weg.<br/>',NULL,47307,1);
INSERT INTO stanza VALUES('G258','chorus','Mehr Vermengung, halleluja,<br/>Mehr Vermengung, halleluja,<br/>Mehr Vermengung, halleluja,<br/>Vermengung ist der Weg!<br/>',NULL,47308,2);
INSERT INTO stanza VALUES('G258','2','Ganz zentral in uns, noch tiefer als Verstand, Gefühl und Willn,<br/>Da liegt unser Geist, mit ihm will Gott auf eines nur abzieln;<br/>Ihn erfüllen soll der Herr, so wird Er Seine Sehnsucht stilln,<br/>Vermengung ist der Weg.<br/>',NULL,47309,3);
INSERT INTO stanza VALUES('G258','3','Im Gemeindeleben heute haben wir den Weg forthin,<br/>Wie man den Dreieinen Gott erfährt und ständig lebt durch Ihn:<br/>Tauche in den Geist hinein und im vermengten Geist bleib drin,<br/>Vermengung ist der Weg.<br/>',NULL,47310,4);
INSERT INTO stanza VALUES('G258','4','Mitten unter sieben Leuchtern dort den Sohn des Menschen seht,<br/>Augen flammen, Füße glühen, Er für Gottes Vorsatz steht;<br/>Gott den korp''rativen Leib will, nur um ihn sich alles dreht,<br/>Vermengung ist der Weg.<br/>',NULL,47311,5);
INSERT INTO stanza VALUES('G258','5','Jeden Tag, in allem, was wir sind und tun und jeder denkt,<br/>Brauchen wir Vermengung, dass der Herr Sich noch vermehrt uns schenkt;<br/>Herr, wir geben uns Dir willig, der vermengte Weg uns lenkt,<br/>Vermengung ist der Weg.<br/>',NULL,47312,6);
INSERT INTO stanza VALUES('G258','6','Durch die Frucht des Alltags wird das Neu Jerusalem bereit,<br/>Gott und Mensch sind dann vollauf vermengt, ja, das ist Herrlichkeit;<br/>Welche Freude! Daran dürfen wir teilhaben allezeit,<br/>Vermengung ist der Weg.<br/>',NULL,47313,7);
INSERT INTO stanza VALUES('G259','1','Gott überträgt sich durch den Geist,<br/>In Ihm kommt Gott in uns hinein;<br/>In Ihm kann Gott in Christus hier<br/>Für uns Erfahrung täglich sein.<br/>',NULL,47314,1);
INSERT INTO stanza VALUES('G259','2','Gott als der Vater ist der Quell,<br/>Und Gott der Sohn Ihm Ausdruck bringt;<br/>Als Geist kommt Gott in uns hinein,<br/>Dass Gott als Alles uns verschlingt.<br/>',NULL,47315,2);
INSERT INTO stanza VALUES('G259','3','Den Vater Gott, im Licht verhüllt,<br/>Macht'' Gott der Sohn uns offenbar,<br/>Ihn überträgt der Geist in uns,<br/>Damit wir Ihn erkennen klar.<br/>',NULL,47316,3);
INSERT INTO stanza VALUES('G259','4','Der Sohn ist in dem Vater stets,<br/>Und jetzt der Sohn ist auch der Geist;<br/>Der Geist, der Sohn und Vater Gott<br/>Sind in uns nun und mit uns eins.<br/>',NULL,47317,4);
INSERT INTO stanza VALUES('G259','5','Gott als der Vater in dem Sohn<br/>Ist offenbar, verkörpert hier,<br/>Und Gott den Geist, die Wirklichkeit<br/>Des Sohnes, nun empfangen wir.<br/>',NULL,47318,5);
INSERT INTO stanza VALUES('G259','6','Oh, sei des Vaters Liebe uns<br/>In Gott dem Sohn als Gnad bekannt,<br/>Und durch des Geists Gemeinschaft nun<br/>Als unsren Anteil stets erkannt.<br/>',NULL,47319,6);
INSERT INTO stanza VALUES('G260','1','Gottes Essenz besteht aus Geist,<br/>Göttlich und heilig, wunderbar;<br/>Wenn mein Geist Gottes Geist berührt,<br/>Genießen kann ich Ihn fürwahr.<br/>',NULL,47320,1);
INSERT INTO stanza VALUES('G260','2','Der Geist ist unser tiefster Teil,<br/>Am wahrsten und am wirklichsten;<br/>Will ich im Leben Gott berührn,<br/>Muss ich mein''n Geist nun aktiviern.<br/>',NULL,47321,2);
INSERT INTO stanza VALUES('G260','3','Anbetung, die der Vater sucht,<br/>Soll sein in unsrem Geist allein;<br/>Sein Geist in den des Menschen kommt,<br/>Eins werden beide Geister sein.<br/>',NULL,47322,3);
INSERT INTO stanza VALUES('G260','4','Ruft Gottes Geist nun unsren Geist,<br/>Werden sie eins, vermengt zugleich;<br/>Gottes Geist wohnt in unsrem Geist,<br/>Leben uns schenkt und stärkt so reich.<br/>',NULL,47323,4);
INSERT INTO stanza VALUES('G260','5','Wenn mein Geist Gottes Geist berührt,<br/>So füllt mich Seine Fülle dann;<br/>Nur wenn in meinem Geist ich bin,<br/>Bete ich Gott in Wahrheit an.<br/>',NULL,47324,5);
INSERT INTO stanza VALUES('G260','6','Im Dienst und in Gemeinschaft gilt,<br/>Dass zu dem Geist man andre weist;<br/>Hin zum Gebet der Dienst soll führn,<br/>Bis Geist gibt Antwort auf den Geist.<br/>',NULL,47325,6);
INSERT INTO stanza VALUES('G260','7','In deinem Geist Ihm dien und bet,<br/>In deinem Geist Sein Leben spür,<br/>In deinem Geist doch wachs, bau auf,<br/>Christus strahl aus, zu andren führ.<br/>',NULL,47326,7);
INSERT INTO stanza VALUES('G260','8','Wende mich, Herr, zu meinem Geist!<br/>Dich zu berühren, lehre mich;<br/>Dein Geist mit meinem Geist reich fließt,<br/>Sie überfließen ewiglich.<br/>',NULL,47327,8);
INSERT INTO stanza VALUES('G261','1','Gott hat vor, dass all Sein Wesen<br/>Mir Versorgung sei;<br/>Ich muss mit Ihm eins im Geist sein,<br/>Mit Ihm vereint.<br/>',NULL,47328,1);
INSERT INTO stanza VALUES('G261','chorus','Gottes Wesen, Gottes Reichtum<br/>Fließt im Geist so rein;<br/>Wenn ich meinen Geist nun übe,<br/>Ist alles mein.<br/>',NULL,47329,2);
INSERT INTO stanza VALUES('G261','2','Alles Reichtum Seines Wesens<br/>Schenkt Er, wunderbar;<br/>Wenn ich Ihn berühr im Geist, dann<br/>Nehm ich''s wahr.<br/>',NULL,47330,3);
INSERT INTO stanza VALUES('G261','3','Mein Verstand versteht Sein Sprechen<br/>Mein Geist kontaktiert;<br/>Wer nie seinen Geist gebraucht, so<br/>Viel verliert.<br/>',NULL,47331,4);
INSERT INTO stanza VALUES('G261','4','Wenn ich eine Botschaft höre,<br/>Bete ich dazu;<br/>So verdaue ich das Wort des<br/>Herrn in Ruh.<br/>',NULL,47332,5);
INSERT INTO stanza VALUES('G261','5','Wenn ich Gottes Wort studier, muss<br/>Ich berühren Gott;<br/>Im Verstand und nicht im Geist, so<br/>Bleibt es tot.<br/>',NULL,47333,6);
INSERT INTO stanza VALUES('G261','6','Oh, welch Herrlichkeit und Reichtum<br/>Im Geist strahlen rein!<br/>Wenn ich meinen Geist nun übe,<br/>Ist alles mein.<br/>',NULL,47334,7);
INSERT INTO stanza VALUES('G262','1','Nehme ich auf das Kreuz, erleid ich Leid und Pein?<br/>Nein, nimmst du auf das Kreuz, stirbst du mit Sicherheit!<br/>Seine Bedeutung ist: Beendet wirst du sein;<br/>Wenn du das Kreuz erfährst, wirst du vom Selbst befreit.<br/>',NULL,47335,1);
INSERT INTO stanza VALUES('G262','2','Gottes Befreiung uns stets tötet durch das Kreuz;<br/>Scheint es auch grausam, die Befreiung riesig ist.<br/>Christus kann nie sein unser Leben ohne Kreuz;<br/>Christus nur strahlt aus dir, wenn du gestorben bist.<br/>',NULL,47336,2);
INSERT INTO stanza VALUES('G262','3','Nur durch das Kreuz kann Gott erfüllen Seinen Plan;<br/>Doch unser Selbst ist stets Sein allergrößter Feind.<br/>Wenn du dein Selbst verleugnet hast und weggetan,<br/>Hat Gottes Willen Sieg, und auch Sein Ziel erscheint.<br/>',NULL,47337,3);
INSERT INTO stanza VALUES('G263','1','Öl fließt nicht aus den Oliven,<br/>Wenn der Druck ausbleibt;<br/>Fliehn die Trauben vor der Presse,<br/>Wird kein Wein auch einverleibt.<br/>Nardenduft nur durch Zerreibung<br/>Kann erfülln das Haus;<br/>Soll ich, Herr, die Leiden meiden,<br/>Die Du liebevoll wählst aus?<br/>',NULL,47338,1);
INSERT INTO stanza VALUES('G263','chorus','Ein jeder Schlag ist<br/>Nur Gewinn für mich.<br/>Anstatt dessen, was Du wegnimmst,<br/>Gibst Du mir, Herr Jesus, Dich.<br/>',NULL,47339,2);
INSERT INTO stanza VALUES('G263','2','Spannst Du meine Herzens-Saiten,<br/>Bis es göttlich klingt?<br/>Züchtigst Du mich stets aus Liebe,<br/>Bis mein Herz Dir Süßres singt?<br/>Herr, ich fürchte kein Entbehren,<br/>Führ zu Dir der Schmerz;<br/>Ich ergebe mich Dir willig,<br/>Um zu sehn Dein liebend Herz.<br/>',NULL,47340,3);
INSERT INTO stanza VALUES('G263','3','Herr, ich schäme mich zu sagen,<br/>Dass ich Selbst bewahr;<br/>Auch wenn Deine Liebe züchtigt,<br/>Wich ich nur, weil''s Drängen war.<br/>Ganz nach Deinem Wohlgefallen<br/>Wirk an mir noch mehr;<br/>Meiner menschlichen Gefühle<br/>Ungeachtet wirke, Herr.<br/>',NULL,47341,4);
INSERT INTO stanza VALUES('G263','4','Ist Dein Sinn nicht gleich wie meiner<br/>Deinen Weg doch geh;<br/>Wenn mich schmerzt Dein Wohlgefallen<br/>Soll mein Herz mit Dir doch stehn.<br/>Ich will Dich zutiefst erfreuen,<br/>Leid ich auch Verlust;<br/>Selbst wenn Deine Freud und Ehre<br/>Heißt, dass ich ans Kreuz hinmuss.<br/>',NULL,47342,5);
INSERT INTO stanza VALUES('G263','5','Oh, ich lob Dich, auch wenn Weinen<br/>Und Verlust mich beugt;<br/>Deine Süße, täglich größer,<br/>Dankbarkeit und Preis erzeugt.<br/>Du bist kostbarer geworden<br/>Als alles für mich:<br/>Dass ich abnehm und Du zunimmst,<br/>Bitt ich Dich, Herr, inniglich.<br/>',NULL,47343,6);
INSERT INTO stanza VALUES('G264','1','Via Bethlehem wir ziehen,<br/>Unser Herz auf Gott gesetzt;<br/>Kindgleich lernen wir von Jesus,<br/>Weinen unsre Wangen netzt;<br/>Denn der Stall und auch die Krippe<br/>Unsrem Auge gar nicht passt,<br/>Doch der Fuß muss folgen Jesus,<br/>Bis die Hand den Preis dann fasst.<br/>',NULL,47344,1);
INSERT INTO stanza VALUES('G264','2','Via Nazareth der Pfad führt,<br/>Schmal ist er, macht ständig kehrt,<br/>So viel Schweres, wer versteht es?<br/>Doch zu sehen, Gott uns lehrt:<br/>Dass der Diener ist nicht größer<br/>Als der Herr, der Sich verbarg<br/>Viele Jahre vor Welt-Ehre,<br/>Folg Ihm! Wirst belohnt nicht karg!<br/>',NULL,47345,2);
INSERT INTO stanza VALUES('G264','3','Via Galiläa, schau doch!<br/>Gegen Ihn sich alles stellt,<br/>Flüche, Steine, Schläge kriegt Er,<br/>Hat Er Seinen Weg verfehlt?<br/>Nein, der Retter ohne Schaden<br/>Geht hindurch und so auch wir,<br/>Jesus hat das Ziel vor Augen,<br/>Zieh uns, Herr, wir folgen Dir.<br/>',NULL,47346,3);
INSERT INTO stanza VALUES('G264','4','Via schlimme Qualenstunden,<br/>Dort im Garten so allein,<br/>Wo die Heere Satans weilen,<br/>Schrecklich ist die Seelenpein!<br/>Doch die Engel Gottes stärken<br/>Durchzuhalten allezeit:<br/>„Dieses Leid nicht lange dauert,<br/>Schau nur auf die Herrlichkeit!“<br/>',NULL,47347,4);
INSERT INTO stanza VALUES('G264','5','Via Golgatha ans Kreuz muss<br/>Jede edle Seele gehn;<br/>Es fällt hier der Schleier, da uns<br/>Jesus nur den Pfad lässt sehn;<br/>„Leiden wir mit Ihm“, oh, hör doch!<br/>Ist''s nur kurze, kurze Zeit,<br/>Die Erinnerung vergehn wird<br/>Dort in Seiner Herrlichkeit!<br/>',NULL,47348,5);
INSERT INTO stanza VALUES('G264','6','Dort am Grab die Lieben weinen,<br/>Meinen, Leben endet jetzt;<br/>(O Mitpilger, hat die Welt dich<br/>Mit den Toten gleichgesetzt?)<br/>Aufersteh, besieg in Jesus,<br/>Diese Welt, die nur zerfällt,<br/>Freudig wollen wir aufgeben,<br/>Was die Welt für Leben hält.<br/>',NULL,47349,6);
INSERT INTO stanza VALUES('G264','7','Vorwärts eile! Drüben schimmert,<br/>Kommt uns näher, oh, nun schaut!<br/>Gottes Stadt mit ihrer Mauer,<br/>Gott hat sie für uns gebaut;<br/>Wir erhaschen sanfte Töne,<br/>Chöre preisen Ihn so reich,<br/>Der hier starb, dass wir mit Ihm sind<br/>Auf dem Thron im Königreich.<br/>',NULL,47350,7);
INSERT INTO stanza VALUES('G264','8','Nur noch ein paar Schritte, Liebste!<br/>Keinen Schmerz der Fuß mehr hat;<br/>Keine Sünden und kein Leid mehr,<br/>Jesus ging vor uns den Pfad;<br/>Und ich höre Ihn süß flüstern:<br/>„Halte durch und lauf zum Ziel,<br/>Denn es könnt'' sein, eh es Tag wird,<br/>Dass die Reise enden will.“<br/>',NULL,47351,8);
INSERT INTO stanza VALUES('G265','1','Des Kreuzes Weg heißt Opferung,<br/>Wenn du alles weichest Gott,<br/>Wenn du dich auf dem Todes-Altar hinlegst,<br/>Wo Feuer ist Sein Gebot.<br/>',NULL,47352,1);
INSERT INTO stanza VALUES('G265','chorus','Bist du willig den Weg Seines Kreuzes zu gehn?<br/>Was für dich heißt das Tragen des Kreuz''?<br/>Du hast Leben und alles nun Gott schon geweiht!<br/>Doch Gott bist du völlig treu?<br/>',NULL,47353,2);
INSERT INTO stanza VALUES('G265','2','Im Gesang und Gebet ist es rasch gesagt:<br/>„Ich geb alles“, wie leicht es fällt!<br/>Bis ein raueres Kreuz uns entgegensteht,<br/>Und strenger die Pflicht jetzt gellt.<br/>',NULL,47354,3);
INSERT INTO stanza VALUES('G265','3','Wankst du dann oder stirbst, dem Tode treu,<br/>Einfach da an dem Kreuz auf dem Weg,<br/>Bis die Fülle von Ihm, dem Lebendigen,<br/>Dich füllt täglich, unentwegt?<br/>',NULL,47355,4);
INSERT INTO stanza VALUES('G265','4','Du musst sterben, damit du leben kannst,<br/>Eins mit Jesus am Kreuz zu sein;<br/>Durch das Leben des Auferstandenen,<br/>Des Verherrlichten leb allein.<br/>',NULL,47356,5);
INSERT INTO stanza VALUES('G266','1','Will ich Auferstehungsleben,<br/>Muss mich Jesu Kreuz anziehn;<br/>Nur durch Tod erhebt sich Leben;<br/>Nur Verlust erzielt Gewinn.<br/>',NULL,47357,1);
INSERT INTO stanza VALUES('G266','chorus','Leben kommt durch Tod,<br/>Leben kommt durch Tod;<br/>Aus dem Tod erhebt sich Leben;<br/>Leben kommt durch Tod.<br/>',NULL,47358,2);
INSERT INTO stanza VALUES('G266','2','Soll sich in mir Christus formen,<br/>Muss ich atmen aus mein Ich,<br/>In des Kreuzes Schatten leben;<br/>Ganz verleugnen muss ich mich.<br/>',NULL,47359,3);
INSERT INTO stanza VALUES('G266','3','Wenn mein Selbst durch Seinen Geist stets<br/>Mit dem Herrn gekreuzigt ist,<br/>Nur dann, wenn der Tod in mir wirkt,<br/>Reich Sein Leben aus mir gießt.<br/>',NULL,47360,4);
INSERT INTO stanza VALUES('G267','1','Lasst uns nun den Weinstock anschaun<br/>Lernt aus seinem Leben heut,<br/>Denn in hartem, kargem Boden,<br/>Ist sein Wachstum voller Leid;<br/>Er gleicht keiner wilden Blume,<br/>Die doch vielen sehr gefällt,<br/>Durcheinander, frei sie wachsen,<br/>Bilden Formen ungezählt.<br/>',NULL,47361,1);
INSERT INTO stanza VALUES('G267','2','Doch die Blüten eines Weinstocks,<br/>Klein und ohne Herrlichkeit,<br/>Unscheinbar und kaum zu sehen,<br/>So bescheiden allezeit;<br/>Doch der Tag kommt, da die Blüte<br/>Wird zur Frucht gewachsen sein;<br/>Keine Blumenkrone ziert sie,<br/>Nichts an ihr ist schön und fein.<br/>',NULL,47362,2);
INSERT INTO stanza VALUES('G267','3','Festgebunden wird der Weinstock,<br/>Dass er wächst nicht wild und frei;<br/>Wenn die Reben sind gewachsen,<br/>Der Spalier ihr Halt dann sei.<br/>Aus dem harten Ackerboden<br/>Muss er seine Nahrung ziehn;<br/>Kann den eignen Weg nicht wählen,<br/>Noch vor Schwierigkeiten fliehn.<br/>',NULL,47363,3);
INSERT INTO stanza VALUES('G267','4','Oh, wie schön ist''s, wenn er grün wird<br/>Und im Frühling sich ausstreckt!<br/>Lebenskraft und Lebensfülle<br/>Reiches Rebenwachstum weckt.<br/>Dichtes Laubwerk zarter Sprossen<br/>Rankt nun frei und ungericht,<br/>Streckt sich aus zum Blau des Himmels<br/>Und genießt das Sonnenlicht.<br/>',NULL,47364,4);
INSERT INTO stanza VALUES('G267','5','Doch der Winzer dieses Weinbergs<br/>Keine Nachsicht, Milde übt:<br/>Mit dem Messer und der Schere<br/>Schneidet ab, was stolz sich gibt.<br/>Wenn der Weinstock auch noch zart ist,<br/>Sitzt genau und tief der Hieb,<br/>Die zu vielen Ruten fallen,<br/>Nimmt der Geize jeden Trieb.<br/>',NULL,47365,5);
INSERT INTO stanza VALUES('G267','6','Seit der Schnittzeit dieser Weinstock<br/>Nur im Selbstmitleid verweilt?<br/>Nein, er gibt sich selbst noch mehr dem,<br/>Der die Hiebe hat erteilt,<br/>In die Hand, die ihn beschneidet,<br/>Bis die Schönheit ist vorbei,<br/>Dass sein Leben nicht vergeudet,<br/>Für die Frucht allein nur sei.<br/>',NULL,47366,6);
INSERT INTO stanza VALUES('G267','7','Wo sich Wunden wieder schließen,<br/>Neues hartes Holz sich zeigt,<br/>Jede Rebe, die geblieben,<br/>Voller Trauben tief sich neigt.<br/>Bis in heißem Sonnenglühen<br/>Blätter welken jeden Tag;<br/>Und so reift die Frucht noch reicher,<br/>Bis man erntet den Ertrag.<br/>',NULL,47367,7);
INSERT INTO stanza VALUES('G267','8','Unter ihrer Last, den Früchten,<br/>Beugt die Rebe sich herab –<br/>Welch ein Wachstum bringt die Arbeit,<br/>Als dem Schnitt er sich hingab!<br/>Dass die Frucht nun ganz gereift ist,<br/>Jeden Weinstock sehr erfreut;<br/>Doch bald kommt die Zeit der Ernte,<br/>Und das Leid beginnt erneut.<br/>',NULL,47368,8);
INSERT INTO stanza VALUES('G267','9','Hände pflücken, Füße treten<br/>Seine Fülle ganz gewillt,<br/>Bis die Kelter rot aussehn,<br/>Und ein Strom aus Wein entquillt.<br/>Blutig rot und ohne Mischung<br/>Fließt er voller Süßigkeit,<br/>Und erfüllt die ganze Erde<br/>Nun mit Freude allezeit.<br/>',NULL,47369,9);
INSERT INTO stanza VALUES('G267','10','Jetzt sieht er erbarmenswert aus,<br/>Er ist arm und kahl gemacht;<br/>Alles hat er hingegeben,<br/>Und nun überkommt ihn Nacht.<br/>Niemand bietet ihm Vergeltung<br/>Für den Wein, froh einverleibt,<br/>Immer mehr wird er geschnitten,<br/>Nur ein leerer Stumpf noch bleibt.<br/>',NULL,47370,10);
INSERT INTO stanza VALUES('G267','11','Wärme schenkt sein Wein im Winter,<br/>Süßigkeit all denen bringt,<br/>Die belastet sind mit Leiden,<br/>Und die Kälte sie durchdringt.<br/>Doch der Weinstock, draußen einsam,<br/>Tief im Schnee und Eis muss stehn,<br/>Er erträgt sein Los dort standhaft,<br/>Wenn''s auch schwer ist zu verstehn.<br/>',NULL,47371,11);
INSERT INTO stanza VALUES('G267','12','Nach dem Winter macht der Weinstock<br/>Sich für neue Frucht bereit;<br/>Knospen sprießen, Reben wachsen,<br/>Lieblich grün ist nun sein Kleid;<br/>Er beklagt sich nie und murrt nicht,<br/>Dass der Winter schmerzhaft war;<br/>Trotz Verlust will er sein Opfer<br/>Nicht vermindern dieses Jahr.<br/>',NULL,47372,12);
INSERT INTO stanza VALUES('G267','13','Während er die Arme ausstreckt,<br/>Luft einatmet, himmlisch rein,<br/>Nein, was irdisch ist und unrein,<br/>Nimmt den Weinstock niemals ein.<br/>Opfer bringt er, doch er lächelt,<br/>Denn in Liebe ist der Schnitt,<br/>Schläge trägt er, als ob niemals<br/>Er zuvor Verlust erlitt.<br/>',NULL,47373,13);
INSERT INTO stanza VALUES('G267','14','Aus den Reben dieses Weinstocks<br/>Fließt sein Saft, sein Blut und Wein.<br/>Wird sein Wachstum durch viel Leiden<br/>Und Verlust je ärmer sein?<br/>Trunkenbolde auf der Erde<br/>Schenken übermäßig ein.<br/>Werden sie durch viel Vergnügen<br/>Und Genuss je reicher sein?<br/>',NULL,47374,14);
INSERT INTO stanza VALUES('G267','15','Unser Leben wird gemessen<br/>Nach Verlust, nicht nach Gewinn;<br/>Wie viel Wein wir trinken, zählt nicht,<br/>Doch wie viel wir geben hin.<br/>Denn im Opfer, das wir bringen,<br/>Ist die Liebe stark fürwahr;<br/>Wer durch tiefstes Leid gegangen,<br/>Reicht am meisten Leben dar.<br/>',NULL,47375,15);
INSERT INTO stanza VALUES('G267','16','Nur wer streng mit sich selbst umgeht,<br/>Ist Gewinn für unsren Gott;<br/>Wer Verletzungen erduldet,<br/>Kann die trösten, die in Not.<br/>Wer das Leiden niemals annimmt,<br/>Nur wie leere Bronze klingt;<br/>Wer sein Seelenleben hingibt,<br/>Größte Freude ihn durchdringt.<br/>',NULL,47376,16);
INSERT INTO stanza VALUES('G268','1','Kein Tod das Auferstehungsleben hält<br/>Denn Gottes Leben macht es offenbar;<br/>Ist unerschaffen, unzerstörbar auch<br/>Und unbesiegbar, Christus Selbst fürwahr.<br/>',NULL,47377,1);
INSERT INTO stanza VALUES('G268','2','Kein Tod das Auferstehungsleben hält,<br/>Wenn er auch alle Macht zusammenrafft;<br/>Tod gibt dem Leben die Gelegenheit<br/>Allen zu zeigen Gottes große Kraft.<br/>',NULL,47378,2);
INSERT INTO stanza VALUES('G268','3','Kein Tod das Auferstehungsleben hält,<br/>Je mehr begraben, desto mehr vermehrt;<br/>Leid hilft dem Leben, dass es noch mehr wächst<br/>Und Frucht des Lebens überreich beschert.<br/>',NULL,47379,3);
INSERT INTO stanza VALUES('G268','4','Kein Tod das Auferstehungsleben hält,<br/>Durch jedes größte Hindernis es dringt;<br/>Es überwindet finstre Hadesmacht,<br/>Tod ganz verschlingt und vollen Sieg erringt.<br/>',NULL,47380,4);
INSERT INTO stanza VALUES('G268','5','Kein Tod das Auferstehungsleben hält,<br/>Denn Gottes Fülle macht es offenbar;<br/>Gottes Gerechtigkeit und Heiligkeit,<br/>Ja, Gottes Bild bringt es zum Ausdruck klar.<br/>',NULL,47381,5);
INSERT INTO stanza VALUES('G268','6','Kräftig das Auferstehungsleben fließt,<br/>In jedem Tod verstärkt es sich noch mehr;<br/>Mög ich erkennen und erfahren reich,<br/>Dass dieses Leben Christus ist, mein Herr.<br/>',NULL,47382,6);
INSERT INTO stanza VALUES('G269','1','Leben entspringt dem Tod! – o liebster Meister,<br/>Gilt''s hier schon oder erst im neuen Land?<br/>Nein, worauf warten? Das Gefäß, zerbrochen,<br/>Jetzt wird geformt durch Gottes Töpfer-Hand.<br/>',NULL,47383,1);
INSERT INTO stanza VALUES('G269','2','Leben entspringt dem Tod! Welch Auferstehung!<br/>Erst sind wir schwach, dann auferweckt in Kraft;<br/>Dein Leben ausgelebt in Müh und Plagen,<br/>„Christus, nicht ich“ Dir Herrlichkeit verschafft.<br/>',NULL,47384,2);
INSERT INTO stanza VALUES('G269','3','Leben entspringt dem Tod – der Pilger, einsam,<br/>Rühmt sich des Kreuzes, diesen Weg will gehn;<br/>Mit „Jesus einzig“ lebt er in Gemeinschaft,<br/>Eitlen Gewinn um Seinetwilln lässt stehn.<br/>',NULL,47385,3);
INSERT INTO stanza VALUES('G269','4','Leben entspringt dem Tod – oh, welch ein Auftrag!<br/>Wasser des Lebens jeder führt mit sich;<br/>Reicht andern diesen Strom, der überfließt, dar,<br/>Durstige Seelen stillt er ewiglich.<br/>',NULL,47386,4);
INSERT INTO stanza VALUES('G270','1','Nimm Zeit, Ihn zu schauen,<br/>Sprich oft mit dem Herrn,<br/>In Ihm bleib beständig,<br/>Und lies Sein Wort gern.<br/>Stets hör auf Sein Sprechen,<br/>Gehorsam und sanft,<br/>Und such Seinen Segen,<br/>Er stärkt Dich mit Kraft.<br/>',NULL,47387,1);
INSERT INTO stanza VALUES('G270','2','Nimm Zeit, Ihn zu schauen,<br/>Auch wenn die Welt eilt;<br/>Verbring im Verborgnen<br/>Mit Jesus viel Zeit.<br/>Wie Er wirst du werden<br/>Durch Schauen auf Ihn;<br/>Dein Wandel wird andre<br/>Zu Jesus hinziehn.<br/>',NULL,47388,2);
INSERT INTO stanza VALUES('G270','3','Nimm Zeit, Ihn zu schauen,<br/>Von Ihm sei geführt;<br/>Ihm eil nicht voraus rasch,<br/>Gleich was auch geschieht.<br/>In Leid oder Freuden<br/>Folg Ihm immer gern;<br/>Vertrau Seinem Wort,<br/>Schau auf Jesus, den Herrn.<br/>',NULL,47389,3);
INSERT INTO stanza VALUES('G270','4','Nimm Zeit, Ihn zu schauen,<br/>Die Seele zu stilln;<br/>Lass Ihn doch beherrschen<br/>Gefühl, Denken, Willn.<br/>Zu Strömen der Liebe<br/>Dich leitet der Geist,<br/>So Seine Barmherzigkeit<br/>Er dir erweist.<br/>',NULL,47390,4);
INSERT INTO stanza VALUES('G271','1','O Seel, bist du matt und bekümmert?<br/>Kein Licht in dem Dunkel du siehst?<br/>Ein Blick auf den Retter gibt Licht dir,<br/>Und Leben in Strömen frei fließt.<br/>',NULL,47391,1);
INSERT INTO stanza VALUES('G271','chorus','Wend den Blick doch auf Jesus,<br/>Schau voll in Sein Antlitz hinein,<br/>Und im Licht Seiner Gnade und Herrlichkeit<br/>Alles Irdische trüb Dir erscheint.<br/>',NULL,47392,2);
INSERT INTO stanza VALUES('G271','2','Er ging durch den Tod in das Leben,<br/>Zur Nachfolge sind wir bereit;<br/>Die Sünde hat nun keine Macht mehr,<br/>Im Herrn überwinden wir weit!<br/>',NULL,47393,3);
INSERT INTO stanza VALUES('G271','3','Der Herr hält Sein Wort, das verhieß Er;<br/>Drum glaubt Ihm und alles wird gut;<br/>Dann geht zu den sterbenden Menschen,<br/>Die volle Errettung tut kund!<br/>',NULL,47394,4);
INSERT INTO stanza VALUES('G272','1','Geh doch voran, zu Christus lauf –<br/>Dem Ziel auf deiner Bahn.<br/>Gewinn den Preis von Gottes Ruf,<br/>Zu Christus geh voran!<br/>',NULL,47395,1);
INSERT INTO stanza VALUES('G272','chorus','Geh voran! Geh voran!<br/>Geh voran! Halleluja für den Preis!<br/>O geh voran! Geh voran!<br/>Zu Christus lauf mit Fleiß!<br/>',NULL,47396,2);
INSERT INTO stanza VALUES('G272','2','Geh doch voran, es ist Verlust,<br/>Was uns Gewinn einst war,<br/>Gewinn den Preis, der Christus ist,<br/>Denn Er ist wunderbar!<br/>',NULL,47397,3);
INSERT INTO stanza VALUES('G272','3','Geh doch voran, erkenn den Herrn<br/>Und Auferstehungskraft –<br/>Denn dies ist unser höchster Lohn,<br/>Wenn Leiden uns auch schafft.<br/>',NULL,47398,4);
INSERT INTO stanza VALUES('G272','4','Geh doch voran, dies eine tu,<br/>Was hinten liegt, vergiss;<br/>Wir jagen auf das Ziel stark zu,<br/>Auf Christus ganz gewiss.<br/>',NULL,47399,5);
INSERT INTO stanza VALUES('G273','1','Einen Wettlauf gibt''s zu laufen – Halleluja,<br/>Diesen Weg nimm und den Preis gewinn.<br/>Zu all denen, die mitlaufen – Halleluja,<br/>Unser Gott sprach: „Schaue weg zu Ihm!“<br/>',NULL,47400,1);
INSERT INTO stanza VALUES('G273','chorus','Schaue weg! Oh, schaue weg!<br/>Schau auf Jesus unentwegt!<br/>Schaue weg von allem hier, schau auf Jesus,<br/>Deinen Blick doch richte nur auf Ihn!<br/>',NULL,47401,2);
INSERT INTO stanza VALUES('G273','2','Schaue nicht, was rundum ist – Halleluja,<br/>Schaue weg von jeder Schwierigkeit;<br/>Schau dahin, wo Frieden fließt – Halleluja,<br/>Schaue nur auf Seine Herrlichkeit.<br/>',NULL,47402,3);
INSERT INTO stanza VALUES('G273','3','Schaue weg, von deiner Seele – Halleluja,<br/>Schaue weg vom mürben Selbst doch drin;<br/>Schaue weg von dir aufs Ziel – Halleluja,<br/>Schaue weg von allem, schau auf Ihn.<br/>',NULL,47403,4);
INSERT INTO stanza VALUES('G273','4','Schaue weg von dem, was war – Halleluja,<br/>Schaue weg von Gut und Bös forthin;<br/>Den Lebendigen halt fest – Halleluja,<br/>Schaue weg von allem, schau auf Ihn.<br/>',NULL,47404,5);
INSERT INTO stanza VALUES('G273','5','Suche nur Sein Angesicht – Halleluja,<br/>Er vollendet auch, was Er begann;<br/>Seine Gnade Er verspricht – Halleluja –<br/>Für den Wettlauf – deshalb schau Ihn an!<br/>',NULL,47405,6);
INSERT INTO stanza VALUES('G274','1','Jahrelang beim Kreuz so sorgenvoll<br/>Tat ich Buße über Sünd und Groll,<br/>Dann den Fluss durchschritt vertrauensvoll,<br/>Den Thron berühr.<br/>',NULL,47406,1);
INSERT INTO stanza VALUES('G274','chorus','Reich Barmherzigkeit und Gnade fließt –<br/>Nun mein Herz gestärkt im Wettlauf ist!<br/>Weil Du immer mehr zu schmecken gibst,<br/>Geliebter Herr!<br/>',NULL,47407,2);
INSERT INTO stanza VALUES('G274','2','Tag für Tag versagte ich, welch Qual!<br/>Folgte dem Altarruf jedes Mal,<br/>Doch nun geh ich weiter, traf die Wahl,<br/>Den Thron berühr.<br/>',NULL,47408,3);
INSERT INTO stanza VALUES('G274','3','Drängt ins Allerheiligste voran,<br/>Lasst die Sünden, lauft nach Seinem Plan;<br/>Preist den Herrn! Er hat Sein Werk getan –<br/>Der Vorhang riss!<br/>',NULL,47409,4);
INSERT INTO stanza VALUES('G274','4','Manna hinterm Vorhang nun genießt,<br/>Das Gesetz des Lebens, Stab der sprießt;<br/>Wohnt in Christus, der die Lade ist –<br/>Halleluja!<br/>',NULL,47410,5);
INSERT INTO stanza VALUES('G275','1','Tief tauch ich ein in Deinen Namen, Herr,<br/>Über mich hast Du stille Freud gebracht;<br/>Du, Herr, genügst, wie lang der Tag auch ist,<br/>Du, Herr, genügst, wie schwarz ist auch die Nacht.<br/>',NULL,47411,1);
INSERT INTO stanza VALUES('G275','2','Du bist der Allgenügende, mein Gott,<br/>Du kannst erschaffen, was mir mangelt sehr.<br/>Auf meiner Bahn, so einsam, hast gestreut<br/>Wunder der Liebe und Versorgung, Herr,<br/>',NULL,47412,2);
INSERT INTO stanza VALUES('G275','3','Für mich, der ich Dir traue. Noch einmal<br/>An Deine Brust zu werfen wag ich mich,<br/>Dort preis ich Deinen Weg in tiefster Ruh<br/>In stiller Glaubensruh bestaun ich Dich.<br/>',NULL,47413,3);
INSERT INTO stanza VALUES('G276','1','Frisch wie der Tau früh am Morgen<br/>Bringst Du die Ruhe, o Herr;<br/>Christus, durch Sein sanftes Salben,<br/>Tröstet mich täglich so sehr:<br/>Steh bis der Sturm ist vorüber,<br/>Steh bis dein Herz nicht mehr bangt,<br/>Steh für die Herrlichkeit Jesu,<br/>Steh bis Sein Reich ist erlangt.<br/>',NULL,47414,1);
INSERT INTO stanza VALUES('G276','chorus','Deine Stimme, o Herr,<br/>Mir Hoffnung bringt,<br/>In Deiner Gegenwart, Herr,<br/>Mein Herz froh singt.<br/>',NULL,47415,2);
INSERT INTO stanza VALUES('G276','2','Ist in der Prüfung der Trübsal<br/>Matt mein Herz, träge mein Geist,<br/>Schimmert der Stern meines Glaubens,<br/>Doch auch noch er mir entgleist.<br/>Dann mög Dein Glaube mich trösten,<br/>Stärken mit Leben und Kraft,<br/>Damit Dein Reichtum mir reichlich<br/>Herrlichkeit ewig verschafft.<br/>',NULL,47416,3);
INSERT INTO stanza VALUES('G276','3','Herr, wie die Sonne am Morgen,<br/>Finsternis völlig verjag,<br/>Mit Deinen Flügeln der Heilung<br/>Wend meine Nacht nun zum Tag.<br/>Komm Du, o komm, Herr des Trostes,<br/>Tröstung hinein in mich gieß,<br/>Hoffnung der Herrlichkeit, stärk mich,<br/>Bis ich den Frieden genieß.<br/>',NULL,47417,4);
INSERT INTO stanza VALUES('G277','1','Oh, freut euch in unserem Herrn allezeit,<br/>Auch wenn es viel gibt zu ertragen;<br/>Nur Trübsal wie Meerwellen tobt weit und breit,<br/>Doch singen ist besser als klagen.<br/>',NULL,47418,1);
INSERT INTO stanza VALUES('G277','chorus','Drum frohlockt immer mehr, frohlockt immer mehr,<br/>Denn zu singen ist besser als klagen,<br/>Durch Leben wird Tod weggetragen,<br/>Oh, freut euch im Herrn allezeit.<br/>',NULL,47419,2);
INSERT INTO stanza VALUES('G277','2','Oh, freut euch in unserem Herrn allezeit,<br/>Trotz Pfeilen vom Feind, die uns jagen;<br/>Denn Satan erschreckt sich und scheut Fröhlichkeit<br/>Und Singen viel mehr als das Klagen.<br/>',NULL,47420,3);
INSERT INTO stanza VALUES('G277','3','Oh, freut euch in unserem Herrn allezeit,<br/>Wenn Krankheit uns niederdrückt heute;<br/>Nichts stärkt unsre Kräfte, ermuntert die Seel,<br/>Noch heilt das Gemüt wie die Freude.<br/>',NULL,47421,4);
INSERT INTO stanza VALUES('G278','1','Durch Sein Wort verspricht Sein Wiederkommen<br/>Zu erlösen dann mein ganzes Sein;<br/>Doch in Zeiten voller Gram und Trübsal<br/>Flieht die Hoffnung, Zweifel kehren ein.<br/>Fällt''s in trüben Stunden schwer zu beten,<br/>Seufz ich nur noch still in innrer Not,<br/>Tritt der Geist Selbst ein in meiner Schwachheit,<br/>Gleicherweise seufzt auch Er zu Gott.<br/>',NULL,47422,1);
INSERT INTO stanza VALUES('G278','2','Herr, ich bete nicht für noch mehr Leiden,<br/>Frei von Trübsal möcht ich mit Dir gehn;<br/>Lass den bittren Kelch von mir entfernen,<br/>Doch nach Deinem Willen soll''s geschehn.<br/>Selbst wenn Seelenschmerz erdrückt mich heftig,<br/>Herrscht in meinem Herzen Frieden tief,<br/>Da die Liebe Gottes, ausgegossen<br/>In mein Herz, die Zweifel mir vertrieb.<br/>',NULL,47423,2);
INSERT INTO stanza VALUES('G278','3','Welch Gewissheit: Gott hält jeden Umstand<br/>Meisterhaft in Seiner weisen Hand!<br/>Jeden Menschen (sehn wir''s auch verschwommen),<br/>Plante Er, wie Er''s für gut empfand.<br/>Jeder Test die Antwort ist vom Vater<br/>Auf das Seufzen des Gebets vom Geist;<br/>Christus mög in uns durch Trübsal wachsen,<br/>Bis Er uns verklärt in Herrlichkeit.<br/>',NULL,47424,3);
INSERT INTO stanza VALUES('G278','4','Soll uns Gott vor Leiden denn noch schonen,<br/>Der den eignen Sohn hat nicht verschont?<br/>Soll die Töpferhand ja nicht vollenden<br/>All Sein Werk an dem Gefäß aus Ton?<br/>Denn Er will, dass wir sind Brüder Christi,<br/>Die Er zubereitet für Sein Reich;<br/>Christus ist der teure Erstgeborne,<br/>Seinem Bild macht Er uns völlig gleich.<br/>',NULL,47425,4);
INSERT INTO stanza VALUES('G278','5','Mit dem Herrn sind wir die Erben Gottes!<br/>Welche Hoffnung auf die Herrlichkeit!<br/>Heute scheinen Leiden zu erdrücken,<br/>Doch die Herrlichkeit liegt schon bereit!<br/>In all dem wir mehr als überwinden,<br/>Durch den Einen, der uns liebt fürwahr;<br/>Bald am Tag, auf den die Schöpfung wartet,<br/>Werden Gottes Söhne offenbar!<br/>',NULL,47426,5);
INSERT INTO stanza VALUES('G279','1','Im Garten Eden stellte Gott<br/>Den Menschen vor zwei Bäume hin:<br/>Der Baum des Lebens Christus ist,<br/>Im andern Baum ist Satan drin.<br/>',NULL,47427,1);
INSERT INTO stanza VALUES('G279','2','Der Baum des Lebens Zentrum ist<br/>Von Gottes Herzenswunsch allein,<br/>Er zeigt uns Gott in Christus auf,<br/>Als Leben nimmt der Mensch Ihn ein.<br/>',NULL,47428,2);
INSERT INTO stanza VALUES('G279','3','Der andre Baum Erkenntnis gibt,<br/>Doch eine Stimme jeden warnt:<br/>Wer diesen wählt, den Tod erfährt,<br/>In ihm ein Todesquell sich tarnt.<br/>',NULL,47429,3);
INSERT INTO stanza VALUES('G279','4','Wer auch vom Baum des Lebens isst,<br/>Nimmt gleich das Leben Gottes ein,<br/>Wird umgewandelt, dies der Plan,<br/>Zu einem kostbarn Edelstein.<br/>',NULL,47430,4);
INSERT INTO stanza VALUES('G279','5','Wenn vom Erkenntnisbaum er isst,<br/>So nimmt der Mensch die Sünde an;<br/>Das bringt ihn in den Tod, sodass<br/>Er Gottes Plan nicht ausführn kann.<br/>',NULL,47431,5);
INSERT INTO stanza VALUES('G279','6','Dies zeigt, dass Gott die Quelle ist,<br/>Den Quell des Lebens immerzu;<br/>Berührn wir andres, bringt uns dies<br/>Hin zum Erkenntnisquell im Nu.<br/>',NULL,47432,6);
INSERT INTO stanza VALUES('G279','7','Denn die Erkenntnis bringt nur Tod<br/>Mag''s Gutes oder Böses sein;<br/>Ja, alles, was von Gott getrennt,<br/>Ist Frucht von Satans Trug allein.<br/>',NULL,47433,7);
INSERT INTO stanza VALUES('G279','8','Im Gegensatz zu Christus steht<br/>Nicht nur das Böse, auch das Gut;<br/>Nicht nur des Bösen Kenntnis, auch<br/>Kenntnis des Guten dieses tut.<br/>',NULL,47434,8);
INSERT INTO stanza VALUES('G279','9','Herr, lehr uns, Dich nur zu berührn<br/>In Deinem Leben für und für;<br/>Von Gut und Böse halt uns fern,<br/>Von allem außerhalb von Dir.<br/>',NULL,47435,9);
INSERT INTO stanza VALUES('G280','1','Gerecht ist das Gesetz von Gott,<br/>Das auf das Gutetun uns dringt;<br/>Durch Forderungen ist sein Zweck<br/>Zu zeigen, dass es nicht gelingt.<br/>',NULL,47436,1);
INSERT INTO stanza VALUES('G280','2','Doch im Verstand ist ein Gesetz,<br/>Das möchte Gutes tun im Nu;<br/>Doch das Gesetz der Sünde siegt<br/>In unsern Gliedern immerzu.<br/>',NULL,47437,2);
INSERT INTO stanza VALUES('G280','3','Das Gut-Gesetz, dort im Verstand,<br/>War bei der Schöpfung vorbestimmt;<br/>Gott hat es damals eingesetzt,<br/>Damit der Mensch sich gut benimmt.<br/>',NULL,47438,3);
INSERT INTO stanza VALUES('G280','4','In unsren Gliedern ein Gesetz,<br/>Das Satans böses Leben ist;<br/>In unsre Glieder drang es ein,<br/>Damals beim Fall durch Satans List.<br/>',NULL,47439,4);
INSERT INTO stanza VALUES('G280','5','Das bös Gesetz von Satan sitzt<br/>Als Sünd-Gesetz, nun in uns drin;<br/>Zum Scheitern bringt''s das Gut-Gesetz,<br/>Denn stärker ist''s von Anbeginn.<br/>',NULL,47440,5);
INSERT INTO stanza VALUES('G280','6','Doch – lobt den Herrn! – in unsrem Geist<br/>Uns das Gesetz des Lebens lenkt;<br/>Von Gottes Leben stammt es her,<br/>Ist uns durch Neugeburt geschenkt.<br/>',NULL,47441,6);
INSERT INTO stanza VALUES('G280','7','Das Geist-Gesetz das stärkste ist,<br/>Es übertrifft die andern weit;<br/>Es das Gesetz von Gott erfüllt<br/>Und vom Gesetz der Sünd befreit.<br/>',NULL,47442,7);
INSERT INTO stanza VALUES('G280','8','Gerichtet sein muss der Verstand<br/>Auf unsren Geist tief in uns drin,<br/>Und nicht auf das gefallne Fleisch,<br/>Den Leib, den Sünde rafft dahin.<br/>',NULL,47443,8);
INSERT INTO stanza VALUES('G280','9','Das Achten auf das Fleisch bringt uns<br/>In Sünde, Tod und Dunkelheit;<br/>Doch Achten auf den Geist versorgt<br/>Mit Leben, Frieden, Licht allzeit.<br/>',NULL,47444,9);
INSERT INTO stanza VALUES('G280','10','Dies ist der Weg, der echt befreit!<br/>Der Weg zum Sieg, den Gott verheißt!<br/>Im Geist zu leben, lehr uns Herr,<br/>Mit Dir zu wandeln nach dem Geist.<br/>',NULL,47445,10);
INSERT INTO stanza VALUES('G281','1','Durch das Gesetz in Buchstaben<br/>Wird Gott bestimmt als Zeugnis echt;<br/>Es zeigt, wie Gott so heilig ist,<br/>Wie liebevoll und wie gerecht.<br/>',NULL,47446,1);
INSERT INTO stanza VALUES('G281','2','Nach Gottes heiliger Natur<br/>Zu leben fordert Sein Gesetz;<br/>Nur so sind wir vor Ihm gerecht<br/>Und kommt Sein Segen zu uns stets.<br/>',NULL,47447,2);
INSERT INTO stanza VALUES('G281','3','Doch das Gesetz kein Leben gibt,<br/>Auch nie versorgt es uns mit Kraft;<br/>Doch Forderungen zeigt es auf,<br/>Zu schwach sind wir, es niemand schafft.<br/>',NULL,47448,3);
INSERT INTO stanza VALUES('G281','4','Es wurde nicht für Gottes Plan<br/>Doch für die Sünde eingeführt;<br/>Der Mensch, der''s bricht, wird bloßgestellt,<br/>Und seiner Sünde überführt.<br/>',NULL,47449,4);
INSERT INTO stanza VALUES('G281','5','Ja, das Gesetz stopft jeden Mund,<br/>Schließt alle unter Sünde ein;<br/>Zu Gottes Christus treibt es uns,<br/>Gesegnet wird dort jeder sein.<br/>',NULL,47450,5);
INSERT INTO stanza VALUES('G281','6','Ein Bild auf Christus stellt es dar,<br/>Der Gott bezeugt zu jeder Zeit;<br/>Er strahlte Gottes Liebe aus,<br/>Gerechtigkeit und Heiligkeit.<br/>',NULL,47451,6);
INSERT INTO stanza VALUES('G281','7','Als Gottes wahres Zeugnis schenkt<br/>Uns Christus Leben immerfort;<br/>So können wir erfüllen nun,<br/>Was täglich fordert Gottes Wort.<br/>',NULL,47452,7);
INSERT INTO stanza VALUES('G281','8','Ja, Christus Gottes Zeugnis ist,<br/>Uns stärkt mit Gottes Leben hier;<br/>Getötet dem Gesetz durch Ihn<br/>Nun Frucht des Geistes tragen wir.<br/>',NULL,47453,8);
INSERT INTO stanza VALUES('G282','1','Gottes Gesetz war seinerzeit<br/>Auf Stein in Tafeln eingraviert;<br/>Doch als Gesetz des Lebens heut<br/>In unsren Herzen es agiert.<br/>',NULL,47454,1);
INSERT INTO stanza VALUES('G282','2','Dieses Gesetz auf Tafeln stets<br/>Das Gute fordert, stellt uns bloß;<br/>Doch das Gesetz des Lebens stärkt<br/>Zu leben Gott, und Ihn macht groß.<br/>',NULL,47455,2);
INSERT INTO stanza VALUES('G282','3','Dieses Gesetz auf Tafeln bringt<br/>Erkenntnis Gottes äußerlich;<br/>Doch das Gesetz des Lebens gibt<br/>Erkenntnis tiefer innerlich.<br/>',NULL,47456,3);
INSERT INTO stanza VALUES('G282','4','Dieses Gesetz auf Tafeln herrscht<br/>Durch tote Regeln äußerlich;<br/>Doch das Gesetz des Lebens lenkt<br/>Durch Leben, leitet innerlich.<br/>',NULL,47457,4);
INSERT INTO stanza VALUES('G282','5','Täglich, in allem, was wir tun,<br/>Regt das Gesetz des Lebens sich;<br/>Rechtes Empfinden schenkt es uns,<br/>Es prüft und leitet innerlich.<br/>',NULL,47458,5);
INSERT INTO stanza VALUES('G282','6','Sein Regulieren wirkt in uns;<br/>Es dringt in unser tiefstes Sein;<br/>Macht uns bewusst, was Leben ist,<br/>Teilt Gott Selbst aus in uns hinein.<br/>',NULL,47459,6);
INSERT INTO stanza VALUES('G282','7','Wo das Gesetz des Lebens ist,<br/>Braucht''s keine Lehre äußerlich;<br/>Gott zu verstehen lehrt es uns,<br/>Und Ihn zu kennen innerlich.<br/>',NULL,47460,7);
INSERT INTO stanza VALUES('G282','8','Herr, lehre uns, auf dies Gesetz<br/>Zu hörn und wandeln stets danach;<br/>Dass jeder an Dir Anteil hat,<br/>Dich mehr erkennt dem Leben nach.<br/>',NULL,47461,8);
INSERT INTO stanza VALUES('G283','1','Ew''ges Leben bringt uns<br/>Die Gemeinschaft wahr,<br/>In Gemeinschaft fließt der<br/>Geist, wie wunderbar!<br/>',NULL,47462,1);
INSERT INTO stanza VALUES('G283','2','Gottes Leben ewig<br/>Uns Gemeinschaft schenkt,<br/>So den Herrn als Geist mit<br/>Uns vermengt und lenkt.<br/>',NULL,47463,2);
INSERT INTO stanza VALUES('G283','3','Leben, das im Geist ist,<br/>Zu Gemeinschaft führt;<br/>Süß dabei der Herr mit<br/>Gnade uns berührt.<br/>',NULL,47464,3);
INSERT INTO stanza VALUES('G283','4','Fähig für Gemeinschaft<br/>Uns das Leben macht;<br/>Jeden sie ins Licht führt,<br/>Der dem Geist gibt Acht.<br/>',NULL,47465,4);
INSERT INTO stanza VALUES('G283','5','Soll Gemeinschaft dauern,<br/>Brauchen wir das Blut;<br/>Dank der innren Salbung<br/>Bleibt Gemeinschaft gut.<br/>',NULL,47466,5);
INSERT INTO stanza VALUES('G283','6','Durch das Kreuz noch tiefer<br/>Die Gemeinschaft wird;<br/>Inniger und höher,<br/>Wenn der Geist regiert.<br/>',NULL,47467,6);
INSERT INTO stanza VALUES('G283','7','Die Gemeinschaft macht vom<br/>Selbst und Sünde rein;<br/>Die Gemeinschaft bringt uns<br/>Ganz in Gott hinein.<br/>',NULL,47468,7);
INSERT INTO stanza VALUES('G284','1','Ein jedes Leben hat Gespür,<br/>Empfindet und nimmt wahr;<br/>Im ew''gen Leben in uns gibt''s<br/>Empfindung göttlich, klar.<br/>',NULL,47469,1);
INSERT INTO stanza VALUES('G284','2','Je höher dieses Leben ist,<br/>Steigt der Empfindungsgrad;<br/>Am höchsten Gottes Leben ist,<br/>Für Gott Empfinden hat.<br/>',NULL,47470,2);
INSERT INTO stanza VALUES('G284','3','Es ist das göttlich Leben drin,<br/>Es ist der Sinn für Gott;<br/>In unsrem neu belebten Geist<br/>Ist''s mehr als Sinn für Gut.<br/>',NULL,47471,3);
INSERT INTO stanza VALUES('G284','4','Das innerste Bewusstsein ist''s,<br/>Ein Sinn im Herzensgrund;<br/>Mit klarer Unterscheidungskraft,<br/>Tut Gottes Willen kund.<br/>',NULL,47472,4);
INSERT INTO stanza VALUES('G284','5','Das innere Empfinden uns<br/>Ein Bild von Gott verschafft;<br/>Kennt keine Mühe, wirkt spontan,<br/>Ganz ohne eigne Kraft.<br/>',NULL,47473,5);
INSERT INTO stanza VALUES('G284','6','Wächst Gottes Leben in uns mehr,<br/>Der Sinn noch feiner wird;<br/>Entsprech ich diesem Leben mehr,<br/>Wird er intensiviert.<br/>',NULL,47474,6);
INSERT INTO stanza VALUES('G284','7','Wer das Empfinden schätzt und übt,<br/>Stärkt seinen Geist zugleich;<br/>Beachten wir stets diesen Sinn,<br/>Dann fließt Gemeinschaft reich.<br/>',NULL,47475,7);
INSERT INTO stanza VALUES('G285','1','Wer neu geboren worden ist vom Herrn,<br/>Der kann in seinem Innern Gott verstehn;<br/>Äußere Lehre brauchen wir nicht mehr,<br/>Wir können Gott in unserm Innern sehn.<br/>',NULL,47476,1);
INSERT INTO stanza VALUES('G285','2','Ewiges Leben hat den höchsten Stand,<br/>Göttliche Fähigkeit birgt es in sich;<br/>Wahre Erkenntnis Gottes schenkt es uns,<br/>Außeres Wissen ist nur kümmerlich.<br/>',NULL,47477,2);
INSERT INTO stanza VALUES('G285','3','Ja, das Gesetz des Lebens ist graviert<br/>Auf unser Herz, gelegt in unsren Sinn;<br/>Weil es dort herrscht, erkennen wir den Herrn,<br/>Äußre Belehrung bringt uns nicht dahin.<br/>',NULL,47478,3);
INSERT INTO stanza VALUES('G285','4','Heilige Salbung wohnt in unsrem Geist,<br/>Zeigt Gottes Wesen dem Herz und Verstand;<br/>Kenntnis von Gott empfangen wir durch sie,<br/>Lehre von Menschen nicht erleuchten kann.<br/>',NULL,47479,4);
INSERT INTO stanza VALUES('G285','5','Nun haben wir den Dreiein''n Gott in uns,<br/>Er regt Sich, lebt, ist wirksam allezeit;<br/>Dass wir durch diesen innern Sinn von Ihm<br/>Sehn Gottes Größe und Erhabenheit.<br/>',NULL,47480,5);
INSERT INTO stanza VALUES('G285','6','Innre Erkenntnis hat keinen Bedarf<br/>Nach äußrem Wissen und Beredsamkeit;<br/>Sondern im Geist nur leben sollen wir,<br/>Wandeln nach dem Empfinden allezeit.<br/>',NULL,47481,6);
INSERT INTO stanza VALUES('G285','7','Wenn wir in Christus göttlich leben heut,<br/>Achten aufs innere Bewusstsein schon,<br/>Dann nimmt die innere Erkenntnis zu,<br/>Und Gott graviert auf unser Herz den Sohn.<br/>',NULL,47482,7);
INSERT INTO stanza VALUES('G285','8','Innre lebendige Erkenntnis uns<br/>In der Gemeinschaft mit dem Herrn bewahrt;<br/>Durch die Erkenntnis, die verborgen ist,<br/>Gott Seine Fülle in uns offenbart.<br/>',NULL,47483,8);
INSERT INTO stanza VALUES('G286','1','Gott will vermengt sein mit dem Menschen<br/>Nach dem Prinzip der Fleischwerdung;<br/>Die beiden wirken nun zusammen,<br/>Dein Plan, Herr, weckt Bewunderung.<br/>',NULL,47484,1);
INSERT INTO stanza VALUES('G286','2','Der Mensch besitzt das Leben Gottes,<br/>Denn Gottes Ausdruck soll er sein;<br/>Den Menschen hat Er Sich erworben,<br/>Dass Gott nun herrlich aus ihm schein.<br/>',NULL,47485,2);
INSERT INTO stanza VALUES('G286','3','Erlösung ist vollbracht im Mensch,<br/>Die Weisheit Gottes ausgestellt;<br/>Die volle Rettung wird vom Menschen<br/>Der ganzen Schöpfung dargestellt.<br/>',NULL,47486,3);
INSERT INTO stanza VALUES('G286','4','Wer dient in dieser Zeit der Gnade,<br/>Abhängig sei vom Herrn dabei;<br/>Der Mensch und Gott sind fest verbunden,<br/>In Harmonie ihr Wirken sei.<br/>',NULL,47487,4);
INSERT INTO stanza VALUES('G286','5','Gott nicht allein Sein Werk vollendet,<br/>Der Mensch auch nicht allein probiert;<br/>Doch stets zusammen sie bewirken,<br/>Dass Gottes Plan gesehen wird.<br/>',NULL,47488,5);
INSERT INTO stanza VALUES('G286','6','Lasst uns bei jedem Werk verwenden<br/>Stets das Prinzip der Fleischwerdung;<br/>So wird auf unsrem Werk von Einheit<br/>Mit Sicherheit der Segen ruhn.<br/>',NULL,47489,6);
INSERT INTO stanza VALUES('G287','1','Gott bestimmte uns zur Sohnschaft,<br/>Eh die Schöpfung war vollbracht,<br/>Durch den Geist uns gleichgestaltet,<br/>Uns zum Bild des Sohnes macht;<br/>Sein geliebter Eingeborner<br/>Wird zum erstgebornen Sohn,<br/>Nun durch Ihn und viele Brüder<br/>Kommt zum Ausdruck Gott hier schon.<br/>',NULL,47490,1);
INSERT INTO stanza VALUES('G287','2','Söhne Gottes wurden wir durch<br/>Göttliche Wiedergeburt,<br/>Doch durch Reife ist''s erst, dass das<br/>Erstgeburtsrecht uns gehört.<br/>Neu geborn und voll erwachsen,<br/>Nimmt uns Gott als Söhne an,<br/>Dass durchs Maß des vollen Wuchses<br/>Gott die Sohnschaft sehen kann.<br/>',NULL,47491,2);
INSERT INTO stanza VALUES('G287','3','Unsre Seele, Leib und Geist muss<br/>Christus gleichgestaltet sein;<br/>Und vollbracht wird dies sein völlig,<br/>Wenn bald unser Herr trifft ein.<br/>Die Erlösung unsres Leibes<br/>Zeigt, dass Gott uns ganz annimmt;<br/>Uns zum letzten Mal umwandelt,<br/>So es Gottes Plan bestimmt.<br/>',NULL,47492,3);
INSERT INTO stanza VALUES('G287','4','Sind wir schließlich umgewandelt<br/>Und geheiligt für Sein Reich,<br/>In die Herrlichkeit bringt Gott uns,<br/>Macht uns Seinem Sohn ganz gleich.<br/>Nun, die Schöpfung wartet sehnlichst,<br/>Söhne solln sich offenbarn,<br/>Die befreit von jeder Knechtschaft,<br/>Freiheit grenzenlos erfahrn.<br/>',NULL,47493,4);
INSERT INTO stanza VALUES('G288','1','Dreiteilig ist der Mensch gemacht,<br/>Leib, Seele und ganz tief der Geist;<br/>So kann er Gottes Plan erfülln,<br/>Der Gottes Erbe uns verheißt.<br/>',NULL,47494,1);
INSERT INTO stanza VALUES('G288','2','Der äußre Teil des Menschen ist<br/>Der Leib, der ihm die Welt erschließt;<br/>Physisches kann der Mensch berührn,<br/>Leibhaftig so sein Ausdruck ist.<br/>',NULL,47495,2);
INSERT INTO stanza VALUES('G288','3','Die Seele ist der innre Teil,<br/>Sie zeigt des Menschen Wesen auf,<br/>Und macht ihn seiner selbst bewusst,<br/>Psychische Welt nimmt wahr vollauf.<br/>',NULL,47496,3);
INSERT INTO stanza VALUES('G288','4','Innerster Teil, das ist der Geist,<br/>Er nimmt Gott auf so wunderbar;<br/>Gottes Empfinden gibt er uns,<br/>Geistliche Welt nimmt er nur wahr.<br/>',NULL,47497,4);
INSERT INTO stanza VALUES('G288','5','Dreiteilig unsre Seele ist,<br/>Wille, Verstand und auch Gefühl;<br/>Unsre Natur zum Ausdruck kommt<br/>Durch die Funktionen unsrer Seel.<br/>',NULL,47498,5);
INSERT INTO stanza VALUES('G288','6','Dreiteilig ist auch unser Geist:<br/>Eingebung und Gemeinschaftssinn,<br/>Auch das Gewissen ist ein Teil,<br/>Anbeten wolln wir Gott durch ihn.<br/>',NULL,47499,6);
INSERT INTO stanza VALUES('G288','7','Üben muss der Mensch die Seel,<br/>Um Gott zu wählen zum Besitz,<br/>Sein Geist hat Anteil nun an Gott,<br/>Sein Leib dem Herrn zum Ausdruck ist.<br/>',NULL,47500,7);
INSERT INTO stanza VALUES('G288','8','Wiedergeboren wird der Geist,<br/>Wenn Gottes Leben ihn erreicht;<br/>Nun wandelt Gott die Seele um,<br/>Bis der Leib dem des Sohnes gleicht.<br/>',NULL,47501,8);
INSERT INTO stanza VALUES('G288','9','Durch diese Schritte wirkt Sich Gott<br/>In alle drei Bereiche ein,<br/>So wird der Mensch mit Gott vermengt,<br/>Er soll Sein voller Ausdruck sein.<br/>',NULL,47502,9);
INSERT INTO stanza VALUES('G289','1','Als Gefäß schuf uns der Schöpfer,<br/>Das Ihn auslebt, Ihm anhängt;<br/>Er gab uns ein Herz zum Lieben,<br/>Einen Geist, der Gott empfängt.<br/>',NULL,47503,1);
INSERT INTO stanza VALUES('G289','2','Unser Herz muss Gott stets lieben,<br/>Unser Geist nimmt Ihn stets ein,<br/>Ihn genießen wir als Leben,<br/>Wollen nur Sein Ausdruck sein.<br/>',NULL,47504,2);
INSERT INTO stanza VALUES('G289','3','Satan hat das Herz verdorben,<br/>Und getötet unsren Geist,<br/>Dass wir nicht den Herrn berühren,<br/>Alles nur ums Selbst sich kreist.<br/>',NULL,47505,3);
INSERT INTO stanza VALUES('G289','4','Doch Gott hat durch Seine Rettung<br/>Herz und Geist ganz neu gemacht,<br/>Die Funktionen Ihn zu lieben,<br/>Zu empfangen neu entfacht.<br/>',NULL,47506,4);
INSERT INTO stanza VALUES('G289','5','Unser neues Herz will folgen<br/>Voller Liebe Gott, dem Herrn;<br/>In der Neuheit unsres Geistes<br/>Kontaktieren wir Gott gern.<br/>',NULL,47507,5);
INSERT INTO stanza VALUES('G289','6','Unser Herz vor Gott muss bleiben<br/>Rein, einfältig und so wahr;<br/>Arm im Geist lasst Ihn uns suchen,<br/>Ihn berühren immerdar.<br/>',NULL,47508,6);
INSERT INTO stanza VALUES('G289','7','Unser Herz Dich stets frisch liebe,<br/>Stärke unsren Geist, o Herr!<br/>In der Neuheit unsres Geistes<br/>Lehr uns Dich berühren mehr.<br/>',NULL,47509,7);
INSERT INTO stanza VALUES('G290','1','In allem Umgang mit dem Herrn<br/>Brauch ich ein rechtes Herz;<br/>Dann wird mir Gnade reich zuteil,<br/>Sein Reichtum wird beschert.<br/>',NULL,47510,1);
INSERT INTO stanza VALUES('G290','2','Ich brauch so sehr ein reines Herz,<br/>Einen Verstand so klar,<br/>Dass ich mit Furcht und Zittern nehm<br/>Gottes Gedanken wahr.<br/>',NULL,47511,2);
INSERT INTO stanza VALUES('G290','3','Ich brauch ein Herz, das glüht für Gott,<br/>Das voller Liebe brennt,<br/>Und ein Gefühl, voll Innigkeit,<br/>Dass keine Lauheit kennt.<br/>',NULL,47512,3);
INSERT INTO stanza VALUES('G290','4','Ich brauch ein Herz, das gern gehorcht,<br/>Willig Sein Wort nimmt an;<br/>Biegsam, doch stark mein Wille sei,<br/>Dienlich für Gottes Plan.<br/>',NULL,47513,4);
INSERT INTO stanza VALUES('G290','5','Ich brauch ein Herz, das nicht verdammt,<br/>Frieden mit Gott genießt,<br/>Und ein Gewissen, dass durchs Blut<br/>Rein und bedeckt auch ist.<br/>',NULL,47514,5);
INSERT INTO stanza VALUES('G290','6','Herr, schenk uns solch ein rechtes Herz,<br/>Ein Herz für Dich allein;<br/>So haben wir an Dir Selbst teil,<br/>Um Deine Füll zu sein.<br/>',NULL,47515,6);
INSERT INTO stanza VALUES('G291','1','Grabe weg, grabe weg, grabe weg,<br/>Schuldgefühle grab in meinem Herzen weg!<br/>Grabe weg, grabe weg, grabe weg,<br/>Schuldgefühle grab in meinem Herzen weg!<br/>',NULL,47516,1);
INSERT INTO stanza VALUES('G291','chorus','Jede Schuld muss gehn sodann,<br/>Dass Sein Leben fließen kann...Halleluja!<br/>Grabe weg, grabe weg, grabe weg,<br/>Schuldgefühle grab in meinem Herzen weg!<br/>',NULL,47517,2);
INSERT INTO stanza VALUES('G291','2','Grabe weg, grabe weg, grabe weg,<br/>Im Verstand grab alle Nichtigkeiten weg!<br/>Grabe weg, grabe weg, grabe weg,<br/>Im Verstand grab alle Nichtigkeiten weg!<br/>',NULL,47518,3);
INSERT INTO stanza VALUES('G291','chorus','Jeder Traum muss gehn sodann,<br/>Dass Sein Leben fließen kann...Halleluja!<br/>Grabe weg, grabe weg, grabe weg,<br/>Im Verstand grab alle Nichtigkeiten weg!<br/>',NULL,47519,4);
INSERT INTO stanza VALUES('G291','3','Grabe weg, grabe weg, grabe weg,<br/>Meine lästigen Gefühle grabe weg!<br/>Grabe weg, grabe weg, grabe weg,<br/>Meine lästigen Gefühle grabe weg!<br/>',NULL,47520,5);
INSERT INTO stanza VALUES('G291','chorus','Eigenlieb muss gehn sodann,<br/>Dass Sein Leben fließen kann...Halleluja!<br/>Grabe weg, grabe weg, grabe weg,<br/>Meine lästigen Gefühle grabe weg!<br/>',NULL,47521,6);
INSERT INTO stanza VALUES('G291','4','Grabe weg, grabe weg, grabe weg,<br/>Widerstand in meinem Willen grabe weg!<br/>Grabe weg, grabe weg, grabe weg,<br/>Widerstand in meinem Willen grabe weg!<br/>',NULL,47522,7);
INSERT INTO stanza VALUES('G291','chorus','Eigenwilln muss gehn sodann,<br/>Dass Sein Leben fließen kann...Halleluja!<br/>Grabe weg, grabe weg, grabe weg,<br/>Widerstand in meinem Willen grabe weg!<br/>',NULL,47523,8);
INSERT INTO stanza VALUES('G291','5','Grabe weg, grabe weg, grabe weg,<br/>Jede Selbstsucht meines Herzens grabe weg!<br/>Grabe weg, grabe weg, grabe weg,<br/>Jede Selbstsucht meines Herzens grabe weg!<br/>',NULL,47524,9);
INSERT INTO stanza VALUES('G291','chorus','Eigne Wahl muss gehn sodann,<br/>Dass Sein Leben fließen kann...Halleluja!<br/>Grabe weg, grabe weg, grabe weg,<br/>Jede Selbstsucht meines Herzens grabe weg!<br/>',NULL,47525,10);
INSERT INTO stanza VALUES('G291','6','Leben fließt, lobt den Herrn, Leben fließt!<br/>Aus dem Brunnen meines Herzens Leben fließt!<br/>Leben fließt, lobt den Herrn, Leben fließt!<br/>Aus dem Brunnen meines Herzens Leben fließt!<br/>',NULL,47526,11);
INSERT INTO stanza VALUES('G291','chorus','Wenn mein Herz ganz frei ist, dann<br/>Durch mich Christus fließen kann...Halleluja!<br/>Leben fließt, lobt den Herrn, Leben fließt!<br/>Aus dem Brunnen meines Herzens Leben fließt!<br/>',NULL,47527,12);
INSERT INTO stanza VALUES('G292','1','Heute bist Du der Geist, o Herr,<br/>In unsrem Geist Du bist;<br/>Beide vermengt, ein Geist nun sind,<br/>Welch Einheit in uns ist!<br/>',NULL,47528,1);
INSERT INTO stanza VALUES('G292','2','Dein Geist mit unsrem Geist, o Herr,<br/>Zeugnis gibt allezeit,<br/>Dass wir des Vaters Kinder sind,<br/>Erben der Herrlichkeit.<br/>',NULL,47529,2);
INSERT INTO stanza VALUES('G292','3','Ja, Deinen Reichtum schmecken wir,<br/>Ist unser Geist geübt;<br/>Du als der Geist Dich Selbst uns gibst,<br/>Jederzeit, ungetrübt.<br/>',NULL,47530,3);
INSERT INTO stanza VALUES('G292','4','In unsrem Geist gehn wir voran,<br/>Folgen Dir allezeit;<br/>Du als der Geist uns führst ins Licht,<br/>In Deine Herrlichkeit.<br/>',NULL,47531,4);
INSERT INTO stanza VALUES('G292','5','In unsrem Geist durch Deinen Geist<br/>Leben und loben wir;<br/>Durch Deinen Geist in unsrem Geist<br/>Stärkst uns mit Kraft von Dir.<br/>',NULL,47532,5);
INSERT INTO stanza VALUES('G292','6','In unsrem Geist mit Deinem Geist<br/>Beten wir, Herr, zu Dir;<br/>Du als der Geist stehst ein in uns,<br/>Seufzt unaussprechlich hier.<br/>',NULL,47533,6);
INSERT INTO stanza VALUES('G292','7','Zu unsrem Geist wir wenden uns,<br/>Deinen wir hier berührn;<br/>Dein reiches Erbteil schmecken wir,<br/>Göttliche Freude spürn.<br/>',NULL,47534,7);
INSERT INTO stanza VALUES('G292','8','Oh! Welche Einheit schenkst Du uns –<br/>Zwei Geister einverleibt!<br/>Dein Geist in unsrem Geist lebt nun,<br/>Unsrer in Deinem bleibt.<br/>',NULL,47535,8);
INSERT INTO stanza VALUES('G293','1','Herr, lass uns stets den Geist erkennen,<br/>Von Seele unterscheiden mehr;<br/>Du bist der Geist in unsrem Geiste,<br/>Vermengt mit uns in Einheit, Herr.<br/>',NULL,47536,1);
INSERT INTO stanza VALUES('G293','2','Herr, lass uns stets den Geist erkennen,<br/>Verleugnen Seelen-Leben ganz;<br/>Dir immer folgend, Herr, im Geiste,<br/>Dich wenden wir, den Geist, stets an.<br/>',NULL,47537,2);
INSERT INTO stanza VALUES('G293','3','Herr, lass uns stets den Geist erkennen,<br/>Aufs Fleisch nie setzen den Verstand,<br/>Vielmehr nur auf den Geist, hinfort nun<br/>Frei, wo einst Selbst und Sünde band.<br/>',NULL,47538,3);
INSERT INTO stanza VALUES('G293','4','Herr, lass uns stets den Geist erkennen,<br/>Damit wir niemals seelisch sind,<br/>Doch wahrlich geistlich, unterscheidend<br/>Klar alle Dinge nun forthin.<br/>',NULL,47539,4);
INSERT INTO stanza VALUES('G293','5','Herr, lass uns stets den Geist erkennen,<br/>Stell bloß das trügerische Ich;<br/>Das Kreuz drauf anwendend, nun leben<br/>Wir nicht durch uns und nur durch Dich.<br/>',NULL,47540,5);
INSERT INTO stanza VALUES('G293','6','Herr, lass uns stets den Geist erkennen,<br/>Dass umgewandelt sei die Seel,<br/>Bis Deinem Bild wir gleichgestaltet,<br/>Und kommen, ausgereift, zum Ziel.<br/>',NULL,47541,6);
INSERT INTO stanza VALUES('G293','7','Herr, lass uns stets den Geist erkennen,<br/>Gib uns doch Dein lebendges Wort,<br/>Das wirksam Geist und Seele scheidet,<br/>Im Heiligsten zum Leben dort.<br/>',NULL,47542,7);
INSERT INTO stanza VALUES('G294','1','Im Tempel ist das Heiligste<br/>Der Gnadenstuhl im Innersten,<br/>Die Bundeslade stehet da,<br/>Und dort sich Gott und Priester sehn.<br/>',NULL,47543,1);
INSERT INTO stanza VALUES('G294','2','Mit dreien Teilen sind nun wir<br/>Der Tempel Gottes; unser Geist,<br/>Wo Gott und Christus als der Geist<br/>Jetzt wohnt, das Allerheil''gste ist.<br/>',NULL,47544,2);
INSERT INTO stanza VALUES('G294','3','In unsrem Innern, tief im Geist,<br/>Ist Gott in Christus reich allzeit;<br/>An diesem Ort macht Gottes Geist<br/>Den Herrn zu unsrer Wirklichkeit.<br/>',NULL,47545,3);
INSERT INTO stanza VALUES('G294','4','Im Geiste wohnen wir im Herrn,<br/>Und können Ihn berühren hier;<br/>Durch unsern Geist wir beten an,<br/>Mit Gott Gemeinschaft haben wir.<br/>',NULL,47546,4);
INSERT INTO stanza VALUES('G294','5','Im Geist ist Christus wie das Land<br/>In dem der Reichtum überfließt;<br/>Mit Christi Vollmacht kämpfen wir,<br/>Dass Gottes Feind gebunden ist.<br/>',NULL,47547,5);
INSERT INTO stanza VALUES('G294','6','Nach Geistes-Kenntnis suchen wir,<br/>Geist unterscheiden von der Seel;<br/>Im Allerheiligsten zu sein,<br/>Gelangen so zu Gottes Ziel.<br/>',NULL,47548,6);
INSERT INTO stanza VALUES('G294','7','Verleugnen wir die Seele stets,<br/>In Gottes Ruhe treten ein,<br/>Wird Christus uns ganz zum Besitz,<br/>Und Gottes Plan verwirklicht sein.<br/>',NULL,47549,7);
INSERT INTO stanza VALUES('G295','1','Dreieiner Gott, Dein Geist wohnt nun<br/>In unsrem Geist, wie wunderbar!<br/>Jetzt will Er durch uns fließen frei,<br/>Macht Gott in Christus offenbar.<br/>',NULL,47550,1);
INSERT INTO stanza VALUES('G295','2','Natürlich ist der äußre Mensch,<br/>Gefangen ist der Geist darin;<br/>Statt einer Wohnung wurden wir<br/>Zu einem Kerker nun für Ihn.<br/>',NULL,47551,2);
INSERT INTO stanza VALUES('G295','3','Als ein Gefäß aus Ton gemacht,<br/>Den Herrn als Schatz enthalten wir;<br/>Wenn das Gefäß zerbrochen ist,<br/>Verschafft der Schatz Sich Ausdruck hier.<br/>',NULL,47552,3);
INSERT INTO stanza VALUES('G295','4','Zerbrechen muss der Herr das Selbst,<br/>Der äußre Mensch stört Gottes Plan;<br/>So tu Dein Werk in uns, o Herr,<br/>Damit der Geist frei fließen kann.<br/>',NULL,47553,4);
INSERT INTO stanza VALUES('G295','5','Drum hält der Herr für uns bereit<br/>Ein Maß an Leiden und Verzicht;<br/>Umgebung ordnet für uns an,<br/>Uns so den äußren Menschen bricht.<br/>',NULL,47554,5);
INSERT INTO stanza VALUES('G295','6','Das Selbst, die Seele – äußrer Mensch –<br/>Vermindert und verzehret sei;<br/>Wird unser Geist – der innre Mensch –<br/>Mit Gottes Geist dann völlig frei.<br/>',NULL,47555,6);
INSERT INTO stanza VALUES('G295','7','Schenk heiliges Zerbrochensein<br/>Von meinem Ganzsein nun befrei;<br/>Verwundest Du die Seele tief,<br/>Bewirke, dass ich willig sei!<br/>',NULL,47556,7);
INSERT INTO stanza VALUES('G295','8','Für Dein Zerbrechen weck in mir<br/>Wertschätzung, dass ich klag nicht mehr;<br/>Gib, dass ich allerlei Verlust<br/>Anstatt Gewinn mehr schätze, Herr.<br/>',NULL,47557,8);
INSERT INTO stanza VALUES('G296','1','Gott will gleichgestalten alle<br/>Seinem erstgebornen Sohn;<br/>Darum wandelt uns Sein Geist um<br/>Und Er tut es heute schon.<br/>',NULL,47558,1);
INSERT INTO stanza VALUES('G296','chorus','Wandle uns, Herr, in Dein Bild um<br/>In Verstand, Gefühl und Willn;<br/>Mög Dein Geist, Herr, uns durchdringen,<br/>Unser ganzes Sein erfülln.<br/>',NULL,47559,2);
INSERT INTO stanza VALUES('G296','2','Gott hat uns mit Seinem Leben<br/>Neu geborn in unsrem Geist;<br/>Unsre Seele wandelt Er um<br/>Durch Sein Leben, das uns speist.<br/>',NULL,47560,3);
INSERT INTO stanza VALUES('G296','3','Gott geht stets von unsrem Geist aus,<br/>Wandelt unsre Seele um;<br/>Er erneuert innre Teile,<br/>Bis Er uns regiert rundum.<br/>',NULL,47561,4);
INSERT INTO stanza VALUES('G296','4','Durch die Kraft des Geistes wandelt<br/>Er uns um in Gottes Bild;<br/>Uns von Herrlichkeit zu Herrlichkeit<br/>Gleich zu machen ist gewillt.<br/>',NULL,47562,5);
INSERT INTO stanza VALUES('G296','5','Er verwandelt, alles heiligt,<br/>Bis wir reif sind und Ihm gleich;<br/>Unsre Seele Er durchsättigt,<br/>Bis Sein Wuchs ist ganz erreicht.<br/>',NULL,47563,6);
INSERT INTO stanza VALUES('G297','1','In Deiner Gegenwart, Herr, bin ich still,<br/>Dass ich im Tiefsten komm in Deine Näh;<br/>Nicht meiner Art nach bete ich zu Dir,<br/>Lass Dein Gebet das meine sein vielmehr.<br/>',NULL,47564,1);
INSERT INTO stanza VALUES('G297','2','Dem Anschein nach hörst Du vom Himmel her,<br/>Doch tief in meinem Geist wohnst Du vielmehr;<br/>Es scheint, dass ich selbst fleh und bet zu Dir,<br/>Doch mein Gebet quillt ganz aus Dir, o Herr.<br/>',NULL,47565,2);
INSERT INTO stanza VALUES('G297','3','Wenn im Gebet ich keine Worte find,<br/>Seufzt tief mein Geist mit Deinem Geist zu Dir;<br/>Wenn ohne Worte meine Bitten sind,<br/>Dann betest Du geheimnisvoll in mir.<br/>',NULL,47566,3);
INSERT INTO stanza VALUES('G297','4','Einatmen will ich Dich, dem Atem gleich,<br/>Als die Versorgung, essen, trinken Dich;<br/>Tiefre Gemeinschaft schenk mir Herr mit Dir,<br/>Bis Du zum Ausdruck kommst so reich durch mich.<br/>',NULL,47567,4);
INSERT INTO stanza VALUES('G297','5','In der Gemeinschaft leuchtet mich Dein Licht,<br/>Dein teures Blute wäscht und macht mich rein;<br/>Möge ich, Herr, Dein Licht nicht nur bewahrn,<br/>Vielmehr Dein Ausdruck soll durch mich hell schein''n.<br/>',NULL,47568,5);
INSERT INTO stanza VALUES('G297','6','Dein Salböl salbt mich hier auf jede Art,<br/>Drinnen Dich salbt es, ohne Unterlass;<br/>Ich nehme ab, Du nehme täglich zu,<br/>Bis Deinen Ausdruck, Herr, durch mich Du hast.<br/>',NULL,47569,6);
INSERT INTO stanza VALUES('G297','7','Ich öffne mich, so fließt Du, Herr, hinein,<br/>Andern geöffnet, fließe, Herr, heraus;<br/>Durch diesen Strom, Gemeinschaft innerlich,<br/>Drückst Du Dich durch mein Leben völlig aus.<br/>',NULL,47570,7);
INSERT INTO stanza VALUES('G298','1','Uns beten lehre, dass der Feind<br/>Uns flüchte in die Weit,<br/>Die böse Macht gebunden sei,<br/>Gefangene befreit.<br/>',NULL,47571,1);
INSERT INTO stanza VALUES('G298','2','Uns beten lehre, und zu stehn<br/>Fest, standhaft in der Schlacht,<br/>Die Festung niederreißen, dass<br/>Der Feind zu Fall gebracht.<br/>',NULL,47572,2);
INSERT INTO stanza VALUES('G298','3','Uns beten lehre, Deinen Stab<br/>Stark üben im Gebet,<br/>Das, mit dem Blut bedeckt, die Erd<br/>Und Macht der Luft bewegt.<br/>',NULL,47573,3);
INSERT INTO stanza VALUES('G298','4','Durch Glauben und Gebet, o Herr,<br/>Bring uns Dein Werk doch nah'',<br/>Zu wissen, dass der Sieg uns ist,<br/>Und Deine Vollmacht gar.<br/>',NULL,47574,4);
INSERT INTO stanza VALUES('G299','1','Dort im Allerheiligsten,<br/>Hinterm Vorhang möcht ich sein;<br/>Dort den Gnadenthron berühr,<br/>Leben stärkt und nimmt mich ein.<br/>',NULL,47575,1);
INSERT INTO stanza VALUES('G299','2','Mein Geist ist das Heiligste,<br/>Worin reich das Leben fließt;<br/>Christus wohnt hier ewiglich,<br/>Eins mein Geist mit Seinem ist.<br/>',NULL,47576,2);
INSERT INTO stanza VALUES('G299','3','Wend ich mich zu meinem Geist,<br/>Gott, dem Herrn, begegne hier;<br/>Oh, wie wunderbar und süß!<br/>Ganz und gar ist Er in mir.<br/>',NULL,47577,3);
INSERT INTO stanza VALUES('G299','4','Wenn in meinem Geist ich bet,<br/>Auferstehungsduft verbreit,<br/>So wird Christus ausgestellt,<br/>Andre Glieder auch befreit.<br/>',NULL,47578,4);
INSERT INTO stanza VALUES('G299','5','Wenn ich Ihn im Geist berühr,<br/>Dann erfüllt Sein Reichtum mich;<br/>Leben, Liebe, Gnade, Licht,<br/>Wie ein Strom ergießen sich.<br/>',NULL,47579,5);
INSERT INTO stanza VALUES('G299','6','Tief und sanft berühr ich Ihn<br/>Und erfahr Ihn wunderbar,<br/>Das Gesetz des Lebens so<br/>Und die Salbung nehm ich wahr.<br/>',NULL,47580,6);
INSERT INTO stanza VALUES('G299','7','Tiefer noch in meinem Geist<br/>Meinen Herrn ich hier berühr;<br/>In den Tiefen, Herr, wirst Du<br/>Manna im Verborgnen mir.<br/>',NULL,47581,7);
INSERT INTO stanza VALUES('G299','8','Wird in mir das Leben der<br/>Auferstehung nun wirklich,<br/>So wie Aarons Stab, der blüht,<br/>Angenommen werde ich.<br/>',NULL,47582,8);
INSERT INTO stanza VALUES('G299','9','Hier den Gnadenthron ich find,<br/>Wo Sein Leben herrlich fließt;<br/>Voller Gnade ist der Strom,<br/>In mein Innres sich ergießt.<br/>',NULL,47583,9);
INSERT INTO stanza VALUES('G299','10','Treffen wir dann zum Gebet,<br/>Alle ihren Geist befrein,<br/>Als vermengte Priesterschaft<br/>Dienen wir dem Herrn allein.<br/>',NULL,47584,10);
INSERT INTO stanza VALUES('G299','11','Hier im Allerheiligsten,<br/>Jeder Dich, o Herr, genießt;<br/>Bleiben wir vor Deinem Thron,<br/>Auf uns reichlich Gnade fließt.<br/>',NULL,47585,11);
INSERT INTO stanza VALUES('G300','1','An dem heil''gsten Ort, Gnade finde dort,<br/>Gnade fließt vom Thron wie ein Strom;<br/>An dem heil''gsten Ort, Gnade finde dort,<br/>Gnade fließt vom Thron wie ein Strom.<br/>',NULL,47586,1);
INSERT INTO stanza VALUES('G300','chorus','Halleluja! Halleluja!<br/>Gnade fließt vom Thron wie ein Strom;<br/>Halleluja! Halleluja!<br/>Gnade fließt vom Thron wie ein Strom.<br/>',NULL,47587,2);
INSERT INTO stanza VALUES('G300','2','Im des Heil''gsten Licht seh Sein Angesicht,<br/>Herrlichkeit wird scheinen durch mich;<br/>Im des Heil''gsten Licht seh Sein Angesicht,<br/>Herrlichkeit wird scheinen durch mich.<br/>',NULL,47588,3);
INSERT INTO stanza VALUES('G300','chorus','Halleluja! Halleluja!<br/>Herrlichkeit wird scheinen durch mich;<br/>Halleluja! Halleluja!<br/>Herrlichkeit wird scheinen durch mich.<br/>',NULL,47589,4);
INSERT INTO stanza VALUES('G300','3','Dich zum Geiste wend, und der Weihrauch brennt,<br/>Komm, die Lebensquelle berühr;<br/>Dich zum Geiste wend, und der Weihrauch brennt,<br/>Komm, die Lebensquelle berühr.<br/>',NULL,47590,5);
INSERT INTO stanza VALUES('G300','chorus','Halleluja! Halleluja!<br/>Komm, die Lebensquelle berühr;<br/>Halleluja! Halleluja!<br/>Komm, die Lebensquelle berühr.<br/>',NULL,47591,6);
INSERT INTO stanza VALUES('G301','1','Zerrissen ist der Vorhang schon,<br/>Frei ist ein neuer Weg;<br/>Durchs teure Blut kühn nahn wir uns,<br/>Und kommen zum Gebet.<br/>',NULL,47592,1);
INSERT INTO stanza VALUES('G301','2','Deine Erlösung Zutritt gibt<br/>Zum Allerheiligsten;<br/>Durch Deines Geistes Salbung stehn<br/>Wir vor dem Gnadenthron.<br/>',NULL,47593,2);
INSERT INTO stanza VALUES('G301','3','Allein im Geist, so beten wir,<br/>Nimm uns, o Herr, ganz ein,<br/>Dass unser Geist zum Ausdruck bringt<br/>Christus als Weihrauch fein.<br/>',NULL,47594,3);
INSERT INTO stanza VALUES('G301','4','Barmherzigkeit und Gnade strömt<br/>Aus Gottes Thron heraus;<br/>Wie sie erfrischt zur rechten Zeit –<br/>So reich tagein, tagaus!<br/>',NULL,47595,4);
INSERT INTO stanza VALUES('G301','5','Wir bitten nicht um was uns fehlt,<br/>Doch wie uns führt Dein Geist;<br/>Du kümmerst Dich ja immerzu,<br/>Und was wir brauchen, weißt.<br/>',NULL,47596,5);
INSERT INTO stanza VALUES('G301','6','Auch wenn uns allerlei bedrückt,<br/>Nimmt uns nicht Sorge ein;<br/>Wir werfen unsre Last auf Dich<br/>Und unsren Geist befrein.<br/>',NULL,47597,6);
INSERT INTO stanza VALUES('G301','7','Ich richte mich nun auf Dich aus<br/>In der Gemeinschaft sehr;<br/>Ich bring Gebet und Weihrauch dar,<br/>Dein Geist mich führt, o Herr.<br/>',NULL,47598,7);
INSERT INTO stanza VALUES('G302','1','Als erlöste Priesterschaft<br/>Beten wir einmütig, Herr;<br/>Suchen Deine Gegenwart,<br/>Auf Dich harren wir so sehr.<br/>',NULL,47599,1);
INSERT INTO stanza VALUES('G302','chorus','Hier zusammen beten wir,<br/>Um das Höchste zu berührn;<br/>Unsre Geister sind vermengt,<br/>So wird dies zum Aufbau führn.<br/>',NULL,47600,2);
INSERT INTO stanza VALUES('G302','2','Wir sind Deine Priester, Herr,<br/>Deinen Willn spürn wir im Geist;<br/>Dienen Dir für Deinen Plan,<br/>Den Du auszuführen weißt.<br/>',NULL,47601,3);
INSERT INTO stanza VALUES('G302','3','Hier im Allerheiligsten<br/>Fassen wir den Gnadenthron;<br/>Durchs Empfinden innerlich<br/>Folgen wir dem Lebensstrom.<br/>',NULL,47602,4);
INSERT INTO stanza VALUES('G302','4','Ströme voller Gnade hältst<br/>Du vom Thron für mich bereit;<br/>Herrlich wird mein Geist erfrischt,<br/>Was mir hilft zur rechten Zeit.<br/>',NULL,47603,5);
INSERT INTO stanza VALUES('G302','5','Was Dein Geist zu tun gedenkt,<br/>Betend unser Geist erkennt;<br/>Nicht für Eignes beten wir,<br/>Doch wonach Dein Herz sich sehnt.<br/>',NULL,47604,6);
INSERT INTO stanza VALUES('G302','6','Herr, obwohl uns vieles drückt,<br/>Und wir alles bringen Dir,<br/>Wollen wir doch so viel mehr<br/>Ein Kanal für Dich sein hier.<br/>',NULL,47605,7);
INSERT INTO stanza VALUES('G302','7','Neig uns zu Dein offnes Ohr,<br/>Uns mit Leben tränk und stärk;<br/>Wenn uns Deine Gnade füllt,<br/>Erst dann kennen wir Dein Werk.<br/>',NULL,47606,8);
INSERT INTO stanza VALUES('G303','1','„Tretet nun hinzu mit Freimut“,<br/>Ruft der Herr zum heil''gsten Ort;<br/>Herrlichkeit in Seinem Antlitz<br/>Schauen wir, die hell strahlt dort.<br/>',NULL,47607,1);
INSERT INTO stanza VALUES('G303','chorus','Kommt zum Heiligsten hinzu nun<br/>Durch des Räucherwerks Gebet;<br/>Fort der Vorhang ist, der trennte,<br/>Freimütig hinein nun geht.<br/>',NULL,47608,2);
INSERT INTO stanza VALUES('G303','2','Durch den neuen Weg kommt vorwärts,<br/>In das Heiligste hinein;<br/>Herrlich offen ist der Eintritt,<br/>Und so wird''s für ewig sein.<br/>',NULL,47609,3);
INSERT INTO stanza VALUES('G303','3','Kommt hinzu zu unsrem Gott nun,<br/>Der auf Seinem Thron hier ruht;<br/>Frei der Weg zur Herrlichkeit ist<br/>Durch Sein Kreuz und durch Sein Blut.<br/>',NULL,47610,4);
INSERT INTO stanza VALUES('G303','4','Kommt hinzu zur Zeit der Neuheit,<br/>Kühn und sicher lasst uns sein;<br/>Wollt ihr Gottes Plan genießen,<br/>Zurückweichen darf nicht sein.<br/>',NULL,47611,5);
INSERT INTO stanza VALUES('G303','5','Nun zum Allerheiligsten sind<br/>Wir hinzugetreten frei;<br/>Du uns Gott bist, wir Dir Volk sind –<br/>Wie gesegnet ist''s dabei!<br/>',NULL,47612,6);
INSERT INTO stanza VALUES('G304','1','In dem mächt''gen Namen Jesu,<br/>Knien wir nieder vor den Thron,<br/>Wird dann manch ein Feind bezwungen,<br/>Tragen wir den Sieg davon.<br/>',NULL,47613,1);
INSERT INTO stanza VALUES('G304','chorus','Nur im Namen des Herrn<br/>Sind wir siegreich immerfort!<br/>In dem Namen des Herrn<br/>Sind besiegt die Sünd und Tod!<br/>',NULL,47614,2);
INSERT INTO stanza VALUES('G304','2','Bitten wir im Namen Jesu,<br/>Müssen Satans Heere fliehn.<br/>Jesus! Jesus! Teurer Jesus!<br/>Lässt von Sieg zu Sieg uns ziehn.<br/>',NULL,47615,3);
INSERT INTO stanza VALUES('G304','3','Bald schon ist der Kampf gewonnen,<br/>Siegesfreude uns entzückt,<br/>Wenn der starke Name Jesu<br/>Uns zu Seinem Thron entrückt.<br/>',NULL,47616,4);
INSERT INTO stanza VALUES('G305','1','Betet einmütig im Geiste,<br/>So wie es der Herr begehrt,<br/>Nicht nach eigenem Verständnis,<br/>Sondern wie die Salbung lehrt.<br/>',NULL,47617,1);
INSERT INTO stanza VALUES('G305','chorus','Betet einmütig im Geiste,<br/>So wie es der Herr begehrt,<br/>Nicht nach eigenem Verständnis,<br/>Sondern wie die Salbung lehrt.<br/>',NULL,47618,2);
INSERT INTO stanza VALUES('G305','2','Betet einmütig im Geiste,<br/>Lasst durchs Kreuz die Seele sein;<br/>Jeder Wunsch und jede Absicht<br/>Sei bestimmt vom Geist allein.<br/>',NULL,47619,3);
INSERT INTO stanza VALUES('G305','3','Betet einmütig im Geiste,<br/>Und vom Himmel betet her;<br/>Lasst die irdischen Interessen,<br/>Gegen Mächte kämpft vielmehr.<br/>',NULL,47620,4);
INSERT INTO stanza VALUES('G305','4','Betet einmütig im Geiste,<br/>Aufeinander abgestimmt;<br/>Sucht das Leiten Seines Geistes,<br/>Bis euch Harmonie einnimmt.<br/>',NULL,47621,5);
INSERT INTO stanza VALUES('G305','5','Betet einmütig im Geiste,<br/>Und harrt aus, ermattet nie;<br/>Eilt zu Gottes Königreich hin,<br/>Betet, wacht in Harmonie.<br/>',NULL,47622,6);
INSERT INTO stanza VALUES('G305','6','Betet einmütig im Geiste,<br/>Sucht in Einheit Ihn allein;<br/>Betet stets im Geist des Leibes,<br/>Bis sich Harmonie stellt ein.<br/>',NULL,47623,7);
INSERT INTO stanza VALUES('G306','1','Bete immer nur im Geiste,<br/>Nie im Fleisch, noch im Verstand!<br/>Gottes Gegenwart zu finden,<br/>Wende diesen Schlüssel an!<br/>',NULL,47624,1);
INSERT INTO stanza VALUES('G306','chorus','Bete immer nur im Geiste,<br/>Wende doch den Schlüssel an!<br/>Üb den Geist, Gott so berühre,<br/>An den Schlüssel halt dich dran!<br/>',NULL,47625,2);
INSERT INTO stanza VALUES('G306','2','Bete immer nur im Geiste,<br/>Nicht nach deinem eignen Sinn!<br/>Nur so führt uns Gott der Geist stets<br/>In Gemeinschaft mit Sich hin.<br/>',NULL,47626,3);
INSERT INTO stanza VALUES('G306','3','Bete immer nur im Geiste,<br/>Seinen Herzenswunsch zu kenn''n;<br/>Mit dem Herrn im Geist verweile,<br/>Bis dein Herz beginnt zu brenn''n.<br/>',NULL,47627,4);
INSERT INTO stanza VALUES('G306','4','Bete immer nur im Geiste,<br/>Wenn auch seufzend von tief drin;<br/>Gottes Absicht wir bekunden<br/>Durch des Geistes Disziplin.<br/>',NULL,47628,5);
INSERT INTO stanza VALUES('G306','5','Bete immer nur im Geiste<br/>In dem Allerheiligsten;<br/>Es ist nur im Geist, dass wir und<br/>Gott in Einheit immer stehn.<br/>',NULL,47629,6);
INSERT INTO stanza VALUES('G306','6','Bete immer nur im Geiste,<br/>Nur auf die Art betet man;<br/>Gottes Fülle wird dich füllen,<br/>Darum wend den Schlüssel an!<br/>',NULL,47630,7);
INSERT INTO stanza VALUES('G307','1','Übe deinen Geist recht,<br/>Bleibe im Gebet!<br/>Noch mein Geist nicht kühn ist,<br/>Da ich wenig bet.<br/>Auch wenn ich dann bete,<br/>Spricht mein Geist kaum mit;<br/>Gottes Geist bewegt Sich,<br/>Doch mein Geist folgt nicht.<br/>',NULL,47631,1);
INSERT INTO stanza VALUES('G307','2','Ich bet nun im Geiste,<br/>Seufze wie Dein Geist,<br/>Wie die Salbung leitet<br/>Und mich unterweist.<br/>Nicht Verstand nur folgend,<br/>Doch im Geist''s gebührt;<br/>Preis ich oder flehe,<br/>Wie Dein Geist mich führt.<br/>',NULL,47632,2);
INSERT INTO stanza VALUES('G307','3','Nicht allein ich bete,<br/>Übe meinen Geist;<br/>Doch mit andern bet ich,<br/>Was mich stärkt und speist.<br/>Stets im Geist ich bete,<br/>So der Geist verlangt''s;<br/>In mir gibt Sein Geist nun<br/>Tiefe Resonanz.<br/>',NULL,47633,3);
INSERT INTO stanza VALUES('G307','4','Dienen wir zusammen,<br/>Geht''s Gebet voraus,<br/>Dann fließt die Gemeinschaft<br/>Reich im Geist heraus.<br/>Betet nicht zusammen,<br/>– Schreien hilft auch nicht –<br/>Ohne zu berührn den<br/>Geist des Herrn im Licht.<br/>',NULL,47634,4);
INSERT INTO stanza VALUES('G307','5','Übe deinen Geist stets,<br/>Hier und überall,<br/>Auch in kleinen Treffen,<br/>Üb in jedem Fall.<br/>Denn kein Ort soll hindern,<br/>Auch nicht die Person,<br/>Allerorts mein Geist sei<br/>Völlig in Funktion.<br/>',NULL,47635,5);
INSERT INTO stanza VALUES('G307','6','Mein erweckter Geist auf<br/>Christus hört jetzt gern,<br/>Und so werd ich nützlich<br/>Sein für meinen Herrn.<br/>Fließen will mein Geist nun,<br/>Leben teilen aus;<br/>Dies vermengt uns Glieder,<br/>Auferbaut Sein Haus.<br/>',NULL,47636,6);
INSERT INTO stanza VALUES('G308','1','Wie geheimnisvoll, o Herr,<br/>Dein Geist wohnt in meinem Geist!<br/>Oh, wie herrlich, wunderbar,<br/>Denn die zwei sind nun ein Geist!<br/>',NULL,47637,1);
INSERT INTO stanza VALUES('G308','2','Ich kann wandeln durch den Geist,<br/>Im Geist kann ich geistlich sein;<br/>Durch den Geist Dir diene ich,<br/>Bet ich an im Geist allein.<br/>',NULL,47638,2);
INSERT INTO stanza VALUES('G308','3','Durch Dein Wort und mein Gebet<br/>Kann ich Dich im Geist berührn;<br/>So mein Geist erhoben wird,<br/>Und gestärkt, das kann ich spürn.<br/>',NULL,47639,3);
INSERT INTO stanza VALUES('G308','4','Stärke meinen Geist doch jetzt,<br/>Dass er andre stärkt im Lauf;<br/>Frisch und frei mein Geist stets sei,<br/>Andre Geister richtet auf.<br/>',NULL,47640,4);
INSERT INTO stanza VALUES('G308','5','Immer wenn ich rede, Herr,<br/>Soll mein Geist der Antrieb sein;<br/>Und in allem, was ich tu,<br/>Soll mein Geist mich führn allein.<br/>',NULL,47641,5);
INSERT INTO stanza VALUES('G308','6','Immer wenn mein Geist agiert,<br/>Mögen andere öffnen sich;<br/>Immer wenn mein Geist sich regt,<br/>Sollen andere spüren Dich.<br/>',NULL,47642,6);
INSERT INTO stanza VALUES('G308','7','Schenk Barmherzigkeit, o Herr,<br/>Hauche Deinen Geist in mich;<br/>Reich gefüllt mein Geist wird sein,<br/>Voller Kraft, erfrischt durch Dich.<br/>',NULL,47643,7);
INSERT INTO stanza VALUES('G309','1','Im Gebet berühr den Thron,<br/>Komm zum Gnadenthron und find<br/>Gnade und Barmherzigkeit,<br/>Die dir eine Hilfe sind.<br/>',NULL,47644,1);
INSERT INTO stanza VALUES('G309','2','Im Gebet berühr den Thron,<br/>Spür, wie du die Gnade brauchst;<br/>In Gemeinschaft bleib mit Gott,<br/>Wenn du in den Geist eintauchst.<br/>',NULL,47645,2);
INSERT INTO stanza VALUES('G309','3','Im Gebet berühr den Thron,<br/>Lern der Gnade Reichtum voll;<br/>Nimm und schmeck so frei davon,<br/>Dafür Dank und Lob Gott zoll.<br/>',NULL,47646,3);
INSERT INTO stanza VALUES('G309','4','Im Gebet berühr den Thron,<br/>Gottes Thron der Kraft berühr,<br/>Dass in Jesu Namen du<br/>Weißt, die Sachen auszuführn.<br/>',NULL,47647,4);
INSERT INTO stanza VALUES('G309','5','Im Gebet berühr den Thron,<br/>Geh mit Glauben in die Schlacht;<br/>Übe deine Vollmacht aus<br/>Über jede Todesmacht.<br/>',NULL,47648,5);
INSERT INTO stanza VALUES('G309','6','Im Gebet berühr den Thron,<br/>Nimm der bösen Macht den Grund;<br/>Bet als König auf dem Thron,<br/>Bet mit Christus diese Stund.<br/>',NULL,47649,6);
INSERT INTO stanza VALUES('G310','1','Für Gemeinschaft bet zu Jesus,<br/>Such im Geist Sein Angesicht;<br/>Seine Gegenwart genieße,<br/>Hör im Stillen, was Er spricht.<br/>',NULL,47650,1);
INSERT INTO stanza VALUES('G310','chorus','Für Gemeinschaft bet zu Jesus,<br/>Such im Geist Sein Angesicht;<br/>Seine Gegenwart genieße,<br/>Hör im Stillen, was Er spricht.<br/>',NULL,47651,2);
INSERT INTO stanza VALUES('G310','2','Für Gemeinschaft bet zu Jesus,<br/>Offne Ihm Dein ganzes Sein,<br/>Und mit aufgedecktem Antlitz<br/>Schau Ihn, einfach, echt und rein.<br/>',NULL,47652,3);
INSERT INTO stanza VALUES('G310','3','Für Gemeinschaft bet zu Jesus,<br/>Ihm in allem stets vertrau;<br/>Ihn als Geist lern zu berühren,<br/>Und in Ehrfurcht auf Ihn schau.<br/>',NULL,47653,4);
INSERT INTO stanza VALUES('G310','4','Für Gemeinschaft bet zu Jesus,<br/>Echt und froh Ihn kontaktier;<br/>Deinem Geist entsprechend bete,<br/>Durchs Empfinden tief in dir.<br/>',NULL,47654,5);
INSERT INTO stanza VALUES('G310','5','Für Gemeinschaft bet zu Jesus,<br/>Höre ernsthaft, was Er will;<br/>Lass dir zeigen Seine Absicht,<br/>Gib dich hin und folg Ihm still.<br/>',NULL,47655,6);
INSERT INTO stanza VALUES('G310','6','Für Gemeinschaft bet zu Jesus,<br/>Bad in Seinem Angesicht;<br/>Seine Schönheit dich durchsättigt,<br/>So erstrahlst du hell Sein Licht.<br/>',NULL,47656,7);
INSERT INTO stanza VALUES('G311','1','Stellt den Herrn durchs Beten aus,<br/>Wir solln nicht der Ausdruck sein;<br/>Lasst den Herrn Sich offenbarn,<br/>Sein Wunsch präge in uns ein.<br/>',NULL,47657,1);
INSERT INTO stanza VALUES('G311','2','Stellt den Herrn durch Beten aus,<br/>Seine Absicht äußern wir;<br/>Eignes bringen wir zur Ruh,<br/>Uns Sein Denken fülle hier.<br/>',NULL,47658,2);
INSERT INTO stanza VALUES('G311','3','Stellt den Herrn durch Beten aus,<br/>Schaut den Herrn an allezeit;<br/>Reflektiert von innen her<br/>Ständig Seine Herrlichkeit.<br/>',NULL,47659,3);
INSERT INTO stanza VALUES('G311','4','Stellt den Herrn durch Beten aus,<br/>Christus, der in uns nun wohnt;<br/>Steht für uns bei Christus ein,<br/>Der im dritten Himmel thront.<br/>',NULL,47660,4);
INSERT INTO stanza VALUES('G311','5','Stellt den Herrn durch Beten aus,<br/>Nicht das Selbst soll tätig sein;<br/>Betet immer mit dem Herrn,<br/>Betet nur durch Ihn allein.<br/>',NULL,47661,5);
INSERT INTO stanza VALUES('G312','1','Bet und arbeit mit dem Herrn,<br/>Dies sei immer unser Stand;<br/>Durch Gebet von Ihm bewegt<br/>Von der Nabe bis zum Rand.<br/>',NULL,47662,1);
INSERT INTO stanza VALUES('G312','2','Bet und arbeit mit dem Herrn,<br/>Mach dich eins mit Ihm allein,<br/>Seinem Ziel und Vorsatz nun,<br/>Bis Sein Segen bricht herein.<br/>',NULL,47663,2);
INSERT INTO stanza VALUES('G312','3','Bet und arbeit mit dem Herrn,<br/>Ehrgeiz, Eigenwilln veracht,<br/>Lehne sie beständig ab,<br/>Bis Sein Vorsatz ist vollbracht.<br/>',NULL,47664,3);
INSERT INTO stanza VALUES('G312','4','Bet und arbeit mit dem Herrn,<br/>Lass den Herrn initiiern<br/>Jeden Plan und jedes Werk;<br/>Dann wird Er durch uns agiern.<br/>',NULL,47665,4);
INSERT INTO stanza VALUES('G312','5','Bet und arbeit mit dem Herrn,<br/>Bis das Rad sich dreht voran;<br/>Bet, bis die Gemeinde hier<br/>Seine Kraft ausstellen kann.<br/>',NULL,47666,5);
INSERT INTO stanza VALUES('G313','1','Harre auf Dich, Herr, harre auf Dich;<br/>Lass mich nun ruhn in Dir;<br/>Deinen Plan zeige mir,<br/>Dies bitt ich ernstlich hier –<br/>Harre auf Dich, harre auf Dich.<br/>',NULL,47667,1);
INSERT INTO stanza VALUES('G313','2','Harre auf Dich, Herr, harre auf Dich;<br/>Während ich vor Dir bleib,<br/>Mir Deinen Weg beschreib,<br/>Und im Gebet verbleib –<br/>Harre auf Dich, harre auf Dich.<br/>',NULL,47668,2);
INSERT INTO stanza VALUES('G313','3','Harre auf Dich, Herr, harre auf Dich;<br/>Dich nun vermeng mit mir,<br/>Bis ich, ganz eins mit Dir,<br/>Werde Dein Bild sein hier –<br/>Harre auf Dich, harre auf Dich.<br/>',NULL,47669,3);
INSERT INTO stanza VALUES('G313','4','Harre auf Dich, Herr, harre auf Dich;<br/>Möchte Dich mehr verstehn,<br/>Und Deinen Weg gern gehn,<br/>Lebensfrucht sollst Du sehn –<br/>Harre auf Dich, harre auf Dich.<br/>',NULL,47670,4);
INSERT INTO stanza VALUES('G313','5','Harre auf Dich, Herr, harre auf Dich;<br/>Liebster Herr, lehre mich,<br/>Denn mein Gebet soll Dich<br/>Ausstellen ewiglich –<br/>Harre auf Dich, harre auf Dich.<br/>',NULL,47671,5);
INSERT INTO stanza VALUES('G314','1','Alle Schrift ist der Atem Gottes wahr,<br/>In Worten ausgehaucht durch Gott den Geist;<br/>Göttliche Männer schrieben alles auf,<br/>Reichlich mit Gottes Fülle sie uns speist.<br/>',NULL,47672,1);
INSERT INTO stanza VALUES('G314','2','Sie ist der Atem Gottes als das Licht,<br/>Des klarer Strahl den Menschen ganz erhellt;<br/>Im Dunkeln scheint''s, dem Menschen leuchtet ein,<br/>Was er bedarf, wie''s um ihn ist bestellt.<br/>',NULL,47673,2);
INSERT INTO stanza VALUES('G314','3','Sie ist der Atem Gottes, Leben uns,<br/>Das uns gebiert, belebt die Toten neu;<br/>Gottes Natur legt sie in uns hinein,<br/>Wandelt uns um, macht unser Herz ganz neu.<br/>',NULL,47674,3);
INSERT INTO stanza VALUES('G314','4','Sie ist der Atem Gottes, Weisheit auch,<br/>Göttliche Kenntnis bringt dem Menschen bei;<br/>Sie weist den ew''gen Vorsatz unsres Herrn,<br/>Und die Vollbringung führt durch uns herbei.<br/>',NULL,47675,4);
INSERT INTO stanza VALUES('G314','5','Sie ist der Atem Gottes als die Kraft,<br/>Göttliche Kraft stärkt uns auf unsrer Bahn;<br/>Sie richtet Schwache und Zerbrochne auf,<br/>Dass sie erfüllen können Gottes Plan.<br/>',NULL,47676,5);
INSERT INTO stanza VALUES('G314','6','Sie atmen wir als Gottes Atem ein,<br/>Gott, unsren Anteil, oh, welch ein Genuss!<br/>Nehmen sie ein durchs Üben unsres Geists,<br/>Reichtum erfahren wir im Uberfluss.<br/>',NULL,47677,6);
INSERT INTO stanza VALUES('G315','1','Gottes lebend''ges Wort, Bild Gottes treu,<br/>Du bist der Inhalt des geschriebnen Worts;<br/>In Dir Gott trafen wir, in Fülle hier,<br/>Und in der Schrift Dich haben wir gehorcht.<br/>',NULL,47678,1);
INSERT INTO stanza VALUES('G315','2','Niemand hat Gott gesehn außer durch Dich,<br/>Ohne die Schrift wärst Du, Herr, kaum zu sehn;<br/>Du hast der Menschheit hier Gott kundgetan,<br/>Die Schrift lässt uns Dein Bild genau erstehn.<br/>',NULL,47679,2);
INSERT INTO stanza VALUES('G315','3','Gottes Verkörperung bist Du perfekt,<br/>Ein volles Bildnis gibt die Schrift von Dir;<br/>In Dir begreifen wir Gottes Bild wahr,<br/>Und durch die Schrift bist Du so wirklich mir.<br/>',NULL,47680,3);
INSERT INTO stanza VALUES('G315','4','Geist, der das Leben gibt, bist Du dazu,<br/>Herr, Du bist überdies der Geist im Wort;<br/>Komm ich zu Deinem Wort durch Deinen Geist,<br/>Göttliche Fülle springt zu mir hervor.<br/>',NULL,47681,4);
INSERT INTO stanza VALUES('G315','5','In Dir Gemeinschaft gibst Du mir mit Gott,<br/>Und durch die Schrift ernähr ich mich von Dir;<br/>Wenn ich Dein Wort studier und dazu bet,<br/>Dein Reichtum stillt all meinen Mangel mir.<br/>',NULL,47682,5);
INSERT INTO stanza VALUES('G315','6','Wenn ich Dein Wort studier, lehre mich, Herr,<br/>Dich zu berührn und üben meinen Geist,<br/>Dass als lebend''ges Wort Du durch die Schrift<br/>Täglich und reichlich mich als Manna speist.<br/>',NULL,47683,6);
INSERT INTO stanza VALUES('G316','1','Du bist das Wort und auch der Geist,<br/>In einem Geist verehrn wir Dich;<br/>Nun durch das Wort begreifen wir<br/>Und in dem Geist berührn Dich.<br/>',NULL,47684,1);
INSERT INTO stanza VALUES('G316','2','Mein Ein und Alles bist Du, Herr,<br/>Denn Du hast Dich vereint mit mir;<br/>Du kommst zu mir als Wort und Geist,<br/>Reich die Versorgung fließt von Dir.<br/>',NULL,47685,2);
INSERT INTO stanza VALUES('G316','3','Wenn Du das Wort nicht wärst, o Herr,<br/>Wie könntest Du Dich kundtun mir?<br/>Wärst Du als Gott doch nicht der Geist,<br/>Wie könnt'' ich Dich berühren hier?<br/>',NULL,47686,3);
INSERT INTO stanza VALUES('G316','4','Das Wort macht Dich mir offenbar,<br/>Es bringt mir Deine Kenntnis nah;<br/>Im Geist besteht Deine Substanz,<br/>Durch den ich Dich berühr fürwahr.<br/>',NULL,47687,4);
INSERT INTO stanza VALUES('G316','5','Du bist mein Leben, Licht und Weg,<br/>Mir Speise, Kraft, und Sicherheit;<br/>Das alles wird durchs Wort bekannt,<br/>Und ich erfahr es als den Geist.<br/>',NULL,47688,5);
INSERT INTO stanza VALUES('G316','6','Zum Ausdruck kommt Dein Wort in Schrift,<br/>Dein Geist, der mich nun innewohnt;<br/>Dein Wort ist Leben sowie Geist,<br/>Wenn es zu meinem Geiste kommt.<br/>',NULL,47689,6);
INSERT INTO stanza VALUES('G316','7','Den Heil''gen Geist muss ich berührn,<br/>Wenn ich Dein Wort verstehen will;<br/>Nicht nur verstehen im Verstand,<br/>Vielmehr im Geist, und beten viel.<br/>',NULL,47690,7);
INSERT INTO stanza VALUES('G316','8','Dein teures Wort ist mir so lieb,<br/>Gemeinschaft haben wir im Geist;<br/>Mein Herz freut sich an Deinem Wort,<br/>Mein Geist in Deinem Geist Dich preist.<br/>',NULL,47691,8);
INSERT INTO stanza VALUES('G317','1','Mein Herz ist hungrig und durstig mein Geist,<br/>Ich komm zu Dir für Versorgung so frei;<br/>Was ich auch brauche, allein bist nur Du,<br/>Hunger und Durst mir stillst Du nur allein.<br/>',NULL,47692,1);
INSERT INTO stanza VALUES('G317','chorus','Speis mich, Herr Jesus, tränk mich mit Dir,<br/>Still meinen Hunger, lösch meinen Durst;<br/>Flut mich mit Freud, sei die Lebenskraft mir,<br/>Still meinen Hunger, lösch meinen Durst.<br/>',NULL,47693,2);
INSERT INTO stanza VALUES('G317','2','Wasser und Brot, Herr, des Lebens bist Du.<br/>Nun meinen Geist reich beleb und begieß;<br/>Gern möcht ich essen und trinken von Dir,<br/>Dich durch mein Lesen und Beten genieß.<br/>',NULL,47694,3);
INSERT INTO stanza VALUES('G317','3','Du bist das Wort, Gottes Fülle in Dir,<br/>Geist bist Du, so dass Gott mein Leben sei;<br/>Dich, Herr, genieß ich als Speise im Wort,<br/>Du als der Geist bist mir Wasser so frei.<br/>',NULL,47695,4);
INSERT INTO stanza VALUES('G317','4','Du kamst als Speise vom Himmel herab,<br/>Um mich zu tränken, ließt schlagen Du Dich;<br/>Als unerschöpfliche Speise bist Du<br/>Und auch das Wasser des Lebens für mich.<br/>',NULL,47696,5);
INSERT INTO stanza VALUES('G317','5','Herr, in dem Wort bist Du Leben und Geist,<br/>Sodass durchs Wort ich von Dir mich ernähr;<br/>Du lebst in meinem Geist nun als der Geist,<br/>Sodass im Geist ich von Dir trinke, Herr.<br/>',NULL,47697,6);
INSERT INTO stanza VALUES('G317','6','Um zu genießen, nun komm ich zum Wort,<br/>Esse von Dir bis mein Hunger vergeht;<br/>Dir wend ich mich nun in meinem Geist zu,<br/>Trinke von Dir, bis kein Durst mehr besteht.<br/>',NULL,47698,7);
INSERT INTO stanza VALUES('G317','7','Essen und trinken, Herr Jesus, von Dir,<br/>Esse durch Lesen, und trink durch Gebet;<br/>Lesen und beten – so ess ich und trink,<br/>Beten und lesen – mein Geist aufersteht.<br/>',NULL,47699,8);
INSERT INTO stanza VALUES('G317','8','Hier, feste ich, liebster Herr, nun mit Dir,<br/>Reich tränkt Dein Geist und Dein Wort fiillt mich sehr;<br/>Sei Du mein herrliches Fest jeden Tag,<br/>Wie es noch niemand erfahren hat, Herr.<br/>',NULL,47700,9);
INSERT INTO stanza VALUES('G318','1','Ich komm zu Dir, o Herr,<br/>Es dürstet mich nach Dir;<br/>Von Dir ich ess, von Dir ich trink,<br/>In Dir mich ganz verlier.<br/>',NULL,47701,1);
INSERT INTO stanza VALUES('G318','2','Dein Angesicht zu sehn,<br/>Ist meines Herzens Schrei;<br/>Ich trinke sehnlich, Herr, von Dir,<br/>Mein Durst erlischt dabei.<br/>',NULL,47702,2);
INSERT INTO stanza VALUES('G318','3','Mein Herz erfreut''s, zu sehn<br/>Dein helles Angesicht;<br/>Hier will ich bleiben immerdar,<br/>Beständig schauen Dich.<br/>',NULL,47703,3);
INSERT INTO stanza VALUES('G318','4','In solch Gemeinschaft, Herr,<br/>Bist Du die Gnade mir;<br/>Du füllst mit Freude Herz und Geist,<br/>So find ich Ruh in Dir.<br/>',NULL,47704,4);
INSERT INTO stanza VALUES('G318','5','Gerne verweil ich hier,<br/>Immerzu suche Dich,<br/>Ich bleib im Wort und im Gebet,<br/>Bis Du, Herr, fließt durch mich.<br/>',NULL,47705,5);
INSERT INTO stanza VALUES('G319','1','Ich komm vor Deinen Gnadenthron,<br/>Herr, nähr mein Herz so reich mit Dir;<br/>Barmherzigkeit und Gnade auch<br/>Zum rechten Zeitpunkt find ich hier.<br/>',NULL,47706,1);
INSERT INTO stanza VALUES('G319','2','Hier schaue ich Dein Antlitz hell,<br/>Sein klares Licht mein Herz belehrt;<br/>Die Heilung in den Strahlen nun<br/>All meine Schwachheit ganz verzehrt.<br/>',NULL,47707,2);
INSERT INTO stanza VALUES('G319','3','Dein Licht erleuchtet mich, mein Herr,<br/>Mein''n wahren Zustand stellt es bloß;<br/>Die Wirkung Deines Blutes hier<br/>Seh ich: Es wäscht mich tadellos.<br/>',NULL,47708,3);
INSERT INTO stanza VALUES('G319','4','Hier salbst Du mich mit Deinem Geist,<br/>Er macht Dein eignes Wesen mein;<br/>So Deinen Herzenswunsch sowie<br/>Dich Selbst sogar genieß ich rein.<br/>',NULL,47709,4);
INSERT INTO stanza VALUES('G319','5','Hier lese ich vor Dir Dein Wort,<br/>So wie die Priester machten Licht;<br/>Hier fließt Dein Geist wie Öl in mir,<br/>Erhellt Dein Wort und gibt mir Sicht.<br/>',NULL,47710,5);
INSERT INTO stanza VALUES('G319','6','Die Priester brachten Weihrauch dar,<br/>So bringe ich Gebet nun Dir;<br/>Wie Weihrauch mengst Du Dich als Geist<br/>Mit dem Gebet, das ich offrier.<br/>',NULL,47711,6);
INSERT INTO stanza VALUES('G319','7','Dein Wort ist Licht, Dein Wort ist Speis,<br/>Dein Wort erleuchtet und verpflegt;<br/>Mit Licht und Speise füllst Du mich<br/>Beim Lesen ess ich unentwegt.<br/>',NULL,47712,7);
INSERT INTO stanza VALUES('G319','8','Du bist der Strom des Lebens, Herr,<br/>Erweckung bringst Du voll und frisch;<br/>Ich möchte beten, trinken mehr,<br/>Bis Du in Strömen fließt durch mich.<br/>',NULL,47713,8);
INSERT INTO stanza VALUES('G319','9','Du steigst als Weihrauch auf zu Gott,<br/>In Dir nimmt Gott uns völlig an;<br/>Ich möchte beten immer mehr,<br/>Dass süßer Duft Dir steigen kann.<br/>',NULL,47714,9);
INSERT INTO stanza VALUES('G319','10','Beim Lesen leuchtet mir Dein Licht,<br/>Durch Beten Du den Durst mir stillst;<br/>So werd ich reich mit Dir versorgt,<br/>Weil Du die Not so treffen willst.<br/>',NULL,47715,10);
INSERT INTO stanza VALUES('G319','11','Nach mehr Gemeinschaft sehn ich mich,<br/>Beim Lesen, Beten, eins mit Dir;<br/>O Herr, mit Dir durchtränke mich,<br/>Bis Du reich überfließt aus mir.<br/>',NULL,47716,11);
INSERT INTO stanza VALUES('G320','1','Nicht nur von Broten lebt der Mensch,<br/>Sondern von jedem klaren Wort,<br/>Das aus dem Mund von Gott ausgeht,<br/>Mit Leben stärkt es uns sofort.<br/>',NULL,47717,1);
INSERT INTO stanza VALUES('G320','2','Gott machte nicht nur unsren Leib,<br/>Seele und Geist warn mit dabei;<br/>Innerster Teil ist unser Geist,<br/>Durch ihn berührn wir Gott ganz frei.<br/>',NULL,47718,2);
INSERT INTO stanza VALUES('G320','3','Irdische Speise braucht der Leib,<br/>Ebenfalls hungrig ist der Geist;<br/>Du Selbst, Herr Jesus, uns versorgst<br/>Und durch Dein Wort uns täglich speist.<br/>',NULL,47719,3);
INSERT INTO stanza VALUES('G320','4','Du bist der Geist und, Herr, Dein Wort<br/>Bringt Dich zum Ausdruck immerzu;<br/>Wir nehmen es durch unseren Geist,<br/>Da es auch Geist ist, so wie Du.<br/>',NULL,47720,4);
INSERT INTO stanza VALUES('G320','5','Dein Wort zu nehmen, heißt nicht nur,<br/>Dass mit den Augen lesen wir<br/>Und es verstehen im Verstand;<br/>Den Geist zu üben, zählt nur hier.<br/>',NULL,47721,5);
INSERT INTO stanza VALUES('G320','6','Herr, Dein Wort essen wir im Geist,<br/>Nehmen''s im tiefsten Teil gern ein;<br/>Was wir erkennen im Verstand,<br/>Betend im Geist nährt unser Sein.<br/>',NULL,47722,6);
INSERT INTO stanza VALUES('G320','7','Doch wenn Dein Wort bleibt im Verstand,<br/>Ist es Erkenntnis, Tod nur bringt;<br/>Es wird zu Leben und zu Geist,<br/>Wenn es auch unsren Geist durchdringt.<br/>',NULL,47723,7);
INSERT INTO stanza VALUES('G320','8','Nur dann wenn unser Geist sich regt<br/>Und Dein Wort aufnimmt, Dich berührt,<br/>Wird unser Sein von Dir ernährt,<br/>Tief in Gemeinschaft dies mich führt.<br/>',NULL,47724,8);
INSERT INTO stanza VALUES('G320','9','Lesen wir nun Dein Wort, o Herr,<br/>Lehr uns zu üben unsren Geist;<br/>Essen wir Dich auf diese Art,<br/>Wird unser Geist so reich gespeist.<br/>',NULL,47725,9);
INSERT INTO stanza VALUES('G321','1','Christus ist Geist und auch das Wort,<br/>Und als der Geist im Wort so reich;<br/>Und alle Worte, die Er spricht,<br/>Sind Leben und sind Geist zugleich.<br/>',NULL,47726,1);
INSERT INTO stanza VALUES('G321','2','Das Heil''ge Wort ist äußerlich,<br/>Der Heil''ge Geist ist innerlich;<br/>Wie groß sind diese Gaben, Herr!<br/>Darin genießen wir nun Dich.<br/>',NULL,47727,2);
INSERT INTO stanza VALUES('G321','3','Das Wort den Geist zum Ausdruck bringt,<br/>Der Geist ist dessen Wirklichkeit;<br/>Sie sind zwei Seiten eines Dings,<br/>Untrennbar, in Abhängigkeit.<br/>',NULL,47728,3);
INSERT INTO stanza VALUES('G321','4','Sooft der Geist das Wort erhellt,<br/>Wirst du zum Leben hingewandt;<br/>Doch ist das Wort getrennt vom Geist,<br/>Dann spricht es an nur den Verstand.<br/>',NULL,47729,4);
INSERT INTO stanza VALUES('G321','5','Wenn du das Wort im Geist berührst,<br/>Wird es zu Leben und zu Geist;<br/>Der Geist, wenn ausgelebt von uns,<br/>Als Lebensworte andre speist.<br/>',NULL,47730,5);
INSERT INTO stanza VALUES('G321','6','Wir sollten üben unsren Geist,<br/>Im Geist das Wort treu nehmen ein,<br/>Um auszuteilen Gott als Geist,<br/>Die beiden eins in uns solln sein.<br/>',NULL,47731,6);
INSERT INTO stanza VALUES('G321','7','O liebster Herr, mach nun Dein Wort<br/>Zum Geist, der Leben gibt, in mir,<br/>Und mög Dein Geist in Deinem Wort<br/>Mein wahrer Ausdruck werden hier.<br/>',NULL,47732,7);
INSERT INTO stanza VALUES('G322','1','Gottes Wort nicht nur zur Kenntnis,<br/>Doch als wahres Leben nimm,<br/>Nicht nur Gottes Denken zeigt es,<br/>Gott als Leben ist in ihm.<br/>Es teilt nicht nur mit, was Gott spricht,<br/>Nicht nur Lehre zieh daraus,<br/>Christus als das Leben birgt es,<br/>Zu erfahren überaus.<br/>',NULL,47733,1);
INSERT INTO stanza VALUES('G322','2','Es ist nur für uns Erkenntnis,<br/>Wenn wir''s lesen im Verstand,<br/>Doch zu Leben wird es werden,<br/>Wenn der Geist uns kommt zur Hand.<br/>Wenn wir nur Buchstaben kennen,<br/>In den Tod bringt''s uns hinein,<br/>Doch mit Leben haucht es uns an,<br/>Wenn im Geist wir''s nehmen ein.<br/>',NULL,47734,2);
INSERT INTO stanza VALUES('G322','3','Wenn der Herr im Wort verfehlt wird,<br/>Bleiben wir im Innern leer;<br/>Doch berührn wir darin Christus,<br/>Füllt das Leben uns so sehr.<br/>Lesen wir es ohne Christus,<br/>Wird nur Wissbegier gespeist,<br/>Doch berührn wir Christus darin,<br/>Fließt das Leben reich im Geist.<br/>',NULL,47735,3);
INSERT INTO stanza VALUES('G322','4','Die Erkenntnis vom Wort Gottes<br/>Wird zu Leben, reich uns dient,<br/>Wenn, was der Verstand verstehn kann,<br/>Form in unsrem Geist gewinnt.<br/>Was du weißt durch die Schrift Gottes,<br/>Soll lebendig machend sein,<br/>Die Erkenntnis des Buchstabens<br/>Atmen wir im Geist tief ein.<br/>',NULL,47736,4);
INSERT INTO stanza VALUES('G322','5','Wissen in dem Wort zu suchen,<br/>Heißt den gleichen Weg zu gehn,<br/>Wie einst Eva ward betrogen,<br/>Durch Erkenntnis ist''s geschehn;<br/>Doch die Schrift wird stets zu Leben,<br/>Wenn vom Lebensbaum du isst;<br/>Gottes Wort im Geist aufnehmen<br/>Täglich wahre Speise ist.<br/>',NULL,47737,5);
INSERT INTO stanza VALUES('G323','1','Willst du, dass Er dich von der Welt befreit?<br/>Amen zu Gottes Wort!<br/>Willst du ein Leben voller Wirklichkeit?<br/>Amen zu Gottes Wort!<br/>',NULL,47738,1);
INSERT INTO stanza VALUES('G323','chorus','Amen zu Gottes Wort!<br/>Amen zu Gottes Wort!<br/>Sein Wort empfange und daran glaube,<br/>Amen zu Gottes Wort!<br/>',NULL,47739,2);
INSERT INTO stanza VALUES('G323','2','Was kann vom Selbst und Sünde dich befrein?<br/>Amen zu Gottes Wort!<br/>Möchtest du im Verstand erneuert sein?<br/>Amen zu Gottes Wort!<br/>',NULL,47740,3);
INSERT INTO stanza VALUES('G323','chorus','Amen zu Gottes Wort!<br/>Amen zu Gottes Wort!<br/>Sein Wort ist Leben, Kraft will uns geben,<br/>Amen zu Gottes Wort!<br/>',NULL,47741,4);
INSERT INTO stanza VALUES('G323','3','Uns zugelost ist Christus als das Land –<br/>Amen zu Gottes Wort!<br/>Willst du hineingehn, lass den Widerstand –<br/>Amen zu Gottes Wort!<br/>',NULL,47742,5);
INSERT INTO stanza VALUES('G323','chorus','Amen zu Gottes Wort!<br/>Amen zu Gottes Wort!<br/>Sein Wort erleuchtet, uns völlig läutert –<br/>Amen zu Gottes Wort!<br/>',NULL,47743,6);
INSERT INTO stanza VALUES('G323','4','Jesus kommt wieder, bald ist es soweit –<br/>Amen zu Gottes Wort!<br/>Wenn Er schon jetzt kommt, bist du dann bereit?<br/>Amen zu Gottes Wort!<br/>',NULL,47744,7);
INSERT INTO stanza VALUES('G323','chorus','Amen zu Gottes Wort!<br/>Amen zu Gottes Wort!<br/>Uns zubereitet, zu Jesus leitet –<br/>Amen zu Gottes Wort!<br/>',NULL,47745,8);
INSERT INTO stanza VALUES('G324','1','Gottes Geheimnis ist Christus;<br/>Gott ist nicht sichtbar, nicht erkannt,<br/>Nie hat der Mensch Sein Bild gesehn,<br/>Doch Gott, der Sohn, macht Ihn bekannt.<br/>',NULL,47746,1);
INSERT INTO stanza VALUES('G324','2','Christus ist Selbst das Wort von Gott,<br/>Das Gott erklärt so wunderbar;<br/>Gottes Verkörperung ist Er,<br/>Und Gottes Bild macht Er sichtbar.<br/>',NULL,47747,2);
INSERT INTO stanza VALUES('G324','3','Er ist das Bild des Unsichtbarn,<br/>Ausstrahlung Seiner Herrlichkeit;<br/>Und Gottes Fülle wohnt in Ihm,<br/>Er trägt Sein Zeugnis allezeit.<br/>',NULL,47748,3);
INSERT INTO stanza VALUES('G324','4','Christi Geheimnis ist Sein Leib,<br/>Denn jetzt ist Christus unsichtbar;<br/>Keiner auf Erden kann Ihn sehn,<br/>Doch die Gemeinde zeigt Ihn klar.<br/>',NULL,47749,4);
INSERT INTO stanza VALUES('G324','5','Christi Ausdruck ist die Gemeind,<br/>Christus leibhaftig wohnt in ihr;<br/>Seine Verdoppelung ist sie,<br/>Sie macht Ihn sichtbar jetzt und hier.<br/>',NULL,47750,5);
INSERT INTO stanza VALUES('G324','6','Seht, die Gemeinde trägt Sein Bild,<br/>Sie ist Sein Zuwachs in Natur;<br/>Er ist ihr Haupt, sie ist Sein Leib,<br/>Ja, sie besteht aus Christus nur.<br/>',NULL,47751,6);
INSERT INTO stanza VALUES('G324','7','Somit der Vater ist im Sohn,<br/>Und nun der Sohn als Geist ist hier;<br/>Dreieiner Gott, als Geist bist Du<br/>In der Gemeinde – eins mit ihr.<br/>',NULL,47752,7);
INSERT INTO stanza VALUES('G325','1','So wie unser Leib die Fülle<br/>Unsres Lebens ist,<br/>So auch Christi Leib der Ausdruck<br/>Seines Lebens ist.<br/>',NULL,47753,1);
INSERT INTO stanza VALUES('G325','2','So wie Eva kommt aus Adam,<br/>Ihm entnommen ist,<br/>So der Zuwachs Christi heute<br/>Die Gemeinde ist.<br/>',NULL,47754,2);
INSERT INTO stanza VALUES('G325','3','Wie das Korn, das stirbt im Erdreich,<br/>Vielfach sich vermehrt,<br/>Wie aus Körnern, die vermengt sind,<br/>Wird ein Brot voll Wert.<br/>',NULL,47755,3);
INSERT INTO stanza VALUES('G325','4','Durch die Christen, die Gemeinde,<br/>Christus sich vermehrt,<br/>Als der Leib, tun sie Ihn kund nun,<br/>so wird Gott verehrt.<br/>',NULL,47756,4);
INSERT INTO stanza VALUES('G325','5','Durch die Reben stellt der Weinstock<br/>Seinen Zuwachs aus,<br/>Sie sind eins mit ihm und tragen<br/>Frucht aus ihm heraus.<br/>',NULL,47757,5);
INSERT INTO stanza VALUES('G325','6','So die Glieder der Gemeinde<br/>Breiten Christus aus,<br/>Tragen, eins mit Ihm, Sein Zeugnis<br/>In die Welt hinaus.<br/>',NULL,47758,6);
INSERT INTO stanza VALUES('G325','7','Fülle, Zuwachs und Vermehrung,<br/>Ausdruck voll Genuss,<br/>Wachstum, Ausbreitung, Verdopplung<br/>Reicher Überfluss,<br/>',NULL,47759,7);
INSERT INTO stanza VALUES('G325','8','Ist für Christus die Gemeinde;<br/>Gott in Christus wird<br/>Reich verehrt durch die Erlösten,<br/>Und ihr Lob Ihn ziert.<br/>',NULL,47760,8);
INSERT INTO stanza VALUES('G325','9','Seht, wie groß ist das Geheimnis:<br/>Christus und Gemeind,<br/>Gottheit ist vermengt mit Menschheit,<br/>Ewiglich vereint.<br/>',NULL,47761,9);
INSERT INTO stanza VALUES('G326','1','Die Gemeinde ist so herrlich und wir sind ein Teil von ihr –<br/>Wir sind glücklich, denn der Herr hat uns vereint!<br/>Einen Leib im Universum gibt''s, dazu gehören wir<br/>Halleluja, denn der Herr hat uns vereint!<br/>',NULL,47762,1);
INSERT INTO stanza VALUES('G326','chorus','Halleluja für den Leib hier!<br/>Wir sind Glieder Seines Leibes!<br/>Wir sind ganz für Seinen Leib hier!<br/>Halleluja, denn der Herr hat uns vereint!<br/>',NULL,47763,2);
INSERT INTO stanza VALUES('G326','2','Nicht die Einzelchristen, sondern einen korp''rativen Leib,<br/>Ist was Gott für Seinen Ausdruck heut verlangt;<br/>Nicht die einzelnen Gemeinden, sondern ein vermengter Leib –<br/>Halleluja, wir sind in den Leib gelangt!<br/>',NULL,47764,3);
INSERT INTO stanza VALUES('G326','chorus','Halleluja für den Leib hier!<br/>Satan zittert vor dem Leibe!<br/>Wir sind siegreich nur im Leibe!<br/>Halleluja, wir sind jetzt in Christi Leib!<br/>',NULL,47765,4);
INSERT INTO stanza VALUES('G326','3','Es gibt sieben goldne Leuchter, alle göttlicher Natur –<br/>Nichts Natürliches der Leib erlauben kann;<br/>Die Natur von Gott vereint uns, deshalb strahlt ihr Licht so hell –<br/>Halleluja, schaut die hellen Leuchter an!<br/>',NULL,47766,5);
INSERT INTO stanza VALUES('G326','chorus','Halleluja für den Leib hier!<br/>Für die Leuchter Seines Leibes!<br/>Für den goldnen, hellen Leib hier!<br/>Halleluja, schaut die hellen Leuchter an!<br/>',NULL,47767,6);
INSERT INTO stanza VALUES('G326','4','Wie stehn wir in dieser Einheit, scheinen hell mit Göttlichkeit?<br/>Halleluja, Jesus essen ist der Weg!<br/>Er ist unser Baum des Lebens, Manna, Fest in Ewigkeit –<br/>Halleluja, Ihn zu essen täglich pfleg!<br/>',NULL,47768,7);
INSERT INTO stanza VALUES('G326','chorus','Wir sind eins durch essen Jesus!<br/>Göttlich sind durch essen Jesus!<br/>Scheinen hell durch essen Jesus!<br/>Halleluja, Jesus essen ist der Weg!<br/>',NULL,47769,8);
INSERT INTO stanza VALUES('G327','1','Nach der Gemeinde sehnt Sich<br/>Der Herr seit Ewigkeit,<br/>Ihr hat Er Seine Taten<br/>Und jedes Wort geweiht.<br/>Er liebt sie unaussprechlich,<br/>Mit ihr will ewig sein;<br/>Vor Grundlegung der Erde<br/>Nahm sie Sein Herz schon ein.<br/>',NULL,47770,1);
INSERT INTO stanza VALUES('G327','2','Am Abend vor der Schöpfung<br/>An sie nur dachte Er,<br/>An jedes Wesensmerkmal,<br/>Das Ihm gefällt so sehr.<br/>Die Schöpfung sprang ins Dasein,<br/>Doch Er voll Sehnsucht schaut<br/>In grenzenloser Liebe<br/>Nur aus nach Seiner Braut.<br/>',NULL,47771,2);
INSERT INTO stanza VALUES('G327','3','Er will Sein Gegenüber<br/>Um jeden Preis erstehn;<br/>Welch Segen, dass Sein Vorsatz<br/>Für ewig bleibt bestehn!<br/>Obwohl der Mensch versagte,<br/>In Sünde fiel, war schwach,<br/>Wird Er sie nie aufgeben,<br/>Die Sehnsucht lässt nie nach.<br/>',NULL,47772,3);
INSERT INTO stanza VALUES('G327','4','Barmherzigkeit erblühte<br/>Und Liebe grenzenlos,<br/>Er suchte sie voll Gnade<br/>Und Weisheit ruhelos.<br/>Nur Gott versteht die Liebe,<br/>Die Er ihr hat erzeigt!<br/>Er gab Sich hin als Opfer,<br/>Dass Wohlgeruch aufsteigt.<br/>',NULL,47773,4);
INSERT INTO stanza VALUES('G327','5','Und jetzt in Auferstehung<br/>Ist ihr der Herr so nah,<br/>In Herrlichkeit und Liebe<br/>Kommt Er und ist bald da.<br/>Der Anblick des Geliebten<br/>Füllt sie mit Herrlichkeit,<br/>Bis sie, die Braut, entrückt ist,<br/>Ersehnt seit Ewigkeit.<br/>',NULL,47774,5);
INSERT INTO stanza VALUES('G328','1','Von Natur warn wir in Sünde tot,<br/>Lebten nur in Unstimmigkeit;<br/>Doch zusammen hat uns Gott belebt,<br/>Um zu sitzen mit dem Herrn nun allezeit.<br/>',NULL,47775,1);
INSERT INTO stanza VALUES('G328','chorus','Jesus, Er fügt uns nun zusammen,<br/>Komm und sieh, die Heiligen vereint.<br/>Seine Liebe bindet uns zusammen<br/>Bis der Wuchs der Fülle Christi ist erreicht.<br/>',NULL,47776,2);
INSERT INTO stanza VALUES('G328','2','Mit den Heiligen erfassen wir<br/>Alle Dimensionen des Herrn.<br/>Christi Liebe alles übersteigt,<br/>Bis zur Fülle Gottes füllt Er uns so gern.<br/>',NULL,47777,3);
INSERT INTO stanza VALUES('G328','3','Unsres Gottes Absicht kennen wir,<br/>Sein Geheimnis ist uns nun bekannt,<br/>Christus, die Gemeinde sehen wir<br/>Und zusammen machen wir den Feind zuschand.<br/>',NULL,47778,4);
INSERT INTO stanza VALUES('G328','4','Daher beten wir zum Vater Gott –<br/>In den innren Menschen uns doch stärk;<br/>Richte Dich in unsren Herzen ein,<br/>Wurzle uns in Deiner Liebe, für Dein Werk.<br/>',NULL,47779,5);
INSERT INTO stanza VALUES('G328','5','Alle Glieder reichen Christus dar,<br/>Werden eingebaut im Leib so gern;<br/>Jeder wirkt gemäß dem eignen Maß,<br/>Und in Liebe baut sich auf der Leib des Herrn.<br/>',NULL,47780,6);
INSERT INTO stanza VALUES('G328','6','Als der neue Mensch erfüllen wir<br/>Gottes Plan, da wir in Einheit stehn;<br/>Ehre Ihm in der Gemeinde sei<br/>Und in Christus Jesus ewiglich – Amen!<br/>',NULL,47781,7);
INSERT INTO stanza VALUES('G329','1','Der Reichtum Christi – mein Genuss!<br/>So Christi Fülle werden wir;<br/>Sind wir mit Christus ganz erfüllt,<br/>Wird Christi Zeugnis sichtbar hier.<br/>',NULL,47782,1);
INSERT INTO stanza VALUES('G329','2','Der Reichtum Christi – was Er ist,<br/>Was uns zu Seiner Fülle macht;<br/>So wie der Mensch umkleidet ist<br/>Von einem Leib, der ihn ausmacht.<br/>',NULL,47783,2);
INSERT INTO stanza VALUES('G329','3','In den Produkten Kanaans<br/>Den Reichtum Christi sehen wir;<br/>So war der Tempel aufgebaut,<br/>Ein Sinnbild der Gemeinde hier.<br/>',NULL,47784,3);
INSERT INTO stanza VALUES('G329','4','Wie Eva Adams Fülle war,<br/>So die Gemeinde Christus ist;<br/>Wie Eva ganz aus Adam kam,<br/>Aus Christi Leben sie entsprießt.<br/>',NULL,47785,4);
INSERT INTO stanza VALUES('G329','5','Der Reichtum Christi ist Er Selbst,<br/>Und Seine Fülle: die Gemeind;<br/>Sie ist Sein Ausdruck, voll von Ihm,<br/>Und mit Ihm aufgebaut erscheint.<br/>',NULL,47786,5);
INSERT INTO stanza VALUES('G330','1','Für Christus die Gemeind ist ein<br/>Gefäß, das Ihm voll Ausdruck schafft;<br/>Wie ein Gefäß ist unser Leib,<br/>Der Ausdruck unsrer Lebenskraft.<br/>',NULL,47787,1);
INSERT INTO stanza VALUES('G330','2','So wie im Tempel seinerzeit<br/>Die Bundeslade ruhte dort,<br/>Ist Christus Inhalt der Gemeind,<br/>Und die Gemeind ist Ihm Wohnort.<br/>',NULL,47788,2);
INSERT INTO stanza VALUES('G330','3','Gottes Geheimnis Christus ist,<br/>Er zeigt uns Gott so deutlich, klar;<br/>Christi Geheimnis, die Gemeind,<br/>Macht Christus heute offenbar.<br/>',NULL,47789,3);
INSERT INTO stanza VALUES('G330','4','Die Glieder der Gemeinde sind<br/>Am Anfang voll und ganz aus Ton;<br/>So wandelt Er sie täglich um,<br/>Bis sie sind transparent und schön.<br/>',NULL,47790,4);
INSERT INTO stanza VALUES('G330','5','Und umgewandelt werden sie,<br/>Dass ein Gefäß sie Ihm verleihn;<br/>Die Allumfassendheit des Herrn<br/>Kommt so zum Ausdruck durch ihr Sein.<br/>',NULL,47791,5);
INSERT INTO stanza VALUES('G330','6','Durch sämtliches Umwandlungswerk,<br/>Das Gott vollbracht hat innerlich,<br/>Wird die Gemeinde Sein Gefäß,<br/>Neues Jerusalem für Sich.<br/>',NULL,47792,6);
INSERT INTO stanza VALUES('G330','7','Wie kostbar die Gemeinde ist!<br/>Durchsichtig ist sie wie Kristall;<br/>Die Fülle Gottes wohnt in ihr,<br/>Und Herrlichkeit strahlt überall.<br/>',NULL,47793,7);
INSERT INTO stanza VALUES('G330','8','Christus als Leben, Gott als Licht,<br/>Der Geist als Strom folgt Seinem Lauf,<br/>So zeigt sie den Dreieinen Gott<br/>Dem ganzen Universum auf.<br/>',NULL,47794,8);
INSERT INTO stanza VALUES('G331','1','Ein Leuchter die Gemeinde ist,<br/>Die Lampe – Christus, Gott das Licht;<br/>Aus Christus scheint es, göttlich, hell,<br/>Und die Gemeinde bringt''s in Sicht.<br/>',NULL,47795,1);
INSERT INTO stanza VALUES('G331','2','Das Licht, das in der Lampe scheint,<br/>Ist Gott als Leben, göttlich, rein;<br/>Damit der Leuchter Ihm entspricht,<br/>Darf er aus reinem Gold nur sein.<br/>',NULL,47796,2);
INSERT INTO stanza VALUES('G331','3','In dieser finstren, dunklen Zeit<br/>Hell Gottes Lebenslicht erstrahlt;<br/>In vielen Städten nah und fern,<br/>Hat Jesu Zeugnis schon Gestalt.<br/>',NULL,47797,3);
INSERT INTO stanza VALUES('G331','4','Soll die Gemeinde Zeugnis sein,<br/>Die „erste Liebe“ halten muss;<br/>Als Überwinder erntet sie<br/>Vom „Baum des Lebens“ den Genuss.<br/>',NULL,47798,4);
INSERT INTO stanza VALUES('G331','5','Sie muss Verfolgung hier durchstehn,<br/>So wird gekrönt mit Leben dann;<br/>Wer Götzen-Unzucht streng ablehnt,<br/>„Verborg''nes Manna“ essen kann.<br/>',NULL,47799,5);
INSERT INTO stanza VALUES('G331','6','Gibt sie das Werk „Isebels“ auf,<br/>Wird sie regieren allezeit;<br/>Wenn sie sich nicht mit Tod befleckt,<br/>Bekleidet sie das „weiße Kleid“.<br/>',NULL,47800,6);
INSERT INTO stanza VALUES('G331','7','Wie „Philadelphia“ muss sie sein,<br/>Bekennt Ihn treu und hält Sein Wort;<br/>Sie überwindet Lauwarmsein,<br/>Mit Ihm wird festen immerfort.<br/>',NULL,47801,7);
INSERT INTO stanza VALUES('G331','8','Geläutert wird nun die Gemeind<br/>Zum reinen, goldnen Leuchter hier,<br/>Das Zeugnis Jesu würdig trägt,<br/>Sein reines Leben wohnt in ihr.<br/>',NULL,47802,8);
INSERT INTO stanza VALUES('G331','9','Die örtlichen Gemeinden sind<br/>Die hellen Leuchter dieser Zeit;<br/>Das himmlische Jerusalem<br/>Der Leuchter ist in Ewigkeit.<br/>',NULL,47803,9);
INSERT INTO stanza VALUES('G331','10','Die Stadt, die scheint wie reines Gold,<br/>Vollendung aller Leuchter ist;<br/>Als Lampe hält sie Christus hin,<br/>Durch die sich Gottes Licht ergießt.<br/>',NULL,47804,10);
INSERT INTO stanza VALUES('G332','1','Gott erwählte die Gemeinde<br/>Schon vor Grundlegung der Welt,<br/>Dass sie teilhat an der Sohnschaft,<br/>Makellos sie vor Sich stellt;<br/>Die Gemeinde Sein Besitz ist,<br/>Die der Geist versiegelt hat,<br/>Unser Unterpfand des Erbes,<br/>Bis Sein Sohn wird offenbar.<br/>',NULL,47805,1);
INSERT INTO stanza VALUES('G332','2','Christus fuhr zu Gottes Thron auf,<br/>Über alle Macht und Kraft;<br/>Gott gab Ihn als Haupt von allem,<br/>Der Gemeinde meisterhaft.<br/>Er füllt alles und in allem,<br/>Seine Fülle stellt heut dar<br/>Die Gemeinde, die Sein Leib ist;<br/>Sie macht Sein Bild offenbar.<br/>',NULL,47806,2);
INSERT INTO stanza VALUES('G332','3','Wir warn tot in unsren Sünden,<br/>Lebten nach dem Lauf der Welt,<br/>Nach Verstand und Lust des Fleisches,<br/>Worin Satan ist der Quell.<br/>Gott erweckte uns mit Christus,<br/>In die Himmel hat gesetzt;<br/>Uns zum Meisterstück im Sohn macht,<br/>Seine Freude sind wir jetzt.<br/>',NULL,47807,3);
INSERT INTO stanza VALUES('G332','4','Juden, Heiden sind ein Leib nun –<br/>Sein Geheimnis ruht allein<br/>Auf Aposteln und Propheten,<br/>Christus Selbst ist der Eckstein.<br/>Christus baut uns auf zusammen,<br/>Gottes Wohnung, Seine Ruh;<br/>Gottes Geist uns fest verbindet,<br/>Für Sein Wohlgefalln dazu.<br/>',NULL,47808,4);
INSERT INTO stanza VALUES('G332','5','Vor den Zeiten war Sein Vorsatz<br/>– Seine Weisheit doch beacht –<br/>Die Gemeinde, Sein Geheimnis,<br/>Wo der Sohn nun Wohnung macht.<br/>Hier im Geist wird Seine Breite,<br/>Höhe, Tiefe uns enthüllt,<br/>Seine unsagbare Liebe<br/>Uns mit Gottes Fülle füllt.<br/>',NULL,47809,5);
INSERT INTO stanza VALUES('G332','6','Nur ein Leib, ein Geist und Hoffnung,<br/>Nur ein Glaube und ein Herr,<br/>Eine Taufe und ein Vater,<br/>Dies eint die Gemeinde sehr.<br/>Lasst uns Christus voll erkennen,<br/>Reifen zum erwachs''nen Mann;<br/>Wind der Lehren nicht annehmen,<br/>Die nur täuschen, schwindeln an.<br/>',NULL,47810,6);
INSERT INTO stanza VALUES('G332','7','Für den Aufbau Seines Leibes<br/>Reicht der Herr die Gaben dar,<br/>Um die Heil''gen zuzurüsten,<br/>So den Dienst sie nehmen wahr.<br/>Drum legt ab den alten Menschen,<br/>Zieht den neuen Menschen an;<br/>Im Verstand und Geist erneuert,<br/>Tragen wir Sein Bild sodann.<br/>',NULL,47811,7);
INSERT INTO stanza VALUES('G332','8','Christus gab Sich hin in Liebe,<br/>Die Gemeinde heiligt Er;<br/>Seine schöne Braut soll strahlen,<br/>Makellos macht sie der Herr.<br/>Wie ein Mensch, der seinen Leib pflegt,<br/>Liebt der Herr sie grenzenlos;<br/>Beide sind ein Leib geworden,<br/>Welch Geheimnis, riesengroß!<br/>',NULL,47812,8);
INSERT INTO stanza VALUES('G332','9','Neuer Mensch, der Leib, die Braut und<br/>Noch viel mehr ist die Gemeind;<br/>Als Armee kämpft sie erfolgreich,<br/>Überwindet Gottes Feind.<br/>Mit der Waffenrüstung Gottes<br/>Ist sie stark in Seiner Kraft,<br/>In dem Herrn ja standfest stehend,<br/>Durch Gebet sie Sieg verschafft.<br/>',NULL,47813,9);
INSERT INTO stanza VALUES('G333','1','Gemeinde, der Leib Christi,<br/>Des Vaters Wohnung hier,<br/>Versammlung der Berufnen,<br/>Vermengt mit Gott sind wir;<br/>Erwählt vor aller Schöpfung,<br/>Erlöst durch Christi nur,<br/>Ihr Wesen und ihr Stand sind<br/>Von himmlischer Natur.<br/>',NULL,47814,1);
INSERT INTO stanza VALUES('G333','2','In Auferstehung ist sie<br/>Der neue Mensch hinfort,<br/>Getauft in Gott dem Geiste,<br/>Geheiligt durch Sein Wort;<br/>Ihr Leben, Inhalt – Christus,<br/>Mit Ihm, dem Haupt vereint,<br/>Mit Ihm hoch aufgefahren,<br/>Hoch über jeden Feind.<br/>',NULL,47815,2);
INSERT INTO stanza VALUES('G333','3','Ihr Fundament ist Christus,<br/>Kein Mensch ein andres legt;<br/>Sie ist wie Christus göttlich,<br/>Besteht aus Ihm durchweg;<br/>Der Geist lässt ihre Glieder<br/>Den Golgatha-Tod teiln,<br/>Gebaut in Auferstehung –<br/>Gold, Silber, Edelstein.<br/>',NULL,47816,3);
INSERT INTO stanza VALUES('G333','4','Ein Gott, ein Herr, ein Geist sind<br/>Die Elemente ein,<br/>Ein Glaube, Hoffnung, Taufe,<br/>Ein Leib im Sohn soll''s sein;<br/>Im Leib mit seinen Gliedern<br/>Wohnt die Dreieinigkeit,<br/>Sie sind vereint im Glauben,<br/>Der Hoffnung Herrlichkeit.<br/>',NULL,47817,4);
INSERT INTO stanza VALUES('G333','5','Von jedem Volk und Sprache<br/>Die Glieder kommen her,<br/>Kein Unterschied der Klassen,<br/>Vereint hat sie der Herr.<br/>Kein Jude und kein Grieche,<br/>Kein Sklave, Freier hier,<br/>Nur Christus ist zu sehen,<br/>Der „neue Mensch“ sind wir.<br/>',NULL,47818,5);
INSERT INTO stanza VALUES('G333','6','Ein Leib im Universum<br/>An jedem Ort erscheint,<br/>Der Wohnort ihrer Glieder<br/>Der Grund ist der Gemeind;<br/>Verwaltet wird sie örtlich,<br/>Dem Herrn alleine gilt;<br/>Gemeinschaft allumschließend<br/>Die Einheit aufrecht hält.<br/>',NULL,47819,6);
INSERT INTO stanza VALUES('G333','7','Heut sehen wir im Kleinen<br/>Durch die Versammlungen<br/>So viele Einzelheiten<br/>Des Neu''n Jerusalem.<br/>Die Lampe, die ist Christus,<br/>Gott scheint als Licht in ihr;<br/>Die Leuchter, die Gemeinden,<br/>Sein Bild hell tragen hier.<br/>',NULL,47820,7);
INSERT INTO stanza VALUES('G334','1','Der Same der Gemeind ist Christus Selbst,<br/>Ins Herz gesät als Leben durch Sein Wort;<br/>Er wächst wie Weizen, wird zu feinem Mehl,<br/>Gott und den Menschen sättigt Er als Brot.<br/>',NULL,47821,1);
INSERT INTO stanza VALUES('G334','2','Satan hat falsche Gläubige gesät,<br/>Unter dem Weizen ließ er Lolch aufgehn;<br/>Sein Durcheinander hält das Wachstum auf,<br/>Denn Gottes Plan möcht er verhindert sehn.<br/>',NULL,47822,2);
INSERT INTO stanza VALUES('G334','3','Wie aus dem Senfkorn wächst ein kleines Kraut,<br/>So muss das Leben der Gemeinde sein;<br/>Ist gut zur Speise für die Hungrigen,<br/>Doch seine Form ist unscheinbar und klein.<br/>',NULL,47823,3);
INSERT INTO stanza VALUES('G334','4','Doch Satan kam, veränderte die Form<br/>Und die Natur des kleinen Krauts sodann;<br/>Es wuchs heran zu einem großen Baum,<br/>Wo so viel Böses sich einnisten kann.<br/>',NULL,47824,4);
INSERT INTO stanza VALUES('G334','5','Auch die Gemeinde fiel durch Satans List,<br/>Heidnische Praxis kam in sie hinein;<br/>So wie der Sauerteig das Mehl durchdringt,<br/>So kann sie nicht mehr reine Speise sein.<br/>',NULL,47825,5);
INSERT INTO stanza VALUES('G334','6','Die Heil''gen wandelt Christus aber um,<br/>Macht sie zur Perle und zum Edelstein;<br/>Er baut durch sie nun die Gemeinde auf,<br/>Bald wird Sein Königreich erkennbar sein.<br/>',NULL,47826,6);
INSERT INTO stanza VALUES('G334','7','Eine Gemeind, in Christi Leben reif,<br/>Schon umgewandelt, eingebaut im Herrn,<br/>Gleicht einem Schatz, verborgen in dem Feld,<br/>Ist wie die Perle, die Er hätte gern.<br/>',NULL,47827,7);
INSERT INTO stanza VALUES('G334','8','Herr, sondre uns vom „Lolch“ des Teufels ab,<br/>Und von dem „Riesen-Baum“ befreie Du,<br/>Reinige uns von allem „Sauerteig“,<br/>Rüst uns für Gott und Mensch als Speise zu.<br/>',NULL,47828,8);
INSERT INTO stanza VALUES('G334','9','Lass uns in Gottes Leben wachsen mehr,<br/>Wandle uns um und bau uns auf in Dir,<br/>Zu Deinem Leib, zu Deinem Königreich,<br/>Dass wir zu Deinem Ausdruck werden hier.<br/>',NULL,47829,9);
INSERT INTO stanza VALUES('G335','1','Die Einheit der Gemeind ist nur,<br/>Dass wir in Einheit leben;<br/>Der Geist, der nun in uns wohnt, hat<br/>Die Einheit uns gegeben.<br/>Die Einheit dieses Geistes ist<br/>Das Friedens-Band, so heißt es;<br/>Auf diesem Glauben fußt sie, der<br/>Den Gläubigen gemein ist.<br/>',NULL,47830,1);
INSERT INTO stanza VALUES('G335','2','Der Glaube aller Heiligen<br/>Besteht allein aus Christus<br/>Und dem Erlösungswerk von Ihm,<br/>Nach Gottes ew''gem Ratschluss.<br/>Darin sind alle Heil''gen eins,<br/>Auf diesem Grund sie stehen;<br/>Durch diesen teuren Glauben konnte<br/>Die Gemeind entstehen.<br/>',NULL,47831,2);
INSERT INTO stanza VALUES('G335','3','Da die Gemeinde eine ist,<br/>Nur einzig Christi Herde,<br/>Muss jederorts ihr Ausdruck nur<br/>Eins sein hier auf der Erde.<br/>Die Elemente sind auch eins –<br/>Ein Leib, ein Geist und ein Herr,<br/>Ein Glaube, Taufe, Hoffnung auch,<br/>Ein Gott und Vater aller.<br/>',NULL,47832,3);
INSERT INTO stanza VALUES('G335','4','Der Grund von der Gemeinde ist<br/>Die Einheit einzigartig,<br/>Nur dieser Stand der Einheit ist<br/>Allein dem Geist gefällig.<br/>Die Einheit zu bewahren stets<br/>Sich die Gemeinden üben,<br/>Durch die Gemeinschaft aufgebaut,<br/>Kann nichts die Einheit trüben.<br/>',NULL,47833,4);
INSERT INTO stanza VALUES('G335','5','Bewirke, dass wir eifrig sind,<br/>Die Einheit zu bewahren,<br/>Dass auf der Einheit Grund wir das<br/>Leib-Leben reich erfahren;<br/>So kann Dein tiefster Herzenswunsch<br/>Nun Wirklichkeit hier werden,<br/>Mög Gottes ew''ger Vorsatz bald<br/>Vollendet sein auf Erden.<br/>',NULL,47834,5);
INSERT INTO stanza VALUES('G336','1','Christus, Gottes Sohn, und Sein Erlösungswerk:<br/>Das ist unser Glaube, unser Augenmerk;<br/>All die andern Lehren sind nicht Teil davon,<br/>Christus ist der Glaube, Sein Werk und Person.<br/>',NULL,47835,1);
INSERT INTO stanza VALUES('G336','2','Jede andre Lehre, unrecht angewandt<br/>Ist ein „Wind der Lehre“, bringt der Einheit Schand,<br/>Bläst die Heil''gen weg von Christus, ihrem Haupt,<br/>Christi Leib zerstört und Aufbau nicht erlaubt.<br/>',NULL,47836,2);
INSERT INTO stanza VALUES('G336','3','Lasst die Lehren fallen, Lehren allerhand,<br/>An den Glauben haltet, Einheit unser Stand;<br/>In dem Herrn, dem Geist, sind wir ganz eins fürwahr,<br/>Lasst uns diese Einheit halten immerdar.<br/>',NULL,47837,3);
INSERT INTO stanza VALUES('G336','4','An der Wahrheit – Christus – halten wir uns fest,<br/>Sodass wir entkommen Sekten von dem Selbst,<br/>Und in allem wachsen wir ins Haupt hinein,<br/>Dieses bringt das Wachstum und die Fülle ein.<br/>',NULL,47838,4);
INSERT INTO stanza VALUES('G336','5','In des Glaubens Einheit wachsen wir stets mehr,<br/>Und den „Wind der Lehr“ verachten wir vielmehr;<br/>Haltet Christus fest als Geist der Wirklichkeit,<br/>Für des Leibs Wachstum in der Einigkeit.<br/>',NULL,47839,5);
INSERT INTO stanza VALUES('G337','1','Du, Herr Jesus, bist der Eckstein,<br/>Der verworfen worden war;<br/>Gott durch Auferstehung setzt'' Dich,<br/>Seinen Augen unschätzbar.<br/>Juden, Heiden sind errettet,<br/>Ineinander fügst Du sie;<br/>Du baust uns zu Deiner Wohnung,<br/>Neuer Mensch in Harmonie.<br/>',NULL,47840,1);
INSERT INTO stanza VALUES('G337','2','Der geschlagne Fels bist Du, Herr,<br/>Unsren Durst stillst Du daraus,<br/>Dass der schwache Mensch auf Dir steht,<br/>So baust Du mit uns Dein Haus.<br/>Du, in Zion, bist der Grundstein,<br/>Der geprüft und sicher ist;<br/>Und als Fels für die Gemeinde<br/>Auch ihr Fundament Du bist.<br/>',NULL,47841,2);
INSERT INTO stanza VALUES('G337','3','Fest auf Dir steht die Gemeinde,<br/>Stürme toben und vergehn;<br/>Hadestore ihr nichts antun,<br/>Felsenfest bleibt sie bestehn.<br/>Die Gemeinde löst und bindet,<br/>Da sie Deine Vollmacht hat,<br/>Führt die Menschen in Dein Reich ein,<br/>Setzt sie frei von Satans Macht.<br/>',NULL,47842,3);
INSERT INTO stanza VALUES('G337','4','Du bist der lebend''ge Stein, Herr,<br/>Auserwählt – Dich schätzen wir;<br/>Wir als die lebend''gen Steine<br/>Haben die Natur von Dir.<br/>Aufgebaut zu einem Tempel,<br/>Deiner Wohnung wunderbar;<br/>Und als Priesterschaft nun bringen<br/>Wir Dir Opfergaben dar.<br/>',NULL,47843,4);
INSERT INTO stanza VALUES('G337','5','Herr, Du bist der Sohn von David,<br/>Du den Tempel Gottes baust;<br/>Nun als König und als Priester<br/>Führst Du Deinen Auftrag aus.<br/>Du regierst für Gott als König,<br/>Menschen unter Gott stellst Du;<br/>Und als Priester führst Du Menschen<br/>Nun hinein in Gottes Ruh.<br/>',NULL,47844,5);
INSERT INTO stanza VALUES('G337','6','Deine Vollmacht geht vom Thron aus,<br/>Gottes Frieden ihm entspringt;<br/>Die Gemeinschaft, die im Strom fließt,<br/>Reich versorgt, Vermehrung bringt.<br/>Sind die beiden ausgeglichen,<br/>Führn sie Gottes Vorsatz aus;<br/>Du bist König, Du bist Priester,<br/>Darum baust Du Gottes Haus.<br/>',NULL,47845,6);
INSERT INTO stanza VALUES('G337','7','Du bist Gott, doch wurdest Fleisch, Herr,<br/>Gott und Mensch wohnt nun in Dir;<br/>Als der Tempel offenbartest<br/>Gottes Herrlichkeit Du hier.<br/>Auch ist die Gemeinde heute<br/>Gott und Mensch vermengt fürwahr;<br/>Jedes Glied mit Gott vermengt ist<br/>Für Sein Haus, wie wunderbar.<br/>',NULL,47846,7);
INSERT INTO stanza VALUES('G337','8','In Dir als der ewigen Wohnung<br/>Bleiben wir in Ewigkeit;<br/>Wir in Dir stets sicher wohnen,<br/>Leben in Dir allezeit.<br/>Du bist unser Heiligtum, Herr,<br/>Mensch und Gott wohnt jetzt in Dir;<br/>Gottes Gegenwart bist Du, wo<br/>Unaufhörlich preisen wir.<br/>',NULL,47847,8);
INSERT INTO stanza VALUES('G337','9','Ja, der Eckstein, Grundstein, Schlussstein,<br/>Fels, lebendiger Stein bist Du;<br/>Wohnung, Heiligtum, Erbauer<br/>Und Gemeinde noch dazu.<br/>Preis sei Dir, so reich bist Du, Herr,<br/>Staunend sehen wir es hier!<br/>Bau uns als lebend''ge Steine<br/>Miteinander auf in Dir.<br/>',NULL,47848,9);
INSERT INTO stanza VALUES('G338','1','Preis sei Dir, Herr, für Deinen Plan,<br/>Wir dürfen Deine Wohnung sein;<br/>Du lebst in uns, füllst uns mit Dir,<br/>Dein Ausdruck ist im Sohn allein.<br/>',NULL,47849,1);
INSERT INTO stanza VALUES('G338','2','Du schufst uns, Herr, in Deinem Bild,<br/>Uns gabst Du die Autorität,<br/>Doch ganz aus Ton sind wir gemacht,<br/>Ohne ein Körnchen Göttlichkeit.<br/>',NULL,47850,2);
INSERT INTO stanza VALUES('G338','3','Nehmen wir Dich als Leben auf,<br/>Deine Natur durch Gnad Du gibst;<br/>Mit Dir vermengt, zum Ausdruck kommt<br/>Dein Leib so herrlich, den Du liebst.<br/>',NULL,47851,3);
INSERT INTO stanza VALUES('G338','4','Unsere Seele erneure, füll<br/>Mit Deinem Leben immerzu,<br/>Bis wir als Perle, Edelstein<br/>Tragen Dein Bild, sind gleich wie Du.<br/>',NULL,47852,4);
INSERT INTO stanza VALUES('G338','5','Dir gleich geformt zu werden ist<br/>Niemals für unsren Ruhm gedacht,<br/>Doch für Dein Haus hast Du aus uns<br/>Wertvolles Material gemacht.<br/>',NULL,47853,5);
INSERT INTO stanza VALUES('G338','6','Dir geben wir uns hin, o Herr,<br/>Nimm uns in Deine weise Hand;<br/>Brich uns und bau uns in Dir auf,<br/>Bring uns als Haus auf Deinen Stand.<br/>',NULL,47854,6);
INSERT INTO stanza VALUES('G338','7','Unseren alten Menschen brich,<br/>Schleife an jeder Eigenheit,<br/>Dass wir nicht unabhängig sind,<br/>Sondern in Einheit allezeit.<br/>',NULL,47855,7);
INSERT INTO stanza VALUES('G338','8','Als Deine Braut dann werden wir<br/>Voll Freud in Deiner Kammer weiln,<br/>Wo Deine Liebe überfließt;<br/>Oh, wie wirst Du zufrieden sein!<br/>',NULL,47856,8);
INSERT INTO stanza VALUES('G339','1','Welch ein Töpfer bist Du, Herr,<br/>Und ein Baumeister dazu!<br/>Herrlich formst Du Dein Gefäß,<br/>Mit dem Haus in Sicht baust Du.<br/>Herr, ich bin ein Mensch aus Ton<br/>Und ein neu belebter Stein,<br/>Dein Gefäß, das Dich enthält,<br/>Um Dein Tempel hier zu sein.<br/>',NULL,47857,1);
INSERT INTO stanza VALUES('G339','2','Du Gefäße, ganz aus Ton,<br/>Wandelst um, machst sie so reich;<br/>Durch Dein Leben, rein wie Gold,<br/>Sind wir Edelsteinen gleich.<br/>Schließlich, durch Dein Bauwerk, Herr,<br/>Werden wir zu Deiner Braut;<br/>Du und wir – in einem Leib,<br/>Ganz zufrieden, wie vertraut!<br/>',NULL,47858,2);
INSERT INTO stanza VALUES('G339','3','Was Dein Herz sich wünscht, sind nicht<br/>Lose Steine, ganz allein;<br/>Du willst sie zusammenbaun,<br/>Deine Wohnung hier zu sein.<br/>Du, der Allerreichste, willst<br/>Die Gemeinde aufgebaut,<br/>Dass Dein ganzer Reichtum hell<br/>Voll und ganz aus ihr erstrahlt.<br/>',NULL,47859,3);
INSERT INTO stanza VALUES('G339','4','Keine geistliche Person,<br/>Die für sich allein nur lebt,<br/>Korp''ratives Leben nur<br/>Dir gefällt und Dich erhebt.<br/>Lose Glieder, abgetrennt,<br/>Wenig Ausdruck sind allein,<br/>Nur Dein aufgebauter Leib,<br/>Der kann Deine Fülle sein.<br/>',NULL,47860,4);
INSERT INTO stanza VALUES('G339','5','Mit den Heil''gen bau mich auf,<br/>Will nicht unabhängig sein,<br/>Füg mich ein nach Deinem Plan,<br/>Wie es passt, so setz mich ein.<br/>Auf Erfahrung poch ich nicht,<br/>Gaben machen mich nicht dreist;<br/>Ich geb alles für Dein Haus,<br/>Dass Du, Herr, verherrlicht seist.<br/>',NULL,47861,5);
INSERT INTO stanza VALUES('G340','1','Frei vom Selbst und Adams Wesen,<br/>Bau mich auf, o Herr, ich fleh,<br/>Mit den Heiligen zum Tempel,<br/>Wo die Herrlichkeit wir sehn.<br/>Von der Eigenart befrei mich,<br/>Auch von Unabhängigkeit,<br/>Dass wir Deine Wohnung sind, Herr,<br/>Unsre ganze Lebenszeit.<br/>',NULL,47862,1);
INSERT INTO stanza VALUES('G340','2','Durch das Fließen Deines Lebens<br/>Werd ich umgewandelt jetzt,<br/>Abgestimmt mit allen Gliedern,<br/>Aufgebaut und eingesetzt;<br/>Respektier des Leibes Ordnung,<br/>So wie Du willst, funktionier,<br/>Ich möcht dienen, andren helfen,<br/>Deinen Plan erfüllen hier.<br/>',NULL,47863,2);
INSERT INTO stanza VALUES('G340','3','In Erkenntnis und Erfahrung<br/>Will ich nicht erhoben sein,<br/>Durch die Unterordnung werd ich<br/>Ausgeglichen durch den Leib;<br/>Halt das Haupt fest, denn von Ihm aus<br/>Wächst der Leib, wie''s Ihm gefällt,<br/>Der durch Sehnen und Gelenke<br/>Seinen Leib zusammenhält.<br/>',NULL,47864,3);
INSERT INTO stanza VALUES('G340','4','Stärk durch Deinen Geist mich täglich<br/>In den innren Menschen, Herr,<br/>Dass ich Deine Liebe sehe,<br/>Deine Maße kenne mehr;<br/>Ich genieße Deinen Reichtum,<br/>Bis Du Deine Fülle siehst,<br/>Wachse zum gereiften Mann hin,<br/>Bis Dein Leib vollendet ist.<br/>',NULL,47865,4);
INSERT INTO stanza VALUES('G340','5','Ich ersehne, Herr, den Aufbau<br/>Im Leib Christi, der Gemeind,<br/>Dass durch dies Gefäß gemeinsam<br/>Deine Herrlichkeit erscheint.<br/>Deine Braut, die Stadt, so herrlich,<br/>Zeigt sich auf der Erde bald;<br/>Deinen Wert zum Ausdruck bringt sie,<br/>Wie ein Leuchter hell erstrahlt.<br/>',NULL,47866,5);
INSERT INTO stanza VALUES('G341','1','Du bist all mein Leben,<br/>Herr, in mir lebst Du,<br/>Und die Fülle Gottes<br/>Schenkst Du mir dazu.<br/>Durch Dein heil''ges Wesen<br/>Heilig machst Du mich,<br/>Durch die Auferstehung<br/>Sieg erfahre ich.<br/>',NULL,47867,1);
INSERT INTO stanza VALUES('G341','2','Nun, Dein fließend Leben<br/>Hell erleuchtet mich,<br/>Und es bringt Gemeinschaft<br/>Stets im Geist mit sich;<br/>Was Du forderst, stillt es,<br/>Und was mangelt mir;<br/>Reinigt mich vollkommen,<br/>Festigt mich in Dir.<br/>',NULL,47868,2);
INSERT INTO stanza VALUES('G341','3','Deine Salbung dringe<br/>Tief in mich hinein,<br/>Geist und Seele sollen<br/>Ganz durchsättigt sein;<br/>Wandle jeden Teil um,<br/>Bis Dein Bild ich trag,<br/>Bis Dein Leben mich zur<br/>Reife bringen mag.<br/>',NULL,47869,3);
INSERT INTO stanza VALUES('G341','4','Deines Lebens Fülle<br/>Strömt so reich und frei,<br/>Bringt mir stets Erfrischung<br/>Meine Kraft stets sei.<br/>Tod ist ganz verschlungen,<br/>Schwaches Kraft bezieht,<br/>Ketten sind zerbrochen,<br/>Schwermut wird zum Lied.<br/>',NULL,47870,4);
INSERT INTO stanza VALUES('G341','5','Herr, ich will mich geben<br/>Völlig und ganz Dir,<br/>Dass Dein Herzenssehnen<br/>Wird erfüllt in mir.<br/>Nun die Selbst-Reformen<br/>Hinfort lasse ich,<br/>So ist meine Mühe<br/>Dir nicht hinderlich.<br/>',NULL,47871,5);
INSERT INTO stanza VALUES('G341','6','Ich will ganz aufhören,<br/>Mich umsonst zu mühen,<br/>Leben soll mich ändern,<br/>In die Freiheit führn.<br/>Bau mich auf mit andern,<br/>Bis in uns Du siehst,<br/>Deinen vollen Ausdruck,<br/>Du verherrlicht bist.<br/>',NULL,47872,6);
INSERT INTO stanza VALUES('G342','1','Befreie meinen Geist! Das brauch ich sehr:<br/>Im Geist mich mit den Heiligen verein;<br/>Nicht mehr alleine möcht ich suchen Dich,<br/>Vom Selbst befreit, will mich dem Aufbau weihn.<br/>',NULL,47873,1);
INSERT INTO stanza VALUES('G342','2','Befreie meinen Geist! Das bitt ich sehr,<br/>Ich möchte nicht mehr selbstbezogen sein;<br/>So tief im Selbst ich schon seit langem bin,<br/>Nur Du allein kannst mich davon befrein.<br/>',NULL,47874,2);
INSERT INTO stanza VALUES('G342','3','Befreie meinen Geist! Das bet ich sehr,<br/>Aus meinem Selbst befrei, das mich verschließt;<br/>Dein Geist soll fließen frei aus mir heraus,<br/>Dass Deine Gegenwart zu sehen ist.<br/>',NULL,47875,3);
INSERT INTO stanza VALUES('G342','4','Befreie meinen Geist! Dies möcht ich sehr,<br/>Zurückgezogenheit von mir nun weich!<br/>Privates Suchen brachte Armut nur,<br/>Rett mich vom Selbst, im Leib bin ich so reich.<br/>',NULL,47876,4);
INSERT INTO stanza VALUES('G342','5','Befreie meinen Geist! Das such ich sehr,<br/>Dass ich im Selbst nicht mehr gefangen bin;<br/>Durch Satans List betrogen nimmermehr,<br/>Ich Deine Unbegrenztheit schmeck forthin.<br/>',NULL,47877,5);
INSERT INTO stanza VALUES('G342','6','Befreie meinen Geist! Ersehne ich,<br/>Dass Geist nie mehr vom Selbst gebunden sei;<br/>Mit allen Heiligen vermeng ich mich,<br/>Genieße Dich und preise Dich dabei.<br/>',NULL,47878,6);
INSERT INTO stanza VALUES('G343','1','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich fleh zu Dir, o Herr,<br/>Er fließe frei!<br/>Vergangnes lass ich sein,<br/>Die Mauern reiße ein,<br/>Will meinen Geist befrein,<br/>Er fließe frei!<br/>',NULL,47879,1);
INSERT INTO stanza VALUES('G343','2','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich ruf Dich an, o Herr,<br/>Er fließe frei!<br/>Nicht Selbstzufriedenheit,<br/>Noch Selbstgefälligkeit,<br/>Mein Geist sei ganz bereit,<br/>Er fließe frei!<br/>',NULL,47880,2);
INSERT INTO stanza VALUES('G343','3','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Inständig bitt ich Dich,<br/>Er fließe frei!<br/>Hochmütig nicht zu sein,<br/>Stolz nehm mich nicht mehr ein,<br/>Ich fließe nun so rein,<br/>Fließ immerzu!<br/>',NULL,47881,3);
INSERT INTO stanza VALUES('G343','4','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Hierzu ersuch ich Dich,<br/>Er fließe frei!<br/>Absondern ist vorbei,<br/>Von Selbstverbessrung frei,<br/>Mein Geist gedämpft nicht sei,<br/>Doch kräftig fließ!<br/>',NULL,47882,4);
INSERT INTO stanza VALUES('G343','5','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich bitt Dich, lieber Herr,<br/>Er fließe frei!<br/>Mein Selbstvertrauen brich,<br/>Vom Thron des Selbst weich ich,<br/>Im Geist durchströmst Du mich,<br/>Mit Leben, Herr.<br/>',NULL,47883,5);
INSERT INTO stanza VALUES('G343','6','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Mein Beten, Herr, erhör,<br/>Er fließe frei!<br/>Oh, nicht nur Du und ich,<br/>Mit andren baue mich,<br/>Vermeng uns innerlich,<br/>Im Geist, o Herr.<br/>',NULL,47884,6);
INSERT INTO stanza VALUES('G344','1','Wie ich mich sehne nach Gemeinschaft!<br/>Vermeng mich mit den Heiligen,<br/>Von Unabhängigkeit errett mich,<br/>Baue mich auf mit anderen.<br/>',NULL,47885,1);
INSERT INTO stanza VALUES('G344','2','Wie ich mich sehne nach Gemeinschaft!<br/>Öffne Du völlig meinen Geist,<br/>Auch von Absonderung errett mich,<br/>Dass Dich mein Geist mit andern preist.<br/>',NULL,47886,2);
INSERT INTO stanza VALUES('G344','3','Wie ich mich sehne nach Gemeinschaft!<br/>Freiheit mein Geist in Dir gewinnt,<br/>Von Selbst-Betrug, o Herr, befrei mich,<br/>Und alle Hürden überwind.<br/>',NULL,47887,3);
INSERT INTO stanza VALUES('G344','4','Wie ich mich sehne nach Gemeinschaft!<br/>Dass ich im Geist mit andern bet;<br/>Von aller Unechtheit befrei mich,<br/>Wahre Gemeinschaft schenk uns stets.<br/>',NULL,47888,4);
INSERT INTO stanza VALUES('G344','5','Wie ich mich sehne nach Gemeinschaft!<br/>Ich möchte Deine Vollmacht sehn;<br/>Beim Dienen suche ich Gemeinschaft,<br/>Koordiniert wir vorwärts gehn.<br/>',NULL,47889,5);
INSERT INTO stanza VALUES('G344','6','Herr, stille unsres Herzens Sehnsucht,<br/>Reg andre zur Gemeinschaft an,<br/>Dass wir bald Deinen Bau vollenden,<br/>Nach Deinem Herzenswunsch und Plan.<br/>',NULL,47890,6);
INSERT INTO stanza VALUES('G345','1','Alle Priester Steine sind<br/>Für das Aufbauwerk von Gott;<br/>Um heut aufgebaut zu sein,<br/>Beten lernen tut uns Not.<br/>',NULL,47891,1);
INSERT INTO stanza VALUES('G345','chorus','Komm ins Allerheiligste,<br/>Und berühr im Geist den Thron;<br/>Fließt der Herr nun im Gebet,<br/>Wird das Aufbauwerk getan.<br/>',NULL,47892,2);
INSERT INTO stanza VALUES('G345','2','Lasst uns alle Priester sein,<br/>Steine, die lebendig sind;<br/>Wer als Priester dienen will,<br/>Sicher seine Funktion find''t.<br/>',NULL,47893,3);
INSERT INTO stanza VALUES('G345','3','Zelt und Priester damals schon<br/>Mussten stets zusammen gehn;<br/>Priester, die den Dienst ausführn,<br/>Mit dem Zelt in Einheit stehn.<br/>',NULL,47894,4);
INSERT INTO stanza VALUES('G345','4','Gottes Haus, das geistlich ist,<br/>Und die Priester stehn vereint;<br/>Heut ist es der Priesterdienst,<br/>Der dem Haus Aufbau verleiht.<br/>',NULL,47895,5);
INSERT INTO stanza VALUES('G345','5','In die Priester legte Gott<br/>Die Substanz fürs Werk hinein;<br/>Wenn sie treu den Dienst erfülln<br/>Wird Sein Haus bald fertig sein.<br/>',NULL,47896,6);
INSERT INTO stanza VALUES('G345','6','Gott und Mensch in eins zu baun,<br/>Ist ihr Werk in dieser Zeit;<br/>Göttliche Gemeinschaft bringt<br/>Uns in die Einmütigkeit.<br/>',NULL,47897,7);
INSERT INTO stanza VALUES('G345','7','Sind wir alle aufgebaut,<br/>Beten stets vermengt im Geist,<br/>Werden wir zur Priesterschaft,<br/>Die mit Opferdienst Dich speist.<br/>',NULL,47898,8);
INSERT INTO stanza VALUES('G345','8','Schenk uns Gnade, Herr, dass wir<br/>Schätzen unsern Priesterdienst;<br/>Wenn im Geist wir dienen Dir,<br/>Die Gemeinde Du gewinnst.<br/>',NULL,47899,9);
INSERT INTO stanza VALUES('G346','1','Entschleiere mein Herz, o Herr,<br/>Und Offenbarung schenk im Licht;<br/>Auf das, was Du erlangen willst,<br/>Schenk ungetrübte Sicht.<br/>',NULL,47900,1);
INSERT INTO stanza VALUES('G346','2','Durch Offenbarung zeigst Du mir<br/>Die Kraft, die auferweckte Dich;<br/>Nehm ich die Kraft im Glauben an,<br/>Führt zur Gemeind sie mich.<br/>',NULL,47901,2);
INSERT INTO stanza VALUES('G346','3','Mit Kraft hast Du mich ganz befreit<br/>Von dem, was ablenkt in der Welt;<br/>Hinein in die Gemeinde hat<br/>Mich Deine Kraft gestellt.<br/>',NULL,47902,3);
INSERT INTO stanza VALUES('G346','4','Und nun in der Gemeinde, Herr,<br/>Leb Du als die Person in mir;<br/>Mein äußrer Mensch nimmt täglich ab,<br/>Mein Herz wird neu in Dir.<br/>',NULL,47903,4);
INSERT INTO stanza VALUES('G346','5','Thron Du in meinem Herzen nun,<br/>Gekreuzigt wurde ich mit Dir;<br/>Erneuert ist mein innrer Mensch,<br/>Du, Herr, wohnst nun in mir.<br/>',NULL,47904,5);
INSERT INTO stanza VALUES('G346','6','Verleugnet jedes Glied sich selbst,<br/>Dann wird Dein Leib, o Herr, erkannt;<br/>Genießen wir Dich als Person,<br/>Der neue Mensch erscheint.<br/>',NULL,47905,6);
INSERT INTO stanza VALUES('G346','7','Gemeindeleben ist der eine<br/>Neue Mensch, am Ort sichtbar;<br/>Als korp''rativer Mensch erscheinst<br/>Du hier im Leib fürwahr.<br/>(Die beiden letzten Zeilen jeder Strophe zwei Mal wiederholen.)<br/>',NULL,47906,7);
INSERT INTO stanza VALUES('G347','1','Lieblich ist Deine Wohnung, Herr!<br/>Nach Deinem Vorhof sehn ich mich;<br/>Mein Geist sucht Deine Gegenwart,<br/>Mein Herz und Fleisch, sie rufen Dich.<br/>',NULL,47907,1);
INSERT INTO stanza VALUES('G347','2','Brandopfer- und Weihrauchaltar<br/>Diese Altäre sind der Ort,<br/>Wo selbst der Sperling hat Sein Haus,<br/>Ihr Nest erbaut die Schwalbe dort.<br/>',NULL,47908,2);
INSERT INTO stanza VALUES('G347','3','Menschen, wie Vögel, schwach und klein,<br/>Finden in Deinem Hause Ruh,<br/>Sie sind bedeckt mit Deinem Blut<br/>Und Weihrauch freut sie immerzu.<br/>',NULL,47909,3);
INSERT INTO stanza VALUES('G347','4','Glückselig sind die Menschen, Herr,<br/>Die Dir vertraun als ihrem Lohn;<br/>In ihren Herzen haben sie<br/>Gebahnte Wege nach Zion.<br/>',NULL,47910,4);
INSERT INTO stanza VALUES('G347','5','Wenn sie durchs Tränental hinziehn,<br/>Machen sie es zum Quellenort;<br/>Regen das Tal mit Segen deckt,<br/>Barmherzigkeit fließt immerfort.<br/>',NULL,47911,5);
INSERT INTO stanza VALUES('G347','6','Sie gehn von Kraft zu Kraft voran,<br/>In Zion kommen sie vor Gott;<br/>Suchen beständig Dich allein,<br/>Beziehen Deine Gnade dort.<br/>',NULL,47912,6);
INSERT INTO stanza VALUES('G347','7','Besser ein Tag in Deinem Hof,<br/>Als sonstwo Tausend, mir gefällt;<br/>Lieber an Deiner Schwelle stehn,<br/>Als wohnen in des Bösen Zelt.<br/>',NULL,47913,7);
INSERT INTO stanza VALUES('G347','8','Sonne und Schild bist Du für uns,<br/>Gnade gibst Du und Herrlichkeit;<br/>Deine Person und Gegenwart,<br/>Erquicken mich zu jeder Zeit.<br/>',NULL,47914,8);
INSERT INTO stanza VALUES('G347','9','Kein Gutes, Herr, enthältst Du vor<br/>Dem, der geht in Aufrichtigkeit;<br/>Glückselig, der auf Dich vertraut<br/>Mit Gnade und mit Herrlichkeit.<br/>',NULL,47915,9);
INSERT INTO stanza VALUES('G348','1','Ich liebe Deine Wohnung, Herr,<br/>Deine Gemeind, so lieb;<br/>Sie – Deines Herzens Freude hier –<br/>Allein Dir Ruhe gibt.<br/>',NULL,47916,1);
INSERT INTO stanza VALUES('G348','2','Für sie gabst Du Dich hin, o Herr,<br/>Dass sie Dir ganz gehör;<br/>Auch ihretwegen geb ich mich<br/>Für Deinen Herzbegehr.<br/>',NULL,47917,2);
INSERT INTO stanza VALUES('G348','3','Du bist mein Leben, und sie ist<br/>Mein Lebenswandel hier;<br/>Für sie verleugne ich mich selbst,<br/>Sie sei erfüllt mit Dir.<br/>',NULL,47918,3);
INSERT INTO stanza VALUES('G348','4','Deine geliebte Braut ist sie,<br/>Du in dem Leib gesehn;<br/>Sie – meines Herzens Freude hier,<br/>Auf die ich mich stets lehn.<br/>',NULL,47919,4);
INSERT INTO stanza VALUES('G348','5','In ihr versorgst Du mich so reich,<br/>So dass mir nichts mehr fehlt;<br/>In ihr bin ich Dein Eigentum,<br/>Was Dich zufriedenstellt.<br/>',NULL,47920,5);
INSERT INTO stanza VALUES('G348','6','Ich liebe Deine Wohnung, Herr,<br/>Deine Gemeind, Dein Haus;<br/>Hier möcht ich leben ewiglich,<br/>Nie will ich mehr hinaus.<br/>',NULL,47921,6);
INSERT INTO stanza VALUES('G349','1','Oh, schau, wie gut und lieblich ist''s,<br/>Wenn Brüder gleich gesinnt!<br/>Es ist wie Öl auf Aarons Haupt,<br/>Zum Saum hinab es rinnt;<br/>Wie Tau des Hermons fällt herab<br/>Auf Zions Berge dort,<br/>So ordnet Gott den Segen an,<br/>Schenkt Leben immerfort.<br/>',NULL,47922,1);
INSERT INTO stanza VALUES('G350','1','Jesus, der liebliche Hirte,<br/>Führte uns aus dem Pferch raus,<br/>Auf Seine saftige Weide;<br/>Hier sind wir endlich zu Haus!<br/>',NULL,47923,1);
INSERT INTO stanza VALUES('G350','chorus','In der Gemeinde<br/>Schmecken wir reichen Genuss!<br/>Hier wohnen wir in der Einheit,<br/>Sodass Gott uns segnen muss.<br/>',NULL,47924,2);
INSERT INTO stanza VALUES('G350','2','Wir warn zerstreut und zerspalten,<br/>Unterernährt, ohne Mut;<br/>Ins gute Land führte Gott uns,<br/>In unsren Geist, o wie gut!<br/>',NULL,47925,3);
INSERT INTO stanza VALUES('G350','3','Jesus Selbst ist unsre Weide,<br/>Er ist die Speise, die nährt;<br/>Wenn Er die Herde versammelt,<br/>Ihn jedes Schaf reich erfährt.<br/>',NULL,47926,4);
INSERT INTO stanza VALUES('G350','4','Bleiben wir auf dem Gebirge,<br/>Wo frischer Tau uns umhüllt,<br/>Löschen den Durst an der Quelle,<br/>Wasser des Lebens uns füllt.<br/>',NULL,47927,5);
INSERT INTO stanza VALUES('G350','5','Wir ruhn und freun uns in Christus,<br/>Hunger und Furcht gibt es nicht;<br/>Sicher sind hier alle Schafe,<br/>Schauen in Sein Angesicht.<br/>',NULL,47928,6);
INSERT INTO stanza VALUES('G351','1','Zuhause sind wir,<br/>Die Gemeinde zeigt''s hier,<br/>Und wir freun uns im Herrn allezeit;<br/>Unser Leben ist Er,<br/>Streiten tun wir nicht mehr,<br/>Sind daheim und in Einmütigkeit!<br/>',NULL,47929,1);
INSERT INTO stanza VALUES('G351','chorus','Hier in der Gemeind<br/>Sind wir endlich zu Haus und vereint,<br/>Und den ganzen Tag lang<br/>Preisen wir mit Gesang,<br/>Lobt für Christus und Seine Gemeind!<br/>',NULL,47930,2);
INSERT INTO stanza VALUES('G351','2','Sie ist Gottes Ruh<br/>Und Sein Schatz noch dazu –<br/>Oh, wie freut Sich der Herr immerfort!<br/>Unser Herz ist Sein Haus,<br/>Und der Feind muss hinaus,<br/>Gottes Herrlichkeit füllt diesen Ort.<br/>',NULL,47931,3);
INSERT INTO stanza VALUES('G351','chorus','Hier in der Gemeind<br/>Nimmt nunmehr Gottes Suchen ein End,<br/>Und den ganzen Tag lang<br/>Preisen wir mit Gesang,<br/>Lobt für Christus und Seine Gemeind!<br/>',NULL,47932,4);
INSERT INTO stanza VALUES('G352','1','Hier in der Gemeinde hören wir den Klang des Lebens,<br/>Christi Freud ermuntert, unsre Herzen setzt in Brand;<br/>Babylon und Nichtigkeiten locken uns vergebens,<br/>Wir sind ja zu Hause in unsrem Land.<br/>',NULL,47933,1);
INSERT INTO stanza VALUES('G352','chorus','Wir versammeln uns im Geiste,<br/>Sind in Christus eins am Grund;<br/>Uns versammeln als Familie,<br/>Welch wunderbarer Fund!<br/>In der Vermengung der Gemeinden überall tun wir dies kund,<br/>O ja, denn Christus ist unser Land!<br/>',NULL,47934,2);
INSERT INTO stanza VALUES('G352','2','Tote Lehre und die Gaben sind für uns vergangen,<br/>Mehr noch alles Weltliche, das sich in uns befand;<br/>Seit die Liebe Christi unsre Herzen hat gefangen,<br/>Bleiben wir in Christus, in unsrem Land.<br/>',NULL,47935,3);
INSERT INTO stanza VALUES('G352','3','„Ich will die Gemeinde hier auf diesen Felsen bauen.“<br/>Seht! Sein Vorsatz wird erfüllt, wie Er es hat geplant;<br/>Jedes Glied setzt Er im Leib, wie Er es gern will schauen,<br/>Baut uns auf in Christus, in unsrem Land.<br/>',NULL,47936,4);
INSERT INTO stanza VALUES('G352','4','Die Gemeinden gehn voran wie''s nie ist da gewesen,<br/>Tu, o Herr, noch Großes über Bitten und Verstand,<br/>Bis die Erde widerhallt und ruft beim Beten-Lesen,<br/>Halleluja! Christus ist unser Land.<br/>',NULL,47937,5);
INSERT INTO stanza VALUES('G353','1','Zum Gemeindeleben-Garten brachte Gott uns souverän!<br/>Um den Christus zu erfahrn, der hier gedeiht!<br/>Hier die Heiligen, ganz einmütig, genießen reich den Herrn;<br/>Er ist neu und frisch und voller Lieblichkeit.<br/>',NULL,47938,1);
INSERT INTO stanza VALUES('G353','chorus','Ich bin glücklich hier an diesem Ort,<br/>Wachse in der Gnade immerfort!<br/>Nichts ist schöner als zu essen froh vom Baum des Lebens hier,<br/>Und das frische Leben trinken mundet mir.<br/>',NULL,47939,2);
INSERT INTO stanza VALUES('G353','2','Keine Schule, noch Fabrik, noch Kathedrale sehen wir,<br/>Doch den Garten, wo der Herr nun pflanzt und sät;<br/>Darin setzte Er uns korp''rativ, Sein Garten sind wir hier,<br/>Wo Er uns zum Wachsen bringt von früh bis spät.<br/>',NULL,47940,3);
INSERT INTO stanza VALUES('G353','3','Im Gemeindeleben-Garten wächst viel Frucht an einem Baum,<br/>Voller Leben, frei verfügbar jederzeit.<br/>Sei so einfach, nicht verhärtet, lass die Meinung – iss vom Baum!<br/>Lass uns gerne schmecken Jesu Lieblichkeit!<br/>',NULL,47941,4);
INSERT INTO stanza VALUES('G353','4','Nebst dem Baum gibt''s auch das Wasser, Gott in Christus fließt zu uns,<br/>Alle Trockenheit und Streit beendet Er;<br/>Halleluja! Denn im Garten fließt der Herr im Geist zu uns,<br/>Und so wachsen wir im Leben immer mehr.<br/>',NULL,47942,5);
INSERT INTO stanza VALUES('G353','5','Bist du dankbar und zufrieden, dass dich Christus trug hierhin,<br/>Wo Sein Reichtum und die Süße endlos fließt?<br/>Sei so glücklich, voller Freude und im Geist froh feste Ihn,<br/>Dann bringt Gottes Garten Frucht, die Er genießt.<br/>',NULL,47943,6);
INSERT INTO stanza VALUES('G354','1','Tiefer, tiefer, tief ins Kreuz von Jesus,<br/>Tiefer lass mich gehn;<br/>Tod und Leben gehen stets zusammen;<br/>Tiefer geh, wir flehn.<br/>Vertief den Strom, o Herr,<br/>In uns wirk täglich mehr;<br/>Geh tiefer, beten wir,<br/>Mach uns völlig neu in Dir.<br/>',NULL,47944,1);
INSERT INTO stanza VALUES('G354','2','Höher, höher, hoch im Leben Jesu;<br/>Höher wolln wir stehn.<br/>Durch Dein Leben gehn wir nun viel höher –<br/>Lasst uns höher gehn.<br/>Uns höher bring, o Herr –<br/>Uns wandle um noch mehr –<br/>Dein Lebensstrom ist reich,<br/>Macht uns immer mehr Dir gleich.<br/>',NULL,47945,2);
INSERT INTO stanza VALUES('G354','3','Wachse, wachse, wachs in uns, Herr Jesus,<br/>Wachse noch so viel;<br/>Täglich wachs in unsrem Lebenswandel –<br/>Denn das ist Dein Ziel.<br/>Nun wachs in uns, o Herr,<br/>Nimm zu in uns noch mehr;<br/>Mehr Wissen schafft Verdruss,<br/>Nur Dein Leben wachsen muss.<br/>',NULL,47946,3);
INSERT INTO stanza VALUES('G354','4','Lebe, lebe, leb durch uns, Herr Jesus,<br/>Lebe jeden Tag;<br/>Großes, Kleines, Du, Herr, bist in allem,<br/>Was da kommen mag.<br/>Lebt Christus allezeit,<br/>Lebt Ihn in Wirklichkeit;<br/>Ruft Seinen Namen an,<br/>Dass Er uns durchdringen kann.<br/>',NULL,47947,4);
INSERT INTO stanza VALUES('G354','5','Als Person, Person in uns lebt Jesus,<br/>Wohnt in uns und lebt;<br/>Er ist unser Denken, Fühlen, Wollen,<br/>Ihm die Ehre gebt!<br/>Als unsere Person<br/>In unsren Herzen wohn;<br/>Uns Leben schenkst nur Du<br/>Als Person, Herr, immerzu.<br/>',NULL,47948,5);
INSERT INTO stanza VALUES('G354','6','Heute in den örtlichen Gemeinden<br/>Reich der Strom uns quillt:<br/>Tiefer, höher, breiter; der Gemeinde<br/>Unser Wachstum gilt.<br/>Ja, die Gemeinden heut<br/>Sind Christi Abbild treu;<br/>Das Selbst verleugnen wir,<br/>Dass Dein Leib Dich groß macht hier.<br/>',NULL,47949,6);
INSERT INTO stanza VALUES('G354','7','Aufbau, Aufbau, so erfolgt der Aufbau,<br/>Dies verhieß der Herr:<br/>Die Erfahrung Christi bringt den Aufbau –<br/>Täglich immer mehr.<br/>Herr, wachs und breit Dich aus,<br/>Und bau uns auf zum Haus;<br/>Zu Edelstein mach Lehm,<br/>Für das Neu Jerusalem.<br/>',NULL,47950,7);
INSERT INTO stanza VALUES('G354','8','Kommen, kommen, Jesus wird bald kommen,<br/>Kommt für Seine Braut,<br/>Die sich in Gemeinden vorbereitet,<br/>Und nach Ihm ausschaut.<br/>Herr Jesus, komm zurück –<br/>Zu Dir uns bald entrück;<br/>Wir preisen Dich und flehn,<br/>Komm zurück! Komm schnell! Amen!<br/>',NULL,47951,8);
INSERT INTO stanza VALUES('G355','1','Gedenk, wie David schwur:<br/>„Ich will nicht in mein Haus gehn,<br/>Zu ruhen liegt mir fern,<br/>Noch Schlaf die Augen sehen;<br/>Ich suche einen Ort für Dich,<br/>Ja, einen Ort für Dich.“<br/>Gott ist allein, will ein Daheim<br/>Für Ihn und uns soll''s sein.<br/>',NULL,47952,1);
INSERT INTO stanza VALUES('G355','2','Wie blind warn wir, o Herr!<br/>Nur mit uns allein beschäftigt,<br/>Doch Gottes Haus liegt wüst –<br/>Brich durch und wend uns ständig;<br/>Wir gehn auf das Gebirge dort,<br/>Holn Holz und baun das Haus;<br/>Wir sagen nicht: „Nicht meine Pflicht.“<br/>Kommt lasst uns heute baun!<br/>',NULL,47953,2);
INSERT INTO stanza VALUES('G355','3','Entgegen dieser Zeit<br/>Erwecke für Dein Haus, Herr,<br/>So wie zu Davids Zeit –<br/>Ein''n Überrest für Dich, Herr,<br/>Der baut und wirkt in Deinem Haus,<br/>Wie segensreich ist dies!<br/>Dein Herzenswunsch ist unser Wunsch –<br/>Wir kommen, Herr, und baun.<br/>',NULL,47954,3);
INSERT INTO stanza VALUES('G355','4','In jenen, die Du rufst,<br/>Erweck die Last zu geben<br/>Sich selbst für diesen Bau –<br/>Und nur für ihn zu leben;<br/>Die Hades-Pforten machtlos sind,<br/>Wenn die Gemeind gebaut!<br/>Knapp ist die Zeit, wer ist bereit?<br/>Herr, bau, o bau in uns!<br/>(Die letzten vier Zeilen wiederholen.)<br/>',NULL,47955,4);
INSERT INTO stanza VALUES('G356','1','In Jerusalem sind wir,<br/>Babylon ist fern von hier,<br/>Nun versammelt sind in Dir,<br/>Oh, Herrlichkeit dem Herrn!<br/>Sich nach Lehren niemand sehnt,<br/>Jede Meinung abgelehnt,<br/>Geist und Seele sind getrennt,<br/>In der örtlichen Gemeind.<br/>',NULL,47956,1);
INSERT INTO stanza VALUES('G356','chorus','Halleluja! Halleluja!<br/>Wir sind in Einmütigkeit,<br/>Für den Bau des Herrn bereit.<br/>Halleluja! Halleluja!<br/>In den örtlichen Gemeinden leben wir!<br/>',NULL,47957,2);
INSERT INTO stanza VALUES('G356','2','Gott erlangt zurück stets mehr,<br/>Wahre Priester braucht Er sehr –<br/>Christus leben – Sein Begehr,<br/>Oh, Herrlichkeit dem Herrn!<br/>Sie sind sättigt mit dem Herrn,<br/>Christus wird als Lohn sie ehrn,<br/>Sie baun Gottes Haus so gern<br/>In der örtlichen Gemeind.<br/>',NULL,47958,3);
INSERT INTO stanza VALUES('G356','3','Und im Königtum – nun seht –<br/>Herrscht des Herrn Autorität,<br/>Hier nur Sein Regieren geht,<br/>Oh, Herrlichkeit dem Herrn!<br/>Uns dem Geist wir beugen hin<br/>Der Gemeinde zum Gewinn –<br/>Das verlangt Er unbedingt<br/>In der örtlichen Gemeind.<br/>',NULL,47959,4);
INSERT INTO stanza VALUES('G356','4','Hin auf den Altar ich muss<br/>Alles legen – mein Beschluss.<br/>Welcher Duft, des Herrn Genuss!<br/>Oh, Herrlichkeit dem Herrn!<br/>Ernst es jeder von uns meint,<br/>Wir sind ganz für die Gemeind,<br/>Alles andre wird verneint<br/>In der örtlichen Gemeind.<br/>',NULL,47960,5);
INSERT INTO stanza VALUES('G356','5','Nun das Fundament besteht –<br/>Gottes Herrlichkeit hier seht!<br/>Voller Freude vorwärts geht,<br/>Oh, Herrlichkeit dem Herrn!<br/>Unser starker Ruf erschallt –<br/>Jeder hört, wie er nachhallt,<br/>Satan schlagt nun mit Gewalt<br/>In der örtlichen Gemeind.<br/>',NULL,47961,6);
INSERT INTO stanza VALUES('G357','1','Dort in Babylon, in Gefangenschaft,<br/>Ja, der Herr hat unsren Geist erweckt!<br/>Uneins und zerstreut, blind und ohne Kraft,<br/>Ja, der Herr hat unsren Geist erweckt!<br/>Weckt auf! Weckt auf!<br/>Ja, der Herr hat unsren Geist erweckt!<br/>',NULL,47962,1);
INSERT INTO stanza VALUES('G357','2','Raus aus Babylon, voller Sekten bunt,<br/>Aus der Spaltung, stehn wir alle auf.<br/>Babylon ist nicht unser rechter Grund,<br/>Aus der Spaltung, stehn wir alle auf.<br/>Steht auf!  Steht auf!<br/>Aus der Spaltung, stehn wir alle auf.<br/>',NULL,47963,2);
INSERT INTO stanza VALUES('G357','3','Nach Jerusalem, vom Gefangensein,<br/>Gott ist mit uns, ziehn wir alle hoch!<br/>Einheit gibt es an diesem Ort allein,<br/>Gott ist mit uns, ziehn wir alle hoch!<br/>Zieht hoch! Zieht hoch!<br/>Gott ist mit uns, ziehn wir alle hoch!<br/>',NULL,47964,3);
INSERT INTO stanza VALUES('G357','4','Schalen christusvoll, Schüsseln geistererfüllt<br/>All des Herrn Gefäße bringt nun hoch!<br/>Bringt sie zur Gemeind, Gott gefällt es wohl –<br/>All des Herrn Gefäße bringt nun hoch!<br/>Bringt hoch! Bringt hoch!<br/>All des Herrn Gefäße bringt nun hoch!<br/>',NULL,47965,4);
INSERT INTO stanza VALUES('G357','5','In Jerusalem, auserwähltem Ort,<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>Alle einmütig dient zusammen dort,<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>Baut auf! Baut auf!<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>',NULL,47966,5);
INSERT INTO stanza VALUES('G358','1','Es ist die Zeit den Tempel des Herrn nun aufzubaun,<br/>Die örtlichen Gemeinden vollendet anzuschaun.<br/>Für unser Haus nicht Zeit ist''s, solang Sein Haus wüst steht –<br/>Oh, Brüder, lasst nicht zu, dass mehr Zeit vergeht!<br/>',NULL,47967,1);
INSERT INTO stanza VALUES('G358','chorus','Seid stark, seid stark, die Wohnung baut für Ihn!<br/>Der Herr der Heerscharn ist mit uns, verherrlicht Sich darin!<br/>Seid stark, seid stark, baut einmütig und gern,<br/>Dass alle Völker sehen dann den Tempel unsres Herrn.<br/>',NULL,47968,2);
INSERT INTO stanza VALUES('G358','2','Der Herr der Heerscharn sagte: „Beachtet, wie''s euch geht,<br/>Ihr sät und erntet wenig, auf Eigenes nur seht.<br/>Den Berg besteigt, bringt fleißig das Material hierhin,<br/>Und baut Mein Haus, so dass Ich verherrlicht bin.“<br/>',NULL,47969,3);
INSERT INTO stanza VALUES('G358','3','Ihr Überrest, ihr Priester, erfüllt nun eure Pflicht –<br/>Der Herr ist unter uns, was ein andrer sagt, gilt nicht,<br/>Im Geist erweckt und brennend lasst uns die Arbeit tun;<br/>Ein jeder seinen Anteil zum Herrn bringt nun.<br/>',NULL,47970,4);
INSERT INTO stanza VALUES('G358','4','Gott sagte: „Ich erfüll dieses Haus mit Herrlichkeit“,<br/>Die Sehnsucht aller Völker erstrahlt aus ihm allzeit.<br/>Die Herrlichkeit des Hauses wird größer als sie war,<br/>An ihr schenkt Er uns Anteil für immerdar.<br/>',NULL,47971,5);
INSERT INTO stanza VALUES('G359','1','Wir sind für die Wied''rerlangung<br/>Der Gemeind am Ort;<br/>Wir sind für die Wied''rerlangung<br/>Von der Stadt und von der Erd.<br/>Auf dem Grund der Einheit stehn wir,<br/>Einheit in dem Herrn,<br/>Und so bauen wir den Tempel<br/>Unsres Gottes gern.<br/>',NULL,47972,1);
INSERT INTO stanza VALUES('G359','chorus','Wir sind für des Herrn,<br/>Wir sind für des Herrn,<br/>Sind für des Herrn Wiedererlangung!<br/>Wir sind für des Herrn,<br/>Wir sind für des Herrn,<br/>Sind für des Herrn Wiedererlangung!<br/>',NULL,47973,2);
INSERT INTO stanza VALUES('G359','2','Wir sind für die Wied''rerlangung,<br/>Lieben sie fürwahr;<br/>Wenn wir unsren Geist nun üben,<br/>Wird die Vision so klar.<br/>Babylon ist schon gefallen<br/>Und besiegt der Feind,<br/>Auf dem Ortsgrund aufgebaut ist die<br/>Örtliche Gemeind.<br/>',NULL,47974,3);
INSERT INTO stanza VALUES('G360','1','Siehst du sie in allen Städten,<br/>Nehmen ein am Ort den Stand?<br/>Seht! In diesen goldnen Leuchtern<br/>Gott nun Sein Zuhause fand.<br/>',NULL,47975,1);
INSERT INTO stanza VALUES('G360','chorus','Die Gemeind am Ort ist Gottes Wahl heute,<br/>Hier sind die Heiligen eins!<br/>Die Gemeind am Ort ist Gottes Wahl heute,<br/>Hier sind die Heiligen eins!<br/>',NULL,47976,2);
INSERT INTO stanza VALUES('G360','2','Siehst du sie in der Versammlung?<br/>Lob und Dank wird dargebracht;<br/>Jeder Bruder, Schwester teilt aus,<br/>Hier wird Christus groß gemacht.<br/>',NULL,47977,3);
INSERT INTO stanza VALUES('G360','3','Hörst du, wie sie betend lesen,<br/>Leben atmen ein durchs Wort?<br/>Beten, preisen, trinken, essen,<br/>Reich genießen sie Gott dort!<br/>',NULL,47978,4);
INSERT INTO stanza VALUES('G360','4','Wie sie rufen: „O Herr Jesus“!<br/>Diesen Namen lieben sie!<br/>Wenn sie Seine Herrschaft kundtun,<br/>Freun sie sich in Harmonie.<br/>',NULL,47979,5);
INSERT INTO stanza VALUES('G360','5','Hörst du ihre Hallelujas,<br/>Wie ein starker Donnerstoß?<br/>Halleluja! Halleluja!<br/>Werft den Feind hinab furchtlos!<br/>',NULL,47980,6);
INSERT INTO stanza VALUES('G360','6','Wie die Heiligen wandern aus jetzt!<br/>Lobt den Herrn, Er geht voran,<br/>Breitet sich an jeden Ort aus,<br/>Dass Er schon bald kommen kann!<br/>',NULL,47981,7);
INSERT INTO stanza VALUES('G360','7','Bald kommt Er für die Gemeinde,<br/>Die Er liebt und jetzt aufbaut;<br/>Er schmückt nun in den Gemeinden<br/>Seine wunderbare Braut.<br/>',NULL,47982,8);
INSERT INTO stanza VALUES('G360','chorus','Ohne Flecken, Runzeln ist die Gemeinde,<br/>Hier Gottes Herrlichkeit wohnt!<br/>Ohne Flecken, Runzeln ist die Gemeinde,<br/>Hier Gottes Herrlichkeit wohnt!<br/>',NULL,47983,9);
INSERT INTO stanza VALUES('G361','1','Ja, die Gemeind am Ort<br/>Ist Gottes Grund;<br/>Hier Christi Leben uns<br/>Reich segnet rundherum.<br/>„Im Geist und auf dem Grund“ –<br/>Das Schlachtgeschrei;<br/>Hier überwinden wir den Feind, führen<br/>Das Königreich herbei.<br/>',NULL,47984,1);
INSERT INTO stanza VALUES('G362','1','Brennen, brennen, ja, wir brennen,<br/>Stets zu unsrem Geist uns wenden,<br/>Eins für Deinen ew''gen Vorsatz, eins sind im Geist;<br/>Auf dem Grund des Ortes stehen wir,<br/>Unsre Einheit zeigen hier,<br/>Nur ein Leib, doch viele Glieder, Christus ist das Haupt.<br/>',NULL,47985,1);
INSERT INTO stanza VALUES('G362','chorus','Christus und die Gemeind,<br/>Christus und die Gemeind,<br/>Christus und die Gemeinde lieben wir,<br/>O Herr! Hallelujah! Ja, wir<br/>Geben unser Leben Dir,<br/>Für den Aufbau Deines Leibes,<br/>Bau uns auf in Liebe hier.<br/>',NULL,47986,2);
INSERT INTO stanza VALUES('G362','2','Atmen, atmen, ja, wir leben,<br/>Neues Leben will Er geben,<br/>Umgewandelt werden wir, das Alte wird neu;<br/>Altheit atmen aus soeben,<br/>Atmen ein das neue Leben,<br/>Ja, wir atmen Jesus ein, erfüllt mit Ihm zu sein.<br/>',NULL,47987,3);
INSERT INTO stanza VALUES('G363','1','Christus rief uns einst zu Sich,<br/>Nochmals ruft Er dich und mich,<br/>Lasst Ihn länger nicht im Stich!<br/>Überwind!<br/>Die Gemeinde niederging,<br/>Weil sie sehr am Wissen hing,<br/>Doch das Leben ist gering,<br/>Überwind!<br/>',NULL,47988,1);
INSERT INTO stanza VALUES('G363','chorus','Überwind! Überwind!<br/>Das gefallne Christentum nun überwind!<br/>Eignes Werk beiseite leg,<br/>Lehre, die zertrennt, lass weg;<br/>Stets den Herrn zu essen pfleg –<br/>Überwind!<br/>',NULL,47989,2);
INSERT INTO stanza VALUES('G363','2','Essen ist für uns bestimmt,<br/>Uns dem Bild des Herrn gleich trimmt,<br/>Und dem Feind den Sieg ganz nimmt –<br/>Überwind!<br/>Komm, den Lebensbaum genieß,<br/>Müh und Lehren doch vergiss!<br/>Täglich Christus reichlich iss –<br/>Überwind!<br/>',NULL,47990,3);
INSERT INTO stanza VALUES('G363','3','Lehren wandeln nicht die Seel,<br/>Lehren sind nicht Gottes Ziel,<br/>Christus essen – das tut viel! –<br/>Überwind!<br/>Überwind und nimm Ihn ein,<br/>In Gemeinschaft und allein,<br/>Stets dein Fest der Herr will sein –<br/>Überwind!<br/>',NULL,47991,4);
INSERT INTO stanza VALUES('G363','4','Esst, gebärt das männlich Kind,<br/>Esst, dann kommt der Herr geschwind;<br/>Essen stärkt, und euch sehr dient –<br/>Überwind!<br/>Seid das Kind, nach dem Er schaut,<br/>Die Gemeinde, so vertraut,<br/>Schließlich Seine liebe Braut –<br/>Überwind!<br/>',NULL,47992,5);
INSERT INTO stanza VALUES('G364','1','Die Gemeinde Jesu Liebe hat für dich,<br/>Sie ist sanft und lieblich, süß und brüderlich;<br/>Warum einsam bleiben? Freunde jeder braucht!<br/>Die Gemeinde Jesu dich in Freude taucht.<br/>',NULL,47993,1);
INSERT INTO stanza VALUES('G364','2','Die Gemeinde Jesu Leben hat für dich,<br/>Warm wie Sommersonne, taufrisch, morgendlich;<br/>Warum dich nun fürchten, warum Angst sich regt?<br/>Die Gemeinde Jesu die Erkauften pflegt.<br/>',NULL,47994,2);
INSERT INTO stanza VALUES('G364','3','Die Gemeinde Jesu Arbeit hat für dich,<br/>So wie Engel täten gern und freuten sich;<br/>Warum stehst du müßig, große Tat ersinnst?<br/>Die Gemeinde Jesu braucht auch deinen Dienst.<br/>',NULL,47995,3);
INSERT INTO stanza VALUES('G364','4','Die Gemeinde Jesu hat auch Platz für dich,<br/>Herrlich, hell und friedlich, recht und brüderlich;<br/>Warum ziellos wandern, warum straucheln fern?<br/>Die Gemeinde Jesu nimmt dich auf ganz gern.<br/>',NULL,47996,4);
INSERT INTO stanza VALUES('G365','1','Wenn immer wir versammelt sind,<br/>Den Uberfluss von Christus bringt,<br/>Dies ist die Speise, die Gott nimmt,<br/>So stelln wir Christus aus.<br/>',NULL,47997,1);
INSERT INTO stanza VALUES('G365','chorus','Wir stellen Christus aus,<br/>Wir stellen Christus aus;<br/>Den Überfluss bringt zur Gemeind,<br/>So stellen Christus aus.<br/>',NULL,47998,2);
INSERT INTO stanza VALUES('G365','2','In Christus leben, kämpfen wir,<br/>Und Christus fleißig kultiviern,<br/>Den Überfluss Gott präsentiern,<br/>So stelln wir Christus aus.<br/>',NULL,47999,3);
INSERT INTO stanza VALUES('G365','3','Im Lebenswandel Christus sei<br/>Allein das Element dabei,<br/>Bei Treffen dann auch jederlei,<br/>So stelln wir Christus aus.<br/>',NULL,48000,4);
INSERT INTO stanza VALUES('G365','4','Sind wir versammelt hier am Ort<br/>Und jeder bringt ein frisches Wort,<br/>Genießen wir den Herrn sofort,<br/>So stelln wir Christus aus.<br/>',NULL,48001,5);
INSERT INTO stanza VALUES('G365','5','Den Auferstandnen Gott darbringt,<br/>Dem Aufgefahrnen Lobpreis singt,<br/>Dann Gottes Herz vor Freude springt,<br/>So stellen wir Christus aus.<br/>',NULL,48002,6);
INSERT INTO stanza VALUES('G365','6','Der Mittelpunkt und Wirklichkeit,<br/>Die Atmosphäre und Dienst dabei,<br/>In der Versammlung allezeit<br/>ist: Christus auszustelln.<br/>',NULL,48003,7);
INSERT INTO stanza VALUES('G365','7','Gebet und Zeugnis, Dienst im Wort,<br/>Und der Gemeinschaft hier und dort,<br/>Den Gaben geht nur ein Ziel vor:<br/>Um Christus auszustelln.<br/>',NULL,48004,8);
INSERT INTO stanza VALUES('G365','8','Dem Vater alle Ehre gebt,<br/>Und Christus, Seinen Sohn, erhebt,<br/>So der Versammlung Ziel erstrebt,<br/>Und Christus ausgestellt.<br/>',NULL,48005,9);
INSERT INTO stanza VALUES('G366','1','In Geist und in Wahrhaftigkeit<br/>Wir beten Dich, Herr, an;<br/>Wie Christus, Gottes Sohn, es lehrt,<br/>In Ihm wir Dir nun nahn.<br/>',NULL,48006,1);
INSERT INTO stanza VALUES('G366','2','Wir danken Gott, ein Geist ist Er<br/>So nah und wunderbar;<br/>Im Leben ist berührbar nun,<br/>Wir beten an fürwahr.<br/>',NULL,48007,2);
INSERT INTO stanza VALUES('G366','3','Gott schuf uns drinnen einen Geist,<br/>So beten wir Ihn an;<br/>Kein kämpfen, dienen äußerlich,<br/>Im Innern uns Ihm nahn.<br/>',NULL,48008,3);
INSERT INTO stanza VALUES('G366','4','Der Herr hat uns nun neugeborn,<br/>Erneuert Sinn und Herz,<br/>Als Leben wohnt Er tief in uns,<br/>Uns Anbetung gibt jetzt.<br/>',NULL,48009,4);
INSERT INTO stanza VALUES('G366','5','Nach dem Empfinden innerlich<br/>Anbetung bringen wir,<br/>Gesalbt vom Geist wir strahlen aus<br/>Nun Seine Fülle hier.<br/>',NULL,48010,5);
INSERT INTO stanza VALUES('G366','6','In Schatten betet nicht mehr an,<br/>Doch in Wahrhaftigkeit,<br/>Den Vater stets in Christus preist,<br/>Er ist die Wirklichkeit.<br/>',NULL,48011,6);
INSERT INTO stanza VALUES('G366','7','Wir bringen Gott den Christus dar,<br/>Den wir stets neu erfahrn,<br/>Und freuen uns mit Gott an Ihm<br/>In Liebe wir uns nahn.<br/>',NULL,48012,7);
INSERT INTO stanza VALUES('G366','8','Im Geist und in Wahrhaftigkeit<br/>Den Herrn lobpreisen wir;<br/>Versammelt um den Gnadenthron,<br/>Anbetung fließt zu Dir.<br/>',NULL,48013,8);
INSERT INTO stanza VALUES('G367','1','Üb den Geist, befrei ihn!<br/>Eignes Denken flieh;<br/>Trefft euch miteinander,<br/>Christi Leib nur sieh.<br/>',NULL,48014,1);
INSERT INTO stanza VALUES('G367','2','Üb den Geist, befrei ihn!<br/>Förmlichkeiten lass;<br/>Teil aus Gottes Leben,<br/>Christus so erfass!<br/>',NULL,48015,2);
INSERT INTO stanza VALUES('G367','3','Üb den Geist, befrei ihn!<br/>Miteinander dient;<br/>Weist ab eure Meinung,<br/>Und den Herrn verkündt.<br/>',NULL,48016,3);
INSERT INTO stanza VALUES('G367','4','Üb den Geist und lass das<br/>Seelenleben gehn;<br/>Hilf damit auch andern,<br/>Gott wird dir beistehn.<br/>',NULL,48017,4);
INSERT INTO stanza VALUES('G367','5','Sei befreit im Geist von<br/>Selbstgerechtigkeit,<br/>Von der Selbstverdammnis,<br/>Selbstbezogenheit.<br/>',NULL,48018,5);
INSERT INTO stanza VALUES('G367','6','Sei befreit im Geist von<br/>Eigenwillen, Stolz,<br/>Eigenliebe, Ehre,<br/>Er trug sie ans Holz.<br/>',NULL,48019,6);
INSERT INTO stanza VALUES('G367','7','Üb den Geist, befrei ihn!<br/>Feinde sind besiegt;<br/>Stets Sein Blut uns reinigt,<br/>Kraft im Namen liegt.<br/>',NULL,48020,7);
INSERT INTO stanza VALUES('G367','8','Übe deinen Geist, um<br/>Christus zu berührn,<br/>Durch den Geist beständig<br/>Sein Wort absorbiern.<br/>',NULL,48021,8);
INSERT INTO stanza VALUES('G367','9','Durch den Geist bezeuge<br/>Christi Herrlichkeit;<br/>Durch den Geist erfährt der<br/>Mensch Zufriedenheit.<br/>',NULL,48022,9);
INSERT INTO stanza VALUES('G367','10','Üb den Geist, befrei ihn!<br/>Das brauch ich so sehr!<br/>Üb den Geist, befrei ihn!<br/>Führe uns so, Herr!<br/>',NULL,48023,10);
INSERT INTO stanza VALUES('G368','1','Durch jedes Glied des Leibes<br/>Wird Christus offenbar,<br/>Wenn jedes die Funktion übt,<br/>Stellt dies die Fülle dar.<br/>Ein Publikum gibt''s keines,<br/>Aktiv ja Glieder sind,<br/>Und keiner Tod verbreitet,<br/>Ein jeder bringt Gewinn.<br/>',NULL,48024,1);
INSERT INTO stanza VALUES('G368','2','Im Team wolln wir nichts ausführn<br/>In Unabhängigkeit,<br/>Vielmehr koordinieren,<br/>Abhängig sein allzeit;<br/>Tun nichts durch eignes Wählen,<br/>Im Strom wolln wir stets stehn,<br/>Und ohne abzulenken,<br/>Den Weg des Geistes gehn.<br/>',NULL,48025,2);
INSERT INTO stanza VALUES('G368','3','Auf Christus ausgerichtet,<br/>Er ist das Zentrum hier,<br/>Mit Ihm Gemeinschaft pflegen,<br/>Sein''n Reichtum teilen wir.<br/>Ja, unser Haupt ist Christus,<br/>Sein Leib sind wir fürwahr,<br/>Und sämtliches Aktiv-Sein<br/>Muss Ihn nur offenbarn.<br/>',NULL,48026,3);
INSERT INTO stanza VALUES('G368','4','Wenn wir so aufgebaut sind,<br/>Keine Kritik übst du;<br/>Wir üben uns in Liebe,<br/>Einander rüsten zu.<br/>Ja, wer vom Selbst befreit ist<br/>Und vom Natürlichsein,<br/>Übt seinen Geist in Gnade<br/>Für Christi Leib allein.<br/>',NULL,48027,4);
INSERT INTO stanza VALUES('G369','1','Auf! Christi Soldaten!<br/>Zieht aus wie zum Krieg,<br/>Bleibt am Kreuz mit Jesus,<br/>Er führt stets zum Sieg.<br/>Christus als der König<br/>Führt im Kampf uns an;<br/>Vorwärts, seht die Banner<br/>Drängen schon voran!<br/>',NULL,48028,1);
INSERT INTO stanza VALUES('G369','chorus','Auf! Christi Soldaten!<br/>Zieht aus wie zum Krieg,<br/>Bleibt am Kreuz mit Jesus,<br/>Er führt euch zum Sieg.<br/>',NULL,48029,2);
INSERT INTO stanza VALUES('G369','2','Bei dem Namen Jesus<br/>Satans Heere fliehn,<br/>Auf! Christi Soldaten!<br/>Hin zum Sieg wir ziehn!<br/>Zittern muss der Hades,<br/>Wenn das Lob erklingt:<br/>Brüder hebt die Stimme,<br/>Siegeslieder singt!<br/>',NULL,48030,3);
INSERT INTO stanza VALUES('G369','3','Das Gemeinde-Heer geht<br/>Froh und kühn voran,<br/>Brüder, folgt den Heil''gen,<br/>Geht in ihrer Bahn;<br/>Wir sind nicht zerspalten,<br/>Nein, ein Leib sind wir –<br/>Eins im Geist, im Glauben,<br/>Ewig eins in Dir.<br/>',NULL,48031,4);
INSERT INTO stanza VALUES('G369','4','Kronen, Throne schwinden,<br/>Reiche kommen, gehn;<br/>Doch Gemeinde Jesu<br/>Ewig bleibt bestehn.<br/>Hades-Tore schlagen<br/>Die Gemeinde nicht;<br/>Die Verheißung Christi<br/>Hält, was Er verspricht.<br/>',NULL,48032,5);
INSERT INTO stanza VALUES('G369','5','Vorwärts, all ihr Völker!<br/>Preis sei Ihm allein;<br/>In den Siegeslobpreis<br/>Stimmt nun alle ein.<br/>Christus, unsrem König,<br/>Sei die Herrlichkeit;<br/>Mensch und Engel lobt Ihn<br/>In all Ewigkeit.<br/>',NULL,48033,6);
INSERT INTO stanza VALUES('G370','1','Geht voran, geht voran, geht im Geist mit Ihm voran,<br/>Halleluja! Gemeinden, voran!<br/>Geht voran, geht voran, geht im Geist mit Ihm voran,<br/>Halleluja! Gemeinden, voran!<br/>Die Gemeinde Er<br/>Stellt jetzt ganz wieder her<br/>Als der siebenfach verstärkte Geist.<br/>Die Welt wird sehn,<br/>Wohin wir immer gehn,<br/>Dass der Herr heute geht noch voran!<br/>',NULL,48034,1);
INSERT INTO stanza VALUES('G371','1','Kämpft doch für Jesus den Herrn!<br/>Einmütig nehmt Sein Leben ein gern!<br/>Niemals fürchtet Gottes Feind;<br/>Siegreich zermalmt ihn doch vereint!<br/>Für die Gemeinde bleibt im Gebet,<br/>Dass jeder auch im Geist vorangeht,<br/>Als der eine neue Mensch<br/>Erfülln wir Gottes Wunsch!<br/>(Amen! Halleluja!)<br/>',NULL,48035,1);
INSERT INTO stanza VALUES('G372','1','Immer heißt mein Wort zum Feinde: „Nein“,<br/>Doch zum Vater immer: „Ja“,<br/>So kann Er erfolgreich ausführn,<br/>Was Er lang voraus ersah;<br/>Schenke mir, Herr, Deine Vollmacht,<br/>Wenn ich nun gehorche Dir,<br/>Deinen Vorsatz zu erfüllen,<br/>Durch des Geistes Kraft in mir.<br/>',NULL,48036,1);
INSERT INTO stanza VALUES('G372','2','Immer heißt mein Wort zum Feinde: „Nein“,<br/>Doch zum Vater immer: „Ja“,<br/>Dies ist immer meine Haltung,<br/>Stärk mich, Herr, und sei mir nah;<br/>Wenn gehorsam ich Ihm folge,<br/>Vor dem Feind schützt Gott mich hier;<br/>Wenn ich höre Deinen Auftrag,<br/>Schenke Deine Gnade mir.<br/>',NULL,48037,2);
INSERT INTO stanza VALUES('G372','3','Immer heißt mein Wort zum Feinde: „Nein“,<br/>Doch zum Vater immer: „Ja“,<br/>Völlig möcht ich Ihm gehorchen,<br/>Sei auch schweres Leiden da.<br/>Doch wenn Du, Herr, mich errettest,<br/>Und mich führst mit Deinem Stab,<br/>Wird mich keine Trübsal hindern,<br/>Und die Gegnerschaft zieht ab.<br/>',NULL,48038,3);
INSERT INTO stanza VALUES('G373','1','Wir nehmen ein das Land, das Gott gegeben hat!<br/>Lasst Christus unsren Lebenswandel sein!<br/>Die Ausrüstung, es einzunehmen, gab Er uns –<br/>Das Blut, das Wort, den Geist und die Gemeind.<br/>',NULL,48039,1);
INSERT INTO stanza VALUES('G373','chorus','(Schwestern singen)<br/>Lasst uns das Land einnehmen! Brüder,<br/>Gott gab es schon in unsre Hand.<br/>Wir überwinden und wir gewinnen,<br/>Das reiche, wunderbare Land!<br/>(Brüder singen)<br/>Lasst uns das Land einnehmen! Schwestern,<br/>Auf alles, was Er gab, gebt Acht.<br/>Hört auf Sein Bitten, folgt Seinen Schritten,<br/>Er hat an alles gut gedacht!<br/>',NULL,48040,2);
INSERT INTO stanza VALUES('G373','2','Das Blut ist da! Weil Christus unser Opfer ist,<br/>Er gab Sich hin, erfüllte Gottes Plan;<br/>So treten wir nun kühn zum Gnadenthron hinzu<br/>Und wenden Christi Blut beständig an.<br/>',NULL,48041,3);
INSERT INTO stanza VALUES('G373','3','Das Wort ist da! Das täglich unsre Speise ist,<br/>Vermischt mit Glauben; sagen wir: „Amen!“<br/>In uns wird es nun täglich zum gesprochnen Wort<br/>Das uns bewahrt, im Geist den Weg zu gehn.<br/>',NULL,48042,4);
INSERT INTO stanza VALUES('G373','4','Der Geist ist da! Der Geist der Wirklichkeit in uns,<br/>Egal wie du dich fühlst, ist Er bereit;<br/>Er wohnt in uns, lehrt uns zu wohnen auch in Ihm,<br/>Uns führt hinein, in Seine Wirklichkeit.<br/>',NULL,48043,5);
INSERT INTO stanza VALUES('G373','5','Wir haben die Gemeinde! Nehmen ein vereint<br/>Die Fülle dieser großen Wirklichkeit;<br/>Ja, Christus, unser allumfassend gutes Land,<br/>Erobern wir zusammen allezeit!<br/>',NULL,48044,6);
INSERT INTO stanza VALUES('G374','1','Kämpf den Kampf im Leibe Christi,<br/>Niemals kämpfe ihn allein;<br/>Kämpf den Kampf auf Seinem Throne,<br/>Haupt und Leib sind immer eins.<br/>',NULL,48045,1);
INSERT INTO stanza VALUES('G374','chorus','Kämpf den Kampf im Leibe Christi!<br/>Durch das Haupt und Sein Verdienst;<br/>Fest und sicher steh im Leibe,<br/>So den Sieg du kommen siehst.<br/>',NULL,48046,2);
INSERT INTO stanza VALUES('G374','2','Gottes Waffenrüstung ist ja<br/>Nicht für Einzelne gedacht;<br/>Wenn du kämpfst in Seinem Leibe,<br/>Wirst erfahren ihre Macht.<br/>',NULL,48047,3);
INSERT INTO stanza VALUES('G374','3','Die Gemeinde fest in Christus<br/>Über Satan hat den Sieg;<br/>Nur der aufgebaute Leib hält<br/>Bösen Mächten stand im Krieg.<br/>',NULL,48048,4);
INSERT INTO stanza VALUES('G374','4','Nun im Leib und durch das Hauptsein<br/>Sitz im Himmel immerfort;<br/>Kämpfe gegen böse Geister<br/>Und die Fürstentümer dort.<br/>',NULL,48049,5);
INSERT INTO stanza VALUES('G374','5','Als ein Glied an Seinem Leibe<br/>Mit den Brüdern steh für Gott;<br/>Bet im Geist und fordre ständig<br/>Seinen Sieg durch Christi Blut.<br/>',NULL,48050,6);
INSERT INTO stanza VALUES('G374','6','In den Himmeln überwinde<br/>In der Kraft all Seiner Macht;<br/>Als Soldat in der Armee kämpf,<br/>Du gewinnst im Herrn die Schlacht.<br/>',NULL,48051,7);
INSERT INTO stanza VALUES('G374','7','Kämpfe weiter stets im Leibe,<br/>Dann kehrn große Siege ein,<br/>Bind und lös nach Gottes Willen,<br/>Feinde werden Speise sein.<br/>',NULL,48052,8);
INSERT INTO stanza VALUES('G375','1','Ein feste Burg ist unser Gott,<br/>Ein gute Wehr und Waffen.<br/>Er hilft uns stets aus aller Not,<br/>Die uns hat stark getroffen.<br/>Der alte böse Feind,<br/>Mit Ernst er es jetzt meint;<br/>Mächtig und voller List<br/>Sein grausam Rüstung ist,<br/>Auf Erd ist nicht seinsgleichen.<br/>',NULL,48053,1);
INSERT INTO stanza VALUES('G375','2','Mit unsrer Macht ist nichts getan,<br/>Wir sind gar bald verloren;<br/>Es streit für uns der rechte Mann,<br/>Den Gott hat selbst erkoren.<br/>Fragst du, wer der ist?<br/>Er heißt Jesus Christ,<br/>Der Herr Zebaoth,<br/>Und ist kein andrer Gott;<br/>Das Feld muss Er behalten.<br/>',NULL,48054,2);
INSERT INTO stanza VALUES('G375','3','Und wenn die Welt voll Teufel wär<br/>Und wollt'' uns gar verschlingen,<br/>So fürchten wir uns nicht so sehr,<br/>Es soll uns doch gelingen.<br/>Der Fürst dieser Welt,<br/>Wie saur er sich stellt,<br/>Tut er uns doch nichts;<br/>Das macht, er ist gericht:<br/>Ein Wörtlein kann ihn fällen.<br/>',NULL,48055,3);
INSERT INTO stanza VALUES('G375','4','Das Wort sie sollen lassen stahn<br/>Und kein Dank dazu haben.<br/>Er ist bei uns wohl auf dem Plan<br/>Mit Seinem Geist und Gaben.<br/>Nehmen sie den Leib,<br/>Gut, Ehr, Kind und Weib,<br/>Lass fahren dahin!<br/>Sie haben''s kein Gewinn;<br/>Das Reich muss uns doch bleiben.<br/>',NULL,48056,4);
INSERT INTO stanza VALUES('G376','1','Dein Name, Herr, ist unser Stand,<br/>Ja, unser Sieg ist er;<br/>Auf uns verlassen wir uns nicht,<br/>Auf Dich nur schaun wir, Herr.<br/>Die Waffen sind hier nicht aus Fleisch:<br/>Der Geist ist unser Schwert,<br/>Wir legen Gottes Rüstung an,<br/>Und kämpfen so im Herrn.<br/>',NULL,48057,1);
INSERT INTO stanza VALUES('G376','2','Der Feind plant einen Anschlag stets,<br/>Einmütig steht und geht!<br/>Der Kampf ist grimmig, hart und stark,<br/>Im Herrn doch widersteht!<br/>Wer sich aus Angst zurückziehn will,<br/>Der untergräbt den Rest.<br/>Lasst eure Brüder nicht im Stich,<br/>Die Einheit haltet fest.<br/>',NULL,48058,2);
INSERT INTO stanza VALUES('G376','3','Der Teufel weiß, die Zeit ist kurz,<br/>Und tobt so bös gesinnt,<br/>Durch seine Arglist schwächt er uns,<br/>Bevor der Kampf beginnt.<br/>Die Lasten nehmen ständig zu,<br/>Die Leiden schmerzen mehr,<br/>Die Hadesmacht steht gegen uns,<br/>Furchtbar wie nie vorher.<br/>',NULL,48059,3);
INSERT INTO stanza VALUES('G376','4','Was sollte unsre Haltung sein<br/>In dieser schweren Zeit?<br/>Uns schonen und nur müßig sein?<br/>Dann geht der Feind zu weit!<br/>Harrst du im finstren, bösen Kampf<br/>In Christus tapfer aus?<br/>Es geht um Tod und Leben hier!<br/>Zu Gott steig Lobpreis auf.<br/>',NULL,48060,4);
INSERT INTO stanza VALUES('G376','5','Für Christus, unsren Herrn stehn wir,<br/>Denn Ihm gehört der Sieg!<br/>Für Ihn harrn wir in Schmerzen aus,<br/>Bald ist vorbei der Krieg.<br/>Die Stunde Seines Kommens naht –<br/>Der Herr wird triumphiern;<br/>Nun leiden wir um Seinetwilln,<br/>Doch dann mit Ihm regiern.<br/>',NULL,48061,5);
INSERT INTO stanza VALUES('G377','1','Durch das Blut des Siegers Christi<br/>Überwind den Feind allzeit;<br/>Kraft und Tugend Seines Blutes<br/>Stellen dir den Sieg bereit.<br/>',NULL,48062,1);
INSERT INTO stanza VALUES('G377','chorus','Durch das Blut des Siegers Christi<br/>Überwind den Feind allzeit;<br/>Kraft und Tugend Seines Blutes<br/>Stellen dir den Sieg bereit.<br/>',NULL,48063,2);
INSERT INTO stanza VALUES('G377','2','Durch das Blut des Siegers Christi<br/>Konter den, der dich verklagt;<br/>Durch das Blut, das dich verteidigt,<br/>Den Verkläger gleich verjag.<br/>',NULL,48064,3);
INSERT INTO stanza VALUES('G377','3','Durch das Blut des Siegers Christi<br/>Gottes fester Treue glaub;<br/>Durch Sein Blut will Gott vergeben,<br/>Dich zu waschen Ihm erlaub.<br/>',NULL,48065,4);
INSERT INTO stanza VALUES('G377','4','Durch das Blut des Siegers Christi<br/>Tu nun deine Stellung kund;<br/>Durch das Blut, das ewig vorherrscht,<br/>Stehst Du auf dem Siegesgrund.<br/>',NULL,48066,5);
INSERT INTO stanza VALUES('G377','5','Durch das Blut des Siegers Christi<br/>Nimm in Anspruch Seine Macht;<br/>Wende einfach Jesu Blut an,<br/>Und gewinne so die Schlacht.<br/>',NULL,48067,6);
INSERT INTO stanza VALUES('G377','6','Durch das Blut des Siegers Christi<br/>Sitz im Himmel auf dem Thron;<br/>In der Kraft des Aufgefahrnen,<br/>Fürstentümer jag davon.<br/>',NULL,48068,7);
INSERT INTO stanza VALUES('G378','1','Preis Ihn! Christus ist der Sieger,<br/>Ständig es verkünd,<br/>Dass der Retter ist der Sieger<br/>Über Tod und Sünd.<br/>',NULL,48069,1);
INSERT INTO stanza VALUES('G378','chorus','Halleluja! Er ist Sieger,<br/>Sag''s, wo immer du bist,<br/>Dass der Herr der Sieger über<br/>Alle Feinde ist.<br/>',NULL,48070,2);
INSERT INTO stanza VALUES('G378','2','Preis Ihn! Christus ist der Sieger,<br/>Krankheit, Schmerz muss gehn;<br/>Anspruch auf den Sieg erhebe,<br/>Der am Kreuz geschehn.<br/>',NULL,48071,3);
INSERT INTO stanza VALUES('G378','3','Preis Ihn! Christus ist der Sieger,<br/>Wag es, geh und red,<br/>Wohin dich auch Jesus sendet,<br/>Stark sei im Gebet.<br/>',NULL,48072,4);
INSERT INTO stanza VALUES('G378','4','Preis Ihn! Christus ist der Sieger,<br/>Niederlag kann nicht<br/>Unsere Vision verschleiern!<br/>Christus gibt stets Sicht.<br/>',NULL,48073,5);
INSERT INTO stanza VALUES('G378','5','Preis Ihn! Christus ist der Sieger,<br/>Bald Ihn rufen hört:<br/>„Überwinder, kommt zum König<br/>Und mit Ihm regiert!“<br/>',NULL,48074,6);
INSERT INTO stanza VALUES('G379','1','Er hat gesiegt! Der Herr hat schon den Feind besiegt!<br/>Der Siegesschrei ist hörbar nah und fern!<br/>Sein Blut herrscht vor! Durchs Blut erlangen wir den Sieg!<br/>Und bald wird Er als Sieger wiederkehrn.<br/>',NULL,48075,1);
INSERT INTO stanza VALUES('G379','chorus','(Schwestern singen)<br/>Er hat gesiegt! O Christen-Brüder,<br/>Er hat gesiegt! Bringt Ihm Lobpreis!<br/>In Zion weilen, den Sieg hier feiern,<br/>Und fülln mit Lob den Erdenkreis.<br/>(Brüder singen)<br/>Er hat gesiegt! O Christen-Schwestern,<br/>Das große Werk hat Er vollbracht!<br/>Den Feind bezwungen, den Sieg errungen –<br/>Uns ewig Freude hat vermacht!<br/>',NULL,48076,2);
INSERT INTO stanza VALUES('G379','2','Er hat gesiegt! Wir überwinden Gottes Feind,<br/>Bezeugen kühn und mutig Gottes Wort.<br/>Gott spricht Sein Wort, das Leben und Befreiung schenkt,<br/>Wenn wir es sprechen, weicht der Feind sofort.<br/>',NULL,48077,3);
INSERT INTO stanza VALUES('G379','3','Er hat gesiegt! Der Feind liegt unter unsrem Fuß,<br/>Ja, wir verleugnen uns bis in den Tod;<br/>Wir rufen froh: „Herr Jesus, Du bist unser Sieg!“<br/>Im Geist gestärkt verehrn wir unsren Gott.<br/>',NULL,48078,4);
INSERT INTO stanza VALUES('G380','1','Die Macht im Universum hat<br/>Der auferstand''ne Herr allein;<br/>Sind wir in Ihm und eins mit Ihm,<br/>Wird Satan unterworfen sein.<br/>',NULL,48079,1);
INSERT INTO stanza VALUES('G380','2','In Jesu Namen tun wir kund:<br/>Wir überwinden Gottes Feind;<br/>Beziehn die Vollmacht unsres Herrn,<br/>Zerstörn den Schlangenkopf vereint.<br/>',NULL,48080,2);
INSERT INTO stanza VALUES('G380','3','Du hoher Berg, wo du auch bist,<br/>Im Himmel oder hier am Ort,<br/>Wir ebnen dich zu jedem Preis,<br/>In Jesu Namen, heb dich fort!<br/>',NULL,48081,3);
INSERT INTO stanza VALUES('G380','4','Der Glaube streng gebietet dir:<br/>„Erhebe dich, ins Meer wirf dich!“<br/>Und so wolln wir erfüllen treu<br/>Den Vorsatz Gottes ewiglich.<br/>',NULL,48082,4);
INSERT INTO stanza VALUES('G381','1','Grimmig ist heut der Kampf,<br/>Denn Satan tobt noch mehr;<br/>Zum Kriegsruf, der nun lauter tönt,<br/>Versammelt sich das Heer.<br/>Und aus dem Hades schreit<br/>Noch stärker der Rebell;<br/>Doch horch, der Mitternachtsruf tönt,<br/>Siehe, Ich komme schnell!<br/>',NULL,48083,1);
INSERT INTO stanza VALUES('G381','2','Trübsal wird größer noch,<br/>Das Kämpfen schwillt noch an;<br/>Die Hadesmacht versammelt sich,<br/>Zum Angriff setzt nun an.<br/>Wir warten wachend, stehn,<br/>Der arge Kampf ist da,<br/>Doch hören wir das frohe Lied:<br/>Jesus, der Herr ist nah!<br/>',NULL,48084,2);
INSERT INTO stanza VALUES('G381','3','Am End wird''s schwerer noch<br/>Zu stehn fürs Wort und Gott,<br/>Denn Satan kämpft mit aller Macht,<br/>Und unsrem Zeugnis trotzt.<br/>Nun mit vermehrter Kraft<br/>Den Feind vollauf bezwing;<br/>Welch Freude, bald den Herrn zu sehn,<br/>Und Seufzer sind dahin!<br/>',NULL,48085,3);
INSERT INTO stanza VALUES('G381','4','Wer denn wird vorwärtsgehn<br/>In Seiner starken Kraft?<br/>Wer denn, wird fest vertraun dem Herrn,<br/>Bis Er uns Sieg verschafft?<br/>Bis Sieger vom Triumph<br/>Bald singen klar und hell?<br/>Der Mensch wird freuen sich zu hörn:<br/>Siehe, Ich komme schnell!<br/>',NULL,48086,4);
INSERT INTO stanza VALUES('G381','5','Wer wählt denn Gottes Weg,<br/>Auf Seinen Ruf denn hört,<br/>Auch wenn''s durch wilde Stürme geht,<br/>Macht jedoch nicht mehr kehrt?<br/>Wer wagt voranzugehn,<br/>Wenn Furcht und Schmerz sind da?<br/>Wer überwindet, freut sich sehr<br/>Auf Jesus, Er ist nah!<br/>',NULL,48087,5);
INSERT INTO stanza VALUES('G381','6','Wenn es auch finster ist,<br/>Gehn wir erst recht voran,<br/>Bis wir entrückt sind hin zu Ihm,<br/>Mit Herrlichkeit erstrahln.<br/>Dort sehen wir den Herrn,<br/>Die Siegesschlacht geschah;<br/>Die Überwinder freuen sich:<br/>Jesus, der Herr ist da!<br/>',NULL,48088,6);
INSERT INTO stanza VALUES('G382','1','Willst du Überwinder werden?<br/>Christus ruft dich jetzt!<br/>Willst du diesem Ruf nicht folgen,<br/>Treu sein bis zuletzt?<br/>',NULL,48089,1);
INSERT INTO stanza VALUES('G382','chorus','Willst du Überwinder werden?<br/>Triff die Wahl doch heut!<br/>Christus ruft Dich, Christus ruft Dich,<br/>Hör auf Ihn erneut!<br/>',NULL,48090,2);
INSERT INTO stanza VALUES('G382','2','Willst du Überwinder werden?<br/>Such Sein Angesicht!<br/>Halte fest die „erste Liebe“,<br/>Bis der Tag anbricht.<br/>',NULL,48091,3);
INSERT INTO stanza VALUES('G382','3','Willst du Uberwinder werden?<br/>Ihm vertrau aufs Neu!<br/>Bleib, Verfolgung wagend, standhaft,<br/>Bis zum Tod sei treu.<br/>',NULL,48092,4);
INSERT INTO stanza VALUES('G382','4','Willst du Überwinder werden?<br/>Dann bezeug den Herrn!<br/>Vom „verborgnen Manna“ iss und<br/>Religion bleib fern.<br/>',NULL,48093,5);
INSERT INTO stanza VALUES('G382','5','Willst du Überwinder werden,<br/>Einfach, echt und rein?<br/>Überwind den Sauerteig und<br/>Herrsch durch Ihn allein.<br/>',NULL,48094,6);
INSERT INTO stanza VALUES('G382','6','Willst du Überwinder werden?<br/>Auf den Herrn vertraun!<br/>Nicht mit Tod dein „Kleid“ beflecke,<br/>Leben ist dein Lohn.<br/>',NULL,48095,7);
INSERT INTO stanza VALUES('G382','7','Willst du Überwinder werden?<br/>Sei doch niemals lau,<br/>Nie zufrieden mit Erreichtem,<br/>Mehr noch musst du schaun.<br/>',NULL,48096,8);
INSERT INTO stanza VALUES('G382','8','Willst du Überwinder werden?<br/>Christus ruft erneut!<br/>Willst du Seinem Ruf gehorchen,<br/>Christus leben heut?<br/>',NULL,48097,9);
INSERT INTO stanza VALUES('G383','1','Nicht der selbst erwählte Kurs,<br/>Doch wie Jesus führen mag,<br/>Dort quillt Lebenswasser auf,<br/>Dort wird unsre Nacht zu Tag.<br/>',NULL,48098,1);
INSERT INTO stanza VALUES('G383','2','Nicht die selbstbestimmte Tat<br/>Wird gebilligt von dem Herrn,<br/>Doch das nicht erdachte Werk,<br/>Ihm getan in Demut, gern.<br/>',NULL,48099,2);
INSERT INTO stanza VALUES('G383','3','Kein Gebet nach unsrem Wunsch<br/>Wird den Thron des Herrn berührn,<br/>Doch der Geist, der in uns seufzt,<br/>Wird zu Seiner Sehnsucht führn.<br/>',NULL,48100,3);
INSERT INTO stanza VALUES('G383','4','Nicht die Gaben, die du stolz<br/>Legst auf den Altar, will Er,<br/>Doch dein Herz, das noch sagt „Nein“,<br/>Wenn Er sagt: „Bedarf ich sehr.“<br/>',NULL,48101,4);
INSERT INTO stanza VALUES('G383','5','Daher sterbend leben wir<br/>In den Himmeln mit dem Herrn;<br/>Dienen, beten, geben so<br/>Christus Selber, unsren Lohn.<br/>',NULL,48102,5);
INSERT INTO stanza VALUES('G384','1','Heut im Neuen Testament heißt''s:<br/>Durch den Geist, nicht durchs Gesetz;<br/>Nicht Buchstaben, die nur töten,<br/>Doch der Geist belebt uns stets.<br/>Nicht die äußren Werke zählen,<br/>Doch das Dienen durch den Geist;<br/>Nicht nur mit Buchstaben dienen,<br/>Nur Sein Leben andre speist.<br/>',NULL,48103,1);
INSERT INTO stanza VALUES('G384','2','Nicht durch äußerliche Lehren,<br/>Seine Salbung leitet dich;<br/>Nicht nur äußerlich ein Vorbild,<br/>Doch Visionen innerlich.<br/>Nicht die Traditionen, Bräuche,<br/>Lass den Himmel doch regiern;<br/>Nicht durch eigenes Entscheiden,<br/>Lass von Ihm dich reguliern.<br/>',NULL,48104,2);
INSERT INTO stanza VALUES('G384','3','Nicht in Religion, die tot ist,<br/>Doch in Christus Leben fließt;<br/>Nicht Theologie mitgeben,<br/>Doch den Herrn, der Leben ist.<br/>Nicht das Wissen bloßer Lehre,<br/>Teile Christus mit vielmehr;<br/>Nicht die Gaben, Lehren, Formen,<br/>Wirklichkeit ist doch der Herr.<br/>',NULL,48105,3);
INSERT INTO stanza VALUES('G384','4','Nicht auf äußere Weise betend,<br/>Doch Ihm dien im Innern tief;<br/>Kein bloß objektiver Christus,<br/>Doch Ihn Selbst lehr, subjektiv.<br/>Nicht nur durch die Schrift alleine,<br/>Doch im Geist und Leben dien;<br/>Nicht durchs Fleisch und unsre Mühe,<br/>Doch vom Geist dich stets lass ziehn.<br/>',NULL,48106,4);
INSERT INTO stanza VALUES('G385','1','Stets im Strom! Stets im Strom! Lasst uns dienen dem Herrn,<br/>Stets im Licht Seines Wortes Ihm dienen wir gern;<br/>Gottes Leben und Kraft, die der Strom bringt, vertraut,<br/>Die Gemeinde, Sein Reich wird im Strom aufgebaut.<br/>',NULL,48107,1);
INSERT INTO stanza VALUES('G385','chorus','Stets im Strom! Stets im Strom!<br/>Lasst uns dienen im Strom!<br/>Stets im Strom! Stets im Strom!<br/>In Gottes Team auch du nun komm!<br/>',NULL,48108,2);
INSERT INTO stanza VALUES('G385','2','Stets im Strom! Stets im Strom! Dient und wirkt mit dem Herrn,<br/>In dem Fließen des Geistes nun dient nah und fern;<br/>Diene nie durch das Selbst, unabhängig und frei,<br/>Doch in Team-Harmonie sind wir immer dabei.<br/>',NULL,48109,3);
INSERT INTO stanza VALUES('G385','3','Stets im Strom! Stets im Strom! Lasst uns dienen im Herrn,<br/>Mit den kostbaren Heiligen dienen wir gern;<br/>Wort und Leben reicht dar, wie das tägliche Brot,<br/>Geht voran nun im Strom, führt den Plan aus von Gott!<br/>',NULL,48110,4);
INSERT INTO stanza VALUES('G386','1','Der Überfluss des Lebens muss<br/>Das Werk sein, das wir leben!<br/>Was wir erfahren, sollte sein<br/>Die Botschaft, die wir geben.<br/>Wenn Wandel und der Dienst eins sind,<br/>Wird unser Werk gelingen;<br/>Sind Botschaft und das Leben eins,<br/>Wird unser Wort Frucht bringen.<br/>',NULL,48111,1);
INSERT INTO stanza VALUES('G386','2','Das Werk muss Frucht des Lebens sein,<br/>Aus Gottes Geist soll''s fließen;<br/>Wie Reben, die nur fruchtbar sind,<br/>Weil sie am Weinstock sprießen.<br/>Ja, Christus wirkt den Dienst in uns,<br/>Zum Ausdruck will Sich bringen,<br/>Durch uns Sein reiches Leben wird<br/>Auf andre überspringen.<br/>',NULL,48112,2);
INSERT INTO stanza VALUES('G386','3','Keine Bewegung ist es hier,<br/>Durch Gottes Kraft wir gehen;<br/>Es sind nicht äußre Werke nur,<br/>Sie innerlich bestehen.<br/>Es ist kein Unternehmerwerk,<br/>Bezeug Sein Leben allen;<br/>Nicht um das eigne Zutun geht''s,<br/>Doch Er soll aus dir strahlen.<br/>',NULL,48113,3);
INSERT INTO stanza VALUES('G386','4','Wir lassen los die eigne Kraft,<br/>Auch unsre eignen Ziele;<br/>Damit der Herr uns brauchen kann,<br/>Durch uns gescheh Sein Wille.<br/>Obwohl wir leben, werden wir<br/>Dem Tod stets übergeben,<br/>Dass Christus und Sein Überfluss<br/>So reich durch uns kann leben.<br/>',NULL,48114,4);
INSERT INTO stanza VALUES('G387','1','Wie gesegnet ist ein Priester!<br/>Christus alles ist für ihn;<br/>Seine Kleidung, Speise, Wohnung,<br/>Auch sein Anteil und Gewinn.<br/>',NULL,48115,1);
INSERT INTO stanza VALUES('G387','chorus','Wie gesegnet ist ein Priester!<br/>Christus alles ist für ihn;<br/>Seine Kleidung, Speise, Wohnung,<br/>Auch sein Anteil und Gewinn.<br/>',NULL,48116,2);
INSERT INTO stanza VALUES('G387','2','Jedes Kleid des Priesterdienstes<br/>Ist die Schönheit unsres Herrn;<br/>Brust- und Schulterstücke prächtig<br/>Samt Gewändern glänzen schön.<br/>',NULL,48117,3);
INSERT INTO stanza VALUES('G387','3','Bringt er Christus dar als Opfer,<br/>Wie es Gott so wohlgefällt,<br/>Dann genießt er Ihn als Speise<br/>Und Sein Reichtum ihn erfüllt.<br/>',NULL,48118,4);
INSERT INTO stanza VALUES('G387','4','Zieht er Christus als sein Kleid an,<br/>Drückt er Ihn aus äußerlich;<br/>Isst und trinkt, mit Ihm vermengt sich,<br/>Reich erfüllt ist innerlich.<br/>',NULL,48119,5);
INSERT INTO stanza VALUES('G387','5','Heilig, schön ist ihre Wohnung,<br/>Christi Zuwachs ist darin;<br/>Priester, aufgebaut zusammen,<br/>Ein Zuhause sind für Ihn.<br/>',NULL,48120,6);
INSERT INTO stanza VALUES('G387','6','All sein Anteil, Lebenswandel,<br/>Was der Priester auch besitzt –<br/>Ist nur Christus, ewig Christus,<br/>Der so allumfassend ist.<br/>',NULL,48121,7);
INSERT INTO stanza VALUES('G388','1','Christus darzureichen andern<br/>Ist für Gott und Mensch ein Dienst;<br/>Reichst du Christi Überfluss dar,<br/>Selbst Versorgung du gewinnst.<br/>',NULL,48122,1);
INSERT INTO stanza VALUES('G388','chorus','Christus darzureichen andern<br/>Ist für Gott und Mensch ein Dienst;<br/>Reichst du Christi Überfluss dar,<br/>Selbst Versorgung du gewinnst.<br/>',NULL,48123,2);
INSERT INTO stanza VALUES('G388','2','Wie die Israeliten brachten<br/>Ihren Überfluss vom Land,<br/>So füllt Frucht von Jesu Ernte<br/>Unsre dienstbereite Hand.<br/>',NULL,48124,3);
INSERT INTO stanza VALUES('G388','3','Christus, unser Land, bebauen,<br/>Ihn auch ernten werden wir;<br/>Schmecken Ihn und überfließen,<br/>Teilen Ihn zusammen hier.<br/>',NULL,48125,4);
INSERT INTO stanza VALUES('G388','4','Halten alle an dem Haupt fest,<br/>In Funktion dann kommen sie;<br/>Durch Empfangen und Genießen<br/>Wächst der Leib in Harmonie.<br/>',NULL,48126,5);
INSERT INTO stanza VALUES('G388','5','In Gemeinschaft, im Bezeugen,<br/>Im Gebet, im Dienen hier,<br/>Auch im Helfen und Verrichten,<br/>Nur mit Christus dienen wir.<br/>',NULL,48127,6);
INSERT INTO stanza VALUES('G389','1','Diene nur im Leibe Christi,<br/>Wie der Herr es uns beschreibt;<br/>Denn der Leib ist Gottes Vorsatz,<br/>Fest im ihm verbunden bleibt.<br/>',NULL,48128,1);
INSERT INTO stanza VALUES('G389','chorus','Diene, wirke stets im Leibe,<br/>Nicht in Unabhängigkeit;<br/>Denn die Glieder funktionieren<br/>Nur in der Verbundenheit.<br/>',NULL,48129,2);
INSERT INTO stanza VALUES('G389','2','Schon als Glieder, nicht alleine,<br/>Wurden wir vom Herrn belebt;<br/>Gegenseitig fest verbunden,<br/>So zu dienen sind bestrebt.<br/>',NULL,48130,3);
INSERT INTO stanza VALUES('G389','3','Wir, die Steine voller Leben,<br/>Sind für Gottes Haus bestimmt;<br/>Und nun dienen wir als Priester,<br/>Schön harmonisch abgestimmt.<br/>',NULL,48131,4);
INSERT INTO stanza VALUES('G389','4','Wir als aufgebaute Glieder<br/>Nehmen unsre Stellung ein;<br/>Wenn wir dienen, soll die Basis<br/>Das Prinzip des Leibes sein.<br/>',NULL,48132,5);
INSERT INTO stanza VALUES('G389','5','Stets genießen wir beim Dienen<br/>Die Versorgung aus dem Leib;<br/>Trennung von dem Leib heißt, sterben,<br/>Isoliert doch niemals bleib!<br/>',NULL,48133,6);
INSERT INTO stanza VALUES('G389','6','Durch den Dienst im Leibe wird uns<br/>Reichtum von dem Haupt zuteil;<br/>Funktionieren wir als Glieder,<br/>Tragen Christi Maß derweil.<br/>',NULL,48134,7);
INSERT INTO stanza VALUES('G389','7','Halten wir an unsrem Haupt fest,<br/>Wächst der Leib in Harmonie;<br/>Und das Haupt stärkt uns mit Reichtum,<br/>Den Er Seinem Leib zufließt.<br/>',NULL,48135,8);
INSERT INTO stanza VALUES('G389','8','Herr, Dir weihn wir unsre Leiber;<br/>Bis wir umgewandelt sind,<br/>Um den Leib noch mehr zu kennen,<br/>Uns darin beim Dienen find.<br/>',NULL,48136,9);
INSERT INTO stanza VALUES('G390','1','Diene nicht für eigne Ziele,<br/>Der Gemeinde diene nur;<br/>So auch dienten die Apostel,<br/>Lasst uns folgen ihre Spur.<br/>',NULL,48137,1);
INSERT INTO stanza VALUES('G390','chorus','Unser Dienst für die Gemeinde,<br/>Das ist Gottes ew''ger Plan;<br/>Diene nicht für eigne Ziele,<br/>Geh für Christi Leib voran.<br/>',NULL,48138,2);
INSERT INTO stanza VALUES('G390','2','Gott will die Gemeinde brauchen<br/>Als Sein herrliches Gefäß;<br/>Unser Dienst soll sie erbauen<br/>Seinem Vorsatz, Ihm gemäß.<br/>',NULL,48139,3);
INSERT INTO stanza VALUES('G390','3','Die begabten Glieder wurden<br/>Durch das Haupt dem Leib vermacht,<br/>Für den Aufbau der Gemeinde,<br/>Die zur Fülle wird gebracht.<br/>',NULL,48140,4);
INSERT INTO stanza VALUES('G390','4','Durch die Gaben und Funktionen<br/>Stärkt der Geist den Leib mit Kraft;<br/>Alles dient nur der Gemeinde,<br/>Bis der Aufbau ist geschafft.<br/>',NULL,48141,5);
INSERT INTO stanza VALUES('G390','5','Jedes Werk des Evangeliums,<br/>Alles Lehren sollte sein<br/>Für die herrliche Gemeinde,<br/>Alles tu für sie allein.<br/>',NULL,48142,6);
INSERT INTO stanza VALUES('G390','6','Nicht dem Dienst dient die Gemeinde,<br/>Nein, der Dienst ist da für sie;<br/>Die Gemeinde scheint als Leuchter,<br/>Eine Dienstart ist sie nie.<br/>',NULL,48143,7);
INSERT INTO stanza VALUES('G390','7','Dies bewahrt uns in der Einheit,<br/>Uns von Spaltung retten wird;<br/>Dies prüft eigene Motive,<br/>Eigne Ziele korrigiert.<br/>',NULL,48144,8);
INSERT INTO stanza VALUES('G390','8','Mach uns frei vom Werk, das spaltet,<br/>Und von jedem Sekten-Werk;<br/>Unser Werk dient der Gemeinde,<br/>Uns für ihren Aufbau stärk.<br/>',NULL,48145,9);
INSERT INTO stanza VALUES('G391','1','Reich den Verlornen Christus dar,<br/>Nicht nur in Wort, lebe Ihn,<br/>Teile durch Taten Christus aus,<br/>Den Abgekämpften stets dien.<br/>',NULL,48146,1);
INSERT INTO stanza VALUES('G391','chorus','Reich den Verlornen Christus dar,<br/>In deinem Alltag stelle Ihn aus,<br/>Teil Christus aus, durch den du lebst,<br/>Bring die Verlornen wieder nach Haus.<br/>',NULL,48147,2);
INSERT INTO stanza VALUES('G391','2','Reich den Verlornen Christus dar,<br/>Als deinen Schatz sprich vom Ihm,<br/>Dem, den du liebst, teil Christus aus,<br/>So wird der Herr sein Gewinn.<br/>',NULL,48148,3);
INSERT INTO stanza VALUES('G391','3','Reich den Verlornen Christus dar,<br/>Der dich erfreut, Gnade gibt,<br/>Teil deinen Freunden Christus aus,<br/>Bis auch ihr Herz Christus liebt.<br/>',NULL,48149,4);
INSERT INTO stanza VALUES('G391','4','Reicht den Verlornen Christus dar,<br/>Er ist dein Ziel, deine Wahl,<br/>Dem, den du triffst, mit Christus dien,<br/>Sprich doch vom Herrn überall.<br/>',NULL,48150,5);
INSERT INTO stanza VALUES('G392','1','Geht, Materialien sammelt für Sein Haus,<br/>Kostbare Seelen doch für Gott gewinnt;<br/>Bringt sie, denn Gott schuf sie für Seinen Plan,<br/>Bringt alle, die in Tod und Sünde sind.<br/>',NULL,48151,1);
INSERT INTO stanza VALUES('G392','2','Geht, Materialien sammelt für Sein Haus,<br/>Helft andern frei zu sein von dieser Welt,<br/>Frei sein von Satans Finsternis und List,<br/>Von allem frei, was sie gebunden hält.<br/>',NULL,48152,2);
INSERT INTO stanza VALUES('G392','3','Geht, Materialien sammelt für Sein Haus,<br/>Seelen gewinnt für Gottes Herrlichkeit;<br/>Geht und besiegt im Geist nun Gottes Feind,<br/>Geht, rettet Sünder in Einmütigkeit.<br/>',NULL,48153,3);
INSERT INTO stanza VALUES('G392','4','Geht, Materialien sammelt für Sein Haus,<br/>Geht, sprecht von Christus, eins in Seinem Leib;<br/>Rede auch du das Evangelium treu,<br/>Und in der Einheit mit den Gliedern bleib.<br/>',NULL,48154,4);
INSERT INTO stanza VALUES('G393','1','Ausfluss hell des Evangeliums<br/>Ist der innre Lebensstrom;<br/>Durch das Zeugnis, das wir leben,<br/>Lenken wir die Sünder um.<br/>',NULL,48155,1);
INSERT INTO stanza VALUES('G393','chorus','Herr, gewähre Lebens-Ausfluss,<br/>Dass durch uns Dein Leben blickt;<br/>Durch Gefäße voller Lebens<br/>Werden Menschen neu erquickt.<br/>',NULL,48156,2);
INSERT INTO stanza VALUES('G393','2','Überzeugend wirkt das Leben,<br/>Dass der Mensch dann glauben kann;<br/>Strömt das Leben zu den Seelen,<br/>Nehmen sie es freudig an.<br/>',NULL,48157,3);
INSERT INTO stanza VALUES('G393','3','Wer in Dir bleibt wie die Rebe,<br/>Bringt viel Frucht hervor für Dich;<br/>Fließt aus uns heraus Dein Leben,<br/>Wirst Du sichtbar äußerlich.<br/>',NULL,48158,4);
INSERT INTO stanza VALUES('G393','4','Unser Wandel sei die Predigt,<br/>Wir erzähln von Christus gern;<br/>Kein Verbreiten toter Lehre,<br/>Leben säen nah und fern.<br/>',NULL,48159,5);
INSERT INTO stanza VALUES('G394','1','In dem Todeswasser starb ich,<br/>Mit dem Retter bin begraben hier;<br/>Kann die Welt mich noch verfolgen?<br/>Nein, jetzt ist zerstört ihre Kraft an mir.<br/>Jetzt mit Christus auferweckt,<br/>Gehe ich mit Ihm aus Tod und Nacht;<br/>Und der Geist reicht Leben dar,<br/>Unerschöpflich stärkt Er mich mit Seiner Macht.<br/>',NULL,48160,1);
INSERT INTO stanza VALUES('G395','1','Beim Taufen machen wir uns eins<br/>Mit Deinem Tod, o Herr,<br/>Durch Deine große Gnade doch<br/>Enthülle ihren Wert.<br/>',NULL,48161,1);
INSERT INTO stanza VALUES('G395','2','Die Taufe, Herr, in Deinen Tod,<br/>Begräbt uns auch mit Dir;<br/>Tot für die Sünde sind wir nun,<br/>Vollauf befreit von ihr.<br/>',NULL,48162,2);
INSERT INTO stanza VALUES('G395','3','Die Taufe, Herr, in Deinen Tod,<br/>Begräbt uns auch mit Dir;<br/>Von Satans Knechtschaft und der Welt<br/>Nur so befreit sind wir.<br/>',NULL,48163,3);
INSERT INTO stanza VALUES('G395','4','Mit Dir auch auferstanden, wir<br/>Von Todeskraft sind frei;<br/>Wir tragen Frucht der Heiligkeit<br/>Im Leben nun herbei.<br/>',NULL,48164,4);
INSERT INTO stanza VALUES('G395','5','Getauft auf Deinen Namen, wir<br/>Gehörn uns selbst nicht mehr;<br/>Wir folgen Deinen Schritten gern,<br/>Sind eins mit Dir, o Herr.<br/>',NULL,48165,5);
INSERT INTO stanza VALUES('G396','1','Mit Christus tot und auch im Grab!<br/>Mit dem alten Menschen schloss ich ab!<br/>Mit Christus tot und auch im Grab!<br/>Mit dem alten Menschen schloss ich ab!<br/>',NULL,48166,1);
INSERT INTO stanza VALUES('G396','2','Nicht länger ich! Christus in mir!<br/>Ihn bezeuge ich im Glauben hier!<br/>Nicht länger ich! Christus in mir!<br/>Ihn bezeuge ich im Glauben hier!<br/>',NULL,48167,2);
INSERT INTO stanza VALUES('G397','1','Das Königreich ist Gottes<br/>Regiern in Herrlichkeit,<br/>Sein souveränes Herrschen<br/>Hält Ordnung fest allzeit.<br/>Im Königreich übt stetig<br/>Der Herr Gerechtigkeit,<br/>Regiert mit seiner Vollmacht<br/>Jetzt und in Ewigkeit.<br/>',NULL,48168,1);
INSERT INTO stanza VALUES('G397','2','Von Seinem Thron, dem Zentrum,<br/>Von wo aus Er regiert,<br/>Bringt Er mit Seinem Vorsatz<br/>In Einklang, was passiert.<br/>Nur als der König herrschend<br/>In seinem Königreich,<br/>Kann Er sein Hauptsein wahren,<br/>Welch Herrscher ohnegleich!<br/>',NULL,48169,2);
INSERT INTO stanza VALUES('G397','3','Im Königreich regiert Er,<br/>Dass Sein Will wird getan,<br/>Und unter Seiner Herrschaft<br/>Erfüllt Er Seinen Plan.<br/>Allein in Gottes Reich wird<br/>Sein Segen uns zuteil,<br/>Von Seinem Thron erhaben<br/>Fließt Lebenswasser frei.<br/>',NULL,48170,3);
INSERT INTO stanza VALUES('G397','4','Wer Gottes Herrschaft annimmt,<br/>Hat Tugend als Gewinn,<br/>Doch Rebellion dagegen<br/>Ist Wurzel aller Sünd.<br/>Denn auf den Sturz von Gottes<br/>Thron Satan abgezielt,<br/>Doch unter Gottes Herrschen<br/>Zu stehn ist unser Ziel.<br/>',NULL,48171,4);
INSERT INTO stanza VALUES('G397','5','In Gottes Königreich wird<br/>Sein Christus groß gemacht,<br/>Herrscht Er im Leben, wird so<br/>Dem Vater Ehr gebracht.<br/>Wenn Gott regiert, ist alles<br/>Gesegnet weit und breit;<br/>Wo Christus als das Haupt herrscht,<br/>Strahlt Gottes Herrlichkeit.<br/>',NULL,48172,5);
INSERT INTO stanza VALUES('G397','6','In Christus aufgehauptet<br/>Wird schließlich alles sein,<br/>Dann herrscht Er vollumfänglich,<br/>Es ehrt Ihn groß und klein.<br/>Schon heut schmeckt die Gemeinde<br/>Den Glanz von Gottes Reich,<br/>Dem König ganz ergeben<br/>Eilt sie zum Königreich.<br/>',NULL,48173,6);
INSERT INTO stanza VALUES('G398','1','Hier auf der Erde hat der Herr<br/>In uns schon heut sein Königreich,<br/>Christus in uns will leben frei<br/>Als König und als Herr zugleich.<br/>',NULL,48174,1);
INSERT INTO stanza VALUES('G398','2','Sein Leben wirkt mit Vollmacht sanft,<br/>Bis unser Herz den Thron Ihm schenkt;<br/>Es regelt uns in Wort und Tat,<br/>All unsre innren Teile lenkt.<br/>',NULL,48175,2);
INSERT INTO stanza VALUES('G398','3','Wenn Er in unsrem Herzen thront,<br/>Errichtet Er Sein Königreich;<br/>Rechtmäßig herrscht der Herr in uns,<br/>Für Gottes Plan macht uns bereit.<br/>',NULL,48176,3);
INSERT INTO stanza VALUES('G398','4','Wenn Er in unsrem Herzen herrscht,<br/>Reicht Er uns Gottes Leben dar;<br/>Nehmen wir Ihn als König an,<br/>Sein Reichtum sättigt uns fürwahr.<br/>',NULL,48177,4);
INSERT INTO stanza VALUES('G398','5','Durch Sein Regiern von innen her<br/>Wird Seine Fülle offenbar;<br/>Durch innres Herrschen segnet Er<br/>Den Leib und baut ihn wunderbar.<br/>',NULL,48178,5);
INSERT INTO stanza VALUES('G398','6','Herrscht nun der Himmel sanft in uns,<br/>Als Himmels-Bürger leben wir;<br/>Lassen wir Sein Regieren zu,<br/>Wird Seine Herrschaft sichtbar hier.<br/>',NULL,48179,6);
INSERT INTO stanza VALUES('G398','7','Hier schon im Himmel leben wir,<br/>Besitzen Himmels-Kraft zugleich;<br/>Himmlisches Licht führt uns im Kampf,<br/>Bis offen sichtbar kommt sein Reich.<br/>',NULL,48180,7);
INSERT INTO stanza VALUES('G399','1','Ein Leben unter Gottes Thron<br/>Ist die Essenz des Königreichs,<br/>Ein Leben göttlicher Natur,<br/>In Christus wir''s erfahren reich.<br/>',NULL,48181,1);
INSERT INTO stanza VALUES('G399','2','Das Leben zeigt sich arm im Geist,<br/>Es trauert, sanft ist es so gern;<br/>Mit andren will barmherzig sein,<br/>Mit reinem Herzen sucht den Herrn,<br/>',NULL,48182,2);
INSERT INTO stanza VALUES('G399','3','Als Gottes Söhnen Frieden wirkt,<br/>Und für Gerechtigkeit trägt Schmerz;<br/>Um Jesu willen wird''s geschmäht,<br/>Mit höchster Freude füllt das Herz.<br/>',NULL,48183,3);
INSERT INTO stanza VALUES('G399','4','Als Salz hemmt es Verdorbenheit,<br/>Im Dunkeln scheint es als das Licht,<br/>Macht unsren Wandel echt und recht,<br/>Ist voller Liebe, fordert nicht.<br/>',NULL,48184,4);
INSERT INTO stanza VALUES('G399','5','Die eigne Ehre weist es ab,<br/>Für Gottes Königreich steht ein;<br/>Vertraut auf Gott zu jeder Zeit,<br/>Sucht stets Sein Reich zuerst allein.<br/>',NULL,48185,5);
INSERT INTO stanza VALUES('G399','6','Mit sich ist''s streng, mit andern mild,<br/>Behandeln lässt sich durch den Herrn;<br/>Des Vaters Willen tut es stets,<br/>Auf Gottes Sprechen hört es gern.<br/>',NULL,48186,6);
INSERT INTO stanza VALUES('G399','7','Es gibt dem Satan keinen Raum,<br/>Noch Selbst, noch Sünde, noch der Welt,<br/>Es unterordnet sich dem Herrn,<br/>Und Gottes Vollmacht so erhält.<br/>',NULL,48187,7);
INSERT INTO stanza VALUES('G399','8','Ja, dieses Leben führt hier aus<br/>Den Willen Gottes unbedingt;<br/>Und es beschleunigt, dass der Herr<br/>Sein Königreich zur Erde bringt.<br/>',NULL,48188,8);
INSERT INTO stanza VALUES('G400','1','Sieh! Das Königreich der Himmel<br/>Strahlt voll Glanz und Herrlichkeit!<br/>Und sein König, unser Meister,<br/>Herrscht für alle Ewigkeit.<br/>Einst kam Er in Fleisch und Demut,<br/>Menschen griffen Ihn stark an;<br/>Jetzt in Herrlichkeit bald kommt Er<br/>Und vollendet Gottes Plan.<br/>',NULL,48189,1);
INSERT INTO stanza VALUES('G400','2','Damals fuhr Er auf zum Vater<br/>Und empfing das Königreich;<br/>Mit dem Reich kommt Christus wieder,<br/>Herrlich, prächtig, ohnegleich.<br/>Er, „der Stein“, zerschlägt Nationen,<br/>Bis sie sind zu Staub zermahlt,<br/>Bis Er zu dem „großen Berg“ wird,<br/>Der als Königreich erstrahlt.<br/>',NULL,48190,2);
INSERT INTO stanza VALUES('G400','3','Sieh! die Erde, Länder, Reiche<br/>Christus, unsrem Herrn, gehörn;<br/>Seine Herrschaft bringt der Erde<br/>Frieden, Ruhe, nichts kann störn.<br/>Keinen Krieg und keine Feindschaft<br/>Gibt es unter Völkern mehr;<br/>Die Erkenntnis Gottes füllt sie,<br/>Wie die Wasser fülln das Meer.<br/>',NULL,48191,3);
INSERT INTO stanza VALUES('G400','4','Alle Christen-Überwinder<br/>Herrschen dann mit Ihm im Reich,<br/>Und der Restteil Israels wird<br/>Priester Gottes sein zugleich.<br/>Unter ihrem Stab und Lehre<br/>Werden alle Völker stehn,<br/>Wiederhergestellt und herrlich<br/>Ist die Schöpfung dann zu sehn.<br/>',NULL,48192,4);
INSERT INTO stanza VALUES('G400','5','Satan wird verbannt, gebunden,<br/>Seine Macht ist dann vorbei;<br/>Christus herrscht! Die ganze Erde<br/>Ist gesegnet reich dabei.<br/>Ihm sich alles unterordnet,<br/>Seinem Willen, Seiner Macht;<br/>Christus, als das Haupt und Zentrum,<br/>Gottes Vorsatz hat vollbracht.<br/>',NULL,48193,5);
INSERT INTO stanza VALUES('G401','1','Gottes Reich heut erfordert viel Übung und Fleiß,<br/>Wenn dann Christus zu herrschen kommt, groß ist der Preis,<br/>Oh, wie weise und so göttlich, dass Er uns trainiert,<br/>Seinen Plan und Gerechtigkeit realisiert.<br/>',NULL,48194,1);
INSERT INTO stanza VALUES('G401','2','Um zu herrschen mit Christus, Gottes Kinder sind wir,<br/>Und wir üben, dass wir überwinden schon hier,<br/>Für das Königreich lassen wir uns heut trainiern,<br/>Damit mit Seinem Königtum wir dann regiern.<br/>',NULL,48195,2);
INSERT INTO stanza VALUES('G401','3','Unter Gottes Thron lernen wir täglich zu sein,<br/>Strikt zu leben, regiert nur von Christus allein;<br/>Seine Vollmacht dann teilen wir, welch schöner Lohn,<br/>Über Völker regiern wir mit Ihm, Gottes Sohn.<br/>',NULL,48196,3);
INSERT INTO stanza VALUES('G401','4','Mit uns selbst streng im Umgang, im Verhalten gerecht,<br/>Sind wir friedlich mit andern, zu kühn und echt;<br/>In des Königreichs Wirklichkeit sind allezeit,<br/>Und bei dessen Erscheinen zum Herrschen bereit.<br/>',NULL,48197,4);
INSERT INTO stanza VALUES('G401','5','Christus trifft mit dem Königreich Gottes bald ein,<br/>Als Belohnung Mitkönige werden wir sein;<br/>So bleibt Seine Gerechtigkeit durch uns bestehn,<br/>Jede Himmelsmacht wird Seine Weisheit dann sehn.<br/>',NULL,48198,5);
INSERT INTO stanza VALUES('G401','6','Deshalb rang der Apostel hart um jeden Preis,<br/>Für die Aussicht des Königreichs übte er Fleiß;<br/>Er ermahnte: Vor Gott treu und aufrichtig seid,<br/>Dass das Reich als Belohnung für euch ist bereit.<br/>',NULL,48199,6);
INSERT INTO stanza VALUES('G401','7','Schenk uns Gnade, zu leben für Dein Königreich,<br/>Lasst uns üben, bis Du uns belohnst ohnegleich;<br/>Für des Königreichs Wirklichkeit uns jetzt trainier,<br/>Bis wir durch sein Erscheinen belohnt werden hier.<br/>',NULL,48200,7);
INSERT INTO stanza VALUES('G402','1','Das Geheimnis aller Zeiten offen mir:<br/>Es ist Christus, Gottes Wirklichkeit;<br/>Er verkörpert Gott, das Leben ist Er mir<br/>Und die Hoffnung auf die Herrlichkeit.<br/>',NULL,48201,1);
INSERT INTO stanza VALUES('G402','chorus','Herrlichkeit, ja Christus lebt in mir!<br/>Herrlichkeit, Er ist die Hoffnung hier!<br/>Heute als Geheimnis lebt in mir der Herr!<br/>Dann die Herrlichkeit für mich ist Er.<br/>',NULL,48202,2);
INSERT INTO stanza VALUES('G402','2','Christus hat in meinem Geist mich neu geborn,<br/>In der Seele wandelt Er mich um,<br/>Meinen Leib verwandelt Er, wie Seiner gleich,<br/>Macht mich gleich wie Er ist rundherum.<br/>',NULL,48203,3);
INSERT INTO stanza VALUES('G402','3','In Natur und Leben jetzt schon eins mit Ihm,<br/>In der Herrlichkeit dann werd ich sein;<br/>Seine Gegenwart genieß ich ewiglich,<br/>Mit Ihm stimme völlig überein.<br/>',NULL,48204,4);
INSERT INTO stanza VALUES('G403','1','Ja, Christus ist die Hoffnung der Herrlichkeit für mich,<br/>Er hat mich neu geboren, durchsättigt mich mit Sich;<br/>Bald kommt Er und verwandelt mit Vollmacht meinen Leib,<br/>In Seiner Herrlichkeit werd ich ewig bleib!<br/>',NULL,48205,1);
INSERT INTO stanza VALUES('G403','chorus','Er kommt, Er kommt und Er verherrlicht mich!<br/>Verklären wird Er meinen Leib, dem Seinen gleich werd ich.<br/>Er kommt, Er kommt, bald ist Erlösungszeit!<br/>Er kommt und Er verherrlicht uns, welch Hoffnung, Herrlichkeit!<br/>',NULL,48206,2);
INSERT INTO stanza VALUES('G403','2','Geheimnis Gottes, Hoffnung der Herrlichkeit ist Er,<br/>Er wirkt nun Gottes Fülle in mich ein mehr und mehr;<br/>Er kommt und Er vermengt mich mit Gott in Wirklichkeit,<br/>Dann habe ich schon teil an der Herrlichkeit.<br/>',NULL,48207,3);
INSERT INTO stanza VALUES('G403','3','Erlösung und die Hoffnung der Herrlichkeit ist Er:<br/>Erlösung für den Leib, ihn vom Tod befreit der Herr,<br/>Bei Seiner Wiederkunft wird Er meinen Leib verklärn,<br/>Und über Tod den Sieg wird Er proklamiern.<br/>',NULL,48208,4);
INSERT INTO stanza VALUES('G403','4','Mein Leben und die Hoffnung der Herrlichkeit ist Er:<br/>Jetzt eins mit Ihm, Sein Leben erfahr ich täglich sehr,<br/>Er kommt, in Seine herrliche Freiheit geh ich ein,<br/>Vollkommen eins mit Ihm werd ich ewig sein.<br/>',NULL,48209,5);
INSERT INTO stanza VALUES('G404','1','Bald kommt unser Herr,<br/>Seine Schritte hören wir schon heut.<br/>Wachsam seid und betet, dass der Herr schon bald<br/>Mit Entrückung unser Herz erfreut.<br/>',NULL,48210,1);
INSERT INTO stanza VALUES('G404','chorus','Herrlichkeit! Denn Christus ist bald hier!<br/>Herrlichkeit! Mit Ihm regieren wir!<br/>Mit verklärtem Leib, auf ewig bei dem Herrn,<br/>Loben Ihn in Harmonie so gern.<br/>',NULL,48211,2);
INSERT INTO stanza VALUES('G404','2','Bald kommt unser Herr, der Morgenstern erscheint;<br/>Nach der dunklen Nacht bricht an der Tag.<br/>Niemals mit dem Lauf der Zeiten wolln wir gehn,<br/>Fliehen so vor Trübsal und vor Plag.<br/>',NULL,48212,3);
INSERT INTO stanza VALUES('G404','3','Bald kommt unser Herr, gibt Seinen Dienern Lohn;<br/>Wer Ihn liebt, hat an der Krone teil.<br/>Wachsam seid und betet, liebt nicht diese Welt,<br/>Liebt den Herrn und dient Ihm gern derweil.<br/>',NULL,48213,4);
INSERT INTO stanza VALUES('G404','4','Bald kommt unser Herr und herrscht in Seinem Reich,<br/>Welt und Satan kriegen ihren Lohn.<br/>Kämpfen wir und überwinden Gottes Feind,<br/>Setzt Er uns mit Ihm auf Seinen Thron.<br/>',NULL,48214,5);
INSERT INTO stanza VALUES('G405','1','Seit wir uns trennten damals in Bethanien,<br/>Im Herzen große Leere spüre ich;<br/>Kann ich die Harfe nehmen von der Weide?<br/>Kann ich mein Lied genießen ohne Dich?<br/>Wenn ich halt einsam Wache in der Nachtzeit –<br/>Taub bin für Sorgen, nichts mehr mich erfreut –<br/>An die Verheißung Deines Kommens denk ich,<br/>Doch seufze: Herr, warum erscheinst Du nicht schon heut?<br/>',NULL,48215,1);
INSERT INTO stanza VALUES('G405','2','Die Krippe zeigt mir: Oh, auch ich bin heimatlos,<br/>Dein Kreuz streift mir all eitle Freuden ab;<br/>Dein Kommen drängt, ein bessres Land zu suchen,<br/>Du bist mein höchstes Ziel, das ich nur hab.<br/>Seit Du weggingst, hat meine Freude kaum Geschmack,<br/>Und nicht mehr klingt mein Lied so süß und hell;<br/>Seit Du weggingst, nimmt Leere mein Empfinden ein,<br/>Wie sehn ich mich, dass Du bald kommst, oh, komm doch schnell!<br/>',NULL,48216,2);
INSERT INTO stanza VALUES('G405','3','Obwohl ich Deine Gegenwart schon heute kenn,<br/>In meinem Herzen mangelt noch ein Stück;<br/>Auch Deine starke, liebe Unterstützung<br/>Stellt nicht zufrieden: Dich will ich zurück!<br/>Trotz Deines Friedens fühl ich mich noch einsam,<br/>Trotz Deiner Freude wird ein Seufzer frei;<br/>Bin ich auch höchst zufrieden, wird mein Sehnen,<br/>Persönlich Dich zu sehen, Herr, zu einem Schrei.<br/>',NULL,48217,3);
INSERT INTO stanza VALUES('G405','4','Ein jeder sehnt sich nach der Heimat im Exil,<br/>Und will sein Volk begrüßen noch so gern;<br/>Ja, wer im fremden Land vergisst Verwandte?<br/>Wollen sich Liebende denn bleiben fern?<br/>All eitle Freuden und Vergnügen geb ich,<br/>Für Deine Rückkehr – meine größte Freud;<br/>Wenn ich Dein Angesicht nun noch nicht sehen kann,<br/>Was soll ich tun als seufzen: Komm, erschein schon heut?<br/>',NULL,48218,4);
INSERT INTO stanza VALUES('G405','5','Könntest Du, Herr, vergessen Dein Versprechen,<br/>Dass Du bald kommst und nimmst mich hin zu Dir?<br/>Ich hab gewartet Tag für Tag und Jahr für Jahr,<br/>Noch immer wart, Dein Kommen seh nicht hier!<br/>Bedenk, o Herr, wie lange ich gewartet hab,<br/>Doch Dein geliebter Schritt ist noch so weit;<br/>Wie lang? Wie lang? Muss ich noch länger warten?<br/>Wann wirst Du wiederkommen voller Herrlichkeit?<br/>',NULL,48219,5);
INSERT INTO stanza VALUES('G405','6','Generationen folgten nacheinander,<br/>Die Heil''gen kamen, gingen, sahen nicht,<br/>Wie Deine herrliche Verheißung eintritt.<br/>Oh, wie viel Zeit doch schon vergangen ist!<br/>Herr, warum nehmen wir nicht Deine Schritte wahr?<br/>Warum der Himmel noch versiegelt fest?<br/>Muss unser Warten noch verlängert werden,<br/>Bis Du in Glanz und Herrlichkeit hier sichtbar bist?<br/>',NULL,48220,6);
INSERT INTO stanza VALUES('G405','7','Herr, viele Jahre habe ich gewartet<br/>Auf Deine Rückkehr – doch nicht ich allein,<br/>Vielmehr die lieben Heil''gen aller Zeiten –<br/>Wir flehen: Komm zurück, denn wir sind Dein.<br/>Auf viele Tränen, liebevolles Flehen<br/>Gib Antwort, eile, komm doch schnell herbei;<br/>Wir beten: Komm, Du Echo der Zeitalter,<br/>Komm und erhöre nun den korp''rativen Schrei!<br/>',NULL,48221,7);
INSERT INTO stanza VALUES('G406','1','Seit Deinem Weggang, Herr, damals vom Ölberg,<br/>Warum verzögert sich Deine Rückkehr?<br/>Lange ersehnen wir nun schon Dein Kommen,<br/>Hörtest Du nicht unser Beten, o Herr?<br/>',NULL,48222,1);
INSERT INTO stanza VALUES('G406','chorus','Komm Du, komm nun,<br/>Unser Herz sehnt sich nach Dir;<br/>Löse ein Deine verheißene Rückkehr,<br/>Komm schnell zurück, liebster Herr, flehen wir.<br/>',NULL,48223,2);
INSERT INTO stanza VALUES('G406','2','Seit Du, o liebster Herr, auffuhrst zum Vater,<br/>Scheint alles farblos und armselig hier;<br/>Oftmals beim Beten und oftmals beim Wachen<br/>Seufzen wir sehnsüchtig nur noch nach Dir.<br/>',NULL,48224,3);
INSERT INTO stanza VALUES('G406','3','Vögel und Blumen, sie sind alle lieblich,<br/>Doch liebster Herr, wann nur treffe ich Dich?<br/>Alles erfreut mich, doch nichts stellt zufrieden,<br/>Nach Deinem Angesicht sehne ich mich.<br/>',NULL,48225,4);
INSERT INTO stanza VALUES('G406','4','Jahrelang sehnten wir uns ungeduldig,<br/>Herr, oh, wie lange Zeit soll es noch gehn?<br/>Vom Sonnenaufgang hell bis Abendröte<br/>Hoffen wir endlich Dein Kommen zu sehn.<br/>',NULL,48226,5);
INSERT INTO stanza VALUES('G406','5','Immer wenn Regen fällt oder der Wind bläst,<br/>Wenn der Mond scheint oder ansteigt das Meer,<br/>Hoffen wir stets zu entdecken Dein Kommen,<br/>Sehn wir kein Zeichen, enttäuscht es uns sehr.<br/>',NULL,48227,6);
INSERT INTO stanza VALUES('G406','6','Hättest Du uns keinen Auftrag gegeben,<br/>Wärn wir entmutigt und mieden den Dienst;<br/>Doch Du willst, dass stets beim Warten auf Dich, Herr,<br/>Jedes Talent wird doch fleißig verzinst.<br/>',NULL,48228,7);
INSERT INTO stanza VALUES('G406','7','Herr, oh, bedenke wie lang wir schon warten,<br/>Seit Du verheißen hast vor der Auffahrt,<br/>Dass Du zurückkommst, worauf wir stets hoffen;<br/>Kannst Du nicht heute schon kommen? Nicht wart!<br/>',NULL,48229,8);
INSERT INTO stanza VALUES('G407','1','Mein König wird bald wiederkehrn,<br/>Den Himmel fülln mit Sich;<br/>Die Schöpfung dann Erlösung sieht<br/>Im Licht, so königlich.<br/>Der Herr wird Seinen Plan erfülln,<br/>Sein Kommen ist nicht fern;<br/>Den Glanz des Herrn kann schwach ich sehn,<br/>Bald wird Er wiederkehrn.<br/>',NULL,48230,1);
INSERT INTO stanza VALUES('G407','2','Nach Seiner Nähe sehn ich mich<br/>und wag nicht faul zu sein<br/>Beim Warten auf den großen Tag,<br/>Sein Kommen nimmt mich ein.<br/>Nur eine Hoffnung habe ich<br/>Er kommt und macht all das<br/>Zur Wirklichkeit, was ich nun glaub;<br/>Welch Freude ohne Maß!<br/>',NULL,48231,2);
INSERT INTO stanza VALUES('G407','3','Mein Herz ist allezeit bei Ihm,<br/>Die Augen suchen Ihn,<br/>Und meine Lippen sagen stets,<br/>Dass ich beim Herrn bald bin.<br/>Ja, Seine Ankunft ist schon nah,<br/>Sein Kommen ist für mich;<br/>Was Er verheißt, bleibt ewig fest,<br/>Wird bald erfüllen sich.<br/>',NULL,48232,3);
INSERT INTO stanza VALUES('G407','4','An Deinem Wort, Mein Retter, ist<br/>Kein Zweifel mehr in mir;<br/>Mit ihm, ermutigt Tag für Tag,<br/>Nun lauf ich, treu bin Dir.<br/>Bald Deine Herrlichkeit erscheint,<br/>Der Feind gestürzt dann schon;<br/>Was Du verheißen hast, erfüllst,<br/>Nimmst uns auf Deinen Thron.<br/>',NULL,48233,4);
INSERT INTO stanza VALUES('G407','5','Dein starker Arm, mein Retter-Gott,<br/>Ist Zuflucht hier für mich;<br/>Wer Dir vertraut, o Vater, den<br/>Bewahrst Du sicherlich.<br/>Die Schafe und der Hirt sind eins,<br/>So eins wie Leib und Haupt;<br/>Aus Deiner Hand reißt niemand je<br/>Das Kind, das Dir, Herr, glaubt.<br/>',NULL,48234,5);
INSERT INTO stanza VALUES('G407','6','Nicht tausend Hände hindern mich,<br/>Zehntausend Augen nicht;<br/>Mich treibt der Dornenweg voran,<br/>Der Preis ist schon in Sicht.<br/>Steh auf mein Geist, steh auf mein Herz,<br/>Die Welt lass fahrn dahin;<br/>Der Herr des Lebens wird mich bald<br/>Zu Sich nach oben ziehn.<br/>',NULL,48235,6);
INSERT INTO stanza VALUES('G407','7','Du Sonn des Heils! Du Hoffnung hier!<br/>Ich liebe Deine Strahln;<br/>Gerechter Herr! O König mein!<br/>Ich beug mich, fleh Dich an:<br/>O Herr, steig bald auf Deinen Thron,<br/>Zeig bald Dein Angesicht;<br/>Schenk allen Deine Gnade nun,<br/>Dein Königreich erricht.<br/>',NULL,48236,7);
INSERT INTO stanza VALUES('G407','8','Die Wahrheit sollte König sein,<br/>Und Freiheit Königin;<br/>Doch Falschheit, völlig zügellos,<br/>Regiert die Welt weithin.<br/>Wir flehen, Wahrheit, komm doch schnell,<br/>Dein Himmels-Licht verbreit,<br/>Zertritt den Feind, die Söhne lass<br/>Bei Dir sein allezeit.<br/>',NULL,48237,8);
INSERT INTO stanza VALUES('G408','1','Oh, wie lang, bis mein Herr wiederkommt?<br/>Mein Herz will sehn Dein Angesicht,<br/>Bis ich singen darf das Siegeslied,<br/>Schaun den Herrn voller Gnade im Licht.<br/>Komm schnell, o Herr, und warte nicht!<br/>Auf Deinen Trost ich wart schon lange hier;<br/>Komm schnell, o Herr, und warte nicht!<br/>Mein Herz sehnt sich zu sein bei Dir.<br/>',NULL,48238,1);
INSERT INTO stanza VALUES('G409','1','Wenn mein Herr wieder kommt hierhin,<br/>Aus allem Schmerz ich frei dann bin,<br/>Mit allen Heil''gen folg ich Ihm,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Mit allen Heil''gen folg ich Ihm,<br/>Oh, lob den Herrn!<br/>',NULL,48239,1);
INSERT INTO stanza VALUES('G409','2','Von Angesicht zu Angesicht<br/>Werd ich Ihn sehn im hellen Licht,<br/>Von Gnade jeder singt und spricht,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Von Gnade jeder singt und spricht,<br/>Oh, lob den Herrn!<br/>',NULL,48240,2);
INSERT INTO stanza VALUES('G409','3','Wenn ich Ihn treffe vor dem Thron,<br/>Ganz frei von Leid in Christus wohn,<br/>Die Siegesfreude ist mein Lohn,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Die Siegesfreude ist mein Lohn,<br/>Oh, lob den Herrn!<br/>',NULL,48241,3);
INSERT INTO stanza VALUES('G409','4','An jenem Tag bezeuge ich,<br/>Mit Christi Leben nichts misst sich,<br/>Auf die Entrückung freu ich mich,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Auf die Entrückung freu ich mich,<br/>Oh, lob den Herrn!<br/>',NULL,48242,4);
INSERT INTO stanza VALUES('G409','5','Versteckt im Herrn in Seiner Seit'',<br/>Stets eins und nie gespalten seid,<br/>Sein Herz zufriedenstellt allzeit,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Sein Herz zufriedenstellt allzeit,<br/>Oh, lob den Herrn!<br/>',NULL,48243,5);
INSERT INTO stanza VALUES('G409','6','Oh, König komm, o liebster Herr!<br/>Nimm uns nach Deinem Wort zur Ehr,<br/>Den Lohn den Siegern nicht verwehr,<br/>Oh, lob den Herrn!<br/>Oh, lob den Herrn! Oh, lob den Herrn!<br/>Den Lohn den Siegern nicht verwehr,<br/>Oh, lob den Herrn!<br/>',NULL,48244,6);
INSERT INTO stanza VALUES('G410','1','Zehn Jungfrauen gingen hinaus<br/>Die Lampe mit sich jede trug;<br/>Den Bräutigam wollten sie sehn,<br/>Nur fünf waren allerdings klug.<br/>Die Klugen viel Öl trugen mit,<br/>Die Törichten warn jedoch leer;<br/>Die Klugen benutzten die Zeit,<br/>Die anderen trödelten sehr.<br/>',NULL,48245,1);
INSERT INTO stanza VALUES('G410','2','O Herr, Deine Botschaft ist klar:<br/>Du nimmst nur die Klugen für Dich,<br/>Die heute ihr Öl kaufen ein,<br/>Von Bindungen lösen sie sich.<br/>Wer Ihm gleichgeformt ist und reif,<br/>Wer Öl fürs Gefäß kaufte ein,<br/>Verleugnet sich bis in den Tod –<br/>Darf König im Königreich sein.<br/>',NULL,48246,2);
INSERT INTO stanza VALUES('G410','3','Wir machen die Lampe zurecht:<br/>Dich rufen wir an jeden Tag;<br/>Wir üben uns ständig im Geist,<br/>Dass Altheit verbrennt werden mag.<br/>Es braucht doch noch Tieferes mehr:<br/>Dass Wirklichkeit in mir ersprießt,<br/>Bis sie dann macht Wohnung in mir,<br/>Bis Öl im Gefäß überfließt.<br/>',NULL,48247,3);
INSERT INTO stanza VALUES('G410','4','Wie finster das Zeitalter ist!<br/>Es naht sich die herrliche Stund;<br/>Ja, kommen kann Er jederzeit –<br/>In uns diese Ehrfurcht entzünd!<br/>So kaufen wir unsre Zeit aus,<br/>Dein Wort nehmen betend treu ein,<br/>Lektionen von Dir nehmen an,<br/>Bereit für den Tag so zu sein.<br/>',NULL,48248,4);
INSERT INTO stanza VALUES('G410','5','O Herr, welch ein Segen ist es,<br/>Dein Reich nun zu bringen zur Erd,<br/>Dass Du über alles regierst,<br/>Dann stellst Du zur Schau Deinen Wert!<br/>Welch Segen, am Feste zu sein!<br/>Dort eins bist Du mit Deiner Braut,<br/>Als Jungfrauen mach uns so klug,<br/>Zusammen mit Dir, so vertraut.<br/>',NULL,48249,5);
INSERT INTO stanza VALUES('G411','1','Voller Öl ist die Lampe – wir brennen!<br/>Unsre Lampe brennt hell und weit!<br/>Herr, zum Geist hilf uns stets uns zu wenden,<br/>Uns zum Geist zu wenden allezeit!<br/>',NULL,48250,1);
INSERT INTO stanza VALUES('G411','chorus','O Herr! Amen! Halleluja!<br/>Ja, wir brennen, brennen hell und weit!<br/>O Herr! Amen! Halleluja!<br/>Wenden, wenden allezeit!<br/>',NULL,48251,2);
INSERT INTO stanza VALUES('G411','2','Doch wir brauchen in unsren Gefäßen<br/>Für Dein Kommen noch Öl-Vorrat;<br/>Und so füllen wir unsre Gefäße,<br/>Dass die Lampe allezeit Licht hat.<br/>',NULL,48252,3);
INSERT INTO stanza VALUES('G411','chorus','O Herr, füll uns! O Herr, füll uns!<br/>Jeden Augenblick, zu jeder Zeit!<br/>O Herr, füll uns! O Herr, füll uns!<br/>Füll uns mit der Wirklichkeit!<br/>',NULL,48253,4);
INSERT INTO stanza VALUES('G411','3','Wir wolln brennen bis Christus zurückkommt<br/>Brennen stets bis zu jenem Tag;<br/>Wenn wir feiern mit Ihm dann die Hochzeit,<br/>Unsre Lampe hell zu strahln vermag.<br/>',NULL,48254,5);
INSERT INTO stanza VALUES('G411','chorus','Komm, Herr Jesus! Komm, Herr Jesus!<br/>Finde uns gefüllt und brennend hell!<br/>Komm, Herr Jesus! Komm, Herr Jesus!<br/>Freu Dich an der Braut, komm schnell!<br/>',NULL,48255,6);
INSERT INTO stanza VALUES('G412','1','Alles aufs Ende zeigt hin,<br/>Christus wird bald zu uns ziehn;<br/>Macht euch bereit nun für Ihn,<br/>Jesus kommt wieder zurück!<br/>',NULL,48256,1);
INSERT INTO stanza VALUES('G412','chorus','Wieder zurück, wieder zurück,<br/>Eilig geht die Zeit vorbei,<br/>Bald erschallt schon der Mitternachtsschrei!<br/>Wieder zurück, wieder zurück,<br/>Als kluge Jungfrauen macht euch bereit!<br/>Jesus kommt wieder zurück!<br/>',NULL,48257,2);
INSERT INTO stanza VALUES('G412','2','Wend dich vom Selbst ab schon hier,<br/>Und dich auf Ihn konzentrier;<br/>Nun keine Zeit mehr verlier –<br/>Jesus kommt wieder zurück!<br/>',NULL,48258,3);
INSERT INTO stanza VALUES('G412','3','Törichte wenden sich nie;<br/>Erst wenn Er kommt, lernen sie,<br/>Doch nun vom Öl viel bezieh –<br/>Jesus kommt wieder zurück!<br/>',NULL,48259,4);
INSERT INTO stanza VALUES('G412','4','Kluge Jungfraun – nützt die Zeit,<br/>Seid von der Welt ganz befreit,<br/>Füllt euch im Geist und strahlt weit –<br/>Jesus kommt wieder zurück!<br/>',NULL,48260,5);
INSERT INTO stanza VALUES('G412','5','Lasst uns hinaus zu Ihm gehn,<br/>Täglich mehr Öl wir erstehn,<br/>Lasst euer Licht nicht ausgehn –<br/>Jesus kommt wieder zurück!<br/>',NULL,48261,6);
INSERT INTO stanza VALUES('G412','6','Sein Kommen ist nicht mehr weit,<br/>Wacht, denn ihr kennt nicht die Zeit;<br/>Oh, bleibt in Ihm! Seid bereit –<br/>Jesus kommt wieder zurück!<br/>',NULL,48262,7);
INSERT INTO stanza VALUES('G413','1','Bald, Herr, erscheinst Du hier,<br/>Vorfreude haben wir.<br/>Nah ist Dein Tag, der strahlt so hell!<br/>Du nur bist unser Herr,<br/>Dich lieben wir so sehr,<br/>Oh, liebster Bräutigam, komm schnell!<br/>',NULL,48263,1);
INSERT INTO stanza VALUES('G413','2','Bald ist Dein Tag schon da,<br/>Dein Ruf ist schon so nah,<br/>Und in der Wolke kommst Du gleich.<br/>Oh, Stunde süß und traut,<br/>Wenn Bräutigam trifft Braut,<br/>Und Liebe füllt sie ohnegleich!<br/>',NULL,48264,2);
INSERT INTO stanza VALUES('G413','3','Schnell wird die Zeit vergehn,<br/>Bis wir Dein Antlitz sehn!<br/>Amen, Herr Jesus! Komm doch bald!<br/>Nach Dir uns sehnen wir,<br/>Ewig zu sein mit Dir,<br/>Dir unser Herz entgegenwallt.<br/>',NULL,48265,3);
INSERT INTO stanza VALUES('G413','4','Nur noch ein Augenblick<br/>Du, Herr, kommst schnell zurück<br/>Und Deine Braut dann forderst ein.<br/>O Halleluja!<br/>Bald sind wir Dir so nah,<br/>Und Du wirst dann zufrieden sein.<br/>',NULL,48266,4);
INSERT INTO stanza VALUES('G414','1','Freut euch! Denn unser Bräutigam kommt,<br/>Und die Zeit ist nicht mehr lang,<br/>Bis der Hochzeit wir entgegensehen<br/>Und begrüßen mit Gesang.<br/>',NULL,48267,1);
INSERT INTO stanza VALUES('G414','chorus','Wunderbarer Tag! Oh, heller Morgen,<br/>An dem Christus wiederkehrt:<br/>Mit Gefäß gefüllt und Lampe leuchtend,<br/>Nun Sein Wiederkommen ehrt!<br/>Freut euch! Denn unser Bräutigam kommt,<br/>Und die Zeit ist nicht mehr lang,<br/>Bis der Hochzeit wir entgegensehen<br/>Und begrüßen mit Gesang.<br/>',NULL,48268,2);
INSERT INTO stanza VALUES('G414','2','Oh, kauft doch jeden Augenblick aus,<br/>Auf das Kaufen gebt doch Acht,<br/>Damit auch euer Gefäß voll Öl ist,<br/>Eh es ruft um Mitternacht.<br/>',NULL,48269,3);
INSERT INTO stanza VALUES('G414','3','Welch Freude bringt uns Vorbereitung<br/>Auf die Hochzeit mit dem Herrn!<br/>Solcher Wonne der Belohnung wegen<br/>Leiden wir gar Trübsal gern!<br/>',NULL,48270,4);
INSERT INTO stanza VALUES('G414','4','Ja, mit Entrückung und viel Freude<br/>Unser Hochzeitstag beginnt;<br/>Dann feiern wir eintausend Jahre,<br/>Unser Herz nur darauf sinnt!<br/>',NULL,48271,5);
INSERT INTO stanza VALUES('G415','1','Hoffnung der Herrlichkeit, Christus kommt bald!<br/>Wird uns entrücken, uns bringen ins Reich;<br/>Mit Ihm verherrlicht genießen wir Ihn,<br/>Tragen Sein Bild, sind dann völlig Ihm gleich.<br/>',NULL,48272,1);
INSERT INTO stanza VALUES('G415','chorus','Herrliche Hoffnung! Christus kommt bald!<br/>Herrliche Hoffnung! Christus kommt bald!<br/>Bald uns entrückt und mit Herrlichkeit schmückt,<br/>Herrliche Hoffnung! Denn Christus kommt bald!<br/>',NULL,48273,2);
INSERT INTO stanza VALUES('G415','2','Hoffnung der Herrlichkeit, Christus kommt bald!<br/>Die alte Schöpfung gelangt dann zum Schluss,<br/>Niemals mehr seufzen wir, denn wir sind frei,<br/>Volle Errettung ist höchster Genuss.<br/>',NULL,48274,3);
INSERT INTO stanza VALUES('G415','3','Hoffnung der Herrlichkeit, Christus kommt bald!<br/>Völker regiern wir mit Ihm auf dem Thron,<br/>Dienen als Priester vor Ihm allezeit,<br/>Volle Errettung schenkt Er uns als Lohn.<br/>',NULL,48275,4);
INSERT INTO stanza VALUES('G415','4','Hoffnung der Herrlichkeit, Christus kommt bald!<br/>Wartend und wachend, so treu wir Ihm dien''n,<br/>Laufen den Wettlauf und jagen zum Ziel,<br/>Sein Königreich ist dann unser Gewinn.<br/>',NULL,48276,5);
INSERT INTO stanza VALUES('G416','1','Gottes ew''ger Vorsatz<br/>Geht den Menschen an:<br/>Ein Gefäß ist er für<br/>Gott und Seinen Plan.<br/>So legt Gott Sein Leben<br/>In den Mensch hinein;<br/>Er, mit Gott in Einheit,<br/>Kann Ihm Ausdruck sein.<br/>',NULL,48277,1);
INSERT INTO stanza VALUES('G416','2','Gott hat uns geschaffen<br/>Ganz nach Seinem Bild,<br/>Dass Sein Plan erfüllt wird,<br/>Sein Verlangn gestillt;<br/>Als den Baum des Lebens<br/>Nehmen wir Ihn an,<br/>Werden Seine Fülle,<br/>Wie die Frau dem Mann.<br/>',NULL,48278,2);
INSERT INTO stanza VALUES('G416','3','Durch Sein reiches Fließen<br/>Prägt Sein Bild uns ein,<br/>Werden wir gewandelt<br/>In kostbaren Stein.<br/>Als Sein Gegenüber<br/>Werden wir gebaut,<br/>Sind wir Seine Wohnung,<br/>Was Sein Herz erbaut.<br/>',NULL,48279,3);
INSERT INTO stanza VALUES('G416','4','In der Stadt so heilig,<br/>Neu''s Jerusalem,<br/>Wohnt Gott in den Heil''gen,<br/>Sie sind eins mit Ihm.<br/>Er wird sein ihr Inhalt,<br/>Strahlt aus ihr, hell scheint;<br/>Herrlichkeit sie kleidet,<br/>Ganz mit Ihm vereint.<br/>',NULL,48280,4);
INSERT INTO stanza VALUES('G416','5','Christus ist das Zentrum,<br/>Auf dem Thron herrscht Er,<br/>Und Sein Leben festigt<br/>Ihre Einheit sehr.<br/>Durch Sein Scheinen sind die<br/>Heiligen im Licht.<br/>Harmonie erfreut sie,<br/>Welche schöne Sicht!<br/>',NULL,48281,5);
INSERT INTO stanza VALUES('G416','6','Er tränkt sie mit Leben,<br/>Kräftigt sie als Speis;<br/>Ihren Durst und Hunger<br/>Stets zu stillen weiß.<br/>In Gott als dem Tempel<br/>Leben sie allzeit,<br/>Und sie beten an vor<br/>Ihm in Ewigkeit.<br/>',NULL,48282,6);
INSERT INTO stanza VALUES('G417','1','Gott hat ewig einen Vorsatz<br/>Seit vergangner Ewigkeit,<br/>Bis in die entfernte Zukunft<br/>Und dazwischen liegt die Zeit.<br/>Um ihn zu erfüllen, wirkt Er,<br/>In der Zeit wird er vollbracht;<br/>Wir sind in der Zeit nur Wandrer –<br/>Weil für Ewigkeit gedacht.<br/>',NULL,48283,1);
INSERT INTO stanza VALUES('G417','2','Gott will eine Menschengruppe,<br/>Aufgebaut nach Seinem Plan,<br/>Die als Sein Gefäß vereint sind,<br/>Gehn als neuer Mensch voran.<br/>Mit Seiner Natur und Leben<br/>Es zu fülln, ist Gott gewillt,<br/>Seinen Geist vermengt mit unsrem,<br/>Ihm das Lob und Freude gilt.<br/>',NULL,48284,2);
INSERT INTO stanza VALUES('G417','3','Gott ist Drei für Seinen Vorsatz,<br/>Führt ihn aus so wunderbar.<br/>Als der Vater, Sohn und Geist nun,<br/>Reicht Er Sich uns herrlich dar!<br/>Alle Schöpfung ist der Rahmen –<br/>Gottes Vorsatz Dienst erweist;<br/>Mit drei Teilen machte Gott uns,<br/>Leib und Seele und dem Geist.<br/>',NULL,48285,3);
INSERT INTO stanza VALUES('G417','4','Kern und Ziel von Gottes Plan ist<br/>Unser tiefster Teil, der Geist;<br/>Wenn wir Jesus rufen, wird er<br/>Eins mit Seinem fest geschweißt!<br/>Gott erneuert uns vom Geist aus,<br/>Jeden Teil von unsrem Sein,<br/>Den Verstand, Gefühl und Willn,<br/>Unser ganzes Herz nimmt ein.<br/>',NULL,48286,4);
INSERT INTO stanza VALUES('G417','5','Aufgebaut im Leben, sodass<br/>Liebe uns verknüpft sodann;<br/>Gott vollendet Seinen Vorsatz,<br/>Bringt zum Schluss was Er begann.<br/>Herr, in uns nimm zu doch täglich,<br/>Baue uns nun völlig ein<br/>Ins gemeinsame Gefäß, das<br/>Ist mit Gott erfüllt allein.<br/>',NULL,48287,5);
INSERT INTO stanza VALUES('G417','6','Die Gemeinde, die Erfüllung,<br/>Wird dann stehn in Herrlichkeit,<br/>Als Vollendung Seines Planes,<br/>Schon gefasst vor Ewigkeit.<br/>Sein gemeinsames Gefäß wird<br/>Füllen Seine Herrlichkeit;<br/>Herr, Dein Ziel in uns erreiche,<br/>Dafür Stelln wir uns bereit.<br/>',NULL,48288,6);
INSERT INTO stanza VALUES('G418','1','Gottes Hauptgedanke ist<br/>Mit dem Menschen eins zu sein;<br/>Gott will alles sein für ihn,<br/>So erfüllt Gott Seinen Plan.<br/>',NULL,48289,1);
INSERT INTO stanza VALUES('G418','2','Gott erschuf ihn als Gefäß –<br/>Leib und Seele und den Geist,<br/>Gottes Leben soll ihn fülln,<br/>Ihn mit Gott vereint und speist.<br/>',NULL,48290,2);
INSERT INTO stanza VALUES('G418','3','Fließt der Lebensstrom in ihm,<br/>Wird der Mensch zum Edelstein;<br/>Seine Stadt baut Gott mit ihm,<br/>Dass aus ihr erstrahlt Sein Schein.<br/>',NULL,48291,3);
INSERT INTO stanza VALUES('G418','4','Diese Stadt von Gott gebaut,<br/>Diese Wohnung, die Gott will,<br/>Dieses Neu Jerusalem,<br/>Ist Sein Herzenswunsch und Ziel.<br/>',NULL,48292,4);
INSERT INTO stanza VALUES('G418','5','Sieh den Bau aus Heiligen,<br/>Gott und Mensch in Einigkeit;<br/>Dies der Plan des Vaters war<br/>Lange vor Beginn der Zeit.<br/>',NULL,48293,5);
INSERT INTO stanza VALUES('G418','6','Gottes und des Lammes Thron<br/>Ihre Macht und Mitte ist;<br/>Hier entspringt der Lebensstrom,<br/>Gottes Geist als Leben fließt.<br/>',NULL,48294,6);
INSERT INTO stanza VALUES('G418','7','Christus, Baum des Lebens, steht<br/>An dem klaren Strom, dem Geist;<br/>Frucht des Lebens trägt er reich,<br/>Uns mit höchstem Leben speist.<br/>',NULL,48295,7);
INSERT INTO stanza VALUES('G418','8','Gott in Christus scheint als Licht,<br/>Er vertreibt die Todesnacht;<br/>Gottes Lebenslicht erstrahlt<br/>In der Stadt so hell mit Macht.<br/>',NULL,48296,8);
INSERT INTO stanza VALUES('G418','9','Gott im Menschen, Mensch in Gott,<br/>Gegenseitig Wohnung sind;<br/>Gott erfüllt den Menschen ganz,<br/>Dass er Gott zum Ausdruck bringt.<br/>',NULL,48297,9);
INSERT INTO stanza VALUES('G419','1','Gottes Ökonomie ist, dass der Mensch wird genau wie Er<br/>Im Leben und Natur, doch nicht in der Gottheit.<br/>Mit dem Menschen macht Er Sich eins<br/>Und den Menschen eins mit Sich.<br/>So wird Er vergrößert und erweitert in Seinem Ausdruck,<br/>Dass all Seine göttlichen Eigenschaften<br/>Nun zum Ausdruck kommen in menschlichen Tugenden.<br/>',NULL,48298,1);
INSERT INTO stanza VALUES('G420','1','Welch Wunder! Welch Geheimnis dies! –<br/>Dass Gott und Mensch vermengt nun sei''n.<br/>Gott wurde Mensch, dass Mensch Gott werd,<br/>Ökonomie so ungemein!<br/>Sein Wohlgefallen, Herzenswunsch,<br/>Sein höchstes Ziel erlangt wird sein.<br/>',NULL,48299,1);
INSERT INTO stanza VALUES('G420','2','Fleisch wurde Er! Der erst Gott-Mensch,<br/>Sein Wunsch: Ich möge auch Gott sein;<br/>Leben, Natur nach Gottes Art,<br/>Doch Gottheit Ihm verbleibt allein;<br/>Durch meine Tugenden erstrahlt<br/>Sein Bild voll Eigenschaften rein.<br/>',NULL,48300,2);
INSERT INTO stanza VALUES('G420','3','Nicht mehr alleine lebe ich,<br/>Weil Gott zusammen lebt mit mir.<br/>In Gott die Heil''gen eingebaut,<br/>Für beide eine Wohnung wir<br/>Und Sein Leib so organisch nun,<br/>Für Seinen Ausdruck korp''rativ.<br/>',NULL,48301,3);
INSERT INTO stanza VALUES('G420','4','Jerusalem – der Höhepunkt,<br/>Aller Visionen Ganzheit wahr;<br/>Dreieiner Gott, dreiteil''ger Mensch<br/>Sind ewiglich ein Liebespaar –<br/>Als Mensch doch Gott, so wohnen sie<br/>In vollem Ineinander-Sein.<br/>Nun Gottes Herrlichkeit erstrahlt<br/>In Menschlichkeit mit hellem Schein!<br/>',NULL,48302,4);
INSERT INTO stanza VALUES('G421','1','Strom des lebendigen Wassers<br/>Gottes Thron sprudelnd entspringt,<br/>Führt mit sich süße Gemeinschaft,<br/>Gottes Autorität bringt.<br/>',NULL,48303,1);
INSERT INTO stanza VALUES('G421','chorus','Strom des lebendigen Wassers,<br/>Frei sich Gemeinschaft ergießt;<br/>Er führt mit sich Gottes Vollmacht<br/>Überallhin, wo er fließt.<br/>',NULL,48304,2);
INSERT INTO stanza VALUES('G421','2','Wasser des Lebens im Geiste,<br/>Gott ist das Leben darin;<br/>Stets Seine Herrschaft befördernd,<br/>Fließt der Strom überall hin.<br/>',NULL,48305,3);
INSERT INTO stanza VALUES('G421','3','Klar auf der goldenen Straße<br/>Lässt er uns Gottes Weg sehn;<br/>Wie er in Gottes Natur fließt,<br/>So wolln wir Seinen Weg gehn.<br/>',NULL,48306,4);
INSERT INTO stanza VALUES('G421','4','Neben dem Fluss weist der Baum auf,<br/>Dass Gott für uns Speise ist;<br/>Jeder, der von diesem Strom trinkt,<br/>Früchte des Baumes genießt.<br/>',NULL,48307,5);
INSERT INTO stanza VALUES('G422','1','Erlösung hat der Herr vollbracht:<br/>Oh, welch herrlicher Retter!<br/>Den Preis bezahlt, mich frei gemacht:<br/>Oh, welch herrlicher Retter!<br/>',NULL,48308,1);
INSERT INTO stanza VALUES('G422','chorus','Oh, welch herrlicher Retter ist Jesus, mein Retter!<br/>Oh, welch herrlicher Retter ist Jesus, mein Herr!<br/>',NULL,48309,2);
INSERT INTO stanza VALUES('G422','2','Für mich gab Er Sein Blut im Tod,<br/>Oh, welch herrlicher Retter!<br/>Versöhnte mich vollauf mit Gott,<br/>Oh, welch herrlicher Retter!<br/>',NULL,48310,3);
INSERT INTO stanza VALUES('G422','3','Er wäscht von jeder Sünde rein:<br/>Oh, welch herrlicher Retter!<br/>Und jetzt herrscht Er in meinem Sein,<br/>Oh, welch herrlicher Retter!<br/>',NULL,48311,4);
INSERT INTO stanza VALUES('G422','4','Er wohnt in mir und macht mich neu,<br/>Oh, welch herrlicher Retter!<br/>Auf meinem Weg bewahrt mich treu,<br/>Oh, welch herrlicher Retter!<br/>',NULL,48312,5);
INSERT INTO stanza VALUES('G422','5','Er gibt mir Überwinderkraft,<br/>Oh, welch herrlicher Retter!<br/>Den Sieg in Kämpfen mir verschafft,<br/>Oh, welch herrlicher Retter!<br/>',NULL,48313,6);
INSERT INTO stanza VALUES('G422','6','Ich gebe Ihm mein Herz ganz hin,<br/>Oh, welch herrlicher Retter!<br/>Die Welt hat keinen Platz darin,<br/>Oh, welch herrlicher Retter!<br/>',NULL,48314,7);
INSERT INTO stanza VALUES('G423','1','Oh, welch finstre Nacht einst meinen Geist umhüllt!<br/>Oh, welch Schmerz mein''n Retter hat gefüllt,<br/>Als Er durch die Wasser meiner Seele ging,<br/>Und mich heilte, dass ich nun froh sing!<br/>',NULL,48315,1);
INSERT INTO stanza VALUES('G423','chorus','Jesus ging für mich den Weg nach Golgatha,<br/>Er ging für mich, Er ging für mich;<br/>Jesus ging für mich den Weg nach Golgatha,<br/>Er starb und ich bin frei.<br/>',NULL,48316,2);
INSERT INTO stanza VALUES('G423','2','Als ein Sünder kam ich vor Sein Angesicht,<br/>Gnade und Vergebung kannte nicht;<br/>„Hör auf zu bereuen“ sagt Er sanft schon bald,<br/>„Deine Schuld hat Jesus schon bezahlt.“<br/>',NULL,48317,3);
INSERT INTO stanza VALUES('G423','3','Große Liebe zeigte der Erlöser mir!<br/>Als Er Seinen Thron fürs Kreuz gab her;<br/>Er trug mein Vergehen, trug es ganz allein,<br/>Seinen Namen lob und verkünd ich sehr.<br/>',NULL,48318,4);
INSERT INTO stanza VALUES('G424','1','Christus ist eins jetzt mit Sündern,<br/>Er kam, um bei uns zu leben;<br/>Wurde für Sünder gekreuzigt,<br/>Herrliches Leben will geben.<br/>',NULL,48319,1);
INSERT INTO stanza VALUES('G424','chorus','O Jesus kam für uns,<br/>O Christus starb für uns;<br/>O ja, für uns, für uns, für uns,<br/>Er kam und starb für uns.<br/>',NULL,48320,2);
INSERT INTO stanza VALUES('G425','1','Was fürcht ich denn und zweifle ich?<br/>Gab Gott nicht Seinen Sohn für mich?<br/>Am Kreuz hing meine Sünd.<br/>All meine Schuld bezahlt hat Er,<br/>Wird Gott Sich ändern, fordern mehr?<br/>Nein, Christus hat gesühnt!<br/>',NULL,48321,1);
INSERT INTO stanza VALUES('G425','2','Erlösung hat der Herr vollbracht,<br/>Von meinen Schulden freigemacht,<br/>Und vom Gesetz befreit.<br/>Nein, Gottes Zorn mich nicht versengt,<br/>Ich bin mit Jesu Blut besprengt,<br/>Es spricht für mich allzeit.<br/>',NULL,48322,2);
INSERT INTO stanza VALUES('G425','3','Dank Jesu Blut vergab mir Gott,<br/>Und sprach mich ewig frei vom Tod,<br/>Denn meine Schuld strich Er;<br/>Gott fordert nicht ein zweites Mal,<br/>Vom Sohn, dem Bürgen Seiner Wahl,<br/>Und dann von mir noch mehr.<br/>',NULL,48323,3);
INSERT INTO stanza VALUES('G425','4','Mein Herz nun vollen Frieden hat,<br/>Mein Retter Christus alles tat,<br/>Mich machte frei für Sich;<br/>Sein Blut so wirksam schätz ich sehr,<br/>Verdammen kann mich Gott nicht mehr,<br/>Denn Christus starb für mich!<br/>',NULL,48324,4);
INSERT INTO stanza VALUES('G426','1','Da ist ein Brunnen voller Blut,<br/>Der aus Immanuel floss;<br/>O Sünder, tauch in diese Flut!<br/>Werd Schulden-Flecken los!<br/>Werd Schulden-Flecken los!<br/>Werd Schulden-Flecken los!<br/>O Sünder, tauch in diese Flut!<br/>Werd Schulden-Flecken los!<br/>',NULL,48325,1);
INSERT INTO stanza VALUES('G426','2','Am Kreuz der Räuber freute sich,<br/>Zu sehn den Brunnen dort;<br/>Und arg wie er, dort wasch auch ich<br/>All meine Sünden fort:<br/>All meine Sünden fort,<br/>All meine Sünden fort;<br/>Und arg wie er, dort wasch auch ich<br/>All meine Sünden fort.<br/>',NULL,48326,2);
INSERT INTO stanza VALUES('G426','3','Du liebster Lamm, dein teures Blut<br/>Gibt Kraft beständig her,<br/>Bis die Erlösten sind befreit,<br/>Und sündigen nicht mehr:<br/>Und sündigen nicht mehr,<br/>Und sündigen nicht mehr;<br/>Bis die Erlösten sind befreit,<br/>Und sündigen nicht mehr.<br/>',NULL,48327,3);
INSERT INTO stanza VALUES('G426','4','Seit Glaube bracht'' den Strom in Sicht,<br/>Der floss am Kreuz für mich,<br/>Mein Herz von der Erlösung spricht<br/>Bis Gott mich nimmt zu Sich:<br/>Bis Gott mich nimmt zu Sich,<br/>Bis Gott mich nimmt zu Sich;<br/>Mein Herz von der Erlösung spricht<br/>Bis Gott mich nimmt zu Sich.<br/>',NULL,48328,4);
INSERT INTO stanza VALUES('G426','5','Wenn meine Stimme einst verklingt,<br/>Dem Grab wird überbracht,<br/>Dann meine Seele froh lobsingt:<br/>Du rettest voller Macht:<br/>Du rettest voller Macht,<br/>Du rettest voller Macht;<br/>Dann meine Seele froh lobsingt,<br/>Du rettest voller Macht.<br/>',NULL,48329,5);
INSERT INTO stanza VALUES('G427','1','Kennst du Jesu Blut? Es reinigt voller Kraft!<br/>Gottes Lamm wäscht dich rein durch Sein Blut!<br/>Glaubst du, dass die Gnade es in dir auch schafft<br/>Und dich reinigt im kostbaren Blut?<br/>',NULL,48330,1);
INSERT INTO stanza VALUES('G427','chorus','Bist du rein durch Sein Blut,<br/>Durch das reinigendes, kostbares Blut?<br/>Ja, sind Deine Kleider rein und weiß wie Schnee?<br/>Gottes Lamm wäscht dich rein durch Sein Blut!<br/>',NULL,48331,2);
INSERT INTO stanza VALUES('G427','2','Wandelst du im Alltag mit dem Retter nun?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Willst du allezeit am Kreuz in Jesus ruhn?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>',NULL,48332,3);
INSERT INTO stanza VALUES('G427','3','Wenn der Bräutigam erscheint, ist weiß dein Kleid?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Deine Seele für Sein Kommen mach bereit,<br/>Sei gewaschen im kostbaren Blut!<br/>',NULL,48333,4);
INSERT INTO stanza VALUES('G427','4','Die von Sünd befleckten Kleider lege ab,<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Deine Seele froh im Quell des Blutes bad,<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>',NULL,48334,5);
INSERT INTO stanza VALUES('G428','1','Was wäscht meine Sünde weg?<br/>Nur das Blut des Lammes Jesu;<br/>Was nur stellt mich wieder her?<br/>Nur das Blut des Lammes Jesu.<br/>',NULL,48335,1);
INSERT INTO stanza VALUES('G428','chorus','Kostbar ist Jesu Blut,<br/>Schneeweiß mich wäscht – wie gut!<br/>Kein andrer Strom dies tut,<br/>Nur das Blut des Lammes Jesu.<br/>',NULL,48336,2);
INSERT INTO stanza VALUES('G428','2','Was nur reinigt? Ja, ich seh –<br/>Nur das Blut des Lammes Jesu!<br/>Gott vergibt mir, wenn ich fleh,<br/>Nur das Blut des Lammes Jesu!<br/>',NULL,48337,3);
INSERT INTO stanza VALUES('G428','3','Was tilgt Sündenschulden hier? –<br/>Nur das Blut des Lammes Jesu!<br/>Nur aus Gnade, nichts aus mir –<br/>Nur das Blut des Lammes Jesu!<br/>',NULL,48338,4);
INSERT INTO stanza VALUES('G428','4','Was hat mich gerecht gemacht? –<br/>Nur das Blut des Lammes Jesu!<br/>Hoffnung, Frieden mir gebracht? –<br/>Nur das Blut des Lammes Jesu!<br/>',NULL,48339,5);
INSERT INTO stanza VALUES('G429','1','Möchtest du frei von der Sündenlast sein?<br/>Die Kraft ist im Blut, Kraft ist im Blut;<br/>Willst du, dass Sieg über Böses zieht ein?<br/>Die heilende Kraft ist im Blut.<br/>',NULL,48340,1);
INSERT INTO stanza VALUES('G429','chorus','Es ist Kraft, Kraft, wunderbare Kraft,<br/>In dem Blut dieses Lamms;<br/>Es ist Kraft, Kraft, wunderbare Kraft,<br/>In dem kostbaren Blut dieses Lamms.<br/>',NULL,48341,2);
INSERT INTO stanza VALUES('G429','2','Möchtest du frei sein von Stolz und von Lust?<br/>Die Kraft ist im Blut, Kraft ist im Blut;<br/>Reinige dich doch im Golgatha-Fluss,<br/>Die heilende Kraft ist im Blut.<br/>',NULL,48342,3);
INSERT INTO stanza VALUES('G429','3','Möchtest du weißer als Schneeflocken sein?<br/>Die Kraft ist im Blut, Kraft ist im Blut;<br/>Leben im Strom wäscht von Sündflecken rein,<br/>Die heilende Kraft ist im Blut.<br/>',NULL,48343,4);
INSERT INTO stanza VALUES('G429','4','Möchtest du Jesus dem Herrn dienen mehr?<br/>Die Kraft ist im Blut, Kraft ist im Blut;<br/>Willst du Ihm leben, Ihm singen zur Ehr?<br/>Die heilende Kraft ist im Blut.<br/>',NULL,48344,5);
INSERT INTO stanza VALUES('G430','1','Was bewahrt die Wanderer davor, verlorn zu gehn?<br/>Nichts als nur die Liebe Jesu!<br/>Was bewirkt, dass sie die Welt und Sünde lassen stehn?<br/>Nichts als nur die Liebe Jesu!<br/>',NULL,48345,1);
INSERT INTO stanza VALUES('G430','chorus','Nur die Liebe Jesu hält dich immer fest!<br/>Nur die Liebe Jesu stützt dich, dass du stehst!<br/>Sie bringt dir Errettung, wenn du sie erflehst,<br/>Nur die Liebe Jesu Christi!<br/>',NULL,48346,2);
INSERT INTO stanza VALUES('G430','2','Was verjagt die Bitterkeit von dem, der leiden muss?<br/>Nichts als nur die Liebe Jesu!<br/>Was wischt ab die Tränen und befreit uns von Verdruss?<br/>Nichts als nur die Liebe Jesu!<br/>',NULL,48347,3);
INSERT INTO stanza VALUES('G430','3','Welche Salbe für die wunden Herzen heilt den Schmerz?<br/>Nichts als nur die Liebe Jesu!<br/>Welcher Regen in der Dürre tröstet jedes Herz?<br/>Nichts als nur die Liebe Jesu!<br/>',NULL,48348,4);
INSERT INTO stanza VALUES('G430','4','Was erfüllt ein Menschenleben voller Nichtigkeit?<br/>Nichts als nur die Liebe Jesu!<br/>Was nur kann verschlingen den Geschmack der Sterblichkeit?<br/>Nichts als nur die Liebe Jesu!<br/>',NULL,48349,5);
INSERT INTO stanza VALUES('G431','1','Gott in Christus wurde Fleisch, zu einem Menschen, so wie ich,<br/>Starb am Kreuz und so von Adam wunderbar befreite mich,<br/>Auferstand und kam als Geist in mir zu leben ewiglich,<br/>Mein Leben ist der Herr.<br/>',NULL,48350,1);
INSERT INTO stanza VALUES('G431','chorus','Erster Refrain:<br/>Lobt den Herrn! O Halleluja!<br/>Lobt den Herrn! O Halleluja!<br/>Lobt den Herrn! O Halleluja!<br/>Mein Leben Christus ist!<br/>',NULL,48351,2);
INSERT INTO stanza VALUES('G431','chorus','Zweiter Refrain:<br/>Welch ein Sieg! O Halleluja!<br/>Welch ein Sieg! O Halleluja!<br/>Welch ein Sieg! O Halleluja!<br/>Mein Alles Christus ist!<br/>',NULL,48352,3);
INSERT INTO stanza VALUES('G432','1','Wer kann uns von Sünd befrein?<br/>Christus nur! Christus nur!<br/>Wer kann unser Leben sein?<br/>Christus nur!<br/>Christus nur! Christus nur!<br/>Christus nur kann uns befrein,<br/>Christus nur!<br/>',NULL,48353,1);
INSERT INTO stanza VALUES('G433','1','Versklavt in Sünde ist der Mensch,<br/>Voll Todesgift ist er;<br/>Von Tod und Sünde retten kann<br/>Nur Christus, unser Herr.<br/>Er lebt in alle Ewigkeit,<br/>Uns ganz befreien will;<br/>Wenn wir an Ihn nicht glauben wolln,<br/>Im Elend sterben still.<br/>',NULL,48354,1);
INSERT INTO stanza VALUES('G434','1','Du brauchst Christus, nur Er errettet dich,<br/>Ja, Er ist Gott, auch Mensch wie du und ich;<br/>Er erlitt in dem Leib so schwere Pein,<br/>Sein Tod macht dich von Flecken rein,<br/>Ja, du brauchst Jesus!<br/>',NULL,48355,1);
INSERT INTO stanza VALUES('G434','chorus','Du brauchst Jesus! Du brauchst Jesus!<br/>Alle Menschen brauchen Ihn!<br/>Zur Erlösung brauchst du Ihn,<br/>Zur Errettung brauchst du Ihn!<br/>Willst du Gottes Leben?<br/>Ja, dann brauchst du Jesus!<br/>',NULL,48356,2);
INSERT INTO stanza VALUES('G434','2','Auferstanden, zum Himmel fuhr Er auf,<br/>Uns Gottes Leben schenkte Er vollauf;<br/>Jetzt empfang Ihn, im Herzen glaub an Ihn,<br/>Die Sehnsucht kann Er dir erfülln,<br/>Ja, du brauchst Jesus!<br/>',NULL,48357,3);
INSERT INTO stanza VALUES('G434','3','Leuchten will Er hinein in deine Nacht,<br/>Vergibt die Sünden, rettet dich mit Macht,<br/>Und Sein Blut wäscht die Flecken weg im Nu,<br/>Sein Leben gibt Er dir dazu.<br/>Ja, du brauchst Jesus!<br/>',NULL,48358,4);
INSERT INTO stanza VALUES('G434','4','Mangel spürst du in deinem Leben sehr,<br/>Und dieser wächst von Jahr zu Jahr noch mehr,<br/>Einzig Jesus zufriedenstellen kann,<br/>Verschlingt die Nichtigkeit sodann.<br/>Ja, Du brauchst Jesus!<br/>',NULL,48359,5);
INSERT INTO stanza VALUES('G434','chorus','Du brauchst Jesus! Du brauchst Jesus!<br/>Alle Menschen brauchen Ihn!<br/>Du entrinnst der Nichtigkeit,<br/>Und gewinnst die Wirklichkeit,<br/>Er gibt deinem Leben Sinn,<br/>Ja, du brauchst Jesus!<br/>',NULL,48360,6);
INSERT INTO stanza VALUES('G434','5','Voller Leiden und Plag ist diese Welt,<br/>In schweren Zeiten nichts dein Herz erhellt;<br/>Leer ist alles, worauf verlässt du dich?<br/>In allen Dingen zeigt es sich:<br/>Ja, du brauchst Jesus!<br/>',NULL,48361,7);
INSERT INTO stanza VALUES('G435','1','Gib die Welt auf, Christus gewinn,<br/>Was dein Herz braucht, ist nur Er;<br/>Was kannst du sonst noch wünschen dir?<br/>Alles ist nichtig und leer!<br/>',NULL,48362,1);
INSERT INTO stanza VALUES('G435','chorus','Er ist so reich, Er überfließt,<br/>Was du auch brauchst, gibt der Herr!<br/>Er ist so gut, Er ist so süß,<br/>Was du auch denkst, Er ist mehr!<br/>',NULL,48363,2);
INSERT INTO stanza VALUES('G435','2','Gib die Welt auf, Christus gewinn,<br/>Was du auch brauchst, alles ist Er;<br/>Wenn du den süßen Christus empfängst,<br/>Auf alle andren baust du nicht mehr.<br/>',NULL,48364,3);
INSERT INTO stanza VALUES('G435','3','Ist all die Welt so sehr groß<br/>Und ist dein Herz so sehr klein,<br/>Kann dennoch alles Reichtum der Welt<br/>Niemals dein Herz erfüllen allein.<br/>',NULL,48365,4);
INSERT INTO stanza VALUES('G435','4','Christus ist jede Freude für dich,<br/>Ohne Ihn hast du Schmerz nur und Leid;<br/>Wo Christus ist, scheint Tageslicht,<br/>Ist Er nicht da, bleibt Dunkelheit.<br/>',NULL,48366,5);
INSERT INTO stanza VALUES('G436','1','Horch, der Retter klopft nun, klopft nun,<br/>An dein Herz klopft Er!<br/>Oh, sei nicht verhärtet, -härtet,<br/>Falls Er wieder geht.<br/>Steh auf, öffne Ihm dein Herz,<br/>Ihm, der dich so liebt;<br/>Gottes Leben gibt Er, gibt Er,<br/>Sünde dir vergibt.<br/>',NULL,48367,1);
INSERT INTO stanza VALUES('G436','chorus','Lass Ihn ein! Lass Ihn ein!<br/>Er klopft nun an dein Herz;<br/>Lass Ihn ein! Oh, lass Ihn ein!<br/>Lass Ihn in dein Herz.<br/>',NULL,48368,2);
INSERT INTO stanza VALUES('G436','2','Warum willst du zögern, zögern,<br/>Lässt Ihn lange stehn?<br/>Er erbarmt Sich gnädig, gnädig,<br/>Lieb ist Er zu sehn.<br/>Seine sanfte Stimme hör,<br/>Mach Sein Herz nicht schwer;<br/>Heiße Ihn willkommen, -kommen,<br/>Schätze Gnade sehr!<br/>',NULL,48369,3);
INSERT INTO stanza VALUES('G437','1','Kurz die Lebenstage sind,<br/>Wie ein Blatt verweht vom Wind,<br/>Wie die Blume welkt geschwind,<br/>Sei bereit!<br/>Jeden Tag bist du verstrickt,<br/>Bis die letzte Stunde tickt,<br/>Und das Lebens-Schilfrohr knickt,<br/>Sei bereit!<br/>',NULL,48370,1);
INSERT INTO stanza VALUES('G437','chorus','Sei bereit! Sei bereit!<br/>Ruft die Stimme Jesu dich, dann<br/>Sei bereit!<br/>Bleibe nicht in Sündennacht,<br/>Bis die Tür ist zugemacht<br/>Und dein Schrei bleibt außer Acht,<br/>Sei bereit!<br/>',NULL,48371,2);
INSERT INTO stanza VALUES('G437','2','Jugend-Schönheit ist bald um,<br/>Schnell vorbei ist jeder Ruhm,<br/>Denn du bleibst nicht lang, darum<br/>Sei bereit!<br/>Gottes Geist lädt dich nun ein,<br/>Sünder, lass das Wandern sein,<br/>Vorm Gericht steh nicht allein,<br/>Sei bereit!<br/>',NULL,48372,3);
INSERT INTO stanza VALUES('G437','3','Diese Zeit verfliegt im Nu,<br/>Tod, Gericht kommt auf dich zu,<br/>Such in Jesu Armen Ruh!<br/>Sei bereit!<br/>Oh, ich bet, dass du Ihn siehst,<br/>Eh vorbei die Gnadenfrist,<br/>Und du ganz verloren bist,<br/>Sei bereit!<br/>',NULL,48373,4);
INSERT INTO stanza VALUES('G437','4','Sünder, hör, Gott mahnt nochmal,<br/>Mach den Herrn zu deiner Wahl,<br/>Engel jauchzen ohne Zahl,<br/>Sei bereit!<br/>Komm aus Finsternis ins Licht,<br/>Komm, gerecht dich Jesus spricht,<br/>Nimm Ihn auf und warte nicht,<br/>Sei bereit!<br/>',NULL,48374,5);
INSERT INTO stanza VALUES('G438','1','So wie ich bin, nichts bringen kann,<br/>Lädst Du mich ein, mich Dir zu nahn;<br/>Dein Blut verschafft mir freie Bahn,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48375,1);
INSERT INTO stanza VALUES('G438','2','So wie ich bin, noch warten? Nein!<br/>In meiner Seel kehrt Friede ein;<br/>Dein Blut wäscht mich von Flecken rein,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48376,2);
INSERT INTO stanza VALUES('G438','3','So wie ich bin, Konflikt-geplagt,<br/>Probleme kreisen, Zweifel nagt;<br/>Durch Furcht und Kämpfe oft verzagt,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48377,3);
INSERT INTO stanza VALUES('G438','4','So wie ich bin, so elend, blind,<br/>Doch Sicht und Heilung nun beginnt;<br/>Was ich auch brauch, in Dir nun find,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48378,4);
INSERT INTO stanza VALUES('G438','5','So wie ich bin, empfängst Du mich,<br/>Vergibst, machst rein und frei für Dich;<br/>Was Du verheißt, das glaube ich,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48379,5);
INSERT INTO stanza VALUES('G438','6','So wie ich bin, Du kennst mein Sein,<br/>In Liebe rissest Mauern ein;<br/>Und nun gehör ich Dir allein,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,48380,6);
INSERT INTO stanza VALUES('G439','1','Aus meinen Ketten, Sorgen und Nacht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deine Freiheit, Freude und Licht,<br/>Jesus, ich komm zu Dir!<br/>In Deine Heilung, Krankheit muss gehn,<br/>In Deinen Reichtum, Wünsche lass stehn,<br/>Komme in Dich, die Sünden vergehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,48381,1);
INSERT INTO stanza VALUES('G439','2','Aus dem Versagen und tiefer Nacht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In das, was Du am Kreuz hast vollbracht,<br/>Jesus, ich komm zu Dir!<br/>In Deinen Balsam, Sorgen lass gehn,<br/>In Deine Ruh, lass Alltags-Sturm stehn,<br/>In den Gesang, die Klagen vergehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,48382,2);
INSERT INTO stanza VALUES('G439','3','Aus meiner Unruh, eigenen Ehr,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deinem Willen zu bleiben, o Herr,<br/>Jesus, ich komm zu Dir!<br/>In Deine Liebe, Eitles lass gehn,<br/>In die Entrückung, Schwermut lass stehn,<br/>Auf Deinen Flügeln, Herrlichkeit sehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,48383,3);
INSERT INTO stanza VALUES('G439','4','Aus aller Angst, wenn''s Grab mich bedroht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deine Friedensfreude, o Gott,<br/>Jesus, ich komm zu Dir!<br/>Aus dem Verderb, auf Dich kann ich baun,<br/>In Deine Herde hier auf den Au''n.<br/>Lass mich Dein liebes Angesicht schaun.<br/>Jesus, ich komm zu Dir!<br/>',NULL,48384,4);
INSERT INTO stanza VALUES('G440','1','Wie sanft klingt Deine Stimm!<br/>Die zu Dir ruft ganz nah,<br/>Zum Reinigen in Deinem Blut,<br/>Das floss auf Golgatha.<br/>',NULL,48385,1);
INSERT INTO stanza VALUES('G440','chorus','Herr, ich komme nun,<br/>Komm zu Dir ganz nah;<br/>Wasch mich rein in Deinem Blut,<br/>Das floss auf Golgatha.<br/>',NULL,48386,2);
INSERT INTO stanza VALUES('G440','2','Ich komme arm und schwach<br/>Und voller jeden Dreck;<br/>Du sprichst mir Kraft und Trost stets zu<br/>Und reinigst jeden Fleck.<br/>',NULL,48387,3);
INSERT INTO stanza VALUES('G440','3','Ja, Jesus, stärkt das Werk,<br/>Es fest und selig macht;<br/>Fügt Gnad um Gnade reich hinzu,<br/>Wo herrschte Sündenmacht.<br/>',NULL,48388,4);
INSERT INTO stanza VALUES('G440','4','Und Seine Liebe bürgt<br/>Bei jedem treuen Mann:<br/>Verheißungen erfüllt Er stets,<br/>Wenn Glaube fleht Ihn an.<br/>',NULL,48389,5);
INSERT INTO stanza VALUES('G440','5','Lob Seinem teuren Blut!<br/>Lob Seiner vollen Gnad!<br/>Lob unsrem Herrn, der Gaben gibt,<br/>Kraft und Gerechtigkeit.<br/>',NULL,48390,6);
INSERT INTO stanza VALUES('G441','1','Einst wanderte ich fern von Gott,<br/>Nun, Herr, komm ich heim;<br/>Zu lang den Sündenweg ich trat,<br/>Herr, ich komme heim.<br/>',NULL,48391,1);
INSERT INTO stanza VALUES('G441','chorus','Komme heim, komme heim,<br/>Schon nicht mehr fern sein;<br/>Deine Liebe reicht so weit;<br/>Herr, ich komme heim.<br/>',NULL,48392,2);
INSERT INTO stanza VALUES('G441','2','Vergeudet hab ich manches Jahr,<br/>Nun, Herr, komm ich heim;<br/>Mit Tränen tu ich Buße gar,<br/>Herr, ich komme heim.<br/>',NULL,48393,3);
INSERT INTO stanza VALUES('G441','3','Ich hab die Sünde satt nunmehr,<br/>Nun, Herr, komm ich heim;<br/>Ich lieb Dein Wort, vertrau ihm sehr,<br/>Herr, ich komme heim.<br/>',NULL,48394,4);
INSERT INTO stanza VALUES('G441','4','Die Seele krank, mein Herz verletzt,<br/>Nun, Herr komm ich heim;<br/>Schenk neue Kraft und Hoffnung jetzt,<br/>Herr, ich komme heim.<br/>',NULL,48395,5);
INSERT INTO stanza VALUES('G441','5','Nur eins versöhnt mich nun mit Gott,<br/>Nun, Herr, komm ich heim,<br/>Dass Jesus litt für mich den Tod,<br/>Herr, ich komme heim.<br/>',NULL,48396,6);
INSERT INTO stanza VALUES('G441','6','Sein Blut, das reinigt, brauche ich,<br/>Nun, Herr, komm ich heim;<br/>Noch weißer als der Schnee wasch mich,<br/>Herr, ich komme heim.<br/>',NULL,48397,7);
INSERT INTO stanza VALUES('G442','1','Sündig und verzagt, ich beug mich,<br/>Herr, vor Deinen Füßen jetzt;<br/>Voller Sorgen, ohne Hoffnung,<br/>Liebster Retter, rett mich jetzt!<br/>Rett mich jetzt, rett mich jetzt!<br/>Liebster Retter, rett mich jetzt!<br/>Rette mich aus all Problemen,<br/>Liebster Retter, rett mich jetzt!<br/>',NULL,48398,1);
INSERT INTO stanza VALUES('G443','1','Fels des Heils, geöffnet mir,<br/>Birg mich, ew''ger Hort, in Dir.<br/>Lass das Wasser und das Blut,<br/>Deiner Seite heil''ge Flut,<br/>Mir das Heil sein zweierfach<br/>Von der Sünde Schuld und Macht.<br/>',NULL,48399,1);
INSERT INTO stanza VALUES('G443','2','Dem, was Dein Gesetze spricht,<br/>Kann mein Werk genügen nicht.<br/>Mag ich ringen wie ich will,<br/>Fließen auch die Tränen viel,<br/>Tilgt das doch nicht meine Schuld.<br/>Herr, mir hilft nur Deine Huld.<br/>',NULL,48400,2);
INSERT INTO stanza VALUES('G443','3','Da ich denn nichts bringen kann,<br/>Schmieg ich an Dein Kreuz mich an.<br/>Nackt und bloß, o kleid mich doch,<br/>Hilflos, ach, erbarm Dich noch,<br/>Unrein, Herr, flieh ich zu Dir,<br/>Wasche mich, sonst sterb ich hier.<br/>',NULL,48401,3);
INSERT INTO stanza VALUES('G443','4','Jetzt, da ich noch leb im Licht,<br/>Wenn mein Aug im Tode bricht,<br/>Wenn durchs finstre Tal ich geh,<br/>Dann vor meinem Herren steh:<br/>Fels des Heils, geöffnet mir,<br/>Birg mich, ew''ger Hort, in Dir.<br/>',NULL,48402,4);
INSERT INTO stanza VALUES('G444','1','Jesus, halt mich nah am Kreuz,<br/>Dort fließt eine Quelle,<br/>Ja, der Strom von Golgatha<br/>Heilung bringt der Seele.<br/>',NULL,48403,1);
INSERT INTO stanza VALUES('G444','chorus','Ja, das Kreuz, ja, das Kreuz<br/>Ist mein Ruhm zu kennen;<br/>Nein, nichts soll von Christi Kreuz<br/>Meine Seele trennen.<br/>',NULL,48404,2);
INSERT INTO stanza VALUES('G444','2','Nah am Kreuz spürt meine Seel<br/>Liebe und Erbarmen,<br/>Strahlen dort vom Morgenstern<br/>Tröstend mich umarmen.<br/>',NULL,48405,3);
INSERT INTO stanza VALUES('G444','3','Nah am Kreuz! O Gotteslamm,<br/>Lass mich es klar sehen,<br/>Mir im Kreuzesschatten hilf<br/>Deinen Weg zu gehen.<br/>',NULL,48406,4);
INSERT INTO stanza VALUES('G444','4','Nah am Kreuz! Ich wach und wart,<br/>Hoffe und vertraue,<br/>Bis ich in das Angesicht<br/>Meines Retters schaue.<br/>',NULL,48407,5);
INSERT INTO stanza VALUES('G445','1','Dort, wo am Kreuz einst mein Retter starb,<br/>Dort, wo ich flehte, Er mir vergab,<br/>Dort wusch Sein Blut meine Sünden ab;<br/>Ehre sei dem Herrn!<br/>',NULL,48408,1);
INSERT INTO stanza VALUES('G445','chorus','Ehre sei dem Herrn,<br/>Ehre sei dem Herrn;<br/>Dort wusch Sein Blut meine Sünden ab;<br/>Ehre sei dem Herrn!<br/>',NULL,48409,2);
INSERT INTO stanza VALUES('G445','2','Herrlich von Sünden hat Er befreit,<br/>Jesus so süß wohnt in mir allzeit,<br/>Mich aufzunehmen war Er bereit;<br/>Ehre sei dem Herrn.<br/>',NULL,48410,3);
INSERT INTO stanza VALUES('G445','3','Ja, durch den kostbaren Quell allein<br/>Rettet mich Jesus und wäscht mich rein,<br/>Ich bin so froh, dass ich sprang hinein;<br/>Ehre sei dem Herrn.<br/>',NULL,48411,4);
INSERT INTO stanza VALUES('G445','4','Komm zu der Quelle, so reich und süß:<br/>Wirf deine Seele vor Seine Füß'',<br/>Sein Wiederherstellen dort begrüß;<br/>Ehre sei dem Herrn.<br/>',NULL,48412,5);
INSERT INTO stanza VALUES('G446','1','Er suchte mich voll Liebe,<br/>Als ich in Sünd verirrt,<br/>Mich trug auf Seinen Schultern<br/>Zur Herde hin der Hirt.<br/>Die Engelschar bei Ihm, die singt,<br/>So dass es wohl im Himmel klingt.<br/>',NULL,48413,1);
INSERT INTO stanza VALUES('G446','chorus','Liebe, die mich suchte!<br/>Blut, das mich erkaufte!<br/>Gnade brachte mich zur Herde hin,<br/>Gnade brachte mich zur Herde hin!<br/>',NULL,48414,2);
INSERT INTO stanza VALUES('G446','2','Er wusch die Sünden-Wunden,<br/>Goss Öl darauf und Wein;<br/>Versprach mir sanft und flüsternd:<br/>„Ich fand dich, du bist Mein.“<br/>Wie süß doch Seine Stimme klingt!<br/>Mein wehes Herz zum Singen bringt.<br/>',NULL,48415,3);
INSERT INTO stanza VALUES('G446','3','Er zeigte Nägelmale,<br/>Vergoss für mich Sein Blut,<br/>Die Spötterkrone, dornig,<br/>Trug Er für mich gut;<br/>Welch Todesqual, so fürchterlich,<br/>Erlitt Er dort am Kreuz für mich!<br/>',NULL,48416,4);
INSERT INTO stanza VALUES('G446','4','Ich sitz vor Ihm und schaue<br/>Sein helles Angesicht,<br/>Und staune, wie viel Segen<br/>Erstrahlt in Seinem Licht.<br/>Zum Lobpreis Seiner Herrlichkeit<br/>Scheint viel zu kurz die Ewigkeit.<br/>',NULL,48417,5);
INSERT INTO stanza VALUES('G446','5','Wenn Stunden nun vergehen,<br/>Sein Frieden zu mir kam;<br/>Ich wart auf jenen Morgen,<br/>Auf meinen Bräutigam,<br/>An Seine Seite, so vertraut,<br/>Ruft Er uns, Seine reine Braut.<br/>',NULL,48418,6);
INSERT INTO stanza VALUES('G447','1','Hör doch, ein Geheimnis kenn ich,<br/>Lang verborgen, nimm''s für dich!<br/>Christus wird im Leben wirklich<br/>Eins sein mit dir, mein Freund!<br/>Lob Ihn, lob Ihn, Halleluja!<br/>Lob Ihn, lob Ihn, Halleluja!<br/>Christus wird im Leben wirklich<br/>Eins sein mit dir, mein Freund!<br/>',NULL,48419,1);
INSERT INTO stanza VALUES('G448','1','Oh, welch Geheimnis, dass der Retter<br/>Eins mit mir ist!<br/>Oh, wie vollkommen ist die Rettung,<br/>Die mir im Sohn zufließt!<br/>Halleluja! Halleluja!<br/>Herrlich ist Sein Plan!<br/>Nichts auf der Erde, noch im Himmel<br/>Ihn von mir scheiden kann!<br/>',NULL,48420,1);
INSERT INTO stanza VALUES('G449','1','Ich bin ein Mensch –<br/>Bin der Sinn des ganzen Weltenraums;<br/>Ich bin ein Mensch –<br/>Bin der Sinn des ganzen Weltenraums.<br/>Gott schuf mich so,<br/>Ich bin so froh;<br/>Ja, der Mittelpunkt und Sinn des ganzen Weltenraums.<br/>',NULL,48421,1);
INSERT INTO stanza VALUES('G449','2','Christus in mir –<br/>Meines Lebens Sinn allein ist Er;<br/>Christus in mir –<br/>Meines Lebens Sinn allein ist Er.<br/>Er ist in mir,<br/>Mein alles hier;<br/>Wirklichkeit und meines Lebens Sinn allein ist Er.<br/>',NULL,48422,2);
INSERT INTO stanza VALUES('G449','3','Sein Ausdruck ist –<br/>Die Gemeinde auf der Erde heut;<br/>Sein Ausdruck ist –<br/>Die Gemeinde auf der Erde heut;<br/>Jetzt Seinen Plan<br/>Erfüllen kann<br/>Dieser neue Mensch; ja, er wird herrschen über die Erd.<br/>',NULL,48423,3);
INSERT INTO stanza VALUES('G449','4','Ja, die Gemeind –<br/>Das Familienleben, neu und echt;<br/>Ja, die Gemeind –<br/>Das Familienleben, neu und echt;<br/>Dies ist der Weg,<br/>Welch Privileg! –<br/>Christus essen baut die örtliche Gemeinde auf.<br/>',NULL,48424,4);
INSERT INTO stanza VALUES('G449','5','Was solln wir tun?<br/>Wir gehn hin und sagen''s überall.<br/>Was solln wir tun?<br/>Wir gehn hin und sagen''s überall.<br/>Von Ihm doch sprich –<br/>Drum rief Er dich.<br/>Voller Freude gehn wir hin und sagen''s überall.<br/>',NULL,48425,5);
INSERT INTO stanza VALUES('G450','1','Hätt'' ich alle Macht, doch keinen Retter,<br/>Nur ein''n Tag zu leben, wär'' Verdruss;<br/>Kann mein Herz denn Trost und Ruhe finden,<br/>Wenn doch alles hier vergehen muss?<br/>Hätt'' ich alle Macht, doch keinen Retter,<br/>Wozu soll ich lebenslang abmühn mich?<br/>Sind die irdischen Vergnügen mehr wert,<br/>Als wenn Christus mich erfüllt mit Sich?<br/>',NULL,48426,1);
INSERT INTO stanza VALUES('G450','2','Hätt'' ich Wohlstand, jeder würd'' mich lieben,<br/>Wär'' mein Name allen ein Begriff,<br/>Doch wenn ohne Hoffnung, ohne Hafen,<br/>Wohin lenk ich denn im Sturm mein Schiff?<br/>Hätt'' ich alle Macht, doch keinen Retter,<br/>Der das Kreuz ertrug und starb für mich,<br/>Könnte mir die Welt hier Zuflucht bieten?<br/>Wenn in Angst und Leid, wohin flieh ich?<br/>',NULL,48427,2);
INSERT INTO stanza VALUES('G450','3','Oh, wie leer ist alles ohn'' den Retter!<br/>Wie die Sündensorge nimmt dich ein!<br/>Und die Ewigkeit so trüb und dunkel,<br/>Voller Weh und Tränen wird sie sein.<br/>Was ist, wenn ich lebe ohne Retter,<br/>Wenn ich sterben muss, was steht bereit?<br/>Ohne Ihn ich dort im finstren Tal steh,<br/>Ohne Ihn, allein in Ewigkeit!<br/>',NULL,48428,3);
INSERT INTO stanza VALUES('G450','4','Welche Freud, in Jesus hab ich alles!<br/>Er ist Balsam für mein krankes Herz!<br/>Er vergibt die allergrößten Sünden,<br/>Zeigt Sein Mitgefühl in jedem Schmerz!<br/>Wenn ich Jesus habe, einzig Jesus,<br/>In der ganzen Welt nichts sonst will ich –<br/>Alles habe ich in Christus Jesus;<br/>Was ich brauch, weiß Er, und sorgt für mich.<br/>',NULL,48429,4);
INSERT INTO stanza VALUES('G451','1','Was bringt der Tagesablauf ein?<br/>Es wird nie etwas Neues sein!<br/>Was war, vergisst man allgemein,<br/>Es ist Nichtigkeit!<br/>',NULL,48430,1);
INSERT INTO stanza VALUES('G451','chorus','Nichtigkeit! Nichtigkeit!<br/>Nichtigkeit! Nichtigkeit!<br/>Ein Haschen nach Wind,<br/>Und nur Nichtigkeit!<br/>',NULL,48431,2);
INSERT INTO stanza VALUES('G451','2','Das Leben ist voll Gram und Pein:<br/>Viel Weisheit viel Verdruss bringt ein!<br/>Viel Wissen steigert Leid allein!<br/>Es ist Nichtigkeit!<br/>',NULL,48432,3);
INSERT INTO stanza VALUES('G451','3','Was nützt Vergnügen, Reichtum heut?<br/>Familie haben und viel Freud?<br/>Denn Sorgen melden sich erneut!<br/>Es ist Nichtigkeit!<br/>',NULL,48433,4);
INSERT INTO stanza VALUES('G451','4','Tags schuften, nachts so ruhelos:<br/>So vieles fällt dir in den Schoß,<br/>Der Tod gibt allem einen Stoß!<br/>Es ist Nichtigkeit!<br/>',NULL,48434,5);
INSERT INTO stanza VALUES('G451','5','An Gott denk in der Jugendzeit!<br/>Fürcht Ihn, das ist Gewinn allzeit,<br/>Nur Er schenkt dir Zufriedenheit,<br/>Nur Er ist Wirklichkeit!<br/>',NULL,48435,6);
INSERT INTO stanza VALUES('G451','chorus','Ohne Ihn, Nichtigkeit!<br/>Doch mit Ihm, Wirklichkeit!<br/>Alles – Nichtigkeit,<br/>Nur Er – Wirklichkeit!<br/>',NULL,48436,7);
INSERT INTO stanza VALUES('G452','1','Einst nach einem Brunnen suchte,<br/>Der zutiefst zufriedenstellt,<br/>Von so vielen Brunnen trank ich,<br/>Doch der Durst blieb, denn Leben fehlt.<br/>Doch dann fand ich Jesus,<br/>Der meinen Durst nun stillt,<br/>Er ist ein tiefer Quell in mir,<br/>Wo Lebenswasser quillt.<br/>Nun ich trink Ihn!<br/>Jesus, Jesus, ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,48437,1);
INSERT INTO stanza VALUES('G452','2','Da der Brunnen mir gemundet,<br/>Sucht'' mein Herz nach dem Ort seitdem;<br/>Die Vision am Berg erhaschte:<br/>Man sich trifft in Jerusalem.<br/>Ja, dann fand mich Jesus,<br/>Mich zur Gemeinde trug;<br/>Hier ewig Freude überfließt,<br/>Gesucht hab ich genug.<br/>Halleluja!<br/>Jesus, Jesus, ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,48438,2);
INSERT INTO stanza VALUES('G452','3','Leerer Wandrer, lass dein Trachten –<br/>Letztlich wird alles wertlos sein;<br/>Öffne nun dein Herz im Glauben,<br/>Ruf: „Herr Jesus!“ Er kommt herein!<br/>Du wirst Ihn heut finden,<br/>Ruf Seinen Namen an,<br/>So hängst du Ihm nun an im Geist –<br/>Wirst anders sein fortan.<br/>Ja, das willst du!<br/>Jesus, Jesus, ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,48439,3);
INSERT INTO stanza VALUES('G453','1','Das Hochzeitsfest, der Höchstgenuss des Menschen,<br/>War voll Vergnügen, bis versiegt der Wein;<br/>Wenn unsre Lebenskraft wie Wein erschöpft ist,<br/>Kommt Jesus, schenkt uns Gottes Leben ein.<br/>',NULL,48440,1);
INSERT INTO stanza VALUES('G453','chorus','Wenn Jesus kommt, wird Neuwein aus dem Wasser,<br/>Wenn Jesus kommt, wird Finsternis zum Licht;<br/>Der Tod in ew''ges Leben wird verwandelt,<br/>Schwachheit in Kraft und Blindheit wird zu Sicht.<br/>',NULL,48441,2);
INSERT INTO stanza VALUES('G453','2','Es kam bei Nacht zu Jesus ein Gerechter,<br/>Mehr Lehre prägte er nun gerne ein;<br/>Doch Lehren ändern nicht gefallne Menschen,<br/>Der Herr sprach: „Du musst neu geboren sein“.<br/>',NULL,48442,3);
INSERT INTO stanza VALUES('G453','3','Die Sünderin gab aus, kein''n Mann zu haben,<br/>Nach vielen Männern hatte sie noch Durst;<br/>Sie schöpfte täglich Wasser, unzufrieden,<br/>Bis Jesus kam, den Durst hat ihr gelöscht.<br/>',NULL,48443,4);
INSERT INTO stanza VALUES('G453','4','Ein Mann lag hilflos unter vielen andren,<br/>Ja, bis der Teich sich rührte, lag er dort;<br/>Gesetz, Religion konnten nicht heilen,<br/>Doch Jesus kam, sprach Leben durch Sein Wort.<br/>',NULL,48444,5);
INSERT INTO stanza VALUES('G453','5','Im Todesgriff vier Tage lang schon war er,<br/>In Trauer weinten sie rundum das Grab;<br/>Still lag er da, in Grabtüchern umbunden,<br/>Doch Jesus kam, ihn weckte, Leben gab.<br/>',NULL,48445,6);
INSERT INTO stanza VALUES('G453','6','Auch heute noch ist Jesus so lebendig,<br/>Von Tod errettet Er in jeder Form;<br/>Öffne dein Herz und rufe an: „Herr Jesus“,<br/>Er kommt zu dir, im Geist wirst du geborn.<br/>',NULL,48446,7);
INSERT INTO stanza VALUES('G454','1','„Alles ist fertig“, komm nun zum Fest!<br/>Komm, denn der Tisch steht schon bereit;<br/>Wer hungrig und ermattet ist,<br/>Komm! Hier wirst du reich gespeist.<br/>',NULL,48447,1);
INSERT INTO stanza VALUES('G454','chorus','Alle sind willkommen,<br/>Komm, wer auch immer will;<br/>Gott rettet so vollkommen,<br/>Komm, wer auch immer will.<br/>',NULL,48448,2);
INSERT INTO stanza VALUES('G454','2','„Alles ist fertig“, komm nun zum Fest!<br/>Komm, offen steht die Türe weit;<br/>Ein Ehrenplatz beim Meister ist<br/>Für dich auch nunmehr bereit.<br/>',NULL,48449,3);
INSERT INTO stanza VALUES('G454','3','„Alles ist fertig“, komm nun zum Fest!<br/>Komm, da Er noch willkommen heißt;<br/>Verspät dich nicht, dies ist dein Tag,<br/>Ob Morgen noch kommt, wer weiß''s?<br/>',NULL,48450,4);
INSERT INTO stanza VALUES('G454','4','„Alles ist fertig“, komm nun zum Fest!<br/>Lass alle Sorgen und Gezank;<br/>Komm, Gottes Christus feste froh,<br/>Genieße den Lebenstrank.<br/>',NULL,48451,5);
INSERT INTO stanza VALUES('G455','1','Schmeck doch und sieh: ja, der Herr ist gut,<br/>Schmeck doch und sieh: ja, der Herr ist gut;<br/>Er ist gut für dich, sowie auch für mich,<br/>Was auch immer du tust, schmeck doch und sieh.<br/>',NULL,48452,1);
INSERT INTO stanza VALUES('G455','2','Ruf doch: „O Herr!“ – Er verändert dich,<br/>Ruf doch: „O Herr!“ – Er verändert dich;<br/>Herrliche Gnade fließt so sehr,<br/>Wenn an jedem Ort du rufst: „O Herr!“<br/>',NULL,48453,2);
INSERT INTO stanza VALUES('G455','3','Ja, Liebe fließt in dein Herz hinein,<br/>Ja, Liebe fließt in dein Herz hinein;<br/>Ein Strom aus Gott fließt dir jetzt zu,<br/>Die wahre Liebe ja fandest du.<br/>',NULL,48454,3);
INSERT INTO stanza VALUES('G455','4','Drum preis den Herrn für Sein Leben in dir,<br/>Ja, preis den Herrn für Sein Leben in dir;<br/>Etwas von Christus goss Er gern<br/>Jetzt in dein Leben, drum preis den Herrn!<br/>',NULL,48455,4);
INSERT INTO stanza VALUES('G456','1','Welch ein Jubeltag<br/>Seit dem ich nicht zurück mehr mag!<br/>Seit Jesus mich heraus aus der dunklen Nacht<br/>Ins Reich des Lichtes hat gebracht.<br/>',NULL,48456,1);
INSERT INTO stanza VALUES('G456','2','Neu mein Leben jetzt,<br/>Denn Er hat mich in Seins versetzt;<br/>Mich locken keine irdischen Träume mehr,<br/>Mein wahres Leben ist der Herr.<br/>',NULL,48457,2);
INSERT INTO stanza VALUES('G456','3','Wenn ich offen bin,<br/>Erfüllt Er mich mit Leben drin;<br/>Sein Leben wird zu meinem in Wirklichkeit,<br/>Er wohnt in mir für allezeit!<br/>',NULL,48458,3);
INSERT INTO stanza VALUES('G456','4','Herr, ich lieb Dich sehr,<br/>Nimm Du mein Herz ein immer mehr;<br/>Du bist mein Leben jetzt und ewiglich,<br/>Du bist der Einzige für mich.<br/>',NULL,48459,4);
INSERT INTO stanza VALUES('G457','1','Wie soll ich bloß dem Herrn vergelten<br/>All Sein-, all Sein-, all Seine Wohltat an mir?<br/>Ich nehm den Kelch der Errettung,<br/>Und ruf, und ruf, und rufe an den Namen des Herrn.<br/>',NULL,48460,1);
INSERT INTO stanza VALUES('G458','1','Dies ist meine Ruh auf ewig,<br/>Hier will ich wohn''n,<br/>Denn der Herr hat Zion erkoren,<br/>Und es begehrt hat Er zu Seiner Wohnung.<br/>Seine Speise will Er reichlich segnen,<br/>Seine Armen will füllen mit Brot;<br/>Seine Priester bekleiden mit Rettung,<br/>Und Seine Heil''gen werden jubeln laut.<br/>',NULL,48461,1);
INSERT INTO stanza VALUES('G459','1','Ihr werdet mit Freuden Wasser schöpfen<br/>Aus den Quellen der Errettung;<br/>An jenem Tag werdet ihr sagen,<br/>Preist den Herrn.<br/>(Die obigen vier Zeilen wiederholen.)<br/>Ruft Sein''n Namen an, tut Seine Taten kund<br/>bei den Völkern,<br/>Verkündet Seinen Namen erhaben;<br/>O juble laut, du Bewohnerin von Zion,<br/>Denn groß ist in Deiner Mitte der Heilige von Israel.<br/>',NULL,48462,1);
INSERT INTO stanza VALUES('G460','1','Dann werden die Erlösten des Herrn wiederkehrn,<br/>Und mit Jauchzen nach Zion kommen,<br/>Und auf ihrem Haupt wird ewige Freude sein;<br/>Dann werden die Erlösten des Herrn wiederkehrn,<br/>Und mit Jauchzen nach Zion kommen,<br/>Und auf ihrem Haupt wird ewige Freude sein.<br/>Wonne und Freude werden einkehrn,<br/>Und Kummer und Seufzer vollauf entfliehn.<br/>',NULL,48463,1);
INSERT INTO stanza VALUES('G460','2','Dann werden die Erlösten des Herrn wiederkehrn,<br/>Und mit Jauchzen nach Zion kommen,<br/>Und auf ihrem Haupt wird ewige Freude sein.<br/>',NULL,48464,2);
INSERT INTO stanza VALUES('J1','1','栄こうちちにあれ, 御子にあれ，<br/>そのれいにもあれ, 永えんに。<br/>',NULL,48465,1);
INSERT INTO stanza VALUES('J1','2','創ぞうのわざ見て かんどうし、<br/>しずかにれいはい ささげる。<br/>',NULL,48466,2);
INSERT INTO stanza VALUES('J1','3','多くの子得んとの ながねがい:<br/>御子にありていま ほめたとう。<br/>',NULL,48467,3);
INSERT INTO stanza VALUES('J1','4','けい示にてなれの みおもいを,<br/>あいにあり,ひとに あらわす。<br/>',NULL,48468,4);
INSERT INTO stanza VALUES('J1','5','主のあがないにて てきほろび,<br/>新創造にて,なれを 礼はいす。<br/>',NULL,48469,5);
INSERT INTO stanza VALUES('J1','6','栄こうちちにあれ, 御子にあれ,<br/>そのれいにもあれ, 永えんに。<br/>',NULL,48470,6);
INSERT INTO stanza VALUES('J2','1','グローリー,グローリー,グローリー,<br/>さん美と礼拝！<br/>うたのこえは, とわにふくらむ！<br/>ちち,子,れいの, かみ啓示され,<br/>ひとは伏して れい拝す！<br/>ちち,子,れいの, かみ啓示され,<br/>ひとは伏して れい拝す!<br/>',NULL,48471,1);
INSERT INTO stanza VALUES('J2','2','ちち,みなもと, えい光,無げん;<br/>子はたい能で ばん有ささえる;<br/>れいは栄光で, すべて満たす;<br/>うたえ!栄光の ほう満を。<br/>',NULL,48472,2);
INSERT INTO stanza VALUES('J2','3','偉だいなかみ, 万ゆうの元首,<br/>せいけつ着て, われらひれ伏す!<br/>威げん,こう貴, えい光,ちから,<br/>なれは永遠の みなもと!<br/>',NULL,48473,3);
INSERT INTO stanza VALUES('J3','1','栄光,御ちちにあれ, 栄光,御子にあれ,<br/>栄光,その霊にあれ, とわに栄光あれ。<br/>',NULL,48474,1);
INSERT INTO stanza VALUES('J3','chorus','賛美せよ,賛美せよ, さんいちのかみ!<br/>くすしわざなしし みかみにえい光あれ!<br/>',NULL,48475,2);
INSERT INTO stanza VALUES('J3','2','けいかくの御ちち, かんせいの御子,<br/>うんこうのその霊, はたらきほめよ。<br/>',NULL,48476,3);
INSERT INTO stanza VALUES('J3','3','栄光,御ちちにあれ, 栄光,御子にあれ,<br/>栄光,その霊にあれ, とわに栄光あれ。<br/>',NULL,48477,4);
INSERT INTO stanza VALUES('J3','note','［２　うんこう(運行)―その霊の働きと伝達］<br/>',NULL,48478,5);
INSERT INTO stanza VALUES('J4','1','せい,せい,せい, ぜん能のかみ!<br/>永えんの世まで われらうたう;<br/>せい,せい,せい, 慈あい,全のう!<br/>　三の実しつ, いちのかみ!<br/>',NULL,48479,1);
INSERT INTO stanza VALUES('J4','2','せい,せい,せい, 伏してはいす;<br/>長ろうはなれに, かんむり投げる;<br/>むかし,いまし, いまもいます<br/>　永遠のかみ れい拝する。<br/>',NULL,48480,2);
INSERT INTO stanza VALUES('J4','3','せい,せい,せい, くらやみ覆い,<br/>つみびとらには 栄光,見えずも,<br/>なれこそせい! そのじゅんけつ,<br/>　ちから,あい, みなかん全。<br/>',NULL,48481,3);
INSERT INTO stanza VALUES('J4','4','せい,せい,せい, ぜん能のかみ!<br/>全被ぞうぶつの 賛美は絶えず;<br/>せい,せい,せい, 慈あい,全のう!<br/>　三の実しつ, いちのかみ!<br/>',NULL,48482,4);
INSERT INTO stanza VALUES('J5','1','ちち,子,れい賛美す! みなもとのちちを,<br/>あがないの御子を, うんこうのれいを。<br/>',NULL,48483,1);
INSERT INTO stanza VALUES('J5','2','御ちちはみなもと, 御子はながれ出て,<br/>れいはながれ込む, 三いちはわがぶん。<br/>',NULL,48484,2);
INSERT INTO stanza VALUES('J6','1','かみはあい,ひかり, 子にありいのち;<br/>愛とひかりにより, いのちを分与す。<br/>',NULL,48485,1);
INSERT INTO stanza VALUES('J6','chorus','なれ愛,ひかり, 子にありいのち;<br/>愛とひかりにより, いのちを分与す。<br/>',NULL,48486,2);
INSERT INTO stanza VALUES('J6','2','うちなるなが愛は そんざいしめす;<br/>そとなるひかりは, ながわざしめす。<br/>',NULL,48487,3);
INSERT INTO stanza VALUES('J6','3','あいなるめぐみは, なれ享受させる;<br/>ひかりなるしん理, なれを知らせる。<br/>',NULL,48488,4);
INSERT INTO stanza VALUES('J6','4','ながあいとおして, いのちを得さす;<br/>ひかりの照らしで, 血をてきようす。<br/>',NULL,48489,5);
INSERT INTO stanza VALUES('J6','5','愛にていのち得て, まじわりに入る;<br/>ひかりのきよめで, まじわり享受す。<br/>',NULL,48490,6);
INSERT INTO stanza VALUES('J6','6','ひかりと血により, あぶら塗り来る;<br/>なれのほんしつは, うちをながれる。<br/>',NULL,48491,7);
INSERT INTO stanza VALUES('J6','7','あいにて子とされ, アバちち,と呼ぶ;<br/>くらやみのぞかれ, 子のかたち成る。<br/>',NULL,48492,8);
INSERT INTO stanza VALUES('J6','chorus','何というえい光, 感謝,賛美やまず!<br/>ちちよ,なれはあい, なれまたひかり!<br/>',NULL,48493,9);
INSERT INTO stanza VALUES('J7','1','えい遠のちちよ, ありてあるもの!<br/>過去の永遠より, なれは存在する!<br/>',NULL,48494,1);
INSERT INTO stanza VALUES('J7','2','えい遠のかみは, すべて超えつす!<br/>えい遠のかん全, 無げんなるかた!<br/>',NULL,48495,2);
INSERT INTO stanza VALUES('J7','3','万ゆうのこん源, 万ぶつにまさる!<br/>世々のはじめに さき立ちてある!<br/>',NULL,48496,3);
INSERT INTO stanza VALUES('J7','4','えい遠のいのち, 終わることなし!<br/>きゅうきょくまでも 朽ちることなし!<br/>',NULL,48497,4);
INSERT INTO stanza VALUES('J7','5','さい初でさい後, アルフｧでオメガ！<br/>はじめと終わり, かん全で無けつ!<br/>',NULL,48498,5);
INSERT INTO stanza VALUES('J7','6','無げんのかみを, われらは賛美す!<br/>なれの豊まんと かん全をたとう!<br/>',NULL,48499,6);
INSERT INTO stanza VALUES('J8','1','ちちよ,なれはれい, 何としんせい;<br/>霊にあり,霊もちい, なれをはいす。<br/>',NULL,48500,1);
INSERT INTO stanza VALUES('J8','2','霊ではいするため, 霊はつくらる;<br/>霊にてさい生され, 霊は呼応する。<br/>',NULL,48501,2);
INSERT INTO stanza VALUES('J8','3','ちち,子にあり来て, 子は霊となり,<br/>ひとの霊にはいり, めぐみゆたか。<br/>',NULL,48502,3);
INSERT INTO stanza VALUES('J8','4','御子はながことば, ことばはれい;<br/>わがれいに入りて, いのちとなる。<br/>',NULL,48503,4);
INSERT INTO stanza VALUES('J8','5','わがれいに住みて, ひとつ霊なり;<br/>われらなが子らと, 霊はあかしす。<br/>',NULL,48504,5);
INSERT INTO stanza VALUES('J8','6','霊でみちびきませ, われしたがう;<br/>われの全存ざいは, 霊にぞくする。<br/>',NULL,48505,6);
INSERT INTO stanza VALUES('J8','7','霊にあり礼はいし, 霊にていのる;<br/>えいこうのかたち, あらわるまで。<br/>',NULL,48506,7);
INSERT INTO stanza VALUES('J8','8','ちちよ,なれはれい, ほめたたえる!<br/>霊にあり,霊もちい, なれをはいす!<br/>',NULL,48507,8);
INSERT INTO stanza VALUES('J9','1','み なもとなるかみよ, ほう富ないのち!<br/>生けるみずとしながれ, えい遠にいたる!<br/>',NULL,48508,1);
INSERT INTO stanza VALUES('J9','2','子にあり,あいにより, 世びとにながれ;<br/>あいもたらす,れいとし, わがうちはいる。<br/>',NULL,48509,2);
INSERT INTO stanza VALUES('J9','3','われらはつみに満ち, とおくはなれど,<br/>なれ,子にてあがないなし, いのちをあとう。<br/>',NULL,48510,3);
INSERT INTO stanza VALUES('J9','4','われ,なれをあなどり, 聖霊かなします;<br/>なれ,なおわが霊に入り, いのちとなりぬ。<br/>',NULL,48511,4);
INSERT INTO stanza VALUES('J9','5','子にあり,れいとして, なれ,はいり来る;<br/>あぶら塗りはぞう加す, まじわりとおし。<br/>',NULL,48512,5);
INSERT INTO stanza VALUES('J9','6','かみの愛,主のめぐみ, れいのまじわり;<br/>かみのほう富,えい遠に われらにあとう。<br/>',NULL,48513,6);
INSERT INTO stanza VALUES('J9','7','ちち,子,れいはひとつ, かえりみゆたか,<br/>ちょう和してながあいを, えい遠に賛美す!<br/>',NULL,48514,7);
INSERT INTO stanza VALUES('J10','1','何とたくえつし, 何と聖なるかみ!<br/>くらべうるもの ほかにありや!<br/>せいのせいなり, 全宇ちゅうはさけぶ!<br/>ちから,せいしつ, 万ぶつ超える!<br/>',NULL,48515,1);
INSERT INTO stanza VALUES('J10','2','なれはユニーク, せい,義,じゅんすい;<br/>欠けることなく, さらにかん全。<br/>くらべうるもの 世にかつてありや;<br/>なにもなれには 代えられ得じ!<br/>',NULL,48516,2);
INSERT INTO stanza VALUES('J10','3','比類なくすぐれ, 美のきわみなり;<br/>こよなくひいで たくえつする。<br/>ながぜんすぐれ, 他のぜんにまさる;<br/>ながうるわしさ, 万ぶつ超える。<br/>',NULL,48517,3);
INSERT INTO stanza VALUES('J10','4','なれのとくしつ, いともせいなり;<br/>ながせいしつに われあずかる。<br/>われらもなれと ともにちょうえつし;<br/>せいなるなれは われせいとす。<br/>',NULL,48518,4);
INSERT INTO stanza VALUES('J10','5','たくえつすなれ, われらさん美す!<br/>なれのせいなる とくしつゆえ!<br/>ながせいしつは われらをぶん離す;<br/>われらあずかる, とこしえまで。<br/>',NULL,48519,5);
INSERT INTO stanza VALUES('J11','1','ちちよ,なれはしんせん, とわにみどり!<br/>生ける主おとろえなく, とわにいたる!<br/>',NULL,48520,1);
INSERT INTO stanza VALUES('J11','chorus','ちちよ,なれは新鮮, ふるびはせず!<br/>いくとせ過ぎ去るも, なおもしん鮮!<br/>',NULL,48521,2);
INSERT INTO stanza VALUES('J11','2','ちちよ,なれはかみ,また なれは「新」なり;<br/>なれなくばみなふるし, なれあれば「新」!<br/>',NULL,48522,3);
INSERT INTO stanza VALUES('J11','3','なれのあとうしゅくふく, みなあたらしい;<br/>新やく,あたらしいみち, とわにつづく。<br/>',NULL,48523,4);
INSERT INTO stanza VALUES('J11','4','あたらしいこころ,れい, あたらしいひと;<br/>日々あたらしくされて, いのちに満つ。<br/>',NULL,48524,5);
INSERT INTO stanza VALUES('J11','5','新天新地,新エルサレム, みなあたらしい;<br/>その実,まいつきみのり, とわにしん鮮。<br/>',NULL,48525,6);
INSERT INTO stanza VALUES('J11','6','ちちよ,なれはしんせん, 賛美はやまず;<br/>とわにあたらしいうた, なれにうたう。<br/>',NULL,48526,7);
INSERT INTO stanza VALUES('J12','1','てん地のつくられしもの, すべてはなれのちから,<br/>そのいろ,かたちすべては, なが無限をひょうげんす。<br/>',NULL,48527,1);
INSERT INTO stanza VALUES('J12','chorus','わがこころ,霊はうたう, なんという不思議よ!<br/>とわにわれらはうたう; 大いなるみかみを!<br/>',NULL,48528,2);
INSERT INTO stanza VALUES('J12','2','あいする御子をつかわし, すくいのみわざを成す,<br/>御子死に,いのちあたえて, われらを新創ぞうとす。<br/>',NULL,48529,3);
INSERT INTO stanza VALUES('J12','3','しょうかいのなかでなれを, ともに享受し,あずかる,<br/>み住まいけんぞうされて, ながゆたかあらわさる。<br/>',NULL,48530,4);
INSERT INTO stanza VALUES('J12','4','とき満ち,新エルサレムに, あずかるをのぞみ待つ;<br/>てん地はあたらしくされ, ながすべてあらわさる。<br/>',NULL,48531,5);
INSERT INTO stanza VALUES('J13','1','ちちよ,偉だいなるかみよ, なれはとわに変わらず。<br/>むかしいまし,いまいまし, とわにいまし,しんじつ。<br/>',NULL,48532,1);
INSERT INTO stanza VALUES('J13','chorus','なが信じつは偉大なるかな! なれはあさごとに新鮮!<br/>わがひつようことごとく, すべてなれは供給する!<br/>',NULL,48533,2);
INSERT INTO stanza VALUES('J13','2','なつもふゆも,はる,あきも, つき日はまわりつづけ,<br/>だい自ぜんはあかしする, なが無げんの信じつを。<br/>',NULL,48534,3);
INSERT INTO stanza VALUES('J13','3','つみのゆるし,へい安,歓喜, なが臨ざいはみちびく,<br/>きょうのちから,明日ののぞみ, すこしも欠くことなし。<br/>',NULL,48535,4);
INSERT INTO stanza VALUES('J14','1','ちちよ,なれなんと 信じつなかみ;<br/>万ぶつはあかしす, なが信じつを。<br/>',NULL,48536,1);
INSERT INTO stanza VALUES('J14','chorus','天にてわがために さだめられし,<br/>なが信じつのゆえ, 礼はいささぐ。<br/>',NULL,48537,2);
INSERT INTO stanza VALUES('J14','2','ちちはかげもなく, へん化もなし;<br/>いま,むかしつねに, とわにいます。<br/>',NULL,48538,3);
INSERT INTO stanza VALUES('J14','3','なれのみことばは とわにたしか;<br/>天地はほろびても, そんぞくする。<br/>',NULL,48539,4);
INSERT INTO stanza VALUES('J14','4','たまものと召しに 変わりはなし;<br/>めぐみとあわれみ, とわにつづく。<br/>',NULL,48540,5);
INSERT INTO stanza VALUES('J14','5','信じつなみことば, わが保証なり;<br/>ながすくいもまた, かくじつなり。<br/>',NULL,48541,6);
INSERT INTO stanza VALUES('J14','6','われは不真なるも, なれは信じつ;<br/>いつわり得ぬなれ, ことば成就す。<br/>',NULL,48542,7);
INSERT INTO stanza VALUES('J14','7','なが信じつにより, やくそく成る;<br/>信じつをかてとし, あまさ享受す。<br/>',NULL,48543,8);
INSERT INTO stanza VALUES('J14','8','御座をめぐるにじ, 信じつしめし;<br/>みやこをささえて, とわにいたる。<br/>',NULL,48544,9);
INSERT INTO stanza VALUES('J15','1','血なくて,ゆるすなら, 義は満たされず;<br/>血ありて責めれば, 理に合うことなし。<br/>',NULL,48545,1);
INSERT INTO stanza VALUES('J15','2','かみ,御子の犠牲ゆえ, ついきゅうできず;<br/>つみは遠くはなれ, 完全な自ゆう得る。<br/>',NULL,48546,2);
INSERT INTO stanza VALUES('J15','3','かみは義のよう求に, だい価をはらう;<br/>ゆるしがあるのみ, かみはさばき得ず。<br/>',NULL,48547,3);
INSERT INTO stanza VALUES('J15','4','かみの愛,あがない成し, 義のよう求満つ;<br/>義は満ち,わが主は, つみびとかい放す。<br/>',NULL,48548,4);
INSERT INTO stanza VALUES('J15','5','われは十字架じょ うで, 愛と義に出会う;<br/>愛と義は満たされ, われ絶えずうたう。<br/>',NULL,48549,5);
INSERT INTO stanza VALUES('J16','1','なが義と正義ゆえ, われらほめたたえ,<br/>あかしをする。<br/>なれはさばきぬし, なれに不義などなし,<br/>なれは義なり!<br/>',NULL,48550,1);
INSERT INTO stanza VALUES('J16','2','義は御座の土だい, へい和,そこに立つ,<br/>この義により,<br/>めぐみは支はいす, 主にありてわれらは,<br/>へい和得たり!<br/>',NULL,48551,2);
INSERT INTO stanza VALUES('J16','3','なが義ゆえ御子を 十字架にて死なせ,<br/>あがない成す;<br/>あがないのゆえに, なが義,われを義とし,<br/>われをすくう。<br/>',NULL,48552,3);
INSERT INTO stanza VALUES('J16','4','なれ,ひとのつみを かつては見過ごし,<br/>なが義しめす;<br/>されど,いまなれは つみびとをゆるして<br/>なが義しめす。<br/>',NULL,48553,4);
INSERT INTO stanza VALUES('J16','5','さばきの日,来ても, 揺らぐことはなし,<br/>なが義により,<br/>われらかたく立つ, めぐみは義のゆえに<br/>あらわされる。<br/>',NULL,48554,5);
INSERT INTO stanza VALUES('J16','6','王こくは義に満ち, へい和,そのうえに<br/>建て上げらる;<br/>しんてんしん地で, ちちの義は満ち満つ,<br/>やくそくゆえ。<br/>',NULL,48555,6);
INSERT INTO stanza VALUES('J17','1','つみに満ちるわれに, 義はさばきよう求する;<br/>主の血のあがないゆえ, 義はわれにへい安あとう。<br/>',NULL,48556,1);
INSERT INTO stanza VALUES('J17','2','かみはすくいぬしを, 十字架にてさばかれる;<br/>かみの義,つみびとらを 義とし,へい安を得さす。<br/>',NULL,48557,2);
INSERT INTO stanza VALUES('J17','3','義はつぐない要求す; 主がつぐなわれたのち,<br/>もはやつぐなわぬこと, 義はまたようきゅうする。<br/>',NULL,48558,3);
INSERT INTO stanza VALUES('J17','4','主,すでに血ながした; もはやくぎづけられず;<br/>われへのよう求もなく, ゆるし,きよめあるのみ。<br/>',NULL,48559,4);
INSERT INTO stanza VALUES('J17','5','かつてなが義を聞き, おそれて,逃げかくれた;<br/>いま,なれの義を聞けば, とうとさ,あいをおぼえる。<br/>',NULL,48560,5);
INSERT INTO stanza VALUES('J17','6','なが義を知ったゆえ, さらにながめぐみ知る;<br/>義はあんそくもたらし, めぐみ,なぐさめ満たす。<br/>',NULL,48561,6);
INSERT INTO stanza VALUES('J18','1','ちちよ,なが義のゆえ, われらは礼はいす;<br/>われ義とされしゆえ, だれ良心責めるや?<br/>なれこう義,信じつゆえ, なが義に立てば,<br/>なが義のみうでより, われをうばうものはなし。<br/>',NULL,48562,1);
INSERT INTO stanza VALUES('J18','2','わがつみ,イエスに置き, なが義,イエス死なす;<br/>律ぽうのようきゅうを, イエスはみな満たす。<br/>かみ,イエスのなだめ受け, われかいほうす;<br/>もっとも義なるかみの こころ,まったく満ち足る。<br/>',NULL,48563,2);
INSERT INTO stanza VALUES('J18','3','身代わりなるイエスを, 受け入れしちちは,<br/>不義なるわれのため, 義なるイエス,さばく。<br/>イエスはながみぎに座し, なが義をしめす;<br/>イエスはながまんぞく, すくいはとわに変わらず。<br/>',NULL,48564,3);
INSERT INTO stanza VALUES('J18','4','主の血によりわれは, すでに義とされる;<br/>なが義の保護により, われふるうものなし。<br/>なが義とされしわれを, だれ責め得るや?<br/>新エルサレムにあり, とわにこのあかしをなす。<br/>',NULL,48565,4);
INSERT INTO stanza VALUES('J19','1','聖なるちちをほめ, うたごえ合わせ,<br/>ながせいなる名を, われらほめうたう。<br/>',NULL,48566,1);
INSERT INTO stanza VALUES('J19','2','愛はちちのこころ, 義はながみわざ,<br/>聖はながせいしつ, ご自身を分与す。<br/>',NULL,48567,2);
INSERT INTO stanza VALUES('J19','3','キリストの血にて われらをきよめ,<br/>なれの真理により まったく聖べつす。<br/>',NULL,48568,3);
INSERT INTO stanza VALUES('J19','4','ながせいれいにて なれへと分離し,<br/>霊,たましい,からだ, まったく聖となす。<br/>',NULL,48569,4);
INSERT INTO stanza VALUES('J19','5','主の聖なるいのち, めぐみにて得る;<br/>聖なるせいしつに あずかるために。<br/>',NULL,48570,5);
INSERT INTO stanza VALUES('J19','6','聖なるみやこにて まったく聖とされ,<br/>「なれはせいなり」と とわにあかしす。<br/>',NULL,48571,6);
INSERT INTO stanza VALUES('J20','1','ちちはけいかくを 知恵のなかで,<br/>なが御子にありて すべて成就す。<br/>',NULL,48572,1);
INSERT INTO stanza VALUES('J20','chorus','かくもふかき知恵, だれきわむや?<br/>あわれみとめぐみ, われにおよぶ!<br/>',NULL,48573,2);
INSERT INTO stanza VALUES('J20','2','知恵なるそうぞう, なれよりいで,<br/>すべてなれ,とおし, なれへと帰す。<br/>',NULL,48574,3);
INSERT INTO stanza VALUES('J20','3','なが知恵はひとを つみのなかに,<br/>閉じ込めたり,そは あわれむため。<br/>',NULL,48575,4);
INSERT INTO stanza VALUES('J20','4','なが知恵にありて, あがない成し,<br/>わがれいに住みて, たからとなる。<br/>',NULL,48576,5);
INSERT INTO stanza VALUES('J20','5','もろもろの支はい, けん威たちに,<br/>しょうかいをとおし, 知恵を知らす。<br/>',NULL,48577,6);
INSERT INTO stanza VALUES('J20','6','新エルサレムにて きわみまでも,<br/>あらわされる知恵, われらほこる。<br/>',NULL,48578,7);
INSERT INTO stanza VALUES('J21','1','ちちよ,なが知恵と ながめぐみは,<br/>キリストのなかにみな, あつめられたり。<br/>かれをわが知恵となし, めぐみとなされた。<br/>',NULL,48579,1);
INSERT INTO stanza VALUES('J21','2','なれのけいかくは みな主にある;<br/>主はながめぐみのみち, 主こそなが知恵。<br/>知恵なる主のなかにて, なが豊富を享受す。<br/>',NULL,48580,2);
INSERT INTO stanza VALUES('J21','3','われら義とされた, かれはこう義;<br/>われらはせいとされた, かれはわがせい。<br/>われらキリストにあり, 義とせいとを得た。<br/>',NULL,48581,3);
INSERT INTO stanza VALUES('J21','4','なが計かくにより, 主はあがなう;<br/>からだまであがないて, えんじゅくさせる。<br/>きわみまでのすくいは, われらにじょう就す。<br/>',NULL,48582,4);
INSERT INTO stanza VALUES('J21','5','ながエコノミーにて 主はなが知恵;<br/>われらひれ伏し,はいす, 主イエスのゆえに;<br/>ちちよ,なれに向かいて われら賛美ささぐ。<br/>',NULL,48583,5);
INSERT INTO stanza VALUES('J21','6','われら,すでに見る, かれのうちに,<br/>なが知恵のゆたかさを, ふかさ,ひろさを;<br/>されど,なお見せたまえ, われらの身の上に。<br/>',NULL,48584,6);
INSERT INTO stanza VALUES('J22','1','ちちよ,偉だいなる あわれみをほむ!<br/>よわさのなかでも あわれみは増す。<br/>御ちちのあわれみ, われらを引き上げる!<br/>　　あわれみゆたか!<br/>',NULL,48585,1);
INSERT INTO stanza VALUES('J22','2','おどろくばかりの あわれみをほ む!<br/>われらにもおよぶ, つみびとにさえ,<br/>かたくとらえたる ちちのあわれみより,<br/>　　はなすものなし。<br/>',NULL,48586,2);
INSERT INTO stanza VALUES('J22','3','ゆたかで偉だいな あわれみをほむ!<br/>あがないにありて われらをめぐむ。<br/>あわれみなくして 恩けいいかで受くや?<br/>　　あわれみゆたか!<br/>',NULL,48587,3);
INSERT INTO stanza VALUES('J22','4','にゅう和とやさしさ, したしさ,あまさ,<br/>忍たい,慈あいもって ひつよう満たす。<br/>くらぶるものなし, かんぜんなあわれみ,<br/>　　われらのたから!<br/>',NULL,48588,4);
INSERT INTO stanza VALUES('J22','5','つねにあたらしい あわれみをほむ!<br/>あさつゆのように われ,あらたにす。<br/>われらきょう受して, あじ見をするたびに,<br/>　　御ちちを賛美す!<br/>',NULL,48589,5);
INSERT INTO stanza VALUES('J22','6','尽きぬあわれみに さん美は絶えず;<br/>めぐみ,かえりみは とわにわれらに,<br/>われら依りたのむ, 御ちちのあわれみに<br/>　　とわにまもらる。<br/>',NULL,48590,6);
INSERT INTO stanza VALUES('J23','1','あわれみしめす御ちちは, われらを,<br/>あいのなかでいとし子と なしたもう。<br/>　　あわれみのうつわとなして,<br/>　　とうときうつわと宣こくす。<br/>',NULL,48591,1);
INSERT INTO stanza VALUES('J23','2','ちちはいけにえこのまず, われらは,<br/>あわれみとおしめぐみに, あずかれり。<br/>　　ひとの意志,努りょくによらず,<br/>　　ただなれのあわれみによる。<br/>',NULL,48592,2);
INSERT INTO stanza VALUES('J23','3','ながあい,めぐみともなう あわれみ<br/>受けて,御ちちの御かおを, たのしめり。<br/>　　あわれみのゆえれいはいす,<br/>　　いまより代々にいたるまで。<br/>',NULL,48593,3);
INSERT INTO stanza VALUES('J24','1','かみの大いなるあい, ことばに言い得じ,<br/>星座よりなおたかく, よみよりもふかし。<br/>つみにおそれ,こころ 悔いるものらを,<br/>御子のすくいにより かみ,むかえたもう。<br/>',NULL,48594,1);
INSERT INTO stanza VALUES('J24','chorus','ゆたかなかみのあい, はかるすべなし。<br/>御つかい,せい徒らも, とわにぞうたわん。<br/>',NULL,48595,2);
INSERT INTO stanza VALUES('J24','2','さいげつもえい華も, てん地も過ぎゆく;<br/>いまあいをこばめば, かの日たすけなし。<br/>つみびとの負さいに, めぐみほどこす,<br/>かみの大いなるあい, 変わることなし。<br/>',NULL,48596,3);
INSERT INTO stanza VALUES('J24','3','大うみをぼく汁とし, 大ぞらをかみとし,<br/>くさをみなふでとし, ひとみな文士とし,<br/>すみ,かみ,ふで,ひとを つかい尽くすも,<br/>かみの無げんのあい, いまだ書き得じ。<br/>',NULL,48597,4);
INSERT INTO stanza VALUES('J25','1','ちちよ,なんという あいあとうや;<br/>かん謝し,さん美す, なれのすべて。<br/>',NULL,48598,1);
INSERT INTO stanza VALUES('J25','2','みこころ,けい示し, 御むね知らす;<br/>子にあり来たりて, けいかく成す。<br/>',NULL,48599,2);
INSERT INTO stanza VALUES('J25','3','ながあいゆえ,御子 来たり,死にて,<br/>おおくの子たちを 世継ぎとする。<br/>',NULL,48600,3);
INSERT INTO stanza VALUES('J25','4','御子を通し,ちちの いのちを持つ;<br/>神せいなせいしつ, われあずかる。<br/>',NULL,48601,4);
INSERT INTO stanza VALUES('J25','5','ながれいはいりて, アバ,と呼ばせ,<br/>再せいし,証いんし, つくり変える。<br/>',NULL,48602,5);
INSERT INTO stanza VALUES('J25','6','御子のかたちへと どうけい化し,<br/>多くの子,栄こうへ みちびき入る。<br/>',NULL,48603,6);
INSERT INTO stanza VALUES('J25','7','つくり変えのため, ばん事そなえ,<br/>栄光から栄光へと かんせいする。<br/>',NULL,48604,7);
INSERT INTO stanza VALUES('J25','8','ちちよ,なんという あいあとうや;<br/>感謝し,れいはいす, 賛美はやまじ!<br/>',NULL,48605,8);
INSERT INTO stanza VALUES('J26','1','ちちのあいのあとうもの, いかにおおくとも,<br/>天じょうではイｴスの血に まさるものはなし!<br/>',NULL,48606,1);
INSERT INTO stanza VALUES('J26','2','血にたいするしんこうを, ながあい,あたえる;<br/>さもなくば,たまものも, むなしいものとなる。<br/>',NULL,48607,2);
INSERT INTO stanza VALUES('J26','3','かみのあいはわがつみを, うみに投げ入れる;<br/>わが不義,すべておおい, とがをゆるしたもう。<br/>',NULL,48608,3);
INSERT INTO stanza VALUES('J26','4','とうとき血に見いだせり, あいのあしあとを;<br/>このゆえ,ながゆるしと, ながこう義を知る。<br/>',NULL,48609,4);
INSERT INTO stanza VALUES('J26','5','こころ,からだ,よわまるも, なおかたくしんず;<br/>信仰のいかりを下ろす, 天地はほろぶとも。<br/>',NULL,48610,5);
INSERT INTO stanza VALUES('J26','6','かの日,ながあいの価値を, われはしょうめいす;<br/>いま,わがいのちはまず, それにささえらる。<br/>',NULL,48611,6);
INSERT INTO stanza VALUES('J26','7','ちちよ,さん美し,さん美す! なれ,すべてあとう;<br/>主とその血のちからを, なれはあらわさる。<br/>',NULL,48612,7);
INSERT INTO stanza VALUES('J27','1','かみよ,なにゆえ ながあいの御子を,<br/>われらつみびとの ためにあとうや?<br/>このおおいなるあいは なれのあいする御子を,<br/>　わがため捨てさせる。<br/>',NULL,48613,1);
INSERT INTO stanza VALUES('J27','2','かみよ,なにゆえ 御子が御座を捨て,<br/>くるしみ,血ながし, いのち断ちしや?<br/>このおおいなるあいは 御子に苦なん受けさす,<br/>　わがため主,くるしむ。<br/>',NULL,48614,2);
INSERT INTO stanza VALUES('J27','3','ながあいのゆえ せいれいたまいて,<br/>てんのへい安もて われらを満たす;<br/>このおおいなるあいに くらぶるものはあらじ,<br/>　せいれいをつかわす。<br/>',NULL,48615,3);
INSERT INTO stanza VALUES('J27','4','かみのめぐみは すべてにまされり,<br/>かん謝とさんびと よろこびわきぬ;<br/>おおいなるあいのゆえ ねがわくはただなれを,<br/>　とわにたたえさせよ。<br/>',NULL,48616,4);
INSERT INTO stanza VALUES('J28','1','かみの愛は真じつ, かみはわれらの賛美を， 至せい所にて受ける。<br/>なれは来て解放す, つみのなかに死んでいて, のぞみなきわれらを。<br/>無げんの豊富なあいと, あわれみをもって, われらをすくわれる。<br/>',NULL,48617,1);
INSERT INTO stanza VALUES('J28','2','つみびとほろびず, なれをすくいぬしとし, もとむを,なれねがう。<br/>なれは御子にあり, われらをすでにえらび, しゅく ふくを得させる。<br/>いま「アバちち」とさけび, もはやおそれなく, わがちちにちかづく。<br/>',NULL,48618,2);
INSERT INTO stanza VALUES('J28','3','やがてかみのひと, なが御座にみちびかれ, 賛美し,れいはいする。<br/>だい群しゅうの賛美, あまきうたごえをもって, 宇宙にひびきわたる。<br/>ちちよ,いまわれしたう, ひとつこころもて, なれを賛美すことを。<br/>',NULL,48619,3);
INSERT INTO stanza VALUES('J29','1','われらかつて持ちしもの, ただ死とつみ;<br/>いまやしゅくふく受けるは, すべてかみによる。<br/>',NULL,48620,1);
INSERT INTO stanza VALUES('J29','2','つみにあるわれをたずね, 信仰をあとう;<br/>いまわれはあんそく得て, 主により生かさる。<br/>',NULL,48621,2);
INSERT INTO stanza VALUES('J29','3','せい徒とされ,受けしもの, またのぞみは,<br/>なにひとつ,われによらず, ながめぐみによる。<br/>',NULL,48622,3);
INSERT INTO stanza VALUES('J29','4','このあいにこたえるもの, だれもあらじ;<br/>ながあいは人知を超えて, しんせいで不思議!<br/>',NULL,48623,4);
INSERT INTO stanza VALUES('J29','5','ちちよ,そのあいをつねに 知らせたまえ;<br/>わがいのち,こころを得て, ながものとしませ。<br/>',NULL,48624,5);
INSERT INTO stanza VALUES('J29','6','うみのごとくふかきあい, 知らぬゆえに,<br/>ながあいにむくい得ると, おろかにもおもう。<br/>',NULL,48625,6);
INSERT INTO stanza VALUES('J29','7','なれのおおいなるあいを, 駆け引きせず,<br/>われを愛すそのこころに, だれむくい得るや!<br/>',NULL,48626,7);
INSERT INTO stanza VALUES('J29','8','ながあいにむくいるとは もはや言わず;<br/>ただかん謝に満たされて, えい遠に礼はいす。<br/>',NULL,48627,8);
INSERT INTO stanza VALUES('J29','9','われ,ちちの愛とみわざに 負い目があり;<br/>御子のゆえに感げきして, なれにあんそくす。<br/>',NULL,48628,9);
INSERT INTO stanza VALUES('J30','1','ちちよ,われら礼はいす, ふしぎなあいにおどろく!<br/>ひとはなにものなれば, かぎりなきめぐみあとうや!<br/>',NULL,48629,1);
INSERT INTO stanza VALUES('J30','2','ちちよ,御むねさん美す, ながすがたにひとつくり,<br/>いのち,せいしつ満たし, ながかたちに,ひょうげんさす。<br/>',NULL,48630,2);
INSERT INTO stanza VALUES('J30','3','なれのかたちにつくり, ひとにけん威をあたえて,<br/>ながいのちを得さすは, なが所ゆう,きょう受するため。<br/>',NULL,48631,3);
INSERT INTO stanza VALUES('J30','4','なれはひとにはいりて, 混ざり合い,かんせいする,<br/>つくり変え,住まいへと けん造し,栄こう表げんさす。<br/>',NULL,48632,4);
INSERT INTO stanza VALUES('J30','5','堕らくしたひと捨てず, 御むねじょう就するために,<br/>あがないて,連れかえり, ながあいと知恵を証めいす。<br/>',NULL,48633,5);
INSERT INTO stanza VALUES('J30','6','なれ,子にありあらわれ, 死と復かつをけい過して,<br/>れいにありひとに入り, いのちとめぐみをもたらす。<br/>',NULL,48634,6);
INSERT INTO stanza VALUES('J30','7','わが霊はなが至せい所, めぐみの御座そこにあり,<br/>いのりとおし,こうたき, わが霊にてなれとまじわる。<br/>',NULL,48635,7);
INSERT INTO stanza VALUES('J30','8','あふれるかわのごとく, めぐみは御座よりながれ,<br/>われらをつくり変えて, なれの住まいに建ぞうする。<br/>',NULL,48636,8);
INSERT INTO stanza VALUES('J30','9','奇しきながめぐみ受け, そのたまものに感どうし,<br/>偉だいなるあいをほめ, れいにてなれをれいはいす。<br/>',NULL,48637,9);
INSERT INTO stanza VALUES('J31','1','ちちなるみかみの あいかぎりなし!<br/>創せいのまえより われらをえらび,<br/>主イｴスに引き寄す あまくふかきあいに,<br/>　とわにまもれや。<br/>',NULL,48638,1);
INSERT INTO stanza VALUES('J31','2','世は変わりゆくも, かみは変わらず;<br/>あいとみことばは とわにわれらに<br/>かたくさだまれり, われらかみの子らよ,<br/>　御ちちをほめよ。<br/>',NULL,48639,2);
INSERT INTO stanza VALUES('J31','3','御子さえおしまず あたえしかみの,<br/>あいはとらえたもう わがいのちをも。<br/>そのあわれみわが うたとくちのほこり,<br/>　こころはたのし。<br/>',NULL,48640,3);
INSERT INTO stanza VALUES('J31','4','こころを合わせて 不思議なあいを,<br/>御まえに行きても たからかにほむ;<br/>えい光を受けませ, みかみと小ひつじよ,<br/>　いまよりとわに。<br/>',NULL,48641,4);
INSERT INTO stanza VALUES('J32','1','ちちよ,われらは, あいのたい象;<br/>われらの賛美に なれは歓喜す;<br/>しるしづけられた 多くの子たちは<br/>なれの至こうの たい象となる。<br/>',NULL,48642,1);
INSERT INTO stanza VALUES('J32','2','創せいのまえに なれはえらび,<br/>なが嗣業として さだめられる。<br/>子たる身ぶんへと なれ,しるしづけ,<br/>せいちょうさせて, しゅくふくする。<br/>',NULL,48643,2);
INSERT INTO stanza VALUES('J32','3','永遠のさだめで われら召され,<br/>ながいのち得て, つみのぞかる。<br/>その霊の証印受け, なれにぞくして,<br/>霊の担保を受け, なれを享受す。<br/>',NULL,48644,3);
INSERT INTO stanza VALUES('J32','4','ちちはわれらを しゅくふくして,<br/>ながれいたまい, いのち得さす。<br/>間もなくわれらは えいこうを得て,<br/>えい遠になれを あらわし出す!<br/>',NULL,48645,4);
INSERT INTO stanza VALUES('J33','1','かみは小ひつじにありて, わがのぞみ,またあんそく,<br/>えいこうの御名にありて われらをしゅくふくす。<br/>',NULL,48646,1);
INSERT INTO stanza VALUES('J33','2','なれは義,ぜん,慈あい,知恵, なれはわがちち,わがかみ;<br/>血にてなれのものとなり, おおくの子らとなる。<br/>',NULL,48647,2);
INSERT INTO stanza VALUES('J33','3','われられいをかつようし, なれに来て,御名をあおぐ;<br/>しか,みずをしたうごとく, なれをしたいもとむ。<br/>',NULL,48648,3);
INSERT INTO stanza VALUES('J33','4','なれのめぐみをしたいて, なれにしたしくまみえる;<br/>なが臨ざいのうちに住み, ながあいをよろこぶ。<br/>',NULL,48649,4);
INSERT INTO stanza VALUES('J33','5','かみはえい遠のよろこび， くらきをひかりに変える;<br/>かすかないきさえあれば, なれに賛美をうたう。<br/>',NULL,48650,5);
INSERT INTO stanza VALUES('J34','1','ほめよ,ちちがみのみわざ； 世をあいし,御子つかわし,<br/>いのち捨てさせ,あがない, すくいのみち,ひらかれる。<br/>',NULL,48651,1);
INSERT INTO stanza VALUES('J34','chorus','ほめよ,ほめよ, 全地よ,うたえ!<br/>ほめよ,ほめよ, よろこびもて,<br/>子にあり,ちちにちかづき, 大いなるかみをほめうたう。<br/>',NULL,48652,2);
INSERT INTO stanza VALUES('J34','2','とうとき血にてあがない, 信じるものをすくわれる;<br/>つみびとのかしらさえも, 信じるものをゆるされる。<br/>',NULL,48653,3);
INSERT INTO stanza VALUES('J34','3','かみはみわざを成し遂げ, われらも子にあり歓喜す;<br/>されど主にまみえるとき, その歓喜,ちょう点にいたる。<br/>',NULL,48654,4);
INSERT INTO stanza VALUES('J35','1','ほめうたう, 御子つかわし,<br/>復かつ,昇天させ, 大祭司とす。<br/>',NULL,48655,1);
INSERT INTO stanza VALUES('J35','chorus','ハレルヤ,えいこう, ハレルヤ,アーメン!<br/>ハレルヤ,めぐみを ほめうたう。<br/>',NULL,48656,2);
INSERT INTO stanza VALUES('J35','2','ほめうたう, 照らす霊に て,<br/>あがないぬしを けい示する。<br/>',NULL,48657,3);
INSERT INTO stanza VALUES('J35','3','賛美,えい光, 御ちちに帰す;<br/>あがないにより すくい受く。<br/>',NULL,48658,4);
INSERT INTO stanza VALUES('J35','4','なが愛ゆえ, さん美ささぐ,<br/>こころ燃やされ, 礼はいする。<br/>',NULL,48659,5);
INSERT INTO stanza VALUES('J36','1','われらのこえはただ主をほむ, 栄こう,主にハレルーヤ!<br/>れいのなかにてさらにつよく, 栄こう,主にハレルヤ!<br/>',NULL,48660,1);
INSERT INTO stanza VALUES('J36','chorus','かみの子どもよ, さけべようたえ,<br/>われらのみちは, ひかりかがやく,<br/>えい光のうちにわが王にまみえん; 栄こう,主にハレルヤ!<br/>',NULL,48661,2);
INSERT INTO stanza VALUES('J36','2','すくいのあいにありてたのし, 栄こう,主にハレルーヤ!<br/>よろこびあふれ,こころおどる, 栄こう,主にハレルヤ!<br/>',NULL,48662,3);
INSERT INTO stanza VALUES('J36','3','みかみの建てたもうしろに行き, 栄こう,主にハレルーヤ!<br/>そこにてわが王のかがやき見ん, 栄こう,主にハレルヤ!<br/>',NULL,48663,4);
INSERT INTO stanza VALUES('J36','4','そこにてあたらしきうたうたう, 栄こう,主にハレルーヤ!<br/>せい徒らともどもイｴスかこみ, 栄こう,主にハレルヤ!<br/>',NULL,48664,5);
INSERT INTO stanza VALUES('J37','1','アバちち,われらいま 御名にて礼はいす;<br/>なが子らつどいきて, しゅくふくもとめる。<br/>主は血にてとがあらい, われら引き寄す;<br/>アバちち,とさけぶを, なれのれいはおしえたもう。<br/>',NULL,48665,1);
INSERT INTO stanza VALUES('J37','2','つみの増すところに, めぐみもいや増す;<br/>なれより遠くはなれ, さまよいしものも,<br/>すくいのころもまとい, 宴せきに着きて,<br/>ながめぐみのとみを, なれもわれらもよろこぶ。<br/>',NULL,48666,2);
INSERT INTO stanza VALUES('J37','3','ちちは放蕩むすこを, ゆるし,くちづけす;<br/>肥えた子うしほふり, 御むねをあらわす。<br/>「うしなわれ,死にし子の, 生きかえるゆえ,<br/>よろこびいわえよ」と, かたるみこえをわれ聞く。<br/>',NULL,48667,3);
INSERT INTO stanza VALUES('J37','4','アバちち,ながあいを, たからかにうたう!<br/>御つかいもほめたとう, 大いなるめぐみを。<br/>なが御座にともに来て, なが子らは言う;<br/>アバのあいはゆたか, アバの名はかん容なり!と。<br/>',NULL,48668,4);
INSERT INTO stanza VALUES('J38','1','アバちち,われらいま, なれを礼はいす!<br/>ちちよ,と呼べるのは 子らのほかなし。<br/>主の名ゆえにわれらは, 子たるけん威受く;<br/>主のれいとわがれいは, ともにあかしする。<br/>',NULL,48669,1);
INSERT INTO stanza VALUES('J38','2','なれは創世のまえに, キリストにあり,<br/>われらをなが子らと すでにさだめる。<br/>ちちよ,何というあいよ, 何というとうとさよ!<br/>ながいのち,せいしつに, われらはあずかる。<br/>',NULL,48670,2);
INSERT INTO stanza VALUES('J38','3','われらアダムにあり, 堕らくしたのに,<br/>なが御むねによって, ながものとなる;<br/>主によりあがなわれて, なれをちちと呼ぶ;<br/>主とちちとしょうかいは, 混ざり合い,ひとつ。<br/>',NULL,48671,3);
INSERT INTO stanza VALUES('J38','4','わざわいも,試れんも, 境ぐう変わるも,<br/>なが不へんのあいは, われらみちびく。<br/>あがなわれし子たちは, 御座のまえに来て,<br/>すくわれたあかしをし, とわにさん美する。<br/>',NULL,48672,4);
INSERT INTO stanza VALUES('J39','1','アバちち,御まえに伏して, こころよりれいはいささぐ;<br/>いけにえでなく,霊のなかで, われら「実さい」をささぐ。<br/>',NULL,48673,1);
INSERT INTO stanza VALUES('J39','2','御ちちはありてあるもの, 永えんよりえい遠にいたる;<br/>なが御座は天でかたく立ち, えいこう,聖,権威は無限。<br/>',NULL,48674,2);
INSERT INTO stanza VALUES('J39','3','偉だいな義を見ただけで, なが慈あいのこころ知らず。<br/>のぞみなき世のつみびとは, どうしていのり得よう?<br/>',NULL,48675,3);
INSERT INTO stanza VALUES('J39','4','されどひとり子のなかで, ご自身を完ぜんにけい示す;<br/>つみびとはあがないを経て, なれは御座で満ぞくす。<br/>',NULL,48676,4);
INSERT INTO stanza VALUES('J39','5','つみびと得るため,なれは ひとり子をいち時,見捨てる;<br/>なれとわれら,したしむため, 十字架でくるしませる。<br/>',NULL,48677,5);
INSERT INTO stanza VALUES('J39','6','ながあいの御子,死なれて, われらはなが子たちとなる;<br/>かつて,なれおそるべきかた, いまや,あいすべきアバ。<br/>',NULL,48678,6);
INSERT INTO stanza VALUES('J39','7','アバちち,ながあいふかく, われらむくいるすべはなし;<br/>われらただ感謝,賛美ささげ, とわになれを礼はいす。<br/>',NULL,48679,7);
INSERT INTO stanza VALUES('J39','note','１　「実さい」はキリストを指す。<br/>',NULL,48680,8);
INSERT INTO stanza VALUES('J40','1','いけにえも血も すべては過ぎ去る;<br/>けむりもなく,火もなく,もう, いけにえひつ要なし;<br/>　さらにまさる血ながれ,<br/>　けがれきよめ,つみをゆるす。<br/>',NULL,48681,1);
INSERT INTO stanza VALUES('J40','2','御子の血のゆえ, かみよ,感謝します,<br/>血により,われらは義とされ, 地ごく,死,やみに勝利;<br/>　たたかうひつようなし,<br/>　てきはすべて,ほろぼされた。<br/>',NULL,48682,2);
INSERT INTO stanza VALUES('J40','3','天のめぐみゆえ, かみよ，感謝します,<br/>われらの不義を過ぎ越して, ふかきつみをゆるす;<br/>　ながあいを賛美します,<br/>　栄こう, 権威がえい遠にあれ。<br/>',NULL,48683,3);
INSERT INTO stanza VALUES('J40','4','かたきのぞみに, かみよ,感謝します，<br/>れいはふたたび生かされて, こころにあさ日照る;<br/>　さいわいなのぞみあり,<br/>　あら野をたびするときにも。<br/>',NULL,48684,4);
INSERT INTO stanza VALUES('J40','5','栄光のかんむりに, かみよ,感謝します,<br/>朽ちるものでなく,枯れない, えいえんのかんむり;<br/>　われらはみなかんむりを,<br/>　よろこびつつ,御座に投げる。<br/>',NULL,48685,5);
INSERT INTO stanza VALUES('J41','1','かみに召されて 御子をあおぐ,<br/>かれは御むねを じょう就される;<br/>ながひとり子を われにあたえ,<br/>すくいのこころを われに知らす。<br/>',NULL,48686,1);
INSERT INTO stanza VALUES('J41','2','御子の名のゆえ, ゆう気を持ち,<br/>めぐみをもとめ, いのちを得る;<br/>なれのよろこぶ 御子のゆえに,<br/>われらのうたがい, おそれはなし。<br/>',NULL,48687,2);
INSERT INTO stanza VALUES('J41','3','主,さばき受けて, 過去は終わり,<br/>つみゆるされて, おそれは去る。<br/>なが御子,死にて, つぐない成し,<br/>なれ,いま,われらに, 自ゆう得さす。<br/>',NULL,48688,3);
INSERT INTO stanza VALUES('J41','4','かれをしんじる われらはいま,<br/>かえりみ知りて こころやすし;<br/>もどりし子らに くちづけをし,<br/>かがやくころもを さずけられる。<br/>',NULL,48689,4);
INSERT INTO stanza VALUES('J41','5','ちちにさからい, ちちをうらむ<br/>われをなにゆえ, あいするのか?<br/>まことに不思議! 神聖なおく義!<br/>「なれはわがもの」と, なれはかたる。<br/>',NULL,48690,5);
INSERT INTO stanza VALUES('J42','1','ちちよ,いまわれ, つつしみをもて,<br/>主のいけにえにて なれを礼拝す。<br/>',NULL,48691,1);
INSERT INTO stanza VALUES('J42','2','おおいなるあい, 主の死にて受け,<br/>めぐみと義を得て, なれを礼拝す。<br/>',NULL,48692,2);
INSERT INTO stanza VALUES('J42','3','われらつみびと, かみの子となる!<br/>ほう富なめぐみに なれを礼拝す。<br/>',NULL,48693,3);
INSERT INTO stanza VALUES('J42','4','霊にあり,はいす, 主を実さいとす;<br/>かれはささげもの, なれを礼拝す。<br/>',NULL,48694,4);
INSERT INTO stanza VALUES('J42','5','とこしえまでも, なれ,たかく揚げ,<br/>なが愛に感謝して, なれを礼拝す。<br/>',NULL,48695,5);
INSERT INTO stanza VALUES('J43','1','ちちのあいは無限, なれをさん美す;<br/>めぐみのえき受けて, われらかん喜す。<br/>創せいのまえより われらをえらび,<br/>ときいたり,われらに めぐみあたえる。<br/>',NULL,48696,1);
INSERT INTO stanza VALUES('J43','2','主をふっかつさせ, 長子とならせる;<br/>かれ,みわざを成就し, 勝利を得られる。<br/>われら多くの子は よろこび,うたう;<br/>長子のかえりみゆえ, にち夜さん美す。<br/>',NULL,48697,2);
INSERT INTO stanza VALUES('J43','3','かれのちち,かみは われのちち,かみ;<br/>主のにくしんである われら,分け得じ。<br/>集かいのなかにて, 主にみちびかる;<br/>主とわれらはひとつ, われら多くの子。<br/>',NULL,48698,3);
INSERT INTO stanza VALUES('J43','4','かみのあい!めぐみ! 主とわれらいち;<br/>そはちちのよろこび, われらのきょう受。<br/>われら待ちのぞむ: 主のさいりんを,<br/>みなひとつこころで, 歓喜することを。<br/>',NULL,48699,4);
INSERT INTO stanza VALUES('J44','1','ちちよ,めぐみにて, なが名をたたえ,<br/>むれへともたらされて, われらは歓喜する。<br/>',NULL,48700,1);
INSERT INTO stanza VALUES('J44','2','わが賛美にまさり, けん固なすくい;<br/>いま,われらのこころは, 天の御座に向かう。<br/>',NULL,48701,2);
INSERT INTO stanza VALUES('J44','3','なれはてんにあり, 永えんのささえ;<br/>つみびとをかいほうし, いのちをあたえる。<br/>',NULL,48702,3);
INSERT INTO stanza VALUES('J44','4','えい遠は,なが豊富, あらわれるため;<br/>また子らがご自しんと 豊富,たたえるため。<br/>',NULL,48703,4);
INSERT INTO stanza VALUES('J44','5','夜明けまだ見ずも, このみちあゆむ;<br/>死とはかより解かれて, たずさえ上げ,待つ。<br/>',NULL,48704,5);
INSERT INTO stanza VALUES('J44','6','なれ「とわのぶん」と, われらよろこぶ;<br/>御子にどう形化されて, 夜明けを享受する。<br/>',NULL,48705,6);
INSERT INTO stanza VALUES('J44','7','ちちよ,御名のゆえ, われをまもれや;<br/>かの地でたのしむまで, 御子にしたがいゆく。<br/>',NULL,48706,7);
INSERT INTO stanza VALUES('J45','1','ちちよ,かん喜し, ほめたたえる;<br/>死より解かれて, 御子とひとつ。<br/>御子は御まえに 「ひと」とし生き,<br/>無限のあいにて なが恩ちょう受く。<br/>',NULL,48707,1);
INSERT INTO stanza VALUES('J45','2','御子のちち,かみ, わがちち,かみ;<br/>主はなれの愛子, かん喜,たから。<br/>御子はわれらを 御まえに連れ,<br/>なが愛の恩ちょうを きょう受させる。<br/>',NULL,48708,2);
INSERT INTO stanza VALUES('J45','3','永遠のなが愛は, われらつつむ;<br/>そのあいすべて, 御子のなかに。<br/>多くの子,御子の 兄だいたちは,<br/>御子にあり,愛を ともに享受す。<br/>',NULL,48709,3);
INSERT INTO stanza VALUES('J46','1','かみの愛におおくの子, 呼応する;<br/>御子の名ゆえ,御まえに ちかづく。<br/>　御子に同けい化されて,<br/>　なれのよろこびとなる。<br/>',NULL,48710,1);
INSERT INTO stanza VALUES('J46','2','御子はちちのよろこび, ながあい;<br/>われらは御子のなかで あずかる。<br/>　無げんのあい,きょう受し,<br/>　ともにえいこうを見る。<br/>',NULL,48711,2);
INSERT INTO stanza VALUES('J46','3','多くの子らちょう和して, さん美す;<br/>御子はわれらのさん美 みちびく。<br/>　エコノミｰのみなもとの,<br/>　さい高のちちをたとう。<br/>',NULL,48712,3);
INSERT INTO stanza VALUES('J47','1','御子にみちびかれ， 御まえにすすみ，<br/>賛美，礼拝をささげ なが慈愛享受す。<br/>ちちは計かく成し， 御座で満ぞくす，<br/>死と復かつとおし， われらを聖とす。<br/>',NULL,48713,1);
INSERT INTO stanza VALUES('J47','2','パンとさかずきを われら食べ飲む；<br/>このしるし，御子の 愛のわざしめす。<br/>からだは裂かれて みちはひらかれ，<br/>われら，すすみ来て， アバ,ちちと呼ぶ。<br/>',NULL,48714,2);
INSERT INTO stanza VALUES('J47','3','御子は血をながし， つみを塗り消す；<br/>なが義といかりは， われを責めない。<br/>主の血は御まえで わがためかたる；<br/>サタンはわれらを うったえられない。<br/>',NULL,48715,3);
INSERT INTO stanza VALUES('J47','4','てん使よりさらに ちいさいひとを，<br/>たからと見なして， かえりみ,さがし，<br/>なれに和かいさせ， ゆるし得させる!<br/>ちちよ,賛美します！ とうといめぐみを。<br/>',NULL,48716,4);
INSERT INTO stanza VALUES('J48','1','宴せき過ぎ,なおあまし, 御子は賛美をみちびく;<br/>なんとあまく,とうとし, 調和しともにさん美す。<br/>',NULL,48717,1);
INSERT INTO stanza VALUES('J48','2','ながゆたかないのちを, われらすでにあじわう;<br/>ち ちよ,なれこそひつ要, なれにまさるものなし。<br/>',NULL,48718,2);
INSERT INTO stanza VALUES('J48','3','ちちよ,ながあいにあり, わがあい増しくわわる;<br/>ながあい,われみちびき, 臨ざいをきょう受させる。<br/>',NULL,48719,3);
INSERT INTO stanza VALUES('J48','4','ちちよ,御子にしたがい, よろこびもてさん美す;<br/>われらおおくの子らは, なが名のほう富に飽く。<br/>',NULL,48720,4);
INSERT INTO stanza VALUES('J49','1','ちちよ,われらかしこみて, 礼はいす;<br/>なが子ら和合しつどいて, 賛美ささぐ。<br/>　なが家にわれらかえり来て,<br/>　御子とともにアバ!とさけぶ。<br/>',NULL,48721,1);
INSERT INTO stanza VALUES('J49','2','ちちよ,いかにふかきかな, ながあい;<br/>御子の上にじょう就されし ちちのあい。<br/>　このあいほむものら連れて,<br/>　御まえに御子はちちをほむ。<br/>',NULL,48722,2);
INSERT INTO stanza VALUES('J49','3','御ちちは御子のさん美を よろこび,<br/>和するわれらのこえをも 聞きたもう。<br/>　ながあい,はじめ御子にあり,<br/>　われらを御子の伴侶とする。<br/>',NULL,48723,3);
INSERT INTO stanza VALUES('J50','1','ちちの愛,子にてあらわれ,<br/>いま,われら呼おうする。<br/>御子ははんさいとなるゆえ,<br/>なれは御子に満ぞくする。<br/>',NULL,48724,1);
INSERT INTO stanza VALUES('J50','2','御子はわれらを引き連れ,<br/>御ちちにさん美うたう。<br/>われらもれいのなかにて,<br/>ともに御ちちをさん美す。<br/>',NULL,48725,2);
INSERT INTO stanza VALUES('J50','3','あい子のなかでえらばれ,<br/>ともに御ちちをうたう。<br/>創せいまえにさだめられ,<br/>御子のいのちにあずかる。<br/>',NULL,48726,3);
INSERT INTO stanza VALUES('J50','4','ちちはおおくの子あいし,<br/>御子をわれらの分とす。<br/>われら子のとくちょう帯び,<br/>とわにながよろこびなり。<br/>',NULL,48727,4);
INSERT INTO stanza VALUES('J51','1','ちちよ,すべてにまさり, われら,なれをほめうたう。<br/>れいもてなれをはいし, 感謝とさん美をささぐ。<br/>',NULL,48728,1);
INSERT INTO stanza VALUES('J51','2','万ぶつは御子によって, 創ぞうされ,成り立っている。<br/>われらは御子のなかで, ちかづき,れいはいする。<br/>',NULL,48729,2);
INSERT INTO stanza VALUES('J51','3','御子はしゅくふくのなか, 召かいのなかにてうたう。<br/>われらきょうだいたちは, 御子ともにあり,うたう。<br/>',NULL,48730,3);
INSERT INTO stanza VALUES('J51','4','われら,主,ともにうたい, ちちにまんぞくあたえる。<br/>なが御子の賛美にあり, なれ,とわにあんそくす。<br/>',NULL,48731,4);
INSERT INTO stanza VALUES('J52','1','われら,すくいぬしの血で, ちちよ,なれにちかづく;<br/>めぐみにより自ゆう得て, 御まえでなれをさん美す。<br/>',NULL,48732,1);
INSERT INTO stanza VALUES('J52','2','ちちよ,われらは御まえに, 御子の香ばしい名ささぐ;<br/>御子の死にてめぐみ受け, しんこうもて御子あおぐ。<br/>',NULL,48733,2);
INSERT INTO stanza VALUES('J52','3','われらちちのよろこびを, 御子とともにきょう受す;<br/>こよなく,うるわしい主の, えい光,とわにおとろえず。<br/>',NULL,48734,3);
INSERT INTO stanza VALUES('J52','4','なれの愛のたいしょう見て, 御まえにちちをはいす;<br/>御子と多くのきょうだいは, ともにちちをほめうたう。<br/>',NULL,48735,4);
INSERT INTO stanza VALUES('J53','1','主はかみのことば, かみのえい光;<br/>はじめからかみと ともにいます。<br/>',NULL,48736,1);
INSERT INTO stanza VALUES('J53','chorus','主は生けることば, かみをはっぴょうす!<br/>かみの栄こう,本しつ, まったきひょう現。<br/>',NULL,48737,2);
INSERT INTO stanza VALUES('J53','2','ばんぶつはかみの えいこう述べ,<br/>かみのせいしつと ちからしめす。<br/>',NULL,48738,3);
INSERT INTO stanza VALUES('J53','3','おく義なることば, なれのあかし;<br/>なれは発表されて, かみをかたる。<br/>',NULL,48739,4);
INSERT INTO stanza VALUES('J53','4','ことば,受にくして, 地上をあゆむ;<br/>ひとがら,こう為は かみあらわす。<br/>',NULL,48740,5);
INSERT INTO stanza VALUES('J53','5','なれ,生けることば, いのち,ひかり,<br/>いのちとし照らし, かみを表現す。<br/>',NULL,48741,6);
INSERT INTO stanza VALUES('J53','6','かみの義あらわる, ながさばきに,<br/>かみをことごとく あらわすため。<br/>',NULL,48742,7);
INSERT INTO stanza VALUES('J53','7','主よ,なれはかみの まったきひょう現;<br/>もはやかくれたる かみにあらず。<br/>',NULL,48743,8);
INSERT INTO stanza VALUES('J54','1','主よ,なれとわのことば, 　 ちちのひとり子,<br/>かみをひとに見せる, 　　あいする御子。<br/>しんせいなかみの御子, かみのほう満あらわす。<br/>',NULL,48744,1);
INSERT INTO stanza VALUES('J54','2','ちちの栄光のかがやき, 　 完全にあらわす;<br/>かみのほう満を持ち, 　　とわに神せい。<br/>しんせいなかみの御子, かみのほう満あらわす。<br/>',NULL,48745,2);
INSERT INTO stanza VALUES('J54','3','無げんのかみのかたち, 　 かみのほんしつ;<br/>かみのひかり照らし, 　　御むね知らす。<br/>しんせいなかみの御子, かみのほう満あらわす。<br/>',NULL,48746,3);
INSERT INTO stanza VALUES('J54','4','御名のおく義のふかさ, 　 天使さえ知らず;<br/>ながしん聖のおく義, 　　ちちのみ知る。<br/>しんせいなかみの御子, かみのほう満あらわす。<br/>',NULL,48747,4);
INSERT INTO stanza VALUES('J54','5','宇宙のなかのちゅうしん, 　主の「である」こと;<br/>えい遠にほめたとう, 　　あいする御子:<br/>しんせいなかみの御子, かみのほう満あらわす。<br/>',NULL,48748,5);
INSERT INTO stanza VALUES('J55','1','主よ,なれはかみのことば, なれはかみの御子;<br/>かみの真じつのかたち, えいこうのすがた。<br/>',NULL,48749,1);
INSERT INTO stanza VALUES('J55','2','かみのすべてのほうまん, ながうちに住めり;<br/>なれにてかみひょう現す, なれはかみの化身。<br/>',NULL,48750,2);
INSERT INTO stanza VALUES('J55','3','かみの栄こうのかがやき, なれはかみといち;<br/>かみの本しつのかたち, かみが実際となる。<br/>',NULL,48751,3);
INSERT INTO stanza VALUES('J55','4','なれにてかみ,わがいのち, わがひかりとなる;<br/>かみのせいしつを持ち, かみ増しくわわる。<br/>',NULL,48752,4);
INSERT INTO stanza VALUES('J55','5','なれにてかみ,わがめぐみ, なれにてかみ受く;<br/>かみの実際,なれにあり, なれにてかみ見る。<br/>',NULL,48753,5);
INSERT INTO stanza VALUES('J55','6','なれにてほうまんを受け, めぐみくわえらる;<br/>われらかみと混ざりて, かみのすべて受く。<br/>',NULL,48754,6);
INSERT INTO stanza VALUES('J55','7','主よ,なれをれいはいする, なれはわがすべて;<br/>なれをひたすらあいし, とわになれをほむ。<br/>',NULL,48755,7);
INSERT INTO stanza VALUES('J56','1','「おんなの子そん」なる 主を賛美します;<br/>処女より生まれて, かみ･ひととなる。<br/>ひとのせいしつ持ち, 十字架をとおして,<br/>へびのかしらくだき, けいかくじょう就す。<br/>',NULL,48756,1);
INSERT INTO stanza VALUES('J56','chorus','われら見たり, かみの栄こう;<br/>人せいの美とくに あらわれる!<br/>',NULL,48757,2);
INSERT INTO stanza VALUES('J56','2','血とにくをまとい, なれひとと成り,<br/>あく魔をほろぼし, 身代わりとなる。<br/>「イェス」また「インマヌエル」 なれはすくいぬし;<br/>わがためにとうとき すくいをじょう就す。<br/>',NULL,48758,3);
INSERT INTO stanza VALUES('J56','3','主は「最後のアダム」, また「第二のひと」;<br/>新そうぞうの元首, アダムにまさる。<br/>地じょうのせいかつで まことにひとの子;<br/>いま,てんにあっても じんせいを帯びる。<br/>',NULL,48759,4);
INSERT INTO stanza VALUES('J56','4','ちちの栄こう帯び, 主はさいりんす;<br/>あらわれるときも なれはなおひと。<br/>さばきの座において なれはなおもひと;<br/>えい遠にいたるまで 人せいをもたらす。<br/>',NULL,48760,5);
INSERT INTO stanza VALUES('J57','1','主よ,なれはひとの子, ひとのせいしつを持ち,<br/>にくと血のからだ着て, おとめより生まれたり。<br/>',NULL,48761,1);
INSERT INTO stanza VALUES('J57','2','奴れいのかたち取り, 苦なんのみちをあゆむ;<br/>じんせいのにがみなめ, くるしみ,すべて耐える。<br/>',NULL,48762,2);
INSERT INTO stanza VALUES('J57','3','飼い葉おけのなかで, 生まれ,まずしくそだち,<br/>だい工としてろう苦し, ざい人とし処刑される。<br/>',NULL,48763,3);
INSERT INTO stanza VALUES('J57','4','死より復かつし,なお, ひとのせいしつを持つ;<br/>神せいなかたちを着て, ひととしてしょうてんす。<br/>',NULL,48764,4);
INSERT INTO stanza VALUES('J57','5','御座にて支はいする えいこうのなかのひと;<br/>かみともにいますひと, かみのまんぞくのひと。<br/>',NULL,48765,5);
INSERT INTO stanza VALUES('J57','6','えいこうをともない さい臨するひとの子は,<br/>おうのおう,主の主,なお ひとのせいしつを持つ。<br/>',NULL,48766,6);
INSERT INTO stanza VALUES('J57','7','あたらしいてんと地で, なれは万ぶつのちゅう心;<br/>しんせいなる主はなお, とわにじんせいを持つ。<br/>',NULL,48767,7);
INSERT INTO stanza VALUES('J58','1','あいもたらす知恵, かみの知恵よ!<br/>さい後のアダム来て, すくいを成す。<br/>',NULL,48768,1);
INSERT INTO stanza VALUES('J58','2','アダムは失ぱいし, 堕らくしたが,<br/>なお,ひとのしょう利を, かみはのぞむ。<br/>',NULL,48769,2);
INSERT INTO stanza VALUES('J58','3','めぐみよりたかき かみのしゅつ現,<br/>かみの本しつをもて, ひとを聖とす。<br/>',NULL,48770,3);
INSERT INTO stanza VALUES('J58','4','かみはひとと成り, ひとに来られ,<br/>死のてきをほろぼし, 苦難を受ける。<br/>',NULL,48771,4);
INSERT INTO stanza VALUES('J58','5','ゲッセマネでうめき, 十字架で死ぬ;<br/>苦難にあまんじるみち, 主はおしえる。<br/>',NULL,48772,5);
INSERT INTO stanza VALUES('J58','6','主はかみ,またひと, わがうちにて,<br/>不思議なことを成し, 賛美をさせる。<br/>',NULL,48773,6);
INSERT INTO stanza VALUES('J59','1','かみの威厳,めぐみ, 栄光をともない,<br/>イェスのかおにふかく きざまれていた!<br/>かみのかたちなる 主を見るとき,<br/>こころは歓喜に満ち, 主をあがめる。<br/>',NULL,48774,1);
INSERT INTO stanza VALUES('J59','2','主,完ぜんなひとで, かみをあらわし,<br/>かみとひとのあいを ともにそなえる;<br/>生と死,復かつ,昇天, 経たかみ･ひと,<br/>地上でいやしいひとは, 万ゆうのかみ。<br/>',NULL,48775,2);
INSERT INTO stanza VALUES('J59','3','永えんのえい光に かがやく御かお!<br/>めぐみにて,われらは つくり変えらる!<br/>間もなくわれらは 同形化されて,<br/>ひとの子なるなれに えい光を見る。<br/>',NULL,48776,3);
INSERT INTO stanza VALUES('J60','1','あいする御名, イェスは主!<br/>万有超える名, イェスわが主!<br/>なれがあれば なにもいらぬ,<br/>嗣業を得たり, イェスわが主!<br/>',NULL,48777,1);
INSERT INTO stanza VALUES('J60','2','主はひとの子, イェスは主!<br/>わがため死ぬ, イェスわが主!<br/>主は真のあい, われの嗣ぎょう,<br/>すくい成就す, イェスわが主!<br/>',NULL,48778,2);
INSERT INTO stanza VALUES('J60','3','いのちを得る, イェスは主!<br/>しょう利を得る, イェスわが主!<br/>おそれ,うれい, 苦なんはなし,<br/>なれはちかし, イェスわが主!<br/>',NULL,48779,3);
INSERT INTO stanza VALUES('J60','4','主は再りんす, イェスは主!<br/>われら歓喜す, イェスわが主!<br/>なれを見つめ, 同けい化され,<br/>なれとひとつ, イェスわが主!<br/>',NULL,48780,4);
INSERT INTO stanza VALUES('J61','1','とうとき主の御名, そは「わたしはある」;<br/>わがひつ要すべて, 　 御名にある!<br/>',NULL,48781,1);
INSERT INTO stanza VALUES('J61','2','主は御子,またちち, そのれいとなりて,<br/>なが豊富すべてを 　 享受させる。<br/>',NULL,48782,2);
INSERT INTO stanza VALUES('J61','3','なれはまく屋,みや, み住まい,ひょうげん,<br/>なれにてかみを見, 豊富を受く。<br/>',NULL,48783,3);
INSERT INTO stanza VALUES('J61','4','かみの小ひつじは はなよめのために,<br/>つみ負い,きず受け, 安そくあとう。<br/>',NULL,48784,4);
INSERT INTO stanza VALUES('J61','5','主は,知恵またみち, 御むねを知らせて,<br/>めぐみを受けさせ, みちびけり。<br/>',NULL,48785,5);
INSERT INTO stanza VALUES('J61','6','なれは義,またせい, かみによろこばれ,<br/>われを義,せいとし, 平和得さす。<br/>',NULL,48786,6);
INSERT INTO stanza VALUES('J61','7','なれいのち,ひかり, 死とやみほろぼし,<br/>われ生かし,目あけ, かい放する。<br/>',NULL,48787,7);
INSERT INTO stanza VALUES('J61','8','復かつのたい能は, はかとよみ,やぶり,<br/>われをつよくして, 勝利あとう。<br/>',NULL,48788,8);
INSERT INTO stanza VALUES('J61','9','なれは生けるみず, 霊のかて,きょうきゅう,<br/>わがかわきいやし, 　 満たされる。<br/>',NULL,48789,9);
INSERT INTO stanza VALUES('J61','10','なれはぼく者,医者, いのち捨て,いやし,<br/>なぐさめ,みちびき, かえりみる。<br/>',NULL,48790,10);
INSERT INTO stanza VALUES('J61','11','主はさい司,われを 御かおへもたらす;<br/>なれはおう,われに 権威あとう。<br/>',NULL,48791,11);
INSERT INTO stanza VALUES('J61','12','主,あがない,のぞみ, なれに同けい化し,<br/>われを変ぼうさせ, 　 ひょう現さす。<br/>',NULL,48792,12);
INSERT INTO stanza VALUES('J61','13','かん喜,平あん,栄光, しん理,めぐみ，いわ,<br/>たいよう,やま,いえ, たて,ことば。<br/>',NULL,48793,13);
INSERT INTO stanza VALUES('J61','14','「わたしはある」名は えい遠,完ぜん,豊富!<br/>わがひつ要,満たし， あふれ出る。<br/>',NULL,48794,14);
INSERT INTO stanza VALUES('J62','1','あいする御名,イェス! 御まえに伏して,<br/>賛美,えい光,権威を, いま,なれにささぐ;<br/>わがくちはうたい, こころは感動す;<br/>ながたくえつした うるわしさゆえに。<br/>',NULL,48795,1);
INSERT INTO stanza VALUES('J62','2','あいする御名,イェス! 創せいのまえに,<br/>無限のあいしめし, すくいをじょう就す;<br/>このまことのあい とわにあらわれ,<br/>われらをあがない, たからとなしたもう。<br/>',NULL,48796,2);
INSERT INTO stanza VALUES('J62','3','あいする御名,イェス! いやしく生まれ,<br/>めぐみ,柔和に満ち, へりくだり,あゆむ;<br/>わが苦つう背負い, かなしみにない,<br/>わざわい,苦なんを, あいのゆえ受ける。<br/>',NULL,48797,3);
INSERT INTO stanza VALUES('J62','4','あいする御名,イェス! かみの小ひつじ,<br/>わがためさばかれ, 血ながし,きよめる;<br/>いまや天に座して, えいこう受ける,<br/>ハレルヤ,主の御名! 主はしょう利を得る。<br/>',NULL,48798,4);
INSERT INTO stanza VALUES('J63','1','かぐわしきイェスの名は, めぐみほどこす;<br/>すくわれしものはみな, この名をおもう。<br/>',NULL,48799,1);
INSERT INTO stanza VALUES('J63','2','かみはひととなり,来て, めぐみをしめす;<br/>天のいのち,持ち来たり, 地でせいかつす。<br/>',NULL,48800,2);
INSERT INTO stanza VALUES('J63','3','あいあらわすイェスの名, この名を呼べば,<br/>わざわいをしのばせて, 孤どくなぐさむ。<br/>',NULL,48801,3);
INSERT INTO stanza VALUES('J63','4','つみなきイェスはわれの つみをになえり;<br/>御身を捨て,わがうちに, めぐみほどこす。<br/>',NULL,48802,4);
INSERT INTO stanza VALUES('J63','5','なが名呼ぶわがこころ, 伏して礼拝する;<br/>ながあいにすくわれて, いまなれに帰す。<br/>',NULL,48803,5);
INSERT INTO stanza VALUES('J64','1','主よ,なが名は「イェス」, 　いともたえなる名,<br/>主はおとめより生まれて, ひとの子となられる。<br/>「エホバすくいぬし」を, 　 われは受け入れ;<br/>神せいないのち得て, 　 すくいを受ける。<br/>',NULL,48804,1);
INSERT INTO stanza VALUES('J64','2','なが名は「キリスト」, 　なれのつとめの名;<br/>主はあぶらをそそがれて, かみにさだめられる。<br/>なれはかみのメシア, 　 愛もて立てらる;<br/>えい光をあらわして, 　 みこころ成就す。<br/>',NULL,48805,2);
INSERT INTO stanza VALUES('J64','3','なれは「インマヌエル」, 　「かみともにいます」;<br/>めぐみにてかみとひとは, 調和し,とわにひとつ。<br/>かみ,にくにあらわれ, 　 真理,めぐみ満つ;<br/>かみのえいこう見て, 　 ほうまんを得る。<br/>',NULL,48806,3);
INSERT INTO stanza VALUES('J64','4','何とたえなる御名, 　ゆたかなる御名よ;<br/>なが名の価値とあまさを, 愛にてとわにまもる。<br/>えい光のキリストよ, 　 われら,はいする;<br/>インマヌエルなる主よ, 　 たからかにほむ!<br/>',NULL,48807,4);
INSERT INTO stanza VALUES('J65','1','イェス,おおいなる御名, われは依りたのむ;<br/>天に座すなれをほむ, 御名はわがしょう利。<br/>',NULL,48808,1);
INSERT INTO stanza VALUES('J65','2','イェス,わがすくいぬし, ひつ要,御名にあり;<br/>ひたすら御名を呼び, ながいのちを飲む。<br/>',NULL,48809,2);
INSERT INTO stanza VALUES('J65','3','イェス,えいこうの御名, 天地はなれをほむ;<br/>つみゆるされしひと, 御名の価値を知る。<br/>',NULL,48810,3);
INSERT INTO stanza VALUES('J65','4','イェスよ!とうとき御名, 病むときのくすり,<br/>たたかうときの武器, 御名により生きる。<br/>',NULL,48811,4);
INSERT INTO stanza VALUES('J66','1','あまくうるわしきイェスの名, せつなさをなぐさめる;<br/>こころよろこび満ちて, 　とうときこの名うたう。<br/>',NULL,48812,1);
INSERT INTO stanza VALUES('J66','chorus','たえなるかな,かみの御子は, わがすくいぬしとなり;<br/>　　わがため生まれ,死にて, 　血によりあがなう。<br/>',NULL,48813,2);
INSERT INTO stanza VALUES('J66','2','イェス,かみのかたちなりしが, 来たり,ひとの子となる;<br/>奴れいのかたちを取り, 　われを世継ぎとす。<br/>',NULL,48814,3);
INSERT INTO stanza VALUES('J66','3','イェス,真理,いのち,ひかり,みち, いまわがこころでおう,<br/>また主となりわれらを, 　みちびき,なぐさむ。<br/>',NULL,48815,4);
INSERT INTO stanza VALUES('J66','4','奇しきすくいぬしは絶えず わがこころ満たされる,<br/>わずらい,うれいを消し, 　えい遠にしたしむ。<br/>',NULL,48816,5);
INSERT INTO stanza VALUES('J66','5','間もなくすくいぬしは来て, われらと同ざいされる;<br/>われらを変ぼうさせて, 　永遠にあんそくす。<br/>',NULL,48817,6);
INSERT INTO stanza VALUES('J66','chorus','よろこばしきかな,主イェスは, えい遠にわがえいこう;<br/>えい光の御名,そはイェス, 　永遠にほめたとう。<br/>',NULL,48818,7);
INSERT INTO stanza VALUES('J67','1','なんとあまき主イェスの御名よ, てん地にたぐいなし!<br/>えい光,捨てて,世に来たるとき, かみより受けし御名。<br/>',NULL,48819,1);
INSERT INTO stanza VALUES('J67','chorus','われらはあいし,うたう, かみの子,主イェス;<br/>「イェス」にまさるとうとき御名は, てんにも地にもなし。<br/>',NULL,48820,2);
INSERT INTO stanza VALUES('J67','2','ひとがなれを木に掛けたとき, この名も木に掛けた;<br/>すべてひとは,かみのふかみの こころをかん賞する。<br/>',NULL,48821,3);
INSERT INTO stanza VALUES('J67','3','なれはたかくのぼり,座に着き, 主,キリストとされる,<br/>せん千,まん万のくちはたたえ, ながさいりんを待つ!<br/>',NULL,48822,4);
INSERT INTO stanza VALUES('J67','4','イェスよ,たぐいなき御名により, めぐみ増しくわわる;<br/>きのう,きょうも,変わることなく, なれはとわにいたる!<br/>',NULL,48823,5);
INSERT INTO stanza VALUES('J68','1','小ひつじほふられ, 引き上げらる;<br/>栄光のすくいぬし, イェス･キリスト。<br/>',NULL,48824,1);
INSERT INTO stanza VALUES('J68','chorus','とうとき名,ほめたたえ, えい光御名に帰す;<br/>とうとき名,ほめたたえ, えい光御名に帰す;<br/>ハレルヤ!ハレルヤ! えい光御名に帰す;<br/>ハレルヤ!ハレルヤ! えい光御名に帰す。<br/>',NULL,48825,2);
INSERT INTO stanza VALUES('J68','2','すべてを超える名, イェスは受ける;<br/>天地はこえ合わせ, 主イェスと呼ぶ。<br/>',NULL,48826,3);
INSERT INTO stanza VALUES('J68','3','天使,天軍,ばん有は, ひれ伏し拝し,<br/>主キリストあがめ, 小ひつじたとう。<br/>',NULL,48827,4);
INSERT INTO stanza VALUES('J68','4','つみびとめぐみ得, かん声上げる;<br/>主，血にてあがない, しゅくふくあとう。<br/>',NULL,48828,5);
INSERT INTO stanza VALUES('J68','5','権威,豊富,知恵,尊貴, えい光,王権が,<br/>主なる小ひつじに, えい遠にあれ!<br/>',NULL,48829,6);
INSERT INTO stanza VALUES('J69','1','とうときイェスの名を, 聖徒らたとう:<br/>あく魔,この名聞き, おそれて逃げる。<br/>',NULL,48830,1);
INSERT INTO stanza VALUES('J69','2','したわしいイェスの名, 安そくあとう;<br/>つみびとおそれず, この名をあいす。<br/>',NULL,48831,2);
INSERT INTO stanza VALUES('J69','3','イェスは十字架にて, サタンくだき,<br/>よわさ飲み尽くし, いのちを得さす。<br/>',NULL,48832,3);
INSERT INTO stanza VALUES('J69','4','世びとよ,あじわえ, 主のめぐみを!<br/>みうでに飛び込み, あんそくを得よ。<br/>',NULL,48833,4);
INSERT INTO stanza VALUES('J69','5','信らいすべき御名, とうとき御名は;<br/>代々にいたるまで, われらのあかし。<br/>',NULL,48834,5);
INSERT INTO stanza VALUES('J70','1','イェスの名はあまし, 音がくのようたとう,<br/>豊まんでかんぜん, とうときイェスの名。<br/>',NULL,48835,1);
INSERT INTO stanza VALUES('J70','chorus','イェス!あまき御名, イェス!変わりなし;<br/>イェス！せい徒らは その価値をほむ。<br/>',NULL,48836,2);
INSERT INTO stanza VALUES('J70','2','われを愛するイェス, わが苦難理かいし,<br/>ともに分かち合う; わがあいす御名。<br/>',NULL,48837,3);
INSERT INTO stanza VALUES('J70','3','御名を聞くものを, 魅りょうし,歓喜させ,<br/>なみだぬぐい去る; いとあまき御名。<br/>',NULL,48838,4);
INSERT INTO stanza VALUES('J70','4','この名のあまさは かたり尽くせない;<br/>とわにほめうたう, わがイェスの名を。<br/>',NULL,48839,5);
INSERT INTO stanza VALUES('J71','1','主はふっかつし, 死人のはつ穂;<br/>たかく上げられて, 栄こうのげん首。<br/>われらめぐみ受け, あいまじわれば,<br/>なれといちとなる, 何というえい光。<br/>',NULL,48840,1);
INSERT INTO stanza VALUES('J71','2','なれは万有の主, さい高けん威;<br/>「ひと」として昇天し, さい高の名持つ!<br/>最高のあい,ちから, ゴルゴタでしめし,<br/>苦つうあんこくに, かん全にしょう利。<br/>',NULL,48841,2);
INSERT INTO stanza VALUES('J71','3','万ぶつはなれを, とうとび,みとめ,<br/>なが名を賛美して, なれを歓げいす。<br/>いまやながあいを, われらあじわい,<br/>こころは満たされ, さん美はやまず。<br/>',NULL,48842,3);
INSERT INTO stanza VALUES('J71','4','御名はご自身を あきらかにし,<br/>ながあいはふかく, えい遠に絶えず。<br/>われらいちとなり, 歓喜し来たりて,<br/>えい遠のえいこう, あいをほめたとう。<br/>',NULL,48843,4);
INSERT INTO stanza VALUES('J72','1','主のみなもとは, 永えんのはじめ!<br/>なれ,永遠のちち, ありてあるもの。<br/>',NULL,48844,1);
INSERT INTO stanza VALUES('J72','2','ひとの世に来て, なお永遠のかみ!<br/>かみとひとしく, かん全また無限!<br/>',NULL,48845,2);
INSERT INTO stanza VALUES('J72','3','創せいのまえに, かみの起源,持つ!<br/>なれよりまえの ものはあり得じ!<br/>',NULL,48846,3);
INSERT INTO stanza VALUES('J72','4','とわに変わらず, とわにふるびず!<br/>なれよりあとの ものはあり得じ!<br/>',NULL,48847,4);
INSERT INTO stanza VALUES('J72','5','ちちと相違なく, かみとどうよう!<br/>さい初でさい後, アルファでオメガ!<br/>',NULL,48848,5);
INSERT INTO stanza VALUES('J72','6','なれの永えんと, かん全を賛美す!<br/>豊まん無げんを, われら鑑賞する!<br/>',NULL,48849,6);
INSERT INTO stanza VALUES('J73','1','受けませ,わが詩歌, こえよわくとも;<br/>すくいぬしなれの めぐみを述べる。<br/>',NULL,48850,1);
INSERT INTO stanza VALUES('J73','2','えい光,豊富を捨て, まずしくなれり;<br/>聖徒をしゅくふくし, 富ませるために。<br/>',NULL,48851,2);
INSERT INTO stanza VALUES('J73','3','なにゆえになれは てんをはなれて,<br/>この世に来たりて 死にたまいしや?<br/>',NULL,48852,3);
INSERT INTO stanza VALUES('J73','4','なんたるながあい! ただわがために,<br/>天のえいこう捨て, 苦なんあじわう。<br/>',NULL,48853,4);
INSERT INTO stanza VALUES('J73','5','ながあいおもえば, よろこびあれど,<br/>なれにむくい得ず, ふかくはじ入る。<br/>',NULL,48854,5);
INSERT INTO stanza VALUES('J73','6','かの日,待ちのぞむ; さまたげ解かれ,<br/>えいこうにはいり, ひたすらつかえん。<br/>',NULL,48855,6);
INSERT INTO stanza VALUES('J73','7','われら待ちのぞみ, はげましを受く;<br/>なれに会う日まで, ながために生く。<br/>',NULL,48856,7);
INSERT INTO stanza VALUES('J74','1','すくいぬし生まれ, 天使らたたえる;<br/>「かみにはえいこう, 世びとにへい和」。<br/>起きよ,天のこえに 呼おうし賛美せよ;<br/>てん地かん喜す, キリストは生まる。<br/>ダビデのまちに すくいぬし生まる。<br/>',NULL,48857,1);
INSERT INTO stanza VALUES('J74','2','主はかみのかたち, かみのえいこう,<br/>てんよりくだりて, 処女より生まる;<br/>かみが受にくする, なんというおく義,<br/>なれひとと成り, ひととともに住む。<br/>イェスはインマヌエル, われらと住み合う。<br/>',NULL,48858,2);
INSERT INTO stanza VALUES('J74','3','見よ,へい和のおう, 義なるたいよう!<br/>いのちとひかりを, ひとにもたらす;<br/>かれは栄こうを捨て, ひととして生まれ。<br/>ひとをすくいて, 死をまぬがれさせ,<br/>さいせい得させ, たかく引き上げる。<br/>',NULL,48859,3);
INSERT INTO stanza VALUES('J74','4','ばんこくの「あい慕」, ばん民の「のぞみ」;<br/>主よ,わがこころに み住まいつくり,<br/>アダムのふるさを, すべてのぞき去り,<br/>さい後のアダム, いのちのれいにて,<br/>なれのかたちに えいこう化しませ。<br/>',NULL,48860,4);
INSERT INTO stanza VALUES('J74','note','　４「あい慕」は慕う方,キリストを指す(ハガイ2:7)。<br/>　「のぞみ」は,キリストが万民の望みであることを指す。<br/>',NULL,48861,5);
INSERT INTO stanza VALUES('J75','1','すくいぬし, えいこう捨て,<br/>世に生まれた, その名はイェス,<br/>かなしみの ひととなって,<br/>つねにくるしみ受ける。<br/>',NULL,48862,1);
INSERT INTO stanza VALUES('J75','chorus','主よ,なれを 愛し,はいす!<br/>主はひかり, 主はいき,<br/>偉だいなる すくいぬし,<br/>かみの豊満 もたらす。<br/>',NULL,48863,2);
INSERT INTO stanza VALUES('J75','2','ご自しんを ひくくされて,<br/>くるしみ受け, さげすまれた;<br/>ほろびゆく われのために,<br/>主はあいをもてすくう。<br/>',NULL,48864,3);
INSERT INTO stanza VALUES('J75','3','創ぞうぬし ひとと成って,<br/>ごけいかくを あらわされた;<br/>かみとひと ひとつとなり,<br/>われ,かみのすべて得る。<br/>',NULL,48865,4);
INSERT INTO stanza VALUES('J76','1','主よ,なれの柔和さ, かがやいてうるわしい!<br/>なれは孤どくなみちを, あいにありあゆむ。<br/>',NULL,48866,1);
INSERT INTO stanza VALUES('J76','2','なれは真のひかり, やさしくまたこまやか；<br/>世のくるしみすべてを, なれは耐えしのぶ。<br/>',NULL,48867,2);
INSERT INTO stanza VALUES('J76','3','そしられ,苦難受け, なれはなお,ふくじゅうす;<br/>へりくだりとにゅう和は， なんとうつくしい。<br/>',NULL,48868,3);
INSERT INTO stanza VALUES('J76','4','あまんじて死を受け, しゅうじんを解きはなつ;<br/>ながあいはあらわされ, あわれみ,あふれる。<br/>',NULL,48869,4);
INSERT INTO stanza VALUES('J76','5','ああ,すばらしき主よ, なれへとかたちづくり,<br/>なれのようにひくくし, ともにあゆませよ。<br/>',NULL,48870,5);
INSERT INTO stanza VALUES('J77','1','いとたかき栄光のかみ, にくたいにあり来たり,<br/>いやしきひととなれり, 　 主よ,なれおもう!<br/>',NULL,48871,1);
INSERT INTO stanza VALUES('J77','2','しんせいを脱ぎ捨てて, にくのまく屋に住まう,<br/>いやしきひととなれり, 主よ,なれおもう!<br/>',NULL,48872,2);
INSERT INTO stanza VALUES('J77','3','かわきし地より出た根, 多くのくるしみを受け,<br/>きらわれ,あなどられる, 主よ,なれおもう!<br/>',NULL,48873,3);
INSERT INTO stanza VALUES('J77','4','ながこころはにゅう和で, すすみてくるしみ受く,<br/>なんらつぶやきもなし, 主よ,なれおもう!<br/>',NULL,48874,4);
INSERT INTO stanza VALUES('J77','5','おん和でかん美なひと, きんこうが取れ,かん全,<br/>こくもつのささげもの, 主よ,なれおもう!<br/>',NULL,48875,5);
INSERT INTO stanza VALUES('J77','6','かみの御むねおもんじ, サタンの虚偽をしりぞけ,<br/>いかにちゅうじつなひと, 主よ,なれおもう!<br/>',NULL,48876,6);
INSERT INTO stanza VALUES('J77','7','かみの御むねにじゅう順, 十字架の死にいたるも,<br/>死のくるしみを受ける, 主よ,なれおもう!<br/>',NULL,48877,7);
INSERT INTO stanza VALUES('J77','8','ちちはなれをたかくし, えいこう,そん貴あとう,<br/>ばんぶつはひれ伏して, なれをはいす。<br/>',NULL,48878,8);
INSERT INTO stanza VALUES('J78','1','主の地じょうでのあゆみ, 慈あい,美に満つ!<br/>なれの非凡な生がいに, われきょう嘆する!<br/>',NULL,48879,1);
INSERT INTO stanza VALUES('J78','2','なれの苦難はあらわす, 耐えしのぶあい!<br/>死の苦つうはあらわす, しんせいなあい!<br/>',NULL,48880,2);
INSERT INTO stanza VALUES('J78','3','きず受け,おも荷を負い, かなしみに満つ。<br/>されどなれのくちには, つぶやきはなし。<br/>',NULL,48881,3);
INSERT INTO stanza VALUES('J78','4','にくまれ,あなどられて, うら切られるも,<br/>なれはなおもゆるして, あいしつづける。<br/>',NULL,48882,4);
INSERT INTO stanza VALUES('J78','5','主よ,なれのしょうがいは, あまくこまやか!<br/>かんぜんで均こう取れ, かみ,ひと享受す!<br/>',NULL,48883,5);
INSERT INTO stanza VALUES('J79','1','主よ,なれはひとにたいし, あいとめぐみ持つ;<br/>かみには忠しんをもて, ひたすらつかえる。<br/>',NULL,48884,1);
INSERT INTO stanza VALUES('J79','2','ひとにうら切られ,死ぬも, あいは死にまさる;<br/>わきばらよりいでし血, われをすくわれる。<br/>',NULL,48885,2);
INSERT INTO stanza VALUES('J79','3','なれは苦難のさなかにも, なお善をおこない,<br/>ながみちの困なんにも, つぶやくことなし。<br/>',NULL,48886,3);
INSERT INTO stanza VALUES('J79','4','なれはまことにちゅうしん, くらき世のひかり;<br/>ちちの御むね,よろこび, ひたすらしたがう。<br/>',NULL,48887,4);
INSERT INTO stanza VALUES('J79','5','サタンのはかりごとにも, そんしつ,苦難にも,<br/>どうじることなくただ, 十字架のみち取る。<br/>',NULL,48888,5);
INSERT INTO stanza VALUES('J79','6','主よ,ながひくき姿せいを, われはまなびたし;<br/>なれに似るものとなり, あんそくを得たし。<br/>',NULL,48889,6);
INSERT INTO stanza VALUES('J80','1','いま,われひれ伏す, いのちの王よ,<br/>なれのきずおぼえ, 栄こうを帰す。<br/>',NULL,48890,1);
INSERT INTO stanza VALUES('J80','chorus','ゲツセマネわすれず, ながうれい,わすれず,<br/>カルバリへのみち, われ,おぼえる。<br/>',NULL,48891,2);
INSERT INTO stanza VALUES('J80','2','ほうむられしなれを, われはしたう;<br/>天使らにまもられ, なれ,やすらぐ。<br/>',NULL,48892,3);
INSERT INTO stanza VALUES('J80','3','マリアにならいて, 香りょうささぐ;<br/>からのはかしめす やくそく見る。<br/>',NULL,48893,4);
INSERT INTO stanza VALUES('J80','4','日々なが十字架を, あまんじて負う;<br/>苦はいあじわうを, われはねがう。<br/>',NULL,48894,5);
INSERT INTO stanza VALUES('J80','5','すべてのひと得る, ながねがいに;<br/>われらもあずかり, カルバリかたる。<br/>',NULL,48895,6);
INSERT INTO stanza VALUES('J81','1','えい遠のいのちの みなもとの主は,<br/>はじと死を受けて, よみに打ち勝つ。<br/>主はくるしみ受け, すくいをじょう就す;<br/>重：せん万のさん美を えいこうの主に!<br/>',NULL,48896,1);
INSERT INTO stanza VALUES('J81','2','御子はあざけられ, 打たれ,きず受く;<br/>いばらのかんむりを わがためかぶる;<br/>つみのくさり解き, われらをすくわる。<br/>重：せん万のさん美を えいこうの主に!<br/>',NULL,48897,2);
INSERT INTO stanza VALUES('J81','3','ひとのそしり受け, ただ耐えしのぶ;<br/>死の苦つうに耐え, すくい,成し遂ぐ。<br/>死ぬため来た主に ひとみなおどろく;<br/>重：せん万のさん美を えいこうの主に!<br/>',NULL,48898,3);
INSERT INTO stanza VALUES('J81','4','われらのため死に, われらを生かす;<br/>われら,霊のなかで, れい拝し,あがむ。<br/>主,かなしみにない, しゅくふくあたえる。<br/>重：われらのさん美は, えい遠に絶えず。<br/>',NULL,48899,4);
INSERT INTO stanza VALUES('J82','1','試れん,くるしみ, あざけり受け,<br/>いばらのきずに 満ちたこうべ,<br/>いま栄光を受け かがやき満つ;<br/>あの日,十字架で 死のきず受く。<br/>',NULL,48900,1);
INSERT INTO stanza VALUES('J82','2','ちちのこころを 満たす御かお,<br/>されどつみびと つばきをする。<br/>主はつみのため くるしみ受け,<br/>負さいをすべて せいさんする。<br/>',NULL,48901,2);
INSERT INTO stanza VALUES('J82','3','なれの無じつと 苦痛おもうとき,<br/>よろこび満ちて, かん,きわまる!<br/>なれの十字架を われらおもい,<br/>いのち捨てても 損をえきとす。<br/>',NULL,48902,3);
INSERT INTO stanza VALUES('J82','4','ながくるしみの ふかさ知らず,<br/>だれもなが恩に むくいられず。<br/>いまより日ごと カルバリおぼえ,<br/>とわのえい光に われらいたる。<br/>',NULL,48903,4);
INSERT INTO stanza VALUES('J83','1','真夜なかにひとり, すくいぬしいのる;<br/>ゲツセマネのそので, すくいぬしいのる。<br/>',NULL,48904,1);
INSERT INTO stanza VALUES('J83','2','ただひとりになり, すくいぬしうめく;<br/>あいする弟子さえ, かれをかえりみず。<br/>',NULL,48905,2);
INSERT INTO stanza VALUES('J83','3','血のあせをながし, すくいぬしいのる;<br/>天使はちからづけ, かみは主を捨てず。<br/>',NULL,48906,3);
INSERT INTO stanza VALUES('J83','4','ちちのみこころは, 苦はい飲むことと,<br/>主はふかく知りて, つみをにない死ぬ。<br/>',NULL,48907,4);
INSERT INTO stanza VALUES('J84','1','ああ,主はこうべを垂れ, わがつみ負う!<br/>ざい人の地位に立ち, つみをになう。<br/>血ながし,あがない, かいほうする。<br/>',NULL,48908,1);
INSERT INTO stanza VALUES('J84','2','わがさかずきは,死と のろいに満つ;<br/>されど,わがにがみを, なれは飲まる。<br/>なれ,苦はいを飲み, しゅくふくあとう。<br/>',NULL,48909,2);
INSERT INTO stanza VALUES('J84','3','かみはつえを上げて, 主を打たれる!<br/>その受けしきずにて, われ,いやさる;<br/>なれのとうとき血は, あがない成す。<br/>',NULL,48910,3);
INSERT INTO stanza VALUES('J84','4','げき怒のなみが寄せ, なれにせまる!<br/>なれはそれを受けて, われ,安そくす。<br/>主はわがため死に, 平安得させる。<br/>',NULL,48911,4);
INSERT INTO stanza VALUES('J84','5','かみはつるぎに命じ, 主に向かわす!<br/>その残こくなやいば, 主の血ながす;<br/>かみの要きゅうみな, 満ち,やわらぐ。<br/>',NULL,48912,5);
INSERT INTO stanza VALUES('J84','6','主はわがため死にて, われらも死ぬ;<br/>主は復かつしていま, わがうち生く。<br/>われら完せいされ, えいこう得る。<br/>',NULL,48913,6);
INSERT INTO stanza VALUES('J85','1','主の十字架をおもい, 　主の苦難をおもうとき,<br/>自分自しんをわすれ, 　たかぶりをいやしめる。<br/>',NULL,48914,1);
INSERT INTO stanza VALUES('J85','2','主の十字架のほかに 　ほこるものないように;<br/>とうとびしえい華を 　捨てること,われねがう。<br/>',NULL,48915,2);
INSERT INTO stanza VALUES('J85','3','見よ,主のぜん身より, 　うれい,あい,血はながれる!<br/>いばらで編み上げた 　かんむりをなれは受ける。<br/>',NULL,48916,3);
INSERT INTO stanza VALUES('J85','4','みずと血にひたされ, 　ころもはあかく染まる;<br/>ゆえに世を断ち切り, 　世はわれにたいし,死ぬ。<br/>',NULL,48917,4);
INSERT INTO stanza VALUES('J85','5','宇ちゅうすべてをもて 　つかえても,なお恥じる;<br/>なれのふかきあいは, 　わがいのちをもとめる。<br/>',NULL,48918,5);
INSERT INTO stanza VALUES('J86','1','あなどり,はじ受け, 十字架を背負う;<br/>主,ほふられるため, もくしてすすむ。<br/>',NULL,48919,1);
INSERT INTO stanza VALUES('J86','chorus','愛のひろさ,ながさ, たかさ,ふかさよ!<br/>わが全しょうがいを なれにささげる。<br/>',NULL,48920,2);
INSERT INTO stanza VALUES('J86','2','木にくぎづけられ, やりでさされて,<br/>ちちにも捨てられ, 身と霊くるしむ。<br/>',NULL,48921,3);
INSERT INTO stanza VALUES('J86','3','十字架より下りず, たすけもとめず,<br/>ひとの手にゆだね, かみ,満ぞくさす。<br/>',NULL,48922,4);
INSERT INTO stanza VALUES('J86','4','きずなき小ひつじ, 死にわたされた;<br/>みやのまくは裂け, みち,ひらかれた。<br/>',NULL,48923,5);
INSERT INTO stanza VALUES('J87','1','主のあゆみしみち, 　苦なんに満ちる;<br/>悲さんな死を遂げ, 　ながあいしめす。<br/>',NULL,48924,1);
INSERT INTO stanza VALUES('J87','chorus','賛美せよ,賛美せよ, 　　えいこうの主を;<br/>すくいぬしは死に, 　われのために生きる。<br/>',NULL,48925,2);
INSERT INTO stanza VALUES('J87','2','主の受けし苦つう, 　だれ知り得るや;<br/>いわれなきじゅうりん, 　だれ知り得るや!<br/>',NULL,48926,3);
INSERT INTO stanza VALUES('J87','3','十字架につくとき, 　みな主をはなれ,<br/>主,つみびとのため, 　むちに打たれる。<br/>',NULL,48927,4);
INSERT INTO stanza VALUES('J87','4','なれはつみの距離, 　そのとき,はかる;<br/>かみに捨てられた 　ながあいを知る。<br/>',NULL,48928,5);
INSERT INTO stanza VALUES('J87','note','（「つみの距離」とは激怒,のろい,悲しみを指す）<br/>',NULL,48929,6);
INSERT INTO stanza VALUES('J88','1','ゲツセマネのそので イェスはいのり,<br/>血のあせながして, いたくさけぶ。<br/>',NULL,48930,1);
INSERT INTO stanza VALUES('J88','chorus','わがため! 十字架につき,<br/>ろうのようこころを 溶かして,あがない成す。<br/>',NULL,48931,2);
INSERT INTO stanza VALUES('J88','2','わがため,主ひとり, 捕ばくされる,<br/>ピラトのまえにて さばき受ける。<br/>',NULL,48932,3);
INSERT INTO stanza VALUES('J88','3','わがため,主ひとり, むち打たれる,<br/>いばらのかんむりで あなどられる。<br/>',NULL,48933,4);
INSERT INTO stanza VALUES('J88','4','わがため,主ひとり, ゴルゴタで死ぬ,<br/>刺されて,血ながし, つみあがなう。<br/>',NULL,48934,5);
INSERT INTO stanza VALUES('J88','5','わがため,主ひとり, 苦はいを飲む,<br/>われらにめぐみを 得させるため。<br/>',NULL,48935,6);
INSERT INTO stanza VALUES('J88','6','死のとき,主さけぶ, 「完りょうした!」と,<br/>この感動,感げきを, とわにたもつ。<br/>',NULL,48936,7);
INSERT INTO stanza VALUES('J89','1','主はあいゆえ,わがため, はじと死を受ける!<br/>つみ,サタンの権せいに, しょう利得させる。<br/>',NULL,48937,1);
INSERT INTO stanza VALUES('J89','2','ひとのつみ,サタンの嘲笑, またかみのげき怒;<br/>主の負われたおも荷の 何とおもきこと!<br/>',NULL,48938,2);
INSERT INTO stanza VALUES('J89','3','主をかこむなみかぜは, えい遠にしずまる;<br/>主は超えつした名,受け, われらは歓喜す。<br/>',NULL,48939,3);
INSERT INTO stanza VALUES('J89','4','間もなく引き上げられ, あたらしいうた,うたう;<br/>されど,いまそのうたを われらはうたう。<br/>',NULL,48940,4);
INSERT INTO stanza VALUES('J90','1','賛美,賛美,賛美, すくいぬし賛美す;<br/>　無限の感げき, 主はご自身捨てる;<br/>見よ,かみの子,ゴルゴタの主を, わがため十字架につく。<br/>',NULL,48941,1);
INSERT INTO stanza VALUES('J90','2','どんなあいにも, 主のあいはまさる;<br/>　つみびとらは とわに主たたえる;<br/>見よ,かみの子,ゴルゴタの主を, わがため十字架につく。<br/>',NULL,48942,2);
INSERT INTO stanza VALUES('J90','3','つみゆるされ, あく魔は失ぱいす;<br/>　主のあいより, だれ引きはなすや？<br/>見よ,かみの子,ゴルゴタの主を, わがため十字架につく。<br/>',NULL,48943,3);
INSERT INTO stanza VALUES('J91','1','自分をすくわず, 十字架で死に,<br/>めぐみは来て つみびとすくう。<br/>御子は血をながし, めぐみの門ひらき,<br/>　つみびときよめられる。<br/>',NULL,48944,1);
INSERT INTO stanza VALUES('J91','2','自分をすくわず, 義を満たして,<br/>つみのために 主は死なれる。<br/>それゆえ寛大にも, つみはゆるされて,<br/>　負さいはみな過ぎ去る。<br/>',NULL,48945,2);
INSERT INTO stanza VALUES('J91','3','自分をすくわず, 身代わりとし,<br/>つみをにない, 主は死なれる。<br/>十字架で血ながし, つみすべてにない,<br/>　すべてのつみ消し去る。<br/>',NULL,48946,3);
INSERT INTO stanza VALUES('J91','4','自分をすくわぬ, 何というあい！<br/>自分を捨てる, あいのきわみ！<br/>このあいにわれら 感げきし賛美する。<br/>　こころあつく賛美する。<br/>',NULL,48947,4);
INSERT INTO stanza VALUES('J92','1','この孤どくなとき！ 　四ほうはやみ！<br/>かみのひとり子は, ひとと成って死ぬ,<br/>　何といたましい!<br/>主,十字架にかかる！ 主,血をながされる！<br/>',NULL,48948,1);
INSERT INTO stanza VALUES('J92','2','かみ･ひとの生死は, 　なんと不思議！<br/>永遠から永遠まで, 過去もしょうらいも,<br/>　なれ,賛美受く！<br/>主よ,なが十字架は, とわにわが安そく！<br/>',NULL,48949,2);
INSERT INTO stanza VALUES('J92','3','十字架を見るとき, 　感動おぼえる;<br/>愛の化身は死んだ！ このくるしみ見て,<br/>　われ,うれえる！<br/>ながさけびを聞く: 「エリ,レマ,サバクタニ！」<br/>',NULL,48950,3);
INSERT INTO stanza VALUES('J92','4','われらが受くべき 　げき怒と死を,<br/>義なるかみは主に, すべてになわせて,<br/>　かれをころす;<br/>われら主とともに 十字架じょうで死ぬ。<br/>',NULL,48951,4);
INSERT INTO stanza VALUES('J92','5','われら主とともに 　ふっかつして,<br/>からだのなかにて, かみのものとなり,<br/>　しゅくふく得る;<br/>死ぬべきわれらは, いまや「アバ」と呼ぶ。<br/>',NULL,48952,5);
INSERT INTO stanza VALUES('J93','1','ああ,主は血をながし, 　いのちを捨てる;<br/>むしのようなわれの 犠せいとなられる。<br/>',NULL,48953,1);
INSERT INTO stanza VALUES('J93','2','十字架上のなげきは, わがつみのため;<br/>あい,めぐみは無限！ あわれみはゆたか！<br/>',NULL,48954,2);
INSERT INTO stanza VALUES('J93','3','たいよう,くらくなり, えいこうかくす;<br/>つみびとのために, 主の死なれしとき。<br/>',NULL,48955,3);
INSERT INTO stanza VALUES('J93','4','主の十字架,見るとき, 恥じて,かお覆う;<br/>こころは感げきし, 自己をひくくする。<br/>',NULL,48956,4);
INSERT INTO stanza VALUES('J93','5','このあいの負い目に だれむくい得よう？<br/>主よ,われらここに, ただひれ伏すのみ。<br/>',NULL,48957,5);
INSERT INTO stanza VALUES('J94','1','主よ,ながあがない, いかに奇しき,<br/>だれかおもいしや, だれか見しや？<br/>なれはおく義,神聖, じん知を超ゆ！<br/>ああ,ながあがない, いかに奇しき！<br/>',NULL,48958,1);
INSERT INTO stanza VALUES('J94','chorus','何という不思議！ ながあがないは;<br/>何というえい光！ 新そうぞうは。<br/>',NULL,48959,2);
INSERT INTO stanza VALUES('J94','2','わがため十字架で なれは裂かれ,<br/>みずと血をながし, いのち分与す。<br/>なが血にあらわれ, 受け入れらる;<br/>われらさい生され, なれとひとつ。<br/>',NULL,48960,3);
INSERT INTO stanza VALUES('J94','3','ひとつぶのむぎは 実をむすびて,<br/>われら多くの実は, からだとなる。<br/>なれをいのちとし, 豊まんとなる;<br/>なれはわれらにて, あらわされる。<br/>',NULL,48961,4);
INSERT INTO stanza VALUES('J94','4','からだはながいえ, なれの住まい;<br/>われらなが安そく, ながはいぐう。<br/>ながこころ満ちて, われらといち;<br/>われらながすべて, 受けて享受す。<br/>',NULL,48962,5);
INSERT INTO stanza VALUES('J94','5','われらパンさきで しるしを見て,<br/>満ち満ちる感謝と, 賛美,禁じ得じ！<br/>われらながからだ 住まい,はい偶,<br/>この感げきのゆえ, れいはいする。<br/>',NULL,48963,6);
INSERT INTO stanza VALUES('J95','1','かみは無げんのあいもて, あいする御子をつかわす;<br/>御子は来て十字架で死に, われらをいえにもたらす。<br/>',NULL,48964,1);
INSERT INTO stanza VALUES('J95','chorus','賛美す! 賛美す! みわざ成就す！<br/>感謝す! 感謝す! しんのめぐみ！<br/>すくいぬしに栄こう帰し, われらはうたい,ほめたとう。<br/>',NULL,48965,2);
INSERT INTO stanza VALUES('J95','2','御座のようきゅうはすべて, イェスの血ゆえに満たされ,<br/>御子,義なるさばきを負い, かみのこころ満たされる。<br/>',NULL,48966,3);
INSERT INTO stanza VALUES('J95','3','主はえい光の御座に着き, イェスの名はたかくされる,<br/>すくいぬしはかんむり受け, せい徒らともにほめうたう。<br/>',NULL,48967,4);
INSERT INTO stanza VALUES('J96','1','かみのキリスト, つみびとすくう,<br/>「かなしみのひと」, ハレルヤ！キリスト！<br/>',NULL,48968,1);
INSERT INTO stanza VALUES('J96','2','あなどりを受け, つみさだめ受け,<br/>いのちあたえる, ハレルヤ！キリスト！<br/>',NULL,48969,2);
INSERT INTO stanza VALUES('J96','3','主はつみのない かみの小ひつじ,<br/>すくいじょう就す！ ハレルヤ！キリスト！<br/>',NULL,48970,3);
INSERT INTO stanza VALUES('J96','4','死より復かつし, あがない成就し,<br/>御座に座したもう。 ハレルヤ！キリスト！<br/>',NULL,48971,4);
INSERT INTO stanza VALUES('J96','5','主はさいりんし, たずさえ上げる;<br/>われらほめうたう: ハレルヤ！キリスト<br/>',NULL,48972,5);
INSERT INTO stanza VALUES('J97','1','カルバリのおかで, イェスは十字架にて,<br/>あがないじょう就し, 新契やくを立てる。<br/>',NULL,48973,1);
INSERT INTO stanza VALUES('J97','chorus','悲さんなカルバリ！ イェスは血をながす;<br/>大いなるカルバリ！ 主わがために死ぬ。<br/>',NULL,48974,2);
INSERT INTO stanza VALUES('J97','2','垂れまく裂かれて, みちはひらかれる;<br/>かみへとちかづき, 無限のめぐみ受く。<br/>',NULL,48975,3);
INSERT INTO stanza VALUES('J97','3','主イェスよ,なにゆえ わがため,くるしみ,<br/>十字架上で,かみの いかりを受けしや？<br/>',NULL,48976,4);
INSERT INTO stanza VALUES('J98','1','何と貴重な賛美のこえ！ いまは聖徒らさけぶとき;<br/>われら,もくするならば, 　 いしがさけび出す。<br/>',NULL,48977,1);
INSERT INTO stanza VALUES('J98','2','血にて買われたゆえに, われらこえたかくさけぶ;<br/>主,わがため死あじわい, ちから尽くされる。<br/>',NULL,48978,2);
INSERT INTO stanza VALUES('J98','3','このとくべつなうたを, すくわれたもののみうたう;<br/>その意義を知らぬもの, うたうことできず。<br/>',NULL,48979,3);
INSERT INTO stanza VALUES('J98','4','あわれみは主の血ゆえ, ながれるをてん使,知るも,<br/>血のきよめる効き目を, われらのよう,知らず。<br/>',NULL,48980,4);
INSERT INTO stanza VALUES('J98','5','天使ら,唯いつのかみを, 賛美し,礼はいし,かたるが,<br/>われら,人性持つかみを, 歓喜してさん美す。<br/>',NULL,48981,5);
INSERT INTO stanza VALUES('J98','6','主よ,われらさん美する, なれは血ながし,死なれた;<br/>ねがわくば,おうこくで, なれを賛美させよ。<br/>',NULL,48982,6);
INSERT INTO stanza VALUES('J99','1','すくいぬしは, はかにあり,<br/>あさ日を待つ, イェスは主！<br/>',NULL,48983,1);
INSERT INTO stanza VALUES('J99','chorus','主は起き上がる, 主はてきに打ち勝つ,<br/>主はしょう利をせん言する,<br/>主は聖徒らとけつ合する,<br/>かれは起きる, ハレルヤ!起きる！<br/>',NULL,48984,2);
INSERT INTO stanza VALUES('J99','2','兵士のけい固, 無駄となる;<br/>封いんは無駄, イェスは主！<br/>',NULL,48985,3);
INSERT INTO stanza VALUES('J99','3','死に打ち勝つ, すくいぬし！<br/>くさりを断つ, イェスは主！<br/>',NULL,48986,4);
INSERT INTO stanza VALUES('J100','1','主,復かつし,さばき去る; かれにあり死,過ぎ去る。<br/>もはやつみさだめなし, 主の権威はあらわれる。<br/>',NULL,48987,1);
INSERT INTO stanza VALUES('J100','2','われも,ともに復かつし, てき,はかにのこされる。<br/>われは死より離だつし, 復かつのいのちに生く。<br/>',NULL,48988,2);
INSERT INTO stanza VALUES('J100','3','主のあゆみにしたがい, 至せい所にすすみ入る;<br/>御かおのひかりのなか, われは主とともに生く。<br/>',NULL,48989,3);
INSERT INTO stanza VALUES('J100','4','主,復かつし,まくに入り, われを主のあかしとす;<br/>われ,こえたかくうたう: 「主はすでに勝利を得た！」<br/>',NULL,48990,4);
INSERT INTO stanza VALUES('J101','1','キリスト,復かつす！ 主はしょう利得る;<br/>賛美せよ,ハレルヤ！ 死より復かつす。<br/>御かおのかがやき, あらわれるゆえ,<br/>がい歌をうたって, なげきにしょう利。<br/>',NULL,48991,1);
INSERT INTO stanza VALUES('J101','chorus','キリスト,復かつす！ 主はしょう利得る;<br/>賛美せよ,ハレルヤ！ 死より復かつす。<br/>',NULL,48992,2);
INSERT INTO stanza VALUES('J101','2','キリスト,復かつす！ かなしみは去る;<br/>主はよろこびつつ いのちにはいる。<br/>主は死を征ふくし, しょう利者となる;<br/>きずあるひたいに, えいこういだく。<br/>',NULL,48993,3);
INSERT INTO stanza VALUES('J101','3','キリスト,復かつす！ 何というちょうえつ;<br/>われら,主に生きて, すべてに勝利す。<br/>うたがい,おそれや, しつぼうはやむ;<br/>主の復かつの日に えんせきに着く。<br/>',NULL,48994,4);
INSERT INTO stanza VALUES('J102','1','キリストはすでに ふっかつす,ハレルーヤ！<br/>死のくさりはみな 断ち切らる,ハレルーヤ！<br/>てん使は歓喜し, ほめうたう,ハレルーヤ！<br/>つみびとはめぐみ受け, ともにうたう,ハレルーヤ！<br/>',NULL,48995,1);
INSERT INTO stanza VALUES('J102','2','主,すでによみから だっしゅつす,ハレルーヤ！<br/>死よ！おまえのとげ どこにある？ハレルーヤ！<br/>主はすでに死に, ふっかつす,ハレルーヤ！<br/>はかよ！おまえのちから, どこにもない,ハレルーヤ！<br/>',NULL,48996,2);
INSERT INTO stanza VALUES('J102','3','主は死に,あがない じょう就する,ハレルーヤ！<br/>てきをほろぼして, しょう利得る,ハレルーヤ！<br/>死はもはや主を とどめえず,ハレルーヤ！<br/>主はしょうてんし,てきを 踏みつけるー,ハレルーヤ！<br/>',NULL,48997,3);
INSERT INTO stanza VALUES('J102','4','われらも主ととも ふっかつす,ハレルーヤ！<br/>主とともにたかき てんに座す,ハレルーヤ！<br/>地じょうのきずな 断ち切られ,ハレルーヤ！<br/>主のようにたかきへと 上げられるー,ハレルーヤ！<br/>',NULL,48998,4);
INSERT INTO stanza VALUES('J103','1','身代わりの復かつを, 見なくばへい安なし;<br/>わがつみ大きくとも, 主はわれをかい放する。<br/>',NULL,48999,1);
INSERT INTO stanza VALUES('J103','2','いかにおもきつみも, ゆるされるみちあり;<br/>主イェスの血のちから, 無げん完全であるゆえ。<br/>',NULL,49000,2);
INSERT INTO stanza VALUES('J103','3','イェス,すでに復かつす, えいこうはいや増す;<br/>主はやみにはいるも, やみは主をとどめ得ず。<br/>',NULL,49001,3);
INSERT INTO stanza VALUES('J103','4','かみの義を満たして, 主は死より復かつす;<br/>かみの大いなるあい, いまもあわれみあとう。<br/>',NULL,49002,4);
INSERT INTO stanza VALUES('J103','5','かみは復かつにより, あがないを承にんす;<br/>血によりきよめられ, ハレルヤ,ゆるしを得る！<br/>',NULL,49003,5);
INSERT INTO stanza VALUES('J104','1','つみなきかた, 　主は死に,<br/>死のちからを 　支はいす。<br/>死のあく魔を 打ちくだいて,<br/>ひとをごくから 　解ほうす。<br/>',NULL,49004,1);
INSERT INTO stanza VALUES('J104','2','はかをやぶり, 　復かつし,<br/>死のくさりに 　勝利する！<br/>くらきはかを 打ちやぶって,<br/>死のかげすべて 　取り去る。<br/>',NULL,49005,2);
INSERT INTO stanza VALUES('J104','3','主は偉だいな 　勝利得る！<br/>何とほう富な 　えいこう！<br/>多くのせい徒, 生み出されて,<br/>主にみ住まいを 　あたえる。<br/>',NULL,49006,3);
INSERT INTO stanza VALUES('J104','4','はつ穂なる主, 　愛します;<br/>かみのちょう子, 　みちびく。<br/>なれはかしら, とわのわが分,<br/>栄こう,れいはい, 　受けませ。<br/>',NULL,49007,4);
INSERT INTO stanza VALUES('J105','1','ハレルヤ,キリスト！ ふっかつされた！<br/>死の門,打ちやぶり, われらかん喜す;<br/>重：キリスト復かつし, いま生きたもう。<br/>',NULL,49008,1);
INSERT INTO stanza VALUES('J105','2','ハレルヤ,キリスト！ かしらとされた！<br/>せいれいはくだり, すべてあたえる;<br/>重：キリスト復かつし, われらを義とす。<br/>',NULL,49009,2);
INSERT INTO stanza VALUES('J105','3','ハレルヤ,キリスト！ 死のちから去る！<br/>かれこそふっかつ, 死よりすくわる;<br/>重：キリスト復かつし, めぐみあたえる。<br/>',NULL,49010,3);
INSERT INTO stanza VALUES('J106','1','栄こうあれ, ふっかつの主に,<br/>なれはすでに死に しょう利得る;<br/>「はかにおられぬ」と, 天使は告げ,<br/>主イェスの復かつが, けい示される。<br/>',NULL,49011,1);
INSERT INTO stanza VALUES('J106','chorus','栄こうあれ, ふっかつの主に,<br/>なれはすでに死に しょう利得る<br/>',NULL,49012,2);
INSERT INTO stanza VALUES('J106','2','復かつの主, われらに会われ,<br/>やみ,おそれのぞき, 平安得さす;<br/>しょうかいは歓喜し, 主をうたう,<br/>死のけん威,失せて, いま主は生く。<br/>',NULL,49013,3);
INSERT INTO stanza VALUES('J106','3','いのちの主, えいこうのおう;<br/>いのちの主を得て, 死にしょう利。<br/>ふっかつの大能で, われら勝利,<br/>おうこくに入れば, たたかいなし。<br/>',NULL,49014,4);
INSERT INTO stanza VALUES('J107','1','イェス,はかより出, すでに死にしょう利;<br/>われら安そくし, 主の名を賛美す。<br/>あがないは成就し, てきに打ち勝つ。<br/>つみのあがない, いち度で成就す。<br/>',NULL,49015,1);
INSERT INTO stanza VALUES('J107','2','はかにはおらず, よみにもおられず;<br/>主は苦難を受け, しゅくふく得さす。<br/>主はすでに死なれ, 死はもはやなし;<br/>死もはかも主を, とどめられない。<br/>',NULL,49016,2);
INSERT INTO stanza VALUES('J107','3','むぎつぶは死に, 多くのむぎを生む;<br/>かつては主のみ, いまはしょうかい。<br/>われら主のからだ, かしらにつづく;<br/>ともに昇天して, えい遠に賛美す。<br/>',NULL,49017,3);
INSERT INTO stanza VALUES('J108','1','あいする主,キリスト, われらはうたう;<br/>血にてあがない成し, しゅくはいあとう。<br/>主はてきをほろぼし, てんの御座に着く;<br/>われら栄光にすすみ, 王こくに入る。<br/>',NULL,49018,1);
INSERT INTO stanza VALUES('J108','2','あいする主,キリスト, われらはうたう;<br/>主は死の領いき攻め, サタンをしばる。<br/>もはやうれいはなく, 死の権せいは去る;<br/>死とハデスのかぎを, 主は持たれる。<br/>',NULL,49019,2);
INSERT INTO stanza VALUES('J108','3','あいする主,キリスト, われらはうたう;<br/>主は十字架を通して, てき取り去る。<br/>いのちの大のうにて, ハデスへ投げ込む,<br/>くらやみ吹きはらい, そくばく解く。<br/>',NULL,49020,3);
INSERT INTO stanza VALUES('J108','4','あいする主,キリスト, われらはうたう;<br/>主は永遠のしょう利者, われ,解放する。<br/>すくいのちからにて, 自ゆうを得させる;<br/>かみと主にえい光を, えい遠に帰す。<br/>',NULL,49021,4);
INSERT INTO stanza VALUES('J109','1','賛美,賛美,キリスト, すでに勝利得る！<br/>あがない成就した, ふるいひとは死ぬ！<br/>十字架のしょう利で サタンはほろびる！<br/>',NULL,49022,1);
INSERT INTO stanza VALUES('J109','2','賛美,賛美,キリスト, すでに復かつす！<br/>死は飲み尽くされ, いのちへみちびく！<br/>よみのやみ,やぶり, たい能あらわす！<br/>',NULL,49023,2);
INSERT INTO stanza VALUES('J109','3','賛美,賛美,キリスト, すでに昇天する！<br/>万ぶつを超えつし, たかき御名を得る！<br/>すべての権威おび, てき投げ落とす！<br/>',NULL,49024,3);
INSERT INTO stanza VALUES('J109','4','ハレルヤ,キリスト, すでに勝利得る！<br/>ハレルヤ,キリスト, すでにふっかつす！<br/>ハレルヤ,キリスト, すでに昇天する！<br/>',NULL,49025,4);
INSERT INTO stanza VALUES('J110','1','聞けよ,小ひつじたとう せんまんのさけびを;<br/>せい徒らも呼おうして, 主の御名をあがむ。<br/>',NULL,49026,1);
INSERT INTO stanza VALUES('J110','2','「小ひつじをたたえよ！」と, あめつち,つどい来る,<br/>よろずのこえはひびき, 宇ちゅうに賛美満つ。<br/>',NULL,49027,2);
INSERT INTO stanza VALUES('J110','3','かん謝,敬虔なるいのり, ちちの御座にのぼる;<br/>御子にひれ伏すひざは, まことにいちりつ。<br/>',NULL,49028,3);
INSERT INTO stanza VALUES('J110','4','御子のすべて,かがやき, ちちの栄光,あらわす;<br/>ちちのすべての知恵は, 御子の尊貴,しめす。<br/>',NULL,49029,4);
INSERT INTO stanza VALUES('J110','5','せいれいはゆきわたり, てん使らさいわいもて,<br/>「ありてあるもの」なる主, 小ひつじをたとう。<br/>',NULL,49030,5);
INSERT INTO stanza VALUES('J110','6','しんそう造はまんぞく, あんそくとよろこび,<br/>すくわれしものもはや, そくばくはあらじ。<br/>',NULL,49031,6);
INSERT INTO stanza VALUES('J110','7','聞けよ,天上のさけびを, 揺れうごくさん美を,<br/>おなじめぐみによくす われらみな「アーメン！」<br/>',NULL,49032,7);
INSERT INTO stanza VALUES('J110','note','　３　いちりつ――一律<br/>',NULL,49033,8);
INSERT INTO stanza VALUES('J111','1','かみの子,すくいぬし, 血によりあがない成し,<br/>死より解かる; ながせい徒らは見た:<br/>いま,なれは栄こうの かんむりを受け,御座に座すを。<br/>',NULL,49034,1);
INSERT INTO stanza VALUES('J111','2','ちちは主をたかくし, えい光,権威をあたえ,<br/>御座に着かす; さん美,知恵,ほう富は,<br/>あいするなれのもの！ 主よ,なれのとしつきは無限。<br/>',NULL,49035,2);
INSERT INTO stanza VALUES('J111','3','主は召かいのかしら, 肢たいをきょう給する,<br/>なれわがもの: なれはいのち,ちから,<br/>われをかたく立たせ, てきすべてにしょう利得さす。<br/>',NULL,49036,3);
INSERT INTO stanza VALUES('J111','4','主のさい臨はちかし, はなよめは上げられ,<br/>なが美を見る。 なんとたのしきこと！<br/>われ,ながものとなり, とわになれとあんそくする。<br/>',NULL,49037,4);
INSERT INTO stanza VALUES('J112','1','見よ,勝者,勝ちほこって, 王のほまれ得る,<br/>くもの戦車に乗り, 天のみやに行く;<br/>聞け,歓喜のうたを, ハレルヤのうた,<br/>天の門あたまを上げて, むかえ入れる,<br/>　かれらのてんの王を。<br/>',NULL,49038,1);
INSERT INTO stanza VALUES('J112','2','ヨベルのとしを告げる, 栄光なるかたよ,<br/>たたかわれる主は, 勝利を得られた。<br/>十字架,あまんじ受け, はかより起きる;<br/>つみ,サタンをほろぼした, 主の死,通して,<br/>　てきを打ちくだいた。<br/>',NULL,49039,2);
INSERT INTO stanza VALUES('J112','3','しゅくふくの手を挙げて, 主はのぼられた;<br/>たずさえ上げられ, 天のみやに行く。<br/>かみとともに行き, 真理をつたえた;<br/>わがエノクはかみへと 取られ,すすみ,<br/>　かみのまえにすすむ。<br/>',NULL,49040,3);
INSERT INTO stanza VALUES('J112','4','わがアロン,血をたずさえ, 至聖所にはいる;<br/>ヨシュア,てきやぶり, カナンの地に入る;<br/>主はかみのたみを, 良き地に植える;<br/>わがエリヤ,しゅくふくを, 二ばいにして,<br/>　てんのしゅくふくあとう。<br/>',NULL,49041,4);
INSERT INTO stanza VALUES('J112','5','主,ひとの性しつたかめ, かみにもたらす;<br/>われら,栄光のなか, 主とともに座す。<br/>天使は主をはいし, ひと,御座に着く;<br/>大能の主,しょうてんした, われは信じる,<br/>　昇てんを得ると信じる。<br/>',NULL,49042,5);
INSERT INTO stanza VALUES('J113','1','とうとき御名,イェス, 天使ら伏して,<br/>かんむりをささげ,ともに 万有の主たとう,<br/>かんむりをささげ,ともに 万有の主をたとう。<br/>',NULL,49043,1);
INSERT INTO stanza VALUES('J113','2','代々の殉きょうした せい徒はみな,<br/>さい壇よりかん喜して, 万有の主たとう,<br/>エッサィの根をたかく上げ, 万有の主をたとう。<br/>',NULL,49044,2);
INSERT INTO stanza VALUES('J113','3','あがないを受けた アダムのすえ,<br/>堕らくよりすくわれて, 万有の主たとう,<br/>せい徒らはれいはいし, 万有の主をたとう。<br/>',NULL,49045,3);
INSERT INTO stanza VALUES('J113','4','つみびとよ,とわに おぼえていよ,<br/>かれのくるしみ,苦のう; 万有の主たとう,<br/>御まえに主をあおぎ見, 万有の主をたとう。<br/>',NULL,49046,4);
INSERT INTO stanza VALUES('J113','5','地のすべてのたみ, 主に呼ばわれ;<br/>えいこうを御名に帰し, 万有の主たとう,<br/>えいこうを御名に帰し, 万有の主をたとう。<br/>',NULL,49047,5);
INSERT INTO stanza VALUES('J113','6','千万のうたごえは 雷めいのよう，<br/>われらもみなひれ伏し, 万有の主たとう,<br/>えい遠にれいはいして, 万有の主をたとう。<br/>',NULL,49048,6);
INSERT INTO stanza VALUES('J114','1','見よや！小ひつじは, 栄こう得られた！<br/>主よりたかきもの, 天じょうにあり得じ,<br/>　天じょうにはなし。<br/>',NULL,49049,1);
INSERT INTO stanza VALUES('J114','2','主はてんにのぼり, 御座に着かれる！<br/>主はせい徒のうた, ちちのあいすもの,<br/>　ちちはあいする。<br/>',NULL,49050,2);
INSERT INTO stanza VALUES('J114','3','主,いかにたかくも, わがさん美受く;<br/>わがこえよわくも, すべて主にとどく,<br/>　みな主にとどく。<br/>',NULL,49051,3);
INSERT INTO stanza VALUES('J114','4','われらのしい歌は, かみの小ひつじ,<br/>かれは御座に着き, 賛美を受けるかた,<br/>　賛美,受けるかた。<br/>',NULL,49052,4);
INSERT INTO stanza VALUES('J114','5','かつてさげすまれ, いまえい光得る;<br/>かんむり,たかき地位, かれのものとなる,<br/>　主のものとなる。<br/>',NULL,49053,5);
INSERT INTO stanza VALUES('J115','1','見よや,天上に座すイェス！ 主キリストの御座を！<br/>ひととしてたかめられ, えいこう,尊貴受く。<br/>',NULL,49054,1);
INSERT INTO stanza VALUES('J115','2','ひとのせいしつを着て, けいかくにより死ぬ,<br/>からだもてよみがえり, ひととし,昇天する。<br/>',NULL,49055,2);
INSERT INTO stanza VALUES('J115','3','主のなかで,かみくだり, 地じょうでひとに住む;<br/>主のなかで,ひとのぼり, かみとともに住む。<br/>',NULL,49056,3);
INSERT INTO stanza VALUES('J115','4','主はかみとひとの調和, ひとにて,かみしめす;<br/>かみ・ひとなる主にあり, ひとは栄光を得る。<br/>',NULL,49057,4);
INSERT INTO stanza VALUES('J115','5','イェスはえいこうを受け, そのれいとして来る;<br/>イェスの人位とみわざを, そのれいはしめす。<br/>',NULL,49058,5);
INSERT INTO stanza VALUES('J115','6','えいこう受けたイェスと, しょうかいはつらなる;<br/>このイェスのれいにより, かく肢体は生きる。<br/>',NULL,49059,6);
INSERT INTO stanza VALUES('J115','7','見よや,天上に座すひと！ 万ゆうの主の御座を！<br/>それは,すくいぬしイェス, とわに栄光あれや！<br/>',NULL,49060,7);
INSERT INTO stanza VALUES('J116','1','主よ,なが苦なんと わざわいのみちは,<br/>いま過ぎ去る。 なれ,はたらき終え,<br/>いまやかみにより, たかくされる。<br/>',NULL,49061,1);
INSERT INTO stanza VALUES('J116','2','苦なん受けし主は, 栄光のかんむり受け,<br/>ちちの御座に。 主をさん美します,<br/>とわのれいはいは, 主にふさわしい！<br/>',NULL,49062,2);
INSERT INTO stanza VALUES('J116','3','かしらなるなれと, 肢たいなるわれら,<br/>けつごうされ, ながえいこう,御座,<br/>なが権威,みくにを, ともに受ける。<br/>',NULL,49063,3);
INSERT INTO stanza VALUES('J116','4','主とわれらはいち, われらはよろこび,<br/>ともにうたう; われ苦なんあれど,<br/>御座をおもうとき, 何たるかん喜。<br/>',NULL,49064,4);
INSERT INTO stanza VALUES('J117','1','すくいぬし御座に着き, えいこうのかんむり受く,<br/>かみは主をたかく上げ, 主はすべてちょうえつす。<br/>',NULL,49065,1);
INSERT INTO stanza VALUES('J117','chorus','すべてに,はるかに, 主イェスはちょうえつす主,<br/>れいはいのうた,やまず, われらのイェス,超えつす。<br/>',NULL,49066,2);
INSERT INTO stanza VALUES('J117','2','この世のあらしに遭い, かぜやなみおそうとも,<br/>主をあおぎのぞむとき, われ,すべてに平安得る。<br/>',NULL,49067,3);
INSERT INTO stanza VALUES('J117','3','じょうへきたかくそびえ, てき,いかにつよくとも,<br/>主はすべて超えつすと, われは信じて前しんす。<br/>',NULL,49068,4);
INSERT INTO stanza VALUES('J117','4','見よ,ぜん地は主のくに, ばんぶつはふくじゅうす,<br/>しょう利得たものすべて, 主とともにちょうえつす。<br/>',NULL,49069,5);
INSERT INTO stanza VALUES('J118','1','いばらを受けたこうべ, いま栄光受け,<br/>すくいぬし元首はいま, たかく昇天す。<br/>',NULL,49070,1);
INSERT INTO stanza VALUES('J118','2','主は地で聖徒のかん喜, 天ではひかり;<br/>あいのかわより飲ませ, ふかさ知らす。<br/>',NULL,49071,2);
INSERT INTO stanza VALUES('J118','3','主よ,なが権威とはじを, ともにたまえ;<br/>世は御名をいなむとも, かみ,たかくす。<br/>',NULL,49072,3);
INSERT INTO stanza VALUES('J118','4','主とともに苦難を受け, 天で栄光得る;<br/>われはいまかたく立ち, 世をいやしむ。<br/>',NULL,49073,4);
INSERT INTO stanza VALUES('J118','5','十字架はながはじと死, されどいまは,<br/>わがいのち,栄光,権せい！ とわの安そく！<br/>',NULL,49074,5);
INSERT INTO stanza VALUES('J119','1','えい遠のえいこう, キリストにあれ;<br/>えい遠のえいこう, 小ひつじにあれ。<br/>かれのとうとき名を てん地はうたう;<br/>えい遠のえいこう, この御名にあれ。<br/>',NULL,49075,1);
INSERT INTO stanza VALUES('J119','2','えいこうの御座で 主はかみといち;<br/>奴れいのさまにて, 地で苦難受ける。<br/>御むねにしたがい, 死にいたるまで,<br/>主はじゅう順になり, じゅう字架で死ぬ。<br/>',NULL,49076,2);
INSERT INTO stanza VALUES('J119','3','天のかんむり,栄光は, ひとなるイェスに;<br/>かがやくころもは えいこうの身に。<br/>万ぶつはひれ伏し, 「主」とこくはくす;<br/>ばん有の主,おうに, ほめうた,うたう。<br/>',NULL,49077,3);
INSERT INTO stanza VALUES('J119','4','えい遠のえい光を, 比るいなき主に;<br/>てん地のえい光を, すべて主に帰す。<br/>えいこうのかみは 「ありてあるもの」;<br/>えい遠のえいこう, とわに主にあれ。<br/>',NULL,49078,4);
INSERT INTO stanza VALUES('J120','1','かんむりを受けた ばんゆうの主よ;<br/>ながけんのうと威げんを, ばんみんはほむ。<br/>',NULL,49079,1);
INSERT INTO stanza VALUES('J120','2','ひとにあるかみは 地じょうでしもべ;<br/>かみにあるひとは天上で ばんゆうの主ぞ。<br/>',NULL,49080,2);
INSERT INTO stanza VALUES('J120','3','えいこうのかみと ともに座すひと;<br/>てん地のけんのうはみな なれに帰せらる。<br/>',NULL,49081,3);
INSERT INTO stanza VALUES('J120','4','たかく上げられた さいこうの名に,<br/>ばんぶつはひざをかがめ, 主とこくはくす。<br/>',NULL,49082,4);
INSERT INTO stanza VALUES('J120','5','主またキリストと, かみはさだめる;<br/>栄こうにあり,座に着くを, 聖霊はあかしす。<br/>',NULL,49083,5);
INSERT INTO stanza VALUES('J120','6','えいこうの主ほむ, こえたからかに;<br/>ばんゆうの主はさん美に ふさわしきゆえ！<br/>',NULL,49084,6);
INSERT INTO stanza VALUES('J121','1','栄こうなる光けい, 御子は栄光を得る！<br/>たたかいを終えて， 勝ちほこり,かえる！<br/>かんむりを,かんむりを, 勝利の王に帰す。<br/>',NULL,49085,1);
INSERT INTO stanza VALUES('J121','2','いばらのかんむりを, ひとはかぶらせる;<br/>いま主は栄こうの かんむりを受けらる。<br/>かんむりを,かんむりを, 愛の御子に帰す。<br/>',NULL,49086,2);
INSERT INTO stanza VALUES('J121','3','われらつみびとは, 主のとりことなる;<br/>われらのこころに, 主を座に着かせる。<br/>かんむりを,かんむりを, つみびとの主に。<br/>',NULL,49087,3);
INSERT INTO stanza VALUES('J121','4','聞け,このさけびを, しょう利のがい歌を！<br/>主はたかきへゆく, 何たるよろこびよ！<br/>かんむりを,かんむりを, 王の王,主の主に！<br/>',NULL,49088,4);
INSERT INTO stanza VALUES('J122','1','えいこうのイェスを 礼はいし,見つめ,<br/>十字架の恥じょくの ものがたり読む。<br/>',NULL,49089,1);
INSERT INTO stanza VALUES('J122','2','恥じょくに満つこうべ, ひとはみな見た;<br/>栄こうはその日の うれいをかたる。<br/>',NULL,49090,2);
INSERT INTO stanza VALUES('J122','3','十字架のときには, 孤どくで無じょう;<br/>御座に上げられて, せい徒ら賛美す。<br/>',NULL,49091,3);
INSERT INTO stanza VALUES('J122','4','かみ,かつてなれを, 見はなし捨てる！<br/>打たれた御かおに, ちちの栄光見る。<br/>',NULL,49092,4);
INSERT INTO stanza VALUES('J122','5','とうとい主！なれ見て, 賛美,きんじ得ず;<br/>天地はともにうたう: 「小ひつじをほむ」。<br/>',NULL,49093,5);
INSERT INTO stanza VALUES('J122','6','こころを起こして, ちちをさん美す;<br/>歓喜,さん美とわに, ちちと子にあれ。<br/>',NULL,49094,6);
INSERT INTO stanza VALUES('J123','1','栄光の主,キリスト, たかく上げらる！<br/>こころ,たましいは なれにひれ伏す;<br/>主を賛美,礼拝す, ながみちは栄光！<br/>',NULL,49095,1);
INSERT INTO stanza VALUES('J123','2','あぶら塗られた王, えいこう受ける！<br/>嘲笑され,いとわれ, きょぜつされた主;<br/>いまわれらほむ, きわみのえい光。<br/>',NULL,49096,2);
INSERT INTO stanza VALUES('J123','3','なれはいのちの主, しゅくふくあとう！<br/>ちちのあいする子, じゅうじゅんなかた。<br/>われ,主を記念し, 苦なんをしのぶ。<br/>',NULL,49097,3);
INSERT INTO stanza VALUES('J123','4','王のころもを着て, かんむり受くかた！<br/>かみのキリストよ, われ,さい臨待つ;<br/>主あいし,ふくす, なれはキリスト。<br/>',NULL,49098,4);
INSERT INTO stanza VALUES('J124','1','主よ,なれは王の王, すべてなれに帰する;<br/>あぶら塗らる主を, れいはいし,あいす！<br/>千まんのせい徒は, 王のおうをたとう！<br/>',NULL,49099,1);
INSERT INTO stanza VALUES('J124','2','くにからくにまで, ながけん威はおよぶ！<br/>万民は来て,なれに 王としてつかえる。<br/>このおうのおうを, 万民はほめたとう！<br/>',NULL,49100,2);
INSERT INTO stanza VALUES('J124','3','なが王こく,御座は えい遠にかたく立つ！<br/>えいこうと権威を, われら,とわにほむ！<br/>このおうのおうを, せい徒らはたとう！<br/>',NULL,49101,3);
INSERT INTO stanza VALUES('J124','4','すくいぬし,おうの 御名をあいし,したう！<br/>なが統治をしたい, 王こく来るを待つ！<br/>いまもわれらほむ！ 「なれ,おうのおう」と！<br/>',NULL,49102,4);
INSERT INTO stanza VALUES('J125','1','主はあぶら塗られた 　おうのなかのおう！<br/>われられいはいし, 　たからかにうたう！<br/>なが王こくは無限, 　なが御座はけん固！<br/>なが統治,義とあい, 　えい光かぎりなし。<br/>',NULL,49103,1);
INSERT INTO stanza VALUES('J125','2','せいなるシオンの上に, 　かみ,なれを立てて,<br/>諸こくをたまわり, 　とわの嗣ぎょうとす。<br/>かみはかれの権威, 　なれに委たくして,<br/>諸こくとう治させ, 　えいえんにいたる。<br/>',NULL,49104,2);
INSERT INTO stanza VALUES('J125','3','ときはいまだ満ちず, 　やみ,権威ふるうも,<br/>千万のぐんしゅうは, 　なれをほめたとう！<br/>ながたみの賛美は, 　地にひびきわたり,<br/>なれをおうとして, 　れい拝し,つかえる。<br/>',NULL,49105,3);
INSERT INTO stanza VALUES('J125','4','さだめの日,来たれば, 　主はさいりんする;<br/>地とその諸こくは, 　みな,なれにかえる。<br/>こう輝,威厳に満ち, 　なれはおうとなる,<br/>諸こくみんすべて, 　なれをほめたとう。<br/>',NULL,49106,4);
INSERT INTO stanza VALUES('J126','1','主よ,ながあいは何と真じつ！ 何と大きく,ひろい！<br/>わがいのちとちからを, かん全になれに帰す！<br/>',NULL,49107,1);
INSERT INTO stanza VALUES('J126','2','なが比るいなき価値のゆえ, われら,なれを愛す;<br/>十字架のはじをしのぶ, ゆえになれをあいす。<br/>',NULL,49108,2);
INSERT INTO stanza VALUES('J126','3','ひとのあいは,とものために 死ぬことであるが,<br/>なれはてきのため死ぬ！ だれかこの愛,持つや？<br/>',NULL,49109,3);
INSERT INTO stanza VALUES('J126','4','なれはかみのかたちにあり, 天じょうでやすらぐ;<br/>されど奴れいとなって, うれい,苦つうを経る。<br/>',NULL,49110,4);
INSERT INTO stanza VALUES('J126','5','なれはつみのほかすべてに, 世びとのようになり,<br/>われらをまったくなれに 似せて,つくり変える。<br/>',NULL,49111,5);
INSERT INTO stanza VALUES('J126','6','なれのようにゅう和でけん固, すべてなれに似る;<br/>栄光からえいこうへと, 日ごと,こう新される。<br/>',NULL,49112,6);
INSERT INTO stanza VALUES('J126','7','主よ,なが愛をわがこころの うちにふかく秘め,<br/>われはながとうとき名を, とわにほめたたえる。<br/>',NULL,49113,7);
INSERT INTO stanza VALUES('J127','1','イェス,えいこうの王, ひろきあいよ！<br/>なれ御座はなれ,世に来る,<br/>馬ぶねに生まれて, はくがいされ,<br/>ガリラヤのナザレに住む;<br/>ひとにつかえて, いやしめられ,<br/>ヨベルのとし告げ知らす;<br/>やすまずつかえて, 苦なん受ける;<br/>なんととうとき主のあい！<br/>',NULL,49114,1);
INSERT INTO stanza VALUES('J127','2','イェス,すくいのおう, ふかきあいよ！<br/>ゲッセマネで主はさけぶ;<br/>血のあせをながし, ちちにいのり,<br/>すくいのため,身を捨てる;<br/>はずかしめ,苦難 耐えしのびて,<br/>ゴルゴタのおかに向かう;<br/>じゅう字架にかかり, いのち捨てる;<br/>なんととうとき主のあい！<br/>',NULL,49115,2);
INSERT INTO stanza VALUES('J127','3','イェス,しょう利のおう, 無げんのあい！<br/>十字架でさえ主はいのる;<br/>ごう盗,のぞみ持ち, すくいを知り,<br/>かみのさばきを解かれる;<br/>主,つみをにない, あざけり受け,<br/>あがない成し,しょう利する;<br/>いま天でとりなし, いのりささぐ;<br/>なんととうとき主のあい！<br/>',NULL,49116,3);
INSERT INTO stanza VALUES('J127','4','イェス,へい和のおう, 偉だいなあい！<br/>わがため死に,あいしめす;<br/>わがつみをあらい, きずをいやし,<br/>われをたい処し, みちびく;<br/>すくいのめぐみ, われをまもり,<br/>つかれたわれをつよめる;<br/>てんの主をあおぎ, われらうたう;<br/>なんととうとき主のあい！<br/>',NULL,49117,4);
INSERT INTO stanza VALUES('J128','1','不思議なめぐみ, 御まえでおもう！<br/>堕らくしたわれ, なぜすくうや？<br/>この世むさぼる つみのわれを,<br/>主はたずね出し, あいでつつむ。<br/>',NULL,49118,1);
INSERT INTO stanza VALUES('J128','2','つみにしばられ, くるしむわれ,<br/>ねがわないのに, 主はたずねる;<br/>ながこえ聞けど, なれを無視し,<br/>ながてきとなり, さからうのみ。<br/>',NULL,49119,2);
INSERT INTO stanza VALUES('J128','3','わがつみのため, 十字架で死に,<br/>われにへい安を, あたえたもう！<br/>おおくのつみと にくに生きる,<br/>このわれをなぜ, 主はあいすや？<br/>',NULL,49120,3);
INSERT INTO stanza VALUES('J128','4','馬ぶねに生まれ, いやしめられ,<br/>さいなまれしは, みなわがため！<br/>なにゆえ見そめ, われあいすや？<br/>くるしみ受けて, しゅくふくあとう。<br/>',NULL,49121,4);
INSERT INTO stanza VALUES('J128','5','何の長所もない われのために,<br/>主は御座はなれ, いのち捨てる！<br/>主よ,自ぶんには なが目を引き,<br/>あいされるもの ひとつもなし！<br/>',NULL,49122,5);
INSERT INTO stanza VALUES('J128','6','われ,つみびとの かしらなるも,<br/>美とく,こうせき, なにもなくも,<br/>なれはゆえなく, われをあいす！<br/>このあい,めぐみ, 言い尽くせず！<br/>',NULL,49123,6);
INSERT INTO stanza VALUES('J128','7','このめぐみゆえ, われ,まことに,<br/>なれをあいして, ふくすべきが,<br/>わがこころ,なお つめたきまま！<br/>ながあい知るも, こたえぬまま！<br/>',NULL,49124,7);
INSERT INTO stanza VALUES('J128','8','御座をはなれて, 死なれた主に,<br/>われ,無感かくで, ねつ意もなし。<br/>この世はなれず, 主にふくさず！<br/>なれをくるしめ, 自己を捨てず！<br/>',NULL,49125,8);
INSERT INTO stanza VALUES('J128','9','この自分おもい, しつぼうする,<br/>悪しきせいしつ, 自己をうらむ。<br/>このわがこころ, なれは知るも,<br/>われをあいして, めぐみたもう！<br/>',NULL,49126,9);
INSERT INTO stanza VALUES('J128','10','このわがために, なれ,くるしみ,<br/>苦なんを受けて, いのち捨てる！<br/>冷えたこころの, 悪しきわれを,<br/>知りつつもなお, なれ,死なれる！<br/>',NULL,49127,10);
INSERT INTO stanza VALUES('J128','11','変わりやすさを, なれは知るも,<br/>わがために死に, わがため生く。<br/>このあいおもうと, なみだあふる,<br/>なれにかん謝し, 不思議におもう！<br/>',NULL,49128,11);
INSERT INTO stanza VALUES('J128','12','主よ,ながこころ, 理かいし得ず,<br/>不思議におもいつ, れいはいする。<br/>天の幸ふくにも こころ向けず,<br/>わがかみ,わが主, うたい,賛美す。<br/>',NULL,49129,12);
INSERT INTO stanza VALUES('J128','13','ひかりのなかで 絶えずうたい,<br/>なが愛に感謝し, れいはいする。<br/>天のみやこにて めぐみにより,<br/>愛の標本となり 絶えず賛美す！<br/>',NULL,49130,13);
INSERT INTO stanza VALUES('J129','1','奇しきすくいぬし, その愛たぐいなし,<br/>うみよりもふかく, てんよりもたかい;<br/>えい遠に 　　変わらず,<br/>ばんゆうを満たす; われを,主はあいす！<br/>',NULL,49131,1);
INSERT INTO stanza VALUES('J129','2','てんで栄こう受け, 御つかいつかえる;<br/>されどあいのゆえ, えいこうを捨てて,<br/>まよいし 　　ひつじを,<br/>たずねもとめ来て, かれはさがし出す！<br/>',NULL,49132,2);
INSERT INTO stanza VALUES('J129','3','かなしみのみちを ひとりあゆまれる;<br/>かれのくるしみは, かみのみ知られる;<br/>われという 　　ごく屋に,<br/>主ははいり来たり, われを,見いだせり！<br/>',NULL,49133,3);
INSERT INTO stanza VALUES('J129','4','ひとにうら切られ, いばらとむち受け,<br/>かみにも捨てられ, つみとさえされる;<br/>わがため 　　くるしみ,<br/>じゅう字架の死にて, われを,すくいたもう。<br/>',NULL,49134,4);
INSERT INTO stanza VALUES('J129','5','主のこよなきあい, 生けるかぎりほむ;<br/>たずさえ上げられ, みやこに住むとき,<br/>御かおを 　　はいして,<br/>こえたかくうたう: われは,主をあいす！<br/>',NULL,49135,5);
INSERT INTO stanza VALUES('J130','1','主よ,なが愛は何とふかきかな, 　わがおもいはるかに超ゆ;<br/>なが愛ひろく,うなばらのごと, 　この愛われにさえおよぶ！<br/>われになれを得させるため, 　なが愛なれを捨てさせり,<br/>なれとわれをひとつにさせて, 　われをなれの肢体とする。<br/>',NULL,49136,1);
INSERT INTO stanza VALUES('J130','2','なが愛のあたえ,なすところは, 　あまりにおおく言いがたし,<br/>われと連合し,われと調和すは, 　もっとも大いなるなが愛ぞ。<br/>なれをわれのものとなさせ, 　なが愛わがすべて供給す;<br/>日々なれをばわがいのちとし, 　なれご自身をたのします。<br/>',NULL,49137,2);
INSERT INTO stanza VALUES('J130','3','なが愛,神聖なかみご自身なり, 　わがじん生の意義となる,<br/>わが生くるはキリストなりと 　なが愛われにさけばせる。<br/>わがいのちまたちからとし, 　なが愛われに経験させる;<br/>われ,ながめぐみ,愛の対象なり, 　わが経験すべてはなれぞ。<br/>',NULL,49138,3);
INSERT INTO stanza VALUES('J130','4','なれとわれ,分かつものありや？ 　なが愛,最後まで愛し通す！<br/>なれとわれはとわにひとつぞ, 　なが愛つよくたぐいなし！<br/>この愛われを感動しつづけ, 　わが賛美のもくてきなり！<br/>なれはわれぞ,われはなれなり, 　これこそなが愛のきわみ！<br/>',NULL,49139,4);
INSERT INTO stanza VALUES('J131','1','主はまよいしわれら, 　愛をもってさがす;<br/>手を伸べ,みちびき, 　十字架にて死ぬ。<br/>うたえ,あいの主を; 　主はご自身あとう。<br/>',NULL,49140,1);
INSERT INTO stanza VALUES('J131','2','聞け！かなしみのこえ, 　ゲッセマネのその;<br/>弟子らねむる間に, 　主はいのりたもう。<br/>主は真に愛された; 　主はご自身あとう。<br/>',NULL,49141,2);
INSERT INTO stanza VALUES('J131','3','主はちちにもとめる, 苦はい受くこと;<br/>われら受くべきが, 　主,あまんじて取る。<br/>おお,何というあいよ， 　主はご自身あとう。<br/>',NULL,49142,3);
INSERT INTO stanza VALUES('J131','4','怒とうのくるしみを 　かみより受ける,<br/>その苦難にて,われ 　新そうぞうとす。<br/>たぐいなきあいよ！ 　主はご自身あとう。<br/>',NULL,49143,4);
INSERT INTO stanza VALUES('J131','5','聞け！主のさけびごえ, 　カルバリにひびく;<br/>かみよ,なにゆえに 　主を捨てたもうや？<br/>そはわれらのため, 　主はご自身あとう。<br/>',NULL,49144,5);
INSERT INTO stanza VALUES('J131','6','主の苦難,終わるゆえ, 　われらよろこぶ,<br/>なれは昇天し,座し, 　永えんに生きる。<br/>わがため死んだ主に, 　いまわれ,生きる。<br/>',NULL,49145,6);
INSERT INTO stanza VALUES('J131','7','主よ,ながめぐみゆえ, 　賛美,礼はいする;<br/>われらは成就され, 　なれにまみえる。<br/>いま,われらはうたう: 　主はご自身あとう。<br/>',NULL,49146,7);
INSERT INTO stanza VALUES('J132','1','無げんのながさ, 宇ちゅうのひろさ,<br/>天のようなたかさ, うみのようなふかさ,<br/>主のあい！<br/>',NULL,49147,1);
INSERT INTO stanza VALUES('J132','chorus','大いなるかな,主のあい！<br/>ながさ,ひろさと,たかさ,ふかさを享受する！<br/>',NULL,49148,2);
INSERT INTO stanza VALUES('J132','2','ながさ-主は死に, ゆるしあたえる;<br/>ひろさ-主,あがない, めぐみを得させる;<br/>主のあい！<br/>',NULL,49149,3);
INSERT INTO stanza VALUES('J132','3','たかさ-引き上げ, 天にすわらせる;<br/>ふかさ-われを生み, わがうちに生きる;<br/>主のあい！<br/>',NULL,49150,4);
INSERT INTO stanza VALUES('J132','4','ながさ,ひろさと, たかさ,ふかさは,<br/>ものごとではなく, 主のあいそのもの,<br/>主のあい！<br/>',NULL,49151,5);
INSERT INTO stanza VALUES('J133','1','兄だい愛にまさる, 　おお,主の愛！<br/>つよくて親みつな, 　おお,主の愛！<br/>世のとものあいは 気まぐれなれども,<br/>あざむくことない, 　おお,主の愛！<br/>',NULL,49152,1);
INSERT INTO stanza VALUES('J133','2','われらは享受する, 　おお,主の愛！<br/>主はだい価はらう, 　おお,主の愛！<br/>主は血をながして, われらを買い取り,<br/>われらをみちびく, 　おお,主の愛！<br/>',NULL,49153,2);
INSERT INTO stanza VALUES('J133','3','イェス,われらのとも, 　おお,主の愛！<br/>しゅくふくあたえる, 　おお,主の愛！<br/>主イェスをあおぎ見, 御まえに安そくす,<br/>たしかにたよれる, 　おお,主の愛！<br/>',NULL,49154,3);
INSERT INTO stanza VALUES('J133','4','わがつみをゆるす, 　おお,主の愛！<br/>てきをせいふくす, 　おお,主の愛！<br/>かんきょうすべてを しゅくふくとなして,<br/>えい遠にみちびく, 　おお,主の愛！<br/>',NULL,49155,4);
INSERT INTO stanza VALUES('J134','1','はかりがたきながあい, 日ごとに増しくわわる;<br/>その愛のひろさ,ながさ, たかさ,ふかさはおよぶ,<br/>わが身に。<br/>',NULL,49156,1);
INSERT INTO stanza VALUES('J134','2','ながあい,人知を越える, われのくちびるにあり,<br/>つみびとらにつたえて, うれいを解き,よろこびを<br/>あたえる。<br/>',NULL,49157,2);
INSERT INTO stanza VALUES('J134','3','いとくすしきながあい, ほめ尽くし得ぬひろさ,<br/>こころよりほめうたい, われもだい胆にかみに<br/>ちかづく。<br/>',NULL,49158,3);
INSERT INTO stanza VALUES('J134','4','あいのみなもとなる主, われながみもとに行く;<br/>このむなしきこころを, 満たしに満たせや,なが<br/>あいもて。<br/>',NULL,49159,4);
INSERT INTO stanza VALUES('J134','5','われはむなしいうつわ, なれをしたうことなし;<br/>されどながあいのゆえ, 御まえにめぐみ,たすけ,<br/>もとめる。<br/>',NULL,49160,5);
INSERT INTO stanza VALUES('J134','6','主よ,あいでわれ満たし, 生けるかわへみちびき,<br/>ひたすらたのしませよ, なれ以がいはなにをも<br/>もとめず。<br/>',NULL,49161,6);
INSERT INTO stanza VALUES('J134','7','御まえに主とまみえて, ひれ伏すときにうたう;<br/>あいのひろさとながさ, たかさとふかさをわれ,<br/>れい拝す。<br/>',NULL,49162,7);
INSERT INTO stanza VALUES('J135','1','われら千万のしたで, 　すくいぬしさん美し,<br/>ながめぐみのふかさ, 　えいこうをかたる。<br/>',NULL,49163,1);
INSERT INTO stanza VALUES('J135','2','イェスの名はなぐさめ, 　おそれを取りのぞく;<br/>われの安そく,いのち, 　わがしらべとなる。<br/>',NULL,49164,2);
INSERT INTO stanza VALUES('J135','3','われをあいするゆえ, 　すべての苦難受ける;<br/>つみのちからのぞき, 　つみの囚人を解く。<br/>',NULL,49165,3);
INSERT INTO stanza VALUES('J135','4','われをすくうあいを, 　いま,しずかにおもう;<br/>つみびとのかしらを 　なにゆえすくうや。<br/>',NULL,49166,4);
INSERT INTO stanza VALUES('J135','5','われはいまあまんじて, 　あいのとりことなる;<br/>わがため,かれは死に, 　自由得させるゆえ。<br/>',NULL,49167,5);
INSERT INTO stanza VALUES('J135','6','あいすべき名により, 　なれのこころを知る;<br/>こころが千万あれば, 　すべてなれに帰す。<br/>',NULL,49168,6);
INSERT INTO stanza VALUES('J136','1','主をあいするもの, よろこび来たれ;<br/>主のあい,あまくうたいつ, 御まえに来たれや。<br/>',NULL,49169,1);
INSERT INTO stanza VALUES('J136','chorus','よろこびのめぐみ, 完ぜんなゆるし！<br/>無だい価のめぐみなれば, よろこばしきかな！<br/>',NULL,49170,2);
INSERT INTO stanza VALUES('J136','2','主の名知らぬもの, もくすほかなし;<br/>すでにめぐみを得しもの, よろこびあふれる。<br/>',NULL,49171,3);
INSERT INTO stanza VALUES('J136','3','えいこうのみやに, いまだ入らねど,<br/>さとのあまき実,あじみし, よろこびたのしむ。<br/>',NULL,49172,4);
INSERT INTO stanza VALUES('J136','4','うたえ,たからかに, うれいわすれて;<br/>てんのふるさとめざして, ひたすらすすめや。<br/>',NULL,49173,5);
INSERT INTO stanza VALUES('J137','1','主はそん貴を捨て, この世に来たり,<br/>わがため十字架で つみを負われる;<br/>ふかきかな, ながめぐみ,<br/>わがすべてのあい, 主にささぐ。<br/>',NULL,49174,1);
INSERT INTO stanza VALUES('J138','1','主,かみのたから, またよろこび！<br/>かみ,よろこびの あぶらを塗られる。<br/>',NULL,49175,1);
INSERT INTO stanza VALUES('J138','chorus','われら珍重する, 主の善さと美,<br/>かぐわしさ,あまさ, うるわしさを。<br/>',NULL,49176,2);
INSERT INTO stanza VALUES('J138','2','うるわしいかた, あいすべき主;<br/>くちにはめぐみ, わがこころしたう。<br/>',NULL,49177,3);
INSERT INTO stanza VALUES('J138','3','誕生のとき,なれ, たからを受け,<br/>埋葬のとき,なれ, 香料でつつまれる。<br/>',NULL,49178,4);
INSERT INTO stanza VALUES('J138','4','ながかしらには, 香油そそがれ,<br/>あしにも塗られ, ひとにあいされる。<br/>',NULL,49179,5);
INSERT INTO stanza VALUES('J138','5','死のもつやくは, ひと,なぐさめ,<br/>復かつの香料は, かみ,満ぞくさせる。<br/>',NULL,49180,6);
INSERT INTO stanza VALUES('J138','6','主,われのなかで, もつやくのよう,<br/>うるわしいヘンナ樹, ゆたかなオレンジ。<br/>',NULL,49181,7);
INSERT INTO stanza VALUES('J138','7','ぶどう酒にまさる あまきなが愛！<br/>香油のような御名, 何ととうとき御名よ。<br/>',NULL,49182,8);
INSERT INTO stanza VALUES('J138','8','なが善さと美を われはおもう;<br/>なれのあまさを あじわい,飽き足る。<br/>［6節の「オレンジ」は，雅歌第2章3節の「りんごの木」の別訳です。］<br/>',NULL,49183,9);
INSERT INTO stanza VALUES('J139','1','御かおにしんせい, 　　　 威げん,そん貴;<br/>かしらにえいこう, くちにはめぐみ,くちにめぐみ。<br/>',NULL,49184,1);
INSERT INTO stanza VALUES('J139','2','地上のだれが主に 　　　 くらべられよう？<br/>主は天の軍ぜいに まさり,うるわしい,主はうるわしい。<br/>',NULL,49185,2);
INSERT INTO stanza VALUES('J139','3','主はわがよろこび, 　　　 いのちといき;<br/>死に打ち勝たせて, はかよりすくう,はかよりすくう。<br/>',NULL,49186,3);
INSERT INTO stanza VALUES('J139','4','住まいなるちちに, 　　　 主はみちびき,<br/>かみのえい光見せ, よろこび満たす,あふれ満たす。<br/>',NULL,49187,4);
INSERT INTO stanza VALUES('J139','5','ゆたかなめぐみで, 　　　 主のあい知る;<br/>われに万のこころ あるなら,すべて主にささげる。<br/>',NULL,49188,5);
INSERT INTO stanza VALUES('J140','1','主,かみのさだめし いとしいはなむこ;<br/>主に引き付けられ, したいてやまず！<br/>',NULL,49189,1);
INSERT INTO stanza VALUES('J140','2','わがあいのおっとよ, なんととうとし！<br/>なが無限のあいを われら珍重する！<br/>',NULL,49190,2);
INSERT INTO stanza VALUES('J140','3','なれ,美のなかの美 あまさのきわみ！<br/>にゅう和でしんせつ, なんとかんぜん！<br/>',NULL,49191,3);
INSERT INTO stanza VALUES('J140','4','ころもにもつやく, くちにはめぐみ;<br/>主の苦難のかおり, われ,いとおしむ。<br/>',NULL,49192,4);
INSERT INTO stanza VALUES('J140','5','よろこびのあぶら, なれにそそがれ,<br/>「ぞう牙のみや」より さん美わき出る。<br/>',NULL,49193,5);
INSERT INTO stanza VALUES('J140','6','主はしゅくふく受け, てきに打ち勝つ;<br/>権威もて座に着き, 威げんを帯びる。<br/>',NULL,49194,6);
INSERT INTO stanza VALUES('J140','7','万こく,主をしたい, なが価値を知る;<br/>万民を超える主を とわにほめたとう！<br/>',NULL,49195,7);
INSERT INTO stanza VALUES('J140','note','［５　ぞう牙のみや――各地の召会を指す］<br/>',NULL,49196,8);
INSERT INTO stanza VALUES('J141','1','主をおもうわがこころ, 　いかにあまきや;<br/>ともにまさばあめに あるがごとし。<br/>',NULL,49197,1);
INSERT INTO stanza VALUES('J141','chorus','うるわしきぶどう園の ヘンナ樹のはなぶさ;<br/>たぐいなきなれをば あいしたたえん。<br/>',NULL,49198,2);
INSERT INTO stanza VALUES('J141','2','ながあいたのしむに 足るこころなく,<br/>主をほむふさわしき がくもあらじ。<br/>',NULL,49199,3);
INSERT INTO stanza VALUES('J141','3','みめぐみ,あいもわが こころ満たさず,<br/>なれご自身こそわが まんぞくなり。<br/>',NULL,49200,4);
INSERT INTO stanza VALUES('J141','4','なれにまさるものは あめつちになし;<br/>あまきながそばにて ねがい満ちぬ。<br/>',NULL,49201,5);
INSERT INTO stanza VALUES('J142','1','主はそよかぜのよう さわやか,柔和！<br/>そのかぐわしさは くらぶるものなし;<br/>なれ,もつやく, 天上のこう油！<br/>',NULL,49202,1);
INSERT INTO stanza VALUES('J142','2','あさつゆにまさり きよくしん鮮！<br/>こころをやしない, ふかみをうるおす;<br/>主よ,わがうち, 浸とうしませ。<br/>',NULL,49203,2);
INSERT INTO stanza VALUES('J142','3','なれ,うるわしさの きわみなる主！<br/>御かおのひかりは いよいよかがやく;<br/>主はうるわしい, 主はうるわしい！<br/>',NULL,49204,3);
INSERT INTO stanza VALUES('J142','4','すべてにまさりて かぐわしき名！<br/>あまさに満たされ, なれをほめうたう！<br/>たのしみわき, よろこび満つ！<br/>',NULL,49205,4);
INSERT INTO stanza VALUES('J142','5','なれのあいらしさ, 言い尽くせず！<br/>にゅう和,こまやかさ, こころを引き寄す;<br/>ともにいまさば, すべて足れり！<br/>',NULL,49206,5);
INSERT INTO stanza VALUES('J143','1','うるわしいイェス！ 自ぜんをおさむ！<br/>かみの子,ひとの子よ！<br/>生けることば, わがよろこび,<br/>わがほこりなる主！<br/>',NULL,49207,1);
INSERT INTO stanza VALUES('J143','2','みどりの野辺, とりうたうもり,<br/>はな咲くそのよりも,<br/>あまいかおり, うるわしいイェス,<br/>こころよりたとう。<br/>',NULL,49208,2);
INSERT INTO stanza VALUES('J143','3','あまい日ざし, ゆめさそうつき,<br/>きらめく星座よりも,<br/>イェスはさらに, 照りかがやく！<br/>まことのひかりよ。<br/>',NULL,49209,3);
INSERT INTO stanza VALUES('J143','4','天と地にある, うるわしいもの,<br/>みなイェスに見いだせり;<br/>イェスこそわが 愛すべきもの,<br/>さいこうの主なり。<br/>',NULL,49210,4);
INSERT INTO stanza VALUES('J144','1','どこからはじめましょう？ 主のしゅくふくのはなしを。<br/>つみと死から解かれて, 奴隷でもてきでもない;<br/>どれほど主を礼はいし, たかく上げましょうか？<br/>',NULL,49211,1);
INSERT INTO stanza VALUES('J144','2','主のあたえるなぐさめ, くちでは言い尽くせない;<br/>かつてのいかりの子ら, いま,かみをちちとする！<br/>つみのゆるしを知った, これぞ天のしゅくふく。<br/>',NULL,49212,2);
INSERT INTO stanza VALUES('J144','3','わがこころ,キリストで 満ちて,ゆたかさあふれる;<br/>主よ,なれはうたのうた, あいするすくいぬしよ;<br/>われうたう,天上のおう, 栄光,とわにあるように！<br/>',NULL,49213,3);
INSERT INTO stanza VALUES('J144','4','主こそすべてにまさり, よりうつくしく,せいけつ;<br/>なれはあい,めぐみ満ち, くるしみ,御身を捨てる;<br/>なれを賛美,礼はいする, わがれいと実際もて。<br/>',NULL,49214,4);
INSERT INTO stanza VALUES('J145','1','イェス，おうの王！ 主,キリスト！<br/>天使ら，はいし， われら，ほむ；<br/>うるわしい主， ふかく知り，<br/>うるわしい主， ほめうたう。<br/>',NULL,49215,1);
INSERT INTO stanza VALUES('J145','2','地のたのしみ， みなむなしい；<br/>天に主なくば， くらくなる。<br/>主のえい光は， 天のひかり；<br/>イェスのえい光, 地のひかり。<br/>',NULL,49216,2);
INSERT INTO stanza VALUES('J145','3','主より去れば， 死の世かい，<br/>主ともにいて， いのちあり。<br/>全被ぞうぶつ， 主より成る，<br/>されどなれは， ひとと成る。<br/>',NULL,49217,3);
INSERT INTO stanza VALUES('J145','4','イェス！うるわしい， 主はすべて；<br/>かみのえい光， イェスご自身。<br/>御かお見つめ， めぐみ受く；<br/>このめぐみで， 満たしませ。<br/>',NULL,49218,4);
INSERT INTO stanza VALUES('J146','1','さあ，うたえ，たのしく， キリストほめよ；<br/>千まんのくちびるあれど， うたはーひとつ。<br/>',NULL,49219,1);
INSERT INTO stanza VALUES('J146','2','受けませさん美を， 御座の小ひつじ!<br/>ひくくなりて，ほふらるは， われらーのため。<br/>',NULL,49220,2);
INSERT INTO stanza VALUES('J146','3','イェスこそ受けませ, えいこう,けん威;<br/>無げんのしゅくふくとわに, なれにー帰する!<br/>',NULL,49221,3);
INSERT INTO stanza VALUES('J146','4','間もなくせい徒ら, 引き上げられて,<br/>賛美のこえは,ぜん宇宙に 満ちあーふれる。<br/>',NULL,49222,4);
INSERT INTO stanza VALUES('J146','5','全宇ちゅうこぞって, 小ひつじほめよ;<br/>地にくだり,死なれた主は, えい光ー受ける。<br/>',NULL,49223,5);
INSERT INTO stanza VALUES('J147','1','栄こう主にあれ, 天地はかん声上げ,<br/>賛美する;<br/>めぐみのゆえ, 永遠にうたう,<br/>「小ひつじこそふさわしい」。<br/>',NULL,49224,1);
INSERT INTO stanza VALUES('J147','2','すくわれしひと, 御座につどい来て,<br/>賛美する;<br/>主の血のゆえ, 和かい受ける,<br/>「主こそ賛美にふさわしい」。<br/>',NULL,49225,2);
INSERT INTO stanza VALUES('J147','3','かみの種ぞくは ひとつこころもて,<br/>賛美する;<br/>くちをそろえ, 歓喜しうたう,<br/>「主こそ感謝にふさわしい」。<br/>',NULL,49226,3);
INSERT INTO stanza VALUES('J147','4','すべて変わるも, われらは変わらず,<br/>賛美する;<br/>こえもたかく, 絶えずうたう,<br/>「小ひつじこそふさわしい」。<br/>',NULL,49227,4);
INSERT INTO stanza VALUES('J148','1','おお,主イェス,御座に向かって, よろこび,さん美します！<br/>しゅくふくゆえ,礼はいする, 賛美はなれにふさわしい。<br/>',NULL,49228,1);
INSERT INTO stanza VALUES('J148','chorus','主,ふさわしい！主,ふさわしい！ 賛美はただ主にふさわしい！<br/>礼拝し,ながえい光述べる, 賛美はなれにふさわしい。<br/>',NULL,49229,2);
INSERT INTO stanza VALUES('J148','2','なれは真のかみ,真のひと, われらの犠せいとなる;<br/>おんなのすえとし,世に来て, へびのかしらをくだく！<br/>',NULL,49230,3);
INSERT INTO stanza VALUES('J148','3','創造ぬしが,ひとと成って, 十字架にくぎづけらる！<br/>自ぶんをすくうことなく, すすんで苦はいを飲む！<br/>',NULL,49231,4);
INSERT INTO stanza VALUES('J148','4','死のちからを打ちやぶり, 栄光の勝利,だいしょう利！<br/>なれおもうとき賛美あふれ, ハデスの門は全めつす。<br/>',NULL,49232,5);
INSERT INTO stanza VALUES('J149','1','主よ,さん美なれに帰す, とわに受けまーせ;<br/>ああ,はかりがたきは, なーがーあいとめぐみ。<br/>',NULL,49233,1);
INSERT INTO stanza VALUES('J149','2','かんげきのこころもて, 御名をほめたーとう;<br/>このあふれるめぐみ, 大ーきーくひょう現する。<br/>',NULL,49234,2);
INSERT INTO stanza VALUES('J149','3','ふかきかな主のゆるし, ただ主をはいーす;<br/>このあいとみちから, えーいー遠に変わらず。<br/>',NULL,49235,3);
INSERT INTO stanza VALUES('J149','4','みちびきの主ははじめ, またおわりなーり;<br/>変わらぬさん美もて, さーらーによりたのまん。<br/>',NULL,49236,4);
INSERT INTO stanza VALUES('J149','5','賛美！さん美！すくいぬし, こえたからかーに;<br/>主よ,えい光をすべて, えーいー遠に受けませ。<br/>',NULL,49237,5);
INSERT INTO stanza VALUES('J150','1','すべてをふくむ主よ, いま,ながうちにいる！<br/>主はとわの分けまえ, 主はわれのすべて。<br/>',NULL,49238,1);
INSERT INTO stanza VALUES('J150','2','なれはわれらの知恵, なれにて,すくわれる;<br/>なれはすくいのみち, めぐみを得るみち。<br/>',NULL,49239,2);
INSERT INTO stanza VALUES('J150','3','主,われらの義となり, かみの要きゅう満たす;<br/>主のなかで義とされ, つみさだめはなし。<br/>',NULL,49240,3);
INSERT INTO stanza VALUES('J150','4','なれはわれらのせい, われら,つくり変える;<br/>主のなかで聖とされ, どうけい化される。<br/>',NULL,49241,4);
INSERT INTO stanza VALUES('J150','5','主は,われらのあがない, 主に似たものとする;<br/>からだを変ぼうさせ, ながかたち得さす。<br/>',NULL,49242,5);
INSERT INTO stanza VALUES('J150','6','主よ,なれを記ねんし, ながすべてきょう受す;<br/>「主よ,はやく来ませ」と, さいりんうながす。<br/>',NULL,49243,6);
INSERT INTO stanza VALUES('J150','7','このまえあじわいは, なんとあまきことよ;<br/>されど,まったききょう受, どうざいをのぞむ。<br/>',NULL,49244,7);
INSERT INTO stanza VALUES('J151','1','わがため裂かれた, 永えんのいわよ;<br/>霊にてなれを飲み, けつごうされる。<br/>この揺りうごかぬ いわに建てらる;<br/>主とのけつごうを, 振るうものはなし。<br/>',NULL,49245,1);
INSERT INTO stanza VALUES('J151','chorus','何たるなが価値よ, なれはわがもの;<br/>愛のゆえに記念し, 豊富に満ち足る。<br/>',NULL,49246,2);
INSERT INTO stanza VALUES('J151','2','多くのこころみを 受けたいしなり;<br/>われらにしたわれ,　 かみにはとうとし。<br/>依りたのむに足る, たしかなちから;<br/>かみにえらばれた, 活気に満ちるいし。<br/>',NULL,49247,3);
INSERT INTO stanza VALUES('J151','3','かみの据えられた, 土だいのいしよ;<br/>たしかな土だいに とわにまもらる。<br/>われらの据え得る いしずえはなし;<br/>なれこそえい遠の 唯いつのいしずえ。<br/>',NULL,49248,4);
INSERT INTO stanza VALUES('J151','4','霊のいえのすみの かしらいしなり;<br/>ユダヤ人,異ほう人, ひとつにきずく。<br/>なれはかしらいし, めぐみをあたえ,<br/>栄こうもておおい, よろこびで満たす。<br/>',NULL,49249,5);
INSERT INTO stanza VALUES('J152','note','この詩は以下のように五つに分けることができる：<br/>１．1－8節，26節。<br/>２．1節，9－13節，26節。<br/>３．1節，14－17節，26節。<br/>４．1節，18－21節，26節。<br/>５．1節，22－25節，26節。<br/>',NULL,49250,1);
INSERT INTO stanza VALUES('J152','1','何とほう富な主よ, 愛は豊富しめす！<br/>われら無限のゆたかさ, 霊にあり享受する。<br/>',NULL,49251,2);
INSERT INTO stanza VALUES('J152','2','なれはことば，かみ, かみ,ともにあり；<br/>にくたいとなり ひとにかみをかたり出す。<br/>',NULL,49252,3);
INSERT INTO stanza VALUES('J152','3','主はかみのまく屋, そこに栄光見る；<br/>なれはかみの真のみや, かみはそこに住む。<br/>',NULL,49253,4);
INSERT INTO stanza VALUES('J152','4','なれはひとり子で, ちちを宣言した；<br/>かみのいのち，性しつを, われらに得させる。<br/>',NULL,49254,5);
INSERT INTO stanza VALUES('J152','5','ひとの子，われらと おなじせいしつ，<br/>われらをかみの子とし, 主のかたちとする。<br/>',NULL,49255,6);
INSERT INTO stanza VALUES('J152','6','なれは主，キリスト, 万有の主，メシア；<br/>万有を持ち，万有にあり, 無限にひろいかた！<br/>',NULL,49256,7);
INSERT INTO stanza VALUES('J152','7','主は十字架で死に, 血とみずながし，<br/>あがない，いのち得させ, われをたからとす！<br/>',NULL,49257,8);
INSERT INTO stanza VALUES('J152','8','主は栄こう受けて, いのちの霊，来る；<br/>すべてをふくむれいは, 豊富を享受させる。<br/>',NULL,49258,9);
INSERT INTO stanza VALUES('J152','9','主,いのちのひかり, くらやみに照る；<br/>わがこころを照らして, わがこころ満たす。<br/>',NULL,49259,10);
INSERT INTO stanza VALUES('J152','10','主は永遠のいのち, 死んだれい,生かす;<br/>われらを死より解いて, いのち享受させる。<br/>',NULL,49260,11);
INSERT INTO stanza VALUES('J152','11','主はかみの実さい, かみ,よろこばす,<br/>主のかぎりないことを, われらに知らせる。<br/>',NULL,49261,12);
INSERT INTO stanza VALUES('J152','12','主は唯いつのみち, かみにみちびく;<br/>いのちと実さいのみち, 栄こうにもたらす。<br/>',NULL,49262,13);
INSERT INTO stanza VALUES('J152','13','主,不思議な復かつ, 一切の死に勝利;<br/>復かつのたい能により, 主とともに生きる。<br/>',NULL,49263,14);
INSERT INTO stanza VALUES('J152','14','主,かみの小ひつじ, あがない成就す;<br/>主はせいれいをあたえ, いのちを得させる。<br/>',NULL,49264,15);
INSERT INTO stanza VALUES('J152','15','主は青どうのへび, つみよりすくう;<br/>じゅう字架に上げられて, あく魔をほろぼす。<br/>',NULL,49265,16);
INSERT INTO stanza VALUES('J152','16','主はぼく者,また門, かこいより出す;<br/>われはいま自由を得て, まき場でしょくする。<br/>',NULL,49266,17);
INSERT INTO stanza VALUES('J152','17','主は洗ばんのよう, あらいきよめる;<br/>まじわりにありまもり, あいとめぐみあとう。<br/>',NULL,49267,18);
INSERT INTO stanza VALUES('J152','18','主は裂かれたいわ, 生けるみず出す;<br/>このしん鮮なみず飲み, つかれ,いやされる。<br/>',NULL,49268,19);
INSERT INTO stanza VALUES('J152','19','主は生けるいずみ, また生けるみず;<br/>このみずを飲むものは, 永えんにかわかず。<br/>',NULL,49269,20);
INSERT INTO stanza VALUES('J152','20','主はいのちのかて, 豊富なかつりょく;<br/>無限のほう富もたらし, わがれい,やしなう。<br/>',NULL,49270,21);
INSERT INTO stanza VALUES('J152','21','主はいのちのいき, 霊にて呼吸する;<br/>主により生き,行どうし, ご自身を享受する。<br/>',NULL,49271,22);
INSERT INTO stanza VALUES('J152','22','主,ひとつぶのむぎ, 地に落ちて死に,<br/>多くのむぎを生み出し, からだを形成する。<br/>',NULL,49272,23);
INSERT INTO stanza VALUES('J152','23','主は天のぶどうの木, われらそのえだ;<br/>なれに住み,むすばれて, ながすべて享受す。<br/>',NULL,49273,24);
INSERT INTO stanza VALUES('J152','24','主は真のはなむこ, われらはなよめ;<br/>霊にありなれとひとつ, あいの豊富,享受す。<br/>',NULL,49274,25);
INSERT INTO stanza VALUES('J152','25','なれは天のはしご, 天と地をむすぶ;<br/>われら,なれをとおして, なれのみやとなる。<br/>',NULL,49275,26);
INSERT INTO stanza VALUES('J152','26','「わたしはある」主は, ひつよう満たす;<br/>主のすべてを享受して, かみに栄光を帰す。<br/>',NULL,49276,27);
INSERT INTO stanza VALUES('J153','1','主よ,なれはわが護えい, たすけなぐさむ;<br/>また御まえにとりなす, われのちゅう保者。<br/>',NULL,49277,1);
INSERT INTO stanza VALUES('J153','2','主よ,なれはわがカウンセラー, またわが弁護者;<br/>わがすべてをとりなし, われをたすける。<br/>',NULL,49278,2);
INSERT INTO stanza VALUES('J153','3','かみのよろこびのため, 主はすべて成し,<br/>てんで,またわがうちで, すべて解けつす。<br/>',NULL,49279,3);
INSERT INTO stanza VALUES('J153','4','なれはないじゅうのれい, つねにとりなす;<br/>天で弁護し,わがうちで, うめいていのる。<br/>',NULL,49280,4);
INSERT INTO stanza VALUES('J153','5','かみのみこころにより, めぐみ,ほどこす;<br/>復かつのたいのうにて, わがうち強化す。<br/>',NULL,49281,5);
INSERT INTO stanza VALUES('J153','6','いのちあたえるれいは, よわさかえりみ,<br/>れいにありわれ生かす, ながたい能もて。<br/>',NULL,49282,6);
INSERT INTO stanza VALUES('J153','7','ながあいはご自身もて, とわにつかえる;<br/>なれをわがすべてとし, われら豊満とす。<br/>',NULL,49283,7);
INSERT INTO stanza VALUES('J154','1','主はそうせいのまえに, ちちのふところで,<br/>ちちのえいこうにあり かみのーひとり子。<br/>かつて,ちち,われらに, なれをあたえしとき,<br/>霊にありわれらに来て, 全ほう満あらわす。<br/>',NULL,49284,1);
INSERT INTO stanza VALUES('J154','2','なれ,死と復かつにより かみの長子となる;<br/>われらは再せいされて, 多くの子らとなる。<br/>われら,ながぞうしょく, なれのきょうだいたち,<br/>ながえいこうのコピー, 神せいなかくだい。<br/>',NULL,49285,2);
INSERT INTO stanza VALUES('J154','3','かつてひとつぶのむぎ, 地に落ちて死ねり;<br/>なが死と復かつにより, いのちぞうしょくす。<br/>なれにより生まれて, われらおおくのむぎ;<br/>調和されてひとつパン, 全ほう満あらわす。<br/>',NULL,49286,3);
INSERT INTO stanza VALUES('J154','4','われら,なれのふくせい, からだとはなよめ,<br/>なれのひょう現,ほうまん, えい遠に住み合う。<br/>われら,なれの継ぞく, いのちの増加,かく大,<br/>せいちょう,豊富な余じょう, 栄光の主とひとつ。<br/>',NULL,49287,4);
INSERT INTO stanza VALUES('J155','1','きゅうやくの予ひょうは, すべてがなれの絵;<br/>絵の表徴を見るとき, なれはなんととうとし！<br/>かく面のうるわしさ, 鑑しょうするたびに,<br/>なれはわがすべてと, われはれいはいする！<br/>',NULL,49288,1);
INSERT INTO stanza VALUES('J155','2','なれはわがすぎこし, かみは過ぎ越さる;<br/>ながあがないにより, かみとの和かい得る。<br/>なれ,かみの小ひつじ, ころされ,血ながす;<br/>その血にあがなわれ, なれを食べて生きる。<br/>',NULL,49289,2);
INSERT INTO stanza VALUES('J155','3','天よりくだりしパン, なれ,いのちのかて;<br/>われら,なれを食べて, なれとちょう和される。<br/>小ひつじ,パンはすべて, いのちを予ひょうす;<br/>宴せきでなれを食べ, ながほう富を享受す。<br/>',NULL,49290,3);
INSERT INTO stanza VALUES('J155','4','なれは天よりのマナ, 日ごとのしょくもつ;<br/>やしなわれ,ちから得, ひつよう満たされる。<br/>なれまた生けるいわ, 裂かれ,みずながす;<br/>生けるみずを飲めば, とわにかわきはなし。<br/>',NULL,49291,4);
INSERT INTO stanza VALUES('J155','5','主よ,なれカナンの地, ゆたかでうるわし,<br/>ちちとみつはながれ, そのさんぶつは豊富。<br/>かみをれいはいして, たがいにまじわり,<br/>愛にてけつごうされ, ともにけんぞうさる。<br/>',NULL,49292,5);
INSERT INTO stanza VALUES('J156','1','なれ,義なるたいよう, いやすひかりに富む;<br/>御かおのかがやきは, いのちとへいあん。<br/>',NULL,49293,1);
INSERT INTO stanza VALUES('J156','2','かみのあい,あわれみ, 主をわれにのぞます;<br/>暗こくに座すひとに, 御かおはかがやく。<br/>',NULL,49294,2);
INSERT INTO stanza VALUES('J156','3','くもなく澄みわたる, なれはあさのひかり;<br/>われら地のわかくさ, ひかりで成ちょうす。<br/>',NULL,49295,3);
INSERT INTO stanza VALUES('J156','4','めぐみ，あいのひかり, あけぼののように増す;<br/>わがうちを照らして, 真ひるへといたる。<br/>',NULL,49296,4);
INSERT INTO stanza VALUES('J156','5','晴れて,ひかりは差し, 苦なんのあめは去る;<br/>あわれみ,慈あいもて, なれ絶えず照らす。<br/>',NULL,49297,5);
INSERT INTO stanza VALUES('J156','6','主は明けのみょうじょう， 目覚めさすほうしょう;<br/>やみのなかで照らす, 主をあいすものを。<br/>',NULL,49298,6);
INSERT INTO stanza VALUES('J156','7','ながひかりをしたい, わが目あかるくされ,<br/>目を覚ましていのり, さい臨待ちのぞむ。<br/>',NULL,49299,7);
INSERT INTO stanza VALUES('J157','1','なれをおもうたび, 　われられいはいす;<br/>くすしく,ほう富な主, 　いかにあいすべき。<br/>',NULL,49300,1);
INSERT INTO stanza VALUES('J157','chorus','ひつよう満たす主よ, 　賛美あふれながる！<br/>わがねがいにまさり, 　絶えず主は満たす！<br/>',NULL,49301,2);
INSERT INTO stanza VALUES('J157','2','まことになれかみ, 　ひかり,あいのかみ;<br/>われのいのちとなり, 　めぐみをあたえる。<br/>',NULL,49302,3);
INSERT INTO stanza VALUES('J157','3','まことになれひと, 　きよく,柔和なひと;<br/>かみによろこばれて, 　われをあいすひと。<br/>',NULL,49303,4);
INSERT INTO stanza VALUES('J157','4','なれ,いやしくなり, 　奴れいとさえなる;<br/>死ぬまでしたがえり, 　われらすくうため。<br/>',NULL,49304,5);
INSERT INTO stanza VALUES('J157','5','めぐみの主,また王, 　かみに立てられる;<br/>いのち,愛もて支配し, 　われともにおさむ。<br/>',NULL,49305,6);
INSERT INTO stanza VALUES('J157','6','なれをおもうたび, 　なれをきょう受する;<br/>あいにて主ご自身を 　とわにあたえませ。<br/>',NULL,49306,7);
INSERT INTO stanza VALUES('J158','1','主よ,なれアルフア, なれはオメガ,<br/>さい初でさい後, なれはすべて。<br/>万ぶつ,なれにて ほうかつされ;<br/>なれはばんぶつを そうかつする。<br/>',NULL,49307,1);
INSERT INTO stanza VALUES('J158','2','主よ,なれアルフア, 万有のかい始;<br/>なれまたオメガ, 万有の終わり。<br/>すべてのもん字, またぶんしょう,<br/>すべてはなれにて 構せいされる。<br/>',NULL,49308,2);
INSERT INTO stanza VALUES('J158','3','なれ,受造の最初, 万有のかしら;<br/>すべてのさい後, 万有終わらす。<br/>すべてのものは なれよりいで,<br/>なれにてばん有は そんざいする。<br/>',NULL,49309,3);
INSERT INTO stanza VALUES('J158','4','ユニｰクなかい始, 万有のそう始;<br/>なれはすべてに さきだちゆく。<br/>無二のしゅうけつ, すべてを継ぎ,<br/>なれにてすべては 終わらされる。<br/>',NULL,49310,4);
INSERT INTO stanza VALUES('J158','5','主よ,なれを拝し, なれをあいす;<br/>アルフアでオメガ, はじめ,終わり。<br/>さい初でさい後, なれはすべて;<br/>なれをほめたたえ, れいはいする。<br/>',NULL,49311,5);
INSERT INTO stanza VALUES('J158','note','［１　ほうかつ――一つにまとめること<br/>そうかつ――締めくくり］<br/>',NULL,49312,6);
INSERT INTO stanza VALUES('J159','1','主よ,なれはいのちの木, いのちの供きゅう;<br/>なが実は豊富ないのち, われのしょくもつ。<br/>',NULL,49313,1);
INSERT INTO stanza VALUES('J159','2','主はまことのぶどうの木, いのちのいずみ;<br/>われはながうちに住み, なが豊富,享受す。<br/>',NULL,49314,2);
INSERT INTO stanza VALUES('J159','3','主よ,なれはりんごの木, われは鑑賞する;<br/>なが木かげにいこいつ, あまき実,享受す。<br/>',NULL,49315,3);
INSERT INTO stanza VALUES('J159','4','主よ,なれはいやしの木, わがために死ぬ;<br/>木にかかり,ころされて, われ,いやされる。<br/>',NULL,49316,4);
INSERT INTO stanza VALUES('J159','5','主よ,なれはかみのえだ, かみの豊満,住む;<br/>なれにてめぐみ,実さい, われらは受ける。<br/>',NULL,49317,5);
INSERT INTO stanza VALUES('J159','6','なれはダビデのえだと, 受にくしてなる;<br/>それにより真の人せい, われら理かいす。<br/>',NULL,49318,6);
INSERT INTO stanza VALUES('J159','7','なれは芽を出したつえ, 無げんのいのち;<br/>ふっかつのたいのうに, 死は打ち勝てず。<br/>',NULL,49319,7);
INSERT INTO stanza VALUES('J159','8','主はあの浮かばせる木, われ,しずむ「おの」;<br/>いのちのたいのうにて, 死をせいふくす。<br/>',NULL,49320,8);
INSERT INTO stanza VALUES('J159','9','主は「ゆう名なしょくぶつ」, ほう富を享受す;<br/>われらなれを記ねんし, なれをほめたとう。<br/>',NULL,49321,9);
INSERT INTO stanza VALUES('J159','note','［９　有名な植物――エゼキエル34:29］<br/>',NULL,49322,10);
INSERT INTO stanza VALUES('J160','1','主はかみのあかし, 　律法にまさる;<br/>律法はながしゅく図, 　なれ,その実際。<br/>律法はかみのせつ明, 　かみのーびょう写;<br/>なれ,かみの実さい, 　かみの住まい。<br/>',NULL,49323,1);
INSERT INTO stanza VALUES('J160','2','あかしのはこには 　律ぽうがある;<br/>ながうちにかみは 　安じゅうされる。<br/>アカシアでつくられ, 　金でおおわれる;<br/>なれはじんせいと 　 神性のちょう和。<br/>',NULL,49324,2);
INSERT INTO stanza VALUES('J160','3','なれは受にくして, 　しんのまく屋;<br/>めぐみと実さいは, 　なれに満ちる。<br/>なれはかみのことば, 　かみのえいこう;<br/>あいとひかりもて, 　かみ,あらわす。<br/>',NULL,49325,3);
INSERT INTO stanza VALUES('J160','4','なれはかみのみや, 　なれ,真のみや;<br/>かみはなれに住み, 　かみを表現す。<br/>サタンの破かいにより, 　死に置かれるも,<br/>なれは復かつにて 　みやを建造す。<br/>',NULL,49326,4);
INSERT INTO stanza VALUES('J160','5','みやこはなが豊満, 　ながはなよめ;<br/>ながかくだい,また, 　豊富のひょう現。<br/>かみ,みやこのひかり, 　なれはともし火;<br/>かみのえいこうは, 　ひとを照らす。<br/>',NULL,49327,5);
INSERT INTO stanza VALUES('J160','6','まくや,はこ,律ぽう, 　みや,みやこは,<br/>すべてなれご自身, 　豊富あらわす。<br/>なれはちゅうしんせい, 　また普へんせい！<br/>かみ・ひとなる主を 　われはとうとぶ。<br/>',NULL,49328,6);
INSERT INTO stanza VALUES('J161','1','なんとほう富な主よ, なれはわがすべて;<br/>わがひつようすべて, なれ,満たされる,<br/>なれの「である」をほめ, わがれいははいす,<br/>ながほう富を享受し, かん謝あふれる。<br/>',NULL,49329,1);
INSERT INTO stanza VALUES('J161','2','なれ,かみの預げん者, かみの権威を持ち,<br/>モーセのよう御むね しめし,みちびく,<br/>またヨナのよう,死と 復かつをけい過す,<br/>このしるしを通して われはしんじる。<br/>',NULL,49330,2);
INSERT INTO stanza VALUES('J161','3','なれ,かみの預げん者, ひかり,ちから満つ,<br/>エリシャのよう愛満ち, 奇せきおこなう；<br/>なれはイザヤのよう キリストけい示し,<br/>めぐみ,ほう富,実さい, われに享受さす。<br/>',NULL,49331,3);
INSERT INTO stanza VALUES('J161','4','ひとからおこされた せいなるさい司は,<br/>アロンのように召され, かみにつかえる。<br/>われのよわさ,にない, かみにもたらして,<br/>あいとちからにより, とりなし,保護す。<br/>',NULL,49332,4);
INSERT INTO stanza VALUES('J161','5','かみにつかわされた おうなるさい司は,<br/>メルキゼデクのよう, かみのほう仕者。<br/>パンとぶどう酒もて かみをもたらして,<br/>てき時にきょうきゅうし, 豊富を享受さす。<br/>',NULL,49333,5);
INSERT INTO stanza VALUES('J161','6','かみのみこころくむ ダビデおうのよう,<br/>てきをせいふくして みこころ満たす。<br/>権威得て,御座に着き, ひとの手によらず,<br/>神聖なけん威をもて, なれは支はいす。<br/>',NULL,49334,6);
INSERT INTO stanza VALUES('J161','7','ソロモンおうのよう, へい和もておさめ,<br/>知恵もてかみのみや, 建造し経えいす。<br/>いま,せい徒のなかで あいもて支はいし,<br/>かの日,われらととも, 王けんあらわす。<br/>',NULL,49335,7);
INSERT INTO stanza VALUES('J161','8','さい司,おう,預げん者, なれは何とほう富,<br/>なが価値をわれらは あいし,とうとぶ。<br/>なが「である」をあいし, なれに捕らえられ,<br/>とわになれをはいし, かん謝,さん美す。<br/>',NULL,49336,8);
INSERT INTO stanza VALUES('J162','1','わが主は「おんなのすえ」, 生まれ,てき打倒す;<br/>なれは人せいを取り, 死に,しょう利得られる。<br/>かみ,にくたいと成り, にくのからだ着る;<br/>死にてサタンほろぼし, 死のちから消し去る。<br/>',NULL,49337,1);
INSERT INTO stanza VALUES('J162','2','かみのやくそくにて, 「アブラハムのすえ」,<br/>万みんにしゅくふくを 得させるために来る。<br/>アブラハムのまえに 「わたしはある」主は,<br/>そのすえとして来て, やくそくをじょう就す。<br/>',NULL,49338,2);
INSERT INTO stanza VALUES('J162','3','「ダビデのすえ」なる主, 王こくをおこして,<br/>栄こう,建ぞうのため, すでに御座に着かる。<br/>「ダビデのすえ」の主は 「わが主」と呼ばれる;<br/>「ダビデの根」なるなれ, とわに「ばんゆうの主」。<br/>',NULL,49339,3);
INSERT INTO stanza VALUES('J162','4','人性もつ「みどりご」は, 「ぜんのうのかみ」と,<br/>「おとこの子」なる主は, 「永遠のちち」と呼ばる。<br/>すべてのしゅくふくは, 信じることにあり,<br/>なれにしかりがあり, なれはそのじっさい！<br/>',NULL,49340,4);
INSERT INTO stanza VALUES('J163','1','主はかみの愛子, かみのかたち;<br/>聖徒の分けまえ, われ,あずかる。<br/>全被造ぶつにて 最初に生まる;<br/>ばん有,なれを通し, なれへと帰す。<br/>',NULL,49341,1);
INSERT INTO stanza VALUES('J163','2','主,万有の由らい, 存在の秘みつ;<br/>主,万ゆうの中心, 万有まとめる。<br/>なれは死人より 最初に生まる;<br/>えいこうのかしら, 召会はからだ。<br/>',NULL,49342,2);
INSERT INTO stanza VALUES('J163','3','いっさいの豊満は, なれにやどる;<br/>万ぶつの首位と ならせるため。<br/>死にて万ぶつを 和かいさせる;<br/>われらを御まえに ささげるため。<br/>',NULL,49343,3);
INSERT INTO stanza VALUES('J163','4','主,かみのすべて, かみのおく義;<br/>知恵と知しきは なれにやどる。<br/>主はわれに住み, 栄光ののぞみ,<br/>われらを成就して, 御むね満たす。<br/>',NULL,49344,4);
INSERT INTO stanza VALUES('J163','5','なれはじっさい, すべてはかげ;<br/>なれに根ざして, 建て上げらる。<br/>豊富を享受して, 豊まんとなり,<br/>かみはぞう加して, せいちょうする。<br/>',NULL,49345,5);
INSERT INTO stanza VALUES('J163','6','われ,主とともに, かみにあるが,<br/>栄こうのうちに あらわされる。<br/>あたらしいひとの なれはすべて;<br/>ばん有のキリスト, なんとほう富！<br/>',NULL,49346,6);
INSERT INTO stanza VALUES('J164','1','なれはかみの御子, かみのかん全な表現;<br/>かみはなれにより かんぜんにかたる。<br/>',NULL,49347,1);
INSERT INTO stanza VALUES('J164','2','なれ,かみのかたち, えいこうのかがやき;<br/>なれ,かみご自しん, かみをかがやかす。<br/>',NULL,49348,2);
INSERT INTO stanza VALUES('J164','3','万ぶつはなれにて つくられ,ささえられ,<br/>かの日なれに帰し, なれ,すべてを継ぐ。<br/>',NULL,49349,3);
INSERT INTO stanza VALUES('J164','4','つみのきよめ成し, かみのみぎに座して,<br/>てき,あし台とする 御むねの成就,待つ。<br/>',NULL,49350,4);
INSERT INTO stanza VALUES('J164','5','御つかいにまさり, とうとき御名受ける;<br/>死より復かつして, かみの御子となる。<br/>',NULL,49351,5);
INSERT INTO stanza VALUES('J164','6','なが王こくは義で, 御座はとわにいたる;<br/>パｰトナｰにまさって, あぶらを塗られる。<br/>',NULL,49352,6);
INSERT INTO stanza VALUES('J164','7','なれ,真のひとの子, われらの人性を持つ;<br/>われのために死に, いのちを得させる。<br/>',NULL,49353,7);
INSERT INTO stanza VALUES('J164','8','なれ,栄光,尊貴を得, ばんぶつはひれ伏す;<br/>なれは苦難を経て, すくいのキｬプテン。<br/>',NULL,49354,8);
INSERT INTO stanza VALUES('J164','9','なが死はサタンを ほろぼし,死より解く;<br/>われらをせいとし, 栄光へともたらす。<br/>',NULL,49355,9);
INSERT INTO stanza VALUES('J164','10','なが兄だいたちに ちちの名言いあらわす;<br/>しょうかいのなかで, ちちをほめたとう。<br/>',NULL,49356,10);
INSERT INTO stanza VALUES('J164','11','建造者がいえより とうとばれるように,<br/>主はモｰセにまさり, 栄光にあたいする。<br/>',NULL,49357,11);
INSERT INTO stanza VALUES('J164','12','なれ,しんのヨシュア, あんそくにもたらす;<br/>なれ,まったきすくい, われらのしんこう。<br/>',NULL,49358,12);
INSERT INTO stanza VALUES('J164','13','なれ,てんの安そく, いま,わがれいに住む;<br/>良き地にいるよう, ながほう富享受す。<br/>',NULL,49359,13);
INSERT INTO stanza VALUES('J164','14','かみのだいさい司, アロンよりもとうとい;<br/>いとたかきてんの せい所でとりなす。<br/>',NULL,49360,14);
INSERT INTO stanza VALUES('J164','15','真のメルキゼデク, いのちの大能により,<br/>「パンとぶどう酒」を, 絶えずきょう給する。<br/>',NULL,49361,15);
INSERT INTO stanza VALUES('J164','16','まさったいけにえ, 永遠のせい霊により,<br/>かみにささげられ, その効き目,得さす。<br/>',NULL,49362,16);
INSERT INTO stanza VALUES('J164','17','まさったけいやく, 血により立てられる;<br/>われらは分を持つ, かくじつな新やく。<br/>',NULL,49363,17);
INSERT INTO stanza VALUES('J164','18','なれは合法てきな 新やくのせつりつ者;<br/>なれはあとうかた, われはすべて継ぐ。<br/>',NULL,49364,18);
INSERT INTO stanza VALUES('J164','19','なれは新契やくの 執行者またちゅう保者;<br/>復かつのいのちで, かみのさだめ成す。<br/>',NULL,49365,19);
INSERT INTO stanza VALUES('J164','20','主よ,なれは先駆者, まくのうちにはいる;<br/>われは営所を出て, なれにしたがい行く。<br/>',NULL,49366,20);
INSERT INTO stanza VALUES('J164','21','主は信仰の創始者, またそのかんせい者;<br/>われ,信仰と愛もて, したがい,前進する。<br/>',NULL,49367,21);
INSERT INTO stanza VALUES('J164','22','なが価値は無げん, ながすべてをとうとぶ;<br/>なれは完全完備で, 人知をちょうえつす。<br/>',NULL,49368,22);
INSERT INTO stanza VALUES('J165','1','主はささげもの, かみは用意す;<br/>その意義は甘美, ゆたか,えい光！<br/>ちちのみこころ, 満たし,成就し,<br/>われのひつようも, すべて満たす！<br/>',NULL,49369,1);
INSERT INTO stanza VALUES('J165','2','なれははんさい, 火にて焼かれ,<br/>香ばしいかおり, かみ,満ぞくす。<br/>主,御まえに生き, 御むねもとむ,<br/>きずなきいけにえ, わがしょくもつ。<br/>',NULL,49370,2);
INSERT INTO stanza VALUES('J165','3','主はあぶら,乳香, 混ぜた素さい,<br/>きよく,こまやか, あまく,かん全。<br/>なれは平安さい, 平あん成就し,<br/>かみとひと,ともに なれを享受す。<br/>',NULL,49371,3);
INSERT INTO stanza VALUES('J165','4','なれはざいさい, つみとなりて,<br/>死,通してわれを あがなわれる。<br/>なれはけんさい, とがをにない,<br/>かみの義を満たし, ゆるし得さす。<br/>',NULL,49372,4);
INSERT INTO stanza VALUES('J165','5','なれはようさい, 復かつにより,<br/>ハデス,死,やみに, しょう利を得る。<br/>なれ,また挙さい, しょうてんして,<br/>てんのパンとなり, われを満たす。<br/>',NULL,49373,5);
INSERT INTO stanza VALUES('J165','note','［２ はんさい――全焼のささげ物，<br/>３ 素さい――穀物のささげ物，<br/>平安さい――平安のささげ物，<br/>４ ざいさい――罪のためのささげ物，<br/>けんさい――違犯のためのささげ物，<br/>５ ようさい――揺り動かすささげ物，<br/>挙さい――挙げるささげ物］<br/>',NULL,49374,6);
INSERT INTO stanza VALUES('J166','1','主よ,御名のなかで あつまり,なれのみ見る;<br/>臨ざいは歓喜させ, 　　われを呼び寄す。<br/>',NULL,49375,1);
INSERT INTO stanza VALUES('J166','2','ちち,なれをあいす, そのあいはかぎりなし;<br/>ちちのみおもいを, 　　われはとうとぶ。<br/>',NULL,49376,2);
INSERT INTO stanza VALUES('J166','3','ちちのよろこびと 安そく,みななれにあり;<br/>ちちはなれを何と 　　ちん重されるや。<br/>',NULL,49377,3);
INSERT INTO stanza VALUES('J166','4','わがあい子と呼び, ちちのあい,なれに置く;<br/>されど,わがために, 　　死にいたらせる。<br/>',NULL,49378,4);
INSERT INTO stanza VALUES('J166','5','やがて主にまみえ, われはよろこびうたう;<br/>おお,主イェス,なが名は 　　とわにかぐわしい。<br/>',NULL,49379,5);
INSERT INTO stanza VALUES('J166','6','かん喜のしらべは 永遠に絶えることなし;<br/>えいこうのうたは 　　えい遠につづく。<br/>',NULL,49380,6);
INSERT INTO stanza VALUES('J167','1','いのちのいずみ, ふかくあまい;<br/>主は生けるみず, わがかわき満たす。<br/>あわれみゆたか, 十分なめぐみ;<br/>なが知恵によりて, われにおよぶ。<br/>',NULL,49381,1);
INSERT INTO stanza VALUES('J167','2','われはながもの, なれ,わがもの;<br/>なれ,つみびとを, 宴せきにみちびく。<br/>ながこうせきに, われはたより;<br/>なが臨ざいに住み, 保護を享受す。<br/>',NULL,49382,2);
INSERT INTO stanza VALUES('J167','3','ながはなよめは, おっとをあいす;<br/>われ見つめるは, なれのうるわしさ;<br/>かんむりではなく, くぎあとの手;<br/>なれ,わがえいこう, 永遠の信らい。<br/>',NULL,49383,3);
INSERT INTO stanza VALUES('J168','1','主よ,ながあいとみめぐみの すべておもうとき,<br/>かおとかお合うのを, わがれいはのぞむ。<br/>',NULL,49384,1);
INSERT INTO stanza VALUES('J168','2','あら野を行くわれら,かわき, さびしく,おののく,<br/>左右も前後もいばら, 周囲はてきのわな。<br/>',NULL,49385,2);
INSERT INTO stanza VALUES('J168','3','されどなれのあいの価値を, ふかくおもうとき,<br/>こころあかるくされ, ながめぐみ賛美す。<br/>',NULL,49386,3);
INSERT INTO stanza VALUES('J168','4','主はわれらのいのち,ちから, またたて,いわ,うた,<br/>なれをおもうたびに, よろこび,たのしむ。<br/>',NULL,49387,4);
INSERT INTO stanza VALUES('J168','5','あいする主よ,まもりたまえ, かたくしたがいて,<br/>われら天の門に入り, 栄光のかたち見る。<br/>',NULL,49388,5);
INSERT INTO stanza VALUES('J169','1','イェスはわがいのち, なが愛のーゆえ,<br/>ひと日にーせんかい, 御名をさーけばん。<br/>',NULL,49389,1);
INSERT INTO stanza VALUES('J169','chorus','イェス,さい愛の主に くらぶるものなし;<br/>なれのえがお見て, われよろーこばん。<br/>',NULL,49390,2);
INSERT INTO stanza VALUES('J169','2','いかに愛すべきか, われ知らーねど,<br/>火のごとーきあいは こころ燃ーやす。<br/>',NULL,49391,3);
INSERT INTO stanza VALUES('J169','3','イェスわがすべてぞ, 依りたのーむ主,<br/>こころしーたうもの, とわのちーから。<br/>',NULL,49392,4);
INSERT INTO stanza VALUES('J169','4','燃えるあいの火は にち夜つーのり,<br/>他のあいーすべてを 焼き尽くーしぬ。<br/>',NULL,49393,5);
INSERT INTO stanza VALUES('J169','5','わがあいなるイェス, またわがーうた;<br/>その価値ーをだれか 知るを得ーんや。<br/>',NULL,49394,6);
INSERT INTO stanza VALUES('J169','6','このあい,なににも 制限を受ーけじ;<br/>主のあまーき価値は きのうにまーさる。<br/>',NULL,49395,7);
INSERT INTO stanza VALUES('J169','note','(人位の場合のおりかえし)<br/>イェス,さい愛の主を, 人位とし受け入れん;<br/>うちに生くるのは あいする主ぞ。<br/>',NULL,49396,8);
INSERT INTO stanza VALUES('J170','1','主よ,わがこころのあい, くちで歓喜し,あらわす;<br/>復かつの主,われらの分, いま,なれをほめたとう。<br/>',NULL,49397,1);
INSERT INTO stanza VALUES('J170','2','ここで,なれをあじわい, なれの同在をたのしむ;<br/>ながかげにあんそくし, あまい実をまんきつす。<br/>',NULL,49398,2);
INSERT INTO stanza VALUES('J170','3','ひとつぶのむぎ落ちて, 多くのむぎを生み出す;<br/>多くの兄弟たちを生み, ながすべてきょう受さす。<br/>',NULL,49399,3);
INSERT INTO stanza VALUES('J170','4','主よ,なれはわがすべて, なれにあり,すべて得る;<br/>わがひつ要,満たされて, なれに感動し,ほめたとう。<br/>',NULL,49400,4);
INSERT INTO stanza VALUES('J171','1','主よ,なれおもうとき, あまさに満つ;<br/>御かお見るあまさ, さらにまさる。<br/>',NULL,49401,1);
INSERT INTO stanza VALUES('J171','2','なが名のひびきは, なんとあまし;<br/>そのあまさ,だれも 言い尽くせぬ。<br/>',NULL,49402,2);
INSERT INTO stanza VALUES('J171','3','悔いたるこころに, 希ぼうあたえ,<br/>つまずくものには, 慈あいしめす。<br/>',NULL,49403,3);
INSERT INTO stanza VALUES('J171','4','ひつぜつ尽くせぬ, ながゆたかさ;<br/>イェスの愛のひろさ, われらは知る。<br/>',NULL,49404,4);
INSERT INTO stanza VALUES('J171','5','イェス！なれはひかり, いのち,いずみ;<br/>わがきょう受,愛慕を はるか超える。<br/>',NULL,49405,5);
INSERT INTO stanza VALUES('J171','6','なれ以外にいずみ, われは持たず;<br/>いのちのみずわき, かわき満たす。<br/>',NULL,49406,6);
INSERT INTO stanza VALUES('J171','7','イェス,わがよろこび, われのほう賞;<br/>わがうた,えいこう, とわにいたる。<br/>',NULL,49407,7);
INSERT INTO stanza VALUES('J172','1','主はいのち,ひかり, さいこうのしゅくふく,<br/>こころむなしくして, なれをあおぎのぞむ。<br/>',NULL,49408,1);
INSERT INTO stanza VALUES('J172','2','なが真じつは不変, もとむものにすくい;<br/>さがすものに慈あい, 見いだすものにすべて。<br/>',NULL,49409,2);
INSERT INTO stanza VALUES('J172','3','生けるパンを食べて, なお,食べるをねがう;<br/>生けるみずを飲んで, なお,飲むことねがう。<br/>',NULL,49410,3);
INSERT INTO stanza VALUES('J172','4','うつり変わる世で, わがれい,なれしたう;<br/>なが笑がお見るとき, 歓喜し,しゅくふく得る。<br/>',NULL,49411,4);
INSERT INTO stanza VALUES('J172','5','主はわれのちから！ 維持し,沈せいさせる;<br/>くらやみを追い出し, 聖なるひかりそそぐ。<br/>',NULL,49412,5);
INSERT INTO stanza VALUES('J173','1','めぐみのことばにて, 　へりくだらされ,<br/>死なれた主よ,いま 　あつまり,記念する。<br/>',NULL,49413,1);
INSERT INTO stanza VALUES('J173','2','裂かれた主のからだ, 　供給となるため;<br/>契やくのさかずき, 　主を記ねんすため。<br/>',NULL,49414,2);
INSERT INTO stanza VALUES('J173','3','ゲｯセマネのいのりで, 　血のあせながす;<br/>主をなぜわすれよう？ 　われらは記念する。<br/>',NULL,49415,3);
INSERT INTO stanza VALUES('J173','4','十字架に目を向けて, 　ゴﾙゴタの主,見る,<br/>かみの小ひつじを, 　われらは記念する。<br/>',NULL,49416,4);
INSERT INTO stanza VALUES('J173','5','なれとなが苦つうと, 　ながあいおぼえ,<br/>生けるかぎり主を 　われらは記念する。<br/>',NULL,49417,5);
INSERT INTO stanza VALUES('J173','6','からだもたましいも, 　よわくなるとき,<br/>また主が来るとき, 　われをおぼえませ。<br/>',NULL,49418,6);
INSERT INTO stanza VALUES('J174','1','主の愛におおわれ, あい餐を享受す;<br/>あがないに感げきし, なれを記念する。<br/>このパンとさかずき, なが愛をひょうめいす;<br/>めぐみにあずかり, ともに礼はいす。<br/>',NULL,49419,1);
INSERT INTO stanza VALUES('J174','2','なれは世にくだり, 奴れいとなって,<br/>つみびとをたずね, ろう苦し,かわく。<br/>ひとりでも悔いて, かみにかえるために,<br/>なれ,血ながしたと われら記念する。<br/>',NULL,49420,2);
INSERT INTO stanza VALUES('J174','3','十字架につけられ, かみに捨てられ,<br/>だい価をはらって, 愛あらわされた;<br/>天でとりなす主を, われらは記ねんする;<br/>さい臨のやくそく, 主よ,成就しませ。<br/>',NULL,49421,3);
INSERT INTO stanza VALUES('J175','1','しゅくはい受けて, さん美あふれる,<br/>わがための血の, なんたる価値よ！<br/>効き目ある血は, すべて解けつし,<br/>うれい,おそれを, すべて消し去る。<br/>',NULL,49422,1);
INSERT INTO stanza VALUES('J175','2','とうとい血にて 基礎づけられて,<br/>しんけいやくは かくりつされた。<br/>あがなわれしは とうとい血による,<br/>この有効な血を, いま,われら飲む。<br/>',NULL,49423,2);
INSERT INTO stanza VALUES('J175','3','ながされた血は つみをきよめて,<br/>義のようきゅうを すべて満たした。<br/>ゆうこうな血は わがつみあらい,<br/>りょうしんきよめ, かみに奉仕さす。<br/>',NULL,49424,3);
INSERT INTO stanza VALUES('J175','4','ぶん離する血は, われをせいとす;<br/>保護する血にて, 聖をあかしする。<br/>あがないの血は われらを義とす;<br/>すくう血により, かみと和かいす。<br/>',NULL,49425,4);
INSERT INTO stanza VALUES('J175','5','十字架の血にて, かみと和かいし,<br/>平あんのなかで, かみとまじわる。<br/>血にあずかりて, ながいのちを得,<br/>血といのちにて, 自由,安そく得る。<br/>',NULL,49426,5);
INSERT INTO stanza VALUES('J175','6','すべてにまさり, 血は天でかたる;<br/>この血のもとで, サタンはしりぞく。<br/>しょう利の血にて, てきに打ち勝つ;<br/>あのこく訴者に われら勝利得る。<br/>',NULL,49427,6);
INSERT INTO stanza VALUES('J175','7','なが血によりて, 聖徒とまじわり,<br/>血におおわれて, わが霊,自由得る。<br/>なが血の価値は 言い尽くし得じ,<br/>われら,永えんに かたりつづける。<br/>',NULL,49428,7);
INSERT INTO stanza VALUES('J176','1','なが愛の宴せき, パン,さかずき,しめす;<br/>このしるし受け, なれを食べて飽く。<br/>さかずき感謝す, しゅくふくいかに,<br/>すくいのめぐみ, 血により用意さる。<br/>',NULL,49429,1);
INSERT INTO stanza VALUES('J176','2','わがためながす 血によりゆるされ,<br/>なが新契やくは, しゅくふくを得さす。<br/>なれいかり飲み, わがため死にて,<br/>しゅくふくを買い, わがための分とす。<br/>',NULL,49430,2);
INSERT INTO stanza VALUES('J176','3','うしなったかみを この分により得る;<br/>なれの血により, かみ,めぐみとなる。<br/>あがない,いのち, この分はふくむ;<br/>御むねのすべて, この分により得る。<br/>',NULL,49431,3);
INSERT INTO stanza VALUES('J176','4','とわの分にあり, 神聖は満ちあふる;<br/>天のあじ見さす 計かくのさかずき。<br/>愛にあり飲みて, なれを記念する;<br/>霊にあり飲みて, カルバリを享受す。<br/>',NULL,49432,4);
INSERT INTO stanza VALUES('J177','1','われは主のうちに, 主はわがうちにいます;<br/>主とわれはひとつなり, すばらしいおく義！<br/>',NULL,49433,1);
INSERT INTO stanza VALUES('J177','2','主はからだを捨て, われを主にあずからせ,<br/>われ,つみより解くため, とうとい血ながす。<br/>',NULL,49434,2);
INSERT INTO stanza VALUES('J177','3','主はれいと成りて, わがれいにはいられた;<br/>つねになれを取り入れ, なが豊富を享受す。<br/>',NULL,49435,3);
INSERT INTO stanza VALUES('J177','4','このしょくたく見て, なれをおもいめぐらす;<br/>みこころにかんどうし, なが手順おぼえる。<br/>',NULL,49436,4);
INSERT INTO stanza VALUES('J177','5','パンとさかずき受け, なれのあまさにひたる;<br/>れいにて主を吸い,受け, いのちに飽き足る。<br/>',NULL,49437,5);
INSERT INTO stanza VALUES('J177','6','霊にあり食べ飲み, 主を取るをせつぼうす;<br/>ぜん存ざいを満たせや, 主を記念するため！<br/>',NULL,49438,6);
INSERT INTO stanza VALUES('J177','note','［６　霊にあり――わたしの霊の中で］<br/>',NULL,49439,7);
INSERT INTO stanza VALUES('J178','1','この宴せきのゆえ, 主よ感謝します;<br/>ご自身をエンジョイする こよなき宴せき。<br/>御身を捨て,われらに 分けあたえしパンと,<br/>血をながし,われらに 飲ませるさかずき。<br/>',NULL,49440,1);
INSERT INTO stanza VALUES('J178','chorus','見よ,宴せきを！ 何というしるし！<br/>ふかき意義を,だれ 知り得るや！<br/>',NULL,49441,2);
INSERT INTO stanza VALUES('J178','2','あがないの死にて いのちをたまい，<br/>ご自身をあたえて わがぶんとなす。<br/>パンさかずき，あずかり， 主の死，告げ知らせ，<br/>ご自身を食べ飲みし, 永えんに記念する。<br/>',NULL,49442,3);
INSERT INTO stanza VALUES('J178','3','おく義なるからだ しめすパンにより，<br/>肢たいとまじわり, いちをあかしす。<br/>いましゅくふくするは, せいなるさかずき;<br/>血によりてすべての せい徒とまじわる。<br/>',NULL,49443,4);
INSERT INTO stanza VALUES('J178','4','とわの分なる主を いまあじ見する;<br/>王こく待ちのぞみ, さい臨うながす。<br/>王こくあらわるとき, 勝利者たちともに,<br/>ご自身にあずかりて はなよめとならん。<br/>',NULL,49444,5);
INSERT INTO stanza VALUES('J179','1','主よ,ながしょくたく見て, われはおどろく;<br/>ひとつパンとさかずきは, みこころしめす。<br/>',NULL,49445,1);
INSERT INTO stanza VALUES('J179','2','このパンはいのちのかて, てんのしょくもつ;<br/>なが死にて,なが豊富を われに享受さす。<br/>',NULL,49446,2);
INSERT INTO stanza VALUES('J179','3','このさかずきはわが分, 血により成就す;<br/>われらしゅく杯受け入れ, ながすべて得る。<br/>',NULL,49447,3);
INSERT INTO stanza VALUES('J179','4','いまこのパンにあずかり, いのちを享受す;<br/>愛にあり,なれを記念し, なれを満きつす。<br/>',NULL,49448,4);
INSERT INTO stanza VALUES('J179','5','ともにしゅくはいを飲み, しゅくふくを得る;<br/>上げらる日までなれを, よろこび,記念す。<br/>',NULL,49449,5);
INSERT INTO stanza VALUES('J179','6','パン,さかずきにあずかり, なが死を展覧す;<br/>「日々なれ,わがいのち」と, われらあかしす。<br/>',NULL,49450,6);
INSERT INTO stanza VALUES('J179','7','いま待ちのぞむ,かの日, 主,ともに座して,<br/>さらにご自身を享受し, 礼拝することを。<br/>',NULL,49451,7);
INSERT INTO stanza VALUES('J180','1','ここで御かおと相対し, 信こうで見えぬこと触れ,<br/>ふかくめぐみを知って, みあしのもと,やすらぐ。<br/>',NULL,49452,1);
INSERT INTO stanza VALUES('J180','2','ここで良きものを食べ, しゅくふくのさかずき飲む,<br/>困なんをすべてわすれ, 平安の感かくあじわう。<br/>',NULL,49453,2);
INSERT INTO stanza VALUES('J180','3','われにつみ,けがれあり, なれに義ととうとい血あり;<br/>なが血はわれをあらい, 義はつみをたい処した。<br/>',NULL,49454,3);
INSERT INTO stanza VALUES('J180','4','なれのほか,たすけなし; めぐみあればもとめない;<br/>あいあればまんぞくす; ながちからにより立つ。<br/>',NULL,49455,4);
INSERT INTO stanza VALUES('J180','note','［以下の三つの節はパンをさいた後に歌う。］<br/>',NULL,49456,5);
INSERT INTO stanza VALUES('J180','5','パン,ぶどう酒すでになし, すくいのあい,なおもある！<br/>宴せきすでに過ぎたが, ながしたしみ,なおある！<br/>',NULL,49457,6);
INSERT INTO stanza VALUES('J180','6','くものはしらはのぼる, 夜の間に荒野をたびだつ;<br/>なれの召しにしたがい, 間もなくみやこに着く。<br/>',NULL,49458,7);
INSERT INTO stanza VALUES('J180','7','宴せきに着き,また去る, こうして天の宴せき目ざす;<br/>小ひつじのこんえんを, いま,まえあじわいする。<br/>',NULL,49459,8);
INSERT INTO stanza VALUES('J181','1','パンとさかずきにて, なが死を展覧し,<br/>あいのわざおもい, 死の価値を見る。<br/>パン,さかずきの分離は, なが死をあらわす,<br/>こころと霊とくちは, かんどうし,うたう。<br/>',NULL,49460,1);
INSERT INTO stanza VALUES('J181','chorus','なれは苦はい, われしゅくはい！<br/>ながあいのわざを, とわにほむ！<br/>',NULL,49461,2);
INSERT INTO stanza VALUES('J181','2','わがため血ながし, かみにもたらす,<br/>そはわれらつねに, 御かお見るため。<br/>かみの義,聖,栄こうの ようきゅうを満たす,<br/>死のこうせきにより かみとまじわりす。<br/>',NULL,49462,3);
INSERT INTO stanza VALUES('J181','3','死によりまく裂け, 至せい所ひらき,<br/>へだてはのぞかれ, めぐみの御座へ,<br/>あわれみ,めぐみ受け, てき時のたすけ得,<br/>生けるみずを飲みて, なれの豊富に飽く。<br/>',NULL,49463,4);
INSERT INTO stanza VALUES('J181','4','われらをあがない, さい司と成して,<br/>かみをきょう受させ, ほう仕をさせる。<br/>このしゅくふく,めぐみ, なが死により受け,<br/>あらたに飲む日まで, 絶えず記ねんする。<br/>',NULL,49464,5);
INSERT INTO stanza VALUES('J181','note','［３　てき時のたすけ得――時機を得た助けを受ける］<br/>',NULL,49465,6);
INSERT INTO stanza VALUES('J182','1','なれは死をまえにして, たみのいちいのられた;<br/>まいかいパンをさくとき, そのいのりじょう就する。<br/>ひとつパンはひとつからだ, このパンさきで記ねんす。<br/>',NULL,49466,1);
INSERT INTO stanza VALUES('J182','2','われら,召かいのために, 分れつせぬこといのる,<br/>われらを主に引き寄せ, なれにむすびつかせよ。<br/>ひとつパンはひとつからだ, このパンさきで記ねんす。<br/>',NULL,49467,2);
INSERT INTO stanza VALUES('J182','3','むれをはなれたひつじ, 良きぼく者,もどしませ,<br/>かれらを当初の真理に, しょうかいにもどしませ。<br/>やがてひとつからだ持ち, このパンさきで記ねんす。<br/>',NULL,49468,3);
INSERT INTO stanza VALUES('J182','4','やがてしるしは過ぎて, 天のシオンでいちとなる,<br/>聖徒ら平安きょう受して, きわみまであいし合う;<br/>御子とともにきょう受する, 愛とへい安,えいえんに。<br/>',NULL,49469,4);
INSERT INTO stanza VALUES('J183','1','主はのろいを受け, われしゅくふく受く;<br/>主は苦はいを飲み, われ宴せきに着く。<br/>',NULL,49470,1);
INSERT INTO stanza VALUES('J183','2','このあいのふかさ, だれはかりうるや？<br/>このあいのたかさ, わがこころうたう。<br/>',NULL,49471,2);
INSERT INTO stanza VALUES('J184','1','そのよる主イェスは, われらに言う,<br/>「わたしを記念して, これ,おこなえ」;<br/>そのみことばに われらしたがい,<br/>いま,ともにつどい, 主を記念する。<br/>',NULL,49472,1);
INSERT INTO stanza VALUES('J184','2','いかりのさかずき, わがため飲む;<br/>死のバプテスマは, なんとふかい！<br/>なれゴルゴタで ちちに捨てらる;<br/>こころ感げき満ち, 主を記念する。<br/>',NULL,49473,2);
INSERT INTO stanza VALUES('J184','3','主の霊を圧ぱくす くらやみあり;<br/>怒とうのよう,主に おそいかかる;<br/>なが無限のあい, そのなかに見る;<br/>うれい,歓喜,混ざり, 主を記念する。<br/>',NULL,49474,3);
INSERT INTO stanza VALUES('J184','4','死より復かつして, はつ穂となる;<br/>ちちのみぎに座す 召会のかしら;<br/>われは主のゆえ, 受け入れられて,<br/>心身みなすくわれ, 主を記念する。<br/>',NULL,49475,4);
INSERT INTO stanza VALUES('J184','5','主の死を展覧して， 死のさまへと，<br/>かたちづくらるを ねがいもとむ；<br/>主の死にならい， 主の死を表明し，<br/>うやまいあいして， 主を記念する。<br/>',NULL,49476,5);
INSERT INTO stanza VALUES('J185','1','このパンを見て感謝します, そは神聖なしるし;<br/>ごけいかくのおく義を, われらここに見る。<br/>',NULL,49477,1);
INSERT INTO stanza VALUES('J185','2','パンはながからだしめす, そはわれらのため;<br/>ながいのちを受けさせ, ご自しんを得さす。<br/>',NULL,49478,2);
INSERT INTO stanza VALUES('J185','3','なれのからだは裂かれて, ご自身をあたえる;<br/>なれ,わがいのちとなり, ながはん侶となす。<br/>',NULL,49479,3);
INSERT INTO stanza VALUES('J185','4','パンはながおく義てきな からだをあらわす;<br/>われらは生ける肢たい, 主とまったくひとつ。<br/>',NULL,49480,4);
INSERT INTO stanza VALUES('J185','5','われら,おおくのむぎつぶ, ひとつパンとなる;<br/>ここになれを記ねんし, なれでやしなわる。<br/>',NULL,49481,5);
INSERT INTO stanza VALUES('J185','6','パンによりまじわるとき, ながこころ満たす;<br/>せい徒らのまじわりは, なが豊満あかしす。<br/>',NULL,49482,6);
INSERT INTO stanza VALUES('J186','1','あいのえんせきは, 　めぐみより出る;<br/>パン,さかずき享受し, 　主を記念する。<br/>',NULL,49483,1);
INSERT INTO stanza VALUES('J186','2','ここにてわれらは 　見ることねがう:<br/>御ちちのこころと 　ながめぐみを。<br/>',NULL,49484,2);
INSERT INTO stanza VALUES('J186','3','わが霊は満ぞくし, 　いま,あかしする:<br/>いのちのパン,あまく, 　豊富なきょう給。<br/>',NULL,49485,3);
INSERT INTO stanza VALUES('J186','4','つみさだめはなく, 　よろこびに満つ;<br/>とうときあがないの血, 　かみの満ぞく。<br/>',NULL,49486,4);
INSERT INTO stanza VALUES('J186','5','いま,この宴せきの 　あまさを享受す,<br/>かの日のえんせき, 　あまさ,いかに！<br/>',NULL,49487,5);
INSERT INTO stanza VALUES('J186','6','えいこう化されて, 　御かお見るとき,<br/>不思議なめぐみを 　みなあかしす。<br/>',NULL,49488,6);
INSERT INTO stanza VALUES('J187','1','パンとさかずきに, ひとと成った主に,<br/>豊富なめぐみに, 主よ,感謝します。<br/>',NULL,49489,1);
INSERT INTO stanza VALUES('J187','2','パンとさかずきに, 愛のこころ見る;<br/>神せいなしるし, 主よ,感謝します。<br/>',NULL,49490,2);
INSERT INTO stanza VALUES('J187','3','すくいあおぎ見, 主にちかづくよう;<br/>われを召すゆえ, 主よ,感謝します。<br/>',NULL,49491,3);
INSERT INTO stanza VALUES('J187','4','柔和でまずしい, なれのあゆみを,<br/>われら記念して, 主よ,感謝します。<br/>',NULL,49492,4);
INSERT INTO stanza VALUES('J187','5','「われが来るまで, これおこなえ」と,<br/>みちびくゆえに, 主よ,感謝します。<br/>',NULL,49493,5);
INSERT INTO stanza VALUES('J187','6','なれが来るまで われらパンをさき,<br/>死と復かつ見て, 主よ,感謝します。<br/>',NULL,49494,6);
INSERT INTO stanza VALUES('J187','7','すべてのそなえ, あたらしい地位に,<br/>さかずきを飲み, 主よ,感謝します。<br/>',NULL,49495,7);
INSERT INTO stanza VALUES('J187','8','「われ,すぐに来る」, その日はちかし;<br/>栄こう,王こくに, 主よ,感謝します。<br/>',NULL,49496,8);
INSERT INTO stanza VALUES('J188','1','栄こうなるキリスト, 　はじめからいますかた！<br/>全のうのかみ,はじめ, 　あってある,永えんのちち;<br/>はじめ,おわりもなく, 　ちち,はは,系図もなし;<br/>いまおり,むかしおり, 　やがて来ようとするかた。<br/>',NULL,49497,1);
INSERT INTO stanza VALUES('J188','2','栄こうなるキリスト, 　万ぶつを創ぞうした主;<br/>万ぶつの根源,かしら, 　万ぶつよりさきにある;<br/>ばんぶつをまとめて, 　ことばにて維持する;<br/>万ぶつのそうぞく者, 　万ぶつはかれに帰する。<br/>',NULL,49498,2);
INSERT INTO stanza VALUES('J188','3','栄こうなるキリスト, 　ことば,にくたいと成り;<br/>かみ,にくにあらわれ, 　まく屋を張られたひと。<br/>かれはいやしくなり, 　奴れいのかたち取る,<br/>かみの栄光のこう輝, 　本しつのしんのかたち。<br/>',NULL,49499,3);
INSERT INTO stanza VALUES('J188','4','栄こうなるキリスト, 　つみにない,つみとされ,<br/>十字架につけられて, 　さばかれ,死をあじわう。<br/>ふるいひとくぎづけ, 　あく魔,サタンほろぼし,<br/>つみよりわれを解き, 　わなよりかいほうする。<br/>',NULL,49500,4);
INSERT INTO stanza VALUES('J188','5','栄こうなるキリスト, 　復かつのはつ穂となる;<br/>われをも復かつさせ, 　われにいのちあたえる。<br/>主はひとつぶのむぎ, 　多くのむぎ生み出す;<br/>おなじかたから出た 　われらは主のきょうだい。<br/>',NULL,49501,5);
INSERT INTO stanza VALUES('J188','6','栄こうなるキリスト, 　霊と成り,わが霊に入り,<br/>かみの性しつ得させ, 　神せいにあずからせる。<br/>わがうちで成ちょうし, 　主のかたちへと変え,<br/>かみの豊富,享受させ, 　豊まんへといたらせる。<br/>',NULL,49502,6);
INSERT INTO stanza VALUES('J188','7','栄こうなるキリスト, 　昇てんして,ちょうえつす,<br/>栄こう,尊貴,かんむり, 　最こうの名を得られた。<br/>われらをも昇天させ, 　ともに天上に座させ,<br/>権威にあずからせて, 　かれのようにつよくする。<br/>',NULL,49503,7);
INSERT INTO stanza VALUES('J188','8','栄こうなるキリスト, 　霊にて召会を生み出し,<br/>たまもの,機能あたえ, 　からだを建ぞうされる。<br/>召かい愛し,はぐくみ, 　召かいは主,表げんす;<br/>召かいは主の継ぞく, 　主を宇宙にかくだいす。<br/>',NULL,49504,8);
INSERT INTO stanza VALUES('J188','9','栄こうなるキリスト, 　再りんし,王こくを得る,<br/>てき討ち,万民さばき, 　権威もて王こく建てる。<br/>聖徒ともに王となし, 　地の果てまでおさむ;<br/>万ゆうともにうたい, 　全地は安そくきょう受す。<br/>',NULL,49505,9);
INSERT INTO stanza VALUES('J188','10','栄こうなるキリスト, 　永えんの世のちゅうしん,<br/>みやこを伴侶として, 　万ぶつを更しんされる。<br/>主,かみの栄光の表現, 　うちよりあらわれる;<br/>みやこは主の表げん, 　主に満ち,とわにいたる。<br/>',NULL,49506,10);
INSERT INTO stanza VALUES('J189','1','小ひつじのうたうたう; 栄こうを主に帰す！<br/>比るいなきよろこび, 　栄こうが主に！<br/>あがないのために, 主はくだりきたる,<br/>不思議なめぐみに, 愚人もおどろく。<br/>',NULL,49507,1);
INSERT INTO stanza VALUES('J189','chorus','大ごえでさん美する, 栄光主に！栄光主に！<br/>かつてない詩のテｰマ, 栄こうが主に！<br/>',NULL,49508,2);
INSERT INTO stanza VALUES('J189','2','聞けよ,天のうたごえ, 栄こうを主に帰す！<br/>主はひかり,主はあい, 栄こうを主に！<br/>かなしんでいるひと, 不安なつみびとよ,<br/>どのひとの負債も, 主はせい算した。<br/>',NULL,49509,3);
INSERT INTO stanza VALUES('J189','3','うたえ,さばき,過ぎた, 栄こうを主に帰す！<br/>主とともに復かつす, 栄こうを主に！<br/>われら,紅海わたり, てきはほうむられた;<br/>死われにおよばず, 主は義とされた。<br/>',NULL,49510,4);
INSERT INTO stanza VALUES('J189','4','うたえ，主はさい臨す, 栄こうを主に帰す！<br/>召かいはえんじゅくす, 栄こうを主に！<br/>もとめ,したうもの, いまや見て受けた,<br/>主とおなじ前途を 愛にありあゆむ。<br/>',NULL,49511,5);
INSERT INTO stanza VALUES('J189','5','明ろうなこえでうたう, 栄こうを主に帰す！<br/>絶えずこのうたうたう, 栄こうを主に！<br/>全地にこのしらべ, 満ちるまでうたう;<br/>新そうぞうはみな, このうたうたう。<br/>',NULL,49512,6);
INSERT INTO stanza VALUES('J190','1','賛美！賛美！主イェスをさん美す！ 　不思議なあいをうたう;<br/>うたえや！てん使らは伏して, 　尊貴,ちから御名に帰す！<br/>ぼく者のよう,イェスはやしない, 　みうでに絶えずいだく。<br/>',NULL,49513,1);
INSERT INTO stanza VALUES('J190','chorus','賛美せよ！主の不思議な愛を！ 　うたえや！かれの御名を。<br/>',NULL,49514,2);
INSERT INTO stanza VALUES('J190','2','賛美！賛美！主イェスをさん美す！ 　わがため苦なん受ける;<br/>うたえや！主はけん固ないし, 　永遠のあがない成就す！<br/>わが苦つう,主はになわれた！ 　このあい,不思議,ゆたか。<br/>',NULL,49515,3);
INSERT INTO stanza VALUES('J190','3','賛美！賛美！主イェスをさん美す！ 　天上には「ホサナ」ひびく！<br/>万有の主,おうにかんむりを！ 　主は万ぶつふっ興する！<br/>主は勝利得,おうこく建てる, 　栄光,権威,わが主に帰す！<br/>',NULL,49516,4);
INSERT INTO stanza VALUES('J191','1','われらをあいし,あわれみ, めぐみたまわる主,<br/>ご自しん捨て,血ながし, われらを生かし,すくう,<br/>ちから,えい光,みくにが, とわに主にあれ。<br/>',NULL,49517,1);
INSERT INTO stanza VALUES('J192','1','主よ,ただなれのみ, 礼拝すべきすくいぬし！<br/>主よ,ただなれのみ, 礼拝すべきすくいぬし！<br/>',NULL,49518,1);
INSERT INTO stanza VALUES('J192','2','主よ,ただなれのみ, 賛美すべきすくいぬし！<br/>主よ,ただなれのみ, 賛美すべきすくいぬし！<br/>',NULL,49519,2);
INSERT INTO stanza VALUES('J192','3','主よ,ただなれのみ, 感謝すべきすくいぬし！<br/>主よ,ただなれのみ, 感謝すべきすくいぬし！<br/>',NULL,49520,3);
INSERT INTO stanza VALUES('J192','4','主よ,ただなれのみ, あがむべきすくいぬし！<br/>主よ,ただなれのみ, あがむべきすくいぬし！<br/>',NULL,49521,4);
INSERT INTO stanza VALUES('J193','1','栄光,尊貴,ほう富が, 小ひつじにあれや！<br/>イェスはすくいぬし！ ハレールヤ！ハレールーヤ！<br/>ハレルヤー！賛美の主！<br/>',NULL,49522,1);
INSERT INTO stanza VALUES('J194','1','かみの霊はキﾘストの霊, 実さいのれいとして来た。<br/>そのれい,わが霊に住み, 　実さいを供きゅうする。<br/>',NULL,49523,1);
INSERT INTO stanza VALUES('J194','2','キリストはかみの化身, かみの性しつをあらわす;<br/>れいはキリストの化身, いのちなる主,啓示す。<br/>',NULL,49524,2);
INSERT INTO stanza VALUES('J194','3','かみの本しつのほう満, キリストのなかにやどる;<br/>キリストの豊富すべて, 霊にて実さいとなる。<br/>',NULL,49525,3);
INSERT INTO stanza VALUES('J194','4','ちち,子にあり表現され, 子はじっさいの霊と成る;<br/>ちち-みなもと,子-ひょう現, 霊ははいり,供給する。<br/>',NULL,49526,4);
INSERT INTO stanza VALUES('J194','5','霊,うちなるひと増強し, キリストはこころに住み,<br/>われらはみな満たされ, かみの豊満にいたる。<br/>',NULL,49527,5);
INSERT INTO stanza VALUES('J194','6','子のなかでちちを得て, 霊のなかで子を経けんす;<br/>わがいのち,わがすべて, 霊にあり満たされる。<br/>',NULL,49528,6);
INSERT INTO stanza VALUES('J194','7','神せいな実さいをもて, 霊によりわれを満たせや,<br/>われらなれに満たされ, 豊富を完全に享受す。<br/>',NULL,49529,7);
INSERT INTO stanza VALUES('J195','1','つみのかいほう得ることを, ひたすら主にいのる;<br/>ある日,主はわれにこたえた, 霊こころに満つ。<br/>',NULL,49530,1);
INSERT INTO stanza VALUES('J195','chorus','霊こころに満ち,そくばくを解く,<br/>われかい放され,さん美に満ちる,　霊こころに満つ。<br/>',NULL,49531,2);
INSERT INTO stanza VALUES('J195','2','われよわく,無ようのうつわ, つよくあるをねがう;<br/>主はめぐみ,こころを満たし, 霊こころに満つ。<br/>',NULL,49532,3);
INSERT INTO stanza VALUES('J195','3','こころひろくされ,あかしす, せいれいのちからを;<br/>たかぶりやつみをはなれる, 霊こころに満つ。<br/>',NULL,49533,4);
INSERT INTO stanza VALUES('J195','4','御かお見ることかくしんす, きよくされたゆえに;<br/>主は霊に住み,めぐみとなり, 霊こころに満つ。<br/>',NULL,49534,5);
INSERT INTO stanza VALUES('J196','1','いまやかみのれいは, 主イェス・キリストのれい;<br/>死と復かつのしん・人, 栄光受けたそのれい。<br/>',NULL,49535,1);
INSERT INTO stanza VALUES('J196','2','昇天した主イェスより, その霊,わが霊にくだり,<br/>かれの実さいすべて, わがけいけんとなす。<br/>',NULL,49536,2);
INSERT INTO stanza VALUES('J196','3','イェス・キリストの霊は, すべてのせい分ふくむ;<br/>しん性,じん性があり, 人生,えいこうがある。<br/>',NULL,49537,3);
INSERT INTO stanza VALUES('J196','4','死のこうのうと苦難, 復かつのたい能,しょう天,<br/>御座,権威,おうこくも, みなその霊はふくむ。<br/>',NULL,49538,4);
INSERT INTO stanza VALUES('J196','5','すべての成分持つ霊, わが霊にあり運こうす;<br/>かれのあぶら塗りで, 主のほう富きょう受す。<br/>',NULL,49539,5);
INSERT INTO stanza VALUES('J196','6','すべてふくむれいは, われのすべての秘けつ;<br/>わがうちではたらき, かみをすべてとなす。<br/>',NULL,49540,6);
INSERT INTO stanza VALUES('J197','1','この知らせを, 宣べつたえよ,<br/>ひとの住まう 地にあまねく;<br/>聖徒らすべて つたえるべき:<br/>なぐさめぬし！<br/>',NULL,49541,1);
INSERT INTO stanza VALUES('J197','chorus','なぐさめぬし,すでに来たる！<br/>主のやくそく,聖れいは来た;<br/>ひとに告げよ:なぐさめぬし,すでに来た！と。<br/>',NULL,49542,2);
INSERT INTO stanza VALUES('J197','2','くらやみの夜, すでに過ぎて,<br/>泣きかなしむ こえはやんだ;<br/>あさ日は照り, やま,かがやく;<br/>なぐさめぬし！<br/>',NULL,49543,3);
INSERT INTO stanza VALUES('J197','3','見よ,おうの王, いやしを帯び,<br/>れいのしゅう人, かいほうする;<br/>いたるところ, 凱歌はひびく:<br/>なぐさめぬし！<br/>',NULL,49544,4);
INSERT INTO stanza VALUES('J197','4','宣べつたえよ！ 流浪のたみに,<br/>神聖なあいを, 無限のあいを;<br/>つみの身にも, 主は来られる;<br/>なぐさめぬし！<br/>',NULL,49545,5);
INSERT INTO stanza VALUES('J197','5','うたのひびき， そらをめぐる，<br/>うえはてん使， したはせい徒；<br/>無限のあいを， ほめたたえる！<br/>なぐさめぬし！<br/>',NULL,49546,6);
INSERT INTO stanza VALUES('J198','1','世びとはなれを普つうの ナザレびとと見た；<br/>地でいつもかろんじられ, 十字架で身を捨てた。<br/>ひとの目にそのれき史, 終わりに見えた。<br/>',NULL,49547,1);
INSERT INTO stanza VALUES('J198','2','天ではなんというちがい！ 昇てんされたとき,<br/>主のじゅうじゅんのゆえに, かみ,宇ちゅうに命じる,<br/>主,宇ちゅうの元首として, 賛美することを。<br/>',NULL,49548,2);
INSERT INTO stanza VALUES('J198','3','かみはすでになれを立て, 主,キリストとした,<br/>天も地もすべては知る, なれのユニークさを,<br/>ひれ伏さぬものはなし, すべてしたがう。<br/>',NULL,49549,3);
INSERT INTO stanza VALUES('J198','4','遠く天でおこったことを, いかに知り得るか？<br/>かみはせいれいくだし, われにたまものとし,<br/>主イェスーが権威を得た 事じつを証明す。<br/>',NULL,49550,4);
INSERT INTO stanza VALUES('J198','5','せい霊わが身にそそがれ, わが身にとどまり,<br/>イェスはキリストであり, キリストはイェスという<br/>その事じつ証めいした, ナザレびとは主。<br/>',NULL,49551,5);
INSERT INTO stanza VALUES('J198','6','イェスは主！イェースーはー主！ 変わらない事じつ！<br/>聖れいすでにそそがれ, 真のたまものとなる;<br/>聖霊すでにあたえらる, ただ賛美すのみ。<br/>',NULL,49552,6);
INSERT INTO stanza VALUES('J199','1','えいこうなる主は, 天かられいたまい,<br/>かく種のめぐみを 召かいにあとう;<br/>なが信じつにより, たまものあたえませ。<br/>',NULL,49553,1);
INSERT INTO stanza VALUES('J199','2','バプテスマされて, なれとひとつれい;<br/>なれのからだには すべてそなわる;<br/>肢たいなるゆえに われはちからを得る。<br/>',NULL,49554,2);
INSERT INTO stanza VALUES('J199','3','われはちから得て, 最高の御名かたり,<br/>たまものを受けて, ふく音をつたえ,<br/>秘けつ得て奉仕し, たみにしょう利得さす。<br/>',NULL,49555,3);
INSERT INTO stanza VALUES('J199','4','ここであん手受け, たまものもとめる;<br/>事じつにもとづき, ちからをそそぎ,<br/>有えきなうつわに, われをじょう就しませ。<br/>',NULL,49556,4);
INSERT INTO stanza VALUES('J200','1','いまや,せいれいは, かみのいのちの霊;<br/>いのちをあたえて, かみにてき合さす。<br/>',NULL,49557,1);
INSERT INTO stanza VALUES('J200','2','生けるみずとして, わがかわきいやし,<br/>いのちの主あたえ, わがひつ要満たす。<br/>',NULL,49558,2);
INSERT INTO stanza VALUES('J200','3','いのちのひかりは, くらやみをのぞく;<br/>ひかりの主あたえ, われをあかるくす。<br/>',NULL,49559,3);
INSERT INTO stanza VALUES('J200','4','いのちの大のうは, わがうちをつよめ,<br/>ちからの主あたえ, エコノミｰ遂行する。<br/>',NULL,49560,4);
INSERT INTO stanza VALUES('J200','5','いのちの法そくは, つみより解放する;<br/>聖なる性しつにて, わがうち規制する。<br/>',NULL,49561,5);
INSERT INTO stanza VALUES('J200','6','いのちの霊われに, 豊富な実むすばせ,<br/>美とくを表現して, キリスト分与する。<br/>',NULL,49562,6);
INSERT INTO stanza VALUES('J200','7','いのち供給する霊, われをつくり変え,<br/>わがうち更しんし, 主と同けい化する。<br/>',NULL,49563,7);
INSERT INTO stanza VALUES('J200','8','いのちのれいにて, わがうち満たせや,<br/>全存ざい浸透され, いのちを表現する。<br/>',NULL,49564,8);
INSERT INTO stanza VALUES('J201','1','井戸のみずよ, わきあがれや！<br/>さまたげなく, 主ながるまで。<br/>',NULL,49565,1);
INSERT INTO stanza VALUES('J201','2','すでに裂けし いわよりみず,<br/>わき上がるも, われはふさぐ。<br/>',NULL,49566,2);
INSERT INTO stanza VALUES('J201','3','いのり,掘って, どろをのぞき,<br/>霊,解きはなち, 自由にながせ。<br/>',NULL,49567,3);
INSERT INTO stanza VALUES('J201','4','いのり,いのって, ますます掘り,<br/>いのることを, じゅくれんする。<br/>',NULL,49568,4);
INSERT INTO stanza VALUES('J201','5','二度と裂くに およばぬいわ,<br/>ただ掘り抜き, みずをながす。<br/>',NULL,49569,5);
INSERT INTO stanza VALUES('J201','6','聖れいくだり, そそぎ出され,<br/>わがうち住み, いずみとなる。<br/>',NULL,49570,6);
INSERT INTO stanza VALUES('J201','7','わがひつ要は, うちの満たし,<br/>さらにいのり, いずみひらく。<br/>',NULL,49571,7);
INSERT INTO stanza VALUES('J201','8','生けるみずが ながれるまで,<br/>さまたげみな 掘りつづける。<br/>',NULL,49572,8);
INSERT INTO stanza VALUES('J201','9','井戸のみずよ, わきあがれや,<br/>さまたげなく, 主ながるまで。<br/>',NULL,49573,9);
INSERT INTO stanza VALUES('J202','1','カデシの地でかわくとき, かみはたみに,命じられる:<br/>いわより,みずいでよ！ すでにいわ,裂けている;<br/>ただ命じ,みずながせ。<br/>',NULL,49574,1);
INSERT INTO stanza VALUES('J202','chorus','いわより,みずながせ！ 聖霊すでに,ともにある;<br/>豊富すべて受け入れよ; 命じるならきょう受する。<br/>',NULL,49575,2);
INSERT INTO stanza VALUES('J202','2','えい遠のいわ,裂けている, 聖れいはいま,満ちている;<br/>なれ,なぜもがくのか？ 主とともにヨルダン経よ;<br/>せいれい,いまや飲む。<br/>',NULL,49576,3);
INSERT INTO stanza VALUES('J202','3','たん純になって,ただ信じよ！ たずねもとめ,くるしまず！<br/>みうでにいだかれて, この世断ち,主の愛得よ,<br/>安そく得,満たされよ。<br/>',NULL,49577,4);
INSERT INTO stanza VALUES('J203','1','生けるみずのかわ, 御座よりながれ,<br/>しゅくふくともない, われにながれる。<br/>',NULL,49578,1);
INSERT INTO stanza VALUES('J203','chorus','生けるみずのかわ, 無だい価のみず;<br/>われを通しながれ, ひとにながれよ。<br/>',NULL,49579,2);
INSERT INTO stanza VALUES('J203','2','すいしょうのよう透明, ほう富なきょう給;<br/>かわくものよ,来て, 無だい価で得よ。<br/>',NULL,49580,3);
INSERT INTO stanza VALUES('J203','3','主よ,われをきよめ, からにし,満たせ;<br/>なれにふくさせて, 良きくだとなせ。<br/>',NULL,49581,4);
INSERT INTO stanza VALUES('J203','4','主よ,ただこのとき, みずはながれる;<br/>このときにひとは, なが豊富を知る。<br/>',NULL,49582,5);
INSERT INTO stanza VALUES('J203','5','すべてをささげて, 主に明けわたす;<br/>生けるみず満ちて, あふれながれる。<br/>',NULL,49583,6);
INSERT INTO stanza VALUES('J204','1','生けるみずのかわ, 御座よりながれ,<br/>ゆたかなまじわり, 権威をもたらす。<br/>',NULL,49584,1);
INSERT INTO stanza VALUES('J204','chorus','生けるみずのかわ, ながれるところ,<br/>ゆたかなまじわり, 権威をもたらす。<br/>',NULL,49585,2);
INSERT INTO stanza VALUES('J204','2','生けるみずは聖霊, いのちなるかみ,<br/>権威を帯び,ながれ, まじわり得さす。<br/>',NULL,49586,3);
INSERT INTO stanza VALUES('J204','3','かわはじゅんきんの 通りをながれる;<br/>神せいなながれは, あゆみもたらす。<br/>',NULL,49587,4);
INSERT INTO stanza VALUES('J204','4','ながれのほとりに, いのちの木あり,<br/>ながれあるところ, 無限の供給あり。<br/>',NULL,49588,5);
INSERT INTO stanza VALUES('J204','5','主よ,なれは裂かれ, みずはながれた；<br/>われをもくだいて, みずをながせや。<br/>',NULL,49589,6);
INSERT INTO stanza VALUES('J205','1','生けるみずながる, 栄光のみやより,<br/>それはみやの門と しき居けい過す。<br/>',NULL,49590,1);
INSERT INTO stanza VALUES('J205','chorus','みずはながれ, 供きゅうもたらし,<br/>死を飲み尽くして, いのちあらわす。<br/>',NULL,49591,2);
INSERT INTO stanza VALUES('J205','2','よどみなくながれ, 栄こうもたらす;<br/>すべてささげるを, だいいちとする。<br/>',NULL,49592,3);
INSERT INTO stanza VALUES('J205','3','無げんにながれて, かみにはかられ,<br/>かみのさばき経て, かみに帰される。<br/>',NULL,49593,4);
INSERT INTO stanza VALUES('J205','4','ながれにながれて, ますますあふれ,<br/>わたれぬまで満ち, めぐみにて生く。<br/>',NULL,49594,5);
INSERT INTO stanza VALUES('J206','1','聖霊をうれえさせて, 　さまよっていたが,<br/>つみにひたるわれを, 　なれは見捨てず。<br/>',NULL,49595,1);
INSERT INTO stanza VALUES('J206','chorus','聖霊おおくあたえて, 　照らし,燃やせや;<br/>「なれ」をいのちとし受け, いのりつづける。<br/>',NULL,49596,2);
INSERT INTO stanza VALUES('J206','2','われ,ねつあいを捨て, 　なれ,かなします;<br/>聖霊,わがうつり気を, 　なんとしのぶや。<br/>',NULL,49597,3);
INSERT INTO stanza VALUES('J206','3','聖霊,わがうちにあり, 　なれを主となす;<br/>ちいさきめいれいさえ 　おそれうやまう。<br/>',NULL,49598,4);
INSERT INTO stanza VALUES('J206','4','ながあいのよう,われは 　なれをあいせぬ;<br/>わがうちに火起こし, 　あつく燃やせや。<br/>',NULL,49599,5);
INSERT INTO stanza VALUES('J207','1','かみはちから, われにあたえ,<br/>絶えずまもり, めぐみあとう;<br/>霊,うちに住み, われを管理し,<br/>あいの火もて, われを燃やす。<br/>',NULL,49600,1);
INSERT INTO stanza VALUES('J207','chorus','こころ燃える,こころ燃える; てんの火,わがうちに燃える！<br/>せいれい来る,主の名,賛美す！ てんの火,わがうちに燃える！<br/>',NULL,49601,2);
INSERT INTO stanza VALUES('J207','2','十字架に伏し, われ,ささげる,<br/>生がいすべて, さい壇に置く;<br/>主はあがない, 火をくだらせ,<br/>わがいけにえ, 受け入れたもう。<br/>',NULL,49602,3);
INSERT INTO stanza VALUES('J207','3','わざではなく, やくそく待つ,<br/>御子,刑を受け, われ,子となる;<br/>えい光かみに, ハレルヤ,アｰメン;<br/>あいはながれ, われを燃やす。<br/>',NULL,49603,4);
INSERT INTO stanza VALUES('J208','1','主よ,われもとむ, 燃やす霊くだせ,<br/>自己のこのみを, のこらず燃やせ。<br/>',NULL,49604,1);
INSERT INTO stanza VALUES('J208','chorus','燃やす霊くだし, われ転機させよ！<br/>なにもかもみな, 燃やし尽くせや,<br/>待つ,待つ, 燃やす霊を待つ。<br/>',NULL,49605,2);
INSERT INTO stanza VALUES('J208','2','たましい,霊,からだ, さいだんに置く;<br/>情よくたい処し, すみずみ満たせ。<br/>',NULL,49606,3);
INSERT INTO stanza VALUES('J208','3','わがしょうがいを, いけにえとする,<br/>あがない成した とうとい主のため。<br/>',NULL,49607,4);
INSERT INTO stanza VALUES('J208','4','血による権利を, 信こうにて受く;<br/>主は御名により, やくそく果たす。<br/>',NULL,49608,5);
INSERT INTO stanza VALUES('J209','1','イェスは勝利のあい, われにそそぐ,<br/>こころは揺るがず, かみに根おろす。<br/>',NULL,49609,1);
INSERT INTO stanza VALUES('J209','2','価値なきものみな 焼き尽くせや;<br/>たかきやまさえも 溶かしながせや。<br/>',NULL,49610,2);
INSERT INTO stanza VALUES('J209','3','さい壇でわがつみ 焼き尽くせや;<br/>燃やす主のれいよ, われを満たせや。<br/>',NULL,49611,3);
INSERT INTO stanza VALUES('J209','4','せい練の火,われを 燃やし尽くせ;<br/>いのちを満たして, せいべつしませ。<br/>',NULL,49612,4);
INSERT INTO stanza VALUES('J209','5','揺れうごくこころ, 堅固にしませ;<br/>キリスト,わが世界, わがこころの愛。<br/>',NULL,49613,5);
INSERT INTO stanza VALUES('J210','1','主よ,なれのれいを 吹き入れたまえ;<br/>ながむねのなかに かくまいたまえ。<br/>',NULL,49614,1);
INSERT INTO stanza VALUES('J210','chorus','ふるきものすべて 吐き出させ,<br/>ながゆたかすべて 吸わしめよ。<br/>',NULL,49615,2);
INSERT INTO stanza VALUES('J210','2','わが持てるいのち, ちからとよわさ,<br/>吐き出すなら,なが いのちは満ちる。<br/>',NULL,49616,3);
INSERT INTO stanza VALUES('J210','3','つみのせいしつを 吐き出すときに,<br/>なが霊のほう富を, われは吸い込む。<br/>',NULL,49617,4);
INSERT INTO stanza VALUES('J210','4','なが愛のみうでに うれい吐き出し,<br/>よろこび,なぐさめ, やすき吸い込む。<br/>',NULL,49618,5);
INSERT INTO stanza VALUES('J210','5','やまいを吐き出し, おも荷は去りぬ;<br/>ながいやしを吸い, へいあん満ちる。<br/>',NULL,49619,6);
INSERT INTO stanza VALUES('J210','6','わがねがいを吐き, ながこたえ吸う;<br/>うたがい,おそれを, なれはしずめる。<br/>',NULL,49620,7);
INSERT INTO stanza VALUES('J210','7','吐くのも吸うのも みななれによる;<br/>主よ,われをとおし, あらわれたまえ。<br/>',NULL,49621,8);
INSERT INTO stanza VALUES('J211','1','主よ,われに息吹き, 生けるいずみ啓示し,<br/>わがうちでうごき, わがうち,照らせや。<br/>',NULL,49622,1);
INSERT INTO stanza VALUES('J211','2','天やよみではなく, 主,わがれいにいます;<br/>霊にもどればすぐ, 主を見,霊に触れる。<br/>',NULL,49623,2);
INSERT INTO stanza VALUES('J211','3','主は天のちゅう保者, めぐみのあぶら塗り;<br/>成就されたすべて, 霊のなかで受ける。<br/>',NULL,49624,3);
INSERT INTO stanza VALUES('J211','4','われ,何と不忠じつ, 主よ,あわれみたまえ;<br/>ながいき吹き込み, 機のうさせたまえ。<br/>',NULL,49625,4);
INSERT INTO stanza VALUES('J211','5','わがれいしぼんで, めぐみかたらぬとき,<br/>うちより息吹いて, なれで満たしませ。<br/>',NULL,49626,5);
INSERT INTO stanza VALUES('J212','1','聖霊のかぜ 天より吹く, ペンテコステ の日のよう;<br/>われくだき, われ生かし, あらたにし, かい放す。<br/>',NULL,49627,1);
INSERT INTO stanza VALUES('J212','chorus','吹く！吹く！ 聖れいのかぜ！ めぐみの くもはおおう！<br/>燃ゆ！燃ゆ！ せいべつの火！ 金のえい光 かがやく！<br/>',NULL,49628,2);
INSERT INTO stanza VALUES('J212','2','聖霊のくも, めぐみ満ち, まく屋のよう 覆われる;<br/>われ生かし, せいとなし, れいにある 住まいとす。<br/>',NULL,49629,3);
INSERT INTO stanza VALUES('J212','3','聖べつの火, われ燃やし, じゅんけつな ものとす;<br/>けがれ焼き, 世ぞく焼き, 神・人,調和し, せいとす。<br/>',NULL,49630,4);
INSERT INTO stanza VALUES('J212','4','金のひかり, われ照らし, しんせいを 得させる;<br/>かみとひと, 混ざり合い, ひと,かみを あらわす。<br/>',NULL,49631,5);
INSERT INTO stanza VALUES('J213','1','主よ,なが天のかぜ, われに吹けや！<br/>感動と復興のため, われに吹けや！<br/>',NULL,49632,1);
INSERT INTO stanza VALUES('J213','chorus','大能の主,来たれや, 聖れい吹けや！<br/>生けるみずとともに, われに吹けや！<br/>',NULL,49633,2);
INSERT INTO stanza VALUES('J213','2','大のうのれい,吹き, 障がい去らせ,<br/>いのちのれい,吹き, あい,満たせや。<br/>',NULL,49634,3);
INSERT INTO stanza VALUES('J213','3','ななばいの豊富の 分にあずかり；<br/>さんいちのかみを けいけんする。<br/>',NULL,49635,4);
INSERT INTO stanza VALUES('J214','1','かぜよ吹けよ, われらのえに,<br/>ちからをもて, 自由もたらし,<br/>リバイバルを 見るときまで，<br/>主にいのりもとめん。<br/>',NULL,49636,1);
INSERT INTO stanza VALUES('J214','chorus','いま吹き去らせよ！<br/>たい惰とねむりを！<br/>大かぜよ,来て, 吹きはらえや！<br/>消きょくてきなわれ。<br/>',NULL,49637,2);
INSERT INTO stanza VALUES('J214','2','あいのかぜよ, 吹きて燃やせ,<br/>冷えしこころ, 無かんしんを;<br/>天のいきもて 捨て去るまで,<br/>主にいのりもとめん。<br/>',NULL,49638,3);
INSERT INTO stanza VALUES('J214','3','ちからのかぜ, 霊を感どうし,<br/>よみがえりの いのち満たせ;<br/>まったくあつく 燃やさるまで,<br/>主にいのりもとめん。<br/>',NULL,49639,4);
INSERT INTO stanza VALUES('J215','1','わがうちでおしえる たえなるあぶら;<br/>かみとまじわるために, われをみちびく。<br/>',NULL,49640,1);
INSERT INTO stanza VALUES('J215','chorus','たえなるぬりあぶらは, わがうちにてみちびけり;<br/>たえなるぬりあぶらは, すべておしえり。<br/>',NULL,49641,2);
INSERT INTO stanza VALUES('J215','2','うちにあるこう油は, せい霊の運こう;<br/>主の血,根拠とすこう油, 効き目はとわに。<br/>',NULL,49642,3);
INSERT INTO stanza VALUES('J215','3','かみの本しつをもて, われを塗りたもう;<br/>かみのせい分すべてを, われに浸透さす。<br/>',NULL,49643,4);
INSERT INTO stanza VALUES('J215','4','あぶらに塗らるとき, まじわりに入る;<br/>ひかりのなかをあゆみ, あいに満たさる。<br/>',NULL,49644,5);
INSERT INTO stanza VALUES('J216','1','主の血あるところ, 塗りあぶら塗られる;<br/>ひとはかみに触れ, まじわりをたもつ。<br/>',NULL,49645,1);
INSERT INTO stanza VALUES('J216','2','血はわれあがない, わがつみをきよめる;<br/>あぶらはそのれい, ひとはかみを得る。<br/>',NULL,49646,2);
INSERT INTO stanza VALUES('J216','3','みわざしめす血と, ご自身しめすあぶら;<br/>わざとパースンにより, かみとひと,調和す。<br/>',NULL,49647,3);
INSERT INTO stanza VALUES('J216','4','血のきよめにより, ざいあくから解かれ,<br/>あぶら塗りにより, かみのよう素得る。<br/>',NULL,49648,4);
INSERT INTO stanza VALUES('J216','5','きよめ,あぶら塗り, かみとひとつとなる;<br/>血と塗りあぶらで, かみご自身,享受す。<br/>',NULL,49649,5);
INSERT INTO stanza VALUES('J216','6','血のひつ要なとき, 信じて,きよめもとむ;<br/>あぶらにふくして, かみとともに生く。<br/>',NULL,49650,6);
INSERT INTO stanza VALUES('J216','7','ひかり,愛なるかみ, 認しきして経験する;<br/>すべてなるかみを 享受し,かみといち。<br/>',NULL,49651,7);
INSERT INTO stanza VALUES('J217','1','何というえいこう, 聖れいうちにて,<br/>主を啓示し,照らし, 真理へみちびく。<br/>',NULL,49652,1);
INSERT INTO stanza VALUES('J217','chorus','満たせ,満たせ, 聖れいで満たせ;<br/>はぎ取り,からにし, 聖れいで満たせ。<br/>',NULL,49653,2);
INSERT INTO stanza VALUES('J217','2','いのちのれいもて われをかい放し,<br/>つみの法そくより はなれさせよや。<br/>',NULL,49654,3);
INSERT INTO stanza VALUES('J217','3','しかがたにがわを したいあえぐよう;<br/>わがかわきいやす, 聖れいをしたう。<br/>',NULL,49655,4);
INSERT INTO stanza VALUES('J217','4','死の地にいて,なお 主の霊で満たし,<br/>栄こうのかたちに つくり変えませ。<br/>',NULL,49656,5);
INSERT INTO stanza VALUES('J218','1','血しおのきよめで よろこびあふれ,<br/>いのちを受けしは, かわとなるため。<br/>生けるみずながし, その霊を満たし,<br/>かわきをうるおす うつわとなせや。<br/>',NULL,49657,1);
INSERT INTO stanza VALUES('J218','2','あまくゆたかなる たえなるすくい;<br/>満ちたるこころで 日々主あかしす。<br/>生けるみずながし その霊を満たし,<br/>ひとを主へと帰す うつわとなせや。<br/>',NULL,49658,2);
INSERT INTO stanza VALUES('J218','3','とうときうつわと われつくり上げ,<br/>めぐみといのちを 満たしに満たせ。<br/>生けるみずながし, その霊を満たし,<br/>ひとの飢えいやす うつわとなせや。<br/>',NULL,49659,3);
INSERT INTO stanza VALUES('J218','4','主よわれを占有し, なが霊を満たし,<br/>あふれにあふれて, とわにいたれや。<br/>生けるみずながし, その霊を満たし,<br/>わきいであふれる うつわとなせや。<br/>',NULL,49660,4);
INSERT INTO stanza VALUES('J219','1','主よ,飢えかわいて ただなれもとむ;<br/>主はかわきいやし, 飢え満たされる。<br/>',NULL,49661,1);
INSERT INTO stanza VALUES('J219','chorus','もとむ,もとむ, せい霊のとみを。<br/>',NULL,49662,2);
INSERT INTO stanza VALUES('J219','2','あゆみもあかしも, すべてに失ぱい,<br/>実もなく労苦して, 賛美さえもなし。<br/>',NULL,49663,3);
INSERT INTO stanza VALUES('J219','3','こころにかくれた, しっぱい,邪あく,<br/>自己満ぞく,傲まん, いま,こくはくす。<br/>',NULL,49664,4);
INSERT INTO stanza VALUES('J219','4','ちちよ,自己,虚えい, 高慢よりすくい,<br/>主とともに死んだ 事じつ知らせよ。<br/>',NULL,49665,5);
INSERT INTO stanza VALUES('J219','5','わがわざ,知恵,あい, ことばではなく,<br/>絶えずキリストが わがうちに生く。<br/>',NULL,49666,6);
INSERT INTO stanza VALUES('J219','6','主よ,ながせい霊を われにながせや;<br/>あかしびととなり, 主に栄こう帰す。<br/>',NULL,49667,7);
INSERT INTO stanza VALUES('J219','7','御名によりいのる, いま,かく信する。<br/>いのりは聞かれた, 主よ,賛美します。<br/>',NULL,49668,8);
INSERT INTO stanza VALUES('J219','chorus','賛美す,賛美す, いのり聞かれた。<br/>',NULL,49669,9);
INSERT INTO stanza VALUES('J220','1','霊にて霊より生まれた われら,かみの子は,<br/>聖れいの証印,たん保を, れいのなかで得る。<br/>されど,主のほう富の 享受をさらにしたう;<br/>ながれいで満たしませ, いのちあふるまで。<br/>',NULL,49670,1);
INSERT INTO stanza VALUES('J220','2','ないじゅうのせいれいは, ながいのちのれい,<br/>かれの「である」を通して, 豊富を享受させる。<br/>されど,ちからとして, さらになが霊ひつ要,<br/>奉仕,はたらきのために, われを装備しませ。<br/>',NULL,49671,2);
INSERT INTO stanza VALUES('J220','3','なが霊でバプテスマし, ちから着せたまえ;<br/>ちからの「ころも」を着て, われらはたたかう。<br/>かぜよ,ほのおのしたを, われらにあたえませ;<br/>あぶら塗らる証人とし, 御むねを成就する。<br/>',NULL,49672,3);
INSERT INTO stanza VALUES('J220','4','聖れいのちから得ても, なお,めぐみひつ要;<br/>肢たいの機能を果たし, ほう仕するために。<br/>霊をゆたかにそそぎ, めぐみをあたえませ;<br/>ながからだ建ぞうされ, しゅくふく得るため。<br/>',NULL,49673,4);
INSERT INTO stanza VALUES('J220','5','栄こうと王こくのため, 聞きませ,さけびを！<br/>わがひつようを満たし, 御むね成就しませ。<br/>なれの霊にあずかり, なれをてき用させや;<br/>満たし,そそぎ,めぐみに あずからせたまえ。<br/>',NULL,49674,5);
INSERT INTO stanza VALUES('J221','1','主はせいれいから, 生まれ,ひとと成り,<br/>つとめのまえより, 満たされていた。<br/>つとめのかい始に, れいのそそぎ受け,<br/>ちからを着せられ, つとめを果たす。<br/>',NULL,49675,1);
INSERT INTO stanza VALUES('J221','2','主の息吹きを受け, せい霊を吸い込み,<br/>ペテロら主の弟子, れいから生まる。<br/>そののちせい霊で, バプテスマされて,<br/>ちからを着せられ, つとめを果たす。<br/>',NULL,49676,2);
INSERT INTO stanza VALUES('J221','3','サウロ,エペソびと, サマリアびとらも,<br/>れいから生まれて, せいれいやどす。<br/>なおあん手により せい霊で満たされ,<br/>ちからを着せられ, かみにつかえる。<br/>',NULL,49677,3);
INSERT INTO stanza VALUES('J221','4','しんじるわれらも れいから生まれて,<br/>日ごとに主を飲み, ほう富きょう受す。<br/>されどせいれいの プレソｰはひつよう,<br/>ちからを着せられ, つとめを果たす。<br/>',NULL,49678,4);
INSERT INTO stanza VALUES('J221','5','主よ,経けんさせよ, れいのバプテスマ,<br/>ちからを着るのは けんぞうのため。<br/>われらはもとめる, うえよりのちから,<br/>主よ,経けんさせよ, れいのプレソｰを。<br/>',NULL,49679,5);
INSERT INTO stanza VALUES('J221','note','［プレソー――外側での満たし］<br/>',NULL,49680,6);
INSERT INTO stanza VALUES('J222','1','ああ,われらは霊のなかに<br/>バﾌﾟテスマされている;<br/>この事じつ,受け入れよ,<br/>バﾌﾟテスマされている。<br/>取れ！ 取れ！ 生ける信仰をもて;<br/>取れ！ 取れ！ この成就した事じつ。<br/>',NULL,49681,1);
INSERT INTO stanza VALUES('J222','2','新契やくのことば告ぐ,<br/>われらは霊のなかに,<br/>バプテスマされている,<br/>いまや,保持するのみ。<br/>保持せよ！　 生ける信仰をもて;<br/>保持せよ！ この成就した事じつ。<br/>',NULL,49682,2);
INSERT INTO stanza VALUES('J222','3','キリストは召会のえに<br/>せいれいをそそがれた;<br/>そのれいのバﾌﾟテスマの<br/>しゅくふくにあずかる。<br/>あずかれ！　 生ける信仰をもて;<br/>あずかれ！　この成就した事じつ。<br/>',NULL,49683,3);
INSERT INTO stanza VALUES('J222','4','からだにて調和しつつ,<br/>この事じつで行動す;<br/>つみ,うたがい,もはやなし,<br/>信仰によりこう動す。<br/>行動せよ！　 生ける信仰をもて;<br/>行動せよ！　この成就した事じつ。<br/>',NULL,49684,4);
INSERT INTO stanza VALUES('J223','1','主よ,われらみもとに来, ながちから要きゅうす;<br/>なが王こく勝つために, 天に座してたたかう！<br/>ちから！ちから！てんのちから！ われらに着せたまえ！<br/>ちから！ちから！からだとして, だい胆にいまさけぶ！<br/>',NULL,49685,1);
INSERT INTO stanza VALUES('J223','2','主よ,われら依りたのみ, ながあめを要きゅうす;<br/>ながみからだのために, ふさわしくはたらく。<br/>あめ！あめ！てんのあめに, われらをよくさせよ！<br/>あめ！あめ！からだとして, だい胆にいまさけぶ！<br/>',NULL,49686,2);
INSERT INTO stanza VALUES('J223','3','主よ,われら待ちのぞみ, ながほのお要きゅうす！<br/>ふくいんのため燃やし, ひとを主に帰させよ！<br/>ほのお！ほのお！ほのおのしたで, 宣べつたえるために,<br/>ほのお！ほのお！からだとして, だい胆にいまさけぶ！<br/>',NULL,49687,3);
INSERT INTO stanza VALUES('J224','1','キリスト,昇てんし, 天のうえに座す,<br/>かみより尊貴,栄光 かんむりとして受く;<br/>主は万有のげん首, すべて超えつす。<br/>',NULL,49688,1);
INSERT INTO stanza VALUES('J224','2','このキリストより その霊はくだる,<br/>からだにそそがれ, 肢たいをつよめる;<br/>召かいをとおして 天であがめらる。<br/>',NULL,49689,2);
INSERT INTO stanza VALUES('J224','3','受にくしてかみを ひとにもたらす;<br/>死と復かつとおし, ひとをかみに帰す;<br/>かみとひとの調和, 主にあり成就す。<br/>',NULL,49690,3);
INSERT INTO stanza VALUES('J224','4','昇天によりてんで 栄光の座に着く;<br/>主の主,王のおうは, すべての主権得る;<br/>霊のそそぎにより, 事じつ証めいす。<br/>',NULL,49691,4);
INSERT INTO stanza VALUES('J224','5','霊は召会にくだり, バプテスマする;<br/>霊のバプテスマは すでにかん成する;<br/>聖徒らこの事じつ, 召会であずかる。<br/>',NULL,49692,5);
INSERT INTO stanza VALUES('J224','6','ハレルヤ,成就した, いち度で永遠に！<br/>ハレルヤ,われらは すべてふくまれる！<br/>主は霊で召かいを バプテスマした！<br/>',NULL,49693,6);
INSERT INTO stanza VALUES('J225','1','主よ,ちからあたえよ, ながはたらきのため,<br/>われはよわく無のう, ちから着せよ！<br/>',NULL,49694,1);
INSERT INTO stanza VALUES('J225','chorus','ひれ伏し待ちのぞむ, なれに呼びもとめる,<br/>ながちからあたえよ, いまあたえよ！<br/>',NULL,49695,2);
INSERT INTO stanza VALUES('J225','2','主よ,しょう会かえりみ, たまものをあたえよ,<br/>よわ気にならぬよう, ちから着せよ！<br/>',NULL,49696,3);
INSERT INTO stanza VALUES('J225','3','ちからと権威着せよ, ペンテコステの日のよう,<br/>いまいのりにこたえ, ちから着せよ！<br/>',NULL,49697,4);
INSERT INTO stanza VALUES('J225','4','めぐみのあめ降らせ, ほのおをあたえませ;<br/>ながからだはもとむ, ちから着せよ！<br/>',NULL,49698,5);
INSERT INTO stanza VALUES('J226','1','いのちのれい,うちに入る,<br/>かわきいやす,みずのよう;<br/>れいを飲み,れいに満たされ,<br/>かわのように永遠にながれる。<br/>',NULL,49699,1);
INSERT INTO stanza VALUES('J226','2','ちからのれい,うえに来る,<br/>ころものようわれらよそおう;<br/>れいのなかで,バプテスマされ,<br/>奉仕のためちから,そなえらる。<br/>',NULL,49700,2);
INSERT INTO stanza VALUES('J226','3','いのちのれい,くう気のよう,<br/>いのちの実際,いぶき込む;<br/>ちからのれい,おおかぜのよう,<br/>うえよりくだって,行動させる。<br/>',NULL,49701,3);
INSERT INTO stanza VALUES('J226','4','主は復かつして,弟子らに,<br/>いのちの霊を息吹き込む;<br/>ペンテコステの日に昇天の主,<br/>かぜのようちからの霊そそぐ。<br/>',NULL,49702,4);
INSERT INTO stanza VALUES('J226','5','いのちの霊,いのちあたえ,<br/>ちからの霊,いのち強化す;<br/>ちからのれい,かぜのよう吹き,<br/>新鮮なくう気来て,呼吸させる。<br/>',NULL,49703,5);
INSERT INTO stanza VALUES('J226','6','ふたつ個々のれいならず,<br/>ひとつのれい,ふたつ機能;<br/>かみに満ち,かみを着せられ,<br/>かみとかんぜんに混ざり合う。<br/>',NULL,49704,6);
INSERT INTO stanza VALUES('J226','7','主よ,いのちの霊で満たし,<br/>なれのように成長させよ；<br/>そとに着せよ,ちからのれい,<br/>奉仕でながねがい満たすため。<br/>',NULL,49705,7);
INSERT INTO stanza VALUES('J227','1','血しおのきよめにて, あぶら塗りは来る;<br/>ゴルゴタを経なければ, ペンテコステはなし。<br/>きよめられなければ, ちからを受けられず;<br/>主をあかしするため, 自己を死にわたす。<br/>',NULL,49706,1);
INSERT INTO stanza VALUES('J227','chorus','十字架をとおして, たましい捨てる;<br/>だい価をはらって, 聖れいで満ちる。<br/>',NULL,49707,2);
INSERT INTO stanza VALUES('J227','2','まず,いわが打たれて, 生けるみずがわく;<br/>死をけい過したのち, 聖れいは満ち満つ。<br/>すべてを損と見なし, 主とともに死ぬなら,<br/>主のちからはくだり, 世からすくわれる。<br/>',NULL,49708,3);
INSERT INTO stanza VALUES('J227','3','まずさい壇,つぎに火,　 うしなって実を得る;<br/>すべてささげないなら, 御座にいたらない。<br/>すべてのことを捨て, かみにふくするなら,<br/>われら,ちからを得て, 主の委たく受ける。<br/>',NULL,49709,4);
INSERT INTO stanza VALUES('J227','4','まず,うつわ用意せよ, あぶら満たすため;<br/>まず,たに掘り起こせ; みずをながすため;<br/>ヨルダンけい過すれば, 霊の感かく増加する;<br/>死のバプテスマ経て, 栄光のはとを得る。<br/>',NULL,49710,5);
INSERT INTO stanza VALUES('J227','5','じゅくしたさくもつを 刈り入れるときに,<br/>たねがまず地に落ち, 死んだことを知る。<br/>死のけい験とおして, いのちははなひらき;<br/>ほうむりをけい過し, 霊のちからを得る。<br/>',NULL,49711,6);
INSERT INTO stanza VALUES('J227','6','主よ,このせまきみち, われにあゆませよ,<br/>たい志,野心を捨てて, したがい,苦難受く;<br/>ちからではなく,ただ ふかき死をもとめる;<br/>主よ,十字架の意義を, いま成し遂げませ。<br/>',NULL,49712,7);
INSERT INTO stanza VALUES('J228','1','主よ,血しおにて われをあらい,<br/>きよきあぶらを そそぎたまえ。<br/>わがせいかつは 失ぱいのみぞ,<br/>れいに満たせや, 主のため生く。<br/>',NULL,49713,1);
INSERT INTO stanza VALUES('J228','chorus','ああ,主よ,自己より, 解きはなちませ！<br/>いまよりとわに 主を満たせや。<br/>',NULL,49714,2);
INSERT INTO stanza VALUES('J228','2','なんとかわきし われのこころ;<br/>れいの満たしを せつにもとむ。<br/>打たれたいわに われをかくし,<br/>生けるみずにて, あふれさせよ。<br/>',NULL,49715,3);
INSERT INTO stanza VALUES('J228','3','冷えたるこころ, にぶきあゆみ;<br/>聖れいに満たせ, 主にそむかず。<br/>さい壇のうえに, わが身を置く;<br/>主の火よ,くだり, 焼き尽くせや。<br/>',NULL,49716,4);
INSERT INTO stanza VALUES('J228','4','主よ,十字架にて さらに燃やせ,<br/>われ,はいと化し, 主,増すために;<br/>日ごとその霊を 満ち満たせや,<br/>生けるいのちを ながすために。<br/>',NULL,49717,5);
INSERT INTO stanza VALUES('J228','note','［４　はい――灰］<br/>',NULL,49718,6);
INSERT INTO stanza VALUES('J229','1','アダムをはなれ, いまや主にある;<br/>ふるきは変わり, 新せんになる;<br/>いま主のめぐみ受け, いのち,平安満つ<br/>われ,主にあり賛美す！<br/>',NULL,49719,1);
INSERT INTO stanza VALUES('J230','1','ちちなるかみはかたる, 「われは世びとをあいす」;<br/>あまきかみのみことば, 「イェスはわれをあいする」。<br/>',NULL,49720,1);
INSERT INTO stanza VALUES('J230','chorus','われはよろこび満つ, 主,われをあいする;<br/>まことなるよろこび, 主のあいゆえ！<br/>',NULL,49721,2);
INSERT INTO stanza VALUES('J230','2','かつてかみをわすれて, とおくはなれまようも,<br/>イェスはわれをあいして, たずねさがし,もどしぬ。<br/>',NULL,49722,3);
INSERT INTO stanza VALUES('J230','3','イェスはわれをあいする, われもイェスをあいする;<br/>主はあいのゆえ来たり, つみをにない,死にたもう。<br/>',NULL,49723,4);
INSERT INTO stanza VALUES('J230','4','はかりがたきながあい, されどわれはいま知る,<br/>れいはわれにいん押し, イェスはわれをあいする。<br/>',NULL,49724,5);
INSERT INTO stanza VALUES('J230','5','かみのことばあるゆえ, こころもはや揺るがず;<br/>われはサタンに宣げんす, 「イェスはわれをあいす」と。<br/>',NULL,49725,6);
INSERT INTO stanza VALUES('J230','6','やがておうにまみえて, えい遠にわれはうたう;<br/>われのあいするうたは, 「イェスはわれをあいする！」<br/>',NULL,49726,7);
INSERT INTO stanza VALUES('J231','1','あまき主のあい, 賛美をさそう;<br/>苦難受けし主は, こころに住み,<br/>いのちとへい安と, たすけをたもう;<br/>いよいよあまく 新鮮な主の愛。<br/>いよよあまきあい, みつのしたたり;<br/>わがすべてをもてほめたとう, ふかき主のあい。<br/>',NULL,49727,1);
INSERT INTO stanza VALUES('J231','2','ふかき主のあい, 賛美たかまる;<br/>いとちかき主は われはなれず;<br/>さい愛のとものよう 愛情そそぎたもう;<br/>いよいよふかく, たかき主の愛。<br/>いよよふかきあい, うみよりふかし;<br/>たからかに絶えずほめたとう, ふかき主のあい。<br/>',NULL,49728,2);
INSERT INTO stanza VALUES('J231','3','柔和な主のあい, 賛美はとわに;<br/>このあいつよく, たぐいあらじ;<br/>天地うつりかわり, うみ枯れるとも,<br/>とわに不めつの, つよき主の愛。<br/>変わらぬ主のあい, かたくさだまる;<br/>とわに不変のあいほめたとう, つよき主のあい。<br/>',NULL,49729,3);
INSERT INTO stanza VALUES('J232','1','えい遠のあいを, めぐみにて知る;<br/>せいれいは来て, われにおしえる。<br/>かん全なへい安！ しん聖なかん喜！<br/>(重)われは主のもの, 主はわれのもの。<br/>',NULL,49730,1);
INSERT INTO stanza VALUES('J232','2','晴れわたるそら, みどりの野辺に,<br/>さえずるとりや, 咲くはなを見て,<br/>われのこころに 主のあいを見る;<br/>(重)われは主のもの, 主はわれのもの。<br/>',NULL,49731,2);
INSERT INTO stanza VALUES('J232','3','えい遠のうでに, われ,安そくして,<br/>なが愛のむねに, われ,まくらする。<br/>うたがい,自己捨て, えい遠にいこう;<br/>(重)われは主のもの, 主はわれのもの。<br/>',NULL,49732,3);
INSERT INTO stanza VALUES('J232','4','わが主イェスより はなすものなし,<br/>主はわがうちに み住まいつくる。<br/>てん地はほろび, くらくなっても,<br/>(重)われは主のもの, 主はわれのもの。<br/>',NULL,49733,4);
INSERT INTO stanza VALUES('J233','1','かみはわがつみを はい後に投げ捨て,<br/>あしのしたにして, もう,おもいださず。<br/>',NULL,49734,1);
INSERT INTO stanza VALUES('J233','chorus','わがおかしたつみ, すべてゆるされた。<br/>あつきくもを消すよう, つみ，すべてゆるす。<br/>',NULL,49735,2);
INSERT INTO stanza VALUES('J233','2','かみはわがつみを われよりとおざけ,<br/>うみに投げるよう, まったくぬぐい去る。<br/>',NULL,49736,3);
INSERT INTO stanza VALUES('J234','1','おお,何というあいでしょう, すくいぬしは血をながし,<br/>わたしのために死に, すくいをじょう就された！<br/>わたしがつみをおかしたのに,<br/>かみがわたしに代わり死なれた！<br/>なんというあいでしょう, かみはわがため死ぬ！<br/>',NULL,49737,1);
INSERT INTO stanza VALUES('J234','2','おお,何というおく義でしょう, だれも知り尽くせぬもの,<br/>かみのあいのひろさ, ながさ,たかさ,ふかさを！<br/>てん使たちも知らないすくい。<br/>ぜん地は伏して,主をほめたとう。<br/>すべてはあわれみ, いま,れいはいします！<br/>',NULL,49738,2);
INSERT INTO stanza VALUES('J234','3','おお,何というめぐみでしょう, 主はちちの御座をはなれ,<br/>御身を捨て,血ながし, のぞみなきひとすくう;<br/>めぐみは無だい価で無げんに,<br/>つみにあるわたしにもおよんだ！<br/>無だい価のめぐみ, わたしにさえおよぶ！<br/>',NULL,49739,3);
INSERT INTO stanza VALUES('J234','4','おお,何というかい放でしょう, 主はめぐみによりすくう;<br/>つみの奴れいとされ, くらきにいたわたしを;<br/>くさりは落ち,かいほうされて,<br/>主にしたがいゆき,かん喜満ちる。<br/>そくばく解かれて, こころ,歓喜に満ちる。<br/>',NULL,49740,4);
INSERT INTO stanza VALUES('J234','5','おお,何というへい安でしょう, もはやつみさだめはなし;<br/>主,わがうちに生きて, しんせいな義はおおう;<br/>めぐみの御座にすすみ出れば,<br/>キリストはわがかんむりとなる。<br/>だいたんにすすみ, 主をかんむりとし受く。<br/>',NULL,49741,5);
INSERT INTO stanza VALUES('J235','1','なぜおそれるのか？ つみは御子にあり,<br/>清さんされた;<br/>負さいははらわれ, 義なるかみはもはや,<br/>要きゅうし得ず。<br/>',NULL,49742,1);
INSERT INTO stanza VALUES('J235','2','まったきあがないは, わがつみの負さい,<br/>すべてはらう;<br/>血のそそぎを受け, めぐみにて義とされ,<br/>おそれはなし。<br/>',NULL,49743,2);
INSERT INTO stanza VALUES('J235','3','主はわたしのため, ゆるしかくとくし,<br/>あたえたもう;<br/>かみはなおわれに へんさいもとむのか？<br/>断じてあらず！<br/>',NULL,49744,3);
INSERT INTO stanza VALUES('J235','4','主のすくいのわざ, こころ安そくさせ,<br/>かいほうする;<br/>おそれず,しんじよ, 効き目ある主の血を,<br/>主は死にたもう。<br/>',NULL,49745,4);
INSERT INTO stanza VALUES('J236','1','「つみにさだーめない！」, 何ととうといことば！<br/>つみはイェスに帰され, われ,生かされる。<br/>',NULL,49746,1);
INSERT INTO stanza VALUES('J236','2','血はかみにたいして さらにまさってかたる;<br/>聖徒たちは主の目に, ほうせきのよう。<br/>',NULL,49747,2);
INSERT INTO stanza VALUES('J236','3','「つみにさだめない！」と, かみのことばかたる;<br/>われ,キリストにあり 完全にうつくしい。<br/>',NULL,49748,3);
INSERT INTO stanza VALUES('J236','4','すくいぬし,わがおう, 主,あおぎ見つづける;<br/>ながこころをあいし, 栄光,御名に帰す。<br/>',NULL,49749,4);
INSERT INTO stanza VALUES('J237','1','キリストはわれの義, われの美,われのころも,<br/>御まえにキリスト着て, よろこびに満ち,うたう。<br/>',NULL,49750,1);
INSERT INTO stanza VALUES('J237','2','主よ,ながとうとい血は, わがつみかいけつして,<br/>わがためかみの御座で, 永遠にべん護している。<br/>',NULL,49751,2);
INSERT INTO stanza VALUES('J237','3','なれ,義としたものを, だれ,つみにさだめるや？<br/>なれはあがない成就し, 負さいをすべてはらう。<br/>',NULL,49752,3);
INSERT INTO stanza VALUES('J237','4','アブラハム,義とされ, せい徒らも義とされた;<br/>すくわれたつみびとは, ただ主の御名をほこる。<br/>',NULL,49753,4);
INSERT INTO stanza VALUES('J237','5','とし経て,ふるびない, えい遠にしろいころも;<br/>その美,変わることなく, その栄こう,とわに新鮮。<br/>',NULL,49754,5);
INSERT INTO stanza VALUES('J237','6','天で栄光を見るとき, われらなお主をほこる;<br/>われの美,われのころも, われの義はわが主イェス。<br/>',NULL,49755,6);
INSERT INTO stanza VALUES('J238','1','わがのぞみの基礎, われの義キリスト;<br/>依りたのむものは, かれのほかになし。<br/>',NULL,49756,1);
INSERT INTO stanza VALUES('J238','chorus','いわなるキリスト, 堅固なるいしずえ！<br/>ほかはみなすな地！<br/>',NULL,49757,2);
INSERT INTO stanza VALUES('J238','2','くらやみ覆うとも, めぐみに安そくす;<br/>信こうのいかりを, 至せい所におろす。<br/>',NULL,49758,3);
INSERT INTO stanza VALUES('J238','3','契やくの血により, 揺らぐことはなし,<br/>周囲はたおれても, 主,かえりみられる。<br/>',NULL,49759,4);
INSERT INTO stanza VALUES('J238','4','ラｯパの音とともに, 主が来られるとき,<br/>義のころもを着て, 御座のまえに立つ。<br/>',NULL,49760,5);
INSERT INTO stanza VALUES('J239','1','かみはわがつみ, 主イェスに置く;<br/>主はのろい受け, われ,解放する。<br/>かみはわがつみ, 小ひつじに置く;<br/>主は苦難を受け, 負さいはらう。<br/>',NULL,49761,1);
INSERT INTO stanza VALUES('J239','2','わがやまい負い, むち打たれる;<br/>わがよわさ負い, 健康,得させる。<br/>わがなやみ負い, わがすべて負う;<br/>くるしみを消し, 平安得させる。<br/>',NULL,49762,2);
INSERT INTO stanza VALUES('J239','3','義なる主の死に, かみ満ぞくす;<br/>主の血はわれの 良心きよめる。<br/>主はわがちから, 主に依りたのむ;<br/>主のゆたかさは, われ,つよめる。<br/>',NULL,49763,3);
INSERT INTO stanza VALUES('J239','4','こころ主に帰し, 主を王とする,<br/>いのちなる主は, こころに住む。<br/>主のかたちへと つくり変えられ,<br/>振る舞い,あゆみ, 主を表現する。<br/>',NULL,49764,4);
INSERT INTO stanza VALUES('J240','1','はばかることもなく, 御まえにすすむ！<br/>つみびと,めぐみのゆえに, かみと和かいす！<br/>',NULL,49765,1);
INSERT INTO stanza VALUES('J240','2','かつては何ととおく, かみをはなれた！<br/>血を信じ,めぐみを受けて, いまへだてなし。<br/>',NULL,49766,2);
INSERT INTO stanza VALUES('J240','3','かみはちかくなった, これほどまでに;<br/>御子を通して子のように, かみとしたしむ。<br/>',NULL,49767,3);
INSERT INTO stanza VALUES('J240','4','かみのこよなきあい, きわみなるあい；<br/>御子をあいするがごとく, われをあいする。<br/>',NULL,49768,4);
INSERT INTO stanza VALUES('J240','5','もはやおそれはない, このかみを得た;<br/>「わたしはあなたのもの！」と， かみは言われる！<br/>',NULL,49769,5);
INSERT INTO stanza VALUES('J241','1','わがいのちにだい変化あり, 主,はいり来てのち;<br/>わがたましいにかみのえい光, いま照りかがやく。<br/>',NULL,49770,1);
INSERT INTO stanza VALUES('J241','chorus','主,はいり来てのち, いつもよろこびと,<br/>たのしみはうしおのように, あふれただよえり。<br/>',NULL,49771,2);
INSERT INTO stanza VALUES('J241','2','つみのきずなまったく解かる, 主,はいり来てのち;<br/>じょうとよくはもはやわれを, まどわすことなし。<br/>',NULL,49772,3);
INSERT INTO stanza VALUES('J241','3','揺りうごかぬのぞみを得ぬ, 主,はいり来てのち;<br/>いまやうたがいのくもさえ, わがみちおおわじ。<br/>',NULL,49773,4);
INSERT INTO stanza VALUES('J241','4','さすらいの人せい終わりぬ, 主,はいり来てのち;<br/>あまき主の安そくはつねに, わがこころ満たす。<br/>',NULL,49774,5);
INSERT INTO stanza VALUES('J241','5','過ぎしみち,もはやしたわじ, 主はいり来てのち;<br/>さいわいののぞみは引き寄す, ただしきみちへと。<br/>',NULL,49775,6);
INSERT INTO stanza VALUES('J242','1','わがこころは,よろこびに満ちる！<br/>よろこび満つ！　主はーいしのこころを,<br/>にくのこころに変える,<br/>れいのこうしん,われらをしんじんとす。<br/>',NULL,49776,1);
INSERT INTO stanza VALUES('J242','2','せいれいがわれをじゅうまんする！<br/>じゅうまんする！ つみー,よわさのぞいて,<br/>義の実むすぶ生かつさせたもう,<br/>せいれい,われーをじゅうまんする！<br/>',NULL,49777,2);
INSERT INTO stanza VALUES('J243','1','つみのおも荷を背負って, ながねんくるしんできた,<br/>みことばしんじ, 主を受け入れて,<br/>すべてかいほうされた。<br/>',NULL,49778,1);
INSERT INTO stanza VALUES('J243','chorus','かい放された！ つみより解かれ,ハレルヤ！<br/>かい放された！ つみより解かれ,ハレルヤ！<br/>',NULL,49779,2);
INSERT INTO stanza VALUES('J243','2','つみのおも荷を背負って, おそれおののいてきた,<br/>れいにしめされ, じゅう字架に来て,<br/>すべてかいほうされた。<br/>',NULL,49780,3);
INSERT INTO stanza VALUES('J243','3','つみのおも荷を背負って, おそれおののいてきた,<br/>御座にちかづき, 主の御かお見て,<br/>すべてかいほうされた。<br/>',NULL,49781,4);
INSERT INTO stanza VALUES('J243','4','わたしはかいほうされた, こえたかく主をうたう;<br/>主のため生きて, 日ごとさん美す;<br/>ハレルﾔ！かいほうされた。<br/>',NULL,49782,5);
INSERT INTO stanza VALUES('J244','1','主はわれをかい放された; イェスわがおう,すくいぬし;<br/>霊に満たされ,日々うたう; われ,かい放された！<br/>',NULL,49783,1);
INSERT INTO stanza VALUES('J244','chorus','栄こうのかいほう！ つみにしばられない;<br/>血であらわれ,ひかり得た; われ,かい放された！<br/>',NULL,49784,2);
INSERT INTO stanza VALUES('J244','2','地のきずな,断ち切られた; つみと情よく,ちからなし,<br/>おもいわずらい,なやみなし; われ,かい放された！<br/>',NULL,49785,3);
INSERT INTO stanza VALUES('J244','3','主はそくばく打ちやぶり, わがため,あく魔ほろぼす;<br/>めぐみのひかりかがやく; われ,かい放された！<br/>',NULL,49786,4);
INSERT INTO stanza VALUES('J245','1','かつては主のかい放を知らずに,<br/>くるしみ,つみの奴れいとなる;<br/>主イェスの御名呼び,われらは知る,<br/>主はすでにかい放すと。<br/>いま,めぐみ受け,つみよりはなれ,<br/>生けるみず飲み,すくい享受す;<br/>ハレルヤ！何とほう富,あまく,<br/>うつくしい,よろこび,主を賛美す！<br/>',NULL,49787,1);
INSERT INTO stanza VALUES('J246','1','つみのかせにしばられ, 奴れいのごとき身も,<br/>主はかせくだきしおり, 栄光の解放を受けた。<br/>',NULL,49788,1);
INSERT INTO stanza VALUES('J246','chorus','栄光の解放,くすし解放, ざいあくより解かる;<br/>主は栄光のすくいぬし, ふたたびしばられず。<br/>',NULL,49789,2);
INSERT INTO stanza VALUES('J246','2','にく,よく,ねたみ,うらみ, あらそいよりはなれ,<br/>この世,虚栄,ほまれなど, すべてよりはなれる。<br/>',NULL,49790,3);
INSERT INTO stanza VALUES('J246','3','まどわす金せんのよく, おのれのかたき意志,<br/>文字,律法のきずなより, くすしくも解かれた。<br/>',NULL,49791,4);
INSERT INTO stanza VALUES('J247','1','おどろくべきめぐみ！ われをもすくう！<br/>うしなわれたわれをたずね, 目ひらき見せる！<br/>',NULL,49792,1);
INSERT INTO stanza VALUES('J247','2','めぐみにておそれは 取りのぞかれた;<br/>信じたときの,あのめぐみは, なんととうとい。<br/>',NULL,49793,2);
INSERT INTO stanza VALUES('J247','3','めぐみをあたえると, 主は保しょうした;<br/>主はーわれのたて,とわの分, 全生がい過ごす。<br/>',NULL,49794,3);
INSERT INTO stanza VALUES('J247','4','万年後,主を見るとき, 照りかがやいて,<br/>はじめのころの賛美よりも, 賛美はふかまる。<br/>',NULL,49795,4);
INSERT INTO stanza VALUES('J248','1','主のめぐみは, われ,支はいし,<br/>つみのちから解き, 天然ほろぼす。<br/>',NULL,49796,1);
INSERT INTO stanza VALUES('J248','chorus','キリストは, うちに生く;<br/>めぐみは満ちた！ 十分なめぐみ！<br/>',NULL,49797,2);
INSERT INTO stanza VALUES('J248','2','めぐみにより, 天のみち行く,<br/>供きゅうはゆたかで, われ,みちびく。<br/>',NULL,49798,3);
INSERT INTO stanza VALUES('J248','3','何たるめぐみ！ にくたい取り,<br/>ひとにあらわれて, わがうち生く。<br/>',NULL,49799,4);
INSERT INTO stanza VALUES('J248','chorus','何たるわれ！ 主のめぐみ！<br/>われはめぐみで 更しんされる。<br/>',NULL,49800,5);
INSERT INTO stanza VALUES('J249','1','銀のひも切れる日, うたはうたえない;<br/>ある日われ目覚め, 主に会い,かん喜す。<br/>',NULL,49801,1);
INSERT INTO stanza VALUES('J249','chorus','御かお見てかたる, すくいのめぐみを;<br/>かお合わせかたる, すくいのめぐみを。<br/>',NULL,49802,2);
INSERT INTO stanza VALUES('J249','2','地じょうのまく屋も, いつかはたおれる;<br/>されどわれは知る, 主,ともにいること。<br/>',NULL,49803,3);
INSERT INTO stanza VALUES('J249','3','主のさいりんの日, 主のこえ聞きたし:<br/>「ちゅう信なしもべよ, あんそくにはいれ」｡<br/>',NULL,49804,4);
INSERT INTO stanza VALUES('J249','4','目を覚まし,そなえ, あかりをともして,<br/>かの日,主にまみえ, とわに主を享受す。<br/>',NULL,49805,5);
INSERT INTO stanza VALUES('J250','1','いずみよ,来たれや！ こころはうたう;<br/>尽きないあわれみ, さん美たかまる。<br/>さまよっていたわれに, キリストは来られ,<br/>かれの十字架にて, われを解ほうす。<br/>',NULL,49806,1);
INSERT INTO stanza VALUES('J250','2','めぐみのはげまし, ゆたかにあたえ,<br/>さまようこころを, しばり,とらえよ;<br/>あいのかみをはなれて, さまようことなく,<br/>なが霊のちからで, 引き寄せたまえ。<br/>',NULL,49807,2);
INSERT INTO stanza VALUES('J250','3','なれのすくい得て, つみと死はなれ，<br/>御子のかたちへと どう形化しませ。<br/>主,われをたすけたゆえ, エベネゼルを建て,<br/>ながよろこびにて, みちびき受ける。<br/>',NULL,49808,3);
INSERT INTO stanza VALUES('J251','1','わが持てるものすべて, めぐみによりたまわる;<br/>つみびとのわれさえ, 主のめぐみを受けた！<br/>',NULL,49809,1);
INSERT INTO stanza VALUES('J251','chorus','つみびとのわれが, 主のめぐみ受けた！<br/>えいこうをかみに帰す, 主のめぐみ受けた！<br/>',NULL,49810,2);
INSERT INTO stanza VALUES('J251','2','かつてつみにしばられ, かみより遠くはなれる;<br/>いまや主にもどされ, われはよろこび満つ！<br/>',NULL,49811,3);
INSERT INTO stanza VALUES('J251','3','なみだも効き目はなし, おこないも効き目なし;<br/>あわれみとめぐみで, かみよりめぐみ受く！<br/>',NULL,49812,4);
INSERT INTO stanza VALUES('J251','4','わがすくいぬしあいす, こころよろこびにわく;<br/>主のめぐみ得たゆえ, このめぐみをかたる！<br/>',NULL,49813,5);
INSERT INTO stanza VALUES('J252','1','かつてつみの奴隷,へい安知らず,<br/>つみのおも荷負い,安そくなし;<br/>自ゆうをもとめて,おも荷を増し,<br/>良き地のとおくにいた。<br/>',NULL,49814,1);
INSERT INTO stanza VALUES('J252','chorus','いま,たかきやま,晴れわたるそら,<br/>生けるみず飲み,かわきはなし,<br/>カナンの豊富:ちち,みつ,あぶらしたたる！<br/>いまや良き地にいる。<br/>',NULL,49815,2);
INSERT INTO stanza VALUES('J252','2','かみの小ひつじにあがなわれて,<br/>バプテスマされ,エジプト出た;<br/>あら野をたびして,さまよい終え,<br/>いまや良き地にはいる。<br/>',NULL,49816,3);
INSERT INTO stanza VALUES('J252','3','主の昇天により,ともに座に着き,<br/>空ちゅうの権威は,打ちやぶられ,<br/>主の名により,やみはちからなし,<br/>良き地で完全にしょう利。<br/>',NULL,49817,4);
INSERT INTO stanza VALUES('J252','4','こよなきへい安,無じょうのかん喜,<br/>うれいはなく,完ぜんな安そく,<br/>何とあまいかん喜,うたに満ちる,<br/>ハレルヤ,これぞ良き地。<br/>',NULL,49818,5);
INSERT INTO stanza VALUES('J253','1','わがこころのなかに, 主のうたごえあり:<br/>「われはなれを捨てず, とわにわがもの」。<br/>',NULL,49819,1);
INSERT INTO stanza VALUES('J253','chorus','イェス,イェス,イェス, あまき御名;<br/>まんぞく得て, うたいつすすむ。<br/>',NULL,49820,2);
INSERT INTO stanza VALUES('J253','2','つみにそこなわれて, こころいたむとき,<br/>主はわがうちに入り, わがうたとなる。<br/>',NULL,49821,3);
INSERT INTO stanza VALUES('J253','3','主のめぐみ,あい受け, ふところにいこい,<br/>主のほほえみを見て, よろこび,ほめる。<br/>',NULL,49822,4);
INSERT INTO stanza VALUES('J253','4','火のごとき苦難にも, 主はともにいまし,<br/>耐えがたきおも荷も, 主はになわれる。<br/>',NULL,49823,5);
INSERT INTO stanza VALUES('J253','5','かの日,主のかたちに, われさえ変えられ,<br/>ともにおうとなって, とわにおさめる。<br/>',NULL,49824,6);
INSERT INTO stanza VALUES('J254','1','かわかぬいのちのいずみ, たずね,つかれぬ;<br/>地のものみなわがこころ 満たすことなし。<br/>',NULL,49825,1);
INSERT INTO stanza VALUES('J254','chorus','かわかぬいずみ見いだし, いのちのいずみ飲まば,<br/>はかりがたきよろこびあり, いまいのちのいずみ飲む。<br/>',NULL,49826,2);
INSERT INTO stanza VALUES('J254','2','つみのあら野さまよわじ, いまいずみあり;<br/>わがさかずき満ちあふれん, キリスト満ちぬ。<br/>',NULL,49827,3);
INSERT INTO stanza VALUES('J254','3','あまくうるわしき満ぞく, 主のやすきあり;<br/>なぐさめ増しくわわりて, しゅくふく受けぬ。<br/>',NULL,49828,4);
INSERT INTO stanza VALUES('J254','4','きょうきゅうはとわにやまじ, めぐみによくす;<br/>いやしのいずみにひたり, とわにいこわん。<br/>',NULL,49829,5);
INSERT INTO stanza VALUES('J255','1','わがうちでかなでる たえなるしらべ;<br/>あいの主こそわがうた, てんのおんがく。<br/>',NULL,49830,1);
INSERT INTO stanza VALUES('J255','chorus','わがこころにうたあり, あまきメロデｨ,てんのうた;<br/>あいのうたのいずみが わがうちにあり。<br/>',NULL,49831,2);
INSERT INTO stanza VALUES('J255','2','なんたるあい,めぐみ, 主はわがいのち;<br/>あいとめぐみのうたを, よろこびうたう。<br/>',NULL,49832,3);
INSERT INTO stanza VALUES('J255','3','なんたるひかり,平安, われらみちびく;<br/>主はわれとともに住み, さん美わき出る。<br/>',NULL,49833,4);
INSERT INTO stanza VALUES('J255','4','なんたるちょうだつよ, われは上げられ,<br/>主とともに支はいして, がい歌をうたう。<br/>',NULL,49834,5);
INSERT INTO stanza VALUES('J255','5','なんたるしゅくふくよ, せいなるみやこ;<br/>いのちのみず,木の実に, とわにあずかる。<br/>［４　ちょうだつ――超脱(それを乗り越えて一段高い所へ出ること)］<br/>',NULL,49835,6);
INSERT INTO stanza VALUES('J256','1','キリスト,わがうた, こころのよろこび;<br/>主はともにいます, よろこび,うたおう！<br/>',NULL,49836,1);
INSERT INTO stanza VALUES('J256','chorus','ハレルヤ！よろこび, ハレルヤ！うたおう！<br/>主はともにいます, よろこび,うたおう！<br/>',NULL,49837,2);
INSERT INTO stanza VALUES('J256','2','かつておも荷負い, いま,へいあんある;<br/>主はつみをゆるし, わがすべてになう。<br/>',NULL,49838,3);
INSERT INTO stanza VALUES('J256','3','かつてはくらやみ, いま,ひかりがある;<br/>主はわれをすくい, 主のみち行かせる。<br/>',NULL,49839,4);
INSERT INTO stanza VALUES('J256','4','かつて,孤どく,悲哀, いま主がパートナｰ;<br/>主はともにいまし, すべてかえりみる。<br/>',NULL,49840,5);
INSERT INTO stanza VALUES('J256','5','あいにありあゆみ, めぐみにてふくす;<br/>あい,われをすくい, めぐみは保護する。<br/>',NULL,49841,6);
INSERT INTO stanza VALUES('J256','6','主のほかてんには, もとめるものなし！<br/>主のほか地上では, したうものはなし！<br/>',NULL,49842,7);
INSERT INTO stanza VALUES('J257','1','焼きつくかわきの いやしをもとめ,<br/>しょうがいいずみを したいつづけた。<br/>',NULL,49843,1);
INSERT INTO stanza VALUES('J257','chorus','ハレルヤ！かわきは すでに満たされ,<br/>キリストのいのち, われらをすくう。<br/>',NULL,49844,2);
INSERT INTO stanza VALUES('J257','2','いなごまめにより 飢えをしのいだ;<br/>ちからは消え去り, 飢えはつづいた。<br/>',NULL,49845,3);
INSERT INTO stanza VALUES('J257','3','まずしさのなかで, ほう富もとめた,<br/>得るものすべては ふん土のごとし。<br/>',NULL,49846,4);
INSERT INTO stanza VALUES('J257','4','生けるいずみわき, あふれつづけて,<br/>とわに不そくなし, わがすくいぬし。<br/>',NULL,49847,5);
INSERT INTO stanza VALUES('J258','1','かつてはのぞみもなく, くるしみもがけど,<br/>いまやキリストを得て, よろこびに満ち満つ。<br/>',NULL,49848,1);
INSERT INTO stanza VALUES('J258','chorus','わがこころ満たす主に, くらぶるものはなし;<br/>尽きぬ愛,いのち,かん喜, この主より受ける。<br/>',NULL,49849,2);
INSERT INTO stanza VALUES('J258','2','この世をきょう受しても, かわきはふかまり,<br/>地のなにものでさえも, わがこころ満たさず。<br/>',NULL,49850,3);
INSERT INTO stanza VALUES('J258','3','かつてしゅくふくもとめ, キリストもとめず;<br/>されど主,われをあいし, われを,たずねもとむ。<br/>',NULL,49851,4);
INSERT INTO stanza VALUES('J258','4','こわれたみずためより, 飲もうとしたわれ;<br/>されどみず,漏れていて, かわきはとどめ得じ。<br/>',NULL,49852,5);
INSERT INTO stanza VALUES('J258','5','すべてうしなったとき, 主は来てくださり,<br/>こころの目をひらいて, あいなる主を見せる。<br/>',NULL,49853,6);
INSERT INTO stanza VALUES('J259','1','なぜか？かみのめぐみが, わが身にのぞんだ;<br/>わたしのようなものに, すくいがおよんだ。<br/>',NULL,49854,1);
INSERT INTO stanza VALUES('J259','chorus','ただわたしは知っている: わたしのたくしたもの,<br/>主はかの日までも, かん全にまもる。<br/>',NULL,49855,2);
INSERT INTO stanza VALUES('J259','2','信仰がいかにこころに はいって来たのか？<br/>信じてすぐにあたらしい こころを得たのか？<br/>',NULL,49856,3);
INSERT INTO stanza VALUES('J259','3','どのようにせいれいが つみをみとめさせ,<br/>聖書により,主を見せて, 主を受けさせたか？<br/>',NULL,49857,4);
INSERT INTO stanza VALUES('J259','4','自分のぜん途わからぬ, あまいか,にがいか？<br/>主の御まえにいかなる 試れんがあるのか？<br/>',NULL,49858,5);
INSERT INTO stanza VALUES('J259','5','死のたにけい過するか, 空中で主に会うか？<br/>主はいつ来られるのか？ わたしは知らない。<br/>',NULL,49859,6);
INSERT INTO stanza VALUES('J260','1','かみはすでに堅固な土だいを, かみのことばで据えられた。<br/>主に信頼して,避なん所にはいり, みことばにより,堅固にまもられ,<br/>主により永遠に保証される。<br/>',NULL,49860,1);
INSERT INTO stanza VALUES('J260','2','信じるものはとわにほろびず, 主の御手によりまもられる。<br/>イェスとちちはえいえんにひとつ; ちちが主イェスにたまわるものを,<br/>主はなにひとつうしなわず。<br/>',NULL,49861,2);
INSERT INTO stanza VALUES('J260','3','主,わがために死なれたゆえに, かみはわれらを義とされた。<br/>義とされ,またあいされるものを, だれがうったえ,だれがほろぼし,<br/>だれが引き裂き得るだろう？<br/>',NULL,49862,3);
INSERT INTO stanza VALUES('J260','4','主はご自身に来るもの捨てず, ゆだねるものをまもられる。<br/>主,わがいのち,われは主の肢たい, 主にけつごうし,主といちとなる;<br/>主と分けるもの,なにもなし。<br/>',NULL,49863,4);
INSERT INTO stanza VALUES('J260','5','悪しきものが,まどわすときに, こころになみが立つときに,<br/>主のことばをしっかりと取って, 信仰のいかりをふかく下ろせば,<br/>とわにこころは揺るぎなし。<br/>',NULL,49864,5);
INSERT INTO stanza VALUES('J261','1','めぐみ受けたものよ,みな来て,<br/>豊富なめぐみにかん謝せよ！<br/>主,つみあがない,いのちをあたえた。<br/>ともに主に来て,ほめうたうたう,<br/>わがすくいぬし,キリストを。<br/>',NULL,49865,1);
INSERT INTO stanza VALUES('J261','2','愛されたもの,揺れうごかない,<br/>主のふかきあい,ほめうたえ！<br/>すくい成就し,とわにうちに住む。<br/>ともに主に来て,感謝,賛美します,<br/>わがすくいぬし,キリストを。<br/>',NULL,49866,2);
INSERT INTO stanza VALUES('J261','3','召され,聖とされ,栄光得たもの,<br/>超えつした名をさん美せよ！<br/>イェス,万有の主,いともたかきおう,<br/>ともに主に来て,れいはいします,<br/>わがすくいぬし,キリストを。<br/>',NULL,49867,3);
INSERT INTO stanza VALUES('J262','1','えい光のひかりいま, こころを照らす;<br/>目にうつるものみな, かがやき満つ。<br/>',NULL,49868,1);
INSERT INTO stanza VALUES('J262','chorus','えい光のひかり満つ, よろこび寄せ来たる;<br/>主がほほえみはなつとき, えいこうあふる。<br/>',NULL,49869,2);
INSERT INTO stanza VALUES('J262','2','こころにしらべあり, 主をほめたとう;<br/>わがうたつたなくも, 主は聞きたもう。<br/>',NULL,49870,3);
INSERT INTO stanza VALUES('J262','3','こころにやすきあり, 主,うちに住まば;<br/>めぐみのはなひらき, はともうたう。<br/>',NULL,49871,4);
INSERT INTO stanza VALUES('J262','4','こころによろこびと のぞみ,賛美あり;<br/>めぐみの主はすでに, 賞与そなえる。<br/>',NULL,49872,5);
INSERT INTO stanza VALUES('J263','1','この日に,わたしは,　 主イェスをえらんだ！<br/>こころはかん喜し,　　よろこび,つたえる。<br/>',NULL,49873,1);
INSERT INTO stanza VALUES('J263','chorus','たのしい,たのしい, 主のすくいを得た！<br/>血によりあらわれ, いのちのみずわく！<br/>日ごと,イェスは, すくいを享受さす！<br/>',NULL,49874,2);
INSERT INTO stanza VALUES('J263','2','わたしは主のもの, 主はわたしのもの;<br/>主に引き寄せられ, 主の召しに応じる。<br/>',NULL,49875,3);
INSERT INTO stanza VALUES('J263','3','こころはさだまり, 主を第いちとする;<br/>ただ主を見つめて, しゅくふくに満ちる。<br/>',NULL,49876,4);
INSERT INTO stanza VALUES('J263','4','御まえでけつ意を, 日ごとあらたにし,<br/>この世を去っても, とわに主とひとつ。<br/>',NULL,49877,5);
INSERT INTO stanza VALUES('J264','1','おく義！すくいぬしと 　われはひとつ。<br/>御子にありたまいし 　くしきすくい;<br/>ハレル,ハレルヤ！ 　栄光のおくぎ！<br/>主よりはなすものは, 　なにもあらず。<br/>',NULL,49878,1);
INSERT INTO stanza VALUES('J264','2','超えつす！主とともに, 　ふっかつした;<br/>ざいあく,あく魔より, 　解ほうされた;<br/>ハレル,ハレルヤ！ 　栄光の超えつ,<br/>超えつし,主とともに 　われは生きる。<br/>',NULL,49879,2);
INSERT INTO stanza VALUES('J265','1','たしかに主わがもの！ あがない,めぐみ受け,<br/>れいにより生まれて, かみの世継ぎとなる。<br/>',NULL,49880,1);
INSERT INTO stanza VALUES('J265','chorus','これこそわがあかし, これこそわがしい歌！<br/>すくいぬしさん美し, 絶えずよろこび満つ！<br/>',NULL,49881,2);
INSERT INTO stanza VALUES('J265','2','かんぜんにふくして, 主のあまさにひたる;<br/>みこえはつねにあり, あいの主のささやき。<br/>',NULL,49882,3);
INSERT INTO stanza VALUES('J265','3','かんぜんにやすらぐ, まじわりのあまさよ；<br/>絶えず主とまじわり, 主ご自身で満ち足る。<br/>',NULL,49883,4);
INSERT INTO stanza VALUES('J266','1','かみの意志,さだめ, 知る知しきないが，<br/>かみのみぎにいる すくいぬしを知る。<br/>',NULL,49884,1);
INSERT INTO stanza VALUES('J266','2','「主,つみびとのため, 十字架で死なれた」,<br/>このことばしんじ, すくいを享受する。<br/>',NULL,49885,2);
INSERT INTO stanza VALUES('J266','3','御子の死以がいに すくいのみちなし;<br/>御子の死ゆえ,ただ さん美しつづける。<br/>',NULL,49886,3);
INSERT INTO stanza VALUES('J266','4','栄こうの天,はなれ, 主は地でくるしむ;<br/>この奇怪な事じつ, いのちで理かいす。<br/>',NULL,49887,4);
INSERT INTO stanza VALUES('J266','5','主よ,われのうえに, ながはたらき見て,<br/>労苦の結果のゆえ, まんぞくしませや。<br/>',NULL,49888,5);
INSERT INTO stanza VALUES('J266','6','生きるも,死ぬにも, 主よりちから得る;<br/>いまや永遠の王は, かつて死なれた主。<br/>',NULL,49889,6);
INSERT INTO stanza VALUES('J267','1','十字架の主を無視し, むなしく生きてきた;<br/>主,わがため死なれた, 　　カルバリで。<br/>',NULL,49890,1);
INSERT INTO stanza VALUES('J267','chorus','無だい価のめぐみで, 多くのつみ,ゆるされ,<br/>いま,かいほうされた, カルバリで。<br/>',NULL,49891,2);
INSERT INTO stanza VALUES('J267','2','かみのひかりにより, つみを知ったわれは,<br/>いま,かん全に転機す, カルバリで。<br/>',NULL,49892,3);
INSERT INTO stanza VALUES('J267','3','主にすべてをささげ, かれのしもべとなり,<br/>いま,よろこびうたう, カルバリで。<br/>',NULL,49893,4);
INSERT INTO stanza VALUES('J267','4','ああ！あいはけいかくす！ めぐみはひとに来る！<br/>かみにもどすちから！ カルバリで。<br/>',NULL,49894,5);
INSERT INTO stanza VALUES('J268','1','主のへい安がながれて,いま, わたしにおよんだ;<br/>かなしみが怒とうのよう, 押しせまり来るとも,<br/>',NULL,49895,1);
INSERT INTO stanza VALUES('J268','chorus','すべてやすし！　へい安をきょう受する。<br/>',NULL,49896,2);
INSERT INTO stanza VALUES('J268','2','あく魔こころみ,おどすとも, こころはやすらか;<br/>わがよわさ,主は知られて, すくいをじょう就する。<br/>',NULL,49897,3);
INSERT INTO stanza VALUES('J268','3','つみはみな十字架について, わたしを覆わない;<br/>このへい安,このよろこび, ハレルヤ,主をうたう！<br/>',NULL,49898,4);
INSERT INTO stanza VALUES('J268','4','生きるのはキリストであり, すべてを支はいす;<br/>死のなみが押しせまるも, もはや苦つうはなし。<br/>',NULL,49899,5);
INSERT INTO stanza VALUES('J268','5','御つかいのラｯパ,主のみこえ, さい臨待ちのぞむ;<br/>よろこびとのぞみ,いかに！ えいえんのしゅくふく！<br/>',NULL,49900,6);
INSERT INTO stanza VALUES('J269','1','しかがたにのみずを したうように,<br/>われはただかみと, めぐみをもとめる。<br/>',NULL,49901,1);
INSERT INTO stanza VALUES('J269','2','生けるかみ,わがかみ, かみにかわく;<br/>かみにしたしんで, かみをきょう受する。<br/>',NULL,49902,2);
INSERT INTO stanza VALUES('J269','3','かみはわれのいのち, ちから,住まい;<br/>キリストのなかで, われ,まんぞくする。<br/>',NULL,49903,3);
INSERT INTO stanza VALUES('J269','4','御かおはわがすくい, かみをあおぐ;<br/>なが同ざいもとむ, めぐみあたえませ。<br/>',NULL,49904,4);
INSERT INTO stanza VALUES('J269','5','しかのようみずしたい, かみをもとむ;<br/>かみこそゆいいつ, ひつようのすべて。<br/>',NULL,49905,5);
INSERT INTO stanza VALUES('J270','1','もとめるのはただかみ, かみのなにかではない;<br/>めぐみ得,代価をはらい, せいなる地へといたる。<br/>',NULL,49906,1);
INSERT INTO stanza VALUES('J270','2','信こうによりかみ得て, 愛にて,かみにしたがう;<br/>かみのすべてで満たし, 自己よりはなれさせよ。<br/>',NULL,49907,2);
INSERT INTO stanza VALUES('J270','3','ときにはみちはくらく, 代価つねにおもくとも,<br/>かみ,わがひつよう知り, ひたすらかみを得さす。<br/>',NULL,49908,3);
INSERT INTO stanza VALUES('J270','4','きょうも明日もただしたう, 日々,かみはわがひつ要;<br/>かみをしたいもとめて, かの日に褒しょうを得る。<br/>',NULL,49909,4);
INSERT INTO stanza VALUES('J271','1','全のうのいのちなるかみ, わがさけび聞きたまえ;<br/>無限の栄こうなるかみよ, われ,ながいのちもとめる。<br/>',NULL,49910,1);
INSERT INTO stanza VALUES('J271','2','御子の十字架をとおして, 死の効き目をとおして,<br/>やみより,あいする御子の ひかりのくにへとうつる。<br/>',NULL,49911,2);
INSERT INTO stanza VALUES('J271','3','われは中心より満たされ, しゅう囲へと満たされる;<br/>わが身のすべてにおよび, なが栄こうかがやき出る。<br/>',NULL,49912,3);
INSERT INTO stanza VALUES('J271','4','いと聖なるかみのいのち, いのちの霊,われに住む;<br/>なが栄こう,あらわさせよ, なれのほか,われもとめず。<br/>',NULL,49913,4);
INSERT INTO stanza VALUES('J271','5','ちちよ,ながめぐみを得て, 十字架にて主をほこる;<br/>いのちのなかで支はいし, ほう富ないのちきょう受す。<br/>',NULL,49914,5);
INSERT INTO stanza VALUES('J272','1','燃えるしばのよう, われにあらわれよ！<br/>なれのめぐみ受け, 栄光あらわさせよ。<br/>',NULL,49915,1);
INSERT INTO stanza VALUES('J272','2','価値なきしばに, 奇せきあらわれる;<br/>かみはちからもて, かみのわざしめす。<br/>',NULL,49916,2);
INSERT INTO stanza VALUES('J272','3','火はかみご自身, かみにより燃える;<br/>かみ,このしばより, 栄光あらわされる。<br/>',NULL,49917,3);
INSERT INTO stanza VALUES('J272','4','かみはしばより, ご自身をあらわす;<br/>めぐみをとおして, 栄光あらわさせよ！<br/>',NULL,49918,4);
INSERT INTO stanza VALUES('J273','1','わが建てしわざこわし,<br/>かみ,わが前途を変える;<br/>汚めい着て,誤かいされ,<br/>なお忠信にふく従したし。<br/>',NULL,49919,1);
INSERT INTO stanza VALUES('J273','chorus','なみだゆえ,御かお見えず,<br/>みことばも取り得ないが,<br/>われ減少し,なれ増加して,<br/>御むねあまくあらせよ。<br/>',NULL,49920,2);
INSERT INTO stanza VALUES('J273','2','ながみ手を閉じたまえ,<br/>われに受くちからなし;<br/>されどかみよ,譲歩せず,<br/>われのふくじゅう待ちませ。<br/>',NULL,49921,3);
INSERT INTO stanza VALUES('J273','3','なが御むね,よろこびが,<br/>くるしみ負うことなら,<br/>あまんじて苦難を受け,<br/>御むねにふくすをねがう。<br/>',NULL,49922,4);
INSERT INTO stanza VALUES('J273','4','くだくこと,御むねなら,<br/>だい価をもいとわない;<br/>ながさえぎり歓げいし,<br/>ながこころをよろこばす。<br/>',NULL,49923,5);
INSERT INTO stanza VALUES('J273','5','主はひとをさいわいにし,<br/>わが頭上を轢きとおる;<br/>主はすべてはぎ取るも,<br/>はぎ取る御手はのこせや。<br/>',NULL,49924,6);
INSERT INTO stanza VALUES('J274','1','かみの超えつすあい, 天のよろこび来て,<br/>いやしきわれに住み, われの恩賞となる。<br/>主はあわれみふかく, 純粋で無限のあい;<br/>われかえりみるため, わがこころに入る。<br/>',NULL,49925,1);
INSERT INTO stanza VALUES('J274','2','主よ,聖霊を息吹けや， うれえるこころに;<br/>なが豊富にあずかり, 安そく享受させよ。<br/>つみをしたうこころ, きずな,のぞき去り,<br/>いのちのみち知らせ, まったく解放しませ。<br/>',NULL,49926,2);
INSERT INTO stanza VALUES('J274','3','たいのうの主よ,来て, いのち供給しませ;<br/>えい遠にともにいて, みやに住まわせよ。<br/>御名をほめたたえて, よろこびつかえる,<br/>絶えず賛美し,いのり, ながあいをほこる。<br/>',NULL,49927,3);
INSERT INTO stanza VALUES('J274','4','純けつできずのない, 新創造,完成しませ;<br/>偉大なすくい,われを なれに同形化する;<br/>栄光へとつくり変え, 豊満へと到たつす;<br/>栄光にはいり,とわに ながあいたたえる。<br/>',NULL,49928,4);
INSERT INTO stanza VALUES('J275','1','とうとき愛の主は, あまくこまやか;<br/>うるわしきゆえに, われは自己いとう,<br/>ひいでし愛の主を なににくらぶや？<br/>',NULL,49929,1);
INSERT INTO stanza VALUES('J275','2','とうとき,愛の主よ！ ながまねき聞く;<br/>みこえはいりきて, きずなを断ち切り,<br/>わがもとめしもの, むなしくなせり。<br/>',NULL,49930,2);
INSERT INTO stanza VALUES('J275','3','とうとき,愛の主よ！ いかで我をはらん？<br/>かたきこころ捨て, 主のいえにかえり,<br/>なが奴れいとなり, よろこびつかえん。<br/>',NULL,49931,3);
INSERT INTO stanza VALUES('J275','4','とうとき,愛の主よ！ ながみちえらばん;<br/>なみだながすとも, なおもしたがいて,<br/>なれのよろこびと あいのむちしたう。<br/>',NULL,49932,4);
INSERT INTO stanza VALUES('J275','5','とうとき,愛の主の 世を去りしより,<br/>のぞみと笑み失せ, ただなれをしたう;<br/>主よ,ふたたび来て, ともにましませ。<br/>',NULL,49933,5);
INSERT INTO stanza VALUES('J275','6','とうとき,愛の主よ！ われに言わせよ,<br/>「なれこそまんぞく, あさゆうしたわん」と,<br/>すべてなれにあり, ほかにもとめじ。<br/>',NULL,49934,6);
INSERT INTO stanza VALUES('J275','7','とうとき,愛の主は, あまくこまやか;<br/>うるわしきゆえに わがすべてささげん;<br/>ひいでし愛の主を なににくらぶや？<br/>',NULL,49935,7);
INSERT INTO stanza VALUES('J276','1','愛すもの取るなら, 主をあたえよ;<br/>誤かい受けるとき, 主をあたえよ。<br/>',NULL,49936,1);
INSERT INTO stanza VALUES('J276','chorus','主イェス,愛の主よ, 主をあたえよ;<br/>まったくしたがう, 主をあたえよ。<br/>',NULL,49937,2);
INSERT INTO stanza VALUES('J276','2','生きがい取るなら, 主をあたえよ;<br/>環きょうゆるすなら, 主をあたえよ。<br/>',NULL,49938,3);
INSERT INTO stanza VALUES('J276','3','たよるもの取れば, 主をあたえよ;<br/>いのりこばむなら, 主をあたえよ。<br/>',NULL,49939,4);
INSERT INTO stanza VALUES('J276','4','忍たいさせるなら, 主をあたえよ;<br/>再臨おくれるなら, 主をあたえよ。<br/>',NULL,49940,5);
INSERT INTO stanza VALUES('J277','1','はいりませ！もんひらく; ながこえと知るゆえに。<br/>日はしずみ,あらし来る; いまは主のとき,来ませ！<br/>',NULL,49941,1);
INSERT INTO stanza VALUES('J277','2','ああ,このみだれた部屋よ: テｰブルざつに置かれて,<br/>良きおとずれのかたを もてなすよう意はなし！<br/>',NULL,49942,2);
INSERT INTO stanza VALUES('J277','3','されど,なれむかえたし, われのみじめな部屋に;<br/>ながひかりで照らして, みだれをととのえませ。<br/>',NULL,49943,3);
INSERT INTO stanza VALUES('J277','4','主をむかえるにあたり, われ,もはやつくろわず;<br/>すべてのもの,見ぐるしい, ありのまま主むかえる。<br/>',NULL,49944,4);
INSERT INTO stanza VALUES('J277','5','来ませや,このこころに, くらやみ,つみをのぞき,<br/>永じゅうの住まいとして, 主イェスよ,いま来ませや！<br/>',NULL,49945,5);
INSERT INTO stanza VALUES('J278','1','真のひかりよ！ やみをのぞき,<br/>まひるのよう われを照らせ！<br/>',NULL,49946,1);
INSERT INTO stanza VALUES('J278','chorus','最上のひかりよ, 真のよろこび;<br/>われのこころに 住みたまえや。<br/>',NULL,49947,2);
INSERT INTO stanza VALUES('J278','2','真のよろこび！ われにはいり,<br/>つみをのぞき, 平あん満たせ！<br/>',NULL,49948,3);
INSERT INTO stanza VALUES('J278','3','真のいのちよ！ われにはいり,<br/>死,飲み尽くし, いのち満たせ！<br/>',NULL,49949,4);
INSERT INTO stanza VALUES('J278','4','まことのあい！ われにはいり,<br/>更しんしませ, あいを満たせ！<br/>',NULL,49950,5);
INSERT INTO stanza VALUES('J278','5','まことのてん！ われにのぞみ,<br/>混乱,くろくも, のぞきたまえ！<br/>',NULL,49951,6);
INSERT INTO stanza VALUES('J278','6','主よ,来ませや！ こころに住み,<br/>豊富なりん在, 主よ,あたえよ！<br/>',NULL,49952,7);
INSERT INTO stanza VALUES('J279','1','主よ,豊富をもて来たり, 生かされたわがこころを,<br/>かえりみたまえ;<br/>血のきよめ受けたゆえ, なれの豊富あずかり,<br/>享受させたまえ。<br/>',NULL,49953,1);
INSERT INTO stanza VALUES('J279','2','こころよ,単いつになれ！ 主とともに十字架で死に,<br/>いま,かみに生く。<br/>われらはすでにこの世, 偶像,娯らくに死んだ,<br/>なれ,わが栄こう。<br/>',NULL,49954,2);
INSERT INTO stanza VALUES('J279','3','絶えずかわきをあたえ, ひたすら主をしたわせよ！<br/>なれはわがあい。<br/>主以がいにしたわない, なれはわれのめぐみ;<br/>なれ,わがすべて！<br/>',NULL,49955,3);
INSERT INTO stanza VALUES('J279','4','主のゆえ,みなうしない, いま,主をすべてとし得る,<br/>なれは永遠の分。<br/>主のまじわりに召され, ただなれをあいする,<br/>さらにめぐみを！<br/>',NULL,49956,4);
INSERT INTO stanza VALUES('J280','1','主はわれのいのち, いのちの供きゅう;<br/>わがれいかえりみ, ゆたかにせよ。<br/>',NULL,49957,1);
INSERT INTO stanza VALUES('J280','2','せいれい息吹いて, なれをあたえよ;<br/>なが十字架と死を, ともに経験す。<br/>',NULL,49958,2);
INSERT INTO stanza VALUES('J280','3','主,サタンに勝つとも, われとあらそう;<br/>われを終わらせて, きょうきゅうせよ。<br/>',NULL,49959,3);
INSERT INTO stanza VALUES('J280','4','なれご自身たまい, わが天然,死なせ,<br/>ともにほうむられて, ともに生きる。<br/>',NULL,49960,4);
INSERT INTO stanza VALUES('J280','5','わがうち支はいし, てきを征ふくす;<br/>みかたちあらわし, なれを生きる。<br/>',NULL,49961,5);
INSERT INTO stanza VALUES('J280','6','すべてつみのぞき, なが住まいとせよ;<br/>栄こうしみわたり, かみ,あらわす。<br/>',NULL,49962,6);
INSERT INTO stanza VALUES('J281','1','なれをさらに 愛させよ！<br/>わがすべてで 愛させよ！<br/>これぞわれの あつきねがい：<br/>主よ，さらに 愛させよ！<br/>',NULL,49963,1);
INSERT INTO stanza VALUES('J281','2','かつてわれは この世の，<br/>平安，たのしみ, もとめた；<br/>されどいまは ただ主，もとむ。<br/>主よ，さらに 愛させよ！<br/>',NULL,49964,2);
INSERT INTO stanza VALUES('J281','3','なげき，いたみ おくって，<br/>われをさ らに 対処せよ！<br/>これはなれの あまきつかい，<br/>主よ，さらに 愛させよ！<br/>',NULL,49965,3);
INSERT INTO stanza VALUES('J281','4','いき,引き取る ときにも,<br/>なれをさらに ほめうたう。<br/>わがこころは なおもねがう,<br/>主よ,さらに 愛させよ！<br/>',NULL,49966,4);
INSERT INTO stanza VALUES('J282','1','わがあゆみで, 苦なん受け,<br/>くるしむのが さだめなら,<br/>苦なんとおし まじわりが,<br/>さらにあまく なるように。<br/>',NULL,49967,1);
INSERT INTO stanza VALUES('J282','2','地のたのしみ 失せるなら,<br/>さらにてんを あたえませ;<br/>地のつながり 失せるなら,<br/>主とのけつ合 あまくなる。<br/>',NULL,49968,2);
INSERT INTO stanza VALUES('J282','3','孤どくなみち, 主とともに,<br/>はげまし受け, まっとうする;<br/>主のちからで 自己失せて,<br/>きよきうつわ, 主をながす。<br/>',NULL,49969,3);
INSERT INTO stanza VALUES('J283','1','吹け,きたかぜよ！ みなみかぜよ！<br/>こころのそのに, かおり散らせ。<br/>',NULL,49970,1);
INSERT INTO stanza VALUES('J283','chorus','ねがわくは愛すかた, 来て,どうざいしたまえ。<br/>純けつなわがあいを, あじわい,きょう受しませ。<br/>',NULL,49971,2);
INSERT INTO stanza VALUES('J283','2','ナﾙドの香油,かけ, あしを拭いた;<br/>王が座すときに, かおり満たす。<br/>',NULL,49972,3);
INSERT INTO stanza VALUES('J283','3','なれはりんごの木, 木かげに座す;<br/>実,じゅくし,あまく, ちから得さす。<br/>',NULL,49973,4);
INSERT INTO stanza VALUES('J283','4','わが愛すものよ, われ主のもの;<br/>さあ,いなかに行き, 享受しましょう。<br/>',NULL,49974,5);
INSERT INTO stanza VALUES('J283','5','ながこころにて, われを印とす;<br/>死よりつよき愛, 洪水も消せず。<br/>',NULL,49975,6);
INSERT INTO stanza VALUES('J283','6','なれ以がい,天に だれ持ち得よう？<br/>なれ以がい,地に だれをしたう？<br/>',NULL,49976,7);
INSERT INTO stanza VALUES('J284','1','みそばに引き寄せて, 御かお見させ,<br/>あいのことば, 聞かせたまえ;<br/>主とへだてはなし。<br/>',NULL,49977,1);
INSERT INTO stanza VALUES('J284','2','地はさわぎ,荒れても, 忠せい尽くし,<br/>ほそきみこえ, 聞かせたまえ;<br/>主とへだてはなし。<br/>',NULL,49978,2);
INSERT INTO stanza VALUES('J284','3','おもいわずらいなく, 自己あいなく,<br/>つくろいなく, 主とまじわる;<br/>主とへだてはなし。<br/>',NULL,49979,3);
INSERT INTO stanza VALUES('J284','4','なれ,ちかくいませば, うたがい去り,<br/>おそれもやみ, へいあん得る;<br/>主とへだてはなし。<br/>',NULL,49980,4);
INSERT INTO stanza VALUES('J284','5','主よ,かがやきたまえ, 邪あくを消し,<br/>わがこころで, おうとなれや;<br/>主とへだてはなし。<br/>',NULL,49981,5);
INSERT INTO stanza VALUES('J284','6','ただなれにしたがい, ただなれを見,<br/>帰するところ, ただなれのみ;<br/>主とへだてはなし。<br/>',NULL,49982,6);
INSERT INTO stanza VALUES('J284','7','なが永遠の栄こうを 見るときには,<br/>暗こくはなく, ひかりに満つ;<br/>主とへだてはなし。<br/>',NULL,49983,7);
INSERT INTO stanza VALUES('J284','8','ある日,地をはなれて, とわになれと,<br/>ともに住まう, そのときまで,<br/>主とへだてはなし。<br/>',NULL,49984,8);
INSERT INTO stanza VALUES('J285','1','たかきやまの上で, ただ主を見たし,<br/>天のみこえを聞き, 新鮮な空気を吸う。<br/>',NULL,49985,1);
INSERT INTO stanza VALUES('J285','chorus','さらにたかねへと, みちびきたまえ;<br/>霊のいずみ飲みて, さらに主,享受す。<br/>',NULL,49986,2);
INSERT INTO stanza VALUES('J285','2','ひかり増すやまへ, 地を遠くはなれ;<br/>いのちにあり主と ともに支配する。<br/>',NULL,49987,3);
INSERT INTO stanza VALUES('J285','3','目当てに向かって, たゆまずのぼる;<br/>ながみかたち成り, 愛とめぐみ満つ。<br/>',NULL,49988,4);
INSERT INTO stanza VALUES('J286','1','主,毎時ひつ要, なれをもとむ;<br/>やさしきこえ, われなぐさむ。<br/>',NULL,49989,1);
INSERT INTO stanza VALUES('J286','chorus','主,わがひつよう, まい時ひつ要,<br/>いま,ちから得て, なれに行く。<br/>',NULL,49990,2);
INSERT INTO stanza VALUES('J286','2','主,毎時ひつ要, 主が来ませば,<br/>誘わくは失せ, なれはしたしい。<br/>',NULL,49991,3);
INSERT INTO stanza VALUES('J286','3','主,毎時ひつ要, 苦らくあるも;<br/>主があるなら, むなしさなし。<br/>',NULL,49992,4);
INSERT INTO stanza VALUES('J286','4','主,毎時ひつ要, われ,みちびき,<br/>良きやくそく, じょう就しませ。<br/>',NULL,49993,5);
INSERT INTO stanza VALUES('J286','5','主,毎時ひつ要, いと聖なる主;<br/>完全にとわに, われを得ませ。<br/>',NULL,49994,6);
INSERT INTO stanza VALUES('J287','1','主よ,なれのみこえ聞き, なが無限の愛知る;<br/>しん仰にてたかめられ, かわきもとめる。<br/>',NULL,49995,1);
INSERT INTO stanza VALUES('J287','chorus','引き寄せ,いたらせよ, なが血の場所へ;<br/>主よ,りんざいのなかへと, いま,引き寄せよ。<br/>',NULL,49996,2);
INSERT INTO stanza VALUES('J287','2','めぐみにて聖べつされ, 専いつにつかえる;<br/>わがねがい,主のなかで, 失せ去るように。<br/>',NULL,49997,3);
INSERT INTO stanza VALUES('J287','3','ただ御座に触れるなら, よろこびあふれる;<br/>かおとかお,見合わせて, とものよう交流す。<br/>',NULL,49998,4);
INSERT INTO stanza VALUES('J287','4','愛とふかさ知り尽くす, かの日,御座にあり！<br/>よろこびのたかさ知る, 主と安そくして！<br/>',NULL,49999,5);
INSERT INTO stanza VALUES('J288','1','主よ,ともに住みたまえ;<br/>夕日は落ち,やみおおい,<br/>安そくも,たすけもない,<br/>主よ,ともに住みたまえ。<br/>',NULL,50000,1);
INSERT INTO stanza VALUES('J288','2','人せいはすぐ過ぎ去り,<br/>地のたのしみ,消え去る;<br/>すべては変わり,朽ちる;<br/>主よ,ともに住みたまえ。<br/>',NULL,50001,2);
INSERT INTO stanza VALUES('J288','3','威厳でなく,慈あい持ち,<br/>いやしのつばさひろげ,<br/>あいもて,われなぐさむ;<br/>主よ,ともに住みたまえ。<br/>',NULL,50002,3);
INSERT INTO stanza VALUES('J288','4','主の臨ざいつねにあれ,<br/>めぐみにてしょう利得る;<br/>みちびくのはなれのみ;<br/>主よ,ともに住みたまえ。<br/>',NULL,50003,4);
INSERT INTO stanza VALUES('J288','5','しゅくふくゆえ,打ち勝つ;<br/>やまいも死もおそれず;<br/>われらともに勝利得る;<br/>主がともに住まうゆえ。<br/>',NULL,50004,5);
INSERT INTO stanza VALUES('J288','6','死ぬときもともにいませ;<br/>なが御かお,あおがせよ;<br/>主,ふたたび来るときも,<br/>主よ,ともに住みたまえ。<br/>',NULL,50005,6);
INSERT INTO stanza VALUES('J289','1','第いちの主！おお,主イェスよ！ くらべるものなし,<br/>かく言,信条,この世の愛, 主とくらべ得ず。<br/>',NULL,50006,1);
INSERT INTO stanza VALUES('J289','2','第いちの主！おお,主イェスよ！ 主のあいにふくす;<br/>主の十字架により死に, ただ主に生きる。<br/>',NULL,50007,2);
INSERT INTO stanza VALUES('J289','3','第いちの主！おお,主イェスよ！ 全存ざい主に満つ;<br/>ながおもいとよろこび, わがものとなる。<br/>',NULL,50008,3);
INSERT INTO stanza VALUES('J289','4','第いちの主！おお,主イェスよ！ われを変貌させて；<br/>このにくのまく屋より, 栄光をあらわす。<br/>',NULL,50009,4);
INSERT INTO stanza VALUES('J289','5','第いちの主！おお，主イェスよ！ なが御むねしたう;<br/>全生がい奴れいとなり, なれにつかえる。<br/>',NULL,50010,5);
INSERT INTO stanza VALUES('J290','1','あさな夕ーなに主よ,われは 　　なれをしたう世かいあり;<br/>なれ以がーいをしたわずに, 　　たのしませや,ただなれを。<br/>くるしくかなしいときにも, こころはげますものーなきときも,<br/>なみだほほをぬらすときも, 　　主よぬぐいて,なぐさめや。<br/>',NULL,50011,1);
INSERT INTO stanza VALUES('J290','2','わがゆめーはうるわしくも, 　　ながうちにおらせたまえ;<br/>主のほかーにたのしませず, 　　じぶん勝手にせぬように！<br/>しずかなよるにもとむるは, 主がわれとともにいーますことぞ;<br/>あさつとーにわれもとむは, 　　主のささやく,ほそきこえ。<br/>',NULL,50012,2);
INSERT INTO stanza VALUES('J290','3','みことばーに触れるたびに, 　　みひかりもて見せたまえ,<br/>すくいぬーしとそのめぐみ, 　　すべてわれにぞくするを。<br/>たよりもなくくずおるとき, いのりを聞きてめぐーみたまえや,<br/>たとえいーのりとどかずも, 　　ともにいませ,御かお見る。<br/>',NULL,50013,3);
INSERT INTO stanza VALUES('J290','4','てんのさーちをおもうたび, 　　なれにまみゆるをしたう;<br/>主の来たーる日,ともにある, 　　そのよろこび,待ちのぞむ。<br/>御まえに生くすべおしえや, あさ夕なれはわがひーとつ世かい,<br/>なれ以がーいをしたわずに, 　　たのしませや,ただなれを。<br/>',NULL,50014,4);
INSERT INTO stanza VALUES('J291','1','主よ,霊のなかに われをみちびき,<br/>ひかりのなかを あゆませたまえ。<br/>',NULL,50015,1);
INSERT INTO stanza VALUES('J291','chorus','主よ,主よ, いのちへとみちびき,<br/>いのちのなかを, 　あゆませたまえ。<br/>',NULL,50016,2);
INSERT INTO stanza VALUES('J291','2','いのちの法そく, われをみちびく;<br/>なれの支はいで, やみをひかりへ。<br/>',NULL,50017,3);
INSERT INTO stanza VALUES('J291','3','霊をかいほうし, われを規せいし,<br/>おもいを変えて, 御むね満たせや。<br/>',NULL,50018,4);
INSERT INTO stanza VALUES('J292','1','さまよわず,ただ, 主のみちを行く;<br/>主のそばにいて, 主のあいに住む。<br/>',NULL,50019,1);
INSERT INTO stanza VALUES('J292','chorus','主よ,主よ, 迷路よりすくいませ;<br/>さき見えずとも, 　みちびきたまえ。<br/>',NULL,50020,2);
INSERT INTO stanza VALUES('J292','2','なれは避なん所, なにもおそれず！<br/>なれにしたしみ, あわれみ受ける。<br/>',NULL,50021,3);
INSERT INTO stanza VALUES('J292','3','みちびきつづけ, 再りんにいたり,<br/>永えんのどう在, 安そくきょう受す。<br/>',NULL,50022,4);
INSERT INTO stanza VALUES('J293','1','主よ,わがみちを えらびたまえ,<br/>いかなる苦難も, あまんじ受け,<br/>なれのさだめし みちをあゆむ;<br/>ながよろこびを われはもとむ。<br/>',NULL,50023,1);
INSERT INTO stanza VALUES('J293','chorus','わが手を取りて みちびきませ,<br/>われのよわさを なれ,知るゆえ;<br/>いかなるときも, どんなみちも,<br/>ながみちびきは, われにあまし。<br/>',NULL,50024,2);
INSERT INTO stanza VALUES('J293','2','ただ主のえらび, われはもとむ,<br/>なが意志に反し, なにもできぬ;<br/>自己のかんがえで なにも決めず,<br/>主よ,わがみちを えらびたまえ。<br/>',NULL,50025,3);
INSERT INTO stanza VALUES('J293','3','御むねのままに けいかくなせ;<br/>自己の意志捨て, したがわせよ;<br/>なれのさだめが, にんたいなら,<br/>とき,はやまるを われ,ねがわず。<br/>',NULL,50026,4);
INSERT INTO stanza VALUES('J293','4','のこりのじん生 えらびたまえ;<br/>御むねのままに, 主よ,決めませ;<br/>なれのたまいし きょう受以がい,<br/>わがよろこびと ならぬように。<br/>',NULL,50027,5);
INSERT INTO stanza VALUES('J293','5','やまい,けんこう, なみだ,笑がお,<br/>あくひょう,こう評, 御むねのまま。<br/>主よ,えらびませ, われ,もとめず,<br/>ながえいこうを せつにもとむ。<br/>',NULL,50028,6);
INSERT INTO stanza VALUES('J294','1','手を取れ,われ,ながたすけ,<br/>ささえなしにあゆめず;<br/>手を取れ！主よ,わざわいが<br/>われをふるわぬように。<br/>',NULL,50029,1);
INSERT INTO stanza VALUES('J294','2','手を取れ！さらに引き寄せ,<br/>なれにちかくあらせよ;<br/>手を取れ！なれをはなれて,<br/>まようことないように。<br/>',NULL,50030,2);
INSERT INTO stanza VALUES('J294','3','手を取れ！予期せぬみちを,<br/>御かおで照らしたまえ;<br/>信こうで栄こう見るとき,<br/>われの歓喜,うたとなる。<br/>',NULL,50031,3);
INSERT INTO stanza VALUES('J294','4','手を取れ！主よ,くらきみち,<br/>なれのようにあゆむとき;<br/>天のひかりが照らすなら,<br/>くらき夜もひるとなる。<br/>',NULL,50032,4);
INSERT INTO stanza VALUES('J295','1','なれのみちなら, くるしくとも;<br/>主よ,わがみち, えらびたまえ。<br/>',NULL,50033,1);
INSERT INTO stanza VALUES('J295','2','順ぷう,ぎゃくふう, すべてさい善;<br/>みちはすべて, 主の安そくへ。<br/>',NULL,50034,2);
INSERT INTO stanza VALUES('J295','3','自分でえらばず, 自分で成さず,<br/>主よ,わがみち, さだめたまえ。<br/>',NULL,50035,3);
INSERT INTO stanza VALUES('J295','4','苦難,たのしみを なれはえらぶ;<br/>わがさかずき, なれに満ちる。<br/>',NULL,50036,4);
INSERT INTO stanza VALUES('J295','5','主よ,えらびませ, やまい,健こう,<br/>主,えらびませ, 貧困も繁栄も。<br/>',NULL,50037,5);
INSERT INTO stanza VALUES('J295','6','もはやこのみで, われ,えらばず;<br/>主はみちびき, 知恵とたから。<br/>',NULL,50038,6);
INSERT INTO stanza VALUES('J296','1','さらに主を知って, 主のみちをあゆみ,<br/>主のあがない知り, 豊富を享受したし。<br/>',NULL,50039,1);
INSERT INTO stanza VALUES('J296','chorus','主を知りたし, 主を知りたし。<br/>主のあがない知り, 豊富を享受したし。<br/>',NULL,50040,2);
INSERT INTO stanza VALUES('J296','2','復かつのたい能を, 朽ちないいのちを,<br/>昇てんの権のうを, えいこうの勝利を。<br/>',NULL,50041,3);
INSERT INTO stanza VALUES('J296','3','せいれいのけい示, ちちがみのおもい,<br/>まくのうちのこと, 主のあがないの死。<br/>',NULL,50042,4);
INSERT INTO stanza VALUES('J296','4','みことば,めぐみに, さらに依りたのむ;<br/>主のしゅつ現したい, 王こく待ちのぞむ。<br/>',NULL,50043,5);
INSERT INTO stanza VALUES('J297','1','愛させたまえ, 主よ,さらに,<br/>燃えたたせよ, 御名のため,<br/>ながうれいを おぼえつつ,<br/>みことば信じ, ふくじゅうす。<br/>',NULL,50044,1);
INSERT INTO stanza VALUES('J297','chorus','ながちからもて, 日々まもりませ,<br/>主よ，せまきみち, 生涯ゆかせよ。<br/>',NULL,50045,2);
INSERT INTO stanza VALUES('J297','2','主に忠じつで， 勝利を得て，<br/>やく立たせよ， 主のなかで；<br/>労苦すること よろこびて，<br/>苦なんに耐え， 依りたのむ。<br/>',NULL,50046,3);
INSERT INTO stanza VALUES('J297','3','天にぞくして， 主,つねに見,<br/>主,おもいつつ, 再臨したう;<br/>ひくきところ, われ,ねがい,<br/>主に似るため, 自己捨てる。<br/>',NULL,50047,4);
INSERT INTO stanza VALUES('J298','1','主よ,わがうちになれを 生かしめたまえ！<br/>日ごとにつみより解き, ちかくいませや;<br/>かよーわきわれーをば, 日々ささえたまえ,<br/>死をも飲み尽くすなが いのちのなかで。<br/>',NULL,50048,1);
INSERT INTO stanza VALUES('J298','2','ながみひかりによりて 照らされるおり,<br/>すべての悪しきおもい, 消え去りゆけり;<br/>われーなにもあーらじ, なれ万ゆうにます,<br/>ねがわくはつねに,主よ, おしえさとせや。<br/>',NULL,50049,2);
INSERT INTO stanza VALUES('J298','3','さらに多くあおがせよ, えいこうの主を,<br/>なれ,かくもせいけつと まことに満てり。<br/>よろーこびの日ーにも, くるしみの日にも,<br/>生けるみかたちに,主よ, 似させたまえや。<br/>',NULL,50050,3);
INSERT INTO stanza VALUES('J298','4','うえよりのよろこびに, われをば満たし,<br/>ながれいのちからもて, われをささえよ。<br/>ながーねつれつーなる あいのほのおもて,<br/>つらぬき燃やせや,わが うちをくまなく。<br/>',NULL,50051,4);
INSERT INTO stanza VALUES('J298','5','主よ,みじめなわれをば, 日ごとに去らせ,<br/>なれをいのち,めあてと なさせたまえや。<br/>ながーみめぐみーもて, 日々つくり変えて,<br/>主よ,御名にふさわしき ものとなしませ。<br/>',NULL,50052,5);
INSERT INTO stanza VALUES('J299','1','天のたびのかて, せい徒のパン,<br/>日々天のマナ食べ, 天の性しつ持つ;<br/>主,したい,きょう受し, 豊富あずかれば,<br/>地のたのしみ失せ, こころ満ち足る。<br/>',NULL,50053,1);
INSERT INTO stanza VALUES('J299','2','裂けしいわより わき出るみず,<br/>主は愛のみなもと, かん美ないずみ。<br/>無だい価で飲ませ, かわきをいやす;<br/>もはや他のみずを 永遠にもとめず。<br/>',NULL,50054,2);
INSERT INTO stanza VALUES('J299','3','主を食べ飲みし, 礼拝し,感謝す;<br/>ことばとれいにて, 主の愛あじわう。<br/>いのちをやしない, 豊満の身のたけ<br/>度りょうへと成長し, なれをあらわす。<br/>',NULL,50055,3);
INSERT INTO stanza VALUES('J300','1','主に似ること, 真にねがう。<br/>このせつ望を 成就しませ。<br/>',NULL,50056,1);
INSERT INTO stanza VALUES('J300','2','れいなる主に 経過させて,<br/>このねがいは 成就される。<br/>',NULL,50057,2);
INSERT INTO stanza VALUES('J300','3','おおいなきかお かがみとし,<br/>主の栄光見て, 主をうつす。<br/>',NULL,50058,3);
INSERT INTO stanza VALUES('J300','4','おおいをのぞき, たんいつに,<br/>主を見つめて, うつし出す。<br/>',NULL,50059,4);
INSERT INTO stanza VALUES('J300','5','かおとかおを 合わせ,見て,<br/>他のなににも そらされず。<br/>',NULL,50060,5);
INSERT INTO stanza VALUES('J300','6','つくり変えは わがもく標;<br/>証いん押され, 主をうつす。<br/>',NULL,50061,6);
INSERT INTO stanza VALUES('J300','7','主のかたちに 変えられて,<br/>栄光から栄光, かぎりなし！<br/>',NULL,50062,7);
INSERT INTO stanza VALUES('J301','1','主よ,われ,したいもとむ, あいの主に似ること;<br/>われ,持てるもの捨てて, ながかたち持ちたし。<br/>',NULL,50063,1);
INSERT INTO stanza VALUES('J301','chorus','主よ,なれに似せたまえ, ながあまさ,まことに;<br/>ながすがた,みかたちを, こころにきざみませ。<br/>',NULL,50064,2);
INSERT INTO stanza VALUES('J301','2','主よ,なれに似せたまえ, なれは柔和,こまやか;<br/>孤どくなひと,はげまし つみびと,たずね出す。<br/>',NULL,50065,3);
INSERT INTO stanza VALUES('J301','3','主よ,なれに似せたまえ, なれは忍たい,けん虚;<br/>理不じんな苦なん受け, ひとのため,死なれる。<br/>',NULL,50066,4);
INSERT INTO stanza VALUES('J301','4','主よ,なれに似せたまえ, われはだい価はらう;<br/>わがすべてをささげて, なれにしたがいゆく。<br/>',NULL,50067,5);
INSERT INTO stanza VALUES('J301','5','主よ,なれに似せたまえ, なれのあいをそそぎ,<br/>わがこころを満たせや, ながみやとなるため。<br/>',NULL,50068,6);
INSERT INTO stanza VALUES('J302','1','おく義,実さい, わがうちで,<br/>ふたつ霊,いま, ひとつれい！<br/>',NULL,50069,1);
INSERT INTO stanza VALUES('J302','2','霊にてあゆむ れいのひと;<br/>霊にてつかえ, 霊をはいす。<br/>',NULL,50070,2);
INSERT INTO stanza VALUES('J302','3','霊のまじわり, 霊つよめる;<br/>読み,いのって, 霊たかめる。<br/>',NULL,50071,3);
INSERT INTO stanza VALUES('J302','4','わが霊つよめ, ひと生かす！<br/>わが霊たかめ, ひと解放す！<br/>',NULL,50072,4);
INSERT INTO stanza VALUES('J302','5','こえ出すたび, 霊,うごかす！<br/>行動すたびに, 霊を供給す！<br/>',NULL,50073,5);
INSERT INTO stanza VALUES('J302','6','霊をうごかし, 霊,啓はつす！<br/>霊で行どうし, 霊をおこす！<br/>',NULL,50074,6);
INSERT INTO stanza VALUES('J302','7','霊を吹きかけ, ひとの霊を,<br/>ゆたかにして, 倍加しませ！<br/>',NULL,50075,7);
INSERT INTO stanza VALUES('J303','1','聖徒は無限のあい知るも, 御すがたを見ない;<br/>天使,つねに御かお見るも, 大きなあい知らぬ。<br/>やがて聖徒らは御かお見, 主のえいこう知る;<br/>かつてマリアは見て知った, 主の目のなみだと,<br/>こころのいたみを。<br/>',NULL,50076,1);
INSERT INTO stanza VALUES('J303','2','やがて主をかん全に知る, かつてないほどに;<br/>いたむこころをいやす手, かの日は感じない。<br/>かの日,無げんの賛美だけ, なみだのいのりや,<br/>病むこころのなぐさめや, こんなんのなかで<br/>たよることもない。<br/>',NULL,50077,2);
INSERT INTO stanza VALUES('J303','3','かの日,かんむりはあっても, この十字架はない;<br/>主が苦難受けたゆえ,いま, 主とまじわり持つ。<br/>安そくに入れば,つかれや, 主のための苦なん,<br/>主のためけい過する試練, 主のため捨て去る<br/>幸ふくはなくなる。<br/>',NULL,50078,3);
INSERT INTO stanza VALUES('J303','4','主のためくるしむ機かい, もうすぐなくなる,<br/>主のため受ける侮じょくや, 嘲笑,もう多くない。<br/>誤かい,はずかしめ,孤どく, 離べつもなくなる;<br/>苦難のしゅくふくとうとび, これらをとおして,<br/>主とけつごうする。<br/>',NULL,50079,4);
INSERT INTO stanza VALUES('J303','5','御かお見ることをしたう， いちにちもはやく；<br/>されどいま試練のあまさ， うしないたくない。<br/>大いなるあいに満たされ， 主のために生きる；<br/>将らいをせつ望すあまり， いま機かいのがし,<br/>かの日に悔いるな。<br/>',NULL,50080,5);
INSERT INTO stanza VALUES('J304','1','イェスはわがいのち, なれ生かし出す;<br/>どのもんだいでも， こたえは主イェス。<br/>主よ,なが意のまま われにはたらいて，<br/>透明なうつわとし, 主を表現させよ。<br/>',NULL,50081,1);
INSERT INTO stanza VALUES('J304','2','からだをささげた, せいべつされた;<br/>えいこうのほのお, あらわれいでよ。<br/>わがからだはいま ささげられている;<br/>じゅう順の奴れいは 主にて行どうす。<br/>',NULL,50082,2);
INSERT INTO stanza VALUES('J304','3','かく肢たい,つねに 主の指示を待つ,<br/>準備し,くびき負う, もちいられずも。<br/>主よ,われせい限し, ふく従させたまえ;<br/>たい処にあまんじ, へい安に満ちる。<br/>',NULL,50083,3);
INSERT INTO stanza VALUES('J304','4','にゅう和で安そくし, へん見を捨てる;<br/>なれの意のままに, 指示したまえや。<br/>イェスはわがいのち, なれを生かし出す;<br/>どのもんだいでも, こたえは主イェス。<br/>',NULL,50084,4);
INSERT INTO stanza VALUES('J305','1','ちちよ,わが生がいは, なが案配と知る;<br/>なにが起ころうとも, われ,おそれない;<br/>ちゅうじつになれにつかえ, 笑がお見たし。<br/>',NULL,50085,1);
INSERT INTO stanza VALUES('J305','2','絶えず目覚めている かしこさもとむ;<br/>どんな環きょうの変化も, よろこびむかえ,<br/>そのかんきょうにアーメンして, なぐさめ受く。<br/>',NULL,50086,2);
INSERT INTO stanza VALUES('J305','3','えらんだことまよわず, あせることなく,<br/>大きなこともとめず, ひみつも知らず,<br/>子どものようにあつかわれ, したがいたし。<br/>',NULL,50087,3);
INSERT INTO stanza VALUES('J305','4','いずこにいようとも, いかなるときも,<br/>わがこころのけつ意, つねに維持する;<br/>あいのゆえ,微りょく尽くし, 王につかえる。<br/>',NULL,50088,4);
INSERT INTO stanza VALUES('J305','5','日々のめぐみさずけ, 日々おしえませ,<br/>主とまじわるときに, うち,そと調和す;<br/>自己の満ぞくでなく,主の 栄光もとめる。<br/>',NULL,50089,5);
INSERT INTO stanza VALUES('J305','6','すべてに虚偽がある, 忍耐させるため,<br/>どこにも十字架ある, 主にたよるため;<br/>主によりへりくだるなら, みなあいらしい。<br/>',NULL,50090,6);
INSERT INTO stanza VALUES('J305','7','主をあいするあいが 満ちるをいのる;<br/>多くはたらくことを のぞまずにただ,<br/>主をよろこばせることを, われはもとむ。<br/>',NULL,50091,7);
INSERT INTO stanza VALUES('J305','8','愛のさだめの選たく, そくばくでない;<br/>ひそかなみちびきを 受けしわれには。<br/>自己を捨てるあいこそは 自由の生がい。<br/>',NULL,50092,8);
INSERT INTO stanza VALUES('J306','1','主が死にてわれは生く, 　主のため生く,<br/>わがため死んだ主のため, いのち,愛ささげる。<br/>',NULL,50093,1);
INSERT INTO stanza VALUES('J306','chorus','おお主イェス,すくいぬし！ 主にしたがわせよ;<br/>主が死に,生きたように, われ,死に,生きたし。<br/>',NULL,50094,2);
INSERT INTO stanza VALUES('J306','2','主が死にてわれは死ぬ, 　つみ,自己,世に。<br/>何たるおく義,死とせい！ 連合し,依りたのむ！<br/>',NULL,50095,3);
INSERT INTO stanza VALUES('J306','3','主,生きるゆえわれ生き, 「自己」もはやない;<br/>主のせいしつ,あらわし, いのち生かし出す。<br/>',NULL,50096,4);
INSERT INTO stanza VALUES('J306','4','わがために生きた主を, 　ひとに供給す;<br/>主のようにわれは生き, 主にしたがいゆく。<br/>',NULL,50097,5);
INSERT INTO stanza VALUES('J307','1','主よ,完成をしたいもとむ, 主がわがたましいに生きて,<br/>偶ぞうくだき,失ぱいのぞき, ゆきよりしろくあらえや。<br/>',NULL,50098,1);
INSERT INTO stanza VALUES('J307','chorus','ゆきよりもしーろく, ゆきよりしろくあらえや。<br/>',NULL,50099,2);
INSERT INTO stanza VALUES('J307','2','主よ,どんなつみものこさず, けがれを血でのぞきませ;<br/>すべて捨てさせ,聖を得させ, ゆきよりしろくあらえや。<br/>',NULL,50100,3);
INSERT INTO stanza VALUES('J307','3','主よ,御座よりあわれんで, わが身をささげさせよや;<br/>自己をまったく捨て去らせて, ゆきよりしろくあらえや。<br/>',NULL,50101,4);
INSERT INTO stanza VALUES('J307','4','主よ,へりくだりていのる, 十字架のもとでなお待つ;<br/>いま,この血にしんらいする, ゆきよりしろくあらえや。<br/>',NULL,50102,5);
INSERT INTO stanza VALUES('J307','5','主よ,われ待つとなれ見る, きよきこころをたまえや;<br/>もとむものを,なれこばまず, ゆきよりしろくあらえや。<br/>',NULL,50103,6);
INSERT INTO stanza VALUES('J308','1','世のさま見しわれ, 盲もくになせや;<br/>主のよろこび,臨在, 失せないために。<br/>',NULL,50104,1);
INSERT INTO stanza VALUES('J308','chorus','世のさま見しわれ, 盲もくになせや;<br/>主のよろこび,臨在 失せないために。<br/>',NULL,50105,2);
INSERT INTO stanza VALUES('J308','2','うつくしさ見るを かの日に延ばす;<br/>あわれみがあれば, 盲もくも満ぞく。<br/>',NULL,50106,3);
INSERT INTO stanza VALUES('J308','3','とげ取ることより, めぐみをのぞむ;<br/>まくのうちの栄光, われにかがやく。<br/>',NULL,50107,4);
INSERT INTO stanza VALUES('J308','4','暗こくで主の美を, 信こうにて見る;<br/>あざむきを受けた 主の御かお見る。<br/>',NULL,50108,5);
INSERT INTO stanza VALUES('J308','5','つき,たいよう超え, くも,ほし超えて,<br/>いばら受けしこうべ, 栄こうかがやく。<br/>',NULL,50109,6);
INSERT INTO stanza VALUES('J308','note','［この詩歌は，ある姉妹によって書かれた。彼女は生まれつき盲目であったが，別の姉妹が按手して祈った後，その目はいやされ，そしてこの詩歌を書いたのである。一節の「盲目になせや」は，彼女を按手した姉妹に対して言っている。］<br/>',NULL,50110,7);
INSERT INTO stanza VALUES('J309','1','主が啓示されて, わがにくを知る;<br/>めぐみのわざで, はいに伏させよ。<br/>勝利をもとめて, 無りょくに終わり,<br/>ぜんをねがうも, あくを脱し得ず。<br/>',NULL,50111,1);
INSERT INTO stanza VALUES('J309','2','かみをもとむも, にくむべき行為;<br/>変わり得ぬわれ, 何たるそくばく！<br/>かみの律ぽうは, つみ,あらわにし,<br/>肢たいの法そく, われ,とりこにす。<br/>',NULL,50112,2);
INSERT INTO stanza VALUES('J309','3','こころざし立て, またもつぶれる;<br/>勝利をもとめて, くだけ,たおれる。<br/>つみに売られて, われ,よわく無能,<br/>にくには善なく, 自己はくらやみ。<br/>',NULL,50113,3);
INSERT INTO stanza VALUES('J309','4','いま自己を知る, 無りょくで無のう,<br/>奇かいな個せい, 腐はいした自己;<br/>いつわる自己は, 信らいできない,<br/>すべてのぞみは, イェスわが王のみ。<br/>',NULL,50114,4);
INSERT INTO stanza VALUES('J309','5','十字架にて死に, 主により生きる；<br/>聖れいで満たし, みわざ成させよ。<br/>主の死,わが身で, みわざをふかめ,<br/>自己うしなわせ, われ,引き上げる。<br/>',NULL,50115,5);
INSERT INTO stanza VALUES('J309','6','わがにがきさま, 死のからだより，<br/>だれ解きはなち, 勝利得させるや？<br/>主は血をながし, われをせいとし,<br/>いのちを分与し, 主にふくさせる。<br/>',NULL,50116,6);
INSERT INTO stanza VALUES('J309','7','まったく聖とされ, かん全にふくす！<br/>御まえにすすみ, 主の御かお見る！<br/>何たるいのちよ, めぐみはおよぶ！<br/>主よ,感謝します, われを自由にす。<br/>',NULL,50117,7);
INSERT INTO stanza VALUES('J310','1','手腕にたけたヤコブのよう, われ負けたことがない;<br/>生死のさかいにいたるも, まだなお自己にたよる;<br/>負けたくないがゆえに, ちから尽くし,けいりゃくす。<br/>',NULL,50118,1);
INSERT INTO stanza VALUES('J310','2','エサウをおそれながらも, 自己はつよく,ごうじょう;<br/>わがさい後の日をおそれ, ちからのかぎり尽くす;<br/>主が来てかく闘すると, ひっ死にもがきつづける。<br/>',NULL,50119,2);
INSERT INTO stanza VALUES('J310','3','不思議！過去の経験もちい, かく闘すも,主たおれず;<br/>わがちから減しょうするが, かれに報ふくの意なし;<br/>われはあとにも引けず, だいたんにようきゅうする。<br/>',NULL,50120,3);
INSERT INTO stanza VALUES('J310','4','このかつてないあい手が, その名を告げられても,<br/>たたかうあい手,わからず, ただその偉だいさ知る;<br/>われ,しゅくふくをせまり, しゅくふくひたすらもとむ。<br/>',NULL,50121,4);
INSERT INTO stanza VALUES('J310','5','夜明けまでしょう負つかず, 主にしゅくふくをせまる;<br/>「なれは勝ち」と主に言わせ, イスラエルと呼ばれる;<br/>もものつがいがはずれ, われ,あしが不自由となる。<br/>',NULL,50122,5);
INSERT INTO stanza VALUES('J310','6','いま,照らされ,理かいした, 真のしょう利はなにかを;<br/>わがもものすじをはずし, かれのしょう利をしめす;<br/>かれはしるしをのこし, わがおろかさを警こくす。<br/>',NULL,50123,6);
INSERT INTO stanza VALUES('J310','7','瞬時ひかり,こころ満たし, 洪ずいのよう押しせまる,<br/>無限の栄光は礼はいさせ, 身をかくすようせまる;<br/>おかしたつみのおもさ, 無軌どうとけがれを知る。<br/>',NULL,50124,7);
INSERT INTO stanza VALUES('J310','8','あわれにも,かつておもう, 創造ぬし,かみに勝ったと！<br/>なんという無知なことよ！ なんというわざわいよ！<br/>わが手もて,主にそむき, 主よ,ゆずれ,と主にせまる。<br/>',NULL,50125,8);
INSERT INTO stanza VALUES('J310','9','主は何という栄光のかみ, 万軍の主,何というこう輝;<br/>主がだれか,ひとたび知り, いかなるかたか見れば,<br/>われさけび,なみだして, 悔いあらため,ひざまずく。<br/>',NULL,50126,9);
INSERT INTO stanza VALUES('J310','10','かみの御かおを見て,なお, かみに対抗し得ようか？<br/>されど,たいこうしたわれ, あなあれば,はいりたし;<br/>このわれがほろびずに, 消え去らないのはなぜか？<br/>',NULL,50127,10);
INSERT INTO stanza VALUES('J310','11','なにもわからずたかぶり, それゆえ盲もくになる;<br/>かみに勝ったとおもうと, おそろしさ禁じ得ない:<br/>われ全身無りょくになり, ふしぶし,はずれ,くずれる。<br/>',NULL,50128,11);
INSERT INTO stanza VALUES('J310','12','いまおもうに,わがしょう涯, 堕らくと腐はいに満つ:<br/>われはかみを犠せいにし, おろかにも満ぞくする;<br/>自己の要求を通すこと, しゅくーふくとおもい込む。<br/>',NULL,50129,12);
INSERT INTO stanza VALUES('J310','13','われはなんと自己ちゅう心, ねがいあればふくさせ,<br/>主ちょうあれば案ばいさせ, このみあれば譲歩さす;<br/>わがはたらきのために, かみをうごかそうとする！<br/>',NULL,50130,13);
INSERT INTO stanza VALUES('J310','14','世にこのようなひとあり, 傲慢,がん固,だますもの！<br/>主よ,われまことにヤコブ, 腐はい,こうかつさに満つ;<br/>ただあわれみをのぞむ, 主よ,われをたい処しませ。<br/>',NULL,50131,14);
INSERT INTO stanza VALUES('J310','15','あわれみはももにさわり, めぐみはしるしのこす;<br/>わすれると,もものつがい, われにおもい出させる;<br/>イスラエルとなるとも, ヤコブはあしが不自ゆう。<br/>',NULL,50132,15);
INSERT INTO stanza VALUES('J310','16','われ降ふくし,なれは勝つ, 主よ,勝利はなれのもの,<br/>なれ負けてくださったゆえ, われ負けることねがう;<br/>生がい,おそれおののき, 御むね成し,御名をあがむ。<br/>',NULL,50133,16);
INSERT INTO stanza VALUES('J311','1','主よ,われさぐり, 単いつにしたまえ;<br/>霊のなかまずしく, ただなれをもとむ。<br/>',NULL,50134,1);
INSERT INTO stanza VALUES('J311','2','高慢な自己より, きんせんよくより,<br/>虚えい,私よくより, はなれさせたまえ。<br/>',NULL,50135,2);
INSERT INTO stanza VALUES('J311','3','傲慢にするもの, すべてのぞきませ;<br/>なが意志にふくし, へりくだりて伏す。<br/>',NULL,50136,3);
INSERT INTO stanza VALUES('J311','4','おさな子とさせ, 知恵,ちから,のぞけ;<br/>主のひかりのなか, ちから受け,あゆむ。<br/>',NULL,50137,4);
INSERT INTO stanza VALUES('J311','5','主の愛のむねに, わがたましい,いこう;<br/>かみのへい安にて, 全存ざい満たせや。<br/>',NULL,50138,5);
INSERT INTO stanza VALUES('J311','6','日々,賛美満たし, われを生かしませ;<br/>死にいたるもなお, ながしゅつ現を待つ。<br/>',NULL,50139,6);
INSERT INTO stanza VALUES('J312','1','主はわがあんそく, まったく享受し;<br/>自己から解かれて, 主で満たせや。<br/>',NULL,50140,1);
INSERT INTO stanza VALUES('J312','2','ああ,こうかつな自己, もがき,あえぎ,<br/>主とわが霊を裂き, 安そくうばう。<br/>',NULL,50141,2);
INSERT INTO stanza VALUES('J312','3','「すべてひつよう」と, 自己はだます;<br/>「主にある安そくで 十ぶんか？」と言う。<br/>',NULL,50142,3);
INSERT INTO stanza VALUES('J312','4','安そくをもとめて, 自己,離だつす;<br/>王として支はいし, 管理したまえ。<br/>',NULL,50143,4);
INSERT INTO stanza VALUES('J312','5','主の手にいだかれ, 自己によらず,<br/>主のめぐみにより 生かしたまえ。<br/>',NULL,50144,5);
INSERT INTO stanza VALUES('J312','6','めぐみの主イェスよ, 自己をくだき,<br/>なれのみかたちを あらわさせよ。<br/>',NULL,50145,6);
INSERT INTO stanza VALUES('J313','1','欺まんに満ちた自己, 脱がせたまえ;<br/>聖のわざ成すのは, ただなれのみ。<br/>',NULL,50146,1);
INSERT INTO stanza VALUES('J313','chorus','自己,脱がせたまえ, 自己に善なし;<br/>くらやみのゆえに, たかぶるわれ,<br/>自己,脱がせたまえ, 御むねのため。<br/>',NULL,50147,2);
INSERT INTO stanza VALUES('J313','2','つみをのぞくよう, さけび,いのる！<br/>自ぶんを見るほど, 不満おぼえる!<br/>',NULL,50148,3);
INSERT INTO stanza VALUES('J313','3','この不安はなにか， ばく露しませ；<br/>良しんのうったえは， 何のつみゆえ？<br/>',NULL,50149,4);
INSERT INTO stanza VALUES('J313','4','主とのへだてあり, 交流,断たれる;<br/>このへだてなにか, 問だいなにか？<br/>',NULL,50150,5);
INSERT INTO stanza VALUES('J314','1','ひそかなてきあり, おそろしいもの,<br/>つみよりも狡かつ, 魅りょくもある。<br/>それはつよい自己, わがままな自己;<br/>自己が死ねば,主は, わがうち生く。<br/>',NULL,50151,1);
INSERT INTO stanza VALUES('J314','2','つよく,ちからある, 天然のひとは,<br/>自しん,自慢,自己愛, 自我に満ちる。<br/>自己を拒ぜつして, 死にわたすとき,<br/>霊のカナンにすすみ, 主をきょう受す。<br/>',NULL,50152,2);
INSERT INTO stanza VALUES('J314','3','御座うばう自己を, はなれさせよ！<br/>ながうちに「われ」が なくなるまで。<br/>自しん,自己満ぞく, はなれさせよや;<br/>なれをちからとし, 住まいとする。<br/>',NULL,50153,3);
INSERT INTO stanza VALUES('J314','4','自己ついきゅうより すくいたまえ;<br/>われをさいだんに ささげさせよ。<br/>傲まん,ほこりより, 主よ,すくいませ,<br/>主をほこりとして, たかく上げる。<br/>',NULL,50154,4);
INSERT INTO stanza VALUES('J314','5','猛れつないき吹き, 自己ほろぼせ;<br/>もはや立てぬまで, 自己ほろぼせ。<br/>栄こう満ちるとき, だれも立ち得ぬ;<br/>栄こうわれに満ち, 自己死なせよ。<br/>',NULL,50155,5);
INSERT INTO stanza VALUES('J315','1','くちびるとおもいは, けがれ,失ぱいのみ;<br/>のぞみすべて失せても, なおめぐみたもうや？<br/>',NULL,50156,1);
INSERT INTO stanza VALUES('J315','2','聖のなかに行為あり, 謙遜も自己による;<br/>悔いあらためのなみだも, 血のあらいひつ要。<br/>',NULL,50157,2);
INSERT INTO stanza VALUES('J315','3','善のなかに自己あり, 自己捨て,なお不純,<br/>わがこころはわがてき, なおのぞみありや？<br/>',NULL,50158,3);
INSERT INTO stanza VALUES('J315','4','奉仕に自己意思あり, 愛にはこのみあり;<br/>うごくも,しずかにすも, 自己そこにひそむ。<br/>',NULL,50159,4);
INSERT INTO stanza VALUES('J315','5','自己に満つきゅう創造, われ,離だつしたい;<br/>主よ,なれのえいこうが こころに満ちませ。<br/>',NULL,50160,5);
INSERT INTO stanza VALUES('J315','6','主よ,あえていのれず, 主を見つめるのみ;<br/>ながことばをつかわし, 栄こう啓示しませ。<br/>',NULL,50161,6);
INSERT INTO stanza VALUES('J316','1','われはめぐみを受け, あたえるものとなる;<br/>自ぶんを知りつつも, 分を越えてしまう！<br/>かみのまえに生きて, ひそかに自己をほこる。<br/>',NULL,50162,1);
INSERT INTO stanza VALUES('J316','2','ひとの耐え得ぬ苦難, わが人せいに満ちる;<br/>ひと知れぬくるしみ, われつよく耐える;<br/>自己捨てたと言いつつ, 自分の経験わすれ得ず！<br/>',NULL,50163,2);
INSERT INTO stanza VALUES('J316','3','われめぐみに満ちて, 他にまさるとおもう！<br/>われのうちとそとで, 主のみわざ見いだす！<br/>わがうえでのみわざ, 何とすばらしいか！とおもう。<br/>',NULL,50164,3);
INSERT INTO stanza VALUES('J316','4','自分のすばらしさを, われはみな知っている;<br/>知らぬうち,たかぶり, 自己ちゅう心となる;<br/>わが手のマナすでに くさり,無駄になっている。<br/>',NULL,50165,4);
INSERT INTO stanza VALUES('J316','5','ともが来てなぐさめ, どうじょうをしめせば,<br/>たかぶりがあらわれ, 忍たいはなくなる;<br/>失敗し,自分をのろい, 真の状たいあらわれる。<br/>',NULL,50166,5);
INSERT INTO stanza VALUES('J316','6','つたえ聞いたことを, かたることできるも,<br/>堕らくした自ぶんは, いまだへん化なし;<br/>たまものにてほこり, めぐみで自己たかくす。<br/>',NULL,50167,6);
INSERT INTO stanza VALUES('J316','7','されど,いまなれ見る, なが聖にばく露され,<br/>ひかり,栄光のもとで, 照らされて,悔いる,<br/>いかに自己に満ちて, けがれたものか悔いる。<br/>',NULL,50168,7);
INSERT INTO stanza VALUES('J316','8','何という恥ずべきこと, めぐみで自己かざり,<br/>はたらきを利ようし, 自己たかく上げる;<br/>わが動機はいやしく, 勝利さえ恥ずべきもの。<br/>',NULL,50169,8);
INSERT INTO stanza VALUES('J316','9','けがれをきよいとし, にくさえも良しとす;<br/>何というはじ,もうもく！ 何とおろかなわれ！<br/>無知で自己を義とし, 主のえいこうもぬすむ。<br/>',NULL,50170,9);
INSERT INTO stanza VALUES('J316','10','わが腐敗,主は知るも, われは知らずにきた,<br/>自己をたよることは, 何と恥ずべきこと;<br/>われをすくいたまえ, なわ目より解きたまえ。<br/>',NULL,50171,10);
INSERT INTO stanza VALUES('J316','11','主よ,われのねがいは, ちりのなかに伏して,<br/>わが身にはい,かぶり, 堕らく悔いること;<br/>われに尽きないはじ, 腐はいしたこころあり。<br/>',NULL,50172,11);
INSERT INTO stanza VALUES('J316','12','わがことば,不正かく, いのちは何とあさく,<br/>こころはけがれ満ち, われにぜんはなし;<br/>われは自己をにくむ, わがのぞみ,主にぞある。<br/>',NULL,50173,12);
INSERT INTO stanza VALUES('J317','1','われを打つかぜから, のがれるいのりから,<br/>代価おそることから, 前進しない虚偽から,<br/>あまえるおのれから, 主よ,われを解放しませ。<br/>',NULL,50174,1);
INSERT INTO stanza VALUES('J317','2','安易えらぶこのみと, おびやかす態度から,<br/>(これは霊つよめない, 十字架ふくまない),<br/>十字架,覆うものから, 主よ,われをすくいませ。<br/>',NULL,50175,2);
INSERT INTO stanza VALUES('J317','3','愛するこころ,信こう, のぞみ,情ねつあたえ,<br/>うみにしずませずに, わしのよう,のぼらせ,<br/>だい胆に前しんさせ, われを燃やしたまえや。<br/>',NULL,50176,3);
INSERT INTO stanza VALUES('J318','1','十字架の主を, 信仰もて見る,<br/>わが主よ！<br/>すくいぬしに 完全にぞくす,<br/>われ,いまより, 主のもの。<br/>',NULL,50177,1);
INSERT INTO stanza VALUES('J318','2','主よ,めぐみで, うちをつよめ,<br/>燃やせや！<br/>血ながした主, ふかくあいす,<br/>真剣,純しんに, 主を愛す。<br/>',NULL,50178,2);
INSERT INTO stanza VALUES('J318','3','われ,なやみと 苦難に遭うも,<br/>みちびけ！<br/>なみだぬぐい, われ,まもれや;<br/>ながみち行き, したがう。<br/>',NULL,50179,3);
INSERT INTO stanza VALUES('J318','4','人生ゆめのよう, 死のあらしが,<br/>おそうも,<br/>めぐみあたえ, おそれのぞき,<br/>のぞみ,へい安, 満たせや。<br/>',NULL,50180,4);
INSERT INTO stanza VALUES('J319','1','われは無りょくで, たんどくでは立てず;<br/>主に依りたのみ, みなしゅくふくとなる。<br/>',NULL,50181,1);
INSERT INTO stanza VALUES('J319','chorus','日ごと,まい時, めぐみをもとむ,<br/>主よ,ご自しんを, さらにけい示しませ。<br/>',NULL,50182,2);
INSERT INTO stanza VALUES('J319','2','わがみち,孤どく, つかれて,うたもなし;<br/>みち知らぬわれ, 主よ,みちびきたまえ。<br/>',NULL,50183,3);
INSERT INTO stanza VALUES('J319','3','感かくが変わり, すべてに価値,失せる;<br/>目が見えぬとき, わが主はいとちかし。<br/>',NULL,50184,4);
INSERT INTO stanza VALUES('J319','4','主のかえりみと， 秘みつのりんざいで,<br/>われはよろこび, 孤どくを耐えしのぶ。<br/>',NULL,50185,5);
INSERT INTO stanza VALUES('J319','5','つき日,過ぎ去り, 死のかわわたるとき,<br/>よわさをおぼえ, 主よ,めぐみをしたう。<br/>',NULL,50186,6);
INSERT INTO stanza VALUES('J320','1','おお,かみよ,しゅくふくのない, 安そくのない枯れた木,<br/>無用の障害ぶつであると, 主はわれをばく露した。<br/>されど「主よ,われを捨てず, 御手でわれを取り上げませ。<br/>',NULL,50187,1);
INSERT INTO stanza VALUES('J320','2','おんなたちがあさを取り, ろうざい工人がろうを取り,<br/>鍛冶屋があらがねを取り, よう具つくり上げるよう;<br/>じゅく練した主の手により, あいもてわれを取りたまえ」｡<br/>',NULL,50188,2);
INSERT INTO stanza VALUES('J320','3','くだかれない意志のため, 金の性しつあらわれず;<br/>ちょうこくできぬいわのよう, 天然は無用のはいぶつ;<br/>主よ,もとむ:「われを捨てず, 御手のうちでくだきたまえ。<br/>',NULL,50189,3);
INSERT INTO stanza VALUES('J320','4','ばくやくは岩せきくだき, つちはせきざいくだく,<br/>ひきうすはむぎをくだき, くるみくだき食べるよう,<br/>主よ,どうか,せいなる手で, われ見捨てず,くだきたまえ」｡<br/>',NULL,50190,4);
INSERT INTO stanza VALUES('J320','5','くだかれたのちにもなお, 炉のけい過はひつよう;<br/>くだかれ,さらに調理され, ひとに供きゅうするため,<br/>主よ,もとむ:「われを捨てず, はたらきのため成就しませ。<br/>',NULL,50191,5);
INSERT INTO stanza VALUES('J320','6','金かいが鋳がたにはいり, 有ようなかたちとなる;<br/>むぎ粉こねて,みずと火で, 調理すれば食べられる;<br/>火によりわれを成就して, なが愛でとわにたもちませ」｡<br/>',NULL,50192,6);
INSERT INTO stanza VALUES('J321','1','かみのあい！何とひろく, ながく,たかく,ふかい！<br/>なれのかがやきを見て, 主よ,安そくをもとむ;<br/>なれのなかにのみ, 真の安そく見いだす。<br/>',NULL,50193,1);
INSERT INTO stanza VALUES('J321','2','ほそきこえ,われを召す, あまきくびき負え,と;<br/>おうじるこころあれど, 前途の障がいおそれ,<br/>主に向こうとするが, なれに背を向ける。<br/>',NULL,50194,2);
INSERT INTO stanza VALUES('J321','3','めぐみは,われ,引き寄せ, 安そくもとめさせる;<br/>なれを追いもとめても, ちかづくことできず;<br/>まよわず主に向き, あゆむ日はいつか？<br/>',NULL,50195,3);
INSERT INTO stanza VALUES('J321','4','主より引きはなすもの, われより取り去れや;<br/>主ときそうものがなく, 主が王となるように;<br/>わがこころ解かれ, 主にて安そく得る。<br/>',NULL,50196,4);
INSERT INTO stanza VALUES('J321','5','主よ,われをまいそうし, わがうちに生きませ！<br/>ひそかな邪あく,よくを, くぎづけ,とどめぬよう;<br/>主のほかなににも, のぞみ置かぬように！<br/>',NULL,50197,5);
INSERT INTO stanza VALUES('J321','6','最じょうのたすけあたえ, おもいわずらい解き,<br/>自己の意思を追い出し, やみをはなれさせよ;<br/>いのちにふくさせ, つねに感謝させよ。<br/>',NULL,50198,6);
INSERT INTO stanza VALUES('J321','7','絶えず地をはなれさせ, 主の命令を聞かせよ;<br/>「われはながあい,いのち, 主である」となれは言う;<br/>みこえ聞き,愛,知り, なれに安そくする。<br/>',NULL,50199,7);
INSERT INTO stanza VALUES('J322','1','自己,しばれや, 自由得るため;<br/>わが武装,放棄させよ, 勝利得るため;<br/>自己によれば, 失敗するのみ;<br/>主,われをしばれば, ちからを得る。<br/>',NULL,50200,1);
INSERT INTO stanza VALUES('J322','2','主になければ, われはよわく,<br/>ねがってもおこなえず, ただようのみ;<br/>主につながり, 自由にされて,<br/>主の奴れいとなり, ちからを得る。<br/>',NULL,50201,2);
INSERT INTO stanza VALUES('J322','3','死ななければ, 生涯うしない,<br/>敗ぼくしちからなく, にくをなげく。<br/>もし死ぬなら, 主により生き,<br/>自己よりはなれて, 完全に主,得る。<br/>',NULL,50202,3);
INSERT INTO stanza VALUES('J322','4','いま主を知り, 自己をも知る,<br/>天然の能りょくもはや, われ,たよらず。<br/>永遠のれいで, くぎづけられ,<br/>われはげんしょうし, 主がぞう加す。<br/>',NULL,50203,4);
INSERT INTO stanza VALUES('J323','1','主よ,照らしませ, ひかりをもとむ,<br/>こころのなかを 照らしたまえ。<br/>',NULL,50204,1);
INSERT INTO stanza VALUES('J323','2','すべてばく露し, 自己をのぞけや,<br/>ひかり来たりて, 照らしたまえ。<br/>',NULL,50205,2);
INSERT INTO stanza VALUES('J323','3','サタンがだまし, 事じつが見えず,<br/>ながひかりもて, われを照らせ！<br/>',NULL,50206,3);
INSERT INTO stanza VALUES('J323','4','われを照らして, 自己を知らせよ,<br/>ひかりなる主よ, よわさ見せよ！<br/>',NULL,50207,4);
INSERT INTO stanza VALUES('J323','5','こころ主に向け, 自由にされたし,<br/>なが意志,知らせ, われを照らせ！<br/>',NULL,50208,5);
INSERT INTO stanza VALUES('J323','6','ひかりのなかで, あゆませたまえ,<br/>なれの臨ざいを うしなわぬよう。<br/>',NULL,50209,6);
INSERT INTO stanza VALUES('J324','1','おおい取りさり, ひかり見させ,<br/>あざむかれず, じつじょう知る。<br/>',NULL,50210,1);
INSERT INTO stanza VALUES('J324','chorus','主,真のひかりよ, このひかりで,<br/>いまわがすべて, 照らしたまえ。<br/>',NULL,50211,2);
INSERT INTO stanza VALUES('J324','2','自己にたいし, 認しきに欠け,<br/>高慢になって, 自己満ぞくす。<br/>',NULL,50212,3);
INSERT INTO stanza VALUES('J324','3','なれにたいし, 認しきに欠け,<br/>教理は知るも, 啓示に欠ける。<br/>',NULL,50213,4);
INSERT INTO stanza VALUES('J324','4','ながいのちの 認しきに欠け,<br/>にくか,れいか, さだかならず。<br/>',NULL,50214,5);
INSERT INTO stanza VALUES('J324','5','なれのみちの 認しきに欠け,<br/>単どくになり, みちをはずす。<br/>',NULL,50215,6);
INSERT INTO stanza VALUES('J324','6','なが御むねの 認しきに欠け,<br/>自己の意志を かたくとおす。<br/>',NULL,50216,7);
INSERT INTO stanza VALUES('J324','7','召会について, 啓示がひつ要;<br/>なにをなすか, 知恵あたえや。<br/>',NULL,50217,8);
INSERT INTO stanza VALUES('J324','8','おおい取りさり, すべて照らし,<br/>あざむかれず, さらに見せよ。<br/>',NULL,50218,9);
INSERT INTO stanza VALUES('J325','1','自分のおもいでは， つよいとおもうが，<br/>ちからないことを， われ，知らず。<br/>',NULL,50219,1);
INSERT INTO stanza VALUES('J325','2','この世にあるとき， 欠け目をおぼえず，<br/>自ぶんの努りょくを ほこっていた。<br/>',NULL,50220,2);
INSERT INTO stanza VALUES('J325','3','自己のあさはかさ， やみのゆえ知らず；<br/>過だいひょう価して， 自己ほこる。<br/>',NULL,50221,3);
INSERT INTO stanza VALUES('J325','4','主のまえに出れば， ひかり刺しとおし，<br/>見えなかったものを ばく露する。<br/>',NULL,50222,4);
INSERT INTO stanza VALUES('J325','5','御まえに畏しゅくし， おごりは消え去る；<br/>すべてばく露され， よわさ知る。<br/>',NULL,50223,5);
INSERT INTO stanza VALUES('J325','6','おごるべきものや たよるものはない;<br/>恥じて悔いるのみ, 　いのれない！<br/>',NULL,50224,6);
INSERT INTO stanza VALUES('J325','7','主の血といのちで ほろびまぬかれた;<br/>されど自己けがれ, 　恥じるのみ。<br/>',NULL,50225,7);
INSERT INTO stanza VALUES('J325','8','あらゆるたかぶり, 自己へのしんらい,<br/>こころにくらやみ 　あるがゆえ。<br/>',NULL,50226,8);
INSERT INTO stanza VALUES('J325','9','うごくも止まるも, かたるもだまるも,<br/>すべてはしっぱい, 　よわさのみ。<br/>',NULL,50227,9);
INSERT INTO stanza VALUES('J325','10','いのろうとしても, 信頼しようとしても,<br/>われに信こうなし, 　あわれみを！<br/>',NULL,50228,10);
INSERT INTO stanza VALUES('J326','1','主よ,照らしませ,アｰメン！ つみ,ばく露して,ハレルヤ！<br/>血もてあらいませ, われきよめませ,アｰメン！<br/>',NULL,50229,1);
INSERT INTO stanza VALUES('J326','2','主よ,かい放せよ,アｰメン！ きずな断ち切り,ハレルヤ！<br/>あく魔ほろぼして, 自ゆうにしませ,アｰメン！<br/>',NULL,50230,2);
INSERT INTO stanza VALUES('J326','3','主よ,ふっ興せよ,アｰメン！ よわさをのぞき,ハレルヤ！<br/>愛の火を燃やして, 主に生きさせよ,アｰメン！<br/>',NULL,50231,3);
INSERT INTO stanza VALUES('J327','1','わが霊きよめよ, わが霊きよめよ,<br/>けがれをのぞき, 　きよめませ;<br/>けがれをのぞいて, 　きよめませ。<br/>',NULL,50232,1);
INSERT INTO stanza VALUES('J327','2','うつわをからに, うつわをからに,<br/>つみ,こくはくし, 　からにする;<br/>つみ,こくはくして, 　からにする。<br/>',NULL,50233,2);
INSERT INTO stanza VALUES('J327','3','わが霊,満たせや, わが霊,満たせや,<br/>わが霊,満たして, 　復興しませ;<br/>わが霊を満たして, 　復興しませ。<br/>',NULL,50234,3);
INSERT INTO stanza VALUES('J328','1','主よ,わが目ひらき, 御かお見せたまえ;<br/>栄こうのかがやきで, くらやみ消し去れ。<br/>めぐみの主よ,われ, なが御かお,もとむ;<br/>主よ,わが目ひらき, 　　見せませ！<br/>',NULL,50235,1);
INSERT INTO stanza VALUES('J328','2','主よ,みみをひらき, みこえを聞かせよ;<br/>みこえ,われにひびき, いつわり,消し去れ。<br/>めぐみの主よ,われ, ながみこえ,もとむ;<br/>主よ,みみをひらき, 　　聞かせよ！<br/>',NULL,50236,2);
INSERT INTO stanza VALUES('J328','3','主よ,こころひらき, ご自身で満たせや;<br/>なれがうちにあふれ, われ,うしなわせよ。<br/>めぐみの主よ,われ, ながめぐみ,もとむ;<br/>主よ,こころひらき, 　　満たせや！<br/>',NULL,50237,3);
INSERT INTO stanza VALUES('J329','1','あるひと,主をはなれ, 　むれの保護をはなれ,<br/>こころは世をあいす, 　主よ,わたしでしょうか？<br/>',NULL,50238,1);
INSERT INTO stanza VALUES('J329','chorus','このことばはこころに, なんとふかく刺さるか！<br/>主の分をうしなうのは, 主よ,わたしでしょうか？<br/>',NULL,50239,2);
INSERT INTO stanza VALUES('J329','2','あるひと,主を捨てて, あくにんにしたがい,<br/>聖霊をかなしませる, 主よ,わたしでしょうか？<br/>',NULL,50240,3);
INSERT INTO stanza VALUES('J329','3','あるひと,主にそむき, マモンにつかえている,<br/>つみのなかにしずむ, 主よ,わたしでしょうか？<br/>',NULL,50241,4);
INSERT INTO stanza VALUES('J329','4','あるひと,主をいなみ, かれをはずかしめた,<br/>そむいてともを売る, 主よ,わたしでしょうか？<br/>',NULL,50242,5);
INSERT INTO stanza VALUES('J329','5','あるひと,上げられて, 安そく享受している,<br/>いのちのかんむり受く, 主よ,わたしでしょうか？<br/>',NULL,50243,6);
INSERT INTO stanza VALUES('J330','1','主のあいはながく, ひろく,たかく,ふかい;<br/>われのようなつみびとが, めぐみを受けるとは？<br/>',NULL,50244,1);
INSERT INTO stanza VALUES('J330','2','主,おもいだい価で われを買いもどした;<br/>われねがう,じゅう字架負い, なれにしたがうこと。<br/>',NULL,50245,2);
INSERT INTO stanza VALUES('J330','3','キリスト得るため, いま,すべて捨て去る;<br/>生も死も何であろうとも, 振りかえらずすすむ。<br/>',NULL,50246,3);
INSERT INTO stanza VALUES('J330','4','親友,さいわい,めい誉, なんのようがあるか？<br/>主がまずしくなったゆえ, われもまずしくなる。<br/>',NULL,50247,4);
INSERT INTO stanza VALUES('J330','5','すくいぬしあいし, 主の「称さん」もとめる;<br/>世のたのしみは苦となり, 利えきはそんとなる！<br/>',NULL,50248,5);
INSERT INTO stanza VALUES('J330','6','めぐみの主イェスよ, なれはわがなぐさめ！<br/>天に主以外持つことなし, 地にしたうものなし。<br/>',NULL,50249,6);
INSERT INTO stanza VALUES('J330','7','患難,苦なん,はん対, われは意に介さない。<br/>わがれい,たましい,からだ, 主の愛でかこみませ。<br/>',NULL,50250,7);
INSERT INTO stanza VALUES('J330','8','主よ！めぐみたまい, 小さきわれみちびき,<br/>ともにいて,ちからあたえ, くらき世,過ごさせよ。<br/>',NULL,50251,8);
INSERT INTO stanza VALUES('J330','9','サタン,この世,にくは, ゆうわくし,あざむく;<br/>ながちからなければ,われ, 主の名,はずかしめる！<br/>',NULL,50252,9);
INSERT INTO stanza VALUES('J330','10','いま,ときはせまる, 世ぞくからのがれる;<br/>主のさい来のときうたう, ハーレルーヤ！アーメン！<br/>',NULL,50253,10);
INSERT INTO stanza VALUES('J331','1','「ながため血ながし, いのち捨てた,<br/>なれあらいきよめ, 死より生かした。<br/>ながため,ながために, いのちを捨てた,<br/>われのためになれは, なにを捨てたか？<br/>',NULL,50254,1);
INSERT INTO stanza VALUES('J331','2','ながためろう苦し 苦難を受けた,<br/>とわのよろこびと 安そくあたえた。<br/>ながためにおおくの としをかけたが,<br/>われのためになれは, いく日かけたか？<br/>',NULL,50255,2);
INSERT INTO stanza VALUES('J331','3','われはえいこうの 御座を捨てた,<br/>ながため苦難の地, あるきつづけた。<br/>ながため,ながために, すべて捨てたが,<br/>われのためになれは, なにを捨てたか？<br/>',NULL,50256,3);
INSERT INTO stanza VALUES('J331','4','ながための苦なん, 言い尽くせず,<br/>大きないたみ受け, よみよりすくう。<br/>ながため,ながために, 苦なんを受けた,<br/>われのためになれは, なにを負うのか？<br/>',NULL,50257,4);
INSERT INTO stanza VALUES('J331','5','無だい価のすくい, ゆるし,慈あい,<br/>てんより,ながため, われはもたらす。<br/>ながため,ながために, 多くもたらした,<br/>われのためになれは, なにあたえるか？」<br/>',NULL,50258,5);
INSERT INTO stanza VALUES('J331','6','「主よ,わがいのちを なれにささげ,<br/>地のきずなを断ち, なれにしたがう。<br/>われのためになれは, すべてを捨てた,<br/>ながため,ながために, すべてを捨てる！」<br/>',NULL,50259,6);
INSERT INTO stanza VALUES('J332','1','われをはなさぬ愛よ, 　なれにあんそくする;<br/>大うみのような主に， 　 全生がいをささげ,<br/>ゆたかを得る。<br/>',NULL,50260,1);
INSERT INTO stanza VALUES('J332','2','われ照らすひかりよ, 　わがともし火ささぐ;<br/>なれを得てかがやき, 　 主のたいようのよう,<br/>ひかり満ちる。<br/>',NULL,50261,2);
INSERT INTO stanza VALUES('J332','3','おお,われのよろこびよ,　こころ,なれにひらく;<br/>やくそくのたしかさ, にじを見て知った,<br/>なみだもなし。<br/>',NULL,50262,3);
INSERT INTO stanza VALUES('J332','4','見上げるじゅう字架よ, われは主をはなれず,<br/>虚栄,地にほうむれば, いのちのはな咲き,<br/>とわにいたる。<br/>',NULL,50263,4);
INSERT INTO stanza VALUES('J333','1','わがれいは主を見た, こころをうばわれた;<br/>なれはだいいちのひと, さいこうのしゅくふく。<br/>',NULL,50264,1);
INSERT INTO stanza VALUES('J333','chorus','なれは千万のあいだで だいいちのひととなる;<br/>なれを見せ,捕らえませ, 偶像くだき,栄光を主に！<br/>',NULL,50265,2);
INSERT INTO stanza VALUES('J333','2','虚えい,世のたからは, ぐう像で,ひとだます;<br/>めっきも,みつのあじも, わがこころ捕らえる。<br/>',NULL,50266,3);
INSERT INTO stanza VALUES('J333','3','ぐう像のあじわいを, うしなわせるものは,<br/>すすめ,はげましでなく, しんのたからによる。<br/>',NULL,50267,4);
INSERT INTO stanza VALUES('J333','4','ぐう像をくだくのは, めい令,おしえでなく,<br/>えい光のうるわしさと, ながれ出る愛による。<br/>',NULL,50268,5);
INSERT INTO stanza VALUES('J333','5','あさ日がのぞむなら, ともし火は消される;<br/>なつのかぜが吹くなら, ふゆ着はしまわれる。<br/>',NULL,50269,6);
INSERT INTO stanza VALUES('J333','6','ペテロの見たなみだ, ステパノの見た御子;<br/>マリアと泣かれた主が, 地からはなれさせる。<br/>',NULL,50270,7);
INSERT INTO stanza VALUES('J333','7','われさらに引き寄せ, こころ,なれで満たせ！<br/>あがなわれたなが伴侶, もはやぐうぞうなし。<br/>',NULL,50271,8);
INSERT INTO stanza VALUES('J334','1','聖べつされよ, 霊なる主へ！<br/>代価,惜しまず, 豊富もとむ;<br/>ともづな断ち, ふかみへと,<br/>しゅくふく大能, 得るために。<br/>',NULL,50272,1);
INSERT INTO stanza VALUES('J334','chorus','聖べつされよ, 万有の主へ！<br/>召しにこたえ, 豊富もとむ。<br/>',NULL,50273,2);
INSERT INTO stanza VALUES('J334','2','聖べつされよ, 霊なる主へ！<br/>自己ほうむられ, きよめ得よ！<br/>このうつわが からにされ,<br/>主に満たされ, 主をながす。<br/>',NULL,50274,3);
INSERT INTO stanza VALUES('J334','3','聖べつされよ, 御むねへと！<br/>主のみち行き, 主にたよる;<br/>きょうらく捨て, ぜん進する;<br/>みちびき待ち みこえ聞く。<br/>',NULL,50275,4);
INSERT INTO stanza VALUES('J334','4','聖べつされよ, 永えんまで！<br/>わが意でなく, 主の御むね;<br/>自分の計かく, 明けわたし,<br/>なにもないが, 万ゆう持つ。<br/>',NULL,50276,5);
INSERT INTO stanza VALUES('J334','5','聖べつされよ！ 何とあまし,<br/>主の愛の捕虜, 何と自ゆう;<br/>つみ,うたがい, おそれ去り,<br/>おも荷,うれい, 心ぱいなし。<br/>',NULL,50277,6);
INSERT INTO stanza VALUES('J334','6','聖べつされよ！ 何と安そく,<br/>御まえに待ち, 照らされる;<br/>主のせい霊で 満たされて,<br/>わがうち,みな きよめらる。<br/>',NULL,50278,7);
INSERT INTO stanza VALUES('J334','7','霊に満たされ, 臨ざい得る！<br/>しゅくふく受け, あいされる！<br/>とわにひかり, かがやいて,<br/>せいべつされ, 主に生きる。<br/>',NULL,50279,8);
INSERT INTO stanza VALUES('J335','1','この世,かいらくに, われ,背を向けて,<br/>すばらしいたからに こころを向ける;<br/>天を見えなくする 虚栄すでになし;<br/>分離のさかい超え, この世を捨てた。<br/>',NULL,50280,1);
INSERT INTO stanza VALUES('J335','chorus','遠く捨てた, 　遠く捨てた,<br/>分離のさかい超え, この世を捨てた。<br/>',NULL,50281,2);
INSERT INTO stanza VALUES('J335','2','つみの生かつ捨て, この世はなれる;<br/>主のみちびき受け, 主のこえを聞く;<br/>死をのがれたゆえ, 主,かしらとする;<br/>主のためみな捨て, この世を捨てた。<br/>',NULL,50282,3);
INSERT INTO stanza VALUES('J335','chorus','遠く捨てた, 　遠く捨てた,<br/>主のためみな捨て, この世を捨てた。<br/>',NULL,50283,4);
INSERT INTO stanza VALUES('J335','3','二度ともどらない, あのみじめさに;<br/>ここだけに安そく, へいあんがある;<br/>主人は代わり,いま, かみにつかえる;<br/>地のそくばく脱ぎ, この世を捨てた。<br/>',NULL,50284,5);
INSERT INTO stanza VALUES('J335','chorus','遠く捨てた, 　遠く捨てた,<br/>地のそくばく脱ぎ, この世を捨てた。<br/>',NULL,50285,6);
INSERT INTO stanza VALUES('J335','4','前途さだめられた, 主のほかいらず;<br/>主のめぐみのほか, われはもとめず;<br/>主にかたく立って, うしろを向かず;<br/>過去すべてを捨て, この世を捨てた。<br/>',NULL,50286,7);
INSERT INTO stanza VALUES('J335','chorus','遠く捨てた, 　遠く捨てた,<br/>過去すべてを捨て， この世を捨てた。<br/>',NULL,50287,8);
INSERT INTO stanza VALUES('J336','1','よろこばしい聖べつ！ これぞ真のしゅくふく;<br/>すべてからはなれて, ただ主を愛し,したう,<br/>キリストに安そくする, キリストに安そくする。<br/>',NULL,50288,1);
INSERT INTO stanza VALUES('J336','2','主は召して聖べつし, 主のみちを行かせる;<br/>ご自身のせいかつは, そのせつ明,れいしょう,<br/>主にしたがうものだれか？ 主にしたがうものだれか？<br/>',NULL,50289,2);
INSERT INTO stanza VALUES('J336','3','営所を出て主に行き, 完ぜんになれに帰す,<br/>よろこびこうふくし, 主のそしりをになう,<br/>わがすべて,なれのもの, わがすべて,なれのもの。<br/>',NULL,50290,3);
INSERT INTO stanza VALUES('J336','4','主をなやますことと, この世からはなれる;<br/>されど,なれのように, つみびとかえりみる,<br/>なが愛のあゆみたどる, なが愛のあゆみたどる。<br/>',NULL,50291,4);
INSERT INTO stanza VALUES('J336','5','主とのへだてのぞき, さらにちかづかせよ;<br/>完全になれに帰する, まったくなれにささぐ,<br/>完全に永遠に主に帰す！ 完全に永遠に主に帰す！<br/>',NULL,50292,5);
INSERT INTO stanza VALUES('J337','1','すべてキリストに よろこびささぐ;<br/>とわに主をあいし, なれにしたがう。<br/>',NULL,50293,1);
INSERT INTO stanza VALUES('J337','chorus','すべて主に, ささげます！<br/>わがめぐみの主よ, ささげます！<br/>',NULL,50294,2);
INSERT INTO stanza VALUES('J337','2','すべて主にささぐ, 御まえに伏して;<br/>世のさちを捨てて, 主に明けわたす。<br/>',NULL,50295,3);
INSERT INTO stanza VALUES('J337','3','すべて主にささぐ, われを受けませ;<br/>われは主のものと, 聖れいあかしす。<br/>',NULL,50296,4);
INSERT INTO stanza VALUES('J337','4','すべて主にささぐ， ながうつわとし;<br/>めぐみに満たされ, 主を生かし出す。<br/>',NULL,50297,5);
INSERT INTO stanza VALUES('J337','5','すべて主にささぐ, 火で焼き尽くせ；<br/>ああ,このあまさ,豊富, 栄こう主にあれ。<br/>',NULL,50298,6);
INSERT INTO stanza VALUES('J338','1','キリストにすべて 帰するはとう然,<br/>とうとき血により 買われたゆえに;<br/>受くべきけん利は 主のうえにある,<br/>',NULL,50299,1);
INSERT INTO stanza VALUES('J338','chorus','すべてを主に帰す！ すべて,主に帰す！<br/>',NULL,50300,2);
INSERT INTO stanza VALUES('J338','2','こころしたう主に, すべてささげる;<br/>主のあいうちにて われをはげまし,<br/>われをうながして, 押しせまるゆえ,<br/>',NULL,50301,3);
INSERT INTO stanza VALUES('J338','3','聖となしたもう主に, すべてささげる;<br/>からだ,れい,たましい, とみも,時かんも,<br/>わが持てるものも, なしうることも,<br/>',NULL,50302,4);
INSERT INTO stanza VALUES('J338','4','主よ,もちいたまえ, われのもろ手を,<br/>したがわせたまえ, もろあしをもて;<br/>目をもてあおがせ, くちもて主ほむ,<br/>',NULL,50303,5);
INSERT INTO stanza VALUES('J338','5','わが目キリストに そそがれるとき,<br/>すべてのものごと, いろあせている;<br/>十字架をしたいて, 主のくびき負い,<br/>',NULL,50304,6);
INSERT INTO stanza VALUES('J338','6','不思議なめぐみの ふかさ,ひろさよ！<br/>栄こうの主,王の王, わがくちのうた;<br/>われさえこよなき たからと見たもう;<br/>',NULL,50305,7);
INSERT INTO stanza VALUES('J339','1','主よ,わがしょう涯, なれにささげる;<br/>わがときを得て, 主よ,もちいませ。<br/>',NULL,50306,1);
INSERT INTO stanza VALUES('J339','chorus','わがためじゅう字架で, なれは苦難を受ける;<br/>ながため愛,いのちささげ, 　永遠につかえる。<br/>',NULL,50307,2);
INSERT INTO stanza VALUES('J339','2','わが手あし得て, みちをあゆませ,<br/>くち,したを得て, 主をかたらせよ。<br/>',NULL,50308,3);
INSERT INTO stanza VALUES('J339','3','わが金ぎん得て, つかい尽くさせ,<br/>わが知恵を得て, かつようさせよ。<br/>',NULL,50309,4);
INSERT INTO stanza VALUES('J339','4','こころ,意志得て, なれにたよらせ,<br/>わがあいを得て, 主にそそがせよ。<br/>',NULL,50310,5);
INSERT INTO stanza VALUES('J339','5','わがすべて得よ, 主とけつごうし,<br/>なれのなかへと, われをうしなう。<br/>',NULL,50311,6);
INSERT INTO stanza VALUES('J340','1','完ぜんに主にささげたい, 主の御まえにささげたい。<br/>祭だんのうえに, 　　すべてささげる,<br/>つみあがなった 　　　 主に帰す。<br/>',NULL,50312,1);
INSERT INTO stanza VALUES('J340','2','主にささげる-わがいのち, あたえられたものすべて。<br/>なれのことばに, よろこびしたがう,<br/>永えんにわたり, したがう。<br/>',NULL,50313,2);
INSERT INTO stanza VALUES('J340','3','主にささげる-金,ぎん,とみ; 主,あとうもの,さらに豊富。<br/>われは買われた, ゆえ,主にささぐ,<br/>すべて主のもの, わが主よ。<br/>',NULL,50314,3);
INSERT INTO stanza VALUES('J340','4','主にささげる-主にささぐ, われ,主のもの,主にささぐ;<br/>豊まんが住まう 主を生かし出す,<br/>われでなく,主が, すべてぞ。<br/>',NULL,50315,4);
INSERT INTO stanza VALUES('J341','1','享らくと利えきで, ゆうわくするな;<br/>地のげん影,虚えい, われ,なやますな;<br/>偶ぞう捨てたわれ, イェスにぞくする,<br/>キリストにささげ, かれにぞくする。<br/>',NULL,50316,1);
INSERT INTO stanza VALUES('J341','chorus','いまや,われ, イェスのもの;<br/>われにぞくさず, イェスのもの。<br/>',NULL,50317,2);
INSERT INTO stanza VALUES('J341','2','キリストにぞくす, 何たるあんそく！<br/>おのれによらずに, 主の豊富による。<br/>主とわれのこのみ, いちとなるとき,<br/>めぐみの主イェスよ, なれをきょう受す。<br/>',NULL,50318,3);
INSERT INTO stanza VALUES('J341','3','うみつかれしわれ, もがきを捨てて,<br/>なにものこさずに, すべてささげる。<br/>主はご自身捨てた, われも主に帰す;<br/>すべてあとう主に, われはささげる。<br/>',NULL,50319,4);
INSERT INTO stanza VALUES('J342','1','イェスのためきよく生く, 主のよろこびもとめて,<br/>わがすべて明けわたす, これぞしゅくふくのみち。<br/>',NULL,50320,1);
INSERT INTO stanza VALUES('J342','chorus','わがために死に,なれたまえば,<br/>すくいぬし主にわれをささぐ;<br/>わがこころには主の御座のみ,<br/>いまよりひたすら,ただ主に生く。<br/>',NULL,50321,2);
INSERT INTO stanza VALUES('J342','2','イェスのためわれは生く, わがつみ,あがなわれた;<br/>はげましてまねく主に, すべてささげ,したがう。<br/>',NULL,50322,3);
INSERT INTO stanza VALUES('J342','3','イェスのためいずこへも, みこころのままに行く;<br/>苦つう,そんしつをみな, 十字架のいち部とする。<br/>',NULL,50323,4);
INSERT INTO stanza VALUES('J342','4','イェスのため生くる日々, 主の笑がおあおぎつつ,<br/>失せしものに主を宣べ, 主のきょう受へみちびく。<br/>',NULL,50324,5);
INSERT INTO stanza VALUES('J343','1','もがかず,主にたより, ちからを得る;<br/>かくとうせず,主に行き, あんそくする。<br/>',NULL,50325,1);
INSERT INTO stanza VALUES('J343','2','無意味なふんとうも, 努りょくもせず,<br/>無じょう件でささげれば, あんそく得る。<br/>',NULL,50326,2);
INSERT INTO stanza VALUES('J343','3','すべてイェスにたよる, 主こそすくい;<br/>あいのゆえ,奴隷となり, 自由ねがわず。<br/>',NULL,50327,3);
INSERT INTO stanza VALUES('J343','4','ふくじゅうし,ちから得, 死ねば生きる;<br/>「わが意でなく,主の意志」, しょう利得さす。<br/>',NULL,50328,4);
INSERT INTO stanza VALUES('J344','1','主の意志にしたがう,<br/>主は陶器士,われ,つち;<br/>意のままつくり,焼き,<br/>降ふくさせ,帰させよ。<br/>',NULL,50329,1);
INSERT INTO stanza VALUES('J344','2','主の意志にしたがう,<br/>主のまえにひれ伏す:<br/>さぐり,わればく露し,<br/>あらい,きよめたまえ。<br/>',NULL,50330,2);
INSERT INTO stanza VALUES('J344','3','主の意志にしたがう,<br/>自己捨てることねがう;<br/>われ,くだき,はぎ取り,<br/>われを無になしませ。<br/>',NULL,50331,3);
INSERT INTO stanza VALUES('J344','4','主の意志にしたがう,<br/>まったく降ふくする;<br/>れい満ちて,主,ながれ,<br/>キリスト,われに生く。<br/>',NULL,50332,4);
INSERT INTO stanza VALUES('J345','1','いかに主をあいすや？ いかに主につかえるや？<br/>主のみちよりはなれず， いかに主にしたしむや？<br/>',NULL,50333,1);
INSERT INTO stanza VALUES('J345','2','わがみち,苦つうでも， 主よ，しり込みさせずに，<br/>なおも主にふく従させ， 主の十字架をおしえよ。<br/>',NULL,50334,2);
INSERT INTO stanza VALUES('J345','3','なれは何とおおくの 純けつなたのしみ捨て，<br/>うれい，つかれ，飢え，かわき， くらいよる過ごしたか。<br/>',NULL,50335,3);
INSERT INTO stanza VALUES('J345','4','わがため，うれい，死に， ご自身をよろこばせず；<br/>ゆえに主より愛すもの われ，地上に持ち得よう？<br/>',NULL,50336,4);
INSERT INTO stanza VALUES('J345','5','すべてをそんとなす， 主のかえりみ得るため;<br/>すべてをふん土として， 惜しみなく主をあいす。<br/>',NULL,50337,5);
INSERT INTO stanza VALUES('J346','1','イェスにしたがう,いずこへも:<br/>たいらなみち,けわしいみち,<br/>主,ともにいませば,ためらわず,<br/>王こくまでしたがいゆく。<br/>',NULL,50338,1);
INSERT INTO stanza VALUES('J346','chorus','主にしたがう！主にしたがう！どこにいても主にしたがう！<br/>主にしたがう！主にしたがう！どんなときにもしたがう！<br/>',NULL,50339,2);
INSERT INTO stanza VALUES('J346','2','イェスにしたがう,いずこへも:<br/>たとえ死のかげのたにでも,<br/>主はみずからかえりみるゆえ,<br/>さい後までしたがいゆく。<br/>',NULL,50340,3);
INSERT INTO stanza VALUES('J346','3','イェスにしたがう,どんなときも:<br/>たとえくろくもがあるとも,<br/>すくいぬしの案ばいあるゆえ,<br/>夜明けまでしたがいゆく。<br/>',NULL,50341,4);
INSERT INTO stanza VALUES('J347','1','十字架,負って,主にしたがう; ほまれ,虚えい,みな捨てる;<br/>嘲しょう,ばとう,気にとめず; はく害あれど,みちそれず;<br/>ことば,まもり,ちゅうじつに; かの日,かんむり受けるまで;<br/>かんむり受く,かんむり受く。<br/>',NULL,50342,1);
INSERT INTO stanza VALUES('J348','1','われ,すべてを捨て, 十字架をになう;<br/>いやしめられても, せまきみち行く。<br/>愛し,もとめしもの, いま,大たんに捨てて,<br/>かみとキリストを, 　受くべき分とす。<br/>',NULL,50343,1);
INSERT INTO stanza VALUES('J348','2','この世は主を捨て, 　われをも捨てた;<br/>ひと,あざむくとも, 　主はあざむかず。<br/>ともはわれを捨て, てきはたけりくるうも,<br/>主の笑がおを見て, 　われ,へい安得る。<br/>',NULL,50344,2);
INSERT INTO stanza VALUES('J348','3','去れ！世のたのしみ, 　来たれ！くるしみ;<br/>主の御むねならば, 　苦痛もよろこび。<br/>アバちちよ,と呼び, こころ,なれにそそぐ;<br/>暴風も濃いくもも, みなえきとなす。<br/>',NULL,50345,3);
INSERT INTO stanza VALUES('J348','4','ひとのはくがいは, 　主にいたらせる;<br/>苦なんおもいほど, 　天の平安あまし。<br/>主の御かおあれば, くるしみ,うれいなし;<br/>主がうちになくば, 　よろこびもなし。<br/>',NULL,50346,4);
INSERT INTO stanza VALUES('J348','5','めぐみにて前進し, 　えい光にはいる;<br/>主,われをみちびき, 　夜明けにいたる。<br/>地のつとめ終わり, こう程をはしり終え,<br/>のぞみ,じつげんし, 　賛美はあふれる。<br/>',NULL,50347,5);
INSERT INTO stanza VALUES('J349','1','王こくを目ざすもの 多くいるが,<br/>十字架を負うものは おおくはない！<br/>主のみちをあゆもうと しないのに,<br/>ひとは主のしゅくふく, なおもとむ。<br/>',NULL,50348,1);
INSERT INTO stanza VALUES('J349','2','えいこうしたうもの 多くいるが,<br/>はじを受けるものは おおくはない！<br/>勝利者を目ざすものは 多くいるが,<br/>損しつをねがうもの 多くはない。<br/>',NULL,50349,2);
INSERT INTO stanza VALUES('J349','3','供きゅうをしたうもの 多くいるが,<br/>断じきをねがうもの おおくはない！<br/>主とともにうたうこと できるとも,<br/>ねむらずいのること むずかしい。<br/>',NULL,50350,3);
INSERT INTO stanza VALUES('J349','4','御座のみぎとひだり もとめるが,<br/>いやしくなることを みなおそれる;<br/>すべてのそなえあれば, 賛美するが,<br/>わずかの要きゅうにも, 不へい言う。<br/>',NULL,50351,4);
INSERT INTO stanza VALUES('J349','5','されど,せいじつに主 愛するもの,<br/>わざわいもさいわいも かえりみない;<br/>主のためにしんけつを そそぎ出す;<br/>',NULL,50352,5);
INSERT INTO stanza VALUES('J350','1','主のがわ立ち, したがって,<br/>主のため生き, みちあゆみ,<br/>この世を捨て, ぜんしんし,<br/>たたかうもの, だれなるや？<br/>',NULL,50353,1);
INSERT INTO stanza VALUES('J350','chorus','あがない通し, めぐみ通し,<br/>えい光の主の がわに立つ。<br/>',NULL,50354,2);
INSERT INTO stanza VALUES('J350','2','主のぐん隊に 参加するは,<br/>かんむり栄光の ためでなく,<br/>主のあいにて はげまされ,<br/>主のめぐみを 受けたゆえ。<br/>',NULL,50355,3);
INSERT INTO stanza VALUES('J350','3','なが血により あがなわれ,<br/>われらなれの たみとなる;<br/>主のしゅくふく 無げんなり,<br/>主にしたがい, ぜん進する。<br/>',NULL,50356,4);
INSERT INTO stanza VALUES('J350','4','てきはいかに つよくとも,<br/>しょう利のはた, ひるがえる;<br/>主のしんじつ, 不変のゆえ,<br/>主のがい歌は さだめらる。<br/>',NULL,50357,5);
INSERT INTO stanza VALUES('J350','5','主のえらびし へいそつは,<br/>主にしたがい, ぜんしんす;<br/>高貴な身分を わすれずに,<br/>忠せつ尽くし, ゆうかんに。<br/>',NULL,50358,6);
INSERT INTO stanza VALUES('J351','1','十字架,負うへい士, 主にしたがう;<br/>代価をおそれずに, 御名つたえる。<br/>',NULL,50359,1);
INSERT INTO stanza VALUES('J351','chorus','とうとい主の御名, 主,わがため死ぬ,<br/>われも十字架,負い, かんむりを得る。<br/>',NULL,50360,2);
INSERT INTO stanza VALUES('J351','2','ひと,栄光得るため, いのちかける;<br/>われ,いかでねむり, むさぼり得よう？<br/>',NULL,50361,3);
INSERT INTO stanza VALUES('J351','3','ないてきをいなむ, やぶれふさぐ;<br/>世はともとならず, たすけならず。<br/>',NULL,50362,4);
INSERT INTO stanza VALUES('J351','4','主よ,勝利のために, ちからたまえ;<br/>みことばにたより, つよくされる。<br/>',NULL,50363,5);
INSERT INTO stanza VALUES('J352','1','われらうつり変わるが, 主はいつも変わらない;<br/>やくそくはひとつだに, むなしくはならない。<br/>',NULL,50364,1);
INSERT INTO stanza VALUES('J352','2','われ,まよいはなれるが, 主は捨てることはない;<br/>かれのような真のとも, 地に見いだし得ない。<br/>',NULL,50365,2);
INSERT INTO stanza VALUES('J352','3','主,えい遠にうら切らず, わがため,ちから尽くす;<br/>われらをあいしたなら, 最後まで愛しとおす。<br/>',NULL,50366,3);
INSERT INTO stanza VALUES('J352','4','されど,われ主をわすれ, ひそかにこころ変わり,<br/>偶ぞうにつかえるとも, こころにいたみなし。<br/>',NULL,50367,4);
INSERT INTO stanza VALUES('J352','5','偶ぞうがたおれたとき, かなしみ,主をたずねた;<br/>主にそむいていたのに, 主は変わらないとも。<br/>',NULL,50368,5);
INSERT INTO stanza VALUES('J352','6','主はなおも受け入れて, なぐさめ,したしくする;<br/>何のわだかまりもなく, 最後まで愛しとおす。<br/>',NULL,50369,6);
INSERT INTO stanza VALUES('J352','7','ああ,主よ,何というあいよ, こえ張り上げ賛美する;<br/>忍たいづよきこの主に, こころ溶け,ひれ伏す。<br/>',NULL,50370,7);
INSERT INTO stanza VALUES('J353','1','かつてのわたしは 燃えていました；<br/>ぜんしんしようと つとめました。<br/>けれどもいまでは, 冷めてしまった。<br/>復こうとろう苦の 日々をおもう。<br/>',NULL,50371,1);
INSERT INTO stanza VALUES('J353','chorus','わすれられぬ, すくいぬしよ！<br/>はなれられぬ, てんのちちよ！<br/>',NULL,50372,2);
INSERT INTO stanza VALUES('J353','2','かつてのわたしは 全しんささげて,<br/>ろう苦を惜しまず つかえました。<br/>けれどもいまでは, この世に染まり,<br/>日々にながされて, 悔いもしない。<br/>',NULL,50373,3);
INSERT INTO stanza VALUES('J353','3','かつてのわたしは 主だけをあいし,<br/>この世を捨て,主を もとめました。<br/>けれどもいまでは, この世をあいし,<br/>世ぞくてきになり, 世びとのよう。<br/>',NULL,50374,4);
INSERT INTO stanza VALUES('J353','4','かつて主はあまく, まんぞくでした;<br/>主にひざまずいて, ちかいました:<br/>「わたしはこれから 自ぶんをささげ,<br/>主のことばにだけ したがいます」。<br/>',NULL,50375,5);
INSERT INTO stanza VALUES('J353','5','主のためではない ろう苦むなしい,<br/>かげを追うように, さすらうのみ。<br/>主はこのわたしを 待っておられる。<br/>世ぞくをはなれて 主にかえろう。<br/>',NULL,50376,6);
INSERT INTO stanza VALUES('J353','6','夜はふけ,みょうじょう あらわれたので,<br/>くらいやみを出て, 主をもとめよう。<br/>もういち度てんの あまさあじわい,<br/>あいを取りもどし, 主に立ちます。<br/>',NULL,50377,7);
INSERT INTO stanza VALUES('J353','chorus','せまいみちを ふたたび行く;<br/>忠じつに生き, 苦難を受ける。<br/>',NULL,50378,8);
INSERT INTO stanza VALUES('J354','1','いかで主のれいを, ひねもすはなれて,<br/>うれえさすや！<br/>主をば待たせずに, いーまやかえりきて,<br/>まったくしたがう。<br/>',NULL,50379,1);
INSERT INTO stanza VALUES('J354','2','御むね成すために, われとわがすべて,<br/>まったくささげん;<br/>いまよりのち,ただ, 御ーむねのじょう就を<br/>したいもとむ。<br/>',NULL,50380,2);
INSERT INTO stanza VALUES('J354','3','かつてひとりをも みちびけぬわれは,<br/>いま恥じ入る;<br/>主をかたるために, ゆーたかにあぶらを<br/>そそぎたまえ。<br/>',NULL,50381,3);
INSERT INTO stanza VALUES('J354','4','めぐみの主,われを ともとなすのみか,<br/>はなよめとす。<br/>主とひとつなれば, 十ー字架をよろこび<br/>いのちながさん。<br/>',NULL,50382,4);
INSERT INTO stanza VALUES('J355','1','サタンのわい賂を断ち, かみに生ーきる;<br/>かみに生きるひとの 所とくは無限;<br/>せいも死もすべては, そのひとのもの。<br/>キリスト,わがいのち, われの住まい。<br/>',NULL,50383,1);
INSERT INTO stanza VALUES('J355','2','われのようなものを 主はえらばれた;<br/>それにおうじないとは, なんたること！<br/>犠せいなどと言うまい, どんなだい価も;<br/>主のぐんたいに入る, 何たるけん利！<br/>',NULL,50384,2);
INSERT INTO stanza VALUES('J355','3','無にひとしいだい価, 支はらうだけで,<br/>ひと,事ぶつすべては, われのものぞ;<br/>主のものはわがもの, われは主といち;<br/>無限のいのち享受す, 何たるえきぞ！<br/>',NULL,50385,3);
INSERT INTO stanza VALUES('J356','1','えい遠の御子といち, 　ひとつれいとなり,<br/>すべてをふくむ死と, 　かみのいのちを得る。<br/>愛された御子といち, 　ながいち部となり,<br/>ともにちちの世継ぎ, 　れいの住まいとなる。<br/>',NULL,50386,1);
INSERT INTO stanza VALUES('J356','2','受にくの御子といち, 　なれの肢体となり,<br/>なれ,わがうちにあり, 　ともにこの地,あゆむ。<br/>受こうの御子といち, 　霊のちからを得て,<br/>まいにち,まい時,主と 　同ろうし,はなれない。<br/>',NULL,50387,2);
INSERT INTO stanza VALUES('J356','3','捨てられた子といち, 　さばき,のろい経て,<br/>つみ,死,よみにたいし, 　ともにしょう利を得る。<br/>復かつの御子といち, 　はかより脱しゅつし,<br/>新そうぞうに生きて, 　ついに義の実むすぶ。<br/>',NULL,50388,3);
INSERT INTO stanza VALUES('J356','4','昇てんの御子といち, 　ともに御座に着き,<br/>なが権威にあずかり, 　主とともに支はいす。<br/>再らいの御子といち, 　ともに栄光を受け,<br/>ながかたちあらわし, 　永えんになれといち。<br/>',NULL,50389,4);
INSERT INTO stanza VALUES('J356','note','［２ 受こう(膏)の――油塗られた］<br/>',NULL,50390,5);
INSERT INTO stanza VALUES('J357','1','しょう利の主と十字架に, われ,けつごうする;<br/>困難にもかたく立つは, 主のささえあるゆえ。<br/>',NULL,50391,1);
INSERT INTO stanza VALUES('J357','2','復かつの主とけつ合す, 天のたち場に立つ;<br/>十字架の栄光かがやき, 無限のめぐみしめす。<br/>',NULL,50392,2);
INSERT INTO stanza VALUES('J357','3','主につながり,勝利得て, わがれい沸き立つ;<br/>聖なる御名をさけべば, くらやみは逃げ去る。<br/>',NULL,50393,3);
INSERT INTO stanza VALUES('J357','4','復かつの主,威厳ある主！ 主とけつごうする;<br/>十字架はつねにしょう利, サタンを打ちくだく。<br/>',NULL,50394,4);
INSERT INTO stanza VALUES('J357','5','キリストとけつ合する！ そはすくいのみち;<br/>何ととうといけつごう, 賛美は主にふさわしい。<br/>',NULL,50395,5);
INSERT INTO stanza VALUES('J358','1','主にあり得た地位, 不思議でたかい！<br/>めぐみのすくいで, 主のようになる。<br/>主,あらわるとき, 完全に主に似る;<br/>されど,いまもわれ, 主といちである。<br/>',NULL,50396,1);
INSERT INTO stanza VALUES('J358','chorus','主といち,主といち, 不思議なけつごう,<br/>めぐみ,われにおよび, 主といちとならせる。<br/>',NULL,50397,2);
INSERT INTO stanza VALUES('J358','2','じゅう字架にていち, 復かつにていち;<br/>のろいから解かれ, 主といちとなる。<br/>しょう天にていち, 子の身分でいち;<br/>新ろう新婦のように, 主といちとなる。<br/>',NULL,50398,3);
INSERT INTO stanza VALUES('J358','3','主の功せきといち, いのりにていち,<br/>主の価値すべては, 信仰で享受する。<br/>信仰,愛にていち, いのちにていち,<br/>いのち,あいを持ち, 主のよう聖となる。<br/>',NULL,50399,4);
INSERT INTO stanza VALUES('J359','1','めぐみの主イェスと 霊にありひとつ;<br/>わがうちに生きる ご自身たのしむ。<br/>',NULL,50400,1);
INSERT INTO stanza VALUES('J359','chorus','なれとわれは, まったくひとつ;<br/>ながとみ,わが供給, なれ,わがすべて。<br/>',NULL,50401,2);
INSERT INTO stanza VALUES('J359','2','ひとなるいのちを, ゆたかな人性を,<br/>われのせいかつに もちい,たのしむ。<br/>',NULL,50402,3);
INSERT INTO stanza VALUES('J359','3','十字架にてひとつ, ながうちで死ぬ;<br/>われ,この世に死ぬ, この世もわれに。<br/>',NULL,50403,4);
INSERT INTO stanza VALUES('J359','4','復かつにてひとつ, いまなれと生く;<br/>主はいのちの供給, いまわがうちに。<br/>',NULL,50404,5);
INSERT INTO stanza VALUES('J359','5','しょう天にてひとつ, ともに天に座す;<br/>地じょうでたびびと, ながうちに生く。<br/>',NULL,50405,6);
INSERT INTO stanza VALUES('J359','6','御座にありひとつ， 権威にあずかる,<br/>いのち得ることで, 性しつ得るように。<br/>',NULL,50406,7);
INSERT INTO stanza VALUES('J360','1','おお,ゴルゴタ！わが主は, ここで死なれた;<br/>十字架で血ながし, つみ解かれた。<br/>',NULL,50407,1);
INSERT INTO stanza VALUES('J360','chorus','ゴルゴタのおく義を われに啓示し,<br/>主とわれ,ひとつを 知らせたまえ。<br/>',NULL,50408,2);
INSERT INTO stanza VALUES('J360','2','おお,ゴルゴタ！ここにて, 主とともに死ぬ;<br/>十字架のゆえ,われ, おも荷解かる。<br/>',NULL,50409,3);
INSERT INTO stanza VALUES('J360','3','おお,ゴルゴタ！主ともに, われはほうむられ,<br/>主ともに復かつし, せいかつする。<br/>',NULL,50410,4);
INSERT INTO stanza VALUES('J360','4','おお,ゴルゴタ！サタンは はずかしめ受け,<br/>御名により悪鬼は われにふくす。<br/>',NULL,50411,5);
INSERT INTO stanza VALUES('J360','5','おお,ゴルゴタ！御名にて, われはたたかう;<br/>てきは御名聞けば, さからい得ず。<br/>',NULL,50412,6);
INSERT INTO stanza VALUES('J360','6','おお,ゴルゴタ！賛美する, 主はそこで死に,<br/>わがつみあがない, われを解放す。<br/>',NULL,50413,7);
INSERT INTO stanza VALUES('J360','7','おお,ゴルゴタ！その意義, われ,まなびたし！<br/>信仰にて,主ととも, しょう利に立つ。<br/>',NULL,50414,8);
INSERT INTO stanza VALUES('J361','1','主とともに死ぬ真理の おく義を主は啓示した;<br/>方ほう,ちからによらず, 勝利得るをわれ知る。<br/>',NULL,50415,1);
INSERT INTO stanza VALUES('J361','2','主の十字架はわがもの, ひかり,わがうち照らす;<br/>ともに死んだと信じれば, 世のちから失せ去る。<br/>',NULL,50416,2);
INSERT INTO stanza VALUES('J361','3','われ,十字架につけられ, 人じょう,自己に勝ったのに,<br/>地のもの,もとめるのか？ 幸ふくをのぞむのか？<br/>',NULL,50417,3);
INSERT INTO stanza VALUES('J361','4','ゆえに主のなかに入り, 主の死のたち場に立つ,<br/>いのち,権のう,わがもの, 主といちであるゆえ。<br/>',NULL,50418,4);
INSERT INTO stanza VALUES('J361','5','主はサタンのわざ,勢りょく, 死のちから,やぶられた,<br/>主とともにしょう利して, 日ごと大能,経けんす。<br/>',NULL,50419,5);
INSERT INTO stanza VALUES('J361','6','主よ,ただ十字架により, われらはしょう利を得る;<br/>御かおを見るときまで, ながそくせきを踏む。<br/>',NULL,50420,6);
INSERT INTO stanza VALUES('J361','7','十字架の事じつ受ける, ねがわくは,ながれいが<br/>われに死の意義しめし, つみ,自己を脱がせよ。<br/>',NULL,50421,7);
INSERT INTO stanza VALUES('J361','8','主のようにしょう利得させ, 主とともにおうとなせ！<br/>十字架負うのをねがえば, この栄光にあずかる！<br/>',NULL,50422,8);
INSERT INTO stanza VALUES('J362','1','自己,つみ,世に対し, 主とともに死ぬ;<br/>へい安得て,死より, いのちにはいる。<br/>主の苦難あずかり, 死にいたるまで,<br/>じゅう字架のみちを, 主にしたがい,行く。<br/>',NULL,50423,1);
INSERT INTO stanza VALUES('J362','chorus','十字架のみちを, 主とともにあゆむ！<br/>主よ,せまきみちを, あゆませたまえ。<br/>',NULL,50424,2);
INSERT INTO stanza VALUES('J362','2','主の死にあずかる, 復かつ知るゆえ;<br/>主の苦難あずかる, ふく従ねがうゆえ。<br/>復かつのちからで, 霊のなかに生き,<br/>われ,よろこび行く, 十字架のみちを。<br/>',NULL,50425,3);
INSERT INTO stanza VALUES('J362','3','主ととも,死に,生き, くるしみ,賞,得る;<br/>勝利者はこうして, ほう賞を受ける。<br/>何とたのしい！かの日, 主のみこえ聞く,<br/>「忠じつにあゆんだ, 十字架のみちを！」<br/>',NULL,50426,4);
INSERT INTO stanza VALUES('J363','1','われは主とともに死ぬ; ともに起き,いのち得る;<br/>ともに昇天し,超えつす; まい時われ,御名に帰す。<br/>',NULL,50427,1);
INSERT INTO stanza VALUES('J363','chorus','まい時あいでまもられ, まい時ながいのち得て,<br/>まい時なれ待ちのぞみ, まい時なが御名に帰す。<br/>',NULL,50428,2);
INSERT INTO stanza VALUES('J363','2','試練にすべて主います; おも荷すべて,主は負う;<br/>苦難をすべて,主になう; まい時,主はかえりみる。<br/>',NULL,50429,3);
INSERT INTO stanza VALUES('J363','3','さびしさ,かなしみなし, ためいき,もだえもなし,<br/>患難すべて,主はにない, まい時,主はかえりみる。<br/>',NULL,50430,4);
INSERT INTO stanza VALUES('J363','4','よわいとき,たすけられ, やまいみな,いやされる;<br/>まい時,苦らくともにし, イェスわが主,ともにいます。<br/>',NULL,50431,5);
INSERT INTO stanza VALUES('J364','1','主とともにほうむられ, 　主とともに復かつす;<br/>わがなすべきわざの 　いまだなにかありや？<br/>栄光かみに！<br/>',NULL,50432,1);
INSERT INTO stanza VALUES('J364','2','主とともに復かつし, 　せいなるみちあゆむ;<br/>つみにたいし死んで, 　かみにたいし生きる！<br/>栄光かみに！<br/>',NULL,50433,2);
INSERT INTO stanza VALUES('J364','3','主とともに生かつし, 　主とともにあゆめば,<br/>日々死にわたされて, 　そくばくより解かる。<br/>栄光かみに！<br/>',NULL,50434,3);
INSERT INTO stanza VALUES('J364','4','わがからだをささげ, 　主の奴隷とし生きる;<br/>めぐみのもとにあり, 　主はわれを支はいす。<br/>栄光かみに！<br/>',NULL,50435,4);
INSERT INTO stanza VALUES('J364','5','主にあり成ちょうして, 　過去のこと恥じ入る;<br/>聖べつへの実むすび, 　かみの御むね満たす。<br/>栄光かみに！<br/>',NULL,50436,5);
INSERT INTO stanza VALUES('J365','1','われ,主とともに死に, 　十字架は解放する;<br/>主,ともに復かつし, 　主,わがうちに生く。<br/>',NULL,50437,1);
INSERT INTO stanza VALUES('J365','chorus','主ともに,この世,自己, つみに死ぬあまさよ！<br/>主ともに生く超えつよ！ わがうち供給する。<br/>',NULL,50438,2);
INSERT INTO stanza VALUES('J365','2','かくされたるおく義, 　信こうにより知る;<br/>栄光ののぞみの主, 　わがうちに生きる。<br/>',NULL,50439,3);
INSERT INTO stanza VALUES('J365','3','自然かいのほうそく: 　むぎ死に,実むすぶ;<br/>いやしいえだ,接がれ, 　豊富ないのち得る。<br/>',NULL,50440,4);
INSERT INTO stanza VALUES('J365','4','それは聖なる秘けつ－　われの聖でなく,主;<br/>われ,空にし,満たせ, 　わが度りょう増せや。<br/>',NULL,50441,5);
INSERT INTO stanza VALUES('J365','5','やまいをいやすのは, 　われが自己に死に,<br/>いのちのちからを 　受けることによる。<br/>',NULL,50442,6);
INSERT INTO stanza VALUES('J365','6','十字架を経て御座に, 　これぞ主のあゆみ;<br/>死ののちにえい光, 　主のようにあゆむ。<br/>',NULL,50443,7);
INSERT INTO stanza VALUES('J366','1','主がたとえ千回, 生まれても,もし,<br/>うちに生きずば, すくいはない。<br/>木の十字架には, すくいはない;<br/>うちなる十字架, なれをいやす。<br/>',NULL,50444,1);
INSERT INTO stanza VALUES('J366','chorus','おお,主のじゅう字架を, うちに受け入れる;<br/>自己の支はいを出て, 主により生きる。<br/>',NULL,50445,2);
INSERT INTO stanza VALUES('J366','2','なにかあいせば, そのものになる:<br/>かみ愛せばかみ, ちりはちりに;<br/>自己が死ぬなら, かみが生きる;<br/>自己なく,無なら, 主は満ち満つ。<br/>',NULL,50446,3);
INSERT INTO stanza VALUES('J366','3','かみ得たいなら, 知恵をつかうな;<br/>「あい」よりちかい みちーはない。<br/>自分の利えきを もとめぬなら,<br/>かみのえい光は, なれを満たす。<br/>',NULL,50447,4);
INSERT INTO stanza VALUES('J367','1','主のすべてのはたらき, 十字架で終わらず,<br/>主はべつのかたちを取りて, はたらきつづける。<br/>',NULL,50448,1);
INSERT INTO stanza VALUES('J367','2','主,いまもすくいをなし, かたって,みちびく;<br/>主はれいと成り,わきいでて, 照らし,ふくさせる。<br/>',NULL,50449,2);
INSERT INTO stanza VALUES('J367','3','れいなるなれのちから, 運こうしつづける;<br/>ひとをかんどうし,はげまし, なぐさめ,めいじる。<br/>',NULL,50450,3);
INSERT INTO stanza VALUES('J367','4','主はれい,れいが来るは, 主が来られること;<br/>れいの満たしは主の満たし, れいはなれご自身。<br/>',NULL,50451,4);
INSERT INTO stanza VALUES('J367','5','れいはなれの命れいを, わがうちで遂行す;<br/>なれが御ちちのめいれいを, 地で成したように。<br/>',NULL,50452,5);
INSERT INTO stanza VALUES('J367','6','霊を知り,れいにふくし, 霊に満ちることは,<br/>なれを知り,なれにふくして, なれに満ちること。<br/>',NULL,50453,6);
INSERT INTO stanza VALUES('J367','7','主よ,なれ,たかきてんに 座するのみでなく,<br/>なおも地じょうでかつどうし, わがうちに生きる。<br/>',NULL,50454,7);
INSERT INTO stanza VALUES('J368','1','ちちはなれにあり, なれを通して来た;<br/>ちちを知りたくば, なれ知るほかなし。<br/>',NULL,50455,1);
INSERT INTO stanza VALUES('J368','2','なれ,地にありし日, ひとはなれを見て,<br/>なれにむらがるも, 真になれに触れず。<br/>',NULL,50456,2);
INSERT INTO stanza VALUES('J368','3','子にあり,ちち来る, 霊として,なれ来る;<br/>なれにてちち知り, 霊にてなれを知る。<br/>',NULL,50457,3);
INSERT INTO stanza VALUES('J368','4','かつてにく体着て, ろう苦された主は,<br/>いま,わが霊に住み, ご自身を供給する。<br/>',NULL,50458,4);
INSERT INTO stanza VALUES('J368','5','かつてなれはちち, いまなれは聖れい;<br/>ないじゅうする霊は, ながべつのかたち。<br/>',NULL,50459,5);
INSERT INTO stanza VALUES('J368','6','聖れいを経験して, なれのえいこうと,<br/>なが性しつ,いのち, なが本しつを知る。<br/>',NULL,50460,6);
INSERT INTO stanza VALUES('J368','7','何と実際である主, 御名を賛美します;<br/>なれよりしたしく, あいするものなし。<br/>',NULL,50461,7);
INSERT INTO stanza VALUES('J369','1','なれ,にくたいにあるとき, なれをふかく知り得ず;<br/>そのれいとなりしいま, 啓示され,あきらかになる。<br/>',NULL,50462,1);
INSERT INTO stanza VALUES('J369','2','なれ,かつてあがないぬし, いま,わがなぐさめぬし;<br/>そとでの接しょくでなく, うちにて主とけつごうす。<br/>',NULL,50463,2);
INSERT INTO stanza VALUES('J369','3','なれはせいれいと成って, ご自身を啓示するゆえ,<br/>なれの臨ざいをかんじ, なれの真じつをおぼえる。<br/>',NULL,50464,3);
INSERT INTO stanza VALUES('J369','4','弟子たちはかつて,なれと したしくともにいたが,<br/>いま,われ,主を知るのは, はるかにかれらにまさる。<br/>',NULL,50465,4);
INSERT INTO stanza VALUES('J369','5','主はない住の霊と成った, 何という実際なるかた！<br/>手で触れず,目で見ぬも, さらにふかく主をあいす。<br/>',NULL,50466,5);
INSERT INTO stanza VALUES('J369','6','せいれいはうちがわより, 絶えずなれを供きゅうし,<br/>われの義,せい,あがない, われの知恵,実となられる。<br/>',NULL,50467,6);
INSERT INTO stanza VALUES('J369','7','ながれい,わがれいに住み, きょうきゅうし,いちとなる;<br/>時々刻こく,なれとわれ, いちのなかで生かつする。<br/>',NULL,50468,7);
INSERT INTO stanza VALUES('J370','1','弟子たちはながねん, 主とともにいたのに,<br/>主ご自身をさとらず, 知っているようで知らず。<br/>',NULL,50469,1);
INSERT INTO stanza VALUES('J370','2','かれらはみこえ聞き, 主の御すがたを見て,<br/>じかに触れ合っても, 主がだれなのか知らず。<br/>',NULL,50470,2);
INSERT INTO stanza VALUES('J370','3','われらの目おおわれ, 真の主を見ていない,<br/>主を知る,と言うとも, とうめいには知り得ず。<br/>',NULL,50471,3);
INSERT INTO stanza VALUES('J370','4','主はそのれいであり, べつのなぐさめぬし,<br/>なれの豊富をもって, われのうちに啓示する。<br/>',NULL,50472,4);
INSERT INTO stanza VALUES('J370','5','われの全そんざいを, ながれいで浸とうし,<br/>なれの感かく満たし, すみずみまで触れませ。<br/>',NULL,50473,5);
INSERT INTO stanza VALUES('J370','6','どうか,なれのれいが, 実感をもてぞう加し,<br/>見ても見えなかった 主ご自身を見せたまえ。<br/>',NULL,50474,6);
INSERT INTO stanza VALUES('J370','7','主よ,ご自身を啓示し, ご自身をあたえませ;<br/>主にまさる実さいも, 真じつもこの世になし。<br/>',NULL,50475,7);
INSERT INTO stanza VALUES('J370','8','主の霊がわが霊より, 洪ずいのようあふれて,<br/>いたるところえい光, ひかり,なれで満たせや。<br/>',NULL,50476,8);
INSERT INTO stanza VALUES('J370','9','何と親みつな生かつ！ 地にあって,なお天のよう;<br/>あまい臨ざいに満ち, 賛美,歓喜,満ちあふれる。<br/>',NULL,50477,9);
INSERT INTO stanza VALUES('J371','1','主よ,なれはいまその霊, いのちあたえる霊;<br/>なが豊富を供給す, 何とえいこうでしんせい！<br/>',NULL,50478,1);
INSERT INTO stanza VALUES('J371','2','主よ,なれはいまその霊, 大能をもって解放す;<br/>いのちのほうそく, われを自由にし,つよめる。<br/>',NULL,50479,2);
INSERT INTO stanza VALUES('J371','3','主よ,なれはいまその霊, つくり変え,浸透す;<br/>なれに同けい化し, ながえいこう照らし出す。<br/>',NULL,50480,3);
INSERT INTO stanza VALUES('J371','4','主よ,なれはいまその霊, わがれいに住まう;<br/>ふたつれい調和し, いちのなかで行どうする。<br/>',NULL,50481,4);
INSERT INTO stanza VALUES('J371','5','いかに霊をかつようし, なれを享受するか,<br/>いかに霊に生くか, 主よ,われを訓練しませや。<br/>',NULL,50482,5);
INSERT INTO stanza VALUES('J372','1','キリスト，かみの 中心せい,普遍せい；<br/>永遠から永遠まで， かみのあい，かん喜。<br/>',NULL,50483,1);
INSERT INTO stanza VALUES('J372','2','主はかみの化身， かみの豊満が住む;<br/>そのとうとさ，神せい， だれもくらべ得ず。<br/>',NULL,50484,2);
INSERT INTO stanza VALUES('J372','3','主，万ぶつに満つ， かみのごけいかく;<br/>宇ちゅうのすべては, 主の栄こうのため。<br/>',NULL,50485,3);
INSERT INTO stanza VALUES('J372','4','万ぶつ主のため, 主を通し存ざいす;<br/>主,万ぶつのささえ, 中心であり円しゅう。<br/>',NULL,50486,4);
INSERT INTO stanza VALUES('J372','5','あがないである主, 万ぶつを復興する;<br/>有こうな血により, かみに和かいさす。<br/>',NULL,50487,5);
INSERT INTO stanza VALUES('J372','6','すべてのはじめ, しょうかいのかしら,<br/>そのいのち,ない容, 復かつにてちょう子。<br/>',NULL,50488,6);
INSERT INTO stanza VALUES('J372','7','主は王こくの王, すべての権威持つ;<br/>栄光通し支はいし, 万ぶつはふくする。<br/>',NULL,50489,7);
INSERT INTO stanza VALUES('J372','8','新天新地にあり, 主は万ぶつの中心;<br/>かみとひと,ともに, 永遠にまでいたる。<br/>',NULL,50490,8);
INSERT INTO stanza VALUES('J372','9','主はばんぶつの 第いち位なるかた;<br/>この万ぶつの主を, いま,われあじわう。<br/>',NULL,50491,9);
INSERT INTO stanza VALUES('J373','1','キリスト,かみのあかし, 本しつ,行動にあって;<br/>かみのえいこうひょうげんし, 神せいをあらわす。<br/>',NULL,50492,1);
INSERT INTO stanza VALUES('J373','2','キリスト,かみのあかし, そは律法にまさる;<br/>律ぽうは文字でかたるのみ, いのちをもちいず。<br/>',NULL,50493,2);
INSERT INTO stanza VALUES('J373','3','キリスト,かみのほう満, かみの内容,よう素;<br/>かれはかみのまったき化身, うつわ,また住まい。<br/>',NULL,50494,3);
INSERT INTO stanza VALUES('J373','4','かみの栄こう,かたちを, キリストは展覧す;<br/>かみのみこころ,かみのみち, かれのなかに見る。<br/>',NULL,50495,4);
INSERT INTO stanza VALUES('J373','5','キリスト,わが霊に住み, 永えんにわがぶん;<br/>霊のなかでかれにあずかり, かみのすべて受く。<br/>',NULL,50496,5);
INSERT INTO stanza VALUES('J374','1','キリスト,唯いつの実際, かみ,ひと,すべての実際;<br/>主はかみにいたるみち, 主なくば万有はいつわり。<br/>',NULL,50497,1);
INSERT INTO stanza VALUES('J374','2','衣,しょく,住すべてはかげ, その本たいはキリスト;<br/>キリストをひょうちょうし, かれがその実さいである。<br/>',NULL,50498,2);
INSERT INTO stanza VALUES('J374','3','キリスト,満ちなければ, 万事,万ぶつみなむなしい;<br/>いっさい得て,享受しても, 主なければ,みなむなしい。<br/>',NULL,50499,3);
INSERT INTO stanza VALUES('J374','4','かれは真のかみ,真の主, 真のひかり,真の事ぶつ,<br/>真の衣しょく,生けるみず, 真のいのち,真のあじわい。<br/>',NULL,50500,4);
INSERT INTO stanza VALUES('J374','5','すべての神がく,道理は, キリスト,実際とすべき;<br/>主なくば,聖書の知しき, 文字にすぎず,みなむなしい。<br/>',NULL,50501,5);
INSERT INTO stanza VALUES('J374','6','時かんと空間の実さい, ものごとすべての実際;<br/>永遠から永遠にいたり, キリスト,唯いつの実さい。<br/>',NULL,50502,6);
INSERT INTO stanza VALUES('J375','1','主よ,なれはご自しんを, われの実さいとなす;<br/>信仰にとりこの実際は, なによりも真じつで,<br/>その親みつなこと, なにもくらべ得ず。<br/>',NULL,50503,1);
INSERT INTO stanza VALUES('J375','2','われはなが実さい見た: なれこそ,わがかん全;<br/>わがねがいをきよめて, 聖なる愛の火ともす;<br/>わが性しつたかめ, なが豊富は満ちる。<br/>',NULL,50504,2);
INSERT INTO stanza VALUES('J375','3','生ける愛のすくいぬし, したしさ,さらに増す;<br/>栄光の御かおかがやき, みことば,わがちから;<br/>われをつくり変え, めぐみを増しませ。<br/>',NULL,50505,3);
INSERT INTO stanza VALUES('J376','1','めぐみとは御子にあり<br/>たまわるかれご自しん;<br/>事ぶつや環きょうでなく,<br/>主がわが分となること。<br/>',NULL,50506,1);
INSERT INTO stanza VALUES('J376','2','受にくし,神・人ちょう和し,<br/>ひとにかみを得させる,<br/>主はわがこころに住む,<br/>これこそかみのめぐみ。<br/>',NULL,50507,2);
INSERT INTO stanza VALUES('J376','3','パｳロは主をめぐみとし,<br/>すべてちりあくたとす;<br/>「主のためにろう苦すは,<br/>われでなく,主のめぐみ」。<br/>',NULL,50508,3);
INSERT INTO stanza VALUES('J376','4','わがうちで主はちから,<br/>真のめぐみ,しんらいす;<br/>めぐみ,わがれいにあり,<br/>みこころじょう就させる。<br/>',NULL,50509,4);
INSERT INTO stanza VALUES('J376','5','このめぐみ,生ける主は,<br/>ちからづけ,かえりみる;<br/>いちずになれをしたい,<br/>さらに享受させたまえ。<br/>',NULL,50510,5);
INSERT INTO stanza VALUES('J377','1','栄光！主はわがいのち, せいれいはみちびく;<br/>無りょくはちからに変わり, やみはひかりとなる。<br/>',NULL,50511,1);
INSERT INTO stanza VALUES('J377','2','栄光！主のなかで生き, 霊にしたがい,あゆむ;<br/>しっぱいは勝利に変わり, なげきは賛美となる。<br/>',NULL,50512,2);
INSERT INTO stanza VALUES('J378','1','おお何といういのちぞや！ 　　おおなんというやすきぞや！<br/>十字架でわれともに, 　　　死にて,いま主はすべて！<br/>主,えい光の事じつあたえたもう, もはや生くるのはわれにあらじ,<br/>わがうちにいますは, 主イェス・キリストなり！<br/>',NULL,50513,1);
INSERT INTO stanza VALUES('J378','2','おお何というよろこびぞ！ おおなんというあんそくぞ！<br/>かたちづくらるるは, 主なり,いまわがうちに;<br/>いのち,せいしつつくり込まれん, わがすべてことごとく終わりぬ。<br/>主のものすべては, わがすべてとなりぬ！<br/>',NULL,50514,2);
INSERT INTO stanza VALUES('J378','3','おお何というおもいぞや！ おおなんというほこりぞや！<br/>あらわさるるは主ぞ, うちにいますキリスト;<br/>死とせい,わざわい,ふくあれど, もはやはずかしめ,われにあらじ;<br/>主はわれによりて, あかしなさしめたもう。<br/>',NULL,50515,3);
INSERT INTO stanza VALUES('J378','4','おお何というさちなるぞ！ おおなんというしゅうかくぞ！<br/>目ざすはまえにある キリストかれご自しん;<br/>他にもとむるたからはあらじ, 主はわがのぞみ,えいこう,かんむり;<br/>すべてをふくむ主, くらぶるものあらじ！<br/>',NULL,50516,4);
INSERT INTO stanza VALUES('J379','1','おお何というちからぞや！ おおなんといういきおいぞ！<br/>かみはキリストをば， 死よりよみがえらせて，<br/>御座に座させ,万ぶつのうえに， かしらとして,しょうかいにあとう，<br/>召会,このちからで， てきをあしのしたに。<br/>',NULL,50517,1);
INSERT INTO stanza VALUES('J379','2','おお何という事じつぞや！ おおなんというおく義ぞや！<br/>キリストの肢体なる われは聖徒らと調和し，<br/>あたらしきひとに建造されて， かしらなるキリストにつながる;<br/>われらはしょうかい, ご計かくにあずかる。<br/>',NULL,50518,2);
INSERT INTO stanza VALUES('J379','3','おお何というひろさぞや！ おおなんというながさぞや！<br/>そのたかさとふかさ, 主なるキリストは無限。<br/>その度りょうははかり知れない, そのひろがりはじん知を越える;<br/>しょうかいを建造し, さらに成就するため。<br/>',NULL,50519,3);
INSERT INTO stanza VALUES('J380','1','えいこうのいのち！ それはキリスト！<br/>ぜん,義,せい,ひかり！ このいのち豊富！<br/>かみの栄こう,豊富, 主のうちにある;<br/>わがいのちなる主, わがうち供給す。<br/>',NULL,50520,1);
INSERT INTO stanza VALUES('J380','2','しんせいないのち！ それはキリスト！<br/>かれはれいとなり, わがうちに住む。<br/>うんこうし,照らし, あぶらもて塗り,<br/>満たし,うるおして, わがうち供給す。<br/>',NULL,50521,2);
INSERT INTO stanza VALUES('J380','3','たいのうのいのち！ それはキリスト！<br/>われもともに死に, つみより解かれ,<br/>ともに復かつして, 主とともに生く。<br/>主,大能けい験させ, わがうち供給す。<br/>',NULL,50522,3);
INSERT INTO stanza VALUES('J380','4','勝利を得たいのち！ それはキリスト！<br/>十字架の勝利にて, とりことさせず。<br/>サタン,この世,人情に, われを勝たせる;<br/>勝利のいのち,いま, わがうち供給す。<br/>',NULL,50523,4);
INSERT INTO stanza VALUES('J380','5','栄光,神せい,たい能, しょう利のいのち！<br/>つよめ,打ちかたせ, せいちょうさせる;<br/>つくり変え,似させ, ちょうえつさせる;<br/>上げられる日まで, わがうち供給す。<br/>',NULL,50524,5);
INSERT INTO stanza VALUES('J381','1','主,わがいのち, うちに生く;<br/>かみの豊富で われ,満たす。<br/>なが性しつで われきよめ,<br/>復かつの大能, 勝利得さす。<br/>',NULL,50525,1);
INSERT INTO stanza VALUES('J381','2','いのちの流通, われ照らし,<br/>ひかりのなか, まじわりす;<br/>種々の供給と, 要求もあり,<br/>われをきよめ, 享受させる。<br/>',NULL,50526,2);
INSERT INTO stanza VALUES('J381','3','なれはその霊, あぶら塗り,<br/>れい,たましいに 浸みわたり,<br/>ながかたちに つくり変え,<br/>身のたけまで 成長させる。<br/>',NULL,50527,3);
INSERT INTO stanza VALUES('J381','4','いのちの成分, ゆたか,新鮮,<br/>われ,うるおし, 呼び覚ます。<br/>いのちは死を 飲み尽くす,<br/>なげき変わり, うたとなる。<br/>',NULL,50528,4);
INSERT INTO stanza VALUES('J381','5','われをまったく 主にささぐ,<br/>みこころにて まじわりす;<br/>もはや自分で あらためず,<br/>もがかず,主を さまたげず。<br/>',NULL,50529,5);
INSERT INTO stanza VALUES('J381','6','おのが努りょく, まったくやめ,<br/>主,はたらかせ, 自己を脱ぐ;<br/>聖徒取り組む みからだは,<br/>主を住まわせ, 主を表現す。<br/>',NULL,50530,6);
INSERT INTO stanza VALUES('J382','1','栄光なるキリスト, かみのえい光の表現！<br/>とわに無限なるかみは, 有限なひととなる。<br/>',NULL,50531,1);
INSERT INTO stanza VALUES('J382','chorus','かみの化身キリストは, おく義,ゆたか,エンジｮィ！<br/>聖のせい,ひとのひと, われ霊で受け継ぐ！<br/>',NULL,50532,2);
INSERT INTO stanza VALUES('J382','2','かみのゆたかさは, ながうちにやどりぬ;<br/>にく体もてあがない成し, いまその霊となる。<br/>',NULL,50533,3);
INSERT INTO stanza VALUES('J382','3','ちちのすべて継ぐ, なれ,わが霊にありて,<br/>じっさいのれいとして, なれを経験させる。<br/>',NULL,50534,4);
INSERT INTO stanza VALUES('J382','4','れいなることばは, なが実さいもたらす;<br/>ことば受け,霊触れなば, わがきょう給となる。<br/>',NULL,50535,5);
INSERT INTO stanza VALUES('J382','5','おおいのないかお, かがみとし栄光うつし,<br/>ながかたちにわれ変え, なれをあらわさす。<br/>',NULL,50536,6);
INSERT INTO stanza VALUES('J382','6','聖となり,勝利得る, みちはこのほかなし;<br/>いのち触れ,霊に生きる, みちはほかになし。<br/>',NULL,50537,7);
INSERT INTO stanza VALUES('J382','7','なが霊しみわたり, かく部分かみで満つ！<br/>ふるきひと捨て,ともに かみの住まいとなる。<br/>',NULL,50538,8);
INSERT INTO stanza VALUES('J383','1','栄こうのなかの かみ・ひとは,<br/>せい,こう義,知恵, ひかり,慈愛;<br/>いのちを捨てて, あがない成し,<br/>かれのせいしつに われ変える。<br/>',NULL,50539,1);
INSERT INTO stanza VALUES('J383','2','栄こうのなかの しょう利の王;<br/>サタンをくだき, やみ,やぶり,<br/>しょうてんにあり, 支はいする,<br/>ともにたかく上げ, 勝利得さす。<br/>',NULL,50540,2);
INSERT INTO stanza VALUES('J383','3','栄こうのなかの いのちの主;<br/>わがうちに住み, 供きゅうする,<br/>聖なるせいしつ つくり込み,<br/>えいこうのいのち, 表現させる。<br/>',NULL,50541,3);
INSERT INTO stanza VALUES('J383','4','栄こうのなかの のぞみの主;<br/>間もなく来たり, われむかえ,<br/>主のたいのうで 変ぼうさせ,<br/>栄こうのかたちに われ,変える。<br/>',NULL,50542,4);
INSERT INTO stanza VALUES('J384','1','いのちの木とかわ, エデンのとくしょくは,<br/>飲しょくし,御まえに 生きることなり。<br/>',NULL,50543,1);
INSERT INTO stanza VALUES('J384','chorus','主はわれのきょうきゅう, れいとなり,やしなう;<br/>主のれいをあじわい, かみを享受する。<br/>',NULL,50544,2);
INSERT INTO stanza VALUES('J384','2','木はえい光ある主, 生けるかてをあとう;<br/>かみの豊富,享受し, まんぞくを得る。<br/>',NULL,50545,3);
INSERT INTO stanza VALUES('J384','3','かわは無限のれい, ひとのれいを供給し,<br/>ゆたかもて満たし, きよくなしたもう。<br/>',NULL,50546,4);
INSERT INTO stanza VALUES('J384','4','キリストはいのち, れいのうちに生きて,<br/>われと混ざり合い, 主,かがやき出る。<br/>',NULL,50547,5);
INSERT INTO stanza VALUES('J384','5','えい光の主あがめ, 絶えず霊にしたがう;<br/>主をふかく知れば, めぐみは満ちる。<br/>',NULL,50548,6);
INSERT INTO stanza VALUES('J385','1','主よ,なれマナ, 天からくだる;<br/>わがパンとなり, われを飽き足らせる。<br/>',NULL,50549,1);
INSERT INTO stanza VALUES('J385','2','裂かれしいわ, みずをながす;<br/>飲めばすぐに, かわきはいやされる。<br/>',NULL,50550,2);
INSERT INTO stanza VALUES('J385','3','飢えかわいて, いま主に行く;<br/>主ご自身もて, いま,やしないたまえ。<br/>',NULL,50551,3);
INSERT INTO stanza VALUES('J385','4','食べ飲みして, 主を取り入れ,<br/>なが聖霊飲み, ながいのち満きつす。<br/>',NULL,50552,4);
INSERT INTO stanza VALUES('J385','5','主,得なければ, むなしくなる;<br/>食べ飲みして, 生きるちからを得る。<br/>',NULL,50553,5);
INSERT INTO stanza VALUES('J386','1','イェスはわが世かい： いのち,すべて！<br/>日々われのちから， 主とともに立つ。<br/>苦なんに遭うとも， ちからづけ，ささえ，<br/>はげまし，解放する わがとも！<br/>',NULL,50554,1);
INSERT INTO stanza VALUES('J386','2','イェスはわが世かい: 試練のなかで,<br/>ささえ,かえりみて, しゅくふく得さす。<br/>たい陽,あめあたえ, 主はしゅうかくする;<br/>みのりをあたえる わがとも！<br/>',NULL,50555,2);
INSERT INTO stanza VALUES('J386','3','イェスはわが世かい, なんと信じつ！<br/>めぐみあとう主を, はなれ得ようか？<br/>主にしたがい行き, 主にみちびかれる;<br/>よるひる見まもる わがとも！<br/>',NULL,50556,3);
INSERT INTO stanza VALUES('J386','4','イェスはわが世かい, さい高のとも;<br/>主との混ざり合い, えい遠にもとむ。<br/>すばらしいいのち, えい遠のけつごう;<br/>これこそよろこび, わがとも！<br/>',NULL,50557,4);
INSERT INTO stanza VALUES('J387','1','つみがふかくとも, みちけわしくとも,<br/>どんな境ぐうにも, 主よ,なれは十分！<br/>',NULL,50558,1);
INSERT INTO stanza VALUES('J387','2','どんな試練のときも, どんなうれいのときも,<br/>たとえたおれても, 主よ,なれは十分！<br/>',NULL,50559,2);
INSERT INTO stanza VALUES('J387','3','ばん事が順ちょうで, 安らくをむさぼり,<br/>くらやみおおうとも, 主はやはり十分！<br/>',NULL,50560,3);
INSERT INTO stanza VALUES('J387','4','かなしみ,わずらい, しつぼうにくれて,<br/>いのれないときも, 主はなおも十分！<br/>',NULL,50561,4);
INSERT INTO stanza VALUES('J387','5','どんな環きょうにも, 主の手はささえて,<br/>なれを経験させる, 主はまったく十分！<br/>',NULL,50562,5);
INSERT INTO stanza VALUES('J388','1','すでに得たり,宇宙にて さいこうのたから;<br/>キリストをば得たり, われよろこばん！<br/>',NULL,50563,1);
INSERT INTO stanza VALUES('J388','2','この主,かみの小ひつじ, わがつみになえり;<br/>かみのこう義,たい陽, いやすひかり。<br/>',NULL,50564,2);
INSERT INTO stanza VALUES('J388','3','この主,いのちの木なり, そのにてせい長す;<br/>その木の実しょくせば, 供給はゆたか。<br/>',NULL,50565,3);
INSERT INTO stanza VALUES('J388','4','この主,いのちのいずみ, 生けるみずながす;<br/>うちをとわにながれ, かわきのぞく。<br/>',NULL,50566,4);
INSERT INTO stanza VALUES('J388','5','この主,わがさい司なり, 御まえにとりなす;<br/>けい示と預言に満ち, 王の権威,持つ。<br/>',NULL,50567,5);
INSERT INTO stanza VALUES('J388','6','主はすくいぬし,仲保者, 医者,ぼく者,げん首,<br/>わがかみ,主,ちち,あに, 師,おっと,しん友。<br/>',NULL,50568,6);
INSERT INTO stanza VALUES('J388','7','わがいのち,ちから,知恵: 義と聖とあがない;<br/>へい安,のぞみ,安そく, 歓喜,栄光,みち。<br/>',NULL,50569,7);
INSERT INTO stanza VALUES('J388','8','この主,万ゆうに満てり, ことばに言い得じ;<br/>かれははじめ,おわり, またすべてぞ。<br/>',NULL,50570,8);
INSERT INTO stanza VALUES('J388','9','なんたるたから得しぞ, こころさけばずや！<br/>キリストをば得たり, われよろこばん！<br/>',NULL,50571,9);
INSERT INTO stanza VALUES('J388','note','(英510)<br/>第 二 首<br/>',NULL,50572,10);
INSERT INTO stanza VALUES('J388','1','すでに得たり,宇宙にて さいこうのたから;<br/>キリストをば得たり, われよろこばん！<br/>',NULL,50573,11);
INSERT INTO stanza VALUES('J388','2','この主,かみの小ひつじ, わがつみになえり;<br/>かみのこう義,たい陽, いやすひかり。<br/>',NULL,50574,12);
INSERT INTO stanza VALUES('J388','3','この主,いのちの木なり, そのにてせい長し,<br/>その木の実しょくせば, 供給はゆたか。<br/>',NULL,50575,13);
INSERT INTO stanza VALUES('J388','4','この主,いのちのいずみ, 生けるみずながす;<br/>うちをとわにながれ, かわきのぞく。<br/>',NULL,50576,14);
INSERT INTO stanza VALUES('J388','5','わがいのち,ひかり,みち, なぐさめ,けんこう,<br/>わがほこり,栄光,豊富, 平安,よろこび。<br/>',NULL,50577,15);
INSERT INTO stanza VALUES('J388','6','主はわが知恵,われの義, せいけつ,じっさい,<br/>われのすくい,ちから, かい放,しょう利。<br/>',NULL,50578,16);
INSERT INTO stanza VALUES('J388','7','この主,わがさい司なり, 御まえにとりなす;<br/>けい示と預言に満ち, 王の権威,持つ。<br/>',NULL,50579,17);
INSERT INTO stanza VALUES('J388','8','主はすくいぬし,仲保者, 医者,ぼく者,げん首,<br/>わがかみ,主,ちち,あに, 師,おっと,しん友。<br/>',NULL,50580,18);
INSERT INTO stanza VALUES('J388','9','主はわが将ぐん,キャプテン, たたかいでみちびく;<br/>護えい,ガイド,じゅう者, まもり,照らす。<br/>',NULL,50581,19);
INSERT INTO stanza VALUES('J388','10','主はわが永遠の住まい, わが豊富な良き地,<br/>とりで,とう,かくれ場, 永遠のもく標。<br/>',NULL,50582,20);
INSERT INTO stanza VALUES('J388','11','主はわがのぞみ,ねがい, よろこび,まんぞく;<br/>わが褒しょう,もくてき, 供きゅう,たすけ。<br/>',NULL,50583,21);
INSERT INTO stanza VALUES('J388','12','主はわれの肥えた土地, はるのあめとつゆ;<br/>まことのぶどうの木, なれに住まう。<br/>',NULL,50584,22);
INSERT INTO stanza VALUES('J388','13','主はわがまつり,新げつ, しんの安そくにち;<br/>主はわれのあさ,ひる, 現ざい,えい遠。<br/>',NULL,50585,23);
INSERT INTO stanza VALUES('J388','14','この主,万ゆうに満てり, ことばに言い得じ;<br/>かれははじめ,おわり, またすべてぞ。<br/>',NULL,50586,24);
INSERT INTO stanza VALUES('J388','15','なんたるたから得しぞ, こころさけばずや！<br/>キリストをば得たり, われよろこばん！<br/>',NULL,50587,25);
INSERT INTO stanza VALUES('J389','1','世のふく去れ, 主,わがもの！<br/>地のあい,絶えて, 主,わがもの！<br/>地はくらやみ, 安そくはなし,<br/>主のみすばらしい, 主,わがもの！<br/>',NULL,50588,1);
INSERT INTO stanza VALUES('J389','2','誘わくするな, 主,わがもの！<br/>主,ともにいます, 主,わがもの！<br/>世のたのしみ, 目をくらます,<br/>われは主に行く, 主,わがもの！<br/>',NULL,50589,2);
INSERT INTO stanza VALUES('J389','3','世のゆめ去れ, 主,わがもの！<br/>いまや目覚めた, 主,わがもの！<br/>世をしたえば, くるしみ増す;<br/>主のみ,まんぞく, 主,わがもの！<br/>',NULL,50590,3);
INSERT INTO stanza VALUES('J389','4','この世よ,去れ, 主,わがもの！<br/>永えんよ,来たれ, 主,わがもの！<br/>しゅくふくの主, 安そくなる主,<br/>主よ,来たりませ！ 主,わがもの！<br/>',NULL,50591,4);
INSERT INTO stanza VALUES('J390','1','イェスはわがすくいぬし， 何とよろこばしいかた；<br/>われをみちびき，まもる， たい能の主，わがため。<br/>',NULL,50592,1);
INSERT INTO stanza VALUES('J390','chorus','イェスこそ，わがため， 主，わがすべてのすべて。<br/>',NULL,50593,2);
INSERT INTO stanza VALUES('J390','2','健こうでも，病んでいても， ひかりでも，暗こくでも，<br/>いかなるきょうぐうでも， へい安の主，わがため。<br/>',NULL,50594,3);
INSERT INTO stanza VALUES('J390','3','主はわがしろ，わがたて， わがいのち，わがひかり；<br/>われをまもり，かくまう， あがないぬし，わがため。<br/>',NULL,50595,4);
INSERT INTO stanza VALUES('J390','4','主は預げん者，さい司，王， いのちのいずみとかて，<br/>しんじつで，よりどころ， すくいぬし，わがため。<br/>',NULL,50596,5);
INSERT INTO stanza VALUES('J390','5','よろこびもくるしみも， そんしつにもえきにも，<br/>主はすべて満たされる， イェスつねに，わがため。<br/>',NULL,50597,6);
INSERT INTO stanza VALUES('J391','1','やすらぎのみなもと, 　 キリスト,まったきあい;<br/>たすけと避けどころ, 臨ざいこそあん全;<br/>つみ,うれい,はじより, 　主のうちに身をかくす。<br/>',NULL,50598,1);
INSERT INTO stanza VALUES('J391','2','主はすべてのひつ要, 　 労苦のなかの安そく;<br/>きずをいやすくすり, 　 そんのときのえき;<br/>しいたげのときの笑み, 　はじのなかのかんむり。<br/>',NULL,50599,2);
INSERT INTO stanza VALUES('J391','3','けつ乏のときの供給, 　 困難のときのかい放;<br/>よわいときのちから, 　 くらやみのひかり;<br/>なやみにあってかん喜, 　死のなかのわが復かつ。<br/>',NULL,50600,3);
INSERT INTO stanza VALUES('J391','4','やすらぎのみなもと, 　 キリスト,まったきあい;<br/>なれに身をかくして, 　 臨ざいを享受する:<br/>主はすべてのすべて, 　無限で尽きないきょう受！<br/>',NULL,50601,4);
INSERT INTO stanza VALUES('J392','1','わがさいあいの主, つねにもとめる;<br/>人せいのおく義, わがよりどころ。<br/>',NULL,50602,1);
INSERT INTO stanza VALUES('J392','2','時機を得たそなえ, 究きょくのたすけ;<br/>かん美のきわみ, つねにしんじつ。<br/>',NULL,50603,2);
INSERT INTO stanza VALUES('J392','3','よろこびのいずみ, とわに変わらず;<br/>もっともしたしい, さいあいのかた。<br/>',NULL,50604,3);
INSERT INTO stanza VALUES('J393','1','主はわがよろこび, かわきをいやす;<br/>主はうたのうた, さびしさを消す。<br/>',NULL,50605,1);
INSERT INTO stanza VALUES('J393','2','主は美のなかの美, あじわいふかし;<br/>高貴に満つ主は こよなきたから。<br/>',NULL,50606,2);
INSERT INTO stanza VALUES('J393','3','主はしんのいのち, われ,復かつさす;<br/>主はせいのせい, 世から分離さす。<br/>',NULL,50607,3);
INSERT INTO stanza VALUES('J393','4','主は義のなかの義, 御まえに立たす;<br/>ちからのちから, あゆみつよめる。<br/>',NULL,50608,4);
INSERT INTO stanza VALUES('J393','5','主はしんのたい能, われ,たかく上げ,<br/>勝利の主われに 勝ちを得させる。<br/>',NULL,50609,5);
INSERT INTO stanza VALUES('J393','6','主はしんのつよさ, われ,かい放する;<br/>主,真のいきおい, こころ,霊,強化す。<br/>',NULL,50610,6);
INSERT INTO stanza VALUES('J393','7','王のおうなる主は, わがこころの王;<br/>ひかりのひかり, われらを照らす。<br/>',NULL,50611,7);
INSERT INTO stanza VALUES('J393','8','主は主のなかの主, わがうちに住む;<br/>主はしんのみち, われをみちびく。<br/>',NULL,50612,8);
INSERT INTO stanza VALUES('J393','9','医者のなかの医者, 全存ざいいやす;<br/>不思議の不思議, われ,えい光化す。<br/>',NULL,50613,9);
INSERT INTO stanza VALUES('J393','10','希望のなかの希望, まえ向きにさす;<br/>賞のなかのしょう, われを前進さす。<br/>',NULL,50614,10);
INSERT INTO stanza VALUES('J393','11','あいのなかのあい, われ,感ぷくさす;<br/>忍たいの忍たい, われを礼拝さす。<br/>',NULL,50615,11);
INSERT INTO stanza VALUES('J393','12','主,真のいさましさ, 尊貴にふさわしい;<br/>主,真のえいこう, 賛美にふさわしい。<br/>',NULL,50616,12);
INSERT INTO stanza VALUES('J394','1','かつていやし,たまものと, しゅくふく,われもとめたが,<br/>されど,いまはただもとむ, 主ご自しんと主のことば。<br/>',NULL,50617,1);
INSERT INTO stanza VALUES('J394','chorus','主たかく上げ, 永えんにうたう;<br/>イェスわがすべて, わがすべて。<br/>',NULL,50618,2);
INSERT INTO stanza VALUES('J394','2','かつて努りょく,いましん頼, 主のことばにかたく立つ;<br/>かれにしっかり捕らえられ, いかり下ろし,堅固になる。<br/>',NULL,50619,3);
INSERT INTO stanza VALUES('J394','3','かつて自分のえきもとむ, いま主に生き,依りたのむ;<br/>かつては主をしたがわす, いま主に聞き,ふくじゅうす。<br/>',NULL,50620,4);
INSERT INTO stanza VALUES('J394','4','かつては主を利ようした, いま主がわれ,はたらかす;<br/>かつては賞賛もとめたが, 主の満ぞくをいまもとむ。<br/>',NULL,50621,5);
INSERT INTO stanza VALUES('J394','5','かつて労苦し,火は消えた, いま主にあり,火を燃やす;<br/>わが得たものただご自身, たずさえ上げ,待ちのぞむ。<br/>',NULL,50622,6);
INSERT INTO stanza VALUES('J395','1','ただ主イェス,われのテｰマ, われのメｯセｰジはイェス;<br/>主イェスのみわれのうた, 主イェスはわがのぞみ。<br/>',NULL,50623,1);
INSERT INTO stanza VALUES('J395','chorus','ただ主イェス,いつもイェス, われらうたうはイェス,<br/>すくいぬし,いのち,医者, おうこくの建ぞう者。<br/>',NULL,50624,2);
INSERT INTO stanza VALUES('J395','2','ただ主イェス,わがすくい, われのつみをになう,<br/>とわのあがない成して, ひとにめぐみあとう。<br/>',NULL,50625,3);
INSERT INTO stanza VALUES('J395','3','ただ主イェス,わがいのち, つみ,自己を去らせる;<br/>主イェスは聖れいにより, わがこころを満たす。<br/>',NULL,50626,4);
INSERT INTO stanza VALUES('J395','4','ただ主イェス,わがいやし, われのやまいを負う;<br/>いのちと昇てんの豊富, 肢たいに分けあとう。<br/>',NULL,50627,5);
INSERT INTO stanza VALUES('J395','5','ただ主イェス,わがちから, ペンテコステもたらす;<br/>主よ,せいでわれ満たし, 絶えず勝利,得させよ。<br/>',NULL,50628,6);
INSERT INTO stanza VALUES('J395','6','いまイェスを待ちのぞむ, 主のまねき,われ聞く;<br/>つねにただイェスであり, イェスこそ万ゆうの主。<br/>',NULL,50629,7);
INSERT INTO stanza VALUES('J396','1','イェスを見なければ, 日々はあじ気なし！<br/>とりのこえ,はなも, あまさはなくなる;<br/>太よう,ひかり失せ, 野やまも歓喜なし;<br/>主のなかにあれば, ふゆもはるのよう。<br/>',NULL,50630,1);
INSERT INTO stanza VALUES('J396','2','香ばしい主の御名, あまき主のみこえ,<br/>臨ざい,うれい消し, すべてよろこびに;<br/>主ちかくいませば, おそれず,満ち足る,<br/>何たるよろこびよ, はるの日永えんに。<br/>',NULL,50631,2);
INSERT INTO stanza VALUES('J396','3','主のえがおもとめ, われ,あまく感じる,<br/>とき場所変われど, ねがいは変わらず;<br/>主のあい知るなら, だい価をはらえる,<br/>主とともにいれば, ごくもみやとなる。<br/>',NULL,50632,3);
INSERT INTO stanza VALUES('J396','4','われが主のもので, 主がわがうたなら,<br/>なぜうれえるのか？ ふゆがつづくのか？<br/>くろくも吹き去り, 臨ざいかいふくし,<br/>ふゆなく,くもなき 至聖所に行かせよ。<br/>',NULL,50633,4);
INSERT INTO stanza VALUES('J397','1','主観てきなキリスト， いのちとし経験す；<br/>主こそわがすべて， 主とわれひとつ霊。<br/>',NULL,50634,1);
INSERT INTO stanza VALUES('J397','chorus','主はわが主観てきな経験， 実際，あまく，豊富！<br/>わがすべてのすべてぞ， ひつ要みな満たす！<br/>',NULL,50635,2);
INSERT INTO stanza VALUES('J397','2','主は主観てきな経験， いのちもて供給す;<br/>われを復かつさせ， わが霊をたかめる。<br/>',NULL,50636,3);
INSERT INTO stanza VALUES('J397','3','主観てきなキリスト, たましいつくり変え,<br/>おもい,意志,更新し, 栄光のかたち成る。<br/>',NULL,50637,4);
INSERT INTO stanza VALUES('J397','4','主は主観てきな経験, われを超えつさす;<br/>いのちの法そくは, 霊にてわれ解放す。<br/>',NULL,50638,5);
INSERT INTO stanza VALUES('J397','5','主観てきなキリスト, われのはかりなわ;<br/>管理,規制,みちびき, くまなく調整する。<br/>',NULL,50639,6);
INSERT INTO stanza VALUES('J397','6','主は主観てきな経験, わがひつ要満たす;<br/>主の豊富を供給し, 主の豊満,享受さす。<br/>',NULL,50640,7);
INSERT INTO stanza VALUES('J398','1','主は客観てきで主観てき;<br/>客観てきには天で弁護者;<br/>主観てきにはぶん与により,<br/>絶えずいのちを供きゅうする主。<br/>',NULL,50641,1);
INSERT INTO stanza VALUES('J398','2','天にてかみのみぎに座し,<br/>大祭司とし血をささげる;<br/>われらを弁護し,おも荷負い,<br/>保証人とし愛もてかえりみる。<br/>',NULL,50642,2);
INSERT INTO stanza VALUES('J398','3','いのちの霊わが霊に住み,<br/>ご自身のすべてもたらす;<br/>絶えずめぐみ,ちから供給し,<br/>たいのうもてわれにつかえる。<br/>',NULL,50643,3);
INSERT INTO stanza VALUES('J398','4','天にある栄光,受けしひと,<br/>まくのうちに入る先駆者;<br/>ひとをばかみにもたらして,<br/>かみとひとをひとつとさせる。<br/>',NULL,50644,4);
INSERT INTO stanza VALUES('J398','5','かみの豊まんは主に住み,<br/>主は霊にて,かみもたらす;<br/>啓示にてかみをじっ際とし,<br/>いのちにてかみとひと調和す。<br/>',NULL,50645,5);
INSERT INTO stanza VALUES('J398','6','客観てきなしょう天の主は,<br/>再らいし,ひとにあらわる;<br/>主観てきなないじゅうの主は,<br/>栄光のかたちへあらわれ出る。<br/>',NULL,50646,6);
INSERT INTO stanza VALUES('J398','7','やがて天と地はむすばれ,<br/>みやこで神-人へだてなし;<br/>客観てきにも主観てきにも,<br/>合併してかん全にいちとなる。<br/>',NULL,50647,7);
INSERT INTO stanza VALUES('J399','1','かみはキリストを わが霊に啓示す;<br/>外面の宗教でなく, かれを内住さす。<br/>',NULL,50648,1);
INSERT INTO stanza VALUES('J399','chorus','かみのよろこびと, こころのねがい;<br/>かれをつくり込み, かく大すること。<br/>',NULL,50649,2);
INSERT INTO stanza VALUES('J399','2','かみはわがうちに, キリスト生かす;<br/>外面のわざでなく, めぐみを享受す。<br/>',NULL,50650,3);
INSERT INTO stanza VALUES('J399','3','キリストがうちに, かたちづくらる;<br/>けいしきによらず, かれを増加さす。<br/>',NULL,50651,4);
INSERT INTO stanza VALUES('J399','4','かれ,わがこころに ホームをつくる;<br/>奉仕だけではなく, かれに占有さす。<br/>',NULL,50652,5);
INSERT INTO stanza VALUES('J399','5','キリストはわれの えい光ののぞみ;<br/>客観てきではなく, 主観てきな栄光。<br/>',NULL,50653,6);
INSERT INTO stanza VALUES('J399','6','キリストはわれの すべてのすべて;<br/>あらゆることにて かれ秘けつとす。<br/>',NULL,50654,7);
INSERT INTO stanza VALUES('J400','1','主よ,なれはわがいのち, わがすべてぞ;<br/>無駄なくわがものとし, 主を経験する！<br/>',NULL,50655,1);
INSERT INTO stanza VALUES('J400','chorus','主よ,なれはれいぞ, あまくちかし！<br/>不思議なる効き目を ほめたたえる。<br/>',NULL,50656,2);
INSERT INTO stanza VALUES('J400','2','ことごと満たしたまわん, わがひつよう;<br/>いま,わがためのそなえ, じゅうぶんなり。<br/>',NULL,50657,3);
INSERT INTO stanza VALUES('J400','3','ちからあるあまきあぶら そそぎもて;<br/>よわさのなかにありて, ささえられる。<br/>',NULL,50658,4);
INSERT INTO stanza VALUES('J400','4','こころ,おもいのなかの, いのちののり;<br/>わざととのえ,ながゆたか, しみとおる。<br/>',NULL,50659,5);
INSERT INTO stanza VALUES('J400','5','主とわれのごういつは, たぐいあらじ;<br/>ひとつれいつねにとわに, ともにあり。<br/>',NULL,50660,6);
INSERT INTO stanza VALUES('J400','6','わがうちにみ住まいを つくりたまえ;<br/>栄光からえいこうへと つくり変えよ。<br/>',NULL,50661,7);
INSERT INTO stanza VALUES('J401','1','キリストはわれを 自ゆうとされる;<br/>すべて死のとげは, われよりはなる。<br/>',NULL,50662,1);
INSERT INTO stanza VALUES('J401','chorus','十字架のしょう利で, 勝ち得てあまる;<br/>復かつのいのちは, われをつよめる。<br/>',NULL,50663,2);
INSERT INTO stanza VALUES('J401','2','のりのようきゅうに われすでに死ぬ;<br/>二度としばられず, めぐみにて生く。<br/>',NULL,50664,3);
INSERT INTO stanza VALUES('J401','3','主,十字架でつみを さばいて,のぞく;<br/>もはやわがうちに つみの地位なし。<br/>',NULL,50665,4);
INSERT INTO stanza VALUES('J401','4','死ははいせられて, 朽ちぬいのち見,<br/>死のきずな断たれ, ふっかつを知る。<br/>',NULL,50666,5);
INSERT INTO stanza VALUES('J401','5','あく魔もこの世も, 踏みくだかれた;<br/>いのちとひかりの 王こくにはいる。<br/>',NULL,50667,6);
INSERT INTO stanza VALUES('J401','6','満ち足りるめぐみ, われらをつつむ;<br/>よわさのなかにて, 主のえい光見る。<br/>［２　のり――律法　３　はいせられて――廃せられて］<br/>',NULL,50668,7);
INSERT INTO stanza VALUES('J402','1','文字にあらず, いのちの主,<br/>教理にあらず, 主キリスト;<br/>自己,つみより 解くものは,<br/>いのちあとう 主キリスト。<br/>',NULL,50669,1);
INSERT INTO stanza VALUES('J402','2','いかなる教訓, 儀しきでも,<br/>たましい変えず, 霊,生かさず;<br/>いのちあたえ, 生かすのは,<br/>れいのなかの 主キリスト。<br/>',NULL,50670,2);
INSERT INTO stanza VALUES('J402','3','いかなる倫理, てつがくも,<br/>主の肢たいに つくり得ず;<br/>復かつの大能, わがうちで,<br/>主のからだを 構せいする。<br/>',NULL,50671,3);
INSERT INTO stanza VALUES('J402','4','キリスト教も, しゅうきょうも,<br/>かみの要求を 満たし得ず;<br/>うちにいます主, わがすべて,<br/>御むねまったく 成し遂げる。<br/>',NULL,50672,4);
INSERT INTO stanza VALUES('J402','5','たまもの,機能, はたらきも,<br/>キリストには 代えられず;<br/>キリストのみ わがすべて,<br/>キリストのみ わがひつ要。<br/>',NULL,50673,5);
INSERT INTO stanza VALUES('J403','1','わが主のほう富は, はかり知れない;<br/>かみのほう富みな, わが享受となる;<br/>',NULL,50674,1);
INSERT INTO stanza VALUES('J403','chorus','しん聖なほう富よ！ すべてわがため！<br/>はかり知れぬ豊富, わが実際となる。<br/>',NULL,50675,2);
INSERT INTO stanza VALUES('J403','2','わが主のほう富は, すべてをふくむ:<br/>いのち,ひかり,知恵, へい安,よろこび。<br/>',NULL,50676,3);
INSERT INTO stanza VALUES('J403','3','あがない,すくいと, 義にん,せいべつ,<br/>復かつのたいのう, しょう天の超えつ。<br/>',NULL,50677,4);
INSERT INTO stanza VALUES('J403','4','わが主のほう富は, すべてなるかみ!<br/>かれのすべて,いま, わが霊で受ける。<br/>',NULL,50678,5);
INSERT INTO stanza VALUES('J403','5','わが主のほう富は, だれも知り得ず！<br/>はかり知れぬ豊富, わが享受となる！<br/>',NULL,50679,6);
INSERT INTO stanza VALUES('J403','6','主の豊富を知って, かん全に経験す;<br/>ともに分け合って, みこころ満たす。<br/>',NULL,50680,7);
INSERT INTO stanza VALUES('J404','1','主,われをみちびく, 何といううるわしさ！<br/>主のなぐさめ満つ, 絶えず御手にたよる身に。<br/>',NULL,50681,1);
INSERT INTO stanza VALUES('J404','chorus','主はわれをみちびく, ちからある御手をもて,<br/>絶えずわれ,したがう, 主の手,われをみちびく。<br/>',NULL,50682,2);
INSERT INTO stanza VALUES('J404','2','苦なんのふちでも, たのしみのそのでも,<br/>平おん,あらしでも, すべては主の御手にある。<br/>',NULL,50683,3);
INSERT INTO stanza VALUES('J404','3','主よ,わが手を取り, ながみちあゆませよ;<br/>さいわい,くるしみ, すべて主の手にゆだねて。<br/>',NULL,50684,4);
INSERT INTO stanza VALUES('J404','4','生がいの行程終え, しょう利を得る日まで,<br/>主の御手はわれを, さい後までみちびきゆく。<br/>',NULL,50685,5);
INSERT INTO stanza VALUES('J405','1','めぐみの主ーよ,われあいす,<br/>つみよりはなれ,なれにつく。<br/>なが血にてわれ,買われしゆえに,<br/>主よ,われはいま,なれをあいす。<br/>',NULL,50686,1);
INSERT INTO stanza VALUES('J405','2','主のあいゆえに主をあいす,<br/>わがためだい価,主ははらう。<br/>いばらのかんむり,われは見たゆえ,<br/>主よ,われはいま,なれをあいす。<br/>',NULL,50687,2);
INSERT INTO stanza VALUES('J405','3','死にいたるまで主をあいす,<br/>いのちのかぎり,主を賛美す。<br/>死にのぞむ日も,なお言いあらわす:<br/>「主よ,われはいま,なれをあいす！」<br/>',NULL,50688,3);
INSERT INTO stanza VALUES('J405','4','無限のよろこび,栄光のなか,<br/>えい遠になれをれいはいす。<br/>えい光のかんむり受ける日,うたう:<br/>「主よ,われはいま,なれをあいす」。<br/>',NULL,50689,4);
INSERT INTO stanza VALUES('J406','1','何とあまくゆたかなる, よろこばしいまじわり！<br/>しゅくふくと平安があり, みうでにあんそくす！<br/>',NULL,50690,1);
INSERT INTO stanza VALUES('J406','chorus','あんそく！ おだやかなへい安;<br/>えい遠の みうでにあんそくす。<br/>',NULL,50691,2);
INSERT INTO stanza VALUES('J406','2','わがたび路行くほどに, こころにへい安ある;<br/>ひかり満ち,めぐみあり, みうでにあんそくす！<br/>',NULL,50692,3);
INSERT INTO stanza VALUES('J406','3','しんぱいやおそれなし, われにあんそくある;<br/>主はともに永遠にいる, みうでにあんそくす！<br/>',NULL,50693,4);
INSERT INTO stanza VALUES('J407','1','主イェスはわれのたい陽, なが臨ざいあればひる,<br/>この世のおおい去り, 御かおを見せたまえ。<br/>',NULL,50694,1);
INSERT INTO stanza VALUES('J407','2','やすらぎ,へい安,かん露, いま,ここちよくねむる;<br/>主のなかにいこい, 主の安そくあじわう。<br/>',NULL,50695,2);
INSERT INTO stanza VALUES('J407','3','よるからあさにいたる 死のかげのたににても,<br/>主よ,ともにいませ, 主なければ意味なし。<br/>',NULL,50696,3);
INSERT INTO stanza VALUES('J407','4','目覚めてしゅくふく受け, わがたび路をつづける;<br/>たずさえ上げられ, あいのうみに溶ける。<br/>',NULL,50697,4);
INSERT INTO stanza VALUES('J408','1','香油のようななれの御名, ぶどう酒にまさるなが愛,<br/>むれにしたがいゆけば, 愛のまじわりにはいる。<br/>',NULL,50698,1);
INSERT INTO stanza VALUES('J408','2','かれはわが愛するもの, かれしたい,かれもとむ;<br/>もつやく,こころに秘め, うるわしさ身にまとう。<br/>',NULL,50699,2);
INSERT INTO stanza VALUES('J408','3','かれの愛のうちに入り, そのあまさに飽き足る;<br/>ひるがえるはたはあい, わがこころ,たのします。<br/>',NULL,50700,3);
INSERT INTO stanza VALUES('J408','4','愛するものはわがもの, 主はぼく者,われはゆり。<br/>日かげ,みな消えるまで, やまの上の雄じかなれ。<br/>',NULL,50701,4);
INSERT INTO stanza VALUES('J408','5','もつやく,乳香のかおり, わがこころ,しみわたれ;<br/>きたかぜ,みなみかぜよ, こころのそのに吹けや。<br/>',NULL,50702,5);
INSERT INTO stanza VALUES('J408','6','はとのようにうるわしく, ゆりのようにきよらかで,<br/>完ぜんに主にぞくして, 主のよろこびとなせや。<br/>',NULL,50703,6);
INSERT INTO stanza VALUES('J408','7','つきのようなかたち持ち, 太陽のような背たけ持つ;<br/>ながいのちをあらわし, ながこころ,やすませる。<br/>',NULL,50704,7);
INSERT INTO stanza VALUES('J408','8','主とわれ,愛でむすばれ, あいは死のようにつよく,<br/>なににも変えられない, 香のやまに主よ,来ませ。<br/>',NULL,50705,8);
INSERT INTO stanza VALUES('J409','1','良きともキリスト, われはとうとぶ;<br/>かれのあいはあまく, おん和でにゅう和;<br/>かれにより生きて, その御手したう;<br/>ともに住み合う, 主とわれ。<br/>',NULL,50706,1);
INSERT INTO stanza VALUES('J409','2','われ,たおれるとき, 主はよわさ知り,<br/>ご自しんにたよらせ, われをささえる;<br/>ひかりにあゆませ, 日々生きさせる;<br/>ともに行どうす, 主とわれ。<br/>',NULL,50707,2);
INSERT INTO stanza VALUES('J409','3','われのあさき愛を, 主は知りながら;<br/>言い知れぬあいもて, われをあいする;<br/>日々,燃えるあいは, とわに絶えない;<br/>ともに愛し合う, 主とわれ。<br/>',NULL,50708,3);
INSERT INTO stanza VALUES('J409','4','くるしみ,よろこび, すべて主に告げ,<br/>ひつよう,ようぼうを, すべて告げれば,<br/>成すべきすべてを, 主,われに告げる;<br/>したしくかたる, 主とわれ。<br/>',NULL,50709,4);
INSERT INTO stanza VALUES('J409','5','ひと,すくうねがい, 主は知りたもう,<br/>主はわれをつかわし, ふく音かたらす;<br/>不思議なあいと死, 主はかたらせる;<br/>つねに同ざいす, 主とわれ。<br/>',NULL,50710,5);
INSERT INTO stanza VALUES('J409','6','おうこく間ぢかと, 主はわれに告げ,<br/>すすみ入るようにと, せつぼうされる;<br/>とわのさち,かん喜, えいこうの御座,<br/>ともに支はいす, 主とわれ。<br/>',NULL,50711,6);
INSERT INTO stanza VALUES('J410','1','えい光のキリスト, わがうち照らす;<br/>たいようにまさり つよくかがやく。<br/>ぜん地はくらやみ, われを捕らえず,<br/>主の苦難のみちが こころ引き寄す。<br/>',NULL,50712,1);
INSERT INTO stanza VALUES('J410','2','われの見たひかり, てんより来たる,<br/>地じょうのひかりに はるかにまさる。<br/>さえぎるものなく, 御かお見させて,<br/>愛とめぐみの豊富, とわに見させる。<br/>',NULL,50713,2);
INSERT INTO stanza VALUES('J410','3','不思議なえい光と ふかきあい得る;<br/>主,みわざじょう就し, たかき座に着く。<br/>垂れまくのぞかれ， 至せい所に入り,<br/>絶えず御かお見て, みことばを聞く。<br/>',NULL,50714,3);
INSERT INTO stanza VALUES('J410','4','主の栄光の御かお, われすでに見た;<br/>主のことば聞いて, 主に満たされた。<br/>えい光がかがやき, 主の御かお見た;<br/>この栄光は,とわに わが住まいなり。<br/>',NULL,50715,4);
INSERT INTO stanza VALUES('J411','1','ゆう日はしずみ, 仕ごとが終わり,<br/>しずかなゆうべに, れいのなかで主に<br/>ひれ伏す。<br/>',NULL,50716,1);
INSERT INTO stanza VALUES('J411','chorus','ちかい,ちかい, ちかい主！<br/>わが霊はしたう, 愛の御かお,したしめる主。<br/>',NULL,50717,2);
INSERT INTO stanza VALUES('J411','2','宇ちゅうのなかで, 御かおもとめる,<br/>見るものすべてに, 主の手をかんじて,<br/>満ち足る。<br/>',NULL,50718,3);
INSERT INTO stanza VALUES('J411','3','夜,更けるほどに, ますますしたう,<br/>ほしを突き抜けて, なれにまみえたし,<br/>主,ともに。<br/>',NULL,50719,4);
INSERT INTO stanza VALUES('J411','4','くらやみ,よるが, やがて過ぎ去り,<br/>えい遠の夜明けが, えい光のキリスト,<br/>もたらす。<br/>',NULL,50720,5);
INSERT INTO stanza VALUES('J412','1','みなもとなる主に しん仰で触れる;<br/>血しおとしん仰で, ながちから得る。<br/>',NULL,50721,1);
INSERT INTO stanza VALUES('J412','chorus','主に触れて,いのち きょうきゅうされる;<br/>主の霊のうん行で, ほう富を享受す。<br/>',NULL,50722,2);
INSERT INTO stanza VALUES('J412','2','しん仰により触れ, なが豊富を得る;<br/>ぜん存ざいひらき, 主に注入される。<br/>',NULL,50723,3);
INSERT INTO stanza VALUES('J412','3','さらにふかく触れ, なが豊富を得る;<br/>めぐみさらに増し, いのちながれる。<br/>',NULL,50724,4);
INSERT INTO stanza VALUES('J412','4','ちから,知恵,慈あい, みななれにある;<br/>なれに触れつづけ, そのすべて得る。<br/>',NULL,50725,5);
INSERT INTO stanza VALUES('J413','1','この静しゅく,臨ざい, さまたげるこえなく,<br/>ただとうとい主ご自身と, みこえがあるのみ。<br/>',NULL,50726,1);
INSERT INTO stanza VALUES('J413','chorus','とうとい主,愛するイェスよ, われにかたりませ:<br/>しずかなてんの場所で, 主のこえを聞く。<br/>',NULL,50727,2);
INSERT INTO stanza VALUES('J413','2','親みつに主かたり, こころにはいり込む;<br/>おくの間に連れてゆき, みこころを明かす。<br/>',NULL,50728,3);
INSERT INTO stanza VALUES('J413','3','このしずけさこそ, 天の聖なるりょういき;<br/>その愛の享受をしたい, よろこび,ちかづく。<br/>',NULL,50729,4);
INSERT INTO stanza VALUES('J413','4','しずけさのなかで, 主よ,身じろぎもせず,<br/>もらさずみこえを聞き, ながあいにひたる。<br/>',NULL,50730,5);
INSERT INTO stanza VALUES('J413','5','いま,わがたましい, やすらぎ,満ぞくする;<br/>主のむねによこたわり, あいの御かお見る。<br/>',NULL,50731,6);
INSERT INTO stanza VALUES('J414','1','まくに入り,えい所,出る, 天あじわい,地を捨てる;<br/>聖のせいで満たされて, 空のくうにだまされず。<br/>',NULL,50732,1);
INSERT INTO stanza VALUES('J414','2','まくに入り,えい所,出る, 天にあれば,地はなれる;<br/>天のえい光したうなら, 地のふくをもとめない。<br/>',NULL,50733,2);
INSERT INTO stanza VALUES('J414','3','まくに入り,主をあおぎ, 営所を出てイェスに行く;<br/>かんむり,御座,はげませば, 十字架おそれずあゆむ。<br/>',NULL,50734,3);
INSERT INTO stanza VALUES('J414','4','まくに入り,復かつ得る, 営所,出て,十字架を負う;<br/>天の御かお見るならば, 地でいさましくあゆむ。<br/>',NULL,50735,4);
INSERT INTO stanza VALUES('J414','5','まくに入り,天あじわい, 営所,出て,患なんしのぶ;<br/>地はいたみあたえるが, 天はわがれいを生かす。<br/>',NULL,50736,5);
INSERT INTO stanza VALUES('J414','6','まくに入り,主を享受し, 営所,出て,ひとを満たす;<br/>天のいのち,われ生かし, 地でひと,しゅくふく得る。<br/>',NULL,50737,6);
INSERT INTO stanza VALUES('J414','7','まくに入り,えい所,出て, まく失せるまですすめ;<br/>天と地がむすびついて, かみ,ひと,住み合うまで。<br/>',NULL,50738,7);
INSERT INTO stanza VALUES('J415','1','主の秘みつの同在, 何とあまいこと！<br/>主イェスにまなぶは 何ととうといこと！<br/>なやみも,試れんも われをみださず;<br/>ゆうわくのときに 主,わがかくれ場,<br/>主,わがかくれ場。<br/>',NULL,50739,1);
INSERT INTO stanza VALUES('J415','2','つかれ,かわくとき, 主のもとに来て,<br/>主のかげにいこい, 新鮮なみず飲む;<br/>主のむねに抱かれ, あまくまじわる;<br/>かれのすばらしい みことばを聞く,<br/>みことばを聞く。<br/>',NULL,50740,2);
INSERT INTO stanza VALUES('J415','3','わが主にくるしみ うったえるときに,<br/>主は忍耐して聞き, わが霊はげます。<br/>主は信じつなかた, わがつみ見つけ,<br/>ひかりで照らして, つみ,責められる,<br/>つみ,責められる。<br/>',NULL,50741,3);
INSERT INTO stanza VALUES('J415','4','秘みつのあまさを 知りたいのなら,<br/>主のみもとに来て, それをあじわえ;<br/>れいにてまじわり, 主の栄光に住み,<br/>主の栄光のかたち, われ,うつし出す,<br/>われ,うつし出す。<br/>',NULL,50742,4);
INSERT INTO stanza VALUES('J416','1','主の死,受け入れ, そとにわとおり,<br/>すくいを受けた, ハレルヤ,賛美す！<br/>あがないの血で, つみより解かれ,<br/>せいべつされた, ハレルヤ,賛美す！<br/>',NULL,50743,1);
INSERT INTO stanza VALUES('J416','chorus','ハレルヤ！ハレルヤ！ 裂かれたまくをわれはとおった！<br/>ハレルヤ,いまわれ おうのまえでせいかつす！<br/>',NULL,50744,2);
INSERT INTO stanza VALUES('J416','2','とばりをとおり, せい所にはいり,<br/>きょうきゅうされた, ハレルヤ,賛美す！<br/>さいだんとおり, かみと和かいし,<br/>この世ほう棄す, ハレルヤ,賛美す！<br/>',NULL,50745,3);
INSERT INTO stanza VALUES('J416','3','たれまくとおり, 至せい所に入り,<br/>めぐみの御座で ハレルヤ,賛美す！<br/>御まえに生きて, 主を住まいとし,<br/>自己のまく裂き, ハレルヤ,賛美す！<br/>',NULL,50746,4);
INSERT INTO stanza VALUES('J416','4','われあがなわれ, さい司とされた,<br/>なんたる身ぶん, ハレルヤ,賛美す！<br/>れいのなかにて えいこうに生き,<br/>よるひるうたう, ハレルヤ,賛美す！<br/>',NULL,50747,5);
INSERT INTO stanza VALUES('J416','note','［３ 自己のまく――自己という隔ての幕］<br/>',NULL,50748,6);
INSERT INTO stanza VALUES('J417','1','夜まだ明けぬ間に, 主の御まえにゆけば,<br/>われ,うちで照らされて, 栄光の御かお見る。<br/>主の豊富きょうのためと, 主はかたり,啓示す;<br/>主のあまさを享受し, かわき満たされる。<br/>',NULL,50749,1);
INSERT INTO stanza VALUES('J417','2','主はことばにより, わがうちでまじわる;<br/>いのち,めぐみともない, わがうちながれる。<br/>主の豊富きょうのためと, 主はかたり,啓示す;<br/>主を飲めばさわやか, かわきいやされる。<br/>',NULL,50750,2);
INSERT INTO stanza VALUES('J417','3','御まえにとどまり, やさしいたい処受け,<br/>しんせいでしん透され, 無限に供給される。<br/>主の豊富きょうのためと, 主はかたり,啓示す;<br/>主の豊満,享受すれば, なやみは逃げ去る。<br/>',NULL,50751,3);
INSERT INTO stanza VALUES('J418','1','主に住みて,まじわれば, しゅくふく,あまさ受ける;<br/>あまき主とけつごうす, もはや主とへだてなし。<br/>',NULL,50752,1);
INSERT INTO stanza VALUES('J418','2','主に住みて,まじわれば, 塗りあぶらはみちびく;<br/>塗りあぶらにしたがい, 主のほう富をきょう受す。<br/>',NULL,50753,2);
INSERT INTO stanza VALUES('J418','3','主に住みて,まじわれば, ひかりさし,やみは去る;<br/>このひかり,したがえば, いのち増し,れい生きる。<br/>',NULL,50754,3);
INSERT INTO stanza VALUES('J418','4','主に住みて,まじわれば, よわさはつよくされる;<br/>なげきはうたと変わり, いのち,死を飲み尽くす。<br/>',NULL,50755,4);
INSERT INTO stanza VALUES('J418','5','主に住みて,まじわれば, この世の魅りょく失せる;<br/>つみはちからうしない, てき逃げ,自己は失せる<br/>',NULL,50756,5);
INSERT INTO stanza VALUES('J418','6','主に住みて,まじわれば, 主のいのちに満たされ,<br/>主のほう富を吸い込み, 主にどうけい化される。<br/>',NULL,50757,6);
INSERT INTO stanza VALUES('J418','7','主に住み,まじわること, わがれいかわき,したう;<br/>全そんざい主に満ちて, とわに主といちとなる。<br/>',NULL,50758,7);
INSERT INTO stanza VALUES('J419','1','なれはぶどうーの木, 　われはそのえだ;<br/>されど,われなにゆえ, 　実をむすばないのか？<br/>',NULL,50759,1);
INSERT INTO stanza VALUES('J419','2','実をむすばせたまえ, 　せつにもとめる;<br/>このいのり聞きませ, 　みこころなるため。<br/>',NULL,50760,2);
INSERT INTO stanza VALUES('J419','3','いかになれに住むか, 　主よ,おしえませ;<br/>もとめばもとむほど, 　へだてをおぼえる。<br/>',NULL,50761,3);
INSERT INTO stanza VALUES('J419','4','なれをなんととおく, 　かんじることか！<br/>ひたすらいのれども, 　いまだ実むすばず。<br/>',NULL,50762,4);
INSERT INTO stanza VALUES('J419','5','「われはぶどうｰの木, 　なれはそのえだ」;<br/>なれを信じたときに, 　この事じつ成就す。<br/>',NULL,50763,5);
INSERT INTO stanza VALUES('J419','6','いまわれ,なれに住み, 　主とわれはいち;<br/>われはすでになれに 　けつ合されたゆえ。<br/>',NULL,50764,6);
INSERT INTO stanza VALUES('J419','7','「住もうとする」のでなく, 　事じつ「住んでいる」;<br/>主からはなれぬように, 　この秘けつたもつ。<br/>',NULL,50765,7);
INSERT INTO stanza VALUES('J419','8','われ,すでに主に住む, 　すでに主に住む;<br/>これはかみの事じつ, 　かみの手のさだめ。<br/>',NULL,50766,8);
INSERT INTO stanza VALUES('J419','9','住もうともとめるのは, 　おろかな行どう;<br/>いま賛美し,よろこび, 　みことばを信じる。<br/>',NULL,50767,9);
INSERT INTO stanza VALUES('J419','10','いまわれ,終わらされ, 　主に安そくする;<br/>なれはいのち,ちから, 　わがすべてとなる。<br/>',NULL,50768,10);
INSERT INTO stanza VALUES('J420','1','主に住むをわれねがう, 絶えずながうちに住む;<br/>えだがぶどうの木に住む, そのようにわれも住む。<br/>',NULL,50769,1);
INSERT INTO stanza VALUES('J420','2','主に住み,豊富きょう受し, ながすべてながし出す,<br/>あたらしきえだとなり, ながいのちの実むすぶ。<br/>',NULL,50770,2);
INSERT INTO stanza VALUES('J420','3','主に住めば自己は失せ, 内じゅうのいのち支配す,<br/>主とふかくまじわれば, 霊はたましい支配する。<br/>',NULL,50771,3);
INSERT INTO stanza VALUES('J420','4','主に住めば御むね知り, なれの秘みつにはいる;<br/>歓喜,へい安われに満つ, みことばはわがちから。<br/>',NULL,50772,4);
INSERT INTO stanza VALUES('J421','1','主なくば無りょく, われ,立ち得ず,<br/>ちから,ぜん,知恵, われにはなし;<br/>親あいなる主は, いっ切のいっさい,<br/>主の手にあれば, 祝ふくとなる。<br/>',NULL,50773,1);
INSERT INTO stanza VALUES('J421','2','主なくば無りょく, みちはながい,<br/>つかれてよわく, ためいきのみ;<br/>主を持てば,われ みちまよわず;<br/>主のみちのゆえ, 主はみちびく。<br/>',NULL,50774,2);
INSERT INTO stanza VALUES('J421','3','主なくば無りょく, あいする主よ;<br/>目には見えねど, 主はしたしい;<br/>あまきまじわり, 安そくなくば,<br/>見知らぬ地にて, 何たる孤どく。<br/>',NULL,50775,3);
INSERT INTO stanza VALUES('J421','4','主なくば無りょく, 霊のふかみの<br/>ひつようなにか, 知るものなし;<br/>こころのおくに 入り,なぐさめ,<br/>ささえるかたは, 主のほかなし。<br/>',NULL,50776,4);
INSERT INTO stanza VALUES('J421','5','主なくば無りょく, とき,みじかし,<br/>われもやがては この世を去る;<br/>されど,主とわに われはなれず,<br/>変わらぬあいを ほどこしたもう。<br/>',NULL,50777,5);
INSERT INTO stanza VALUES('J422','1','天にだれ持ち得よう？ 主のみ！主のみ！<br/>ただこのうたあり: 主為我！主為我！(主,われのため！)<br/>主,すでに血ながし, あがないじょう就して,<br/>かみと和解させた, 主為我！主為我！(主,われのため！)<br/>',NULL,50778,1);
INSERT INTO stanza VALUES('J422','2','自己あいもとめず, 我要主！我要主！(主,わがひつ要！)<br/>地のものしたわず, 我要主！我要主！(主,わがひつ要！)<br/>地のもの過ぎ去り, いきのようにはかない,<br/>わがよろこび永遠, 我要主！我要主！(主,わがひつ要！)<br/>',NULL,50779,2);
INSERT INTO stanza VALUES('J422','3','世のとみもとめず, 主為我！主為我！(主,われのため！)<br/>安らくをのぞまず, 主為我！主為我！(主,われのため！)<br/>いちじくの木,枯れ, ぶどう,オリブ実なし,<br/>うし,ひつじなくも, 主為我！主為我！(主,われのため！)<br/>',NULL,50780,3);
INSERT INTO stanza VALUES('J422','4','完ぜんに安そくす, 主為我！主為我！(主,われのため！)<br/>試れんをおそれず, 主為我！主為我！(主,われのため！)<br/>世の誘わくあるが, 主にちかづくならば,<br/>世のちから失せる, 主為我！主為我！(主,われのため！)<br/>',NULL,50781,4);
INSERT INTO stanza VALUES('J422','5','人生終わるときも, 我要主！我要主！(主,わがひつ要！)<br/>御手にまもられる, 我要主！我要主！(主,わがひつ要！)<br/>いたみがあるとも, ちからうしなうとも,<br/>われのうたごえは, 我要主！我要主！(主,わがひつ要！)<br/>',NULL,50782,5);
INSERT INTO stanza VALUES('J422','note','[主為我(ツーウェイウォー)：主はわたしのためである。]<br/>[我要主(ウォーヤォツー):わたしは主を求める。]<br/>',NULL,50783,6);
INSERT INTO stanza VALUES('J423','1','われは意志よわく, 　無りょくでのぞみなし；<br/>やしないみちびく主, 　なれにすべてたくす。<br/>',NULL,50784,1);
INSERT INTO stanza VALUES('J423','2','さい善尽くしても, 　いまだに失ぱいする;<br/>主よ,われつかまえて, 　めいれい,まもらせよ。<br/>',NULL,50785,2);
INSERT INTO stanza VALUES('J423','3','こころ,たかぶれば, 　たおれやすく危けん;<br/>なにもできぬわれは, 　ことごと,主がひつ要。<br/>',NULL,50786,3);
INSERT INTO stanza VALUES('J423','4','つよきすくいぬし, 　なが御かおもとめる;<br/>なれのめぐみのみが, 　よわきもののちから。<br/>',NULL,50787,4);
INSERT INTO stanza VALUES('J424','1','主のなかであんそくす！ これぞ真のあんそく！<br/>これ以がいつみびとに, なんののぞみありや？<br/>ながひかり,愛は, わが知恵,どう機,<br/>主の栄光の地位, 日々われをみちびく。<br/>',NULL,50788,1);
INSERT INTO stanza VALUES('J424','2','わがつみはおおくとも, めぐみ,さらにまさる;<br/>主はささげられて死に, さばきより解かれた;<br/>ことばはひかり, なが血はたから;<br/>われ,解放された, われ,かいふくされた。<br/>',NULL,50789,2);
INSERT INTO stanza VALUES('J424','3','温和な主よ,われを通し, もくてき果たしませ;<br/>御むねをおこなうため, われを主にささげる。<br/>われ,よわくとも, なれ,わがちから;<br/>主,ともにあれば, すべてに満ち足りる。<br/>',NULL,50790,3);
INSERT INTO stanza VALUES('J424','4','くろくも,おおうときに, なれはもっともちかい,<br/>わが信こうかたくして, わが霊をつよくする。<br/>みうでに抱かれ, 栄光のかお見る;<br/>なれは安そく所, サタンもさまたげ得ず。<br/>',NULL,50791,4);
INSERT INTO stanza VALUES('J424','5','主はわれをよろこばせ, われを解ほうされる;<br/>それゆえ,しい歌ささげ, えい遠にほめうたう。<br/>幸ふく,あい情が みなかれるとも,<br/>めぐみあるなら, 生きるも死ぬも良し。<br/>',NULL,50792,5);
INSERT INTO stanza VALUES('J425','1','つちのうつわに, たからをやどす;<br/>主をない容とす, われ,うつわなり。<br/>',NULL,50793,1);
INSERT INTO stanza VALUES('J425','2','主にふさわしく, かたどられたり;<br/>すべてを満たせ, キリストをもて。<br/>',NULL,50794,2);
INSERT INTO stanza VALUES('J425','3','そのれい,わが霊, ひとつとなりて,<br/>ちからある主は, わが実さいなり。<br/>',NULL,50795,3);
INSERT INTO stanza VALUES('J425','4','日ごとに調和し, あゆみととのえ,<br/>主はしみわたる, われのすべてに。<br/>',NULL,50796,4);
INSERT INTO stanza VALUES('J425','5','ひとに見えるよう, とうめいになせ;<br/>わが身をとおし, 主をひょう現する。<br/>',NULL,50797,5);
INSERT INTO stanza VALUES('J425','6','さらにくだきて, つちくれ変えよ;<br/>たからにかなう, かたちなるまで。<br/>',NULL,50798,6);
INSERT INTO stanza VALUES('J426','1','主とあゆめば,ことばのなか, えい光われを照らす;<br/>主の命れいにふく従すれば, わが霊は満たされる。<br/>',NULL,50799,1);
INSERT INTO stanza VALUES('J426','chorus','しんじて, 主にしたがう！<br/>主,よろこばすは, このほかなし！<br/>',NULL,50800,2);
INSERT INTO stanza VALUES('J426','2','地の暗こくに,おおわれない, 主の笑がおあるなら;<br/>うたがい,おそれ,なみだもなし, ただ信じ,したがえば。<br/>',NULL,50801,3);
INSERT INTO stanza VALUES('J426','3','おも荷,苦なん,主はかえりみ, はたらき,むくわれる;<br/>はじ,損しつは,さいわいとなる, ただ信じ,したがえば。<br/>',NULL,50802,4);
INSERT INTO stanza VALUES('J426','4','この身すべて,ささげて知る, 主の愛のうるわしさ;<br/>主のしい歌と,主のよろこび, したがうもののため。<br/>',NULL,50803,5);
INSERT INTO stanza VALUES('J426','5','ひかりのなか,あまき臨ざい, ともにあゆみ,享受す;<br/>主の要きゅうにおうじ,あゆむ; ただ信じてしたがう。<br/>',NULL,50804,6);
INSERT INTO stanza VALUES('J427','1','すくいぬしのこえ, いま,われは聞けり;<br/>われを呼びたもう 主にしたがいて行く。<br/>',NULL,50805,1);
INSERT INTO stanza VALUES('J427','chorus','わざわい,ふくにも, かならずしたがい,<br/>しりぞくことなく, 主にしたがいて行く。<br/>',NULL,50806,2);
INSERT INTO stanza VALUES('J427','2','主のまねくこえに, いま,われはこたえ,<br/>われ生きるかぎり, よろこびて,したがう。<br/>',NULL,50807,3);
INSERT INTO stanza VALUES('J427','3','したしきひと捨て, 世のさいわい捨て,<br/>われ生きるかぎり, よろこびて,したがう。<br/>',NULL,50808,4);
INSERT INTO stanza VALUES('J427','4','十字架を負いつつ, せまきみちを行く;<br/>われ生きるかぎり, よろこびて,したがう。<br/>',NULL,50809,5);
INSERT INTO stanza VALUES('J427','5','うしろ振り向かず, ひたすらまえへと,<br/>われ生きるかぎり, よろこびて,したがう。<br/>',NULL,50810,6);
INSERT INTO stanza VALUES('J428','1','主にしたがい行くは, 　何とあまいこと！<br/>主のあしあとを踏み, 　日々したがい行く。<br/>',NULL,50811,1);
INSERT INTO stanza VALUES('J428','chorus','いっ歩,いっ歩, 　せまきみちを,<br/>日ごと,日ごと, 　主にしたがう。<br/>',NULL,50812,2);
INSERT INTO stanza VALUES('J428','2','したがい,ひかり得て, 　真ひるにいたる;<br/>主のこえにしたがい, 　いつもしたがう。<br/>',NULL,50813,3);
INSERT INTO stanza VALUES('J428','chorus','いっ歩,いっ歩, 　 せまきみちを,<br/>いつも,いつも, 　 主にしたがう。<br/>',NULL,50814,4);
INSERT INTO stanza VALUES('J428','3','おそれずにしたがう, 　苦難があるとも;<br/>主のみちびきにより, 　いつもしたがう。<br/>',NULL,50815,5);
INSERT INTO stanza VALUES('J428','chorus','いっ歩,いっ歩, 　 せまきみちを,<br/>どこにいても, 　 主にしたがう。<br/>',NULL,50816,6);
INSERT INTO stanza VALUES('J428','4','主とともに前進して, 　おうこくを得る;<br/>主のもくひょう目ざし, 　せまきみち行く。<br/>',NULL,50817,7);
INSERT INTO stanza VALUES('J428','chorus','いっ歩,いっ歩, 　 せまきみちを,<br/>ずっと,ずっと, 　 主にしたがう。<br/>',NULL,50818,8);
INSERT INTO stanza VALUES('J429','1','「えい所より出て」, はずかしめ負う,<br/>主は門のそとで, くるしんだゆえ。<br/>',NULL,50819,1);
INSERT INTO stanza VALUES('J429','2','「えい所より出て」, 十字架あまんじる,<br/>主のせまきみち, われらもたどる。<br/>',NULL,50820,2);
INSERT INTO stanza VALUES('J429','3','「えい所より出て」, イェスにしたがう,<br/>御むねかえりみ, なさけ断ち切る。<br/>',NULL,50821,3);
INSERT INTO stanza VALUES('J429','4','「えい所より出て」, イェスにぞくする;<br/>しゅう教,組しきは もはやえんなし。<br/>',NULL,50822,4);
INSERT INTO stanza VALUES('J429','5','「えい所より出て」, このみちを行く;<br/>みち,きびしくも, 主あれば満ぞく。<br/>',NULL,50823,5);
INSERT INTO stanza VALUES('J429','6','「えい所より出て」, いま主とあゆむ;<br/>はげます笑がお, 臨在のなか住む。<br/>',NULL,50824,6);
INSERT INTO stanza VALUES('J429','7','「えい所より出て」, 主に会い,歓喜す;<br/>主によしとされ， 王こくにはいる。<br/>',NULL,50825,7);
INSERT INTO stanza VALUES('J430','1','かみは予知により, ひとを召し,御子に<br/>同けい化する。<br/>',NULL,50826,1);
INSERT INTO stanza VALUES('J430','chorus','同形化す,同形化す！ 御子のかたちへと,<br/>同けい化する。<br/>',NULL,50827,2);
INSERT INTO stanza VALUES('J430','2','聖れいはわがため うめきつついのる:<br/>同形化のため。<br/>',NULL,50828,3);
INSERT INTO stanza VALUES('J430','3','聖霊うちで運行し, そとで管理するは,<br/>同形化のため。<br/>',NULL,50829,4);
INSERT INTO stanza VALUES('J430','4','聖霊の管理,運こう, とりなしすべては,<br/>同形化のため。<br/>',NULL,50830,5);
INSERT INTO stanza VALUES('J430','5','万事えきとなるよう, ともにはたらくは,<br/>同形化のため。<br/>',NULL,50831,6);
INSERT INTO stanza VALUES('J430','6','多くの子得るため, かみは完せいする:<br/>同形化により。<br/>',NULL,50832,7);
INSERT INTO stanza VALUES('J430','7','栄光得させるため, かみは成就される:<br/>同形化により。<br/>',NULL,50833,8);
INSERT INTO stanza VALUES('J430','8','キリストの愛より はなすものはなし:<br/>同形化のため。<br/>',NULL,50834,9);
INSERT INTO stanza VALUES('J431','1','見よ,つちのうつわが, めぐみでかがやく;<br/>孤どくなこころへと, 御かお照らし出す。<br/>',NULL,50835,1);
INSERT INTO stanza VALUES('J431','2','主は天に満つひかり, 地に来てかがやく;<br/>その霊はひとに住み, いのち照らし込む。<br/>',NULL,50836,2);
INSERT INTO stanza VALUES('J431','3','天の栄光なるかみが, 地にあらわされる;<br/>あまさ,あいらしさを ひとにかん賞さす。<br/>',NULL,50837,3);
INSERT INTO stanza VALUES('J431','4','たからを持つゆえに, 栄こうと美を持つ;<br/>天の不変のたからは, 栄こうかがやかす。<br/>',NULL,50838,4);
INSERT INTO stanza VALUES('J431','5','よわくもろいうつわ, つねに御子を持ち,<br/>いま価値あるたから, 無限にひょう現する。<br/>',NULL,50839,5);
INSERT INTO stanza VALUES('J432','1','主こころ照らせば, われ,ふるきを脱ぎ,<br/>つちのうつわより, 主をあらわし出す。<br/>',NULL,50840,1);
INSERT INTO stanza VALUES('J432','chorus','1-3<br/>とうときたからは, たくえつのちから,<br/>このうつわにある。<br/>',NULL,50841,2);
INSERT INTO stanza VALUES('J432','chorus','4,5<br/>そとなるひと朽ち, うちなるひと日々<br/>あたらしくされる。<br/>',NULL,50842,3);
INSERT INTO stanza VALUES('J432','2','はくがいされても, われ,見捨てられず;<br/>投げたおされても, われ,ほろぼされず。<br/>',NULL,50843,4);
INSERT INTO stanza VALUES('J432','3','イェスの致死りょくは, いのちをあらわす;<br/>死がはたらくとき, いのち,あらわれる。<br/>',NULL,50844,5);
INSERT INTO stanza VALUES('J432','4','主は復かつすゆえ, われも復かつする;<br/>うちなるひと日々 あたらしくされる。<br/>',NULL,50845,6);
INSERT INTO stanza VALUES('J432','5','しばしの患なんは, おもき栄光得さす;<br/>見えるものでなく, 見えぬものに生く。<br/>',NULL,50846,7);
INSERT INTO stanza VALUES('J433','1','われにあらず,ただ主のみ, つたえられ,あがめられ,<br/>わがことば,振る舞いより, ただ主をあらわし出す。<br/>',NULL,50847,1);
INSERT INTO stanza VALUES('J433','chorus','なれのなかで自己を うしなわせよ！<br/>もはやわれならず, 主よ,生きませ！<br/>',NULL,50848,2);
INSERT INTO stanza VALUES('J433','2','われにあらず,ただ主のみ, 主はすべてのはじまり;<br/>主はきょうきゅうのみなもと, 主ははたらき,せいかつ。<br/>',NULL,50849,3);
INSERT INTO stanza VALUES('J433','3','主のみ,主のみ,ただ主のみ, もはや自己をあいさず;<br/>もはや自己そんちょうせず, もはや自己をかたらず。<br/>',NULL,50850,4);
INSERT INTO stanza VALUES('J433','4','われにあらず,ただ主のみ, われにほこるものなし;<br/>もはやわれにおも荷なく, わざわいをおそれない。<br/>',NULL,50851,5);
INSERT INTO stanza VALUES('J433','5','主のみ,主のみ,ただ主のみ, わが目は主のみ満ちる;<br/>主のみ,とわのかん謝受け, 主はわがすべてとなる。<br/>',NULL,50852,6);
INSERT INTO stanza VALUES('J434','1','天にたからがある, そは愛する御子;<br/>その豊富とうとさを だれも言い得ず。<br/>地にもたからがあり, かみのみ価値知る;<br/>キリストはそれを こころに啓示す。<br/>',NULL,50853,1);
INSERT INTO stanza VALUES('J434','2','ほのおのしたもて, かみ,くだり来て,<br/>こう価なたからで うつわを満たす。<br/>かみ,天の栄こうもて このうつわ満たし,<br/>愛の無限の豊富で, まんぞく得さす。<br/>',NULL,50854,2);
INSERT INTO stanza VALUES('J434','3','こころみあるとも 栄光の召し受く;<br/>ぶどうの木のえだ, ぶどうの木に住む。<br/>つちのうつわのゆえ 世びと,あなどるが,<br/>たからもて,かみの えい光あらわす。<br/>',NULL,50855,3);
INSERT INTO stanza VALUES('J434','4','われをからにして, 目立つことなく,<br/>かみのうつわとし えい光満たせや。<br/>なにもこのえい光を さまたげられない,<br/>主に満たされつつ, 主を告げ知らす。<br/>',NULL,50856,4);
INSERT INTO stanza VALUES('J435','1','アダムにてつみと死受け, キリストにて義と生,継ぐ;<br/>にくにありアダム表現し, 霊にありキリスト表現す。<br/>',NULL,50857,1);
INSERT INTO stanza VALUES('J435','2','アダムのなかにあるひと, つみおかさずもつみびと;<br/>キリストのなかにあれば, 義のこう為なくとも義人。<br/>',NULL,50858,2);
INSERT INTO stanza VALUES('J435','3','にくにあると,ひとりでに, アダムの性しつあらわる;<br/>霊にあると,ごく自ぜんに, 主のえいこう生かし出す。<br/>',NULL,50859,3);
INSERT INTO stanza VALUES('J435','4','主ともに死に,アダム去り, 主ともに生き,いのち得る;<br/>にくに付けば,旧そうぞう, 霊に付けば,せいあらわす。<br/>',NULL,50860,4);
INSERT INTO stanza VALUES('J435','5','れいに付くはかみのみち, 霊に付くほかすくいなし;<br/>れいに付き,情よくに勝ち, つみの法そくをはなれる。<br/>',NULL,50861,5);
INSERT INTO stanza VALUES('J435','6','霊に付くとき十字架知り, 霊に付くとき復かつ知る;<br/>霊に付けばキリスト生き, れいに付けばえんじゅくす。<br/>',NULL,50862,6);
INSERT INTO stanza VALUES('J435','7','霊にあれば主わがいのち, 霊にあれば大のうを得る;<br/>霊にあればせいとされて, けいけんは実さいとなる。<br/>',NULL,50863,7);
INSERT INTO stanza VALUES('J436','1','主,わがいのち, わがへい安,<br/>れいのなかで, けつごうす。<br/>',NULL,50864,1);
INSERT INTO stanza VALUES('J436','chorus','れいにあゆみ, 主にあり生き,<br/>いのち,へい安, きょう受する。<br/>',NULL,50865,2);
INSERT INTO stanza VALUES('J436','2','われ,主のもの, しばられず;<br/>いのちののり, かいほうす。<br/>',NULL,50866,3);
INSERT INTO stanza VALUES('J436','3','にくに付かず れいに付き,<br/>ひたすら霊に したがわん。<br/>',NULL,50867,4);
INSERT INTO stanza VALUES('J436','4','すべて超える かみの義は,<br/>律ぽうまもる 義にまさる。<br/>',NULL,50868,5);
INSERT INTO stanza VALUES('J436','5','われのれいに れいが住み,<br/>死のからだも 生かされる。<br/>',NULL,50869,6);
INSERT INTO stanza VALUES('J436','6','ふたつれいは ひとつれい，<br/>「かみの子ら」と あかしする。<br/>',NULL,50870,7);
INSERT INTO stanza VALUES('J436','note','[2　いのちののり――命の法則]<br/>',NULL,50871,8);
INSERT INTO stanza VALUES('J437','1','この世を捨て去り, キリストもとめる;<br/>すべてはむなしい, かれこそまんぞく。<br/>',NULL,50872,1);
INSERT INTO stanza VALUES('J437','chorus','ゆたかなキリスト, ことばに尽くせず！<br/>すべてにまされる, あまさをあじわう。<br/>',NULL,50873,2);
INSERT INTO stanza VALUES('J437','2','キリスト以がいに, もとめるものなし,<br/>世を得てむなしい, 主を得てまんぞく。<br/>',NULL,50874,3);
INSERT INTO stanza VALUES('J437','3','あらゆるとみ持つ 巨だいなこの世も,<br/>ちいさいこころの むなしさ満たさず。<br/>',NULL,50875,4);
INSERT INTO stanza VALUES('J437','4','キリストわがうた, よろこび満ち満つ;<br/>たからはキリスト, われらは主に住む！<br/>',NULL,50876,5);
INSERT INTO stanza VALUES('J438','1','主イェスをえらび, わが世界とす;<br/>主のあいは十分, われを満たす;<br/>スカルのみずは かわき止めず;<br/>主よ,われうつわ, 主,入れる。<br/>',NULL,50877,1);
INSERT INTO stanza VALUES('J438','chorus','イェス,イェス, 主イェスをえらび,<br/>すべてのあまさの みなもとに住む;<br/>イェス,イェス, イェスは満ぞく,<br/>かわきを消し去り, 「われ」しずめる。<br/>',NULL,50878,2);
INSERT INTO stanza VALUES('J438','2','主イェスをえらび, よろこびとす;<br/>苦つうあるとも, うたながれる。<br/>ただ主があれば, 理由なくても,<br/>よろこびのこえ, わき出る。<br/>',NULL,50879,3);
INSERT INTO stanza VALUES('J438','3','主イェスをえらび, のぞみとする;<br/>たまわる嗣業は なんとゆたか;<br/>わがすくいぬし, 主こそたから<br/>主イェスを得るは さいこう。<br/>',NULL,50880,4);
INSERT INTO stanza VALUES('J438','4','主イェスをえらび, わが主とする;<br/>言い知れぬ愛に, われ屈ぷくす。<br/>なにももとめず, すべてささげ,<br/>主のよろこびを もとめる。<br/>',NULL,50881,5);
INSERT INTO stanza VALUES('J439','1','こころよろこび,うたう, 主はわがいのち,へい安;<br/>われの前途,なれによる, ちちがみはわれのため。<br/>',NULL,50882,1);
INSERT INTO stanza VALUES('J439','chorus','すべては主による！ すべてのこと,主による！<br/>',NULL,50883,2);
INSERT INTO stanza VALUES('J439','2','かつて,われ死をおそれ, 良きわざで自己かざり,<br/>ばつ,のがれようとしたが, すくいはただ主による。<br/>',NULL,50884,3);
INSERT INTO stanza VALUES('J439','3','やがてつみびとは泣く, されど召かい上げられ,<br/>なれのとうとい血により, ハデスのちからに勝つ。<br/>',NULL,50885,4);
INSERT INTO stanza VALUES('J439','4','小ひつじはつみにない, いかりのさかずき飲む;<br/>さばきは去り,死もなく, われをすくいて生かす。<br/>',NULL,50886,5);
INSERT INTO stanza VALUES('J439','5','われをまき場に伏させ, かみ,最高のものあとう;<br/>いまながむねに抱かれ, まじわり,あいあじわう。<br/>',NULL,50887,6);
INSERT INTO stanza VALUES('J439','6','そしり,嘲しょうに遭うも, なお信じて,主をあおぐ;<br/>くるしみを受けるとも, なおよろこべるように。<br/>',NULL,50888,7);
INSERT INTO stanza VALUES('J439','7','われは名せいをこばみ, 火とふかきみずを経る;<br/>主の苦なんにあずかり, 御名ゆえ,じゅんきょうする！<br/>',NULL,50889,8);
INSERT INTO stanza VALUES('J439','8','われ,主のまえに立つ日, 十字架の主がわがうた;<br/>天を捨て,くるしみ受け, いのち捨て,血をながす。<br/>',NULL,50890,9);
INSERT INTO stanza VALUES('J439','chorus','すべてはわがため！ すべてのこと,わがため！<br/>',NULL,50891,10);
INSERT INTO stanza VALUES('J440','1','日に焼け,くろいけれど, ひかりの子はうつくしい;<br/>おく義てきなよろこび, 栄こうの主はたまわる;<br/>ひとが想像もせず, 　触れもしないこと;<br/>聖徒らはひかりに住み, かくされた栄光得る。<br/>',NULL,50892,1);
INSERT INTO stanza VALUES('J440','2','ひとの見かたによれば, 聖徒もアダムより出て,<br/>つみびととおなじように, そとなるひつ要がある,<br/>生かつの方ほうも, 　寝起き,みなおなじ。<br/>それは,ひと,とうとぶこと, 聖徒に軽視さすため。<br/>',NULL,50893,2);
INSERT INTO stanza VALUES('J440','3','聖徒,かみのいのち持ち, ことばで再せいされた;<br/>かみの愛で燃やされた, 新エﾙサレﾑにぞくする;<br/>ひかりの聖徒らは, 　あまきうた,うたう,<br/>最こうのかみをたたえ, すばらしいメロディ出す。<br/>',NULL,50894,3);
INSERT INTO stanza VALUES('J440','4','地にあるが,てんに住む; よわいようで,けん威持つ;<br/>四ほうからのあっぱく, されど,窮することなし;<br/>投げたおされても, 　ほろびることなし;<br/>死のかげを行くときも, 無限のいのちを生く。<br/>',NULL,50895,4);
INSERT INTO stanza VALUES('J440','5','いのちなる主あらわれ, 栄こうの王が来るとき,<br/>かくされてきたえい光, かがやいて,ひとは見る。<br/>おお！ひかりかがやき, 　ともに上げられて,<br/>かくされてきたひかり, 聖徒らよりかがやく。<br/>',NULL,50896,5);
INSERT INTO stanza VALUES('J441','1','わがかみ,わがあい, わが分けまえ;<br/>なれのほか天地に わがもとむもの,まったくなし。<br/>',NULL,50897,1);
INSERT INTO stanza VALUES('J441','2','てんも地もすべて, むなしさのみ！<br/>なれのようしたうに あたいするもの,てん地になし。<br/>',NULL,50898,2);
INSERT INTO stanza VALUES('J441','3','なれはわがたから, いのち,住まい;<br/>他のもの受けても, わがかみでない,わが主でない。<br/>',NULL,50899,3);
INSERT INTO stanza VALUES('J441','4','かがやくざいほう, なんとむなしい！<br/>なれにくらべれば, おもちゃのようで,たよりならず。<br/>',NULL,50900,4);
INSERT INTO stanza VALUES('J441','5','たとえ全地を得て, ほしを得ても,<br/>なれともになくば, あわれのきわみ！なれはすべて。<br/>',NULL,50901,5);
INSERT INTO stanza VALUES('J441','6','ばくだいなとみを, ひとはもとむ,<br/>されど,なが同ざい, われのまんぞく,なれをもとむ。<br/>',NULL,50902,6);
INSERT INTO stanza VALUES('J442','1','サタンに捕らわれ, 死の地で奴隷であった;<br/>かみは愛のゆえに, キリストにもどす。<br/>',NULL,50903,1);
INSERT INTO stanza VALUES('J442','chorus','めぐみで再せいし, あたらしい霊あたえ,<br/>主の霊を霊に置き, 主の性しつ持たす。<br/>',NULL,50904,2);
INSERT INTO stanza VALUES('J442','2','きよいみずそそぎ, ぐうぞうよりきよめ,<br/>にくのこころとし, あたらしいひととす。<br/>',NULL,50905,3);
INSERT INTO stanza VALUES('J442','3','かみはわがいのち, わがせいしつとなる;<br/>神聖にふさわしく, 主の命令に生きる。<br/>',NULL,50906,4);
INSERT INTO stanza VALUES('J442','4','われはかみのたみ, かみと真にまじわる;<br/>かみ,わがしゅくふく, 受くべきわけまえ。<br/>',NULL,50907,5);
INSERT INTO stanza VALUES('J442','5','キリスト,わが住まい, その豊富きょう受する;<br/>主はわがしょくもつ, えい遠に飽き足る。<br/>',NULL,50908,6);
INSERT INTO stanza VALUES('J443','1','何という栄光,神聖！ かみ,永遠のいのち！<br/>豊富,無限,のうりょく, 堅固,慈あい,光みょう！<br/>その本しつと豊富, いのちのなかに。<br/>',NULL,50909,1);
INSERT INTO stanza VALUES('J443','2','何という慈愛,めぐみ！ かみ,ひとのいのち！<br/>ひとにはいるため, ひとの霊を創造す。<br/>ひとが受け入れて, かみはよろこぶ。<br/>',NULL,50910,2);
INSERT INTO stanza VALUES('J443','3','何というあい,めぐみ！ ながれ出るいのち！<br/>もはやかくされず, ひとにあらわれる;<br/>受にくし霊と成り, いのちあたえる。<br/>',NULL,50911,3);
INSERT INTO stanza VALUES('J443','4','何というしたしさ！ キリストはいのち！<br/>かれはかみの化身, にくにてあらわれ,<br/>死と復かつ経過し, ひとへとはいる。<br/>',NULL,50912,4);
INSERT INTO stanza VALUES('J443','5','何という不思議よ！ そのれいはいのち！<br/>かれはべつの化身, 実さいのあらわれ;<br/>ひとの霊にはいり, いのちあたえる。<br/>',NULL,50913,5);
INSERT INTO stanza VALUES('J443','6','さんいちのかみは, わがいのちとなる！<br/>ちちはながれ,子に, 子はながれて霊に;<br/>霊はひとにながれ, いのちあたえる。<br/>',NULL,50914,6);
INSERT INTO stanza VALUES('J443','7','何というじっさい！ かみはながれ出て,<br/>わがうちにながれ, われとけつ合する。<br/>ハレルヤ,ハレルヤ, かみ,わがいのち！<br/>',NULL,50915,7);
INSERT INTO stanza VALUES('J444','1','主はわれのぼく者, とぼしきことなし;<br/>かれはわれのもの, われはかれのもの。<br/>',NULL,50916,1);
INSERT INTO stanza VALUES('J444','2','みどりのまき場で, 満ち足り,よろこぶ;<br/>ながれのほとりで, まじわり,やすらぐ。<br/>',NULL,50917,2);
INSERT INTO stanza VALUES('J444','3','まよえど,もどして, こころ支はいする;<br/>揺れうごくわれを, 御名ゆえ,みちびく。<br/>',NULL,50918,3);
INSERT INTO stanza VALUES('J444','4','むちでささえられ, つえでみちびかれ,<br/>主のどう在満ちて, 主とともにあゆむ。<br/>',NULL,50919,4);
INSERT INTO stanza VALUES('J444','5','わがてきのまえで わがため宴もうけ,<br/>あぶらそそがれて, さかずきあふれる。<br/>',NULL,50920,5);
INSERT INTO stanza VALUES('J444','6','あまき不思議な愛, とわに変わらぬ愛,<br/>世にあるかぎりは, 賛美,増しくわわる。<br/>',NULL,50921,6);
INSERT INTO stanza VALUES('J445','1','かみよ,なれおもえば, 　 引き寄せられ,<br/>この世の吸引りょくは, 　もはやなくなる。<br/>',NULL,50922,1);
INSERT INTO stanza VALUES('J445','2','ほろびまぬかれても, 　 まだ不じゅう分;<br/>全体てきなすくいを, 　われはもとめる。<br/>',NULL,50923,2);
INSERT INTO stanza VALUES('J445','3','かみはひとの住まい, 　 ながみち行く;<br/>なれのほか,こころを 　満たすものなし。<br/>',NULL,50924,3);
INSERT INTO stanza VALUES('J445','4','こころのふかみより, 　 御名を呼べば,<br/>この世のゆうわくは, 　たちまち消える。<br/>',NULL,50925,4);
INSERT INTO stanza VALUES('J445','5','依りたのむこころと 　 あおぐ目にて,<br/>かみのみちびき得て, 　ご自身をしたう。<br/>',NULL,50926,5);
INSERT INTO stanza VALUES('J445','6','ながみちしたうこと, 　 何とすくない！<br/>こころかみに向けて, 　すすませたまえ！<br/>',NULL,50927,6);
INSERT INTO stanza VALUES('J445','7','つみに打ち勝つのは, 　 とう然のこと！<br/>なお,たかきを目ざし, 　主の愛もとめる。<br/>',NULL,50928,7);
INSERT INTO stanza VALUES('J445','8','愛にあり完全なみち, 　われはあゆむ;<br/>主をたよりとすれば, 　すべてはやすし。<br/>',NULL,50929,8);
INSERT INTO stanza VALUES('J445','9','良心を研ぎ澄まして, 　 うちにもどり,<br/>あぶらにしたがうは, 　円じゅくの秘けつ。<br/>',NULL,50930,9);
INSERT INTO stanza VALUES('J446','1','わが住まいはかみご自身, 主がここにみちびいて,<br/>われに主のみちあゆませ, 至せい所に住まわせる。<br/>神せいな栄こうのいえ, かみ,ひとともに住み合う！<br/>',NULL,50931,1);
INSERT INTO stanza VALUES('J446','2','真のみちたずねもとめて, にち夜あるきつづけた;<br/>何のせい果,しん歩もなく, わが努りょくみな失ぱい,<br/>いまや知る,主こそみち, 主にてかみのなかに住む。<br/>',NULL,50932,2);
INSERT INTO stanza VALUES('J446','3','けん固で不思議な住まい！ かみとひと,ともに住む。<br/>神せいなえいこうのいえ, かみ,ひと相互の住まい;<br/>栄光のいえでやすらぎ, 主をひとに分けあたえる。<br/>',NULL,50933,3);
INSERT INTO stanza VALUES('J447','1','何というおく義,ちち,子,霊, 三かく位,本しつひとつ;<br/>このかみわが霊にはいり, わがすべてのきょうきゅう。<br/>',NULL,50934,1);
INSERT INTO stanza VALUES('J447','chorus','さんいちのかみはいま, われらのすべてぞ！<br/>神聖な成分,無尽蔵なり, 何という不思議よ！<br/>',NULL,50935,2);
INSERT INTO stanza VALUES('J447','2','ゆたかなみなもと,ちちは, ひとにエンジｮイさせるため,<br/>その豊富われにぶん与す; とわにつかい尽くせじ！<br/>',NULL,50936,3);
INSERT INTO stanza VALUES('J447','3','くすしき,子はちちの表現, にく体もてともに住む;<br/>十字架のあがないの効果, つみびとかみと連合す！<br/>',NULL,50937,4);
INSERT INTO stanza VALUES('J447','4','うるわしい,霊は子の変容ぞ, わが霊に入りて供給す;<br/>霊は霊に触れてちょう和し, ふたつ霊いまやひとつ。<br/>',NULL,50938,5);
INSERT INTO stanza VALUES('J447','5','実際なり,かみのすべては, 霊にあり日々経験さす;<br/>驚異なり,いのち性しつは, かみとすこしも差なし。<br/>',NULL,50939,6);
INSERT INTO stanza VALUES('J448','1','かみよ,おく義を賛美す, ついになれに触れる;<br/>かつてはちかづけぬわれも, いまは霊にてしたしむ。<br/>',NULL,50940,1);
INSERT INTO stanza VALUES('J448','2','ちちと子とせいれいは, われのいのちとなる;<br/>わがうちできょうきゅうとなり, かみのせいしつ得さす。<br/>',NULL,50941,2);
INSERT INTO stanza VALUES('J448','3','ちちは子のうちにあり, 子はそのれいと成り,<br/>霊はかぜのようわれにのぞみ, このおく義,経験させる。<br/>',NULL,50942,3);
INSERT INTO stanza VALUES('J448','4','ちちのすべて子にあり, 子の豊富,れいにあり,<br/>霊はわがうちにはいり来て, われのしゅくふくとなる。<br/>',NULL,50943,4);
INSERT INTO stanza VALUES('J448','5','ちち,みなもと,子は表現, 霊はそれをもたらす;<br/>ちちは子に,子はれいにあり, わがうちにはいられる。<br/>',NULL,50944,5);
INSERT INTO stanza VALUES('J448','6','ちちは子を第いちとし, 子はちちかしらとす;<br/>霊は子にえい光得さすため, わがこころに啓示する。<br/>',NULL,50945,6);
INSERT INTO stanza VALUES('J448','7','霊はなが最後のかたち, わが霊にはいり込む;<br/>主のほう富を享受するため, われ, 霊にて霊に触れる。<br/>',NULL,50946,7);
INSERT INTO stanza VALUES('J448','8','れいのなかでまじわり, 礼拝し,賛美し,いのる;<br/>れいのなかで聖れいに触れ, なが供きゅうを享受する。<br/>',NULL,50947,8);
INSERT INTO stanza VALUES('J449','1','霊はかみの本しつ, また神せいな「である」；<br/>霊にてかみに触れ, ほう富を享受する。<br/>',NULL,50948,1);
INSERT INTO stanza VALUES('J449','2','霊はさい深の部分， もっとも真なる部ぶん;<br/>真のひとは霊にて かみに触れるひと。<br/>',NULL,50949,2);
INSERT INTO stanza VALUES('J449','3','霊もて霊を拝して, 主を供給され,享受す;<br/>主の霊はわが霊に はいり,けつ合する。<br/>',NULL,50950,3);
INSERT INTO stanza VALUES('J449','4','霊と霊は呼応して, ふたつ霊は調和する;<br/>れいはれいに住む, その霊わが生かつ。<br/>',NULL,50951,4);
INSERT INTO stanza VALUES('J449','5','れいはれいに触れ, かみの豊富,享受する;<br/>霊と霊ともにあり, かみを礼はいする。<br/>',NULL,50952,5);
INSERT INTO stanza VALUES('J449','6','集会とまじわりで, ひとを霊にみちびく;<br/>みないのりに変え, れいにて呼応する。<br/>',NULL,50953,6);
INSERT INTO stanza VALUES('J449','7','霊でいのり,奉仕し, 神聖ないのちに触れ,<br/>霊で成長,霊で建造, 主の栄光かがやく。<br/>',NULL,50954,7);
INSERT INTO stanza VALUES('J449','8','われを霊にもどし, 主に触れるをねがう;<br/>なが霊とわが霊は, とわにながれ出る。<br/>',NULL,50955,8);
INSERT INTO stanza VALUES('J450','1','ひとに対すかみのストーリー, みな霊にある;<br/>ひとはかみの本しつを, 霊で経験する。<br/>',NULL,50956,1);
INSERT INTO stanza VALUES('J450','chorus','霊は霊を生み, 霊は霊を拝す;<br/>霊,ことばとなり, 生けるみずはながる。<br/>',NULL,50957,2);
INSERT INTO stanza VALUES('J450','2','かみはひとの霊つくり, 霊で霊,拝さす;<br/>いのちとし,かみを得て, ひと,供給受く。<br/>',NULL,50958,3);
INSERT INTO stanza VALUES('J450','3','霊もてひとの霊に入り, 再せいさせる;<br/>霊にあり,かみと交流し, ゆたか享受す。<br/>',NULL,50959,4);
INSERT INTO stanza VALUES('J450','4','霊のなか満たし,そそぎ, つくり変える;<br/>霊から全身まですべて しみ込ませる。<br/>',NULL,50960,5);
INSERT INTO stanza VALUES('J450','5','霊のなか,とけ合い調和し, かたち変えられ,<br/>かみの成分くわえられ, かみを表現す。<br/>',NULL,50961,6);
INSERT INTO stanza VALUES('J450','6','かみのすべてのゆたか, みな霊にある;<br/>つねに霊でかみ,呼吸し, 経験し,享受す。<br/>',NULL,50962,7);
INSERT INTO stanza VALUES('J451','1','かみのものすべて, われの供給,<br/>かみと混ざるのは, 霊のなか。<br/>',NULL,50963,1);
INSERT INTO stanza VALUES('J451','chorus','ちちのすべて,子のゆたかさは,<br/>霊にあるゆえ,霊をかつ用す。<br/>',NULL,50964,2);
INSERT INTO stanza VALUES('J451','2','かみの本しつ,豊富 あたえらる;<br/>かみに触れるのは, 霊のなか。<br/>',NULL,50965,3);
INSERT INTO stanza VALUES('J451','3','知せいでかみ知り 霊で触れる;<br/>まんぞく得るため, 霊生かす。<br/>',NULL,50966,4);
INSERT INTO stanza VALUES('J451','4','あたまをもちいず, 霊かつ用す;<br/>聖書いのり読みし, 呼応する。<br/>',NULL,50967,5);
INSERT INTO stanza VALUES('J451','5','何たるほう富,栄光, 霊で触れる！<br/>かみのものすべて, わがもの。<br/>',NULL,50968,6);
INSERT INTO stanza VALUES('J452','1','聖れいはかみの伝たつ, かみは霊を通しはいり,<br/>キリストのなかで 霊により経験される。<br/>',NULL,50969,1);
INSERT INTO stanza VALUES('J452','2','ちちなるかみ,みなもと, 子なるかみ,そのひょう現;<br/>霊はひとにはいり, かみのすべて得さす。<br/>',NULL,50970,2);
INSERT INTO stanza VALUES('J452','3','ちかづきがたきちちは, 子にてひとにあらわれ,<br/>霊にて伝たつされ, ひとは霊で受け継ぐ。<br/>',NULL,50971,3);
INSERT INTO stanza VALUES('J452','4','ちちは子のなかで来て, 子はれいと成り,はいる;<br/>ちち,子,霊,三いちは, いまやわが霊に住む。<br/>',NULL,50972,4);
INSERT INTO stanza VALUES('J452','5','御ちちは御子のなかに 具たい化と表現を得る;<br/>れいは子の実さい, われにめぐみ得さす。<br/>',NULL,50973,5);
INSERT INTO stanza VALUES('J452','6','ちちなるかみのあいが, 御子にてめぐみとなり,<br/>霊にて伝たつされ, かみの豊満にいたる。<br/>',NULL,50974,6);
INSERT INTO stanza VALUES('J453','1','さらになれと したしむ;<br/>十字架のみち, われは行く,<br/>われはうたう: なおしたしむ,<br/>主としたしむ, 主したしむ。<br/>',NULL,50975,1);
INSERT INTO stanza VALUES('J453','2','さすらい行き, 日しずみ,<br/>いしまくらで ねむるとも,<br/>ゆめのなかで なおもねがう,<br/>主としたしむ, 主したしむ。<br/>',NULL,50976,2);
INSERT INTO stanza VALUES('J453','3','天につうじる はしごを,<br/>御つかいらは 行き来する;<br/>出来ごとみな めぐみによる,<br/>主としたしむ, 主したしむ。<br/>',NULL,50977,3);
INSERT INTO stanza VALUES('J453','4','ゆめより覚め, 感謝満つ;<br/>まくらとした いし立てる;<br/>かならず主の みやを建てよう。<br/>主としたしむ, 主したしむ。<br/>',NULL,50978,4);
INSERT INTO stanza VALUES('J453','5','よろこび去り 飛び立ち,<br/>天地はすべて 過ぎゆくも,<br/>なおもうたう: われしたしむ,<br/>主としたしむ, 主したしむ。<br/>',NULL,50979,5);
INSERT INTO stanza VALUES('J454','1','カルバﾘやまのふるき十字架, はじと苦難のしるし;<br/>十字架を愛す,われはあいす, 主わがため死んだゆえ。<br/>',NULL,50980,1);
INSERT INTO stanza VALUES('J454','chorus','あの十字架をとうとぶ, あの十字架をたもつ;<br/>かの日この十字架が, わがかんむりとなる。<br/>',NULL,50981,2);
INSERT INTO stanza VALUES('J454','2','ひと軽視したあの十字架は, いまわれを引き寄す;<br/>小ひつじ来て,十字架を負い, ゴルゴタへ行かれた。<br/>',NULL,50982,3);
INSERT INTO stanza VALUES('J454','3','あの十字架に血のあとあり, わが目にはよろこび！<br/>あの十字架で主はくるしみ, ゆるしと聖をあとう。<br/>',NULL,50983,4);
INSERT INTO stanza VALUES('J454','4','あの十字架にしたがい行き, そしりをあまんじ受く;<br/>主が再らいし,まみえるとき, 主の栄こう享受する。<br/>',NULL,50984,5);
INSERT INTO stanza VALUES('J455','1','十字架はわがほこり, 永遠に存ぞくす;<br/>神聖な功せきはかがやく, 十字架,その中心。<br/>',NULL,50985,1);
INSERT INTO stanza VALUES('J455','2','患難,試練に会うとき, われおそれるも,<br/>主の十字架,われを捨てず, 見よ！歓喜と平安。<br/>',NULL,50986,2);
INSERT INTO stanza VALUES('J455','3','主は愛とひかりもて, わがみち照らす,<br/>主の十字架,ひかりはなち, われ,かがやかす。<br/>',NULL,50987,3);
INSERT INTO stanza VALUES('J455','4','苦もらくも,十字架は われを聖とする,<br/>ここにて平あんふかまり, よろこび,永遠に。<br/>',NULL,50988,4);
INSERT INTO stanza VALUES('J455','5','十字架はわがほこり, 永遠に存ぞくす;<br/>神聖な功せきはかがやく, 十字架,その中心。<br/>',NULL,50989,5);
INSERT INTO stanza VALUES('J456','1','じゅう字架に行き, いずみを得る！<br/>いやしのみずは, カﾙバリにわく。<br/>',NULL,50990,1);
INSERT INTO stanza VALUES('J456','chorus','十字架！十字架！ とわのほこり！<br/>主のあがないは, とわの信らい！<br/>',NULL,50991,2);
INSERT INTO stanza VALUES('J456','2','じゅう字架に行き, 愛,ゆるし受く;<br/>明けのみょうじょう, われを照らす。<br/>',NULL,50992,3);
INSERT INTO stanza VALUES('J456','3','じゅう字架に行き， その価値知り，<br/>十字架のもとで， つねにすすむ。<br/>',NULL,50993,4);
INSERT INTO stanza VALUES('J456','4','じゅう字架に行き, 絶えずあおぎ,<br/>引き上げられて, 御かおを見る。<br/>',NULL,50994,5);
INSERT INTO stanza VALUES('J456','note','［2節の「明けの明星」はキリストを指す。］<br/>',NULL,50995,6);
INSERT INTO stanza VALUES('J457','1','十字架しょう利得た, ハレルヤ！ハレルヤ！<br/>永遠にてきのぞく, ハレルヤ！ハレルヤ！<br/>この世,荒れくるい, にくはつよくとも,<br/>じゅう字架はわれを 勝ちほこらせる！<br/>',NULL,50996,1);
INSERT INTO stanza VALUES('J457','chorus','ハレルヤ！ハレルヤ！ キリストしょう利得た！<br/>ハレルヤ！ハレルヤ！ じゅう字架ほこる！<br/>',NULL,50997,2);
INSERT INTO stanza VALUES('J457','2','十字架,わがいのち, ハレルヤ！ハレルヤ！<br/>十字架けん威あとう, ハレルヤ！ハレルヤ！<br/>にん情,自己に勝つ, 世の勢りょくに勝つ,<br/>じゅう字架はわれに しょう利を得さす！<br/>',NULL,50998,3);
INSERT INTO stanza VALUES('J457','3','十字架はわがはた, ハレルヤ！ハレルヤ！<br/>永遠にてん覧する, ハレルヤ！ハレルヤ！<br/>よわさ,つよくされ, うち,たかめられる,<br/>じゅう字架はわれに かい放を得さす！<br/>',NULL,50999,4);
INSERT INTO stanza VALUES('J458','1','オリブしぼられて, あぶらとなる;<br/>ぶどうもつぶされ, 良きさけとなる;<br/>こうりょう焼かれて, かおりはなつ;<br/>さればわれいかに くだかるべきや？<br/>',NULL,51000,1);
INSERT INTO stanza VALUES('J458','chorus','打げきみな, えきとなし,<br/>取りしものに代え, 主はご自身あとう。<br/>',NULL,51001,2);
INSERT INTO stanza VALUES('J458','2','主よ,こころの弦を かきならせや;<br/>主のしらべあれば, すべて耐え得る;<br/>たおれるたびごと, ながあい知る;<br/>なれちかくませば, 損しつおそれじ。<br/>',NULL,51002,3);
INSERT INTO stanza VALUES('J458','3','あいのたい処をば, つらくかんじ,<br/>自我に捕らわれし われ,恥じるのみ,<br/>主よ,わがおもいを かえりみずに,<br/>主のよろこぶまま, 御むね成しませ。<br/>',NULL,51003,4);
INSERT INTO stanza VALUES('J458','4','主とわれの苦らく, 合わざるとき,<br/>主よ,よろこびませ, われくびき負わん;<br/>主のよろこび,栄光, ねがうわれは,<br/>十字架とだい価を, いかでこばむや。<br/>',NULL,51004,5);
INSERT INTO stanza VALUES('J458','5','賛美せよ,賛美せよ, 賛美はあまし;<br/>あまさはいや増す, なみだの賛美に;<br/>主,わがたからゆえ, ただいのりせん:<br/>われおとろえゆき, 主いよよ増せと。<br/>',NULL,51005,6);
INSERT INTO stanza VALUES('J459','1','じゅう字架がおもいほど, さらにかみにしたしめる;<br/>じゅう字架をになうとき, やみのおう,踏みつける。<br/>十字架上にあるひとは, 損しつ,よろこびとす。<br/>',NULL,51006,1);
INSERT INTO stanza VALUES('J459','2','じゅう字架がおもいほど, 聖徒はかみに成就される。<br/>そそぐなみだないなら, そのにある木は枯れる！<br/>金は火にて精錬される, 苦難はわれを聖とす。<br/>',NULL,51007,2);
INSERT INTO stanza VALUES('J459','3','じゅう字架がおもいほど, 信仰つよくされ,根を張る;<br/>ぶどうの実,つぶされて, あまい果じゅうをながす;<br/>苦難により,きずを受け, 真珠はせいちょうする。<br/>',NULL,51008,3);
INSERT INTO stanza VALUES('J460','1','損しつを経て得る; 十字架経て生きる;<br/>むぎは地に落ちて, おおくの実むすぶ;<br/>完ぜんにくだかれ, ひゃくばい実むすぶ。<br/>完ぜんにくだかれ, ひゃくばい実むすぶ。<br/>',NULL,51009,1);
INSERT INTO stanza VALUES('J460','2','捕らえようとすると, それに捕らえられ,<br/>なにかに向くなら, それがひと,しばる;<br/>財さんも健こうも, 愛せば,かせとなる。<br/>財さんも健こうも, 愛せば,かせとなる。<br/>',NULL,51010,2);
INSERT INTO stanza VALUES('J460','3','こくもつじゅくして, 収かくされるのは,<br/>せい徒のかくれた 犠せいと死のゆえ;<br/>われらが収かくを きょう受できるのは,<br/>だれかがいのって, 労苦していたゆえ。<br/>',NULL,51011,3);
INSERT INTO stanza VALUES('J461','1','十字架は苦つう得るのみか？<br/>いな！負えばすべて死すべし！<br/>十字架とはほふることなり;<br/>十字架通れば自己は終わる。<br/>',NULL,51012,1);
INSERT INTO stanza VALUES('J461','2','十字架つねにひとをほふる;<br/>こくなようで,高貴なすくい;<br/>十字架,避ければいのちなく,<br/>いのちなくば主あらわれず。<br/>',NULL,51013,2);
INSERT INTO stanza VALUES('J461','3','十字架はごけいかくを成し,<br/>ふるきいのちをたい処する;<br/>十字架が自己をくだくとき,<br/>主の御むねさかえ,勝利得る。<br/>',NULL,51014,3);
INSERT INTO stanza VALUES('J462','1','十字架のみちで主に すべてささげる,<br/>さい壇にいけにえとして 置けば火はくだる。<br/>',NULL,51015,1);
INSERT INTO stanza VALUES('J462','chorus','なれはすでに主にすべてを ささげたひとである！<br/>日々十字架のみち行くか？ 　忠じつであるか？<br/>',NULL,51016,2);
INSERT INTO stanza VALUES('J462','2','「すべてをささげる」と 言うをねがうが,<br/>ぜん途はおもき十字架と, 困難なあゆみなり。<br/>',NULL,51017,3);
INSERT INTO stanza VALUES('J462','3','死ぬまで忠じつなれ, みなうしなうとも;<br/>さらばゆたかないのちは, 日々われら満たす。<br/>',NULL,51018,4);
INSERT INTO stanza VALUES('J462','4','主とひとつとなりて, 死にて生かさる;<br/>主の十字架をともに受け, 主のいのちながす。<br/>',NULL,51019,5);
INSERT INTO stanza VALUES('J462','5','みこころおもうとき, そんとくはなし;<br/>すべてふん土と見なせば, 主,さまたげられず。<br/>',NULL,51020,6);
INSERT INTO stanza VALUES('J463','1','十字架受け,主とあゆみ, 主をとどめず表現す。<br/>この世捨て,主もとめる, 主をとどめず表現す。<br/>',NULL,51021,1);
INSERT INTO stanza VALUES('J463','chorus','あらわす！ もう主を閉じ込めず;<br/>あらわす！ 主をとどめず表現す。<br/>',NULL,51022,2);
INSERT INTO stanza VALUES('J464','1','復かつの大能知り, 十字架をあいす;<br/>死をとおしてのみ, いのち成長する。<br/>',NULL,51023,1);
INSERT INTO stanza VALUES('J464','chorus','死なければ, いのちなく,<br/>死を経て,いのちは 成ちょうする。<br/>',NULL,51024,2);
INSERT INTO stanza VALUES('J464','2','つくり変えのため 死ぬことひつ要;<br/>日々十字架を負い, たましい終わらす。<br/>',NULL,51025,3);
INSERT INTO stanza VALUES('J464','3','かみよ,主とともに くぎづけたまえ；<br/>死,われに,はたらき, いのちあらわる。<br/>',NULL,51026,4);
INSERT INTO stanza VALUES('J465','1','ぶどうの木の一しょう, 　 かんがえてみよ：<br/>そのみち苦難,満ち, 　環境はきびしい;<br/>気ままに咲きみだれ, いろあざやかなはな,<br/>野生のはなとは, 　何というちがい。<br/>',NULL,51027,1);
INSERT INTO stanza VALUES('J465','2','ぶどうのはな小さく, 　 華麗さもなし;<br/>ひと目につかずに 　いちにちで散る;<br/>ただ実をむすぶため, ひたすらはげむのみ,<br/>きれいなはなびら, 　ほこることなし。<br/>',NULL,51028,2);
INSERT INTO stanza VALUES('J465','3','たなにしばられて, 　 自ゆうはない;<br/>気ままなせいちょう, 　ゆるされはしない;<br/>困なんに出会っても, 逃げることもできず;<br/>自ぶんのみちを 　えらぶことなし。<br/>',NULL,51029,3);
INSERT INTO stanza VALUES('J465','4','はるにうるわしい 　 えだひろげて,<br/>木はいのちに満ち, 　わか葉はしげる;<br/>やわらかなえだ出し, そらに向けて伸ばす;<br/>無限のあまさを 　きょう受しながら。<br/>',NULL,51030,4);
INSERT INTO stanza VALUES('J465','5','されど,農夫が来て, 　 あわれみなく,<br/>ナイフとはさみで, 　ほこりはぎ取る;<br/>いまさかりのえだも, てきかくに刈り込み,<br/>いらないえだを 　すべて取り去る。<br/>',NULL,51031,5);
INSERT INTO stanza VALUES('J465','6','そんしつのあいだ, 　 自己憐憫せず,<br/>刈り取るその手に 　自己明けわたす;<br/>実をむすぶためには, 日ごとを無駄にせず,<br/>切り取るものに 　自己,明けわたす。<br/>',NULL,51032,6);
INSERT INTO stanza VALUES('J465','7','血をながしたえだ, 　 つよくされて,<br/>刈りのこされた芽, 　豊富に実むすぶ;<br/>されどたいよう照り, 枯れるようにせまり,<br/>実は盛り上がり, 　収かくにいたる。<br/>',NULL,51033,7);
INSERT INTO stanza VALUES('J465','8','ゆたかな実おもく, 　 えだしずます;<br/>ながく努りょくして, 　試練受けたゆえ;<br/>いま,うつくしい実で, なぐさめを受けるが,<br/>すぐ収かくされ, 　なぐさめは去る！<br/>',NULL,51034,8);
INSERT INTO stanza VALUES('J465','9','手でもがれ,あしで 　 踏みつけられ,<br/>ぶどうの豊富すべて 　押しつぶされる;<br/>あかいさけのながれ, この地に満ちあふれ,<br/>ゆたかにあまく, 　よろこび満たす。<br/>',NULL,51035,9);
INSERT INTO stanza VALUES('J465','10','木ははだかにされ, 　 見るもみじめ:<br/>すべてをあたえて, 　くらき夜に入る,<br/>ひとにきょうきゅうして, たのしみあたえるも,<br/>むくいを受けず, 　さらに刈られる。<br/>',NULL,51036,10);
INSERT INTO stanza VALUES('J465','11','ふゆのさむいとき, 　 ぶどう酒,ひとに<br/>あたたかさあたえ, 　あまさあたえる;<br/>かなしみなやむひと, なぐさめつづけるが,<br/>ぶどうの木はただ 　さむさに耐える。<br/>',NULL,51037,11);
INSERT INTO stanza VALUES('J465','12','ふゆは過ぎてまた 　 しん芽を吹き,<br/>実をむすぶために, 　よう意をーする;<br/>過去の苦なんのゆえ つぶやくこともなく,<br/>ただうしなうも, 　献身は変わらず。<br/>',NULL,51038,12);
INSERT INTO stanza VALUES('J465','13','きよい空気を吸い, 　 けがれ受けず,<br/>犠せいに出会っても, 　なおもほほえむ,<br/>さらにまえにすすみ, あいのはぎ取り受く,<br/>損しつ,くるしみ, 　知らぬがごとく。<br/>',NULL,51039,13);
INSERT INTO stanza VALUES('J465','14','木はそのえだより, 　 ぶどう酒ながす,<br/>捨て尽くすことで 　まずしくなるや？<br/>さけを飲み,たのしむ, 気ままな世びとらは,<br/>さいわいを得て, 　ゆたかになるや？<br/>',NULL,51040,14);
INSERT INTO stanza VALUES('J465','15','いのちの原そくは 　 うしなうこと;<br/>飲むことではなく, 　そそぎ出すこと;<br/>さいだいのちからは あいゆえ捨てること,<br/>くるしむひとの 　供きゅうはゆたか。<br/>',NULL,51041,15);
INSERT INTO stanza VALUES('J465','16','自己をにくむもの, 　 主にえらばれ,<br/>きずを受けるもの, 　ひとをなぐさむ;<br/>損しつを受けぬもの, さわがしいにょうはち,<br/>自己,愛するなら, 　よろこびはなし。<br/>',NULL,51042,16);
INSERT INTO stanza VALUES('J466','1','「死んだならおおくの 実をむすぶ」｡<br/>これは主より出た メッセージ！<br/>',NULL,51043,1);
INSERT INTO stanza VALUES('J466','2','いのちながすため, 死を経過す;<br/>地に落ち,ほうむられ, 実をむすぶ。<br/>',NULL,51044,2);
INSERT INTO stanza VALUES('J466','3','主,なれを死のなか 閉じ込めず;<br/>いのちを満たして, 復かつさす。<br/>',NULL,51045,3);
INSERT INTO stanza VALUES('J466','4','いのちながすこと ねがうなら,<br/>死を経過してこそ, ながれ出る。<br/>',NULL,51046,4);
INSERT INTO stanza VALUES('J466','5','この秘けつまなべ: 「死ねば生く」;<br/>死よりいのち出て, 収かく豊富。<br/>',NULL,51047,5);
INSERT INTO stanza VALUES('J467','1','きず,ないのか？　　 なぜきずあとないのか？<br/>なが名せい,しょうさんは, ひびきわたっているのに,<br/>きず,ないのか？<br/>',NULL,51048,1);
INSERT INTO stanza VALUES('J467','2','きず,ないのか？　　 われははくがいされて,<br/>無情,残こくな仕打ちで, むち,くぎのきず受けた,<br/>きず,ないのか？<br/>',NULL,51049,2);
INSERT INTO stanza VALUES('J467','3','なぜないのか？　　 奴隷,主人にまさるのか？<br/>師がはじ受け,弟子らは 無きずであん易なのか？<br/>きず,ないのか？<br/>',NULL,51050,3);
INSERT INTO stanza VALUES('J467','4','きず,ないのか？　　 じゅんきょう者われのゆえ,<br/>しばられ,打たれ,焼かれ, 獅子にころされたのに,<br/>きず,ないのか？<br/>',NULL,51051,4);
INSERT INTO stanza VALUES('J467','5','きず,ないのか？　　 われはしいたげられて,<br/>にくまれ,むち打たれた, なれは健康,無事,へい安,<br/>きずあとない！<br/>',NULL,51052,5);
INSERT INTO stanza VALUES('J467','6','きずあとない！　　 この世あいするからか？<br/>そんしつおそれるのか？ あいまいなゆえなのか？<br/>なぜないのか？<br/>',NULL,51053,6);
INSERT INTO stanza VALUES('J467','7','きず,ないのか？　　 きょう受しているだけか？<br/>主にちゅうじつなものは, ひとから称さんされず,<br/>きずあとある！<br/>',NULL,51054,7);
INSERT INTO stanza VALUES('J468','1','主のみちそれれば, 自己らくするが,<br/>されどわれは主の 忠じつさをおもう。<br/>',NULL,51055,1);
INSERT INTO stanza VALUES('J468','2','すでに世を捨てて, きずなを解かれ,<br/>せまきみちを行く, われらはたびびと。<br/>',NULL,51056,2);
INSERT INTO stanza VALUES('J468','3','世びとのいかる目, さげすみあるも,<br/>ただ主の笑がおと, 主の称賛もとめる。<br/>',NULL,51057,3);
INSERT INTO stanza VALUES('J468','4','しゅっ世やせいこう, われはもとめず;<br/>主につかえ,かの日, 褒賞得るをねがう。<br/>',NULL,51058,4);
INSERT INTO stanza VALUES('J468','5','日々御座をあおぎ, われはもとめる,<br/>生かつ,はたらきが, かの日耐えること。<br/>',NULL,51059,5);
INSERT INTO stanza VALUES('J468','6','世びとよ,めいせい, とみ,ほまれ得よ,<br/>せいこう,はんえい, えい誉,称賛を得よ。<br/>',NULL,51060,6);
INSERT INTO stanza VALUES('J468','7','されど，われねがう， 孤どく，貧こんを;<br/>最後まで忠じつに したがい行かせよ。<br/>',NULL,51061,7);
INSERT INTO stanza VALUES('J468','8','主,得たのは死のみ, われも主により,<br/>うしなわるをねがう, ほかにのぞみなし。<br/>',NULL,51062,8);
INSERT INTO stanza VALUES('J468','9','わが栄光はかの日, いまはにんたい;<br/>主よりもさきには 地のさちもとめず。<br/>',NULL,51063,9);
INSERT INTO stanza VALUES('J468','10','かの日かんむり受け, なみだぬぐわる！<br/>ちゅう信もてすすむ, 「主よ,とく来ませや」。<br/>',NULL,51064,10);
INSERT INTO stanza VALUES('J469','1','ベツレヘムを発ち, かみへといたる,<br/>主の忠じつまなび, まったくしたがう。<br/>馬ぶねはまずしく, 見るも耐えない,<br/>されどあしすすむ, 手に賞,得るため。<br/>',NULL,51065,1);
INSERT INTO stanza VALUES('J469','2','行けば行くほどに, みちせまくなる,<br/>労苦理かいされず, はずかしめ受く。<br/>しもべは主じんに まさらないゆえ,<br/>主のくるしみ受け, ともになみだす。<br/>',NULL,51066,2);
INSERT INTO stanza VALUES('J469','3','ガリラヤ経てのち, ひとに捨てられ,<br/>みちあやまったか？ 断じてそうでない。<br/>みちけわしくとも, 平安のなか行く;<br/>上げられるために, おそれずすすむ。<br/>',NULL,51067,3);
INSERT INTO stanza VALUES('J469','4','ゲｯセマネのそので ひとり試練受く,<br/>サタンのこうげき, だれ耐え得るか？<br/>「たたかいはいち時, 賞を見つめよ！」と,<br/>かたる御つかいは, われらはげます。<br/>',NULL,51068,4);
INSERT INTO stanza VALUES('J469','5','忠じつなたましい, カルバリを経よ;<br/>十字架のもとにて, ともにはじ受く。<br/>自己をあわれむな, 苦つうはしばし;<br/>なれにまみえる日, うれい消え去る。<br/>',NULL,51069,5);
INSERT INTO stanza VALUES('J469','6','「ぜん途は死んだ」と, とも,はかで泣く,<br/>われら主とともに, たかく上げられ,<br/>地にぞくするもの, もはやもとめず,<br/>よろこんで,いのち, とみをうしなう。<br/>',NULL,51070,6);
INSERT INTO stanza VALUES('J469','7','もくひょうに向かい, 日々ぜんしんす;<br/>みやこのかがやき, 間ぢかに見える。<br/>われ,ひそかに聞く, てんのしらべを;<br/>イェス,われらむかえ, きずいやされる。<br/>',NULL,51071,7);
INSERT INTO stanza VALUES('J469','8','主とともにあゆむ, 王こくは間ぢか,<br/>自己はまったく失せ, 主に満たされる。<br/>もはやつみもなく, くるしみもない;<br/>もくひょうに向かい, あゆみつづける｡<br/>',NULL,51072,8);
INSERT INTO stanza VALUES('J470','1','だい価はらい,十字架負い, 　 しょう利を得て,ちから得る。<br/>自己のちから,知恵でなく, とうとき主の御名しょう利得さす。<br/>',NULL,51073,1);
INSERT INTO stanza VALUES('J470','chorus','だい価はらい,十字架負い,<br/>われら勝利得て,ちから得る。<br/>',NULL,51074,2);
INSERT INTO stanza VALUES('J470','2','たくらみ絶ち,ほこり捨て, 　 イェスのようにたたかえば,<br/>負けても勝利,死はちから, 十字架の苦難はサタンをほろぼす。<br/>',NULL,51075,3);
INSERT INTO stanza VALUES('J470','3','だい胆で柔和,慈あい満つ; 　 はたらくとも,安そくある;<br/>よわさあれど,ゆう気あり, 十字架につけられ,いのち満ちる。<br/>',NULL,51076,4);
INSERT INTO stanza VALUES('J470','4','主にしたがってあゆむなら, 　 十字架を負い,主とひとつ。<br/>死にいたるも,耐えしのび, 主あらわれる日にかんむり受ける。<br/>',NULL,51077,5);
INSERT INTO stanza VALUES('J471','1','「くだかれてはじめて, 主のふところにいる！」<br/>なみかぜをおそれて, きしはなれないなら,<br/>ふところのあんそく, 享受はあり得ない。<br/>',NULL,51078,1);
INSERT INTO stanza VALUES('J471','2','「くだかれ」,かなしむが, そののち賛美となる！<br/>なみかぜはげしくも, ふところを享受する。<br/>ふところに安そくし, 揺りうごかされず。<br/>',NULL,51079,2);
INSERT INTO stanza VALUES('J471','3','「くだかれた」のちには, ひとのわざ不ひつ要;<br/>以前の航路を行くも, いかり,天にあるゆえ,<br/>おもいわずらいなし, 主の同在がすべて。<br/>',NULL,51080,3);
INSERT INTO stanza VALUES('J471','4','「くだかれる」のはえき, 他のひとはおどろく:<br/>ざんにんに見えるが, 仮装した真のめぐみ！<br/>くだかれたのちには, 主ご自身がまもる。<br/>',NULL,51081,4);
INSERT INTO stanza VALUES('J472','1','死はいのちとどめ得ず, かみの復かつのいのち;<br/>非受造で永遠のいのち, キリストよりあらわる。<br/>',NULL,51082,1);
INSERT INTO stanza VALUES('J472','2','死はいのちとどめ得ず, 死はいのちに対こうす;<br/>そは復かつのちからを あらわす機かいとなる。<br/>',NULL,51083,2);
INSERT INTO stanza VALUES('J472','3','死はいのちとどめ得ず, ほうむられてもぞう加す;<br/>苦難によりせいちょうし, 豊富に実をむすばせる。<br/>',NULL,51084,3);
INSERT INTO stanza VALUES('J472','4','死はいのちとどめ得ず, いのち,要塞を破かいす;<br/>やみの勢りょく征ふくし, 死,飲み尽くし,勝利得る。<br/>',NULL,51085,4);
INSERT INTO stanza VALUES('J472','5','死はいのちとどめ得ず, かみの全豊満あらわす;<br/>かみの義,聖を生み出し, 栄光のかたちあらわす。<br/>',NULL,51086,5);
INSERT INTO stanza VALUES('J472','6','死に出会うたびごとに, いのち経験させたまえ;<br/>この復かつのいのちは, うちに生きるキリスト。<br/>',NULL,51087,6);
INSERT INTO stanza VALUES('J473','1','「死んで生きる」,かみのいのち,<br/>いま地上でけいけんす;<br/>打ちくだかれたうつわを<br/>陶器師はつくり変える。<br/>',NULL,51088,1);
INSERT INTO stanza VALUES('J473','2','「死んで生きる」,何たる復かつ！<br/>よわいときこそつよい;<br/>苦難にていのちあらわる,<br/>われではなく,キリスト。<br/>',NULL,51089,2);
INSERT INTO stanza VALUES('J473','3','「死んで生きる」,孤どくなみち,<br/>ともに死のみちあゆむ,<br/>主の死に同けい化されて,<br/>すべてをそんと見なす。<br/>',NULL,51090,3);
INSERT INTO stanza VALUES('J473','4','「死んで生きる」,何たる使めい！<br/>天のかわあふれながる;<br/>かわくものにいま告げる,<br/>もはやかわくことなし。<br/>',NULL,51091,4);
INSERT INTO stanza VALUES('J474','1','おのがみちあゆむ つかれたひとよ,<br/>主をあおぎのぞめ, しつぼうはなし;<br/>御かおはかがやき, やみ追いやる,<br/>御かおあおぐなら, 真ひるのひかり。<br/>',NULL,51092,1);
INSERT INTO stanza VALUES('J474','2','はくがい,かんなん, 貧苦に遭うとも,<br/>主をあおぎのぞめ, おそれなどなし；<br/>かなしみのなみだ, 苦難,危けんも,<br/>こころまどわさず, ひかりうばわず。<br/>',NULL,51093,2);
INSERT INTO stanza VALUES('J474','3','主をあおぎのぞめ, 不あんなどなし,<br/>苦難に出会っても, 霊はめぐみ受く;<br/>じんせいのうみで なみかぶっても,<br/>御かおあおぐなら, こころはへい安。<br/>',NULL,51094,3);
INSERT INTO stanza VALUES('J474','4','主をあおぎのぞめ, まようことなし,<br/>かれを見上げつつ, ただしきみちへ;<br/>きりでかすんでも, 主あおぐなら,<br/>みちびきを受けて, あやまりはなし。<br/>',NULL,51095,4);
INSERT INTO stanza VALUES('J474','5','たずさえ上げられ, 栄光にあずかる,<br/>あいする主イェスを 目の当たり見る;<br/>かの日のぞみ見て, ちからを得る,<br/>やがて,われうたう, とわのさん美を。<br/>',NULL,51096,5);
INSERT INTO stanza VALUES('J475','1','くらやみのなかにて, つかれ果て,まよう！<br/>キリストあおぐなら, すべてはかがやく。<br/>',NULL,51097,1);
INSERT INTO stanza VALUES('J475','chorus','　主に目を向けよ！ 　 栄光の御かお見よ！<br/>主の栄光のなかにあり,　すべてはいろあせる。<br/>',NULL,51098,2);
INSERT INTO stanza VALUES('J475','2','死を経過しいのち得, 主のあとにしたがう;<br/>つみの権せいは去り, すでに勝利を得る。<br/>',NULL,51099,3);
INSERT INTO stanza VALUES('J475','3','やくそくはしんじつ, 信頼すれば成就す;<br/>かたく立ちつづけて, すくいを経験する。<br/>',NULL,51100,4);
INSERT INTO stanza VALUES('J476','1','いのちに生き, 主とまじわり,<br/>主をあおぎ見, 霊にしたがう,<br/>栄光日々増し, 賛美は絶えず,<br/>ひかりに生く。<br/>',NULL,51101,1);
INSERT INTO stanza VALUES('J477','1','主にまみえて, 主とかたり,<br/>主のなか住み, 主を食べる。<br/>主待ちのぞみ, 主にふくし,<br/>すべてわすれ, 主,もとめる。<br/>',NULL,51102,1);
INSERT INTO stanza VALUES('J477','2','主にまみえて, 世をわすれ,<br/>主とひそかな とき過ごす。<br/>主をあおぎ見, 変えられて,<br/>わがこう動で 主,あらわす。<br/>',NULL,51103,2);
INSERT INTO stanza VALUES('J477','3','主にまみえて, みちびかれ,<br/>すべてに主の さき行かず;<br/>苦らくあるも, 主にしたがい,<br/>みことば信じ, 主をあおぐ。<br/>',NULL,51104,3);
INSERT INTO stanza VALUES('J477','4','主にまみえて, 平あん得る;<br/>感じょう,おもい, 管理される。<br/>愛のいずみに みちびかれ,<br/>天のみわざを 実こうする。<br/>',NULL,51105,4);
INSERT INTO stanza VALUES('J478','1','主のへい士ら, 　たたかいで,<br/>自己たよらず, 　勝利を得る;<br/>主のたい能に しんらいする,<br/>主のなかにあり, すべておこなう。<br/>',NULL,51106,1);
INSERT INTO stanza VALUES('J478','2','義に生きるを 　日々ねがう,<br/>ときに飽きて, 　容易でない;<br/>おも荷負う主に すべてゆだね,<br/>主のなかにあり, すべておこなう。<br/>',NULL,51107,2);
INSERT INTO stanza VALUES('J478','3','つかれるとき, 　主はたすけ,<br/>辛苦のなかを 　わたらせる;<br/>よろこびの日, くるしみの日,<br/>主のなかにあり, すべておこなう。<br/>',NULL,51108,3);
INSERT INTO stanza VALUES('J478','4','この世に試練 　満ちるとも,<br/>つまずくこと 　あり得ない;<br/>主の事じつを せんげんして,<br/>主のなかにあり, すべておこなう。<br/>',NULL,51109,4);
INSERT INTO stanza VALUES('J478','5','主のちからは, 　つよく無限;<br/>きわみまでも 　みなすくう;<br/>主のめぐみは よわさおおう;<br/>主のなかにあり, すべておこなう。<br/>',NULL,51110,5);
INSERT INTO stanza VALUES('J479','1','イェスおもい,鋳がたとし, われより栄光あらわす;<br/>すでに永遠のいのち得, 復かつのたい能,享受する。<br/>',NULL,51111,1);
INSERT INTO stanza VALUES('J479','2','イェスおもう,日々おもう, ひくき地位にあまんじる;<br/>無げんのいのちを知り, 復かつの大能で死,経験す。<br/>',NULL,51112,2);
INSERT INTO stanza VALUES('J479','3','イェスおもう,生涯おもう, まくのうちで栄光見る;<br/>自己捨て,みこころ知り, 純けつとあんそくを得る。<br/>',NULL,51113,3);
INSERT INTO stanza VALUES('J479','4','イェスおもい,前しんする, 栄こうの御かお見つつ,<br/>栄こうから栄こうへと, 主のかたちに変えられる。<br/>',NULL,51114,4);
INSERT INTO stanza VALUES('J480','1','すべての主に, したがうか？<br/>てんは振るわれ, 地,揺れるとも;<br/>かみの同在を しんじるか？<br/>わざわい急に のぞむとも。<br/>',NULL,51115,1);
INSERT INTO stanza VALUES('J480','2','奉仕する主に したがうか？<br/>なにもおそれず, じょう歩せずに;<br/>自己,顧慮せず したがうか？<br/>ぜん途に死が 満ちるとも。<br/>',NULL,51116,2);
INSERT INTO stanza VALUES('J480','3','本とうに主に したがうか？<br/>主がぜんせんに つかわすとも;<br/>本とうに立ち, たたかうか？<br/>ゆうやみ真に せまるとも。<br/>',NULL,51117,3);
INSERT INTO stanza VALUES('J480','4','わがきょう弟よ, かみは待つ,<br/>権威にふくして, 使命果たすを。<br/>主のへい士は 主のときに,<br/>「よくやった！」と ほめられる。<br/>',NULL,51118,4);
INSERT INTO stanza VALUES('J481','1','主ちかければ, 心ぱいなし;<br/>やくそく信じ, へい安得る。<br/>揺りうごかず, つつしんで,<br/>いま来る主に, そなえする。<br/>',NULL,51119,1);
INSERT INTO stanza VALUES('J481','2','主にたよれば, 心ぱいなし;<br/>つみ,くるしみ, 主はになう。<br/>あまいあいと 堅固な御手,<br/>きかい捕らえ, けい験する。<br/>',NULL,51120,2);
INSERT INTO stanza VALUES('J481','3','主があるなら, 心ぱいなし;<br/>かみのちから, われにあり。<br/>主のみうでに 依りたのみ,<br/>おそれずただ すすみ行く。<br/>',NULL,51121,3);
INSERT INTO stanza VALUES('J482','1','やくそくすたれず, 一句ごと堅固;<br/>主がかたられると, かならず成る。<br/>',NULL,51122,1);
INSERT INTO stanza VALUES('J482','chorus','てん地,焼け失せ, やまくずれても,<br/>信じるものには ことば成就す。<br/>',NULL,51123,2);
INSERT INTO stanza VALUES('J482','2','アブラハムのように, 目を上げ見よ;<br/>多くのほしかぞえ, かたく信じよ。<br/>',NULL,51124,3);
INSERT INTO stanza VALUES('J482','3','くろくも濃くても, くものうえは,<br/>変わらぬたい陽の かがやきあり。<br/>',NULL,51125,4);
INSERT INTO stanza VALUES('J482','4','炉の火のなかでも, かみの御子は,<br/>絶えずともにいる, 試練おそるな。<br/>',NULL,51126,5);
INSERT INTO stanza VALUES('J482','5','たとえとも去っても, かみを信じよ;<br/>ちからなるイェスの めぐみのゆえ。<br/>',NULL,51127,6);
INSERT INTO stanza VALUES('J482','6','上げられる日まで, かみにたよる;<br/>のぞんだことみな, かの日に成る。<br/>',NULL,51128,7);
INSERT INTO stanza VALUES('J483','1','すすめ,すすめ！ 主とともに；<br/>まえに向かい， 身を伸ばし。<br/>振りかえらず， まえにすすめ,<br/>火のはしらで 主みちびく。<br/>すすめ,すすめ！ あら野越え,<br/>たたかい抜き， カナンに入れ。<br/>',NULL,51129,1);
INSERT INTO stanza VALUES('J483','2','栄光化のみち かみ用意す；<br/>主を愛すもの， みちあゆむ；<br/>目がまだ見ず， みみが聞かぬ<br/>栄こう目ざし 前しんせよ。<br/>やがて王こく しゅつげんし,<br/>しんじたこと じつげんす。<br/>',NULL,51130,2);
INSERT INTO stanza VALUES('J483','3','すすめ,すすめ！ あさ,ちかし;<br/>聖なるみやこ, 新エルサレﾑ。<br/>われら受ける 栄光のかんむり,<br/>おうけん持ち, 支はいする。<br/>すすめ,すすめ！ もく標見て,<br/>主の王こくに すすみ行け。<br/>',NULL,51131,3);
INSERT INTO stanza VALUES('J484','1','もくひょう目ざせ, ただ前しんせよ！<br/>先導者の召しに応じ, 主のみちはしれ。<br/>',NULL,51132,1);
INSERT INTO stanza VALUES('J484','2','もくひょう目ざせ！ 他にとらわれず;<br/>主の目は火のように なれを見つめる。<br/>',NULL,51133,2);
INSERT INTO stanza VALUES('J484','3','もくひょう目ざせ！ うしろを向かず;<br/>かれのしょうを目ざし, かんむりもとめて。<br/>',NULL,51134,3);
INSERT INTO stanza VALUES('J484','4','もくひょう目ざせ！ 目とみみふさぎ;<br/>血をながすみちにて, 主にしたがって。<br/>',NULL,51135,4);
INSERT INTO stanza VALUES('J485','note','第 一 首<br/>',NULL,51136,1);
INSERT INTO stanza VALUES('J485','1','全のうの主にたより, 　すすめ！すすめ！<br/>やくそく捕らえ信じて, 　 　すすめ！<br/>ハムの地をはなれて, エジプトあとにす,<br/>うしろ振り向かずただ 　 　すすめ！<br/>',NULL,51137,2);
INSERT INTO stanza VALUES('J485','2','てきが追って来ても, 　すすめ！すすめ！<br/>前ぽうにうみがあっても, 　 　すすめ！<br/>紅海のみずは分かれ, みずはてきほうむる;<br/>すくいのがい歌うたい, 　 　すすめ！<br/>',NULL,51138,3);
INSERT INTO stanza VALUES('J485','3','ひるはくものはしら, 　すすめ！すすめ！<br/>よるは火ばしら照らす, 　　 すすめ！<br/>飢えればマナくだり, かわけばいわ裂け,<br/>主はてきを打ちやぶる, 　　 すすめ！<br/>',NULL,51139,4);
INSERT INTO stanza VALUES('J485','4','あら野はけわしいが, 　すすめ！すすめ！<br/>契やくのはこにつづき, 　　 すすめ！<br/>ヨルダンを越えるまで, カナンにはいるまで,<br/>シオンへといたるまで, 　　 すすめ！<br/>',NULL,51140,5);
INSERT INTO stanza VALUES('J485','note','第 二 首<br/>',NULL,51141,6);
INSERT INTO stanza VALUES('J485','1','この世,愛ししたわず, 　すすめ！すすめ！<br/>おも荷,下ろし,つみ捨て, 　　 すすめ！<br/>ちち,なれを聖へ召し, キリストはいのち,<br/>聖れいはちからとなる, 　　 すすめ！<br/>',NULL,51142,7);
INSERT INTO stanza VALUES('J485','2','手をすきにかけたら, 　すすめ！すすめ！<br/>ためらわず,とどまらず, 　　 すすめ！<br/>イェスをあおぎのぞみ, つかれはいやされ,<br/>ますますゆう敢になり, 　　 すすめ！<br/>',NULL,51143,8);
INSERT INTO stanza VALUES('J485','3','ゴｰルへといたるまで, 　すすめ！すすめ！<br/>もくひょうに向かい,ただ 　　 すすめ！<br/>王こくにはいるまで, かんむり受けるまで,<br/>明けの明じょう見るまで, 　　 すすめ！<br/>',NULL,51144,9);
INSERT INTO stanza VALUES('J486','1','この世の未練を いま,断ち切り,<br/>居ねむりするな！ 目を覚ませ！<br/>間もなく主は来る！ こしにおびし,<br/>主を待ちのぞめ, 目を覚ませ！<br/>',NULL,51145,1);
INSERT INTO stanza VALUES('J486','2','とき無駄にせず, 主につかえよう;<br/>主のときせまる, 目を覚ませ！<br/>かみの武具を着け, 霊をつよくし,<br/>あく魔に対抗す, 目を覚ませ！<br/>',NULL,51146,2);
INSERT INTO stanza VALUES('J486','3','栄こうは間ぢか, 主,待ちのぞめ;<br/>王こくをもとめ, 目を覚ませ！<br/>主のらい臨間ぢか, 主,待ちのぞめ;<br/>主,来られるまで 目を覚ませ！<br/>',NULL,51147,3);
INSERT INTO stanza VALUES('J487','1','霊をかつ用し, 自己いなむ;<br/>生かつ行動の 真の秘けつ。<br/>',NULL,51148,1);
INSERT INTO stanza VALUES('J487','2','霊をかつ用し, 規てい捨て,<br/>あぶら塗りに ふく従する。<br/>',NULL,51149,2);
INSERT INTO stanza VALUES('J487','3','霊をかつ用し, 意志いなむ;<br/>ひかりのなか, 主を生きる。<br/>',NULL,51150,3);
INSERT INTO stanza VALUES('J487','4','霊をかつ用し, たましい捨て,<br/>すべての問題, かいけつす。<br/>',NULL,51151,4);
INSERT INTO stanza VALUES('J487','5','霊をかつ用し, 主をながす;<br/>霊をくん練し, 豊富,享受す。<br/>',NULL,51152,5);
INSERT INTO stanza VALUES('J487','6','霊をかつ用し, 主に触れる;<br/>霊をくん練し, 建造される。<br/>',NULL,51153,6);
INSERT INTO stanza VALUES('J487','7','霊のかつ用を もとむ主に,<br/>霊をくん練し, 栄光を帰す。<br/>',NULL,51154,7);
INSERT INTO stanza VALUES('J488','1','なぜ心ぱいするか？ まずはあたえよ;<br/>主の管理のもとで, 枯れることない。<br/>ひつようあるなら, きょうきゅうもある;<br/>創ぞうぬし,かみは, すべてそなえる。<br/>',NULL,51155,1);
INSERT INTO stanza VALUES('J488','chorus','あいして,あたえよ, ひとにぎりある;<br/>あいし,あたえるなら, かみはばい加す。<br/>',NULL,51156,2);
INSERT INTO stanza VALUES('J488','2','信じよ！ときは来る, おくれはしない;<br/>瓶のあぶら尽きず, からにならない。<br/>ゆりがころも欠き, とり飢えるとも,<br/>やもめにはなおも, ひとにぎりある。<br/>',NULL,51157,3);
INSERT INTO stanza VALUES('J488','3','明日をなやむのか？ いまあれば十分;<br/>手にまだあるのに, なぜなやむのか？<br/>おおくまくものは, おおく刈り取る;<br/>みなささげたようで, 見よ！なおもある。<br/>',NULL,51158,4);
INSERT INTO stanza VALUES('J489','1','ちちのふかき愛, 感じているか？<br/>ちちのあわれみ, 感じているか？<br/>ちちの慈あいは 何とおおきい;<br/>まったく無代価で あたえられる。<br/>',NULL,51159,1);
INSERT INTO stanza VALUES('J489','chorus','おおく,おおく, あたえられる;<br/>その大いなるあい 言い尽くせない。<br/>',NULL,51160,2);
INSERT INTO stanza VALUES('J489','2','主をしんみつに 感じているか？<br/>主のりんざいを, 享受しているか？<br/>主のみめぐみは 何とおおきい;<br/>まったく無代価で あたえられる。<br/>',NULL,51161,3);
INSERT INTO stanza VALUES('J489','3','聖れいのちから, 感じているか？<br/>あまきつゆのよう のぞんでいるか？<br/>れいのちからは 何とおおきい;<br/>まったく無代価で あたえられる。<br/>',NULL,51162,4);
INSERT INTO stanza VALUES('J490','1','天てきなあいに 　つねに住めば,<br/>環きょうの変化も, おそれることなし。<br/>つよきかぜ吹き, 　希望うばうも,<br/>かみ,われをかこみ, 　まもりたもう。<br/>',NULL,51163,1);
INSERT INTO stanza VALUES('J490','2','あともどりせぬ, 　まずしくても；<br/>とぼしくはない, 主がぼく者なれば。<br/>主はまどろまず, 　われ,見まもる,<br/>主のあゆみしみち, 　われもあゆむ。<br/>',NULL,51164,2);
INSERT INTO stanza VALUES('J490','3','みどりのまき場， 行く手にある,<br/>くろくも覆うも， すぐ,あかるくなる。<br/>のぞみは絶えず， みちあかるい,<br/>主はわれとともに， あゆむゆえに。<br/>',NULL,51165,3);
INSERT INTO stanza VALUES('J490','4','にくたい脱げば 　問題なくなる;<br/>されどもとめる, 主の臨ざい保護を。<br/>栄光の主,とつ然, 　もどって来て,<br/>御座に召されるを 　われはのぞむ。<br/>',NULL,51166,4);
INSERT INTO stanza VALUES('J490','5','その日せい徒ら, 　ともに主を見,<br/>主に触れ,賛美す, 栄光うるわしさを。<br/>不思議なその日, 　なれとともに,<br/>あんそくきょう受し, 　よろこび満つ。<br/>',NULL,51167,5);
INSERT INTO stanza VALUES('J491','1','「われともにいる」このやくそく, くらきよるでもおそれなし,<br/>主はわれのたて,れいにもどり, 主のどうざいで,なぐさめ受く。<br/>',NULL,51168,1);
INSERT INTO stanza VALUES('J491','chorus','主のどう在,えい遠のどう在,<br/>ともにいますのは,やくそくした主;<br/>主のどう在,えい遠のどう在,<br/>ともにいますのは,やくそくした主。<br/>',NULL,51169,2);
INSERT INTO stanza VALUES('J491','2','はなは枯れるが,主の愛枯れず, 天のひかりなお,ひかり増す;<br/>主もつやくのようふところにて, 夜が明けるまでともにいます。<br/>',NULL,51170,3);
INSERT INTO stanza VALUES('J491','3','ぜん途は多難で,試れんおおい, されど主ちかく,かたるゆえ,<br/>歓喜わがうちに飛び込みきて, 「主ともにいます」,われはうたう！<br/>',NULL,51171,4);
INSERT INTO stanza VALUES('J492','1','主のつばさのもとでいこう,<br/>あめかぜはげしくても;<br/>われはなおも主にたよる,<br/>すでにかみの子なれば。<br/>',NULL,51172,1);
INSERT INTO stanza VALUES('J492','chorus','つばさにのがれて, 主のあい,はなれず！<br/>つばさはわが住まい, 永遠に主と住まう。<br/>',NULL,51173,2);
INSERT INTO stanza VALUES('J492','2','うれいのがれつばさへと,<br/>満ぞく得て安そくする;<br/>この世,きずをいやせない,<br/>つばさのみなぐさめる。<br/>',NULL,51174,3);
INSERT INTO stanza VALUES('J492','3','つばさのもとに享受あり,<br/>われ,生がいここにいる！<br/>試練はもはや過ぎ去されば,<br/>安そくし,心ぱいはなし。<br/>',NULL,51175,4);
INSERT INTO stanza VALUES('J493','1','みつばさーのもとに, 　住まいがあるー,<br/>どんな環境ーにあっても,　われ,おそれず。<br/>',NULL,51176,1);
INSERT INTO stanza VALUES('J493','chorus','主はかならず, いかなるときにも,<br/>かえりみられる, かえりみられる。<br/>',NULL,51177,2);
INSERT INTO stanza VALUES('J493','2','ときに困ー難により, 　しつ望してもー,<br/>ときに危ー険われに 　のぞむときも。<br/>',NULL,51178,3);
INSERT INTO stanza VALUES('J493','3','ながいのーりすべて, 　拒ぜつされずー,<br/>どんなひーつようも, 　そなえられる。<br/>',NULL,51179,4);
INSERT INTO stanza VALUES('J493','4','いかなるー試れんに 　出会うときもー,<br/>むねに寄ーりかかり, 　かえりみ受く。<br/>',NULL,51180,5);
INSERT INTO stanza VALUES('J494','1','試れんに出会い,ぜつ望し,<br/>のぞみまったく絶えるとき,<br/>かぞえよ,主のしゅくふくを,<br/>ひとつひとつ挙げながら。<br/>',NULL,51181,1);
INSERT INTO stanza VALUES('J494','chorus','かぞえよ,しゅくふくを,<br/>かつてのかえりみを,<br/>かぞえよ,ひとつずつ,<br/>主のふかきあいに触れよ。<br/>',NULL,51182,2);
INSERT INTO stanza VALUES('J494','2','くるしみ,耐えがたいとき,<br/>十字架を負い切れぬとき,<br/>かぞえよ,主のしゅくふくを,<br/>うたがい消え,さん美満つ。<br/>',NULL,51183,3);
INSERT INTO stanza VALUES('J494','3','世のせいこうを見るとき,<br/>おぼえよ,主のやくそくを;<br/>御ちちのいえと主のあい,<br/>主のしゅくふくここにある。<br/>',NULL,51184,4);
INSERT INTO stanza VALUES('J494','4','いかなる試れんに遭っても,<br/>しつぼう,らくたんしない,<br/>主のしゅくふく,かぞえれば,<br/>御つかいは来て,つかえる。<br/>',NULL,51185,5);
INSERT INTO stanza VALUES('J495','1','ちから尽き,つかれ, たおれそうになる;<br/>おも荷をたくせと, みこえささやく。<br/>',NULL,51186,1);
INSERT INTO stanza VALUES('J495','chorus','なれのおも荷を, かみにゆだねよ,<br/>主はなぐさめ,けん固にする, かみにゆだねよ。<br/>',NULL,51187,2);
INSERT INTO stanza VALUES('J495','2','ながあし,よわまり, 火は消えかかり,<br/>しつぼうするとき, かみにゆだねよ。<br/>',NULL,51188,3);
INSERT INTO stanza VALUES('J495','3','ともは去ってゆき, こころはうれえ,<br/>きずを受けるとき, かみにゆだねよ。<br/>',NULL,51189,4);
INSERT INTO stanza VALUES('J495','4','孤どくと不あんで こころみだれる,<br/>おも荷ゆだねるを わすれたゆえに。<br/>',NULL,51190,5);
INSERT INTO stanza VALUES('J495','5','なぐさめ,やすらぎ, ちから,けん固を<br/>あたえるエホバに おも荷ゆだねよ。<br/>',NULL,51191,6);
INSERT INTO stanza VALUES('J496','1','いばらやおおかみの 試練を経過するとき,<br/>主のこころくばりを 　 あまく感じる。<br/>',NULL,51192,1);
INSERT INTO stanza VALUES('J496','chorus','主,かえりみる！ 主,かえりみる！<br/>なにもおそれはない, 主,かえりみる！<br/>',NULL,51193,2);
INSERT INTO stanza VALUES('J496','2','この世の苦のう,試練, おもいくらくするも,<br/>主のこころくばりを 　 おもい起こす。<br/>',NULL,51194,3);
INSERT INTO stanza VALUES('J496','3','うれい,苦らく,苦のう, あるともまんぞくす,<br/>主のこころくばりを われ知るゆえ。<br/>',NULL,51195,4);
INSERT INTO stanza VALUES('J497','1','主の名ふかくてひろい！<br/>そのなかにあんそくす;<br/>ときながく,くらくても,<br/>主よ,なれがあれば十分。<br/>',NULL,51196,1);
INSERT INTO stanza VALUES('J497','2','どんなかん境にあっても,<br/>主があればすべて足る;<br/>主があれば歓喜があり,<br/>主があればうたがある。<br/>',NULL,51197,2);
INSERT INTO stanza VALUES('J497','3','なれは万有のわがかみ！<br/>なれあれば満ち足りる;<br/>かえる途上のひつ要も,<br/>主があればみな足りる。<br/>',NULL,51198,3);
INSERT INTO stanza VALUES('J497','4','かつて愛の奇せきもて,<br/>主はわれをかえりみた;<br/>いま,むねに飛び込んで,<br/>こころやすらぎ,賛美す。<br/>',NULL,51199,4);
INSERT INTO stanza VALUES('J498','1','かなしむものらよ, 主の御名を取れ,<br/>主はへい安あたえ, くるしみのぞく。<br/>',NULL,51200,1);
INSERT INTO stanza VALUES('J498','chorus','あまい主の名！ 地じょうののぞみ！<br/>とうとい主の名ー！ てんのよろこび。<br/>',NULL,51201,2);
INSERT INTO stanza VALUES('J498','2','火の矢を消すたて, 主の御名を取れ;<br/>誘わくが来るとき, 御名を吸い込め。<br/>',NULL,51202,3);
INSERT INTO stanza VALUES('J498','3','愛の手のなぐさめ, うた,うたわせる;<br/>とうといイェスの名は, こころを満たす。<br/>',NULL,51203,4);
INSERT INTO stanza VALUES('J498','4','たずさえ上げられ, 主の名たたえる;<br/>御まえにひれ伏し, 王の王あがめる。<br/>',NULL,51204,5);
INSERT INTO stanza VALUES('J499','1','われでなく，ただ主なり, 主のみ平安を得させる;<br/>ただなが愛がうれい消し, こころのなみ,しずめる。<br/>',NULL,51205,1);
INSERT INTO stanza VALUES('J499','2','主のしゅくふく,すくいは, いまあり,永遠につづく;<br/>最後までわれをささえて, みちびき,つう過させる。<br/>',NULL,51206,2);
INSERT INTO stanza VALUES('J499','3','主よ,なれを知る知しき, 平あんとうたを満たす;<br/>主はわがいのち,よろこび, 主に生き,つよくされる。<br/>',NULL,51207,3);
INSERT INTO stanza VALUES('J499','4','わがこころ飢えかわき, さらにあまさをしたう:<br/>ともが去ったこころの空間, 主よ,なれで満たします。<br/>',NULL,51208,4);
INSERT INTO stanza VALUES('J499','5','さらに主を啓示しませ, さらになが栄光もとむ！<br/>めぐみとちからともない, 主よ,われにのぞみませ。<br/>',NULL,51209,5);
INSERT INTO stanza VALUES('J500','1','かみ,かぎにぎるのを, よろこぶ;<br/>もしかぎがたくされ, 　 権威さずけられれば,<br/>ためいき。ためいき。<br/>',NULL,51210,1);
INSERT INTO stanza VALUES('J500','2','もし,明日の心ぱいが きょう来て,<br/>かえりみもなければ, 　 どうしようもなく,また,<br/>(重) いのれず。<br/>',NULL,51211,2);
INSERT INTO stanza VALUES('J500','3','見えぬゆえに,むしろ より安全,<br/>暗中模さくしながら, 　 御手感じ,みこえ聞く,<br/>(重) 主,ちかい。<br/>',NULL,51212,3);
INSERT INTO stanza VALUES('J500','4','ご計かく知らねども, われ知る:<br/>主の笑がおとめぐみ, 　 この世で絶えずわれ,<br/>(重) みちびく。<br/>',NULL,51213,4);
INSERT INTO stanza VALUES('J500','5','万有網羅の主にあり, 安そくす！<br/>あせることなどない, 　 主がわれに代わって<br/>(重) こと成す。<br/>',NULL,51214,5);
INSERT INTO stanza VALUES('J501','1','主のうでに抱かれ, むねにいこう;<br/>あいにおおわれて, あんそく満ちる。<br/>われなぐさめる 天のおとずれは,<br/>聖徒たちのうた, ともに賛美する。<br/>',NULL,51215,1);
INSERT INTO stanza VALUES('J501','chorus','主のうでに抱かれ, むねにいこう;<br/>あいにおおわれて, あんそく満ちる。<br/>',NULL,51216,2);
INSERT INTO stanza VALUES('J501','2','主のうでに抱かれ, むねにいこう;<br/>あさつゆのように めぐみはのぞむ。<br/>試練もなみだも まだあるけれど,<br/>うたがい,おそれ, もうわれにはない。<br/>',NULL,51217,3);
INSERT INTO stanza VALUES('J501','3','主のうでに抱かれ, むねにいこう;<br/>永えんのつばさは, わがすべて覆う。<br/>待ちのぞむなら, 夜のかげは去り,<br/>愛すべき夜明け, ひかりもたらす。<br/>',NULL,51218,4);
INSERT INTO stanza VALUES('J502','1','かなしむもの,うれいをもって,<br/>めぐみの御座に来たれ;<br/>こころのきず,くるしみを述べよ,<br/>いやされ得ぬうれいなし。<br/>',NULL,51219,1);
INSERT INTO stanza VALUES('J502','2','孤どく,まよい,悔いたるものの<br/>ひかり,のぞみ,よろこび;<br/>なぐさめぬし,柔和にかたられる:<br/>のぞかれぬうれいなしと。<br/>',NULL,51220,2);
INSERT INTO stanza VALUES('J502','3','いのちのパン,滋養ありあまい,<br/>みず御座よりながれる;<br/>愛の宴せきで,このことおぼえる:<br/>天にて解けぬうれいなし。<br/>',NULL,51221,3);
INSERT INTO stanza VALUES('J503','1','天にさけぶこえがある, 「成就した」;<br/>信こうは呼応して言う, 「成った」。<br/>',NULL,51222,1);
INSERT INTO stanza VALUES('J503','chorus','聞け,主のことば: 「われ,すでに成就した」;<br/>また信仰は言う: 　「すでに成就した」;<br/>いのりは賛美となる, 　ハレルヤ,「成った」｡<br/>',NULL,51223,2);
INSERT INTO stanza VALUES('J503','2','完ぜんなすくい受けよ, 「成就した」;<br/>全そんざいささげよう, 「成った」｡<br/>',NULL,51224,3);
INSERT INTO stanza VALUES('J503','3','かみのやくそく受けよ, 「成就した」;<br/>感かくでなくしんじよ, 「成った」｡<br/>',NULL,51225,4);
INSERT INTO stanza VALUES('J503','4','かみのやくそくに言う: 「成就した」;<br/>じょう就をみとめて言う: 「成った」｡<br/>',NULL,51226,5);
INSERT INTO stanza VALUES('J503','5','みことばどおり信じる, 「成就した」;<br/>そは秘けつ受けるみち, 「成った」｡<br/>',NULL,51227,6);
INSERT INTO stanza VALUES('J504','1','信じてなぜもがくか？ もはやもがかない;<br/>主には良きみちあり, もがくことなし。<br/>',NULL,51228,1);
INSERT INTO stanza VALUES('J504','chorus','主のことばたしか, 信らいするに足る;<br/>もはやうたがうな, 労苦しくるしむな;<br/>しんじて安そくせよ, みことばたしか。<br/>',NULL,51229,2);
INSERT INTO stanza VALUES('J504','2','みこころにふく従し, 死にいたるも信じ,<br/>うたがいをのぞいて, きょうをゆだねよ。<br/>',NULL,51230,3);
INSERT INTO stanza VALUES('J504','3','揺れうごくたましい, やくそくしんじて,<br/>いかりを主に下ろし, きょうをゆだねよ。<br/>',NULL,51231,4);
INSERT INTO stanza VALUES('J504','4','主よ,いまもがき捨て, すべてをゆだねる;<br/>とわにみことば信じ, いま主に行こう。<br/>',NULL,51232,5);
INSERT INTO stanza VALUES('J505','1','くらやみ,うれいで, けわしくても,<br/>こころをしずめて, 御むねもとむ。<br/>',NULL,51233,1);
INSERT INTO stanza VALUES('J505','2','主にはめぐみ,慈愛, やくそくあり;<br/>間ちがい,へんこう, おくれはなし。<br/>',NULL,51234,2);
INSERT INTO stanza VALUES('J505','3','主があれと言えば, 万ぶつ存在し,<br/>主があれば,なやみ, あせりはなし;<br/>',NULL,51235,3);
INSERT INTO stanza VALUES('J505','4','主よ,なれのゆえに, 安そくを得る,<br/>われ賛美して言う: 主あれば足る！<br/>',NULL,51236,4);
INSERT INTO stanza VALUES('J505','5','主よ,なが霊あたえ, 信仰,満たせや;<br/>御名をさらに知り, 豊富にはいる。<br/>',NULL,51237,5);
INSERT INTO stanza VALUES('J506','1','かみにはあやまりなし！ かれのめぐみはじゅうぶん！<br/>かれのことばはたしか！ われら,なにをおそれよう？<br/>',NULL,51238,1);
INSERT INTO stanza VALUES('J506','2','たかきやま,たいらにし, 紅かいを分けられるかみ;<br/>それゆえ,かみはひとを, 不可能なことに置かれる。<br/>',NULL,51239,2);
INSERT INTO stanza VALUES('J506','3','かみはおのを浮かせる, うみをかわいた地とする,<br/>太よう,中くうに止める, これがかみのなさること！<br/>',NULL,51240,3);
INSERT INTO stanza VALUES('J506','4','かみは境かいをさだめ, さかまくなみをしずめる;<br/>かみには,ひとのために, できないことがあろうか？<br/>',NULL,51241,4);
INSERT INTO stanza VALUES('J506','5','愛のかみ,ひつよう知り, やくそく,すべてじょう就す;<br/>かみはあわれみに満ち, たみのさけびを聞かれる。<br/>',NULL,51242,5);
INSERT INTO stanza VALUES('J506','6','かみは不義となり得ず, やくそくをわすれ得ない;<br/>やくそく,キリストにて, アｰメンであり,みな「しかり」｡<br/>',NULL,51243,6);
INSERT INTO stanza VALUES('J506','7','かみの信じつのなかで, やくそく,かたくさだまる,<br/>信じ呼びもとめるなら, かみはかならずこたえる。<br/>',NULL,51244,7);
INSERT INTO stanza VALUES('J506','8','信こうのゆえにうたう： かみにはあやまりはなし！<br/>やくそくのゆえうたう： かみゆえに，あやまりなし！<br/>',NULL,51245,8);
INSERT INTO stanza VALUES('J507','1','じん生になみかぜ, 危けん満ちるも,<br/>地図とコンパス, 主よ,あたえませ;<br/>すくいぬしー主よ, みちびきたまえ。<br/>',NULL,51246,1);
INSERT INTO stanza VALUES('J507','2','ははおや子どもを あやすがごとく,<br/>あれくるううみ, 主,しずめられる;<br/>不思議な主けんで, みちびきたまえ。<br/>',NULL,51247,2);
INSERT INTO stanza VALUES('J507','3','死のたに行くとも, おそれはあらじ;<br/>御むねにいこい, われ,みこえ聞く:<br/>「おそれるなーかれ, なれをみちびく」｡<br/>',NULL,51248,3);
INSERT INTO stanza VALUES('J508','1','いまにいたるまで 主イェスみちびく;<br/>どうして主の愛を, うたがい得よう？<br/>いま天にぞくして, 主にふくじゅうす;<br/>(重)出会うことすべて, 主の意志がある。<br/>',NULL,51249,1);
INSERT INTO stanza VALUES('J508','2','いまにいたるまで 主イェスみちびく;<br/>霊をきょうきゅうして, いのち成長さす;<br/>たびのちから尽き, れいよわるとも,<br/>(重)いわあり,みずわき, かわきをいやす。<br/>',NULL,51250,2);
INSERT INTO stanza VALUES('J508','3','いまにいたるまで 主イェスみちびく;<br/>ちちのふところで, へい安きょう受す;<br/>からだも変えられ, えい光にはいり,<br/>(重)われ永遠にうたう, 「主のみちびき」を。<br/>',NULL,51251,3);
INSERT INTO stanza VALUES('J509','1','えい光へのたびびとよ, つかれ果て,まようも,<br/>かみはとうときやくそく, あなたにあたーえた。<br/>',NULL,51252,1);
INSERT INTO stanza VALUES('J509','chorus','「えい光へのたびびとよ, わーたしはこの目で,<br/>あーなたをえいこうへ, かーならずみちびく」｡<br/>',NULL,51253,2);
INSERT INTO stanza VALUES('J509','2','こーころはまよっても, じょう緒がみだれても,<br/>なんのさまたげもなく, やくそくはみちびく。<br/>',NULL,51254,3);
INSERT INTO stanza VALUES('J509','3','おおきな試れんのとき, ともが去っていくとき,<br/>主はこのやくーそくを, ささやいてくださる。<br/>',NULL,51255,4);
INSERT INTO stanza VALUES('J509','4','としつきは過ぎ去って, すべてうしなうとき,<br/>主はこのやくーそくで, さい後までささえる。<br/>',NULL,51256,5);
INSERT INTO stanza VALUES('J509','5','えいこうのからだ着て, おうこくに入るとき,<br/>主のこのやくーそくは, さらに信じつとなる。<br/>',NULL,51257,6);
INSERT INTO stanza VALUES('J509','6','れいはかみをよろこび, たましい,かみ,あがめ,<br/>いま主とのまじわりと, 目のみちびき受ける。<br/>',NULL,51258,7);
INSERT INTO stanza VALUES('J510','1','信こうよわるとき, 主はささえ;<br/>てき攻め来るとき, 主はささえる。<br/>',NULL,51259,1);
INSERT INTO stanza VALUES('J510','chorus','主,かならず, 主ささえる;<br/>ふかいあいのゆえ, 主ささえる。<br/>',NULL,51260,2);
INSERT INTO stanza VALUES('J510','2','主よ,ゆらぐわれを ささえませ;<br/>愛は冷えてにぶい, 主,ささえませ。<br/>',NULL,51261,3);
INSERT INTO stanza VALUES('J510','3','主,われをたからと 見なされた;<br/>われをよろこんで, 主はささえる。<br/>',NULL,51262,4);
INSERT INTO stanza VALUES('J510','4','主,われを捕らえて はなさない;<br/>代価をはらったゆえ, 主はささえる。<br/>',NULL,51263,5);
INSERT INTO stanza VALUES('J511','1','主はみな知っている！ よわさもざせつも,<br/>みことばは告げる: 「主はみな知っている」｡<br/>',NULL,51264,1);
INSERT INTO stanza VALUES('J511','2','なれのこころみや, めぐみがひつ要か,<br/>主は知っているので, おそれることはない。<br/>',NULL,51265,2);
INSERT INTO stanza VALUES('J511','3','ひとのはんたいや, 誤かいを受けても,<br/>主は知っているので, 主の安そくを享受す。<br/>',NULL,51266,3);
INSERT INTO stanza VALUES('J511','4','主におも荷ゆだね, 主になげき述べる;<br/>主は知っているので, めぐみでかえりみる。<br/>',NULL,51267,4);
INSERT INTO stanza VALUES('J511','5','主は知っているので, なぐさめ,歓喜得る;<br/>主はかならずすくう, 他になにをもとめよう？<br/>',NULL,51268,5);
INSERT INTO stanza VALUES('J512','1','この世でたびびと, 出会う苦なんは,<br/>われを天のちちに 　ちかづける;<br/>行く手さまたげる さまざまな苦なん,<br/>われのあゆみみな, 　ちちは知る。<br/>',NULL,51269,1);
INSERT INTO stanza VALUES('J512','2','御ちちが知るとは, 何という保しょう;<br/>主の同ざいあれば, 　ゆるがない。<br/>耐えがたい試練も, 主見つめ安そくす,<br/>主の同ざいあまし, 　ちちは知る。<br/>',NULL,51270,2);
INSERT INTO stanza VALUES('J512','3','ちちは日々われを, あいで見まもり,<br/>おそいかかる困難, 　越えさせる。<br/>わが行くたび路を, まもり,前進させて,<br/>えい光にはいるを 　ちちは知る。<br/>',NULL,51271,3);
INSERT INTO stanza VALUES('J512','4','御まえに立つ日に, 御かおをあおぎ,<br/>かん喜し,かん謝し, 　れい拝する。<br/>主のあまきどう在, わずらい去らせる,<br/>やくそく成るのを, 　ちちは知る。<br/>',NULL,51272,4);
INSERT INTO stanza VALUES('J513','1','主はかならず そなえたもう;<br/>わたしたちの 方法ではなく,<br/>主のほう法で そなえられる。<br/>',NULL,51273,1);
INSERT INTO stanza VALUES('J513','chorus','あんしんして 依りたのむ,<br/>主がすべて 　　 そなえられるゆえ。<br/>',NULL,51274,2);
INSERT INTO stanza VALUES('J513','2','主はかならず, そなえたもう;<br/>わたしたちの ときではなく,<br/>ご自身のとき そなえられる。<br/>',NULL,51275,3);
INSERT INTO stanza VALUES('J513','3','主はかならず, そなえたもう;<br/>主のやくそく かたく信じる,<br/>主のことばは かならず成る;<br/>',NULL,51276,4);
INSERT INTO stanza VALUES('J513','4','すすむ,すすむ, 主とともに;<br/>主,紅かい分け, マナを降らせ,<br/>てきをすべて 打ちほろぼす。<br/>',NULL,51277,5);
INSERT INTO stanza VALUES('J514','1','「わがめぐみ,なれに十分, よわさにあらわる」;<br/>この不思議なやくそく, われ,かたり,うたう。<br/>このやくそく決して わすれないように,<br/>主は絶えずかたられる: 「わがめぐみは十分」｡<br/>',NULL,51278,1);
INSERT INTO stanza VALUES('J514','chorus','「わがめぐみなれに十分, よわさにあらわる」;<br/>このように繰りかえし, 主,かたりつづける。<br/>',NULL,51279,2);
INSERT INTO stanza VALUES('J514','2','めぐみはすくいに十分, つみから解放して,<br/>あたらしいこころ得させ, 主の聖霊で満たす。<br/>めぐみはわれに十分, 試練を通過させる;<br/>やくそく,試練げき退す, 主のめぐみは十分｡<br/>',NULL,51280,3);
INSERT INTO stanza VALUES('J514','3','めぐみはやまいに十分， ささえ，またいやす。<br/>めぐみはわれをたすけ， 苦難を経過させる。<br/>めぐみは奉仕に十分， われ，兄弟をたすけ，<br/>まためぐみ十分なこと， 知るようにさせる。<br/>',NULL,51281,4);
INSERT INTO stanza VALUES('J514','4','めぐみは生かつに十分, みちびき,たすけて,<br/>死のたににも携挙にも, 十分にかえりみる。<br/>かの日に栄光の主の うるわしさを見て,<br/>ひれ伏し,言いあらわす: 「ながめぐみは十分」｡<br/>',NULL,51282,5);
INSERT INTO stanza VALUES('J514','5','主のめぐみだけが十分, われらなにもない。<br/>われらはきりのよう消え, 主はえい遠に不変。<br/>主のかたられたこと, われらは暗唱する:<br/>「わがめぐみ,なれに十分, よわさにあらわる」｡<br/>',NULL,51283,6);
INSERT INTO stanza VALUES('J515','1','主のさいらいの日, わたしは知るでしょう;<br/>ためいき,なみだの その意味なにかを。<br/>',NULL,51284,1);
INSERT INTO stanza VALUES('J515','chorus','おそれず,たよりて, たすける主に行け;<br/>くらくともさん美しよう,　みな,わかる日来る。<br/>',NULL,51285,2);
INSERT INTO stanza VALUES('J515','2','わがじんせいには, ひとつのみちあり;<br/>かくされたことも, かの日はあきらか。<br/>',NULL,51286,3);
INSERT INTO stanza VALUES('J515','3','なにゆえ,くもわき, たいようかくすか？<br/>なにゆえ,うたごえ, ためいきとなるか？<br/>',NULL,51287,4);
INSERT INTO stanza VALUES('J515','4','わたしのいのりは, なぜ,聞かれないか？<br/>わたしののぞみは, なぜ,あわとなるか？<br/>',NULL,51288,5);
INSERT INTO stanza VALUES('J515','5','わたしのすべては, 主の御手のなかに;<br/>知恵あるみちびき, かの日すべて知る。<br/>',NULL,51289,6);
INSERT INTO stanza VALUES('J516','1','主に信らいするは 何とあまいこと,<br/>やくそくのうえに われ安そくする。<br/>',NULL,51290,1);
INSERT INTO stanza VALUES('J516','chorus','イェス,イェス,信頼する, その都度たしか;<br/>イェス,イェス,とうといイェス, 主は生けるかみ。<br/>',NULL,51291,2);
INSERT INTO stanza VALUES('J516','2','イェスにしん頼して, とうとい血を信じる;<br/>いやし,きよめる血, 単純にしんじる。<br/>',NULL,51292,3);
INSERT INTO stanza VALUES('J516','3','イェスにしん頼する, つみ,自己を解く;<br/>歓喜,安そく,いのち, めぐみを受ける。<br/>',NULL,51293,4);
INSERT INTO stanza VALUES('J516','4','イェスにしん頼する, 何たるよろこび！<br/>われは主とともに えい遠にいたる。<br/>',NULL,51294,5);
INSERT INTO stanza VALUES('J517','1','わが前途,覆われ, なにも見えぬ;<br/>あゆむみちすべて, あたらしいきょう遇;<br/>そのなかでの歓喜は, なんと不思議。<br/>',NULL,51295,1);
INSERT INTO stanza VALUES('J517','chorus','みちびきにしたがい, 主に信らいする;<br/>平安のうちにうたう: 「かれは知っている」;<br/>平安のうちにうたう: 「主は知っている」｡<br/>',NULL,51296,2);
INSERT INTO stanza VALUES('J517','2','面前の一歩見た, そなえは十分;<br/>地のゆめ捨てると, 天のひかり照り,<br/>しずかなこえがある: 「われを信じよ」｡<br/>',NULL,51297,3);
INSERT INTO stanza VALUES('J517','3','知らないことは, 真のしゅくふく！<br/>主はみぎ手をもて われをはなれず,<br/>あいのなかでわれを 安そくさせる。<br/>',NULL,51298,4);
INSERT INTO stanza VALUES('J517','4','このさきのこと, 知ろうとしない;<br/>やみのなかであれ, われ主とあゆみ,<br/>見えることによらず, 主に信頼する。<br/>',NULL,51299,5);
INSERT INTO stanza VALUES('J518','1','主にたよるは真のさち, 時機得たたすけ得ん;<br/>主にかたくしたがえば, やくそくのもの得ん。<br/>',NULL,51300,1);
INSERT INTO stanza VALUES('J518','chorus','単いつに 　主にたよれ;<br/>すべてを主と見れば, みち,しめされる。<br/>',NULL,51301,2);
INSERT INTO stanza VALUES('J518','2','主にたよるは真のさち, てんのみちあゆむ;<br/>絶えず主をあおぐなら, けん固なあゆみ得ん。<br/>',NULL,51302,3);
INSERT INTO stanza VALUES('J518','3','すくいぬしはかえりみ, 御ちちはたすける;<br/>主のどうざいあるなら, まことのしゅくふく。<br/>',NULL,51303,4);
INSERT INTO stanza VALUES('J518','4','しゅくふくのみちあゆみ, 日々ぜんしんする;<br/>豊富な同ざいあるなら, 時機得たたすけ得ん。<br/>',NULL,51304,5);
INSERT INTO stanza VALUES('J519','1','途中で試練に出会うとき, サタンは「気抜け」とささやく;<br/>荷おもいが,ほう棄しない, しん仰は困難を追い出す。<br/>',NULL,51305,1);
INSERT INTO stanza VALUES('J519','chorus','信じます！信じます！ 信じるこころ,つよめてください;<br/>信じます！信じます！ 　　うたがいを下ろします。<br/>',NULL,51306,2);
INSERT INTO stanza VALUES('J519','2','順風のとき,かみの御手を しんじることたやすいが,<br/>なみがふねをおそうとき, しん仰のひつようを知る。<br/>',NULL,51307,3);
INSERT INTO stanza VALUES('J519','3','ひとは言う:「かたく立って, 死にいたるまで忠じつ」と;<br/>されど,試練がひどいとき, しん仰失せ,みなうしなう。<br/>',NULL,51308,4);
INSERT INTO stanza VALUES('J519','4','あるひとはゆう敢,ねっ心, てつ人のようほう仕するが,<br/>にくとかくとうするとき, そんしつおそれ,信じない。<br/>',NULL,51309,5);
INSERT INTO stanza VALUES('J519','5','信仰はかんかくではなく, 手に触れることでもない;<br/>すべてが見えないときも, なおかたくしんじるべき。<br/>',NULL,51310,6);
INSERT INTO stanza VALUES('J520','1','あまくしんせんな あさつゆのように,<br/>主はあぶらそそぎ, みこえささやく;<br/>立て,試れん過ぎて, あらし去るまで,<br/>立て,主のえい光と 御くに勝つため。<br/>',NULL,51311,1);
INSERT INTO stanza VALUES('J520','chorus','のぞみの主のあまきこえ！<br/>御まえにわれはたのし！<br/>',NULL,51312,2);
INSERT INTO stanza VALUES('J520','2','こころみを受けて, れいよわるとき,<br/>たとえわがのぞみ 消え去るときも,<br/>ながいのち,ちから, われを捕らえや,<br/>ながえい光のとみ, われにあたえや。<br/>',NULL,51313,3);
INSERT INTO stanza VALUES('J520','3','夜明けのひかりは, くらきをはらい,<br/>いやしのつばさは, わが夜をひるに;<br/>おお,主,なぐさめの主, うみしこころに,<br/>しゅくふくとのぞみ, とわにあたえや。<br/>',NULL,51314,4);
INSERT INTO stanza VALUES('J521','1','おお,主のなかでよろこぼう, こころみがあるとも,<br/>かんなんがなみのごとくー われにおそいかかるも。<br/>',NULL,51315,1);
INSERT INTO stanza VALUES('J521','chorus','いつもよろこび,よろこべ, ためいきつかず,うたおう,<br/>死ぬよりは生きていよう, いつもよろこぼう！<br/>',NULL,51316,2);
INSERT INTO stanza VALUES('J521','2','おお,主のなかでよろこぼう, くらやみおそうとも,<br/>あく魔はわれらのさん美を おそれるゆえにうたおう。<br/>',NULL,51317,3);
INSERT INTO stanza VALUES('J521','3','おお,主のなかでよろこぼう, やまいでよわるとも,<br/>主をよろこぶことはわれの ちからであるがゆえに。<br/>',NULL,51318,4);
INSERT INTO stanza VALUES('J521','4','おお,主のなかでよろこぼう， 地上のまく屋を脱ぎ,<br/>間もなく主に引き上げられ, もはやなげきなくなる。<br/>',NULL,51319,5);
INSERT INTO stanza VALUES('J522','1','ながくくるしんだあと, われはあますところなく,<br/>御手にゆだねた;<br/>主の手,なみだをぬぐい, 　かなしみを取り去り,<br/>かがやき満ちる。<br/>',NULL,51320,1);
INSERT INTO stanza VALUES('J522','2','さようなら！世のたのしみ, 何というむなしい娯らく,<br/>もうきょう味はない。<br/>真のよろこびは十字架, 　世のたのしみは虚偽,<br/>主,そのように見る。<br/>',NULL,51321,2);
INSERT INTO stanza VALUES('J522','3','十字架は真のしゅくふく, そのくるしみまたあまく,<br/>そんしつはえき！<br/>わがおもい,感じょう,意志, 　すべてきよめられて,<br/>よろこび満ちる。<br/>',NULL,51322,3);
INSERT INTO stanza VALUES('J522','4','自己愛,何のえきもなし, 真じつのあいにはたかい<br/>もくてきがある;<br/>自己捨てるは愛の表現, 　苦難は愛のよろこび,<br/>この愛たのしむ。<br/>',NULL,51323,4);
INSERT INTO stanza VALUES('J522','5','主よ,聖なる火で燃やし, 主とおなじ選たくするよう,<br/>われ,はいとなせ！<br/>十字架負い,主にしたがい, 　なが愛ゆえ賛美すは,<br/>最高の分けまえ。<br/>',NULL,51324,5);
INSERT INTO stanza VALUES('J523','1','十字架はおもくとも, 主のめぐみ越えず;<br/>おそろしいあらしも, 御かお,おおわず。<br/>',NULL,51325,1);
INSERT INTO stanza VALUES('J523','chorus','めぐみ,苦難にまさる, 試練,御かお,おおわず;<br/>こころかん喜す,　主ともにあれば,　てきに打ち勝つ。<br/>',NULL,51326,2);
INSERT INTO stanza VALUES('J523','2','わがみちのいばらは, 主のいばら越えず;<br/>苦杯もゲッセマネには とおくおよばず。<br/>',NULL,51327,3);
INSERT INTO stanza VALUES('J523','3','危険で苦難のみちに, ひかり,さらに増す;<br/>ひとの荷負うときも, 荷はかるくなる。<br/>',NULL,51328,4);
INSERT INTO stanza VALUES('J523','4','御かおのまえで生き, 御むねにしたがう;<br/>どのような試れんも, しゅくふくの化身。<br/>',NULL,51329,5);
INSERT INTO stanza VALUES('J524','1','われ,かごのなかのとり, おおぞらを飛べない;<br/>ここへと置かれた主に, われは絶えずうたう;<br/>われ拘そく享受す, かみも享受しませ。<br/>',NULL,51330,1);
INSERT INTO stanza VALUES('J524','2','監禁され,なにもできず, しずかにうたうのみ;<br/>わがほめたたえるうた, かみは聞き入りたもう;<br/>かみは拘そくして, 賛美聞くをこのむ。<br/>',NULL,51331,2);
INSERT INTO stanza VALUES('J524','3','かみは聞くみみを持ち, 祝ふくのこころあり;<br/>わがつたないしらべも, 主はかろんじられない;<br/>引くあいのこころ, なれは知るゆえに。<br/>',NULL,51332,3);
INSERT INTO stanza VALUES('J524','4','われはかごに入れられ, 自ゆうに飛べないが,<br/>こころ,れいはなお自由, かい放され,飛び立つ;<br/>牢ごくのかべさえ, それをさまたげず。<br/>',NULL,51333,4);
INSERT INTO stanza VALUES('J524','5','わがこころ,ごくを越え, わがれい何と自ゆう！<br/>愛する主へと飛び立ち, みこころ礼はいする;<br/>みこころのなかで, よろこび,わき出る。<br/>',NULL,51334,5);
INSERT INTO stanza VALUES('J525','1','四方かべで終じつ 　　われ,ごくにある;<br/>ごくにつなぐとも, 　　主よりはなせず;<br/>主がともにいませば, 　かべもまたあいらしい。<br/>',NULL,51335,1);
INSERT INTO stanza VALUES('J525','2','孤どくでないこと, 　　知ってはいるが,<br/>秘みつのなぐさめ, 　　ひとは知らない;<br/>やみをひかりに変え, 　わが霊に歓喜満たす。<br/>',NULL,51336,2);
INSERT INTO stanza VALUES('J525','3','愛われをはげまし, 　　さん美に変える;<br/>とき,場所を問わず, 　　ふかみで礼拝す;<br/>どんな環きょうでも主と　調和することもとむ。<br/>',NULL,51337,3);
INSERT INTO stanza VALUES('J525','4','これはわがたから, 　　えきをもたらす;<br/>なにがのぞもうとも, 　　主があれば十分。<br/>わざわいをふくに変え, 　苦難を歓喜に変える。<br/>',NULL,51338,4);
INSERT INTO stanza VALUES('J526','1','主,やくそくされない, つねに晴れわたって,<br/>苦つうない,たのしい, はなやかな人せいを。<br/>',NULL,51339,1);
INSERT INTO stanza VALUES('J526','chorus','主のあたえるやくそく: 　 せいかつにちからと,<br/>試練のときめぐみと, すべてをふくむ主キリスト。<br/>',NULL,51340,2);
INSERT INTO stanza VALUES('J526','2','主,やくそくされない, 苦難,試練に出遭わず,<br/>おも荷負うことない, じゅんちょうな生がいを。<br/>',NULL,51341,3);
INSERT INTO stanza VALUES('J526','3','主,やくそくされない, 平坦なみち,行き交い,<br/>大うなばら,ひろがり, さまたげないことを。<br/>',NULL,51342,4);
INSERT INTO stanza VALUES('J527','1','圧ぱくされ,のがれ場ない; 孤どくでなみだながす;<br/>どうしようもない圧ぱくで, のぞみは絶えたゆえに。<br/>',NULL,51343,1);
INSERT INTO stanza VALUES('J527','chorus','かみは希望,よろこび, 無をゆうに変え,死人生かす。<br/>',NULL,51344,2);
INSERT INTO stanza VALUES('J527','2','圧ぱくされ,へいあんない; 四ほうくらやみで満つ;<br/>圧ぱくにあっぱくされて, いのち消えそうになる。<br/>',NULL,51345,3);
INSERT INTO stanza VALUES('J527','3','圧ぱくで主に追いやられ, まずしさ,むちをあいす;<br/>あい次ぐ圧ぱくのなかで, ただ主をあいし,したう。<br/>',NULL,51346,4);
INSERT INTO stanza VALUES('J527','4','圧ぱくはこの世を去らせ, 天にのぼらせ,自由にす;<br/>不可能を可能とする主に 信らいし,生き,また死ぬ。<br/>',NULL,51347,5);
INSERT INTO stanza VALUES('J527','5','あまりのあっぱくにより, ちから尽きてたおれた;<br/>きょく度のあっぱくにより, 永えんのあんそく得る。<br/>',NULL,51348,6);
INSERT INTO stanza VALUES('J527','6','圧ぱくにかみの手を見る; 大きな利えきもたらす;<br/>圧ぱくで動揺しないのを, ひとは不思議におもう。<br/>',NULL,51349,7);
INSERT INTO stanza VALUES('J527','7','圧ぱくあれど前しんする, のぞみ,てんにあるゆえ;<br/>依然として圧ぱくあるが, なおかみの安そくあり。<br/>',NULL,51350,8);
INSERT INTO stanza VALUES('J528','1','やみ,かならずひかりに, 苦難,かならずあまさに;<br/>損しつはえきもたらす, 十字架のあと栄光あり。<br/>',NULL,51351,1);
INSERT INTO stanza VALUES('J528','2','たねをまけば刈り取る, あめのあとに日は照る；<br/>いたみのあと平安あり, なげきのあと歓喜あり。<br/>',NULL,51352,2);
INSERT INTO stanza VALUES('J528','3','放とうのあと安住する， 孤どくのあと同在あり；<br/>十字架かんむりに変わり， 主と間ぢかにまみえる。<br/>',NULL,51353,3);
INSERT INTO stanza VALUES('J529','1','かみは二本の木の まえにひとを置く:<br/>いのちの木はかみ, 知しきの木はサタン。<br/>',NULL,51354,1);
INSERT INTO stanza VALUES('J529','2','永遠のご計かくの 中心はいのちの木,<br/>キリストのなかで ご自しんを分与す。<br/>',NULL,51355,2);
INSERT INTO stanza VALUES('J529','3','べつのみなもとの 知しきの木があり:<br/>触れるなら死ぬと, かみは警こくする。<br/>',NULL,51356,3);
INSERT INTO stanza VALUES('J529','4','いのちの木を食べ, いのちを受ければ,<br/>宝せきに変えられ, みこころ,成就する。<br/>',NULL,51357,4);
INSERT INTO stanza VALUES('J529','5','知しきの木,取れば, サタン,ひとにはいり,<br/>つみは死,もたらし, ご計かく,さえぎる。<br/>',NULL,51358,5);
INSERT INTO stanza VALUES('J529','6','かみこそ唯いつの いのちのみなもと;<br/>その他のすべては, ただ死をもたらす。<br/>',NULL,51359,6);
INSERT INTO stanza VALUES('J529','7','善とあく,いずれも ひとに死もたらす;<br/>かみ以がいのもの, みなサタンの計りゃく。<br/>',NULL,51360,7);
INSERT INTO stanza VALUES('J529','8','あくのみかぜんも, キリストにてきし,<br/>知しきにぞくせば, いのちに相対する。<br/>',NULL,51361,8);
INSERT INTO stanza VALUES('J529','9','ぜんあくに触れず, ただ主にのみ触れ,<br/>主よ,ながいのちで, わがうち満たせや。<br/>',NULL,51362,9);
INSERT INTO stanza VALUES('J530','1','かみの律法は聖にて, ひとに善を要求する;<br/>そは,ひと応じ得ぬを ひとに証めいするため。<br/>',NULL,51363,1);
INSERT INTO stanza VALUES('J530','2','おもいにある法そく, つねに善を欲するが,<br/>肢たいにある法そく, 絶えずそれにさからう。<br/>',NULL,51364,2);
INSERT INTO stanza VALUES('J530','3','ひとのいのちにある おもいの法そくは善;<br/>善行を維持するため, 創造のときあたえらる。<br/>',NULL,51365,3);
INSERT INTO stanza VALUES('J530','4','肢たいにある法そく, 邪あくでサタンから出,<br/>からだのなかに入り, 死を通して支はいする。<br/>',NULL,51366,4);
INSERT INTO stanza VALUES('J530','5','肢たいのなかにある つみおかす法そくは,<br/>善のほうそくに勝ち, ひとをうばい,支はいす。<br/>',NULL,51367,5);
INSERT INTO stanza VALUES('J530','6','さらに法そくがある, いのちの霊の法そく;<br/>わが霊のなかにあり, 再生のとき,あたえらる。<br/>',NULL,51368,6);
INSERT INTO stanza VALUES('J530','7','このさい高の法そく, 他の法そくを超える;<br/>死の法そくより解き, かみの要求みな満たす。<br/>',NULL,51369,7);
INSERT INTO stanza VALUES('J530','8','さればわがおもいを, つねに霊の上に置く;<br/>もはやにくに置かず, つみのちからはなれる。<br/>',NULL,51370,8);
INSERT INTO stanza VALUES('J530','9','にくに付けたおもい, おそろしい死とやみ;<br/>れいに付けたおもい, しゅくふくのいのち,平安。<br/>',NULL,51371,9);
INSERT INTO stanza VALUES('J530','10','これこそ解放のみち, これこそ勝利のみち！<br/>われらを霊に生かし, なれともにあゆませよ。<br/>',NULL,51372,10);
INSERT INTO stanza VALUES('J531','1','文字の律法,かみしめし, かみをあかししてかたる;<br/>なんとせいで義であり, なんとひかり,愛であるかを。<br/>',NULL,51373,1);
INSERT INTO stanza VALUES('J531','2','かみの本しつのゆえに, かみの律法は要きゅうする;<br/>ひとを義とし受け入れ, しゅくふくをあたえるために。<br/>',NULL,51374,2);
INSERT INTO stanza VALUES('J531','3','律法はいのちあたえず, 何のちからもあたえない;<br/>ただ要きゅうするだけで, ひとのよわさをばく露する。<br/>',NULL,51375,3);
INSERT INTO stanza VALUES('J531','4','律法,当初のものでなく, のちにくわえられたもの,<br/>ひとがつみをおかして, とがに満ちること証明する。<br/>',NULL,51376,4);
INSERT INTO stanza VALUES('J531','5','律ぽうはくちをふさぎ, つみのもとに閉じ込めて,<br/>キリストへともたらす, われにしゅくふくあとうため。<br/>',NULL,51377,5);
INSERT INTO stanza VALUES('J531','6','律法はキリストのかげ, キリストはかみのあかし,<br/>かみのあい,聖,義,ひかり, キリストは完全に表現する。<br/>',NULL,51378,6);
INSERT INTO stanza VALUES('J531','7','かみのキリスト,われに 神聖ないのちを供給する,<br/>律法のあらゆる要求が, われにあり成就されるため。<br/>',NULL,51379,7);
INSERT INTO stanza VALUES('J531','8','キリスト,生けるあかし, 大能のいのちにあずかり,<br/>かれにあり律法に死に, かれの霊のなかで聖となる。<br/>',NULL,51380,8);
INSERT INTO stanza VALUES('J532','1','旧やくのかみの律法は, いしのいたにしるし,<br/>いまや,いのちのほうそくは, 霊にてこころにしるす。<br/>',NULL,51381,1);
INSERT INTO stanza VALUES('J532','2','律法はぜんを要求して, ひとはよわさを知る;<br/>いのちの法そくはきょう給し, かみの大能を享受さす。<br/>',NULL,51382,2);
INSERT INTO stanza VALUES('J532','3','文字の律法は外めんで, かみを認しきさせる;<br/>いのちの法そくはない面で, かみを供給し啓示する。<br/>',NULL,51383,3);
INSERT INTO stanza VALUES('J532','4','文字の律法は外めんで, いましめもて管理す;<br/>いのちの法そくはない面で, 生ける知しきもて制す。<br/>',NULL,51384,4);
INSERT INTO stanza VALUES('J532','5','生けるいのちの法そく, わがうちで運行する,<br/>いのちの感かくにしたがい うちより管理,規制する。<br/>',NULL,51385,5);
INSERT INTO stanza VALUES('J532','6','この管理いとこまやか, わがふかみにありて,<br/>いのちの感かくをあたえて, かみご自身を供給する。<br/>',NULL,51386,6);
INSERT INTO stanza VALUES('J532','7','いのちの法そくのゆえ, 外面のおしえは不要;<br/>かみに対する認しきをみな, 内面の法そく,おしえる。<br/>',NULL,51387,7);
INSERT INTO stanza VALUES('J532','8','この法そくにしたがい, 内面の管理にふくす,<br/>生ける認しきもて主を知り, ご自身を享受するため。<br/>',NULL,51388,8);
INSERT INTO stanza VALUES('J533','1','とわのいのち, まじわりを,<br/>霊のまじわり, 霊もたらす。<br/>',NULL,51389,1);
INSERT INTO stanza VALUES('J533','2','神聖ないのち, 分与されて,<br/>主の霊わが霊, ともに生く。<br/>',NULL,51390,2);
INSERT INTO stanza VALUES('J533','3','交流もたらす 霊のいのち;<br/>めぐみ得さす 霊の交りゅう。<br/>',NULL,51391,3);
INSERT INTO stanza VALUES('J533','4','いのちの大能, 交流得させ,<br/>霊の交流には, ひかりあり。<br/>',NULL,51392,4);
INSERT INTO stanza VALUES('J533','5','血のきよめは, 交流たもち,<br/>内面のあぶら, 交流得さす。<br/>',NULL,51393,5);
INSERT INTO stanza VALUES('J533','6','十字架通して, 交流ふかめ,<br/>霊の運行にて, 交流,更新す。<br/>',NULL,51394,6);
INSERT INTO stanza VALUES('J533','7','交流にてわれ, 自己はなれ,<br/>交流にてわれ, かみに入る。<br/>',NULL,51395,7);
INSERT INTO stanza VALUES('J534','1','どんないのちにも 感かくがある;<br/>神聖ないのち,さらに 感かくがある。<br/>',NULL,51396,1);
INSERT INTO stanza VALUES('J534','2','かみのいのちには 感かくがある;<br/>いのちがたかいほど, 感かくがある。<br/>',NULL,51397,2);
INSERT INTO stanza VALUES('J534','3','うちなる感かくは かみの感かく;<br/>善の感かくにまさる れいのいのち。<br/>',NULL,51398,3);
INSERT INTO stanza VALUES('J534','4','うちなる感かくは, ふかい感かく;<br/>すべてをしきべつし, 御むねしめす。<br/>',NULL,51399,4);
INSERT INTO stanza VALUES('J534','5','いのちの感かくで, かみ認しきす;<br/>そとがわからでなく, うちなる啓示。<br/>',NULL,51400,5);
INSERT INTO stanza VALUES('J534','6','いのち成長すれば, 感かくは増す;<br/>いのちにてあゆめば, 感かくたしか。<br/>',NULL,51401,6);
INSERT INTO stanza VALUES('J534','7','感かく訓練すれば, 霊はつよまり,<br/>うちなる感かくにて まじわり得る。<br/>',NULL,51402,7);
INSERT INTO stanza VALUES('J535','1','聖徒の霊の理かいりょく, それは実際またほう富;<br/>外めんのおしえでなく, 内めんでかみ理かいす。<br/>',NULL,51403,1);
INSERT INTO stanza VALUES('J535','2','さいこうのいのちには, 神せいなはたらきある;<br/>いのちでかみ知るのは, 外めんの知しき超える。<br/>',NULL,51404,2);
INSERT INTO stanza VALUES('J535','3','いのちの霊の法そくを, 聖霊わがこころに書く;<br/>内めんの管理によって, ふかくかみを知らせる。<br/>',NULL,51405,3);
INSERT INTO stanza VALUES('J535','4','塗りあぶら,わが霊にて, かみのことがらしめす;<br/>このあぶら塗りとおし, ふかくかみを知らせる。<br/>',NULL,51406,4);
INSERT INTO stanza VALUES('J535','5','三いちのかみ,わが霊に 住み,運行し,こうどうす;<br/>このうちなる感かくで, ふかくかみを認しきす。<br/>',NULL,51407,5);
INSERT INTO stanza VALUES('J535','6','内面の認しき持つゆえ, もうがい面の知しき不要;<br/>時々刻こくれいに生き, れいの指示にしたがう。<br/>',NULL,51408,6);
INSERT INTO stanza VALUES('J535','7','キリスト生きるほどに, さらに感かくつよまり,<br/>内面の認しきふかまり, キリスト書き込まれる。<br/>',NULL,51409,7);
INSERT INTO stanza VALUES('J535','8','内めんの認しきにより, 主とのまじわり維持す;<br/>この認しきをとおして, 神せいの豊満を享受す。<br/>',NULL,51410,8);
INSERT INTO stanza VALUES('J536','1','受にくの原そくは,かみ,ひと 　ともに混ざり合うこと;<br/>両者はおく義てきなひとに 調和し,ともに生かつする。<br/>',NULL,51411,1);
INSERT INTO stanza VALUES('J536','2','ひとは外面でかみの表げん, 　かみ,内めんでいのち;<br/>ひと,かみにまったく占有され, かみ,ひとを通し表現さる。<br/>',NULL,51412,2);
INSERT INTO stanza VALUES('J536','3','あがない,ひとにあり成就され, 　かみの知恵をしめす;<br/>すくい,ひとを通し述べられ, 全被造ぶつに知らせらる。<br/>',NULL,51413,3);
INSERT INTO stanza VALUES('J536','4','霊てきなはたらきはすべて 　ひとの同労がひつ要,<br/>かみ,ひと,たがいにしたしみ, たがいにけつ合し,調和す。<br/>',NULL,51414,4);
INSERT INTO stanza VALUES('J536','5','かみご自身が労すにあらず, 　ひとのみにもよらず;<br/>かみとひと,ともにはたらき, ごけいかくを完せいする。<br/>',NULL,51415,5);
INSERT INTO stanza VALUES('J536','6','われらいちのなかでともに 　つかえ,奉仕するため,<br/>すべてのわざとたまものに, 受にくの原そくてき用す。<br/>',NULL,51416,6);
INSERT INTO stanza VALUES('J537','1','ひとは三部分から成り, からだ,たましい,霊がある,<br/>それで主を享受し, 永遠の計かく成就す。<br/>',NULL,51417,1);
INSERT INTO stanza VALUES('J537','2','からだはがい面の部分, 物しつの感かくを持つ;<br/>外面のものに触れ, かたちをもて表現す。<br/>',NULL,51418,2);
INSERT INTO stanza VALUES('J537','3','たましいは内面の部分, まことにひとそのもの;<br/>それは心理てきで, 精しんかいに触れる。<br/>',NULL,51419,3);
INSERT INTO stanza VALUES('J537','4','霊はひとの最深の部分, かみと接しょくするため;<br/>かみを受け入れて, 霊の世かいに触れる。<br/>',NULL,51420,4);
INSERT INTO stanza VALUES('J537','5','ひとのたましいのうちに, おもい,感情,意志がある;<br/>ひとの機のう持ち, ひとのねがい果たす。<br/>',NULL,51421,5);
INSERT INTO stanza VALUES('J537','6','良心,まじわり,直かくは, ひとの霊のなかにある;<br/>それは霊でかみを 礼拝して触れるため。<br/>',NULL,51422,6);
INSERT INTO stanza VALUES('J537','7','たましいの諸部分もちい, かみをつねに選たくす;<br/>霊でかみを享受し, からだ通し表現する。<br/>',NULL,51423,7);
INSERT INTO stanza VALUES('J537','8','霊は再生でいのち持ち, たましいつくり変えられ,<br/>からだは変貌され, 栄光のからだとなる。<br/>',NULL,51424,8);
INSERT INTO stanza VALUES('J537','9','ひとの三部分はすべて, 神聖なはたらきにより,<br/>主と混ざり合って, 完全に主を表現する。<br/>',NULL,51425,9);
INSERT INTO stanza VALUES('J538','1','かみは創世のまえに 子たる身ぶんへと<br/>あらかじめさだめて ご自身をあたえた;<br/>われらを同けい化して, ひとり子,長子となし,<br/>多くの子たちにより 主の栄光あらわす。<br/>',NULL,51426,1);
INSERT INTO stanza VALUES('J538','2','さい生により,われら 多くの子となるが,<br/>相ぞく人となるには, えんじゅくがひつ要。<br/>完全に成長することで 子たる身分を享受し,<br/>主の身のたけに達し, しゅくふくあじわう。<br/>',NULL,51427,2);
INSERT INTO stanza VALUES('J538','3','霊,たましい,からだみな 同形化されるように;<br/>主の栄光に入るとき, それは成就される。<br/>からだがあがなわれて, 子たる身分,完成され,<br/>最後のつくり変えで, 御むね満たされる。<br/>',NULL,51428,3);
INSERT INTO stanza VALUES('J538','4','最後のつくり変えで, 完全に聖べつされ,<br/>栄光にもたらされて, 御子のよう完成する。<br/>かみの子らのしゅつ現を 被造ぶつ待ちのぞみ,<br/>やがてかれらはみな, 栄光の自由に入る。<br/>',NULL,51429,4);
INSERT INTO stanza VALUES('J539','1','あいするこころと 受け入れる霊を持つ<br/>かみのうつわとし ひとはつくられた。<br/>',NULL,51430,1);
INSERT INTO stanza VALUES('J539','2','こころで主あいし, 霊で主を受け入れる;<br/>いのちにあずかる みちはほかになし。<br/>',NULL,51431,2);
INSERT INTO stanza VALUES('J539','3','サタンはこころを けがし,れいを死なせ,<br/>主に触れさせずに, 自己に生きさせる。<br/>',NULL,51432,3);
INSERT INTO stanza VALUES('J539','4','主はすくいにあり, こころと霊を更新し,<br/>受け入れ,あいする 機能かいふくした。<br/>',NULL,51433,4);
INSERT INTO stanza VALUES('J539','5','あらたなこころで, かみをあいし,もとめ,<br/>あらたなれいもて, 礼拝し,受け入れる。<br/>',NULL,51434,5);
INSERT INTO stanza VALUES('J539','6','かみに対しこころ, 単いつで純粋であり,<br/>霊のなかまずしく, ついきゅうし,ふくす。<br/>',NULL,51435,6);
INSERT INTO stanza VALUES('J539','7','こころは主あいし, 新せんでふるさなく,<br/>霊はつねにつよく, 活ぱつであるように。<br/>',NULL,51436,7);
INSERT INTO stanza VALUES('J540','1','主のすべて享受し, まじわるため,<br/>せいじょうなこころ, われらひつ要。<br/>',NULL,51437,1);
INSERT INTO stanza VALUES('J540','2','純すいで冷せいな おもいにより,<br/>主のこころを知り, おそれふくす。<br/>',NULL,51438,2);
INSERT INTO stanza VALUES('J540','3','感情はあいに富み, 火つねに燃え,<br/>せつに主をしたい, 追いもとめる。<br/>',NULL,51439,3);
INSERT INTO stanza VALUES('J540','4','意志はせいじつで, 従順にふくす;<br/>つよくまたじゅう軟 主におうじて。<br/>',NULL,51440,4);
INSERT INTO stanza VALUES('J540','5','良心はとがめ去り, きよく透めい;<br/>かみと和かいする, 主の血通して。<br/>',NULL,51441,5);
INSERT INTO stanza VALUES('J540','6','このこころをもて なれをしたい,<br/>ながほう富,享受し, 豊まんとなる。<br/>',NULL,51442,6);
INSERT INTO stanza VALUES('J541','1','われらの霊にあり, なれはその霊;<br/>ふたつ霊はひとつ, われら得たり。<br/>',NULL,51443,1);
INSERT INTO stanza VALUES('J541','2','なが霊とわが霊は, あかしをする:<br/>われらかみの子ぞ, 栄光の世継ぎ。<br/>',NULL,51444,2);
INSERT INTO stanza VALUES('J541','3','なれは霊のうちで, 主ご自身あとう;<br/>われら霊のうちで, 主のとみ受く。<br/>',NULL,51445,3);
INSERT INTO stanza VALUES('J541','4','なれは霊のうちで, われみちびく;<br/>われら霊のうちで, したがいゆく。<br/>',NULL,51446,4);
INSERT INTO stanza VALUES('J541','5','その霊わがうちで, 供給しつよむ;<br/>われその霊により, 奉仕,れい拝す。<br/>',NULL,51447,5);
INSERT INTO stanza VALUES('J541','6','そのれいはうめき, とりなしたもう;<br/>われは霊のなかで, ともにいのる。<br/>',NULL,51448,6);
INSERT INTO stanza VALUES('J541','7','われら霊にもどり, なが霊に触れ,<br/>せいなる遺産をば, 受けたのしむ。<br/>',NULL,51449,7);
INSERT INTO stanza VALUES('J541','8','ふたつ霊はひとつ, 何たるきょう給！<br/>主,わがうちに生き, われ主に住む！<br/>',NULL,51450,8);
INSERT INTO stanza VALUES('J542','1','十字架で霊見分け, たましいを死なす;<br/>日々自己をいなみ, その霊に生きる。<br/>',NULL,51451,1);
INSERT INTO stanza VALUES('J542','2','ことばと十字架で れいを見分ける;<br/>れい,たましい分離し, 霊のなか生きる。<br/>',NULL,51452,2);
INSERT INTO stanza VALUES('J542','3','十字架で霊見分け, おもい更新され,<br/>かんじょうをささげ, 意志はふくする。<br/>',NULL,51453,3);
INSERT INTO stanza VALUES('J542','4','十字架で霊見分け, 垂れまく経過し,<br/>にく,たましい裂かれ, 霊は支はいする。<br/>',NULL,51454,4);
INSERT INTO stanza VALUES('J542','5','十字架で霊見分け, 至せい所に入り,<br/>かみとまじわって, どう在享受する。<br/>',NULL,51455,5);
INSERT INTO stanza VALUES('J542','6','十字架で霊見分け, ヨルダンをわたり,<br/>カナンの地に入り, キリスト生きる。<br/>',NULL,51456,6);
INSERT INTO stanza VALUES('J542','7','十字架で霊見分け, 霊のなかに生き,<br/>良き地をたがやし, 主の豊富を得る。<br/>',NULL,51457,7);
INSERT INTO stanza VALUES('J543','1','至聖所には契やくの はことめぐみの御座あり,<br/>そこに栄光と臨在あり, 祭司,かみとかい見する。<br/>',NULL,51458,1);
INSERT INTO stanza VALUES('J543','2','われらはかみのみや, ひとの霊はその至せい所,<br/>かみ,キリスト,そのれい, わがれいのなかに住む。<br/>',NULL,51459,2);
INSERT INTO stanza VALUES('J543','3','いとふかきわが霊で, 主にあるかみ,わがすべて;<br/>その霊は主キリストを, とわにわが実さいとす。<br/>',NULL,51460,3);
INSERT INTO stanza VALUES('J543','4','至せい所わが霊にて, 主に触れ,主とともにある;<br/>至せい所わが霊を通し, かみとまじわり,礼拝す。<br/>',NULL,51461,4);
INSERT INTO stanza VALUES('J543','5','キリストこそ良き地, そこにてその豊富エンジｮィす;<br/>そこにて,てき攻め取り, 権威もちい,よみ対処す。<br/>',NULL,51462,5);
INSERT INTO stanza VALUES('J543','6','霊の認しきつい求し, たましいより霊,切りはなす,<br/>至せい所にて生かつし, かみ,主の同ざいエンジｮィす。<br/>',NULL,51463,6);
INSERT INTO stanza VALUES('J543','7','われ,たましいをいなみ, かみのあんそくにはいり,<br/>キリストの豊富を得て, 御むねをまったく成就す。<br/>',NULL,51464,7);
INSERT INTO stanza VALUES('J544','1','霊とたましいを見分けさせよ, 　主を真に知るために;<br/>なれはいま霊,わが霊に住み, ふたつ霊ひとつ霊となる。<br/>',NULL,51465,1);
INSERT INTO stanza VALUES('J544','2','霊とたましいを見分けさせよ, 　たましいを拒否して;<br/>霊にありて,とわにしたがい, なが生ける霊をてき用す。<br/>',NULL,51466,2);
INSERT INTO stanza VALUES('J544','3','霊とたましいを見分けさせよ, 　おもいをにくに付けず;<br/>つねにおもいを霊に付けて, つみと自己よりはなれる。<br/>',NULL,51467,3);
INSERT INTO stanza VALUES('J544','4','霊とたましいを見分けさせよ, 　たましいにぞくさず,<br/>完全に真じつに霊にぞくし, 霊にて生かつし行動する。<br/>',NULL,51468,4);
INSERT INTO stanza VALUES('J544','5','霊とたましいを見分けさせよ, 　卑怯な自己,ばく露し;<br/>なれの十字架をてき用して, われでなく,キリスト生く。<br/>',NULL,51469,5);
INSERT INTO stanza VALUES('J544','6','霊とたましいを見分けさせよ, 　たましいをつくり変え,<br/>ながかたちに同けい化され, えんじゅくし,ゴｰルに達する。<br/>',NULL,51470,6);
INSERT INTO stanza VALUES('J544','7','霊とたましいを見分けさせよ, 　生けることばにより,<br/>たましいと霊を切り分けて, 霊にありなれ,ともに住む。<br/>',NULL,51471,7);
INSERT INTO stanza VALUES('J545','1','三いちのかみ,栄光の霊, いまわれらのれいに住み,<br/>われらよりながれ出て, 　かみをあらわさせる。<br/>',NULL,51472,1);
INSERT INTO stanza VALUES('J545','2','そとなる天然のひとは, つねにその霊,閉じ込める;<br/>かれにいえを得させず, 　かれの監ごくとなる。<br/>',NULL,51473,2);
INSERT INTO stanza VALUES('J545','3','つちのうつわのなかの たから,かくされて見えず;<br/>うつわ,打ちくだかれて, 　たからはあらわれる。<br/>',NULL,51474,3);
INSERT INTO stanza VALUES('J545','4','そくばくするたましい, かならずくだかれるべき;<br/>天然のひと,くだかれて, 　霊は解放されるゆえ。<br/>',NULL,51475,4);
INSERT INTO stanza VALUES('J545','5','苦難通しのぞむかん境, なにゆえ主はゆるすのか？<br/>それはそとなるひとを 　主が折りくだくため。<br/>',NULL,51476,5);
INSERT INTO stanza VALUES('J545','6','そとなるひとかならず きず受け,こわされるべき;<br/>そのときうちなるひと, 　霊とともに解放得る。<br/>',NULL,51477,6);
INSERT INTO stanza VALUES('J545','7','主よ,われをくだきませ, どんなそんしつも甘受して,<br/>自己や自分の意けんを 　たもつことないように。<br/>',NULL,51478,7);
INSERT INTO stanza VALUES('J545','8','つぶやき,うらみないよう, ながくだきとうとばせよ;<br/>どんなえきにもまさって, 　損しつおもんじさせよ。<br/>',NULL,51479,8);
INSERT INTO stanza VALUES('J546','1','御子とわれらひとつに なるをかみねがう;<br/>つくり変えるみわざは そのれいによる。<br/>',NULL,51480,1);
INSERT INTO stanza VALUES('J546','chorus','われらの思,意,感,を ながみかたちに;<br/>れいもてしみ通り, すべて満たせや。<br/>',NULL,51481,2);
INSERT INTO stanza VALUES('J546','2','みかみのいのちにより， さいせいされり;<br/>さらにつくり変えよや， たましいのうち。<br/>',NULL,51482,3);
INSERT INTO stanza VALUES('J546','3','れいよりそとに向かい， たましいにまで，<br/>まったき支はいなるまで あらたにせよや。<br/>',NULL,51483,4);
INSERT INTO stanza VALUES('J546','4','いのちのたい能により つくり変えたもう;<br/>栄光からえいこうへと 御子のかたちに。<br/>',NULL,51484,5);
INSERT INTO stanza VALUES('J546','5','聖べつし,つくり変えて, 円じゅくする主は,<br/>たましいをせん有して, からだあがなう。<br/>',NULL,51485,6);
INSERT INTO stanza VALUES('J547','1','われもがかず, 明けわたす,<br/>われ安そくし, ちから得る。<br/>善の意志捨て, 霊にしたがう,<br/>つみ解放され, 勝利を得る。<br/>',NULL,51486,1);
INSERT INTO stanza VALUES('J547','2','文字によらず, れいにより,<br/>われ義とされ, いのち得る。<br/>おしえでなく, あぶら塗り,<br/>われを照らし, まじわらす。<br/>',NULL,51487,2);
INSERT INTO stanza VALUES('J547','3','けつ意でなく, あわれみで,<br/>さい高の豊富, めぐみ得る。<br/>くるしい環境, 経過さすは,<br/>知恵ではなく, 主のめぐみ。<br/>',NULL,51488,3);
INSERT INTO stanza VALUES('J547','4','世からすくい, 生かすのは,<br/>かく言でなく, 主のけん能。<br/>御むね,使めい, 果たすのは,<br/>さい能でなく, かみのれい。<br/>',NULL,51489,4);
INSERT INTO stanza VALUES('J548','1','しゅくふくのふく音！ 世のひとをすくう;<br/>主の打たれたきず, やまいをいやす。<br/>',NULL,51490,1);
INSERT INTO stanza VALUES('J548','chorus','完ぜんなあがない, 主,世びとをすくう;<br/>主の打たれたきず, やまいをいやす。<br/>',NULL,51491,2);
INSERT INTO stanza VALUES('J548','2','だれがもとめても, 主は受け入れらる;<br/>やまいのまま行き, いやしを受ける。<br/>',NULL,51492,3);
INSERT INTO stanza VALUES('J548','3','しんせいなあぶら, めぐみをたまわる;<br/>主が御手を置けば, いやし,ながれる。<br/>',NULL,51493,4);
INSERT INTO stanza VALUES('J548','4','なが打たれたきず, われのきずいやし,<br/>サタンの火の矢の たてとなられる。<br/>',NULL,51494,5);
INSERT INTO stanza VALUES('J548','5','わがからだささげ, 栄こうなれに帰す;<br/>打たれた主のきず, とわにおぼえる。<br/>',NULL,51495,6);
INSERT INTO stanza VALUES('J549','1','主はまことの医者, 主の御名さん美す;<br/>たい能の主,われを かい放し,いやした。<br/>',NULL,51496,1);
INSERT INTO stanza VALUES('J549','chorus','主は権威ある医者, われ,すくい,いやす;<br/>主は多くのひとに いのちをあたえた。<br/>',NULL,51497,2);
INSERT INTO stanza VALUES('J549','2','しんこうもちいて, 主のことばしんじ,<br/>やまいのとこより いやされ,やすらぐ。<br/>',NULL,51498,3);
INSERT INTO stanza VALUES('J549','3','みころものすそに, しんじて触れれば,<br/>いのちはながれて, すぐにいやされる。<br/>',NULL,51499,4);
INSERT INTO stanza VALUES('J549','4','すくいぬしと大能, とう初と変わらず;<br/>やまいとざい過を 主はつねにになう。<br/>',NULL,51500,5);
INSERT INTO stanza VALUES('J549','5','いまだ得なくとも, 主,いやされたので,<br/>主はわれ生かすと, こころから信じる。<br/>',NULL,51501,6);
INSERT INTO stanza VALUES('J550','1','主が通られたとき, 　ひとは押し寄せた,<br/>おんなが主に触れると, 　 すぐいやされた。<br/>',NULL,51502,1);
INSERT INTO stanza VALUES('J550','chorus','触れれば,いやさる！ 　いま主ここにいる;<br/>うたがわず触れれば, 　 すぐいやされる。<br/>',NULL,51503,2);
INSERT INTO stanza VALUES('J550','2','ただ触れ,いやされ, 　おそれはなくなり,<br/>すべてのおも荷去る, 　 主のあしもとで。<br/>',NULL,51504,3);
INSERT INTO stanza VALUES('J550','3','ただ主に触れると, 　すべては成就する;<br/>えい遠にほめうたう, 　 いやされたゆえ。<br/>',NULL,51505,4);
INSERT INTO stanza VALUES('J550','4','ただ主に触れると, 　主は振り向かれる;<br/>不思議な目のあいに, 　 われは感動する。<br/>',NULL,51506,5);
INSERT INTO stanza VALUES('J550','5','ただ主に触れると, 　かならずいやさる,<br/>いかなるやまいでも, 　 いま,いやされる。<br/>',NULL,51507,6);
INSERT INTO stanza VALUES('J551','1','主はいのりのアルフア, 　 霊はおしえる;<br/>いかにいのるべきか, 　れいはみちびく。<br/>',NULL,51508,1);
INSERT INTO stanza VALUES('J551','2','主はいのりのオメガ, 　 いのりの内容,<br/>わがいのり,やむとき, 　かみは「アｰメン」する。<br/>',NULL,51509,2);
INSERT INTO stanza VALUES('J551','3','アルフアでオメガの主, 　 いのることば,<br/>つたないことばもて, 　御むねいのらす。<br/>',NULL,51510,3);
INSERT INTO stanza VALUES('J551','4','主よ,われのいのりが, 　 主とけつ合し,<br/>みこころのねがいを 　いのり出させよ。<br/>',NULL,51511,4);
INSERT INTO stanza VALUES('J551','5','主よ,われのいのりを 　 いのりはじめ,<br/>はっきりしないいのり, 　終わりとなれや。<br/>',NULL,51512,5);
INSERT INTO stanza VALUES('J552','1','いのりは,れいのなかで たかれたせいなるこう;<br/>くだかれたひととおし, 信こうもてささげらる。<br/>',NULL,51513,1);
INSERT INTO stanza VALUES('J552','2','いのりとはこうりょうに, 信仰,苦難,愛,混ぜたもの;<br/>かおりに満ちるものを, かみはあまさ鑑賞する。<br/>',NULL,51514,2);
INSERT INTO stanza VALUES('J552','3','いのりは水じょう気のよう, 天にのぼり,あめとなり,<br/>かわいた地をうるおし, 砂ばくにはな,咲かせる。<br/>',NULL,51515,3);
INSERT INTO stanza VALUES('J552','4','いのりとはきんのくだ, しょく台にあぶら供給す;<br/>ひとつこころのいのり, 霊満たし,ひかりはなつ。<br/>',NULL,51516,4);
INSERT INTO stanza VALUES('J552','5','いのりはかみのちから, かみのダィナマィトであり,<br/>大のうの御手うごかし, 大きな輪を地でまわす。<br/>',NULL,51517,5);
INSERT INTO stanza VALUES('J552','6','主よ,感動されていのる 霊のいのり,おしえませ！<br/>わがうちのキリストが, 天のキリストにいのる。<br/>',NULL,51518,6);
INSERT INTO stanza VALUES('J553','1','主よ,御まえにしずまり, 全そん在をうちに置く;<br/>自ぶんの方法でいのらず, れいのかんかく発表す。<br/>',NULL,51519,1);
INSERT INTO stanza VALUES('J553','2','主,てんで聞くようなれど, 主はわれのうちに住む;<br/>われ,主にいのるようなれど, 主がわがうちで発表す。<br/>',NULL,51520,2);
INSERT INTO stanza VALUES('J553','3','ときにことばなくても, れいにしたがい,うめく;<br/>こいもとめるのではなく, 主がわがうちで発表す。<br/>',NULL,51521,3);
INSERT INTO stanza VALUES('J553','4','われはなれを吸い込み, 食べ,飲み,供きゅう受ける;<br/>われは真に主とまじわり, 主はわがうちで発表す。<br/>',NULL,51522,4);
INSERT INTO stanza VALUES('J553','5','まじわりでひかり受け, 照らされ,血であらわれ,<br/>われを照らすだけでなく, 主はめいかくに発表す。<br/>',NULL,51523,5);
INSERT INTO stanza VALUES('J553','6','ここで主のあぶら塗り, わがうちくまなく塗る;<br/>われ減少し,主は増加して, 主はいや増しに発表す。<br/>',NULL,51524,6);
INSERT INTO stanza VALUES('J553','7','主にひらき,ちゅう入され, 主をひとにながし出す;<br/>ながれのなかでまじわり, なれをゆたかに発表す。<br/>',NULL,51525,7);
INSERT INTO stanza VALUES('J554','1','いのり,おしえませ！ てき,追いはらい,<br/>そのけん勢しばり, 捕虜解くこと。<br/>',NULL,51526,1);
INSERT INTO stanza VALUES('J554','2','いのり,おしえませ！ てき,打ちやぶり,<br/>てき地に攻め込み, 対処すること。<br/>',NULL,51527,2);
INSERT INTO stanza VALUES('J554','3','いのり,おしえませ！ 血しおのもとで,<br/>最高の主,理解させ, 権威持つこと。<br/>',NULL,51528,3);
INSERT INTO stanza VALUES('J554','4','いのりと信仰もて, 主とどう労する;<br/>万ぶつはわがもの, 権威もちいる。<br/>',NULL,51529,4);
INSERT INTO stanza VALUES('J555','1','ひとつこころで ともにあつまる;<br/>さい司のたい系, ともにつかえる。<br/>',NULL,51530,1);
INSERT INTO stanza VALUES('J555','chorus','われらはいのり, 主の最高に触れ,<br/>れいにて調和し, 召かい建造する。<br/>',NULL,51531,2);
INSERT INTO stanza VALUES('J555','2','われらさい司は つとめを果たし,<br/>れいにて御むね, かんせいさせる。<br/>',NULL,51532,3);
INSERT INTO stanza VALUES('J555','3','至せい所に入り, 主の御座に触れ,<br/>なれとかたって, なれ通過させる。<br/>',NULL,51533,4);
INSERT INTO stanza VALUES('J555','4','めぐみのかわは, 御座よりながれ,<br/>われをうるおし, てき時たすける。<br/>',NULL,51534,5);
INSERT INTO stanza VALUES('J555','5','われらのいのり, 主の霊の発ぴょう;<br/>わが意志でなく, なが意志による。<br/>',NULL,51535,6);
INSERT INTO stanza VALUES('J555','6','日々の生かつで, 主にもとめるは,<br/>なれがみちを得, 御むね成すこと。<br/>',NULL,51536,7);
INSERT INTO stanza VALUES('J555','7','主をあおぎ見て, 生けるみず飲む;<br/>めぐみ受ければ, 主,はたらかれる。<br/>',NULL,51537,8);
INSERT INTO stanza VALUES('J556','1','至せい所に入り, まくのうちで生き,<br/>めぐみの座に触れ, 生けるみず通す。<br/>',NULL,51538,1);
INSERT INTO stanza VALUES('J556','2','わが霊,至せい所, 主はわが霊に住む;<br/>ただ霊にいるなら, かれにまみえる。<br/>',NULL,51539,2);
INSERT INTO stanza VALUES('J556','3','復かつのかおり, 霊にありはなたれ,<br/>霊にあるいのりで, 主を発ぴょうする。<br/>',NULL,51540,3);
INSERT INTO stanza VALUES('J556','4','ひかりと糧しょく, 主の豊富きょう受し,<br/>復かつのかおりが それにくわわる。<br/>',NULL,51541,4);
INSERT INTO stanza VALUES('J556','5','さらに主に触れ, ますます主を得る;<br/>いのちの法そくと, マナとして得る。<br/>',NULL,51542,5);
INSERT INTO stanza VALUES('J556','6','復かつに触れて, 枯れたつえ,芽吹く;<br/>ここに御座があり, めぐみながれる。<br/>',NULL,51543,6);
INSERT INTO stanza VALUES('J556','7','あつまり,いのり, 霊,解放し,調和する,<br/>そこは至せい所で, われ,主に触れる。<br/>',NULL,51544,7);
INSERT INTO stanza VALUES('J556','8','この至せい所で, 祭司のせいかつし,<br/>御座に多面で触れ, みず,ながし出す。<br/>',NULL,51545,8);
INSERT INTO stanza VALUES('J557','1','至せい所のうちに入り, 御座に触れましょう;<br/>かわのようみめぐみが, ながれ出るでしょう。<br/>ハレルヤ！ハレルヤ！ ながれ出るめぐみ;<br/>かわのよう,めぐみが ながれ出るでしょう。<br/>',NULL,51546,1);
INSERT INTO stanza VALUES('J557','2','至せい所のうちに入り, 御かお,はいしましょう。<br/>わたしからえいこうが, かがやき出るでしょう。<br/>ハレルヤ！ハレルヤ！ わたしをとおして,<br/>えい光のみひかり, かがやき出るでしょう。<br/>',NULL,51547,2);
INSERT INTO stanza VALUES('J557','3','れいのなかにもどって, こうをたきましょう。<br/>わきあがるいーのちの いずみに触れましょう。<br/>ハレルヤ！ハレルヤ！ 生ける主のいずみ,<br/>わき出るいのちの いずみに触れましょう。<br/>',NULL,51548,3);
INSERT INTO stanza VALUES('J558','1','まく裂かれ,生ける みちひらかれ,<br/>血によりだい胆に 臨ざいに入る。<br/>',NULL,51549,1);
INSERT INTO stanza VALUES('J558','2','あがないの血にて, 至聖所に入る;<br/>あぶら塗りにより, 御座に触れる。<br/>',NULL,51550,2);
INSERT INTO stanza VALUES('J558','3','その霊にしたがい, 香たき,いのる;<br/>主は霊にて香のよう, あらわれ出る。<br/>',NULL,51551,3);
INSERT INTO stanza VALUES('J558','4','あわれみとめぐみ, 御座より出る;<br/>時機を得たたすけ, われにおよぶ。<br/>',NULL,51552,4);
INSERT INTO stanza VALUES('J558','5','ものごと請わずに, れいでいのる;<br/>主はひつよう知り, かえりみたもう。<br/>',NULL,51553,5);
INSERT INTO stanza VALUES('J558','6','しんぱいあるとも, もうなやまず;<br/>主に明けわたして, 霊は自由得る。<br/>',NULL,51554,6);
INSERT INTO stanza VALUES('J558','7','専いつに霊にあり 主とまじわり,<br/>その霊にしたがい, 主に香をたく。<br/>',NULL,51555,7);
INSERT INTO stanza VALUES('J559','1','全能の御名により, 　御座にひれ伏し,<br/>くらやみをやぶり, 　火の矢,打ち消す。<br/>',NULL,51556,1);
INSERT INTO stanza VALUES('J559','chorus','ぜん能の御名！ 　この御名で勝利！<br/>ぜん能の御名で, 　死とサタンに勝利！<br/>',NULL,51557,2);
INSERT INTO stanza VALUES('J559','2','御名にていのれば, 　サタンはいぼくす;<br/>イェス,イェス,大いなる 　御名,しょう利得る！<br/>ぜん能の御名！ 　この御名で勝利！<br/>ぜん能の御名で, 　死とサタンに勝利！<br/>',NULL,51558,3);
INSERT INTO stanza VALUES('J559','3','しゅくふくのめい令, 　王こくへと召し,<br/>全能のイェスの名は, 　御座にもたらす。<br/>ぜん能の御名！ 　この御名で勝利！<br/>ぜん能の御名で, 　死とサタンに勝利！<br/>',NULL,51559,4);
INSERT INTO stanza VALUES('J560','1','「うみにうつれ！」と, 　やまに対し言え;<br/>うたがわないなら, 　かならず成就す。<br/>ことば成ると信じ, なれのやまに命ぜよ！<br/>',NULL,51560,1);
INSERT INTO stanza VALUES('J560','2','御血で買われた 　すくいの権利取れ;<br/>三いちのかみは, 　権利を有効にす。<br/>主のことばにより, なれのやまに命ぜよ！<br/>',NULL,51561,2);
INSERT INTO stanza VALUES('J560','3','自己,つみ,やまい, 　主はみなになう;<br/>かみの要求満ち, 　なれ,解放された;<br/>みことばに信頼し, なれのやまに命ぜよ！<br/>',NULL,51562,3);
INSERT INTO stanza VALUES('J560','4','城へきをまわり, 　信仰にていのる;<br/>くずれるまえに, 　勝利を宣言する。<br/>成るとかたく信じ, なれのやまに命ぜよ！<br/>',NULL,51563,4);
INSERT INTO stanza VALUES('J560','5','銅とてつの門を 　みな打ちやぶり,<br/>信仰の戦士らは, 　凱歌もて進入す。<br/>てきに目をとめず, なれのやまに命ぜよ！<br/>',NULL,51564,5);
INSERT INTO stanza VALUES('J560','6','主の信仰を取り, 　不信仰脱ぎ去れ;<br/>奇せきのつえは, 　言いわけ追い出す;<br/>主のことばに立ち, なれのやまに命ぜよ！<br/>',NULL,51565,6);
INSERT INTO stanza VALUES('J561','1','「信じ,いのれ」,御名にて 御座に来ていのる;<br/>信じて主のこたえ聞け: 「見よ,すでに成就す」｡<br/>',NULL,51566,1);
INSERT INTO stanza VALUES('J561','2','「信じ,いのれ」,せい霊に 織り込まれ,いのれ；<br/>おもいをはるかに超え, 主は不思議を成す。<br/>',NULL,51567,2);
INSERT INTO stanza VALUES('J561','3','「信じ,いのれ」,しん仰に かたく立ち,いのる;<br/>のぞみ,よろこびあふれ, もろ手,主に挙げる。<br/>',NULL,51568,3);
INSERT INTO stanza VALUES('J561','4','「信じ,いのれ」,信仰もて いのるを主は待つ;<br/>まったき信仰はいつでも 主をよろこばせる。<br/>',NULL,51569,4);
INSERT INTO stanza VALUES('J562','1','信仰のうたうたえ！ 　 くらき夜にも;<br/>ながさん美にこたえ, 　 かみ,はたらき,<br/>なが信じることを, かみはかなえたもう。<br/>',NULL,51570,1);
INSERT INTO stanza VALUES('J562','2','信仰のうたうたえ！ 　 ほめたたえよ;<br/>そは,かみ信仰のうた 　 よろこぶゆえ;<br/>いかに夜ながくも, しん仰もてうたえや。<br/>',NULL,51571,2);
INSERT INTO stanza VALUES('J562','3','信仰のうたうたえ！ 　 てき,ふるえる;<br/>ながくちをあく魔に 　 閉ざさせるな;<br/>さん美はもともと あく魔に勝つなれば。<br/>',NULL,51572,3);
INSERT INTO stanza VALUES('J562','4','信仰のうたうたえ！ 　 あさ間ぢかし;<br/>尽きない賛美のうた, 　 やがてうたう;<br/>うたいつつ行きて, われら主にまみえる。<br/>',NULL,51573,4);
INSERT INTO stanza VALUES('J563','1','ひとつこころもて, 霊のなかでいのる;<br/>あぶらを塗られて, みこころ果たす。<br/>おもいによらずに, 霊のなかでいのり,<br/>あぶらを塗られて, みこころ果たす。<br/>',NULL,51574,1);
INSERT INTO stanza VALUES('J563','2','ひとつこころもて, 霊のなかでいのる;<br/>おのれをいなめや, 十字架によって。<br/>自ぶんのおもいと すべてのねがいを,<br/>うちなるその霊に かん理をさせよ。<br/>',NULL,51575,2);
INSERT INTO stanza VALUES('J563','3','ひとつこころもて, 霊のなかでいのる;<br/>われら,てんに座し, 権威をもちいて。<br/>この世の利とくを あしのしたに踏み,<br/>空中のかしらなる あく魔を攻めよ。<br/>',NULL,51576,3);
INSERT INTO stanza VALUES('J563','4','ひとつこころもて, 霊のなかでいのれ;<br/>せい徒らとともに, いのりもとめよ。<br/>御むねとみちびき, たゆまずたずねて,<br/>霊のなかの平和を 永えんにたもて。<br/>',NULL,51577,4);
INSERT INTO stanza VALUES('J563','5','ひとつこころもて, 霊のなかでいのれ;<br/>絶えず目を覚まし, いのりつづけよ。<br/>かみのおうこくと えいこうのために,<br/>目を覚ましいのれ, じょう就するまで。<br/>',NULL,51578,5);
INSERT INTO stanza VALUES('J563','6','ひとつこころもて, 霊のなかでいのれ;<br/>いちのなか和合し, かみにたずねよ。<br/>からだのれいにて, ひとつこころもて,<br/>えいえんにいのり, みこころ果たす。<br/>',NULL,51579,6);
INSERT INTO stanza VALUES('J564','1','つねにれいにていのれ, にく,おもいでなく！<br/>この秘けつ,実こうして, かみの臨ざい得る。<br/>',NULL,51580,1);
INSERT INTO stanza VALUES('J564','chorus','つねに霊でいのるは, 主のあたえた秘けつ;<br/>霊にてかみに触れるは, たもつべき秘けつ。<br/>',NULL,51581,2);
INSERT INTO stanza VALUES('J564','2','つねにれいにていのれ, わがおもいでなく;<br/>かみの霊とまじわれば, そのあじわい得る。<br/>',NULL,51582,3);
INSERT INTO stanza VALUES('J564','3','つねにれいにていのれ, みこころ発ぴょうす;<br/>霊にて主とともにいて, 全存ざい燃やさる。<br/>',NULL,51583,4);
INSERT INTO stanza VALUES('J564','4','つねにれいにていのれ, うちよりうめいて！<br/>そのれいのみちびきで, みこころ発ぴょうす。<br/>',NULL,51584,5);
INSERT INTO stanza VALUES('J564','5','つねにれいにていのれ, かみの至せい所で;<br/>れいのなかにいてこそ, かみとちょう和する。<br/>',NULL,51585,6);
INSERT INTO stanza VALUES('J564','6','つねにれいにていのれ, そは唯いつのみち;<br/>この秘けつをとおして, 全ほう満,受け継ぐ。<br/>',NULL,51586,7);
INSERT INTO stanza VALUES('J565','1','めぐみの御座に いのって触れる;<br/>めぐみとあわれみ, たすけ得るため。<br/>',NULL,51587,1);
INSERT INTO stanza VALUES('J565','2','御座に触れつつ, めぐみあじわう;<br/>かおとかお合わせ, 霊にてまじわる。<br/>',NULL,51588,2);
INSERT INTO stanza VALUES('J565','3','御座に触れつつ, めぐみのとみを,<br/>絶えず受け,享受し, 感謝し,賛美する。<br/>',NULL,51589,3);
INSERT INTO stanza VALUES('J565','4','支はいの御座に, いのって触れる;<br/>主の御名のなかで, あく魔対処する。<br/>',NULL,51590,4);
INSERT INTO stanza VALUES('J565','5','御座に触れつつ, 生ける信仰持つ;<br/>天の権威をもちい, 死の権勢,対処す。<br/>',NULL,51591,5);
INSERT INTO stanza VALUES('J565','6','ハデスのちから, いのり,揺るがす;<br/>御座の王権もちい, 主にありいのる。<br/>',NULL,51592,6);
INSERT INTO stanza VALUES('J566','1','かつていのり, もとめたが,<br/>いのるときには 霊もちいず;<br/>われはねがう, 霊をくんれんし,<br/>その霊にしたがい いのること。<br/>',NULL,51593,1);
INSERT INTO stanza VALUES('J566','2','いまは霊にて うめきつつ,<br/>れいの感かくに したがいたし。<br/>おもいでなく,　 賛美もいのりも,<br/>れいのみちびきに したがいたし。<br/>',NULL,51594,2);
INSERT INTO stanza VALUES('J566','3','ひとりのとき, 霊をもちい,<br/>ともにいのるも, 霊もちいる。<br/>霊をつかえば, 　 れいとれいとが,<br/>うちなるふかみで 呼おうする。<br/>',NULL,51595,3);
INSERT INTO stanza VALUES('J566','4','奉仕するとき, いのりもて,<br/>くちだけでなく, 霊もちいる。<br/>ともにいのり, れいでまじわり,<br/>うちなるふかみで 混ざり合う。<br/>',NULL,51596,4);
INSERT INTO stanza VALUES('J566','5','どこにいても, 霊をもちい,<br/>多ぜい,少数でも, 霊でいのる。<br/>とき,場所,ひと, えいきょうされず,<br/>どのしゅうかいでも 霊,かい放す。<br/>',NULL,51597,5);
INSERT INTO stanza VALUES('J566','6','霊,たかまれば 主,みちを得,<br/>霊がつよければ やくに立つ;<br/>生けるみずの ながれのなかで,<br/>聖徒らはちょう和し, 建造される。<br/>',NULL,51598,6);
INSERT INTO stanza VALUES('J567','1','真のいのりとは, 主,発表すること;<br/>啓示されたこと, いのり,発表する。<br/>',NULL,51599,1);
INSERT INTO stanza VALUES('J567','2','みこころ,かたり, 主を発ぴょうする;<br/>主のおもい知り, 主とちょう和する。<br/>',NULL,51600,2);
INSERT INTO stanza VALUES('J567','3','主をあおぎ見て, 主を発ぴょうする;<br/>かがみのように, えい光をうつす。<br/>',NULL,51601,3);
INSERT INTO stanza VALUES('J567','4','主にかたらせて, 主を発ぴょうする;<br/>わがうちの主が, 天の主にいのる。<br/>',NULL,51602,4);
INSERT INTO stanza VALUES('J567','5','自己によらずに, 主を発ぴょうする;<br/>まったく主に向き, 主によりいのる。<br/>',NULL,51603,5);
INSERT INTO stanza VALUES('J568','1','主とまじわるため, れいをもちいて,<br/>主の御かおたずね, 臨ざいもとめる。<br/>',NULL,51604,1);
INSERT INTO stanza VALUES('J568','chorus','かおおおいなしに, 主を見つめつつ,<br/>かくれたところで, ひたすらいのる。<br/>',NULL,51605,2);
INSERT INTO stanza VALUES('J568','2','主とまじわるため, うちをひらいて,<br/>真じつとまことで, 単いつにいのる。<br/>',NULL,51606,3);
INSERT INTO stanza VALUES('J568','3','主とまじわるため, れいにていのる；<br/>信こうもてもとめ, 主を待ちのぞむ。<br/>',NULL,51607,4);
INSERT INTO stanza VALUES('J568','4','霊としんじつもて, 主とまじわりし,<br/>れいのかんかくに したがい，いのる。<br/>',NULL,51608,5);
INSERT INTO stanza VALUES('J568','5','主のかたりかけを せつにもとめる;<br/>主のこころを知って, 御むねをいのる。<br/>',NULL,51609,6);
INSERT INTO stanza VALUES('J568','6','御かおのかがやき, われを照らして,<br/>われにしんとうし, えい光かがやく。<br/>',NULL,51610,7);
INSERT INTO stanza VALUES('J569','1','いのりで同労し, みちをそなえる;<br/>主とともにうごき, そのみちあゆむ。<br/>',NULL,51611,1);
INSERT INTO stanza VALUES('J569','2','いのりで同労し, 御むねにふくす;<br/>主とけつごうして, しゅくふく満たす。<br/>',NULL,51612,2);
INSERT INTO stanza VALUES('J569','3','いのりで同労し, 野しんを捨てる;<br/>自己をきょぜつして, 御むねのみ見る。<br/>',NULL,51613,3);
INSERT INTO stanza VALUES('J569','4','いのりで同労し, はじめてもらう;<br/>計かくはたらきは, われ通し成就す。<br/>',NULL,51614,4);
INSERT INTO stanza VALUES('J569','5','いのりで同労し, 車輪をうごかす;<br/>主とともにいのり, 召かいはふくす。<br/>',NULL,51615,5);
INSERT INTO stanza VALUES('J570','1','主のためサタンと いま,たたかう;<br/>サタンのぼうがいで いのりやめず;<br/>さらにいのり, われら勝利す,<br/>主にかたるなら, 主,こたえる。<br/>',NULL,51616,1);
INSERT INTO stanza VALUES('J570','chorus','主にかたるなら, 主,こたえる;<br/>主にかたるなら, 主,こたえる。<br/>試れんのとき, 主にひとこと<br/>かたるなら,すぐ 主,こたえる。<br/>',NULL,51617,2);
INSERT INTO stanza VALUES('J570','2','みちはけわしくて, 風雨に出会い,<br/>試れんはかさなり, 心ぱいあるも,<br/>主の大能にて, 瞬時にしょう利,<br/>主にかたるなら, 主,こたえる。<br/>',NULL,51618,3);
INSERT INTO stanza VALUES('J570','3','ともはこうげきし, われ,見捨てる,<br/>誤かいされ,よわり, 寄る辺もない,<br/>主にかたれば, なぐさめ得る;<br/>主にかたるなら, 主,こたえる。<br/>',NULL,51619,4);
INSERT INTO stanza VALUES('J570','4','主とあまくかたり, なやみはなし,<br/>主のむねに抱かれ, 主に安そくす;<br/>ほめうたいつ, あかしをする:<br/>主にかたるなら, 主,こたえる。<br/>',NULL,51620,5);
INSERT INTO stanza VALUES('J571','1','ともなる主イェスは, わがつみにない,<br/>どんななやみうれいも 聞いてくださる。<br/>へいあんうしない, 苦なんあるとき,<br/>みな主に持ち出し, したしくかたる。<br/>',NULL,51621,1);
INSERT INTO stanza VALUES('J571','2','苦なんやもんだい, ゆうわくあるが,<br/>しつぼうせずただ いのりもとめる。<br/>わがおも荷を負う しんじつな主は,<br/>よわさを知るゆえ, ただ主にいのる。<br/>',NULL,51622,2);
INSERT INTO stanza VALUES('J571','3','おも荷負い,よわく, つかれていても,<br/>主,わが避けどころ, ただ主にいのる。<br/>したしいともらが われを捨てても,<br/>ただ主にいのって, なぐさめを得る。<br/>',NULL,51623,3);
INSERT INTO stanza VALUES('J572','1','主に告げる,わが苦なん, うちにあるおも荷を;<br/>なぐさめに満ちる主は, ぬぐわれる,なみだを。<br/>',NULL,51624,1);
INSERT INTO stanza VALUES('J572','chorus','主に告げる,主に告げる, ひとりではになえず;<br/>わがこころ主は知って, なぐさめをあたえる。<br/>',NULL,51625,2);
INSERT INTO stanza VALUES('J572','2','主に告げる,わがこん難, 耐えがたきなやみを;<br/>わがすべてになう主は, あんそくをあたえる。<br/>',NULL,51626,3);
INSERT INTO stanza VALUES('J572','3','主に告げる,わがけつ乏, しんぱいとかなしみ;<br/>わがひつ要,満たす主は, ほう富を享受させる。<br/>',NULL,51627,4);
INSERT INTO stanza VALUES('J572','4','主に告げる,よくぼうに 打ち勝てぬよわさを;<br/>かいほうす,しょう利の主, つみのかせより解く。<br/>',NULL,51628,5);
INSERT INTO stanza VALUES('J572','5','主に告げる,こころみを, たんどくで勝てない;<br/>おなじようためされた主, いましょう利,得させる。<br/>',NULL,51629,6);
INSERT INTO stanza VALUES('J573','1','さい司のつとめは しんせいで高しょう;<br/>つねにかみをあおぎ, 　かみに香たく！<br/>',NULL,51630,1);
INSERT INTO stanza VALUES('J573','chorus','かみに香たく！ つねに香たく！<br/>ともし火あかるくし, かみにうたう！<br/>',NULL,51631,2);
INSERT INTO stanza VALUES('J573','2','せい所のひかりは, ともし火のひかり,<br/>さい司はこうをたき, 　しょく台ともす！<br/>',NULL,51632,3);
INSERT INTO stanza VALUES('J573','3','かみの美とくほめ, かんしょうするため,<br/>さい司はこうをたき, 　かみにうたう！<br/>',NULL,51633,4);
INSERT INTO stanza VALUES('J573','4','復かつのかおりを いのりとしささげ,<br/>かみはともに享受し, かんしょうする。<br/>',NULL,51634,5);
INSERT INTO stanza VALUES('J573','5','みことば読むとき, わがうちを照らし,<br/>ともし火はともって, 　ひかり満ちる。<br/>',NULL,51635,6);
INSERT INTO stanza VALUES('J573','6','しい歌で主をほめ, さい司のよううたう;<br/>あいとめぐみの主を 　まんきつする。<br/>',NULL,51636,7);
INSERT INTO stanza VALUES('J573','7','いのりで香をたき, せい書でひかり得,<br/>しい歌でさん美して, その霊ながす。<br/>',NULL,51637,8);
INSERT INTO stanza VALUES('J574','1','主よ,いま待ちのぞむ; 主の安そくと,<br/>主のこころを, われはいのり,<br/>主を待つ,主を待つ。<br/>',NULL,51638,1);
INSERT INTO stanza VALUES('J574','2','主よ,いま待ちのぞむ; なれを通して<br/>いのることを おしえたまえ;<br/>主を待つ,主を待つ。<br/>',NULL,51639,2);
INSERT INTO stanza VALUES('J574','3','主よ,いま待ちのぞむ; われと調和し,<br/>われに住みて, ながかたちを,<br/>ひょうげんさせよや。<br/>',NULL,51640,3);
INSERT INTO stanza VALUES('J574','4','主よ,いま待ちのぞむ; 御むね知らせ,<br/>主のいのちが ながれるため,<br/>ながみち行かせよ。<br/>',NULL,51641,4);
INSERT INTO stanza VALUES('J574','5','すべてのいのり通し, 主を発ぴょうし,<br/>かみ,栄こうを 受けられるよう,<br/>主を待つ,主を待つ。<br/>',NULL,51642,5);
INSERT INTO stanza VALUES('J575','1','われしずまり,主を待つ; まずかれにかたらせる。<br/>真のいのり,主がはじめ, われは主をはっ表する。<br/>',NULL,51643,1);
INSERT INTO stanza VALUES('J575','2','われしずまり,主を待つ; わがおもい,意志いなむ。<br/>かみにあぶら塗らせて, ただかれを生かし出す。<br/>',NULL,51644,2);
INSERT INTO stanza VALUES('J575','3','われしずまり,主を待つ; 自己いなみ,世を捨てる。<br/>自ぶんでみちを決めず, みこころをかえりみる。<br/>',NULL,51645,3);
INSERT INTO stanza VALUES('J575','4','われしずまり,主を待つ; わが霊にけい示しませ。<br/>おもいを霊にふくさせ, 従じゅんなしつ事となる。<br/>',NULL,51646,4);
INSERT INTO stanza VALUES('J575','5','われしずまり,主を待つ; 霊にわれをつう過させ,<br/>れいと混ざり,いのって, かみのはっぴょうとなる。<br/>',NULL,51647,5);
INSERT INTO stanza VALUES('J575','6','われしずまり,主を待つ; かみといちとなるまで。<br/>すべてで主に降ふくし, すべてで主のようになる。<br/>',NULL,51648,6);
INSERT INTO stanza VALUES('J575','7','われしずまり,主を待つ； かみを自ゆうにながす。<br/>わがことば,こうどうに， 御むねをじょう就させる。<br/>',NULL,51649,7);
INSERT INTO stanza VALUES('J576','1','おこしたまえ,主よ！ ながたみらを,<br/>みわざのため,なが権威もて, めいじたまえ。<br/>',NULL,51650,1);
INSERT INTO stanza VALUES('J576','chorus','リバイバルをば, いま待ちのぞむ;<br/>御まえにひれ伏すとき主よ, ちからたまえ。<br/>',NULL,51651,2);
INSERT INTO stanza VALUES('J576','2','おこしたまえ,主よ！ 召会を感動し,<br/>ペンテコステの火をもとめて, いのり燃やせ。<br/>',NULL,51652,3);
INSERT INTO stanza VALUES('J576','3','おこしたまえ,主よ！ たからを見せ,<br/>ねむるこころ燃え立たせよ, ながあいもて。<br/>',NULL,51653,4);
INSERT INTO stanza VALUES('J576','4','おこしたまえ,主よ！ 信仰によりて;<br/>ながことばのきよき真理を, 聞かせたまえ。<br/>',NULL,51654,5);
INSERT INTO stanza VALUES('J576','5','おこしたまえ,主よ！ てき絶やさせ;<br/>いくさに向かうときに,主よ, 勝利しめせや。<br/>',NULL,51655,6);
INSERT INTO stanza VALUES('J576','6','おこしたまえ,主よ！ リバイバルを;<br/>えい光すべて御名に帰して, しゅくふく得る。<br/>',NULL,51656,7);
INSERT INTO stanza VALUES('J577','1','主よ,この地をあたえませ, 復こうを地にあたえませ;<br/>さまたげ取り,れいたかめ, ひとをいやすものとなせ。<br/>',NULL,51657,1);
INSERT INTO stanza VALUES('J578','1','いのるときあまい！ なやみから解かれて,<br/>御座にすすみ出て, ひつ要をはっ表する;<br/>困なんはいのらせ, わが霊,自由にする;<br/>いのりのなかには, 主がおられるゆえに。<br/>',NULL,51658,1);
INSERT INTO stanza VALUES('J578','2','いのるときあまい！ ねがい,つばさに載せ,<br/>御座へともたらす; 主はしんじつ,実さい。<br/>「御かおもとめよ」と 言われる主のもと,<br/>わがおも荷,下ろす, あまきいのりにより！<br/>',NULL,51659,2);
INSERT INTO stanza VALUES('J578','3','いのるときあまい！ つねになぐさめ受く,<br/>ピスガにのぼりて, うるわしい地,見わたす;<br/>まく屋を脱ぐとき, のぞんだこと成就す;<br/>おおごえでさけぶ: 「いのるとき平安ある！」<br/>',NULL,51660,3);
INSERT INTO stanza VALUES('J579','1','せい書はかみのいぶき, かみの霊にて息吹かれた;<br/>かみ・ひと通して書かれ, かみの豊富,吸い込ませる。<br/>',NULL,51661,1);
INSERT INTO stanza VALUES('J579','2','いぶきはひかりとなり, 神せいなひかりで照らす;<br/>ひとの真のひつようと, 実さいのじょうたい見せる。<br/>',NULL,51662,2);
INSERT INTO stanza VALUES('J579','3','いぶきはいのちとなり, 神せいなせいしつ分与す;<br/>死人生かし,さいせいし, 更しんして,つくり変える。<br/>',NULL,51663,3);
INSERT INTO stanza VALUES('J579','4','いぶきは知恵となって, 神せいな知しきもたらす;<br/>とわのもくてきしめし, かみのゴｰルへとみちびく。<br/>',NULL,51664,4);
INSERT INTO stanza VALUES('J579','5','いぶきはちからとなり, 神せいなちから供きゅうす;<br/>ちからづけ,権威あたえ, かみの御むねじょう就する。<br/>',NULL,51665,5);
INSERT INTO stanza VALUES('J579','6','いま,いぶき呼きゅうする, かみのしゅくふくきょう受す;<br/>霊をかつ用し,呼きゅうし, かみの豊富をきょう受する。<br/>',NULL,51666,6);
INSERT INTO stanza VALUES('J580','1','かみはかたり,けい示して, 人位,性かく,ひとに知らす;<br/>啓示,予ひょう,預言を通して, みこころかん全に描写す。<br/>',NULL,51667,1);
INSERT INTO stanza VALUES('J580','2','かみはかたり,ひょう明した: 御子すべてのかしらとし,<br/>御子にありえい光を得て, 万ゆうにあらわれること。<br/>',NULL,51668,2);
INSERT INTO stanza VALUES('J580','3','かみはかたる,キリストを, かれは真のかみ,またひと,<br/>すべてのなかのすべてで, 計かくのすべてであると。<br/>',NULL,51669,3);
INSERT INTO stanza VALUES('J580','4','かみはすでにかたられた: しん人ちょう和のご計かく,<br/>ちち,子にあり,子,霊にあり, からだにありかん成する。<br/>',NULL,51670,4);
INSERT INTO stanza VALUES('J580','5','かみはおく義かたられた: キリスト,しょう会のいちを,<br/>キリスト,えい光のかしら, しょうかい,キリストの豊満。<br/>',NULL,51671,5);
INSERT INTO stanza VALUES('J580','6','かみはすでにかたられた: そうぞう,受にくをかたり,<br/>あがない,すくいを啓示す; 主のほめうた,地に満ちよ。<br/>',NULL,51672,6);
INSERT INTO stanza VALUES('J581','1','主,なれはかみのことば, かたち,ないよう,たから;<br/>かみのほう満,表げんし, 聖書にてあらわされる。<br/>',NULL,51673,1);
INSERT INTO stanza VALUES('J581','2','主以がい,かみ見られず, 聖書なしに啓示されず;<br/>なれはせい書とおして, ひとにご自身をしめす。<br/>',NULL,51674,2);
INSERT INTO stanza VALUES('J581','3','主,かみの化身,ほうまん, 聖書はこの主を描写す;<br/>聖書をとおし鑑しょうす, かみのしんのかたちを。<br/>',NULL,51675,3);
INSERT INTO stanza VALUES('J581','4','なれ,いのちの霊,ことば, ことばはれい,何と豊富;<br/>霊でことばをあじわい, 主のほう富にあずかる。<br/>',NULL,51676,4);
INSERT INTO stanza VALUES('J581','5','主にてかみとまじわる, 聖書により主を享受す;<br/>いのり読みでちかづき, わがひつよう満たさる。<br/>',NULL,51677,5);
INSERT INTO stanza VALUES('J581','6','霊をくん練し,享受する, いのり読みで供給受く;<br/>主とことばは調和して, 日々のりょうしょくとなる。<br/>',NULL,51678,6);
INSERT INTO stanza VALUES('J582','1','主はことば,またれいなり, 主とひとつ霊で唱和す！<br/>ことばの啓示を賛美し, れいのなかの主に触れる。<br/>',NULL,51679,1);
INSERT INTO stanza VALUES('J582','2','めぐみの主,なれはすべて, 主とけつごうしたゆえ;<br/>なれはことば,霊として, わがすべての供給となる。<br/>',NULL,51680,2);
INSERT INTO stanza VALUES('J582','3','なれ,ことばでないならば, なれを知るすべはない！<br/>なれ,れいでないならば, なれに触れるすべはない！<br/>',NULL,51681,3);
INSERT INTO stanza VALUES('J582','4','ことばは主をけい示して, われに主,認しきさせる;<br/>れいはなれのほんしつ, なれご自身に触れさせる。<br/>',NULL,51682,4);
INSERT INTO stanza VALUES('J582','5','主,わがいのち,ひかり,みち, しん理,生けるみず,かて;<br/>ことば,すべて伝たつし, 霊はわれにけい験させる。<br/>',NULL,51683,5);
INSERT INTO stanza VALUES('J582','6','主のことばは聖書にある, 主の霊は内じゅうする霊;<br/>ながことば,わがうちで れいであり,ことばである。<br/>',NULL,51684,6);
INSERT INTO stanza VALUES('J582','7','なれの聖書を理かいして, ながせい霊に触れたし;<br/>ただ知しきだけでなく, 霊により礼はいし,いのる。<br/>',NULL,51685,7);
INSERT INTO stanza VALUES('J582','8','われはながことばあいし, 霊はなが霊を礼拝する;<br/>ことばのなかで歓喜し， 霊のなかでれいはうたう。<br/>',NULL,51686,8);
INSERT INTO stanza VALUES('J583','1','いのちのパン,さきませ, うみ辺でさかれたように。<br/>生けることば,聖書にて, 主をしたい,追いもとむ！<br/>',NULL,51687,1);
INSERT INTO stanza VALUES('J583','2','いのちのパン,さきませ, 愛満たされ,御名,記念す！<br/>自己よりかい放されて, ただ主だけをもとめる。<br/>',NULL,51688,2);
INSERT INTO stanza VALUES('J583','3','真理がわれにひらかれ, みことば理かいさせる;<br/>主のおもいをあたえて, 栄光へとつくり変える。<br/>',NULL,51689,3);
INSERT INTO stanza VALUES('J583','4','主よ,あのパンさいたよう, 真理をしゅくふくしませ;<br/>世のくさりをくだいて, 自由に主のため生きる。<br/>',NULL,51690,4);
INSERT INTO stanza VALUES('J584','1','みことばください, 自我よりはなれさせ,<br/>なお主に信らいする みことばをください。<br/>',NULL,51691,1);
INSERT INTO stanza VALUES('J584','2','自己満ぞくのとき, われのよわさ見せて,<br/>無駄な労苦とかたる みことばをください。<br/>',NULL,51692,2);
INSERT INTO stanza VALUES('J584','3','わがこころに住み, わがいのちとなって,<br/>したしむ主を見せる みことばをください。<br/>',NULL,51693,3);
INSERT INTO stanza VALUES('J584','4','おそれ,なやむとき, ちからあるやくそく,<br/>ほそくささやくこえ, みことばをください。<br/>',NULL,51694,4);
INSERT INTO stanza VALUES('J584','5','しょう利を得させる やくそくをあたえて,<br/>あまき主と住み合う みことばをください。<br/>',NULL,51695,5);
INSERT INTO stanza VALUES('J585','1','こころしずめ, なれを待つ;<br/>期たいをもて, ことば聞く。<br/>',NULL,51696,1);
INSERT INTO stanza VALUES('J585','2','主よ,みことば かたりませ;<br/>御かお見つつ, なれに聞く。<br/>',NULL,51697,2);
INSERT INTO stanza VALUES('J585','3','ながことばは, れい,いのち;<br/>霊を供給する てんのパン。<br/>',NULL,51698,3);
INSERT INTO stanza VALUES('J585','4','われはすべて なれに帰す;<br/>降ふくすわれ, なれのもの。<br/>',NULL,51699,4);
INSERT INTO stanza VALUES('J585','5','しもべは聞く, かたりませ;<br/>生けることば, われは待つ。<br/>',NULL,51700,5);
INSERT INTO stanza VALUES('J585','6','ながことばで 満たしませ;<br/>御むねの成就, われ,ねがう。<br/>',NULL,51701,6);
INSERT INTO stanza VALUES('J585','7','いとかぐわしい そののよう,<br/>臨ざいのうち われ,生きる。<br/>',NULL,51702,7);
INSERT INTO stanza VALUES('J586','1','かわきしわがれいもて,<br/>ながみもとに来しわれ,<br/>主よ,なれをもて満たせ,<br/>わが飢え,わがかわきを。<br/>',NULL,51703,1);
INSERT INTO stanza VALUES('J586','chorus','しょくさせよ,飲ませよ,<br/>満たせ,わが飢えをば,<br/>いやせや,わがかわきを,<br/>よろこびにひたせや。<br/>',NULL,51704,2);
INSERT INTO stanza VALUES('J586','2','なれはマナ,生けるみず,<br/>われを生かし,つよめる;<br/>いのり読みもてなれを,<br/>しょくし,飲みてたのしむ。<br/>',NULL,51705,3);
INSERT INTO stanza VALUES('J586','3','なれ,かみのことばなり,<br/>いのちとなったれいなり;<br/>みことばとれいにより,<br/>マナとみずをたのしむ。<br/>',NULL,51706,4);
INSERT INTO stanza VALUES('J586','4','なれはてんからのマナ,<br/>打たれてながれたみず;<br/>マナはわれのきょうきゅう,<br/>みずはながれ出たれい。<br/>',NULL,51707,5);
INSERT INTO stanza VALUES('J586','5','なれはいのち,れいなり,<br/>しょくしうることばなり;<br/>わがれいになれは生き,<br/>ながれいにてわれ飲む。<br/>',NULL,51708,6);
INSERT INTO stanza VALUES('J586','6','ことばに来てたのしむ,<br/>わが飢えを満たすまで;<br/>れいのなかでもとめる,<br/>わがかわき満たすまで。<br/>',NULL,51709,7);
INSERT INTO stanza VALUES('J586','7','みことばによりしょくす,<br/>いのりにより,なれ飲む;<br/>読みいのりで食べ飽き,<br/>いのり読みで飲み飽く。<br/>',NULL,51710,8);
INSERT INTO stanza VALUES('J586','8','なれ,わがえんせきなり,<br/>ことば,れいもて満たせ;<br/>いんしょくによりわれは,<br/>ながゆたかをたのしむ。<br/>',NULL,51711,9);
INSERT INTO stanza VALUES('J587','1','めぐみの御座に来て, あわれみとめぐみ受ける;<br/>それはてき時のたすけ, こころと霊,あんそくす。<br/>',NULL,51712,1);
INSERT INTO stanza VALUES('J587','2','御かおのかがやきは, わがこころのなか照らし,<br/>いやすひかりはなちて, わがよわさを消し去る。<br/>',NULL,51713,2);
INSERT INTO stanza VALUES('J587','3','ながひかりは照らす, わがまことのじょうたいを;<br/>なが血しおの効き目は, わがつみすべてあらう。<br/>',NULL,51714,3);
INSERT INTO stanza VALUES('J587','4','なれはあぶら塗りで, ながせい分をつくり込む;<br/>われはご自身を享受し, ながみこころに触れる。<br/>',NULL,51715,4);
INSERT INTO stanza VALUES('J587','5','祭司が火をともすよう, 御まえでみことばを読む;<br/>ながれいはあぶらのよう, ことばのひかり,はなつ。<br/>',NULL,51716,5);
INSERT INTO stanza VALUES('J587','6','われらはいのるとき, さい司が香をたくように,<br/>れいにあり,キリストを, 香のようかみにささげる。<br/>',NULL,51717,6);
INSERT INTO stanza VALUES('J587','7','ことばはひかり,かて, われ照らされ,満ぞくする;<br/>さらに読み,さらに食べ, 啓示を受け,かてを得る。<br/>',NULL,51718,7);
INSERT INTO stanza VALUES('J587','8','なれはこう,またみず, われはつかれいやされる;<br/>おおくいのり,多く飲み, 香をささげ,みずながす。<br/>',NULL,51719,8);
INSERT INTO stanza VALUES('J587','9','ことば読み,いのれば, あかるくされ,満たされる;<br/>読みいのりで主を受け, いのり読みで主ながす。<br/>',NULL,51720,9);
INSERT INTO stanza VALUES('J587','10','いのり読みによりて, 主とまじわり,混ざり合う;<br/>主よ,われに浸とうして, われよりながれ出ませ！<br/>',NULL,51721,10);
INSERT INTO stanza VALUES('J588','1','わがこころは 飢えてかわく;<br/>なれを食べ飲みし, 享受させたまえ。<br/>',NULL,51722,1);
INSERT INTO stanza VALUES('J588','2','なれの御かお, 見るをしたう;<br/>れいのなかで触れ, まんぞくを得る。<br/>',NULL,51723,2);
INSERT INTO stanza VALUES('J588','3','栄光の御かお, 見てよろこぶ！<br/>つねにあおがせよ, ちかくにありて。<br/>',NULL,51724,3);
INSERT INTO stanza VALUES('J588','4','まじわりにて, 主,わがめぐみ！<br/>こころはよろこび, 霊は満たされる。<br/>',NULL,51725,4);
INSERT INTO stanza VALUES('J588','5','主をもとめる, なおもとめる！<br/>ことば,いのり読み, 主を浸透させる。<br/>',NULL,51726,5);
INSERT INTO stanza VALUES('J589','1','「ひとはパンだけでなく, かみのことばで生きる」,<br/>いのちのかてとし, つねにことば食べる。<br/>',NULL,51727,1);
INSERT INTO stanza VALUES('J589','2','ひとにはからだがあり, たましいとれいがある;<br/>霊はさい深の部分, かみを受ける部ぶん。<br/>',NULL,51728,2);
INSERT INTO stanza VALUES('J589','3','にくたいにはぶっしつの しょくもつがひつ要なよう;<br/>霊も天のしょくもつ, かみのことばひつ要。<br/>',NULL,51729,3);
INSERT INTO stanza VALUES('J589','4','主よ,なれはれい,ことば, なれを完全にあらわす;<br/>わが霊をかつ用し, ことば通し，霊受ける。<br/>',NULL,51730,4);
INSERT INTO stanza VALUES('J589','5','ながことば得るために, 目をもちい,ことば読み,<br/>おもいで理かいし, 霊をもちい吸収する。<br/>',NULL,51731,5);
INSERT INTO stanza VALUES('J589','6','霊のなかでことば食べ, 最深の部分に取り込む;<br/>霊でいのり読みし, 全存ざい,浸透される。<br/>',NULL,51732,6);
INSERT INTO stanza VALUES('J589','7','おもいで取ったことば, それはおも荷となるが,<br/>霊のなかで取れば, 霊,いのち,平安となる。<br/>',NULL,51733,7);
INSERT INTO stanza VALUES('J589','8','わがれいをくん練して, 主に触れることねがう;<br/>ことばのやしない, ご自身に触れさせる。<br/>',NULL,51734,8);
INSERT INTO stanza VALUES('J589','9','主よ,ことばを読むたび, いかに霊を訓練するか,<br/>主よ,われにおしえ, われをやしないませ。<br/>',NULL,51735,9);
INSERT INTO stanza VALUES('J590','1','キリストはことば,また霊, ことばのなかにある霊;<br/>かれのかたることばは, れいであり,いのちである。<br/>',NULL,51736,1);
INSERT INTO stanza VALUES('J590','2','かみはそとに聖書あたえ, うちに聖霊をあたえる;<br/>このさい大のたまもの, かみを供給し,エンジｮィさせる｡<br/>',NULL,51737,2);
INSERT INTO stanza VALUES('J590','3','聖書は聖霊にて表明され, 聖れいは聖書の実さい;<br/>ふたつはひとつの両面, えいえんに分けられない。<br/>',NULL,51738,3);
INSERT INTO stanza VALUES('J590','4','聖書は聖霊の照らしにて, わが霊に入るといのち;<br/>霊なく聖書を読むなら, むなしく,何の供給もない。<br/>',NULL,51739,4);
INSERT INTO stanza VALUES('J590','5','霊をもちいるとき聖書は, 霊となり,いのちとなる;<br/>れいがあらわれるとき, ことばとなり,供きゅうする。<br/>',NULL,51740,5);
INSERT INTO stanza VALUES('J590','6','われらの霊をかつ用して, 聖書をうちに受け取る;<br/>すると霊はかい放され, れいと聖書のいちを見る。<br/>',NULL,51741,6);
INSERT INTO stanza VALUES('J590','7','主よ,ことばがわがうちで, 霊といのちとなるように;<br/>ことばにあるなが霊が, わが真の発表となるように。<br/>',NULL,51742,7);
INSERT INTO stanza VALUES('J591','1','みことばはひとに いのち供きゅうし,<br/>かみの思想つたえ, かみを得させる。<br/>けい示だけでなく, いのちもたらし,<br/>おしえだけでなく, 主を供きゅうする。<br/>',NULL,51743,1);
INSERT INTO stanza VALUES('J591','2','文字,読むだけなら, 知しきにすぎず;<br/>霊でいのり読めば, いのち,じっさい。<br/>文字,知しきはただ 死,もたらすのみ;<br/>霊でことばを受け, われ,生かされる。<br/>',NULL,51744,2);
INSERT INTO stanza VALUES('J591','3','聖書,読むだけでは, むなしい知しき;<br/>れいで主に触れて, いのちを受ける。<br/>文字は,わがおもい きょう給するのみ;<br/>霊でいのり読みし, 主のいのち得る。<br/>',NULL,51745,3);
INSERT INTO stanza VALUES('J591','4','せい書の知しきを いのちに変える;<br/>あたまの理かいを 霊に形せいする。<br/>せい書の理かいを 霊のいのちとす;<br/>文字のにんしきを 霊に受け入れる。<br/>',NULL,51746,4);
INSERT INTO stanza VALUES('J591','5','ただ知しき得るは, エバのあやまち;<br/>サタンは知しき通し, つみ,おかさせる。<br/>いのちとして読み, いのちの木受く;<br/>それゆえ,ことばを れいで受け取る。<br/>',NULL,51747,5);
INSERT INTO stanza VALUES('J592','1','キﾘストの豊富エンジｮィし, われらその豊満となる;<br/>かれご自身のすべてに 　あずかりて表現す。<br/>',NULL,51748,1);
INSERT INTO stanza VALUES('J592','2','その豊富は主自身, われらのきょう受となる;<br/>かれの豊満はしょうかい, 　主をエンジｮィし,成就す。<br/>',NULL,51749,2);
INSERT INTO stanza VALUES('J592','3','主の豊富を予表す カナンの富む産ぶつもて,<br/>かみのみや建造するは, 　召会産しゅつ予表す。<br/>',NULL,51750,3);
INSERT INTO stanza VALUES('J592','4','アダムの豊満なる エバはアダムより出て,<br/>しょう会がキリストより 　出たことを予表す。<br/>',NULL,51751,4);
INSERT INTO stanza VALUES('J592','5','豊富はうちなる主, ほう満は外面の召かい;<br/>主に満たされた表現は, 　主と同様にとうとし。<br/>',NULL,51752,5);
INSERT INTO stanza VALUES('J593','1','キリスト,かみのおく義, かみを見たものはなし;<br/>されど,御子キリストは, われらにかみ,ひょうめいす。<br/>',NULL,51753,1);
INSERT INTO stanza VALUES('J593','2','キリスト,かみのことば, かみのしんのせつめい;<br/>かれはかみの具たい化, かみの本しつ,ひょうげんす。<br/>',NULL,51754,2);
INSERT INTO stanza VALUES('J593','3','キリスト,かみのほう満, かみの栄光のかがやき;<br/>かみの本しつのかたち, かれにあり,かみかがやく。<br/>',NULL,51755,3);
INSERT INTO stanza VALUES('J593','4','キリストはかくされて, ひとの目に見えないが,<br/>召かいはかれのおく義, ひとにキリストあらわす。<br/>',NULL,51756,4);
INSERT INTO stanza VALUES('J593','5','召会,キリストのほう満, かれは召かいのない容;<br/>召かい,キリストのコピｰ, ひとはしょう会に主を見る。<br/>',NULL,51757,5);
INSERT INTO stanza VALUES('J593','6','召会,キリストのかたち, かれのぞう加,かくだい;<br/>かれは召かいのすべて, しょうかいはかれのからだ。<br/>',NULL,51758,6);
INSERT INTO stanza VALUES('J593','7','ちち,御子のうちにあり, 御子いま,その霊と成る;<br/>三いちのかみのれいは, 召かいと調和され,ひとつ。<br/>',NULL,51759,7);
INSERT INTO stanza VALUES('J594','1','からだはひとの豊満, ひと,あらわす;<br/>しょうかいは主のからだ, 主をあらわす。<br/>',NULL,51760,1);
INSERT INTO stanza VALUES('J594','2','エバはアダムより出, かれのいち部;<br/>しょうかいはキリストの 増しくわわり。<br/>',NULL,51761,2);
INSERT INTO stanza VALUES('J594','3','地に落ち,死んだむぎ, 実をむすんで,<br/>こなにされ,混ざり合い, からだとなる。<br/>',NULL,51762,3);
INSERT INTO stanza VALUES('J594','4','主は死んで復かつし, 多くの子,生む;<br/>多くの子,からだとなり, 主をあらわす。<br/>',NULL,51763,4);
INSERT INTO stanza VALUES('J594','5','ぶどうのえだえだは 木のひろがり,<br/>木に住んで,むすぶ実は そのほうまん。<br/>',NULL,51764,5);
INSERT INTO stanza VALUES('J594','6','キリストの肢たいは 主のかくだい;<br/>主とひとつ,主に住んで, 主はぞう加す。<br/>',NULL,51765,6);
INSERT INTO stanza VALUES('J594','7','召かいは主のぞう加, 増しょく,ひょう現;<br/>けいぞく,余じょう,コピー, かくだい,豊満。<br/>',NULL,51766,7);
INSERT INTO stanza VALUES('J594','8','かみのあがなわれた ひとを通して,<br/>召かいはかみのえい光, ひょうげんする。<br/>',NULL,51767,8);
INSERT INTO stanza VALUES('J594','9','キリストと召かいは 偉大なおく義;<br/>しんせいとじんせいが 調和され,いち。<br/>',NULL,51768,9);
INSERT INTO stanza VALUES('J595','1','召会は主のうつわ, 主を内容とし,主を表現す;<br/>ひとのにくたいが, 　ひとを表現するように。<br/>',NULL,51769,1);
INSERT INTO stanza VALUES('J595','2','けいやくのはこが みやのない容であるように；<br/>召会はキリストを 　内容とし,住まわせる。<br/>',NULL,51770,2);
INSERT INTO stanza VALUES('J595','3','キリストはかみの おく義,またかみのひょう現;<br/>召会はキリストの 　おく義,かれの表げん。<br/>',NULL,51771,3);
INSERT INTO stanza VALUES('J595','4','召かいの肢たいは, もともとはつちのたぐい;<br/>再生され,変えられ, 　透明なたからとなる。<br/>',NULL,51772,4);
INSERT INTO stanza VALUES('J595','5','変えられ,建造され, 主の透明なうつわとなる;<br/>主の豊富をやどし, 　ひとにてあらわれる。<br/>',NULL,51773,5);
INSERT INTO stanza VALUES('J595','6','さんいちのかみは, つくり変えのわざ完成す;<br/>召会,うつわとなり, 　かみの住まいとなる。<br/>',NULL,51774,6);
INSERT INTO stanza VALUES('J595','7','召会は何ととうとい, かく面,透めいでかがやく;<br/>主とかみの豊満を 　かがやき出している。<br/>',NULL,51775,7);
INSERT INTO stanza VALUES('J595','8','かみはひかり,主は いのち,霊はみずのながれ;<br/>さんいちのかみは, 　召会にてあらわれる。<br/>',NULL,51776,8);
INSERT INTO stanza VALUES('J596','1','召かいはきんのしょく台, 主はそのともし火;<br/>しんせいなかがやきを, しょうかいはささげる。<br/>',NULL,51777,1);
INSERT INTO stanza VALUES('J596','2','しょく台はかみのいのち かがやかすゆえに,<br/>純金でかみの栄こうに ふさわしくあるように。<br/>',NULL,51778,2);
INSERT INTO stanza VALUES('J596','3','このくらき時だいにて 神せいなひかりは,<br/>多くのひとを照らして, ひとに主をあかしす。<br/>',NULL,51779,3);
INSERT INTO stanza VALUES('J596','4','純けつなあかしのため, 「はじめの愛」持てば,<br/>勝利者の分けまえなる 「いのちの木の実」受く。<br/>',NULL,51780,4);
INSERT INTO stanza VALUES('J596','5','はくがい,苦なんに耐え, 「いのちのかんむり」得,<br/>霊てき姦淫に打ち勝ち, 「かくされたマナ」得る。<br/>',NULL,51781,5);
INSERT INTO stanza VALUES('J596','6','イゼベルのわざを捨て, 支配する権威得る;<br/>死のけがれに打ち勝ち, 「しろいころも」を着る。<br/>',NULL,51782,6);
INSERT INTO stanza VALUES('J596','7','「ヒラデルヒヤ」のように 御名ことば,まもる;<br/>なまぬるさに打ち勝ち, 主とともにしょくする。<br/>',NULL,51783,7);
INSERT INTO stanza VALUES('J596','8','召会は純けつであって, 金のしょく台である;<br/>キリストを照らし出し, えいこうに満ち満つ。<br/>',NULL,51784,8);
INSERT INTO stanza VALUES('J596','9','いま,かく地の召かいは 地じょうのしょくだい,<br/>将らい,新エルサレムは, えいえんのしょくだい。<br/>',NULL,51785,9);
INSERT INTO stanza VALUES('J596','10','聖なる純きんのみやこ, しよくだいの完せい;<br/>主のともし火をささえ, えいえんにかがやく。<br/>',NULL,51786,10);
INSERT INTO stanza VALUES('J597','1','かみは創世のまえ, 御子にありえらび,<br/>子たる身分あたえ, 召会を聖となす。<br/>召会はかみの所有, 聖霊の証印受く,<br/>それは嗣業の担保, またまえあじわい。<br/>',NULL,51787,1);
INSERT INTO stanza VALUES('J597','2','キリスト昇天して, すべてに超えつし,<br/>ばんぶつのかしら, 召会そのからだ。<br/>かれ,万ゆう満たし, 召会はその豊満,<br/>しょう会はかん全に かれを表現する。<br/>',NULL,51788,2);
INSERT INTO stanza VALUES('J597','3','かつて,つみに死に, 世の潮流にならい,<br/>にくよくにふけり, サタンにしたがう。<br/>いまや主とともに 復かつ,昇てんし,<br/>ともにてんに座す けっさくとなる。<br/>',NULL,51789,3);
INSERT INTO stanza VALUES('J597','4','主はすみのいしで, 使徒,預言者は土台,<br/>ユダヤ人と異邦人, 建造されていち;<br/>かみのいえとなり, ともに建造され,<br/>霊にてちょう和され, 主を安そくさす。<br/>',NULL,51790,4);
INSERT INTO stanza VALUES('J597','5','召会かみのおく義, かみのごけいかく,<br/>キリスト住まわせ, 知恵をあらわす。<br/>主を理かいさせて, 主を鑑しょうさせ,<br/>無限のあい満たし, 主の豊満とする。<br/>',NULL,51791,5);
INSERT INTO stanza VALUES('J597','6','からだ,れい,のぞみ, 主,信仰,バプテスマ,<br/>御ちち,みなひとつ, しょう会もひとつ。<br/>キリストの豊満の 身のたけの度量,<br/>われらはせい長し, ともに到たつす。<br/>',NULL,51792,6);
INSERT INTO stanza VALUES('J597','7','かく種のたまもの, 召会はあたえられ,<br/>せい徒らを成就し, からだ建造する。<br/>ふるいひとを脱ぎ, あたらしいひと着,<br/>おもいの霊のなかで こうしんされる。<br/>',NULL,51793,7);
INSERT INTO stanza VALUES('J597','8','しみもしわもない 召かいをむかえんと,<br/>主は召かいを愛し, ご自身あたえた。<br/>おのがからだのよう やしないはぐくむ,<br/>キリストと召かい, 大いなるおく義。<br/>',NULL,51794,8);
INSERT INTO stanza VALUES('J597','9','召会はからだ,つま, 住まいだけでなく,<br/>あく魔をほろぼす たたかうせん士。<br/>主の大のうにより ちからづけられ,<br/>かみの武具を着け, 霊にありいのる。<br/>',NULL,51795,9);
INSERT INTO stanza VALUES('J598','1','召会,主のからだ, かみの住まい,<br/>召された聖徒の 結集,神人,調和;<br/>かみにえらばれ, あがなわれた;<br/>その性しつ,地位, 天にぞくする。<br/>',NULL,51796,1);
INSERT INTO stanza VALUES('J598','2','召会,復かつ通し 新人に生まれ,<br/>れいとことばで あらわれ,せい。<br/>主,召会のいのち, 召会のかしら,<br/>性しつはおなじ, 万有超えつす。<br/>',NULL,51797,2);
INSERT INTO stanza VALUES('J598','3','主イェス・キリスト, 召会の土だい;<br/>召会のすべては 主と同様,神聖。<br/>十字架の死,通り, 復かつにあり,<br/>金,銀,宝せきとし 建ぞうされる。<br/>',NULL,51798,3);
INSERT INTO stanza VALUES('J598','4','かみ,主,霊ひとつ, 要素はひとつ,<br/>信仰,希望,バﾌﾟテｽマ, からだひとつ。<br/>三いちのかみは 召会のちゅう心,<br/>信仰でむすばれ, 再臨をのぞむ。<br/>',NULL,51799,4);
INSERT INTO stanza VALUES('J598','5','諸こく民より出, 肢体とされる,<br/>身分の高低なく, ひとつとなる;<br/>ユダヤ人,異邦人, 自由,奴隷なく,<br/>あるはひとりの あたらしいひと。<br/>',NULL,51800,5);
INSERT INTO stanza VALUES('J598','6','宇宙のからだは かく地にあり,<br/>地方のたち場で あらわれ出る。<br/>行政は地方てき, 主はその元首,<br/>まじわりは宇宙, へだてはなし。<br/>',NULL,51801,6);
INSERT INTO stanza VALUES('J598','7','諸召会の完成は 新エルサレム;<br/>キリストの豊満, みやこの光景;<br/>主は燃える燈火, 召会はしょく台,<br/>栄光のみかたち 完成,到たつす。<br/>',NULL,51802,7);
INSERT INTO stanza VALUES('J599','1','キリストは召会のたね, ひとのこころにまかれ,<br/>成ちょうして,実をむすび, パンとなり,かみひと,満たす。<br/>',NULL,51803,1);
INSERT INTO stanza VALUES('J599','2','あく魔来て,にせ信者を 聖徒のなかにまき込む,<br/>どくむぎのよう混乱させ, むぎの成ちょうさまたげる。<br/>',NULL,51804,2);
INSERT INTO stanza VALUES('J599','3','からしだねなる主より, 召会のいのち生まれる；<br/>ちいさくて目立たぬが, 飢えるものらを飽かせる。<br/>',NULL,51805,3);
INSERT INTO stanza VALUES('J599','4','あく魔来て,小さき菜の 性しつとかたち変える,<br/>たいぼくに成ちょうさせ， 悪しきものの住みかとす。<br/>',NULL,51806,4);
INSERT INTO stanza VALUES('J599','5','サタンは変しつの「召会」に 異邦のしゅう慣,持ち込む,<br/>パンだねとし,こなに混ぜ, かみのもくてき破かいす。<br/>',NULL,51807,5);
INSERT INTO stanza VALUES('J599','6','しかし主は聖徒たちを 真珠と宝せきに変える,<br/>王こくの実際を持たせ, 召会をとうといものとする。<br/>',NULL,51808,6);
INSERT INTO stanza VALUES('J599','7','成ちょうして,主と調和し, 主のかたちに変えられ,<br/>主の建造にてきごうし, かみの王こくをもたらす。<br/>',NULL,51809,7);
INSERT INTO stanza VALUES('J599','8','「どくむぎ」,「たいぼく」から, 主よ,ぶん離させたまえ;<br/>「パンだね」ないパンとして, かみひとのひつ要,満たせ。<br/>',NULL,51810,8);
INSERT INTO stanza VALUES('J599','9','いのちのなかで成長し, 主のからだに建造され,<br/>召会となり,主を表現し, 主に王こくの実際得さす。<br/>',NULL,51811,9);
INSERT INTO stanza VALUES('J600','1','ない住するれいは, いちをもたらした,<br/>その実さいを生き, 召会はいちとなる;<br/>聖霊から出たゆえ, 霊のいちと呼ばれ,<br/>すべてのせい徒の 信こうにもとづく。<br/>',NULL,51812,1);
INSERT INTO stanza VALUES('J600','2','すべての聖徒らの 共通のしんこうは,<br/>主と主のあがない, それを要素とする。<br/>聖徒らは真にいち, 信仰はまったくいち,<br/>たっとい信仰により, 召会は存ざいする。<br/>',NULL,51813,2);
INSERT INTO stanza VALUES('J600','3','宇宙の召会はいち, 主の所ゆうとなる;<br/>地方の召会もいち, ただ主をひょう現す。<br/>かみ,主,れい,信こう, バプテスマ,からだ,<br/>のぞみ,いちであり, 召会の要素はいち。<br/>',NULL,51814,3);
INSERT INTO stanza VALUES('J600','4','この「いち」のたち場, 召会,聖徒のたち場,<br/>このいちの実さい, そのれいはのぞむ;<br/>たち場まもりつつ, その「いち」を実行し,<br/>召会はかく地にて 建造され,しゅつ現す。<br/>',NULL,51815,4);
INSERT INTO stanza VALUES('J600','5','主よ,聖霊のいちを つねにまもらせよ;<br/>このたち場に立ち, からだにあずかる。<br/>なれのみこころが じつげんするように,<br/>永遠のご計かくが 成就されるように。<br/>',NULL,51816,5);
INSERT INTO stanza VALUES('J601','1','かみの御子とあがないは, すくい得さすわが信こう;<br/>教理はわれをすくい得ず, すくうは主のパｰスン,みわざ。<br/>',NULL,51817,1);
INSERT INTO stanza VALUES('J601','2','教理,おしえのかぜとなり, 聖徒のいちを駄目にする:<br/>聖徒を主から吹き去らせ, からだの建造,破かいする。<br/>',NULL,51818,2);
INSERT INTO stanza VALUES('J601','3','すべての教理のぞき去り, そのしん仰のいち,たもつ。<br/>れいなる主のなかでいち; ただこのいち実こうする。<br/>',NULL,51819,3);
INSERT INTO stanza VALUES('J601','4','主ご自身なる真理たもち, かしらである主のなかへ,<br/>すべてにありせいちょうし, からだ建造し,豊満となる。<br/>',NULL,51820,4);
INSERT INTO stanza VALUES('J601','5','「おしえのかぜ」みな捨てて, 「信こうのいち」到たつする;<br/>このいち通し,主のなかで, 主のからだを成長させる。<br/>',NULL,51821,5);
INSERT INTO stanza VALUES('J602','1','ユダヤ人の捨てた すみのいしなる主,<br/>死と復かつにより, かたく据えらる。<br/>ユダヤ人,異邦人は, ひとつに建造され,<br/>あたらしいひと,主の み住まいとなる。<br/>',NULL,51822,1);
INSERT INTO stanza VALUES('J602','2','霊のいわなる主は, かわきをいやして,<br/>たよらせるのみか, 住まい建造する。<br/>シオンのいしずえは, こころみ経て立つ;<br/>ただこのいわのみ, 召かいのもとい。<br/>',NULL,51823,2);
INSERT INTO stanza VALUES('J602','3','建造された召会は 困難に出会っても,<br/>なおかたく立って, よみに打ち勝つ。<br/>主の権威もちいて, 主のようしばり,解き,<br/>王こくをもたらし, あく霊追い出す。<br/>',NULL,51824,3);
INSERT INTO stanza VALUES('J602','4','生けるいしなる主, われらをいしとし,<br/>なれのせいしつと ひとしくさせる;<br/>霊のいえとされて, 祭司の体系となり,<br/>れいのいけにえを かみにささげる。<br/>',NULL,51825,4);
INSERT INTO stanza VALUES('J602','5','ダビデのすえの主, かみのみや建造す;<br/>王とさい司しょくで, つとめを果たす。<br/>王なる主は支配し, ひと,ふくじゅうさせ,<br/>祭司として,かみに ひとをもたらす。<br/>',NULL,51826,5);
INSERT INTO stanza VALUES('J602','6','御座より権威出て, たみをとう治する;<br/>かわはまじわりで, たみを供給する。<br/>権威とまじわりを ともに並こうさせ,<br/>王と祭司である主, 建ぞう成就する。<br/>',NULL,51827,6);
INSERT INTO stanza VALUES('J602','7','受にくしたまく屋, かみの栄光のみや,<br/>ひとのうちに住み, かみをあらわす。<br/>なれはまたしょう会, かみとひとの合併,<br/>かみの豊富で満つ 聖徒のけんぞう。<br/>',NULL,51828,7);
INSERT INTO stanza VALUES('J602','8','とわの住まいなる主, 代々われの住まい,<br/>なれのうちに生き, とわにまもらる。<br/>なれ,われらの聖所, かみとわれら住む;<br/>ともに生かつして, 絶えず礼拝する。<br/>',NULL,51829,8);
INSERT INTO stanza VALUES('J602','9','なれはすみのいし, もとい,生けるいし,<br/>みや,召かい,建造者, み住まい,せい所！<br/>なれによりわれら, 生けるいしとなり,<br/>建造されることを ねがいもとめる！<br/>',NULL,51830,9);
INSERT INTO stanza VALUES('J603','1','主よ,ご計かくを賛美す, われらをなが住まいとし,<br/>主うちに生かし,満たし, 子にある主,表現さす。<br/>',NULL,51831,1);
INSERT INTO stanza VALUES('J603','2','ながかたちにつくられ, なれのだいひょうとなる,<br/>つちのうつわであるが, うちにはれいがある。<br/>',NULL,51832,2);
INSERT INTO stanza VALUES('J603','3','いのちとし,主を受けて, なが性しつにあずかる;<br/>なれとわれは調和され, ひとつからだとなる。<br/>',NULL,51833,3);
INSERT INTO stanza VALUES('J603','4','ながいのち,ながれ込み, こころすべてに浸透し,<br/>真珠,宝せきに変えられ, ながみかたちとなる。<br/>',NULL,51834,4);
INSERT INTO stanza VALUES('J603','5','われは知る,そはひとの 鑑しょうのためではなく,<br/>建造され,組み合わされ, 主のいえとなるため。<br/>',NULL,51835,5);
INSERT INTO stanza VALUES('J603','6','いま,われを主にささぐ, 建造の御手で受け入れ,<br/>征ふくし,くだき,つなぎ, 住まいに建造しませ。<br/>',NULL,51836,6);
INSERT INTO stanza VALUES('J603','7','天然のいのち,性かくを すべて攻め,くだきませ;<br/>もはや単どくにならず, 聖徒らともに調和す。<br/>',NULL,51837,7);
INSERT INTO stanza VALUES('J603','8','主に愛されるはなよめ, 主のすべてを享受する,<br/>愛満たされ,ともに住む, なが満ぞく,ああ,いかに。<br/>',NULL,51838,8);
INSERT INTO stanza VALUES('J604','1','主は陶器師，また けんぞうする主;<br/>つくり上げ,また けんぞうされる。<br/>われ,新そうぞう 生けるいしなり;<br/>ながうつわ,また みやとなるため。<br/>',NULL,51839,1);
INSERT INTO stanza VALUES('J604','2','つちのうつわを なれ,つくり変え,<br/>いのちぶん与し, ほうせきとなす。<br/>さらに建造され, はなよめとなり,<br/>主に占ゆうされ, 主といちとなる。<br/>',NULL,51840,2);
INSERT INTO stanza VALUES('J604','3','なれのねがいは, ざいりょうもちい,<br/>ながいえ建造し, なれが住むこと;<br/>すべてをふくむ 主の表げんには,<br/>けんぞうされた しょう会がひつ要。<br/>',NULL,51841,3);
INSERT INTO stanza VALUES('J604','4','たんどくでなく, だん体のいのち,<br/>なれのねがいを かん全に成就す。<br/>ながみからだに 建造されてこそ,<br/>ながほうまんを ひょうげんし得る。<br/>',NULL,51842,4);
INSERT INTO stanza VALUES('J604','5','主よ,われをいま, 孤りつさせずに,<br/>聖徒らとともに けんぞうしませ。<br/>けんぞうのため, すべてをささげ,<br/>なれにえいこう 帰すことねがう。<br/>',NULL,51843,5);
INSERT INTO stanza VALUES('J605','1','息吹けや,主よ！ 霊を生かせや！<br/>うれい,死より解き, 復こうしませ。<br/>',NULL,51844,1);
INSERT INTO stanza VALUES('J605','2','息吹けや,主よ！ つばさあたえ,<br/>あらたなちからで, われ,つよめよ。<br/>',NULL,51845,2);
INSERT INTO stanza VALUES('J605','3','息吹けや,主よ！ 主にたよらせ,<br/>あんそくにはいり, 歓喜,満たせや。<br/>',NULL,51846,3);
INSERT INTO stanza VALUES('J605','4','息吹けや,主よ！ なれで満たせ;<br/>もはや行動,意志は われにあらず。<br/>',NULL,51847,4);
INSERT INTO stanza VALUES('J605','5','息吹けや,主よ！ からだに生き,<br/>せい徒らとともに 建ぞうしませ。<br/>',NULL,51848,5);
INSERT INTO stanza VALUES('J606','1','自己,てん然を捨て, けんぞうされて,<br/>ともにみやとなり, えいこう満たす。<br/>たかぶり,たんどく, とく異せいを捨て,<br/>主の権威にふくし, 主の住まいとなる。<br/>',NULL,51849,1);
INSERT INTO stanza VALUES('J606','2','せい長し,変えられ, 供給し,建造され,<br/>機のうを果たして, ひとをじょう就す。<br/>自分にぞくすもの, たかくひょう価せず,<br/>すべてかたよらず, きん衡をたもつ。<br/>',NULL,51850,2);
INSERT INTO stanza VALUES('J606','3','かしらにつながり, 主の豊富,享受す;<br/>かみ増しくわわり, 円じゅくにいたる。<br/>主のあいを知って, かん全にせい長し,<br/>キリストの豊満の 身のたけとなる。<br/>',NULL,51851,3);
INSERT INTO stanza VALUES('J606','4','み住まい,からだに, けんぞうされて,<br/>主のうつわとなり, えい光あらわす。<br/>はなよめ,みやこは, いまや地上にあり,<br/>なが栄こう照らし, ひとにかがやく。<br/>',NULL,51852,4);
INSERT INTO stanza VALUES('J607','1','かたれや！息吹けや！ 主よ,枯れたほねに！<br/>ぜん地に散らさる, ほねにかたれや！<br/>',NULL,51853,1);
INSERT INTO stanza VALUES('J607','2','かたれや！息吹けや！ 枯れたほね,生かせ！<br/>はかより起こして, かたり,息吹けや！<br/>',NULL,51854,2);
INSERT INTO stanza VALUES('J607','3','かたれや！息吹けや！ あつめて,生かして,<br/>ぐんたいとなして, てき攻めさせよ！<br/>',NULL,51855,3);
INSERT INTO stanza VALUES('J607','4','かたれや！息吹けや！ たみをいちとなし,<br/>かしらのけん威に, ふくじゅうさせよ！<br/>',NULL,51856,4);
INSERT INTO stanza VALUES('J607','5','かたれや！息吹けや！ からだに建ぞうし,<br/>なが住まいとなって, 主に安そくさす。<br/>',NULL,51857,5);
INSERT INTO stanza VALUES('J607','6','かたれや！息吹けや！ われ,生きかえらせ,<br/>孤りつも死もない からだに生かせ！<br/>',NULL,51858,6);
INSERT INTO stanza VALUES('J607','7','かたれや！息吹けや！ ともにてきを攻め,<br/>いそいで,ながいえ, けんぞうさせよ。<br/>',NULL,51859,7);
INSERT INTO stanza VALUES('J608','1','主よ,いのちのいき入れませ！ 枯れたるほねの身に,<br/>よみがえらせ,いのちあたえ, からだのなかに生かせや。<br/>',NULL,51860,1);
INSERT INTO stanza VALUES('J608','2','主よ,いのちのいき入れませ！ おもく閉ざした霊に,<br/>さまたげのぞき,かいほうし, からだのなか,調和させよ。<br/>',NULL,51861,2);
INSERT INTO stanza VALUES('J608','3','主よ,いのちのいき入れませ！ もだえ,しずむれいに,<br/>ちからをあたえ,なぐさめて, からだの供きゅう,得させよ。<br/>',NULL,51862,3);
INSERT INTO stanza VALUES('J608','4','主よ,いのちのいき入れませ！ むなしく,欠けた霊を,<br/>満ち満たして,めぐみあたえ, からだの豊富,享受させよ。<br/>',NULL,51863,4);
INSERT INTO stanza VALUES('J608','5','主よ,いのちのいき入れませ！ 死と単どくより解き,<br/>死と孤どくを打ちやぶって, まったくからだに生かせや。<br/>',NULL,51864,5);
INSERT INTO stanza VALUES('J609','1','ながあお写真,まく屋は, なれがいかに建造するか,<br/>いかに栄光あらわすか, われらにかたり出す。<br/>',NULL,51865,1);
INSERT INTO stanza VALUES('J609','2','はこはまく屋のちゅう心, まく屋ははこをない蔵す;<br/>十戒,はこのなかにあり, はこはまく屋に住む。<br/>',NULL,51866,2);
INSERT INTO stanza VALUES('J609','3','はこは神人のキリスト, かみとひとの調和,予表す;<br/>十かいはかみのひょう現, キﾘストのなかに住む。<br/>',NULL,51867,3);
INSERT INTO stanza VALUES('J609','4','キリスト,召かいの中心, 召会はキリストをやどす;<br/>かみはキリストに住み, キﾘストは召会に住む。<br/>',NULL,51868,4);
INSERT INTO stanza VALUES('J609','5','まく屋ははこのかく大, ともに金と木でつくらる;<br/>召かいはかれのかく充, かみとひととの調和。<br/>',NULL,51869,5);
INSERT INTO stanza VALUES('J609','6','たてわく,銀の座に立ち, まく屋を建て上げている;<br/>金でおおわれ,金の環に よこ木通り,つらなる。<br/>',NULL,51870,6);
INSERT INTO stanza VALUES('J609','7','聖徒はあがないに立ち, 召かいを建て上げている;<br/>神性にあり霊はつなぎ, 組み合わされて建つ。<br/>',NULL,51871,7);
INSERT INTO stanza VALUES('J609','8','まく屋の四層のおおい, キリストのかく面,予表す;<br/>キリスト,かみのえい光, かみの住まいおおう。<br/>',NULL,51872,8);
INSERT INTO stanza VALUES('J609','9','栄こうの主におおわれ, せい徒ら組み合わされる;<br/>かれのすべてきょう受し, 主にあり建造される。<br/>',NULL,51873,9);
INSERT INTO stanza VALUES('J609','10','十戒,はこのなかにあり, はこ,まく屋のなかにある;<br/>かみはキリストにあり, キﾘストは召会にある！<br/>',NULL,51874,10);
INSERT INTO stanza VALUES('J610','1','霊の解放！われはねがう: 霊のなかひとと調和す,<br/>単どくでなく,自己脱ぎ, 建造にふさわしくなる。<br/>',NULL,51875,1);
INSERT INTO stanza VALUES('J610','2','霊の解放！われ,もとめる： われ閉じず,閉じ込めず；<br/>ながくいた自己はなれ, いま自己脱ぎ,自由得る。<br/>',NULL,51876,2);
INSERT INTO stanza VALUES('J610','3','霊の解放！われは愛する: 自己より抜け出るなら,<br/>聖霊,自由に行きわたり, 主の臨在はあらわれる。<br/>',NULL,51877,3);
INSERT INTO stanza VALUES('J610','4','霊の解放！われはしたう: 自己つい求はまずしい;<br/>どくりつからはなれて, いま豊富をきょう受する。<br/>',NULL,51878,4);
INSERT INTO stanza VALUES('J610','5','霊の解放！われはねがう: もはやあざむかれずに;<br/>自己の領いきより出て, 無限の領いきにはいる！<br/>',NULL,51879,5);
INSERT INTO stanza VALUES('J610','6','霊の解放！われはのぞむ: 自己脱ぎ,なわめ解かれ,<br/>調和し,つよく,あかるく, 主のすべてきょう受する。<br/>',NULL,51880,6);
INSERT INTO stanza VALUES('J611','1','霊のまじわりしたう！ ともに調和されて,<br/>単どくなたい度捨て, ともに建造される。<br/>',NULL,51881,1);
INSERT INTO stanza VALUES('J611','2','霊のまじわりしたう！ ひとに向きひらき,<br/>閉じこもるくせ捨て, ともにれいはいす。<br/>',NULL,51882,2);
INSERT INTO stanza VALUES('J611','3','霊のまじわりしたう！ まったく霊,解放され,<br/>たかぶりを脱ぎ捨て, 霊を自由にながす。<br/>',NULL,51883,3);
INSERT INTO stanza VALUES('J611','4','霊のまじわりしたう！, ひとつ霊でいのり,<br/>虚えい虚しょくを捨て, 真のまじわりしたう。<br/>',NULL,51884,4);
INSERT INTO stanza VALUES('J611','5','霊のまじわりしたう！ 権威と均衡が取れ,<br/>はたらきに均衡あり, ともにほう仕する。<br/>',NULL,51885,5);
INSERT INTO stanza VALUES('J611','6','主よ,聖徒をはげまし, まじわりしたわせ,<br/>はやくけんぞうして, 計かく成就しませ！<br/>',NULL,51886,6);
INSERT INTO stanza VALUES('J612','1','なんたるしゅくふく, われらはさい司！<br/>かみに立てられて, とうといつとめ負う。<br/>',NULL,51887,1);
INSERT INTO stanza VALUES('J612','chorus','からだのけん造は さい司のつとめ;<br/>霊のなかでいのり, つとめを果たす。<br/>',NULL,51888,2);
INSERT INTO stanza VALUES('J612','2','けん威にふくして, 身ぶんをまもり,<br/>つとめを果たせば, しょう会,建ぞうす。<br/>',NULL,51889,3);
INSERT INTO stanza VALUES('J612','3','しょう会はさい司団, さい司のたい系;<br/>みな組み合わされ, けんぞうされる。<br/>',NULL,51890,4);
INSERT INTO stanza VALUES('J612','4','しょう会の堕らくで さい司,荒はいし,<br/>聖徒の霊はよわく, ことばのみある。<br/>',NULL,51891,5);
INSERT INTO stanza VALUES('J612','5','預言者にかたより, ことばかたるが,<br/>さい司はいのらず, れい,かつ用せず。<br/>',NULL,51892,6);
INSERT INTO stanza VALUES('J612','6','いのり,かいふくし, きん衡をたもつ;<br/>いのりとことばで ひとをみちびく。<br/>',NULL,51893,7);
INSERT INTO stanza VALUES('J612','7','いのりによる奉仕, 霊にて調和され,<br/>いのり,おもんじて, しょう会,建ぞうす。<br/>',NULL,51894,8);
INSERT INTO stanza VALUES('J613','1','せいなる祭司は, 建造の生けるいし;<br/>建造には祭司の いのりがひつよう。<br/>',NULL,51895,1);
INSERT INTO stanza VALUES('J613','chorus','至聖所にはいり, 霊で御座に触れ,<br/>かみ通過させて, 建造のわざ成就す。<br/>',NULL,51896,2);
INSERT INTO stanza VALUES('J613','2','せい徒はさい司, 生けるいしなれば,<br/>祭司は奉仕して, いしとし,機能する。<br/>',NULL,51897,3);
INSERT INTO stanza VALUES('J613','3','旧やくの祭司は まく屋につかえる;<br/>祭司はまく屋に 調和されてひとつ。<br/>',NULL,51898,4);
INSERT INTO stanza VALUES('J613','4','新やくの祭司は 霊のまく屋といち;<br/>建造の実さいは さい司のたいけい。<br/>',NULL,51899,5);
INSERT INTO stanza VALUES('J613','5','建造の本しつは 祭司の奉仕にある;<br/>絶えず奉仕して, 召かい建造される。<br/>',NULL,51900,6);
INSERT INTO stanza VALUES('J613','6','さい司の奉仕で, ひと,かみにつなぎ,<br/>このまじわりで, 聖徒ら建ぞうする。<br/>',NULL,51901,7);
INSERT INTO stanza VALUES('J613','7','調和され,いのり, ともに建造されて,<br/>たいけいとなり, いけにえ,ささげる。<br/>',NULL,51902,8);
INSERT INTO stanza VALUES('J613','8','何ととうとい奉仕！ めぐみあたえませ;<br/>霊で多くいのり, 召かい,建ぞうする。<br/>',NULL,51903,9);
INSERT INTO stanza VALUES('J614','1','めぐみの主よ, 霊の交流！<br/>せつにわれは もとめる！<br/>てつのかべを 押したおして,<br/>主とまじわり, 霊ながす！<br/>',NULL,51904,1);
INSERT INTO stanza VALUES('J614','2','めぐみの主よ, 霊の交流！<br/>いま霊の交流, 懇願する！<br/>他人,見下げず, 自己閉ざさず,<br/>主とまじわり, 霊ながす！<br/>',NULL,51905,2);
INSERT INTO stanza VALUES('J614','3','めぐみの主よ, 霊の交流！<br/>われはいのり もとめる！<br/>もはやからに 閉じこもらず,<br/>ながれ止めず, 霊ながす！<br/>',NULL,51906,3);
INSERT INTO stanza VALUES('J614','4','めぐみの主よ, 霊の交流！<br/>たずねもとむ, 霊の交流！<br/>もはや自己を かい良せずに,<br/>日ごと,日ごと, 霊ながす！<br/>',NULL,51907,4);
INSERT INTO stanza VALUES('J614','5','めぐみの主よ, 霊の交流！<br/>めぐみの主よ, 要求する！<br/>自己をたおし, へりくだらせ,<br/>いのちながし, 霊ながす！<br/>',NULL,51908,5);
INSERT INTO stanza VALUES('J614','6','わが霊を主よ, ながせや！<br/>めぐみの主よ, われ,ねがう！<br/>建ぞうされて, 主とまじわり,<br/>ひとと調和し, 霊ながす！<br/>',NULL,51909,6);
INSERT INTO stanza VALUES('J615','1','何とあいすべきや！ こころしたういえ！<br/>なが臨在せつにもとめ, わがこころさけばん。<br/>',NULL,51910,1);
INSERT INTO stanza VALUES('J615','2','祭だんのかたわら, すずめ住みかを得,<br/>つばめはひなをかえす 巣をば見いだせり。<br/>',NULL,51911,2);
INSERT INTO stanza VALUES('J615','3','すずめ,つばめのよう よわく,ちいさくも,<br/>主のいえに住み,さい壇, 香壇のさち享受す。<br/>',NULL,51912,3);
INSERT INTO stanza VALUES('J615','4','ちから,なれにあり, 前途もかえりみず,<br/>こころシオンのおお路に あるひと,さちなり。<br/>',NULL,51913,4);
INSERT INTO stanza VALUES('J615','5','なみだのたに間も, いずみある地とし,<br/>あきのあめ,いけとなり, しゅくふくは満ちる。<br/>',NULL,51914,5);
INSERT INTO stanza VALUES('J615','6','ちからにちから得, シオンでかみに会い,<br/>もとめし主ご自しんと めぐみをたまわる。<br/>',NULL,51915,6);
INSERT INTO stanza VALUES('J615','7','主のいえのひと日, よその千にちにも<br/>まさるゆえ,ねがわくは, かどもりとさせよ。<br/>',NULL,51916,7);
INSERT INTO stanza VALUES('J615','8','わが日,たてなる主, めぐみ,えい光あとう;<br/>ともにませばひつよう, ことごとく足れり。<br/>',NULL,51917,8);
INSERT INTO stanza VALUES('J615','9','なおくあゆむひと, 良きものを受ける;<br/>主にたよるひと,さいわい, めぐみ,栄光受ける。<br/>',NULL,51918,9);
INSERT INTO stanza VALUES('J616','1','主よ,なが住まいである 召かいを愛する！<br/>そは主のよろこび,また われのあんそく。<br/>',NULL,51919,1);
INSERT INTO stanza VALUES('J616','2','主はしょうかいのために, ご自身を捨てる;<br/>われもこの身ささげて, みこころ成就す。<br/>',NULL,51920,2);
INSERT INTO stanza VALUES('J616','3','主はわがいのち,召会は, われのせいかつ;<br/>自己捨てる,ながねがい 成就するように。<br/>',NULL,51921,3);
INSERT INTO stanza VALUES('J616','4','召会はながはいぐう者, またながからだ;<br/>わがこころもとむもの, 依りたのむもの。<br/>',NULL,51922,4);
INSERT INTO stanza VALUES('J616','5','召会にて主はわが享受, あかしであって,<br/>われ,主の満ぞくとなる, 主に占有されて。<br/>',NULL,51923,5);
INSERT INTO stanza VALUES('J616','6','主よ,なが住まいである 召かいを愛する！<br/>われ,永遠に召会に生く, 他にいえはない。<br/>',NULL,51924,6);
INSERT INTO stanza VALUES('J617','1','主から出た生きものは, おなじいのちを持つ;<br/>かく自,十字架経て, 団体のキリスト生きる。<br/>',NULL,51925,1);
INSERT INTO stanza VALUES('J617','chorus','主にありつながり, 相互に取り組み,<br/>ともに行どうして, 御座をもたらす。<br/>',NULL,51926,2);
INSERT INTO stanza VALUES('J617','2','その行動めぐみにより, 自己に信らいしない;<br/>かみをおおいとし, 主なるかみを表現する。<br/>',NULL,51927,3);
INSERT INTO stanza VALUES('J617','3','かれらは純すい,真っすぐ, 柔和な霊,へりくだり;<br/>自己のこのみなく, どこでも霊にしたがう。<br/>',NULL,51928,4);
INSERT INTO stanza VALUES('J617','4','たがいにむすび合って, 成就し合い,機能する;<br/>ひとつこう動にて, ごけいかく成し遂げる。<br/>',NULL,51929,5);
INSERT INTO stanza VALUES('J617','5','組み合わされ,燃やされ, けがれを焼き尽くす;<br/>聖べつの照らしで, わが行どうはかがやく。<br/>',NULL,51930,6);
INSERT INTO stanza VALUES('J617','6','それで車輪うごきだし, かがやく大ぞら持つ;<br/>御座は支はいして, 主のえい光あらわれる。<br/>',NULL,51931,7);
INSERT INTO stanza VALUES('J618','1','主にある聖徒, みな肢たい,<br/>組み合わされ, いちとなる。<br/>',NULL,51932,1);
INSERT INTO stanza VALUES('J618','2','たまもの多くも, れいひとつ,<br/>つとめは多くも, 主はひとつ。<br/>',NULL,51933,2);
INSERT INTO stanza VALUES('J618','3','かく肢たいは みなひつ要,<br/>かく自は地位, 機のう持つ。<br/>',NULL,51934,3);
INSERT INTO stanza VALUES('J618','4','たまものには 差はあれど,<br/>価値はおなじ, たかぶらず。<br/>',NULL,51935,4);
INSERT INTO stanza VALUES('J618','5','かく自,機能し, つとめする;<br/>うむことなく, ちゅうじつに。<br/>',NULL,51936,5);
INSERT INTO stanza VALUES('J618','6','かく自,供給し, つつみ合い,<br/>すべてにおいて 主おもんじる。<br/>',NULL,51937,6);
INSERT INTO stanza VALUES('J618','7','召かいからだ, 主はかしら,<br/>あぶら塗りで, われらいち。<br/>',NULL,51938,7);
INSERT INTO stanza VALUES('J619','1','かみの生きもの, キリスト表現す;<br/>組み合わされて, 御むねを成就す;<br/>霊にしたがえば, 主も行どうする。<br/>',NULL,51939,1);
INSERT INTO stanza VALUES('J619','chorus','生きものうごき, 主の車輪,うごく,<br/>威厳もてうごき, 主をひょうげんし,<br/>かみの計かく完成す。<br/>',NULL,51940,2);
INSERT INTO stanza VALUES('J619','2','聖べつの烈火は, けがれを燃やす;<br/>聖べつのひかり, すべてを照らす;<br/>ひかりのなかで, かみにしたがう。<br/>',NULL,51941,3);
INSERT INTO stanza VALUES('J619','3','聖霊とあゆめば, 天はすい晶のよう;<br/>あかるい良心は, あかしし,かたる;<br/>かたり,また聞き, はたらき遂行す。<br/>',NULL,51942,4);
INSERT INTO stanza VALUES('J619','4','こうしてみ住まい, 御座を得られる;<br/>主は権威,遂行し, えい光あらわす;<br/>ひとのさま持ち, 周囲にかがやく。<br/>',NULL,51943,5);
INSERT INTO stanza VALUES('J620','1','かぜ,くも,火,神聖な金を あらわし,これにて,<br/>かみ,ひとのいのち得て, 生きものは生きる。<br/>',NULL,51944,1);
INSERT INTO stanza VALUES('J620','2','ひとと獅子,うし,わしは, かく面もて生きる;<br/>キリストのさまを生き, その栄光を表現す。<br/>',NULL,51945,2);
INSERT INTO stanza VALUES('J620','3','そのあゆみ真っすぐで, しん鮮,活ぱつ,光輝;<br/>訓練経過し,きよめられ, ひと照らし,さばく。<br/>',NULL,51946,3);
INSERT INTO stanza VALUES('J620','4','舞い上がり,しばられず, ひとのよう振る舞う;<br/>主をほこり,自己いなみ, ただかみを表現す。<br/>',NULL,51947,4);
INSERT INTO stanza VALUES('J620','5','めぐみにて,取り組んで, かく自は機能する;<br/>すみ火のよう燃え,照らし, 全行動はかがやく。<br/>',NULL,51948,5);
INSERT INTO stanza VALUES('J620','6','霊にしたがいあゆむなら, かみは行動される;<br/>行動のなか,主はうごき, 一致し,霊ともなう。<br/>',NULL,51949,6);
INSERT INTO stanza VALUES('J620','7','透めいな天,きよい良心, こえ出し,また聞く;<br/>主,表げんす軍隊として, てきをせいふくす。<br/>',NULL,51950,7);
INSERT INTO stanza VALUES('J620','8','澄みわたる天の御座に, ひとのような主,座す;<br/>琥はく金と火のよう見え, 御座の周囲はにじ。<br/>',NULL,51951,8);
INSERT INTO stanza VALUES('J621','1','キリストのあいで, われらむすばれる;<br/>このひとつ霊のまじわりは, 天にあるがごとし。<br/>',NULL,51952,1);
INSERT INTO stanza VALUES('J621','2','御座のまえに出て, ひとつ霊でいのる;<br/>もくてき,のぞみ,しんぱいを われらともに負う。<br/>',NULL,51953,2);
INSERT INTO stanza VALUES('J621','3','ひとつの肢たいの なやみともに負い,<br/>おもいやりのなみだながし, 苦らくをともにす。<br/>',NULL,51954,3);
INSERT INTO stanza VALUES('J621','4','わかれるときには, かなしみおぼえど,<br/>れいはなおともにあり,また 会うのぞみがある。<br/>',NULL,51955,4);
INSERT INTO stanza VALUES('J621','5','わかれることなき その日,待ちのぞむ;<br/>まったきあいに支はいされて, えい遠にたのしむ。<br/>',NULL,51956,5);
INSERT INTO stanza VALUES('J622','1','兄弟のいちはうるわしい: かしらのあぶら,すそに,<br/>ヘﾙモンのつゆがシオンに, 主はしゅくふくを命じる。<br/>',NULL,51957,1);
INSERT INTO stanza VALUES('J622','2','よろこびつつ,愛えんに; 主を食べ飲み,感謝満つ！<br/>このまじわり,すばらしい！ わかれなき日をのぞむ。<br/>',NULL,51958,2);
INSERT INTO stanza VALUES('J623','1','天のくう気を吸えば, 天のかおり来る;<br/>たましいーがにくをはなれ, 霊,愛に満つように。<br/>',NULL,51959,1);
INSERT INTO stanza VALUES('J623','2','きよい感情と意志で ともにむすばれ,<br/>いつのときも変わらず,主と 主のもの,あいす。<br/>',NULL,51960,2);
INSERT INTO stanza VALUES('J623','3','十字架にみちびかれ, 御むねにふくす;<br/>まじわりにて,したしさ増し, 主へとちかづく。<br/>',NULL,51961,3);
INSERT INTO stanza VALUES('J624','1','すべてのしゅうかい, 主と主のゆたかを,<br/>みかみのーかてとし, 展覧しよう,主を。<br/>',NULL,51962,1);
INSERT INTO stanza VALUES('J624','chorus','展覧しよう,主を, 展覧しよう,主を,<br/>主のとみを持ち来て, 展覧しよう,主を。<br/>',NULL,51963,2);
INSERT INTO stanza VALUES('J624','2','主により生き,また 主によりたたかわん;<br/>主によりーむすばれ, 展覧しよう,主を。<br/>',NULL,51964,3);
INSERT INTO stanza VALUES('J624','3','わがあゆみすべて, 主を実際となして,<br/>しゅうかいーたびごと, 展覧しよう,主を。<br/>',NULL,51965,4);
INSERT INTO stanza VALUES('J624','4','かみのためつどい, 手に主,持ち寄らば,<br/>かみと主ーたのしまん, 展覧しよう,主を。<br/>',NULL,51966,5);
INSERT INTO stanza VALUES('J624','5','復かつ,しょう天の主, 薫香としささげる;<br/>みかみ満ーぞくする, 展覧しよう,主を。<br/>',NULL,51967,6);
INSERT INTO stanza VALUES('J624','6','しゅうかいのちゅう心, ほう仕,ふん囲気も,<br/>主を展覧ーするため, 展覧しよう，主を。<br/>',NULL,51968,7);
INSERT INTO stanza VALUES('J624','7','あかしもいのりも, おしえ,まじわりも，<br/>たまものーすべてで, 展覧しよう,主を。<br/>',NULL,51969,8);
INSERT INTO stanza VALUES('J624','8','ちちにえい光帰し, 御子をたかく上げ,<br/>ひつ要満ーたすため, 展覧しよう,主を。<br/>',NULL,51970,9);
INSERT INTO stanza VALUES('J625','1','主よ,われらつどうとき, さらにふかいめぐみを得,<br/>ゆたかにいのちを得て, 主のあかしとならせよ;<br/>わがせつなるねがいを, 主よ,どうかじょう就しませ。<br/>',NULL,51971,1);
INSERT INTO stanza VALUES('J625','2','ひとの霊にかわきあり, こころに照らしがひつ要;<br/>あぶら塗りでうるおし, めぐみでこころ照らせ;<br/>ひと復興し,主あいさせ, 日々,主をもとめさせよ。<br/>',NULL,51972,2);
INSERT INTO stanza VALUES('J625','3','わがうちをつよくして, そくばくよりかいほうし,<br/>霊のなかでちから得て, 自己よりはなれさせよ;<br/>主のいのち,わがうちで, 御むね遂行するように。<br/>',NULL,51973,3);
INSERT INTO stanza VALUES('J625','4','主よ,さらにわれもとむ, ペンテコステの霊をあたえ,<br/>ひと悔いあらためさせ, めぐみをもとめさせよ;<br/>くらやみに光明あたえ, 囚人に解放を得させよ。<br/>',NULL,51974,4);
INSERT INTO stanza VALUES('J626','1','御子の言われたよう, 御まえに来て,<br/>霊と実際のなかで なれ,礼拝する。<br/>',NULL,51975,1);
INSERT INTO stanza VALUES('J626','2','ちちよ,なれはれい, あまくちかい！<br/>実際でなれ,とうとび, れいで触れる。<br/>',NULL,51976,2);
INSERT INTO stanza VALUES('J626','3','かみをはいすため, 霊,つくられる;<br/>外面でもがかずに, れいにもどる。<br/>',NULL,51977,3);
INSERT INTO stanza VALUES('J626','4','霊もて霊,再生され, いのちを得る,<br/>おもいこう新され, 真に奉仕する。<br/>',NULL,51978,4);
INSERT INTO stanza VALUES('J626','5','うちなる感かくで, なれを礼拝す;<br/>あぶらの運こうで, なれ,あらわす。<br/>',NULL,51979,5);
INSERT INTO stanza VALUES('J626','6','もはやかげでなく, 実際で礼拝す;<br/>キリストは実さい, 礼拝し,ほめる。<br/>',NULL,51980,6);
INSERT INTO stanza VALUES('J626','7','経験したキリスト, なれにささぐ;<br/>あまさ,うるわしさ, 鑑賞し,享受す。<br/>',NULL,51981,7);
INSERT INTO stanza VALUES('J626','8','霊と実際のなかで われらつどい,<br/>なれの御座かこみ, 礼拝し,賛美す。<br/>',NULL,51982,8);
INSERT INTO stanza VALUES('J627','1','日々の生かつ,集かいも, 主がちゅう心,またない容;<br/>儀しき,教理,是非でなく, 集かいはただ主のため。<br/>',NULL,51983,1);
INSERT INTO stanza VALUES('J627','2','主はひかり,みちゆえに, 照らせや,われしたがう;<br/>主は生けるみずとかて, 飲しょくし,やしなわれる。<br/>',NULL,51984,2);
INSERT INTO stanza VALUES('J627','3','主はいのち,われながす, 真理の主,われあかしす;<br/>めぐみの主,われたたえ, かしらの主,たかく上げん。<br/>',NULL,51985,3);
INSERT INTO stanza VALUES('J627','4','主はかみにもひとにも, すべて,ひつ要,かいけつ;<br/>召かいの実さい,ない容, いのち,ひと,増加される。<br/>',NULL,51986,4);
INSERT INTO stanza VALUES('J627','5','うたといのりをささげ, 霊によりて主あらわす;<br/>霊の奉仕とまじわりで, 主をかつ用し,ひょう現す。<br/>',NULL,51987,5);
INSERT INTO stanza VALUES('J627','6','御名でつどい,霊で行動し, 塗りあぶらもていのる;<br/>儀しきや思考によらず, 霊もちいて主あらわす。<br/>',NULL,51988,6);
INSERT INTO stanza VALUES('J627','7','ひたすらまえに向かい, 主てき用し,えんじゅくす;<br/>すべてを損しつとなし, とわに主をすべてとす。<br/>',NULL,51989,7);
INSERT INTO stanza VALUES('J628','1','霊かつ用せよ, おもい捨て,<br/>これぞ集会の 秘けつなり。<br/>',NULL,51990,1);
INSERT INTO stanza VALUES('J628','2','霊かつ用せよ, 儀しき捨て,<br/>主すべてとし, 主をながす。<br/>',NULL,51991,2);
INSERT INTO stanza VALUES('J628','3','霊かつ用せよ, 感じょう捨て,<br/>相互に奉仕す, 主その実際。<br/>',NULL,51992,3);
INSERT INTO stanza VALUES('J628','4','霊かつ用せよ, たましい捨て,<br/>たすけ合って, 主にたよる。<br/>',NULL,51993,4);
INSERT INTO stanza VALUES('J628','5','霊かつ用せよ, 自己はなれ,<br/>自己愛,自せき, 傲慢捨てる。<br/>',NULL,51994,5);
INSERT INTO stanza VALUES('J628','6','霊のなかにて 解放される;<br/>「われ義なり」の 意しきより。<br/>',NULL,51995,6);
INSERT INTO stanza VALUES('J628','7','霊かつ用して, 勝利,宣言す;<br/>きよめる血と 御名により。<br/>',NULL,51996,7);
INSERT INTO stanza VALUES('J628','8','霊かつ用して, 主に触れる;<br/>ことばに触れ, 主を享受す。<br/>',NULL,51997,8);
INSERT INTO stanza VALUES('J628','9','霊かつ用して, 主あかしす;<br/>霊をもちいて, 主を供給す。<br/>',NULL,51998,9);
INSERT INTO stanza VALUES('J628','10','霊かつ用すは, わがひつ要,<br/>主のみちびき 受けるため。<br/>',NULL,51999,10);
INSERT INTO stanza VALUES('J629','1','キリストの肢体, かれのひょう現;<br/>かく自は機能し, 豊富あらわす。<br/>傍観者とならず, 死,もたらさず,<br/>ぶんを果たして, まじわり持つ。<br/>',NULL,52000,1);
INSERT INTO stanza VALUES('J629','2','みなチｰムとなり, 単どくでなく,<br/>組み合わされて, したがい合う;<br/>自己によらずに, ながれにより,<br/>受けたせい霊を きょうきゅうする。<br/>',NULL,52001,2);
INSERT INTO stanza VALUES('J629','3','キリストが中心, ほかにあらず,<br/>ともにまじわり, めぐみ享受す。<br/>主はかしら,内容, われらは豊満;<br/>集会のかつどう, 主を表現する。<br/>',NULL,52002,3);
INSERT INTO stanza VALUES('J629','4','非難をしないで, 愛で建造され,<br/>じょう就し合うを, われらねがう。<br/>自己,天然はなれ, 霊をくん練し,<br/>からだの奉仕に ともに生きる。<br/>',NULL,52003,4);
INSERT INTO stanza VALUES('J630','1','主よ,なが生けることば,<br/>なが臨在を賛美します;<br/>とうとい主は引き寄せて,<br/>わがこころを捕らえた。<br/>',NULL,52004,1);
INSERT INTO stanza VALUES('J630','2','ながことば,霊といのち,<br/>われやしない,供給する;<br/>われを主に同けい化し,<br/>身のたけの度量得さす。<br/>',NULL,52005,2);
INSERT INTO stanza VALUES('J630','3','主をさらに供きゅうして,<br/>霊のなかで生かつさせ,<br/>日々生かし,まもりませ,<br/>またあつまるときまで。<br/>',NULL,52006,3);
INSERT INTO stanza VALUES('J631','1','集かいが終わるまえに,<br/>ながひょう現,栄光のため,<br/>新せんなめぐみのゆえ,<br/>主よ,感謝し,賛美します。<br/>',NULL,52007,1);
INSERT INTO stanza VALUES('J631','2','集かいを終えてもなお,<br/>主の臨在はつづきます;<br/>霊のなかのちからもて,<br/>愛のゆえ供きゅうしませ。<br/>',NULL,52008,2);
INSERT INTO stanza VALUES('J631','3','主の臨在がともにあり,<br/>わがなやみ,ともに負い,<br/>絶えず主を享受させて,<br/>また集かいさせたまえ。<br/>',NULL,52009,3);
INSERT INTO stanza VALUES('J632','1','立て,イェスのため, 主のつわもの；<br/>主のはたかかげ, たかく上げよ。<br/>主,たい軍ひきい, 勝利から勝利へ,<br/>てき絶やし,御名 聖とならせる。<br/>',NULL,52010,1);
INSERT INTO stanza VALUES('J632','2','立て,イェスのため, 主のラｯパ聞け;<br/>勝利の名により, 戦場をはしれ。<br/>てき,荒れくるうも, まえに向かいつ,<br/>てきほろぶまで, 雄々しく行け。<br/>',NULL,52011,2);
INSERT INTO stanza VALUES('J632','3','立て,イェスのため, 主に信頼して,<br/>自己とけっ気を 武器としない。<br/>霊の武具を着け, 絶えずいのりつ,<br/>れいにしたがい, すすみすすめ。<br/>',NULL,52012,3);
INSERT INTO stanza VALUES('J632','4','立て,イェスのため, 勝利はちかい;<br/>きょうはたたかい, 明日はがい歌。<br/>勝利を得たもの, かんむりを受けて,<br/>ともに王となり, とわに支配す。<br/>',NULL,52013,4);
INSERT INTO stanza VALUES('J633','1','すすめや,すすめ,主のへい士！ 十字架のはた,たかく上げ;<br/>主にしたがってすすむなら, てきは,かならず一そうされる。<br/>',NULL,52014,1);
INSERT INTO stanza VALUES('J633','chorus','すすめキリスートの へい士らーよ;<br/>主にしたがって, いざすすめ。<br/>',NULL,52015,2);
INSERT INTO stanza VALUES('J633','2','いざ,へい士らよ,立ち向かえ, 主の名聞けば,てき逃げる。<br/>いざ,きょうだいよ,たからかに, 賛美もてハデスをふるわせよ。<br/>',NULL,52016,3);
INSERT INTO stanza VALUES('J633','3','かみの召かいのたいぐんは, 父祖の聖徒ら,さきに行く;<br/>われらもあとにつらなって, からだ,霊,のぞみ,信こうひとつ。<br/>',NULL,52017,4);
INSERT INTO stanza VALUES('J633','4','世の王,諸こくはほろびゆき, キリストのみ存ぞくする。<br/>召会にハデスは打ち勝てず; 召会は主にしたがいしょう利する。<br/>',NULL,52018,5);
INSERT INTO stanza VALUES('J633','5','すすめ！召かいに呼おうして, 歩ちょう合わせ,したがえや;<br/>えい光,ほまれは主にあれと, 聖徒,天使はともにほめうたう。<br/>',NULL,52019,6);
INSERT INTO stanza VALUES('J634','1','とつげき！へい士ら！ 戦とうは最なか;<br/>主は勝利得られた, うたいすすめ。<br/>サタンは敗ぼくして, やみしりぞく！<br/>ばん軍の主はしょう軍, 凱せんは間ぢか。<br/>',NULL,52020,1);
INSERT INTO stanza VALUES('J634','2','「とつげき！へい士ら！ われ,あおぎ見よ;<br/>勝利のたたかいで, 御座にいたる」｡<br/>世の戦場ではなく, 霊のたたかい;<br/>てき,周囲に満ちるを, 主は知りたもう。<br/>',NULL,52021,2);
INSERT INTO stanza VALUES('J634','3','「とつげき！へい士ら！ 御座へといたる;<br/>復かつのちからは 霊超えつさす。<br/>われにより権能と しょう利を得て,<br/>がい歌をうたいつつ, たかく上げらる」｡<br/>',NULL,52022,3);
INSERT INTO stanza VALUES('J634','4','「とつげき！へい士ら！ 御座へといたれ;<br/>ながせきかく保す, 歓喜し,うたえ」｡<br/>主ととも復かつし, 昇天して,座す;<br/>せん場のこえ,つみを とおくはなれる。<br/>',NULL,52023,4);
INSERT INTO stanza VALUES('J634','5','とつげき！へい士ら！ 御座へといたれ;<br/>主はなれをえらび, 王こく継がす。<br/>なが将来あかるく, しつ望はなし,<br/>とわに主のあい得て, とわに住み合う。<br/>',NULL,52024,5);
INSERT INTO stanza VALUES('J634','6','とつげき！へい士ら！ 面前に御座あり！<br/>あたらしいうたを シオンでうたう。<br/>小ひつじは勝利し, 御座に着いた！<br/>かれの勝利のゆえに, よろこびうたう。<br/>',NULL,52025,6);
INSERT INTO stanza VALUES('J635','1','やみのなかでサタン, こころみて言う:<br/>「かんむりに固守せず, 自己あいせよ」と。<br/>',NULL,52026,1);
INSERT INTO stanza VALUES('J635','chorus','戦士よ,かたく立て！ 勝利の主をおもえ！<br/>イェスはすでに勝利, 雄々しくたたかえ。<br/>',NULL,52027,2);
INSERT INTO stanza VALUES('J635','2','ともはどう揺して, ふたごころ持つ;<br/>あざむいて,そしり, てきとつうじる;<br/>',NULL,52028,3);
INSERT INTO stanza VALUES('J635','3','この世はにんじょう, 虚えいもちいて,<br/>なれにあみを張り, しん仰をなくす;<br/>',NULL,52029,4);
INSERT INTO stanza VALUES('J635','4','ざつ務に追われて, 労苦し,くるしむ,<br/>損しつ,やまいなど, おも荷負い得ず;<br/>',NULL,52030,5);
INSERT INTO stanza VALUES('J635','5','やがて戦争終わり, サタンつながれる;<br/>しょう会はラｯパ聞き, 勝利,栄こう得る。<br/>',NULL,52031,6);
INSERT INTO stanza VALUES('J635','chorus','ゆえにかたく立て！ 勝利の主をおもえ！<br/>イェスはすでに勝利, 雄々しくたたかえ。<br/>',NULL,52032,7);
INSERT INTO stanza VALUES('J635','6','おうはがいせんし, 世を支はいする;<br/>ばんみんはかえり, イェスの名とうとぶ。<br/>',NULL,52033,8);
INSERT INTO stanza VALUES('J636','1','邪あくな日にて, 抵こうして立て,<br/>ひと,おそれるな, 兵士よ,立て。<br/>',NULL,52034,1);
INSERT INTO stanza VALUES('J636','2','ことばあるゆえ, 代価はらい,立て,<br/>聖徒のみち行け, 兵士よ,立て。<br/>',NULL,52035,2);
INSERT INTO stanza VALUES('J636','3','てきの計りゃくに 打ち勝って,立て,<br/>あざむかれるな, 兵士よ,立て。<br/>',NULL,52036,3);
INSERT INTO stanza VALUES('J636','4','かの日来るまで, 主のゆえに立て,<br/>目さまし,いのれ, 兵士よ,立て。<br/>',NULL,52037,4);
INSERT INTO stanza VALUES('J637','1','たんどくではなく, からだのなかで,<br/>かしらにつながり, 御座でたたかう。<br/>',NULL,52038,1);
INSERT INTO stanza VALUES('J637','chorus','からだのなかにて, からだとともに,<br/>かしらにより立ち, ともに勝利する。<br/>',NULL,52039,2);
INSERT INTO stanza VALUES('J637','2','かみの武具はみな, からだが着ける;<br/>からだの戦とうは, みなえきとなる。<br/>',NULL,52040,3);
INSERT INTO stanza VALUES('J637','3','建造された召会は, よみに打ち勝つ;<br/>建造されたからだ, あく魔を対処す。<br/>',NULL,52041,4);
INSERT INTO stanza VALUES('J637','4','からだをとおして, かしらによって,<br/>天に座し,かく闘す, あくの勢りょくと。<br/>',NULL,52042,5);
INSERT INTO stanza VALUES('J637','5','兄弟たちとともに, かみのため立つ;<br/>霊のなかでいのり, 血にて勝利得る。<br/>',NULL,52043,6);
INSERT INTO stanza VALUES('J637','6','勝利から勝利へと, 主の大能通して,<br/>主の軍たいとして, 主にありたたかう。<br/>',NULL,52044,7);
INSERT INTO stanza VALUES('J637','7','からだのなかにて, てき征ふくする;<br/>てき,食いものとし, 御むねを成就す。<br/>',NULL,52045,8);
INSERT INTO stanza VALUES('J638','1','かみはたい能のとりで, 永遠に堅固な保しょう;<br/>てき,われをかこむとも, われにおそれはなし。<br/>すきを見つけ, てき攻め来る,<br/>その計りゃくは 残忍で残こく,<br/>されど,主,わがとりで。<br/>',NULL,52046,1);
INSERT INTO stanza VALUES('J638','2','自分のちからによれば, かならず失ぱいする;<br/>ともに立たれるかみに, われはただしん頼す！<br/>キリストこそ ふさわしいかた;<br/>かれ,万軍の主, とこしえまで,<br/>しょう利はかれのもの！<br/>',NULL,52047,2);
INSERT INTO stanza VALUES('J638','3','この世にあく魔が満ち, 破かいをくわだてる,<br/>されど，かみ,われら通し, 真理によりしょう利す。<br/>名声を去らせ, 生死，考慮せず,<br/>ころされても, 真理なお立つ，<br/>王こくはとわに無限。<br/>',NULL,52048,3);
INSERT INTO stanza VALUES('J639','1','てきはきょう暴, すさまじい;<br/>みことば信じ, 賛美せよ。<br/>',NULL,52049,1);
INSERT INTO stanza VALUES('J639','2','御名さけべば, 勝利する,<br/>くちをひらき, 賛美する。<br/>',NULL,52050,2);
INSERT INTO stanza VALUES('J639','3','憂うつになり, 霊よわる,<br/>血もていのり, 回ふくす。<br/>',NULL,52051,3);
INSERT INTO stanza VALUES('J639','4','たち場に立ち, たたかう,<br/>凶暴なてきに 勝利する。<br/>',NULL,52052,4);
INSERT INTO stanza VALUES('J639','5','主のしょう利を, 宣げんす,<br/>やみ,かならず 変化する。<br/>',NULL,52053,5);
INSERT INTO stanza VALUES('J640','1','つねにかみに「はい」と言い, サタンに「ノー」と言う;<br/>案配のすべてがそれで じょう就するため。<br/>われ,主にしたがい, 主の権威受けて,<br/>その霊に満たされ, みこころ成就す。<br/>',NULL,52054,1);
INSERT INTO stanza VALUES('J640','2','つねにかみに「はい」と言い, サタンに「ノー」と言う;<br/>主よ,それはわがたい度, めぐみあたえよ。<br/>じゅう順になるとき, さまたげのぞき,<br/>みこえを聞くとき, かえりみたまえ！<br/>',NULL,52055,2);
INSERT INTO stanza VALUES('J640','3','つねにかみに「はい」と言い, サタンに「ノー」と言う;<br/>どんな苦なんに出会うとも, 絶対にしたがう。<br/>主と前進するとき, 主まもり,すくう,<br/>ゆうわく,おどしは, われを捕らえず。<br/>',NULL,52056,3);
INSERT INTO stanza VALUES('J641','1','てき,はげしく攻め来て, よみのはん抗はひびく！<br/>されど夜半に主は言う: 「われはかならず来る」と。<br/>',NULL,52057,1);
INSERT INTO stanza VALUES('J641','2','試練はさらにはげしく, よみ,さらにせまり来る;<br/>されど,聖徒ら歓喜して, ともに言う:「主は間ぢか！」<br/>',NULL,52058,2);
INSERT INTO stanza VALUES('J641','3','サタンの攻げき,はげしく, あかしをさまたげるが,<br/>霊のちからでてき討ち, 主,来て,よろこびとなる。<br/>',NULL,52059,3);
INSERT INTO stanza VALUES('J641','4','われら大能で前しんし, かたく信じて勝利得る;<br/>われらがい歌うたって, 「すぐ来る」とのこえ聞く。<br/>',NULL,52060,4);
INSERT INTO stanza VALUES('J641','5','十字架のみち,選たくし, 苦難をしのび,奮闘する;<br/>なおたたかい,前しんし, われは知る:「主は間ぢか！」<br/>',NULL,52061,5);
INSERT INTO stanza VALUES('J641','6','暗こくのなか前しんし, 上げられ,あさ日を見る！<br/>てき敗ぼくし,勝利者は ともにさけぶ:「主は来た！」<br/>',NULL,52062,6);
INSERT INTO stanza VALUES('J642','1','イェスの名にかたく立ち, 主の勝利しんじる;<br/>自己や才のうによらず, 血気の武具もちいず;<br/>かみの武器を身に着け, しん仰のたてを取り,<br/>てきの投げやりを消し, 霊のつるぎ受ける。<br/>',NULL,52063,1);
INSERT INTO stanza VALUES('J642','2','見よ,てきはけっ集する, なが持ち場まもれ！<br/>やみのなか,てきせまる, 主によりてい抗せよ！<br/>なれがしりぞくならば, ぜん軍はどう揺する;<br/>兄だいたちのこころを なれゆえくじくな。<br/>',NULL,52064,2);
INSERT INTO stanza VALUES('J642','3','ときはみじかいと知り, サタンいかりくるう,<br/>たたかいのまえでさえ, なが霊をくるしめる。<br/>誘わく,試れん,苦なんは, ますますおおくなり,<br/>よみのちから攻め寄せ, おそろしさは増す。<br/>',NULL,52065,3);
INSERT INTO stanza VALUES('J642','4','このようなじょうけいに, いかに振る舞うや？<br/>あん易,安らくもとめて, てきに食われるのか？<br/>苦難の増すことにより, さらにゆう気出すか？<br/>生きるも,死ぬるもただ, 主のほまれのため！<br/>',NULL,52066,4);
INSERT INTO stanza VALUES('J642','5','主のためにかたく立て; 主イェスはしょう利者！<br/>苦つう,なお耐えしのべ, かの日にいたるまで。<br/>間もなくイェスは来たり, たたかい,しゅうけつす;<br/>いま,主のため苦難受け, かの日,権威受ける。<br/>',NULL,52067,5);
INSERT INTO stanza VALUES('J643','1','勝利,勝利,ハレルヤ！ 勝利,勝利,ハレルヤ！<br/>キリストはすでに しょう利得たもう！<br/>',NULL,52068,1);
INSERT INTO stanza VALUES('J643','2','勝利,勝利,ハレルヤ！ 勝利,勝利,ハレルヤ！<br/>われらも主といま ともに勝利者！<br/>',NULL,52069,2);
INSERT INTO stanza VALUES('J643','3','えいこう,ハレルヤ！ えいこう,ハレルヤ！<br/>えいこうはすべて 御名にあれや！<br/>',NULL,52070,3);
INSERT INTO stanza VALUES('J644','1','ハレルヤ,イェス勝利！ がい歌あり！<br/>つみと死,あく魔に イェスは勝利！<br/>',NULL,52071,1);
INSERT INTO stanza VALUES('J644','chorus','ハレルヤ,えい光のおとずれは！<br/>イェス勝利,すべてにイェスは勝利！<br/>',NULL,52072,2);
INSERT INTO stanza VALUES('J644','2','ハレルヤ,イェス勝利！ 血のちから！<br/>十字架のしょう利に, あく魔逃げん。<br/>',NULL,52073,3);
INSERT INTO stanza VALUES('J644','3','ハレルヤ,イェス勝利！ やまい消し,<br/>ゴルゴタ,しょう利を じょう就した。<br/>',NULL,52074,4);
INSERT INTO stanza VALUES('J644','4','ハレルヤ,イェス勝利！ ちからあり！<br/>つかわしたまえば いずこへも。<br/>',NULL,52075,5);
INSERT INTO stanza VALUES('J644','5','ハレルヤ,イェス勝利！ おそれなし！<br/>くらやみ,みち覆うも, イェスひらく。<br/>',NULL,52076,6);
INSERT INTO stanza VALUES('J644','6','ハレルヤ,勝利の主！ すぐ来たもう！<br/>勝利者もともども よろこばん。<br/>',NULL,52077,7);
INSERT INTO stanza VALUES('J645','1','天地のすべてのけん威, 復かつの主は得た;<br/>主につながり,主を生き, てきをせいふくする。<br/>',NULL,52078,1);
INSERT INTO stanza VALUES('J645','2','あく魔にかならず勝つ！ 主のなかで告げよ;<br/>主からのけん威を受け, へびのかしら,くだけ。<br/>',NULL,52079,2);
INSERT INTO stanza VALUES('J645','3','天も地もたかきやまも, かならず平らにし,<br/>主の名によりそこから すみやかにはなれよ！<br/>',NULL,52080,3);
INSERT INTO stanza VALUES('J645','4','「うみに行け」と言う主に 信仰によりふくす;<br/>われらはかみの御むね, かならず成し遂げる。<br/>',NULL,52081,4);
INSERT INTO stanza VALUES('J646','1','しょう利者,主の血で, てきに打ち勝て;<br/>その効き目,ちから, 勝利を得させる。<br/>',NULL,52082,1);
INSERT INTO stanza VALUES('J646','chorus','しょう利者,主の血で, てきに打ち勝てー;<br/>その効き目,ちから, 勝利を得させる。<br/>',NULL,52083,2);
INSERT INTO stanza VALUES('J646','2','こく訴するてきに, 血によりしょう利;<br/>そしり,しりぞける, べん護する血で。<br/>',NULL,52084,3);
INSERT INTO stanza VALUES('J646','3','かみのしんじつを, 血により信じる。<br/>あがないの血により ゆるしを受けた。<br/>',NULL,52085,4);
INSERT INTO stanza VALUES('J646','4','主の血にて，われの 地位,宣こくする;<br/>とわの勝利の血で, てき打ちやぶる。<br/>',NULL,52086,5);
INSERT INTO stanza VALUES('J646','5','しょう利の血により 主の権威を取る;<br/>血をてき用すれば, かならずしょう利。<br/>',NULL,52087,6);
INSERT INTO stanza VALUES('J646','6','キリストの血にて, てんじょうに座し,<br/>主のけんのうにて, てき打ちやぶる。<br/>',NULL,52088,7);
INSERT INTO stanza VALUES('J647','1','なれ勝利者なるや？ 主は召さる！<br/>忠じつな従者たれ, おさなくも。<br/>',NULL,52089,1);
INSERT INTO stanza VALUES('J647','chorus','なれ勝利者なるや？ 主は召さる！<br/>かんむりを得るよう 主は召さる！<br/>',NULL,52090,2);
INSERT INTO stanza VALUES('J647','2','主に引き寄せられ, 勝利を得る;<br/>「はじめの愛」たもつ, かの日まで。<br/>',NULL,52091,3);
INSERT INTO stanza VALUES('J647','3','主のいのちを生き, 勝利を得よ;<br/>死にいたるまでも 忠信であれ。<br/>',NULL,52092,4);
INSERT INTO stanza VALUES('J647','4','あかしとなるため, 勝利を得る;<br/>かくされたマナを 食べつづけ。<br/>',NULL,52093,5);
INSERT INTO stanza VALUES('J647','5','たん純とまことで 勝利を得る;<br/>混ごうに打ち勝ち, 権威を得る。<br/>',NULL,52094,6);
INSERT INTO stanza VALUES('J647','6','生ける主にたのみ, 勝利を得る;<br/>ころもをけがさず, いのち得る。<br/>',NULL,52095,7);
INSERT INTO stanza VALUES('J647','7','主の名をいなまず, 勝利を得る;<br/>主のことばまもり, 忍たいする。<br/>',NULL,52096,8);
INSERT INTO stanza VALUES('J647','8','なまぬるくならず, 勝利を得る;<br/>まん心せず,さらに 豊富を得る。<br/>',NULL,52097,9);
INSERT INTO stanza VALUES('J647','9','なれ勝利者なるや？ 主は召さる！<br/>みこころのじょう就, 主にねがう。<br/>',NULL,52098,10);
INSERT INTO stanza VALUES('J648','1','失敗したくない, 勝利得るため。<br/>ゴルゴタで主は サタンに勝利す;<br/>主よ,ビジｮンあたえ, われはげまし,<br/>なが大能により 勝利を得させよ。<br/>',NULL,52099,1);
INSERT INTO stanza VALUES('J648','chorus','勝利者,勝利す, ゴルゴタゆえ。<br/>なれにあり勝利す, なれのため勝利する。<br/>',NULL,52100,2);
INSERT INTO stanza VALUES('J648','2','失敗したくない, 勝利得るため。<br/>われ前線に召し, 追げきさせる。<br/>大胆さをあたえ, われをつよめ,<br/>うちを満たして 勝利を得させよ。<br/>',NULL,52101,3);
INSERT INTO stanza VALUES('J648','3','失敗したくない, 勝利得るため。<br/>よみを突破させ, 御座に着かせ,<br/>ちからをあたえ, つるぎ持たせ,<br/>みことばにより 勝利を得させよ。<br/>',NULL,52102,4);
INSERT INTO stanza VALUES('J648','4','失敗したくない, 勝利得るため。<br/>いま,日暮れどき, 主は待っている,<br/>「われのしもべよ, よくやった」との<br/>みこえ聞くため, 勝利を得させよ。<br/>',NULL,52103,5);
INSERT INTO stanza VALUES('J649','1','かみの子らにサタン てき対する;<br/>情ほう得たものよ, ちゅう意せよ！<br/>',NULL,52104,1);
INSERT INTO stanza VALUES('J649','chorus','われ,たたかうため, ここにいる;<br/>御むねをなすため 戦とうする。<br/>',NULL,52105,2);
INSERT INTO stanza VALUES('J649','2','やみのぐんぜいが せまり来る;<br/>従軍した召かいよ, ふん起せよ！<br/>',NULL,52106,3);
INSERT INTO stanza VALUES('J649','3','陣えいでそむかず, 世を愛さず,<br/>召かいはたたかい, 主にふくせ。<br/>',NULL,52107,4);
INSERT INTO stanza VALUES('J649','4','てきにのぞむとき, つよくあれ;<br/>召かい,らくするは, 何というはじ！<br/>',NULL,52108,5);
INSERT INTO stanza VALUES('J649','5','主につかないなら, てきとなる;<br/>従軍した召かいよ, だれにつく？<br/>',NULL,52109,6);
INSERT INTO stanza VALUES('J649','6','勝利者は勝利得て, 主を享受す;<br/>召かいよ,十字架は なれのもの。<br/>',NULL,52110,7);
INSERT INTO stanza VALUES('J649','7','真の戦士なる主は, 危険避けぬ;<br/>従軍した召かいよ, おそれるな。<br/>',NULL,52111,8);
INSERT INTO stanza VALUES('J649','8','主は勝利者を召す, だれ応じる？<br/>おくれず,武具着け, ぜん進せよ。<br/>',NULL,52112,9);
INSERT INTO stanza VALUES('J650','1','わが意志ではなく, みちびきによる;<br/>生けるみず,ある場所, また照らしある。<br/>',NULL,52113,1);
INSERT INTO stanza VALUES('J650','2','自己のせんたくを, 主はよろこばず;<br/>主の委たく成し遂げ, 主の称賛を得る。<br/>',NULL,52114,2);
INSERT INTO stanza VALUES('J650','3','自己の意のままに, いのるのでなく,<br/>せいれいのうめきで, 御むねに触れる。<br/>',NULL,52115,3);
INSERT INTO stanza VALUES('J650','4','かみのひつように, 「いな」と言うなら,<br/>祭だんにささげても, よろこばれない。<br/>',NULL,52116,4);
INSERT INTO stanza VALUES('J650','5','自己を死にわたし, 主とともに生き,<br/>ささげて,つかえれば, かみ,褒賞となる。<br/>',NULL,52117,5);
INSERT INTO stanza VALUES('J651','1','主がつかわすならば, どんな場所でも,<br/>秘境とかぎらないが, 主よ,まいります。<br/>主の召すこえがあれば, 見知らぬ地でさえ,<br/>ためらわずに,よろこんで, 主よ,まいります。<br/>',NULL,52118,1);
INSERT INTO stanza VALUES('J651','chorus','主よ,どこでも行きます, 平地でも,山地でも;<br/>主がのぞむこと,わたしも, 主よ,おこないます。<br/>',NULL,52119,2);
INSERT INTO stanza VALUES('J651','2','主がさけんでほしい ことばあります,<br/>主が連れもどしたい つみびといます。<br/>主が来てみちびくなら, みちはくらくとも,<br/>良きおとずれに呼おうし, 主よ,かたります。<br/>',NULL,52120,3);
INSERT INTO stanza VALUES('J651','3','このこうだいな地に, 自分の分がある,<br/>わがため死んだ主に, 生涯ささげます;<br/>自分を御手にたくして, ふかきあいを知り,<br/>あなたのみこころのまま, 主よ,したがいます。<br/>',NULL,52121,4);
INSERT INTO stanza VALUES('J652','1','しょうらい,おおきなことすると, とおくばかり見るな,<br/>もくぜんに果たすべき分ある, 自分のそば照らせ。<br/>',NULL,52122,1);
INSERT INTO stanza VALUES('J652','chorus','自分のそば照らせ！ 自分のそば照らせ！<br/>せい徒は苦難によりかがやく, なおつよく照らせ。<br/>',NULL,52123,2);
INSERT INTO stanza VALUES('J652','2','「ながひかり照らせ」と主は言う, ながかがやき覆うな;<br/>ひとをすくい,みちびくために, 自分のそば照らせ。<br/>',NULL,52124,3);
INSERT INTO stanza VALUES('J652','3','自ぶんのまわりを見るならば, さまようせい徒がいる,<br/>主のもとへ引きもどすために, 自分のそば照らせ。<br/>',NULL,52125,4);
INSERT INTO stanza VALUES('J652','4','主とまじわり,御かおあおげば, 栄光うつし,かがやく;<br/>主をあいせば,ひとは感動する, 自分のそば照らせ。<br/>',NULL,52126,5);
INSERT INTO stanza VALUES('J652','5','間もなく主じんはかえって来て, しもべはほう賞得る;<br/>ひとすくい,せい徒ばん回せよ, 自分のそば照らせ。<br/>',NULL,52127,6);
INSERT INTO stanza VALUES('J653','1','ながれのなか！ながれのなか！<br/>主のためにはたらきましょう。<br/>かれのおもい,かれのみちで,<br/>いのちのながれのなかにて。<br/>',NULL,52128,1);
INSERT INTO stanza VALUES('J653','chorus','かれのみくに,しょう会のため,<br/>主のちからで，天のチームとして。<br/>',NULL,52129,2);
INSERT INTO stanza VALUES('J653','2','ながれのなか！ながれのなか！<br/>主とともにはたらきましょう。<br/>かれのことば,おしえられて,<br/>その霊のながれのなかにて。<br/>',NULL,52130,3);
INSERT INTO stanza VALUES('J653','3','ながれのなか！ながれのなか！<br/>主のなかではたらきましょう。<br/>しょう会のなか,聖徒らともに,<br/>みことばのひかりのなかで。<br/>',NULL,52131,4);
INSERT INTO stanza VALUES('J654','1','新やくの奉仕みな, 文字でなくその霊;<br/>文字はひところし, 霊はひと生かす。<br/>主が見られるのは, うちがわのこと;<br/>霊のあたらしさで 奉仕し,つかえる。<br/>',NULL,52132,1);
INSERT INTO stanza VALUES('J654','2','がい面のおしえや ようしきではなく,<br/>内面のあぶら塗り, みちびきによる。<br/>ひとの規定でなく, 決ていでもなく,<br/>それは天のかん理, 主の啓示による。<br/>',NULL,52133,2);
INSERT INTO stanza VALUES('J654','3','死んだ宗教ではなく, キリスト供きゅうす;<br/>しんがくではなく, 主の豊富による。<br/>教理,知しきでなく, 主をかたり出す;<br/>儀しき,律法でなく, 主を実際とする。<br/>',NULL,52134,3);
INSERT INTO stanza VALUES('J654','4','外面の礼拝でなく, 真に主につかえる;<br/>単なる伝道でなく, 主をひょう現する。<br/>聖書だけではなく, その霊といのち,<br/>にく,自己ではなく, 大能の霊による。<br/>',NULL,52135,4);
INSERT INTO stanza VALUES('J655','1','いのちながれ出て, はたらきとなる;<br/>生かつがともなって, 結果が得られる。<br/>経けんしたことを, われ,かたり出す,<br/>かたり出すことみな, 経けんしたもの。<br/>',NULL,52136,1);
INSERT INTO stanza VALUES('J655','2','その霊のはたらき, 霊の実をむすぶ;<br/>ぶどうの木のように, 豊富をあらわす。<br/>キリスト,われより, 生かし出されて,<br/>主のいのちの豊富が, ひとに見られる。<br/>',NULL,52137,2);
INSERT INTO stanza VALUES('J655','3','ひとの運動でなく, 聖霊のかんどう,<br/>外面の行どうでなく, 内面のはたらき;<br/>ひとの事業でなく, いのちのひょう現,<br/>ひとの労苦ではなく, 主,表現すること。<br/>',NULL,52138,3);
INSERT INTO stanza VALUES('J655','4','われのけいかくを すべて放棄する,<br/>かみのごけいかくを じょう就するため。<br/>われを死にわたし, 主を生かし出し,<br/>主のとみ,うるわしさ, ともにてん覧す。<br/>',NULL,52139,4);
INSERT INTO stanza VALUES('J656','1','からだのほう仕を, 主はおもく見たもう;<br/>からだがもくてき, われらしたがう。<br/>',NULL,52140,1);
INSERT INTO stanza VALUES('J656','chorus','からだのなかにて, など孤りつすべき;<br/>いち肢たいの分を, からだに果たす。<br/>',NULL,52141,2);
INSERT INTO stanza VALUES('J656','2','さい生されたのは, 肢たいとなるため;<br/>個々の自ゆうなく, むすび合わさる。<br/>',NULL,52142,3);
INSERT INTO stanza VALUES('J656','3','生けるいしとして, ともに建てられる,<br/>さい司のたい系は, ちょう和し,奉仕す。<br/>',NULL,52143,4);
INSERT INTO stanza VALUES('J656','4','ぶんにしたがいて, ともに建てらるは,<br/>からだのせいしつ, ほう仕のこん拠。<br/>',NULL,52144,5);
INSERT INTO stanza VALUES('J656','5','からだのきょう給を 得て,つとめ果たす;<br/>からだ,はなれれば, 機のう,うしなう。<br/>',NULL,52145,6);
INSERT INTO stanza VALUES('J656','6','からだのほう仕で, かしらのとみ受け,<br/>肢たいのやく目で, キリスト満ちる。<br/>',NULL,52146,7);
INSERT INTO stanza VALUES('J656','7','みかしらにかたく むすびつくときに,<br/>かしらのきょうきゅう, からだにながる。<br/>',NULL,52147,8);
INSERT INTO stanza VALUES('J656','8','われらのからだを, あらたにささげる,<br/>おもいつくり変え, 御むね知らせよ。<br/>',NULL,52148,9);
INSERT INTO stanza VALUES('J657','1','さい司のせいかつ, なんとさちなる！<br/>衣,しょく,住すべては, 分なるキリスト。<br/>',NULL,52149,1);
INSERT INTO stanza VALUES('J657','chorus','さい司のせいかつ, なんとさちなる！<br/>衣,しょく,住すべては, 分なるキリスト。<br/>',NULL,52150,2);
INSERT INTO stanza VALUES('J657','2','ほう仕のころもは, 主のうるわしさ;<br/>衣ふくやかんむり, えいこうで尊貴。<br/>',NULL,52151,3);
INSERT INTO stanza VALUES('J657','3','キリストささげて, 祭司は機能する,<br/>しょくもつなる主を 食べて満ぷくす。<br/>',NULL,52152,4);
INSERT INTO stanza VALUES('J657','4','ころもとして,主を そとにあらわし,<br/>飲しょくにより,主と うちで混ざり合う。<br/>',NULL,52153,5);
INSERT INTO stanza VALUES('J657','5','しん聖なえい光は, さい司の住まい;<br/>ともに建造されて, 霊のいえとなる。<br/>',NULL,52154,6);
INSERT INTO stanza VALUES('J657','6','さい司の嗣ぎょうは, 内住のキリスト,<br/>せいかつすべては キリストご自身。<br/>',NULL,52155,7);
INSERT INTO stanza VALUES('J658','1','われらのほう仕は, ただ召会のため;<br/>そは主のみこころ, 使徒たちの実行。<br/>',NULL,52156,1);
INSERT INTO stanza VALUES('J658','chorus','われらのほう仕は, ただ召会のため;<br/>これは主の御むね, われらおこなう。<br/>',NULL,52157,2);
INSERT INTO stanza VALUES('J658','2','召会は主のうつわ, とわのご計かく;<br/>すべてのほう仕は, けんぞうのため。<br/>',NULL,52158,3);
INSERT INTO stanza VALUES('J658','3','たまものあるひと, からだのなかで,<br/>しょう会をけん造し, ほう満もたらす。<br/>',NULL,52159,4);
INSERT INTO stanza VALUES('J658','4','たまもの,機のうも, れいのちからも,<br/>すべてのつとめは, しょうかいのため。<br/>',NULL,52160,5);
INSERT INTO stanza VALUES('J658','5','ふく音もおしえも, やしない,かん理も,<br/>すべてのほう仕は, みからだのため。<br/>',NULL,52161,6);
INSERT INTO stanza VALUES('J658','6','しょう会がつとめの ためではなしに,<br/>つとめは,しょうかい, しょくだいのため。<br/>',NULL,52162,7);
INSERT INTO stanza VALUES('J658','7','これがしょうかいの いちをたもって,<br/>わが動機をさぐり, もくてきただす。<br/>',NULL,52163,8);
INSERT INTO stanza VALUES('J658','8','自ぶんのわざより, 主よ,すくいませ;<br/>われらのろう苦は, しょうかいのため。<br/>',NULL,52164,9);
INSERT INTO stanza VALUES('J659','1','かみにもひとにも, キリストきょう給す;<br/>キリストささぐは, まことのほう仕。<br/>',NULL,52165,1);
INSERT INTO stanza VALUES('J659','chorus','かみにもひとにも, キリスト供給す;<br/>キリストささぐは, まことのほう仕。<br/>',NULL,52166,2);
INSERT INTO stanza VALUES('J659','2','良き地のほう富を ささげしごとくに,<br/>主からのしゅうかく, われらもささぐ。<br/>',NULL,52167,3);
INSERT INTO stanza VALUES('J659','3','主,われらの良き地, その地をたがやし,<br/>かれから収かくし, われら分け合う。<br/>',NULL,52168,4);
INSERT INTO stanza VALUES('J659','4','かしらにつながり, 肢たいは機のうし,<br/>主を受け,ながして, からだに奉仕す。<br/>',NULL,52169,5);
INSERT INTO stanza VALUES('J659','5','まじわり,あかしも, ことばのつとめも,<br/>主と主のほう富を きょう給するため。<br/>',NULL,52170,6);
INSERT INTO stanza VALUES('J660','1','ときはおおくなく, たび路，過ぎ去る,<br/>引き上げ間ぢか, おうにまみえる;<br/>きん勉であらせよ, さい臨をのぞむ。<br/>',NULL,52171,1);
INSERT INTO stanza VALUES('J660','2','あつく主をもとめ, ちからを尽くし，<br/>十字架をにない, 苦なんをねがう;<br/>主が来られるまで, 主の「商ばい」する。<br/>',NULL,52172,2);
INSERT INTO stanza VALUES('J660','3','あく霊を追い出し, くらやみ攻める,<br/>たたかいに勝利し, へいあんを得る;<br/>日々絶えずいのり, せんじょうに立つ。<br/>',NULL,52173,3);
INSERT INTO stanza VALUES('J660','4','霊,たましい,からだ, 主にまもられて,<br/>主にかん理され, かん全にふくす;<br/>たゆまずつかえて, 用意ととのえる。<br/>',NULL,52174,4);
INSERT INTO stanza VALUES('J660','5','用意をととのえる, 試れん受けても,<br/>主もとめなくば, 生かつ意義なし;<br/>主よ,はやく来ませ！ きょうにも来ませ！<br/>',NULL,52175,5);
INSERT INTO stanza VALUES('J661','1','いそぎ,はたらく, 夜はすぐ来る;<br/>あたらしいあさに, 太陽のもと;<br/>はたらきできない 夜来るまえに,<br/>いそぎ,はたらく, よるが来る。<br/>',NULL,52176,1);
INSERT INTO stanza VALUES('J661','2','いそぎ,はたらく, ひるのうちに;<br/>あかるいときに, きんべんに。<br/>よるに労苦解かれ, 安そくに入る,<br/>いそぎ,はたらく, よるが来る。<br/>',NULL,52177,2);
INSERT INTO stanza VALUES('J661','3','いそぎ,はたらく, 夜はすぐ来る;<br/>夕暮れのときを 捕らえよう;<br/>一瞬によるが来て, はたらきやむ,<br/>いそぎ,はたらく, よるが来る。<br/>',NULL,52178,3);
INSERT INTO stanza VALUES('J662','1','えい光のふく音は, いのちのながれ;<br/>ひとはすくわれる, 生けるあかしで。<br/>',NULL,52179,1);
INSERT INTO stanza VALUES('J662','chorus','生けるみずながし, いのちあらわし,<br/>ひとの霊を生かす うつわとなせや。<br/>',NULL,52180,2);
INSERT INTO stanza VALUES('J662','2','いのちのあかしで, ひとはしんじる;<br/>いのち,供きゅうされ, 主を受け入れる。<br/>',NULL,52181,3);
INSERT INTO stanza VALUES('J662','3','ぶどうの木のように, 主のなかに住み,<br/>いのちをながして, 主を供きゅうする。<br/>',NULL,52182,4);
INSERT INTO stanza VALUES('J662','4','せいかつのなかで, 主を表げんする;<br/>ことばだけでなく, いのち植え込む。<br/>',NULL,52183,5);
INSERT INTO stanza VALUES('J663','1','せい徒ら,いそぎ出て行き, かみの愛,告げ知らせよ:<br/>かみはすくいを成就して, ひとのほろび,ねがわず。<br/>',NULL,52184,1);
INSERT INTO stanza VALUES('J663','chorus','良き知らせ,つたえる,<br/>すくいのじょう就をつたえる。<br/>',NULL,52185,2);
INSERT INTO stanza VALUES('J663','2','世のひと,つみにしばられ, あく魔のはい下にある;<br/>主のすくいは成就された, 主の復かつ,勝利述べよ。<br/>',NULL,52186,3);
INSERT INTO stanza VALUES('J663','3','主はひとをつみより解き, ふるいひとを終わらす;<br/>危けんおそれず,出て行き, ひとに主を信じさせよ。<br/>',NULL,52187,4);
INSERT INTO stanza VALUES('J663','4','世かいのたみ,くに,ひとに, めぐみをつたえに行け,<br/>かみはにくたい取り,死に, ひとを再生す,と告げよ。<br/>',NULL,52188,5);
INSERT INTO stanza VALUES('J663','5','ふく音つたえに行くのを, 財ぶつささげ,たすけよ,<br/>ふく音のかく大をいのれ, 主は犠牲をおぼえたもう。<br/>',NULL,52189,6);
INSERT INTO stanza VALUES('J663','6','間もなくすくいぬし来る！ とき捕らえ,分を果たせ;<br/>たゆまずに主をつたえて, 世びとを主にもたらせ。<br/>',NULL,52190,7);
INSERT INTO stanza VALUES('J664','1','さあ,ふくいんをつたえよう！ たましいをうばい取ろう！<br/>千まんのひとほろびゆく！ あわれみをとどめるな。<br/>',NULL,52191,1);
INSERT INTO stanza VALUES('J664','chorus','さあ,ふくいんをつたえよう！ ひとのほろび見るのか？<br/>',NULL,52192,2);
INSERT INTO stanza VALUES('J665','1','キリストあたえよ, ことばとこう為で。<br/>せいかつをとおして, あわれなひとらに。<br/>',NULL,52193,1);
INSERT INTO stanza VALUES('J665','chorus','キリストあたえよ, せいかつのなかで;<br/>キリスト生かし出し, 持つものあたえよ。<br/>',NULL,52194,2);
INSERT INTO stanza VALUES('J665','2','キリストあたえよ, とうといなが主を;<br/>したしいひとたちに, たからを得させよ。<br/>',NULL,52195,3);
INSERT INTO stanza VALUES('J665','3','キリストあたえよ, あなたのともらに;<br/>自分の享受した主を, しゅくふくなる主を。<br/>',NULL,52196,4);
INSERT INTO stanza VALUES('J665','4','キリストあたえよ, 会うひとすべてに;<br/>いのち,またすべての キリストあたえよ。<br/>',NULL,52197,5);
INSERT INTO stanza VALUES('J666','1','みやの材料をあつめよ, したしいともにかたれ;<br/>連れ来たれ,つみびとを, むれにもたらせ,ひつじを。<br/>',NULL,52198,1);
INSERT INTO stanza VALUES('J666','2','みやの材料をあつめよ, 世びとを世からすくえ;<br/>あく魔のやみ,あざむき, 誘わくよりはなれさせよ。<br/>',NULL,52199,2);
INSERT INTO stanza VALUES('J666','3','みやの材料をあつめよ, 流浪者をむれにもどせ;<br/>サタンやぶり,ひとを解き, 主のふところにもたらせ。<br/>',NULL,52200,3);
INSERT INTO stanza VALUES('J666','4','みやの材料をあつめよ, からだのたち場に立ち;<br/>ひとつれい,たましいで, 吹けや,ふくいんのラｯパを。<br/>',NULL,52201,4);
INSERT INTO stanza VALUES('J667','1','あさもひるも, ゆうぐれにも,<br/>かみのあいの たねをまく;<br/>せいじゅくして, 刈り取るとき,<br/>よろこび満ち, しゅうかくす。<br/>',NULL,52202,1);
INSERT INTO stanza VALUES('J667','chorus','たばかかえ,かえり来る, よろこび満ち,かえり来る。<br/>たばかかえ,かえり来る, よろこび満ち,かえり来る。<br/>',NULL,52203,2);
INSERT INTO stanza VALUES('J667','2','えん天にまき, どん天にまく,<br/>かぜもくもも, おそれずに;<br/>のうさくもつ, やがてみのり,<br/>よろこび満ち, しゅうかくす。<br/>',NULL,52204,3);
INSERT INTO stanza VALUES('J667','3','行け,主のため, たねたずさえ,<br/>うしなうとも, 耐えしのび,<br/>なみだをもて まけばついに,<br/>よろこび満ち, しゅうかくす。<br/>',NULL,52205,4);
INSERT INTO stanza VALUES('J668','1','主よ,なにも持たずに, 御かお見られよう？<br/>労苦をしなかったので, ささぐものなし。<br/>',NULL,52206,1);
INSERT INTO stanza VALUES('J668','chorus','から手で主のまえに どうして出られよう？<br/>ひとりもキリストに 帰することなく！<br/>',NULL,52207,2);
INSERT INTO stanza VALUES('J668','2','めぐみを受けたいま, 死のおそれないが,<br/>から手で主のまえに 出るをおそれる。<br/>',NULL,52208,3);
INSERT INTO stanza VALUES('J668','3','浪費したさいげつを 取りもどせるなら,<br/>かんぜんにささげて, みこころおこなう。<br/>',NULL,52209,4);
INSERT INTO stanza VALUES('J668','4','聖徒よ,ひるのうちに, 勤べんにはたらけ；<br/>死の夜のぞむまえに, すくいもたらせ。<br/>',NULL,52210,5);
INSERT INTO stanza VALUES('J669','1','天でいのるすくいぬしあり,<br/>かえりみ,愛じょうはゆたか;<br/>主のふかきあい,いつも絶えぬ；<br/>主がなが主となるように！<br/>',NULL,52211,1);
INSERT INTO stanza VALUES('J669','chorus','1-4<br/>なれのためにわれらいのる！<br/>主がなれをすくうようにと！<br/>',NULL,52212,2);
INSERT INTO stanza VALUES('J669','chorus','5<br/>ひとのためになれもいのれ！<br/>主がかれをすくうようにと！<br/>',NULL,52213,3);
INSERT INTO stanza VALUES('J669','2','天に住むひとりのちちあり,<br/>えい遠ののぞみあたえる;<br/>われを引き上げ,まみえさせる;<br/>このめぐみ,なれにもあれ！<br/>',NULL,52214,4);
INSERT INTO stanza VALUES('J669','3','尽きぬよろこびわれにあり,<br/>主はわがつみをになわれ,<br/>いまや主はわがうちに生きる;<br/>このかん喜,なれにもあれ！<br/>',NULL,52215,5);
INSERT INTO stanza VALUES('J669','4','おだやかなへいあんがあり,<br/>世の知らぬくしきへい安;<br/>ただ主イェスのみ,そのみなもと;<br/>このへい安,なれにもあれ！<br/>',NULL,52216,6);
INSERT INTO stanza VALUES('J669','5','すくい得たら,ひとに告げよ:<br/>いかにすくい得たのかを;<br/>ひとのすくいのためにいのれ;<br/>主はながいのり聞かれる！<br/>',NULL,52217,7);
INSERT INTO stanza VALUES('J670','1','かみに会うため, そなえをしましょう,<br/>悔いあらためて, 主,信じましょう;<br/>すくいのめぐみを 受けましょう。<br/>',NULL,52218,1);
INSERT INTO stanza VALUES('J670','2','かみに会うため, そなえをしましょう;<br/>かみに会うため, つみを捨て;<br/>主イェスの名を呼び, すくわれよう。<br/>',NULL,52219,2);
INSERT INTO stanza VALUES('J670','3','かみに会うため, そなえをしましょう;<br/>かみに会うため, ささげましょう;<br/>かん全にささげて, かみに行こう。<br/>',NULL,52220,3);
INSERT INTO stanza VALUES('J671','1','キリストわがため, だい価をはらい,<br/>あがないじょう就す, 不思議なすくい！<br/>',NULL,52221,1);
INSERT INTO stanza VALUES('J671','chorus','不思議なすくい, わが主イェスよ！<br/>不思議なすくい, イェスわが主！<br/>',NULL,52222,2);
INSERT INTO stanza VALUES('J671','2','効き目ある主の血, いま賛美します,<br/>かみに和かいさす 不思議なすくい！<br/>',NULL,52223,3);
INSERT INTO stanza VALUES('J671','3','主はわがつみ,とが, すべてあらって,<br/>わがうち支はいす, 不思議なすくい！<br/>',NULL,52224,4);
INSERT INTO stanza VALUES('J671','4','主は絶えずまもり, ともにおられる;<br/>やしないはぐくむ, 不思議なすくい！<br/>',NULL,52225,5);
INSERT INTO stanza VALUES('J671','5','しょう利のちからを 絶えずあたえる;<br/>しょう利を得させる 不思議なすくい！<br/>',NULL,52226,6);
INSERT INTO stanza VALUES('J671','6','主よ,わがこころを, 主にささげます;<br/>この世に死なせる, 不思議なすくい！<br/>',NULL,52227,7);
INSERT INTO stanza VALUES('J672','1','ある日,てんにさん美満つ, つみのくらやみの世に,<br/>イェスは処女より生まれて, われらのあいだに住む！<br/>',NULL,52228,1);
INSERT INTO stanza VALUES('J672','chorus','主,わがため,来たり,死に, ほうむられ,つみのぞく;<br/>よみがえって,義とされる: ある日,主はさいりんす！<br/>',NULL,52229,2);
INSERT INTO stanza VALUES('J672','2','ある日,カルバリのやまで, くぎ打たれ,あざけられ,<br/>くるしみ,捨てられて,死ぬ, 主はわがあがないぬし！<br/>',NULL,52230,3);
INSERT INTO stanza VALUES('J672','3','ある日,主はくるしみより 解かれて,あんそくする;<br/>のぞみなきものののぞみ, 主イェスわがすくいぬし！<br/>',NULL,52231,4);
INSERT INTO stanza VALUES('J672','4','ある日,いし取りのぞかれ, 主ははかより出られた;<br/>よみがえり,しょうてんして, 主,またキリストとなる！<br/>',NULL,52232,5);
INSERT INTO stanza VALUES('J672','5','ある日,えいこうのなかで, 主イェスはさいりんする;<br/>えいこうなるすくいぬし, この主イェスはわがもの！<br/>',NULL,52233,6);
INSERT INTO stanza VALUES('J673','1','イェス,ベツレヘムに来て, 「かなしみのひと」となる;<br/>すくいを得させるため, 主は来られた！<br/>主,われをさがす！ 主,われをさがす！<br/>すくいを得させるため, 主は来られた！<br/>',NULL,52234,1);
INSERT INTO stanza VALUES('J673','2','イェスは十字架のうえで, われらの負さい,はらう;<br/>自ゆうを得させるため, 主は死なれた！<br/>主,わがため死ぬ！ 主,わがため死ぬ！<br/>自ゆうを得させるため, 主は死なれた！<br/>',NULL,52235,2);
INSERT INTO stanza VALUES('J673','3','イェス,生けるすくいぬし, さまようわれを呼ばれる;<br/>まねきこばむわれをも, 主は呼ばれる！<br/>おお,主は呼ばれる！ おお,主は呼ばれる！<br/>まねきこばむわれをも, 主は呼ばれる！<br/>',NULL,52236,3);
INSERT INTO stanza VALUES('J673','4','イェス,やがてさい臨する, かん美な主のやくそく;<br/>さい臨の主,待ちのぞむ, 主は来られる！<br/>主,わがため来る！ 主,わがため来る！<br/>さい臨の主,待ちのぞむ, 主は来られる！<br/>',NULL,52237,4);
INSERT INTO stanza VALUES('J674','1','偉だいなる医者は, したしい主イェス,<br/>つみのきずいやす, 主イェスに行こう。<br/>',NULL,52238,1);
INSERT INTO stanza VALUES('J674','chorus','主はつみをにない, われらのため死ぬ,<br/>きずいやされる イェスに行こう！<br/>',NULL,52239,2);
INSERT INTO stanza VALUES('J674','2','つみがおおくとも, 主はゆるされる！<br/>とがめがあるとも, 主イェスに行こう。<br/>',NULL,52240,3);
INSERT INTO stanza VALUES('J674','3','せいしつがわるく, つみに生きても,<br/>よわく,うめいても, 主イェスに行こう。<br/>',NULL,52241,4);
INSERT INTO stanza VALUES('J674','4','憂うつで,くるしみ, 飢え,かわくなら,<br/>いのちのいずみの 主イェスに行こう。<br/>',NULL,52242,5);
INSERT INTO stanza VALUES('J674','5','イェスを受け入れて, いやされました;<br/>小ひつじをたたえ, なおも信じます。<br/>主の受けたきずで, いやされ,解かれた,<br/>イェスをしんじて, いのちを得た。<br/>',NULL,52243,6);
INSERT INTO stanza VALUES('J674','6','主の名あいします, イェスを愛します！<br/>すくい得させる名, とうとい名,イェス！<br/>こうばしい名うたう！ とうとい名うたう！<br/>すべてにまさる, とうとい名,イェス！<br/>',NULL,52244,7);
INSERT INTO stanza VALUES('J674','7','たずさえ上げられ, わがイェスを見る,<br/>さらに主を賛美す: イェス！とうといイェス！<br/>',NULL,52245,8);
INSERT INTO stanza VALUES('J675','1','えいこうのおとずれ, 何とあまい:<br/>きのう,きょうも,とわに 主は変わらず。<br/>主はつみびとをあいし, すくわれる,<br/>えいこうが主の名に あるように！<br/>',NULL,52246,1);
INSERT INTO stanza VALUES('J675','chorus','きのうも,きょうもとわに 主は変わらず！<br/>すべてうつり変わるも 主,変わらず！<br/>主,変わらず, 主,変わーらず;<br/>すべては変わるとも, 主,変わらず！<br/>',NULL,52247,2);
INSERT INTO stanza VALUES('J675','2','主はつみびとのとも, なれさがす；<br/>つみをこくはくして, すくわーれよ；<br/>「ながつみ，ゆるされた」と 主はかたる,<br/>このめぐみのこえを いまぞ聞け！<br/>',NULL,52248,3);
INSERT INTO stanza VALUES('J675','3','かつて病めるものに 御手を置き,<br/>やまいをことごとく いやさーれた。<br/>いまもしんじるものを いやされる;<br/>しんこうにより,主の ことば取る！<br/>',NULL,52249,4);
INSERT INTO stanza VALUES('J675','4','主はエマオへのみち あゆまれた;<br/>ともにわがしょうがい あゆまーれる。<br/>間もなくさいらいする 主に出会う！<br/>まみえる主はなおも おなじイェス。<br/>',NULL,52250,5);
INSERT INTO stanza VALUES('J676','1','わたしは聞いた: イェスはすくう！<br/>全地に知らせよう: イェスはすくう！<br/>労苦をいとわず, すべてのひとに,<br/>主を知らせよう: イェスはすくう！<br/>',NULL,52251,1);
INSERT INTO stanza VALUES('J676','2','ひん富の差なく, イェスはすくう！<br/>つみびとに告ぐ: イェスはすくう！<br/>しまはさけんで, うみは呼応する,<br/>地は告げ知らす: イェスはすくう！<br/>',NULL,52252,2);
INSERT INTO stanza VALUES('J676','3','十字架は告げる: イェスはすくう！<br/>とうとい血,かたる: イェスはすくう！<br/>主は死んで,「ゆるし」, 復かつし,「生かす」,<br/>昇天し,「たかめる」, イェスはすくう！<br/>',NULL,52253,3);
INSERT INTO stanza VALUES('J676','4','まことのふく音: イェスはすくう！<br/>ひとのなぐさめ: イェスはすくう！<br/>ひとによろこび, やすらぎあとう,<br/>つみびとよ,聞け: イェスはすくう！<br/>',NULL,52254,4);
INSERT INTO stanza VALUES('J676','5','ふく音つたえよう: イェスはすくう！<br/>世のひとよ,知れ: イェスはすくう！<br/>かみはゆたかな めぐみをたまう;<br/>われらはさけぶ: イェスはすくう！<br/>',NULL,52255,5);
INSERT INTO stanza VALUES('J677','1','慈あいに満ち,温和な主は, われらのため十字架負う;<br/>いのちを捨て,血をながす, この主イェスを信じ,受けよ。<br/>',NULL,52256,1);
INSERT INTO stanza VALUES('J678','1','主をのぞいて,主のほかには,<br/>すくいはない,すくいはなし,<br/>てんのしたには,この名のほかに,<br/>すくい得さすほかの名なし。<br/>',NULL,52257,1);
INSERT INTO stanza VALUES('J679','1','どんな努りょくも, 善きおこないも,<br/>あくのせいしつ, かい善できない！<br/>すくい得ない！<br/>',NULL,52258,1);
INSERT INTO stanza VALUES('J679','chorus','イェスはわがため, つみをあがない,<br/>めぐみをあたえ, われをすくう！<br/>',NULL,52259,2);
INSERT INTO stanza VALUES('J679','2','どんななげきも, ながすなみだも,<br/>つみあらわれず, へい安得られず！<br/>すくい得ない！<br/>',NULL,52260,3);
INSERT INTO stanza VALUES('J679','3','「そのうちに」と, どんなに待っても,<br/>へい安ないまま 死ぬほかはない！<br/>すくわれない！<br/>',NULL,52261,4);
INSERT INTO stanza VALUES('J679','4','イェスを信じる, これこそすくい！<br/>イェスがながした 血はつみあらい,<br/>われをすくう！<br/>',NULL,52262,5);
INSERT INTO stanza VALUES('J680','1','不思議なあい！主のあいよ！ 主は御座をはなれて,<br/>わたしのため,苦なん受け, カルバリへ行かれた！<br/>主はカルバリへ行かれた, わがため,わがため,<br/>主はカルバリへ行かれた, すくいのため！<br/>',NULL,52263,1);
INSERT INTO stanza VALUES('J680','2','主は木にくぎづけられた！ いばらのかんむり受け,<br/>むち打たれて,きず受けた, わたしを愛するゆえ！<br/>主は十字架でくるしんだ, わたしをあいして;<br/>主は十字架でくるしんだ, 解放するため！<br/>',NULL,52264,2);
INSERT INTO stanza VALUES('J680','3','かみは来て,かれをさばく！ わたしの身代わりに！<br/>かみの義ゆえ,かれころし, かれはばつを受けた！<br/>主はじゅう字架で死なれた, わたしに代わって;<br/>主はじゅう字架で死なれた, つみのために！<br/>',NULL,52265,3);
INSERT INTO stanza VALUES('J680','4','カルバリの十字架を見て, いま主のみこえ聞く！<br/>「あなたのため血をながし, あがないを成就した！」<br/>主は十字架で血ながした, わたしをすくった;<br/>主は十字架で血ながした, もうほろびない！<br/>',NULL,52266,4);
INSERT INTO stanza VALUES('J681','1','すくいぬしイェスは, じゅう字架にて,<br/>くるしみ,いばらの かんむり受ける。<br/>',NULL,52267,1);
INSERT INTO stanza VALUES('J681','chorus','十字架じょうに主のめぐみを見, つみのおも荷は去る！<br/>しん仰によりへい安を得て, いつも,いつもよろこぶ！<br/>',NULL,52268,2);
INSERT INTO stanza VALUES('J681','2','わたしに代わって 主は苦難受く;<br/>なんたるあわれみ, あいとめぐみ！<br/>',NULL,52269,3);
INSERT INTO stanza VALUES('J681','3','主はひとのつみを になったとき,<br/>照る日もかくれて, 全地はやみに。<br/>',NULL,52270,4);
INSERT INTO stanza VALUES('J681','4','かみとひと分ける, まく裂かれた;<br/>死とよみのちから, 征ふくされた。<br/>',NULL,52271,5);
INSERT INTO stanza VALUES('J681','5','主のわきばらより, 血とみず出て,<br/>わがつみをきよめ, いのち得さす。<br/>',NULL,52272,6);
INSERT INTO stanza VALUES('J681','6','すくいのみわざは, かんりょうした;<br/>かなしみは消され, 賛美と変わる！<br/>',NULL,52273,7);
INSERT INTO stanza VALUES('J682','1','わたしはよわく, ちからはない,<br/>しんじることで, ざい過のがれる。<br/>',NULL,52274,1);
INSERT INTO stanza VALUES('J682','chorus','　負さいみな, 主ははらう;<br/>すべてのつみを, 主,ゆるされる。<br/>',NULL,52275,2);
INSERT INTO stanza VALUES('J682','2','いまや見ました, 主のちからを;<br/>けがれをあらい, よわさ,つよめる。<br/>',NULL,52276,3);
INSERT INTO stanza VALUES('J682','3','ぜん行はないが, 主,すくわれる;<br/>あわれみの主は, つみびとあいす。<br/>',NULL,52277,4);
INSERT INTO stanza VALUES('J682','4','この世はなれる ちからないが;<br/>つみのつぐない, 主は成したもう。<br/>',NULL,52278,5);
INSERT INTO stanza VALUES('J682','5','かみはわたしを, もう,問われない;<br/>主が血をながし, さばかれたゆえ。<br/>',NULL,52279,6);
INSERT INTO stanza VALUES('J683','1','イェスはわれを愛し, にく身を取りたもう。<br/>いのちをあたえんと, 十字架につけらる。<br/>イェス来たーりて, イェス死にーたもう,<br/>わがため,わがため, イェス死にーたもう。<br/>',NULL,52280,1);
INSERT INTO stanza VALUES('J684','1','つみをあらうは, とうといイェスの血！<br/>かん全にするは, とうといイェスの血！<br/>',NULL,52281,1);
INSERT INTO stanza VALUES('J684','chorus','完全な効き目！ ゆきよりしろく,<br/>血はきよめる; とうといイェスの血！<br/>',NULL,52282,2);
INSERT INTO stanza VALUES('J684','2','つみ,きよめるは, とうといイェスの血！<br/>つみをゆるすは, とうといイェスの血！<br/>',NULL,52283,3);
INSERT INTO stanza VALUES('J684','3','つみ,あがなうは, とうといイェスの血！<br/>めぐみ受くのは, とうといイェスの血！<br/>',NULL,52284,4);
INSERT INTO stanza VALUES('J684','4','わがせいと義は, とうといイェスの血！<br/>のぞみ,安そくは, とうといイェスの血！<br/>',NULL,52285,5);
INSERT INTO stanza VALUES('J685','1','イェス,かみの小ひつじ, つみびとのため死ぬ;<br/>イェスの血がそそがれ, かみは過ぎ越される。<br/>',NULL,52286,1);
INSERT INTO stanza VALUES('J685','chorus','小ひつじの血, かみは見らる,<br/>この血を見て, かみはゆるしたもう。<br/>',NULL,52287,2);
INSERT INTO stanza VALUES('J685','2','つみびとのかしらも, 主イェスはすくいたもう;<br/>血のいずみのなかで, いますぐにあらえや。<br/>',NULL,52288,3);
INSERT INTO stanza VALUES('J685','3','さばきの日来るとき, だれまぬかれ得るか？<br/>つみをきよめ,すくう 血のなかにかくれよ。<br/>',NULL,52289,4);
INSERT INTO stanza VALUES('J685','4','主のかぎりなきあい！ めぐみ,ゆたか,あまさ！<br/>血のもとで平安を得, かみのゆるし受けた！<br/>',NULL,52290,5);
INSERT INTO stanza VALUES('J685','chorus','不思議な血よ, 　 小ひつじの血,<br/>この血を見て, かみは過ぎ越された。<br/>',NULL,52291,6);
INSERT INTO stanza VALUES('J686','1','主ーイェスのわきより, わき出る血のいずみ,<br/>ひとたび身ひたせば, つみは消え去る。<br/>すぐにわがすべての つみは消え去ーる,<br/>ひとたび身,ひたせば, つみは消え去る。<br/>',NULL,52292,1);
INSERT INTO stanza VALUES('J686','2','かのぬすびとさえも, いずみの効き目見た,<br/>主はどんなつみでも, ぬぐい去られる。<br/>血のいずみのなかで ぬぐい去られーる,<br/>主はどんなつみでも, ぬぐい去られる。<br/>',NULL,52293,2);
INSERT INTO stanza VALUES('J686','3','小ひつじ,ほふられた そのとうとき血しおは,<br/>ちからがあり,とわに つみ,とおざける。<br/>かみのたみをすべて, あらいきよめーる,<br/>ちからがあり,とわに つみ,とおざける。<br/>',NULL,52294,3);
INSERT INTO stanza VALUES('J686','4','主のからだ裂かれて, いずみはひらかれた,<br/>あがないのあいゆえ, 主をさん美する。<br/>われ死にいたるまで, 主をほめたたえる,<br/>あがないのあいゆえ, 主をさん美する。<br/>',NULL,52295,4);
INSERT INTO stanza VALUES('J686','5','世を去り,はかに入り, さん美できなくとも,<br/>ふっかつのそのあさ, たい能,たたえる。<br/>あがないのたいのう, われ,ほめたたえる,<br/>ふっかつのそのあさ, たい能,たたえる。<br/>',NULL,52296,5);
INSERT INTO stanza VALUES('J687','1','良しんのおも荷を解く, そのちから,血にある;<br/>義のさばきまぬかれる, 奇しき血のちから。<br/>',NULL,52297,1);
INSERT INTO stanza VALUES('J687','chorus','不思議なちからある, 小ひつじの血！<br/>不思議なちからある, 小ひつじの血しお！<br/>',NULL,52298,2);
INSERT INTO stanza VALUES('J687','2','つみの誘わくより解く, そのちから,血にある;<br/>情よくのけがれのぞく, 奇しき血のちから。<br/>',NULL,52299,3);
INSERT INTO stanza VALUES('J687','3','ゆきよりもしろくする, そのちから,血にある;<br/>主のようにせいとする, 奇しき血のちから。<br/>',NULL,52300,4);
INSERT INTO stanza VALUES('J687','4','完ぜんなすくい得さす, そのちから,血にある;<br/>永遠のしゅくふく得さす, 奇しき血のちから。<br/>',NULL,52301,5);
INSERT INTO stanza VALUES('J687','5','つみを完ぜんにころす, そのちから,血にある;<br/>われのつみを取り去る, 奇しき血のちから。<br/>',NULL,52302,6);
INSERT INTO stanza VALUES('J688','1','小ひつじの血のあらいを, すでに受けましたか？<br/>こころに主イェスをしんじ, めぐみ,受けましたか？<br/>',NULL,52303,1);
INSERT INTO stanza VALUES('J688','chorus','小ひつじの血, あなたをあらいます,<br/>あなたのころも,ゆきより なおしろくされます。<br/>',NULL,52304,2);
INSERT INTO stanza VALUES('J688','2','つみゆるす主のめぐみを, すでに受けましたか？<br/>あなたのため死んだ主は, へいあんあたえます。<br/>',NULL,52305,3);
INSERT INTO stanza VALUES('J688','3','間もなく来るはなむこの, かがやくりんざいに,<br/>ゆきよりしろいころもの, よう意できましたか？<br/>',NULL,52306,4);
INSERT INTO stanza VALUES('J688','4','つみのけがれをきよめる, 主の血を受けましょう,<br/>たましいのけがれのぞく, 血のあらい受けましょう。<br/>',NULL,52307,5);
INSERT INTO stanza VALUES('J689','1','不思議なあーい,主はくだって,<br/>わがため十字架でくるしむ;<br/>不思議なあーい,主は裂かれて,<br/>血をながし,負さいはらった。<br/>',NULL,52308,1);
INSERT INTO stanza VALUES('J690','1','何と不思議なあい,ふかく,ひろい;<br/>御子,来て,わがため,さばかれ,死ぬ。<br/>あいとめぐみの門,いまひらいている;<br/>かみはせつに待つ,なれの来るを。<br/>',NULL,52309,1);
INSERT INTO stanza VALUES('J691','1','うるわしきは 主のみめぐみ,<br/>あめつちに満ちて, ひびきわたる。<br/>',NULL,52310,1);
INSERT INTO stanza VALUES('J691','chorus','　すくわるは, めぐみなり！<br/>つみびとのため, 主は死なれた。<br/>',NULL,52311,2);
INSERT INTO stanza VALUES('J691','2','キリストこそ, めぐみに富む;<br/>わたしをあがない, つみより解く。<br/>',NULL,52312,3);
INSERT INTO stanza VALUES('J691','3','つみあがない, ゆるすめぐみ;<br/>かみにまみえ,天の 平あん得さす。<br/>',NULL,52313,4);
INSERT INTO stanza VALUES('J691','4','主のめぐみは, いのちあたえ,<br/>よみからすくいて, 御名に帰さす。<br/>',NULL,52314,5);
INSERT INTO stanza VALUES('J692','1','主のわざを見たニコデモ, よる来て,ひとのみち問う;<br/>主はよくよくかたられた: 「再せいされよ！」<br/>',NULL,52315,1);
INSERT INTO stanza VALUES('J692','chorus','「さいせいされよ！ さいせいされよ！」<br/>主はよくよくかたられた: 「再せいされよ！」<br/>',NULL,52316,2);
INSERT INTO stanza VALUES('J692','2','世びとよ,このことば聞け, 主は厳しゅくにかたられた;<br/>神せいなメｯセージは言う: 「再せいされよ！」<br/>',NULL,52317,3);
INSERT INTO stanza VALUES('J692','3','てんのみやこにはいって, へいあんきょう受するには,<br/>えいえんのいのちひつ要: 「再せいされよ！」<br/>',NULL,52318,4);
INSERT INTO stanza VALUES('J692','4','主はしんじるもの生かし, 霊は従順なもの聖とする;<br/>悔いあらため,しんじれば, 再せいされる！<br/>',NULL,52319,5);
INSERT INTO stanza VALUES('J692','chorus','さいせいされる！ さいせいされる！<br/>悔いあらため,しんじれば, 再せいされる！<br/>',NULL,52320,6);
INSERT INTO stanza VALUES('J693','1','キリストはひとのせいしつを着て,<br/>ひとと成り,じゅう字架につけられた;<br/>ふっかつし,れいと成り,わがうちで<br/>いのちとなる。<br/>えいこう！ハレルヤ！えいこう！ハレルヤ！<br/>ハレルヤ！キリスト,われのいのち！<br/>',NULL,52321,1);
INSERT INTO stanza VALUES('J694','1','主はいのち,復かつ, いのちのおう；<br/>死によりあく魔を, すでにほろぼして,<br/>主はいま生きる, えーい遠に生きる,<br/>えーい遠に,えい遠に生きる。<br/>',NULL,52322,1);
INSERT INTO stanza VALUES('J694','2','栄こうのいのちを, わたしは得た！<br/>あんこくはほろび, 死とつみのちから,<br/>すでに消え去る, すでに消え去ーる,<br/>すーでに,すでーに消え去る。<br/>',NULL,52323,2);
INSERT INTO stanza VALUES('J695','1','主はわがために死んで, つみさだめより解かる;<br/>信じるものはかならず, いのちを持つ！<br/>',NULL,52324,1);
INSERT INTO stanza VALUES('J695','chorus','しんのふく音, 聞きなさい！<br/>しんのふく音, 主はかたる:<br/>「御子をしんじるものは, いのちを持つ」。<br/>',NULL,52325,2);
INSERT INTO stanza VALUES('J695','2','主はわがつみをにない, 負さいをすべてはらう;<br/>かれをしんじるものは, いのちを持つ！<br/>',NULL,52326,3);
INSERT INTO stanza VALUES('J695','3','かつてはつみに満ちて, よわさのなかにあった;<br/>いまは主の名を信じて, いのちを持つ！<br/>',NULL,52327,4);
INSERT INTO stanza VALUES('J695','4','うたがいはもはやなし, 主はとわに見捨てない;<br/>よきおとずれを聞いて, いのちを持つ！<br/>',NULL,52328,5);
INSERT INTO stanza VALUES('J696','1','聞け！かくされてきたおく義を受け入れよ！<br/>このおく義,受けるなら,主といちとなる！<br/>栄光,栄こう,ハレルヤ！栄光,栄こう,ハレルヤ！<br/>このおく義,受けるなら,主といちとなる！<br/>',NULL,52329,1);
INSERT INTO stanza VALUES('J697','1','うれしきおとずれ！かみがひとに住む！<br/>いやしきものをもみこころにとめて。<br/>かみがひととともに住みたもう！<br/>えいえんにひとつ,かみをきょう受する。<br/>かみがひとととわにともに住む。<br/>',NULL,52330,1);
INSERT INTO stanza VALUES('J698','1','主はいのちのみなもと, またわきいずるいずみ;<br/>このみずを飲むもの, とわにかわかず。<br/>ほんにかわかぬか？ そう,かわかぬよ！<br/>ほんにかわかぬか？ そうかわくことなし！<br/>このみずを飲むもの, とわにかわかず。<br/>',NULL,52331,1);
INSERT INTO stanza VALUES('J698','2','主はいのちのくらなり, われらのいのちのかて;<br/>このかてをしょくせば, とわに飢えない。<br/>ほんに飢えないか？ そう,飢えないよ！<br/>ほんに飢えないか？ そう,飢えることなし！<br/>このかてをしょくせば, とわに飢えない。<br/>',NULL,52332,2);
INSERT INTO stanza VALUES('J698','3','主はよみがえりのおう, われらのいのちのきみ;<br/>主を信じるものみな, とわに死なない。<br/>ほんに死なないか？ そう,死なないよ！<br/>ほんに死なないか？ そう,死ぬことはなし！<br/>主を信じるものみな, とわに死なない。<br/>',NULL,52333,3);
INSERT INTO stanza VALUES('J699','1','つみが緋のように あかくあっても,<br/>それはゆきのように しろくなるのだ。<br/>ひつじの毛のように しろくなる。<br/>つみが緋のように, つみが緋のように,<br/>あかくあっても, しろくなるのだ。<br/>',NULL,52334,1);
INSERT INTO stanza VALUES('J699','2','かみのみこえ聞き, いま主にかえれ！<br/>かみのみこえ聞き, いま主にかえれ！<br/>あいの主,待ちたもう, いまかえれ！<br/>かみのみこえ聞け, かみのみこえ聞け,<br/>いま主にかえれ！ いま主にかえれ！<br/>',NULL,52335,2);
INSERT INTO stanza VALUES('J699','3','つみはゆるされて, おぼえられない。<br/>つみはゆるされて, おぼえられない。<br/>あなたのつみはみな, 消し去られ,<br/>つみはゆるされた, つみはゆるされた,<br/>えい遠にそれは, おぼえられない。<br/>',NULL,52336,3);
INSERT INTO stanza VALUES('J700','1','よろこびがありますか？ 生きがいがありますーか？<br/>過ぎてゆくものごとに, 安そく,なぐさめなし。<br/>全世かいを得たとしても, 主がなければ価値がない;<br/>キリストに満ちたじん生, これこそすばらしい！<br/>',NULL,52337,1);
INSERT INTO stanza VALUES('J700','2','とみとあいとめい声を, きわみまで得たとしても,<br/>とつ然あらし来るとき, やすみ場ありますか？<br/>全世かいを得たとしても, 主がなければ価値がない;<br/>とつぜんあらし来るとき, キリストこそちから！<br/>',NULL,52338,2);
INSERT INTO stanza VALUES('J700','3','キリストを得なければ, ただつみとかなしみだけ！<br/>キリストを得なければ, 何のかいけつもない！<br/>全世かいを得たとしても, 死のときはかならず来る;<br/>キリストを得なけれーば, くらやみがあるのみ。<br/>',NULL,52339,3);
INSERT INTO stanza VALUES('J700','4','主イェスにはかん喜あり, こころいやすあぶらあり,<br/>主はつみをゆるされた, よろこびわき上がる。<br/>イェスあれば,イェスがあれば, すべてのものはすばらしい！<br/>イェスあれば,イェスがあれば, 無げんのほう富得る。<br/>',NULL,52340,4);
INSERT INTO stanza VALUES('J701','1','いまの労えきすべて, なんのえきあるか？<br/>新鮮なものはなし！ 過去捨てよ！<br/>',NULL,52341,1);
INSERT INTO stanza VALUES('J701','chorus','むなし！むなし！ むなし！むなし！<br/>そはかぜを追ーうごとし。<br/>',NULL,52342,2);
INSERT INTO stanza VALUES('J701','2','かなしみといたみは, じんせいに満ちる！<br/>知恵,知しき増せば, なげき増す。<br/>',NULL,52343,3);
INSERT INTO stanza VALUES('J701','3','とみやたのしみなど, なんのえきあるか？<br/>よろこびとともに, なやみある。<br/>',NULL,52344,4);
INSERT INTO stanza VALUES('J701','4','にち夜,労苦あるのみ, もとむもの得るも,<br/>死の来たる日には, みな失せる。<br/>',NULL,52345,5);
INSERT INTO stanza VALUES('J701','5','わかき日におぼえよ, ながつくりぬしを！<br/>かれともにあれば, 満ち足りる！<br/>満たし得るは キリストのみ！<br/>キリストはわーが満たし！<br/>',NULL,52346,6);
INSERT INTO stanza VALUES('J702','1','苦つう,なやみ, おも荷負う;<br/>人せいは苦悩満ち, 平安はなし。<br/>',NULL,52347,1);
INSERT INTO stanza VALUES('J702','2','ただ主あれば, 苦のうなし;<br/>ためらわずにいま, 平安を得よ。<br/>',NULL,52348,2);
INSERT INTO stanza VALUES('J703','1','えい遠を,えいー遠を！ いかーに過ごしますか？<br/>この解けつなければ, しょうらい後かいします！<br/>すくいもほろびも永遠, どちらえらびますか？<br/>',NULL,52349,1);
INSERT INTO stanza VALUES('J703','2','えい遠を,えいー遠を！ いかーに過ごしますか？<br/>イェスをえらんだひと, すべてのつみをはなれ，<br/>すくわれ,さいせいされ, ちちがみにちかづく。<br/>',NULL,52350,2);
INSERT INTO stanza VALUES('J703','3','えい遠を，えいー遠を！ いかーに過ごしますか？<br/>すくい受けなければ， ほろびのみちをあゆむ，<br/>よくよくかんがえなさい, その終わりはほろび。<br/>',NULL,52351,3);
INSERT INTO stanza VALUES('J703','4','えい遠を，えいー遠を！ いかーに過ごしますか？<br/>天で御かおあおぐか, 地ごくでくるしむのか？<br/>なんとげんしゅくなこと, これは永遠のさだめ。<br/>',NULL,52352,4);
INSERT INTO stanza VALUES('J703','5','えい遠を，えいー遠を！ いかーに過ごしますか？<br/>主を信じ,ひかり追い, 死よりいのちにはいり,<br/>「かみのみくにに住む」と, すすんでこたえましょう。<br/>',NULL,52353,5);
INSERT INTO stanza VALUES('J704','1','ほろびをまぬかれさすは, イェスのみ！<br/>イェスは永遠の 苦痛のぞく！<br/>消えぬ火, わざわい,<br/>すくい得るかたは, 主イェス！<br/>',NULL,52354,1);
INSERT INTO stanza VALUES('J704','2','えい光のいのちのみちは, イェスのみ！<br/>永遠のしゅくふくは, 主イェス！<br/>死と苦痛, 悲哀なし！<br/>この豊富たもうは, 主イェス！<br/>',NULL,52355,2);
INSERT INTO stanza VALUES('J705','1','つみのどくで死ぬ, つみのしゅうじん;<br/>主イェスをしんじて, いのちを受けよ。<br/>ちからある御子は かいほうする;<br/>つみより解かれて, えい遠に自ゆう。<br/>',NULL,52356,1);
INSERT INTO stanza VALUES('J706','1','何とやさしき呼びごえよ, イェスの呼びごえ！<br/>てんでなれを待つイェスは, 地でさがしたもう！<br/>',NULL,52357,1);
INSERT INTO stanza VALUES('J706','chorus','　　いえにかえれ！ つかれ果てしもーの,<br/>いえにかえれ,つみびとよ, イェスは呼びたもう！<br/>',NULL,52358,2);
INSERT INTO stanza VALUES('J706','2','イェス,かさねてすすめるに, なぜためらうや？<br/>まねくこえにしたがって, めぐみを受けよ。<br/>',NULL,52359,3);
INSERT INTO stanza VALUES('J706','3','いま,このときを捕らえよ, 過ぎゆかぬ間に;<br/>のがせば死のかげは待つ, なれも,われをも。<br/>',NULL,52360,4);
INSERT INTO stanza VALUES('J706','4','ああ,くすしきイェスのあい, よわさ,けがれを,<br/>すでにイェスはゆるしたもう, なんたるあいよ。<br/>',NULL,52361,5);
INSERT INTO stanza VALUES('J707','1','いま主のみこえ聞く: 「われのもとに来たれ」;<br/>主は絶えず呼びたもう: 「われのもとに来たれ;<br/>なれのためにわれは, 苦なんのみちをたどり,<br/>ながおも荷をになう, われのもとに来たれ。<br/>',NULL,52362,1);
INSERT INTO stanza VALUES('J707','2','なれのつみをゆるす, われのもとに来たれ;<br/>なれに自ゆう得さす, われのもとに来たれ;<br/>うつり変わる世にて, われはなれをみちびき,<br/>よろこびたのします, われのもとに来たれ。<br/>',NULL,52363,2);
INSERT INTO stanza VALUES('J707','3','心ぱいごとを持って, われのもとに来たれ;<br/>おも荷負ったままで, われのもとに来たれ;<br/>ながうたがい,おそれ, すべて,われにゆだねよ;<br/>われにあんそくあり, われのもとに来たれ」。<br/>',NULL,52364,3);
INSERT INTO stanza VALUES('J708','1','イェスやさしく呼びたもう, いますぐかえれ！と。<br/>とおく愛の主をはなれ, なぜさまようや？<br/>',NULL,52365,1);
INSERT INTO stanza VALUES('J708','chorus','主やさしく, きょう呼びたもう！<br/>主,呼びたもう, ゆえ,いますぐかえれや。<br/>',NULL,52366,2);
INSERT INTO stanza VALUES('J708','2','おも荷負うもの来たれと, きょうこの日,呼びたもう！<br/>ながおも荷を下ろせや, 主のもとに来て。<br/>',NULL,52367,3);
INSERT INTO stanza VALUES('J708','3','イェス,つみをゆるすため, きょうこの日,待ちたもう！<br/>とく主のもとに来たれ, つみのあるまま。<br/>',NULL,52368,4);
INSERT INTO stanza VALUES('J708','4','イェス,いまなお呼びたもう, 主のこえ,いま聞け！<br/>主よ,と呼べばかならず, なれはすくわる。<br/>',NULL,52369,5);
INSERT INTO stanza VALUES('J709','1','つみびとに良きおとずれ, はやく告げ知らせましょう:<br/>「だれでもみなすくわれる, みんな来なさい！」<br/>',NULL,52370,1);
INSERT INTO stanza VALUES('J709','chorus','どんなひとも,どんなひとも, あいのちちは呼びかける;<br/>「だれでもみな,かえりなさい！ なにも持たずに」。<br/>',NULL,52371,2);
INSERT INTO stanza VALUES('J709','2','めぐみの門はひらかれた, イェスまことのすくいぬし;<br/>主はあなたにかたられる: みんな来なさい！<br/>',NULL,52372,3);
INSERT INTO stanza VALUES('J709','3','みなえい遠のいのち持て！ ことばにしるしともなう;<br/>このやくそく変わりなし, みんな来なさい！<br/>',NULL,52373,4);
INSERT INTO stanza VALUES('J710','1','こころをたたく！ だれかがたたく！<br/>あなたのこころの もんが開くまで;<br/>すばらしいおきゃくが, 気だかいかたが。<br/>',NULL,52374,1);
INSERT INTO stanza VALUES('J710','2','こころをたたく！ にんたいづよく！<br/>つるくさ,からまり, かな具はさびて,<br/>おもく閉ざされた もんが開くまで。<br/>',NULL,52375,2);
INSERT INTO stanza VALUES('J710','3','こころをたたく！ にんたいづよく！<br/>くぎあとある手が たゆまずたたく,<br/>あなたをもとめる 主のつよいあい。<br/>',NULL,52376,3);
INSERT INTO stanza VALUES('J711','1','聞け！主がこころを たたくおと;<br/>なぜ,なれこころを, かたくする？<br/>とく門をひらき, 主を入れよー;<br/>いのちあたえ,つみ, ゆるす主を。<br/>',NULL,52377,1);
INSERT INTO stanza VALUES('J711','chorus','主をば入れよ, なれのこころに;<br/>主をばこころに, 受け入れよ。<br/>',NULL,52378,2);
INSERT INTO stanza VALUES('J711','2','「つみびと,つみびと, 安そく得よ;<br/>われはながために, 天を捨てた;<br/>めぐみあとうため, 血,ながしたー;<br/>つみが緋のようでも, しろくなる」。<br/>',NULL,52379,3);
INSERT INTO stanza VALUES('J711','3','主はめぐみふかく, 慈あい満つ;<br/>なぜ,なれためらい, 主を待たす？<br/>主をなげかせず, みこえ聞けー;<br/>めぐみをあたえる 主を入れよ。<br/>',NULL,52380,4);
INSERT INTO stanza VALUES('J711','4','おくらせていると, かの日来る,<br/>おくらせていると, 後かいするー;<br/>門を閉じるなら, みちはなし！<br/>なぜ,きょう主イェスを 受け入れぬ？<br/>',NULL,52381,5);
INSERT INTO stanza VALUES('J712','1','まよい出た一ぴき, イェスはさがす;<br/>九十九ひきのこし, たずねさがす。<br/>まよえるひつじよ, ほろびのみちまぬかれ,<br/>はやく主イェスにかえれ！<br/>',NULL,52382,1);
INSERT INTO stanza VALUES('J713','1','まよっているひつじを, 主イェスたずねさがす！<br/>まよったいっぴきよ, いまどこに？<br/>まよい出たのは，あなたでないか？<br/>ひつじ百ぴきのうち， まようもの。<br/>',NULL,52383,1);
INSERT INTO stanza VALUES('J713','2','うしなわれたものを, 聖れいたずねさがす！<br/>うしなったいちまい, いまどこに？<br/>そのいちまいは, あなたでないか？<br/>ぎん貨十まいのうち, 失せしもの。<br/>',NULL,52384,2);
INSERT INTO stanza VALUES('J713','3','放とうしたむすこを, ちち,待ちわびている！<br/>遠くはなれたものよ, いまどこに？<br/>放とうむすこは, あなたでないか？<br/>ちちはいえでいまも, 待っている。<br/>',NULL,52385,3);
INSERT INTO stanza VALUES('J714','1','いま主イェスは, ここにいる;<br/>死のみち行かず, 主のもとへ;<br/>この機かいを のがさないで,<br/>ためらわず,いま, 主に行こう。<br/>',NULL,52386,1);
INSERT INTO stanza VALUES('J714','2','いま主イェスは, ここにいる;<br/>この世したわず, 主のもとへ;<br/>めぐみを得て, ほろびのがれ,<br/>まようことなく, 主に行こう。<br/>',NULL,52387,2);
INSERT INTO stanza VALUES('J714','3','いま主イェスは, ここにいる;<br/>うたがいを捨て, 主のもとへ;<br/>おそれないで, つみあるまま,<br/>なれをあいする 主に行こう。<br/>',NULL,52388,3);
INSERT INTO stanza VALUES('J714','4','いま主イェスは, ここにいる;<br/>みちをそれずに, 主のもとへ;<br/>あがない成し, いま,主は呼ぶ;<br/>すくいぬしなる 主に行こう。<br/>',NULL,52389,4);
INSERT INTO stanza VALUES('J715','1','なれ堕らくし,つみに生き, くるしみもはやじゅう分;<br/>悔いあらため,立ち上がれ, そのくるしみより出よ！<br/>',NULL,52390,1);
INSERT INTO stanza VALUES('J715','chorus','主は待ちたもう！主,待ちたもう！ いますくいを受けよう！<br/>',NULL,52391,2);
INSERT INTO stanza VALUES('J715','2','なれ,あく魔の手に落ちて, わざわいをこうむった;<br/>そのそくばく,支はいより, のがれるほう法はない！<br/>',NULL,52392,3);
INSERT INTO stanza VALUES('J715','3','このじんせい,つゆのように, さいげつは消えてゆく;<br/>死んだのちに,さばきある！ 永えんの火をのがれよ！<br/>',NULL,52393,4);
INSERT INTO stanza VALUES('J715','4','主は死を経て,よみがえり, 昇てんし,おうとなった;<br/>死をはい棄し,解ほうして, いのちをあらわされる。<br/>',NULL,52394,5);
INSERT INTO stanza VALUES('J715','5','主はいまなお,耐えしのび, なれ,受け入れるを待つ;<br/>悔いあらため,主をしんじ, すくい得よ,と主は待つ。<br/>',NULL,52395,6);
INSERT INTO stanza VALUES('J716','1','イェスはいま待っている, あなたを待っている;<br/>悔いあらため,えいえんの いのち享受せよ。<br/>',NULL,52396,1);
INSERT INTO stanza VALUES('J716','chorus','「どんなひとも来なさい」と, 主イェスはまねく;<br/>ただ信じればすくわれる, いますくわれる。<br/>',NULL,52397,2);
INSERT INTO stanza VALUES('J716','2','世をあいし,ほう浪して, つかれているもの,<br/>イェスはなお待っている, あいのこころで。<br/>',NULL,52398,3);
INSERT INTO stanza VALUES('J716','3','主の召しを拒ぜつして, かえりみをこばむ,<br/>しかし主は慈あいもて, うながしている。<br/>',NULL,52399,4);
INSERT INTO stanza VALUES('J716','4','このあいに降ふくせよ, イェスは待っている;<br/>「したがって来なさい！」と, 主はなおまねく。<br/>',NULL,52400,5);
INSERT INTO stanza VALUES('J717','note','第　一　首<br/>',NULL,52401,1);
INSERT INTO stanza VALUES('J717','1','つみびと,主に来て, あわれみ得よ,<br/>みことばを信じて, 安そくを得よ。<br/>',NULL,52402,2);
INSERT INTO stanza VALUES('J717','chorus','主を信じよ！主,信じよ！ 主を信じよ！<br/>主はすくう！主,すくう！ いま,すくう！<br/>',NULL,52403,3);
INSERT INTO stanza VALUES('J717','2','イェス,血をながして, めぐみあとう;<br/>血のいずみに入り, しろくされよ。<br/>',NULL,52404,4);
INSERT INTO stanza VALUES('J717','3','イェスはみち,しん理, 安そく,満ぞく;<br/>いますぐに信じて, しゅくふく得よ。<br/>',NULL,52405,5);
INSERT INTO stanza VALUES('J717','4','せいなるむれへと いそぎ来たれ;<br/>天のみやにはいり, 永遠に享受す。<br/>',NULL,52406,6);
INSERT INTO stanza VALUES('J717','note','第　二　首(復は第一首と同じ)<br/>',NULL,52407,7);
INSERT INTO stanza VALUES('J717','1','ひとよ,主に来たれ, 主は待っている;<br/>ただ主イェス信じて, 安そくを得よ。<br/>',NULL,52408,8);
INSERT INTO stanza VALUES('J717','2','イェスは十字架にて, あがない成す;<br/>無だい価のすくい, 信じて受けよ。<br/>',NULL,52409,9);
INSERT INTO stanza VALUES('J717','3','主は慈あいに満ち, めぐみあとう;<br/>この機かい捕らえ, いそぎ来たれ。<br/>',NULL,52410,10);
INSERT INTO stanza VALUES('J717','chorus','すぐ来たれ！すぐ来て, 主を信じよ！<br/>主はすくう！主,すくう！ いま,すくう！<br/>',NULL,52411,11);
INSERT INTO stanza VALUES('J717','4','すくいか,ほろびか？ ときちぢまる;<br/>永遠に生きるため, イェスを,信じよ。<br/>',NULL,52412,12);
INSERT INTO stanza VALUES('J718','1','主のことば,こばむな, ひかりに目を向け;<br/>主にこころひらき, すくわれよ！<br/>この日,受けよ, 主のすくい;<br/>ためらわず, すくわれよ。<br/>',NULL,52413,1);
INSERT INTO stanza VALUES('J718','2','あすのあさ,目覚めて, たいようを見ると,<br/>だれが言い得よう？ さとくあれ！<br/>この日,受けよ, 主のすくい;<br/>ためらわず, すくわれよ。<br/>',NULL,52414,2);
INSERT INTO stanza VALUES('J718','3','世の魅りょくあるもの, それはみなむなしい;<br/>主のめぐみ受けよ！ きょう,この日！<br/>この日,受けよ, 主のめぐみ;<br/>ためらわず, すくわれよ。<br/>',NULL,52415,3);
INSERT INTO stanza VALUES('J718','4','主に来るものたちを, 主はこばまれない;<br/>主,ただちにすくう！ 主を信じよ！<br/>いまぞ,受けよ, このときに,<br/>ためらわず, すくわれよ。<br/>',NULL,52416,4);
INSERT INTO stanza VALUES('J719','1','つみのおも荷背負って, つかーれているなら,<br/>あたらしいじんせいを はじーめたいなら,<br/>',NULL,52417,1);
INSERT INTO stanza VALUES('J719','chorus','いま,うたがわず, もはやまよわず,<br/>こころをひらき, イェスを受け入れよ。<br/>',NULL,52418,2);
INSERT INTO stanza VALUES('J719','2','自己のけがれと無のう, 不まんとむなしさを,<br/>こころにかんじるなら, イェスを受け入れよ。<br/>',NULL,52419,3);
INSERT INTO stanza VALUES('J719','3','やまいをけんこうへと, くらきをひかりへと,<br/>うつり変わりたいなら, イェスを受け入れよ。<br/>',NULL,52420,4);
INSERT INTO stanza VALUES('J719','4','まんぞくとたのしみと よろこびとへい安を,<br/>あなたも得たいのなら, イェスを受け入れよ。<br/>',NULL,52421,5);
INSERT INTO stanza VALUES('J720','1','イェスを見上げよ！ 見上げ,生きよ！<br/>主はすくい成す, 生きよ！<br/>十字架で成就す, 見上げ,生きよ！<br/>主のみこえ聞き, 生きよ！<br/>',NULL,52422,1);
INSERT INTO stanza VALUES('J720','chorus','主は木に掛かり, 死のきずいやす;<br/>主イェスを,見上げて, 生きよ！<br/>',NULL,52423,2);
INSERT INTO stanza VALUES('J720','2','けがれていても, 見上げ,生きよ！<br/>つみをはなれて, 生きよ！<br/>サタンより解かれ, 見上げ,生きよ！<br/>かいほうされて, 生きよ！<br/>',NULL,52424,3);
INSERT INTO stanza VALUES('J720','3','まよっていても, 見上げ,生きよ！<br/>こころ,主に向け, 生きよ！<br/>ちちは呼びたもう, 見上げ,生きよ！<br/>主を待たせずに, 生きよ！<br/>',NULL,52425,4);
INSERT INTO stanza VALUES('J721','1','いそがしくて不安な つみびとよ,来なさい！<br/>愛とちからに満ちた イェス,ひとをすくう;<br/>主はすくう！主,すくう！ 主イェス受け入れよ。<br/>',NULL,52426,1);
INSERT INTO stanza VALUES('J721','2','どんなひとも来なさい, かみは歓迎される;<br/>悔いあらため,信じて, 主のめぐみ受けよ;<br/>無だい価で！無代価で！ 来て,買いもとめよ。<br/>',NULL,52427,2);
INSERT INTO stanza VALUES('J721','3','良しんのとがめ去り, まよわず来なさい;<br/>あなたのひつようは, ただ主イェスのあい;<br/>条けんなし！条件なし！ 主はあたえられる。<br/>',NULL,52428,3);
INSERT INTO stanza VALUES('J721','4','堕らくし,おも荷負い, つかれたあなたは,<br/>良くなるまで待たず, いますぐ来なさい;<br/>十字架上で,十字架で, あがない成就した。<br/>',NULL,52429,4);
INSERT INTO stanza VALUES('J721','5','ゲｯセマネのそのにて, すくいぬし,いのる！<br/>十字架上で言われた みこえ聞きなさい:<br/>「完りょうした！完了した！」 もうそれで十分です。<br/>',NULL,52430,5);
INSERT INTO stanza VALUES('J721','6','イェスは血をながして, かみの義,満たした;<br/>信じて,したがうなら, ばつはまぬかれる;<br/>ただ主だけ,イェスだけ, わたしたちのとも。<br/>',NULL,52431,6);
INSERT INTO stanza VALUES('J722','1','浮きぐものごと, あらわれて散る,<br/>じんせいはしばーしのみ！<br/>ときはちぢまり, 死の日はせまるー！<br/>よみからまぬかーれよや！<br/>',NULL,52432,1);
INSERT INTO stanza VALUES('J722','chorus','ときはいまぞ！ すくいのときはーいまぞ！<br/>このとき捕らえ, すくいを受けよー！<br/>すくいのときはーいまぞ！<br/>',NULL,52433,2);
INSERT INTO stanza VALUES('J722','2','あしたにひらく 可れんなはなも,<br/>ゆうべとともにーしぼむ。<br/>わかき日だれも, 取りもどし得ずー！<br/>かしこきものはーさとれ！<br/>',NULL,52434,3);
INSERT INTO stanza VALUES('J722','3','いま押しせまる 霊にさからわず,<br/>したがい,やすきー得よや。<br/>ためらわず来て, すくいを受けよー！<br/>主はめぐみもてー待てり！<br/>',NULL,52435,4);
INSERT INTO stanza VALUES('J722','4','つみびとよ,聞け, せつなるすすめ,<br/>なおざりにせずー,来たれ。<br/>さがしつづける 主に身をゆだねー,<br/>すくわるためにー来たれ。<br/>',NULL,52436,5);
INSERT INTO stanza VALUES('J723','1','主はわがひつようなり, みかみがにく身を取り,<br/>おおくのくるしみ受け, 十字架にていのち,なれにあとう。<br/>',NULL,52437,1);
INSERT INTO stanza VALUES('J723','chorus','主を得よ！主を得よ！ 主キリスト得よ！<br/>つみからのがれ, やすらぎを得よ！<br/>ほろびをまぬかれ, 主を得よ！<br/>',NULL,52438,2);
INSERT INTO stanza VALUES('J723','2','主すでによみがえって, しょう天し,ちゅう保者なり,<br/>霊によりなれをさがす, 信じて御名よべば,めぐみ受く。<br/>',NULL,52439,3);
INSERT INTO stanza VALUES('J723','3','こころはやみおおえど, くまなくひかり照らし,<br/>ながつみおおくあれど, 主の血はすべてをゆるしたもう。<br/>',NULL,52440,4);
INSERT INTO stanza VALUES('J723','4','なが身は満たされ得ず, ひつよう,つねにおぼゆ;<br/>むなしさ取りのぞいて, 満たしたもうは主のほかになし。<br/>',NULL,52441,5);
INSERT INTO stanza VALUES('J723','chorus','主を得よ！主を得よ！ 主キリスト得よ！<br/>むなしさのがれ, まんぞくを得よ！<br/>有意義なじんせい！ 主を得よ！<br/>',NULL,52442,6);
INSERT INTO stanza VALUES('J723','5','この世はろう苦,なやみ, すべてはだましごとぞ;<br/>イェスこそひとのひつ要, たよりなることをしめされる。<br/>',NULL,52443,7);
INSERT INTO stanza VALUES('J723','6','すべてのひとはつみを おかして,えいこう欠く;<br/>信ずるはすくいのみち, 主はかみとひとの満ぞくなり。<br/>',NULL,52444,8);
INSERT INTO stanza VALUES('J724','1','こーんなわたしのために, 血をながし,死なれて,<br/>わたしを生かし,召された: 主よ,いまー行きます！<br/>',NULL,52445,1);
INSERT INTO stanza VALUES('J724','2','よわさのゆえに自ぶんを 変えられないけれど,<br/>主の血に依りたのみつつ, 主よ,いまー行きます！<br/>',NULL,52446,2);
INSERT INTO stanza VALUES('J724','3','なみのようにこころ揺れ, しんじても,うたがう,<br/>しんぱい,けがれあるまま, 主よ,いまー行きます！<br/>',NULL,52447,3);
INSERT INTO stanza VALUES('J724','4','もうもくで無知なわたし, 主のめぐみひつよう,<br/>目をあけ,見せてください, 主よ,いまー行きます！<br/>',NULL,52448,4);
INSERT INTO stanza VALUES('J724','5','主はわたしをめぐまれた, ゆるしといのち得た,<br/>主はやくそく果たされた; 主よ,いまー行きます！<br/>',NULL,52449,5);
INSERT INTO stanza VALUES('J725','1','かなしみとやみから, わたしは来ました！<br/>よろこびとひかりに, おお,主イェスよ！<br/>そくばくから解かれ, やまいをもいやされ,<br/>つみからあなたへと, 主よ,来ました！<br/>',NULL,52450,1);
INSERT INTO stanza VALUES('J725','2','この世のろう苦から, わたしは来ました！<br/>じゅう字架のすくいに, おお,主イェスよ！<br/>しつ望から希ぼうに, おそれからやすきに,<br/>なげきからさん美に, 主よ,来ました！<br/>',NULL,52451,2);
INSERT INTO stanza VALUES('J725','3','たかぶり,不へいから わたしは来ました！<br/>まったきしゅくふくに, おお,主イェスよ！<br/>おのれからはなれて, あなたのあいに住み,<br/>つばさ張り真っすぐ, 主よ,来ました！<br/>',NULL,52452,3);
INSERT INTO stanza VALUES('J725','4','サタンの死のちから, はなれて,来ました！<br/>いのちのめぐみへと, おお,主イェスよ！<br/>この世から分かたれ, しょうかいのなかへと,<br/>えいこうの御かおを とわにあおぐ！<br/>',NULL,52453,4);
INSERT INTO stanza VALUES('J726','1','主のまねくこえ, いま,われ聞く;<br/>すでにながされし 血であらえや。<br/>',NULL,52454,1);
INSERT INTO stanza VALUES('J726','chorus','おお,主よ,いまわれは行く！<br/>血をもてあらい,きよめたまえ。<br/>',NULL,52455,2);
INSERT INTO stanza VALUES('J726','2','よわさとけがれ, 身に満ちるも,<br/>めぐみとたすけは, つみより解く。<br/>',NULL,52456,3);
INSERT INTO stanza VALUES('J726','3','つみをはなれて, 悔いあらため,<br/>すくいを受けよと, 主まねきたもう。<br/>',NULL,52457,4);
INSERT INTO stanza VALUES('J726','4','おのれによらず, 主にたよれと,<br/>かみはせい霊もて 照らしたもう。<br/>',NULL,52458,5);
INSERT INTO stanza VALUES('J726','5','わがれいにあり, 聖霊あかしす:<br/>すでに信じたわれ, いのちあり,と。<br/>',NULL,52459,6);
INSERT INTO stanza VALUES('J726','6','絶えなるめぐみ！ くすしきあい！<br/>主のあがないの血！ われをささぐ。<br/>',NULL,52460,7);
INSERT INTO stanza VALUES('J727','1','あわれなわたし, 十字架に来ます；<br/>すべてはむなしい, ただ主がすくい。<br/>',NULL,52461,1);
INSERT INTO stanza VALUES('J727','chorus','十字架のもとで, しんらいします，<br/>あがないぬしよ, いま，すくいませ。<br/>',NULL,52462,2);
INSERT INTO stanza VALUES('J727','2','主のみすくいを ながくもとめた;<br/>「つみ，のぞく」との 主のみこえ聞く。<br/>',NULL,52463,3);
INSERT INTO stanza VALUES('J727','3','血であらわれて, あがないを得た;<br/>あらたにされて, よろこび満ちる。<br/>',NULL,52464,4);
INSERT INTO stanza VALUES('J727','chorus','主よ,感謝します, すでにすくわれ,<br/>よろこびあふれ, 主のみちあゆむ。<br/>',NULL,52465,5);
INSERT INTO stanza VALUES('J727','4','とみもちからも, ともも時かんも,<br/>すべてをとわに 主にささげます。<br/>',NULL,52466,6);
INSERT INTO stanza VALUES('J728','1','主をはなれ,まようもの, なぜかえらん？<br/>つみに生き,くるしみ, なぜかえらん？<br/>',NULL,52467,1);
INSERT INTO stanza VALUES('J728','chorus','1<br/>かえれ,いえに！ まよわずに;<br/>愛のかみ待ちたもう, かえれや,と。<br/>',NULL,52468,2);
INSERT INTO stanza VALUES('J728','chorus','2-5<br/>かえらん,いえに！ まよわずに,<br/>愛のかみのいえに, いま,かえらん！<br/>',NULL,52469,3);
INSERT INTO stanza VALUES('J728','2','ながく主をはなれて, まよいしが,<br/>悪しきみちあとにし, 主にかえらん。<br/>',NULL,52470,4);
INSERT INTO stanza VALUES('J728','3','おおくのとしつきを, 浪費せしが,<br/>きょうこそ悔いあらため, 主にかえらん。<br/>',NULL,52471,5);
INSERT INTO stanza VALUES('J728','4','放蕩し,つみおかして, つかれしが,<br/>主のあいにたよりて, 主にかえらん。<br/>',NULL,52472,6);
INSERT INTO stanza VALUES('J728','5','虚偽にしつぼうして, きずついた,<br/>主はのぞみ,ちからぞ, 主にかえらん。<br/>',NULL,52473,7);
INSERT INTO stanza VALUES('J729','1','あいする主イェス, かくまいたまえ;<br/>かぜ吹き荒れて, なみ,さわぎ立つ！<br/>かくまいたまえ, あらしやむまで！<br/>安全にみちびき, まもりたまえや。<br/>',NULL,52474,1);
INSERT INTO stanza VALUES('J729','2','主は避けどころ, すべてゆだねる;<br/>われを捨てずに, なぐさめたまえ;<br/>すべてをたくし, たすけを受ける;<br/>聖なるつばさで, われをおおえや。<br/>',NULL,52475,2);
INSERT INTO stanza VALUES('J729','3','主はわがひつ要, あってあるかた:<br/>われをつよめて, みちびきたまえ;<br/>われ,不義なれど, なれは義とせい;<br/>めぐみと真理を, 主は満たされた。<br/>',NULL,52476,3);
INSERT INTO stanza VALUES('J729','4','大いなるめぐみ, わがつみ,ゆるす;<br/>いやすみずわき, きよめてまもる;<br/>なれはみなもと, いのちのいずみ,<br/>われよりあふれ, とわにながれる。<br/>',NULL,52477,4);
INSERT INTO stanza VALUES('J730','1','すくいぬしのこえ, ひとよ,聞け！<br/>主はたずねもとめ, なれさがす！<br/>',NULL,52478,1);
INSERT INTO stanza VALUES('J730','chorus','つみびとよ, みこえ聞け！<br/>主はたずねもとめ, なれ,まねく！<br/>',NULL,52479,2);
INSERT INTO stanza VALUES('J730','2','わがすくいぬしよ, 聞きたまえ！<br/>まねきにこたえる わがこえを。<br/>',NULL,52480,3);
INSERT INTO stanza VALUES('J730','chorus','すくいぬし！ 聞きたまえ！<br/>まねきにこたえる わがこえを。<br/>',NULL,52481,4);
INSERT INTO stanza VALUES('J730','3','めぐみの御座にて, すくい得る;<br/>いま,悔いあらため, こくはくす。<br/>',NULL,52482,5);
INSERT INTO stanza VALUES('J730','4','十字架のちからに, 依りたのむ;<br/>こころのいたみを いやしませ！<br/>',NULL,52483,6);
INSERT INTO stanza VALUES('J730','5','主はわがなぐさめ, わがいのち;<br/>主のほかにはなし, たよるもの。<br/>',NULL,52484,7);
INSERT INTO stanza VALUES('J731','1','裂かれたいわよ, かくまいたまえ;<br/>ながされた血は, われをあがない,<br/>ながされたみず, いのちあたえる。<br/>',NULL,52485,1);
INSERT INTO stanza VALUES('J731','2','いかなる労苦も, やくには立たず;<br/>なみだながすも, あがなわれ得ず;<br/>すくい得るのは, ただ主イェスのみ。<br/>',NULL,52486,2);
INSERT INTO stanza VALUES('J731','3','なにも持たずに, 十字架にたよる;<br/>すくいのころも, めぐみをもとむ;<br/>血のいずみにて, われをあらえや。<br/>',NULL,52487,3);
INSERT INTO stanza VALUES('J731','4','としつきは過ぎ, 死ぬ間ぎわにも,<br/>御まえに立つ日, えい遠にまでも,<br/>裂かれたいわよ, かくまいたまえ。<br/>',NULL,52488,4);
INSERT INTO stanza VALUES('J732','1','主は御座とかんむりを捨て, わがため世に来たもう;<br/>されどなが生まれし部屋は, ベツレヘムになし。<br/>',NULL,52489,1);
INSERT INTO stanza VALUES('J732','chorus','ああ,主イェスよ来ませ！ いまこころに来ませ！<br/>わがこころに来ませや！ ながため,部屋あり。<br/>',NULL,52490,2);
INSERT INTO stanza VALUES('J732','2','天使のうた,てん上のひびき, なが王たるを述べる;<br/>されどなれ,へりくだりもて, いやしく生まれる。<br/>',NULL,52491,3);
INSERT INTO stanza VALUES('J732','3','きつねにあな,とりに巣あれど, なれにやすみ場なし;<br/>子なるなれ,ガリラヤの地の, あら野に伏したもう。<br/>',NULL,52492,4);
INSERT INTO stanza VALUES('J732','4','主はたみを解きはなつため, めぐみもてこられた;<br/>カルバリでいばらのかんむり, あなどりを受ける。<br/>',NULL,52493,5);
INSERT INTO stanza VALUES('J732','5','さん美わき,てん上に和する, なれ勝利,得て来る日;<br/>「わがそばになが部屋あり」と のたもうみこえ聞く。<br/>',NULL,52494,6);
INSERT INTO stanza VALUES('J732','chorus','わが名を呼ぶために, とく主イェスよ,来ませ;<br/>そのときわがこころは, よろこびあふれる。<br/>',NULL,52495,7);
INSERT INTO stanza VALUES('J733','1','主イェスよ,来たりませ！ 悔いたるこころに;<br/>むなしくつかれたる こころに来ませ。<br/>',NULL,52496,1);
INSERT INTO stanza VALUES('J733','chorus','こころに,こころに, 主イェスよ来ませや！<br/>いま主よ,来たりて, こころにやどれや！<br/>',NULL,52497,2);
INSERT INTO stanza VALUES('J733','2','主イェスよ,来たりませ！ わがすくいとなり,<br/>つみの荷を解くため, こころに来ませ。<br/>',NULL,52498,3);
INSERT INTO stanza VALUES('J733','3','主イェスよ,来たりませ！ われをあらたにし,<br/>いのちのれい住みて, 支はいしたまえ。<br/>',NULL,52499,4);
INSERT INTO stanza VALUES('J734','1','つみあらい,きよめたもう, キリスト,すくいぬし;<br/>サタンすでにくだかれた, キリスト,すくいぬし。<br/>受け入れん！ いま,信じ受け入れん;<br/>受け入れん！ キリスト,すくいぬし。<br/>',NULL,52500,1);
INSERT INTO stanza VALUES('J734','2','わがいのち,大変化あり, キリスト,わがいのち！<br/>前途ひらけ,平安に満つ, キリスト,いのちとす。<br/>受け入れん！ こころむなしくし;<br/>受け入れん！ キリスト,いのちとす。<br/>',NULL,52501,2);
INSERT INTO stanza VALUES('J734','3','やまい去り,よわさなし, キリストはわが医者;<br/>苦痛も死も飲み尽くす, キリストを医者とす。<br/>受け入れん！ もはやうたがわず;<br/>受け入れん！ キリストを医者とす。<br/>',NULL,52502,3);
INSERT INTO stanza VALUES('J734','4','かなしみを歓喜とする, キリストはわがおう;<br/>王こく受け,栄光のぞむ, キリスト,わが王とす。<br/>受け入れん！ おのれを下ろして,<br/>受け入れん！ キリスト,わが王とす。<br/>',NULL,52503,4);
INSERT INTO stanza VALUES('J735','1','つみにおぼれて, へいあんなく,<br/>けがれにけがれ, もがきしとき,<br/>「主イェス」とさけぶ わがこえ聞き,<br/>イェスは引き上げ, すくわる！<br/>',NULL,52504,1);
INSERT INTO stanza VALUES('J735','chorus','主のあい！主のあい！ つみにおぼれたわれさえ,<br/>主のあい！主のあい！ われさえ世からすくわる！<br/>',NULL,52505,2);
INSERT INTO stanza VALUES('J735','2','ざいあく解かれ, あんそく得る,<br/>主イェスにぞくし, よろこび得る。<br/>あいはなお増し, さん美あふれ,<br/>われのすべては 主のもの！<br/>',NULL,52506,3);
INSERT INTO stanza VALUES('J735','3','くしき主のあい, なれをすくう;<br/>みこえを聞いて, すくいを得よ。<br/>ひさしくイェスは, 待ちわびたもう;<br/>いま,すくい得よ, ただちに！<br/>',NULL,52507,4);
INSERT INTO stanza VALUES('J736','1','つみのなかさすらって, けがれていた,<br/>主はわがこころに来て, あいでつつむ。<br/>',NULL,52508,1);
INSERT INTO stanza VALUES('J736','chorus','わが主,えい光, ハレルヤ,いーま主を見た！<br/>わが主,えい光, いーま主を見た！<br/>',NULL,52509,2);
INSERT INTO stanza VALUES('J736','2','見えない目ひらかれて, 御かおを見た;<br/>主の愛のうつくしさは, 言い尽くせず。<br/>',NULL,52510,3);
INSERT INTO stanza VALUES('J736','3','すべてに勝利得させる 主にゆだねる;<br/>こよなきすくいぬしよ, わがいのち,愛。<br/>',NULL,52511,4);
INSERT INTO stanza VALUES('J737','1','つみにくるしむ われをさがし,<br/>かれはやさしく かたに乗せて,<br/>ひつじのむれへと, われをかえされる。<br/>',NULL,52512,1);
INSERT INTO stanza VALUES('J737','chorus','こよなきあい！ あがないの死！<br/>満ちあふるめぐみよ！ むれへとかえされる！<br/>',NULL,52513,2);
INSERT INTO stanza VALUES('J737','2','きず負うわれに あぶらを塗り,<br/>かれはささやく: 「なれ,わがもの！」<br/>このあまきこえに, こころはよろこぶ。<br/>',NULL,52514,3);
INSERT INTO stanza VALUES('J737','3','くぎあとしめし, 血はながれる,<br/>いばらのかんむり, こうべに受く;<br/>主の受けた苦つう, はかり知れぬもの。<br/>',NULL,52515,4);
INSERT INTO stanza VALUES('J737','4','御まえに座して, 御かおを見る,<br/>こころ感げきし, しゅくふくおもう;<br/>とこ世のさん美も, なお主には足らず。<br/>',NULL,52516,5);
INSERT INTO stanza VALUES('J737','5','ときは過ぎゆき, あんそくする;<br/>さいこうのあさ, いまや間ぢか:<br/>きずなきはなよめ, むかえ入れられる。<br/>',NULL,52517,6);
INSERT INTO stanza VALUES('J738','1','ゆたかなすくい, ゆたかなすくい,<br/>ゆたかなすくい, 言いがたし！<br/>',NULL,52518,1);
INSERT INTO stanza VALUES('J738','chorus','主はきずな断つ, 主はきずな断つ,<br/>主はきずな断ち, かい放する。<br/>',NULL,52519,2);
INSERT INTO stanza VALUES('J738','2','つみゆるされて, へい安に満ちる,<br/>きずなより,われ かい放さる！<br/>',NULL,52520,3);
INSERT INTO stanza VALUES('J738','3','つみやゆうわく, この世やあく魔,<br/>やまい,うれいに しばられず！<br/>',NULL,52521,4);
INSERT INTO stanza VALUES('J738','4','ハレル！あまき名, ハレル！あまき名,<br/>ハレル！あまき名, ほめうたう！<br/>',NULL,52522,5);
INSERT INTO stanza VALUES('J738','5','うたえ,ハレルヤ, うたえ,ハレルヤ,<br/>うたえ,ハレルヤ, 主のかい放！<br/>',NULL,52523,6);
INSERT INTO stanza VALUES('J739','1','十字架ですくいぬし, いのち捨て,血ながす;<br/>この血われをあらう; 栄こう主に！<br/>',NULL,52524,1);
INSERT INTO stanza VALUES('J739','chorus','栄こう主の名に！ 栄こう主の名に！<br/>主の血われをあらう; 栄こう主に！<br/>',NULL,52525,2);
INSERT INTO stanza VALUES('J739','2','十字架で血をながし, 主,わがつみをあらう;<br/>何と不思議なあらい; 栄こう主に！<br/>',NULL,52526,3);
INSERT INTO stanza VALUES('J739','3','何ときよきあらいよ, ゆきのようなしろさ！<br/>われを超えつさせる; 栄こう主に！<br/>',NULL,52527,4);
INSERT INTO stanza VALUES('J739','4','このいずみに来たれ; 主にすべてゆだねよ;<br/>きょうのうちに飛び込め; 栄こう主に！<br/>',NULL,52528,5);
INSERT INTO stanza VALUES('J740','1','主イェスよ,なれの はかをかこみ,<br/>ながわざのゆえ, あかしをする。<br/>われら信仰もて ながみち行き,<br/>このみずにより, みわざに入る。<br/>',NULL,52529,1);
INSERT INTO stanza VALUES('J740','2','主イェスの苦難を いま記念する,<br/>ほえたけるなみ, なれをおそう;<br/>死のみずのなか, バプテスマされ,<br/>御血をながして, わがため死ぬ。<br/>',NULL,52530,2);
INSERT INTO stanza VALUES('J740','3','主は復かつして, くらやみなし,<br/>御座にのぼって, 永遠に生きる;<br/>死とよみ,やぶり, われもともに,<br/>ながいのちにて, みわざ享受す。<br/>',NULL,52531,3);
INSERT INTO stanza VALUES('J740','4','バプテスマされ, 主の死といち！<br/>ともに復かつし, 栄光を受ける。<br/>サタン,この世,つみ, もはや縁なし;<br/>たびびととして, ともに生きる。<br/>',NULL,52532,4);
INSERT INTO stanza VALUES('J741','1','キリストとともに,みずにほうむられ,死ぬ;<br/>この世もサタンも,もはやついげきし得ず。<br/>ともに復かつし,主とともに生き,あゆむ;<br/>れいのちからは無げん,めぐみ,えいこういや増す。<br/>',NULL,52533,1);
INSERT INTO stanza VALUES('J742','1','主よ,このみずにて, なが死とひとつ,<br/>その価値と意義を, 啓示したまえ。<br/>',NULL,52534,1);
INSERT INTO stanza VALUES('J742','2','このみずのなかで ともにほうむられ,<br/>つみのなわめより 永遠に解かる。<br/>',NULL,52535,2);
INSERT INTO stanza VALUES('J742','3','このみずによって, この世とわかれ,<br/>この世のきみより, 解ほうされる。<br/>',NULL,52536,3);
INSERT INTO stanza VALUES('J742','4','ともに復かつして, 死より解かれる;<br/>新ようしきを生き, 聖の実むすぶ。<br/>',NULL,52537,4);
INSERT INTO stanza VALUES('J742','5','主の名のなかへと バプテスマされ,<br/>永遠になれを生き, なれとひとつ。<br/>[４　新ようしき――新しい生活様式]<br/>',NULL,52538,5);
INSERT INTO stanza VALUES('J743','1','われ死に,ほうむられ, 完全に終わらされた！<br/>われ死に,ほうむられ, 完全に終わらされた！<br/>',NULL,52539,1);
INSERT INTO stanza VALUES('J743','2','終わった！終わった！ 完全に終わらされた！<br/>終わった！終わった！ 完全に終わらされた！<br/>',NULL,52540,2);
INSERT INTO stanza VALUES('J743','3','わたしは,もはーや, 生きているのでなく,<br/>キリスト！キリスト！ わがうちに生きるは。<br/>',NULL,52541,3);
INSERT INTO stanza VALUES('J744','1','「みずにてすくわる」, 何たる不思議,<br/>すくいのきょう地を けい示しませ。<br/>',NULL,52542,1);
INSERT INTO stanza VALUES('J744','2','「みずにてすくわれ」, 再せいされた;<br/>過去のものすべて ほうむられた。<br/>',NULL,52543,2);
INSERT INTO stanza VALUES('J744','3','洪ずい,この世から ノアをすくう;<br/>バプテスマ,われを 世から分離す。<br/>',NULL,52544,3);
INSERT INTO stanza VALUES('J744','4','紅かいのみず経て, エジプト去る;<br/>バプテスマ,われを, 世から解放す。<br/>',NULL,52545,4);
INSERT INTO stanza VALUES('J744','5','「みずにてすくわる」, 何たる超えつ;<br/>つみやあく魔より, われ,はなれる。<br/>',NULL,52546,5);
INSERT INTO stanza VALUES('J744','6','「みずにてすくわれ」, かみに帰する;<br/>礼はいとほう仕は, わが分となる。<br/>',NULL,52547,6);
INSERT INTO stanza VALUES('J745','1','王こくはかみの とう治,えい光;<br/>主権は王こくの ちつ序維持す。<br/>かみは王こくで 王権を行使す,<br/>なが権威,王こく, 永遠にいたる。<br/>',NULL,52548,1);
INSERT INTO stanza VALUES('J745','2','王こくの中心は, けん威の御座;<br/>御むねにしたがい, かみ,支はいす。<br/>かれは王となり, 一切を管理す;<br/>主の身分,保持し, かしらとなる。<br/>',NULL,52549,2);
INSERT INTO stanza VALUES('J745','3','かみは王こくで, 御むね遂行す;<br/>統治権のもとで, 御むね成就す。<br/>王こくのなかで, しゅくふく得る;<br/>御座より,いのち あふれながる。<br/>',NULL,52550,3);
INSERT INTO stanza VALUES('J745','4','かん理にふくし, しゅくふく得る;<br/>反ぎゃくするのは, ざいあくの根。<br/>御座をたおそうと, サタンもくろむ;<br/>主の権威のもと, われら生きる。<br/>',NULL,52551,4);
INSERT INTO stanza VALUES('J745','5','王こくのなかで, いのちにあり,<br/>キリスト大きく あらわされる。<br/>かみは統治して, しゅくふくする;<br/>主は権威にぎり, 栄光,表現する。<br/>',NULL,52552,5);
INSERT INTO stanza VALUES('J745','6','ときが満ちると, 万有,主に帰し,<br/>主の権威を知り, 統治を受ける。<br/>いのちの支配を 召会あじわい,<br/>王こくもたらし, 万有も享受す。<br/>',NULL,52553,6);
INSERT INTO stanza VALUES('J746','1','天ごくいま地上にあり, わがこころ支配する;<br/>キリストわがうちに生きて, 主とし王としおさめる。<br/>',NULL,52554,1);
INSERT INTO stanza VALUES('J746','2','主はいのち,権威により, こころに御座を据え,<br/>われらの言動すべて支配し, うちなる部分を管理す。<br/>',NULL,52555,2);
INSERT INTO stanza VALUES('J746','3','主はこころに御座据え, 主の王こくを建造す,<br/>主の全権統治をもておさめ, かく面でみちそなえる。<br/>',NULL,52556,3);
INSERT INTO stanza VALUES('J746','4','こころ支配されるとき, いのち供きゅうされる;<br/>主を主とし,王とするときに, 主のゆたかを享受する。<br/>',NULL,52557,4);
INSERT INTO stanza VALUES('J746','5','わがうちの統治により, 主の豊満,けん造され,<br/>わがうちの王こくの権威で, 主のからだ建造される。<br/>',NULL,52558,5);
INSERT INTO stanza VALUES('J746','6','うちなる天の支配にて, 天のたみのように生く;<br/>主の支配にふくするわれに, おうこくはじつ現する。<br/>',NULL,52559,6);
INSERT INTO stanza VALUES('J746','7','この天の領いきに生き, 天の主権を所有する,<br/>天のひかりに生き,たたかい, 王こくを地にもたらす。<br/>',NULL,52560,7);
INSERT INTO stanza VALUES('J747','1','王こくのよう求たかく, 律法の要求超える;<br/>小さな要きゅうでさえも, 応じるのはむずかしい。<br/>',NULL,52561,1);
INSERT INTO stanza VALUES('J747','2','「てんごくはちかづいた, 悔いあらためよ」と,<br/>王こくのよう求はまず, おもいを変えること。<br/>',NULL,52562,2);
INSERT INTO stanza VALUES('J747','3','天ごくへはいるために, 最高の義がひつ要;<br/>いのちから出たものは, 律ぽうの義にまさる。<br/>',NULL,52563,3);
INSERT INTO stanza VALUES('J747','4','天ごくへはいるために, 御むねをおこなう;<br/>自己のねがいによらず, みこころにしたがう。<br/>',NULL,52564,4);
INSERT INTO stanza VALUES('J747','5','天ごくへはいるために, 自分をひくくして,<br/>おさな子のようになり, 単純で従じゅんになる。<br/>',NULL,52565,5);
INSERT INTO stanza VALUES('J747','6','かみとおなじ完ぜんを, 天ごくは要求する;<br/>この標準に生きるなら, 天ごくのじっ際持つ。<br/>',NULL,52566,6);
INSERT INTO stanza VALUES('J747','7','王こくはかみの支はい, ひとは神性ひつ要;<br/>ただかみのいのちのみ, 王こくにはいらせる。<br/>',NULL,52567,7);
INSERT INTO stanza VALUES('J747','8','王こく,天のかん理ゆえ, 天の状況と合致し,<br/>王こくにあずかるには, 天のいのちがひつ要。<br/>',NULL,52568,8);
INSERT INTO stanza VALUES('J748','1','天ごくのその実際は, 天に支はいされる生かつ;<br/>その生かつは神せいで, キリストを生きること。<br/>',NULL,52569,1);
INSERT INTO stanza VALUES('J748','2','そのような生かつは, 霊にてまずしく,かなしみ,<br/>ひとにあわれみふかく, かみにはきよきこころ。<br/>',NULL,52570,2);
INSERT INTO stanza VALUES('J748','3','かみの子,平和つくり, 義のためくるしみを受け,<br/>主のためそしられても, うらまず,よろこんでいる。<br/>',NULL,52571,3);
INSERT INTO stanza VALUES('J748','4','地のしおとして殺菌し, ひかりとしてやみ照らす;<br/>動機と行動は真じつで, ただあいして,うらまず。<br/>',NULL,52572,4);
INSERT INTO stanza VALUES('J748','5','おのが義,栄光こばみ, かみのくにのためいのる;<br/>かみのくにと義もとめ, ただかみに依りたのむ。<br/>',NULL,52573,5);
INSERT INTO stanza VALUES('J748','6','おのれにはきびしく, 他のひとにめぐみふかく,<br/>ちちの御むねおこない, みことばにより行動す。<br/>',NULL,52574,6);
INSERT INTO stanza VALUES('J748','7','サタンに地位ゆずらず, この世の人情をいなんで,<br/>天のかん理にしたがい, かみのまったき権威受く。<br/>',NULL,52575,7);
INSERT INTO stanza VALUES('J748','8','その生かつすべては, かみの大能もて征ふくす;<br/>主のさい来をうながし, ここに天ごくじつ現す。<br/>',NULL,52576,8);
INSERT INTO stanza VALUES('J749','1','何というえいこう,光輝！ 王こくじつ現する！<br/>かみはキリスト立て, 権威さずけられた。<br/>かつてにくたいにあり, かれはあなどられた;<br/>威厳帯びてさい臨し, 王こくを成就する。<br/>',NULL,52577,1);
INSERT INTO stanza VALUES('J749','2','日の老いたるものは, 権威,王こくを得る;<br/>王こくとともに来て, 栄光をひょう現する。<br/>「ひと手によらぬいし」は, 諸こくをふんさいし,<br/>「大きなやま」は満ちて, 王こくはかがやく。<br/>',NULL,52578,2);
INSERT INTO stanza VALUES('J749','3','見よ,地と諸こくみな, キリストに帰する,<br/>かみの至高の統治で, 平安とへい和満つ。<br/>諸こくに戦そうはなく, 惨さつの戦場はなし;<br/>かみを知る知しきは, 全地に満ち満ちる。<br/>',NULL,52579,3);
INSERT INTO stanza VALUES('J749','4','勝利のキリスト者は, 主とともにおさむ;<br/>イスラェルのレムナント, かみの祭司となる。<br/>諸こくみんは地じょうで 王こくのたみとなる;<br/>万ぶつはえいこうの 復こうへといたる。<br/>',NULL,52580,4);
INSERT INTO stanza VALUES('J749','5','サタンはしばられて, 地はかいふくされ,<br/>キリストのとう治で 地,しゅくふく満ちる。<br/>キリストにみな降参し, かれの統治にふくす;<br/>かれはかしらとなり, みこころを成就す。<br/>',NULL,52581,5);
INSERT INTO stanza VALUES('J750','1','かみの子来てたねまく, ご自身のいのちを;<br/>たねは王こく生み, 永遠のご計かく成就する。<br/>',NULL,52582,1);
INSERT INTO stanza VALUES('J750','2','ひとつぶのむぎのたね, 多くのむぎを生む;<br/>王こくの子らとし, 権威をあたえ,統治させる。<br/>',NULL,52583,2);
INSERT INTO stanza VALUES('J750','3','かみのてきなるサタンは, どくむぎまき込む;<br/>王こくの子,混乱し, おそるべき損害あたえる。<br/>',NULL,52584,3);
INSERT INTO stanza VALUES('J750','4','むぎにどくむぎ混ぜる こうかつな手ぐちで,<br/>天ごくのがい観は, 不正常に大きく生長した。<br/>',NULL,52585,4);
INSERT INTO stanza VALUES('J750','5','天ごく,からしだねのよう, 食べるに良きもの,<br/>いま大ぼくとなり, 巨大な組しきに変化した。<br/>',NULL,52586,5);
INSERT INTO stanza VALUES('J750','6','しょくもつとなる代わり, そらの「とり」やどす;<br/>あく人やあく霊が いまや寄せいするところ。<br/>',NULL,52587,6);
INSERT INTO stanza VALUES('J750','7','巨大な宗教の世かいは, がい観があるのみ;<br/>あく事をふくんで, パンだねにより発こうする。<br/>',NULL,52588,7);
INSERT INTO stanza VALUES('J750','8','この世の組しきはいま, このように変化して,<br/>邪あく,けがれ満ち, 内面は腐敗と淫行で満つ。<br/>',NULL,52589,8);
INSERT INTO stanza VALUES('J750','9','かくれたこと見る主は, われらをさがして,<br/>真珠,ほうせきへと つくり変え,たからとする。<br/>',NULL,52590,9);
INSERT INTO stanza VALUES('J750','10','キリスト教にかくされ, 外観にかくされた,<br/>王こくの実さいは, キリストとかみ表現する。<br/>',NULL,52591,10);
INSERT INTO stanza VALUES('J750','11','どくむぎ,たいぼくより, われ,はなれさせよ;<br/>すべてのパンだねを きよめて,純粋にならせよ。<br/>',NULL,52592,11);
INSERT INTO stanza VALUES('J750','12','たましいをつくり変え, とうとき材料となし,<br/>王こくの実際持ち, なが霊のみやとなしませ。<br/>',NULL,52593,12);
INSERT INTO stanza VALUES('J751','1','いま,かみのくにはくん練である,<br/>やがて主の統治のときには,<br/>大いなる褒美となるを知れば,<br/>ご計かく成るため訓練受く。<br/>',NULL,52594,1);
INSERT INTO stanza VALUES('J751','2','王となるために生まれたわれら,<br/>王となるため,訓練はひつ要。<br/>王こくで支配するすべを知り,<br/>すべてのうえで王権,表現す。<br/>',NULL,52595,2);
INSERT INTO stanza VALUES('J751','3','御座にふくするをこの日まなび,<br/>ご自身の統治と生かつ知る;<br/>さらば主のけん威にあずかり,<br/>御子とともに王権,行使する。<br/>',NULL,52596,3);
INSERT INTO stanza VALUES('J751','4','おのれにきびしく,義をたもちて,<br/>ひとに寛だい,めぐみふかく;<br/>王こくの実さいに生きつづけ,<br/>王こくでの統治を準備する。<br/>',NULL,52597,4);
INSERT INTO stanza VALUES('J751','5','王こくとともにキリスト来る日,<br/>われら褒賞とし王権を得る;<br/>主の義われらにより表現され,<br/>主の知恵あきらかにされる。<br/>',NULL,52598,5);
INSERT INTO stanza VALUES('J751','6','ゆえ使徒まえに向かい努りょくし,<br/>そらされないよう代価はらう;<br/>王こくのほう賞を得るために,<br/>忠じつなれとひとに命じる。<br/>',NULL,52599,6);
INSERT INTO stanza VALUES('J751','7','王こくに生きるめぐみあたえよ,<br/>ほう賞受くため訓練される;<br/>王こくの実さいを日々実行す,<br/>その出現われらの褒賞なり。<br/>',NULL,52600,7);
INSERT INTO stanza VALUES('J752','1','主がほう賞あたえる日, だれも知らない;<br/>絶えず明かりととのえ, そなえているか？<br/>',NULL,52601,1);
INSERT INTO stanza VALUES('J752','chorus','主に会う用意をしたか, 準備ととのったか？<br/>主が来られるのを待ち, 目を覚ましているか？<br/>',NULL,52602,2);
INSERT INTO stanza VALUES('J752','2','きょう主が来て自分を呼び, けい算するとき,<br/>「良いしもべ,よくやった」と 言われるだろうか？<br/>',NULL,52603,3);
INSERT INTO stanza VALUES('J752','3','主の委たくを忠じつに おこなっているか？<br/>自分にできることみな, 尽くしただろうか？<br/>',NULL,52604,4);
INSERT INTO stanza VALUES('J752','4','その日,目,覚ましている, さいわいなひと！<br/>主がさいりんするとき, ともに王となる。<br/>',NULL,52605,5);
INSERT INTO stanza VALUES('J753','1','主イェスよ,われは待つ, たずさえ上げを,<br/>主の来ることよりも あまきものなし。<br/>主のさいりんをいま, われは待ちのぞむ,<br/>主はちかいこと知る, 主の臨ざいゆえ。<br/>',NULL,52606,1);
INSERT INTO stanza VALUES('J753','2','わがうちのふかみで, ながみこえ聞き,<br/>なれのごけいかくを, めいかくに知る。<br/>さいりんの日ちかい！ 主のしゅつ現,間ぢか！<br/>めぐみの日はわずか！ てきはほろびる！<br/>',NULL,52607,2);
INSERT INTO stanza VALUES('J753','3','からみつくものから, われ,自由にされ,<br/>まといつくもの捨て, なれにしたがう。<br/>「理にかなうこと」でも, 下ろしてしたがう,<br/>主が来られるときに, すぐ行けるため。<br/>',NULL,52608,3);
INSERT INTO stanza VALUES('J753','4','目を覚まし,待つこと, われはもとめる;<br/>引き上げられるため, れいにしたがう。<br/>用意をしないがゆえ, 居ねむりしたゆえ,<br/>地じょうにのこされて, 歯がみせぬように。<br/>',NULL,52609,4);
INSERT INTO stanza VALUES('J753','5','わがこころよ,これは 厳しゅくな警こく,<br/>世をあいすことから, かいほうされよ。<br/>絶えず主をしたいて, 主をふかくおもい,<br/>主にいつ呼ばれても, すぐ応じるように。<br/>',NULL,52610,5);
INSERT INTO stanza VALUES('J753','6','たたかいははげしく, 試練があるとも,<br/>たずさえ上げちかし, おそれなどなし。<br/>いま,くらやみあれど, あがないの日来る,<br/>こうべを上げて待つ, 主はすぐに来る。<br/>',NULL,52611,6);
INSERT INTO stanza VALUES('J753','7','主よ,なれのみあいし, なれのみおもう,<br/>世のわい賂をこばみ, ただなれもとむ。<br/>そくばくは解かれた, わが主,来たりませ,<br/>天でわが愛する主に まみえるをしたう！<br/>',NULL,52612,7);
INSERT INTO stanza VALUES('J754','1','主はさいりんする,ラッパはひびく,<br/>死んだせい徒は復かつす;<br/>生きているせい徒は引き上げられ,<br/>からだはえい光化される。<br/>',NULL,52613,1);
INSERT INTO stanza VALUES('J754','chorus','主は再臨する,われ, えい光の主を見る;<br/>からだのあがないに, われもかならずあずかる。<br/>',NULL,52614,2);
INSERT INTO stanza VALUES('J754','2','主はさいりんする,あさ日はのぼり,<br/>よるとなみだは過ぎ去る;<br/>えい光の日が来る,堕らくなくなり,<br/>なげき,かならず逃げ去る。<br/>',NULL,52615,3);
INSERT INTO stanza VALUES('J754','3','主はさいりんする,明けの明じょう出,<br/>忠じつなものかんむり得る;<br/>義のたい陽,権威を持ち,ばんぶつを<br/>復こうし,地をかえりみる。<br/>',NULL,52616,4);
INSERT INTO stanza VALUES('J754','4','主はさいりんする，せい徒は目覚め,<br/>ともし火ともし,主を待つ;<br/>たまもの地に埋めず,いたる場所で<br/>忠じつにつとめを尽くす。<br/>',NULL,52617,5);
INSERT INTO stanza VALUES('J755','1','間もなく主はさい臨する; あしおとが聞こえる。<br/>目覚めよ！主を待ちのぞめ, 上げられて,主に会え。<br/>',NULL,52618,1);
INSERT INTO stanza VALUES('J755','chorus','栄光！主はすぐに来る, 栄光！せい徒ら歓喜す,<br/>いやしきからだ変えられ, 主としゅくふく享受す。<br/>',NULL,52619,2);
INSERT INTO stanza VALUES('J755','2','間もなく主はさい臨する; 明けの明星あらわる。<br/>目覚めよ！世の潮りゅう出て, だい患難まぬかれよ。<br/>',NULL,52620,3);
INSERT INTO stanza VALUES('J755','3','間もなく主はさい臨する; しもべは褒しょう得る。<br/>目覚めよ！主を愛するもの, かならずかんむり得る。<br/>',NULL,52621,4);
INSERT INTO stanza VALUES('J755','chorus','いま,こころを尽くし, 主をあいし,つかえる,<br/>「良いしもべよ,よくやった！」 主のほめるこえ聞く。<br/>',NULL,52622,5);
INSERT INTO stanza VALUES('J755','4','間もなく主はさい臨する; ばん民は帰じゅんする。<br/>目覚めよ！聖徒,ぜん進して, 王となり,王こく得よ。<br/>',NULL,52623,6);
INSERT INTO stanza VALUES('J756','1','わが王はさいりんし, 万ぶつは復こうし,<br/>宇ちゅうはあがなわれ, すくい完成する！<br/>われはくものなかの 主のあしおと聞き,<br/>主の栄光のひそかな あらわれを見る。<br/>',NULL,52624,1);
INSERT INTO stanza VALUES('J756','2','主の「臨ざい」をのぞむ, 主がさいりんして,<br/>われに天を得さすよう, われ待ちのぞむ。<br/>すばらしい臨在のなか あること以がいに,<br/>こころのしたうもの, われは持たない。<br/>',NULL,52625,2);
INSERT INTO stanza VALUES('J756','3','こころ,もう天にあり, 目はただ主,見つめ,<br/>くちは主に会うこと, ひたすらかたる。<br/>主のさい臨は間ぢか, それはわれのため;<br/>主のやくそくは不変, かならず成就す。<br/>',NULL,52626,3);
INSERT INTO stanza VALUES('J756','4','主のことばは不へん, かんぜんでかん備,<br/>そのことばをもって, われをはげます。<br/>なが栄こうあらわし, てきを打ちやぶり,<br/>ながやくそく成就し, われ,むかえませ。<br/>',NULL,52627,4);
INSERT INTO stanza VALUES('J756','5','すくいぬしのうでは, われのさけどころ！<br/>なれにたよるものを, みなまもられる;<br/>主はひつじをとうとび, からだ,ひつ要とす;<br/>だれもなれの手より, うばうものなし。<br/>',NULL,52628,5);
INSERT INTO stanza VALUES('J756','6','もはや千万のひとも, われをさまたげず;<br/>路上のいばらさえも, わがえきとなる。<br/>こころ,れい,復興せよ, この世を去らせよ;<br/>いのちの主よ！来ませ, われ,なれを待つ。<br/>',NULL,52629,6);
INSERT INTO stanza VALUES('J756','7','いやす太陽,のぞみよ, ながひかりあいす;<br/>こう義の主！栄光の王！ われはひれ伏す;<br/>主よ,とく御座に着き, 御かお照らしませ！<br/>万民にめぐみあたえ, 王こく建てませ！<br/>',NULL,52630,7);
INSERT INTO stanza VALUES('J756','8','真理はおうであって, 自由は王妃である！<br/>虚偽がたけりくるい, 世のきみとなる！<br/>されば真理よ,来たれ！ 天のひかり帯びて,<br/>主よ,来て主の子らを, 主にむかえませ！<br/>',NULL,52631,8);
INSERT INTO stanza VALUES('J757','1','間もなく来る主を どうしてわすれよう？<br/>あさの詩歌うたい, 主をしたい,おもう。<br/>',NULL,52632,1);
INSERT INTO stanza VALUES('J757','chorus','主よ,来ませ！ わが王よ,来ませ！<br/>',NULL,52633,2);
INSERT INTO stanza VALUES('J757','2','目を覚ましいのり, あさに夕に主,おもう！<br/>引き上げの機かい, うしなわぬように。<br/>',NULL,52634,3);
INSERT INTO stanza VALUES('J757','3','天に召されたゆえ, この世を断ち切る;<br/>地のもの捨て去り, ただ主をあいする。<br/>',NULL,52635,4);
INSERT INTO stanza VALUES('J757','4','日ごと霊にあゆみ, 主のちからを得る;<br/>目を覚まし,そなえ, 主の日待ちのぞむ。<br/>',NULL,52636,5);
INSERT INTO stanza VALUES('J757','5','サタンをおそれず, つねにかたく立つ;<br/>ハデスの門に勝利, 主すでに権威持つ。<br/>',NULL,52637,6);
INSERT INTO stanza VALUES('J757','6','このメｯセｰジさけび, 地をおそれさせる！<br/>主,やくそく成就し, みことば証明する。<br/>',NULL,52638,7);
INSERT INTO stanza VALUES('J758','1','ベタニアにてわかれしあと, こころにむなしさあり,<br/>主がここにおられないのに, どうしてうたえようか？<br/>ひとりさびしく夜まわりし, やくそくをおもい起こす;<br/>主よ,いつの日まで待つのか？ 主よ,はやくじょう就しませや｡<br/>',NULL,52639,1);
INSERT INTO stanza VALUES('J758','2','馬ぶね,わが家を持たせない, 十字架,たのしみ去らす,<br/>さい臨,ふるさとをおもわせ, 主,わがもくひょうとなる。<br/>主いなければ,あじわい失せ, うたもあまさをうしなう;<br/>なにかうしない,待ちのぞむ, 主よ,おくれずに来たりませ！<br/>',NULL,52640,2);
INSERT INTO stanza VALUES('J758','3','なれの臨ざいきょう受するが, なお欠けた感かくあり;<br/>なが照らし,なぐさめあるが, いまだ満たされ得ない！<br/>へい安のなかで孤どく感じ, なお,ためいきが出てくる,<br/>わがこころ満たされぬのは, いまだなれとまみえぬゆえ。<br/>',NULL,52641,3);
INSERT INTO stanza VALUES('J758','4','異きょうにて祖こくをおもい, ふるさと,とも,恋いしたう;<br/>あいするもの,家ぞくはなれ, さいかいの日をしたう;<br/>主よ,このようなよろこびも, あの感げきにはおよばず;<br/>主よ,なが御かお見ぬうちは, ためいきのみ,主よ,来ませや！<br/>',NULL,52642,4);
INSERT INTO stanza VALUES('J758','5','主よ,やくそくおもい起こし, 待たせず,とく来ませや。<br/>あの日からいくとせ待てど, いまだ,なれかえり来ぬ！<br/>主よ,いつまで待つのですか？ なれをしたい,待ちわびる！<br/>いつの日,やくそくじょう就す？ たずさえ上げを待ちのぞむ。<br/>',NULL,52643,5);
INSERT INTO stanza VALUES('J758','6','いちだい,いちだい,聖徒らは, 日ごと,日ごと再臨待つ,<br/>その日,来るのを待ちながら, せい徒ら,この世を去る。<br/>わが主よ,はやく来たりませ, なにゆえ天は閉ざされる;<br/>われらいまだに待ちに待つ, 待つことなおも足りぬのか？<br/>',NULL,52644,6);
INSERT INTO stanza VALUES('J758','7','さい臨をおもい,なみだする, わがねがい聞き入れて,<br/>いますぐわれをむかえ入れ, なれに相まみえさせよ；<br/>召かいはさけぶ,来たりませ！ 聖徒らさけぶ,来たりませ！<br/>れき代の積み上げたさけび, 主よ,いまこそ聞きたまえや！<br/>',NULL,52645,7);
INSERT INTO stanza VALUES('J759','1','いつの日,主はもどる？ とく主に会いたい！<br/>がい歌をうたいつつ, 主の来られるを待つ。<br/>めぐみの主,来ませ, いつわれ,なぐさめ得るや？<br/>主よ,とく来ませや, われいのり,待つ！<br/>',NULL,52646,1);
INSERT INTO stanza VALUES('J760','1','オリブやま,はなれてから, いまだ,われら召されず;<br/>代々にわたり待ってきたが, いのり聞かれないかのよう。<br/>',NULL,52647,1);
INSERT INTO stanza VALUES('J760','chorus','主よ,来ませや！ 主よ,はやく来まーせ！<br/>せつにのぞむ,さいらいを！ はやく主,来ませ！<br/>',NULL,52648,2);
INSERT INTO stanza VALUES('J760','2','愛する主が昇天してから, すべてあじわい失せる;<br/>つねに目を覚まし,いのり, ためいきもて主を待つ。<br/>',NULL,52649,3);
INSERT INTO stanza VALUES('J760','3','景しきうるわしくあれど, なれ,いずこにいますや？<br/>わがこころは満たされぬ, なれにまみえるまでは。<br/>',NULL,52650,4);
INSERT INTO stanza VALUES('J760','4','主よ！われら待ちこがれる, なお,どれほど待つのか？<br/>日が出て暮れるたびごと, なが再来を待ちのぞむ。<br/>',NULL,52651,5);
INSERT INTO stanza VALUES('J760','5','自ぜん界はうつり変わり, ときがめぐるたびごと,<br/>ながかえり待ちわびるも, きざしなく,しつ望する。<br/>',NULL,52652,6);
INSERT INTO stanza VALUES('J760','6','なれの命令おぼえるゆえ, わが勤労むなしくない;<br/>さい臨を待ちのぞみつつ, ながために生かつする。<br/>',NULL,52653,7);
INSERT INTO stanza VALUES('J760','7','ながく待ちのぞんできたが, 主よ,さらに待ちのぞむ;<br/>主のさい来の日はちかい, 主よ！きょうにも来たりませ。<br/>',NULL,52654,8);
INSERT INTO stanza VALUES('J761','1','主イェス,主イェス！なぜ来ぬや！ 主イェス,主イェス！なぜ来ぬや？<br/>全被造ぶつはみなうめき, 天地はすべてさい臨待つ;<br/>宇ちゅうふるび,なれを待つー, われらいのる,ながさい臨,<br/>とく来ませ, とく来ませ。<br/>',NULL,52655,1);
INSERT INTO stanza VALUES('J761','2','主イェス,主イェス！なぜ来ぬや！ なぜにさい臨おくらすや？<br/>聖徒ら代々にながく待ち, われらすでにながく待つ,<br/>なぜにかの日,はやめぬやー？ なぜにおそい？とく来ませ,<br/>とく来ませ, とく来ませ。<br/>',NULL,52656,2);
INSERT INTO stanza VALUES('J761','3','主イェス,主イェス！なぜ来ぬや！ なれがしょう天されたのち,<br/>われのてんは明けぬよう, われのかおは笑み失せる;<br/>こころざしもいろあせるー, 主イェス,主イェス！なぜ来ぬや！<br/>なぜ来ぬや, なぜ来ぬや！<br/>',NULL,52657,3);
INSERT INTO stanza VALUES('J761','4','来ませ,来ませ！周囲はみな, こうたいして怠惰である！<br/>あいは冷めて,代価避ける, しん仰よわり,あし,おもい,<br/>のぞみ,消えた燈火のようー, 主イェス！なぜにまだ来ぬや？<br/>まだ来ぬや？ まだ来ぬや？<br/>',NULL,52658,4);
INSERT INTO stanza VALUES('J761','5','主イェス,主イェス！なぜ来ぬや！ 主イェス,主イェス！なぜ来ぬや？<br/>われをなん年待たせるや？ いのり,待てど,もう待てぬ;<br/>主イェス,主イェス！来たりませｰ, 主イェス,主イェス！とく来ませ！<br/>とく来ませ！ とく来ませ！<br/>',NULL,52659,5);
INSERT INTO stanza VALUES('J762','1','主よ,ながさい臨待つ, ひさしく,<br/>いつまでも待つよう, 待ちつづけた;<br/>御かお見,こえ聞くを われしたう,<br/>なおふかきまじわり, われはもとむ。<br/>',NULL,52660,1);
INSERT INTO stanza VALUES('J762','chorus','さらにいくとせ 主を待つのか？<br/>なみだもて,主おもい, 再りんをしたう。<br/>',NULL,52661,2);
INSERT INTO stanza VALUES('J762','2','やもめはありし日を しのんで,<br/>もう会えないことを かなしまぬか？<br/>はなよめ,とつぐ日を 延ばされ,<br/>日取り決まらないなら, 嘆そくせぬか？<br/>',NULL,52662,3);
INSERT INTO stanza VALUES('J762','3','召かい代々になれを 待ち,待つ,<br/>忍たいして待てども, なれ,まだ来ぬ;<br/>われもしょう涯かけて 待ち,待つ,<br/>あのともも世を去った, なれ,まだ来ぬ。<br/>',NULL,52663,4);
INSERT INTO stanza VALUES('J762','4','われ,なれを待つこと ひさしく,<br/>試練のゆえつぶやき, 献身もゆらぐ。<br/>ゆえにおくれるのか？ 来たれや;<br/>忍たいしつづけるも, もう待ちきれぬ。<br/>',NULL,52664,5);
INSERT INTO stanza VALUES('J762','5','主よ,待ちくたびれて, ひさしい;<br/>なれ,来られないなら, われ,行かせよ。<br/>ながくなれの栄こう かくされ,<br/>こころなきものらは, 嘲笑している。<br/>',NULL,52665,6);
INSERT INTO stanza VALUES('J762','6','このこころのいたみ, うれいを,<br/>いやし得るものなし, なれ,いないゆえ。<br/>永えんの嗣業に入り, 満たさる,<br/>なが御かお見るとき, 苦難わすれる。<br/>',NULL,52666,7);
INSERT INTO stanza VALUES('J763','1','栄こうののぞみ, そはキリスト;<br/>わがれいすでに さいせいされ,<br/>いまたましいを つくり変えて,<br/>わがからださえ 栄光化す。<br/>',NULL,52667,1);
INSERT INTO stanza VALUES('J763','chorus','　　主は来て, えいこう化する！<br/>からだも主のよう へんぼうされる。<br/>からだも栄光化す主は, えいこうののぞみ。<br/>わがえいこう！<br/>',NULL,52668,2);
INSERT INTO stanza VALUES('J763','2','栄こうののぞみ, かみのおく義;<br/>かみのほう満に あずからせる。<br/>われらをかみと 混ざり合わせ,<br/>かみのえい光を　 得させる。<br/>',NULL,52669,3);
INSERT INTO stanza VALUES('J763','3','栄こうののぞみ, わがあがない;<br/>われのからだを 主はあがなう。<br/>栄光のかたちに へんぼうさせ,<br/>死を飲み尽くし, かい放す。<br/>',NULL,52670,4);
INSERT INTO stanza VALUES('J763','4','栄こうののぞみ, そはキリスト;<br/>かれ,わがいのち, わがけいけん,<br/>えいこう,自由に われ,もたらし,<br/>主といちとなる, えい遠に。<br/>',NULL,52671,5);
INSERT INTO stanza VALUES('J764','1','世々にかくされたおく義, そは栄光のキリスト;<br/>かみの実さい,かみの化身, またわがいのちなり！<br/>',NULL,52672,1);
INSERT INTO stanza VALUES('J764','chorus','うちにいますキリスト！ わが栄光,わがのぞみ！<br/>うちにあるこのおく義は, かの日,栄こうとなる！<br/>',NULL,52673,2);
INSERT INTO stanza VALUES('J764','2','わが霊のなかで再生され, いま，たましい変えらる;<br/>またからだも変えられて, かみのかたちとなる。<br/>',NULL,52674,3);
INSERT INTO stanza VALUES('J764','3','いのち,せいしつのなかで, かみとまったくひとつ;<br/>かみご自身をエンジョイしつつ, 主に似るものとなる。<br/>',NULL,52675,4);
INSERT INTO stanza VALUES('J765','1','わが主,さいらいのとき, われらうれい脱ぎ去り,<br/>聖徒ら主にしたがい行く, 主,賛美す！<br/>主,賛美す！主,賛美す！ 聖徒ら主にしたがい行く,主,賛美す！<br/>',NULL,52676,1);
INSERT INTO stanza VALUES('J765','2','したしく主にまみえて, 栄光のなかで主と住み,<br/>こころはかんせい上げ, 歓喜する！<br/>主,賛美す！主,賛美す！ こころはかんせい上げて,歓喜する！<br/>',NULL,52677,2);
INSERT INTO stanza VALUES('J765','3','主を御座にて見るとき, 十字架,苦つうではない,<br/>勝利のよろこびを得て, 主,賛美す！<br/>主,賛美す！主,賛美す！ しょう利のよろこびを得て,主,賛美す！<br/>',NULL,52678,3);
INSERT INTO stanza VALUES('J765','4','そのときわれあかしす, 主のいのちこそ勝利と,<br/>たずさえ上げられるは, よろこび！<br/>主,賛美す！主,賛美す！ たずさえ上げられるのはよろこび！<br/>',NULL,52679,4);
INSERT INTO stanza VALUES('J765','5','主のわきばらにかくれ, いちとなり,はなれない,<br/>主のこころ満たさるを, われねがう！<br/>主,賛美す！主,賛美す！ 主のこころ満たされるを,われねがう。<br/>',NULL,52680,5);
INSERT INTO stanza VALUES('J765','6','来たりませ,われの王よ！ なれ待つものに同在を,<br/>なれ愛すものに褒賞を あたえよ！<br/>主,賛美す！主,賛美す！ ながどうざいとほう賞をあたえよ！<br/>',NULL,52681,6);
INSERT INTO stanza VALUES('J766','1','栄光ののぞみ,主は来る！ われら上げられ栄化す;<br/>主の栄光にあずかれば, 最高の享受はああ,いかに。<br/>',NULL,52682,1);
INSERT INTO stanza VALUES('J766','chorus','　のぞみのキリスト, 栄光の主,来るとき,<br/>われら上げられ栄化す, のぞみの主,とく来ませ！<br/>',NULL,52683,2);
INSERT INTO stanza VALUES('J766','2','栄光ののぞみ,主は来る！ 旧創造脱ぎ,更新されて,<br/>ためいきなく,自由得る, 最高のすくい,ああ,いかに。<br/>',NULL,52684,3);
INSERT INTO stanza VALUES('J766','3','栄光ののぞみ,主は来る！ 王となり万民,支はいし,<br/>祭司とし主につかえる, 最高のめぐみ,ああ,いかに。<br/>',NULL,52685,4);
INSERT INTO stanza VALUES('J766','4','栄光ののぞみ,主は来る！ 目覚まし,忠信につかえ,<br/>明かりととのえ,はしる, 最高のすくい,ああ,いかに。<br/>栄化す――栄光化する<br/>',NULL,52686,5);
INSERT INTO stanza VALUES('J767','1','かみの子らのしゅつげんを, 被造ぶつ待っている,<br/>かみの子らの栄光の自由に はいることのぞんでいる。<br/>',NULL,52687,1);
INSERT INTO stanza VALUES('J767','2','被造ぶつみなうめきつつ, いま虚無にふくす,<br/>朽ち果てる奴隷状たいから かい放されることのぞむ。<br/>',NULL,52688,2);
INSERT INTO stanza VALUES('J767','3','われらもまたうめきつつ, 子たる身分のぞむ;<br/>キリストの身のたけである えんじゅくにいたるをねがう。<br/>',NULL,52689,3);
INSERT INTO stanza VALUES('J767','4','そのれい,わがためうめき, わがためとりなす;<br/>すべてのこと,えきとなして, 御子のかたちに同形化す。<br/>',NULL,52690,4);
INSERT INTO stanza VALUES('J767','5','栄光のなかへもたらされ, われらをえい化す;<br/>まったくかみにしんとうされ, 聖なる新そうぞうとなる。<br/>',NULL,52691,5);
INSERT INTO stanza VALUES('J767','6','全被造ぶつは解放されて, 栄光の自由に入る;<br/>子やぎは豹とともに伏して, 獅子はうしのようわら食う。<br/>',NULL,52692,6);
INSERT INTO stanza VALUES('J767','7','子たる身分を受け継いで, 主ともに嗣業受く;<br/>主のきょう弟としえい化され, わが身から栄光あらわす。<br/>',NULL,52693,7);
INSERT INTO stanza VALUES('J768','1','かみの中心思想, ひととの合ぺい,<br/>すべてとなりて, けいかく成就す。<br/>',NULL,52694,1);
INSERT INTO stanza VALUES('J768','2','ひとはうつわで, 三部分から成り,<br/>かみ,いのちとし, かみとひとつぞ。<br/>',NULL,52695,2);
INSERT INTO stanza VALUES('J768','3','いのちのながれ, 宝せきに変える;<br/>み住まいとなり, えい光あらわす。<br/>',NULL,52696,3);
INSERT INTO stanza VALUES('J768','4','かみのみやこは, かみのもくてき;<br/>御むねは成就す, そは新エルサレﾑ。<br/>',NULL,52697,4);
INSERT INTO stanza VALUES('J768','5','聖徒らの建ぞう, かみ,ひとの調和;<br/>かみとひととの ひつ要を満たす。<br/>',NULL,52698,5);
INSERT INTO stanza VALUES('J768','6','かみ,小ひつじの 御座の中心より,<br/>いのちのかわは, みやこ,ながれる。<br/>',NULL,52699,6);
INSERT INTO stanza VALUES('J768','7','主はいのちの木, かわのきし辺で,<br/>神聖な実むすび, しょくもつ供給す。<br/>',NULL,52700,7);
INSERT INTO stanza VALUES('J768','8','キリストにある ひかりなるかみ,<br/>みやこを照らし, よるを追い出す。<br/>',NULL,52701,8);
INSERT INTO stanza VALUES('J768','9','かみ,ひとにあり, ひと,かみにあり,<br/>かみ,ひとの内容, ひと,かみの表現。<br/>',NULL,52702,9);
INSERT INTO stanza VALUES('J769','1','ひととの合併, 主のねがい,<br/>ひと,うつわとし, 主がはいる;<br/>いのちとなり, ひとを満たして,<br/>主といちとならせ, 主を表現す。<br/>',NULL,52703,1);
INSERT INTO stanza VALUES('J769','2','主のかたちに ひとつくり,<br/>かれのねがいを 成就させる;<br/>いのちの木を 受け入れさせて,<br/>つまとならせ,主の 豊満とする。<br/>',NULL,52704,2);
INSERT INTO stanza VALUES('J769','3','ひと,ながれの なかにあり,<br/>主のかたちへと 変えられる。<br/>主の住まいに けんぞうされて,<br/>主のはん侶となり, 主は享受す。<br/>',NULL,52705,3);
INSERT INTO stanza VALUES('J769','4','そはえい光の 新エルサレﾑ,<br/>かみ,ひと調和し, ともに住む。<br/>かみはない容, われらはひょう現,<br/>えい光をきょう受し, 栄光となる。<br/>',NULL,52706,4);
INSERT INTO stanza VALUES('J769','5','かみは中しん, 御座にある;<br/>いのちの権威で 聖徒はいち。<br/>照らしにより, ひかりに生きて,<br/>たがいに調和して, 主を表現す。<br/>',NULL,52707,5);
INSERT INTO stanza VALUES('J769','6','主はしょくもつ, 生けるみず,<br/>飢えとかわきを みな満たす。<br/>せいなるみや, 主のなかに生き,<br/>みひかりのなかで 礼はいする。<br/>',NULL,52708,6);
INSERT INTO stanza VALUES('J770','1','主よ,新エルサレムは,<br/>主のけん造,またわれのもの;<br/>あがなわれた聖徒たちは,<br/>権威を得て,もんにはいる。<br/>われはそのえい光したう,<br/>主がそのなかに住むゆえ,<br/>たとえそれがとおくても,<br/>ひとりでに,それをおもう。<br/>',NULL,52709,1);
INSERT INTO stanza VALUES('J770','2','エルサレムおもうたび,<br/>せつになれの御かおしたう;<br/>主よ,はやくたずさえ上げ,<br/>なれのみそばにおらせよ。<br/>なれをあいすもの,ともに,<br/>新地でなれをあいさせよ。<br/>無限の主のあいをうたい,<br/>記ねんして,ほめたたえる。<br/>',NULL,52710,2);
INSERT INTO stanza VALUES('J770','3','よろこび,したうのは,<br/>めのう,へきぎょく,純きんでなく,<br/>われをあいした主ご自身！<br/>こころうばうあいの主よ！<br/>わがねがいじょう就しませ,<br/>はやくわれ引き上げられ,<br/>永遠になれとともに住み,<br/>御かお見て,みこえを聞く。<br/>',NULL,52711,3);
INSERT INTO stanza VALUES('J770','4','新エルサレム,わがうた,<br/>主はちゅうしん,ほうしょうゆえ;<br/>主とみすがたがあったゆえ,<br/>エルサレムはわがのぞみ！<br/>主あって万ぶつ更しんされ,<br/>なげき,なみだも過ぎ去り,<br/>安そくとよろこびは満つ,<br/>主よ,はやく来たりませや！<br/>',NULL,52712,4);
INSERT INTO stanza VALUES('J771','1','みやこをのぞみ,まく屋に住み,<br/>てんのみやこを目ざし,すすむ;<br/>地上のえい華をもとめないで,<br/>かみのやくそく,信じてすすむ。<br/>',NULL,52713,1);
INSERT INTO stanza VALUES('J771','chorus','栄光のみやこ！<br/>かみとひと住む新エルサレム！<br/>',NULL,52714,2);
INSERT INTO stanza VALUES('J771','2','かみの住まいのみやこのぞみ,<br/>地じょうの住まいもとめもしない;<br/>天のふるさとを享受するのは,<br/>「忠信なたびびと」だと主かたる。<br/>',NULL,52715,3);
INSERT INTO stanza VALUES('J771','3','みやこをのぞむ,たび路けわしい,<br/>ためいき,苦のう,損しつあれど,<br/>みやこおもえば,うたあふれる,<br/>みちまがれども,たび路わずか。<br/>',NULL,52716,4);
INSERT INTO stanza VALUES('J771','4','われらはともにみやこのぞむ:<br/>われらみやこでとわのはん侶,<br/>かみのそなえをわれら享受し,<br/>たびびととして,地上をあゆむ。<br/>',NULL,52717,5);
INSERT INTO stanza VALUES('J772','1','わがめあて,せいなるみやこ, その栄光に,われあずかる;<br/>わが身なおここにあれど, れいはすでにかしこにあり,<br/>主とともに立つをわれねがう。<br/>',NULL,52718,1);
INSERT INTO stanza VALUES('J772','2','聖なるゴ-ル,しんエルサレム, ひとのため,かみそなえる;<br/>血によりてあがなわれた, せい徒らすべてけん利ある,<br/>このしゅくふくのみーやこに。<br/>',NULL,52719,2);
INSERT INTO stanza VALUES('J772','3','かのみやこ,あおぎてねがう: 主のかおのかがやきを見,<br/>主のまねく呼びごえ聞き, かのみやこにすすみはいり,<br/>主のほう富をきょう受すこと。<br/>',NULL,52720,3);
INSERT INTO stanza VALUES('J772','4','あんそくやしゅくふくでなく, われもとむ,主ご自しんを;<br/>えいこうののぞみなる主, かれはわれの受くべきぶん,<br/>永遠にわがほうしょうとなる。<br/>',NULL,52721,4);
INSERT INTO stanza VALUES('J772','5','主よ,なれをあいするものを, ながもとにいたらせよや;<br/>みやこにて主をきょう受し, ともにえいこうにあずかり,<br/>永えんに主とともに住まう。<br/>',NULL,52722,5);
INSERT INTO stanza VALUES('J772','6','かの日にはすべてのものが, なれによりこうしんされ,<br/>えいこうのかみご自身は, とわにわれらのぶんとなる。<br/>主よ,はやく来たりたまえや！<br/>',NULL,52723,6);
INSERT INTO stanza VALUES('J773','1','はしるべきみちを はしり尽くして,<br/>たたかいぬき天にはいる;<br/>死にわたさるともしん仰をまもり, かみの褒賞を得ん。<br/>',NULL,52724,1);
INSERT INTO stanza VALUES('J773','chorus','われ引き上げられ, 主とともに住まん;<br/>新エルサレム,新エルサレム！<br/>新エルサレムにて御名をばさけばん, 勝利者はともに！<br/>',NULL,52725,2);
INSERT INTO stanza VALUES('J773','2','この世でたびびと, 苦なんおそれず,<br/>間もなくふるさとに入らん;<br/>ともは世あいせど,われ日々きよき しろをばあおがん。<br/>',NULL,52726,3);
INSERT INTO stanza VALUES('J773','3','けわしき世のみち, つかれ果てても,<br/>しろおもえばちからあり;<br/>しろそなえあれば,なみだ絶えぬも,われしつ望せじ。<br/>',NULL,52727,4);
INSERT INTO stanza VALUES('J773','4','くうを打つような たたかいせずに,<br/>御こころにしたがいゆく,<br/>うしろをわすれて,まえに向かいつ, しろの栄光を得ん。<br/>しろに住みうるは, 主のあい,めぐみ,<br/>新エルサレム,新エルサレム！<br/>せい徒ら和して,主の御名をうたわん, ああ新エルサレム！<br/>',NULL,52728,5);
INSERT INTO stanza VALUES('J774','1','はじめに,ひとつのその, 最後には,みやことなる;<br/>そのは,かみのそうぞう, みやこは,かみの建ぞう。<br/>',NULL,52729,1);
INSERT INTO stanza VALUES('J774','2','そのとみやこ,いずれも, かわといのちの木ある;<br/>かわは聖れいのながれ, 木はキリストの供きゅう。<br/>',NULL,52730,2);
INSERT INTO stanza VALUES('J774','3','そのとみやこ,いずれも, 三種るいのものがある:<br/>きん,しん珠,ほうせきは, すべてけんぞうのため。<br/>',NULL,52731,3);
INSERT INTO stanza VALUES('J774','4','そのにあるものはみな, 散らばっているざい料,<br/>みやこでは建ぞうされ, かみのみ住まいとなる。<br/>',NULL,52732,4);
INSERT INTO stanza VALUES('J774','5','そので,ひとはつちくれ, 地にぞくし,えい光なし;<br/>いのちの木そとにあり, いのちとなっていない。<br/>',NULL,52733,5);
INSERT INTO stanza VALUES('J774','6','みやこで,いのちの木は, ひとのうちがわに生き,<br/>だんたいのひとに住む, そはいのちのはたらき。<br/>',NULL,52734,6);
INSERT INTO stanza VALUES('J774','7','このみやことなるため, 再せいされ,へん化して,<br/>金,しん珠,宝せきとなり, からだとして主に似る。<br/>',NULL,52735,7);
INSERT INTO stanza VALUES('J774','8','そのにははなよめあり, アダムより出たはん侶;<br/>かのみやこははなよめ, キリストの豊満となる。<br/>',NULL,52736,8);
INSERT INTO stanza VALUES('J774','9','このみやこ,せい徒らの 組み合わせ,霊のちょう和;<br/>かみの安そくの住まい, 主の満ぞくのはなよめ。<br/>',NULL,52737,9);
INSERT INTO stanza VALUES('J774','10','かみの表現,そのほう満, 宇ちゅうてきなだんたい;<br/>三いちのかみのえい光, 配ぐう者,究きょくの栄光。<br/>',NULL,52738,10);
INSERT INTO stanza VALUES('J775','1','主はからだ,はなよめをあがないて,<br/>主のゆたか満たし,主をひょうげんす。<br/>主はしょう会のすべて,しょうかいは主述べ,<br/>主がしみわたり,また主とえい光分かつ。<br/>',NULL,52739,1);
INSERT INTO stanza VALUES('J775','chorus','見よ,主のしろ！えい光に満つ！<br/>そはまったきかみのひょう現なり。<br/>',NULL,52740,2);
INSERT INTO stanza VALUES('J775','2','かみとひとが混ざり合うはおく義;<br/>ひとが栄光に満つかみをやどすは,<br/>かみのゆたかしめす宇ちゅうのうつわぞ;<br/>きよさと混ざりつつ,うるわしさ表現す。<br/>',NULL,52741,3);
INSERT INTO stanza VALUES('J775','3','変えられしたみの生けるたい系は，<br/>しん珠や宝せきのとうときがごと。<br/>かみのみかたちへとかたちづくられる;<br/>ちゅう心なる御座より生けるみずながる。<br/>',NULL,52742,4);
INSERT INTO stanza VALUES('J775','chorus','キリストなるいのちの木は,<br/>ゆたかにしん鮮な実をむすぶ。<br/>',NULL,52743,5);
INSERT INTO stanza VALUES('J775','4','せい金のしょくだい,あかりは主なり,<br/>主はかみのえい光,聖れいで照らす。<br/>ひとはかみに住みて,かみはひとに住む,<br/>これぞかみの永遠のけいかく,もくてき。<br/>',NULL,52744,6);
INSERT INTO stanza VALUES('J776','1','何という栄光,何という光明, ああ,神聖な新エルサレム！<br/>かみ,ひと住み合う, 小ひつじのはなよめ。<br/>',NULL,52745,1);
INSERT INTO stanza VALUES('J776','2','新旧やくのせい徒らは, かみの契やく受け継ぐ;<br/>ともに建てられる みやこの構せい要素。<br/>',NULL,52746,2);
INSERT INTO stanza VALUES('J776','3','みやこは立ぽうたいで, たて,よこ,たかさ,おなじ;<br/>あまることもなく, 欠けることなどない。<br/>',NULL,52747,3);
INSERT INTO stanza VALUES('J776','4','純金の通りのみやこは, ガラスのようとうめい;<br/>かみの超えつした いのち性しつしめす。<br/>',NULL,52748,4);
INSERT INTO stanza VALUES('J776','5','十二の門はみなしん珠, そは,ひとが再せいされ,<br/>真珠に変えられて, その門にはいるため。<br/>',NULL,52749,5);
INSERT INTO stanza VALUES('J776','6','城へきの十二の土だい, 十二の宝せきでかざる;<br/>高温高あつにより, えい遠の価値を持つ。<br/>',NULL,52750,6);
INSERT INTO stanza VALUES('J776','7','へきぎょくのじょうへきは, すいしょうのようとうめい;<br/>主の栄光そこから かがやき,あらわれる。<br/>',NULL,52751,7);
INSERT INTO stanza VALUES('J776','8','城へき,けがれを分離し, 不透明なもの取り去る;<br/>みやこにあるのは, きん,真珠,宝せきのみ。<br/>',NULL,52752,8);
INSERT INTO stanza VALUES('J776','9','かみと小ひつじはみや！ 栄光なる御かおはいす;<br/>主の臨在のなかで, とこしえに礼はいす。<br/>',NULL,52753,9);
INSERT INTO stanza VALUES('J776','10','かみの栄光のひかりで, 太陽もつきもいらない;<br/>小ひつじのあかり, みやこ全体を照らす。<br/>',NULL,52754,10);
INSERT INTO stanza VALUES('J776','11','御座よりいのちのかわ, 通りの中央をながれる;<br/>きし辺の両がわに, いのちの木はしげる。<br/>',NULL,52755,11);
INSERT INTO stanza VALUES('J776','12','いのちのみずのながれ, かみの権威をもたらし,<br/>みやこをながれて, いのちを供きゅうする。<br/>',NULL,52756,12);
INSERT INTO stanza VALUES('J776','13','みやこは金,真珠,宝せき, 神性が大どおりとなり,<br/>供給のかわ,ながれ, その糧しょくはゆたか。<br/>',NULL,52757,13);
INSERT INTO stanza VALUES('J776','14','十二は行せいを意味し, 永遠の完全をも意味す;<br/>三,四を掛けたもの, かみ,ひとのまざり合い。<br/>',NULL,52758,14);
INSERT INTO stanza VALUES('J776','15','やみと死はもはやなく, かなしみ,いたみは去る;<br/>すべてはあたらしい, かみ,ひと,ともに住む。<br/>',NULL,52759,15);
INSERT INTO stanza VALUES('J776','16','みやこはかみのかたち, 王の権威もて支はいす;<br/>ごけいかく成就し, みこころを成就する。<br/>',NULL,52760,16);
INSERT INTO stanza VALUES('J777','1','しん天しん地に しんエルサレム;<br/>かみより生まれ, かがやき満つ。<br/>',NULL,52761,1);
INSERT INTO stanza VALUES('J777','chorus','主のかたちあり, えい光に満ちる;<br/>ともにおうとなる かみのみやこ！<br/>',NULL,52762,2);
INSERT INTO stanza VALUES('J777','2','みやこのみちは, とう明な精金;<br/>土だいは宝せき, じょう門は真珠。<br/>',NULL,52763,3);
INSERT INTO stanza VALUES('J777','3','とう明なみちに かわはながれ,<br/>いのちの木あり, ひつ要満たす。<br/>',NULL,52764,4);
INSERT INTO stanza VALUES('J777','4','ひかりのみやこ, かみはすべて;<br/>小ひつじにあり, とわにひかる。<br/>',NULL,52765,5);
INSERT INTO stanza VALUES('J778','1','旧新やくのたみに ふたつの面がある:<br/>かみの愛するはなよめ, またかみの住まい。<br/>',NULL,52766,1);
INSERT INTO stanza VALUES('J778','2','旧やくにある予表, おんなと建造による;<br/>こころにかなうはん侶, 住まいなるけん造。<br/>',NULL,52767,2);
INSERT INTO stanza VALUES('J778','3','イスラエルのたみ, かみはつまと呼ぶ;<br/>そこにみ住まいのみや, かみのみやこある。<br/>',NULL,52768,3);
INSERT INTO stanza VALUES('J778','4','神じんのキリスト, はなよめをめとる;<br/>再せいされたはなよめ, 主の満ぞくとなる。<br/>',NULL,52769,4);
INSERT INTO stanza VALUES('J778','5','復かつのキリスト, みやをけん造する,<br/>かみに安そくを得させ, みこころじょう就す。<br/>',NULL,52770,5);
INSERT INTO stanza VALUES('J778','6','召かい,主の配偶者, 主のほう満となる;<br/>召かいはかみの住まい, かみをひょう現する。<br/>',NULL,52771,6);
INSERT INTO stanza VALUES('J778','7','将らい新エルサレム, はなよめ,また建造;<br/>予ひょう,完全にじょう就し, かみを満ぞくさす。<br/>',NULL,52772,7);
INSERT INTO stanza VALUES('J778','8','それは主の配偶者, 主のほう満となる;<br/>かみの住まいとなって, おう権,こう使する。<br/>',NULL,52773,8);
INSERT INTO stanza VALUES('J778','9','ひとに見るみわざ, 究きょくのかんせい;<br/>ひとにて主をひょう現す, えい遠なるほう満。<br/>',NULL,52774,9);
INSERT INTO stanza VALUES('J779','1','キリスト,かしらに 万ぶつつり上げ,<br/>いちへと帰するは, かみのエコノミｰ。<br/>',NULL,52775,1);
INSERT INTO stanza VALUES('J779','2','かみとキリストは ともに座に着き,<br/>こころのねがいが ひょうげんされる。<br/>',NULL,52776,2);
INSERT INTO stanza VALUES('J779','3','いのちの主は内容, 聖徒らはうつわ;<br/>万ぶつをつり上げ, 栄光をひょう現す。<br/>',NULL,52777,3);
INSERT INTO stanza VALUES('J779','4','サタン自身を注入し, 万ぶつ破かいす,<br/>腐はいをもたらし, ご計かく,はばむ。<br/>',NULL,52778,4);
INSERT INTO stanza VALUES('J779','5','主は来て,ご自身を 分与してすくう;<br/>死,やみのちからは, もはやおよばず。<br/>',NULL,52779,5);
INSERT INTO stanza VALUES('J779','6','万ぶつはかしらに つり上げられる;<br/>召会通し万ぶつは たいけいとなる。<br/>',NULL,52780,6);
INSERT INTO stanza VALUES('J779','7','キリストのもとで 万ぶつ存在する;<br/>召会通し,万ぶつは, つり上げられる。<br/>',NULL,52781,7);
INSERT INTO stanza VALUES('J779','8','主はかしら,中しん, からだかがやき,<br/>万ぶつは調和して, へい和をたもつ。<br/>',NULL,52782,8);
INSERT INTO stanza VALUES('J779','9','やみ,堕らくはなし, 死も空虚もなし;<br/>万ぶつ,なわめより とわに解放さる。<br/>',NULL,52783,9);
INSERT INTO stanza VALUES('J780','1','かの日たからは かくされない,<br/>さまたげもなく, 主,かがやき出る。<br/>',NULL,52784,1);
INSERT INTO stanza VALUES('J780','2','きんのうつわは, 栄光を照らす;<br/>かみ,そのひかり, たい陽いらない。<br/>',NULL,52785,2);
INSERT INTO stanza VALUES('J780','3','金,真珠,ほうせき, かみの美,満つ;<br/>へきぎょくのように 栄光はかがやく。<br/>',NULL,52786,3);
INSERT INTO stanza VALUES('J780','4','うつわのなかで 栄光かがやく,<br/>地はひかり満ち, くらやみはなし。<br/>',NULL,52787,4);
INSERT INTO stanza VALUES('J780','5','かみのひかりを 新創造は見る；<br/>かがやくうつわ, 小ひつじの新婦。<br/>',NULL,52788,5);
INSERT INTO stanza VALUES('J780','6','金のうつわ見て, かみを拝する；<br/>小ひつじにあり, かみ,あらわれる。<br/>',NULL,52789,6);
INSERT INTO stanza VALUES('G1001','1','Der „ICH BIN“, Herr, ist Dein Name,<br/>Name kostbar, reich in Fülle,<br/>Allumfassend, voller Treue –<br/>Was uns Not, bist Du!<br/>',NULL,52790,1);
INSERT INTO stanza VALUES('G1001','2','Du der Sohn, der Vater in Dir;<br/>Als der Geist wohnst Du nun in mir,<br/>Dass den Reichtum Deiner Selbst wir<br/>Nunmehr voll erfahrn.<br/>',NULL,52791,2);
INSERT INTO stanza VALUES('G1001','3','Du der Tempel – Gottes Wohnung,<br/>Seines Lebens die Erklärung;<br/>Bist in uns der Freude Krönung,<br/>Sein Gesicht sehn wir.<br/>',NULL,52792,3);
INSERT INTO stanza VALUES('G1001','4','Du der Bräutigam, das Lamm bist,<br/>Für die Braut der Sünde Tod littst,<br/>Du am Kreuz an unsrer Statt trittst,<br/>Und so ruhen wir.<br/>',NULL,52793,4);
INSERT INTO stanza VALUES('G1001','5','Du bist Weisheit und der Weg, Herr,<br/>Jeden Tag des Lebens planst, Herr,<br/>Uns mit Gnade Du versorgst, Herr,<br/>Deinen Pfad gehn wir.<br/>',NULL,52794,5);
INSERT INTO stanza VALUES('G1001','6','Du bist rein, gerecht und heilig,<br/>Gottes Herzen wohlgefällig,<br/>Und der Harmonie teilhaftig<br/>Sind wir nun mit Gott.<br/>',NULL,52795,6);
INSERT INTO stanza VALUES('G1001','7','Du bist Leben, Du bist Licht, Herr,<br/>Tod verschlangst, und Nacht vertriebest,<br/>Du belebst und schenkst uns Sicht, Herr,<br/>So sind wir nun frei.<br/>',NULL,52796,7);
INSERT INTO stanza VALUES('G1001','8','Du, die Kraft der Auferstehung,<br/>Hast die Höllenmacht bezwungen;<br/>Deine Macht ist unsre Stärkung,<br/>So regieren wir.<br/>',NULL,52797,8);
INSERT INTO stanza VALUES('G1001','9','Du bist unser Lebenswasser,<br/>Unsre Speise bist Du Selbst, Herr,<br/>Ja, es mangelt uns an nichts mehr,<br/>Unser Fest bist Du.<br/>',NULL,52798,9);
INSERT INTO stanza VALUES('G1001','10','Du bist Hirte, Du bist Arzt heut,<br/>Du trugst alle unsre Krankheit,<br/>Trost und Schutz ist Deine Arbeit,<br/>So sorgst Du für uns.<br/>',NULL,52799,10);
INSERT INTO stanza VALUES('G1001','11','Priester, König bist Du ewig,<br/>Brachtest uns in Gott, wie herrlich!<br/>Deiner Vollmacht nun teilhaftig,<br/>Welch ein Ehrenplatz!<br/>',NULL,52800,11);
INSERT INTO stanza VALUES('G1001','12','Du bist Hoffnung und Erlösung,<br/>Uns verklärst die alte Schöpfung,<br/>Machst von Dir eine Verdopplung,<br/>Die Dein Ausdruck ist.<br/>',NULL,52801,12);
INSERT INTO stanza VALUES('G1001','13','Du bist Freude, Friede, Ehre,<br/>Wahrheit, Lebensbaum und Gnade,<br/>Bau und Berg und Schild und Sonne,<br/>Und noch vieles mehr.<br/>',NULL,52802,13);
INSERT INTO stanza VALUES('G1001','14','Herr, Dein Wesen – ohne Grenzen,<br/>Unausschöpflich, reich, vollkommen –<br/>Übertrifft was uns vonnöten,<br/>Überfließt von uns.<br/>',NULL,52803,14);
INSERT INTO stanza VALUES('G1002','1','O Halleluja! Welchen Tod<br/>Starb Christus an dem Kreuz!<br/>Doch starb dort nicht der Herr allein:<br/>Auch alles, was der Tod schloss ein –<br/>Gott war da noch dazu,<br/>All Menschen, ich und du,<br/>O Halleluja für dieses Kreuz!<br/>',NULL,52804,1);
INSERT INTO stanza VALUES('G1002','2','Oh, lobt den Herrn! Mensch starb in Gott,<br/>Zu einem Ende kam!<br/>Von diesem Menschen bin ich frei,<br/>Denn Gott beendet mich dabei!<br/>O wunderbarer Tod!<br/>O wunderbarer Tod!<br/>O Halleluja für diesen Tod!<br/>',NULL,52805,2);
INSERT INTO stanza VALUES('G1002','3','Oh, lobt den Herrn! Gott starb im Mensch<br/>Und wurde freigesetzt!<br/>Es fiel zur Erd ein Weizenkorn,<br/>Und viele sind nun neugeborn,<br/>Mit Gottes Leben voll,<br/>Mit Gottes Leben voll,<br/>O Halleluja für Leben frei!<br/>',NULL,52806,3);
INSERT INTO stanza VALUES('G1002','4','Lob sei Dir, Herr, für Deinen Tod,<br/>Für Dein vollkomm’nes Kreuz!<br/>Des Weltalls Mittelpunkt ist wert,<br/>Dass sein Verdienst wird laut erklärt!<br/>Wie lieben wir Dein Kreuz!<br/>Wie lieben wir Dein Kreuz!<br/>O Halleluja für dieses Kreuz!<br/>',NULL,52807,4);
INSERT INTO stanza VALUES('G1003','1','Hoch über alle, das Lamm auf dem Thron,<br/>Retter der Sünder, ist Er jetzt gekrönt;<br/>Lebend stets, sorgt Er Sich um unsren Fall,<br/>Von Gott erhoben, sehr hoch über allm.<br/>',NULL,52808,1);
INSERT INTO stanza VALUES('G1003','chorus','Hoch über allm! Hoch über allm!<br/>Jesus gekreuzigt ist hoch über allm!<br/>Von Seinen Gliedern ertönt laut der Schall,<br/>Von Gott erhoben, sehr hoch über allm.<br/>',NULL,52809,2);
INSERT INTO stanza VALUES('G1003','2','Schlagen die Sturmwellen ein, voller Wut,<br/>Rufen wir, kommt Er und rettet in Not;<br/>Schauend auf Jesus, uns schützt Seine Hand,<br/>Gehen auf Wogen, so sicher wie Land.<br/>',NULL,52810,3);
INSERT INTO stanza VALUES('G1003','3','Hoch sind die Städte, die trotzen Gewalt,<br/>Stark sind die Schranken, die bieten uns Halt;<br/>Preschen wir vor, und sie bringen zu Fall,<br/>Sie sind besiegt durch Ihn, hoch über allm.<br/>',NULL,52811,4);
INSERT INTO stanza VALUES('G1003','4','Über den Globus herrscht Er weit und breit,<br/>Hoch über alle nun durch alle Zeit;<br/>Sieger regiern mit Ihm über das All,<br/>Die Ihm treu nachfolgten, hoch über allm.<br/>',NULL,52812,5);
INSERT INTO stanza VALUES('G1004','1','Herr, wir wissen, Du bist bei uns,<br/>Hier an Deinem reichen Tisch,<br/>Unter Deinem Banner sitzend,<br/>An dem Mahl so vortrefflich.<br/>Teure Augenblicke diese,<br/>Von all Furcht und Zweifel frei,<br/>Wir genießen süße Ruhe,<br/>Und betrachten Dich allein.<br/>',NULL,52813,1);
INSERT INTO stanza VALUES('G1004','2','Freudig hier in Deiner Nähe,<br/>Gern geführt von Deinem Geist;<br/>Still, gesegnet – das Gedächtnis<br/>Deines Bluts, vergossen einst.<br/>Herr, wir nehmen jedes Zeichen<br/>Im Gedenken zart an Dich.<br/>Dein’n geschund’nen Leib besinnen,<br/>Wie Dein Blut das Kreuz bestrich.<br/>',NULL,52814,2);
INSERT INTO stanza VALUES('G1004','3','O welch Freude, Dich zu sehen<br/>Hier in beiderlei Symbol,<br/>In dem Brot und Wein des Segens –<br/>Brot soll stärken, Wein macht froh!<br/>Schau, auf uns, Herr, nun versammelt,<br/>Hier in uns’rem Haupt vereint.<br/>Nehmen wir den Kelch des Segens,<br/>Das gebroch’ne Brot verteiln.<br/>',NULL,52815,3);
INSERT INTO stanza VALUES('G1004','4','Herr, wie treu ist Dein Versprechen,<br/>Dass Du dort bei uns stets bist,<br/>Wo wir uns beisammenfinden<br/>Für Gemeinschaft froh und süß!<br/>Lieber noch hegt jedes Herz doch<br/>Die Verheißung inniglich,<br/>Dass wir bald dann schon bei Dir sind,<br/>Ja, wo Du bist „ewiglich“.<br/>',NULL,52816,4);
INSERT INTO stanza VALUES('G1005','1','O Festmahl – göttlich, süß!<br/>Die Gnade macht uns frei,<br/>Im Angedenken, Herr, an Dich,<br/>Zu diesem Brot und Wein.<br/>',NULL,52817,1);
INSERT INTO stanza VALUES('G1005','2','Hier wartet jeder Gast,<br/>Um, Herr, von Dir zu hörn,<br/>Was Du von Deinem Vater hast,<br/>Und Deine Gnad zu spür’n.<br/>',NULL,52818,2);
INSERT INTO stanza VALUES('G1005','3','Gewissen findet Ruh,<br/>So wie der Glaube prüft<br/>Die Süßigkeit des Lebensbrots<br/>Und Deiner Liebe Füll.<br/>',NULL,52819,3);
INSERT INTO stanza VALUES('G1005','4','Dass Blut für Sünde floss,<br/>Im Bild hier sehen wir,<br/>Und spüren die Gewähr in uns:<br/>Wir sind geliebt von Dir.<br/>',NULL,52820,4);
INSERT INTO stanza VALUES('G1005','5','Ist dieser Liebesblick<br/>So göttlich süß und zart,<br/>Wie wird’s denn sein, wenn Dein Gesicht<br/>Uns dann entgegenstrahlt!<br/>',NULL,52821,5);
INSERT INTO stanza VALUES('G1005','6','Dein Angesicht betrachtend,<br/>Dein Gleichnis tragend, Herr,<br/>Wir Deine Gnadenwege dann<br/>In Ewigkeit erklärn.<br/>',NULL,52822,6);
INSERT INTO stanza VALUES('G1006','1','Ewig hält mich Liebe fest,<br/>Durch die Gnade mir gewährt;<br/>Himmels-Atem hier, o Geist,<br/>Dies hast Du mich ja gelehrt.<br/>O wie voll der Friede ist!<br/>O wie göttlich ist’s allein!<br/>Diese Liebe schwindet nicht:<br/>Ich bin Dein und Du bist mein.<br/>',NULL,52823,1);
INSERT INTO stanza VALUES('G1006','2','Heller scheint der Himmel blau,<br/>Sanfter blickt die Erde grün,<br/>Etwas schillert, was das Aug<br/>Ohne Christus nie gesehn.<br/>Blumen strahlen bunter da,<br/>Schöner stimmen Vögel ein,<br/>Seit ich weiß, wie ich nun weiß:<br/>Ich bin Dein und Du bist mein.<br/>',NULL,52824,2);
INSERT INTO stanza VALUES('G1006','3','Einst mich plagte manch Alarm,<br/>Jetzt den Frieden nichts verschlägt,<br/>Ewig fest in Seinem Arm,<br/>In der Liebe Schoß umhegt.<br/>O, ich läge ewig hier,<br/>Angst und Zweifel lass ich sein,<br/>Und ins Ohr verspricht Er mir:<br/>Ich bin Sein und Er ist mein.<br/>',NULL,52825,3);
INSERT INTO stanza VALUES('G1006','4','Ich bin Sein; ja, ewig Sein:<br/>Wer kann uns denn trennen jetzt?<br/>Ach, welch Ruhe nimmt mich ein,<br/>Mit der Christus füllt das Herz!<br/>Schwinden All und Erd dahin,<br/>Dämmern Himmelsleuchten ein,<br/>Dann, da Gott und ich noch sind,<br/>Bin ich Sein und Er ist mein.<br/>',NULL,52826,4);
INSERT INTO stanza VALUES('G1007','1','Freue dich nun mit mir!<br/>Da mein Herz elend war,<br/>Und ich entdeckte einen Hort<br/>Der Liebe unsagbar.<br/>',NULL,52827,1);
INSERT INTO stanza VALUES('G1007','2','Freue dich nun mit mir!<br/>Ich, einst verzagt und krank,<br/>Bin nun begegnet einem Arzt;<br/>Der nimmt Sich meiner an.<br/>',NULL,52828,2);
INSERT INTO stanza VALUES('G1007','3','Freue dich nun mit mir!<br/>Ich war geschunden sehr,<br/>Und nun mich trägt ein starker Arm;<br/>Der hält mich fest nunmehr.<br/>',NULL,52829,3);
INSERT INTO stanza VALUES('G1007','4','Freue dich nun mit mir!<br/>Arg schweifte ich einst aus,<br/>Und Einer brachte mich zurück,<br/>In Ihm zu sein, zuhaus.<br/>',NULL,52830,4);
INSERT INTO stanza VALUES('G1007','5','Freue dich nun mit mir!<br/>Denn ich fand einen Freund,<br/>Der meine Herzenstiefen kennt,<br/>Doch liebt mich ohne End.<br/>',NULL,52831,5);
INSERT INTO stanza VALUES('G1007','6','Sein Liebe war mir fremd,<br/>Lang hat Er auch geliebt,<br/>Liebe so standfest und so treu,<br/>So einfühlsam und tief.<br/>',NULL,52832,6);
INSERT INTO stanza VALUES('G1007','7','Und jetzt ist alles mein,<br/>Ich kenne Seine Stimm;<br/>Wie schöpfe ich denn jemals aus<br/>Die Freude hier an Ihm?<br/>',NULL,52833,7);
INSERT INTO stanza VALUES('G1008','1','Erlöst – O wie gern ich’s verkünde!<br/>Das Blut des Lamms hat mich erlöst;<br/>Vollkommen erlöst durch Erbarmen,<br/>Auf ewig Sein Kind bin ich jetzt.<br/>',NULL,52834,1);
INSERT INTO stanza VALUES('G1008','chorus','Erlöst, erlöst,<br/>Des Lammes Blut hat mich erlöst;<br/>Erlöst, erlöst,<br/>Auf ewig Sein Kind bin ich jetzt.<br/>',NULL,52835,2);
INSERT INTO stanza VALUES('G1008','2','Erlöst und so glücklich in Jesus,<br/>Entzückung, die Sprache verschlägt;<br/>Das Licht Seiner Gegenwart, weiß ich,<br/>Bleibt immer bei mir und mich hegt.<br/>',NULL,52836,3);
INSERT INTO stanza VALUES('G1008','3','Ich denke an meinen Erlöser,<br/>An Ihn nur den ganzen Tag lang;<br/>Ich singe, ich kann ja nicht schweigen,<br/>Mach’ aus Seiner Liebe Gesang.<br/>',NULL,52837,4);
INSERT INTO stanza VALUES('G1008','4','Bald werde ich sehen in Schönheit,<br/>Den König, nach dem es mich tracht’,<br/>Der stets meine Schritte behütet,<br/>Und Lieder mir gibt in der Nacht.<br/>',NULL,52838,5);
INSERT INTO stanza VALUES('G1009','1','Mein Retter, Du bist mein,<br/>Wie süß ist dies doch mir!<br/>Ich rufe Deinen Nam,<br/>Erheb mein Herz zu Dir!<br/>',NULL,52839,1);
INSERT INTO stanza VALUES('G1009','chorus','Mein! Mein! Mein!<br/>Ich weiß, Du bist mein;<br/>Retter, o Retter,<br/>Ich weiß, Du bist mein.<br/>',NULL,52840,2);
INSERT INTO stanza VALUES('G1009','2','Du bist des Sünders Freund,<br/>Ich nehm die Freundschaft an;<br/>Gerettet durch die Gnad,<br/>Als Deine Botschaft kam.<br/>',NULL,52841,3);
INSERT INTO stanza VALUES('G1009','3','Mein hartes Herz, gerührt,<br/>Hat Deiner Stimm gehorcht;<br/>Und Friede kam hinein<br/>Und Freude durch Dein Wort.<br/>',NULL,52842,4);
INSERT INTO stanza VALUES('G1009','4','So singe ich Dein Lob,<br/>So nenn ich Dich nun mein;<br/>Ich baue auf Dein Wort,<br/>Ich weiß, ja, ich bin Dein.<br/>',NULL,52843,5);
INSERT INTO stanza VALUES('G1010','1','Komm, Du Quelle jedes Segens,<br/>Stimm mein Herz auf Lobgesang!<br/>Gnadenströme, voll Erbarmen,<br/>Fordern Jubel laut und lang!<br/>Jesus suchte mich als Fremden,<br/>Als ich irrte weit von Gott;<br/>Meine Seelennot zu wenden,<br/>Schritt Er ein mit Seinem Blut.<br/>',NULL,52844,1);
INSERT INTO stanza VALUES('G1010','2','O wie viel der Gnade schuld ich,<br/>Wie sie täglich drängt mich sehr!<br/>Band der Gnade, nun umschling mich,<br/>Dass mein Herz nicht strauchle mehr.<br/>Lehr mich, Herr, ein Maß Entzückung,<br/>Das mich Gnad beweisen lässt;<br/>Schätze, über all Erzählung,<br/>Deiner Liebe sing ich jetzt.<br/>',NULL,52845,2);
INSERT INTO stanza VALUES('G1010','3','Öfters schweif ich, Herr; ich fühl es,<br/>Bin oft meinem Gott nicht treu;<br/>Nimm mein Herz, o nimm, versiegle’s<br/>Mit dem Geist von oben neu.<br/>Nun befreit von Not und Sünde,<br/>Durch des Retters Blut erwirkt,<br/>Mög ich wandeln als ein Fremder,<br/>Sohn und Erbe Gottes hier.<br/>',NULL,52846,3);
INSERT INTO stanza VALUES('G1011','1','Kühlen Trank aus einem Brunnen<br/>Hatt’ ich lebenslang begehrt,<br/>Der den Durst doch löschen sollte,<br/>Der mich innerlich verzehrt.<br/>',NULL,52847,1);
INSERT INTO stanza VALUES('G1011','chorus','Ja, ich habe Ihn gefunden,<br/>Nach dem suchte meine Seel!<br/>Jesus stillt all meine Sehnsucht,<br/>Und Sein Leben bringt mir Heil.<br/>',NULL,52848,2);
INSERT INTO stanza VALUES('G1011','2','Ich ernährte mich von Hülsen,<br/>Bis die Kraft mir beinah schwand,<br/>Meine Seele suchte Bess’res,<br/>Jedoch Hunger nur empfand.<br/>',NULL,52849,3);
INSERT INTO stanza VALUES('G1011','3','Ich war arm und suchte Reichtum,<br/>Dachte Friede wär’ mein Lohn,<br/>Doch der Staub, den ich gesammelt,<br/>Lachte meinem Klagen Hohn.<br/>',NULL,52850,4);
INSERT INTO stanza VALUES('G1011','4','Quell des Wassers immer sprudelnd,<br/>Brot des Lebens nährt mich hier;<br/>Reichtum, welcher nimmer ausgeht,<br/>So viel ist mein Retter mir.<br/>',NULL,52851,5);
INSERT INTO stanza VALUES('G1012','1','Welches fest Fundament uns zum Glauben gelegt,<br/>Sich, ihr Heiligen, in Seinem Wort niederschlägt!<br/>Was mehr kann Er dann sagen, dass Er nicht gesagt,<br/>Zu euch, die ihr um Zuflucht in Jesus euch bargt?<br/>',NULL,52852,1);
INSERT INTO stanza VALUES('G1012','2','„Fürchte nicht, Ich bin bei dir, verängstigt nicht sei,<br/>Denn Ich bin noch dein Gott und Ich stehe dir bei;<br/>Ich beschütze und stärk dich, verleihe dir Stand,<br/>Heil in Meiner gerechten, allmächtigen Hand.<br/>',NULL,52853,2);
INSERT INTO stanza VALUES('G1012','3','„Wenn Ich dich dann berufe, durch Tiefen zu gehn,<br/>Sollen Ströme der Trauer nicht über dir stehn;<br/>Denn Ich segne dich, wenn dich Bedrängnis bedroht,<br/>Und Ich heilige dir deine bitterste Not.<br/>',NULL,52854,3);
INSERT INTO stanza VALUES('G1012','4','„Wenn durch Proben von Feuer dich leitet dein Pfad,<br/>Werde Ich dich versorgen anhand Meiner Gnad;<br/>Denn die Flamme verletzt nicht, nur dies Mein Begehr:<br/>Dass dein Gold werd’ geläutert, dein Unrat verzehrt.<br/>',NULL,52855,4);
INSERT INTO stanza VALUES('G1012','5','„Immer noch soll Mein Volk, auch wenn schon hoch betagt,<br/>Prüfen, wie Meine Liebe, so fest, nie versagt;<br/>Und wenn weißes Haar ihnen die Schläfen verziert,<br/>Im Schoß trag Ich sie noch wie die Lämmer der Hirt.<br/>',NULL,52856,5);
INSERT INTO stanza VALUES('G1012','6','„Und die Seel, die um Ruhe an Jesus sich wend’t,<br/>Überlasse Ich niemals, nein, nie ihrem Feind;<br/>Will die Hölle die Seele erschüttern auch schwer,<br/>So verlass Ich sie nimmer, o nein, nimmermehr.“<br/>',NULL,52857,6);
INSERT INTO stanza VALUES('G1013','1','Ihm, der hat, noch mehr bescherest,<br/>Überfließend mehr schenkst Du;<br/>Herr, ich lebe, weil Du lebest,<br/>Drum sprich mir mehr Leben zu.<br/>Herr, bestärke mich im Lauf,<br/>Und in Gnade wachs ich auf.<br/>',NULL,52858,1);
INSERT INTO stanza VALUES('G1013','2','Stärke all Dein Werk, o Meister,<br/>Schlagen Wurzeln tief und fest;<br/>Bring die Früchte bloß zur Reife,<br/>Die Du mir gedeihen lässt.<br/>Schneide wildes Selbst bloß weg,<br/>Lass mich wachsen unentwegt.<br/>',NULL,52859,2);
INSERT INTO stanza VALUES('G1013','3','Lass die Sonne Wachstum stärken,<br/>Schenke Regen, frisch und reich;<br/>Jede Stunde soll verzeichnen:<br/>Wirklich machst Du mich Dir gleich,<br/>Dass Dein liebend Auge fass,<br/>Wie in Gnad ich täglich wachs.<br/>',NULL,52860,3);
INSERT INTO stanza VALUES('G1013','4','Gnade Deiner Füll entströmend,<br/>Führ mir Größeres noch vor;<br/>Adlerflügel mir verleihend,<br/>Lass mich steigen hoch empor.<br/>Durch Dein leuchtend Angesicht<br/>In der Gnade wachse ich.<br/>',NULL,52861,4);
INSERT INTO stanza VALUES('G1013','5','Deshalb lass mich ständig wachsen,<br/>Stehen nimmer, nimmer still,<br/>Hören, besser kennenlernen<br/>Dich und Dein’n vollkomm’nen Willn.<br/>Bis ich geh den Sieger-Pfad,<br/>Lass mich wachsen in der Gnad.<br/>(Die letzten beiden Zeilen wiederholen.)<br/>',NULL,52862,5);
INSERT INTO stanza VALUES('G1014','1','O Herr, nun heil’ge uns, füge Dich Selbst hinzu,<br/>In der Erfahrung, Herr, ja, Dich verbreit in uns,<br/>Mach die Gemeinde hier doch wirklich herrlich nun,<br/>Füg Dich hinzu, Herr, beten wir.<br/>O heil’ge uns doch heute, Herr,<br/>Wir brauchen Dich, Herr Jesus, mehr.<br/>Wir nehmen Dein’ Person,<br/>Breite Dich aus in uns,<br/>O heil’ge uns doch heute, Herr.<br/>',NULL,52863,1);
INSERT INTO stanza VALUES('G1014','2','O Herr, nun mach uns rein mit Deinem Lebenswort,<br/>Sprich doch Dein Wort in uns, wasch unsre Altheit fort,<br/>Vermehr Dein Sprechen, Herr, uns rundum reinige,<br/>O mach uns rein, Herr, beten wir.<br/>Herr, mach uns rein mit Deinem Wort,<br/>Wasch unser altes Leben fort.<br/>Dein Wort in uns doch sprich<br/>Und mache uns herrlich,<br/>Herr, sprich in uns doch nun Dein Wort.<br/>',NULL,52864,2);
INSERT INTO stanza VALUES('G1014','3','O Herr, ernähre uns, Du bist die Speis für uns,<br/>Wir nehmen Dich zu uns, dann wandelst Du uns um,<br/>Wir sind gesättigt, Herr, zufrieden rundherum,<br/>Daher ernähr uns, beten wir.<br/>O Herr, ernähre uns durchweg<br/>Und wasche unser Selbst ganz weg.<br/>Und nicht nur reinige,<br/>Dazu noch sättige,<br/>O Herr, ernähre uns durchweg.<br/>',NULL,52865,3);
INSERT INTO stanza VALUES('G1014','4','O Herr, umhege uns, während wir uns ernährn,<br/>Nimm Dich doch unsrer an und unser Herz erwärm,<br/>Ja, unsre Härten, Herr, erweiche und entfern,<br/>O Herr, umheg uns, beten wir.<br/>O Herr, umhege uns doch heut,<br/>Bis unsre Kälte aufgetaut,<br/>Ja, halt uns dicht an Dich<br/>Und heg uns inniglich,<br/>O Herr, umhege uns doch heut.<br/>',NULL,52866,4);
INSERT INTO stanza VALUES('G1014','5','O mach uns herrlich, Herr,<br/>Durch all Dein innres Werk,<br/>Nicht unsre Herrlichkeit, die der Gemeind vielmehr,<br/>Dass Du die Braut erlangst, die Du schon lang begehrt,<br/>O wirk an uns, Herr, beten wir.<br/>O wirke, Herr, an uns doch heut,<br/>Für der Gemeinde Herrlichkeit.<br/>Mach Dich in uns doch breit,<br/>Erfüll mit Herrlichkeit,<br/>O mach uns herrlich, Herr, doch heut.<br/>',NULL,52867,5);
INSERT INTO stanza VALUES('G1015','1','Ich bin des Herrn! O Freude unaussprechlich!<br/>O süße Antwort auf die Liebesstimm;<br/>„Ja“ ruft der Glaube auf Sein treues Flüstern:<br/>Ich muss nicht fürchten, ich gehöre Ihm.<br/>',NULL,52868,1);
INSERT INTO stanza VALUES('G1015','2','Ich bin des Herrn! So klingt das froh Bekenntnis,<br/>Mit dem die Braut den frohen Tag besinnt,<br/>Als Ihm die Liebe ihr Gelübde aussprach,<br/>Und Ehre und Gehorsam gab sich hin.<br/>',NULL,52869,2);
INSERT INTO stanza VALUES('G1015','3','Ich bin des Herrn! Mich lehr, was dies bedeutet<br/>Alles, was Liebe, Treue anbetrifft,<br/>Heiliger Dienst, und absolute Weihung,<br/>Was vorbehaltloser Gehorsam ist.<br/>',NULL,52870,3);
INSERT INTO stanza VALUES('G1015','4','Ich bin des Herrn! Ja, Geist samt Leib und Seele;<br/>Komm, nun versiegle alles völlig Dein;<br/>So, Liebster, in der Fülle Deiner Liebe<br/>Immer und ewiglich bist Du nun mein.<br/>',NULL,52871,4);
INSERT INTO stanza VALUES('G1016','1','Wir ruhn in Dir, Du unser Schild und Schützer,<br/>Dem Feind entgegen nicht alleine stehn,<br/>In Deiner Kraft, Du unser Unterstützer,<br/>Ruhn wir in Dir, in Deinem Namen gehn.<br/>',NULL,52872,1);
INSERT INTO stanza VALUES('G1016','2','In Deinem Namen, Herzog unsres Heiles,<br/>Ja, Deinem Namen, der sich uns verschrieb,<br/>Gerechtigkeit und unser fester Pfeiler,<br/>Der Fürst der Herrlichkeit und Herr der Lieb.<br/>',NULL,52873,2);
INSERT INTO stanza VALUES('G1016','3','Wir gehn im Glauben, unsre Schwachheit fühlen,<br/>In Gnade jeden Tag mehr müssen stehn,<br/>Doch klingt ein Siegeslied aus unseren Herzen,<br/>Wir ruhn in Dir, in Deinem Namen gehn.<br/>',NULL,52874,3);
INSERT INTO stanza VALUES('G1016','4','Wir ruhn in Dir, Du unser Schild und Schützer,<br/>Dein’ ist die Schlacht, und Dein das Lob wird sein,<br/>Und im Reich Deines Glanzes dann als Sieger<br/>Ruhn wir in Dir auf ewig und allein.<br/>',NULL,52875,4);
INSERT INTO stanza VALUES('G1017','1','Wie herrlich der König ist uns!<br/>Ihm dienen die Himmel als Thron;<br/>All’ Welten regiert Seine Macht,<br/>Ihm wird jedes Reich untertan.<br/>Er wohnt unten bei Seinem Volk,<br/>Nimmt Sich dessen Sorgen an gern;<br/>Beim König zum Werk wohnen wir,<br/>Gern teilen die Lasten des Herrn.<br/>',NULL,52876,1);
INSERT INTO stanza VALUES('G1017','2','Ich wohn mit dem König schon hier,<br/>Wo Er mit den Seinigen wohnt;<br/>Die Herzenstür machte ich auf,<br/>Dass darin als Tempel Er thront.<br/>Ich bleib wie Maria vor Ihm,<br/>Johannes gleich, auf Seiner Brust;<br/>Wo Er ist, sind Freuden so voll,<br/>Sein Schoß birgt unendlichen Trost.<br/>',NULL,52877,2);
INSERT INTO stanza VALUES('G1017','3','Beim König wohn ich für Sein Werk,<br/>An Seinem Plan habe ich teil,<br/>Zu bringen Sein Reich auf die Erd,<br/>Den Menschen verkünden Sein Heil.<br/>Die Welt hätte Werke genug,<br/>Mir sind sie nur eitler Verlust;<br/>Sein Auftrag beschäftigt mich nur,<br/>Allein meine Botschaft: Sein Kreuz.<br/>',NULL,52878,3);
INSERT INTO stanza VALUES('G1017','4','Beim König wohn ich für Sein Werk,<br/>Das Werk, Ihm gehört’s, und nicht mir;<br/>Er plant und bereitet es vor,<br/>Mir göttliche Kraft gibt dafür.<br/>Pflicht wird so verwandelt in Freud,<br/>Gebet wird zu Lob und Gesang;<br/>Beim König wohn ich für Sein Werk,<br/>Zum Werk Seine Stärke empfang.<br/>',NULL,52879,4);
INSERT INTO stanza VALUES('G1017','5','Beim König fürs Werk wohnen wir,<br/>Und wirken all Tage im Jahr,<br/>Vielleicht, eh es um ist, wird Er,<br/>Der König, erscheinen hier klar.<br/>Dann trägt Er uns Nobleres auf,<br/>Noch näher dann in Seinem Schoß;<br/>Beim König zum Werk werden wir<br/>Dann wohnen in Freud grenzenlos.<br/>',NULL,52880,5);
INSERT INTO stanza VALUES('G1018','1','Wir sind jetzt, wir sind jetzt schon bei Gottes Haus,<br/>Wir sind jetzt bei dem Haus, wo der Strom fließt aus;<br/>Von dem Ort immerfort fließt das Wasser stets,<br/>Das für uns die Lebensfrüchte wachsen lässt.<br/>',NULL,52881,1);
INSERT INTO stanza VALUES('G1018','2','Von dem Haus, von dem Haus Lebenswasser quillt,<br/>Von dem Haus fließt heraus, Durst der Erde stillt;<br/>Tiefer noch soll jedoch dieses Fließen sein,<br/>So kannst Du uns messen, nimmst uns völlig ein.<br/>',NULL,52882,2);
INSERT INTO stanza VALUES('G1018','3','Miss uns, Herr; miss uns, Herr; miss uns jeden Tag;<br/>Miss uns, Herr; miss uns mehr; was es kosten mag,<br/>Bis der Fluss werden muss eine starke Flut,<br/>Und die Erde überschwemmt für unsren Gott.<br/>',NULL,52883,3);
INSERT INTO stanza VALUES('G1018','4','Bring uns durch, bring uns durch, hoch die Wasser stehn,<br/>Bring uns durch, ganz hindurch, wohin wir auch gehn;<br/>Höher geht’s, steigend stets, bis in Dir wir schwimm’n,<br/>Bis wir in Gott bleiben, eingetaucht in Ihn.<br/>',NULL,52884,4);
INSERT INTO stanza VALUES('G1018','5','Alles lebt, alles lebt, wo der Strom auch fließt,<br/>Alles lebt, wirklich lebt, wo er sich ergießt;<br/>Fließen soll, übervoll, uns das Leben bringt,<br/>Bis der Erden Wüsten voll Gemeinden sind.<br/>',NULL,52885,5);
INSERT INTO stanza VALUES('G1019','1','Dich als Leib, Herr, zu erkennen,<br/>Ja, das muss ich dringend sehn;<br/>Dich in Deinen Gliedern blicken,<br/>Dem gilt mein Gebet und Flehn.<br/>Damit ich Dein Hauptsein kenne<br/>Nur für mich allein nicht mehr,<br/>Sondern Dich, jetzt Fleisch geworden,<br/>Als den Leib-Christus vielmehr.<br/>',NULL,52886,1);
INSERT INTO stanza VALUES('G1019','2','Durch die Jahre, wie die Heil’gen<br/>Sich nach Wirklichkeit gesehnt,<br/>Aufwärts schauend, drinnen forschend,<br/>Einen Blick von Dir zu sehn!<br/>Zeig mir nun: der Herr im Himmel<br/>Ist der Leib hier offenbar,<br/>Und dem Christus, der in uns wohnt,<br/>Stellt der Leib den Ausdruck dar.<br/>',NULL,52887,2);
INSERT INTO stanza VALUES('G1019','3','Leicht verleiten mich Gedanken,<br/>Sinnen voll Erhabenheit;<br/>Einfach ist’s fürs Selbst zu suchen<br/>Ganz vorbei an Wirklichkeit.<br/>Oh, wie sehr muss ich erblicken<br/>Dich in Deinen Gliedern klar!<br/>Unter uns wohnt Gott auf ewig,<br/>In dem Fleisch hier offenbar.<br/>',NULL,52888,3);
INSERT INTO stanza VALUES('G1019','4','Schränke meine Freiheit ein, Herr,<br/>An den Leib wend ich mich gern;<br/>Nicht nur Licht vom Himmel suchend,<br/>Dass Gemeinde-Sinn ich lern.<br/>Werden wir zu gutem Baustein!<br/>Nicht mehr Ton ohn jede Form,<br/>Find in uns doch Dein Verlangen:<br/>Wir gemeinsam Dir konform.<br/>',NULL,52889,4);
INSERT INTO stanza VALUES('G1020','1','Kommt, sprechen wir, bis das Königreich des Herrn da ist,<br/>Kommt, sprechen wir, bis das Königreich des Herrn da ist;<br/>Warum nur schweigt?<br/>Das Wort befreit!<br/>Lasst uns sprechen bis das Königreich des Herrn da ist.<br/>',NULL,52890,1);
INSERT INTO stanza VALUES('G1020','2','Befreit das Wort! Zu Ihm kehrt es niemals leer zurück.<br/>Befreit das Wort! Zu Ihm kehrt es niemals leer zurück.<br/>Wir säen hier,<br/>Das müssen wir;<br/>Wenn wir sprechen, kehrt es zu Ihm niemals leer zurück.<br/>',NULL,52891,2);
INSERT INTO stanza VALUES('G1020','3','Verkünden wir überall das Evangelium!<br/>Verkünden wir! Auch trotz Tadel kehren niemals um!<br/>Gott tat das Sein’,<br/>Setzt euch doch ein!<br/>Wir sind Pilger hier und wenden uns doch niemals um!<br/>',NULL,52892,3);
INSERT INTO stanza VALUES('G1020','4','Verkünden wir, dann spricht Christus ihre Herzen an.<br/>Verkünden wir, dann spricht Christus ihre Herzen an.<br/>Gewinnen viel,<br/>Ist unser Ziel;<br/>Wenn wir sprechen, dann bezeugt der Herr den Menschen hier.<br/>',NULL,52893,4);
INSERT INTO stanza VALUES('G1020','5','Die Ernte – reif! Sprecht das volle Evangelium!<br/>Die Felder – weiß! Sprecht das volle Evangelium!<br/>Bringt sie doch heim,<br/>In die Gemeind;<br/>Lasst uns ernten, sprecht das volle Evangelium!<br/>',NULL,52894,5);
INSERT INTO stanza VALUES('NS618','chorus','If we have an affectionate love,<br/>An affectionate love for the Lord Jesus,<br/>Our tongue will be, will be the pen<br/>Of a ready writer,<br/>Ready to write our love for Him<br/>And our praise, our praise to Him<br/>With our experience and enjoyment of Him<br/>According to all, according to all,<br/>According to all that He is.<br/>',NULL,52898,1);
INSERT INTO stanza VALUES('NS619','1','O Morning Star! Arise ere day is broken,<br/>Shine, Thou, dear Lord—our hope, our light, our way;<br/>Thou art that noble root and fruit of David,<br/>Lucent above, guides to a perfect day.<br/>',NULL,52899,1);
INSERT INTO stanza VALUES('NS619','chorus','O Morning Star! Arise in secret stillness,<br/>Break through the gloom, the darkness of this age;<br/>Burst forth, Thou Sun of Righteousness, in splendor!<br/>Come now, our King, turn Thou a glorious page.<br/>',NULL,52900,2);
INSERT INTO stanza VALUES('NS619','2','O Morning Star! Ascend before the dawning,<br/>In twilight radiate—how clear and bright!<br/>While here we love and wait for Thy dear coming,<br/>Silently, Thou illuminate our night.<br/>',NULL,52901,3);
INSERT INTO stanza VALUES('NS619','3','O Morning Star! Spring forth from my heart’s fountain,<br/>As we attend to Thy prophetic word;<br/>Glow as a lamp amidst apostate darkness,<br/>Until the morn arrives in all the earth.<br/>',NULL,52902,4);
INSERT INTO stanza VALUES('NS619','4','O Morning Star! Appear to us Thy seekers!<br/>Midst this black hour, we wait for Thy return.<br/>Earnestly longing for Thy hidden presence;<br/>Our fond Reward, for Thee we dearly yearn!<br/>',NULL,52903,5);
INSERT INTO stanza VALUES('NS620','chorus','Until we all arrive<br/>At the oneness of the faith<br/>And of the full knowledge<br/>Of the Son of God,<br/>At the oneness of the faith,<br/>At a full-grown man,<br/>At the measure of the stature<br/>Of the fullness of Christ,<br/>Until we all arrive.<br/>',NULL,52904,1);
INSERT INTO stanza VALUES('NS620','chorus','Let us rejoice,<br/>And let us give the glory to Him,<br/>For the marriage of the Lamb has come,<br/>Let us exult,<br/>And let us give the glory to Him,<br/>For the marriage of the Lamb has come,<br/>And His wife has made herself ready.<br/>For the marriage of the Lamb has come.<br/>',NULL,52905,2);
INSERT INTO stanza VALUES('NS621','1','In Christ, God’s will and heart’s desire<br/>Is focused, fixed, and firm;<br/>Towards one thing only God has worked<br/>For time’s entire term;<br/>His purpose, from eternity,<br/>Has always been the same—<br/>To mingle His own life with man<br/>To glorify His name.<br/>',NULL,52906,1);
INSERT INTO stanza VALUES('NS621','2','As Architect and Builder too<br/>God works to build His house;<br/>The building is the mingling<br/>Of Bridegroom with His spouse;<br/>As Eve was built from Adam’s rib,<br/>The church comes out from Christ;<br/>His wife prepares to marry Him<br/>By mingling in life.<br/>',NULL,52907,2);
INSERT INTO stanza VALUES('NS621','3','Christ is our entrance into God,<br/>Our portal and our way,<br/>The Pearl prepared by wounding sand,<br/>Redemption made for aye.<br/>God’s building is sustained by Christ,<br/>Upheld victoriously;<br/>God’s testimony He uplifts<br/>In His humanity.<br/>',NULL,52908,3);
INSERT INTO stanza VALUES('NS621','4','Christ also is the Man of bronze<br/>Before the building’s gate,<br/>Whom God has judged on our behalf,<br/>Most qualified His state.<br/>He knows our real condition and<br/>Has paid our debt with blood.<br/>He measures us, possessing us,<br/>To mingle us with God.<br/>',NULL,52909,4);
INSERT INTO stanza VALUES('NS621','5','When found in Christ, expressing God,<br/>We overcome with might,<br/>Protected by God’s holy fire<br/>Within us burning bright!<br/>The Triune God in Christ will be<br/>The glory at the heart<br/>Of all we are and all we do,<br/>Transparency our part.<br/>',NULL,52910,5);
INSERT INTO stanza VALUES('NS621','6','The element that builds the church,<br/>That constitutes the saints,<br/>Is Christ the resurrected One,<br/>The Blessing earth awaits!<br/>The Spirit of reality<br/>Infuses us with Christ!<br/>We gain Him through our mingling<br/>With resurrection life!<br/>',NULL,52911,6);
INSERT INTO stanza VALUES('NS621','7','This mingling in glory is<br/>The New Jerusalem,<br/>The Holy City, God’s elect,<br/>Yea, God built into man!<br/>As God’s expression, we’ll be there,<br/>Inwrought with Christ the Son,<br/>Co-kings with Him, those crowned with life,<br/>Matured and built as one!<br/>',NULL,52912,7);
INSERT INTO stanza VALUES('NS622','1','For the building of the Body<br/>We need Jesus humanly;<br/>The humanity of Jesus<br/>Builds the church organically.<br/>In the Spirit, all that Christ is<br/>Has become our life supply<br/>To equip us for God’s building,<br/>God in Man to glorify.<br/>',NULL,52913,1);
INSERT INTO stanza VALUES('NS622','2','When we fell, our human vessel<br/>Was corrupted by the fall;<br/>The humanity of Jesus<br/>Now uplifts, enriches all.<br/>Christ became us, incarnated,<br/>To bring us into Himself;<br/>With the Triune God we’re mingled;<br/>Christ our life saves us from self.<br/>',NULL,52914,2);
INSERT INTO stanza VALUES('NS622','3','Do you yearn to love as God loves?<br/>Grow up into Christ our Head.<br/>Would you live the way that God lives?<br/>Then choose Christ to live instead.<br/>God gave us the highest living<br/>And the life to live this way.<br/>In the Spirit, God compounded<br/>Everything we need today.<br/>',NULL,52915,3);
INSERT INTO stanza VALUES('NS622','4','In the Spirit of this Jesus,<br/>Every step God took became<br/>Elements that we experience<br/>And apply through Jesus’ name.<br/>Christ’s humanity and living,<br/>With the cross as our release,<br/>Brings in life in resurrection<br/>For our one accord in peace.<br/>',NULL,52916,4);
INSERT INTO stanza VALUES('NS622','5','In the church life, in our spirit,<br/>In the building we are one,<br/>In one Body and one Spirit,<br/>This our calling in the Son.<br/>In the heavens, Christ is sitting<br/>As the Man enthroned and crowned.<br/>The humanity of Jesus<br/>Is the life for glory bound.<br/>',NULL,52917,5);
INSERT INTO stanza VALUES('NS622','6','Our High Priest, this Man in heaven,<br/>Faithful, merciful and true,<br/>Was in all respects once tempted;<br/>Made like us, He suffered too.<br/>His dear blood now gives us boldness<br/>To approach the throne of grace,<br/>Where the Lamb of God receives us,<br/>Timely help we must embrace.<br/>',NULL,52918,6);
INSERT INTO stanza VALUES('NS622','7','For the building of the Body<br/>We are human Jesusly;<br/>By the Spirit of this Jesus<br/>We are built up corporately.<br/>The humanity of Jesus<br/>God supplies us day by day<br/>To become God’s holy city,<br/>Glorifying God for aye.<br/>',NULL,52919,7);
INSERT INTO stanza VALUES('NS623','1','I have loved you,<br/>Says Jehovah.<br/>Yes I have loved you,<br/>With eternal love.<br/>',NULL,52920,1);
INSERT INTO stanza VALUES('NS623','2','I have drawn you,<br/>With lovingkindness.<br/>For I have called you,<br/>And gathered you.<br/>',NULL,52921,2);
INSERT INTO stanza VALUES('NS623','3','The King has brought me,<br/>Into His chambers.<br/>We will extol,<br/>His love, more than wine.<br/>',NULL,52922,3);
INSERT INTO stanza VALUES('NS623','4','O let Him kiss me,<br/>My Beloved.<br/>My heart is with Thee,<br/>Till the end.<br/>',NULL,52923,4);
INSERT INTO stanza VALUES('NS624','1','Your words, Your words,<br/>Your words were found and I ate them,<br/>Your words, Your words,<br/>Your words were found and I ate them,<br/>And Your word became to me<br/>The gladness and joy of my heart,<br/>And Your word became to me<br/>The gladness and joy of my heart.<br/>',NULL,52924,1);
INSERT INTO stanza VALUES('NS625','1','And He said to me,<br/>Son of man, feed your stomach<br/>And fill your inward parts<br/>With this scroll that I am giving you.<br/>',NULL,52925,1);
INSERT INTO stanza VALUES('NS625','2','How sweet are Your words,<br/>How sweet are Your words to my taste!<br/>Sweeter than honey to my mouth,<br/>The gladness and joy of my heart!<br/>',NULL,52926,2);
INSERT INTO stanza VALUES('NS626','1','In my love for You,<br/>Through Your love for me,<br/>Overflowing from within,<br/>In my touch with You,<br/>Being touched by Thee,<br/>I’m abiding, grafted in;<br/>Now Your life bears fruit;<br/>It’s surpassing all<br/>I could say or do;<br/>Keep spreading, Lord.<br/>Keep spreading, Lord.<br/>',NULL,52927,1);
INSERT INTO stanza VALUES('NS626','2','As I dwell in You,<br/>You’re indwelling me;<br/>That Your building work increase.<br/>As I’m born of You,<br/>You’ve been born in me,<br/>That full-growth, this life would reach.<br/>So I open wide,<br/>Ever more abide,<br/>In my every part.<br/>Keep spreading Lord,<br/>Keep spreading Lord.<br/>',NULL,52928,2);
INSERT INTO stanza VALUES('NS626','chorus','(Bridge)<br/>Keep spreading through my mind,<br/>My emotion, will,<br/>Every day renewing<br/>My being till<br/>I’m fully saturated with You.<br/>',NULL,52929,3);
INSERT INTO stanza VALUES('NS626','3','In my heart for You,<br/>Through Your heart for me,<br/>From eternity through time;<br/>In my work for You,<br/>Through Your work in me,<br/>I am resting in the vine.<br/>I now clearly see<br/>All things sovereignly<br/>Work toward Your goal;<br/>So till You return,<br/>Keep spreading Lord.<br/>',NULL,52930,4);
INSERT INTO stanza VALUES('NS627','1','Make my hands full, I pray, dear Lord;<br/>Full of the Christ enjoyed each day.<br/>E’en now I come to You for more,<br/>Empty for You; fill me today.<br/>',NULL,52931,1);
INSERT INTO stanza VALUES('NS627','2','Make my hands full today, O Lord.<br/>You lived a life all absolute.<br/>I lay my hands upon You, Lord,<br/>In union, grafted, one with You.<br/>',NULL,52932,2);
INSERT INTO stanza VALUES('NS627','3','Make my hands full right now, O Lord,<br/>That I’d partake of You today.<br/>By eating of Your living Word,<br/>My old self would be purged away.<br/>',NULL,52933,3);
INSERT INTO stanza VALUES('NS627','4','Make my hands full, my Savior Lord.<br/>You were made sin and judged by God,<br/>That all my sins may be no more.<br/>I would, each day, apply Your blood.<br/>',NULL,52934,4);
INSERT INTO stanza VALUES('NS627','5','Make my hands full; You are my peace.<br/>In everything, I’d talk to You,<br/>With God no longer enemies,<br/>Enjoying peace with all saints, too.<br/>',NULL,52935,5);
INSERT INTO stanza VALUES('NS627','6','Make my hands full; this is my prayer.<br/>Remind me, Lord, how rich are You.<br/>I’d on Thee labor, to prepare,<br/>To offer Christ in worship true.<br/>',NULL,52936,6);
INSERT INTO stanza VALUES('NS627','7','Make my hands full with only You;<br/>Nothing of self, but all of Christ.<br/>Savor so sweet and fragrant, too,<br/>Rises to God, now satisfied.<br/>',NULL,52937,7);
INSERT INTO stanza VALUES('NS628','1','Oh Lord, I’ve seen Your worth.<br/>There’s nothing on this earth<br/>That matches who You are.<br/>You’ve captured all my heart.<br/>You’ve captured all my heart.<br/>',NULL,52938,1);
INSERT INTO stanza VALUES('NS628','chorus','You are my hope, my goal, Lord;<br/>You’re the meaning of my life, Lord;<br/>You alone are worthy, Lord;<br/>I give my life to You.<br/>',NULL,52939,2);
INSERT INTO stanza VALUES('NS628','2','I consecrate myself<br/>To give You the first place,<br/>First love, and only love.<br/>To all else, You’re above.<br/>To all else, You’re above.<br/>',NULL,52940,3);
INSERT INTO stanza VALUES('NS628','3','Preeminence, I give.<br/>Do reign supreme in me,<br/>In my entire being.<br/>You are my Lord, my King.<br/>You are my Lord, my King.<br/>',NULL,52941,4);
INSERT INTO stanza VALUES('NS628','4','There’s nothing I hold back.<br/>No room in me I close,<br/>But have the way in me.<br/>All freedom’s giv’n to Thee.<br/>All freedom’s giv’n to Thee.<br/>',NULL,52942,5);
INSERT INTO stanza VALUES('NS628','5','Though I don’t know my future,<br/>I trust in Your wise hands,<br/>Your sovereignty, Your ways;<br/>I’ll love You, Lord, always.<br/>I’ll love You, Lord, always.<br/>',NULL,52943,6);
INSERT INTO stanza VALUES('NS629','1','If we neglect the gospel,<br/>If we refuse to pray,<br/>If we neglect our spirit,<br/>Then we have lost our way.<br/>Oh, how our friends and neighbors,<br/>Those in our families,<br/>All need our interceding,<br/>Our prayer upon our knees!<br/>',NULL,52944,1);
INSERT INTO stanza VALUES('NS629','2','Saints, time is of the essence,<br/>’Tis time for us to gain<br/>The fruit unto the gospel,<br/>The ripened golden grain.<br/>Oh, let us not be slothful,<br/>Rise up and seize the day!<br/>Let not our hours be wasted,<br/>His purpose more delayed.<br/>',NULL,52945,2);
INSERT INTO stanza VALUES('NS629','3','Oh, let’s all work together,<br/>Let’s pray in two’s and three’s.<br/>Serve in coordination,<br/>The Father’s heart to please.<br/>We must no more be barren.<br/>Steadfastly persevere,<br/>Pour out our dearest treasure,<br/>And mix our prayer with tears.<br/>',NULL,52946,3);
INSERT INTO stanza VALUES('NS629','4','Our life must have a purpose,<br/>For this we must spend all<br/>As debtors to the gospel<br/>In answer to His call.<br/>We need a heart for people,<br/>For other’s lives outpoured,<br/>A heart that’s for the gospel,<br/>A heart that’s for the Lord.<br/>',NULL,52947,4);
INSERT INTO stanza VALUES('NS629','5','We bear the gladdest tidings,<br/>The only news that’s good.<br/>God’s grace is apprehended,<br/>His mercies understood.<br/>And if we have such riches,<br/>How can we dare forbear<br/>To tell a world that’s hungry<br/>Our Father’s loving care.<br/>',NULL,52948,5);
INSERT INTO stanza VALUES('NS630','1','Lord, perfect us, Thy believers,<br/>As the New Jerusalem;<br/>God as newness wrought within us,<br/>New creation we’ll become.<br/>As we’re opened fully to Thee,<br/>Lord, renew our every part.<br/>Gain Thy corporate, image-bearing<br/>One new man, Thy counterpart.<br/>',NULL,52949,1);
INSERT INTO stanza VALUES('NS630','2','Holy city, all God’s people<br/>Sanctified in nature true,<br/>Saturated with Thine essence,<br/>Is Thy one eternal view.<br/>Yield us weighty, constituted,<br/>Fully mingled, Lord, with Thee<br/>That Thou gain Thy full expression<br/>And Thy glory fully see.<br/>',NULL,52950,2);
INSERT INTO stanza VALUES('NS630','3','We’re God’s tabernacle, dwelling;<br/>Here is Thine eternal rest.<br/>We’re Thy house, Thy splendid temple,<br/>Joined in spirit, fully blessed.<br/>Lord, our bodies we present now,<br/>With all saints together grow;<br/>Blended, built, coordinated,<br/>We’d Thy building truly know.<br/>',NULL,52951,3);
INSERT INTO stanza VALUES('NS630','4','Now betrothed to Thee, dear Bridegroom,<br/>Bring us to maturity.<br/>Beautify, reconstitute us<br/>Till we match Thee perfectly.<br/>May our love grow deeper, fuller;<br/>Foretaste of our married life.<br/>How we long to finally meet Thee!<br/>Thou, the Lamb, and we, the wife!<br/>',NULL,52952,4);
INSERT INTO stanza VALUES('NS630','5','With that City as our mother,<br/>We’ve been born of God by grace.<br/>In this grace we stand, receiving,<br/>And Thy purpose we embrace:<br/>Many more sons God desires;<br/>We too bring them forth in love.<br/>One with God, we’re now components<br/>Of Jerusalem above.<br/>',NULL,52953,5);
INSERT INTO stanza VALUES('NS630','6','Consummated Triune God with<br/>Redeemed man is joined as one;<br/>Marvelous eternal couple<br/>To declare all Thou hast done.<br/>Lord, obtain Thy deepest longing—<br/>Corporate man build up in Thee;<br/>Thine economy accomplish;<br/>New Jerusalem complete.<br/>',NULL,52954,6);
INSERT INTO stanza VALUES('NS631','1','O lovely Bridegroom, we long for Thy returning;<br/>Quicken that day: increase Thyself in us.<br/>Lord, beautify each member with Thy beauty;<br/>Thy bride we’ll be, prepared and glorious.<br/>',NULL,52955,1);
INSERT INTO stanza VALUES('NS631','2','O lovely Bridegroom, our nat’ral strength e’er fails us;<br/>Hopeless Thou found us, and one gift Thou gave:<br/>Our little pow’r to cling to our Beloved,<br/>Leaning on Thee and guided all the way.<br/>',NULL,52956,2);
INSERT INTO stanza VALUES('NS631','3','O lovely Bridegroom, have mercy on Thy people<br/>That we’d forsake all other loves but Thee,<br/>Cleaving to Thee, our dear and faithful Husband;<br/>Loving Thee solely, unreservedly.<br/>',NULL,52957,3);
INSERT INTO stanza VALUES('NS631','4','O lovely Bridegroom, Thy burning love compels us<br/>That we’d be ready for that wedding day.<br/>E’er we’d adorn the church with all Thy riches;<br/>Her beauty then Thou wouldst desire for aye.<br/>',NULL,52958,4);
INSERT INTO stanza VALUES('NS631','5','O lovely Bridegroom, we yearn to hear Thy speaking:<br/>“You’re altogether beautiful, My love!”<br/>Aching for Thee, Thy coming we would hasten<br/>Till at Thy wedding feast we meet above.<br/>',NULL,52959,5);
INSERT INTO stanza VALUES('NS632','1','God commends His own love to us,<br/>That You died on our behalf,<br/>For us, enemies and sinners<br/>Who were slated for God’s wrath.<br/>We by sin were separated,<br/>From God’s life were alienated.<br/>Then Your death propitiated<br/>And to God You brought us back.<br/>',NULL,52960,1);
INSERT INTO stanza VALUES('NS632','2','On the cusp of crucifixion,<br/>In great agony You prayed;<br/>You besought the Father greatly<br/>That You’d from this hour be saved.<br/>But You rea’lized God’s intention;<br/>Love outweighed Your apprehension,<br/>“Not as I will,” Your submission<br/>To the Father for our sake.<br/>',NULL,52961,2);
INSERT INTO stanza VALUES('NS632','3','When God made You sin entire,<br/>Dying for us on the cross,<br/>God withdrew from You in judgment,<br/>This by far Your greatest loss.<br/>You made reconciliation,<br/>Ending our great separation,<br/>Making us a new creation,<br/>One new man, formed on the cross.<br/>',NULL,52962,3);
INSERT INTO stanza VALUES('NS632','4','Then the veil within the temple,<br/>Top to bottom, split in two,<br/>Rent because You’re now our access<br/>To God’s glory ever new.<br/>With the Father we’ve reunion,<br/>Face to face in holy union,<br/>Reconciled in sweet communion,<br/>Glorious twining through and through.<br/>',NULL,52963,4);
INSERT INTO stanza VALUES('NS632','5','Separation has been dealt with,<br/>We from God no more exiled!<br/>Through Your sacrifice forgiven,<br/>We to Him are reconciled!<br/>We can live in resurrection,<br/>Joined to God through Your oblation,<br/>To express Your life and person,<br/>In our spirit, by the blood!<br/>',NULL,52964,5);
INSERT INTO stanza VALUES('NS632','6','Praise the Son sent by the Father,<br/>Lamb of God Whom God made sin!<br/>Praise You for Your dread endurance,<br/>As that breach brought judgment in!<br/>Praise You for God’s satisfaction<br/>With Your death and its transaction,<br/>And that Your brief separation<br/>Made us one with God fore’er!<br/>',NULL,52965,6);
INSERT INTO stanza VALUES('NS633','1','O Lord, through all the years I’ve been under Your word,<br/>Yet the rate of growth matched not Your grace.<br/>I have heard very much, yet how deep have I been touched;<br/>O Lord, please hear my cry—grow apace!<br/>',NULL,52966,1);
INSERT INTO stanza VALUES('NS633','chorus','Grant me to stay<br/>Lord, every day,<br/>Open and longing to see<br/>Your beauty, Your glory, Your supremacy!<br/>Lord, empty me,<br/>Increase in me;<br/>Fill all my being thoroughly.<br/>',NULL,52967,2);
INSERT INTO stanza VALUES('NS633','2','In the earlier years when Your love felt so strong;<br/>To pursue just felt easy, worthwhile.<br/>Now I’ve journeyed so long, with the wind contrary, strong;<br/>I’m afraid I might drift in a while.<br/>',NULL,52968,3);
INSERT INTO stanza VALUES('NS633','chorus','Lest I should stray,<br/>Draw me, I pray,<br/>Loving and seeking Your face,<br/>To run with endurance and finish my race!<br/>O may Your joy<br/>Become my joy;<br/>May You be all my employ.<br/>',NULL,52969,4);
INSERT INTO stanza VALUES('NS633','3','May Your building, O Lord, measure me, be my light,<br/>All my living and serving to prove.<br/>Draw me nigh day and night, minist’ring to Your delight;<br/>Lord, initiate my every move.<br/>',NULL,52970,5);
INSERT INTO stanza VALUES('NS633','chorus','Grant me to heed<br/>Your Body’s need;<br/>None else on earth would I seek:<br/>Not service, nor persons, nor earthly intrigue!<br/>Deepen the flow,<br/>Your Body grow,<br/>Your bride prepare, kingdom show!<br/>',NULL,52971,6);
INSERT INTO stanza VALUES('NS634','1','I have treasured Your word<br/>More than my daily bread,<br/>I have treasured Your word<br/>More than my daily bread.<br/>',NULL,52972,1);
INSERT INTO stanza VALUES('NS634','2','Man shall not live on bread alone,<br/>But on every word that<br/>Proceeds out through the mouth of God,<br/>Out through the mouth of God.<br/>',NULL,52973,2);
INSERT INTO stanza VALUES('NS634','3','Your word enlivens,<br/>Your word revives,<br/>Your words are Spirit,<br/>Your words are life.<br/>',NULL,52974,3);
INSERT INTO stanza VALUES('NS635','1','Lord, fill me up past the brim,<br/>Pouring in from limb to limb.<br/>It’s Your love that comforts me<br/>Deeper and wider than the sea.<br/>',NULL,52975,1);
INSERT INTO stanza VALUES('NS635','chorus','I am a Jesus Bottle!<br/>I am an open vessel!<br/>I am a gushing fountain<br/>Flowing with Christ Jesus my Lord!<br/>',NULL,52976,2);
INSERT INTO stanza VALUES('NS635','2','Lord I was blind; I could not see.<br/>It’s Your light that shines through me.<br/>Nothing can explain how bright<br/>Like Your star that appeared that night.<br/>',NULL,52977,3);
INSERT INTO stanza VALUES('NS635','3','Power that is a mystery;<br/>It’s Your Spirit infusing me.<br/>All because of God’s vast grace,<br/>There’s this big smile on my face!<br/>',NULL,52978,4);
INSERT INTO stanza VALUES('NS636','1','Lord, You suffered and were ravaged<br/>By the cruelty of men.<br/>From Gethsemane to Calvary,<br/>Men oppressed and judged You then;<br/>Our transgressions caused You wounding,<br/>Pain and suffering all consuming,<br/>’Til a breach in Your communing<br/>Caused You grief unknown from birth.<br/>From the garden to Golgotha,<br/>All You passed through proved Your worth.<br/>',NULL,52979,1);
INSERT INTO stanza VALUES('NS636','2','You had one friend who betrayed You,<br/>With a kiss, to hate-filled men,<br/>And another who denied You<br/>Out of fear towards all of them.<br/>When they took You as their prisoner,<br/>Questioned You, their anger bitter,<br/>And then mocked You, thought a sinner,<br/>You did not Yourself defend.<br/>You were mute and long-enduring<br/>With a view to reach Your end.<br/>',NULL,52980,2);
INSERT INTO stanza VALUES('NS636','3','The Sanhedrin sought to weaken<br/>Your endurance and Your strength,<br/>Then delivered You to Pilate<br/>Whose men scourged You, whipped at length.<br/>At Golgotha, soldiers stripped You,<br/>And with violent pounding nailed You<br/>To Your cross, through joint and sinew,<br/>There to hang upon the tree,<br/>Where bystanders mocked, despising,<br/>Wagging heads contempt’ously.<br/>',NULL,52981,3);
INSERT INTO stanza VALUES('NS636','4','Those who hated You were staring,<br/>No respect, their visage hard.<br/>Soldiers gambled for Your garments<br/>While Your strength dried like a shard.<br/>Like hot wax, Your heart was melting.<br/>Gravity each joint was rending.<br/>In Your mouth, Your tongue was cleaving.<br/>As Your weight each breath then stole,<br/>Your ordeal made all the harder<br/>When God made You sin for all.<br/>',NULL,52982,4);
INSERT INTO stanza VALUES('NS636','5','At the noon hour, when God judged You,<br/>Laid on You the whole of sin,<br/>God’s dear presence fled, departed,<br/>From Your fellowship within.<br/>This was much worse than the violence;<br/>This forsaking—dreaded silence,<br/>All the scorn of men’s derision<br/>Paling in comparison<br/>To the scope of God’s own judgement<br/>Poured upon His only Son.<br/>',NULL,52983,5);
INSERT INTO stanza VALUES('NS636','6','After three hours, at Your limit,<br/>You cried out in agony,<br/>In the words of David, Psalmist,<br/>“Why have You forsaken Me?”<br/>Saying, “I thirst... It is finished”<br/>You were done, Your work unblemished.<br/>You prayed “Father, into Your hands<br/>I commit My spirit.” Then<br/>With a loud cry, You expired,<br/>As Your loved ones grieved again.<br/>',NULL,52984,6);
INSERT INTO stanza VALUES('NS636','7','When Your death the soldiers noticed,<br/>One took up His weighted spear<br/>And he pierced Your side in coldness,<br/>Blood and water flowing clear.<br/>From Gethsemane to Calvary<br/>You were broken, suffering greatly.<br/>Wounds innumerable, a fountain,<br/>Flowing precious priceless blood,<br/>For our sins and our redemption,<br/>Reconciling us to God.<br/>',NULL,52985,7);
INSERT INTO stanza VALUES('NS636','8','Lord, I praise You and I thank You<br/>That You bled and died for me,<br/>As I ponder how You loved me<br/>And You gave Yourself for me.<br/>I am filled with love and reverence,<br/>Gratitude and deep assurance<br/>You forgive me in Your mercy,<br/>By Your blood, for all my sin!<br/>And You joined me to the Father!<br/>Hallelujah, Lord! Amen!<br/>',NULL,52986,8);
INSERT INTO stanza VALUES('NS637','1','He who overcomes,<br/>him I’ll make a pillar in the<br/>temple of My God,<br/>He who overcomes,<br/>he shall by no means go out,<br/>go out anymore.<br/>',NULL,52987,1);
INSERT INTO stanza VALUES('NS637','2','I come quickly;<br/>hold fast what you have,<br/>I come quickly;<br/>hold fast what you have<br/>that no one, no one<br/>take your crown.<br/>',NULL,52988,2);
INSERT INTO stanza VALUES('NS638','1','Manna from heaven came down.<br/>Miraculous mystery from God.<br/>Jesus said, “I am this bread...<br/>Given for the life of the world.”<br/>Eat Him.<br/>He is the living bread.<br/>Gain Him.<br/>Oh what a supply!<br/>Praise Him!<br/>Only He satisfies.<br/>Jesus!<br/>The all-inclusive Christ.<br/>',NULL,52989,1);
INSERT INTO stanza VALUES('NS638','2','Christ is the spiritual rock,<br/>Smitten and cleft by our God.<br/>Water of life flowed forth.<br/>Now quenching all of our thirst.<br/>Drink Him.<br/>He is the fount of life.<br/>Taste Him.<br/>Oh sweet well of life.<br/>Praise Him!<br/>Never you’ll thirst again.<br/>Jesus!<br/>The all-inclusive Christ.<br/>',NULL,52990,2);
INSERT INTO stanza VALUES('NS638','3','On the cross where He was nailed,<br/>Both blood and water flowed out.<br/>Redemption is fully paid.<br/>Why not receive and enjoy.<br/>Take Him.<br/>Our Savior and our King.<br/>Give Him,<br/>The first place in us.<br/>Praise Him!<br/>One sacrifice for all.<br/>Jesus!<br/>The all-inclusive Christ.<br/>',NULL,52991,3);
INSERT INTO stanza VALUES('NS638','4','He is the Spirit today.<br/>Ready to make home in us.<br/>Calling on Him is the way.<br/>All of His riches to gain.<br/>Breathe Him.<br/>He’s the pneumatic One.<br/>Touch Him.<br/>Oh He is so near.<br/>Praise Him!<br/>Life-giving Spirit.<br/>Jesus!<br/>The all-inclusive Christ.<br/>',NULL,52992,4);
INSERT INTO stanza VALUES('NS639','1','I need a new heart<br/>So God gave His Spirit to me,<br/>I need a new start<br/>Each morning, dear Lord, renew me;<br/>He saves and revives me,<br/>Making home in all our hearts,<br/>I need a new heart....<br/>I need a new start....<br/>I need a new heart, today!<br/>',NULL,52993,1);
INSERT INTO stanza VALUES('NS639','2','I need a soft heart,<br/>Repenting to God completely,<br/>To transform each part,<br/>By loving the Lord more deeply;<br/>The Lord is the Spirit<br/>And we all with unveiled face<br/>Receive a soft heart....<br/>Enjoy a fresh start....<br/>Receive a soft heart, today!<br/>',NULL,52994,2);
INSERT INTO stanza VALUES('NS639','3','Lord, broaden my heart,<br/>In matters of pride, defeat me;<br/>A duplicate heart,<br/>From Your heart to mine, infuse me;<br/>To minister Jesus,<br/>Showing love to all we meet,<br/>Lord, broaden my heart....<br/>Lord, be my new start....<br/>Lord, broaden my heart, today!<br/>',NULL,52995,3);
INSERT INTO stanza VALUES('NS639','chorus','ENDING:<br/>Lord, You’re my new heart,<br/>Lord, You’re my soft heart,<br/>Lord, give us Your heart, we pray!<br/>',NULL,52996,4);
INSERT INTO stanza VALUES('NS640','1','But we all, but we all with unveiled face,<br/>Beholding, beholding and reflecting like a mirror<br/>The glory of the Lord, are being transformed<br/>Into the same image from glory to glory,<br/>Even as from the Lord, the Lord Spirit.<br/>From glory to glory.<br/>',NULL,52997,1);
INSERT INTO stanza VALUES('NS641','1','Jesus’ humanity<br/>God unto us doth give,<br/>As Spirit in His Word,<br/>The food by which we live.<br/>',NULL,52998,1);
INSERT INTO stanza VALUES('NS641','2','Jesus’ humanity,<br/>With God enriched divine<br/>Is constituting us<br/>In spirit as we dine.<br/>',NULL,52999,2);
INSERT INTO stanza VALUES('NS641','3','Jesus’ humanity,<br/>Unique beyond compare,<br/>Fulfills all righteousness;<br/>To do God’s will, His fare.<br/>',NULL,53000,3);
INSERT INTO stanza VALUES('NS641','4','Jesus’ humanity<br/>Takes on the lower place—<br/>Lowly in heart, not grand<br/>But humbled, serves in grace.<br/>',NULL,53001,4);
INSERT INTO stanza VALUES('NS641','5','Jesus’ humanity<br/>Bends in response to change,<br/>Perfectly flexible<br/>Our way to rearrange.<br/>',NULL,53002,5);
INSERT INTO stanza VALUES('NS641','6','Jesus’ humanity<br/>Does all things properly,<br/>Setting things in array,<br/>His living orderly.<br/>',NULL,53003,6);
INSERT INTO stanza VALUES('NS641','7','Jesus’ humanity<br/>Loves all those frail and weak;<br/>He does not break the bruised<br/>Nor quench them in critique.<br/>',NULL,53004,7);
INSERT INTO stanza VALUES('NS641','8','Jesus’ humanity<br/>Cherishes sinful men,<br/>Seeking to save the lost<br/>And Jubilee begin.<br/>',NULL,53005,8);
INSERT INTO stanza VALUES('NS641','9','Jesus’ humanity<br/>Serves as a slave of God,<br/>His service rendered by<br/>Our ransom bought with blood.<br/>',NULL,53006,9);
INSERT INTO stanza VALUES('NS641','10','Jesus’ humanity,<br/>On earth, constrained by time,<br/>Fulfills each prophecy,<br/>Death’s hour endures, sublime.<br/>',NULL,53007,10);
INSERT INTO stanza VALUES('NS641','11','Jesus’ humanity<br/>Reconstitutes the saints,<br/>Building the church, His house,<br/>Wherein His rest awaits.<br/>',NULL,53008,11);
INSERT INTO stanza VALUES('NS641','12','Jesus’ humanity<br/>Cherish with holy praise!<br/>Thus, in remembrance here,<br/>One voice with reverence raise!<br/>',NULL,53009,12);
INSERT INTO stanza VALUES('NS642','1','As the world rushes on,<br/>I’m reminded of Thee.<br/>Though time passes away,<br/>There’s eternity in me.<br/><br/>Now nothing ’neath the sun,<br/>But Thou and Thou alone,<br/>Can satisfy my heart.<br/>Things temp’ral will not do;<br/>I’d things above pursue;<br/>Eternal One, Thou art.<br/>',NULL,53010,1);
INSERT INTO stanza VALUES('NS642','2','Priceless ’tis, now I see,<br/>To spend time seeking Thee.<br/>Time is precious to me,<br/>Limited in quantity.<br/><br/>Lord, I just want to spend<br/>My time with only Thee,<br/>For Thou art worthy Lord.<br/>I’d every moment seize,<br/>Not one spent without Thee,<br/>But with my love, my Lord.<br/>',NULL,53011,2);
INSERT INTO stanza VALUES('NS642','3','How can I spend my time<br/>That it’d be valuable,<br/>Thousand-fold multiplied,<br/>Ever our memorial?<br/><br/>I’d rather spend a day,<br/>With Thee and with Thy saints,<br/>Than thousand days away.<br/>One thing, that do I seek,<br/>To dwell within Thy house<br/>Beholding Thee always.<br/>',NULL,53012,3);
INSERT INTO stanza VALUES('NS642','4','New beginning I ask.<br/>All my heart, capture more;<br/>All my time, spent with Thee;<br/>All my days, on Thee outpoured.<br/><br/>The time, may I redeem,<br/>From many wasted days,<br/>From wand’ring aimlessly.<br/>More time I cannot waste;<br/>Thou long didst wait for me,<br/>To turn my being to Thee.<br/>',NULL,53013,4);
INSERT INTO stanza VALUES('NS643','1','Jesus Lord, I’m coming forward unto You.<br/>Hiding not, I come just as I am,<br/>Though reviewing how I’ve lived today<br/>I am filled with shame once again.<br/>No more myself deceiving,<br/>No more to You pretending,<br/>Simply opening my heart in full,<br/>In my spirit Lord I pray to You.<br/>',NULL,53014,1);
INSERT INTO stanza VALUES('NS643','2','To be like Abraham,<br/>Intimate and sweet with You,<br/>Lingering in fellowship,<br/>Lord I want to know Your heart’s<br/>Longing and deep desire.<br/>This is my plea, reveal to me this mystery.<br/>What privilege, how glorious,<br/>To be one with Your great plan.<br/>',NULL,53015,2);
INSERT INTO stanza VALUES('NS643','3','Receiving You, dear Lord,<br/>Letting this life saturate,<br/>Listening to Your sweet Word,<br/>Truly I want to express<br/>Nothing but only You.<br/>I consecrate and give You all my heart and mouth.<br/>This is, alone, the meaning and<br/>Purpose of my prayer, Lord.<br/>',NULL,53016,3);
INSERT INTO stanza VALUES('NS643','4','Now on the earth, freely through us,<br/>Carry out Your will, my Lord.<br/>',NULL,53017,4);
INSERT INTO stanza VALUES('NS644','5','Let us rejoice, let us rejoice,<br/>Let us rejoice in the Lord!<br/>Let us rejoice, let us rejoice,<br/>Let us rejoice in the Lord!<br/>',NULL,53018,1);
INSERT INTO stanza VALUES('NS644','1','Let us keep calling, pursuing our Lord.<br/>Let us keep singing, pray-reading His word.<br/>Let us keep meeting, receiving His grace.<br/>Let us keep running this race.<br/>',NULL,53019,2);
INSERT INTO stanza VALUES('NS644','2','Let us keep praising and touching His life.<br/>Let us keep loving, denying all strife.<br/>Let us eat, drink Him and breath Him today.<br/>Let us enjoy Him this way.<br/>',NULL,53020,3);
INSERT INTO stanza VALUES('NS644','3','Let us keep resting, abide and obey.<br/>Let us keep listening to all He will say.<br/>Let us keep speaking, expressing His light.<br/>Let us dispense Christ as life.<br/>',NULL,53021,4);
INSERT INTO stanza VALUES('NS644','4','Let’s keep enjoying our rich treasure store.<br/>Let us keep sharing His Life more and more.<br/>Let’s keep dispensing our portion today.<br/>Let us keep caring and pray.<br/>',NULL,53022,5);
INSERT INTO stanza VALUES('NS644','chorus','Let us rejoice, let us rejoice,<br/>Let us rejoice in the Lord!<br/>Let us rejoice, let us rejoice,<br/>Let us rejoice in the Lord!<br/>Let us rejoice!<br/>',NULL,53023,6);
INSERT INTO stanza VALUES('NS645','1','On the Table, before us displayed,<br/>The bread and the cup manifest<br/>All the sufferings that You underwent and<br/>The mercy with which we are blessed,<br/>For You knew in advance God’s intention,<br/>And what bearing God’s judgment would cost,<br/>Then You paid it in Your crucifixion,<br/>A gift we can never exhaust.<br/>',NULL,53024,1);
INSERT INTO stanza VALUES('NS645','chorus','We gather in love to remember,<br/>Partaking the bread and the cup,<br/>That Your death is an eternal splendor<br/>Which satisfies God as we sup.<br/>',NULL,53025,2);
INSERT INTO stanza VALUES('NS645','2','All the beatings, the scourging, the thorns,<br/>The ravage You suffered and bore,<br/>In these two precious symbols are shown here,<br/>In bread and in cup evermore.<br/>For Your flesh and Your blood, separated,<br/>Are both here, on the Table displayed.<br/>We all eat and we drink, reassured that<br/>Your death every righteous debt paid.<br/>',NULL,53026,3);
INSERT INTO stanza VALUES('NS645','3','When the brothers, with hands on the bread,<br/>Press downward to break it apart,<br/>I see You in my stead being broken<br/>And weep with a gratified heart.<br/>All Your wounds, without number created,<br/>Borne as You were poured out mortally,<br/>All Your sufferings, eternally slated,<br/>Accomplished redemption for me.<br/>',NULL,53027,4);
INSERT INTO stanza VALUES('NS645','4','You were pierced on the cross for my sin,<br/>Forsaken of men and despised.<br/>You were poured out like water in death, Lord,<br/>Affliction that God Himself prized.<br/>Here, one bread and one cup both exhibit<br/>How Your death reconciles us to be<br/>In the oneness that’s in God the Father,<br/>For which we rejoice gratefully!<br/>',NULL,53028,5);
INSERT INTO stanza VALUES('NS645','5','On the Table, before us displayed,<br/>The bread and the cup manifest<br/>You were wounded for all our transgressions,<br/>Bore stripes for our healing and rest.<br/>Chastening for our peace fell upon You,<br/>Even all our iniquity too,<br/>All our burdens, our sickness, our sorrow.<br/>We pour out our praises to You!<br/>',NULL,53029,6);
INSERT INTO stanza VALUES('NS646','1','I was going down<br/>From Jerusalem to Jericho,<br/>Towards that cursed town,<br/>Exchanging peace for pain and sorrow.<br/>',NULL,53030,1);
INSERT INTO stanza VALUES('NS646','chorus','Then the robbers came<br/>Stripped me and beat me, left me half dead.<br/>Stuck here, bruised and lame<br/>Will this wretched road be my deathbed?<br/>',NULL,53031,2);
INSERT INTO stanza VALUES('NS646','chorus','Can somebody help me?<br/>I’m hurting! I’m dying! Does anyone care?<br/>I have an urgent need!<br/>But sadly it seems that no one is aware.<br/>',NULL,53032,3);
INSERT INTO stanza VALUES('NS646','2','Wait, a priest I see!<br/>Descending like me. My case he’ll claim!<br/>He passes by me,<br/>Then comes a Levite and does the same.<br/>',NULL,53033,4);
INSERT INTO stanza VALUES('NS646','chorus','I thought they would help me!<br/>They seemed to serve God and to honor His name.<br/>Religion is empty!<br/>It cannot heal me. All my wounds still remain.<br/>',NULL,53034,5);
INSERT INTO stanza VALUES('NS646','3','A Samaritan<br/>Comes upon me and observes my plight.<br/>Moved with compassion<br/>He treats my wounds, binding them just right.<br/>',NULL,53035,6);
INSERT INTO stanza VALUES('NS646','chorus','Lord Jesus You found me!<br/>You poured oil and wine on my wounds, them to heal!<br/>You put me on Your beast!<br/>At last! Here is kindness and tenderness real.<br/>',NULL,53036,7);
INSERT INTO stanza VALUES('NS646','4','Now I’m in the inn,<br/>The church, with all those under Your care.<br/>And now I begin<br/>To find some others still in despair.<br/>',NULL,53037,8);
INSERT INTO stanza VALUES('NS646','chorus','Lord, bring in more wounded!<br/>Those without the Spirit and the life divine.<br/>That they could be added,<br/>And at Your return, the same care You would find.<br/>',NULL,53038,9);
INSERT INTO stanza VALUES('NS647','1','I will also give you<br/>A new heart, and a new spirit<br/>I will put within you;<br/>And I will take away the heart of stone<br/>Out of your flesh,<br/>',NULL,53039,1);
INSERT INTO stanza VALUES('NS647','2','And I will give you a heart of flesh,<br/>And I will give you a heart of flesh!<br/>',NULL,53040,2);
INSERT INTO stanza VALUES('NS647','chorus','I will also give you<br/>A new heart, and a new spirit<br/>I will put within you;<br/>And I will take away the heart of stone<br/>Out of your flesh.<br/>',NULL,53041,3);
INSERT INTO stanza VALUES('NS648','1','After breakfast on the seashore,<br/>Jesus set about to restore<br/>Peter’s love, that he would henceforth<br/>Not trust himself,<br/>He committed some big failures,<br/>Three times denying the Savior,<br/>Then leading others to waiver,<br/>Yet Jesus said...<br/>',NULL,53042,1);
INSERT INTO stanza VALUES('NS648','chorus','Do you love me? Feed my lambs,<br/>Do you love me? Shepherd my sheep,<br/>Do you love me?<br/>Then give My sheep something to eat.<br/>',NULL,53043,2);
INSERT INTO stanza VALUES('NS648','2','We, like Peter, all have stumbled,<br/>Such defeats make our strength crumble,<br/>Our once proud hearts become humble,<br/>We are so low,<br/>In these moments the Lord comes in,<br/>Seeking our love and affection,<br/>As we listen, we can hear Him<br/>Saying to us...<br/>',NULL,53044,3);
INSERT INTO stanza VALUES('NS648','3','In these days the Lord is hindered<br/>Because of a lack of shepherds<br/>Who dispense the milk of the Word<br/>To the lost sheep,<br/>He needs man’s cooperation,<br/>To let Him shepherd from within,<br/>Will you be one who is open<br/>And say to Him...<br/>',NULL,53045,4);
INSERT INTO stanza VALUES('NS648','chorus','Lord, I love You! I’ll feed Your lambs,<br/>Lord I love You! I’ll shepherd Your sheep,<br/>Lord I love You!<br/>I’ll give Your sheep something to eat.<br/>',NULL,53046,5);
INSERT INTO stanza VALUES('NS649','chorus','New day, new start—Oh, I love the Lord.<br/>His way, my heart—Yes, I love the Lord.<br/>Rise up spirit, soul, body so the day can start<br/>God is moving on today and I have a heart.<br/>',NULL,53047,1);
INSERT INTO stanza VALUES('NS650','1','Come to Me all who toil and are burdened,<br/>And I will give you rest.<br/>Come to Me all who toil and are burdened,<br/>And I will give you rest.<br/>',NULL,53048,1);
INSERT INTO stanza VALUES('NS650','2','Take My yoke upon you and learn from Me,<br/>For I’m meek and lowly in heart,<br/>And you’ll find rest for your souls.<br/>My yoke is easy and My burden is light.<br/>',NULL,53049,2);
INSERT INTO stanza VALUES('NS651','1','What kind of person would die for my sin?<br/>Someone more perfect than all men have been.<br/>Someone who did not deserve death, my due,<br/>Bridging the gap that brought curse to all men.<br/>',NULL,53050,1);
INSERT INTO stanza VALUES('NS651','chorus','Christ on the cross was a man without sin,<br/>Living, while dying, by virtues within,<br/>Virtues expressing divine attributes,<br/>His life, most valued by God, shown therein.<br/>',NULL,53051,2);
INSERT INTO stanza VALUES('NS651','2','Christ chose the friend who betrayed Him for gain;<br/>Loved Peter still, though he’d sworn at His name;<br/>Mutely faced hatred from those who’d defame;<br/>Saved one who mocked Him but later felt shame.<br/>',NULL,53052,3);
INSERT INTO stanza VALUES('NS651','3','For the transgressors while dying Christ prayed,<br/>“Father, forgive them,” this prayer for us made.<br/>“They do not know what they’re doing,” He said.<br/>God’s tender mercy and love He displayed.<br/>',NULL,53053,4);
INSERT INTO stanza VALUES('NS651','4','Dying, in pain, Christ saw Mary bereaved.<br/>Still, in compassion, He cared for her need—<br/>“Behold your mother” and “Behold your son”—<br/>She from that hour by John was received.<br/>',NULL,53054,5);
INSERT INTO stanza VALUES('NS651','5','What shall we say then for all of these things?<br/>God’s Son was raised by the Father, approved.<br/>Seated at God’s right, the Lord Himself brings<br/>Me to the Father, all distance removed.<br/>',NULL,53055,6);
INSERT INTO stanza VALUES('NS651','6','Were I the only one e’er to be born,<br/>Christ would have given Himself, still, in love.<br/>He lived and died making all of us one,<br/>His life and living God’s gift from above.<br/>',NULL,53056,7);
INSERT INTO stanza VALUES('NS652','1','Set your mind on the things which are above,<br/>Not on the things which are on the earth.<br/>For you died, and your life is<br/>Hidden with Christ in God.<br/>',NULL,53057,1);
INSERT INTO stanza VALUES('NS652','2','Set your mind on the things which are above,<br/>Not on the things which are on the earth.<br/>For you died, and your life is<br/>Hidden with Christ in God.<br/>',NULL,53058,2);
INSERT INTO stanza VALUES('NS652','3','For you died, For you died,<br/>For you died, and your life is hidden with Christ in God.<br/>',NULL,53059,3);
INSERT INTO stanza VALUES('NS652','4','Set your mind on the things which are above,<br/>Not on the things which are on the earth.<br/>For you died, and your life is<br/>Hidden with Christ in God.<br/>',NULL,53060,4);
INSERT INTO stanza VALUES('NS653','1','Lord, thank You for a new day for me to take You as Lord.<br/>I subject myself under Your headship for the whole day.<br/>Lord, set up Your throne in my life, Set up<br/>Your throne at the center of my being.<br/>Bring my whole day with my daily life<br/>Under Your throne.<br/><br/>Lord, set up Your throne in my life, Set up<br/>Your throne at the center of my being.<br/>Bring my whole day with my daily life<br/>Under Your throne.<br/>',NULL,53061,1);
INSERT INTO stanza VALUES('NS654','1','God’s heart’s desire, a house on earth,<br/>Mutual abode of God and of man;<br/>For He is pleased, that we may be,<br/>Joined with our God, a mingling to be<br/>A temple where His interests are met,<br/>Yet while here we rest, who for God will care?<br/>So dear Lord, we bear, Thy building and plan,<br/>Working with Thee, Thy will to fulfill!<br/>',NULL,53062,1);
INSERT INTO stanza VALUES('NS654','chorus','Dear Lord, we waste ourselves upon Thee,<br/>All our lives for Thine eternal will!<br/>For Thy love, Lord, constrains us all,<br/>To make way for Thy house and Thy will!<br/>Let’s arise! It’s time to build!<br/>For His dwelling place we give all!<br/>Standing firm, fulfilling the pleasure of God,<br/>New Jerusalem!<br/>',NULL,53063,2);
INSERT INTO stanza VALUES('NS654','2','For God’s dispensing, we have been,<br/>Made into vessels open to Him;<br/>His element is wrought in us,<br/>Making us living stones, corporately;<br/>Being saved from self, the flesh and its will,<br/>It’s no longer I, but Christ lives in me;<br/>Members of the Body, built up in love,<br/>Joined to be one, for Him corporately.<br/>',NULL,53064,3);
INSERT INTO stanza VALUES('NS654','3','Lord, as a living sacrifice,<br/>We will be perfected by Thee<br/>To build Thy Body, seek increase,<br/>Lord, the commission now we receive<br/>In spirit, soul, we’re one for His goal,<br/>The lampstands to spread His recovery,<br/>A local being, a global seeing,<br/>Gospel in hand, the kingdom we’ll preach!<br/>',NULL,53065,4);
INSERT INTO stanza VALUES('NS655','1','These are the generations of Noah,<br/>Noah was a righteous man,<br/>Blameless in his generations;<br/>And Noah walked with God.<br/>',NULL,53066,1);
INSERT INTO stanza VALUES('NS655','chorus','Noah walked with God and found favor in His sight,<br/>Noah walked with God and found grace in His eyes,<br/>Now today we can also find favor in His sight,<br/>Let us find grace in Jehovah’s eyes.<br/>',NULL,53067,2);
INSERT INTO stanza VALUES('NS655','2','May we be the generation<br/>God will use to turn this age,<br/>Blameless in our generations,<br/>Those who walk with God and consecrate.<br/>',NULL,53068,3);
INSERT INTO stanza VALUES('NS655','chorus','Noah walked with God and found favor in His sight,<br/>Noah walked with God and found grace in His eyes,<br/>Now today we can also find favor in His sight,<br/>Let us find grace in Jehovah’s eyes.<br/>',NULL,53069,4);
INSERT INTO stanza VALUES('NS656','1','Making known to us<br/>The mystery of His will<br/>According to His good pleasure,<br/>Which He purposed in Himself,<br/>',NULL,53070,1);
INSERT INTO stanza VALUES('NS656','2','Unto the economy of the fullness of the times,<br/>To head up all things in Christ,<br/>The things in the heavens<br/>And the things on the earth,<br/>In Him, in Him,<br/>',NULL,53071,2);
INSERT INTO stanza VALUES('NS656','end-note','(repeat)<br/>',NULL,53072,3);
INSERT INTO stanza VALUES('NS656','chorus','In Him.<br/>',NULL,53073,4);
INSERT INTO stanza VALUES('NS657','1','How can I say how much I love You?<br/>What words express the way I feel?<br/>How can I say how much I need You?<br/>The words I use at times don’t seem so real!<br/>But I’m just going to say them any way!<br/>I love You Lord, with each new living day.<br/>The words I use are just the words You planted deep in me.<br/>I love You Lord with Your own love in me.<br/>Again I’ll say, Jesus, I love You,<br/>In spirit, Lord, and with my soul,<br/>And as I speak I am so happy<br/>That by Your life in me this love I know!<br/>',NULL,53074,1);
INSERT INTO stanza VALUES('NS658','1','You seek Me not because<br/>you have seen signs,<br/>You seek Me because you<br/>ate of the bread and were filled.<br/>',NULL,53075,1);
INSERT INTO stanza VALUES('NS658','2','Work not for the food which perishes,<br/>But for the food which abides<br/>unto eternal life.<br/>',NULL,53076,2);
INSERT INTO stanza VALUES('NS659','1','Lord, Your presence provides an atmosphere<br/>Of Your tenderness and warmth to us.<br/>As You cherish our whole being,<br/>You give rest and comfort,<br/>Healing, cleansing too.<br/>We’re encouraged, so we can now enjoy<br/>This atmosphere of cherishing.<br/>Lord, Your presence in the<br/>Lampstands makes us comfortable,<br/>Happy and pleasant too.<br/>',NULL,53077,1);
INSERT INTO stanza VALUES('NS659','chorus','Overcomers, overcomers,<br/>Overcomers is Your need.<br/>As we heed Your call, Lord Jesus,<br/>Overcomers we may be.<br/>',NULL,53078,2);
INSERT INTO stanza VALUES('NS659','2','Lord, You also are judging us today.<br/>As Your church, Lord, take us all the way.<br/>As You judge by cutting, snuffing, trimming<br/>Out the negatives we now MUST PRAY.<br/>Lord, we all want to let You LOOK AT US.<br/>Lord, expose the degradation thus,<br/>Judge our living, working;<br/>Let us also hear Your voice,<br/>Your work in us be done.<br/>',NULL,53079,3);
INSERT INTO stanza VALUES('NS660','1','Lord, I seek Your will<br/>And Your will alone.<br/>Though there’s times I hold my ground<br/>And block the way.<br/>Lord, wait longer than I<br/>Until Your way You’ve gained,<br/>Until Your way You’ve gained.<br/>',NULL,53080,1);
INSERT INTO stanza VALUES('NS660','2','This naturalness within<br/>Disguises my intentions.<br/>It’s a mixture of soul.<br/>Show me where You lie<br/>And I’ll discover there<br/>Alone my hearts true delight,<br/>Alone my hearts true delight.<br/>',NULL,53081,2);
INSERT INTO stanza VALUES('NS660','3','May I not rush the night;<br/>Though signs I may not see,<br/>Yet Lord I trust You will<br/>End my soulish source<br/>And with the morning light<br/>Resurrection will remain,<br/>Resurrection will remain.<br/>',NULL,53082,3);
INSERT INTO stanza VALUES('NS660','4','So I resign this day<br/>The ruling of my life;<br/>Lord, You will meet my need.<br/>Faithful unto God,<br/>You make me so content<br/>When Your heart’s satisfied.<br/>When Your heart’s satisfied.<br/>',NULL,53083,4);
INSERT INTO stanza VALUES('NS661','1','Lord, my eyes are seeing,<br/>Lord, my ears are hearing,<br/>All that You’ve been speaking,<br/>My heart’s understanding, too.<br/>Finally, I am turning,<br/>Willing to be healed by You.<br/>Thank You for Your waiting,<br/>Arranging everything I’d do.<br/>',NULL,53084,1);
INSERT INTO stanza VALUES('NS661','chorus','Now Lord, my heart<br/>Cries out for Your loving hand.<br/>And Lord, Amen,<br/>I’d be touched by You.<br/>',NULL,53085,2);
INSERT INTO stanza VALUES('NS661','2','Lord, I’ve been so hardened,<br/>Caught in worldly traffic,<br/>Drowning out Your words that<br/>Fell upon my wayward heart.<br/>Somehow, still You got in,<br/>Soft’ning up my tender parts.<br/>How could I refuse You?<br/>You bore me on Your wounded heart.<br/>',NULL,53086,3);
INSERT INTO stanza VALUES('NS661','3','I thought I was willing,<br/>Shallowly receiving,<br/>Meanwhile I was sinning,<br/>Burying my shameful side.<br/>But the sun exposed me,<br/>Now I can no longer hide.<br/>Bare without Your presence,<br/>For dire help to You I fly.<br/>',NULL,53087,4);
INSERT INTO stanza VALUES('NS661','4','Everything seemed peaceful,<br/>Till Your words intruded,<br/>Anxious thoughts arose and<br/>Tried to choke the life away.<br/>Lifelessly I drifted,<br/>Couldn’t tell the night from day.<br/>Then a ray of light came,<br/>Shining through a man of clay.<br/>',NULL,53088,5);
INSERT INTO stanza VALUES('NS661','5','Oh, the time I wasted,<br/>Trying to be better.<br/>All along You waited,<br/>Just for me to reach my end.<br/>Now I simply open,<br/>Trusting in my truest Friend.<br/>Hold me by Your mercy,<br/>Bear fruit in me until the end.<br/>',NULL,53089,6);
INSERT INTO stanza VALUES('NS661','chorus','Now Lord, my heart<br/>Overflows with a praising song!<br/>For Lord, I know,<br/>I’ve been touched by You.<br/>',NULL,53090,7);
INSERT INTO stanza VALUES('NS662','1','I will also give you<br/>A new heart, and a new spirit<br/>I’ll put within you,<br/>put within you;<br/>And I will take away the heart,<br/>The heart of stone out of your flesh,<br/>And I will give you a heart of flesh.<br/>',NULL,53091,1);
INSERT INTO stanza VALUES('NS662','2','And I will put My Spirit within you<br/>And cause you to walk in My statutes,<br/>walk in My statutes,<br/>And I will put My Spirit within you<br/>My ordinances you shall keep and do.<br/>And I will put My Spirit within you,<br/>And I will put My Spirit within you.<br/>',NULL,53092,2);
INSERT INTO stanza VALUES('NS663','1','God grants us to be strengthened<br/>Into the inner man<br/>With power, through His Spirit,<br/>To carry out His plan<br/>That Christ would make His home in<br/>Our hearts through faith each day,<br/>That we’d lay hold of Him and<br/>God’s love would know for aye.<br/>',NULL,53093,1);
INSERT INTO stanza VALUES('NS663','2','By Christ’s indwelling Spirit,<br/>We’re strong to apprehend<br/>His magnitude and substance,<br/>Dimensions without end;<br/>His love surpasses knowledge,<br/>Yet naught would He conceal;<br/>He fills us in our spirit,<br/>God’s fullness to reveal.<br/>',NULL,53094,2);
INSERT INTO stanza VALUES('NS663','3','Christ is our life and person,<br/>Head of the one new man<br/>Created in Himself, where<br/>Our corporate life began.<br/>We’re rooted and we’re grounded<br/>In Christ, God’s Firstborn Son;<br/>We, in His love, enjoy Him,<br/>We, in His life, are one.<br/>',NULL,53095,3);
INSERT INTO stanza VALUES('NS663','4','We exercise our spirit<br/>That Christ indwell our hearts<br/>To spread throughout our being<br/>To all our inward parts,<br/>His life substantiating—<br/>Mysterious, unseen—<br/>By Him as faith, perceiving<br/>God’s bounty unforeseen.<br/>',NULL,53096,4);
INSERT INTO stanza VALUES('NS663','5','This metabolic process<br/>Is constituting us<br/>With Christ in all His riches<br/>Through our enjoyment thus;<br/>The church in our experience<br/>Is full of God expressed,<br/>For Christ is God embodied,<br/>Made known and manifest.<br/>',NULL,53097,5);
INSERT INTO stanza VALUES('NS663','6','Above all we could ask for<br/>Or think of in this age,<br/>God’s work exceeds our measure;<br/>He molds us, stage by stage.<br/>God’s resurrection power<br/>Within us operates.<br/>We give God all the glory,<br/>From whom all emanates.<br/>',NULL,53098,6);
INSERT INTO stanza VALUES('NS664','1','Lord, bring forth the one new man;<br/>Grant this vision now to us.<br/>Gain in us Thy heart’s desire—<br/>Thine expression glorious.<br/>',NULL,53099,1);
INSERT INTO stanza VALUES('NS664','2','When Thou first didst man create,<br/>Thine own likeness to possess,<br/>Thine intention was that he<br/>Take Thee in and Thee express.<br/>',NULL,53100,2);
INSERT INTO stanza VALUES('NS664','3','But, instead, man was deceived,<br/>To the knowledge-tree misled.<br/>Then, Thy plan he did forsake;<br/>To the self he’d live instead.<br/>',NULL,53101,3);
INSERT INTO stanza VALUES('NS664','4','So, Thou in the flesh didst come,<br/>Mingling with humanity,<br/>Living to the Father’s will,<br/>God’s intent accomplishing.<br/>',NULL,53102,4);
INSERT INTO stanza VALUES('NS664','5','First, Thou to the cross didst go,<br/>Our old man to terminate;<br/>Then, in resurrection, come,<br/>Thy new man to germinate.<br/>',NULL,53103,5);
INSERT INTO stanza VALUES('NS664','6','Now Thou in our spirit art,<br/>As the inner man within;<br/>As our heart becomes Thine home,<br/>Thou dost live and rule therein.<br/>',NULL,53104,6);
INSERT INTO stanza VALUES('NS664','7','Spread within us, Lord, we pray;<br/>Gain the ground in all our heart.<br/>We’d the self deny always,<br/>That Thyself Thou wouldst impart.<br/>',NULL,53105,7);
INSERT INTO stanza VALUES('NS664','8','We’d allow Thy peace to reign,<br/>In the Body-life we’d live;<br/>No more self-directed be,<br/>For Thy church our all we’d give.<br/>',NULL,53106,8);
INSERT INTO stanza VALUES('NS664','9','Be the person of our heart;<br/>Manifest Thyself through us.<br/>Build the saints into Thine house<br/>That we’d bear Thine image thus.<br/>',NULL,53107,9);
INSERT INTO stanza VALUES('NS664','10','Consummate Thy central work<br/>That we’d match Thee perfectly;<br/>Thus, the church would builded be—<br/>One new man eternally.<br/>',NULL,53108,10);
INSERT INTO stanza VALUES('NS665','1','Through the blood, I come to You, Lord,<br/>To Your throne of grace in prayer;<br/>How I need Your tender mercies,<br/>Timely grace, and loving care!<br/>Cover me, for I am helpless.<br/>Hide me as my heart I bare.<br/>Cling to me in loving kindness.<br/>Be my shield from every snare.<br/>',NULL,53109,1);
INSERT INTO stanza VALUES('NS665','2','My habitual, heedless conduct<br/>Full of self has ever been.<br/>I abhor that I could stumble<br/>Even one due to this sin.<br/>I confess that I’m a sinner—<br/>Laying hands on You within.<br/>Wash me clean till I am spotless<br/>And restore my inner man!<br/>',NULL,53110,2);
INSERT INTO stanza VALUES('NS665','3','In my spirit, by Your mercy,<br/>Shine upon my wayward heart.<br/>Break the independent nature<br/>Of my soul, each inward part.<br/>Make me one who cares for others,<br/>Nurturing, to life impart,<br/>Buoyant with Your living Spirit,<br/>Cherishing this fresh new start.<br/>',NULL,53111,3);
INSERT INTO stanza VALUES('NS665','4','Lord, I turn my whole heart, yielding<br/>To You, for Your masterpiece.<br/>In Your light comes understanding;<br/>You forgive and joy increase.<br/>My mind setting on my spirit,<br/>I can sense Your life and peace;<br/>Turning to You in my spirit,<br/>I find You, my true release.<br/>',NULL,53112,4);
INSERT INTO stanza VALUES('NS665','5','Lord, You’ve been my only comfort.<br/>Even now You comfort me.<br/>I cannot be lost and mournful.<br/>I love You increasingly.<br/>Your dear blood does cleanse me wholly,<br/>White as snow effectively.<br/>I stand with Your inward working,<br/>I in You and You in me.<br/>',NULL,53113,5);
INSERT INTO stanza VALUES('NS665','6','I agree with what You’re speaking<br/>In my heart, and in Your Word.<br/>You alone are sanctuary,<br/>Your dear presence joy assured.<br/>What You are imbues me sweetly.<br/>I will rest in what I’ve heard—<br/>Private, wooing words, like kisses,<br/>Touching depths, with love conferred.<br/>',NULL,53114,6);
INSERT INTO stanza VALUES('NS665','7','Through Your precious blood, I come Lord<br/>To Your dear and lovely face.<br/>I love You for You love deeply,<br/>Holding me in Your embrace.<br/>Heav’n and earth may bear this witness—<br/>Here, the object of Your grace<br/>Is myself, blood-washed, enlivened,<br/>Full of joy, Your joy to trace.<br/>',NULL,53115,7);
INSERT INTO stanza VALUES('NS666','1','I am made so awesomely<br/>And so wonderf’ly—<br/>Inward parts and hidden part—<br/>That I might know Thee.<br/>Jesus, Lord, I come to Thee,<br/>With an open heart.<br/>I, my spirit exercise—<br/>Inward, hidden parts.<br/>',NULL,53116,1);
INSERT INTO stanza VALUES('NS666','2','Lord, I turn my heart to Thee.<br/>Take my veils away,<br/>Purify my heart to see<br/>Thee through all my days.<br/>Lord, I give my heart to Thee.<br/>How I love Thee so!<br/>Make Thy home in all my heart,<br/>Through my being flow.<br/>',NULL,53117,2);
INSERT INTO stanza VALUES('NS666','3','I, my spirit exercise,<br/>Nothing outwardly.<br/>By my spirit’s function—three—<br/>I may contact Thee.<br/>Touch my conscience thoroughly.<br/>I, my sins confess.<br/>Enter into fellowship,<br/>Oneness with Thee sense.<br/>',NULL,53118,3);
INSERT INTO stanza VALUES('NS666','4','Living God, I come to Thee.<br/>From dead works save me.<br/>Purify my conscience, Lord,<br/>That I might serve Thee.<br/>Daily, I now exercise<br/>All sins to confess.<br/>That my conscience clear may be,<br/>Void of all offense.<br/>',NULL,53119,4);
INSERT INTO stanza VALUES('NS666','5','Now I am in Penuel,<br/>Face to face with God.<br/>With an open, loving heart,<br/>Spirit exercised.<br/>Conscience, mind, emotion, will,<br/>I will dig away,<br/>That through me Thou may’st flow<br/>Freely day by day.<br/>',NULL,53120,5);
INSERT INTO stanza VALUES('NS666','chorus','Jesus, Lord, I come to Thee,<br/>With an open heart.<br/>I, my spirit exercise—<br/>Inward, hidden parts.<br/>',NULL,53121,6);
INSERT INTO stanza VALUES('NS667','1','Seek ye the Lord all ye people,<br/>Turn to Him while He is near,<br/>Let the wicked forsake his own way,<br/>And call on Him while He may hear.<br/>Ho, everyone who is thirsty,<br/>Come to the waters of life,<br/>Come and drink of the milk and the wine,<br/>Come without money and price.<br/>',NULL,53122,1);
INSERT INTO stanza VALUES('NS667','chorus','And there is peace like a river,<br/>And glory divine,<br/>If you’ll come to the water,<br/>If you’ll taste of His wine,<br/>There is love ever flowing,<br/>And joy ever full,<br/>And there’s life everlasting<br/>For us all.<br/>',NULL,53123,2);
INSERT INTO stanza VALUES('NS667','2','For you shall go out in joy,<br/>And be led forth in peace.<br/>The mountains and hills before you shall sing,<br/>And the trees of the fields clap their hands.<br/>Instead of the thorns shall come cypress,<br/>And myrtle replace every brier,<br/>And it shall be to remember the Lord,<br/>And everlasting sign.<br/>',NULL,53124,3);
INSERT INTO stanza VALUES('NS668','1','Live through me, Lord! Though old man’s termination<br/>Brought to an end my life apart from Thee,<br/>Yet, joined to Thee, I still need transformation<br/>To shine Thee forth with all saints corporately.<br/>',NULL,53125,1);
INSERT INTO stanza VALUES('NS668','2','Live through me, Lord; let self no longer bind Thee;<br/>Remove all traces of its hold on me.<br/>Be magnified in every word and action;<br/>In me, Thy living manifested be.<br/>',NULL,53126,2);
INSERT INTO stanza VALUES('NS668','3','Live through me, Lord; my soul be emptied wholly,<br/>All pleasures and self-seeking put away;<br/>Be Thou my aim and satisfaction solely,<br/>Our loving union e’er through me convey.<br/>',NULL,53127,3);
INSERT INTO stanza VALUES('NS668','4','Live through me, Lord, and make my heart Thy dwelling,<br/>Each chamber fully occupied by Thee;<br/>Thought, feeling, will, infuse with Thee completely<br/>Till we’ve one living out unceasingly.<br/>',NULL,53128,4);
INSERT INTO stanza VALUES('NS668','5','Live through me, Lord; stop independent action;<br/>Each breath, each step, would in Thy Body be.<br/>Build us in Thee till we’re Thy full reflection,<br/>Thy corporate one new man eternally.<br/>',NULL,53129,5);
INSERT INTO stanza VALUES('NS669','1','Lord, You give based on who You are,<br/>Not by anything that I deserve.<br/>Lord, it is not by self effort<br/>Or by any merit of my own, but...<br/>',NULL,53130,1);
INSERT INTO stanza VALUES('NS669','chorus','You are the Ruler and the King of the universe.<br/>It is Your word that will last.<br/>You are the Master and the Shepherd of the flock.<br/>It is not my will, but Yours, that stands.<br/>And You are in charge.<br/>',NULL,53131,2);
INSERT INTO stanza VALUES('NS669','2','Lord, even though I tend to doubt,<br/>I believe Your heart for me is good, and<br/>Lord, I know You do all things well,<br/>So I offer myself willingly, cause...<br/>',NULL,53132,3);
INSERT INTO stanza VALUES('NS669','3','Lord, I trust in Your perfect will,<br/>Because all Your thoughts surpass my highest.<br/>Lord, I may never understand,<br/>Why You act the way You do, but I know...<br/>',NULL,53133,4);
INSERT INTO stanza VALUES('NS669','4','Lord, thank You for Your good pleasure.<br/>I can trust that all You do is for it.<br/>So, if it makes You happy, Lord,<br/>I will step aside to let You be my God.<br/>',NULL,53134,5);
INSERT INTO stanza VALUES('NS670','1','God’s loving seekers will receive,<br/>God’s blessing of the light;<br/>When in God’s Word we are immersed,<br/>Light shines and life supplies.<br/>',NULL,53135,1);
INSERT INTO stanza VALUES('NS670','chorus','God’s loving seekers in the Word,<br/>Enter a realm of light and life,<br/>And they will walk in this light!<br/>',NULL,53136,2);
INSERT INTO stanza VALUES('NS670','2','God’s loving seekers can receive<br/>The water in God’s Word;<br/>As we are watered in the Word<br/>God’s person is absorbed.<br/>',NULL,53137,3);
INSERT INTO stanza VALUES('NS670','3','God’s loving seekers, in the Word,<br/>Receive the Spirit’s breath;<br/>When we inhale the living Word<br/>We exhale sin and death.<br/>',NULL,53138,4);
INSERT INTO stanza VALUES('NS670','4','God’s loving seekers will enjoy<br/>Great blessing rich and full;<br/>God as the Author is conveyed,<br/>Our portion, wonderful.<br/>',NULL,53139,5);
INSERT INTO stanza VALUES('NS670','5','The loving seekers of God’s Word,<br/>Will often see God’s face;<br/>His countenance, when lifted up,<br/>Infuse His loving grace.<br/>',NULL,53140,6);
INSERT INTO stanza VALUES('NS670','end-note','(Do not repeat Chorus after verse 5)<br/>',NULL,53141,7);
INSERT INTO stanza VALUES('NS671','1','In God’s economy,<br/>The Lord is all there is,<br/>One Person with one way, in all,<br/>The God-man living His.<br/>God does not give us things—<br/>He only gives us Christ.<br/>God’s gift, the Lord and Head of all,<br/>In all things does suffice.<br/>',NULL,53142,1);
INSERT INTO stanza VALUES('NS671','2','There’s only room for Christ,<br/>The One who’s all in all.<br/>In Him, the natural man is null<br/>And has no place at all.<br/>In Christ, there is no Jew,<br/>No Greek, no slave, no free,<br/>Barbarians and Scythians—<br/>Crossed out entirely.<br/>',NULL,53143,2);
INSERT INTO stanza VALUES('NS671','3','All differences we see<br/>In culture, practice, creed<br/>Are not in Christ, our Lord and Head—<br/>From oldness these proceed.<br/>Distinctions have no place<br/>In Christ, nor in the saints.<br/>Our nature is the very same,<br/>As oneness demonstrates.<br/>',NULL,53144,3);
INSERT INTO stanza VALUES('NS671','4','God governs and He deals<br/>With all things by the cross.<br/>It’s God’s unique solution for<br/>The substitutes in us.<br/>The cross becomes our way<br/>To put off all things old,<br/>To live in resurrection till<br/>Christ in us all behold.<br/>',NULL,53145,4);
INSERT INTO stanza VALUES('NS671','5','Put on the one new man,<br/>The old man strip away.<br/>Pass through the cross to take Christ as<br/>Our Person now today.<br/>The Spirit with the cross<br/>Is our unique supply<br/>That causes us to be renewed<br/>As one new man thereby.<br/>',NULL,53146,5);
INSERT INTO stanza VALUES('NS671','6','The practicality<br/>Of passing through the cross<br/>Is in the mingling that blends<br/>God’s essence into us.<br/>The key is be renewed!<br/>We have the mind of Christ!<br/>The newness of God’s life, imbued,<br/>Renews and rectifies.<br/>',NULL,53147,6);
INSERT INTO stanza VALUES('NS671','7','Put off the old today<br/>And every day beyond.<br/>But set your mind on spirit now<br/>And to God’s life respond.<br/>Enjoy the Lord and drink<br/>The Spirit till you’re new,<br/>To think the one thing with all saints,<br/>With God soaked through and through.<br/>',NULL,53148,7);
INSERT INTO stanza VALUES('NS671','8','Christ is the One we love,<br/>The One whom we pursue.<br/>There’s nothing else that we desire<br/>But Christ, who’s ever new.<br/>God sees us all in Christ,<br/>The status we convey;<br/>Christ and His cross are all we have—<br/>One Person and one way.<br/>',NULL,53149,8);
INSERT INTO stanza VALUES('NS672','1','The Word is living, a divine Person—<br/>Christ the Son of God, the living God.<br/>It is God defined, explained, and expressed<br/>When the Word comes, God comes.<br/>When the Word is present, God is present.<br/>',NULL,53150,1);
INSERT INTO stanza VALUES('NS672','chorus','So let the Word of Christ dwell in you (richly!)<br/>In all wisdom, teaching, admonishing<br/>Each one the other with psalms and hymns;<br/>Singing with grace, sing with grace to God<br/>in your hearts to God.<br/>(on last chorus)<br/>(To God.)<br/>',NULL,53151,2);
INSERT INTO stanza VALUES('NS672','2','The Word received is life and Spirit.<br/>Our spirit we must exercise<br/>To receive the life embodied in the Word.<br/>Read, eat, breathe, everyday;<br/>To take God in His Word is necessary.<br/>',NULL,53152,3);
INSERT INTO stanza VALUES('NS672','3','The Word we speak is the Lord Jesus,<br/>Him who we’ve known, we testify,<br/>Building up the church as prophesied.<br/>As we speak, Satan flees;<br/>Speaking God defeats the enemy.<br/>',NULL,53153,4);
INSERT INTO stanza VALUES('NS673','chorus','Producing overcomers is God’s move on earth today;<br/>Living and active, they live and serve in a vital way,<br/>Shepherd ’ccording to God, to build up Christ’s Body corp’rately.<br/>We all need to be in Christ’s heav’nly ministry.<br/>One with the interceding Christ, to carry out God’s admin’stration,<br/>Carry out God’s administration for His economy.<br/>As God’s redeemed, sanctified elect, His holy army arrayed we stand,<br/>And in the energizing God, we move, we battle, we take the land.<br/>We must move today in the wheel of God’s ultimate move,<br/>Go forth, disciple all nations, teach the divine truths,<br/>The kingdom’s gospel spread to all earth inhabited,<br/>Till lampstands shine throughout all the earth,<br/>Hasten the day of the Lord’s return,<br/>Hasten the day of His return!<br/>',NULL,53154,1);
INSERT INTO stanza VALUES('NS674','1','Lord Jesus, I love You.<br/>Thank You for this start.<br/>Dew of Mercy, come to<br/>Make home in my heart;<br/>I praise You, Lord Jesus.<br/>Gain ground in me today;<br/>With You, one spirit, I’d stay.<br/>',NULL,53155,1);
INSERT INTO stanza VALUES('NS675','1','The Bible shows that man was made<br/>To simply enter into rest.<br/>The Sabbath was man’s first full day,<br/>God had prepared for him the best.<br/>All had been done, there was no need<br/>For man to work but rest with God.<br/>This is our life today, right now!<br/>How wonderful, He’s done it all!<br/>',NULL,53156,1);
INSERT INTO stanza VALUES('NS675','chorus','There’s no need to struggle!<br/>There’s no need to strain!<br/>There’s no need to labor,<br/>All self-effort is vain!<br/>It’s a life of resting!<br/>It’s a life of feasting!<br/>It’s a life of enjoying God!<br/>',NULL,53157,2);
INSERT INTO stanza VALUES('NS675','2','We once tried doing what was good<br/>But right and wrong are just one tree.<br/>Instead, we eat the tree of life,<br/>And take God in, receive, believe!<br/>No longer I—I’m crucified,<br/>But it is Christ who lives in me.<br/>No need to try to imitate,<br/>He is displayed spontaneously!<br/>',NULL,53158,3);
INSERT INTO stanza VALUES('NS675','3','We have been grafted to a tree.<br/>The Lord, the vine, does flow so free<br/>With all His riches into us.<br/>Positioned now, we just receive.<br/>He is the place for us to stay;<br/>As we remain, much fruit we bear.<br/>Abide in Him, let Him abide,<br/>Such sweet supply, His life to share!<br/>',NULL,53159,4);
INSERT INTO stanza VALUES('NS675','4','Though we still err, so prone to fail,<br/>God’s given us a testament<br/>Of all He’s done for us to claim.<br/>Let’s seize it to the full extent!<br/>When we fall short and miss the mark,<br/>We take the blood, He paid the cost.<br/>From scarlet stain to pure white snow,<br/>How powerful! We’re cleansed, we’re washed!<br/>',NULL,53160,5);
INSERT INTO stanza VALUES('NS675','5','We’re free, unbound from chains that held.<br/>We have returned from slavery.<br/>Such joy, such rest! We’re home, how blessed!<br/>It’s Christ! He’s here as Jubilee!<br/>A feast is spread, it’s Christ Himself,<br/>Our food, our drink eternally.<br/>No condemnation but a call<br/>To eat and drink and merry be!<br/>',NULL,53161,6);
INSERT INTO stanza VALUES('NS676','1','Who can match the “waste” He tendered,<br/>Willingly so much surrender?<br/>Who can count the fruit of His labor?<br/>Who else can such rich harvest render?<br/>Though all drank, the cup’s o’erflowing;<br/>Though all ate, the table’s loaded;<br/>He sought nothing, yet caused others’ blessing,<br/>Ne’er sought payment, to others dispensing.<br/>Free from bondage and frustration,<br/>Free from sorrow and vexation,<br/>E’er outpouring, love bestowing,<br/>Ever surging, ever o’erflowing.<br/><br/>To flow out this life, He was willing to taste death,<br/>To be broken that resurrection’s fragrance spread.<br/>These are just the footsteps You left behind,<br/>Quietly calling, “Follow Me.”<br/>From their shining faces we can see<br/>Just how glorious this path’s end will be.<br/><br/>I’ve clearly counted the cost to take this way,<br/>And gladly now all for You lay down today;<br/>Just a drink offering, joy to others I’d bring,<br/>Ceaselessly pouring out through all my days;<br/>Let me love, O Lord! You be my reward!<br/>Let Your presence forever with me stay.<br/>Cause me to maintain, Lord, Your joy within,<br/>Let eternity wash my tears away.<br/>',NULL,53162,1);
INSERT INTO stanza VALUES('NS677','chorus','’Tis because Thou drawest me<br/>I can closely follow Thee;<br/>Thy forbearance can appraise,<br/>Thee experience all my days.<br/>Henna flow’r, Thy loveliness<br/>Beautifies earth’s wilderness;<br/>Like the fragrant myrrh to me,<br/>In my heart I’ve hidden Thee.<br/>Hear, O Lord, my whispered plea:<br/>Henceforth I’ve no Lord but Thee;<br/>All Thy wealth is joy to me,<br/>By Thy life matured I’d be.<br/>',NULL,53163,1);
INSERT INTO stanza VALUES('NS678','1','Lord Jesus, thank You for this very day,<br/>I do believe in You; I do love You.<br/>Thank You that I can know what’s in Your heart:<br/>You want to make me one with You.<br/>I open my entire inner being,<br/>My every inward part is just for You.<br/>Is there a part You have not entered yet?<br/>I need Your shining to repent.<br/>',NULL,53164,1);
INSERT INTO stanza VALUES('NS678','chorus','Lord, here I am, I’m enterable.<br/>Saturate me and possess me today.<br/>Gain me, increase more in me,<br/>Make Yourself thus one with me.<br/>Lord, make me You, in life and nature,<br/>Deify me, Lord, and Christify me,<br/>Sonize me even today,<br/>For Your dear Body’s sake.<br/>',NULL,53165,2);
INSERT INTO stanza VALUES('NS678','2','Thank You for showing me Your heart’s desire:<br/>You would be one with me—I say, Amen!<br/>You’re fully able to accomplish this;<br/>Today, I give myself to You.<br/>To not live contradiction, I agree—<br/>With any kind of friction in my being.<br/>In all the ordinary things of life,<br/>Lord, make me always one with You.<br/>',NULL,53166,3);
INSERT INTO stanza VALUES('NS679','1','The grace of the Lord Jesus Christ<br/>And the love of God<br/>And the fellowship of the Holy Spirit<br/>Be with you all.<br/>',NULL,53167,1);
INSERT INTO stanza VALUES('NS679','2','Be with you all,<br/>Be with you all,<br/>The grace and the love and the fellowship<br/>Be with you all.<br/>',NULL,53168,2);
INSERT INTO stanza VALUES('NS679','3','The grace of the Lord Jesus Christ<br/>And the love of God<br/>And the fellowship of the Holy Spirit<br/>Be with you all.<br/>',NULL,53169,3);
INSERT INTO stanza VALUES('NS679','4','Amen,<br/>Amen,<br/>The grace and the love and the fellowship<br/>Be with you all.<br/>',NULL,53170,4);
INSERT INTO stanza VALUES('NS680','1','Lord, Your voice calls; we just obey;<br/>Our blest place has been prepared;<br/>Though my young heart may shrink or stray,<br/>Your restoring staff is there.<br/>In green pastures, by still waters,<br/>How Your presence comforts me.<br/>God’s dwelling place abounds with grace;<br/>Flock follow unswervingly.<br/>',NULL,53171,1);
INSERT INTO stanza VALUES('NS680','chorus','You say, “Closely follow the flock’s footsteps;”<br/>All the way, dear Shepherd, my footsteps guide;<br/>Shepherd me, Lord, and perfect, all my life;<br/>Lord, transform, mature me in life.<br/>',NULL,53172,2);
INSERT INTO stanza VALUES('NS680','2','Things on the way serve to expose<br/>Natural ability;<br/>My stubborn heart knows not Your will,<br/>With God wrestles tirelessly.<br/>Your hand touched my stubborn places,<br/>Transformed, to obed’ient be;<br/>Your word reveals, leads me to know: <br/>“My life-long Shepherd is Thee.<br/>',NULL,53173,3);
INSERT INTO stanza VALUES('NS680','3','Your love constrains, You gently urge,<br/>We are drawn as You adjure,<br/>To go in faith, as mothers, nurse,<br/>Feed, cherish, raise up, mature;<br/>In love pay the price, work gladly.<br/>Praying, bear men to the Lord; <br/>Together tried, fear not defeat;<br/>Your coming is our reward.<br/>',NULL,53174,4);
INSERT INTO stanza VALUES('NS680','chorus','Oh, arise! In steps of the flock we move!<br/>Pour out all and work with You, Lord, in love;<br/>We, step by step, towards the goal, run the race;<br/>Our life for God’s dream consecrate.<br/>',NULL,53175,5);
INSERT INTO stanza VALUES('NS680','4','To build Your house, no more we roam,<br/>God’s dream’s fixed upon our soul;<br/>Cast off all weights, and run the race,<br/>The building’s our only goal.<br/>Pattern cheers, and we respond, renewed;<br/>As faith’s footsteps we accept,<br/>Follow the Lamb unto the end,<br/>That Holy City with You.<br/>',NULL,53176,6);
INSERT INTO stanza VALUES('NS681','1','Just to enjoy Thy word,<br/>I come to Thee, dear Lord;<br/>Spirit and life, I need to gain,<br/>Through Thee, O living Word!<br/>',NULL,53177,1);
INSERT INTO stanza VALUES('NS681','2','Just to enjoy Thy word,<br/>Thy Testaments for man—<br/>Spoken through men by Spirit borne—<br/>Reveal Thy hidden plan.<br/>',NULL,53178,2);
INSERT INTO stanza VALUES('NS681','3','Just to enjoy Thy word,<br/>Prophets spoke from of old<br/>The coming Savior of God’s plan;<br/>Now through the Son ‘tis told.<br/>',NULL,53179,3);
INSERT INTO stanza VALUES('NS681','4','Just to enjoy Thy word;<br/>God’s covenant to share;<br/>God’s promises made real through faith,<br/>Laid hold of by my prayer.<br/>',NULL,53180,4);
INSERT INTO stanza VALUES('NS681','5','Just to enjoy Thy Word;<br/>He’s God expressed, defined;<br/>My spirit with His Spirit joined,<br/>God’s grace I’ll surely find.<br/>',NULL,53181,5);
INSERT INTO stanza VALUES('NS681','6','Just to enjoy Thy word;<br/>Thy constant, written word,<br/>Mingled with prayer, becomes in me<br/>Thine instant, spoken word.<br/>',NULL,53182,6);
INSERT INTO stanza VALUES('NS681','7','Just to enjoy Thy word,<br/>Thy words anticipate,<br/>Cry out at dawn, and hope in them,<br/>On them to ruminate.<br/>',NULL,53183,7);
INSERT INTO stanza VALUES('NS681','8','Just to enjoy Thy word,<br/>The living God to see,<br/>As hart doth pant for cooling streams,<br/>I pant, O God, for Thee.<br/>',NULL,53184,8);
INSERT INTO stanza VALUES('NS681','9','Just to enjoy Thy word,<br/>Flooding my path with light;<br/>Let it pierce through, illuminate,<br/>Dispel my heart’s dark night.<br/>',NULL,53185,9);
INSERT INTO stanza VALUES('NS681','10','Just to enjoy Thy word,<br/>Do make my heart, good ground!<br/>Let Thy word’s seed take root and grow,<br/>That from me fruit abound.<br/>',NULL,53186,10);
INSERT INTO stanza VALUES('NS681','11','Just to enjoy Thy word,<br/>For Thou Thyself didst say,<br/>Man shall not live by bread alone,<br/>But by Thy word each day.<br/>',NULL,53187,11);
INSERT INTO stanza VALUES('NS681','12','Just to enjoy Thy word,<br/>Coming as crumbs, so small,<br/>Reaching me in my lowest state,<br/>To be my all in all.<br/>',NULL,53188,12);
INSERT INTO stanza VALUES('NS681','13','Just to enjoy Thy word,<br/>Thy lips bring words of grace;<br/>Sweeter than honey to my mouth,<br/>Oh, how it cheers always!<br/>',NULL,53189,13);
INSERT INTO stanza VALUES('NS681','14','Just to enjoy Thy word,<br/>I ate the words I found,<br/>And they became the gladness, joy,<br/>That makes my heart resound!<br/>',NULL,53190,14);
INSERT INTO stanza VALUES('NS681','15','Just to enjoy Thy word,<br/>Spirit’ual food to me—<br/>As guileless milk, then solid food—<br/>Unto maturity.<br/>',NULL,53191,15);
INSERT INTO stanza VALUES('NS681','16','Just to enjoy Thy word,<br/>A two-edged sword to me,<br/>Which divides spirit from the soul,<br/>My thoughts, intents to see.<br/>',NULL,53192,16);
INSERT INTO stanza VALUES('NS681','17','Just to enjoy Thy word,<br/>Thy Word instructeth me,<br/>It is God-breathed to make complete<br/>The man of God in me.<br/>',NULL,53193,17);
INSERT INTO stanza VALUES('NS681','18','Just to enjoy Thy word,<br/>God’s proclaimed Jubilee!<br/>From sin released, to land returned—<br/>We’re made God’s family!<br/>',NULL,53194,18);
INSERT INTO stanza VALUES('NS681','19','Just to enjoy Thy word,<br/>Which each day fresh does fall,<br/>As heaven’s manna coming down,<br/>To be our all in all.<br/>',NULL,53195,19);
INSERT INTO stanza VALUES('NS681','20','Just to enjoy Thy word,<br/>Save from fall’s sin and stain;<br/>Reconstitute with manna pure;<br/>Thy holy people gain.<br/>',NULL,53196,20);
INSERT INTO stanza VALUES('NS681','21','Just to enjoy Thy word,<br/>Our daily, sure supply;<br/>Eating this manna heavenly,<br/>Thy church we’ll build thereby.<br/>',NULL,53197,21);
INSERT INTO stanza VALUES('NS681','22','Just to enjoy Thy word,<br/>Hold forth the word of life;<br/>God’s luminaries, blameless, shine,<br/>Amidst this world of strife.<br/>',NULL,53198,22);
INSERT INTO stanza VALUES('NS681','23','Just to enjoy Thy word,<br/>With it, go forth to sow,<br/>Watering men’s hearts faithfully,<br/>That God may cause to grow.<br/>',NULL,53199,23);
INSERT INTO stanza VALUES('NS681','24','Just to enjoy Thy Word,<br/>Our hearts with love o’erflow,<br/>With one another, Christ we share,<br/>Thy Body thus doth grow.<br/>',NULL,53200,24);
INSERT INTO stanza VALUES('NS681','25','Just to enjoy Thy word,<br/>Let Christ’s word richly dwell,<br/>Speak, teach, admonish, sing with grace<br/>To saints and God as well.<br/>',NULL,53201,25);
INSERT INTO stanza VALUES('NS681','26','Just to enjoy Thy word;<br/>The speaking Spirit, hear;<br/>As Son of Man midst lampstands moves,<br/>Cares for His churches dear.<br/>',NULL,53202,26);
INSERT INTO stanza VALUES('NS681','27','Just to enjoy Thy word;<br/>Thy truth doth sanctify,<br/>Become our full reality,<br/>And oneness bring thereby.<br/>',NULL,53203,27);
INSERT INTO stanza VALUES('NS681','28','Just to enjoy Thy word,<br/>To be prepared His bride;<br/>We’re by its washing, cleansing pow’r<br/>Made holy, glorified!<br/>',NULL,53204,28);
INSERT INTO stanza VALUES('NS681','29','Just to enjoy Thy word,<br/>The Spirit’s sword receive;<br/>By means of prayer, petitioning,<br/>We victory achieve.<br/>',NULL,53205,29);
INSERT INTO stanza VALUES('NS681','30','Just to enjoy Thy word,<br/>Richly, in many ways,<br/>Till it is our memorial,<br/>Throughout eternal days.<br/>',NULL,53206,30);
INSERT INTO stanza VALUES('NS681','31','Just to enjoy Thy word,<br/>Faithful Thy surety;<br/>Though heav’n and earth shall pass away,<br/>It stands eternally.<br/>',NULL,53207,31);
INSERT INTO stanza VALUES('NS681','end-note','The following can be grouped together: Suggestion 1: Stanzas 1, 4-7, 30. Suggestion 2: Stanzas 1-17. Suggestion 3: Stanzas 2, 3, 18-31.<br/>',NULL,53208,32);
INSERT INTO stanza VALUES('NS682','1','Create in me a pure heart, O God,<br/>Fully empty my spirit within me;<br/>So pure in heart, I’d see Thee, solely;<br/>Poor in spirit, the kingdom I’d receive.<br/>',NULL,53209,1);
INSERT INTO stanza VALUES('NS682','chorus','Deliver me from all my iniquities;<br/>Take every veil and hindrance from me;<br/>My stone heart replaced, turned, single for Thy face,<br/>I’d behold and reflect Thee gloriously.<br/>',NULL,53210,2);
INSERT INTO stanza VALUES('NS682','2','Oh, purify my heart, Lord, wholly;<br/>Empty all of my spirit utterly;<br/>So pure in heart, I’d love Thee, supremely;<br/>Poor in spirit, the kingdom I’d receive.<br/>',NULL,53211,3);
INSERT INTO stanza VALUES('NS682','chorus','Unload everything from the depth of my being;<br/>Spirit of revelation give me;<br/>How blest to decrease, in spirit fully emptied,<br/>To receive Thy vast riches bountif’lly!<br/>',NULL,53212,4);
INSERT INTO stanza VALUES('NS682','3','Oh, purify our heart, Lord, wholly;<br/>Empty all of our spirit utterly;<br/>So pure in heart, we’d see You solely;<br/>Poor in spirit, the kingdom we’d receive.<br/>',NULL,53213,5);
INSERT INTO stanza VALUES('NS682','chorus','Lord, make us that people who’d give You the way<br/>To bring Your kingdom to earth, we pray;<br/>Your name sanctify; fulfill Your will divine;<br/>Quickly come for Your glorious wedding day.<br/>',NULL,53214,6);
INSERT INTO stanza VALUES('NS682','chorus','Lord, we’d be that people who’d give You the way<br/>To bring Your kingdom to earth today,<br/>Your name sanctify, fulfill Your will divine,<br/>And hasten Your glorious wedding day.<br/>',NULL,53215,7);
INSERT INTO stanza VALUES('NS683','1','How lovely are Your tabernacles,<br/>This my heart doth seek;<br/>Experience of Christ in all<br/>The offerings we bring.<br/>Once God as life supply,<br/>Now Eden’s ground withheld;<br/>To taste the tree of life requires<br/>An entrance once again.<br/>',NULL,53216,1);
INSERT INTO stanza VALUES('NS683','chorus','My soul, my soul longs<br/>For the courts of the Lord;<br/>My heart and flesh cry out<br/>To my God.<br/>',NULL,53217,2);
INSERT INTO stanza VALUES('NS683','2','At Thy two altars, e’en the<br/>Weakest sparrow may draw near.<br/>The swallow come for refuge and<br/>A nest for tender care.<br/>Redeemed may entrance find,<br/>And offer thus in prayer<br/>The resurrected Christ in His<br/>Ascension, fragrance rare.<br/>',NULL,53218,3);
INSERT INTO stanza VALUES('NS683','3','In our acceptance, God in peace<br/>Hath made a living way,<br/>Our boldness now for entering<br/>Within the Holiest Place.<br/>Tis’ here within the ark<br/>Eternal portion share.<br/>Incarnate Triune God and we<br/>One testimony bear.<br/>',NULL,53219,4);
INSERT INTO stanza VALUES('NS683','4','Eternally Thy house of rest;<br/>With God, now consummate,<br/>We’re mingled, one, incorp’rate<br/>In this mutual dwelling place.<br/>The priests who live to God<br/>Elect among man’s race.<br/>Now Christ’s own Body are,<br/>To have His foretaste in this age.<br/>',NULL,53220,5);
INSERT INTO stanza VALUES('NS684','chorus','By the grace of God I am what I am;<br/>And His grace unto me did not turn out to be<br/>In vain, but on the contrary,<br/>I labored more abundantly.<br/>',NULL,53221,1);
INSERT INTO stanza VALUES('NS684','1','Grace is not only something given by God,<br/>But it is God Himself coming to us;<br/>Grace is not only something given by God,<br/>But it is God Himself doing things for us.<br/>',NULL,53222,2);
INSERT INTO stanza VALUES('NS684','2','“How we need grace! Lord, I am here,<br/>I need Your grace, Lord, I am here.”<br/>',NULL,53223,3);
INSERT INTO stanza VALUES('NS684','3','Abundantly, abundantly, I labored more abundantly,<br/>Not I but the grace of God.<br/>Abundantly, abundantly, I labored more abundantly,<br/>Not I but the grace of God.<br/>',NULL,53224,4);
INSERT INTO stanza VALUES('NS685','1','Who can ever know the feeling deep down in my heart?<br/>Who can really understand my weakness to sustain?<br/>When I have lost hope to carry on by myself,<br/>Your person stands by me to be my hope and life.<br/>',NULL,53225,1);
INSERT INTO stanza VALUES('NS685','chorus','Your love so deep moving and sweet<br/>How can I still stubborn be;<br/>No more I struggle and strive,<br/>Trust in Your faith and rest in Your breast.<br/>',NULL,53226,2);
INSERT INTO stanza VALUES('NS685','2','When I feel the touch of Your hand upon my life,<br/>I sense the flow of life flowing rich and free;<br/>When You wipe away every tear in my eyes,<br/>Sorrow has depart’d, behold a smiling face!<br/>',NULL,53227,3);
INSERT INTO stanza VALUES('NS686','1','In Him who’s able,<br/>Full rest and perfect peace;<br/>In Him who’s faithful,<br/>Supply can never cease.<br/>I need not strive now,<br/>Self-effort, strength deplete.<br/>But to Him I bow,<br/>In the “I Am” believe.<br/>',NULL,53228,1);
INSERT INTO stanza VALUES('NS686','chorus','By faith I now see Him,<br/>Jehovah, Elohim;<br/>Fulfilling One He is,<br/>In all His promises.<br/>In all His promises.<br/>',NULL,53229,2);
INSERT INTO stanza VALUES('NS686','2','Those on my heart, I give<br/>To Him who will perfect,<br/>Ground, and establish,<br/>For these are His elect.<br/>Faithful is He who calls<br/>Who also will complete<br/>The good work in them all,<br/>Nothing unfinished leave.<br/>',NULL,53230,3);
INSERT INTO stanza VALUES('NS686','chorus','By faith I look away<br/>From change that seems halfway,<br/>But on faith’s Author gaze,<br/>Perfecter, all the way.<br/>Perfecter, all the way.<br/>',NULL,53231,4);
INSERT INTO stanza VALUES('NS686','3','I simply give my strength<br/>To Him, cooperate,<br/>Dropping my wings at length<br/>To let Him operate.<br/>’Tis He who causes growth,<br/>Not toil, struggle, strain,<br/>Nor strategies and goals,<br/>But letting His light reign.<br/>',NULL,53232,5);
INSERT INTO stanza VALUES('NS686','chorus','No darkness—all is light;<br/>’Tis He who gives the sight<br/>To see a vision bright<br/>Of only Jesus Christ.<br/>Of only Jesus Christ.<br/>',NULL,53233,6);
INSERT INTO stanza VALUES('NS686','4','I cannot help but praise,<br/>What wisdom manifest!<br/>The rightness of His ways<br/>I worship and attest.<br/>I can no more hold in<br/>My sacrifice of praise,<br/>For He has faithful been,<br/>And will remain always.<br/>',NULL,53234,7);
INSERT INTO stanza VALUES('NS686','chorus','Fruit of my lips to Him,<br/>Now overflows the brim;<br/>His throne on praise is raised.<br/>Out of my mouth, I praise,<br/>Yes, He’s perfected praise!<br/>',NULL,53235,8);
INSERT INTO stanza VALUES('NS687','1','Do you know that you<br/>have a special portion of Christ<br/>unique to you?<br/>And it may just be true<br/>that person ’cross the room can benefit<br/>from the Christ in you.<br/>',NULL,53236,1);
INSERT INTO stanza VALUES('NS687','chorus','Though you may have those butterflies,<br/>Or like me you may just be shy.<br/>Don’t you realize how much help you’ll give<br/>When your Christ in them will live.<br/>',NULL,53237,2);
INSERT INTO stanza VALUES('NS687','2','Do you know when we<br/>exercise our spirit with the saints<br/>our joy is made full.<br/>And that ministering<br/>our Christ to one another we’re built up<br/>into something eternal.<br/>',NULL,53238,3);
INSERT INTO stanza VALUES('NS687','chorus','This is God’s economy<br/>That you would be filled fully,<br/>Overflowing His rich dispensing,<br/>Build the Body corporately.<br/>',NULL,53239,4);
INSERT INTO stanza VALUES('NS687','3','Do you know it starts<br/>with our enjoyment of the Lord,<br/>to be filled with Him?<br/>And if we do our part<br/>to spend time to receive Him in the Word,<br/>we’ll spontaneously o’erflow Him.<br/>',NULL,53240,5);
INSERT INTO stanza VALUES('NS687','chorus','So why not turn to Christ right now?<br/>Simply eat Him that is how.<br/>If we’re soaked and filled up to the brim,<br/>We can’t help but express Him.<br/>',NULL,53241,6);
INSERT INTO stanza VALUES('NS687','chorus','This is God’s economy<br/>That you would be filled fully,<br/>Overflowing His rich dispensing,<br/>Build the Body corporately.<br/>',NULL,53242,7);
INSERT INTO stanza VALUES('NS688','chorus','Lord I am willing to let You<br/>love me more today,<br/>Your life operating in me,<br/>and You can have Your way.<br/>',NULL,53243,1);
INSERT INTO stanza VALUES('NS688','1','Lord I open up for You to make<br/>Your home in my heart li’l more today;<br/>Make me a part of Your move<br/>to build up Your church and bring the coming age.<br/>',NULL,53244,2);
INSERT INTO stanza VALUES('NS688','2','O Lord, have Your expression;<br/>Do not let me win today.<br/>Duplicate Your heart in my heart,<br/>Your life saturates and permeates.<br/>',NULL,53245,3);
INSERT INTO stanza VALUES('NS688','3','Your love is the burning fire;<br/>Things of my self You burn away.<br/>Do gain in me what You desire—<br/>A loving Bride to match You in every way.<br/>',NULL,53246,4);
INSERT INTO stanza VALUES('NS688','4','Lord I open up for You to make<br/>Your home in my heart li’l more today;<br/>Make me a part of Your move<br/>to build up Your church and bring the coming age.<br/>',NULL,53247,5);
INSERT INTO stanza VALUES('NS689','1','Lord, remove my veil;<br/>Let me clearly see You.<br/>Cast away my pride and anger,<br/>Keep me soft toward You.<br/>',NULL,53248,1);
INSERT INTO stanza VALUES('NS689','2','Lord, remove my veil;<br/>Let my mind be renewed.<br/>Cast away evil thoughts in my head, Lord.<br/>Fill me with Spirit full.<br/>',NULL,53249,2);
INSERT INTO stanza VALUES('NS689','3','Lord, remove my veil;<br/>Let me dearly behold You.<br/>Burn away any thorn in my heart, Lord,<br/>With Your love sweet and true.<br/>',NULL,53250,3);
INSERT INTO stanza VALUES('NS689','4','Lord, remove my veil;<br/>Make me deeply in love with You.<br/>Nothing else I desire but Your presence;<br/>Let me remain here with You.<br/>',NULL,53251,4);
INSERT INTO stanza VALUES('NS690','1','Make me an inward Christian, Lord,<br/>Weighty within I’d be;<br/>I’d do things from the deepest part,<br/>Live fully unto Thee.<br/>',NULL,53252,1);
INSERT INTO stanza VALUES('NS690','chorus','Paying attention to one thing—<br/>The wondrous Christ within,<br/>All persons, every matter, everything,<br/>Into the spirit bring.<br/>',NULL,53253,2);
INSERT INTO stanza VALUES('NS690','2','To not by knowledge, doctrine, live,<br/>But eat the tree of life;<br/>First caring for the flow within,<br/>Never by self to strive.<br/>',NULL,53254,3);
INSERT INTO stanza VALUES('NS690','3','Not outward changing of myself,<br/>But transformed inwardly,<br/>Not self improvement, self control,<br/>But Christ who reigns in me.<br/>',NULL,53255,4);
INSERT INTO stanza VALUES('NS690','4','Unfazed by outward sufferings,<br/>Glory to glory bring;<br/>Through Baca’s valley traveling,<br/>Yet making it a spring.<br/>',NULL,53256,5);
INSERT INTO stanza VALUES('NS690','5','Highways to Zion make my heart,<br/>From strength to strength each day<br/>Taking the church way inwardly,<br/>The inner life t’obey.<br/>',NULL,53257,6);
INSERT INTO stanza VALUES('NS690','6','Living in the reality,<br/>Though outward shell we see,<br/>On the intrinsic focusing,<br/>We’ll constituted be.<br/>',NULL,53258,7);
INSERT INTO stanza VALUES('NS691','1','The sins we commit must be washed.<br/>By His shining, we see one by one.<br/>When we confess, He forgives, we are clean!<br/>The sense of life then can be keen.<br/>',NULL,53259,1);
INSERT INTO stanza VALUES('NS691','chorus','We have a living Christ!<br/>He always gives us life!<br/>Overcoming life! Transcending life!<br/>We just cooperate! Don’t even hesitate!<br/>We allow Him to have His way in us!<br/>',NULL,53260,2);
INSERT INTO stanza VALUES('NS691','2','The world, we cannot overcome!<br/>But our spirit, is powerful! Strong!<br/>We exercise, call His name, breathe Him in!<br/>The world then has no chance to win!<br/>',NULL,53261,3);
INSERT INTO stanza VALUES('NS691','3','The self and the flesh have to go!<br/>My natural ability too!<br/>All independence, division must flee,<br/>The work of the Spirit frees me!<br/>',NULL,53262,4);
INSERT INTO stanza VALUES('NS692','chorus','He who is joined to the Lord is one Spirit.<br/>Hallelujah!<br/>This is our organic union with the Lord<br/>Through believing into Him.<br/>It is like that of the branches with the vine;<br/>In and of life, the divine life.<br/>Such a union with our resurrected Lord<br/>Can only be in our spirit!<br/>',NULL,53263,1);
INSERT INTO stanza VALUES('NS693','1','O perfect love! It suffers long, forbearing;<br/>Tender and kind, it leads the soul to sing;<br/>Free from all jealous thought and boastful feeling,<br/>May I this love divine to others bring.<br/>',NULL,53264,1);
INSERT INTO stanza VALUES('NS693','2','O, selfless love! ’Tis never unbecoming;<br/>Purest affection “seeks not its own things;”<br/>Never Provoked, not counting evil doing;<br/>Let this love echo forth from my heart’s strings.<br/>',NULL,53265,2);
INSERT INTO stanza VALUES('NS693','3','O noble love! In righteousness rejoicing,<br/>A love that cheers whenever truth is king;<br/>It covers all things, and believes in all things,<br/>It hopes all things, and will endure all things.<br/>',NULL,53266,3);
INSERT INTO stanza VALUES('NS693','4','O lasting love! It fades not, ne’er abating;<br/>Timeless and strong, prevails o’er everything;<br/>When knowledge fails, and gifts are unavailing;<br/>May I be found in its eternal spring.<br/>',NULL,53267,4);
INSERT INTO stanza VALUES('NS694','1','From God Triune comes blessing eternal;<br/>Father, Son, Spirit, our portion free;<br/>What gift of favor, what staying power;<br/>What wealth of grace, O what perfect peace!<br/>',NULL,53268,1);
INSERT INTO stanza VALUES('NS694','2','Eternal Father, source of each blessing,<br/>Bestowed in Christ from heaven above;<br/>In Your name keep us, with Your hand hold us;<br/>From evil shield us, safe in Your love!<br/>',NULL,53269,2);
INSERT INTO stanza VALUES('NS694','3','Eternal Son, rose as the morning sun;<br/>God in the flesh brought glory and grace;<br/>Be gracious to us, do shine upon us;<br/>Grant us Your presence, show us Your face!<br/>',NULL,53270,3);
INSERT INTO stanza VALUES('NS694','4','Eternal Spirit, countenance lifting,<br/>Dispensed into us as joy and peace;<br/>Your eyes assure us, Your gaze approves us;<br/>Your smiling visage, our guarantee!<br/>',NULL,53271,4);
INSERT INTO stanza VALUES('NS694','5','Praise to You, Father, for Your mighty care;<br/>Praise to You, Son, for Your wondrous grace;<br/>Praise to You, Spirit, for measureless peace;<br/>Blessing eternal, ours to embrace!<br/>',NULL,53272,5);
INSERT INTO stanza VALUES('NS694','6','The love of God, the grace of Christ Jesus,<br/>Fellowship of the Spirit divine;<br/>Be with us all, and be with us ever;<br/>Blessing and praise shall now intertwine!<br/>',NULL,53273,6);
INSERT INTO stanza VALUES('NS695','1','Hear the joyful trumpet sound:<br/>Jubilee! Jubilee!<br/>Let the word of grace abound:<br/>Jubilee! Jubilee!<br/>Liberty is now proclaimed!<br/>From all bondage we are free!<br/>All lost property’s reclaimed!<br/>Jubilee! Jubilee!<br/>',NULL,53274,1);
INSERT INTO stanza VALUES('NS695','2','God is man’s appointed share!<br/>Jubilee! Jubilee!<br/>He’s our lot divinely fair!<br/>Jubilee! Jubilee!<br/>Once we lived a life that’s vain,<br/>Now we’re full, with Christ replete!<br/>What a portion we’ve regained!<br/>Jubilee! Jubilee!<br/>',NULL,53275,2);
INSERT INTO stanza VALUES('NS695','3','We have left captivity!<br/>Jubilee! Jubilee!<br/>Christ’s redemption’s set us free!<br/>Jubilee! Jubilee!<br/>Gone are Satan, world, and sin!<br/>From their slav’ry we’ve been freed!<br/>With a new life we begin!<br/>Jubilee! Jubilee!<br/>',NULL,53276,3);
INSERT INTO stanza VALUES('NS695','4','All our roaming days are done!<br/>Jubilee! Jubilee!<br/>With God’s people we are one!<br/>Jubilee! Jubilee!<br/>For a home we’ve always yearned!<br/>It’s the Church, God’s family!<br/>To our kinfolk we’ve returned!<br/>Jubilee! Jubilee!<br/>',NULL,53277,4);
INSERT INTO stanza VALUES('NS695','5','Echo now that awesome sound:<br/>Jubilee! Jubilee!<br/>Sanctify the year renowned:<br/>Jubilee! Jubilee!<br/>Spread the news across the land!<br/>Go announce in ecstasy!<br/>God’s salvation is at hand!<br/>Jubilee! Jubilee!<br/>',NULL,53278,5);
INSERT INTO stanza VALUES('NS696','1','The voice of grace is heard;<br/>Its sound the spirit stirs!<br/>The Scripture’s now fulfilled;<br/>It speaks of God’s good will!<br/>Christ Jesus has appeared!<br/>His proclamation’s clear:<br/>The Jubilee has come!<br/>',NULL,53279,1);
INSERT INTO stanza VALUES('NS696','chorus','The Jubilee has come!<br/>The Jubilee has come!<br/>The prophets were aware;<br/>The Lord this word declared!<br/>The year acceptable!<br/>His full salvation shows!<br/>The Jubilee has come!<br/>',NULL,53280,2);
INSERT INTO stanza VALUES('NS696','2','Upon the Son of Man<br/>God’s Spirit did descend!<br/>The Savior to anoint,<br/>The Herald to appoint!<br/>Bring gospel to the poor!<br/>The broken hearts to cure!<br/>The Jubilee has come!<br/>',NULL,53281,3);
INSERT INTO stanza VALUES('NS696','3','For captives, freedom claim!<br/>Set liberty aflame!<br/>Cause all the blind to see!<br/>Their vision to receive!<br/>Give all oppressed release!<br/>From bondage set them free!<br/>The Jubilee has come!<br/>',NULL,53282,4);
INSERT INTO stanza VALUES('NS696','4','O speak this note of cheer!<br/>Proclaim it far and near!<br/>Where human sorrow’s found;<br/>Where misery abounds!<br/>The gospel now make plain!<br/>Ring out the blessed refrain:<br/>The Jubilee has come!<br/>',NULL,53283,5);
INSERT INTO stanza VALUES('NS697','1','In the Day of Expiation<br/>Blow the horn of liberty!<br/>It’s Jehovah’s Word to Israel<br/>To announce the Jubilee!<br/>Each one to his land return<br/>And to his own lost family!<br/>’Tis the Sabbath year of Sabbaths<br/>For man’s rest and ecstasy!<br/>',NULL,53284,1);
INSERT INTO stanza VALUES('NS697','2','Christ appeared to usher in<br/>The glorious age of Jubilee!<br/>He brought God to men,<br/>And from the hold of Satan set them free!<br/>Eyes He opened, hearts He mended,<br/>Burdened sinners He released!<br/>‘Tis the season of salvation<br/>Purposed from eternity!<br/>',NULL,53285,2);
INSERT INTO stanza VALUES('NS697','3','Rise up, Christians, go and open<br/>People’s eyes that they may see!<br/>Turn them unto God from darkness,<br/>From His foe’s authority!<br/>Sins’ forgiveness<br/>And a portion of the saints they will receive!<br/>Sanctified by faith to taste<br/>The blessing of God’s Jubilee!<br/>',NULL,53286,3);
INSERT INTO stanza VALUES('NS698','1','O how deep and e’er expanding<br/>Is my love, dear Lord, to Thee!<br/>Thy love’s depth, I cannot fathom;<br/>It constrains me ceaselessly.<br/>Like a strong tide pressed upon me,<br/>It surrounds on every side!<br/>By Thy love engulfed entirely,<br/>In Thy perfect will I ’bide.<br/>',NULL,53287,1);
INSERT INTO stanza VALUES('NS698','2','By Thy blood, Lord, I’ve been purchased;<br/>Thou hast paid the highest price;<br/>‘Tis the basis of my offering<br/>As a living sacrifice.<br/>I love Thee, for Thou first loved me;<br/>As more love I daily see,<br/>Thy love greatly motivates me<br/>Willingly to live for Thee!<br/>',NULL,53288,2);
INSERT INTO stanza VALUES('NS698','3','Yet, the service Thou desirest<br/>Must not from my self be brought;<br/>Thou wouldst have me open to Thee,<br/>For Thy love’s work to be wrought.<br/>In my heart, Thy home establish;<br/>Reproduce Thyself in me;<br/>Built with others in Thy Body,<br/>For Thy service meet I’d be.<br/>',NULL,53289,3);
INSERT INTO stanza VALUES('NS698','4','Lord, like Mary, to Thee listening,<br/>At Thy feet, so lovingly,<br/>Hearing Thy dear heart’s intention,<br/>Revelation I’ll receive.<br/>Lord, I break my flask, most precious;<br/>My heart’s treasury outpour;<br/>Fill Thy house with sweetest fragrance,<br/>A memorial evermore!<br/>',NULL,53290,4);
INSERT INTO stanza VALUES('NS699','1','O Lord, perfect another generation<br/>Of ministers for Your recovery;<br/>Etch in our hearts this desp’rate aspiration,<br/>In our forefathers’ steps and ministry.<br/>Lord, heed the cry from deep within our spirit;<br/>All o’er the earth gain channels of supply.<br/>Remove the fear within us of the cost, Lord;<br/>That we’d unsparingly our soul life e’er deny.<br/>',NULL,53291,1);
INSERT INTO stanza VALUES('NS699','2','Gain us, we pray, a little more each day, Lord;<br/>May we likewise gain You, to be Your bride;<br/>You’re our first love; Your riches are our beauty;<br/>Mature us soon, that no more veils divide.<br/>Make us today’s “one hundred twenty saints,” Lord,<br/>In upper room with God identified;<br/>One with You as a corporate burnt off’ring<br/>To turn this age, Lord, that Your heart be satisfied.<br/>',NULL,53292,2);
INSERT INTO stanza VALUES('NS700','1','Hold a pattern of the healthy words<br/>that you’ve heard from me,<br/>in faith and love which are in Christ Jesus.<br/>',NULL,53293,1);
INSERT INTO stanza VALUES('NS700','2','Hold a pattern of the healthy words<br/>that you’ve heard from me,<br/>in faith and love which are in Christ Jesus.<br/>',NULL,53294,2);
INSERT INTO stanza VALUES('NS700','3','Guard the good deposit<br/>through the Holy Spirit<br/>who dwells in us,<br/>who dwells in us.<br/>Hold a pattern of the healthy words!<br/>',NULL,53295,3);
INSERT INTO stanza VALUES('NS701','1','One thing I have asked from Jehovah,<br/>That do I seek, that do I seek.<br/>To dwell in the house of Jehovah,<br/>All the days of my life,<br/>All the days of my life.<br/>',NULL,53296,1);
INSERT INTO stanza VALUES('NS701','2','To behold the beauty of Jehovah,<br/>And to inquire in His temple.<br/>Psalms 27:4<br/>',NULL,53297,2);
INSERT INTO stanza VALUES('NS702','1','Anyone who hears these words of mine and does them,<br/>Shall be likened to a prudent man,<br/>Who built his house upon the rock,<br/>And the rain descended and the rivers came,<br/>And the winds blew, and they beat against that house,<br/>And it did not fall, for it was founded on the rock.<br/>',NULL,53298,1);
INSERT INTO stanza VALUES('NS702','2','Lord, I thank You that I have the rock, Your wise words,<br/>That reveal the Father’s will to me.<br/>Put in me a heart that would respond,<br/>And a will to choose the narrow way.<br/>Make me prudent, Lord, for the building of Your house,<br/>And I would not fall, for I’d be founded on the rock.<br/>',NULL,53299,2);
INSERT INTO stanza VALUES('NS703','1','For I do not do the good which I will;<br/>But the evil which I do not will,<br/>This I practice.<br/>',NULL,53300,1);
INSERT INTO stanza VALUES('NS703','chorus','But the law of the Spirit of life<br/>Has freed me in Christ Jesus<br/>From the law of sin and of death, freed me.<br/>',NULL,53301,2);
INSERT INTO stanza VALUES('NS703','2','But if what I, I do not will, this I do,<br/>It’s no longer I that work it out<br/>But sin that dwells in me.<br/>',NULL,53302,3);
INSERT INTO stanza VALUES('NS704','1','Two are better than one;<br/>If I fall, then you can pick me up.<br/>Two are better than one<br/>To resist the enemy.<br/>Three are better than two;<br/>A three-fold cord’s not quickly broken.<br/>(Insert name), I need you;<br/>Be my companion.<br/>',NULL,53303,1);
INSERT INTO stanza VALUES('NS704','chorus','God has placed me with you here,<br/>My companions who are so dear.<br/>Blend us, knit us, and build us up today.<br/>Day by day you encourage me;<br/>A foretaste of New Jerusalem I see.<br/>I need you, my companion.<br/>',NULL,53304,2);
INSERT INTO stanza VALUES('NS704','2','We are running a race,<br/>Pressing on each day toward the goal.<br/>We are running a race;<br/>Christ the prize we hold in view.<br/>Fleeing youthful lusts,<br/>But faith, love, peace, and righteousness pursue;<br/>(Insert name), I need you.<br/>Be my companion.<br/>',NULL,53305,3);
INSERT INTO stanza VALUES('NS704','3','I’m an ear that can’t see;<br/>There are many things that I can’t do.<br/>You’re an eye that can’t hear;<br/>See, I have my function too.<br/>We’re an eye and an ear,<br/>So we need arms and legs and pinky toes.<br/>(Insert name), we need them;<br/>We’re one living Body.<br/>',NULL,53306,4);
INSERT INTO stanza VALUES('NS705','1','There is Someone interceding for you.<br/>He’s in the heavens and He’s praying for you.<br/>There is Someone who stands before the face of God<br/>And knows every one of your needs.<br/>There is Someone. Just believe.<br/>',NULL,53307,1);
INSERT INTO stanza VALUES('NS705','chorus','Though you can’t see Him,<br/>Have faith that He’s working behind the scenes.<br/>Though the heavens are silent right now,<br/>Be simple to love and believe<br/>In Jesus our High Priest.<br/>',NULL,53308,2);
INSERT INTO stanza VALUES('NS705','2','There is Someone who is living for you.<br/>He is list’ning and responding to you.<br/>He’s preparing, arranging each circumstance<br/>To meet every one of your needs.<br/>There is Someone. Just believe.<br/>',NULL,53309,3);
INSERT INTO stanza VALUES('NS705','3','There is Someone who is strengthening you.<br/>He’s sustaining and He’s bearing you through.<br/>You’re not forgotten. At this moment you’re in His hands.<br/>He’s ministering what you need.<br/>Love this Someone and believe.<br/>',NULL,53310,4);
INSERT INTO stanza VALUES('NS706','chorus','This is my prayer, Lord:<br/>Open my heart, Lord.<br/>I want to hear what You say.<br/>Open my spirit.<br/>Open my soul, Lord.<br/>I give myself; have Your way.<br/>Grant me a vision,<br/>Clear revelation, Lord, I pray.<br/>I want You to<br/>Speak words of life, Lord,<br/>Into my being fresh today,<br/>That I may be<br/>Able to see You<br/>And all You want to be in me.<br/>Lord, I want to live You.<br/>Wash me and cleanse me.<br/>Set me apart for You.<br/>O Lord, Your earthen vessel I would be.<br/>',NULL,53311,1);
INSERT INTO stanza VALUES('NS707','1','I just realized dear Lord, You’ve had a longing<br/>Deep within Your heart from the beginning.<br/>Just to have a companion who would match You,<br/>Who would know You, want You, and would love You.<br/>This is why You became a man just like me<br/>So You could know all my feelings and could reach me<br/>Oh You paid such a price, You left Your glory<br/>To gain a people, a bride to live with You...eternally.<br/>',NULL,53312,1);
INSERT INTO stanza VALUES('NS707','chorus','So recover my heart to love You more,<br/>Recover my mind to know You more,<br/>Recover my strength to live You more, O Lord.<br/>I’d be found in You and You in me...living together constantly<br/>Enjoying each other mutually...<br/>Oh this is Your recovery...this meets Your need.<br/>',NULL,53313,2);
INSERT INTO stanza VALUES('NS707','2','Draw me Lord, together with some others<br/>Who would run after You, and not another.<br/>Make us vital in Your life and purpose<br/>Willing to know You, gain You, and to match You!<br/>Above all, dear Lord, Your need is greater<br/>Since You are the “I AM”—the great Creator!<br/>Matchless One, our Lover, and our dear Bridegroom...<br/>Expecting to realize Your dream in all You have won!<br/>',NULL,53314,3);
INSERT INTO stanza VALUES('NS708','1','He’s the Father of compassions,<br/>The God of all comfort,<br/>Comforting us in a personal way.<br/>Though the suff’rings abound,<br/>Christ the Comfort abounds.<br/>Partake of the Comfort today.<br/>',NULL,53315,1);
INSERT INTO stanza VALUES('NS708','chorus','The ministry is formed when we turn to the Lord,<br/>And experience Christ in affliction.<br/>Then we unto others a comfort become,<br/>True ministers in resurrection.<br/>',NULL,53316,2);
INSERT INTO stanza VALUES('NS708','2','So stay open, open to Him,<br/>The God of all comfort;<br/>Then He can touch others in a personal way.<br/>Comfort to you, comfort through you;<br/>The Comfort abounds!<br/>Partake of the Comfort today.<br/>',NULL,53317,3);
INSERT INTO stanza VALUES('NS709','1','In nothing be anxious, but in everything,<br/>By prayer and petition with thanksgiving,<br/>Let your requests be made known to God;<br/>And the peace of God,<br/>Which surpasses every man’s understanding,<br/>Will guard your hearts and your thoughts in Christ Jesus.<br/>',NULL,53318,1);
INSERT INTO stanza VALUES('NS709','chorus','And the peace of God is God as peace<br/>Infused into you and me,<br/>Through our fellowship with Him by prayer;<br/>As the counterpoise to troubles,<br/>And the antidote to anxiety,<br/>Mounting guard over us,<br/>Saving us from all our cares.<br/>',NULL,53319,2);
INSERT INTO stanza VALUES('NS709','2','In all situations, every frustration,<br/>All your anxiety comes from Satan,<br/>To disturb your life of living Christ.<br/>Just stay in the union, living communion,<br/>One with Christ; give everything to Him.<br/>Peace of God through our life of living Christ.<br/>',NULL,53320,3);
INSERT INTO stanza VALUES('NS710','1','God needs some young people,<br/>To keep themselves from defilement;<br/>Some who will stand against the current of the age,<br/>Who will declare, Lord, from today<br/>We’re going to flee youthful lusts and pursue<br/>righteousness, me and you,<br/>Who call upon the Lord<br/>From a pure heart.<br/>Keep purifying our hearts,<br/>Enlightening every part,<br/>Oh Lord ’til the church is all we see!<br/>',NULL,53321,1);
INSERT INTO stanza VALUES('NS710','2','God needs some young people,<br/>To keep themselves from defilement;<br/>Some who will stand against the current of the age,<br/>Who will declare, Lord, from today<br/>We’re going to flee youthful lusts and pursue<br/>righteousness with the view—<br/>The building of the church.<br/>Not wasting time,<br/>Pressing on toward the goal,<br/>Occupied with the prize,<br/>Oh Lord, we’ve been wrecked, we’ll build Your church!<br/>',NULL,53322,2);
INSERT INTO stanza VALUES('NS711','1','We are pressed on every side; unable to find a way out;<br/>Persecuted and cast down;<br/>Every suffering in our natural man is another opportunity<br/>For our inner man to develop and be renewed.<br/>',NULL,53323,1);
INSERT INTO stanza VALUES('NS711','chorus','So we do not lose heart though our outer man is decaying;<br/>We do not lose heart for our inner man is being renewed day by day;<br/>And we do not regard the temporary things which are seen<br/>But the things which are not seen which are eternal.<br/>',NULL,53324,2);
INSERT INTO stanza VALUES('NS711','2','Nourish me, Lord, in my sufferings with a fresh supply;<br/>Renew me day by day with resurrection life.<br/>Every suffering in my natural man is another opportunity<br/>For Your life and resurrection to be released.<br/>',NULL,53325,3);
INSERT INTO stanza VALUES('NS711','chorus','Bridge:<br/>We are pressed on every side; (but not constricted)<br/>Unable to find a way out; (still with a way out)<br/>Persecuted (but not abandoned)<br/>And cast down (but not destroyed)<br/>For our momentary lightness of affliction works out for us<br/>More and more surpassingly an eternal weight of glory.<br/>',NULL,53326,4);
INSERT INTO stanza VALUES('NS711','chorus','Ending:<br/>But the things which are not seen—which are eternal,<br/>Which are eternal,<br/>Which are eternal.<br/>',NULL,53327,5);
INSERT INTO stanza VALUES('NS712','1','We must see today that God needs expressing on earth;<br/>And for this we say, “Lord, increase in us!”<br/>Lord, give us Your heart<br/>To speak what we’ve seen and heard of God’s Jubilee,<br/>His economy, the reason we pray...<br/>',NULL,53328,1);
INSERT INTO stanza VALUES('NS712','chorus','To open their eyes,<br/>To turn them from darkness to light,<br/>And from the authority of Satan to God,<br/>That they may receive forgiveness of sins,<br/>And all that God has, all that God has done,<br/>And all God will do!<br/>',NULL,53329,2);
INSERT INTO stanza VALUES('NS712','2','Lord Jesus we pray, announcing the eternal life,<br/>Enlightening all that they may believe;<br/>Lord, strengthen us now,<br/>Proclaiming this Jubilee, our purpose to live,<br/>This gospel we give, to all who would pray...<br/>',NULL,53330,3);
INSERT INTO stanza VALUES('NS712','chorus','Lord, open my eyes,<br/>And turn me from darkness to light,<br/>And from the authority of Satan to God,<br/>That I may receive forgiveness of sins,<br/>And all that God has, all that God has done<br/>And all God will do!<br/>',NULL,53331,4);
INSERT INTO stanza VALUES('NS713','1','We satisfy Christ, as His Bride, in His image;<br/>As new man and warrior, dominion we win!<br/>Safeguarded in battle in Christ as our armor,<br/>We fight for God’s interests, His kingdom bring in!<br/>',NULL,53332,1);
INSERT INTO stanza VALUES('NS713','2','We’re garbed in fine linen, our bridal apparel,<br/>Made spotless and bright through God’s love and His light;<br/>An army that follows the Lord into battle,<br/>We’re clothed in this linen, with Christ armed in might!<br/>',NULL,53333,2);
INSERT INTO stanza VALUES('NS713','3','We’re girded with Truth, with Christ’s righteousness covered,<br/>We’re shod with the gospel of peace through His blood,<br/>We’re shielded by faith, and we’re helmed with salvation,<br/>And armed with the sword of the Spirit, the word!<br/>',NULL,53334,3);
INSERT INTO stanza VALUES('NS713','4','God’s word is a bounty of food for our eating;<br/>This food constitutes us, through prayer, hour by hour;<br/>By this constitution we’re readied for battle,<br/>And, led by the Spirit, we speak with His pow’r!<br/>',NULL,53335,4);
INSERT INTO stanza VALUES('NS713','5','Our battle is corporate—as one man we conquer!<br/>We’re one with the Lord in the might of His strength!<br/>Withstanding the foe, in the Body empowered,<br/>Steadfastly we stand, headed up through His reign!<br/>',NULL,53336,5);
INSERT INTO stanza VALUES('NS713','6','The Lord is our center, our source and our standing,<br/>Our leader, our Captain, our conqueror, our King!<br/>Our Bridegroom, our Husband, our Head, our Beloved!<br/>We love Him intensely—from Him triumphs spring!<br/>',NULL,53337,6);
INSERT INTO stanza VALUES('NS713','7','We move in God’s move with the Lord in His headship,<br/>Upheld by the Head as His Body on earth!<br/>Christ’s made us partakers in all He’s accomplished!<br/>Exalt Him, rejoicing! God’s will must come forth!<br/>',NULL,53338,7);
INSERT INTO stanza VALUES('NS713','8','God’s image expressed, His dominion established,<br/>Through prayer corresponding to Christ on the throne,<br/>Fulfills God’s intention, His purpose eternal,<br/>Regaining the earth for God’s pleasure alone!<br/>',NULL,53339,8);
INSERT INTO stanza VALUES('NS713','9','The church is the Bride, the new man, and the warrior<br/>Fulfilling God’s heart’s desire, stage after stage.<br/>We love Christ supremely and stand in His victory<br/>To bring in His Kingdom by turning the age.<br/>',NULL,53340,9);
INSERT INTO stanza VALUES('NS714','1','Oh what a mystery! Christ in you, Christ in me!<br/>Oh what a victory! Christ in you, Christ in me!<br/>',NULL,53341,1);
INSERT INTO stanza VALUES('NS714','2','Christ is in you,<br/>though the body’s dead because of sin.<br/>The spirit’s life because of righteousness.<br/>(Romans 8:10)<br/>',NULL,53342,2);
INSERT INTO stanza VALUES('NS714','3','God willed to make known<br/>the riches of the glory of this mystery,<br/>which is Christ in you, the hope of glory.<br/>(Colossians 1:27)<br/>',NULL,53343,3);
INSERT INTO stanza VALUES('NS714','4','Test yourselves, prove yourselves.<br/>Or do you not realize that Jesus Christ is in you?<br/>(2 Corinthians 13:5)<br/>',NULL,53344,4);
INSERT INTO stanza VALUES('NS714','5','I am crucified with Christ and it is no longer I<br/>who live but it is Christ who lives in me!<br/>(Galatians 2:20)<br/>',NULL,53345,5);
INSERT INTO stanza VALUES('NS714','6','Oh what a mystery! Christ in you, Christ in me!<br/>Oh what a victory! Christ in you, Christ in me!<br/>',NULL,53346,6);
INSERT INTO stanza VALUES('NS715','1','If you’ve lost all your possessions<br/>And you’re feeling the oppressions,<br/>There’s a gift of grace to you who would believe;<br/>There’s no high requirement from you,<br/>Jesus Christ, Whose blood redeemed you,<br/>Is the One who is forgiveness, just receive!<br/>',NULL,53347,1);
INSERT INTO stanza VALUES('NS715','chorus','There’s good news on your horizon—(Shout) Jubilee!<br/>There’s a gospel worth announcin’—(Shout) Just believe!<br/>It’s the word for which you’re waiting,<br/>It’s a gift worth celebrating,<br/>Hear the trumpet, how elating—Be set free....<br/>To enjoy the Lord, receive abundant grace,<br/>Just enjoy the Lord, behold His shining face,<br/>In the Jubilee! Just believe! Be set free!<br/>In the Jubilee!<br/>',NULL,53348,2);
INSERT INTO stanza VALUES('NS715','2','Through Christ’s words of grace and mercy,<br/>There’s no shortage, lack, or worry,<br/>Don’t be bothered, vexed, or feel anxiety;<br/>In the Jubilee of grace where<br/>All our debt has been erased there,<br/>We are happy, joyful, filled with ecstasy!<br/>',NULL,53349,3);
INSERT INTO stanza VALUES('NS715','3','When Christ is our satisfaction<br/>And our one unique attraction,<br/>Christ, the Savior, has become our Jubilee;<br/>Everything is satisfying<br/>When in all Christ is supplying<br/>All the riches found in God’s economy!<br/>',NULL,53350,4);
INSERT INTO stanza VALUES('NS716','1','Lord, I open to Your light<br/>That I vanquished be.<br/>Mend with balm anointing life;<br/>Build Yourself in me,<br/>And adorn my being.<br/>',NULL,53351,1);
INSERT INTO stanza VALUES('NS716','2','I would walk as if one blind,<br/>Faith my only guide,<br/>Understanding cast behind,<br/>As a veil of night,<br/>That I know real sight.<br/>',NULL,53352,2);
INSERT INTO stanza VALUES('NS716','3','Sun of revelation, rise!<br/>Gush, O vital stream!<br/>That by light and flowing life,<br/>Living I would be,<br/>Fully one with Thee.<br/>',NULL,53353,3);
INSERT INTO stanza VALUES('NS716','4','Fruit most fragrant may You find,<br/>Bursting with Your life,<br/>Fully ready, wholly ripe,<br/>Pleasing in Your sight;<br/>You I would delight.<br/>',NULL,53354,4);
INSERT INTO stanza VALUES('NS716','5','Come, dear hand of mercy, bring<br/>Grace full supply!<br/>For a love-filled out-pouring<br/>Of my very life<br/>On Your Body, Christ.<br/>',NULL,53355,5);
INSERT INTO stanza VALUES('NS717','1','From the Head to the Body flows a rich supply.<br/>Thus as members of Christ we must relate.<br/>Every need in the Body can be met thereby.<br/>Build us up in Your Body, we pray.<br/>',NULL,53356,1);
INSERT INTO stanza VALUES('NS717','chorus','Members one of another, the Body will grow,<br/>As we’re knit together in our inward parts.<br/>Open firstly to Christ our Head, then life He will bestow<br/>Through the function in measure of each part.<br/>',NULL,53357,2);
INSERT INTO stanza VALUES('NS717','2','Christ is Head of the Body; we’re His members true.<br/>When we hold fast the Head, life freely flows.<br/>As we’re daily enjoying, we with Christ are infused,<br/>All His heart for the Body we’ll know.<br/>',NULL,53358,3);
INSERT INTO stanza VALUES('NS717','3','For the sake of Your Body, Lord, unveil our eyes,<br/>Deal with self, all the ground to You we give.<br/>Save us from independence and all natural ties.<br/>Blend us all in Your Body to live.<br/>',NULL,53359,4);
INSERT INTO stanza VALUES('NS717','4','One with Christ in His Body, in the rich supply,<br/>Every part causing growth in love each day.<br/>Thus God’s purpose eternal will be realized—<br/>Christ expressed through His Body for aye.<br/>',NULL,53360,5);
INSERT INTO stanza VALUES('NS718','1','Because those whom He foreknew,<br/>He also predestinated<br/>To be conformed to the image of His Son,<br/>That He might be the Firstborn among many brothers;<br/>',NULL,53361,1);
INSERT INTO stanza VALUES('NS718','2','And those whom He predestinated,<br/>These He also called;<br/>And those whom He called, these He also justified;<br/>And those whom He justified, these He also glorified.<br/>',NULL,53362,2);
INSERT INTO stanza VALUES('NS718','3','We know all things work together for good<br/>To those who love God,<br/>To those who are called<br/>According to His purpose,<br/>According to His purpose, we know.<br/>',NULL,53363,3);
INSERT INTO stanza VALUES('NS718','4','We know all things work together for good<br/>To those who love God,<br/>To those who are called<br/>According to His purpose,<br/>According to His purpose, we know.<br/>',NULL,53364,4);
INSERT INTO stanza VALUES('NS719','1','God planned His great purpose in eternity,<br/>This great will was hidden, a great mystery;<br/>With wisdom and prudence He has made it known,<br/>Through revelation, in Christ, the Son.<br/>',NULL,53365,1);
INSERT INTO stanza VALUES('NS719','chorus','Unto the economy of the fullness of the times,<br/>To head up all things in Christ,<br/>The things in the heavens in Him;<br/>Unto the economy of the fullness of the times,<br/>To head up all things in Christ<br/>And the things on the earth, in Him.<br/>',NULL,53366,2);
INSERT INTO stanza VALUES('NS719','2','Through Christ’s incarnation God came into man,<br/>And through crucifixion came redemption’s plan;<br/>Then in resurrection, the Comforter came,<br/>And in His ascension exalt His name!<br/>',NULL,53367,3);
INSERT INTO stanza VALUES('NS719','3','It is God’s good pleasure to show us the Son,<br/>And through His dispensing we are all made one;<br/>Through this life abundant and rich life supply,<br/>The church will be builded and beautified.<br/>',NULL,53368,4);
INSERT INTO stanza VALUES('NS720','1','The Lord has given freedom<br/>To all who just believe Him.<br/>Be no longer enslaved.<br/>Come now! Return to Jesus.<br/>Receive the Life that frees us!<br/>Call on Him and be saved.<br/>',NULL,53369,1);
INSERT INTO stanza VALUES('NS720','chorus','This is the year of jubilee!<br/>Proclaim our liberty in Him!<br/>Throughout the land we sound out:<br/>The slaves have been returned to Him,<br/>Released from toil, anxiety, and sin!<br/>This is the year of jubilee!<br/>',NULL,53370,2);
INSERT INTO stanza VALUES('NS720','2','Reclaim the land, our portion,<br/>God as our rich possession.<br/>Feast on Him ev’ry day!<br/>Enjoy Him with God’s fam’ly;<br/>Find satisfaction and peace.<br/>Here forever to stay!<br/>',NULL,53371,3);
INSERT INTO stanza VALUES('NS721','1','I was so full, but still so poor,<br/>Still empty as I grasped for more.<br/>Then I received the glorious Christ;<br/>He’s now my portion, grace, and life!<br/>',NULL,53372,1);
INSERT INTO stanza VALUES('NS721','chorus','Christ has proclaimed the jubilee,<br/>This age of grace, for you and me!<br/>Return to Him, be filled and free<br/>Here in the church, our family!<br/>',NULL,53373,2);
INSERT INTO stanza VALUES('NS721','2','Intending good, but failing still,<br/>I slaved for sin against my will.<br/>But Christ redeemed, enlivened me,<br/>Replaced my bonds with liberty!<br/>',NULL,53374,3);
INSERT INTO stanza VALUES('NS721','3','I wandered far and found no home;<br/>If not my feet, my heart did roam.<br/>But I have found my family—<br/>Christ and the church—a place for me!<br/>',NULL,53375,4);
INSERT INTO stanza VALUES('NS721','4','Let us proclaim the jubilee,<br/>Announce good news, set captives free!<br/>Trumpet salvation to all men—<br/>God is our portion once again!<br/>',NULL,53376,5);
INSERT INTO stanza VALUES('NS721','end-note','Verse and chorus can be sung together.<br/>',NULL,53377,6);
INSERT INTO stanza VALUES('NS722','1','This is the year of Jubilee,<br/>The year of grace to men;<br/>Christ is the Jubilee to us<br/>To free from every sin.<br/>When living in the Jubilee<br/>There’s freedom in the Lord;<br/>Enjoying our inheritance<br/>With saints in one accord.<br/>',NULL,53378,1);
INSERT INTO stanza VALUES('NS722','chorus','Jubilee! Jubilee!<br/>The Spirit is upon Me<br/>To cause the blind to see.<br/>Jubilee! Jubilee!<br/>Announce the gospel to the poor...<br/>Open up the prison doors...<br/>Come let us enjoy the Lord...<br/>And be set free!<br/>JUBILEE!!<br/>',NULL,53379,2);
INSERT INTO stanza VALUES('NS722','2','The Jubilee is Christ the feast,<br/>Enjoyed by all who eat;<br/>We take Him as our dwelling place<br/>To have true rest and peace;<br/>The secret of the Jubilee<br/>Is gaining Christ, our rest;<br/>With Christ in us and us in Christ,<br/>Our life is really blessed.<br/>',NULL,53380,3);
INSERT INTO stanza VALUES('NS722','3','The living in the Jubilee<br/>Is Christ lived out in us;<br/>Through every trial and circumstance,<br/>Christ reigns victorious;<br/>Release your voice, proclaim the news<br/>To all the captured ones,<br/>Rejoicing, thanking, praising God<br/>Until the kingdom comes!<br/>',NULL,53381,4);
INSERT INTO stanza VALUES('NS723','1','In these last days before the Lord’s coming,<br/>before the Lord’s coming,<br/>We must be those who have great resolutions in heart,<br/>We must be those who have<br/>',NULL,53382,1);
INSERT INTO stanza VALUES('NS723','chorus','Great resolutions in heart and great searchings of heart,<br/>Who have great resolutions in heart,<br/>and great searchings of heart,<br/>searchings of heart,<br/>searchings of heart.<br/>',NULL,53383,2);
INSERT INTO stanza VALUES('NS723','chorus','(Bridge)<br/>We must be absolutely consecrated to God,<br/>Having one heart to love Him, seek Him, live Him,<br/>And be constituted with Him to be His expression.<br/>We must be those who have<br/>',NULL,53384,3);
INSERT INTO stanza VALUES('NS723','2','In these last days before the Lord’s coming,<br/>before the Lord’s coming,<br/>We must be those who have great resolutions in heart,<br/>We must be those who have<br/>',NULL,53385,4);
INSERT INTO stanza VALUES('NS723','chorus','Great resolutions in heart and great searchings of heart,<br/>Who have great resolutions in heart,<br/>and great searchings of heart,<br/>searchings of heart,<br/>searchings of heart.<br/>',NULL,53386,5);
INSERT INTO stanza VALUES('NS723','end-note','(Verse 2 and chorus can be sung together)<br/>',NULL,53387,6);
INSERT INTO stanza VALUES('NS724','1','Emmanuel—His name men calleth,<br/>God with us—with them He dwelleth;<br/>I’m in their midst—where saints assembleth,<br/>“Behold, I am with thee”—<br/>’til this age hath ended.<br/>',NULL,53388,1);
INSERT INTO stanza VALUES('NS725','chorus','And He has said to me,<br/>My grace is sufficient for you,<br/>And He has said to me,<br/>My grace is sufficient for you,<br/>For My power is perfected in weakness,<br/>For My power is perfected in weakness.<br/>',NULL,53389,1);
INSERT INTO stanza VALUES('NS725','chorus','Most gladly therefore I will rather boast in my weaknesses,<br/>In my weaknesses,<br/>Most gladly therefore I will rather boast in my weaknesses,<br/>In my weaknesses,<br/>That the power of Christ might tabernacle over me,<br/>That the power of Christ might tabernacle over me.<br/>',NULL,53390,2);
INSERT INTO stanza VALUES('NS726','1','Bringing in the good news we announce the gospel.<br/>Binding up the wounds of those who are enslaved;<br/>We proclaim the freedom to release the captives,<br/>Freed from sin and death, in Christ, we have been saved.<br/>',NULL,53391,1);
INSERT INTO stanza VALUES('NS726','chorus','Spread the Jubilee, live the Jubilee!<br/>We have been recovered, we have been redeemed!<br/>Spread the Jubilee, live the Jubilee!<br/>We enjoy our birthright, Christ, our everything!<br/>',NULL,53392,2);
INSERT INTO stanza VALUES('NS726','2','Serving in the priesthood, reigning in the kingship.<br/>We enjoy the double portion of the land;<br/>Christ, the serving priest and ruling One within us.<br/>Keeps us in the oneness, our eternal stand!<br/>',NULL,53393,3);
INSERT INTO stanza VALUES('NS726','3','Exercise your spirit in the royal priesthood<br/>And the resurrection power will engage;<br/>By cooperating we are now securing<br/>Out participating in the kingdom age.<br/>',NULL,53394,4);
INSERT INTO stanza VALUES('NS727','1','Open my eyes, Savior, true sight now render!<br/>Turn me, dear Lord, from darkness to the light!<br/>From Satan’s pow’r to God my soul deliver!<br/>That I may know forgiveness of my sins.<br/>And an inheritance divine to savor,<br/>With those made holy by their faith in You!<br/>',NULL,53395,1);
INSERT INTO stanza VALUES('NS728','1','Fill my spirit up,<br/>Fill my spirit up,<br/>Till it overflows<br/>Right out<br/>of my innermost being!<br/>Fill my spirit up,<br/>Fill my spirit up,<br/>Till it overflows<br/>Right out<br/>of my innermost being!<br/>',NULL,53396,1);
INSERT INTO stanza VALUES('NS728','chorus','Fill me today,<br/>Fill me, I pray!<br/>Oh, Lord Jesus,<br/>Flow as the living water!<br/>Oh, Lord Jesus,<br/>Gush up as the living spring!<br/>Right out of my innermost being.<br/>',NULL,53397,2);
INSERT INTO stanza VALUES('NS728','2','Break through every part,<br/>Break through every part<br/>Of my mind, emotion,<br/>will and heart!<br/>Break through every part,<br/>Break through every part<br/>Of my mind, emotion,<br/>will and heart!<br/>',NULL,53398,3);
INSERT INTO stanza VALUES('NS728','chorus','Break through today,<br/>Break through, I pray!<br/>Oh, Lord Jesus,<br/>Flow as the living water!<br/>Oh, Lord Jesus,<br/>Gush up as the living spring!<br/>Right out of my innermost being.<br/>',NULL,53399,4);
INSERT INTO stanza VALUES('NS728','3','Flow that river out,<br/>Flow that river out<br/>Whether I might call,<br/>pray, sing or shout!<br/>Flow that river out,<br/>Flow that river out<br/>Whether I might call,<br/>pray, sing or shout!<br/>',NULL,53400,5);
INSERT INTO stanza VALUES('NS728','chorus','Flow out today,<br/>Flow out, I pray!<br/>Oh, Lord Jesus,<br/>Flow as the living water!<br/>Oh, Lord Jesus,<br/>Gush up as the living spring!<br/>Right out of my innermost being.<br/>',NULL,53401,6);
INSERT INTO stanza VALUES('NS729','1','Thou blessed and kept us in Thy love,<br/>Drawn from the world and brought above.<br/>Thy glorious face hath shined on us,<br/>Grace flowed into our hearts at last!<br/>Then Thou lifted Thy countenance.<br/>Confirmed with us what’s in Thine heart<br/>Threefold blessing for three-part man!<br/>O what a blessing we can stand!<br/>',NULL,53402,1);
INSERT INTO stanza VALUES('NS729','chorus','Jesus Lord, we give ourselves to Thee<br/>And with Thy blessing we will serve Thee.<br/>No longer for ourselves alone,<br/>But for Thy Church, we will go on.<br/>Bless us Lord, till we’re fully blessed<br/>Make us persons blessed to bless.<br/>',NULL,53403,2);
INSERT INTO stanza VALUES('NS729','2','Our doubts and fears are now all gone.<br/>We’re for Thy purpose and Thy plan.<br/>Whatever may befall us—<br/>The Great I Am, we fully trust.<br/>Where’er Thou wilt send us, we’ll go.<br/>Whate’er Thou dispensed, we’ll outflow.<br/>Beget, nourish, perfect, and build,<br/>Till Thy divine plan is fulfilled.<br/>',NULL,53404,3);
INSERT INTO stanza VALUES('NS729','3','We stand before Thee face to face,<br/>Exhibit how we ran the race.<br/>Now we’re not here with empty hands,<br/>But filled with Jesus and Thy brands.<br/>Thy love, and grace,and fellowship—<br/>All for the Body, not for ’self’.<br/>Threefold blessing for three-part man<br/>Behold the blessings, here we stand!<br/>',NULL,53405,4);
INSERT INTO stanza VALUES('NS730','1','For of His fullness we have all received,<br/>And grace upon grace.<br/>For of His fullness we have all received,<br/>And grace upon grace.<br/>',NULL,53406,1);
INSERT INTO stanza VALUES('NS730','2','Grace and reality<br/>came through Jesus Christ.<br/>Grace and reality<br/>came through Jesus Christ.<br/>',NULL,53407,2);
INSERT INTO stanza VALUES('NS731','1','I have loved Your precepts; O Jehovah, enliven me.<br/>I have not swerved from Your testimonies. Your word is truth.<br/>In Your statutes do I take delight;<br/>In Your precepts do I muse.<br/>In my heart do I treasure Your word<br/>That I might not sin against You.<br/>',NULL,53408,1);
INSERT INTO stanza VALUES('NS732','1','Why do you stand alone?<br/>Why are you so withdrawn?<br/>Open to Him, be not afraid,<br/>The Lord will take care of you.<br/>',NULL,53409,1);
INSERT INTO stanza VALUES('NS732','2','Why do you fear your future<br/>Will only be filled with pain?<br/>You’re in His hands, trust in His plans.<br/>He will take care of you.<br/>',NULL,53410,2);
INSERT INTO stanza VALUES('NS732','3','He loves you more than you know.<br/>Open to Him, just let go<br/>Of all your fears, of all your cares.<br/>Let Him love you. His heart is good toward you.<br/>Trust and believe.<br/>',NULL,53411,3);
INSERT INTO stanza VALUES('NS732','4','You’re a child in God’s economy,<br/>Predestinated, chosen, His bride-to-be.<br/>How could He not prepare the best for you?<br/>Let Him love you. His heart is good toward you.<br/>Trust and believe.<br/>',NULL,53412,4);
INSERT INTO stanza VALUES('NS732','5','He loves you more than you know.<br/>Open to Him, just let go<br/>Of all your fears, of all your cares.<br/>Let Him love you. His will take care of you.<br/>Trust and believe.<br/>',NULL,53413,5);
INSERT INTO stanza VALUES('NS733','1','Would You subdue my soul?<br/>Would You increase in me?<br/>For years Your life has been so bound,<br/>O Lord, within my soul! Grow in me!<br/>Would You break forth again?<br/>Would You flow unrestrained?<br/>Divide my spirit from my soul!<br/>O may my spirit reign! O Lord!<br/>O may my spirit reign! O Lord!<br/>',NULL,53414,1);
INSERT INTO stanza VALUES('NS733','2','Soften my hardened heart,<br/>Touch all its calloused sense,<br/>Till You gain ground in all my heart;<br/>O Lord! Revive my being and dispense!<br/>Soulish love, Lord, recede,<br/>Nat’ral strength, Lord, deplete,<br/>Fill more with Spirit, Lord, I plead!<br/>This cost I’d hourly meet! O Lord!<br/>This cost I’d hourly meet! O Lord!<br/>',NULL,53415,2);
INSERT INTO stanza VALUES('NS733','3','Shine on my life and work,<br/>Reveal my Christlessness;<br/>The flesh expose that loves to boast<br/>In vanity, its own righteousness.<br/>In all things great or small,<br/>Sever me from the fall—<br/>Deliver me from right and wrong<br/>Till tree of life is all! O Lord!<br/>Till tree of life is all! O Lord!<br/>',NULL,53416,3);
INSERT INTO stanza VALUES('NS733','4','Lord, break my outer man;<br/>All independent traits<br/>To death confine by pow’r divine;<br/>Each feeling, thought and word regulate.<br/>Quiet soul reinstate,<br/>Every part saturate;<br/>Upon Your gentle voice I’d wait;<br/>Your move initiate! O Lord!<br/>Your move initiate! O Lord!<br/>',NULL,53417,4);
INSERT INTO stanza VALUES('NS733','5','Grant me the grace to bear<br/>What’s measured by Your hand;<br/>Lest I be blind and You withstand,<br/>Lord, do what pleases You—I consent!<br/>From my wounded heart raise<br/>Sacrifices of praise;<br/>I’d worship You in all Your ways<br/>And You as God appraise! O Lord!<br/>And You as God appraise! O Lord!<br/>',NULL,53418,5);
INSERT INTO stanza VALUES('NS733','6','O Lord, mature in me,<br/>Channel of life make me;<br/>That long before my days shall end,<br/>Life from my being flow constantly.<br/>Help us learn earnestly<br/>Skills to fight corporately,<br/>Perpetuate Your victory,<br/>Subdue Your enemy! O Lord!<br/>Subdue Your enemy! O Lord!<br/>',NULL,53419,6);
INSERT INTO stanza VALUES('NS734','1','On my bed night after night,<br/>I sought Him whom my soul loves.<br/>I sought Him, but I found Him not,<br/>I found Him not...<br/>',NULL,53420,1);
INSERT INTO stanza VALUES('NS734','2','I will rise now and go,<br/>About in the city,<br/>In the streets and in the squares.<br/>I will seek Him whom my soul loves.<br/>I sought Him, but found Him not.<br/>',NULL,53421,2);
INSERT INTO stanza VALUES('NS734','3','The watchmen who go,<br/>About in the city found me,<br/>Have you seen Him<br/>Whom my soul loves?<br/>Scarcely had I passed them,<br/>When I found Him<br/>Whom my soul loves,<br/>My soul loves!<br/>',NULL,53422,3);
INSERT INTO stanza VALUES('NS734','4','I found Him whom my soul loves!<br/>I held Him and would not let go.<br/>Until I had brought Him<br/>Into my mother’s house,<br/>Into the chamber<br/>Of her who conceived me<br/>My mother is grace,<br/>And I am a sinner saved by grace,<br/>Saved by grace.<br/>',NULL,53423,4);
INSERT INTO stanza VALUES('NS734','5','I found Him,<br/>I found Him whom my soul loves,<br/>I held Him,<br/>I found Him.<br/>I found Him.<br/>My soul loves You, my Lord, my Lord.<br/>',NULL,53424,5);
INSERT INTO stanza VALUES('NS735','1','The Spirit of the Lord is upon Me<br/>Because He has anointed Me,<br/>To announce the gospel to the poor,<br/>To proclaim the acceptable year of the Lord, jubilee.<br/>',NULL,53425,1);
INSERT INTO stanza VALUES('NS735','2','He has sent Me to proclaim release to the captives,<br/>And recovery of sight to the blind,<br/>To send away in release those who are oppressed,<br/>Who are oppressed. Jubilee!<br/>',NULL,53426,2);
INSERT INTO stanza VALUES('NS736','1','And you will know that I am Jehovah,<br/>when I open your graves<br/>and bring you up<br/>out of your graves, O My people,<br/>out of your graves, O My people.<br/>',NULL,53427,1);
INSERT INTO stanza VALUES('NS736','2','And I will put My Spirit in you,<br/>and you shall live,<br/>you shall live;<br/>and I will place you in your own land.<br/>Then you will know that I, Jehovah,<br/>have spoken and that I have performed it,<br/>declares Jehovah.<br/>',NULL,53428,2);
INSERT INTO stanza VALUES('NS737','1','What a rich enjoyment, living in God’s house!<br/>Oh, how sweet the church life to us!<br/>Breathe His holy name, and eat and drink His Word!<br/>Standingfor His church glorious!<br/>Walking, we are walking in His light of life today.<br/>Living, we are living; in the church of God to stay.<br/>We’re preserved by love, shined on by His light,<br/>All the members built up in love.<br/>',NULL,53429,1);
INSERT INTO stanza VALUES('NS738','1','Speak to the rock who was smitten for our full salvation!<br/>Sing to the well with a spirit of praise and elation!<br/>Drink the supply from God enthroned, the Most High,<br/>Our inexhaustible portion!<br/>',NULL,53430,1);
INSERT INTO stanza VALUES('NS738','2','God gave us Christ as the rock of our refuge, our rampart,<br/>Cov’ring from tempests, our strength, our protection, our bulwark!<br/>As we entreat, He is our shield and retreat;<br/>Morning by morning, our safeguard!<br/>',NULL,53431,2);
INSERT INTO stanza VALUES('NS738','3','God stands on Christ, the cleft rock, His own life to deliver!<br/>He comes as Spirit, refreshing us as the Life-giver!<br/>Our El Shaddai, our all-sufficient supply,<br/>Flows into us as a river!<br/>',NULL,53432,3);
INSERT INTO stanza VALUES('NS738','4','Christ is unlimited, flowing, our rock of salvation!<br/>Having done all, He’s awaiting our cooperation!<br/>Simply believe! Speak to the rock and receive!<br/>Drink Him with great jubilation!<br/>',NULL,53433,4);
INSERT INTO stanza VALUES('NS738','5','Our smitten rock has been following us without ceasing,<br/>Ready to flow out, the torrents of God’s life releasing!<br/>Life as a tide streams from the Lord’s wounded side,<br/>Thirst quenching, dryness appeasing!<br/>',NULL,53434,5);
INSERT INTO stanza VALUES('NS738','6','Life springs from death by the power of Christ’s resurrection!<br/>Baptism into His death brings release and protection!<br/>Subjectively, His cross continually<br/>Deepens the river’s extension!<br/>',NULL,53435,6);
INSERT INTO stanza VALUES('NS738','7','Dig out the well in the light of the Lord’s inner shining!<br/>Sense the anointing, to His inner feeling aligning;<br/>Prayer after prayer, through the Lord’s leading and care,<br/>Our inward parts He’s refining!<br/>',NULL,53436,7);
INSERT INTO stanza VALUES('NS738','8','The throne of God is the source of this crystalline river,<br/>Heading us up and renewing us for His good pleasure!<br/>His kingdom come! On earth, His will must be done!<br/>His be the glory forever!<br/>',NULL,53437,8);
INSERT INTO stanza VALUES('NS738','9','Sing songs of praise to the well, to the Christ we embody!<br/>Drink the one Spirit, as members of Christ’s unique Body!<br/>Thus sanctified, we are prepared as His Bride,<br/>Purified, spotless, and godly!<br/>',NULL,53438,9);
INSERT INTO stanza VALUES('NS738','10','Out of our innermost being flows rivers of water!<br/>Thus we’re conformed to the Son! What a joy to the Father!<br/>Jerusalem, God fully mingled with man,<br/>Flows forth this river forever!<br/>',NULL,53439,10);
INSERT INTO stanza VALUES('NS739','1','Come and let us return to Jehovah;<br/>For He has torn us, but He will heal us,<br/>And He has stricken us, but He will bind us up.<br/>He will enliven us after two days;<br/>And on the third day He will raise us up,<br/>And we will live in His presence.<br/>On the third day He will raise us up,<br/>And we will live in His presence.<br/>',NULL,53440,1);
INSERT INTO stanza VALUES('NS739','2','Therefore let us know,<br/>Let us pursue knowing Jehovah;<br/>Therefore let us know,<br/>Let us pursue knowing Jehovah:<br/>His going forth is as sure as the dawn<br/>And He will come to us as the rain<br/>As the late rain which waters the earth.<br/>Therefore let us know,<br/>Let us pursue knowing Jehovah.<br/>',NULL,53441,2);
INSERT INTO stanza VALUES('NS740','1','Lord, with all my heart I love You!<br/>Make my heart Your cherished prize!<br/>Pierce my depths with radiant brightness<br/>From Your loving eyes!<br/>In Your presence, as You’re shining,<br/>To Your will, O Lord, I yield!<br/>In this light, You are my comfort!<br/>Here Your heart’s revealed!<br/>',NULL,53442,1);
INSERT INTO stanza VALUES('NS740','chorus','Lord, to You I give my best love!<br/>How I treasure all You are!<br/>You’re the beacon, all men drawing!<br/>You’re my morning star!<br/>',NULL,53443,2);
INSERT INTO stanza VALUES('NS740','2','By the blood You shed at Calvary<br/>I’m defended constantly,<br/>Prayer by prayer, unloaded, cherished<br/>Unreservedly!<br/>Lord, I come to You with boldness!<br/>I believe Your precious blood!<br/>Speak to me, in my confessions!<br/>Bring me nigh to God!<br/>',NULL,53444,3);
INSERT INTO stanza VALUES('NS740','3','In this fellowship surrendered,<br/>In communion face to face,<br/>I am touched, Lord, and illumined<br/>In Your love’s embrace.<br/>I would linger in Your presence<br/>Spending time alone with You!<br/>As I bask in Your affection,<br/>Shine in me anew!<br/>',NULL,53445,4);
INSERT INTO stanza VALUES('NS740','4','Peace that passes understanding,<br/>Freedom from my struggles vain,<br/>Come from rest in You, confiding<br/>In Your inward reign!<br/>Your anointing and Your Headship<br/>Make Your feelings known in me;<br/>By Your love constrained, I follow<br/>Your lead inwardly!<br/>',NULL,53446,5);
INSERT INTO stanza VALUES('NS740','5','I refuse what doesn’t match You!<br/>All Your foes have met defeat!<br/>Satan’s pow’rs can’t stand against You!<br/>Victory is complete!<br/>In Your life, from death I’ve risen!<br/>In Your victory, I stand!<br/>What a blest, dependent living<br/>By the Father planned!<br/>',NULL,53447,6);
INSERT INTO stanza VALUES('NS740','6','May Your word, Lord, light my footsteps<br/>Till Your day dawns gloriously!<br/>May You come, Lord, with the rising<br/>Of Your star in me!<br/>Brightly shine within my heart, Lord!<br/>Deeply touch each hidden part!<br/>“Come, Beloved! Lord, come quickly!”<br/>Issues from my heart!<br/>',NULL,53448,7);
INSERT INTO stanza VALUES('NS741','1','When this poor sinner stands at last<br/>Perfected as a son,<br/>I’ll praise my God for many things<br/>But most what mercy’s done.<br/>While far from God and dead in sin<br/>Rich mercy did abound;<br/>I did not ask or seek for God<br/>But yet my Lord I found.<br/>',NULL,53449,1);
INSERT INTO stanza VALUES('NS741','2','I’m mercy’s vessel, this I know,<br/>For God has chosen me;<br/>The riches of His glory shall<br/>Thus manifested be.<br/>Not him who wills can follow now<br/>This way as yet unknown;<br/>Not him who runs can yet pursue,<br/>But to whom mercy’s shown.<br/>',NULL,53450,2);
INSERT INTO stanza VALUES('NS741','3','My Father’s lovingkindness, ’tis,<br/>That I am not consumed—<br/>For His compassions never fail;<br/>Each morning they are new.<br/>Through His compassions day by day<br/>I give myself to be<br/>Transformed and built with other saints,<br/>Christ’s Body thus to see.<br/>',NULL,53451,3);
INSERT INTO stanza VALUES('NS742','1','Where the Forerunner, Jesus,<br/>Has entered for us,<br/>Having become forever a High Priest<br/>According to, according to,<br/>According to the order of Melchizedek.<br/>',NULL,53452,1);
INSERT INTO stanza VALUES('NS742','2','Melchizedek the king of Salem<br/>Brought out bread and wine.<br/>Now he was priest,<br/>Was priest of God,<br/>Of God the Most High,<br/>Of God the Most High,<br/>Now he was priest of God,<br/>Of God the Most High.<br/>',NULL,53453,2);
INSERT INTO stanza VALUES('NS743','1','Let Your ear, Lord, be attentive,<br/>And Your eyes open to hear<br/>The prayer of Your servant<br/>Which echoes Your own will.<br/>Even when the king approached me<br/>I turned to You in prayer.<br/>I answered in Your wisdom;<br/>Now I will go and build.<br/>',NULL,53454,1);
INSERT INTO stanza VALUES('NS743','chorus','Let us rise up and build<br/>And strengthen our hands for the work.<br/>The God of heaven Himself will make us prosper.<br/>Lord, we have set our will,<br/>We will enter in Your work.<br/>',NULL,53455,2);
INSERT INTO stanza VALUES('NS743','2','All the walls are crushed and broken,<br/>And the gates once burned with fire,<br/>But we will not be discouraged,<br/>Our spirits never tire.<br/>Let the enemy oppose us;<br/>We will fight and build our part.<br/>To God this is our memorial;<br/>Remember, Lord, my heart!<br/>',NULL,53456,3);
INSERT INTO stanza VALUES('NS743','3','Now the walls are high and mighty;<br/>All our foes, they shake in fear.<br/>The people return and they gather<br/>God’s Holy Word to hear.<br/>We may mourn and weep in sorrow,<br/>But our God wants us to feast.<br/>Come in, eat the fat, drink the sweet wine!<br/>O Lord, we’re blessing Thee!<br/>',NULL,53457,4);
INSERT INTO stanza VALUES('NS744','1','Yet to us there is one God, the Father,<br/>out from whom are all things,<br/>and we are unto Him;<br/>and one Lord, Jesus Christ,<br/>through whom are all things,<br/>and we are through Him.<br/>',NULL,53458,1);
INSERT INTO stanza VALUES('NS745','1','Jesus, fair Thou art to me,<br/>More than gems most treasured,<br/>Purely, sweetly charming me,<br/>My delight and pleasure!<br/>',NULL,53459,1);
INSERT INTO stanza VALUES('NS745','chorus','Thou art fair! Thou art fair!<br/>Thou my heart hast captured!<br/>Keep me here forevermore,<br/>With Thee, Lord, enraptured!<br/>',NULL,53460,2);
INSERT INTO stanza VALUES('NS745','2','More than jewels I’ve seen before,<br/>Charming, mesmerizing;<br/>As I’m dazzled, drawn e’en more,<br/>Joy as dawn is rising.<br/>',NULL,53461,3);
INSERT INTO stanza VALUES('NS745','3','Stone that ne’er shall age or change,<br/>My fresh love restoring;<br/>Daily I anticipate<br/>Facets new each morning!<br/>',NULL,53462,4);
INSERT INTO stanza VALUES('NS745','4','Jesus, Thou art loveliest!<br/>Precious, matchless treasure!<br/>Shine in Thine exquisiteness,<br/>Clear and bright forever!<br/>',NULL,53463,5);
INSERT INTO stanza VALUES('NS746','1','The good land has been given—<br/>’Tis Christ in all He is!<br/>Let’s claim Him with boldness,<br/>Stand on God’s promises!<br/>He’s our allotted portion,<br/>So vast, immeasurable!<br/>Unsearchable riches!<br/>He’s inexhaustible!<br/>',NULL,53464,1);
INSERT INTO stanza VALUES('NS746','chorus','Look! Milk and honey flowing!<br/>What wealth there is to gain!<br/>We’re crossing river Jordan!<br/>We roam no more! We enter in,<br/>Christ to obtain!<br/>',NULL,53465,2);
INSERT INTO stanza VALUES('NS746','2','Though foes try every tactic<br/>To make us shy away,<br/>We, fearless, march onward,<br/>Much to their great dismay!<br/>Forgetting all our failures,<br/>We’re pressing on to seize<br/>The good land, God’s interest,<br/>With hearts of full belief!<br/>',NULL,53466,3);
INSERT INTO stanza VALUES('NS746','chorus','The giants may seem mighty,<br/>But God is on our side;<br/>He’s fighting for us daily!<br/>“The Nephilim are bread for us!”<br/>We boldly cry!<br/>',NULL,53467,4);
INSERT INTO stanza VALUES('NS746','3','Let us go up at once and<br/>Possess the land in sight,<br/>For we are well able<br/>To overcome with might!<br/>We care not for the outward;<br/>We hear not Satan’s lies.<br/>“Rejoice not against us,<br/>For when we fall, we rise!”<br/>',NULL,53468,5);
INSERT INTO stanza VALUES('NS746','chorus','Though we may feel defeated,<br/>“How can grasshoppers win?”<br/>That’s only in our own sight;<br/>So we no more look to ourselves<br/>But unto Him!<br/>',NULL,53469,6);
INSERT INTO stanza VALUES('NS746','4','We look unto our Captain,<br/>Our Leader and our Way;<br/>We know Him, show strength, and<br/>Take action right away!<br/>We execute His triumph,<br/>Subdue each foe we meet;<br/>Dominion He gives us<br/>To crush them ’neath our feet!<br/>',NULL,53470,7);
INSERT INTO stanza VALUES('NS746','chorus','We’re in this all together;<br/>We’re fighting corporately!<br/>The warrior-bride we’re readying!<br/>The enemy cannot withstand<br/>God’s formed army!<br/>',NULL,53471,8);
INSERT INTO stanza VALUES('NS746','5','’Tis not to win we’re fighting;<br/>We fight from victory;<br/>Our Captain is Conqu’ror<br/>And us to glory leads!<br/>Our banners we’re unfurling;<br/>Our armor’s linen bright;<br/>Our Love finds us lovely;<br/>Our foes are terrified!<br/>',NULL,53472,9);
INSERT INTO stanza VALUES('NS746','chorus','From glory unto glory,<br/>E’er higher we ascend;<br/>We’re pressing onward, upward,<br/>Jerusalem to Zion go,<br/>This age to end!<br/>',NULL,53473,10);
INSERT INTO stanza VALUES('NS746','end-note','Note on “our armor’s linen bright”: The saints fight with soft, linen armor (“Senir” meaning “soft armor” in S.S. 4:8; Rev. 19:14). Hard metal armor is unnecessary, for Christ has already won the victory! Hallelujah!<br/>',NULL,53474,11);
INSERT INTO stanza VALUES('NS747','1','Let’s seek God’s will for His purpose:<br/>Christ our center, Christ our focus;<br/>Christ our life and everything!<br/>God’s eternal will and pleasure:<br/>Christ wrought in us in full measure,<br/>All His fullness expressing!<br/><br/>He’s all-inclusive<br/>And all-extensive!<br/>Let’s know, experience Him!<br/>Let’s trust God’s counsel,<br/>Abide in God’s will,<br/>Make Christ our goal, quest, and theme!<br/>',NULL,53475,1);
INSERT INTO stanza VALUES('NS747','2','Daily, weekly, monthly, yearly,<br/>Christ our milk and Christ our honey,<br/>Sabbath, new moon and new feasts!<br/>Eat Him! Eat Him! Eat more of Him!<br/>Drink Him! Drink Him! Overflow Him!<br/>Breathe Him! Be His life increase!<br/><br/>Christ is our good land,<br/>A rich and vast land;<br/>We lack for nothing in Him!<br/>Now walk more in Him,<br/>Absorb more of Him,<br/>Filled more and more to the brim!<br/>',NULL,53476,2);
INSERT INTO stanza VALUES('NS747','3','Christ must be preeminent in<br/>Our love, our tripartite being,<br/>And our daily living too!<br/>In our spiritual experience,<br/>And our private universes,<br/>He must have the first place true!<br/><br/>We’ve all been chosen,<br/>A corporate person,<br/>To make Christ preeminent!<br/>God’s ruling o’er us<br/>In our universe<br/>To give Christ preeminence.<br/>',NULL,53477,3);
INSERT INTO stanza VALUES('NS747','4','Christ, God’s myst’ry, God embodied—<br/>In Him we’re made full and splendid;<br/>All God’s fullness dwells in Him!<br/>Let us realize what is in Him,<br/>Exercise faith, partake of Him,<br/>And lose sight of all but Him!<br/><br/>For all He is and<br/>Attained and obtained<br/>Belongs to us already!<br/>For all that He has<br/>Experienced has<br/>Become our own history!<br/>',NULL,53478,4);
INSERT INTO stanza VALUES('NS747','5','With Christ we have one position,<br/>One life, living, destination,<br/>Glory, in the heavenlies!<br/>Christ is our life, Christ’s subjective;<br/>He’s our living with one motive—<br/>Life and glory to release!<br/><br/>He’s all the members,<br/>In all the members;<br/>He constitutes the new man!<br/>His peace must rule us,<br/>His word must fill us,<br/>To manifest one new man.<br/>',NULL,53479,5);
INSERT INTO stanza VALUES('NS747','6','Broaden, lengthen, heighten, deepen<br/>Our spiritual dimensions;<br/>All Your fullness manifest!<br/>In each daily situation,<br/>With each person, time, location,<br/>Magnify Your boundlessness!<br/><br/>You’re all inclusive!<br/>You’re all extensive!<br/>This light must penetrate us!<br/>May all Your riches,<br/>Your exhaustlessness,<br/>Be day by day wrought in us!<br/>',NULL,53480,6);
INSERT INTO stanza VALUES('NS748','1','Your words were found,<br/>And I ate them.<br/>And Your words became,<br/>Became to me,<br/>The gladness and joy<br/>Of my heart,<br/>Became the gladness and joy<br/>Of my heart.<br/>',NULL,53481,1);
INSERT INTO stanza VALUES('NS748','2','I will muse upon your precepts,<br/>And regard Your ways,<br/>I will turn the Bible into<br/>Both my prayer and praise.<br/>I will sing it in the morning,<br/>And I’ll pray it all day long,<br/>Until Jehovah has become<br/>My strength and song.<br/>',NULL,53482,2);
INSERT INTO stanza VALUES('NS749','1','And to enlighten all<br/>That they may see,<br/>And to enlighten all<br/>That they may see,<br/>And to enlighten all<br/>That they may see,<br/>See the mystery.<br/>',NULL,53483,1);
INSERT INTO stanza VALUES('NS749','2','And to enlighten all<br/>That they may see<br/>What the economy<br/>Of the mystery is,<br/>And to enlighten all<br/>That they may see,<br/>See the mystery.<br/>',NULL,53484,2);
INSERT INTO stanza VALUES('NS749','3','Which throughout the ages<br/>Has been hidden in God,<br/>God who created all things,<br/>Which throughout the ages<br/>Has been hidden in God,<br/>God who created all things.<br/>',NULL,53485,3);
INSERT INTO stanza VALUES('NS749','4','And to enlighten all<br/>That they may see,<br/>And to enlighten all<br/>That they may see,<br/>And to enlighten all<br/>That they may see,<br/>See the mystery.<br/>',NULL,53486,4);
INSERT INTO stanza VALUES('NS749','5','And to enlighten all<br/>That they may see<br/>What the economy<br/>Of the mystery is,<br/>And to enlighten all<br/>That they may see,<br/>See the mystery.<br/>',NULL,53487,5);
INSERT INTO stanza VALUES('NS749','6','In order that now to the rulers <br/>And authorities in heavenlies<br/>The multifarious wisdom of God<br/>Might be known through the church,<br/>According to the eternal purpose<br/>Which He made in Christ Jesus our Lord,<br/>According to the eternal purpose<br/>Which He made in Christ Jesus our Lord,<br/>Which He made in Christ Jesus our Lord.<br/>',NULL,53488,6);
INSERT INTO stanza VALUES('NS750','1','Jesus Lord, I truly love You.<br/>I must gain—gain only You.<br/>Your great love has reached me, transforming me<br/>E’en made me Thy Beloved.<br/>',NULL,53489,1);
INSERT INTO stanza VALUES('NS750','chorus','Day by day, unceasingly,<br/>Sweetly whispering in me,<br/>My whole heart You melt! My spirit within<br/>Rejoices, Lord, with Thee!<br/>',NULL,53490,2);
INSERT INTO stanza VALUES('NS750','2','Love constrains me, draws gradually,<br/>To pour out my all to Thee;<br/>All my life and future, once held so dear,<br/>I yield wholeheartedly.<br/>',NULL,53491,3);
INSERT INTO stanza VALUES('NS750','chorus','Thy hands break me faithfully—<br/>The burnt off’ring’s flame burns bright;<br/>Only after death does suffering cease;<br/>My soul-life I deny.<br/>',NULL,53492,4);
INSERT INTO stanza VALUES('NS750','3','Breaking of the outer man frees;<br/>Inner life thus is released;<br/>Living water, in resurrection life,<br/>Flows forth abundantly.<br/>',NULL,53493,5);
INSERT INTO stanza VALUES('NS750','chorus','No more I who live, but Thee;<br/>It is Christ who lives in me;<br/>My humanity now transparently<br/>Expresses only Thee.<br/>',NULL,53494,6);
INSERT INTO stanza VALUES('NS750','4','Show me, Lord, a vision more clear;<br/>Draw me on, higher, more near;<br/>That I’d deeply long to see Thee come soon,<br/>And build Thy Body dear.<br/>',NULL,53495,7);
INSERT INTO stanza VALUES('NS750','chorus','Lord, Thy glory’s blinded me;<br/>I the world no more can see.<br/>Now unhindered, I must finish the race,<br/>Run swiftly, steadfastly.<br/>',NULL,53496,8);
INSERT INTO stanza VALUES('NS750','5','See the prize ahead, very near!<br/>Soon the Kingdom will appear!<br/>Virgins, quickly rise! Trim your lamps! Behold,<br/>Here comes Your Bridegroom dear!<br/>',NULL,53497,9);
INSERT INTO stanza VALUES('NS750','chorus','Full account the Master makes:<br/>“Well done! Well done! Faithful slave!”<br/>Wedding feast, the Kingdom, New Jerusalem—<br/>Eternal joy and praise<br/>',NULL,53498,10);
INSERT INTO stanza VALUES('NS751','1','He Himself is our peace,<br/>He who made both into one.<br/>Peace with God, peace with man,<br/>All the enmity is gone.<br/>Peace within, peace without,<br/>Through Himself and for His plan.<br/>Peace is Christ, and He’s in us,<br/>We are now the one new man!<br/>',NULL,53499,1);
INSERT INTO stanza VALUES('NS751','2','Abolishing in His flesh,<br/>Commandments in the ordinances.<br/>That He might make the two<br/>In Himself into one new man.<br/>Making peace!<br/>Making peace!<br/>In Himself and through the cross,<br/>Making peace!<br/>Making peace!<br/>We are now the one new man.<br/>',NULL,53500,2);
INSERT INTO stanza VALUES('NS752','1','Sitting in an ordinary home on the couch,<br/>Feasting on the Christ that’s growing in all the saints;<br/>Here I touch the purpose of why I am living—<br/>Eating, drinking, building with the saints!<br/>',NULL,53501,1);
INSERT INTO stanza VALUES('NS752','chorus','Day by day as we partake of such a Christ,<br/>We are built together as His house, so bright!<br/>Here the river’s flowing with the tree of life,<br/>In God’s light we’re headed up aright!<br/>',NULL,53502,2);
INSERT INTO stanza VALUES('NS752','2','Drawn by Him each morning at His dear face we gaze,<br/>Sitting at His feet each day His speaking we heed,<br/>Then in Him we’re living, Him to others shining,<br/>Bearing fruit we’re filled with joy indeed!<br/>',NULL,53503,3);
INSERT INTO stanza VALUES('NS752','3','Holding truth in love we’re growing up into Christ,<br/>Honouring each other that we’re members we prove;<br/>Through the cross, by Spirit, Christ we are dispensing,<br/>Blended as the one new man we move.<br/>',NULL,53504,4);
INSERT INTO stanza VALUES('NS752','chorus','House to house we’re practising the Body life,<br/>We in life are reigning as His loving bride;<br/>Here we have the foretaste of our destiny—<br/>God and man completely satisfied!<br/>',NULL,53505,5);
INSERT INTO stanza VALUES('NS753','1','Once in the world we wandered all,<br/>Enslaved by sin, under usurpation;<br/>But He chose, redeemed us<br/>From bondage, fall,<br/>Revealed to us His divine intention.<br/>Now that we see His heart’s desire,<br/>We willingly give our life entire.<br/>',NULL,53506,1);
INSERT INTO stanza VALUES('NS753','chorus','O Lord, we now lay all aside:<br/>Self-choice, own cares, and all self-love;<br/>O Christ, the meaning of our life,<br/>Our goal and aim, there’s none beside;<br/>Toward the good land, we now are poised<br/>To take, possess, Your perfect choice.<br/>',NULL,53507,2);
INSERT INTO stanza VALUES('NS753','2','As priestly army we are formed;<br/>To fight for Him, journey with Him, able;<br/>Whether trouble rise up or raging storm,<br/>He’ll care for us; we’re His numbered people.<br/>Waters of death we fain would pass;<br/>Defeat the foes: they are food for us!<br/>',NULL,53508,3);
INSERT INTO stanza VALUES('NS753','3','Unlike the two and one-half tribes<br/>Which settled on the land “good for cattle”;<br/>Our own ease and comfort can never bribe;<br/>God’s choice in sight, we will enter in full!<br/>For east of Jordan’s not our rest,<br/>We’ll cross, not settling for second-best.<br/>',NULL,53509,4);
INSERT INTO stanza VALUES('NS753','4','Stretch forward! Christ we now lay hold.<br/>Called upward to pursue goal eternal;<br/>When we take His cross and be in His mold,<br/>His Body’s built; Christ is all and in all.<br/>We press on to prepare His Bride;<br/>He chose us to be His heart’s delight.<br/>',NULL,53510,5);
INSERT INTO stanza VALUES('BF440','1','Rivers of living water,<br/>Rivers that flow from the throne,<br/>Rivers o’erflowing with blessing,<br/>Coming from Jesus alone.<br/>',NULL,53511,1);
INSERT INTO stanza VALUES('BF440','chorus','Rivers of living water,<br/>Rivers of life so free,<br/>Flowing from Thee, my Savior,<br/>Send now this life through me.<br/>',NULL,53512,2);
INSERT INTO stanza VALUES('BF440','2','Whoso is thirsty come hither,<br/>Here is abundant supply;<br/>Water transparent as crystal,<br/>Come without money and buy.<br/>',NULL,53513,3);
INSERT INTO stanza VALUES('BF440','3','Cleanse me, oh, cleanse me, my Savior,<br/>Make me a channel today;<br/>Empty me, fill me and use me,<br/>Teach me to trust and obey.<br/>',NULL,53514,4);
INSERT INTO stanza VALUES('BF440','4','Then, and then only, Lord Jesus,<br/>Through me the rivers can flow;<br/>Thus and thus only will others<br/>Learn Thy great fulness to know.<br/>',NULL,53515,5);
INSERT INTO stanza VALUES('BF440','5','Now I surrender to Jesus,<br/>Here I lay all at His feet;<br/>Anything, anywhere only,<br/>Just for His service made meet!<br/>',NULL,53516,6);
INSERT INTO stanza VALUES('BF441','1','Full salvation! Full salvation!<br/>Lo, the fountain opened wide,<br/>Streams through every land and nation<br/>From the Savior’s wounded side.<br/>Full salvation! Full salvation!<br/>Streams an endless crimson tide.<br/>',NULL,53522,1);
INSERT INTO stanza VALUES('BF441','2','Oh, the glorious revelation!<br/>See the cleansing current flow,<br/>Washing stains of condemnation<br/>Whiter than the driven snow:<br/>Full salvation! Full salvation!<br/>Oh, the rapturous bliss to know.<br/>',NULL,53523,2);
INSERT INTO stanza VALUES('BF441','3','Love’s resistless current sweeping<br/>All the regions deep within;<br/>Thought, and wish, and senses keeping<br/>Now, and every instant, clean:<br/>Full salvation! Full salvation!<br/>From the guilt and power of sin.<br/>',NULL,53524,3);
INSERT INTO stanza VALUES('BF441','4','Life immortal, Christ descending,<br/>Lo! my heart the Spirit’s shrine:<br/>God and man in oneness blending,<br/>Oh, what fellowship is mine!<br/>Full salvation! Full salvation!<br/>Raised in Christ to life divine!<br/>',NULL,53525,4);
INSERT INTO stanza VALUES('BF441','5','Care and doubting, gloom and sorrow,<br/>Fear and shame are mine no more;<br/>Faith knows naught of dark tomorrow,<br/>For my Savior goes before:<br/>Full salvation! Full salvation!<br/>Full and free for evermore!<br/>',NULL,53526,5);
INSERT INTO stanza VALUES('BF442','1','How firm a foundation, ye saints of the Lord,<br/>Is laid for your faith in His excellent word!<br/>What more can He say than to you He hath said,<br/>To you who for refuge to Jesus have fled?<br/><br/>“Fear not, I am with thee, O be not dismayed,<br/>For I am thy God, and will still give thee aid;<br/>I’ll strengthen thee, help thee, and cause thee to stand,<br/>Upheld by My righteous, omnipotent hand.”<br/><br/>“When through the deep waters I call thee to go,<br/>The rivers of sorrow shall not overflow;<br/>For I will be with thee, thy troubles to bless,<br/>And sanctify to thee thy deepest distress.”<br/>',NULL,53527,1);
INSERT INTO stanza VALUES('BF442','2','“When through fiery trials thy pathway shall lie,<br/>My grace, all sufficient, shall be thy supply;<br/>The flame shall not hurt thee; I only design<br/>Thy dross to consume, and thy gold to refine.”<br/><br/>“E’en down to old age all My people shall prove<br/>My sovereign, eternal, unchangeable love;<br/>And then, when grey hairs shall their temples adorn,<br/>Like lambs they shall still in My bosom be borne.”<br/><br/>“The soul that on Jesus hath leaned for repose,<br/>I will not, I will not desert to his foes;<br/>That soul, though all hell should endeavor to shake,<br/>I’ll never, no, never, no, never forsake!”<br/>',NULL,53528,2);
INSERT INTO stanza VALUES('BF443','1','Let me love Thee, Thou art claiming<br/>Every feeling of my soul;<br/>Let that love in pow’r prevailing,<br/>Render Thee my life, my all;<br/>For life’s burdens they are easy,<br/>And life’s sorrows lose their sting,<br/>If they’re carried, Lord, to please Thee,<br/>If their pain Thy smile should win.<br/>',NULL,53529,1);
INSERT INTO stanza VALUES('BF443','chorus','Let me love Thee, Savior,<br/>Take my heart forever;<br/>Nothing but Thy favor<br/>My soul can satisfy.<br/>',NULL,53530,2);
INSERT INTO stanza VALUES('BF443','2','Let me love Thee, come revealing<br/>All Thy love has done for me;<br/>Help my heart, so unbelieving,<br/>By the sight of Calvary:<br/>Let me see Thy love despising<br/>All the shame my sins had brought;<br/>By Thy torments realizing<br/>What a price my pardon bought.<br/>',NULL,53531,3);
INSERT INTO stanza VALUES('BF443','3','Let me love Thee, I am gladdest<br/>When I’m loving Thee, the best;<br/>For in sunshine or in sadness<br/>I can find in Thee a rest;<br/>But without Thee life is fading,<br/>Treasureless its choicest flowers;<br/>Taken are its gifts eternal;<br/>Left, its empty passing hours.<br/>',NULL,53532,4);
INSERT INTO stanza VALUES('BF443','4','Let me love Thee, love is mighty,<br/>Swaying realms of deed and thought;<br/>By it I shall walk uprightly,<br/>I shall serve Thee as I ought:<br/>Love will soften every sorrow,<br/>Love will lighten every care,<br/>Love unquestioning will follow,<br/>Love will triumph, love will dare.<br/>',NULL,53533,5);
INSERT INTO stanza VALUES('BF444','1','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Thou art the Potter,<br/>I am the clay.<br/>Mould me and make me<br/>After Thy will,<br/>While I am waiting,<br/>Yielded and still.<br/>',NULL,53534,1);
INSERT INTO stanza VALUES('BF444','2','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Search me and try me,<br/>Master, today.<br/>Whiter than snow, Lord,<br/>Wash me just now,<br/>As in Thy presence<br/>Humbly I bow.<br/>',NULL,53535,2);
INSERT INTO stanza VALUES('BF444','3','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Wounded and weary,<br/>Help me, I pray.<br/>Power, all power,<br/>Surely is Thine,<br/>Touch me and heal me,<br/>Savior divine.<br/>',NULL,53536,3);
INSERT INTO stanza VALUES('BF444','4','Have Thine own way, Lord,<br/>Have Thine own way;<br/>Hold o’er my being<br/>Absolute sway.<br/>Fill with Thy Spirit<br/>Till all shall see<br/>Christ only, always,<br/>Living in me.<br/>',NULL,53537,4);
INSERT INTO stanza VALUES('BF445','1','Christ is the one reality of all,<br/>Of Godhead and of man and all things else;<br/>No man without Him ever findeth God,<br/>Without Him man and everything is false.<br/>',NULL,53538,1);
INSERT INTO stanza VALUES('BF445','2','All types and figures of the ancient time,<br/>All things we ever need, both great and small,<br/>Only are shadows of the Christ of God,<br/>Showing that He must be our all in all.<br/>',NULL,53539,2);
INSERT INTO stanza VALUES('BF445','3','All things are vanity of vanities,<br/>Christ, the reality all things to fill;<br/>Though everything we may enjoy and own,<br/>If we’re devoid of Christ we’re empty still.<br/>',NULL,53540,3);
INSERT INTO stanza VALUES('BF445','4','Christ is our real God, our real Lord,<br/>Christ is our real life, our real light;<br/>Christ is our real food, our real drink,<br/>Our real clothing, and our real might.<br/>',NULL,53541,4);
INSERT INTO stanza VALUES('BF445','5','Christ also is the one reality<br/>Of all our doctrine and theology;<br/>And all our scriptural knowledge without Him<br/>Is just in letter and is vanity.<br/>',NULL,53542,5);
INSERT INTO stanza VALUES('BF445','6','Christ, the reality of time and space,<br/>Christ, the reality of every stage;<br/>Christ is the one reality of all<br/>Thru all eternity from age to age.<br/>',NULL,53543,6);
INSERT INTO stanza VALUES('BF446','1','I have come to the Fountain of Life,<br/>A fountain that flows from above;<br/>I have passed from the waters of strife<br/>And come to the Elim of love;<br/>I have drunk of the heavenly well,<br/>In the depths of my being it springs.<br/>No mortal can measure or tell<br/>The gladness the Comforter brings.<br/>',NULL,53544,1);
INSERT INTO stanza VALUES('BF446','chorus','Oh, come to the Fountain of Life,<br/>The fountain that never runs dry;<br/>Oh, drink of the boundless supply,<br/>For Christ is the Fountain of Life.<br/>',NULL,53545,2);
INSERT INTO stanza VALUES('BF446','2','I have come to the Fountain of Blood<br/>That for guilt and uncleanness doth flow;<br/>I have washed in its sin-cleansing flood<br/>And my garments are whiter than snow.<br/>I count not my righteousness mine—<br/>’Tis Jesus that lives in my soul.<br/>I partake of His nature divine,<br/>And in Him I am perfectly whole.<br/>',NULL,53546,3);
INSERT INTO stanza VALUES('BF446','3','I have come to the Fountain of Health,<br/>A boundless and endless supply;<br/>’Tis a secret man’s wisdom or wealth<br/>Can never discover or buy.<br/>But the secret my Lord hath revealed<br/>In the fountain that flows from His side,<br/>In the stripes by whose pain we are healed,<br/>In Himself as He comes to abide.<br/>',NULL,53547,4);
INSERT INTO stanza VALUES('BF446','4','I have come to the Fountain of Joy;<br/>His joy is the strength of my heart.<br/>My delight is unmixed with alloy,<br/>My sunshine can never depart.<br/>The fig tree may wither and die,<br/>Earth’s pleasures and prospects decline;<br/>But my fountains can never be dry—<br/>My portion, my joy is divine.<br/>',NULL,53548,5);
INSERT INTO stanza VALUES('BF447','1','Jesus, Fountain of my days,<br/>Well-spring of my heart’s delight,<br/>Brightness of my morning rays,<br/>Solace of my hours of night;<br/>When I see Thee, I arise<br/>To the hope of cloudless skies.<br/>',NULL,53549,1);
INSERT INTO stanza VALUES('BF447','2','Oh, how weary were the years<br/>Ere Thy form to me was known;<br/>Oh, how gloomy were the fears<br/>When I seemed to be alone;<br/>I despaired the storm to brave<br/>Till Thy footprints touched the wave.<br/>',NULL,53550,2);
INSERT INTO stanza VALUES('BF447','3','But Thy presence on the deep<br/>Calmed the pulses of the sea,<br/>And the waters sank to sleep<br/>In the rest of seeing Thee;<br/>And my once rebellious will<br/>Heard the mandate, Peace, be still!<br/>',NULL,53551,3);
INSERT INTO stanza VALUES('BF447','4','Now Thy will and mine are one,<br/>Heart in heart, and hand in hand;<br/>All the clouds have touched the sun,<br/>And the ships have reached the land;<br/>For Thy love has said to me,<br/>No more night! and No more sea!<br/>',NULL,53552,4);
INSERT INTO stanza VALUES('BF448','1','Why should I fear the darkest hour,<br/>Or tremble at the tempter’s power?<br/>Jesus vouchsafes to be my tower.<br/>Jesus my tower!<br/>',NULL,53553,1);
INSERT INTO stanza VALUES('BF448','2','Though hot the fight, why quit the field?<br/>Why must I either fly or yield,<br/>Since Jesus is my mighty shield?<br/>Jesus my shield!<br/>',NULL,53554,2);
INSERT INTO stanza VALUES('BF448','3','When creature comforts fade and die,<br/>Worldlings may weep, but why should I?<br/>Jesus still lives, and still is nigh.<br/>Jesus is nigh!<br/>',NULL,53555,3);
INSERT INTO stanza VALUES('BF448','4','Though all the flocks and herds were dead,<br/>My soul a famine need not dread,<br/>For Jesus is my living bread.<br/>Jesus my bread!<br/>',NULL,53556,4);
INSERT INTO stanza VALUES('BF448','5','I know not what may soon betide,<br/>Or how my wants shall be supplied;<br/>But Jesus knows, and will provide.<br/>Jesus provides!<br/>',NULL,53557,5);
INSERT INTO stanza VALUES('BF448','6','Though sin would fill me with distress,<br/>The throne of grace I dare address,<br/>For Jesus is my righteousness.<br/>My righteousness!<br/>',NULL,53558,6);
INSERT INTO stanza VALUES('BF448','7','Though faint my prayers and cold my love,<br/>My steadfast hope shall not remove,<br/>While Jesus intercedes above.<br/>He intercedes!<br/>',NULL,53559,7);
INSERT INTO stanza VALUES('BF448','8','Against me earth and hell combine;<br/>But on my side is power divine;<br/>Jesus is all, and He is mine!<br/>Jesus is mine!<br/>',NULL,53560,8);
INSERT INTO stanza VALUES('BF449','1','Break Thou the Bread of Life,<br/>Dear Lord, to me,<br/>As Thou didst break the loaves<br/>Beside the sea;<br/>Beyond the sacred page<br/>I seek Thee, Lord;<br/>My spirit pants for Thee,<br/>O Living Word.<br/>',NULL,53561,1);
INSERT INTO stanza VALUES('BF449','chorus','Break Thou the Bread of Life,<br/>Dear Lord, to me,<br/>As Thou didst break the loaves<br/>Beside the sea;<br/>Beyond the sacred page<br/>I seek Thee, Lord;<br/>My spirit pants for Thee,<br/>O Living Word.<br/>',NULL,53562,2);
INSERT INTO stanza VALUES('BF449','2','Thou art the Bread of Life,<br/>O Lord, to me,<br/>Thy holy Word the truth<br/>That saveth me;<br/>Give me to eat and live<br/>With Thee above;<br/>Teach me to love Thy truth,<br/>For Thou art Love.<br/>',NULL,53563,3);
INSERT INTO stanza VALUES('BF449','3','Oh, send Thy Spirit, Lord,<br/>Now unto me,<br/>That He may touch my eyes,<br/>And make me see;<br/>Show me the truth concealed<br/>Within Thy Word,<br/>And in Thy Book revealed<br/>I see the Lord.<br/>',NULL,53564,4);
INSERT INTO stanza VALUES('BF449','4','Bless Thou the truth, dear Lord,<br/>To me, to me,<br/>As Thou didst bless the bread<br/>By Galilee;<br/>Then shall all bondage cease,<br/>All fetters fall,<br/>And I shall find my peace,<br/>My All in all.<br/>',NULL,53565,5);
INSERT INTO stanza VALUES('BF450','1','Loved with everlasting love,<br/>Led by grace that love to know;<br/>Spirit, breathing from above,<br/>Thou hast taught me it is so.<br/>Oh, this full and perfect peace!<br/>Oh, this transport all divine!<br/>In a love which cannot cease,<br/>I am His, and He is mine.<br/>',NULL,53566,1);
INSERT INTO stanza VALUES('BF450','2','Heaven above is softer blue,<br/>Earth around is sweeter green;<br/>Something lives in every hue<br/>Christless eyes have never seen:<br/>Birds with gladder songs o’erflow,<br/>Flow’rs with deeper beauties shine,<br/>Since I know, as now I know,<br/>I am His, and He is mine.<br/>',NULL,53567,2);
INSERT INTO stanza VALUES('BF450','3','Things that once were wild alarms<br/>Cannot now disturb my rest;<br/>Closed in everlasting arms,<br/>Pillowed on the loving breast.<br/>Oh, to lie forever here,<br/>Doubt and care and self resign,<br/>While He whispers in my ear,<br/>I am His, and He is mine.<br/>',NULL,53568,3);
INSERT INTO stanza VALUES('BF450','4','His forever, only His:<br/>Who the Lord and me shall part?<br/>Ah, with what a rest of bliss<br/>Christ can fill the loving heart.<br/>Heaven and earth may fade and flee,<br/>Firstborn light in gloom decline;<br/>But, while God and I shall be,<br/>I am His, and He is mine.<br/>',NULL,53569,4);
INSERT INTO stanza VALUES('BF451','1','My goal is God Himself, not joy, nor peace,<br/>Nor even blessing, but Himself, my God;<br/>’Tis His to lead me there—not mine, but His—<br/>At any cost, dear Lord, by any road.<br/>',NULL,53570,1);
INSERT INTO stanza VALUES('BF451','2','So faith bounds forward to its goal in God,<br/>And love can trust her Lord to lead her there;<br/>Upheld by Him, my soul is following hard<br/>Till God hath full fulfilled my deepest prayer.<br/>',NULL,53571,2);
INSERT INTO stanza VALUES('BF451','3','No matter if the way be sometimes dark,<br/>No matter though the cost be oft-times great,<br/>He knoweth how I best shall reach the mark,<br/>The way that leads to Him must needs be strait.<br/>',NULL,53572,3);
INSERT INTO stanza VALUES('BF451','4','One thing I know, I cannot say Him nay;<br/>One thing I do, I press towards my Lord;<br/>My God my glory here, from day to day,<br/>And in the glory there my great Reward.<br/>',NULL,53573,4);
INSERT INTO stanza VALUES('BF452','1','Unto him that hath Thou givest<br/>Ever more abundantly;<br/>Lord, I live because Thou livest,<br/>Therefore give more life to me,<br/>Therefore speed me in the race,<br/>Therefore let me grow in grace.<br/>',NULL,53574,1);
INSERT INTO stanza VALUES('BF452','2','Deepen all Thy work, O Master,<br/>Strengthen every downward root;<br/>Only do Thou ripen faster,<br/>More and more Thy pleasant fruit;<br/>Purge me, prune me, self abase;<br/>Only let me grow in grace.<br/>',NULL,53575,2);
INSERT INTO stanza VALUES('BF452','3','Let me grow by sun and shower,<br/>Every moment water me;<br/>Make me really, hour by hour,<br/>More and more conformed to Thee,<br/>That Thy loving eye may trace<br/>Day by day my growth in grace.<br/>',NULL,53576,3);
INSERT INTO stanza VALUES('BF452','4','From Thy fulness grace outpouring,<br/>Show me ever greater things;<br/>Raise me higher, sunward soaring,<br/>Mounting as on eagle-wings.<br/>By the brightness of Thy face,<br/>Ever let me grow in grace.<br/>',NULL,53577,4);
INSERT INTO stanza VALUES('BF452','5','Let me, then, be always growing,<br/>Never, never standing still,<br/>Listening, learning, better knowing<br/>Thee and Thy most blessed will.<br/>Till I win the glorious race,<br/>Daily let me grow in grace.<br/>',NULL,53578,5);
INSERT INTO stanza VALUES('BF452','end-note','(Repeat the last two lines of each stanza)<br/>',NULL,53579,6);
INSERT INTO stanza VALUES('BF453','1','I know not what awaits me,<br/>God kindly veils my eyes,<br/>And o’er each step of my onward way<br/>He makes new scenes to rise;<br/>And every joy He sends me comes<br/>A sweet and glad surprise.<br/>',NULL,53580,1);
INSERT INTO stanza VALUES('BF453','chorus','Where He may lead me I’ll follow,<br/>My trust in Him repose;<br/>And every hour in perfect peace,<br/>I’ll sing, “He knows, He knows”,<br/>I’ll sing, “He knows, He knows.”<br/>',NULL,53581,2);
INSERT INTO stanza VALUES('BF453','2','One step I see before me,<br/>’Tis all I need to see,<br/>The light of heaven more brightly shines<br/>When earth’s illusions flee;<br/>And sweetly through the silence comes,<br/>His loving, “Trust in Me!”<br/>',NULL,53582,3);
INSERT INTO stanza VALUES('BF453','3','Oh, blissful lack of wisdom,<br/>’Tis blessed not to know;<br/>He holds me with His own right hand,<br/>And will not let me go,<br/>And lulls my troubled soul to rest<br/>In Him who loves me so.<br/>',NULL,53583,4);
INSERT INTO stanza VALUES('BF453','4','So on I go not knowing;<br/>I would not if I might;<br/>I’d rather walk in the dark with God<br/>Than go alone in the light;<br/>I’d rather walk by faith with Him<br/>Than go alone by sight.<br/>',NULL,53584,5);
INSERT INTO stanza VALUES('BF454','1','God hath not promised skies always blue,<br/>Flower-strewn pathways all our lives through;<br/>God hath not promised sun without rain,<br/>Joy without sorrow, peace without pain.<br/>',NULL,53585,1);
INSERT INTO stanza VALUES('BF454','chorus','But God hath promised strength for the day,<br/>Rest for the labor, light for the way,<br/>Grace for the trials, help from above,<br/>Unfailing sympathy, undying love.<br/>',NULL,53586,2);
INSERT INTO stanza VALUES('BF454','2','God hath not promised we shall not know<br/>Toil and temptation, trouble and woe;<br/>He hath not told us we shall not bear<br/>Many a burden, many a care.<br/>',NULL,53587,3);
INSERT INTO stanza VALUES('BF454','3','God hath not promised smooth roads and wide,<br/>Swift, easy travel, needing no guide;<br/>Never a mountain, rocky and steep,<br/>Never a river, turbid and deep.<br/>',NULL,53588,4);
INSERT INTO stanza VALUES('Z1','1','但愿荣耀归于圣父，<br/>并圣子基督，<br/>且愿荣耀归于圣灵<br/>到永古。<br/>','',53589,7123);
INSERT INTO stanza VALUES('Z1','2','当我观赏广大创造-神智所制订，<br/>我灵受感，立献敬拜，<br/>并肃静。<br/>','',53590,7124);
INSERT INTO stanza VALUES('Z1','3','但是我神，你是深愿：<br/>能得有众子，<br/>今在子里对你赞美，<br/>并赏识。<br/>','',53591,7125);
INSERT INTO stanza VALUES('Z1','4','你话已向我们启示，<br/>你情爱秘密，<br/>为要我们领略接受，<br/>以爱你。<br/>','',53592,7126);
INSERT INTO stanza VALUES('Z1','5','因此借着基督救赎，<br/>既将敌全克，<br/>在新造里你就带来<br/>敬拜者。<br/>','',53593,7127);
INSERT INTO stanza VALUES('Z1','6','但愿荣耀归于圣父，<br/>并圣子基督，<br/>且愿荣耀归于圣灵<br/>到永古。<br/>','',53594,7128);
INSERT INTO stanza VALUES('Z2','1','荣耀、荣耀、荣耀、<br/>赞美、崇敬、爱戴！<br/>听哪，颂赞声浪，<br/>从永世一直澎湃！<br/>圣父、圣子、圣灵-<br/>神，已启示出来，<br/>人人都当向祂俯伏敬拜！<br/>','',53595,7129);
INSERT INTO stanza VALUES('Z2','2','圣父乃是源头，<br/>荣耀、无限、丰厚；<br/>圣子借着权能，<br/>以命令托住万有；<br/>圣灵充满全景，<br/>荣耀、无往不透，<br/>哦，这荣耀丰满<br/>配得歌讴！<br/>','',53596,7130);
INSERT INTO stanza VALUES('Z2','3','尊高、伟大真神，<br/>万有有福元首，<br/>我们今以圣洁<br/>作装饰向你拜叩！<br/>威严、尊大、权能、<br/>荣耀、高超、优秀，<br/>全属你这万有永远源头！<br/>','',53597,7131);
INSERT INTO stanza VALUES('Z3','1','荣耀、荣耀归于圣父，<br/>荣耀、荣耀归圣子，<br/>荣耀、荣耀归于圣灵，<br/>荣耀归神永无止。<br/>','',53598,7132);
INSERT INTO stanza VALUES('Z3','chorus','高声赞美！<br/>高声赞美！<br/>高声赞美三一神！<br/>荣耀归祂！<br/>荣耀归祂！<br/>荣耀、荣耀，<br/>神来施救恩。<br/>','',53599,7133);
INSERT INTO stanza VALUES('Z3','2','赞美圣父定意、计划，<br/>赞美圣子来完成，<br/>赞美圣灵运行、实施，<br/>赞美三一作生命。<br/>','',53600,7134);
INSERT INTO stanza VALUES('Z3','3','荣耀、荣耀归于圣父，<br/>荣耀、荣耀归圣子，<br/>荣耀、荣耀归于圣灵，<br/>荣耀归神永无止。<br/>','',53601,7135);
INSERT INTO stanza VALUES('Z4','1','圣哉、圣哉、圣哉，<br/>全能的主神！<br/>我们向你扬声，<br/>颂赞直到永远；<br/>圣哉、圣哉、圣哉，<br/>全能而又慈怜！<br/>一神别三位，<br/>三位是一身！<br/>','',53602,7136);
INSERT INTO stanza VALUES('Z4','2','圣哉、圣哉、圣哉，<br/>众圣都俯伏；<br/>天上长老在你<br/>座前金冠抛开；<br/>基路伯、撒拉弗，<br/>也都一同敬拜<br/>你昔在、今在、<br/>永远常在主。<br/>','',53603,7137);
INSERT INTO stanza VALUES('Z4','3','圣哉、圣哉、圣哉，<br/>你藏身黑暗，<br/>罪人也都不能<br/>看见你的荣光，<br/>惟你乃是至圣，<br/>无人与你相像，<br/>爱心并纯洁、<br/>能力都完全。<br/>','',53604,7138);
INSERT INTO stanza VALUES('Z4','4','圣哉、圣哉、圣哉，<br/>全能的主神！<br/>天、地、沧海之间，<br/>造物无不颂赞：<br/>圣哉、圣哉、圣哉，<br/>全能而又慈怜！<br/>一神别三位，<br/>三位是一身！<br/>','',53605,7139);
INSERT INTO stanza VALUES('Z5','1','赞美父乃祝福之源，<br/>赞美子将救赎成全，<br/>赞美灵来实施、运行，<br/>赞美圣父、圣子、圣灵！<br/>','',53606,7140);
INSERT INTO stanza VALUES('Z5','2','赞美父是永活源头，<br/>赞美子作生命涌流，<br/>赞美灵已流入我心，<br/>赞美三一神是我分。<br/>','',53607,7141);
INSERT INTO stanza VALUES('Z6','1','神，你是爱，你也是光，<br/>且在子里作生命；<br/>爱已显明，光已照亮，<br/>我们因此而得生。<br/>','',53608,7142);
INSERT INTO stanza VALUES('Z6','chorus','你是爱！你是光！<br/>且在子里作生命；<br/>爱已显明，光已照亮，<br/>我们因此而得生。<br/>','',53609,7143);
INSERT INTO stanza VALUES('Z6','2','爱重所是，光重所为，<br/>爱是借光而释放；<br/>光显于外，爱在于内，<br/>光是带爱而照亮。<br/>','',53610,7144);
INSERT INTO stanza VALUES('Z6','3','爱的显明就是恩典，<br/>光的照亮是真理；<br/>爱叫我们享你肥甘，<br/>光叫我们认识你。<br/>','',53611,7145);
INSERT INTO stanza VALUES('Z6','4','爱叫你在子里来死，<br/>使我借祂得生命；<br/>光叫我能有所认识，<br/>使我借血得洁净。<br/>','',53612,7146);
INSERT INTO stanza VALUES('Z6','5','爱叫我们得着生命，<br/>有分于你的交通；<br/>光叫我们得着洁净，<br/>能以活在交通中。<br/>','',53613,7147);
INSERT INTO stanza VALUES('Z6','6','光的照亮、血的洗净，<br/>带来膏油的涂抹，<br/>你的成分、爱的生命，<br/>在我里面就加多。<br/>','',53614,7148);
INSERT INTO stanza VALUES('Z6','7','爱叫我们成为儿女，<br/>时常称你作阿爸；<br/>光叫我们不洁全去，<br/>直到见主得像祂。<br/>','',53615,7149);
INSERT INTO stanza VALUES('Z6','chorus','何荣耀！何福气！<br/>爱已显明，光已亮！<br/>感谢不尽，赞美不已！<br/>父，你是爱又是光！<br/>','',53616,7150);
INSERT INTO stanza VALUES('Z7','1','哦神，你是永远父，<br/>也是自有永有主！<br/>你比古者还要古，<br/>你比初者还要初！<br/>','',53617,7151);
INSERT INTO stanza VALUES('Z7','2','你是永远到永远，<br/>超过时间和空间！<br/>永永远远的完满，<br/>无始无终的无限！<br/>','',53618,7152);
INSERT INTO stanza VALUES('Z7','3','你是万有的根源，<br/>早过大地并诸天！<br/>你比先者还要先，<br/>你比前者还要前！<br/>','',53619,7153);
INSERT INTO stanza VALUES('Z7','4','你是生命永存留，<br/>世世代代无尽休！<br/>你比久者还要久，<br/>你比后者还要后！<br/>','',53620,7154);
INSERT INTO stanza VALUES('Z7','5','首先，你是阿拉法，<br/>末后，你是俄梅嘎！<br/>自始至终无所差，<br/>完全丰满无可加！<br/>','',53621,7155);
INSERT INTO stanza VALUES('Z7','6','我们赞美你永远，<br/>我们称颂你无限！<br/>赞美你是何丰满，<br/>称颂你是何完全！<br/>','',53622,7156);
INSERT INTO stanza VALUES('Z8','1','父阿，你是万灵之灵，<br/>神圣远超万众；<br/>我们敬拜以灵、在灵，<br/>同灵向你称颂。<br/>','',53623,7157);
INSERT INTO stanza VALUES('Z8','2','为要我们以灵拜灵，<br/>你为我们造灵；<br/>且将我们灵里重生，<br/>为叫灵灵响应。<br/>','',53624,7158);
INSERT INTO stanza VALUES('Z8','3','父来作子，子又作灵，<br/>为要进入我灵；<br/>父、子、圣灵来作生命，<br/>这是何等恩情。<br/>','',53625,7159);
INSERT INTO stanza VALUES('Z8','4','你在子里，子是你话，<br/>这话也就是灵；<br/>灵进我灵，将我感化，<br/>也就作我生命。<br/>','',53626,7160);
INSERT INTO stanza VALUES('Z8','5','你灵现今住在我灵，<br/>你我联成一灵；<br/>你灵我灵同作见证，<br/>我是由你而生。<br/>','',53627,7161);
INSERT INTO stanza VALUES('Z8','6','你灵凡事将我引领，<br/>使我随灵而行，<br/>使我得享平安、生命，<br/>使我全人属灵。<br/>','',53628,7162);
INSERT INTO stanza VALUES('Z8','7','灵里祷告、灵里敬拜、<br/>灵里将你瞻仰，<br/>直到灵能完全出来，<br/>满有荣耀形状。<br/>','',53629,7163);
INSERT INTO stanza VALUES('Z8','8','父阿，我们赞美你灵，<br/>赞美你就是灵！<br/>我们敬拜以灵、在灵，<br/>同灵称颂你名！<br/>','',53630,7164);
INSERT INTO stanza VALUES('Z9','1','哦神，你是生命源头，<br/>神圣、甘美、丰满！<br/>你如活水向外涌流，<br/>一直流到永远！<br/>','',53631,7165);
INSERT INTO stanza VALUES('Z9','2','你在子里因爱流出，<br/>流到人类中间；<br/>且成那灵带爱流入，<br/>流进我们里面。<br/>','',53632,7166);
INSERT INTO stanza VALUES('Z9','3','我们虽都偏行己路，<br/>满了邪恶罪愆，<br/>你在子里仍来救赎，<br/>赐以生命恩典。<br/>','',53633,7167);
INSERT INTO stanza VALUES('Z9','4','我们甚且将你欺侮，<br/>时常抗拒圣灵，<br/>但你这灵仍然眷顾，<br/>来作我们生命。<br/>','',53634,7168);
INSERT INTO stanza VALUES('Z9','5','你在子里、借成那灵，<br/>已与我们调和；<br/>你的成分借祂运行，<br/>还要涂抹加多。<br/>','',53635,7169);
INSERT INTO stanza VALUES('Z9','6','你的慈爱、子的恩典、<br/>加上灵的交通，<br/>使我得享神的丰满，<br/>直到永世无终！<br/>','',53636,7170);
INSERT INTO stanza VALUES('Z9','7','三一之神，<br/>父、子、圣灵，<br/>如此厚待我们，<br/>配得我们和声响应，<br/>赞美你爱不尽！<br/>','',53637,7171);
INSERT INTO stanza VALUES('Z10','1','哦神，你是何超越，<br/>你是何等圣别！<br/>无何能与你并列，<br/>你的一切超绝！<br/>你是宇宙的至圣，<br/>你是圣中之圣！<br/>你的永能和神性，<br/>远超万有、众生！<br/>','',53638,7172);
INSERT INTO stanza VALUES('Z10','2','你是圣而有分别，<br/>非仅无罪圣洁；<br/>非仅丝毫无残缺，<br/>且与完全有别。<br/>无何能与你比拟，<br/>无何能与你攀；<br/>无论以何代替你，<br/>都是对你亵慢！<br/>','',53639,7173);
INSERT INTO stanza VALUES('Z10','3','你在优者之外优，<br/>你与优者有别；<br/>你在秀者之外秀，<br/>秀者与你难列。<br/>你与善者也有别，<br/>你善乃是超绝；<br/>美者与你也难列，<br/>你美也是超越。<br/>','',53640,7174);
INSERT INTO stanza VALUES('Z10','4','圣别乃是你特性，<br/>你已赐给我们；<br/>你那分别的性情，<br/>我们已经有分。<br/>我们与你同超越，<br/>因已与你同性；<br/>我们追随你圣别，<br/>就得分别为圣。<br/>','',53641,7175);
INSERT INTO stanza VALUES('Z10','5','我们赞美你超越，<br/>赞美你的圣别！<br/>无何能与你并列，<br/>你的一切超绝！<br/>我们赞美你特性，<br/>已经赐给我们；<br/>你那分别的性情，<br/>我们已经有分。<br/>','',53642,7176);
INSERT INTO stanza VALUES('Z11','1','父神，你如青翠松树，<br/>永远常新不衰！<br/>你是永活长存的主，<br/>直到永远不败！<br/>','',53643,7177);
INSERT INTO stanza VALUES('Z11','chorus','哦父，你是常新的神，<br/>永远不知陈旧！<br/>千万亿载仍是鲜新！<br/>尽管年日悠久。<br/>','',53644,7178);
INSERT INTO stanza VALUES('Z11','2','父，你是神<br/>也就是『新，』<br/>无你就是陈旧；<br/>有你，虽然代远年湮，<br/>仍是常新不朽。<br/>','',53645,7179);
INSERT INTO stanza VALUES('Z11','3','你向我们所赐之福，<br/>都是新而不旧；<br/>约是新约、路是新路，<br/>都要永远存留。<br/>','',53646,7180);
INSERT INTO stanza VALUES('Z11','4','我们乃是你的新造，<br/>新人、新心、新灵；<br/>日日更新，永不衰老，<br/>满有新样、新生。<br/>','',53647,7181);
INSERT INTO stanza VALUES('Z11','5','最终新天、新地、新城，<br/>一切全都更新；<br/>月月都有新果供应，<br/>永远不再变陈。<br/>','',53648,7182);
INSERT INTO stanza VALUES('Z11','6','父神，你是常新不旧，<br/>我们赞美不休！<br/>永远赞美、永远歌讴：<br/>你是常新不旧！<br/>','',53649,7183);
INSERT INTO stanza VALUES('Z12','1','当我观赏，<br/>父，你广大的创造，<br/>天空、地面、<br/>万有无数无边，<br/>形形色色，<br/>壮丽、奇观又微妙，<br/>大大小小说出你的无限；<br/>','',53650,7184);
INSERT INTO stanza VALUES('Z12','chorus','我心、我灵<br/>立即兴起赞美：<br/>你何希奇！你何伟大！<br/>赞美之声永世还要宏伟；<br/>你何希奇！你何伟大！<br/>','',53651,7185);
INSERT INTO stanza VALUES('Z12','2','当我尝到<br/>奇妙救恩的深高，<br/>想到你曾如何差遣爱子，<br/>为我来死，<br/>使我成为你新造，<br/>将你生命显得完全尽致；<br/>','',53652,7186);
INSERT INTO stanza VALUES('Z12','3','当在会中，<br/>享受有福的交通，<br/>得见众圣如何有你生命，<br/>同被建造，<br/>作你安居的灵宫，<br/>你的丰满因此就得显明；<br/>','',53653,7187);
INSERT INTO stanza VALUES('Z12','4','到我所望<br/>日期满足的时候，<br/>我得有分于新耶路撒冷，<br/>天地更新，<br/>旧造一无再存留，<br/>你的所是得到完全显明；<br/>','',53654,7188);
INSERT INTO stanza VALUES('Z13','1','父阿，<br/>在你并无转动的影儿，<br/>你的信实极其广大无边。<br/>你是昔在、今在、<br/>以后永在者；<br/>你的怜悯像你永远不变。<br/>','',53655,7189);
INSERT INTO stanza VALUES('Z13','chorus','你的信实广大！<br/>你的信实无边！<br/>你的怜悯每晨都是新鲜！<br/>我所需要<br/>一切全由你供给，<br/>你的信实极其广大无边！<br/>','',53656,7190);
INSERT INTO stanza VALUES('Z13','2','冬夏、寒暑、稼穑<br/>及时的供应，<br/>日、月、星辰<br/>昼夜所有循环，<br/>并大自然，<br/>多方全都在见证：<br/>你的信实<br/>极其广大、无边！<br/>','',53657,7191);
INSERT INTO stanza VALUES('Z13','3','你的赦免所带<br/>平安与喜乐，<br/>你的同在所赐<br/>安抚、引导，<br/>今日力量、明日<br/>光明的盼望，<br/>全都属我，<br/>福分一无缺少。<br/>','',53658,7192);
INSERT INTO stanza VALUES('Z14','1','父神，<br/>你是何等信实、<br/>何等可信、可靠；<br/>宇宙万有都在见证，<br/>将你信实宣告。<br/>','',53659,7193);
INSERT INTO stanza VALUES('Z14','chorus','你的信实何等坚定！<br/>为此我献敬拜；<br/>坚定在天，如日之恒，<br/>永远为我存在！<br/>','',53660,7194);
INSERT INTO stanza VALUES('Z14','2','在你并无转动影儿，<br/>并无任何改迁；<br/>昔在、今在、以后常在，<br/>直到永远不变。<br/>','',53661,7195);
INSERT INTO stanza VALUES('Z14','3','你话像你自己可靠，<br/>永远不能废去；<br/>天地虽然都要灭没，<br/>你话永存不渝。<br/>','',53662,7196);
INSERT INTO stanza VALUES('Z14','4','你的恩赐和你选召，<br/>永远没有后悔；<br/>你的恩惠和你怜悯，<br/>又如你名不颓。<br/>','',53663,7197);
INSERT INTO stanza VALUES('Z14','5','你话加上你的信实，<br/>对我乃是保证；<br/>借此对你可靠救恩，<br/>我是万分确定。<br/>','',53664,7198);
INSERT INTO stanza VALUES('Z14','6','纵然因罪我能失信，<br/>你仍可信不变；<br/>你绝不能背乎自己，<br/>你话必定成全。<br/>','',53665,7199);
INSERT INTO stanza VALUES('Z14','7','你因信实必定成就<br/>你所应许恩言；<br/>我今以你信实为粮，<br/>借享你的甘甜。<br/>','',53666,7200);
INSERT INTO stanza VALUES('Z14','7','彩虹围绕你的宝座，<br/>宣告你的信实；<br/>圣城根基犹似彩虹，<br/>见证直到永世。<br/>','',53667,7201);
INSERT INTO stanza VALUES('Z15','1','若无流血就有赦罪，<br/>如何对付公义？<br/>若已流血仍然责备，<br/>仍然不能合理。<br/>','',53668,7202);
INSERT INTO stanza VALUES('Z15','2','神，你今已不能追究，<br/>我主已经献祭；<br/>我已得着完全自由，<br/>我罪像东离西。<br/>','',53669,7203);
INSERT INTO stanza VALUES('Z15','3','你义所有每一要求，<br/>我主都付代价；<br/>现今你只能加宽宥，<br/>因无审判可加。<br/>','',53670,7204);
INSERT INTO stanza VALUES('Z15','4','前是爱叫祂来救赎，<br/>满足你义要求；<br/>满足你义，今叫我主<br/>释放所有罪囚。<br/>','',53671,7205);
INSERT INTO stanza VALUES('Z15','5','奇妙、奇妙，在十字架，<br/>我遇爱和公义；<br/>爱和公义如此交加，<br/>使我歌唱不已。<br/>','',53672,7206);
INSERT INTO stanza VALUES('Z16','1','我们赞美你的公义，<br/>你的正义我们称奇，<br/>永远见证不已。<br/>你是审判全地的主，<br/>在你不义谁能寻出？<br/>你是全然公义！<br/>','',53673,7207);
INSERT INTO stanza VALUES('Z16','2','公义是你宝座根基，<br/>和平借此得以建立，<br/>像你信实坚定！<br/>借着你这无比公义，<br/>基督恩典作王管理，<br/>使我得享和平。<br/>','',53674,7208);
INSERT INTO stanza VALUES('Z16','3','你的公义使你儿子<br/>去到十架为我受死，<br/>救赎借此成就；<br/>当这救赎人肯信倚，<br/>你的公义立刻称义，<br/>使人得蒙拯救。<br/>','',53675,7209);
INSERT INTO stanza VALUES('Z16','4','为着显明你的公义，<br/>你曾宽容前一时期<br/>众人所有过犯；<br/>并为显明你的公义，<br/>你也赦免这一时期<br/>罪人所有罪愆。<br/>','',53676,7210);
INSERT INTO stanza VALUES('Z16','5','一日你要审判万民，<br/>将你公义显得完尽，<br/>借着我主基督；<br/>我们要靠你义站立，<br/>无何能将我们摇移，<br/>恩典因义显着。<br/>','',53677,7211);
INSERT INTO stanza VALUES('Z16','6','将来国度充满公义，<br/>和平得在其上建立，<br/>万物和谐、同居；<br/>在那永世新天新地，<br/>更要充满你的公义，<br/>照着你所应许。<br/>','',53678,7212);
INSERT INTO stanza VALUES('Z17','1','当我有罪充满痛苦，<br/>公义要求我受审判；<br/>当主流血为我救赎，<br/>公义要求赐我平安。<br/>','',53679,7213);
INSERT INTO stanza VALUES('Z17','2','神，是你义将我救主<br/>带上十架忍受审判；<br/>也是你义将众罪徒<br/>赦免、称义并赐平安。<br/>','',53680,7214);
INSERT INTO stanza VALUES('Z17','3','公义要求账须清偿；<br/>当账已经清偿之后，<br/>公义又要已偿的账，<br/>不得再偿，不得再收。<br/>','',53681,7215);
INSERT INTO stanza VALUES('Z17','4','自从我主一次流血，<br/>你不能再要祂受钉，<br/>也不能再要我解决，<br/>只能将我赦免、洁净。<br/>','',53682,7216);
INSERT INTO stanza VALUES('Z17','5','从前我听你是公义，<br/>我便害怕、逃匿不迨；<br/>现今你义一被品题，<br/>我反感觉宝贝可爱。<br/>','',53683,7217);
INSERT INTO stanza VALUES('Z17','6','自从我识你的公义，<br/>我更明白你的恩惠；<br/>前者使我何等安息，<br/>后者使我充满安慰。<br/>','',53684,7218);
INSERT INTO stanza VALUES('Z18','1','父神，为着你的公义，<br/>我们俯伏敬拜你；<br/>你既因主称我为义，<br/>谁能将我良心抑？<br/>你既公义，你又信实，<br/>靠你公义我站立；<br/>在你永无半点不义，<br/>谁能转动你义臂？<br/>','',53685,7219);
INSERT INTO stanza VALUES('Z18','2','你将我罪已归耶稣，<br/>你的公义将祂诛；<br/>你的律法所有要求，<br/>祂照你义全满足。<br/>从祂你已得到赎价，<br/>因此我已得释放；<br/>你这极公至义的神，<br/>怎能向我再讨偿？<br/>','',53686,7220);
INSERT INTO stanza VALUES('Z18','3','公义父神，你已接受<br/>耶稣作我的代替；<br/>祂是义的受你审判，<br/>代替我这不义的。<br/>祂今坐在你的右边，<br/>作你公义的明证；<br/>祂已使你完全满足，<br/>你义使你难变更。<br/>','',53687,7221);
INSERT INTO stanza VALUES('Z18','4','借着基督赎罪宝血，<br/>我已得着你的义；<br/>在你这义遮护之下，<br/>无何能将我摇移。<br/>你且使我成为你义，<br/>何人能再定我罪？<br/>将来在那圣城撒冷，<br/>我这见证永不颓！<br/>','',53688,7222);
INSERT INTO stanza VALUES('Z19','1','圣父，我们向你下拜，<br/>献上同声的歌颂；<br/>你何圣别、你何超凡，<br/>配得永远的尊崇。<br/>','',53689,7223);
INSERT INTO stanza VALUES('Z19','2','亲爱父神，你心是爱，<br/>你的作为是公义，<br/>但你性情却是圣别，<br/>使我有分你自己。<br/>','',53690,7224);
INSERT INTO stanza VALUES('Z19','3','你已借着基督宝血，<br/>使我永远成圣洁；<br/>你也借着你的真理，<br/>使我全人被分别。<br/>','',53691,7225);
INSERT INTO stanza VALUES('Z19','4','你曾借着你的圣灵，<br/>将我圣别归于你；<br/>叫我完全得以成圣，<br/>全人，灵、魂与身体。<br/>','',53692,7226);
INSERT INTO stanza VALUES('Z19','5','借着你恩，我已得到<br/>基督圣洁的生命；<br/>因此使我得以有分<br/>你那圣别的性情。<br/>','',53693,7227);
INSERT INTO stanza VALUES('Z19','6','将来在那圣城之中，<br/>完全有分你圣别，<br/>永远要作极峰见证：<br/>你是如何的圣洁！<br/>','',53694,7228);
INSERT INTO stanza VALUES('Z20','1','父神，你曾凭你智慧，<br/>照你所爱心愿，<br/>为子制定永远计划：<br/>万有由祂充满。<br/>','',53695,7229);
INSERT INTO stanza VALUES('Z20','chorus','深哉、富哉，你的智慧，<br/>谁能测度、追寻？<br/>然而父神，因这智慧，<br/>我蒙恩惠、怜悯！<br/>','',53696,7230);
INSERT INTO stanza VALUES('Z20','2','你造万有，何其奇妙，<br/>你心谁能洞鉴？<br/>一切由你、靠你、归你，<br/>在此你智我见。<br/>','',53697,7231);
INSERT INTO stanza VALUES('Z20','3','你智让人全圈罪中，<br/>为显怜悯之大；<br/>使人无不心服、口服，<br/>除你别无可夸。<br/>','',53698,7232);
INSERT INTO stanza VALUES('Z20','4','你凭智慧、借十字架，<br/>救赎为我作成；<br/>好叫你的宝贝自己，<br/>得以置于我灵。<br/>','',53699,7233);
INSERT INTO stanza VALUES('Z20','5','空中执政，借你召会，<br/>得知你智丰富；<br/>借她，你的万般智慧，<br/>在天给彼领悟。<br/>','',53700,7234);
INSERT INTO stanza VALUES('Z20','6','将来在新耶路撒冷，<br/>怜悯是我所夸；<br/>你的智慧全得显明，<br/>显得永无复加。<br/>','',53701,7235);
INSERT INTO stanza VALUES('Z21','1','父，你智慧同你恩典，<br/>全在基督集中；<br/>你使祂作我们智慧，<br/>因祂我蒙恩宠。<br/>你使祂作我们智慧，<br/>因祂我蒙恩宠。<br/>','',53702,7236);
INSERT INTO stanza VALUES('Z21','2','你的计划全在于祂，<br/>祂是你恩之路；<br/>在祂-你这智慧-里面，<br/>我得享你丰富。<br/>','',53703,7237);
INSERT INTO stanza VALUES('Z21','3','因祂，我们得蒙称义，<br/>祂是我们公义；<br/>我们借祂也得成圣，<br/>我们圣洁是彼。<br/>','',53704,7238);
INSERT INTO stanza VALUES('Z21','4','照着你的永远计划，<br/>祂也是我救赎；<br/>最终将我身体救赎，<br/>使我全人成熟。<br/>','',53705,7239);
INSERT INTO stanza VALUES('Z21','5','在你神圣经营之中，<br/>祂是你的智慧；<br/>为祂，我们俯伏敬拜，<br/>向你献上赞美。<br/>','',53706,7240);
INSERT INTO stanza VALUES('Z21','6','在祂，我们已经看见<br/>你智丰富深广；<br/>但是还要加富、加深，<br/>全在我们身上。<br/>','',53707,7241);
INSERT INTO stanza VALUES('Z22','1','父，我赞美你的怜悯，<br/>如此高大并深阔；<br/>因着我的软弱、失败，<br/>你的怜悯时加多。<br/>我今敬拜、我今敬拜，<br/>你这怜悯抬举我！<br/>你这怜悯抬举我！<br/>','',53708,7242);
INSERT INTO stanza VALUES('Z22','2','对你怜悯我们惊奇，<br/>如此低就且不移，<br/>竟然临及我这罪人，<br/>且要维持永无已。<br/>何能使我、何能使我<br/>从这怜悯被遗弃？<br/>','',53709,7243);
INSERT INTO stanza VALUES('Z22','3','我们感激你的怜悯，<br/>如此丰富且充足！<br/>因这怜悯、借着救赎，<br/>你曾丰厚赐眷顾。<br/>舍此何能、舍此何能<br/>使我如此蒙爱护？<br/>','',53710,7244);
INSERT INTO stanza VALUES('Z22','4','哦，你怜悯富有感召，<br/>柔细、可爱又甘甜！<br/>借你忍耐和你恩慈，<br/>正合我需赐恩典。<br/>我们宝贵、我们宝贵<br/>你这怜悯的完全。<br/>','',53711,7245);
INSERT INTO stanza VALUES('Z22','5','我今享受你的怜悯，<br/>永远不旧、永远新；<br/>每日早晨临到我身，<br/>犹如甘露施滋润。<br/>何等甜美、何等甜美，<br/>满心赞美你怜悯。<br/>','',53712,7246);
INSERT INTO stanza VALUES('Z22','6','对你赞美何能止息，<br/>因你怜悯永持久；<br/>你的恩惠、你的眷顾，<br/>全都为我永保守。<br/>可靠怜悯、可靠怜悯，<br/>永不能叫我蒙羞。<br/>','',53713,7247);
INSERT INTO stanza VALUES('Z23','1','父，你怜悯<br/>已向我们显明，<br/>照你启示；<br/>罪人如我竟能有你生命，<br/>作你儿子。<br/>怜悯器皿乃是你所豫定，<br/>贵重器皿永为你作见证。<br/>','',53714,7248);
INSERT INTO stanza VALUES('Z23','2','『喜爱怜悯，<br/>并不喜爱祭祀，』<br/>你曾宣告；<br/>因这怜悯，<br/>我们受你恩赐，<br/>并得荣耀。<br/>不在定意或是奔跑的人，<br/>乃在你这愿发怜悯的神。<br/>','',53715,7249);
INSERT INTO stanza VALUES('Z23','3','父，你怜悯<br/>并你恩惠、慈爱，<br/>我已得尝；<br/>你这怜悯带来你的同在，<br/>并你面光。<br/>因你怜悯，<br/>我今向你下拜，<br/>赞你怜悯，<br/>歌颂直到万代。<br/>','',53716,7250);
INSERT INTO stanza VALUES('Z24','1','神的大爱真是远超<br/>笔所能描、口所能陈；<br/>牠比最高星宿还高，<br/>牠比最深地狱还深。<br/>始祖犯罪，惊恐自危，<br/>神赐爱子来救；<br/>当人痛悔，神就迎归，<br/>所有罪案全勾。<br/>','',53717,7251);
INSERT INTO stanza VALUES('Z24','chorus','哦，神的爱，何其丰富、<br/>何其无法测量！<br/>牠是坚强，存到永古，<br/>天使、圣徒同唱。<br/>','',53718,7252);
INSERT INTO stanza VALUES('Z24','2','岁月消逝，荣华衰败，<br/>天地废去，事物更变，<br/>人今拒绝神的大爱，<br/>那日惟有求助山岩；<br/>神的大爱不会稍改，<br/>何其无法测量；<br/>大施恩贷，对人罪债，<br/>圣徒、天使同唱。<br/>','',53719,7253);
INSERT INTO stanza VALUES('Z24','3','纵令洋海尽是墨汁，<br/>无边穹苍都成白纸，<br/>田间草杆根根笔枝，<br/>世上众人个个文士；<br/>若写神的大爱无极，<br/>一切犹感缺欠；<br/>墨干、笔弃、纸罄、人敝，<br/>未能写出半点。<br/>','',53720,7254);
INSERT INTO stanza VALUES('Z25','1','父阿，你赐何等慈爱，<br/>我们衷心感铭；<br/>因此我们前来敬拜，<br/>称颂你的圣名。<br/>','',53721,7256);
INSERT INTO stanza VALUES('Z25','2','你已敞开你的胸怀，<br/>将你心意显明；<br/>且在子里已经出来，<br/>将这心意完成。<br/>','',53722,7257);
INSERT INTO stanza VALUES('Z25','3','为爱我们你舍爱子，<br/>叫祂来此受死，<br/>好叫我们成为众子，<br/>与祂同作后嗣。<br/>','',53723,7258);
INSERT INTO stanza VALUES('Z25','4','我们因祂有你生命，<br/>永远得你为父，<br/>有分于你神圣性情，<br/>得享你的丰富。<br/>','',53724,7259);
INSERT INTO stanza VALUES('Z25','5','你差子灵进入我灵，<br/>使我称呼阿爸；<br/>灵里重生、灵里印证、<br/>灵里使我变化。<br/>','',53725,7260);
INSERT INTO stanza VALUES('Z25','6','带领众子进入荣耀，<br/>乃是你的目标；<br/>与你儿子毕像毕肖，<br/>必使我们达到。<br/>','',53726,7261);
INSERT INTO stanza VALUES('Z25','7','在这变化过程之中，<br/>凡事有你引领；<br/>力上加力、荣上加荣，<br/>直到变化完成。<br/>','',53727,7262);
INSERT INTO stanza VALUES('Z25','7','父阿，你赐何等慈爱，<br/>我们永远感铭！<br/>永远俯伏、永远敬拜、<br/>永远称颂你名！<br/>','',53728,7263);
INSERT INTO stanza VALUES('Z26','1','你爱所给虽然甚多，<br/>恩赐众善者哪！<br/>但在天上，还未见过<br/>甚么比血更大。<br/>','',53729,7264);
INSERT INTO stanza VALUES('Z26','2','就是我的信心对血，<br/>也是你爱所给；<br/>不然，恩赐虽合所缺，<br/>也是虚空无益。<br/>','',53730,7265);
INSERT INTO stanza VALUES('Z26','3','哦，神的爱，你是深海，<br/>我罪都埋里面；<br/>我的不义，你都遮盖，<br/>亏欠，你都赦免。<br/>','',53731,7266);
INSERT INTO stanza VALUES('Z26','4','在宝血里，我已寻出<br/>你爱心的踪迹；<br/>由此我知你的宽恕，<br/>并知你的公义。<br/>','',53732,7267);
INSERT INTO stanza VALUES('Z26','5','心会软弱，身会衰颓，<br/>我总安然相信；<br/>天地虽然都要销毁，<br/>我锚已经抛稳。<br/>','',53733,7268);
INSERT INTO stanza VALUES('Z26','6','到了那时，我要证明<br/>你爱有何价值；<br/>但在今日我的生命<br/>就先靠牠扶持。<br/>','',53734,7269);
INSERT INTO stanza VALUES('Z26','7','当赞美你！再赞美你！<br/>有何不是你给：<br/>宝贵救主，和那使彼<br/>显为宝贵的力。<br/>','',53735,7270);
INSERT INTO stanza VALUES('Z27','1','神阿，你为何故<br/>赐下耶稣基督，<br/>你的亲爱儿子，<br/>来为罪人受死？<br/>无他，乃是你的大爱，<br/>叫你这样舍去心爱。<br/>','',53736,7271);
INSERT INTO stanza VALUES('Z27','2','神，你儿子为何<br/>离开天上宝座，<br/>受苦直到命绝，<br/>流出祂的宝血？<br/>无他，乃是祂的大爱，<br/>叫祂这样为我受害。<br/>','',53737,7272);
INSERT INTO stanza VALUES('Z27','3','甚么感动你心，<br/>叫你赐下圣灵，<br/>将天上的平安，<br/>充满我们心坎？<br/>无他，乃是你的大爱，<br/>叫你这样差遣祂来。<br/>','',53738,7273);
INSERT INTO stanza VALUES('Z27','4','神阿，你恩这大！<br/>我爱实在太差！<br/>我心应当涌出<br/>感谢、赞美、欢呼，<br/>求主使我因你大爱，<br/>向你歌颂直到万代。<br/>','',53739,7274);
INSERT INTO stanza VALUES('Z28','1','神哪，你在圣所之内，<br/>接受我们敬拜赞美，<br/>因你的爱何其真。<br/>我们死在罪恶之中，<br/>好像囚犯早已途穷，<br/>你就来释放我们。<br/>你那无限丰富的爱，<br/>感动你以怜悯为怀，<br/>你就来拯救我们。<br/>','',53740,7275);
INSERT INTO stanza VALUES('Z28','2','你并不愿罪人沉沦，<br/>你愿他们回转求恳<br/>你作他们的救主。<br/>你在子里拣选我们<br/>脱离罪和死亡围困，<br/>又使我们蒙永福。<br/>我们今可来喊『阿爸，』<br/>乃因你子，不再惧怕，<br/>坦然亲近我们父。<br/>','',53741,7276);
INSERT INTO stanza VALUES('Z28','3','不久祂接属祂的人，<br/>围你宝座，带着他们<br/>前来敬拜并赞美。<br/>那时歌唱甜美声浪，<br/>要达天地最远边疆，<br/>发自蒙赎的大会。<br/>但是今日我们渴慕，<br/>父阿，向你敬拜俯伏，<br/>同心歌唱你恩惠。<br/>','',53742,7277);
INSERT INTO stanza VALUES('Z29','1','我们从前所有，<br/>不过就是死亡、罪恶；<br/>我们现今所有福分，<br/>都是来自我神。<br/>','',53743,7278);
INSERT INTO stanza VALUES('Z29','2','我在罪中，你爱来寻，<br/>感动我心相信；<br/>叫我因信得着安乐，<br/>因你基督得活。<br/>','',53744,7279);
INSERT INTO stanza VALUES('Z29','3','我为圣徒，现在所享，<br/>和我将来盼望，<br/>无一是我自己配得，<br/>都是因你恩泽。<br/>','',53745,7280);
INSERT INTO stanza VALUES('Z29','4','神，你这样丰富的爱，<br/>谁能报答得来？<br/>你爱真是远超人意，<br/>神圣！不可思议！<br/>','',53746,7281);
INSERT INTO stanza VALUES('Z29','5','哦父，但愿你今使我<br/>时刻明白更多：<br/>像你这样慈爱的神，<br/>当得我命、我心！<br/>','',53747,7282);
INSERT INTO stanza VALUES('Z29','6','我心若说要报你爱，<br/>聊以表明感戴，<br/>我就还是不知你爱<br/>深阔远超洋海！<br/>','',53748,7283);
INSERT INTO stanza VALUES('Z29','7','但愿我们对你大爱，<br/>不致当作买卖；<br/>你向我们所有爱心，<br/>我们怎能报尽！<br/>','',53749,7284);
INSERT INTO stanza VALUES('Z29','8','因此我们不再说报，<br/>-你爱实是太高-<br/>我们惟有满心感戴，<br/>向你永远敬拜。<br/>','',53750,7285);
INSERT INTO stanza VALUES('Z29','9','慈爱父神，我们欠你，<br/>一切都欠了你，<br/>我们只好一面感激，<br/>一面因子安息。<br/>','',53751,7286);
INSERT INTO stanza VALUES('Z30','1','父阿，我们向你下拜，<br/>满心希奇你的大爱！<br/>人算甚么，你竟眷念？<br/>轻微如我你也拣选！<br/>','',53752,7287);
INSERT INTO stanza VALUES('Z30','2','我们赞美你的心意，<br/>原是计划要人像你，<br/>有你生命，给你充满，<br/>有你形像，将你彰显。<br/>','',53753,7288);
INSERT INTO stanza VALUES('Z30','3','你来造人照你形像，<br/>并将权柄交人执掌，<br/>且作生命给人接受，<br/>要人享受你的所有。<br/>','',53754,7289);
INSERT INTO stanza VALUES('Z30','4','你要进入人的里面，<br/>与人调和，将人成全，<br/>使人变质，同被建造，<br/>作你居所，显你荣耀。<br/>','',53755,7290);
INSERT INTO stanza VALUES('Z30','5','人虽堕落，你未放弃，<br/>仍要在人成全你意；<br/>借着救赎将人带回，<br/>显出万般爱心、智慧。<br/>','',53756,7291);
INSERT INTO stanza VALUES('Z30','6','你在子里已经显出，<br/>死而复活成功救赎；<br/>借成那灵也已进入，<br/>在我里面施恩、眷顾。<br/>','',53757,7292);
INSERT INTO stanza VALUES('Z30','7','你以我灵为至圣所，<br/>其中设你施恩宝座；<br/>要我灵里与你相交，<br/>如同祭司烧香、祷告。<br/>','',53758,7293);
INSERT INTO stanza VALUES('Z30','8','在此恩惠如同江河，<br/>流自你的施恩宝座，<br/>将我流过、将我变化、<br/>将我建造成为你家。<br/>','',53759,7294);
INSERT INTO stanza VALUES('Z30','9','我们如此受宠、受惠，<br/>万分希奇你的圣垂；<br/>心中感激你的大爱，<br/>灵里向你献上敬拜。<br/>','',53760,7295);
INSERT INTO stanza VALUES('Z31','1','父阿，久在创世之前，<br/>你选我们，爱无限！<br/>这爱甘美、激励、深厚，<br/>吸引我们亲耶稣。<br/>还要保守，还要保守，<br/>我们今后永稳固。<br/>我们今后永稳固。<br/>','',53761,7296);
INSERT INTO stanza VALUES('Z31','2','虽然宇宙逐渐改迁，<br/>但是我神总不变；<br/>祂的爱心，同祂话语，<br/>向着我们永坚定；<br/>神的儿女，神的儿女，<br/>我们应当赞祂名。<br/>我们应当赞祂名。<br/>','',53762,7297);
INSERT INTO stanza VALUES('Z31','3','神的怜悯是我诗歌，<br/>我口所夸心所乐；<br/>从始至终，惟有白恩，<br/>能得我命感我心。<br/>神爱我们！神爱我们！<br/>连祂爱子都不吝！<br/>连祂爱子都不吝！<br/>','',53763,7298);
INSERT INTO stanza VALUES('Z31','4','爱的神阿，我们现在<br/>同心歌颂你奇爱，<br/>直到天上，远离尘嚣，<br/>我们仍是要称扬；<br/>但愿荣耀，但愿荣耀，<br/>永远归神和羔羊。<br/>永远归神和羔羊。<br/>','',53764,7299);
INSERT INTO stanza VALUES('Z32','1','荣耀父神，赞美你，<br/>我是你恩对象；<br/>今为使你心欢喜，<br/>前来向你颂扬：<br/>永世标出的众子，<br/>豫定都进荣光，<br/>同着基督你爱子，<br/>作你至高对象。<br/>','',53765,7300);
INSERT INTO stanza VALUES('Z32','2','创世之前你拣选，<br/>要我成为圣洁；<br/>豫定我们蒙恩典，<br/>作你荣耀基业。<br/>为着儿子的名分，<br/>你早将我标出；<br/>等到长大得成人，<br/>必得豫定之福。<br/>','',53766,7301);
INSERT INTO stanza VALUES('Z32','3','照着永世的豫定，<br/>赐我以你恩召；<br/>叫我得着你生命，<br/>将我罪过去掉。<br/>圣灵作质、作印记，<br/>并作一切供应，<br/>我得永远属于你，<br/>享受你的丰盛。<br/>','',53767,7302);
INSERT INTO stanza VALUES('Z32','4','哦！父，除你有谁能<br/>如此祝福我们：<br/>使我有分你的灵，<br/>蒙你生命之恩？<br/>不久我们要永远<br/>与祂同得荣耀；<br/>永远与祂活你前，<br/>将你荣形返照！<br/>','',53768,7303);
INSERT INTO stanza VALUES('Z33','1','父神阿，你在羔羊里<br/>是我的希望和安息，<br/>你名所表一切慈仁，<br/>都是为着赐福我们。<br/>','',53769,7304);
INSERT INTO stanza VALUES('Z33','2','你大而智、你公而仁，<br/>你是我父、又是我神；<br/>我们属你，是借宝血，<br/>作你儿女，永远联结。<br/>','',53770,7305);
INSERT INTO stanza VALUES('Z33','3','我们今带疲倦的灵，<br/>来到你前仰望你名；<br/>烦闷艰苦，寻求恩惠，<br/>如同困鹿渴慕溪水。<br/>','',53771,7306);
INSERT INTO stanza VALUES('Z33','4','既是这样，愿你施恩，<br/>好叫我们亲近你身；<br/>你的同在作我居所，<br/>你的大爱作我喜乐。<br/>','',53772,7307);
INSERT INTO stanza VALUES('Z33','5','这叫我们永远欢腾，<br/>这叫黑夜变为光明；<br/>若有微息尚能称颂，<br/>必引弱声向你歌诵。<br/>','',53773,7308);
INSERT INTO stanza VALUES('Z34','1','荣耀归于父神，<br/>祂已作大事；<br/>祂爱世人，<br/>甚至差遣祂儿子，<br/>来为我们舍命，<br/>成功了救赎，<br/>打开生命恩门，<br/>人人可进入。<br/>','',53774,7309);
INSERT INTO stanza VALUES('Z34','chorus','赞美神！赞美神！<br/>全地都当称祝！<br/>赞美神！赞美神！<br/>众人都要欢呼！<br/>哦，来就近父神，<br/>借着祂儿子，<br/>并将荣耀归祂，<br/>祂已作大事！<br/>','',53775,7310);
INSERT INTO stanza VALUES('Z34','2','何等完全救赎，<br/>宝血将我买；<br/>这是神的应许，<br/>信者可倚赖；<br/>就是极大罪人，<br/>若真肯相信，<br/>在他相信之时，<br/>必得赦罪恩。<br/>','',53776,7311);
INSERT INTO stanza VALUES('Z34','3','神已晓谕大事，<br/>神已作大事，<br/>我们也要大乐，<br/>借着祂儿子；<br/>但当看见主时，<br/>我们的惊喜必要更纯、<br/>更高、更大得无比。<br/>','',53777,7312);
INSERT INTO stanza VALUES('Z35','1','神，我赞美你，<br/>差遣你的爱子，<br/>钉死，复活，又升天，<br/>作我大祭司。<br/>','',53778,7313);
INSERT INTO stanza VALUES('Z35','chorus','阿利路亚，荣耀归你；<br/>阿利路亚，阿们！<br/>阿利路亚，荣耀归你，<br/>感谢你大恩。<br/>','',53779,7314);
INSERT INTO stanza VALUES('Z35','2','神，我赞美你，<br/>赐下亮光之灵，<br/>启示我的救赎主，<br/>开明我眼睛。<br/>','',53780,7315);
INSERT INTO stanza VALUES('Z35','3','荣耀和赞美，<br/>归给慈爱父神；<br/>借你爱子的救赎，<br/>得蒙你救恩。<br/>','',53781,7316);
INSERT INTO stanza VALUES('Z35','4','赞美再赞美，<br/>感激你的大爱，<br/>心被你爱再焚烧，<br/>向你献敬拜。<br/>','',53782,7317);
INSERT INTO stanza VALUES('Z36','1','我们不会疲倦<br/>不唱这首旧诗章，<br/>荣耀归神，阿利路亚！<br/>我们声浪依旧，<br/>灵里比前更坚强；<br/>荣耀归神，阿利路亚！<br/>','',53783,7318);
INSERT INTO stanza VALUES('Z36','chorus','神的儿女有权利，<br/>可以大喊并大唱，<br/>因为前途更光明，<br/>我们魂乐似飞翔，<br/>不久我们进荣耀，<br/>就要朝见我君王，<br/>荣耀归神，阿利路亚！<br/>','',53784,7319);
INSERT INTO stanza VALUES('Z36','2','我们浸沉在那<br/>救赎大爱，极乐中；<br/>荣耀归神，阿利路亚！<br/>我们心中乐极<br/>有如插翅上高空；<br/>荣耀归神，阿利路亚！<br/>','',53785,7320);
INSERT INTO stanza VALUES('Z36','3','我们要去之城<br/>乃是父神所建造；<br/>荣耀归神，阿利路亚！<br/>那里，我可面见<br/>我王所有的光耀；<br/>荣耀归神，阿利路亚！<br/>','',53786,7321);
INSERT INTO stanza VALUES('Z36','4','那里，我们要借新诗<br/>喊出救赎恩；<br/>荣耀归神，阿利路亚！<br/>那里，我们要同<br/>众圣拥挤耶稣身；<br/>荣耀归神，阿利路亚！<br/>','',53787,7322);
INSERT INTO stanza VALUES('Z37','1','阿爸，父阿，我们现在<br/>因主到你面前来；<br/>你的儿女到此聚集，<br/>愿得应许的福气。<br/>祂的宝血已洗我们，<br/>我们借祂来得恩；<br/>你灵也已指教我们<br/>呼喊阿爸，近你身。<br/>','',53788,7323);
INSERT INTO stanza VALUES('Z37','2','我们从前好像浪子，<br/>离你流荡真无知；<br/>但你的恩比罪更多，<br/>拯救我们脱灾祸。<br/>给我们穿救恩衣裳，<br/>给我们坐你席上；<br/>我们快乐，你也快乐，<br/>因你恩典真溥博！<br/>','',53789,7324);
INSERT INTO stanza VALUES('Z37','3','你用为父的爱亲嘴，<br/>表明你赦浪子罪；<br/>你宰肥犊，你使我们<br/>永远与你不再分。<br/>『我们理当欢喜快乐，』<br/>我们听你如此说：<br/>『因我儿子死而复活，<br/>曾经失去又得着。』<br/>','',53790,7325);
INSERT INTO stanza VALUES('Z37','4','阿爸，父阿，我称颂你，<br/>因你慈爱真希奇！<br/>天上天军因着我们，<br/>也要希奇你大恩。<br/>不久我们都要聚集，<br/>在你座前来温习：<br/>阿爸的爱何等丰富！<br/>阿爸的名何宽恕！<br/>','',53791,7326);
INSERT INTO stanza VALUES('Z38','1','阿爸，我们来颂赞你！<br/>我们谦卑敬拜你！<br/>我们现今得认识你，<br/>真是我们的福气。<br/>我们得着这样权柄，<br/>是因耶稣的尊名；<br/>你灵也和我们的灵，<br/>证明我们有生命。<br/>','',53792,7327);
INSERT INTO stanza VALUES('Z38','2','世界还未起首时候，<br/>你就在基督里头，<br/>豫定我们作你儿子，<br/>得你生命的恩赐。<br/>哦父，你是何等慈爱，<br/>竟使我们蒙恩待！<br/>叫我们这凡俗罪人，<br/>得与你性情有分！<br/>','',53793,7328);
INSERT INTO stanza VALUES('Z38','3','我们天性在亚当里，<br/>真是败坏无可比；<br/>但是你的永远旨意，<br/>豫定我们归于你；<br/>靠着救主我们得赎，<br/>因重生称你为父；<br/>救主、天父、教会合一，<br/>哦，这恩典何希奇！<br/>','',53794,7329);
INSERT INTO stanza VALUES('Z38','4','因此，境遇虽然转迁，<br/>虽有患难和试炼，<br/>你的慈爱总是不变，<br/>要领我们直到天。<br/>不久，你所赎的儿女，<br/>要在宝座前相聚，<br/>述说他们得救故事，<br/>并向你赞美不置。<br/>','',53795,7330);
INSERT INTO stanza VALUES('Z39','1','阿爸父神，我们前来<br/>低头、屈膝、全心敬拜；<br/>你既不需牛羊之祭，<br/>我们灵中献上『实际。』<br/>','',53796,7331);
INSERT INTO stanza VALUES('Z39','2','阿爸，你是自有永有，<br/>亘古常在，存到永久；<br/>你的宝座安定在天，<br/>荣耀、圣洁、权能无限。<br/>','',53797,7332);
INSERT INTO stanza VALUES('Z39','3','无望、无救，世上罪黎，<br/>获罪于你，何敢祷祈？<br/>只看见你无私公义，<br/>未认识你慈爱心意。<br/>','',53798,7333);
INSERT INTO stanza VALUES('Z39','4','但你借着怀中独子，<br/>将你自己完全启示；<br/>罪人一日未经救赎，<br/>你在宝座无从满足。<br/>','',53799,7334);
INSERT INTO stanza VALUES('Z39','5','独生儿子可暂离弃，<br/>为要得着我们罪黎；<br/>十字架上任其受苦，<br/>为使我们亲你有路。<br/>','',53800,7335);
INSERT INTO stanza VALUES('Z39','6','我们因你爱子受死，<br/>归你名下作你众子；<br/>从前你是何等可怕，<br/>今日你是亲爱阿爸。<br/>','',53801,7336);
INSERT INTO stanza VALUES('Z39','7','阿爸父神，爱深、恩高，<br/>你的儿女无法图报；<br/>我们惟有永远感戴，<br/>向你赞美、向你敬拜。<br/>第一节的『实际』<br/>指基督。<br/>','',53802,7337);
INSERT INTO stanza VALUES('Z40','1','没有血、没有坛，<br/>祭祀已成过去；<br/>没有烟冒、没有火燃，<br/>牺牲再无必需；<br/>更美的血流自更贵的脉，<br/>洗净人的污秽，<br/>清偿人的罪债。<br/>','',53803,7338);
INSERT INTO stanza VALUES('Z40','2','神，我们感谢你，<br/>为你儿子的血，<br/>靠牠我们被称为义，<br/>靠牠我们得捷；<br/>大胜地狱、死亡、<br/>黑暗势力，<br/>毋需两次争战，<br/>不留一个仇敌。<br/>','',53804,7339);
INSERT INTO stanza VALUES('Z40','3','神，我们感谢你，<br/>因有天来恩典，<br/>漫过我们最阔不义，<br/>赦免最深罪愆。<br/>我们要赞美你所有的爱，<br/>像你荣耀、权柄、能力，<br/>存到万代。<br/>','',53805,7340);
INSERT INTO stanza VALUES('Z40','4','神，我们感谢你，<br/>因为盼望坚定，<br/>下沉的灵借以再起，<br/>直至晨曦显明；<br/>有福的盼望、<br/>何等的鼓舞、<br/>最疲倦的旷野、<br/>最艰难的道路。<br/>','',53806,7341);
INSERT INTO stanza VALUES('Z40','5','神，我们感谢你，<br/>为那荣耀之冠，<br/>并非只有一时美丽，<br/>转眼即已枯残，<br/>乃是像宝座不朽到永远，<br/>乐哉，能向宝座<br/>投下所有冠冕。<br/>','',53807,7342);
INSERT INTO stanza VALUES('Z41','1','哦，神，是你召我们<br/>来看你的儿子，<br/>祂是你心的奇珍，<br/>祂行完你意思；<br/>我们因你肯白舍，<br/>你的独一心爱，<br/>才知你心是真切，<br/>要救我们脱害。<br/>','',53808,7343);
INSERT INTO stanza VALUES('Z41','2','哦，圣父，怜悯的神，<br/>我们因子的名，<br/>才敢向你常求恩，<br/>才有永远生命。<br/>你耳所常爱听闻-，<br/>悠扬如音乐的，<br/>已叫我们的灵魂，<br/>脱尽所有猜疑。<br/>','',53809,7344);
INSERT INTO stanza VALUES('Z41','3','战兢罪人心常怕，<br/>你永不忘先前，<br/>但祂一次的受罚，<br/>使你不再记念。<br/>当无甚么可以使，<br/>我们得自由时，<br/>父，你爱子的受死，<br/>还了我们罪值。<br/>','',53810,7345);
INSERT INTO stanza VALUES('Z41','4','你对我们(信祂的)<br/>心中已无忿怒；<br/>我们现今也无忌，<br/>因知你已眷顾；<br/>回家儿女你亲嘴，<br/>并赐光明衣袍，<br/>你的慈爱已安慰，<br/>我们心中苦恼。<br/>','',53811,7346);
INSERT INTO stanza VALUES('Z41','5','哦，你怎么能喜欢，<br/>我们这样的人？<br/>我们岂非使你难，<br/>岂非见你就恨？<br/>哦，真希奇，最希奇！<br/>这是神圣奥秘！<br/>从前发声如雷的，<br/>说：『罪人，我属你！』<br/>','',53812,7347);
INSERT INTO stanza VALUES('Z42','1','父神，我今敬拜你，<br/>恭敬向你来顶礼，<br/>借着基督作我祭：<br/>父阿，我敬拜你。<br/>','',53813,7348);
INSERT INTO stanza VALUES('Z42','2','你爱浩大，何深阔，<br/>借着祂死临及我，<br/>恩、义，因此我全得：<br/>父阿，我敬拜你。<br/>','',53814,7349);
INSERT INTO stanza VALUES('Z42','3','原是罪人何污秽，<br/>今成神子何尊贵！<br/>何等丰厚的恩惠：<br/>父阿，我敬拜你。<br/>','',53815,7350);
INSERT INTO stanza VALUES('Z42','4','今在灵中敬拜你，<br/>并以基督为实际，<br/>对你，祂是馨香祭：<br/>父阿，我敬拜你。<br/>','',53816,7351);
INSERT INTO stanza VALUES('Z42','5','我愿向你再献上，<br/>深处感戴的颂扬，<br/>颂扬你爱永无疆：<br/>父阿，我敬拜你。<br/>','',53817,7352);
INSERT INTO stanza VALUES('Z43','1','父阿，你是爱大无极，<br/>我们要来赞美你；<br/>我们是受恩典教益，<br/>你前不能不欢喜。<br/>你从世前就已定意，<br/>豫备我们的地位；<br/>你在时来就显能力，<br/>就向我们施恩惠。<br/>','',53818,7353);
INSERT INTO stanza VALUES('Z43','2','你使祂从死里复活，<br/>你使祂成你首生，<br/>祂已完成祂的工作，<br/>我们已信祂得胜。<br/>我们现今已成众子，<br/>我们不能不快乐；<br/>面向长子所有布置，<br/>日夜时常有诗歌。<br/>','',53819,7354);
INSERT INTO stanza VALUES('Z43','3','祂的神是我们的神，<br/>祂父也是我们父，<br/>我们与祂无法割分，<br/>祂与我们同骨肉。<br/>祂领我们回去见你，<br/>今日会中同唱诗；<br/>像祂，我们与祂合一，<br/>因子，我们作众子。<br/>','',53820,7355);
INSERT INTO stanza VALUES('Z43','4','神圣的爱！神圣的恩！<br/>子和众子永联合；<br/>这个就是我们永分！<br/>这个就是父喜乐！<br/>我们现今等在这里，<br/>等你儿子从天临；<br/>求使我们所有心意，<br/>是到祂前鼓乐琴。<br/>','',53821,7356);
INSERT INTO stanza VALUES('Z44','1','父阿，儿女称颂你名，<br/>是受恩典的教训；<br/>我们欢乐，因你生命，<br/>已使我们归羊群。<br/>','',53822,7357);
INSERT INTO stanza VALUES('Z44','2','你所给的得救证实，<br/>远超我们的赞美；<br/>我们的心现在直指，<br/>你在天上的座位。<br/>','',53823,7358);
INSERT INTO stanza VALUES('Z44','3','因在那里，祂作我们，<br/>永远不变的寄托。<br/>你将生命分给罪人，<br/>祂为罪人谋解脱。<br/>','',53824,7359);
INSERT INTO stanza VALUES('Z44','4','永世虽久，不过就是：<br/>显明你恩的丰富，<br/>好叫那些因你儿子，<br/>为儿女者，来称祝。<br/>','',53825,7360);
INSERT INTO stanza VALUES('Z44','5','我们现虽未见早晨，<br/>却仍安心历世途，<br/>等候祂来提接我们，<br/>脱离死亡和坟墓。<br/>','',53826,7361);
INSERT INTO stanza VALUES('Z44','6','我们欢乐，因你自己，<br/>就是我们的『永分，』<br/>像你儿子！同祂一起！<br/>享受光明的早晨！<br/>','',53827,7362);
INSERT INTO stanza VALUES('Z44','7','哦，求圣父因祂慈名，<br/>保守我们在这里，<br/>无忧无虑，随祂而行，<br/>直到同乐在那地。<br/>','',53828,7363);
INSERT INTO stanza VALUES('Z45','1','父神，我们称颂你，<br/>你前我们欢喜；<br/>永远脱开了死亡，<br/>与你儿子一起。<br/>祂是一『人』活你前，<br/>在那清明光中，<br/>在你无限的爱里，<br/>永远蒙你恩宠。<br/>','',53829,7364);
INSERT INTO stanza VALUES('Z45','2','祂父就是我们父，<br/>祂神就是我神；<br/>祂是你爱的儿子，<br/>你心所喜所珍。<br/>祂带我们亲近你，<br/>有分于祂地位，<br/>享受你爱的恩宠，<br/>并你脸上光辉。<br/>','',53830,7365);
INSERT INTO stanza VALUES('Z45','3','你爱已将我拥抱，<br/>这爱永不消沉；<br/>这爱全都集中，<br/>在你的爱子一身。<br/>在祂里面，你众子<br/>-祂的许多弟兄-<br/>与祂同享你这爱，<br/>同受你的恩宠。<br/>','',53831,7366);
INSERT INTO stanza VALUES('Z46','1','慈爱父神，<br/>对于你的大爱，<br/>众子响应；<br/>我们今能自由坦然前来，<br/>是靠子名。<br/>何等希奇，<br/>我们都能像祂，<br/>作你喜悦，<br/>永远与祂无差。<br/>','',53832,7367);
INSERT INTO stanza VALUES('Z46','2','祂作喜悦，<br/>我们挂祂身上，<br/>借着你恩；<br/>祂是你爱所有独一对象，<br/>我竟有分。<br/>我们同祂享受你爱无限，<br/>祂的荣耀你前我们得见。<br/>','',53833,7368);
INSERT INTO stanza VALUES('Z46','3','正当众子你前<br/>口唱、心和，<br/>同声颂扬；<br/>祂在率领，<br/>心中何等喜乐，<br/>向你歌唱。<br/>父神，<br/>在那爱的经营之中，<br/>你是最高源头，<br/>配得称颂。<br/>','',53834,7369);
INSERT INTO stanza VALUES('Z47','1','阿爸，我们进前来，<br/>由你爱子领率，<br/>献上赞美和敬拜，<br/>并享父亲慈爱。<br/>你在宝座心欢乐，<br/>永世计划成功-<br/>死而复活、失又得，<br/>我们已成圣众。<br/>','',53835,7370);
INSERT INTO stanza VALUES('Z47','2','桌上陈设杯和饼，<br/>我们已同领过；<br/>这个表记是说明<br/>你的爱子工作。<br/>祂的身体被擘开，<br/>辟成新活道路，<br/>我们借此得前来，<br/>称你作阿爸父。<br/>','',53836,7371);
INSERT INTO stanza VALUES('Z47','3','祂的宝血已流出，<br/>涂抹我们罪愆；<br/>你的公义和忿怒，<br/>不再追我亏欠。<br/>祂血永在你面前，<br/>为我说出美言，<br/>撒但控告无效验，<br/>我们不再自谴。<br/>','',53837,7372);
INSERT INTO stanza VALUES('Z47','4','人比天使更微小，<br/>你前算得甚么？<br/>你竟眷顾如珍宝，<br/>寻他与你复和。<br/>天使堕落你不寻，<br/>惟人蒙你赦免！<br/>赞美，哦父，赞不尽<br/>你这逾格恩典。<br/>','',53838,7373);
INSERT INTO stanza VALUES('Z48','1','宴筵方过，<br/>我们尚感甜美，<br/>父，<br/>你爱子率领我们赞美；<br/>祂领诗歌，<br/>于你何亲、何甜，<br/>我们与祂一致，<br/>和声颂赞。<br/>','',53839,7374);
INSERT INTO stanza VALUES('Z48','2','哦父，<br/>你外我们不需别惠，<br/>有何比你恩爱更为宝贵！<br/>我们敬拜，因为我们尝到<br/>你那无穷生命丰美味道。<br/>','',53840,7375);
INSERT INTO stanza VALUES('Z48','3','在你爱中我爱对你增长，<br/>胜过所有人情、<br/>属地捆绑；<br/>你爱借着大能，带领我心<br/>享受你的同在与日俱深。<br/>','',53841,7376);
INSERT INTO stanza VALUES('Z48','4','父阿，<br/>我们跟随你的爱子，<br/>在此向你赞美颂扬不止；<br/>饱享你的圣爱，<br/>心满意足，<br/>众子尝到你名所有丰富。<br/>','',53842,7377);
INSERT INTO stanza VALUES('Z49','1','父阿，<br/>我们在你面前拜礼，<br/>尊敬郑重；<br/>现在我们这些儿女聚集，<br/>是要称颂：<br/>奇恩如何带领我们回家，<br/>与你儿子一同亲近阿爸！<br/>','',53843,7378);
INSERT INTO stanza VALUES('Z49','2','知爱的人都知这里的爱，<br/>何等的深；<br/>从祂身上你爱已经布开，<br/>我父我神！<br/>现今祂在你的面前带同<br/>所有称颂你爱的人称颂。<br/>','',53844,7379);
INSERT INTO stanza VALUES('Z49','3','祂领诗歌，<br/>你耳何等乐听祂的颂称；<br/>但你岂不也是一样爱聆<br/>我们和声；<br/>你心爱祂远在创世之前，<br/>你也定规我们作祂同伴。<br/>','',53845,7380);
INSERT INTO stanza VALUES('Z50','1','我父、我神，<br/>你爱在子显明，<br/>对此我们再来你前响应。<br/>祂作燔祭，<br/>满足你的心意；<br/>忍受十架，<br/>使我得你欢喜。<br/>','',53846,7381);
INSERT INTO stanza VALUES('Z50','2','祂今率领许多弟兄歌唱，<br/>我们和声，<br/>从心响应颂扬。<br/>当祂在此引声向你赞美，<br/>我们灵里共鸣，<br/>欢然跟随。<br/>','',53847,7382);
INSERT INTO stanza VALUES('Z50','3','在你爱子里面蒙了拣选，<br/>今得有分你前欢呼、<br/>颂赞；<br/>创世之前已经蒙你豫定，<br/>要我有分于你儿子生命。<br/>','',53848,7383);
INSERT INTO stanza VALUES('Z50','4','蒙爱众子，<br/>全由你灵更新，<br/>有你爱子作那无穷之分；<br/>每个都有祂的一分特点，<br/>供你喜悦欣赏，<br/>直到永远。<br/>','',53849,7384);
INSERT INTO stanza VALUES('Z51','1','亲爱父神，<br/>我们向你歌唱，<br/>有谁比你更配我们颂扬。<br/>你今要人<br/>以灵以『真』敬拜，<br/>我们照此向你献上感戴。<br/>','',53850,7385);
INSERT INTO stanza VALUES('Z51','2','所有世界是你借子造成，<br/>万有也都由祂大能托撑；<br/>但我却是在你爱子里面，<br/>与你亲近，<br/>敬拜何其甘甜。<br/>','',53851,7386);
INSERT INTO stanza VALUES('Z51','3','祂今在这蒙福范围领唱，<br/>在你召会唱诗向你颂扬；<br/>何等欢乐，<br/>祂有弟兄随同，<br/>与祂同享自由，<br/>向你歌颂。<br/>','',53852,7387);
INSERT INTO stanza VALUES('Z51','4','我们和祂在此同声歌唱，<br/>哦父，<br/>使你满足、供你欣赏；<br/>在你爱子所领赞美之中，<br/>你可安居，<br/>永远享受称颂。<br/>『真』指基督。<br/>','',53853,7388);
INSERT INTO stanza VALUES('Z52','1','靠着我们救主流血作祭，<br/>父阿，我们前来一同就你；<br/>距离已去，借恩已得自由，<br/>前来敬拜向你赞美、歌讴。<br/>','',53854,7389);
INSERT INTO stanza VALUES('Z52','2','哦父，我们愿在你前献上<br/>你的爱子之名所有馨香；<br/>借着祂死为我所得恩典，<br/>在此凭信我们将祂观瞻。<br/>','',53855,7390);
INSERT INTO stanza VALUES('Z52','3','你的喜乐我今与祂同享，<br/>在祂里面我心因你欢畅；<br/>万人之上，祂比美者更美，<br/>祂的荣耀永不衰落败褪。<br/>','',53856,7391);
INSERT INTO stanza VALUES('Z52','4','在你座前我们俯伏仰望，<br/>凭信看见你爱所有对象；<br/>祂今在此率领许多弟兄-<br/>你的众子，同声向你歌颂。<br/>','',53857,7392);
INSERT INTO stanza VALUES('Z53','1','哦主，你是神的活道，<br/>太初与神同在；<br/>你是神的荣耀发表，<br/>将神表明出来。<br/>','',53858,7393);
INSERT INTO stanza VALUES('Z53','chorus','赞美你是神的活道，<br/>将神完全发表！<br/>神的本性、神的荣耀，<br/>借你全都揭晓！<br/>','',53859,7394);
INSERT INTO stanza VALUES('Z53','2','诸天述说神的荣耀，<br/>万有也在发声；<br/>神能、神性，原难知晓，<br/>借你创造显明。<br/>','',53860,7395);
INSERT INTO stanza VALUES('Z53','3','神的话语丰富、奥妙，<br/>全是你的见证；<br/>你在其中得着发表，<br/>为要将神说明。<br/>','',53861,7396);
INSERT INTO stanza VALUES('Z53','4','你这活道成为肉身，<br/>住在人的中间；<br/>你的一切行事、为人，<br/>就是神的彰显。<br/>','',53862,7397);
INSERT INTO stanza VALUES('Z53','5','你这活道乃是生命，<br/>也是生命之光；<br/>你作生命发光照明，<br/>使神得着显彰。<br/>','',53863,7398);
INSERT INTO stanza VALUES('Z53','6','将来你要施行审判，<br/>表明神的公义；<br/>也是叫神得着彰显，<br/>将神表明无遗。<br/>','',53864,7399);
INSERT INTO stanza VALUES('Z53','7','哦主，你是神的显出，<br/>你是显出的神；<br/>你已将神向人宣布，<br/>使神不再自隐。<br/>','',53865,7400);
INSERT INTO stanza VALUES('Z54','1','哦主，你是永远之道，<br/>父的独生爱子，<br/>是神给人看见听到，<br/>天的可爱之子。<br/>哦，神儿子，你何神圣，<br/>在你我见神的丰盛。<br/>','',53866,7401);
INSERT INTO stanza VALUES('Z54','2','在你，父的荣耀照明，<br/>显得无比完全；<br/>你有神的丰满神性，<br/>神圣直到永远。<br/>哦，神儿子，你何神圣，<br/>在你我见神的丰盛。<br/>','',53867,7402);
INSERT INTO stanza VALUES('Z54','3','你是无限之神的像，<br/>神的本质包藏；<br/>你是非造之光的亮，<br/>神的心情显彰。<br/>哦，神儿子，你何神圣，<br/>在你我见神的丰盛。<br/>','',53868,7403);
INSERT INTO stanza VALUES('Z54','4','但你名的最高奥秘，<br/>即使天使难晓；<br/>你的奥妙神圣自己，<br/>惟有父神知道。<br/>哦，神儿子，你何神圣，<br/>在你我见神的丰盛。<br/>','',53869,7404);
INSERT INTO stanza VALUES('Z54','5','在那蒙福宇宙之中，<br/>中心在你所是；<br/>永远都要如此称颂<br/>天的可爱之子：<br/>哦， 神儿子，你何神圣，<br/>在你我见神的丰盛。<br/>','',53870,7405);
INSERT INTO stanza VALUES('Z55','1','哦主，你是神的活话，<br/>又是神的儿子；<br/>你是神的真实形像，<br/>有神荣耀样式。<br/>','',53871,7406);
INSERT INTO stanza VALUES('Z55','2','神的本性一切丰满，<br/>全都住你里面；<br/>你是神的具体化身，<br/>借你神得彰显。<br/>','',53872,7407);
INSERT INTO stanza VALUES('Z55','3','是神荣耀所发光辉，<br/>与神原本是一；<br/>是神本体所有真像，<br/>在你神成实际。<br/>','',53873,7408);
INSERT INTO stanza VALUES('Z55','4','在你神是我们生命，<br/>在你神是亮光；<br/>在你我们有神性情，<br/>在你因神增长。<br/>','',53874,7409);
INSERT INTO stanza VALUES('Z55','5','在你神的恩典常存，<br/>在你我得着神；<br/>在你神的实际可寻，<br/>在你我看见神。<br/>','',53875,7410);
INSERT INTO stanza VALUES('Z55','6','在你领受神的丰满，<br/>而且恩上加恩；<br/>在你我们与神调和，<br/>与神一切有分。<br/>','',53876,7411);
INSERT INTO stanza VALUES('Z55','7','哦主，我神，我敬拜你，<br/>我的一切在你；<br/>我心珍爱你的自己，<br/>永远欣赏不已！<br/>','',53877,7412);
INSERT INTO stanza VALUES('Z56','1','恩主耶稣，我敬拜你，<br/>你曾成为『女人裔；』<br/>为一贞洁童女所生，<br/>使神与人成为一。<br/>有了我们人的性情，<br/>以人身分毁古蛇；<br/>借着十架击伤他头，<br/>为神计画胜利得。<br/>','',53878,7413);
INSERT INTO stanza VALUES('Z56','chorus','主，我见你荣耀，<br/>在人美丽显照，<br/>神性荣美显于人性，<br/>配永远称道！<br/>','',53879,7414);
INSERT INTO stanza VALUES('Z56','2','道成肉身，来成为人，<br/>穿上血肉的身体；<br/>为要毁坏魔鬼、撒但，<br/>作了我们的代替。<br/>神命为你起名『耶稣，』<br/>『以马内利』人竟称；<br/>如此成为宝贵救主，<br/>救恩为我全作成。<br/>','',53880,7415);
INSERT INTO stanza VALUES('Z56','3','你被称为『末后亚当，』<br/>也被称为『第二人；』<br/>作新造的万有元首，<br/>胜过旧造第一人。<br/>在这地上生活、行动，<br/>确是人子人共见；<br/>今在天上带着人性，<br/>仍是一人显神前。<br/>','',53881,7416);
INSERT INTO stanza VALUES('Z56','4','在神所定荣耀日子，<br/>恩主，你要再降临；<br/>带着父神丰满荣耀，<br/>显于人前仍是人。<br/>甚至在那审判宝座，<br/>你仍是人行审判；<br/>并且你要将这人性<br/>一直带着到永远。<br/>','',53882,7417);
INSERT INTO stanza VALUES('Z57','1','哦主，你曾成为人子，<br/>有了我们人的性情，<br/>穿上我们血肉之体，<br/>为一贞洁童女所生。<br/>','',53883,7418);
INSERT INTO stanza VALUES('Z57','2','虚己取了奴仆形像，<br/>行走在这艰苦尘世；<br/>尝尽人生所有苦味，<br/>忍受苦难从无所辞。<br/>','',53884,7419);
INSERT INTO stanza VALUES('Z57','3','生在马槽，作一婴孩，<br/>长在干地，出身寒门；<br/>劳苦工作如一木匠，<br/>终被处死像一犯人。<br/>','',53885,7420);
INSERT INTO stanza VALUES('Z57','4','神虽使你从死复活，<br/>你仍带着我们人性；<br/>你虽穿上神圣形状，<br/>仍是一人上升天庭。<br/>','',53886,7421);
INSERT INTO stanza VALUES('Z57','5','今在宝座掌管一切，<br/>荣耀之中仍是一人；<br/>神圣光中与神同在，<br/>以人身位满足神心。<br/>','',53887,7422);
INSERT INTO stanza VALUES('Z57','6','带着荣耀，你要回来，<br/>仍是一人显于众目；<br/>万王之王、万主之主，<br/>仍带人性为人所睹。<br/>','',53888,7423);
INSERT INTO stanza VALUES('Z57','7','将来你在新天、新地，<br/>要作万有一切中心；<br/>虽然你是神圣之主，<br/>仍带人性永远长存。<br/>','',53889,7424);
INSERT INTO stanza VALUES('Z58','1','哦，我神那施爱智慧！<br/>罪恶正盛时候，<br/>末后亚当就来争战，<br/>并来施行拯救。<br/>','',53890,7425);
INSERT INTO stanza VALUES('Z58','2','哦，我神那最智之爱！<br/>亚当虽然失败，<br/>但祂仍要血肉之人，<br/>重新争战奏凯。<br/>','',53891,7426);
INSERT INTO stanza VALUES('Z58','3','要一比恩更高恩赐，<br/>就是神的出现，<br/>和神自己，并神本质，<br/>来将血肉提炼。<br/>','',53892,7427);
INSERT INTO stanza VALUES('Z58','4','哦，我神那慷慨之爱！<br/>祂来在人里面，<br/>为人击杀掌死仇敌，<br/>并且忍死受难。<br/>','',53893,7428);
INSERT INTO stanza VALUES('Z58','5','暗中在那园里哀哭，<br/>明处十架受死，<br/>都是教导祂的弟兄，<br/>如何苦死不辞。<br/>','',53894,7429);
INSERT INTO stanza VALUES('Z58','6','哦主，你这神而人者，<br/>在我人性里面，<br/>为我所作何多、何妙，<br/>配我永远称赞！<br/>','',53895,7430);
INSERT INTO stanza VALUES('Z59','1','哦，何感人的故事：<br/>神的『尊严、』恩典，<br/>带着荣光的启示，<br/>深刻耶稣面间！<br/>当我注目来观审<br/>神这光明形像，<br/>我心惊喜又欢欣，<br/>满了崇敬、欣赏！<br/>','',53896,7431);
INSERT INTO stanza VALUES('Z59','2','你有完全的人性，<br/>神性在你也显；<br/>神的爱与人的情，<br/>神性、人性俱全；<br/>生、死、复活与升天，<br/>显明是神而人，<br/>在地卑微人出现，<br/>在天万有之神。<br/>','',53897,7432);
INSERT INTO stanza VALUES('Z59','3','荣耀无玷的光辉！<br/>永远放光的脸！<br/>丰富难测的作为<br/>借恩将我改变！<br/>不久与你全相像，<br/>眼睛被爱点亮，<br/>在你人子的身上，<br/>见神敞开面光。<br/>','',53898,7433);
INSERT INTO stanza VALUES('Z60','1','耶稣！我爱这名，<br/>耶稣我主！<br/>耶稣！远超万名，<br/>耶稣我主！<br/>主，你作我一切，<br/>你外我无基业，<br/>有你我无所缺，<br/>耶稣我主！<br/>','',53899,7434);
INSERT INTO stanza VALUES('Z60','2','你曾成为人子，<br/>耶稣我主！<br/>你曾替我受死，<br/>耶稣我主！<br/>你爱真是殊优，<br/>远超人世所有，<br/>救恩因你成就，<br/>耶稣我主！<br/>','',53900,7435);
INSERT INTO stanza VALUES('Z60','3','我惟因你得生，<br/>耶稣我主！<br/>我惟靠你得胜，<br/>耶稣我主！<br/>我们还怕甚么<br/>忧虑、苦难、鬼魔！<br/>因为有你相佐，<br/>耶稣我主！<br/>','',53901,7436);
INSERT INTO stanza VALUES('Z60','4','不久你要再临，<br/>耶稣我主！<br/>我们快要欢欣，<br/>耶稣我主！<br/>那时我们见你，<br/>我们就要像你，<br/>并要永远偕你，<br/>耶稣我主！<br/>','',53902,7437);
INSERT INTO stanza VALUES('Z61','1','恩主耶稣，<br/>你名『我是，』<br/>宝贵圣名，丰美、真实！<br/>我所需要全都在此-<br/>全在你所是！<br/>','',53903,7438);
INSERT INTO stanza VALUES('Z61','2','你是圣子、又是圣父，<br/>是神隐藏、是神显出，<br/>且成那灵与我同处，<br/>使我享丰富。<br/>','',53904,7439);
INSERT INTO stanza VALUES('Z61','3','你是帐幕、你是圣殿，<br/>给神安居，将神彰显，<br/>使我在你与神相见，<br/>得享神肥甘。<br/>','',53905,7440);
INSERT INTO stanza VALUES('Z61','4','你是羔羊、你是新郎，<br/>为娶新妇，将罪担当，<br/>为我舍己、为我受伤，<br/>使我得安康。<br/>','',53906,7441);
INSERT INTO stanza VALUES('Z61','5','你是智慧、你是道路，<br/>照神旨意，为我部署，<br/>使我蒙恩，使我受福，<br/>纳我入正途。<br/>','',53907,7442);
INSERT INTO stanza VALUES('Z61','6','你是公义、你是圣洁，<br/>与神相合，为神所悦，<br/>使我称义，使我圣别，<br/>能与神和谐。<br/>','',53908,7443);
INSERT INTO stanza VALUES('Z61','7','你是生命、你是亮光，<br/>消除黑暗，吞灭死亡，<br/>使我复生，使我明亮，<br/>使我得释放。<br/>','',53909,7444);
INSERT INTO stanza VALUES('Z61','7','你是复活、你是大能，<br/>冲破坟墓，胜过幽冥，<br/>使我刚强，使我得胜，<br/>使我占上风。<br/>','',53910,7445);
INSERT INTO stanza VALUES('Z61','9','你是灵粮、你是活水，<br/>为作供应，甘愿降卑，<br/>解我饥渴，苏我困惫，<br/>作了我美味。<br/>','',53911,7446);
INSERT INTO stanza VALUES('Z61','10','你是牧人、你是医生，<br/>为我舍命，医我疾病，<br/>保养、顾惜、<br/>安慰、引领，<br/>凡事都照应。<br/>','',53912,7447);
INSERT INTO stanza VALUES('Z61','11','你是祭司、你是君王，<br/>将我带进神的面光；<br/>你的权柄我得分享，<br/>地位何高尚！<br/>','',53913,7448);
INSERT INTO stanza VALUES('Z61','12','你是救赎、你是盼望，<br/>还要将我改变形状，<br/>使我完全与你相像，<br/>将你来显彰。<br/>','',53914,7449);
INSERT INTO stanza VALUES('Z61','13','还是荣耀、喜乐、平安、<br/>真理、恩典、<br/>活道、灵磐、<br/>日头、盾牌、<br/>居所、靠山，<br/>何人能尽言！<br/>','',53915,7450);
INSERT INTO stanza VALUES('Z61','14','你的所是永远、无限、<br/>长、阔、高、深、<br/>丰满、完全！<br/>岂只应付我的缺欠！<br/>且从我溢漫！<br/>','',53916,7451);
INSERT INTO stanza VALUES('Z62','1','主耶稣，我爱你名！<br/>谦卑俯伏在你前；<br/>荣耀、权柄、<br/>颂赞、尊敬，<br/>我活时必向你献；<br/>向你高歌歌声沛，<br/>心口同声来歌唱，<br/>我魂感佩，因你是配，<br/>你的美丽真非常！<br/>','',53917,7452);
INSERT INTO stanza VALUES('Z62','2','主耶稣，我爱你名！<br/>未有天地未有时，<br/>神爱无境，就已显明，<br/>要施恩典救亡世；<br/>这爱真是永远爱！<br/>堕落如我也眷顾！<br/>爱叫你来，为我负债，<br/>使我成为你珍物。<br/>','',53918,7453);
INSERT INTO stanza VALUES('Z62','3','主耶稣，我爱你名！<br/>你的降生何寒微！<br/>你的慈心满有恩情，<br/>你的道路孤且卑；<br/>我的痛苦你替背，<br/>我的荆冕你替戴，<br/>我的祸杯你替尝备，<br/>常经忧患是为爱。<br/>','',53919,7454);
INSERT INTO stanza VALUES('Z62','4','主耶稣，我爱你名！<br/>『神的羔羊』何清洁！<br/>你被豫定为我受刑，<br/>流出宝血洗罪孽；<br/>现在你坐高天上，<br/>尊贵、荣耀为冠冕；<br/>你打胜仗，我得释放；<br/>阿利路亚主名甜！<br/>','',53920,7455);
INSERT INTO stanza VALUES('Z63','1','耶稣！你名何等芬芳，<br/>在蒙恩人身上！<br/>得救罪人，心里所念，<br/>无一像你这甜。<br/>','',53921,7456);
INSERT INTO stanza VALUES('Z63','2','神来为人，所表恩义，<br/>你名包含无遗，<br/>天上生命、世间生活，<br/>神在你身显着！<br/>','',53922,7457);
INSERT INTO stanza VALUES('Z63','3','『耶稣』这名表明大爱，<br/>如何忍受祸害，<br/>这名说出我们零丁，<br/>天上如何同情。<br/>','',53923,7458);
INSERT INTO stanza VALUES('Z63','4','耶稣无罪，为我成罪，<br/>使我蒙恩受惠；<br/>你舍你身，来得我心，<br/>今后你重我轻。<br/>','',53924,7459);
INSERT INTO stanza VALUES('Z63','5','题起你名，我心即伏，<br/>敬拜救主我主；<br/>你爱救我，我今归你-这超万人的你！<br/>','',53925,7460);
INSERT INTO stanza VALUES('Z64','1','我主，你名<br/>称为『耶稣，』<br/>可爱之名何奇妙；<br/>你由圣洁童女而生，<br/>取了人性与人貌。<br/>你是我『耶和华救主，』<br/>拯救我们脱罪恶；<br/>当我接受你作救主，<br/>神圣生命我得着。<br/>','',53926,7461);
INSERT INTO stanza VALUES('Z64','2','你名也被称为『基督，』<br/>荣耀职事的名称；<br/>你确是神的受膏者，<br/>神从永远所选定。<br/>主，你是神的弥赛亚，<br/>神已因爱立了你，<br/>要你彰显祂的荣耀，<br/>并且完成祂心意。<br/>','',53927,7462);
INSERT INTO stanza VALUES('Z64','3','你也称为『以马内利，』<br/>你是『神与人同在；』<br/>借恩神与人性调和，<br/>永远不能再分开。<br/>神在肉身得着彰显，<br/>满有真理和恩典；<br/>在你我见神的荣耀，<br/>并且得着神丰满。<br/>','',53928,7463);
INSERT INTO stanza VALUES('Z64','4','哦主，我们珍爱你名，<br/>你名所示何丰富；<br/>你名价值和其甘美，<br/>因爱永远要守住。<br/>宝贵救主，荣耀基督，<br/>敬拜、爱戴全归你；<br/>亲爱救主、以马内利，<br/>我要高举永无已！<br/>','',53929,7464);
INSERT INTO stanza VALUES('Z65','1','耶稣大名，荣耀、有能，<br/>是我投靠、是我倚；<br/>『坐在天上，』<br/>我今赞美，<br/>你名就是我胜利。<br/>','',53930,7465);
INSERT INTO stanza VALUES('Z65','2','可颂耶稣、大能救主，<br/>我所需要在你名；<br/>只要呼吸耶稣这名，<br/>就是饮于你生命。<br/>','',53931,7466);
INSERT INTO stanza VALUES('Z65','3','耶稣大名，荣耀、有能，<br/>天地宣告牠大能；<br/>然而只有蒙恩罪人，<br/>知道这名的丰盛！<br/>','',53932,7467);
INSERT INTO stanza VALUES('Z65','4','耶稣！耶稣！最贵之名，<br/>战时兵器、病时膏；<br/>在你名里生活争战，<br/>就有喜乐和荣耀。<br/>','',53933,7468);
INSERT INTO stanza VALUES('Z66','1','耶稣，这名甜美、芬芳，<br/>慰我痛苦心情；<br/>我心欢乐，我口歌唱<br/>这个宝贵的名。<br/>','',53934,7469);
INSERT INTO stanza VALUES('Z66','chorus','美哉、妙哉，神的爱子<br/>作我宝贵救主；<br/>为我降生，为我受死，<br/>流血将我救赎。<br/>','',53935,7470);
INSERT INTO stanza VALUES('Z66','2','耶稣原有神的形像，<br/>竟来成为人子，<br/>虚己取了奴仆形状，<br/>使我作神后嗣。<br/>','',53936,7471);
INSERT INTO stanza VALUES('Z66','3','耶稣乃是生命、亮光，<br/>乃是真理、道路；<br/>今在我心作主、作王，<br/>将我引导、安抚。<br/>','',53937,7472);
INSERT INTO stanza VALUES('Z66','4','宝贵救主远胜奇珍，<br/>时刻满足我心，<br/>解我愁苦、消我烦闷，<br/>永远与我相亲。<br/>','',53938,7473);
INSERT INTO stanza VALUES('Z66','5','宝贵救主不久再临，<br/>接我与祂同在，<br/>使我贱体变成荣身，<br/>安息直到万代。<br/>','',53939,7474);
INSERT INTO stanza VALUES('Z66','chorus','荣哉、乐哉，耶稣我主，<br/>永是我的荣耀；<br/>荣耀之名乃是耶稣，<br/>我要永远称道。<br/>','',53940,7475);
INSERT INTO stanza VALUES('Z67','1','大地无名甜至如此！<br/>名甜至此高天无！<br/>祂离荣耀来世界时，<br/>神将这名赐救主。<br/>','',53941,7476);
INSERT INTO stanza VALUES('Z67','chorus','我们爱唱：基督神子，<br/>并且称祂为耶稣；<br/>因为从来未有文字，<br/>这宝、这甜，<br/>如『耶稣。』<br/>','',53942,7477);
INSERT INTO stanza VALUES('Z67','2','当人将祂挂在木上，<br/>他们同时挂这名，<br/>好叫天下都能欣赏<br/>我们爱祂的究竟。<br/>','',53943,7478);
INSERT INTO stanza VALUES('Z67','3','当祂上升高坐宝座，<br/>神将这名赏赐祂，<br/>万膝跪拜、万口唱和，<br/>天上地下都迎驾！<br/>','',53944,7479);
INSERT INTO stanza VALUES('Z67','4','主，借你这名的无比，<br/>恩典不至渐疲倦；<br/>今日、昨天，你不更易，<br/>你是一样到永远！<br/>','',53945,7480);
INSERT INTO stanza VALUES('Z68','1','被杀羔羊，耶稣基督，<br/>被神高举天上；<br/>罪人朋友，荣耀救主，<br/>配得永远颂扬。<br/>','',53946,7481);
INSERT INTO stanza VALUES('Z68','chorus','颂赞主尊名，<br/>颂赞主尊名，<br/>颂赞、荣耀，归主尊名。<br/>阿利路亚！阿利路亚！<br/>颂赞、荣耀，归主尊名。<br/>阿利路亚！阿利路亚！<br/>颂赞、荣耀，归主尊名。<br/>','',53947,7482);
INSERT INTO stanza VALUES('Z68','2','超乎万名之上的名，<br/>已经赐给耶稣；<br/>天上、地上一切众生，<br/>无不称祂为主。<br/>','',53948,7483);
INSERT INTO stanza VALUES('Z68','3','天使下拜，天军俯伏，<br/>万有也都屈膝，<br/>敬拜救主，高举基督，<br/>颂赞羔羊不已。<br/>','',53949,7484);
INSERT INTO stanza VALUES('Z68','4','蒙恩罪人也要欢呼，<br/>同声颂赞救主：<br/>为我流血，将我救赎，<br/>使我永远得福。<br/>','',53950,7485);
INSERT INTO stanza VALUES('Z68','5','但愿权柄、智慧、丰富、<br/>尊贵、荣耀、王权，<br/>归给羔羊，救主基督，<br/>直到永永远远！<br/>','',53951,7486);
INSERT INTO stanza VALUES('Z69','1','耶稣这名超乎万名，<br/>天上、地上、阴间：<br/>天使和人无不尊敬，<br/>魔鬼惧怕、逃窜。<br/>','',53952,7487);
INSERT INTO stanza VALUES('Z69','2','耶稣这名可亲、可爱，<br/>赐给罪人之名；<br/>定罪、惧怕，为我赶开，<br/>带来天上安宁。<br/>','',53953,7488);
INSERT INTO stanza VALUES('Z69','3','耶稣打碎罪囚枷锁，<br/>打伤撒但的头；<br/>祂用大能吞灭软弱，<br/>祂用生命拯救。<br/>','',53954,7489);
INSERT INTO stanza VALUES('Z69','4','但愿世人都能尝到<br/>祂的丰富恩典！<br/>都能享受祂的怀抱，<br/>投在祂的胸间。<br/>','',53955,7490);
INSERT INTO stanza VALUES('Z69','5','耶稣这名永远可靠，<br/>够我度过今生；<br/>直到永世可爱、可宝，<br/>永远是我见证。<br/>','',53956,7491);
INSERT INTO stanza VALUES('Z70','1','耶稣这名何其甘甜，<br/>犹如音乐我爱称赞，<br/>牠使我乐丰满完全，<br/>耶稣宝贵之名。<br/>','',53957,7492);
INSERT INTO stanza VALUES('Z70','chorus','耶稣！这名何甘甜，<br/>耶稣！天天不改变；<br/>耶稣！圣徒当称赞<br/>牠的价值到永远。<br/>','',53958,7493);
INSERT INTO stanza VALUES('Z70','2','我爱那爱我者之名，<br/>祂知我苦，分担、同情，<br/>命令忧惧从我隐形，<br/>我爱耶稣之名。<br/>','',53959,7494);
INSERT INTO stanza VALUES('Z70','3','这名迷人，我爱听见，<br/>一听我心不禁狂欢，<br/>其乐将我眼泪擦干；<br/>高举耶稣之名。<br/>','',53960,7495);
INSERT INTO stanza VALUES('Z70','4','无人话语能以尽言<br/>我爱之名何其甘甜；<br/>愿人将牠永远称赞，<br/>称赞耶稣之名。<br/>','',53961,7496);
INSERT INTO stanza VALUES('Z71','1','我们知你已复起，<br/>死亡中的初熟；<br/>我们见你已被提，<br/>荣耀元首基督。<br/>蒙恩得与你相交，<br/>心、思都能无忌<br/>来想你的众荣耀，<br/>因已与你合一。<br/>','',53962,7497);
INSERT INTO stanza VALUES('Z71','2','你是万有的元首，<br/>你有最大权柄；<br/>你是以『人』升父右，<br/>你有最高的名！<br/>加略已显最高能，<br/>也显你最高爱；<br/>你爱已完全得胜，<br/>痛苦最暗残害。<br/>','',53963,7498);
INSERT INTO stanza VALUES('Z71','3','不久万有宝珍你，<br/>万有赞美你名；<br/>不久万有承认你，<br/>向你表示欢迎。<br/>现今只有我们能<br/>认识你的大爱；<br/>能尝你爱满衷情，<br/>向你赞美不迨。<br/>','',53964,7499);
INSERT INTO stanza VALUES('Z71','4','你名更比万名彰，<br/>你赐越乎众赐，<br/>你爱高于万爱上，<br/>永不、永不中止。<br/>我们欢乐来称道，<br/>因已合一不改；<br/>永远乃是你荣耀，<br/>永远乃是你爱。<br/>','',53965,7500);
INSERT INTO stanza VALUES('Z72','1','主，你根源在亘古，<br/>在那无始的太初！<br/>因你就是永远父，<br/>就是自有永有主！<br/>','',53966,7501);
INSERT INTO stanza VALUES('Z72','2','你虽出生人世间，<br/>却是与神同永远！<br/>与神同样的完满，<br/>与神同样的无限！<br/>','',53967,7502);
INSERT INTO stanza VALUES('Z72','3','你乃与神同根源，<br/>早过万有并地天！<br/>没有先者比你先，<br/>没有前者比你前！<br/>','',53968,7503);
INSERT INTO stanza VALUES('Z72','4','永不改变永不旧，<br/>你的年数无尽休！<br/>没有久者比你久，<br/>没有后者比你后！<br/>','',53969,7504);
INSERT INTO stanza VALUES('Z72','5','你与父神无所差，<br/>与神一样无可加！<br/>所以也是阿拉法，<br/>并且也是俄梅嘎！<br/>','',53970,7505);
INSERT INTO stanza VALUES('Z72','6','我们赞美你永远，<br/>我们称颂你完全！<br/>赏识你是何丰满，<br/>希奇你是何无限！<br/>','',53971,7506);
INSERT INTO stanza VALUES('Z73','1','主，接纳我们的诗歌，<br/>虽然声音顶柔弱；<br/>我们述说你的恩笃，<br/>因你是我们救主。<br/>','',53972,7507);
INSERT INTO stanza VALUES('Z73','2','因你舍去荣耀、丰富，<br/>你的信徒才得福；<br/>你变贫穷，叫你信徒<br/>因你享荣耀、丰富。<br/>','',53973,7508);
INSERT INTO stanza VALUES('Z73','3','天上有何使你心厌？<br/>世界有何使你羡？<br/>因而你就离天临世，<br/>孤单、凄凉直到死？<br/>','',53974,7509);
INSERT INTO stanza VALUES('Z73','4','你在天上何等荣耀！<br/>你在世上何萧条！<br/>你早已知此行艰难，<br/>只因爱我竟甘愿。<br/>','',53975,7510);
INSERT INTO stanza VALUES('Z73','5','当我想到你的良善，<br/>就不禁又喜又惭！<br/>喜，因你能这样爱好；<br/>惭，因我这样还报。<br/>','',53976,7511);
INSERT INTO stanza VALUES('Z73','6','但我们望那日快到，<br/>脱尽所有的阻挠；<br/>那时我们进荣耀里，<br/>要照本分服事你。<br/>','',53977,7512);
INSERT INTO stanza VALUES('Z73','7','现今我们等在这里，<br/>因这盼望受策励；<br/>主，使我们活着为你，<br/>直到你前同聚集。<br/>','',53978,7513);
INSERT INTO stanza VALUES('Z74','1','听阿，天使赞高声，<br/>颂扬救主今诞生！<br/>『荣耀在天归与神，<br/>平安在地临及人。』<br/>兴起！地上众生灵，<br/>响应天上赞美声；<br/>天唱地和乐欢腾，<br/>基督诞生大卫城。<br/>天唱地和乐欢腾，<br/>基督诞生大卫城。<br/>','',53979,7514);
INSERT INTO stanza VALUES('Z74','2','基督本有神形像，<br/>基督原居神荣光，<br/>竟在末世从天降，<br/>生于童女成人状；<br/>神性穿上血肉体，<br/>道成肉身何奥秘，<br/>甘愿作人同人住，<br/>以马内利是耶稣。<br/>甘愿作人同人住，<br/>以马内利是耶稣。<br/>','',53980,7515);
INSERT INTO stanza VALUES('Z74','3','欢迎，天来和平王！<br/>欢迎，公义的太阳！<br/>带来生命与亮光，<br/>使人复活，医人伤；<br/>虚己，撇下祂荣光，<br/>降生救人免死亡，<br/>降生使人得重生，<br/>降生使人能高升。<br/>降生使人得重生，<br/>降生使人能高升。<br/>','',53981,7516);
INSERT INTO stanza VALUES('Z74','4','万国『羡慕，』<br/>万民『望，』<br/>愿你安家我心房；<br/>女人后裔-得胜者，<br/>在我里面毁古蛇；<br/>亚当旧样全除尽，<br/>你的形像将我印；<br/>末后亚当的丰盛，<br/>使我变成你荣形。<br/>末后亚当的丰盛，<br/>使我变成你荣形。<br/>『羡慕』意即所羡慕的那位，指基督，引自哈该书二章七节小字。<br/>『望』指基督是万民的盼望。<br/>','',53982,7517);
INSERT INTO stanza VALUES('Z75','1','永活的故事，<br/>撇下荣耀降世，<br/>神来作我救主，<br/>成人，名叫耶稣。<br/>生在马槽里，<br/>像根出于干地，<br/>成为忧患的人，<br/>常受痛苦。<br/>','',53983,7518);
INSERT INTO stanza VALUES('Z75','chorus','我何等爱祂！<br/>何等敬拜祂！<br/>我气，我日光，<br/>我的一切！<br/>伟大创造主，<br/>作了我救主，<br/>带来神丰满，取用不竭。<br/>','',53984,7519);
INSERT INTO stanza VALUES('Z75','2','何等的低就，<br/>为要使我得救；<br/>使那荫中丧亡，<br/>无一至于失望；<br/>神何柔而爱，<br/>撇开祂的光彩，<br/>降卑来苦、来爱、<br/>来救丧亡。<br/>','',53985,7520);
INSERT INTO stanza VALUES('Z75','3','丝毫不勉强，<br/>祂将血肉穿上，<br/>取了人的形状，<br/>将神计划显彰。<br/>荣耀的奥秘，<br/>神人竟成为一；<br/>在你，神的一切<br/>我全得享。<br/>','',53986,7521);
INSERT INTO stanza VALUES('Z76','1','主，你温柔所留印记，<br/>照耀神圣，何其美丽！<br/>在你所行孤单路中，<br/>你爱留下希奇行踪。<br/>','',53987,7522);
INSERT INTO stanza VALUES('Z76','2','你这人子，光中之光，<br/>有谁像你柔细、明亮？<br/>有谁像你如此忍耐，<br/>经过这一艰苦尘埃？<br/>','',53988,7523);
INSERT INTO stanza VALUES('Z76','3','被人辱骂向不还口，<br/>遭受苦害从无怨尤；<br/>何其和善、何其谦卑，<br/>谦和之中又何荣美！<br/>','',53989,7524);
INSERT INTO stanza VALUES('Z76','4','为使罪囚得着自由，<br/>囚犯之死甘愿忍受；<br/>借此你爱显明无留，<br/>怜悯随着你血涌流。<br/>','',53990,7525);
INSERT INTO stanza VALUES('Z76','5','希奇的主，我何愿望：<br/>更多模成你的形像，<br/>学你式微，像你谦卑，<br/>你的脚踪终生跟随。<br/>','',53991,7526);
INSERT INTO stanza VALUES('Z77','1','你是至高、荣耀的神，<br/>竟肯降卑成为肉身，<br/>作了一个式微的人，<br/>主阿，我记念你！<br/>','',53992,7527);
INSERT INTO stanza VALUES('Z77','2','你将一切神性荣耀，<br/>全用肉身幔子遮罩，<br/>显于外者不过枯槁，<br/>主阿，我记念你！<br/>','',53993,7528);
INSERT INTO stanza VALUES('Z77','3','你乃像根出于干地，<br/>多受痛苦，常经忧悒，<br/>被人藐视，受人厌弃，<br/>主阿，我记念你！<br/>','',53994,7529);
INSERT INTO stanza VALUES('Z77','4','你的心里谦卑、温柔，<br/>任何遭遇都肯接受，<br/>对神、对人从无怨尤，<br/>主阿，我记念你！<br/>','',53995,7530);
INSERT INTO stanza VALUES('Z77','5','你的为人甜美、柔细、<br/>各方均平、不偏不倚，<br/>在神眼中犹如素祭，<br/>主阿，我记念你！<br/>','',53996,7531);
INSERT INTO stanza VALUES('Z77','6','神的旨意你所顾念，<br/>从未接受撒但欺骗，<br/>无人像你忠诚、完全，<br/>主阿，我记念你！<br/>','',53997,7532);
INSERT INTO stanza VALUES('Z77','7','为着顺服神的旨意，<br/>你竟甘愿走到死地，<br/>且在十架舍了自己，<br/>主阿，我记念你！<br/>','',53998,7533);
INSERT INTO stanza VALUES('Z77','7','父神因此将你升高，<br/>使你得着尊贵、荣耀，<br/>天地一切无不拜朝，<br/>主阿，我敬拜你！<br/>','',53999,7534);
INSERT INTO stanza VALUES('Z78','1','你在地上所有行径，<br/>何其仁慈、美丽！<br/>你在人性不凡生平，<br/>令人叹赏、惊奇！<br/>','',54000,7535);
INSERT INTO stanza VALUES('Z78','2','你在艰苦历程显出<br/>何等忍耐的爱！<br/>艰苦至死亦所不顾，<br/>忍、爱，谁能比赛！<br/>','',54001,7536);
INSERT INTO stanza VALUES('Z78','3','你心受创，重负难减，<br/>常是忧患重重，<br/>然而从无不美怨言，<br/>出你缄默口中。<br/>','',54002,7537);
INSERT INTO stanza VALUES('Z78','4','敌者妒恨，拒者辱骂，<br/>从者显为不忠，<br/>你仍不烦，宽赦有加，<br/>你心惟爱是从。<br/>','',54003,7538);
INSERT INTO stanza VALUES('Z78','5','哦！主，在地你的生平，<br/>各方真如素祭：<br/>柔细、香甜、<br/>完全、均衡，<br/>神、人共赏不已！<br/>','',54004,7539);
INSERT INTO stanza VALUES('Z79','1','哦主，当我们想到你<br/>在世所历路程：<br/>（你以恩爱对待群黎，<br/>你以忠诚对神。<br/>','',54005,7540);
INSERT INTO stanza VALUES('Z79','2','你爱虽然被人辜负，<br/>显为比死更强；<br/>刺你的枪，不过引出<br/>血水，洗人天良。<br/>','',54006,7541);
INSERT INTO stanza VALUES('Z79','3','你虽自己常经忧患，<br/>你却到处行善；<br/>虽然你的路途艰难，<br/>你却不想怨叹。<br/>','',54007,7542);
INSERT INTO stanza VALUES('Z79','4','四围不忠，你却赤忠；<br/>黑暗，你却光明。<br/>父的喜乐，你心所重，<br/>从未违祂命令。<br/>','',54008,7543);
INSERT INTO stanza VALUES('Z79','5','不因撒但诡计摇动，<br/>不顾苦难、损失；<br/>你的行径，无人同情，<br/>孤单一直到死。）<br/>','',54009,7544);
INSERT INTO stanza VALUES('Z79','6','我们不禁奇你谦卑，<br/>盼望能以像你；<br/>主，我们愿学你式微，<br/>因这里有安息。<br/>','',54010,7545);
INSERT INTO stanza VALUES('Z80','1','我今俯伏，生命的王，<br/>奉献荣耀于你；<br/>惟恐我忘你的受创，<br/>领我去髑髅地。<br/>','',54011,7546);
INSERT INTO stanza VALUES('Z80','chorus','惟恐我忘客西马尼，<br/>惟恐我忘你心忧急，<br/>惟恐我忘你爱无极，<br/>领我去髑髅地。<br/>','',54012,7547);
INSERT INTO stanza VALUES('Z80','2','何处是你被埋坟墓？<br/>让我前去哀悼；<br/>天使是在何处守护？<br/>当你息劳睡倒。<br/>','',54013,7548);
INSERT INTO stanza VALUES('Z80','3','让我效法马利亚女，<br/>前来向你献礼；<br/>请示空墓是在何许，<br/>领我去髑髅地。<br/>','',54014,7549);
INSERT INTO stanza VALUES('Z80','4','使我甘心天天为你<br/>背起我十字架，<br/>尝你苦杯，我也愿意，<br/>因你为我被杀。<br/>','',54015,7550);
INSERT INTO stanza VALUES('Z80','5','你愿得着所有的人，<br/>我求同此心意，<br/>求用圣火洁我嘴唇，<br/>来说你髑髅地。<br/>','',54016,7551);
INSERT INTO stanza VALUES('Z81','1','耶稣！永远生命之源！<br/>耶稣！我气息之始！<br/>你已胜过阴府黑暗，<br/>借着忍辱与受死。<br/>你曾经过火热、水深，<br/>屈尊为我成功救恩：<br/>千千万万的赞美，<br/>荣耀救主，惟你配！<br/>千千万万的赞美，<br/>荣耀救主，惟你配！<br/>','',54017,7552);
INSERT INTO stanza VALUES('Z81','2','神的儿子，你曾忍受<br/>讥诮、妒恨与苦害！<br/>荣耀的王，为我愆尤，<br/>荆棘冠冕你竟戴；<br/>受死为要将我救援，<br/>使我脱离罪的锁炼：<br/>千千万万的赞美，<br/>宝贵救主，惟你配！<br/>','',54018,7553);
INSERT INTO stanza VALUES('Z81','3','人所堆在你身羞辱，<br/>你全无声的忍受；<br/>甚至忍受死的痛苦，<br/>为使救赎得成就。<br/>你的降卑令人惊奇，<br/>竟肯来到受死之地：<br/>千千万万的赞美，<br/>宝贵救主，惟你配！<br/>','',54019,7554);
INSERT INTO stanza VALUES('Z81','4','因着你曾降卑尘埃，<br/>因着你死使我生，<br/>心中赞美、灵里敬拜，<br/>救主，全都向你呈。<br/>所有忧患你已担当，<br/>所有祝福我今得享：<br/>这要成为我诗题，<br/>永远赞美你不已。<br/>','',54020,7555);
INSERT INTO stanza VALUES('Z82','1','哦，满了伤痕的头，<br/>满了痛苦、谇诟，<br/>受尽万般的试炼，<br/>又戴荆棘冠冕；<br/>这头今日已得荣，<br/>已得圣徒歌诵，<br/>可怜当日受死伤，<br/>在加略木头上。<br/>','',54021,7556);
INSERT INTO stanza VALUES('Z82','2','你的面容原超凡，<br/>如同光明太阳，<br/>父神一见就悦纳，<br/>竟受罪人唾打。<br/>主，你所受的一切，<br/>都为我们罪孽；<br/>我们债务得清付，<br/>你却被人剪除。<br/>','',54022,7557);
INSERT INTO stanza VALUES('Z82','3','我们想到你痛苦，<br/>又想到你无辜，<br/>我们又满心欢喜，<br/>又是感激无既！<br/>阿，当我们正如此<br/>念你十字架时，<br/>就是生命全舍弃，<br/>损失还算利益。<br/>','',54023,7558);
INSERT INTO stanza VALUES('Z82','4','我们救主-危难友，<br/>我们报恩无由！<br/>当你为我流血时，<br/>你的痛苦谁知？<br/>求你使我从今后，<br/>天天记念髑髅，<br/>直到被提进荣耀，<br/>永远与你相交。<br/>','',54024,7559);
INSERT INTO stanza VALUES('Z83','1','时已夜半，晚星久沉，<br/>救主身临橄榄山岑；<br/>客西马尼，深夜寂静，<br/>救主在内祈祷、儆醒。<br/>','',54025,7560);
INSERT INTO stanza VALUES('Z83','2','时已夜半，无人陪同，<br/>救主独自祈祷、伤痛；<br/>虽是爱徒也都沉睡，<br/>不顾救主伤心、流泪。<br/>','',54026,7561);
INSERT INTO stanza VALUES('Z83','3','时已夜半，忧伤至极，<br/>救主祈祷汗如血滴；<br/>天使来临加祂身力，<br/>证明神未将祂撇弃。<br/>','',54027,7562);
INSERT INTO stanza VALUES('Z83','4','时已夜半，祈祷已尽，<br/>深知苦杯不能不饮，<br/>甘愿成就父神旨意，<br/>去替罪人担罪舍己。<br/>','',54028,7563);
INSERT INTO stanza VALUES('Z84','1','哦主，甚么使你头垂？<br/>我罪压你身上！<br/>你是站在罪人地位，<br/>将我罪孽担当。<br/>作我祭牲，流血赎罪，<br/>使我得着释放。<br/>','',54029,7564);
INSERT INTO stanza VALUES('Z84','2','我杯满了咒诅、死亡，<br/>是我应得之分，<br/>然而其中每滴苦汤，<br/>你都为我喝尽。<br/>苦杯你爱为我尽尝，<br/>福杯我今得饮。<br/>','',54030,7565);
INSERT INTO stanza VALUES('Z84','3','耶和华曾举起祂杖，<br/>哦主，向你打下！<br/>你被你神痛苦击伤，<br/>使我免受刑罚；<br/>你的宝血因此流淌，<br/>作了我的赎价。<br/>','',54031,7566);
INSERT INTO stanza VALUES('Z84','4','狂风大起，怒涛骇浪，<br/>哦主，向你进迫！<br/>你的胸怀为我抵挡，<br/>作我安息之所。<br/>因你为我受死受伤，<br/>平安我今得着。<br/>','',54032,7567);
INSERT INTO stanza VALUES('Z84','5','耶和华曾吩咐祂刀，<br/>哦主，向你兴起！<br/>牠的残酷火刃闪耀，<br/>须将你血饮吸；<br/>既已满足神之所要，<br/>牠的要求遂息。<br/>','',54033,7568);
INSERT INTO stanza VALUES('Z84','6','哦主，你曾为我受死，<br/>我也在你死了；<br/>你已复活，将我开释，<br/>今在我里活着。<br/>经过炼净、纯洁、无疵，<br/>就得进你荣耀。<br/>','',54034,7569);
INSERT INTO stanza VALUES('Z85','1','我每静念那十字架，<br/>并主如何在上受熬，<br/>我就不禁浑忘身家，<br/>鄙视从前所有倨傲。<br/>','',54035,7570);
INSERT INTO stanza VALUES('Z85','2','愿主禁我别有所夸，<br/>除了基督的十字架；<br/>前所珍爱虚空荣华，<br/>今为祂血情愿丢下。<br/>','',54036,7571);
INSERT INTO stanza VALUES('Z85','3','看从祂头！祂脚！祂手！<br/>忧情、慈爱和血而流！<br/>那有爱忧如此相遘？<br/>荆棘编成如此冕旒？<br/>','',54037,7572);
INSERT INTO stanza VALUES('Z85','4','看祂全身满被水血，<br/>如同穿上朱红衣饰！<br/>因此，我与世界断绝，<br/>世界向我也像已死。<br/>','',54038,7573);
INSERT INTO stanza VALUES('Z85','5','假若宇宙都归我手，<br/>尽以奉主仍觉可羞；<br/>爱既如此奇妙、深厚，<br/>当得我心、我命-所有。<br/>','',54039,7574);
INSERT INTO stanza VALUES('Z86','1','屈身，低首，强暴压逼，<br/>背着十架向前行；<br/>如羊牵到宰杀之地，<br/>忍辱、忍怨，无反应。<br/>','',54040,7575);
INSERT INTO stanza VALUES('Z86','chorus','哦主，你是无辜，竟肯<br/>为我罪愆受委屈！<br/>爱既如此长阔高深，<br/>余生属你永不渝。<br/>','',54041,7576);
INSERT INTO stanza VALUES('Z86','2','头戴荆冕，身悬木上，<br/>手足被钉，肋中枪，<br/>父神离弃，敌魔猖狂，<br/>身灵受创痛难当。<br/>','',54042,7577);
INSERT INTO stanza VALUES('Z86','3','未肯从你十架跳下，<br/>未求天使来营救；<br/>任人摆布，甘受倾轧，<br/>正为满足神要求。<br/>','',54043,7578);
INSERT INTO stanza VALUES('Z86','4','太阳掩面不忍再睹，<br/>无疵羔羊惨丧身。<br/>殿幔裂出新活的路，<br/>罪人坦然亲近神。<br/>','',54044,7579);
INSERT INTO stanza VALUES('Z87','1','主，我宝贵你的行径，<br/>如何在此受苦害；<br/>那些最终悲痛情形，<br/>使我更觉你可爱。<br/>','',54045,7580);
INSERT INTO stanza VALUES('Z87','chorus','赞美救主，赞美救主，<br/>赞美主为罪人死；<br/>荣耀救主，荣耀救主，<br/>荣耀、荣耀，<br/>主为死人活。<br/>','',54046,7581);
INSERT INTO stanza VALUES('Z87','2','主，你当时艰难何大，<br/>大到无人会究推；<br/>无道摧残、无理蹧蹋，<br/>痛苦有谁能微窥！<br/>','',54047,7582);
INSERT INTO stanza VALUES('Z87','3','可爱的主，当你救赎，<br/>没有一人能跟随；<br/>因为许多定罪囚奴，<br/>需要你独受鞭锤。<br/>','',54048,7583);
INSERT INTO stanza VALUES('Z87','4','那时你量罪的距离-<br/>忿怒、咒诅和悲哀，<br/>为人所卖，为神所弃，<br/>我们才识你可爱。<br/>','',54049,7584);
INSERT INTO stanza VALUES('Z88','1','耶稣独自为我祈祷，<br/>在那客西马尼，<br/>极其伤痛，大声哀告，<br/>流汗犹如血滴。<br/>','',54050,7585);
INSERT INTO stanza VALUES('Z88','chorus','为我！为我！<br/>为我祂钉十架，<br/>舍命流血作我赎价；<br/>祂心如蜡镕化，<br/>为我！为我！<br/>','',54051,7586);
INSERT INTO stanza VALUES('Z88','2','耶稣独自为我被捆，<br/>在祂被卖晚间；<br/>并且独自为我受审，<br/>在彼拉多面前。<br/>','',54052,7587);
INSERT INTO stanza VALUES('Z88','3','耶稣独自为我被鞭，<br/>鞭得皮破肉烂；<br/>独自为我头戴荆冕，<br/>被人羞辱侮慢。<br/>','',54053,7588);
INSERT INTO stanza VALUES('Z88','4','耶稣独自为我受死，<br/>在各各他山巅，<br/>手足被钉，肋旁被刺，<br/>流血赎我罪愆。<br/>','',54054,7589);
INSERT INTO stanza VALUES('Z88','5','耶稣独自为我喝尽<br/>忿怒咒诅苦杯，<br/>好使我能得蒙救恩，<br/>永远不尝死味。<br/>','',54055,7590);
INSERT INTO stanza VALUES('Z88','6','听祂临死喊说：<br/>『成了！』<br/>我心能无感慨？<br/>切莫硬把感动灭消，<br/>不理祂这大爱！<br/>','',54056,7591);
INSERT INTO stanza VALUES('Z89','1','主，你的爱竟然不辞<br/>为我忍辱受死！<br/>好叫我们胜过罪世，<br/>并那壮士权势。<br/>','',54057,7592);
INSERT INTO stanza VALUES('Z89','2','哦，你的担何等的重！<br/>何等难于背负！<br/>人的罪恶、鬼的讥讽、<br/>加上神的忿怒。<br/>','',54058,7593);
INSERT INTO stanza VALUES('Z89','3','围困你的狂怒风波，<br/>今已永远平静；<br/>因之我们得着欢乐，<br/>你得超绝的名。<br/>','',54059,7594);
INSERT INTO stanza VALUES('Z89','4','我们不久你前被提，<br/>要唱新歌赞你；<br/>但在这里-你死的地，<br/>我们要先唱起。<br/>','',54060,7595);
INSERT INTO stanza VALUES('Z90','1','赞美不尽赞美，<br/>赞美救主恩深；<br/>感佩无限感佩，<br/>感佩救主舍身；<br/>看哪，神子在各各他，<br/>为你和我钉十字架。<br/>','',54061,7596);
INSERT INTO stanza VALUES('Z90','2','主爱远胜爷娘，<br/>远胜最好朋友；<br/>蒙恩罪人颂扬<br/>主爱，直到永久；<br/>看哪，神子在各各他，<br/>为你和我钉十字架。<br/>','',54062,7597);
INSERT INTO stanza VALUES('Z90','3','罪人今已蒙恩，<br/>魔鬼今已失败；<br/>谁能再使我们<br/>离开基督的爱？<br/>看哪，神子在各各他，<br/>为你和我钉十字架。<br/>','',54063,7598);
INSERT INTO stanza VALUES('Z91','1','祂不能救自己，<br/>必须死髑髅地；<br/>不然，恩典无门，<br/>来救荒凉罪人；<br/>真的，神儿子当流血，<br/>罪人才能洗得清洁，<br/>罪人才能洗得清洁。<br/>','',54064,7599);
INSERT INTO stanza VALUES('Z91','2','祂不能救自己，<br/>必须成全公义；<br/>我罪当有刑罚，<br/>需要祂来被杀；<br/>律法非此不算还债，<br/>非此，罪恶不能宽贷。<br/>','',54065,7600);
INSERT INTO stanza VALUES('Z91','3','祂不能救自己，<br/>因为祂是代替<br/>信祂的人站立<br/>在罪人的死地。<br/>祂在十字架上流血，<br/>担当信徒一切罪孽。<br/>','',54066,7601);
INSERT INTO stanza VALUES('Z91','4','祂不能救自己，<br/>这爱怎么样呢！<br/>祂不能救自己，<br/>这爱那有止极！<br/>我们的心虽然冷淡，<br/>这爱叫牠发出感赞。<br/>','',54067,7602);
INSERT INTO stanza VALUES('Z92','1','此时何时！孤单之时！<br/>四围都是黑暗！<br/>天上神的独生之子，<br/>以人血肉代人受死，<br/>这是何等悲惨！<br/>荣耀的主钉十字架！<br/>生命的王受人倾轧！<br/>','',54068,7603);
INSERT INTO stanza VALUES('Z92','2','哦，这样的神、人，<br/>生、死，<br/>真是奇中之奇！<br/>这是中心！两个永世<br/>莫不举目而顾、而视<br/>你这当受赞的！<br/>哦，主耶稣，你十字架<br/>乃是我的永远美家！<br/>','',54069,7604);
INSERT INTO stanza VALUES('Z92','3','哦，当我们看那木头，<br/>心中何等感动；<br/>爱的化身死在髑髅！<br/>哦，怎能不又喜又愁，<br/>看你这样苦痛！<br/>我们心裂听你呼祈：<br/>『以利，<br/>拉马撒巴大尼！』<br/>','',54070,7605);
INSERT INTO stanza VALUES('Z92','4','哦主，我们真是该死，<br/>该受神的忿怒，<br/>但神使你-祂的爱子-为我受苦、担罪、忍耻；<br/>公义杀我救主；<br/>我已与你同被钉钉，<br/>我已与你在彼丧命。<br/>','',54071,7606);
INSERT INTO stanza VALUES('Z92','5','我们与你一同得生，<br/>与你从死同苏，<br/>因你是头，我们是身，<br/>我们同你都是属神，<br/>一同蒙神赐福；<br/>我们原来只配受罚，<br/>今却同你呼喊阿爸。<br/>','',54072,7607);
INSERT INTO stanza VALUES('Z93','1','哎哟！救主真曾流血？<br/>真曾舍命亡躬？<br/>祂肯牺牲祂的超越，<br/>为我这个小虫？<br/>','',54073,7608);
INSERT INTO stanza VALUES('Z93','2','祂在木上那样哀叹，<br/>可是为我罪愆？<br/>怜悯何满！慈爱何泛！<br/>恩典何其无边！<br/>','',54074,7609);
INSERT INTO stanza VALUES('Z93','3','难怪太阳立变暗乌，<br/>隐藏一切荣光；<br/>当神基督造物的主，<br/>为人担罪而亡。<br/>','',54075,7610);
INSERT INTO stanza VALUES('Z93','4','当我看见祂十字架，<br/>也当隐藏羞脸，<br/>心当镕化，感激不暇，<br/>眼当流泪自贬。<br/>','',54076,7611);
INSERT INTO stanza VALUES('Z93','5','但这满腔忧伤，<br/>不能稍还主爱的债；<br/>主，我在此奉上一生，<br/>聊表此心感戴。<br/>','',54077,7612);
INSERT INTO stanza VALUES('Z94','1','你的救赎何等奇妙，<br/>我的恩主耶稣！<br/>未见、未闻、也未想到，<br/>你竟为我作出！<br/>你的身位奥秘、神圣，<br/>远超我所能言！<br/>你的救赎奇妙、有能，<br/>过于我所能赞！<br/>','',54078,7613);
INSERT INTO stanza VALUES('Z94','chorus','哦，你救赎何奇妙！<br/>新造故事，何荣耀！<br/>永远丰满有功效！<br/>配得我们称道！<br/>','',54079,7614);
INSERT INTO stanza VALUES('Z94','2','你在十架为我裂破，<br/>流出你水和血，<br/>为将生命分赐与我，<br/>并为赎我罪孽。<br/>你的宝血将我洗净，<br/>使我蒙神喜悦；<br/>你的生命使我重生，<br/>叫我与你联结。<br/>','',54080,7615);
INSERT INTO stanza VALUES('Z94','3','你是一粒神圣麦子，<br/>结出许多子粒；<br/>我们与你同性、同质，<br/>成为你的身体。<br/>你是我们生命、内容，<br/>我们是你丰满；<br/>你借我们生活、行动，<br/>我们把你彰显。<br/>','',54081,7616);
INSERT INTO stanza VALUES('Z94','4','既是身体你可定居，<br/>就是你的居所；<br/>你在我们得到倚据，<br/>我们作你寄托。<br/>满足你心、怡悦你意，<br/>也是你的配偶；<br/>同你生活、与你一体，<br/>享受你的所有。<br/>','',54082,7617);
INSERT INTO stanza VALUES('Z94','5','我们在此擘饼记念，<br/>看到表记之物，<br/>心、灵不禁充满感赞，<br/>希奇你的救赎！<br/>你使我们作你身体，<br/>并你居所、配偶，<br/>我们只有一面感激，<br/>一面敬拜、歌讴！<br/>','',54083,7618);
INSERT INTO stanza VALUES('Z95','1','这个真是何等<br/>甘美的故事，<br/>神用无限的爱<br/>差遣祂儿子，<br/>来自天上荣耀，<br/>死于十字架，<br/>成功救赎，<br/>好使我们进神家。<br/>','',54084,7619);
INSERT INTO stanza VALUES('Z95','chorus','赞美祂！赞美祂！<br/>工作已经成功！<br/>感谢祂！感谢祂！<br/>恩典真宽宏！<br/>我们荣耀耶稣，<br/>我们的救主，<br/>我们歌唱耶稣，<br/>永远不止住。<br/>','',54085,7620);
INSERT INTO stanza VALUES('Z95','2','这个真是何等<br/>奇妙的故事，<br/>宝座要求，<br/>因着宝血就停止，<br/>公义审判，<br/>竟被神儿子担负，<br/>因此神就心满，<br/>罪人也意足。<br/>','',54086,7621);
INSERT INTO stanza VALUES('Z95','3','基督已登宝座，<br/>荣耀何光辉！<br/>耶稣已被高举，<br/>名字何尊贵！<br/>是的，我们救主，<br/>得华冠的主，<br/>配得所有圣徒<br/>永远的称祝。<br/>','',54087,7622);
INSERT INTO stanza VALUES('Z96','1','神的基督从天至，<br/>拯救罪人脱罪、死，<br/>竟然称为『忧患子！』<br/>阿利路亚！何等救主！<br/>','',54088,7623);
INSERT INTO stanza VALUES('Z96','2','被人侮慢被人讥，<br/>代替我站罪人地，<br/>赐我生命赐我力，<br/>阿利路亚！何等救主！<br/>','',54089,7624);
INSERT INTO stanza VALUES('Z96','3','我们又弱又不好，<br/>祂是圣洁的羊羔，<br/>救赎竟然作得到！<br/>阿利路亚！何等救主！<br/>','',54090,7625);
INSERT INTO stanza VALUES('Z96','4','祂被举起，我免死；<br/>祂说成了，鬼失势；<br/>祂登宝座给恩赐。<br/>阿利路亚！何等救主！<br/>','',54091,7626);
INSERT INTO stanza VALUES('Z96','5','当祂复临遣天使，<br/>提接圣徒见祂时，<br/>我们还要唱此诗：<br/>阿利路亚！何等救主！<br/>','',54092,7627);
INSERT INTO stanza VALUES('Z97','1','加略山巅救主丧命，<br/>在彼受辱、在彼被钉；<br/>为我赎罪、为我流血，<br/>买来赦免、立了新约。<br/>','',54093,7628);
INSERT INTO stanza VALUES('Z97','chorus','惨哉加略！痛哉加略！<br/>在彼耶稣为我流血；<br/>大哉加略！福哉加略！<br/>在彼救主为我命绝。<br/>','',54094,7629);
INSERT INTO stanza VALUES('Z97','2','磐石崩裂，天地昏暗，<br/>主喊成了，垂首气断；<br/>殿幔中裂，活路开通，<br/>我得近神，蒙恩无穷。<br/>','',54095,7630);
INSERT INTO stanza VALUES('Z97','3','哦主耶稣，怎会这样-<br/>为我你竟甘心受戕？<br/>身悬木架受神责谴！<br/>在那惨痛加略山巅！<br/>','',54096,7631);
INSERT INTO stanza VALUES('Z98','1','颂赞声音何等难得！<br/>所以应当无间时刻；<br/>如果我们自甘缄默，<br/>石头也要说话相责。<br/>','',54097,7632);
INSERT INTO stanza VALUES('Z98','2','我们应当高声颂美<br/>那用己血买我们的；<br/>祂替我们备尝死味，<br/>祂为我们费尽心力。<br/>','',54098,7633);
INSERT INTO stanza VALUES('Z98','3','此世有一特别诗歌，<br/>惟独蒙恩罪人会唱；<br/>此外无人懂那音乐，<br/>因不知其意义之纲。<br/>','',54099,7634);
INSERT INTO stanza VALUES('Z98','4','天使虽能欢然承认<br/>怜悯如何由血洞晓，<br/>但是他们不像我们，<br/>能以证明这血功效。<br/>','',54100,7635);
INSERT INTO stanza VALUES('Z98','5','天使虽能赞美拜朝，<br/>说神是神，向神恭敬；<br/>我们却能欢乐唱道：<br/>祂在宝座还带人性！<br/>','',54101,7636);
INSERT INTO stanza VALUES('Z98','6','哦主，我们赞美那使<br/>你来流血受死的爱；<br/>但愿不久在天相值，<br/>向你赞美、向你敬拜。<br/>','',54102,7637);
INSERT INTO stanza VALUES('Z99','1','祂躺卧在坟墓，<br/>耶稣我救主！<br/>静待晨光重睹。<br/>耶稣我主！<br/>','',54103,7638);
INSERT INTO stanza VALUES('Z99','chorus','祂从坟墓已起来，<br/>胜过仇敌，大大的奏凯，<br/>祂从黑域起来，<br/>祂是得胜者，活着掌权，<br/>同祂众圣徒联合。<br/>祂起来！祂起来！<br/>阿利路亚！主起来！<br/>','',54104,7639);
INSERT INTO stanza VALUES('Z99','2','兵丁徒然看守，<br/>耶稣我救主！<br/>石头徒然封口，<br/>耶稣我主！<br/>','',54105,7640);
INSERT INTO stanza VALUES('Z99','3','死亡无法锁关，<br/>耶稣我救主！<br/>祂已打断栅栏，<br/>耶稣我主！<br/>','',54106,7641);
INSERT INTO stanza VALUES('Z100','1','主已复活，<br/>死的审判已过；<br/>在祂里面，<br/>死亡难再淹没。<br/>主已复活，<br/>我今不再定罪；<br/>祂的空墓作证最具权威。<br/>','',54107,7642);
INSERT INTO stanza VALUES('Z100','2','主已复活，<br/>我也同祂复活；<br/>在祂墓中，<br/>仇敌全都埋没。<br/>主已复活，<br/>我得脱离死寨；<br/>在祂里面，<br/>复活生命倚赖。<br/>','',54108,7643);
INSERT INTO stanza VALUES('Z100','3','主已复活，<br/>我已得蒙拯救，<br/>今在旷野跟祂脚踪行走。<br/>主已复活，<br/>我得进至圣所，<br/>与祂一同在神面光生活。<br/>','',54109,7644);
INSERT INTO stanza VALUES('Z100','4','主已复活，<br/>作了幔内先锋，<br/>使我营外来作祂的见证。<br/>主已复活，<br/>我要高唱凯歌：<br/>『你已得胜！<br/>你民已脱捆索！』<br/>','',54110,7645);
INSERT INTO stanza VALUES('Z101','1','基督复活！阿利路亚！<br/>得胜的主已复活；<br/>向祂高歌，阿利路亚！<br/>基督死过又活着。<br/>我心感戴，向祂敬拜，<br/>因祂面光又重显；<br/>祂前俯伏，欢乐奏凯，<br/>胜过痛苦与忧患。<br/>','',54111,7646);
INSERT INTO stanza VALUES('Z101','chorus','基督复活！阿利路亚！<br/>得胜的主已复活；<br/>向祂高歌，阿利路亚！<br/>基督死过又活着。<br/>','',54112,7647);
INSERT INTO stanza VALUES('Z101','2','基督复活！何等欢欣！<br/>地上艰苦都过去；<br/>经过欢乐敞开之门，<br/>祂又回到生命域；<br/>死亡阴间全都征服，<br/>复活作了得胜者；<br/>天使观看祂的步武，<br/>荣冕戴祂伤过额。<br/>','',54113,7648);
INSERT INTO stanza VALUES('Z101','3','基督复活，何等超脱！<br/>死亡、阴间难困我；<br/>我属基督，凭祂活着，<br/>一切就都全胜过；<br/>所有疑惑、一切颓丧，<br/>从我栗心全止息；<br/>复活之日应该欢畅，<br/>兴起来赴这筵席。<br/>','',54114,7649);
INSERT INTO stanza VALUES('Z102','1','救主基督已复活，<br/>阿利路亚！<br/>死亡捆索全解脱，<br/>阿利路亚！<br/>天使赞美乐欢腾，<br/>阿利路亚！<br/>罪人蒙恩也响应，<br/>阿利路亚！<br/>','',54115,7650);
INSERT INTO stanza VALUES('Z102','2','祂从阴间已脱出，<br/>阿利路亚！<br/>死阿！你钩在何处？<br/>阿利路亚！<br/>祂曾死过又复生，<br/>阿利路亚！<br/>坟墓！你今有何能？<br/>阿利路亚！<br/>','',54116,7651);
INSERT INTO stanza VALUES('Z102','3','祂曾死过救赎成，<br/>阿利路亚！<br/>毁灭仇敌胜利赢，<br/>阿利路亚！<br/>死亡不能拘禁祂，<br/>阿利路亚！<br/>祂升高天仇敌踏，<br/>阿利路亚！<br/>','',54117,7652);
INSERT INTO stanza VALUES('Z102','4','我们与祂同复活，<br/>阿利路亚！<br/>与祂高升天上坐，<br/>阿利路亚！<br/>与祂一样的高昂，<br/>阿利路亚！<br/>脱开地上诸捆绑，<br/>阿利路亚！<br/>','',54118,7653);
INSERT INTO stanza VALUES('Z103','1','我的代替未见归回，<br/>我怎能够放心无虑；<br/>会否我罪将祂连累，<br/>未能救我，祂倒被拘？<br/>','',54119,7654);
INSERT INTO stanza VALUES('Z103','2','能否是因我的罪孽，<br/>太大、过多、无法赦免？<br/>能否是因祂的宝血，<br/>能力有限、包括不全？<br/>','',54120,7655);
INSERT INTO stanza VALUES('Z103','3','欢呼！耶稣已经复活，<br/>未损毫发，只增荣耀；<br/>祂虽进入黑暗处所，<br/>黑暗未曾留下功效。<br/>','',54121,7656);
INSERT INTO stanza VALUES('Z103','4','主得归回，就是凭据，<br/>神的公义已得满足，<br/>神的大爱仍施怜恤，<br/>主是已经完成救赎。<br/>','',54122,7657);
INSERT INTO stanza VALUES('Z103','5','神用复活答复流血，<br/>承认流血所成救赎；<br/>阿利路亚，我已清洁！<br/>阿利路亚，我得饶恕！<br/>','',54123,7658);
INSERT INTO stanza VALUES('Z104','1','哦主，死的领土<br/>你曾去走；<br/>非因罪将你毒，<br/>死有要求。<br/>掌死权的魔鬼，<br/>你已完全摧毁，<br/>使他不再作祟，<br/>将人监囚。<br/>','',54124,7659);
INSERT INTO stanza VALUES('Z104','2','你已冲破坟墓，<br/>从死复活；<br/>死难将你拘束，<br/>反被胜过！<br/>你已得胜走出<br/>幽冥、黑暗之墓，<br/>死荫全都破除，<br/>从死超脱。<br/>','',54125,7660);
INSERT INTO stanza VALUES('Z104','3','何等大能得胜<br/>你已得到！<br/>结果何其丰盛，<br/>将神荣耀！<br/>从你死中生出<br/>无数活的信徒，<br/>给你安家居住，<br/>凭你活着。<br/>','',54126,7661);
INSERT INTO stanza VALUES('Z104','4','你是初熟果子，<br/>我们爱戴；<br/>作神心爱长子，<br/>将我领率。<br/>凡事你居首位，<br/>是我永远所归，<br/>配得荣耀、尊贵，<br/>配得敬拜。<br/>','',54127,7662);
INSERT INTO stanza VALUES('Z105','1','阿利路亚，<br/>『祂已复活！』<br/>基督已经高天升！<br/>死的门闩已经断开，<br/>天使欢呼，人响应；<br/>祂已复活，祂已复活，<br/>祂今活着作生命。<br/>祂已复活，祂已复活，<br/>祂今活着作生命。<br/>','',54128,7663);
INSERT INTO stanza VALUES('Z105','2','阿利路亚，祂已复活！<br/>作我高举的元首！<br/>赐下圣灵来作见证，<br/>将祂一切向我授；<br/>祂已复活，祂已复活，<br/>使我称义蒙拯救。<br/>','',54129,7664);
INSERT INTO stanza VALUES('Z105','3','阿利路亚，祂已复活！<br/>死亡永远失权势！<br/>基督自己就是复活，<br/>要救我们脱离死；<br/>祂已复活，祂已复活，<br/>一直活着作恩赐。<br/>','',54130,7665);
INSERT INTO stanza VALUES('Z106','1','荣耀归于你，<br/>复活得胜子，<br/>你已永远得胜，<br/>你已胜过死；<br/>天使身穿白衣，<br/>辊开坟墓石，<br/>凭着你的空墓，<br/>你复活启示。<br/>','',54131,7666);
INSERT INTO stanza VALUES('Z106','chorus','荣耀归于你，<br/>复活得胜子，<br/>你已永远得胜，<br/>你已胜过死。<br/>','',54132,7667);
INSERT INTO stanza VALUES('Z106','2','看！复活基督，<br/>与我们相见；<br/>祂那可爱问安，<br/>驱尽惧与暗；<br/>但愿召会欢乐，<br/>高唱得胜诗，<br/>因主现在活着，<br/>死已失权势。<br/>','',54133,7668);
INSERT INTO stanza VALUES('Z106','3','不再怀疑你，<br/>荣耀生命王；<br/>无你就无生命，<br/>有你胜死亡。<br/>使我得胜有余，<br/>靠复活大能，<br/>直到进入国度，<br/>不再有战争。<br/>','',54134,7669);
INSERT INTO stanza VALUES('Z107','1','耶稣已经出墓来，<br/>死亡对祂毫无害；<br/>我们应当相安慰，<br/>将祂的名同赞美。<br/>救赎工作今作成，<br/>与敌交战已得胜。<br/>赎罪一次就清楚，<br/>祂并不用多受苦。<br/>','',54135,7670);
INSERT INTO stanza VALUES('Z107','2','封墓、设兵、空画策，<br/>阴府对祂无奈何；<br/>我主暂时虽受苦，<br/>但祂使我得永福。<br/>祂已死过不再死，<br/>撒但计穷无可施；<br/>我既看见一墓空，<br/>就知万墓必相同。<br/>','',54136,7671);
INSERT INTO stanza VALUES('Z107','3','一粒麦子已死了，<br/>今日万粒都生苗；<br/>当日不过只一位，<br/>今日已变全召会。<br/>我们是祂的身体，<br/>头既上升肢继起；<br/>与祂同葬、同升天，<br/>赞美祂名亿万年。<br/>','',54137,7672);
INSERT INTO stanza VALUES('Z108','1','神的基督、亲爱救主，<br/>我们向你歌唱；<br/>你曾流血、成功救赎，<br/>福杯我们得尝。<br/>你用大能已将敌剿，<br/>今登天上宝座；<br/>还要将我带进荣耀，<br/>进入你的天国。<br/>','',54138,7673);
INSERT INTO stanza VALUES('Z108','2','神的基督、亲爱救主，<br/>我们向你歌唱；<br/>你已进攻死的领土，<br/>掳掠死的君王。<br/>尘下之屋难再困扰，<br/>死的权势已黜；<br/>你手拿着死亡锁钥，<br/>掌管阴府、坟墓。<br/>','',54139,7674);
INSERT INTO stanza VALUES('Z108','3','神的基督、亲爱救主，<br/>我们向你歌唱；<br/>你借十架已经剪除<br/>今世背叛君王，<br/>并借你的生命大能，<br/>投入黑暗阴府，<br/>扫荡黑暗，胜过幽冥，<br/>释放死的囚奴。<br/>','',54140,7675);
INSERT INTO stanza VALUES('Z108','4','神的基督、亲爱救主，<br/>永远向你歌唱；<br/>你是永远得胜的主，<br/>将我永远释放。<br/>你是神的拯救能力，<br/>使我完全自由；<br/>荣耀归神并你自己，<br/>从今直到永久。<br/>','',54141,7676);
INSERT INTO stanza VALUES('Z109','1','赞美、赞美基督得胜！<br/>赞美基督已得胜！<br/>罪孽赎清，旧人同钉，<br/>救赎大功已完成！<br/>毁坏撒但，掳掠邪灵，<br/>仗着十架而夸胜！<br/>','',54142,7677);
INSERT INTO stanza VALUES('Z109','2','赞美、赞美基督复生！<br/>赞美基督已复生！<br/>吞灭死亡顽强权能，<br/>使人出死而入生！<br/>冲破阴府残忍幽冥，<br/>显出复活的大能！<br/>','',54143,7678);
INSERT INTO stanza VALUES('Z109','3','赞美、赞美基督高升！<br/>赞美基督已高升！<br/>远超宇宙一切首领，<br/>得着至高的尊名！<br/>领得天地所有权柄，<br/>等候仇敌作脚凳！<br/>','',54144,7679);
INSERT INTO stanza VALUES('Z109','4','阿利路亚，基督得胜！<br/>阿利路亚，已得胜！<br/>阿利路亚，基督复生！<br/>阿利路亚，已复生！<br/>阿利路亚，基督高升！<br/>阿利路亚，已高升！<br/>','',54145,7680);
INSERT INTO stanza VALUES('Z110','1','听哪，千万声音雷鸣，<br/>同声高举神羔羊；<br/>万万千千立即响应，<br/>和声爆发同颂扬。<br/>','',54146,7681);
INSERT INTO stanza VALUES('Z110','2','『赞美羔羊！』<br/>声音四合，<br/>全天会集来歌诵，<br/>万口莫不响亮协和，<br/>宇宙充满救主颂。<br/>','',54147,7682);
INSERT INTO stanza VALUES('Z110','3','这样感激心香如缕，<br/>永向父的宝座去；<br/>万膝莫不向子屈曲，<br/>天上心意真一律。<br/>','',54148,7683);
INSERT INTO stanza VALUES('Z110','4','子所有的一切光辉，<br/>使父荣耀得发挥；<br/>父所有的一切智慧，<br/>宣告子是同尊贵。<br/>','',54149,7684);
INSERT INTO stanza VALUES('Z110','5','借着圣灵无往不透，<br/>天人无数都无求，<br/>围着羔羊，<br/>俯伏拜叩，<br/>称颂祂作『自永有。』<br/>','',54150,7685);
INSERT INTO stanza VALUES('Z110','6','现今新造何等满足、<br/>安息、喜乐并稳固，<br/>因着祂的救恩受福，<br/>不再受缚，不再苦。<br/>','',54151,7686);
INSERT INTO stanza VALUES('Z110','7','听哪，天上又发歌声，<br/>赞美声音又四震，<br/>穹苍之中满了阿们！<br/>『阿们』因是同蒙恩。<br/>','',54152,7687);
INSERT INTO stanza VALUES('Z111','1','神的儿子、亲爱救主，<br/>你曾用你宝血救赎<br/>我们脱死和罪；<br/>你的圣徒欢乐看见：<br/>现今你戴荣耀冠冕，<br/>并登天上座位。<br/>并登天上座位。<br/>','',54153,7688);
INSERT INTO stanza VALUES('Z111','2','父的爱心将你高升，<br/>赐你荣耀、尊贵、权能。<br/>使你坐祂右边；<br/>现今颂赞、智慧、丰富，<br/>完全属你，亲爱救主！<br/>你的年日无限。<br/>','',54154,7689);
INSERT INTO stanza VALUES('Z111','3','召会的头，你坐那里，<br/>赐福给你所有肢体，<br/>你的是我们的：<br/>你是我们生命、能力，<br/>你使我们坚定站立，<br/>胜过一切仇敌。<br/>','',54155,7690);
INSERT INTO stanza VALUES('Z111','4','荣耀日子不久来临，<br/>你的新妇就要上升，<br/>鉴赏你的美丽。<br/>何等可乐！看见了你，<br/>听见你认我们属你，<br/>并永同你安息。<br/>','',54156,7691);
INSERT INTO stanza VALUES('Z112','1','看那胜者奏凯上升，<br/>带着君王的尊荣，<br/>乘驾彩云当祂车辇，<br/>归回天上的王宫；<br/>听阿，天使合声歌唱<br/>阿利路亚的颂扬，<br/>天上城门头全抬起，<br/>欢迎祂，欢迎祂，<br/>欢迎他们天国王。<br/>','',54157,7692);
INSERT INTO stanza VALUES('Z112','2','是谁带着荣耀而来，<br/>配上禧年的号声？<br/>争战之主、万军之神，<br/>祂在战场已得胜。<br/>祂已忍受十架苦难，<br/>且从坟墓已复起；<br/>祂已除灭罪与撒但，<br/>借着死，借着死，<br/>借着祂死毁仇敌。<br/>','',54158,7693);
INSERT INTO stanza VALUES('Z112','3','正在举手祝福之时，<br/>祂就离地往上升；<br/>当祂门徒正在看祂，<br/>祂就被接去天庭。<br/>与神同行，使神喜悦，<br/>传过真理与审判；<br/>我的以诺被神取去，<br/>得进到，得进到，<br/>得以进到神面前。<br/>','',54159,7694);
INSERT INTO stanza VALUES('Z112','4','我的亚伦进入圣所，<br/>带着祂血进幔内；<br/>我约书亚进入迦南，<br/>众王祂前都败退；<br/>祂将我们神的选民，<br/>栽植应许的美地；<br/>我以利亚现今赐下<br/>双倍福，双倍福，<br/>双倍属天的福气。<br/>','',54160,7695);
INSERT INTO stanza VALUES('Z112','5','祂已提高我们人性，<br/>将人带到神右边；<br/>我们与祂同坐天上，<br/>与祂同在荣耀间。<br/>耶稣作王，天使敬拜，<br/>人竟与神同宝座；<br/>大能的主，凭你升天，<br/>我相信，我相信，<br/>相信升天必得着。<br/>','',54161,7696);
INSERT INTO stanza VALUES('Z113','1','何等权能！耶稣尊名！<br/>天使全都俯伏，<br/>献上冠冕，同心尊敬<br/>祂作万有之主，<br/>献上冠冕，同心尊敬<br/>祂作万有之主。<br/>','',54162,7697);
INSERT INTO stanza VALUES('Z113','2','你们历代殉道众圣，<br/>要从祭坛欢呼，<br/>同声高举耶西的根，<br/>祂是万有之主。<br/>','',54163,7698);
INSERT INTO stanza VALUES('Z113','3','你们被赎亚当后代，<br/>出身『堕落』圣徒，<br/>蒙恩得救，应当敬拜<br/>祂作万有之主。<br/>','',54164,7699);
INSERT INTO stanza VALUES('Z113','4','罪人，你心永不能忘<br/>祂的苦胆、酸醋，<br/>今当到祂面前瞻望<br/>祂这万有之主<br/>','',54165,7700);
INSERT INTO stanza VALUES('Z113','5','但愿地上万族万民<br/>都向救主欢呼，<br/>荣耀、尊贵，都归祂名，<br/>祂是万有之主。<br/>','',54166,7701);
INSERT INTO stanza VALUES('Z113','6','亿万群众歌声雷动，<br/>我也一同俯伏，<br/>直到永远敬拜称颂<br/>祂作万有之主。<br/>','',54167,7702);
INSERT INTO stanza VALUES('Z114','1','看哪，冠冕已给羊羔！<br/>荣耀、尊贵已归祂！<br/>为祂无处算是太高，<br/>天上无处是太大。<br/>天上无处是太大。<br/>','',54168,7703);
INSERT INTO stanza VALUES('Z114','2','祂登宝座-天上宝座，<br/>祂登宝座何豪迈！<br/>祂是题目，圣徒所歌，<br/>祂是珍物，父所爱。<br/>','',54169,7704);
INSERT INTO stanza VALUES('Z114','3','祂虽高大，却肯接受<br/>我们在此的殷勤；<br/>我们所有微声弱讴，<br/>无一不入救主心。<br/>','',54170,7705);
INSERT INTO stanza VALUES('Z114','4','我的诗歌，惟独就是<br/>高举被杀的羔羊，<br/>并那坐在宝座上的，<br/>如何应当受颂扬。<br/>','',54171,7706);
INSERT INTO stanza VALUES('Z114','5','从前那受人藐视的，<br/>今得荣耀和尊贵；<br/>冠冕、高位，原是祂的，<br/>祂得这些真无愧！<br/>','',54172,7707);
INSERT INTO stanza VALUES('Z115','1','看哪，耶稣天上坐着！<br/>我主基督登宝座！<br/>祂是那人神所高举，<br/>荣耀、尊贵已得着。<br/>','',54173,7708);
INSERT INTO stanza VALUES('Z115','2','祂曾穿上人的性情，<br/>照神计画且死过，<br/>带着身体从死复活，<br/>仍然是人升天坐。<br/>','',54174,7709);
INSERT INTO stanza VALUES('Z115','3','在祂里面神降为卑，<br/>神来地上同人处；<br/>在祂里面人升为高，<br/>人到天上同神住。<br/>','',54175,7710);
INSERT INTO stanza VALUES('Z115','4','祂是真神与人调和，<br/>神在人里被宣告；<br/>祂是真人与神联合，<br/>人在神里得荣耀。<br/>','',54176,7711);
INSERT INTO stanza VALUES('Z115','5','从那升天得荣耶稣，<br/>降下包罗万有灵；<br/>耶稣身位和祂工作，<br/>全由这灵来证明。<br/>','',54177,7712);
INSERT INTO stanza VALUES('Z115','6','和那升天得荣耶稣，<br/>今天召会能联合；<br/>借着这位耶稣的灵，<br/>基督肢体能同活。<br/>','',54178,7713);
INSERT INTO stanza VALUES('Z115','7','看哪，一人天上坐着！<br/>万有之主在宝座！<br/>这是救主耶稣基督，<br/>荣耀、尊贵永得着！<br/>','',54179,7714);
INSERT INTO stanza VALUES('Z116','1','哦主耶稣，我心喜乐，<br/>因你为我所历坎坷，<br/>现今已经过去；<br/>你的工作都已得胜，<br/>你今就是坐享其成，<br/>被神荣耀高举。<br/>','',54180,7715);
INSERT INTO stanza VALUES('Z116','2','你的圣首曾被芒刺，<br/>现今已得荣冕装饰，<br/>并坐父的座位。<br/>哦主，我们真赞美你，<br/>我们永要虔诚拜礼，<br/>并说：惟你是配！<br/>','',54181,7716);
INSERT INTO stanza VALUES('Z116','3','你在那里是作元首，<br/>等你肢体也同接受<br/>你所有的一切-<br/>你的荣耀和你宝座、<br/>你的权柄和你天国，<br/>因为你我联结。<br/>','',54182,7717);
INSERT INTO stanza VALUES('Z116','4','主，你快乐，我们也乐，<br/>因你得胜我们唱歌，<br/>因为你我合一；<br/>现今在此受苦任劳，<br/>何等欢欣，当我想到<br/>宝座是属于你。<br/>','',54183,7718);
INSERT INTO stanza VALUES('Z117','1','救主已登宝座，<br/>远超一切；<br/>羔羊已得冠冕，<br/>荣耀超绝。<br/>祂要永远活着，<br/>永远超越；<br/>神已将祂高举，<br/>远超一切。<br/>','',54184,7719);
INSERT INTO stanza VALUES('Z117','chorus','远超一切！远超一切！<br/>那被钉的耶稣远超一切！<br/>在祂脚凳之前，<br/>敬拜不歇，<br/>神已将祂高举，<br/>远超一切！<br/>','',54185,7720);
INSERT INTO stanza VALUES('Z117','2','当那狂风大作，<br/>洪涛翻腾，<br/>想要将我淹没，<br/>逞凶肆能，<br/>我向救主仰望，<br/>祂就拯救，<br/>踏着风波行走，<br/>平安无忧。<br/>','',54186,7721);
INSERT INTO stanza VALUES('Z117','3','我要进攻之城<br/>虽然高大，<br/>障碍虽也有力，<br/>要我停下，<br/>仍要无惧向前，<br/>一一解决，<br/>坚定相信祂是<br/>远超一切。<br/>','',54187,7722);
INSERT INTO stanza VALUES('Z117','4','看哪！全地都是<br/>祂的国度，<br/>远超一切，<br/>万有无不归服；<br/>所有的得胜者，<br/>无一或缺，<br/>都要与祂一同<br/>远超一切。<br/>','',54188,7723);
INSERT INTO stanza VALUES('Z118','1','从前那戴荆棘的头，<br/>今戴荣耀冠冕；<br/>救主耶稣，我们元首，<br/>你今已升高天。<br/>','',54189,7724);
INSERT INTO stanza VALUES('Z118','2','你是地上圣徒之乐，<br/>你是天上之光；<br/>你今领我饮于爱河，<br/>使我知其深广。<br/>','',54190,7725);
INSERT INTO stanza VALUES('Z118','3','主，将你的羞辱、权柄，<br/>一并赐给我们；<br/>地虽否认你的微名，<br/>神却使你高升。<br/>','',54191,7726);
INSERT INTO stanza VALUES('Z118','4','凡肯与你在世同苦，<br/>也要同荣在天，<br/>所以求主使我坚固，<br/>鄙视世界恩典。<br/>','',54192,7727);
INSERT INTO stanza VALUES('Z118','5','十架于你虽是辱、死，<br/>在我却是生命！<br/>也是我的荣耀、权势！<br/>我的永远安宁！<br/>','',54193,7728);
INSERT INTO stanza VALUES('Z119','1','荣耀、荣耀、永远荣耀，<br/>归给登极的基督；<br/>荣耀、荣耀、永远荣耀，<br/>归给高举的救主。<br/>祂已得着至高尊名，<br/>天上地下都颂称；<br/>荣耀、荣耀、永远荣耀，<br/>归给祂这至尊名。<br/>','',54194,7729);
INSERT INTO stanza VALUES('Z119','2','原在天上荣耀宝座，<br/>与神同等、居天庭；<br/>竟然卑取奴仆形状，<br/>历尽地上苦人生：<br/>顺服父旨从不偏离，<br/>甚至顺服到死地；<br/>十字架上死的羞辱，<br/>甘愿受尽无所遗。<br/>','',54195,7730);
INSERT INTO stanza VALUES('Z119','3','天上冠冕，光明、荣耀，<br/>今已归那降卑人；<br/>天上佳袍，华丽、灿烂，<br/>今已穿在祂荣身。<br/>因祂尊名无不屈膝，<br/>无不口称祂为主；<br/>天地之主、普世之王，<br/>亿兆都将祂称祝。<br/>','',54196,7731);
INSERT INTO stanza VALUES('Z119','4','荣耀、荣耀、永远荣耀，<br/>归那无价的至宝；<br/>荣耀在天、荣耀在地，<br/>全都归祂作荣耀。<br/>荣耀归神、归给我神、<br/>归给至大的『我是；』<br/>荣耀、荣耀、永远荣耀，<br/>一直归祂到永世。<br/>','',54197,7732);
INSERT INTO stanza VALUES('Z120','1','哦主，你是万有的主，<br/>已得荣耀冠冕；<br/>因你权柄和你威严，<br/>万众将你称赞。<br/>','',54198,7733);
INSERT INTO stanza VALUES('Z120','2','神在人里活在地上，<br/>曾经成为奴仆；<br/>人在神里住在天上，<br/>尊为万有之主。<br/>','',54199,7734);
INSERT INTO stanza VALUES('Z120','3','你是那人在荣耀里，<br/>与神同坐宝座；<br/>天上地上所有权柄，<br/>全都归你得着。<br/>','',54200,7735);
INSERT INTO stanza VALUES('Z120','4','升上高天，得被高举，<br/>且得至高尊名；<br/>万口无不称你为主，<br/>万膝无不跪敬。<br/>','',54201,7736);
INSERT INTO stanza VALUES('Z120','5','神已使你作主基督，<br/>圣灵如此证明；<br/>在荣耀里，并在天上，<br/>得着宝座、权柄。<br/>','',54202,7737);
INSERT INTO stanza VALUES('Z120','6','荣耀之主，我们敬拜，<br/>高声向你赞美；<br/>万有之主，我们高举，<br/>赞美惟你是配！<br/>','',54203,7738);
INSERT INTO stanza VALUES('Z121','1','看哪，何等荣耀情景，<br/>忧患之子得荣耀！<br/>祂从战场凯旋乘胜，<br/>荣耀之中登大宝！<br/>加冠于祂、加冠于祂、<br/>加冠王中的至高。<br/>','',54204,7739);
INSERT INTO stanza VALUES('Z121','2','人曾戏弄，给祂加冠，<br/>荆棘冠冕给祂戴；<br/>祂今得着荣耀冠冕，<br/>天使、圣徒都敬拜。<br/>加冠于祂、加冠于祂、<br/>加冠神心所宝爱。<br/>','',54205,7740);
INSERT INTO stanza VALUES('Z121','3','加冠救主、罪人加冠，<br/>你是祂的胜利品；<br/>当着穹苍正在腾欢，<br/>让祂登极在你心。<br/>加冠于祂、加冠于祂、<br/>加冠罪魁的恩人。<br/>','',54206,7741);
INSERT INTO stanza VALUES('Z121','4','听哪！群众喝采、欢呼！<br/>听哪！胜利的高歌！<br/>耶稣升到最高之处，<br/>此景令人何欢乐！<br/>加冠于祂、加冠于祂、<br/>加冠于那至高者！<br/>','',54207,7742);
INSERT INTO stanza VALUES('Z122','1','我们的灵伏着注视<br/>在荣耀里的耶稣，<br/>我们在彼读祂故事，<br/>如何在世受羞辱。<br/>','',54208,7743);
INSERT INTO stanza VALUES('Z122','2','你的圣首满了羞辱，<br/>世人竟然大欢畅；<br/>今日荣耀反面说出：<br/>当日你心的忧伤。<br/>','',54209,7744);
INSERT INTO stanza VALUES('Z122','3','当你挂在十字架时，<br/>孤单被弃无人怜；<br/>众圣今则向你唱诗，<br/>你则高升到父前。<br/>','',54210,7745);
INSERT INTO stanza VALUES('Z122','4','神曾不顾你的无告！<br/>神曾离弃你不瞧！<br/>我们从你憔悴面貌，<br/>现今看见父荣耀。<br/>','',54211,7746);
INSERT INTO stanza VALUES('Z122','5','宝贵的主！注视这个，<br/>我们不禁要赞美；<br/>但愿天地同心唱和：<br/>『神的羔羊，你是配。』<br/>','',54212,7747);
INSERT INTO stanza VALUES('Z122','6','我们的心应当起来，<br/>即今起来赞美父；<br/>但愿歌颂、欢呼、爱戴，<br/>归给父子到永古。<br/>','',54213,7748);
INSERT INTO stanza VALUES('Z123','1','神的基督、荣耀的主，<br/>你的心慈、你恩溥！<br/>我们现在全魂、全心，<br/>到你面前来朝觐；<br/>我敬拜你、赞美你，<br/>你的道路无可比！<br/>','',54214,7749);
INSERT INTO stanza VALUES('Z123','2','受膏的王、一切的主，<br/>进入荣耀得万福！<br/>前曾被人讥笑、厌弃，<br/>你欲救人，人绝你；<br/>我敬爱你、称颂你，<br/>今得尊荣至无极。<br/>','',54215,7750);
INSERT INTO stanza VALUES('Z123','3','你曾死过，生命的主，<br/>祝福人者竟受诅！<br/>你是父神所爱所重，<br/>竟受苦难学顺从；<br/>我仰望你、记念你，<br/>为我亲历忧患地。<br/>','',54216,7751);
INSERT INTO stanza VALUES('Z123','4','不久华冠将加你首，<br/>不久铁杖操你手！<br/>神的基督，我们现今<br/>等候你从天降临；<br/>我敬爱你、顺服你，<br/>永远认你为基督。<br/>','',54217,7752);
INSERT INTO stanza VALUES('Z124','1','主，你乃是王中王，<br/>我们何人不归向？<br/>神的受膏我敬拜，<br/>衷心敬畏又爱戴！<br/>对你这位王中王，<br/>千万圣徒在颂扬<br/>','',54218,7753);
INSERT INTO stanza VALUES('Z124','2','全地这国到那国，<br/>无不由你来掌握！<br/>万民都要来归依，<br/>尊你为王，事奉你。<br/>对你这位王中王，<br/>万民有谁不颂扬！<br/>','',54219,7754);
INSERT INTO stanza VALUES('Z124','3','你的国度到永远，<br/>你的宝座永稳坚！<br/>对你荣耀和国权，<br/>我们永远要颂赞！<br/>对你这位王中王，<br/>千万圣徒要颂扬！<br/>','',54220,7755);
INSERT INTO stanza VALUES('Z124','4','亲爱救主、至高王，<br/>你的尊名我爱唱！<br/>你的统治何可亲，<br/>愿你国度早降临！<br/>但对你这王中王，<br/>在此我们就颂扬！<br/>','',54221,7756);
INSERT INTO stanza VALUES('Z125','1','主，你是神受膏者，<br/>你是万王之王！<br/>在此俯伏并敬拜，<br/>向你高声颂扬！<br/>你的国度无穷尽，<br/>你的宝座坚定！<br/>你的治理公而仁，<br/>荣耀无可抗衡。<br/>','',54222,7757);
INSERT INTO stanza VALUES('Z125','2','在那锡安圣山上，<br/>神已将你立定，<br/>并将列国赐给你，<br/>作你基业永恒。<br/>祂已将祂的权柄，<br/>完全委托于你，<br/>要你列国全管治，<br/>直到永世无已。<br/>','',54223,7758);
INSERT INTO stanza VALUES('Z125','3','日期尚未满足时，<br/>黑暗尚在掌权，<br/>仍有千万的群众，<br/>向你忠贞颂赞！<br/>大洋这岸到那岸，<br/>你民向你歌唱；<br/>敬拜、爱戴、事奉你，<br/>作彼救主-君王！<br/>','',54224,7759);
INSERT INTO stanza VALUES('Z125','4','等到豫定的日子，<br/>你要荣中降临，<br/>地和其上的列国，<br/>都要向你归顺。<br/>满了光辉和威严，<br/>你要被尊为王，<br/>各族、各民和各国，<br/>都要将你颂扬！<br/>','',54225,7760);
INSERT INTO stanza VALUES('Z126','1','我的救主，你爱为何<br/>这挚！这宽！这博！<br/>不然，<br/>我心、我命、我力，<br/>那肯完全归你！<br/>','',54226,7761);
INSERT INTO stanza VALUES('Z126','2','我们爱你，因你自己<br/>上下千秋无匹；<br/>我们爱你，因你忍受<br/>十字架的耻羞。<br/>','',54227,7762);
INSERT INTO stanza VALUES('Z126','3','人爱所夸，不过就是<br/>代友受死的事；<br/>但你却为仇敌被杀！<br/>谁曾如此爱法？<br/>','',54228,7763);
INSERT INTO stanza VALUES('Z126','4','虽然你有神的形像，<br/>安居荣耀天乡；<br/>但你却来成为奴仆，<br/>亲历忧患、痛苦。<br/>','',54229,7764);
INSERT INTO stanza VALUES('Z126','5','你愿凡事都像世人，<br/>（除了罪恶无分，）<br/>好叫我们完全像你，<br/>虽然前此不一。<br/>','',54230,7765);
INSERT INTO stanza VALUES('Z126','6','像你温柔、像你坚刚<br/>、像你在凡事上！<br/>荣上加荣，天天更变，<br/>直到与你相见。<br/>','',54231,7766);
INSERT INTO stanza VALUES('Z126','7','我们的主，我们的心<br/>珍藏你的爱情；<br/>今后我们对你尊名，<br/>永要感激、恭敬。<br/>','',54232,7767);
INSERT INTO stanza VALUES('Z127','1','耶稣我主荣耀王，<br/>你爱何等宽广！<br/>甘离宝座，<br/>亲来世界寻迷羊，<br/>诞生马槽谦卑样，<br/>又向埃及逃亡，<br/>回加利利，居拿撒勒，<br/>历风霜；<br/>三十三载役于人，<br/>藐视、厌弃难当；<br/>广传福音，报告禧年，<br/>走四方；<br/>殷勤服事忍饥肠，<br/>困乏休息无床；<br/>美哉、善哉、主爱奇哉，<br/>深且长！<br/>','',54233,7768);
INSERT INTO stanza VALUES('Z127','2','耶稣我主救世王，<br/>你爱感我衷肠！<br/>客西马尼备极伤痛，<br/>意怆惶；<br/>汗如血点滴地上，<br/>顺从父旨不忘；<br/>舍身救世，面如坚石，<br/>前行壮；<br/>轻看羞辱和苦难，<br/>忍受罪人顶撞；<br/>背负十架，往各各他，<br/>不延宕；<br/>手足被钉，肋受伤，<br/>血、水流出命丧；<br/>美哉、善哉、主爱奇哉，<br/>深且长！<br/>','',54234,7769);
INSERT INTO stanza VALUES('Z127','3','耶稣我主得胜王，<br/>你爱何等无量！<br/>十架祈祷，怜悯为怀，<br/>心何广；<br/>同钉一贼得生望，<br/>可知救恩无疆；<br/>身负重罪，为神离弃，<br/>倍凄凉；<br/>痛彻肺腑，心焦渴，<br/>苦胆、酸醋亲尝；<br/>救赎功成，将灵交神，<br/>打胜仗；<br/>由死复活升天上，<br/>代祷犹如馨香；<br/>美哉、善哉、主爱奇哉，<br/>深且长！<br/>','',54235,7770);
INSERT INTO stanza VALUES('Z127','4','耶稣我主平安王，<br/>你爱岂能测量！<br/>我犹罪人，你已代死，<br/>爱明彰；<br/>洗我罪孽，医我伤，<br/>安慰、怜恤多方；<br/>责备、管教、定我步履、<br/>赐我光，<br/>敌虽凶恶不足惧，<br/>救恩为我城墙；<br/>疲乏、软弱，你加我力，<br/>使刚强；<br/>仰望我主在天上，<br/>心被恩感歌唱；<br/>美哉、善哉、主爱奇哉，<br/>深且长！<br/>','',54236,7771);
INSERT INTO stanza VALUES('Z128','1','我今俯伏主面前，<br/>我希奇主恩典！<br/>像我这样的罪魁，<br/>主竟拯救归回！<br/>我本罪人贪世福，<br/>那里想到要主；<br/>为何无端来寻我，<br/>用爱把我围着。<br/>','',54237,7772);
INSERT INTO stanza VALUES('Z128','2','当时我心因罪恶，<br/>纠缠得真难过，<br/>但我并未求解脱，<br/>你却前来寻我！<br/>当时我虽听见你，<br/>但我总是不理，<br/>并且多次反对你，<br/>实是你的仇敌。<br/>','',54238,7773);
INSERT INTO stanza VALUES('Z128','3','我实不知为何故，<br/>你竟为我罪辜，<br/>钉死在十字架上，<br/>使我得着平康！<br/>我的罪恶比人多，<br/>我为肉体活着，<br/>我的性情比人坏，<br/>你为甚么要爱？<br/>','',54239,7774);
INSERT INTO stanza VALUES('Z128','4','你生马槽何寒微！<br/>你的生活何卑！<br/>你到加略受折磨！<br/>你的全是为我！<br/>你在何处看上我？<br/>为何又爱上我？<br/>所以才如此受苦，<br/>为要使我得福？<br/>','',54240,7775);
INSERT INTO stanza VALUES('Z128','5','我比别人有何长？<br/>有何比人高尚？<br/>因此使你离天上，<br/>为我十架命丧？<br/>主阿，当我想自己，<br/>实在无一可以<br/>邀你青眼，使你喜，<br/>我就只得希奇！<br/>','',54241,7776);
INSERT INTO stanza VALUES('Z128','6','无他，我今只能说：<br/>你是无故爱我！<br/>哦，你是无故爱我！<br/>哦，这恩真难说！<br/>哦，不是因自己好，<br/>不是因自己高，<br/>乃是你要爱罪魁，<br/>无故的爱罪魁！<br/>','',54242,7777);
INSERT INTO stanza VALUES('Z128','7','我既如此的蒙恩，<br/>自然应当认真<br/>爱你、念你、顺服你，<br/>才可对得住你；<br/>但是，可怜到如今<br/>我心仍冷如冰！<br/>虽然明知你恩、爱，<br/>仍是对你懈怠！<br/>','',54243,7778);
INSERT INTO stanza VALUES('Z128','7','你虽为我舍性命，<br/>我对你仍无情；<br/>你虽为我离天庭，<br/>我对你只半心。<br/>隐藏世界离不得，<br/>你道路嫌太窄！<br/>微小自己舍不得，<br/>你生命苦太默！<br/>','',54244,7779);
INSERT INTO stanza VALUES('Z128','9','当我想到这里时，<br/>我心若有所失，<br/>自恨性情太败坏，<br/>自恨生活太歹。<br/>但是，主，你岂不知<br/>我心将要如此！<br/>你既豫知我冷淡，<br/>当初何必恩湛？<br/>','',54245,7780);
INSERT INTO stanza VALUES('Z128','10','难道你为我舍命，<br/>担当痛苦、罪、病，<br/>受尽人世的艰辛，<br/>就是为此冷心！<br/>你既知道我如此，<br/>何苦为我受死？<br/>你既知道我无良，<br/>何竟为我受伤？<br/>','',54246,7781);
INSERT INTO stanza VALUES('Z128','11','你虽豫知我冷淡，<br/>对你刻变时翻，<br/>但你仍然要爱我，<br/>为我死，为我活。<br/>当我想到这样爱，<br/>不知泪从何来，<br/>满心感激我救主，<br/>希奇你的无故！<br/>','',54247,7782);
INSERT INTO stanza VALUES('Z128','12','主阿，对于你大爱，<br/>我真明白不来，<br/>一面我希奇不迨，<br/>一面我要敬拜；<br/>天上福乐虽无比，<br/>我心并不在彼，<br/>我爱作个唱诗人，<br/>赞美我主我神。<br/>','',54248,7783);
INSERT INTO stanza VALUES('Z128','13','在那光明荣耀中，<br/>我要不住称颂，<br/>我要感谢你恩、爱，<br/>我要永远敬拜。<br/>我望我能在天城，<br/>作主恩、爱标本，<br/>爱虽难答，恩难报，<br/>惟愿赞美得好！<br/>','',54249,7784);
INSERT INTO stanza VALUES('Z129','1','我有一位奇妙救主，<br/>祂的爱情举世莫如，<br/>深海虽深，牠还要深，<br/>高天虽高，牠还要高；<br/>亦新、亦陈、<br/>又挚、又真，<br/>不分境地、不理晚早；<br/>祂爱我，赞美祂的名！<br/>','',54250,7785);
INSERT INTO stanza VALUES('Z129','2','祂在天上位分至尊，<br/>天使、天军无不拜顿，<br/>却因情爱非常坚强，<br/>以至愿意撇弃穹苍，<br/>来寻迷羊，<br/>并且受戕，<br/>舍了天福，又失世赏，<br/>祂寻我，赞美祂的名！<br/>','',54251,7786);
INSERT INTO stanza VALUES('Z129','3','祂的道路实在孤单，<br/>没有同心、没有同伴；<br/>祂的所有患难、忧愁，<br/>惟祂自己和神知道；<br/>但祂前走，<br/>不稍退后，<br/>直等祂到我的囚牢，<br/>祂见我，赞美祂的名！<br/>','',54252,7787);
INSERT INTO stanza VALUES('Z129','4','不久，悲惨日子就到：<br/>祂被人卖，祂被人告，<br/>祂就如此-零丁孤苦，<br/>头戴荆冕，身受鞭伤，<br/>为我之故，<br/>来髑髅处，<br/>忍辱、受死，疼痛独当，<br/>祂救我，赞美祂的名！<br/>','',54253,7788);
INSERT INTO stanza VALUES('Z129','5','一生一世，我要述说，<br/>祂的爱情超人能度，<br/>当我至终被提祂前，<br/>住在祂所豫备的城，<br/>我心所羡，<br/>是见祂面，<br/>并要敬拜，高声颂称，<br/>我爱祂，赞美祂的名！<br/>','',54254,7789);
INSERT INTO stanza VALUES('Z130','1','哦主，你爱何等深广！<br/>过于我所能测度！<br/>你爱深广，远超海洋！<br/>这爱竟然临及我！<br/>你爱叫你舍了自己，<br/>为要叫我得着你，<br/>你爱叫你与我合一，<br/>叫我成为你肢体。<br/>','',54255,7790);
INSERT INTO stanza VALUES('Z130','2','你爱所给、所作太多！<br/>过于我所能述说！<br/>最大乃是与我联合，<br/>并且与我相调和。<br/>你爱叫你成为我的，<br/>作我一切的供应；<br/>叫我享受你的自己，<br/>时时以你为生命。<br/>','',54256,7791);
INSERT INTO stanza VALUES('Z130','3','你爱就是你的自己-<br/>你那神圣的自己，<br/>作了我的人生意义，<br/>使我活着就是你。<br/>你是我的生命、力量，<br/>你爱给我所经历；<br/>我是你的恩、爱对象，<br/>所经、所历全是你。<br/>','',54257,7792);
INSERT INTO stanza VALUES('Z130','4','甚么能使你我分离？<br/>你爱就必爱到底！<br/>你必与我永远合一，<br/>你爱刚强无可比！<br/>这爱使我感激不已，<br/>是我赞美的目的！<br/>你成为我，<br/>我成为你，<br/>这是你爱的至极！<br/>','',54258,7793);
INSERT INTO stanza VALUES('Z131','1','主，当我们飘流旷野，<br/>你爱前来寻我们：<br/>你用恩手逐步提挈，<br/>至终十架舍己身。<br/>唱罢，我魂，祂爱你；<br/>耶稣为我舍自己。<br/>','',54259,7794);
INSERT INTO stanza VALUES('Z131','2','听哪，这是谁的哭声，<br/>来自溪边的荒园？<br/>这是我主儆醒守更，<br/>虽然门徒已疲倦。<br/>阿，我魂，祂真爱你；<br/>是的，祂为我舍己。<br/>','',54260,7795);
INSERT INTO stanza VALUES('Z131','3','此时祂正对父求恳，<br/>深尝义怒的滋味，<br/>但祂为着我们罪人，<br/>情愿喝干这苦杯。<br/>阿，爱！我魂，祂爱你！<br/>所以为你舍自己。<br/>','',54261,7796);
INSERT INTO stanza VALUES('Z131','4','再后就是惨案末幕：<br/>神的波浪和洪涛，<br/>漫过祂身，使祂痛苦，<br/>才好使我成新造。<br/>这爱无比又无极！<br/>耶稣为我舍自己。<br/>','',54262,7797);
INSERT INTO stanza VALUES('Z131','5','请再听哪！祂正呼喊：<br/>-当祂见父与己分-<br/>神哪、神哪，你竟摧残<br/>那常顺服你的人？<br/>阿，我魂，这是为你；<br/>是的，祂为我舍己。<br/>','',54263,7798);
INSERT INTO stanza VALUES('Z131','6','主，我心乐，因你苦难，<br/>现今都已成往事，<br/>你已升天坐父右边，<br/>永远活着不再死。<br/>那为我们舍己的，<br/>我魂今活着为你。<br/>','',54264,7799);
INSERT INTO stanza VALUES('Z131','7','主，我们因你的奇恩，<br/>现在敬拜、颂赞你；<br/>不久你要成全我们，<br/>与你相见同欢喜。<br/>然而我们今唱说：<br/>耶稣舍己为着我。<br/>','',54265,7800);
INSERT INTO stanza VALUES('Z132','1','长似东西无终点，<br/>阔似宇宙无边岸，<br/>高似高天无限量，<br/>深似深海无底疆，<br/>基督大爱！<br/>','',54266,7801);
INSERT INTO stanza VALUES('Z132','chorus','大哉，大哉，大哉，<br/>基督大爱！<br/>长、阔、高、深不能度，<br/>丰满、优厚临及我，<br/>直到万代！<br/>','',54267,7802);
INSERT INTO stanza VALUES('Z132','2','长得使祂来舍身，<br/>阔得使祂成救恩，<br/>高得使祂将我升，<br/>深得使祂临我生，<br/>基督大爱！<br/>','',54268,7803);
INSERT INTO stanza VALUES('Z132','3','长得使我得赦免，<br/>阔得使我蒙恩典，<br/>高得使我天上坐，<br/>深得在我里面活，<br/>基督大爱！<br/>','',54269,7804);
INSERT INTO stanza VALUES('Z132','4','长、阔，并非何尺度，<br/>高、深，也非何事物；<br/>『长、』『阔，』<br/>二形乃是指，<br/>『高、』『深，』<br/>二者也都是，<br/>基督大爱！<br/>','',54270,7805);
INSERT INTO stanza VALUES('Z133','1','祂是超乎万人之上，<br/>哦，祂的爱！<br/>比诸兄弟更密、更强，<br/>哦，祂的爱！<br/>地上朋友时常离我，<br/>今日慰我，明日忌我，<br/>但这朋友从不欺我，<br/>哦，祂的爱！<br/>','',54271,7806);
INSERT INTO stanza VALUES('Z133','2','我今享受喜乐、安康，<br/>哦，祂的爱！<br/>都亏我主罪债代偿，<br/>哦，祂的爱！<br/>祂流宝血，祂买了我，<br/>祂来旷野，祂寻找我，<br/>同归羊群，祂领导我，<br/>哦，祂的爱！<br/>','',54272,7807);
INSERT INTO stanza VALUES('Z133','3','耶稣乃是我们朋友，<br/>哦，祂的爱！<br/>祂赐福气，祂赐恩祐，<br/>哦，祂的爱！<br/>我心欣幸能瞻仰祂，<br/>叫我安居常倚傍祂，<br/>我怎可以再顶撞祂，<br/>哦，祂的爱！<br/>','',54273,7808);
INSERT INTO stanza VALUES('Z133','4','因祂的名我得赦免，<br/>哦，祂的爱！<br/>在仇敌前为我设筵，<br/>哦，祂的爱！<br/>祂使最好福分临我，<br/>祂禁旨外祸害侵我，<br/>直到荣耀祂在引我，<br/>哦，祂的爱！<br/>','',54274,7809);
INSERT INTO stanza VALUES('Z134','1','你的大爱，<br/>过于人所能度，<br/>我救主耶稣！<br/>但不堪的我，<br/>真要知道牠的<br/>高、深、长、阔，<br/>好叫牠的能力越显越多<br/>在我身上！<br/>','',54275,7810);
INSERT INTO stanza VALUES('Z134','2','你的慈爱，<br/>过于人所能论，<br/>我救主耶稣！<br/>但我的嘴唇<br/>要向远近罪人<br/>劝诲谆谆，<br/>告诉他们，<br/>你爱能解忧困，<br/>并赐喜乐。<br/>','',54276,7811);
INSERT INTO stanza VALUES('Z134','3','你的奇爱，<br/>过于人所能赞，<br/>我救主耶稣！<br/>但我的心坎<br/>总要歌唱那爱，<br/>这大！这满！<br/>因为恶性如我，<br/>也得恩湛，<br/>来亲近神！<br/>','',54277,7812);
INSERT INTO stanza VALUES('Z134','4','我今虽然不能在这地方<br/>测度、讲论、<br/>颂赞爱的泱漭，<br/>但我要带我的虚空心房，<br/>来到你这爱的泉源良港，<br/>求你充满！<br/>','',54278,7813);
INSERT INTO stanza VALUES('Z134','5','我真是一个虚空的器皿，<br/>对你从无一次恋慕深情，<br/>但我却能一再来你面前，<br/>求你怜恤、帮助，<br/>得你恩典，<br/>因你爱我！<br/>','',54279,7814);
INSERT INTO stanza VALUES('Z134','6','哦我主，<br/>求你用爱充满我，<br/>领我到天上永活的江河，<br/>让我用简单的信到那里，<br/>倚靠、鉴赏、称羡<br/>并享受你，<br/>不再他求。<br/>','',54280,7815);
INSERT INTO stanza VALUES('Z134','7','当我面对面看见我救主，<br/>当我在祂的宝座前俯伏，<br/>那时，我就要希奇<br/>并歌唱祂的大爱如何<br/>深、高、阔、长，<br/>并要敬拜。<br/>','',54281,7816);
INSERT INTO stanza VALUES('Z135','1','哦，愿我有千万舌头，<br/>前来赞美救主，<br/>说祂恩典何等深厚，<br/>荣耀何等丰富。<br/>','',54282,7817);
INSERT INTO stanza VALUES('Z135','2','耶稣这名，慰我苦情，<br/>驱尽我的惊怯，<br/>是我安息、是我生命，<br/>成为我的音乐。<br/>','',54283,7818);
INSERT INTO stanza VALUES('Z135','3','祂因爱我，竟愿经历<br/>人世所有苦楚；<br/>祂已消灭罪的能力，<br/>释放罪的囚徒。<br/>','',54284,7819);
INSERT INTO stanza VALUES('Z135','4','我每静念救我的爱，<br/>立即感觉不配；<br/>不知祂为甚么恩待<br/>我这人中罪魁。<br/>','',54285,7820);
INSERT INTO stanza VALUES('Z135','5','我今作祂爱的俘虏，<br/>甘心作到永久；<br/>因祂为我受死、忍辱，<br/>使我得以自由。<br/>','',54286,7821);
INSERT INTO stanza VALUES('Z135','6','我既从你可爱的名，<br/>知你待我美意；<br/>假若我有千万的心，<br/>也当一一归你。<br/>','',54287,7822);
INSERT INTO stanza VALUES('Z136','1','爱主的人都来，<br/>将你喜乐敞开，<br/>甘甜唱着主的奇爱，<br/>同到宝座前来。<br/>','',54288,7823);
INSERT INTO stanza VALUES('Z136','chorus','乐哉，白白恩典！<br/>乐哉，白白恩典！<br/>白白恩典，完全赦免，<br/>乐哉，白白恩典！<br/>','',54289,7824);
INSERT INTO stanza VALUES('Z136','2','未识主名的人，<br/>让他缄默无声；<br/>主的子民既蒙深恩，<br/>应当喜乐欢腾。<br/>','',54290,7825);
INSERT INTO stanza VALUES('Z136','3','未入荣耀之城，<br/>未履精金之街，<br/>郇山佳果甜美丰盈，<br/>豫尝何等喜悦。<br/>','',54291,7826);
INSERT INTO stanza VALUES('Z136','4','故当高声歌唱，<br/>忘记所有忧伤；<br/>我们昂首向前直往，<br/>属天、更美家乡。<br/>','',54292,7827);
INSERT INTO stanza VALUES('Z137','1','恩主为我舍弃尊贵，<br/>为我降世处卑微，<br/>为我饱尝十架苦味，<br/>为我担当所有罪。<br/>','',54293,7828);
INSERT INTO stanza VALUES('Z137','chorus','恩深逾洋海，<br/>真报答不来！<br/>惟有把我全般的爱，<br/>永献我主宰。<br/>','',54294,7829);
INSERT INTO stanza VALUES('Z138','1','主阿，你是神所宝，<br/>是神所悦、所选！<br/>神用乐油将你膏，<br/>胜过膏你同伴。<br/>','',54295,7830);
INSERT INTO stanza VALUES('Z138','chorus','我们心中在珍赏，<br/>珍赏你的美善，<br/>珍赏你是何馨香，<br/>珍赏你的甘甜。<br/>','',54296,7831);
INSERT INTO stanza VALUES('Z138','2','你比世人更秀美，<br/>你是全然可爱；<br/>你的口中有恩惠，<br/>我们满心爱戴。<br/>','',54297,7832);
INSERT INTO stanza VALUES('Z138','3','你生，博士来献宝，<br/>自始人就爱戴；<br/>你死，贵人裹香料，<br/>至终仍然可爱。<br/>','',54298,7833);
INSERT INTO stanza VALUES('Z138','4','你头曾为膏所浇，<br/>人所最为爱戴；<br/>你脚也为人所膏，<br/>你是处处可爱。<br/>','',54299,7834);
INSERT INTO stanza VALUES('Z138','5','你的受死如没药，<br/>安慰人的心灵；<br/>你的复活似香料，<br/>满足神的心情。<br/>','',54300,7835);
INSERT INTO stanza VALUES('Z138','6','在我你香似没药，<br/>你美犹如凤仙，<br/>还像柑树盛而茂，<br/>果实丰美、香甜。<br/>','',54301,7836);
INSERT INTO stanza VALUES('Z138','7','美酒不如你爱美，<br/>你名却似膏香！<br/>我们以你为宝贵，<br/>怎能忘而不想？<br/>','',54302,7837);
INSERT INTO stanza VALUES('Z138','7','我们非仅在默想，<br/>默想你的美善；<br/>我们更是在饱尝，<br/>饱尝你的甘甜！<br/>','',54303,7838);
INSERT INTO stanza VALUES('Z138','chorus','我们心中在珍赏，<br/>珍赏你的美善，<br/>珍赏你是何馨香，<br/>珍赏你的甘甜。<br/>第六节的『柑树』是雅歌二章三节『苹果树』的另一译法。<br/>','',54304,7839);
INSERT INTO stanza VALUES('Z139','1','『甜美』登极救主额上，<br/>神圣、尊贵、庄严；<br/>祂头披戴荣耀之光，<br/>祂口溢出恩典。<br/>祂口溢出恩典。<br/>','',54305,7840);
INSERT INTO stanza VALUES('Z139','2','地上所有必死之人，<br/>与祂相比，谁配？<br/>天上所有天使天军，<br/>有谁比祂更美？<br/>','',54306,7841);
INSERT INTO stanza VALUES('Z139','3','祂是我的生命、气息、<br/>我的所有喜乐；<br/>使我胜过死的能力，<br/>脱离坟墓幽所。<br/>','',54307,7842);
INSERT INTO stanza VALUES('Z139','4','向着父神-我的居所，<br/>祂带我的脚步；<br/>将神荣耀指示与我，<br/>使我喜乐满足。<br/>','',54308,7843);
INSERT INTO stanza VALUES('Z139','5','我从祂的神圣厚恩，<br/>得知祂爱之大；<br/>倘若我有千万的心，<br/>也必全都归祂。<br/>','',54309,7844);
INSERT INTO stanza VALUES('Z140','1','主，你是那可爱新郎，<br/>神所选立，我所爱；<br/>你的自己富有吸引，<br/>我心怎能不爱戴！<br/>','',54310,7845);
INSERT INTO stanza VALUES('Z140','2','亲爱良人，我爱慕你，<br/>你的宝贵谁能言！<br/>你的爱情，我深珍爱，<br/>你的可爱何无限！<br/>','',54311,7846);
INSERT INTO stanza VALUES('Z140','3','你比美者还要更美，<br/>你比甜者还更甜！<br/>你既柔细、你又亲切，<br/>你是何等的完全！<br/>','',54312,7847);
INSERT INTO stanza VALUES('Z140','4','你的衣服满了没药，<br/>你的口中满恩惠！<br/>在你受苦馨香气中，<br/>凭爱珍藏你宝贵。<br/>','',54313,7848);
INSERT INTO stanza VALUES('Z140','5','神曾用那喜乐的油，<br/>膏你胜过你同伴；<br/>从你那些『象牙宫』中，<br/>发出对你的称赞。<br/>','',54314,7849);
INSERT INTO stanza VALUES('Z140','6','神已永远赐福与你，<br/>你已胜过众仇敌；<br/>我今见你加冕、登极，<br/>权柄、威严，无可比。<br/>','',54315,7850);
INSERT INTO stanza VALUES('Z140','7','你是『万国所羡慕的，』<br/>他们必知你价值；<br/>你乃『超乎万人之上，』<br/>永远配得我赏识！<br/>  第五节的『象牙宫』指各地召会。<br/>','',54316,7851);
INSERT INTO stanza VALUES('Z141','1','哦主耶稣，每想到你，<br/>我心便觉甘甜；<br/>深愿我能立刻被提，<br/>到你可爱身边！<br/>','',54317,7852);
INSERT INTO stanza VALUES('Z141','chorus','主，你如一棵美丽凤仙，<br/>显在山野葡萄园间，<br/>殊姿超群、秀色独艳，<br/>我心依依恋恋。<br/>','',54318,7853);
INSERT INTO stanza VALUES('Z141','2','世上并无一个妙音，<br/>能把你恩尽唱；<br/>人间也无一颗情心，<br/>能把你爱全享。<br/>','',54319,7854);
INSERT INTO stanza VALUES('Z141','3','但那最使我心欢喜，<br/>尚非你爱、你恩；<br/>乃是你的可爱自己，<br/>最满我情、我心。<br/>','',54320,7855);
INSERT INTO stanza VALUES('Z141','4','你比美者还要更美，<br/>你比甜者更甜；<br/>你外，在天我心何归？<br/>在地我心何恋？<br/>','',54321,7856);
INSERT INTO stanza VALUES('Z142','1','凉爽，你像柔和微风，<br/>怎能将你吸够！<br/>芬芳胜过所有花丛，<br/>如同没药在我怀中，<br/>又像天上膏油！<br/>又像天上膏油！<br/>','',54322,7857);
INSERT INTO stanza VALUES('Z142','2','滋润，你像清晨甘露，<br/>怎能被你浸够！<br/>新鲜、清凉、<br/>消干、解枯、<br/>滋我心情、润我深处；<br/>愿你将我浸透，<br/>愿你将我浸透。<br/>','',54323,7858);
INSERT INTO stanza VALUES('Z142','3','你是美丽中的至美，<br/>怎能将你赏够！<br/>你的面容所发光辉，<br/>使我更感你美可贵：<br/>你是美中之首！<br/>你是美中之首！<br/>','',54324,7859);
INSERT INTO stanza VALUES('Z142','4','你名香甜远超众名，<br/>怎能将你唱够！<br/>我心充满甜美感应，<br/>深愿向你不住颂称！<br/>喜乐涌自心头，<br/>喜乐涌自心头。<br/>','',54325,7860);
INSERT INTO stanza VALUES('Z142','5','你的自己可爱、饶优，<br/>怎能将你说够！<br/>你心柔细，同情、俯就，<br/>吸引我心向你倚投，<br/>细语：『有你就够！』<br/>细语：『有你就够！』<br/>','',54326,7861);
INSERT INTO stanza VALUES('Z143','1','最美的耶稣！<br/>管理『自然』的主！<br/>神子、人子！永活的道，<br/>你是我所爱，<br/>我所永感戴，<br/>我的喜乐、我的夸耀！<br/>','',54327,7862);
INSERT INTO stanza VALUES('Z143','2','草地何青绿！<br/>树木更加悦目！<br/>披着春花，盛开争艳！<br/>耶稣更鲜艳！<br/>耶稣更香甜！<br/>伤痛之心因祂欢赞。<br/>','',54328,7863);
INSERT INTO stanza VALUES('Z143','3','日光何晴美！<br/>月光更加明媚！<br/>群星闪烁，光辉夺目！<br/>耶稣更明亮！<br/>耶稣更晴朗！<br/>胜过天上一切景物！<br/>','',54329,7864);
INSERT INTO stanza VALUES('Z143','4','所有的美丽，<br/>在天或是在地，<br/>在你身上全都见到；<br/>无何更光彩，<br/>无何更可爱！<br/>惟我救主，你最高超！<br/>','',54330,7865);
INSERT INTO stanza VALUES('Z144','1','我们要从那里说起，<br/>主，你所赐一切福气？<br/>既然脱罪不作奴隶，<br/>既然免死不作仇敌；<br/>我当如何向你拜礼，<br/>把你高举才算适宜？<br/>','',54331,7866);
INSERT INTO stanza VALUES('Z144','2','你向我们所施安抚，<br/>我们怎能用口倾吐？<br/>可怒之子当下火湖，<br/>竟然得救，以神为父！<br/>在地我知罪已抹涂，<br/>真是豫享属天美福。<br/>','',54332,7867);
INSERT INTO stanza VALUES('Z144','3','我们的心满是基督，<br/>切望倾倒此中丰富；<br/>你是我们诗歌题目，<br/>你是我们心爱救主；<br/>我们舌头急要唱出：<br/>天上君王荣耀万古！<br/>','',54333,7868);
INSERT INTO stanza VALUES('Z144','4','你比世上一切众生，<br/>都更美丽、都更成圣；<br/>你心有爱，你口有恩；<br/>你既受苦、你又舍身；<br/>你这永受颂赞的神！<br/>我们敬拜以灵以真。<br/>','',54334,7869);
INSERT INTO stanza VALUES('Z145','1','耶稣，奇妙救主！<br/>基督，王中王！<br/>天使敬拜俯伏，<br/>我们也颂扬；<br/>他们在天承认<br/>你乃美至极；<br/>我们也在爱吟<br/>你是最美丽。<br/>','',54335,7870);
INSERT INTO stanza VALUES('Z145','2','地上所有安逸，<br/>尽都是空穴；<br/>天上缺少了你，<br/>也变成黑夜。<br/>基督，你的荣耀<br/>乃是天上光；<br/>耶稣，你的荣耀<br/>使地也明亮。<br/>','',54336,7871);
INSERT INTO stanza VALUES('Z145','3','如果与你分开，<br/>生命变死亡；<br/>若是有你同在，<br/>死中生仍旺。<br/>宇宙、人类、天使，<br/>全由你造成，<br/>然而你肯降世，<br/>穿上人性情。<br/>','',54337,7872);
INSERT INTO stanza VALUES('Z145','4','耶稣！一切美善，<br/>始终全在你；<br/>神的荣耀光线，<br/>乃是你自己。<br/>人若得见你面，<br/>是蒙了奇恩；<br/>但愿你这恩典，<br/>我也满有分。<br/>','',54338,7873);
INSERT INTO stanza VALUES('Z146','1','我们当来同声欢呼，<br/>称颂神的基督；<br/>我们若有千万舌头，<br/>诗歌只有一首。<br/>','',54339,7874);
INSERT INTO stanza VALUES('Z146','2','『升天羔羊，你真是配，<br/>来得这样赞美！』<br/>我们喊说：『你真是配，<br/>因你为我降卑！』<br/>','',54340,7875);
INSERT INTO stanza VALUES('Z146','3','救主耶稣配得尊贵、<br/>权柄、荣耀、智慧；<br/>还有许多献上不及，<br/>主阿，永都归你！<br/>','',54341,7876);
INSERT INTO stanza VALUES('Z146','4','不久圣徒快要上升，<br/>同发赞美之声；<br/>一切住在青天之下，<br/>都要颂扬不暇！<br/>','',54342,7877);
INSERT INTO stanza VALUES('Z146','5','待赎宇宙合而为一，<br/>颂赞羔羊不已；<br/>因祂降世，亲临死地，<br/>现今荣耀无比。<br/>','',54343,7878);
INSERT INTO stanza VALUES('Z147','1','荣耀归于我主，<br/>天地齐来欢呼，<br/>向祂赞美；<br/>祂的恩典、慈爱，<br/>除我死亡、悲哀；<br/>高唱直到万代，<br/>『羔羊是配。』<br/>','',54344,7879);
INSERT INTO stanza VALUES('Z147','2','蒙恩人们都来，<br/>环绕宝座敬拜，<br/>向祂赞美；<br/>为我宝血流出，<br/>与神和好无阻；<br/>赞颂之声四布，<br/>『羔羊是配。』<br/>','',54345,7880);
INSERT INTO stanza VALUES('Z147','3','被赎族类都来，<br/>同心向主敬拜，<br/>向祂赞美；<br/>因祂我得欢乐，<br/>发出感恩诗歌，<br/>起来，口唱心和，<br/>『羔羊是配。』<br/>','',54346,7881);
INSERT INTO stanza VALUES('Z147','4','事物虽然改迁，<br/>但我依旧不变，<br/>向祂赞美；<br/>诗歌不绝颂扬，<br/>尊祂我主我王，<br/>欢声上达穹苍，<br/>『羔羊是配。』<br/>','',54347,7882);
INSERT INTO stanza VALUES('Z148','1','哦主耶稣，<br/>我的心向着宝座，<br/>何等喜乐，<br/>向你献上赞美！<br/>因着蒙福，<br/>我敬拜，我也述说，<br/>承认你配，<br/>惟有你真是配。<br/>','',54348,7883);
INSERT INTO stanza VALUES('Z148','chorus','主，你真是配！<br/>主，你真是配！<br/>赞美，因为惟有你<br/>真是配！<br/>因着蒙福，我敬拜，<br/>我也述说你的荣耀，<br/>因为你真是配。<br/>','',54349,7884);
INSERT INTO stanza VALUES('Z148','2','你这神人，是真神，<br/>又是真人，<br/>低于天使，<br/>为我们作牺牲；<br/>女人后裔，<br/>曾如何亲临嚣尘，<br/>败坏古蛇，<br/>伤其头，踏其身！<br/>','',54350,7885);
INSERT INTO stanza VALUES('Z148','3','创造的主，竟然被<br/>受造的人钉十字架，<br/>你是如何降卑！<br/>你不自救，<br/>被神弃又被人恨！<br/>你不退缩，<br/>经黑暗，喝苦杯！<br/>','',54351,7886);
INSERT INTO stanza VALUES('Z148','4','接战死亡，<br/>你如何退其狂澜，<br/>荣耀得胜，<br/>全得胜，大得胜！<br/>思念及此，<br/>怎能不歌颂弥漫！<br/>阴府的门，<br/>到如今全溃崩。<br/>','',54352,7887);
INSERT INTO stanza VALUES('Z149','1','我主耶稣，惟你是配，<br/>来得永远的赞美，<br/>因你爱心、恩典、慈良，<br/>远超我们所能想。<br/>','',54353,7888);
INSERT INTO stanza VALUES('Z149','2','我们满心感激不尽，<br/>前来称颂你尊名；<br/>一生一世满被恩惠，<br/>到处述说你宝贵。<br/>','',54354,7889);
INSERT INTO stanza VALUES('Z149','3','我们所拜的主耶稣，<br/>你是何等的宽恕；<br/>你的爱心像你能力，<br/>永无限量永无已。<br/>','',54355,7890);
INSERT INTO stanza VALUES('Z149','4','耶稣，你是首先、末后，<br/>你要领我到尽头；<br/>因着已往我赞美你，<br/>为着将来我靠你。<br/>','',54356,7891);
INSERT INTO stanza VALUES('Z149','5','赞祂！赞祂！赞我恩人！<br/>圣徒们哪，当高声！<br/>赞祂！赞祂！直到天上，<br/>赞得完全赞得长。<br/>','',54357,7892);
INSERT INTO stanza VALUES('Z150','1','哦主，你是何等包罗，<br/>我竟得在你里！<br/>神要你作我们永分，<br/>我的一切是你。<br/>','',54358,7893);
INSERT INTO stanza VALUES('Z150','2','神使你作我们智慧，<br/>我们因你得救；<br/>你是惟一得救之路，<br/>惟一蒙恩之由。<br/>','',54359,7894);
INSERT INTO stanza VALUES('Z150','3','神使你作我们公义，<br/>满足神的要求；<br/>在你里面我得称义，<br/>再无何罪可究。<br/>','',54360,7895);
INSERT INTO stanza VALUES('Z150','4','神使你作我们圣洁，<br/>为将我们变化；<br/>在你里面我被圣别，<br/>直到与你无差。<br/>','',54361,7896);
INSERT INTO stanza VALUES('Z150','5','神使你作我们救赎，<br/>为要我们像你；<br/>你要改变我们身体，<br/>我就与你无异。<br/>','',54362,7897);
INSERT INTO stanza VALUES('Z150','6','主，当我们在此记念，<br/>享受你的所是；<br/>真愿催促你快回来，<br/>不再有所延迟。<br/>','',54363,7898);
INSERT INTO stanza VALUES('Z150','7','这个豫尝何等甘甜，<br/>已足令人满意；<br/>但我仍望与你同在，<br/>满享你的自己。<br/>','',54364,7899);
INSERT INTO stanza VALUES('Z151','1','主，你是那永久磐石，<br/>属灵磐石为我裂；<br/>灵中饮于你流活水，<br/>就得与你永联结。<br/>你是磐石，永远稳固，<br/>我在其上被建造；<br/>借着救赎，与你联合，<br/>无何能将我动摇。<br/>','',54365,7900);
INSERT INTO stanza VALUES('Z151','chorus','我们珍贵你的价值，<br/>你之所是全为我；<br/>我们在此因爱记念，<br/>满享你富的广阔。<br/>','',54366,7901);
INSERT INTO stanza VALUES('Z151','2','你是石头，多人试过，<br/>神所宝贵，我所爱；<br/>极其稳固、极其可靠，<br/>你的力量永不衰。<br/>你也是那永生活石，<br/>神所拣选，归我们；<br/>何其坚强、何其有力，<br/>无穷生命是我分。<br/>','',54367,7902);
INSERT INTO stanza VALUES('Z151','3','你又是那神圣基石，<br/>神所安放，稳而坚；<br/>借着你这稳固根基，<br/>我们永远享安全。<br/>对于我们，在你之外，<br/>无人能立别根基；<br/>你是我们惟一基础，<br/>直到永远不更移。<br/>','',54368,7903);
INSERT INTO stanza VALUES('Z151','4','为着神的属灵建造，<br/>你是房角的首石；<br/>犹太、外邦，成为一体，<br/>建造全靠你所是。<br/>主，你也是那块顶石，<br/>无限恩典所搬出；<br/>你是我们遮盖、荣耀，<br/>我们心中满歌赋。<br/>','',54369,7904);
INSERT INTO stanza VALUES('Z152','1','主，你于我何其丰富，<br/>你爱说出其度量！<br/>你的自己无限富有，<br/>今在我灵给我享。<br/>','',54370,7905);
INSERT INTO stanza VALUES('Z152','2','你乃是话，也就是神，<br/>太初就与神同在；<br/>成为肉身，与人同处，<br/>将神向人说出来。<br/>','',54371,7906);
INSERT INTO stanza VALUES('Z152','3','你乃是神真的帐幕，<br/>在你我见神荣耀；<br/>你也是神真的圣殿，<br/>在你里面神住着。<br/>','',54372,7907);
INSERT INTO stanza VALUES('Z152','4','你乃是神独生爱子，<br/>永远将父来表明，<br/>使我能有神的生命，<br/>并且有分神性情。<br/>','',54373,7908);
INSERT INTO stanza VALUES('Z152','5','你是人子，与我一样，<br/>确有我们的性情，<br/>使我能作神的儿子，<br/>直到满有你荣形。<br/>','',54374,7909);
INSERT INTO stanza VALUES('Z152','6','你是基督，有的主，<br/>是神所膏弥赛亚；<br/>你是万有，又在万有，<br/>神人所赖，无限大！<br/>','',54375,7910);
INSERT INTO stanza VALUES('Z152','7','你是救主，钉死十架，<br/>从你流出血和水，<br/>使我得蒙神的救赎，<br/>有神生命，成宝贵！<br/>','',54376,7911);
INSERT INTO stanza VALUES('Z152','7','你今是那得荣耶稣，<br/>从你降下生命灵；<br/>祂是包罗万有的灵，<br/>来使我享你丰盛。<br/>','',54377,7912);
INSERT INTO stanza VALUES('Z152','9','你是神圣生命之光，<br/>黑暗之中来照亮；<br/>在我心中，带神照亮，<br/>直到充满我心房。<br/>','',54378,7913);
INSERT INTO stanza VALUES('Z152','10','你是神圣永远生命，<br/>点活我们死的灵；<br/>你使我们脱离死亡，<br/>享受生命的丰盛。<br/>','',54379,7914);
INSERT INTO stanza VALUES('Z152','11','主，你乃是神的实际，<br/>惟你能使神喜悦；<br/>你这实际使我知道<br/>你是如何用不竭。<br/>','',54380,7915);
INSERT INTO stanza VALUES('Z152','12','主，你也是惟一道路，<br/>使我进入神自己；<br/>生命之道，实际之路，<br/>将我带进荣耀里。<br/>','',54381,7916);
INSERT INTO stanza VALUES('Z152','13','主，你又是奇妙复活，<br/>所有死亡全胜过；<br/>使我借你复活大能，<br/>与你同死并同活。<br/>','',54382,7917);
INSERT INTO stanza VALUES('Z152','14','你是神的无瑕羔羊，<br/>救赎为我来作成；<br/>你也是那赐圣灵者，<br/>为着使我得生命。<br/>','',54383,7918);
INSERT INTO stanza VALUES('Z152','15','你是杆上所挂铜蛇，<br/>救我脱离致死罪；<br/>你在十架被人举起，<br/>掌死魔鬼为我毁。<br/>','',54384,7919);
INSERT INTO stanza VALUES('Z152','16','你是牧人，又是羊门，<br/>使我脱离律法圈，<br/>借你我今已得自由，<br/>青草地上尝甘甜。<br/>','',54385,7920);
INSERT INTO stanza VALUES('Z152','17','你的洗涤使我洁净，<br/>功能如同洗濯盆；<br/>将我保守在你交通，<br/>享你恩爱无穷尽。<br/>','',54386,7921);
INSERT INTO stanza VALUES('Z152','18','你是磐石为我裂开，<br/>流出生命的活水；<br/>饮于你这常新水流，<br/>得脱一切的困惫。<br/>','',54387,7922);
INSERT INTO stanza VALUES('Z152','19','你是属天永生泉源，<br/>活水藏在你里面；<br/>喝了你这永生活水，<br/>不再干渴到永远。<br/>','',54388,7923);
INSERT INTO stanza VALUES('Z152','20','你是天降生命的粮，<br/>神圣、丰富又盛旺，<br/>带着你的无限丰富，<br/>时将我灵来喂养。<br/>','',54389,7924);
INSERT INTO stanza VALUES('Z152','21','你是我们生命之气，<br/>给我灵中来呼吸；<br/>靠你生活，凭你行动，<br/>就得享受你自己。<br/>','',54390,7925);
INSERT INTO stanza VALUES('Z152','22','你是一粒神圣麦子，<br/>甘愿落到死地里，<br/>结出我们许多子粒，<br/>作你奥秘的身体。<br/>','',54391,7926);
INSERT INTO stanza VALUES('Z152','23','你是属天真葡萄树，<br/>我们是你的枝子；<br/>住在你里，与你联结，<br/>享受一切你所是。<br/>','',54392,7927);
INSERT INTO stanza VALUES('Z152','24','你是宇宙真的新郎，<br/>我们是你的新妇；<br/>灵里与你成为一体，<br/>得享你爱的丰富。<br/>','',54393,7928);
INSERT INTO stanza VALUES('Z152','25','你是雅各所见天梯，<br/>借你天向地而开；<br/>靠你我们作神圣殿，<br/>地联于天无阻碍。<br/>','',54394,7929);
INSERT INTO stanza VALUES('Z152','26','哦主，你是那<br/>『我是』的，<br/>应付我们所需要；<br/>享受你作一切一切，<br/>神就因你得荣耀。<br/>','',54395,7930);
INSERT INTO stanza VALUES('Z153','1','主，你是我照护侍从，<br/>也是我保惠师；<br/>你又是我诚信中保，<br/>神前为我办事。<br/>','',54396,7931);
INSERT INTO stanza VALUES('Z153','2','你是我的辩护顾问，<br/>也是我辩护者；<br/>是我凡事的代祷者，<br/>也是我帮助者。<br/>','',54397,7932);
INSERT INTO stanza VALUES('Z153','3','主，你照着神所喜悦，<br/>为我办理一切；<br/>你在天上，又在我里，<br/>凡事为我解决。<br/>','',54398,7933);
INSERT INTO stanza VALUES('Z153','4','你乃是那内住之灵，<br/>时常为我代祷；<br/>天上辩护，我里叹息，<br/>代我向神求告。<br/>','',54399,7934);
INSERT INTO stanza VALUES('Z153','5','永远活着，照神旨意，<br/>施恩、帮助惟殷；<br/>借着复活生命大能，<br/>加强里面的人。<br/>','',54400,7935);
INSERT INTO stanza VALUES('Z153','6','你是那赐生命之灵，<br/>时常顾我软弱；<br/>在我灵中，用你大能，<br/>使我凭你活着。<br/>','',54401,7936);
INSERT INTO stanza VALUES('Z153','7','借你爱怜，以你自己，<br/>永远服事、眷念；<br/>好使你作我们一切，<br/>我们作你丰满。<br/>','',54402,7937);
INSERT INTO stanza VALUES('Z154','1','远在时间尚未起首，<br/>万有尚都未开始，<br/>在父怀中并荣耀里，<br/>你是神的独生子。<br/>当父将你赐给我们，<br/>你的身位仍一样，<br/>为将父的所有丰满，<br/>借着圣灵来表扬。<br/>','',54403,7938);
INSERT INTO stanza VALUES('Z154','2','借着你死并你复活，<br/>你就成为神长子；<br/>借着重生分赐生命，<br/>我们成为神众子。<br/>我们是你生命繁殖，<br/>是你许多的弟兄，<br/>我们是你荣耀复本，<br/>是你神圣的扩充。<br/>','',54404,7939);
INSERT INTO stanza VALUES('Z154','3','你曾是那惟一麦粒，<br/>落到地里而死了；<br/>借着死亡，并借复活，<br/>显出繁殖的荣耀。<br/>你使我们由你得生，<br/>变成许多的子粒；<br/>众人调和成为一饼，<br/>作你丰满的身体。<br/>','',54405,7940);
INSERT INTO stanza VALUES('Z154','4','我们是你的复制品、<br/>是你身体并新妇、<br/>是你表现、是你丰满，<br/>永远让你来居住。<br/>我们是你普及、继续、<br/>是你生命的开展、<br/>是你长成、是你富余，<br/>与你合一永无间。<br/>','',54406,7941);
INSERT INTO stanza VALUES('Z155','1','古时一切豫表、影像，<br/>全都是你的描绘；<br/>正如这些所表所征，<br/>你今于我何宝贵！<br/>当我注视这幅图画，<br/>欣赏各方的优越，<br/>我就惊奇你的丰美，<br/>敬拜你是我一切！<br/>','',54407,7942);
INSERT INTO stanza VALUES('Z155','2','恩主，你是我逾越节，<br/>因你神将我逾越；<br/>借你自己和你救赎，<br/>我们得与神和谐。<br/>主，你也是神的羔羊，<br/>被杀、流血、救赎我；<br/>应用你血作我赎价，<br/>并靠吃你而活着。<br/>','',54408,7943);
INSERT INTO stanza VALUES('Z155','3','你是天降生命的粮，<br/>就是无酵生命饼；<br/>我们吃你，与你调和，<br/>就得有分你功能。<br/>羔羊和饼都是豫表，<br/>象征你是我生命；<br/>筵席之上吃你、喝你，<br/>我们享受你丰盛。<br/>','',54409,7944);
INSERT INTO stanza VALUES('Z155','4','主，你也是属天吗哪，<br/>我们每日的食物；<br/>喂养、饱足、刚强、<br/>加力，<br/>所有需要全应付。<br/>主，你又是活的磐石，<br/>为我裂开，生命流；<br/>饮于你这生命活水，<br/>不再干渴到永久。<br/>','',54410,7945);
INSERT INTO stanza VALUES('Z155','5','主，你更是迦南美地，<br/>超越、丰富又佳美，<br/>流奶与蜜，各物丰收，<br/>凡我需要无不备。<br/>凭你丰余向神敬拜，<br/>并且借此相交通，<br/>如此爱中彼此联结，<br/>神的建造得成功。<br/>','',54411,7946);
INSERT INTO stanza VALUES('Z156','1','恩主，你是公义太阳，<br/>富有医治光线；<br/>你的荣耀面光照临，<br/>带来生命、平安。<br/>','',54412,7947);
INSERT INTO stanza VALUES('Z156','2','慈爱神的怜悯心肠，<br/>叫你临到我们，<br/>为要照亮坐在黑暗<br/>死荫之中的人。<br/>','',54413,7948);
INSERT INTO stanza VALUES('Z156','3','对我你像无云清晨，<br/>又如日出晨光；<br/>我们乃像地上嫩草，<br/>靠你光线生长。<br/>','',54414,7949);
INSERT INTO stanza VALUES('Z156','4','恩光带着可爱光线，<br/>扩增犹如天曙；<br/>在我里面越照越明，<br/>直至中天日午。<br/>','',54415,7950);
INSERT INTO stanza VALUES('Z156','5','清明光线照透苦难，<br/>犹如雨后晴光；<br/>带着你的怜悯、慈爱，<br/>永不停止照亮。<br/>','',54416,7951);
INSERT INTO stanza VALUES('Z156','6','主，你也是明亮晨星，<br/>作我儆醒赏赐；<br/>照亮那些爱你之人，<br/>正当黑暗深时。<br/>','',54417,7952);
INSERT INTO stanza VALUES('Z156','7','求主使我爱慕你光，<br/>使我眼光清明；<br/>儆醒、祷告、等候你来，<br/>犹如等候晨星。<br/>','',54418,7953);
INSERT INTO stanza VALUES('Z157','1','主，当我们把你思念，<br/>因你所是我们敬拜；<br/>你是如此丰富、奇妙，<br/>何其可宝、何其可爱！<br/>','',54419,7954);
INSERT INTO stanza VALUES('Z157','chorus','你之所是正合我需！<br/>我心对你赞美洋溢！<br/>我之所愿你全满足，<br/>绰绰有余，应付不已！<br/>','',54420,7955);
INSERT INTO stanza VALUES('Z157','2','实实在在你真是神，<br/>是那是光是爱之神；<br/>是神，你作我们生命，<br/>是神，你向我们赐恩。<br/>','',54421,7956);
INSERT INTO stanza VALUES('Z157','3','实实在在你也是人，<br/>是一柔细、纯良的人；<br/>是人，你使神心喜悦，<br/>是人，你能得着我心。<br/>','',54422,7957);
INSERT INTO stanza VALUES('Z157','4','你竟也是卑微奴仆，<br/>为着我们作神奴仆；<br/>甘心顺服以至于死，<br/>为使我们得救、蒙福。<br/>','',54423,7958);
INSERT INTO stanza VALUES('Z157','5','此外，恩主，你还是王，<br/>为神所膏、是神所立；<br/>借着生命和爱掌权，<br/>带着我们一同治理。<br/>','',54424,7959);
INSERT INTO stanza VALUES('Z157','6','主，当我们在此记念，<br/>我们分享你之所是；<br/>爱中享受你的自己，<br/>如此享受直到永世！<br/>','',54425,7960);
INSERT INTO stanza VALUES('Z158','1','哦主，你是阿拉法，<br/>你也是俄梅嘎；<br/>你前并无更前者，<br/>你后也无可加。<br/>你是惟一的元始，<br/>也是万事之终；<br/>万有包括在你里，<br/>你是万有之总。<br/>','',54426,7961);
INSERT INTO stanza VALUES('Z158','2','主，因你是阿拉法，<br/>万有由你开始；<br/>因你也是俄梅嘎，<br/>万有在你而止。<br/>又是全部的字母，<br/>一切由你组成；<br/>既是所有的字母，<br/>一切为你托撑。<br/>','',54427,7962);
INSERT INTO stanza VALUES('Z158','3','你是受造首先者，<br/>你是万有之首；<br/>你是一切末后者，<br/>你来结束万有。<br/>你是受造首先者，<br/>万有由你而来；<br/>你是一切末后者，<br/>万有靠你存在。<br/>','',54428,7963);
INSERT INTO stanza VALUES('Z158','4','你是一切的元始，<br/>你在万有之前；<br/>你是一切的终结，<br/>万有归你承揽。<br/>你是独一的元始，<br/>万有由你创始；<br/>你是无二的终结，<br/>万有归你终止。<br/>','',54429,7964);
INSERT INTO stanza VALUES('Z158','5','哦主，我们敬拜你，<br/>以爱将你珍赏；<br/>阿拉法及俄梅嘎，<br/>乃在万有之上。<br/>赞美你是元始者，<br/>你在一切之先；<br/>敬拜你是终结者，<br/>你后何可加添？<br/>','',54430,7965);
INSERT INTO stanza VALUES('Z159','1','主，你乃是那生命树，<br/>生命惟一出处；<br/>你的果子富有生命，<br/>作我最美食物。<br/>','',54431,7966);
INSERT INTO stanza VALUES('Z159','2','你是属天真葡萄树，<br/>生命供应源头；<br/>住在你里，靠你生活，<br/>得享你的富有。<br/>','',54432,7967);
INSERT INTO stanza VALUES('Z159','3','主，你也是那苹果树，<br/>给我享受欣赏；<br/>你的果子滋味甘甜，<br/>在你荫下得尝。<br/>','',54433,7968);
INSERT INTO stanza VALUES('Z159','4','主，你更是医治之树，<br/>曾经为我受死；<br/>挂在木上为我被杀，<br/>使我得到医治。<br/>','',54434,7969);
INSERT INTO stanza VALUES('Z159','5','你是神的独一枝子，<br/>藏着神的丰满；<br/>在你我们得享神作<br/>无限实际、恩典。<br/>','',54435,7970);
INSERT INTO stanza VALUES('Z159','6','主，你也是大卫之枝，<br/>借成肉身而成；<br/>在你我们得以领略<br/>何为真实人性。<br/>','',54436,7971);
INSERT INTO stanza VALUES('Z159','7','你是神的发芽之杖，<br/>含有无穷生命；<br/>死亡永远不能胜过<br/>你那复活大能。<br/>','',54437,7972);
INSERT INTO stanza VALUES('Z159','7','你是那根漂起之木，<br/>我是沉水『斧头；』<br/>借你生命超越大能，<br/>得从死水起浮。<br/>','',54438,7973);
INSERT INTO stanza VALUES('Z159','9','你是如此『有名植物，』<br/>我得丰富分享；<br/>主，当我们在此记念，<br/>我愿将你颂扬。<br/>『有名植物』见以西结三十四章二十九节。<br/>','',54439,7974);
INSERT INTO stanza VALUES('Z160','1','哦主，你是神的见证，<br/>远非律法能比；<br/>律法不过是你小影，<br/>你是律法实际。<br/>律法仅是神的说明，<br/>描述神是如何；<br/>而你乃是神的实际，<br/>神在你里住着。<br/>','',54440,7975);
INSERT INTO stanza VALUES('Z160','2','约柜也是你的豫表，<br/>其中仅有律法；<br/>但你里面有神自己，<br/>带着一切安家。<br/>约柜乃用坚实木料，<br/>上面包金而造；<br/>豫表你有正确人性，<br/>并有神性相调。<br/>','',54441,7976);
INSERT INTO stanza VALUES('Z160','3','你也是那真实帐幕，<br/>有神住你里面；<br/>你成肉身，与人同住，<br/>满有真理、恩典。<br/>在你人见神的荣耀，<br/>你是神的活话；<br/>你凭光、爱所有言行，<br/>是神活的图画。<br/>','',54442,7977);
INSERT INTO stanza VALUES('Z160','4','圣殿也是你的豫表，<br/>你是神的真殿；<br/>神带一切居住于你，<br/>借你得着彰显。<br/>撒但虽尽其力拆毁，<br/>将你置于死地，<br/>但你却在复活里面，<br/>更大之殿建起。<br/>','',54443,7978);
INSERT INTO stanza VALUES('Z160','5','圣城象征你的丰满，<br/>是你新妇小影；<br/>这是你的丰满扩充，<br/>出于你的丰盛。<br/>神在你里作城的光，<br/>你是城中明灯；<br/>带神经她照亮众人，<br/>将神荣耀显明。<br/>','',54444,7979);
INSERT INTO stanza VALUES('Z160','6','哦主，<br/>帐幕、约柜、律法，<br/>以及圣殿、圣城，<br/>全都是你宝贵自己，<br/>说出你的丰盛。<br/>中心是你，圆周是你、<br/>一切全都是你！<br/>神、人全都在你一身，<br/>我心宝爱、称奇。<br/>','',54445,7980);
INSERT INTO stanza VALUES('Z161','1','哦主，于我你是何丰，<br/>是我一切一切；<br/>我的需要无论多多，<br/>你全应付无缺。<br/>我心欣赏你之所是，<br/>我灵向你敬拜；<br/>因着享受你的丰富，<br/>对你满了感戴。<br/>','',54446,7981);
INSERT INTO stanza VALUES('Z161','2','你是先知，神所兴起，<br/>富有神的权能；<br/>如同摩西，指明神意，<br/>我们得以照行。<br/>又像约拿，被神差遣，<br/>经过死而复活；<br/>借这死与生的表记，<br/>使我相信悔过。<br/>','',54447,7982);
INSERT INTO stanza VALUES('Z161','3','你是先知，人间兴起，<br/>满有亮光、能力；<br/>像以利沙，充满爱心，<br/>对人广行神迹。<br/>像以赛亚，满有恩惠，<br/>启示神的基督，<br/>使我得享祂作一切，<br/>实际而又丰富。<br/>','',54448,7983);
INSERT INTO stanza VALUES('Z161','4','你是祭司，人间选出，<br/>作我圣洁祭司；<br/>好像亚伦，蒙神所召，<br/>代人神前服事。<br/>凭爱将我带到神前，<br/>像大祭司一般；<br/>因爱在彼为我代祷，<br/>我的软弱承担。<br/>','',54449,7984);
INSERT INTO stanza VALUES('Z161','5','你是祭司，神所差来，<br/>作神君尊祭司；<br/>像撒冷王，麦基洗德，<br/>为神前来服事。<br/>带饼和酒从神而来，<br/>作我应时供应；<br/>将神带来，使我得享<br/>祂的所有丰盛。<br/>','',54450,7985);
INSERT INTO stanza VALUES('Z161','6','你是君王，如同大卫，<br/>体贴神的心愿；<br/>为神争战，征服仇敌，<br/>神的心愿成全。<br/>得着权柄，登上宝座，<br/>非凭人手掌管；<br/>乃是运用神圣权柄，<br/>为神作王掌权。<br/>','',54451,7986);
INSERT INTO stanza VALUES('Z161','7','你是君王，像所罗门，<br/>带着和平执政；<br/>凭着智慧作王治理，<br/>为建神殿经营。<br/>现今在你圣徒中间，<br/>凭爱隐着掌权；<br/>将来要同我们作王，<br/>王权显于众前。<br/>','',54452,7987);
INSERT INTO stanza VALUES('Z161','7','你是祭司、先知、君王，<br/>所是何其丰美；<br/>对神、对人，你的价值，<br/>我们凭爱宝贵。<br/>我们珍爱你之所是，<br/>全人受你吸引；<br/>对你献上敬拜、赞美，<br/>永远感激不尽。<br/>','',54453,7988);
INSERT INTO stanza VALUES('Z162','1','我主，你是<br/>『女人后裔，』<br/>诞生为毁那仇敌；<br/>你曾取了人的性情，<br/>为借受死得胜利。<br/>你乃是神成了肉身，<br/>穿上血肉的身体；<br/>你已借死毁坏魔鬼，<br/>消除死亡的势力。<br/>','',54454,7989);
INSERT INTO stanza VALUES('Z162','2','照神应许，你已来作<br/>『亚伯拉罕的后裔，』<br/>为使万人都能得到<br/>神所应许的福气。<br/>你在亚伯拉罕之先，<br/>因你是那『我是』的，<br/>但为成就神的应许，<br/>你竟作了他后裔。<br/>','',54455,7990);
INSERT INTO stanza VALUES('Z162','3','主，你也是<br/>『大卫后裔，』<br/>为神国度被兴起；<br/>为神荣耀和神建造，<br/>宝座已经归于你。<br/>虽然你是『大卫后裔，』<br/>他却称你为『我主，』<br/>因你原是『大卫的根、』<br/>『万有之主』到永古。<br/>','',54456,7991);
INSERT INTO stanza VALUES('Z162','4','虽『一婴孩』生有人性，<br/>『全能之神』被称呼；<br/>虽是『一子』赐给我们，<br/>却被称为『永远父。』<br/>神所应许一切福气，<br/>全在我们相信你；<br/>应许在你都是是的，<br/>你是应许的实际！<br/>','',54457,7992);
INSERT INTO stanza VALUES('Z163','1','主，你是神的爱子，<br/>是神荣耀形像；<br/>你是圣徒的永分，<br/>我们都得分享。<br/>你是受造首生者，<br/>一切造物之首；<br/>万有靠你而被造，<br/>也都归你承受。<br/>','',54458,7993);
INSERT INTO stanza VALUES('Z163','2','你是万有的由来，<br/>万有存在之秘；<br/>你是万有的中心，<br/>万有靠你而立。<br/>你是从死首生者，<br/>一切元始是你；<br/>你是召会荣耀头，<br/>召会是你身体。<br/>','',54459,7994);
INSERT INTO stanza VALUES('Z163','3','父愿一切的丰满，<br/>全都住你里面；<br/>使你凡事居首位，<br/>凡事得着彰显。<br/>你已借死使万有<br/>全都与神和好，<br/>好将我们呈神前，<br/>圣洁合神所要。<br/>','',54460,7995);
INSERT INTO stanza VALUES('Z163','4','神之所是全在你，<br/>你是神的奥秘；<br/>所积智慧与知识<br/>全都居住于你。<br/>你是荣耀的盼望，<br/>现今住我里面；<br/>在你我们被成全，<br/>使神意足心满。<br/>','',54461,7996);
INSERT INTO stanza VALUES('Z163','5','一切全都是影儿，<br/>惟有你是实际；<br/>我们在你已生根，<br/>现在正被建立。<br/>享受所有你丰富，<br/>成为你的丰满；<br/>作你身体持守你，<br/>长大因神增添。<br/>','',54462,7997);
INSERT INTO stanza VALUES('Z163','6','我们同你藏神内，<br/>你是我们生命；<br/>将来同显荣耀里，<br/>尽享你的丰盛。<br/>在你身体-新人里，<br/>你是一切一切；<br/>包罗万有的基督，<br/>你何丰富、超越！<br/>','',54463,7998);
INSERT INTO stanza VALUES('Z164','1','☆恩主，你是神的儿子，<br/>是神完满的表现；<br/>借你，神向我们说话，<br/>将祂说得详而全。<br/>','',54464,7999);
INSERT INTO stanza VALUES('Z164','2','☆你是神的本体真像，<br/>是神荣耀的光辉；<br/>你也就是神的自己，<br/>是神自己的发挥。<br/>','',54465,8000);
INSERT INTO stanza VALUES('Z164','3','宇宙万有借你而造，<br/>也是由你来托住，<br/>将来且都归你承受，<br/>你是神立的基督。<br/>','',54466,8001);
INSERT INTO stanza VALUES('Z164','4','你已洗净我们的罪，<br/>今坐高天神右边；<br/>等候仇敌作你脚凳，<br/>神的旨意得成全。<br/>','',54467,8002);
INSERT INTO stanza VALUES('Z164','5','更尊之名你已承受，<br/>远超所有的天使；<br/>神已叫你从死复活，<br/>显明你是祂儿子。<br/>','',54468,8003);
INSERT INTO stanza VALUES('Z164','6','你的国权公义、正直，<br/>你的宝座到永远。<br/>喜乐的油神曾膏你，<br/>胜过膏你的同伴。<br/>','',54469,8004);
INSERT INTO stanza VALUES('Z164','7','☆你也真是一个人子，<br/>具有我们的人性；<br/>借恩为我尝了死味，<br/>使我能有你生命。<br/>','',54470,8005);
INSERT INTO stanza VALUES('Z164','7','你已得了尊贵、荣耀，<br/>万有向你全降服，<br/>你这神的救恩元帅，<br/>得以完全，因受苦。<br/>','',54471,8006);
INSERT INTO stanza VALUES('Z164','9','☆你已借死毁坏魔鬼，<br/>使我从死得释放；<br/>今借生命使我成圣，<br/>还要带我进荣光。<br/>','',54472,8007);
INSERT INTO stanza VALUES('Z164','10','今向我们-你的弟兄，<br/>在此传扬父的名；<br/>你在会中颂扬父神，<br/>我们和声同响应。<br/>','',54473,8008);
INSERT INTO stanza VALUES('Z164','11','☆好像造者之于房屋，<br/>你比摩西更尊荣；<br/>你是使徒，神所差来，<br/>配得更多的敬重。<br/>','',54474,8009);
INSERT INTO stanza VALUES('Z164','12','你是我们真约书亚，<br/>带领我们进安息；<br/>你是我们完满救恩，<br/>我们信心全在你。<br/>','',54475,8010);
INSERT INTO stanza VALUES('Z164','13','你是我们属天安息，<br/>现今住在我灵里；<br/>给我进入，享你丰富，<br/>犹如进入那美地。<br/>','',54476,8011);
INSERT INTO stanza VALUES('Z164','14','☆蒙神选召作大祭司，<br/>你比亚伦更尊荣；<br/>圣洁、无疵，高过诸天，<br/>体恤、代祷圣所中。<br/>','',54477,8012);
INSERT INTO stanza VALUES('Z164','15','你是那真麦基洗德，<br/>借着生命的大能，<br/>正在我们需要时候，<br/>以『饼和酒』来供应。<br/>','',54478,8013);
INSERT INTO stanza VALUES('Z164','16','你是我们更美祭物，<br/>借着永远的圣灵，<br/>曾经为我向神献上，<br/>使我今享其功能。<br/>','',54479,8014);
INSERT INTO stanza VALUES('Z164','17','☆更美之约你为我立，<br/>借着你的更美血；<br/>借你我今得有分于<br/>这个可靠的新约。<br/>','',54480,8015);
INSERT INTO stanza VALUES('Z164','18','你是这约合法立者，<br/>如此资格惟你有；<br/>你也是其胜任赐者，<br/>使我一切能承受。<br/>','',54481,8016);
INSERT INTO stanza VALUES('Z164','19','你今更是其执行者，<br/>借着复活的生命；<br/>你也是其有力中保，<br/>为我成全神命定。<br/>','',54482,8017);
INSERT INTO stanza VALUES('Z164','20','哦主，你今已在幔内，<br/>作我惟一的先锋，<br/>使我靠你出到营外，<br/>忠诚跟随你脚踪。<br/>','',54483,8018);
INSERT INTO stanza VALUES('Z164','21','☆你是我信的创始者，<br/>也是我信成终主；<br/>借信与爱，随你前行，<br/>向你我要永降服。<br/>','',54484,8019);
INSERT INTO stanza VALUES('Z164','22','☆你的价值无可比拟，<br/>我们珍爱你所是；<br/>你是如此完美、全备，<br/>远超人所能赏识。<br/>','',54485,8020);
INSERT INTO stanza VALUES('Z165','1','你是一切的祭物，<br/>为我神所豫备；<br/>哦，其意义何丰富、<br/>何其荣耀、甘美！<br/>成全父神的旨意，<br/>满足祂心所愿；<br/>应付我们的需要，<br/>所缺全都补满！<br/>','',54486,8021);
INSERT INTO stanza VALUES('Z165','2','你是馨香的燔祭，<br/>焚于神圣火焰；<br/>作神甜美的香气，<br/>满足神的心愿。<br/>你曾行在神面前，<br/>神旨是你所顾；<br/>献上无瑕的自己，<br/>为我作神食物。<br/>','',54487,8022);
INSERT INTO stanza VALUES('Z165','3','你是甜美的素祭，<br/>调油加上乳香；<br/>纯净、柔细又完全，<br/>甘美供神欣赏。<br/>你是完全平安祭，<br/>和平为我成就；<br/>且作食物何丰富，<br/>供我同神享受。<br/>','',54488,8023);
INSERT INTO stanza VALUES('Z165','4','你是我的赎罪祭，<br/>为我你曾成罪；<br/>借死成功了救赎，<br/>为要将我赎回。<br/>你也是我赎愆祭，<br/>担当我众罪愆，<br/>满足我神的公义，<br/>使我得蒙赦免。<br/>','',54489,8024);
INSERT INTO stanza VALUES('Z165','5','你也是我的摇祭，<br/>已经从死复活，<br/>阴府、死亡并黑暗，<br/>全都为我胜过。<br/>你更是我的举祭，<br/>为我升到神前，<br/>作我天界的食物，<br/>使我得到饱满。<br/>','',54490,8025);
INSERT INTO stanza VALUES('Z166','1','哦主，在你名里聚集，<br/>任何不见惟见你，<br/>你的同在使我欢喜，<br/>呼召我心来归依。<br/>','',54491,8026);
INSERT INTO stanza VALUES('Z166','2','爱我之爱无知其限，<br/>除了父对你的爱；<br/>父神对你所有意念，<br/>我心宝贵又感戴。<br/>','',54492,8027);
INSERT INTO stanza VALUES('Z166','3','父的喜悦、安息、喜乐，<br/>一切全都在于你；<br/>惟有你心能够测度，<br/>父在你身之珍惜。<br/>','',54493,8028);
INSERT INTO stanza VALUES('Z166','4','父将祂爱全置于你，<br/>称你作祂的爱子；<br/>然而为我未曾爱惜，<br/>为我得生要你死。<br/>','',54494,8029);
INSERT INTO stanza VALUES('Z166','5','将来见你如你所是，<br/>我要如何的欢唱！<br/>哦，主耶稣，你的名字，<br/>在神心中永馨香！<br/>','',54495,8030);
INSERT INTO stanza VALUES('Z166','6','喜乐音调、不息歌唱、<br/>永远赞美的颂辞、<br/>荣耀诗章、永增欢畅，<br/>一直继续到永世。<br/>','',54496,8031);
INSERT INTO stanza VALUES('Z167','1','恩主，你是生命源，<br/>深而且甜之泉：<br/>你的活水我已尝，<br/>永不再渴再干。<br/>你的怜悯时扩展，<br/>丰满如同海洋；<br/>你的恩典够我用，<br/>是你智慧所量。<br/>','',54497,8032);
INSERT INTO stanza VALUES('Z167','2','我乃属我的良人，<br/>我的良人属我；<br/>你将污秽的罪人，<br/>带进你宴筵所。<br/>你的功绩我所倚，<br/>你外别无可投；<br/>隐藏在你面光中，<br/>享受你的保守。<br/>','',54498,8033);
INSERT INTO stanza VALUES('Z167','3','新妇所爱非妆饰，<br/>乃是良人自己；<br/>我所注视非荣耀，<br/>乃是你的美丽：<br/>非你所赐的冠冕，<br/>乃你被钉之手；<br/>恩主，你是我荣耀，<br/>我的永远倚投。<br/>','',54499,8034);
INSERT INTO stanza VALUES('Z168','1','主耶稣，当我们想到<br/>你的一切恩爱，<br/>我们的灵盼望最好<br/>当面见你丰采。<br/>','',54500,8035);
INSERT INTO stanza VALUES('Z168','2','虽然我们行在野地，<br/>寂寞、干渴、骇惊，<br/>左右荆棘，前后蒺藜，<br/>四围仇敌陷阱。<br/>','',54501,8036);
INSERT INTO stanza VALUES('Z168','3','我们却从深处着想，<br/>知道你爱价值；<br/>我们因此心里明亮，<br/>赞美你恩不置。<br/>','',54502,8037);
INSERT INTO stanza VALUES('Z168','4','你是我们生命、力量、<br/>盾牌、磐石、诗歌，<br/>无论怎样把你思想，<br/>总叫我们快乐。<br/>','',54503,8038);
INSERT INTO stanza VALUES('Z168','5','可爱的主，保守我们<br/>紧紧跟随你行，<br/>直到我们进入天门，<br/>面见你的荣形。<br/>','',54504,8039);
INSERT INTO stanza VALUES('Z169','1','耶稣，耶稣，我的性命，<br/>因为爱的缘故，<br/>求原谅我，将你圣名，<br/>日念千遍不住。<br/>','',54505,8040);
INSERT INTO stanza VALUES('Z169','chorus','耶稣，耶稣，最爱救主，<br/>无人无物与你比拟，<br/>你的笑容是我欢喜，<br/>我爱，…爱你，<br/>…你，…主。<br/>','',54506,8041);
INSERT INTO stanza VALUES('Z169','2','我心爱你，不知如何<br/>约束我的奇乐；<br/>你爱有如一团热火，<br/>使我心中火热。<br/>','',54507,8042);
INSERT INTO stanza VALUES('Z169','3','因你是我一切一切、<br/>我的倚靠、食粮、<br/>我心『羡慕、』<br/>我身医药、<br/>我魂永远力量。<br/>','',54508,8043);
INSERT INTO stanza VALUES('Z169','4','烧、烧，哦爱，<br/>在我心怀，<br/>日夜厉害的烧，<br/>直至所有其他的爱<br/>烧到无处可找。<br/>','',54509,8044);
INSERT INTO stanza VALUES('Z169','5','暗中之光、忧中之乐、<br/>天在地上开始；<br/>耶稣，你是我爱、我歌，<br/>有谁知你价值！<br/>','',54510,8045);
INSERT INTO stanza VALUES('Z169','6','这爱将受甚么限制？<br/>要到那里停止？<br/>进、进，我主，<br/>甘甜价值<br/>今日远胜昨日。<br/>','',54511,8046);
INSERT INTO stanza VALUES('Z169','chorus','耶稣，耶稣，最爱救主，<br/>无人无物与你比拟，<br/>你的笑容是我欢喜，<br/>我爱，…爱你，<br/>…你，…主。<br/>第三节的『羡慕』作名词用。<br/>','',54512,8047);
INSERT INTO stanza VALUES('Z170','1','恩主，<br/>我心对你所爱、所宝，<br/>在此，<br/>我口都要欢乐发表；<br/>你这复活，<br/>作我福分的主，<br/>现今我要向你献上称祝。<br/>','',54513,8048);
INSERT INTO stanza VALUES('Z170','2','在此，<br/>你给我们再次尝到<br/>你的同在何其<br/>可爱、可宝；<br/>在你荫下<br/>我们欢乐、安息，<br/>你的美果我们饱尝不已。<br/>','',54514,8049);
INSERT INTO stanza VALUES('Z170','3','你曾孤单，<br/>直至落到死地，<br/>像粒麦子结出许多子粒；<br/>借着复活生出许多弟兄，<br/>使你一切我们都能与共。<br/>','',54515,8050);
INSERT INTO stanza VALUES('Z170','4','哦主，<br/>你今作了<br/>我们一切，<br/>在你里面我们一无所缺；<br/>你已满足我们所有需要，<br/>我心感铭，<br/>我口永要称道。<br/>','',54516,8051);
INSERT INTO stanza VALUES('Z171','1','耶稣，只要一想到你，<br/>我心就满甘甜；<br/>但这甘甜还远不及<br/>亲眼看见你面。<br/>','',54517,8052);
INSERT INTO stanza VALUES('Z171','2','无口能唱，无心能思，<br/>也无记性能忆<br/>一种声音比你名字<br/>更为甘甜、可喜。<br/>','',54518,8053);
INSERT INTO stanza VALUES('Z171','3','你是痛悔者的希望，<br/>温柔者的喜乐；<br/>你对寻求者何善良，<br/>跌倒者何仁德。<br/>','',54519,8054);
INSERT INTO stanza VALUES('Z171','4','但对寻得你者如何？<br/>无口无笔能述；<br/>耶稣的爱，其深、其阔，<br/>惟被爱者略熟。<br/>','',54520,8055);
INSERT INTO stanza VALUES('Z171','5','耶稣！你是世人之光，<br/>你是生命之源！<br/>远超一切我之所享、<br/>一切我所能羡。<br/>','',54521,8056);
INSERT INTO stanza VALUES('Z171','6','你外我无别的源头<br/>能解我心干渴；<br/>无穷宝泉！活水涌流！<br/>别流全都干涸。<br/>','',54522,8057);
INSERT INTO stanza VALUES('Z171','7','耶稣，你今是我喜乐，<br/>将来是我赏赐；<br/>你是我的荣耀、诗歌，<br/>从今直到永世。<br/>','',54523,8058);
INSERT INTO stanza VALUES('Z172','1','哦主，你是人心之乐，<br/>生命之源，人们之光，<br/>从地所给最佳福乐，<br/>空心转来向你仰望。<br/>','',54524,8059);
INSERT INTO stanza VALUES('Z172','2','你的真实永存不变，<br/>凡求你者，你都提挈：<br/>对寻求者，你是慈善，<br/>对寻得者，你是一切。<br/>','',54525,8060);
INSERT INTO stanza VALUES('Z172','3','生命的粮，我已尝过，<br/>仍是切慕尝食不已；<br/>活水的泉，我饮虽多，<br/>仍是渴望更多饮你。<br/>','',54526,8061);
INSERT INTO stanza VALUES('Z172','4','当那易变之福改变，<br/>不安的灵对你渴慕；<br/>欢喜，因见你的笑脸，<br/>有福，凭信将你抓住。<br/>','',54527,8062);
INSERT INTO stanza VALUES('Z172','5','愿你作我力量、维持！<br/>使我时时宁静、明亮，<br/>驱尽黑暗罪恶之思，<br/>向我倒下你的圣光。<br/>','',54528,8063);
INSERT INTO stanza VALUES('Z173','1','我们照你恩惠话语，<br/>带着谦卑心意，<br/>受死的主，我们会聚，<br/>现今来记念你。<br/>','',54529,8064);
INSERT INTO stanza VALUES('Z173','2','你的身体为我裂开，<br/>要成我的供给；<br/>我今举起立约杯来，<br/>为的是记念你。<br/>','',54530,8065);
INSERT INTO stanza VALUES('Z173','3','能否我忘客西马尼，<br/>或看你的孤寂、<br/>你的血汗和你哭泣，<br/>而不来记念你？<br/>','',54531,8066);
INSERT INTO stanza VALUES('Z173','4','当我转眼看十字架，<br/>看你在髑髅地，<br/>神的羔羊，我的救法，<br/>我必须记念你。<br/>','',54532,8067);
INSERT INTO stanza VALUES('Z173','5','记念你和你的苦痛、<br/>和你对我爱意，<br/>一息尚存、一脉尚动，<br/>我必定记念你。<br/>','',54533,8068);
INSERT INTO stanza VALUES('Z173','6','当我渐衰，嘴唇无音，<br/>思想、记忆软弱，<br/>当你在你国度降临，<br/>主，求你记念我。<br/>','',54534,8069);
INSERT INTO stanza VALUES('Z174','1','主举爱旗遮盖我们<br/>同来享受祂爱筵；<br/>我们感激救赎大恩，<br/>全心虔诚来记念。<br/>桌上陈设这饼和杯，<br/>都是表明你的爱；<br/>我们一同领你恩惠，<br/>我们一同来敬拜。<br/>','',54535,8070);
INSERT INTO stanza VALUES('Z174','2','我们记念你曾临世，<br/>成了奴仆历艰苦；<br/>你受试探，你常禁食，<br/>劳碌并无枕首处。<br/>我们记念你寻罪人，<br/>常受顶撞和饥渴；<br/>如有一人悔改归神，<br/>你认流血也值得。<br/>','',54536,8071);
INSERT INTO stanza VALUES('Z174','3','我们记念你钉十架，<br/>被人定罪、被神弃，<br/>独自支付我们赎价，<br/>你显你爱的无极；<br/>我们记念你今在天，<br/>在神右边常代求；<br/>你曾应许还要显现，<br/>主阿，求你快成就。<br/>','',54537,8072);
INSERT INTO stanza VALUES('Z175','1','在此分享这福杯，<br/>怎能闭口不赞美？<br/>你为我流的宝血，<br/>价值谁能尽领会！<br/>哦主，你血何宝贵！<br/>我的问题全应付；<br/>因你有效的宝血，<br/>一切忧惧都消除。<br/>','',54538,8073);
INSERT INTO stanza VALUES('Z175','2','借这有效的宝血，<br/>新约为我得成立；<br/>为着这个更美约，<br/>牠是稳固的根基。<br/>我们已蒙神救赎，<br/>并非凭着金或银，<br/>乃是凭着你宝血，<br/>就是在此我所饮。<br/>','',54539,8074);
INSERT INTO stanza VALUES('Z175','3','为使我罪得洗净，<br/>洗罪之血你已流；<br/>这血为我满足神<br/>一切公义的要求。<br/>用你有力洁净血，<br/>你将我罪已洗尽；<br/>并且洗净我良心，<br/>使我事奉永活神。<br/>','',54540,8075);
INSERT INTO stanza VALUES('Z175','4','借你分别的宝血，<br/>我们都已得成圣；<br/>借你保守的宝血，<br/>圣别成为我见证。<br/>借你赎罪的宝血，<br/>我们都已得称义；<br/>借你救赎的宝血，<br/>我得与神无距离。<br/>','',54541,8076);
INSERT INTO stanza VALUES('Z175','5','借你十架所流血，<br/>我们已与神和好；<br/>使我能以接触神，<br/>与神平安的相交。<br/>借着有分你的血，<br/>我已得着你生命；<br/>凭你宝血和生命，<br/>享受自由和安宁。<br/>','',54542,8077);
INSERT INTO stanza VALUES('Z175','6','在天你所洒的血，<br/>为我说出更美事；<br/>在这血的护庇下，<br/>我脱撒但的攻势。<br/>靠你得胜的宝血，<br/>我们胜过那仇敌；<br/>如此对那控告者，<br/>我们就能得胜利。<br/>','',54543,8078);
INSERT INTO stanza VALUES('Z175','7','我们借着你的血，<br/>与众圣徒同交通；<br/>在你这血遮盖下，<br/>我灵自由无惊恐。<br/>我们何能用话语，<br/>说尽你血的故事，<br/>我们需要那永世，<br/>来说你血的价值。<br/>','',54544,8079);
INSERT INTO stanza VALUES('Z176','1','在你爱的筵席上，<br/>有杯陪饼同陈列；<br/>这些表记我分享，<br/>就得饱尝你超越。<br/>为着这杯我感谢，<br/>就是你赐的福杯，<br/>也是丰满救恩杯，<br/>你借你血所豫备。<br/>','',54545,8080);
INSERT INTO stanza VALUES('Z176','2','这是你流的宝血，<br/>使我罪恶得清洗；<br/>这是你立的新约，<br/>使我得着神福气。<br/>你已喝了忿怒杯，<br/>为我尝尽了死味；<br/>如此买了这福杯，<br/>永作我分，福全备。<br/>','',54546,8081);
INSERT INTO stanza VALUES('Z176','3','亚当堕落失去神，<br/>在这分内我得回；<br/>借着你所流的血，<br/>神就成为我恩惠。<br/>救赎、生命并一切，<br/>在这分内都包括；<br/>凡神所愿并所筹，<br/>在这分内全归我。<br/>','',54547,8082);
INSERT INTO stanza VALUES('Z176','4','这是我们的永分，<br/>神圣、满溢的福杯；<br/>在神设计的杯里，<br/>尝到属天的滋味。<br/>在此因爱饮这杯，<br/>恩主，为着记念你；<br/>灵中如此的饮领，<br/>满享加略的功绩。<br/>','',54548,8083);
INSERT INTO stanza VALUES('Z177','1','哦主，这是何等神迹，<br/>你我竟然联合为一！<br/>我在你内，你在我里，<br/>真是希奇，真是奥秘！<br/>','',54549,8084);
INSERT INTO stanza VALUES('Z177','2','为使我能有分于你，<br/>你竟为我舍了身体；<br/>并为使我脱离罪孽，<br/>你也为我流了宝血。<br/>','',54550,8085);
INSERT INTO stanza VALUES('Z177','3','你且复活化身圣灵，<br/>进入我灵作我生命，<br/>要我时常将你接领，<br/>享受你的一切丰盛。<br/>','',54551,8086);
INSERT INTO stanza VALUES('Z177','4','我们面对桌上表记，<br/>思念你的可爱自己！<br/>一面感激你的心意，<br/>一面重温你的经历。<br/>','',54552,8087);
INSERT INTO stanza VALUES('Z177','5','借着吃饼，借着喝杯，<br/>再来享受你的甘美；<br/>灵里吸取，灵里接受，<br/>灵里饱尝生命珍馐。<br/>','',54553,8088);
INSERT INTO stanza VALUES('Z177','6','深愿如此吃你、喝你，<br/>用灵接受你的自己，<br/>直到全人被你充满，<br/>让你得到真正记念！<br/>','',54554,8089);
INSERT INTO stanza VALUES('Z178','1','为这筵席我献感谢，<br/>饼、杯在此同陈列；<br/>借此享受你的自己，<br/>神圣爱筵何超绝。<br/>这饼是你所舍身体，<br/>我们在此同分享；<br/>这杯是你所流宝血，<br/>我们在此同饮尝。<br/>','',54555,8090);
INSERT INTO stanza VALUES('Z178','chorus','看，这神圣筵席！<br/>其上何等表记！<br/>意义深厚，永垂不朽，<br/>人知何能及！<br/>','',54556,8091);
INSERT INTO stanza VALUES('Z178','2','借着你的救赎之死，<br/>你将生命来分赐；<br/>你将自己给了我们，<br/>要我有分你所是。<br/>借着分享这饼、这杯，<br/>我们陈列你的死；<br/>在此吃喝你的自己，<br/>如此记念到永世。<br/>','',54557,8092);
INSERT INTO stanza VALUES('Z178','3','这饼在此也是指明<br/>你那奥秘的身体；<br/>借此与众肢体交通，<br/>见证身体的合一。<br/>这杯也是神圣福杯，<br/>我们现在所祝福；<br/>借着你血我们交通，<br/>与你所有的圣徒。<br/>','',54558,8093);
INSERT INTO stanza VALUES('Z178','4','你是我们永远的分，<br/>在此豫尝何有福；<br/>我们等候你的国度，<br/>你的显现我催促。<br/>当你显现在你国度，<br/>同着得胜的圣徒，<br/>重新享受你的自己，<br/>作你心爱的新妇。<br/>','',54559,8094);
INSERT INTO stanza VALUES('Z179','1','当我注视你这桌子，<br/>表记使我惊奇；<br/>一饼一杯分别陈列，<br/>照神所爱心意。<br/>','',54560,8095);
INSERT INTO stanza VALUES('Z179','2','这饼表明生命之粮，<br/>作我属天食物，<br/>借着你死给我分享，<br/>使我尝你丰富。<br/>','',54561,8096);
INSERT INTO stanza VALUES('Z179','3','这杯乃是神圣之分，<br/>你血为我成就；<br/>我们接受这一福杯，<br/>就得享神所有。<br/>','',54562,8097);
INSERT INTO stanza VALUES('Z179','4','在此借着分享这饼，<br/>吃你生命之粮；<br/>因爱如此将你记念，<br/>就得将你饱尝。<br/>','',54563,8098);
INSERT INTO stanza VALUES('Z179','5','借着同喝这一福杯，<br/>得享神的福气；<br/>如此欢乐将你记念，<br/>直到我们被提。<br/>','',54564,8099);
INSERT INTO stanza VALUES('Z179','6','借吃这饼，并喝这杯，<br/>你死我们陈列；<br/>见证你是我们生命，<br/>每日取用不竭。<br/>','',54565,8100);
INSERT INTO stanza VALUES('Z179','7','我们等候那日来到，<br/>与你一同坐席，<br/>更多享受你的自己，<br/>并要敬拜不已。<br/>','',54566,8101);
INSERT INTO stanza VALUES('Z180','1','在此我要，<br/>主，与你面对面，<br/>在此我要用信把握不见，<br/>在此我要更深认识恩典，<br/>将我疲劳都息在主脚前。<br/>','',54567,8102);
INSERT INTO stanza VALUES('Z180','2','在此我要吃主所赐美物，<br/>在此我要饮主所递福杯，<br/>在此我要忘记一切难处，<br/>再尝一次赦罪平安滋味。<br/>','',54568,8103);
INSERT INTO stanza VALUES('Z180','3','我虽有罪，<br/>但你却有公义，<br/>我虽污秽，<br/>但你却有宝血；<br/>哦主，<br/>你的宝血将我清洗，<br/>你的公义对付我的罪孽。<br/>','',54569,8104);
INSERT INTO stanza VALUES('Z180','4','除你之外，<br/>我无别的帮助；<br/>有你赐恩，<br/>我就不求人惠；<br/>有你的爱，<br/>我已心意满足；<br/>靠你能力，<br/>我要站住地位。<br/>以下三节在擘饼后唱<br/>','',54570,8105);
INSERT INTO stanza VALUES('Z180','5','席撤何速，<br/>表记的物已尽！<br/>酒饼虽无，<br/>拯救的爱未亡！<br/>宴筵已过，<br/>你仍在此亲近，<br/>亲近有加，<br/>作我万有君王！<br/>','',54571,8106);
INSERT INTO stanza VALUES('Z180','6','看哪，<br/>云柱今又离地上升，<br/>在这野地又要乘夜前征；<br/>你正招呼，<br/>我们紧紧随行，<br/>不久我们就到光明天城。<br/>','',54572,8107);
INSERT INTO stanza VALUES('Z180','7','上席罢席，<br/>次次我们聚散，<br/>如此聚散，<br/>摇指天上佳筵；<br/>时虽未至，<br/>我们却已豫尝<br/>他日天上羔羊婚娶喜宴。<br/>','',54573,8108);
INSERT INTO stanza VALUES('Z181','1','哦主耶稣，借着饼杯，<br/>我们陈列你的死；<br/>温习你爱所作所为，<br/>珍赏你死的价值。<br/>饼杯分列，身血分开，<br/>表明你死已成就；<br/>我心感戴，我灵敬拜，<br/>我口向你献歌讴。<br/>','',54574,8109);
INSERT INTO stanza VALUES('Z181','chorus','你尝死亡苦味，<br/>我饮救恩福杯！<br/>你爱所作所为，<br/>配得永远赞美！<br/>','',54575,8110);
INSERT INTO stanza VALUES('Z181','2','你爱叫你为我流血，<br/>为要引我到神前；<br/>使我与神不再隔绝，<br/>随时得见神圣面。<br/>神的荣耀、圣洁、公义，<br/>所有要求已满足；<br/>我能借着你死功绩，<br/>坦然与神来接触。<br/>','',54576,8111);
INSERT INTO stanza VALUES('Z181','3','你死已将幔子裂开，<br/>为我打通至圣所，<br/>除去我与神的阻碍，<br/>使我能到施恩座，<br/>得神怜恤，蒙神恩惠，<br/>作我应时的帮助，<br/>如同饮到生命活水，<br/>饱尝神性的丰富。<br/>','',54577,8112);
INSERT INTO stanza VALUES('Z181','4','你既如此将我赎回，<br/>就使我能作祭司，<br/>得享神的一切甘美，<br/>常在神前供圣职。<br/>如此福气、如此恩典，<br/>全都由于你受死；<br/>我愿不断如此记念，<br/>直到喝新的日子。<br/>','',54578,8113);
INSERT INTO stanza VALUES('Z182','1','在你首次要显你死之时，<br/>你曾祷告要你子民合一；<br/>求使我们每次显你的死，<br/>我们都能成功你的旨意。<br/>只有一饼，<br/>我们只成一体，<br/>借着这个擘饼来作表记。<br/>','',54579,8114);
INSERT INTO stanza VALUES('Z182','2','我们为你所有召会祷告，<br/>求使我们不再分裂排逼，<br/>求你吸引我们彼此紧靠，<br/>借你吸引我们都紧靠你。<br/>我们就能<br/>只有一饼、一体，<br/>借着这个擘饼来作表记。<br/>','',54580,8115);
INSERT INTO stanza VALUES('Z182','3','我们也为离群的羊祈求，<br/>良好牧人，<br/>求带他们回来，<br/>回到真理，<br/>当初门徒所有，<br/>回到召会，<br/>当初真理所在；<br/>不久，<br/>我们只有一饼、一体，<br/>借着这个擘饼来作表记。<br/>','',54581,8116);
INSERT INTO stanza VALUES('Z182','4','主阿，<br/>不久所有表记过去，<br/>我们要在天上锡安合一，<br/>与众圣徒享受平安不渝，<br/>与众圣徒彼此相爱无极；<br/>更为可乐，<br/>能同神的儿子<br/>同享爱与平安，<br/>永远不止。<br/>','',54582,8117);
INSERT INTO stanza VALUES('Z183','1','咒诅祂受，祝福我享；<br/>苦杯祂饮，爱筵我尝；<br/>恩爱高深，谁能测量？<br/>我的心哪，应当歌唱！<br/>','',54583,8118);
INSERT INTO stanza VALUES('Z184','1','主耶稣，当那晚间，<br/>世人在你旁边，<br/>用尽黑暗的工夫，<br/>叫你圣心受苦；<br/>那时，你对我们说：<br/>『如此行，记念我；』<br/>我们听话今聚集，<br/>为的来记念你。<br/>','',54584,8119);
INSERT INTO stanza VALUES('Z184','2','怒气的杯何等苦！<br/>但你为我们茹；<br/>死亡的浸何等深！<br/>但你为我们沉；<br/>可怜你在髑髅地，<br/>竟被父神离弃；<br/>主，我们满心感激，<br/>不能不记念你。<br/>','',54585,8120);
INSERT INTO stanza VALUES('Z184','3','我想当日的幽冥，<br/>怎样攻逼你灵；<br/>又想洪涛和波澜，<br/>怎样将你冲漫；<br/>但在那里，我看见<br/>你的恩爱无限；<br/>主，我们忧喜交集，<br/>现在来记念你。<br/>','',54586,8121);
INSERT INTO stanza VALUES('Z184','4','我们知你已复活，<br/>作死人初熟果；<br/>我们见你坐父右，<br/>作召会荣耀头。<br/>我们因你蒙悦纳，<br/>身、心都得救拔；<br/>不然怎会想慕你，<br/>这样来记念你？<br/>','',54587,8122);
INSERT INTO stanza VALUES('Z184','5','你若尚未得荣来，<br/>接我免去大灾，<br/>叫我与你永同在，<br/>安息直到万代；<br/>我还要效法你死，<br/>还要表明你死，<br/>还要竭力敬爱你，<br/>还要来记念你。<br/>','',54588,8123);
INSERT INTO stanza VALUES('Z185','1','为着这饼我感谢你，<br/>这是神圣表记；<br/>借此，恩主，我得看见<br/>神计画的奥秘。<br/>','',54589,8124);
INSERT INTO stanza VALUES('Z185','2','这饼指明你的身体，<br/>你为我们舍弃，<br/>使我有分你的生命，<br/>并得你的自己。<br/>','',54590,8125);
INSERT INTO stanza VALUES('Z185','3','你的身体为我裂开，<br/>为将自己分授，<br/>使我能得你作生命，<br/>成为你的配偶。<br/>','',54591,8126);
INSERT INTO stanza VALUES('Z185','4','如此，这饼也是指明<br/>你那奥秘身体；<br/>我们是祂活的肢体，<br/>与你完全合一。<br/>','',54592,8127);
INSERT INTO stanza VALUES('Z185','5','我们虽是许多子粒，<br/>却都成为一饼；<br/>在此这样将你记念，<br/>从你得到供应。<br/>','',54593,8128);
INSERT INTO stanza VALUES('Z185','6','借着这饼我们交通，<br/>使你心满意足；<br/>同众圣徒如此交通，<br/>见证你的丰富。<br/>','',54594,8129);
INSERT INTO stanza VALUES('Z186','1','神圣、爱的珍馐，<br/>乃是出于恩典；<br/>借着享受这饼与酒，<br/>我们将你记念。<br/>','',54595,8130);
INSERT INTO stanza VALUES('Z186','2','在此我们都愿<br/>从你得以看见：<br/>你父对你所有心愿，<br/>并你所赐恩典。<br/>','',54596,8131);
INSERT INTO stanza VALUES('Z186','3','我灵今已满足，<br/>我心今作见证：<br/>生命之饼，甜美、丰富，<br/>作我生命供应。<br/>','',54597,8132);
INSERT INTO stanza VALUES('Z186','4','良心不再定罪，<br/>信心欢乐宣告：<br/>赎罪之血何其宝贵，<br/>满足神之所要。<br/>','',54598,8133);
INSERT INTO stanza VALUES('Z186','5','今享这个筵席，<br/>如此神圣、甜美，<br/>等到那日与你再席，<br/>甜美岂只万倍！<br/>','',54599,8134);
INSERT INTO stanza VALUES('Z186','6','那时得见你面，<br/>穿上你的荣形；<br/>所有你的奇妙恩典，<br/>我要永远见证。<br/>','',54600,8135);
INSERT INTO stanza VALUES('Z187','1','为着这饼和这杯，<br/>为着神子曾降卑，<br/>为着神恩如雨沛，<br/>主，我们感谢你。<br/>','',54601,8136);
INSERT INTO stanza VALUES('Z187','2','依然是酒、依然饼，<br/>借此信心却看明<br/>爱心神圣的小影，<br/>主，我们感谢你。<br/>','',54602,8137);
INSERT INTO stanza VALUES('Z187','3','为着你曾召我们，<br/>举目仰望你救恩，<br/>借着信心近你身，<br/>主，我们感谢你。<br/>','',54603,8138);
INSERT INTO stanza VALUES('Z187','4','为着你曾发命令，<br/>要我记念你行径-<br/>何等温柔、何等贫，<br/>主，我们感谢你。<br/>','',54604,8139);
INSERT INTO stanza VALUES('Z187','5','为着你曾用慈爱，<br/>引我想家在天外-<br/>『行此直等到我来，』<br/>主，我们感谢你。<br/>','',54605,8140);
INSERT INTO stanza VALUES('Z187','6','直到祂来，我擘饼，<br/>表明祂作我生命，<br/>为我睡了、为我醒，<br/>主，我们感谢你。<br/>','',54606,8141);
INSERT INTO stanza VALUES('Z187','7','直到祂来，我饮杯，<br/>表明祂赐福全备，<br/>使我站在新地位，<br/>主，我们感谢你。<br/>','',54607,8142);
INSERT INTO stanza VALUES('Z187','7','为着再来的嘱咐，<br/>为着那日的紧速，<br/>为着荣耀和国度，<br/>主，我们感谢你。<br/>','',54608,8143);
INSERT INTO stanza VALUES('Z188','1','荣耀基督，太初就有，<br/>祂的根源在亘古！<br/>全能的神，早过宇宙，<br/>自有永有永远父；<br/>无生之始，无命之终，<br/>无父、无母、无族谱；<br/>永不改变，年数无穷，<br/>昔在、今在、永在主。<br/>','',54609,8144);
INSERT INTO stanza VALUES('Z188','2','荣耀基督，创造万有，<br/>万有独一的根源；<br/>万有主宰、万有元首，<br/>万有之间祂居先；<br/>用祂命令托住万有，<br/>万有靠祂而团结；<br/>神早立祂承受万有，<br/>万有归祂为基业。<br/>','',54610,8145);
INSERT INTO stanza VALUES('Z188','3','荣耀基督，道成肉身，<br/>支搭帐幕在人间；<br/>童女所生正式的人，<br/>神在肉身的显现。<br/>神而人者自甘卑微，<br/>取了奴仆的形状，<br/>是神荣耀所发光辉，<br/>是神本体的真像。<br/>','',54611,8146);
INSERT INTO stanza VALUES('Z188','4','荣耀基督，钉死十架，<br/>替我担罪并成罪，<br/>受神审判，被神所杀，<br/>尝尽死亡的苦味。<br/>将我旧人一同钉死，<br/>毁坏撒但和鬼魔，<br/>使我脱离罪的权势，<br/>脱离一切的网罗。<br/>','',54612,8147);
INSERT INTO stanza VALUES('Z188','5','荣耀基督，从死复活，<br/>成为复活初熟果；<br/>祂也使我同祂复活，<br/>将祂生命分给我。<br/>祂是一粒生命麦种，<br/>生出我们许多粒，<br/>成为祂的许多弟兄，<br/>与祂同是出于一。<br/>','',54613,8148);
INSERT INTO stanza VALUES('Z188','6','荣耀基督，化成圣灵，<br/>到我灵里作生命，<br/>使我有分神的性情，<br/>与祂同样的神圣。<br/>在我里面长大成形，<br/>将我变成祂形状；<br/>使我享受神的丰盛，<br/>有祂丰满的身量。<br/>','',54614,8149);
INSERT INTO stanza VALUES('Z188','7','荣耀基督，升上高天，<br/>远超一切的首领，<br/>得着尊贵、荣耀冠冕，<br/>并得至高的尊名。<br/>祂也带我与祂同升，<br/>与祂一同坐天上，<br/>使我分享祂的权柄，<br/>同祂一样的高强。<br/>','',54615,8150);
INSERT INTO stanza VALUES('Z188','7','荣耀基督，赐下圣灵，<br/>召会因此得成立；<br/>并赐恩赐，各尽功能，<br/>建造召会作身体。<br/>祂爱召会，保养、顾惜，<br/>借着召会得彰显；<br/>召会将祂延长、普及，<br/>延长、普及宇宙间。<br/>','',54616,8151);
INSERT INTO stanza VALUES('Z188','9','荣耀基督，得国再临，<br/>提接、救赎祂圣徒，<br/>践踏仇敌，审判万民，<br/>凭祂权柄设国度。<br/>带着圣徒一同作王，<br/>执政掌权到地极，<br/>万国和平，万有歌唱，<br/>全地都得享安息。<br/>','',54617,8152);
INSERT INTO stanza VALUES('Z188','10','荣耀基督，永世中心，<br/>得着圣城为配偶；<br/>天地一切全都更新，<br/>脱尽一切的陈旧。<br/>神是荣光，祂是明灯，<br/>神在祂内得彰显；<br/>圣城又是祂的显明，<br/>由祂充满到永远！<br/>','',54618,8153);
INSERT INTO stanza VALUES('Z189','1','美哉、善哉，<br/>羔羊的新歌；<br/>荣耀归主！荣耀归主！<br/>这个福音赐无比快乐，<br/>荣耀至高的主！<br/>耶稣基督降生下土，<br/>离去尊荣是为救赎，<br/>如此奇恩举世皆无，<br/>愚人也会感惊愕。<br/>','',54619,8154);
INSERT INTO stanza VALUES('Z189','chorus','大声赞美，口唱连心和，<br/>荣耀归主！荣耀归主！<br/>自古以来无此诗歌，<br/>荣耀至高的主！<br/>','',54620,8155);
INSERT INTO stanza VALUES('Z189','2','听哪，歌声由天飘扬来，<br/>荣耀归主！荣耀归主！<br/>祂就是光，祂也就是爱，<br/>荣耀至高的主！<br/>世界所有悲伤泪人，<br/>地上一切不安罪人，<br/>完全不管你是谁人，<br/>耶稣都已为还债。<br/>','',54621,8156);
INSERT INTO stanza VALUES('Z189','3','应当高歌，因审判已过，<br/>荣耀归主！荣耀归主！<br/>与主联合，我们已复活，<br/>荣耀至高的主！<br/>我们已在坟墓那边，<br/>立在死亡不到地点，<br/>仇敌浮沉红海中间，<br/>主赐称义的把握。<br/>','',54622,8157);
INSERT INTO stanza VALUES('Z189','4','唱哪，祂再降临接圣徒，<br/>荣耀归主！荣耀归主！<br/>不再耽延，召会已成熟，<br/>荣耀至高的主！<br/>今能看见前所求呼，<br/>也能领受久所羡慕，<br/>永能倾吐此心情愫，<br/>与祂只有一前途。<br/>','',54623,8158);
INSERT INTO stanza VALUES('Z189','5','此歌再唱声音应明朗，<br/>荣耀归主！荣耀归主！<br/>此歌题目应当一直唱，<br/>荣耀至高的主！<br/>唱至内心欢喜会跳，<br/>唱至天下布满此调，<br/>唱至所有蒙爱新造，<br/>都唱此歌不肯放。<br/>','',54624,8159);
INSERT INTO stanza VALUES('Z190','1','赞美！赞美！赞美耶稣，<br/>我救赎主！<br/>圣徒歌唱，<br/>将祂奇爱宣明；<br/>称颂！称颂！称颂基督！<br/>天使俯伏，<br/>能力、尊贵，<br/>归于祂的圣名！<br/>有如牧者，<br/>主将祂的人喂养，<br/>祂的膀臂怀抱他们安康。<br/>','',54625,8160);
INSERT INTO stanza VALUES('Z190','chorus','赞美！赞美！<br/>赞美祂的奇妙爱情！<br/>称颂！称颂！<br/>称颂祂的圣名。<br/>','',54626,8161);
INSERT INTO stanza VALUES('Z190','2','赞美！赞美！赞美耶稣，<br/>我救赎主！<br/>祂为我罪<br/>受苦、流血、受刑；<br/>称颂！称颂！称颂<br/>祂是磐石稳固，<br/>为成永远救恩，<br/>十架被钉！<br/>高声赞祂！<br/>主担当我的痛苦！<br/>此爱奇妙，<br/>贞坚、绝顶、丰富。<br/>','',54627,8162);
INSERT INTO stanza VALUES('Z190','3','赞美！赞美！赞美耶稣，<br/>我救赎主！<br/>响彻天门，<br/>『和散那』声飞扬！<br/>加冠！加冠！加冠<br/>祂作万有之主，<br/>复兴万物，<br/>永作祭司，君王！<br/>神的基督，<br/>得胜一切，立国度，<br/>荣耀、权柄，<br/>永归我主耶稣！<br/>','',54628,8163);
INSERT INTO stanza VALUES('Z191','1','那爱我们，怜悯我们，<br/>在凡事恩待我们，<br/>白白流血拯救我们，<br/>舍命，活我们的主，<br/>但愿权能、荣耀、国度，<br/>归给祂直到永古！<br/>','',54629,8164);
INSERT INTO stanza VALUES('Z192','1','主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要敬拜你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要敬拜你！<br/>','',54630,8165);
INSERT INTO stanza VALUES('Z192','2','主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要赞美你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要赞美你！<br/>','',54631,8166);
INSERT INTO stanza VALUES('Z192','3','主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要感谢你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要感谢你！<br/>','',54632,8167);
INSERT INTO stanza VALUES('Z192','4','主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要高举你！<br/>主，惟有你，<br/>主，惟有你，<br/>耶稣我救主，<br/>我要高举你！<br/>','',54633,8168);
INSERT INTO stanza VALUES('Z193','1','但愿尊贵、荣耀、丰富，<br/>归给羔羊直到永古！<br/>耶稣基督是我救主！<br/>阿利路亚！阿利路亚！<br/>阿利路亚！赞美主！<br/>','',54634,8169);
INSERT INTO stanza VALUES('Z194','1','神灵今是基督的灵，<br/>如此来作实际的灵。<br/>祂乃基督住在我灵，<br/>使祂作我实际供应。<br/>','',54635,8170);
INSERT INTO stanza VALUES('Z194','2','基督乃是神的化身，<br/>显明神的圣别性情；<br/>这灵也是基督化身，<br/>启示基督作我生命。<br/>','',54636,8171);
INSERT INTO stanza VALUES('Z194','3','神的本性一切丰满，<br/>全在基督有形有体；<br/>基督带着一切丰富，<br/>成为这灵来作实际。<br/>','',54637,8172);
INSERT INTO stanza VALUES('Z194','4','父在子里得着彰显，<br/>子今成为实际的灵；<br/>父是源头，子是流出，<br/>灵是流入作我供应。<br/>','',54638,8173);
INSERT INTO stanza VALUES('Z194','5','当灵刚强我里面人，<br/>基督安家在我心间，<br/>父所有的一切丰满，<br/>就将我人全都充满。<br/>','',54639,8174);
INSERT INTO stanza VALUES('Z194','6','在子里面我得着父，<br/>接受祂来应付所缺；<br/>在灵里面我经历子<br/>作我生命和我一切。<br/>','',54640,8175);
INSERT INTO stanza VALUES('Z194','7','求主用你神圣实际，<br/>借着你灵将我充满，<br/>使我得以充满了你，<br/>将你丰富享得完全。<br/>','',54641,8176);
INSERT INTO stanza VALUES('Z195','1','我在主前等候，<br/>并且专心祈祷，<br/>盼望能以从罪得释放；<br/>一日主施怜悯，<br/>答应我的求告，<br/>圣灵显在我心房。<br/>','',54642,8177);
INSERT INTO stanza VALUES('Z195','chorus','圣灵显在我心房，<br/>圣灵解开我捆绑，<br/>我就从罪得释放，<br/>我就心口满颂扬，<br/>圣灵显在我心房。<br/>','',54643,8178);
INSERT INTO stanza VALUES('Z195','2','我是多年软弱、<br/>残废、无用器皿，<br/>而又明知自己当刚强；<br/>主是忽然施恩，<br/>使我喜乐满心，<br/>圣灵显在我心房。<br/>','',54644,8179);
INSERT INTO stanza VALUES('Z195','3','我今能以见证<br/>圣灵奇妙能力，<br/>因为我心已经被开广；<br/>我已脱离骄傲，<br/>我已洗净罪习，<br/>圣灵显在我心房。<br/>','',54645,8180);
INSERT INTO stanza VALUES('Z195','4','我今已有把握，<br/>我能看见神面，<br/>因主已经将我洗透亮；<br/>主今住在我灵，<br/>作我够用恩典，<br/>圣灵显在我心房。<br/>','',54646,8181);
INSERT INTO stanza VALUES('Z196','1','今日我们神的灵，<br/>成了耶稣基督灵；<br/>死而复活的神人，<br/>得荣升天，此灵成。<br/>','',54647,8182);
INSERT INTO stanza VALUES('Z196','2','从那升天的耶稣，<br/>这灵降到我灵里，<br/>使祂一切的实际，<br/>都成我们的经历。<br/>','',54648,8183);
INSERT INTO stanza VALUES('Z196','3','这个耶稣基督灵，<br/>包含一切的成分；<br/>神、人二性其中存，<br/>人生、神荣也藏隐。<br/>','',54649,8184);
INSERT INTO stanza VALUES('Z196','4','死的功能及受苦、<br/>复活大能并升天、<br/>宝座、权柄和国度，<br/>全都在这灵中含。<br/>','',54650,8185);
INSERT INTO stanza VALUES('Z196','5','凭这一切的成分，<br/>这灵运行在我灵；<br/>借祂膏油的涂抹，<br/>我得享受主丰盛。<br/>','',54651,8186);
INSERT INTO stanza VALUES('Z196','6','这个包罗万有灵，<br/>是我一切的秘诀；<br/>多方作工在我里，<br/>使神作我的一切。<br/>','',54652,8187);
INSERT INTO stanza VALUES('Z197','1','应当将此消息，<br/>遍传有人之地；<br/>只要有人有心，<br/>只要有人饮泣；<br/>信徒就当殷勤，<br/>传此喜乐信息：<br/>保惠师已经来！<br/>','',54653,8188);
INSERT INTO stanza VALUES('Z197','chorus','保惠师已经来！<br/>保惠师已经来！<br/>主所应许已赐，<br/>圣灵从天来此；<br/>应当将此消息，<br/>遍传有人之地，<br/>保惠师已经来！<br/>','',54654,8189);
INSERT INTO stanza VALUES('Z197','2','漫漫黑夜已过，<br/>最终晨晓已破，<br/>悲哭声音停止，<br/>哀求声音不作，<br/>远山现出金丝，<br/>晨曦已在炳烁：<br/>保惠师已经来！<br/>','',54655,8190);
INSERT INTO stanza VALUES('Z197','3','请看万王之王，<br/>带着医治之光，<br/>来使属灵囚犯，<br/>都得完全释放；<br/>现今空虚牢监，<br/>到处凯歌高唱：<br/>保惠师已经来！<br/>','',54656,8191);
INSERT INTO stanza VALUES('Z197','4','无限神圣的爱！<br/>我的拙口缺才，<br/>向着流浪的人，<br/>说你无比恩爱-<br/>我怎是个罪身，<br/>你竟肯来同在：<br/>保惠师已经来！<br/>','',54657,8192);
INSERT INTO stanza VALUES('Z197','5','唱阿，直到回响<br/>飞射上下碧苍；<br/>所有使者在上<br/>响应在下声浪，<br/>无穷的爱颂扬，<br/>我来引吭歌唱：<br/>保惠师已经来！<br/>','',54658,8193);
INSERT INTO stanza VALUES('Z198','1','世人看你不过仍是<br/>平常的拿撒勒人，<br/>活在地上常受轻视，<br/>十字架上终舍身。<br/>从人眼光你的历史<br/>到此已经无下文。<br/>','',54659,8194);
INSERT INTO stanza VALUES('Z198','2','天上情形何等不同！<br/>当你升天的时候，<br/>荣耀的神因你顺从，<br/>已命宇宙在等候，<br/>准备迎接、准备歌颂<br/>你作宇宙的元首。<br/>','',54660,8195);
INSERT INTO stanza VALUES('Z198','3','神已设立你为基督，<br/>神已设立你为主，<br/>天上地下已经无处<br/>不知你今的特独，<br/>没有一个能不俯伏，<br/>没有一个不顺服。<br/>','',54661,8196);
INSERT INTO stanza VALUES('Z198','4','远在天上发生的事，<br/>我今如何能知情？<br/>因神要证此事属实，<br/>祂就从天降圣灵，<br/>在我身上成为恩赐，<br/>来证耶稣得权柄。<br/>','',54662,8197);
INSERT INTO stanza VALUES('Z198','5','我身所显圣灵停驻，<br/>证明耶稣是基督，<br/>神立基督若是耶稣，<br/>我身必有圣灵注；<br/>永远真实、永远坚固，<br/>拿撒勒人已是主。<br/>','',54663,8198);
INSERT INTO stanza VALUES('Z198','6','耶稣是主！耶稣是主！<br/>永不改变的事实！<br/>我被圣灵已经灌注，<br/>也是事实的恩赐；<br/>我今只能赞美称祝，<br/>圣灵恩赐已开始。<br/>','',54664,8199);
INSERT INTO stanza VALUES('Z199','1','荣耀的主，你曾经<br/>从天赐下你圣灵；<br/>将祂各种的恩惠，<br/>赐你在下的召会；<br/>求你凭你的信实，<br/>再次赐下你恩赐。<br/>','',54665,8200);
INSERT INTO stanza VALUES('Z199','2','我今已经奉你名，<br/>受浸归你成一灵；<br/>你的身体已得有<br/>所有恩赐和成就；<br/>因我也是一肢体，<br/>不能不也得能力。<br/>','',54666,8201);
INSERT INTO stanza VALUES('Z199','3','赐我能力来证明<br/>你是已得最高名；<br/>赐我恩赐来传说<br/>你救罪人的工作；<br/>赐我知识来事奉，<br/>使你子民能得胜。<br/>','',54667,8202);
INSERT INTO stanza VALUES('Z199','4','当我在此受按手、<br/>在此许愿的时候，<br/>在此严肃望恩赐，<br/>求你按你的事实，<br/>倾下无穷的能力，<br/>来使每人作用器。<br/>','',54668,8203);
INSERT INTO stanza VALUES('Z200','1','现今神的圣别之灵，<br/>乃是神的生命之灵；<br/>将我点活，赐我生命，<br/>使我适合神所命定。<br/>','',54669,8204);
INSERT INTO stanza VALUES('Z200','2','祂作活水，解我干渴，<br/>永远供我生命水流；<br/>供应基督作我生命，<br/>我心愿望祂全成就。<br/>','',54670,8205);
INSERT INTO stanza VALUES('Z200','3','照亮我以生命之光，<br/>从我全人驱尽黑暗；<br/>供应基督作我亮光，<br/>使我黑夜变成中天。<br/>','',54671,8206);
INSERT INTO stanza VALUES('Z200','4','刚强我以生命大能，<br/>加力给我里面的人；<br/>供应基督作我能力，<br/>为神计画运行施恩。<br/>','',54672,8207);
INSERT INTO stanza VALUES('Z200','5','借着神圣生命的律，<br/>释放我脱罪恶的律；<br/>借着神的圣别性情，<br/>在我里面将我规律。<br/>','',54673,8208);
INSERT INTO stanza VALUES('Z200','6','祂作神的生命之灵，<br/>丰盛果子借我结出；<br/>显出神的各种美德，<br/>借着生命供人基督。<br/>','',54674,8209);
INSERT INTO stanza VALUES('Z200','7','生命之灵供应生命，<br/>用神生命将我变化；<br/>更新我的里面部分，<br/>使与基督相像无差。<br/>','',54675,8210);
INSERT INTO stanza VALUES('Z200','7','求主用你生命的灵，<br/>将我各部全都充满，<br/>直到全人尽都浸透，<br/>使你生命在我彰显。<br/>','',54676,8211);
INSERT INTO stanza VALUES('Z201','1','井阿，涌上水来！<br/>我愿被挖透！<br/>挖去一切障碍，<br/>活水好涌流！<br/>','',54677,8212);
INSERT INTO stanza VALUES('Z201','2','磐石已经裂开，<br/>活水已流出；<br/>流到我的心怀，<br/>竟然被堵住。<br/>','',54678,8213);
INSERT INTO stanza VALUES('Z201','3','我要祷告挖井，<br/>挖去我泥土；<br/>直到挖出圣灵，<br/>活水能流出。<br/>','',54679,8214);
INSERT INTO stanza VALUES('Z201','4','祷告还要祷告，<br/>挖了还要挖！<br/>直到挖得透了，<br/>祷告得练达。<br/>','',54680,8215);
INSERT INTO stanza VALUES('Z201','5','不需磐石再开，<br/>只要我挖透；<br/>不需活水再来，<br/>只要我涌流。<br/>','',54681,8216);
INSERT INTO stanza VALUES('Z201','6','圣灵降在我身，<br/>不过是浇灌；<br/>圣灵住在我心，<br/>才是活水泉。<br/>','',54682,8217);
INSERT INTO stanza VALUES('Z201','7','我所急切需要，<br/>非仅求浇灌，<br/>更是透彻祷告，<br/>挖通活水泉。<br/>','',54683,8218);
INSERT INTO stanza VALUES('Z201','7','挖到再无事物<br/>能将灵阻隔；<br/>挖到泉源涌出<br/>活水的江河！<br/>','',54684,8219);
INSERT INTO stanza VALUES('Z201','9','井阿，涌上水来！<br/>我愿被挖透！<br/>挖去一切障碍，<br/>活水好涌流！<br/>','',54685,8220);
INSERT INTO stanza VALUES('Z202','1','在旷野加低斯，<br/>以色列百姓，<br/>因干渴快要死，<br/>神就发命令：<br/>吩咐磐石发出活水来！<br/>击打勿再施，<br/>因早已裂开；<br/>只要吩咐，活水就流开。<br/>','',54686,8221);
INSERT INTO stanza VALUES('Z202','chorus','吩咐磐石发出活水来！<br/>圣灵早已赐，<br/>早与你同在；<br/>一切的丰富，<br/>等着你接受；<br/>你若肯信服，<br/>必享祂富有。<br/>','',54687,8222);
INSERT INTO stanza VALUES('Z202','2','那永久的磐石，<br/>今仍是裂开，<br/>神圣灵的恩赐，<br/>今仍在等待；<br/>祂仍在说，挣扎果为何？<br/>只与主死合，<br/>立刻解干渴；<br/>一经约但，就必得圣鸽。<br/>','',54688,8223);
INSERT INTO stanza VALUES('Z202','3','但愿心肯简单，<br/>完全的相信！<br/>但愿心能平安，<br/>不再苦求寻！<br/>如同婴孩，静卧主怀间，<br/>向世界断奶，<br/>饱尝祂爱甜，<br/>灵得安息，全由祂充满。<br/>','',54689,8224);
INSERT INTO stanza VALUES('Z203','1','生命活水的江河，<br/>流自天上的宝座，<br/>满带祝福而流着，<br/>从神基督流到我。<br/>','',54690,8225);
INSERT INTO stanza VALUES('Z203','chorus','生命活水的江河，<br/>人人可以白喝；<br/>愿这活水通过我，<br/>流到众人，解干渴。<br/>','',54691,8226);
INSERT INTO stanza VALUES('Z203','2','活水明亮如水晶，<br/>带着丰盛的供应，<br/>渴者喝了得生命，<br/>不需代价，乃白奉。<br/>','',54692,8227);
INSERT INTO stanza VALUES('Z203','3','哦主，修理、洁净我，<br/>使我成为你运河；<br/>倒空、充满、使用我，<br/>使我顺服无阻隔。<br/>','',54693,8228);
INSERT INTO stanza VALUES('Z203','4','这时，也惟有这时，<br/>水流才能无阻止；<br/>如此，也惟有如此，<br/>你的丰盛人才知。<br/>','',54694,8229);
INSERT INTO stanza VALUES('Z203','5','今将一切全奉献，<br/>全都带到主脚前；<br/>凡事只有一心愿，<br/>活水从我能溢漫。<br/>','',54695,8230);
INSERT INTO stanza VALUES('Z204','1','生命活水水晶河，<br/>流自天上的宝座，<br/>带着权柄施交通，<br/>无处不能流得通。<br/>','',54696,8231);
INSERT INTO stanza VALUES('Z204','chorus','生命活水在流通，<br/>处处都要流得通，<br/>带着权柄施交通，<br/>处处都要流得通。<br/>','',54697,8232);
INSERT INTO stanza VALUES('Z204','2','生命活水是圣灵，<br/>是神流出作生命，<br/>带着权柄而流通，<br/>处处都要流得通。<br/>','',54698,8233);
INSERT INTO stanza VALUES('Z204','3','河在精金街中流，<br/>表明路在何处有；<br/>活水若在神性流，<br/>在此就有路可走。<br/>','',54699,8234);
INSERT INTO stanza VALUES('Z204','4','河的两岸生命树，<br/>表明神来作食物，<br/>必须活水能流通，<br/>才能供应得无穷。<br/>','',54700,8235);
INSERT INTO stanza VALUES('Z204','5','主阿，你曾被裂开，<br/>为将活水流出来；<br/>求你也将我打破，<br/>让你活水能通过。<br/>','',54701,8236);
INSERT INTO stanza VALUES('Z205','1','活水涌流，活水涌流，<br/>涌自荣耀的圣殿，<br/>经过圣殿出入之口，<br/>并牠分别的界限。<br/>','',54702,8237);
INSERT INTO stanza VALUES('Z205','chorus','神的活水涌流，<br/>带来新鲜的供应，<br/>吞灭死亡，不稍存留，<br/>显出生命的丰盛。<br/>','',54703,8238);
INSERT INTO stanza VALUES('Z205','2','活水涌流，涌流通畅，<br/>为着神圣的荣耀，<br/>一切全献祭坛之上，<br/>凡事以此为首要。<br/>','',54704,8239);
INSERT INTO stanza VALUES('Z205','3','活水涌流，涌流无限，<br/>凡事都由神量过，<br/>经过神的量度审判，<br/>一切全归神得着。<br/>','',54705,8240);
INSERT INTO stanza VALUES('Z205','4','活水涌流，越流越盛，<br/>成为汹涌的江河，<br/>人就无法再有所行，<br/>只能靠恩而生活。<br/>','',54706,8241);
INSERT INTO stanza VALUES('Z206','1','主，我曾否叫圣灵忧愁，<br/>流荡、随便并冷落？<br/>然而我的犯罪和退后，<br/>未曾叫祂厌倦过。<br/>','',54707,8242);
INSERT INTO stanza VALUES('Z206','chorus','求你多赐我们以圣灵，<br/>让祂光照并焚烧，<br/>将『你』供给我们<br/>作生命，<br/>使我不住的祷告。<br/>','',54708,8243);
INSERT INTO stanza VALUES('Z206','2','你的圣灵曾如何忍耐，<br/>等我慢慢心转变；<br/>我曾如何弃绝你热爱，<br/>当祂为我忧心煎。<br/>','',54709,8244);
INSERT INTO stanza VALUES('Z206','3','你的圣灵今在我心内，<br/>我要以祂为我主；<br/>因为爱你使我能敬畏<br/>你的最小的宣布。<br/>','',54710,8245);
INSERT INTO stanza VALUES('Z206','4','我们现今虽不能爱你，<br/>如你那样爱我们；<br/>你在我心若将火点起，<br/>牠就不会终冷沉。<br/>','',54711,8246);
INSERT INTO stanza VALUES('Z207','1','神赐祂的能力<br/>在我穷苦心内，<br/>时刻保守提挈，<br/>灌以必需恩惠，<br/>借灵住我里面，<br/>掌管我的全人，<br/>用爱发出火焰，<br/>在我心内直焚。<br/>','',54712,8247);
INSERT INTO stanza VALUES('Z207','chorus','焚烧在我心内，<br/>焚烧在我心内；<br/>爱焰自天倾下，<br/>焚烧在我心内！<br/>圣灵已来保惠，<br/>主名应当赞美，<br/>爱焰自天倾下，<br/>焚烧在我心内！<br/>','',54713,8248);
INSERT INTO stanza VALUES('Z207','2','我在架下低头，<br/>我在坛上奉献，<br/>此生一切所有，<br/>都呈我主脚前；<br/>祂为我付赎价，<br/>祂召我得安息，<br/>祂使天火降下，<br/>悦纳我的活祭。<br/>','',54714,8249);
INSERT INTO stanza VALUES('Z207','3','我无任何功行，<br/>惟有神的应许；<br/>我借爱子受刑，<br/>蒙恩作神儿女。<br/>荣耀归于我神，<br/>阿利路亚，阿们；<br/>这爱激励至深，<br/>如火内心在焚。<br/>','',54715,8250);
INSERT INTO stanza VALUES('Z208','1','我今举手向你请，<br/>要你赐下焚烧灵，<br/>焚烧一切所欢喜，<br/>不留一点为自己。<br/>','',54716,8251);
INSERT INTO stanza VALUES('Z208','chorus','求你赐下焚烧灵，<br/>成我毕生大事情；<br/>满足我心的要求，<br/>用火焚烧到无有；<br/>等候，等候，<br/>我们等候焚烧灵。<br/>','',54717,8252);
INSERT INTO stanza VALUES('Z208','2','我今坛上来献祭，<br/>摆上全人灵、魂、体；<br/>求将情欲都解脱，<br/>并来充满每角落。<br/>','',54718,8253);
INSERT INTO stanza VALUES('Z208','3','我今真切已牺牲<br/>我所宝贝的一生，<br/>完全为着宝贝主，<br/>因祂流血来救赎。<br/>','',54719,8254);
INSERT INTO stanza VALUES('Z208','4','我今以信来领取<br/>血下权利的给予；<br/>靠你得胜的名字，<br/>所有应许成现实。<br/>','',54720,8255);
INSERT INTO stanza VALUES('Z209','1','耶稣，你的全胜的爱，<br/>已经浇灌我心，<br/>我心就不再会摇摆，<br/>就能生根于神，<br/>就能生根于神。<br/>','',54721,8256);
INSERT INTO stanza VALUES('Z209','2','但愿圣火今在我心，<br/>就已发旺不休；<br/>烧掉所有卑情下品，<br/>并使高山镕流。<br/>','',54722,8257);
INSERT INTO stanza VALUES('Z209','3','你曾赐下祭坛火炭，<br/>求你烧掉我罪；<br/>我向焚烧的灵呼喊，<br/>主灵，满我心内。<br/>','',54723,8258);
INSERT INTO stanza VALUES('Z209','4','我心要接锻炼的火，<br/>将我旧造烧绝；<br/>散布生命在每角落，<br/>并使全人圣洁。<br/>','',54724,8259);
INSERT INTO stanza VALUES('Z209','5','摇动的心求你扶掖，<br/>使牠变成坚崖；<br/>基督成为我的世界，<br/>我的全心成爱。<br/>','',54725,8260);
INSERT INTO stanza VALUES('Z210','1','主，求你向我吹圣灵，<br/>教我如何吸入你；<br/>助我向你胸怀一倾<br/>我的犯罪与自己。<br/>','',54726,8261);
INSERT INTO stanza VALUES('Z210','chorus','我是呼出我的愁苦，<br/>呼出我罪污；<br/>我是吸入，一直吸入，<br/>你所有丰富。<br/>','',54727,8262);
INSERT INTO stanza VALUES('Z210','2','我是呼出我的生命，<br/>我才可能被充满；<br/>放弃软弱或是力劲，<br/>吸入怜悯和恩湛。<br/>','',54728,8263);
INSERT INTO stanza VALUES('Z210','3','呼出我的罪律桎梏，<br/>你已为我全除摒；<br/>吸入你的圣洁丰富，<br/>发现惟你是生命。<br/>','',54729,8264);
INSERT INTO stanza VALUES('Z210','4','我正呼出我的忧愁<br/>在你慈爱的胸臆；<br/>吸入你的喜乐、保守，<br/>吸入你的甜安息。<br/>','',54730,8265);
INSERT INTO stanza VALUES('Z210','5','我正呼出我的病势，<br/>你早已为我负担；<br/>我正吸入你的医治，<br/>因你早已赐平安。<br/>','',54731,8266);
INSERT INTO stanza VALUES('Z210','6','我今呼出我的羡慕，<br/>入你慈爱的耳中；<br/>我今吸入你的答复，<br/>平静疑惑和惊恐。<br/>','',54732,8267);
INSERT INTO stanza VALUES('Z210','7','我今每刻都在呼吸<br/>你的生命作生命；<br/>一呼一吸都在乎你，<br/>求你由我来显明。<br/>','',54733,8268);
INSERT INTO stanza VALUES('Z211','1','生命之主，向我吹气，<br/>将你活泉从我开启；<br/>在我里面将我推动，<br/>生命之光照我心中。<br/>','',54734,8269);
INSERT INTO stanza VALUES('Z211','2','主，何希奇，你在我里，<br/>不必天上、阴间寻你，<br/>一回灵里，就得见你，<br/>灵灵接触，毫无距离。<br/>','',54735,8270);
INSERT INTO stanza VALUES('Z211','3','你是我的在天中保，<br/>又是我的灵中恩膏；<br/>凡你神前为我所作，<br/>都在我灵给我摸着。<br/>','',54736,8271);
INSERT INTO stanza VALUES('Z211','4','但是我心何等不忠，<br/>常虽深感，仍不顺从；<br/>求主眷怜，吹气、推动，<br/>使我全人都尽功用。<br/>','',54737,8272);
INSERT INTO stanza VALUES('Z211','5','当我灵里瘪气、下沉，<br/>难将你恩向人言陈，<br/>求你从我里面吹气，<br/>使我完全充满了你。<br/>','',54738,8273);
INSERT INTO stanza VALUES('Z212','1','圣灵的大风，<br/>从天来吹动，<br/>吹到我群众，如在五旬；<br/>吹软我硬心，<br/>吹活我全人，<br/>吹得我更新，罪孽脱尽。<br/>','',54739,8274);
INSERT INTO stanza VALUES('Z212','chorus','吹到！吹到！<br/>圣灵大风吹到！<br/>覆罩！覆罩！<br/>灵恩大云覆罩！<br/>焚烧！焚烧！<br/>圣别烈火焚烧！<br/>显耀！显耀！<br/>神精金显耀！<br/>','',54740,8275);
INSERT INTO stanza VALUES('Z212','2','灵恩的大云，<br/>满带神洪恩，<br/>覆罩我众人，如覆帐幕；<br/>覆得我得生，<br/>覆得我成圣，<br/>覆到我属灵，神可居住。<br/>','',54741,8276);
INSERT INTO stanza VALUES('Z212','3','圣别的烈火，<br/>来从我烧着，<br/>烧到每角落，将人纯洁；<br/>烧尽了邪污，<br/>烧尽了俗物，<br/>使人、神相符，<br/>全圣无劣。<br/>','',54742,8277);
INSERT INTO stanza VALUES('Z212','4','光耀的精金，<br/>照进我内心，<br/>使我得有分神的性情；<br/>神性调人性，<br/>人灵联神灵，<br/>使神的生命显于人形。<br/>','',54743,8278);
INSERT INTO stanza VALUES('Z213','1','主阿，愿你属天之风，<br/>现在吹到我身！<br/>用那感人、复兴大能，<br/>吹动我的心魂。<br/>','',54744,8279);
INSERT INTO stanza VALUES('Z213','chorus','大能主阿，求你降临，<br/>用你圣灵来吹！<br/>用你大能将我吹过，<br/>带来涌流活水！<br/>','',54745,8280);
INSERT INTO stanza VALUES('Z213','2','用你能力之灵来吹，<br/>吹去所有障碍；<br/>用你生命之灵来呼，<br/>呼进你的大爱。<br/>','',54746,8281);
INSERT INTO stanza VALUES('Z213','3','你灵具有七倍丰富，<br/>为使我享你分；<br/>求你叫我有分这灵，<br/>经历三一之神。<br/>','',54747,8282);
INSERT INTO stanza VALUES('Z214','1','哦主，向我吹风，<br/>我们在此等候；<br/>用你大风来吹，<br/>带给我们自由；<br/>吹到我们众人<br/>无不复兴得透；<br/>哦主，求你向我吹风！<br/>','',54748,8283);
INSERT INTO stanza VALUES('Z214','chorus','哦主，现在将我来吹！<br/>吹去所有松懒沉睡！<br/>愿你大风来临，<br/>将我退落吹尽！<br/>哦主，求你向我吹风。<br/>','',54749,8284);
INSERT INTO stanza VALUES('Z214','2','哦主，用爱来吹，<br/>吹热冰冷的心；<br/>将那属天之气，<br/>吹到我的全魂；<br/>吹到我们众人<br/>毫无冷淡留存；<br/>哦主，求你向我吹风！<br/>','',54750,8285);
INSERT INTO stanza VALUES('Z214','3','哦主，用力来吹，<br/>吹起死沉的灵；<br/>吹到我们复苏，<br/>充满复活生命；<br/>吹到我们众人<br/>无不刚强有能；<br/>哦主，求你向我吹风！<br/>','',54751,8286);
INSERT INTO stanza VALUES('Z215','1','奇妙的恩膏住我里面，<br/>凡事都将我教导；<br/>将神的同在时常带给我，<br/>使我得与神相交。<br/>','',54752,8287);
INSERT INTO stanza VALUES('Z215','chorus','在我里面有一奇妙恩膏，<br/>有一奇妙恩膏，<br/>凡事都教导；<br/>在我里面有一奇妙恩膏，<br/>凡事都将我教导。<br/>','',54753,8288);
INSERT INTO stanza VALUES('Z215','2','圣灵的运行在我里面，<br/>柔细如同纯膏油；<br/>这乃是根据主血的洗净，<br/>并要存在到永久。<br/>','',54754,8289);
INSERT INTO stanza VALUES('Z215','3','祂用神本质将我涂抹，<br/>我得主观认识神；<br/>使我能得着神所有成分，<br/>浸透我的整个人。<br/>','',54755,8290);
INSERT INTO stanza VALUES('Z215','4','凭着这里面生命涂抹，<br/>我今行在交通中；<br/>凭真理之光，<br/>活在神里面，<br/>恩典之爱贯我衷。<br/>','',54756,8291);
INSERT INTO stanza VALUES('Z216','1','何处洒了赎罪之血，<br/>何处就抹圣膏油；<br/>借此人得与神接触，<br/>交通也得蒙保守。<br/>','',54757,8292);
INSERT INTO stanza VALUES('Z216','2','血是救赎所有表记，<br/>洗净所有的罪恶；<br/>膏油是灵所有表号，<br/>将神带给人得着。<br/>','',54758,8293);
INSERT INTO stanza VALUES('Z216','3','血是说出神之所作，<br/>膏油说出神所是；<br/>借祂所作并祂所是，<br/>神就与人调无弛。<br/>','',54759,8294);
INSERT INTO stanza VALUES('Z216','4','借着基督血的洗净，<br/>我得脱去众罪恶；<br/>借着灵的运行涂抹，<br/>神的成分我得着。<br/>','',54760,8295);
INSERT INTO stanza VALUES('Z216','5','借这洗净和这涂抹，<br/>我得与神合为一；<br/>借着这血和这膏油，<br/>我得享受神自己。<br/>','',54761,8296);
INSERT INTO stanza VALUES('Z216','6','当我真是需要主血，<br/>就要凭信求洗净；<br/>永远顺从膏油涂抹，<br/>与神同活并同行。<br/>','',54762,8297);
INSERT INTO stanza VALUES('Z216','7','如此，认识神就是光，<br/>并且经历神是爱，<br/>享受神作我的一切，<br/>与神合一毫无碍。<br/>','',54763,8298);
INSERT INTO stanza VALUES('Z217','1','何等荣耀，何等福气，<br/>真理圣灵在我心，<br/>见证救主，启示真理，<br/>光照、安慰并指引。<br/>','',54764,8299);
INSERT INTO stanza VALUES('Z217','chorus','充满我！充满我！<br/>愿主圣灵充满我；<br/>将我倒空，将我剥夺，<br/>愿主圣灵充满我。<br/>','',54765,8300);
INSERT INTO stanza VALUES('Z217','2','愿主所说在我证实，<br/>生命圣灵将我释，<br/>使我脱离罪律辖制，<br/>脱离死亡的权势。<br/>','',54766,8301);
INSERT INTO stanza VALUES('Z217','3','我如困鹿切慕溪水，<br/>深愿圣灵解我渴，<br/>使我尝到丰满滋味，<br/>流出活水的江河。<br/>','',54767,8302);
INSERT INTO stanza VALUES('Z217','4','愿我自己被置死地，<br/>使我充满主圣灵；<br/>愿我全人归主管理，<br/>使我变成主荣形。<br/>','',54768,8303);
INSERT INTO stanza VALUES('Z218','1','我已得蒙宝血洗净，<br/>充满天上的喜乐；<br/>我已得着永远生命，<br/>成为活水的运河。<br/>','',54769,8304);
INSERT INTO stanza VALUES('Z218','chorus','我愿作主活水运河，<br/>充满生命的圣灵，<br/>灌输生命，解人干渴，<br/>涌流活水无止境。<br/>','',54770,8305);
INSERT INTO stanza VALUES('Z218','2','奇妙救恩，甜美、丰盛，<br/>满足我心如我意；<br/>我愿天天作此见证，<br/>吸引多人来归依。<br/>','',54771,8306);
INSERT INTO stanza VALUES('Z218','3','主，你使我完全成圣，<br/>作你贵重的器皿，<br/>充满恩典，充满生命，<br/>供应饥渴的人群。<br/>','',54772,8307);
INSERT INTO stanza VALUES('Z218','4','将我倒空，将我充满，<br/>愿我全人你占有；<br/>活水江河洋溢、泛滥，<br/>涌流生命到永久。<br/>','',54773,8308);
INSERT INTO stanza VALUES('Z219','1','主，你知道所有干渴，<br/>在这不足寻求心；<br/>我心羡慕何等深刻，<br/>惟你能使不饥馑。<br/>','',54774,8309);
INSERT INTO stanza VALUES('Z219','chorus','今寻求，今寻求，<br/>赐你圣灵的富有。<br/>','',54775,8310);
INSERT INTO stanza VALUES('Z219','2','行为失败，见证失败，<br/>工作失败已明显，<br/>无果之劳、非主之态，<br/>对你没有赞美献。<br/>','',54776,8311);
INSERT INTO stanza VALUES('Z219','3','我今向你承认我的<br/>所有失败和邪恶，<br/>所有自满，所有刚愎，<br/>所有心里的隐慝。<br/>','',54777,8312);
INSERT INTO stanza VALUES('Z219','4','父阿，救我脱离自己，<br/>脱离化装的骄傲；<br/>带我与主同到死地，<br/>知道同钉的奇道。<br/>','',54778,8313);
INSERT INTO stanza VALUES('Z219','5','从今不再是我工作，<br/>我想，我爱，或我说；<br/>惟独乃是基督生活，<br/>时时刻刻通过我。<br/>','',54779,8314);
INSERT INTO stanza VALUES('Z219','6','但愿你的满有圣灵，<br/>流通在我的衷表，<br/>好叫对人我是证明，<br/>对你乃是归荣耀。<br/>','',54780,8315);
INSERT INTO stanza VALUES('Z219','7','父阿，我奉子名祷告，<br/>我信祷告已答应，<br/>我今赞美答应可靠，<br/>安息只因话足凭。<br/>','',54781,8316);
INSERT INTO stanza VALUES('Z219','chorus','就赞美，就赞美，<br/>因你已听我祷告。<br/>第三节的『隐慝，』意思是隐藏的恶念。<br/>','',54782,8317);
INSERT INTO stanza VALUES('Z220','1','我在灵中从灵而生，<br/>已得成为神儿子，<br/>我已得着神的圣灵，<br/>住在我灵作印、质。<br/>但主，我需得祂更多，<br/>使我得享你丰盛；<br/>愿你用祂将我充满，<br/>赐我丰盛的生命。<br/>','',54783,8318);
INSERT INTO stanza VALUES('Z220','2','你的圣灵在我里面，<br/>不过是你生命灵，<br/>使我借着祂之所是，<br/>可得有分你丰盛。<br/>但我仍需你的圣灵，<br/>作那上头的能力，<br/>使我借祂得着装备，<br/>为你作工，事奉你。<br/>','',54784,8319);
INSERT INTO stanza VALUES('Z220','3','求主使我经历灵浸，<br/>穿上上头的能力；<br/>借着你这能力『外衣，』<br/>我可进攻你仇敌。<br/>愿你大风今向我吹，<br/>赐我火焰的舌头，<br/>使我作你受膏证人，<br/>将你心愿来成就。<br/>','',54785,8320);
INSERT INTO stanza VALUES('Z220','4','即使已得圣灵能力，<br/>我仍需要你恩赐，<br/>使我能尽肢体功用，<br/>与众肢体同服事。<br/>主，借你灵丰满浇灌，<br/>所需恩赐分给我，<br/>使你身体得着建造，<br/>作你祝福的结果。<br/>','',54786,8321);
INSERT INTO stanza VALUES('Z220','5','为你荣耀并你国度，<br/>听你身体这呼求！<br/>满足我们所有需要，<br/>使你圣旨得成就。<br/>愿我丰满有分你灵，<br/>多方将祂来应用；<br/>里面充满、外面浇灌、<br/>以及恩赐，全贯通。<br/>','',54787,8322);
INSERT INTO stanza VALUES('Z221','1','当主基督降生为人，<br/>乃由圣灵而成孕；<br/>在祂工作开始之先，<br/>圣灵充满也有分。<br/>但在开始作工之时，<br/>祂仍受了圣灵浸；<br/>借此穿上上头能力，<br/>为尽神圣的职分。<br/>','',54788,8323);
INSERT INTO stanza VALUES('Z221','2','彼得和主其他门徒，<br/>都已由灵所重生；<br/>主向他们吹气之时，<br/>早已吸入了圣灵。<br/>但是后来又都受了<br/>主在圣灵里的浸，<br/>穿上能力，得着装备，<br/>神圣职分才能尽。<br/>','',54789,8324);
INSERT INTO stanza VALUES('Z221','3','大数扫罗，以弗所人，<br/>撒玛利亚的信徒，<br/>都已得着圣灵重生，<br/>且有圣灵在内住。<br/>但当有人为其按手，<br/>又都经历圣灵浸，<br/>穿上上头来的能力，<br/>见证基督，事奉神。<br/>','',54790,8325);
INSERT INTO stanza VALUES('Z221','4','我们也在相信之时，<br/>都已由灵而重生，<br/>并且现今得饮于祂，<br/>天天享受祂丰盛。<br/>然而我们仍需经历<br/>圣灵里面的受浸，<br/>借此穿上上头能力，<br/>得着装备，尽职分。<br/>','',54791,8326);
INSERT INTO stanza VALUES('Z221','5','求主使我经历灵浸，<br/>这是我的真需要；<br/>上头能力给我穿上，<br/>为着召会的建造。<br/>愿主现在给我经历，<br/>我今如此迫切求；<br/>使我丰满经历灵浸，<br/>上头能力浇我透。<br/>','',54792,8327);
INSERT INTO stanza VALUES('Z222','1','有福的事实，<br/>主话已启示，<br/>我在圣灵里面已受浸；<br/>接受这事实，<br/>毋须再延迟，<br/>我在圣灵里面已受浸。<br/>','',54793,8328);
INSERT INTO stanza VALUES('Z222','chorus','接受！接受！<br/>凭信接受勿再延迟；<br/>接受！接受！<br/>凭信接受这已成事实。<br/>','',54794,8329);
INSERT INTO stanza VALUES('Z222','2','新约的话语，<br/>清楚已言明，<br/>我在圣灵里面已受浸；<br/>只需我持守，<br/>不需我何行，<br/>我在圣灵里面已受浸。<br/>','',54795,8330);
INSERT INTO stanza VALUES('Z222','chorus','持守！持守！<br/>凭信持守不稍松弛；<br/>持守！持守！<br/>凭信持守这已成事实。<br/>','',54796,8331);
INSERT INTO stanza VALUES('Z222','3','基督向召会，<br/>已浇下圣灵，<br/>我在圣灵里面已受浸；<br/>分享这福分，<br/>分享得丰盛，<br/>我在圣灵里面已受浸。<br/>','',54797,8332);
INSERT INTO stanza VALUES('Z222','chorus','分享！分享！<br/>凭信分享已得恩赐；<br/>分享！分享！<br/>凭信分享这已成事实。<br/>','',54798,8333);
INSERT INTO stanza VALUES('Z222','4','在身体里面，<br/>与身体和谐，<br/>凭这已成事实而行动；<br/>罪恶都认清，<br/>疑惑全拒绝，<br/>因信凭这事实就行动。<br/>','',54799,8334);
INSERT INTO stanza VALUES('Z222','chorus','行动！行动！<br/>因信行动在身体中；<br/>行动！行动！<br/>因信凭这事实而行动。<br/>','',54800,8335);
INSERT INTO stanza VALUES('Z223','1','主，我来就你，<br/>自由的恳祈，<br/>求你赐我以你能力；<br/>为着你国度，<br/>能力归我属，<br/>坐在天上进攻你仇敌。<br/>能力！能力！<br/>给我穿上能力！<br/>穿上上头来的大能力！<br/>能力！能力！<br/>给我穿上能力！<br/>你的身体今向你恳祈！<br/>','',54801,8336);
INSERT INTO stanza VALUES('Z223','2','主，我仰望你，<br/>肯定的恳祈，<br/>求你赐我以你甘雨；<br/>为着你身体，<br/>甘雨你供给，<br/>使我适合你工作所需。<br/>甘雨！甘雨！<br/>向我浇下甘雨！<br/>浇下上头来的圣甘雨！<br/>甘雨！甘雨！<br/>向我浇下甘雨！<br/>你的身体今向你呼吁！<br/>','',54802,8337);
INSERT INTO stanza VALUES('Z223','3','主，我等候你，<br/>确信的恳祈，<br/>求你赐我以你圣火！<br/>为着你福音，<br/>圣火将我焚，<br/>使人悔改、相信、<br/>进神国。<br/>圣火！圣火！<br/>焚我以你圣火！<br/>带着你的热爱焚烧我！<br/>圣火！圣火！<br/>焚我以你圣火！<br/>你的身体如此在求着！<br/>','',54803,8338);
INSERT INTO stanza VALUES('Z224','1','救主基督已经高升，<br/>坐在诸天的上面，<br/>从祂父神也已得着<br/>尊贵、荣耀为冠冕；<br/>神要祂作万有元首，<br/>使祂尊高得彰显。<br/>','',54804,8339);
INSERT INTO stanza VALUES('Z224','2','从这升到神前基督，<br/>圣灵已经浇下来，<br/>浇在祂的身体上面，<br/>给祂肢体都穿戴，<br/>使那在天万有之主，<br/>借祂召会得敬拜。<br/>','',54805,8340);
INSERT INTO stanza VALUES('Z224','3','基督借着成为肉身，<br/>将神带到人里面；<br/>祂也借着死而复活，<br/>将人带进神中间；<br/>神与人的完全调和，<br/>在祂里面得成全。<br/>','',54806,8341);
INSERT INTO stanza VALUES('Z224','4','祂今已升高天之上，<br/>登上荣耀的宝座；<br/>万主之主，万王之王，<br/>所有主权全得着；<br/>借着浇下祂的圣灵，<br/>已将这事证确凿。<br/>','',54807,8342);
INSERT INTO stanza VALUES('Z224','5','借将祂灵浇灌下来，<br/>祂在召会又降临；<br/>在祂这位圣灵里面，<br/>给全召会来施浸；<br/>如此完成的这灵浸，<br/>所有信徒都有分。<br/>','',54808,8343);
INSERT INTO stanza VALUES('Z224','6','阿利路亚，已经完成，<br/>一次永远的完成！<br/>阿利路亚，此浸我承，<br/>大小信徒都得承！<br/>祂已将祂所有肢体，<br/>早都浸在祂的灵！<br/>','',54809,8344);
INSERT INTO stanza VALUES('Z225','1','主，你能力我今在寻求，<br/>对你工作我无所成就，<br/>懦弱、无能，<br/>实在已够久，<br/>给我穿上能力！<br/>','',54810,8345);
INSERT INTO stanza VALUES('Z225','chorus','谦卑俯伏，我在此等候，<br/>诚恳迫切，我向你呼求，<br/>给我能力，给我毫不留，<br/>给我穿上能力！<br/>','',54811,8346);
INSERT INTO stanza VALUES('Z225','2','施恩眷顾，我今在此催，<br/>将你恩赐分给你召会，<br/>使我工作，永不再气馁，<br/>给我穿上能力！<br/>','',54812,8347);
INSERT INTO stanza VALUES('Z225','3','赐上能力，带着你权柄，<br/>如同你在五旬节所行，<br/>答应所求，答应不稍等，<br/>给我穿上能力！<br/>','',54813,8348);
INSERT INTO stanza VALUES('Z225','4','你的身体，如此在请愿，<br/>靠着你名，因信求成全，<br/>降下甘雨，并赐下火焰，<br/>给我穿上能力！<br/>','',54814,8349);
INSERT INTO stanza VALUES('Z226','1','主的生命之灵，<br/>进到我里面，<br/>如同活水解渴，<br/>作我活水泉；<br/>我可饮于这灵，<br/>且被祂充满，<br/>直到如同江河，<br/>涌流到永远。<br/>','',54815,8350);
INSERT INTO stanza VALUES('Z226','2','主的能力之灵，<br/>降到我身上，<br/>犹如外衣遮身，<br/>作我的力量；<br/>在祂里面受浸，<br/>就将祂穿上，<br/>为着工作装备，<br/>使我人刚强。<br/>','',54816,8351);
INSERT INTO stanza VALUES('Z226','3','主的生命之灵，<br/>犹如同空气，<br/>作了生命实际，<br/>呼吸到我里；<br/>主的能力之灵，<br/>乃像似大风，<br/>从上用力而吹，<br/>使我能行动。<br/>','',54817,8352);
INSERT INTO stanza VALUES('Z226','4','向着祂的门徒，<br/>复活主吹气，<br/>将祂生命之灵，<br/>吹到他们里；<br/>在五旬节时候，<br/>升天主浇下<br/>祂的能力之灵，<br/>如同大风刮。<br/>','',54818,8353);
INSERT INTO stanza VALUES('Z226','5','生命之灵乃是<br/>作里面生命，<br/>能力之灵乃是<br/>为着这生命；<br/>如同风吹带来<br/>新鲜的空气，<br/>能力之灵带来<br/>生命给人吸。<br/>','',54819,8354);
INSERT INTO stanza VALUES('Z226','6','并非二位分开、<br/>不同的圣灵，<br/>乃是一位圣灵<br/>不同的功能；<br/>在内充满了神，<br/>在外穿上神，<br/>使我与神相调，<br/>永远不再分。<br/>','',54820,8355);
INSERT INTO stanza VALUES('Z226','7','主，用生命之灵，<br/>充满我里面，<br/>使我生命长大，<br/>如同你完全；<br/>在外给我穿上<br/>能力的圣灵，<br/>使我有力工作，<br/>完成你使命。<br/>','',54821,8356);
INSERT INTO stanza VALUES('Z227','1','后是膏油先是血，<br/>要得滋润先得洁；<br/>若非经过各各他，<br/>必不能到五旬节。<br/>我们若未蒙洗净，<br/>能力必不从上倾；<br/>我们若要作见证，<br/>必须钉死己生命。<br/>','',54822,8357);
INSERT INTO stanza VALUES('Z227','chorus','因此求主借十字架，<br/>治死我的魂生命；<br/>使我愿出重大代价，<br/>来满受主的圣灵。<br/>','',54823,8358);
INSERT INTO stanza VALUES('Z227','2','先是用杖击石磐，<br/>后来活水才溢漫；<br/>死亡若未作过工，<br/>圣灵必定不充满。<br/>我们若真同主死，<br/>愿意万有都损失，<br/>主的能力要降临，<br/>使用我们救亡世。<br/>','',54824,8359);
INSERT INTO stanza VALUES('Z227','3','先是祭坛后是火，<br/>若没丧失就没果；<br/>若非所有先奉献，<br/>必定不能登宝座。<br/>我们若真肯牺牲，<br/>舍弃万事降服神，<br/>我们必定得能力，<br/>因主信托顺从人。<br/>','',54825,8360);
INSERT INTO stanza VALUES('Z227','4','先是豫备瓶子空，<br/>后是膏油盛其中；<br/>先是山谷挖成沟，<br/>后来活水才深泓；<br/>先是经过约但河，<br/>后是灵感加倍多；<br/>先受死亡的浸洗，<br/>后得荣耀的圣鸽。<br/>','',54826,8361);
INSERT INTO stanza VALUES('Z227','5','当你举目望禾田，<br/>金谷丰盈你称羡；<br/>当念果实未生时，<br/>就有麦种死在先。<br/>若要生命的子粒，<br/>须有死亡的经历；<br/>凡人未到髑髅地，<br/>就无圣灵的能力。<br/>','',54827,8362);
INSERT INTO stanza VALUES('Z227','6','既是这样，求我主，<br/>使我忠诚走窄路，<br/>除去雄心和大志，<br/>只愿顺服并受苦；<br/>更大能力我不取，<br/>更深的死我所需；<br/>但愿加略的意义，<br/>完全成功在我躯。<br/>','',54828,8363);
INSERT INTO stanza VALUES('Z228','1','求主宝血洁净我，<br/>洗尽所有罪过，<br/>将你圣洁的膏油，<br/>重新为我涂抹。<br/>我认自己的生活，<br/>真是失败、软弱，<br/>我望充满你的灵，<br/>完全为你而活。<br/>','',54829,8364);
INSERT INTO stanza VALUES('Z228','chorus','哦，求主救我脱离<br/>这个可怜的自己！<br/>求主使我从今后，<br/>完全充满了你。<br/>','',54830,8365);
INSERT INTO stanza VALUES('Z228','2','我心何等的干旱，<br/>常为软弱悲叹；<br/>我是何等的盼望，<br/>能被圣灵充满。<br/>求主让我今隐藏<br/>在你击伤石磐；<br/>求主今听我呼求，<br/>让你活水泛滥。<br/>','',54831,8366);
INSERT INTO stanza VALUES('Z228','3','我心何等的冷淡，<br/>顺服何等迟慢；<br/>愿主圣灵充满我，<br/>使我不再背叛。<br/>我今躺卧在祭坛，<br/>不敢稍为动弹；<br/>求主烈火从天降，<br/>把我所有烧干。<br/>','',54832,8367);
INSERT INTO stanza VALUES('Z228','4','求主十架在我身，<br/>天天作工更深，<br/>把我度量扩充大，<br/>使我化为灰尘；<br/>好叫圣灵充满我，<br/>天天比前更多，<br/>你的活水到处流，<br/>解除众人干渴。<br/>','',54833,8368);
INSERT INTO stanza VALUES('Z229','1','我今在基督里面，<br/>脱离了亚当界限；<br/>凡旧事都变新鲜，<br/>属地变为属天！<br/>赞美主，在此得享恩典，<br/>饱尝生命与平安！<br/>赞美主，我今在主里面！<br/>','',54834,8369);
INSERT INTO stanza VALUES('Z230','1','我真欢乐，<br/>因为天上父神，<br/>在祂话中明说祂爱世人；<br/>圣经所载奇妙之事甚多，<br/>其最甜者，<br/>就是耶稣爱我。<br/>','',54835,8370);
INSERT INTO stanza VALUES('Z230','chorus','我真欢乐，因耶稣爱我！<br/>耶稣爱我，耶稣爱我；<br/>我真欢乐，因耶稣爱我！<br/>耶稣竟然爱我！<br/>','',54836,8371);
INSERT INTO stanza VALUES('Z230','2','我虽忘祂，<br/>一直流荡远离，<br/>祂仍爱我，<br/>无论流荡何地；<br/>祂来寻我，<br/>直到将我寻着，<br/>并且带回，<br/>因为耶稣爱我。<br/>','',54837,8372);
INSERT INTO stanza VALUES('Z230','3','耶稣爱我，<br/>我也要爱耶稣；<br/>爱叫祂来将我灵魂救赎，<br/>爱叫祂来受死担我罪过，<br/>因此我就确信耶稣爱我。<br/>','',54838,8373);
INSERT INTO stanza VALUES('Z230','4','这爱奇妙，<br/>虽然我不会说，<br/>我却知道，<br/>并且满有把握！<br/>在我灵中圣灵盖上印戳，<br/>不断向我印证耶稣爱我。<br/>','',54839,8374);
INSERT INTO stanza VALUES('Z230','5','因有此证，<br/>我灵充满安息，<br/>因有主话，<br/>我心不再怀疑。<br/>撒但惊慌，<br/>离我远远逃躲，<br/>当我告诉他说，<br/>耶稣爱我。<br/>','',54840,8375);
INSERT INTO stanza VALUES('Z230','6','等进荣耀亲眼看见我王，<br/>若有诗歌是我口舌爱唱，<br/>那就必是我所永要唱说：『何等奇妙之事，<br/>耶稣爱我！』<br/>','',54841,8376);
INSERT INTO stanza VALUES('Z231','1','主爱新鲜又甘甜，<br/>我要引声颂扬：<br/>主既为我受苦难，<br/>又来住我心房；<br/>赐我生命与平安，<br/>扶持、照护无间；<br/>主爱越久越新鲜，<br/>主爱越久越甜。<br/>','',54842,8377);
INSERT INTO stanza VALUES('Z231','chorus','主的爱越久越甜，<br/>主的爱越久越甜；<br/>甜过美酒甘蜜，<br/>我要颂扬不已，<br/>主的爱越久越甜。<br/>','',54843,8378);
INSERT INTO stanza VALUES('Z231','2','主爱长阔又高深，<br/>我要高声颂扬：<br/>主比亲者还要亲，<br/>永不离我身旁；<br/>待我情深如密友，<br/>与我心心相印；<br/>主爱越久越丰厚，<br/>主爱越久越深。<br/>','',54844,8379);
INSERT INTO stanza VALUES('Z231','chorus','主的爱越久越深，<br/>主的爱越久越深；<br/>深逾大海汪洋，<br/>我要时时颂扬，<br/>主的爱越久越深。<br/>','',54845,8380);
INSERT INTO stanza VALUES('Z231','3','主爱温柔又坚刚，<br/>我要永远颂扬：<br/>主比强者还要强，<br/>主爱也是这样；<br/>虽然天地会改迁，<br/>虽然海枯石烂；<br/>主爱至终不消减，<br/>主爱历久不变。<br/>','',54846,8381);
INSERT INTO stanza VALUES('Z231','chorus','主的爱历久不变，<br/>主的爱历久不变；<br/>坚定远胜日月，<br/>我要颂扬不绝。<br/>主的爱历久不变。<br/>','',54847,8382);
INSERT INTO stanza VALUES('Z232','1','永远的爱已爱我，<br/>这爱借恩我赏识；<br/>圣灵从上来吹着，<br/>为要如此来指示。<br/>哦，这丰满的平安！<br/>哦，这神圣的欢乐！<br/>在这不息爱里面，<br/>我是属祂，祂属我。<br/>','',54848,8383);
INSERT INTO stanza VALUES('Z232','2','头上之天何蔚蓝，<br/>四周之地也青绿；<br/>有一景色更鲜艳，<br/>无主之目从未睹：<br/>鸟鸣变为更音乐，<br/>花美使我更快活，<br/>自从我心能领略：<br/>我是属祂，祂属我。<br/>','',54849,8384);
INSERT INTO stanza VALUES('Z232','3','有事曾使我惊恐，<br/>今不再扰我安息；<br/>靠在永久膀臂中，<br/>枕在爱的胸怀里。<br/>哦，愿永远卧于此，<br/>忧疑、自己，全逃脱，<br/>当祂柔声的指示：<br/>我是属祂，祂属我。<br/>','',54850,8385);
INSERT INTO stanza VALUES('Z232','4','我是永远只属祂，<br/>谁能使祂与我分？<br/>祂在我心来安家，<br/>有福、安息满我心。<br/>天地可以都废去，<br/>亮光也可全衰落，<br/>但主与我永同居，<br/>我是属祂，祂属我。<br/>','',54851,8386);
INSERT INTO stanza VALUES('Z233','1','神将我罪丢在背后，<br/>不再记念，不再追究；<br/>神将我罪踏在脚下，<br/>不再看见，不再鉴察。<br/>','',54852,8387);
INSERT INTO stanza VALUES('Z233','chorus','我的过犯神全赦免，<br/>好似厚云完全消散；<br/>我的罪恶神都涂抹，<br/>犹如薄云尽都灭没。<br/>','',54853,8388);
INSERT INTO stanza VALUES('Z233','2','神将我罪投于深海，<br/>如石下沉全被淹埋；<br/>神叫我罪离开我身，<br/>如东离西同样远甚。<br/>','',54854,8389);
INSERT INTO stanza VALUES('Z234','1','救主流血所成救恩，<br/>我是何人竟也有分？<br/>罪是我犯，死归祂受，<br/>祂替我死，为将我救！<br/>惊人之爱，何竟如此？<br/>我主我神为我受死！<br/>惊人之爱，何竟如此？<br/>我主我神为我受死！<br/>','',54855,8390);
INSERT INTO stanza VALUES('Z234','2','不能死者，竟然受死！<br/>全是奥秘，谁能尽知？<br/>神圣之爱，高深长阔，<br/>最高天使也难测度！<br/>所有天使不必臆猜，<br/>全是怜悯，当得敬拜！<br/>所有天使不必臆猜，<br/>全是怜悯，当得敬拜！<br/>','',54856,8391);
INSERT INTO stanza VALUES('Z234','3','离开天上父的宝座，<br/>降世为人，恩何广阔；<br/>虚己、舍身，<br/>流血、赎罪，<br/>为救亚当无望族类；<br/>全是怜悯，无量、白给，<br/>竟然临及我这罪魁！<br/>全是怜悯，无量、白给，<br/>竟然临及我这罪魁！<br/>','',54857,8392);
INSERT INTO stanza VALUES('Z234','4','天性黑暗，邪恶满心，<br/>我灵久为罪恶监禁；<br/>你眼垂顾，带来恩光，<br/>我立苏醒，囚牢明亮，<br/>锁炼尽脱，全人释放，<br/>起来随主，心中欢畅。<br/>锁炼尽脱，全人释放，<br/>起来随主，心中欢畅。<br/>','',54858,8393);
INSERT INTO stanza VALUES('Z234','5','不再定罪，尚何惧忧？<br/>主和一切尽归我有！<br/>活在元首基督里面，<br/>神圣之义将我遮掩；<br/>坦然来到施恩座前，<br/>有主基督作我冠冕。<br/>坦然来到施恩座前，<br/>有主基督作我冠冕。<br/>','',54859,8394);
INSERT INTO stanza VALUES('Z235','1','我为甚么忧惧疑惑？<br/>神岂未曾将我罪过<br/>归祂儿子身上？<br/>主所为我还清的债，<br/>公义的神能否再来<br/>要我重新清偿？<br/>','',54860,8395);
INSERT INTO stanza VALUES('Z235','2','你的救赎永远完全，<br/>你已还清每一文钱-<br/>我们所有罪戾；<br/>神的忿怒不能威胁，<br/>因我已经洒上宝血，<br/>靠恩已经称义。<br/>','',54861,8396);
INSERT INTO stanza VALUES('Z235','3','你既为我领得赦免，<br/>你既给我白白恩典-<br/>罪债一起清算；<br/>神就不会两面讨偿：<br/>先在我的中保身上…<br/>后又要我归还。<br/>','',54862,8397);
INSERT INTO stanza VALUES('Z235','4','所以我心，你当安息，<br/>你的救主所有功绩，<br/>已使你得开释；<br/>当信祂的有效宝血，<br/>不怕神再将你弃绝，<br/>因主已为你死。<br/>','',54863,8398);
INSERT INTO stanza VALUES('Z236','1','『不再定罪！』<br/>何等希奇！<br/>我魂，应当欢喜！<br/>你罪已经都归耶稣，<br/>祂死使你得苏。<br/>','',54864,8399);
INSERT INTO stanza VALUES('Z236','2','宝血为我永远在天，<br/>对神说出美言；<br/>主看圣徒如同奇珍，<br/>天天照顾惟殷。<br/>','',54865,8400);
INSERT INTO stanza VALUES('Z236','3','『不再定罪！』<br/>我的魂哪，<br/>这是神说的话；<br/>你在基督复活主里，<br/>已是完全美丽。<br/>','',54866,8401);
INSERT INTO stanza VALUES('Z236','4','神阿，教我注目仰望<br/>救主基督，我王；<br/>我才会爱你的心情，<br/>才会荣耀祂名。<br/>','',54867,8402);
INSERT INTO stanza VALUES('Z237','1','神的基督是我的义，<br/>我的美丽，我的锦衣，<br/>在宝座前服此盛装，<br/>我能抬头欢乐歌唱。<br/>','',54868,8403);
INSERT INTO stanza VALUES('Z237','2','主阿，我信你的宝血，<br/>已将我罪全都解决，<br/>为我洒在神施恩座，<br/>永远为我向神求赦。<br/>','',54869,8404);
INSERT INTO stanza VALUES('Z237','3','借你救赎，我已脱去<br/>我罪、我过、<br/>我耻、我惧；<br/>审判大日我敢站立，<br/>谁能控告你所称义？<br/>','',54870,8405);
INSERT INTO stanza VALUES('Z237','4','亚伯拉罕就是如此，<br/>蒙赎圣徒也都一式，<br/>宣布你为罪人救星，<br/>他们所夸只在你名。<br/>','',54871,8406);
INSERT INTO stanza VALUES('Z237','5','这件白衣永远不变，<br/>尽管旧造沉没多年；<br/>时代不能改其美艳，<br/>牠的荣美永远新鲜。<br/>','',54872,8407);
INSERT INTO stanza VALUES('Z237','6','直到天上见你荣耀，<br/>我们仍要以你自骄：<br/>我的美丽、我的锦衣，<br/>我主耶稣是我的义。<br/>','',54873,8408);
INSERT INTO stanza VALUES('Z238','1','我的所有希望根基，<br/>并不少于基督我义；<br/>最好的义也不敢倚，<br/>只敢倚靠祂的自己。<br/>','',54874,8409);
INSERT INTO stanza VALUES('Z238','chorus','基督磐石，我所稳踏，<br/>其他地位都是流沙！<br/>其他地位都是流沙！<br/>','',54875,8410);
INSERT INTO stanza VALUES('Z238','2','即有黑云掩祂爱脸，<br/>祂心不变，祂恩不移；<br/>每次风浪虽欲漫淹，<br/>信心的锚抛牢幔里。<br/>','',54876,8411);
INSERT INTO stanza VALUES('Z238','3','祂血、祂约何等可靠，<br/>我名已经刻在祂手；<br/>四围虽然都能倾倒，<br/>祂仍存在永不弃守。<br/>','',54877,8412);
INSERT INTO stanza VALUES('Z238','4','当祂再来，号筒吹响，<br/>那时我在祂内出现；<br/>只穿着祂作我义裳，<br/>无可指责被献座前。<br/>','',54878,8413);
INSERT INTO stanza VALUES('Z239','1','神将我罪归耶稣，<br/>神的圣洁羔羊；<br/>使祂替我受咒诅，<br/>将我全人释放。<br/>神将我愆归耶稣，<br/>神的无疵羔羊；<br/>使祂替我受痛苦，<br/>将我罪债清偿。<br/>','',54879,8414);
INSERT INTO stanza VALUES('Z239','2','我的疾病归耶稣，<br/>为我祂受鞭伤；<br/>我的软弱祂背负，<br/>我得医治、健康。<br/>我的忧患归耶稣，<br/>为我祂全担当；<br/>我的愁苦祂消除，<br/>我得平安、欢畅。<br/>','',54880,8415);
INSERT INTO stanza VALUES('Z239','3','我今安息于耶稣，<br/>祂是我的义皇；<br/>祂死已使神满足，<br/>祂血洗我天良。<br/>我今所靠惟耶稣，<br/>祂是我的力量；<br/>祂活彰显神丰富，<br/>祂生使我刚强。<br/>','',54881,8416);
INSERT INTO stanza VALUES('Z239','4','我将我心归耶稣，<br/>惟愿祂来为王，<br/>作我生命，为我主，<br/>永远居我心房。<br/>我愿我能像耶稣，<br/>活出祂的模样；<br/>在我态度和步武，<br/>永远将祂显扬。<br/>','',54882,8417);
INSERT INTO stanza VALUES('Z240','1','『坦然无惧来到神前，』<br/>这真是从何说起！<br/>一个罪人因着恩典，<br/>竟可不再作仇敌！<br/>','',54883,8418);
INSERT INTO stanza VALUES('Z240','2','我性、我行，都远离神！<br/>哎哟，离神何等远！<br/>现今因我信血受恩，<br/>不再两下隔天渊。<br/>','',54884,8419);
INSERT INTO stanza VALUES('Z240','3','我极近神，近到如此，<br/>已经不能再相近；<br/>我因借着祂的儿子，<br/>就得像子那么亲。<br/>','',54885,8420);
INSERT INTO stanza VALUES('Z240','4','神极爱我，爱到如此，<br/>已经不能再珍爱；<br/>祂是如何爱祂儿子，<br/>照样爱我不稍改。<br/>','',54886,8421);
INSERT INTO stanza VALUES('Z240','5','我既得着这样的神，<br/>我心为何仍畏避？<br/>祂之于我一往情深，<br/>祂对我说：『我属你！』<br/>','',54887,8422);
INSERT INTO stanza VALUES('Z241','1','我生命有何等<br/>奇妙的大改变，<br/>自基督来住在我心；<br/>神荣耀的光辉，<br/>照耀在我魂间，<br/>自基督来住在我心。<br/>','',54888,8423);
INSERT INTO stanza VALUES('Z241','chorus','自基督来住在我心，<br/>自基督来住在我心；<br/>喜乐潮溢我魂，<br/>如海涛之滚滚，<br/>自基督来住在我心。<br/>','',54889,8424);
INSERT INTO stanza VALUES('Z241','2','我罪恶的捆绑，<br/>从里外全脱落，<br/>自基督来住在我心；<br/>我肉体的情欲，<br/>也不能再迷惑，<br/>自基督来住在我心。<br/>','',54890,8425);
INSERT INTO stanza VALUES('Z241','3','这世界的福乐，<br/>既变色，又失味，<br/>自基督来住在我心；<br/>我今生的忧虑，<br/>也不能再缠累，<br/>自基督来住在我心。<br/>','',54891,8426);
INSERT INTO stanza VALUES('Z241','4','我流荡已止息，<br/>不再感人生空，<br/>自基督来住在我心；<br/>主甜美的安息，<br/>时满足我情衷，<br/>自基督来住在我心。<br/>','',54892,8427);
INSERT INTO stanza VALUES('Z241','5','往日事都已过，<br/>永不再恋旧途，<br/>自基督来住在我心；<br/>那有福的盼望，<br/>吸引我奔义路，<br/>自基督来住在我心。<br/>','',54893,8428);
INSERT INTO stanza VALUES('Z242','1','喜乐满我心！<br/>满我心！满我心！<br/>喜乐满我心！<br/>主将我石心，<br/>换成了肉心；<br/>圣灵来更新，<br/>使我成为新人：<br/>喜乐满我心！<br/>满我心！满我心！<br/>','',54894,8429);
INSERT INTO stanza VALUES('Z242','2','圣灵充满我！<br/>充满我！充满我！<br/>圣灵充满我！<br/>除去我罪过，<br/>消灭我软弱，<br/>使我结义果，<br/>并过圣洁生活：<br/>圣灵充满我！<br/>充满我！充满我！<br/>','',54895,8430);
INSERT INTO stanza VALUES('Z243','1','我知何时我的罪担全脱落：<br/>多年昼夜将罪担苦背着，<br/>等我相信主的话，<br/>按祂所说接受祂，<br/>霎时间，我的罪担全脱落！<br/>','',54896,8431);
INSERT INTO stanza VALUES('Z243','chorus','全脱落！全脱落！<br/>我今快乐，<br/>因我罪担全脱落；<br/>全脱落！全脱落！<br/>我今快乐，<br/>因我罪担全脱落。<br/>','',54897,8432);
INSERT INTO stanza VALUES('Z243','2','我知何处我的罪担全脱落：<br/>当我昼夜怕罪担不能脱，<br/>圣灵示我脱罪法，<br/>带着罪担就十架；<br/>一到彼，我的罪担全脱落。<br/>','',54898,8433);
INSERT INTO stanza VALUES('Z243','3','我知何故我的罪担全脱落：<br/>罪担多年曾昼夜缠累我，<br/>等我来到恩座前，<br/>主的荣颜仅一显，<br/>就因此，我的罪担全脱落。<br/>','',54899,8434);
INSERT INTO stanza VALUES('Z243','4','我今歌唱，因我罪担全脱落，<br/>心里昼夜涌美辞、<br/>颂不辍；我今活着为我主，<br/>日日高唱乐欢呼-阿利路！<br/>我的罪担全脱落。<br/>','',54900,8435);
INSERT INTO stanza VALUES('Z244','1','我因归耶稣，<br/>全人得着释放；<br/>耶稣我救主，<br/>今在我心作王；<br/>圣灵充满我，<br/>使我终日欢唱；<br/>主耶稣已把我释放！<br/>','',54901,8436);
INSERT INTO stanza VALUES('Z244','chorus','释放！释放！荣耀释放！<br/>我不再被罪恶捆绑；<br/>宝血洗净我，<br/>全人明亮、清爽；<br/>主耶稣已把我释放！<br/>','',54902,8437);
INSERT INTO stanza VALUES('Z244','2','罪恶失权势，<br/>情欲不能羁绊，<br/>今生的忧虑<br/>也难再将我缠，<br/>属地的捆索<br/>也都已被斩断；<br/>主耶稣已把我释放！<br/>','',54903,8438);
INSERT INTO stanza VALUES('Z244','3','救主已为我<br/>冲破世界重围，<br/>霸占的魔鬼<br/>祂也替我击退；<br/>恩光今照我，<br/>荣耀何其煌辉！<br/>主耶稣已把我释放！<br/>','',54904,8439);
INSERT INTO stanza VALUES('Z245','1','前在罪中为罪奴仆，<br/>受尽罪中痛苦；<br/>罪作我主，将我制伏，<br/>又将我捆缚；<br/>我虽挣扎，不能逃出，<br/>时常叹息、喊苦；<br/>从未知道基督释放罪奴。<br/>','',54905,8440);
INSERT INTO stanza VALUES('Z245','chorus','我今已蒙主恩湛，<br/>脱离了罪恶霸权，<br/>畅饮于生命活泉，<br/>饱尝救恩盛筵；<br/>阿利路，<br/>何等丰富、甘甜，<br/>带来喜乐和颂赞！<br/>阿利路，<br/>我今已蒙恩湛！<br/>','',54906,8441);
INSERT INTO stanza VALUES('Z246','1','罪恶的锁炼，<br/>曾使我难当，<br/>我如同囚奴，挣扎枉然；<br/>但我今得着奇妙的释放，<br/>就是主耶稣打碎锁炼。<br/>','',54907,8442);
INSERT INTO stanza VALUES('Z246','chorus','荣耀的释放！<br/>奇妙的释放！<br/>主耶稣是我荣耀救主。<br/>我今已脱离罪恶的捆绑，<br/>从今到永远不再痛苦。<br/>','',54908,8443);
INSERT INTO stanza VALUES('Z246','2','脱离了肉体、<br/>邪情和私欲，<br/>脱离了嫉妒、<br/>忌恨、争竞，<br/>脱离了世界、<br/>虚荣并美誉，<br/>脱离了一切无谓人生。<br/>','',54909,8444);
INSERT INTO stanza VALUES('Z246','3','脱离了金钱<br/>闪耀的吸力，<br/>脱离了刚硬、<br/>雄心、己意，<br/>脱离了律法字句的绊羁；<br/>希奇的释放，<br/>哦，何希奇！<br/>','',54910,8445);
INSERT INTO stanza VALUES('Z247','1','惊人恩典！何等甘甜，<br/>来救无赖如我！<br/>前曾失落，今被寻见！<br/>前盲，今不摸索！<br/>','',54911,8446);
INSERT INTO stanza VALUES('Z247','2','恩典教导我心惧怕，<br/>又将惧怕除掉；<br/>恩典在我初信刹那，<br/>显为何等可宝。<br/>','',54912,8447);
INSERT INTO stanza VALUES('Z247','3','主已应许向我施恩，<br/>祂话就是保证；<br/>祂要作我盾牌、永分，<br/>带我经过此生。<br/>','',54913,8448);
INSERT INTO stanza VALUES('Z247','4','当我见主万年之后，<br/>仍像太阳照耀，<br/>比我开始赞美时候，<br/>赞美仍不减少。<br/>','',54914,8449);
INSERT INTO stanza VALUES('Z248','1','恩典代罪而兴，<br/>在我灵中执政，<br/>使我脱离罪的权能，<br/>脱离败坏天性。<br/>','',54915,8450);
INSERT INTO stanza VALUES('Z248','chorus','恩典够我用！<br/>永不感力穷；<br/>基督活在我灵中，<br/>使我受恩重重。<br/>','',54916,8451);
INSERT INTO stanza VALUES('Z248','2','恩典使我脚步<br/>行在属天路途，<br/>祂的恩典，应时、丰富，<br/>从未将我迟误。<br/>','',54917,8452);
INSERT INTO stanza VALUES('Z248','3','何能大于恩典！<br/>祂是神来人间，<br/>祂是神在肉身显现，<br/>是神在我里面。<br/>','',54918,8453);
INSERT INTO stanza VALUES('Z248','chorus','我成何等人！<br/>是因蒙神恩；<br/>神恩今显在我身，<br/>作我神人永分。<br/>','',54919,8454);
INSERT INTO stanza VALUES('Z249','1','有日银炼将要折断，<br/>我就不再如此歌唱；<br/>但我醒来何等喜欢，<br/>竟然得以面见我王。<br/>','',54920,8455);
INSERT INTO stanza VALUES('Z249','chorus','我要看见祂面对面，<br/>我要述说救我恩典；<br/>我要看见祂面对面，<br/>我要述说救我恩典。<br/>','',54921,8456);
INSERT INTO stanza VALUES('Z249','2','有日地上帐棚倾覆，<br/>我也不知何日何载；<br/>但我确知有个去处，<br/>使我能以与主同在。<br/>','',54922,8457);
INSERT INTO stanza VALUES('Z249','3','或者有日救主再临，<br/>那时工作即将完毕；<br/>得主称许『忠心仆人，』<br/>我要进入祂的安息。<br/>','',54923,8458);
INSERT INTO stanza VALUES('Z249','4','有日；所以我要准备，<br/>把灯剔亮，儆醒守待；<br/>那日我得与主相会，<br/>永远享受祂的同在。<br/>','',54924,8459);
INSERT INTO stanza VALUES('Z250','1','来阿，你这万福泉源！<br/>调整我心来歌唱；<br/>怜悯江河涌流不断，<br/>召我高声来颂扬。<br/>我本外人离神流浪，<br/>基督亲来寻找我；<br/>因要救我脱离死亡，<br/>祂竟为我被钉戳。<br/>','',54925,8460);
INSERT INTO stanza VALUES('Z250','2','我今天天被你激励，<br/>对你恩典来负债；<br/>我主，让此恩典维系<br/>我这流浪的心怀。<br/>我认我是趋向流浪，<br/>趋向离开爱的神；<br/>求你用你灵的力量，<br/>将我荡心来吸引。<br/>','',54926,8461);
INSERT INTO stanza VALUES('Z250','3','我已得着你的救恩，<br/>脱离罪恶和死亡；<br/>但愿能作脱俗的人，<br/>显出神子的景况。<br/>我今建立以便以谢，<br/>因你一直赐帮助；<br/>因你喜悦，我望永得<br/>你的带领和眷顾。<br/>','',54927,8462);
INSERT INTO stanza VALUES('Z251','1','一切我所有，<br/>无非是接受；<br/>全是恩所赐，<br/>在我信之后；<br/>所以不自夸，也不自尊，<br/>我是一个罪人蒙主恩！<br/>','',54928,8463);
INSERT INTO stanza VALUES('Z251','chorus','我是个罪人蒙主恩！<br/>我是个罪人蒙主恩！<br/>这是我身分，<br/>荣耀归给神，<br/>我是个罪人蒙主恩！<br/>','',54929,8464);
INSERT INTO stanza VALUES('Z251','2','从前我愚昧，<br/>罪恶辖我心，<br/>使我的脚步完全远离神；<br/>今被主寻回，能不欢欣？<br/>现今是个罪人蒙主恩！<br/>','',54930,8465);
INSERT INTO stanza VALUES('Z251','3','流泪有何用，<br/>功行有何效？<br/>若非神怜悯，<br/>灭亡怎能逃？<br/>前我因有罪，不敢近神，<br/>现今是个罪人蒙主恩！<br/>','',54931,8466);
INSERT INTO stanza VALUES('Z251','4','我爱我救主，<br/>心中乐欢腾，<br/>我这蒙恩人不能不说明；<br/>让我再说明-用尽声音-<br/>我是一个罪人蒙主恩！<br/>','',54932,8467);
INSERT INTO stanza VALUES('Z252','1','前在埃及为罪奴仆，<br/>不知何为平安，<br/>良心常有罪的重负，<br/>昼夜无安息；<br/>欲求自由，少烧砖土，<br/>反而增加负担，<br/>可怜，从未听见<br/>荣美之地。<br/>','',54933,8468);
INSERT INTO stanza VALUES('Z252','chorus','今我登巍巍高山，<br/>在光天化日之中，<br/>今我饮滚滚活泉，<br/>长年涌流无终，<br/>今我得丰富，地满乳蜜，<br/>路滴脂油，恩重重，<br/>乐哉！今我居荣美之地。<br/>','',54934,8469);
INSERT INTO stanza VALUES('Z252','2','幸得神赐逾越羔羊，<br/>因血得着救赎，<br/>经过受浸，进入野疆，<br/>完全脱埃及，<br/>时有试探，时有力量，<br/>常走弯曲道路，<br/>没有信心去进荣美之地。<br/>','',54935,8470);
INSERT INTO stanza VALUES('Z252','3','我主基督将我高升，<br/>与祂同坐天上，<br/>空中权势无不溃崩，<br/>撒但不安席，<br/>奉主名字，阴府无能，<br/>今都向我退让，<br/>完全得胜，<br/>在于荣美之地。<br/>','',54936,8471);
INSERT INTO stanza VALUES('Z252','4','在此乃是无边平安，<br/>乃是无比喜乐，<br/>不再忧愁，不觉孤单，<br/>完全是安息，<br/>爱何甘甜，交通何欢，<br/>处处都是诗歌，<br/>阿利路亚，<br/>这是荣美之地。<br/>','',54937,8472);
INSERT INTO stanza VALUES('Z253','1','在我心中欢奏一音乐，<br/>乃是恩主柔声说：<br/>『我必永远不将你弃绝，<br/>你必永远属于我。』<br/>','',54938,8473);
INSERT INTO stanza VALUES('Z253','chorus','耶稣，耶稣，耶稣！<br/>最甜美之名，<br/>满足我的衷情，<br/>使我唱着往前行。<br/>','',54939,8474);
INSERT INTO stanza VALUES('Z253','2','我的人生原被罪所害，<br/>心情痛苦无和谐；<br/>等到恩主进入我心怀，<br/>心弦欢奏永不歇。<br/>','',54940,8475);
INSERT INTO stanza VALUES('Z253','3','我今享受祂恩与祂爱，<br/>安息在祂胸怀间，<br/>时常见祂笑脸向我开，<br/>因此欢乐又颂赞。<br/>','',54941,8476);
INSERT INTO stanza VALUES('Z253','4','有时虽遇苦难如火烧，<br/>苦中有祂作我伴；<br/>有时虽有重担似难挑，<br/>重量有祂替我担。<br/>','',54942,8477);
INSERT INTO stanza VALUES('Z253','5','不久祂来接我到天上，<br/>远离今生的捆绑，<br/>那时我必变成祂形状，<br/>并要与祂同作王。<br/>','',54943,8478);
INSERT INTO stanza VALUES('Z254','1','多年疲惫，未能寻到一泉源-<br/>永不干涸的活泉；<br/>地上一切全都未能如我愿-<br/>无何能使我心满。<br/>','',54944,8479);
INSERT INTO stanza VALUES('Z254','chorus','我今饮于永不干涸的活泉，<br/>我今饮于生命活水泉源；<br/>甜美、喜乐、欢畅，<br/>何其无限无量，<br/>我今饮于生命活水泉源。<br/>','',54945,8480);
INSERT INTO stanza VALUES('Z254','2','永远不在罪的野地再流荡，<br/>我已寻到活水泉；<br/>我的喜乐之杯满溢而流淌，<br/>基督已使我心满。<br/>','',54946,8481);
INSERT INTO stanza VALUES('Z254','3','在此所得满足越过越甜美，<br/>在此得主的安息；<br/>在此所受安慰越过越加倍，<br/>在此受主的福气。<br/>','',54947,8482);
INSERT INTO stanza VALUES('Z254','4','在此得到永无止境的供应，<br/>在此恩中永沐浴；<br/>向这医治活泉，我心必全倾，<br/>直到永世不稍渝。<br/>','',54948,8483);
INSERT INTO stanza VALUES('Z255','1','我心中奏一甜美音乐，<br/>恩主耶稣是我歌；<br/>从无一音乐如此妙绝，<br/>使我尝到天上乐。<br/>','',54949,8484);
INSERT INTO stanza VALUES('Z255','chorus','在我心中唱一甜美诗歌，<br/>唱一甜美诗歌，<br/>唱天上乐歌；<br/>在我心中唱一甜美诗歌，<br/>唱那奇妙爱之歌。<br/>','',54950,8485);
INSERT INTO stanza VALUES('Z255','2','奇妙爱！耶稣将我救活，<br/>使我得着救恩乐；<br/>何大恩！基督替我活着，<br/>使我欢唱恩爱歌。<br/>','',54951,8486);
INSERT INTO stanza VALUES('Z255','3','何光明！耶稣领我行路，<br/>步步唱着上行诗；<br/>何平安！基督与我同住，<br/>时时涌出赞美辞。<br/>','',54952,8487);
INSERT INTO stanza VALUES('Z255','4','何超脱！我要被提上升，<br/>圣徒必唱凯旋歌；<br/>何尊荣！我要同主执政，<br/>天使必奏同声贺。<br/>','',54953,8488);
INSERT INTO stanza VALUES('Z255','5','何福气！还要进到圣城，<br/>永饮生命的乐河；<br/>何快乐！且要享主丰盛，<br/>饱尝生命的美果。<br/>','',54954,8489);
INSERT INTO stanza VALUES('Z256','1','基督使我心中喜乐，<br/>基督使我口中高歌；<br/>有祂同在，就能欢畅，<br/>有祂同在，就能歌唱！<br/>','',54955,8490);
INSERT INTO stanza VALUES('Z256','chorus','阿利路亚，真能歌唱！<br/>阿利路亚，真能欢畅！<br/>有祂同在，就能欢畅，<br/>有祂同在，就能歌唱！<br/>','',54956,8491);
INSERT INTO stanza VALUES('Z256','2','从前心身全是重担，<br/>今日里外都是平安；<br/>祂已赦我一切罪愆，<br/>祂已担我一切为难。<br/>','',54957,8492);
INSERT INTO stanza VALUES('Z256','3','从前瞎眼，暗如夜半，<br/>今日看见，明如中天；<br/>祂已救我脱离迷途，<br/>祂今领我行走正路。<br/>','',54958,8493);
INSERT INTO stanza VALUES('Z256','4','从前一人寂寞、孤单，<br/>今日有祂作我同伴，<br/>天天相随，时时相偕，<br/>处处体谅，事事体贴。<br/>','',54959,8494);
INSERT INTO stanza VALUES('Z256','5','祂爱甘甜，激我走路，<br/>祂恩丰满，使我顺服；<br/>祂的爱心将我拯救，<br/>祂的恩手将我保守。<br/>','',54960,8495);
INSERT INTO stanza VALUES('Z256','6','除祂以外，在天有谁？<br/>除祂以外，在地无归！<br/>祂之爱我，直到万代！<br/>我之爱祂，岂只现在？<br/>','',54961,8496);
INSERT INTO stanza VALUES('Z257','1','一生渴慕我能饮于<br/>一个清凉的泉源，<br/>得以解除里面所感<br/>火烧一般的渴干。<br/>','',54962,8497);
INSERT INTO stanza VALUES('Z257','chorus','阿利路亚！<br/>我已得到<br/>我心久所渴慕者！<br/>基督满足我的愿望，<br/>借祂生命救了我。<br/>','',54963,8498);
INSERT INTO stanza VALUES('Z257','2','前吃豆荚勉以充饥，<br/>直到力量几消没；<br/>虽然想吃较佳之物，<br/>但仍只有忍饥饿。<br/>','',54964,8499);
INSERT INTO stanza VALUES('Z257','3','我前贫穷，寻求丰富，<br/>使我饥饿得满足，<br/>但我所得一切粪土，<br/>只使我求受侮辱。<br/>','',54965,8500);
INSERT INTO stanza VALUES('Z257','4','活水之泉涌流不息，<br/>生命的粮可白得；<br/>难言丰富，永无不足，<br/>我的救主之于我。<br/>','',54966,8501);
INSERT INTO stanza VALUES('Z258','1','以前我心苦楚悲伤，<br/>永生之福无望；<br/>惟有基督今为我王，<br/>我心充满欢畅。<br/>','',54967,8502);
INSERT INTO stanza VALUES('Z258','chorus','今主耶稣满足我心，<br/>并无别人如祂；<br/>历久爱情、生命、欢欣，<br/>都由耶稣赐下。<br/>','',54968,8503);
INSERT INTO stanza VALUES('Z258','2','我尝世间许多好味，<br/>干渴仍然极深；<br/>普天之下万般全备，<br/>仍不满足我心。<br/>','',54969,8504);
INSERT INTO stanza VALUES('Z258','3','以前我心思慕祝福，<br/>并不来寻基督；<br/>我虽忽略我的救主，<br/>祂爱却来寻吾。<br/>','',54970,8505);
INSERT INTO stanza VALUES('Z258','4','我曾试过破裂水池，<br/>希望痛快而喝；<br/>哎哟，水却完全漏失，<br/>讥讽我的干渴。<br/>','',54971,8506);
INSERT INTO stanza VALUES('Z258','5','祝福丧失，我心悲哀，<br/>仍未想到祂来；<br/>蒙昧心目，祂为我开，<br/>始知祂是可爱。<br/>','',54972,8507);
INSERT INTO stanza VALUES('Z259','1','我真不知神的奇恩<br/>为何临到我身；<br/>我也不知不堪如我，<br/>救来有何足多。<br/>','',54973,8508);
INSERT INTO stanza VALUES('Z259','chorus','惟知道我所信的是谁，<br/>并且也深信祂实在是能<br/>保守我所信托祂的，<br/>都全备直到那日！<br/>','',54974,8509);
INSERT INTO stanza VALUES('Z259','2','我真不知救我的信<br/>如何进入我心，<br/>我也不知何以一信，<br/>便得一个新心。<br/>','',54975,8510);
INSERT INTO stanza VALUES('Z259','3','我真不知圣灵如何<br/>引人知道己过，<br/>并由圣经显明耶稣，<br/>使人接祂为主。<br/>','',54976,8511);
INSERT INTO stanza VALUES('Z259','4','我真不知我的前途<br/>到底是甘是苦；<br/>我也不知未见主前<br/>还有甚么试炼。<br/>','',54977,8512);
INSERT INTO stanza VALUES('Z259','5','我真不知何时主来，<br/>那时我是何在-<br/>到底我当经过死谷？<br/>或将空中遇主？<br/>','',54978,8513);
INSERT INTO stanza VALUES('Z260','1','稳固的根基，<br/>为信徒已建立，<br/>在神话语中，<br/>其稳固胜天地。<br/>你既投靠主，<br/>如投到避难所，<br/>神话就保证你<br/>永远是稳妥。<br/>神话就保证你<br/>永远是稳妥。<br/>','',54979,8514);
INSERT INTO stanza VALUES('Z260','2','主说信祂者，<br/>必永远不灭亡；<br/>无谁从祂手，<br/>能夺去祂的羊。<br/>父比万有大，<br/>主与父原为一；<br/>凡父赐祂的，<br/>祂一个不失遗。<br/>','',54980,8515);
INSERT INTO stanza VALUES('Z260','3','神所称义者，<br/>有谁能再控告？<br/>主所替死者，<br/>有谁能再追讨？<br/>神义既赐你，<br/>有谁能来除灭？<br/>主爱既属你，<br/>有谁能来隔绝？<br/>','',54981,8516);
INSERT INTO stanza VALUES('Z260','4','凡是就主者，<br/>主永远不丢弃；<br/>凡是靠主者，<br/>主都能救到底。<br/>祂是你生命，<br/>你又是祂肢体，<br/>与祂合为一，<br/>何能使再分离？<br/>','',54982,8517);
INSERT INTO stanza VALUES('Z260','5','当你遇试探，<br/>那恶者来迷惑，<br/>使你心疑虑，<br/>如海中起风波，<br/>抓住主的话，<br/>速抛出信心锚，<br/>坚固又牢靠，<br/>必永远不动摇。<br/>','',54983,8518);
INSERT INTO stanza VALUES('Z261','1','哦来，蒙恩群众，<br/>释放而欢腾，<br/>同来称谢主，<br/>歌祂恩何丰盛！<br/>祂赎你罪过，<br/>又赐你神生命。<br/>同来称谢耶稣，<br/>同来称谢耶稣，<br/>同来称谢耶稣，<br/>我救主基督。<br/>','',54984,8519);
INSERT INTO stanza VALUES('Z261','2','哦来，蒙爱群众，<br/>稳固不摇动，<br/>同来颂扬主，<br/>唱祂爱何深泓！<br/>祂已拯救你，<br/>又永住你心中。<br/>同来颂扬耶稣，<br/>同来颂扬耶稣，<br/>同来颂扬耶稣，<br/>我救主基督。<br/>','',54985,8520);
INSERT INTO stanza VALUES('Z261','3','哦来，蒙召群众，<br/>圣洁又光荣，<br/>同来敬拜主，<br/>赞祂名何超众！<br/>祂是万有主，<br/>又是王至高耸。<br/>同来敬拜耶稣，<br/>同来敬拜耶稣，<br/>同来敬拜耶稣，<br/>我救主基督。<br/>','',54986,8521);
INSERT INTO stanza VALUES('Z262','1','今有荣光照耀我魂间，<br/>胜于星月太阳；<br/>光线清新，辉煌又灿烂，<br/>因主就是这光。<br/>','',54987,8522);
INSERT INTO stanza VALUES('Z262','chorus','荣耀之光！福乐之光！<br/>带来平安喜乐滚滚浪；<br/>当主耶稣笑脸欣欣放，<br/>荣耀之光照明亮。<br/>','',54988,8523);
INSERT INTO stanza VALUES('Z262','2','今有音乐洋溢我魂间，<br/>颂赞我主我王；<br/>恩主在听，且也会听见，<br/>尽管我拙于唱。<br/>','',54989,8524);
INSERT INTO stanza VALUES('Z262','3','今有平安弥漫我魂间，<br/>因主在我心房；<br/>平安之鸽吟于我心坎，<br/>恩典之花开放。<br/>','',54990,8525);
INSERT INTO stanza VALUES('Z262','4','今有喜乐充满我魂间，<br/>且有颂赞盼望；<br/>因主向我既已施恩典，<br/>为我又储天赏。<br/>','',54991,8526);
INSERT INTO stanza VALUES('Z263','1','今日何日！我意立定，<br/>拣选耶稣作我救主！<br/>我心欢乐如火荧荧，<br/>将此欢乐到处传述。<br/>','',54992,8527);
INSERT INTO stanza VALUES('Z263','chorus','快乐日！快乐日！<br/>耶稣救我，使我欢乐！<br/>赎罪宝血洗我罪恶！<br/>生命活水解我干渴！<br/>快乐日！快乐日！<br/>耶稣救我，使我欢乐！<br/>','',54993,8528);
INSERT INTO stanza VALUES('Z263','2','此意一定，永不反悔，<br/>主今属我，我也属主；<br/>祂既吸引，我必跟随，<br/>欢然答应祂的招呼。<br/>','',54994,8529);
INSERT INTO stanza VALUES('Z263','3','前我二意，今可安定，<br/>让主作我惟一中心：<br/>注定于祂，永不别倾，<br/>有祂就有一切福分。<br/>','',54995,8530);
INSERT INTO stanza VALUES('Z263','4','今在主前立定此意，<br/>更愿此意与日俱新，<br/>直到临终双目垂闭，<br/>进入永远与祂更亲。<br/>','',54996,8531);
INSERT INTO stanza VALUES('Z264','1','真奥秘！真奥秘！<br/>主基督与罪人合为一。<br/>或人事、或时地，<br/>不能使主与我再分离。<br/>阿利路亚！阿利路亚！<br/>荣耀的奥秘！<br/>真奥秘！真奥秘！<br/>在主里我与神永合一。<br/>','',54997,8532);
INSERT INTO stanza VALUES('Z264','2','真超脱！真超脱！<br/>我已经与基督同复活；<br/>是罪恶、是鬼魔，<br/>从今后都不能再缠我；<br/>阿利路亚！阿利路亚！<br/>荣耀的超脱！<br/>真超脱！真超脱！<br/>我现今与基督同活着。<br/>','',54998,8533);
INSERT INTO stanza VALUES('Z265','1','有福的确据，基督属我！<br/>豫尝神荣耀，何等快活！<br/>蒙宝血赎回，领受恩赐；<br/>由圣灵重生，作神后嗣。<br/>','',54999,8534);
INSERT INTO stanza VALUES('Z265','chorus','这是我见证，是我诗歌，<br/>赞美我救主，口唱心和！<br/>这是我见证，是我诗歌，<br/>赞美我救主，终日欢乐！<br/>','',55000,8535);
INSERT INTO stanza VALUES('Z265','2','完全的顺服，完全甘甜，<br/>被提的景象，显在眼前；<br/>似乎有声音，从天而来，<br/>细说主怜悯，柔述主爱。<br/>','',55001,8536);
INSERT INTO stanza VALUES('Z265','3','完全的顺服，完全安息，<br/>与主时交通，何等福气；<br/>儆醒且等候，仰望主来，<br/>充满主甘甜，浸透主爱。<br/>','',55002,8537);
INSERT INTO stanza VALUES('Z266','1','我无技巧前来领会<br/>神的旨意、神的定规；<br/>但我只知有了一位，<br/>在祂右边是救主。<br/>','',55003,8538);
INSERT INTO stanza VALUES('Z266','2','『基督已为罪人死了，』<br/>我读话语，我信功效，<br/>因在我心我有需要：<br/>祂来作我的救主。<br/>','',55004,8539);
INSERT INTO stanza VALUES('Z266','3','是否没有别的法子<br/>给神去作？我是不知；<br/>但我只能连唱美诗，<br/>因祂救我借救主。<br/>','',55005,8540);
INSERT INTO stanza VALUES('Z266','4','祂竟离开荣耀天畔，<br/>竟来地上为人受难；<br/>你说奇怪，我无同感，<br/>因我已经识救主。<br/>','',55006,8541);
INSERT INTO stanza VALUES('Z266','5','但愿祂能在我心里，<br/>完全看见劳苦功绩，<br/>使祂对祂工作满意，<br/>如同我对我救主。<br/>','',55007,8542);
INSERT INTO stanza VALUES('Z266','6','让我无论生存、死亡，<br/>得力、得慰从这宝矿；<br/>祂今活着永远为王，<br/>却曾死过为救主。<br/>','',55008,8543);
INSERT INTO stanza VALUES('Z267','1','多年过着虚妄的生活，<br/>不理我主如何被钉戳，<br/>不知祂死原是为着我，<br/>在加略山。<br/>','',55009,8544);
INSERT INTO stanza VALUES('Z267','chorus','广大怜悯，白白的恩典；<br/>众多罪愆我全得赦免，<br/>得着释放脱去了重担，<br/>在加略山。<br/>','',55010,8545);
INSERT INTO stanza VALUES('Z267','2','蒙神光照，得知我罪愆，<br/>恐惧战兢，在律法跟前，<br/>直到我心完全的回转，<br/>向加略山。<br/>','',55011,8546);
INSERT INTO stanza VALUES('Z267','3','今将一切，全都献给主，<br/>甘心乐意作祂的奴仆，<br/>永远不忘祂所受的苦，<br/>在加略山。<br/>','',55012,8547);
INSERT INTO stanza VALUES('Z267','4','哦！爱何大，<br/>计划了救恩！<br/>哦！恩何丰，<br/>将此带给人！<br/>哦！力何强，<br/>带我归向神，<br/>在加略山。<br/>','',55013,8548);
INSERT INTO stanza VALUES('Z268','1','平安正如水流，<br/>一路跟随我；<br/>忧虑却如怒涛横涌；<br/>任何的遭遇，<br/>你已教我能说：<br/>我魂，你应安息，<br/>无所恐！<br/>','',55014,8549);
INSERT INTO stanza VALUES('Z268','chorus','哦，我魂，可无恐！<br/>哦，我魂，<br/>可安乐、可无恐！<br/>','',55015,8550);
INSERT INTO stanza VALUES('Z268','2','撒但虽来肆虐，<br/>试炼虽如火，<br/>我心应当充满把握；<br/>因主明瞭<br/>我是何等的软弱，<br/>祂已为我流血成工作。<br/>','',55016,8551);
INSERT INTO stanza VALUES('Z268','3','我罪-这是何等<br/>荣耀的思想，<br/>我罪-非局部乃拢总，<br/>全钉在祂十架，<br/>不压我身上，<br/>我魂，你要称颂、<br/>要称颂！<br/>','',55017,8552);
INSERT INTO stanza VALUES('Z268','4','活着乃是基督，<br/>是基督执政，<br/>就是死河兴起波澜，<br/>我也没有苦痛，<br/>因死要如生，<br/>听祂低声对我赐平安。<br/>','',55018,8553);
INSERT INTO stanza VALUES('Z268','5','哦，我主、我救主，<br/>我等你再临，<br/>我是望你不是望墓；<br/>哦，天使的号筒！<br/>哦，主的声音！<br/>何等的希望，永远的福！<br/>','',55019,8554);
INSERT INTO stanza VALUES('Z269','1','我如困鹿切慕溪水，<br/>里面干渴难言；<br/>哦神，我心惟你是追，<br/>并你复苏恩典。<br/>','',55020,8555);
INSERT INTO stanza VALUES('Z269','2','活的神阿，你是我神，<br/>我心饥渴要你；<br/>深愿全人与你相亲，<br/>尽享你的自己。<br/>','',55021,8556);
INSERT INTO stanza VALUES('Z269','3','你是我的生命、力量，<br/>也是我的居所；<br/>你在基督给我饱尝，<br/>在祂给我得着。<br/>','',55022,8557);
INSERT INTO stanza VALUES('Z269','4','你的笑脸是我拯救，<br/>我今向你仰望；<br/>你的同在是我所求，<br/>愿你多多恩赏。<br/>','',55023,8558);
INSERT INTO stanza VALUES('Z269','5','我如困鹿切慕溪水，<br/>愿你赏我所欲；<br/>哦神，除你何能施惠？<br/>惟你是我所需。<br/>','',55024,8559);
INSERT INTO stanza VALUES('Z270','1','我心所追求乃是神自己，<br/>不是乐与安，<br/>也不是福气；<br/>我能出代价，<br/>达到这圣地，<br/>不是我自己，<br/>乃是祂恩力。<br/>','',55025,8560);
INSERT INTO stanza VALUES('Z270','2','因信而向前，<br/>要得神自己，<br/>凭爱而跟随，<br/>永远不他依；<br/>愿主拯救我脱离我自己，<br/>直到神一切充满在我里。<br/>','',55026,8561);
INSERT INTO stanza VALUES('Z270','3','虽然这道路有时真可怕，<br/>虽然这代价常是非常大，<br/>但是神知道何者是我需，<br/>得着神的路永不能弯曲。<br/>','',55027,8562);
INSERT INTO stanza VALUES('Z270','4','一事我所知，<br/>祂永不会错，<br/>一事我所作，<br/>要将祂得着；<br/>一天过一天神是我所要，<br/>至终的赏赐，<br/>神作我荣耀。<br/>','',55028,8563);
INSERT INTO stanza VALUES('Z271','1','全能的神，<br/>非受造的生命，<br/>听我呼求，<br/>允我在此所请；<br/>无限荣耀，<br/>在你周身围绕，<br/>生命赐者，<br/>求你给我所要。<br/>','',55029,8564);
INSERT INTO stanza VALUES('Z271','2','借着基督所经历的十架，<br/>借着祂死所成功的击杀，<br/>黑暗权势，<br/>救我全然脱离，<br/>迁我到你爱子光明国里。<br/>','',55030,8565);
INSERT INTO stanza VALUES('Z271','3','从我中心，<br/>将我绝对充满，<br/>满到圆周，<br/>满达四周边缘；<br/>在我周身，<br/>直到极边之上，<br/>射出你的荣耀所有光芒。<br/>','',55031,8566);
INSERT INTO stanza VALUES('Z271','4','非造生命，<br/>你是至圣的神，<br/>生命之灵，<br/>求你今在我心，<br/>有所创作，<br/>使我显你荣耀，<br/>并且逼我除你别无所要。<br/>','',55032,8567);
INSERT INTO stanza VALUES('Z271','5','感谢父神，<br/>我已得你恩赏，<br/>同着基督，<br/>今在生命作王；<br/>我已满足，<br/>且因基督夸胜，<br/>借祂十架，<br/>得享丰盛生命。<br/>','',55033,8568);
INSERT INTO stanza VALUES('Z272','1','旷野之中为着神！<br/>一丛荆棘在火焚！<br/>愿我如此蒙你恩，<br/>使你荣耀显我身。<br/>','',55034,8569);
INSERT INTO stanza VALUES('Z272','2','仅是平常的荆棘，<br/>神能在牠显为奇，<br/>神能凭牠显能力，<br/>神能借牠行神迹。<br/>','',55035,8570);
INSERT INTO stanza VALUES('Z272','3','不是用牠作燃料，<br/>乃神自己来燃烧；<br/>神在牠身无所要，<br/>仅要借牠显荣耀。<br/>','',55036,8571);
INSERT INTO stanza VALUES('Z272','4','神借荆棘来显现，<br/>无他只见神火焰；<br/>愿我如此，借恩典<br/>使你荣耀显完全！<br/>','',55037,8572);
INSERT INTO stanza VALUES('Z273','1','神，<br/>你正在重排我的前途，<br/>你也正在拆毁我的建筑，<br/>忠心事奉的人日少一日，<br/>误会增加，<br/>清白逐渐消失。<br/>','',55038,8573);
INSERT INTO stanza VALUES('Z273','chorus','我眼有泪珠，<br/>看不清你脸面，<br/>好像你话语真实不如前；<br/>你使我减少，<br/>好叫你更加添，<br/>好叫你旨意比前更甘甜。<br/>','',55039,8574);
INSERT INTO stanza VALUES('Z273','2','我几乎要求你停止你手，<br/>当我觉得我已无力再受；<br/>但你是神，<br/>你怎可以让步？<br/>求你不要让步，<br/>等我顺服。<br/>','',55040,8575);
INSERT INTO stanza VALUES('Z273','3','如果你的旨意和你喜乐<br/>乃是在乎我负痛苦之轭，<br/>就愿我的喜乐乃是在乎<br/>顺服你的旨意来受痛苦。<br/>','',55041,8576);
INSERT INTO stanza VALUES('Z273','4','好像你的喜乐所需代价<br/>乃是需我受你阻扼倒下，<br/>所以我就欢迎你的阻扼，<br/>好叫我能使你的心喜乐。<br/>','',55042,8577);
INSERT INTO stanza VALUES('Z273','5','你将车辆赐与别人乘坐，<br/>你使他们从我头上轧过；<br/>我的所有你正下手剥夺，<br/>求你留下剥夺的手给我。<br/>','',55043,8578);
INSERT INTO stanza VALUES('Z274','1','神圣之爱，远超众爱，<br/>天上之乐临地上，<br/>竟来住我卑微胸怀，<br/>作我相信的恩赏。<br/>恩主，你是所有怜悯，<br/>你是纯洁无限爱；<br/>眷顾我们，带来救恩，<br/>进入相信的胸怀。<br/>','',55044,8579);
INSERT INTO stanza VALUES('Z274','2','哦主，向我吹你圣灵，<br/>吹进烦扰的心里；<br/>使我有分你的丰盛，<br/>享受应许的安息。<br/>从我除去罪的爱好，<br/>除去一切的捆绑；<br/>使我认识生命之道，<br/>使我完全得释放。<br/>','',55045,8580);
INSERT INTO stanza VALUES('Z274','3','大能的主，前来拯救，<br/>丰盛生命赐给我；<br/>愿你同在直到永久，<br/>在你殿中永住着。<br/>我要时常颂赞你名，<br/>照你喜悦事奉你，<br/>不住祷告，不住颂称，<br/>夸耀你爱永无已。<br/>','',55046,8581);
INSERT INTO stanza VALUES('Z274','4','求你完成你的新造，<br/>使我纯洁无瑕疵；<br/>你大救恩我全享到，<br/>得以和你全相似；<br/>更新变化、荣上加荣，<br/>直到满有你身量，<br/>直到进入荣耀之中，<br/>永远将你爱颂扬。<br/>','',55047,8582);
INSERT INTO stanza VALUES('Z275','1','亲爱主！宝贝主！<br/>我轻视我事物；<br/>有谁像你如此美丽？<br/>如此甘甜？如此柔细？<br/>你是人中无比，<br/>谁能与你相匹？<br/>','',55048,8583);
INSERT INTO stanza VALUES('Z275','2','亲爱主！宝贝主！<br/>我听见你招呼；<br/>你的声音入我心内，<br/>我就脱离所有缠累，<br/>骄傲都归虚无，<br/>追求都变庸俗。<br/>','',55049,8584);
INSERT INTO stanza VALUES('Z275','3','亲爱主！宝贝主！<br/>我怎能再顽固？<br/>我将刚硬投你脚旁，<br/>领首诗歌回家去唱，<br/>欢喜作你奴仆，<br/>欢喜向你屈服。<br/>','',55050,8585);
INSERT INTO stanza VALUES('Z275','4','亲爱主！宝贝主！<br/>我拣选你道路；<br/>一面顺服，一面流泪，<br/>但我不肯改变地位，<br/>我要讨你喜悦，<br/>羡慕爱的暴虐。<br/>','',55051,8586);
INSERT INTO stanza VALUES('Z275','5','亲爱主！宝贝主！<br/>自从你去天府，<br/>我脸好像不能再笑，<br/>我天好像不能再晓，<br/>我只想你回来，<br/>我只想你同在。<br/>','',55052,8587);
INSERT INTO stanza VALUES('Z275','6','亲爱主！宝贝主！<br/>让我来向你诉，<br/>你是我所朝夕思慕，<br/>只有你能使我满足，<br/>得你甚么都有，<br/>你外无所要求。<br/>','',55053,8588);
INSERT INTO stanza VALUES('Z275','7','亲爱主！宝贝主！<br/>我奉献我事物；<br/>有谁像你如此美丽，<br/>如此甘甜，如此柔细？<br/>你是人中无比，<br/>谁能与你相匹？<br/>','',55054,8589);
INSERT INTO stanza VALUES('Z276','1','你若取去我的心爱，<br/>求以自己给我；<br/>你若仍定我受疑猜，<br/>求以自己给我。<br/>','',55055,8590);
INSERT INTO stanza VALUES('Z276','chorus','主耶稣，亲爱救主，<br/>多以自己给我；<br/>我向你完全顺服，<br/>多以自己给我。<br/>','',55056,8591);
INSERT INTO stanza VALUES('Z276','2','你使我的望星迷糊，<br/>求以自己给我；<br/>你许我的心绪起伏，<br/>求以自己给我。<br/>','',55057,8592);
INSERT INTO stanza VALUES('Z276','3','你既拆毁我所倚靠，<br/>求以自己给我，<br/>你既拒绝我的祷告，<br/>求以自己给我。<br/>','',55058,8593);
INSERT INTO stanza VALUES('Z276','4','我若需要仍旧忍耐，<br/>仍以自己给我；<br/>你若尚未立即再来，<br/>再加自己给我。<br/>','',55059,8594);
INSERT INTO stanza VALUES('Z277','1','请进，哦请进！<br/>大门现已开；<br/>这是你声音，<br/>我能认出来。<br/>夕阳早西沉，<br/>风暴已来临；<br/>这是你时候，<br/>哦救主，请进！<br/>','',55060,8595);
INSERT INTO stanza VALUES('Z277','2','唉，这个零乱<br/>凄凉的房间：<br/>家中的用具乱堆于幽暗，<br/>座椅未整理，<br/>饭桌空站着，<br/>呀，岂可如此<br/>待永世佳客！<br/>','',55061,8596);
INSERT INTO stanza VALUES('Z277','3','但就此欢迎；这情景惨甚<br/>就是我请你进来的原因；<br/>这黑暗混乱且即刻要求<br/>你光明同在，<br/>并整理的手。<br/>','',55062,8597);
INSERT INTO stanza VALUES('Z277','4','在你这佳客光顾的跟前，<br/>我不再寻求修补或改善；<br/>一切全不像，<br/>且比人更坏，<br/>使你仍等候，<br/>不能就进来。<br/>','',55063,8598);
INSERT INTO stanza VALUES('Z277','5','请进，非来寻，<br/>乃是使这心<br/>配作你居所，<br/>适合你留存；<br/>将黑暗、罪恶，<br/>驱逐得净尽：<br/>请进，主耶稣，<br/>现在就请进！<br/>','',55064,8599);
INSERT INTO stanza VALUES('Z278','1','光中之光，照进！<br/>罪恶之夜驱尽，<br/>白日显于内心，<br/>光中之光，照进！<br/>','',55065,8600);
INSERT INTO stanza VALUES('Z278','chorus','哦，超过众光之光，<br/>请来住我心房；<br/>哦，驱散忧苦之乐，<br/>请来我心住着。<br/>','',55066,8601);
INSERT INTO stanza VALUES('Z278','2','乐中之乐，请进！<br/>罪恶之苦去尽，<br/>平安满我内心，<br/>乐中之乐，请进！<br/>','',55067,8602);
INSERT INTO stanza VALUES('Z278','3','命中之命，倾进！<br/>罪恶之死吞尽，<br/>复苏我的内心，<br/>命中之命，倾进！<br/>','',55068,8603);
INSERT INTO stanza VALUES('Z278','4','爱中之爱，流进！<br/>罪恶之恨除根，<br/>更新我的内心，<br/>爱中之爱，流进！<br/>','',55069,8604);
INSERT INTO stanza VALUES('Z278','5','天上之天，降临！<br/>破除云幔遮隐，<br/>地上扰乱除尽，<br/>天上之天，降临！<br/>','',55070,8605);
INSERT INTO stanza VALUES('Z278','6','我神我主，请来！<br/>安家在我心怀，<br/>赐我丰满同在，<br/>我神我主，请来。<br/>','',55071,8606);
INSERT INTO stanza VALUES('Z279','1','哦主，带着丰富请进，<br/>眷顾我这复苏之心，<br/>良心血已洗净；<br/>将你自己向我供应，<br/>使我享受你的丰盛，<br/>因我是神所生。<br/>','',55072,8607);
INSERT INTO stanza VALUES('Z279','2','不让甚么分我心情，<br/>因我与你已经同钉，<br/>现今向神活着。<br/>我向世界和牠妖姿，<br/>并牠偶像、娱乐已死，<br/>让你作我荣耀。<br/>','',55073,8608);
INSERT INTO stanza VALUES('Z279','3','不灭之渴向我惠顾，<br/>赐我无限渴望羡慕，<br/>你是我心所爱。<br/>少于你者，请勿赐给，<br/>必须你来作我恩惠；<br/>带你所是而来！<br/>','',55074,8609);
INSERT INTO stanza VALUES('Z279','4','从前一切失丧于你，<br/>今后一切是你自己，<br/>你是我们永分。<br/>蒙召有分于你交通，<br/>你外不再有所爱钟，<br/>哦来，恩上加恩！<br/>','',55075,8610);
INSERT INTO stanza VALUES('Z280','1','哦主，你是我的生命，<br/>也是生命供应；<br/>求在灵中眷顾我灵，<br/>使我生命丰盛。<br/>','',55076,8611);
INSERT INTO stanza VALUES('Z280','2','将你自己于我应用，<br/>向我吹你圣灵；<br/>使我经历与你同钉，<br/>模成你死之形。<br/>','',55077,8612);
INSERT INTO stanza VALUES('Z280','3','你已胜过阴府、撒但，<br/>但仍与我相争；<br/>愿你工作在我里面，<br/>杀死并且供应。<br/>','',55078,8613);
INSERT INTO stanza VALUES('Z280','4','当我天然被你治死，<br/>你就应用于我；<br/>将我埋葬，永不再世，<br/>使我同你活着。<br/>','',55079,8614);
INSERT INTO stanza VALUES('Z280','5','在我里面掌权作王，<br/>征服倔强仇敌；<br/>从我显出你的形像，<br/>活出你的自己。<br/>','',55080,8615);
INSERT INTO stanza VALUES('Z280','6','从我除去罪的余烬，<br/>使我作你居所；<br/>愿你荣耀浸透全人，<br/>神在我身显着。<br/>','',55081,8616);
INSERT INTO stanza VALUES('Z281','1','愿我爱你更深！<br/>爱你更深！<br/>哦主，听此求恳，<br/>成全此心。<br/>我心真是切慕：<br/>爱你更深，我主，<br/>爱你更深，<br/>爱你更深！<br/>','',55082,8617);
INSERT INTO stanza VALUES('Z281','2','前我追求世福、<br/>贪享安乐，<br/>今只寻求基督，<br/>解我干渴；<br/>我今惟独切慕：<br/>爱你更深，我主，<br/>爱你更深，<br/>爱你更深！<br/>','',55083,8618);
INSERT INTO stanza VALUES('Z281','3','哦，让痛苦、伤悲，<br/>将我试炼；<br/>你的使者何美！<br/>其歌何甜！<br/>我同他们唱出：<br/>爱你更深，我主，<br/>爱你更深，<br/>爱你更深！<br/>','',55084,8619);
INSERT INTO stanza VALUES('Z281','4','直到呼吸渐促，<br/>歌声渐收，<br/>我心仍要发出<br/>临别节奏，<br/>且要永远渴慕：<br/>爱你更深，我主，<br/>爱你更深，<br/>爱你更深！<br/>','',55085,8620);
INSERT INTO stanza VALUES('Z282','1','如果我的道路<br/>引我去受苦，<br/>如果你是命定<br/>要我历艰辛，<br/>就愿你我从兹<br/>交通益亲挚，<br/>时也刻也无间，<br/>弥久弥香甜。<br/>','',55086,8621);
INSERT INTO stanza VALUES('Z282','2','如果地乐消减，<br/>求你多给天；<br/>虽然心可伤痛，<br/>愿灵仍赞颂；<br/>地的香甜联结，<br/>若因你分裂，<br/>就愿你我之间，<br/>联结更香甜。<br/>','',55087,8622);
INSERT INTO stanza VALUES('Z282','3','这路虽然孤单，<br/>求你作我伴，<br/>用你笑容鼓舞<br/>我来尽前途；<br/>主，我靠你恩力，<br/>盼望能无己，<br/>作一洁净器皿，<br/>流出你生命。<br/>','',55088,8623);
INSERT INTO stanza VALUES('Z283','1','北风阿，求速兴起！<br/>南风阿，快吹来！<br/>吹在我心的园地，<br/>满园芬芳播开。<br/>北风阿，求速兴起！<br/>南风阿，快吹来！<br/>吹在我心的园地，<br/>满园芬芳播开。<br/>','',55089,8624);
INSERT INTO stanza VALUES('Z283','chorus','愿我的所爱到这里来，<br/>与我永同在，<br/>尝我纯洁爱。<br/>愿我的所爱到这里来，<br/>与我永同在，<br/>尝我纯洁爱。<br/>','',55090,8625);
INSERT INTO stanza VALUES('Z283','2','哪哒香膏浇祂头，<br/>秀丽发擦祂脚；<br/>正当王坐席时候，<br/>满屋馨香四飘。<br/>','',55091,8626);
INSERT INTO stanza VALUES('Z283','3','祂像林中苹果树，<br/>我喜歇祂柔荫；<br/>果实甘甜又成熟，<br/>增我力、畅我心。<br/>','',55092,8627);
INSERT INTO stanza VALUES('Z283','4','我心所爱者，来阿，<br/>-我属你，你属我，<br/>-我们同往田间罢，<br/>享受各样佳果。<br/>','',55093,8628);
INSERT INTO stanza VALUES('Z283','5','愿我在祂的心上，<br/>铭刻如同印戳；<br/>祂爱比死更坚强，<br/>众水不能淹没。<br/>','',55094,8629);
INSERT INTO stanza VALUES('Z283','6','除你以外，在高天<br/>我还可以有谁？<br/>除你以外，在人间<br/>我也别无所归。<br/>','',55095,8630);
INSERT INTO stanza VALUES('Z284','1','没有间隔，<br/>主，没有间隔；<br/>让我见你荣面，<br/>引我近你身边，<br/>然后听你慈言；<br/>没有间隔，<br/>没有间隔。<br/>','',55096,8631);
INSERT INTO stanza VALUES('Z284','2','没有间隔，<br/>主，没有间隔；<br/>但愿地上翻腾<br/>不乱你的微声；<br/>我愿向你忠诚；<br/>没有间隔，<br/>没有间隔。<br/>','',55097,8632);
INSERT INTO stanza VALUES('Z284','3','没有间隔，<br/>主，没有间隔；<br/>没有世上罣虑，<br/>没有属己兴趣，<br/>没有掩饰空虚；<br/>没有间隔，<br/>没有间隔。<br/>','',55098,8633);
INSERT INTO stanza VALUES('Z284','4','没有间隔，<br/>主，没有间隔；<br/>当你亲近我时，<br/>疑惑完全消失，<br/>恐惧也都停止；<br/>没有间隔，<br/>没有间隔。<br/>','',55099,8634);
INSERT INTO stanza VALUES('Z284','5','没有间隔，<br/>主，没有间隔；<br/>求你照耀辉煌，<br/>消灭一切邪光，<br/>作我无限心王；<br/>没有间隔，<br/>没有间隔。<br/>','',55100,8635);
INSERT INTO stanza VALUES('Z284','6','没有间隔，<br/>主，没有间隔；<br/>愿我如此随你，<br/>愿我所见惟你，<br/>愿我所归惟你；<br/>没有间隔，<br/>没有间隔。<br/>','',55101,8636);
INSERT INTO stanza VALUES('Z284','7','没有间隔，<br/>主，没有间隔；<br/>直到我眼看见<br/>你的永光显现，<br/>再无任何黑暗；<br/>没有间隔，<br/>没有间隔。<br/>','',55102,8637);
INSERT INTO stanza VALUES('Z284','7','没有间隔，<br/>主，没有间隔；<br/>直到此生过去，<br/>脱离地上寄庐，<br/>永远与你同居；<br/>没有间隔，<br/>没有间隔。<br/>','',55103,8638);
INSERT INTO stanza VALUES('Z285','1','求主带我上到高山，<br/>给我只见你自己，<br/>天上声音给我听见，<br/>新鲜空气给我吸。<br/>','',55104,8639);
INSERT INTO stanza VALUES('Z285','chorus','带我上到更高之山，<br/>与你交通更亲密；<br/>更在灵中饮于活泉，<br/>更得享受你自己。<br/>','',55105,8640);
INSERT INTO stanza VALUES('Z285','2','更高山上，更高亮光，<br/>远超属地的遮蔽；<br/>生命之中与你同王，<br/>脱开挣扎的自己。<br/>','',55106,8641);
INSERT INTO stanza VALUES('Z285','3','保守我在更高山上，<br/>向着标竿直往前；<br/>直到模成你的形像，<br/>流露你爱和恩典。<br/>','',55107,8642);
INSERT INTO stanza VALUES('Z286','1','我每时刻需你，<br/>可爱恩主；<br/>无人柔声似你，<br/>能施安抚。<br/>','',55108,8643);
INSERT INTO stanza VALUES('Z286','chorus','我需你，主，我需你，<br/>每时刻我需你；<br/>哦主，现在赐恩力，<br/>我来就你。<br/>','',55109,8644);
INSERT INTO stanza VALUES('Z286','2','我每时刻需你，<br/>求你来临；<br/>试探失去能力，<br/>当你亲近。<br/>','',55110,8645);
INSERT INTO stanza VALUES('Z286','3','我每时刻需你，<br/>或乐或苦；<br/>速来住留不离，<br/>免我虚度。<br/>','',55111,8646);
INSERT INTO stanza VALUES('Z286','4','我每时刻需你，<br/>求你指引；<br/>使你所许福气，<br/>应于我身。<br/>','',55112,8647);
INSERT INTO stanza VALUES('Z286','5','我每时刻需你，<br/>至圣恩主；<br/>使我完全属你，<br/>永偕无阻。<br/>','',55113,8648);
INSERT INTO stanza VALUES('Z287','1','主，我是属你，<br/>我听你宣告，<br/>知你爱我的无匹；<br/>但我是渴望能因信升高，<br/>能以和你更亲密。<br/>','',55114,8649);
INSERT INTO stanza VALUES('Z287','chorus','吸引我近，更近，<br/>亲爱主，<br/>直至你流血身边；<br/>吸引我近，更近，更近，<br/>亲爱主，<br/>直至你同在中间。<br/>','',55115,8650);
INSERT INTO stanza VALUES('Z287','2','靠着你恩典，<br/>求你分别我，<br/>从此专一事奉你；<br/>让我灵望你，<br/>有坚定把握，<br/>我志消失你旨里。<br/>','',55116,8651);
INSERT INTO stanza VALUES('Z287','3','费时虽不多，<br/>喜乐已难言，<br/>当我座前小逗遛；<br/>俯伏你脚前，<br/>和你面对面，<br/>交通有如人间友。<br/>','',55117,8652);
INSERT INTO stanza VALUES('Z287','4','爱有其深处，<br/>我不能通晓，<br/>除非有日到那边；<br/>乐有其高处，<br/>我无法达到，<br/>除非安息你面前。<br/>','',55118,8653);
INSERT INTO stanza VALUES('Z288','1','与我同住，<br/>夕阳西沉迅速；<br/>黑暗渐深，<br/>求主与我同住；<br/>安慰消逝，<br/>且无何人能助；<br/>无助之助，<br/>求你与我同住。<br/>','',55119,8654);
INSERT INTO stanza VALUES('Z288','2','人生短日，<br/>转瞬就已入暮，<br/>地乐灯残，<br/>世荣花谢草枯；<br/>四境所见，<br/>尽是变迁朽腐；<br/>你，不变者，<br/>求来与我同住。<br/>','',55120,8655);
INSERT INTO stanza VALUES('Z288','3','莫带威严，<br/>有如王中之王，<br/>只带慈良，<br/>并你施医翅膀，<br/>泪来洗忧，<br/>心来听我求诉；<br/>来，罪人友，<br/>如此与我同住。<br/>','',55121,8656);
INSERT INTO stanza VALUES('Z288','4','你的同在，<br/>时时我都需要；<br/>除你恩典，<br/>何能使魔败逃；<br/>有谁像你，<br/>将我引导扶助；<br/>或阴或晴，<br/>求你与我同住。<br/>','',55122,8657);
INSERT INTO stanza VALUES('Z288','5','有你赐福，<br/>我就不怕敌凶；<br/>病而不苦，<br/>流泪也不酸痛；<br/>甚么毒钩！<br/>甚么死亡、坟墓！<br/>我都胜过，<br/>若你与我同住。<br/>','',55123,8658);
INSERT INTO stanza VALUES('Z288','6','若我临终，<br/>愿你在我身边，<br/>照明幽谷，<br/>指我仰望你面；<br/>或到你来，<br/>天晓，地影尽无；<br/>无论如何，<br/>求你与我同住。<br/>','',55124,8659);
INSERT INTO stanza VALUES('Z289','1','愿你为大，哦主耶稣！<br/>信条、话语、虚仪、<br/>属人的会、属世的爱，<br/>不能与你相比。<br/>','',55125,8660);
INSERT INTO stanza VALUES('Z289','2','愿你为大，哦主耶稣！<br/>你爱征服了我；<br/>靠你十架我向己死，<br/>完全为你而活。<br/>','',55126,8661);
INSERT INTO stanza VALUES('Z289','3','愿你为大，哦主耶稣！<br/>全人被你充满，<br/>使我思想像你思想，<br/>喜欢像你喜欢。<br/>','',55127,8662);
INSERT INTO stanza VALUES('Z289','4','愿你为大，哦主耶稣！<br/>把我改变全备；<br/>从这幔子(软弱肉体)<br/>显出你的荣美。<br/>','',55128,8663);
INSERT INTO stanza VALUES('Z289','5','愿你为大，哦主耶稣！<br/>我心真是要求：<br/>作你奴隶，行你旨意，<br/>一生不再自由。<br/>','',55129,8664);
INSERT INTO stanza VALUES('Z290','1','主耶稣，<br/>我羡慕活在你面前，<br/>在早晨，在晚上，<br/>只有一世间；<br/>不让我心快乐，<br/>若我在爱慕、在感觉、<br/>或思想无你的事物。<br/>每一刻，每一天，<br/>不论何痛苦，<br/>当世上正没有<br/>甚么可鼓舞，<br/>当叹息正不禁，<br/>眼泪流滴滴，<br/>主，擦干我眼泪，<br/>平静我叹息。<br/>','',55130,8665);
INSERT INTO stanza VALUES('Z290','2','我每次如梦想<br/>人生的善美，<br/>亲爱主，我求你，<br/>必须也在内！<br/>不让我离开你<br/>去寻求快乐，<br/>不让我凭自己<br/>去单独选择！<br/>当每夜万籁静，<br/>孤单自处时，<br/>主耶稣，我求你，<br/>仍与我同止；<br/>当每晨未破晓，<br/>我仍蒙昧中，<br/>求你来低声唤，<br/>将我耳开通。<br/>','',55131,8666);
INSERT INTO stanza VALUES('Z290','3','当每次我虔读<br/>你圣洁话语，<br/>求你用你荣耀<br/>照亮每一句；<br/>让我能明看见：<br/>这宝贵救主，<br/>和祂的大救恩，<br/>无一不我属。<br/>当我正无倚靠<br/>跪到你座前，<br/>求垂听我祷告，<br/>赐够用恩典；<br/>有时候因有错，<br/>祷告你不听，<br/>别收回你同在，<br/>使我感不宁。<br/>','',55132,8667);
INSERT INTO stanza VALUES('Z290','4','当每次我想到<br/>属天的福气，<br/>让我心切羡慕<br/>早日会见你；<br/>我今日所希望<br/>只有你再来，<br/>我那日所快乐<br/>只有你同在。<br/>主，求你教训我<br/>活在你面前，<br/>在早晨，在晚上，<br/>只有一世间；<br/>不让我心快乐，<br/>若我在爱慕、<br/>在感觉、或思想<br/>无你的事物。<br/>','',55133,8668);
INSERT INTO stanza VALUES('Z291','1','救主，求你引领我，<br/>灵中引我过生活；<br/>行在生命的光中，<br/>不再挣扎或妄动。<br/>','',55134,8669);
INSERT INTO stanza VALUES('Z291','chorus','引我，引我，<br/>救主，这是我所求；<br/>借你生命的水流，<br/>引我你路来行走。<br/>','',55135,8670);
INSERT INTO stanza VALUES('Z291','2','你在我里作生命，<br/>借你活律来引领；<br/>在我身上你执政，<br/>所有黑暗变光明。<br/>','',55136,8671);
INSERT INTO stanza VALUES('Z291','3','你是释放人的灵，<br/>求你全将我规正；<br/>我的心思得更新，<br/>就能满足你圣心。<br/>','',55137,8672);
INSERT INTO stanza VALUES('Z292','1','救主，领我免迷途，<br/>温柔领我完世路；<br/>在你身边我稳固，<br/>在你爱里我居住。<br/>','',55138,8673);
INSERT INTO stanza VALUES('Z292','chorus','领我，领我，<br/>救主，领我免迷途；<br/>我的前面无把握，<br/>救主，领我完世路。<br/>','',55139,8674);
INSERT INTO stanza VALUES('Z292','2','你是我魂避难所，<br/>何怕人生起风波！<br/>有你亲近我安全，<br/>有你怜悯我无怨。<br/>','',55140,8675);
INSERT INTO stanza VALUES('Z292','3','救主，领我到尽头，<br/>直到你来的时候，<br/>我要与你永同在，<br/>同享安息到万代。<br/>','',55141,8676);
INSERT INTO stanza VALUES('Z293','1','求你拣选我道路，<br/>我主，为我拣选，<br/>我无自己的羡慕，<br/>我要你的意念；<br/>你所命定的前途，<br/>无论何等困难，<br/>我要甘心的顺服，<br/>来寻你的喜欢。<br/>','',55142,8677);
INSERT INTO stanza VALUES('Z293','chorus','求你握住我的手，<br/>你知我的软弱；<br/>否则我只能忧愁，<br/>不知如何生活。<br/>你若握住我的手，<br/>不问你是拣选<br/>何种道路和时候，<br/>我心都觉甘甜。<br/>','',55143,8678);
INSERT INTO stanza VALUES('Z293','2','不问平坦与崎岖，<br/>只要是你拣选，<br/>就是我所最心许，<br/>别的不合意愿；<br/>我是不敢自作主，<br/>你许，我也不要，<br/>求你拣选我道路，<br/>我要听你遣调。<br/>','',55144,8679);
INSERT INTO stanza VALUES('Z293','3','我的时候在你手，<br/>不论或快或慢，<br/>照你喜悦来画筹，<br/>我无自己喜欢；<br/>你若定我须忍耐<br/>许多日日年年，<br/>我就不愿早无碍，<br/>一切就早改变。<br/>','',55145,8680);
INSERT INTO stanza VALUES('Z293','4','主，我余生的小杯，<br/>求你随意倾注，<br/>或是喜乐或伤悲，<br/>求你随意作主；<br/>一切痛苦都甘甜，<br/>若知是你意思，<br/>一切享受成可厌，<br/>若非你所恩赐。<br/>','',55146,8681);
INSERT INTO stanza VALUES('Z293','5','求你为我来拣选，<br/>健康或是疾病，<br/>或是笑容或泪眼，<br/>美名或是恶名；<br/>不论事情大或小，<br/>拣选？我是不要，<br/>不要自己的感觉，<br/>只要你的荣耀。<br/>','',55147,8682);
INSERT INTO stanza VALUES('Z294','1','紧握我手，<br/>我是这样的无倚，<br/>没有扶助，<br/>一步我不敢走；<br/>紧握我手！<br/>亲爱救主，求提携，<br/>祸害、恐吓<br/>才不使我战抖。<br/>','',55148,8683);
INSERT INTO stanza VALUES('Z294','2','紧握我手！<br/>求你更紧的拉我，<br/>近你自己，<br/>我一切中一切；<br/>紧握我手！<br/>免得偶然我流落，<br/>迷失了你，<br/>我脚发软滑跌。<br/>','',55149,8684);
INSERT INTO stanza VALUES('Z294','3','紧握我手！<br/>前面道路不豫晓，<br/>因为没有你脸上的亮光；<br/>但是，当我借信<br/>瞥见你荣耀，<br/>我的喜乐立即发音成唱。<br/>','',55150,8685);
INSERT INTO stanza VALUES('Z294','4','紧握我手！<br/>当我走到你为我<br/>所经过的黑河孤单边界，<br/>属天的光才会<br/>照射到此河，<br/>其中黑水才会不像黑夜。<br/>','',55151,8686);
INSERT INTO stanza VALUES('Z295','1','只要是你道路，<br/>不论如何黑暗，<br/>不管怎样艰苦，<br/>求你为我拣选。<br/>','',55152,8687);
INSERT INTO stanza VALUES('Z295','2','平坦或是崎岖，<br/>必定都是上好；<br/>笔直或是弯曲，<br/>安息都必引到。<br/>','',55153,8688);
INSERT INTO stanza VALUES('Z295','3','不敢自作选择，<br/>即可，我也不愿；<br/>求你为我定夺，<br/>使我脚步不偏。<br/>','',55154,8689);
INSERT INTO stanza VALUES('Z295','4','以苦或是以乐，<br/>我杯由你充满；<br/>照你看为最妥，<br/>祸福为我拣选。<br/>','',55155,8690);
INSERT INTO stanza VALUES('Z295','5','为我选择友人，<br/>选择疾病、健康；<br/>为我选择责任，<br/>选择衰贫、隆昌。<br/>','',55156,8691);
INSERT INTO stanza VALUES('Z295','6','事情不论大小，<br/>不随我的爱好；<br/>你是我的引导，<br/>是我智慧、至宝。<br/>','',55157,8692);
INSERT INTO stanza VALUES('Z296','1','我愿更多认识基督，<br/>更多追踪祂的道路；<br/>更多认识祂的救赎，<br/>更多享受祂的丰富。<br/>','',55158,8693);
INSERT INTO stanza VALUES('Z296','chorus','更多认识基督，<br/>更多认识基督。<br/>更多认识祂的救赎，<br/>更多享受祂的丰富。<br/>','',55159,8694);
INSERT INTO stanza VALUES('Z296','2','更多认识复活大能，<br/>更多经历无穷生命；<br/>更多取用升天权柄，<br/>更多有分荣耀得胜。<br/>','',55160,8695);
INSERT INTO stanza VALUES('Z296','3','更多得着圣灵启示，<br/>更多知道父神意思；<br/>更多看见幔内的事，<br/>更多效法基督的死。<br/>','',55161,8696);
INSERT INTO stanza VALUES('Z296','4','更多相信主的圣言，<br/>更多倚靠祂的恩典；<br/>更多爱慕祂的显现，<br/>更多盼望祂的王权。<br/>','',55162,8697);
INSERT INTO stanza VALUES('Z297','1','主！使我更爱你，<br/>和你更亲密，<br/>为你名更热心，<br/>向你话更信，<br/>对你忧更关心，<br/>因你苦更贫，<br/>更觉得你看顾，<br/>更完全顺服。<br/>','',55163,8698);
INSERT INTO stanza VALUES('Z297','chorus','求主天天扶持我，<br/>给我力量保守我，<br/>使我一生走窄路，<br/>使主心满意足。<br/>','',55164,8699);
INSERT INTO stanza VALUES('Z297','2','主！使我更得胜，<br/>向你更忠诚，<br/>在你手更有用，<br/>对你仇更勇，<br/>受苦更为忍耐，<br/>犯罪更悲哀，<br/>更喜乐任怨劳，<br/>更完全倚靠。<br/>','',55165,8700);
INSERT INTO stanza VALUES('Z297','3','主！使我更属天，<br/>更常见你面，<br/>更爱慕你再来，<br/>更想你『同在，』<br/>更愿意处卑微，<br/>更轻看高贵，<br/>更为不顾自己，<br/>凡事更像你。<br/>','',55166,8701);
INSERT INTO stanza VALUES('Z298','1','哦主，求你长在我心，<br/>你外再无他求！<br/>使我逐日与你更亲，<br/>逐日向罪自由。<br/>','',55167,8702);
INSERT INTO stanza VALUES('Z298','chorus','愿你逐日维持的力，<br/>仍然顾我软弱，<br/>你的亮光除我阴翳，<br/>生命吞我死涸。<br/>','',55168,8703);
INSERT INTO stanza VALUES('Z298','2','当你荣光照我心头，<br/>所有恶念都消；<br/>『我是无有，<br/>你是万有，』<br/>我愿常受此教。<br/>','',55169,8704);
INSERT INTO stanza VALUES('Z298','3','你这圣洁、荣耀的主，<br/>让我更多瞻仰；<br/>无论快乐或是艰苦，<br/>我愿作你活像。<br/>','',55170,8705);
INSERT INTO stanza VALUES('Z298','4','天上喜乐，求你膏我，<br/>灵力，求你助我；<br/>但愿你的热切爱火，<br/>从我全人射过。<br/>','',55171,8706);
INSERT INTO stanza VALUES('Z298','5','可怜的己，愿其消沉，<br/>惟你作我目标，<br/>使我逐日借着你恩，<br/>更配与你相交。<br/>','',55172,8707);
INSERT INTO stanza VALUES('Z298','chorus','愿你逐日维持的力，<br/>仍然顾我软弱，<br/>你的亮光除我阴翳，<br/>生命吞我死涸。<br/>第一节的『长，』意思是生长、长大。<br/>','',55173,8708);
INSERT INTO stanza VALUES('Z299','1','天程旅客的粮食，<br/>圣徒可食之饼，<br/>每日吗哪天所赐，<br/>适合属天性情；<br/>长久渴慕享受你，<br/>饱尝你的丰富，<br/>直到地乐全灭迹，<br/>所有心愿满足。<br/>','',55174,8709);
INSERT INTO stanza VALUES('Z299','2','涌流生命的活水，<br/>流自裂开灵磐，<br/>明晶活泉何甘美，<br/>你是爱的泉源。<br/>让我白白来畅饮，<br/>消除我的干渴；<br/>你外，别水不再寻，<br/>永远将你来喝。<br/>','',55175,8710);
INSERT INTO stanza VALUES('Z299','3','吃你、喝你、享受你，<br/>我们敬拜感戴；<br/>在你话并你灵里，<br/>饱尝你的大爱。<br/>使我从你得喂养，<br/>凭你活在地上，<br/>满有长成的身量，<br/>叫你得着显彰。<br/>','',55176,8711);
INSERT INTO stanza VALUES('Z300','1','变成主的形状！<br/>这是我心愿！<br/>我今深切仰望，<br/>愿主就成全！<br/>','',55177,8712);
INSERT INTO stanza VALUES('Z300','2','变成主的形状！<br/>主就是那灵；<br/>肯让主灵通畅，<br/>此愿就完成。<br/>','',55178,8713);
INSERT INTO stanza VALUES('Z300','3','敞着我脸观瞧，<br/>瞧见主荣光；<br/>如同镜子返照，<br/>照出主形状。<br/>','',55179,8714);
INSERT INTO stanza VALUES('Z300','4','但愿再无遮蔽，<br/>常将主返照；<br/>更愿心能纯一，<br/>返照无搅扰。<br/>','',55180,8715);
INSERT INTO stanza VALUES('Z300','5','观看主的荣光，<br/>与主面对面；<br/>一直将主瞻仰，<br/>心不再他转。<br/>','',55181,8716);
INSERT INTO stanza VALUES('Z300','6','变成主的形状，<br/>乃是我目标！<br/>将主印在心上，<br/>反映主荣耀。<br/>','',55182,8717);
INSERT INTO stanza VALUES('Z300','7','变成主的形状，<br/>荣上又加荣！<br/>显出主的荣光，<br/>无穷又无终！<br/>','',55183,8718);
INSERT INTO stanza VALUES('Z301','1','哦，我要像你，<br/>可爱的救主！<br/>这是我所求，是我所慕；<br/>我欢喜丢弃一切的富足，<br/>盼望能和你形像合符。<br/>','',55184,8719);
INSERT INTO stanza VALUES('Z301','chorus','哦，我要像你！<br/>哦，我要像你！<br/>可爱的救主，像你模样；<br/>像你的甘甜，<br/>像你的贞坚，<br/>在我的衷心，刻你形像。<br/>','',55185,8720);
INSERT INTO stanza VALUES('Z301','2','哦，我要像你：<br/>那样的柔细，<br/>宽恕又怜悯、<br/>仁爱、良善，<br/>帮助孤单的，<br/>勉励灰心的，<br/>寻找犯罪人，<br/>不辞危难。<br/>','',55186,8721);
INSERT INTO stanza VALUES('Z301','3','哦，我要像你：<br/>那样的忍耐，<br/>圣洁而谦卑，于人无伤，<br/>温和的接受无理的苦待，<br/>宁可救别人，自己死亡。<br/>','',55187,8722);
INSERT INTO stanza VALUES('Z301','4','哦，我要像你！<br/>我今迫切求：<br/>我愿出代价跟随你行，<br/>将我的所是和我的所有，<br/>完全献给你，不自经营。<br/>','',55188,8723);
INSERT INTO stanza VALUES('Z301','5','哦，我要像你！<br/>正当我祈求，<br/>倒下你的爱充满我心，<br/>使我作个殿，<br/>配给你居留，<br/>使我的生命与你相印。<br/>','',55189,8724);
INSERT INTO stanza VALUES('Z302','1','主阿，何等奥秘，<br/>你灵在我灵！<br/>也是何等实际，<br/>二灵成一灵！<br/>','',55190,8725);
INSERT INTO stanza VALUES('Z302','2','我能靠灵行动，<br/>因灵而属灵；<br/>也能凭灵事奉，<br/>以灵敬拜灵。<br/>','',55191,8726);
INSERT INTO stanza VALUES('Z302','3','灵里接触相交，<br/>我灵就刚强；<br/>灵里读经、祷告，<br/>我灵就高昂。<br/>','',55192,8727);
INSERT INTO stanza VALUES('Z302','4','求你使我灵强，<br/>点活别人灵！<br/>使我灵能高昂，<br/>释放别人灵！<br/>','',55193,8728);
INSERT INTO stanza VALUES('Z302','5','使我每一出声，<br/>就能推动灵！<br/>无论有何动静，<br/>都能供应灵！<br/>','',55194,8729);
INSERT INTO stanza VALUES('Z302','6','但愿我灵一动，<br/>人灵就开启！<br/>但愿我灵一冲，<br/>人灵就提起！<br/>','',55195,8730);
INSERT INTO stanza VALUES('Z302','7','主阿，求你垂顾，<br/>多用灵来吹！<br/>人人灵都丰富，<br/>人人灵加倍！<br/>','',55196,8731);
INSERT INTO stanza VALUES('Z303','1','祂的脸面，<br/>祂的天使常看见，<br/>但不认识祂的大爱；<br/>祂的圣徒<br/>虽然认识爱无限，<br/>却未看见祂的丰采。<br/>他们不久<br/>也要看见祂脸面，<br/>认识祂的荣耀光明；<br/>但马利亚<br/>曾看见祂的泪眼，<br/>知道祂心痛的情形。<br/>知道祂心痛的情形。<br/>','',55197,8732);
INSERT INTO stanza VALUES('Z303','2','我们快要<br/>完全知道我们主，<br/>已往从未如此知道；<br/>但是今日<br/>医治伤心的摸抚，<br/>不是那日感觉得到。<br/>那日虽有<br/>无穷无尽的赞美，<br/>却无流泪迫切祷告，<br/>却无伤心痛苦<br/>所得的安慰，<br/>也无困难所生倚靠。<br/>也无困难所生倚靠。<br/>','',55198,8733);
INSERT INTO stanza VALUES('Z303','3','那日虽有<br/>无比荣耀的冠冕，<br/>但无十架可以顺从；<br/>祂为我们<br/>所受一切的磨碾，<br/>今日才能与祂交通。<br/>进入安息，<br/>就再寻不到疲倦，<br/>再无机会为祂受苦；<br/>再也不能<br/>为祂经过何试炼，<br/>再为祂舍弃何幸福。<br/>','',55199,8734);
INSERT INTO stanza VALUES('Z303','4','哎阿，为祂，<br/>机会已是何等少，<br/>所有机会快要过去，<br/>机会无多，<br/>为祂，蒙羞和受嘲，<br/>为祂，再来分心、分虑。<br/>不久就无<br/>误会、怒骂与凌辱，<br/>就无孤单、寂寞、离别；<br/>我当宝贝<br/>这些不久的祝福，<br/>我借这些与你联结。<br/>','',55200,8735);
INSERT INTO stanza VALUES('Z303','5','主，我羡慕<br/>早日看见你脸面，<br/>那是实在好得无比；<br/>但是，我也不愿<br/>免去你试炼，<br/>失去如此交通甜蜜。<br/>求你怜悯，<br/>使我充满你大爱，<br/>不顾一切为你生活；<br/>免你仆人<br/>今天急切望将来，<br/>将来又悔今天错过。<br/>将来又悔今天错过。<br/>','',55201,8736);
INSERT INTO stanza VALUES('Z304','1','从我活出你的自己，<br/>耶稣，你是我生命；<br/>对于我的所有问题，<br/>求你以你为答应。<br/>从我活出你的自己，<br/>一切事上能随意，<br/>我不过是透明用器，<br/>为着彰显你秘密。<br/>','',55202,8737);
INSERT INTO stanza VALUES('Z304','2','殿宇今已完全奉献，<br/>已除所有的不洁，<br/>但愿你的荣耀火焰，<br/>今从里面就露襭。<br/>全地现在都当肃穆，<br/>我的身体今进供，<br/>作你顺服、安静奴仆，<br/>只有被你来推动。<br/>','',55203,8738);
INSERT INTO stanza VALUES('Z304','3','所有肢体每个时刻，<br/>约束、等候你发言，<br/>准备为你前来负轭，<br/>或是不用放一边。<br/>约束，没有不安追求，<br/>没有紧张与受压，<br/>没有因受对付怨尤，<br/>没有因懊悔倒下。<br/>','',55204,8739);
INSERT INTO stanza VALUES('Z304','4','乃是柔软、安静、安息，<br/>脱离倾向与成见，<br/>让你能够自由定意，<br/>当你对我有指点。<br/>从我活出你的自己，<br/>耶稣你是我生命；<br/>对于我的所有问题，<br/>求你以你为答应。<br/>第二节的『露襭，』意思是露出所包藏之物。<br/>','',55205,8740);
INSERT INTO stanza VALUES('Z305','1','父，我知道我的一生，<br/>你已替我分好；<br/>所有必须发生变更，<br/>我不害怕看到；<br/>我求你赐长久忠诚，<br/>存心讨你欢笑。<br/>','',55206,8741);
INSERT INTO stanza VALUES('Z305','2','我求要得『有意』的爱，<br/>时常儆醒的慧，<br/>常以笑容欢迎事态，<br/>擦干不禁眼泪，<br/>心能与牠自己合拍，<br/>好来同情、安慰。<br/>','',55207,8742);
INSERT INTO stanza VALUES('Z305','3','我不要有不安意志，<br/>急忙到东到西，<br/>要求要作几件大事，<br/>或要明白秘密；<br/>我要被待如同孩子，<br/>所往都是受意。<br/>','',55208,8743);
INSERT INTO stanza VALUES('Z305','4','无论我在世界何地，<br/>是有何种景况，<br/>我与人心有个交契，<br/>我要保守发旺，<br/>我要为爱出我微力，<br/>为着事奉我王。<br/>','',55209,8744);
INSERT INTO stanza VALUES('Z305','5','我求你赐每日恩泽，<br/>使我能常受教；<br/>心能从里与外调和，<br/>当我与你契交；<br/>满意只占微小旁侧，<br/>若你能得荣耀。<br/>','',55210,8745);
INSERT INTO stanza VALUES('Z305','6','每条路上都有虚假，<br/>是你要我忍耐；<br/>每种境遇都有十架，<br/>是你引我倚赖；<br/>但心靠你若是卑下，<br/>无论那里可爱。<br/>','',55211,8746);
INSERT INTO stanza VALUES('Z305','7','如果在我幸福之中，<br/>有何尚未求祈，<br/>我是渴慕我的内衷，<br/>向你能满爱意；<br/>宁愿不多为你作工，<br/>完全使你欢喜。<br/>','',55212,8747);
INSERT INTO stanza VALUES('Z305','7','你爱所定我的选择，<br/>不是我的捆绳；<br/>我在暗中受你领帅，<br/>已识你的见证：<br/>一生充满舍己的爱，<br/>就是自由一生。<br/>','',55213,8748);
INSERT INTO stanza VALUES('Z306','1','祂为我死，我才能活；<br/>我今为祂活着，<br/>我命、我爱，我都献给<br/>那为我钉死的。<br/>','',55214,8749);
INSERT INTO stanza VALUES('Z306','chorus','哦耶稣我主，我救主！<br/>使我能专心跟从主；<br/>你怎样为我而死而活，<br/>让我照样为你死活。<br/>','',55215,8750);
INSERT INTO stanza VALUES('Z306','2','祂为我死，我才能死，<br/>脱离罪、己、俗世。<br/>哦，死何奥！<br/>哦，生何高！<br/>愿我联合倚靠！<br/>','',55216,8751);
INSERT INTO stanza VALUES('Z306','3','祂为我活，我才能活，<br/>像祂那样『无我；』<br/>求主从我显你性情，<br/>活出你的生命。<br/>','',55217,8752);
INSERT INTO stanza VALUES('Z306','4','祂为我活，我愿一生<br/>把祂分给众人；<br/>让我像主为人而活，<br/>跟随主的领率。<br/>','',55218,8753);
INSERT INTO stanza VALUES('Z307','1','主耶稣，<br/>我真羡慕能得完全，<br/>我要你时刻<br/>活在我的魂间，<br/>粉碎众偶像，<br/>驱逐所有失败，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55219,8754);
INSERT INTO stanza VALUES('Z307','chorus','比雪更白，<br/>是比雪更白，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55220,8755);
INSERT INTO stanza VALUES('Z307','2','主耶稣，<br/>不要让有『不圣』遗留，<br/>求用你宝血<br/>除去所有污垢，<br/>我为得圣洁，<br/>一切都愿割爱，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55221,8756);
INSERT INTO stanza VALUES('Z307','3','主耶稣，<br/>求从天上宝座垂怜，<br/>助我献完全的祭<br/>在你面前；<br/>我放下自己<br/>和我所有障碍，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55222,8757);
INSERT INTO stanza VALUES('Z307','4','主耶稣，<br/>为此，我今谦卑祈求，<br/>在十字架下，<br/>我已等候很久，<br/>你所流宝血，<br/>我今完全信赖，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55223,8758);
INSERT INTO stanza VALUES('Z307','5','主耶稣，<br/>你已看见我在求寻，<br/>求你今就来，<br/>赐给一个清心；<br/>凡向你求的，<br/>你永不会不睬，<br/>求主洗净我，<br/>使我比雪更白。<br/>','',55224,8759);
INSERT INTO stanza VALUES('Z308','1','世上景色我已一阅，<br/>愿你使我目复盲；<br/>不然，我怕祂的喜悦，<br/>不如从前的显彰。<br/>','',55225,8760);
INSERT INTO stanza VALUES('Z308','chorus','世上景色我已一阅，<br/>愿你使我目复盲；<br/>不然，我怕祂的喜悦，<br/>不如从前的显彰。<br/>','',55226,8761);
INSERT INTO stanza VALUES('Z308','2','晨曦、晚霞、<br/>星光、云锦，<br/>留等乐园再接触；<br/>今天在此有祂怜悯，<br/>即使盲目亦满足。<br/>','',55227,8762);
INSERT INTO stanza VALUES('Z308','3','我今不望离开苦刺，<br/>甘心软弱望加恩；<br/>座上荣耀、幔内启示，<br/>依然照亮无眼人。<br/>','',55228,8763);
INSERT INTO stanza VALUES('Z308','4','黑夜沉沉何等美丽，<br/>摸索用信不用眼；<br/>祂受人欺，祂被人讥，<br/>我见祂的发光脸。<br/>','',55229,8764);
INSERT INTO stanza VALUES('Z308','5','超过月亮，超过日头，<br/>超过星河并云霄，<br/>乃是那戴荆冕圣首<br/>所显无比的荣耀。<br/>','',55230,8765);
INSERT INTO stanza VALUES('Z308','chorus','世上景色我已一阅，<br/>愿你使我目复盲；<br/>不然，我怕祂的喜悦，<br/>不如从前的显彰。<br/>这首诗歌是一位姊妹写的。<br/>她原来双目失明，当另一位姊妹为<br/>她按手祷告之后，她的眼睛得了医治，<br/>她就写了这首诗歌。<br/>第一节『你』就是指为她按手的姊妹。<br/>','',55231,8766);
INSERT INTO stanza VALUES('Z309','1','求主启示主自己，<br/>使我认识我肉体；<br/>愿主恩典大作工，<br/>使我俯伏灰尘中。<br/>逐时逐日我求胜，<br/>一生一世终无能，<br/>善虽愿意作不来，<br/>恶虽恨恶脱不开。<br/>','',55232,8767);
INSERT INTO stanza VALUES('Z309','2','里面意思虽要神，<br/>外头行为总可恨；<br/>爱莫能助将奈何！<br/>事与愿违真束缚！<br/>神律才显罪便在，<br/>善念一动恶也来；<br/>肢体的律掳了我，<br/>挣扎奋斗终难脱。<br/>','',55233,8768);
INSERT INTO stanza VALUES('Z309','3','多次跌倒多次起，<br/>时而立志时而遗，<br/>要求得胜反退溃，<br/>愿意成圣倒污秽。<br/>我实已是卖给罪，<br/>我真已经无能为，<br/>我的肉体没良善，<br/>我的自己乃黑暗。<br/>','',55234,8769);
INSERT INTO stanza VALUES('Z309','4','我今已略识自己，<br/>实在没有一点力，<br/>我的性情真古怪，<br/>我的生命全败坏；<br/>自己诡诈不可靠，<br/>肉体软弱不能保，<br/>我今所有的盼望，<br/>都在耶稣我的王。<br/>','',55235,8770);
INSERT INTO stanza VALUES('Z309','5','求主十架治死我，<br/>使我靠主而生活；<br/>求主圣灵充满我，<br/>使我凭主而工作；<br/>愿主的死在我身，<br/>天天作工比前深，<br/>让我自己全消灭，<br/>让主生命来提挈。<br/>','',55236,8771);
INSERT INTO stanza VALUES('Z309','6','我的光景真是苦，<br/>谁能使我不为奴，<br/>救我脱离取死身，<br/>使我能够常得胜？<br/>耶稣为我流宝血，<br/>基督作我的圣洁，<br/>我今接祂为生命，<br/>我今服祂的号令。<br/>','',55237,8772);
INSERT INTO stanza VALUES('Z309','7','完全圣洁无恶意！<br/>完全顺服无自己-<br/>不再觉羞到父前！<br/>不再难过见主面！<br/>哦，这生命何等高！<br/>一信主恩即临到！<br/>感谢主今听呼求，<br/>使我完全得自由。<br/>','',55238,8773);
INSERT INTO stanza VALUES('Z310','1','一生聪明未遇敌手，<br/>以扫、以撒均成往事；<br/>我今到了生死关头，<br/>虽然绝望仍然自恃；<br/>束手就缚我不能受，<br/>我要用力，我要用谋。<br/>','',55239,8774);
INSERT INTO stanza VALUES('Z310','2','彷佛我见有人偷营，<br/>我心害怕但我倔强：<br/>惟恐我的末日已定，<br/>用尽全身所有力量；<br/>祂来摔跤，我要招架，<br/>未到死地还要挣扎。<br/>','',55240,8775);
INSERT INTO stanza VALUES('Z310','3','奇哉！我用已往经验，<br/>摔跤一夜祂仍不倒；<br/>我的力量眼见将减，<br/>但是祂像无意回报；<br/>奇哉！又像无法脱身，<br/>我的胆量又复加甚。<br/>','',55241,8776);
INSERT INTO stanza VALUES('Z310','4','如此对手从未得会，<br/>祂虽告我祂的名字，<br/>我仍不知所战为谁，<br/>只知祂有很大赏赐；<br/>我就迫祂向我赐福，<br/>迫祂向我赐福、屈服。<br/>','',55242,8777);
INSERT INTO stanza VALUES('Z310','5','天已黎明难分胜负：<br/>好像无法、好像无能，<br/>祂就被迫向我赐福，<br/>并且称许，说我得胜，<br/>说我新名是以色列；<br/>当我起来，我腿已瘸！<br/>','',55243,8778);
INSERT INTO stanza VALUES('Z310','6','有了微光进我暗心，<br/>开始照亮使我领会：<br/>若我有能，为何扭筋？<br/>若我得胜，为何瘸腿？<br/>是祂得胜留下记号，<br/>使我愚昧受了警告。<br/>','',55244,8779);
INSERT INTO stanza VALUES('Z310','7','瞬息之间，光满我心，<br/>如同洪流冲破堤防，<br/>我就看见荣耀无尽，<br/>迫我敬拜、迫我隐藏；<br/>我才知道我的大罪、<br/>我的不轨、我的污秽。<br/>','',55245,8780);
INSERT INTO stanza VALUES('Z310','7','哎阿，想到：我曾胜过<br/>造物的主、全能的神！<br/>荒谬之极，该当有祸！<br/>该死之至，该死无恩！<br/>我这双手竟然背叛，<br/>强迫主神不得动弹！<br/>','',55246,8781);
INSERT INTO stanza VALUES('Z310','9','你是何等荣耀的神，<br/>万军之主何等显赫；<br/>我一认识你是谁人，<br/>并一看见你是如何，<br/>我要长号，我要流泪，<br/>我要懊悔，我要下跪。<br/>','',55247,8782);
INSERT INTO stanza VALUES('Z310','10','怎么可能！怎么可以！<br/>见神的面，与神相持！<br/>我恨不得有缝入地，<br/>才可稍微掩我羞耻：<br/>为何我不在此以先，<br/>即已毁灭，离世长眠？<br/>','',55248,8783);
INSERT INTO stanza VALUES('Z310','11','我恨自己过于昏沉，<br/>因为骄傲瞎了眼睛；<br/>想到我是得胜了神，<br/>我就不禁胆战心惊：<br/>浑身无力，何只一腿？<br/>百节俱脱，全人崩溃！<br/>','',55249,8784);
INSERT INTO stanza VALUES('Z310','12','我今回顾我的一生，<br/>全是充满败坏事体：<br/>保全自己，将神牺牲，<br/>愚昧的心只知快意，<br/>我还以为祝福在于<br/>强神来听我的所欲。<br/>','',55250,8785);
INSERT INTO stanza VALUES('Z310','13','我有欲望天来顺服，<br/>我出主张天来安排，<br/>我有喜好望神让步，<br/>我有工作望神领帅，<br/>我若急切天须赶快，<br/>那有一次神不失败！<br/>','',55251,8786);
INSERT INTO stanza VALUES('Z310','14','世界竟有如此邪恶、<br/>骄傲、顽固、诡诈的人！<br/>主，你知道我是雅各，<br/>充满败坏，充满可恨；<br/>我无可望，只望怜悯，<br/>你来怜悯败坏这心。<br/>','',55252,8787);
INSERT INTO stanza VALUES('Z310','15','我今已蒙怜悯一摸，<br/>举步蹒跚，恩典遗迹；<br/>我若忘记，新的腿窝<br/>要使我感何等无倚；<br/>你虽许我作以色列，<br/>但是雅各永远病瘸。<br/>','',55253,8788);
INSERT INTO stanza VALUES('Z310','16','主，我服了，是你得胜：<br/>因你失败我求失败，<br/>因我得胜我来投诚，<br/>你的软弱领我下拜；<br/>我愿一生战战兢兢，<br/>行你旨意，荣耀你名。<br/>','',55254,8789);
INSERT INTO stanza VALUES('Z311','1','主阿，求你将我看，<br/>赐我甜美的简单；<br/>灵中贫穷，心卑微，<br/>寻求犹如向日葵。<br/>','',55255,8790);
INSERT INTO stanza VALUES('Z311','2','脱离作威的自己，<br/>脱离财奴之所倚，<br/>脱离显扬的兴趣，<br/>脱离受夸的私欲。<br/>','',55256,8791);
INSERT INTO stanza VALUES('Z311','3','所有供我骄傲的，<br/>求你为我全抛弃；<br/>使我意志服你的，<br/>谦卑顺服到死地。<br/>','',55257,8792);
INSERT INTO stanza VALUES('Z311','4','使我回转像婴孩，<br/>将我智、力、全毁坏；<br/>只在你的光中行，<br/>只靠你的能力动。<br/>','',55258,8793);
INSERT INTO stanza VALUES('Z311','5','倚在你爱的胸膛，<br/>好像断奶的仰望；<br/>感到神赐的平安，<br/>充满在我全人间。<br/>','',55259,8794);
INSERT INTO stanza VALUES('Z311','6','让我活在这姿态，<br/>天天满出赞美来，<br/>如此到死也不变，<br/>但我等候你显现。<br/>','',55260,8795);
INSERT INTO stanza VALUES('Z312','1','恩主，你是我的安息，<br/>深愿我能全享；<br/>停下自己所有活动，<br/>完全将你饱尝。<br/>','',55261,8796);
INSERT INTO stanza VALUES('Z312','2','哦，这诡诈、残酷自己，<br/>总是挣扎努力，<br/>将你与我的灵隔开，<br/>使我不得安息。<br/>','',55262,8797);
INSERT INTO stanza VALUES('Z312','3','『己』取许多狡猾形状，<br/>好像都是必要，<br/>给我觉得安息于你，<br/>并不一定可靠。<br/>','',55263,8798);
INSERT INTO stanza VALUES('Z312','4','我今寻求神圣安息，<br/>完全脱离自己；<br/>惟独让你作王掌权，<br/>里外全都管理。<br/>','',55264,8799);
INSERT INTO stanza VALUES('Z312','5','我今躺卧在你手下，<br/>求你着手工作；<br/>愿你恩典使我不再<br/>凭自己活着。<br/>','',55265,8800);
INSERT INTO stanza VALUES('Z312','6','恩主，作工直到这己<br/>完全被你破碎，<br/>我能完全有你形像，<br/>显出你的光辉。<br/>','',55266,8801);
INSERT INTO stanza VALUES('Z313','1','求主倒空我脱自己，<br/>我心满诡诈；<br/>这个重大圣洁成绩，<br/>只你有办法。<br/>','',55267,8802);
INSERT INTO stanza VALUES('Z313','chorus','求主倒空我脱自己，<br/>里面无良善；<br/>我的一生全是受欺，<br/>骄傲因黑暗；<br/>求主倒空我脱自己，<br/>里面真黑暗。<br/>','',55268,8803);
INSERT INTO stanza VALUES('Z313','2','求你听我向你呼祈，<br/>罪过何难除！<br/>自己越看越不满意，<br/>何况你圣目？<br/>','',55269,8804);
INSERT INTO stanza VALUES('Z313','3','我的不安是为甚么，<br/>求你来揭露；<br/>良心时常控告不默，<br/>我注重何垢？<br/>','',55270,8805);
INSERT INTO stanza VALUES('Z313','4','你我之间有重幔子，<br/>交通常间断；<br/>到底是在那里有失，<br/>信心不坦然？<br/>','',55271,8806);
INSERT INTO stanza VALUES('Z314','1','有一仇敌，其力潜伏，<br/>信徒无不惧怕，<br/>奸狡远超生来之罪，<br/>与心更为融洽。<br/>就是那个倔强的己，<br/>那个任性的我；<br/>这个自己必须钉死，<br/>在我主才能活。<br/>','',55272,8807);
INSERT INTO stanza VALUES('Z314','2','在我老旧天性里面，<br/>己是强而有力：<br/>自信、自爱、<br/>自夸、自耀，<br/>全都随着己意。<br/>己的各面必须拒绝，<br/>必须置于死地，<br/>我才能进灵中迦南，<br/>得享主作安息。<br/>','',55273,8808);
INSERT INTO stanza VALUES('Z314','3','那篡夺你宝座的己，<br/>主阿，救我脱离！<br/>愿『我』失去在你里面，<br/>永远不得复辟。<br/>哦主，使我脱离自信，<br/>脱离自满、自足；<br/>完全以你作我能力，<br/>并作我的住处。<br/>','',55274,8809);
INSERT INTO stanza VALUES('Z314','4','救我脱离己的寻求，<br/>不再为着自己；<br/>使我总是躺在祭坛，<br/>献上作你活祭。<br/>脱离骄傲、夸耀、显扬，<br/>脱离虚荣、美誉，<br/>只以基督为我夸耀，<br/>惟独将祂高举。<br/>','',55275,8810);
INSERT INTO stanza VALUES('Z314','5','求主向我猛烈吹气，<br/>烧杀我的自己；<br/>所有己的各方各面，<br/>永远不再复起。<br/>当你荣光充满帐幕，<br/>摩西也难站立；<br/>愿你荣耀将我充满，<br/>永远杀死这己。<br/>','',55276,8811);
INSERT INTO stanza VALUES('Z315','1','嘴唇不洁、心意不洁，<br/>都是失败、都是污秽；<br/>前所希望今已销灭，<br/>主，你是否仍有恩惠？<br/>','',55277,8812);
INSERT INTO stanza VALUES('Z315','2','圣洁里面仍有行为，<br/>谦卑时候仍凭自己；<br/>连我流泪为罪懊悔，<br/>都需你血把牠洗涤。<br/>','',55278,8813);
INSERT INTO stanza VALUES('Z315','3','最好存心仍存自己，<br/>最大舍己仍有动机，<br/>我心就是我的仇敌，<br/>主，我希望可否在你？<br/>','',55279,8814);
INSERT INTO stanza VALUES('Z315','4','事奉神中，有己意思，<br/>爱别人中，有己兴趣；<br/>我不能动，我不敢止，<br/>事事处处有己寄寓。<br/>','',55280,8815);
INSERT INTO stanza VALUES('Z315','5','我的所有难脱旧造，<br/>只要一动就有自己；<br/>何等羡慕你的荣耀<br/>完全充满蒙福心地。<br/>','',55281,8816);
INSERT INTO stanza VALUES('Z315','6','不敢祈求、不敢应许，<br/>主，我只能向你注视；<br/>可否差遣你的话语，<br/>将你荣耀向我启示。<br/>','',55282,8817);
INSERT INTO stanza VALUES('Z316','1','当我蒙恩能够施恩，<br/>可怜！我竟自己知道！<br/>我是如何超越本分，<br/>自己觉得、自己记牢！<br/>我想我是活在神前，<br/>但我暗许自己敬虔！<br/>','',55283,8818);
INSERT INTO stanza VALUES('Z316','2','我的一生充满试炼，<br/>大至不是常人可忍；<br/>人虽不知我的苦艰，<br/>我却知道自己坚韧；<br/>我想我是丢弃自己，<br/>但我不忘自己经历！<br/>','',55284,8819);
INSERT INTO stanza VALUES('Z316','3','我知我是满受恩惠，<br/>已至地上无人似我！<br/>在我身上，在我心内，<br/>我能寻出神的工作！<br/>神的工作在我身上，<br/>我全知道如何欣赏！<br/>','',55285,8820);
INSERT INTO stanza VALUES('Z316','4','我知我的所有登造，<br/>我知我的一切善义，<br/>不知不觉我觉自豪，<br/>中心从神移到自己；<br/>我的手中隔夜吗哪，<br/>已变臭坏，已被蹧蹋。<br/>','',55286,8821);
INSERT INTO stanza VALUES('Z316','5','当有朋友向我慰问，<br/>向我苦情表示同情，<br/>我的骄傲不再隐闷，<br/>我的忍耐立即空罄；<br/>我就失败如同常人，<br/>咒诅生日显出根本。<br/>','',55287,8822);
INSERT INTO stanza VALUES('Z316','6','神阿，我是风闻有你，<br/>讲你论你，我是都能；<br/>但是我的败坏自己，<br/>从未因你有何变更；<br/>我用你赐固我骄傲，<br/>我因你恩加我自高。<br/>','',55288,8823);
INSERT INTO stanza VALUES('Z316','7','但我现今亲眼见你，<br/>你的圣洁显我污秽，<br/>你的亮光使我倾圮，<br/>你的荣耀使我痛悔，<br/>使我痛悔我怎能以<br/>对我自己如此着迷？<br/>','',55289,8824);
INSERT INTO stanza VALUES('Z316','7','何等惭愧，何等惭愧，<br/>将你恩典装饰自己，<br/>高抬自己用你作为，<br/>无一动机不是可鄙；<br/>我的失败不可收拾，<br/>我的得胜更为羞耻。<br/>','',55290,8825);
INSERT INTO stanza VALUES('Z316','9','何等羞耻我能骄傲！<br/>何等瞎眼我能愚昧！<br/>污秽竟会以为洁好，<br/>肉体竟会以为佳美；<br/>我是何等无知自义！<br/>我偷多少荣耀归己！<br/>','',55291,8826);
INSERT INTO stanza VALUES('Z316','10','你早知我何等败坏，<br/>但我竟然一无所知，<br/>竟然以为自己可赖，<br/>岂知乃是十分可耻；<br/>主阿，可否求你救我，<br/>今天为我开此捆锁。<br/>','',55292,8827);
INSERT INTO stanza VALUES('Z316','11','主阿，我心是在希望<br/>能有尘土给我躺卧，<br/>能有炉灰撒我身上，<br/>让我懊悔我的堕落；<br/>我是羞耻，羞耻无尽，<br/>我有如此败坏的心。<br/>','',55293,8828);
INSERT INTO stanza VALUES('Z316','12','我的言语何等不准，<br/>我的生命何等肤浅，<br/>我的存心无不浊溷，<br/>我的一切无不可厌；<br/>我今恨恶我的自己，<br/>主阿，我的希望在你。<br/>第七节的『倾圮』意思是毁坏。<br/>第十二节的『浊溷』意思是污秽不洁。<br/>','',55294,8829);
INSERT INTO stanza VALUES('Z317','1','从那求你将我遮蔽<br/>免去击你风浪之祈，<br/>从那怕有大志之惧，<br/>从那不敢上进之虚，<br/>从这自娇的己与性，<br/>释放你这从军小兵！<br/>','',55295,8830);
INSERT INTO stanza VALUES('Z317','2','从那避难就易之爱，<br/>从那使人怯懦之态，<br/>（这些不能使灵刚强，<br/>也都未钉十字架上，）<br/>从那遮蔽十架事物，<br/>神的羔羊，将我救出。<br/>','',55296,8831);
INSERT INTO stanza VALUES('Z317','3','赐我爱心带我向前，<br/>赐我信心永不丧胆，<br/>赐我盼望永不受挫，<br/>赐我热情焚烧如火，<br/>使我不像沉海沙土，<br/>却能上腾冲出云雾。<br/>','',55297,8832);
INSERT INTO stanza VALUES('Z318','1','我以信心仰望<br/>你在十字架上，<br/>我的救主！<br/>求你听我祷告，<br/>将我罪过宽饶，<br/>使我从今到老，<br/>全属救主。<br/>','',55298,8833);
INSERT INTO stanza VALUES('Z318','2','主，赐能力恩惠，<br/>在这软弱心内，<br/>热情鼓舞！<br/>你既为我流血，<br/>我要爱你深切、<br/>真挚、长久、纯洁，<br/>如火如荼。<br/>','',55299,8834);
INSERT INTO stanza VALUES('Z318','3','我今行走世路，<br/>不时遇见忧苦；<br/>求你引领！<br/>擦干我的眼泪，<br/>保守我不懊悔，<br/>拯救我不犯罪，<br/>而随你行。<br/>','',55300,8835);
INSERT INTO stanza VALUES('Z318','4','人生短梦一过，<br/>死河要起寒波，<br/>将我淹没；<br/>那时求主恩惠，<br/>除我疑惑、惊畏，<br/>赐我盼望、安慰，<br/>安然度过。<br/>','',55301,8836);
INSERT INTO stanza VALUES('Z319','1','我无能力，我的主，<br/>无法孤独、孤独的站立；<br/>我的软弱成祝福，<br/>如果完全、完全倚靠你。<br/>','',55302,8837);
INSERT INTO stanza VALUES('Z319','chorus','每一点，每一天，<br/>我是一样需恩典，<br/>我仍一样是无倚，<br/>求你更多、更多显自己。<br/>','',55303,8838);
INSERT INTO stanza VALUES('Z319','2','我的路途真孤苦，<br/>时常疲倦、疲倦不唱诗；<br/>我不认识我路途，<br/>你能使我、使我不迷失。<br/>','',55304,8839);
INSERT INTO stanza VALUES('Z319','3','我的感觉常改变，<br/>一切可厌、可厌无价值；<br/>当我眼睛看不见，<br/>正是我主、我主最近时。<br/>','',55305,8840);
INSERT INTO stanza VALUES('Z319','4','我是孤单，我的主，<br/>不易喜乐、喜乐并忍耐；<br/>若无甘甜的眷顾，<br/>和你秘密、秘密的同在。<br/>','',55306,8841);
INSERT INTO stanza VALUES('Z319','5','时日飞逝河水高，<br/>不久我要、我要横度过；<br/>四围冷静我独祷，<br/>求你记念、记念我软弱。<br/>','',55307,8842);
INSERT INTO stanza VALUES('Z320','1','哦神，一棵没有祝福、<br/>枯干而无安息的树，<br/>一个无用的障碍物，<br/>在你工场我被显出。<br/>但我求主：<br/>『勿将我废弃，<br/>要用你手将我来拿起。<br/>','',55308,8843);
INSERT INTO stanza VALUES('Z320','2','好像妇取未劈之麻，<br/>塑者取未成形之蜡，<br/>铁匠取那粗生之铁，<br/>作成用具，蒙人喜悦；<br/>照样，你手要将我拿起，<br/>勿让你爱将我来废弃。』<br/>','',55309,8844);
INSERT INTO stanza VALUES('Z320','3','顽固意志，如石未碎，<br/>虽含金质难显宝贵；<br/>天然之心，无用废物，<br/>像大理石尚未刻出；<br/>因此求主：<br/>『不要废弃我，<br/>要在你手将我来攻破。<br/>','',55310,8845);
INSERT INTO stanza VALUES('Z320','4','好像炸药攻破坚石，<br/>好像铁锤打碎石子，<br/>好像磨石压碎麦子，<br/>也像干果破壳供食；<br/>照样，用你圣手破碎我，<br/>永远勿让你爱废弃我。』<br/>','',55311,8846);
INSERT INTO stanza VALUES('Z320','5','虽已破碎，仍不中用，<br/>碎渣还须放到炉中；<br/>虽已压碎，我仍不能<br/>将那将亡群众供应；<br/>因此求主：<br/>『不要废弃我，<br/>为你事工要将我制作。<br/>','',55312,8847);
INSERT INTO stanza VALUES('Z320','6','好像金块经过模制，<br/>就成各种有用样式；<br/>也像麦粉经过泡制，<br/>水调火烤，可供人食；<br/>照样用火将我来制作，<br/>永远勿让你爱废弃我。』<br/>','',55313,8848);
INSERT INTO stanza VALUES('Z321','1','你这神的隐藏的爱！<br/>长阔高深无人知悉，<br/>远远我见你的光彩，<br/>我就叹息望得安息，<br/>我心痛苦，不能安息，<br/>除非我心安息于你。<br/>','',55314,8849);
INSERT INTO stanza VALUES('Z321','2','你的声音，仍然隐招<br/>我来负你甜美的轭；<br/>我虽几乎前来应召，<br/>但是惧怕前途阻隔；<br/>我志虽定，我情却离，<br/>我欲向你，反而背你。<br/>','',55315,8850);
INSERT INTO stanza VALUES('Z321','3','全是恩典！使你吸引<br/>我心向你追求安息；<br/>我虽追求，不能亲近，<br/>流荡的我无所凭倚；<br/>哦，要何时不再流荡，<br/>所有脚踪向你而往？<br/>','',55316,8851);
INSERT INTO stanza VALUES('Z321','4','日下有无甚么东西，<br/>与你相争来分我心？<br/>呀，我求你把牠割弃，<br/>让你作王无人与竞；<br/>我心才会不再拘泥，<br/>当牠借你得了安息。<br/>','',55317,8852);
INSERT INTO stanza VALUES('Z321','5','哦，我求你埋藏这己，<br/>使主(非我)从我而活！<br/>恶欲邪情钉死绝迹，<br/>不私留一宝贝罪恶；<br/>除你之外，在凡事上，<br/>使我无求，使我无望！<br/>','',55318,8853);
INSERT INTO stanza VALUES('Z321','6','哦主，给我无上之助，<br/>救我脱离无用之虑；<br/>赶出己意离我心府，<br/>离我全人隐密之域；<br/>使我作个顺命的人，<br/>不断称颂，时常感恩。<br/>','',55319,8854);
INSERT INTO stanza VALUES('Z321','7','求你使我时刻离地，<br/>谦卑等候听你吩咐；<br/>求你对我时常题起：<br/>『我是你爱、你命、<br/>你主；』<br/>来听你声，来觉你力，<br/>来尝你爱，是我所期。<br/>','',55320,8855);
INSERT INTO stanza VALUES('Z322','1','求主把我捆绑，<br/>我才得着释放；<br/>愿主迫我向主缴械，<br/>我才得胜奏捷；<br/>当我倚靠自己，<br/>我就失败危亟；<br/>当主膀臂将我监禁，<br/>我手就更有劲。<br/>','',55321,8856);
INSERT INTO stanza VALUES('Z322','2','我心未交主时，<br/>真是软弱愚痴，<br/>自己所愿自己不行，<br/>万事漂流无定；<br/>主若未加锁炼，<br/>就难自由进前，<br/>求主慈爱将牠奴隶，<br/>牠才会得能力。<br/>','',55322,8857);
INSERT INTO stanza VALUES('Z322','3','我的生命未死，<br/>终身总是丧失：<br/>胜少败多，实无能力，<br/>时为肉体叹息。<br/>我若没有死过，<br/>我就难以活着，<br/>求主使我脱离自己，<br/>才会完全得你。<br/>','',55323,8858);
INSERT INTO stanza VALUES('Z322','4','我今认识了你，<br/>也略知道自己，<br/>所以今后真不愿意<br/>再借天然能力。<br/>求主永远的灵，<br/>使我生命全钉，<br/>使我治死肉体行为，<br/>主兴盛，我衰微。<br/>','',55324,8859);
INSERT INTO stanza VALUES('Z323','1','愿光今天照亮，主，<br/>在我最黑路上，主，<br/>我求你的大光，主，<br/>照进我的心内。<br/>','',55325,8860);
INSERT INTO stanza VALUES('Z323','2','光来明显一切，主，<br/>光来除去自借，主，<br/>光来，当光正缺，主，<br/>赐你自己的光。<br/>','',55326,8861);
INSERT INTO stanza VALUES('Z323','3','甚么我都看不见，<br/>撒但正在施欺骗，<br/>求你对准你光线<br/>在我身上，我主！<br/>','',55327,8862);
INSERT INTO stanza VALUES('Z323','4','光照我的生命，主，<br/>使得自知之明，主，<br/>没有丝毫黑影，主，<br/>光照使知软弱。<br/>','',55328,8863);
INSERT INTO stanza VALUES('Z323','5','集中我心对你，主，<br/>使牠自由无羁，主，<br/>照牠使知你意，主，<br/>将你的光，照我！<br/>','',55329,8864);
INSERT INTO stanza VALUES('Z323','6','使我永远能行动<br/>在你无影亮光中，<br/>不离同在的交通，<br/>认识光的拆毁。<br/>','',55330,8865);
INSERT INTO stanza VALUES('Z324','1','除去我的遮蔽，<br/>使我得见亮光！<br/>任何不再受欺，<br/>一切认识真像。<br/>','',55331,8866);
INSERT INTO stanza VALUES('Z324','chorus','主阿，愿你这真光，<br/>你这生命之光，<br/>现在就肯来照亮，<br/>使我一切明朗。<br/>','',55332,8867);
INSERT INTO stanza VALUES('Z324','2','对于我的自己，<br/>我真不够认识；<br/>因受骄傲所欺，<br/>常是自满、自是。<br/>','',55333,8868);
INSERT INTO stanza VALUES('Z324','3','对于你的自己，<br/>我更缺少认识；<br/>所知多是道理，<br/>缺少真实启示。<br/>','',55334,8869);
INSERT INTO stanza VALUES('Z324','4','对于你的生命，<br/>我也缺乏认识；<br/>肉体或是圣灵，<br/>常是以彼为此。<br/>','',55335,8870);
INSERT INTO stanza VALUES('Z324','5','对于你的道路，<br/>我也常是迷糊；<br/>因着偏于单独，<br/>就难认识正路。<br/>','',55336,8871);
INSERT INTO stanza VALUES('Z324','6','对于你的旨意，<br/>我也不够认识；<br/>多是己意充替，<br/>常是用脚踢刺。<br/>','',55337,8872);
INSERT INTO stanza VALUES('Z324','7','对于你的召会，<br/>我更需要启示；<br/>使我知所向背，<br/>以你智慧为是。<br/>','',55338,8873);
INSERT INTO stanza VALUES('Z324','7','真愿脱去遮蔽，<br/>各方都蒙光照；<br/>任何不再受欺，<br/>一切不再骄傲。<br/>','',55339,8874);
INSERT INTO stanza VALUES('Z325','1','当我凭着自己思想，<br/>我觉自己很是刚强，<br/>不知自己却是怎样<br/>没有力量。<br/>','',55340,8875);
INSERT INTO stanza VALUES('Z325','2','当我生活世人中间，<br/>我就不觉自己亏欠，<br/>只觉自己如何奋勉，<br/>如何上前。<br/>','',55341,8876);
INSERT INTO stanza VALUES('Z325','3','当我住在黑暗里面，<br/>我就不知自己肤浅，<br/>以为自己何等无限，<br/>不必虚谦。<br/>','',55342,8877);
INSERT INTO stanza VALUES('Z325','4','当我来到你的面前，<br/>亮光刺破遮蔽幕帘，<br/>我就看见前所未见，<br/>完全露现。<br/>','',55343,8878);
INSERT INTO stanza VALUES('Z325','5','在你面前我只萎缩，<br/>一切萎缩、一切消没，<br/>所有骄傲都变软弱，<br/>都变赤裸。<br/>','',55344,8879);
INSERT INTO stanza VALUES('Z325','6','没有可骄，没有可傲，<br/>没有可倚，没有可靠，<br/>只有自惭，只有自懊，<br/>能否祷告？<br/>','',55345,8880);
INSERT INTO stanza VALUES('Z325','7','幸有你血免我定罪，<br/>你的生命免我销毁，<br/>但我真是何等污秽、<br/>何等惭愧。<br/>','',55346,8881);
INSERT INTO stanza VALUES('Z325','7','所有骄傲都是愚昧，<br/>看见实在何必谦卑，<br/>所有自恃都是因为<br/>心中墨黑。<br/>','',55347,8882);
INSERT INTO stanza VALUES('Z325','9','静我也错，动我也错，<br/>不说不安，说又太过，<br/>都是失败、都是软弱、<br/>都是不妥。<br/>','',55348,8883);
INSERT INTO stanza VALUES('Z325','10','我要祷告，没有信心；<br/>我要倚靠，如何求寻？<br/>不知如何方能重新…<br/>主阿，怜悯！<br/>','',55349,8884);
INSERT INTO stanza VALUES('Z326','1','求主光照、光照我，<br/>阿们！<br/>显明、显明我罪过，<br/>阿利路亚！<br/>用血洗濯，用血洗濯，<br/>使我污秽全消没，<br/>阿们！<br/>','',55350,8885);
INSERT INTO stanza VALUES('Z326','2','求主释放、释放我，<br/>阿们！<br/>断开、断开我捆索，<br/>阿利路亚！<br/>败坏鬼魔，败坏鬼魔，<br/>使我自由而超脱，<br/>阿们！<br/>','',55351,8886);
INSERT INTO stanza VALUES('Z326','3','求主复兴、复兴我，<br/>阿们！<br/>消除、消除我软弱，<br/>阿利路亚！<br/>挑旺爱火，挑旺爱火，<br/>使我完全为主活，<br/>阿们！<br/>','',55352,8887);
INSERT INTO stanza VALUES('Z327','1','求主洁净我的灵，<br/>求主洁净我的灵，<br/>求主洁净我的灵，<br/>污秽除净；<br/>洁净我灵，污秽除净，<br/>完全除净。<br/>','',55353,8888);
INSERT INTO stanza VALUES('Z327','2','使我倒空我器皿，<br/>使我倒空我器皿，<br/>使我倒空我器皿，<br/>罪恶认清；<br/>倒空器皿，罪恶认清，<br/>彻底认清。<br/>','',55354,8889);
INSERT INTO stanza VALUES('Z327','3','求主充满我的灵，<br/>求主充满我的灵，<br/>求主充满我的灵，<br/>使我复兴；<br/>充满我灵，使我复兴，<br/>全人复兴。<br/>','',55355,8890);
INSERT INTO stanza VALUES('Z328','1','主，你荣面是我所羡，<br/>开启我眼使我看见；<br/>愿你荣光照我眼前，<br/>消除我的一切黑暗。<br/>恩主，我今寻求你面，<br/>愿你不再向我隐瞒；<br/>开启我眼，使我看见<br/>你的荣面！<br/>','',55356,8891);
INSERT INTO stanza VALUES('Z328','2','主，你慈声是我所羡，<br/>开启我耳使我听见；<br/>愿你声音绕我耳边，<br/>消除恶者一切谎言。<br/>恩主，我今寻求你面，<br/>愿你不再向我隐瞒；<br/>开启我耳，使我听见<br/>你的圣言！<br/>','',55357,8892);
INSERT INTO stanza VALUES('Z328','3','主，你自己是我所羡，<br/>开启我心使我充满；<br/>愿你丰满溢我心间，<br/>使我失去在你里面。<br/>恩主，我今寻求你面，<br/>愿你不再向我隐瞒；<br/>开启我心，使我充满<br/>你的恩典！<br/>','',55358,8893);
INSERT INTO stanza VALUES('Z329','1','有人已离主，别行他途，<br/>有人已溜出羊群保护，<br/>有人已动心贪爱世俗，<br/>主，是我否？<br/>主，是我否？<br/>','',55359,8894);
INSERT INTO stanza VALUES('Z329','chorus','主，是我否？<br/>此言犹如利刃刺入我心，<br/>刺入何等的深！<br/>若有一人要失去主的分，<br/>主，是我否？<br/>主，是我否？<br/>','',55360,8895);
INSERT INTO stanza VALUES('Z329','2','有人竟把主撇在背后，<br/>有人竟随从恶人计谋，<br/>有人竟作到圣灵担忧，<br/>主，是我否？<br/>主，是我否？<br/>','',55361,8896);
INSERT INTO stanza VALUES('Z329','3','有人竟甘心辜负主恩，<br/>有人竟甘心事奉玛门，<br/>有人竟甘心罪中下沉，<br/>主，是我否？<br/>主，是我否？<br/>','',55362,8897);
INSERT INTO stanza VALUES('Z329','4','有人已否认救主耶稣，<br/>有人已使祂蒙受羞辱，<br/>有人已背叛，<br/>卖友、卖主，<br/>主，是我否？<br/>主，是我否？<br/>','',55363,8898);
INSERT INTO stanza VALUES('Z329','5','有人将被提到主面前，<br/>有人将享受安息甘甜，<br/>有人将得着生命冠冕，<br/>主，是我否？<br/>主，是我否？<br/>','',55364,8899);
INSERT INTO stanza VALUES('Z330','1','主爱长阔高深，<br/>实在不能推测；<br/>不然，像我这样罪人，<br/>怎能满被恩泽。<br/>','',55365,8900);
INSERT INTO stanza VALUES('Z330','2','我主出了重价，<br/>买我回来归祂；<br/>我今愿意背十字架，<br/>忠心一路跟祂。<br/>','',55366,8901);
INSERT INTO stanza VALUES('Z330','3','我今撇下一切，<br/>为要得着基督；<br/>生也、死也，想都不屑，<br/>有何使我回顾？<br/>','',55367,8902);
INSERT INTO stanza VALUES('Z330','4','亲友、欲好、利名，<br/>于我夫复何用？<br/>恩主为我变作苦贫，<br/>我今为主亦穷。<br/>','',55368,8903);
INSERT INTO stanza VALUES('Z330','5','我爱我的救主，<br/>我求祂的称是；<br/>为祂之故，安逸变苦，<br/>利益变为损失！<br/>','',55369,8904);
INSERT INTO stanza VALUES('Z330','6','你是我的安慰，<br/>我的恩主耶稣！<br/>除你之外，在天何归？<br/>在地何所爱慕？<br/>','',55370,8905);
INSERT INTO stanza VALUES('Z330','7','艰苦、反对、飘零，<br/>我今一起不理；<br/>只求我主用你爱情，<br/>绕我灵、魂、身体。<br/>','',55371,8906);
INSERT INTO stanza VALUES('Z330','7','主阿，我今求你，<br/>施恩引导小子，<br/>立在我旁，常加我力，<br/>过此黑暗罪世。<br/>','',55372,8907);
INSERT INTO stanza VALUES('Z330','9','撒但、世界、肉体，<br/>时常试探、欺凌；<br/>你若不加小子能力，<br/>恐将贻羞你名！<br/>','',55373,8908);
INSERT INTO stanza VALUES('Z330','10','现今时候不多，<br/>求主使我脱尘；<br/>你一再来，我即唱说：<br/>阿利路亚！阿们！<br/>','',55374,8909);
INSERT INTO stanza VALUES('Z331','1','『为你，我流宝血，<br/>为你，我舍生命，<br/>将你洗得清洁，<br/>使你从死复生。<br/>为你，为你，舍生命，<br/>为我，你舍何情？<br/>','',55375,8910);
INSERT INTO stanza VALUES('Z331','2','为你，我费多年，<br/>来受劳苦灾殃，<br/>好使欢乐永远，<br/>你也得以安享。<br/>为你，为你，我费多年，<br/>为我，你费几天？<br/>','',55376,8911);
INSERT INTO stanza VALUES('Z331','3','我父光明之家，<br/>我的荣耀宝座，<br/>为你，我都撇下，<br/>来到苦地飘泊。<br/>为你，为你，我撇这些，<br/>为我你何所撇？<br/>','',55377,8912);
INSERT INTO stanza VALUES('Z331','4','为你，我受多苦，<br/>过于你口能述，<br/>受了极大痛楚，<br/>救你脱离阴府。<br/>为你，为你，我受多苦，<br/>为我，你肯何负？<br/>','',55378,8913);
INSERT INTO stanza VALUES('Z331','5','从我天上之家，<br/>为你，我已带来：<br/>救恩无以复加，<br/>赦免陪同慈爱。<br/>为你，为你，我带许多，<br/>为我，你带甚么？』<br/>','',55379,8914);
INSERT INTO stanza VALUES('Z331','6','『主，我献上生命，<br/>并献所有时光，<br/>完全听你使令，<br/>脱离地上捆绑。<br/>为我，为我，你的全舍，<br/>为你，我撇一切！』<br/>','',55380,8915);
INSERT INTO stanza VALUES('Z332','1','哦，那不肯放我之爱，<br/>我将疲魂安息于你；<br/>我把所欠余生归来，<br/>好使牠在你这深海，<br/>得更丰满洋溢。<br/>','',55381,8916);
INSERT INTO stanza VALUES('Z332','2','哦，那照耀我路之光，<br/>我将残灯带来交你；<br/>我心因得你光复亮，<br/>牠的日子借你太阳，<br/>得更光明美丽。<br/>','',55382,8917);
INSERT INTO stanza VALUES('Z332','3','哦，那苦中寻我之乐，<br/>我心不能向你关闭；<br/>我在雨中彩虹寻得，<br/>知你应许不会空说，<br/>天亮便无泪涕。<br/>','',55383,8918);
INSERT INTO stanza VALUES('Z332','4','哦，那使我抬头十架，<br/>我不敢求与你稍离；<br/>今生虚荣死葬土下，<br/>那土长出生命红花，<br/>永远开放不已。<br/>','',55384,8919);
INSERT INTO stanza VALUES('Z333','1','你的灵岂非已见祂过？<br/>你的心曾否被祂所夺？<br/>你当认祂为人中第一人，<br/>欢喜选那上好的福分。<br/>','',55385,8920);
INSERT INTO stanza VALUES('Z333','chorus','你是千万人中之第一人！<br/>哦，求你开我眼，<br/>并夺我心，<br/>摔碎众偶像，<br/>并欢然加冠<br/>你为千万人中之第一人！<br/>','',55386,8921);
INSERT INTO stanza VALUES('Z333','2','世界的一切虚荣、珍宝，<br/>尽都是偶像，使人颠倒；<br/>镀过金，<br/>使人不容易淡泊，<br/>浸过蜜，使人真难超脱。<br/>','',55387,8922);
INSERT INTO stanza VALUES('Z333','3','甚么会使地上的偶像，<br/>失去牠那美丽的模样，<br/>并不是灰心、<br/>失望或劝勉，<br/>乃是『无价之宝』<br/>的一现！<br/>','',55388,8923);
INSERT INTO stanza VALUES('Z333','4','并不是甚么本分催促，<br/>就会使偶像化成灰土；<br/>乃是祂荣耀美丽的倾投，<br/>并祂心里柔爱的流露。<br/>','',55389,8924);
INSERT INTO stanza VALUES('Z333','5','有谁愿熄灭他的灯光，<br/>若非早晨的日已在望？<br/>又有谁愿意收藏他寒衣，<br/>若非炎夏的风已兴起？<br/>','',55390,8925);
INSERT INTO stanza VALUES('Z333','6','惟有彼得所见的泪眼，<br/>司提反所仰望的荣脸，<br/>陪着马利亚同哭的慈心，<br/>会使我脱离地的吸引。<br/>','',55391,8926);
INSERT INTO stanza VALUES('Z333','7','哦，求你来施情并吸引，<br/>直等到你充满了这心；<br/>我们蒙救赎，<br/>是你的同伴，<br/>与偶像还有甚么相干？<br/>','',55392,8927);
INSERT INTO stanza VALUES('Z334','1','绝对分别出来，<br/>归于主圣灵！<br/>不惜任何代价，<br/>寻求祂丰盛；<br/>割断所有岸索，<br/>开到水深处，<br/>得着祂的大能，<br/>带进祂祝福。<br/>','',55393,8928);
INSERT INTO stanza VALUES('Z334','chorus','绝对分别出来，<br/>归于万有主，<br/>答应祂的呼召，<br/>寻求祂丰富。<br/>','',55394,8929);
INSERT INTO stanza VALUES('Z334','2','绝对分别出来，<br/>归于主圣灵！<br/>沉没还要沉没，<br/>直到己去净！<br/>直到器皿倒空，<br/>祂脚前破碎；<br/>等候直到充满，<br/>流出主恩惠。<br/>','',55395,8930);
INSERT INTO stanza VALUES('Z334','3','绝对分别出来，<br/>归于神旨意！<br/>走主所走道路，<br/>靠着祂恩力；<br/>撇弃安逸、享乐，<br/>随主向前进；<br/>等候祂的引导，<br/>静听祂声音。<br/>','',55396,8931);
INSERT INTO stanza VALUES('Z334','4','绝对分别出来！<br/>一直到永世；<br/>不要我的心意，<br/>乃要祂意旨；<br/>我的计划、愿望，<br/>在祂全灭没；<br/>似乎一无所有，<br/>万有实属我。<br/>','',55397,8932);
INSERT INTO stanza VALUES('Z334','5','绝对分别出来！<br/>何等的甜美，<br/>作祂爱的俘虏，<br/>自由何宝贵；<br/>脱离罪的辖制、<br/>疑惑与恐惧，<br/>脱离所有重担、<br/>忧愁和罣虑。<br/>','',55398,8933);
INSERT INTO stanza VALUES('Z334','6','绝对分别出来！<br/>何等的安息，<br/>在祂面前等候，<br/>照祂的心意；<br/>等候得着充满，<br/>满有祂圣灵，<br/>将我里面各部<br/>完全都炼净。<br/>','',55399,8934);
INSERT INTO stanza VALUES('Z334','7','祂灵将我充满，<br/>带着祂同在！<br/>在祂我蒙祝福，<br/>在祂我蒙爱！<br/>今后里面亮光<br/>永不再变暗，<br/>如此向祂活着，<br/>分别到永远。<br/>','',55400,8935);
INSERT INTO stanza VALUES('Z335','1','我已转身背向俗世，<br/>和牠一切的欢娱；<br/>我已心向更美的事，<br/>就是天上的储蓄；<br/>一切虚荣、一切扬显，<br/>不能使我再逗遛；<br/>我已越过分别界线，<br/>世界已丢在背后。<br/>','',55401,8936);
INSERT INTO stanza VALUES('Z335','chorus','远远丢背后，<br/>远远丢背后，<br/>我已越过分别界线，<br/>世界已丢在背后。<br/>','',55402,8937);
INSERT INTO stanza VALUES('Z335','2','我已脱离罪的生活，<br/>弃绝所有的愚行；<br/>我已接受主的领率，<br/>愿意听祂的命令；<br/>我既靠主免为死囚，<br/>有主作我的元首；<br/>就愿为祂舍去所有，<br/>世界已丢在背后。<br/>','',55403,8938);
INSERT INTO stanza VALUES('Z335','chorus','远远丢背后，<br/>远远丢背后，<br/>就愿为祂舍去所有，<br/>世界已丢在背后。<br/>','',55404,8939);
INSERT INTO stanza VALUES('Z335','3','我今永远不再返回<br/>旧日愚昧的境地；<br/>惟独在此才不定罪，<br/>在此才会有安息；<br/>我今已经更换主人，<br/>对祂我要永伺候；<br/>地的捆绑就此脱尽，<br/>世界已丢在背后。<br/>','',55405,8940);
INSERT INTO stanza VALUES('Z335','chorus','远远丢背后，<br/>远远丢背后，<br/>地的捆绑就此脱尽，<br/>世界已丢在背后。<br/>','',55406,8941);
INSERT INTO stanza VALUES('Z335','4','我的前途，一定永定，<br/>我并不要别救主；<br/>我也不求更好福音，<br/>过于祂赐的宽恕；<br/>我心已经决定事神，<br/>无论如何不回头；<br/>已往一切实为可恨，<br/>世界已丢在背后。<br/>','',55407,8942);
INSERT INTO stanza VALUES('Z335','chorus','远远丢背后，<br/>远远丢背后，<br/>已往一切实为可恨，<br/>世界已丢在背后。<br/>','',55408,8943);
INSERT INTO stanza VALUES('Z336','1','圣洁、欢乐，何等分别！<br/>惟有如此能蒙福；<br/>脱开主外一切事物，<br/>惟主是我所爱所慕，<br/>单单安息在基督，<br/>单单安息在基督。<br/>','',55409,8944);
INSERT INTO stanza VALUES('Z336','2','基督呼召，要我分别，<br/>祂已带路如此行；<br/>祂的生活将此说明，<br/>祂的生活也是例证，<br/>谁愿随从祂带领？<br/>谁愿随从祂带领？<br/>','',55410,8945);
INSERT INTO stanza VALUES('Z336','3','恩主，求你使我愿意<br/>出到营外归于你，<br/>完全归你，欢乐降服，<br/>忍受你所受的羞辱，<br/>完全归你无所遗，<br/>完全归你无所遗。<br/>','',55411,8946);
INSERT INTO stanza VALUES('Z336','4','分别！脱离忧你之事，<br/>分别！罪人也脱离；<br/>然而，像你关心罪人，<br/>并且像你担负他们，<br/>跟随你爱的踪迹，<br/>跟随你爱的踪迹。<br/>','',55412,8947);
INSERT INTO stanza VALUES('Z336','5','完全归你！心爱救主，<br/>愿我与你无居间；<br/>完全归你！奉献彻底，<br/>完全归你！分别至极，<br/>完全归你到永远！<br/>完全归你到永远！<br/>','',55413,8948);
INSERT INTO stanza VALUES('Z337','1','我将一切全献基督，<br/>全献恩主心甘愿；<br/>我要永远爱主，随主，<br/>天天活在主面前。<br/>','',55414,8949);
INSERT INTO stanza VALUES('Z337','chorus','一切全奉献！<br/>一切全奉献！<br/>我的恩主，<br/>向你我愿一切全奉献！<br/>','',55415,8950);
INSERT INTO stanza VALUES('Z337','2','我将一切全献基督，<br/>我今俯伏主脚前；<br/>今世福乐永不我属，<br/>恩主，收我在今天。<br/>','',55416,8951);
INSERT INTO stanza VALUES('Z337','3','我将一切全献基督，<br/>恩主，将我全得着。<br/>惟愿圣灵从我证出：<br/>我是属主，主属我。<br/>','',55417,8952);
INSERT INTO stanza VALUES('Z337','4','我将一切全献基督，<br/>主，我愿作你器皿；<br/>恩惠、能力充我如注，<br/>显明你生在我身。<br/>','',55418,8953);
INSERT INTO stanza VALUES('Z337','5','我将一切全献基督，<br/>圣火已焚我心情；<br/>哦，这救恩甜美丰富，<br/>荣耀、荣耀归主名。<br/>','',55419,8954);
INSERT INTO stanza VALUES('Z338','1','都归基督，都归基督，<br/>都归基督理当然；<br/>我既是主宝血所赎，<br/>主就当得所有权。<br/>','',55420,8955);
INSERT INTO stanza VALUES('Z338','chorus','都归基督，都归基督，<br/>都归基督我救主！<br/>都归基督，都归基督，<br/>都归基督我救主！<br/>','',55421,8956);
INSERT INTO stanza VALUES('Z338','2','都归基督，都归基督，<br/>都归基督心所慕；<br/>主爱激励，主爱催促，<br/>怎能不都归救主？<br/>','',55422,8957);
INSERT INTO stanza VALUES('Z338','3','都归基督，都归基督，<br/>都归基督成为圣：<br/>身体、灵、魂、<br/>时间、财物、<br/>所是、所有并所能。<br/>','',55423,8958);
INSERT INTO stanza VALUES('Z338','4','愿我双手归主使用，<br/>愿我两脚跟主行，<br/>愿我双目瞻主圣容，<br/>愿我两唇颂主名。<br/>','',55424,8959);
INSERT INTO stanza VALUES('Z338','5','自从我眼注视基督，<br/>所有事物全变色；<br/>一望主在十架受苦，<br/>我就甘愿负主轭。<br/>','',55425,8960);
INSERT INTO stanza VALUES('Z338','6','奇妙恩典，深高阔长！<br/>我口歌颂，心感戴；<br/>荣耀救主，王中之王，<br/>竟然看我可宝爱！<br/>','',55426,8961);
INSERT INTO stanza VALUES('Z339','1','主，你得着我一生，<br/>使牠归你成为圣；<br/>得着我日与我时，<br/>归你使用永无止。<br/>','',55427,8962);
INSERT INTO stanza VALUES('Z339','chorus','为我荆棘冠冕你肯戴，<br/>为我钉死苦架你受害；<br/>为你我愿献上<br/>我命与我爱，<br/>事你、爱你到万代。<br/>','',55428,8963);
INSERT INTO stanza VALUES('Z339','2','得着我手与我足，<br/>勤作你工，奔你路；<br/>得着我口与我舌，<br/>传扬你话，颂你德。<br/>','',55429,8964);
INSERT INTO stanza VALUES('Z339','3','得着我金与我银，<br/>分文不由我留存；<br/>得着我才与我智，<br/>运用全照你指示。<br/>','',55430,8965);
INSERT INTO stanza VALUES('Z339','4','得着我心与我意，<br/>全归于你不他依；<br/>得着我爱与我情，<br/>全注于你不别倾。<br/>','',55431,8966);
INSERT INTO stanza VALUES('Z339','5','主，你得着我一切，<br/>我愿与你永联结，<br/>爱你、念你、事奉你，<br/>永远失去在你里。<br/>','',55432,8967);
INSERT INTO stanza VALUES('Z340','1','完全的交出，主，<br/>我今愿完全的交出，<br/>交在你前。<br/>所有摆在祭坛，<br/>所有全都奉献，<br/>你已赎我罪愆，<br/>我今归你。<br/>','',55433,8968);
INSERT INTO stanza VALUES('Z340','2','完全的交出-生命、一切，<br/>凡你赐我的，全都不缺。<br/>求你向我发言，<br/>我愿跟随不偏，<br/>从今直到永远，<br/>顺服我主。<br/>','',55434,8969);
INSERT INTO stanza VALUES('Z340','3','完全的交出-金、银、财物；<br/>你所赐我的，何其丰富。<br/>全愿向你交出，<br/>因你是我买主，<br/>理当全都你属，<br/>耶稣我主。<br/>','',55435,8970);
INSERT INTO stanza VALUES('Z340','4','完全的交出-我属基督；<br/>完全的交出，我的救主；<br/>从我活出你命，<br/>在你有神丰盛，<br/>非我，惟你得胜，<br/>一切的主。<br/>','',55436,8971);
INSERT INTO stanza VALUES('Z341','1','勿对我谈属地享乐，<br/>勿用鄙利引诱我；<br/>勿愚我以地上幻影，<br/>勿用虚荣烦扰我。<br/>我已弃绝化装偶像，<br/>今后不再属自己；<br/>我已将心献给基督，<br/>我愿属祂无所遗。<br/>','',55437,8972);
INSERT INTO stanza VALUES('Z341','chorus','我不属自己，<br/>我不属自己，<br/>我今属于基督，<br/>不再属于自己。<br/>','',55438,8973);
INSERT INTO stanza VALUES('Z341','2','哦，只属于我主基督，<br/>带来何等的安息！<br/>当我所有全都不留，<br/>祂的丰盛我能倚。<br/>荣耀恩主，将我接收，<br/>使我完全属于你，<br/>适合享受你作我分，<br/>当我喜欢成你的。<br/>','',55439,8974);
INSERT INTO stanza VALUES('Z341','3','疲倦人哪，放弃挣扎，<br/>永勿再属你自己；<br/>将你自己全给基督，<br/>全然属祂无所遗。<br/>祂曾舍己为要得你，<br/>今来要你全归祂；<br/>凡祂所有都已给你，<br/>你就不该不给祂。<br/>','',55440,8975);
INSERT INTO stanza VALUES('Z342','1','活着为耶稣，<br/>只望能单纯，<br/>所有的一切都求祂喜悦，<br/>自动并乐意来向祂投顺，<br/>这是我蒙神赐福的秘诀。<br/>','',55441,8976);
INSERT INTO stanza VALUES('Z342','chorus','耶稣我主，我救主，<br/>我将自己给你，<br/>因你为我代死时，<br/>给的是你自己；<br/>从此，我无别的主，<br/>我心是你宝座，<br/>我的一生一世，基督，<br/>只要为你生活。<br/>','',55442,8977);
INSERT INTO stanza VALUES('Z342','2','活着为耶稣，<br/>祂为我缘故，<br/>在十字架上担当罪与羞；<br/>这爱激励我答应祂招呼，<br/>恭敬向着祂奉献我所有。<br/>','',55443,8978);
INSERT INTO stanza VALUES('Z342','3','活着为耶稣，<br/>无论在何处，<br/>我为祂缘故，<br/>作成祂事务，<br/>甘愿来承受损失或痛苦，<br/>看每个试炼是十架一部。<br/>','',55444,8979);
INSERT INTO stanza VALUES('Z342','4','活着为耶稣，<br/>时间已短促，<br/>祂的笑脸是我宝贵秘密，<br/>寻找失丧者，<br/>祂死所救赎，<br/>带领疲倦者，<br/>享受祂安息。<br/>','',55445,8980);
INSERT INTO stanza VALUES('Z343','1','不是挣扎，乃是归依，<br/>会使我得力；<br/>挣扎不会使我得益，<br/>归依才安息。<br/>','',55446,8981);
INSERT INTO stanza VALUES('Z343','2','我若不作无谓奋勉，<br/>并不再努力，<br/>没有条件完全奉献，<br/>会得神安息。<br/>','',55447,8982);
INSERT INTO stanza VALUES('Z343','3','我的全量都靠耶稣，<br/>惟祂能拯救；<br/>因祂的爱，我乐为奴，<br/>不愿再自由。<br/>','',55448,8983);
INSERT INTO stanza VALUES('Z343','4','顺服，我就真能得势，<br/>死，我就得生；<br/>『不是我意，<br/>乃是你旨，』<br/>会使我得胜。<br/>','',55449,8984);
INSERT INTO stanza VALUES('Z344','1','照你企图，主，<br/>照你企图，<br/>因你是陶人，我是泥土：<br/>制造又甄陶，照你美意；<br/>降服且等候，使我归依。<br/>','',55450,8985);
INSERT INTO stanza VALUES('Z344','2','照你企图，主，<br/>照你企图，<br/>我在你面前谦卑俯伏：<br/>鉴察又试炼，显我真情；<br/>修理且洗涤，使我纯净。<br/>','',55451,8986);
INSERT INTO stanza VALUES('Z344','3','照你企图，主，<br/>照你企图，<br/>完全脱自己，是我所慕：<br/>破碎又剥夺，使我成零；<br/>挖透且倒空，使我无剩。<br/>','',55452,8987);
INSERT INTO stanza VALUES('Z344','4','照你企图，主，<br/>照你企图，<br/>深愿我全人向你降服：<br/>圣灵充满我，流露你命；<br/>基督活于我，彰显你形。<br/>','',55453,8988);
INSERT INTO stanza VALUES('Z345','1','我当如何爱我的主？<br/>如何奉献使祂欢喜？<br/>不稍离开祂的道路，<br/>学习如何与祂亲密？<br/>','',55454,8989);
INSERT INTO stanza VALUES('Z345','2','我的途径若是痛苦，<br/>主，我求你，禁我退缩，<br/>使我仍然向你顺服，<br/>追忆你的十架重负。<br/>','',55455,8990);
INSERT INTO stanza VALUES('Z345','3','让我思念，你曾如何<br/>离开许多纯洁乐事，<br/>来忧、来饿、<br/>来倦、来渴，<br/>无家之夜，不息之日。<br/>','',55456,8991);
INSERT INTO stanza VALUES('Z345','4','为我来忧、来倦、来死，<br/>你来不求自己喜悦；<br/>地上安逸虽难恝置，<br/>我岂爱你不胜这些？<br/>','',55457,8992);
INSERT INTO stanza VALUES('Z345','5','是的，我算万事为损，<br/>为要来得你的注意；<br/>丢弃万事虽如土粪，<br/>为着爱你有何可惜？<br/>第四节的『恝置，』意思是淡然置之。<br/>','',55458,8993);
INSERT INTO stanza VALUES('Z346','1','我今愿跟随耶稣，<br/>不论走何路：<br/>或是平坦大路，<br/>或是崎岖窄途；<br/>既有救主亲自相辅，<br/>我就不踌躇，<br/>一路跟随耶稣，<br/>直到进国度。<br/>','',55459,8994);
INSERT INTO stanza VALUES('Z346','chorus','跟随！跟随！<br/>我愿跟随耶稣！<br/>不论福，不论苦，<br/>我必跟随主！<br/>跟随！跟随！<br/>我愿跟随耶稣！<br/>不论领我何处，<br/>我必跟随主！<br/>','',55460,8995);
INSERT INTO stanza VALUES('Z346','2','我今愿跟随耶稣，<br/>不论在何处：<br/>或在明媚乐土，<br/>或在死荫幽谷；<br/>既有救主亲自照护，<br/>我就不感苦；<br/>处处跟随耶稣，<br/>直到末一步。<br/>','',55461,8996);
INSERT INTO stanza VALUES('Z346','3','我今愿跟随耶稣，<br/>不论时何如：<br/>或是阳光满目，<br/>或是黑云密布；<br/>既有救主亲自部署，<br/>我就无所顾；<br/>时时跟随耶稣，<br/>一直到天曙。<br/>','',55462,8997);
INSERT INTO stanza VALUES('Z347','1','主，我今背十架，<br/>前来跟随你；<br/>浮名利、虚荣华，<br/>一概都舍弃；<br/>人讥笑，人辱骂，<br/>我全不在意；<br/>虽受苦，虽受压，<br/>窄路不稍离；<br/>靠主恩，遵主话，<br/>忠心直到底；<br/>到那日，蒙主夸，<br/>冠冕荣无比；<br/>冠冕荣无比，<br/>冠冕荣无比。<br/>','',55463,8998);
INSERT INTO stanza VALUES('Z348','1','我今撇下一切事物，<br/>背起十架跟耶稣；<br/>甘受藐视、厌弃、贫苦，<br/>一心跟主走窄路。<br/>前我所爱、所慕、所求，<br/>今与雄心同归尽；<br/>但我又是何等饶优，<br/>神与基督是我分。<br/>','',55464,8999);
INSERT INTO stanza VALUES('Z348','2','让这世界弃我、嫌我，<br/>恩主也曾被弃嫌；<br/>人面、人心，<br/>欺我、骗我，<br/>惟你永远不欺骗。<br/>当你向我显出笑脸，<br/>友虽生疏敌虽险，<br/>但我心安，处之泰然，<br/>因我得见你欢颜。<br/>','',55465,9000);
INSERT INTO stanza VALUES('Z348','3','去罢！今世名利福乐，<br/>来罢！痛苦和嘲讥；<br/>为主活着苦是喜乐，<br/>有主喜悦损是益。<br/>我既称祂阿爸父亲，<br/>我既将心注于你；<br/>怒吼暴风、密集厚云，<br/>都该效力成我益。<br/>','',55466,9001);
INSERT INTO stanza VALUES('Z348','4','人虽逼我使我苦痛，<br/>不过驱我到你前；<br/>世间苦难压我越重，<br/>天上平安越甘甜。<br/>有何忧苦能将我袭，<br/>当你荣面向我显？<br/>有何快乐能将我迷，<br/>若你不在牠里面？<br/>','',55467,9002);
INSERT INTO stanza VALUES('Z348','5','向前！由恩进入荣耀，<br/>信当籐牌，求当翼；<br/>永世日子就要破晓，<br/>主必领我直到底。<br/>地上职事就要停止，<br/>作客旅程就要完，<br/>盼望就要变成事实，<br/>信变眼见，求变赞。<br/>','',55468,9003);
INSERT INTO stanza VALUES('Z349','1','众人涌进主的国度，<br/>十架少人负；<br/>众人争夺主的赏赐，<br/>世界有谁辞？<br/>人虽无心走主道路，<br/>仍想主祝福！<br/>人虽无心走主道路，<br/>仍想主祝福！<br/>','',55469,9004);
INSERT INTO stanza VALUES('Z349','2','众人都慕得主荣耀，<br/>羞辱少人要；<br/>众人都爱同主掌权，<br/>损失有谁愿？<br/>几乎无人因主缘故，<br/>看万事如土！<br/>','',55470,9005);
INSERT INTO stanza VALUES('Z349','3','多人都贪享主甘旨，<br/>少有愿禁食！<br/>多人都喜登主宝座，<br/>少有愿飘泊！<br/>同祂唱诗虽然有人，<br/>儆醒却不能。<br/>','',55471,9006);
INSERT INTO stanza VALUES('Z349','4','众人都想同主高贵，<br/>卑贱却都畏。<br/>当主凡事为他豫备，<br/>他就大赞美；<br/>当主稍微求他一点，<br/>就立发怨言。<br/>','',55472,9007);
INSERT INTO stanza VALUES('Z349','5','但那诚实爱主的人，<br/>祸福都不问，<br/>就是他们宝贵心血，<br/>也愿为主舍；<br/>求主给我这样心志，<br/>赤忠忘生死。<br/>','',55473,9008);
INSERT INTO stanza VALUES('Z350','1','谁是在主这边？<br/>谁要跟随主？<br/>谁要为主活着，<br/>走祂的道路？<br/>谁要撇开世界，<br/>去为主争战？<br/>谁是在主这边，<br/>跟随主向前？<br/>','',55474,9009);
INSERT INTO stanza VALUES('Z350','chorus','借着你的救赎，<br/>并借你恩典，<br/>可爱、荣耀救主，<br/>我在你这边。<br/>','',55475,9010);
INSERT INTO stanza VALUES('Z350','2','参加主的军队，<br/>欢乐去争战，<br/>不是为着荣耀，<br/>不是为冠冕；<br/>乃是因着主爱<br/>激励我向前；<br/>我既蒙祂恩待，<br/>该在祂这边。<br/>','',55476,9011);
INSERT INTO stanza VALUES('Z350','3','你已将我救赎，<br/>作你的子民，<br/>乃是用你宝血，<br/>不是用金银；<br/>凡来跟从你者，<br/>得福都无限；<br/>你使我们甘愿<br/>且自由向前。<br/>','',55477,9012);
INSERT INTO stanza VALUES('Z350','4','战争虽会凶猛，<br/>仇敌也强悍；<br/>但是主的军队，<br/>无人能击散。<br/>在祂大纛之下，<br/>必定能得胜，<br/>因祂真实、不变，<br/>奏凯已确定。<br/>','',55478,9013);
INSERT INTO stanza VALUES('Z350','5','蒙主选为兵丁，<br/>在今世争战，<br/>我当完全忠心，<br/>随元帅向前；<br/>如此服事我王，<br/>切勿变冷淡，<br/>守住高贵身位，<br/>忠贞又勇敢。<br/>','',55479,9014);
INSERT INTO stanza VALUES('Z351','1','我是否要背负十架，<br/>跟从神的羔羊？<br/>我岂可以怕出代价，<br/>要得世界原谅？<br/>','',55480,9015);
INSERT INTO stanza VALUES('Z351','chorus','因你名，宝贵的名，<br/>因你为我舍命，<br/>靠恩，无论如何艰难，<br/>我要求你喜欢。<br/>','',55481,9016);
INSERT INTO stanza VALUES('Z351','2','别人苦战要得荣耀，<br/>血汗满被沙场；<br/>我岂可以安坐花轿，<br/>盼望抬到天上？<br/>','',55482,9017);
INSERT INTO stanza VALUES('Z351','3','难道我无仇敌当拒？<br/>我无破口当堵？<br/>难道俗世也可相与？<br/>也可作我帮助？<br/>','',55483,9018);
INSERT INTO stanza VALUES('Z351','4','我要掌权，就得争战，<br/>哦主，加我力量；<br/>我愿受辱，我不畏难，<br/>靠你话语刚强。<br/>','',55484,9019);
INSERT INTO stanza VALUES('Z352','1','我们虽然时常摇动，<br/>但祂依然历久不变；<br/>祂的应许无一落空，<br/>天地没有那样贞坚。<br/>','',55485,9020);
INSERT INTO stanza VALUES('Z352','2','我们虽然二三其心，<br/>但祂不肯撇弃我们；<br/>虽受冷落，仍要亲近，<br/>地上朋友无祂这真！<br/>','',55486,9021);
INSERT INTO stanza VALUES('Z352','3','祂永不肯辜负我们，<br/>所有信托祂都尽力；<br/>因为祂既爱了我们，<br/>就爱我们一直到底。<br/>','',55487,9022);
INSERT INTO stanza VALUES('Z352','4','到底！我们对祂无良，<br/>忘祂，伤祂，暗中心变；<br/>祂外，我们另事偶像，<br/>心里也不抱歉半点！<br/>','',55488,9023);
INSERT INTO stanza VALUES('Z352','5','到这偶像倾倒绝迹，<br/>不禁悲伤，又来寻求<br/>我们从前所辜负的，<br/>这位始终如一的友！<br/>','',55489,9024);
INSERT INTO stanza VALUES('Z352','6','祂又收留安慰我们，<br/>并引我们亲近自己，<br/>一若毫无其事发生，<br/>并爱我们一直到底。<br/>','',55490,9025);
INSERT INTO stanza VALUES('Z352','7','哦主，我们对着这爱，<br/>不能不发高声赞美；<br/>比死坚强，比水忍耐，<br/>我们心融，只有感佩。<br/>','',55491,9026);
INSERT INTO stanza VALUES('Z353','1','从前我亦曾热心，<br/>多努力，求上进，<br/>可怜现在已改变，<br/>不与救主亲近；<br/>追想昔日殷勤景，<br/>深夜寐，清晨兴，<br/>如何辛苦不自顾，<br/>而今却冷如冰！<br/>','',55492,9027);
INSERT INTO stanza VALUES('Z353','chorus','我岂能忘救主？<br/>我岂可离天父？<br/>祂心为我忧伤，<br/>我心安忍不顾？<br/>','',55493,9028);
INSERT INTO stanza VALUES('Z353','2','从前我已献全身，<br/>虽劳碌，不为金，<br/>而今却为世俗用，<br/>却随世界浮沉！<br/>从前守节今流连，<br/>是放纵，说消遣！<br/>多年流浪不懊悔，<br/>何日才会生厌？<br/>','',55494,9029);
INSERT INTO stanza VALUES('Z353','3','从前我心专爱主，<br/>在祂外，无所慕，<br/>时常想念热如火，<br/>无论梦寐醒苏，<br/>世俗、人情皆无意，<br/>一切事都丢弃，<br/>今则追求属地物，<br/>与俗复有何异？<br/>','',55495,9030);
INSERT INTO stanza VALUES('Z353','4','追想昔日跪主前，<br/>何满足，何甘甜，<br/>应许你说：『从今后，<br/>我只听你差遣，<br/>愿意顺服失自由，<br/>在你外，无他求；』<br/>至今为时并不久，<br/>此心已归乌有！<br/>','',55496,9031);
INSERT INTO stanza VALUES('Z353','5','你外劳碌总是空，<br/>如捉影，如捕风，<br/>多年流落羊群外，<br/>无你怎能亨通；<br/>世界情欲快过去，<br/>岂可再受驾御？<br/>爱主多年在等候，<br/>岂可依然犹豫？<br/>','',55497,9032);
INSERT INTO stanza VALUES('Z353','6','晨星将现夜已阑，<br/>生越过，时越暂，<br/>立即脱离堕落处，<br/>重来求你喜欢；<br/>拒绝世俗和魔鬼，<br/>再来尝天滋味，<br/>爱心已失今再得，<br/>仍站从前地位。<br/>','',55498,9033);
INSERT INTO stanza VALUES('Z353','chorus','我今再行窄路，<br/>虚空世界不顾；<br/>前面荣耀快现，<br/>我愿忠心受苦。<br/>','',55499,9034);
INSERT INTO stanza VALUES('Z354','1','我岂可再冷淡退后，<br/>使神圣灵终日担忧，<br/>恩主也在等候！<br/>我今愿意转身回头，<br/>不再留恋，不再逗遛，<br/>就此跟主而走！<br/>','',55500,9035);
INSERT INTO stanza VALUES('Z354','2','我今将我所是所有，<br/>完全奉献，一无保留，<br/>从今直到永久；<br/>惟愿恩主悦纳、保守，<br/>使我今后无望、无求，<br/>惟愿父旨成就。<br/>','',55501,9036);
INSERT INTO stanza VALUES('Z354','3','回顾已往，又惭、又羞，<br/>无一灵魂是我所救-<br/>救恩被我全扣；<br/>今求恩主用祂膏油，<br/>将我全人厚厚浇透，<br/>使成救恩出口。<br/>','',55502,9037);
INSERT INTO stanza VALUES('Z354','4','恩主一向施恩深厚，<br/>待我远胜知己爱友，<br/>竟以我作配偶。<br/>祂的生命我当倚投，<br/>祂的苦难我该接受，<br/>将祂生命流露。<br/>','',55503,9038);
INSERT INTO stanza VALUES('Z355','1','当人弃绝地的贿赂，<br/>前来为神而活，<br/>他所得的无限富有，<br/>口舌难以述说。<br/>因为万有全是他的，<br/>生、死、或是事、物；<br/>基督是他生命、呼吸，<br/>也是他的住处。<br/>','',55504,9039);
INSERT INTO stanza VALUES('Z355','2','像我这人，王肯选上，<br/>有分祂的宝座，<br/>而我竟然不肯应选，<br/>这是何其奇特！<br/>永远勿说这是牺牲！<br/>无论代价若干，<br/>只要能入加略圣军，<br/>权利都是难言。<br/>','',55505,9040);
INSERT INTO stanza VALUES('Z355','3','起来！将这交易算看：<br/>零碎换来整个-<br/>万事、万物、加上万人，<br/>竟都归你得着。<br/>当你属祂，万有属你，<br/>并且祂你合一；<br/>你还得享无限生命，<br/>权益有何能比！<br/>','',55506,9041);
INSERT INTO stanza VALUES('Z356','1','与你合一，永远之子，<br/>因信与你成一灵，<br/>得你包罗万有的死，<br/>和非受造的生命。<br/>与你合一，蒙爱之子，<br/>借恩成为你一部，<br/>与你同为父的后嗣，<br/>并作圣灵的房屋。<br/>','',55507,9042);
INSERT INTO stanza VALUES('Z356','2','与你合一，化身之子，<br/>作你奥秘的肢体，<br/>因你诞生与你连枝，<br/>与你一同客此地。<br/>与你合一，受膏之子，<br/>同得圣灵的能力，<br/>日复一日，时复一时，<br/>与你合作不稍离。<br/>','',55508,9043);
INSERT INTO stanza VALUES('Z356','3','与你合一，被弃之子，<br/>经过审判和咒诅，<br/>永远同你向罪而死，<br/>并胜凶恶的阴府。<br/>与你合一，复活之子，<br/>脱离坟墓的埋没，<br/>因你更生，同你更始，<br/>靠你逐日结义果。<br/>','',55509,9044);
INSERT INTO stanza VALUES('Z356','4','与你合一，升天之子，<br/>同登宝座来管治，<br/>你的权柄我也掌执，<br/>因我和你同位置。<br/>与你合一，再来之子，<br/>同得荣耀同临世，<br/>那时都要显你殊姿，<br/>与你合一无已时。<br/>','',55510,9045);
INSERT INTO stanza VALUES('Z357','1','联于基督得胜的主，<br/>并祂十架工夫；<br/>我处艰难仍觉稳固，<br/>因祂必定扶助。<br/>','',55511,9046);
INSERT INTO stanza VALUES('Z357','2','联于基督复活的主，<br/>现今居于天府，<br/>十架光荣，立时彰显<br/>无限希奇恩典。<br/>','',55512,9047);
INSERT INTO stanza VALUES('Z357','3','联于基督完全得胜，<br/>我灵立即飞腾；<br/>靠主圣名我一宣告，<br/>黑暗权势即逃。<br/>','',55513,9048);
INSERT INTO stanza VALUES('Z357','4','复活基督，你真庄严！<br/>愿我与你相联；<br/>你十字架时常得胜，<br/>败坏撒但凶横。<br/>','',55514,9049);
INSERT INTO stanza VALUES('Z357','5','联于基督何等尊大！<br/>这是神的救法，<br/>这叫我们永远赞美，<br/>因为羔羊真配。<br/>','',55515,9050);
INSERT INTO stanza VALUES('Z358','1','今在基督何奇妙，<br/>所得地位真高尚！<br/>借恩得救何荣耀，<br/>竟然能与祂一样。<br/>将来同祂显现时，<br/>我必与祂全相像；<br/>但今与祂行于此，<br/>我就能与祂一样。<br/>','',55516,9051);
INSERT INTO stanza VALUES('Z358','chorus','与祂一样，与祂一样，<br/>何等奇妙，与祂一样；<br/>主的奇恩临到我身上，<br/>使我与祂合一且一样。<br/>','',55517,9052);
INSERT INTO stanza VALUES('Z358','2','合一与祂同钉死，<br/>合一与祂同复活；<br/>咒诅之下得开释，<br/>现今与祂同活着。<br/>合一与祂同升天，<br/>合一与祂同名分；<br/>如妻与夫之相联，<br/>像枝与树同一身。<br/>','',55518,9053);
INSERT INTO stanza VALUES('Z358','3','合一与祂同功绩，<br/>合一与祂同祈求，<br/>凡祂价值的效力，<br/>因信全归我享受。<br/>合一与祂同信、爱，<br/>合一与祂同生命，<br/>有祂圣灵常同在，<br/>与祂一样成为圣。<br/>','',55519,9054);
INSERT INTO stanza VALUES('Z359','1','与你合一，恩主耶稣，<br/>与你合一在灵里；<br/>凡你所是都活我里，<br/>我今得享你自己。<br/>','',55520,9055);
INSERT INTO stanza VALUES('Z359','chorus','合为一，合为一，<br/>我与你合为一；<br/>你的丰富是我供给，<br/>我的一切全是你。<br/>','',55521,9056);
INSERT INTO stanza VALUES('Z359','2','今享你的属人生命，<br/>丰满有你的人性，<br/>所有你的为人生活，<br/>都能用于我人生。<br/>','',55522,9057);
INSERT INTO stanza VALUES('Z359','3','与你合一，在十架上，<br/>在你里面我已死；<br/>我向世界已经死了，<br/>世界向我也如此。<br/>','',55523,9058);
INSERT INTO stanza VALUES('Z359','4','与你合一，在复活里，<br/>现今与你同活着；<br/>复活生命-你的自己-<br/>在我里面供应我。<br/>','',55524,9059);
INSERT INTO stanza VALUES('Z359','5','与你合一，在升天里，<br/>现今同你坐天上；<br/>在这地上乃是旅客，<br/>我的真命在你藏。<br/>','',55525,9060);
INSERT INTO stanza VALUES('Z359','6','与你合一，在宝座上，<br/>有分于你的权柄，<br/>如同有分于你生命，<br/>同一性情，同一灵。<br/>','',55526,9061);
INSERT INTO stanza VALUES('Z360','1','哦，各各他！<br/>好，各各他！<br/>我主在此受死；<br/>祂流宝血，祂钉苦架，<br/>使我从罪得释。<br/>','',55527,9062);
INSERT INTO stanza VALUES('Z360','chorus','因此，切求我主，<br/>启示各各他的奥秘，<br/>使我知道，<br/>现在我是与祂合而为一。<br/>','',55528,9063);
INSERT INTO stanza VALUES('Z360','2','哦，各各他！<br/>好，各各他！<br/>在此我同主死：<br/>借着与主同钉十架，<br/>我的重负得释。<br/>','',55529,9064);
INSERT INTO stanza VALUES('Z360','3','哦，各各他！<br/>主的空坟<br/>也曾把我埋过；<br/>主的复苏我也有分，<br/>因此我能生活。<br/>','',55530,9065);
INSERT INTO stanza VALUES('Z360','4','哦，各各他！<br/>撒但全军<br/>在此被主羞辱；<br/>奉着主名，邪灵、魔君，<br/>向我也当俯伏。<br/>','',55531,9066);
INSERT INTO stanza VALUES('Z360','5','哦，各各他！<br/>我有主名，<br/>在争战时已足；<br/>仇敌一听，立即亡命，<br/>不能抵挡我主。<br/>','',55532,9067);
INSERT INTO stanza VALUES('Z360','6','哦，各各他！<br/>我赞美主！<br/>因祂在此受死，<br/>舍了祂命，赎我罪辜，<br/>使我捆绑全失。<br/>','',55533,9068);
INSERT INTO stanza VALUES('Z360','7','哦，各各他！<br/>我愿学习<br/>你的所有意义！<br/>我今因信，在得胜地，<br/>与主一同站立。<br/>','',55534,9069);
INSERT INTO stanza VALUES('Z361','1','主，你启示一个奥秘，<br/>就是我同你死的理，<br/>不用别法，不用别能，<br/>我就看见完全得胜。<br/>','',55535,9070);
INSERT INTO stanza VALUES('Z361','2','你的十架就是我的，<br/>其光照耀我生命里；<br/>一信与你同钉那里，<br/>世界失去牠的能力。<br/>','',55536,9071);
INSERT INTO stanza VALUES('Z361','3','我既与你十架同钉，<br/>胜过罪恶、自己、人情，<br/>就怎能尚追求地物？<br/>就怎能再盼望世福？<br/>','',55537,9072);
INSERT INTO stanza VALUES('Z361','4','因此，我便到你那里，<br/>与你同站十架死地，<br/>你命、你权，全是我的，<br/>因我与你合而为一。<br/>','',55538,9073);
INSERT INTO stanza VALUES('Z361','5','你既是来败坏撒但<br/>一切作为、势力、死权，<br/>我自然可和你同胜，<br/>天天经历你的大能。<br/>','',55539,9074);
INSERT INTO stanza VALUES('Z361','6','但是我主，我们只能<br/>靠着你的十架得胜；<br/>你走的路，我们当走，<br/>直到与你见面时候。<br/>','',55540,9075);
INSERT INTO stanza VALUES('Z361','7','我今接受你的同钉，<br/>求你所赐永远的灵<br/>使我更懂你死意义，<br/>使我脱离罪、己、肉体。<br/>','',55541,9076);
INSERT INTO stanza VALUES('Z361','7','我愿得胜像你得胜！<br/>与你同王，同得权能！<br/>背负十架，我们若肯，<br/>这些荣耀必定有分！<br/>','',55542,9077);
INSERT INTO stanza VALUES('Z362','1','我已与基督同钉死，<br/>脱自己、罪恶、俗世；<br/>所以我能平安接领<br/>主从死得生的命。<br/>我甘愿和祂同受苦，<br/>效法祂至死顺服；<br/>我愿跟主耶稣基督<br/>直走十字架的路。<br/>','',55543,9078);
INSERT INTO stanza VALUES('Z362','chorus','一直走十架窄路！<br/>主是受死在那里！<br/>求主使我能同你<br/>一直走十架窄路！<br/>','',55544,9079);
INSERT INTO stanza VALUES('Z362','2','我何难与基督同死，<br/>因复活我已认识；<br/>我何难与耶稣同苦，<br/>因神旨我愿顺服。<br/>主借着复活的能力，<br/>今生在我的灵里，<br/>因此我欢乐着举足，<br/>直走十字架的路。<br/>','',55545,9080);
INSERT INTO stanza VALUES('Z362','3','同主死，就必同主生，<br/>同受苦，必同高升；<br/>得胜者惟独照这样，<br/>才能蒙基督奖赏。<br/>真可乐！若在那早晨，<br/>你听主对你发声，<br/>以为你曾忠心顺服，<br/>直走十字架的路！<br/>','',55546,9081);
INSERT INTO stanza VALUES('Z363','1','与基督同死，<br/>祂死算我死；<br/>与基督同起，<br/>我有祂生命；<br/>与基督同升，<br/>我超过此世；<br/>主，时时刻刻，<br/>我归于你名。<br/>','',55547,9082);
INSERT INTO stanza VALUES('Z363','chorus','我时时刻刻蒙祂爱保守，<br/>我时时刻刻从祂得生命，<br/>我时时刻刻在祂前等候，<br/>我时时刻刻归于祂的名。<br/>','',55548,9083);
INSERT INTO stanza VALUES('Z363','2','没有一试炼，<br/>祂是不同在；<br/>没有一重担，<br/>祂是不与共；<br/>没有一痛苦，<br/>祂是不担代；<br/>我时时刻刻在祂眷顾中。<br/>','',55549,9084);
INSERT INTO stanza VALUES('Z363','3','没有一寂寞、<br/>没有一感伤、<br/>没有一叹息、<br/>没有一郁闷、<br/>没有一艰难，<br/>-但在宝座上，<br/>祂时时刻刻思念祂的人。<br/>','',55550,9085);
INSERT INTO stanza VALUES('Z363','4','没有一软弱，<br/>祂不曾扶助；<br/>没有一疾病，<br/>祂不能医治；<br/>哦，时时刻刻，<br/>无论乐或苦，<br/>耶稣我救主，<br/>与我同行止。<br/>','',55551,9086);
INSERT INTO stanza VALUES('Z364','1','与主同葬，也一同复活，<br/>还有甚么留给我去作？<br/>只要我不再奋斗击空，<br/>只要我照新生而举动。<br/>荣耀归于神！<br/>','',55552,9087);
INSERT INTO stanza VALUES('Z364','2','与主我的元首同复活，<br/>我今在圣洁路上走着；<br/>当我向前时，我就想到：<br/>『死的人脱罪』<br/>是何其好！<br/>荣耀归于神！<br/>','',55553,9088);
INSERT INTO stanza VALUES('Z364','3','与主同活，祂永不再死；<br/>与主同行，祂永不会迟；<br/>我天天算自己已经死，<br/>所以我就从捆绑得释。<br/>荣耀归于神！<br/>','',55554,9089);
INSERT INTO stanza VALUES('Z364','4','为主活着，我献上肢体，<br/>永远归神，作祂的奴隶。<br/>我今在恩下，不在法下，<br/>罪已失势，主代兴管辖。<br/>荣耀归于神！<br/>','',55555,9090);
INSERT INTO stanza VALUES('Z364','5','靠主长大，我今真惭愧<br/>再题到我的已往宝贵；<br/>我愿意结出成圣果子，<br/>满足神心意，遵行神旨。<br/>荣耀归于神！<br/>','',55556,9091);
INSERT INTO stanza VALUES('Z365','1','我与基督已同钉死，<br/>十架已将我解释；<br/>我与基督已同复活，<br/>祂生我里，供应我。<br/>','',55557,9092);
INSERT INTO stanza VALUES('Z365','chorus','与基督同死，<br/>何等的安适！<br/>脱世界、自己、罪恶！<br/>与基督同活，<br/>何等的超脱！<br/>祂生我里，供应我。<br/>','',55558,9093);
INSERT INTO stanza VALUES('Z365','2','历世历代所藏奥秘，<br/>今借信心可知悉：<br/>荣耀盼望-基督居衷，<br/>应当无时不歌颂。<br/>','',55559,9094);
INSERT INTO stanza VALUES('Z365','3','天然景物都有隐征：<br/>麦种死了子粒生；<br/>贱木接在珍树上面，<br/>小则变大，苦变甜。<br/>','',55560,9095);
INSERT INTO stanza VALUES('Z365','4','这个就是圣洁秘诀-<br/>不是自己无残缺；<br/>主阿，求你虚我、满我，<br/>扩我度量给我多。<br/>','',55561,9096);
INSERT INTO stanza VALUES('Z365','5','这个会使病痛得治-<br/>只要你向自己死，<br/>并以主的生命能力<br/>作为全人的供给。<br/>','',55562,9097);
INSERT INTO stanza VALUES('Z365','6','经过十架，达到宝座，<br/>主是这样的领率，<br/>先是死亡，后是荣耀，<br/>主既如此我倣效。<br/>','',55563,9098);
INSERT INTO stanza VALUES('Z366','1','基督虽能千回<br/>降生于伯利恒，<br/>若未活你心内，<br/>救恩仍是无成。<br/>各各他的十架，<br/>还不会拯救你；<br/>在你里的十架，<br/>才有能医治你。<br/>','',55564,9099);
INSERT INTO stanza VALUES('Z366','chorus','哦！基督的十字架，<br/>我接你进我心，<br/>使我脱自己管辖，<br/>完全凭主而生存。<br/>','',55565,9100);
INSERT INTO stanza VALUES('Z366','2','人哪！你爱何物，<br/>你就变成该物：<br/>成神，你若爱神；<br/>成尘，你若爱尘；<br/>你出，神就进入；<br/>你死，神就生苏；<br/>无你，就有基督；<br/>无物，就得万物。<br/>','',55566,9101);
INSERT INTO stanza VALUES('Z366','3','你若要得着神，<br/>切勿跟从智慧；<br/>『爱』是最短路径，<br/>使你免去纡回。<br/>你若不为自己<br/>寻求甚么利益，<br/>神的荣耀自己，<br/>就要充满了你。<br/>','',55567,9102);
INSERT INTO stanza VALUES('Z367','1','主，你所有一切工作，<br/>并非到了十架为止；<br/>你今乃是仍旧生活，<br/>从你另一形态表示。<br/>','',55568,9103);
INSERT INTO stanza VALUES('Z367','2','你今仍旧施行拯救，<br/>仍旧说话，仍旧引导；<br/>你今成灵，仍在涌流，<br/>仍旧光照，使人仆倒。<br/>','',55569,9104);
INSERT INTO stanza VALUES('Z367','3','你成那灵，不停能力，<br/>你成那灵，不停运行，<br/>你的感动、你的鼓励；<br/>你仍安慰，你仍命令。<br/>','',55570,9105);
INSERT INTO stanza VALUES('Z367','4','因为你已成为那灵，<br/>祂来就是你又来地，<br/>祂的内住是你充盈，<br/>祂是你灵，祂又是你。<br/>','',55571,9106);
INSERT INTO stanza VALUES('Z367','5','祂今在我的心执行<br/>你的一切命令、希冀；<br/>有如从前你在世境，<br/>执行父的所有旨意。<br/>','',55572,9107);
INSERT INTO stanza VALUES('Z367','6','我们识祂就是识你，<br/>服祂就是服你旨意；<br/>我们被祂渗透、洋溢，<br/>就是充满你的自己。<br/>','',55573,9108);
INSERT INTO stanza VALUES('Z367','7','你今不是远在高天，<br/>不是一去就不复返，<br/>乃是仍旧在这世间，<br/>奇哉！并住在我心坎。<br/>','',55574,9109);
INSERT INTO stanza VALUES('Z368','1','主，当无人认识父时，<br/>父在你里借你来地，<br/>好叫我们虽然无知，<br/>如要识父只要认你。<br/>','',55575,9110);
INSERT INTO stanza VALUES('Z368','2','但是，当你在世时候，<br/>识你的人何等的少！<br/>与你好像间隔很厚，<br/>虽在挤你，摸你不到。<br/>','',55576,9111);
INSERT INTO stanza VALUES('Z368','3','你今成为那灵再来，<br/>有如当初父显于你，<br/>我要识父是看父怀，<br/>我要识你在于灵力。<br/>','',55577,9112);
INSERT INTO stanza VALUES('Z368','4','你今不是披前肉体，<br/>四处奔波劳碌不息，<br/>你今乃是住我灵里，<br/>时刻用灵供应自己。<br/>','',55578,9113);
INSERT INTO stanza VALUES('Z368','5','曾有一次你就是父，<br/>现今的你就是圣灵，<br/>祂是你的另一态度，<br/>祂是你的第二情形。<br/>','',55579,9114);
INSERT INTO stanza VALUES('Z368','6','我今因为认识圣灵，<br/>我就认识你的荣耀、<br/>你的性情和你生命，<br/>认识你的本质奇妙。<br/>','',55580,9115);
INSERT INTO stanza VALUES('Z368','7','赞美你名，我们的心<br/>认识你是何等实在；<br/>没有亲的比你可亲，<br/>没有爱的比你可爱。<br/>','',55581,9116);
INSERT INTO stanza VALUES('Z369','1','当你住在肉身生命，<br/>知我识你至不深刻，<br/>你就定规成为那灵，<br/>要在我灵启示明白。<br/>','',55582,9117);
INSERT INTO stanza VALUES('Z369','2','从前你是我救赎主，<br/>现今你是我保惠师，<br/>不再是那外面接触，<br/>乃是里面合一不弛。<br/>','',55583,9118);
INSERT INTO stanza VALUES('Z369','3','我今因你所成圣灵，<br/>住在灵里不断启示<br/>你的自己、你的性情，<br/>觉你同在，感你真实。<br/>','',55584,9119);
INSERT INTO stanza VALUES('Z369','4','我能认识你的生命，<br/>远超当日门徒经历；<br/>虽然他们与你同行、<br/>同食、同住、<br/>同劳、同息。<br/>','',55585,9120);
INSERT INTO stanza VALUES('Z369','5','哦主，成为内住圣灵，<br/>你是何等实在、实在！<br/>不摸，比摸更为可凭；<br/>不见，但已心中深爱。<br/>','',55586,9121);
INSERT INTO stanza VALUES('Z369','6','圣灵现今是从衷里，<br/>时刻将你供应给我，<br/>作我救赎、圣洁、公义，<br/>作我智慧和我结果。<br/>','',55587,9122);
INSERT INTO stanza VALUES('Z369','7','因你成灵，住我灵里，<br/>将你供应，与我合一，<br/>时时刻刻是我自己，<br/>时时刻刻也都是你。<br/>','',55588,9123);
INSERT INTO stanza VALUES('Z370','1','哦，主耶稣，当你在地，<br/>他们与你多年同处；<br/>但是他们对你自己，<br/>似识不识，似悟不悟。<br/>','',55589,9124);
INSERT INTO stanza VALUES('Z370','2','他们听过你的声音，<br/>他们见过你的丰姿，<br/>他们挤过你的肉身，<br/>但你是谁，似知不知。<br/>','',55590,9125);
INSERT INTO stanza VALUES('Z370','3','我们好像盖重幔子，<br/>彷佛知道，又不透明，<br/>说不认识，早已认识，<br/>说已认识，认识不清。<br/>','',55591,9126);
INSERT INTO stanza VALUES('Z370','4','但你今已化身那灵，<br/>成为另一位保惠师，<br/>带着你的所有丰盛，<br/>在我里面将你启示。<br/>','',55592,9127);
INSERT INTO stanza VALUES('Z370','5','愿你这灵浸透充满<br/>在我全人每一角落，<br/>没有一处不受你感，<br/>没有一处不被你摸。<br/>','',55593,9128);
INSERT INTO stanza VALUES('Z370','6','求你这灵向我显现，<br/>加倍实在，在我心怀；<br/>无耳所听，无目所见，<br/>无手所摸，如此实在。<br/>','',55594,9129);
INSERT INTO stanza VALUES('Z370','7','当你怜悯，肯来启示，<br/>将你自己给了我们，<br/>世上有谁比你更实？<br/>世上有何比你更真？<br/>','',55595,9130);
INSERT INTO stanza VALUES('Z370','7','求你这灵从我的灵，<br/>如同洪水漫溢全人：<br/>到处荣耀，到处光明，<br/>到处是你，到处是神。<br/>','',55596,9131);
INSERT INTO stanza VALUES('Z370','9','这个生活何等亲近！<br/>你使我已在地若天：<br/>赞美满口，喜乐满心，<br/>同在满魂，一切甘甜。<br/>','',55597,9132);
INSERT INTO stanza VALUES('Z371','1','哦主，你今乃是那灵，<br/>将我点活、赐我生命；<br/>用你丰富将我供应，<br/>何其荣耀、何其神圣！<br/>','',55598,9133);
INSERT INTO stanza VALUES('Z371','2','哦主，你今乃是那灵，<br/>用你大能将我释放；<br/>生命之律，规律、节制，<br/>使我自由、使我刚强。<br/>','',55599,9134);
INSERT INTO stanza VALUES('Z371','3','哦主，你今乃是那灵，<br/>将我变化、使我透亮；<br/>将我模成你的形像，<br/>使我返照你的荣光。<br/>','',55600,9135);
INSERT INTO stanza VALUES('Z371','4','哦主，你今乃是那灵，<br/>居住、生活在我灵里；<br/>你灵借着我灵行动，<br/>二灵相调，化合为一。<br/>','',55601,9136);
INSERT INTO stanza VALUES('Z371','5','求主教我如何操练、<br/>运用我灵与你接触；<br/>使我活在你的灵里，<br/>凭你实际将你活出。<br/>','',55602,9137);
INSERT INTO stanza VALUES('Z372','1','基督是神的中心，<br/>祂也是神的普及；<br/>祂从永远到永远，<br/>是神心爱与欢喜。<br/>','',55603,9138);
INSERT INTO stanza VALUES('Z372','2','基督是神的化身，<br/>神的丰满住祂里；<br/>祂的尊高与神性，<br/>无人能与祂比拟。<br/>','',55604,9139);
INSERT INTO stanza VALUES('Z372','3','神所计画是为祂，<br/>要祂充满万有中；<br/>天地宇宙的一切，<br/>都是为祂得尊荣。<br/>','',55605,9140);
INSERT INTO stanza VALUES('Z372','4','一切创造全为祂，<br/>万有借着祂而有；<br/>万有也靠祂而立，<br/>祂是中心并圆周。<br/>','',55606,9141);
INSERT INTO stanza VALUES('Z372','5','祂是救赎的一切，<br/>万有借祂得复交；<br/>借祂有效的宝血，<br/>万有得与神和好。<br/>','',55607,9142);
INSERT INTO stanza VALUES('Z372','6','祂是一切的元始，<br/>也是召会永活头，<br/>召会生命及内容，<br/>从死首生的元首。<br/>','',55608,9143);
INSERT INTO stanza VALUES('Z372','7','祂是神国的君王，<br/>执掌所有的权柄；<br/>借祂荣耀来管治，<br/>天地万有全从命。<br/>','',55609,9144);
INSERT INTO stanza VALUES('Z372','7','祂在新天新地里，<br/>要作万有的中心；<br/>为着神性、为着人，<br/>直到永远无穷尽。<br/>','',55610,9145);
INSERT INTO stanza VALUES('Z372','9','神的心意是要祂<br/>能在万有居首位；<br/>这一万有的基督，<br/>现今竟作我美味！<br/>','',55611,9146);
INSERT INTO stanza VALUES('Z373','1','基督是神真实见证，<br/>或在本质、或在言行；<br/>完满显出神的荣耀，<br/>使人看见神的性情。<br/>','',55612,9147);
INSERT INTO stanza VALUES('Z373','2','基督作神完满见证，<br/>远胜律法为神所作；<br/>律法不过只用字句，<br/>非用生命，将神述说。<br/>','',55613,9148);
INSERT INTO stanza VALUES('Z373','3','神性丰满住在基督，<br/>作了祂的内容成分；<br/>祂是神的具体化身，<br/>神的住处、神的器皿。<br/>','',55614,9149);
INSERT INTO stanza VALUES('Z373','4','神的荣耀、神的形像，<br/>基督全都彰显展览；<br/>神的心意、神的道路，<br/>也都在祂给人看见。<br/>','',55615,9150);
INSERT INTO stanza VALUES('Z373','5','基督现今住在我灵，<br/>为作我分直到永久；<br/>我在灵中将祂分享，<br/>神性一切全归我有。<br/>','',55616,9151);
INSERT INTO stanza VALUES('Z374','1','基督是万有惟一的实际，<br/>在神或在人一切同此理；<br/>人在祂以外，<br/>无法寻到神，<br/>除非有祂在，<br/>万有全不真。<br/>','',55617,9152);
INSERT INTO stanza VALUES('Z374','2','一切的形像、<br/>所有的豫表，<br/>并人之所需，<br/>无论大或小，<br/>全都是影儿，<br/>象征神基督，<br/>表明祂是我一切的事物。<br/>','',55618,9153);
INSERT INTO stanza VALUES('Z374','3','万事与万物尽都是虚空，<br/>除非有基督充满在其中；<br/>纵然能得到并享尽一切，<br/>若没有基督，<br/>我仍是空缺。<br/>','',55619,9154);
INSERT INTO stanza VALUES('Z374','4','基督是真神，<br/>基督是真主，<br/>祂是我真光、<br/>是我真事物、<br/>是我真衣食<br/>、是我真活水、<br/>是我真生命、<br/>是我真美味。<br/>','',55620,9155);
INSERT INTO stanza VALUES('Z374','5','所有的神学、<br/>一切的道理，<br/>也都应该有基督作实际；<br/>圣经的知识若缺少基督，<br/>不过是字句，<br/>尽都是虚无。<br/>','',55621,9156);
INSERT INTO stanza VALUES('Z374','6','时间或空间，<br/>基督是实际，<br/>一切的事物，<br/>尽都同此理；<br/>基督是万有惟一的实际，<br/>一直到永远，<br/>此理不更易。<br/>','',55622,9157);
INSERT INTO stanza VALUES('Z375','1','主，你已使你的自己，<br/>成为我们活的实际；<br/>荣耀实际对于信心，<br/>比诸地上任何都真；<br/>可爱实际，其亲其密，<br/>地上最近亲人难比。<br/>','',55623,9158);
INSERT INTO stanza VALUES('Z375','2','有福异象我已看见：<br/>惟有你是我的完全；<br/>你已纯洁我的意愿，<br/>最圣爱火其中点燃；<br/>你已提高我的性情，<br/>充满你的荣耀丰盛。<br/>','',55624,9159);
INSERT INTO stanza VALUES('Z375','3','永活救主，可爱恩人，<br/>对我你要更亲更近；<br/>你的荣面要更光明，<br/>你的恩言要更有能；<br/>爱中要将我全变化，<br/>怜悯、恩典要更增加。<br/>','',55625,9160);
INSERT INTO stanza VALUES('Z376','1','神所赐恩典，<br/>最高的定义，<br/>是神在子里<br/>所给的自己；<br/>不重在事物，<br/>赐于古或今，<br/>乃是神自己<br/>作我的永分。<br/>','',55626,9161);
INSERT INTO stanza VALUES('Z376','2','神成为肉身，<br/>来与人调和，<br/>为给人接受，<br/>而将祂得着；<br/>人借主从神<br/>所得的恩典，<br/>就是主自己<br/>来住我心间。<br/>','',55627,9162);
INSERT INTO stanza VALUES('Z376','3','在使徒保罗，<br/>万事如粪土，<br/>恩典之于他，<br/>只是神基督；<br/>乃借这恩典-<br/>他所经历主，<br/>他为主劳苦，<br/>超过众使徒。<br/>','',55628,9163);
INSERT INTO stanza VALUES('Z376','4','基督在我里，<br/>作我的能力，<br/>乃是真恩典，<br/>够为我赖倚；<br/>这够用恩典<br/>在我的灵里，<br/>时常加我力，<br/>完成神旨意。<br/>','',55629,9164);
INSERT INTO stanza VALUES('Z376','5','这恩典就是<br/>那活的基督<br/>作我的一切，<br/>时将我眷顾。<br/>主，愿我认识<br/>你这真恩典，<br/>享你作恩典，<br/>一直的增添。<br/>','',55630,9165);
INSERT INTO stanza VALUES('Z377','1','荣耀！荣耀！<br/>基督作生命，<br/>荣耀！荣耀！<br/>圣灵来引领，<br/>无力变为有能，<br/>黑暗变光明，<br/>荣耀！荣耀！<br/>基督作生命。<br/>','',55631,9166);
INSERT INTO stanza VALUES('Z377','2','荣耀！荣耀！<br/>靠着主而生，<br/>荣耀！荣耀！<br/>随从灵而行，<br/>失败变为得胜，<br/>叹息变颂称，<br/>荣耀！荣耀！<br/>靠着主而生。<br/>','',55632,9167);
INSERT INTO stanza VALUES('Z378','1','何等生命！何等平安！<br/>基督活在我的里面！<br/>我已与祂同钉十架，<br/>荣耀事实、奇妙救法！<br/>现在活着不再是我，<br/>乃是基督在我活着！<br/>现在活着不再是我，<br/>乃是基督在我活着！<br/>','',55633,9168);
INSERT INTO stanza VALUES('Z378','2','何等快乐！何等安息！<br/>基督成形在我心里！<br/>祂的生命、祂的性情，<br/>在我全人都已组成；<br/>我的一切全都了结，<br/>祂的成分作我一切！<br/>我的一切全都了结，<br/>祂的成分作我一切！<br/>','',55634,9169);
INSERT INTO stanza VALUES('Z378','3','何等荣耀！何等可夸！<br/>总叫基督照常显大！<br/>无论祸、福，<br/>无论生、死，<br/>并无一事叫我羞耻；<br/>任何境遇、一切事故，<br/>都是叫我彰显基督！<br/>任何境遇、一切事故，<br/>都是叫我彰显基督！<br/>','',55635,9170);
INSERT INTO stanza VALUES('Z378','4','何等结果！何等有福！<br/>我能活着就是基督！<br/>祂的心意是我爱好，<br/>祂的荣耀是我发表；<br/>无何可要、无何可宝，<br/>惟有基督是我目标！<br/>无何可要、无何可宝，<br/>惟有基督是我目标！<br/>','',55636,9171);
INSERT INTO stanza VALUES('Z379','1','何等大能！何等大力！<br/>神使基督从死复起，<br/>远超一切，坐在神右，<br/>为我今作万有之首。<br/>浩大能力全为召会，<br/>好使万有尽都来归。<br/>浩大能力全为召会，<br/>好使万有尽都来归。<br/>','',55637,9172);
INSERT INTO stanza VALUES('Z379','2','何等事实！何等奥秘！<br/>我今乃是基督肢体；<br/>与众圣徒彼此相调，<br/>新人里面同被建造；<br/>联于我们升天元首，<br/>作祂身体，照神所筹。<br/>联于我们升天元首，<br/>作祂身体，照神所筹。<br/>','',55638,9173);
INSERT INTO stanza VALUES('Z379','3','何等高、深！<br/>何等长、阔！<br/>其度、其量无法测度！<br/>神的基督无限、无量，<br/>广大无边，超人所想。<br/>凡祂所是和祂所有，<br/>都是为将召会成就。<br/>凡祂所是和祂所有，<br/>都是为将召会成就。<br/>','',55639,9174);
INSERT INTO stanza VALUES('Z380','1','荣耀！荣耀！荣耀生命！<br/>荣耀生命是基督！<br/>圣洁、公义、<br/>良善、光明！<br/>哦，这生命何丰富！<br/>神性一切荣耀、丰盛，<br/>在祂里面全藏着；<br/>祂今竟是我的生命，<br/>在我里面供应我。<br/>','',55640,9175);
INSERT INTO stanza VALUES('Z380','2','神圣！神圣！神圣生命！<br/>神圣生命是基督！<br/>祂已化身成为圣灵，<br/>到我里面来居住。<br/>感动、运行、<br/>光照、教训，<br/>如同膏油在涂抹，<br/>充满、浇灌、<br/>加力、滋润，<br/>在我里面供应我。<br/>','',55641,9176);
INSERT INTO stanza VALUES('Z380','3','大能！大能！大能生命！<br/>大能生命是基督！<br/>祂已带我与祂同钉，<br/>使我不再作罪奴。<br/>祂也带我同祂复生，<br/>使我和祂同活着，<br/>经历祂的复活大能，<br/>在我里面供应我。<br/>','',55642,9177);
INSERT INTO stanza VALUES('Z380','4','得胜！得胜！得胜生命！<br/>得胜生命是基督！<br/>祂在十架已经得胜，<br/>使我不再作俘虏。<br/>撒但、鬼魔、<br/>世界、人情，<br/>祂都为我全胜过；<br/>今来作我得胜生命，<br/>在我里面供应我。<br/>','',55643,9178);
INSERT INTO stanza VALUES('Z380','5','荣耀！神圣！大能生命！<br/>得胜生命是基督！<br/>使我刚强，使我得胜，<br/>使我长大并成熟；<br/>使我变质，使我像祂，<br/>使我自由且超脱；<br/>直到那日被提变化，<br/>在我里面供应我。<br/>','',55644,9179);
INSERT INTO stanza VALUES('Z381','1','主，你是我生命，<br/>活在我里面；<br/>带着神的丰盛，<br/>来将我充满。<br/>你的圣别性情，<br/>使我能成圣；<br/>你的复活大能，<br/>使我能得胜。<br/>','',55645,9180);
INSERT INTO stanza VALUES('Z381','2','你这生命流通，<br/>我就蒙光照，<br/>使我活在光中，<br/>与你能相交；<br/>带来各种供应，<br/>也有所要求，<br/>使我得蒙洁净，<br/>享受你所有。<br/>','',55646,9181);
INSERT INTO stanza VALUES('Z381','3','你是那灵运行，<br/>像膏油涂抹，<br/>将我心思、心、灵，<br/>全都浸润过，<br/>使我全人变化，<br/>成为你形状，<br/>直到成熟长大，<br/>满有你身量。<br/>','',55647,9182);
INSERT INTO stanza VALUES('Z381','4','你的生命成分，<br/>成为我丰富，<br/>时常将我滋润，<br/>使我得复苏。<br/>生命吞灭死亡，<br/>软弱变刚强；<br/>释放消除捆绑，<br/>下沉变高昂。<br/>','',55648,9183);
INSERT INTO stanza VALUES('Z381','5','因此我将自己，<br/>完全献给你，<br/>照着你的心意，<br/>活在交通里；<br/>不再立志挣扎，<br/>不再改自己，<br/>使你受到打岔，<br/>毫不能为力。<br/>','',55649,9184);
INSERT INTO stanza VALUES('Z381','6','乃是完全停下<br/>自己的努力，<br/>让你运行、变化，<br/>使我脱自己；<br/>与众圣徒配搭，<br/>成为你身体，<br/>让你定居、安家，<br/>彰显你自己。<br/>','',55650,9185);
INSERT INTO stanza VALUES('Z382','1','荣耀基督，亲爱救主，<br/>你是神的荣耀显出！<br/>原是永远无限的神，<br/>竟作时间有限的人。<br/>','',55651,9186);
INSERT INTO stanza VALUES('Z382','chorus','荣耀基督，大神化身，<br/>奥妙、丰富，享受不尽！<br/>圣中之圣，人中之人，<br/>在我灵里作我福分！<br/>','',55652,9187);
INSERT INTO stanza VALUES('Z382','2','神的丰盛藏你里面，<br/>神的荣耀从你彰显；<br/>前在肉身成功救赎，<br/>今成那灵与我联属。<br/>','',55653,9188);
INSERT INTO stanza VALUES('Z382','3','凡父所有全由你承，<br/>凡你所是都归于灵；<br/>灵进我灵作你实际，<br/>使你成为我的经历。<br/>','',55654,9189);
INSERT INTO stanza VALUES('Z382','4','灵今借你生命活话，<br/>在我里面将你实化；<br/>接受这话，接触这灵，<br/>你就作了我的供应。<br/>','',55655,9190);
INSERT INTO stanza VALUES('Z382','5','灵里敬拜，灵里瞻仰，<br/>如镜返照你的荣光，<br/>我就变成你的形状，<br/>使你从我得着显彰。<br/>','',55656,9191);
INSERT INTO stanza VALUES('Z382','6','惟有如此才能成圣，<br/>必须如此才能得胜；<br/>舍此无法摸着生命，<br/>舍此无路可以属灵。<br/>','',55657,9192);
INSERT INTO stanza VALUES('Z382','7','借此你灵浸透全人，<br/>到处是你，到处是神！<br/>我就脱离天然自我，<br/>与众圣徒作神居所。<br/>','',55658,9193);
INSERT INTO stanza VALUES('Z383','1','荣耀之中有一位，<br/>乃是神而人；<br/>圣洁、公义又智慧，<br/>光明且慈仁；<br/>祂曾为我舍生命，<br/>成功神救法，<br/>使我能有祂性情，<br/>使我能像祂。<br/>','',55659,9194);
INSERT INTO stanza VALUES('Z383','2','荣耀之中有一位，<br/>乃是得胜王；<br/>黑暗权势祂摧毁，<br/>撒但祂击伤，<br/>冲破阴府升天庭，<br/>远超诸执政，<br/>使我与祂同高升，<br/>与祂同夸胜。<br/>','',55660,9195);
INSERT INTO stanza VALUES('Z383','3','荣耀之中有一位，<br/>祂是我生命；<br/>时刻住在我心内，<br/>管理并引领，<br/>使祂圣洁的性情，<br/>成形在我心，<br/>使祂荣耀的生命，<br/>彰显于我身。<br/>','',55661,9196);
INSERT INTO stanza VALUES('Z383','4','荣耀之中有一位，<br/>祂是我盼望；<br/>不久从天必归回，<br/>接我到天上，<br/>用祂荣耀的大能，<br/>改变我形状，<br/>使我变成祂荣形，<br/>与祂永相像。<br/>','',55662,9197);
INSERT INTO stanza VALUES('Z384','1','一棵果树、一道水河，<br/>二者乃是乐园特色，<br/>供人饮食、解人饥渴，<br/>使人神前活着。<br/>','',55663,9198);
INSERT INTO stanza VALUES('Z384','chorus','神在基督里作人食粮，<br/>基督成为灵供人营养；<br/>这无限之灵给我饱尝，<br/>我就将神全享。<br/>','',55664,9199);
INSERT INTO stanza VALUES('Z384','2','果树乃指荣耀基督，<br/>来作人的生命食物，<br/>使人享受神的丰富，<br/>人就得到满足。<br/>','',55665,9200);
INSERT INTO stanza VALUES('Z384','3','水河乃指无限之灵，<br/>来作人的灵性供应，<br/>使人饱尝神的丰盛，<br/>人就成为神圣。<br/>','',55666,9201);
INSERT INTO stanza VALUES('Z384','4','荣耀基督作我生命，<br/>成为那灵活在我灵，<br/>使我调进神的性情，<br/>有分神的荣形。<br/>','',55667,9202);
INSERT INTO stanza VALUES('Z384','5','荣耀基督我肯尊崇，<br/>无限之灵我肯顺从，<br/>我就显出神的光荣，<br/>恩荣世世无穷！<br/>','',55668,9203);
INSERT INTO stanza VALUES('Z385','1','主阿，你是吗哪，<br/>已经从天降下；<br/>来作我的食物，<br/>使我得着饱足。<br/>','',55669,1);
INSERT INTO stanza VALUES('Z385','2','你是磐石裂破，<br/>流出活水为我；<br/>随时我都可喝，<br/>使我免去干渴。<br/>','',55670,2);
INSERT INTO stanza VALUES('Z385','3','现在我来就你，<br/>因我又渴又饥；<br/>用你自己喂我，<br/>给我活水解渴。<br/>','',55671,3);
INSERT INTO stanza VALUES('Z385','4','我愿吃你、喝你，<br/>吸取你的自己；<br/>饱尝你的生命，<br/>畅饮你的圣灵。<br/>若非如此吸取，<br/>就难免去空虚；<br/>如此吃你、喝你，<br/>才能生活有力。<br/>','',55672,4);
INSERT INTO stanza VALUES('Z386','1','基督就是我的世界：<br/>生命、喜乐、一切！<br/>祂是我力，时时提挈，<br/>离祂我就仆跌。<br/>当我愁苦我来就祂，<br/>无人如此安抚接纳；<br/>使我心乐，解我心忧，<br/>祂是我友！<br/>','',55673,9208);
INSERT INTO stanza VALUES('Z386','2','基督就是我的世界：<br/>百般试炼之助，<br/>处处照护，事事体贴，<br/>一再向我赐福。<br/>祂赐日光，又赐甘霖，<br/>祂赐收获，金谷丰稔；<br/>日光甘霖，金谷丰收，<br/>祂是我友！<br/>','',55674,9209);
INSERT INTO stanza VALUES('Z386','3','基督就是我的世界，<br/>对祂我必效忠！<br/>我怎能够将祂弃绝，<br/>当祂施恩重重？<br/>随祂行走，必不会错，<br/>有祂引领，昼夜无辍；<br/>随祂行走，夜以继昼，<br/>祂是我友！<br/>','',55675,9210);
INSERT INTO stanza VALUES('Z386','4','基督就是我的世界，<br/>更好朋友无需；<br/>我愿与祂完全联结，<br/>直到永世不渝。<br/>美丽生命，配此良友，<br/>美丽生命，直到永久；<br/>永久生命，永久逍游，<br/>祂是我友！<br/>','',55676,9211);
INSERT INTO stanza VALUES('Z387','1','无论罪恶如何深剧，<br/>无论道路如何崎岖，<br/>无论境遇如何可虑，<br/>主，你总是够用！<br/>','',55677,9212);
INSERT INTO stanza VALUES('Z387','2','遇到试炼，无论大小，<br/>有了罣虑，无论多少，<br/>即使脚步尽都跌倒，<br/>主，你总是够用！<br/>','',55678,9213);
INSERT INTO stanza VALUES('Z387','3','属地事物悦意称心，<br/>光天化日路途平顺，<br/>安逸竟成遮光之云，<br/>主，你当然够用！<br/>','',55679,9214);
INSERT INTO stanza VALUES('Z387','4','即使忧苦终日为患，<br/>失望、灰心、前途黑暗，<br/>心麻、灵木、欲祷无言，<br/>主，你仍是够用！<br/>','',55680,9215);
INSERT INTO stanza VALUES('Z387','5','不论我的环境如何，<br/>你手都在将我托着，<br/>使我经历你之于我，<br/>乃是全足之主！<br/>','',55681,9216);
INSERT INTO stanza VALUES('Z388','1','我已得到宇宙至宝，<br/>我心因此欢呼；<br/>欢呼基督给我得到，<br/>何等一位基督！<br/>','',55682,9217);
INSERT INTO stanza VALUES('Z388','2','我这基督是神羔羊，<br/>担当我的罪愆；<br/>又是神的公义太阳，<br/>发出医治光线。<br/>','',55683,9218);
INSERT INTO stanza VALUES('Z388','3','我这基督是生命树，<br/>长在神的乐园；<br/>祂的美果作我食物，<br/>供应丰富、甘甜。<br/>','',55684,9219);
INSERT INTO stanza VALUES('Z388','4','我这基督是生命泉，<br/>流出活水江河；<br/>在我里面流到永远，<br/>解除一切干渴。<br/>','',55685,9220);
INSERT INTO stanza VALUES('Z388','5','我这基督是我祭司，<br/>为我显在神前，<br/>也是先知满有启示，<br/>且是君王掌权。<br/>','',55686,9221);
INSERT INTO stanza VALUES('Z388','6','是我救主、中保、大夫、<br/>牧人、策士、元首、<br/>我兄、我父、<br/>我神、我主、<br/>师尊、良人、密友。<br/>','',55687,9222);
INSERT INTO stanza VALUES('Z388','7','是我生命、能力、智慧：<br/>公义、圣洁、救赎；<br/>平安、喜乐、<br/>盼望、安慰、<br/>荣耀、亮光、道路。<br/>','',55688,9223);
INSERT INTO stanza VALUES('Z388','7','我这基督充满万有，<br/>怎能述尽说竭？<br/>祂是首先、祂是末后、<br/>祂是一切一切！<br/>','',55689,9224);
INSERT INTO stanza VALUES('Z388','9','我既得到这样至宝，<br/>我心怎不欢呼！<br/>欢呼基督给我得到，<br/>何等一位基督！<br/>','',55690,9225);
INSERT INTO stanza VALUES('Z389','1','今世福乐没灭，<br/>基督属我！<br/>地上爱情断绝，<br/>基督属我！<br/>在此幽暗野地，<br/>无处可以安息，<br/>惟有基督可倚，<br/>基督属我！<br/>','',55691,9226);
INSERT INTO stanza VALUES('Z389','2','莫诱我心离开，<br/>基督属我！<br/>我愿与主同在，<br/>基督属我！<br/>你这今世欢娱，<br/>一时骗人之局，<br/>从我心中离去，<br/>基督属我！<br/>','',55692,9227);
INSERT INTO stanza VALUES('Z389','3','去罢，今世幻梦，<br/>基督属我！<br/>我今已经清醒，<br/>基督属我！<br/>凡我从前所慕，<br/>不过使我痛苦；<br/>惟主使我满足，<br/>基督属我！<br/>','',55693,9228);
INSERT INTO stanza VALUES('Z389','4','去罢，短暂今时，<br/>基督属我！<br/>来罢，长久永世，<br/>基督属我！<br/>来罢，可爱福气！<br/>来罢，甜美安息！<br/>来罢，恩主自己！<br/>基督属我！<br/>','',55694,9229);
INSERT INTO stanza VALUES('Z390','1','耶稣，我救主，<br/>祂是我一切！<br/>奇妙的救主，<br/>何等的可悦！<br/>引导和保护，<br/>所有安度过，<br/>大能的救主-<br/>耶稣为我。<br/>','',55695,9230);
INSERT INTO stanza VALUES('Z390','chorus','耶稣为我！耶稣为我！<br/>每时候，每处所，<br/>耶稣为我！<br/>','',55696,9231);
INSERT INTO stanza VALUES('Z390','2','耶稣于康健，<br/>耶稣于病痛，<br/>耶稣于富裕，<br/>或是于贫穷，<br/>无论是日光，<br/>无论是风波，<br/>祂是我平安-<br/>耶稣为我。<br/>','',55697,9232);
INSERT INTO stanza VALUES('Z390','3','祂是我磐石、<br/>堡垒和盾牌，<br/>祂是我生命、<br/>亮光和高台，<br/>我的保护者、<br/>我的避难所、<br/>我的救赎主-<br/>耶稣为我。<br/>','',55698,9233);
INSERT INTO stanza VALUES('Z390','4','祂是我先知、<br/>祭司和君王、<br/>我的生命泉、<br/>我的生命粮；<br/>祂是我信实<br/>和我的寄托、<br/>我的拯救角-<br/>耶稣为我。<br/>','',55699,9234);
INSERT INTO stanza VALUES('Z390','5','耶稣于喜乐、<br/>或是于痛苦，<br/>损失或利益，<br/>祂是我宝库；<br/>无论在何处，<br/>祂顾我软弱，<br/>留世或离世-<br/>耶稣为我。<br/>','',55700,9235);
INSERT INTO stanza VALUES('Z391','1','你这『恬静』隐密之源，<br/>你这神圣全足的爱；<br/>是我帮助，是我靠山，<br/>我的安全是你同在；<br/>我从一切忧困、罪缠，<br/>前来藏身在你里面。<br/>','',55701,9236);
INSERT INTO stanza VALUES('Z391','2','你是我的一切需要，<br/>劳中之息，苦中之逸；<br/>你是敷我伤心之膏，<br/>乱时之安，损时之益；<br/>受虐之时，是我笑脸；<br/>蒙羞之时，是我冠冕。<br/>','',55702,9237);
INSERT INTO stanza VALUES('Z391','3','缺乏之时，是我供给；<br/>受困之时，是我释放；<br/>软弱之时，是我能力；<br/>黑暗之时，是我亮光；<br/>愁苦之时，是我喜乐；<br/>死亡之中，是我复活。<br/>','',55703,9238);
INSERT INTO stanza VALUES('Z391','4','你这『恬静』隐密之源，<br/>你这神圣全足的爱，<br/>我愿藏身在你里面，<br/>享受你的甜美同在：<br/>你是我的一切一切，<br/>享受不尽、取用不竭！<br/>','',55704,9239);
INSERT INTO stanza VALUES('Z392','1','祂是一切最亲-<br/>我所一切最爱；<br/>人生平常所寻，<br/>人生终久所赖。<br/>','',55705,9240);
INSERT INTO stanza VALUES('Z392','2','缺乏之时豫备，<br/>无倚之时扶持，<br/>所有美时，最美，<br/>无论何时，信实。<br/>','',55706,9241);
INSERT INTO stanza VALUES('Z392','3','无穷喜乐，原因，<br/>年日移换，不改；<br/>祂是一切最亲-<br/>我所一切最爱。<br/>','',55707,9242);
INSERT INTO stanza VALUES('Z393','1','祂是乐中之乐，<br/>祂已解我干渴；<br/>祂是歌中之歌，<br/>祂今消我寂寞。<br/>','',55708,9243);
INSERT INTO stanza VALUES('Z393','2','祂是美中之美，<br/>合我人生口味；<br/>祂是贵中之贵，<br/>是我无上宝贝。<br/>','',55709,9244);
INSERT INTO stanza VALUES('Z393','3','祂是命中之命，<br/>使我从死复生；<br/>祂是圣中之圣，<br/>使我与世不并。<br/>','',55710,9245);
INSERT INTO stanza VALUES('Z393','4','祂是义中之义，<br/>使我神前站立；<br/>祂是力中之力，<br/>使我路中不疲。<br/>','',55711,9246);
INSERT INTO stanza VALUES('Z393','5','祂是能中之能，<br/>使我如鹰上腾；<br/>祂是胜中之胜，<br/>使我得占上风。<br/>','',55712,9247);
INSERT INTO stanza VALUES('Z393','6','祂是强中之强，<br/>将我全人释放；<br/>祂是壮中之壮，<br/>使我心灵坚刚。<br/>','',55713,9248);
INSERT INTO stanza VALUES('Z393','7','祂是王中之王，<br/>祂今作我心皇；<br/>祂是光中之光，<br/>时时使我明亮。<br/>','',55714,9249);
INSERT INTO stanza VALUES('Z393','7','祂是主中之主，<br/>祂今住我心府；<br/>祂是路中之路，<br/>处处引我脚步。<br/>','',55715,9250);
INSERT INTO stanza VALUES('Z393','9','祂是医中之医，<br/>医我灵、魂、身体；<br/>祂是奇中之奇，<br/>使我荣耀无比。<br/>','',55716,9251);
INSERT INTO stanza VALUES('Z393','10','祂是望中之望，<br/>吸我心情向上；<br/>祂是赏中之赏，<br/>引我脚步前往。<br/>','',55717,9252);
INSERT INTO stanza VALUES('Z393','11','祂是爱中之爱，<br/>配我全心感戴；<br/>祂是耐中之耐，<br/>配我永远敬拜。<br/>','',55718,9253);
INSERT INTO stanza VALUES('Z393','12','祂是雄中之雄，<br/>惟祂配我尊崇；<br/>祂是荣中之荣，<br/>惟祂配我称颂。<br/>','',55719,9254);
INSERT INTO stanza VALUES('Z394','1','前要的是祝福，<br/>今要主自己；<br/>前要的是医治，<br/>今要主而已；<br/>前我贪求恩赐，<br/>今要赐恩者；<br/>前我寻求能力，<br/>今要全能者。<br/>','',55720,9255);
INSERT INTO stanza VALUES('Z394','chorus','永远举起耶稣，<br/>赞美主不歇；<br/>一切在于基督，<br/>主是我一切。<br/>','',55721,9256);
INSERT INTO stanza VALUES('Z394','2','前常用手抓主，<br/>今主手牵我；<br/>前常无所适从，<br/>今抛锚稳妥；<br/>前是宝贵感觉，<br/>今凭主口说；<br/>前是频频苦试，<br/>今完全信托。<br/>','',55722,9257);
INSERT INTO stanza VALUES('Z394','3','前是忙于打算，<br/>今则靠祈求；<br/>前是悬切罣虑，<br/>今则主担忧；<br/>前随我之所欲，<br/>今听主支配；<br/>前不住的讨问，<br/>今不断赞美。<br/>','',55723,9258);
INSERT INTO stanza VALUES('Z394','4','前我欲利用主，<br/>今则主用我；<br/>前是我的事业，<br/>今为主工作；<br/>前欲得人称赞，<br/>今求主欢喜；<br/>前不过半得救，<br/>今被救到底。<br/>','',55724,9259);
INSERT INTO stanza VALUES('Z394','5','前羡慕得着主，<br/>今知主属我；<br/>前我灯将熄灭，<br/>今则光炳烁；<br/>前所望的是死，<br/>今等候被提；<br/>我所有的一切，<br/>都在主自己。<br/>','',55725,9260);
INSERT INTO stanza VALUES('Z395','1','惟有耶稣是我题目，<br/>我的信息是耶稣；<br/>惟有耶稣是我歌赋，<br/>我所仰望是耶稣。<br/>','',55726,9261);
INSERT INTO stanza VALUES('Z395','chorus','惟有耶稣，永是耶稣，<br/>我们歌颂这耶稣，<br/>祂是救主、生命、大夫，<br/>祂是君王建国度。<br/>','',55727,9262);
INSERT INTO stanza VALUES('Z395','2','惟有耶稣是我救主，<br/>担当我的所有罪，<br/>一次成功永远救赎，<br/>使我得以蒙恩惠。<br/>','',55728,9263);
INSERT INTO stanza VALUES('Z395','3','惟有耶稣是我生命，<br/>救我脱离罪与己；<br/>惟有耶稣用祂圣灵，<br/>充满我心作我力。<br/>','',55729,9264);
INSERT INTO stanza VALUES('Z395','4','惟有耶稣是我大夫，<br/>担当我的病与疾；<br/>复活生命、升天丰富，<br/>祂都分赐祂肢体。<br/>','',55730,9265);
INSERT INTO stanza VALUES('Z395','5','惟有耶稣是我能力，<br/>是祂赐下五旬节；<br/>哦主，求你使我得以<br/>充满圣灵常胜捷。<br/>','',55731,9266);
INSERT INTO stanza VALUES('Z395','6','我们现在等候耶稣，<br/>要听祂来的招呼；<br/>但是始终惟有耶稣，<br/>惟有耶稣万有主。<br/>','',55732,9267);
INSERT INTO stanza VALUES('Z396','1','当我不见基督容华，<br/>时间何等无味、可厌！<br/>甘甜的鸟、甘甜的花，<br/>对我就不再是甘甜；<br/>可爱太阳如失光线，<br/>田野枉欲表现欢喜；<br/>当我快乐在祂里面，<br/>阴霾也如晴空美丽。<br/>','',55733,9268);
INSERT INTO stanza VALUES('Z396','2','祂名发出最美香味，<br/>祂声成为最甜音乐，<br/>祂的同在展我愁眉，<br/>使我里面尽都欢悦；<br/>祂若如此不断亲密，<br/>我就无何可怕、可求，<br/>无人快乐与我可比，<br/>我的春日长年常有。<br/>','',55734,9269);
INSERT INTO stanza VALUES('Z396','3','看见祂面我就甘甜，<br/>我就只求祂的欢喜，<br/>不论时地有何改变，<br/>不能改变我的心意；<br/>只要感觉祂的爱恋，<br/>宫殿也成可笑玩具，<br/>监狱可成荣耀宫殿，<br/>如果基督和我同居。<br/>','',55735,9270);
INSERT INTO stanza VALUES('Z396','4','我主，若我真是属你，<br/>你若是我诗歌、太阳，<br/>请问为何我仍忧悒？<br/>为何严冬这样久长？<br/>或将黑云赶离我天，<br/>恢复你的欢乐同在；<br/>或接我到你的面前，<br/>无冬昏昧，无云叆叇。<br/>','',55736,9271);
INSERT INTO stanza VALUES('Z397','1','基督是我主观经历，<br/>住于我灵作生命；<br/>基督是我一切一切，<br/>我得与祂成一灵。<br/>','',55737,9272);
INSERT INTO stanza VALUES('Z397','chorus','哦，基督是我<br/>主观的经历，<br/>实际、甘甜又丰富！<br/>哦，基督是我<br/>一切的一切，<br/>我的需要全应付！<br/>','',55738,9273);
INSERT INTO stanza VALUES('Z397','2','基督是我主观经历，<br/>时时供我以生命；<br/>生命之灵使我复苏，<br/>天天使我灵高升。<br/>','',55739,9274);
INSERT INTO stanza VALUES('Z397','3','基督是我主观经历，<br/>变化我的魂生命；<br/>更新我的心思、意志，<br/>将我模成祂荣形。<br/>','',55740,9275);
INSERT INTO stanza VALUES('Z397','4','基督是我主观经历，<br/>使我全人都超脱；<br/>借祂生命律的大能，<br/>在我灵中释放我。<br/>','',55741,9276);
INSERT INTO stanza VALUES('Z397','5','基督是我主观经历，<br/>事事作我的准绳，<br/>管理、改正、<br/>规律、引导，<br/>处处予我以调整。<br/>','',55742,9277);
INSERT INTO stanza VALUES('Z397','6','基督是我主观经历，<br/>使我所需无缺欠；<br/>用祂丰富将我供应，<br/>使我得享神丰满。<br/>','',55743,9278);
INSERT INTO stanza VALUES('Z398','1','基督今日于我，<br/>客观也主观；<br/>客观，<br/>祂在天上为我在代辩；<br/>主观，<br/>祂在我里作我的生命，<br/>时刻将祂自己<br/>由衷来供应。<br/>','',55744,9279);
INSERT INTO stanza VALUES('Z398','2','祂在天上<br/>坐在父神的右边，<br/>为我作大祭司<br/>将血献神前；<br/>在天作我中保，<br/>担负我重担，<br/>凭祂爱心、忠诚，<br/>办理我案件。<br/>','',55745,9280);
INSERT INTO stanza VALUES('Z398','3','祂是生命之灵，<br/>住在我灵中，<br/>在此作我生命，<br/>万有且带同；<br/>作我内心力量，<br/>恩惠时供应；<br/>作我里面侍从，<br/>维持以大能。<br/>','',55746,9281);
INSERT INTO stanza VALUES('Z398','4','祂在天上<br/>为我作一得荣人，<br/>作我开路先锋，<br/>幔内显荣身；<br/>在那属天境地，<br/>以祂的自己，<br/>将人带到神里，<br/>人、神得成一。<br/>','',55747,9282);
INSERT INTO stanza VALUES('Z398','5','祂在我里<br/>使我有分神丰满，<br/>祂乃那灵<br/>将神带到我里面；<br/>借着启示，<br/>使神成为我实际，<br/>生命之中，<br/>神、人相调成为一。<br/>','',55748,9283);
INSERT INTO stanza VALUES('Z398','6','升天客观救主，<br/>今住高天上，<br/>不久祂要归回，<br/>众目得观赏；<br/>内住主观基督，<br/>今活我灵里，<br/>不久祂要显出，<br/>改变我贱体。<br/>','',55749,9284);
INSERT INTO stanza VALUES('Z398','7','日子不久要到，<br/>天地要结联，<br/>在新圣城撒冷，<br/>神、人再无间；<br/>在那荣耀时日，<br/>客观与主观<br/>在我相调为一，<br/>完全又永远。<br/>','',55750,9285);
INSERT INTO stanza VALUES('Z399','1','神的心意所喜所爱：<br/>基督启示我灵中；<br/>不是接受外面宗教，<br/>乃让基督来居衷。<br/>','',55751,9286);
INSERT INTO stanza VALUES('Z399','chorus','神的心意所喜所爱：<br/>基督作到我里面；<br/>不是有何外面成就，<br/>乃让基督来扩展。<br/>','',55752,9287);
INSERT INTO stanza VALUES('Z399','2','神的心意所喜所爱：<br/>基督活在我里面；<br/>不是注意外面事工，<br/>乃享基督作恩典。<br/>','',55753,9288);
INSERT INTO stanza VALUES('Z399','3','神的心意所喜所爱：<br/>基督成形我魂间；<br/>不是跟随外面仪式，<br/>乃让基督时加添。<br/>','',55754,9289);
INSERT INTO stanza VALUES('Z399','4','神的心意所喜所爱：<br/>基督安家在心头；<br/>不仅外面对祂事奉，<br/>更让基督全占有。<br/>','',55755,9290);
INSERT INTO stanza VALUES('Z399','5','神的心意所喜所爱：<br/>基督成为我盼望；<br/>不是外面客观荣耀，<br/>乃是基督作荣光。<br/>','',55756,9291);
INSERT INTO stanza VALUES('Z399','6','神的心意所喜所爱：<br/>基督居衷作一切；<br/>不是外面有何得着，<br/>乃有基督作秘诀。<br/>','',55757,9292);
INSERT INTO stanza VALUES('Z400','1','哦主，在我你是生命，<br/>对我也是一切；<br/>何其亲切、何其便利，<br/>永远取用不竭！<br/>','',55758,9293);
INSERT INTO stanza VALUES('Z400','chorus','哦主，你是生命之灵，<br/>对我何亲何近！<br/>亲切、便利，令人赞赏，<br/>又是甜美、常新。<br/>','',55759,9294);
INSERT INTO stanza VALUES('Z400','2','对于我的大小需要，<br/>你是丰富供应；<br/>何其全备、何其充足，<br/>我得应用于灵。<br/>','',55760,9295);
INSERT INTO stanza VALUES('Z400','3','你作膏油涂抹、运行，<br/>时常顾我软弱；<br/>借你能力无限供应，<br/>使我刚强、灵活。<br/>','',55761,9296);
INSERT INTO stanza VALUES('Z400','4','生命之律灵中规律，<br/>使我得享自由；<br/>你的实际所有丰富，<br/>将我全人浸透。<br/>','',55762,9297);
INSERT INTO stanza VALUES('Z400','5','你是与我永远成一，<br/>无比神圣联结；<br/>永远与我成为一灵，<br/>永远不再隔绝。<br/>','',55763,9298);
INSERT INTO stanza VALUES('Z400','6','愿你在我全人居衷，<br/>在我心中安家；<br/>一部一部、荣上加荣，<br/>将我全人变化。<br/>','',55764,9299);
INSERT INTO stanza VALUES('Z401','1','我今得着何等自由，<br/>基督已经释放我！<br/>罪的权势、死的毒钩，<br/>从我身上全脱落！<br/>','',55765,9300);
INSERT INTO stanza VALUES('Z401','chorus','基督使我得胜有余，<br/>仗祂十架我夸胜！<br/>生命大能、圣灵的律，<br/>使我刚强而有能！<br/>','',55766,9301);
INSERT INTO stanza VALUES('Z401','2','基督使我脱离律法，<br/>永远向着律法死；<br/>完全活在恩典之下，<br/>不受律法的挟制。<br/>','',55767,9302);
INSERT INTO stanza VALUES('Z401','3','基督已经定罪了罪，<br/>除掉罪恶的权势；<br/>罪在我身再无地位，<br/>我从罪里得开释。<br/>','',55768,9303);
INSERT INTO stanza VALUES('Z401','4','基督已经将死废去，<br/>显出不坏的生命；<br/>胜过死亡顽强禁拘，<br/>彰显复活的大能。<br/>','',55769,9304);
INSERT INTO stanza VALUES('Z401','5','基督已经毁坏撒但，<br/>审判世界和邪灵；<br/>使我脱离黑暗、死权，<br/>进入光明与生命。<br/>','',55770,9305);
INSERT INTO stanza VALUES('Z401','6','基督赐我够用恩典，<br/>用祂能力覆庇我；<br/>在我软弱显得完全，<br/>使我喜欢夸软弱。<br/>','',55771,9306);
INSERT INTO stanza VALUES('Z402','1','不是字句律法，<br/>乃是生命主，<br/>神愿赐给我们，<br/>救我脱重负；<br/>不是任何道理，<br/>乃是主基督，<br/>使我脱离自己，<br/>不再作罪奴。<br/>','',55772,9307);
INSERT INTO stanza VALUES('Z402','2','任何一种仪式，<br/>任何的教训，<br/>不能点活我灵，<br/>不能变化魂；<br/>乃是活的基督，<br/>赐给我生命，<br/>使我活出神命，<br/>照神所命定。<br/>','',55773,9308);
INSERT INTO stanza VALUES('Z402','3','不是任何哲学，<br/>任何的伦理，<br/>能照基督模出<br/>祂的众肢体；<br/>乃是基督自己，<br/>在我人性里，<br/>借祂复活大能，<br/>作成祂身体。<br/>','',55774,9309);
INSERT INTO stanza VALUES('Z402','4','不是任何宗教，<br/>也非基督教，<br/>能将神旨成就，<br/>够上神所要；<br/>乃是内住基督，<br/>作我的一切，<br/>成全神的心意，<br/>问题全解决。<br/>','',55775,9310);
INSERT INTO stanza VALUES('Z402','5','我们从主所得<br/>恩赐与功用，<br/>全都不能顶替<br/>基督的内容；<br/>必须基督自己<br/>作我的一切，<br/>惟有基督自己<br/>是我之所缺。<br/>','',55776,9311);
INSERT INTO stanza VALUES('Z403','1','哦，我主的神圣丰富，<br/>深阔无人能测透；<br/>神性所有一切丰富，<br/>在祂全归我享受。<br/>','',55777,9312);
INSERT INTO stanza VALUES('Z403','chorus','神圣丰富！荣耀丰富！<br/>基督丰富全为我！<br/>深广无限，人难测度，<br/>却成实际我得着！<br/>','',55778,9313);
INSERT INTO stanza VALUES('Z403','2','哦，我主的神圣丰富，<br/>一切一切全包括：<br/>生命、亮光、<br/>智慧、能力、<br/>医治、平安和喜乐。<br/>','',55779,9314);
INSERT INTO stanza VALUES('Z403','3','完全救赎、丰满救恩、<br/>称义、成圣并释放、<br/>复活大能、升天超越，<br/>神所喜爱的宝藏！<br/>','',55780,9315);
INSERT INTO stanza VALUES('Z403','4','哦，我主的神圣丰富，<br/>乃是神来作一切！<br/>凡神所是并祂所有，<br/>全在我灵被领略。<br/>','',55781,9316);
INSERT INTO stanza VALUES('Z403','5','哦，我主的神圣丰富，<br/>谁能穷知其所有！<br/>长、阔、高、深，<br/>无法测量，<br/>却都作了我享受！<br/>','',55782,9317);
INSERT INTO stanza VALUES('Z403','6','愿我认识我主丰富，<br/>丰满经历神基督；<br/>并与别人共同分享，<br/>使神心满、我意足。<br/>','',55783,9318);
INSERT INTO stanza VALUES('Z404','1','祂带领我，此意何美！<br/>此言充满天上安慰！<br/>处处、事事、<br/>所是、所作，<br/>都有主手来带领我。<br/>','',55784,9319);
INSERT INTO stanza VALUES('Z404','chorus','祂带领我，祂带领我，<br/>祂是亲手在带领我；<br/>不分时地，我都随着，<br/>因祂亲手在带领我。<br/>','',55785,9320);
INSERT INTO stanza VALUES('Z404','2','有时似堕痛苦深渊，<br/>有时似在快乐伊甸；<br/>或遇平顺，或遭风波，<br/>都有主手来带领我。<br/>','',55786,9321);
INSERT INTO stanza VALUES('Z404','3','主阿，愿你紧握我手，<br/>领我一生随你而走；<br/>是福是苦由你定夺，<br/>只要你手来带领我。<br/>','',55787,9322);
INSERT INTO stanza VALUES('Z404','4','等我行完今生路程，<br/>靠你恩典完全得胜；<br/>死河寒波我亦不躲，<br/>因你至终亲手领我。<br/>','',55788,9323);
INSERT INTO stanza VALUES('Z405','1','恩主，我爱你，<br/>我深知你属我；<br/>一切罪中乐，<br/>我为你全摆脱。<br/>你是我救主，<br/>曾流血将我买；<br/>如果我爱你，<br/>主耶稣，是现在！<br/>','',55789,9324);
INSERT INTO stanza VALUES('Z405','2','恩主，我爱你，<br/>因为你先爱我，<br/>为我在加略<br/>将赎价已付妥。<br/>爱你，是因为<br/>荆棘冕你肯戴；<br/>如果我爱你，<br/>主耶稣，是现在！<br/>','',55790,9325);
INSERT INTO stanza VALUES('Z405','3','活着我爱你，<br/>到死了也爱你；<br/>并要赞美你，<br/>只要你给气息。<br/>即是死临到，<br/>我仍然要表白：<br/>如果我爱你，<br/>主耶稣，是现在！<br/>','',55791,9326);
INSERT INTO stanza VALUES('Z405','4','在那无止境<br/>喜乐的荣耀里，<br/>我要在光中<br/>到永远敬拜你；<br/>头戴荣耀冕，<br/>我还要唱出来：<br/>如果我爱你，<br/>主耶稣，是现在。<br/>','',55792,9327);
INSERT INTO stanza VALUES('Z406','1','交通何甜美，<br/>喜乐何丰盈，<br/>安息在那永久膀臂中；<br/>福气何全备，<br/>平安何神圣，<br/>安息在那永久膀臂中。<br/>','',55793,9328);
INSERT INTO stanza VALUES('Z406','chorus','安息！安息！<br/>平安稳妥，一无惊恐；<br/>安息！安息！<br/>安息在那永久膀臂中。<br/>','',55794,9329);
INSERT INTO stanza VALUES('Z406','2','今行这旅程，<br/>心中满平安，<br/>安息在那永久膀臂中；<br/>越行越光明，<br/>恩光照灿烂，<br/>安息在那永久膀臂中。<br/>','',55795,9330);
INSERT INTO stanza VALUES('Z406','3','有何我所惧？<br/>有何我所怕？<br/>安息在那永久膀臂中；<br/>与主永同居，<br/>平安无复加，<br/>安息在那永久膀臂中。<br/>','',55796,9331);
INSERT INTO stanza VALUES('Z407','1','救主耶稣，我的太阳，<br/>有你同在夜也明亮，<br/>勿让人世有云遮掩<br/>仆人心眼不见慈颜。<br/>','',55797,9332);
INSERT INTO stanza VALUES('Z407','2','倦眼欲合，频频催眠，<br/>睡如甘露，润我夕荐，<br/>深愿今晚最后思念，<br/>乃是永世息你胸前。<br/>','',55798,9333);
INSERT INTO stanza VALUES('Z407','3','与我同在自晨至夕，<br/>离你我觉生无意义，<br/>无你我惧死荫临到，<br/>求你相偕自晚至朝。<br/>','',55799,9334);
INSERT INTO stanza VALUES('Z407','4','当我睡醒，求主赐福，<br/>扶我行走人生路途，<br/>直至那日被提你旁，<br/>溶化在你爱的海洋。<br/>','',55800,9335);
INSERT INTO stanza VALUES('Z408','1','你名似膏香，<br/>你爱比酒美，<br/>你若来吸引，<br/>有谁不跟随？<br/>我们若跟随<br/>羊群的脚踪，<br/>我们必进入<br/>你爱的交通。<br/>','',55801,9336);
INSERT INTO stanza VALUES('Z408','2','祂是我良人，<br/>我是祂佳偶，<br/>祂将我吸引，<br/>我将祂追求；<br/>祂香如没药，<br/>我愿藏心房，<br/>祂美似凤仙，<br/>我愿戴身上。<br/>','',55802,9337);
INSERT INTO stanza VALUES('Z408','3','进入祂爱里，<br/>享受祂肥甘，<br/>躺在祂怀中，<br/>饱尝祂香甜；<br/>祂爱为旌旗，<br/>将我身遮藏，<br/>祂情似美物，<br/>使我心舒畅。<br/>','',55803,9338);
INSERT INTO stanza VALUES('Z408','4','良人属于我，<br/>我也属于祂，<br/>祂是牧养者，<br/>我是百合花。<br/>惟愿天快曙，<br/>黑影全飞散，<br/>见祂如朝鹿，<br/>显在比特山。<br/>','',55804,9339);
INSERT INTO stanza VALUES('Z408','5','同死的没药，<br/>复活的乳香，<br/>来将我薰透，<br/>好给祂欣赏；<br/>北风阿，兴起，<br/>南风阿，吹来，<br/>来使我心园，<br/>成为祂心爱。<br/>','',55805,9340);
INSERT INTO stanza VALUES('Z408','6','愿在祂眼中，<br/>美丽如良鸽，<br/>愿在祂面前，<br/>皎洁似百合；<br/>愿我全属祂，<br/>作祂乐中乐，<br/>像祂全属我，<br/>是我歌中歌。<br/>','',55806,9341);
INSERT INTO stanza VALUES('Z408','7','美丽如月亮，<br/>得有祂形像，<br/>皎洁似太阳，<br/>得有祂身量；<br/>全属我良人，<br/>使祂命显彰，<br/>全为我良人，<br/>使祂心舒畅。<br/>','',55807,9342);
INSERT INTO stanza VALUES('Z408','7','你是我生命，<br/>我是你活像，<br/>爱情的联结，<br/>如死之坚强，<br/>无何能消灭，<br/>无何能替换，<br/>直到你显现，<br/>在那香草山。<br/>','',55808,9343);
INSERT INTO stanza VALUES('Z409','1','我有一位好朋友，<br/>我是非常宝贵；<br/>祂是爱我如此温柔，<br/>祂爱非常甜美；<br/>我不能活无祂之处，<br/>我爱祂的提握；<br/>所以我们就同住，<br/>我主与我。<br/>','',55809,9344);
INSERT INTO stanza VALUES('Z409','2','有时我几乎卧倒，<br/>祂知我的软弱，<br/>当祂叫我向祂倚靠，<br/>我乐受祂扶托；<br/>祂带我走光明途径，<br/>日过光明生活；<br/>所以我们就同行，<br/>我主与我。<br/>','',55810,9345);
INSERT INTO stanza VALUES('Z409','3','祂知我爱祂几多，<br/>祂知我爱浅深；<br/>但祂是用何爱爱我，<br/>我永不能说清；<br/>乃是一爱永远不衰，<br/>越过越像热火；<br/>所以彼此就相爱，<br/>我主与我。<br/>','',55811,9346);
INSERT INTO stanza VALUES('Z409','4','我告祂以我痛苦，<br/>告祂以我欢喜；<br/>我告祂以我所羡慕，<br/>告祂以我刺激；<br/>祂告我以所当策励，<br/>告我以所当作；<br/>我们彼此吐心意，<br/>我主与我。<br/>','',55812,9347);
INSERT INTO stanza VALUES('Z409','5','祂知我心真羡慕<br/>能救一个灵魂，<br/>祂就叫我为祂外出，<br/>去报爱的新闻；<br/>祂叫我说祂的奇爱，<br/>并祂受死经过；<br/>我们如此常同在，<br/>我主与我。<br/>','',55813,9348);
INSERT INTO stanza VALUES('Z409','6','祂告我以祂国度<br/>离此并不太远；<br/>祂心切望能够尽速<br/>把我带到那边；<br/>无终幸福，喜乐在望，<br/>还有荣耀宝座，<br/>不久我们同作王，<br/>我主与我。<br/>','',55814,9349);
INSERT INTO stanza VALUES('Z410','1','哦，在荣耀里的基督，<br/>已将我心全照亮；<br/>非像微星暗中光顾，<br/>乃是明光胜太阳。<br/>地上全是黑暗、阴影，<br/>无何能以得我心，<br/>惟祂所行艰苦途径，<br/>值得我心来宝珍。<br/>','',55815,9350);
INSERT INTO stanza VALUES('Z410','2','世人乃靠属地之光，<br/>艰苦疲困度人生；<br/>我见之光来自天上，<br/>远胜午日放光明：<br/>毫无遮蔽，永不衰亏，<br/>使我得见祂荣面，<br/>和祂爱的无限宝贵，<br/>并祂恩典的丰满。<br/>','',55816,9351);
INSERT INTO stanza VALUES('Z410','3','得见祂的奇妙荣耀，<br/>并祂更妙的奇爱，<br/>如何为我已经得到<br/>高超地位到万代。<br/>幔子已撤，非仅一瞥，<br/>乃是幔内来安居；<br/>注视祂面无间无歇，<br/>得听隐密的话语。<br/>','',55817,9352);
INSERT INTO stanza VALUES('Z410','4','我已看见基督荣面，<br/>别事请勿向我题；<br/>我已听见祂的恩言，<br/>这已够使我满意。<br/>借祂荣耀所发光辉，<br/>有福荣面我已见，<br/>这个荣耀且要成为<br/>我的住处到永远。<br/>','',55818,9353);
INSERT INTO stanza VALUES('Z411','1','夕阳西沉大地静，<br/>猬务完毕我心定，<br/>晚星高照暗中明，<br/>幽夜近主灵里清，<br/>静候俯伏。<br/>','',55819,9354);
INSERT INTO stanza VALUES('Z411','chorus','近乎，近乎，近乎，<br/>可近之主！<br/>我心所羡灵所慕，<br/>是你可爱的面目，<br/>可亲之主！<br/>','',55820,9355);
INSERT INTO stanza VALUES('Z411','2','在这宇宙广厦中，<br/>我心寻求你面容，<br/>深愿能在我四围，<br/>所见全是你光辉，<br/>使我满足。<br/>','',55821,9356);
INSERT INTO stanza VALUES('Z411','3','当这夜影越幽深，<br/>我心切慕越殷勤，<br/>愿能冲过众星辰，<br/>得见你面近你身，<br/>永不孤苦。<br/>','',55822,9357);
INSERT INTO stanza VALUES('Z411','4','到这黑夜与星辰，<br/>从我眼前全逝逊，<br/>愿那永远的早晨，<br/>为我带来你荣身，<br/>夜影俱无。<br/>','',55823,9358);
INSERT INTO stanza VALUES('Z412','1','恩主，我今凭信摸你，<br/>你是供给的源头；<br/>凭信取用你的能力，<br/>借你宝血来领受。<br/>','',55824,9359);
INSERT INTO stanza VALUES('Z412','chorus','摸你，就得生命供应，<br/>借着你灵的运行；<br/>你灵将我纯洁、充盈，<br/>使我得享你丰盛。<br/>','',55825,9360);
INSERT INTO stanza VALUES('Z412','2','凭信取用，凭信摸你，<br/>凭信应用你丰富；<br/>我的全人向你开启，<br/>你之所是向我注。<br/>','',55826,9361);
INSERT INTO stanza VALUES('Z412','3','摸你，恩主，摸你更深，<br/>摸而取用你丰盛；<br/>从你接受，恩上加恩，<br/>我就流露你生命。<br/>','',55827,9362);
INSERT INTO stanza VALUES('Z412','4','能力、智慧、<br/>慈爱、恩宠，<br/>凡我需要你供应；<br/>使我摸你，使我取用，<br/>摸你、取用，不稍停。<br/>','',55828,9363);
INSERT INTO stanza VALUES('Z413','1','无别声音破此静寂，<br/>无别踪迹侵扰此光景，<br/>只有祂美丽、<br/>宝贝的自己，<br/>和祂可爱的柔声。<br/>','',55829,9364);
INSERT INTO stanza VALUES('Z413','chorus','宝贝的救主、<br/>亲爱的耶稣，<br/>可否求你向我说出：<br/>你曾为何故，<br/>你究是何如，<br/>在这安静属天处？<br/>','',55830,9365);
INSERT INTO stanza VALUES('Z413','2','安静之中有祂莅止，<br/>祂向我密语，深入我心，<br/>带我进内室，<br/>向我表意思，<br/>说祂是我的爱人。<br/>','',55831,9366);
INSERT INTO stanza VALUES('Z413','3','在此就是属天圣境，<br/>不许有声音，<br/>一切安静；<br/>我喜乐来近，<br/>我渴求来饮<br/>你肯表露的爱情。<br/>','',55832,9367);
INSERT INTO stanza VALUES('Z413','4','在这俯伏安静之中，<br/>主耶稣，我不敢稍动弹；<br/>恐有音失踪，<br/>恐有语落空，<br/>我失你爱的片段。<br/>','',55833,9368);
INSERT INTO stanza VALUES('Z413','5','我魂，当息！<br/>我心，当足！<br/>你已达到最高快乐间：<br/>安卧你救主亲爱的胸府，<br/>注视祂的可爱面。<br/>','',55834,9369);
INSERT INTO stanza VALUES('Z414','1','进入幔内，<br/>就必出到营外，<br/>尝到天美，<br/>就必丢弃地爱；<br/>圣中之圣如果满足我心，<br/>空中之空岂能欺骗我魂？<br/>','',55835,9370);
INSERT INTO stanza VALUES('Z414','2','进入幔内，<br/>就必出到营外，<br/>天一同在，<br/>就必使地离开；<br/>天上荣耀如果吸引我灵，<br/>地上福乐岂能霸占我情？<br/>','',55836,9371);
INSERT INTO stanza VALUES('Z414','3','进入幔内，<br/>瞻仰荣耀基督，<br/>出到营外，<br/>跟随卑微耶稣；<br/>宝座、冠冕，<br/>如果将我鼓舞，<br/>马槽、十架，<br/>岂能使我裹足？<br/>','',55837,9372);
INSERT INTO stanza VALUES('Z414','4','进入幔内，<br/>吸取复活大能，<br/>出到营外，<br/>奔跑十架路程；<br/>我若看见祂在天上面容，<br/>就必步武祂在地上脚踪。<br/>','',55838,9373);
INSERT INTO stanza VALUES('Z414','5','进入幔内，<br/>饱尝天上肥甘，<br/>出到营外，<br/>忍受地上艰难；<br/>地上经历虽使我心酸痛，<br/>天上交通却叫我灵赞颂。<br/>','',55839,9374);
INSERT INTO stanza VALUES('Z414','6','进入幔内，<br/>享受主的上好，<br/>出到营外，<br/>供应人的需要；<br/>天上生命如果从我活出，<br/>地上灵魂就必因我得福。<br/>','',55840,9375);
INSERT INTO stanza VALUES('Z414','7','进入幔内，<br/>直到幔子不存，<br/>出到营外，<br/>直到营都灭尽；<br/>直到天地所有同归于一，<br/>直到神、人永远<br/>不再分离。<br/>','',55841,9376);
INSERT INTO stanza VALUES('Z415','1','在祂同在的秘密处，<br/>我得安居何甘美！<br/>在祂面前时常俯伏，<br/>所学功课何宝贵！<br/>忧虑不能将我搅扰，<br/>试炼也不能压住；<br/>每逢撒但引诱吼叫，<br/>我就到祂隐密处，<br/>我就到祂隐密处。<br/>','',55842,9377);
INSERT INTO stanza VALUES('Z415','2','当我带着疲倦、干渴，<br/>来到祂的翅膀间，<br/>就得荫庇、凉爽、快乐，<br/>活泉清澈而新鲜；<br/>在此投身救主胸怀，<br/>彼此交通满香甜；<br/>我虽尝试，也说不来<br/>祂那秘密的语言。<br/>','',55843,9378);
INSERT INTO stanza VALUES('Z415','3','但有一事是我所知：<br/>当我向祂诉苦情，<br/>祂就耐心听我心事，<br/>并且鼓舞我萎灵。<br/>你想从来祂不责备？<br/>那祂就是很虚伪，<br/>如果祂是从来也未<br/>责备祂所见的罪。<br/>','',55844,9379);
INSERT INTO stanza VALUES('Z415','4','这隐密处如何美佳，<br/>如果你也愿知晓，<br/>请去住在祂的荫下，<br/>就必尝到这味道；<br/>若你的灵与祂相交，<br/>安静住于祂荣光，<br/>你的脸面就必返照<br/>祂那荣美的形像。<br/>','',55845,9380);
INSERT INTO stanza VALUES('Z416','1','我已相信真事实，<br/>我已接受主的死，<br/>我已经过外院子，<br/>阿利路亚，赞美主！<br/>借主赎罪的宝血，<br/>我得归神成圣洁，<br/>不再有分于罪孽，<br/>阿利路亚，赞美主！<br/>','',55846,9381);
INSERT INTO stanza VALUES('Z416','chorus','阿利路亚！阿利路亚！<br/>裂开幔子我已过，<br/>这里荣耀不败落！<br/>阿利路亚！阿利路亚！<br/>我今在我王的面前<br/>过生活！<br/>','',55847,9382);
INSERT INTO stanza VALUES('Z416','2','外层幔子我已过，<br/>进入头层的圣所，<br/>神圣供应全得着，<br/>阿利路亚，赞美主！<br/>我今与神已和谐，<br/>经过祭坛全圣别，<br/>神外世界永弃绝，<br/>阿利路亚，赞美主！<br/>','',55848,9383);
INSERT INTO stanza VALUES('Z416','3','内层幔子我也过，<br/>进入二层至圣所，<br/>来到神的施恩座，<br/>阿利路亚，赞美主！<br/>今在神前过生活，<br/>以神作我的居所，<br/>不再有己的间隔，<br/>阿利路亚，赞美主！<br/>','',55849,9384);
INSERT INTO stanza VALUES('Z416','4','我今是神的祭司，<br/>经过救赎才如此，<br/>身分地位何确实，<br/>阿利路亚，赞美主！<br/>我今是在灵里面，<br/>活在神的荣耀前，<br/>夜以继昼不间断，<br/>阿利路亚，赞美主！<br/>','',55850,9385);
INSERT INTO stanza VALUES('Z417','1','夜影尚存，晨光未现，<br/>重新来到恩主面前；<br/>祂在里面放明、照耀，<br/>我得看见祂的荣颜。<br/>向我发言、给我看见：<br/>祂的丰富是为今天；<br/>甜美、欢乐，将祂享受，<br/>所有饥饿全变饱满。<br/>','',55851,9386);
INSERT INTO stanza VALUES('Z417','2','主灵借话与我交谈，<br/>直到我心发出颂赞，<br/>生命活泉，带着恩力，<br/>在我里面涌流潺潺。<br/>向我发言、给我看见：<br/>祂的丰富是为今天；<br/>清爽、畅快，将祂欢饮，<br/>所有干渴全都消减。<br/>','',55852,9387);
INSERT INTO stanza VALUES('Z417','3','当我欢留于祂面光，<br/>祂以温情对付、指点；<br/>用祂神圣、宝贵成分，<br/>浸透全人、供应无限。<br/>向我发言、给我看见：<br/>祂的丰富是为今天；<br/>多方、丰满将祂享受，<br/>所有问题全都逃窜！<br/>','',55853,9388);
INSERT INTO stanza VALUES('Z418','1','住在主里面，<br/>无上的福气，<br/>常与主交通，<br/>甜美的经历；<br/>住在主里面，<br/>主与我联合，<br/>常与主交通，<br/>我与主无隔。<br/>','',55854,9389);
INSERT INTO stanza VALUES('Z418','2','住在主里面，<br/>恩膏必运行，<br/>常与主交通，<br/>圣灵必引领；<br/>顺服主恩膏，<br/>得享主肥甘，<br/>跟随主圣灵，<br/>必作主同伴。<br/>','',55855,9390);
INSERT INTO stanza VALUES('Z418','3','住在主里面，<br/>恩光必照明，<br/>常与主交通，<br/>黑影必除净；<br/>恩光一顺从，<br/>生命必增长，<br/>黑影全脱离，<br/>心、灵才舒畅。<br/>','',55856,9391);
INSERT INTO stanza VALUES('Z418','4','住在主里面，<br/>软弱变刚强，<br/>常与主交通，<br/>生命吞死亡；<br/>住在主里面，<br/>叹息变歌唱，<br/>常与主交通，<br/>喜乐代忧伤。<br/>','',55857,9392);
INSERT INTO stanza VALUES('Z418','5','住在主里面，<br/>撒但难攻击，<br/>常与主交通，<br/>世界失吸力；<br/>住在主里面，<br/>罪恶无权势，<br/>常与主交通，<br/>自己必消逝。<br/>','',55858,9393);
INSERT INTO stanza VALUES('Z418','6','住在主里面，<br/>模成主荣形，<br/>常与主交通，<br/>充满主生命；<br/>住在主里面，<br/>经历主大能，<br/>常与主交通，<br/>吸取主丰盛。<br/>','',55859,9394);
INSERT INTO stanza VALUES('Z418','7','住在主里面，<br/>心、灵在渴慕，<br/>常与主交通，<br/>圣灵在催促；<br/>惟愿我全人<br/>浸在主里面，<br/>与主溶为一，<br/>从今到永远。<br/>','',55860,9395);
INSERT INTO stanza VALUES('Z419','1','我主，你说你是真树，<br/>我是你的真枝子；<br/>但我不知为何缘故，<br/>我是如此不结实。<br/>','',55861,9396);
INSERT INTO stanza VALUES('Z419','2','我心羡慕结果更多，<br/>更能彰显你生命；<br/>更能荣耀归与宝座，<br/>更能祷告得答应。<br/>','',55862,9397);
INSERT INTO stanza VALUES('Z419','3','但是，主阿，我不明白<br/>『常在里面』的圣言；<br/>我越追求要去『常在，』<br/>我越发现在外边。<br/>','',55863,9398);
INSERT INTO stanza VALUES('Z419','4','我不觉得我在里面，<br/>我也祷告并立志！<br/>但你都像隔开很远，<br/>生命仍然无果子。<br/>','',55864,9399);
INSERT INTO stanza VALUES('Z419','5','但你是说，你已是树，<br/>我也已是你枝子；<br/>当我信你作我救主，<br/>圣灵已成此事实。<br/>','',55865,9400);
INSERT INTO stanza VALUES('Z419','6','我今已是在你里面，<br/>再也不必求加入；<br/>我是已经与你结联，<br/>完全合一的骨肉。<br/>','',55866,9401);
INSERT INTO stanza VALUES('Z419','7','秘诀不是要我『去在，』<br/>事实是我『已在』内；<br/>所求乃是不要离开，<br/>不是如何得地位。<br/>','',55867,9402);
INSERT INTO stanza VALUES('Z419','7','我已在内，已在你内！<br/>这是神作的事实！<br/>不必祷告，不必行为，<br/>乃是神手的设施。<br/>','',55868,9403);
INSERT INTO stanza VALUES('Z419','9','我已在内怎求入内，<br/>我是何等的愚昧，<br/>现今我只欢乐赞美，<br/>相信圣言的无伪。<br/>','',55869,9404);
INSERT INTO stanza VALUES('Z419','10','我今只有完全安息，<br/>知道你是我一切，<br/>你是生命、你是能力，<br/>而我一切都了结。<br/>','',55870,9405);
INSERT INTO stanza VALUES('Z420','1','住在你里面，<br/>这是我心愿，<br/>住在你里面，<br/>时刻不间断；<br/>枝子如何与葡萄树相联，<br/>我也深愿，<br/>主，住在你里面。<br/>','',55871,9406);
INSERT INTO stanza VALUES('Z420','2','住在你里面，<br/>你富我享受，<br/>你所是一切，<br/>得借我流露；<br/>愿作你身上常新的枝子，<br/>彰显你生命，<br/>结果永不止。<br/>','',55872,9407);
INSERT INTO stanza VALUES('Z420','3','住在你里面，<br/>罪、己失权能，<br/>再无法胜过你内住生命；<br/>与你相结联，<br/>深处互交通，<br/>灵就能管治魂一切活动。<br/>','',55873,9408);
INSERT INTO stanza VALUES('Z420','4','住在你里面，<br/>得知你心意，<br/>摸着你同在，<br/>进入你秘密；<br/>喜乐与平安要将我充溢，<br/>你话的供应也作我能力。<br/>','',55874,9409);
INSERT INTO stanza VALUES('Z421','1','无你，我就无法想，<br/>不能立定地位，<br/>我无力量和善良，<br/>我无自己智慧；<br/>但你，亲爱的救主，<br/>一切中的一切，<br/>软弱要变成祝福，<br/>如果我被提挈。<br/>','',55875,9410);
INSERT INTO stanza VALUES('Z421','2','无你，我就无法想，<br/>这路何等的长，<br/>我是疲倦身不强，<br/>叹息代替诗章；<br/>我怎可以能无你？<br/>我并不能识路；<br/>但你识路直到底，<br/>不肯让我迷途。<br/>','',55876,9411);
INSERT INTO stanza VALUES('Z421','3','无你，我就无法想，<br/>耶稣，亲爱救主；<br/>就是我眼无印象，<br/>你仍亲近无误；<br/>何等孤单何等痛，<br/>在这生疏人地，<br/>若无甘甜的交通，<br/>若无你的安息。<br/>','',55877,9412);
INSERT INTO stanza VALUES('Z421','4','无你，我就无法想，<br/>无人能够认识<br/>我灵奇深的意向，<br/>将牠需要解释；<br/>我心秘密的角落，<br/>无人能够进入，<br/>来慰、来静并来托，<br/>只有你能，我主。<br/>','',55878,9413);
INSERT INTO stanza VALUES('Z421','5','无你，我就无法想，<br/>年日已经不多，<br/>我是须与人同样<br/>孤独渡河而过；<br/>但你永远不离开，<br/>不管浪有几多，<br/>我知你仍要施爱，<br/>并低声说：『是我。』<br/>','',55879,9414);
INSERT INTO stanza VALUES('Z422','1','主，我还有谁在天上？<br/>惟有你！惟有你！<br/>我的一生只此可唱：<br/>主为我！主为我！<br/>祂已为我流血辛劳，<br/>祂作我的赎罪羊羔，<br/>使我这人与神和好，<br/>主为我！主为我！<br/>','',55880,9415);
INSERT INTO stanza VALUES('Z422','2','我不追求自私福气，<br/>我要主！我要主！<br/>我不羡慕镀金玩意，<br/>我要主！我要主！<br/>自私福气不能长久，<br/>性质规定瞬息罢休，<br/>我的喜乐永远存留，<br/>我要主！我要主！<br/>','',55881,9416);
INSERT INTO stanza VALUES('Z422','3','我今弃绝为富思想，<br/>主为我！主为我！<br/>我不盼望自己安享，<br/>主为我！主为我！<br/>无花果树虽不发旺，<br/>葡萄、橄榄无一可享，<br/>棚内无牛、圈中无羊，<br/>主为我！主为我！<br/>','',55882,9417);
INSERT INTO stanza VALUES('Z422','4','我心现今完全安息，<br/>主为我！主为我！<br/>不怕试炼常来攻击，<br/>主为我！主为我！<br/>任凭引诱力量汹涌，<br/>我们靠主能够强勇，<br/>能够冷笑牠们无用，<br/>主为我！主为我！<br/>','',55883,9418);
INSERT INTO stanza VALUES('Z422','5','当我人生路程将毕，<br/>我要主！我要主！<br/>安全倚靠祂的手臂，<br/>我要主！我要主！<br/>我的躯壳虽有痛苦，<br/>所有自然力量都无，<br/>我仍高声歌唱欢呼，<br/>我要主！我要主！<br/>','',55884,9419);
INSERT INTO stanza VALUES('Z423','1','意志薄弱，能力软弱，<br/>盼望已经全都消灭；<br/>只有信托你的工作<br/>将我这人温柔提挈。<br/>','',55885,9420);
INSERT INTO stanza VALUES('Z423','2','尽我所有，所有失败，<br/>失败至今，失败频仍；<br/>无何可信，信你能耐，<br/>能够抓我听你命令。<br/>','',55886,9421);
INSERT INTO stanza VALUES('Z423','3','当我的心稍微高仰，<br/>我就近乎跌倒危地；<br/>我不敢作，我不敢想，<br/>事事处处，我需要你。<br/>','',55887,9422);
INSERT INTO stanza VALUES('Z423','4','你是救主…刚强…体贴，<br/>哦主，我今寻求你面；<br/>虽然我是弱中弱者，<br/>我的能力是你恩典。<br/>','',55888,9423);
INSERT INTO stanza VALUES('Z424','1','我心安息在于主！<br/>这才真是安息！<br/>除此，全能的耶稣，<br/>罪人有何希冀？<br/>你光是我的智慧，<br/>你爱是我奋勉；<br/>你在荣耀的地位，<br/>天天引我进前。<br/>','',55889,9424);
INSERT INTO stanza VALUES('Z424','2','我罪虽大无法比，<br/>你赐恩典更大；<br/>你是羔羊来献祭，<br/>你死我免受罚；<br/>我从罪中得释放，<br/>就从灰尘重回；<br/>你话是我的亮光，<br/>你血是我宝贝。<br/>','',55890,9425);
INSERT INTO stanza VALUES('Z424','3','温柔的主，你目的，<br/>惟愿从我得成；<br/>为着遵行你旨意，<br/>我今奉献此生。<br/>我虽是真的软弱，<br/>可是你是能力；<br/>你的子民万事绰，<br/>只要他们有你。<br/>','',55891,9426);
INSERT INTO stanza VALUES('Z424','4','黑云罩我最黑时，<br/>正是你最近我，<br/>来使我信能坚持，<br/>来教我灵不懦。<br/>在你怀里我安卧，<br/>注视你的荣颜；<br/>你是我的安息所，<br/>撒但徒然离间。<br/>','',55892,9427);
INSERT INTO stanza VALUES('Z424','5','是你使我能喜乐，<br/>是你使我释放；<br/>因此我要献诗歌，<br/>向你永远称扬。<br/>地上福乐和爱情，<br/>来源纵然全涸，<br/>只须你恩有供应，<br/>或生或死都可。<br/>','',55893,9428);
INSERT INTO stanza VALUES('Z425','1','我是受造的瓦器，<br/>宝贝基督放我里；<br/>我须作祂的器皿，<br/>祂作内容来藏隐。<br/>','',55894,9429);
INSERT INTO stanza VALUES('Z425','2','照祂形像我被造，<br/>适合基督来住着；<br/>神使器皿的形状，<br/>与其内容能相像。<br/>','',55895,9430);
INSERT INTO stanza VALUES('Z425','3','祂今居留在我灵，<br/>用祂大能来支撑；<br/>我得与祂成一灵，<br/>受祂实际的供应。<br/>','',55896,9431);
INSERT INTO stanza VALUES('Z425','4','天天居衷在感动，<br/>时时调和相交通；<br/>所有脚步祂保守，<br/>每一部分祂浸透。<br/>','',55897,9432);
INSERT INTO stanza VALUES('Z425','5','让祂由衷得表现，<br/>使祂在我被人见；<br/>我须透明又透亮，<br/>祂可借我得显彰。<br/>','',55898,9433);
INSERT INTO stanza VALUES('Z425','6','变化乃是我所需，<br/>全人破碎无所余；<br/>泥土得改原形状，<br/>变成宝贝的模样。<br/>','',55899,9434);
INSERT INTO stanza VALUES('Z426','1','当我同主行动，<br/>在祂话的光中，<br/>何等荣耀照在我全身；<br/>当我肯听命令，<br/>祂就充满我灵，<br/>祂充满信而顺从的人。<br/>','',55900,9435);
INSERT INTO stanza VALUES('Z426','chorus','信而顺从！<br/>因为除此以外，<br/>不能得主的喜爱-<br/>惟有信而顺从！<br/>','',55901,9436);
INSERT INTO stanza VALUES('Z426','2','地无一点黑影、<br/>天无一片暗景<br/>能迷漫，当祂显露笑容；<br/>没有疑惑畏惧、<br/>没有流泪忧虑<br/>能存在，若我信而顺从。<br/>','',55902,9437);
INSERT INTO stanza VALUES('Z426','3','没有一个重担、<br/>没有一点为难，<br/>祂是不顾，让我们苦痛；<br/>所有伤心损失、<br/>所有厌弃羞耻<br/>都成祝福，若信而顺从。<br/>','',55903,9438);
INSERT INTO stanza VALUES('Z426','4','但我不能领会<br/>祂爱何等的美，<br/>若我不放一切于坛社；<br/>因祂所给诗歌、<br/>因祂所赐喜乐<br/>乃是为肯信而顺从者。<br/>','',55904,9439);
INSERT INTO stanza VALUES('Z426','5','然后在祂光中，<br/>才有甜美交通，<br/>我就前行，与祂同脚踪；<br/>祂要求，我就许；<br/>祂差遣，我就去；<br/>不要怕，只要信而顺从。<br/>','',55905,9440);
INSERT INTO stanza VALUES('Z427','1','我今听见救主招呼，<br/>我今听见救主招呼，<br/>我今听见救主招呼，<br/>要我跟祂，跟祂走窄路。<br/>','',55906,9441);
INSERT INTO stanza VALUES('Z427','chorus','无论何处要我跟随，<br/>无论何时要我跟随，<br/>无论祸福，无论安危，<br/>要我跟随，<br/>跟随，不稍退。<br/>','',55907,9442);
INSERT INTO stanza VALUES('Z427','2','我今答应救主招呼，<br/>我今答应救主招呼，<br/>我今答应救主招呼，<br/>甘愿一生，<br/>一生，跟随主。<br/>','',55908,9443);
INSERT INTO stanza VALUES('Z427','chorus','无论何处我必跟随，<br/>无论何时我必跟随，<br/>无论祸福，无论安危，<br/>我必跟随，<br/>跟随，不稍退。<br/>','',55909,9444);
INSERT INTO stanza VALUES('Z427','3','撇下亲人，舍弃世福，<br/>撇下亲人，舍弃世福，<br/>撇下亲人，舍弃世福，<br/>甘愿一生，<br/>一生，跟随主。<br/>','',55910,9445);
INSERT INTO stanza VALUES('Z427','4','背起十架，行走窄路，<br/>背起十架，行走窄路，<br/>背起十架，行走窄路，<br/>甘愿一生，<br/>一生，跟随主。<br/>','',55911,9446);
INSERT INTO stanza VALUES('Z427','5','一直向前，必不回顾，<br/>一直向前，必不回顾，<br/>一直向前，必不回顾，<br/>甘愿一生，<br/>一生，跟随主。<br/>','',55912,9447);
INSERT INTO stanza VALUES('Z428','1','跟主行走，心中甜美，<br/>虽然身外有苦楚；<br/>主的脚踪步步追随，<br/>天天跟主走窄路。<br/>','',55913,9448);
INSERT INTO stanza VALUES('Z428','chorus','步步追，步步随，<br/>步步跟随耶稣；<br/>天天追，天天随，<br/>天天行走窄路。<br/>','',55914,9449);
INSERT INTO stanza VALUES('Z428','2','跟主行走，必得光辉，<br/>必见晨光到日午；<br/>主的声音步步追随，<br/>时时跟主走窄路。<br/>','',55915,9450);
INSERT INTO stanza VALUES('Z428','chorus','步步追，步步随，<br/>步步跟随耶稣；<br/>时时追，时时随，<br/>时时行走窄路。<br/>','',55916,9451);
INSERT INTO stanza VALUES('Z428','3','跟主行走，无何可畏，<br/>虽然艰难常四伏；<br/>主的引领步步追随，<br/>处处跟主走窄路。<br/>','',55917,9452);
INSERT INTO stanza VALUES('Z428','chorus','步步追，步步随，<br/>步步跟随耶稣；<br/>处处追，处处随，<br/>处处行走窄路。<br/>','',55918,9453);
INSERT INTO stanza VALUES('Z428','4','跟主行走，前途可贵，<br/>必要同主得国度；<br/>主的标竿步步追随，<br/>一直跟主走窄路。<br/>','',55919,9454);
INSERT INTO stanza VALUES('Z428','chorus','步步追，步步随，<br/>步步跟随耶稣；<br/>一直追，一直随，<br/>一直行走窄路。<br/>','',55920,9455);
INSERT INTO stanza VALUES('Z429','1','『出到营外』就耶稣，<br/>忍受祂受的凌辱；<br/>祂在城外受苦楚，<br/>我岂可以贪舒服。<br/>','',55921,9456);
INSERT INTO stanza VALUES('Z429','2','『出到营外』就耶稣，<br/>十字苦架甘背负；<br/>祂曾走过这窄路，<br/>我今跟随祂脚步。<br/>','',55922,9457);
INSERT INTO stanza VALUES('Z429','3','『出到营外』就耶稣，<br/>撇下亲人和家族；<br/>父神旨意祂所顾，<br/>人情岂能将我阻？<br/>','',55923,9458);
INSERT INTO stanza VALUES('Z429','4','『出到营外』就耶稣，<br/>除非与祂不为伍；<br/>世界团体、宗教组，<br/>就此永远不再属。<br/>','',55924,9459);
INSERT INTO stanza VALUES('Z429','5','『出到营外』就耶稣，<br/>任凭人都与我疏；<br/>这路虽然苦且孤，<br/>有祂作伴心已足。<br/>','',55925,9460);
INSERT INTO stanza VALUES('Z429','6','『出到营外』就耶稣，<br/>与祂同行乐何如；<br/>因祂笑容受鼓舞，<br/>以祂同在作寄庐。<br/>','',55926,9461);
INSERT INTO stanza VALUES('Z429','7','『出到营外』就耶稣，<br/>直到路尽天已曙；<br/>那时见祂必欢呼，<br/>得祂称许进国度。<br/>','',55927,9462);
INSERT INTO stanza VALUES('Z430','1','神照祂所豫知豫定，<br/>要祂所召的人模成<br/>祂儿子的形像。<br/>','',55928,9463);
INSERT INTO stanza VALUES('Z430','chorus','模成，模成神子形像！<br/>模成神儿子的形像！<br/>模成神子形像。<br/>','',55929,9464);
INSERT INTO stanza VALUES('Z430','2','圣灵照着神的自己，<br/>常为我们祷告叹息：<br/>模成神子形像。<br/>','',55930,9465);
INSERT INTO stanza VALUES('Z430','3','圣灵在我里面运行，<br/>也在外面管治模成<br/>神儿子的形像。<br/>','',55931,9466);
INSERT INTO stanza VALUES('Z430','4','圣灵管治、祷告、运行，<br/>都是为将我们模成<br/>神儿子的形像。<br/>','',55932,9467);
INSERT INTO stanza VALUES('Z430','5','万事万物互相效力，<br/>为叫爱神的人得益：<br/>模成神子形像。<br/>','',55933,9468);
INSERT INTO stanza VALUES('Z430','6','为要得着许多儿子，<br/>神就必须完成这事：<br/>模成神子形像。<br/>','',55934,9469);
INSERT INTO stanza VALUES('Z430','7','为叫我们得着荣耀，<br/>神也必须完全作到：<br/>模成神子形像。<br/>','',55935,9470);
INSERT INTO stanza VALUES('Z430','7','基督的爱不能隔绝，<br/>为将这事作得确切：<br/>模成祂的形像。<br/>','',55936,9471);
INSERT INTO stanza VALUES('Z431','1','看！从那些卑贱瓦器，<br/>无尽恩典在照亮，<br/>照到疲困、孤苦心里，<br/>照出基督的面光。<br/>','',55937,9472);
INSERT INTO stanza VALUES('Z431','2','基督，充满天上之光，<br/>今在地上来照亮，<br/>生命之灵住人心房，<br/>死荫照进生命光。<br/>','',55938,9473);
INSERT INTO stanza VALUES('Z431','3','从那天上清明荣光，<br/>瓦器将神带下来，<br/>如此将神给人欣赏，<br/>更加甜美、更可爱。<br/>','',55939,9474);
INSERT INTO stanza VALUES('Z431','4','瓦器并无佳形、美容，<br/>内藏宝贝却荣美；<br/>荣耀焕发，常新、光荣，<br/>属天不变的宝贝。<br/>','',55940,9475);
INSERT INTO stanza VALUES('Z431','5','经过许多饥渴世代，<br/>瓦器虽然弱又脆，<br/>却总将神儿子装载，<br/>显出无价的宝贝。<br/>','',55941,9476);
INSERT INTO stanza VALUES('Z432','1','神的自己照在我心，<br/>我就得以脱旧更新。<br/>宝贝放在瓦器里面，<br/>莫大能力借此彰显！<br/>','',55942,9477);
INSERT INTO stanza VALUES('Z432','chorus','宝贝放在瓦器里面，<br/>莫大能力借此彰显！<br/>莫大能力借此彰显！<br/>','',55943,9478);
INSERT INTO stanza VALUES('Z432','2','四面受敌，不被困住；<br/>遭受逼迫，不被轻忽；<br/>心里作难，不至失望；<br/>被人打倒，不至死亡。<br/>','',55944,9479);
INSERT INTO stanza VALUES('Z432','3','耶稣的死带在身上，<br/>耶稣的生就得显彰；<br/>死在我身发动运行，<br/>生在我身就得显明。<br/>','',55945,9480);
INSERT INTO stanza VALUES('Z432','4','神既叫主从死复活，<br/>也必叫我同祂活着。<br/>外面的人虽然毁坏，<br/>里面的人却新起来！<br/>','',55946,9481);
INSERT INTO stanza VALUES('Z432','chorus','外面的人虽然毁坏，<br/>里面的人却新起来！<br/>里面的人却新起来！<br/>','',55947,9482);
INSERT INTO stanza VALUES('Z432','5','至暂至轻苦楚忍受，<br/>极大无比荣耀成就；<br/>眼所能见并不顾念，<br/>惟有顾念眼所不见。<br/>','',55948,9483);
INSERT INTO stanza VALUES('Z433','1','非我惟主，<br/>被人高举并爱敬；<br/>非我惟主，<br/>被人传扬相信；<br/>非我惟主，<br/>显在言语和步武；<br/>非我惟主，<br/>显在思想态度。<br/>','',55949,9484);
INSERT INTO stanza VALUES('Z433','chorus','哦，求主救我脱离自己！<br/>失去在你里面！<br/>哦，但愿不再是自己，<br/>惟主活我里面！<br/>','',55950,9485);
INSERT INTO stanza VALUES('Z433','2','非我惟主，<br/>是我一切的起首；<br/>非我惟主，<br/>是供给的源头；<br/>非我惟主，<br/>是我所为而工作；<br/>非我惟主，<br/>是我所为生活。<br/>','',55951,9486);
INSERT INTO stanza VALUES('Z433','3','主，惟有主，<br/>所以不再有闲言；<br/>主，惟有主，<br/>所以不再自怜；<br/>主，惟有主，<br/>所以不再谋自存；<br/>主，惟有主，<br/>所以不再自尊。<br/>','',55952,9487);
INSERT INTO stanza VALUES('Z433','4','非我惟主，<br/>故无一可以自傲；<br/>非我惟主，<br/>故无一可自暴；<br/>非我惟主，<br/>因此不再有重担；<br/>非我惟主，<br/>因此不怕危难。<br/>','',55953,9488);
INSERT INTO stanza VALUES('Z433','5','主，惟有主，<br/>不久充满我眼睛，<br/>荣耀无比，<br/>不久就要显明；<br/>主，惟有主，<br/>要永受我的感谢，<br/>耶稣基督，<br/>要永是我一切。<br/>','',55954,9489);
INSERT INTO stanza VALUES('Z434','1','神在天上有一宝贝，<br/>丰富无人能言述；<br/>永远心爱祂所宝贵，<br/>就是祂子主基督。<br/>神在地上有一宝贝，<br/>价值惟有神知悉；<br/>极深心爱人难测窥-<br/>基督启示我心里。<br/>','',55955,9490);
INSERT INTO stanza VALUES('Z434','2','神借火焰舌头临到，<br/>用这永远无穷尽、<br/>取用不竭的无价宝，<br/>充满所选的器皿。<br/>神从天上荣耀里头，<br/>亲来充满这器皿，<br/>用祂爱的无限富有，<br/>满足所有渴慕心。<br/>','',55956,9491);
INSERT INTO stanza VALUES('Z434','3','虽受折磨、试炼、试探，<br/>荣耀呼召仍属你；<br/>葡萄树枝与树相联，<br/>向主倒空你自己。<br/>泥土器皿世人鄙视，<br/>软弱、贫穷又卑贱，<br/>装着宝贝神心赏识，<br/>将主荣耀来彰显。<br/>','',55957,9492);
INSERT INTO stanza VALUES('Z434','4','愿我更加倒空、谦卑，<br/>不为人知、不显扬，<br/>作神器皿，更圣、更贵，<br/>充满基督的荣光！<br/>无何地物遮此荣光，<br/>也无自己的遮蔽，<br/>将这奇妙故事宣扬，<br/>倒空、充满祂自己。<br/>','',55958,9493);
INSERT INTO stanza VALUES('Z435','1','在亚当里面，<br/>罪、死是我所有，<br/>在基督里面，<br/>义、生是我所受；<br/>在肉体里面，<br/>显出亚当性情，<br/>在那灵里面，<br/>活出基督生命。<br/>','',55959,9494);
INSERT INTO stanza VALUES('Z435','2','在亚当里面，<br/>不必再有罪行，<br/>我就是罪人，<br/>已被定罪死刑；<br/>在基督里面，<br/>不须再有义行，<br/>我就是义人，<br/>已被称义得生。<br/>','',55960,9495);
INSERT INTO stanza VALUES('Z435','3','在肉体里面，<br/>不必特意用力，<br/>我就能显出<br/>亚当败坏形迹；<br/>在那灵里面，<br/>不必专一立志，<br/>我就能活出<br/>基督荣耀样式。<br/>','',55961,9496);
INSERT INTO stanza VALUES('Z435','4','与基督同死，<br/>脱离亚当旧性，<br/>与基督同活，<br/>得着基督新生；<br/>不体贴肉体，<br/>旧性就难逞能，<br/>只体贴那灵，<br/>新生就能显圣。<br/>','',55962,9497);
INSERT INTO stanza VALUES('Z435','5','只体贴那灵，<br/>乃是神的救法，<br/>只体贴那灵，<br/>除此别无救拔；<br/>只体贴那灵，<br/>就能胜过情欲，<br/>只体贴那灵，<br/>就必脱离罪律。<br/>','',55963,9498);
INSERT INTO stanza VALUES('Z435','6','只体贴那灵，<br/>就有十架经历，<br/>只体贴那灵，<br/>就得复活能力；<br/>只体贴那灵，<br/>基督就能活出，<br/>只体贴那灵，<br/>生命就必成熟。<br/>','',55964,9499);
INSERT INTO stanza VALUES('Z435','7','在那灵里面，<br/>基督才是生命，<br/>在那灵里面，<br/>生命才是大能；<br/>在那灵里面，<br/>成圣才是经历，<br/>在那灵里面，<br/>经历才能实际。<br/>','',55965,9500);
INSERT INTO stanza VALUES('Z436','1','基督是我生命，<br/>也是我平安；<br/>使我有分那灵，<br/>与祂相结联。<br/>','',55966,9501);
INSERT INTO stanza VALUES('Z436','chorus','随从那灵而行，<br/>活在主里面，<br/>就得饱尝生命，<br/>并得享平安。<br/>','',55967,9502);
INSERT INTO stanza VALUES('Z436','2','基督我已属于，<br/>不再受捆绑；<br/>生命之灵的律<br/>已将我释放。<br/>','',55968,9503);
INSERT INTO stanza VALUES('Z436','3','不再体贴肉体，<br/>凡事体贴灵；<br/>不再随从己意，<br/>只随灵而行。<br/>','',55969,9504);
INSERT INTO stanza VALUES('Z436','4','不再与神为敌，<br/>不服神律法；<br/>乃有超凡之义，<br/>远胜守律法。<br/>','',55970,9505);
INSERT INTO stanza VALUES('Z436','5','那灵住在我里，<br/>不只能属灵；<br/>就是必死身体，<br/>也必得复生。<br/>那灵在我灵里，<br/>二灵成一灵，<br/>见证我是神裔，<br/>凡事也引领。<br/>','',55971,9506);
INSERT INTO stanza VALUES('Z437','1','宁舍世界而要基督，<br/>因祂满足我情衷；<br/>除祂以外，何所爱慕？<br/>何况世福尽虚空！<br/>','',55972,9507);
INSERT INTO stanza VALUES('Z437','chorus','哦，祂丰满我不能言！<br/>但这丰满我知道；<br/>哦，祂甘甜真是超凡！<br/>但这甘甜我尝到。<br/>','',55973,9508);
INSERT INTO stanza VALUES('Z437','2','宁舍世界而要基督，<br/>有祂我就别无需；<br/>得着世界仍是缺如，<br/>得着基督就有余。<br/>','',55974,9509);
INSERT INTO stanza VALUES('Z437','3','世界虽大，我心虽小，<br/>大者难使小者足；<br/>小小之心所需所要，<br/>惟有基督能满足。<br/>','',55975,9510);
INSERT INTO stanza VALUES('Z437','4','有了基督就能欢唱，<br/>没有基督必忧郁；<br/>基督是我一切宝藏，<br/>在祂里面我定居！<br/>','',55976,9511);
INSERT INTO stanza VALUES('Z438','1','我已拣选主耶稣，<br/>拣选祂作世界；<br/>祂爱实在是充足，<br/>满足我的一切；<br/>主，我是你的器皿，<br/>只有你能充盈；<br/>叙加的水饮千井，<br/>渴仍不停。<br/>','',55977,9512);
INSERT INTO stanza VALUES('Z438','chorus','耶稣，耶稣，<br/>我拣选主耶稣，<br/>我心今正住在所有甘甜事物之源；<br/>耶稣，耶稣，<br/>祂乃是我满足，<br/>是祂消除我的要求，<br/>平静我的意愿。<br/>','',55978,9513);
INSERT INTO stanza VALUES('Z438','2','我已拣选主耶稣，<br/>拣选祂作喜乐；<br/>有祂，我心虽痛苦，<br/>依然会唱诗歌；<br/>有祂，我无别原因，<br/>也发喜乐声音；<br/>因我所有的欢欣，<br/>是在祂心。<br/>','',55979,9514);
INSERT INTO stanza VALUES('Z438','3','我已拣选主耶稣，<br/>拣选祂作希望；<br/>祂赐基业甚丰富，<br/>使我不住思量；<br/>将牠赐我的救主<br/>乃是我的至宝；<br/>今天我心有催促：<br/>得祂最好。<br/>','',55980,9515);
INSERT INTO stanza VALUES('Z438','4','我已拣选主耶稣，<br/>拣选祂作我主；<br/>祂爱实在是难述，<br/>尝到就会屈服；<br/>我已奉献我一切，<br/>向祂我无要求；<br/>我心只求祂喜悦，<br/>怕祂心忧。<br/>','',55981,9516);
INSERT INTO stanza VALUES('Z439','1','今日我心因欢乐而歌唱，<br/>我主，<br/>因你是我生命、安康；<br/>亲爱的主，<br/>前途我全借你，<br/>我也知道父神是为我的。<br/>','',55982,1);
INSERT INTO stanza VALUES('Z439','chorus','都因着你！<br/>都因着你！<br/>都因着各各他！<br/>都因着你！<br/>','',55983,2);
INSERT INTO stanza VALUES('Z439','2','前有一日，<br/>我因惧怕永死，<br/>就用行为将我自己装饰，<br/>盼望能够避免神的刑罚，<br/>但我今知你是惟一救法。<br/>','',55984,3);
INSERT INTO stanza VALUES('Z439','3','将来罪人虽然都要痛哭，<br/>但你召会却要被提得福，<br/>因为借你所洒幔里宝血，<br/>她能胜过阴府所有猖獗。<br/>','',55985,4);
INSERT INTO stanza VALUES('Z439','4','神的羔羊为我担当罪恶，<br/>使我得救，<br/>今后永远生活，<br/>你为我喝公义忿怒的杯，<br/>审判已过，<br/>现今再无死味。<br/>','',55986,5);
INSERT INTO stanza VALUES('Z439','5','你使我在青草地场躺卧，<br/>平安的神将祂最好给我，<br/>因我现今倚在你的胸怀，<br/>与你交通，<br/>并尝你的大爱。<br/>','',55987,6);
INSERT INTO stanza VALUES('Z439','6','愿你保守我的生命佳美，<br/>使我虽然遇见<br/>讥嘲、谤毁，<br/>也能因信时常仰望父神，<br/>学习交托，<br/>受苦仍能欢欣。<br/>','',55988,7);
INSERT INTO stanza VALUES('Z439','7','求主教我拒绝人世名声，<br/>面如坚石，<br/>经过火热水深，<br/>愿意与主同受<br/>羞辱、挫折，<br/>为主的名作一个殉道者！<br/>当我被提，<br/>在人子前站立，<br/>钉十架者要成我的诗题；<br/>你从天来经历人生苦楚，<br/>又在加略舍去生命血肉。<br/>','',55989,8);
INSERT INTO stanza VALUES('Z439','chorus','都因着我！<br/>都因着我！<br/>都因着我一人！<br/>都因着我！<br/>','',55990,10);
INSERT INTO stanza VALUES('Z440','1','外面虽被旷野太阳晒黑，<br/>光明之子里面却都秀美；<br/>奥秘之乐远非人所能知，<br/>荣耀之王每个都已赏赐；<br/>人心从来未曾想到，<br/>人手也永不能摸着；<br/>圣徒住在神的光中，<br/>得到神的隐藏光荣。<br/>','',55991,9526);
INSERT INTO stanza VALUES('Z440','2','在人看来，乃是亚当族类，<br/>带着属地形状，病、苦缠累，<br/>和那堕落罪人完全相像，<br/>外面需要也和他们一样，<br/>属地生活所有方式、<br/>睡眠起居也都相似。<br/>这是为使他们藐视<br/>人眼所重虚容美姿。<br/>','',55992,9527);
INSERT INTO stanza VALUES('Z440','3','他们里面却有神的生命，<br/>主的话语已将他们重生；<br/>他们已被神圣爱火所焚，<br/>成为属新耶路撒冷的人；<br/>他们都是光中圣徒，<br/>常将甜美诗辞歌赋，<br/>彼此颂扬最高之神，<br/>发出深处最妙之音。<br/>','',55993,9528);
INSERT INTO stanza VALUES('Z440','4','他们行在地上，住在天上；<br/>无力，却能暗中将地执掌；<br/>为难，深处却有神赐平安；<br/>贫穷，却有万有效力成全；<br/>虽被打倒，不至死亡，<br/>心里作难，不至失望；<br/>好像行在死荫之中，<br/>却是活着生命无穷。<br/>','',55994,9529);
INSERT INTO stanza VALUES('Z440','5','将来基督-他们生命-显现，<br/>带着荣耀前来作王掌权，<br/>他们久藏荣耀也要显出，<br/>同着基督要被众目所睹。<br/>哦！光明者，兴起发光，<br/>你同基督要升天上，<br/>隐藏之光要照远方，<br/>每一圣徒都像太阳。<br/>','',55995,9530);
INSERT INTO stanza VALUES('Z441','1','我神、我爱、我的永分，<br/>你永是我一切；<br/>你外，在天我有何人，<br/>在地有你无缺！<br/>在地有你无缺！<br/>','',55996,9531);
INSERT INTO stanza VALUES('Z441','2','天上一切尽都空虚，<br/>地上更是如此！<br/>并无一物值得欢娱，<br/>能与我神相似。<br/>','',55997,9532);
INSERT INTO stanza VALUES('Z441','3','你是我的财富、生命，<br/>我的安稳住处；<br/>其他事物，我也感领，<br/>但非我神、我主。<br/>','',55998,9533);
INSERT INTO stanza VALUES('Z441','4','闪耀财富，与你相比，<br/>不过虚空玩具！<br/>何况其他人之所倚，<br/>岂不更将人愚？<br/>','',55999,9534);
INSERT INTO stanza VALUES('Z441','5','即使全地归我为业，<br/>群星也是我的，<br/>若无你作我的一切，<br/>我仍可怜至极！<br/>','',56000,9535);
INSERT INTO stanza VALUES('Z441','6','让人伸臂如同大海，<br/>笼罗一切财富；<br/>但我只要你的同在，<br/>此外无所爱慕。<br/>','',56001,9536);
INSERT INTO stanza VALUES('Z442','1','当我已为撒但所掳，<br/>正在死地作罪囚奴；<br/>神因爱怜前来眷顾，<br/>将我带回归向基督。<br/>','',56002,9537);
INSERT INTO stanza VALUES('Z442','chorus','神的宏恩将我重生，<br/>赐我新心，又赐新灵，<br/>且将祂灵放在我灵，<br/>使我有分祂的性情。<br/>','',56003,9538);
INSERT INTO stanza VALUES('Z442','2','神用清水洒在我身，<br/>污秽、偶像我全脱尽；<br/>除掉石心，赐我肉心，<br/>使我成为新造新人。<br/>','',56004,9539);
INSERT INTO stanza VALUES('Z442','3','神的自己作我生命，<br/>祂的神性是我性情；<br/>我就合于祂的神圣，<br/>能以活出祂所命令。<br/>','',56005,9540);
INSERT INTO stanza VALUES('Z442','4','我作祂民，祂作我神，<br/>彼此交通相近相亲；<br/>祂是我福，祂是我分，<br/>不再他投，不再他奔。<br/>','',56006,9541);
INSERT INTO stanza VALUES('Z442','5','祂的基督作我住处，<br/>我享祂的一切丰富；<br/>祂作我的生命食物，<br/>我就永远得到饱足。 (副)<br/>神的宏恩将我重生，<br/>赐我新心，又赐新灵，<br/>且将祂灵放在我灵，<br/>使我有分祂的性情。<br/>','',56007,9542);
INSERT INTO stanza VALUES('Z443','1','何等荣耀！何等神圣！<br/>神是永远的生命！<br/>丰富、无限、<br/>坚强、有能、<br/>圣洁、慈仁又光明！<br/>祂的本性、祂的丰盛，<br/>全都在于这生命。<br/>','',56008,9543);
INSERT INTO stanza VALUES('Z443','2','何等慈爱！何等恩典！<br/>神之于人是生命！<br/>祂要进入人的里面，<br/>所以为人创造灵。<br/>祂心对人所喜所愿，<br/>乃在接祂作生命。<br/>','',56009,9544);
INSERT INTO stanza VALUES('Z443','3','何等大爱！何等大恩！<br/>神已流出作生命！<br/>不再自藏，不再自隐，<br/>已经向人来显明；<br/>后成那灵，先在肉身，<br/>给人接受作生命。<br/>','',56010,9545);
INSERT INTO stanza VALUES('Z443','4','何等可亲！何等可近！<br/>神在基督作生命！<br/>基督乃是祂的化身，<br/>祂在肉身的显明；<br/>死而复活，给人相信，<br/>到人里面作生命。<br/>','',56011,9546);
INSERT INTO stanza VALUES('Z443','5','何等奇妙！何等可信！<br/>神成那灵作生命！<br/>那灵是祂又一化身，<br/>是祂实际的显明；<br/>感动人信，进入人心，<br/>到人灵里作生命。<br/>','',56012,9547);
INSERT INTO stanza VALUES('Z443','6','何等宝贵！何等真实！<br/>三一之神作生命！<br/>父先流出就是一子，<br/>子再流出就是灵；<br/>灵一流入就是恩赐，<br/>在人里面作生命。<br/>','',56013,9548);
INSERT INTO stanza VALUES('Z443','7','何等奥秘！何等实际！<br/>神已流入作生命！<br/>流入我心，与我合一，<br/>在我灵里作生命。<br/>阿利路亚，赞美不已，<br/>神竟作了我生命！<br/>','',56014,9549);
INSERT INTO stanza VALUES('Z444','1','是爱的神作我牧人，<br/>祂常喂养，祂常施恩；<br/>祂是属我，我是属祂，<br/>何来需要？何来缺乏？<br/>','',56015,9550);
INSERT INTO stanza VALUES('Z444','2','祂带我到嫩草地场，<br/>使我感觉满足欢畅；<br/>又带我到平静溪流，<br/>交通不断，安息无忧。<br/>','',56016,9551);
INSERT INTO stanza VALUES('Z444','3','我时迷路，祂来截回，<br/>再侧我心受祂支配；<br/>我常摇动，不甚坚定，<br/>但祂引导，是为己名。<br/>','',56017,9552);
INSERT INTO stanza VALUES('Z444','4','何等不明，何等可疑，<br/>怎能行走无所顾忌？<br/>你竿扶持，你杖引领，<br/>你的同在满我途径。<br/>','',56018,9553);
INSERT INTO stanza VALUES('Z444','5','你使我能大胆夸胜，<br/>敌虽四布，享恩如恒：<br/>我头油润，我杯酒溢，<br/>我神从来不曾吝惜。<br/>','',56019,9554);
INSERT INTO stanza VALUES('Z444','6','你的甘甜、奇妙的爱，<br/>测量我的一生年代；<br/>你爱既然永不改变，<br/>我的赞美还要加添。<br/>','',56020,9555);
INSERT INTO stanza VALUES('Z445','1','一想到神，就受吸引，<br/>吸引我心离地，<br/>对于幻景立生厌心，<br/>抵消地的吸力。<br/>','',56021,9556);
INSERT INTO stanza VALUES('Z445','2','仅仅得救，免去沉沦，<br/>难够神之所想；<br/>对神之念激动我心，<br/>使有更高愿望。<br/>','',56022,9557);
INSERT INTO stanza VALUES('Z445','3','惟有神是人的住处，<br/>路虽窄而崎岖；<br/>除神，无何能够满足<br/>我心深处所欲。<br/>','',56023,9558);
INSERT INTO stanza VALUES('Z445','4','只要从你心的深处，<br/>将神尊名称颂，<br/>一切引诱你的邪术，<br/>都要立即消踪。<br/>','',56024,9559);
INSERT INTO stanza VALUES('Z445','5','信靠之心、仰望之眼，<br/>必得神的引导；<br/>如果信心能够移山，<br/>爱心之力岂小？<br/>','',56025,9560);
INSERT INTO stanza VALUES('Z445','6','哦，那追求神的道路，<br/>你仅走了一点！<br/>向神之心，对神之顾，<br/>必能带你向前。<br/>','',56026,9561);
INSERT INTO stanza VALUES('Z445','7','从罪权下得着自由，<br/>生活不失检点；<br/>这些比那爱心所求，<br/>仍是较低恩典。<br/>','',56027,9562);
INSERT INTO stanza VALUES('Z445','7','完全之路，肉体感难，<br/>但在爱心不然；<br/>如果你因要神而前，<br/>必胜一切纠缠。<br/>','',56028,9563);
INSERT INTO stanza VALUES('Z445','9','然后保守良心敏锐，<br/>顾到里面感觉；<br/>膏油涂抹，时时跟随，<br/>这是成熟秘诀。<br/>','',56029,9564);
INSERT INTO stanza VALUES('Z446','1','我的居所乃是神的自己，<br/>我主基督将我带到这里；<br/>祂带我走祂所走过的路，<br/>到这至圣所里与神同住。<br/>圣别所在！<br/>神圣荣美之家，<br/>在此与神同住，<br/>至美绝佳！<br/>','',56030,9565);
INSERT INTO stanza VALUES('Z446','2','夜以继日走过漫长的路，<br/>自己里面想要找到一途；<br/>一无所成，<br/>也无任何进步，<br/>自己努力不过全是失误，<br/>而后得知主是惟一道路，<br/>我当借祂到神里面居住。<br/>','',56031,9566);
INSERT INTO stanza VALUES('Z446','3','奇妙住处，<br/>神圣荣美之家！<br/>与神同住，<br/>安稳无以复加。<br/>哦神，<br/>你我既是互为居所，<br/>求你使我只是向你活着；<br/>在这最美之家，<br/>得享安康，<br/>随事随在将你与人分享。<br/>','',56032,9567);
INSERT INTO stanza VALUES('Z447','1','何等奥妙，<br/>父、子、灵乃是一神！<br/>身位虽三，<br/>本质却是一灵；<br/>何等荣耀，<br/>这位神进入我心，<br/>在我里面，<br/>作我一切供应。<br/>','',56033,9568);
INSERT INTO stanza VALUES('Z447','chorus','三一之神，<br/>作了我的一切！<br/>何等奇妙！<br/>何等荣耀！<br/>神圣成分，<br/>我能取用不竭！<br/>何等高超！<br/>何等逍遥！<br/>','',56034,9569);
INSERT INTO stanza VALUES('Z447','2','何等丰富，<br/>父乃是一切源头，<br/>祂的一切全为供人享受；<br/>何等有福，<br/>这一切竟归我有，<br/>不尽不竭，<br/>取用直到永久！<br/>','',56035,9570);
INSERT INTO stanza VALUES('Z447','3','何等奇妙，<br/>子乃是父的显出，<br/>借着肉身来与人类同处；<br/>何等有效，<br/>在十架成功救赎，<br/>使我罪人竟能与神联属！<br/>','',56036,9571);
INSERT INTO stanza VALUES('Z447','4','何等美妙，<br/>灵乃是子的进入，<br/>进入我灵，<br/>作我生命供应；<br/>何等逍遥，<br/>我今能与灵接触，<br/>灵灵响应，<br/>二灵竟成一灵。<br/>','',56037,9572);
INSERT INTO stanza VALUES('Z447','5','何等实际，<br/>神一切全在灵里，<br/>是灵在灵<br/>给我接触、经历；<br/>何等希奇，<br/>我与神联合为一，<br/>生命、性情<br/>不再彼此各异。<br/>','',56038,9573);
INSERT INTO stanza VALUES('Z448','1','哦神，赞美你的奥妙，<br/>竟然能给我们摸到；<br/>原在光中人难靠近，<br/>今在灵里与我相亲。<br/>','',56039,9574);
INSERT INTO stanza VALUES('Z448','2','你是圣父、圣子、圣灵，<br/>三一之神作我生命；<br/>在我里面将我供应，<br/>使我有你神圣性情。<br/>','',56040,9575);
INSERT INTO stanza VALUES('Z448','3','父在子里，子成为灵，<br/>灵临到我如气似风；<br/>父、子、圣灵，<br/>神圣、奥秘，<br/>成为我的实际经历。<br/>','',56041,9576);
INSERT INTO stanza VALUES('Z448','4','父的一切全归子有，<br/>子的丰富全由灵受；<br/>灵降我身并进我心，<br/>使你成为我的福分。<br/>','',56042,9577);
INSERT INTO stanza VALUES('Z448','5','父是源头，子是显出，<br/>灵是你对我的进入；<br/>父在子里显在人间，<br/>子成为灵进我里面。<br/>','',56043,9578);
INSERT INTO stanza VALUES('Z448','6','父愿子能凡事居首，<br/>子愿凡事以父为头；<br/>灵愿使子得着荣耀，<br/>在我心中向我启晓。<br/>','',56044,9579);
INSERT INTO stanza VALUES('Z448','7','灵是你的最终形态，<br/>进入我灵受我敬拜；<br/>我要享受你的丰富，<br/>必须灵里与灵接触。<br/>','',56045,9580);
INSERT INTO stanza VALUES('Z448','7','灵里敬拜，灵里交通，<br/>灵里祷告、赞美、称颂，<br/>我就摸着灵里圣灵，<br/>享受你作一切供应。<br/>','',56046,9581);
INSERT INTO stanza VALUES('Z449','1','灵是神的荣耀本质，<br/>也是神的神圣所是；<br/>与神接触，享神丰富，<br/>必须借灵，舍此无路。<br/>','',56047,9582);
INSERT INTO stanza VALUES('Z449','2','灵也是人最深部分，<br/>全人里面灵是最真；<br/>要作真人，要摸着神，<br/>必须从灵，才能入门。<br/>','',56048,9583);
INSERT INTO stanza VALUES('Z449','3','神是要人以灵拜灵，<br/>享受祂作一切供应；<br/>祂灵要进人灵里面，<br/>使人与祂灵里相联。<br/>','',56049,9584);
INSERT INTO stanza VALUES('Z449','4','灵灵相交，灵灵响应，<br/>二灵调和成为一灵；<br/>人灵作了神灵居所，<br/>神灵成为人灵生活。<br/>','',56050,9585);
INSERT INTO stanza VALUES('Z449','5','须凭人灵接触神灵，<br/>才能得享神的丰盛；<br/>在人灵里神灵同在，<br/>才能向神献上敬拜。<br/>','',56051,9586);
INSERT INTO stanza VALUES('Z449','6','福音、造就、<br/>聚会、交通，<br/>都该将人带进灵中；<br/>读经、听道或听见证，<br/>都该化祷，灵中响应。<br/>','',56052,9587);
INSERT INTO stanza VALUES('Z449','7','灵里祷告，灵里事奉，<br/>灵里摸着神圣生命；<br/>灵里长进，灵里建造，<br/>灵里显出基督荣耀。<br/>','',56053,9588);
INSERT INTO stanza VALUES('Z449','7','主阿，我愿回到灵里，<br/>学习摸着你的自己；<br/>你灵、我灵不断交流，<br/>涌流生命直到永久！<br/>','',56054,9589);
INSERT INTO stanza VALUES('Z450','1','神之于人一切正常故事，<br/>全都在于灵里；<br/>人须灵里摸着神灵本质，<br/>对神才有经历。<br/>','',56055,9590);
INSERT INTO stanza VALUES('Z450','chorus','灵生灵，<br/>灵拜灵，<br/>以至灵充满我；<br/>灵且成话，<br/>带着丰盛生命，<br/>流出活水江河。<br/>','',56056,9591);
INSERT INTO stanza VALUES('Z450','2','神乃是灵，<br/>并且为人造灵，<br/>要人以灵拜灵；<br/>借此人能得着祂作生命，<br/>以祂为人供应。<br/>','',56057,9592);
INSERT INTO stanza VALUES('Z450','3','神乃是灵<br/>进入人的灵中，<br/>叫人得着重生；<br/>人就能在灵里与祂交通，<br/>得享祂的丰盛。<br/>','',56058,9593);
INSERT INTO stanza VALUES('Z450','4','神乃是灵<br/>充满、浇灌、滋润，<br/>将我变化、更新；<br/>直到能从我灵遍及全身，<br/>浸透我的全人。<br/>','',56059,9594);
INSERT INTO stanza VALUES('Z450','5','神乃是灵<br/>与我融洽、调和，<br/>使我改变形状；<br/>祂的成分在我一再加多，<br/>直到能得显彰。<br/>','',56060,9595);
INSERT INTO stanza VALUES('Z450','6','神的一切丰盛全在灵里，<br/>给我经历、享受；<br/>我须灵里时常将神呼吸，<br/>才得享神所有。 (副)<br/>灵生灵，<br/>灵拜灵，<br/>以至灵充满我；<br/>灵且成话，<br/>带着丰盛生命，<br/>流出活水江河。<br/>','',56061,9596);
INSERT INTO stanza VALUES('Z451','1','神的心意要祂一切<br/>全作我供应；<br/>需要我能与祂联结，<br/>联于祂灵。<br/>','',56062,9597);
INSERT INTO stanza VALUES('Z451','chorus','父的一切、子的丰富，<br/>全都归于灵；<br/>我要与神这灵接触，<br/>必须用灵。<br/>','',56063,9598);
INSERT INTO stanza VALUES('Z451','2','神已将祂本性丰富，<br/>全都赐给我；<br/>但须灵里与祂接触，<br/>才能摸着。<br/>','',56064,9599);
INSERT INTO stanza VALUES('Z451','3','神需心思明白、认识，<br/>也需灵接触；<br/>若不动灵，只凭理智，<br/>难得满足。<br/>','',56065,9600);
INSERT INTO stanza VALUES('Z451','4','不能听道而不祷告，<br/>用脑不用灵；<br/>不能读经而不灵交，<br/>灵不响应。<br/>','',56066,9601);
INSERT INTO stanza VALUES('Z451','5','何等丰富，何等荣耀，<br/>灵里接触神！<br/>神的一切，神的上好，<br/>全是我分。<br/>','',56067,9602);
INSERT INTO stanza VALUES('Z452','1','神的圣灵是神传达，<br/>借祂，神得进入我里；<br/>借祂，神在基督里面，<br/>给我得着，作我经历。<br/>','',56068,9603);
INSERT INTO stanza VALUES('Z452','2','神之为父是作源头，<br/>神之为子是为表现，<br/>神之为灵是为进入，<br/>使我得着神的丰满。<br/>','',56069,9604);
INSERT INTO stanza VALUES('Z452','3','父原住在难近光中，<br/>子来将祂向人显明；<br/>灵又将祂向人传达，<br/>人可灵中将祂接领。<br/>','',56070,9605);
INSERT INTO stanza VALUES('Z452','4','父在子里来人中间，<br/>子又成灵进人里面；<br/>父、子、圣灵，<br/>三一之神，<br/>现今住在我们灵间。<br/>','',56071,9606);
INSERT INTO stanza VALUES('Z452','5','父神乃在子神里面，<br/>得着化身而得彰显；<br/>灵神乃是子神实际，<br/>给我得着作我恩典。<br/>','',56072,9607);
INSERT INTO stanza VALUES('Z452','6','但愿父神对我之爱，<br/>在子神里成我恩典，<br/>借着灵神交通传达，<br/>使我得享神的丰满。<br/>','',56073,9608);
INSERT INTO stanza VALUES('Z453','1','与你更亲，我神，<br/>与你更亲；<br/>虽然十架在身，<br/>使我前进，<br/>我仍发此歌音：<br/>与你更亲，我神，<br/>与你更亲，我神，<br/>与你更亲。<br/>','',56074,9609);
INSERT INTO stanza VALUES('Z453','2','虽作旅客飘泊，<br/>日已西坠，<br/>惊人黑暗罩我，<br/>枕石而睡，<br/>梦中我仍不禁，<br/>愿我与你更亲，<br/>愿我与你更亲，<br/>与你更亲。<br/>','',56075,9610);
INSERT INTO stanza VALUES('Z453','3','梦中有路显明，<br/>如梯通天；<br/>凡你所许事情，<br/>全出恩怜；<br/>又有天使显身，<br/>招我与你更亲，<br/>招我与你更亲，<br/>与你更亲。<br/>','',56076,9611);
INSERT INTO stanza VALUES('Z453','4','醒来心情安适，<br/>充满感赞；<br/>所枕艰苦硬石，<br/>必作你殿；<br/>原来所遇艰辛，<br/>使我与你更亲，<br/>使我与你更亲，<br/>与你更亲。<br/>','',56077,9612);
INSERT INTO stanza VALUES('Z453','5','假若喜乐生翼，<br/>向天飞腾，<br/>日月星辰尽历，<br/>翱翔不停，<br/>我仍发此歌音：<br/>与你更亲，我神，<br/>与你更亲，我神，<br/>与你更亲。<br/>','',56078,9613);
INSERT INTO stanza VALUES('Z454','1','在远山耸立着古老的十字架，<br/>作为羞辱、痛苦标志；<br/>我爱这十字架，<br/>因主离荣耀家，<br/>来在上面替人受死。<br/>','',56079,9614);
INSERT INTO stanza VALUES('Z454','chorus','我宝贵古老的十字架，<br/>一直到我俯伏主脚前；<br/>我坚持古老的十字架，<br/>等有天，<br/>我将牠换冠冕。<br/>','',56080,9615);
INSERT INTO stanza VALUES('Z454','2','古老的十字架，<br/>不少人很轻视，<br/>对我却有奇妙吸力；<br/>神圣洁的羔羊曾降临到此世，<br/>将牠背至髑髅死地。<br/>','',56081,9616);
INSERT INTO stanza VALUES('Z454','3','古老的十字架，<br/>染斑斑的血迹，<br/>从我眼光何等可悦！<br/>就在这十字架，<br/>主受苦到至极，<br/>为要赐我赦免、圣洁。<br/>','',56082,9617);
INSERT INTO stanza VALUES('Z454','4','我永远要效忠古老的十字架，<br/>欢喜受牠所受讥诮；<br/>有一天主再来，<br/>面对面看见祂，<br/>永远享受祂的荣耀。<br/>','',56083,9618);
INSERT INTO stanza VALUES('Z455','1','基督十架是我夸耀，<br/>年代灭没牠独存；<br/>神圣事迹光辉环绕，<br/>十架巍然是中心。<br/>','',56084,9619);
INSERT INTO stanza VALUES('Z455','2','当我遭遇患难、折磨，<br/>希望成空，忧惧缠，<br/>基督十架永不弃我，<br/>看哪！喜乐与平安。<br/>','',56085,9620);
INSERT INTO stanza VALUES('Z455','3','有福太阳，以光以爱，<br/>照耀在我路程上，<br/>基督十架放射光彩，<br/>使我人生更光亮。<br/>','',56086,9621);
INSERT INTO stanza VALUES('Z455','4','是祸是福，是苦是乐，<br/>十架使我全成圣，<br/>在此平安深广莫测，<br/>喜乐永远不变更。<br/>','',56087,9622);
INSERT INTO stanza VALUES('Z455','5','基督十架是我夸耀，<br/>年代灭没牠独存；<br/>神圣事迹光辉环绕，<br/>十架巍然是中心。<br/>','',56088,9623);
INSERT INTO stanza VALUES('Z456','1','求主使我近十架！<br/>在此有一宝泉，<br/>医治活水，无代价，<br/>流自加略山巅。<br/>','',56089,9624);
INSERT INTO stanza VALUES('Z456','chorus','十字架！十字架！<br/>永是我的夸耀！<br/>在此主付的赎价，<br/>是我永远倚靠！<br/>','',56090,9625);
INSERT INTO stanza VALUES('Z456','2','前我战兢就十架，<br/>得蒙爱怜、宽饶；<br/>明亮晨星的光华，<br/>在此仍将我照。<br/>','',56091,9626);
INSERT INTO stanza VALUES('Z456','3','哦主，当我近十架，<br/>示我以其情景；<br/>在你十架荫庇下，<br/>天天助我前行。<br/>','',56092,9627);
INSERT INTO stanza VALUES('Z456','4','就近十架而儆醒，<br/>时时信靠、瞻仰，<br/>直到被提得上升，<br/>永远见主面光。<br/>','',56093,9628);
INSERT INTO stanza VALUES('Z456','chorus','十字架！十字架！<br/>永是我的夸耀！<br/>在此主付的赎价，<br/>是我永远倚靠！<br/>第二节的『明亮晨星』指主基督。<br/>','',56094,9629);
INSERT INTO stanza VALUES('Z457','1','十架永远得胜，<br/>阿利路亚！阿利路亚！<br/>十架将敌除净，<br/>阿利路亚！阿利路亚！<br/>阴府虽极凶猛，<br/>世界虽在翻腾，<br/>肉体虽也逞能，<br/>十架使我仍夸胜！<br/>','',56095,9630);
INSERT INTO stanza VALUES('Z457','chorus','阿利路亚！阿利路亚！<br/>基督十架永得胜！<br/>阿利路亚！阿利路亚！<br/>仗这十架我夸胜！<br/>','',56096,9631);
INSERT INTO stanza VALUES('Z457','2','十架是我生命，<br/>阿利路亚！阿利路亚！<br/>十架赐我权柄，<br/>阿利路亚！阿利路亚！<br/>胜过人情、自己，<br/>胜过世界势力，<br/>胜过一切仇敌，<br/>十架使我胜无已！<br/>','',56097,9632);
INSERT INTO stanza VALUES('Z457','3','十架是我旌旗，<br/>阿路利亚！阿利路亚！<br/>我要永远举起，<br/>阿路利亚！阿利路亚！<br/>软弱变为刚强，<br/>下沉变为高昂，<br/>黑暗变为明亮，<br/>十架使我得释放！<br/>','',56098,9633);
INSERT INTO stanza VALUES('Z458','1','你若不压橄榄成渣，<br/>牠就不能成油；<br/>你若不投葡萄入醡，<br/>牠就不能变成酒；<br/>你若不炼哪哒成膏，<br/>牠就不流芬芳；<br/>主，我这人是否也要<br/>受你许可的创伤？<br/>','',56099,9634);
INSERT INTO stanza VALUES('Z458','chorus','每次的打击，<br/>都是真利益，<br/>如果你收去的东西，<br/>你以自己来代替。<br/>','',56100,9635);
INSERT INTO stanza VALUES('Z458','2','你是否要鼓我心弦，<br/>发出你的音乐？<br/>是否要使音乐甘甜，<br/>须有你爱来苦虐？<br/>是否当我下倒之时，<br/>才能识『爱』的心？<br/>我是不怕任何损失，<br/>若你让我来相亲。<br/>','',56101,9636);
INSERT INTO stanza VALUES('Z458','3','主，我惭愧，因我感觉<br/>总是保留自己，<br/>虽我也曾受你雕削，<br/>我却感觉受强逼！<br/>主，你能否照你喜乐，<br/>没有顾忌去行，<br/>不顾我的感觉如何，<br/>只是要求你欢欣？<br/>','',56102,9637);
INSERT INTO stanza VALUES('Z458','4','如果你我所有苦乐<br/>不能完全相同，<br/>要你喜乐，须我负轭，<br/>我就愿意多苦痛；<br/>主，我全心要你所要，<br/>不惜任何代价；<br/>你若喜悦，并得荣耀，<br/>我背任何十字架。<br/>','',56103,9638);
INSERT INTO stanza VALUES('Z458','5','我要赞美，再要赞美，<br/>赞美何等甘甜；<br/>虽我边赞美边流泪，<br/>甘甜比前更加添；<br/>能有甚么比你更好？<br/>比你喜悦可宝？<br/>主，我只有一个祷告：<br/>你能加增，我减少。<br/>','',56104,9639);
INSERT INTO stanza VALUES('Z459','1','十架越重，神越亲近；<br/>外无十架，内即无神！<br/>黑暗君王必被践踏，<br/>如果我肯背负十架。<br/>神所置于十架之人，<br/>虽受损失，也是欢欣。<br/>','',56105,9640);
INSERT INTO stanza VALUES('Z459','2','十架越重，圣徒越佳，<br/>这是神的试金估价。<br/>若无眼睛流泪浇灌，<br/>园中花木多必枯干！<br/>金子经火才得炼净，<br/>圣徒借苦才能成圣。<br/>','',56106,9641);
INSERT INTO stanza VALUES('Z459','3','十架越重，信心越强；<br/>树越负重，根越深长；<br/>葡萄美果经过压榨，<br/>甜美汁水才能流下；<br/>苦难来临，胆量增长，<br/>珍珠长成，是借蚌伤。<br/>','',56107,9642);
INSERT INTO stanza VALUES('Z460','1','若无损失，就无得着；<br/>非经十架，不能生活；<br/>一粒麦子不落死地，<br/>就难结出许多子粒；<br/>如果我要结果百倍，<br/>怎能完整，不被破碎？<br/>如果我要结果百倍，<br/>怎能完整，不被破碎？<br/>','',56108,9643);
INSERT INTO stanza VALUES('Z460','2','魂所抓者将魂抓住，<br/>金炼之中无不为奴；<br/>我们无论倾向何物，<br/>何物就必将魂锁住；<br/>无论生命或是财产，<br/>只要心爱，必成锁炼。<br/>无论生命或是财产，<br/>只要心爱，必成锁炼。<br/>','',56109,9644);
INSERT INTO stanza VALUES('Z460','3','每当看见成熟禾田，<br/>金谷丰盈向神呈献，<br/>当知必有子粒死过，<br/>必有圣徒牺牲自我；<br/>必定有人受苦、流泪，<br/>争战至死并不心灰。<br/>必定有人受苦、流泪，<br/>争战至死并不心灰。<br/>','',56110,9645);
INSERT INTO stanza VALUES('Z461','1','十架人若背起，<br/>岂只受苦而已！<br/>十架人若不离，<br/>终必被置死地！<br/>因为十架用意，<br/>就是使人绝气；<br/>所以十架经历，<br/>总是结束自己。<br/>','',56111,9646);
INSERT INTO stanza VALUES('Z461','2','这是神的救法，<br/>将人十架治杀；<br/>像是残酷刑罚，<br/>实是荣耀救拔；<br/>非让十架剪除，<br/>不能经历基督；<br/>十架将我结束，<br/>基督才能活出。<br/>','',56112,9647);
INSERT INTO stanza VALUES('Z461','3','十架最终目的，<br/>乃是成功神意；<br/>神意最大仇敌，<br/>乃是人的自己；<br/>治死魂的生命，<br/>自己才能除净；<br/>除去己的性情，<br/>神意才得通行。<br/>','',56113,9648);
INSERT INTO stanza VALUES('Z462','1','十字架的道路要牺牲，<br/>要将一切献于神，<br/>将一切放在<br/>死的祭坛上面，<br/>火才在这里显现。<br/>','',56114,9649);
INSERT INTO stanza VALUES('Z462','chorus','这是十架道路！<br/>你愿否走这个？<br/>你曾否背十架为你主？<br/>你这奉献一切给神的人！<br/>对神你是否全贞？<br/>','',56115,9650);
INSERT INTO stanza VALUES('Z462','2','当我们唱诗祷告时候，<br/>何等愿说『献所有！』<br/>但前面有更沉重的<br/>十字架！<br/>有更艰难的生涯！<br/>','',56116,9651);
INSERT INTO stanza VALUES('Z462','3','你要变节；<br/>或忠心到死，<br/>让一切完全损失，<br/>直等到<br/>永活主的丰盛生命，<br/>天天充满在你灵？<br/>','',56117,9652);
INSERT INTO stanza VALUES('Z462','4','神的救法是由死得生<br/>-你与主合为一人-<br/>在十架你因信<br/>已与祂同钉，<br/>从你身活出祂命。<br/>','',56118,9653);
INSERT INTO stanza VALUES('Z462','5','我们的得失并不要紧，<br/>神的旨意当留心，<br/>我们若将万事<br/>都看如粪土，<br/>主才不会受拦阻。<br/>','',56119,9654);
INSERT INTO stanza VALUES('Z463','1','十架乐接受，<br/>窄路肯行走，<br/>流露生命，不再将主扣；<br/>世界丢背后，<br/>主外无所求，<br/>流露生命，不再将主扣。<br/>','',56120,9655);
INSERT INTO stanza VALUES('Z463','chorus','流露！流露！<br/>流露生命，不再扣留；<br/>流露！流露！<br/>流露生命，不再将主扣。<br/>','',56121,9656);
INSERT INTO stanza VALUES('Z464','1','我若认识复活大能，<br/>必爱十架的模型；<br/>惟死能使生命长成，<br/>若不死了，就不生。<br/>','',56122,9657);
INSERT INTO stanza VALUES('Z464','chorus','不死就不生，<br/>不死就不生，<br/>惟死能使生命长成，<br/>不死就不生。<br/>','',56123,9658);
INSERT INTO stanza VALUES('Z464','2','基督要在我心成形，<br/>我就必须死干净，<br/>天天活在十架阴影，<br/>时时治死魂生命。<br/>','',56124,9659);
INSERT INTO stanza VALUES('Z464','3','惟愿神借永远的灵，<br/>使我与主永同钉；<br/>死在我身发动运行，<br/>生在我身就显明。<br/>','',56125,9660);
INSERT INTO stanza VALUES('Z465','1','我们现在默思<br/>葡萄一生的事：<br/>其路并不容易，<br/>其境也不安逸；<br/>生长不像野地野花，<br/>随地随意自由吐华；<br/>生成曲径迷堂，<br/>生成款式百样。<br/>','',56126,9661);
INSERT INTO stanza VALUES('Z465','2','反之，葡萄开花，<br/>非常渺小无华；<br/>人几不能辨省，<br/>牠竟也曾有英；<br/>花尚未曾开得一日，<br/>即已迅速结为果实，<br/>不得成为骄葩，<br/>自感丰姿可夸。<br/>','',56127,9662);
INSERT INTO stanza VALUES('Z465','3','牠是拴在桩上，<br/>不能随意生长；<br/>牠如伸肢展臂，<br/>也是架上被系；<br/>牠就如此从了砾土，<br/>吸取牠的养生食物；<br/>不能自由拣选，<br/>不能遇难思迁。<br/>','',56128,9663);
INSERT INTO stanza VALUES('Z465','4','是的，绿衣秀美，<br/>春地披上明媚；<br/>因着生命丰裕，<br/>自然生长有余；<br/>直至满身嫩枝细苗，<br/>开始四向飘浮盘绕；<br/>在于青蓝空中，<br/>尝其甘美无穷。<br/>','',56129,9664);
INSERT INTO stanza VALUES('Z465','5','但是园主、园工，<br/>对牠并不放松；<br/>带来刈剪、修刀，<br/>要剥牠的骄傲；<br/>毫不顾惜牠的细嫩，<br/>将牠割得又深又准，<br/>所有多余美穗，<br/>尽都断折破碎。<br/>','',56130,9665);
INSERT INTO stanza VALUES('Z465','6','在牠损失期间，<br/>牠并不敢自怜，<br/>乃是反将自己，<br/>更为完全彻底<br/>交付给那剥夺所有，<br/>使牠成为虚空的手；<br/>牠不浪费生活，<br/>一切都为结果。<br/>','',56131,9666);
INSERT INTO stanza VALUES('Z465','7','那些流血的枝，<br/>渐变坚硬木质；<br/>那些存留的穗，<br/>也渐结果累累；<br/>太阳又来迫牠枯干，<br/>牠叶开始败落四散，<br/>使牠果子盛紫，<br/>直至收成之日。<br/>','',56132,9667);
INSERT INTO stanza VALUES('Z465','7','牠因负重过甚，<br/>以致无枝不沉；<br/>这是长期努力，<br/>受尽琢磨来的；<br/>现今果实已经全美，<br/>自然牠可欣喜自慰；<br/>但是收成就到，<br/>欣慰日子何少！<br/>','',56133,9668);
INSERT INTO stanza VALUES('Z465','9','有手要来摘下，<br/>有脚要来践踏，<br/>葡萄所有宝藏，<br/>在于酒醡之上，<br/>直到丰富、血红的酒，<br/>浩荡有如长江大流，<br/>终日涌溢不息，<br/>喜乐充满大地。<br/>','',56134,9669);
INSERT INTO stanza VALUES('Z465','10','但是葡萄形状，<br/>乃是剥光凄凉：<br/>已经给了一切，<br/>又将进入黑夜，<br/>却无谁人向牠偿还<br/>牠所给人酣醉之欢，<br/>反而将牠再砍，<br/>使成无枝秃干。<br/>','',56135,9670);
INSERT INTO stanza VALUES('Z465','11','然而全冬之间，<br/>牠酒却赐甘甜，<br/>给那寒冷之中，<br/>忧郁愁苦之众；<br/>但是葡萄却在外面，<br/>孤独经历雪地冰天，<br/>坚定忍受一切，<br/>一切可疑、难解！<br/>','',56136,9671);
INSERT INTO stanza VALUES('Z465','12','直到寒冬已过，<br/>牠又豫备结果，<br/>重新萌芽生枝，<br/>再来放绿成姿；<br/>不因已往所受磨难，<br/>心中有了埋怨不甘；<br/>不因所失无限，<br/>而欲减少奉献。<br/>','',56137,9672);
INSERT INTO stanza VALUES('Z465','13','牠的所有呼吸，<br/>尽是高天清气，<br/>并不半点沾染<br/>不洁属地情感；<br/>面向牺牲，依然含笑，<br/>再来接受爱的剥削，<br/>有如从未遇过<br/>损失、痛苦、折磨。<br/>','',56138,9673);
INSERT INTO stanza VALUES('Z465','14','葡萄从牠肢枝，<br/>流酒、流血、流汁，<br/>是否因已舍尽，<br/>牠就变为更贫？<br/>世上醉人、人间浪者，<br/>从牠畅饮，因牠作乐，<br/>是否因了享福，<br/>他们就变更富？<br/>','',56139,9674);
INSERT INTO stanza VALUES('Z465','15','估量生命原则，<br/>以失不是以得；<br/>不视酒饮几多，<br/>乃视酒倾几何；<br/>因为爱的最大能力，<br/>乃是在于爱的舍弃，<br/>谁苦受得最深，<br/>最有，可以给人。<br/>','',56140,9675);
INSERT INTO stanza VALUES('Z465','16','谁待自己最苛，<br/>最易为神选择；<br/>谁伤自己最狠，<br/>最能擦人泪痕；<br/>谁不熟练损失、剥夺，<br/>谁就仅是响钹、鸣锣；<br/>谁能拯救自己，<br/>谁就不能乐极。<br/>','',56141,9676);
INSERT INTO stanza VALUES('Z466','1','『若是死了！』<br/>哦，这是主亲口的信息！<br/>『若是死了，<br/>就必结出许多的子粒。』<br/>','',56142,9677);
INSERT INTO stanza VALUES('Z466','2','人得生命，你若真要，<br/>你就必须死；<br/>落在地里死了，葬了，<br/>就必能结实。<br/>','',56143,9678);
INSERT INTO stanza VALUES('Z466','3','但主不会死中留你，<br/>祂命必逞能；<br/>祂必使你从死复起，<br/>充满了新生。<br/>','',56144,9679);
INSERT INTO stanza VALUES('Z466','4','你愿走主生命道路，<br/>释放祂生命？<br/>当你经过死的路途，<br/>生命才供应。<br/>','',56145,9680);
INSERT INTO stanza VALUES('Z466','5','你要学这有福秘诀：<br/>不死就不生；<br/>倒出生命，直到死绝，<br/>收获必丰盈。<br/>','',56146,9681);
INSERT INTO stanza VALUES('Z467','1','你怎没有伤痕？<br/>没有伤痕<br/>在你身上、肋旁？<br/>你的名声反而远播四方，<br/>他们反而赞美你的光芒？<br/>你怎没有伤痕？<br/>','',56147,9682);
INSERT INTO stanza VALUES('Z467','2','你怎没有伤痕？<br/>我是受迫、孤独、<br/>挂在树上，<br/>四围无情，<br/>都是残忍、狂妄，<br/>我是受了鞭伤、<br/>刺伤、钉伤，<br/>你怎没有伤痕？<br/>','',56148,9683);
INSERT INTO stanza VALUES('Z467','3','怎能你无伤痕？<br/>仆人不比主人更有希望，<br/>先生蒙羞，<br/>学生何能堂皇？<br/>而你却是容易、<br/>完整、无恙！<br/>怎能你无伤痕？<br/>','',56149,9684);
INSERT INTO stanza VALUES('Z467','4','怎能你无伤痕？<br/>他们为我缘故<br/>受人捆绑、<br/>枷锁、监禁、<br/>焚烧或是流放，<br/>或是舍身，<br/>喂狮在于广场，<br/>怎能你无伤痕？<br/>','',56150,9685);
INSERT INTO stanza VALUES('Z467','5','你是没有伤痕！<br/>我是被人摧残，<br/>饮人锋铓，<br/>他们忍受忌恨，<br/>忍受刀棒，<br/>你却平安无事，<br/>不缺宁康，<br/>你却没有伤痕！<br/>','',56151,9686);
INSERT INTO stanza VALUES('Z467','6','你却没有伤痕！<br/>能否是因你向世俗依傍，<br/>是因你怕自己利益失丧，<br/>因你远远跟随，<br/>不甚明朗，<br/>所以没有伤痕？<br/>','',56152,9687);
INSERT INTO stanza VALUES('Z467','7','你怎没有伤痕？<br/>没有疲倦，<br/>只有安然受享？<br/>能否有人忠心，<br/>受人奖赏？<br/>能否有人彻底跟随羔羊，<br/>而他没有伤痕？<br/>','',56153,9688);
INSERT INTO stanza VALUES('Z468','1','我若稍微偏离正路，<br/>我要立刻舒服；<br/>但我记念我主基督，<br/>如何忠心受苦。<br/>','',56154,9689);
INSERT INTO stanza VALUES('Z468','2','我今已经撇弃世界，<br/>所有关系都解；<br/>虽然道路越走越窄，<br/>但我在此是客。<br/>','',56155,9690);
INSERT INTO stanza VALUES('Z468','3','管他世人怒目白眼，<br/>我只求主笑脸；<br/>群众虽然喜欢外貌，<br/>但我要主的『好。』<br/>','',56156,9691);
INSERT INTO stanza VALUES('Z468','4','我心所望不是伟大，<br/>不是今生通达；<br/>我愿现在卑微事主，<br/>那日得祂称许。<br/>','',56157,9692);
INSERT INTO stanza VALUES('Z468','5','我今每日举目细望<br/>审判台前亮光；<br/>愿我所有生活、工作，<br/>那日都能耐火。<br/>','',56158,9693);
INSERT INTO stanza VALUES('Z468','6','让你们去得着名声、<br/>富足、荣耀、友朋，<br/>让你们去得着成功、<br/>赞美、从者、兴隆。<br/>','',56159,9694);
INSERT INTO stanza VALUES('Z468','7','但我只愿孤单、贫穷，<br/>在此不求亨通；<br/>我心切望忠诚跟从<br/>我主到了路终。<br/>','',56160,9695);
INSERT INTO stanza VALUES('Z468','7','因我知道，主在此世<br/>不过得着一死，<br/>所以现在我无他望，<br/>只望因祂失丧。<br/>','',56161,9696);
INSERT INTO stanza VALUES('Z468','9','我的荣耀还在将来，<br/>今日只得忍耐；<br/>我决不肯先我的主，<br/>在此世界得福。<br/>','',56162,9697);
INSERT INTO stanza VALUES('Z468','10','那日我要得着冠冕，<br/>主要拭我泪眼！<br/>今日主既仍旧迟延，<br/>我要忠心进前。<br/>','',56163,9698);
INSERT INTO stanza VALUES('Z469','1','从伯利恒我们动身，<br/>学习耶稣的忠贞，<br/>跟着祂要完全归神，<br/>但是脸上满泪痕；<br/>因为马槽那样寒陋，<br/>并非我们所爱视；<br/>但是脚须与祂同走，<br/>如果手要接赏赐。<br/>','',56164,9699);
INSERT INTO stanza VALUES('Z469','2','经拿撒勒，这条道路，<br/>我们越走越窄小，<br/>多年劳碌无人领悟，<br/>常受羞辱，常无聊。<br/>但神借此教训我们：<br/>如此苦难，是因为<br/>仆人不能大于主人，<br/>所以当同祂流泪。<br/>','',56165,9700);
INSERT INTO stanza VALUES('Z469','3','经加利利，我们见祂<br/>被人厌弃，被人诅；<br/>祂路岂非走错了么？<br/>不然那有许多苦？<br/>不！不！这段虽然崎岖，<br/>祂仍前进平安过；<br/>我们若要同祂高举，<br/>也得前进不畏祸。<br/>','',56166,9701);
INSERT INTO stanza VALUES('Z469','4','随后就在客西马尼，<br/>园中孤单受磨炼，<br/>撒但全军都来攻逼，<br/>这样光景真难遣！<br/>但是我们并不失败，<br/>因有天使来服事，<br/>并说：『应当注目赏赉，<br/>争战不过此一时。』<br/>','',56167,9702);
INSERT INTO stanza VALUES('Z469','5','十架到了！因为所有<br/>忠魂都当经加略；<br/>我们在此同祂蒙羞，<br/>不肯自怜，不退却；<br/>因为不过一点时候，<br/>我们如此感苦痛；<br/>将来见祂，一切忧愁，<br/>要消在祂笑容中。<br/>','',56168,9703);
INSERT INTO stanza VALUES('Z469','6','随到坟墓，亲友环泣，<br/>知道已经无希望；<br/>（亲爱旅伴！世人对你，<br/>是否算为已经亡？）<br/>我们从此与祂同升，<br/>远离属地的追求，<br/>心里欢然失去世人<br/>所谓生命和富有。<br/>','',56169,9704);
INSERT INTO stanza VALUES('Z469','7','我们努力向竿而前，<br/>日近一日仍追随；<br/>我们已经彷佛能见<br/>天城四射的光辉；<br/>我们已经隐约可闻<br/>天乐悠扬的清音；<br/>耶稣在彼迎接我们，<br/>要慰百创的这心。<br/>','',56170,9705);
INSERT INTO stanza VALUES('Z469','7','不过，再过几里，朋友！<br/>腿要不酸，身不累，<br/>不再有罪，不再有忧，<br/>主要擦干你眼泪；<br/>听祂正用柔声说道：<br/>『勿恐，勿馁，仍力前，<br/>因为也许明朝未到，<br/>旅程就已到终点。』<br/>','',56171,9706);
INSERT INTO stanza VALUES('Z470','1','惟有常出代价，<br/>愿背十字架，<br/>我们才会得胜，<br/>才会得权能。<br/>不是自己力量，<br/>不是人思想，<br/>乃是耶稣尊名，<br/>使我们得赢。<br/>','',56172,9707);
INSERT INTO stanza VALUES('Z470','chorus','惟有常出代价，<br/>愿背十字架，<br/>我们才会得胜，<br/>才会得权能。<br/>','',56173,9708);
INSERT INTO stanza VALUES('Z470','2','应当除去夸耀，<br/>绝一切机巧；<br/>我们应当争战，<br/>像耶稣一般：<br/>借死亡得权能，<br/>借失败得胜，<br/>因十字架苦难，<br/>毁坏了撒但。<br/>','',56174,9709);
INSERT INTO stanza VALUES('Z470','3','既勇敢，又温柔，<br/>慈仁且奋斗；<br/>虽工作，亦安息，<br/>刚强却无力；<br/>欲得反倒赐给，<br/>有能却无倚；<br/>虽与救主同钉，<br/>却满有生命。<br/>','',56175,9710);
INSERT INTO stanza VALUES('Z470','4','我们若随救主，<br/>走祂的道路，<br/>必须背十字架，<br/>与祂才融洽。<br/>应当忍耐到底，<br/>虽死亦不避，<br/>直到救主显现，<br/>得血染冠冕。<br/>','',56176,9711);
INSERT INTO stanza VALUES('Z471','1','『破毁带我到主怀！』<br/>毁后如此唱出来！<br/>小船若是紧靠岸，<br/>深怕风浪的为患，<br/>难知在主的怀里，<br/>毁后所享的安息。<br/>','',56177,9712);
INSERT INTO stanza VALUES('Z471','2','我们哀叹：『被破毁！』<br/>岂知『破毁』当赞美！<br/>风浪无情的损伤，<br/>使我主怀享喂养。<br/>在此安息主怀中，<br/>何能再将我摇动？<br/>','',56178,9713);
INSERT INTO stanza VALUES('Z471','3','『破毁』之后，不需要<br/>任何航行的技巧；<br/>虽然仍旧在航行，<br/>却是抛锚在天庭；<br/>再不需要作或虑，<br/>只要我和主同居。<br/>','',56179,9714);
INSERT INTO stanza VALUES('Z471','4','『破毁！』成为我纯益，<br/>其他航者要惊奇：<br/>像似残忍的摧毁，<br/>实是化装的恩惠！<br/>毁后乃是在主手，<br/>有主自己来看守。<br/>','',56180,9715);
INSERT INTO stanza VALUES('Z472','1','死亡不能拘禁复活生命-<br/>神那非受造的永远生命；<br/>刚强、得胜、<br/>无何能以毁坏，<br/>就是基督自己，<br/>已经显明。<br/>','',56181,9716);
INSERT INTO stanza VALUES('Z472','2','死亡不能拘禁复活生命，<br/>虽然死亡集中全力以赴；<br/>死亡不过使这神圣生命<br/>得机显牠能力无量丰富。<br/>','',56182,9717);
INSERT INTO stanza VALUES('Z472','3','死亡不能拘禁复活生命，<br/>治死、埋葬，<br/>不过叫牠繁殖；<br/>所有苦难都是叫牠增长，<br/>并且结出丰盛生命果实。<br/>','',56183,9718);
INSERT INTO stanza VALUES('Z472','4','死亡不能拘禁复活生命，<br/>牠能冲破<br/>所有障碍、阻挡；<br/>胜过黑暗、<br/>阴府所有权势，<br/>吞灭死亡，<br/>并将生命释放。<br/>','',56184,9719);
INSERT INTO stanza VALUES('Z472','5','死亡不能拘禁复活生命，<br/>牠能显出神性所有丰满；<br/>神的公义、圣洁，<br/>牠都产生，<br/>神的荣耀形像牠全彰显。<br/>','',56185,9720);
INSERT INTO stanza VALUES('Z472','6','愿我认识这个复活生命，<br/>每遇死亡，<br/>都让牠力倾出；<br/>使我借着经历永远赏识：复活生命就是活的基督。<br/>','',56186,9721);
INSERT INTO stanza VALUES('Z473','1','由死而生-恩主，这乃是说明，<br/>生命在此，或是在于来世？<br/>不必等候！毁坏破碎的器皿，<br/>即今可在陶人手中陶制。<br/>','',56187,9722);
INSERT INTO stanza VALUES('Z473','2','由死而生-何等奇妙的复活！<br/>种时明感软弱，起时强壮；<br/>你的生命显于劳碌和折磨；<br/>时刻非我，乃是基督我王。<br/>','',56188,9723);
INSERT INTO stanza VALUES('Z473','3','由死而生-客旅道路何孤单，<br/>认识十架者却都愿同行，<br/>效法祂死，他们与祂同苦难，<br/>因祂，就将万事当作有损。<br/>','',56189,9724);
INSERT INTO stanza VALUES('Z473','4','由死而生-何等有福的使命！<br/>从天上的洁清白明江河，<br/>带着活泉，生命洋溢又丰盛，<br/>告诉渴人，从兹无需再渴。<br/>','',56190,9725);
INSERT INTO stanza VALUES('Z474','1','你这因着奔正路，<br/>手垂腿酸之人，<br/>望断以及于耶稣，<br/>免得疲倦灰心；<br/>祂的面光照灿烂，<br/>驱尽困人黑暗，<br/>你若仰望祂荣面，<br/>就必明如中天。<br/>','',56191,9726);
INSERT INTO stanza VALUES('Z474','2','望断以及于耶稣，<br/>你就必不看见<br/>逼迫、艰难与贫苦，<br/>如何四围为患；<br/>没有忧伤的眼泪，<br/>能使你眼失明，<br/>没有惊险的可畏，<br/>能使你心迷蒙。<br/>','',56192,9727);
INSERT INTO stanza VALUES('Z474','3','望断以及于耶稣，<br/>你灵必蒙恩湛，<br/>在这世上有苦楚，<br/>在祂里面平安；<br/>虽在人生苦海中，<br/>时有波浪澎湃，<br/>你若仰望祂面容，<br/>你心必不惊骇。<br/>','',56193,9728);
INSERT INTO stanza VALUES('Z474','4','望断以及于耶稣，<br/>你就不会迷糊，<br/>你若向祂常举目，<br/>祂必指你正路；<br/>当祂领你向前走，<br/>即使遇到云雾，<br/>你若向祂常仰首，<br/>也必不会错误。<br/>','',56194,9729);
INSERT INTO stanza VALUES('Z474','5','望断以及于耶稣，<br/>直到被提上天，<br/>直到荣耀的面目，<br/>完全显你眼前；<br/>今日仰望之荣面，<br/>使你路中得力，<br/>那日变作你颂赞，<br/>使你永远欢喜。<br/>','',56195,9730);
INSERT INTO stanza VALUES('Z475','1','暗中摸索，无一线光明！<br/>何等疲乏！何等劳形！<br/>但一仰望基督你的王，<br/>甚么都必照耀辉煌。<br/>','',56196,9731);
INSERT INTO stanza VALUES('Z475','chorus','转眼将耶稣观看！<br/>注目仰望祂的荣面！<br/>所有事物在祂荣耀光中，<br/>都要次第变色成曚昽。<br/>','',56197,9732);
INSERT INTO stanza VALUES('Z475','2','经过死亡就必得生命，<br/>祂已前去，我们随行；<br/>罪的权势今已经过去，<br/>我们已经得胜有余。<br/>','',56198,9733);
INSERT INTO stanza VALUES('Z475','3','祂的应许终不至落空，<br/>若信靠祂，事事亨通；<br/>所以应当坚定不灰心，<br/>你必经历祂的救恩。<br/>','',56199,9734);
INSERT INTO stanza VALUES('Z476','1','活在生命光中，<br/>不断与主交通，<br/>瞻仰恩主慈容，<br/>顺从圣灵感动，<br/>天天荣上加荣，<br/>时时赞美称颂，<br/>活在生命光中。<br/>','',56200,9735);
INSERT INTO stanza VALUES('Z477','1','用功朝见主面，<br/>多和主对讲，<br/>常住在祂里面，<br/>以祂话为粮。<br/>等候在祂面前，<br/>柔顺且降服，<br/>每件事上不忘<br/>寻求祂祝福。<br/>','',56201,9736);
INSERT INTO stanza VALUES('Z477','2','用功朝见主面，<br/>事务虽忙碌；<br/>多花时间单独<br/>和主在密处。<br/>借着仰望耶稣，<br/>你变祂形像；<br/>在你行为之上，<br/>人见祂模样。<br/>','',56202,9737);
INSERT INTO stanza VALUES('Z477','3','用功朝见主面，<br/>让祂作领导；<br/>任何事情发生，<br/>不在祂前跑；<br/>无论是乐是苦，<br/>始终跟随主，<br/>始终相信祂话，<br/>常仰望耶稣。<br/>','',56203,9738);
INSERT INTO stanza VALUES('Z477','4','用功朝见主面，<br/>内心须宁静；<br/>让祂前来管理<br/>意念和性情。<br/>祂灵把你带到<br/>爱的发源所，<br/>如此你才配作<br/>属天的工作。<br/>','',56204,9739);
INSERT INTO stanza VALUES('Z478','1','亲爱基督精兵，<br/>战场在冲锋，<br/>前曾倚赖自己，<br/>争战难得胜；<br/>勿再倚靠自己，<br/>单靠基督大力；<br/>在那加力基督里，<br/>凡事我都能作。<br/>','',56205,9740);
INSERT INTO stanza VALUES('Z478','2','在你日常分内，<br/>站住为正义，<br/>是否有时厌倦，<br/>感到不容易？<br/>务要投靠救主，<br/>你担祂肯背负：<br/>在那加力基督里，<br/>凡事我都能作。<br/>','',56206,9741);
INSERT INTO stanza VALUES('Z478','3','路中若感疲乏，<br/>祂必愿扶助，<br/>无论你是喜乐，<br/>或者是痛苦；<br/>虽经水深火热，<br/>也必安然渡过：<br/>在那加力基督里，<br/>凡事我都能作。<br/>','',56207,9742);
INSERT INTO stanza VALUES('Z478','4','在这邪恶世界，<br/>试探实频繁，<br/>但你不需跌倒，<br/>撒但必逃窜；<br/>他必全然徒劳，<br/>只要你肯宣告：<br/>在那加力基督里，<br/>凡事我都能作。<br/>','',56208,9743);
INSERT INTO stanza VALUES('Z478','5','基督能力无量，<br/>深广如海洋；<br/>祂能拯救到底，<br/>凡事都担当；<br/>祂的够用恩力，<br/>将我软弱覆庇：<br/>在那加力基督里，<br/>凡事我都能作。<br/>','',56209,9744);
INSERT INTO stanza VALUES('Z479','1','要思想耶稣，<br/>以祂作模型，<br/>好在你身上显出祂荣形：祂已经赐你永远的生命，<br/>并使你享受复活的大能。<br/>','',56210,9745);
INSERT INTO stanza VALUES('Z479','2','要思想耶稣，<br/>天天都如此，<br/>要自甘卑微，<br/>不再有大志；<br/>那无穷生命也要多认识，<br/>靠复活大能经历主的死。<br/>','',56211,9746);
INSERT INTO stanza VALUES('Z479','3','要思想耶稣，<br/>一生当这样，<br/>要活在幔内常见主荣光；<br/>若弃掉自己，<br/>必知主心意，<br/>一脱离自己，<br/>纯洁又安息。<br/>','',56212,9747);
INSERT INTO stanza VALUES('Z479','4','要思想耶稣，<br/>当你在向前，<br/>要一直向上瞻仰祂荣面，<br/>必荣上加荣，<br/>变成祂形状，<br/>使祂的形像显在你身上。<br/>','',56213,9748);
INSERT INTO stanza VALUES('Z480','1','你们能否顺从<br/>你一切的主，<br/>如果地要震动，<br/>天象要翻覆？<br/>你们能否相信，<br/>神与你同在，<br/>就是灾祸忽临，<br/>必定不见害？<br/>','',56214,9749);
INSERT INTO stanza VALUES('Z480','2','你们能否顺从<br/>所事奉的主，<br/>不稍软弱、惊恐，<br/>也不稍让步？<br/>虽然你的前途<br/>好像是死路，<br/>此时能否顺服，<br/>而不一自顾？<br/>','',56215,9750);
INSERT INTO stanza VALUES('Z480','3','你真能否顺从，<br/>如果主召你<br/>加入前线进攻，<br/>抵御凶仇敌？<br/>你真能否立前，<br/>欢喜受差遣？<br/>你真能否争战，<br/>直到晚色遍？<br/>','',56216,9751);
INSERT INTO stanza VALUES('Z480','4','能否？我的弟兄，<br/>你神已久等，<br/>应当服祂权柄，<br/>遵行祂命令。<br/>你若作主精兵，<br/>当祂再降临，<br/>祂要题起你名，<br/>并说你『忠心！』<br/>','',56217,9752);
INSERT INTO stanza VALUES('Z481','1','应当一无罣虑，<br/>主已经近了；<br/>应当信神应许，<br/>平安不动摇；<br/>你切不可失败，<br/>也不可失检，<br/>因耶稣快要来，<br/>也许是今天。<br/>','',56218,9753);
INSERT INTO stanza VALUES('Z481','2','应当一无罣虑，<br/>凡事交托主；<br/>祂替你罪受鞫，<br/>必替你担苦。<br/>你当自由进前，<br/>寻机会证明：<br/>祂爱心的甘甜，<br/>祂手的坚定。<br/>','',56219,9754);
INSERT INTO stanza VALUES('Z481','3','应当一无罣虑；<br/>即云主迟延，<br/>祂能力要扶勗<br/>你终身无间；<br/>你可相信祂心，<br/>你可靠祂手，<br/>这样有何可惊，<br/>当力前勿愁。<br/>','',56220,9755);
INSERT INTO stanza VALUES('Z482','1','神的应许不能废去，<br/>句句都是坚定；<br/>信心从来不用凭据，<br/>因神言出必行。<br/>','',56221,9756);
INSERT INTO stanza VALUES('Z482','chorus','天地虽能被焚烧，<br/>小山大山虽倾倒，<br/>但那相信主的人，<br/>必见主话得成。<br/>','',56222,9757);
INSERT INTO stanza VALUES('Z482','2','你心应该像亚伯兰，<br/>那样举目望天，<br/>数算众星，轻看艰难，<br/>信心越久越坚。<br/>','',56223,9758);
INSERT INTO stanza VALUES('Z482','3','即使黑云暂时浓厚，<br/>云上太阳未变，<br/>只要再过一点时候，<br/>阳光就要显现。<br/>','',56224,9759);
INSERT INTO stanza VALUES('Z482','4','虽遇试炼，仍要镇定，<br/>因为在火窑中，<br/>有荣耀的神子同行，<br/>仇敌终要击空。<br/>','',56225,9760);
INSERT INTO stanza VALUES('Z482','5','纵然朋友都辜负你，<br/>但你还当信神，<br/>因为耶稣你的能力，<br/>仍然亲近施恩。<br/>','',56226,9761);
INSERT INTO stanza VALUES('Z482','6','凡事倚赖神的大力，<br/>直到被提上天；<br/>现在所望所深信的，<br/>将来都必实现。<br/>','',56227,9762);
INSERT INTO stanza VALUES('Z483','1','前进！是我口号，<br/>步声相接联；<br/>向着标竿直跑，<br/>永不回头看。<br/>军前火柱灿烂，<br/>照明我路程；<br/>谁还畏缩不前，<br/>基督在率领。<br/>前进！经过旷野，<br/>经过苦战争；<br/>迦南不再隐约，<br/>锡安放光明。<br/>','',56228,9763);
INSERT INTO stanza VALUES('Z483','2','荣耀又加荣耀，<br/>父神已豫备；<br/>凡爱神者必要<br/>有分于此内：<br/>眼睛未曾看见，<br/>耳朵未曾听，<br/>荣耀达到极点，<br/>心想也未曾。<br/>前进！一直前进！<br/>直到国度显，<br/>直到幔子不存，<br/>信心变眼见。<br/>','',56229,9764);
INSERT INTO stanza VALUES('Z483','3','前进！天就要明，<br/>圣城在眼前；<br/>天上耶路撒冷，<br/>等你尝新鲜。<br/>进入自由荣光，<br/>得戴荣耀冕。<br/>与主基督同王，<br/>掌权到永远。<br/>向彼，前进！向彼，<br/>奔完你程途，<br/>靠主大能大力，<br/>前进！入国度。<br/>','',56230,9765);
INSERT INTO stanza VALUES('Z484','1','当向标竿力前！<br/>虽然孤单，不变；<br/>那开路者现在召你，<br/>所以当前勿延。<br/>','',56231,9766);
INSERT INTO stanza VALUES('Z484','2','当向标竿力前！<br/>主眼睛像火焰，<br/>正在看你；人算甚么？<br/>何必管他喜厌！<br/>','',56232,9767);
INSERT INTO stanza VALUES('Z484','3','当向标竿力前！<br/>不要再望后面，<br/>因为前头就是奖赏，<br/>主要赐给冠冕。<br/>','',56233,9768);
INSERT INTO stanza VALUES('Z484','4','当向标竿力前！<br/>塞耳、哑口、闭眼，<br/>在崎岖的血迹路上，<br/>紧随基督向前！<br/>','',56234,9769);
INSERT INTO stanza VALUES('Z485','1','靠着恩主全能神，<br/>往前走！往前走！<br/>抓住应许凭信心，<br/>往前走！<br/>含地永不再逗遛，<br/>埃及从此丢背后，<br/>就此一去不回头，<br/>往前走！<br/>','',56235,9770);
INSERT INTO stanza VALUES('Z485','2','虽然后面仇敌追，<br/>往前走！往前走！<br/>虽然前面是深水，<br/>往前走！<br/>深水为你必分开，<br/>仇敌全都必淹埋，<br/>救恩使你必奏凯，<br/>往前走！<br/>','',56236,9771);
INSERT INTO stanza VALUES('Z485','3','白昼云柱来引导，<br/>往前走！往前走！<br/>黑夜火柱来光照，<br/>往前走！<br/>饥饿，吗哪必降来，<br/>干渴，磐石必裂开，<br/>遇敌，尼西必击败，<br/>往前走！<br/>','',56237,9772);
INSERT INTO stanza VALUES('Z485','4','旷野道路虽艰险，<br/>往前走！往前走！<br/>跟随约柜直往前，<br/>往前走！<br/>往前！直到过约但，<br/>往前！直到进迦南！<br/>往前！n直到在锡安，<br/>往前走！<br/>','',56238,9773);
INSERT INTO stanza VALUES('Z485','1','儆醒阿，黑夜已深！<br/>儆醒，莫恋红尘；<br/>儆醒阿，白昼将近！<br/>儆醒，莫睡沉。<br/>儆醒阿，主就要来！<br/>儆醒，莫松腰带；<br/>儆醒阿，主在等待！<br/>儆醒，莫懈怠。<br/>','',56239,9774);
INSERT INTO stanza VALUES('Z485','2','儆醒阿，起来事奉！<br/>时间已到末点；<br/>儆醒阿，前来作工！<br/>年日已将残。<br/>儆醒阿，穿上军装！<br/>儆醒，灵要刚强；<br/>儆醒阿，将魔抵挡！<br/>儆醒，心要壮。<br/>','',56240,9775);
INSERT INTO stanza VALUES('Z485','3','儆醒阿，等候救主！<br/>晨星就要出现；<br/>儆醒阿，追求国度！<br/>荣耀在眼前。<br/>儆醒阿，务要儆醒！<br/>儆醒，等待主来！<br/>儆醒阿，儆醒莫停！<br/>儆醒到主来！<br/>','',56241,9776);
INSERT INTO stanza VALUES('Z487','1','灵要操练运用，<br/>魂却要拒绝；<br/>无论生活行动，<br/>以此为秘诀。<br/>','',56242,9777);
INSERT INTO stanza VALUES('Z487','2','灵要操练运用，<br/>规条要弃绝；<br/>恩膏涂抹顺从，<br/>时刻无间歇。<br/>','',56243,9778);
INSERT INTO stanza VALUES('Z487','3','灵要操练运用，<br/>己意要拒绝；<br/>活在生命光中，<br/>让主作一切。<br/>','',56244,9779);
INSERT INTO stanza VALUES('Z487','4','灵肯操练运用，<br/>魂肯全拒绝，<br/>就能赞美、称颂，<br/>问题全解决。<br/>','',56245,9780);
INSERT INTO stanza VALUES('Z487','5','灵肯操练运用，<br/>主就有出路；<br/>灵肯操练运用，<br/>我就享丰富。<br/>','',56246,9781);
INSERT INTO stanza VALUES('Z487','6','灵肯操练运用，<br/>主就能摸到；<br/>灵肯操练运用，<br/>我就被建造。<br/>','',56247,9782);
INSERT INTO stanza VALUES('Z487','7','灵要操练运用，<br/>这是主所要；<br/>灵肯操练运用，<br/>主就得荣耀。<br/>','',56248,9783);
INSERT INTO stanza VALUES('Z488','1','何必担心一握不释？<br/>且让先知先果腹；<br/>若是神管你的度支，<br/>你的来源何患枯？<br/>每天都有新的需要，<br/>每天必有新供给；<br/>你既然是祂所创造，<br/>祂岂不为你设计？<br/>','',56249,9784);
INSERT INTO stanza VALUES('Z488','chorus','仍然当爱，仍然当给，<br/>照旧你还余一握；<br/>所有的爱，所有的给，<br/>要使神赐加倍多。<br/>','',56250,9785);
INSERT INTO stanza VALUES('Z488','2','相信！时候不至耽搁，<br/>虽是不快，总不慢；<br/>相信！瓶子不至干涸，<br/>永远不空，也不满。<br/>纵使百合缺了衣衫，<br/>纵使小鸟无食啄，<br/>但是寡妇微小面坛，<br/>必定依然有一握。<br/>','',56251,9786);
INSERT INTO stanza VALUES('Z488','3','何必豫料明天境遇，<br/>目前够了就可乐；<br/>何必先借明天忧虑，<br/>手里岂非还有着！<br/>爱是生活，给反存留，<br/>种得多的收也多；<br/>好像你已罄你所有，<br/>看哪！你还有一握！<br/>','',56252,9787);
INSERT INTO stanza VALUES('Z489','1','你曾觉得父爱心？<br/>不只这么一点；<br/>你曾尝到祂怜悯？<br/>不只这么一点。<br/>父的慈爱何等大，<br/>不只这么一点；<br/>平白赐给无代价，<br/>不只这么一点。<br/>','',56253,9788);
INSERT INTO stanza VALUES('Z489','chorus','多又多，多又多，<br/>不只这么一点，<br/>神的大爱难尽说，<br/>不只这么一点。<br/>','',56254,9789);
INSERT INTO stanza VALUES('Z489','2','你曾觉得主亲近？<br/>不只这么一点；<br/>祂的同在乐你心？<br/>不只这么一点；<br/>主的恩典何等大，<br/>不只这么一点；<br/>平白赐给无代价，<br/>不只这么一点。<br/>','',56255,9790);
INSERT INTO stanza VALUES('Z489','3','你觉圣灵的能力？<br/>不只这么一点；<br/>犹如甘雨临及你？<br/>不只这么一点。<br/>圣灵能力何等大，<br/>不只这么一点；<br/>平白赐给无代价，<br/>不只这么一点。<br/>','',56256,9791);
INSERT INTO stanza VALUES('Z490','1','我常居住天爱中，<br/>不怕改变一点；<br/>如此把握不落空，<br/>在此没有改变。<br/>也许狂风四面起，<br/>也许无多希望；<br/>但神四面来护庇，<br/>我怎能够徬徨？<br/>','',56257,9792);
INSERT INTO stanza VALUES('Z490','2','穷困难迫我回头，<br/>任主领我何方；<br/>我不至有何不够，<br/>我的牧人在旁。<br/>祂的慧心常清醒，<br/>祂的明眼不眛，<br/>祂知祂行的路径，<br/>我要始终跟随。<br/>','',56258,9793);
INSERT INTO stanza VALUES('Z490','3','青草地场尚在前，<br/>是我从所未见；<br/>再过就是清朗天，<br/>今虽稠云绵绵。<br/>我的希望真久长，<br/>我的途径光明，<br/>救主掌握我宝藏，<br/>祂要和我同行。<br/>','',56259,9794);
INSERT INTO stanza VALUES('Z490','4','或许明朝天未晓，<br/>我灵不及等待，<br/>就脱肉体全不要，<br/>主，就与你同在。<br/>安息！睡眠！何宝贵，<br/>有你保护照顾；<br/>或许你忽荣耀归，<br/>召我座前相晤！<br/>','',56260,9795);
INSERT INTO stanza VALUES('Z490','5','那时看见你自己，<br/>被众选民拥挤，<br/>又是荣耀又美丽，<br/>又是歌唱无已。<br/>奇妙应许的日期，<br/>我们能够同你<br/>永远享受神安息，<br/>永远喜乐满意。<br/>','',56261,9796);
INSERT INTO stanza VALUES('Z491','1','『我必与你同在，』<br/>甜美的应许，<br/>安慰我的心怀，<br/>消除我惊惧；<br/>在此幽暗长夜，<br/>主是我盾牌，<br/>永不将我弃绝，<br/>必与我同在。<br/>','',56262,9797);
INSERT INTO stanza VALUES('Z491','chorus','主与我同在，<br/>主与我同在，<br/>主曾应许与我同在，<br/>直到永远不离开；<br/>主与我同在，<br/>主与我同在，<br/>主曾应许与我同在，<br/>直到永远不离开。<br/>','',56263,9798);
INSERT INTO stanza VALUES('Z491','2','四围鲜花败落，<br/>主爱不凋残，<br/>地上日光灭没，<br/>天光仍灿烂；<br/>主如一袋没药，<br/>整夜在我怀，<br/>直到晨曦破晓，<br/>必与我同在。<br/>','',56264,9799);
INSERT INTO stanza VALUES('Z491','3','前途虽然艰困，<br/>试炼要来临，<br/>但主必更亲近，<br/>必说『可放心；』<br/>喜乐犹如春鸟，<br/>飞入我心怀，<br/>使我甜美唱道：<br/>『主与我同在！』<br/>','',56265,9800);
INSERT INTO stanza VALUES('Z492','1','在祂翼下，<br/>平安稳妥我居住，<br/>不管夜色多深，<br/>且有风雨；<br/>但我能信靠，<br/>我知祂必眷顾，<br/>因祂已救我，<br/>我是祂儿女。<br/>','',56266,9801);
INSERT INTO stanza VALUES('Z492','chorus','在祂翼下，<br/>在祂翼下，<br/>谁能使我离祂爱！<br/>在祂翼下，<br/>这是我的家，<br/>我必与主永同在。<br/>','',56267,9802);
INSERT INTO stanza VALUES('Z492','2','在祂翼下，<br/>我能躲过我忧伤，<br/>我心满足，<br/>我能在此安歇，<br/>世上并无膏油<br/>可治我病创，<br/>在此我得祝福，<br/>我得慰借。<br/>','',56268,9803);
INSERT INTO stanza VALUES('Z492','3','在祂翼下，<br/>何等宝贵的享受！<br/>一生在此，<br/>直到试炼过去；<br/>有主保护荫庇，<br/>无何再添愁，<br/>安息于主，<br/>我是永远无虞。<br/>','',56269,9804);
INSERT INTO stanza VALUES('Z493','1','应当住在神的翅下，<br/>神必定顾念你；<br/>任何遭遇不要惊怕，<br/>神必定顾念你。<br/>','',56270,9805);
INSERT INTO stanza VALUES('Z493','chorus','神必定顾念你，<br/>时时顾念，处处顾念，<br/>祂必定顾念你，<br/>神必定顾念你。<br/>','',56271,9806);
INSERT INTO stanza VALUES('Z493','2','时因困难心中失望，<br/>神必定顾念你；<br/>时遇险恶无处隐藏，<br/>神必定顾念你。<br/>','',56272,9807);
INSERT INTO stanza VALUES('Z493','3','无一祈求祂会推诿，<br/>神必定顾念你；<br/>所有需要祂必豫备，<br/>神必定顾念你。<br/>','',56273,9808);
INSERT INTO stanza VALUES('Z493','4','无论你遇何种试炼，<br/>神必定顾念你；<br/>疲倦的人，靠祂胸前，<br/>神必定顾念你。<br/>','',56274,9809);
INSERT INTO stanza VALUES('Z494','1','当你经过试炼，<br/>茫然无所从，<br/>你心绝望，<br/>以为甚么都失踪；<br/>就当数主祝福，<br/>当一一的数，<br/>你就要希奇<br/>祂曾如何眷顾。<br/>','',56275,9810);
INSERT INTO stanza VALUES('Z494','chorus','数主祝福！<br/>要一一的数！<br/>记看祂曾如何眷顾你！<br/>数主祝福！<br/>要一一的数！<br/>你就要希奇<br/>祂曾如何爱你。<br/>','',56276,9811);
INSERT INTO stanza VALUES('Z494','2','当你有所罣虑，<br/>如同挑重担，<br/>觉得所要负的<br/>十架苦难堪，<br/>你若数主祝福，<br/>疑惑要消散，<br/>并要不止住的<br/>欢乐和颂赞。<br/>','',56277,9812);
INSERT INTO stanza VALUES('Z494','3','当你看见别人<br/>属世的亨通，<br/>你若念主应许，<br/>心就不会动；<br/>你所受的祝福，<br/>原来无处买，<br/>你有了父的家，<br/>又有主的爱。<br/>','',56278,9813);
INSERT INTO stanza VALUES('Z494','4','所以，无论遇见<br/>大小的试探，<br/>不必灰心，<br/>万事总有主承担，<br/>你若数主祝福，<br/>天使要来临，<br/>伺候你，服侍你，<br/>直到你路尽。<br/>','',56279,9814);
INSERT INTO stanza VALUES('Z495','1','路途遥远，负担沉着，<br/>力尽身疲要倒下；<br/>请听主声，柔然轻说：<br/>重担当托耶和华。<br/>','',56280,9815);
INSERT INTO stanza VALUES('Z495','chorus','重担当托耶和华，<br/>重担当托耶和华，<br/>主会安慰你，<br/>又会坚固你，<br/>重担当托耶和华。<br/>','',56281,9816);
INSERT INTO stanza VALUES('Z495','2','双脚已软，双手已酸，<br/>灯火将灭目又花，<br/>眼见就要心灰气短，<br/>重担当托耶和华。<br/>','',56282,9817);
INSERT INTO stanza VALUES('Z495','3','亲友离散，遭遇凄凉，<br/>忧心难解常悬罣，<br/>一身难受如此创伤，<br/>重担当托耶和华。<br/>','',56283,9818);
INSERT INTO stanza VALUES('Z495','4','孤单软弱，无所傍倚，<br/>心绪起落乱如麻，<br/>都是因为我们忘记<br/>重担当托耶和华。<br/>','',56284,9819);
INSERT INTO stanza VALUES('Z495','5','祂会安慰，祂会坚固，<br/>祂要使你力有加，<br/>祂要使你心境安舒，<br/>重担当托耶和华。<br/>','',56285,9820);
INSERT INTO stanza VALUES('Z496','1','当我遇见试炼灾殃，<br/>经过荆棘豺狼之疆，<br/>我有一个甘美思想，<br/>就是主怀念我。<br/>','',56286,9821);
INSERT INTO stanza VALUES('Z496','chorus','主，你正怀念我！<br/>主，你正怀念我！<br/>我怕甚么？<br/>有你亲近，<br/>并且还怀念我！<br/>','',56287,9822);
INSERT INTO stanza VALUES('Z496','2','今生忧虑、苦难、折磨，<br/>使我心思都变昏黑，<br/>但是苦境使我记得：<br/>主，你正怀念我！<br/>','',56288,9823);
INSERT INTO stanza VALUES('Z496','3','所以，无论愁云多少，<br/>无论安乐，或是苦恼，<br/>我已满足，因我知道：<br/>主还是怀念我。<br/>','',56289,9824);
INSERT INTO stanza VALUES('Z497','1','神阿，<br/>你名何等广大泱漭！<br/>我今投身其中，<br/>心顶安然；<br/>有你够了，<br/>无论日有多长；<br/>有你够了，<br/>无论夜有多暗。<br/>','',56290,9825);
INSERT INTO stanza VALUES('Z497','2','有你够了，<br/>无论事多纷烦；<br/>有你够了，<br/>无论境多寂寞；<br/>有你，<br/>我就已经能够尽欢，<br/>有你，<br/>我就已经能够唱歌。<br/>','',56291,9826);
INSERT INTO stanza VALUES('Z497','3','你是我神！<br/>全有！全足！全丰！<br/>你能为我创造我所缺乏；<br/>有你自己，<br/>在我回家途中，<br/>无论有何需要，<br/>都必无差。<br/>','',56292,9827);
INSERT INTO stanza VALUES('Z497','4','我的神阿，<br/>你在已过路上，<br/>曾用爱的神迹多方眷顾；<br/>故我敢再投入你的胸膛，<br/>因信心安，<br/>赞美你的道路。<br/>','',56293,9828);
INSERT INTO stanza VALUES('Z498','1','时常携带耶稣的名，<br/>你们忧愁困苦人，<br/>祂能赐你安慰、安宁，<br/>除去所有的烦闷。<br/>','',56294,9829);
INSERT INTO stanza VALUES('Z498','chorus','宝贝名，何甘甜！<br/>世之望和天之乐！<br/>宝贝名，何甘甜！<br/>世之望和天之乐。<br/>','',56295,9830);
INSERT INTO stanza VALUES('Z498','2','时常携带耶稣的名，<br/>当作籐牌敌火箭；<br/>每逢诱惑搅扰你灵，<br/>呼吸这名在心间。<br/>','',56296,9831);
INSERT INTO stanza VALUES('Z498','3','当祂爱手抚摩、安慰，<br/>当我舌头在歌唱，<br/>耶稣的名何等宝贝，<br/>使我心头满欢畅。<br/>','',56297,9832);
INSERT INTO stanza VALUES('Z498','4','等到被提、面见救主，<br/>耶稣的名仍颂扬，<br/>在祂脚前欢然俯伏，<br/>尊敬祂为王中王。<br/>','',56298,9833);
INSERT INTO stanza VALUES('Z499','1','非我所是，<br/>主阿，乃你所是，<br/>只有这个会叫我心安宁；<br/>你(非我)爱<br/>会叫疑惑消失，<br/>会叫起伏心怀<br/>风平、波静。<br/>','',56299,9834);
INSERT INTO stanza VALUES('Z499','2','祂今赐福，<br/>并要永远赐福，<br/>祂今救我，<br/>并要永远救我，<br/>祂要扶我，<br/>在此无倚中途，<br/>祂要领我危关<br/>平安度过。<br/>','',56300,9835);
INSERT INTO stanza VALUES('Z499','3','我主、我神！<br/>我的对你认识，<br/>使我心满平安，<br/>口满歌唱；<br/>你是我的生命、<br/>喜乐、杖子，<br/>倚身于你，<br/>使我软弱变强。<br/>','',56301,9836);
INSERT INTO stanza VALUES('Z499','4','我是缺乏、饥渴，<br/>我这心怀<br/>焦慕这里所难寻的甘甜：<br/>恋人逐渐离开，<br/>他们离开<br/>留下空隙<br/>为着更为可恋。<br/>','',56302,9837);
INSERT INTO stanza VALUES('Z499','5','更多的你，<br/>求你时刻启迪，<br/>更多你的荣耀，<br/>我主、我神！<br/>更多的你，<br/>在于恩典、能力，<br/>更多你的怜悯<br/>赐给我身。<br/>','',56303,9838);
INSERT INTO stanza VALUES('Z500','1','神操未知事件之钥，<br/>我觉欢喜；<br/>若是祂托别人代劳，<br/>或是授权叫我照料，<br/>我就叹息。<br/>我就叹息。<br/>','',56304,9839);
INSERT INTO stanza VALUES('Z500','2','若是我的明天烦恼，<br/>今天临到，<br/>而又没有明天关照，<br/>我就不知怎样是好！<br/>无法祷告。<br/>','',56305,9840);
INSERT INTO stanza VALUES('Z500','3','就因我的眼目不明，<br/>我反安全；<br/>我在暗中摸索失凭，<br/>祂手能觉，祂声能听，<br/>祂并不远。<br/>','',56306,9841);
INSERT INTO stanza VALUES('Z500','4','祂的计划我是不晓，<br/>但我能知：<br/>祂的笑脸如光照耀，<br/>祂的恩典不断领导，<br/>在于此世。<br/>','',56307,9842);
INSERT INTO stanza VALUES('Z500','5','够了，这已包罗万有，<br/>我可安息！<br/>我所不能，祂都能救，<br/>有祂替我事事讲究，<br/>我不着急。<br/>','',56308,9843);
INSERT INTO stanza VALUES('Z501','1','安稳在基督手臂，<br/>安稳在主怀里；<br/>在此祂爱常覆翼，<br/>我魂满得安息。<br/>这是天来的佳音，<br/>慰我惊恐心情，<br/>这是众圣的讴吟，<br/>我要和声颂称。<br/>','',56309,9844);
INSERT INTO stanza VALUES('Z501','chorus','安稳在基督手臂，<br/>安稳在主怀里；<br/>在此祂爱常覆翼，<br/>我魂满得安息。<br/>','',56310,9845);
INSERT INTO stanza VALUES('Z501','2','安稳在基督手臂，<br/>安稳在主怀里；<br/>在此祂恩时临及，<br/>犹如甘露滴沥。<br/>虽然试炼未全历，<br/>眼泪尚余几滴，<br/>危难、惊惧或忧疑，<br/>在此莫能我袭。<br/>','',56311,9846);
INSERT INTO stanza VALUES('Z501','3','安稳在基督手臂，<br/>安稳在主怀里；<br/>永久磐石之圣翼，<br/>将我全人遮蔽。<br/>在此我耐候依依，<br/>直到夜影飞散，<br/>直到那可爱晨曦，<br/>破晓在我眼前。<br/>','',56312,9847);
INSERT INTO stanza VALUES('Z502','1','来罢，忧伤的人，<br/>随带你烦恼，<br/>向着施恩宝座虔诚屈膝；<br/>来陈你心创痕，<br/>来诉你困扰，<br/>地无一个忧伤天不能医。<br/>','',56313,9848);
INSERT INTO stanza VALUES('Z502','2','孤单中的喜乐，<br/>迷途的光照，<br/>痛悔者的希望-<br/>祂永不变；<br/>保惠师正在此<br/>柔声的说道：<br/>地无一个忧伤天不能遣。<br/>','',56314,9849);
INSERT INTO stanza VALUES('Z502','3','这是生命的饼，<br/>滋养又甘甜，<br/>这是生命的水，<br/>流自宝座；<br/>来赴主的爱筵，<br/>心中常思念：<br/>地无一个忧伤天不能脱。<br/>','',56315,9850);
INSERT INTO stanza VALUES('Z503','1','听哪，天上有声喊说：<br/>『已成了；』<br/>信心立即回声答说：<br/>『已成了。』<br/>','',56316,9851);
INSERT INTO stanza VALUES('Z503','chorus','请听宝座的话语，<br/>你可来领神应许；<br/>神口曾说：<br/>『已成了，』<br/>信心也说：<br/>『已成了；』<br/>祈祷已过赞美始，<br/>阿利路亚，<br/>『已成了。』<br/>','',56317,9852);
INSERT INTO stanza VALUES('Z503','2','接受主的完全救恩，<br/>『已成了；』<br/>应当绝对奉献全身，<br/>『已成了。』<br/>','',56318,9853);
INSERT INTO stanza VALUES('Z503','3','领取神的医治恩约，<br/>『已成了；』<br/>只要相信，不要感觉，<br/>『已成了。』<br/>','',56319,9854);
INSERT INTO stanza VALUES('Z503','4','对神应许应当说道：<br/>『已成了；』<br/>对神话语应当认道：<br/>『已成了。』<br/>','',56320,9855);
INSERT INTO stanza VALUES('Z503','5','按祂所说来相信祂，<br/>『已成了；』<br/>这个就是接受秘法，<br/>『已成了。』<br/>','',56321,9856);
INSERT INTO stanza VALUES('Z504','1','你这奋斗的信徒，<br/>你不当再奋斗，<br/>主有更好的道路，<br/>何必这样苦筹。<br/>','',56322,9857);
INSERT INTO stanza VALUES('Z504','chorus','我主的话可算得数，<br/>哦，主的话算得数；<br/>我不必这样疑惑，<br/>不必苦求不辍，<br/>我当安息，不当奔波，<br/>因主的话算得数。<br/>','',56323,9858);
INSERT INTO stanza VALUES('Z504','2','你当服降主旨意，<br/>被杀仍要相信；<br/>停止所有的问题，<br/>今天就此决定。<br/>','',56324,9859);
INSERT INTO stanza VALUES('Z504','3','为何这样的起倒！<br/>应当靠祂应许，<br/>抛出信心当铁锚，<br/>今天就此定局。<br/>','',56325,9860);
INSERT INTO stanza VALUES('Z504','4','主，我今不再挣扎，<br/>一切向你交托，<br/>永远相信你的话，<br/>今天就此着落。<br/>','',56326,9861);
INSERT INTO stanza VALUES('Z505','1','主阿，即或尽是黑暗，<br/>尽是坎坷忧悒，<br/>但我仍要镇定安然，<br/>寻求你的心意。<br/>','',56327,9862);
INSERT INTO stanza VALUES('Z505','2','你有怜悯，你有恩慈，<br/>你有宝贵应许；<br/>你不会错，你不会迟，<br/>你不翻云覆雨。<br/>','',56328,9863);
INSERT INTO stanza VALUES('Z505','3','大能的主，说有就有，<br/>命立没有不立；<br/>有主就可无罣无忧，<br/>就可不焦不急。<br/>','',56329,9864);
INSERT INTO stanza VALUES('Z505','4','主阿，因你我心定了，<br/>因你我魂安歇；<br/>我赞美说：有主够了！<br/>主是包括一切！<br/>','',56330,9865);
INSERT INTO stanza VALUES('Z505','5','主，我还要求你的灵，<br/>使我信心充足，<br/>领我更深认识你名，<br/>进入你的丰富。<br/>','',56331,9866);
INSERT INTO stanza VALUES('Z506','1','祂不误事，因祂是神！<br/>祂不误事，祂乐施恩！<br/>祂不误事，祂已许过！<br/>我们有神，还怕谁何？<br/>','',56332,9867);
INSERT INTO stanza VALUES('Z506','2','有何高山你不能锄？<br/>有何深水你不能渡？<br/>我们的神专门处置<br/>人所以为不能的事。<br/>','',56333,9868);
INSERT INTO stanza VALUES('Z506','3','是祂使铁浮水而起，<br/>是祂使海分成干地，<br/>是祂使日半空停止，<br/>我们的神并无难事！<br/>','',56334,9869);
INSERT INTO stanza VALUES('Z506','4','祂使软沙作海界限，<br/>波浪虽狂，不能再前；<br/>祂是你神，还有甚么<br/>祂是不能为你工作？<br/>','',56335,9870);
INSERT INTO stanza VALUES('Z506','5','祂心爱你，知你难处，<br/>所以应许祂要照顾；<br/>我们的神充满怜悯，<br/>对待祂的无告子民。<br/>','',56336,9871);
INSERT INTO stanza VALUES('Z506','6','我们的神不能不义，<br/>不能将祂应许忘记；<br/>祂的应许在基督里，<br/>都是阿们，都是是的。<br/>','',56337,9872);
INSERT INTO stanza VALUES('Z506','7','我们的神不能失信，<br/>祂的恩约永远坚定，<br/>祂要照祂应许，答应<br/>我们因信所发呼声。<br/>','',56338,9873);
INSERT INTO stanza VALUES('Z506','7','我们因信欢乐唱说：<br/>祂不误我，祂已许过！<br/>祂不误我，祂乐施恩！<br/>祂不误我，因祂是神！<br/>','',56339,9874);
INSERT INTO stanza VALUES('Z507','1','主，你作我的领港，<br/>来过此人生风浪；<br/>前面是未识水道，<br/>浮沙外加上暗礁；<br/>你当赐南针图状，<br/>主，你作我的领港。<br/>','',56340,9875);
INSERT INTO stanza VALUES('Z507','2','慈母能平定婴孩，<br/>你也能镇静狂海；<br/>当你说应当安静，<br/>风和浪立听命令；<br/>你真是奇妙的王，<br/>主，你作我的领港。<br/>','',56341,9876);
INSERT INTO stanza VALUES('Z507','3','到至终我近彼岸，<br/>可怕的激浪摇撼；<br/>在我与平安之间，<br/>当我正倚你身边，<br/>让我听你对我讲：<br/>不要怕，是我领港。<br/>','',56342,9877);
INSERT INTO stanza VALUES('Z508','1','一路我蒙救主引领，<br/>陈腐事物何必求？<br/>难道我还疑祂爱情，<br/>毕生既由祂拯救？<br/>神圣安慰、属天生活，<br/>凭信我可从祂得；<br/>我深知道凡事临我，<br/>祂有美意不必测。<br/>我深知道凡事临我，<br/>祂有美意不必测。<br/>','',56343,9878);
INSERT INTO stanza VALUES('Z508','2','一路我蒙救主引领，<br/>鼓励我走每步路；<br/>供我灵粮，长我生命，<br/>帮助我历每次苦。<br/>旅程虽然力不能支，<br/>心、灵虽然渴难当，<br/>看哪，面前就是磐石，<br/>喜乐活泉可来尝。<br/>','',56344,9879);
INSERT INTO stanza VALUES('Z508','3','一路我蒙救主引领，<br/>哦，主大爱何丰满，<br/>不久我到父的怀中，<br/>得享应许的平安。<br/>我灵披上荣耀身躯，<br/>飞入无夜光明处，<br/>我要永远唱此佳句，<br/>蒙祂引领我一路。<br/>','',56345,9880);
INSERT INTO stanza VALUES('Z509','1','你这奔向荣耀客旅，<br/>疲倦困乏心迷离；<br/>神已赐你宝贵应许：<br/>『我必用眼引导你。』<br/>','',56346,9881);
INSERT INTO stanza VALUES('Z509','chorus','『我必引导，我必引导，<br/>我必用眼引导你；<br/>你这奔向荣耀客旅，<br/>我必用眼引导你。』<br/>','',56347,9882);
INSERT INTO stanza VALUES('Z509','2','虽然心中常是纷乱，<br/>情绪扰人欲昏迷，<br/>但这应许排解万难：<br/>『我必用眼引导你。』<br/>','',56348,9883);
INSERT INTO stanza VALUES('Z509','3','虽然试探几乎得胜，<br/>可靠亲友也远离，<br/>但这应许发出微声：<br/>『我必用眼引导你。』<br/>','',56349,9884);
INSERT INTO stanza VALUES('Z509','4','你的隐秘盼望消逝，<br/>埋在年日坟墓里，<br/>让这应许将你支持：<br/>『我必用眼引导你。』<br/>','',56350,9885);
INSERT INTO stanza VALUES('Z509','5','生命阴影逐渐加深，<br/>要穿荣耀的身体，<br/>神这应许显为更真：<br/>『我必用眼引导你。』<br/>','',56351,9886);
INSERT INTO stanza VALUES('Z509','6','但愿我灵以神为乐，<br/>我心以祂为至宝，<br/>与祂交通一无间隔，<br/>接受祂眼的引导。<br/>','',56352,9887);
INSERT INTO stanza VALUES('Z510','1','当我信心失效能，<br/>主必扶持我；<br/>当试探者将得胜，<br/>祂必扶持我。<br/>','',56353,9888);
INSERT INTO stanza VALUES('Z510','chorus','祂必扶持我，<br/>祂必扶持我，<br/>因为救主爱我甚，<br/>祂必扶持我。<br/>','',56354,9889);
INSERT INTO stanza VALUES('Z510','2','我向不能站得稳，<br/>须祂扶持我；<br/>因为爱心冷且钝，<br/>须祂扶持我。<br/>','',56355,9890);
INSERT INTO stanza VALUES('Z510','3','祂看我是祂珍宝，<br/>祂必扶持我；<br/>祂所救的祂喜好，<br/>祂必扶持我。<br/>','',56356,9891);
INSERT INTO stanza VALUES('Z510','4','祂不让我终失丧，<br/>祂必扶持我；<br/>如此代价既肯偿，<br/>祂必扶持我。<br/>','',56357,9892);
INSERT INTO stanza VALUES('Z511','1','主已知道你的挫折！<br/>主已知道你的软弱！<br/>主全知道你的无告！<br/>主的话说：我已知道。<br/>','',56358,9893);
INSERT INTO stanza VALUES('Z511','2','祂知你能受甚试炼，<br/>祂知你是需何恩典，<br/>祂早知你所有遭遇，<br/>祂是你主，何必疑惧。<br/>','',56359,9894);
INSERT INTO stanza VALUES('Z511','3','虽然多人讥讽、反对，<br/>亲友离弃，旅伴误会；<br/>但祂深知你的一切；<br/>有主知道你可安歇。<br/>','',56360,9895);
INSERT INTO stanza VALUES('Z511','4','重担只要交托给主，<br/>叹息只要向祂倾吐；<br/>祂心爱你，知你忧苦，<br/>祂必施恩，祂必看顾。<br/>','',56361,9896);
INSERT INTO stanza VALUES('Z511','5','主既知道，足慰我心，<br/>主既知道，我便欢欣！<br/>主既知道，祂必搭救！<br/>主既知道，我还何求？<br/>','',56362,9897);
INSERT INTO stanza VALUES('Z512','1','我是一个异乡旅客，<br/>跋涉遥远的道路；<br/>虽然有时遇见阻隔，<br/>引我亲天父。<br/>途中虽有乌云笼罩，<br/>也有意外的打扰，<br/>思虑、烦恼把我压倒，<br/>但我父知道。<br/>','',56363,9898);
INSERT INTO stanza VALUES('Z512','2','父是知道，何等保证！<br/>沿途试炼有何害？<br/>纵然牠们随我一生，<br/>不容易忍耐。<br/>主已在望，莫大鼓励，<br/>使我安息不动摇！<br/>祂的同在何其甜蜜，<br/>我天父知道。<br/>','',56364,9899);
INSERT INTO stanza VALUES('Z512','3','我父每日都知道我，<br/>看守我在爱里面；<br/>艰难来袭，祂来助我，<br/>叫我往上看。<br/>不久旅程到达止境，<br/>今生就要告终了，<br/>我将如何进入光明，<br/>这事父知道。<br/>','',56365,9900);
INSERT INTO stanza VALUES('Z512','4','那时我在主的面前，<br/>亲眼看见祂慈颜，<br/>满心欢喜，俯伏朝见，<br/>感谢祂恩典。<br/>在祂甜美同在之前，<br/>再无今生的搅扰，<br/>祂的应许全得应验，<br/>这事父知道。<br/>','',56366,9901);
INSERT INTO stanza VALUES('Z513','1','或这样，或那样，<br/>主总必豫备：<br/>虽不照我方法，<br/>也不照你方法，<br/>主要照祂方法，<br/>为我们豫备。<br/>','',56367,9902);
INSERT INTO stanza VALUES('Z513','chorus','我安心靠主，<br/>因主必豫备；<br/>我完全望主，<br/>因主要豫备。<br/>','',56368,9903);
INSERT INTO stanza VALUES('Z513','2','或这时，或那时，<br/>主总必豫备：<br/>虽不照我时候，<br/>也不照你时候，<br/>在主所定时候，<br/>主总必豫备。<br/>','',56369,9904);
INSERT INTO stanza VALUES('Z513','3','所以不要怀疑，<br/>因主必豫备：<br/>我主所有应许，<br/>那里曾有一句<br/>变作乌有空虚？<br/>主总必豫备。<br/>','',56370,9905);
INSERT INTO stanza VALUES('Z513','4','因此，应当进前，<br/>进前不疲惫；<br/>海水必定分开，<br/>吗哪要从天来，<br/>仇敌都要失败，<br/>主总必豫备。<br/>','',56371,9906);
INSERT INTO stanza VALUES('Z514','1','我要歌唱那奇妙应许，<br/>就是耶稣亲口所说：<br/>『我的恩典是够你使用，<br/>我的能力显于软弱。』<br/>惟恐我这恶心会忘记，<br/>忘记这应许的光荣，<br/>所以祂一直一直的说：<br/>『我的恩典够你使用。』<br/>','',56372,9907);
INSERT INTO stanza VALUES('Z514','chorus','是的，救主一直对我说，<br/>一直，一直，一直的说：<br/>『我的恩典是够你使用，<br/>我的能力显于软弱。』<br/>','',56373,9908);
INSERT INTO stanza VALUES('Z514','2','祂的恩典够使我得救，<br/>脱离罪恶，得着新心；<br/>够使我灵、魂、体<br/>都圣洁，<br/>并且满有主的圣灵。<br/>祂的恩典够助我经过<br/>各种试炼，无论多凶；<br/>祂的应许抵挡了牠们，<br/>『我的恩典够你使用。』<br/>','',56374,9909);
INSERT INTO stanza VALUES('Z514','3','祂的恩典够为我疾病：<br/>一面扶持，一面施医。<br/>祂的恩典够助我经过<br/>一切苦楚、一切攻击。<br/>祂的恩典是够我工作，<br/>使我能够帮助弟兄，<br/>并使他们与我同知道，<br/>祂的恩典足够使用。<br/>','',56375,9910);
INSERT INTO stanza VALUES('Z514','4','祂的恩典是够我生活，<br/>够来引领，够来扶助；<br/>将来被提或经过死谷，<br/>祂的恩典都够眷顾。<br/>到那时当我看见救主-<br/>祂的美丽、祂的光荣，<br/>我就要俯伏并承认说：<br/>你的恩典够我使用。<br/>','',56376,9911);
INSERT INTO stanza VALUES('Z514','5','我们的恩典并不够用，<br/>够用惟有祂的恩典。<br/>我们的常是昙花一现，<br/>但是祂的永不改变。<br/>因此我就不断的背诵<br/>祂曾对我亲口所说：<br/>『我的恩典是够你使用，<br/>我的能力显在软弱。』<br/>','',56377,9912);
INSERT INTO stanza VALUES('Z515','1','不在此时，许待主回，<br/>不在此地，许到那里；<br/>我们才能完全领会，<br/>叹息眼泪所有意义。<br/>','',56378,9913);
INSERT INTO stanza VALUES('Z515','chorus','你当一生信靠救主，<br/>路虽阴暗，仍当赞美，<br/>不必惧怕，主在搀扶，<br/>有日、有日都要领会。<br/>','',56379,9914);
INSERT INTO stanza VALUES('Z515','2','中断线索，都将接上，<br/>一生经过，必有路轨，<br/>天能解释各样秘藏，<br/>那日、那日都必领会。<br/>','',56380,9915);
INSERT INTO stanza VALUES('Z515','3','何故厚云遮蔽太阳？<br/>何故寂寞代替安慰？<br/>何故叹息多过歌唱？<br/>有日我们就要领会。<br/>','',56381,9916);
INSERT INTO stanza VALUES('Z515','4','何以祈求未见答应？<br/>何以将成终又不遂？<br/>何以盼望终成泡影？<br/>那日那里，我必领会。<br/>','',56382,9917);
INSERT INTO stanza VALUES('Z515','5','神知我路，手拿牠钥，<br/>祂的带领充满智慧；<br/>有日我眼看见一切，<br/>祂在那里，我必领会。<br/>','',56383,9918);
INSERT INTO stanza VALUES('Z516','1','信靠耶稣何其甘甜，<br/>抓祂话语作把握，<br/>安息在祂应许上面，<br/>只知主曾如此说。<br/>','',56384,9919);
INSERT INTO stanza VALUES('Z516','chorus','耶稣、耶稣，何等可靠，<br/>我曾试祂多少次；<br/>耶稣、耶稣，我的至宝，<br/>祂是活神不误事。<br/>','',56385,9920);
INSERT INTO stanza VALUES('Z516','2','信靠耶稣，何其甘甜，<br/>信祂宝血能洗净；<br/>信心简单，血有效验，<br/>疾病医治，罪洗清。<br/>','',56386,9921);
INSERT INTO stanza VALUES('Z516','3','信靠耶稣，真是甘甜，<br/>救我远离罪与己；<br/>从祂接受无限恩典：<br/>生命、喜乐和安息。<br/>','',56387,9922);
INSERT INTO stanza VALUES('Z516','4','何等喜乐，我能信你，<br/>至宝耶稣，我救主！<br/>信你与我是在一起，<br/>一直一起到永古。<br/>','',56388,9923);
INSERT INTO stanza VALUES('Z517','1','前途如何我不知，<br/>神将我眼遮蔽；<br/>在我向前每步路上，<br/>都有新的境地；<br/>祂所赐的每一喜乐，<br/>也都令人惊奇。<br/>','',56389,9924);
INSERT INTO stanza VALUES('Z517','chorus','我愿跟随祂带领，<br/>对祂完全信靠；<br/>随时随在安然唱道：<br/>『祂知道，祂知道；』<br/>随时随在安然唱道：<br/>『祂知道，祂知道。』<br/>','',56390,9925);
INSERT INTO stanza VALUES('Z517','2','眼前一步我看见，<br/>已够应付需要；<br/>属地幻想若肯去掉，<br/>天光就必照耀；<br/>静中也必甜然听见：<br/>『你要将我信靠。』<br/>','',56391,9926);
INSERT INTO stanza VALUES('Z517','3','哦，那有福的『无智，』<br/>『不知』真是福气！<br/>祂用右手将我握住，<br/>不肯让我稍离，<br/>并使我的受惊心魂<br/>在祂爱中安息。<br/>','',56392,9927);
INSERT INTO stanza VALUES('Z517','4','如此不知而向前；<br/>能知，我也不愿；<br/>宁愿暗中与神同行，<br/>不愿光中孤单；<br/>宁愿凭信与神同行，<br/>不愿凭着眼见。<br/>','',56393,9928);
INSERT INTO stanza VALUES('Z518','1','人若倚靠耶和华，<br/>真有福，<br/>必得着应时的帮助；<br/>你若处处紧紧的跟随主，<br/>必承受应许的好处。<br/>','',56394,9929);
INSERT INTO stanza VALUES('Z518','chorus','务要靠主，专心靠主，<br/>凡你所行，都要认定主，<br/>祂必指引你的路。<br/>务要靠主，专心靠主，<br/>凡你所行，都要认定主，<br/>祂必指引你的路。<br/>','',56395,9930);
INSERT INTO stanza VALUES('Z518','2','人若倚靠耶和华，<br/>真有福，<br/>必定走属天的道路；<br/>你若时时不断的仰望主，<br/>必能有稳健的脚步。<br/>','',56396,9931);
INSERT INTO stanza VALUES('Z518','3','真是有福，<br/>有天父来扶助，<br/>并且有救主来照顾；<br/>你若得着主与父来同住，<br/>就永远不再感孤苦。<br/>','',56397,9932);
INSERT INTO stanza VALUES('Z518','4','真是有福，<br/>得不断走正路，<br/>且天天向前不受阻；<br/>你若得着主同在的丰富，<br/>就必得应时的帮助。<br/>','',56398,9933);
INSERT INTO stanza VALUES('Z519','1','当我在我路上<br/>遇见试探时，<br/>撒但就在耳语<br/>叫我可放弛；<br/>但是负担虽重<br/>我已不发愁，<br/>只要一点相信<br/>就赶难处走。<br/>','',56399,9934);
INSERT INTO stanza VALUES('Z519','chorus','主，我相信！<br/>主，我相信！<br/>求提高我信你的心，<br/>使我能以移山；<br/>主，我相信！<br/>主，我相信！<br/>我的疑虑全投在你身畔。<br/>','',56400,9935);
INSERT INTO stanza VALUES('Z519','2','当我航行海上<br/>顺风的时候，<br/>何等容易相信<br/>耶和华的手，<br/>但我发现正当<br/>波浪漫船来，<br/>需要好多相信<br/>才能不沉埋。<br/>','',56401,9936);
INSERT INTO stanza VALUES('Z519','3','我常听人说：<br/>『我要坚持到底，<br/>我要忠心至死，<br/>我绝不逃避，』<br/>但当试探<br/>来得特别凶猛时，<br/>他就停止相信，<br/>甚么都丧失。<br/>','',56402,9937);
INSERT INTO stanza VALUES('Z519','4','还有别人满有<br/>勇敢与热心，<br/>他们参加事奉<br/>如同钢铁人，<br/>但是正当<br/>与罪摔跤最热时，<br/>他们不是相信，<br/>乃是怕损失。<br/>','',56403,9938);
INSERT INTO stanza VALUES('Z519','5','但愿我们记得，<br/>在属灵生活，<br/>信心不是感觉，<br/>信靠非抚摸；<br/>正当一切<br/>好像最看不见时，<br/>我们仍要相信，<br/>因而仍坚持。<br/>','',56404,9939);
INSERT INTO stanza VALUES('Z520','1','新鲜如同清晨甘露，<br/>带来畅爽的甘美，<br/>基督借祂温情恩膏，<br/>柔声细语的安慰：<br/>站住，直到试炼过去，<br/>站住，直到风波平，<br/>站住，为着神的荣耀，<br/>站住，与主同得胜。<br/>','',56405,9940);
INSERT INTO stanza VALUES('Z520','chorus','盼望之主，<br/>你的声音何甜！<br/>在你面前我心因此畅欢！<br/>','',56406,9941);
INSERT INTO stanza VALUES('Z520','2','如果在我苦炼之中，<br/>我灵、我心皆衰弱，<br/>信心和那盼望之星，<br/>也都退落不闪烁，<br/>愿你信心和你能力，<br/>尽其全力抓住我，<br/>使你所有荣耀丰富，<br/>我可无间的尝着。<br/>','',56407,9942);
INSERT INTO stanza VALUES('Z520','3','主，像清晨放明日光，<br/>驱尽所有的黑暗，<br/>并且用你医治光线，<br/>使我黑暗变中天。<br/>安慰之主，求你就来，<br/>来到忧苦、疲倦心，<br/>你这有福、荣耀盼望，<br/>哦，来与我永亲近。<br/>','',56408,9943);
INSERT INTO stanza VALUES('Z521','1','哦，<br/>让我们在主里面常喜乐，<br/>虽然四围充满了凶恶，<br/>虽然患难如同波涛<br/>在冲击，<br/>但是歌唱总胜似叹息。<br/>','',56409,9944);
INSERT INTO stanza VALUES('Z521','chorus','应当时常喜乐，<br/>当时常喜乐，<br/>无论如何，<br/>歌唱总胜叹息，<br/>无论如何，<br/>生存总胜死寂，<br/>所以应当时常喜乐！<br/>','',56410,9945);
INSERT INTO stanza VALUES('Z521','2','哦，<br/>让我们在主里面常喜乐，<br/>虽然火箭暗中频频戳，<br/>因为撒但还是像从前那样<br/>惧怕赞美远过于悲伤。<br/>','',56411,9946);
INSERT INTO stanza VALUES('Z521','3','哦，<br/>让我们在主里面常喜乐，<br/>虽然精神在病中消磨；<br/>因主的喜乐<br/>就是你的力量，<br/>若靠主喜乐就必刚强。<br/>','',56412,9947);
INSERT INTO stanza VALUES('Z521','4','哦，<br/>让我们在主里面常喜乐，<br/>因这地上帐幕快要脱，<br/>我们要被提，<br/>得与主在一起，<br/>不再有何忧愁与叹息。<br/>','',56413,9948);
INSERT INTO stanza VALUES('Z522','1','长久陷入忧患、苦痛，<br/>我就退到你的手中；<br/>丝毫再无保留；<br/>你手擦干我的眼泪，<br/>使我哭脸满了光辉，<br/>再无苦泪可流。<br/>','',56414,9949);
INSERT INTO stanza VALUES('Z522','2','再会！你这虚空欢娱：<br/>无味消遣，儿戏乐趣，<br/>对你我失口味。<br/>真实快乐乃在十架，<br/>其他娱乐尽是虚假-<br/>主是如此定规。<br/>','',56415,9950);
INSERT INTO stanza VALUES('Z522','3','哦，十字架才是福气：<br/>牠的损失乃是利益；<br/>其苦也是甘甜！<br/>所有心思、心志、心情，<br/>在此全都得以炼净，<br/>尝到真乐之满。<br/>','',56416,9951);
INSERT INTO stanza VALUES('Z522','4','苦中自爱难能得益，<br/>因牠总求自己安逸：<br/>除此，牠无福气；<br/>真实之爱，目的高尚，<br/>舍己乃是牠所欣赏，<br/>受苦是牠所喜。<br/>','',56417,9952);
INSERT INTO stanza VALUES('Z522','5','我的选择和你一样，<br/>哦，将圣火前来挑旺，<br/>使之永焚无烬！<br/>背起十架将你跟随，<br/>因着你爱时常赞美，<br/>乃是我的福分。<br/>','',56418,9953);
INSERT INTO stanza VALUES('Z523','1','祂赐的十架虽然沉重，<br/>不会重逾祂恩典；<br/>我怕的风波虽然汹涌，<br/>不至掩蔽祂荣脸。<br/>','',56419,9954);
INSERT INTO stanza VALUES('Z523','chorus','十架不会重逾祂恩典，<br/>风波不会掩蔽祂荣脸；<br/>我心欢乐，<br/>因我知有主耶稣同在此，<br/>我就胜过敌权势。<br/>','',56420,9955);
INSERT INTO stanza VALUES('Z523','2','我路上荆棘，并不会比<br/>祂头上的荆冕利；<br/>我喝的苦杯，还远不及<br/>祂的在客西马尼。<br/>','',56421,9956);
INSERT INTO stanza VALUES('Z523','3','祂光照耀得更加昭明，<br/>在危难的道路中；<br/>我担子变得更为省轻，<br/>当我为人来任重。<br/>','',56422,9957);
INSERT INTO stanza VALUES('Z523','4','我今生活在祂的面前，<br/>欢然顺服祂旨意；<br/>我知我所受各种试炼，<br/>都是化装的福庇。<br/>','',56423,9958);
INSERT INTO stanza VALUES('Z524','1','我是一只笼中小鸟，<br/>远离天空、旷阔野地；<br/>是祂将我安置于此，<br/>我愿向祂歌颂不已；<br/>如此被囚，我甚欢欣，<br/>因这，我神，使你称心。<br/>','',56424,9959);
INSERT INTO stanza VALUES('Z524','2','禁中我无他事可作，<br/>终日就是静中歌唱；<br/>我所使之称心的神，<br/>也在倾听我的颂扬；<br/>祂捆绑了我的翅膀，<br/>却爱俯首听我歌唱。<br/>','',56425,9960);
INSERT INTO stanza VALUES('Z524','3','哦神，你是有耳能听，<br/>你也有心施爱赐福；<br/>我的音调虽然粗陋，<br/>你却毫不鄙弃厌恶；<br/>因你知这音调之弦，<br/>乃是甜美之爱所弹。<br/>','',56426,9961);
INSERT INTO stanza VALUES('Z524','4','这笼将我四面禁锢，<br/>我难外飞任意遨游；<br/>我的翅膀虽被捆住，<br/>我心我灵仍是自由；<br/>监牢墙垣，不能阻挡<br/>心灵所有释放、翱翔。<br/>','',56427,9962);
INSERT INTO stanza VALUES('Z524','5','我心超越监牢之闩，<br/>我灵腾飞何其自在！<br/>向着心爱之主腾飞，<br/>祂的旨意我所敬拜；<br/>在你坚定旨意之中，<br/>我灵得到自由、欢腾。<br/>','',56428,9963);
INSERT INTO stanza VALUES('Z525','1','四围墙垣坚而固，<br/>终日将我禁闭；<br/>但那关闭我的人，<br/>不能使神远离：<br/>监牢墙垣全变可爱，<br/>因为我神在此同在。<br/>','',56429,9964);
INSERT INTO stanza VALUES('Z525','2','关闭我者都知道，<br/>甚难使我孤单；<br/>但是他们却不知<br/>是祂来狱慰安；<br/>祂使牢中黑暗变明，<br/>并用喜乐充满我灵。<br/>','',56430,9965);
INSERT INTO stanza VALUES('Z525','3','哦神，你爱激动我，<br/>悲叹转为颂赞；<br/>我从深处敬拜你，<br/>不管时间地点；<br/>或顺或逆，都无所要，<br/>只要和你旨意相调。<br/>','',56431,9966);
INSERT INTO stanza VALUES('Z525','4','这个成为我宝贝，<br/>这个使我得益；<br/>为我将祸变祝福，<br/>使我苦中欢喜。<br/>不论何事都可临到，<br/>只要有神我就够了。<br/>','',56432,9967);
INSERT INTO stanza VALUES('Z526','1','神未曾应许：天色常蓝，<br/>人生的路途花香常漫；<br/>神未曾应许：常晴无雨，<br/>常乐无痛苦，常安无虞。<br/>','',56433,9968);
INSERT INTO stanza VALUES('Z526','chorus','神却曾应许：生活有力，<br/>行路有光亮，作工得息，<br/>试炼得恩勗，危难有赖，<br/>无限的体谅，不死的爱。<br/>','',56434,9969);
INSERT INTO stanza VALUES('Z526','2','神未曾应许：我们不遇<br/>苦难和试探、<br/>懊恼、忧虑；<br/>神未曾应许：我们不负<br/>许多的重担、许多事务。<br/>','',56435,9970);
INSERT INTO stanza VALUES('Z526','3','神未曾应许：前途尽是<br/>平坦的大路，任意驱驰；<br/>没有深水拒，汪洋一片，<br/>没有大山阻，高薄云天。<br/>','',56436,9971);
INSERT INTO stanza VALUES('Z527','1','迫得太紧，<br/>迫得无处可逃生；<br/>迫到极点，<br/>好像力不能胜；<br/>迫到四顾茫然，<br/>惟有独流泪；<br/>迫得无可奈何，<br/>望绝心灰。<br/>','',56437,9972);
INSERT INTO stanza VALUES('Z527','chorus','神是我盼望，<br/>是我喜乐；<br/>是祂叫无变有，<br/>叫死人复活！<br/>','',56438,9973);
INSERT INTO stanza VALUES('Z527','2','压迫在身，<br/>无处可算是平安；<br/>压迫在心，<br/>四围都是黑暗；<br/>迫于仇敌，<br/>有时也迫于朋友；<br/>迫上加迫，<br/>性命几归乌有。<br/>','',56439,9974);
INSERT INTO stanza VALUES('Z527','3','迫到除神之外，<br/>别无人帮助；<br/>迫到喜欢贫穷如同丰富；<br/>迫到接受鞭杖<br/>如同蒙雨露；<br/>迫到除主之外，<br/>别无爱慕。<br/>','',56440,9975);
INSERT INTO stanza VALUES('Z527','4','迫到脱尘，<br/>现今就登天逍游；<br/>迫到无一缠累，<br/>完全自由；<br/>迫到信神来作<br/>不可能的事；<br/>迫到必须靠主而生而死。<br/>','',56441,9976);
INSERT INTO stanza VALUES('Z527','5','『迫得太紧！』<br/>我们如此的哭泣；<br/>迫到如此，<br/>压迫已竭其力；<br/>压迫余生已非<br/>压迫所能及；<br/>迫过之后，<br/>已得永远安息。<br/>','',56442,9977);
INSERT INTO stanza VALUES('Z527','6','『迫得太紧！』<br/>实在乃是大利益；<br/>压迫不过显明神的手臂；<br/>迫过之后，<br/>旁观者都要看见：<br/>迫上加迫，<br/>不会摇动一点。<br/>','',56443,9978);
INSERT INTO stanza VALUES('Z527','7','『压迫虽紧，』<br/>我们仍旧的进前；<br/>压迫续来，<br/>我们的望在天；<br/>压迫续来，<br/>已经无可再压迫；<br/>压迫续来，<br/>心仍因神自得。<br/>','',56444,9979);
INSERT INTO stanza VALUES('Z528','1','暗过必明亮，<br/>苦过必甜；<br/>弱过必刚强，<br/>难过必安；<br/>损过必有益，<br/>风过必静；<br/>劳过必安息，<br/>雨过必晴。<br/>','',56445,9980);
INSERT INTO stanza VALUES('Z528','2','压过必高升，<br/>忧过必乐；<br/>死过必复生，<br/>失过必得；<br/>累过必轻松，<br/>困过必苏；<br/>迫过必从容，<br/>贫过必富。<br/>','',56446,9981);
INSERT INTO stanza VALUES('Z528','3','荡过必安居，<br/>孤过有伴，<br/>与主再无距，<br/>直到相见，<br/>十架变冠冕，<br/>叹息变赞，<br/>信望变眼见，<br/>再无疑难。<br/>','',56447,9982);
INSERT INTO stanza VALUES('Z529','1','当日神在伊甸园中，<br/>将人置于二树之前：<br/>借生命树指明自己，<br/>以知识树表明撒但。<br/>','',56448,9983);
INSERT INTO stanza VALUES('Z529','2','生命树乃神的中心，<br/>照神永远计划所定，<br/>神是要在基督里面，<br/>给人接受，作人生命。<br/>','',56449,9984);
INSERT INTO stanza VALUES('Z529','3','知识树是神的警告，<br/>题示神外另有源头：<br/>恶者撒但，死亡渊薮，<br/>人若接触，死亡必受。<br/>','',56450,9985);
INSERT INTO stanza VALUES('Z529','4','生命之树人肯接受，<br/>人必得着神作生命，<br/>且必变成珍贵宝石，<br/>神的心愿借此完成。<br/>','',56451,9986);
INSERT INTO stanza VALUES('Z529','5','知识一树人若接触，<br/>撒但必得进人里面，<br/>成为罪恶，带进死亡，<br/>使神计划难得成全。<br/>','',56452,9987);
INSERT INTO stanza VALUES('Z529','6','这是表明只有神是<br/>我们生命惟一源头；<br/>摸着神外一切事物，<br/>就是摸着死亡之由。<br/>','',56453,9988);
INSERT INTO stanza VALUES('Z529','7','知识不过带来死亡，<br/>尽管外观是善非恶；<br/>在神之外任何事物，<br/>都是撒但施计之所。<br/>','',56454,9989);
INSERT INTO stanza VALUES('Z529','7','不只恶与基督相对，<br/>就是善也与祂相抵；<br/>凡属知识不拘善恶，<br/>都与生命相反不一。<br/>','',56455,9990);
INSERT INTO stanza VALUES('Z529','9','主，教我们惟独摸你，<br/>好叫我们被你充满；<br/>你外事物概不接触，<br/>对恶如此，对善亦然。<br/>','',56456,9991);
INSERT INTO stanza VALUES('Z530','1','神的律法在人身外，<br/>圣洁、良善，要人遵行；<br/>为要向人确切证明，<br/>神所要求人难完成。<br/>','',56457,9992);
INSERT INTO stanza VALUES('Z530','2','在人心思存有一律，<br/>使人立志愿意为善；<br/>但肢体中另有一律，<br/>与其争战，使其难堪。<br/>','',56458,9993);
INSERT INTO stanza VALUES('Z530','3','心思之律乃是良善，<br/>原是人在受造之时，<br/>得自人的受造生命，<br/>使人善行得以维持。<br/>','',56459,9994);
INSERT INTO stanza VALUES('Z530','4','肢体之律乃是邪恶，<br/>当人堕落，联于撒但，<br/>来自撒但邪恶生命，<br/>进入人体，借死掌权。<br/>','',56460,9995);
INSERT INTO stanza VALUES('Z530','5','这个肢体犯罪之律<br/>强过心思为善之律，<br/>借着撒但邪恶能力，<br/>征服善律将人掳去。<br/>','',56461,9996);
INSERT INTO stanza VALUES('Z530','6','在我灵中更有一律，<br/>乃是生命之灵的律，<br/>来自神的大能生命，<br/>当我重生即为我具。<br/>','',56462,9997);
INSERT INTO stanza VALUES('Z530','7','这个灵中生命之律，<br/>乃是最强，强过所有；<br/>使我脱离犯罪之律，<br/>成全神律一切要求。<br/>','',56463,9998);
INSERT INTO stanza VALUES('Z530','7','因此，我们要将心思<br/>时常置于灵的上面，<br/>永不再放肉体之上，<br/>我们便脱罪的霸权。<br/>','',56464,9999);
INSERT INTO stanza VALUES('Z530','9','心思放在肉体之上，<br/>就是可怕死亡、黑暗；<br/>心思置于灵的上面，<br/>乃是有福生命、平安。<br/>','',56465,10000);
INSERT INTO stanza VALUES('Z530','10','这是得着释放之路，<br/>这是最妙成圣途径！<br/>主，使我们活在灵中，<br/>凭着此灵与你同行。<br/>','',56466,10001);
INSERT INTO stanza VALUES('Z531','1','字句律法是神见证，<br/>说明神是如何的神，<br/>如何圣洁，如何公义，<br/>如何光明，如何慈仁。<br/>','',56467,10002);
INSERT INTO stanza VALUES('Z531','2','神的律法是要我们<br/>照神所是行事为人，<br/>使神可来称义、悦纳，<br/>并按公义赐以福分。<br/>','',56468,10003);
INSERT INTO stanza VALUES('Z531','3','律法不能赐人生命，<br/>任何能力不能供应，<br/>只向我们有所要求，<br/>显明我们软弱无能。<br/>','',56469,10004);
INSERT INTO stanza VALUES('Z531','4','律法并非神的心愿，<br/>乃为显明罪过而添，<br/>给人干犯，向人证明<br/>人是满了罪恶过犯。<br/>','',56470,10005);
INSERT INTO stanza VALUES('Z531','5','律法塞住众人之口，<br/>并将众人圈在罪中；<br/>为将我们带到基督，<br/>在祂里面蒙神恩宠。<br/>','',56471,10006);
INSERT INTO stanza VALUES('Z531','6','律法乃是基督小影，<br/>基督是神实际见证，<br/>丰满表明神是如何<br/>圣洁、公义、<br/>仁爱、光明。<br/>','',56472,10007);
INSERT INTO stanza VALUES('Z531','7','乃是神的这位基督，<br/>供应我们以神生命，<br/>好使律法所有要求，<br/>都在我们得以完成。<br/>','',56473,10008);
INSERT INTO stanza VALUES('Z531','7','基督，神这活的见证，<br/>使我有分大能生命；<br/>借祂我向律法已死，<br/>在祂灵中得以成圣。<br/>','',56474,10009);
INSERT INTO stanza VALUES('Z532','1','旧约时代神的律法，<br/>乃用字句写在石版；<br/>但是现今生命的律，<br/>是由圣灵写在心坎。<br/>','',56475,10010);
INSERT INTO stanza VALUES('Z532','2','字句律法要人为善，<br/>人的软弱借此显明；<br/>生命的律乃是供应，<br/>使人享受神的大能。<br/>','',56476,10011);
INSERT INTO stanza VALUES('Z532','3','字句律法乃在外面，<br/>使我对神有所认识；<br/>生命的律是在里面，<br/>供我以神更深启示。<br/>','',56477,10012);
INSERT INTO stanza VALUES('Z532','4','字句律法乃在外面，<br/>借着死的诫命管治；<br/>生命的律是在里面，<br/>借着活的知识节制。<br/>','',56478,10013);
INSERT INTO stanza VALUES('Z532','5','这个活的生命之律，<br/>在我里面多方运行，<br/>照着里面生命感觉，<br/>从我里面管治、规正。<br/>','',56479,10014);
INSERT INTO stanza VALUES('Z532','6','这个管治极细、极深，<br/>在我全人最深之处，<br/>带来活的生命感觉，<br/>将神自己向我供输。<br/>','',56480,10015);
INSERT INTO stanza VALUES('Z532','7','因这活的生命之律，<br/>外面教导，就不需要；<br/>对神一切活的认识，<br/>从我里面，这律教导。<br/>','',56481,10016);
INSERT INTO stanza VALUES('Z532','7','主，教我凭这律行动，<br/>顺服牠的里面管理，<br/>对你我有活的认识，<br/>并得享受你的自己。<br/>','',56482,10017);
INSERT INTO stanza VALUES('Z533','1','永远生命带来<br/>生命的交通；<br/>在灵里的交通，<br/>使灵来推动。<br/>','',56483,10018);
INSERT INTO stanza VALUES('Z533','2','永远生命赐给<br/>神圣的交通；<br/>如此主灵与我，<br/>灵里同行动。<br/>','',56484,10019);
INSERT INTO stanza VALUES('Z533','3','乃是灵里生命，<br/>带来这交通；<br/>在灵里的交通，<br/>使我蒙恩宠。<br/>','',56485,10020);
INSERT INTO stanza VALUES('Z533','4','借着生命大能，<br/>能正确交通；<br/>在灵里的交通，<br/>带我到光中。<br/>','',56486,10021);
INSERT INTO stanza VALUES('Z533','5','借血外面洗净，<br/>交通得维持；<br/>借膏里面涂抹，<br/>交通能充实。<br/>','',56487,10022);
INSERT INTO stanza VALUES('Z533','6','借着十架工作，<br/>交通得加深；<br/>借着圣灵运行，<br/>交通得更新。<br/>','',56488,10023);
INSERT INTO stanza VALUES('Z533','7','这一生命交通，<br/>使我脱自己；<br/>这一生命交通，<br/>带我进神里。<br/>','',56489,10024);
INSERT INTO stanza VALUES('Z534','1','任何生命具有意识，<br/>都有生命感觉；<br/>在我里的神圣生命，<br/>感觉更为超越。<br/>','',56490,10025);
INSERT INTO stanza VALUES('Z534','2','生命性质越是高超，<br/>生命感觉越好；<br/>神的生命最为超特，<br/>牠的感觉最高。<br/>','',56491,10026);
INSERT INTO stanza VALUES('Z534','3','这个神的生命感觉，<br/>就是神的感觉，<br/>乃是在我重生灵里，<br/>远胜善的感觉。<br/>','',56492,10027);
INSERT INTO stanza VALUES('Z534','4','这一里面生命感觉，<br/>是我最深感觉，<br/>从我里面分辨一切，<br/>指明神之所悦。<br/>','',56493,10028);
INSERT INTO stanza VALUES('Z534','5','借这里面生命感觉，<br/>对神我有认识；<br/>不是外面挣扎所得，<br/>乃是自发启示。<br/>','',56494,10029);
INSERT INTO stanza VALUES('Z534','6','我们越在生命长大，<br/>生命感觉越敏；<br/>我们越凭生命行动，<br/>生命感觉越紧。<br/>','',56495,10030);
INSERT INTO stanza VALUES('Z534','7','生命感觉若肯操练，<br/>就能使灵刚强；<br/>借这里面神的感觉，<br/>交通得以增长。<br/>','',56496,10031);
INSERT INTO stanza VALUES('Z535','1','在神所重生圣徒的灵中，<br/>里面的认识实际又丰富；<br/>所以不需要外面的教导，<br/>乃是在里面对神有领悟。<br/>','',56497,10032);
INSERT INTO stanza VALUES('Z535','2','永远的生命，<br/>最好也最高，<br/>具有各种样神圣的功能；<br/>借着这生命对神的认识，<br/>远超过外面知识的供应。<br/>','',56498,10033);
INSERT INTO stanza VALUES('Z535','3','生命的律法放在我心里，<br/>由神的圣灵写在我心上；<br/>里面的管治，<br/>使我认识神，<br/>远超过外面教导的影响。<br/>','',56499,10034);
INSERT INTO stanza VALUES('Z535','4','恩膏的涂抹住在我灵中，<br/>将神的事情向我心显明；<br/>借着这涂抹我能认识神，<br/>超过借外面教导之所能。<br/>','',56500,10035);
INSERT INTO stanza VALUES('Z535','5','三而一的神住在我里面，<br/>时刻在运行、<br/>生活并行动；<br/>借神在里面运行的感觉，<br/>对神的认识高超且深宏。<br/>','',56501,10036);
INSERT INTO stanza VALUES('Z535','6','我今既有这里面的认识，<br/>我就不需要外面的知识；<br/>只需要时刻活在灵里面，<br/>行事与为人全照灵指示。<br/>','',56502,10037);
INSERT INTO stanza VALUES('Z535','7','我们越活在基督的里面，<br/>越凭着里面感觉而行动，<br/>我们就越有里面的认识，<br/>神越将基督铭刻我心中。<br/>','',56503,10038);
INSERT INTO stanza VALUES('Z535','7','借着这里面生命的认识，<br/>我们能维持与神的交通；<br/>借着这里面隐藏的认识，<br/>神性的丰满要输供无穷。<br/>','',56504,10039);
INSERT INTO stanza VALUES('Z536','1','神成肉身神圣的原则，<br/>乃是神人互相调和；<br/>二者调成一个奥秘人，<br/>照神计划，共同生活。<br/>','',56505,10040);
INSERT INTO stanza VALUES('Z536','2','人是神在外面的表现，<br/>神是人里面的生命；<br/>人是完全为神所占有，<br/>神是借人得着显明。<br/>','',56506,10041);
INSERT INTO stanza VALUES('Z536','3','救赎乃是在人得完成，<br/>为要显明神的智慧；<br/>救恩乃是借人来传扬，<br/>为使造物全都领会。<br/>','',56507,10042);
INSERT INTO stanza VALUES('Z536','4','在这时代属灵的事工，<br/>都该是人与神合作，<br/>使神与人紧密的联结，<br/>彼此倚赖，互相调和。<br/>','',56508,10043);
INSERT INTO stanza VALUES('Z536','5','并非是神单独的工作，<br/>也非是人单独事奉；<br/>乃是神、人绝对的合作，<br/>使神计划得以完成。<br/>','',56509,10044);
INSERT INTO stanza VALUES('Z536','6','这个神成肉身的原则，<br/>须应用于一切事工，<br/>也须用于恩赐和功用，<br/>我们就能共同事奉。<br/>','',56510,10045);
INSERT INTO stanza VALUES('Z537','1','受造之人是三部分，<br/>有体、有魂并且有灵，<br/>为着成全神的计划，<br/>并得享受神作供应。<br/>','',56511,10046);
INSERT INTO stanza VALUES('Z537','2','身体乃是外面部分，<br/>借此人有物觉功能；<br/>使人接触物质世界，<br/>将人自己显于体形。<br/>','',56512,10047);
INSERT INTO stanza VALUES('Z537','3','魂乃是人里面部分，<br/>是人自己，给人自觉；<br/>借此人在心理方面，<br/>能以接触精神世界。<br/>','',56513,10048);
INSERT INTO stanza VALUES('Z537','4','灵乃是人最深部分，<br/>在人深处给人神觉；<br/>使人借此能接受神，<br/>且能接触属灵世界。<br/>','',56514,10049);
INSERT INTO stanza VALUES('Z537','5','在人魂中有三部分：<br/>心思、意志以及情感；<br/>这是人的各种功能，<br/>用以成全人的意愿。<br/>','',56515,10050);
INSERT INTO stanza VALUES('Z537','6','在人灵里也有三部：<br/>交通、直觉以及良心；<br/>借此人能与神交通，<br/>也能敬拜并接受神。<br/>','',56516,10051);
INSERT INTO stanza VALUES('Z537','7','人须运用魂的各部，<br/>将神所是全都拣选；<br/>并用灵来将神接受，<br/>且借身体将神彰显。<br/>','',56517,10052);
INSERT INTO stanza VALUES('Z537','7','人灵需要神来重生，<br/>得着神的非造生命；<br/>人魂需要神的变化，<br/>体需变成基督荣形。<br/>','',56518,10053);
INSERT INTO stanza VALUES('Z537','9','借着这些神圣工作，<br/>人在他的每一部分，<br/>都得与主完全调和，<br/>并能完全彰显主神。<br/>','',56519,10054);
INSERT INTO stanza VALUES('Z538','1','创世之前神已豫定<br/>儿子名分归我享，<br/>借着祂灵将我模成<br/>祂那儿子的形像；<br/>好使祂的独生爱子，<br/>在众子中作长子，<br/>借祂儿子和其弟兄，<br/>满得彰显祂荣姿。<br/>','',56520,10055);
INSERT INTO stanza VALUES('Z538','2','借着灵中神圣重生，<br/>我们得作神众子；<br/>但是我们必须成熟，<br/>才能作神的后嗣。<br/>借着完全长大成人，<br/>儿子名分我得享；<br/>借着长成丰满身量，<br/>后嗣福分我饱尝。<br/>','',56521,10056);
INSERT INTO stanza VALUES('Z538','3','我们的灵、魂与身体，<br/>都需模成主形状；<br/>这要完满完成于我，<br/>当我进入祂荣光。<br/>借着身体得蒙救赎，<br/>儿子名分得成全；<br/>借着最终一步变化，<br/>就能满足神心愿。<br/>','',56522,10057);
INSERT INTO stanza VALUES('Z538','4','借那最终一步变化，<br/>我们完全被圣别；<br/>神将我们带进荣耀，<br/>像祂儿子无亏缺。<br/>造物都在切望等候<br/>神的众子显出来；<br/>牠们得进『荣耀』自由，<br/>脱离辖制与败坏。<br/>','',56523,10058);
INSERT INTO stanza VALUES('Z539','1','神造我们作祂器皿，<br/>乃为彰显祂丰盛；<br/>要我爱祂，为我造心；<br/>要我接受，且造灵。<br/>','',56524,10059);
INSERT INTO stanza VALUES('Z539','2','我们应该用心爱神，<br/>也该用灵接受神；<br/>要得神作我们生命，<br/>非此无法能入门。<br/>','',56525,10060);
INSERT INTO stanza VALUES('Z539','3','撒但败坏我们的心，<br/>也弄死了我们灵；<br/>使我不能与神接触，<br/>反倒靠赖己生命。<br/>','',56526,10061);
INSERT INTO stanza VALUES('Z539','4','因此，主在祂救恩里，<br/>更新我的心与灵；<br/>恢复了我爱的心情，<br/>并我接受的本能。<br/>','',56527,10062);
INSERT INTO stanza VALUES('Z539','5','乃是借着更新的心，<br/>我们爱神，渴慕神；<br/>且是借着更新的灵，<br/>我们拜神，接受神。<br/>','',56528,10063);
INSERT INTO stanza VALUES('Z539','6','对神，我们的心应当<br/>诚实、清洁又单纯；<br/>并且我们的灵该是<br/>贫穷、寻求且温顺。<br/>','',56529,10064);
INSERT INTO stanza VALUES('Z539','7','神阿，保守我心爱你，<br/>常是新鲜、无陈迹；<br/>并使我灵刚强、活泼，<br/>永以新样接触你。<br/>','',56530,10065);
INSERT INTO stanza VALUES('Z540','1','与主来往，享主生命，<br/>需一正确的心，<br/>使主一切，借祂恩典，<br/>我们全都有分。<br/>','',56531,10066);
INSERT INTO stanza VALUES('Z540','2','需要一心，凡事纯洁，<br/>心思纯正、清明，<br/>使我明白主的心意，<br/>常存恐惧、战兢。<br/>','',56532,10067);
INSERT INTO stanza VALUES('Z540','3','需要一心，富有爱情，<br/>情感满了爱火，<br/>对主热切，爱慕追求，<br/>不为其他所夺。<br/>','',56533,10068);
INSERT INTO stanza VALUES('Z540','4','需要一心，诚实、顺服，<br/>意志降服归顺，<br/>要刚则刚，要柔则柔，<br/>神旨惟从、惟遵。<br/>','',56534,10069);
INSERT INTO stanza VALUES('Z540','5','需要一心，毫无责备，<br/>良心清洁、无亏，<br/>凡事与神和谐相安，<br/>借血脱尽定罪。<br/>','',56535,10070);
INSERT INTO stanza VALUES('Z540','6','主，赐我们这样的心，<br/>时刻将你思恋，<br/>使我得享你的丰富，<br/>成为你的丰满。<br/>','',56536,10071);
INSERT INTO stanza VALUES('Z541','1','哦主，你今乃是那灵，<br/>住在我们灵里；<br/>二灵现今成为一灵，<br/>你我得成为一。<br/>','',56537,10072);
INSERT INTO stanza VALUES('Z541','2','你的灵与我们的灵，<br/>永远同证不弛：<br/>我们乃是神的儿女，<br/>且是神的后嗣。<br/>','',56538,10073);
INSERT INTO stanza VALUES('Z541','3','你已成为生命之灵，<br/>来将自己赐赋；<br/>我们今在我们灵中，<br/>享受你的丰富。<br/>','',56539,10074);
INSERT INTO stanza VALUES('Z541','4','你今是那生命之灵，<br/>引导、光照、流通；<br/>我们今在我们灵中，<br/>随你生活、行动。<br/>','',56540,10075);
INSERT INTO stanza VALUES('Z541','5','你是那灵，在我灵里，<br/>时常加强、供应；<br/>在我灵中，借着你灵，<br/>我们敬拜、事奉。<br/>','',56541,10076);
INSERT INTO stanza VALUES('Z541','6','你是那灵，经过我灵，<br/>时以叹息代祷；<br/>在我灵里，同着你灵，<br/>我们向你祷告。<br/>','',56542,10077);
INSERT INTO stanza VALUES('Z541','7','我愿回到我们灵中，<br/>在此接触你灵；<br/>在这灵中我们得享<br/>你的神圣供应。<br/>','',56543,10078);
INSERT INTO stanza VALUES('Z541','7','哦主，这是何等联结，<br/>二灵竟成一灵！<br/>你灵活在我的灵中，<br/>我灵住于你灵！<br/>','',56544,10079);
INSERT INTO stanza VALUES('Z542','1','借着十架将灵分辨，<br/>时常将魂置死地；<br/>背着十架，拒绝自己，<br/>终日活在你灵里。<br/>','',56545,10080);
INSERT INTO stanza VALUES('Z542','2','借着十架将灵分辨，<br/>靠神生命的活话；<br/>将魂全然从灵分开，<br/>行在灵中不稍差。<br/>','',56546,10081);
INSERT INTO stanza VALUES('Z542','3','借着十架将灵分辨，<br/>心思借光得更新，<br/>感情全都奉献给主，<br/>意志因爱也归顺。<br/>','',56547,10082);
INSERT INTO stanza VALUES('Z542','4','借着十架将灵分辨，<br/>经过裂开的幔子；<br/>肉体与魂全被破碎，<br/>灵在凡事占优势。<br/>','',56548,10083);
INSERT INTO stanza VALUES('Z542','5','借着十架将灵分辨，<br/>灵是神的至圣所；<br/>在此灵中与神交通，<br/>神的同在必得着。<br/>','',56549,10084);
INSERT INTO stanza VALUES('Z542','6','借着十架将灵分辨，<br/>如同经过约但河；<br/>因此进入迦南美地，<br/>借享基督而生活。<br/>','',56550,10085);
INSERT INTO stanza VALUES('Z542','7','借着十架将灵分辨，<br/>行动总要在灵里；<br/>经营基督犹如美地，<br/>祂的丰富必归你。<br/>','',56551,10086);
INSERT INTO stanza VALUES('Z543','1','圣殿深处是至圣所，<br/>内有约柜并施恩座，<br/>其上有神荣耀同在，<br/>在此神给祭司遇着。<br/>','',56552,10087);
INSERT INTO stanza VALUES('Z543','2','我今乃是神的圣殿，<br/>灵是其中的至圣所，<br/>神和基督在此居住，<br/>那灵在此与我同活。<br/>','',56553,10088);
INSERT INTO stanza VALUES('Z543','3','在此，在我最深之处，<br/>神在主里作我一切；<br/>在此，那灵使主基督<br/>作我实际，取用不竭。<br/>','',56554,10089);
INSERT INTO stanza VALUES('Z543','4','在此，我在我灵里面，<br/>和主接触，与主同在；<br/>在此，我也借着我灵，<br/>与神交通，向神敬拜。<br/>','',56555,10090);
INSERT INTO stanza VALUES('Z543','5','在此，基督如同美地，<br/>我居其中，享其丰富；<br/>也当在此进攻仇敌，<br/>运用权柄对付阴府。<br/>','',56556,10091);
INSERT INTO stanza VALUES('Z543','6','我当追求对灵认识，<br/>永远将灵从魂分开，<br/>并且活在这至圣所，<br/>享受神与主的同在。<br/>','',56557,10092);
INSERT INTO stanza VALUES('Z543','7','我当永远拒绝我魂，<br/>努力进入神的安息，<br/>使我丰满得着基督，<br/>成全神的永远旨意。<br/>','',56558,10093);
INSERT INTO stanza VALUES('Z544','1','求主教我分辨灵与魂，<br/>好叫我能真认识你；<br/>你今是灵，住在我灵中，<br/>二灵联合相调为一。<br/>','',56559,10094);
INSERT INTO stanza VALUES('Z544','2','求主教我分辨灵与魂，<br/>永远拒绝魂的生命；<br/>并在灵中永远跟随你，<br/>随时应用你这活灵。<br/>','',56560,10095);
INSERT INTO stanza VALUES('Z544','3','求主教我分辨灵与魂，<br/>心思永不置于肉体；<br/>乃是随时放在灵上面，<br/>使我脱离罪与自己。<br/>','',56561,10096);
INSERT INTO stanza VALUES('Z544','4','求主教我分辨灵与魂，<br/>使我永远不再属魂，<br/>乃是完全真实的属灵，<br/>时在灵中行动、生存。<br/>','',56562,10097);
INSERT INTO stanza VALUES('Z544','5','求主教我分辨灵与魂，<br/>诡诈的己可被点出；<br/>凡事应用你的十字架，<br/>活着非我，乃是基督。<br/>','',56563,10098);
INSERT INTO stanza VALUES('Z544','6','求主教我分辨灵与魂，<br/>使我魂中得以变化，<br/>直到我被模成你形像，<br/>直到成熟，目的得达。<br/>','',56564,10099);
INSERT INTO stanza VALUES('Z544','7','求主教我分辨灵与魂，<br/>赐我以你活的话语，<br/>叫我将灵从魂全分开，<br/>而在其中与你同居。<br/>','',56565,10100);
INSERT INTO stanza VALUES('Z545','1','三一之神荣耀的灵，<br/>现今住在我灵里面；<br/>一直想要从我流出，<br/>使神可以得着彰显。<br/>','',56566,10101);
INSERT INTO stanza VALUES('Z545','2','但我外面天然的人，<br/>常将那灵关闭禁拘；<br/>未能让祂得家安居，<br/>反倒成了祂的监狱。<br/>','',56567,10102);
INSERT INTO stanza VALUES('Z545','3','祂像宝贝放在瓦器，<br/>受了遮藏，人难看见；<br/>瓦器必须毁坏、破碎，<br/>宝贝才能得着彰显。<br/>','',56568,10103);
INSERT INTO stanza VALUES('Z545','4','我们的己必须拆毁，<br/>魂的生命实是捆绑！<br/>天然的人必须破碎，<br/>那灵才能得着释放。<br/>','',56569,10104);
INSERT INTO stanza VALUES('Z545','5','这个说明何以主许<br/>苦难环境临到我们；<br/>为要借着一些折磨，<br/>破碎我们外面的人。<br/>','',56570,10105);
INSERT INTO stanza VALUES('Z545','6','外面的人-就是旧魂-<br/>必须毁坏、必须受伤；<br/>里面的人-就是新灵-<br/>才与那灵同得释放。<br/>','',56571,10106);
INSERT INTO stanza VALUES('Z545','7','求主给我这种破碎，<br/>不许我再保全自己；<br/>使我接受一切伤损，<br/>甘愿接受，再无异议。<br/>','',56572,10107);
INSERT INTO stanza VALUES('Z545','7','使我宝贵你的破碎，<br/>永不再有怨言、怨意；<br/>使我看重一切损失，<br/>过于任何一种利益。<br/>','',56573,10108);
INSERT INTO stanza VALUES('Z546','1','神的心意是要我们<br/>模成祂儿子形像；<br/>因此祂灵变化工作，<br/>必须完成我身上。<br/>','',56574,10109);
INSERT INTO stanza VALUES('Z546','chorus','求主将我魂的各部，<br/>全都变成你形像；<br/>用你那灵将我浸透，<br/>使我全像你模样。<br/>','',56575,10110);
INSERT INTO stanza VALUES('Z546','2','神已用祂神圣生命，<br/>在我灵中重生我；<br/>但祂还须在我魂中，<br/>作那变化的工作。<br/>','',56576,10111);
INSERT INTO stanza VALUES('Z546','3','从我灵中向外开展，<br/>祂就变化我全魂；<br/>更新里面每一部分，<br/>直到全人都归顺。<br/>','',56577,10112);
INSERT INTO stanza VALUES('Z546','4','借祂那灵生命大能，<br/>照祂形状变化我；<br/>一部一部，荣上加荣，<br/>模成祂形，新而活。<br/>','',56578,10113);
INSERT INTO stanza VALUES('Z546','5','一直变化，全人圣别，<br/>直到像祂，得成熟；<br/>一直变化，魂全占有，<br/>直到贱体蒙救赎。<br/>','',56579,10114);
INSERT INTO stanza VALUES('Z547','1','不是挣扎努力，<br/>乃是全归依，<br/>使我能得安息，<br/>使我能得力。<br/>不是立志为善，<br/>乃是随从灵，<br/>使我能脱罪缠，<br/>使我能得胜。<br/>','',56580,10115);
INSERT INTO stanza VALUES('Z547','2','不是凭着字句，<br/>乃是凭着灵，<br/>使我能蒙称许，<br/>使我能得生。<br/>不是人的教导，<br/>乃是神恩膏，<br/>使我能蒙光照，<br/>使我能灵交。<br/>','',56581,10116);
INSERT INTO stanza VALUES('Z547','3','不是定意、奔跑，<br/>乃是神怜悯，<br/>使我得神上好，<br/>使我蒙神恩。<br/>不是智慧、聪明，<br/>乃是神恩典，<br/>使我经过苦境，<br/>使我历艰难。<br/>','',56582,10117);
INSERT INTO stanza VALUES('Z547','4','不是高言、大智，<br/>乃是神权能，<br/>使我拯救罪世，<br/>引领人得生。<br/>不是才能、势力，<br/>乃是神圣灵，<br/>使我成功神意，<br/>完成主使命。<br/>','',56583,10118);
INSERT INTO stanza VALUES('Z548','1','神的福音，何等有福！<br/>来救痛苦的人世；<br/>耶稣已为疾病救赎，<br/>祂的鞭伤有医治。<br/>','',56584,10119);
INSERT INTO stanza VALUES('Z548','chorus','赞美救主完全救赎，<br/>来救痛苦的人世；<br/>赞美救主作我大夫，<br/>祂受鞭伤我得治。<br/>','',56585,10120);
INSERT INTO stanza VALUES('Z548','2','无论是谁求祂设法，<br/>祂都欢迎不推辞；<br/>祂叫我带疾病寻祂，<br/>因祂鞭伤能医治。<br/>','',56586,10121);
INSERT INTO stanza VALUES('Z548','3','赞美祂的神圣膏油，<br/>就是圣灵来恩赐；<br/>求你来为我们按手，<br/>因你鞭伤能医治。<br/>','',56587,10122);
INSERT INTO stanza VALUES('Z548','4','当那撒但火箭环攻，<br/>求作盾牌来抵制；<br/>我们必定安全到终，<br/>因你鞭伤有医治。<br/>','',56588,10123);
INSERT INTO stanza VALUES('Z548','5','主，我奉献所有肢体，<br/>我要荣耀你不止；<br/>使我不至有日忘记<br/>你的鞭伤有医治。<br/>','',56589,10124);
INSERT INTO stanza VALUES('Z549','1','祂医治我，赞美祂名！<br/>我要歌颂祂的救赎；<br/>祂释放我脱离疾病，<br/>大能的主是我大夫。<br/>','',56590,10125);
INSERT INTO stanza VALUES('Z549','chorus','祂医治我，祂医治我，<br/>祂有权柄来医治我，<br/>许多的人祂已救活，<br/>我今相信祂医治我。<br/>','',56591,10126);
INSERT INTO stanza VALUES('Z549','2','祂医治我，我用信心<br/>简单相信祂说的话；<br/>满有希望，满有安宁，<br/>信祂必使我离病榻。<br/>','',56592,10127);
INSERT INTO stanza VALUES('Z549','3','祂医治我，我心相信，<br/>来摸祂的衣裳䍁子，<br/>祂的能力流通我身，<br/>沉疔霍然得了医治。<br/>','',56593,10128);
INSERT INTO stanza VALUES('Z549','4','祂医治我，有如当初<br/>祂来担当疾病、罪过；<br/>祂的大能依然如故，<br/>我的救主永远活着。<br/>','',56594,10129);
INSERT INTO stanza VALUES('Z549','5','祂医治我，我已求寻<br/>许多次数，但未得着；<br/>如今我是全心相信，<br/>因信，祂今使我再活。<br/>','',56595,10130);
INSERT INTO stanza VALUES('Z550','1','当主正从那里经过，<br/>众人拥塞将祂挤着，<br/>她从背后将主一摸，<br/>立刻得着了痊愈。<br/>','',56596,10131);
INSERT INTO stanza VALUES('Z550','chorus','只是一摸，就得痊愈！<br/>主仍在此，尚未离去，<br/>前来摸祂，不必再疑虑，<br/>一摸就必得痊愈。<br/>','',56597,10132);
INSERT INTO stanza VALUES('Z550','2','只是一摸，就得痊愈，<br/>祂使我心平安无惧，<br/>在祂脚前，重担全去，<br/>我已得着了痊愈。<br/>','',56598,10133);
INSERT INTO stanza VALUES('Z550','3','只是一摸，一切完成，<br/>我得脱去所有疾病，<br/>直到永远我要颂称，<br/>因我得着了痊愈。<br/>','',56599,10134);
INSERT INTO stanza VALUES('Z550','4','只是一摸，祂就转来，<br/>哦，祂眼中希奇之爱！<br/>抚慰我心，使我感戴，<br/>我已得着了痊愈。<br/>','',56600,10135);
INSERT INTO stanza VALUES('Z550','5','只要一摸，必得医治，<br/>祂能医你，就在此时，<br/>只是一摸，不管病势，<br/>就必得着了痊愈。<br/>','',56601,10136);
INSERT INTO stanza VALUES('Z551','1','主是祷告的阿拉法，<br/>祂灵教自我灵；<br/>我们不知如何祷告，<br/>除非祂在带领。<br/>','',56602,10137);
INSERT INTO stanza VALUES('Z551','2','主是祷告的俄梅嘎，<br/>神的最大『阿们，』<br/>在我祷告停息之时，<br/>发出同感声音。<br/>','',56603,10138);
INSERT INTO stanza VALUES('Z551','3','但在首尾两端之间，<br/>祂让我们接联，<br/>用那不清似吃话语，<br/>译出祂所欲言。<br/>','',56604,10139);
INSERT INTO stanza VALUES('Z551','4','哦主，你这首先、末后，<br/>使我所有祷告<br/>与你心愿完全结合，<br/>说出你之所要。<br/>','',56605,10140);
INSERT INTO stanza VALUES('Z551','5','我们不能道出之祈，<br/>全有你作其始；<br/>我们简短不清之祷，<br/>其终愿你也是！<br/>','',56606,10141);
INSERT INTO stanza VALUES('Z552','1','祷告乃是灵中所烧圣香，<br/>经过破碎之人向神献上：<br/>乃是圣灵焚烧之气所点，<br/>再由信心呼求带到神前。<br/>','',56607,10142);
INSERT INTO stanza VALUES('Z552','2','祷告乃是恩典所产香料，<br/>信心、爱心、<br/>苦难之花所调，<br/>藏在满了香气的话里面，<br/>给神吸入，<br/>欣赏其味之甜。<br/>','',56608,10143);
INSERT INTO stanza VALUES('Z552','3','祷告乃是上升含水之气，<br/>供给甘雨，<br/>并使河流不息，<br/>灌溉干地，<br/>直到地的四方<br/>所有沙漠都像玫瑰开放。<br/>','',56609,10144);
INSERT INTO stanza VALUES('Z552','4','祷告乃是圣灵所满金管，<br/>用神的油供给神的灯盏；<br/>正当我们<br/>同心等候、祷告，<br/>灵就充满，<br/>灯就发光照耀。<br/>','',56610,10145);
INSERT INTO stanza VALUES('Z552','5','祷告乃是宇宙最大力量，<br/>乃是神的炸药，<br/>无何能挡；<br/>推动那只推动一切之手，<br/>转动大轮，<br/>掠过全地无留。<br/>','',56611,10146);
INSERT INTO stanza VALUES('Z552','6','教我祷告！<br/>运行在我灵中，<br/>直到全人被你感觉推动！<br/>在我里面祷告，<br/>直到显出：我里基督祷告天上基督。<br/>','',56612,10147);
INSERT INTO stanza VALUES('Z553','1','主阿，<br/>我要安静在你面前，<br/>将我全人收回到我里面；<br/>不再仅是外面随意祷告，<br/>乃是照着灵里感觉发表。<br/>','',56613,10148);
INSERT INTO stanza VALUES('Z553','2','主，<br/>你好像是在天上听我，<br/>实在你是在我里面住着；<br/>好像是我向你<br/>呼求、祷告，<br/>实在是你在我里面发表。<br/>','',56614,10149);
INSERT INTO stanza VALUES('Z553','3','有时我虽没有话语达意，<br/>但我能随那灵深深叹息；<br/>不是我在外面向你求讨，<br/>乃是你在里面借我发表。<br/>','',56615,10150);
INSERT INTO stanza VALUES('Z553','4','我愿在此吸取你的自己，<br/>吃你喝你，<br/>享受你的供给；<br/>好叫我能真实与你相交，<br/>让你从我里面得着发表。<br/>','',56616,10151);
INSERT INTO stanza VALUES('Z553','5','在这交通里面，<br/>你光照亮，<br/>你血也要将我洗得清爽；<br/>不仅使我能得彻底光照，<br/>并且使你能有清楚发表。<br/>','',56617,10152);
INSERT INTO stanza VALUES('Z553','6','在此你的膏油多方涂抹，<br/>将你涂我里面越过越多；<br/>你的成分加多，<br/>我的减少，<br/>你就从我得着更多发表。<br/>','',56618,10153);
INSERT INTO stanza VALUES('Z553','7','在此向你开启，<br/>让你注入，<br/>也要向人敞开，<br/>让你流出；<br/>在你活水流中与人相交，<br/>好叫你能得着丰满发表！<br/>','',56619,10154);
INSERT INTO stanza VALUES('Z554','1','求主教我如何祷告！<br/>如何使敌遁逃，<br/>如何捆绑灭其权势，<br/>使众罪囚得释。<br/>','',56620,10155);
INSERT INTO stanza VALUES('Z554','2','求主教我如何祷告！<br/>如何阵地站牢，<br/>如何奋进攻破营垒，<br/>立使仇敌溃退。<br/>','',56621,10156);
INSERT INTO stanza VALUES('Z554','3','求主教我如何祷告！<br/>明白神的最好；<br/>如何祷告摇动天地，<br/>得着血下权利。<br/>','',56622,10157);
INSERT INTO stanza VALUES('Z554','4','因着信心，借着祷告，<br/>学习与主同劳；<br/>学知万有全属我们，<br/>运用得胜权柄。<br/>','',56623,10158);
INSERT INTO stanza VALUES('Z555','1','主阿，我们今聚集，<br/>同心祷告寻求你；<br/>我们乃是祭司体，<br/>要在你前同侍立。<br/>','',56624,10159);
INSERT INTO stanza VALUES('Z555','chorus','在此我们同祷告，<br/>学习摸着你上好，<br/>直到灵里能相调，<br/>使你召会得建造。<br/>','',56625,10160);
INSERT INTO stanza VALUES('Z555','2','切愿前来作祭司，<br/>在你面前供圣职，<br/>用灵来摸你意旨，<br/>让你完成你设施。<br/>','',56626,10161);
INSERT INTO stanza VALUES('Z555','3','我们进到至圣所，<br/>摸你施恩的宝座，<br/>随着灵感向你说，<br/>让你灵里多经过。<br/>','',56627,10162);
INSERT INTO stanza VALUES('Z555','4','从你施恩的宝座，<br/>流出恩惠的江河，<br/>流到我灵滋润我，<br/>应时帮助我得着。<br/>','',56628,10163);
INSERT INTO stanza VALUES('Z555','5','但愿我们的祷告，<br/>就是你灵的发表；<br/>不随己意来求讨，<br/>只照你意向你要。<br/>','',56629,10164);
INSERT INTO stanza VALUES('Z555','6','虽有许多的事务，<br/>需要向你来求诉，<br/>却愿你能有出路，<br/>过于我们蒙眷顾。<br/>','',56630,10165);
INSERT INTO stanza VALUES('Z555','7','我们仰望你圣垂，<br/>多赐生命的活水；<br/>我们饱尝你恩惠，<br/>就能让你有作为。<br/>','',56631,10166);
INSERT INTO stanza VALUES('Z556','1','我要进入至圣所，<br/>幔子里面过生活，<br/>摸主施恩的宝座，<br/>让主活水来流过。<br/>','',56632,10167);
INSERT INTO stanza VALUES('Z556','2','我灵就是至圣所，<br/>主在里面今住着；<br/>只要回到灵里面，<br/>我就与主得相见。<br/>','',56633,10168);
INSERT INTO stanza VALUES('Z556','3','复活基督的馨香，<br/>调在灵里来发放；<br/>在灵里面我祷告，<br/>祂就借此得发表。<br/>','',56634,10169);
INSERT INTO stanza VALUES('Z556','4','摸着灵里的基督，<br/>就必饱尝祂丰富：<br/>生命亮光、生命粮，<br/>加上复活的馨香。<br/>','',56635,10170);
INSERT INTO stanza VALUES('Z556','5','越摸越深越丰富，<br/>摸着深处的基督：<br/>摸着生命的律法，<br/>摸着隐藏的吗哪。<br/>','',56636,10171);
INSERT INTO stanza VALUES('Z556','6','摸着复活蒙悦纳，<br/>如同枯杖发了芽；<br/>在此才有施恩座，<br/>恩惠流出如江河。<br/>','',56637,10172);
INSERT INTO stanza VALUES('Z556','7','我们聚集同祷告，<br/>灵得释放并相调，<br/>也是进入至圣所，<br/>在此能将主摸着。<br/>','',56638,10173);
INSERT INTO stanza VALUES('Z556','7','我们在这至圣所，<br/>同过祭司的生活，<br/>多方摸主施恩座，<br/>直到活水全流过。<br/>','',56639,10174);
INSERT INTO stanza VALUES('Z557','1','进入至圣所，<br/>摸主施恩座，<br/>恩惠临到如同江河；<br/>进入至圣所，<br/>摸主施恩座，<br/>恩惠临到如同江河。<br/>','',56640,1);
INSERT INTO stanza VALUES('Z557','2','进入至圣所，<br/>幔内过生活，<br/>荣光照耀将我射过；<br/>进入至圣所，<br/>幔内过生活，<br/>荣光照耀将我射过。<br/>','',56641,3);
INSERT INTO stanza VALUES('Z557','3','回到灵里面，<br/>祷告在主前，<br/>摸着生命活水泉源；<br/>回到灵里面，<br/>祷告在主前，<br/>摸着生命活水泉源。<br/>','',56642,5);
INSERT INTO stanza VALUES('Z558','1','哦主，幔子已经裂开，<br/>新活之路已通；<br/>我能借血坦然前来，<br/>到你面光之中。<br/>','',56643,10178);
INSERT INTO stanza VALUES('Z558','2','借着你血赎罪功效，<br/>进入你至圣所；<br/>随着你灵涂抹、引导，<br/>来摸你施恩座。<br/>','',56644,10179);
INSERT INTO stanza VALUES('Z558','3','只随那灵，不凭自己，<br/>在此烧香祷告，<br/>让主基督从我灵里，<br/>如香得着发表。<br/>','',56645,10180);
INSERT INTO stanza VALUES('Z558','4','怜恤、恩惠犹如活水，<br/>流自施恩宝座，<br/>应时帮助丰盛、甘美，<br/>将我全人流过。<br/>','',56646,10181);
INSERT INTO stanza VALUES('Z558','5','虽然不为事物求讨，<br/>只随那灵祷告，<br/>你却知道一切需要，<br/>必为我们照料。<br/>','',56647,10182);
INSERT INTO stanza VALUES('Z558','6','纵然有何忧苦、罣虑，<br/>也能不受搅扰；<br/>一切全都交你担去，<br/>我灵就得逍遥。<br/>','',56648,10183);
INSERT INTO stanza VALUES('Z558','7','切愿如此专清静，<br/>灵里与你相交；<br/>随着你灵转动、运行，<br/>你前烧香祷告。<br/>','',56649,10184);
INSERT INTO stanza VALUES('Z559','1','我奉耶稣全能的名，<br/>跪在施恩宝座前，<br/>打败许多黑暗军兵，<br/>灭熄许多的火箭。<br/>','',56650,10185);
INSERT INTO stanza VALUES('Z559','chorus','全能名！全能名！<br/>我奉此名就得胜！<br/>全能名！全能名！<br/>撒但、罪、死，都无能！<br/>','',56651,10186);
INSERT INTO stanza VALUES('Z559','2','当我求告全能耶稣，<br/>撒但全军都败阵；<br/>耶稣，耶稣，全能耶稣！<br/>你的大名是得胜！<br/>','',56652,10187);
INSERT INTO stanza VALUES('Z559','3','不久主颁有福命令，<br/>召我进入祂天国，<br/>那时全能耶稣的名，<br/>使我得登祂宝座！<br/>','',56653,10188);
INSERT INTO stanza VALUES('Z560','1','要对这山说：『去，<br/>离此，投在海里！』<br/>心中若不疑惑，<br/>就必成就于你。<br/>相信主话，必要成全，<br/>在主里面吩咐你山！<br/>','',56654,10189);
INSERT INTO stanza VALUES('Z560','2','取用救赎权利，<br/>主的宝血所买；<br/>使这权利有效，<br/>三一之神同来。<br/>顺服主话，必要成全，<br/>在主里面吩咐你山！<br/>','',56655,10190);
INSERT INTO stanza VALUES('Z560','3','自己、罪恶、病痛，<br/>主已全部担当，<br/>神的要求满足，<br/>你已得着释放。<br/>倚靠主话，必要成全，<br/>在主里面吩咐你山！<br/>','',56656,10191);
INSERT INTO stanza VALUES('Z560','4','围绕高大墙垣，<br/>凭信祷告放胆；<br/>在墙未倒之先，<br/>喊出得胜颂赞。<br/>安心相信，必要成全，<br/>在主里面吩咐你山！<br/>','',56657,10192);
INSERT INTO stanza VALUES('Z560','5','所有铜门铁闩，<br/>全都仆倒降服，<br/>让那相信战士，<br/>高唱凯歌进入。<br/>不睬仇敌，必要成全，<br/>在主里面吩咐你山！<br/>','',56658,10193);
INSERT INTO stanza VALUES('Z560','6','取用神的信心，<br/>脱去不信耻辱；<br/>广行神迹之杖，<br/>要将理由尽逐。<br/>站在主话，必要成全，<br/>在主里面吩咐你山！<br/>','',56659,10194);
INSERT INTO stanza VALUES('Z561','1','『凭信心求，』<br/>奉主的名，<br/>施恩座前来祷告；<br/>你若相信，听主答应：<br/>看哪，小子，已成了。<br/>','',56660,10195);
INSERT INTO stanza VALUES('Z561','2','『凭信心求，』<br/>神要成就<br/>圣灵组织的祷告；<br/>祂必施行奇妙拯救，<br/>远超过你所意料。<br/>','',56661,10196);
INSERT INTO stanza VALUES('Z561','3','『凭信心求，』<br/>才是祷告，<br/>因信你就敢站牢，<br/>满有平安、盼望、欢笑，<br/>高张两手向神要。<br/>','',56662,10197);
INSERT INTO stanza VALUES('Z561','4','『凭信心求，』<br/>神正等你<br/>能凭信心来求恳；<br/>因为信心随时随地<br/>得神喜悦摸着神。<br/>','',56663,10198);
INSERT INTO stanza VALUES('Z562','1','再唱信心的歌！<br/>无论夜如何黑；<br/>你若赞美，神要工作，<br/>使你所信能得。<br/>使你所信能得。<br/>','',56664,10199);
INSERT INTO stanza VALUES('Z562','2','再唱信心的歌！<br/>你魂应当赞颂；<br/>因神喜悦信心唱歌，<br/>于漫漫长夜中。<br/>','',56665,10200);
INSERT INTO stanza VALUES('Z562','3','再唱信心的歌！<br/>仇敌听见要抖；<br/>赞美原来会胜鬼魔，<br/>何致被他箝口。<br/>','',56666,10201);
INSERT INTO stanza VALUES('Z562','4','再唱信心的歌！<br/>不久天就要曙，<br/>我们要唱无终的歌，<br/>我们要去见主。<br/>','',56667,10202);
INSERT INTO stanza VALUES('Z563','1','要在灵里同心祷告，<br/>不照你心所思想，<br/>只照深处恩膏涂抹，<br/>成全主心所愿望。<br/>','',56668,10203);
INSERT INTO stanza VALUES('Z563','chorus','要在灵里同心祷告，<br/>不照你心所思想，<br/>只照深处恩膏涂抹，<br/>成全主心所愿望。<br/>','',56669,10204);
INSERT INTO stanza VALUES('Z563','2','要在灵里同心祷告，<br/>借着十架否认己；<br/>一切愿望、所有心意，<br/>都要让灵来管理。<br/>','',56670,10205);
INSERT INTO stanza VALUES('Z563','3','要在灵里同心祷告，<br/>坐在天上用权柄；<br/>属地利益全踏脚下，<br/>进攻空中的首领。<br/>','',56671,10206);
INSERT INTO stanza VALUES('Z563','4','要在灵里同心祷告，<br/>与众圣徒同祈求；<br/>寻求主的心意、带领，<br/>灵中和谐永保守。<br/>','',56672,10207);
INSERT INTO stanza VALUES('Z563','5','要在灵里同心祷告，<br/>儆醒、祷告要持久；<br/>为神国度和神荣耀，<br/>儆醒、祷告到成就。<br/>','',56673,10208);
INSERT INTO stanza VALUES('Z563','6','要在灵里同心祷告，<br/>和谐一致寻求神；<br/>在主身体的灵里面，<br/>永远祷告凭同心。<br/>','',56674,10209);
INSERT INTO stanza VALUES('Z564','1','永远要在灵里祷告，<br/>不凭肉体或头脑！<br/>这个秘诀若肯实行，<br/>神的同在必得到。<br/>','',56675,10210);
INSERT INTO stanza VALUES('Z564','chorus','永远要在灵里祷告，<br/>这个秘诀主所示；<br/>在灵里面与神接触，<br/>这个秘诀要保持。<br/>','',56676,10211);
INSERT INTO stanza VALUES('Z564','2','永远要在灵里祷告，<br/>绝不凭着人思想；<br/>与神这灵交通来往，<br/>惟有如此能得尝。<br/>','',56677,10212);
INSERT INTO stanza VALUES('Z564','3','永远要在灵里祷告，<br/>借此发表神心愿；<br/>灵里与主一直相处，<br/>全人必被主火燃。<br/>','',56678,10213);
INSERT INTO stanza VALUES('Z564','4','永远要在灵里祷告，<br/>甚至由衷来叹息！<br/>借着那灵管治、带领，<br/>如此发表神心意。<br/>','',56679,10214);
INSERT INTO stanza VALUES('Z564','5','永远要在灵里祷告，<br/>就是在神至圣所；<br/>惟有如此在这灵里，<br/>才能与神相调和。<br/>','',56680,10215);
INSERT INTO stanza VALUES('Z564','6','永远要在灵里祷告，<br/>这是惟一的途径；<br/>神性所有一切丰满，<br/>借这秘诀能受领。<br/>','',56681,10216);
INSERT INTO stanza VALUES('Z565','1','祷告摸神的宝座，<br/>摸神施恩的宝座，<br/>蒙到怜恤和恩惠，<br/>应时帮助必得着。<br/>','',56682,10217);
INSERT INTO stanza VALUES('Z565','2','祷告摸神的宝座，<br/>深感需要神恩典，<br/>灵里与神同停留，<br/>面面交通毫无间。<br/>','',56683,10218);
INSERT INTO stanza VALUES('Z565','3','祷告摸神的宝座，<br/>认识恩典的富有；<br/>一直支取并享受，<br/>向神感赞胜祈求。<br/>','',56684,10219);
INSERT INTO stanza VALUES('Z565','4','祷告摸神的宝座，<br/>摸神掌权的宝座；<br/>在主基督的名里，<br/>对付阴府与鬼魔。<br/>','',56685,10220);
INSERT INTO stanza VALUES('Z565','5','祷告摸神的宝座，<br/>借着活信主所赐；<br/>运用属天的权柄，<br/>对付死亡的权势。<br/>','',56686,10221);
INSERT INTO stanza VALUES('Z565','6','祷告摸神的宝座，<br/>震动阴府的权势；<br/>宝座之上用王权，<br/>同主祷告在此时。<br/>','',56687,10222);
INSERT INTO stanza VALUES('Z566','1','我愿多方祷告，<br/>随时操练灵！<br/>已往祷告太少，<br/>所以灵不明；<br/>即使有些祷告，<br/>也是少用灵；<br/>多为事物求讨，<br/>不随灵运行。<br/>','',56688,10223);
INSERT INTO stanza VALUES('Z566','2','今愿灵里祷告，<br/>随从灵叹息；<br/>照着灵感发表，<br/>不照所记忆。<br/>不再凭着头脑，<br/>只是凭着灵；<br/>无论赞美求告，<br/>都随灵引领。<br/>','',56689,10224);
INSERT INTO stanza VALUES('Z566','3','不但自己祷告，<br/>我要操练灵；<br/>就是同人祷告，<br/>也要如此行。<br/>绝不外面应付，<br/>祷告不动灵；<br/>乃是里面深处，<br/>灵与灵响应。<br/>','',56690,10225);
INSERT INTO stanza VALUES('Z566','4','不再一同事奉，<br/>却不同祷告，<br/>光用唇舌交通，<br/>灵不动丝毫。<br/>不再一同祷告，<br/>灵却不相交；<br/>外面尽管喊叫，<br/>里面摸不着。<br/>','',56691,10226);
INSERT INTO stanza VALUES('Z566','5','随处都能祷告，<br/>随处操练灵；<br/>无论人多人少，<br/>都能运用灵。<br/>不分时、地、人位，<br/>总不受影响；<br/>任何一种聚会，<br/>灵都能释放。<br/>','',56692,10227);
INSERT INTO stanza VALUES('Z566','6','灵一如此高昂，<br/>主就能亨通。<br/>灵是如此刚强，<br/>我就能有用。<br/>灵里活水流通，<br/>圣徒才相调；<br/>在这流通之中，<br/>召会得建造。<br/>','',56693,10228);
INSERT INTO stanza VALUES('Z567','1','祷告要将主发表，<br/>不可发表我自己；<br/>让主启示祂自己，<br/>借我发表祂心意。<br/>','',56694,10229);
INSERT INTO stanza VALUES('Z567','2','祷告要将主发表，<br/>必须说出祂所要，<br/>静下自己的思想，<br/>与主心思得协调。<br/>','',56695,10230);
INSERT INTO stanza VALUES('Z567','3','祷告要将主发表，<br/>总要将祂来瞻仰，<br/>如同镜子在观看，<br/>从衷返照祂荣光。<br/>','',56696,10231);
INSERT INTO stanza VALUES('Z567','4','祷告要将主发表，<br/>让祂借我来求诉；<br/>住在我里的基督，<br/>祷告天上的基督。<br/>','',56697,10232);
INSERT INTO stanza VALUES('Z567','5','祷告要将主发表，<br/>学习不凭自己求，<br/>完全向着主祷告，<br/>只凭祂求到永久。<br/>','',56698,10233);
INSERT INTO stanza VALUES('Z568','1','祷告与主来往交通，<br/>祂面灵里来寻求；<br/>祂前求问并且静听，<br/>隐密之处来等候。<br/>','',56699,10234);
INSERT INTO stanza VALUES('Z568','chorus','祷告与主来往交通，<br/>祂面灵里来寻求；<br/>祂前求问并且静听，<br/>隐密之处来等候。<br/>','',56700,10235);
INSERT INTO stanza VALUES('Z568','2','祷告与主来往交通，<br/>从你里面全敞开；<br/>敞着脸面将祂瞻仰，<br/>单一、纯洁又实在。<br/>','',56701,10236);
INSERT INTO stanza VALUES('Z568','3','祷告与主来往交通，<br/>凭信将祂来寻求；<br/>学习来摸祂这活灵，<br/>恭敬、仰望并等候。<br/>','',56702,10237);
INSERT INTO stanza VALUES('Z568','4','祷告与主来往交通，<br/>以灵、以真为秘诀；<br/>总要凭灵祷告、求问，<br/>照着里面的感觉。<br/>','',56703,10238);
INSERT INTO stanza VALUES('Z568','5','祷告与主来往交通，<br/>诚恳静听祂所言；<br/>让祂心意印刻于你，<br/>使你成全祂心愿。<br/>','',56704,10239);
INSERT INTO stanza VALUES('Z568','6','祷告与主来往交通，<br/>沐浴在祂面光中；<br/>让祂荣美将你浸透，<br/>使你返照祂面容。<br/>','',56705,10240);
INSERT INTO stanza VALUES('Z569','1','祷告与主同劳苦，<br/>祷告为主将路铺，<br/>祷告把主来推动，<br/>也被推动走主路。<br/>','',56706,10241);
INSERT INTO stanza VALUES('Z569','2','祷告与主同劳苦，<br/>照主心意和目的；<br/>与主完全的联合，<br/>直到祝福能满溢。<br/>','',56707,10242);
INSERT INTO stanza VALUES('Z569','3','祷告与主同劳苦，<br/>自己雄心要抛弃；<br/>己意也要全拒绝，<br/>惟独顾到主旨意。<br/>','',56708,10243);
INSERT INTO stanza VALUES('Z569','4','祷告与主同劳苦，<br/>让主发起并推行；<br/>所有计划和工作，<br/>都是主借我完成。<br/>','',56709,10244);
INSERT INTO stanza VALUES('Z569','5','祷告与主同劳苦，<br/>直到大轮已转动；<br/>与主一同来祷告，<br/>直到召会能跟从。<br/>','',56710,10245);
INSERT INTO stanza VALUES('Z570','1','我今如此为主争战，<br/>撒但真是不甘；<br/>他用他的所有权势，<br/>要我中途停止；<br/>我却不住祷告，<br/>转使仇敌遁逃；<br/>因为与主说一声，<br/>甚么就都好。<br/>','',56711,10246);
INSERT INTO stanza VALUES('Z570','chorus','只要与主说一声，<br/>甚么就都好；<br/>只要与主说一声，<br/>甚么就都好。<br/>赞美主，<br/>我每次受试炼的时候，<br/>只要与主说一声，<br/>甚么就都好。<br/>','',56712,10247);
INSERT INTO stanza VALUES('Z570','2','我虽经历黑暗、崎岖，<br/>虽遇疾风、暴雨，<br/>虽然试炼不断继续，<br/>前途真是可虑，<br/>转瞬我就得胜，<br/>因我靠主大能，<br/>因我与主说一声，<br/>甚么必都好。<br/>','',56713,10248);
INSERT INTO stanza VALUES('Z570','3','当我亲友向我攻击，<br/>爱人渺无信息，<br/>当我软弱、孤单、无倚，<br/>被人误会、撇弃，<br/>我将伤心告主，<br/>祂就立刻安抚；<br/>真的，与主说一声，<br/>甚么就都好。<br/>','',56714,10249);
INSERT INTO stanza VALUES('Z570','4','因我与主常是密语，<br/>我心就无烦虑，<br/>逐日都是欢呼歌唱，<br/>稳靠救主胸膛；<br/>我今倚主手臂，<br/>我要证明到底：<br/>只要与主说一声，<br/>甚么就都好。<br/>','',56715,10250);
INSERT INTO stanza VALUES('Z571','1','何等朋友，我主耶稣！<br/>担我罪孽负我忧；<br/>何等权利，能将难处<br/>到主面前去祈求。<br/>多少平安屡屡丧失，<br/>多少痛苦无须受；<br/>无非我们未将万事<br/>到主面前去祈求。<br/>','',56716,10251);
INSERT INTO stanza VALUES('Z571','2','我们有否苦难、艰辛？<br/>有否试探和引诱？<br/>不能因此失望、灰心，<br/>应当向主去祈求。<br/>谁能像祂忠实、稳妥，<br/>背我重担分我愁？<br/>惟祂知我每一软弱，<br/>故当向主去祈求。<br/>','',56717,10252);
INSERT INTO stanza VALUES('Z571','3','我们是否疲倦，苦楚、<br/>思虑、重担压心头？<br/>救主仍旧是避难处，<br/>应当向祂去祈求。<br/>朋友有否卖你、弃你？<br/>应当向主去祈求；<br/>祂的怀抱是你护庇，<br/>经祂抚慰必无忧。<br/>','',56718,10253);
INSERT INTO stanza VALUES('Z572','1','我所有苦况，<br/>必须告诉主，<br/>我不能独自担此忧郁；<br/>我在患难中，<br/>惟主能安抚，<br/>擦去我眼泪，<br/>将我体恤。<br/>','',56719,10254);
INSERT INTO stanza VALUES('Z572','chorus','我必须告诉，<br/>必须告诉主，<br/>将我的心事向主倾吐；<br/>我必须告诉，<br/>必须告诉主，<br/>惟主知我心，<br/>乐于安抚。<br/>','',56720,10255);
INSERT INTO stanza VALUES('Z572','2','我所有困难，<br/>必须告诉主，<br/>我不能独自对付遭遇；<br/>我一切事务，<br/>惟主能担负，<br/>使我得安息，<br/>慰我情绪。<br/>','',56721,10256);
INSERT INTO stanza VALUES('Z572','3','我所有缺乏，<br/>必须告诉主，<br/>我不能独自卸去忧虑；<br/>我所有需要，<br/>惟主能满足，<br/>使我享丰富，<br/>绰绰有余。<br/>','',56722,10257);
INSERT INTO stanza VALUES('Z572','4','我所有软弱，<br/>必须告诉主，<br/>我不能独自胜过私欲；<br/>我所有捆绑，<br/>惟主能帮助，<br/>使我得释放，<br/>脱离罪律。<br/>','',56723,10258);
INSERT INTO stanza VALUES('Z572','5','我所有试探，<br/>必须告诉主，<br/>我不能独自抵挡鬼魔；<br/>主所受试探，<br/>与我毫无殊，<br/>惟主能救我脱离凶恶。<br/>','',56724,10259);
INSERT INTO stanza VALUES('Z573','1','祭司职分神圣高尚！<br/>常将祭物向神献上，<br/>常在圣所向神仰望，<br/>常在神前烧香！<br/>','',56725,10260);
INSERT INTO stanza VALUES('Z573','chorus','常在神前烧香！<br/>常在神前烧香！<br/>常在神前将灯点亮，<br/>也常向神歌唱！<br/>','',56726,10261);
INSERT INTO stanza VALUES('Z573','2','圣所并无天然之光，<br/>需要灯台发光照亮；<br/>祭司每逢进内烧香，<br/>都要将灯点亮！<br/>','',56727,10262);
INSERT INTO stanza VALUES('Z573','3','为要将神美德颂扬，<br/>激动人心起来共赏，<br/>祭司除了点灯、烧香，<br/>也要向神歌唱！<br/>','',56728,10263);
INSERT INTO stanza VALUES('Z573','4','我要祷告如同烧香，<br/>献上基督复活馨香，<br/>照神心愿，供神欣赏，<br/>我得与神同享。<br/>','',56729,10264);
INSERT INTO stanza VALUES('Z573','5','我要读经接受亮光，<br/>如同神前将灯点亮；<br/>神圣之光照耀辉煌，<br/>在我心中射放。<br/>','',56730,10265);
INSERT INTO stanza VALUES('Z573','6','我要唱诗向主颂扬，<br/>犹如祭司向神歌唱，<br/>颂扬主恩、主爱无疆，<br/>我就将主饱尝。<br/>','',56731,10266);
INSERT INTO stanza VALUES('Z573','7','祷告献上主的馨香，<br/>读经接受主的亮光，<br/>唱诗颂扬主的恩赏，<br/>主灵就得通畅！<br/>','',56732,10267);
INSERT INTO stanza VALUES('Z574','1','我今等候，<br/>主，我今等候；<br/>让我安息于你，<br/>使我清楚你意，<br/>这是我所恳祈-<br/>我今等候，我今等候。<br/>','',56733,10268);
INSERT INTO stanza VALUES('Z574','2','我今等候，<br/>主，我今等候；<br/>当我在此停留，<br/>向我施行拯救，<br/>教我借你祈求-<br/>我今等候，我今等候。<br/>','',56734,10269);
INSERT INTO stanza VALUES('Z574','3','我今等候，<br/>主，我今等候；<br/>完全与我调和，<br/>直到安家于我，<br/>你像在我显着-<br/>我今等候，我今等候。<br/>','',56735,10270);
INSERT INTO stanza VALUES('Z574','4','我今等候，<br/>主，我今等候；<br/>你旨向我明授，<br/>你路助我肯走，<br/>你命借我涌流-<br/>我今等候，我今等候。<br/>','',56736,10271);
INSERT INTO stanza VALUES('Z574','5','我今等候，<br/>主，我今等候；<br/>愿我所有祷告，<br/>都是你的发表，<br/>使神得着荣耀-<br/>我今等候，我今等候。<br/>','',56737,10272);
INSERT INTO stanza VALUES('Z575','1','我魂要肃静，<br/>等候你的主！<br/>先让祂说话，<br/>然后向祂诉。<br/>真实的祷告，<br/>乃是主发起；<br/>你仅是器皿，<br/>发表祂自己。<br/>','',56738,10273);
INSERT INTO stanza VALUES('Z575','2','我魂要肃静，<br/>等候你的主！<br/>你所有意念，<br/>全都要不顾。<br/>让神用自己，<br/>来将你涂抹，<br/>并借你祷告，<br/>且借你活着。<br/>','',56739,10274);
INSERT INTO stanza VALUES('Z575','3','我魂要肃静，<br/>等候你的主！<br/>停下你心愿，<br/>不再操己路。<br/>今生的忧虑、<br/>地上的呼召，<br/>全都丢一边，<br/>只顾神所要。<br/>','',56740,10275);
INSERT INTO stanza VALUES('Z575','4','我魂要肃静，<br/>等候你的主！<br/>将你的心意<br/>向灵全降服。<br/>并且要让灵<br/>指明神所示，<br/>如此你就作<br/>顺服的执事。<br/>','',56741,10276);
INSERT INTO stanza VALUES('Z575','5','我魂要肃静，<br/>等候你的主！<br/>学习更让灵<br/>经过你求诉。<br/>你整个的人<br/>都与灵相调，<br/>使你的祷告<br/>作神的发表。<br/>','',56742,10277);
INSERT INTO stanza VALUES('Z575','6','我魂要肃静，<br/>等候你的主！<br/>直等在灵里<br/>你与神相符。<br/>并且借着灵<br/>一切全归服，<br/>如此每部分<br/>都变得像主。<br/>','',56743,10278);
INSERT INTO stanza VALUES('Z575','7','我魂要肃静，<br/>等候你的主！<br/>使神能借你<br/>自由的流出，<br/>直到每时刻<br/>你言与你行，<br/>都使神心意<br/>借你得完成。<br/>','',56744,10279);
INSERT INTO stanza VALUES('Z576','1','复兴你工作，主！<br/>向你圣徒显现；<br/>求你用权发命监督，<br/>让你儿女检点。<br/>','',56745,10280);
INSERT INTO stanza VALUES('Z576','chorus','复兴你工作，主！<br/>我们现今等候；<br/>但愿正当我们俯伏，<br/>你就显现能手。<br/>','',56746,10281);
INSERT INTO stanza VALUES('Z576','2','复兴你工作，主！<br/>求你感动召会，<br/>为着罪恶，忧伤痛悔，<br/>好让你显作为。<br/>','',56747,10282);
INSERT INTO stanza VALUES('Z576','3','复兴你工作，主！<br/>启示你的宝贵；<br/>但愿你爱在人心内，<br/>好像复燃死灰。<br/>','',56748,10283);
INSERT INTO stanza VALUES('Z576','4','复兴你工作，主！<br/>祝福你的话语；<br/>但愿你道所有真理，<br/>到处被人高举。<br/>','',56749,10284);
INSERT INTO stanza VALUES('Z576','5','复兴你工作，主！<br/>证明你的得胜；<br/>但愿你民起来战争，<br/>使敌权势溃崩。<br/>','',56750,10285);
INSERT INTO stanza VALUES('Z576','6','复兴你工作，主！<br/>赐下当初权能；<br/>愿其荣耀全归你名，<br/>祝福则归我们。<br/>','',56751,10286);
INSERT INTO stanza VALUES('Z577','1','主给这个地方，<br/>给这个地方，<br/>将一个大复兴，<br/>给这个地方。<br/>除去所有阻挡，<br/>使我灵高昂，<br/>好叫我运生命<br/>来医治人伤。<br/>','',56752,10287);
INSERT INTO stanza VALUES('Z578','1','祷告之时、甘甜之时！<br/>使我离开烦恼之事，<br/>来到神的座前发表<br/>所有意愿、所有需要；<br/>当我遇到重压、忧愁，<br/>我灵却常得着自由，<br/>不陷恶者所有布置，<br/>因为有你-祷告之时！<br/>','',56753,10288);
INSERT INTO stanza VALUES('Z578','2','祷告之时、甘甜之时！<br/>如有双翼载我愿辞，<br/>到祂宝座向神求恳，<br/>祂是信实，祂是全真。<br/>祂既命我寻求祂面，<br/>信祂话语，靠祂恩典，<br/>我要将我重担卸释<br/>在于你前-甘甜之时！<br/>','',56754,10289);
INSERT INTO stanza VALUES('Z578','3','祷告之时、甘甜之时！<br/>每次相逢慰我心思，<br/>直到我在毗斯迦山，<br/>发现美地极目一看，<br/>脱下帐棚，安静等候，<br/>信心变见，盼望成就；<br/>临行我必大声告辞：<br/>平安、平安，祷告之时！<br/>','',56755,10290);
INSERT INTO stanza VALUES('Z579','1','全部的圣经<br/>都是神呼出，<br/>由神的圣灵<br/>用字来撰述；<br/>再借众神人<br/>将撰述记录，<br/>带着神丰富，<br/>给人来吸入。<br/>','',56756,10291);
INSERT INTO stanza VALUES('Z579','2','这是神呼出，<br/>作人的亮光，<br/>用神圣光线<br/>将人来照亮；<br/>照在黑暗中，<br/>使人能看明<br/>自己的需要、<br/>并真实光景。<br/>','',56757,10292);
INSERT INTO stanza VALUES('Z579','3','这是神呼出，<br/>作人的生命，<br/>使人能得着<br/>神圣的性情；<br/>点活死的人，<br/>且将人重生，<br/>更新人心思、<br/>变化魂生命。<br/>','',56758,10293);
INSERT INTO stanza VALUES('Z579','4','这是神呼出，<br/>作人的智慧，<br/>神圣的知识，<br/>教导人领会；<br/>向人来启示<br/>神永远旨意，<br/>领导人达到<br/>神终极目的。<br/>','',56759,10294);
INSERT INTO stanza VALUES('Z579','5','这是神呼出，<br/>作人的能力，<br/>神圣的能力，<br/>向人来供给；<br/>软弱者刚强，<br/>疲倦者加力，<br/>使人有力量<br/>完成神旨意。<br/>','',56760,10295);
INSERT INTO stanza VALUES('Z579','6','这是神呼出，<br/>为给我呼吸，<br/>好叫我享受<br/>神作我福气；<br/>借着运用灵，<br/>吸入神所呼，<br/>应付我需要，<br/>享受神丰富。<br/>','',56761,10296);
INSERT INTO stanza VALUES('Z580','1','主神已经说话，<br/>自己已启晓；<br/>祂的性格、身位，<br/>全给人知道；<br/>向着亚当子孙，<br/>启示祂心意，<br/>明言、豫表、豫言，<br/>描绘几无遗。<br/>','',56762,10297);
INSERT INTO stanza VALUES('Z580','2','主神已经说话，<br/>表明所欲为：<br/>要叫祂的儿子，<br/>凡事居首位，<br/>使祂在子里面，<br/>荣耀得完全，<br/>而在万有中间，<br/>得着了彰显。<br/>','',56763,10298);
INSERT INTO stanza VALUES('Z580','3','主神已经说话，<br/>基督已启示：<br/>虽然祂是真神，<br/>但人祂也是；<br/>祂是一切一切，<br/>充满了万有；<br/>是神计画里的<br/>中心与圆周。<br/>','',56764,10299);
INSERT INTO stanza VALUES('Z580','4','主神已经说话，<br/>天不再缄默：<br/>三一之神愿意<br/>来与人调和；<br/>父在子的里面，<br/>子又成为灵，<br/>住进基督身体，<br/>计划得完成。<br/>','',56765,10300);
INSERT INTO stanza VALUES('Z580','5','主神已经说话，<br/>启示祂奥秘：<br/>基督与祂召会，<br/>二者成为一；<br/>基督带神丰满，<br/>来作荣耀头；<br/>召会是祂身体，<br/>享受祂所有。<br/>','',56766,10301);
INSERT INTO stanza VALUES('Z580','6','主神已经说话，<br/>一切已启示：<br/>说到祂的创造，<br/>并说祂降世，<br/>说到祂的救赎，<br/>并说祂救恩；<br/>但愿地上万有，<br/>赞美祂不尽。<br/>','',56767,10302);
INSERT INTO stanza VALUES('Z581','1','哦主，<br/>神的活话，<br/>神的真像，<br/>你是神话内容，<br/>神圣宝藏；<br/>在你我们看见神的丰满，<br/>你又借着圣经向我显现。<br/>','',56768,10303);
INSERT INTO stanza VALUES('Z581','2','从未有人见神，<br/>在你之外，<br/>若无圣经你难启示出来；<br/>你已将神向人清楚表明，<br/>然而对你认识是借圣经。<br/>','',56769,10304);
INSERT INTO stanza VALUES('Z581','3','你是神的化身，<br/>具体、完全，<br/>圣经是你描述，<br/>真实、丰满；<br/>在你我们领略神的真像，<br/>但借圣经才能将你欣赏。<br/>','',56770,10305);
INSERT INTO stanza VALUES('Z581','4','你是生命之灵，<br/>你又是话，<br/>这话因灵丰盛，<br/>无以复加；<br/>借你内住之灵摸着这话，<br/>你就将你丰盛向我赐下。<br/>','',56771,10306);
INSERT INTO stanza VALUES('Z581','5','在你里面我可与神交通，<br/>借着圣经我能享你无穷；<br/>每凭经中话语向你读祷，<br/>你的丰富就顾我的需要。<br/>','',56772,10307);
INSERT INTO stanza VALUES('Z581','6','求主教我如何运用我灵，<br/>祷读你话，<br/>借以受你供应；<br/>你和经中话语相调为一，<br/>就作生命吗哪，<br/>每日供给。<br/>','',56773,10308);
INSERT INTO stanza VALUES('Z582','1','主，你是话，你也是灵，<br/>我们赞美同灵和声！<br/>赞美你话使我知晓，<br/>敬拜你灵使我触到。<br/>','',56774,10309);
INSERT INTO stanza VALUES('Z582','2','恩主，你是我的一切，<br/>全在你能与我联结；<br/>所以是话，且又是灵，<br/>为能来作我的供应。<br/>','',56775,10310);
INSERT INTO stanza VALUES('Z582','3','你若是主，而不是话，<br/>我要知你，有何办法？<br/>你若是神，而不是灵，<br/>我要触你，又怎可能？<br/>','',56776,10311);
INSERT INTO stanza VALUES('Z582','4','话是你的明确启示，<br/>使我对你能有认识；<br/>灵是你的本身本质，<br/>使我接触你的所是。<br/>','',56777,10312);
INSERT INTO stanza VALUES('Z582','5','你是我的生命、亮光、<br/>道路、真理、<br/>活水、灵粮；<br/>全借你话向我传递，<br/>并凭你灵使我经历。<br/>','',56778,10313);
INSERT INTO stanza VALUES('Z582','6','你话在于所写圣经，<br/>你灵就是内住圣灵；<br/>你话进入我心我灵，<br/>也就是灵，且是生命。<br/>','',56779,10314);
INSERT INTO stanza VALUES('Z582','7','我要明白你的圣经，<br/>也要接触你的圣灵；<br/>不仅凭着头脑明瞭，<br/>且要用灵敬拜祷告。<br/>','',56780,10315);
INSERT INTO stanza VALUES('Z582','7','你话乃是我心所爱，<br/>你灵更是我灵所拜；<br/>在你话中我心欢畅，<br/>在你灵里我灵歌唱。<br/>','',56781,10316);
INSERT INTO stanza VALUES('Z583','1','愿主为我擘开生命的饼，<br/>就像当日旁海对众所行。<br/>靠这圣书引导，<br/>我寻求你；<br/>我主，神的活道，<br/>我渴慕你！<br/>','',56782,10317);
INSERT INTO stanza VALUES('Z583','2','愿主为我擘开生命的饼，<br/>使我充满主爱，<br/>记念主名！<br/>释放我的思想脱离自己，<br/>好叫我的倾向都在乎你。<br/>','',56783,10318);
INSERT INTO stanza VALUES('Z583','3','惟主解开真理，我才明白<br/>你的一切信息如何警策；<br/>使我与你同情，<br/>与你同行，<br/>使我逐日变化，<br/>像你荣形。<br/>','',56784,10319);
INSERT INTO stanza VALUES('Z583','4','爱主，求你祝福<br/>你的真理，<br/>像你为饼祝福在加利利；<br/>叫我捆绑都脱，<br/>锁炼都落，<br/>自由为你生活，<br/>为你工作。<br/>','',56785,10320);
INSERT INTO stanza VALUES('Z584','1','主，你没有一句为我？<br/>使我更能向你信托，<br/>使我更能离开喜欲，<br/>一句，我主，求赐一句。<br/>','',56786,10321);
INSERT INTO stanza VALUES('Z584','2','一句来显我的软弱，<br/>当我欣赏自己工作；<br/>我空劳碌，我空叹吁，<br/>一句，我主，求赐一句。<br/>','',56787,10322);
INSERT INTO stanza VALUES('Z584','3','一句来示你的相亲，<br/>因你乃是住在我心，<br/>你的生命我也同豫，<br/>一句，我主，求赐一句。<br/>','',56788,10323);
INSERT INTO stanza VALUES('Z584','4','一句，求将有力应许<br/>显在许多畏惧、罣虑，<br/>你微而清所说话语，<br/>一句，我主，求赐一句。<br/>','',56789,10324);
INSERT INTO stanza VALUES('Z584','5','一句最终得胜呼喊，<br/>得你应许甘甜盘桓，<br/>与你永远快乐同居，<br/>一句，我主，求赐一句。<br/>','',56790,10325);
INSERT INTO stanza VALUES('Z585','1','求主静中发言，<br/>当我在等候；<br/>我心在此静听，<br/>望允我所求。<br/>','',56791,10326);
INSERT INTO stanza VALUES('Z585','2','恩主，求来发言，<br/>在这安静时；<br/>让我见你荣面，<br/>感到你所指。<br/>','',56792,10327);
INSERT INTO stanza VALUES('Z585','3','你所说的话语，<br/>是灵、是生命；<br/>天上来的活粮，<br/>将我灵供应。<br/>','',56793,10328);
INSERT INTO stanza VALUES('Z585','4','一切全都归你，<br/>不再属自己；<br/>甘心乐意降服，<br/>我只属于你。<br/>','',56794,10329);
INSERT INTO stanza VALUES('Z585','5','请说，仆人敬听，<br/>哦主，勿静默；<br/>我灵向你仰望，<br/>活话愿得着。<br/>','',56795,10330);
INSERT INTO stanza VALUES('Z585','6','用你丰富话语，<br/>将我心充满；<br/>使你一切心愿，<br/>在我得成全。<br/>','',56796,10331);
INSERT INTO stanza VALUES('Z585','7','像一灌溉花园，<br/>充满了香气，<br/>给你进来欣赏，<br/>满足你心意。<br/>','',56797,10332);
INSERT INTO stanza VALUES('Z586','1','主阿，我心我灵<br/>又渴又饥，<br/>今来就你，<br/>求你给我供给；<br/>我所需要乃是你的自己，<br/>作我生命供应，<br/>作我能力。<br/>','',56798,10333);
INSERT INTO stanza VALUES('Z586','chorus','喂我饮我，主，<br/>喂我饮我！<br/>充我饥饿，主，<br/>解我干渴！<br/>使我快乐，<br/>并且有力生活，<br/>喂我饮我，主，<br/>喂我饮我！<br/>','',56799,10334);
INSERT INTO stanza VALUES('Z586','2','你是我的食物、<br/>我的活水，<br/>你能解我饥渴，<br/>苏我困惫。<br/>我今愿在这里吃你喝你，<br/>借着读祷享受你的自己。<br/>','',56800,10335);
INSERT INTO stanza VALUES('Z586','3','你乃是话，<br/>藏着神的丰盛；<br/>你又是灵，<br/>就是神作生命。<br/>你今是话，<br/>作我食物可享；<br/>你今是灵，<br/>作我活水可尝。<br/>','',56801,10336);
INSERT INTO stanza VALUES('Z586','4','为作食物，<br/>你已从天降下；<br/>为流活水，<br/>你也受了击打。<br/>食物是你作了我的供应；<br/>活水是你为我所流之灵。<br/>','',56802,10337);
INSERT INTO stanza VALUES('Z586','5','你今是话，<br/>是灵也是生命，<br/>在这话里，<br/>我能得你供应；<br/>你今是灵，<br/>住在我的灵里，<br/>在这灵中，<br/>我能饮你自己。<br/>','',56803,10338);
INSERT INTO stanza VALUES('Z586','6','我今到这话里来享受你；<br/>也要在这灵中来吸取你。<br/>愿将你话吃饱，<br/>免得饥饿；<br/>愿将你灵喝足，<br/>免得干渴。<br/>','',56804,10339);
INSERT INTO stanza VALUES('Z586','7','但愿我的读经乃是吃你；<br/>也愿我的祷告就是喝你。<br/>读读祷祷，<br/>我就将你吃饱；<br/>祷祷读读，<br/>也就将你喝了。<br/>','',56805,10340);
INSERT INTO stanza VALUES('Z586','7','但愿你的自己作我筵席；<br/>你话你灵为我解渴充饥，<br/>使我得在这里吃你喝你，<br/>丰丰满满享受你的自己。<br/>','',56806,10341);
INSERT INTO stanza VALUES('Z587','1','我今来到施恩座前，<br/>得你怜恤，蒙你恩典，<br/>作我所需应时帮助，<br/>使我心、灵得到安舒。<br/>','',56807,10342);
INSERT INTO stanza VALUES('Z587','2','在此瞻仰你的荣面，<br/>你的面光照我心间，<br/>放出你的医治光线，<br/>消杀我的软弱、缺点。<br/>','',56808,10343);
INSERT INTO stanza VALUES('Z587','3','在此你的亮光照明，<br/>显示我的真实情形；<br/>你血也就显出功能，<br/>将我罪污全都洗净。<br/>','',56809,10344);
INSERT INTO stanza VALUES('Z587','4','你的膏油也在涂抹，<br/>你的成分给我得着；<br/>我就享受你的自己，<br/>也就摸着你的心意。<br/>','',56810,10345);
INSERT INTO stanza VALUES('Z587','5','我愿在你面前读经，<br/>犹如祭司圣所点灯；<br/>需要你灵像油一样，<br/>使你话语放明发光。<br/>','',56811,10346);
INSERT INTO stanza VALUES('Z587','6','也愿在此向你祷告，<br/>好像祭司将香焚烧；<br/>灵里基督如香一般，<br/>调着祷告向神呈献。<br/>','',56812,10347);
INSERT INTO stanza VALUES('Z587','7','你话是灯，也是食物，<br/>我蒙光照，也得饱足；<br/>深愿在此多读多吃，<br/>受到启示，得着粮食。<br/>','',56813,10348);
INSERT INTO stanza VALUES('Z587','7','基督是香，也是活水，<br/>我蒙悦纳，也脱困惫；<br/>也愿在此多祷多喝，<br/>献上香气，流出江河。<br/>','',56814,10349);
INSERT INTO stanza VALUES('Z587','9','读经使我明亮、不饿，<br/>祷告使我馨香、不渴；<br/>读读祷祷你就注入，<br/>祷祷读读你就流出。<br/>','',56815,10350);
INSERT INTO stanza VALUES('Z587','10','我愿如此与你相交，<br/>读祷、祷读与你相调；<br/>也愿如此给你浸透，<br/>直到你能从我涌流！<br/>','',56816,10351);
INSERT INTO stanza VALUES('Z588','1','主阿，我来就你，<br/>我心饥渴要你！<br/>深愿在此吃你喝你，<br/>享受你的自己。<br/>','',56817,10352);
INSERT INTO stanza VALUES('Z588','2','得见你的面目，<br/>乃是我心所慕！<br/>甚愿在此与你接触，<br/>灵里得着饱足。<br/>','',56818,10353);
INSERT INTO stanza VALUES('Z588','3','你的荣耀面光，<br/>我心何等欣赏！<br/>真愿留此不再他往，<br/>一直向你瞻仰。<br/>','',56819,10354);
INSERT INTO stanza VALUES('Z588','4','在这交通里面，<br/>你是我的恩典！<br/>使我心欢，使我灵满，<br/>全人进入平安。<br/>','',56820,10355);
INSERT INTO stanza VALUES('Z588','5','还要在此等候，<br/>还要向你寻求！<br/>读经、祷告交替不休，<br/>直到被你浸透！<br/>','',56821,10356);
INSERT INTO stanza VALUES('Z589','1','『活着不是单靠食物，<br/>乃靠神口所出的话；』<br/>因此须将神话当作<br/>生命之粮，时常吃下。<br/>','',56822,10357);
INSERT INTO stanza VALUES('Z589','2','我们受造非仅身体，<br/>乃是身体与魂与灵；<br/>灵是里面最深部分，<br/>为着接受神作供应。<br/>','',56823,10358);
INSERT INTO stanza VALUES('Z589','3','正如我们身体需要<br/>属地物质食物营养，<br/>灵也需要神的话语，<br/>作牠属天生命食粮。<br/>','',56824,10359);
INSERT INTO stanza VALUES('Z589','4','主，你是灵，且借你话<br/>将你自己完全表明；<br/>我今需要运用我灵，<br/>借着你话接受你灵。<br/>','',56825,10360);
INSERT INTO stanza VALUES('Z589','5','因此，我们接受你话，<br/>非仅用眼读其字句，<br/>并用心思领会其意，<br/>更须用灵将其吸取。<br/>','',56826,10361);
INSERT INTO stanza VALUES('Z589','6','须在灵里吃你的话，<br/>将其接到最深部分；<br/>运用我灵祷读你话，<br/>你就供应，浸透全人。<br/>','',56827,10362);
INSERT INTO stanza VALUES('Z589','7','你话留在我的心思，<br/>仅是知识，变作重担；<br/>若被接受到我灵里，<br/>就变灵与生命、平安。<br/>','',56828,10363);
INSERT INTO stanza VALUES('Z589','7','当我真肯运用我灵，<br/>接受你话并接触你，<br/>我就得着你话喂养，<br/>深处摸着你的自己。<br/>','',56829,10364);
INSERT INTO stanza VALUES('Z589','9','哦主，教我每读你话，<br/>就肯操练运用我灵，<br/>好使我灵得到喂养，<br/>你就作我生命供应。<br/>','',56830,10365);
INSERT INTO stanza VALUES('Z590','1','基督是话，祂也是灵，<br/>且是祂话里面的灵；<br/>祂对我们所说的话，<br/>都是灵，也都是生命。<br/>','',56831,10366);
INSERT INTO stanza VALUES('Z590','2','神在外面赐我圣经，<br/>也在里面赐我圣灵；<br/>二者是神极大礼物，<br/>使我享受神作供应。<br/>','',56832,10367);
INSERT INTO stanza VALUES('Z590','3','圣经乃借圣灵表明，<br/>圣灵乃是圣经实际；<br/>二者乃是一物两面，<br/>永远不可彼此分离。<br/>','',56833,10368);
INSERT INTO stanza VALUES('Z590','4','圣经一经圣灵照亮，<br/>到我灵中就是生命；<br/>圣经若与圣灵分开，<br/>立变虚空，毫无供应。<br/>','',56834,10369);
INSERT INTO stanza VALUES('Z590','5','当我用灵接触圣经，<br/>牠就变成灵作生命；<br/>当灵从我发表出去，<br/>又成为话将人供应。<br/>','',56835,10370);
INSERT INTO stanza VALUES('Z590','6','必须运用我们的灵，<br/>深处接受神的圣经；<br/>然后当灵释放出去，<br/>灵、经乃一，在我证明。<br/>','',56836,10371);
INSERT INTO stanza VALUES('Z590','7','主，愿你话在我里面，<br/>能成为灵作我生命；<br/>并愿你灵在你话里，<br/>成为我的真实表明。<br/>','',56837,10372);
INSERT INTO stanza VALUES('Z591','1','神的话语非仅知识，<br/>更是生命赐给人；<br/>非仅传递神的思想，<br/>更是使人得着神；<br/>非仅启示神的心意，<br/>更是带来生命主；<br/>非仅供给一些教训，<br/>更是供应主基督。<br/>','',56838,10373);
INSERT INTO stanza VALUES('Z591','2','我们若仅读其字句，<br/>神话不过是知识；<br/>但若用灵将其祷读，<br/>就是生命，真又实。<br/>所有字句、各种知识，<br/>只将死亡带给我；<br/>惟有灵里接受的话，<br/>供给生命使我活。<br/>','',56839,10374);
INSERT INTO stanza VALUES('Z591','3','只读圣经，而不触主，<br/>仅得虚空的知识；<br/>若在灵里摸着基督，<br/>就得生命的美食。<br/>只读字句，而不摸主，<br/>仅叫心思得供应；<br/>若用祷读接触基督，<br/>灵得丰盛的生命。<br/>','',56840,10375);
INSERT INTO stanza VALUES('Z591','4','圣经所有各种知识，<br/>都须变化成生命；<br/>头脑所有各种领会，<br/>都须灵中再成形。<br/>对于圣经所有明白，<br/>都须生命的流通；<br/>对于字句所有认识，<br/>都须接受到灵中。<br/>','',56841,10376);
INSERT INTO stanza VALUES('Z591','5','接触圣经为得知识，<br/>乃效夏娃之所为；<br/>撒但就是借着知识，<br/>引诱女祖去犯罪。<br/>若当生命接受圣经，<br/>就是来吃生命树；<br/>因此必须将主话语，<br/>接到灵里作食物。<br/>','',56842,10377);
INSERT INTO stanza VALUES('Z592','1','我们享受基督丰富，<br/>就得成为祂的丰满；<br/>分享一切祂之所是，<br/>就能使祂得着彰显。<br/>','',56843,10378);
INSERT INTO stanza VALUES('Z592','2','基督丰富是祂所是，<br/>来作我们一切享受；<br/>基督丰满乃是召会，<br/>因享基督而得成就。<br/>','',56844,10379);
INSERT INTO stanza VALUES('Z592','3','迦南美地丰富出产，<br/>乃是豫表基督丰富；<br/>借这出产圣殿得成，<br/>象征召会出于基督。<br/>','',56845,10380);
INSERT INTO stanza VALUES('Z592','4','夏娃乃是亚当丰满，<br/>豫表召会之于基督；<br/>夏娃原是出于亚当，<br/>基督也是召会出处。<br/>','',56846,10381);
INSERT INTO stanza VALUES('Z592','5','丰富是我里面基督，<br/>丰满是我外面召会；<br/>充满基督，作祂表现，<br/>得与基督同样宝贵。<br/>','',56847,10382);
INSERT INTO stanza VALUES('Z593','1','神是人所不能见者，<br/>从未有人见过祂形；<br/>但有基督作祂奥秘，<br/>将祂向人全然表明。<br/>','',56848,10383);
INSERT INTO stanza VALUES('Z593','2','基督乃是神的活话，<br/>是神惟一真实说明；<br/>祂是神的具体化身，<br/>在祂得见神的本性。<br/>','',56849,10384);
INSERT INTO stanza VALUES('Z593','3','基督是神本体真像，<br/>是神荣耀所发光辉；<br/>神的丰满住祂里面，<br/>神之所是由祂发挥。<br/>','',56850,10385);
INSERT INTO stanza VALUES('Z593','4','基督现今也是隐瞒，<br/>地上今日无人能见；<br/>但有召会作祂奥秘，<br/>到处将祂显于人前。<br/>','',56851,10386);
INSERT INTO stanza VALUES('Z593','5','召会是祂丰满表现，<br/>祂是召会内容生命；<br/>召会是祂真实复本，<br/>祂借召会向人显明。<br/>','',56852,10387);
INSERT INTO stanza VALUES('Z593','6','召会具有基督形像，<br/>是祂扩增，是祂普及；<br/>祂之所是全在召会，<br/>召会乃是祂的身体。<br/>','',56853,10388);
INSERT INTO stanza VALUES('Z593','7','父神乃在子神里面，<br/>子神且已成为那灵；<br/>现今这位三一神灵，<br/>是与召会合一同性。<br/>','',56854,10389);
INSERT INTO stanza VALUES('Z594','1','身体乃是人的丰满，<br/>表现人生命；<br/>照样，召会是主身体，<br/>使祂得显明。<br/>','',56855,10390);
INSERT INTO stanza VALUES('Z594','2','夏娃乃是亚当一部，<br/>出自于亚当；<br/>召会也是基督扩增，<br/>出于祂肋旁。<br/>','',56856,10391);
INSERT INTO stanza VALUES('Z594','3','一粒麦子落地死了，<br/>结出许多粒；<br/>许多子粒磨粉相调，<br/>就成为一体。<br/>','',56857,10392);
INSERT INTO stanza VALUES('Z594','4','照样基督死而复活，<br/>也得了繁生；<br/>许多信徒成为一身，<br/>来将祂表明。<br/>','',56858,10393);
INSERT INTO stanza VALUES('Z594','5','葡萄树的许多枝子，<br/>乃是树开展，<br/>与树合一，住树里面，<br/>结果显丰满。<br/>','',56859,10394);
INSERT INTO stanza VALUES('Z594','6','照样，基督许多肢体<br/>也是祂扩大，<br/>与祂成一，活在祂里，<br/>使祂得发达。<br/>','',56860,10395);
INSERT INTO stanza VALUES('Z594','7','繁殖、扩增、开展、普及、<br/>长大与表现、复本、再世、<br/>继续、富余、扩大与丰满：<br/>','',56861,10396);
INSERT INTO stanza VALUES('Z594','8','这是召会之于基督，<br/>使神得荣耀；<br/>借着祂所救赎的人，<br/>永远来显照。<br/>','',56862,10397);
INSERT INTO stanza VALUES('Z594','9','乃是基督与祂召会-<br/>神的大奥秘；<br/>乃是神性与我人性，<br/>相调成为一。<br/>','',56863,10398);
INSERT INTO stanza VALUES('Z595','1','召会乃是基督器皿，<br/>将祂盛装，将祂彰显；<br/>犹如人的血肉身体，<br/>人在其中得着表现。<br/>','',56864,10399);
INSERT INTO stanza VALUES('Z595','2','如同圣殿之于约柜，<br/>是其容器、安息之所；<br/>召会乃是基督住处，<br/>内容基督在她住着。<br/>','',56865,10400);
INSERT INTO stanza VALUES('Z595','3','基督乃是神的奥秘，<br/>将神解说，将神表现；<br/>召会也是基督奥秘，<br/>将祂言明，将祂彰显。<br/>','',56866,10401);
INSERT INTO stanza VALUES('Z595','4','基督召会所有肢体，<br/>原都属于泥土之类；<br/>所以需要重生变化，<br/>变为透明，成为宝贵。<br/>','',56867,10402);
INSERT INTO stanza VALUES('Z595','5','借着变化同被建造，<br/>来作基督透明器皿；<br/>盛装基督所有丰盛，<br/>将祂一切显于人群。<br/>','',56868,10403);
INSERT INTO stanza VALUES('Z595','6','三一之神合作同工，<br/>完成所有变化工作；<br/>召会得成团体器皿，<br/>如同圣城作神居所。<br/>','',56869,10404);
INSERT INTO stanza VALUES('Z595','7','如此召会何其宝贵，<br/>各方都是透明、透亮；<br/>盛装基督和神丰满，<br/>照出基督和神荣光。<br/>','',56870,10405);
INSERT INTO stanza VALUES('Z595','7','神作亮光，主作生命，<br/>灵作活的生命水流；<br/>三一之神由她彰显，<br/>显于万有直到永久！<br/>','',56871,10406);
INSERT INTO stanza VALUES('Z596','1','召会乃是精金灯台，<br/>基督是灯，神是其光；<br/>神圣之光由主照出，<br/>召会托住，荣耀辉煌。<br/>','',56872,10407);
INSERT INTO stanza VALUES('Z596','2','灯中照出神圣之光，<br/>乃是神作生命照亮；<br/>因此灯台须属精金，<br/>配合神的圣别荣光。<br/>','',56873,10408);
INSERT INTO stanza VALUES('Z596','3','在这黑暗时代之中，<br/>神圣生命之光照亮，<br/>照在许多人群中心，<br/>将主见证向人释放。<br/>','',56874,10409);
INSERT INTO stanza VALUES('Z596','4','要作这个纯洁见证，<br/>『起初的爱』必须保守；<br/>如此，那得胜者之分-<br/>『生命树果，』<br/>必得享受。<br/>','',56875,10410);
INSERT INTO stanza VALUES('Z596','5','必须忍受苦难、逼迫，<br/>才能得着『生命冠冕；』<br/>属灵淫乱也要胜过，<br/>『隐藏吗哪』始得饱餐。<br/>','',56876,10411);
INSERT INTO stanza VALUES('Z596','6','弃绝『耶洗别』之所为，<br/>就能得着辖管之权；<br/>死的玷污要全胜过，<br/>洁义『白衣』就必得穿。<br/>','',56877,10412);
INSERT INTO stanza VALUES('Z596','7','必须如同『非拉铁非，』<br/>遵守主话，不弃主名；<br/>『温水』自满，<br/>尽都胜过，<br/>与主同筵，享祂丰盛。<br/>','',56878,10413);
INSERT INTO stanza VALUES('Z596','7','召会必须如此纯洁，<br/>成为明净精金灯台，<br/>配合主的纯洁见证，<br/>照明基督，荣光满载。<br/>','',56879,10414);
INSERT INTO stanza VALUES('Z596','9','地上各处地方召会，<br/>在这时代作这灯台；<br/>将来圣城耶路撒冷，<br/>作这灯台直到万代。<br/>','',56880,10415);
INSERT INTO stanza VALUES('Z596','10','圣城宝贵如同精金，<br/>作主灯台最终出现；<br/>永远托着基督作灯，<br/>使神圣光照耀灿烂。<br/>','',56881,10416);
INSERT INTO stanza VALUES('Z597','1','神在永远创世之前，<br/>喜悦、拣选并豫定，<br/>要叫召会在子里面，<br/>得子名分成为圣；<br/>得蒙救赎，作祂产业，<br/>受祂圣灵为印记，<br/>保证必得祂的基业，<br/>并得先享祂自己。<br/>','',56882,10417);
INSERT INTO stanza VALUES('Z597','2','基督升天坐在神右，<br/>远超一切的势力；<br/>神使祂作万有元首，<br/>召会是祂的身体。<br/>万有一切祂全充满，<br/>召会乃是祂丰满，<br/>祂借召会普及、曼延，<br/>召会彰显祂完全。<br/>','',56883,10418);
INSERT INTO stanza VALUES('Z597','3','原是死在罪恶之中，<br/>随从今世的风俗，<br/>撒但、邪灵竟也顺从，<br/>放纵肉体真可怒。<br/>今与基督一同复活，<br/>一同坐在高天上，<br/>成为神的荣耀杰作，<br/>基督里面所独创。<br/>','',56884,10419);
INSERT INTO stanza VALUES('Z597','4','基督作了房角首石，<br/>使徒、先知为根基，<br/>照着神的奥秘启示，<br/>犹太、外邦归一体；<br/>在祂里面同被建造，<br/>作神灵里的居所；<br/>在灵里面彼此相调，<br/>给神定居享安乐。<br/>','',56885,10420);
INSERT INTO stanza VALUES('Z597','5','神的奥秘乃是召会，<br/>神在永远所计画，<br/>为着彰显祂的智慧，<br/>基督也可来安家。<br/>给众圣徒明白基督，<br/>赏识基督的无限，<br/>知道祂爱超人领悟，<br/>充满神性的丰满。<br/>','',56886,10421);
INSERT INTO stanza VALUES('Z597','6','一身、一灵、同一指望，<br/>一主、一信并一洗，<br/>一位父神，众人之上，<br/>召会因此当合一。<br/>认识基督，长大成人，<br/>有祂丰满的身量；<br/>不再受到诱骗、牵引，<br/>不再随风而飘荡。<br/>','',56887,10422);
INSERT INTO stanza VALUES('Z597','7','基督赐下各样恩赐，<br/>为要建造祂身体，<br/>成全圣徒各尽其职，<br/>爱中建造她自己。<br/>脱去旧人，穿上新人，<br/>再无从前的旧样；<br/>心思灵里得以更新，<br/>满有主神的形像。<br/>','',56888,10423);
INSERT INTO stanza VALUES('Z597','7','基督舍己为爱召会，<br/>要使召会脱斑皱，<br/>圣洁，毫无瑕疵、污秽，<br/>作祂荣耀的配偶。<br/>祂爱召会，保养、顾惜，<br/>如待自己的身体；<br/>祂与召会成为一体，<br/>乃是极大的奥秘。<br/>','',56889,10424);
INSERT INTO stanza VALUES('Z597','9','身体、居所、<br/>新人、配偶，<br/>召会不仅是这些；<br/>也是战士，为神争斗，<br/>将神仇敌全除灭。<br/>穿戴神的全副军装，<br/>赖主大能而刚强；<br/>靠主站住，靠灵抵挡，<br/>祷告随时又多方。<br/>第七节的『心思灵里，』意思是在心思的灵里。<br/>','',56890,10425);
INSERT INTO stanza VALUES('Z598','1','召会是主的身体，<br/>也是神的居所；<br/>是众圣徒的结集，<br/>也是神人调和；<br/>创世以前神所选，<br/>十架主死所赎；<br/>性质、地位全属天，<br/>地上任何不属。<br/>','',56891,10426);
INSERT INTO stanza VALUES('Z598','2','她是新造的新人，<br/>基督复活所生；<br/>圣灵里面受了浸，<br/>借道之洗成圣。<br/>基督是她的生命，<br/>又是她的元首；<br/>她与基督同性情，<br/>高升远超万有。<br/>','',56892,10427);
INSERT INTO stanza VALUES('Z598','3','她的根基已立定，<br/>乃是耶稣基督；<br/>能与基督同神圣，<br/>才是她的事物。<br/>凡属她者都需要<br/>经过十架妙死，<br/>在复活里被建造，<br/>全是金、银、宝石。<br/>','',56893,10428);
INSERT INTO stanza VALUES('Z598','4','她的元素全是一：<br/>一神、一主、一灵、<br/>一身、一信并一洗，<br/>一望，神所命定。<br/>三一之神在里面，<br/>众人成为一身，<br/>借信联结，因洗断，<br/>凭望等候主临。<br/>','',56894,10429);
INSERT INTO stanza VALUES('Z598','5','她的所有众肢体，<br/>出自各方、各民，<br/>全都结合成为一，<br/>不分任何身分；<br/>没有犹太或外邦，<br/>没有自主、为奴，<br/>没有卑下或高尚，<br/>只有新人『基督。』<br/>','',56895,10430);
INSERT INTO stanza VALUES('Z598','6','宇宙之中独一个，<br/>分在各地出现；<br/>一地一会为原则，<br/>地方立场为限。<br/>地方行政虽独立，<br/>各向元首负责，<br/>宇宙交通却一体，<br/>无何离异间隔。<br/>','',56896,10431);
INSERT INTO stanza VALUES('Z598','7','她在各地的出现，<br/>都是撒冷雏形；<br/>为作基督的丰满，<br/>先有圣城情景：<br/>基督是灯，神是光，<br/>她是灯台照明，<br/>显出荣耀的形像，<br/>直到撒冷完成。<br/>','',56897,10432);
INSERT INTO stanza VALUES('Z599','1','召会的种子，<br/>乃基督自己<br/>作生命子粒，<br/>撒在人心里，<br/>要长成麦子，<br/>细面能产出，<br/>作食物使<br/>神与人得满足。<br/>','',56898,10433);
INSERT INTO stanza VALUES('Z599','2','但魔鬼却来，<br/>把虚假信徒<br/>撒在圣徒中，<br/>使圣徒迷糊，<br/>像稗子阻碍<br/>麦子的生长，<br/>使麦子不能<br/>供神、人饱享。<br/>','',56899,10434);
INSERT INTO stanza VALUES('Z599','3','召会的生命<br/>应该像嫩菜，<br/>从那芥菜种<br/>-基督-长出来；<br/>暂时长地上，<br/>式微且不显，<br/>却可作食物，<br/>供饥者饱餐。<br/>','',56900,10435);
INSERT INTO stanza VALUES('Z599','4','但魔鬼却来，<br/>使式微之菜<br/>改变了性质，<br/>也改了形态，<br/>而长成一棵<br/>显耀的大树，<br/>给许多恶者<br/>作栖身之处。<br/>','',56901,10436);
INSERT INTO stanza VALUES('Z599','5','魔鬼且利用<br/>变质的『召会，』<br/>带进来外邦<br/>邪恶的俗规，<br/>如同将面酵<br/>搀在细面里，<br/>败坏其纯洁，<br/>破坏神目的。<br/>','',56902,10437);
INSERT INTO stanza VALUES('Z599','6','但主作生命，<br/>要变化圣徒，<br/>使他们成为<br/>宝石和珍珠，<br/>作贵重材料，<br/>建造成召会，<br/>有国度之实，<br/>光荣又宝贵。<br/>','',56903,10438);
INSERT INTO stanza VALUES('Z599','7','靠主作生命，<br/>召会得生长，<br/>与基督调和，<br/>变成祂形像；<br/>像藏地宝贝<br/>和贵重珍珠，<br/>适合主建造，<br/>带进神国度。<br/>','',56904,10439);
INSERT INTO stanza VALUES('Z599','7','求主从『稗子』<br/>将我们分出，<br/>救我们脱离<br/>那宗教『大树，』<br/>从我们除去<br/>所有的『面酵，』<br/>使得作食物，<br/>供神人需要。<br/>','',56905,10440);
INSERT INTO stanza VALUES('Z599','9','使我们生长<br/>在你生命里，<br/>得以被变化<br/>建造成一体，<br/>作你的召会，<br/>彰显你自己，<br/>叫你能得着<br/>国度的实际。<br/>','',56906,10441);
INSERT INTO stanza VALUES('Z600','1','圣徒实际活在一起，<br/>才是召会的合一；<br/>内住圣灵将这合一<br/>放在所有圣徒里。<br/>因是出于圣灵自己，<br/>故称圣灵的合一；<br/>乃是根据所有圣徒<br/>同得之信而有的。<br/>','',56907,10442);
INSERT INTO stanza VALUES('Z600','2','所有圣徒共同所得<br/>一样宝贵的信心，<br/>组成是以基督和祂<br/>救赎工作为成分。<br/>在此圣徒真是合一，<br/>信仰全同，无异议；<br/>由于这个同得之信，<br/>始有召会的存立。<br/>','',56908,10443);
INSERT INTO stanza VALUES('Z600','3','宇宙召会既然是一，<br/>作主基督的产业；<br/>各地召会也该是一，<br/>作主表现无分别。<br/>召会元素原都是一：<br/>一神、一主并一灵，<br/>一信、一洗并一身体，<br/>一望由于神命定。<br/>','',56909,10444);
INSERT INTO stanza VALUES('Z600','4','这『一』就是召会立场，<br/>圣徒共同的立场，<br/>就是合一独一立场，<br/>圣灵在我所愿望。<br/>借此，召会就能实行<br/>真正实际的合一，<br/>她在各地所有出现<br/>也就因此得建立。<br/>','',56910,10445);
INSERT INTO stanza VALUES('Z600','5','主，使我们竭力保守<br/>这个圣灵的合一，<br/>站在召会合一立场，<br/>身体生活来经历。<br/>使你心中伟大愿望，<br/>因此就可得实现，<br/>使神心爱永远计划，<br/>也可完满得成全。<br/>','',56911,10446);
INSERT INTO stanza VALUES('Z601','1','神子基督和<br/>祂救赎的工作，<br/>是我得救信仰，<br/>圣徒同守着；<br/>其他一切道理，<br/>不在信仰内，<br/>惟有基督工作，<br/>和祂的身位。<br/>','',56912,10447);
INSERT INTO stanza VALUES('Z601','2','此外一切教训，<br/>若用之不当，<br/>就成『教训之风』，<br/>使合一受伤；<br/>能从元首基督，<br/>将圣徒吹开，<br/>并不建造身体，<br/>反倒是毁坏。<br/>','',56913,10448);
INSERT INTO stanza VALUES('Z601','3','因此必须清除<br/>各种的道理，<br/>只是守住信仰，<br/>来实行合一。<br/>在基督那灵里，<br/>我们确是一；<br/>只要保守这一，<br/>其他可放弃。<br/>','',56914,10449);
INSERT INTO stanza VALUES('Z601','4','真理-基督自己-<br/>我们须持守，<br/>如此就从宗派<br/>得蒙主拯救，<br/>并在凡事<br/>长到基督的里面，<br/>身体就得建造，<br/>作主的丰满。<br/>','',56915,10450);
INSERT INTO stanza VALUES('Z601','5','我们必须达到<br/>『信仰的合一』，<br/>所有『教训之风』，<br/>永远都离弃；<br/>灵中持守基督，<br/>作我们实际，<br/>好使身体增长，<br/>借着这合一。<br/>','',56916,10451);
INSERT INTO stanza VALUES('Z602','1','主阿，你是房角首石，<br/>犹太匠人所轻弃；<br/>但你却为神所珍视，<br/>从死复活所设立。<br/>我们靠你得蒙救恩，<br/>也得一同被建造；<br/>犹太、外邦成一新人，<br/>作神居所永和好。<br/>','',56917,10452);
INSERT INTO stanza VALUES('Z602','2','主，你也是属灵磐石，<br/>非仅为解人干渴，<br/>也非仅为给人倚恃，<br/>更是为造神居所。<br/>你是锡安所放基石，<br/>试过、稳固，神所立；<br/>也是召会所靠磐石，<br/>召会惟一的根基。<br/>','',56918,10453);
INSERT INTO stanza VALUES('Z602','3','召会建造在你身上，<br/>阴间之门难胜过；<br/>虽经各种风雨冲撞，<br/>仍然屹立不灭没。<br/>召会在此有你权柄，<br/>捆绑你所要捆绑；<br/>带进天国，驱逐邪灵，<br/>释放你所要释放。<br/>','',56919,10454);
INSERT INTO stanza VALUES('Z602','4','主，你更是生命活石，<br/>神所拣选、所宝贵，<br/>也使我们成为活石，<br/>与你同性、同地位；<br/>同被建造成为灵宫，<br/>就是祭司的体系，<br/>给神居住，对神事奉，<br/>献上可悦的灵祭。<br/>','',56920,10455);
INSERT INTO stanza VALUES('Z602','5','主，你又是大卫苗裔，<br/>为要建造神圣殿；<br/>君王、祭司两职合一，<br/>你就得尽你职权。<br/>你作君王为神掌权，<br/>权柄人就肯顺服；<br/>你作祭司显在神前，<br/>交通人就能进入。<br/>','',56921,10456);
INSERT INTO stanza VALUES('Z602','6','权柄出于神的宝座，<br/>使神子民能平定；<br/>交通来自生命水河，<br/>叫神子民得供应。<br/>权柄、交通平衡并行，<br/>建造进行才可能；<br/>君王、祭司在你合并，<br/>神的建造得完成。<br/>','',56922,10457);
INSERT INTO stanza VALUES('Z602','7','你是神成肉身帐幕，<br/>是神荣耀的圣殿；<br/>神在你里人间居住，<br/>在你里面得彰显。<br/>又是召会，神、人联属，<br/>充满一切神丰满；<br/>且是我们每个圣徒，<br/>为着建造神圣殿。<br/>','',56923,10458);
INSERT INTO stanza VALUES('Z602','7','哦，你还是永久居所，<br/>我们历代的住处，<br/>在你里面我们生活，<br/>得蒙永远的遮护。<br/>你对我们也是圣所，<br/>神与我们的同在，<br/>我们和神共同生活，<br/>向神不断的敬拜。<br/>','',56924,10459);
INSERT INTO stanza VALUES('Z602','9','角石、基石、磐石、<br/>活石、圣殿、召会、<br/>建造者、居所、圣所，<br/>你全都是，<br/>你是建造的一切！<br/>我们赞美你的所是，<br/>赞美你是何奇妙！<br/>但愿我们这些活石，<br/>因你所是被建造！<br/>','',56925,10460);
INSERT INTO stanza VALUES('Z603','1','神，我赞美你的计画，<br/>要使我们成为你家，<br/>给你安居，由你充满，<br/>你在子里好得彰显。<br/>','',56926,10461);
INSERT INTO stanza VALUES('Z603','2','我们虽是你所创造，<br/>有你形像，作你代表，<br/>不过仅是土造陋器，<br/>里面有灵，外面是体。<br/>','',56927,10462);
INSERT INTO stanza VALUES('Z603','3','惟有接受你作生命，<br/>才能有你精金性情；<br/>你与我们调和为一，<br/>我们与你成为一体。<br/>','',56928,10463);
INSERT INTO stanza VALUES('Z603','4','当你生命流通、滋润，<br/>浸透我的全心、全魂，<br/>我就变成珍珠、宝石，<br/>与你荣形一样一式。<br/>','',56929,10464);
INSERT INTO stanza VALUES('Z603','5','但是，恩主，我们深知，<br/>这些并非为供赏识，<br/>乃是全为建造、配搭，<br/>成为你的荣耀之家。<br/>','',56930,10465);
INSERT INTO stanza VALUES('Z603','6','主，我在此献上自己，<br/>求你接在建造手里，<br/>将我折服，将我联络，<br/>造成你能安居之所。<br/>','',56931,10466);
INSERT INTO stanza VALUES('Z603','7','天然生命、孤僻性格，<br/>求你全都为我攻破，<br/>不再单独，不再自善，<br/>与众圣徒调成一团。<br/>','',56932,10467);
INSERT INTO stanza VALUES('Z603','7','如此才能作你配偶，<br/>享受你爱所是所有，<br/>共同生活，互相安居，<br/>满足你心，得你称许。<br/>','',56933,10468);
INSERT INTO stanza VALUES('Z604','1','主，你不仅是陶人，<br/>更是荣耀建造主；<br/>不仅要把我陶甄，<br/>更是要把我建筑。<br/>我也不仅是土人，<br/>更是新造的活石；<br/>不仅为作你器皿，<br/>更是为作你宫室。<br/>不仅为作你器皿，<br/>更是为作你宫室。<br/>','',56934,10469);
INSERT INTO stanza VALUES('Z604','2','你虽用土造我们，<br/>却要我们能变质，<br/>有你生命的精金，<br/>变成珍珠与宝石。<br/>再经建造在一起，<br/>作你心爱的配偶，<br/>与你联合成一体，<br/>给你占有并享受。<br/>','',56935,10470);
INSERT INTO stanza VALUES('Z604','3','你心所爱并所要，<br/>非仅珍贵的材料，<br/>更要材料被建造，<br/>给你安居显荣耀。<br/>你这万有的基督，<br/>需要建造的召会，<br/>使你荣耀的丰富，<br/>显出完全的光辉。<br/>','',56936,10471);
INSERT INTO stanza VALUES('Z604','4','并非单独的属灵，<br/>就能博得你称羡；<br/>乃是团体的生命，<br/>才能成全你心愿。<br/>并非脱节的肢体，<br/>就能彰显你完全；<br/>乃是配搭的身体，<br/>才能成为你丰满。<br/>','',56937,10472);
INSERT INTO stanza VALUES('Z604','5','求不再容我单独，<br/>立即来把我建造；<br/>一切全照你蓝图，<br/>联络、结合，精而牢。<br/>属灵不再为自高，<br/>恩赐不再为自傲；<br/>全都为供你建造，<br/>全都为显你荣耀。<br/>','',56938,10473);
INSERT INTO stanza VALUES('Z605','1','求主向我吹气，<br/>使我沉灵复起！<br/>脱离忧悒，胜过死寂，<br/>进入复兴境地。<br/>','',56939,10474);
INSERT INTO stanza VALUES('Z605','2','求主向我吹气，<br/>使我从新得力！<br/>作工不乏，行路不疲，<br/>展腾如驾双翼。<br/>','',56940,10475);
INSERT INTO stanza VALUES('Z605','3','求主向我吹气，<br/>使我进入安息！<br/>灵有所赖，心有所倚，<br/>因你充满欢喜。<br/>','',56941,10476);
INSERT INTO stanza VALUES('Z605','4','求主向我吹气，<br/>使我充满了你！<br/>无论行动，或是起意，<br/>不再是我自己。<br/>','',56942,10477);
INSERT INTO stanza VALUES('Z605','5','求主向我吹气，<br/>使我活在身体！<br/>同众圣徒建造一起，<br/>永远不再独立。<br/>','',56943,10478);
INSERT INTO stanza VALUES('Z606','1','救我脱离自己、天然，<br/>主阿，我愿被建造，<br/>同众圣徒作你圣殿，<br/>为着充满你荣耀。<br/>救我脱离乖僻个性，<br/>脱离骄傲与单独；<br/>使我甘愿服你权柄，<br/>让你有家可居住。<br/>','',56944,10479);
INSERT INTO stanza VALUES('Z606','2','生命供应，活水流通，<br/>长进、变化又配搭；<br/>守住等次，尽我功用，<br/>成全别人，不践踏。<br/>自己所经，自己所见，<br/>所是、所有并所能，<br/>不再高估，不再稍偏，<br/>接受一切的平衡。<br/>','',56945,10480);
INSERT INTO stanza VALUES('Z606','3','持定元首，联络供应，<br/>享受基督的丰富；<br/>充满神的一切丰盛，<br/>因神增加得成熟，<br/>同尝基督莫测大爱，<br/>赏识基督的阔长；<br/>长大成人，不作婴孩，<br/>满有基督的身量。<br/>','',56946,10481);
INSERT INTO stanza VALUES('Z606','4','作神居所，作你身体，<br/>主阿，我愿被建造，<br/>成为你的团体大器，<br/>让你来显你荣耀。<br/>圣城景色、新妇荣美，<br/>今在此地就彰显，<br/>透出你的荣耀光辉，<br/>将你照耀在人间。<br/>','',56947,10482);
INSERT INTO stanza VALUES('Z607','1','主阿，发言！<br/>主阿，吹气！<br/>请看，枯骨遍满全地！<br/>埋在墓中，离散死寂，<br/>求主发言并吹气！<br/>','',56948,10483);
INSERT INTO stanza VALUES('Z607','2','主阿，发言，<br/>主阿，吹气！<br/>吹进枯骨，使之复起，<br/>出离坟墓，脱开死地，<br/>求主发言并吹气！<br/>','',56949,10484);
INSERT INTO stanza VALUES('Z607','3','主阿，发言，<br/>主阿，吹气！<br/>使你子民活到一起，<br/>成为大军，向敌攻击，<br/>求主发言并吹气！<br/>','',56950,10485);
INSERT INTO stanza VALUES('Z607','4','主阿，发言，<br/>主阿，吹气！<br/>使你子民合而为一，<br/>权柄、带领，不再互异，<br/>求主发言并吹气！<br/>','',56951,10486);
INSERT INTO stanza VALUES('Z607','5','主阿，发言，<br/>主阿，吹气！<br/>使你子民搭成一体，<br/>作你居所，使你安息，<br/>求主发言并吹气！<br/>','',56952,10487);
INSERT INTO stanza VALUES('Z607','6','向我发言，向我吹气！<br/>使我复苏，归回身体，<br/>不再死寂，不再孤僻，<br/>主阿，现在就吹气！<br/>','',56953,10488);
INSERT INTO stanza VALUES('Z607','7','向我发言，向我吹气！<br/>愿与众圣进攻仇敌，<br/>使你居所早得建立，<br/>主阿，现在就吹气！<br/>','',56954,10489);
INSERT INTO stanza VALUES('Z608','1','哦主，生命之气向我吹！<br/>我如枯骨，脱节离散，<br/>需要你来复苏并带回，<br/>使我活在身体里面。<br/>','',56955,10490);
INSERT INTO stanza VALUES('Z608','2','哦主，生命之气向我吹！<br/>我灵关闭，禁锢重重，<br/>需要你来释放并解围，<br/>使我调进身体灵中。<br/>','',56956,10491);
INSERT INTO stanza VALUES('Z608','3','哦主，生命之气向我吹！<br/>我灵沉闷，不能展腾，<br/>需要你来复兴并抚慰，<br/>使我得到身体供应。<br/>','',56957,10492);
INSERT INTO stanza VALUES('Z608','4','哦主，生命之气向我吹！<br/>我灵虚空，无法饱足，<br/>需要你来充实并施惠，<br/>使我享受身体丰富。<br/>','',56958,10493);
INSERT INTO stanza VALUES('Z608','5','哦主，生命之气向我吹！<br/>使我脱尽死枯、离散；<br/>死、散因素全给你摧毁，<br/>完全活在身体里面。<br/>','',56959,10494);
INSERT INTO stanza VALUES('Z609','1','主，我宝贵你的蓝图，<br/>就是你所造的帐幕；<br/>说出你是如何建造，<br/>如何显出你的荣耀。<br/>','',56960,10495);
INSERT INTO stanza VALUES('Z609','2','约柜乃是帐幕中心，<br/>帐幕是给约柜藏身；<br/>十条诫命放在约柜，<br/>约柜住在帐幕以内。<br/>','',56961,10496);
INSERT INTO stanza VALUES('Z609','3','约柜豫表神人基督，<br/>神、人相调如金包木；<br/>十诫指神具体表现，<br/>完全住在基督里面。<br/>','',56962,10497);
INSERT INTO stanza VALUES('Z609','4','基督也是召会中心，<br/>召会是给基督安身；<br/>神是住在基督里面，<br/>基督住在召会中间。<br/>','',56963,10498);
INSERT INTO stanza VALUES('Z609','5','帐幕乃是约柜扩大，<br/>金包木头，同样造法；<br/>召会也是基督扩充，<br/>神、人调和，完全相同。<br/>','',56964,10499);
INSERT INTO stanza VALUES('Z609','6','竖板相联，搭成帐幕，<br/>立在银座，基础稳固；<br/>精金包裹，上带金环，<br/>环内套闩，众板相联。<br/>','',56965,10500);
INSERT INTO stanza VALUES('Z609','7','召会也是圣徒集成，<br/>基督救赎上面立定；<br/>神性里面圣灵联系，<br/>彼此配搭，建造一起。<br/>','',56966,10501);
INSERT INTO stanza VALUES('Z609','7','帐幕上盖四层罩棚，<br/>豫表基督各种情形；<br/>这位基督显神荣耀，<br/>将神居所完全遮罩。<br/>','',56967,10502);
INSERT INTO stanza VALUES('Z609','9','在这基督遮护之下，<br/>圣徒才能彼此配搭；<br/>享受祂的一切功效，<br/>披祂戴祂，同被建造。<br/>','',56968,10503);
INSERT INTO stanza VALUES('Z609','10','十诫在柜，柜在帐幕，<br/>使神荣耀来此居住；<br/>神在主里，主在召会，<br/>你这蓝图何其宝贵！<br/>','',56969,10504);
INSERT INTO stanza VALUES('Z610','1','释放我灵！<br/>这是我心所要：<br/>使我能和众人灵里相调，<br/>不再单独追求，<br/>不再假冒，<br/>完全脱离自己，<br/>适合建造。<br/>','',56970,10505);
INSERT INTO stanza VALUES('Z610','2','释放我灵！<br/>这是我心所求：<br/>使我不再关闭，<br/>不再自囚；<br/>我在自己里面，<br/>又深又久，<br/>现在非脱自己，<br/>不能自由！<br/>','',56971,10506);
INSERT INTO stanza VALUES('Z610','3','释放我灵！<br/>这是我心所爱：<br/>从我自己里面完全出来，<br/>好叫你的圣灵通行无碍，<br/>你就丰满显出你的同在！<br/>','',56972,10507);
INSERT INTO stanza VALUES('Z610','4','释放我灵！<br/>这是我心所慕：<br/>使我脱离孤独，<br/>脱离干枯；<br/>已往自己追求，<br/>不过贫苦，<br/>今愿脱离自己，<br/>得享丰富。<br/>','',56973,10508);
INSERT INTO stanza VALUES('Z610','5','释放我灵！<br/>这是我心所愿：<br/>使我识破诡计，<br/>不再受骗；<br/>不再自己为牢，<br/>坐井观天，<br/>脱离狭小自己，<br/>进入无限！<br/>','',56974,10509);
INSERT INTO stanza VALUES('Z610','6','释放我灵！<br/>这是我心所望：<br/>使我脱离自己，<br/>不受捆绑；<br/>与众圣徒相调，<br/>刚强、明亮，<br/>享受你的一切，<br/>无量无疆！<br/>','',56975,10510);
INSERT INTO stanza VALUES('Z611','1','我今渴慕灵里的交通！<br/>渴慕灵里彼此相调，<br/>渴慕脱离单独的作风，<br/>渴慕灵里同被建造。<br/>','',56976,10511);
INSERT INTO stanza VALUES('Z611','2','我真渴慕灵里的交通！<br/>渴慕灵能向人敞开，<br/>渴慕脱离孤僻的自封，<br/>渴慕灵能同人敬拜。<br/>','',56977,10512);
INSERT INTO stanza VALUES('Z611','3','我实渴慕灵里的交通！<br/>渴慕灵能完全出来，<br/>渴慕脱离作怪的自崇，<br/>渴慕灵能胜过阻碍。<br/>','',56978,10513);
INSERT INTO stanza VALUES('Z611','4','我甚渴慕灵里的交通！<br/>渴慕灵能同人祷告，<br/>渴慕脱离虚饰的两层，<br/>渴慕灵能真实相交。<br/>','',56979,10514);
INSERT INTO stanza VALUES('Z611','5','我极渴慕灵里的交通！<br/>渴慕交通平衡权柄，<br/>渴慕脱离事工的偏重，<br/>渴慕交通配合事奉。<br/>','',56980,10515);
INSERT INTO stanza VALUES('Z611','6','主阿，成全我们这心愿！<br/>激动圣徒响应交通，<br/>使你建造快快的实现，<br/>你的计划早日成功！<br/>','',56981,10516);
INSERT INTO stanza VALUES('Z612','1','何等福气，何等权利，<br/>我是君尊的祭司！<br/>由神所选，为神所立，<br/>承担尊荣的圣职。<br/>','',56982,10517);
INSERT INTO stanza VALUES('Z612','chorus','祭司职分何等尊荣，<br/>召会建造所倚恃；<br/>灵里祷告，神前事奉，<br/>我愿如此供圣职。<br/>','',56983,10518);
INSERT INTO stanza VALUES('Z612','2','我若守住君尊身分，<br/>权柄、等次不颠倒，<br/>并且肯尽祭司职分，<br/>召会才能被建造。<br/>','',56984,10519);
INSERT INTO stanza VALUES('Z612','3','召会乃是祭司团体，<br/>祭司职分不可少；<br/>且须编成祭司体系，<br/>才是真正被建造。<br/>','',56985,10520);
INSERT INTO stanza VALUES('Z612','4','因着召会堕落荒凉，<br/>祭司职分被忽视；<br/>因着圣徒灵不刚强，<br/>话语职事独得势。<br/>','',56986,10521);
INSERT INTO stanza VALUES('Z612','5','人多偏重先知讲道，<br/>单靠话语的供应；<br/>很少倚重祭司祷告，<br/>在神面前运用灵。<br/>','',56987,10522);
INSERT INTO stanza VALUES('Z612','6','主阿，给我厉害平衡，<br/>倚重祷告如讲道；<br/>对人常用祷告带领，<br/>配同话语的教导。<br/>','',56988,10523);
INSERT INTO stanza VALUES('Z612','7','惟有如此事奉、祷告，<br/>叫人灵里得相调，<br/>看重祷告犹如听道，<br/>召会才能被建造。<br/>','',56989,10524);
INSERT INTO stanza VALUES('Z613','1','建造召会的活石，<br/>乃是圣洁的祭司；<br/>若要活石被建造，<br/>必须祭司能祷告。<br/>','',56990,10525);
INSERT INTO stanza VALUES('Z613','chorus','必须常进至圣所，<br/>用灵摸神施恩座，<br/>祷告让神能通过，<br/>才有建造的工作。<br/>','',56991,10526);
INSERT INTO stanza VALUES('Z613','2','圣徒必须作祭司，<br/>才能真正作活石；<br/>须有祭司的事奉，<br/>才有活石的功能。<br/>','',56992,10527);
INSERT INTO stanza VALUES('Z613','3','旧约祭司与帐幕，<br/>总是相调在一处；<br/>祭司调在帐幕里，<br/>帐幕、祭司成一体。<br/>','',56993,10528);
INSERT INTO stanza VALUES('Z613','4','新约祭司的团体，<br/>与神灵宫原是一；<br/>灵宫建造的实际，<br/>就是祭司的体系。<br/>','',56994,10529);
INSERT INTO stanza VALUES('Z613','5','召会建造的本质，<br/>就是祭司的圣职；<br/>祭司尽职常事奉，<br/>召会建造就完成。<br/>','',56995,10530);
INSERT INTO stanza VALUES('Z613','6','祭司神前的事奉，<br/>使人进入神交通；<br/>在神这一交通里，<br/>圣徒建造在一起。<br/>','',56996,10531);
INSERT INTO stanza VALUES('Z613','7','惟有如此被建造，<br/>灵里相调同祷告，<br/>成为祭司的体系，<br/>才能向神献灵祭。<br/>','',56997,10532);
INSERT INTO stanza VALUES('Z613','7','主阿，求你施恩惠，<br/>祭司圣职我宝贵！<br/>用灵事奉，多祷告，<br/>好叫召会被建造。<br/>','',56998,10533);
INSERT INTO stanza VALUES('Z614','1','灵能交流，恩主，<br/>灵能交流！<br/>我今切求，恩主，<br/>灵能交流！<br/>甚愿一反已往，<br/>推倒铁壁铜墙，<br/>灵能交流通畅，<br/>灵能交流！<br/>','',56999,10534);
INSERT INTO stanza VALUES('Z614','2','灵能交流，恩主，<br/>灵能交流！<br/>我今恳求，恩主，<br/>灵能交流！<br/>不再自满自负，<br/>不再作茧自缚，<br/>灵能交流无阻，<br/>灵能交流！<br/>','',57000,10535);
INSERT INTO stanza VALUES('Z614','3','灵能交流，恩主，<br/>灵能交流！<br/>我今祈求，恩主，<br/>灵能交流！<br/>不再不凡自命，<br/>不再自觉聪明，<br/>灵能交流不停，<br/>灵能交流！<br/>','',57001,10536);
INSERT INTO stanza VALUES('Z614','4','灵能交流，恩主，<br/>灵能交流！<br/>我今寻求，恩主，<br/>灵能交流！<br/>不再自藏自隐，<br/>不再独善己身，<br/>灵能交流日深，<br/>灵能交流！<br/>','',57002,10537);
INSERT INTO stanza VALUES('Z614','5','灵能交流，恩主，<br/>灵能交流！<br/>我今要求，恩主，<br/>灵能交流！<br/>打倒自持架格，<br/>走下作人宝座，<br/>流出活水江河，<br/>灵能交流！<br/>','',57003,10538);
INSERT INTO stanza VALUES('Z614','6','灵能交流，恩主，<br/>灵能交流！<br/>允我所求，恩主，<br/>灵能交流！<br/>切愿能被建造，<br/>不但与你相交，<br/>且能与人相调，<br/>灵能交流！<br/>','',57004,10539);
INSERT INTO stanza VALUES('Z615','1','主，你居所何等可爱！<br/>我心渴慕你的院宇！<br/>切望得到你的同在，<br/>我的心肠向你呼吁。<br/>','',57005,10540);
INSERT INTO stanza VALUES('Z615','2','在你祭坛所在之处，<br/>并你香坛所在之所，<br/>麻雀找着可居房屋，<br/>燕子找着菢雏之窝。<br/>','',57006,10541);
INSERT INTO stanza VALUES('Z615','3','微弱虽如麻雀、燕子，<br/>住在你殿，便为有福！<br/>凭着祭坛赎罪价值，<br/>享受香坛所有好处。<br/>','',57007,10542);
INSERT INTO stanza VALUES('Z615','4','因着靠你而有力量，<br/>前途险阻毫不思顾，<br/>锡安大道心中想往，<br/>如此之人，便为有福。<br/>','',57008,10543);
INSERT INTO stanza VALUES('Z615','5','虽经巴迦，流泪之谷，<br/>亦使变成泉源之地，<br/>并且盖满秋雨之福，<br/>成为路中福分之一。<br/>','',57009,10544);
INSERT INTO stanza VALUES('Z615','6','他们行走，力上加力，<br/>要到锡安朝见主神；<br/>如此寻求你的自己，<br/>也需你来垂顾赐恩。<br/>','',57010,10545);
INSERT INTO stanza VALUES('Z615','7','在你院宇一日之留，<br/>胜住别处千日之久，<br/>宁在你殿看门守候，<br/>不在恶人帐棚住留。<br/>','',57011,10546);
INSERT INTO stanza VALUES('Z615','7','你是日头，你是盾牌，<br/>你要赐下恩惠、荣耀，<br/>以你自己和你同在，<br/>满足我的一切需要。<br/>','',57012,10547);
INSERT INTO stanza VALUES('Z615','9','你未留下一样好处，<br/>不给行动正直的人；<br/>倚靠你的，便为有福，<br/>必得恩惠、荣耀无尽。<br/>','',57013,10548);
INSERT INTO stanza VALUES('Z616','1','主阿，我爱你的居所，<br/>就是你的召会！<br/>她是你心所喜所乐，<br/>也是我心所归。<br/>','',57014,10549);
INSERT INTO stanza VALUES('Z616','2','你曾为她舍了自己，<br/>为要叫她归你；<br/>我也为她献上身体，<br/>成全你的心意。<br/>','',57015,10550);
INSERT INTO stanza VALUES('Z616','3','为她你作我的生命，<br/>叫她作我生活；<br/>为她我愿脱去个性，<br/>让她作你寄托。<br/>','',57016,10551);
INSERT INTO stanza VALUES('Z616','4','她是你的心爱配偶，<br/>也是你的身体；<br/>她是我的心情所投，<br/>也是我的凭倚。<br/>','',57017,10552);
INSERT INTO stanza VALUES('Z616','5','在她你是我所享受，<br/>成为我所见证；<br/>在她我给你所占有，<br/>满足你的心情。<br/>','',57018,10553);
INSERT INTO stanza VALUES('Z616','6','主阿，我爱你的居所，<br/>就是你的召会！<br/>我愿永在其中生活，<br/>不再别有所归。<br/>','',57019,10554);
INSERT INTO stanza VALUES('Z617','1','生命活物出于基督，<br/>同一生命，无法单独；<br/>各方接受十架对付，<br/>就能活出团体基督。<br/>','',57020,10555);
INSERT INTO stanza VALUES('Z617','chorus','互相联络，彼此配搭，<br/>作主荣耀寄托；<br/>共同行动，同一步伐，<br/>带进神的宝座。<br/>','',57021,10556);
INSERT INTO stanza VALUES('Z617','2','生活行动靠神恩力，<br/>不再自恃，不再自倚；<br/>以主夸口，以神为蔽，<br/>彰显主神而非自己。<br/>','',57022,10557);
INSERT INTO stanza VALUES('Z617','3','单纯无杂，正直不曲，<br/>灵中柔和，心里谦虚；<br/>随灵而行，无论何去，<br/>不从自己所好所欲。<br/>','',57023,10558);
INSERT INTO stanza VALUES('Z617','4','结得坚固，联得合式，<br/>彼此成全，各尽各职；<br/>功用虽异，行动一致，<br/>成全神的荣耀启示。<br/>','',57024,10559);
INSERT INTO stanza VALUES('Z617','5','如此配搭，圣火焚烧，<br/>污秽、杂质全都烧掉；<br/>圣火且成圣别光照，<br/>一举一动亮光闪耀。<br/>','',57025,10560);
INSERT INTO stanza VALUES('Z617','6','神的大轮随此而转，<br/>活物得有清明之天；<br/>神的宝座借此掌权，<br/>主的荣形在此彰显。<br/>','',57026,10561);
INSERT INTO stanza VALUES('Z618','1','圣徒在基督里，<br/>互相作肢体，<br/>成为一个身体，<br/>配搭在一起。<br/>','',57027,10562);
INSERT INTO stanza VALUES('Z618','2','恩赐虽有不同，<br/>圣灵是一位；<br/>职事虽有多种，<br/>主也是一位。<br/>','',57028,10563);
INSERT INTO stanza VALUES('Z618','3','谁也不能无谁，<br/>不可轻或重；<br/>各有各的地位，<br/>各有各功用。<br/>','',57029,10564);
INSERT INTO stanza VALUES('Z618','4','蒙恩有多有少，<br/>恩赐分大小；<br/>看得合乎中道，<br/>谦卑不自高。<br/>','',57030,10565);
INSERT INTO stanza VALUES('Z618','5','各尽各的职事，<br/>各显各功用；<br/>个个都不松弛，<br/>个个都尽忠。<br/>','',57031,10566);
INSERT INTO stanza VALUES('Z618','6','互相供应联系，<br/>彼此多包容；<br/>毫无不谐嫌隙，<br/>凡事主为重。<br/>','',57032,10567);
INSERT INTO stanza VALUES('Z618','7','基督乃是元首，<br/>召会是身体；<br/>圣灵又是膏油，<br/>我们该是一。<br/>','',57033,10568);
INSERT INTO stanza VALUES('Z619','1','出于神性的活物，<br/>彰显荣耀的基督；<br/>联络配搭成一体，<br/>完成神圣的旨意；<br/>随从圣灵而行动，<br/>神的举动就随同。<br/>','',57034,10569);
INSERT INTO stanza VALUES('Z619','chorus','随着活物的行踪，<br/>神的大轮在转动，<br/>动得可畏高而明，<br/>显出恩主的荣形，<br/>神圣的计划借此完成。<br/>','',57035,10570);
INSERT INTO stanza VALUES('Z619','2','圣别烈火在焚烧，<br/>不洁、不圣全烧掉；<br/>圣火烧成圣别光，<br/>上下四方照明亮；<br/>一切行动在光中，<br/>神的举动就随同。<br/>','',57036,10571);
INSERT INTO stanza VALUES('Z619','3','随从圣灵光中行，<br/>天就清明如水晶；<br/>能从无亏的良心，<br/>发出见证的声音；<br/>如此发声并静听，<br/>神的举动得推行。<br/>','',57037,10572);
INSERT INTO stanza VALUES('Z619','4','在此才有神居所，<br/>在此也有神宝座；<br/>神的权柄得施展，<br/>神的荣耀得彰显；<br/>主在宝座像人形，<br/>周围光辉如圣城。<br/>','',57038,10573);
INSERT INTO stanza VALUES('Z620','1','圣灵的大云，<br/>圣别的烈火，<br/>显出光耀精金神性；<br/>借此，<br/>受造者得生而活着，<br/>神的生命显于人形。<br/>','',57039,10574);
INSERT INTO stanza VALUES('Z620','2','生活如常人，<br/>雄壮似猛狮，<br/>劳役如牛，超脱似鹰；<br/>如此就活出基督的样式，<br/>各方显出祂的荣形。<br/>','',57040,10575);
INSERT INTO stanza VALUES('Z620','3','脚步无弯曲，<br/>行动有分别，<br/>新鲜、活泼、<br/>光明、灿烂；<br/>经过神锻炼，<br/>受过神纯洁，<br/>成为人的亮光、审判。<br/>','',57041,10576);
INSERT INTO stanza VALUES('Z620','4','靠神能腾空，<br/>不为地拘留，<br/>作事仍具人形、人迹；<br/>以神为遮蔽，<br/>以主为夸口，<br/>彰显主神，而非自己。<br/>','',57042,10577);
INSERT INTO stanza VALUES('Z620','5','靠着主恩力，<br/>接联而配搭，<br/>各尽其职，不需转调。<br/>焚烧如火炭，<br/>照明似火把，<br/>一举一动亮光闪耀。<br/>','',57043,10578);
INSERT INTO stanza VALUES('Z620','6','随从灵而行，<br/>就有神举动，<br/>动得可畏，眼光丰盛；<br/>动中有主动，<br/>显出主圣容，行动一致，<br/>动中有灵。<br/>','',57044,10579);
INSERT INTO stanza VALUES('Z620','7','天明如水晶，<br/>良心无搅扰，<br/>能以发声，也能静听；<br/>发声由配搭，<br/>使神得发表，<br/>也像军队将敌克征。<br/>','',57045,10580);
INSERT INTO stanza VALUES('Z620','7','天上的宝座，<br/>满呈天景色，<br/>主在其上显如人形：<br/>光耀如精金，<br/>圣别似烈火，<br/>周围虹辉状如圣城。<br/>','',57046,10581);
INSERT INTO stanza VALUES('Z621','1','福哉以爱联系，<br/>圣徒心心相契；<br/>彼此交通一情一意，<br/>真如在天无异。<br/>','',57047,10582);
INSERT INTO stanza VALUES('Z621','2','在父恩座之前，<br/>同心寻求眷怜；<br/>有望同盼，有苦同难，<br/>同忧、同乐、同安。<br/>','',57048,10583);
INSERT INTO stanza VALUES('Z621','3','软弱彼此体谅，<br/>重担互相担当；<br/>人心伤，众人泪淌，<br/>充满同情心肠。<br/>','',57049,10584);
INSERT INTO stanza VALUES('Z621','4','每逢彼此分离，<br/>总是难免依依，<br/>但身虽离，灵仍一起，<br/>且有再会之期。<br/>','',57050,10585);
INSERT INTO stanza VALUES('Z621','5','盼望那日快显，<br/>再无离别辛酸；<br/>相爱更亲，相交更甜，<br/>同乐直到永远。<br/>','',57051,10586);
INSERT INTO stanza VALUES('Z622','1','弟兄和睦同居，<br/>何等美善：<br/>像油从亚伦头，<br/>流到衣衫；<br/>又像露从黑门，<br/>降在锡安；<br/>在此有生命福，<br/>直到永远！<br/>','',57052,10587);
INSERT INTO stanza VALUES('Z622','2','心存欢喜诚实，<br/>来赴爱筵；<br/>借此饱尝主恩，<br/>满心感赞！<br/>弟兄彼此交通，<br/>何等甘甜；<br/>盼望那日快到，<br/>不再离散。<br/>','',57053,10588);
INSERT INTO stanza VALUES('Z623','1','我们呼吸天上空气，<br/>香味从天而来；<br/>但愿每魂脱离肉体，<br/>每灵都充满爱。<br/>','',57054,10589);
INSERT INTO stanza VALUES('Z623','2','主，使我们心心相联，<br/>满有圣洁情意，<br/>不至有日彼此改变，<br/>不爱你或你的。<br/>','',57055,10590);
INSERT INTO stanza VALUES('Z623','3','只受你的十架指引，<br/>服你所有旨意，<br/>能以彼此更为亲近，<br/>能以更亲近你。<br/>','',57056,10591);
INSERT INTO stanza VALUES('Z624','1','每逢聚集带来基督，<br/>将祂所赐有余丰富，<br/>同来献上作神食物，<br/>如此展览基督。<br/>','',57057,10592);
INSERT INTO stanza VALUES('Z624','chorus','前来展览基督，<br/>前来展览基督；<br/>共同带来祂的丰富，<br/>前来展览基督。<br/>','',57058,10593);
INSERT INTO stanza VALUES('Z624','2','凭祂生活，靠祂争战，<br/>在祂身上经营无间；<br/>借祂丰富彼此结联，<br/>为要展览基督。<br/>','',57059,10594);
INSERT INTO stanza VALUES('Z624','3','凡我所是、所行、所历，<br/>都是基督作我实际，<br/>好使我们每逢聚集，<br/>都能展览基督。<br/>','',57060,10595);
INSERT INTO stanza VALUES('Z624','4','聚会为神带来基督，<br/>彼此享受祂的丰富，<br/>且得与神同享基督，<br/>如此展览基督。<br/>','',57061,10596);
INSERT INTO stanza VALUES('Z624','5','复活基督作神馨香，<br/>升天基督向神举上，<br/>使神满足供神欣赏，<br/>如此展览基督。<br/>','',57062,10597);
INSERT INTO stanza VALUES('Z624','6','聚会中心、聚会实际、<br/>所有服事、所有空气，<br/>除此之外别无目的，<br/>全为展览基督。<br/>','',57063,10598);
INSERT INTO stanza VALUES('Z624','7','所有见证、所有祷告、<br/>所有灵中彼此相交、<br/>恩赐运用、一切教导，<br/>都为展览基督。<br/>','',57064,10599);
INSERT INTO stanza VALUES('Z624','7','为使父神得荣称许，<br/>为使基督得到高举，<br/>并使聚会应付所需，<br/>必须展览基督。<br/>','',57065,10600);
INSERT INTO stanza VALUES('Z625','1','主阿，我们聚集你前，<br/>求你赐给更深恩典，<br/>使我得着更丰生命，<br/>使我能作更美见证；<br/>恩主，这是我灵所求，<br/>我心所慕愿你成就。<br/>','',57066,10601);
INSERT INTO stanza VALUES('Z625','2','在此多人灵里干燥，<br/>多人心里需要光照；<br/>愿你赐下恩膏滋润，<br/>赐下恩光照亮人心，<br/>使人复兴，爱你更深，<br/>使人自审，追求上进。<br/>','',57067,10602);
INSERT INTO stanza VALUES('Z625','3','愿你使我里面刚强，<br/>使我脱离外面捆绑；<br/>使我灵里更有能力，<br/>使我心里更脱自己；<br/>使你生命在我成形，<br/>使你旨意借我通行。<br/>','',57068,10603);
INSERT INTO stanza VALUES('Z625','4','亲爱的主，还要求你，<br/>赐下当初五旬能力，<br/>使人痛悔，觉得扎心，<br/>使人回转，寻求你恩：<br/>病者得医，暗者见光，<br/>受缚囚奴得着释放。<br/>','',57069,10604);
INSERT INTO stanza VALUES('Z626','1','哦神，凭灵并凭实际，<br/>我们在此敬拜；<br/>照着你子基督所说，<br/>你前我们今来。<br/>','',57070,10605);
INSERT INTO stanza VALUES('Z626','2','感谢父神，你乃是灵，<br/>对我何亲何近！<br/>使我凭灵与你接触，<br/>并凭实际敬尊。<br/>','',57071,10606);
INSERT INTO stanza VALUES('Z626','3','你曾为我创造一灵，<br/>为使我能拜你；<br/>不需外面挣扎事奉，<br/>只需回到灵里。<br/>','',57072,10607);
INSERT INTO stanza VALUES('Z626','4','你已用灵重生我灵，<br/>且作我的生命，<br/>还在将我心思更新，<br/>使我真能事奉。<br/>','',57073,10608);
INSERT INTO stanza VALUES('Z626','5','我们照着里面感觉，<br/>在此向你敬拜；<br/>借着你灵涂抹、运行，<br/>将你表明出来。<br/>','',57074,10609);
INSERT INTO stanza VALUES('Z626','6','凭着实际事奉敬拜，<br/>不再凭着影像；<br/>凭着基督，惟一实际，<br/>我们敬拜颂扬。<br/>','',57075,10610);
INSERT INTO stanza VALUES('Z626','7','我们向你献上基督，<br/>就是我所经历；<br/>与你同尝祂的甘甜，<br/>欣赏祂的美丽。<br/>','',57076,10611);
INSERT INTO stanza VALUES('Z626','7','哦神，凭灵并凭实际，<br/>我们在此聚集，<br/>围绕你的施恩宝座，<br/>敬拜、感赞不已。<br/>','',57077,10612);
INSERT INTO stanza VALUES('Z627','1','在日常生活或在聚会中，<br/>基督是中心，<br/>基督是内容；<br/>并非为仪式，<br/>也非为道理，<br/>纯是为基督，<br/>我们相聚集。<br/>','',57078,10613);
INSERT INTO stanza VALUES('Z627','2','基督是道路，<br/>基督是亮光，<br/>凭祂而行动，<br/>由祂来照亮；<br/>基督是活水，<br/>基督是灵粮，<br/>喝祂并吃祂，<br/>从祂得喂养。<br/>','',57079,10614);
INSERT INTO stanza VALUES('Z627','3','基督是真理，<br/>我们所见证，<br/>基督是生命，<br/>我们所供应，<br/>基督是恩主，<br/>我们所称誉，<br/>基督是元首，<br/>我们所高举。<br/>','',57080,10615);
INSERT INTO stanza VALUES('Z627','4','对神或对人，<br/>基督是一切，<br/>神、人的需要<br/>全由祂解决；<br/>祂是召会的实际与内容，<br/>生命与人数都借祂而增。<br/>','',57081,10616);
INSERT INTO stanza VALUES('Z627','5','所献上一切诗歌和祷告，<br/>都要叫基督借灵得发表；<br/>所有灵中的交通和事奉，<br/>都该是基督彰显的运行。<br/>','',57082,10617);
INSERT INTO stanza VALUES('Z627','6','奉祂名聚集，<br/>随祂灵活动，<br/>借着祂恩膏祷告并赞颂；<br/>不是动头脑，<br/>仪式得成全，<br/>乃是运用灵，<br/>使祂得彰显。<br/>','',57083,10618);
INSERT INTO stanza VALUES('Z627','7','一切全忘掉，<br/>只忠于基督，<br/>凡事应用祂，<br/>一直到成熟；<br/>因祂将万事都当作损失，<br/>让祂作一切，<br/>一直到永世。<br/>','',57084,10619);
INSERT INTO stanza VALUES('Z628','1','灵要操练、运用，<br/>头脑要拒绝，<br/>每逢我们聚集，<br/>以此为秘诀。<br/>','',57085,10620);
INSERT INTO stanza VALUES('Z628','2','灵要操练、运用，<br/>仪式全弃绝；<br/>彼此交通、分享，<br/>基督作一切。<br/>','',57086,10621);
INSERT INTO stanza VALUES('Z628','3','灵要操练、运用，<br/>情感要抛弃；<br/>彼此事奉、供应，<br/>基督是实际。<br/>','',57087,10622);
INSERT INTO stanza VALUES('Z628','4','灵要操练、运用，<br/>魂要全舍弃；<br/>彼此相助、联络，<br/>以主为凭倚。<br/>','',57088,10623);
INSERT INTO stanza VALUES('Z628','5','灵中得着释放，<br/>脱开了自义；<br/>脱开自觉、自责，<br/>不再理自己。<br/>','',57089,10624);
INSERT INTO stanza VALUES('Z628','6','灵中得着释放，<br/>脱开了己意；<br/>自爱、自骄、自荣，<br/>全都被贬抑。<br/>','',57090,10625);
INSERT INTO stanza VALUES('Z628','7','灵要操练、运用，<br/>取用主得胜；<br/>借着洗罪宝血，<br/>并主大能名。<br/>','',57091,10626);
INSERT INTO stanza VALUES('Z628','7','灵要操练、运用，<br/>如此摸着主；<br/>用灵接触主话，<br/>饱尝主丰富。<br/>','',57092,10627);
INSERT INTO stanza VALUES('Z628','9','乃是借着用灵，<br/>基督被见证；<br/>乃是借着用灵，<br/>人们得供应。<br/>','',57093,10628);
INSERT INTO stanza VALUES('Z628','10','灵要操练、运用，<br/>这是我需要；<br/>灵要操练、运用，<br/>如此主引导。<br/>','',57094,10629);
INSERT INTO stanza VALUES('Z629','1','既是基督的肢体，<br/>就当彰显基督；<br/>各都学习尽功用，<br/>显出祂的丰富。<br/>不该作一旁观者，<br/>该像肢体行动，<br/>不带死亡或损伤，<br/>只带有益交通。<br/>','',57095,10630);
INSERT INTO stanza VALUES('Z629','2','众人乃是成一队，<br/>永不单独行动，<br/>乃是彼此相配搭，<br/>互相倚赖听从；<br/>不照我们所拣选，<br/>乃随生命水流，<br/>永不带进分离来，<br/>只供圣灵所授。<br/>','',57096,10631);
INSERT INTO stanza VALUES('Z629','3','全都集中在基督，<br/>别无任何中心，<br/>共同交通于基督，<br/>分享祂的宏恩。<br/>祂是元首并内容，<br/>我们是祂丰满；<br/>会中任何的活动，<br/>都当将祂彰显。<br/>','',57097,10632);
INSERT INTO stanza VALUES('Z629','4','爱中一同被建造，<br/>无人随意批评；<br/>彼此成全互担就，<br/>都愿照此而行。<br/>全蒙拯救脱自己，<br/>拒绝天然生命；<br/>借恩灵中受过训，<br/>活出身体事奉。<br/>','',57098,10633);
INSERT INTO stanza VALUES('Z630','1','为着你同在并你活的话，<br/>离去前，<br/>赞美还要向你发；<br/>我们已为你宝贵所吸引，<br/>你有力信息已抓住我心。<br/>','',57099,10634);
INSERT INTO stanza VALUES('Z630','2','你话对于我，<br/>是灵、是生命，<br/>使我得喂养，<br/>时将我供应；<br/>要将我变化，<br/>模成你形像，<br/>直到我成熟，<br/>满有你身量。<br/>','',57100,10635);
INSERT INTO stanza VALUES('Z630','3','求将你自己，<br/>更多供应我，<br/>使我在灵里行动并生活，<br/>并将我保守在你交通里，<br/>直到借你恩，<br/>我们再聚集。<br/>','',57101,10636);
INSERT INTO stanza VALUES('Z631','1','恩主，<br/>在我们尚未散会前，<br/>为着你荣耀、<br/>丰厚的显现，<br/>并为你所赐新鲜的恩典，<br/>我们从心中再向你感赞。<br/>','',57102,10637);
INSERT INTO stanza VALUES('Z631','2','在你的恩中，<br/>聚会虽将完，<br/>但你的同在永远不间断；<br/>那在你灵里维持的能力，<br/>因爱你必要不停的供给。<br/>','',57103,10638);
INSERT INTO stanza VALUES('Z631','3','愿你的同在与我们同去，<br/>分担我心中一切的罣虑，<br/>使我能时刻享受你自己，<br/>直到我有分再一次聚集。<br/>','',57104,10639);
INSERT INTO stanza VALUES('Z632','1','兴起，兴起，为基督，<br/>兴起，十架精兵；<br/>举起主旗扬威武，<br/>永远将牠高撑。<br/>主必率领祂大军，<br/>得胜而又得胜，<br/>直到仇敌全灭尽，<br/>人尊主名为圣。<br/>','',57105,10640);
INSERT INTO stanza VALUES('Z632','2','兴起，兴起，为基督，<br/>兴起，听主号令；<br/>走上疆场齐步武，<br/>靠主得胜大名。<br/>仇敌虽多，又凶险，<br/>也必向其进攻；<br/>越险，越攻，越勇敢，<br/>攻到仇敌消踪。<br/>','',57106,10641);
INSERT INTO stanza VALUES('Z632','3','兴起，兴起，为基督，<br/>兴起，靠主大力；<br/>莫靠自己而贻误，<br/>莫用血气兵器。<br/>穿上属灵的军装，<br/>祷告随时多方；<br/>无论何处需抵挡，<br/>都能随灵前往。<br/>','',57107,10642);
INSERT INTO stanza VALUES('Z632','4','兴起，兴起，为基督，<br/>战争必不会长；<br/>今日杀声虽高呼，<br/>明日凯歌必唱。<br/>凡是靠主得胜者，<br/>必得荣耀冠冕，<br/>必与基督同快乐，<br/>同王直到永远。<br/>','',57108,10643);
INSERT INTO stanza VALUES('Z633','1','前进！基督精兵，<br/>前进！如出征；<br/>十架旌旗高撑，<br/>随主向前行。<br/>前进！走上疆场，<br/>进攻诸幽冥；<br/>必将仇敌扫荡，<br/>若听主号令。<br/>','',57109,10644);
INSERT INTO stanza VALUES('Z633','chorus','前进！基督精兵，<br/>前进！如出征；<br/>十架旌旗高撑，<br/>随主向前行。<br/>','',57110,10645);
INSERT INTO stanza VALUES('Z633','2','一闻耶稣大名，<br/>魔军必窜逃；<br/>所以基督精兵，<br/>向前将敌剿。<br/>若肯高声赞颂，<br/>阴间必动摇；<br/>所以亲爱弟兄，<br/>赞颂声要高。<br/>','',57111,10646);
INSERT INTO stanza VALUES('Z633','3','基督召会出征，<br/>势如大军队：<br/>古圣在前先行，<br/>我们在后随；<br/>并非分成两起，<br/>古圣与我们；<br/>乃是一灵、一体、<br/>一望并一信。<br/>','',57112,10647);
INSERT INTO stanza VALUES('Z633','4','王位终必摧毁，<br/>邦国兴而衰；<br/>惟有基督召会，<br/>永远必存在。<br/>阴间权势虽凶，<br/>不能胜召会；<br/>召会随主进攻，<br/>必能毁魔鬼。<br/>','',57113,10648);
INSERT INTO stanza VALUES('Z633','5','前进！蒙恩圣徒，<br/>响应主召会；<br/>跟随召会步武，<br/>必奏凯歌归。<br/>荣耀、尊贵、颂扬，<br/>归给得胜王；<br/>圣徒天使合唱，<br/>颂扬永无疆。<br/>','',57114,10649);
INSERT INTO stanza VALUES('Z634','1','冲过！战士哪，冲过！<br/>前线正在开火；<br/>但各各他已得胜，<br/>请你常唱此歌。<br/>黑暗权势应当退，<br/>撒但阴府已危！<br/>万军之主的元帅，<br/>快要奏凯归回。<br/>','',57115,10650);
INSERT INTO stanza VALUES('Z634','2','『冲过！战士哪，冲过！<br/>仰起你头看我；<br/>你若为我打胜仗，<br/>必得登我宝座。』<br/>这是属灵的交战，<br/>不在属世地场；<br/>主已知道仇敌迫，<br/>前后四围布满！<br/>','',57116,10651);
INSERT INTO stanza VALUES('Z634','3','『冲过！战士哪，冲过！<br/>你要登我宝座；<br/>使我复活的能力，<br/>会使你灵超脱。<br/>借我你要得权能，<br/>借我你要得胜，<br/>借我你要唱凯歌，<br/>借我你要高升。』<br/>','',57117,10652);
INSERT INTO stanza VALUES('Z634','4','『冲过！战士哪，冲过！<br/>你要登我宝座；<br/>我已为你留一席，<br/>你要欢喜快乐。』<br/>我们与祂同复活，<br/>同升天上坐着，<br/>远离战场的喊声，<br/>远离绑人罪恶。<br/>','',57118,10653);
INSERT INTO stanza VALUES('Z634','5','冲过！战士哪，冲过！<br/>你要登主宝座；<br/>主从灰尘拣选你，<br/>要你同祂得国。<br/>你的将来乃光明，<br/>不是黑暗灰心，<br/>永与耶稣在一起，<br/>永得祂的爱情。<br/>','',57119,10654);
INSERT INTO stanza VALUES('Z634','6','冲过！欢呼着冲过！<br/>前面就是宝座！<br/>你从郇山的高峰，<br/>可唱得胜新歌。<br/>被杀羔羊已得胜！<br/>登基羔羊已胜！<br/>我们欢呼赞美祂，<br/>因祂必定得胜。<br/>','',57120,10655);
INSERT INTO stanza VALUES('Z635','1','当你苦受撒但试探，<br/>四围无处不黑暗，<br/>邪灵劝你稍为自循，<br/>将来冠冕听命运；<br/>','',57121,10656);
INSERT INTO stanza VALUES('Z635','chorus','战士哪，你就当站住！<br/>思念你的得胜主！<br/>耶稣已经胜过撒但，<br/>故当奋勇去争战。<br/>','',57122,10657);
INSERT INTO stanza VALUES('Z635','2','当你同伴逡巡、摇动，<br/>向你怀贰和敌通；<br/>你的乡邻讥你、欺你，<br/>竟然同敌联一气；<br/>','',57123,10658);
INSERT INTO stanza VALUES('Z635','3','当这世界用牠福乐，<br/>暗中为你张网罗，<br/>要借虚荣、世俗、人情，<br/>使你狂放失信心；<br/>','',57124,10659);
INSERT INTO stanza VALUES('Z635','4','当你困于烦琐事务，<br/>虽然劳碌无所补，<br/>损失、病痛，使你艰苦，<br/>身灵疲惫难担负；<br/>','',57125,10660);
INSERT INTO stanza VALUES('Z635','5','不久，争战就要过去，<br/>撒但、邪灵要受拘；<br/>不久，召会要听号声，<br/>要得荣耀，要得胜。<br/>','',57126,10661);
INSERT INTO stanza VALUES('Z635','chorus','战士哪，故你当站住！<br/>思念你的得胜主！<br/>耶稣已经胜过撒但，<br/>故当奋勇去争战。<br/>','',57127,10662);
INSERT INTO stanza VALUES('Z635','6','此后，我王就要凯旋，<br/>在这世界掌王权；<br/>此后，万国都要归顺，<br/>颂扬耶稣并敬尊。<br/>','',57128,10663);
INSERT INTO stanza VALUES('Z636','1','邪恶之日要站住，<br/>人说甚么不必顾，<br/>泥土之脸何必睹，<br/>站住，主精兵。<br/>','',57129,10664);
INSERT INTO stanza VALUES('Z636','2','站住因有神的话，<br/>站住，甘愿出代价，<br/>追随众圣的步法，<br/>站住，主精兵。<br/>','',57130,10665);
INSERT INTO stanza VALUES('Z636','3','站住，胜过敌诡计，<br/>站住，不被乐所迷，<br/>站住，不为人所欺，<br/>站住，主精兵。<br/>','',57131,10666);
INSERT INTO stanza VALUES('Z636','4','站住，直到那日到，<br/>站住，因主，无所要，<br/>站住，儆醒且祷告，<br/>站住，主精兵。<br/>','',57132,10667);
INSERT INTO stanza VALUES('Z637','1','争战要在身体里面，<br/>永勿单独去迎敌；<br/>同着身体联于元首，<br/>宝座之上将敌袭。<br/>','',57133,10668);
INSERT INTO stanza VALUES('Z637','chorus','争战要在身体里面，<br/>借着元首的功绩；<br/>同着身体站得稳坚，<br/>你就必定得胜利。<br/>','',57134,10669);
INSERT INTO stanza VALUES('Z637','2','神的军装乃为身体，<br/>非为任何的个人；<br/>当你凭着身体争战，<br/>所有益处是你分。<br/>','',57135,10670);
INSERT INTO stanza VALUES('Z637','3','召会建在基督身上，<br/>阴府权势难胜过；<br/>乃是身体得被建造，<br/>才能抵挡众恶魔。<br/>','',57136,10671);
INSERT INTO stanza VALUES('Z637','4','凭着身体，靠着元首，<br/>坐在诸天的境界，<br/>与执政者并众恶魔，<br/>摔跤奋斗不松懈。<br/>','',57137,10672);
INSERT INTO stanza VALUES('Z637','5','同众弟兄为神站住，<br/>作主身上一肢体；<br/>灵中随时多方祷告，<br/>靠着宝血取胜利。<br/>','',57138,10673);
INSERT INTO stanza VALUES('Z637','6','坐在天上得胜有余，<br/>借主力量的大能，<br/>在主里面，同众作战，<br/>如同军队一兵丁。<br/>','',57139,10674);
INSERT INTO stanza VALUES('Z637','7','凭着身体向前进攻，<br/>恶者必由你征服；<br/>照神旨意捆绑、释放，<br/>仇敌必作你食物。<br/>','',57140,10675);
INSERT INTO stanza VALUES('Z638','1','我神是我大能堡垒，<br/>坚固保障永不颓；<br/>致命凶恶虽在包围，<br/>祂作帮助我何畏。<br/>我们老旧仇敌<br/>仍在寻隙攻击，<br/>诡计、能力都大，<br/>又加狠心、毒辣，<br/>地上无人能抵他。<br/>','',57141,10676);
INSERT INTO stanza VALUES('Z638','2','我们若靠自己力量，<br/>奋斗争战必失败；<br/>神选之人岂非在旁？<br/>为何不将祂倚赖？<br/>这位适当之人，<br/>乃是基督本身；<br/>祂是万军之主，<br/>万世万代无殊，<br/>胜利永远惟祂属。<br/>','',57142,10677);
INSERT INTO stanza VALUES('Z638','3','世界虽然充满鬼魔，<br/>常施惊吓谋毁坏，<br/>但是我神定规借我<br/>使祂真理得奏凯。<br/>名利都可远离，<br/>生死我也不计；<br/>即使杀我身体，<br/>真理仍然屹立，<br/>神的国度永无已。<br/>','',57143,10678);
INSERT INTO stanza VALUES('Z639','1','如果争战凶猛，<br/>仇敌强盛，<br/>你当坚信主话，<br/>并发歌声。<br/>','',57144,10679);
INSERT INTO stanza VALUES('Z639','2','只要呼喊一声，<br/>就要得胜，<br/>不要哑口不作<br/>反抗见证。<br/>','',57145,10680);
INSERT INTO stanza VALUES('Z639','3','你灵现在郁闷，<br/>好像无能，<br/>你若借血祷告，<br/>就要高升。<br/>','',57146,10681);
INSERT INTO stanza VALUES('Z639','4','仇敌虽然蛮横，<br/>你可与争，<br/>如果坚守地位，<br/>不久就胜。<br/>','',57147,10682);
INSERT INTO stanza VALUES('Z639','5','所以应当发声，<br/>证明主胜，<br/>光景虽然黑暗，<br/>但必变更。<br/>','',57148,10683);
INSERT INTO stanza VALUES('Z640','1','我对撒但总是说：<br/>『不，』<br/>我对父神就说：『是！』<br/>好叫我主所有部署，<br/>全得成功不受阻。<br/>当我这样听主号令，<br/>求主赐给我权柄，<br/>使我满有能力圣灵，<br/>成功主永远定命。<br/>','',57149,10684);
INSERT INTO stanza VALUES('Z640','2','我对撒但总是说：<br/>『不，』<br/>我对父神就说：『是！』<br/>这个是我永远态度，<br/>求神施恩加保护。<br/>不然当我实行顺服，<br/>撒但就要拦去路；<br/>当我正在听你吩咐，<br/>主耶稣，求你看顾！<br/>','',57150,10685);
INSERT INTO stanza VALUES('Z640','3','我对撒但总是说：<br/>『不，』<br/>我对父神就说：『是！』<br/>我愿完全绝对顺服，<br/>不论将受如何苦。<br/>当我与主同前时候，<br/>主若肯拯救保守，<br/>无论甚么威胁、引诱，<br/>不会使我一回头。<br/>','',57151,10686);
INSERT INTO stanza VALUES('Z641','1','今日战争凶猛，<br/>仇敌更强；<br/>战场呼喊之声<br/>比前响亮！<br/>阴府反抗之声<br/>比前厉害！<br/>却有半夜呼声：<br/>『我必快来！』<br/>','',57152,10687);
INSERT INTO stanza VALUES('Z641','2','今日试炼更苦，<br/>交战益烈；<br/>阴府一齐鼓舞，<br/>集队来劫；<br/>我在此处守等，<br/>更难得胜；<br/>却听喜乐之声：<br/>『耶稣已近！』<br/>','',57153,10688);
INSERT INTO stanza VALUES('Z641','3','更难证实主话，<br/>在此末世，<br/>因为撒但攻打，<br/>竭其权势；<br/>我需更大灵力，<br/>才会败敌；<br/>主来不再叹息，<br/>何等乐呢！<br/>','',57154,10689);
INSERT INTO stanza VALUES('Z641','4','谁愿一直前进，<br/>借主大能？<br/>谁要坚定相信，<br/>以至得胜？<br/>谁要靠主壮心，<br/>以至奏凯？<br/>如此之人乐听：<br/>『我必快来！』<br/>','',57155,10690);
INSERT INTO stanza VALUES('Z641','5','谁选神的最好-<br/>十架窄路，<br/>历尽百般苦恼，<br/>并不回顾？<br/>谁敢奋勇直前，<br/>忍苦、受惊？<br/>因在此时可见：<br/>『耶稣已近！』<br/>','',57156,10691);
INSERT INTO stanza VALUES('Z641','6','现今黑暗深厚，<br/>我们当前，<br/>直至被提时候，<br/>光明才现！<br/>在彼我们见主，<br/>仇敌已败，<br/>得胜者同欢呼：<br/>『耶稣已来！』<br/>','',57157,10692);
INSERT INTO stanza VALUES('Z642','1','当奉耶稣这名站住，<br/>信祂得胜站住；<br/>不靠自己力量站住，<br/>不靠才能站住；<br/>不要使用血气兵器，<br/>只用圣灵宝剑；<br/>穿上神的军装服役，<br/>灭尽仇敌火箭。<br/>','',57158,10693);
INSERT INTO stanza VALUES('Z642','2','看哪，仇敌正在聚集，<br/>故当守你地场！<br/>四面黑暗，争战紧急，<br/>故当靠主抵挡！<br/>你若退后，怕仇敌凶，<br/>一人牵动全军；<br/>请你不要使你弟兄，<br/>因你缘故受窘。<br/>','',57159,10694);
INSERT INTO stanza VALUES('Z642','3','撒但已知其时不久，<br/>所以其气忿忿，<br/>要在争战尚未起首，<br/>就使你灵郁闷。<br/>诱惑、试探比前更多，<br/>苦难比前更大，<br/>阴府权势攻逼你我，<br/>比前更为可怕。<br/>','',57160,10695);
INSERT INTO stanza VALUES('Z642','4','对此情形，我们当有<br/>何种态度才可？<br/>我们可否因贪优游，<br/>便让仇敌宰割？<br/>或者因着苦难加倍，<br/>更加忍耐、奋勇？<br/>生死关头在此定规！<br/>谁要得主称荣？<br/>','',57161,10696);
INSERT INTO stanza VALUES('Z642','5','因此，你当为主站住；<br/>耶稣是得胜者！<br/>你当忍受一切痛苦，<br/>直到那日方舍。<br/>耶稣不久快要再临，<br/>战事不久要停；<br/>你今为主受难、受惊，<br/>那日必得权柄。<br/>','',57162,10697);
INSERT INTO stanza VALUES('Z643','1','得胜、得胜，阿利路亚！<br/>得胜、得胜，阿利路亚！<br/>得胜、得胜，阿利路亚！<br/>基督已经得胜！<br/>','',57163,10698);
INSERT INTO stanza VALUES('Z643','2','得胜、得胜，阿利路亚！<br/>得胜、得胜，阿利路亚！<br/>得胜、得胜，阿利路亚！<br/>基督使我得胜！<br/>','',57164,10699);
INSERT INTO stanza VALUES('Z643','3','荣耀、荣耀，阿利路亚！<br/>荣耀、荣耀，阿利路亚！<br/>荣耀、荣耀，阿利路亚！<br/>荣耀归于主名！<br/>','',57165,10700);
INSERT INTO stanza VALUES('Z644','1','阿利路亚，耶稣得胜！<br/>大声唱凯歌！<br/>耶稣得胜，仍旧得胜，<br/>胜过罪、死、魔！<br/>','',57166,10701);
INSERT INTO stanza VALUES('Z644','chorus','阿利路亚，耶稣得胜！<br/>荣耀的消息！<br/>耶稣得胜，仍旧得胜，<br/>胜过众仇敌！<br/>','',57167,10702);
INSERT INTO stanza VALUES('Z644','2','阿利路亚，耶稣得胜！<br/>宝血有能力！<br/>仗祂十架，时时夸胜，<br/>魔鬼就逃匿。<br/>','',57168,10703);
INSERT INTO stanza VALUES('Z644','3','阿利路亚，耶稣得胜！<br/>疾病也消杀！<br/>因借耶稣，完全得胜，<br/>成于各各他。<br/>','',57169,10704);
INSERT INTO stanza VALUES('Z644','4','阿利路亚，耶稣得胜！<br/>故刚强有为！<br/>无论何处，祂有遣征，<br/>当应命勿畏。<br/>','',57170,10705);
INSERT INTO stanza VALUES('Z644','5','阿利路亚，耶稣得胜！<br/>勿惧，勿让步！<br/>前途纵有黑暗权能，<br/>耶稣必开路。<br/>','',57171,10706);
INSERT INTO stanza VALUES('Z644','6','阿利路亚，耶稣得胜！<br/>耶稣快再临！<br/>所有同祂得胜的人，<br/>前来同欢欣！<br/>','',57172,10707);
INSERT INTO stanza VALUES('Z645','1','天上地下所有权柄，<br/>都已赐给复活基督；<br/>与祂联合，靠祂生命，<br/>所有仇敌都要屈服。<br/>','',57173,10708);
INSERT INTO stanza VALUES('Z645','2','你当借主说你必定<br/>胜过魔鬼一切能力！<br/>应当从主支取权柄，<br/>践踏地上蛇头、龙体。<br/>','',57174,10709);
INSERT INTO stanza VALUES('Z645','3','管你甚么，你这高山！<br/>管你那里，或天或地！<br/>无论如何我总要铲，<br/>奉主的名，你当快离！<br/>','',57175,10710);
INSERT INTO stanza VALUES('Z645','4','信心命你离开此地，<br/>你当顺服投在海里！<br/>我当、我要、我能、<br/>我必成功我神所有目的。<br/>','',57176,10711);
INSERT INTO stanza VALUES('Z646','1','要借基督得胜宝血，<br/>胜过凶恶的仇敌；<br/>借其功效和其能力，<br/>你就必定得胜利。<br/>','',57177,10712);
INSERT INTO stanza VALUES('Z646','chorus','要借基督得胜宝血，<br/>胜过凶恶的仇敌；<br/>借其功效和其能力，<br/>你就必定得胜利。<br/>','',57178,10713);
INSERT INTO stanza VALUES('Z646','2','要借基督得胜宝血，<br/>抵挡狡诈控告者；<br/>借这为你辩护之血，<br/>拒绝谗者的指责。<br/>','',57179,10714);
INSERT INTO stanza VALUES('Z646','3','要借基督得胜宝血，<br/>信神可靠的信实；<br/>因这为你赎罪之血，<br/>神的赦免早已赐。<br/>','',57180,10715);
INSERT INTO stanza VALUES('Z646','4','要借基督得胜宝血，<br/>现今宣告你地位；<br/>借这永远得胜之血，<br/>迫使仇敌全败退。<br/>','',57181,10716);
INSERT INTO stanza VALUES('Z646','5','要借基督得胜宝血，<br/>完全取用祂权柄；<br/>只要应用耶稣之血，<br/>你就必定能得胜。<br/>','',57182,10717);
INSERT INTO stanza VALUES('Z646','6','要借基督得胜宝血，<br/>坐在属天的境界；<br/>借着升天基督权能，<br/>将你仇敌全缴械。<br/>','',57183,10718);
INSERT INTO stanza VALUES('Z647','1','你愿否作主得胜者？<br/>主正在呼召！<br/>愿否作主忠心从者，<br/>路虽不尽晓？<br/>','',57184,10719);
INSERT INTO stanza VALUES('Z647','chorus','你愿否作主得胜者，<br/>满足主心愿？<br/>主在呼召，主在呼召，<br/>要你得冠冕！<br/>','',57185,10720);
INSERT INTO stanza VALUES('Z647','2','你愿否作主得胜者？<br/>要受主吸引；<br/>『起初的爱』总不离弃，<br/>直到那早晨。<br/>','',57186,10721);
INSERT INTO stanza VALUES('Z647','3','你愿否作主得胜者？<br/>倚靠主『生命』；<br/>敢为主受逼迫、苦难，<br/>至死不变更。<br/>','',57187,10722);
INSERT INTO stanza VALUES('Z647','4','你愿否作主得胜者？<br/>要作主见证；<br/>若肯如此，『隐藏吗哪』<br/>必作你供应。<br/>','',57188,10723);
INSERT INTO stanza VALUES('Z647','5','你愿否作主得胜者，<br/>单纯又真诚？<br/>胜过所有邪恶混杂，<br/>必得主『权柄』。<br/>','',57189,10724);
INSERT INTO stanza VALUES('Z647','6','你愿否作主得胜者？<br/>信赖活的主；<br/>使你『衣服』不沾死污，<br/>得生命祝福。<br/>','',57190,10725);
INSERT INTO stanza VALUES('Z647','7','你愿否作主得胜者？<br/>切勿弃主名！<br/>遵守『主的忍耐之道』，<br/>尽上你所能。<br/>','',57191,10726);
INSERT INTO stanza VALUES('Z647','7','你愿否作主得胜者？<br/>勿『不冷不热』；<br/>切勿满意于你所有，<br/>需更有所得。<br/>','',57192,10727);
INSERT INTO stanza VALUES('Z647','9','你愿否作主得胜者？<br/>主仍在呼召！<br/>愿否立即对祂赤诚，<br/>成全祂所要？<br/>','',57193,10728);
INSERT INTO stanza VALUES('Z648','1','我不敢稍微失败，<br/>因有加略在望，<br/>耶稣在彼曾奏凯，<br/>胜过黑暗君王；<br/>求主赐给我异象，<br/>我才临阵奋兴，<br/>使我作个得胜者，<br/>靠着你的大能。<br/>','',57194,10729);
INSERT INTO stanza VALUES('Z648','chorus','得胜，得胜者，<br/>都因着髑髅地。<br/>使我作个得胜者，<br/>因着你，因着你能得胜。<br/>','',57195,10730);
INSERT INTO stanza VALUES('Z648','2','我不敢稍微失败，<br/>因为基督我主，<br/>召我进到前线来，<br/>与祂一同追逐。<br/>求主赐给我胆量，<br/>使我刚强有力，<br/>使我作个得胜者，<br/>里面充满了你。<br/>','',57196,10731);
INSERT INTO stanza VALUES('Z648','3','我不敢稍微失败，<br/>因为耶稣领我<br/>来冲阴府的境界，<br/>与祂同登宝座。<br/>求主赐给你战士，<br/>有力能以挥剑，<br/>使我作个得胜者，<br/>借着你的圣言。<br/>','',57197,10732);
INSERT INTO stanza VALUES('Z648','4','我不敢稍微失败，<br/>当此日西时辰，<br/>因为我主正等待，<br/>要说『好！我仆人。』<br/>求主今日从天上，<br/>从新赐我能力，<br/>使我作个得胜者，<br/>得胜一直到底。<br/>','',57198,10733);
INSERT INTO stanza VALUES('Z649','1','撒但早已定规抵敌<br/>我神的后裔；<br/>从军的召会，当注意！<br/>你已得消息！<br/>','',57199,10734);
INSERT INTO stanza VALUES('Z649','chorus','主留我们今日在世，<br/>原是为争战；<br/>所以若要成功神旨，<br/>就须上疆场。<br/>','',57200,10735);
INSERT INTO stanza VALUES('Z649','2','黑暗军兵已经聚集，<br/>他们已逼近；<br/>从军的召会，当奋起！<br/>你是主亲兵！<br/>','',57201,10736);
INSERT INTO stanza VALUES('Z649','3','奈何主营也有背叛？<br/>是谁爱世俗？<br/>从军的召会不争战，<br/>怎能跟从主？<br/>','',57202,10737);
INSERT INTO stanza VALUES('Z649','4','怎样竟有懦夫<br/>不敢向仇敌挑战？<br/>从军的召会何羞惭，<br/>竟畏势偷安！<br/>','',57203,10738);
INSERT INTO stanza VALUES('Z649','5','若非为我，便是助敌，<br/>此间无两可；<br/>从军的召会，你到底<br/>是与谁联合？<br/>','',57204,10739);
INSERT INTO stanza VALUES('Z649','6','那得胜者仍然得胜，<br/>当享祂功绩；<br/>从军的召会，当承认<br/>加略是为你。<br/>','',57205,10740);
INSERT INTO stanza VALUES('Z649','7','我们的主原是战士，<br/>故当不避危，<br/>否则那里还能算是<br/>从军的召会！<br/>','',57206,10741);
INSERT INTO stanza VALUES('Z649','7','主今呼召，要得胜者，<br/>谁站主一边？<br/>从军的召会，勿耽搁，<br/>甲胄上前线。<br/>','',57207,10742);
INSERT INTO stanza VALUES('Z650','1','不是我们随意走，<br/>乃是随主的引领；<br/>那里活水方涌流，<br/>那里心中方光明。<br/>','',57208,10743);
INSERT INTO stanza VALUES('Z650','2','不是自择的工作，<br/>就能博得祂嘉许；<br/>乃是完成祂委托，<br/>才可领受祂称誉。<br/>','',57209,10744);
INSERT INTO stanza VALUES('Z650','3','不是我们随自己，<br/>就能座前献祷告；<br/>乃是那灵的叹息，<br/>摸着更深的需要。<br/>','',57210,10745);
INSERT INTO stanza VALUES('Z650','4','如果我们答应『不』，<br/>当祂轻说『我需要』，<br/>就是坛上有礼物，<br/>也不能使祂称好。<br/>','',57211,10746);
INSERT INTO stanza VALUES('Z650','5','我们如此向己死，<br/>与祂一同活天上，<br/>如此奉献而服事，<br/>祂将自己作恩赏。<br/>','',57212,10747);
INSERT INTO stanza VALUES('Z651','1','主要我事奉祂的所在，<br/>未必是远隔重洋，<br/>未必是在高山的巉崖，<br/>或在危险的异乡；<br/>但是祂若微声召我去<br/>我不知道的地区，<br/>爱主，我必欣然<br/>答应不犹豫，<br/>要我何去，我就去。<br/>','',57213,10748);
INSERT INTO stanza VALUES('Z651','chorus','爱主，要我何去，<br/>我就去，<br/>无论平地或山河；<br/>要我去说何语，<br/>我就说何语，<br/>要我如何，就如何。<br/>','',57214,10749);
INSERT INTO stanza VALUES('Z651','2','也许今天就有神恩言，<br/>是主要我去呼喊；<br/>也许现在罪恶途径间，<br/>有人要我去追还；<br/>救主，你若亲自来带领，<br/>道路虽然暗无光，<br/>我的声音要<br/>响应你的佳音，<br/>要我怎讲，我就讲。<br/>','',57215,10750);
INSERT INTO stanza VALUES('Z651','3','在这世界广大禾田间，<br/>总有我的一寸土，<br/>我能够花费此生余年，<br/>为着我的受死主；<br/>我将自己交托你手里，<br/>知道你爱我深刻，<br/>我要从我心里<br/>顺服你旨意，<br/>要我如何，就如何。<br/>','',57216,10751);
INSERT INTO stanza VALUES('Z652','1','不可等候，<br/>一直梦想将来成大业，<br/>不可等候，要光被远方，<br/>你有诸般目前本分，<br/>今日当解决，<br/>你的一隅，你当照亮。<br/>','',57217,10752);
INSERT INTO stanza VALUES('Z652','chorus','你的一隅，你当照亮！<br/>你的一隅，你当照亮！<br/>情形越难，<br/>圣徒之光越当照得亮，<br/>你的一隅，你当照亮。<br/>','',57218,10753);
INSERT INTO stanza VALUES('Z652','2','『你们的光当照人前，』<br/>乃是主命令，<br/>你们应当遵从莫掩藏；<br/>一个罪人弃暗就光，<br/>也需人引领，<br/>你的一隅，你当照亮。<br/>','',57219,10754);
INSERT INTO stanza VALUES('Z652','3','请看在你旁边<br/>就有信徒在流浪，<br/>何必到处寻找失迷羊，<br/>应当劝勉、挽回、安慰，<br/>体贴主心肠，<br/>你的一隅，你当照亮。<br/>','',57220,10755);
INSERT INTO stanza VALUES('Z652','4','应当时时与主交通，<br/>瞻仰主圣容，<br/>才能返照荣耀的明光；<br/>你若热诚爱主事主，<br/>人必受感动，<br/>你的一隅，你当照亮。<br/>','',57221,10756);
INSERT INTO stanza VALUES('Z652','5','现今，救主已近，<br/>天上晨星要出现，<br/>主人要来，仆人要得奖；<br/>拯救罪人，挽回信徒，<br/>当趁有今天，<br/>你的一隅，你当照亮。<br/>','',57222,10757);
INSERT INTO stanza VALUES('Z653','1','在流中！在流中！<br/>来为主同作工；<br/>遵主旨，行主路，<br/>照主话来事奉。<br/>在生命水流中，<br/>靠主能而作工；<br/>为召会，为国度，<br/>在此时同事奉。<br/>','',57223,10758);
INSERT INTO stanza VALUES('Z653','chorus','在流中！在流中！<br/>同作工在流中！<br/>在流中！在流中！<br/>与圣徒配搭而事奉。<br/>','',57224,10759);
INSERT INTO stanza VALUES('Z653','2','在流中！在流中！<br/>来为主同作工；<br/>在圣灵水流中，<br/>主的话肯遵从。<br/>永不靠自己力，<br/>不单独，不任意，<br/>乃是与众肢体，<br/>同事奉，互相倚。<br/>','',57225,10760);
INSERT INTO stanza VALUES('Z653','3','在流中！在流中！<br/>来为主同作工，<br/>同召会，同圣徒，<br/>在主话亮光中。<br/>向需要的群众，<br/>传主话，供生命，<br/>为成功神计画，<br/>在流中向前行。<br/>','',57226,10761);
INSERT INTO stanza VALUES('Z654','1','新约之下所有事奉，<br/>不在字句只在灵；<br/>字句乃是将人杀死，<br/>惟有灵是叫人生。<br/>外面作的全都不算，<br/>里面作的才算是；<br/>不是按着旧的仪文，<br/>乃是照灵新样式。<br/>','',57227,10762);
INSERT INTO stanza VALUES('Z654','2','不是仅借外面教导，<br/>乃靠里面的恩膏；<br/>不是仅借外面样式，<br/>乃借里面的光照。<br/>不是凭着人的规条，<br/>乃凭属天的管治；<br/>不是照着人的决定，<br/>乃照神赐的启示。<br/>','',57228,10763);
INSERT INTO stanza VALUES('Z654','3','不是给人死的宗教，<br/>乃是供应活基督；<br/>不是传递虚空神学，<br/>乃是活出主丰富。<br/>不是道理、字句、知识，<br/>乃是基督作信息；<br/>不是恩赐、仪式、作法，<br/>乃是基督为实际。<br/>','',57229,10764);
INSERT INTO stanza VALUES('Z654','4','不是客观对神敬拜，<br/>乃是主观事奉神；<br/>不是传扬客观基督，<br/>乃让基督显我身。<br/>不是仅凭圣经作工，<br/>乃是借灵和生命；<br/>不是靠着肉体、自己，<br/>乃靠大能的圣灵。<br/>','',57230,10765);
INSERT INTO stanza VALUES('Z655','1','生命流露才是工作，<br/>工作必须是生活；<br/>生活、工作成为一体，<br/>工作才会有结果。<br/>经验说出才是信息，<br/>信息必须是经历；<br/>经历、信息能够一致，<br/>信息才会有能力。<br/>','',57231,10766);
INSERT INTO stanza VALUES('Z655','2','工作须是生命果子，<br/>借着那灵所结出；<br/>犹如葡萄树枝结实，<br/>彰显生命的丰富。<br/>乃是基督借我工作，<br/>将祂生命来表现，<br/>使祂生命所有丰富，<br/>借我显在众人前。<br/>','',57232,10767);
INSERT INTO stanza VALUES('Z655','3','不是人所推行运动，<br/>乃是圣灵的感动；<br/>不是外面有所作为，<br/>乃是里面在作工。<br/>不是人的一种事业，<br/>乃是神命的活出；<br/>不是劳苦为着成功，<br/>乃是表现主基督。<br/>','',57233,10768);
INSERT INTO stanza VALUES('Z655','4','我的计划、目的、努力，<br/>一切必须全放弃，<br/>使主可以借我工作，<br/>全为完成祂心意。<br/>我之所是与我所有，<br/>全都必须置死地，<br/>使主可以借我活着，<br/>显祂丰富和美丽。<br/>','',57234,10769);
INSERT INTO stanza VALUES('Z656','1','要在身体事奉、工作，<br/>这是主旨所着重；<br/>身体乃是主所要者，<br/>当与身体同行动。<br/>','',57235,10770);
INSERT INTO stanza VALUES('Z656','chorus','要在身体事奉、工作，<br/>永远不要再单独；<br/>既是身体上的肢体，<br/>就当配搭事奉主。<br/>','',57236,10771);
INSERT INTO stanza VALUES('Z656','2','重生是作主的肢体，<br/>非作单独的个人；<br/>总是应该与众圣徒<br/>互相配搭事奉神。<br/>','',57237,10772);
INSERT INTO stanza VALUES('Z656','3','乃是活石同被建造，<br/>必须作神的灵宫，<br/>成为圣洁祭司体系，<br/>和谐一致的事奉。<br/>','',57238,10773);
INSERT INTO stanza VALUES('Z656','4','因此必须同被建造，<br/>各守地位尽职事；<br/>我们事奉所有根据，<br/>乃是身体的性质。<br/>','',57239,10774);
INSERT INTO stanza VALUES('Z656','5','我们工作，尽职事奉，<br/>须从身体得供应；<br/>若与身体脱节、孤立，<br/>必失功用与功能。<br/>','',57240,10775);
INSERT INTO stanza VALUES('Z656','6','我们若在身体事奉，<br/>元首丰富必得享；<br/>尽上肢体所有功用，<br/>必有基督的身量。<br/>','',57241,10776);
INSERT INTO stanza VALUES('Z656','7','永远持定元首基督，<br/>借祂一同得长进；<br/>从祂得到丰满供应，<br/>分给身体各部分。<br/>','',57242,10777);
INSERT INTO stanza VALUES('Z656','7','主，我重新献上身体，<br/>求你变化我心思，<br/>使我明白你的旨意，<br/>借你身体而服事。<br/>','',57243,10778);
INSERT INTO stanza VALUES('Z657','1','祭司生活何等有福，<br/>得享基督作一切！<br/>衣、食、住处，<br/>全是基督，<br/>并有基督为产业。<br/>','',57244,10779);
INSERT INTO stanza VALUES('Z657','chorus','祭司生活何等有福，<br/>得享基督作一切！<br/>衣、食、住处，<br/>全是基督，<br/>并有基督为产业。<br/>','',57245,10780);
INSERT INTO stanza VALUES('Z657','2','祭司供职所披所戴，<br/>全是基督的荣美；<br/>圣服、圣冠、面牌、<br/>胸牌，<br/>荣耀、华美又尊贵。<br/>','',57246,10781);
INSERT INTO stanza VALUES('Z657','3','祭司向神献上基督，<br/>作神悦纳的祭物，<br/>就得享受祂作食物，<br/>饱尝基督的丰富。<br/>','',57247,10782);
INSERT INTO stanza VALUES('Z657','4','披戴基督，与祂联合，<br/>外面有祂作彰显；<br/>吃喝基督，与祂调和，<br/>里面有祂来充满。<br/>','',57248,10783);
INSERT INTO stanza VALUES('Z657','5','祭司所住，神圣、荣耀，<br/>乃是扩大的基督；<br/>祭司在此同被建造，<br/>就有属灵的住处。<br/>','',57249,10784);
INSERT INTO stanza VALUES('Z657','6','祭司所有也是基督-<br/>祭司惟一的产业；<br/>祭司生活所有事物，<br/>全是基督的一切！<br/>','',57250,10785);
INSERT INTO stanza VALUES('Z658','1','我们事奉须为召会，<br/>神的美意如此定；<br/>这是工作惟一途径，<br/>使徒都曾如此行。<br/>','',57251,10786);
INSERT INTO stanza VALUES('Z658','chorus','我们事奉须为召会，<br/>不该为着别事情；<br/>这是神的完全旨意，<br/>我们必须如此行。<br/>','',57252,10787);
INSERT INTO stanza VALUES('Z658','2','召会要作神的器皿，<br/>是神永远的计划；<br/>神要我们所有事奉，<br/>都为建造祂的家。<br/>','',57253,10788);
INSERT INTO stanza VALUES('Z658','3','元首所赐恩赐的人，<br/>全都为着祂身体；<br/>他们都该建造召会，<br/>使主丰满得建起。<br/>','',57254,10789);
INSERT INTO stanza VALUES('Z658','4','所有恩赐、一切功用、<br/>圣灵所显的能力，<br/>以及所有不同职事，<br/>都该只为主身体。<br/>','',57255,10790);
INSERT INTO stanza VALUES('Z658','5','传扬福音、拯救罪人、<br/>教导、牧养并治理，<br/>以及各样别的工作，<br/>也该只为主身体。<br/>','',57256,10791);
INSERT INTO stanza VALUES('Z658','6','职事乃是为着召会，<br/>召会不是为职事；<br/>所有灯台都是召会，<br/>任何职事都不是。<br/>','',57257,10792);
INSERT INTO stanza VALUES('Z658','7','这能保守召会合一，<br/>拯救我们脱宗派；<br/>这将试验我的动机，<br/>予我目的以更改。<br/>','',57258,10793);
INSERT INTO stanza VALUES('Z658','7','求主救我脱离工作，<br/>脱离宗派的工作；<br/>使我只为召会劳苦，<br/>只为召会而活着。<br/>','',57259,10794);
INSERT INTO stanza VALUES('Z659','1','事奉乃是供应基督，<br/>无论对神或对人；<br/>总是供应基督富余，<br/>以祂为祭事奉神。<br/>','',57260,10795);
INSERT INTO stanza VALUES('Z659','chorus','事奉乃是供应基督，<br/>无论对神或对人；<br/>总是供应基督富余，<br/>以祂为祭事奉神。<br/>','',57261,10796);
INSERT INTO stanza VALUES('Z659','2','古时选民以色列人，<br/>献上美地的丰盛；<br/>照样我们应当献上<br/>从主所有的收成。<br/>','',57262,10797);
INSERT INTO stanza VALUES('Z659','3','基督乃是我们美地，<br/>在祂身上须经营；<br/>从祂收获，丰富有余，<br/>与人分享祂丰盛。<br/>','',57263,10798);
INSERT INTO stanza VALUES('Z659','4','持定基督，借祂长大，<br/>每一肢体尽功用；<br/>接受基督，分给基督，<br/>对祂身体来事奉。<br/>','',57264,10799);
INSERT INTO stanza VALUES('Z659','5','交通、见证、话语职事、<br/>各种事奉及帮助，<br/>都该是将基督摆出，<br/>供应基督的丰富。<br/>','',57265,10800);
INSERT INTO stanza VALUES('Z660','1','现今时候已不多，<br/>旅世程途快要过，<br/>被提钟点已在望，<br/>我们快要见天王；<br/>但愿我们常殷勤，<br/>直到救主再降临。<br/>','',57266,10801);
INSERT INTO stanza VALUES('Z660','2','殷勤服事不冷淡，<br/>竭力作工不畏难，<br/>背负十架不自怜，<br/>愿意为主历苦艰，<br/>一直『买卖』到主来，<br/>若未被提终不改。<br/>','',57267,10802);
INSERT INTO stanza VALUES('Z660','3','殷勤讨伐众恶灵，<br/>竭力进攻诸幽冥，<br/>虽遇危难仍得胜，<br/>未见平安不收阵，<br/>昼夜不断靠祈祷，<br/>在战场上站得牢。<br/>','',57268,10803);
INSERT INTO stanza VALUES('Z660','4','现今光阴如箭飞，<br/>我们盼望快得慰；<br/>愿主保守灵、魂、体，<br/>完全顺服主管理；<br/>但愿我们常豫备，<br/>直到主来不疲惫。<br/>','',57269,10804);
INSERT INTO stanza VALUES('Z660','5','豫备，虽然受试炼；<br/>豫备，虽然无脸面；<br/>豫备，直到我生活，<br/>不能不向主求说：<br/>求主快来不迟延！<br/>求主快来在今天！<br/>','',57270,10805);
INSERT INTO stanza VALUES('Z661','1','赶紧工作，夜快临，<br/>工作在于清晨；<br/>工作，正当朝色新，<br/>工作，花正芬；<br/>工作，当日光无荫，<br/>工作在于骄阳；<br/>赶紧工作，夜快临，<br/>必须离工场。<br/>','',57271,10806);
INSERT INTO stanza VALUES('Z661','2','赶紧工作，夜快临，<br/>工作在于正午；<br/>最亮时辰宜辛勤，<br/>不久不辛苦。<br/>每一飞逝的光阴，<br/>都当装满成绩；<br/>赶紧工作，夜快临，<br/>那时人安息。<br/>','',57272,10807);
INSERT INTO stanza VALUES('Z661','3','赶紧工作，夜快临，<br/>趁此加深暮景；<br/>夕阳西移彩霞新，<br/>再过成灰影；<br/>最后一线的光阴，<br/>不久就要没落；<br/>赶紧作工，夜正临，<br/>转瞬工作过。<br/>','',57273,10808);
INSERT INTO stanza VALUES('Z662','1','荣耀福音向外推广，<br/>乃是生命的涌流；<br/>借着我们活的见证，<br/>失丧罪人蒙拯救。<br/>','',57274,10809);
INSERT INTO stanza VALUES('Z662','chorus','求主使我涌流生命，<br/>使你生命显于我；<br/>借我作你活的器皿，<br/>将人灵里来点活。<br/>','',57275,10810);
INSERT INTO stanza VALUES('Z662','2','生命见证，使人心服，<br/>人才肯来相信主；<br/>借我生命涌流供应，<br/>人才接主进心府。<br/>','',57276,10811);
INSERT INTO stanza VALUES('Z662','3','永远要像葡萄树枝，<br/>住在主里结果子；<br/>借着里面生命涌流，<br/>将主向人来分赐。<br/>','',57277,10812);
INSERT INTO stanza VALUES('Z662','4','愿我生活就是传扬，<br/>使人在我看见祂；<br/>不仅用话宣传道理，<br/>更将生命来种下。<br/>','',57278,10813);
INSERT INTO stanza VALUES('Z663','1','信徒赶快<br/>遵命出去普天下，<br/>通知他们神是如何慈爱，<br/>使之深晓<br/>神已成功祂救法，<br/>并不愿意一人灭亡悲哀。<br/>','',57279,10814);
INSERT INTO stanza VALUES('Z663','chorus','传扬好信息，和平福音，<br/>传扬主耶稣<br/>已经救赎罪人。<br/>','',57280,10815);
INSERT INTO stanza VALUES('Z663','2','请看，<br/>何止千万的人在罪中，<br/>受了捆绑，<br/>一直事奉鬼魔，<br/>无人前去通知：<br/>救赎已成功，<br/>救主已经得胜，<br/>死而复活。<br/>','',57281,10816);
INSERT INTO stanza VALUES('Z663','3','主能救人脱离<br/>罪恶的捆绑，<br/>亚当种类，<br/>因祂舍命结束；<br/>我们应当不畏<br/>赴火与蹈汤，<br/>庶免拦阻一人来信耶稣。<br/>','',57282,10817);
INSERT INTO stanza VALUES('Z663','4','世界各民、各国、<br/>各方并各人，<br/>我们都当前往传扬恩典，<br/>叫人知道：<br/>神是如何成肉身，<br/>受死在地，<br/>使人重生属天。<br/>','',57283,10818);
INSERT INTO stanza VALUES('Z663','5','不该拦阻儿女<br/>献身往边荒，<br/>应当奉献财物帮助福音，<br/>并且祷告，<br/>求神祝福并推广；<br/>你的牺牲，<br/>主必记念在心。<br/>','',57284,10819);
INSERT INTO stanza VALUES('Z663','6','应当记得，<br/>救主已将快再临，<br/>机会一过，<br/>就难再尽本分；<br/>只怕有人<br/>是因你我不热心，<br/>不能得救，<br/>也不能亲近神。<br/>','',57285,10820);
INSERT INTO stanza VALUES('Z664','1','速兴起传福音！<br/>速抢救灵魂！<br/>请你看千万人天天沉沦！<br/>莫塞住怜悯心，<br/>莫看重金银，<br/>松开手，传福音，<br/>趁着现今。<br/>','',57286,10821);
INSERT INTO stanza VALUES('Z664','chorus','速兴起传福音！<br/>速抢救灵魂！<br/>你为何仍忍心，<br/>看人沉沦？<br/>','',57287,10822);
INSERT INTO stanza VALUES('Z665','1','去向亡世供应基督，<br/>非仅借话之所云。<br/>更借生活分出基督，<br/>供应可怜的人群。<br/>','',57288,10823);
INSERT INTO stanza VALUES('Z665','chorus','去向亡世供应基督，<br/>使祂显于你生活；<br/>凭祂活着，将祂分出，<br/>使人与你同得着。<br/>','',57289,10824);
INSERT INTO stanza VALUES('Z665','2','去向亡世供应基督-<br/>你所有的宝贵主；<br/>将你基督分给亲人，<br/>作其成功与财富。<br/>','',57290,10825);
INSERT INTO stanza VALUES('Z665','3','去向亡世供应基督-<br/>你所享受的基督；<br/>将你基督分给朋友，<br/>作其夸耀与鸿福。<br/>','',57291,10826);
INSERT INTO stanza VALUES('Z665','4','去向亡世供应基督，<br/>祂是你命并一切；<br/>将你基督分给众人，<br/>带人来尝祂超越。<br/>','',57292,10827);
INSERT INTO stanza VALUES('Z666','1','去采集材料，为着神的殿，<br/>去劝告亲友向神来回转；<br/>去带领罪人脱罪免沉沦，<br/>去寻找迷羊来归主羊群。<br/>','',57293,10828);
INSERT INTO stanza VALUES('Z666','2','去采集材料，为着神的殿，<br/>去拯救世人脱世界纠缠；<br/>脱离撒但的黑暗与欺骗，<br/>脱离他一切诱惑的手段。<br/>','',57294,10829);
INSERT INTO stanza VALUES('Z666','3','去采集材料，为着神的殿，<br/>去引导浪者，来投主怀间；<br/>去打败魔鬼-害人的仇敌，<br/>去释放俘囚，来向主归依。<br/>','',57295,10830);
INSERT INTO stanza VALUES('Z666','4','去采集材料，为着神的殿，<br/>在身体立场，将基督宣传；<br/>与主众圣徒灵同魂也同，<br/>到处去吹响福音的号筒。<br/>','',57296,10831);
INSERT INTO stanza VALUES('Z667','1','早晨我们播种，<br/>晌午我们播种，<br/>傍晚我们播种，<br/>播出神慈爱；<br/>等候成熟日子，<br/>等候收割点钟，<br/>我们喜乐满怀，<br/>禾捆带回来。<br/>','',57297,10832);
INSERT INTO stanza VALUES('Z667','chorus','禾捆带回来，<br/>禾捆带回来，<br/>我们喜乐满怀，<br/>禾捆带回来。<br/>禾捆带回来，<br/>禾捆带回来，<br/>我们喜乐满怀，<br/>禾捆带回来。<br/>','',57298,10833);
INSERT INTO stanza VALUES('Z667','2','炎日我们播种，<br/>阴天我们播种，<br/>不怕朔风怒号，<br/>不怕乌云盖；<br/>不久庄稼成熟，<br/>不久一切完工，<br/>我们喜乐满怀，<br/>禾捆带回来。<br/>','',57299,10834);
INSERT INTO stanza VALUES('Z667','3','起来，前去播种，<br/>为主流泪播种，<br/>虽然时遭损失，<br/>虽然当忍耐，<br/>哭泣就会过去，<br/>欢迎就在路终，<br/>我们喜乐满怀，<br/>禾捆带回来。<br/>','',57300,10835);
INSERT INTO stanza VALUES('Z668','1','我岂可去，双手空空？<br/>岂可如此见主面？<br/>从无一日为主作工，<br/>未有虏物献主前。<br/>','',57301,10836);
INSERT INTO stanza VALUES('Z668','chorus','我岂可以空手见主？<br/>岂可双手空空去？<br/>未领一人来归基督！<br/>岂可双手空空去？<br/>','',57302,10837);
INSERT INTO stanza VALUES('Z668','2','今日去世复有何恐？<br/>因为恩主已救我；<br/>但一想到双手空空，<br/>愁云立即覆我额！<br/>','',57303,10838);
INSERT INTO stanza VALUES('Z668','3','从前犯罪所废岁月，<br/>假若现在能赎回，<br/>我必完全奉献无缺，<br/>乐行主旨不再违。<br/>','',57304,10839);
INSERT INTO stanza VALUES('Z668','4','哦，愿信徒速起热心，<br/>殷勤作工趁白昼；<br/>死夜尚未临到你身，<br/>努力救人不稍休。<br/>','',57305,10840);
INSERT INTO stanza VALUES('Z669','1','我有一救主，<br/>在天为我祈求，<br/>可亲又可爱，<br/>虽朋友与我疏；<br/>现今祂时时看顾我，<br/>情爱深厚：<br/>哦，愿我救主<br/>也成为你救主！<br/>','',57306,10841);
INSERT INTO stanza VALUES('Z669','chorus','为你，我今祈求！<br/>为你，我今祈求！<br/>但愿我救主<br/>也向你施拯救！<br/>','',57307,10842);
INSERT INTO stanza VALUES('Z669','2','我有一天父，<br/>住在光明之家，<br/>许我一盼望，<br/>既永远，又有据；<br/>不久要接我<br/>到天上去会见祂：<br/>哦，愿祂施恩，<br/>你也能同我去！<br/>','',57308,10843);
INSERT INTO stanza VALUES('Z669','3','我有一喜乐，<br/>这乐涌如海波，<br/>因为我救主<br/>已担去我罪恶，<br/>并且祂现今<br/>还在我里面活着：<br/>哦，愿我救主<br/>也赐你这喜乐！<br/>','',57309,10844);
INSERT INTO stanza VALUES('Z669','4','我有一平安，<br/>静如湖水一般，<br/>奇妙的平安，<br/>世上友未知晓；<br/>惟有主耶稣，<br/>祂是这平安根源：<br/>哦，愿这平安，<br/>你也能亲尝到！<br/>','',57310,10845);
INSERT INTO stanza VALUES('Z669','5','等主救了你，<br/>请也告诉别人：<br/>我主曾如何<br/>也把你来拯救；<br/>并且要祈求，<br/>求你主也救他们：<br/>主听我祈求，<br/>也必听你祈求！<br/>','',57311,10846);
INSERT INTO stanza VALUES('Z669','chorus','为他，你要祈求！<br/>为他，你要祈求！<br/>但愿你救主<br/>也把他来拯救！<br/>','',57312,10847);
INSERT INTO stanza VALUES('Z670','1','你当豫备迎见神，<br/>你当豫备迎见神，<br/>你当豫备迎见神，<br/>悔改相信；豫备见神，<br/>悔改相信，接受救恩。<br/>','',57313,10848);
INSERT INTO stanza VALUES('Z670','2','你当豫备迎见神，<br/>你当豫备迎见神，<br/>你当豫备迎见神，<br/>罪恶脱尽；豫备见神，<br/>罪恶脱尽，改换一新。<br/>','',57314,10849);
INSERT INTO stanza VALUES('Z670','3','你当豫备迎见神，<br/>你当豫备迎见神，<br/>你当豫备迎见神，<br/>奉献心身；豫备见神，<br/>奉献心身，完全归神。<br/>','',57315,10850);
INSERT INTO stanza VALUES('Z671','1','基督已经完成赎罪，<br/>何等奇妙的救主！<br/>重价已付，我被赎回！<br/>何等奇妙的救主！<br/>','',57316,10851);
INSERT INTO stanza VALUES('Z671','chorus','何等奇妙的救主，<br/>是耶稣，我耶稣！<br/>何等奇妙的救主，<br/>是耶稣，我主！<br/>','',57317,10852);
INSERT INTO stanza VALUES('Z671','2','赞美祂血洗罪有效，<br/>何等奇妙的救主！<br/>使我这人与神和好，<br/>何等奇妙的救主！<br/>','',57318,10853);
INSERT INTO stanza VALUES('Z671','3','祂已洗净我的罪愆，<br/>何等奇妙的救主！<br/>今在我心作王掌权，<br/>何等奇妙的救主！<br/>','',57319,10854);
INSERT INTO stanza VALUES('Z671','4','时时刻刻与我亲近，<br/>何等奇妙的救主！<br/>天天保守使我忠心，<br/>何等奇妙的救主！<br/>','',57320,10855);
INSERT INTO stanza VALUES('Z671','5','得胜能力随时赐与，<br/>何等奇妙的救主！<br/>使我争战奏凯有余，<br/>何等奇妙的救主！<br/>','',57321,10856);
INSERT INTO stanza VALUES('Z671','6','我已向祂献上心身，<br/>何等奇妙的救主！<br/>世界不能再把我分，<br/>何等奇妙的救主！<br/>','',57322,10857);
INSERT INTO stanza VALUES('Z672','1','一日，<br/>当天上充满赞美之声，<br/>一日，<br/>当罪恶深染全人类，<br/>耶稣就降世，<br/>为一童女所生，<br/>住在人中间，<br/>显出神光辉！<br/>','',57323,10858);
INSERT INTO stanza VALUES('Z672','chorus','降生，为爱我；<br/>受死，为救我；<br/>埋葬，为带去<br/>我一切罪过；<br/>复活，为白白的<br/>永远称义我；<br/>一日，祂要来，<br/>哦，荣日接我！<br/>','',57324,10859);
INSERT INTO stanza VALUES('Z672','2','一日，<br/>人将祂带到加略山上，<br/>一日，<br/>人把祂钉木上剪除；<br/>祂备尝痛苦，<br/>被神击打、压伤，<br/>担当我罪过，<br/>作我救赎主！<br/>','',57325,10860);
INSERT INTO stanza VALUES('Z672','3','一日，<br/>人撇祂独自在那园中，<br/>一日，<br/>祂安息，息了诸痛苦；<br/>天使从天来，<br/>夜间守祂墓洞；<br/>无望者之望，<br/>乃是我救主！<br/>','',57326,10861);
INSERT INTO stanza VALUES('Z672','4','一日，<br/>那坟墓不能将祂留藏，<br/>一日，<br/>那大石辊开不封堵；<br/>祂已复活了，<br/>祂已胜过死亡，<br/>升到高天上，<br/>永远作我主！<br/>','',57327,10862);
INSERT INTO stanza VALUES('Z672','5','一日，号筒响，<br/>传报祂从天来，<br/>一日，<br/>祂荣光满天都照出；<br/>奇妙的日子，<br/>带来我的心爱；<br/>荣耀的救主，<br/>就是我耶稣！<br/>','',57328,10863);
INSERT INTO stanza VALUES('Z673','1','耶稣，我救主，<br/>降生马槽中，<br/>成为『忧患人』，<br/>来经历苦痛；<br/>哦，这真希奇，<br/>值得我称颂！<br/>祂来寻我，寻我！<br/>','',57329,10864);
INSERT INTO stanza VALUES('Z673','chorus','祂来寻我，寻我！<br/>祂来寻我，寻我！<br/>哦，这真希奇，<br/>值得我称颂！<br/>祂来寻我，寻我！<br/>','',57330,10865);
INSERT INTO stanza VALUES('Z673','2','耶稣，我救主，<br/>在加略木上，<br/>还我众罪债，<br/>将我人释放；<br/>哦，这真希奇，<br/>怎么会这样？<br/>祂死为我，为我！<br/>','',57331,10866);
INSERT INTO stanza VALUES('Z673','chorus','祂死为我，为我！<br/>祂死为我，为我！<br/>哦，这真希奇，<br/>怎么会这样？<br/>祂死为我，为我！<br/>','',57332,10867);
INSERT INTO stanza VALUES('Z673','3','耶稣，我救主，<br/>永活不改变，<br/>当我在流荡，<br/>将我来召唤；<br/>虽遭我拒绝，<br/>仍召不间断，<br/>祂来召我，召我！<br/>','',57333,10868);
INSERT INTO stanza VALUES('Z673','chorus','祂来召我，召我！<br/>祂来召我，召我！<br/>虽遭我拒绝，<br/>仍召不间断，<br/>祂来召我，召我！<br/>','',57334,10869);
INSERT INTO stanza VALUES('Z673','4','耶稣，我救主，<br/>要来接选民，<br/>这应许甜美，<br/>当年日飞奔：<br/>哦，我要见祂<br/>从天上降临，<br/>祂来接我，接我！<br/>','',57335,10870);
INSERT INTO stanza VALUES('Z673','chorus','祂来接我，接我！<br/>祂来接我，接我！<br/>哦，我要见祂<br/>从天上降临，<br/>祂来接我，接我！<br/>','',57336,10871);
INSERT INTO stanza VALUES('Z674','1','至大医生可亲可近，<br/>就是同情的耶稣，<br/>能医罪伤，能解忧困，<br/>请你速来就耶稣。<br/>','',57337,10872);
INSERT INTO stanza VALUES('Z674','chorus','祂为你受死木上，<br/>祂将你众罪担当，<br/>祂寻你前来医伤，<br/>速来就这耶稣。<br/>','',57338,10873);
INSERT INTO stanza VALUES('Z674','2','罪孽虽多，必蒙赦免，<br/>只要肯来就耶稣！<br/>良心虽亏，必得平安，<br/>若你肯来就耶稣！<br/>','',57339,10874);
INSERT INTO stanza VALUES('Z674','3','性情败坏，罪恶染心，<br/>要得救治，就耶稣；<br/>软弱、叹息、疾病缠身，<br/>要蒙医治，就耶稣！<br/>','',57340,10875);
INSERT INTO stanza VALUES('Z674','4','郁闷、痛苦、人生乏味，<br/>何不前来就耶稣？<br/>祂能赐你医治活水，<br/>请来一试就耶稣！<br/>','',57341,10876);
INSERT INTO stanza VALUES('Z674','5','我已得着医治、释放，<br/>因我接受主耶稣；<br/>荣耀归给被杀羔羊，<br/>我今相信主耶稣。<br/>','',57342,10877);
INSERT INTO stanza VALUES('Z674','chorus','我得释，因祂被绑；<br/>我得医，因祂受伤；<br/>我得生，因祂命亡；<br/>我已得着耶稣。<br/>','',57343,10878);
INSERT INTO stanza VALUES('Z674','6','我爱救我恩主之名，<br/>我爱之名是耶稣！<br/>这名驱尽我的苦情，<br/>宝贝之名惟耶稣！<br/>','',57344,10879);
INSERT INTO stanza VALUES('Z674','chorus','馨香名，圣徒爱唱！<br/>尊贵名，天使颂扬！<br/>高超名，万名之上！<br/>耶稣！宝贝耶稣！<br/>','',57345,10880);
INSERT INTO stanza VALUES('Z674','7','等我被提到祂面前，<br/>亲眼得见我耶稣，<br/>荣耀之中更要颂赞<br/>耶稣！宝贝的耶稣！<br/>','',57346,10881);
INSERT INTO stanza VALUES('Z675','1','这个荣耀信息何甜，<br/>相信要简单：<br/>昨日、今日、直到永远，<br/>耶稣不改变。<br/>祂仍喜爱拯救罪人，<br/>医治人疾病，<br/>平静风浪，安抚惊魂；<br/>荣耀归祂名！<br/>','',57347,10882);
INSERT INTO stanza VALUES('Z675','chorus','昨日、今日、直到永远，<br/>耶稣不改变！<br/>万事万物都在递迁，<br/>耶稣不改变！<br/>耶稣不改变，<br/>耶稣不改变；<br/>万事万物都在递迁，<br/>耶稣不改变！<br/>','',57348,10883);
INSERT INTO stanza VALUES('Z675','2','耶稣乃是罪人之友，<br/>祂今寻找你；<br/>来祂脚前认罪、祈求，<br/>祂必不丢弃；<br/>祂必对你说出恩言，<br/>像祂在当年<br/>曾对人说：『你罪赦免，<br/>可平安向前。』<br/>','',57349,10884);
INSERT INTO stanza VALUES('Z675','3','当祂在世，曾医病痛，<br/>用祂大能手；<br/>今仍施医与昔相同，<br/>祂话要接受。<br/>医治之能曾经显在<br/>一妇的一摸；<br/>今向信心此能不改，<br/>要显同样多。<br/>','',57350,10885);
INSERT INTO stanza VALUES('Z675','4','像祂前曾与人同行，<br/>去以马忤斯；<br/>照样祂在我的一生，<br/>与我永偕止。<br/>不久我就要再见祂，<br/>因祂必快来！<br/>但祂必定一点不差，<br/>像祂在离开。<br/>','',57351,10886);
INSERT INTO stanza VALUES('Z676','1','大喜信我已听见：<br/>主救人！主救人！<br/>这佳音务要传遍：<br/>主救人！主救人！<br/>去天下中外人间，<br/>不要顾路途艰险，<br/>遵主命到处宣传：<br/>主救人！主救人！<br/>','',57352,10887);
INSERT INTO stanza VALUES('Z676','2','去通知贫富家门：<br/>主救人！主救人！<br/>去告诉大小罪人：<br/>主救人！主救人！<br/>众海岛应当歌唱，<br/>深海洋也当应响，<br/>全地上都当宣扬：<br/>主救人！主救人！<br/>','',57353,10888);
INSERT INTO stanza VALUES('Z676','3','十字架已经宣告：<br/>主救人！主救人！<br/>宝贵血仍在说道：<br/>主救人！主救人！<br/>主受死使人免惩，<br/>主复活使人得生，<br/>主升天使人高升：<br/>主救人！主救人！<br/>','',57354,10889);
INSERT INTO stanza VALUES('Z676','4','这个是真正福音：<br/>主救人！主救人！<br/>这个能安慰人心：<br/>主救人！主救人！<br/>疲困人可得安息，<br/>忧伤人也能欢喜，<br/>有罪人不必迟疑：<br/>主救人！主救人！<br/>','',57355,10890);
INSERT INTO stanza VALUES('Z676','5','这福音仍要传报：<br/>主救人！主救人！<br/>世上人都该知晓：<br/>主救人！主救人！<br/>神恩丰，广赐众人；<br/>人罪深，也能蒙恩；<br/>我声微，仍要诵吟：<br/>主救人！主救人！<br/>','',57356,10891);
INSERT INTO stanza VALUES('Z677','1','怜悯、慈爱、宽恕、<br/>温柔又谦和；<br/>为了罪人忍辱，<br/>甘负十架轭；<br/>舍命、流血、受苦，<br/>为救失丧者：<br/>这是基督耶稣，<br/>对祂你如何？<br/>','',57357,10892);
INSERT INTO stanza VALUES('Z678','1','除了耶稣以外，<br/>除了耶稣以外，<br/>没有别的拯救，<br/>没有别的拯救；<br/>因为在天下人间，<br/>因为在天下人间，<br/>没有赐下别名，<br/>人可靠着得生。<br/>','',57358,10893);
INSERT INTO stanza VALUES('Z679','1','行善不能救我！<br/>我虽谨慎我行径，<br/>不过使我得美名，<br/>不能改变我恶性；<br/>行善不能救我！<br/>','',57359,10894);
INSERT INTO stanza VALUES('Z679','chorus','耶稣为我曾流泪！<br/>耶稣为我曾赎罪！<br/>耶稣现今施恩惠！<br/>耶稣才能救我！<br/>','',57360,10895);
INSERT INTO stanza VALUES('Z679','2','哀哭不能救我！<br/>我眼虽然常流泪，<br/>不能洗净我的罪，<br/>不能使我得安慰；<br/>哀哭不能救我！<br/>','',57361,10896);
INSERT INTO stanza VALUES('Z679','3','等候不能救我！<br/>罪恶害我到如此，<br/>越过惟有越放肆，<br/>若再等候是等死；<br/>等候不能救我！<br/>','',57362,10897);
INSERT INTO stanza VALUES('Z679','4','信主才能救我！<br/>因主为我流宝血，<br/>要将我洗白如雪，<br/>我若信祂必清洁；<br/>信主才能救我！<br/>','',57363,10898);
INSERT INTO stanza VALUES('Z680','1','哦，爱！奇妙之爱，<br/>救主去加略！<br/>为去那地，祂竟离宝座，<br/>来受贫穷、苦楚，<br/>遭患从未却，<br/>一路艰难全是为着我！<br/>','',57364,10899);
INSERT INTO stanza VALUES('Z680','chorus','祂去加略，<br/>一路全是为着我，<br/>是为着我，是为着我；<br/>祂去加略，<br/>一路全是为着我，<br/>祂去将我救活！<br/>','',57365,10900);
INSERT INTO stanza VALUES('Z680','2','哦，惨！惨不忍睹，<br/>救主挂木上！<br/>头戴荆冕，手脚被钉着，<br/>身带鞭打创伤，<br/>全人血成行，<br/>备尝痛苦，是因爱怜我！<br/>','',57366,10901);
INSERT INTO stanza VALUES('Z680','chorus','祂钉木上受苦，<br/>是因爱怜我，<br/>因爱怜我，因爱怜我；<br/>祂钉木上受苦，<br/>是因爱怜我，<br/>祂钉解我捆索！<br/>','',57367,10902);
INSERT INTO stanza VALUES('Z680','3','阿呀！遍地黑暗，<br/>神来审判祂！<br/>圣洁怒气焚烧如烈火；<br/>因祂替我担罪，<br/>公义将祂杀，<br/>祂受刑罚，乃是代替我！<br/>','',57368,10903);
INSERT INTO stanza VALUES('Z680','chorus','祂在十架受死，<br/>乃是代替我，<br/>是代替我，是代替我；<br/>祂在十架受死，<br/>乃是代替我，<br/>祂死担我罪过！<br/>','',57369,10904);
INSERT INTO stanza VALUES('Z680','4','可怜！<br/>战兢罪人原不懂恩典！<br/>今在加略见祂肋被戳，<br/>并闻：『我血流出，<br/>为你买赦免，』<br/>才知祂死已经救赎我！<br/>','',57370,10905);
INSERT INTO stanza VALUES('Z680','chorus','祂在十架流血，<br/>已经救赎我，已救赎我，<br/>已救赎我；<br/>祂在十架流血，<br/>已经救赎我，<br/>流血免我灾祸！<br/>','',57371,10906);
INSERT INTO stanza VALUES('Z681','1','阿呀！救主身悬木架，<br/>手足被钉难忍，<br/>头戴荆冕，利刺痛扎，<br/>身有鞭打伤痕。<br/>','',57372,10907);
INSERT INTO stanza VALUES('Z681','chorus','在十架，在十架，<br/>我看见主恩光，<br/>罪重担从我身全卸脱！<br/>在十架，我因信，<br/>眼明亮，心平康，<br/>从今后，我终日能欢乐！<br/>','',57373,10908);
INSERT INTO stanza VALUES('Z681','2','祂在十架这样被难，<br/>乃是替我受谴；<br/>怜悯惊人，恩难测算，<br/>慈爱何其超凡！<br/>','',57374,10909);
INSERT INTO stanza VALUES('Z681','3','神将人罪归祂身上，<br/>要祂为人担当，<br/>难怪太阳全然隐藏，<br/>关闭一切荣光。<br/>','',57375,10910);
INSERT INTO stanza VALUES('Z681','4','看哪！祂死，殿幔即裂，<br/>神、人间隔已去；<br/>圣徒坟墓亦多崩决，<br/>死亡不能再拘。<br/>','',57376,10911);
INSERT INTO stanza VALUES('Z681','5','哦，祂肋旁还被扎伤，<br/>有血和水流出，<br/>赐我生命，免我死亡，<br/>将我罪孽洁除。<br/>','',57377,10912);
INSERT INTO stanza VALUES('Z681','6','临死之前，祂喊，<br/>『成了！』<br/>宣告救工已完；<br/>我闻此言，忧惧顿消，<br/>哀叹立变感赞！<br/>','',57378,10913);
INSERT INTO stanza VALUES('Z682','1','我听救主声音，<br/>说我能力薄弱，<br/>若非诚心相信，<br/>不能免去罪过。<br/>','',57379,10914);
INSERT INTO stanza VALUES('Z682','chorus','我欠千万金，<br/>主替我还尽；<br/>一生犯罪真苦辛，<br/>主今赦免、怜悯。<br/>','',57380,10915);
INSERT INTO stanza VALUES('Z682','2','主，我今才看明，<br/>惟你有这力量，<br/>能洗污秽洁净，<br/>能使软弱刚强。<br/>','',57381,10916);
INSERT INTO stanza VALUES('Z682','3','我真没有善良，<br/>可以得主救恩；<br/>但主特别体谅，<br/>用爱救我罪人。<br/>','',57382,10917);
INSERT INTO stanza VALUES('Z682','4','即云我要离世，<br/>我仍不至战兢；<br/>因我所欠罪值，<br/>主早替我还清。<br/>','',57383,10918);
INSERT INTO stanza VALUES('Z682','5','将来立在神前，<br/>神必不再追问；<br/>因主为我缺欠，<br/>已经流血受审。<br/>','',57384,10919);
INSERT INTO stanza VALUES('Z683','1','耶稣爱我，从天降临，<br/>甘心虚己，成为肉身。<br/>受尽讥诮、鞭打、辱骂，<br/>至终被钉十字苦架。<br/>','',57385,10920);
INSERT INTO stanza VALUES('Z683','chorus','耶稣死是为我，<br/>耶稣死是为我，<br/>为我，为我，为我，<br/>为我，耶稣死是为我。<br/>','',57386,10921);
INSERT INTO stanza VALUES('Z684','1','何能洗去我污点？<br/>无他，惟有耶稣宝血！<br/>何能恢复我完全？<br/>无他，惟有耶稣宝血！<br/>','',57387,10922);
INSERT INTO stanza VALUES('Z684','chorus','哦，这血泉何妙！<br/>洗我如雪白皎！<br/>别泉无此功效：<br/>无他，惟有耶稣宝血！<br/>','',57388,10923);
INSERT INTO stanza VALUES('Z684','2','要得清洁，我认定，<br/>无他，惟有耶稣宝血！<br/>要得赦免，我能凭，<br/>无他，惟有耶稣宝血！<br/>','',57389,10924);
INSERT INTO stanza VALUES('Z684','3','无何能赎我罪愆，<br/>无他，惟有耶稣宝血！<br/>无何能算我义善，<br/>无他，惟有耶稣宝血！<br/>','',57390,10925);
INSERT INTO stanza VALUES('Z684','4','我的圣洁和公义，<br/>无他，惟有耶稣宝血！<br/>我的盼望和安息，<br/>无他，惟有耶稣宝血！<br/>','',57391,10926);
INSERT INTO stanza VALUES('Z685','1','耶稣我救主作神羔羊，<br/>为罪人受死，罪债清偿；<br/>将祂的宝血洒你身上，<br/>神必越过你，你免灭亡。<br/>','',57392,10927);
INSERT INTO stanza VALUES('Z685','chorus','我一见这血，<br/>我一见这血，<br/>我一见这血，<br/>我就必越过你，不毁灭！<br/>','',57393,10928);
INSERT INTO stanza VALUES('Z685','2','罪中的罪魁，耶稣肯救，<br/>凡祂所应许，祂必成就，<br/>在祂这血下，虽有愆尤，<br/>神必越过你，你得宽宥。<br/>','',57394,10929);
INSERT INTO stanza VALUES('Z685','3','审判要来到，无人免除；<br/>在神公义前，谁能立足？<br/>惟有让祂血将你掩护，<br/>神必越过你，你免对簿。<br/>','',57395,10930);
INSERT INTO stanza VALUES('Z685','4','哦，怜悯何大！<br/>哦，爱无边！<br/>哦，神圣恩典，<br/>丰盛、甘甜！<br/>在血荫蔽下享受平安，<br/>神必越过你，你要颂赞！<br/>','',57396,10931);
INSERT INTO stanza VALUES('Z685','chorus','奇妙羔羊血，<br/>荣耀羔羊血，<br/>宝贵羔羊血，<br/>神一见羔羊血便逾越。<br/>','',57397,10932);
INSERT INTO stanza VALUES('Z686','1','今有一泉，血流盈满，<br/>涌自耶稣肋边；<br/>罪人只要一投此泉，<br/>立去全身罪愆。<br/>立去全身罪愆，<br/>立去全身罪愆，<br/>罪人只要一投此泉，<br/>立去全身罪愆。<br/>','',57398,10933);
INSERT INTO stanza VALUES('Z686','2','当日与主同钉一盗，<br/>曾见此泉功效；<br/>我罪即使不比他少，<br/>在此必能除掉。<br/>在此必能除掉，<br/>在此必能除掉，<br/>我罪即使不比他少，<br/>在此必能除掉。<br/>','',57399,10934);
INSERT INTO stanza VALUES('Z686','3','被杀羔羊，你的宝血，<br/>权能永不消灭，<br/>要将选民都洗清洁，<br/>永远与罪隔绝。<br/>永远与罪隔绝，<br/>永远与罪隔绝，<br/>要将选民都洗清洁，<br/>永远与罪隔绝。<br/>','',57400,10935);
INSERT INTO stanza VALUES('Z686','4','自从我见此泉之开，<br/>乃因你身受害，<br/>我便颂扬救赎大爱，<br/>颂扬至死不迨。<br/>颂扬至死不迨，<br/>颂扬至死不迨，<br/>我便颂扬救赎大爱，<br/>颂扬至死不迨。<br/>','',57401,10936);
INSERT INTO stanza VALUES('Z686','5','等到离世，拙口闭封，<br/>笨舌墓中寂静，<br/>我要发出复活歌声，<br/>赞你救赎大能。<br/>赞你救赎大能，<br/>赞你救赎大能，<br/>我要发出复活歌声，<br/>赞你救赎大能。<br/>','',57402,10937);
INSERT INTO stanza VALUES('Z687','1','你愿脱离良心的重担么？<br/>权能是在血，权能在血；<br/>你愿免去公义的审判么？<br/>奇妙的权能是在血。<br/>','',57403,10938);
INSERT INTO stanza VALUES('Z687','chorus','有权能！能！<br/>奇妙大权能，<br/>在羔羊之宝血！<br/>有权能！能！<br/>奇妙大权能，<br/>在圣洁羔羊之宝血！<br/>','',57404,10939);
INSERT INTO stanza VALUES('Z687','2','你愿脱掉罪恶的羞愧么？<br/>权能是在血，权能在血；<br/>你愿去掉情欲的污秽么？<br/>奇妙的权能是在血。<br/>','',57405,10940);
INSERT INTO stanza VALUES('Z687','3','你愿洁净犹如雪一般么？<br/>权能是在血，权能在血；<br/>你愿成圣好像主完全么？<br/>奇妙的权能是在血。<br/>','',57406,10941);
INSERT INTO stanza VALUES('Z687','4','你愿得着完全的救恩么？<br/>权能是在血，权能在血；<br/>你愿享受永生的福分么？<br/>奇妙的权能是在血。<br/>','',57407,10942);
INSERT INTO stanza VALUES('Z687','5','惟有这泉能将罪全抹杀，<br/>权能是在血，权能在血；<br/>速投这泉，<br/>你众罪必脱下，<br/>奇妙的权能是在血。<br/>','',57408,10943);
INSERT INTO stanza VALUES('Z688','1','曾否就主，<br/>求祂洗净你罪愆？<br/>曾否在羔羊血洗清洁？<br/>曾否信主，<br/>接祂进入你心间？<br/>曾否在羔羊血洗清洁？<br/>','',57409,10944);
INSERT INTO stanza VALUES('Z688','chorus','曾否在羔羊血，<br/>在羔羊有能血洗清洁？<br/>你的衣裳<br/>是否洁白犹如雪？<br/>曾否在羔羊血洗清洁？<br/>','',57410,10945);
INSERT INTO stanza VALUES('Z688','2','曾否蒙主赐你<br/>赦罪的恩典？<br/>曾否在羔羊血洗清洁？<br/>曾否因主<br/>替你受死而心安？<br/>曾否在羔羊血洗清洁？<br/>','',57411,10946);
INSERT INTO stanza VALUES('Z688','3','救主来时，<br/>你的衣裳是否白？<br/>曾否在羔羊血洗清洁？<br/>荣耀冠冕，<br/>你的头额配否戴？<br/>曾否在羔羊血洗清洁？<br/>','',57412,10947);
INSERT INTO stanza VALUES('Z688','4','加略泉源<br/>为着罪人正流淌，<br/>曾否在羔羊血洗清洁？<br/>污秽衣裳，<br/>不该还留在身上！<br/>曾否在羔羊血洗清洁？<br/>','',57413,10948);
INSERT INTO stanza VALUES('Z689','1','奇妙的爱，耶稣从天来，<br/>竟肯为我罪人十架受害；<br/>奇妙的爱，耶稣被裂开，<br/>白白为我罪人流血还债。<br/>','',57414,10949);
INSERT INTO stanza VALUES('Z690','1','爱何奇妙，恩何深广，<br/>神差爱子来此；<br/>罪的审判归祂身上，<br/>祂为你我代死。<br/>爱路，恩门，今正齐开，<br/>无别拯救舍此以外，<br/>神心依依等待你来，<br/>切莫拒祂恩爱。<br/>','',57415,10950);
INSERT INTO stanza VALUES('Z691','1','恩典！美妙声音，<br/>悦耳，又慰人心，<br/>天上充满祂的回音，<br/>地上也都听闻。<br/>','',57416,10951);
INSERT INTO stanza VALUES('Z691','chorus','得救本乎恩！<br/>这是真福音；<br/>耶稣死为救罪人，<br/>为救我这罪人。<br/>','',57417,10952);
INSERT INTO stanza VALUES('Z691','2','恩典藏于基督，<br/>丰富口舌难述；<br/>恩典为我成功救赎，<br/>释放我这罪奴。<br/>','',57418,10953);
INSERT INTO stanza VALUES('Z691','3','恩典赎我罪愆，<br/>使我得着赦免；<br/>恩典使我得见神面，<br/>得享天上平安。<br/>','',57419,10954);
INSERT INTO stanza VALUES('Z691','4','恩典赐我生命，<br/>使我有神性情；<br/>恩典使我永属主名，<br/>脱离阴府幽冥。<br/>','',57420,10955);
INSERT INTO stanza VALUES('Z692','1','前有一官<br/>因见耶稣的神能，<br/>就在夜间<br/>来问作人的途径；<br/>救主实实在在的<br/>对他说明：<br/>『你们必须重生！』<br/>','',57421,10956);
INSERT INTO stanza VALUES('Z692','chorus','『你们必须重生！<br/>你们必须重生！』<br/>救主实实在在的<br/>对他说明：<br/>『你们必须重生！』<br/>','',57422,10957);
INSERT INTO stanza VALUES('Z692','2','这话，<br/>世人务要郑重而敬听，<br/>这是救主所说，<br/>严肃而肯定，<br/>切莫轻忽<br/>祂这神圣的叮咛：<br/>『你们必须重生！』<br/>','',57423,10958);
INSERT INTO stanza VALUES('Z692','3','哦，<br/>谁想要进那光明的天城，<br/>并同赎民<br/>享那荣耀的安宁，<br/>他就需要<br/>得那永远的生命：<br/>『你们必须重生！』<br/>','',57424,10959);
INSERT INTO stanza VALUES('Z692','4','救主已被举起，<br/>信者就得生；<br/>圣灵今在感动，<br/>顺者必成圣；<br/>只要你肯悔改，<br/>相信主的名，<br/>你就必能重生！<br/>','',57425,10960);
INSERT INTO stanza VALUES('Z692','chorus','你就必能重生！<br/>你就必能重生！<br/>只要你肯悔改，<br/>相信主的名，<br/>你就必能重生！<br/>','',57426,10961);
INSERT INTO stanza VALUES('Z693','1','基督已经穿上人性，<br/>成为一人好像我；<br/>祂已钉死十字架上，<br/>亚当生命我得脱；<br/>祂且复活，化身圣灵，<br/>到我里面来活着，<br/>为要作我生命。<br/>','',57427,10962);
INSERT INTO stanza VALUES('Z693','chorus','荣耀！荣耀！阿利路亚！<br/>荣耀！荣耀！阿利路亚！<br/>荣耀！荣耀！阿利路亚！<br/>基督是我生命！<br/>','',57428,10963);
INSERT INTO stanza VALUES('Z694','1','主是生命，主是复活，<br/>生命是祂掌握；<br/>祂已借死毁坏死、魔，<br/>现今永远活着；<br/>现今永远活着，<br/>现今永远、永远活着。<br/>','',57429,10964);
INSERT INTO stanza VALUES('Z694','2','荣耀、荣耀，何等生命，<br/>我今已经得着！<br/>黑暗、死亡、罪的权势，<br/>现今都已消没！<br/>现今都已消没！<br/>现今都已、都已消没！<br/>','',57430,10965);
INSERT INTO stanza VALUES('Z695','1','救主为我死，<br/>何等的奇妙！<br/>我本该定罪，<br/>祂使我逍遥；<br/>祂再三的说：<br/>人若是信靠，<br/>已经出死入生！<br/>','',57431,10966);
INSERT INTO stanza VALUES('Z695','chorus','真福音，真福音，<br/>你们快来听！<br/>真福音，真福音，<br/>基督已讲明：<br/>人若肯相信神儿子的名，<br/>已经出死入生！<br/>','',57432,10967);
INSERT INTO stanza VALUES('Z695','2','一切的亏欠，<br/>祂替我还清；<br/>一切的污秽，<br/>祂替我洗净；<br/>祂特意的说：<br/>人若信祂名，<br/>已经出死入生！<br/>','',57433,10968);
INSERT INTO stanza VALUES('Z695','3','我虽满罪恶，<br/>我能信祂名；<br/>我虽极软弱，<br/>我能受祂灵；<br/>朋友，<br/>这真是何等的荣幸！<br/>已经出死入生！<br/>','',57434,10969);
INSERT INTO stanza VALUES('Z695','4','我虽顶不堪，<br/>我不肯生疑；<br/>到祂那里的，<br/>祂永不绝弃；<br/>凡是信祂的，<br/>都当时常记：<br/>已经出死入生！<br/>','',57435,10970);
INSERT INTO stanza VALUES('Z696','1','听阿，有一隐藏奥秘，<br/>历世历代人未知悉！<br/>若肯接受这一奥秘，<br/>就与基督成一！<br/>荣耀、荣耀，阿利路亚！<br/>荣耀、荣耀，阿利路亚！<br/>若肯接受这一奥秘，<br/>就与基督成一！<br/>','',57436,10971);
INSERT INTO stanza VALUES('Z697','1','大喜信息！惊天动地！<br/>神愿与人住在一起！<br/>人虽卑鄙，祂仍属意；<br/>人虽不堪，祂仍不弃。<br/>','',57437,10972);
INSERT INTO stanza VALUES('Z697','chorus','大信息！真奥秘！<br/>神愿与人住在一起！<br/>永远合一，永远安息，<br/>永远享受神的自己。<br/>大信息！真奥秘！<br/>神愿与人住在一起！<br/>','',57438,10973);
INSERT INTO stanza VALUES('Z698','1','我主耶稣是生命源，<br/>我主耶稣是活水泉；<br/>喝了这水，主曾明说，<br/>就永远永远不再渴。<br/>难道永远不再渴？<br/>是！永远不再渴！<br/>难道永远不再渴？<br/>是！永远不再渴！<br/>喝了这水，主曾明说，<br/>就永远永远不再渴。<br/>','',57439,10974);
INSERT INTO stanza VALUES('Z698','2','我主耶稣是永生仓，<br/>我主耶稣是生命粮；<br/>吃了这粮，主曾明说，<br/>就永远永远不再饿。<br/>难道永远不再饿？<br/>是！永远不再饿！<br/>难道永远不再饿？<br/>是！永远不再饿！<br/>吃了这粮，主曾明说，<br/>就永远永远不再饿。<br/>','',57440,10975);
INSERT INTO stanza VALUES('Z698','3','我主耶稣是复活王，<br/>我主耶稣是生命皇；<br/>凡信祂的，主曾明示，<br/>就永远永远不再死。<br/>难道永远不再死？<br/>是！永远不再死！<br/>难道永远不再死？<br/>是！永远不再死！<br/>凡信祂的，主曾明示，<br/>就永远永远不再死。<br/>','',57441,10976);
INSERT INTO stanza VALUES('Z699','1','你的罪虽像朱红，<br/>主必使变成雪白。<br/>你的罪虽像朱红，<br/>主必使变成雪白。<br/>你罪虽红如丹颜，<br/>必白羊毛般。<br/>你的罪虽像朱红，<br/>你的罪虽像朱红，<br/>主必使变成雪白，<br/>主必使变成雪白。<br/>','',57442,10977);
INSERT INTO stanza VALUES('Z699','2','你要听主的呼声，<br/>当回转归向救主！<br/>你要听主的呼声，<br/>当回转归向救主！<br/>爱主招呼耐等待，<br/>你何不归来？<br/>你要听主的呼声，<br/>你要听主的呼声，<br/>当回转归向救主！<br/>当回转归向救主！<br/>','',57443,10978);
INSERT INTO stanza VALUES('Z699','3','你的罪，主必赦免，<br/>必永远不再记念。<br/>你的罪，主必赦免，<br/>必永远不再记念。<br/>你罪，主必全涂抹，<br/>如厚云灭没。<br/>你的罪，主必赦免，<br/>你的罪，主必赦免，<br/>必永远不再记念，<br/>必永远不再记念。<br/>','',57444,10979);
INSERT INTO stanza VALUES('Z700','1','若尽得世界，<br/>而失去救主，<br/>岂值得一日在此活着？<br/>在这些就要过去之物中，<br/>安息与安慰岂能寻得？<br/>若尽得世界，<br/>而失去救主，<br/>所得的一切够用一生？<br/>地上所有的快乐，<br/>也不能比<br/>那充满了主的生命！<br/>','',57445,10980);
INSERT INTO stanza VALUES('Z700','2','纵令你满得财富和爱情，<br/>无论远或近也都知名，<br/>前面仍无望，<br/>仍无一港口<br/>让你这惊船可以靠停。<br/>若尽得世界，<br/>而失去救主，<br/>就是那为你受死的主，<br/>是否这世界能供一避所，<br/>给你逃进去永远居住？<br/>','',57446,10981);
INSERT INTO stanza VALUES('Z700','3','何等的虚空！<br/>若没有救主：<br/>地上尽都是罪恶、苦难！<br/>永世何黑暗！<br/>若没有救主：<br/>黑夜与眼泪，<br/>痛苦无边！<br/>若没有救主，<br/>虽暂能活着，<br/>但到要死时，<br/>将要怎办？哦，<br/>必要面对那无主幽谷！<br/>且一直无主，<br/>直到永远！<br/>','',57447,10982);
INSERT INTO stanza VALUES('Z700','4','在主得一切，<br/>何等的快乐！<br/>何等能安抚伤痛心田！<br/>并无一罪过祂不肯赦免，<br/>也无一忧患祂不承担！<br/>若你只有主，<br/>只有主基督，<br/>全地除了祂，你无他物，<br/>那，在祂里面，<br/>你就有一切，<br/>应付你需要，无限丰富。<br/>','',57448,10983);
INSERT INTO stanza VALUES('Z701','1','日光下劳碌，有何益？<br/>令人厌，万事无新奇！<br/>一过去，无人再记忆！<br/>虚空的虚空！<br/>','',57449,10984);
INSERT INTO stanza VALUES('Z701','chorus','空空空！空空空！<br/>空空空！空空空！<br/>凡事都虚空，<br/>如捉影，如捕风。<br/>','',57450,10985);
INSERT INTO stanza VALUES('Z701','2','人生的经验是苦难：<br/>多有了智慧，多愁烦！<br/>增加了知识，增悲叹！<br/>虚空的虚空！<br/>','',57451,10986);
INSERT INTO stanza VALUES('Z701','3','富有与享受，有何效？<br/>纵你有妻子与财宝，<br/>也一样连累你烦恼！<br/>虚空的虚空！<br/>','',57452,10987);
INSERT INTO stanza VALUES('Z701','4','劳苦成愁苦，夜不安：<br/>你所得，即使不遭患，<br/>死来了，一切也是完！<br/>虚空的虚空！<br/>','',57453,10988);
INSERT INTO stanza VALUES('Z701','5','趁幼年，当念造你主！<br/>敬爱祂，才是乐与福！<br/>有了祂，心满意也足！<br/>惟祂不虚空！<br/>','',57454,10989);
INSERT INTO stanza VALUES('Z701','chorus','没有主，就虚空，<br/>有了主，就不空！<br/>凡事都虚空！<br/>惟有主，不虚空。<br/>','',57455,10990);
INSERT INTO stanza VALUES('Z702','1','多患难，常愁烦，<br/>劳苦负重担；<br/>人生充满悲伤、凄惨，<br/>叹息无平安。<br/>','',57456,10991);
INSERT INTO stanza VALUES('Z702','2','惟有主，惟有主，<br/>能解你愁苦；<br/>不要迟误，不要踌躇，<br/>来此得安抚。<br/>','',57457,10992);
INSERT INTO stanza VALUES('Z703','1','永远永远，永永远远！<br/>你要如何过此永远？<br/>当先解决这个问题，<br/>免得将来痛悔无及！<br/>得救、沉沦都是永远，<br/>你要如何过此永远？<br/>','',57458,10993);
INSERT INTO stanza VALUES('Z703','2','永远永远，永永远远！<br/>你要如何过此永远？<br/>多人现在拣选耶稣，<br/>离开他们一切罪途，<br/>相信救主，接受救恩，<br/>得了重生，亲近父神。<br/>','',57459,10994);
INSERT INTO stanza VALUES('Z703','3','永远永远，永永远远！<br/>你要如何过此永远？<br/>你若不入得救恩门，<br/>灭亡道上仍然驰奔，<br/>现在请你仔细思量，<br/>至终结局将要怎样？<br/>','',57460,10995);
INSERT INTO stanza VALUES('Z703','4','永远永远，永永远远！<br/>你要如何过此永远？<br/>是在天城看见主面？<br/>是在地狱受苦中间？<br/>极其严肃，极其要紧，<br/>一次定规，永远定准。<br/>','',57461,10996);
INSERT INTO stanza VALUES('Z703','5','永远永远，永永远远！<br/>你要如何过此永远？<br/>回头信主趁有光明，<br/>不被定罪，出死入生，<br/>你就可以欢然应说：<br/>我要永远住在神国。<br/>','',57462,10997);
INSERT INTO stanza VALUES('Z704','1','谁能免我死亡凶路？<br/>惟耶稣！惟耶稣！<br/>谁能除我地狱永苦？<br/>惟耶稣！<br/>不灭火，无期祸！<br/>谁能去我如此痛楚？<br/>惟耶稣！<br/>','',57463,10998);
INSERT INTO stanza VALUES('Z704','2','谁能引我生命荣途？<br/>惟耶稣！惟耶稣！<br/>谁能给我属天永福？<br/>惟耶稣！<br/>无死亡，无悲伤！<br/>谁能赐我如此丰富？<br/>惟耶稣！<br/>','',57464,10999);
INSERT INTO stanza VALUES('Z705','1','所有罪人都是罪囚，<br/>已中死亡毒钩；<br/>除信主是自有永有，<br/>必在罪中死休。<br/>神的儿子自有永有，<br/>惟祂能释罪囚，<br/>能使罪囚得着自由，<br/>自由直到永久。<br/>','',57465,11000);
INSERT INTO stanza VALUES('Z706','1','何等柔细慈爱，<br/>耶稣在呼召，<br/>呼召他，也呼召你！<br/>祂在天上等待，<br/>也来地寻找，<br/>寻找他，也寻找你！<br/>','',57466,11001);
INSERT INTO stanza VALUES('Z706','chorus','来家！来家！<br/>你这疲乏人，来家！<br/>何等恳切慈爱，<br/>耶稣在呼召，<br/>呼召你，罪人，来家！<br/>','',57467,11002);
INSERT INTO stanza VALUES('Z706','2','为何糊涂迟延，<br/>不听祂恳劝，<br/>恳劝他，也恳劝你？<br/>为何踌躇留恋，<br/>不理祂恩眷，<br/>恩眷他，也恩眷你？<br/>','',57468,11003);
INSERT INTO stanza VALUES('Z706','3','时间急急在逝，<br/>机会要越过，<br/>越过他，也越过你；<br/>阴影渐渐在集，<br/>死亡要来捉，<br/>来捉他，也来捉你。<br/>','',57469,11004);
INSERT INTO stanza VALUES('Z706','4','哦，那奇妙之爱，<br/>祂已经应许，<br/>应许他，也应许你；<br/>虽然污秽败坏，<br/>祂仍必怜恤，<br/>怜恤他，也怜恤你。<br/>','',57470,11005);
INSERT INTO stanza VALUES('Z707','1','我听我的救主吩咐：<br/>『跟从我，跟从我，<br/>跟从我；』<br/>祂的声音终日招呼：<br/>『跟从我，跟从我，<br/>跟从我；<br/>为你，我走艰辛路途，<br/>为你，我曾性命不顾，<br/>并尝苦胆免你重负，<br/>跟从我，跟从我，<br/>跟从我。<br/>','',57471,11006);
INSERT INTO stanza VALUES('Z707','2','你虽有罪，我必宽宥，<br/>跟从我，跟从我，<br/>跟从我；<br/>脱离捆绑，你必自由，<br/>跟从我，跟从我，<br/>跟从我；<br/>人事变动不甚长久，<br/>我作你神引导无休，<br/>作你喜乐直至千秋，<br/>跟从我，跟从我，<br/>跟从我。<br/>','',57472,11007);
INSERT INTO stanza VALUES('Z707','3','带你罣虑到我这里，<br/>跟从我，跟从我，<br/>跟从我；<br/>你的重担放我手臂，<br/>跟从我，跟从我，<br/>跟从我；<br/>你的疑惧息我胸臆，<br/>你的将来向我依倚，<br/>我必亲手拭你泪滴，<br/>跟从我，跟从我，<br/>跟从我。』<br/>','',57473,11008);
INSERT INTO stanza VALUES('Z708','1','耶稣发慈声要召你回来，<br/>今日召你，今日召你！<br/>为何仍迷蒙，<br/>远离主慈怀，<br/>终日流荡在苦地？<br/>','',57474,11009);
INSERT INTO stanza VALUES('Z708','chorus','今日召你！今日召你！<br/>耶稣今召你，<br/>今日发慈声呼召你！<br/>','',57475,11010);
INSERT INTO stanza VALUES('Z708','2','耶稣在呼召劳者来得息，<br/>今日召你，今日召你！<br/>重担卸给祂，<br/>无倚成有倚，<br/>祂要欢迎不绝弃。<br/>','',57476,11011);
INSERT INTO stanza VALUES('Z708','3','耶稣在等待你来得赦免，<br/>今日等你，今日等你！<br/>可带你罪来，<br/>俯伏主脚前；<br/>现在就来莫迟疑！<br/>','',57477,11012);
INSERT INTO stanza VALUES('Z708','4','耶稣仍呼召，<br/>何不就听从？今日听祂，今日听祂！<br/>来求告祂名，<br/>蒙恩必无穷；<br/>祂要赐福无复加。<br/>','',57478,11013);
INSERT INTO stanza VALUES('Z709','1','无论何人愿意，<br/>就可得救恩，<br/>这是天上来的佳音<br/>给罪人；<br/>赶快将这信息<br/>向万人宣陈：<br/>无论何人都可来。<br/>','',57479,11014);
INSERT INTO stanza VALUES('Z709','chorus','『无论甚么人，<br/>无论甚么人，』<br/>这是慈爱天父<br/>唤浪子回家；<br/>『无论老幼、男妇，<br/>都不必代价，<br/>无论甚么人可来。』<br/>','',57480,11015);
INSERT INTO stanza VALUES('Z709','2','无论何人想来，<br/>不必稍迟延；<br/>恩门已经大开，<br/>进者可随便；<br/>耶稣真是救主，<br/>祂已发恩言：<br/>无论何人都可来。<br/>','',57481,11016);
INSERT INTO stanza VALUES('Z709','3','无论何人愿意，<br/>就可得永生；<br/>无论何人愿意，<br/>这话语有征；<br/>无论何人愿意，<br/>这应许无更，<br/>无论何人都可来。<br/>','',57482,11017);
INSERT INTO stanza VALUES('Z710','1','叩门，叩门，谁在外？<br/>等着，等着，何忍耐！<br/>远来佳客君尊气概，<br/>生平未见这丰采；<br/>我的心阿，既感奇哉，<br/>何不立即把门开？<br/>','',57483,11018);
INSERT INTO stanza VALUES('Z710','2','叩门，叩门，还在外！<br/>等着，等着，真忍耐！<br/>但是这门还是难开，<br/>因有蔓草和藤艾，<br/>重重缠塞，层层阻碍，<br/>金已生锈，木已坏。<br/>','',57484,11019);
INSERT INTO stanza VALUES('Z710','3','叩门，叩门，仍在外！<br/>等着，等着，太忍耐！<br/>被钉之手连叩不怠，<br/>荆棘冠冕似仍戴，<br/>目中仍露请求之爱，<br/>原是救主等门开。<br/>','',57485,11020);
INSERT INTO stanza VALUES('Z711','1','听阿，救主叩门，叩门，<br/>不住叩心门！<br/>为何你仍硬心，硬心，<br/>不理这声音？<br/>火速起来开心门，<br/>火速请祂进；<br/>祂要进入你心，你心，<br/>赐给你救恩。<br/>','',57486,11021);
INSERT INTO stanza VALUES('Z711','chorus','请主进！请主进！<br/>祂在心外叩门；<br/>请主进！哦，请主进！<br/>祂必进你心。<br/>','',57487,11022);
INSERT INTO stanza VALUES('Z711','2','请听祂说：<br/>『罪人，罪人，<br/>就我得安息；<br/>我曾为你舍身，舍身，<br/>死在髑髅地；<br/>为要使你蒙恩宠，<br/>流血将你买；<br/>你罪虽像朱红，朱红，<br/>也能变雪白。』<br/>','',57488,11023);
INSERT INTO stanza VALUES('Z711','3','为何你仍犹豫，犹豫，<br/>让主等门外？<br/>要知机会一去，一去，<br/>永远不再来！<br/>祂既对你满恩情，<br/>莫把祂心伤；<br/>祂愿赐你生命，生命，<br/>何必等死亡？<br/>','',57489,11024);
INSERT INTO stanza VALUES('Z711','4','如果你仍迟延，迟延，<br/>终必有一天，<br/>懊悔为时已晚，已晚，<br/>哀呼主眷怜；<br/>那时恩门已经关，<br/>哀呼必徒然！<br/>为何不趁今天，今天，<br/>请主进心间？<br/>','',57490,11025);
INSERT INTO stanza VALUES('Z712','1','百只羊，少了一口，<br/>良牧耶稣悲愁，<br/>不顾山路崎岖难走，<br/>冒险前往寻救。<br/>迷羊回头！迷羊回头！<br/>前面尽是陷阱、猛兽；<br/>火速回来，勿再逗遛！<br/>','',57491,11026);
INSERT INTO stanza VALUES('Z713','1','失迷的羊，你今在那里？<br/>救主今天正在寻找你！<br/>一百只羊内中缺一只，<br/>莫非就是你？<br/>','',57492,11027);
INSERT INTO stanza VALUES('Z713','chorus','莫非就是你？<br/>莫非就是你？<br/>一百只羊内中缺一只，<br/>莫非就是你？<br/>','',57493,11028);
INSERT INTO stanza VALUES('Z713','2','失落的人，你今在那里？<br/>圣灵今天正在寻找你！<br/>十块银钱内中缺一块，<br/>莫非就是你？<br/>','',57494,11029);
INSERT INTO stanza VALUES('Z713','chorus','莫非就是你？<br/>莫非就是你？<br/>十块银钱内中缺一块，<br/>莫非就是你？<br/>','',57495,11030);
INSERT INTO stanza VALUES('Z713','3','浪荡的人，你有无安息？<br/>家中快乐正在需要你！<br/>天父在家整天巴望的，<br/>莫非就是你？<br/>','',57496,11031);
INSERT INTO stanza VALUES('Z713','chorus','莫非就是你？<br/>莫非就是你？<br/>天父在家整天巴望的，<br/>莫非就是你？<br/>','',57497,11032);
INSERT INTO stanza VALUES('Z714','1','此时当就耶稣，<br/>耶稣在此；<br/>不可再行死路，<br/>耶稣在此；<br/>众人拢总当来，<br/>时日机会不再，<br/>不可迟延等待，<br/>耶稣在此。<br/>','',57498,11033);
INSERT INTO stanza VALUES('Z714','2','此时当就耶稣，<br/>耶稣在此；<br/>不可因循自误，<br/>耶稣在此；<br/>救主欢喜施恩，<br/>救你免得沦沉；<br/>不可再恋红尘，<br/>耶稣在此。<br/>','',57499,11034);
INSERT INTO stanza VALUES('Z714','3','此时当就耶稣，<br/>耶稣在此；<br/>不可疑惑踌躇，<br/>耶稣在此；<br/>罪恶虽然极重，<br/>救主仍然爱钟；<br/>不必绝望惶恐，<br/>耶稣在此。<br/>','',57500,11035);
INSERT INTO stanza VALUES('Z714','4','此时当就耶稣，<br/>耶稣在此；<br/>天下再无别路，<br/>耶稣在此；<br/>救主成功救赎，<br/>救主尚在招呼；<br/>你当火速就主，<br/>耶稣在此。<br/>','',57501,11036);
INSERT INTO stanza VALUES('Z715','1','你堕落罪恶境，<br/>历尽了苦情，<br/>为何不立悔改，<br/>脱此苦境？<br/>邪路上你在行，<br/>前面多陷阱，<br/>不回头，势难免，<br/>堕入深坑！<br/>','',57502,11037);
INSERT INTO stanza VALUES('Z715','chorus','主渴望拯救你！<br/>主等候救你！<br/>为何不趁今天让主救你？<br/>','',57503,11038);
INSERT INTO stanza VALUES('Z715','2','恶者手你安卧，<br/>被任意加祸，<br/>你虽想，却不能<br/>脱他掌握；<br/>他摆布，他弄捉，<br/>使你受困惑，<br/>如鱼鸟被圈捕，<br/>难逃网罗！<br/>','',57504,11039);
INSERT INTO stanza VALUES('Z715','3','残岁月，增却减！<br/>人生像云烟！<br/>怎能知，朝夕间<br/>不会消散？<br/>死亡后，有审判！<br/>地狱又紧联！<br/>你如何能逃避<br/>永火烈焰？<br/>','',57505,11040);
INSERT INTO stanza VALUES('Z715','4','主受死，把魔伤，<br/>并将罪担当，<br/>又复活，升天上，<br/>作主作王；<br/>死亡废，生命彰，<br/>你可得释放，<br/>何必再受捆绑，<br/>等待沦亡？<br/>','',57506,11041);
INSERT INTO stanza VALUES('Z715','5','你虽然使主忧，<br/>祂仍愿拯救，<br/>祂忍耐，祂渴望，<br/>等你回头；<br/>你虽然拒不受，<br/>祂仍在等候，<br/>祂等候你悔改，<br/>相信得救。<br/>','',57507,11042);
INSERT INTO stanza VALUES('Z716','1','耶稣今留步，<br/>要等候你来，<br/>祂已等候好久长；<br/>祂这样等候，<br/>是望你悔改，<br/>得享永生免灭亡。<br/>','',57508,11043);
INSERT INTO stanza VALUES('Z716','chorus','欢迎你来，你来，<br/>无论甚么人，<br/>这是救主的呼召；<br/>祂能、祂肯、祂等，<br/>等着施救恩，<br/>不过只要你信靠。<br/>','',57509,11044);
INSERT INTO stanza VALUES('Z716','2','你虽然不羁，<br/>流荡已经远，<br/>沉溺罪中已经深，<br/>祂仍然等候，<br/>忍耐着申劝，<br/>要得你这疲倦人。<br/>','',57510,11045);
INSERT INTO stanza VALUES('Z716','3','你虽已多次拒祂的恩召，<br/>多次使祂空眷顾，<br/>祂的爱不因你冷落生恼，<br/>今又向你来催促。<br/>','',57511,11046);
INSERT INTO stanza VALUES('Z716','4','你应当服降，<br/>服降这个爱，<br/>耶稣现在等候你；<br/>祂既仍招呼：<br/>『请你就我来！』<br/>你当回应：『我愿意。』<br/>','',57512,11047);
INSERT INTO stanza VALUES('Z717','1','被罪压害人人请来，<br/>被罪压害人人要来，<br/>救主在此等待；<br/>祂要救你，安你心怀，<br/>只要你肯信祂。<br/>','',57513,11048);
INSERT INTO stanza VALUES('Z717','chorus','只要信祂！只要信祂！<br/>现在要信祂！<br/>祂要救你！祂要救你！<br/>现在要救你！<br/>','',57514,11049);
INSERT INTO stanza VALUES('Z717','2','耶稣替你钉死十架，<br/>流血作你赎价；<br/>救赎已成不用代价，<br/>只要你肯信祂。<br/>','',57515,11050);
INSERT INTO stanza VALUES('Z717','3','耶稣对你满有慈爱，<br/>恩门为你大开；<br/>机会一过未必再来，<br/>请你快来信祂。<br/>','',57516,11051);
INSERT INTO stanza VALUES('Z717','chorus','快来信祂！快来信祂！<br/>现在快信祂！<br/>祂能救你！祂能救你！<br/>现在能救你！<br/>','',57517,11052);
INSERT INTO stanza VALUES('Z717','4','不久离世，结局怎样，<br/>得救或是灭亡？<br/>永生何乐！永死难当！<br/>请你快来信祂。<br/>','',57518,11053);
INSERT INTO stanza VALUES('Z718','1','哦，不要弃绝主恩道，<br/>也不要闭目拒光照；<br/>亲爱的，切莫心硬着！<br/>得救当趁早！<br/>','',57519,11054);
INSERT INTO stanza VALUES('Z718','chorus','何必再迟延？<br/>何必再迟延？<br/>你要得救援，<br/>何必再迟延？<br/>','',57520,11055);
INSERT INTO stanza VALUES('Z718','2','明天的太阳不一定<br/>还照你受欺的眼睛；<br/>今夜是时机！该聪明！<br/>要信，何必等！<br/>','',57521,11056);
INSERT INTO stanza VALUES('Z718','chorus','何不趁今夜？<br/>何不趁今夜？<br/>你要免罪孽，<br/>何不趁今夜？<br/>','',57522,11057);
INSERT INTO stanza VALUES('Z718','3','这世界有何可留恋？<br/>不会有新事，纯又甜；<br/>请你来尝尝主恩典！<br/>要来，趁今天！<br/>副)<br/>何不趁今天？<br/>何不趁今天？<br/>你要蒙恩典，<br/>何不趁今天？<br/>','',57523,11058);
INSERT INTO stanza VALUES('Z718','4','我们的恩主满慈仁，<br/>从未曾拒绝人来信；<br/>祂总是立刻施救恩！<br/>信罢，请放心！<br/>','',57524,11059);
INSERT INTO stanza VALUES('Z718','chorus','信罢，趁现在！<br/>时过，不再来！<br/>要信，何须待？<br/>时过，不再来！<br/>','',57525,11060);
INSERT INTO stanza VALUES('Z719','1','你若愿意脱离罪的苦情，<br/>让基督来进入你心；<br/>你若渴慕得着新的人生，<br/>让基督来进入你心。<br/>','',57526,11061);
INSERT INTO stanza VALUES('Z719','chorus','现在，将疑惑抛弃；<br/>现在，将救主投倚；<br/>现在，将心门开启；<br/>让基督来进入你心。<br/>','',57527,11062);
INSERT INTO stanza VALUES('Z719','2','若觉恶性，<br/>自己不能治服，<br/>让基督来进入你心；<br/>若感虚空，<br/>世界不能满足，<br/>让基督来进入你心。<br/>','',57528,11063);
INSERT INTO stanza VALUES('Z719','3','若要黑暗变成无上光明，<br/>让基督来进入你心；<br/>若要病痛转为永久康宁，<br/>让基督来进入你心。<br/>','',57529,11064);
INSERT INTO stanza VALUES('Z719','4','若要心中充满快乐欢喜，<br/>让基督来进入你心；<br/>若要全人进入平静安息，<br/>让基督来进入你心。<br/>','',57530,11065);
INSERT INTO stanza VALUES('Z720','1','仰望耶稣，将亡人！<br/>望就活！望就活！<br/>仰望救主已舍身，<br/>望就活！<br/>看祂木上被举着，<br/>望就活！望就活！<br/>听祂在说：『仰望我！』<br/>望就活！<br/>','',57531,11066);
INSERT INTO stanza VALUES('Z720','chorus','看哪！救主举木上，<br/>仰望救主医死伤；<br/>望就活了！何必亡？<br/>望就活！<br/>','',57532,11067);
INSERT INTO stanza VALUES('Z720','2','你虽邪恶又污秽，<br/>望就活！望就活！<br/>如望，就必脱众罪，<br/>望就活！<br/>久受撒但的捆绑，<br/>望就活！望就活！<br/>一望，就必得释放，<br/>望就活！<br/>','',57533,11068);
INSERT INTO stanza VALUES('Z720','3','你虽流荡已久远，<br/>望就活！望就活！<br/>却莫硬心在今天，<br/>望就活！<br/>救主巴望你回转！<br/>望就活！望就活！<br/>为何忍心仍迟延？<br/>望就活！<br/>','',57534,11069);
INSERT INTO stanza VALUES('Z721','1','贫穷、软弱、悲伤、<br/>忧愁，<br/>亲爱罪人请你来！<br/>耶稣等着要施拯救，<br/>满了能力和怜爱；<br/>祂能救你！祂能救你！<br/>祂肯救你，莫疑猜。<br/>','',57535,11070);
INSERT INTO stanza VALUES('Z721','2','祂要欢迎，来罢，放心，<br/>祂不弃绝任何人；<br/>实在懊悔，实在相信，<br/>你就必定能蒙恩；<br/>不用代价！不用代价！<br/>就可进入得救门。<br/>','',57536,11071);
INSERT INTO stanza VALUES('Z721','3','莫让良心使你徘徊，<br/>或想怎样才配来；<br/>你已『配来』，<br/>若你理会：<br/>你是需要祂的爱；<br/>无别条件！无别条件！<br/>恩门是为罪人开。<br/>','',57537,11072);
INSERT INTO stanza VALUES('Z721','4','你心烦闷，你心悒怏，<br/>疲倦、痛苦、常失败；<br/>如果你要等到改良，<br/>你就永远不会来；<br/>耶稣钉死，耶稣钉死，<br/>是为罪人赎罪债。<br/>','',57538,11073);
INSERT INTO stanza VALUES('Z721','5','请你想起客西马尼，<br/>救主如何流血汗！<br/>请你听祂在髑髅地，<br/>如何临死大声喊：<br/>『已经成了！』<br/>『已经成了！』<br/>罪人你今能无感？<br/>','',57539,11074);
INSERT INTO stanza VALUES('Z721','6','祂的流血已经满足<br/>你神公义的要求；<br/>应当信服，完全信服，<br/>罪过就都得免宥；<br/>惟有耶稣，惟有耶稣，<br/>能作罪人的朋友。<br/>','',57540,11075);
INSERT INTO stanza VALUES('Z722','1','飘渺人生何短暂，<br/>好似浮云现即散，<br/>又似幻梦醒就完：<br/>要及时！<br/>时日飞逝在宣言：<br/>转瞬就到死亡线，<br/>再迟必在地狱间：<br/>要及时！<br/>','',57541,11076);
INSERT INTO stanza VALUES('Z722','chorus','要及时！要及时！<br/>当今耶稣在召唤：<br/>要及时！<br/>若在罪中仍流连，<br/>只怕恩门向你关，<br/>那时呼救已太晚：<br/>要及时！<br/>','',57542,11077);
INSERT INTO stanza VALUES('Z722','2','谁是智者，该想看：<br/>鲜花朝艳暮凋残，<br/>英年要去何能挽？<br/>要及时！<br/>哦，我求你早打算，<br/>免得过了死亡线，<br/>全人丧在地狱间：<br/>要及时！<br/>','',57543,11078);
INSERT INTO stanza VALUES('Z722','3','圣灵仍在把你感，<br/>时常与你来争战，<br/>何不降服得平安？<br/>要及时！<br/>救主等候赐恩典，<br/>愿意救你免悲惨；<br/>你若踌躇何愚顽！<br/>要及时！<br/>','',57544,11079);
INSERT INTO stanza VALUES('Z722','4','罪人，请听我忠言，<br/>莫把救恩视等闲，<br/>速把救主来拣选：<br/>要及时！<br/>来投耶稣怀里面，<br/>来接基督进心间，<br/>来就救主趁今天：<br/>要及时！<br/>','',57545,11080);
INSERT INTO stanza VALUES('Z723','1','耶稣恩主是人惟一需要：<br/>祂是神成肉身生于马槽，<br/>在世为人历尽万般苦恼，<br/>末了被钉木架，<br/>为救你将命倾倒。<br/>','',57546,11081);
INSERT INTO stanza VALUES('Z723','chorus','需要耶稣！需要耶稣！<br/>人人都需要耶稣！<br/>要脱罪担需要主，<br/>要得平安需要主，<br/>要免沉沦得永生，<br/>你需要耶稣！<br/>','',57547,11082);
INSERT INTO stanza VALUES('Z723','2','祂已复活，<br/>升天永作中保，<br/>差遣圣灵下来将你寻找；<br/>你若来信，<br/>将祂尊名求告，<br/>祂必赐你恩典，<br/>满足你一切需要。<br/>','',57548,11083);
INSERT INTO stanza VALUES('Z723','3','你心虽暗，<br/>祂能彻底光照；<br/>你罪虽多，<br/>祂必全都宽饶；<br/>祂血能将你的污秽除掉；<br/>祂灵必赐生命，<br/>来将你软弱尽消。<br/>','',57549,11084);
INSERT INTO stanza VALUES('Z723','4','你的人生常感有所缺少；<br/>有一需要，<br/>你尚莫名其妙；<br/>你这需要，<br/>惟从耶稣得到：<br/>祂能满足你心，<br/>除去你虚空无聊。<br/>','',57550,11085);
INSERT INTO stanza VALUES('Z723','chorus','需要耶稣！需要耶稣！<br/>人人都需要耶稣！<br/>要免虚空需要主，<br/>要得满足需要主！<br/>要使人生有意义，<br/>你需要耶稣！<br/>','',57551,11086);
INSERT INTO stanza VALUES('Z723','5','人在世上，<br/>尽是劳苦烦恼；<br/>遭遇困苦，<br/>又是无求无告；<br/>世事虚谎，<br/>还有甚么可靠？<br/>这些都是说出：<br/>耶稣是人的需要！<br/>','',57552,11087);
INSERT INTO stanza VALUES('Z723','6','世人不分智愚、<br/>男女、老少，<br/>都已犯罪，<br/>亏缺神的荣耀；<br/>除信耶稣，<br/>别无得救之道，<br/>因为惟有耶稣<br/>能满足神、人需要。<br/>','',57553,11088);
INSERT INTO stanza VALUES('Z724','1','照我本相，无善足称，<br/>惟你流血，替我受惩，<br/>并且召我就你得生；<br/>救主耶稣，我来！我来！<br/>','',57554,11089);
INSERT INTO stanza VALUES('Z724','2','照我本相，不必等到<br/>自己改变比前更好，<br/>因你宝血除罪可靠；<br/>救主耶稣，我来！我来！<br/>','',57555,11090);
INSERT INTO stanza VALUES('Z724','3','照我本相，反复不定，<br/>疑信参半，如浪不平，<br/>内有罣虑，外有恶行；<br/>救主耶稣，我来！我来！<br/>','',57556,11091);
INSERT INTO stanza VALUES('Z724','4','照我本相，<br/>贫、瞎、可怜；<br/>我真需要你的恩典，<br/>感我恶心，开我盲眼；<br/>救主耶稣，我来！我来！<br/>','',57557,11092);
INSERT INTO stanza VALUES('Z724','5','照我本相，你肯收留，<br/>赐我生命，赦我愆尤，<br/>你既应许，必定成就；<br/>救主耶稣，我来！我来！<br/>','',57558,11093);
INSERT INTO stanza VALUES('Z725','1','脱离捆绑、忧愁与黑影，<br/>耶稣，我来！<br/>耶稣，我来！<br/>进入自由、喜乐与光明，<br/>耶稣，我来就你！<br/>脱离疾病，进入你健全；<br/>脱离贫乏，进入你富源；<br/>脱离罪恶，进入你救援，<br/>耶稣，我来就你！<br/>','',57559,11094);
INSERT INTO stanza VALUES('Z725','2','脱离失败羞耻的结果，<br/>耶稣，我来！<br/>耶稣，我来！<br/>进入十架荣耀的收获，<br/>耶稣，我来就你！<br/>脱离痛苦，进入你安宁；<br/>脱离风波，进入你平静；<br/>脱离怨叹，进入你诵称，<br/>耶稣，我来就你！<br/>','',57560,11095);
INSERT INTO stanza VALUES('Z725','3','脱离狂傲不平的血气，<br/>耶稣，我来！<br/>耶稣，我来！<br/>进入完全有福的旨意，<br/>耶稣，我来就你！<br/>脱离自己，住在你爱里；<br/>脱离绝望，等候你来提，<br/>离地上腾，如鹰展双翼，<br/>耶稣，我来就你！<br/>','',57561,11096);
INSERT INTO stanza VALUES('Z725','4','脱离撒但死亡的权势，<br/>耶稣，我来！<br/>耶稣，我来！<br/>进入基督生命的恩赐，<br/>耶稣，我来就你！<br/>脱离败坏无底的深渊，<br/>进入护庇安歇的家园，<br/>永永远远瞻仰你荣颜，<br/>耶稣，我来就你！<br/>','',57562,11097);
INSERT INTO stanza VALUES('Z726','1','你的欢迎声音，<br/>召我前来相信，<br/>因你为我已流宝血，<br/>特要洗我良心。<br/>','',57563,11098);
INSERT INTO stanza VALUES('Z726','chorus','主，我来就你！<br/>我今来就你！<br/>求主用血将我洗，<br/>使我干净无比。<br/>','',57564,11099);
INSERT INTO stanza VALUES('Z726','2','我真污秽可鄙，<br/>行善一无能力；<br/>但你欢喜赐恩帮助，<br/>并除一切恶迹。<br/>','',57565,11100);
INSERT INTO stanza VALUES('Z726','3','你今郑重吩咐，<br/>要我远离罪俗，<br/>虚心悔改，实心相信，<br/>接受你作救主。<br/>','',57566,11101);
INSERT INTO stanza VALUES('Z726','4','神用恩言呼召，<br/>又用圣灵光照，<br/>使我知道自己不堪，<br/>知道救主可靠。<br/>','',57567,11102);
INSERT INTO stanza VALUES('Z726','5','圣灵今在我灵，<br/>证明我有生命；<br/>神的应许已经应验，<br/>若我已信祂名。<br/>','',57568,11103);
INSERT INTO stanza VALUES('Z726','6','奇哉！神爱罪人！<br/>妙哉！神有救恩！<br/>美哉！耶稣流血赎罪！<br/>我愿献上全身。<br/>','',57569,11104);
INSERT INTO stanza VALUES('Z727','1','我今来就主十架，<br/>既软弱而又贫、瞎；<br/>世上事尽都空虚，<br/>惟主恩是我所需。<br/>','',57570,11105);
INSERT INTO stanza VALUES('Z727','chorus','我今来投靠救主，<br/>十架下谦卑俯伏，<br/>求耶稣，神的羔羊，<br/>拯救我脱离灭亡。<br/>','',57571,11106);
INSERT INTO stanza VALUES('Z727','2','我久慕救主恩典，<br/>罪却在我心掌权；<br/>今闻主柔声说道：<br/>『你罪孽，我必除掉。』<br/>','',57572,11107);
INSERT INTO stanza VALUES('Z727','3','主已来充满我心，<br/>并将我一切更新；<br/>祂宝血洗我罪愆，<br/>祂救赎使我完全。<br/>','',57573,11108);
INSERT INTO stanza VALUES('Z727','chorus','感谢主，我已蒙恩，<br/>罪得赦，喜乐满心；<br/>赞美主，我已得救，<br/>眼明亮，愿跟主走。<br/>','',57574,11109);
INSERT INTO stanza VALUES('Z727','4','我在此献上所有：<br/>灵、魂、体、<br/>亲人、挚友，<br/>智与力、财物、时间，<br/>全归主直到永远。<br/>','',57575,11110);
INSERT INTO stanza VALUES('Z728','1','谁在流荡远离天父？<br/>为何不回家？<br/>活在罪中，终日痛苦，<br/>何不就回家？<br/>','',57576,11111);
INSERT INTO stanza VALUES('Z728','chorus','回家罢！回家罢！<br/>不要再流荡！<br/>慈爱天父等你回家，<br/>整天在巴望！<br/>','',57577,11112);
INSERT INTO stanza VALUES('Z728','2','我已流荡，远离天父，<br/>现在要回家；<br/>走过好长罪恶道路，<br/>主，我要回家。<br/>','',57578,11113);
INSERT INTO stanza VALUES('Z728','chorus','要回家！要回家！<br/>不愿再流荡！<br/>现在我要回到父家，<br/>永住父身旁！<br/>','',57579,11114);
INSERT INTO stanza VALUES('Z728','3','多年浪费宝贵岁月，<br/>现在要回家；<br/>今天懊悔，流泪、悲切，<br/>主，我要回家。<br/>','',57580,11115);
INSERT INTO stanza VALUES('Z728','4','流荡、犯罪，我已疲乏，<br/>现在要回家；<br/>投靠你爱，相信你话，<br/>主，我要回家。<br/>','',57581,11116);
INSERT INTO stanza VALUES('Z728','5','我魂衰残，我心悲伤，<br/>现在要回家；<br/>加我力量，复我盼望，<br/>主，我要回家。<br/>','',57582,11117);
INSERT INTO stanza VALUES('Z729','1','耶稣，我人的爱人，<br/>你怀让我来藏身；<br/>惊波，骇涛滚滚近！<br/>狂风暴雨阵阵紧！<br/>藏我！哦，主，求藏我！<br/>直到今生风波过！<br/>引我安全到路尽，<br/>至终求接我灵魂！<br/>','',57583,11118);
INSERT INTO stanza VALUES('Z729','2','别无避所能藏隐，<br/>无助之人托你身；<br/>不！哦，不要丢弃我！<br/>扶持、安慰，望无辍：<br/>所有倚靠寄你身，<br/>所有救助由你临；<br/>头无遮护身无蔽，<br/>求你圣翼来覆庇。<br/>','',57584,11119);
INSERT INTO stanza VALUES('Z729','3','主阿，你是我所需，<br/>够我一切还有余：<br/>仆，你扶起；弱，你保；<br/>病，你医治；瞽，你导；<br/>你名至义至圣洁，<br/>我全不义满罪孽；<br/>我是邪恶没良善，<br/>恩典、真理你充满。<br/>','',57585,11120);
INSERT INTO stanza VALUES('Z729','4','你前我遇恩浩瀚，<br/>赦我众罪之恩典；<br/>医治活水望涌流，<br/>洁我衷里并保守；<br/>你是永远生命源，<br/>望在我心成活泉，<br/>从我里头来涌流，<br/>一直涌流到永久。<br/>','',57586,11121);
INSERT INTO stanza VALUES('Z730','1','听阿！罪人，慈声何高！<br/>救主在呼召；<br/>当祂正把多人寻找，<br/>莫让祂漏掉！<br/>','',57587,11122);
INSERT INTO stanza VALUES('Z730','chorus','罪人！罪人！<br/>听主在呼召；<br/>当祂正把多人寻找，<br/>莫让祂漏掉！<br/>','',57588,11123);
INSERT INTO stanza VALUES('Z730','2','莫我，救主，莫我漏掉！<br/>听我恭求告！<br/>当你正把别人呼召，<br/>莫把我漏掉！<br/>','',57589,11124);
INSERT INTO stanza VALUES('Z730','chorus','救主！救主！<br/>听我恭求告！<br/>当你正把别人呼召，<br/>莫把我漏掉！<br/>','',57590,11125);
INSERT INTO stanza VALUES('Z730','3','让我在你施恩座前，<br/>从你得救恩；<br/>俯伏痛悔，承认罪愆，<br/>求你助我信。<br/>','',57591,11126);
INSERT INTO stanza VALUES('Z730','4','单单靠赖十架功能，<br/>我寻求你面；<br/>医我伤痛、破碎心、灵，<br/>救我用恩典。<br/>','',57592,11127);
INSERT INTO stanza VALUES('Z730','5','你是我的安慰源头，<br/>于我比命贵；<br/>除你之外，在地何投？<br/>在天何所归？<br/>','',57593,11128);
INSERT INTO stanza VALUES('Z731','1','永久磐石为我开，<br/>让我藏身在你怀；<br/>愿你所流血与水，<br/>解决我的双重罪：<br/>赎我免去牠永刑，<br/>救我脱离牠权能。<br/>','',57594,11129);
INSERT INTO stanza VALUES('Z731','2','纵我双手不罢休，<br/>不能满足你要求；<br/>纵我热心能持久，<br/>纵我眼泪永远流，<br/>仍不足以赎愆尤；<br/>必须你来施拯救。<br/>','',57595,11130);
INSERT INTO stanza VALUES('Z731','3','空空两手无代价，<br/>单单投靠你十架！<br/>赤身，就你求衣衫；<br/>无助，望你赐恩典；<br/>污秽，飞奔你泉旁，<br/>主阿，洗我，否则亡。<br/>','',57596,11131);
INSERT INTO stanza VALUES('Z731','4','当我此生年日逝，<br/>当我临终闭目时，<br/>当我飞进永世间，<br/>当我到你宝座前，<br/>永久磐石为我开，<br/>让我藏身在你怀。<br/>','',57597,11132);
INSERT INTO stanza VALUES('Z732','1','你曾离天庭，<br/>撇弃宝座和荣冕，<br/>为救我竟甘愿来世间；<br/>但在伯利恒，<br/>并无一家房空闲，<br/>备接你降生到里面。<br/>','',57598,11133);
INSERT INTO stanza VALUES('Z732','chorus','哦，来我心中，主耶稣！<br/>在我心有空房为着你；<br/>哦，来我心中，<br/>主耶稣！来！<br/>在我心有空房为你。<br/>','',57599,11134);
INSERT INTO stanza VALUES('Z732','2','天使赞高声，<br/>天上众军也响应，<br/>乐宣告你身位，君尊荣；<br/>但你来地上，<br/>出生寒门，无佳形，<br/>陋城中生长，无人重。<br/>','',57600,11135);
INSERT INTO stanza VALUES('Z732','3','狐狸尚有洞，<br/>飞鸟亦有其窝巢，<br/>山谷中，树林内，<br/>任逍遥；<br/>你无枕头地，<br/>终日飘泊犹太郊，<br/>加利利野地宿荒草。<br/>','',57601,11136);
INSERT INTO stanza VALUES('Z732','4','哦，主，你来此，<br/>带生命之恩言，<br/>好释放你子民脱苦难；<br/>他们却侮慢，<br/>戏弄且加荆棘冕，<br/>终将你置于受难山。<br/>','',57602,11137);
INSERT INTO stanza VALUES('Z732','5','天上还要响，<br/>天使更要赞高声，<br/>欢颂你来得胜，至威荣；<br/>愿你那时候，<br/>将我提接并说明：<br/>『我身边有房备你用！』<br/>','',57603,11138);
INSERT INTO stanza VALUES('Z732','chorus','我心要欢畅，<br/>主耶稣！<br/>你来时要召我到身边；<br/>哦，愿你快来！<br/>主耶稣！来！<br/>快将我接到你身边。<br/>','',57604,11139);
INSERT INTO stanza VALUES('Z733','1','来进入我心，主耶稣！<br/>我今愿悔改相信；<br/>我心感觉虚空、孤独，<br/>现在来进入我心！<br/>','',57605,11140);
INSERT INTO stanza VALUES('Z733','chorus','进入我心！进入我心！<br/>来进入我心，主耶稣！<br/>求你现今进来施恩，<br/>来进入我心，主耶稣！<br/>','',57606,11141);
INSERT INTO stanza VALUES('Z733','2','来进入我心，主耶稣，<br/>向我施行你救恩；<br/>救我脱离罪的痛苦，<br/>现在来进入我心！<br/>','',57607,11142);
INSERT INTO stanza VALUES('Z733','3','来进入我心，主耶稣！<br/>将我全人都更新；<br/>生命之灵进来居住，<br/>现在就进入我心。<br/>','',57608,11143);
INSERT INTO stanza VALUES('Z734','1','罪恶全洗净，<br/>肉体都脱清，<br/>接受基督作我的救主；<br/>撒但已无能，<br/>世界也失形，<br/>接受基督作我的救主。<br/>','',57609,11144);
INSERT INTO stanza VALUES('Z734','chorus','接受！接受！<br/>相信接受，不再延误；<br/>接受！接受！<br/>接受基督作我的救主。<br/>','',57610,11145);
INSERT INTO stanza VALUES('Z734','2','生命大改变，<br/>灵里极有能，<br/>接受基督作我的生命！<br/>心中满平安，<br/>前途尽光明，<br/>接受基督作我的生命。<br/>','',57611,11146);
INSERT INTO stanza VALUES('Z734','chorus','接受！接受！<br/>虚心接受，一无刚硬；<br/>接受！接受！<br/>接受基督作我的生命。<br/>','',57612,11147);
INSERT INTO stanza VALUES('Z734','3','疾病得医治，<br/>软弱也退却，<br/>接受基督作我的医生；<br/>痛苦已息止，<br/>死亡被吞灭，<br/>接受基督作我的医生。<br/>','',57613,11148);
INSERT INTO stanza VALUES('Z734','chorus','接受！接受！<br/>满心接受，疑惧除净；<br/>接受！接受！<br/>接受基督作我的医生。<br/>','',57614,11149);
INSERT INTO stanza VALUES('Z734','4','叹息变歌唱，<br/>喜乐代忧伤，<br/>接受基督作我的君王；<br/>天国我所享，<br/>荣耀也在望，<br/>接受基督作我的君王。<br/>','',57615,11150);
INSERT INTO stanza VALUES('Z734','chorus','接受！接受！<br/>完全接受，情往意降；<br/>接受！接受！<br/>接受基督作我的君王。<br/>','',57616,11151);
INSERT INTO stanza VALUES('Z735','1','前我堕入罪海中，<br/>远离平安之岸，<br/>受尽摧残深感痛，<br/>欲拔不能，徒叹！<br/>但主听见我呼喊，<br/>立前来拯救，<br/>甘冒风险施救援，<br/>爱何深厚！<br/>','',57617,11152);
INSERT INTO stanza VALUES('Z735','chorus','爱救了我！爱救了我！<br/>当我在罪中落泊，<br/>爱救了我！爱救了我！<br/>爱救了我！<br/>当我在世界活，<br/>爱救了我！<br/>','',57618,11153);
INSERT INTO stanza VALUES('Z735','2','现今我在平安地，<br/>脱离罪恶痛苦，<br/>满了喜乐和安息，<br/>完全属于耶稣。<br/>爱是如此强而真，<br/>配得我的歌讴；<br/>我心、我命、我全人，<br/>永归祂有！<br/>','',57619,11154);
INSERT INTO stanza VALUES('Z735','3','苦中罪人，请听信，<br/>耶稣能施拯救；<br/>祂爱奇妙的救恩，<br/>现在就要接受。<br/>祂心渴望拯救你，<br/>等候已经够久；<br/>立即相信，勿犹疑，<br/>就来得救！<br/>','',57620,11155);
INSERT INTO stanza VALUES('Z736','1','罪恶途中多年流荡，<br/>我魂被罪摧残，<br/>等到基督来我心房，<br/>祂爱将我裹缠。<br/>','',57621,11156);
INSERT INTO stanza VALUES('Z736','chorus','我救主，何荣耀！<br/>从前瞎眼，<br/>阿利路亚，今看见！<br/>我救主，何荣耀！<br/>从前瞎眼，今看见！<br/>','',57622,11157);
INSERT INTO stanza VALUES('Z736','2','因我盲眼被主开启，<br/>我得见祂荣颜；<br/>祂爱向我所显美丽，<br/>我口难述半点。<br/>','',57623,11158);
INSERT INTO stanza VALUES('Z736','3','宝贝救主是我所倚，<br/>使我凡事得胜；<br/>我的救主无人能比，<br/>祂是我爱、我命。<br/>','',57624,11159);
INSERT INTO stanza VALUES('Z737','1','当我疲困罪恶境，<br/>祂以柔爱来寻，<br/>怀我、肩我满温情，<br/>带我归祂羊；<br/>千万天使因此欢腾，<br/>甚至歌声满天响应。<br/>','',57625,11160);
INSERT INTO stanza VALUES('Z737','chorus','爱何大，寻回我！<br/>血何宝，赎回我！<br/>恩何丰，带回我归羊群！<br/>奇妙恩，带回我归羊群！<br/>','',57626,11161);
INSERT INTO stanza VALUES('Z737','2','伤重待毙祂见我，<br/>便以油酒敷裹；<br/>柔声细语许我说；<br/>『你要永远属我！』<br/>从无声音如此甜美，<br/>伤痛之心顿觉欣慰！<br/>','',57627,11162);
INSERT INTO stanza VALUES('Z737','3','钉痕枪伤祂示我，<br/>血也水也流出，<br/>头戴荆冕利刺戳，<br/>羞辱加上痛楚：<br/>我真不知我有何长，<br/>使祂为我这样受戕。<br/>','',57628,11163);
INSERT INTO stanza VALUES('Z737','4','我今安坐祂面前，<br/>瞻仰祂的荣颜，<br/>心觉希奇灵感赞，<br/>追忆祂的恩眷；<br/>似乎永世所有时间，<br/>用来赞祂尚嫌太短。<br/>','',57629,11164);
INSERT INTO stanza VALUES('Z737','5','当今时日在逝逊，<br/>一切皆能安心；<br/>惟独切盼那早晨-<br/>无上光明时辰：<br/>那时召我到祂身边，<br/>与祂同在，作祂圣伴。 (副)<br/>爱何大，寻回我！<br/>血何宝，赎回我！<br/>恩何丰，带回我归羊！<br/>奇妙恩，带回我归羊！<br/>','',57630,11165);
INSERT INTO stanza VALUES('Z738','1','救我恩何等丰满，<br/>救我恩何等丰满，<br/>救我恩何等丰满，<br/>救我恩无量！<br/>','',57631,11166);
INSERT INTO stanza VALUES('Z738','chorus','主断开一切锁炼，<br/>主断开一切锁炼，<br/>主断开一切锁炼，<br/>主把我释放！<br/>','',57632,11167);
INSERT INTO stanza VALUES('Z738','2','我罪过都蒙赦免，<br/>我心中充满平安，<br/>我全人脱离羁绊，<br/>我今得释放！<br/>','',57633,11168);
INSERT INTO stanza VALUES('Z738','3','无论是罪恶、试探，<br/>无论是世界、撒但，<br/>无论是疾病、忧患，<br/>都不能捆绑！<br/>','',57634,11169);
INSERT INTO stanza VALUES('Z738','4','阿利路！主名香甜，<br/>阿利路！主名香甜，<br/>阿利路！主名香甜，<br/>我永要颂扬！<br/>','',57635,11170);
INSERT INTO stanza VALUES('Z738','5','还要唱阿利路亚，<br/>还要唱阿利路亚，<br/>还要唱阿利路亚，<br/>主把我释放！<br/>','',57636,11171);
INSERT INTO stanza VALUES('Z739','1','在十字架我救主舍命，<br/>所流宝血洗罪有权能；<br/>这宝贝血已将我洗清；<br/>荣耀归主名！<br/>','',57637,11172);
INSERT INTO stanza VALUES('Z739','chorus','荣耀归主名！<br/>荣耀归主名！<br/>主宝贝血已将我洗清；<br/>荣耀归主名！<br/>','',57638,11173);
INSERT INTO stanza VALUES('Z739','2','十字架下救主施恩典，<br/>用祂宝血洗净我罪愆；<br/>哦，这洗净奇妙而甘甜；<br/>荣耀归主名！<br/>','',57639,11174);
INSERT INTO stanza VALUES('Z739','3','这宝贝血洗我何清洁，<br/>我真快乐，我今白如雪！<br/>这血还要使我常超越；<br/>荣耀归主名！<br/>','',57640,11175);
INSERT INTO stanza VALUES('Z739','4','请你速来投入这泉源，<br/>将你全人抛在主脚前；<br/>今天来投，今天得完全；<br/>荣耀归主名！<br/>','',57641,11176);
INSERT INTO stanza VALUES('Z740','1','主耶稣，我们聚集<br/>在你墓的四围，<br/>口中歌唱心欢喜，<br/>见证你的作为。<br/>我们用信来跟随，<br/>追踪你的道路，<br/>借这庄严、奥妙水，<br/>进入你的工夫。<br/>','',57642,11177);
INSERT INTO stanza VALUES('Z740','2','主耶稣，我们记念<br/>你魂中的苦难，<br/>因你向我施恩典，<br/>曾被波浪冲漫；<br/>为我你浸死水中，<br/>为我你曾流血，<br/>为我你曾离天庭，<br/>为我你曾命绝。<br/>','',57643,11178);
INSERT INTO stanza VALUES('Z740','3','哦，主，你今已复活，<br/>黑暗已成往事，<br/>现今你已登宝座，<br/>活着，永不再死；<br/>罪、死、阴府你毁尽，<br/>我也同你得胜，<br/>因你是我的生命，<br/>我是坐享其成。<br/>','',57644,11179);
INSERT INTO stanza VALUES('Z740','4','我今受浸归你死！<br/>承认与你同尽，<br/>我也与你同复活，<br/>与你荣耀有分。<br/>撒但、世界和罪恶，<br/>今都不能摸我；<br/>我今同你作旅客，<br/>同你为神生活。<br/>','',57645,11180);
INSERT INTO stanza VALUES('Z741','1','基督死葬我随同，<br/>走进死水中，<br/>与祂同归终；<br/>世界、撒但势虽凶，<br/>到此便消踪，<br/>不能再追攻。<br/>基督复活我与共，<br/>走出死水中，<br/>与祂同行动；<br/>生命圣灵力无穷，<br/>使我蒙恩宠，<br/>荣上又加荣。<br/>','',57646,11181);
INSERT INTO stanza VALUES('Z742','1','主当我们借着这水，<br/>承认同死事实，<br/>求你在此怜悯施惠，<br/>启示牠的价值。<br/>','',57647,11182);
INSERT INTO stanza VALUES('Z742','2','借着这水归入你死，<br/>与你一同埋葬，<br/>我们永远离罪若失，<br/>脱离罪的捆绑。<br/>','',57648,11183);
INSERT INTO stanza VALUES('Z742','3','借着这水归入你死，<br/>与你一同埋葬，<br/>我们就此与世长辞，<br/>脱离今世君王。<br/>','',57649,11184);
INSERT INTO stanza VALUES('Z742','4','在此与你一同复活，<br/>脱离死亡权势；<br/>靠你结出成圣美果，<br/>活出新生样式。<br/>','',57650,11185);
INSERT INTO stanza VALUES('Z742','5','在此受浸归于你名，<br/>不再属于自己；<br/>为你而活，随你而行，<br/>永远与你合一。<br/>','',57651,11186);
INSERT INTO stanza VALUES('Z743','1','已经死了！已经葬了！<br/>从今以后我完全了了！<br/>已经死了！已经葬了！<br/>从今以后我完全了了！<br/>','',57652,11187);
INSERT INTO stanza VALUES('Z743','2','完全了了！完全了了！<br/>从今以后我完全了了！<br/>完全了了！完全了了！<br/>从今以后我完全了了！<br/>','',57653,11188);
INSERT INTO stanza VALUES('Z743','3','不再是我！不再是我！<br/>乃是基督在我里面活！<br/>不再是我！不再是我！<br/>乃是基督在我里面活！<br/>','',57654,11189);
INSERT INTO stanza VALUES('Z744','1','『借水得救』，<br/>此言奥妙，<br/>哦，主，启示其意，<br/>使我知道救恩何高，<br/>救我到何境地。<br/>','',57655,11190);
INSERT INTO stanza VALUES('Z744','2','『借水得救』，<br/>脱离世界，<br/>进入新生境地；<br/>已往一切都已完结，<br/>全埋奥妙水里。<br/>','',57656,11191);
INSERT INTO stanza VALUES('Z744','3','洪水如何拯救挪亚，<br/>脱离当日世代；<br/>浸水照样因着十架，<br/>使我与世分开。<br/>','',57657,11192);
INSERT INTO stanza VALUES('Z744','4','海水曾救以色列人，<br/>脱离埃及权势；<br/>浸水照样也救我们，<br/>脱离世界辖制。<br/>','',57658,11193);
INSERT INTO stanza VALUES('Z744','5','『借水得救』，<br/>何等释放，<br/>何等自由超脱：<br/>脱离世界一切捆绑，<br/>脱离病、苦、罪、魔。<br/>','',57659,11194);
INSERT INTO stanza VALUES('Z744','6','『借水得救』，<br/>永远归神，<br/>不再属于世界；<br/>敬拜、事奉，<br/>是我福分，<br/>归神成为圣洁。<br/>','',57660,11195);
INSERT INTO stanza VALUES('Z745','1','国度是神的掌权，<br/>维持神的荣耀；<br/>是神主宰的管治，<br/>将祂秩序建造。<br/>神在祂的国度里，<br/>施行祂的王权，<br/>照祂自己来治理，<br/>直到永永远远。<br/>','',57661,11196);
INSERT INTO stanza VALUES('Z745','2','国度中心是宝座，<br/>神在其上掌权；<br/>一切带上祂正规，<br/>照着祂心所愿。<br/>国度之中祂作王，<br/>一切归祂管治；<br/>为首为主的身分，<br/>如此始能维持。<br/>','',57662,11197);
INSERT INTO stanza VALUES('Z745','3','神借掌权国度中，<br/>通行祂的旨意；<br/>在祂统治的权下，<br/>成全祂的心意。<br/>惟有在神国度中，<br/>祝福始能得着；<br/>乃是从神的宝座，<br/>流出生命水河。<br/>','',57663,11198);
INSERT INTO stanza VALUES('Z745','4','服在神的管治下，<br/>乃是蒙福之本；<br/>背叛神圣的主权，<br/>乃是罪恶之根。<br/>撒但邪恶的目的，<br/>乃在翻神宝座；<br/>我们该有的目标，<br/>在神权下活着。<br/>','',57664,11199);
INSERT INTO stanza VALUES('Z745','5','在神至高国度中，<br/>基督得显为大；<br/>基督掌权生命中，<br/>神就能有可夸。<br/>当神施行祂统治，<br/>一切全都蒙福；<br/>基督若为神掌权，<br/>神的荣耀显出。<br/>','',57665,11200);
INSERT INTO stanza VALUES('Z745','6','日期满足的时候，<br/>主要归一万有，<br/>万有要认祂王权，<br/>将祂统治领受。<br/>生命荣耀的管治，<br/>召会现已豫尝，<br/>并催国度速实现，<br/>万有都得分享。<br/>','',57666,11201);
INSERT INTO stanza VALUES('Z746','1','神的国度今在地上，<br/>是神掌权在我心里；<br/>乃是基督活我里面，<br/>作主作王统治管理。<br/>','',57667,11202);
INSERT INTO stanza VALUES('Z746','2','基督生命同祂权柄，<br/>使祂登极在我心中，<br/>管理全人每一部分，<br/>规律一切言语行动。<br/>','',57668,11203);
INSERT INTO stanza VALUES('Z746','3','基督在我心中登极，<br/>就在我心建祂国度，<br/>稳定祂的全权统治，<br/>为着神旨各方铺路。<br/>','',57669,11204);
INSERT INTO stanza VALUES('Z746','4','借着祂在我心执政，<br/>祂将生命向我供应；<br/>当我让祂作主作王，<br/>我就得享祂的丰盛。<br/>','',57670,11205);
INSERT INTO stanza VALUES('Z746','5','借着祂在里面管治，<br/>祂的丰满在我建起；<br/>当祂里面国度掌权，<br/>祂的身体就得建立。<br/>','',57671,11206);
INSERT INTO stanza VALUES('Z746','6','借祂里面属天管治，<br/>我像天上国民活着；<br/>借着我肯服祂权柄，<br/>祂的国度实现于我。<br/>','',57672,11207);
INSERT INTO stanza VALUES('Z746','7','在这属天范围活着，<br/>带着祂这属天王权，<br/>属天光中行动、争战，<br/>直到国度在地实现。<br/>','',57673,11208);
INSERT INTO stanza VALUES('Z747','1','国度要求，标准严格，<br/>远超律法所有要求；<br/>神的要求无论大小，<br/>无一比这高而难就。<br/>','',57674,11209);
INSERT INTO stanza VALUES('Z747','2','天国近了，<br/>『应当悔改』，<br/>这是国度首一要求；<br/>我们心思必须转变，<br/>向神一边全面转投。<br/>','',57675,11210);
INSERT INTO stanza VALUES('Z747','3','我们要进诸天国度，<br/>必须有那超凡的义；<br/>乃是出乎大能生命，<br/>远非律法所能为力。<br/>','',57676,11211);
INSERT INTO stanza VALUES('Z747','4','我们要进诸天国度，<br/>天父旨意必须遵行；<br/>不是照我心愿所选，<br/>乃是照祂心意所定。<br/>','',57677,11212);
INSERT INTO stanza VALUES('Z747','5','我们要进诸天国度，<br/>必须变成孩童样式；<br/>谦卑、简单、顺服、<br/>易改，<br/>毫无自满、自恃、自是。<br/>','',57678,11213);
INSERT INTO stanza VALUES('Z747','6','诸天国度甚至要求<br/>我们与神一样完全；<br/>必须完全合这标准，<br/>国度实际才能实践。<br/>','',57679,11214);
INSERT INTO stanza VALUES('Z747','7','国度乃是神的掌权，<br/>需要与神性质相合；<br/>只有借着神的生命，<br/>才能进这神圣之国。<br/>','',57680,11215);
INSERT INTO stanza VALUES('Z747','7','国度乃是属天管治，<br/>必须合于属天情形；<br/>若要与主有分这国，<br/>惟有借着属天生命。<br/>','',57681,11216);
INSERT INTO stanza VALUES('Z748','1','诸天国度，牠的实际，<br/>在于受天管治生活；<br/>这种生活，性质神圣，<br/>全让基督居衷活着。<br/>','',57682,11217);
INSERT INTO stanza VALUES('Z748','2','这种生活：灵里贫穷，<br/>心里饥渴、哀恸、温柔；<br/>对人总是满了怜恤，<br/>对神又是清心寻求。<br/>','',57683,11218);
INSERT INTO stanza VALUES('Z748','3','作神儿子，制造和睦；<br/>为着公义，忍受逼迫；<br/>为主受人辱骂、毁谤；<br/>无怨无恨，欢喜快乐。<br/>','',57684,11219);
INSERT INTO stanza VALUES('Z748','4','作盐消杀地上败坏；<br/>作光照亮世上黑暗；<br/>存心行动，正直真诚，<br/>只爱不恨，像父完全。<br/>','',57685,11220);
INSERT INTO stanza VALUES('Z748','5','自荣自耀全都抛弃，<br/>永远为着神国祷告；<br/>先求神国和神的义，<br/>一切需要惟神是靠。<br/>','',57686,11221);
INSERT INTO stanza VALUES('Z748','6','对己严格，对人有恩，<br/>对神，又是殷勤求寻；<br/>永远遵行天父旨意，<br/>照主话语行事为人。<br/>','',57687,11222);
INSERT INTO stanza VALUES('Z748','7','对待撒但，不留地步，<br/>同样拒绝世界人情；<br/>只愿顺服诸天管治，<br/>接受神的完全权柄。<br/>','',57688,11223);
INSERT INTO stanza VALUES('Z748','7','这种生活征服一切，<br/>借神大能遵神吩咐；<br/>促进主的再来日子，<br/>带进国度实现之福。<br/>','',57689,11224);
INSERT INTO stanza VALUES('Z749','1','看，何荣耀！<br/>看，何光彩！<br/>诸天国度今实现！<br/>荣耀之王，神的基督，<br/>为神所立来掌权。<br/>曾在肉身卑微来过，<br/>被人藐视并厌恶；<br/>今带荣耀威严再来，<br/>成全国度的意图。<br/>','',57690,11225);
INSERT INTO stanza VALUES('Z749','2','去从祂神，亘古存者，<br/>领得权柄和国度；<br/>现今带着国度回来，<br/>荣耀显之于众目。<br/>这『非人手所凿石头』<br/>已将列国砸粉碎；<br/>变成『大山』充满天下，<br/>显出国度的光辉。<br/>','',57691,11226);
INSERT INTO stanza VALUES('Z749','3','看哪，地和其上列国，<br/>都归基督为基业；<br/>在祂至高统治之下，<br/>满了平安与和谐。<br/>列国之间再无争战，<br/>再无残杀的战场；<br/>神的知识充满遍地，<br/>好像大水满海洋。<br/>','',57692,11227);
INSERT INTO stanza VALUES('Z749','4','所有得胜的基督徒，<br/>荣中与主同管治；<br/>以色列的得救遗民，<br/>也要作神的祭司。<br/>在这管治教导之下，<br/>列国要作神百姓；<br/>所有万物都要得到<br/>荣耀无比的复兴。<br/>','',57693,11228);
INSERT INTO stanza VALUES('Z749','5','撒但被捆丢于深坑，<br/>全地脱离他霸权；<br/>由主基督为首统治，<br/>全地蒙福真空前。<br/>万有全都降服基督，<br/>服祂统治与管理；<br/>祂作元首，万有中心，<br/>成全祂神的旨意。<br/>','',57694,11229);
INSERT INTO stanza VALUES('Z750','1','神子来作生命种子，<br/>将祂自己种人心里，<br/>如此从祂长出国度，<br/>完成神的永远旨意。<br/>','',57695,11230);
INSERT INTO stanza VALUES('Z750','2','祂是惟一生命麦种，<br/>从祂生出许多子粒，<br/>配作诸天国度之子，<br/>带进神的掌权治理。<br/>','',57696,11231);
INSERT INTO stanza VALUES('Z750','3','但是撒但，神的仇敌，<br/>却将稗子撒在麦里，<br/>为要扰乱国度之子，<br/>造出可怕败坏事迹。<br/>','',57697,11232);
INSERT INTO stanza VALUES('Z750','4','借着他这奸狡工作，<br/>稗子、麦子混杂一起，<br/>国度外表变为反常，<br/>庞大惊人，丑形离奇。<br/>','',57698,11233);
INSERT INTO stanza VALUES('Z750','5','诸天国度该像芥菜，<br/>青嫩、微小，可供人食，<br/>但却变成一棵大『树』，<br/>不伦不类、庞大组织。<br/>','',57699,11234);
INSERT INTO stanza VALUES('Z750','6','不再能作神、人食物，<br/>反成『飞鸟』栖身之所；<br/>恶人、恶事以及恶灵，<br/>都能在此得到寄托。<br/>','',57700,11235);
INSERT INTO stanza VALUES('Z750','7','牠这外表给人看见<br/>一个属世伟大宗教；<br/>容纳外邦邪恶事物，<br/>犹如细面搀上面酵。<br/>','',57701,11236);
INSERT INTO stanza VALUES('Z750','7','既成这种属世组织，<br/>外表遂即改变形状；<br/>借其所容邪恶事物，<br/>里面充满败坏、淫荡。<br/>','',57702,11237);
INSERT INTO stanza VALUES('Z750','9','但神寻找隐藏珍物，<br/>『珍珠』和那『藏地<br/>宝贝；』<br/>主要将我全然变化，<br/>如同珠宝一样宝贵。<br/>','',57703,11238);
INSERT INTO stanza VALUES('Z750','10','隐自庞大基督教国，<br/>隐自国度属世外表；<br/>却有国度丰满实际，<br/>具有基督和神相貌。<br/>','',57704,11239);
INSERT INTO stanza VALUES('Z750','11','求主使我脱离『稗子』，<br/>救我脱离宗教大『树』；<br/>从我除去所有面酵，<br/>使我像你纯洁不俗。<br/>','',57705,11240);
INSERT INTO stanza VALUES('Z750','12','求借生命变化我魂，<br/>使我变成宝贵材料，<br/>带着你的国度实际，<br/>适合于你灵宫建造。<br/>','',57706,11241);
INSERT INTO stanza VALUES('Z751','1','今天神的国度，<br/>对我是操练，<br/>将来却是奖赏，<br/>与主一同掌权。<br/>这是神的智慧，<br/>现今将我训练，<br/>使祂计划完成，<br/>将祂公义彰显。<br/>','',57707,11242);
INSERT INTO stanza VALUES('Z751','2','我们为神所生，<br/>好为祂作王，<br/>但是还需训练，<br/>才能像王一样，<br/>好在祂的国中，<br/>胜任作王掌权，<br/>使祂神圣王权，<br/>借我得着彰显。<br/>','',57708,11243);
INSERT INTO stanza VALUES('Z751','3','今天我需学习<br/>服神的权柄，<br/>甘愿受祂管治，<br/>严格对付言行。<br/>如此祂的权柄，<br/>我就得以分享，<br/>将来管理列国，<br/>与祂儿子同王。<br/>','',57709,11244);
INSERT INTO stanza VALUES('Z751','4','严格对待自己，<br/>持守着公义，<br/>对人宽大有恩，<br/>对神灵中欢喜；<br/>一直都要活在<br/>国度实际里面，<br/>为着国度实现，<br/>能得进入掌权。<br/>','',57710,11245);
INSERT INTO stanza VALUES('Z751','5','如此，<br/>基督带着国度降临时，<br/>要将祂的王权<br/>赐我作为赏赐；<br/>如此，<br/>主要借我使祂公义彰显，<br/>并将祂的智慧<br/>给众天使看见。<br/>','',57711,11246);
INSERT INTO stanza VALUES('Z751','6','为着这个，<br/>使徒曾努力向前，<br/>愿出任何代价，<br/>不甘落在后面；<br/>也为这个，<br/>他劝我们忠诚向上，<br/>好在将来<br/>得着国度作为奖赏。<br/>','',57712,11247);
INSERT INTO stanza VALUES('Z751','7','求主赐我恩典，<br/>为国度活着，<br/>今天受你训练，<br/>将来你肯赏我；<br/>求使国度实际，<br/>今天作我操练，<br/>将来我的奖赏，<br/>乃是国度实现。<br/>','',57713,11248);
INSERT INTO stanza VALUES('Z752','1','耶稣要来奖赏祂的仆人，<br/>或早或晚时不定；<br/>会否祂来正逢我们坚忍，<br/>我们的灯修光明？<br/>','',57714,11249);
INSERT INTO stanza VALUES('Z752','chorus','我能否说，<br/>我是已经准备，<br/>准备坦然见主面？<br/>会否祂来正逢我仍不睡，<br/>仍然等候，直至祂显现？<br/>','',57715,11250);
INSERT INTO stanza VALUES('Z752','2','若祂在一清晨回来结算，<br/>一一指名传我们，<br/>我们各人要将银子交还，<br/>祂能否说『好，仆人？』<br/>','',57716,11251);
INSERT INTO stanza VALUES('Z752','3','主的委托，<br/>我们是否忠心？<br/>我们是否尽所能？<br/>我们里面若无指责声音，<br/>我们就必得高升。<br/>','',57717,11252);
INSERT INTO stanza VALUES('Z752','4','福哉人也！<br/>主来正逢儆醒，<br/>就必与祂同作王；<br/>当祂再临，<br/>或夜半或天明，<br/>是否正逢我瞭望？<br/>','',57718,11253);
INSERT INTO stanza VALUES('Z753','1','主耶稣，我正等待<br/>被提到你面前，<br/>除了你的快再来，<br/>无别如此甘甜。<br/>我今盼望你再来，<br/>我知道你已近，<br/>我觉得你的同在，<br/>已经包围我心。<br/>','',57719,11254);
INSERT INTO stanza VALUES('Z753','2','在我全人最深处，<br/>我已听见你话；<br/>感谢你，因你清楚<br/>语我以你计划。<br/>你的再临何等近！<br/>你的显现已快！<br/>恩典余日何等紧！<br/>仇敌就要败坏！<br/>','',57720,11255);
INSERT INTO stanza VALUES('Z753','3','求你斩断众籐蔓，<br/>使我完全自由，<br/>完全脱去诸累缠，<br/>紧紧跟随你走。<br/>我愿放下『合理事』，<br/>免得我心受拘，<br/>免得当你再来时，<br/>我不能自由去。<br/>','',57721,11256);
INSERT INTO stanza VALUES('Z753','4','时刻等候并儆醒，<br/>这是我的心意；<br/>愿我完全随从灵，<br/>免得错过被提；<br/>免得因我未豫备，<br/>因我打盹睡觉，<br/>你就以为我不配，<br/>留我在地受熬。<br/>','',57722,11257);
INSERT INTO stanza VALUES('Z753','5','我的心哪，这真是<br/>极庄严的儆戒，<br/>因此，你所爱的事，<br/>应当完全脱解。<br/>应当完全恋慕主，<br/>完全想念见祂；<br/>无论何时主招呼，<br/>能将一切撇下。<br/>','',57723,11258);
INSERT INTO stanza VALUES('Z753','6','虽然今日争战猛，<br/>多有撒但折磨，<br/>但是不久要高升，<br/>所以还怕甚么！<br/>现今黑暗虽加增，<br/>救赎日子也近，<br/>所以你可昂首等，<br/>因不久主必临。<br/>','',57724,11259);
INSERT INTO stanza VALUES('Z753','7','愿我所爱惟有主，<br/>愿我所想惟主，<br/>拒绝世界的贿赂，<br/>心已与主同处。<br/>地上束缚已经松；<br/>我主，求你就来，<br/>我心盼望到天中，<br/>看见我主我爱！<br/>','',57725,11260);
INSERT INTO stanza VALUES('Z754','1','主必亲自从天降临，<br/>神的号筒要吹响，<br/>圣徒死者复活，<br/>生命吞死亡，<br/>主必亲自从天降临，<br/>天上使者要宣扬，<br/>圣徒活者被提，<br/>身体变形状。<br/>','',57726,11261);
INSERT INTO stanza VALUES('Z754','chorus','主必亲自从天降临，<br/>我必面见祂的荣身；<br/>主必亲自从天降临，<br/>圣徒身体得赎，<br/>我也必有分。<br/>','',57727,11262);
INSERT INTO stanza VALUES('Z754','2','主必亲自从天降临，<br/>光明早晨要破晓，<br/>黑夜必要过去，<br/>哭泣必终了；<br/>主必亲自从天降临，<br/>荣耀日子要来到，<br/>败坏不再辖制，<br/>叹息必遁逃。<br/>','',57728,11263);
INSERT INTO stanza VALUES('Z754','3','主必亲自从天降临，<br/>明亮晨星要出现，<br/>醒者免去灾难，<br/>忠者得冠冕；<br/>主必亲自从天降临，<br/>公义太阳要掌权，<br/>万物得着复兴，<br/>大地蒙眷怜。<br/>','',57729,11264);
INSERT INTO stanza VALUES('Z754','4','主必亲自从天降临，<br/>圣徒等候要儆醒，<br/>腰带时时束紧，<br/>灯光要剔亮；<br/>主必亲自从天降临，<br/>你我事奉要忠诚，<br/>职事处处尽到，<br/>恩赐莫埋藏。<br/>','',57730,11265);
INSERT INTO stanza VALUES('Z755','1','基督快要再临，<br/>日子已紧近；<br/>有福脚声隐约可听闻。<br/>醒哉！醒哉！<br/>圣民，等候要儆心；<br/>被提见主喜乐无穷尽。<br/>','',57731,11266);
INSERT INTO stanza VALUES('Z755','chorus','荣耀！荣耀！<br/>基督快再临，<br/>荣耀！荣耀！<br/>圣者要欢欣，<br/>贱体变成荣身，<br/>与主永相亲，<br/>自由，荣耀，<br/>同主享福分。<br/>','',57732,11267);
INSERT INTO stanza VALUES('Z755','2','基督快要再临，<br/>晨星要显身；<br/>黑夜已深，白昼将临近。<br/>醒哉！醒哉！<br/>圣民，与俗莫浮沉；<br/>得蒙保守免去大灾辰。<br/>','',57733,11268);
INSERT INTO stanza VALUES('Z755','3','基督快要再临，<br/>赏赐祂仆人；<br/>凡爱祂者，冠冕必有分。<br/>醒哉！醒哉！<br/>圣民，莫把世界珍；<br/>爱主，事主，<br/>尽性又尽心。<br/>','',57734,11269);
INSERT INTO stanza VALUES('Z755','chorus','荣耀！荣耀！<br/>基督快再临，<br/>荣耀！荣耀！<br/>胜者要欢欣，<br/>听主称赞声音，<br/>说：『好！我仆人，<br/>你可进来享受我福分。』<br/>','',57735,11270);
INSERT INTO stanza VALUES('Z755','4','基督快要再临，<br/>得国作大君；<br/>撒但被擒，万民来归顺。<br/>醒哉！醒哉！<br/>圣民，努力向前奔，<br/>进入天国作王何荣尊。<br/>','',57736,11271);
INSERT INTO stanza VALUES('Z756','1','我王必定快要再临，<br/>天空都满了祂！<br/>待赎宇宙快得复兴，<br/>主要完成救法！<br/>我已听见祂的脚声，<br/>在那彩云中间；<br/>我已看见祂的荣身，<br/>隐约显露在天。<br/>','',57737,11272);
INSERT INTO stanza VALUES('Z756','2','我今仰望我主『同在』，<br/>不敢懈怠一点；<br/>我今等候我主再来，<br/>使我得着所天。<br/>除了我主此刻就来，<br/>接我与祂同在，<br/>除了这件美事以外，<br/>我心别无所爱。<br/>','',57738,11273);
INSERT INTO stanza VALUES('Z756','3','我眼专看我的救主，<br/>我心已经在天，<br/>我口不说别的题目，<br/>只说与主相见。<br/>主的再临已经紧近，<br/>主来原是为我；<br/>主的应许永远坚定，<br/>从来没有空说。<br/>','',57739,11274);
INSERT INTO stanza VALUES('Z756','4','我的救主，你的圣言<br/>无可惑，无可减；<br/>我今忠诚不顾脸面，<br/>因你圣言自勉。<br/>愿你荣耀早日显现，<br/>仇敌败，阴府陷；<br/>愿你应许早日应验，<br/>接我们到那边。<br/>','',57740,11275);
INSERT INTO stanza VALUES('Z756','5','你的膀臂是逃避所，<br/>耶稣救主我神！<br/>你像天父一样保妥<br/>一切靠你的人；<br/>羊和牧者同样轻重，<br/>身和头同境遇！<br/>谁也不能从你手中，<br/>夺去你的儿女。<br/>','',57741,11276);
INSERT INTO stanza VALUES('Z756','6','千人的手不能阻我，<br/>万人的眼也不；<br/>路上荆棘，不过助我<br/>忠勇进前得福。<br/>我心！我灵！今当复兴，<br/>让这世界过去；<br/>生命的主！求你快临，<br/>接我进入天域。<br/>','',57742,11277);
INSERT INTO stanza VALUES('Z756','7','医治的日！人的盼望！<br/>我真爱你光线；<br/>公义的主！荣耀的王！<br/>我今伏你面前；<br/>求你自己快登宝座！<br/>求你脸面快显！<br/>求你伸手建立天国，<br/>向万民赐恩典！<br/>','',57743,11278);
INSERT INTO stanza VALUES('Z756','7','真理本当得胜为王！<br/>自由本当为后！<br/>但是谎言竟然猖狂，<br/>为这世界元首！<br/>所以真理求你快来！<br/>带着天光而来！<br/>好使仇敌遇见失败，<br/>众子投入你怀。<br/>','',57744,11279);
INSERT INTO stanza VALUES('Z757','1','我能否忘快来的主？<br/>否，否，我心不断想慕：<br/>我为祂向父神求索，<br/>我为祂唱早晨诗歌。<br/>','',57745,11280);
INSERT INTO stanza VALUES('Z757','chorus','来罢！亲爱主！<br/>来罢！主！<br/>来罢！我王！<br/>','',57746,11281);
INSERT INTO stanza VALUES('Z757','2','我今能否忘了儆醒？<br/>否，否，我心早晚深省！<br/>惟恐错过被提机会，<br/>容让世事使我聋瞆。<br/>','',57747,11282);
INSERT INTO stanza VALUES('Z757','3','我能否与世界结联？<br/>否，否，祂召我往上面！<br/>愿我舍弃属地事物，<br/>爱祂，念祂，我的救主。<br/>','',57748,11283);
INSERT INTO stanza VALUES('Z757','4','愿我逐日行在灵里，<br/>吸取祂的生命能力，<br/>儆醒，等候，直到祂来，<br/>时刻豫备，不敢稍怠。<br/>','',57749,11284);
INSERT INTO stanza VALUES('Z757','5','愿我不怕撒但权势，<br/>一日在此，一日坚持，<br/>阴府的门必不得胜，<br/>神的基督已经执政。<br/>','',57750,11285);
INSERT INTO stanza VALUES('Z757','6','我能否忘这个信息？<br/>我要呼喊使地战栗！<br/>求主成全所赐信心，<br/>将你的话早日证明。<br/>','',57751,11286);
INSERT INTO stanza VALUES('Z758','1','自伯大尼<br/>你与我们分手后，<br/>我心有个真空无可补满，<br/>我坐河滨，<br/>将琴挂在柳枝头，<br/>你不在此，<br/>我怎有心鼓弹？<br/>当我深夜孤独<br/>安静的时候，<br/>（此时我无忍受，<br/>我也无享受，）<br/>不禁叹息，<br/>我想着你是多远，<br/>我想着你<br/>应许已久的归旋。<br/>','',57752,11287);
INSERT INTO stanza VALUES('Z758','2','你的马槽<br/>使我生无家之想，<br/>你的苦架使我无所欲喜，<br/>你的再来<br/>使我怀未见之乡，<br/>你的自己<br/>成我追求目的。<br/>你不在此，<br/>喜乐已减牠滋味，<br/>诗歌也缺<br/>牠所应有的甜美；<br/>你不在此，<br/>终日我若有所失，<br/>主阿，我要你来，<br/>我不要你迟。<br/>','',57753,11288);
INSERT INTO stanza VALUES('Z758','3','虽我在此<br/>也能享受你同在，<br/>但我深处依然有个缺憾；<br/>虽然有你光照，<br/>也有你抚爱，<br/>有个甚么我不知仍不满！<br/>平安里面，<br/>我却仍感觉孤单，<br/>喜乐时候，<br/>我仍不免有吁叹，<br/>最是足意中间，<br/>也有不足意，<br/>就是我还不能<br/>当面看见你。<br/>','',57754,11289);
INSERT INTO stanza VALUES('Z758','4','亡人怎不想见<br/>生长的乡邑？<br/>俘虏怎不想见故国故人？<br/>情人分离，<br/>怎不一心羁两地？<br/>儿女远游，<br/>怎不思家思亲？<br/>主阿，<br/>我想看见你面的心意，<br/>还非这些<br/>人间情形可比拟；<br/>现今在此，<br/>我无法见你丰采，<br/>是否只好叹息<br/>等到你回来！<br/>','',57755,11290);
INSERT INTO stanza VALUES('Z758','5','主你能否忘记<br/>你曾经应许，你要回来，<br/>接我与你同在？<br/>但一天天<br/>又一年年的过去，<br/>我仍等候，<br/>你却仍未回来！<br/>求你记念，<br/>我已等得好疲倦，<br/>而你踪迹<br/>好像当初一样远！<br/>多久？多久？<br/>还有多久的时候，<br/>才应验应许<br/>来把我提走？<br/>','',57756,11291);
INSERT INTO stanza VALUES('Z758','6','日出日落，<br/>一世过去又一代，<br/>你的圣徒生活、<br/>等候、安睡，<br/>一位一位，<br/>他们已逐渐离开，<br/>一次一次，<br/>我们望你快回。<br/>我主，<br/>为何你仍没有显动静，<br/>天仍闭住，<br/>我们观看仍对镜，<br/>我们在此<br/>依然等候再等候，<br/>哎呀，<br/>是否我们等候还不够？<br/>','',57757,11292);
INSERT INTO stanza VALUES('Z758','7','当我回想，<br/>我已等候多长久，<br/>不禁叹息，<br/>低头独自流泪，<br/>求你别再迟延<br/>不听我要求，<br/>现今就来接我与你相会；<br/>来罢，我主，<br/>这是召会的求呼！<br/>来罢，我主，<br/>请听圣徒的催促！<br/>来罢，<br/>历世历代累积的共鸣，<br/>我主，<br/>能否求你今天一起听！<br/>','',57758,11293);
INSERT INTO stanza VALUES('Z759','1','等到何日恩主才回来？<br/>我心渴望见祂丰采！<br/>等到何日恩主才回来，<br/>好使我得奏凯，见心爱？<br/>恩主快来！恩主何待？<br/>到何日你才肯来<br/>慰我心怀？<br/>恩主快来！恩主何待？<br/>我心切慕你同在！<br/>','',57759,11294);
INSERT INTO stanza VALUES('Z760','1','自从当年<br/>橄榄山前一别离，<br/>至今你仍未向我们呼召；<br/>历世历代<br/>我们都求看见你，<br/>但你好像不听我们祷告。<br/>','',57760,11295);
INSERT INTO stanza VALUES('Z760','chorus','你来！就来！<br/>我们呼求你快来！<br/>我们的心所有盼望<br/>是你来！<br/>我们等候你快来！<br/>','',57761,11296);
INSERT INTO stanza VALUES('Z760','2','爱主，<br/>自从当年你上升之后，<br/>这里都变何等枯燥无味；<br/>我们时在祈求，<br/>又时在看守，<br/>每一动静，<br/>都疑是你已回。<br/>','',57762,11297);
INSERT INTO stanza VALUES('Z760','3','景色虽美，<br/>你我何日才相聚？<br/>山水虽佳，<br/>你今在天何方？<br/>花香鸟语<br/>不能使我有情绪，<br/>因我正在思念你的容光。<br/>','',57763,11298);
INSERT INTO stanza VALUES('Z760','4','主阿，<br/>我们等待已久真焦灼，<br/>不知还要多少时候等待；<br/>从每次日出<br/>直到每次日落，<br/>我们都是望你能就回来。<br/>','',57764,11299);
INSERT INTO stanza VALUES('Z760','5','当雨每次滴沥，<br/>海每次澎湃，<br/>风每次吹动，<br/>月每次照明，<br/>我们都望<br/>就是你已经回来，<br/>何等失望，<br/>至今尚无动静！<br/>','',57765,11300);
INSERT INTO stanza VALUES('Z760','6','若非记念你临行<br/>所赐命令，<br/>我们就要灰心，<br/>无意工作；<br/>但你要我们<br/>一面等你来迎，<br/>一面努力工作为你生活。<br/>','',57766,11301);
INSERT INTO stanza VALUES('Z760','7','主阿，<br/>求你记念日子已长久，<br/>应许已过多年尚未应验；<br/>希望又希望，<br/>一直希望不休，<br/>要来未来，<br/>可否来在今天？<br/>','',57767,11302);
INSERT INTO stanza VALUES('Z761','1','主耶稣，主耶稣！<br/>为何你不来！<br/>主耶稣，主耶稣！<br/>为何你不来？<br/>受造物都纳闷，<br/>天地与深海，<br/>有牠们与我们，<br/>同望你回来；<br/>现宇宙年渐老，<br/>一切在等待，<br/>我们正同祷告，<br/>求你快回来，<br/>求你快回来，<br/>求你快回来。<br/>','',57768,11303);
INSERT INTO stanza VALUES('Z761','2','主耶稣，主耶稣！<br/>为何不回来？<br/>为何故你耽延，<br/>至今不回来？<br/>看他们是已经<br/>等候多少代，<br/>看我们也已经<br/>等候多少载，<br/>你为何不缩短<br/>久望的日子，<br/>因我们频呼喊，<br/>就来不再迟？<br/>','',57769,11304);
INSERT INTO stanza VALUES('Z761','3','主耶稣，主耶稣！<br/>为何不回来？<br/>自从你去天府，<br/>我心无可爱，<br/>我的天就好像<br/>不会再破晓，<br/>我的面就好像<br/>不能再欢笑；<br/>所有的雄心志，<br/>我都失兴采，<br/>主耶稣，主耶稣！<br/>为何不回来！<br/>','',57770,11305);
INSERT INTO stanza VALUES('Z761','4','求你来，求你来！<br/>四围所看见，<br/>是退后，是懈怠，<br/>逐一在改变：<br/>爱心是渐冷淡，<br/>受苦渐计算，<br/>信心渐发吁叹，<br/>举步渐迟缓，<br/>盼望如灯渐灭，<br/>像要不等待，<br/>主耶稣！看这些，<br/>为何不回来？<br/>','',57771,11306);
INSERT INTO stanza VALUES('Z761','5','主耶稣，主耶稣！<br/>为何你不来？<br/>主耶稣，主耶稣！<br/>为何你不来？<br/>你是要我等候<br/>到何日何年？<br/>我祷告，我看守，<br/>已难再迟延；<br/>主耶稣，主耶稣！<br/>我求你快来，<br/>主耶稣，主耶稣！<br/>我求你快来！<br/>','',57772,11307);
INSERT INTO stanza VALUES('Z762','1','我主，我正等候你再临，<br/>等候已久，<br/>好像这个等候无穷尽，<br/>一直等候不休；<br/>我是羡慕看见你面容，<br/>听你声音；<br/>我是希望能同你交通，<br/>比今更为相亲。<br/>','',57773,11308);
INSERT INTO stanza VALUES('Z762','chorus','是否须再等几年，<br/>再有几度徘徊，<br/>再有几次流泪、几思念，<br/>然后，主，你才回来？<br/>','',57774,11309);
INSERT INTO stanza VALUES('Z762','2','寡妇怎能在此不披素，<br/>回想已往；<br/>欲见不得，怎能不哀哭，<br/>怎不念念不忘？<br/>新妇怎能不因爱成病，<br/>切望婚期；<br/>如果久延无日徒引领，<br/>怎不连连叹息？<br/>','',57775,11310);
INSERT INTO stanza VALUES('Z762','3','召会等候你许多年代，<br/>从古到今，<br/>一世又一世一直忍耐，<br/>但你仍未降临；<br/>我也等候你许多岁月，<br/>从少而老，<br/>同时少年次第都永诀，<br/>但是你仍未到。<br/>','',57776,11311);
INSERT INTO stanza VALUES('Z762','4','我是已经等待好疲倦，<br/>求你记念；<br/>试炼使我渐易生埋怨，<br/>渐易忘记奉献。<br/>所以求你不要再迟延，<br/>求你快来；<br/>我已忍耐等候到今天，<br/>实在不易再挨。<br/>','',57777,11312);
INSERT INTO stanza VALUES('Z762','5','求你记念我的长等待，<br/>实难继续；<br/>你若不能及时早回来，<br/>只好让我前去。<br/>这久、这久，<br/>你不显荣耀，<br/>留在那边，<br/>无心的人已经在讥笑，<br/>说你不是迟延。<br/>','',57778,11313);
INSERT INTO stanza VALUES('Z762','6','我心所有忧伤与痛楚，<br/>无法平息，<br/>任何的人不能有帮助，<br/>因你不在这里。<br/>只有你来带我进永业，<br/>我才满愿；<br/>我要忘记路上这一切，<br/>当我看见你面。<br/>','',57779,11314);
INSERT INTO stanza VALUES('Z763','1','荣耀盼望是基督，<br/>我的生命是祂；<br/>祂已将我灵重生，<br/>现将我魂变化；<br/>还要改变我身体，<br/>用祂归服大能，<br/>使之和祂身体同，<br/>有祂荣形。<br/>','',57780,11315);
INSERT INTO stanza VALUES('Z763','chorus','祂来，祂来，<br/>祂来将我荣耀！<br/>将我身体改变形状，<br/>和祂身体相肖。<br/>祂来，祂来，<br/>为我身体需要！<br/>祂是我们荣耀盼望<br/>来将我们荣耀。<br/>','',57781,11316);
INSERT INTO stanza VALUES('Z763','2','荣耀盼望是基督，<br/>祂是神的奥秘；<br/>使我有分神丰满，<br/>将神带到我里。<br/>祂来使我能与神<br/>在各方面相调，<br/>使我有分祂荣耀，<br/>将祂返照。<br/>','',57782,11317);
INSERT INTO stanza VALUES('Z763','3','荣耀盼望是基督，<br/>祂是我的救赎：<br/>将我身体来救赎，<br/>脱离死的痛苦。<br/>祂来使我的身体<br/>变成荣耀形状；<br/>永远吞灭了死亡，<br/>将我释放。<br/>','',57783,11318);
INSERT INTO stanza VALUES('Z763','4','荣耀盼望是基督，<br/>祂是我的履历：<br/>祂的生命我经历，<br/>祂乃与我合一；<br/>祂来要将我带进<br/>祂的荣耀、自由，<br/>完全与祂成为一，<br/>直到永久。<br/>','',57784,11319);
INSERT INTO stanza VALUES('Z764','1','历代隐藏奥秘，<br/>向我已显明，<br/>就是荣耀基督-神实际。<br/>祂是神的化身，<br/>也是我生命，<br/>更是我的荣耀，我所期。<br/>','',57785,11320);
INSERT INTO stanza VALUES('Z764','chorus','荣耀！荣耀！<br/>基督在心房！<br/>荣耀！荣耀！<br/>祂是我盼望！<br/>现今在我里面，<br/>乃是一奥秘！<br/>将来是我荣耀，我所期。<br/>','',57786,11321);
INSERT INTO stanza VALUES('Z764','2','祂已将我重生，<br/>在我的灵中；<br/>现今在我魂里变化我；<br/>还要改变我体，<br/>和祂体相同，<br/>使我完全与祂像符合。<br/>','',57787,11322);
INSERT INTO stanza VALUES('Z764','3','今在生命、性情，<br/>祂与我合一；<br/>将来我要在祂荣耀里；<br/>与祂完全合一，<br/>享受祂自己，<br/>和祂全然相像，毫无异！<br/>','',57788,11323);
INSERT INTO stanza VALUES('Z765','1','当我恩主降临时候，<br/>我要脱尽所有忧愁，<br/>同众圣徒跟祂而走，<br/>哦！赞美主！<br/>哦！赞美主！<br/>哦！赞美主！<br/>同众圣徒跟祂而走，<br/>哦！赞美主！<br/>','',57789,11324);
INSERT INTO stanza VALUES('Z765','2','当我亲眼见我救主，<br/>与祂荣中永远同住，<br/>我心快乐，我口欢呼，<br/>哦！赞美主！<br/>','',57790,11325);
INSERT INTO stanza VALUES('Z765','3','当我见主在那空中，<br/>我十字架就不苦重，<br/>何等畅乐与主相逢！<br/>哦！赞美主！<br/>','',57791,11326);
INSERT INTO stanza VALUES('Z765','4','当那时候，<br/>我要证明<br/>无何能胜主的生命，<br/>离地上升何等欢腾！<br/>哦！赞美主！<br/>','',57792,11327);
INSERT INTO stanza VALUES('Z765','5','但愿我们隐主肋畔！<br/>合而为一不再离散，<br/>好叫耶稣意足心满，<br/>在祂来时！<br/>','',57793,11328);
INSERT INTO stanza VALUES('Z765','6','来罢我王，愿你就来！<br/>接等你者与你同在，<br/>使爱你者得你赏赉，<br/>主阿，快来！<br/>','',57794,11329);
INSERT INTO stanza VALUES('Z766','1','荣耀的盼望，<br/>基督要再临！<br/>我们要被提，<br/>贱体变荣身，<br/>与祂同荣耀，<br/>享受祂至宝，<br/>那时才知道救恩有多高。<br/>','',57795,11330);
INSERT INTO stanza VALUES('Z766','chorus','荣耀盼望，基督再临！<br/>荣耀盼望，基督再临！<br/>我们要被提，<br/>贱体变荣身，<br/>荣耀的盼望，<br/>基督要再临！<br/>','',57796,11331);
INSERT INTO stanza VALUES('Z766','2','荣耀的盼望，<br/>基督要再临！<br/>旧造全脱去，<br/>一切都更新，<br/>不再有叹息，<br/>尽都是逍遥，<br/>那时才尝到救恩的上好。<br/>','',57797,11332);
INSERT INTO stanza VALUES('Z766','3','荣耀的盼望，<br/>基督要再临！<br/>与祂同作王辖管列国民，<br/>且要作祭司事奉永活神，<br/>那时才享受至高的救恩。<br/>','',57798,11333);
INSERT INTO stanza VALUES('Z766','4','荣耀的盼望，<br/>基督要再临！<br/>等候当儆醒，<br/>事奉当忠心，<br/>灯油常豫备，<br/>前程努力奔；<br/>不然，<br/>怎配得上好的救恩？<br/>','',57799,11334);
INSERT INTO stanza VALUES('Z767','1','受造之物切望等候<br/>神的众子显出来，<br/>指望进入神子自由，<br/>脱离虚空与败坏。<br/>','',57800,11335);
INSERT INTO stanza VALUES('Z767','2','一切受造都在叹息，<br/>劳苦服在虚空下，<br/>指望得着完全释放，<br/>脱离败坏的管辖。<br/>','',57801,11336);
INSERT INTO stanza VALUES('Z767','3','甚至我们也在叹息，<br/>等候儿子的名分；<br/>我们须有基督身量，<br/>成为长大成熟人。<br/>','',57802,11337);
INSERT INTO stanza VALUES('Z767','4','为此圣灵替我叹息，<br/>愿我变成神子像；<br/>祂使万事互相效力，<br/>将我模成主模样。<br/>','',57803,11338);
INSERT INTO stanza VALUES('Z767','5','神要将我带进荣耀，<br/>那时我要被荣耀；<br/>用祂自己将我浸透，<br/>全然圣别成新造。<br/>','',57804,11339);
INSERT INTO stanza VALUES('Z767','6','所有受造要被释放，<br/>得进『荣耀』的自由；<br/>豹子与山羊羔同卧，<br/>狮子吃草好像牛。<br/>','',57805,11340);
INSERT INTO stanza VALUES('Z767','7','长大与主同作后嗣，<br/>承受儿子的名分；<br/>作祂弟兄与祂同荣，<br/>神的荣耀显我身。<br/>','',57806,11341);
INSERT INTO stanza VALUES('Z768','1','阿，神中心的观念，<br/>乃是与人相结联，<br/>祂来作人的一切，<br/>使祂计划得成全。<br/>','',57807,11342);
INSERT INTO stanza VALUES('Z768','2','人是被造的瓦器，<br/>有灵、有魂也有体；<br/>人可取神作生命，<br/>借此与神成为一。<br/>','',57808,11343);
INSERT INTO stanza VALUES('Z768','3','借着生命的流通，<br/>人变宝石为神用；<br/>适合为神造居所，<br/>让神彰显祂光荣。<br/>','',57809,11344);
INSERT INTO stanza VALUES('Z768','4','这是圣城神所建，<br/>这是居所神所羡；<br/>这是新耶路撒冷，<br/>完满成全神心愿。<br/>','',57810,11345);
INSERT INTO stanza VALUES('Z768','5','这是众圣的建造，<br/>这是神、人的相调；<br/>原是父神所筹划，<br/>满足神、人的需要。<br/>','',57811,11346);
INSERT INTO stanza VALUES('Z768','6','神和羔羊的宝座，<br/>在这荣耀的居所；<br/>从这掌权的中心，<br/>流出圣灵生命河。<br/>','',57812,11347);
INSERT INTO stanza VALUES('Z768','7','基督乃是生命树，<br/>长在河的两岸处；<br/>结出神圣生命果，<br/>供应众圣作食物。<br/>','',57813,11348);
INSERT INTO stanza VALUES('Z768','7','神在基督里作光，<br/>透过全城来照亮；<br/>死亡之夜全驱尽，<br/>神圣之光照辉煌。<br/>','',57814,11349);
INSERT INTO stanza VALUES('Z768','9','神在人里，人在神，<br/>互为居所来藏身；<br/>人的内容乃是神，<br/>神的表现乃是人。<br/>','',57815,11350);
INSERT INTO stanza VALUES('Z769','1','神的永远心意，<br/>是与人联合，<br/>要人作祂器皿，<br/>来将祂盛着；<br/>祂作人的生命，<br/>将人全充满，<br/>使人与祂合一，<br/>将祂来彰显。<br/>','',57816,11351);
INSERT INTO stanza VALUES('Z769','2','神照自己形像，<br/>将人造完全，<br/>使人能有资格，<br/>成全祂心愿；<br/>要人将祂接受<br/>作人生命树，<br/>成为祂的丰满，<br/>如妻之于夫。<br/>','',57817,11352);
INSERT INTO stanza VALUES('Z769','3','借祂生命流通，<br/>要将人变化，<br/>变成宝贵材料，<br/>与祂像无差。<br/>如此同被建造，<br/>作祂的配偶，<br/>也作祂的居所，<br/>给祂来享受。<br/>','',57818,11353);
INSERT INTO stanza VALUES('Z769','4','这是荣耀圣城，<br/>新耶路撒冷；<br/>神与圣徒相调，<br/>互居之所成。<br/>祂作他们内容，<br/>她作祂彰显，<br/>与祂同享荣耀，<br/>合一到永远。<br/>','',57819,11354);
INSERT INTO stanza VALUES('Z769','5','神是惟一中心，<br/>在宝座掌权；<br/>借祂生命权柄，<br/>圣徒全结联。<br/>因祂荣耀光照，<br/>都活在光中，<br/>彼此和谐一致，<br/>彰显祂光荣。<br/>','',57820,11355);
INSERT INTO stanza VALUES('Z769','6','神是生命活水，<br/>也是生命粮，<br/>充解圣徒饥渴，<br/>供他们饱享。<br/>祂是他们圣殿，<br/>他们活其间；<br/>在祂面光之中，<br/>敬拜到永远。<br/>','',57821,11356);
INSERT INTO stanza VALUES('Z770','1','哦，主，<br/>撒冷是你所建设，<br/>来赐给世上<br/>所有蒙恩的罪人；<br/>一切蒙血救赎，<br/>洗得洁净者，<br/>你都赐给权柄<br/>可入她的门。<br/>光是她荣耀<br/>已足使我羡慕，<br/>何况我主<br/>你是住在她中间，<br/>怎不叫我<br/>被吸引注目远处，<br/>就是无意想时<br/>也是在想念。<br/>','',57822,11357);
INSERT INTO stanza VALUES('Z770','2','哦，主，<br/>当我每想到撒冷，<br/>我就切切想要<br/>看见你的容颜，<br/>我心盼望<br/>我能早日被提升，<br/>好使我能早日<br/>倚傍你身边。<br/>我心真羡慕<br/>能早日到新地，<br/>能同所有爱你的人<br/>来爱你，<br/>时常歌颂<br/>你的爱无边无极，<br/>时常记念你爱<br/>舍己的踪迹。<br/>','',57823,11358);
INSERT INTO stanza VALUES('Z770','3','哦，主，<br/>我所欢喜和羡慕，<br/>不是红石绿宝，<br/>也非碧玉精金，<br/>我所想念乃是你，<br/>爱我的主！<br/>你是何等可爱，<br/>何等倾我心！<br/>我求你早日<br/>成全我的心愿，<br/>提接我到你前，<br/>不再有别离，<br/>好叫我与你<br/>同住直到永远，<br/>常能看见你，<br/>也常能听见你。<br/>','',57824,11359);
INSERT INTO stanza VALUES('Z770','4','撒冷是爱，是光，<br/>又是诗，<br/>因为有你在内作中心，<br/>并奖赏；<br/>因为有你自己<br/>和你的丰姿，<br/>才使撒冷对我<br/>能成为盼望！<br/>因为有了你，<br/>万物才得更新，<br/>叹息才成过去，<br/>眼泪才会干，<br/>我心才会满了<br/>安息与欢欣，<br/>主阿，<br/>为何你不早日快显现？<br/>','',57825,11360);
INSERT INTO stanza VALUES('Z771','1','他等候一座城，<br/>却住在帐棚，<br/>这天城的旅客，<br/>一直奔前程；<br/>他有美好证据，<br/>前途实堪夸，<br/>难怪他不寻求<br/>地上的荣华。<br/>','',57826,11361);
INSERT INTO stanza VALUES('Z771','chorus','城！城！荣美城！<br/>神与人的住处，<br/>新耶路撒冷！<br/>','',57827,11362);
INSERT INTO stanza VALUES('Z771','2','他等候一座城，<br/>他神的住处，<br/>他没有，<br/>也不求地上的房屋；<br/>因神岂非说过，<br/>属天的家乡，<br/>是那不离正道旅客<br/>所安享。<br/>','',57828,11363);
INSERT INTO stanza VALUES('Z771','3','他等候一座城，<br/>虽然有时因跋涉苦，<br/>丧失多，有叹息声音，<br/>但一想到那城，<br/>就引声歌唱，<br/>因为路虽崎岖，<br/>必定不会长。<br/>','',57829,11364);
INSERT INTO stanza VALUES('Z771','4','他等候一座城，<br/>我们今亦然：<br/>望能在你城中，<br/>同你永为伴，<br/>享受你的豫备；<br/>因此也愿意<br/>以帐棚为寄庐，<br/>同你客此地。<br/>','',57830,11365);
INSERT INTO stanza VALUES('Z772','1','圣城同救主是我们目标，<br/>我们的永分，<br/>灿烂又荣耀；<br/>我身虽在此，<br/>灵却已在彼，<br/>深望与恩主立在一起，<br/>深望与恩主立在一起。<br/>','',57831,11366);
INSERT INTO stanza VALUES('Z772','2','神圣的目标，<br/>新耶路撒冷，<br/>乃是神为人豫备的圣城；<br/>所有蒙宝血救赎的圣人，<br/>都能有权利享受这福分。<br/>','',57832,11367);
INSERT INTO stanza VALUES('Z772','3','哦，那座圣城，<br/>我每一瞻仰，<br/>就渴想见我恩主的面光；<br/>巴不得早日听见祂呼声，<br/>得进入那城，<br/>永享祂丰盛。<br/>','',57833,11368);
INSERT INTO stanza VALUES('Z772','4','我心所渴慕，<br/>并非甜安息，<br/>我久所盼望，<br/>也非何福气；<br/>乃是主自己-我荣耀盼望，<br/>就是我永分，<br/>作我的奖赏。<br/>','',57834,11369);
INSERT INTO stanza VALUES('Z772','5','哦，求主耶稣，<br/>快照我心愿，<br/>来接爱你者到你的面前！<br/>在那圣城中享受你自己，<br/>同住并同荣，<br/>永不再分离。<br/>','',57835,11370);
INSERT INTO stanza VALUES('Z772','6','那时的一切都因你更新，<br/>新天并新地，<br/>陪新城、新人！<br/>神荣耀自己要作我永分；<br/>哦，荣耀时辰，<br/>主阿，快显身！<br/>','',57836,11371);
INSERT INTO stanza VALUES('Z773','1','当我跑尽应跑道路，<br/>打过当打的美仗，<br/>我必被提升天<br/>进入主荣光；<br/>当我守住所信真道，<br/>甚至殉道毫不爽，<br/>必得圣城为奖赏。<br/>','',57837,11372);
INSERT INTO stanza VALUES('Z773','chorus','我必被提进入荣光，<br/>同主住在那圣城，<br/>新耶路撒冷，<br/>新耶路撒冷！<br/>同众胜者欢呼歌唱，<br/>赞美主恩颂主名，<br/>在那新耶路撒冷！<br/>','',57838,11373);
INSERT INTO stanza VALUES('Z773','2','今在异地作客飘泊，<br/>虽受窘困仍欢畅，<br/>因我不久必到<br/>更美的家乡；<br/>亲朋虽以世福为上，<br/>但我天天所仰望，<br/>乃是圣城在天上。<br/>','',57839,11374);
INSERT INTO stanza VALUES('Z773','3','虽然道路崎岖难行，<br/>使我腿酸手下垂，<br/>但一想到那城，<br/>全身力即回；<br/>虽然我眼难免流泪，<br/>但是我心永不灰，<br/>因有圣城为我备。<br/>','',57840,11375);
INSERT INTO stanza VALUES('Z773','4','我今斗拳，不是打空，<br/>奔跑不是无目标，<br/>乃是照神心意，<br/>追求那上好；<br/>忘记背后，努力面前，<br/>向着标竿一直跑，<br/>要得圣城的荣耀。<br/>','',57841,11376);
INSERT INTO stanza VALUES('Z773','chorus','主爱何丰，主恩何盛，<br/>使我得住那圣城，<br/>新耶路撒冷，<br/>新耶路撒冷！<br/>众圣欢腾，众圣和声，<br/>赞美主恩颂主名，<br/>在那新耶路撒冷！<br/>','',57842,11377);
INSERT INTO stanza VALUES('Z774','1','在起初时候，<br/>原是一园子，<br/>但到了末后，<br/>却是一城池；<br/>在园子那里，<br/>乃是神创造，<br/>在城池这里，<br/>成了神建造。<br/>','',57843,11378);
INSERT INTO stanza VALUES('Z774','2','无论在园里，<br/>或是在城中，<br/>河与生命树，<br/>都是神所重；<br/>河是指圣灵，<br/>作涌流生命，<br/>树是指基督，<br/>作生命供应。<br/>','',57844,11379);
INSERT INTO stanza VALUES('Z774','3','无论在园子，<br/>或是在城池，<br/>都有同三种贵重的物质：<br/>精金和珍珠、<br/>并贵重宝石，<br/>为着神建造，<br/>彰显神所是。<br/>','',57845,11380);
INSERT INTO stanza VALUES('Z774','4','但是在园里，<br/>这三种东西，<br/>不过是材料，<br/>散布在那里；<br/>乃是在城中，<br/>全都被建造，<br/>成为神居所，<br/>彰显神荣耀。<br/>','',57846,11381);
INSERT INTO stanza VALUES('Z774','5','人在园子里，<br/>乃是土所造，<br/>性质属于土，<br/>无属天荣耀；<br/>那时生命树，<br/>也在人外面，<br/>未作人生命，<br/>将人来改变。<br/>','',57847,11382);
INSERT INTO stanza VALUES('Z774','6','但是在城中，<br/>神圣生命树，<br/>长在人里面，<br/>团体人中住；<br/>指明神基督是神圣生命，<br/>在人的里面将生命供应。<br/>','',57848,11383);
INSERT INTO stanza VALUES('Z774','7','人之被创造，<br/>乃是为这城，<br/>所以须重生，<br/>变化质与形，<br/>能成为精金、<br/>珍珠和宝石，<br/>作主的身体，<br/>与主像相似。<br/>','',57849,11384);
INSERT INTO stanza VALUES('Z774','7','在那园子里，<br/>也有一新妇，<br/>作亚当配偶，<br/>出于他肋骨；<br/>这圣城本身，<br/>就是一新妇，<br/>作基督丰满，<br/>出于祂丰富。<br/>','',57850,11385);
INSERT INTO stanza VALUES('Z774','9','这圣城乃是神完满建造，<br/>众圣的组合，<br/>在灵里相调；<br/>作神的居所，<br/>给神来居住，<br/>作基督新妇，<br/>使祂心满足。<br/>','',57851,11386);
INSERT INTO stanza VALUES('Z774','10','是神的表现，<br/>终极且丰满，<br/>是宇宙团体，<br/>神圣又完全；<br/>三一神荣耀，<br/>她全然彰显，<br/>作基督配偶，<br/>荣耀达极点。<br/>','',57852,11387);
INSERT INTO stanza VALUES('Z775','1','哦主耶稣，你的赎民<br/>是你身体并新妇，<br/>作你丰满、作你表现，<br/>使你彰显你丰富。<br/>你永是她一切一切，<br/>她是你恩的宣告；<br/>你要将她完全浸透，<br/>要她有分你荣耀。<br/>','',57853,11388);
INSERT INTO stanza VALUES('Z775','chorus','看哪，神的圣城！<br/>满了神的光明！<br/>这是神完满的表现，<br/>永显于人性。<br/>','',57854,11389);
INSERT INTO stanza VALUES('Z775','2','是神与人完全相调，<br/>大哉，敬虔的奥秘；<br/>神的荣耀，丰满、灿烂，<br/>人作神居，荣无比。<br/>是一宇宙伟大器皿，<br/>全然表现神丰满；<br/>完全调着神的圣洁，<br/>使神荣美得彰显。<br/>','',57855,11390);
INSERT INTO stanza VALUES('Z775','3','乃是神所变化的人，<br/>一个永活的组合；<br/>如同珍珠、宝石珍贵，<br/>与神荣形相符合。<br/>从神宝座-她的中心，<br/>流出生命的活水；<br/>基督在此作生命树，<br/>结出鲜果，丰而美。<br/>','',57856,11391);
INSERT INTO stanza VALUES('Z775','4','是一永远精金灯台，<br/>托着基督作明灯；<br/>神在基督作她荣光，<br/>借着圣灵来照明。<br/>乃是终极、完满表现，<br/>是神调人的建造；<br/>乃是神、人互作居所，<br/>是神计画的目标。<br/>','',57857,11392);
INSERT INTO stanza VALUES('Z776','1','何等荣耀，何等光明，<br/>何等神圣耶路撒冷！<br/>乃是神在人间帐幕，<br/>又是羔羊所娶新妇。<br/>','',57858,11393);
INSERT INTO stanza VALUES('Z776','2','新约圣徒，旧约选民，<br/>都是圣城组成成分；<br/>同蒙救赎，同承应许，<br/>同被建造，给神安居。<br/>','',57859,11394);
INSERT INTO stanza VALUES('Z776','3','圣城四方，完美、方正，<br/>长宽高度全都相等，<br/>无何多余，无何不及，<br/>无何偏斜，无何不齐。<br/>','',57860,11395);
INSERT INTO stanza VALUES('Z776','4','精金城身、精金街道，<br/>如同玻璃明净、透照；<br/>象征神的尊贵生命，<br/>就是圣城本质本性。<br/>','',57861,11396);
INSERT INTO stanza VALUES('Z776','5','十二城门全是珍珠，<br/>因蒙基督奥妙救赎；<br/>重生使其变质成珍，<br/>神圣事物由此入门。<br/>','',57862,11397);
INSERT INTO stanza VALUES('Z776','6','十二墙基十二宝石，<br/>石石都是珍贵装饰；<br/>经过烧压，经过组织，<br/>方有如此永远价值。<br/>','',57863,11398);
INSERT INTO stanza VALUES('Z776','7','碧玉城墙明如水晶，<br/>神的光辉在此照明；<br/>射出神的荣耀光芒，<br/>照出神的碧玉形像。<br/>','',57864,11399);
INSERT INTO stanza VALUES('Z776','7','城墙为界，里外分别，<br/>摒除一切不圣、不洁；<br/>惟有精金、珍珠、宝石，<br/>能合圣城荣耀性质。<br/>','',57865,11400);
INSERT INTO stanza VALUES('Z776','9','神和羔羊为城的殿，<br/>人得时常见祂荣面；<br/>祂的同在永不离开，<br/>人在祂前事奉、敬拜。<br/>','',57866,11401);
INSERT INTO stanza VALUES('Z776','10','城不需要日、月、灯光，<br/>有神荣耀昼夜照亮；<br/>羔羊是灯，城是灯台，<br/>将神荣光四射城外。<br/>','',57867,11402);
INSERT INTO stanza VALUES('Z776','11','城中神和羔羊宝座，<br/>流出生命活水明河；<br/>流在城内街道中间，<br/>生命果树长在两岸。<br/>','',57868,11403);
INSERT INTO stanza VALUES('Z776','12','这是表明神的生命，<br/>不仅流出、滋润、供应，<br/>并且带着神的权柄，<br/>全城盘旋流通、运行。<br/>','',57869,11404);
INSERT INTO stanza VALUES('Z776','13','所以神性成为街道，<br/>满城尽是精金、珠宝；<br/>有道可行，有水可饮，<br/>生命粮食丰富、鲜新。<br/>','',57870,11405);
INSERT INTO stanza VALUES('Z776','14','十二数目表明政权，<br/>也是表明永远完全；<br/>更是表明神、人调和，<br/>三四相乘，融洽无隔。<br/>','',57871,11406);
INSERT INTO stanza VALUES('Z776','15','再无死亡，再无黑夜，<br/>咒诅、痛苦也都根绝；<br/>旧事全过，一切更新，<br/>神、人互居，相安相亲。<br/>','',57872,11407);
INSERT INTO stanza VALUES('Z776','16','圣城非但有神形像，<br/>并且为神掌权作王；<br/>成全神的永远心愿，<br/>满足神心，直到永远！<br/>','',57873,11408);
INSERT INTO stanza VALUES('Z777','1','在那新天与新地，<br/>有新耶路撒冷；<br/>她有神圣的光辉，<br/>因是由神而生。<br/>','',57874,11409);
INSERT INTO stanza VALUES('Z777','chorus','看，她有神的形像，<br/>也有分神的荣光，<br/>且与主一同作王，<br/>哦，神的圣城！<br/>','',57875,11410);
INSERT INTO stanza VALUES('Z777','2','城与其中的街道，<br/>都是透明精金，<br/>墙和根基是宝石，<br/>珍珠是作城门。<br/>','',57876,11411);
INSERT INTO stanza VALUES('Z777','3','生命水河如水晶，<br/>流在城内街道；<br/>河的两岸生命树，<br/>满足所有需要。<br/>','',57877,11412);
INSERT INTO stanza VALUES('Z777','4','在那光明的城中，<br/>神是一切一切；<br/>祂在羔羊里作光，<br/>城就永无黑夜。<br/>','',57878,11413);
INSERT INTO stanza VALUES('Z778','1','全部圣经新旧两约，<br/>都将圣民比作二物：<br/>新妇作神心爱佳偶，<br/>建筑作神安居之处。<br/>','',57879,11414);
INSERT INTO stanza VALUES('Z778','2','旧约所有召会豫表，<br/>不外妇女以及建筑；<br/>妇女作人称心配偶，<br/>建筑给人安居作主。<br/>','',57880,11415);
INSERT INTO stanza VALUES('Z778','3','古时神的以色列民，<br/>被神称作祂的妻子；<br/>其中有殿给神居住，<br/>也有圣城给神管治。<br/>','',57881,11416);
INSERT INTO stanza VALUES('Z778','4','为人之神，神人基督，<br/>作了新郎来娶新妇；<br/>祂用己命将她重生，<br/>可作配偶使祂满足。<br/>','',57882,11417);
INSERT INTO stanza VALUES('Z778','5','基督今在复活里面，<br/>像所罗门为神建殿，<br/>使神可有安息之所，<br/>成全祂的所有心愿。<br/>','',57883,11418);
INSERT INTO stanza VALUES('Z778','6','召会乃是基督新妇，<br/>使祂称心，作祂丰满；<br/>召会也是神的居所，<br/>给神安居，将神彰显。<br/>','',57884,11419);
INSERT INTO stanza VALUES('Z778','7','将来的新耶路撒冷，<br/>乃是所有新妇、建筑，<br/>一切豫表终极成全，<br/>使神得以心满意足。<br/>','',57885,11420);
INSERT INTO stanza VALUES('Z778','7','她是新妇作主配偶，<br/>使主称心，作主丰满；<br/>也是帐幕作神居所，<br/>给神安居，作王掌权。<br/>','',57886,11421);
INSERT INTO stanza VALUES('Z778','9','她是神在人里工作<br/>终极完满的集大成，<br/>作神人性里的表现，<br/>丰满、永远、而且神圣。<br/>','',57887,11422);
INSERT INTO stanza VALUES('Z779','1','在基督里归一万有，<br/>乃是我神的经营；<br/>基督作头并作中心，<br/>万有和谐而安宁。<br/>','',57888,11423);
INSERT INTO stanza VALUES('Z779','2','基督元首要作中心，<br/>神在其中作亮光；<br/>基督和神同坐宝座，<br/>使其心愿全得赏。<br/>','',57889,11424);
INSERT INTO stanza VALUES('Z779','3','基督要作生命、内容，<br/>归一万有于光中；<br/>众圣要作祂的器皿，<br/>永远彰显祂光荣。<br/>','',57890,11425);
INSERT INTO stanza VALUES('Z779','4','撒但已将他的自己<br/>注到人里，毁万有，<br/>带进黑暗、败坏、紊乱，<br/>使神计划难成就。<br/>','',57891,11426);
INSERT INTO stanza VALUES('Z779','5','基督来将祂的自己<br/>分赐与人作生命，<br/>拯救人脱黑暗权势，<br/>黑暗、死亡，再无能。<br/>','',57892,11427);
INSERT INTO stanza VALUES('Z779','6','借召会-祂的身体，<br/>要将万有归于一；<br/>万有都要联得合式，<br/>无论大小成一系。<br/>','',57893,11428);
INSERT INTO stanza VALUES('Z779','7','在这元首基督之下，<br/>万有联结而存立；<br/>在祂召会所照光中，<br/>万有全都归于一。<br/>','',57894,11429);
INSERT INTO stanza VALUES('Z779','7','有祂作头并作中心，<br/>万有全都能和谐；<br/>借祂身体所有光照，<br/>万有相安无间歇。<br/>','',57895,11430);
INSERT INTO stanza VALUES('Z779','9','再无黑暗，再无死亡，<br/>再无败坏与虚空；<br/>万有都要脱离辖制，<br/>永远居于自由中。<br/>','',57896,11431);
INSERT INTO stanza VALUES('Z780','1','那日我神的宝贝，<br/>不再藏于瓦器，<br/>乃从变化的人中，<br/>显出无遮美丽。<br/>','',57897,11432);
INSERT INTO stanza VALUES('Z780','2','借那伟大的金器，<br/>神的荣耀照亮；<br/>不用日、月来光照，<br/>因神自己作光。<br/>','',57898,11433);
INSERT INTO stanza VALUES('Z780','3','全城珍珠和宝石，<br/>满了神的美丽；<br/>光辉照耀如碧玉，<br/>荣耀灿烂无比。<br/>','',57899,11434);
INSERT INTO stanza VALUES('Z780','4','在那伟大器皿中，<br/>荣光永不暗淡，<br/>明光丰满照四方，<br/>驱尽地上黑暗。<br/>','',57900,11435);
INSERT INTO stanza VALUES('Z780','5','所有新造要看见，<br/>在彼神光四布；<br/>那个照耀的器皿，<br/>乃是羔羊新妇。<br/>','',57901,11436);
INSERT INTO stanza VALUES('Z780','6','那个荣耀的金器，<br/>令人向神敬拜，<br/>神在荣中羔羊里，<br/>显现直到万代。<br/>','',57902,11437);
INSERT INTO stanza VALUES('ZS1','1','当我们开口赞美，<br/>主就得着荣耀；<br/>当欢声响彻云霄，<br/>天使拍手叫好！<br/>我们是活神见证，<br/>该让世人知道；<br/>撒但全军必溃散，<br/>闻声四处窜逃。<br/>','',57903,11462);
INSERT INTO stanza VALUES('ZS1','2','我们闭口就失败，<br/>换来魔鬼嘲笑；<br/>因此为何不开火，<br/>直到把他赶跑？<br/>以『赞美为祭』献上，<br/>大大欢呼释放，<br/>怎能说这是丢脸？<br/>为神应该发狂！<br/>','',57904,11463);
INSERT INTO stanza VALUES('ZS1','3','世界从未助我们<br/>向主献赞美祭，<br/>从未向祂归荣耀，<br/>从未向祂感激。<br/>因此我们岂需要，<br/>得允许而赞美？<br/>喊出！释放你的灵！<br/>祂赐无限恩惠。<br/>','',57905,11464);
INSERT INTO stanza VALUES('ZS1','4','弟兄们，不要静默！<br/>姊妹们，大声喊！<br/>将神的得胜祝福，<br/>传遍远近四方。<br/>现在是赞美之时，<br/>任何代价不顾！<br/>因祂救恩而喜乐，<br/>因祂怜悯欢呼！<br/>','',57906,11465);
INSERT INTO stanza VALUES('ZS2','1','看哪，地上万民聚集，<br/>一同谋算虚妄事；<br/>君王臣宰起来商议，<br/>同声一气抵挡主。<br/>『我们挣开一切捆绑，<br/>脱去他们的绳索，』<br/>世上君王如此设谋，<br/>抵挡神并受膏者。<br/>','',57907,11466);
INSERT INTO stanza VALUES('ZS2','2','那坐天上的必发笑，<br/>主必定嗤笑他们；<br/>那时祂在怒中责备，<br/>烈怒中惊吓他们。<br/>在祂的锡安圣山上，<br/>神已膏祂的君王─<br/>这是神自己的宣告，<br/>警戒地上的诸王。<br/>','',57908,11467);
INSERT INTO stanza VALUES('ZS2','3','现今基督，神所膏者，<br/>传扬主神的旨意：<br/>『你是我子<br/>（在复活里），<br/>我在今日生了你。<br/>我将列国都赐给你，<br/>使你承受为基业，<br/>你显王权，手拿铁杖，<br/>将他们打破摔裂。』<br/>','',57909,11468);
INSERT INTO stanza VALUES('ZS2','4','你们君王应当省悟，<br/>审判官该受管教；<br/>当存畏惧事奉我主，<br/>又存战兢而欢跃。<br/>当以嘴亲子，消祂怒，<br/>免得你道中灭亡；<br/>『投靠祂的是有福的，』<br/>让我们同来欢唱！<br/>','',57910,11469);
INSERT INTO stanza VALUES('ZS2','5','哦，赞美神，我们看见<br/>你独一受膏之子；<br/>从虚妄中我们悔改，<br/>在爱里亲你爱子。<br/>『投靠祂的是有福的』─<br/>非那『遵守律法的；』<br/>只要信靠那复活者，<br/>就必蒙福永无已。<br/>','',57911,11470);
INSERT INTO stanza VALUES('ZS3','1','主耶和华，<br/>你的圣名在全地何其美！<br/>但愿各民、各族、各方，<br/>宣扬你名宝贝。<br/>从婴孩，吃奶者口中，<br/>你建立了赞美，<br/>使你仇敌闭口无言，<br/>敌权速速崩溃。<br/>','',57912,11471);
INSERT INTO stanza VALUES('ZS3','2','当我夜间观看诸天，<br/>你指头的工作─<br/>月亮、星宿暗中放明，<br/>凭你智慧述说。<br/>不禁要说：人算甚么，<br/>你竟如此顾念？<br/>在你神圣经营里面，<br/>叫人特蒙恩眷！<br/>','',57913,11472);
INSERT INTO stanza VALUES('ZS3','3','哦，主耶稣，你是那人─<br/>神来联于人类；<br/>你穿上了血肉之体，<br/>取了卑微地位。<br/>如今你得主宰权柄，<br/>荣耀为你冠冕，<br/>你将万有服你脚下，<br/>借你『身体』掌权。<br/>','',57914,11473);
INSERT INTO stanza VALUES('ZS3','4','你经过了道成肉身、<br/>受死、复活、升天，<br/>主权、元首、<br/>国度、身体，<br/>一一你都成全。<br/>借着这些神圣工作，<br/>你建立了赞美，<br/>我们的心喜乐满溢，<br/>赞美惟你是配。<br/>','',57915,11474);
INSERT INTO stanza VALUES('ZS3','5','有福之日不久将到，<br/>万口莫不同唱，<br/>但在地方召会之中，<br/>我们先有豫尝！<br/>哦，主耶和华，你的名<br/>在全地何其美！<br/>但愿各民、各族、各方，<br/>宣扬你名宝贝。<br/>','',57916,11475);
INSERT INTO stanza VALUES('ZS4','1','你的怒气，<br/>不过是转眼之间；<br/>你的恩典，<br/>乃是一生之久。<br/>一宿虽然有哭泣，<br/>早晨便必欢呼。<br/>','',57917,11476);
INSERT INTO stanza VALUES('ZS5','1','你已经将我的哀哭<br/>变为跳舞，<br/>将我的麻衣脱去，<br/>你已经将我的哀哭<br/>变为跳舞，<br/>给我披上了喜乐；<br/>好使我灵来歌颂你，<br/>并不住声。<br/>哦，主耶和华，<br/>我的神阿，我要称谢你，<br/>直到永远！<br/>','',57918,11477);
INSERT INTO stanza VALUES('ZS6','1','从我们心的深处，<br/>不断涌出美辞─<br/>论到我们至高王，<br/>论到祂的所是。<br/>我们舌如快手笔，<br/>篇篇见证待写─<br/>我们新郎的荣美，<br/>我们所爱所悦。<br/>','',57919,11478);
INSERT INTO stanza VALUES('ZS6','2','主耶稣，你的美丽<br/>超过所有世人；<br/>你的良善真无比─<br/>你是人中之人。<br/>从你圣洁的嘴里，<br/>流出丰盛恩惠；<br/>所以神赐福给你，<br/>赐福直到永远。<br/>','',57920,11479);
INSERT INTO stanza VALUES('ZS6','3','你是大能的勇士，<br/>赫然坐车前往；<br/>大有荣耀和得胜，<br/>所向显你雄威！<br/>万民倒在你以下，<br/>谁能阻你前进？<br/>你的箭极其锋利，<br/>射中撒但之心。<br/>','',57921,11480);
INSERT INTO stanza VALUES('ZS6','4','神阿，你坐的宝座，<br/>是永永远远的；<br/>你的国度与王权，<br/>是完全正直的。<br/>所以神，就是你神，<br/>用喜乐油膏你，<br/>胜过膏你的同伴─<br/>你是何等的配！<br/>','',57922,11481);
INSERT INTO stanza VALUES('ZS6','5','没药、沉香和肉桂，<br/>是你衣服香气；<br/>你的受死与复活，<br/>表明你的功绩。<br/>从众地方召会中，<br/>赞美之声四起，<br/>赞美再加上赞美，<br/>使你称心如意。<br/>','',57923,11482);
INSERT INTO stanza VALUES('ZS7','1','王后戴俄斐金饰，<br/>站在你右手边；<br/>有君王女儿，<br/>列在你尊贵妇女间。<br/>荣耀的召会<br/>将与她荣耀王相配，<br/>所有妇女（圣徒们）<br/>，彰显你的荣美。<br/>','',57924,11483);
INSERT INTO stanza VALUES('ZS7','2','女子阿，你当思想，<br/>你当侧耳而听；<br/>不要记念你的民，<br/>和父家的事情。<br/>你的美丽就显出，<br/>必为王所羡慕；<br/>你当亲近敬拜祂，<br/>因祂是你的主。<br/>','',57925,11484);
INSERT INTO stanza VALUES('ZS7','3','王女的华贵衣服，<br/>是用金线绣的，<br/>她在王的内宫里，<br/>实是荣华无比！<br/>神本性一切荣耀，<br/>赐给她为穿戴，<br/>她所有生活行为，<br/>将神发表出来。<br/>','',57926,11485);
INSERT INTO stanza VALUES('ZS7','4','她要被引到王前，<br/>身穿刺绣衣服，<br/>洁白美丽细麻衣，<br/>将她义行显出。<br/>借圣灵针针刺绣，<br/>基督作到身上，<br/>穿上这荣耀衣服，<br/>得蒙君王称赏！<br/>','',57927,11486);
INSERT INTO stanza VALUES('ZS7','5','当我们见王丰采，<br/>将是何等喜乐！<br/>我们要大声赞美，<br/>高唱永远乐歌。<br/>我们在此敬拜王，<br/>也因王后而夸，<br/>在这一切享受中，<br/>荣耀完全归祂。<br/>','',57928,11487);
INSERT INTO stanza VALUES('ZS8','1','主本为大！<br/>在我们神城内，<br/>在祂的圣山上，<br/>理当受大大的赞美！<br/>锡安山座落在北面，<br/>居高华美胜一切，<br/>乃是我们大君的京城，<br/>为全地所喜悦，<br/>乃是我们大君的京城，<br/>为全地所喜悦。<br/>','',57929,11488);
INSERT INTO stanza VALUES('ZS9','1','神兴起，使仇敌四散，<br/>叫恨祂的人逃跑；<br/>恶人见神面就消灭，<br/>如同蜡被火熔掉。<br/>惟有义人必欢喜，<br/>大声夸胜永不已，<br/>唱诗歌颂，唱诗歌颂，<br/>唱诗歌颂祂名。<br/>','',57930,11489);
INSERT INTO stanza VALUES('ZS9','2','祂坐车行过旷野地，<br/>将缺乏之民带回，<br/>祂是一切孤儿的父，<br/>也是寡妇的护卫─<br/>乃是在祂圣所里，<br/>哦，这救恩何希奇！<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57931,11490);
INSERT INTO stanza VALUES('ZS9','3','孤独者在此可安家，<br/>寂寞者寻得住处；<br/>被囚者从捆绑得释，<br/>并且享受无穷福。<br/>为祂羊群神豫备，<br/>这个住处─何恩惠！<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57932,11491);
INSERT INTO stanza VALUES('ZS9','4','现今主以大能夸胜，<br/>发出胜利的捷报，<br/>我们『妇女们』报喜信：<br/>『统兵君王逃跑了！』<br/>不用流汗不劳苦，<br/>我们在家分掠物！<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57933,11492);
INSERT INTO stanza VALUES('ZS9','5','看，基督已升上高天，<br/>领着长串的俘虏！<br/>祂将这些作成恩赐，<br/>为着神与人同住。<br/>弟兄姊妹，<br/>我们是那变化了的俘虏！<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57934,11493);
INSERT INTO stanza VALUES('ZS9','6','愿颂赞归神到永远，<br/>祂天天满载美物；<br/>祂是拯救我们的神，<br/>颂赞之声当远布。<br/>曾在阴间里漫游，<br/>祂打破仇敌的头！<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57935,11494);
INSERT INTO stanza VALUES('ZS9','7','神阿，我们看见了你，<br/>在你圣所中行走，<br/>你凯旋的队伍游行，<br/>作乐的跟随在后。<br/>看，歌唱的行在前，<br/>赞美一遍又一遍，<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57936,11495);
INSERT INTO stanza VALUES('ZS9','7','领先的是小便雅悯，<br/>接着是犹大支队，<br/>忧患之子在神右边，<br/>狮子掌权执王圭。<br/>西布伦，拿弗他利，<br/>传扬大喜的信息：<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57937,11496);
INSERT INTO stanza VALUES('ZS9','9','圣民哪，你们的能力，<br/>出自荣耀的圣殿；<br/>神阿，求你刚强我们，<br/>直到我们被成全。<br/>我们要赞美不停，<br/>直到地极都响应：<br/>阿利路亚，阿利路亚，<br/>阿利路亚，阿们！<br/>','',57938,11497);
INSERT INTO stanza VALUES('ZS10','1','普天之下当向耶和华<br/>大声喧嚷欢呼！<br/>应当乐意事奉耶和华，<br/>当来向祂歌颂。<br/>你们当晓得祂是神，<br/>我们乃是祂造的，<br/>也是属祂的；<br/>我们是祂民，<br/>也是祂草场的羊。<br/>应当称谢进入祂的门，<br/>赞美进入祂的院。<br/>应当同声感谢耶和华，<br/>称颂祂的名。<br/>因祂本为善；<br/>祂的慈爱是存到永远，<br/>祂的信实向我们<br/>一直到万代。<br/>','',57939,11498);
INSERT INTO stanza VALUES('ZS11','1','主，你若究察<br/>我们的众罪，<br/>谁还能站得住？<br/>主，你若究察<br/>我们的众罪，<br/>谁能站得住？<br/>但在你有赦免之恩，<br/>但在你有赦免之恩，<br/>但在你有赦免之恩，<br/>要人敬畏你。<br/>','',57940,11499);
INSERT INTO stanza VALUES('ZS12','1','看哪，耶和华仆人，<br/>夜间站在祂的殿中的，<br/>你们当称颂耶和华！<br/>当称颂祂名。<br/>你们当向圣所举手，<br/>称颂耶和华！<br/>愿造天地的耶和华，<br/>从锡安赐福给你。<br/>','',57941,11500);
INSERT INTO stanza VALUES('ZS13','1','我要永远的歌唱<br/>主耶稣的慈爱，<br/>我要唱，我要唱；<br/>何等的慈爱，<br/>我今活在召会之中，<br/>我要歌唱主耶稣的慈爱。<br/>用我口，我要传扬<br/>祂的信实，祂的信实。<br/>用我口，<br/>我要传扬祂的信实，<br/>直到世世代代。<br/>我要永远的歌唱<br/>主耶稣的慈爱，<br/>我要唱，我要唱；<br/>何等的慈爱，<br/>我今活在召会之中，<br/>我要歌唱主耶稣的慈爱。<br/>','',57942,11501);
INSERT INTO stanza VALUES('ZS14','1','你们要向主称颂，<br/>祂的名已被尊崇。<br/>你们要向主称颂，<br/>祂的名已被尊崇。<br/>因为祂所行的真是美好，<br/>但愿这事普传天下。<br/>你们要向主称颂，<br/>祂的名已被尊崇。<br/>','',57943,11502);
INSERT INTO stanza VALUES('ZS15','1','我要不住赞美称颂神，<br/>因祂活在我里，<br/>祂是我的一切，<br/>不断供应生命。<br/>我要不住赞美称颂神，<br/>因祂活在我里，<br/>与我永不分离。<br/>','',57944,11503);
INSERT INTO stanza VALUES('ZS15','chorus','今在灵里我能享受<br/>基督作我的一切<br/>呼求祂名<br/>祂就成了我实际。<br/>敞开你口就能尝到<br/>主是何等的丰富，<br/>祂是奇妙全备<br/>生命的供应。<br/>','',57945,11504);
INSERT INTO stanza VALUES('ZS15','2','现今我因生命树而活，<br/>其美果喂养我，<br/>其生命刚强我，<br/>我要永远活着。<br/>现今我因生命树而活，<br/>我天天取用祂，<br/>祂是我生命粮。<br/>','',57946,11505);
INSERT INTO stanza VALUES('ZS15','3','在我里面有生命水流，<br/>时刻都在涌流，<br/>处处都要流通，<br/>把我全人浸透。<br/>在我里面有生命水流，<br/>祂是生命泉源，<br/>一直涌到永生。<br/>','',57947,11506);
INSERT INTO stanza VALUES('ZS16','1','我们同声赞美<br/>来将祂颂扬，<br/>我们蒙神恩同住圣山上；<br/>见证祂的作为<br/>无论大或小，<br/>掌权的基督是我们君王。<br/>召会的生活实际又丰富，<br/>罪与世界都日渐的消逝；<br/>我们今跳跃尽情的欢唱，<br/>我们今跳跃尽情的欢唱。<br/>','',57948,11507);
INSERT INTO stanza VALUES('ZS16','2','赞祂与神同等<br/>原坐在天上，<br/>竟成为人子为我们受创；<br/>赞祂从死复活<br/>宝座上为王，<br/>复活的丰富我们能尽尝。<br/>赞祂何丰富充满了一切，<br/>我们竟成祂丰富的显彰；<br/>哦，阿利路亚！<br/>丰富的显彰，<br/>哦，阿利路亚！<br/>丰富的显彰。<br/>','',57949,11508);
INSERT INTO stanza VALUES('ZS16','3','赞祂今是那灵<br/>活在我灵里，<br/>宗教的仪文我不再凭依；<br/>我可时刻享受，<br/>享受祂自己，<br/>祂一切丰盛都成我经历。<br/>在地方召会我们齐欢畅，<br/>刚强的灵中将祂来颂扬；<br/>颂扬祂是灵，<br/>在召会作王，<br/>颂扬祂是灵，<br/>在召会中作王。<br/>','',57950,11509);
INSERT INTO stanza VALUES('ZS16','4','当祂荣耀自己<br/>充满在召会，<br/>召会的见证得胜又明亮；<br/>满得灵中丰富<br/>我们同颂扬，<br/>让世人都知这万王之王。<br/>丢弃自己那窄小的天地，<br/>自由的灵引我们到地极；<br/>荣耀欢乐的流出祂自己，<br/>荣耀欢乐的流出祂自己。<br/>','',57951,11510);
INSERT INTO stanza VALUES('ZS17','1','乐，乐，乐，<br/>我心充满喜乐；<br/>乐，乐，乐，<br/>耶稣使我唱歌；<br/>唱祂奇妙大爱为着我，<br/>说祂如何受死释放我，<br/>使我全人自由且超脱，<br/>我心乐，乐，乐！<br/>','',57952,11511);
INSERT INTO stanza VALUES('ZS17','2','主，主，主，<br/>在我灵中流通；<br/>主，主，主，<br/>在我魂中扩充；<br/>将我里面陈旧全烧尽，<br/>将我全人变化且更新，<br/>使我成熟迎接祂再临，<br/>是我主，主，主！<br/>','',57953,11512);
INSERT INTO stanza VALUES('ZS17','3','赞，赞，赞，<br/>将神心意发表，<br/>赞，赞，赞，<br/>使我灵里发烧，<br/>赞美满心满口满全人，<br/>将神计划到处告诉人，<br/>将流荡者带回归向神，<br/>高声赞，赞，赞！<br/>','',57954,11513);
INSERT INTO stanza VALUES('ZS17','4','召会，一地一个出现，<br/>召会，分裂何等可怜，<br/>大巴比伦今正在倾倒，<br/>主在耶路撒冷为至高；<br/>我们站住立场同建造，<br/>地方的召会。<br/>','',57955,11514);
INSERT INTO stanza VALUES('ZS17','5','地方召会，<br/>我们已经看见；<br/>地方召会，<br/>我们已在里面。<br/>光明的城造在圣山上，<br/>基督、召会同得着显彰；<br/>终于完成了神的愿望，<br/>在地方召会！<br/>','',57956,11515);
INSERT INTO stanza VALUES('ZS18','1','我有一诗歌我爱唱，<br/>自从我被赎回，<br/>唱我救赎主，救主，王，<br/>自从我被赎回。<br/>','',57957,11516);
INSERT INTO stanza VALUES('ZS18','chorus','自从我被赎回，<br/>自从我被赎回，<br/>我要靠主名夸耀；<br/>自从我被赎回，<br/>我要靠救主的名夸耀。<br/>','',57958,11517);
INSERT INTO stanza VALUES('ZS18','2','我有一基督能满足，<br/>自从我被赎回；<br/>行祂旨意是我所慕，<br/>自从我被赎回。<br/>','',57959,11518);
INSERT INTO stanza VALUES('ZS18','3','我有一中保神前立，<br/>自从我被赎回，<br/>消除一切忧惧、怀疑，<br/>自从我被赎回。<br/>','',57960,11519);
INSERT INTO stanza VALUES('ZS18','4','我有一喜乐说不出，<br/>自从我被赎回，<br/>都因我的义─我的主，<br/>自从我被赎回。<br/>','',57961,11520);
INSERT INTO stanza VALUES('ZS18','5','我有一位神我所属，<br/>自从我被赎回，<br/>与祂我要永远同住，<br/>自从我被赎回。<br/>','',57962,11521);
INSERT INTO stanza VALUES('ZS19','1','我在拿撒勒人耶稣面前<br/>惊异的站立，<br/>希奇，不洁罪人如我，<br/>祂爱竟然能临及。<br/>','',57963,11522);
INSERT INTO stanza VALUES('ZS19','chorus','何等希奇！何等奇妙！<br/>我要歌唱到万代，<br/>何等希奇！何等奇妙！<br/>是我救主的大爱！<br/>','',57964,11523);
INSERT INTO stanza VALUES('ZS19','2','为我祂在园中祷告：<br/>『只要照你的旨意；』<br/>祂无眼泪为己忧伤，<br/>为我流汗如血滴。<br/>','',57965,11524);
INSERT INTO stanza VALUES('ZS19','3','天使看见就怜恤祂，<br/>从光明之中显现；<br/>在那极其伤痛晚上，<br/>使祂力量得加添。<br/>','',57966,11525);
INSERT INTO stanza VALUES('ZS19','4','祂除去我罪与我忧，<br/>将其全归祂自己；<br/>祂负重担到各各他，<br/>独自受苦并受死。<br/>','',57967,11526);
INSERT INTO stanza VALUES('ZS19','5','当那日与蒙赎的人，<br/>在荣耀里见祂面，<br/>何等欢乐歌唱祂爱，<br/>一直到千万亿年。<br/>','',57968,11527);
INSERT INTO stanza VALUES('ZS20','1','何等权能！耶稣尊名！<br/>天使全都俯伏，<br/>天使全都俯伏，<br/>献上冠冕，同心尊敬。<br/>','',57969,11528);
INSERT INTO stanza VALUES('ZS20','chorus','加冠祂，加冠，加冠，<br/>加冠，加冠祂万有主！<br/>','',57970,11529);
INSERT INTO stanza VALUES('ZS20','2','你们堕落亚当后代，<br/>今成被赎圣徒，<br/>今成被赎圣徒，<br/>靠恩得救，<br/>应当敬拜。<br/>','',57971,11530);
INSERT INTO stanza VALUES('ZS20','3','罪人，你心永不可忘，<br/>祂的苦胆、酸醋，<br/>祂的苦胆、酸醋，<br/>今当到祂面前瞻望。<br/>','',57972,11531);
INSERT INTO stanza VALUES('ZS20','4','但愿地上万族万民，<br/>都向救主俯伏。<br/>都向救主俯伏，<br/>荣耀、尊贵都归祂名。<br/>','',57973,11532);
INSERT INTO stanza VALUES('ZS20','5','亿万群众歌声雷动，<br/>我也一同欢呼，<br/>我也一同欢呼，<br/>直到永远敬拜称颂。<br/>','',57974,11533);
INSERT INTO stanza VALUES('ZS21','1','祂是主，祂是主，<br/>祂已从死复活，<br/>如今祂是主！<br/>万膝莫不屈服，<br/>万口莫不称呼，<br/>耶稣基督为主。<br/>','',57975,11534);
INSERT INTO stanza VALUES('ZS22','1','我们歌唱要来掌权的王，<br/>荣耀归耶稣，<br/>被杀的羔羊；<br/>祂的国度带来公义平安，<br/>喜乐遍全地，<br/>当耶稣为王。<br/>','',57976,11535);
INSERT INTO stanza VALUES('ZS22','chorus','同心赞美，大声歌唱；<br/>耶稣为王，耶稣为王。<br/>这首诗章属主的人爱唱：<br/>荣耀归耶稣，<br/>我们的君王。<br/>','',57977,11536);
INSERT INTO stanza VALUES('ZS22','2','万民要住在祂奇妙光中，<br/>万族要因祂爱<br/>归于『大同』。<br/>公平与真实出自祂王杖，<br/>不法必终止，<br/>当耶稣为王。<br/>','',57978,11537);
INSERT INTO stanza VALUES('ZS22','3','在祂国度里完全是和睦，<br/>自由必旺盛，<br/>强暴被剪除，<br/>敌化为友，<br/>当祂凯歌同唱；<br/>剑变成镰刀，<br/>当耶稣为王。<br/>','',57979,11538);
INSERT INTO stanza VALUES('ZS22','4','认识神的知识充满全地，<br/>好像深水般将海洋淹蔽；<br/>地上万物都必如春发旺，<br/>一切全和谐，<br/>当耶稣为王。<br/>','',57980,11539);
INSERT INTO stanza VALUES('ZS22','5','愿基督的国度早日来临，<br/>晨光速露出，<br/>我们同欢欣。<br/>当受造之物新歌同声唱，<br/>撒但被摧毁而耶稣为王！<br/>','',57981,11540);
INSERT INTO stanza VALUES('ZS23','1','这是召会得胜歌声，<br/>羔羊是配；<br/>天上充满赞美欢腾，<br/>羔羊是配。<br/>王位政权向祂屈服，<br/>馨香气味升上高处，<br/>歌唱声音永不止住，<br/>羔羊是配。<br/>','',57982,11541);
INSERT INTO stanza VALUES('ZS23','2','各类各族各国人们，<br/>羔羊是配；<br/>一同歌唱这大救恩，<br/>羔羊是配。<br/>响声如同大雷轰隆，<br/>又如众水澎湃激冲。<br/>在祂脚前屈膝歌颂，<br/>羔羊是配。<br/>','',57983,11542);
INSERT INTO stanza VALUES('ZS23','3','琴声歌声永远不辍，<br/>羔羊是配；<br/>洪恩比罪更加显多，<br/>羔羊是配。<br/>借祂宝血，祂买我们；<br/>离群失落，祂寻我们；<br/>进入荣耀，祂领我们；<br/>羔羊是配。<br/>','',57984,11543);
INSERT INTO stanza VALUES('ZS23','4','这是何等有福盼望，<br/>羔羊是配；<br/>虽经试炼仍能歌唱，<br/>羔羊是配。<br/>甘甜超过最甜歌赋，<br/>只有一首诗歌题目，<br/>一直述说仍未说出，<br/>羔羊是配。<br/>','',57985,11544);
INSERT INTO stanza VALUES('ZS24','1','恩主，我们阿利路亚<br/>向你高声唱，<br/>永远赞美你的价值<br/>超万人之上。<br/>','',57986,11545);
INSERT INTO stanza VALUES('ZS24','chorus','赞美羔羊！你真是配！<br/>永远的歌声。<br/>阿利路亚！阿利路亚！<br/>赞美主！阿们！<br/>','',57987,11546);
INSERT INTO stanza VALUES('ZS24','2','赞美羔羊！你真是配！<br/>你宝血流出，<br/>赎回我们归神<br/>作王并祭司国度。<br/>','',57988,11547);
INSERT INTO stanza VALUES('ZS24','3','阿利路亚！恩主耶稣，<br/>你爱不止息；<br/>我们属你，永远属你，<br/>与你永合一。<br/>','',57989,11548);
INSERT INTO stanza VALUES('ZS24','4','赞美主！哦，阿利路亚！<br/>谁不唱此歌？<br/>来自各族各方各国<br/>众圣同唱和。<br/>','',57990,11549);
INSERT INTO stanza VALUES('ZS25','1','所以你们从救恩泉源<br/>欢然取水，欢然取水。<br/>就在那日，<br/>你们说：赞美主！<br/>所以你们从救恩泉源<br/>欢然取水，欢然取水。<br/>就在那日，<br/>你们说：赞美主！<br/>呼求祂的名，<br/>将祂所行传扬在万民中，<br/>题说祂的名已经被尊崇。<br/>扬声欢呼！<br/>你们锡安的居民哪！<br/>因你们中间的<br/>以色列的圣者为至大！<br/>','',57991,11550);
INSERT INTO stanza VALUES('ZS26','1','你们要尝尝主恩的滋味，<br/>便知道祂是美善；<br/>主耶稣是信实的，<br/>信靠祂的人有福了。<br/>敬畏祂的一无所缺，<br/>少壮狮子还缺食忍饿；<br/>但寻求主耶稣的人，<br/>甚么好处都不缺。<br/>','',57992,11551);
INSERT INTO stanza VALUES('ZS27','1','在荣耀里有一人，<br/>祂的生命是为我。<br/>祂是完全圣洁，<br/>自由且超脱，<br/>祂是全智、仁慈，<br/>祂是何温柔！<br/>祂荣耀里的生命<br/>乃是为着我。<br/>祂荣耀里的生命<br/>乃是为着我。<br/>','',57993,11552);
INSERT INTO stanza VALUES('ZS27','2','在荣耀里有一人，<br/>祂的生命是为我。<br/>在祂全无疾病，<br/>祂毫无软弱，<br/>祂是刚强、有力，<br/>且能往上浮！<br/>祂荣耀里的生命<br/>乃是为着我。<br/>祂荣耀里的生命<br/>乃是为着我。<br/>','',57994,11553);
INSERT INTO stanza VALUES('ZS27','3','在荣耀里有一人，<br/>祂的生命是为我。<br/>祂胜过了死亡，<br/>拘禁全脱落，<br/>在复活里作王，<br/>权柄手中握！<br/>祂荣耀里的生命<br/>乃是为着我。<br/>祂荣耀里的生命<br/>乃是为着我。<br/>','',57995,11554);
INSERT INTO stanza VALUES('ZS27','4','在荣耀里有一人，<br/>祂的生命是为我。<br/>祂的平安长存，<br/>不怕何风波，<br/>祂喜乐，发光辉，<br/>盼望而等着，<br/>祂荣耀里的生命<br/>从我里透过。<br/>祂荣耀里的生命<br/>从我里透过。<br/>','',57996,11555);
INSERT INTO stanza VALUES('ZS101','1','神，我赞美你，<br/>赐下基督的灵，<br/>祂今来住我里面，<br/>作我的生命。<br/>阿利路亚，基督的灵！<br/>阿利路亚，内住！<br/>阿利路亚，丰盛生命！<br/>永远不止住！<br/>','',57997,11556);
INSERT INTO stanza VALUES('ZS101','2','在灵里歌唱，<br/>末后亚当已经<br/>成为赐生命的灵，<br/>与我合为一。<br/>阿利路亚，这是耶稣！<br/>阿利路亚，那灵！<br/>阿利路亚，与祂联合！<br/>二灵成一灵！<br/>','',57998,11557);
INSERT INTO stanza VALUES('ZS101','3','在灵里重生，<br/>我们今被变化，<br/>模成神儿子形像，<br/>成熟并长大。<br/>阿利路亚，分赐生命！<br/>阿利路亚，变化！<br/>阿利路亚，改变形状！<br/>模成祂形像！<br/>','',57999,11558);
INSERT INTO stanza VALUES('ZS101','4','模成祂形像，<br/>乃借灵得喂养，<br/>时刻吃喝生命主，<br/>祂供应无量。<br/>阿利路亚，完全救恩！<br/>阿利路亚，属我！<br/>阿利路亚，够我应用！<br/>生活何超脱！<br/>','',58000,11559);
INSERT INTO stanza VALUES('ZS102','1','看哪，时代已转移，<br/>随主转入圣灵里，<br/>神宝座前的七灵，<br/>奉差遣到全地去。<br/>','',58001,11560);
INSERT INTO stanza VALUES('ZS102','chorus','哦，神七灵，我恳求，<br/>愿你工作得成就！<br/>将我鉴察并焚烧，<br/>为着召会的建造，<br/>鉴察，焚烧，<br/>为着召会的建造。<br/>','',58002,11561);
INSERT INTO stanza VALUES('ZS102','2','圣灵乃是七倍灵，<br/>应付召会死光景，<br/>圣徒转回得复苏，<br/>使主召会得恢复。<br/>','',58003,11562);
INSERT INTO stanza VALUES('ZS102','3','现今我们神的灵，<br/>成为召会的供应，<br/>而且加强成七倍，<br/>何等丰富又全备！<br/>','',58004,11563);
INSERT INTO stanza VALUES('ZS102','4','神的七灵是七灯，<br/>七盏烧着的火灯，<br/>并不是为着教导，<br/>乃是为将我焚烧。<br/>','',58005,11564);
INSERT INTO stanza VALUES('ZS102','5','看哪！现在神七灵，<br/>七眼如火焰照明，<br/>洁净召会每角落，<br/>肉体情欲都脱落。<br/>','',58006,11565);
INSERT INTO stanza VALUES('ZS102','6','主今赐下祂七灵，<br/>带着丰盛的生命，<br/>今在地方召会里，<br/>供我享受并经历。<br/>','',58007,11566);
INSERT INTO stanza VALUES('ZS103','1','哦主，以审判的灵，<br/>审判我一切恶行！<br/>我不凭自己搜寻，<br/>只等你灵来显明。<br/>','',58008,11567);
INSERT INTO stanza VALUES('ZS103','2','哦主，以焚烧的灵，<br/>烧去我所有污秽；<br/>把世界一烧而空，<br/>直到我爆炸发疯。<br/>','',58009,11568);
INSERT INTO stanza VALUES('ZS103','3','哦主，以智慧的灵，<br/>启示你一切奥秘；<br/>你是根、枝子、果实，<br/>你是内容和丰富。<br/>','',58010,11569);
INSERT INTO stanza VALUES('ZS103','4','哦主，以谋略的灵，<br/>显出你奇妙带领；<br/>新旧办法都无用，<br/>有灵能力才成功。<br/>','',58011,11570);
INSERT INTO stanza VALUES('ZS103','5','哦主，以知识的灵，<br/>非凭眼见或耳闻；<br/>使我明白你心意，<br/>战兢活出你救恩。<br/>','',58012,11571);
INSERT INTO stanza VALUES('ZS103','6','哦主，以公正的灵，<br/>带我学习走正路；<br/>不因人情而退却，<br/>不因艰难而变节。<br/>','',58013,11572);
INSERT INTO stanza VALUES('ZS103','7','主，去我沉睡的灵，<br/>开我眼使我儆醒；<br/>你来的日子近了，<br/>让我随时准备好。<br/>','',58014,11573);
INSERT INTO stanza VALUES('ZS104','1','我主基督是赐生命的灵，<br/>赐生命的灵，<br/>赐生命的灵。<br/>我主基督是赐生命的灵，<br/>祂活在我里面。<br/>祂活！祂活！<br/>祂在里面成形！<br/>我活！我活！<br/>我将祂来彰显！<br/>阿利路亚！<br/>我主基督是赐生命的灵，<br/>赐生命的灵，<br/>赐生命的灵。<br/>我主基督是赐生命的灵，<br/>祂活在我里面。<br/>','',58015,11574);
INSERT INTO stanza VALUES('ZS105','1','基督是那赐生命的灵，<br/>进入我灵赐我生命；<br/>基督是那赐生命的灵，<br/>在我灵里引导供应。<br/>','',58016,11575);
INSERT INTO stanza VALUES('ZS105','chorus','哦，主！阿们！<br/>哦，主！阿们！<br/>阿利路亚！<br/>哦，主！阿们！<br/>哦，主！阿们！<br/>阿利路亚！<br/>','',58017,11576);
INSERT INTO stanza VALUES('ZS105','2','如今主基督就是那灵，<br/>主灵，我灵联成一灵；<br/>如今主基督就是那灵，<br/>将我变化成主荣形。<br/>','',58018,11577);
INSERT INTO stanza VALUES('ZS106','1','我爱我的主耶稣，<br/>祂是赐生命的灵；<br/>我已与祂合为一，<br/>二灵成为一灵！<br/>','',58019,11578);
INSERT INTO stanza VALUES('ZS107','1','人人都应该知道，<br/>人人都应该知道，<br/>人人都应该知道，<br/>主住那里？<br/>祂是住在我们灵里，<br/>作我们生命、气息；<br/>我们与祂联合为一，<br/>这是何等的奥秘！<br/>','',58020,11579);
INSERT INTO stanza VALUES('ZS107','2','人人都应该知道，<br/>人人都应该知道，<br/>人人都应该知道，<br/>活的基督。<br/>基督是赐生命的灵，<br/>包含神一切丰富；<br/>取之不竭，用之不尽，<br/>只要呼喊主耶稣。<br/>','',58021,11580);
INSERT INTO stanza VALUES('ZS108','1','如今三一神<br/>已住在我里面，<br/>祂是奇妙之灵在我里。<br/>我已与主调和<br/>联成为一灵，<br/>祂是生命之灵在我里。<br/>','',58022,11581);
INSERT INTO stanza VALUES('ZS108','chorus','哦，祂是<br/>奇妙之灵住我里，<br/>祂是奇妙之灵住我里。<br/>如今神在子里，<br/>子就是那灵─<br/>祂是奇妙之灵住我里。<br/>','',58023,11582);
INSERT INTO stanza VALUES('ZS108','2','『阿爸父』我今<br/>从深处呼喊你，<br/>喊自奇妙之灵在我里；<br/>也就是子之灵<br/>向父神呼喊，<br/>祂是生命之灵在我里。<br/>','',58024,11583);
INSERT INTO stanza VALUES('ZS108','3','如今主耶稣基督<br/>住在我里，<br/>祂是奇妙之灵住我里；<br/>祂已经过变化，<br/>我可享受祂，<br/>祂是生命之灵住我里。<br/>','',58025,11584);
INSERT INTO stanza VALUES('ZS108','4','如今那实际之灵<br/>已经来到，<br/>祂是奇妙之灵住我里；<br/>今基督的一切，<br/>明亮又实际，<br/>借着生命之灵住我里。<br/>','',58026,11585);
INSERT INTO stanza VALUES('ZS108','5','我愿常挑旺<br/>这深处的恩赐，<br/>这是奇妙之灵住我里；<br/>喊『哦！主耶稣，』<br/>这使我灵跳跃，<br/>因着生命之灵在我里。<br/>','',58027,11586);
INSERT INTO stanza VALUES('ZS109','1','膏油在此！<br/>主在我们里面运行，<br/>宝贝膏油一直涂抹不停。<br/>宝血有能！<br/>牠为我们带进交通，<br/>如今我们活在生命流中。<br/>','',58028,11587);
INSERT INTO stanza VALUES('ZS109','chorus','（姊妹)<br/>膏油在此！<br/>哦，弟兄们哪！<br/>膏油在此我们相信！<br/>我们已从主得着这膏油，<br/>圣灵在灵里面运行！<br/>（弟兄）<br/>膏油在此！<br/>哦，姊妹们哪！<br/>膏油涂抹永远不停，<br/>借祂的涂抹住在祂里面，<br/>哦，阿利路亚，何丰盛！<br/>','',58029,11588);
INSERT INTO stanza VALUES('ZS109','2','膏油在此！<br/>是神自己与人调和，<br/>如今二者相调成为一个！<br/>时时刻刻，<br/>我们生活、动作、存留<br/>都在乎祂─<br/>神在我们里头。<br/>','',58030,11589);
INSERT INTO stanza VALUES('ZS109','3','膏油在此！<br/>膏油教导我们一切，<br/>我们经常有这生命感觉；<br/>顺这感觉，<br/>我们知道如何行事，<br/>凭祂而活，<br/>凡事无不清楚。<br/>','',58031,11590);
INSERT INTO stanza VALUES('ZS110','1','在神话里我看见，<br/>膏油已住在我里面！<br/>不需人为的教训，<br/>膏油自然有引领！<br/>','',58032,11591);
INSERT INTO stanza VALUES('ZS110','chorus','哦！在我的灵里<br/>祂是在运行！<br/>膏油涂抹常引领，<br/>神在我里涌流！<br/>哦，感谢赞美主，<br/>祂话已说出，<br/>我要不断的顺服，<br/>靠膏油涂抹而活。<br/>','',58033,11592);
INSERT INTO stanza VALUES('ZS110','2','为要将基督经历，<br/>借取用纯净话语；<br/>主灵与我联为一，<br/>永远不会再离去！<br/>','',58034,11593);
INSERT INTO stanza VALUES('ZS110','3','先有宝血的洁净，<br/>没有间隔没距离；<br/>接着膏油来涂抹，<br/>使我得着神自己。<br/>','',58035,11594);
INSERT INTO stanza VALUES('ZS110','4','基督是生命的灵，<br/>进入我的灵里头；<br/>神，那圣者涂抹我，<br/>直到神人全调和。<br/>','',58036,11595);
INSERT INTO stanza VALUES('ZS110','5','神是灵，我可摸着；<br/>祂是在我灵里流；<br/>更深、更广、更丰盛；<br/>膏油叫我认识神！<br/>','',58037,11596);
INSERT INTO stanza VALUES('ZS110','6','按照膏油的教导，<br/>经常住在主里面；<br/>祂边教导边展伸，<br/>直到占有我全人。<br/>','',58038,11597);
INSERT INTO stanza VALUES('ZS111','1','你找着你的灵没有？<br/>灵与口原分不开！<br/>『哦主，阿们，<br/>阿利路亚，』<br/>你的灵就能出来！<br/>','',58039,11598);
INSERT INTO stanza VALUES('ZS111','chorus','从圣灵生的<br/>乃是我们的灵，<br/>这工作已经完成；<br/>从圣灵生的<br/>乃是我们的灵，<br/>二灵相调成一灵。<br/>','',58040,11599);
INSERT INTO stanza VALUES('ZS111','2','不要苦等所谓『感动，』<br/>不要上撒但的当；<br/>要开口释放你的灵，<br/>见证你得了释放。<br/>','',58041,11600);
INSERT INTO stanza VALUES('ZS112','1','转入灵里，<br/>转入实际灵里！<br/>转入灵里，<br/>转入实际灵里！<br/>从外面字句、道理，<br/>转入灵里；<br/>哦，转入、转入，<br/>要转入灵里！<br/>转罢，弟兄！<br/>转罢，姊妹！<br/>实际是在灵里！<br/>（荣耀，阿利路亚！）<br/>转入实际灵里，<br/>直到转得彻底；<br/>转罢，随灵转罢！<br/>','',58042,11601);
INSERT INTO stanza VALUES('ZS112','2','随主往前，<br/>灵里随主往前！<br/>随主往前，<br/>灵里随主往前！<br/>看！时代已经转了，<br/>主已往前！<br/>哦，往前、往前，<br/>要随主往前！<br/>往前，弟兄！<br/>往前，姊妹！<br/>灵里随主往前！<br/>（荣耀，阿利路亚！）<br/>灵里一直往前，<br/>直到荣耀显现！<br/>往前，一直往前！<br/>','',58043,11602);
INSERT INTO stanza VALUES('ZS113','1','回到你灵里，<br/>在灵中与主相通！<br/>回到你灵里，<br/>得着生命供应；<br/>回到你灵里，<br/>时刻来呼喊主名！<br/>回到你灵里，活在灵中。<br/>','',58044,11603);
INSERT INTO stanza VALUES('ZS113','2','回到你灵里，<br/>在灵中与主相通！<br/>回到你灵里，<br/>这会使你歌唱；<br/>回到你灵里，<br/>正当事情在繁忙；<br/>回到你灵里，活在灵中。<br/>','',58045,11604);
INSERT INTO stanza VALUES('ZS113','3','回到你灵里，<br/>在灵中与主相通！<br/>回到你灵里，<br/>不管下沉、高昂；<br/>今日到永远，<br/>主对你总是一样！<br/>回到你灵里，活在灵中。<br/>','',58046,11605);
INSERT INTO stanza VALUES('ZS114','1','我们已得着释放，<br/>赞美主！（赞美主）<br/>我们已得着释放，<br/>赞美主！（赞美主）<br/>脱离了老旧宗教，<br/>脱离了死的规条，<br/>我们已得着释放，<br/>赞美主！（赞美主）<br/>','',58047,11606);
INSERT INTO stanza VALUES('ZS114','2','我们已得着释放，<br/>在灵里！（在灵里）<br/>我们已得着释放，<br/>在灵里！（在灵里）<br/>享受了生命自由，<br/>享受了完全拯救，<br/>我们已得着释放，<br/>在灵里！（在灵里）<br/>','',58048,11607);
INSERT INTO stanza VALUES('ZS115','1','饱尝我基督在灵里，<br/>吃喝祂，享受祂，<br/>甜无比！<br/>祂丰富都成为我实际，<br/>安息又饱足不止息。<br/>在灵里，在灵里，<br/>饱尝我基督在灵里；<br/>在灵里，在灵里，<br/>在灵里，<br/>享受主基督，在灵里！<br/>','',58049,11608);
INSERT INTO stanza VALUES('ZS116','1','我们要在灵里向主歌唱，<br/>我们要从里面向主唱，<br/>我们要阿利路亚向主唱，<br/>我们相调为一向主唱！<br/>','',58050,11609);
INSERT INTO stanza VALUES('ZS116','2','我们曾多年在宗教里面，<br/>我们曾多年在心思里，<br/>我们曾多年在情感里面，<br/>一直追求却在黑暗里。<br/>','',58051,11610);
INSERT INTO stanza VALUES('ZS116','3','今我们操练灵里接触主<br/>今我们操练取用基督，<br/>今我们操练吃喝主耶稣，<br/>脱离挣扎奋斗的痛苦。<br/>','',58052,11611);
INSERT INTO stanza VALUES('ZS116','4','阿利路亚！<br/>圣灵里的生命，<br/>阿利路亚！<br/>里面的新样。<br/>当我们从心思中转入灵，<br/>祂一切丰富我们全享。<br/>','',58053,11612);
INSERT INTO stanza VALUES('ZS117','1','我们已定意在灵里行事，<br/>我们已定意在灵里行事，<br/>我们已定意在灵里行事，<br/>在灵里，阿利路亚！<br/>','',58054,11613);
INSERT INTO stanza VALUES('ZS117','2','在灵里行事，<br/>喊『哦，主耶稣！』<br/>在灵里行事，<br/>喊『哦，主耶稣！』<br/>在灵里行事，<br/>喊『哦，主耶稣！』<br/>祂何丰富，阿利路亚！<br/>','',58055,11614);
INSERT INTO stanza VALUES('ZS117','3','要跟随耶稣，<br/>就需要『身体，』<br/>要跟随耶稣，<br/>就需要『身体，』<br/>要跟随耶稣，<br/>就需要『身体，』<br/>何等实际，阿利路亚！<br/>','',58056,11615);
INSERT INTO stanza VALUES('ZS117','4','建造在一起，<br/>其乐真无比，<br/>建造在一起，<br/>其乐真无比，<br/>建造在一起，<br/>其乐真无比，<br/>何等荣耀，地方召会！<br/>','',58057,11616);
INSERT INTO stanza VALUES('ZS117','5','神正在恢复召会的生活，<br/>神正在恢复召会的生活，<br/>神正在恢复召会的生活，<br/>我们在内，阿利路亚！<br/>','',58058,11617);
INSERT INTO stanza VALUES('ZS118','1','哦我神，在你里，<br/>有永远的生命，<br/>这生命在子里得显明。<br/>如今主复活里<br/>已成为生命灵，<br/>在我里点活我，赐生命。<br/>','',58059,11618);
INSERT INTO stanza VALUES('ZS118','2','哦看哪！<br/>从神和羔羊的宝座间，<br/>已流出这一道生命河；<br/>神乃是生命源，<br/>主乃是生命泉，<br/>三一神涌流成生命河。<br/>','',58060,11619);
INSERT INTO stanza VALUES('ZS118','3','主耶稣，主耶稣，<br/>我向你敞开灵，<br/>从深处呼你名将你饮；<br/>主耶稣，主耶稣，<br/>向这河我全倾，<br/>三一神漫全人作生命。<br/>','',58061,11620);
INSERT INTO stanza VALUES('ZS119','1','主是赐生命者，<br/>赐我生命；<br/>当每一次我呼喊祂，<br/>祂就释放我灵。<br/>主是赐生命者，<br/>住在我里；<br/>祂不仅是一个名字，<br/>乃是我的实际。<br/>','',58062,11621);
INSERT INTO stanza VALUES('ZS120','1','前远离神死在罪中，<br/>黑暗蒙蔽心眼；<br/>今蒙主话照明得知，<br/>主活在我里面。<br/>','',58063,11622);
INSERT INTO stanza VALUES('ZS120','chorus','主活我里面，<br/>主活我里面，<br/>哦，这是何等救恩，<br/>主竟活我里面。<br/>','',58064,11623);
INSERT INTO stanza VALUES('ZS120','2','如同阳光照射大地，<br/>百花盛开争艳；<br/>生命，光，爱从主而来，<br/>祂活在我里面。<br/>','',58065,11624);
INSERT INTO stanza VALUES('ZS120','3','正如花朵隐于花籽，<br/>树木孕于种子，<br/>同样，满带实际、恩典，<br/>主活在我里面。<br/>','',58066,11625);
INSERT INTO stanza VALUES('ZS120','4','我心不禁羡慕像祂，<br/>完全将祂彰显；<br/>我被吸引不断思量，<br/>主活在我里面。<br/>','',58067,11626);
INSERT INTO stanza VALUES('ZS121','1','耶稣是我主，<br/>祂活在我里；<br/>现今我真是快乐无比。<br/>哦，阿利路亚！<br/>哦，阿利路亚！<br/>祂活在我里！<br/>','',58068,11627);
INSERT INTO stanza VALUES('ZS121','2','世界尽都是充满了空虚，<br/>基督才是惟一的实际。<br/>哦，阿利路亚！<br/>哦，阿利路亚！<br/>祂活在我里！<br/>','',58069,11628);
INSERT INTO stanza VALUES('ZS122','1','我们看见基督是实际，<br/>但是不能只看见而已，<br/>祂在我们所有的经历，<br/>必须是一切。<br/>祷告之时瞻仰祂荣面，<br/>读经聚会认识祂恩典，<br/>但在日常生活的细节，<br/>祂是否一切？阿利路亚！<br/>在光中看见，<br/>主是何等真实又完全，<br/>只要我们在每一时间，<br/>在每一天，<br/>并在每一事件，<br/>随处多方回到祂前─经历祂的实际须具体！<br/>不再笼统，摸不着边际！<br/>只要应用祂就必经历─<br/>祂乃是一切！<br/>','',58070,11629);
INSERT INTO stanza VALUES('ZS122','2','我们一生充满了机会，<br/>父所安排，为显祂智慧。<br/>一切遭遇是最好最美，<br/>使我得基督─<br/>祂是内容，祂也是实际，<br/>我们将祂来照耀不已，<br/>你我身上祂必须有路，<br/>祂必须有路。<br/>阿利路亚！我们的身体，<br/>常带着主的被置死地，<br/>祂的生命得显明无比。<br/>外面的人虽然渐渐毁坏，<br/>里面的人却新起来─<br/>周围的人就都能看见，<br/>宝贝实际在瓦器里面，<br/>福音荣光全得着彰显─<br/>是借着我们。<br/>不是道理也不是神学，<br/>乃是实际内容毫不缺，<br/>基督作了我的一切，<br/>祂乃是一切！<br/>','',58071,11630);
INSERT INTO stanza VALUES('ZS123','1','阿利路亚！阿利路亚！<br/>耶稣如今活在我的里面。<br/>阿利路亚！阿利路亚！<br/>耶稣活在我里面。<br/>?<br/>附注：『活在』可改唱为<br/>『运行、』『成长、』<br/>『成形、』『涂抹、』<br/>『启示、』『安家』<br/>等等。<br/>','',58072,11631);
INSERT INTO stanza VALUES('ZS124','1','是生命，生命<br/>使我们高声喊，<br/>阿利路亚！赞美主！<br/>是生命，生命，<br/>使我们高声喊，<br/>阿利路亚！赞美主！<br/>我们心中充满喜乐，<br/>主在我们里面活着，<br/>主在我们里面活着！<br/>','',58073,11632);
INSERT INTO stanza VALUES('ZS125','1','主是生命种子，<br/>已经撒在我们心里，<br/>祂要发苗渐渐长大，<br/>长成祂的身量。<br/>祂不需要规条，仪文，<br/>只需活水浇灌；<br/>借此，包罗万有生命<br/>就要逐渐成长。<br/>何等奇妙的种子，<br/>就是耶稣我主，<br/>祂撒在我的里面，<br/>长大并达到成熟。<br/>','',58074,11633);
INSERT INTO stanza VALUES('ZS125','2','我们许多个别麦粒<br/>不能沾沾自喜，<br/>所有麦粒必须<br/>一起接受捣碎磨细；<br/>直到麦子磨成细面<br/>并作成一个饼，<br/>所有圣徒相调为一，<br/>模成主的身体。<br/>我们都须被磨细，<br/>直到失去自己，<br/>所有个别麦粒<br/>都模成祂一个身体。<br/>','',58075,11634);
INSERT INTO stanza VALUES('ZS125','3','种子已种，麦子长成，<br/>细面是那成品，<br/>我们乃是神的田地<br/>在合一里长进。<br/>所有生命的长大<br/>是为着建造召会，<br/>让神和人得一居所<br/>不再无家可归。<br/>生命是为着建造，<br/>神与人可安息，<br/>在此神与祂子民<br/>大家都和睦同居。<br/>','',58076,11635);
INSERT INTO stanza VALUES('ZS125','4','神的建造乃在于<br/>精金、宝石和银子，<br/>为着变化，<br/>细面需经多少压榨苦楚！<br/>麦子不能停在细面阶段<br/>自满自足，<br/>必须经过生命变化<br/>成为金银宝石。<br/>细面须经历痛苦，<br/>才能变成宝石；<br/>然后建造在一起，<br/>完全达到祂旨意。<br/>','',58077,11636);
INSERT INTO stanza VALUES('ZS125','5','生命变化完全成熟，<br/>结出一颗珍珠，<br/>简单、珍贵、包罗万有、<br/>且是满有价值。<br/>荣耀之主死而复活，<br/>经过生产之苦，<br/>终于得着召会─新妇，<br/>叫祂心满意足。<br/>珍珠是祂心所要，<br/>新妇是祂所悦；<br/>这是祂心爱配偶，<br/>单纯净、又宝贝。<br/>','',58078,11637);
INSERT INTO stanza VALUES('ZS125','6','愿主保守我们灵里贫穷，<br/>清心向主；<br/>使我们作好土，<br/>生命种子长大，丰富。<br/>直到目标达到，<br/>同被建造，你能满足，<br/>得着无价至宝─珍珠，<br/>就是你的新妇。<br/>主，倒空我们的灵，<br/>使我们心纯净，<br/>叫我们生命成熟<br/>成为你心爱新妇。<br/>','',58079,11638);
INSERT INTO stanza VALUES('ZS126','1','生命的种子撒我里，<br/>我要让祂长大；<br/>生命的种子撒我里，<br/>我要让祂长大，祂长大，<br/>祂长大，祂长大！<br/>','',58080,11639);
INSERT INTO stanza VALUES('ZS126','2','不让魂生命挤住祂，<br/>我要让祂长大；…<br/>','',58081,11640);
INSERT INTO stanza VALUES('ZS126','3','借着祷读来浇灌祂，…<br/>','',58082,11641);
INSERT INTO stanza VALUES('ZS126','4','天天呼喊<br/>『哦，主耶稣，』…<br/>','',58083,11642);
INSERT INTO stanza VALUES('ZS126','5','同众圣徒一起交通，…<br/>','',58084,11643);
INSERT INTO stanza VALUES('ZS126','6','要站起来为神说话，…<br/>','',58085,11644);
INSERT INTO stanza VALUES('ZS126','7','当主说话我就阿们，…<br/>','',58086,11645);
INSERT INTO stanza VALUES('ZS126','7','与众圣徒一起长大，…<br/>','',58087,11646);
INSERT INTO stanza VALUES('ZS126','9','直到长成基督身量，…<br/>','',58088,11647);
INSERT INTO stanza VALUES('ZS126','10','直到国度完全实现，…<br/>','',58089,11648);
INSERT INTO stanza VALUES('ZS127','1','主，给我们看见你心意，<br/>在于你的国度。<br/>不需我们愚昧的努力，<br/>却需你的恩典。<br/>不必等候那日显明，<br/>你把我们已迁国里；<br/>只要让你在里面长大，<br/>国度就得彰显。<br/>','',58090,11649);
INSERT INTO stanza VALUES('ZS127','2','神的国度是基督扩展：<br/>种子已撒我里；<br/>耶稣就是那生命种子─<br/>生长须加留意。<br/>石头地乃是魂生命，<br/>荆棘是思虑和财富；<br/>我们不能作路旁硬地，<br/>愿祂落在好土。<br/>','',58091,11650);
INSERT INTO stanza VALUES('ZS127','3','在好土里麦苗快生长，<br/>果实麦子结出；<br/>然而麦子须成为细面，<br/>好作神人食物。<br/>若要成就神这心意，<br/>就得接受一切磨炼，<br/>成为一个圣洁的素祭，<br/>主里紧紧相联。<br/>','',58092,11651);
INSERT INTO stanza VALUES('ZS127','4','从磨炼中变化成活石，<br/>个个为着建造！<br/>在圣灵里变质而长成─<br/>金银、宝石、珍珠。<br/>我们接受主作人位，<br/>占有我们全人生活；<br/>借此生命长大而变化，<br/>国度就能显现。<br/>','',58093,11652);
INSERT INTO stanza VALUES('ZS127','5','珍珠性质纯洁又完美，<br/>达到最高境界；<br/>虽然经历百般的痛苦，<br/>生命却更长成。<br/>主作我们生命、人位─<br/>国度原是主的自己；<br/>祂在里面不断的增长，<br/>直到神人合一。<br/>','',58094,11653);
INSERT INTO stanza VALUES('ZS128','1','国度就是基督作生命，<br/>满带着丰富在我里，<br/>复活里成长运行不息，<br/>基督能成为我新人。<br/>哦，愿你无限丰富，<br/>成我的供应能力，<br/>使我得天天享受你的，<br/>享受你的，<br/>享受你的一切的丰富。<br/>哦，愿你荣耀权能，<br/>在我里运行不息，<br/>好叫我天天变化成长，<br/>变化成长，变化成长，<br/>长成你形像。<br/>愿我有国度的实际，<br/>有召会生活的经历，<br/>与众圣徒<br/>同被建造在一起。<br/>哦，愿你国度权柄<br/>使我住属天境地，<br/>你能够天天自由运行，<br/>自由运行，自由运行，<br/>我住荣耀里。<br/>','',58095,11654);
INSERT INTO stanza VALUES('ZS129','1','耶稣我太阳，<br/>惟一的太阳，<br/>照亮我路途，灿烂明亮；<br/>不管是阴霾抑或是天晴，<br/>耶稣，耶稣，<br/>我惟一太阳。<br/>','',58096,11655);
INSERT INTO stanza VALUES('ZS129','2','耶稣我生命，<br/>美妙的生命，<br/>与我永联结，扶持供应；<br/>昨日今日到永远是一样，<br/>耶稣，耶稣，<br/>我惟一生命。<br/>','',58097,11656);
INSERT INTO stanza VALUES('ZS130','1','主耶稣，作了我人位；<br/>主耶稣，作了我人位。<br/>哦，我接受<br/>基督作我人位。<br/>基督安家在我心里，<br/>神的丰满充满了我。<br/>哦，我接受<br/>基督作我人位。<br/>','',58098,11657);
INSERT INTO stanza VALUES('ZS131','1','我的旧人已经被废除，<br/>在十架上已与主同死；<br/>现在他再无任何用处，<br/>对我他已故。<br/>我的新人在我灵里住，<br/>在我里面如活井涌出，<br/>以祂丰盛生命<br/>来充满我的每一部。<br/>基督在我灵里作人位，<br/>我心天天向祂不别归，<br/>好让里面的人有个家：<br/>一个地方可以安息，<br/>一个地方成为祂的─<br/>那里是我完全的实际，<br/>将祂所是向我全开启，<br/>丰丰富富居住我心里，<br/>作我真人位。<br/>','',58099,11658);
INSERT INTO stanza VALUES('ZS131','2','借这人位成形在我里，<br/>我成祂身上的一肢体，<br/>所有行动都不再单独，<br/>全在配搭里。<br/>基督必须是我们人位，<br/>我们天然个性须拆毁，<br/>天天拆毁直到拆干净，<br/>基督作一切！<br/>惟有基督是我们人位，<br/>再无自己的愿望目的，<br/>直到召会是基督自己，<br/>建造成为一个新人，<br/>实现神的永远旨意─<br/>神人完完全全的调和，<br/>得到一个合式的居所，<br/>建立起祂国度的权柄，<br/>在这全地上。<br/>不是单单基督的自己，<br/>还有召会同配合为一，<br/>取用基督自己作一切，<br/>成一个新人。<br/>','',58100,11659);
INSERT INTO stanza VALUES('ZS132','1','何等得胜，何等夸胜，<br/>神自己来成为人！<br/>亲自穿上人的性情，<br/>叫神的计划成全；<br/>借着十架败坏魔鬼，<br/>以『人子』复活升天！<br/>','',58101,11660);
INSERT INTO stanza VALUES('ZS132','2','耶稣凭着人的美德，<br/>逮捕了那诡诈者；<br/>以『人』身分抵挡试探，<br/>所有考验全通过！<br/>如今我在灵的里头，<br/>拥有祂一切美德。<br/>','',58102,11661);
INSERT INTO stanza VALUES('ZS132','3','祂作人的匀细生命，<br/>乃是在耶稣灵里，<br/>人的美德已经『子化』，<br/>与神的灵调为一。<br/>如今这灵丰富无比，<br/>足供我全人所需。<br/>','',58103,11662);
INSERT INTO stanza VALUES('ZS132','4','何等奥秘，却极真实，<br/>人子在我里面住！<br/>祂正伸展到我全人，<br/>要从我里面活出。<br/>阿利路亚，阿利路亚，<br/>我要赞美永不止。<br/>','',58104,11663);
INSERT INTO stanza VALUES('ZS132','5','何等奇妙，何等荣耀，<br/>神是在肉身显现！<br/>我们乃是祂的肢体，<br/>为将祂人性彰显。<br/>我们现在凭祂而活，<br/>让神居所早得建。<br/>','',58105,11664);
INSERT INTO stanza VALUES('ZS133','1','看哪！时代已经转移，<br/>争战已经开始！<br/>那背叛者撒但一伙，<br/>现在倾巢而出。<br/>所以圣徒必须<br/>具备耶稣完美人性，<br/>为着彰显神的形像，<br/>执行神的权柄。<br/>','',58106,11665);
INSERT INTO stanza VALUES('ZS133','chorus','让我们凭着<br/>耶稣的人性而站住，<br/>洋溢出人性美德，<br/>成为中流砥柱。<br/>在这世代，罪恶猖獗，<br/>弯曲败坏，悖逆刚硬，<br/>召会必须强烈见证<br/>耶稣完美人性！<br/>','',58107,11666);
INSERT INTO stanza VALUES('ZS133','2','看哪！撒但来到地上，<br/>破坏人类生命；<br/>但神从中兴起一人，<br/>祂的价值无比！<br/>从这一个女人后裔，<br/>神来成为肉身，<br/>这人耶稣─末后亚当─<br/>摧毁撒但诡计。<br/>','',58108,11667);
INSERT INTO stanza VALUES('ZS133','3','触目惊心，全地污染，<br/>罪中滚向下坡；<br/>每况愈下，几无药救，<br/>人性何其堕落！<br/>我们却是天国子民，<br/>显为世上的盐，<br/>在这不法世代里面，<br/>蒙祂人性保全。<br/>','',58109,11668);
INSERT INTO stanza VALUES('ZS133','4','今日惟有借着吃喝，<br/>主名不断呼喊；<br/>享受祂的人性所有，<br/>天天践踏撒但。<br/>哦，让我们回转向主，<br/>弃绝魂的生命；<br/>毁坏撒但所有计谋，<br/>供应新人生命。<br/>','',58110,11669);
INSERT INTO stanza VALUES('ZS134','1','神子耶稣为我离宝座，<br/>降世为人，历尽忧苦；<br/>舍了自己，流血救赎我，<br/>从死复活，化身那灵，<br/>作我拯救主。<br/>','',58111,11670);
INSERT INTO stanza VALUES('ZS134','chorus','永活救主，<br/>是我荣耀盼望，<br/>点活我灵，圣化我情；<br/>安家我心房，<br/>使我有力量，<br/>同众圣享主大爱，<br/>神丰满显明。<br/>','',58112,11671);
INSERT INTO stanza VALUES('ZS134','2','在主里面我获得新生，<br/>旧事已过，全都更新；<br/>爱中生活，新造何光明；<br/>生机拯救来自那灵，<br/>救恩何丰盛。<br/>','',58113,11672);
INSERT INTO stanza VALUES('ZS134','3','主，我爱你，<br/>愿跟随你行，<br/>奔跑赛程，讨你欢心；<br/>使我忠诚，紧联于你灵，<br/>直到路终，完全得胜，<br/>与你永相亲。<br/>','',58114,11673);
INSERT INTO stanza VALUES('ZS135','1','真葡萄树，<br/>生命何等丰美，<br/>繁生枝子无数，<br/>结出果实累累；<br/>主，你是树，<br/>我们是你枝子，<br/>爱中互相内住，<br/>生命涌流不止；<br/>生机结联，<br/>彼此合一无间，<br/>享受父神栽培、照护，<br/>生命充满，<br/>不断洋溢、扩展，<br/>彰显父神一切丰富。<br/>','',58115,11674);
INSERT INTO stanza VALUES('ZS136','1','在我灵中，<br/>祂的生命在流通，<br/>流通不停，<br/>光照、运行又感动，<br/>使我洁净，<br/>享受神圣的供应，<br/>我得复兴<br/>在祂生命滋润中；<br/>滋润我，滋润我，<br/>祂的生命时时滋润我，<br/>使我灵中新又活，<br/>得着基督多又多，<br/>何等甘甜，<br/>祂以生命滋润我。<br/>','',58116,11675);
INSERT INTO stanza VALUES('ZS136','2','在我魂间，<br/>祂的生命在溢漫，<br/>不断扩展，<br/>带来生命和平安，<br/>进入我心，<br/>祂要浸透并充填，<br/>更新、变化，<br/>使我属土成属天；<br/>浸透我，浸透我，<br/>祂的生命深深浸透我，<br/>将我全魂更新过，<br/>自己、天然都消没，<br/>何等释放，<br/>祂以生命浸透我。<br/>','',58117,11676);
INSERT INTO stanza VALUES('ZS136','3','我心盼望<br/>祂的生命得显彰，<br/>我脸瞻仰，<br/>返照基督的荣光，<br/>生命作王，<br/>我得模成主形像，<br/>有日身体改变，<br/>完全像祂样；<br/>变化我，变化我，<br/>祂的生命逐部变化我，<br/>在我建造神居所，<br/>完成神中心工作，<br/>何等荣耀，<br/>祂以生命变化我。<br/>','',58118,11677);
INSERT INTO stanza VALUES('ZS137','1','如今主，你就是那灵，<br/>是那赐人生命的活灵，<br/>为进我灵，作我生命，<br/>你已完成必经的过程：<br/>你从天降下成肉体，<br/>从阴间上来又复起；<br/>今犹如空气在我口里，<br/>一喊你名，我就将你吸。<br/>对我，你丰富无比；<br/>对我，你何等实际；<br/>丰富无比，何等实际，<br/>你今就在我心里！<br/>（重复一至四行）<br/>','',58119,11678);
INSERT INTO stanza VALUES('ZS137','2','愿主多赐我以那灵，<br/>以你新鲜生命来供应，<br/>从我心中浸透、充盈，<br/>直达圆周，处处都光明；<br/>你多方运行并工作，<br/>像神圣膏油在涂抹，<br/>将我的心、灵全浸润过，<br/>且来挑旺我深处爱火。<br/>有你，我灵会飞扬；<br/>有你，我心会歌唱；<br/>灵会飞扬，心会歌唱，<br/>生活如同在天上！<br/>（重复一至四行）<br/>','',58120,11679);
INSERT INTO stanza VALUES('ZS201','1','我们的心天天被吸引，<br/>更亲近耶稣；<br/>祂比世人更美，<br/>新鲜胜过清晨甘露。<br/>世上最美言辞<br/>还不能尽说祂价值，<br/>祂是天天更加宝贝，<br/>今日远胜昨日。<br/>','',58121,11680);
INSERT INTO stanza VALUES('ZS201','chorus','如此丰富的宝库，<br/>一半都难领会；<br/>昨日，今日，到永远，<br/>祂是天天更宝贝。<br/>','',58122,11681);
INSERT INTO stanza VALUES('ZS201','2','我们是在召会里面<br/>看见祂的荣耀，<br/>祂的丰富全都在此，<br/>我们不再他找，<br/>祂使我们渴慕的灵<br/>一再得着饱足，<br/>祂是天天更加宝贝，<br/>现在远胜当初。<br/>','',58123,11682);
INSERT INTO stanza VALUES('ZS201','3','如今祂是活灵，<br/>住在我们的灵里面，<br/>借祂甜美的涂抹，<br/>灵里生命更充满！<br/>当与圣徒一同聚集，<br/>我灵如插翅飞，<br/>因为如今我们的主<br/>比从前更宝贝。<br/>','',58124,11683);
INSERT INTO stanza VALUES('ZS201','4','主已使我们合而为一<br/>为着祂恢复，<br/>基督的丰富并祂丰满─<br/>召会─全显出，<br/>我们所有、所是，<br/>全倾于祂而不别归，<br/>为着祂的伟大计画<br/>比从前更宝贝。<br/>','',58125,11684);
INSERT INTO stanza VALUES('ZS202','1','我们已得到万有基督，<br/>祂是我们的一切；<br/>呼喊祂的名，何等有福，<br/>何等神圣，何超越！<br/>','',58126,11685);
INSERT INTO stanza VALUES('ZS202','chorus','哦，说不出的喜乐，<br/>且满了荣耀，<br/>满了荣耀，满了荣耀，<br/>说不出的喜乐，<br/>且满了荣耀，<br/>甚至一半都未能说出。<br/>','',58127,11686);
INSERT INTO stanza VALUES('ZS202','2','我们已知道那灵基督，<br/>住在我们的灵里，<br/>何等便利又亲近的主，<br/>祂的甘甜无可比。<br/>','',58128,11687);
INSERT INTO stanza VALUES('ZS202','3','我们已得到生活秘诀，<br/>读祂话并喊祂名！<br/>借此吃喝主，必无所缺，<br/>牠的价值真显明。<br/>','',58129,11688);
INSERT INTO stanza VALUES('ZS202','4','我们已寻到地方召会，<br/>我们已经回到家！<br/>永不再在巴比伦徘徊，<br/>在召会里美而佳。<br/>','',58130,11689);
INSERT INTO stanza VALUES('ZS202','5','我们已经历圣徒同聚，<br/>是地上最乐的事；<br/>借此我们的灵不忧郁，<br/>且使生活有价值。<br/>','',58131,11690);
INSERT INTO stanza VALUES('ZS203','1','我们来享受这<br/>新鲜活泼的耶稣，<br/>我们尽情吃喝吸入主。<br/>我们来享受这<br/>新鲜活泼的耶稣，<br/>真是实际，<br/>我们尽情吃喝吸入主。<br/>我们来享受这<br/>新鲜活泼的耶稣，<br/>真是实际，在召会中，<br/>我们尽情吃喝吸入主。<br/>我们来享受这<br/>新鲜活泼的耶稣，<br/>真是实际，在召会中，<br/>爱与合一，<br/>我们尽情吃喝吸入主。<br/>我们来享受这<br/>新鲜活泼的耶稣，<br/>耶稣是主！真是实际，<br/>在召会中，爱与合一，<br/>我们尽情吃喝吸入主。<br/>','',58132,11691);
INSERT INTO stanza VALUES('ZS204','1','享受主，享受主，<br/>享受祂的丰富。<br/>（四遍）<br/>享受，何必天天愁苦，<br/>失去见证。<br/>（二遍）<br/>享受主，享受主，<br/>享受祂的丰富。<br/>（二遍）<br/>?<br/>可换唱：释放主！<br/>释放主！<br/>…释放，<br/>何必将主丰富尽都扣住。<br/>或：见证主！<br/>赞美主！<br/>分享主！<br/>吃喝主！<br/>吸入主！…<br/>','',58133,11692);
INSERT INTO stanza VALUES('ZS205','1','更多得着基督，<br/>多又多又多！<br/>更多得着基督，<br/>多过从前所得着。<br/>更多得祂作生命，<br/>丰富无可加；<br/>更多得着基督，<br/>我将自己多给祂。<br/>','',58134,11693);
INSERT INTO stanza VALUES('ZS205','2','更多吃主耶稣，<br/>多又多又多！<br/>更多吃主耶稣，<br/>吃得比前还要多。<br/>更多吃祂作食物，<br/>丰富又美佳。<br/>更多吃主耶稣，<br/>我们时刻都吃祂。<br/>','',58135,11694);
INSERT INTO stanza VALUES('ZS206','1','我们同站在守望台，<br/>更上层楼向前观测；<br/>主在里面向我们说，<br/>祂的日子不再耽搁！<br/>','',58136,11695);
INSERT INTO stanza VALUES('ZS206','chorus','趁着今天多享受主，<br/>不要等到那日受苦，<br/>等到那日已经太迟！<br/>','',58137,11696);
INSERT INTO stanza VALUES('ZS206','2','蒙昧的人忙着搭窝，<br/>堆积财宝，据如己有；<br/>我们不等烈火来烤，<br/>今天凭信，先行焚烧。<br/>','',58138,11697);
INSERT INTO stanza VALUES('ZS206','3','无花果树要不发枝，<br/>葡萄树要不结果子，<br/>橄榄树要不再效力，<br/>田地也要不出粮食。<br/>','',58139,11698);
INSERT INTO stanza VALUES('ZS206','4','只要享受基督丰富，<br/>地上有无就可不顾；<br/>棚内缺牛，圈中绝羊，<br/>对于我们没有两样！<br/>','',58140,11699);
INSERT INTO stanza VALUES('ZS206','5','有祂就够我们欢喜，<br/>天天加力，成为劲旅！<br/>有祂就够我们快跑，<br/>与祂同奔，步步登高！<br/>','',58141,11700);
INSERT INTO stanza VALUES('ZS207','1','我们同来享受主的丰富，<br/>因主耶稣是赐生命的灵，<br/>又住在我们灵里，<br/>赐我们生命供应，<br/>运行调和又变化。<br/>哦，何等奇妙的主，<br/>和我联合为一，<br/>我要高声歌唱。<br/>阿利路亚，赞美我主！<br/>我们同来享受<br/>主的一切丰富，<br/>饱尝这包罗万有的主。<br/>','',58142,11701);
INSERT INTO stanza VALUES('ZS208','1','靠耶和华得的喜乐<br/>是你的力量。<br/>靠耶和华得的喜乐<br/>是你的力量。<br/>吃肥美的，喝甘甜的，<br/>今日是我们主的圣日。<br/>靠耶和华得的喜乐<br/>是你的力量。<br/>','',58143,11702);
INSERT INTO stanza VALUES('ZS209','1','生命树果，甘甜之至，<br/>生命全丰全足。<br/>前我死枯，如今活着；<br/>前饿，如今吃喝。<br/>','',58144,11703);
INSERT INTO stanza VALUES('ZS209','2','是神领我到生命树，<br/>享受基督自己。<br/>其中滋味，开口一吃，<br/>就觉甘甜无比！<br/>','',58145,11704);
INSERT INTO stanza VALUES('ZS209','3','基督是我生命供应，<br/>祂作我的食物；<br/>祂是惟一纯净享受，<br/>祂外再无满足。<br/>','',58146,11705);
INSERT INTO stanza VALUES('ZS209','4','我今尽情吃生命树，<br/>因为吃就是路！<br/>生命借吃加我里头，<br/>使我凭祂而活。<br/>','',58147,11706);
INSERT INTO stanza VALUES('ZS210','1','神已将祂儿子赐下，<br/>作生命树无比丰富；<br/>要叫人人一尝便知，<br/>神是我们食物。<br/>神是我们食物！<br/>神是我们食物！<br/>我们尝过就作见证，<br/>神是我们食物！<br/>','',58148,11707);
INSERT INTO stanza VALUES('ZS210','2','借吃把主接受进去；<br/>凭主而活，并不吃力，<br/>因为我们所吃筵席<br/>全是主的自己。<br/>主是我们筵席！<br/>主是我们筵席！<br/>我们吃主，因主活着，<br/>主是我们筵席！<br/>','',58149,11708);
INSERT INTO stanza VALUES('ZS210','3','我们所吃乃是基督─<br/>是粮，是肉，属天食物；<br/>生命供应，营养充足，<br/>我们天天吃主！<br/>我们天天吃主，<br/>我们天天吃主，<br/>生命供应，营养充足，<br/>我们天天吃主！<br/>','',58150,11709);
INSERT INTO stanza VALUES('ZS210','4','吃这筵席，真是享福！<br/>应有尽有，极其丰富！<br/>无论何人，凡是愿意，<br/>都可白白来吃。<br/>都可白白来吃，<br/>都可白白来吃，<br/>无论何人，凡是愿意，<br/>都可白白来吃。<br/>','',58151,11710);
INSERT INTO stanza VALUES('ZS211','1','经上记着：<br/>人活着不是单靠食物，<br/>乃是靠着神口里<br/>所出的一切话。<br/>（太四4）<br/>','',58152,11711);
INSERT INTO stanza VALUES('ZS211','chorus','阿利路亚！阿利路亚！<br/>阿利路亚！阿们，<br/>阿利路亚！<br/>','',58153,11712);
INSERT INTO stanza VALUES('ZS211','2','叫人活着的是灵，<br/>肉体是无益的；<br/>我对你们说的话，<br/>就是灵、是生命。<br/>（约六63）<br/>','',58154,11713);
INSERT INTO stanza VALUES('ZS211','3','我得着你的言语，<br/>就当食物吃了。<br/>你的话在我心中，<br/>是我欢喜快乐。<br/>（耶十五16）<br/>','',58155,11714);
INSERT INTO stanza VALUES('ZS211','4','要拿着灵的宝剑，<br/>这灵是神的话─<br/>借着多方的祷告，<br/>每次都在灵里。<br/>（弗六17～18）<br/>','',58156,11715);
INSERT INTO stanza VALUES('ZS211','5','要借着话里的水，<br/>来把召会洗净，<br/>成为圣洁，献给主，<br/>作荣耀的召会。<br/>（弗五26～27）<br/>','',58157,11716);
INSERT INTO stanza VALUES('ZS212','1','哦，主耶稣，<br/>我们在你前称颂，<br/>为着杯饼我们感激不已；<br/>同心赞美，<br/>你竟然成为食物，<br/>叫人多方享受你的自己。<br/>','',58158,11717);
INSERT INTO stanza VALUES('ZS212','chorus','我心我灵立即兴起赞美，<br/>你何微小，你何微小。<br/>直至永世还要吃喝不已，<br/>你何微小，你何微小。<br/>','',58159,11718);
INSERT INTO stanza VALUES('ZS212','2','何等可怜─<br/>当基督来到人群，<br/>满带丰盛，<br/>来作生命供应，<br/>人竟拒绝，<br/>反倚靠道理教训，<br/>不懂如何取用祂的丰盛。<br/>','',58160,11719);
INSERT INTO stanza VALUES('ZS212','chorus','我们所需乃是把你吃了，<br/>何等奇妙，何等逍遥！<br/>我们吃主，<br/>里面就被复苏。<br/>长大成人，活出基督。<br/>','',58161,11720);
INSERT INTO stanza VALUES('ZS212','3','哦主耶稣，<br/>你降卑来到世上，<br/>并非为着在外面作君王；<br/>乃作食物<br/>供我们享受饱足，<br/>里面生命引导我们成熟。<br/>','',58162,11721);
INSERT INTO stanza VALUES('ZS212','4','主，赞美你，<br/>你实在伟大荣耀，<br/>能力无穷，<br/>威严、丰富无限，<br/>但你竟成<br/>微小食物真奇妙，<br/>我们更要高唱直到永远。<br/>','',58163,11722);
INSERT INTO stanza VALUES('ZS213','1','胜哉、胜哉、胜哉，<br/>完全回到起初！<br/>神今在基督里，<br/>成为我们食物。<br/>吃喝、吃喝、吃喝，<br/>我们尽情吃喝；<br/>在神恢复里，<br/>我不知太多。<br/>','',58164,11723);
INSERT INTO stanza VALUES('ZS213','2','大声呼喊耶稣，<br/>哦，我们真饱足！<br/>主在我们口中，<br/>只等我们来吃。<br/>用灵大声呼喊，<br/>远胜默默点头；<br/>在神恢复里，<br/>我不知太多。<br/>','',58165,11724);
INSERT INTO stanza VALUES('ZS213','3','细嚼、细嚼、细嚼，<br/>不是外面工作；<br/>放下你的重担，<br/>再来坐下吃喝。<br/>坐席、坐席、坐席，<br/>教训束之高阁！<br/>在神恢复里，<br/>我只知吃喝。<br/>','',58166,11725);
INSERT INTO stanza VALUES('ZS214','1','主曾召你我得救，<br/>祂再召你我得胜。<br/>对主呼召说『阿们』─<br/>要得胜！<br/>召会光景堕落了，<br/>许多道理都知道，<br/>生命却是摸不着─<br/>要得胜！<br/>','',58167,11726);
INSERT INTO stanza VALUES('ZS214','chorus','要得胜！要得胜！<br/>胜过死沉的宗教，<br/>要得胜！<br/>放下所有的辛劳，<br/>脱离一切的老套，<br/>只管单单来吃主─<br/>要得胜！<br/>','',58168,11727);
INSERT INTO stanza VALUES('ZS214','2','神原命定人来吃，<br/>吃是今日的恢复，<br/>吃是得胜的道路─<br/>要得胜！<br/>快来享受生命树，<br/>脱去道理的束缚，<br/>得胜借着吃基督─<br/>要得胜！<br/>','',58169,11728);
INSERT INTO stanza VALUES('ZS214','3','教训不能变化魂，<br/>叫神旨意受亏损，<br/>吃主搆上神标准─<br/>要得胜！<br/>若要得胜就要吃，<br/>无论聚集或独处，<br/>吃到全人得饱足─<br/>要得胜！<br/>','',58170,11729);
INSERT INTO stanza VALUES('ZS214','4','速速催促主再来，<br/>借着吃喝产男孩，<br/>现在吃祂，<br/>一直吃─要得胜！<br/>为着主的金灯台，<br/>为着得胜的男孩，<br/>为着新妇祂所爱─<br/>要得胜！<br/>','',58171,11730);
INSERT INTO stanza VALUES('ZS215','1','『你们来吃，』<br/>主正在呼召，<br/>『你们来吃。』<br/>我们可以随时随刻<br/>吃喝主！<br/>祂是『日用的饮食，』<br/>祂才能叫人满足。<br/>『你们来吃，』<br/>主正在呼召，<br/>『你们来吃。』<br/>','',58172,11731);
INSERT INTO stanza VALUES('ZS215','2','『你们来吃，』<br/>主正在呼召，<br/>『你们来吃。』<br/>我们若是随时随刻<br/>吃喝主，<br/>祂就作我们生命，<br/>一直到生命满出！<br/>『你们来吃，』<br/>主正在呼召，<br/>『你们来吃。』<br/>','',58173,11732);
INSERT INTO stanza VALUES('ZS216','1','喝！从宝座流出<br/>纯净生命河的水！<br/>吃！生命树果子，<br/>丰硕又累累垂垂！<br/>看！那满城光辉，<br/>不需灯光或日、月，<br/>她没有黑夜！<br/>','',58174,11733);
INSERT INTO stanza VALUES('ZS216','chorus','来罢！哦，来罢！<br/>圣灵与新妇说；<br/>来罢！哦，来罢！<br/>听见的人也说；<br/>来罢！哦，来罢！<br/>口渴又愿意的<br/>可白白来喝！<br/>','',58175,11734);
INSERT INTO stanza VALUES('ZS216','2','基督乃是我们河水，<br/>在里面涌流；<br/>基督乃是生命树果，<br/>供我们享受；<br/>基督乃是我们的光、<br/>晨星与白昼；<br/>祂乃是万有！<br/>','',58176,11735);
INSERT INTO stanza VALUES('ZS216','3','我们洗净袍子，<br/>有权来吃生命树，<br/>『哦主，阿们，<br/>阿利路亚，』<br/>我们真有福！<br/>我们操练我们的灵，<br/>来经历基督─<br/>何等的基督！<br/>','',58177,11736);
INSERT INTO stanza VALUES('ZS216','4','现在我们有一个家，<br/>辉煌胜太阳，<br/>弟兄姊妹同心站住<br/>合一的立场；<br/>地方召会乃是<br/>新耶路撒冷豫尝─<br/>何等的豫尝！<br/>','',58178,11737);
INSERT INTO stanza VALUES('ZS217','1','我们来，我们来，<br/>到神殿里来；我们来，<br/>从神殿有水流出来。<br/>这水流，在殿右，<br/>昼夜涌流着，滋润我们，<br/>结出生命的美果。<br/>','',58179,11738);
INSERT INTO stanza VALUES('ZS217','2','从这殿，从这殿，<br/>涌出这水流，<br/>从这殿到全地，<br/>生命在涌流，<br/>愿这水流加深，<br/>主，听我们求，我们就必<br/>被你量过并占有。<br/>','',58180,11739);
INSERT INTO stanza VALUES('ZS217','3','量我们，量我们，<br/>天天量又量，<br/>量我们，量更多，<br/>一直量又量，<br/>直到我们看见<br/>水流成江河，流通全地，<br/>使人全被主点活。<br/>','',58181,11740);
INSERT INTO stanza VALUES('ZS217','4','领我们，领我们，<br/>从水流经过，<br/>领我们从水流，<br/>经过再经过，<br/>水流一直涨高，<br/>成可洑的水，<br/>我们被浸透，<br/>永远享神恩惠。<br/>','',58182,11741);
INSERT INTO stanza VALUES('ZS217','5','都必活，都必活，<br/>随流都必活，<br/>都必活，真正活，<br/>百物随流活，<br/>愿这水流带来<br/>丰盛的生命，<br/>直到众召会<br/>在全地都显明。<br/>','',58183,11742);
INSERT INTO stanza VALUES('ZS218','1','我们在喝生命的水，<br/>活水涌出如同江河！<br/>喝了这水，主曾明说，<br/>就永远永远不再渴！<br/>难道永远不再渴？是！<br/>永远不再渴！<br/>难道永远不再渴？是！<br/>永远不再渴！<br/>喝了这水，主曾明说，<br/>就永远永远不再渴。<br/>','',58184,11743);
INSERT INTO stanza VALUES('ZS218','2','我们在吃生命的粮─<br/>神的筵席为人摆设；<br/>吃了这粮，主曾明说，<br/>就永远永远不再饿。<br/>难道永远不再饿？是！<br/>永远不再饿！<br/>难道永远不再饿？是！<br/>永远不再饿！<br/>吃了这粮，主曾明说，<br/>就永远永远不再饿。<br/>','',58185,11744);
INSERT INTO stanza VALUES('ZS218','3','我们在吸生命之气，<br/>就是那赐生命的灵；<br/>吸了这气─直到永远，<br/>就必定有神的生命。<br/>难道有神的生命？是！<br/>有神的生命！<br/>难道有神的生命？是！<br/>有神的生命！<br/>吸了这气─直到永远，<br/>都必定有神的生命。<br/>','',58186,11745);
INSERT INTO stanza VALUES('ZS218','4','我们在尝生命之酒，<br/>神圣芬芳绝无仅有；<br/>尝了这酒─每时每刻，<br/>都必定有神的喜乐。<br/>难道有神的喜乐？是！<br/>有神的喜乐！<br/>难道有神的喜乐？是！<br/>有神的喜乐！<br/>尝了这酒─每时每刻，<br/>都必定有神的喜乐。<br/>','',58187,11746);
INSERT INTO stanza VALUES('ZS218','5','基督是王死而复活，<br/>赐人生命丰盛阔绰；<br/>你接受祂，也必高歌，<br/>并且要永远的活着。<br/>难道永远的活着？是！<br/>永远的活着！<br/>难道永远的活着？是！<br/>永远的活着！<br/>你接受祂，也必高歌，<br/>并且要永远的活着！<br/>','',58188,11747);
INSERT INTO stanza VALUES('ZS219','1','活水涌流，<br/>（涌流！涌流！）<br/>生命水涌流，<br/>（涌流！涌流！）<br/>满带神生命，<br/>（生命！生命！）<br/>生命的供应，<br/>（供应！供应！）<br/>使我们成形，<br/>（成形！成形！）<br/>成为祂荣形，<br/>（荣形！荣形！）<br/>流成祂模样，<br/>神和人都在此得着满足。<br/>生命何丰富，<br/>喜乐何满足，<br/>奇妙甘甜，越过越富，<br/>主是何深厚，<br/>永不能测透，<br/>却流经我身给我享受。<br/>享受，享受不尽，<br/>成长，成长不停，<br/>流出宝石、精金，<br/>成为神居所荣耀见证。<br/>','',58189,11748);
INSERT INTO stanza VALUES('ZS220','1','我曾经在巴比伦地<br/>干渴度日；<br/>始终无何能使我心满足。<br/>但有一天<br/>我来到蒙福的召会，<br/>我才找着那洋溢的活水。<br/>','',58190,11749);
INSERT INTO stanza VALUES('ZS220','chorus','我今饮于生命活水泉源，<br/>我喜出望外，<br/>满足溢于全人！<br/>我今饮于生命活水泉源，<br/>奇妙丰富的供应到永远。<br/>','',58191,11750);
INSERT INTO stanza VALUES('ZS220','2','从宝座流出的水<br/>何等的甘甜，<br/>经常流进、流出，<br/>在我里面。<br/>如今我找着<br/>长久渴慕的泉源，<br/>在此生命极丰盛又新鲜。<br/>','',58192,11751);
INSERT INTO stanza VALUES('ZS220','3','亲爱的弟兄，<br/>为何不同来聚集？<br/>又深又广的泉源等着你！<br/>好牧人巴望<br/>领你到地方召会，<br/>祂要使你多年心愿得遂！<br/>','',58193,11752);
INSERT INTO stanza VALUES('ZS221','1','恩典实际涌自基督，<br/>尽管畅饮于活泉！<br/>我们赞美，歌唱不倦，<br/>在召会（家）里面。<br/>','',58194,11753);
INSERT INTO stanza VALUES('ZS221','chorus','荣耀归神！<br/>我们畅饮于活泉！<br/>荣耀归神！<br/>我们在家里面。<br/>','',58195,11754);
INSERT INTO stanza VALUES('ZS221','2','主是何等乐意施恩，<br/>尽管畅饮于活泉！<br/>不必天涯海角去找，<br/>祂是在家里面。<br/>','',58196,11755);
INSERT INTO stanza VALUES('ZS221','3','任凭撒但多方打岔，<br/>尽管畅饮于活泉！<br/>无论何时，撒但不能<br/>丝毫胜过我们。<br/>','',58197,11756);
INSERT INTO stanza VALUES('ZS221','4','你若渴了，火速赶来，<br/>尽管畅饮于活泉！<br/>只管畅饮，不用担心，<br/>你是在家里面。<br/>','',58198,11757);
INSERT INTO stanza VALUES('ZS222','1','阿利路亚，主是生命，<br/>如气给人呼吸！<br/>祂向门徒吹一口气，<br/>并说，<br/>『你们接受圣气。』<br/>现在我们呼吸，<br/>现在我们呼吸，<br/>呼吸我主生命气息。<br/>','',58199,11758);
INSERT INTO stanza VALUES('ZS223','1','基督是那赐生命的灵，<br/>基督也是生命的话；<br/>生命的灵供应我的灵，<br/>基督的话变成生命─<br/>借着天天吃祂、<br/>喝祂、并呼吸祂！<br/>借着天天吃祂、喝祂、<br/>并呼吸祂！<br/>','',58200,11759);
INSERT INTO stanza VALUES('ZS223','2','基督是那赐生命的灵，<br/>基督也是生命的话；<br/>生命的灵供应我的灵，<br/>基督的话变成生命─<br/>借着用灵祷读、<br/>赞美、呼喊主名！<br/>借着用灵祷读、赞美、<br/>呼喊主名！<br/>','',58201,11760);
INSERT INTO stanza VALUES('ZS224','1','一呼一吸我吸主，<br/>阿们！阿们！<br/>一呼一吸我就活，<br/>阿们！阿们！<br/>哦，祂呼出而我吸入，<br/>祂生命从我里流出，<br/>因为我已学会<br/>深深吸入主。<br/>','',58202,11761);
INSERT INTO stanza VALUES('ZS224','2','约翰第三章<br/>是指外面空气，<br/>风在外面吹呀吹，<br/>随意而吹。<br/>并不知牠来自何方，<br/>并不知牠吹往何处，<br/>凡从圣灵生的，<br/>也都是如此。<br/>','',58203,11762);
INSERT INTO stanza VALUES('ZS224','3','约翰二十章<br/>是指里面空气，<br/>主耶稣所呼出的<br/>生命之气，<br/>只要我们接受这气─<br/>不必思虑，只要呼吸；<br/>我们经历生命<br/>是借着这气。<br/>','',58204,11763);
INSERT INTO stanza VALUES('ZS224','4','无论在那里都有<br/>空气，空气！<br/>牠包围笼罩我们，<br/>随时、随地！<br/>白白赐给，丰富便利，<br/>我们生活丰盛无比；<br/>所以弟兄姊妹，<br/>同来吸这气。<br/>','',58205,11764);
INSERT INTO stanza VALUES('ZS224','5','只要来呼喊祂名，<br/>哦主！哦主！<br/>祂就成我们气息，<br/>哦主！哦主！<br/>从最深处吸入祂名，<br/>直到我们充满生命，<br/>这位耶稣是<br/>何等生命供应！<br/>','',58206,11765);
INSERT INTO stanza VALUES('ZS225','1','主对呼喊祂名的人<br/>何等的相近！每次呼喊，<br/>祂的同在就刚强我们！<br/>寻找耶稣，就必寻见；<br/>喊祂，就相近；<br/>我们深得安慰，<br/>因为祂可爱可亲！<br/>','',58207,11766);
INSERT INTO stanza VALUES('ZS225','chorus','耶稣，何等的名！<br/>哦，主耶稣，赐生命名！<br/>得胜的名，荣耀的名，<br/>超越的名─何等的名！<br/>耶稣，刚强的名！<br/>哦，主耶稣，安慰的名！<br/>名可常吸入，<br/>可随处喊出；<br/>哦，主耶稣，何等的名！<br/>','',58208,11767);
INSERT INTO stanza VALUES('ZS225','2','只要呼喊耶稣的名，<br/>你就必得救。<br/>哦！主耶稣，阿利路亚，<br/>从此不被囚！<br/>我们举起救恩之杯，<br/>呼喊祂的名，<br/>祂便拯救我们<br/>脱离多少的事情！<br/>','',58209,11768);
INSERT INTO stanza VALUES('ZS225','3','犹太人或希利尼人，<br/>并没有差异，<br/>主对呼喊祂名的人<br/>都是丰富的。<br/>哦主耶稣，呼喊你名，<br/>活着真喜乐！<br/>每当把你的名吸入，<br/>我们就快活！<br/>','',58210,11769);
INSERT INTO stanza VALUES('ZS225','4','我们欣然享受<br/>经常施恩的救主，<br/>无论祸福，无论乐苦，<br/>都呼喊如故！<br/>只要我有气息活着，<br/>我就必喊主，<br/>因祂乐意侧耳倾听，<br/>恩典常倾注！<br/>','',58211,11770);
INSERT INTO stanza VALUES('ZS225','5','我们如此乐而不疲<br/>呼喊主的名，<br/>对主赞美感激之情<br/>便油然而生。<br/>我们乃是那些<br/>随处呼喊主的人，<br/>与那清心爱主的人<br/>同呼喊蒙恩。<br/>','',58212,11771);
INSERT INTO stanza VALUES('ZS226','1','有一婴孩，<br/>祂是全能的神；<br/>有一儿子，<br/>祂是永在的父。<br/>哦，何奇妙！<br/>神人相调在祂身；<br/>来作策士，<br/>完成永远救赎。<br/>国度政权，<br/>必担在祂肩头上！<br/>和平的君，<br/>平安加增无穷！<br/>','',58213,11772);
INSERT INTO stanza VALUES('ZS227','1','祂的名是奇妙，<br/>祂的名是策士，<br/>祂是全能的神，<br/>永在的父；<br/>有一婴孩降生，<br/>一子赐给我们，<br/>祂是和平的君，<br/>耶稣我主。<br/>赞美创造主，<br/>耶稣我救主，<br/>生命的灵内住；<br/>在灵里敬拜祂，<br/>爱祂并事奉祂，<br/>祂的名是奇妙，<br/>耶稣我主。<br/>','',58214,11773);
INSERT INTO stanza VALUES('ZS228','1','我们今活着<br/>是靠着吸入主，<br/>并非靠思想活着，<br/>惟呼吸才是路。<br/>我们从里面最深处喊<br/>『哦主！』<br/>满心喜乐作见证，<br/>我们在吸入主。<br/>','',58215,11774);
INSERT INTO stanza VALUES('ZS228','chorus','吸入主，吸入主，<br/>吸入主生命；<br/>祂是生命的供应，<br/>吸入主不稍停！<br/>吸入主，吸入主，<br/>吸入主生命；<br/>祂是生命的供应，<br/>吸入主不稍停！<br/>','',58216,11775);
INSERT INTO stanza VALUES('ZS228','2','祂真是奇妙，<br/>祂是生命的气，<br/>原来祂在肉身里，<br/>如今作我气息；<br/>祂改变形状，<br/>如今乃是那灵─<br/>神所呼出是基督，<br/>我所吸入是灵。<br/>','',58217,11776);
INSERT INTO stanza VALUES('ZS228','chorus','基督是我生命，<br/>无论在那里，<br/>我呼喊祂的名，<br/>就得着祂气息！<br/>','',58218,11777);
INSERT INTO stanza VALUES('ZS229','1','哦，主耶稣！<br/>哦，主耶稣！<br/>呼喊你名何甘甜！<br/>比酒更美，比蜜更甜；<br/>哦，主耶稣！阿们。<br/>','',58219,11778);
INSERT INTO stanza VALUES('ZS230','1','我们已经找到<br/>摸着主的最简单的路，<br/>主曾应许凡呼喊祂的人<br/>必蒙祂垂顾，<br/>因此只要我们<br/>从灵里面来向主呼喊，<br/>就可以摸着主。<br/>哦！主，阿们，<br/>阿利路亚！<br/>哦！主，阿们，<br/>阿利路亚！<br/>哦！主，阿们，<br/>阿利路亚！<br/>如此就摸着主。<br/>','',58220,11779);
INSERT INTO stanza VALUES('ZS231','1','每当我喊主耶稣，<br/>我深处总觉发烫；<br/>祂生命冉冉而升上，<br/>在我里面成长。<br/>请来同喊主耶稣，<br/>这喜乐地上无双；<br/>主且要进入你里面，<br/>作你生命供你享。<br/>','',58221,11780);
INSERT INTO stanza VALUES('ZS231','2','请来同喊主耶稣，<br/>祂必使你得释放─<br/>不管你的心多疏远，<br/>或如野马脱缰。<br/>只要简单的喊主，<br/>不管你在何地方；<br/>一呼喊立刻祂就来，<br/>祂原近在你口旁。<br/>','',58222,11781);
INSERT INTO stanza VALUES('ZS231','3','呼喊我们的救主，<br/>每次祂都必垂听。<br/>何不来投靠祂胸怀，<br/>重担立变轻盈！<br/>祂是我们的山寨，<br/>是喜乐、安息、力量；<br/>只要你尝尝便知道，<br/>祂恩典真是无量。<br/>','',58223,11782);
INSERT INTO stanza VALUES('ZS231','4','上好乃是主自己，<br/>等着你白白接受。<br/>让我们向祂全敞开，<br/>让祂生命拯救！<br/>当祂再来的时候，<br/>我们不惊惶失措，<br/>并且要面见祂荣耀，<br/>若一直让祂成熟。<br/>','',58224,11783);
INSERT INTO stanza VALUES('ZS232','1','当你说『主』，你是把<br/>难以形容的一语道出；<br/>当你说『主』，<br/>你宣告你所要的<br/>只是那『万主之主』。<br/>除祂再无爱慕，<br/>万事尽是虚无；<br/>祂是一切一切，<br/>在祂一无所缺。<br/>当你说『主耶稣』，<br/>你说出一切。<br/>','',58225,11784);
INSERT INTO stanza VALUES('ZS233','1','呼喊『哦，主耶稣！』<br/>这使我们灵刚强！<br/>在灵里摸着主，<br/>忧郁就变成颂扬！<br/>切勿听从撒但，<br/>切勿受他的打岔，<br/>只要回到灵里行动，<br/>毫不惧怕！<br/>呼喊『哦，主耶稣，』<br/>就必终日将祂享！<br/>','',58226,11785);
INSERT INTO stanza VALUES('ZS234','1','『哦，主耶稣！』<br/>喊祂名，<br/>使我终日运用灵；<br/>不断呼喊祂的名，<br/>祂就来充满我灵。<br/>','',58227,11786);
INSERT INTO stanza VALUES('ZS234','chorus','喊：『哦，主耶稣！』<br/>喊：『哦，主耶稣！』<br/>喊：『哦，主耶稣！』<br/>终日喊主耶稣！<br/>','',58228,11787);
INSERT INTO stanza VALUES('ZS234','2','『哦，主耶稣！』<br/>就是路，<br/>使我不至走迷途。<br/>不分昼夜常呼求，<br/>祂必向我施拯救。<br/>','',58229,11788);
INSERT INTO stanza VALUES('ZS234','3','现在从魂转入灵，<br/>『哦，主耶稣！』<br/>喊祂名。<br/>从我自己转向主，<br/>终日呼喊『主耶稣！』<br/>','',58230,11789);
INSERT INTO stanza VALUES('ZS234','4','如此呼喊充满主，<br/>祂是圣灵，生命主。<br/>呼喊向祂来表示，<br/>我之爱祂永不止。<br/>','',58231,11790);
INSERT INTO stanza VALUES('ZS235','1','我时刻呼喊主名，<br/>当我往前行，<br/>我时刻呼喊主名，<br/>祂使我欢腾；<br/>虽然黑云笼罩天空，<br/>遮蔽我路程，<br/>我只要呼喊主名，<br/>祂必显权能。<br/>祂是我朋友，<br/>最信实忠诚，<br/>我可倚靠祂，<br/>直走完路程。<br/>我时刻呼喊主名，<br/>当我往前行，<br/>我时刻呼喊主名，<br/>祂使我欢腾；<br/>虽然黑云笼罩天空，<br/>遮蔽我路程，<br/>我只要呼喊主名，<br/>祂必显权能。<br/>','',58232,11791);
INSERT INTO stanza VALUES('ZS236','1','自从基督释放我，<br/>我心充满了喜乐。<br/>自从基督释放我，<br/>我口高声唱新歌。<br/>终日将祂名呼喊，<br/>我过天上的生活，<br/>何等的平安！<br/>何等的丰满！<br/>自从基督释放我！<br/>','',58233,11792);
INSERT INTO stanza VALUES('ZS237','1','在早晨我们呼喊：<br/>『哦，主耶稣！』<br/>午间我们呼喊：<br/>『哦，主耶稣！』<br/>在晚上我们呼喊：<br/>『哦，主耶稣！』<br/>终日我们呼喊：<br/>『哦，主耶稣！』<br/>祂就住在灵里面；<br/>勿别处浪费时间。<br/>赞美主！赞美主！哦…<br/>','',58234,11793);
INSERT INTO stanza VALUES('ZS237','2','在灵里呼喊，<br/>享受祂的丰富；<br/>在灵里叹息，<br/>必能摸着主；<br/>在灵里祷告，<br/>直到焚烧，高昂；<br/>住在灵里面，<br/>必像祂刚强。<br/>有分祂丰盛生命，<br/>渐渐变成主荣形。<br/>荣耀，阿利路亚！<br/>荣耀归主名！<br/>荣耀，阿利路亚！<br/>荣耀归主名！<br/>','',58235,11794);
INSERT INTO stanza VALUES('ZS238','1','在主耶稣名下，<br/>在主耶稣名下，<br/>我们就必得胜！<br/>在主耶稣名下，<br/>在主耶稣名下，<br/>撒但惧怕无能。<br/>在我们主耶稣名下，<br/>无人能够抵挡；<br/>在主耶稣名下，<br/>我们就必得胜！<br/>','',58236,11795);
INSERT INTO stanza VALUES('ZS239','1','『金银财宝我没有，<br/>只把我所有的给你；<br/>我奉耶稣基督的名，<br/>叫你现在起来行走！』<br/>他就走着，又跳着，<br/>又赞美神；走着，<br/>又跳着，又赞美神。<br/>阿利路亚，赞美我主！<br/>荣耀，荣耀归于主名！<br/>','',58237,11796);
INSERT INTO stanza VALUES('ZS239','2','金银财宝我没有，<br/>却有七倍加强的灵；<br/>我奉耶稣基督的名，<br/>刚强站起作祂见证！<br/>我在召会中<br/>又赞美又见证，<br/>召会中又赞美又见证。<br/>阿利路亚，赞美我主！<br/>荣耀，荣耀归于主名！<br/>','',58238,11797);
INSERT INTO stanza VALUES('ZS240','1','基督美地，丰富之地，<br/>神已赐给我们了！<br/>山、谷、泉、源，<br/>流水潺潺，<br/>阿利路亚何荣耀！<br/>','',58239,11798);
INSERT INTO stanza VALUES('ZS240','2','基督美地，丰富之地，<br/>神已赐给我们了！<br/>有奶有蜜，分文不要，<br/>白白恩典，何荣耀！<br/>','',58240,11799);
INSERT INTO stanza VALUES('ZS240','3','基督美地，丰富之地，<br/>神已赐给我们了！<br/>有葡萄树，无花果树，<br/>丰富供应给我们！<br/>','',58241,11800);
INSERT INTO stanza VALUES('ZS240','4','基督美地，丰富之地，<br/>神已赐给我们了！<br/>五谷和油，我们享受，<br/>无限无量，何荣耀！<br/>','',58242,11801);
INSERT INTO stanza VALUES('ZS240','5','同来经营，同来经营，<br/>在美地上同经营！<br/>昼夜不息，带着能力，<br/>收获丰富，何荣耀！<br/>','',58243,11802);
INSERT INTO stanza VALUES('ZS240','6','在聚会中，在聚会中，<br/>荣耀筵席将主尝！<br/>美地出产，上好肥甘，<br/>带来献上同分享！<br/>','',58244,11803);
INSERT INTO stanza VALUES('ZS240','7','阿利路亚，阿利路亚，<br/>美地神给我们了！<br/>经营不息，享受不已，<br/>阿利路亚，何荣耀！<br/>','',58245,11804);
INSERT INTO stanza VALUES('ZS241','1','基督是神所应许的美地，<br/>靠祂而争战，<br/>必赶出仇敌；<br/>跟随主元帅，<br/>进入得安息，<br/>这地是为着我和你。<br/>','',58246,11805);
INSERT INTO stanza VALUES('ZS241','2','高大的城邑，<br/>非你建造的；<br/>房屋满美物，<br/>非你装满的；<br/>凿成的水井，<br/>非你凿成的；<br/>葡萄，橄榄非你栽的。<br/>','',58247,11806);
INSERT INTO stanza VALUES('ZS241','3','有河有泉源，<br/>谷中有水溪，<br/>有小麦、大麦、<br/>果树、油和蜜，<br/>居住在这地，<br/>必永不缺食；<br/>山可挖铜，地有铁石。<br/>','',58248,11807);
INSERT INTO stanza VALUES('ZS241','4','我们同欢乐，<br/>歌唱于锡安；<br/>我们同向前，<br/>进入祂美善；<br/>新酒和五谷，<br/>出产肥而甘；<br/>这地实在又丰又满。<br/>','',58249,11808);
INSERT INTO stanza VALUES('ZS241','5','基督是我的，<br/>基督是你的，<br/>我们分享祂，<br/>并不分彼此，<br/>哦，我们产业，<br/>广大达四极；<br/>全地是为着我们的。<br/>','',58250,11809);
INSERT INTO stanza VALUES('ZS241','6','这广大享受，<br/>这丰盈之地，<br/>路上滴脂油，<br/>到处是乳蜜，<br/>恩重重四溢！<br/>哦，尝尝便知，<br/>基督是我们的美地。<br/>','',58251,11810);
INSERT INTO stanza VALUES('ZS241','7','祂道成肉身，<br/>受尽人欺厌，<br/>由死而复活，<br/>升上了高天，<br/>得荣耀尊贵，<br/>作祂的冠冕；<br/>美地今在我们里面。<br/>','',58252,11811);
INSERT INTO stanza VALUES('ZS241','7','我们同经营内住的基督；<br/>将丰余收获献上作食物；<br/>如此献基督，<br/>神、人得饱足；<br/>我们歌颂永不止住。<br/>','',58253,11812);
INSERT INTO stanza VALUES('ZS241','9','赞美神使祂成为我美地；<br/>赞美神使祂成为你美地；<br/>哦，阿利路亚！<br/>荣耀的美地；<br/>我们今住基督美地！<br/>','',58254,11813);
INSERT INTO stanza VALUES('ZS242','1','美地，美地，<br/>神已赐给我们；<br/>基督是神所赐美地。<br/>这是召会合一，<br/>大家来在一起，<br/>脱离弯曲世代，<br/>世界完全丢弃！<br/>','',58255,11814);
INSERT INTO stanza VALUES('ZS242','2','来罢！来罢！<br/>我们来得这地，<br/>今日行走在基督里。<br/>我们站住立场，<br/>一同经营这地，<br/>生命长进成熟，<br/>迎接主的再临。<br/>','',58256,11815);
INSERT INTO stanza VALUES('ZS242','3','基督，基督，<br/>无比丰富肥甘！<br/>召会是基督的丰满！<br/>我们经历实际，<br/>显出敬拜真意，<br/>见证那位奇妙者，<br/>使万人归依。<br/>','',58257,11816);
INSERT INTO stanza VALUES('ZS243','1','来得这地，<br/>神已将这地赐我们；<br/>平日生活，<br/>可满基督丰富。<br/>来得这地，所需装备，<br/>一样不缺─宝血、<br/>见证的话、灵与召会。<br/>','',58258,11817);
INSERT INTO stanza VALUES('ZS243','chorus','（女声）<br/>来得这地，<br/>哦，弟兄们哪！<br/>神赐这地给我们了。<br/>刚强去争战，<br/>我们必得胜！<br/>来得这地，何等荣耀！<br/>（男声）<br/>来得这地，<br/>哦，姊妹们哪！<br/>投身其中，紧紧跟随；<br/>祂正在呼召，<br/>祂走在前头，<br/>所需一切祂已赐给！<br/>','',58259,11818);
INSERT INTO stanza VALUES('ZS243','2','我们有血，<br/>基督是无瑕疵的祭，<br/>祂舍自己，<br/>使神完全满意；<br/>所以我们到神面前，<br/>坦然无惧，<br/>只要我们宝血不断支取。<br/>','',58260,11819);
INSERT INTO stanza VALUES('ZS243','3','我们有话，<br/>神话乃是我们食物，<br/>我们用信调话并说<br/>『阿们，』在每日中，<br/>圣灵再向我们说话，<br/>祂从里面规律调整我们。<br/>','',58261,11820);
INSERT INTO stanza VALUES('ZS243','4','我们有灵，<br/>这灵乃是实际的灵，<br/>不以我们的感觉作根据。<br/>内住的灵，<br/>教导我们住在祂里，<br/>引导我们进入一切实际。<br/>','',58262,11821);
INSERT INTO stanza VALUES('ZS243','5','我们还有召会，<br/>她是何等宝贝！<br/>经历丰满，<br/>圣徒不可或缺！<br/>我们同聚必得<br/>这包罗万有主，<br/>祂是我们一切中的一切！<br/>','',58263,11822);
INSERT INTO stanza VALUES('ZS244','1','行走在这美地，<br/>这使我们灵刚强！<br/>经营在这美地，<br/>享受基督无限量！<br/>祂的丰富，丰满，<br/>并祂一切的能力，<br/>每时每刻<br/>成为我们所经所历！<br/>祂是一切一切，<br/>我们今住在美地。<br/>','',58264,11823);
INSERT INTO stanza VALUES('ZS245','1','我们在美地，<br/>我们在美地！<br/>哦，阿利路亚！在美地！<br/>基督是美地，<br/>基督是美地！<br/>哦，赞美主，祂是美地！<br/>祂就是奶，祂也是蜜；<br/>五谷和油、新酒无比。<br/>我们在美地，<br/>我们在美地！<br/>哦，阿利路亚！在美地！<br/>','',58265,11824);
INSERT INTO stanza VALUES('ZS245','2','美地之上有许多的丰富：小麦、大麦、各种果树；<br/>有泉、源、水流，<br/>涌流到永远，<br/>何等美地摆在眼前！<br/>为要得着地里出产，<br/>我们天天经营无间；<br/>每逢同聚集都带来基督─<br/>『上好』基督作为供物！<br/>','',58266,11825);
INSERT INTO stanza VALUES('ZS246','1','主，你是那宽阔<br/>与高超的美地，<br/>让我们来享受，<br/>天天经营行走！<br/>活水泉源涌流，<br/>经历钉死复活，<br/>产生新酒美果，<br/>牛羊奶蜜和油。<br/>','',58267,11826);
INSERT INTO stanza VALUES('ZS246','2','我们乃是活石，<br/>成为建造材料，<br/>凿成七根柱子，<br/>完成神的目标！<br/>取用得胜基督，<br/>奋勇与敌争战，<br/>带进神的国度，<br/>掌权直到永远。<br/>','',58268,11827);
INSERT INTO stanza VALUES('ZS247','1','早晨我们经营，<br/>晌午我们经营，<br/>傍晚我们经营，<br/>经营不稍怠；<br/>美地出产成熟，<br/>一同欢乐收割，<br/>每逢我们聚集，<br/>禾捆都带来。<br/>','',58269,11828);
INSERT INTO stanza VALUES('ZS247','chorus','禾捆都带来，<br/>禾捆都带来，<br/>我们喜乐满怀，<br/>禾捆都带来。<br/>禾捆都带来，<br/>禾捆都带来，<br/>我们喜乐满怀，<br/>禾捆都带来。<br/>','',58270,11829);
INSERT INTO stanza VALUES('ZS247','2','收割小麦、大麦，<br/>经历死与复活，<br/>虽然遭受损失，<br/>旧人也被埋；<br/>但在复活里面，<br/>经历丰盛生命。<br/>每逢我们聚集，<br/>禾捆都带来。<br/>','',58271,11830);
INSERT INTO stanza VALUES('ZS247','3','葡萄酒、无花果、<br/>石榴与橄榄油，<br/>舒畅、甘美、<br/>丰盛、高贵又可爱；<br/>公牛、羔羊赎罪，<br/>奶蜜丰富甘甜─<br/>上好十分之一，<br/>禾捆都带来。<br/>','',58272,11831);
INSERT INTO stanza VALUES('ZS301','1','耶稣！我爱你，<br/>你爱来吸引，<br/>使我渴慕亲近你，<br/>快跑跟随你。<br/>使我渴慕亲近你，<br/>快跑跟随你。<br/>你是我良人，<br/>哦，全然美丽可爱，<br/>我心朝夕依依恋恋的。<br/>你是我良人，<br/>哦，全然美丽可爱，<br/>我心中所依依恋恋的。<br/>','',58273,11832);
INSERT INTO stanza VALUES('ZS301','2','你爱，主耶稣，<br/>比酒更甜美，<br/>你膏油所发香气，<br/>使我心欢喜。<br/>你膏油所发香气，<br/>使我心欢喜。<br/>你是园中泉，<br/>你又是活水的井，<br/>流自利巴嫩山的溪涧。<br/>你是园中泉，<br/>你又是活水的井，<br/>流自利巴嫩山的溪涧。<br/>','',58274,11833);
INSERT INTO stanza VALUES('ZS301','3','来罢，我良人，<br/>同到园子里，<br/>使其中各种香气，<br/>发出并漫溢。<br/>使其中各种香气，<br/>发出并漫溢。<br/>『我新妇妹子，<br/>我到了我的园子，<br/>尽情享受酒奶和蜂蜜。<br/>我新妇妹子，<br/>我到了我的园子，<br/>尽情享受酒奶和蜂蜜。』<br/>','',58275,11834);
INSERT INTO stanza VALUES('ZS301','4','把我，主耶稣，<br/>铭刻你心上，<br/>嫉恨残忍如阴间，<br/>爱如死坚强。<br/>嫉恨残忍如阴间，<br/>爱如死坚强。<br/>众水不能灭，<br/>大水也不能淹没，<br/>你的爱情无何能替换。<br/>众水不能灭，<br/>大水也不能淹没，<br/>你的爱情无何能替换。<br/>','',58276,11835);
INSERT INTO stanza VALUES('ZS302','1','你名如同倒出香膏，<br/>耶稣，耶稣，<br/>耶稣，耶稣，<br/>你名如同倒出香膏，<br/>你名如同倒出香膏。<br/>','',58277,11836);
INSERT INTO stanza VALUES('ZS302','2','你的爱情比酒更美<br/>………<br/>','',58278,11837);
INSERT INTO stanza VALUES('ZS302','3','所以众童女都爱你<br/>………<br/>','',58279,11838);
INSERT INTO stanza VALUES('ZS302','4','我的良人你甚可爱<br/>………<br/>','',58280,11839);
INSERT INTO stanza VALUES('ZS302','5','我已寻见我心所慕<br/>………<br/>','',58281,11840);
INSERT INTO stanza VALUES('ZS302','6','我拉住祂不容祂走<br/>………<br/>','',58282,11841);
INSERT INTO stanza VALUES('ZS302','7','我的良人愿你快来<br/>………<br/>','',58283,11842);
INSERT INTO stanza VALUES('ZS303','1','多次我曾床上躺卧，<br/>寻找我多年心所至爱，<br/>我寻找祂，却寻不着，<br/>迫我各处游行。<br/>弟兄们哪，请你告诉我，<br/>我心所爱现今在何处，<br/>我好前去把祂带回，<br/>再让我享受祂的爱情。<br/>是你们来将我引领，<br/>我才能得着真实交通；<br/>原来我爱就在身边，<br/>从来不曾远离。<br/>','',58284,11843);
INSERT INTO stanza VALUES('ZS303','2','为何我能成你心爱，<br/>满带着圣灵犹如烟柱，<br/>能效法你的死，复活，<br/>没药乳香显出。<br/>为何我能成为你华轿，<br/>让你能借我行动安息，<br/>我怎能如勇士持刀，<br/>为你防备夜间的袭击。<br/>是因多人巡逻殷勤，<br/>我能在其中得以安稳；<br/>是因你那无量爱情，<br/>琢磨使我成形。<br/>','',58285,11844);
INSERT INTO stanza VALUES('ZS303','3','哦，我渴慕往没药山，<br/>好让我一切全置死地，<br/>可否带我往乳香岗，<br/>直至黑影飞去。<br/>你既称我是全然美丽，<br/>你既享受我至美爱情，<br/>我的眼目夺取你心，<br/>我膏油胜过一切香品。<br/>我就愿意从利巴嫩，<br/>经历你那升天的超越，<br/>我也愿意常住黑门，<br/>夸耀十架得胜。<br/>','',58286,11845);
INSERT INTO stanza VALUES('ZS303','4','哦，愿我唇中常滴蜜，<br/>叫你享受爱情的甜蜜，<br/>哦，愿我生活满香气，<br/>芬芳如利巴嫩。<br/>哦主，我愿你快快前来，<br/>我的全人都归你占有，<br/>关锁的园，禁闭的井，<br/>完全封闭给你的泉源。<br/>北风南风快快兴起，<br/>使我心园能发出香气，<br/>引我良人进祂园内，<br/>享受祂的所有。<br/>','',58287,11846);
INSERT INTO stanza VALUES('ZS304','1','我属我的良人，<br/>祂也是恋慕我。<br/>来罢，我们同往田间去；<br/>我们要在爱里，<br/>同在村庄住宿，<br/>享受你我之间爱情。<br/>','',58288,11847);
INSERT INTO stanza VALUES('ZS304','2','我们早晨起来，<br/>同往葡萄园去，<br/>同享受我们劳苦果实；<br/>葡萄是否开花，<br/>石榴是否放蕊，<br/>我在那里将爱给你。<br/>','',58289,11848);
INSERT INTO stanza VALUES('ZS304','3','风茄是在放香，<br/>新陈果子佳美，<br/>良人哪！这是为你存留；<br/>我的爱都归你，<br/>也把你全享受，<br/>因爱情是如死坚强。<br/>','',58290,11849);
INSERT INTO stanza VALUES('ZS305','1','主耶稣，<br/>你美丽夺了我心，<br/>我全心向你完全敞开；<br/>释放我，<br/>脱离宗教的义务，<br/>只让我永远享你同在。<br/>当我在此注视你的荣耀，<br/>我的心充满了你荣耀；<br/>浸透我，主，<br/>我今恳切求祷，<br/>以你灵与我灵永相调。<br/>','',58291,11850);
INSERT INTO stanza VALUES('ZS305','2','光照者─<br/>我的天何等明亮，<br/>我看见人子在宝座上；<br/>圣别者，<br/>以神的火焰烧我，<br/>直等我因你灼灼发亮！<br/>主，当我初次<br/>看见你荣耀，<br/>自爱与夸耀同归羞惭；<br/>今我心涌出爱戴与颂赞，<br/>品尝你名里一切肥甘。<br/>','',58292,11851);
INSERT INTO stanza VALUES('ZS305','3','宝贝主，<br/>我将真哪哒香膏，<br/>为你爱，欣然打破倾倒，<br/>我的主，<br/>我前来膏你的头，<br/>看哪，主，<br/>为你我献上好。<br/>亲爱主，<br/>我甘愿为你枉费，<br/>爱着你，我深处就满足。<br/>为着你，<br/>贵重油我早豫备，<br/>要将爱从心深处倒出。<br/>','',58293,11852);
INSERT INTO stanza VALUES('ZS305','4','良人哪，<br/>快来到香草山上，<br/>我切慕与你早面对面。<br/>主，请喝<br/>我心所流出之泉，<br/>我巴望永远在你身边。<br/>我并非单独的来爱你，<br/>主，乃是与<br/>众圣作你新妇；<br/>快来罢，<br/>我们爱已经久等，<br/>主耶稣，愿意你得满足。<br/>','',58294,11853);
INSERT INTO stanza VALUES('ZS306','1','耶稣，耶稣，<br/>可否容我向你诉，<br/>你名对我如此丰富，<br/>我爱耶稣。<br/>','',58295,11854);
INSERT INTO stanza VALUES('ZS307','1','有一个名我爱听见，<br/>我爱唱牠价值；<br/>犹如音乐美妙甘甜，<br/>地上无名如此。<br/>','',58296,11855);
INSERT INTO stanza VALUES('ZS307','chorus','我何等爱耶稣，<br/>我何等爱耶稣，<br/>我何等爱耶稣，<br/>因为祂先爱我。<br/>','',58297,11856);
INSERT INTO stanza VALUES('ZS307','2','这名说出救主的爱，<br/>祂死使我自由；<br/>祂的宝血已流出来，<br/>神前说出美言。<br/>','',58298,11857);
INSERT INTO stanza VALUES('ZS307','3','这名说出我父为我，<br/>每日所有部署；<br/>眼前道路虽然阴暗，<br/>阳光终必照出！<br/>','',58299,11858);
INSERT INTO stanza VALUES('ZS307','4','这名说出祂心有爱，<br/>知我深处愁苦；<br/>每一忧伤祂都担代，<br/>地上无人同负。<br/>','',58300,11859);
INSERT INTO stanza VALUES('ZS308','1','主，每代你有一人：<br/>如朋友，亚伯拉罕；<br/>呼喊者，如撒母耳；<br/>又如大卫，满了颂赞，<br/>但你要得一班。<br/>','',58301,11860);
INSERT INTO stanza VALUES('ZS308','2','主，我们巴望就是<br/>服事你的那一班；<br/>洗你脚，合你需要，<br/>使你舒畅，令你心欢，<br/>作你密友良伴，<br/>无所不谈…<br/>','',58302,11861);
INSERT INTO stanza VALUES('ZS308','chorus','我们要颂赞，<br/>我们要呼喊，<br/>一心转向你，<br/>让你来掌管，<br/>专一的爱你，<br/>一直爱到底，<br/>愿此情不移。<br/>','',58303,11862);
INSERT INTO stanza VALUES('ZS308','3','主，你的丰盛怜悯，<br/>向我们毫不吝惜！<br/>我们是团体新人，<br/>为着你的永远旨意，<br/>只望能爱到底，<br/>坚定不移……<br/>','',58304,11863);
INSERT INTO stanza VALUES('ZS309','1','哦，我主！<br/>我将自己给你，<br/>你外我无出路，<br/>世界已经消逝。<br/>这世代都卧恶者手中，<br/>但我属我的父，<br/>祂爱供我所需。<br/>','',58305,11864);
INSERT INTO stanza VALUES('ZS309','chorus','主，我今将自己<br/>完全给你，<br/>生命的流我愿时刻经历；<br/>耶稣，耶稣，<br/>耶稣，耶稣，耶稣，<br/>我全心爱你，<br/>真正的爱你。<br/>','',58306,11865);
INSERT INTO stanza VALUES('ZS309','2','我羡慕你从我心流出，<br/>我心永远不能<br/>装你之外事物。<br/>我深处时刻向你呼求，<br/>满带饥渴羡慕，<br/>从我甜美流出。<br/>','',58307,11866);
INSERT INTO stanza VALUES('ZS309','3','你的光天天照在我身，<br/>参透虚假属灵，<br/>使我不再受欺。<br/>我深知我需你的光照，<br/>若无你光照亮，<br/>我怎能属于你。<br/>','',58308,11867);
INSERT INTO stanza VALUES('ZS309','4','洁净我，不让一罪存留，<br/>愿我天天改变，<br/>让你生命有路；<br/>我求你赦免我罪软弱，<br/>使我里外清洁，<br/>活水涌流无阻。<br/>','',58309,11868);
INSERT INTO stanza VALUES('ZS309','5','何喜乐，享受生命平安，<br/>有主甜美同在，<br/>死亡毫无踪迹；<br/>何喜乐，生命交通甜蜜，<br/>我觉即使在天，<br/>也不能够相匹。<br/>','',58310,11869);
INSERT INTO stanza VALUES('ZS309','chorus','主，我今将自己<br/>完全给你，<br/>生命的流使我赞美不已；<br/>耶稣，耶稣，<br/>耶稣，耶稣，耶稣，<br/>我全心爱你，<br/>真正的爱你。<br/>','',58311,11870);
INSERT INTO stanza VALUES('ZS310','1','何等快乐日，<br/>当我已经别无他途，<br/>当主夺取我心，<br/>从无边黑暗<br/>进入祂光明的国度。<br/>','',58312,11871);
INSERT INTO stanza VALUES('ZS310','2','我新生开始，<br/>这新生命是神爱子，<br/>我不再为幻梦<br/>而如醉如痴；<br/>因活泉涌流我深处！<br/>','',58313,11872);
INSERT INTO stanza VALUES('ZS310','3','当我转向祂，<br/>祂就供应祂的生命，<br/>祂生命成为<br/>我人生的实际，<br/>哦，阿利路亚在我里！<br/>','',58314,11873);
INSERT INTO stanza VALUES('ZS310','4','我单单爱你，<br/>其他的爱求你烧去，<br/>从现今到永远，<br/>你是我生命，<br/>你是我一切的一切。<br/>','',58315,11874);
INSERT INTO stanza VALUES('ZS311','1','沉醉在你爱里，<br/>滋润新鲜，<br/>让你爱来浸透，<br/>远比蜂蜜甘甜！<br/>你爱紧握我手，<br/>引我前行，<br/>我时依你胸臆，<br/>饱尝你爱情。<br/>我切慕，哦主，<br/>筵宴你爱里，<br/>让你爱将我遮蔽。<br/>你以爱为旌旗─<br/>你的自己，<br/>你的爱原与你为一。<br/>','',58316,11875);
INSERT INTO stanza VALUES('ZS311','2','你是我至宝爱，<br/>独一的你；<br/>你是我爱对象，<br/>是的，是你自己。<br/>若你仅赐救赎，<br/>和你爱情；<br/>你知这都不能<br/>满足我心灵。<br/>我切慕，哦主！<br/>得着你自己；<br/>我深知一切是你。<br/>满带爱情的你，<br/>我所追求；<br/>我惟一的至宝是你。<br/>','',58317,11876);
INSERT INTO stanza VALUES('ZS312','1','当我浸透在祂爱里，<br/>追求思虑尽消失；<br/>祂爱四围把我覆庇，<br/>引我失去在祂里。<br/>当我瞻仰祂的荣美，<br/>发光的脸何可亲；<br/>我就不禁涌出爱情，<br/>与祂联结再不分。<br/>当我浸透在祂爱里，<br/>追求思虑尽消失；<br/>祂爱四围把我覆庇，<br/>引我失去在祂里。<br/>','',58318,11877);
INSERT INTO stanza VALUES('ZS312','2','当我们同活祂爱里，<br/>彼此交通又相依；<br/>祂爱是我们的联系，<br/>『爱』使我们永不离。<br/>当祂爱围绕着我们，<br/>相亲相惜何甜蜜；<br/>我们就同活在爱里，<br/>心心相联在一起。<br/>当我们同活在祂爱里，<br/>彼此交通又相依；<br/>祂爱是我们的联系，<br/>『爱』使我们永不离。<br/>','',58319,11878);
INSERT INTO stanza VALUES('ZS313','1','前我曾多次呼求主耶稣，<br/>但是从未这样<br/>实际的摸着我主，<br/>不知为何故忽见祂丰采，<br/>哦我的主耶稣，我爱你！<br/>','',58320,11879);
INSERT INTO stanza VALUES('ZS313','2','世上的事物我已不再属，<br/>我已得着这位<br/>可爱的生命救主，<br/>让万事逝去，只要我能够<br/>天天在召会中来爱你。<br/>耶稣！奇妙的耶稣！<br/>是我何等的救主。<br/>哦主，愿我爱全归你，<br/>天天欢喜快乐地<br/>享受你实际！<br/>（重复）<br/>','',58321,11880);
INSERT INTO stanza VALUES('ZS314','1','我们与爱的耶稣<br/>彼此享受何快乐，<br/>我们涌起爱意<br/>向着爱主唱歌，<br/>向着爱主唱新歌。<br/>从祂我们得平安，<br/>因祂我们享自由；<br/>祂是我们救主，<br/>又是我们生命，<br/>与我们永远合一！<br/>（一至三行重复一次）<br/>耶稣，耶稣，<br/>你名何富有！<br/>我们捆绑全脱落，<br/>灵里释放唱新歌，<br/>阿利路亚向你唱新歌。<br/>','',58322,11881);
INSERT INTO stanza VALUES('ZS315','1','每日单单地爱主，<br/>爱祂经过风暴路，<br/>爱祂虽然信微弱，<br/>一切在于爱耶稣！<br/>','',58323,11882);
INSERT INTO stanza VALUES('ZS315','chorus','爱祂当时辰飞逝，<br/>爱祂当日子流去；<br/>爱祂无论何事临，<br/>一切在于爱耶稣！<br/>','',58324,11883);
INSERT INTO stanza VALUES('ZS315','2','主灵照耀何明亮，<br/>进我微小的这心，<br/>当祂引导我稳固，<br/>一切在于爱耶稣！<br/>','',58325,11884);
INSERT INTO stanza VALUES('ZS315','3','歌唱当我景晴朗，<br/>祷告当我路崎岖，<br/>惊险临到我呼求，<br/>一切在于爱耶稣！<br/>','',58326,11885);
INSERT INTO stanza VALUES('ZS315','4','爱祂直到今生过，<br/>爱祂直到地消逝，<br/>爱祂直到祂回来，<br/>一切在于爱耶稣！<br/>','',58327,11886);
INSERT INTO stanza VALUES('ZS316','1','恩主，你是我至爱，<br/>我的爱情都归你，<br/>当你爱充满我心，<br/>我在爱里得安息。<br/>主，我爱你的自己，<br/>不是你所作所赐，<br/>无一能与你相匹，<br/>我今欢乐的爱你。<br/>','',58328,11887);
INSERT INTO stanza VALUES('ZS316','chorus','主，我曾享受许多事物，<br/>但我现今欢然全丢弃；<br/>我不再爱恋别的事物，<br/>我将上好爱情归你。<br/>','',58329,11888);
INSERT INTO stanza VALUES('ZS316','2','有何能使我眷恋，<br/>若非你作牠实际；<br/>我心单纯的祈求，<br/>只望全人充满你。<br/>恩主，你是我至爱，<br/>我的爱情都归你，<br/>当你爱充满我心，<br/>我在爱里得安息。<br/>','',58330,11889);
INSERT INTO stanza VALUES('ZS317','chorus','直等到<br/>我进了神的圣所里面，<br/>才看出他们的结局。<br/>直等到<br/>我进了神的圣所里面，<br/>才看出他们的结局。<br/>恶人和狂傲人<br/>反倒享平安；<br/>至于我，我脚几乎失闪；<br/>我思索不明白，<br/>眼看实为难！<br/>（接上面副歌）<br/>','',58331,11890);
INSERT INTO stanza VALUES('ZS317','1','你实在把他们<br/>安置在滑地，<br/>使他们掉在沉沦之中，<br/>他们所夸口的<br/>转眼便成空。<br/>','',58332,11891);
INSERT INTO stanza VALUES('ZS317','chorus','因而我的心里发酸，<br/>肺腑被刺，<br/>我竟这样愚昧无知。<br/>（重复最后两行，下同）<br/>','',58333,11892);
INSERT INTO stanza VALUES('ZS317','2','除你外，<br/>在天上我岂有谁呢？<br/>在地上我也无所爱慕；<br/>你是我的力量<br/>和永远之福！<br/>','',58334,11893);
INSERT INTO stanza VALUES('ZS317','chorus','你搀着我右手，<br/>以你训言引导，<br/>以后必接我到荣耀。<br/>','',58335,11894);
INSERT INTO stanza VALUES('ZS318','1','当头一次遇见了你，<br/>我的心充满欢喜。<br/>阿利路亚，喜乐满溢，<br/>主耶稣充满在我里。<br/>头一次的爱，<br/>最甘甜的爱，<br/>耶稣，耶稣，我的爱。<br/>超过一切真实的爱，<br/>竟然临及我；<br/>甘甜的爱，最真实的爱，<br/>耶稣，耶稣，我的爱。<br/>','',58336,11895);
INSERT INTO stanza VALUES('ZS319','1','你，你，你常在我心中，<br/>梦，梦，梦里萦绕；<br/>你，你，你爱情何其甜，<br/>你是比一切都好。<br/>耶稣！耶稣！<br/>你是比一切都好。<br/>耶稣！耶稣！<br/>你是比一切都好。<br/>','',58337,11896);
INSERT INTO stanza VALUES('ZS319','2','爱，爱，爱是丰盛无边，<br/>甜，甜，甜过蜂蜜；<br/>流，流，流遍我的心田，<br/>饱尝你爱情新鲜。<br/>耶稣！耶稣！<br/>饱尝你爱情新鲜。<br/>耶稣！耶稣！<br/>饱尝你爱情新鲜。<br/>','',58338,11897);
INSERT INTO stanza VALUES('ZS320','1','因着你将我吸引，<br/>我才能跟随紧紧，<br/>知你是包容无限，<br/>我一生经历不尽。<br/>你好似美丽凤仙，<br/>显在荒野的世间，<br/>又好像馨香没药，<br/>珍藏在我的胸怀。<br/>哦，愿你听我轻诉，<br/>从此后我无别主，<br/>你丰富给我享受，<br/>你生命使我成熟。<br/>','',58339,11898);
INSERT INTO stanza VALUES('ZS321','1','我怎能离开主，<br/>怎能将主忘记，<br/>当主爱情依依，<br/>在我胸臆；<br/>万事都要逝去，<br/>只有爱永不移，<br/>除了主还有谁，<br/>使我归依。<br/>','',58340,11899);
INSERT INTO stanza VALUES('ZS321','2','我怎能离开主，<br/>怎能将主忘记，<br/>当祂爱的泉源，<br/>涌流我里；<br/>将我全人浸透，<br/>使我全人复苏，<br/>除了主还有谁，<br/>使我归依。<br/>','',58341,11900);
INSERT INTO stanza VALUES('ZS322','1','我今是单纯敞开我心，<br/>主耶稣来进入，<br/>我今是单纯敞开我心，<br/>主耶稣来进入。<br/>','',58342,11901);
INSERT INTO stanza VALUES('ZS322','2','我只望单单纯纯爱你，<br/>求你住我心内。<br/>我只望单单纯纯爱你，<br/>求你住我心内。<br/>','',58343,11902);
INSERT INTO stanza VALUES('ZS322','3','主你是活活泼泼人位，<br/>时刻活在我里。<br/>主你是活活泼泼人位，<br/>时刻活在我里。<br/>','',58344,11903);
INSERT INTO stanza VALUES('ZS322','4','现在我在灵中享受你，<br/>借你生命而活。<br/>现在我在灵中享受你，<br/>借你生命而活。<br/>','',58345,11904);
INSERT INTO stanza VALUES('ZS322','5','安息的『阿们』你，<br/>主耶稣，你占有我全人。<br/>安息的『阿们』你，<br/>主耶稣，你占有我全人。<br/>','',58346,11905);
INSERT INTO stanza VALUES('ZS323','1','转，转，我转向你，<br/>主，我承认我空虚无比；<br/>转，转，流浪的心，<br/>只能满足于你爱情！<br/>','',58347,11906);
INSERT INTO stanza VALUES('ZS323','chorus','主耶稣！我呼求你，<br/>你是我惟一所需。<br/>','',58348,11907);
INSERT INTO stanza VALUES('ZS323','2','厚，厚，祂赐恩典，<br/>呼求祂的，必尝祂甘甜；<br/>厚，厚，祂恩待你，<br/>从今到永远，主不变。<br/>','',58349,11908);
INSERT INTO stanza VALUES('ZS323','3','爱，爱，基督的爱，<br/>如同江河，满至涌出来；<br/>爱，爱，我充满爱，<br/>疯狂的充满主的爱。<br/>','',58350,11909);
INSERT INTO stanza VALUES('ZS324','1','每当你向我敞开胸襟，<br/>我的心立刻起共鸣。<br/>你慈手抚我身，<br/>我就立刻能对你诉衷情，<br/>如何能倾诉得尽，<br/>如何能倾诉得尽。<br/>','',58351,11910);
INSERT INTO stanza VALUES('ZS324','2','但我却知道我的心声，<br/>你又是何等的爱听，<br/>我的爱语，叹息，<br/>都能在你里震动你情心，<br/>却不能震动得尽，<br/>却不能震动得尽。<br/>','',58352,11911);
INSERT INTO stanza VALUES('ZS324','3','主，愿我向你所表情心，<br/>都能经你手的炼净，<br/>使我全人全心，<br/>全都注于你，<br/>经历你爱情，<br/>至终能经历得尽，<br/>至终能经历得尽。<br/>','',58353,11912);
INSERT INTO stanza VALUES('ZS325','1','从我心涌出了音乐，<br/>流向我爱，<br/>祂曾为我舍己。<br/>我怎能转脸不向你，<br/>当我浸润在你不移爱里。<br/>享受何丰富，<br/>生命何实际，<br/>喜乐何洋溢，<br/>哦主，得我全心！<br/>得我心，也得我全人，<br/>恩主，<br/>我不得不将我给你。<br/>','',58354,11913);
INSERT INTO stanza VALUES('ZS325','2','从那日，当我遇见你，<br/>我怎能不深深坠入爱里；<br/>我曾是虚空又忧郁，<br/>世上无一情爱能使我依。<br/>直至有一日，<br/>我敞开我心，<br/>你爱得流入，<br/>充满我心深处！<br/>我今知，主！你我合一，<br/>这使我不得不将我给你。<br/>恩主！<br/>我不得不将我给你！<br/>','',58355,11914);
INSERT INTO stanza VALUES('ZS326','1','哦，是你爱来遇见我们，<br/>当我们正堕落罪恶境；<br/>哦，是你爱将我们吸引，<br/>使我们能得着新生命。<br/>何奇妙，是你的爱<br/>赐给我们更新的一生。<br/>哦，是你爱改变我石心，<br/>当我对你冷酷又坚硬；<br/>哦，是你爱赐给我新心，<br/>使我向你依依不再分。<br/>','',58356,11915);
INSERT INTO stanza VALUES('ZS326','2','是你的爱，天天来扶持，<br/>使我们能不断向前行；<br/>是你的爱，时刻来供应，<br/>使我们能脱离幻梦境。<br/>何奇妙，是你的爱，<br/>成为我们行走的能力。<br/>是你的爱，使你将自己，<br/>化成为灵，住在我灵里；<br/>是你的爱，在我心运行，<br/>我才能够渴慕来经营。<br/>','',58357,11916);
INSERT INTO stanza VALUES('ZS326','3','是你的爱，作工在我身，<br/>琢磨不断好使我成形；<br/>是你的爱，量给我处境，<br/>好使我能破碎流生命。<br/>何奇妙，是你的爱，<br/>在我心里多面的作为；<br/>为何我能安家在召会？<br/>无非因你爱里的花费！<br/>为何我能享受在家里？<br/>无非因你爱手的实际！<br/>','',58358,11917);
INSERT INTO stanza VALUES('ZS326','4','是你的爱，使我能变化，<br/>借着瓦器彰显你荣华；<br/>是你的爱，赐给我盼望，<br/>立刻被提变成你形像。<br/>何奇妙，是你的爱，<br/>使我改变，催促你归回。<br/>主，我实在不知、也不会<br/>细细述说你爱的宝贵；<br/>求你浇我，浸透你爱里，<br/>使我余生失去在你里。<br/>','',58359,11918);
INSERT INTO stanza VALUES('ZS327','1','主阿！我爱你，<br/>我实在深爱你，<br/>无你活着枉然、失意。<br/>你是富有吸引，<br/>极其引人着迷，<br/>你的丰富追测不尽。<br/>我主名何甜蜜，<br/>呼求叫人满意，<br/>主，你属我；<br/>主，我也属你。<br/>联结调和于你，<br/>神人合并为一，<br/>豫尝新耶路撒冷实际。<br/>注：此首诗辞采自李常受弟兄一九九七年离世前不久的祷告。<br/>','',58360,11919);
INSERT INTO stanza VALUES('ZS328','1','怎能乡村女子如我，<br/>成为你的新妇、配偶？<br/>你是如此圣洁、神圣，<br/>我却堕落、属人。<br/>若非是你，我怎得以<br/>在这罗曼史里像你？<br/>在创世前，我蒙拣选，<br/>你计划永不变！<br/>（副一）<br/>神圣罗曼史，<br/>神心计划之；<br/>神成为卑微人子，<br/>追求乡村女子！<br/>神永远的爱，<br/>无何能妨碍，<br/>亦无何能以更改，<br/>神终得心所爱！<br/>','',58361,11920);
INSERT INTO stanza VALUES('ZS328','2','世人、天使未曾知悉，<br/>隐藏在你心中秘密；<br/>创世之前，你已定意：<br/>与人联调为一！<br/>因那恶者阴谋、诡计，<br/>我被罪恶败坏至极；<br/>但无何能断绝你爱，<br/>我终投入你怀！<br/>（回副一）<br/>','',58362,11921);
INSERT INTO stanza VALUES('ZS328','3','万王之王，你竟成人，<br/>为我受死，将我拯救；<br/>在复活里，我成童女，<br/>许配给你─我王！<br/>死而复活，你进我灵，<br/>使我得有你的神性；<br/>你我今同生命、性情，<br/>神人二性合并！<br/>（副二）<br/>因你爱吸引，<br/>我得属于你；<br/>主，我不属于自己，<br/>我只属你而已。<br/>被你爱吸引，<br/>为你名所迷，<br/>我为你人位所夺；<br/>愿你亲嘴与我。<br/>','',58363,11922);
INSERT INTO stanza VALUES('ZS328','4','主，在这亲密交通里，<br/>我得与你倾心吐意；<br/>与你个人情深关系，<br/>是何等的甜蜜！<br/>逐日改变我之所是，<br/>主，占有我全心、全志；<br/>将我全人变化、浸透，<br/>成你新妇、佳偶！<br/>（回副二）<br/>','',58364,11923);
INSERT INTO stanza VALUES('ZS329','1','何等喜乐，何等喜乐，<br/>我们能够一无所有，<br/>一无所是，一无所见，<br/>惟见荣耀里的基督；<br/>何等喜乐，何等喜乐，<br/>我们能够一无所有，<br/>一无所是，一无所顾，<br/>惟顾祂在地权益。<br/>注：本首诗辞编译自达秘（J. N. Darby）的话。<br/>','',58365,11924);
INSERT INTO stanza VALUES('ZS401','1','生命之主向我吹气，<br/>将你活泉向我开启，<br/>从我里面将我推动，<br/>生命之光照我心中。<br/>','',58366,11925);
INSERT INTO stanza VALUES('ZS401','2','主，何希奇，你在我里，<br/>不必天上阴间寻你，<br/>一回灵里就得见你，<br/>灵灵接触毫无距离。<br/>','',58367,11926);
INSERT INTO stanza VALUES('ZS401','3','你是我的在天中保，<br/>又是我的灵中恩膏；<br/>凡你神前为我所作，<br/>都在我灵给我摸着。<br/>','',58368,11927);
INSERT INTO stanza VALUES('ZS401','4','但是我心何等不忠，<br/>常虽深感仍不顺从；<br/>求主眷怜、吹气、推动，<br/>使我全人都尽功用。<br/>','',58369,11928);
INSERT INTO stanza VALUES('ZS401','5','当我灵里憋气，下沉，<br/>难将你恩向人言陈，<br/>求你从我里面吹气，<br/>使我完全充满了你。<br/>','',58370,11929);
INSERT INTO stanza VALUES('ZS402','1','吸引、吸引，<br/>我们被吸引转向主，<br/>再好的前途<br/>我们也不屑一顾。<br/>情愿趁着现在，<br/>把上好的年岁，<br/>全然奉献给基督与召会！<br/>','',58371,11930);
INSERT INTO stanza VALUES('ZS402','2','吸引、吸引，<br/>召会生活满了丰富；<br/>从岁首到年终，<br/>神眼目常看顾，<br/>百花开放，百鸟鸣叫，<br/>满了生命，<br/>荫下尝甘甜显出祂秀美。<br/>','',58372,11931);
INSERT INTO stanza VALUES('ZS402','3','吸引、吸引，<br/>可爱新郎步步临近；<br/>祂正在侧身倾听，<br/>要题我的名。<br/>有天祂要回到半空中，<br/>悄悄的，一刹那之间<br/>把我吸上去！<br/>','',58373,11932);
INSERT INTO stanza VALUES('ZS403','1','主耶稣！主耶稣！<br/>我渴慕摸着你！<br/>多又多，多又多，<br/>你长大在我里。<br/>愿你的生命不断成长，<br/>『荣耀之花』盛放！<br/>叫世人看见你<br/>显在我的身上。<br/>','',58374,11933);
INSERT INTO stanza VALUES('ZS404','1','可恶世界一直骗我，<br/>我还以为是好友；<br/>甚么都还没有到手，<br/>我心就先被骗走。<br/>害得我主苦苦巴望，<br/>想要爱我爱不着！<br/>主，我今天向你悔改，<br/>你已等得够长久……<br/>','',58375,11934);
INSERT INTO stanza VALUES('ZS404','2','主，感谢你嫉妒的灵<br/>保守我单为你活。<br/>你的恩典多而又多，<br/>足够我欢喜快乐。<br/>现在我要疯狂爱主，<br/>爱到全心只有主！<br/>哦主、阿们，世界断开，<br/>阿利路亚，主同在！<br/>','',58376,11935);
INSERT INTO stanza VALUES('ZS405','1','但他们的心几时归向主，<br/>帕子就几时除去了。<br/>所以你的心终日归向主，<br/>你的帕子就除去了。<br/>如今主就是那灵，<br/>主的灵若是在那里，<br/>那里就得以释放自由。<br/>所以你的心终日归向主，<br/>你的帕子就除去了。<br/>','',58377,11936);
INSERT INTO stanza VALUES('ZS406','1','更深，更深，<br/>借着主的十架，<br/>让我更深入；死与生命，<br/>二者连在一起，<br/>使流加深，主。<br/>哦主，我求更深，<br/>天天作工我身；<br/>遍我全人各部，<br/>直到全新于我主。<br/>','',58378,11937);
INSERT INTO stanza VALUES('ZS406','2','更高，更高，<br/>在主生命里面；<br/>主，我何低浅！<br/>借你生命我能更高，<br/>更高─更高往上面。<br/>哦主，我求更高，<br/>变化乃我需要─<br/>流中更加丰盛，<br/>惟愿认识你生命。<br/>','',58379,11938);
INSERT INTO stanza VALUES('ZS406','3','长大，长大，<br/>主在我里长大，<br/>一天过一天。<br/>祂今流入我的一切生活─<br/>这是祂所愿。<br/>哦主，长在我里，<br/>逐日增加不已；<br/>知识不足应付，<br/>必须长大并成熟。<br/>','',58380,11939);
INSERT INTO stanza VALUES('ZS406','4','生活，生活，<br/>基督是我生活，<br/>祂实际无限！<br/>小事，大事，任何事，<br/>一切事─祂都在里面。<br/>每日活出基督，<br/>时刻将祂流露，<br/>祂名你当呼求，<br/>为得基督献所有。<br/>','',58381,11940);
INSERT INTO stanza VALUES('ZS406','5','人位，人位，<br/>主是我的人位，<br/>今住在我里。<br/>祂是我的口味，<br/>态度，动作，<br/>哦，何等希奇！<br/>主，你是我人位，<br/>安家在我心内；<br/>作我生命一切，<br/>这是何等的联结！<br/>','',58382,11941);
INSERT INTO stanza VALUES('ZS406','6','召会，召会，<br/>在众地方召会，<br/>有圣灵的流；<br/>更深，更高，<br/>基督是我生活，<br/>我被祂占有。<br/>召会乃是基督<br/>各方面的显出；<br/>主，我愿脱自己，<br/>为着建造你身体。<br/>','',58383,11942);
INSERT INTO stanza VALUES('ZS406','7','建造，建造，<br/>召会得着建造，<br/>靠经历基督；<br/>惟有如此才会产生建造，<br/>除祂无别路。<br/>哦主，我今求告，<br/>我愿被你建造，<br/>生命逐日加增，<br/>为着新耶路撒冷。<br/>','',58384,11943);
INSERT INTO stanza VALUES('ZS406','7','快来，快来，<br/>基督必要快来，<br/>娶祂的新妇；<br/>在召会中我们准备等候，<br/>身体得救赎。<br/>哦主，愿你快来─<br/>此声出自心怀；<br/>我们赞美不住，<br/>愿你快来，主耶稣！<br/>','',58385,11944);
INSERT INTO stanza VALUES('ZS407','1','哦，让我们将<br/>昨日的事丢背后，<br/>努力面前<br/>向着标竿一直跑！<br/>让我们在流中<br/>跟随主行动，<br/>为着主的恢复<br/>答应主呼召。<br/>','',58386,11945);
INSERT INTO stanza VALUES('ZS408','1','挖透我，挖透我，<br/>挖透我，<br/>挖去我心里所有硬石头！<br/>所有罪，皆脱落，<br/>让生命涌流！阿利路亚！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我心里所有硬石头！<br/>','',58387,11946);
INSERT INTO stanza VALUES('ZS408','2','挖透我，挖透我，<br/>挖透我，<br/>挖去我所有虚空的幻想！<br/>所有梦，须清醒，<br/>让生命涌流…阿利路亚！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我所有虚空的幻想！<br/>','',58388,11947);
INSERT INTO stanza VALUES('ZS408','3','挖透我，挖透我，<br/>挖透我，<br/>挖去所有困扰我的感情！<br/>己所爱，须撇弃，<br/>让生命涌流…阿利路亚！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去所有困扰我的感情！<br/>','',58389,11948);
INSERT INTO stanza VALUES('ZS408','4','挖透我，挖透我，<br/>挖透我，<br/>挖去所有意志里的悖逆！<br/>己所愿，须平息，<br/>让生命涌流…阿利路亚！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去所有意志里的背逆！<br/>','',58390,11949);
INSERT INTO stanza VALUES('ZS408','5','挖透我，挖透我，<br/>挖透我，<br/>挖去我所有自己的追求！<br/>己所望，须扑灭，<br/>让生命涌流…阿利路亚！<br/>挖透我，挖透我，<br/>挖透我，<br/>挖去我所有自己的追求！<br/>','',58391,11950);
INSERT INTO stanza VALUES('ZS408','6','涌流出！赞美主！<br/>涌流出！<br/>生命从心中活泉涌流出！<br/>我的心全释放，<br/>灵就能『赞美』…<br/>阿利路亚！涌流出！<br/>赞美主！涌流出！<br/>生命从心中活泉涌流出！<br/>?<br/>注：第六节『赞美』可换唱『祷告、』『唱诗、』『长大』…等。<br/>','',58392,11951);
INSERT INTO stanza VALUES('ZS409','1','有一生命比心思更深，<br/>在我灵里可经历，<br/>何等神圣！<br/>无限无量何奇妙，<br/>充满了神荣耀，阔长深高<br/>过于人所能测度。<br/>这一生命乃是永活神，<br/>曾从人子耶稣身上<br/>显出来，<br/>今成赐生命的灵，<br/>在我灵祂成长，长大成为<br/>祂所喜悦的召会。<br/>','',58393,11952);
INSERT INTO stanza VALUES('ZS409','chorus','哦主阿！更多来涌流！<br/>我们生活意义，<br/>你进我们里面用意，<br/>都是为这流！<br/>主转我，转更多，<br/>借着生命你才能得着召会<br/>你心所渴慕的家。<br/>','',58394,11953);
INSERT INTO stanza VALUES('ZS409','2','在祂召会我们同明白，<br/>祂那丰盛生命<br/>在我们里面；<br/>不是外面的挣扎，<br/>乃深处的平安，漫溢全人<br/>并流出活水江河。<br/>同众圣徒我就能放胆，<br/>追求享用持定<br/>这丰盛生命；<br/>主外一切的事物，<br/>丢背后全弃绝，<br/>直到召会<br/>完全充满神生命。<br/>','',58395,11954);
INSERT INTO stanza VALUES('ZS409','3','主阿！使我更深转向你，<br/>生活行动说话<br/>工作全凭你；<br/>放弃所有老观念，<br/>绝对照你生命，给我恩典<br/>每时每刻转更多。<br/>当我转到灵里享安息，<br/>里面的人<br/>一天比一天更新；<br/>在我全人最深处，<br/>来安家，主耶稣！<br/>深愿你的同在<br/>包围我全人。<br/>','',58396,11955);
INSERT INTO stanza VALUES('ZS410','1','从我灵里深处，<br/>有生命水涌流，<br/>是三一神在我里面流。<br/>父神乃是源头，<br/>主基督乃是河，<br/>灵是流，分赐生命给我。<br/>','',58397,11956);
INSERT INTO stanza VALUES('ZS410','chorus','主，我宝贝这生命的流，<br/>我的魂生命不再保留；<br/>哦主，加深这生命的流，<br/>愿你来时我生命成熟。<br/>','',58398,11957);
INSERT INTO stanza VALUES('ZS410','2','在鲜嫩草地上，<br/>在可安歇水边，<br/>跟羊群的脚踪享受主。<br/>不用勉强挣扎，<br/>徒然自讨苦吃，<br/>在流里我就全然蒙福！<br/>','',58399,11958);
INSERT INTO stanza VALUES('ZS410','3','借着血我坦然<br/>进前到至圣所，<br/>活在祂面前─联于源头。<br/>阿利路亚，祂说，<br/>切不可离开我，<br/>当住我里头─一直交流。<br/>','',58400,11959);
INSERT INTO stanza VALUES('ZS411','1','我们可以立刻胜过仇敌，<br/>立刻胜过仇敌，<br/>立刻胜过仇敌；<br/>我们可以立刻胜过仇敌，<br/>若取用宝血。<br/>若取用宝血，<br/>若取用宝血。<br/>我们可以立刻胜过仇敌，<br/>若取用宝血。<br/>','',58401,11960);
INSERT INTO stanza VALUES('ZS411','2','得胜原来不在乎多属灵，<br/>不在乎多属灵，<br/>不在乎多属灵；<br/>得胜原来不在乎多属灵，<br/>乃在乎宝血。<br/>乃在乎宝血，<br/>乃在乎宝血。<br/>得胜原来不在乎属灵，<br/>乃在乎宝血。<br/>','',58402,11961);
INSERT INTO stanza VALUES('ZS411','3','我们容易作正常基督徒，<br/>作正常基督徒，<br/>作正常基督徒；<br/>我们容易作正常基督徒，<br/>只要用宝血。<br/>只要用宝血，<br/>只要用宝血，<br/>我们容易作正常基督徒，<br/>只要用宝血。<br/>','',58403,11962);
INSERT INTO stanza VALUES('ZS411','4','靠着宝血我们恢复交通，<br/>我们恢复交通，<br/>我们恢复交通；<br/>靠着宝血我们恢复交通，<br/>不必等时间。<br/>不必等时间，<br/>不必等时间，<br/>靠着宝血我们恢复交通，<br/>不必等时间。<br/>','',58404,11963);
INSERT INTO stanza VALUES('ZS412','1','吃喝主的话就不萎缩，<br/>欢喜阿们，不是受强迫！<br/>在话的水里泡，<br/>泡到全人快活；<br/>无论我们时间多难得！<br/>经常来祷读就不退后，<br/>欢喜祷读，不是受强迫！<br/>大家一起焚烧，<br/>烧到全人发热；<br/>无论我们环境多难受，<br/>不退后！<br/>','',58405,11964);
INSERT INTO stanza VALUES('ZS413','1','『阿们』，主耶稣！<br/>『阿们』，主！<br/>是的『阿们』不停，<br/>我『阿们』你写出的话，<br/>『阿们』整本圣经，<br/>也『阿们』你随时的话，<br/>你知我所需要，<br/>因此我仍说：<br/>『阿们』主！<br/>无论甚么都好。<br/>','',58406,11965);
INSERT INTO stanza VALUES('ZS414','1','你若要脱离世界的辖制，<br/>阿们神的话语！<br/>你若要经历属灵的实际，<br/>阿们神的话语！<br/>阿们神的话语！<br/>阿们神的话语！<br/>接受祂话语，<br/>一点不怀疑，<br/>阿们神的话语！<br/>','',58407,11966);
INSERT INTO stanza VALUES('ZS414','2','你若要脱离罪恶与自己，<br/>阿们神的话语！<br/>你若要主来更新你心意，<br/>阿们神的话语！<br/>阿们神的话语！<br/>阿们神的话语！<br/>祂话点活你，<br/>赐生命给你，<br/>阿们神的话语！<br/>','',58408,11967);
INSERT INTO stanza VALUES('ZS414','3','基督是美地，<br/>我们的永分，<br/>阿们神的话语！<br/>今天听祂话，<br/>不可硬着心，<br/>阿们神的话语！<br/>阿们神的话语！<br/>阿们神的话语！<br/>祂话语分辨，<br/>如两刃利剑，<br/>阿们神的话语！<br/>','',58409,11968);
INSERT INTO stanza VALUES('ZS414','4','耶稣快再来，<br/>时间已短少，<br/>阿们神的话语！<br/>你能否说你已经豫备好，<br/>阿们神的话语！<br/>阿们神的话语！<br/>阿们神的话语！<br/>不要再愚昧，<br/>以祂话装备，<br/>阿们神的话语！<br/>','',58410,11969);
INSERT INTO stanza VALUES('ZS415','1','我们坦然来到施恩座，<br/>得着怜恤恩惠作帮助；<br/>不再环绕十字架敬拜，<br/>因为我主已不在彼。<br/>祂已冲破了死亡捆绑，<br/>复活升天得荣耀！<br/>现今祂从施恩宝座，<br/>用祂生命供应我。<br/>','',58411,11970);
INSERT INTO stanza VALUES('ZS415','2','施恩宝座虽然在天上，<br/>借祂天梯通到我灵里；<br/>所以我不在魂里游荡，<br/>时时全人转回灵里。<br/>耶稣是我尊荣大祭司，<br/>喜欢体恤我软弱！<br/>我靠着祂进到神前，<br/>祂必将我救到底。<br/>','',58412,11971);
INSERT INTO stanza VALUES('ZS415','3','赞美耶稣是我大祭司，<br/>按着麦基洗德的等次；<br/>我今为着神利益争战，<br/>祂就代求供我能力。<br/>等我得胜杀败众仇敌，<br/>祂用饼酒供应我！<br/>何等释放得享自由，<br/>经历祂完全救恩！<br/>','',58413,11972);
INSERT INTO stanza VALUES('ZS416','1','同环绕施恩座，<br/>这是天来佳音。<br/>我们在至圣所，<br/>享受完全救恩。<br/>在灵里面一同相聚，<br/>享受基督直到永远，<br/>享受基督直到永远。<br/>','',58414,11973);
INSERT INTO stanza VALUES('ZS416','2','同奔入至圣所，<br/>直达施恩宝座；<br/>开始于外院子，<br/>也经过了圣所。<br/>世界丢弃，罪恶消除，<br/>进入幔内，与神同住。<br/>（重复末句，下同）<br/>','',58415,11974);
INSERT INTO stanza VALUES('ZS416','3','赎罪祭已成了，<br/>亚伦早已过时；<br/>照着麦基洗德，<br/>基督作大祭司。<br/>更美之约，更美职事，<br/>以饼和酒，供应扶持。<br/>','',58416,11975);
INSERT INTO stanza VALUES('ZS416','4','基督远在天上，<br/>我今地上居住；<br/>如何能接触神？<br/>灵是惟一通路。<br/>在我灵里联着三者─<br/>神与宝座并至圣所。<br/>','',58417,11976);
INSERT INTO stanza VALUES('ZS416','5','我们是团体人，<br/>非流荡基督徒；<br/>只要投入身体，<br/>勿再单独思虑。<br/>每逢聚集，一同敞开，<br/>环绕宝座，赞美敬拜。<br/>','',58418,11977);
INSERT INTO stanza VALUES('ZS417','1','四周满艰辛，<br/>无一处可安息，<br/>我心似乎消化如水；<br/>但是在深处<br/>有微声轻轻诉，<br/>你是否真知道<br/>『祂是主』？<br/>','',58419,11978);
INSERT INTO stanza VALUES('ZS417','chorus','哦我心，当肃穆！<br/>祂是主，祂是主，<br/>祂是主！<br/>','',58420,11979);
INSERT INTO stanza VALUES('ZS417','2','试探常临及，<br/>如花在梦中现，<br/>花容既美丽又鲜艳，<br/>生姿的微笑，<br/>招我回世界中，<br/>深处却有声说：<br/>『祂是主！』<br/>','',58421,11980);
INSERT INTO stanza VALUES('ZS417','3','全人已破碎，<br/>无一处是完整，<br/>但是黑影笼罩愈深；<br/>双手尽伸出，<br/>却不见何依倾，<br/>在深处却涌出：<br/>『祂是主！』<br/>','',58422,11981);
INSERT INTO stanza VALUES('ZS417','4','雄心和壮志，<br/>皆已随风而去，<br/>祂所给苦刺似过重；<br/>轻声问我主，<br/>是否已被你弃，<br/>却听祂爱中说：<br/>『我是主！』<br/>','',58423,11982);
INSERT INTO stanza VALUES('ZS417','5','心头满羞惭，<br/>泪眼向心所爱─<br/>多年来祂一再赏赉，<br/>顽梗又不贞，<br/>似不能显祂荣，<br/>钉痕手却见证：<br/>『祂是主！』<br/>','',58424,11983);
INSERT INTO stanza VALUES('ZS418','1','我是小花一朵，<br/>敞开我脸；<br/>我完全转向神，<br/>接受恩典。<br/>不知如何往前，<br/>就是这样；<br/>一朵小百合信靠神。<br/>','',58425,11984);
INSERT INTO stanza VALUES('ZS418','2','地上并无一物使我羡慕；<br/>也无任何经历让我满足。<br/>然而有一件事是我所求─<br/>作朵小百合，信靠神。<br/>','',58426,11985);
INSERT INTO stanza VALUES('ZS418','3','若当我信靠神，<br/>我却蒙羞；<br/>若当与神同行，<br/>失去自由；<br/>这都不搅扰我，<br/>不算甚么。<br/>我是小百合，信靠神。<br/>','',58427,11986);
INSERT INTO stanza VALUES('ZS418','4','看你烦恼终日，<br/>愁衣忧食；<br/>常常昧着良心，<br/>只为淘金；<br/>看你发苍胃溃，<br/>金银何补？<br/>不如小百合，信靠神。<br/>','',58428,11987);
INSERT INTO stanza VALUES('ZS418','5','你虽知道许多，<br/>失败如故；<br/>你虽长篇大道，<br/>不肯喊主；<br/>所以，归根究底，<br/>有何益处？<br/>不如小百合，信靠神。<br/>','',58429,11988);
INSERT INTO stanza VALUES('ZS418','6','请勿以恐惧来搅扰我，<br/>何必挣扎努力，<br/>汗泪交流？<br/>简单的信靠主，<br/>祂常相近！<br/>作朵小百合，信靠神。<br/>','',58430,11989);
INSERT INTO stanza VALUES('ZS418','7','我长进得不错，<br/>别打搅我；<br/>你若满腹牢骚，<br/>请勿嫁祸；<br/>我是宁愿发光，<br/>知道不多。<br/>我是小百合，信靠神。<br/>','',58431,11990);
INSERT INTO stanza VALUES('ZS418','7','请勿以你罣虑，<br/>扰我清兴；<br/>请勿以你苦情，<br/>强迫我听；<br/>我们的神真大，<br/>祂甚关心！<br/>作朵小百合，信靠神。<br/>','',58432,11991);
INSERT INTO stanza VALUES('ZS418','9','好像我不理人，<br/>毫不在乎，<br/>其实我心深处，<br/>关怀备注！<br/>只是百合不惯闷闷不乐；<br/>我是小百合，你如何？<br/>','',58433,11992);
INSERT INTO stanza VALUES('ZS419','1','求主不要向我掩面，<br/>使我得以走正路；<br/>求主不断向我显现，<br/>使我能以尽旅途。<br/>惟有你的面光指引，<br/>我才能放胆不畏惧；<br/>所以求主你的面光，<br/>照耀我里常明亮。<br/>','',58434,11993);
INSERT INTO stanza VALUES('ZS419','2','每一举步都是犹豫，<br/>四围荆棘与蒺藜；<br/>每一定意都是可疑，<br/>不知你隐藏何地。<br/>惟有你的亲切同在，<br/>使我能放胆往前去；<br/>所以求主：你的同在<br/>显在我身不稍离。<br/>','',58435,11994);
INSERT INTO stanza VALUES('ZS419','3','当我要求你的上好，<br/>我才认识我邪僻；<br/>当我要行你的旨意，<br/>我才经历无能力。<br/>惟有你的荣耀自己，<br/>使我能消失在你里；<br/>所以求主：你的荣耀<br/>时刻吸引我离地。<br/>','',58436,11995);
INSERT INTO stanza VALUES('ZS419','4','求主赐我一个心志，<br/>只要得着你自己；<br/>求主赐我一个盼望，<br/>不再让你心忧戚。<br/>哦我的主，我今求你，<br/>紧紧拥我在你怀里；<br/>好叫你的甜美自己，<br/>成我力量我安息。<br/>','',58437,11996);
INSERT INTO stanza VALUES('ZS420','1','我们奔那前面的路，<br/>脱去缠累，放下重负，<br/>来望断，来望断，<br/>来望断及于主。<br/>荣耀在望，欢然冲刺，<br/>主必加力，主必扶持；<br/>当望断，当望断，<br/>当望断及于主。<br/>祂已经领先跑到，<br/>赢了！赢了！<br/>祂如今坐在神右边，<br/>要带我们进荣耀！<br/>望断，望断，<br/>望断以及于耶稣，<br/>望断，望断，<br/>望断以及于耶稣。<br/>','',58438,11997);
INSERT INTO stanza VALUES('ZS421','1','我只有一个心志，<br/>向着标竿一直跑，<br/>要得上面奖赏；<br/>背后一切都忘记，<br/>万事也当作有损，<br/>惟有祂才是至宝。<br/>丢弃万事如粪土，<br/>竭力追求不稍弛，<br/>为要认识<br/>这位复活的基督。<br/>虽然四围是艰难，<br/>要使我灰心丧胆，<br/>我知所信是谁；<br/>无论是生或是死，<br/>凡事我都能放胆，<br/>祂要在我身显大。<br/>','',58439,11998);
INSERT INTO stanza VALUES('ZS422','1','向标竿，豫备，<br/>奔跑生命路；<br/>上头奖赏来接受。<br/>放下各样重担<br/>和缠累的罪，<br/>属天异象不违背，<br/>见证人围绕着<br/>观看我奔跑，<br/>永不退后永不倒！<br/>向标竿，豫备，<br/>奔跑生命路；<br/>上头奖赏来接受。<br/>','',58440,11999);
INSERT INTO stanza VALUES('ZS423','1','向前直跑，向前直跑！<br/>标竿是万有主；<br/>为得奖赏，别无旁顾，<br/>一直跑向基督。<br/>','',58441,12000);
INSERT INTO stanza VALUES('ZS423','chorus','向前跑，向前跑，<br/>向前跑！阿利路亚，<br/>要得奖赏向前跑，<br/>一直跑！为要得着基督。<br/>','',58442,12001);
INSERT INTO stanza VALUES('ZS423','2','向前直跑！丢弃万事，<br/>看万物如粪土！<br/>神的基督，荣耀奖赏，<br/>吸引我的脚步！<br/>','',58443,12002);
INSERT INTO stanza VALUES('ZS423','3','向前直跑！认识基督，<br/>经历复活高超，<br/>哦，这乃是上好奖赏─<br/>若先进入荣耀！<br/>','',58444,12003);
INSERT INTO stanza VALUES('ZS423','4','向前直跑！只有一事：<br/>就是忘记背后，<br/>向着前头基督直跑，<br/>向前永不回头！<br/>','',58445,12004);
INSERT INTO stanza VALUES('ZS424','1','我们有当跑的路，<br/>阿利路亚！<br/>当一路跑尽，莫停下！<br/>对所有在跑的人，<br/>阿利路亚！<br/>神说：<br/>『当望断及于祂！』<br/>','',58446,12005);
INSERT INTO stanza VALUES('ZS424','chorus','当望断以及于祂！<br/>一路跑尽，莫停下！<br/>望断一切身外物，<br/>注视耶稣，<br/>当望断一切及于祂！<br/>','',58447,12006);
INSERT INTO stanza VALUES('ZS424','2','望断周遭的事物，<br/>阿利路亚！<br/>当望断扰嚷与挣扎；<br/>专一注视安息主，<br/>阿利路亚！<br/>当望断一切及于祂！<br/>','',58448,12007);
INSERT INTO stanza VALUES('ZS424','3','望断起伏的心绪，<br/>阿利路亚！<br/>别管你自己好或差；<br/>专一注视那标竿，<br/>阿利路亚！<br/>当望断一切及于祂！<br/>','',58449,12008);
INSERT INTO stanza VALUES('ZS424','4','望断背后的一切，<br/>阿利路亚！<br/>好或坏完全不管它；<br/>持守那位活的主，<br/>阿利路亚！<br/>当望断一切及于祂！<br/>','',58450,12009);
INSERT INTO stanza VALUES('ZS424','5','专一注视祂荣脸，<br/>阿利路亚！<br/>祂是阿拉法、俄梅嘎；<br/>领受恩典向前跑，<br/>阿利路亚！<br/>当望断一切及于祂！<br/>','',58451,12010);
INSERT INTO stanza VALUES('ZS425','1','曙光初现，心清灵明，<br/>与主相见在清晨，<br/>回到灵中，进入交通，<br/>何等甘甜，何等亲近；<br/>祂圣名，祂恩言，<br/>是我每晨新供应；<br/>饥渴尽除，全人明亮，<br/>赞美主，恩典够我用！<br/>','',58452,12011);
INSERT INTO stanza VALUES('ZS425','2','黎明即起，受主喂养，<br/>我得复兴在清晨，<br/>新的照耀，新的加力，<br/>得享基督作我福分；<br/>祂慈爱，祂怜悯，<br/>每个早晨都新鲜，<br/>我全人再次得更新，<br/>凭信、爱跟随主向前！<br/>','',58453,12012);
INSERT INTO stanza VALUES('ZS426','1','我们是一粒粒『麦子』，<br/>里面含有大能的生命，<br/>经过死的破碎、限制，<br/>就要显出复活的荣景；<br/>只要埋下，<br/>置魂生命于十架，<br/>就要结实，<br/>神的生命繁殖。<br/>我们是一粒粒『麦子』，<br/>里面含有大能的生命，<br/>经过死的破碎、限制，<br/>就要显出复活的荣景。<br/>','',58454,12013);
INSERT INTO stanza VALUES('ZS426','2','我听主一次次招呼，<br/>今愿跟随我主的脚步，<br/>使我不再完整如故，<br/>惟愿生命在我有出路；<br/>将我种下，<br/>直到复活的萌芽，<br/>结成满穗，<br/>一粒扩增百倍。<br/>我听主一次次招呼，<br/>今愿跟随我主的脚步，<br/>使我不再完整如故，<br/>惟愿生命在我有出路。<br/>','',58455,12014);
INSERT INTO stanza VALUES('ZS427','1','主呼召我们在这里，<br/>是为神永远的经纶，<br/>这是我人生的目的，<br/>是我生活的中心！<br/>三一神化身成为人，<br/>为使人变化成为神，<br/>祂钉死、复活成为那灵，<br/>今在我灵里作我分。<br/>','',58456,12015);
INSERT INTO stanza VALUES('ZS427','chorus','愿神这永远经纶异象，<br/>定住我心中每个方向，<br/>光照我，<br/>使我灵里发旺，更刚强，<br/>好模成基督荣耀形像，<br/>在生命中作王，<br/>将圣城撒冷带到地上。<br/>','',58457,12016);
INSERT INTO stanza VALUES('ZS427','2','哦，在这蒙福的境地，<br/>神与人联调成为一，<br/>留在基督这美地里，<br/>享受基督作实际；<br/>珍惜这无上的权利，<br/>建造主生机的身体，<br/>作基督显身团体大器，<br/>将见证普及在各地。<br/>','',58458,12017);
INSERT INTO stanza VALUES('ZS427','3','站在这异象的高峰，<br/>心里真欢欣，灵却重：<br/>我需要复活的大能，<br/>需要真实的复兴；<br/>时时照着那灵而行动，<br/>处处为那灵来撒种，<br/>成为神在地团体模型，<br/>如同主当日所实行。<br/>','',58459,12018);
INSERT INTO stanza VALUES('ZS427','4','我向自己死，向神活，<br/>凭调和的灵而活着，<br/>旧生命从此全摆脱，<br/>罪、肉体、世界消没；<br/>主，我愿作个得胜者，<br/>以此为目标、为警策，<br/>与众圣徒过神人生活，<br/>同基督显于神的国。<br/>','',58460,12019);
INSERT INTO stanza VALUES('ZS428','1','让我爱而不受感戴，<br/>让我事而不受赏赐；<br/>让我尽力而不被人记，<br/>让我受苦而不被人睹。<br/>只知倾酒不知饮酒，<br/>只想擘饼不想留饼；<br/>倒出生命来使人得幸福，<br/>舍弃安宁来使人得舒服。<br/>不受体恤，不受眷顾；<br/>不受推崇，不受安抚；<br/>宁可凄凉，宁可孤苦；<br/>宁可无告，宁可被负。<br/>愿意以血泪<br/>作为冠冕的代价，<br/>愿意受亏损<br/>来度旅客的生涯；<br/>因为当你活在这里时，<br/>你也是如此过日子。<br/>欣然忍受一切的损失，<br/>好使近你的人得安适。<br/>我今不知前途究有多远，<br/>这条道路<br/>一去就不再还原；<br/>所以让我学习<br/>你那样的完全，<br/>时常被人辜负心不生怨。<br/>求你在这惨淡时期之内，<br/>擦干我一切暗中的眼泪；<br/>学习知道你是我的安慰，<br/>并求别人喜悦以度此岁。<br/>','',58461,12020);
INSERT INTO stanza VALUES('ZS429','1','主阿，在那清晨， 你去海边等待彼得；<br/>主阿，在那正午， 你在路上等待保罗；<br/>在我的日子里， 你忽来到我的生命。<br/>你来临如强光， 那片光明不能抵挡；<br/>我真无法解释， 天天疑惑，天天相信，<br/>我真无法解释， 天天疑惑，天天相信。<br/>','',58462,1);
INSERT INTO stanza VALUES('ZS429','2','时走在大草原， 听见亲爱牧者柔声；<br/>时走在山谷间， 智慧领路暂时离开；<br/>时被带到海上， 爱我的主竟然睡著。<br/>往前的每一步， 常在冒险、惊喜之中；<br/>从来没见过祂， 天天糢糊，天天清明，<br/>从来没见过祂， 天天糢糊，天天清明。<br/>','',58463,2);
INSERT INTO stanza VALUES('ZS429','3','每天非我所愿， 日子多么富於挑战，<br/>不许安逸、自怜， 与人同情，与人同行；<br/>祂供应生命粮、 生命活水、一切动力。<br/>带人走出黑暗， 多少生命因此转换；<br/>祂能力来覆庇， 天天怯场，天天强壮，<br/>祂能力来覆庇， 天天怯场，天天强壮。<br/>','',58464,3);
INSERT INTO stanza VALUES('ZS429','4','你许凡爱你者， 一生充满多少矛盾，<br/>似乎不为人知， 却是诚实，人所共知，<br/>似乎即將丧命， 却是復活，欢呼得生。<br/>在己里有痛楚， 在你里面无量丰富；<br/>瓦器里有宝贝， 天天羞辱，天天荣耀，<br/>瓦器里有宝贝， 天天羞辱，天天荣耀。<br/>','',58465,4);
INSERT INTO stanza VALUES('ZS501','1','今从律法转向基督，<br/>投靠于祂何等有福；<br/>我们既已见祂荣耀，<br/>我们只要基督！<br/>我们只要基督，<br/>我们只要基督，<br/>我们既已见祂荣耀，<br/>我们只要基督！<br/>','',58466,12025);
INSERT INTO stanza VALUES('ZS501','2','基督领我住神殿中，<br/>在此终日向祂歌颂；<br/>哦，阿利路亚，主同在！<br/>神殿何等可爱！<br/>神殿何等可爱，<br/>神殿何等可爱，<br/>哦，阿利路亚，主同在！<br/>神殿何等可爱！<br/>','',58467,12026);
INSERT INTO stanza VALUES('ZS501','3','殿再扩大就变为城，<br/>万国所慕万民所称；<br/>神施行权柄的地方，<br/>在锡安圣山上。<br/>在锡安圣山上，<br/>在锡安圣山上，<br/>神施行权柄的地方，<br/>在锡安圣山上。<br/>','',58468,12027);
INSERT INTO stanza VALUES('ZS501','4','主从锡安要得全地，<br/>掌权并使万民欣喜；<br/>列国要来同声颂扬，<br/>向祂欢呼歌唱！<br/>向祂欢呼歌唱，<br/>向祂欢呼歌唱，<br/>列国要来同声颂扬，<br/>向祂欢呼歌唱！<br/>','',58469,12028);
INSERT INTO stanza VALUES('ZS501','5','基督乃是殿，城，与地，<br/>成全神的永远旨意；<br/>哦，弟兄们，为这目的，<br/>必须完全合一！<br/>必须完全合一，<br/>必须完全合一，<br/>哦，弟兄们，为这目的，<br/>必须完全合一！<br/>','',58470,12029);
INSERT INTO stanza VALUES('ZS502','1','当神将那被掳的带回锡安，<br/>我们像作梦的人，<br/>满怀感赞！<br/>我们满口的喜笑，<br/>满舌欢呼，<br/>神果然为我们行大事！<br/>主阿，使归回的增多，<br/>像南地河水复流！<br/>看哪！父老们在号哭，<br/>听哪，少年们在欢呼！<br/>如今我们<br/>一同经营并唱歌；<br/>流泪撒种的必欢呼收割。<br/>阿利路亚！<br/>将禾捆都带回家；<br/>在锡安荣耀归耶和华！<br/>','',58471,12030);
INSERT INTO stanza VALUES('ZS503','1','落到巴比伦，<br/>在被掳之地，<br/>哦主，将我们的灵激起！<br/>分散在各处，<br/>失去了合一，<br/>哦主，将我们的灵激起！<br/>激起！激起！哦主，<br/>将我们的灵激起！<br/>激起！激起！哦主，<br/>将我们的灵激起！<br/>','',58472,12031);
INSERT INTO stanza VALUES('ZS503','2','离开巴比伦，<br/>各宗各派之地，<br/>从分裂中我们都起来！<br/>因为巴比伦，<br/>并非神所立，<br/>从分裂中我们都起来！<br/>起来！起来！<br/>从分裂中我们都起来！<br/>（重复最后一行，下同）<br/>','',58473,12032);
INSERT INTO stanza VALUES('ZS503','3','从被掳之地，<br/>回耶路撒冷，<br/>有神同在，我们都上来！<br/>在独一立场，<br/>作合一见证，<br/>有神同在，我们都上来！<br/>上来！上来！有神同在，<br/>我们都上来！<br/>','',58474,12033);
INSERT INTO stanza VALUES('ZS503','4','盘里满基督，<br/>碗里满圣灵，<br/>将所有的器皿都带来！<br/>带到召会里，<br/>照神所命定，<br/>将所有的器皿都带来！<br/>带来！带来！<br/>将所有的器皿都带来！<br/>','',58475,12034);
INSERT INTO stanza VALUES('ZS503','5','在耶路撒冷，<br/>神所选之地，<br/>神的圣殿我们同建立！<br/>众圣同事奉，<br/>都一心一意，<br/>神的圣殿我们同建立！<br/>建立！建立！<br/>神的圣殿我们同建立！<br/>注：原文里共有五个<br/>up:Stir up<br/>','',58476,12035);
INSERT INTO stanza VALUES('ZS504','1','我已拣选了锡安，<br/>作我的居所。<br/>这是我永远安息之所，<br/>我要住这里，<br/>这是我愿意的。<br/>我要使其中的粮食丰满，<br/>使其中的穷人饱足。<br/>我要使祭司披上救恩，<br/>使圣民大声赞美欢呼。<br/>','',58477,12036);
INSERT INTO stanza VALUES('ZS505','1','耶和华所救赎的民<br/>必归回，<br/>他们要歌唱来到锡安；<br/>永远之乐<br/>必归到他们的头上。<br/>他们必得欢喜快乐；<br/>或忧愁，或叹息，<br/>尽都逃避！<br/>耶和华所救赎的民<br/>必归回，<br/>他们要歌唱来到锡安；<br/>永远之乐<br/>必归到他们的头上。<br/>','',58478,12037);
INSERT INTO stanza VALUES('ZS506','1','当周游，当周游锡安，<br/>在她的四围旋绕；<br/>当周游，当周游锡安，<br/>数点她城楼多少。<br/>','',58479,12038);
INSERT INTO stanza VALUES('ZS506','2','哦，你心当想她堡垒，<br/>哦，你当想她墙垣，<br/>哦，你心当想她堡垒，<br/>仔细察看她宫殿。<br/>','',58480,12039);
INSERT INTO stanza VALUES('ZS506','3','她在北面居高华美，<br/>乃为全地所喜悦！<br/>她在北面居高华美，<br/>锡安─价值何超越！<br/>','',58481,12040);
INSERT INTO stanza VALUES('ZS506','4','在锡安有一道河流，<br/>具有无数的分汊，<br/>在锡安有一道河流，<br/>使这城喜乐增加。<br/>','',58482,12041);
INSERT INTO stanza VALUES('ZS506','5','主，锡安等候赞美你，<br/>主，锡安等候赞你，<br/>主，锡安等候赞美你，<br/>因锡安充满了你。<br/>','',58483,12042);
INSERT INTO stanza VALUES('ZS506','6','耶和华在锡安为大，<br/>该受何等大赞美，<br/>祂在这城中本为大，<br/>这城地位何高贵。<br/>','',58484,12043);
INSERT INTO stanza VALUES('ZS506','7','哦，当从锡安称颂神，<br/>赞美声音不止息；<br/>哦，当从锡安称颂神，<br/>你们凡敬畏神的。<br/>','',58485,12044);
INSERT INTO stanza VALUES('ZS506','7','神从锡安赐福给你，<br/>神赐福无量无限；<br/>神从锡安赐福给你，<br/>赐生命福到永远！<br/>','',58486,12045);
INSERT INTO stanza VALUES('ZS506','9','看哪！何等善，何等美，<br/>弟兄们都在一起！<br/>看哪！何等善，何等美，<br/>和睦同居真合一！<br/>','',58487,12046);
INSERT INTO stanza VALUES('ZS506','10','当传说给所有后代，<br/>凡愿意的都可来；<br/>当传说给所有后代，<br/>灵与新妇都说『来！』<br/>','',58488,12047);
INSERT INTO stanza VALUES('ZS507','1','聚集在耶路撒冷，<br/>完全脱离巴比伦，<br/>我们作合一见证，<br/>哦，愿荣耀归给神！<br/>摒弃各样的教训，<br/>放下一切的异议，<br/>竭力保守灵合一，<br/>在众地方召会里。<br/>','',58489,12048);
INSERT INTO stanza VALUES('ZS507','chorus','阿利路亚！阿利路亚！<br/>我们都同心合意，<br/>建造基督的身体。<br/>阿利路亚！阿利路亚！<br/>我们如今<br/>活在地方召会里。<br/>','',58490,12049);
INSERT INTO stanza VALUES('ZS507','2','为使恢复能继续，<br/>祭司体系乃所需，<br/>惟此才蒙神称许，<br/>哦，愿荣耀归给神！<br/>祭司神前过生活，<br/>完全被主浸透过，<br/>如此建造神居所，<br/>在众地方召会里。<br/>','',58491,12050);
INSERT INTO stanza VALUES('ZS507','3','我们眼睛须开启，<br/>看见君王的治理，<br/>神圣权柄得建立，<br/>哦，愿荣耀归给神！<br/>为使召会得益处，<br/>先决条件要守住─<br/>完全向圣灵顺服，<br/>在众地方召会里。<br/>','',58492,12051);
INSERT INTO stanza VALUES('ZS507','4','我们须就近祭坛，<br/>将一切全都奉献，<br/>如此事奉理当然，<br/>哦，愿荣耀归给神！<br/>对此我们无争辩，<br/>绝对摆上心甘愿，<br/>召会合一得实现，<br/>在众地方召会里。<br/>','',58493,12052);
INSERT INTO stanza VALUES('ZS507','5','现今根基已立定！<br/>哦，何等荣耀显明！<br/>我们都快乐高兴，<br/>哦，愿荣耀归给神！<br/>让我们大声欢呼，<br/>将声音传到远处，<br/>并将仇敌全灭除，<br/>在众地方召会里。<br/>','',58494,12053);
INSERT INTO stanza VALUES('ZS508','1','哦，基督有一荣耀召会，<br/>我们有分于她─<br/>何等喜乐，<br/>主使我们合为一！<br/>看哪，<br/>在宇宙中有一身体，<br/>我们属于她─阿利路亚，<br/>主使我们合为一！<br/>阿利路亚，荣耀身体！<br/>我们是身体的肢体！<br/>一切完全为这身体！<br/>阿利路亚，<br/>主使我们合为一！<br/>','',58495,12054);
INSERT INTO stanza VALUES('ZS508','2','不是单独孤立基督徒，<br/>乃是团体新人─<br/>神需要她<br/>完全彰显祂自己！<br/>不仅是一个地方召会，<br/>乃是整个身体─<br/>阿利路亚，<br/>我们在这身体里！<br/>阿利路亚，荣耀身体！<br/>使撒但战抖的身体！<br/>在身体里我们得胜！<br/>阿利路亚，<br/>我们在这身体里！<br/>','',58496,12055);
INSERT INTO stanza VALUES('ZS508','3','神那完全圣别的性情，<br/>显在七金灯台─<br/>身体生活不容<br/>天然的存在。<br/>我们合一且有分神性，<br/>金灯台就照耀─<br/>阿利路亚，<br/>她正发光且照耀！<br/>阿利路亚，荣耀身体！<br/>这个身体是金灯台！<br/>处处发光，精光照耀！<br/>阿利路亚，<br/>她正发光且照耀！<br/>','',58497,12056);
INSERT INTO stanza VALUES('ZS508','4','我们如何彰显这合一，<br/>圣别并且照耀？<br/>阿利路亚，<br/>吃主耶稣就是路！<br/>祂是生命树，是吗哪，<br/>又是常新的筵席─<br/>阿利路亚，<br/>我们天天都吃主！<br/>我们合一借着吃主！<br/>我们圣别借着吃主！<br/>我们发光借着吃主！<br/>阿利路亚，<br/>吃主耶稣就是路！<br/>?<br/>注：『身体』可改唱<br/>『国度，』副歌改唱<br/>『我们是国度的子民。』<br/>','',58498,12057);
INSERT INTO stanza VALUES('ZS509','1','在灵里，在灵里，<br/>在灵里，在灵里，<br/>主启示给我们<br/>何等大的奥秘！<br/>在灵里看召会，<br/>在灵里看世界，<br/>在灵里看宗教，<br/>在灵里看圣城。<br/>','',58499,12058);
INSERT INTO stanza VALUES('ZS509','chorus','在灵里，在灵里，<br/>在灵里，在灵里！<br/>撇世界，脱宗教，<br/>豫备新妇，主快来了！<br/>','',58500,12059);
INSERT INTO stanza VALUES('ZS509','2','在灵里，<br/>我看见主眼目如火焰，<br/>我所有的隐密，<br/>完全显露无遗。<br/>哦，主阿，我悔改！<br/>当焚烧，就焚烧；<br/>撇世界，撇干净，<br/>使我脚，全光明。<br/>','',58501,12060);
INSERT INTO stanza VALUES('ZS509','3','在灵里，<br/>我认定那七灵和七星，<br/>七灵强，七星亮，<br/>死沉沉怎么行？<br/>我不要搞道理，<br/>只要灵和能力；<br/>脱宗教，灵发烧，<br/>烧到强，烧到亮！<br/>','',58502,12061);
INSERT INTO stanza VALUES('ZS509','4','在灵里，<br/>我保持进天国的钥匙，<br/>借祷读守你话，<br/>借呼喊尊你名，<br/>以相爱裹伤痕，<br/>以新鲜去皱纹，<br/>守冠冕，作柱子，<br/>得新名，住新城！<br/>','',58503,12062);
INSERT INTO stanza VALUES('ZS509','5','在灵里说阿们，<br/>在灵里汇一流，<br/>圣灵有新起头，<br/>我不愿再守旧；<br/>主，使我能绝对，<br/>出代价，不妥协；<br/>操练灵，释放灵，<br/>顺从灵，充满灵！<br/>','',58504,12063);
INSERT INTO stanza VALUES('ZS510','1','在这启示录的时代，<br/>看见人子的异象；<br/>在七个金灯台中间，<br/>祂与召会同动向。<br/>祂是神的独一发表，<br/>是神真实的见证，<br/>召会又是祂的发表，<br/>祂的性质是精金。<br/>','',58505,12064);
INSERT INTO stanza VALUES('ZS510','2','主阿，你曾呼召召会，<br/>发光为你作见证；<br/>我们愿意成就你意，<br/>除去所有的瑕疵。<br/>世代虽然弯曲悖谬，<br/>极其黑暗无生命，<br/>召会却是照耀明亮，<br/>将你自己全表明。<br/>','',58506,12065);
INSERT INTO stanza VALUES('ZS510','3','主阿，我们喜乐赞美，<br/>召会也是你新妇；<br/>从她你能得男孩子，<br/>借以打败你仇敌。<br/>主，我们要作得胜者，<br/>使你权柄得恢复，<br/>世界罪恶一扫而空，<br/>地上建立你国度！<br/>','',58507,12066);
INSERT INTO stanza VALUES('ZS510','4','主阿，你的所是所作，<br/>全在地方召会中，<br/>自从看见召会异象，<br/>我们此心再不移，<br/>因得启示心被吸引，<br/>渴慕奔跑到路终。<br/>为着启示录的异象，<br/>主阿，荣耀全归你！<br/>','',58508,12067);
INSERT INTO stanza VALUES('ZS511','1','看哪，在这黑夜，<br/>众地方召会<br/>作耶稣的见证，<br/>发出祂光辉。<br/>因基督而形成，<br/>以灵为模子，<br/>性质完全相同，<br/>彰显出基督。<br/>','',58509,12068);
INSERT INTO stanza VALUES('ZS511','chorus','看哪，在这黑夜，<br/>众地方召会<br/>凭圣灵而焚烧，<br/>发出主光辉。<br/>','',58510,12069);
INSERT INTO stanza VALUES('ZS511','2','神有形有体的<br/>住在基督里；<br/>基督如今是灵，<br/>是一切实际。<br/>个个金灯台<br/>是这灵的复制，<br/>召会在各地方<br/>一一的显出。<br/>','',58511,12070);
INSERT INTO stanza VALUES('ZS511','3','行走众召会中，<br/>是一位人子。<br/>祂穿着细麻衣，<br/>乃是大祭司！<br/>胸前束着金带，<br/>在爱里照顾；<br/>七星在祂手中，<br/>众召会有路！<br/>','',58512,12071);
INSERT INTO stanza VALUES('ZS511','4','谁能困金灯台？<br/>谁能来破坏？<br/>反对越发增多，<br/>牠扩展越快！<br/>环境越是黑暗，<br/>牠就越光明；<br/>因为召会乃是<br/>神生命构成。<br/>','',58513,12072);
INSERT INTO stanza VALUES('ZS511','5','从众地方召会，<br/>新妇要产生，<br/>带进荣耀圣城，<br/>新耶路撒冷。<br/>许多的金灯台，<br/>至终成一座，<br/>彰显三一之神，<br/>遍及全宇宙。<br/>','',58514,12073);
INSERT INTO stanza VALUES('ZS511','chorus','看哪，从天而降，<br/>全地都看见<br/>神的完全彰显，<br/>到永永远远！<br/>','',58515,12074);
INSERT INTO stanza VALUES('ZS512','1','在启示录第二，三章，<br/>显出七个召会真相；<br/>其中教训为着你我，<br/>在恢复中切莫错过。<br/>','',58516,12075);
INSERT INTO stanza VALUES('ZS512','2','不但她们需要细听，<br/>我们更有留心必要；<br/>为祂旨意，主发警告，<br/>使祂召会圣洁荣耀。<br/>','',58517,12076);
INSERT INTO stanza VALUES('ZS512','3','对以弗所，主有呼召：<br/>起初的爱你已失去；<br/>只顾工作，却忘了主；<br/>快快悔改，恢复当初。<br/>','',58518,12077);
INSERT INTO stanza VALUES('ZS512','4','必须转向主的自己，<br/>其他的爱都要丢抛；<br/>哦让我们听祂呼召，<br/>切勿失去宇宙至宝。<br/>','',58519,12078);
INSERT INTO stanza VALUES('ZS512','5','对士每拿，受苦之子：<br/>你曾被试，但不仅此；<br/>至死忠心，不可怕死，<br/>甘愿牺牲魂与身子。<br/>','',58520,12079);
INSERT INTO stanza VALUES('ZS512','6','忠心直到天然除净，<br/>不能看轻一切环境；<br/>主让牠们临到你身，<br/>有祂美意，试你爱情。<br/>','',58521,12080);
INSERT INTO stanza VALUES('ZS512','7','到别迦摩，堕落更深，<br/>基督教与世界通婚；<br/>忠心的安提帕殉道，<br/>惟有他才敢反宗教。<br/>','',58522,12081);
INSERT INTO stanza VALUES('ZS512','7','我们必须恐惧战兢，<br/>小心勿与世界行淫；<br/>惟有主话，能救我们，<br/>只要对牠不断经营。<br/>','',58523,12082);
INSERT INTO stanza VALUES('ZS512','9','推雅推喇跟在后面，<br/>她的能力并非属天；<br/>细面与酵混成一片，<br/>淫妇和兽联成一线。<br/>','',58524,12083);
INSERT INTO stanza VALUES('ZS512','10','我们搀杂，求主光照，<br/>主来显明所有假冒；<br/>除去一切或坏或好，<br/>直至绝对被你得着。<br/>','',58525,12084);
INSERT INTO stanza VALUES('ZS512','11','从撒狄中看得清楚，<br/>生命乃是惟一道路；<br/>她说她活，其实是死，<br/>撒狄必须接触活主。<br/>','',58526,12085);
INSERT INTO stanza VALUES('ZS512','12','主，引我们摸着生命，<br/>胜过所有死的情形；<br/>脱离一切宗教背景，<br/>满足你心，充满生命。<br/>','',58527,12086);
INSERT INTO stanza VALUES('ZS512','13','非拉铁非最终出现：<br/>应当守住她的冠冕；<br/>主名主话，弟兄相爱，<br/>如此召会，为主所爱。<br/>','',58528,12087);
INSERT INTO stanza VALUES('ZS512','14','弟兄姊妹完全是一，<br/>借着生命才有实际；<br/>单单持守祂的自己，<br/>如此通行神的旨意。<br/>','',58529,12088);
INSERT INTO stanza VALUES('ZS512','15','对老底嘉应当留心，<br/>她的堕落大有原因；<br/>皆因她说我富足了，<br/>却不知道主离开了。<br/>','',58530,12089);
INSERT INTO stanza VALUES('ZS512','16','我们不能再像温水，<br/>灵要火热，一直跟随；<br/>丰富进入生命经历，<br/>得主称许同祂坐席。<br/>','',58531,12090);
INSERT INTO stanza VALUES('ZS512','17','主阿，今天求你光照，<br/>使你道路给我看见；<br/>擦我眼睛使我富足，<br/>你的恢复快快实现。<br/>','',58532,12091);
INSERT INTO stanza VALUES('ZS513','1','看哪！<br/>各国各族各民各方人，<br/>身穿白衣，<br/>站在宝座和羔羊面前，<br/>大声欢呼，<br/>救恩归与神和羔羊，<br/>颂赞荣耀归祂，<br/>一直到永远！<br/>','',58533,12092);
INSERT INTO stanza VALUES('ZS513','2','坐宝的用帐幕覆庇我们，<br/>不再饥渴，<br/>日头炎热也必不伤害，<br/>因羔羊必领我们<br/>到生命水泉，神也必擦去<br/>我们一切的眼泪。<br/>','',58534,12093);
INSERT INTO stanza VALUES('ZS514','1','看哪！他们在各城里，<br/>站住立场同聚集，<br/>是金灯台照亮各地，<br/>使神有家可安息。<br/>','',58535,12094);
INSERT INTO stanza VALUES('ZS514','chorus','这是地方召会，<br/>是神所拣选，<br/>所有圣徒合为一；<br/>这是地方召会，<br/>是神所拣选，<br/>所有圣徒合为一。<br/>','',58536,12095);
INSERT INTO stanza VALUES('ZS514','2','看哪！他们正在聚会，<br/>他们声音何响亮！<br/>弟兄姊妹踊跃分享，<br/>将主基督来显扬。<br/>','',58537,12096);
INSERT INTO stanza VALUES('ZS514','3','听哪！他们都在祷读，<br/>将生命的话吸入，<br/>祷告，赞美，<br/>喝主，吃主，<br/>他们何等享受主！<br/>','',58538,12097);
INSERT INTO stanza VALUES('ZS514','4','听哪！<br/>他们喊『主耶稣，』<br/>他们何等爱这名！<br/>当他们宣告祂是主，<br/>喜乐就越发加增。<br/>','',58539,12098);
INSERT INTO stanza VALUES('ZS514','5','听哪！他们阿利路亚，<br/>声音如大雷爆炸！<br/>阿利路亚！阿利路亚！<br/>仇敌已经被摔下！<br/>','',58540,12099);
INSERT INTO stanza VALUES('ZS514','6','看哪！圣徒们在移民，<br/>赞美主行动开始，<br/>召会在各城市显明，<br/>使主快来不延迟。<br/>','',58541,12100);
INSERT INTO stanza VALUES('ZS514','7','看哪！主基督将要来，<br/>为祂曾舍命召会；<br/>祂今妆饰祂的心爱，<br/>作祂新妇与祂配。<br/>','',58542,12101);
INSERT INTO stanza VALUES('ZS514','chorus','荣耀的召会，<br/>毫无斑点皱纹，<br/>充满了主的荣耀。<br/>荣耀的召会，<br/>毫无斑点皱纹，<br/>充满了主的荣耀。<br/>','',58543,12102);
INSERT INTO stanza VALUES('ZS515','1','这是地方召会宣告：<br/>耶稣是主！<br/>所有圣徒欢乐称呼：<br/>耶稣是主！<br/>祂已完成一切工作，<br/>撒但全军已被征服，<br/>祂已登上荣耀宝座，<br/>耶稣是主。<br/>','',58544,12103);
INSERT INTO stanza VALUES('ZS515','2','如今祂是那位活灵，<br/>耶稣是主！<br/>祂今在此众民要听：<br/>耶稣是主！<br/>不须再有哀恸祈求，<br/>呼求祂名，祂就进入，<br/>成为你的荣耀人位，<br/>耶稣是主！<br/>','',58545,12104);
INSERT INTO stanza VALUES('ZS515','3','祂要变化你的生活，<br/>耶稣是主！<br/>将祂一切丰富赐你，<br/>耶稣是主！<br/>祂要不断满足你心，<br/>天天供应真实生命，<br/>使你与神完全结联，<br/>耶稣是主！<br/>','',58546,12105);
INSERT INTO stanza VALUES('ZS515','4','因祂怜悯接纳我们，<br/>耶稣是主！<br/>祂必永不撇下我们，<br/>耶稣是主！<br/>在身体中我们看见，<br/>祂的本性一切丰盛，<br/>仇敌魔鬼远远逃避，<br/>耶稣是主！<br/>','',58547,12106);
INSERT INTO stanza VALUES('ZS516','1','在地方召会中─<br/>神所拣选；<br/>在此基督作生命，<br/>圣灵有主权。<br/>（阿利路亚）<br/>在灵中，站立场，<br/>为主争战！<br/>我们必胜过仇敌，<br/>带进神国度─基督作王。<br/>','',58548,12107);
INSERT INTO stanza VALUES('ZS517','1','基督是元首，<br/>在地方召会，<br/>在地方召会，<br/>在地方召会；<br/>基督是元首，<br/>在地方召会，<br/>基督是元首。<br/>','',58549,12108);
INSERT INTO stanza VALUES('ZS517','2','基督是实际，<br/>在地方召会，<br/>在地方召会，<br/>在地方召会；<br/>基督是实际，<br/>在地方召会，<br/>基督是实际。<br/>','',58550,12109);
INSERT INTO stanza VALUES('ZS517','3','有丰富供应，<br/>在地方召会，<br/>在地方召会，<br/>在地方召会；<br/>有丰富供应，<br/>在地方召会，<br/>有丰富供应。<br/>','',58551,12110);
INSERT INTO stanza VALUES('ZS517','4','我们能安家，<br/>在地方召会，<br/>在地方召会，<br/>在地方召会；<br/>我们能安家，<br/>在地方召会，<br/>家，家，甜美家。<br/>','',58552,12111);
INSERT INTO stanza VALUES('ZS518','1','地方召会，可爱的召会，<br/>我灵所慕，我命所归。<br/>在祂我尝基督的丰富，<br/>何等享受！何等满足！<br/>当众圣徒在爱中被建造，<br/>作神灵里的居所，<br/>何等的美丽，<br/>何等的荣耀！<br/>地方召会，可爱的召会，<br/>我灵所慕，我命所归。<br/>','',58553,12112);
INSERT INTO stanza VALUES('ZS519','1','看哪，万民流归这山，<br/>她被高举超诸山。<br/>来罢，我们奔主的殿，<br/>训诲必出于锡安！<br/>','',58554,12113);
INSERT INTO stanza VALUES('ZS519','chorus','哦，地方召会，<br/>主何等祝福你，<br/>恩典荣耀总不离；<br/>哦，地方召会，<br/>我何等宝爱你，<br/>我心我命全归你！<br/>','',58555,12114);
INSERT INTO stanza VALUES('ZS519','2','看哪！贵重的油流淌，<br/>流到胡须和衣裳。<br/>因有弟兄和睦同居，<br/>这是何等的美善！<br/>','',58556,12115);
INSERT INTO stanza VALUES('ZS519','3','看哪！荣耀主显威荣，<br/>手拿七星赐七灵。<br/>使金灯台焚烧照明，<br/>结束时代将祂迎！<br/>','',58557,12116);
INSERT INTO stanza VALUES('ZS520','1','老宗教敬拜和虚名，<br/>仪文和其他活动。<br/>作法、规则、无数教条，<br/>老基督教的光景！<br/>如今看见主的旨意，<br/>在地方召会彰显，<br/>合一立场我们聚集，<br/>现今我们都活了。<br/>我们都活了！<br/>我们都活了！<br/>宗教观念全都丢弃，<br/>活的基督寻见了。<br/>','',58558,12117);
INSERT INTO stanza VALUES('ZS520','2','从前愿望是上天堂，<br/>天空中的『象牙塔』。<br/>虽然知道这是虚妄，<br/>我们仍是受蒙蔽。<br/>在召会立场上聚集，<br/>我们已寻到实际，<br/>神的国度就是基督，<br/>今天显在召会中。<br/>显在召会中！<br/>显在召会中！<br/>父神旨意不再落空，<br/>完全显在召会中。<br/>','',58559,12118);
INSERT INTO stanza VALUES('ZS521','1','离开，离开老旧的背景，<br/>你若肯转身，<br/>祂光必照耀；<br/>离开，离开死沉基督教，<br/>活的基督才是你所需要。<br/>','',58560,12119);
INSERT INTO stanza VALUES('ZS521','chorus','来，来这美妙地方，<br/>是神所拣选，<br/>实现祂意旨。<br/>来，来这美妙住处，<br/>不再流荡，<br/>可享安息、满足。<br/>','',58561,12120);
INSERT INTO stanza VALUES('ZS521','2','召会，召会，<br/>在地方立场，<br/>作主金灯台，<br/>照耀何辉煌。<br/>召会，召会，<br/>神永远计划，<br/>使基督安家，<br/>彰显祂智慧。<br/>','',58562,12121);
INSERT INTO stanza VALUES('ZS521','3','来罢，来罢，<br/>我们来一起，<br/>作合一见证，<br/>召会得建造。<br/>来罢，来罢，<br/>一切都成了，<br/>我们元首基督在此呼召。<br/>','',58563,12122);
INSERT INTO stanza VALUES('ZS522','1','我们看见一道河流，<br/>就投身流中，<br/>站住地方的立场。<br/>我们看见一道河流，<br/>就投身流中，<br/>站住地方的立场。<br/>','',58564,12123);
INSERT INTO stanza VALUES('ZS522','chorus','我们，我们，哦主，<br/>站住地方的立场。<br/>我们，我们，哦主，<br/>站住地方的立场。<br/>','',58565,12124);
INSERT INTO stanza VALUES('ZS522','2','我们已经看见<br/>召会恢复的异象……<br/>','',58566,12125);
INSERT INTO stanza VALUES('ZS522','3','这里乃是地方召会，<br/>非宗派公会……<br/>','',58567,12126);
INSERT INTO stanza VALUES('ZS522','4','我们爱所有的<br/>弟兄姊妹们，哦主……<br/>','',58568,12127);
INSERT INTO stanza VALUES('ZS522','5','我们蒙主呼召在此<br/>一同受训练……<br/>','',58569,12128);
INSERT INTO stanza VALUES('ZS522','6','我们已被编入军队<br/>去为主争战……<br/>','',58570,12129);
INSERT INTO stanza VALUES('ZS522','7','我们忠心站在这里<br/>直到主再来……<br/>','',58571,12130);
INSERT INTO stanza VALUES('ZS523','1','神已救我脱世界，<br/>我绝对不能再回头；<br/>神已救我脱世界，<br/>我绝对不能再回头！<br/>','',58572,12131);
INSERT INTO stanza VALUES('ZS523','chorus','不能，绝不能，<br/>我绝对不能再回头；<br/>不能，绝不能，<br/>我绝对不能再回头！<br/>','',58573,12132);
INSERT INTO stanza VALUES('ZS523','2','我已走出巴比伦……<br/>','',58574,12133);
INSERT INTO stanza VALUES('ZS523','3','我既找到了召会……<br/>','',58575,12134);
INSERT INTO stanza VALUES('ZS523','4','赞美主，我已回家……<br/>','',58576,12135);
INSERT INTO stanza VALUES('ZS523','5','我既摸着我的主……<br/>','',58577,12136);
INSERT INTO stanza VALUES('ZS523','6','基督是我的一切……<br/>','',58578,12137);
INSERT INTO stanza VALUES('ZS523','7','我是为神的恢复……<br/>','',58579,12138);
INSERT INTO stanza VALUES('ZS524','1','我们一生一定永定，<br/>阿利路亚！阿利路亚！<br/>基督召会是我永分。<br/>阿利路亚！阿利路亚！<br/>不在世界流荡飘泊，<br/>安家在召会，<br/>享受祂丰富。<br/>阿利路亚！阿利路亚！<br/>','',58580,12139);
INSERT INTO stanza VALUES('ZS525','1','我们乃是为着<br/>主的召会的恢复；<br/>乃是为着地方召会<br/>在各地显出。<br/>站住地方合一立场，<br/>在主里合一；<br/>我们建造神的居所，<br/>完成神旨意。<br/>','',58581,12140);
INSERT INTO stanza VALUES('ZS525','chorus','我们为着主，<br/>我们为着主，<br/>我们为着主的恢复！<br/>我们为着主，<br/>我们为着主，<br/>为着主的恢复！<br/>','',58582,12141);
INSERT INTO stanza VALUES('ZS525','2','我们乃是为着<br/>主的召会的恢复；<br/>见证基督，高举基督，<br/>带进神国度！<br/>活在灵中，站住立场，<br/>并广传福音。<br/>哦，主，阿们，<br/>阿利路亚！<br/>主必快再临！<br/>','',58583,12142);
INSERT INTO stanza VALUES('ZS525','3','我们乃是为着<br/>主的召会的恢复；<br/>时刻操练我们的灵，<br/>异象更清楚！<br/>大巴比伦已经倾倒，<br/>撒但被摧毁；<br/>圣城撒冷从天而降，<br/>荣耀何光辉！<br/>','',58584,12143);
INSERT INTO stanza VALUES('ZS526','1','神救我们<br/>脱离邪恶的世代，<br/>聚集一起为祂永远旨意；<br/>神的儿女<br/>都该看见这异象，<br/>阿利路亚！<br/>这是神的恢复。<br/>','',58585,12144);
INSERT INTO stanza VALUES('ZS526','chorus','我们在各城<br/>站住地方的立场，<br/>永不倚靠自己天然力量。<br/>不再是一个信徒<br/>单独的追求，<br/>乃是一直跟召会的水流，<br/>迎主再临。<br/>','',58586,12145);
INSERT INTO stanza VALUES('ZS526','2','在流中，忘记背后，<br/>随灵向前；弃绝宗教，<br/>将世界丢干净。<br/>现今主在全地<br/>不断作新事，阿利路亚！<br/>这是神的恢复。<br/>','',58587,12146);
INSERT INTO stanza VALUES('ZS526','3','七倍灵─<br/>众召会是纯金灯台，<br/>地方召会，<br/>人子显出丰采。<br/>七灯台在各地<br/>焚烧并照耀，阿利路亚！<br/>这是神的恢复。<br/>','',58588,12147);
INSERT INTO stanza VALUES('ZS526','4','主得胜，<br/>用大能建造祂召会，<br/>我们同站在祂的得胜里。<br/>都成了！<br/>仇敌已在祂的脚下，<br/>阿利路亚！<br/>这是神的恢复。<br/>','',58589,12148);
INSERT INTO stanza VALUES('ZS526','5','祂生命在召会中<br/>供应无限，阿利路亚！<br/>众召会同向前。<br/>这水流乃基督<br/>作我们实际，阿利路亚！<br/>这是神的恢复。<br/>','',58590,12149);
INSERT INTO stanza VALUES('ZS526','6','在召会中<br/>我们同见这异象，<br/>永不单独，<br/>我们建造一起。<br/>同往前，<br/>在这时代作主见证，<br/>阿利路亚！<br/>这是神的恢复。<br/>','',58591,12150);
INSERT INTO stanza VALUES('ZS527','1','我们都是为着神的恢复，<br/>神的恢复，神的恢复。<br/>我们都是为着神的见证，<br/>神的见证，神的见证。<br/>刚强火热的灵<br/>在焚烧我们，<br/>焚烧我们，焚烧我们。<br/>单一纯洁的心，<br/>时时亲近神，<br/>时时近神，时时近神。<br/>事业！前途！何屑一顾。<br/>活着只为祂的恢复。<br/>祂的恢复，祂的恢复，<br/>祂的恢复！<br/>我们是为神的恢复，<br/>神的见证！<br/>事业！前途！何屑一顾。<br/>活着只为着祂的恢复。<br/>恢复，恢复，恢复，<br/>恢复，恢复，恢复！<br/>我们是为神的恢复，<br/>神的见证！<br/>','',58592,12151);
INSERT INTO stanza VALUES('ZS528','1','这是时候，朋友，<br/>日子已经不多；<br/>要事奉谁，<br/>必须趁早选择！<br/>愿否同一阵线，<br/>为主奋勇争战，<br/>击溃仇敌─<br/>那狡猾的撒但？<br/>','',58593,12152);
INSERT INTO stanza VALUES('ZS528','2','这是时候，圣徒，<br/>到处人心惶惶，<br/>撒但猖狂，<br/>遍地兴风作浪。<br/>所以我们必须<br/>看万事如粪土，<br/>不计代价，<br/>奉献为主恢复！<br/>','',58594,12153);
INSERT INTO stanza VALUES('ZS528','3','这是时候，圣徒，<br/>圣灵正在运行，<br/>加速恢复，<br/>拔高纯洁人性，<br/>照着祂的计划，<br/>产生『一个新人，』<br/>借此吸引这一代归向神。<br/>','',58595,12154);
INSERT INTO stanza VALUES('ZS528','4','这是末了时日，<br/>应当出去宣告，<br/>让人听见国度即将来到！<br/>神的军队所至，<br/>仇敌一一赶出，<br/>好使全地重新归服基督。<br/>','',58596,12155);
INSERT INTO stanza VALUES('ZS529','1','进入启示录的时代，<br/>从各宗派完全脱离；<br/>我们在众地方召会，<br/>灵里合一。<br/>没有老旧宗教捆绑，<br/>个个都是发光亮星；<br/>各地召会是金灯台，<br/>因主焚烧。<br/>主与焚烧召会，<br/>主与焚烧召会，<br/>在召会中，<br/>圣徒都是发光星！<br/>阿利路亚！阿利路亚！<br/>主，我们将命献给你，<br/>为着在灵里焚烧，<br/>将基督来照明。<br/>','',58597,12156);
INSERT INTO stanza VALUES('ZS530','1','焚烧，焚烧，<br/>日夜焚烧，<br/>不断回到我们灵里；<br/>为着你永远的旨意，<br/>灵里合一。<br/>我们站住地方立场，<br/>召会合一在此显彰；<br/>肢体虽多，仍是一身，<br/>基督为首。<br/>','',58598,12157);
INSERT INTO stanza VALUES('ZS530','chorus','基督与祂召会，<br/>基督与祂召会，<br/>乃是我们<br/>一切实际和生活。<br/>阿利路亚，阿利路亚，<br/>主，我们将命献给你，<br/>为建造你的身体，<br/>并在爱中被建立。<br/>','',58599,12158);
INSERT INTO stanza VALUES('ZS530','2','呼吸，呼吸，<br/>我们呼吸，<br/>每一呼吸得新气息，<br/>何等的变化，<br/>一切陈旧全更新。<br/>呼出我们老旧自己，<br/>吸入新生命与合一，<br/>我们今吸入主耶稣，<br/>吸入生命。<br/>','',58600,12159);
INSERT INTO stanza VALUES('ZS531','1','我们在流中，<br/>我们在流中！<br/>哦，阿利路亚，在流中！<br/>（二遍）<br/>哦，赞美主，<br/>我们在流中！<br/>哦，阿利路亚，在流中！<br/>哦，赞美主，<br/>我们在流中！<br/>哦，阿利路亚，在流中。<br/>','',58601,12160);
INSERT INTO stanza VALUES('ZS532','1','何等奇妙的事实，<br/>我竟成为你基业，<br/>你的丰富原无比，<br/>无我却仍有所缺。<br/>','',58602,12161);
INSERT INTO stanza VALUES('ZS532','chorus','哦！我们竟成为<br/>你爱的对象，<br/>将你丰富来彰显，<br/>你荣耀得称赞。<br/>哦！我们竟成为<br/>你爱的对象，<br/>将你丰富来彰显，<br/>叫你荣耀得称赞。<br/>','',58603,12162);
INSERT INTO stanza VALUES('ZS532','2','照你所定的美意，<br/>我得各样的福气，<br/>创世以前蒙拣选，<br/>今得救赎成圣洁。<br/>','',58604,12163);
INSERT INTO stanza VALUES('ZS532','3','借你圣灵作凭质，<br/>我得被赎的确据，<br/>满得智慧和启示，<br/>对你完全有认识。<br/>','',58605,12164);
INSERT INTO stanza VALUES('ZS532','4','当我心眼被照明，<br/>知你恩召满指望，<br/>你复活大能大力，<br/>也显在我们身上。<br/>','',58606,12165);
INSERT INTO stanza VALUES('ZS532','5','主，我们满心赞美<br/>我们乃是你基业，<br/>是你召会你身体，<br/>你今是一无所缺。<br/>','',58607,12166);
INSERT INTO stanza VALUES('ZS533','1','我们在旷野流落，<br/>日子已经够久；<br/>谁说要进入迦南，<br/>现在不是时候？看哪，<br/>荣耀在望，<br/>应当刚强胆壮！<br/>我们是新的一代，<br/>一定要过去承受！<br/>快，快，快！为主恢复，<br/>我们不能再落后。<br/>','',58608,12167);
INSERT INTO stanza VALUES('ZS533','2','我们有主的约柜，<br/>走在我们前头，<br/>要领我们走新路，<br/>向来没有走过。<br/>看哪，约但河水，<br/>已经立起如垒；<br/>我们这一代<br/>应该打断世界的潮流！<br/>走，走，走！我们大伙儿<br/>浩浩荡荡往前走！<br/>','',58609,12168);
INSERT INTO stanza VALUES('ZS533','3','赞美主，阿利路亚，<br/>我们到了吉甲；<br/>老旧已经埋葬了，<br/>肉体也被割下。<br/>吃了迦南土产，<br/>吗哪不再稀罕；<br/>我们不再像从前<br/>完全靠神迹度日。<br/>吃，吃，吃！为着争战<br/>天天吃迦南产物！<br/>','',58610,12169);
INSERT INTO stanza VALUES('ZS533','4','与主同站在一边，<br/>不怕没主同在；<br/>照着主吩咐去行，<br/>因为主是元帅！<br/>无论关得多紧，<br/>你这城耶利哥，<br/>等我们大声呼喊，<br/>你就非倒塌不可！<br/>去，去，去！我们出去，<br/>把各城一一夺取。<br/>','',58611,12170);
INSERT INTO stanza VALUES('ZS533','5','这全地不为别的，<br/>乃是为着召会！<br/>主，我们奉献一切，<br/>让你能早归回。<br/>你若还不满意，<br/>我们也不满意，<br/>疯，疯，疯！为着全岛<br/>我们要继续发疯，<br/>直到神所应许的，<br/>没有一句话落空。<br/>','',58612,12171);
INSERT INTO stanza VALUES('ZS601','1','神的生命，是人需要；<br/>神的建造是神的目标。<br/>基督得胜，魔鬼蒙羞；<br/>神的计划不久要成就！<br/>','',58613,12172);
INSERT INTO stanza VALUES('ZS601','chorus','建造我，主耶稣！<br/>我不愿再我行我素。<br/>『活在灵中，经常祷读，<br/>多祷告。』阿们，主！<br/>','',58614,12173);
INSERT INTO stanza VALUES('ZS601','2','生命的主，满有个性；<br/>祂的丰富是我们供应。<br/>为着建造，需要生命；<br/>生命、建造，<br/>原相辅相成。<br/>','',58615,12174);
INSERT INTO stanza VALUES('ZS601','3','我们起来，献上自己，<br/>一手建造，一手拿兵器。<br/>除去纷争，消杀己意，<br/>两刃利剑，刺身内仇敌。<br/>','',58616,12175);
INSERT INTO stanza VALUES('ZS601','4','有一条路<br/>是通到主丰盛的生命，<br/>借这生命长进，<br/>建造自然产生；<br/>只要全人敞开，<br/>心转向主，在灵里<br/>天天都来祷读，来祷读。<br/>（接到副歌）<br/>','',58617,12176);
INSERT INTO stanza VALUES('ZS602','1','我们看见你荣耀计画，<br/>要在地上建造你家；<br/>不禁祷告：『主，<br/>得着我们，建造我们─<br/>照你办法！』<br/>你的回答迅速又肯定：<br/>『为建我家，你当知道：<br/>你魂生命必须要了了，<br/>你必须在坛上仆倒。』<br/>','',58618,12177);
INSERT INTO stanza VALUES('ZS602','2','乍听之下，审判太严厉，<br/>难免令人不寒而栗；<br/>但是我们天天亲近你，<br/>任何代价就可不计。<br/>为你的家我们愿受死，<br/>好让你作我们一切；<br/>你是我们完全的供应，<br/>你是我们建造凭借。<br/>','',58619,12178);
INSERT INTO stanza VALUES('ZS602','3','为你计划我们献自己，<br/>虽不尽知其中深意；<br/>生命一切，如今全献上，<br/>作为活祭，倒出、失去。<br/>在你坛上，<br/>主，烧毁我们，<br/>直到成灰，完全彻底，<br/>让你馨香，袅袅不绝的，<br/>在赞美中永远归你。<br/>','',58620,12179);
INSERT INTO stanza VALUES('ZS603','1','记得大卫起誓：<br/>『我不进我的帐幕，<br/>不上我的床榻，<br/>不容我打盹闭目，<br/>直等到我为耶和华，<br/>寻得安息之处。』<br/>全能的神<br/>巴望有家使属祂者可住。<br/>','',58621,12180);
INSERT INTO stanza VALUES('ZS603','2','我们何等眼瞎，<br/>只顾自己的事务，<br/>任凭神殿荒凉─<br/>哦主，你必须有路！<br/>我们情愿上山取木，<br/>为建你殿劳碌；<br/>绝不再说：<br/>『且等明日，』<br/>建造当趁今日！<br/>','',58622,12181);
INSERT INTO stanza VALUES('ZS603','3','哦主，此时此境，<br/>激动人起来建造，<br/>正如大卫之日，<br/>自动答应你呼召。<br/>同心合意，配搭一起，<br/>受此托付，多好！<br/>我们所喜，是你心意，<br/>主，我们来建造。<br/>','',58623,12182);
INSERT INTO stanza VALUES('ZS603','4','主，为着你召会，<br/>叫我们废寝忘食，<br/>为建造献一切─<br/>专心豫备你居所！<br/>阴间的门不能胜过<br/>已建成的召会。<br/>时候不多，建造我们，<br/>让你能早归回！<br/>（重复最后两行）<br/>','',58624,12183);
INSERT INTO stanza VALUES('ZS604','1','全地平静安息，<br/>神却为着祂的见证，<br/>心里火热着急，<br/>祂是何等着急！<br/>弟兄姊妹，<br/>我们不能只顾自己，<br/>依旧贪享安逸，<br/>安逸会被撇弃。<br/>','',58625,12190);
INSERT INTO stanza VALUES('ZS604','2','定期已经到了，<br/>神要来再拣选我们，<br/>复兴全地召会，<br/>现在正是时候！<br/>弟兄姊妹，<br/>我们应当趁这关头，<br/>起来与主配合，<br/>不容机会错过。<br/>','',58626,12191);
INSERT INTO stanza VALUES('ZS604','3','请听主的应许：<br/>我要回到耶路撒冷，<br/>仍旧与你同住，<br/>使你丰盛发达。<br/>我的城邑，<br/>要像无城墙的乡村，<br/>因为生养众多，<br/>甚至容纳不下。<br/>','',58627,12192);
INSERT INTO stanza VALUES('ZS604','4','神已开始作工，<br/>看哪，祂正兴起环境，<br/>要来震动列国，<br/>好使召会抬头。<br/>我们宣告：<br/>这个大地，乃至宇宙，<br/>都是属于主的，<br/>撒但休要伸手，<br/>','',58628,12193);
INSERT INTO stanza VALUES('ZS604','5','我们有主的话，<br/>我们不是依靠势力，<br/>不是倚靠才能，<br/>乃是靠主的灵。<br/>哦，大山哪，<br/>别在我们面前作祟，<br/>你算不得甚么，<br/>迟早要被铲平。<br/>','',58629,12194);
INSERT INTO stanza VALUES('ZS604','6','七眼遍察全地，<br/>看见我们手拿线铊，<br/>神是何等欢喜！<br/>别的祂不在意！<br/>荣耀！荣耀！<br/>殿的根基既然立了，<br/>圣殿也必完成，<br/>成在我们手里。<br/>','',58630,12195);
INSERT INTO stanza VALUES('ZS605','1','万世之前主选我，<br/>到了今世我蒙召，<br/>分别为圣归于祂─<br/>为建造！<br/>借着爱子的宝血，<br/>儿子名分我得到，<br/>生在神的甜美家，<br/>为建造！<br/>','',58631,12196);
INSERT INTO stanza VALUES('ZS605','chorus','为建造！为建造！<br/>放下成见与爱好，<br/>为建造！<br/>阿们圣灵与召会，<br/>阿们职事的引导，<br/>完全投身主经营，<br/>为建造！<br/>','',58632,12197);
INSERT INTO stanza VALUES('ZS605','2','我们既然蒙主召，<br/>行事为人照恩膏，<br/>凡事谦卑并温柔─<br/>为建造！<br/>相互宽容过得去，<br/>存心忍耐吃得消，<br/>竭力保守那灵一─<br/>为建造！<br/>','',58633,12198);
INSERT INTO stanza VALUES('ZS605','3','使徒、先知祂设立，<br/>建造根基所凭靠，<br/>成全圣徒各尽职─<br/>为建造！<br/>凡事长进联元首，<br/>百节相助功用调，<br/>各站地位尽本分─<br/>为建造！<br/>','',58634,12199);
INSERT INTO stanza VALUES('ZS605','4','我们不再作小孩，<br/>中了诡计随风飘，<br/>惟在爱中持真实─<br/>为建造！<br/>全房靠祂得联络，<br/>同归于一在真道，<br/>天衣无缝配搭好─<br/>为建造！<br/>','',58635,12200);
INSERT INTO stanza VALUES('ZS606','1','建造神的圣殿的时候<br/>已经来到，<br/>所有的地方召会<br/>要完全被建造。<br/>不该专顾你的家，<br/>而神家却荒废；<br/>弟兄们，快快兴起，<br/>建造召会！<br/>','',58636,12201);
INSERT INTO stanza VALUES('ZS606','chorus','刚强！刚强！<br/>全体起来建造！<br/>神必定与我们同在，<br/>使殿满了荣耀。<br/>刚强！刚强！<br/>同心合意工作；地上万国<br/>都要看见神荣耀的居所！<br/>','',58637,12202);
INSERT INTO stanza VALUES('ZS606','2','听阿，神说：<br/>你们要省察自己行为，<br/>撒种虽多，收却少，<br/>因对我缺赞美；<br/>你们要上到山上<br/>去为我取木料，<br/>同心建造我居所，<br/>我得荣耀。<br/>','',58638,12203);
INSERT INTO stanza VALUES('ZS606','3','你们蒙召的祭司<br/>当向神全顺服，<br/>神既与我们同在，<br/>管他世人怒目，<br/>灵里激动并火热，<br/>我们同来作工，<br/>但愿在其中<br/>没有一人放松。<br/>','',58639,12204);
INSERT INTO stanza VALUES('ZS606','4','万军之耶和华说：<br/>我殿要满荣耀，<br/>地上万国羡慕的<br/>必定快要来到，<br/>这殿后来的荣耀<br/>必大过先前的，<br/>我们同享这荣耀，<br/>喜乐无比。<br/>','',58640,12205);
INSERT INTO stanza VALUES('ZS607','1','阿利路亚，我是活石，<br/>为被基督建造！<br/>我对祂说：<br/>『你是基督，』<br/>祂立刻对我说，<br/>『你是一块石头。』<br/>阿利路亚，我是活石！<br/>','',58641,12206);
INSERT INTO stanza VALUES('ZS608','1','来罢！活石同来建造<br/>耶路撒冷的城墙，<br/>我们不再受到凌辱，<br/>圣城已联络整齐。<br/>','',58642,12207);
INSERT INTO stanza VALUES('ZS608','chorus','阿利路亚！<br/>我们都在祂里面<br/>同被建造，<br/>成为神在灵里居所，<br/>借她彰显神荣耀。<br/>','',58643,12208);
INSERT INTO stanza VALUES('ZS608','2','为着恢复投身流中，<br/>产生宝石与珍珠，<br/>不再单独追求属灵，<br/>愿和圣徒同建造。<br/>','',58644,12209);
INSERT INTO stanza VALUES('ZS608','3','我们的灵相调一起，<br/>才有建造的实际，<br/>不谈关系情感兴趣，<br/>乃是灵与灵相系。<br/>','',58645,12210);
INSERT INTO stanza VALUES('ZS608','4','不是尽喊口号道理，<br/>乃是实际摆上去，<br/>一同享受配搭事奉，<br/>天天经营不松弛。<br/>','',58646,12211);
INSERT INTO stanza VALUES('ZS608','5','建造实际灵中显露，<br/>生命活水就流出，<br/>轮中套轮行动快速，<br/>配搭犹如四活物。<br/>','',58647,12212);
INSERT INTO stanza VALUES('ZS608','6','阿利路亚我真欢喜，<br/>我是快乐的肢体，<br/>我愿脱离关闭自己，<br/>投身荣耀经营里。<br/>','',58648,12213);
INSERT INTO stanza VALUES('ZS608','chorus','求主使我心思改变，<br/>有这属天的观念，<br/>凡我生活所作所言，<br/>都为让神得彰显。<br/>','',58649,12214);
INSERT INTO stanza VALUES('ZS609','1','相调为一，<br/>灵里相调为一！<br/>相调为一，<br/>灵里相调为一！<br/>从个人、关闭出来，<br/>调入灵里，<br/>哦，灵里相调，<br/>直到调为一。<br/>调罢，弟兄！<br/>调罢，姊妹！<br/>灵里相调为一。<br/>（荣耀，阿利路亚！）<br/>追求、交通、事奉，<br/>众灵调为一灵。<br/>调罢，灵里调罢！<br/>','',58650,12215);
INSERT INTO stanza VALUES('ZS609','2','同被建造，<br/>爱中同被建造。<br/>同被建造，<br/>爱中同被建造。<br/>要脱离骄傲、不服，<br/>同被建造。<br/>哦！彼此配搭，<br/>一同被建造。<br/>建造，弟兄！<br/>建造，姊妹！<br/>爱中同被建造。<br/>（荣耀，阿利路亚！）<br/>肢体彼此相顾，<br/>长幼互相顺服，<br/>爱中同被建造。<br/>','',58651,12216);
INSERT INTO stanza VALUES('ZS610','1','借主宝血，<br/>我们已被赎回。<br/>借主宝血，<br/>我们已被赎回。<br/>借主宝血，<br/>我们已被赎回。<br/>荣耀，荣耀，今看见！<br/>我们罪恶全得赦免，<br/>全得赦免。<br/>','',58652,12217);
INSERT INTO stanza VALUES('ZS610','2','蒙主拣选，<br/>我们都是祭司。<br/>蒙主拣选，<br/>我们都是祭司。<br/>蒙主拣选，<br/>我们都是祭司。<br/>荣耀，荣耀，今看见！<br/>我们侍立在神面前，<br/>在神面前。<br/>','',58653,12218);
INSERT INTO stanza VALUES('ZS610','3','在基督里，<br/>我们都是弟兄。<br/>在基督里，<br/>我们都是弟兄。<br/>在基督里，<br/>我们都是弟兄。<br/>荣耀，荣耀，今看见！<br/>在主爱里一同向前，<br/>一同向前。<br/>','',58654,12219);
INSERT INTO stanza VALUES('ZS610','4','在基督里，<br/>我们都是姊妹。<br/>在基督里，<br/>我们都是姊妹。<br/>在基督里，<br/>我们都是姊妹。<br/>荣耀，荣耀，今看见！<br/>在主爱里一同向前，<br/>一同向前。<br/>','',58655,12220);
INSERT INTO stanza VALUES('ZS610','5','弟兄姊妹，<br/>我们彼此相爱。<br/>弟兄姊妹，<br/>我们彼此相爱。<br/>弟兄姊妹，<br/>我们彼此相爱。<br/>荣耀，荣耀，今看见！<br/>『非拉铁非』在此出现，<br/>在此出现。<br/>','',58656,12221);
INSERT INTO stanza VALUES('ZS610','6','我们站住地方一的立场。<br/>我们站住地方一的立场。<br/>我们站住地方一的立场。<br/>荣耀，荣耀，今看见！<br/>主的恢复完全实现，<br/>完全实现。<br/>','',58657,12222);
INSERT INTO stanza VALUES('ZS611','1','主，我们是你身体<br/>在此聚集，人数虽多，<br/>我们仍然是一。<br/>你的生命<br/>使我们成为肢体，<br/>在生命里，<br/>我们完全是一。<br/>','',58658,12223);
INSERT INTO stanza VALUES('ZS611','chorus','在宇宙中只有一个身体，<br/>我们将她彰显于地；<br/>我们站住地方一的立场，<br/>让所有人同来观赏。<br/>','',58659,12224);
INSERT INTO stanza VALUES('ZS611','2','这一个饼乃是<br/>表明你身体，曾被擘开，<br/>好使众圣分享；<br/>我们吃饼，<br/>如此一同领受你，<br/>借此见证我们真正是一。<br/>','',58660,12225);
INSERT INTO stanza VALUES('ZS611','3','现在桌上陈列着<br/>一饼一杯，说出我们<br/>不能分门别类；<br/>同蒙主恩，<br/>还有甚么话可说，<br/>惟有喊说：『阿们，<br/>我们是一！』<br/>','',58661,12226);
INSERT INTO stanza VALUES('ZS611','4','我们是一，<br/>不能再被谁分离，<br/>因为这『一』<br/>出自基督自己。<br/>同一饼杯，<br/>我们在这一里吃，<br/>有目共睹这个一的事实。<br/>','',58662,12227);
INSERT INTO stanza VALUES('ZS611','5','何等喜乐，<br/>能有分于这个一！<br/>我们深觉，<br/>主，这使你满意！<br/>满足之中，<br/>我们豫尝了那日，<br/>新郎新妇那最甜美的一。<br/>','',58663,12228);
INSERT INTO stanza VALUES('ZS612','1','我们已经看见<br/>召会是在合一里面，<br/>在和谐中我们联结，<br/>见证唱诗赞美。地方召会<br/>才是祂惟一所爱的新妇，<br/>借呼喊主<br/>我们能够更多得着基督。<br/>','',58664,12229);
INSERT INTO stanza VALUES('ZS612','chorus','惟有祂是爱，<br/>我们天天享受，<br/>我们天天享受，<br/>真实的爱。<br/>','',58665,12230);
INSERT INTO stanza VALUES('ZS612','2','安家召会，享受基督，<br/>使我们得饱足；<br/>灵和召会，<br/>才是我们今日真正恢复。<br/>借呼喊主，<br/>我们吸入祂所有的丰富，<br/>当我们被浸透占有，<br/>灵就得着自由。<br/>','',58666,12231);
INSERT INTO stanza VALUES('ZS612','3','爱的水流，来自宝座，<br/>使我清新明透，<br/>何等甘甜，何等荣耀，<br/>让我们全享受。<br/>爱的联结，如此深厚，<br/>使我们得造就，<br/>哦，让我们在召会中，<br/>一同长大成熟！<br/>','',58667,12232);
INSERT INTO stanza VALUES('ZS613','1','我们在主里是一，<br/>在圣灵里是一；<br/>我们在主里是一，<br/>在圣灵里是一；<br/>我们赞美祂，<br/>因祂使我们永远合一。<br/>','',58668,12233);
INSERT INTO stanza VALUES('ZS613','chorus','在主的爱里我们永合一，<br/>永合一；<br/>在主的爱里我们永合一，<br/>永合一；<br/>我们赞美祂，<br/>因祂使我们永远合一。<br/>','',58669,12234);
INSERT INTO stanza VALUES('ZS613','2','我们众人被建造，<br/>在爱里被建造；<br/>我们众人被建造，<br/>在爱里被建造；<br/>便叫身体渐渐长大，<br/>显出神的荣耀。<br/>','',58670,12235);
INSERT INTO stanza VALUES('ZS613','3','如今主就是那灵，<br/>主灵在我灵里；<br/>如今主就是那灵，<br/>主灵在我灵里；<br/>在主灵里我们<br/>同被建造合而为一。<br/>','',58671,12236);
INSERT INTO stanza VALUES('ZS613','4','愿颂赞归于圣父，<br/>祂是一切源头；<br/>愿颂赞归于圣子，<br/>祂将一切承受；<br/>又愿颂赞归于圣灵，<br/>祂将一切渗透。<br/>','',58672,12237);
INSERT INTO stanza VALUES('ZS614','chorus','当我们信入神儿子，<br/>借祂的灵我们合一；<br/>当我们信入神儿子，<br/>借祂的灵我们合一。<br/>合为一，我们合为一；<br/>合为一，我们合为一；<br/>合为一，我们合为一；<br/>合为一！<br/>世界一直寻求和平，<br/>战争风声却总不停；<br/>忧心忡忡，无法消除；<br/>多少恨，多少泪，<br/>多少苦！主才是路！<br/>（接副歌，下同）<br/>','',58673,12238);
INSERT INTO stanza VALUES('ZS614','1','我们在主爱里同住，<br/>真正合一已经恢复；<br/>弟兄姊妹不分彼此，<br/>父与子如何是永合一，<br/>我们也是！<br/>','',58674,12239);
INSERT INTO stanza VALUES('ZS614','2','众圣徒们和睦同居，<br/>何等的好，何等美丽！<br/>满了膏油，满了甘露，<br/>神永远的生命<br/>够你我永远享受！<br/>','',58675,12240);
INSERT INTO stanza VALUES('ZS615','1','知否神有一需要，<br/>弟兄姊妹们？<br/>神需要有一居所，<br/>让祂安家！<br/>我们若合而为一，<br/>就被建造成神家，<br/>这家使神安息，<br/>我们也得安息。<br/>','',58676,12241);
INSERT INTO stanza VALUES('ZS615','2','我们若分裂四散，<br/>居所怎出现？<br/>主心所喜爱乃是<br/>同心合意。<br/>故我们必须放下，<br/>拦阻合一的异议，<br/>如此带进合一，<br/>如此带进合一。<br/>','',58677,12242);
INSERT INTO stanza VALUES('ZS615','3','当我们活在『一』里，<br/>这相爱显出。<br/>这爱是在神家里，<br/>实际真挚。<br/>在这家我们尝尽，<br/>历代圣徒的丰富。<br/>神家满了肥甘！<br/>神家满了肥甘！<br/>','',58678,12243);
INSERT INTO stanza VALUES('ZS615','4','你是否真为召会？<br/>在主前显出？<br/>愿否把自己摆上，<br/>加强恢复？<br/>愿否接受这挑战，<br/>承担召会的托付？<br/>绝对为神花费，<br/>绝对为神花费！<br/>','',58679,12244);
INSERT INTO stanza VALUES('ZS615','5','从过去所有时代，<br/>主拣选我们<br/>这荣耀有福一代，<br/>带进国度！<br/>但我们不能停顿，<br/>因目前所有满足。<br/>我们努力向前！<br/>我们努力向前！<br/>','',58680,12245);
INSERT INTO stanza VALUES('ZS616','1','从前我们在罪中死了，<br/>这世界全然一团糟；<br/>但神使我们一起复活，<br/>一起与基督升天，<br/>同坐宝座。<br/>','',58681,12246);
INSERT INTO stanza VALUES('ZS616','chorus','耶稣聚集我们在一起，<br/>请看看圣徒同心合意！<br/>主爱使得我们都一致，<br/>达到基督<br/>丰满身量的地步。<br/>','',58682,12247);
INSERT INTO stanza VALUES('ZS616','2','因此我们能和众圣徒，<br/>一起明白基督的爱；<br/>长阔高深虽然无法测度，<br/>但神的丰满<br/>我们一再得着。<br/>','',58683,12248);
INSERT INTO stanza VALUES('ZS616','3','神在历代隐藏的旨意，<br/>已成了显明的奥秘；<br/>基督，召会，<br/>我们今看见，<br/>这真叫撒但受辱，<br/>羞惭满面！<br/>','',58684,12249);
INSERT INTO stanza VALUES('ZS616','4','我们为此来祷告父神─<br/>刚强我们里面的人，<br/>让你安家在我们心里，<br/>使我们<br/>在你爱中生根立基。<br/>','',58685,12250);
INSERT INTO stanza VALUES('ZS616','5','在身体里联络得合式，<br/>各筋节都供应基督，<br/>各个肢体功用都摆上，<br/>使身体得着建造，<br/>不断增长！<br/>','',58686,12251);
INSERT INTO stanza VALUES('ZS616','6','如今我们已合而为一，<br/>成为神所要的新人；<br/>在基督里，在召会中间，<br/>愿荣耀归神，<br/>直到永永远远！<br/>','',58687,12252);
INSERT INTO stanza VALUES('ZS617','1','我们聚在一起<br/>来吃主的晚餐；<br/>借着这吃喝，<br/>来把合一展览。<br/>越发宣告合一，<br/>越发有主同在，<br/>深知如此吃喝，<br/>蒙主祝福眷爱。<br/>','',58688,12253);
INSERT INTO stanza VALUES('ZS617','2','我们所吃的饼<br/>乃是主的身体，<br/>擘开吃进去，<br/>加起来仍是一。<br/>桌上只有一饼─<br/>只有一个身体，<br/>为着向人表明，<br/>我们主里是一。<br/>','',58689,12254);
INSERT INTO stanza VALUES('ZS617','3','我们所喝的杯<br/>乃是主的新约，<br/>我们今一同<br/>交通于主的血。<br/>接纳所有圣徒─<br/>只要因血得赎，<br/>在神面前称谢<br/>我们如何蒙福。<br/>','',58690,12255);
INSERT INTO stanza VALUES('ZS617','4','我们别无可说，<br/>除说，『阿利路亚，』<br/>因主给我们<br/>经历了这实际。<br/>取用主的宝血，<br/>享受主的身体，<br/>主就得着召会，<br/>荣耀归祂自己。<br/>','',58691,12256);
INSERT INTO stanza VALUES('ZS618','1','我们在神家里，<br/>蒙召在一起，<br/>因宝血洗净，<br/>得成为圣洁；<br/>借圣灵重生，<br/>并与神联结，<br/>作了神后嗣，<br/>成了祂基业。<br/>自由饱足安息，<br/>赞美歌颂不绝。<br/>哦阿利路亚，<br/>蒙召在一起。<br/>','',58692,12257);
INSERT INTO stanza VALUES('ZS618','2','我们在圣灵里，<br/>交通在一起，<br/>丢弃了道理，<br/>抛掉了虚仪；<br/>不拘在形式，<br/>不泥于字句，<br/>生命的新样，<br/>活水的洋溢。<br/>不再属于宗教，<br/>凡事追求实际，<br/>哦阿利路亚，<br/>交通在一起。<br/>','',58693,12258);
INSERT INTO stanza VALUES('ZS618','3','我们在召会里，<br/>事奉在一起，<br/>除尽了恶毒，<br/>吃饱了灵食；<br/>来到主面前，<br/>个个像活石，<br/>建造为灵宫，<br/>祭司的体系。<br/>借着耶稣基督，<br/>奉献神喜灵祭，<br/>哦阿利路亚，<br/>事奉在一起。<br/>','',58694,12259);
INSERT INTO stanza VALUES('ZS618','4','我们在主爱里，<br/>结合在一起，<br/>用爱心包容，<br/>用和平联系；<br/>一人有心欢乐，<br/>大家都欣喜，<br/>一人有心伤，<br/>众人都流泪。<br/>彼此相助相顾，<br/>全体同心合意，<br/>哦阿利路亚，<br/>结合在一起。<br/>','',58695,12260);
INSERT INTO stanza VALUES('ZS618','5','我们在主营里，<br/>争战在一起，<br/>守住了立场，<br/>站稳了等次；<br/>穿戴神军装，<br/>手执主兵器，<br/>奉耶稣大名，<br/>靠元首功绩。<br/>随时多方祷告，<br/>灭尽仇敌诡计，<br/>哦阿利路亚，<br/>争战在一起。<br/>','',58696,12261);
INSERT INTO stanza VALUES('ZS618','6','我们在荣耀里，<br/>与主在一起，<br/>咒诅成往事，<br/>天地俱和煦；<br/>生命水解渴，<br/>生命果充饥，<br/>新郎偕新妇，<br/>相爱永同居。<br/>神人永远合一，<br/>光明喜乐无比，<br/>哦阿利路亚，<br/>与主在一起。<br/>','',58697,12262);
INSERT INTO stanza VALUES('ZS701','1','听这流浪者的歌声，<br/>把他经历道出：<br/>在他已过的年日里，<br/>他总常感不足。<br/>','',58698,12263);
INSERT INTO stanza VALUES('ZS701','chorus','赞美主！赞美主！<br/>赞美主！<br/>阿利路亚，阿利路亚，<br/>赞美主！赞美主！<br/>我永不再那样！<br/>（一至三节）<br/>','',58699,12264);
INSERT INTO stanza VALUES('ZS701','2','流浪奔波在世界里，<br/>寻求快乐满足；<br/>但是我的肉体心灵，<br/>仍然虚空痛苦。<br/>','',58700,12265);
INSERT INTO stanza VALUES('ZS701','3','昼夜劳苦为着自己，<br/>我房建在沙地；<br/>但赞美主！祂来拆毁，<br/>给我更好豫备。<br/>','',58701,12266);
INSERT INTO stanza VALUES('ZS701','4','如今找到地方召会，<br/>作一喜乐肢体；<br/>结束流浪者的生活，<br/>安居在神家里。<br/>','',58702,12267);
INSERT INTO stanza VALUES('ZS701','chorus','赞美主！赞美主！<br/>赞美主！<br/>阿利路亚，阿利路亚，<br/>赞美主！赞美主！<br/>我永活在召会！<br/>（四至七节）<br/>','',58703,12268);
INSERT INTO stanza VALUES('ZS701','5','从前的我乖僻孤独，<br/>活在自己里面；<br/>但如今我与众圣徒，<br/>在主里同被建。<br/>','',58704,12269);
INSERT INTO stanza VALUES('ZS701','6','我被吸引到召会中，<br/>享受甜蜜交通；<br/>并学习在任何场合，<br/>从别人接受主。<br/>','',58705,12270);
INSERT INTO stanza VALUES('ZS701','7','流荡止息，安家召会，<br/>活在祂心意里；<br/>这是我的喜乐秘诀：<br/>享受神的安息。<br/>','',58706,12271);
INSERT INTO stanza VALUES('ZS702','1','（一）摸索<br/>为何你常是没有喜乐，<br/>天天都平淡缺少音乐？<br/>是否你自己把你捆绑，<br/>生活的圈子窄小无望，<br/>所以才这样惆怅？<br/>（哎阿！）<br/>抑或你正是另有追求，<br/>忘记了你的宝贵的主？<br/>所以你才是经常失望，<br/>但却又不肯归回群羊，<br/>才感到如此迷惘？<br/>（哎阿！）<br/>','',58707,12272);
INSERT INTO stanza VALUES('ZS702','chorus','我心所爱，我心所爱，<br/>快快前来！<br/>享受我们，享受我们，<br/>就是现在！<br/>神的需要，你的需要，<br/>都得着满足。<br/>当你投流中，<br/>只为着召会，<br/>必得着荣耀冠冕。<br/>阿利路亚！<br/>','',58708,12273);
INSERT INTO stanza VALUES('ZS702','2','你常对别人诉说愁苦：<br/>为何我常是走投无路，<br/>总不能冲破愁云惨雾，<br/>奋斗又挣扎却不明朗。<br/>哦！何日方能刚强！<br/>（哎阿！）<br/>是因你不知何为自由，<br/>常常把自己陷在泥淖！<br/>是因你不知宝贵生命，<br/>是因你不肯把祂释放！<br/>所以才凄凄凉凉！<br/>（哎阿！）<br/>','',58709,12274);
INSERT INTO stanza VALUES('ZS702','chorus','（二）追寻<br/>我心所爱，我心所爱，<br/>快快前来！<br/>享受我们，享受我们，<br/>就是现在！<br/>神的需要，你的需要，<br/>都得着满足。<br/>当你投流中，<br/>只为着召会，<br/>必得着荣耀冠冕。<br/>阿利路亚！<br/>','',58710,12275);
INSERT INTO stanza VALUES('ZS702','1','你常在那里寻寻觅觅，<br/>也曾觉主是那样甜蜜，<br/>你却不让主占你心房，<br/>总要留一点为你着想。<br/>所以才时变刻翻！<br/>（哎阿！）<br/>你也在主前立定心志，<br/>除了祂之外别无所知，<br/>但当祂向你有所要求，<br/>你就觉为难畏缩退后，<br/>担不起损失剥夺！<br/>（哎阿！）<br/>','',58711,12276);
INSERT INTO stanza VALUES('ZS702','2','你也是常常感到困惑，<br/>为何你自己这样软弱，<br/>是因你羡慕<br/>得些『权能，』<br/>还是你只望<br/>为祂『工作，』<br/>失去了单纯生活！<br/>（哎阿！）<br/>你或有『得胜』<br/>你就骄傲，<br/>不然就满了灰心叹息，<br/>只因你仍要自己属灵，<br/>忘却了<br/>来向『他们』投依，<br/>失去了供应能力！<br/>（哎阿！）<br/>','',58712,12277);
INSERT INTO stanza VALUES('ZS702','1','（三）生活<br/>你也曾多次向主说过，<br/>不来是不安，来又不妥，<br/>盼望在会中得点甚么，<br/>补满自己的贫穷软弱，<br/>却不知如何得着！<br/>（哎阿！）<br/>也许你却是逢会必到，<br/>也跟着别人<br/>『阿们』喊叫，<br/>但你确又是虚空无聊，<br/>只因你是在<br/>履行『宗教，』<br/>不知道生命逍遥！<br/>（哎阿！）<br/>','',58713,12278);
INSERT INTO stanza VALUES('ZS702','2','当你见别人投身流中，<br/>你也曾多次隔岸观望，<br/>见主在祝福你就拍掌，<br/>见别人失败你也失望，<br/>但你却总是这样！<br/>（哎阿！）<br/>你私下盼望多些责任，<br/>好叫你名声远播四方，<br/>常给人『帮助』<br/>得着『赞赏，』<br/>常流出『关切』<br/>得着『颂扬，』<br/>你的主却不这样！<br/>（哎阿！）<br/>','',58714,12279);
INSERT INTO stanza VALUES('ZS703','1','前我曾是个孤单的人，<br/>追求自己的属灵，<br/>盼望我能在主前侍立，<br/>使祂能欢喜满意。<br/>多年来虽屡觉得甜美，<br/>却又是时常凄凉，<br/>我是已有够多的失望，<br/>知道不能再这样。<br/>','',58715,12280);
INSERT INTO stanza VALUES('ZS703','2','在主里我寻见了你们，<br/>如寻见所爱的主，<br/>我就知我已得着归宿，<br/>在家中享受丰富。<br/>借你们我能得着力量，<br/>不知不觉的向前，<br/>我何愿与你们永结联，<br/>只望为你们而活。<br/>','',58716,12281);
INSERT INTO stanza VALUES('ZS704','1','你如今活在召会里，<br/>岂不令你欢天喜地！?<br/>赞美主，实在是荣耀，<br/>我们终于找着目标。<br/>','',58717,12282);
INSERT INTO stanza VALUES('ZS704','2','从此不再寻寻觅觅，<br/>我们已经回到家里。<br/>弟兄们和睦的同居，<br/>真正天伦之乐无比！<br/>','',58718,12283);
INSERT INTO stanza VALUES('ZS704','3','这是神拣选的地方，<br/>神荣脸得以常瞻仰；<br/>神的名是摆在这里，<br/>你住些时，就不一样。<br/>','',58719,12284);
INSERT INTO stanza VALUES('ZS704','4','阿利路亚，别无拣选─<br/>从听见祂声音那天。<br/>自深处我们说：『阿们，<br/>我们乐意，投身其间。』<br/>','',58720,12285);
INSERT INTO stanza VALUES('ZS705','1','恩主是我所至爱，<br/>我心我命所归。<br/>是我时刻扶持，<br/>也是我体恤安慰。<br/>前舍命成救赎，<br/>今是生命泉源，<br/>成为我安息，<br/>是我的喜乐。<br/>恩主阿！我爱你，<br/>我爱你，你，到永远！<br/>','',58721,12286);
INSERT INTO stanza VALUES('ZS705','2','召会是我甜美家，<br/>满足我的心怀。<br/>是主心爱配偶，<br/>也是我终生所投。<br/>在这家中有爱，<br/>扶持供应无限，<br/>使我有力量，<br/>引领我前往。<br/>召会阿！我爱你，<br/>我爱你，你，甜美家！<br/>','',58722,12287);
INSERT INTO stanza VALUES('ZS706','1','快乐日，我们回家来，<br/>同饱尝父神慈爱；<br/>地方召会中过生活，<br/>基督丰富我们全享。<br/>','',58723,12288);
INSERT INTO stanza VALUES('ZS706','chorus','为着主今日恢复，<br/>操练灵，立场站住，<br/>合一中同配搭事奉，<br/>基督身体在此显出。<br/>','',58724,12289);
INSERT INTO stanza VALUES('ZS706','2','神七灵，乃是焚烧灵，<br/>召会中把我炼净；<br/>光照耀，倒空并充盈，<br/>使我变化成主荣形。<br/>','',58725,12290);
INSERT INTO stanza VALUES('ZS707','1','何喜乐，神的众儿女，<br/>在家里主面前同欢聚，<br/>同述说蒙主奇恩的故事，<br/>灵里高昂<br/>引声颂扬永不止。<br/>','',58726,12291);
INSERT INTO stanza VALUES('ZS708','1','我们同声歌唱欢呼，<br/>我们与王一同居住！<br/>异象清楚，向主绝对，<br/>我们是祂拣选的召会。<br/>','',58727,12292);
INSERT INTO stanza VALUES('ZS708','2','我们听见大雷声响，<br/>众圣站住地方立场，<br/>阿利路亚！我们欢呼，<br/>聚会中赞美主不止住。<br/>','',58728,12293);
INSERT INTO stanza VALUES('ZS708','3','我们不再流荡不定，<br/>摸索寻找天上的星；<br/>阿利路亚，明光照亮，<br/>我们今已在家，已在家！<br/>','',58729,12294);
INSERT INTO stanza VALUES('ZS709','1','安家在召会，<br/>不再无家可归，<br/>我心终日喜乐又满足；<br/>基督作生命，<br/>一切挣扎全停，<br/>阿利路亚！我在家居住！<br/>我有家─召会，<br/>我今不再感无家可归；<br/>我一生一世<br/>高声颂赞不止，<br/>阿利路亚！基督与召会！<br/>','',58730,12295);
INSERT INTO stanza VALUES('ZS709','2','神已得安息，<br/>这是祂的住处，<br/>祂心终日喜乐又满足；<br/>祂家已恢复，<br/>撒但别想来侵，<br/>在此祂的荣耀全显出。<br/>神有家─召会，<br/>神今不再感无家可归；<br/>我一生一世<br/>高声颂赞不止，<br/>阿利路亚！基督与召会！<br/>','',58731,12296);
INSERT INTO stanza VALUES('ZS710','1','人人要出所多玛，<br/>人人要出所多玛，<br/>人人要出所多玛，<br/>主必快来！<br/>世界都快要过去了，<br/>你还在留恋甚么？<br/>我们被提日子近了，<br/>你要被提或留下？<br/>','',58732,12297);
INSERT INTO stanza VALUES('ZS710','2','在主被钉死地方，<br/>在主被钉死地方，<br/>在主被钉死地方，<br/>你要死透！<br/>我们已经与主同钉，<br/>世界对我是空白；<br/>我们如今活在地上，<br/>只为迎接祂再来！<br/>','',58733,12298);
INSERT INTO stanza VALUES('ZS710','3','人人都要进方舟，<br/>人人都要进方舟，<br/>人人都要进方舟，<br/>同过召会！<br/>方舟里头，我们享受<br/>主作我们的一切；<br/>多多经历，多多分享，<br/>不知枯燥不觉累！<br/>','',58734,12299);
INSERT INTO stanza VALUES('ZS711','1','耶稣是那奇妙牧人，<br/>带领我们出羊圈。<br/>肥沃草地，广阔无边，<br/>我们处身在其间！<br/>','',58735,12300);
INSERT INTO stanza VALUES('ZS711','chorus','哦，召会生活，<br/>无比荣耀又丰富！<br/>在此我们合一相处，<br/>享受生命的祝福。<br/>','',58736,12301);
INSERT INTO stanza VALUES('ZS711','2','身处异地，饥寒交迫，<br/>是祂来把我找着；<br/>祂带我们进入美地，<br/>灵里舒适真无比！<br/>','',58737,12302);
INSERT INTO stanza VALUES('ZS711','3','耶稣自己乃是草场，<br/>祂是我们的食物；<br/>我们都是属祂的羊，<br/>每次聚集真饱足。<br/>','',58738,12303);
INSERT INTO stanza VALUES('ZS711','4','我们今正住于高山，<br/>新鲜甘露何舒适！<br/>所有干渴一去不回，<br/>祂是常新的活水。<br/>','',58739,12304);
INSERT INTO stanza VALUES('ZS711','5','基督是我们的享受，<br/>可以高枕而无忧；<br/>我们在此平安稳妥，<br/>蒙祂同在的保守。<br/>','',58740,12305);
INSERT INTO stanza VALUES('ZS712','1','召会生活，辉煌之至！<br/>这是神美丽园子，<br/>在此经历基督成长，<br/>赞美主！<br/>神在基督里的丰富，<br/>不断的供应我们，<br/>祂是何等新鲜、便利、<br/>又亲近！<br/>','',58741,12306);
INSERT INTO stanza VALUES('ZS712','chorus','我真欢喜！在神的园里，<br/>这园实在可爱又美丽！<br/>天天饱尝生命美果，<br/>畅饮生命的乐河；<br/>世上没有比这<br/>更好的生活！<br/>','',58742,12307);
INSERT INTO stanza VALUES('ZS712','2','召会不是学校、工厂，<br/>召会不是礼拜堂，<br/>乃是生命园子，<br/>让基督成长；<br/>主把我们栽于其中，<br/>时时浇灌又培养，<br/>我们是神亲手<br/>经营的农场！<br/>','',58743,12308);
INSERT INTO stanza VALUES('ZS712','3','在这『召会生活』园子，<br/>我们有棵生命树，<br/>结满生命美果，<br/>为作人食物；<br/>放下成见，不搞心思，<br/>只要简单吃这树，<br/>时时刻刻享受<br/>甜美的基督。<br/>','',58744,12309);
INSERT INTO stanza VALUES('ZS712','4','看哪！还有生命乐河，<br/>不断流自神宝座，<br/>消除人间一切<br/>疲倦与干渴。<br/>阿利路亚，在这园中，<br/>基督流入我里头，<br/>不断滋润、浇灌，<br/>直到我成熟。<br/>','',58745,12310);
INSERT INTO stanza VALUES('ZS712','5','主已把我带进这里，<br/>享受基督的自己，<br/>真是称心如意，<br/>又满心感激！<br/>我们常在灵里吃喝，<br/>心里大大的喜乐，<br/>且在乐园之中<br/>月月结新果。<br/>','',58746,12311);
INSERT INTO stanza VALUES('ZS713','1','阿！可爱的召会生活！<br/>我们在这里，<br/>天天有吃喝；<br/>何必挨饿？何必干渴？<br/>让我们一同来享受！<br/>','',58747,12312);
INSERT INTO stanza VALUES('ZS713','chorus','快快进入方舟，<br/>同过召会生活，<br/>天天吃喝享受，<br/>日子已经不多！<br/>快快进入方舟，<br/>同过召会生活，<br/>迎接新郎回来，<br/>最是值得！<br/>','',58748,12313);
INSERT INTO stanza VALUES('ZS713','2','阿！可爱的召会生活！<br/>为这个奉献，<br/>实在是值得！<br/>我们爱基督与召会，<br/>除此以外，别无所求。<br/>','',58749,12314);
INSERT INTO stanza VALUES('ZS713','3','阿！可爱的召会生活！<br/>在神的家中，<br/>个个都富有！<br/>可以在会中尽功用，<br/>可以到处带人得救！<br/>','',58750,12315);
INSERT INTO stanza VALUES('ZS713','4','阿！可爱的召会生活！<br/>我们有美地，<br/>无比的肥沃！<br/>殷勤耕种，时刻浇灌，<br/>我们都是全时间的！<br/>','',58751,12316);
INSERT INTO stanza VALUES('ZS713','5','阿！可爱的召会生活！<br/>建造在一起，<br/>我们是一个！<br/>哈！老撒但，该你蒙羞，<br/>新妇到底被主得着！<br/>','',58752,12317);
INSERT INTO stanza VALUES('ZS714','1','有些宗教人士会说：<br/>『耶稣不可吃；<br/>我们只要明白道理，<br/>努力作好事。』<br/>亲爱弟兄，请听主说：<br/>『我是生命粮。』<br/>吃主的人凭祂活着，<br/>天天喜洋洋。<br/>','',58753,12318);
INSERT INTO stanza VALUES('ZS714','chorus','我爱召会生活，<br/>吃主，喝主，并呼吸主；<br/>我爱召会生活，<br/>接受神的话。<br/>我爱听见呼喊：<br/>哦主，阿们，阿利路亚！<br/>我爱召会生活，<br/>与主同坐席。<br/>','',58754,12319);
INSERT INTO stanza VALUES('ZS714','2','我们时常呼喊主名，<br/>享用祂丰富，<br/>祂就充满我们<br/>全人里面每一部。<br/>天天聚会，交通，歌颂，<br/>与圣徒一起，<br/>如此生活直到主来，<br/>活着同被提。<br/>','',58755,12320);
INSERT INTO stanza VALUES('ZS714','3','末后日子，<br/>社会生活处处是邪恶，<br/>使你觉得<br/>好像跌落危险的漩涡；<br/>速速投入召会生活，<br/>倾听圣灵说：『这是今日<br/>地上惟一有福的生活。』<br/>','',58756,12321);
INSERT INTO stanza VALUES('ZS715','1','清早起来就先把主吃饱，<br/>大家一同来过召会生活；<br/>守晨更，天天来，<br/>多阿们，灵就开，<br/>整天享受主同在。<br/>阿利路亚，主同在！<br/>阿利路亚，主同在！<br/>无论何处唱乐歌，<br/>过召会生活。<br/>','',58757,12322);
INSERT INTO stanza VALUES('ZS715','2','不讲蒙恩先后，<br/>不谈新旧，<br/>大家一同来见证主基督；<br/>同是身上肢体，<br/>互相联结供应，<br/>爱里扶持作肢体。<br/>阿利路亚，作肢体！<br/>阿利路亚，作肢体！<br/>显出功用不畏缩，<br/>过召会生活！<br/>','',58758,12323);
INSERT INTO stanza VALUES('ZS715','3','基督是我的，<br/>也是你们的，<br/>大家一同来分享祂自己，<br/>在召会，在家里，<br/>同享祂的福气，<br/>阿利路亚，乐无比！<br/>阿利路亚，乐无比！<br/>阿利路亚，乐无比！<br/>身体丰富我全享，<br/>过召会生活！<br/>','',58759,12324);
INSERT INTO stanza VALUES('ZS715','4','称耶稣是主，<br/>喊阿利路亚，<br/>大家一同来展览主基督，<br/>你唱诗，我赞美，<br/>他见证，同阿们，<br/>聚起会来真有味！<br/>阿利路亚，真有味！<br/>阿利路亚，真有味！<br/>新鲜丰富又活泼，<br/>过召会生活！<br/>','',58760,12325);
INSERT INTO stanza VALUES('ZS716','1','生命歌声在召会中，<br/>处处可以听闻，<br/>基督是我们的喜乐，<br/>彰显在四方。<br/>巴比伦和世俗的事<br/>与我无关无分，<br/>我们已经回家，<br/>在美地上。<br/>','',58761,12326);
INSERT INTO stanza VALUES('ZS716','chorus','在灵中同过召会，<br/>在召会地方立场；<br/>弟兄们同过召会，<br/>我们已经回家；<br/>跟随众召会同过召会，<br/>直到全地都同唱，<br/>哦阿利路亚！基督美地！<br/>','',58762,12327);
INSERT INTO stanza VALUES('ZS716','2','一切背景，所有道理，<br/>已经远远抛弃；<br/>世俗人情，罪中之乐，<br/>更是全绝离。<br/>耶稣基督大爱<br/>正在我们心中洋溢，<br/>我们决不离开基督美地。<br/>','',58763,12328);
INSERT INTO stanza VALUES('ZS716','3','『我要把我的召会<br/>建造在这磐石上！』<br/>主既如此豫言，<br/>祂也必如此成就。<br/>将各肢体按祂意思，<br/>配搭在身体上，<br/>建造一起，<br/>在基督美地上！<br/>','',58764,12329);
INSERT INTO stanza VALUES('ZS716','4','现今主正全地<br/>快速开展祂的恢复，<br/>所有地方召会，<br/>同心向着主求祷，<br/>速速降临结束时代，<br/>迎娶祂的新妇。<br/>阿利路亚欢呼：<br/>基督美地！<br/>','',58765,12330);
INSERT INTO stanza VALUES('ZS716','chorus','在灵中同过召会，<br/>在召会地方立场；<br/>弟兄们同过召会，<br/>我们已经回家；<br/>跟随众召会同过召会，<br/>直到全地都同唱，<br/>哦阿利路亚！基督美地！<br/>注：『过召会』系译自英诗新辞『Churching。』<br/>','',58766,12331);
INSERT INTO stanza VALUES('ZS717','1','自从『过召会』，<br/>生活何美丽，豫尝那日；<br/>新耶路撒冷，<br/>新耶路撒冷，<br/>安息的满足。<br/>','',58767,12332);
INSERT INTO stanza VALUES('ZS717','2','今日的召会就是那美地<br/>─流奶与蜜。<br/>尽情的享受，<br/>尽情的享受，<br/>丰盛的生命。<br/>','',58768,12333);
INSERT INTO stanza VALUES('ZS717','3','建造的召会就是神居所，<br/>让祂安息；为祂掌王权，<br/>为祂掌王权，<br/>完成神旨意。<br/>','',58769,12334);
INSERT INTO stanza VALUES('ZS718','1','我们一心巴望着<br/>同去过节；<br/>有人说『去』，<br/>我们就兴高采烈！<br/>悲哀禁食的日子<br/>已经过去，<br/>现在我们在一起，<br/>是为着享受欢喜。<br/>哦！阿利路亚，<br/>一同过节，<br/>哦！这是我们的聚会！<br/>凡尝到的人都能述说，<br/>这甘甜无比的滋味！<br/>难怪一心巴望着<br/>同去过节；<br/>有人说『去』，<br/>我们就兴高采烈！<br/>悲哀禁食的日子<br/>已经过去，<br/>现在我们在一起，<br/>是为着享受欢喜。<br/>','',58770,12335);
INSERT INTO stanza VALUES('ZS718','2','我们过节，<br/>要来到耶路撒冷；<br/>耶路撒冷<br/>是我们合一见证！<br/>我们的脚<br/>一站在你的门内，<br/>我们就情不自禁，<br/>赞美主荣耀的名！<br/>看！耶路撒冷联络整齐，<br/>看！真正合一多美丽！<br/>凡爱你的人必然兴旺，<br/>因神的荣耀在这里！<br/>难怪过节<br/>要来到耶路撒冷；<br/>耶路撒冷<br/>是我们合一见证！<br/>我们的脚<br/>一站在你的门内，<br/>我们就情不自禁，<br/>赞美主荣耀的名！<br/>','',58771,12336);
INSERT INTO stanza VALUES('ZS718','3','我们前来朝见神，<br/>不能空手；<br/>牛、羊、鸽子或斑鸠，<br/>大小皆可，<br/>无酵薄饼、新穗子、<br/>细面调油…<br/>当献上你的礼物，<br/>神与人才得饱足。<br/>看！琳瑯满目，<br/>尽是基督；<br/>看！美不胜收，好丰富！<br/>若我们想要得着饱足，<br/>须首先让神得饱足。<br/>难怪前来朝见神，<br/>不能空手；<br/>牛、羊、鸽子或斑鸠，<br/>大小皆可，<br/>无酵薄饼、新穗子、<br/>细面调油…<br/>当献上你的礼物，<br/>神与人才得饱足。<br/>','',58772,12337);
INSERT INTO stanza VALUES('ZS719','1','我们与偶像，<br/>不再有关涉，<br/>基督是我们惟一的享受！<br/>我们不再受世界的迷惑，<br/>召会是我们实际的生活。<br/>','',58773,12338);
INSERT INTO stanza VALUES('ZS719','chorus','哦，对付以后，<br/>何等的享受！<br/>高山上滴酒、滴酒、<br/>滴酒、滴甜酒！<br/>哦！当赞美主，<br/>何等的丰富，<br/>小山上流奶、<br/>流奶、流奶子！<br/>','',58774,12339);
INSERT INTO stanza VALUES('ZS719','2','不再有形式，<br/>不再有老套，<br/>新酒灌满了，<br/>自然有高潮！<br/>老年作异梦，<br/>少年见异象，<br/>有何比聚集，<br/>更令人向往？<br/>','',58775,12340);
INSERT INTO stanza VALUES('ZS719','3','活在灵里面，<br/>恢复真是快，<br/>多年被吃去，<br/>统统补回来！<br/>人人都活跃，<br/>来供应基督─<br/>我们的聚集，<br/>越过越丰富。<br/>','',58776,12341);
INSERT INTO stanza VALUES('ZS720','1','基督是活神，<br/>说：阿利路亚！<br/>祂活我里面，<br/>说：阿利路亚！<br/>祂是我永分，<br/>丰富又美佳；<br/>只要喊『哦，主』<br/>就尝祂。<br/>','',58777,12342);
INSERT INTO stanza VALUES('ZS720','2','我们同聚集<br/>是好得无比；<br/>因为在灵里<br/>一同作肢体，<br/>成为主身体<br/>彰显祂自己；<br/>基督是我们的实际。<br/>','',58778,12343);
INSERT INTO stanza VALUES('ZS720','3','在地方召会<br/>我们被充满，<br/>为使主丰富<br/>向全地扩展！<br/>一地又一地，<br/>一直到地极，<br/>把活的基督传出去！<br/>','',58779,12344);
INSERT INTO stanza VALUES('ZS721','1','在主的召会中，<br/>有爱为着你；<br/>爱是纯洁温柔，<br/>深挚又真切。<br/>何必常感孤单，<br/>叹息无友伴？<br/>在主召会之中<br/>有丰富供应！<br/>','',58780,12345);
INSERT INTO stanza VALUES('ZS721','2','在主的召会中，<br/>有生命为你；<br/>温热如同太阳，<br/>新鲜像甘露。<br/>何必感到惧怕，<br/>烦恼又焦虑？<br/>召会必定看顾，<br/>主所赎的人！<br/>','',58781,12346);
INSERT INTO stanza VALUES('ZS721','3','在主的召会中，<br/>有事工为你；<br/>甚至天使也会<br/>乐意来有分。<br/>何必闲站等候，<br/>要作更大事？<br/>召会正在需要<br/>你来尽功用！<br/>','',58782,12347);
INSERT INTO stanza VALUES('ZS721','4','在主的召会中，<br/>有住处为你；<br/>荣耀、光明、喜乐、<br/>公义又安息。<br/>何必像浪荡者；<br/>疲倦而流落？<br/>在主召会之中<br/>有你的住处。<br/>','',58783,12348);
INSERT INTO stanza VALUES('ZS722','1','何等的享受，<br/>我活在祂家中，<br/>召会生活何等甘甜。<br/>呼吸祂的圣名，<br/>吃喝祂话语，<br/>为着祂的荣耀恢复。<br/>行走，我们今行走<br/>在生命的光中，<br/>生活，我们是生活在<br/>神的召会中。<br/>祂爱保守我，<br/>祂光照亮我，<br/>肢体相爱一同被建造。<br/>','',58784,12349);
INSERT INTO stanza VALUES('ZS723','1','我们今日的聚会<br/>乃是又新又活，<br/>灵里聚集并敬拜，<br/>完全自由超脱。<br/>我们享受基督<br/>作一切的实际，<br/>呼喊主名时，<br/>仪文『影儿』全都撇弃。<br/>','',58785,12350);
INSERT INTO stanza VALUES('ZS723','chorus','又新又活的聚集，<br/>又新又活样式，<br/>学校、公园、或海边，<br/>那里都不在乎！<br/>我们弃绝一切的规条、<br/>死宗教，阿利路亚！<br/>主的灵冲破一切限制！<br/>','',58786,12351);
INSERT INTO stanza VALUES('ZS723','2','不要任何死宗教，<br/>不要任何形式，<br/>不要任何的规条，<br/>不要人的意思，<br/>不要那杀死人的字句<br/>与道理，阿利路亚！<br/>在灵里我们自由无比！<br/>','',58787,12352);
INSERT INTO stanza VALUES('ZS723','3','又新又活的聚集，<br/>一切老旧全除；<br/>唱诗祷读的时候<br/>我们分享基督。<br/>老而又老的光景<br/>已无处可找，阿利路亚！<br/>主今日乃是在作新事！<br/>','',58788,12353);
INSERT INTO stanza VALUES('ZS724','1','我们是一群有雄心的人，<br/>在聚会中我们是祝福。<br/>我们不再作宗教的礼拜，<br/>乃要让功用活泼显出。<br/>阿利路亚！<br/>擘饼、祷告、交通，<br/>所有聚会我们都有分！<br/>不容任何聚会<br/>发死、空洞；<br/>搅活、充实是我们心志。<br/>','',58789,12354);
INSERT INTO stanza VALUES('ZS724','2','我们是一群有雄心的人，<br/>出口者的灵在我们里；<br/>前不应用，<br/>将牠束缚关闭，<br/>今我们愿意释放这灵。<br/>阿利路亚！<br/>众人释放这灵，<br/>所有聚会再也不沉寂；<br/>我们要在会中为主说话，<br/>使众圣徒都得着建造。<br/>','',58790,12355);
INSERT INTO stanza VALUES('ZS725','1','听主吹笛，就欢欣鼓舞，<br/>见主举哀，就捶胸哀哭；<br/>我们是小孩子，<br/>不受老套拘束，<br/>主有带领就快快顺服！<br/>聪明的人，考虑得太多，<br/>圣灵流到，还慢慢研究；<br/>难怪主向他们就封住，<br/>向婴孩祂就乐意显出来。<br/>','',58791,12356);
INSERT INTO stanza VALUES('ZS725','2','负祂的轭，一步一步走，<br/>学祂样式，跟随祂举止；<br/>我们是小牛犊，<br/>自己不会作主，<br/>每一步都听凭祂指示！<br/>祂要向东，我们就向东，<br/>祂要向西，我们就向西；<br/>又容易、又轻省、<br/>又喜乐，<br/>因为轭其实是由祂负着。<br/>','',58792,12357);
INSERT INTO stanza VALUES('ZS726','1','我们同声阿们，<br/>召会实际是灵；<br/>不是仪文、教训、办法，<br/>一切都在乎灵。<br/>这灵浸透我们，<br/>何等轻省便利！<br/>纯洁自己，脱旧更新，<br/>成为神要的人。<br/>','',58793,12358);
INSERT INTO stanza VALUES('ZS726','2','新酒装新皮袋，<br/>一切老旧消除；<br/>冲破自己所有束缚，<br/>圣灵就有出路！<br/>弟兄姊妹，释放！<br/>召会就必刚强！<br/>我们的灵如火挑旺，<br/>召会常青发旺。<br/>','',58794,12359);
INSERT INTO stanza VALUES('ZS727','1','基督已经将我释放，<br/>我也释放灵中基督；<br/>借祂生命我脱罪律，<br/>借我见证祂得显彰。<br/>','',58795,12360);
INSERT INTO stanza VALUES('ZS727','chorus','阿利路亚！荣耀释放！<br/>神人同工，成祂旨意。<br/>','',58796,12361);
INSERT INTO stanza VALUES('ZS727','2','在基督里我得释放，<br/>脱离今世所有辖制；<br/>前途事业尽都撇弃，<br/>为祂见证活在灵里。<br/>','',58797,12362);
INSERT INTO stanza VALUES('ZS727','3','丰富基督住在灵里，<br/>等候我来把祂经历；<br/>每当释放灵中基督，<br/>能力智慧无不我属。<br/>','',58798,12363);
INSERT INTO stanza VALUES('ZS727','4','哦主！求你救我脱离<br/>所有老旧空洞道理；<br/>天天经营灵中丰富，<br/>时时释放荣耀基督。<br/>','',58799,12364);
INSERT INTO stanza VALUES('ZS727','5','基督借我得以彰显，<br/>祂的荣美为人所见；<br/>每当我把祂来释放，<br/>祂的喜乐满我心房。<br/>','',58800,12365);
INSERT INTO stanza VALUES('ZS727','6','主！我今在你前抛弃，<br/>已往自大<br/>『属灵』、『经历』；<br/>今后不再自是自觉，<br/>运用我灵将你释放。<br/>','',58801,12366);
INSERT INTO stanza VALUES('ZS728','1','阿利路亚！何等奥秘，<br/>神在肉身显现，<br/>荣耀神的一切丰富，<br/>从我完全显出，<br/>从我完全显出。<br/>阿利路亚！完全显出。<br/>','',58802,12367);
INSERT INTO stanza VALUES('ZS728','2','我虽不知是何肢体，<br/>却知神住我里，<br/>是何功用我今不问，<br/>只求让灵自由，<br/>只求让灵自由，<br/>阿利路亚！让灵自由。<br/>','',58803,12368);
INSERT INTO stanza VALUES('ZS728','3','召会『地位』我全不顾，<br/>只顾里面的主。<br/>我若自居把持带领，<br/>不过捆绑聚会；<br/>我愿让神显出。<br/>阿利路亚！让神显出。<br/>','',58804,12369);
INSERT INTO stanza VALUES('ZS728','4','荣耀！荣耀！何等奥秘，<br/>我们都在灵里，<br/>配搭合式，结合坚固，<br/>显出荣耀召会，<br/>显出荣耀召会。<br/>阿利路亚！荣耀召会。<br/>','',58805,12370);
INSERT INTO stanza VALUES('ZS729','1','阿利路亚，自由！<br/>阿利路亚，自由！<br/>我不再受罪的捆绑。<br/>因主耶稣，<br/>将我罪辜钉在十架，<br/>阿利路亚！我自由！<br/>','',58806,12371);
INSERT INTO stanza VALUES('ZS729','2','阿利路亚，自由！<br/>阿利路亚，自由！<br/>我不再随仪文摆布，<br/>脱离宗教，<br/>完全圣别成为新人，<br/>阿利路亚！我自由！<br/>','',58807,12372);
INSERT INTO stanza VALUES('ZS729','3','阿利路亚，自由！<br/>阿利路亚，自由！<br/>祂的生命，变化了我，<br/>天天更新，<br/>直到长成基督身量，<br/>阿利路亚！我自由！<br/>','',58808,12373);
INSERT INTO stanza VALUES('ZS729','4','阿利路亚，自由！<br/>阿利路亚，自由！<br/>我们是为主的见证，<br/>在身体里，<br/>同被模成神的形像。<br/>阿利路亚！全自由！<br/>','',58809,12374);
INSERT INTO stanza VALUES('ZS729','5','阿利路亚，自由！<br/>阿利路亚，自由！<br/>交给召会，配搭一起，<br/>经营建造，<br/>成为神的荣耀身体。<br/>阿利路亚！全自由！<br/>','',58810,12375);
INSERT INTO stanza VALUES('ZS729','6','阿利路亚，自由！<br/>阿利路亚，自由！<br/>我们经历真实建造，<br/>终于寻到─<br/>地方召会，乃是神家。<br/>阿利路亚！全自由！<br/>','',58811,12376);
INSERT INTO stanza VALUES('ZS730','1','大户人家器皿众多，<br/>你是属那一流？<br/>金器、银器、<br/>木器、瓦器，<br/>贵重卑贱都有！<br/>','',58812,12377);
INSERT INTO stanza VALUES('ZS730','chorus','纯洁自己并脱离卑贱，<br/>必作贵重器皿；<br/>成为圣别，合乎主用，<br/>使我显主荣美！<br/>','',58813,12378);
INSERT INTO stanza VALUES('ZS730','2','木器─憋气，<br/>瓦器─泄气，<br/>你看多么难过！<br/>金器─神气，<br/>银器─争气，<br/>你看多么荣耀！<br/>','',58814,12379);
INSERT INTO stanza VALUES('ZS730','3','活在心思，考虑分析，<br/>就成木器、瓦器。<br/>顺从膏油，释放我灵，<br/>就是金器、银器。<br/>','',58815,12380);
INSERT INTO stanza VALUES('ZS731','1','不走宗教仪文错路，<br/>不搞字句道理；<br/>转到灵中才是正路，<br/>快快投进流里！<br/>活在灵里我们合一，<br/>同心而合意。<br/>呼喊：『哦主，阿们，<br/>阿利路亚！』耶稣是主！<br/>','',58816,12381);
INSERT INTO stanza VALUES('ZS732','1','流露、流露、<br/>流露祂的丰富，<br/>让生命丰富<br/>从我里面尽流出；<br/>流露、流露、<br/>流露祂的生命，<br/>让生命丰富<br/>成为众人的供应。<br/>当我知道在我里的丰富，<br/>当我知道这丰富的满足，<br/>我就愿意将牠尽都流出，<br/>好叫众人<br/>都因这流露得饱足。<br/>','',58817,12382);
INSERT INTO stanza VALUES('ZS732','2','释放、释放、<br/>释放祂的生命，<br/>让祂生命的<br/>一切丰富都流出；<br/>能力、智慧<br/>都在这生命里，<br/>无时无刻<br/>不豫备从我里显出。<br/>不需尽力喊叫才能释放，<br/>不需维持宗教里的安静；<br/>祂的一切都在这生命里，<br/>我若自由<br/>祂就能从我身流出。<br/>','',58818,12383);
INSERT INTO stanza VALUES('ZS733','1','我们现今一同前来享受<br/>众圣徒里面的基督。<br/>脱离自己窄小天地，<br/>以为基督仅仅是属我的。<br/>祂的丰富已经住在<br/>我们的他们里。<br/>所以我们一同前来享受<br/>众圣徒里面的基督。<br/>','',58819,12384);
INSERT INTO stanza VALUES('ZS733','chorus','弟兄们哪，快快前来！<br/>尽情享受你的所有；<br/>当我们能让祂自由，<br/>我们就能同得享受。<br/>我的经历是你丰富，<br/>你的经营是我供应；<br/>我们一同彼此享受，<br/>神人在此同得满足。<br/>','',58820,12385);
INSERT INTO stanza VALUES('ZS733','2','我享受你，你享受我，<br/>才知道基督是何等丰富。<br/>我供应你，你供应我，<br/>才得着生命一切的实际。<br/>祂赐我的丰富产业<br/>在我的他们里。<br/>现今我们彼此享受，<br/>就经历生活是何等甜美。<br/>','',58821,12386);
INSERT INTO stanza VALUES('ZS734','1','弟兄们哪！让我问问你，<br/>可否作一个见证，<br/>喂养我灵满足我的心，<br/>使我能向前行。<br/>我的灵里何等饥渴，<br/>要得供应，<br/>若是你们都闭口无言，<br/>我岂能得饱足。<br/>多次我是切切盼望<br/>这时刻来到，<br/>与你们能相聚在一起，<br/>得着供应。<br/>','',58822,12387);
INSERT INTO stanza VALUES('ZS734','2','亲爱弟兄，让我对你说，<br/>我不仅有一见证，<br/>里面丰富我时刻经营，<br/>我也述说不尽。<br/>岂是仅有一个见证，<br/>满足你心？<br/>我们一同释放这丰富，<br/>彼此一同享受。<br/>不是我们比你刚强，<br/>是借祂的灵，<br/>我们就能相聚在一起，<br/>彼此供应。<br/>','',58823,12388);
INSERT INTO stanza VALUES('ZS735','1','当我经历这位可爱、<br/>奇妙、丰富的救主，<br/>当祂的灵充满我灵，<br/>犹如焚烧的烈火，<br/>当祂将祂荣耀旨意<br/>启示照亮我心中，<br/>我就为祂说话。<br/>','',58824,12389);
INSERT INTO stanza VALUES('ZS735','chorus','说话，说话，阿利路亚！<br/>说话，说话，阿利路亚！<br/>说话，说话，阿利路亚！<br/>我们都能说话。<br/>','',58825,12390);
INSERT INTO stanza VALUES('ZS735','2','每逢操练运用我灵，<br/>享受祂一切丰富，<br/>无论会中，或在人前，<br/>或是单独过生活，<br/>我都不禁涌出美辞，<br/>述说祂一切眷顾，<br/>我就为祂说话。<br/>','',58826,12391);
INSERT INTO stanza VALUES('ZS735','3','主，我今愿时时刻刻<br/>经营内在的丰富，<br/>让你生命大能运行<br/>将我里面全点活，<br/>与你交通，祷读你话，<br/>呼喊你名不止住，<br/>我就为你说话。<br/>','',58827,12392);
INSERT INTO stanza VALUES('ZS735','4','主，愿我们的灵<br/>时时活泼自由的流出，<br/>每次会中我们都能<br/>让你随意的运行，<br/>不再作老宗教礼拜，<br/>持守仪文或遗传，<br/>我们都能说话。<br/>','',58828,12393);
INSERT INTO stanza VALUES('ZS736','1','在召会中鉴赏，<br/>你的可爱，<br/>你美丽吸引我们，<br/>一同追随。<br/>哦，阿利路亚！<br/>哦，阿利路亚！<br/>是你吸引我们一同追随。<br/>','',58829,12394);
INSERT INTO stanza VALUES('ZS736','2','在召会中寻到甜美的家，<br/>在安息里<br/>喜乐的享受丰富。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>安息里喜乐的享受丰富。<br/>','',58830,12395);
INSERT INTO stanza VALUES('ZS736','3','在召会中同心来跟随主，<br/>直到祂能因我们<br/>心满意足。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>直到祂因我们心满意足。<br/>','',58831,12396);
INSERT INTO stanza VALUES('ZS736','4','在召会中我们同是肢体，<br/>个个都能活泼的<br/>来尽功用。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>个个都活泼的来尽功用。<br/>','',58832,12397);
INSERT INTO stanza VALUES('ZS736','5','在召会中我们彼此相爱，<br/>个个供应生命<br/>在爱中建造。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>个个供应生命爱中建造。<br/>','',58833,12398);
INSERT INTO stanza VALUES('ZS736','6','在召会中我们天天长大，<br/>直到长成<br/>我主丰满的身量。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>直到长成我主丰满身量。<br/>','',58834,12399);
INSERT INTO stanza VALUES('ZS736','7','我们所有一切都为召会，<br/>直到荣耀的召会<br/>完全显出。<br/>哦阿利路亚！<br/>哦阿利路亚！<br/>直到荣耀召会完全显出。<br/>','',58835,12400);
INSERT INTO stanza VALUES('ZS737','1','万军之耶和华神说，<br/>你们要将当纳供物，<br/>十分之一全送仓库，<br/>使我有粮，以此试我，<br/>是否为你敞开天窗，<br/>倾福于你无处可容。<br/>我必为你斥责蝗虫，<br/>不容牠毁坏你土产，<br/>你们田间的葡萄树，<br/>未熟之先不掉果子；<br/>万国必称你们有福，<br/>你地必成喜乐之地。<br/>','',58836,12401);
INSERT INTO stanza VALUES('ZS738','1','你要给人神必给你，<br/>并且要用十足升斗，<br/>连摇带按，上尖下流，<br/>倒在你怀，倒在你怀。<br/>','',58837,12402);
INSERT INTO stanza VALUES('ZS739','1','真欢喜！我们接待圣徒；<br/>真欢喜！我们接待圣徒。<br/>真欢喜！享受美好交通。<br/>高唱荣耀阿利路亚！<br/>这是何等祝福！<br/>','',58838,12403);
INSERT INTO stanza VALUES('ZS739','2','真欢喜！我们接待圣徒；<br/>真欢喜！借此服事恩主。<br/>真欢喜！召会生活丰富。<br/>高唱荣耀阿利路亚！<br/>神的家得恢复！<br/>','',58839,12404);
INSERT INTO stanza VALUES('ZS740','1','谁是在主这边？<br/>谁要迎接王？<br/>谁要在新样中，<br/>常青而发旺？<br/>谁要脱离宗教，<br/>活在灵里面，<br/>为主断送前途，<br/>站在主这边？<br/>我们在主这边！<br/>切勿变冷淡；<br/>灵里时常火热，<br/>在灵里壮胆！<br/>','',58840,12405);
INSERT INTO stanza VALUES('ZS741','1','为着祂！为着祂！<br/>为着祂！为着祂！<br/>为着祂召会恢复！<br/>让我们！让我们！<br/>让我们！<br/>让我们齐心努力的<br/>争战在一起！<br/>祂既是有一需要，<br/>你我何能不顾，<br/>祂既是有一呼召，<br/>你我何能再踌躇。<br/>','',58841,12406);
INSERT INTO stanza VALUES('ZS741','2','为着祂！为着祂！<br/>为着祂！为着祂！<br/>为着祂荣耀见证！<br/>让我们！让我们！<br/>让我们！<br/>让我们同心合意的<br/>建造在一起！<br/>我们看见这需要，<br/>我们都在这里，<br/>我们一同在经营，<br/>直到祂全心满意。<br/>','',58842,12407);
INSERT INTO stanza VALUES('ZS742','1','今日的基督教，<br/>死沉，分裂，无望，<br/>牠的一切光景，<br/>不过证实指明：<br/>只有基督自己，<br/>显在真实合一，<br/>能使我们生活充实<br/>而有意义。<br/>','',58843,12408);
INSERT INTO stanza VALUES('ZS742','2','我们清楚看见：<br/>思想，情感，意志，<br/>一切从魂东西，<br/>不能事奉基督。<br/>我们被神创造，<br/>为作神的器皿，<br/>不断灵被充满，<br/>今活着是基督。<br/>','',58844,12409);
INSERT INTO stanza VALUES('ZS742','3','主，我们在老旧宗教里<br/>已够久，<br/>生活好像『属灵』，<br/>起初爱心却失，<br/>但主仍许悔改，<br/>活在生命里面，<br/>成为『疯狂爱人』，<br/>只为着你召会。<br/>','',58845,12410);
INSERT INTO stanza VALUES('ZS742','4','为着主的恢复，<br/>我们须被分别，<br/>脱离世界迷惑，<br/>弃绝今生骄傲；<br/>我们须为基督，<br/>作透亮的器皿，<br/>使全地上的人，<br/>都看见神荣耀！<br/>','',58846,12411);
INSERT INTO stanza VALUES('ZS742','5','巴比伦已倾倒，<br/>这是无可置疑，<br/>快快从她出来，<br/>弟兄们，留心听！<br/>守住地方立场，<br/>为着基督站住；<br/>我们绑在一起，<br/>为着祂的见证。<br/>','',58847,12412);
INSERT INTO stanza VALUES('ZS742','6','在混乱的今日，<br/>层云依旧密布，<br/>哦主！求赐晴天，<br/>带进你的国度；<br/>耶稣，惟一太阳；<br/>召会，惟一月亮，<br/>哦！新耶路撒冷，<br/>今显出她荣耀。<br/>','',58848,12413);
INSERT INTO stanza VALUES('ZS743','1','绝对分别出来，<br/>活在召会中！<br/>不惜任何代价，<br/>经历祂丰富；<br/>割断所有岸索，<br/>投进她流中，<br/>满有生命供应，<br/>成为她祝福。<br/>','',58849,12414);
INSERT INTO stanza VALUES('ZS743','chorus','绝对分别出来，<br/>归于主召会，<br/>答应主的呼召，<br/>开展主国度。<br/>','',58850,12415);
INSERT INTO stanza VALUES('ZS743','2','绝对分别出来，<br/>活在召会中！<br/>治死还要治死，<br/>直到己去净！<br/>直到器皿倒空，<br/>祂脚前破碎，<br/>直到灵里充满<br/>基督的生命。<br/>','',58851,12416);
INSERT INTO stanza VALUES('ZS743','3','绝对分别出来，<br/>归于神旨意，<br/>走主所走道路，<br/>力上复加力。<br/>满了荣耀喜乐，<br/>不断向前行，<br/>同在主引导中，<br/>见证祂行动。<br/>','',58852,12417);
INSERT INTO stanza VALUES('ZS743','4','绝对分别出来，<br/>一直到永世；<br/>不再是我心意，<br/>全是主意旨；<br/>我的计划愿望，<br/>为她全灭没，<br/>在世一无所有，<br/>万有实属我。<br/>','',58853,12418);
INSERT INTO stanza VALUES('ZS743','5','绝对分别出来，<br/>活在召会中！<br/>灵里何等安息，<br/>因见主心意。<br/>天天经营基督，<br/>呼喊主圣名，<br/>时刻灵里火热，<br/>彰显这新人。<br/>','',58854,12419);
INSERT INTO stanza VALUES('ZS743','6','我灵满了基督，<br/>过召会生活，<br/>在她我蒙祝福，<br/>在她我长成！<br/>里面所得异象，<br/>越过越明亮，<br/>活着是为召会，<br/>赤忠迎主归！<br/>','',58855,12420);
INSERT INTO stanza VALUES('ZS744','1','我只要神旨意借我成就，<br/>这是我惟一心志；<br/>除此外我确是一无所知，<br/>只愿祂心满意足。<br/>让事业前途的光明火花<br/>在我身都成损失，<br/>我的生活每点每滴，<br/>完完全全都是为着主。<br/>','',58856,12421);
INSERT INTO stanza VALUES('ZS744','2','让你们去努力建造城池，<br/>叫你们生活安逸；<br/>让你们去尽情吹箫弹琴，<br/>去享受人间情趣。<br/>让你们去打造铜铁利器，<br/>为自己创造事业；<br/>我是一心为神旨意，<br/>绝不向世界屈就妥协。<br/>','',58857,12422);
INSERT INTO stanza VALUES('ZS744','3','我今见复活的荣耀基督，<br/>借我身得以显出；<br/>我今见祂那升天的大能，<br/>在我里发动运行；<br/>我今见宝座的权能超越，<br/>显我身把我提挈；<br/>我已看见祂是一切，<br/>也就是我生命的一切。<br/>','',58858,12423);
INSERT INTO stanza VALUES('ZS745','1','我若仅为个人『属灵』，<br/>我就不屑再追求；<br/>所有我的属灵经历，<br/>都该为召会建造。<br/>','',58859,12424);
INSERT INTO stanza VALUES('ZS745','chorus','一切为召会，<br/>一切为召会，<br/>我的一切所有所是，<br/>全都为召会。<br/>','',58860,12425);
INSERT INTO stanza VALUES('ZS745','2','我若专求<br/>『亮光』『启示』，<br/>求主就向我掩面；<br/>愿我从你每一认识，<br/>都是为召会建造。<br/>','',58861,12426);
INSERT INTO stanza VALUES('ZS745','3','我若夸耀『圣灵恩赐』，<br/>求主收去你印证；<br/>愿我的灵天天满溢，<br/>好叫召会得建造。<br/>','',58862,12427);
INSERT INTO stanza VALUES('ZS745','4','我若只求『工作果效』，<br/>就愿主亲手拆毁；<br/>愿我所有劳苦工作，<br/>全都为召会建造。<br/>','',58863,12428);
INSERT INTO stanza VALUES('ZS745','5','我若追求召会『地位』，<br/>求主使我感羞耻；<br/>求主时刻光照显明，<br/>单纯为召会建造。<br/>','',58864,12429);
INSERT INTO stanza VALUES('ZS746','1','主，我今将自己<br/>交在你恩手中，<br/>我只望能为着召会花费，<br/>虽不知我前途<br/>有何患难或痛苦，<br/>若是为着你召会，<br/>何来懊悔！<br/>','',58865,12430);
INSERT INTO stanza VALUES('ZS747','1','哦主！我愿花费自己，<br/>为着建造你的召会；<br/>无奈对你认识浮浅，<br/>扎实经历实在欠缺。<br/>','',58866,12431);
INSERT INTO stanza VALUES('ZS747','chorus','我今立下一个心志，<br/>愿意完全认识基督；<br/>更要天天享受经历，<br/>得着基督供应召会。<br/>','',58867,12432);
INSERT INTO stanza VALUES('ZS747','2','万有基督在我里头，<br/>祂是源泉，祂也是流；<br/>惟有更多认识经历，<br/>才能成流点活别人。<br/>','',58868,12433);
INSERT INTO stanza VALUES('ZS747','3','『认识基督』只说不够，<br/>须在经历享用实际，<br/>享用越多，越有花费，<br/>经历越深，越有摆出。<br/>','',58869,12434);
INSERT INTO stanza VALUES('ZS747','4','虽未坐在三层天上，<br/>圣灵充满，亦感被提；<br/>虽在肉身仍然活着，<br/>却有死而复活经历。<br/>','',58870,12435);
INSERT INTO stanza VALUES('ZS747','5','当我享祂，祂亦享我，<br/>当我得祂，祂亦得我；<br/>惟有如此相互享用，<br/>结实经历，越过越丰。<br/>','',58871,12436);
INSERT INTO stanza VALUES('ZS747','6','若要花费，需有本钱，<br/>认识基督是我至宝；<br/>万事在我，都如粪土，<br/>我要实际得着基督。<br/>','',58872,12437);
INSERT INTO stanza VALUES('ZS748','1','这世界非我家，<br/>我的家是召会，<br/>我的生命财物，<br/>全为召会花费；<br/>这世界一切事务<br/>尽都是虚空，<br/>我若不为召会，<br/>必浪费世界中。<br/>哦主！<br/>你的心意乃是召会，<br/>开展你的国度，<br/>执行你的权柄。<br/>我的所是所有<br/>从世界全收回，<br/>从今起我活着<br/>完全是为召会。<br/>','',58873,12438);
INSERT INTO stanza VALUES('ZS749','1','恩主我们同在这里，<br/>来向你表明心意，<br/>为着你召会的恢复，<br/>我们愿侍立一起。<br/>让我们能同死同苦，<br/>同承担你的托付，<br/>让我们能一同花费，<br/>直到你得胜归回。<br/>哦主，愿你成全此意，<br/>使我们终身相依，<br/>借着我们你得满足，<br/>并且成全你旨意。<br/>','',58874,12439);
INSERT INTO stanza VALUES('ZS750','1','我今撇下一切事物，<br/>背起十架为召会；<br/>甘受藐视厌弃贫苦，<br/>一心跟主走窄路。<br/>前我所爱所慕所求，<br/>今与雄心同归尽；<br/>但我又是何等饶优，<br/>基督召会是我分。<br/>','',58875,12440);
INSERT INTO stanza VALUES('ZS750','2','让这世界弃我嫌我，<br/>召会原不属尘世；<br/>人面人心欺我骗我，<br/>召会却是我实际。<br/>当我生活在召会中，<br/>友虽生疏敌虽险，<br/>但我心安处之泰然，<br/>荣耀召会我看见。<br/>','',58876,12441);
INSERT INTO stanza VALUES('ZS750','3','去罢！今世名利福乐，<br/>来罢！痛苦和嘲讥。<br/>为主旨意苦是喜乐，<br/>与主同工损是益。<br/>我既称祂阿爸父亲，<br/>我既将心注于你，<br/>怒吼暴风密集厚云，<br/>都该效力成我益。<br/>','',58877,12442);
INSERT INTO stanza VALUES('ZS750','4','人虽逼我使我苦痛，<br/>不能改变我心愿，<br/>世间苦难压我越重，<br/>召会生活越甘甜。<br/>有何忧苦能将我袭，<br/>当你荣耀向我显；<br/>有何快乐能将我迷，<br/>若牠不在召会里。<br/>','',58878,12443);
INSERT INTO stanza VALUES('ZS750','5','向前！由恩进入荣耀，<br/>经历身体是能力，<br/>她的丰满是我实际，<br/>为她活着直到底。<br/>直到地上职事停止，<br/>直到奔跑到路终；<br/>直到盼望成为事实，<br/>围绕宝座同赞颂。<br/>','',58879,12444);
INSERT INTO stanza VALUES('ZS751','1','遇见耶稣，我才相信，<br/>有一种爱果真没有条件；<br/>爱使祂来救我并住我心，<br/>背负我的软弱，<br/>医治甘甜。<br/>遇见你们，我才知道，<br/>我的产业竟是如此丰盛；<br/>弟兄姊妹如同云彩围绕，<br/>我真满足活在幸福之中。<br/>祂的爱情不会毁损，<br/>祂的信实从不短缺，<br/>生命供应全备、常新，<br/>带我与祂身体联结；<br/>为祂我愿撇下世界，<br/>因我有更荣耀基业；<br/>主已应许我得生命，<br/>换来百倍，就在今生。<br/>','',58880,12445);
INSERT INTO stanza VALUES('ZS751','2','奔跑路上，主恩丰满，<br/>应时、多方，<br/>你们供应无限；<br/>你们爱主，<br/>常激励我向前，<br/>也用这爱爱我，<br/>何其深远；<br/>软弱，<br/>陪我同哭主前；<br/>失败，<br/>也要跌在你们中间。<br/>走过日子，<br/>我心只有感恩，<br/>我的成长、喜悦<br/>都在你们。<br/>我心赞美，为着你们；<br/>弟兄姊妹最爱最亲。<br/>我灵、我魂、我整个人，<br/>乐意全然信托你们；<br/>我们成为一个活祭，<br/>主前侍立，讨主欢喜，<br/>无论何往，放胆举步，<br/>有弟兄处，就有活路。<br/>','',58881,12446);
INSERT INTO stanza VALUES('ZS752','1','因着爱，<br/>我们又再次相聚，<br/>诉说恩典、安慰和鼓励；<br/>享受灵的交通、<br/>慈心、怜恤，<br/>我们喜乐、满足且洋溢。<br/>爱里没有惧怕，<br/>完全的爱把惧怕驱除。<br/>同作肢体，<br/>相互提携、接纳，<br/>同蒙天召，奔跑生命路。<br/>爱使我们相聚一起，<br/>彼此相爱，心心相系，<br/>有圣洁情意，<br/>让世人都知道：<br/>这爱是在基督耶稣里！<br/>爱使我们建造一起，<br/>持守真实，联调为一，<br/>有生命实际，<br/>让世人都看见：<br/>永远的爱就是神自己！<br/>','',58882,12447);
INSERT INTO stanza VALUES('ZS801','chorus','我们投入恢复流里，<br/>有分于祂荣耀经营；<br/>我们进入身体事奉，<br/>被建造完成神旨意。<br/>被建造，完成神旨意；<br/>被建造，完成神旨意；<br/>被建造，完成神旨意；<br/>真欢喜！<br/>世界情欲，即将过去，<br/>神的旨意永不止息。<br/>我们不甘随流失去，<br/>我们愿被建造在一起，<br/>永不分离。<br/>（接副歌，下同。）<br/>','',58883,12448);
INSERT INTO stanza VALUES('ZS801','1','从前浪费在世界中，<br/>全不关心神的行动，<br/>终日追求不过幻梦，<br/>尽都是如捉影、如捕风，<br/>凡事虚空。<br/>','',58884,12449);
INSERT INTO stanza VALUES('ZS801','2','今蒙怜悯，未被撇弃，<br/>祂爱寻我回伯特利，<br/>投身在这荣耀经营，<br/>我此生有意义，有目的，<br/>满了实际。<br/>','',58885,12450);
INSERT INTO stanza VALUES('ZS802','1','我们有位荣耀君王，<br/>天上之天是祂宝座，<br/>全地都在祂的脚下，<br/>万国都要归祂管治。<br/>祂和祂的百姓同住，<br/>祂也分担一切苦楚，<br/>我们与这位王同工，<br/>无比荣耀，那里羞耻？<br/>','',58886,12451);
INSERT INTO stanza VALUES('ZS802','2','我们与王同工同作，<br/>工作全归祂不归我，<br/>祂先用荣耀来搞我，<br/>我们再把别人搞活。<br/>我们能够与王同工，<br/>全凭王的能力托着，<br/>所以责任变成喜乐，<br/>祷告变成赞美颂歌。<br/>','',58887,12452);
INSERT INTO stanza VALUES('ZS802','3','我们与王同工同享，<br/>高品福音不断传扬，<br/>领成千成万人得救，<br/>把国度带到这地上。<br/>世界无论甚么酬劳，<br/>我们连一样也不要，<br/>我们的职业是搞人，<br/>直到把新妇豫备好。<br/>','',58888,12453);
INSERT INTO stanza VALUES('ZS802','4','我们一直与王同工，<br/>天天搞人，天天发疯，<br/>也许冬天还没有到，<br/>荣耀的王就要来了。<br/>那时我们要围绕祂，<br/>赞美快乐，欢呼跳跃，<br/>阿利路亚！同掌王权，<br/>阿利路亚！直到永远。<br/>','',58889,12454);
INSERT INTO stanza VALUES('ZS803','1','我从来不后悔<br/>答应神呼召，<br/>我从来不后悔<br/>完全献给主;<br/>我与恩主同行，<br/>天天在登高，<br/>我从来不后悔<br/>所走每步路。<br/>','',58890,12455);
INSERT INTO stanza VALUES('ZS804','1','早上有人作工，<br/>晌午有人作工，<br/>但我整天闲站，<br/>五点才被召。<br/>我虚度了早上，<br/>枉费晌午时光，<br/>仍旧被你选上，<br/>怎能不感激？<br/>','',58891,12456);
INSERT INTO stanza VALUES('ZS804','chorus','爱，作得最快，<br/>爱，作得最好！<br/>我们格外蒙爱，<br/>并不觉辛苦！<br/>加紧罢，姊妹！<br/>加紧罢，弟兄！<br/>只剩一个钟头，<br/>让我们赶工！<br/>','',58892,12457);
INSERT INTO stanza VALUES('ZS804','2','我原来是在后，<br/>没甚么好夸口；<br/>若论忠心追求，<br/>我不敢抬头。<br/>但你满有怜恤，<br/>叫我从新起头；<br/>『爱』实在摸着我，<br/>怎能再保守？<br/>','',58893,12458);
INSERT INTO stanza VALUES('ZS804','3','不用我们流汗，<br/>别人已经耕好；<br/>不必我们流泪，<br/>圣灵已动工。<br/>时间这么短暂，<br/>工作这么轻松，<br/>别人种我们收，<br/>加紧来赶工！<br/>','',58894,12459);
INSERT INTO stanza VALUES('ZS805','1','基督我王正驱前，<br/>地方召会出现！<br/>今后在许多城市，<br/>召会必成你殿。<br/>借着在灵里的日子，<br/>生命使我们刚强。<br/>基督我王正驱前，<br/>得胜之歌高唱！<br/>','',58895,12460);
INSERT INTO stanza VALUES('ZS806','1','向前进，向前进，<br/>在圣灵里向前进，<br/>阿利路亚，随召会前进。<br/>我们今看见<br/>主召会的恢复，<br/>随着七倍之灵前进。<br/>无论往那里，<br/>使世人都知道，<br/>在这时代主一直前进！<br/>在这时代主一直前进！<br/>','',58896,12461);
INSERT INTO stanza VALUES('ZS807','1','新局面出现，<br/>众圣徒正往前，看！<br/>神的荣耀在地上彰显！<br/>召会复兴的征象，<br/>前后左右皆可见，<br/>阿利路亚，新局面出现。<br/>','',58897,12462);
INSERT INTO stanza VALUES('ZS808','1','从台北市地方召会，<br/>到南部高雄海岸；<br/>我们在灵的新样中，<br/>为主的召会争战。<br/>将地方召会的见证，<br/>在全台湾岛播散；<br/>我们不断向前移动，<br/>到各城市去开展！<br/>这是主今日的恢复，<br/>这乃是祂的行动；<br/>我们必须同心合意，<br/>靠主刚强向前冲。<br/>','',58898,12463);
INSERT INTO stanza VALUES('ZS809','1','在主里刚强！<br/>倚靠主大能大力，<br/>作刚强的人！<br/>在主里刚强！<br/>倚靠主大能大力，<br/>作刚强的人！<br/>在主里刚强，<br/>倚靠主大能大力；<br/>穿戴神军装，<br/>抵挡魔鬼的诡计；<br/>在主里刚强，<br/>在主里刚强，<br/>倚靠主大能大力，刚强！<br/>','',58899,12464);
INSERT INTO stanza VALUES('ZS810','1','为主打美好胜仗，<br/>凭主而活着，<br/>站住立场！<br/>不怕仇敌的攻击，<br/>靠主践踏在牠的头上！<br/>为强的召会生活祷告，<br/>圣徒个个在灵里焚烧，<br/>在新人里面争战，<br/>达到神的目标！<br/>（荣耀，阿利路亚！）<br/>','',58900,12465);
INSERT INTO stanza VALUES('ZS811','1','我不敢稍微失败，<br/>荣耀召会在望，<br/>基督是她的元首，<br/>坐在三层天上。<br/>我今活在异象中，<br/>我能时刻刚强；<br/>今我是个得胜者，<br/>为着召会恢复。<br/>','',58901,12466);
INSERT INTO stanza VALUES('ZS811','chorus','得胜，得胜者！<br/>都因荣耀召会。<br/>今我是个得胜者，<br/>因召会，因召会能得胜。<br/>','',58902,12467);
INSERT INTO stanza VALUES('ZS811','2','我不敢稍微失败，<br/>因有荣耀基督，<br/>召我进到前线来，<br/>享受祂的得胜。<br/>我今是满了胆量，<br/>灵中刚强有力；<br/>今我是个得胜者，<br/>完全充满了你。<br/>','',58903,12468);
INSERT INTO stanza VALUES('ZS811','3','我不敢稍微失败，<br/>因为从军召会<br/>在冲阴府的境界，<br/>成就神的旨意。<br/>我们个个是战士，<br/>刚强能以挥剑；<br/>我们同是得胜者，<br/>见证主的圣言。<br/>','',58904,12469);
INSERT INTO stanza VALUES('ZS811','4','我不敢稍微失败，<br/>当此得胜时辰，<br/>荣耀我王正归回，<br/>要说好！我仆人。<br/>我们同活在天上，<br/>取用祂的能力；<br/>天天作个得胜者，<br/>得胜一直到底。<br/>','',58905,12470);
INSERT INTO stanza VALUES('ZS812','1','已经得胜！<br/>基督已经胜过仇敌，<br/>得胜之声远近都可听见！<br/>宝血有能，<br/>借牠我们必得胜利，<br/>不久全能得胜主必显现！<br/>','',58906,12471);
INSERT INTO stanza VALUES('ZS812','chorus','（女声）<br/>已经得胜！<br/>哦，弟兄们哪，<br/>已经得胜，当高声喊！<br/>在锡安圣城宣告祂得胜，<br/>直到全地充满颂赞。<br/>（男声）<br/>已经得胜！<br/>哦，姊妹们哪，<br/>基督已经完成神旨！<br/>祂是得胜主，<br/>将仇敌征服，<br/>永远之乐从今开始。<br/>','',58907,12472);
INSERT INTO stanza VALUES('ZS812','2','已经得胜！<br/>我们已经胜过仇敌，<br/>因为我们放胆见证主话；<br/>神的话语<br/>带给我们生命、能力；<br/>借着这话我们必向敌夸。<br/>','',58908,12473);
INSERT INTO stanza VALUES('ZS812','3','已经得胜！<br/>仇敌已在我们脚底，<br/>因我们虽至死不爱性命；<br/>我们高喊：『主阿，<br/>你使我们胜利！』<br/>荣耀归神！<br/>赞颂之声不停。<br/>','',58909,12474);
INSERT INTO stanza VALUES('ZS813','1','赞美主，我们都在基督里<br/>得胜有余！<br/>万事万物都互相效力，<br/>使我们得益。<br/>召会是蒙主拣选，<br/>完全合乎神旨意，<br/>原是得胜，全是得胜，<br/>本质就是得胜！<br/>仇敌虽然不甘，<br/>多次多方攻击，<br/>患难、困苦、逼迫、<br/>饥饿、赤身露体，<br/>靠我们主<br/>在凡事上都得胜有余。<br/>得胜！已经完全的得胜！<br/>已经完全的得胜！<br/>已经完全的得胜！<br/>（重复头四句。）<br/>','',58910,12475);
INSERT INTO stanza VALUES('ZS814','1','我们现在就是<br/>在主的得胜里，<br/>不需要我们再来<br/>挣扎与努力；<br/>我们只要享受，<br/>在灵里来支取，<br/>就经历得胜实际。<br/>为何不齐夸胜！<br/>齐夸胜齐夸胜！<br/>我们已经与主<br/>同高升！同高升！<br/>三层天，在灵里，<br/>要得胜，多容易！<br/>撒但在我们脚底！<br/>在主得胜里面<br/>我们一同有分，<br/>这得胜的联结<br/>是永远不可分。<br/>我岂能再失败、灰心，<br/>软弱无能？<br/>我现在享受得胜！<br/>','',58911,12476);
INSERT INTO stanza VALUES('ZS815','1','瞧！我是人，<br/>我是这个宇宙的意义，<br/>对，我是人，<br/>我是这个宇宙的意义！<br/>神造了我，神造了我，<br/>身分崇高，身分崇高，<br/>使我成为<br/>这个宇宙中心和意义。<br/>','',58912,12477);
INSERT INTO stanza VALUES('ZS815','2','我有基督─<br/>祂乃是我人生的意义！<br/>（重复）<br/>这位基督，是我一切，<br/>祂乃是我人生内容、<br/>实际和意义。<br/>','',58913,12478);
INSERT INTO stanza VALUES('ZS815','3','召会乃是─<br/>基督在这地上的彰显！<br/>（重复）<br/>这团体人，能代表神，<br/>管理、征服全地，<br/>使神的计划实现。<br/>','',58914,12479);
INSERT INTO stanza VALUES('ZS815','4','地方召会─<br/>才是真正的团体生活！<br/>（重复）<br/>我们今天生活有路，<br/>借着吃喝<br/>同被建造成地方召会。<br/>','',58915,12480);
INSERT INTO stanza VALUES('ZS815','5','当怎么办？<br/>应当赶快去告诉别人！<br/>（重复）<br/>使万民作主的门徒。<br/>我们都去把这消息<br/>传扬到各地。<br/>','',58916,12481);
INSERT INTO stanza VALUES('ZS816','1','你知道你为何被造？<br/>有否想过这问题？<br/>你的生存有何目的？<br/>你今活着何意义！<br/>你知道神愿作你生命？<br/>祂愿作你生命，<br/>祂愿作你生命！<br/>你乃是祂所造的器皿，<br/>为了装祂，将祂表明。<br/>','',58917,12482);
INSERT INTO stanza VALUES('ZS816','2','你有灵，在你最深处，<br/>比你的心更深入；<br/>你的心装许多事物，<br/>但你的灵仍缺如！<br/>多少年来，你虚空度日；<br/>虽然到处尝试，<br/>总是不得满足。<br/>你的深处岂不觉渴慕；<br/>愿意敞开，尝尝耶稣？<br/>','',58918,12483);
INSERT INTO stanza VALUES('ZS816','3','不管你的看法如何，<br/>在神面前谁无过？<br/>主耶稣已为你流血，<br/>使你过错得解决。<br/>救主耶稣已成全一切，<br/>不需你再努力─<br/>功过全无差别；<br/>祂乃是灵，你接受就行，<br/>祂愿进来作你生命。<br/>','',58919,12484);
INSERT INTO stanza VALUES('ZS816','4','犹如你外面的身子，<br/>容纳自己正合式，<br/>你的灵─在你的深处，<br/>乃是专为容纳主。<br/>何不现在从深处敞开，<br/>现在让主进来，<br/>充满你的心怀；<br/>何不现在从深处敞开，<br/>呼喊主名，祂必进来。<br/>','',58920,12485);
INSERT INTO stanza VALUES('ZS817','1','你知道你为何得救，<br/>有否想过这问题？<br/>究竟神有甚么计划？<br/>基督为何拯救你？<br/>直到如今，我们只知道<br/>基督活在我里，<br/>这实在是美好；<br/>但是神有更深的启示，<br/>神的旨意必须达到。<br/>','',58921,12486);
INSERT INTO stanza VALUES('ZS817','2','伊甸河流有一目的，<br/>供应生命滋润地。<br/>神的拯救如同水流，<br/>经过几段的经历。<br/>我们先脱撒但的辖制，<br/>以后再进一步，<br/>脱开那基督教。<br/>神的恢复一直往前流，<br/>永不会在中途停往。<br/>','',58922,12487);
INSERT INTO stanza VALUES('ZS817','3','不是仅仅一个信徒，<br/>单单独独到处荡；<br/>乃是活石同被建造，<br/>团体基督得显彰。<br/>我们重生为着得更新，<br/>但基督进你心，<br/>还有另一缘故；<br/>祂作我们生命的缘故，<br/>为要得着祂的新妇。<br/>','',58923,12488);
INSERT INTO stanza VALUES('ZS817','4','不是零星散乱宝石，<br/>个别属灵的造诣;<br/>乃是实际在生命里，<br/>同被建造在一起。<br/>你永远不会完全满足，<br/>除非耶稣基督<br/>得着祂的新妇。<br/>有否想过，<br/>今天主正在等待<br/>把你建造起来！<br/>','',58924,12489);
INSERT INTO stanza VALUES('ZS818','1','人生意义是何在？<br/>答案今已找出来！<br/>喊主耶稣尝尝看！<br/>祂是实际真无限！<br/>祂赐丰盛的生命─<br/>活水江河流不停，<br/>新的生命今开始，<br/>喜乐涌出永无止；<br/>爱在里面时增加。<br/>这全都是因着祂！<br/>阿利路亚！<br/>（重复二至五行）<br/>','',58925,12490);
INSERT INTO stanza VALUES('ZS819','1','我们曾遍寻<br/>各处的山岭高岗，<br/>盼望得知人生的真相，<br/>但是一次一次<br/>我们换得失望，<br/>知道世事不过是这样。<br/>直到一天你来<br/>途中遇见我们，<br/>将你可爱的胸怀敞露，<br/>我们就被吸引<br/>归入甜美的你，<br/>得着人生的真谛实意。<br/>','',58926,12491);
INSERT INTO stanza VALUES('ZS819','2','我们看见你那<br/>复活里的荣脸，<br/>知道你曾戴荆棘冠冕；<br/>你那可亲的手<br/>是我所依所倾，<br/>因手上钉痕依然显明。<br/>我们现今在此<br/>享受可爱的你，<br/>日复一日更觉你实际，<br/>犹如潺潺流水<br/>归回无垠大海，<br/>不知不觉失去在你里。<br/>','',58927,12492);
INSERT INTO stanza VALUES('ZS820','1','哦！你今在何处，<br/>天天奔波又忙碌，<br/>却是虚空、虚空、<br/>虚空的生活！<br/>你曾追求过万物，<br/>却是不能得饱足，<br/>总觉得里面缺少、<br/>缺少些甚么！<br/>','',58928,12493);
INSERT INTO stanza VALUES('ZS820','chorus','你需要耶稣！宇宙之主！<br/>你需要享受祂的丰富！<br/>你的心虽比万物都大，<br/>祂却能够、<br/>能够使你得着满足！<br/>','',58929,12494);
INSERT INTO stanza VALUES('ZS820','2','哦！你确是自足，<br/>世上一切你都有，<br/>还是不觉、不觉、<br/>不觉得满足！<br/>你的工作有成就，<br/>学业也可以自负，<br/>但是在你的深处、<br/>深处仍缺如！<br/>','',58930,12495);
INSERT INTO stanza VALUES('ZS821','1','（问）<br/>朋友！朋友！告诉我说：<br/>甚么使你这样快活？<br/>为何喜乐常显你面，<br/>似有活泉涌自你怀。<br/>（答）<br/>你怎不知耶稣我主，<br/>祂曾舍命担我罪辜，<br/>借祂十架，我蒙救赎；<br/>所有罪过祂血尽除。<br/>（同啍）<br/>啦…………（一遍）<br/>','',58931,12496);
INSERT INTO stanza VALUES('ZS821','2','（问）<br/>我的朋友，再告诉我，<br/>是否你的就是这些？<br/>即或我罪都洗清洁，<br/>我的生活仍有所需。<br/>（答）<br/>哦，这恩主何其丰厚，<br/>岂是数语就能说尽，<br/>祂已复活作我生命，<br/>成为我的能力，供应。<br/>（同啍）<br/>啦…………（一遍）<br/>','',58932,12497);
INSERT INTO stanza VALUES('ZS821','3','（问）<br/>我是希奇你所得着，<br/>罪已赦免，生命里活，<br/>但我不知像我这样，<br/>祂的救恩能否得着？<br/>（答）<br/>哦，愿你能知祂大爱，<br/>祂需要你，祂手伸出，<br/>祂巴不得赐你救赎，<br/>作你生命，作你救主。<br/>（同啍）<br/>啦…………（一遍）<br/>','',58933,12498);
INSERT INTO stanza VALUES('ZS821','4','（问）<br/>朋友，朋友，<br/>我今敞开我的心门<br/>让祂进来，<br/>但愿赦罪、生命、能力、<br/>喜乐活水涌自我怀。<br/>（答）<br/>弟兄，弟兄，我们同来，<br/>享受救主，就是现在，<br/>我们同是蒙恩罪人，<br/>赞祂恩惠，颂祂大爱。<br/>（同啍）<br/>啦…………（一遍）<br/>','',58934,12499);
INSERT INTO stanza VALUES('ZS822','1','我曾虚空又痛苦，<br/>不明白活着为何故，<br/>常今朝有酒就今朝醉，<br/>虽强作欢颜，里面流泪，<br/>这辛酸滋味无人能领会；<br/>把牠麻醉，<br/>曾几何时，又归回。<br/>','',58935,12500);
INSERT INTO stanza VALUES('ZS822','2','虽然我并不知道，<br/>当如何解决或祷告，<br/>但是我深处总是渴慕，<br/>想要把生命意义找出。<br/>直到有一天呼喊主耶稣，<br/>让祂进入，<br/>虚空痛苦才消除。<br/>','',58936,12501);
INSERT INTO stanza VALUES('ZS822','3','耶稣活在我里面，<br/>作我主、生命，真甘甜！<br/>因借着呼喊耶稣的名，<br/>我生命、平安与日俱增，<br/>这世上无何使我心羡慕，<br/>我已满足，<br/>因我得着主耶稣。<br/>','',58937,12502);
INSERT INTO stanza VALUES('ZS823','1','你若感觉孤单，<br/>日子难挨，<br/>耶稣，耶稣，与你同在；<br/>你若觉人生黑暗，<br/>前途茫茫，<br/>耶稣，耶稣，是你的光。<br/>你若从深处转向祂，<br/>重担卸下，<br/>祂必定替你担代─<br/>祂与你同在。<br/>不要四处寻求答案，<br/>空等待，<br/>耶稣，耶稣，<br/>祂是『现在』；<br/>你若从深处呼求祂，<br/>祂不失误！<br/>当你多方受磨炼，<br/>请务必记住：无论此世<br/>有多少景况遭遇，<br/>耶稣，耶稣，耶稣是主。<br/>','',58938,12503);
INSERT INTO stanza VALUES('ZS824','1','有所得─<br/>多少东西你梦寐以求，<br/>衣食住行育乐样样有；<br/>等到得手，不过如此。<br/>','',58939,12504);
INSERT INTO stanza VALUES('ZS824','2','有所事─<br/>兴高采烈不过一阵子，<br/>喜新厌旧又再绞脑汁；<br/>日光之下，并无新事。<br/>','',58940,12505);
INSERT INTO stanza VALUES('ZS824','3','人生宛如走马看花，<br/>来去匆匆，<br/>天天忙西忙东，<br/>到头来是虚空的虚空。<br/>你寻求─<br/>要看有何能叫你满足，<br/>扎扎实实非敷衍了事，<br/>能解决你心中苦楚。<br/>','',58941,12506);
INSERT INTO stanza VALUES('ZS824','4','不错，<br/>是有一样你从来没有过，<br/>你所可能企求的<br/>都可在祂身上得着。<br/>祂是主─<br/>祂是何等的丰富实际，<br/>我的无聊已消踪匿迹。<br/>祂填满了我的空虚。<br/>（结尾）<br/>哦主耶稣，你是实际！<br/>','',58942,12507);
INSERT INTO stanza VALUES('ZS825','1','我曾寻找一道泉水，<br/>能解我里面的干渴，<br/>但我饮尽所有水泉，<br/>仍不满足，一无所获。<br/>有一天我寻到，<br/>我寻到我的主，<br/>祂在我深处成为泉源，<br/>一直到永远。阿利路亚！<br/>耶稣！耶稣！耶稣！<br/>耶稣！耶稣解了我干渴。<br/>耶稣！耶稣！耶稣！<br/>耶稣！耶稣作了我生命。<br/>','',58943,12508);
INSERT INTO stanza VALUES('ZS825','2','奇妙活泉住我里面，<br/>天天涌流从不止息，<br/>流向祂的永远心意，<br/>就是祂荣耀的召会。<br/>那一天祂寻回，<br/>祂寻我回祂家，<br/>我就安家在召会里面，<br/>让祂得满足。阿利路亚！<br/>召会！召会！召会！<br/>召会！召会就是祂满足。<br/>召会！召会！召会！<br/>召会！召会就是我生活。<br/>','',58944,12509);
INSERT INTO stanza VALUES('ZS826','1','前我生活，满了愁苦，<br/>我的奋斗，都归虚无。<br/>自从耶稣，进我心府，<br/>祂作了我喜乐满足。<br/>哦，何等奇妙，<br/>是我主耶稣！<br/>请你接受耶稣作救主，<br/>呼求祂的名，<br/>你就必得救！<br/>','',58945,12510);
INSERT INTO stanza VALUES('ZS827','1','这是在你，朋友，<br/>你的被造<br/>是为装神的生命，<br/>当你敞开你心怀的刹那，<br/>祂将要进来，<br/>在你深处安家。<br/>呼喊祂名耶稣，<br/>祂是又真<br/>又活的可爱救主，<br/>祂的灵正如同生命之气，<br/>哦，向祂敞开，<br/>就能将祂支取。<br/>不要将祂不顾，<br/>你若虚空，<br/>惟有祂爱能满足，<br/>何不速来呼求，<br/>让祂进入，你必无所失，<br/>却充满祂丰富。<br/>主！耶稣！阿利路亚！<br/>阿利路亚！耶稣。<br/>主！耶稣！阿利路亚！<br/>阿利路亚！耶稣。<br/>','',58946,12511);
INSERT INTO stanza VALUES('ZS828','1','你若渴慕得着主，<br/>切莫寻祂世界中，<br/>因这世界<br/>并非祂居住之所。<br/>非祂居所，非祂居所，<br/>非祂居所，非祂居所，<br/>因这世界<br/>并非祂居住之所。<br/>','',58947,12512);
INSERT INTO stanza VALUES('ZS828','2','你若渴慕得着主，<br/>切莫寻祂心思中，<br/>心思只使你明白，<br/>却不能尝。<br/>它不能尝，（四次）<br/>心思只使你明白，<br/>却不能尝。<br/>','',58948,12513);
INSERT INTO stanza VALUES('ZS828','3','你若渴慕得着主，<br/>只要敞开你的心，<br/>只要敞开你的心，<br/>让祂进来。<br/>让祂进来，（四次）<br/>只要敞开你的心，<br/>让祂进来。<br/>','',58949,12514);
INSERT INTO stanza VALUES('ZS828','4','你若想让祂进来，<br/>只要呼喊祂的名，<br/>只要呼喊祂的名，<br/>祂就进来。<br/>哦！主耶稣！（四次）<br/>只要呼喊祂的名，<br/>祂必进来。<br/>','',58950,12515);
INSERT INTO stanza VALUES('ZS829','1','你若虚空，<br/>常觉得若有所失，<br/>你的答案乃是─耶稣！<br/>你若是有一饥渴<br/>在你深处，<br/>你可得着满足─耶稣！<br/>你不需要再受捆绑，<br/>感觉前途茫茫；<br/>你不需要再作罪奴，<br/>或者成天幻想。<br/>耶稣甚近，在你心上，<br/>你口旁，<br/>祂正在等待你敞开，<br/>一呼喊，祂就进来。<br/>耶稣─黑暗变成光明；<br/>耶稣─平安难以形容；<br/>耶稣─从此开始新生命！<br/>','',58951,12516);
INSERT INTO stanza VALUES('ZS830','1','呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>哦，主耶稣！<br/>哦，主耶稣！<br/>呼喊主的名必得救！<br/>哦，主耶稣！<br/>哦，主耶稣！<br/>呼喊主的名必得救！<br/>','',58952,12517);
INSERT INTO stanza VALUES('ZS830','2','呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>呼喊主的名，<br/>呼喊主的名，<br/>呼喊主的名必得救！<br/>哦，主耶稣！<br/>哦，主耶稣！<br/>阿利路亚我已得救！<br/>哦，主耶稣！<br/>哦，主耶稣！<br/>阿利路亚我已得救！<br/>','',58953,12518);
INSERT INTO stanza VALUES('ZS831','1','朋友，朋友，<br/>且听这呼召，<br/>不住地临及你心内；<br/>祂的声音是何等柔细，<br/>却又何其实际。<br/>祂请你分享祂的爱情，<br/>来经历祂超越的丰富，<br/>祂请你活着为祂旨意，<br/>让祂能借你得满足。<br/>','',58954,12519);
INSERT INTO stanza VALUES('ZS831','2','我爱，我爱，<br/>这是何奇妙，<br/>你慈爱柔声的细语，<br/>使我的心熔化在你里，<br/>使我忘却自己。<br/>不仅是一个蒙爱儿女，<br/>也能跟随你坚定脚踪，<br/>能作你朋友同你心意，<br/>让你能借我得满足。<br/>','',58955,12520);
INSERT INTO stanza VALUES('ZS832','1','我听见了主耶稣说：<br/>『来，就我得安息！<br/>疲倦的人，来这里躺卧，<br/>你可歇我胸臆。』<br/>照我本相，来就耶稣，<br/>疲惫、困倦又忧郁。<br/>祂是我的安息之所，<br/>祂使我心畅欢。<br/>','',58956,12521);
INSERT INTO stanza VALUES('ZS832','2','我听见了主耶稣说：<br/>『看！我白白赐给。<br/>干渴的人，来畅饮活水，<br/>你可欢然取水。』<br/>我敞开心怀就耶稣，<br/>并喝那生命活泉，<br/>干渴立消，我魂复苏，<br/>现今活在祂前。<br/>','',58957,12522);
INSERT INTO stanza VALUES('ZS832','3','我听见了主耶稣说：<br/>『我是世界的光，<br/>转眼看我，晨星必出现，<br/>照耀你的途径。』<br/>我从自己转向耶稣，<br/>祂是我晨星、太阳。<br/>生命光中，欢乐行走，<br/>行尽客旅路程。<br/>','',58958,12523);
INSERT INTO stanza VALUES('ZS833','1','有一新生命，<br/>美妙、喜乐、光明；<br/>你能够得到，<br/>只要你决意。<br/>耶稣能满足<br/>你的虚空心灵，<br/>祂使你心中无比的喜乐。<br/>你能够经历<br/>人生奇妙大改变，<br/>你能够进入伟大的情境；<br/>你能够经历<br/>超越荣耀的事情，<br/>如果你让救主<br/>进入你的心。<br/>','',58959,12524);
INSERT INTO stanza VALUES('ZS833','2','现在你心思<br/>不需完全明白，<br/>不必知道为甚么，<br/>或怎样；<br/>因祂要给<br/>你远超你心所望，<br/>远超你头脑所领会得来。<br/>','',58960,12525);
INSERT INTO stanza VALUES('ZS834','1','『各样都齐备』，<br/>请来赴席！<br/>来，桌上已摆满美物；<br/>哦，饥饿者，疲倦者，<br/>来，你们就必得饱足。<br/>','',58961,12526);
INSERT INTO stanza VALUES('ZS834','chorus','听，主正在邀请，<br/>无论何人愿意，<br/>来得神完全救恩，<br/>无论何人愿意。<br/>','',58962,12527);
INSERT INTO stanza VALUES('ZS834','2','『各样都齐备』，<br/>请来赴席！<br/>来，恩门现在正大开；<br/>尊贵之位为你保留，<br/>靠近主人的胸怀。<br/>','',58963,12528);
INSERT INTO stanza VALUES('ZS834','3','『各样都齐备』，<br/>请来赴席！<br/>来，祂等着你尝恩典；<br/>今天是时候，莫迟延，<br/>因不一定有明天。<br/>','',58964,12529);
INSERT INTO stanza VALUES('ZS834','4','『各样都齐备』，<br/>请来赴席！<br/>脱去罣虑，属世争竞，<br/>来，吃神所赐的基督，<br/>并喝永远的生命。<br/>','',58965,12530);
INSERT INTO stanza VALUES('ZS835','1','何大怜悯，<br/>我眼得开识真神，<br/>喜脱黑暗，<br/>得享光明自由！<br/>何奇恩典，<br/>我能白白得救恩，<br/>不需善行，<br/>也不需我苦修！<br/>','',58966,12531);
INSERT INTO stanza VALUES('ZS835','2','主已救我；<br/>求也记念我家人，<br/>你已担当他们罪过愆尤；<br/>我今切求，<br/>求你应许成为真：<br/>『信主耶稣，<br/>全家都必得救。』<br/>','',58967,12532);
INSERT INTO stanza VALUES('ZS835','3','主，你听我：<br/>切要得着我全家！<br/>也要垂顾，<br/>我心为此如焚：<br/>『我和我家，<br/>都要事奉耶和华！』<br/>世世代代敬拜我真活神！<br/>','',58968,12533);
INSERT INTO stanza VALUES('ZS836','1','虽经漫漫长夜，<br/>晚星也都已消灭，<br/>神却末曾忘记<br/>祂所定的永约；<br/>当我们正徘徊在<br/>死荫之地离不开，<br/>有一清晨的日光<br/>从天而来。<br/>是神怜悯的心肠，<br/>眷顾罪人的忧伤，<br/>把我们的脚<br/>引到平安路上，<br/>所有黑暗尽驱走，<br/>天来救主施拯救，<br/>使我们的黑夜变为白昼！<br/>','',58969,12534);
INSERT INTO stanza VALUES('ZS836','2','你来寻找失丧者，<br/>你肯赦免犯罪的，<br/>你使卑贱无望人<br/>得享天上乐；<br/>从你活出神自己，<br/>在神拯救恩典里，<br/>你给万民带来<br/>大喜的信息。<br/>你是神人的调和，<br/>你是人中的圣者，<br/>我们从你看见<br/>人性的美德；<br/>如此救主我爱戴，<br/>向你我心献敬拜，<br/>赞美你，<br/>今住我卑微胸怀！<br/>','',58970,12535);
INSERT INTO stanza VALUES('ZS837','1','初次来这里，<br/>听他们在说耶稣的事迹，<br/>未曾闻过，<br/>但在我心坎有新的感受，<br/>莫名的平安像股暖流；<br/>我几乎忘记来前的苦恼，<br/>不觉已脱离俗世的囚牢。<br/>从他们脸上表露的纯真，<br/>我心暗想：真的有神！<br/>','',58971,12536);
INSERT INTO stanza VALUES('ZS837','2','他们且告诉，<br/>神要进我里，<br/>作生命、救主，<br/>若我愿意；我眼未看到，<br/>对祂又不知，<br/>只觉得需要，不妨一试；<br/>我就从深处真心转向祂，<br/>喊『哦，主耶稣！』<br/>求祂来救拔。<br/>从无一名字如此甘又美，<br/>我享真实，今仍回味！<br/>','',58972,12537);
INSERT INTO stanza VALUES('ZS837','3','脱一身缠累，<br/>进入真安息，<br/>不再有定罪，蒙神称义，<br/>我与主联合，<br/>祂是我生命，<br/>今向神活着，因信得生；<br/>我在基督里荣耀又逍遥，<br/>我与祂是一，<br/>成为神新造。哦，<br/>这个就是我信的故事，<br/>美妙之至，是爱是诗！<br/>','',58973,12538);
INSERT INTO stanza VALUES('ZS838','1','让我满怀喜乐告诉你，<br/>朋友，<br/>我已得到真正自由，<br/>痛苦、压制、忧愁<br/>全都不留，<br/>就在我信主之后。<br/>祂不是信条，<br/>要我来遵守，<br/>也非诫命对我只要求；<br/>祂是神儿子，<br/>人心灵拯救，<br/>爱和生命从祂涌流，<br/>祂来解开深牢中<br/>苦恼罪囚，<br/>出死入生带我行走。<br/>','',58974,12539);
INSERT INTO stanza VALUES('ZS838','2','我今在蔚蓝天空<br/>展翅遨游，<br/>耶稣是我真正自由，<br/>日复一日在这无边享受，<br/>我心说：『有祂就够！』<br/>朋友，<br/>这样一位何处能有，<br/>祂爱你，已等得好长久，<br/>愿否趁祂胸怀向你敞露，<br/>前来向祂完全倚投，<br/>当你进入<br/>神儿女荣耀自由，<br/>你心就不会不歌讴。<br/>','',58975,12540);
INSERT INTO stanza VALUES('ZS839','1','我的生命不再挥霍，<br/>自从我看见云彩，<br/>越过一片死寂荒漠，<br/>远远的显现出来；<br/>牠像光明火柱，<br/>照亮黑暗道路，<br/>燃起人生新希望，<br/>定住我的脚步。<br/>','',58976,12541);
INSERT INTO stanza VALUES('ZS839','2','我的人生变得充实，<br/>正当我迎向云彩，<br/>宇宙万物真理柱石，<br/>千百年历久不衰；<br/>牠是神所经营，<br/>活神显于肉身，<br/>给我无比信心，<br/>给我无比温馨。<br/>','',58977,12542);
INSERT INTO stanza VALUES('ZS839','3','我的生活何等豪迈，<br/>因我已拥有云彩，<br/>弟兄姊妹坚强的爱，<br/>围绕我不至摇摆；<br/>真理照亮我的灵，<br/>恩典无穷无尽，<br/>从此我心有所归，<br/>不再叹息徘徊。<br/>','',58978,12543);
INSERT INTO stanza VALUES('ZS839','4','我与你们已经融合，<br/>也化为这朵云彩，<br/>天空多么灿烂明亮，<br/>不怕那弯曲世代；<br/>让我大步向前去，<br/>将这见证高举，<br/>愿牠光采更壮丽，<br/>直到永世不渝。<br/>（尾声）<br/>主，噢！主，噢！<br/>让我放下各样重担，<br/>生活在光明的云彩。<br/>（注）『云彩』一辞<br/>采自希伯来十二章一节，<br/>指许多见证人。<br/>','',58979,12544);
INSERT INTO stanza VALUES('ZS840','1','听！大好信息，<br/>惊天又动地，<br/>你是神容器，<br/>为装祂自己，<br/>祂不仅造了你，<br/>更要来充满你，<br/>作你生命住你里；<br/>使你享受祂实际，<br/>使你人生变美丽，<br/>使你活着满意义，<br/>只要你愿意。<br/>','',58980,12545);
INSERT INTO stanza VALUES('ZS840','2','过去永远里祂早拣选你，<br/>因爱的催逼为你亲来地，<br/>十架上被举起，<br/>经死亡祂复起，<br/>今特地来寻找你；<br/>要将活神带给你，<br/>要将生命分给你，<br/>要将恩典赐给你，<br/>使你心满意！<br/>','',58981,12546);
INSERT INTO stanza VALUES('ZS840','3','当你有了祂─<br/>三一神自己，<br/>你全人会有生命的奇迹：<br/>你灵会有活力，<br/>你魂会真欢喜，<br/>你身安居指望里；<br/>只要将心全开启，<br/>只要主名一呼吸，<br/>只要一刹那而已，<br/>祂、你就是一！<br/>','',58982,12547);
INSERT INTO stanza VALUES('ZS841','1','生命如此好，<br/>生存价值如此高，<br/>我热爱生命，<br/>举手叩求真理之门；<br/>第一声呼求，<br/>冲出我心灵，<br/>哦，主耶稣！<br/>亮光之名，自由之名，<br/>我生命终于破晓，<br/>哦，主耶稣！<br/>亮光之名，自由之名，<br/>我生命开始有了日出。<br/>','',58983,12548);
INSERT INTO stanza VALUES('ZS841','2','生命如此好，<br/>本来就是神创造，<br/>我热爱生命，<br/>迫切投入生命泉源；<br/>第一声呼求，<br/>冲出我心灵，<br/>哦，主耶稣！<br/>活水之源，甘甜之泉，<br/>我生命得到滋润，<br/>哦，主耶稣！<br/>活水之源，甘甜之泉，<br/>我生命涌流着活的泉水。<br/>','',58984,12549);
INSERT INTO stanza VALUES('ZS841','3','生命如此好，<br/>追求真理要趁早，<br/>我热爱生命，<br/>我热爱生命之主；<br/>第一声呼求，<br/>冲出我心灵，<br/>哦，主耶稣！<br/>进入我心，进入我灵，<br/>我生命因你成新人，<br/>哦，主耶稣！<br/>进入我心，进入我灵，<br/>我生命有了你境界全新。<br/>','',58985,12550);
INSERT INTO stanza VALUES('ZS842','1','在那迷失年代，<br/>我曾寻访爱的天地，<br/>明知多人爱我，<br/>但我仍是寂寞不乐；<br/>直到我有耶稣─<br/>神赐给人爱的名字，<br/>响亮在我心灵，<br/>我的年代因祂常青。<br/>','',58986,12551);
INSERT INTO stanza VALUES('ZS842','2','祂是爱又是灵，<br/>进入我灵，与我结盟，<br/>我享受祂生命，<br/>祂享受我爱的顺从；<br/>我们融在一起，<br/>日夜作伴，苦乐不离；<br/>爱是最大财富，<br/>世间最爱我的是主。<br/>（重复第四行）<br/>','',58987,12552);
INSERT INTO stanza VALUES('ZS843','1','天起了凉风，<br/>人陷罪恶中；<br/>神在天地间，声声呼唤：<br/>你在那里？人哪，<br/>你在何地？<br/>神的爱情，祂的安息，<br/>全都在于你。<br/>','',58988,12553);
INSERT INTO stanza VALUES('ZS843','2','享受主救恩，<br/>满足人和神，<br/>神、人同建造，<br/>居所何荣耀；<br/>团体新人，大哉！<br/>神显于肉身，<br/>天使看见，世人信服，<br/>活神住人间。<br/>','',58989,12554);
INSERT INTO stanza VALUES('ZS843','3','畅饮生命河，<br/>欢唱恩爱歌，<br/>同享主肥甘，荣光溢漫；<br/>天地相系，<br/>神、人永远合一，<br/>人的住处，神的安息，<br/>显在荣耀里！<br/>','',58990,12555);
INSERT INTO stanza VALUES('ZS844','1','我是个新约福音祭司，<br/>带罪人归神是我天职，<br/>挨家去寻访平安之子，<br/>神生命涌流不止；<br/>传扬福音救罪人，<br/>当作祭物献给神，<br/>天上都因此喜乐欢欣，<br/>我神也喜悦满心。<br/>','',58991,12556);
INSERT INTO stanza VALUES('ZS844','chorus','何荣耀！这样的工作，<br/>使我天天新又活，<br/>何美妙！这样的生活，<br/>使我常常结新果。<br/>','',58992,12557);
INSERT INTO stanza VALUES('ZS844','2','我是个新约福音祭司，<br/>带领人归神，劳苦不辞，<br/>使人能甘心献上自己，<br/>作活祭满足神心意；<br/>宣扬基督供应人，<br/>警戒、教导，成全人，<br/>直等到将人在基督里，<br/>成熟的献上给神。<br/>','',58993,12558);
INSERT INTO stanza VALUES('ZS845','1','那些愁苦、忧虑的日子，<br/>已经一去不再回，<br/>喜乐活泉潺潺流不止，<br/>平安在心间，不消退；<br/>哦，主耶稣，我感谢你，<br/>这都是因你的怜悯，<br/>使我全家完全属你，<br/>满享神的救恩。<br/>','',58994,12559);
INSERT INTO stanza VALUES('ZS845','2','我要宣告：<br/>至于我和我家，<br/>必定事奉耶和华，<br/>从大到小个个尊主为大，<br/>一心成全神计画；<br/>哦，主耶稣，我赞美你，<br/>我的家作你的住处，<br/>惟愿这家圣别归你，<br/>多人因此蒙福。<br/>','',58995,12560);
INSERT INTO stanza VALUES('ZS846','1','跟随我主走一程，<br/>向上去得奖赏，<br/>正直爱主过一生，<br/>如同黎明的光；<br/>挥别世途和都城，<br/>选这光明一程，<br/>投身开展行列中，<br/>作主争战弟兄。<br/>一步迈开又一步，<br/>走出主恢复前途，<br/>见牠日日更辉煌，<br/>直到普照四方。<br/>','',58996,12561);
INSERT INTO stanza VALUES('ZS846','2','跟随耶稣的脚踪，<br/>一路洋溢歌声，<br/>各处宣扬主得胜，<br/>美好微曦上升；<br/>轻举脚步向前行，<br/>肩负我主使命，<br/>福音遍传，主扩增，<br/>光芒越照越明。<br/>今日胜过了昨日，<br/>开创主恢复历史，<br/>写下崭新的一页，<br/>至终光辉烈烈。<br/>','',58997,12562);
INSERT INTO stanza VALUES('ZS847','1','若世间真有一种爱，<br/>能满足人最深情怀，<br/>无限量像洋海，<br/>不改变比坚崖，<br/>救主耶稣祂就不必来；<br/>黑暗里，祂听见<br/>我叹息，我悲哀，<br/>一路上，祂看见<br/>我徘徊，我无奈。<br/>','',58998,12563);
INSERT INTO stanza VALUES('ZS847','2','因着爱，祂不能再等待，<br/>从天来，走在人世尘埃，<br/>寻找我，不懈怠；<br/>忍饥渴，受苦害；<br/>被挂木上，清偿我罪债；<br/>经死亡，祂复活，<br/>进我灵，作主宰，<br/>与我联合，使我心满爱。<br/>','',58999,12564);
INSERT INTO stanza VALUES('ZS847','3','这世间我得到真爱，<br/>是耶稣，那全胜的爱，<br/>无限量像洋海，<br/>不改变比坚崖，<br/>真挚、无价、<br/>恒久且不衰；<br/>我日子祂同在，<br/>我道路祂领帅；<br/>我的主，我的爱，<br/>我爱你到万代。<br/>','',59000,12565);
INSERT INTO stanza VALUES('ZS848','1','听我唱，奇妙爱：<br/>是耶稣，从天来，<br/>十架上，祂裂开，<br/>将神圣生命释放出来；<br/>真喜乐，罪全赦，<br/>进我灵，解干渴，<br/>住我心，永联合，<br/>且从我涌出如江河。<br/>','',59001,12566);
INSERT INTO stanza VALUES('ZS848','2','祂离你并不远，<br/>就在你口里面；<br/>主的名一呼喊，<br/>祂立刻进入你的心间；<br/>我尝过，我诉说，<br/>主的爱深难测，<br/>凡愿意，谁都可<br/>从救恩水泉来白喝。<br/>','',59002,12567);
INSERT INTO stanza VALUES('ZS849','1','哦，让我们扬声欢呼，<br/>角声遍地发出，<br/>同宣告神救赎之日，<br/>人生从今开始；<br/>出黑暗，脱捆绑，<br/>我这罪囚大得释放。<br/>哦，让我们扬声欢呼，<br/>角声遍地发出。<br/>','',59003,12568);
INSERT INTO stanza VALUES('ZS849','2','哦，让我们击鼓跳舞，<br/>踏着喜悦脚步，<br/>同进入神恩典禧年，<br/>前途美好无限；<br/>我权益都恢复，<br/>重归自由，产业丰富。<br/>哦，让我们击鼓跳舞，<br/>踏着喜悦脚步。<br/>','',59004,12569);
INSERT INTO stanza VALUES('ZS849','3','哦，让我们尽情享受，<br/>去罢，烦恼、忧愁，<br/>将你喜乐快快敞开，<br/>神自己必进来；<br/>祂丰富充满我，<br/>如同大水，全人漫过。<br/>哦，让我们尽情享受，<br/>去罢，烦恼、忧愁。<br/>','',59005,12570);
INSERT INTO stanza VALUES('ZS849','4','哦，让我们吃喝快乐，<br/>父家满了诗歌，<br/>祂是我们完全的爱，<br/>我们一生年代；<br/>来安家神居所，<br/>天天过着禧年生活。<br/>哦，让我们吃喝快乐，<br/>父家满了诗歌。<br/>','',59006,12571);
INSERT INTO stanza VALUES('ZS901','1','末期豫兆在指明，<br/>基督快要再降临，<br/>我们豫备当儆醒─<br/>恩主耶稣要再临！<br/>','',59007,12572);
INSERT INTO stanza VALUES('ZS901','chorus','主要再临，主要再临，<br/>时间飞逝不稍等，<br/>不久即闻半夜喊声！<br/>主要再临，主要再临，<br/>我们须豫备像聪明童女，<br/>恩主耶稣要再临！<br/>','',59008,12573);
INSERT INTO stanza VALUES('ZS901','2','当从魂和你自己，<br/>转眼望主不稍离，<br/>没有时间再迟疑─<br/>恩主耶稣要再临！<br/>','',59009,12574);
INSERT INTO stanza VALUES('ZS901','3','愚拙童女恋世界，<br/>到主来时才发觉，<br/>器皿里面油空缺─<br/>恩主耶稣要再临！<br/>','',59010,12575);
INSERT INTO stanza VALUES('ZS901','4','聪明童女常殷勤，<br/>世界的酒不醉饮，<br/>她们发光，灵充盈─<br/>恩主耶稣要再临！<br/>','',59011,12576);
INSERT INTO stanza VALUES('ZS901','5','我们出去迎新郎，<br/>必须将灯修明亮，<br/>也须买油免灯暗─<br/>恩主耶稣要再临！<br/>','',59012,12577);
INSERT INTO stanza VALUES('ZS901','6','聪明童女都进去，<br/>作祂新妇同坐席，<br/>门向她们不关闭─<br/>恩主耶稣要再临！<br/>','',59013,12578);
INSERT INTO stanza VALUES('ZS901','7','主今就在归途中，<br/>无人知道那点钟，<br/>儆醒与主时交通─<br/>恩主耶稣要再临！<br/>','',59014,12579);
INSERT INTO stanza VALUES('ZS902','1','主必要快来─<br/>今与世界断开；<br/>脱去一切的缠累，<br/>快跑不懈怠。<br/>','',59015,12580);
INSERT INTO stanza VALUES('ZS902','chorus','主就要来！主就要来！<br/>哦，主就要回来！<br/>主就要来！主就要来！<br/>阿们，主快来！<br/>','',59016,12581);
INSERT INTO stanza VALUES('ZS902','2','也许是今天─<br/>向主注目不变，<br/>转眼仰望主耶稣，<br/>虽时遭惊险。<br/>','',59017,12582);
INSERT INTO stanza VALUES('ZS902','3','从自己、罪、世，<br/>转眼向主注视，<br/>祂必为你来完成，<br/>祂所已创始。<br/>','',59018,12583);
INSERT INTO stanza VALUES('ZS902','4','注视祂荣面<br/>满受祂的恩典，<br/>将来在祂国度里，<br/>与祂同显现。<br/>','',59019,12584);
INSERT INTO stanza VALUES('ZS902','5','阿们祂的话─<br/>所读所听的话，<br/>我们灵里被激动；<br/>准备迎接祂。<br/>','',59020,12585);
INSERT INTO stanza VALUES('ZS903','1','主随时随刻都可能回来，<br/>主随时随刻都可能回来，<br/>主随时随刻都可能回来，<br/>哦，让我们儆醒等待！<br/>','',59021,12586);
INSERT INTO stanza VALUES('ZS903','2','基督是我们可爱的新郎，<br/>（重复三次，下同）<br/>我们乃是祂的新妇！<br/>','',59022,12587);
INSERT INTO stanza VALUES('ZS903','3','我们已定意转眼注视主，<br/>永不回头，永不回头！<br/>','',59023,12588);
INSERT INTO stanza VALUES('ZS903','4','路程在前头，<br/>缠累丢背后，<br/>加速向前！加速向前！<br/>','',59024,12589);
INSERT INTO stanza VALUES('ZS903','5','我们正快跑，<br/>迎接主来到，<br/>不久就要与主相遇！<br/>','',59025,12590);
INSERT INTO stanza VALUES('ZS904','1','醒罢，弟兄！<br/>醒罢，姊妹！<br/>黑夜已深，<br/>白昼现正临近。<br/>我们的主快再来，<br/>快再来，快再来。<br/>我们的主快再来，<br/>掌权直到万代。<br/>','',59026,12591);
INSERT INTO stanza VALUES('ZS904','2','时候不多！不可懒惰！<br/>在祂面前必须多花时间，<br/>我们就必充满主，<br/>充满主，充满主，<br/>我们就必充满主，<br/>并要将主溢出。<br/>','',59027,12592);
INSERT INTO stanza VALUES('ZS904','3','应当喜乐！凭信唱歌！<br/>任何试炼，<br/>只要住主里面！<br/>我们快乐往前走，<br/>往前走，往前走；<br/>无论夜是多么暗，<br/>有主就可安然。<br/>','',59028,12593);
INSERT INTO stanza VALUES('ZS904','4','站稳，弟兄！<br/>站稳，姊妹！<br/>争战快停，<br/>灵里刚强前行，<br/>一直等到主再来，<br/>主再来，主再来。<br/>一直等到主再来，<br/>同作王到万代。<br/>','',59029,12594);
INSERT INTO stanza VALUES('ZS905','1','喜乐，喜乐，<br/>新郎快来到，<br/>时候必不再耽搁。<br/>不久那婚娶之晨临到，<br/>我们欢唱新诗歌。<br/>','',59030,12595);
INSERT INTO stanza VALUES('ZS905','chorus','哦，美妙日！<br/>哦，荣耀之晨！<br/>当基督我爱来临，<br/>我们器皿充满，<br/>灯都发光，<br/>出去迎接祂回来。<br/>喜乐，喜乐，<br/>新郎快来到，<br/>时候必不再耽搁；<br/>不久那婚娶之晨临到，<br/>我们欢唱新诗歌。<br/>','',59031,12596);
INSERT INTO stanza VALUES('ZS905','2','让我们赎回每寸光阴，<br/>买更多贵重的油；<br/>当夜半呼声响起时候，<br/>全人已被主浸透。<br/>','',59032,12597);
INSERT INTO stanza VALUES('ZS905','3','哦，何等欢乐！<br/>我们豫备，<br/>等候基督来迎娶；<br/>为着这样荣耀的奖赏，<br/>痛苦试炼不介意！<br/>','',59033,12598);
INSERT INTO stanza VALUES('ZS905','4','哦，当那婚娶之日临到，<br/>将是何等大欢乐。<br/>与主一同作王一千年，<br/>饱享羔羊的婚筵。<br/>','',59034,12599);
INSERT INTO stanza VALUES('ZS906','1','恩主，我心所爱，<br/>求你快回来，<br/>与我永同在，<br/>让我紧贴你胸前，<br/>瞻仰你光荣慈颜，<br/>得以面对面吐意倾心，<br/>述说你我阔别思念。<br/>恩主，我爱你，<br/>爱主！我亲你，我恋你，<br/>犹如朝鹿慕溪，<br/>干旱久候云霓，<br/>望眼欲穿，此心欲碎，<br/>相思之苦，何日得慰，<br/>此情垂听。<br/>','',59035,12600);
INSERT INTO stanza VALUES('ZS906','2','爱主！我心所好，<br/>你是我至宝；<br/>围你魂缭绕。<br/>我真爱你，真慕你，<br/>深愿时刻在一起，<br/>形影不分离，虽在睡梦，<br/>仍然切切把你挂记。<br/>此情和此境，爱主！<br/>人间语怎表明？<br/>我心被你溶化，<br/>一切为你丢下，<br/>因宇宙间谁能比你<br/>慈爱无涯，怜悯无底？<br/>主阿！来罢！<br/>','',59036,12601);
INSERT INTO stanza VALUES('ZS906','3','荣主！我心所属，<br/>你是我良牧，<br/>有你心满足。<br/>十架上，你命捐弃，<br/>流宝血买我归你，<br/>我今把自己，一切，<br/>今后永远专一奉献作祭，<br/>主阿！快回来<br/>享受我所有和情爱，<br/>我的爱如膏倾，<br/>远超属世人情，<br/>天长地久，与你连理；<br/>海枯石烂，此志不移。<br/>心恳！阿们！<br/>','',59037,12602);
INSERT INTO stanza VALUES('ZS906','4','甜主！我心所系，<br/>恨不插双翼，<br/>飞投你怀里，<br/>多少次举目望天，<br/>等候你驾云显现；<br/>提接你面前，<br/>谁知荣影无踪，<br/>云彩依然翩翩。<br/>天哪！别留祂！<br/>看我伤心，泪哭无涯！<br/>主！你岂能安息，<br/>任我思爱成疾？<br/>爱主，你何忍再延待？<br/>无论如何，求你快来，<br/>此愿成全！<br/>','',59038,12603);
INSERT INTO stanza VALUES('ZS907','1','别了！世界，<br/>别了！世界，<br/>让这世界过去！<br/>主快来了，主快来了！<br/>我还留恋甚么？<br/>别了！安逸，<br/>别了！糜烂，<br/>别了！属地享受；<br/>别了！所有缠累重量！<br/>从此不再回头！<br/>『安逸、』『糜烂，』可以自行更改，如『钱财、』『地位、』『电视』等。<br/>','',59039,12604);
INSERT INTO stanza VALUES('ZS908','1','看！无花果树早已发枝，<br/>圣城被践踏，日期满足；<br/>哦，阿利路亚，<br/>我们真有福，<br/>要亲眼看见得赎之日！<br/>我们这一代，<br/>末了的一代，<br/>一定要把主迎接回来！<br/>','',59040,12605);
INSERT INTO stanza VALUES('ZS908','2','不要被今生思虑累住，<br/>不要像世人贪恋前途；<br/>快出所多玛，<br/>快进入方舟，<br/>天天都过着召会生活。<br/>趁这个时候，<br/>当挺身昂首，<br/>多抢救灵魂，带人得救！<br/>','',59041,12606);
INSERT INTO stanza VALUES('ZS908','3','愿主保守<br/>你的灵、魂、体，<br/>所有的聚集你都能去。<br/>也许那一次，<br/>我们正聚集，<br/>赞美到高潮，主突然到！<br/>不知不觉中，<br/>立刻就被提，<br/>唱阿利路亚，在荣耀里。<br/>','',59042,12607);
INSERT INTO stanza VALUES('ZS909','1','看哪！世上的国已成了<br/>我主基督的国！<br/>众圣欢呼因祂作王，<br/>永永远远坐宝座！<br/>千千万万立即响应，<br/>和声爆发同歌讴！<br/>基督已经得胜！<br/>','',59043,12608);
INSERT INTO stanza VALUES('ZS909','chorus','得胜！得胜！阿利路亚！<br/>得胜！得胜！阿利路亚！<br/>得胜！得胜！阿利路亚！<br/>基督已经得胜！<br/>','',59044,12609);
INSERT INTO stanza VALUES('ZS909','2','那古蛇，大龙，<br/>就是魔鬼已经被摔下去，<br/>撒但和他的使者<br/>不能再迷惑设骗局，<br/>我们颂赞之声<br/>如同雷鸣将主永高举。<br/>基督已经得胜！<br/>','',59045,12610);
INSERT INTO stanza VALUES('ZS909','3','『救恩、能力、国度，<br/>并祂基督的权柄到了！<br/>因那昼夜控告我们弟兄的<br/>已被摔倒，』<br/>如今召会正在地上<br/>执行天上的宣告，<br/>基督已经得胜！<br/>','',59046,12611);
INSERT INTO stanza VALUES('ZS909','4','我们胜过那控告者，<br/>因为宝血有功效，<br/>借着口中的话，<br/>我们宣告：<br/>『一切都成了！』<br/>我们虽至于死，<br/>魂生命也不爱惜计较。<br/>基督已经得胜！<br/>','',59047,12612);
INSERT INTO stanza VALUES('ZS909','5','哦！弟兄们，姊妹们，<br/>请听天上又发声音：<br/>『巴比伦倾倒，<br/>倾倒了！』<br/>─怎能不令人欢欣。<br/>我们已从她出来，<br/>何等有福又可庆幸！<br/>基督已经得胜！<br/>','',59048,12613);
INSERT INTO stanza VALUES('ZS909','6','奥秘大巴比伦，<br/>她乃是众淫妇的母亲，<br/>我们极其憎恶<br/>她所装满的污秽邪淫；<br/>但神已加倍罚她，<br/>因此我们灵欢欣，<br/>基督已经得胜！<br/>','',59049,12614);
INSERT INTO stanza VALUES('ZS909','7','救恩、荣耀、权能，<br/>都属我们的神，<br/>赞美主！祂凭真实公义，<br/>讨罪伸冤，审判了淫妇。<br/>看！<br/>那烧她的烟直往上冒，<br/>让我们欢呼！<br/>基督已经得胜！<br/>','',59050,12615);
INSERT INTO stanza VALUES('ZS909','7','『神的众仆，无论大小，<br/>当赞美神，』祂嘱咐；<br/>如同众水的声音，<br/>又如雷鸣，群众同欢呼：<br/>『阿利路亚！<br/>我们的神全能者<br/>作王作主！』<br/>基督已经得胜！<br/>','',59051,12616);
INSERT INTO stanza VALUES('ZS909','9','现在我们应当欢喜<br/>快乐向神归荣耀；<br/>羔羊婚娶时候到了，<br/>新妇也已豫备好，<br/>蒙了救恩穿上<br/>光明洁白的细麻义袍，<br/>基督已经得胜！<br/>','',59052,12617);
INSERT INTO stanza VALUES('ZS909','10','魔鬼身在火湖，<br/>这是约翰目睹的事实，<br/>今后不要怕他信口雌黄，<br/>或造谣生事，<br/>大胆宣告他的判辞，<br/>是圣徒得胜之路！<br/>基督已经得胜！<br/>','',59053,12618);
INSERT INTO stanza VALUES('ZS909','11','看哪！最大的奇景─<br/>新耶路撒冷由天降！<br/>基督新妇妆饰整齐<br/>模成基督的模样；<br/>神人调和建造一起<br/>显出神荣耀形像，<br/>基督已经得胜！<br/>','',59054,12619);
INSERT INTO stanza VALUES('ZS909','12','这是神在人间支搭帐幕，<br/>神人永同住，<br/>神的圣洁、荣耀，<br/>从人身上完全的显出！<br/>听哪！主在宣告：<br/>『都成了！』<br/>神已心满意足，<br/>基督已经得胜！<br/>','',59055,12620);
INSERT INTO stanza VALUES('ZS909','chorus','阿利路亚！阿利路亚！<br/>阿利路亚！阿利路亚！<br/>阿利路亚！阿利路亚！<br/>基督已经得胜！<br/>','',59056,12621);
INSERT INTO stanza VALUES('ZS910','1','我们曾顶羡慕<br/>门徒在高山上，<br/>亲眼看见你改变形像，<br/>你面貌像日头<br/>显出何等荣光，<br/>你衣裳洁白何等明亮！<br/>现在我们<br/>每当想到你快回来，<br/>我们就立刻喜乐满怀，<br/>因为在还没有<br/>尝到死味之先，<br/>同样要看见你的显现！<br/>','',59057,12622);
INSERT INTO stanza VALUES('ZS910','2','那一次门徒们<br/>看见你的改变，<br/>虽然是真好，却是有限，<br/>因为你那时候，<br/>还没有经过死，<br/>不过是父怀中的爱子。<br/>如今你再来到，<br/>要得完全荣耀；<br/>千万的圣徒，赞赏不置！<br/>你是万王之王，<br/>你是万主之主，<br/>你要与你的百姓同住。<br/>','',59058,12623);
INSERT INTO stanza VALUES('ZS910','3','主，我们赞美你，<br/>不只你得荣耀，<br/>也要把众子带进荣耀！<br/>我们原是罪人，<br/>在你眼中蒙恩，<br/>为要变成你爱的标本。<br/>我们原是泥土，<br/>竟然要变宝石，<br/>等候着在荣耀里显出。<br/>即使在永世里，<br/>我们也唱不尽，<br/>爱戴之情与感激之心！<br/>','',59059,12624);
INSERT INTO stanza VALUES('ZS911','1','时候快要到了，<br/>主要醡葡萄！<br/>吸满地汁，<br/>滴滴都要醡出！<br/>主是一无所有，<br/>如根出干地，你怎能够<br/>与『地』这么亲密？<br/>','',59060,12625);
INSERT INTO stanza VALUES('ZS911','chorus','快起来脱离『地』，<br/>快抢救自己，<br/>作初熟的果子，<br/>归神与主。<br/>','',59061,12626);
INSERT INTO stanza VALUES('ZS911','2','时候快要满足，<br/>主要收麦子！<br/>麦子要熟，<br/>需断『地』的享受；<br/>牠的里头饱满，<br/>外面却枯干；主作一切，<br/>就不需要世界。<br/>','',59062,12627);
INSERT INTO stanza VALUES('ZS911','3','作初熟的果子，<br/>是何等有福！<br/>得享婚筵，<br/>又得同掌王权！<br/>不要等待世界<br/>来把你对付，趁有今日，<br/>自动丢弃粪土。<br/>','',59063,12628);
INSERT INTO stanza VALUES('ZS912','1','我们灯里有油，<br/>灵里焚烧，<br/>我们灯里有油，今朝！<br/>主，不断使我们<br/>转到灵里，<br/>使油源源不绝，灯不熄。<br/>哦主！阿们！阿利路亚！<br/>我们昼夜焚烧，灯不熄！<br/>哦主！阿们！阿利路亚！<br/>不断转回到灵里！<br/>','',59064,12629);
INSERT INTO stanza VALUES('ZS912','2','但我们的器皿必须有油，<br/>你来时才不致蒙羞。主，<br/>浸透我们魂每一角落，<br/>好叫我们全人满了油。<br/>哦！主耶稣，充满我们，<br/>每时每刻赐下你自己！<br/>哦！主耶稣，浸透我们，<br/>使我们满了实际。<br/>','',59065,12630);
INSERT INTO stanza VALUES('ZS912','3','满了油才能够不断焚烧，<br/>直到主那一日来到。<br/>我们要与新郎一同坐席，<br/>光明灿烂欢然渡佳期。<br/>主阿，快来！<br/>主阿，快来！<br/>来看我们充满且发光；<br/>主阿，快来！<br/>主阿，快来！<br/>接你佳偶永同享！<br/>','',59066,12631);
INSERT INTO stanza VALUES('ZS913','1','十个童女迎接新郎，<br/>为何结局不一样？<br/>聪明愚拙都将灯点，<br/>器皿的油是关键。<br/>趁着今日赶紧豫备，<br/>让灵充满魂浸透；<br/>儆醒等候直到主来，<br/>可以同祂享爱筵。<br/>','',59067,12632);
INSERT INTO stanza VALUES('ZS913','2','三个仆人都有银子，<br/>为何结局不一样？<br/>因那忠仆随即买卖，<br/>恶仆却将银子埋。<br/>快将一千银子摆出，<br/>在召会里同经营；<br/>忠心事奉，直到主来，<br/>可以从祂得赏赐。<br/>','',59068,12633);
INSERT INTO stanza VALUES('ZS913','3','不多时候，要来就来，<br/>我们儆醒齐等待，<br/>不可辜负主的委派，<br/>忠心良善得赏赉。<br/>基督台前，审判钟点，<br/>主的公义威荣显，<br/>金银宝石能耐火焰，<br/>千年国度掌王权。<br/>','',59069,12634);
INSERT INTO stanza VALUES('ZS914','1','这个世代已将结束，<br/>十个童女手拿着灯，<br/>出去迎接可爱新郎，<br/>五个愚拙，五个聪明。<br/>那聪明的油是充满，<br/>那愚拙的油却将尽；<br/>及时买油才是聪明，<br/>勿成愚拙，到时饮恨。<br/>','',59070,12635);
INSERT INTO stanza VALUES('ZS914','2','主耶稣，你话够清楚，<br/>你为聪明童女而来。<br/>他们趁着今天买油，<br/>对付所有捆绑阻碍；<br/>他们的全魂已被变化，<br/>灵充满了他们全人，<br/>他们在此儆醒等候，<br/>就必得享你的婚筵。<br/>','',59071,12636);
INSERT INTO stanza VALUES('ZS914','3','灯是我灵须修明亮，<br/>借着每日呼喊你名。<br/>天天操练活在灵中，<br/>烧去所有老旧光景。<br/>哦主，求你扎根生长，<br/>扩展到我的魂里去；<br/>直到你安家在我心，<br/>油自器皿充满洋溢。<br/>','',59072,12637);
INSERT INTO stanza VALUES('ZS914','4','看！这世代何等黑暗，<br/>有福日子已经接近。<br/>我们新郎随时会来，<br/>须快豫备为那时辰。<br/>何等蒙福，得享婚筵，<br/>看见新妇与主合一！<br/>主，使我们活你面前，<br/>如同那些聪明童女！<br/>','',59073,12638);
INSERT INTO stanza VALUES('ZS915','1','一天，约在黄昏时分，<br/>亚伯拉罕的仆人，<br/>为着寻找新妇，<br/>在井旁驻足。<br/>那利百加适时而至，<br/>所行印证出乎主；<br/>仆人不虚此行，<br/>因为神赐福。<br/>','',59074,12639);
INSERT INTO stanza VALUES('ZS915','chorus','哦，快快豫备，<br/>夜幕将低垂，<br/>且听那老仆人频频催！<br/>喜事已经近在眼前，<br/>不久我们要欢祝；<br/>驼队带新妇到以撒帐幕。<br/>','',59075,12640);
INSERT INTO stanza VALUES('ZS915','2','如今圣灵受父差遣，<br/>带来基督的丰富，<br/>同样为要寻找<br/>圣洁的新妇。<br/>我们以撒在父家里，<br/>已经豫备好帐幕，<br/>巴望接利百加<br/>到他身旁住。<br/>','',59076,12641);
INSERT INTO stanza VALUES('ZS915','3','我们欣然离开亲友，<br/>向这世界说再见；<br/>我们已蒙呼召，<br/>完全归给主。<br/>不久脱尽斑点皱纹，<br/>面见我们主耶稣，<br/>何等喜乐<br/>我们是荣耀新妇！<br/>','',59077,12642);
INSERT INTO stanza VALUES('ZS1001','1','神完整的救恩<br/>是本于祂的义，<br/>并借着我们的信。<br/>凭两个神圣的迁移：<br/>从亚当里迁到基督里；<br/>并从肉体里迁到那灵里。<br/>在一个属灵的联结里：<br/>生命的灵与我们的灵，<br/>联结成为一个调和的灵。<br/>使我们借着洋溢之恩<br/>并洋溢之义的恩赐，<br/>在生命中作王。<br/>','',59078,12643);
INSERT INTO stanza VALUES('ZS1002','1','神重生我们，<br/>使我们得有<br/>祂的神圣生命；<br/>更新我们，使我们成为<br/>祂的神圣新造；<br/>圣别我们，使我们得有<br/>祂的圣别性情；<br/>变化我们，使我们得有<br/>祂的神圣形像。<br/>模成我们，使我们得有<br/>祂的神圣成分；<br/>荣化我们，使我们全有<br/>祂的神圣形像。<br/>我们凭神生机的救恩，<br/>在祂的生命中作王，<br/>成功祂永远的经纶，<br/>达到祂神圣的目的。<br/>','',59079,12644);
INSERT INTO stanza VALUES('ZS1003','1','经过过程<br/>终极完成的三一神，<br/>照着祂的心爱美意，<br/>为着祂经纶最高的目的，<br/>正将祂自己<br/>和祂所拣选的人，<br/>相互建造到彼此里面，<br/>好使祂在基督里<br/>得着神性调和<br/>人性的一个构成，<br/>作祂的生机体，<br/>就是基督的身体，<br/>成为祂永远的彰显，<br/>并救赎之神与蒙救赎之人<br/>相互的居所。<br/>这个奇妙珍宝构成的<br/>终极完成，<br/>乃是新耶路撒冷，<br/>直存到永远。<br/>注：此首诗辞编译自李常受弟兄墓前碑文。<br/>','',59080,12645);
INSERT INTO stanza VALUES('ZS1004','1','神永远的经纶，<br/>乃是要使人在生命、<br/>性情上，<br/>但不在神格上，<br/>与祂一模一样，<br/>并使祂自己与人成为一，<br/>使人与祂成为一，<br/>因而使祂在彰显上<br/>得以扩大并扩展，<br/>使祂一切神圣的属性<br/>得以彰显在人性美德里。<br/>','',59081,12646);
INSERT INTO stanza VALUES('ZS1005','1','神在宇宙中历世历代<br/>独一中心的工作，<br/>乃是要在基督里<br/>将祂自己建造到<br/>祂拣选的人里面，<br/>使祂自己与他们成为一。<br/>在神这中心的<br/>建造工作中，<br/>神将祂神圣的元素<br/>构造到人的元素里，<br/>并将人的元素<br/>构造到神的元素里。<br/>神这中心的工作<br/>有一个奇妙的过程，<br/>就是神成了人，<br/>为要使人在生命、<br/>性情上，<br/>但不在神格上成为神。<br/>神这中心工作的<br/>终极完成，<br/>乃是新耶路撒冷，<br/>就是经过过程<br/>并终极完成的三一神，<br/>与蒙祂重生、变化<br/>并荣化之三部分选民，<br/>相调和的生机构成。<br/>','',59082,12647);
INSERT INTO stanza VALUES('ZS28','1','来与我同欢唱！<br/>我心曾经匮乏,<br/>如今寻得爱的宝藏,<br/>供应丰富无差。<br/>','',59083,1);
INSERT INTO stanza VALUES('ZS28','2','来与我同欢唱！<br/>我原病弱无望,<br/>喜遇救主知我景况,<br/>并赐医治良方。<br/>','',59084,2);
INSERT INTO stanza VALUES('ZS28','3','来与我同欢唱！<br/>困倦疲惫如我,<br/>欢然投靠大能臂膀,<br/>加力、扶持无辍。<br/>','',59085,3);
INSERT INTO stanza VALUES('ZS28','4','来与我同欢唱！<br/>我原偏行己路,<br/>今由慈牧领回身旁,<br/>祂里安然居住。<br/>','',59086,4);
INSERT INTO stanza VALUES('ZS28','5','来与我同欢唱！<br/>孤独乖僻如我,<br/>竟得一友知我心肠,<br/>用爱将我紧握。<br/>','',59087,5);
INSERT INTO stanza VALUES('ZS28','6','从前未识祂爱,<br/>但祂早已爱上;<br/>这爱深厚、坚定、<br/>实在,既温柔又坚刚。<br/>','',59088,6);
INSERT INTO stanza VALUES('ZS28','7','我乐听祂慈声,<br/>引我日日向上;<br/>祂爱既是如此丰盛,<br/>我岂能不欢唱?<br/>','',59089,7);
INSERT INTO stanza VALUES('ZS29','1','历代圣徒都颂赞:<br/>“美哉,神的羔羊！<br/>舍命救人脱罪孽,<br/>将人罪债清偿。<br/>救赎大恩多人识,<br/>却鲜有人歌唱:<br/>“争战狮子已得捷,<br/>配得永远称扬！<br/>','',59090,1);
INSERT INTO stanza VALUES('ZS29','2','坐宝座者右手中,<br/>书卷七印封严;<br/>”天上、地下、地底下,<br/>谁配展开书卷?<br/>约翰以为无人配,<br/>为此痛哭掩面;<br/>奥秘若真不得启,<br/>我们能不悲叹?<br/>','',59091,2);
INSERT INTO stanza VALUES('ZS29','3','宇宙奥秘深难测,<br/>须借启示照明;<br/>神的旨意若不彰,<br/>万有都归虚空。<br/>看哪,犹大的狮子！<br/>祂已争战得胜,<br/>配展书卷揭七印,<br/>将神经纶完成。<br/>','',59092,3);
INSERT INTO stanza VALUES('ZS29','4','前在暗中无亮光,<br/>未识神心秘密;<br/>今蒙光照,心眼开,<br/>异象辉煌无比;<br/>只愿活着为神旨,<br/>此心坚定不移;<br/>“狮子羔羊”揭奥秘,<br/>我们赞美不已！<br/>','',59093,4);
INSERT INTO stanza VALUES('ZS29','5','长老、活物齐俯伏,<br/>座前敬拜歌唱;<br/>赞美昼夜不歇息,<br/>都归“狮子羔羊”<br/>我们和声同响应,<br/>高声欢呼颂扬:<br/>神圣计画已显明,<br/>赞美“狮子羔羊”！<br/>','',59094,5);
INSERT INTO stanza VALUES('ZS30','1','耶和华对我主说,<br/>“你坐在我右边,<br/>等我使你众仇敌<br/>作脚凳伏你前。”<br/>耶和华必从锡安<br/>伸出你大能仗:<br/>列国必归你管治,<br/>直到永世无疆。<br/>','',59095,1);
INSERT INTO stanza VALUES('ZS30','2','当你争战的日子,<br/>你民献上自己;<br/>甘心奉献为彩饰,<br/>荣美有何能比！<br/>畅爽、滋润如甘露,<br/>新鲜,孕于清晨,<br/>少年人分别归你,<br/>于你如宝如珍。<br/>','',59096,2);
INSERT INTO stanza VALUES('ZS30','3','耶和华必不后悔,<br/>祂已明确起誓:<br/>“照麦基洗德等次,<br/>你必永为祭司。<br/>你既无时日之始,<br/>也无生命之终;<br/>凭你代求供圣职,<br/>我们受恩无穷。<br/>','',59097,3);
INSERT INTO stanza VALUES('ZS30','4','在神右边你是主,<br/>列邦受你审判;<br/>当你发怒伤列王,<br/>敌权尽都溃散。<br/>路旁河水供你饮,<br/>你必抬头胜敌;<br/>我们如此解你渴,<br/>同你收复全地。<br/>','',59098,4);
INSERT INTO stanza VALUES('ZS30','5','哦主,你已升高天,<br/>登极安坐神右;<br/>神已使你将敌剿,<br/>万有之上居首。<br/>你是君王施权柄,<br/>又是祭司代求,<br/>且是荣耀得胜者,<br/>配得我们所有。<br/>','',59099,5);
INSERT INTO stanza VALUES('ZS31','1','哦主,你是平安祭,<br/>我们按手于你;<br/>你的事实我经历,<br/>因为你我是一。<br/>众圣欢聚会幕里,<br/>以你向神献祭;<br/>同父吃喝享受你,<br/>丰富有何能比。<br/>','',59100,1);
INSERT INTO stanza VALUES('ZS31','chorus','赞美基督是平安祭,<br/>使神与人满意;<br/>距离全去,交通甜蜜,<br/>平安永远坚立！<br/>','',59101,2);
INSERT INTO stanza VALUES('ZS31','2','血洒于坛何有能,<br/>神圣平安得成;<br/>宝血功效永坚定,<br/>神前我享安宁。<br/>我们放胆齐颂称<br/>“和平借血己成！”<br/>仇敌闻之惊又恐,<br/>我们昂然夸胜。<br/>','',59102,3);
INSERT INTO stanza VALUES('ZS31','3','燔祭馨香使神喜,<br/>素祭叫人满意,<br/>据此再献平安祭─<br/>全是基督自己。<br/>救主人性何柔细,<br/>我们吃喝不已;<br/>如此享受真可喜,<br/>每逢我们聚集。<br/>','',59103,4);
INSERT INTO stanza VALUES('ZS31','chorus','交通何美筵席何富,<br/>神人同得饱足！<br/>喜乐盈盈,平安处处,<br/>圣民怎不欢呼！<br/>','',59104,5);
INSERT INTO stanza VALUES('ZS31','4','内脏、脂油最甘美,<br/>当先归神回味;<br/>摇祭的胸何宝贝,<br/>全体祭司受惠;<br/>无酵饼同举祭腿,<br/>纯全有能宝贵,<br/>供职祭司受无愧,<br/>福分拔尖全备。<br/>','',59105,6);
INSERT INTO stanza VALUES('ZS31','chorus','赞美基督是平安祭,<br/>使神与人满足！<br/>喜乐盈盈,平安处处,<br/>圣民怎不欢呼！<br/>','',59106,7);
INSERT INTO stanza VALUES('ZS31','5','胸作摇祭何丰富,<br/>豫表复活基督,<br/>以爱围绕且照护,<br/>使我超越脱俗。<br/>腿作举祭何充足,<br/>描绘升天救主,<br/>使我有能历世途,<br/>活出他命无误。<br/>','',59107,8);
INSERT INTO stanza VALUES('ZS31','6','得洁众圣聚一堂,<br/>基督爱筵饱尝;<br/>如此享受真无双,<br/>带来交通无量。<br/>心存感恩来歌唱,<br/>因主恩典深广;<br/>为使主旨得显彰,<br/>愿将全人献上。<br/>','',59108,10);
INSERT INTO stanza VALUES('ZS32','1','基督在地生活超凡且佳美,<br/>祂是神、人调和,价值何宝贵;<br/>态度、拣选、喜悦全与神相合─<br/>惟祂是那配住神的帐幕者。<br/>','',59109,1);
INSERT INTO stanza VALUES('ZS32','2','“神,求你保守我,因我投靠你”─<br/>无论起何风暴,祂安居神里。<br/>“你是我主我神,我一切好处”─<br/>惟神是祂心中朝夕所思慕。<br/>','',59110,2);
INSERT INTO stanza VALUES('ZS32','3','“论到地上圣民,尊高又可悦,”<br/>属神子民祂心最喜爱、关切,<br/>祂亲临地服事且照护殷殷,<br/>如四福音书中所记述显明。<br/>','',59111,3);
INSERT INTO stanza VALUES('ZS32','4','“神外别有拣选,愁苦必加增”─<br/>耶稣在地生活与偶像无分。<br/>神外任何名号一概都不题,<br/>祂的追求、想望全是神自己。<br/>','',59112,4);
INSERT INTO stanza VALUES('ZS32','5','“惟你是我产业,是我杯中分”─<br/>祂在一切事上只拣选父神。<br/>“那指教我的神,我昼夜称颂”─<br/>祂己全然弃绝,只活出神命。<br/>','',59113,5);
INSERT INTO stanza VALUES('ZS32','6','因此祂心喜乐,祂灵也欢腾,<br/>甚至被置死地仍能赞美神;<br/>神必不将祂魂撇弃在阴间,<br/>祂的肉身安居,复活显神前。<br/>','',59114,6);
INSERT INTO stanza VALUES('ZS32','7','神已使祂复起,赐祂荣耀冕,<br/>祂在神前所得喜乐何丰满。<br/>高升远超万有,父右边安坐,<br/>享受无穷无尽无终的福乐。<br/>','',59115,7);
INSERT INTO stanza VALUES('ZS33','1','主耶和华永是我牧者，<br/>使我躺卧，令我喜乐；<br/>祂领我在可安歇水边，<br/>何等满足，何等甘甜！<br/>','',59116,1);
INSERT INTO stanza VALUES('ZS33','chorus','我一生一世必有恩惠慈爱随着我，<br/>必有恩惠慈爱随着我。<br/>我一生一世必有恩惠慈爱随着我，<br/>必有恩惠慈爱随着我。<br/>我且要住在神的殿中，直到永远，<br/>享受祂为我摆设的筵席。<br/>我一生一世必有恩惠慈爱随着我，<br/>必有恩惠慈爱随着我。<br/>','',59117,2);
INSERT INTO stanza VALUES('ZS33','2','我的牧者是我青草地，<br/>也是流水 使我安息；<br/>我在灵中享受祂丰富，<br/>吃喝祂哦！何等蒙福！<br/>','',59118,3);
INSERT INTO stanza VALUES('ZS33','3','我的牧者使我魂苏醒，<br/>行走义路，随祂引领；<br/>我虽行过死荫的幽谷，<br/>有祂同在，我能安渡。<br/>','',59119,4);
INSERT INTO stanza VALUES('ZS33','4','祂在敌前为我设筵席，<br/>在筵席间 击败仇敌，<br/>丰厚膏油祂抹我头上，<br/>我的福杯 满溢流淌。<br/>','',59120,5);
INSERT INTO stanza VALUES('ZS33','5','我今安住在我神殿里，<br/>享受神的 美善不已；<br/>我的喜乐非口舌能述，<br/>因主自己 是我满足。<br/>','',59121,6);
INSERT INTO stanza VALUES('ZS34','1','来向基督赞美歌颂,<br/>神使救恩借祂成功;<br/>得救惟靠神圣生命,<br/>律法规条一无所成;<br/>人虽努力不能得胜,<br/>神圣生命才有大能;<br/>将人改变带来重生。<br/>','',59122,1);
INSERT INTO stanza VALUES('ZS34','2','借祂赐下生命能力,<br/>祂将信徒整救到底;<br/>神圣生命注入人里,<br/>供应救恩时刻不息;<br/>人虽失丧祂来临及,<br/>拯救罪人脱离仇敌;<br/>带领众子进荣耀里。<br/>','',59123,2);
INSERT INTO stanza VALUES('ZS34','3','祂是祭司为神所立,<br/>赐人生命带来实际;<br/>神的生命就在祂里,<br/>拯救世人脱罪胜己;<br/>永远生命不朽不已,<br/>所施救恩全备无比;<br/>赞美我主完全能力。<br/>','',59124,3);
INSERT INTO stanza VALUES('ZS34','4','祂的生命足能担保,<br/>带领我们达到荣耀;<br/>若非祂曾得胜宣告,<br/>我们有何可以信靠。<br/>祂受试验屹立不摇,<br/>终于十架始于马槽;<br/>不受死亡阴间缠绕。<br/>','',59125,4);
INSERT INTO stanza VALUES('ZS34','5','祂作凭质供人接受,<br/>担保信徒完全得救;<br/>全备供应包罗万有,<br/>亲自成全终能成就;<br/>属人生命失败、老旧,<br/>惟祂生命坚定永久;<br/>祂作生命完全拯救。<br/>','',59126,5);
INSERT INTO stanza VALUES('ZS34','6','基督今日高过诸天,<br/>忠信代求直到永远;<br/>不受輭弱、死亡阻拦,<br/>祭司职分无需更换;<br/>长远活着,立于神前,<br/>代求满足神、人心愿;<br/>祂已高升远超诸天。<br/>','',59127,6);
INSERT INTO stanza VALUES('ZS34','7','来到神前,靠主宝血,<br/>绝不退缩而遭毁坏;<br/>来到神前,得着生命,<br/>各尽功用不作婴孩;<br/>来到神前,享受生命,<br/>作祂子民,蒙祂所爱;<br/>生命作王,死亡不在。<br/>','',59128,7);
INSERT INTO stanza VALUES('ZS35','1','万军之耶和华阿,<br/>你的居所何等可爱！<br/>住在你殿中真有福;<br/>他们仍要赞美你。<br/>因你有力量,心中想往<br/>锡安大道,便为有福。<br/>流泪谷变泉源之地;<br/>秋雨之福,盖满这谷。<br/>行走力上加力,<br/>到锡安朝见我主神。<br/>求你垂顾我们盾牌;<br/>观看受膏者面。<br/>在你的院宇住一日,<br/>胜似在别处住千日;<br/>愿常在你殿享受你<br/>所赐恩典和荣耀。<br/>','',59129,1);
INSERT INTO stanza VALUES('ZS36','1','你将我们的罪孽摆在你面前,<br/>将我们隐藏的罪摆在你面光之中。<br/>我们经过的日子,都在你盛怒之中;<br/>我们度尽的年岁,好像一声叹息。<br/>我们一生的年日是七十岁,<br/>若是强壮可到八十岁;<br/>但其中所矜夸不过是劳苦愁烦,<br/>转眼成空,我们便如飞而去。<br/>求你指教我们怎样数算自己的日子,<br/>好叫我们得着智慧的心,得着智慧的心。<br/>求你使我们在早晨饱得你的慈爱,<br/>好叫我们一生欢呼喜乐,一生欢呼喜乐！<br/>求你照着你使我们受苦的日子,<br/>照着我们遭难的年岁,<br/>叫我们喜乐,叫我们喜乐。<br/>','',59130,1);
INSERT INTO stanza VALUES('ZS37','1','当向万有之主高声来颂扬;<br/>祂作为奇妙,当传布四方;<br/>诸天是祂座位,祂竟临地上,<br/>与百姓同住,在撒冷为王。<br/>从锡安而出,救恩何深广;<br/>被掳者归回,怎能不欢唱?<br/>当喜乐欢腾,唱祂恩无量！<br/>当喜乐欢腾,唱祂恩无量！<br/>','',59131,1);
INSERT INTO stanza VALUES('ZS37','2','圣城为祂居所,圣民同欢唱;<br/>主名何尊大,全地当称扬;<br/>赞美为祂宝座,欢呼应明朗;<br/>祂独爱锡安,倾福于其上。<br/>在地方召会,神行动刚强;<br/>享祂作永分,满足又欢畅;<br/>产业何丰富,我们竟得享！<br/>产业何丰富,我们竟得享！<br/>','',59132,2);
INSERT INTO stanza VALUES('ZS37','3','谁能登上圣山,国权来执掌?<br/>谁能住圣所,使神家彰显?<br/>必须手洁心清,寻求主面光,<br/>迎接祂进来,居衷作君王。<br/>让我们抬头,寻求主面光,<br/>向荣耀君王,心门全开放;<br/>让基督进来,居衷永作王;<br/>让基督进来,居衷永作王。<br/>','',59133,3);
INSERT INTO stanza VALUES('ZS37','4','看哪神的帐幕降临在地上;<br/>哦以马内利！”众圣齐欢唱。<br/>一切都已完成,神人永同享;<br/>基督与召会─美妙的诗章！<br/>众城要抬头,注目主荣光！<br/>门户要举起,迎祂来作王！<br/>赞美荣耀王,欢呼声要强！<br/>赞美荣耀王,欢呼声要强！<br/>','',59134,4);
INSERT INTO stanza VALUES('ZS138','1','“我必叫雨按时落下;<br/>那必是赐福的雨”─<br/>立约的神坚定应许,<br/>借主救赎而赐与。<br/>','',59135,1);
INSERT INTO stanza VALUES('ZS138','chorus','哦,赐福的雨,<br/>我们同心所渴求;<br/>处处滴落尽是怜悯,<br/>哦求恩雨来浇透。<br/>','',59136,2);
INSERT INTO stanza VALUES('ZS138','2','赐福的雨必然降临,<br/>带来生命的复兴;<br/>宝贵甘霖滋润大地,<br/>山谷中沛雨充盈。<br/>','',59137,3);
INSERT INTO stanza VALUES('ZS138','3','赐福的雨必然降临,<br/>因主应许不落空;<br/>主命这雨按时落下,<br/>使我们不感力穷！<br/>','',59138,4);
INSERT INTO stanza VALUES('ZS138','4','赐福的雨必然降临,<br/>愿主应许今成就;<br/>主必向祂子民仰脸,<br/>当我们同心呼求。<br/>','',59139,5);
INSERT INTO stanza VALUES('ZS138','5','赐福的雨必然降临,<br/>若人肯相信顺从;<br/>舒爽时期就要来到,<br/>若人愿让神流通。<br/>','',59140,6);
INSERT INTO stanza VALUES('ZS139','1','没药与香肉桂,香菖蒲与桂皮─<br/>你成分何包罗,耶稣我主！<br/>橄榄油中相调,分量完整奇妙─<br/>宝贵膏油涂抹,供应丰富！<br/>香料加上油,四调和于一,<br/>终成复合之灵;<br/>基督之 死甜美, 基督复活馨香,<br/>复合成为膏油,流进我灵！<br/>','',59141,1);
INSERT INTO stanza VALUES('ZS139','2','苏合香与香螺,白松香与乳香─<br/>你成分何包罗,耶稣我主！<br/>生命产生众子,救赎使罪脱落,<br/>驱逐死亡鬼魔,功效全足！<br/>分量各相等,复活里调和,<br/>加盐制成香物;<br/>捣细置 于柜前, 供神圣火焚烧,<br/>至纯至圣之香,耶稣我主！<br/>','',59142,2);
INSERT INTO stanza VALUES('ZS139','3','膏油是为我们,馨香完全为神,<br/>人神同享基督,荣耀丰富！<br/>膏油流至我们,带来福分全备,<br/>馨香升达宝座,使神满足！<br/>先涂抹膏油,后焚烧馨香,<br/>如此经历基督;<br/>祷告赞 美高举, 出自我们经历,<br/>珍贵蒙神悦纳─全是基督！<br/>','',59143,3);
INSERT INTO stanza VALUES('ZS140','1','出于圣灵,由灵而生─<br/>神人耶稣何神圣;<br/>充满那灵,全是那灵─<br/>祂的素质就是灵。<br/>死而复活,成为那灵,<br/>如今主就是那灵;<br/>是灵在灵、凭灵眷临,<br/>我们与祂成一灵。<br/>','',59144,1);
INSERT INTO stanza VALUES('ZS140','2','我们受浸归入圣灵,<br/>浸于灵中,饮于灵;<br/>召会全然出于那灵,<br/>宗教、规条尽除摒。<br/>活在灵里,照灵而行,<br/>信条、仪文勿倚凭;<br/>召会实际全在于灵,<br/>故当操练活灵中。<br/>','',59145,2);
INSERT INTO stanza VALUES('ZS140','3','在此所享神圣交通,<br/>乃是那灵的交通;<br/>我们所顾惟有那灵,<br/>此外无何可依从。<br/>那灵今已加强七倍,<br/>神圣经纶来完成;<br/>众召会中,那灵发声,<br/>凡有耳者当聆听。<br/>','',59146,3);
INSERT INTO stanza VALUES('ZS140','4','来罢！那灵、新妇呼召:<br/>“生命活水可白喝！”<br/>召会那灵发声如一─<br/>终极、完满的联合。<br/>今日务要实际操练,<br/>“照灵而行”为原则;<br/>众召会中惟有那灵,<br/>是主恢复的独特。<br/>','',59147,4);
INSERT INTO stanza VALUES('ZS141','1','神在基督耶稣里成那灵，<br/>流入我们灵里作生命；<br/>何等的享受，三一奇妙人位，<br/>来作生命全足又全丰。<br/>','',59148,1);
INSERT INTO stanza VALUES('ZS141','2','祂是活神，我们向祂敞开，<br/>由祂所生，经历何实在；<br/>美妙的重生！神将我们充满，<br/>借祂生命不断流进来。<br/>','',59149,2);
INSERT INTO stanza VALUES('ZS141','3','祂是活灵住在我们灵里，<br/>向外涌流，分赐祂自己；<br/>在我们心间，祂正扩展不已，<br/>逐步变化，成就祂美意。<br/>','',59150,3);
INSERT INTO stanza VALUES('ZS141','4','哦，让我们配合里面的主，<br/>目标专一，只思念基督；<br/>时刻转向祂，离弃打岔事物，<br/>除祂以外，心别无所属。<br/>','',59151,4);
INSERT INTO stanza VALUES('ZS141','5','我们不仅灵中将主盛装，<br/>更要让祂定旨得开广；<br/>丢弃老观念，不再心思流荡，<br/>生命平安我们可得享。<br/>','',59152,5);
INSERT INTO stanza VALUES('ZS141','6','哦主，得着我们每一思想，<br/>在你话中不断得滋养；<br/>借你话供应，心思常置于灵，<br/>就得圣别，模成你形像。<br/>','',59153,6);
INSERT INTO stanza VALUES('ZS141','7','我们同来经历生命之神，<br/>思念那灵，操练当认真；<br/>何等的实际！凭祂而活有路！<br/>主，我们心与你永不分。<br/>','',59154,7);
INSERT INTO stanza VALUES('ZS142','1','我神乃是澎湃水流,<br/>历世历代涌流不休;<br/>种种过程祂已尽历,<br/>为要流进卑微人里。<br/>独一、不变活神,为要作人永分,<br/>祂竟亲临人间,历经多方变迁,<br/>现今涌流我们里面！<br/>','',59155,1);
INSERT INTO stanza VALUES('ZS142','2','在那起初乐园之中<br/>神已流出,满带丰盛;<br/>祂是水河,又是果树,<br/>分赐生命,作人永福。<br/>这河涌流不息,直至永世无已;<br/>神在羔羊里流,树果供应丰厚,<br/>神圣分赐无尽、悠久！<br/>','',59156,2);
INSERT INTO stanza VALUES('ZS142','3','看哪那人耶稣基督,<br/>是神流出与人同处;<br/>为人舍命,成功救赎,<br/>为将神圣生命释出。<br/>撒但诡计多端,要将水流阻断;<br/>岂知祂钉十架,兵丁扎祂肋下,<br/>不过引出血、水无价！<br/>','',59157,3);
INSERT INTO stanza VALUES('ZS142','4','哦,血与水从祂而出,<br/>救恩泉源涌流不住;<br/>宝血洗罪永远有能,<br/>生命之水使人重生。<br/>如今那灵流通─是神流入人中;<br/>仇敌伎俩依旧;不过助长水流,<br/>我神涌流无止、无休！<br/>','',59158,4);
INSERT INTO stanza VALUES('ZS143','1','看哪,暴风刮自北方,力无穷;<br/>来吹动！来吹动！<br/>是神眷临使人翻转得复兴;<br/>来吹动！来吹动！<br/>','',59159,1);
INSERT INTO stanza VALUES('ZS143','chorus','来吹动！圣灵强风吹动,<br/>使我悔改得生命！<br/>来吹动！恩典大风吹动,<br/>使我主里得复兴！<br/>','',59160,2);
INSERT INTO stanza VALUES('ZS143','2','看哪,还有一朵大云随风到;<br/>来覆罩！来覆罩！<br/>主同在如云满足所有需要;<br/>来覆罩！来覆罩！<br/>','',59161,3);
INSERT INTO stanza VALUES('ZS143','chorus','来覆罩！神来与人相交,<br/>覆庇、加力又照料！<br/>来覆罩！神恩如云围绕,<br/>带来安慰和荣耀！<br/>','',59162,4);
INSERT INTO stanza VALUES('ZS143','3','云中又有烈火不断的闪烁;<br/>来焚烧！来焚烧！<br/>罪肉体魂生命再无处可躲;<br/>来焚烧！来焚烧！<br/>','',59163,5);
INSERT INTO stanza VALUES('ZS143','chorus','来焚烧！神圣嫉妒烈火<br/>烧遍全人每角落！<br/>来焚烧！神外一切尽脱,<br/>天然、旧造都灭没！<br/>','',59164,6);
INSERT INTO stanza VALUES('ZS143','4','火中发出金银合金显光耀;<br/>在显耀！在显耀！<br/>救赎之神经历宝贵又高超;<br/>在显耀！在显耀！<br/>','',59165,7);
INSERT INTO stanza VALUES('ZS143','chorus','在显耀！我们今已尝到<br/>羔羊神丰美味道！<br/>在显耀！救赎之神荣耀,<br/>彰显于人何奇妙！<br/>','',59166,8);
INSERT INTO stanza VALUES('ZS143','5','风云、火金的经历将人点活;<br/>多又多！多又多！<br/>愿这循环将我重构永不辍;<br/>多又多！多又多！<br/>','',59167,9);
INSERT INTO stanza VALUES('ZS143','chorus','风吹到！云覆罩！火焚烧！<br/>金银合金显荣耀！<br/>愿与主如此全然相调,<br/>使主荣形得显照！<br/>','',59168,10);
INSERT INTO stanza VALUES('ZS144','1','你若要脱离天然与自己,<br/>阿们生命之律！<br/>让这律自动运行在你里,<br/>阿们生命之律！<br/>阿们生命之律！阿们生命之律！<br/>如此被变化,与主像无异,<br/>阿们生命之律！<br/>','',59169,1);
INSERT INTO stanza VALUES('ZS144','2','这律是出自神圣的生命,<br/>阿们生命之律！<br/>凭生命大能自然的运行,<br/>阿们生命之律！<br/>阿们生命之律！阿们生命之律！<br/>生命是凭倚,挣扎可全停,<br/>阿们生命之律！<br/>','',59170,2);
INSERT INTO stanza VALUES('ZS144','3','生命之律能成全神心意,<br/>阿们生命之律！<br/>切勿凭己力改良你自己,<br/>阿们生命之律！<br/>阿们生命之律！阿们生命之律！<br/>主我愿配合,成就你所期,<br/>阿们生命之律！<br/>','',59171,3);
INSERT INTO stanza VALUES('ZS144','4','生命律带来生机的变化,<br/>阿们生命之律！<br/>将我们构成身体主所夸,<br/>阿们生命之律！<br/>阿们生命之律！阿们生命之律！<br/>旧人渐消减,神生命添加,<br/>阿们生命之律！<br/>','',59172,4);
INSERT INTO stanza VALUES('ZS144','5','这律将基督铭刻在我心,<br/>阿们生命之律！<br/>直至祂充满内里各部分,<br/>阿们生命之律！<br/>阿们生命之律！阿们生命之律！<br/>让基督成形,非外在教训,<br/>阿们生命之律！<br/>','',59173,5);
INSERT INTO stanza VALUES('ZS145','1','基督要从我灵深处<br/>向外扩展并征服─<br/>心思、情感、意志各部,<br/>尽都充满祂丰富。<br/>基督作王,悖逆全除,<br/>黑暗尽去,光显露;<br/>生命吞灭死亡、阴府,<br/>撒但国度再无处。<br/>这是得胜主的恢复,<br/>上好！我们齐欢呼！<br/>当将主权完全归主,<br/>直至国度全显出。<br/>','',59174,1);
INSERT INTO stanza VALUES('ZS146','1','哦主你在复活里,<br/>已成赐生命之灵;<br/>使我与你同复起,<br/>使我重生得生命。<br/>','',59175,1);
INSERT INTO stanza VALUES('ZS146','2','这灵就是你进入,<br/>带着丰盛的生命;<br/>包罗万有的丰富,<br/>作我全备的供应。<br/>','',59176,2);
INSERT INTO stanza VALUES('ZS146','3','如今这灵已内住,<br/>在你无数肢体里;<br/>我们与你得联属,<br/>我们活着就是你。<br/>','',59177,3);
INSERT INTO stanza VALUES('ZS146','4','凭灵全备的供应,<br/>我们将你来活出;<br/>成为你的活见证,<br/>成为团体的基督。<br/>','',59178,4);
INSERT INTO stanza VALUES('ZS146','5','借着你灵的率领,<br/>见证向外能普及;<br/>我们是你见证人,<br/>将你传扬到地极。<br/>','',59179,5);
INSERT INTO stanza VALUES('ZS146','6','如此扩展这见证,<br/>达到终极的完成;<br/>乃是新耶路撒冷,<br/>永远丰满无止境。<br/>','',59180,6);
INSERT INTO stanza VALUES('ZS147','1','我神如今你已成那灵,<br/>借你话语实化我灵里;<br/>运用我灵来接触你话,<br/>话中之灵我就能经历。<br/>','',59181,1);
INSERT INTO stanza VALUES('ZS147','chorus','主阿！你话离我并不远,<br/>在我口里也在我心里,<br/>你灵借话来作你实际,<br/>你我联调合并永为一。<br/>','',59182,2);
INSERT INTO stanza VALUES('ZS147','2','你之所是及一切属性,<br/>全都具体实化基督里;<br/>我享你灵、你话、你自己,<br/>经历中作我爱光圣义。<br/>','',59183,3);
INSERT INTO stanza VALUES('ZS147','3','住你话里就是住你里,<br/>我在爱里借话享受你;<br/>你住我里与我成为一,<br/>我活出你,彰显你秘密。<br/>','',59184,4);
INSERT INTO stanza VALUES('ZS148','1','子同着父并凭着灵而来,<br/>哦这是何等奥秘！<br/>神格一切的丰满都有形<br/>有体住在祂里。<br/>','',59185,1);
INSERT INTO stanza VALUES('ZS148','chorus','子同着父,<br/>祂何等奇妙！<br/>子凭着灵,<br/>祂何等高超！<br/>耶稣基督至宝,<br/>三一何深奥,<br/>三一神何奇妙！<br/>','',59186,2);
INSERT INTO stanza VALUES('ZS148','2','子同着父并凭着灵而来,<br/>由童女怀孕所生;<br/>耶稣基督奇妙的神人,<br/>在他,神、人成一身。<br/>','',59187,3);
INSERT INTO stanza VALUES('ZS148','3','祂的生活将父完全彰显,<br/>是人却凭神生命;<br/>祂是神无罪羔羊,<br/>罪、世界、撒但不能得逞。<br/>','',59188,4);
INSERT INTO stanza VALUES('ZS148','chorus','在人性里,<br/>来救赎洗净;<br/>在神性里,<br/>作救恩保证。<br/>祂血将我洗净,<br/>祂又作保证─<br/>神今是我保证。<br/>','',59189,5);
INSERT INTO stanza VALUES('ZS148','4','祂虽无罪却有分血肉之体,<br/>这使撒但中计;<br/>肉体罪撒但<br/>与祂同钉一起,<br/>哦何等清理！<br/>','',59190,6);
INSERT INTO stanza VALUES('ZS148','chorus','祂已了结<br/>旧造众仇敌！<br/>祂已废掉<br/>罪、撒但、肉体！<br/>哦应许的后裔,<br/>祂毁坏古蛇,<br/>胜过魔鬼诡计。<br/>','',59191,7);
INSERT INTO stanza VALUES('ZS148','5','在基督的复活里,<br/>这位奇妙三一成为那灵;<br/>如今三一之神己成那灵,<br/>作祂终极完成。<br/>','',59192,8);
INSERT INTO stanza VALUES('ZS148','chorus','何亲何近,<br/>赐生命的灵！<br/>三一之神<br/>己终极完成。<br/>子与父是一灵,<br/>祂成为那灵,<br/>今内住于我灵。<br/>','',59193,9);
INSERT INTO stanza VALUES('ZS148','6','这奇妙人子在升天里,<br/>仍是一人在神右边;<br/>神已将人子升高至极,<br/>使祂作王并掌权。<br/>','',59194,10);
INSERT INTO stanza VALUES('ZS148','chorus','万主之主,<br/>是王中之王;<br/>基督耶稣,<br/>远超万名上;<br/>祂登宝座为王,<br/>至高宝座上,<br/>得荣人子为王。<br/>','',59195,11);
INSERT INTO stanza VALUES('ZS148','7','经过种种过程,主今已登<br/>宝座,万有祂治理;<br/>作生命之灵分赐给人,<br/>接受产生祂身体。<br/>','',59196,12);
INSERT INTO stanza VALUES('ZS148','chorus','神是三一,<br/>不是为道理;<br/>神是三一,<br/>分赐祂自己。<br/>分赐永不停息,<br/>我们可经历,<br/>尽享祂的自己。<br/>','',59197,13);
INSERT INTO stanza VALUES('ZS149','1','在创世之前,神就豫定了我们,<br/>按祂所喜悦,来得儿子的名分;<br/>及至时候满足,神就差出祂儿子,<br/>由女子所生,为赎我们竟受死;<br/>并且神又差出祂儿子的灵,<br/>带来生机救恩,进入我们的心。<br/>','',59198,1);
INSERT INTO stanza VALUES('ZS149','chorus','何其甜美而亲密,<br/>同灵呼叫阿爸,父！<br/>真实主观的经历<br/>儿子名分的丰富。<br/>','',59199,2);
INSERT INTO stanza VALUES('ZS150','1','灵里贫穷的人有福了,<br/>因为诸天的国是他们的。<br/>哀恸的人有福了,<br/>因为他们必得安慰。<br/>温柔的人有福了,<br/>因为他们必承受地土。<br/>饥渴慕义的人有福了,<br/>因为他们必得饱足。<br/>怜悯人的人有福了,<br/>因为他们必蒙怜悯。<br/>清心的人有福了,<br/>因为他们必看见神。<br/>制造和平的人有福了,<br/>因为他们必称为神的儿子。<br/>为义受逼迫的人有福了,<br/>因为诸天的国是他们的。<br/>','',59200,1);
INSERT INTO stanza VALUES('ZS248','1','兴起！我魂,兴起！<br/>摆脱惧怕蒙蔽;<br/>救主流血作祭,<br/>神前我蒙称义。<br/>宝座之前担保确立,<br/>我得安稳在神手里,<br/>我得安稳在神手里。<br/>','',59201,1);
INSERT INTO stanza VALUES('ZS248','2','救主活到永久,<br/>在天为我代求;<br/>祂爱赎回万有,<br/>祂血满足要求;<br/>为救万族、万民而流,<br/>施恩座前功效不朽,<br/>施恩座前功效不朽。<br/>','',59202,2);
INSERT INTO stanza VALUES('ZS248','3','加略十字架上,<br/>手足、肋旁受创;<br/>祂行父旨不忘,<br/>代求,将罪担当;<br/>宽容、赦免无知顶撞,<br/>蒙赎罪人免去死亡,<br/>蒙赎罪人免去死亡。<br/>','',59203,3);
INSERT INTO stanza VALUES('ZS248','4','祷告蒙父垂听,<br/>受膏基督高升;<br/>救赎大功完成,<br/>父来称许、印证;<br/>祂灵应允宝血之声,<br/>宣告我已由神而生,<br/>宣告我已由神而生。<br/>','',59204,4);
INSERT INTO stanza VALUES('ZS248','5','我今与神和好,<br/>知祂赦免、宽饶;<br/>儿女将父倚靠,<br/>忧虑不再搅扰;<br/>凭信坦然进前宣告:<br/>阿爸,父阿,与你和好,<br/>阿爸,父阿,与你和好。<br/>','',59205,5);
INSERT INTO stanza VALUES('ZS249','1','一切变迁中有一位,<br/>永远屹立不朽;<br/>惟祂昔是、今是、永是,<br/>包罗万有,永久！<br/>这是基督─永久磐石,<br/>哦,祂是首先,<br/>祂也是末后。<br/>','',59206,1);
INSERT INTO stanza VALUES('ZS249','chorus','耶稣是首先,<br/>耶稣是末后,<br/>已往交祂担去,<br/>将来祂保守;<br/>耶稣是首先,<br/>耶稣是末后,<br/>基督-永久磐石,<br/>首先与末后。<br/>','',59207,2);
INSERT INTO stanza VALUES('ZS249','2','这位用祂大能膀臂,<br/>托住宇宙万有,<br/>但祂向人敞开胸臆,<br/>要人向祂倚投;<br/>忧疑尽可带来归祂,<br/>因祂是首先,<br/>祂也是末后。<br/>','',59208,3);
INSERT INTO stanza VALUES('ZS249','3','惊涛骇浪不过证明:<br/>祂爱永无尽头;<br/>直到所有风波过去,<br/>祂手仍必保守;<br/>信靠耶稣绝不蒙羞,<br/>因祂是首先,<br/>祂也是末后。<br/>','',59209,4);
INSERT INTO stanza VALUES('ZS249','4','我们加冠至爱基督,<br/>祂是首先、末后。<br/>万主之主,你脚凳前,<br/>冠冕都当倾投。<br/>那日快临,万有拜叩:<br/>惟你是首先,<br/>你也是末后。<br/>','',59210,5);
INSERT INTO stanza VALUES('ZS250','1','我已寻得一生命泉源,<br/>清新活泉流自高天;<br/>脱开属地挣扎与纠缠,<br/>欢然饮于“以琳”爱泉。<br/>何等神圣属天的活泉,<br/>在我深处涌流不断;<br/>带来喜乐满足时加添,<br/>无人话语能以尽言。<br/>','',59211,1);
INSERT INTO stanza VALUES('ZS250','chorus','请来畅饮于活水泉源,<br/>无须代价只要你愿;<br/>活水供应甘甜丰富无限,<br/>因主自己就是这泉。<br/>','',59212,2);
INSERT INTO stanza VALUES('ZS250','2','我今投靠于洗罪泉源,<br/>洗净一切污秽罪愆;<br/>借主宝血我罪得赦免,<br/>洁白如雪立于神前。<br/>蒙神称义非凭我优点,<br/>乃因基督活我里面;<br/>属天性情我取用无间,<br/>在祂里面我得完全。<br/>','',59213,3);
INSERT INTO stanza VALUES('ZS250','3','恩主也是我医治泉源,<br/>作我秘诀供应无限;<br/>远超人智慧所及所见,<br/>也非财富可以兑现。<br/>这医治活泉神圣完全,<br/>流自救主被刺肋边;<br/>祂受鞭伤使我得康健,<br/>又来安家在我心间。<br/>','',59214,4);
INSERT INTO stanza VALUES('ZS250','4','我爱畅饮于喜乐泉源,<br/>作我力量溢我心田;<br/>主是我日光辉煌灿烂,<br/>我的欢欣在祂里面。<br/>草木荣华转眼即凋残,<br/>人间宴乐短似云烟;<br/>主作我喜乐从未消减,<br/>以神为乐在地如天。<br/>','',59215,5);
INSERT INTO stanza VALUES('ZS251','1','在圣经开始,神已经启示,<br/>人是按着祂形像造成;<br/>为要彰显祂,并且代表祂,<br/>征服全地带进祂权能。<br/>','',59216,1);
INSERT INTO stanza VALUES('ZS251','chorus','形像,形像─<br/>人是按着神形像造成;<br/>形像,形像─<br/>征服全地带进祂权能。<br/>','',59217,2);
INSERT INTO stanza VALUES('ZS251','2','祂没有立下任何的律法,<br/>只说园中果子随意吃;<br/>但是善恶树,万不可接触,<br/>吃了知识果子必定死。<br/>','',59218,3);
INSERT INTO stanza VALUES('ZS251','chorus','知识,知识─<br/>知识果子不能随意吃;<br/>知识,知识─<br/>知识果子吃了必定死。<br/>','',59219,4);
INSERT INTO stanza VALUES('ZS251','3','在伊甸乐园,摆在人面前,<br/>有生命树代表神自己;<br/>但是那毒蛇,诡诈又邪恶,<br/>借着知识使人心偏离。<br/>','',59220,5);
INSERT INTO stanza VALUES('ZS251','chorus','堕落,堕落─<br/>人不幸已中了蛇的毒;<br/>堕落,堕落─<br/>人需要一个完全恢复。<br/>','',59221,6);
INSERT INTO stanza VALUES('ZS251','4','主耶稣基督就是生命树,<br/>神成肉身,满足神要求;<br/>祂救赎我们,又重生我们,<br/>现今成了我们的珍馐。<br/>','',59222,7);
INSERT INTO stanza VALUES('ZS251','chorus','耶稣基督─<br/>耶稣基督是我真食物;<br/>耶稣基督─<br/>吃喝享受祂就得饱足。<br/>','',59223,8);
INSERT INTO stanza VALUES('ZS251','5','主不是要搞我们的头脑,<br/>知识只叫人自高自大;<br/>祂来的目的乃是作筵席,<br/>不重研究乃在吃喝祂。<br/>','',59224,9);
INSERT INTO stanza VALUES('ZS251','chorus','接受,接受─<br/>祂作食物,供应真充足;<br/>接受,接受─<br/>耶稣乃是我们生命树。<br/>','',59225,10);
INSERT INTO stanza VALUES('ZS251','6','越多吃喝祂,越不断长大,<br/>生命、人数必加增不已;<br/>我们要清楚神今天恢复,<br/>基督不是宗教,是筵席。<br/>','',59226,11);
INSERT INTO stanza VALUES('ZS251','chorus','吃祂,吃祂─<br/>越多吃祂,祂越要增多;<br/>吃祂,吃祂─<br/>吃祂的人必因祂活着。<br/>','',59227,12);
INSERT INTO stanza VALUES('ZS251','7','今天的道路是吃喝基督,<br/>没有一件事比此重要;<br/>召会借着吃,新妇得妆饰,<br/>迎接新郎带进神荣耀。<br/>','',59228,13);
INSERT INTO stanza VALUES('ZS251','chorus','吃喝,吃喝─<br/>没有一件事比此重要<br/>吃喝,吃喝─<br/>迎接新郎带进神荣耀。<br/>','',59229,14);
INSERT INTO stanza VALUES('ZS252','1','神圣应许甘甜无比:<br/>人若敬畏耶和华名,<br/>必见公义日头升起,<br/>其翼能医罪、病。<br/>','',59230,1);
INSERT INTO stanza VALUES('ZS252','2','救主满带医治大能,<br/>信祂名者祂必不弃;<br/>痛悔之心速来投诚,<br/>藏身医治圣翼。<br/>','',59231,2);
INSERT INTO stanza VALUES('ZS252','3','公义救主如日展翅;<br/>我若纠缠罪中不离,<br/>怎能得祂抚摸、医治,<br/>安歇于祂圣翼?<br/>','',59232,3);
INSERT INTO stanza VALUES('ZS252','4','妙哉祂已毁伤蛇头,<br/>毒螫消解苦痛全去;<br/>爱的胸臆我当紧投,<br/>医治翼下无虞。<br/>','',59233,4);
INSERT INTO stanza VALUES('ZS252','5','医治翼下我得安息,<br/>满心乐极,高歌颂称:<br/>公义日头今已升起,<br/>其翼能医罪、病。<br/>','',59234,5);
INSERT INTO stanza VALUES('ZS253','1','基督美地,包罗万有-<br/>祂是我的一切:<br/>源、泉、河川,清新明透,<br/>日夜涌流不歇;<br/>谷中山上流出水来,<br/>润我心田,满溢充盈;<br/>何等荣耀,活水澎湃─<br/>作我生命！<br/>','',59235,1);
INSERT INTO stanza VALUES('ZS253','2','神成肉身,忍辱受死,<br/>繁增如同小麦;<br/>死而复活,生命分赐,<br/>初熟如同大麦;<br/>无花果树,甘甜满足,<br/>葡萄产酒,神、人喜悦;<br/>如此供应,全在基督─<br/>有祂无缺！<br/>','',59236,2);
INSERT INTO stanza VALUES('ZS253','3','基督还是真石榴树,<br/>生命丰美充足;<br/>是橄榄树,新油产出,<br/>膏抹永不缺如;<br/>流奶与蜜,美善甘甜,<br/>供我滋养,加我能力;<br/>祂的丰富,如此完全─<br/>基督美地！<br/>','',59237,3);
INSERT INTO stanza VALUES('ZS253','4','在这美地不缺食物,<br/>我们一无所缺;<br/>祂是如此丰饶富庶,<br/>我们颂赞不绝;<br/>上好美地,广大无边,<br/>应有尽有,齐备完全;<br/>今在我心还要扩展─<br/>无量无限！<br/>','',59238,4);
INSERT INTO stanza VALUES('ZS253','5','这地石头如铁之坚,<br/>山内可以挖铜;<br/>权柄如铁,凭以争战,<br/>仇敌不能得逞;<br/>再经苦难,渣滓全去,<br/>炼净明亮,如铜显出;<br/>有铁有铜,应付所需─<br/>全是基督！<br/>','',59239,5);
INSERT INTO stanza VALUES('ZS253','6','为这美地我们颂赞:<br/>主,你何其包罗！<br/>吃喝饱足,让你充满,<br/>丰富岂能尽说！<br/>求使我们经营不辍,<br/>美地实际增长不已;<br/>我的喜乐,我的生活─<br/>基督美地！<br/>','',59240,6);
INSERT INTO stanza VALUES('ZS254','1','生活秘诀欢然寻得,<br/>神圣异象照明亮:<br/>蒙神接枝在基督里,<br/>如同枝子住在葡萄树上。<br/>','',59241,1);
INSERT INTO stanza VALUES('ZS254','chorus','赞美神使我们<br/>得住葡萄树上,<br/>神圣生命丰富得全享！<br/>住在葡萄树上,<br/>留此不再他往;<br/>哦,我们安住葡萄树上！<br/>','',59242,2);
INSERT INTO stanza VALUES('ZS254','2','不再徒然挣扎、努力,<br/>寻求如何得进入;<br/>奇妙事实-我在主里;<br/>奥妙联结-葡萄树是住处。<br/>','',59243,3);
INSERT INTO stanza VALUES('ZS254','3','只要住在葡萄树上,<br/>内里膏抹必不断,<br/>带来神圣宝贵素质,<br/>滋润、浸透,时时充满加添。<br/>','',59244,4);
INSERT INTO stanza VALUES('ZS254','4','如此活在生命流中,<br/>神圣之光常放明;<br/>神人互住,安息稳固,<br/>神的心意在此尽得完成。<br/>','',59245,5);
INSERT INTO stanza VALUES('ZS255','1','基督复活能力浩大无比,<br/>今向祂身体,正在输供;<br/>我们借信领受这大能力─<br/>何等神圣、奇妙输供！<br/>浩大能力,复活的能力,<br/>向召会,在输供！<br/>浩大能力,复活的能力,<br/>向基督身体,在输供！<br/>','',59246,1);
INSERT INTO stanza VALUES('ZS255','2','浩大能力使基督得高升,<br/>远超诸执政,坐在神右;<br/>高升远超一切受称之名─<br/>大能向召会在倾投！<br/>浩大能力,升天的能力,<br/>向召会,在输供！<br/>浩大能力,升天的能力,<br/>向基督身体,在输供！<br/>','',59247,2);
INSERT INTO stanza VALUES('ZS255','3','浩大能力使万有都归服,<br/>在基督脚下,无不归顺;<br/>如此大能正向召会传输,<br/>使身体与头无可分。<br/>浩大能力,归服的能力,<br/>向召会,在输供！<br/>浩大能力,归服的能力,<br/>向基督身体,在输供！<br/>','',59248,3);
INSERT INTO stanza VALUES('ZS255','4','浩大能力使基督向召会,<br/>作万有的头,支配各方;<br/>如此大能乃向着祂召会,<br/>且要借召会全显彰。<br/>浩大能力,支配的能力,<br/>向召会,在输供！<br/>浩大能力,支配的能力,<br/>向基督身体,在输供！<br/>','',59249,4);
INSERT INTO stanza VALUES('ZS256','1','复活的大能,神已经显明,<br/>使祂的儿子从死复生;<br/>因此见大能,我们得加力,<br/>复活生命里昂然夸胜。<br/>大能大能,复活生命大能─<br/>内里运行,时时加添能力;<br/>大能大能,复活生命大能─<br/>里面的人时时得加力！<br/>','',59250,1);
INSERT INTO stanza VALUES('ZS256','2','超越的大能使基督高升,<br/>坐在神右边,远超万有:<br/>执政掌权者,有能主治者,<br/>因基督大名无不拜叩。<br/>大能大能,超越一切大能─<br/>内里运行,使人离地上腾;<br/>大能大能,超越一切大能─<br/>里面的人离地得上腾。<br/>','',59251,2);
INSERT INTO stanza VALUES('ZS256','3','征服的大能使万有归服,<br/>悖逆尽消弭,基督为大;<br/>作祂的身体,分享祂能力,<br/>有何不踏在我们脚下?<br/>大能大能,征服一切大能─<br/>内里运行,处处施行管治;<br/>大能大能,征服一切大能─<br/>里面的人处处施管治。<br/>','',59252,3);
INSERT INTO stanza VALUES('ZS256','4','归一的大能使基督居首,<br/>向着召会作万有的头;<br/>大能的输供成功主身体,<br/>作祂的丰满神旨成就。<br/>大能大能,掌管万有大能─<br/>里里外外,一切尽都归顺;<br/>大能大能,掌管万有大能─<br/>里面的人率先来归顺。<br/>','',59253,4);
INSERT INTO stanza VALUES('ZS257','1','求主赐我启示的灵,<br/>认识复活的大能,<br/>这大能在基督身上,<br/>运行不息时加增。<br/>不单叫祂从死复活,<br/>更叫我因祂得生;<br/>浩大能力借信经历,<br/>使我活在属天层。<br/>','',59254,1);
INSERT INTO stanza VALUES('ZS257','2','复活乃是信徒经历,<br/>非仅历史一事实;<br/>坟墓虽已千年空置,<br/>复活大能仍运施。<br/>这个大能不是神学,<br/>不仅是理论而已;<br/>它使信徒天天实际,<br/>联于复活主自己。<br/>','',59255,2);
INSERT INTO stanza VALUES('ZS257','3','复活带进新造领域,<br/>使我脱离旧自我;<br/>非如拉撒路之神迹,<br/>苟延旧造并重活。<br/>我所需要不是任何<br/>起死回生的经过,<br/>亦非任何工作能力,<br/>乃让复活将我摸。<br/>','',59256,3);
INSERT INTO stanza VALUES('ZS257','4','一切死亡阴间经历,<br/>皆为复活启生机;<br/>生借死亡发动运行,<br/>肉体治死灵奋起。<br/>死亡所设千万防线,<br/>基督走过何容易;<br/>畅游阴间乐园深渊,<br/>从未恐慌或逃离。<br/>','',59257,4);
INSERT INTO stanza VALUES('ZS257','5','死亡对人最大威胁,<br/>无非惧怕与捆绑;<br/>当主打破死亡门槛,<br/>粉碎限制与惊惶。<br/>天然生命不再缠扰,<br/>复活生命得显扬;<br/>最后仇敌既被吞灭,<br/>有何能将生命挡?<br/>','',59258,5);
INSERT INTO stanza VALUES('ZS257','6','基督人性借着复活,<br/>已被拔高并标出;<br/>从此堕落人类生命,<br/>可望与主同前途。<br/>经历基督全备救恩,<br/>不仅那日体得赎,<br/>人性更被拯救、拔高,<br/>提升等同复活主。<br/>','',59259,6);
INSERT INTO stanza VALUES('ZS257','7','复活并不改良旧造,<br/>减轻旧造的折腾;<br/>也不加强旧造生命,<br/>使之能以自逞能。<br/>基督虽曾肉体痛哭,<br/>灵里却是倚靠神;<br/>复活不求改变环境,<br/>只在环境显效能。<br/>','',59260,7);
INSERT INTO stanza VALUES('ZS257','7','神借旧造产生新造,<br/>此为极大的奥秘;<br/>罪、死虽然污染肉体,<br/>经死一笔全清洗。<br/>主将伊甸所造人性,<br/>给予重整赋新机;<br/>复活原则永不改变─<br/>新造取材旧造里。<br/>','',59261,8);
INSERT INTO stanza VALUES('ZS257','9','基督复活生为长子,<br/>人性拔高至神性;<br/>大衞后裔今日被生,<br/>此为真正的福音。<br/>从此人类新生有望,<br/>复活产生新族群─<br/>同父同胎同命同性,<br/>同一源头同命运。<br/>','',59262,9);
INSERT INTO stanza VALUES('ZS257','10','复活大能使我重生,<br/>得有神圣诸供备;<br/>使我有权成为儿女,<br/>从神而生属神类─<br/>生命性情与神一样,<br/>只与神格无分位。<br/>第一神人我们长兄,<br/>作我原型并原胚。<br/>','',59263,10);
INSERT INTO stanza VALUES('ZS257','11','我与基督已经联合,<br/>祂我生命已接枝;<br/>复活生命天天交流,<br/>时时相调永无止。<br/>祂更成了赐生命灵,<br/>作神终极的显出,<br/>带来神性人性丰富,<br/>使我活出子基督。<br/>','',59264,11);
INSERT INTO stanza VALUES('ZS257','12','我们成了基督肢体,<br/>与主成为一单元;<br/>祂的经历成我履历,<br/>我的一切祂成全。<br/>复活早晨新生男孩,<br/>乃是宇宙新生族;<br/>这是神人互住父家,<br/>又是生机葡萄树。<br/>','',59265,12);
INSERT INTO stanza VALUES('ZS257','13','复活实际-生命之灵,<br/>今已住在我灵中;<br/>使我天天经历复活,<br/>与我同活同行动;<br/>永远胜过罪与死律,<br/>作王生命来居衷;<br/>最终漫溢必死身体,<br/>使我贱身与祂同。<br/>','',59266,13);
INSERT INTO stanza VALUES('ZS257','14','在复活里与祂同长,<br/>活出生命的新样,<br/>一举一动结出义果,<br/>主观称义得显彰。<br/>水浸埋葬旧人自己,<br/>灵浸引我奔义路;<br/>在此赛程不偏左右,<br/>直至我被义构成。<br/>','',59267,14);
INSERT INTO stanza VALUES('ZS257','15','复活彰显在我事奉,<br/>发芽枯杖作仲裁;<br/>只凭复活生命建造,<br/>召会必成杏树台。<br/>木草禾稭烧尽去净,<br/>只用复活作建材;<br/>圣城撒冷神人合一,<br/>作我工作的赏赉。<br/>','',59268,15);
INSERT INTO stanza VALUES('ZS257','16','但愿我能深切认识,<br/>何谓复活的大能,<br/>天天模成十架模型,<br/>单凭复活度此生;<br/>认识复活人位基督,<br/>在那灵中时加增,<br/>直到见主被提时刻,<br/>杰出复活展上腾。<br/>','',59269,16);
INSERT INTO stanza VALUES('ZS258','1','主,我在你内,你在我里;<br/>住在你里面,时刻不离;<br/>你与我同在,何其亲密;<br/>主,我们彼此,联结为一。<br/>','',59270,1);
INSERT INTO stanza VALUES('ZS258','chorus','神圣经纶,神圣分赐,<br/>在你三一里;<br/>向我传输,与我调和,<br/>用你的自己。<br/>','',59271,2);
INSERT INTO stanza VALUES('ZS258','2','我是你枝子,你是真树;<br/>我在你里面,安然居住;<br/>主,我心深愿,住留此处;<br/>主,我是属你,你也我属。<br/>','',59272,3);
INSERT INTO stanza VALUES('ZS258','3','橄榄枝与你已经相接,<br/>得丰富供应,取用不竭;<br/>享生命涌流,永不停歇;<br/>在此必成长,因这联结。<br/>','',59273,4);
INSERT INTO stanza VALUES('ZS258','4','当我们内住彼此里面,<br/>实际的相联真是无间;<br/>当我们停留彼此里面,<br/>主观的相调才得完全。<br/>','',59274,5);
INSERT INTO stanza VALUES('ZS258','5','主,爱你享你,满足我需;<br/>你成为我里应时话语;<br/>在我里代求,促我前去;<br/>结常存果子,让你继续。<br/>','',59275,6);
INSERT INTO stanza VALUES('ZS258','6','生命在我里,流通四处;<br/>你就能充满,洋溢不住;<br/>我们成为一,将你显出;<br/>住在你里面,喜乐满足。<br/>','',59276,7);
INSERT INTO stanza VALUES('ZS331','1','我是属主！哦,喜乐真是难述！<br/>甜美的回应主爱的招呼;<br/>“你是属我,别怕,我已将你赎”─<br/>祂柔声应许我凭信顺服。<br/>','',59277,1);
INSERT INTO stanza VALUES('ZS331','2','我是属主！哦,心中欢喜承认！<br/>享快乐之日,望婚娶之晨;<br/>我说“我愿”迎接祂进入心门,<br/>敬爱顺从主永作“主的人”。<br/>','',59278,2);
INSERT INTO stanza VALUES('ZS331','3','我是属主！哦,要学更深一步:<br/>不愿自由去,因我爱我主;<br/>忠贞、爱慕、犠牲事奉并降服,<br/>我毫无保留永作你奴仆。<br/>','',59279,3);
INSERT INTO stanza VALUES('ZS331','4','我是属主！哦,灵、魂、体每一部,<br/>都有你印记,永不再他属;<br/>就像你,主,满带恩典和丰富,<br/>一直到永远,全都归我属。<br/>','',59280,4);
INSERT INTO stanza VALUES('ZS332','1','仅仅一摸,亲爱主,<br/>仅仅一望便知足,<br/>你与我亲嘴,我心别无所归。<br/>让我再听你慈声,<br/>最后选择不变更,<br/>向我爱语陈,我就枉费你身。<br/>','',59281,1);
INSERT INTO stanza VALUES('ZS332','chorus','无人无物能满足我情我意,<br/>爱主,惟你。<br/>耶稣,我爱你,我心惟一所要爱你,<br/>直到天晓。<br/>','',59282,2);
INSERT INTO stanza VALUES('ZS332','2','让我摸你如昨曾,<br/>渴慕之情日添增,<br/>至宝我已得,为你,一切愿舍！<br/>与我亲嘴爱何深,<br/>颂赞欢呼溢我唇,<br/>主,你满恩惠,何等甜美滋味！<br/>','',59283,3);
INSERT INTO stanza VALUES('ZS332','chorus','无人无物能满足我情我意,<br/>爱主惟你。<br/>耶稣,起初爱,将,我全人焚烧<br/>我心惟一所要！<br/>','',59284,4);
INSERT INTO stanza VALUES('ZS332','3','你的爱眼来注目,<br/>哦,这联结何稳固。<br/>每当我凝视,我被充满,消失。<br/>惟有你才能满足,<br/>我不能活无你处,<br/>让我你身倚,与你联结为一。<br/>','',59285,5);
INSERT INTO stanza VALUES('ZS332','chorus','无人无物能满足我情我意,<br/>爱主惟你。<br/>耶稣,我爱你我,心惟一所要<br/>爱主,将我焚烧！<br/>','',59286,6);
INSERT INTO stanza VALUES('ZS332','4','今我悔改归向神,<br/>求让我心为你焚！<br/>愿你这热火,我里真实烧着。<br/>今我悔改归向神,<br/>求让我心为你焚！<br/>愿你这热火,我里真实烧着。<br/>','',59287,7);
INSERT INTO stanza VALUES('ZS332','chorus','耶稣,起初爱！哦,耶稣,上好爱！<br/>我全归来！<br/>耶稣,起初爱！哦,耶稣,上好爱！<br/>我爱！求听此籁！<br/>','',59288,8);
INSERT INTO stanza VALUES('ZS333','1','我爱我主,非用天然之爱;<br/>我无可以给你。<br/>主,我爱你,这爱全然属你,<br/>使我活在你里。<br/>我一无所有,却欢然经历,<br/>倒空,消失,浸没在你爱里。<br/>','',59289,1);
INSERT INTO stanza VALUES('ZS333','2','我主,惟你是我一切所需,<br/>我心别无所愿;<br/>住在你里,经历祝福江河,<br/>从你涌流无间。<br/>饮生命活泉,享你作恩典,<br/>作我中心、居所、祝福之源。<br/>','',59290,2);
INSERT INTO stanza VALUES('ZS334','1','哦,主耶稣愿你吸引我,<br/>我就快跑来跟随,<br/>享受你的名如倒出香膏,<br/>你的爱比酒更美！<br/>你是我王,带我进你内室,<br/>享受你甜美的同在;<br/>我要称赞你宝贵爱情,<br/>价值存到万代。<br/>','',59291,1);
INSERT INTO stanza VALUES('ZS334','2','我原顽强如法老骏马,<br/>你使我变化如鸽,<br/>在你面光中,纯一来仰望,<br/>信靠你,犹似百合。<br/>以你性情构成我的妆饰,<br/>我两腮因金辫秀美;<br/>倔强颈项因珠串美丽,<br/>甘服你旨不违。<br/>','',59292,2);
INSERT INTO stanza VALUES('ZS334','3','蹿山越岭,你如同羚羊,<br/>召我脱“自己”拘禁:<br/>“冬天已过去雨水也止住,<br/>佳偶,来与我同去！”<br/>百鸟鸣叫,地上百花开放,<br/>复活的丰富何繁茂,<br/>深深吸引我脱离自己,<br/>进入你的高超。<br/>','',59293,3);
INSERT INTO stanza VALUES('ZS334','4','“我的佳偶,你在磐穴中,<br/>在陡岩的隐密处,<br/>让我见你面,得听你声音-<br/>我死里你当留驻。<br/>声音柔和,面貌更显秀美-<br/>复活里新造何饶优！”<br/>主我宝贵你十架模型,<br/>愿在此永住留。<br/>','',59294,4);
INSERT INTO stanza VALUES('ZS334','5','“我的妹子,你夺了我心,<br/>你全然美丽可珍,<br/>用你眼一看,用你项上炼,<br/>深深夺取了我心;<br/>我的新妇,你爱情何其美,<br/>你膏油香气无可比,<br/>嘴唇滴蜜,舌下有奶、蜜,<br/>衣服香气盈溢。”<br/>','',59295,5);
INSERT INTO stanza VALUES('ZS334','6','我愿成为关锁的园子,<br/>只供良人你享乐;<br/>又如利巴嫩,在你升天里,<br/>流出溪水解干渴。<br/>南风吹来,北风阿快醒起,<br/>吹在我心中的园地,<br/>好,使香气从园中溢出,<br/>叫我良人满意。<br/>','',59296,6);
INSERT INTO stanza VALUES('ZS334','7','亲爱良人,我只属于你,<br/>爱中联调永不移,<br/>求将我如同印记放心上<br/>带在臂上如戳记！<br/>主,我深知爱情如死坚强,<br/>众水也不能来熄灭;<br/>直到永世仍要唱不尽,<br/>你我情深联结！<br/>','',59297,7);
INSERT INTO stanza VALUES('ZS335','1','人的心哪,你爱甚么?<br/>若非基督,无安息。<br/>哦,主,求你悦纳我心,<br/>上好之爱,来爱你。<br/>','',59298,1);
INSERT INTO stanza VALUES('ZS335','2','今将世界全都抛弃,<br/>我主耶稣最美丽;<br/>你是可爱、甘甜、柔细,<br/>怜悯、恩典全洋溢。<br/>','',59299,2);
INSERT INTO stanza VALUES('ZS335','3','你的荣脸,明亮辉煌,<br/>发光照耀永无已;<br/>最美事物也无可比,<br/>惟你使我心欢喜。<br/>','',59300,3);
INSERT INTO stanza VALUES('ZS335','4','主！是你爱先来临及,<br/>流血拯救你仇敌;<br/>你之爱我,永不止息,<br/>我心岂可不爱你?<br/>','',59301,4);
INSERT INTO stanza VALUES('ZS335','5','保守我心忠诚向你,<br/>使我同你藏神里,<br/>在世一切所经所历,<br/>让你荣耀留足迹。<br/>','',59302,5);
INSERT INTO stanza VALUES('ZS336','1','请告诉我,祂被移到何处?<br/>石头已辊开,只留下空墓。<br/>哦！有人己将祂移出,<br/>祂在何处?<br/>','',59303,1);
INSERT INTO stanza VALUES('ZS336','2','门徒前来,亲眼看见空墓;<br/>竟然就离开,回自己住处。<br/>眼前事实,他们满足。<br/>祂在何处?<br/>','',59304,2);
INSERT INTO stanza VALUES('ZS336','chorus','何处寻祂─主耶稣?<br/>何处寻祂-爱主?<br/>何处寻祂-我心所慕?<br/>耶稣,挚爱,我要你,主。<br/>','',59305,3);
INSERT INTO stanza VALUES('ZS336','3','我心破碎,失去最深渴慕;<br/>不要问我:妇人,你为何哭?<br/>除了耶稣,别无满足。<br/>祂在何处?<br/>','',59306,4);
INSERT INTO stanza VALUES('ZS336','4','转过身来,看见复活耶稣;<br/>以为是园丁,我竟未认出;<br/>以为他知主在何处。<br/>祂在何处?<br/>','',59307,5);
INSERT INTO stanza VALUES('ZS336','chorus','何处寻祂─主耶稣?<br/>何处寻祂-爱主?<br/>何处寻祂-指示我路,<br/>我要取祂,不畏险阻。<br/>','',59308,6);
INSERT INTO stanza VALUES('ZS336','5','我听见祂对我柔声轻诉;<br/>甜美呼唤进入我心深处。<br/>熟悉声音,就是我主;<br/>是我耶稣！<br/>','',59309,7);
INSERT INTO stanza VALUES('ZS336','chorus','我已寻见主耶稣,<br/>我已寻见爱主,<br/>我已寻见我心所慕,<br/>耶稣,挚爱,我爱你,主。<br/>','',59310,8);
INSERT INTO stanza VALUES('ZS336','6','得见我主,我心喜难述;<br/>祂要升天,使父心满意足。<br/>祂神、祂父成我们神、<br/>我们的父。<br/>','',59311,9);
INSERT INTO stanza VALUES('ZS336','chorus','你要升天,去见父;<br/>要我告诉门徒:<br/>你神已成我们的神,<br/>你父已成我们的父。<br/>','',59312,10);
INSERT INTO stanza VALUES('ZS337','1','已过二十世纪以来，<br/>千千万万宝贵的性命，<br/>心爱的奇珍、崇高的地位、<br/>以及灿烂的前途，<br/>都曾枉费在主耶稣身上。<br/>对这些爱主的人，<br/>祂是全然可爱，<br/>祂是全然可爱，<br/>配得我们献上一切，<br/>我们浇在主身上的不是枉费，<br/>乃是馨香的见证，<br/>见证祂的甘甜。<br/>','',59313,1);
INSERT INTO stanza VALUES('ZS338','1','主耶稣，我是真爱你，愿意单纯，<br/>赎回我所有的光阴，享你爱恩。<br/>喔看那！我能在今天全然奉献，<br/>是因你始终的恩眷，奇妙成全。<br/>求你开通我耳，在你这神家的门，<br/>当你发出呼声，我愿意永远向你忠诚。<br/>把我印在你心，以你爱甚至你嫉恨；<br/>让我一生作你疯狂爱人。<br/>','',59314,1);
INSERT INTO stanza VALUES('ZS338','2','荣耀神，今愿在这里，向你屈膝，<br/>赐我们智慧启示灵，得见奥秘。<br/>这一生只愿投身你神圣经纶，<br/>只为你永远的心意︰基督身体。<br/>在我调和灵里，带我进身体实际；<br/>享你加强救恩，使我们成耶稣的见证。<br/>主阿！愿你快来！照着你所曾经答应；<br/>我们唯一羡慕是你再临。<br/>','',59315,2);
INSERT INTO stanza VALUES('ZS339','1','主，袮保守我心永真诚，<br/>绝不稍退后，时见袮面容。<br/>一心单纯、清洁，只愿面见袮。<br/>一心只爱袮，只宝贝袮自己。<br/>','',59316,1);
INSERT INTO stanza VALUES('ZS339','chorus','袮爱困迫，我愿奉献我所有，<br/>袮爱吸引，我心全向袮倚投，<br/>哦，何等权利，能将自己给袮，<br/>主，我爱袮！亲爱主！我只愿深爱袮。<br/>','',59317,2);
INSERT INTO stanza VALUES('ZS339','2','主，使我爱向着袮焚烧！<br/>从来不熄灭，火热不减少，<br/>深愿这爱向袮，一生都显耀；<br/>新鲜如当日，初尝袮的上好。<br/>','',59318,3);
INSERT INTO stanza VALUES('ZS339','3','主，得着我一生献给袮，<br/>纵有命成千，归袮也愿意。<br/>无何保留为己，一切全为袮，<br/>我命、我一生，爱主，愿都为袮。<br/>','',59319,4);
INSERT INTO stanza VALUES('ZS340','1','主,我爱你逐日益深挚,<br/>主,我爱你今日胜昨日。<br/>我不能再活无你之处,<br/>我不能重步往日行径。<br/>','',59320,1);
INSERT INTO stanza VALUES('ZS340','2','哦,在往昔无你岁月中,<br/>当我失丧,你来施拯救。<br/>我每忆过往其余年日,<br/>虚空心痛并潸然泪流。<br/>','',59321,2);
INSERT INTO stanza VALUES('ZS340','chorus','主,我真爱你,日益深挚。<br/>主,我真爱你,历久弥新无止。<br/>','',59322,3);
INSERT INTO stanza VALUES('ZS340','3','哦干渴吞噬我心深处,<br/>驱使我寻求以得满足。<br/>哦我曾尝试许多事物,<br/>却仍干渴且不得满足。<br/>','',59323,4);
INSERT INTO stanza VALUES('ZS340','4','主你充满我全人深处,<br/>丰美甘甜最令人满足。<br/>你是那灵,作我的一切,<br/>你灵与我灵洋溢不住。<br/>','',59324,5);
INSERT INTO stanza VALUES('ZS340','5','追寻新事物总无止境,<br/>惟你才是我终日渴求。<br/>我前盲目且汲汲营营,<br/>直至饮你作活水源头。<br/>','',59325,6);
INSERT INTO stanza VALUES('ZS340','6','何感谢！主,你进入我灵,<br/>今在我里你不断扩展。<br/>何宝贝！主安家我心房,<br/>将我里面各部分充满。<br/>','',59326,7);
INSERT INTO stanza VALUES('ZS341','1','从前沉溺罪恶地,<br/>良心终日无安息,<br/>深感痛苦、无能力我知罪,<br/>我自责,因罪污不义。<br/>','',59327,1);
INSERT INTO stanza VALUES('ZS341','2','悲惨人生无所期,<br/>虚空世界无意义,<br/>追求快乐和刺激如补风,<br/>如捉影,既虚空又无益。<br/>','',59328,2);
INSERT INTO stanza VALUES('ZS341','3','神！我曾远离你,<br/>你至高、至大、独一;<br/>哦！你竟然成为肉体,<br/>亲来寻觅,血将我洗,<br/>钉死作我代替。<br/>','',59329,3);
INSERT INTO stanza VALUES('ZS341','chorus','愿一生爱你,<br/>愿与你更亲密,<br/>愿将生命和一切全献给你。<br/>愿一生爱你,<br/>愿与你更亲密,<br/>愿将生命和一切全献给你。<br/>','',59330,4);
INSERT INTO stanza VALUES('ZS342','1','愿你用口与我亲嘴,<br/>因你爱情比酒美;<br/>我虽然黑,却是秀美,<br/>哪哒香膏满香味。<br/>我尝甘甜,我享筵宴,<br/>你的呼召我听见;<br/>唤我起来同你往前,<br/>我何愚昧竟迟延。<br/>','',59331,1);
INSERT INTO stanza VALUES('ZS342','chorus','主阿,在你与我爱的交通里,<br/>你天天吸引,呼召我脱自己;<br/>要我凡事与你是一,<br/>与你同工等候被提。<br/>','',59332,2);
INSERT INTO stanza VALUES('ZS342','2','蓦然醒悟,失去你面,<br/>身体里将你寻见;<br/>我爱作你华轿坐垫,<br/>我成你喜乐冠冕。<br/>你召我上真理山岭,<br/>同你活在升天境;<br/>我心答应,我目送情,<br/>甘心作你园、泉、井。<br/>','',59333,3);
INSERT INTO stanza VALUES('ZS342','3','听见柔声,要我开门,<br/>上前,你竟已转身;<br/>当我述说可爱良人,<br/>真实同在又满魂。<br/>作你佳偶,全因你恩,<br/>且带盼望如清晨;<br/>书拉密女与所罗门,<br/>神人调和永不分。<br/>','',59334,4);
INSERT INTO stanza VALUES('ZS342','4','起来与你同往田间,<br/>清晨流连葡萄园;<br/>风茄见证你我相联,<br/>我结果佳美新鲜。<br/>为你旨意,爱你所爱,<br/>豫备新妇趁现在;<br/>殷勤劳苦,盼望等待,<br/>良人哪,愿你快来。<br/>','',59335,5);
INSERT INTO stanza VALUES('ZS343','1','你的爱和你美丽自己，<br/>吸引我快跑跟随你。<br/>我重生进你内室，<br/>蒙你喂养到永世。<br/>','',59336,1);
INSERT INTO stanza VALUES('ZS343','chorus','良人阿！我只属于你。<br/>佳偶阿！你何等美丽。<br/>你我生命、性情是一，<br/>爱里联结永不分离。<br/>','',59337,2);
INSERT INTO stanza VALUES('ZS343','2','因你，我得有圣别性情，<br/>我美丽来自你生命。<br/>得更新顺从听命，<br/>同良人蹿山越岭。<br/>','',59338,3);
INSERT INTO stanza VALUES('ZS343','3','单一里注视你如良鸽，<br/>荆棘中信靠如百合。<br/>被变化，得你建造，<br/>成为你安息、喜乐。<br/>','',59339,4);
INSERT INTO stanza VALUES('ZS343','4','在田间随你往前脚踪，<br/>愿一生爱你而同工。<br/>作王女，满你情衷，<br/>更巴望被提得荣。<br/>','',59340,5);
INSERT INTO stanza VALUES('ZS343','chorus','请将我铭刻你心上，<br/>因你爱如死之坚强。<br/>朝思暮想，良人，我王，<br/>愿你快来，香草山上！<br/>','',59341,6);
INSERT INTO stanza VALUES('ZS344','1','祂寻我如同寻找迷羊，<br/>祂赎我舍了性命；<br/>使我能得祂生命，<br/>经历祂享受不尽。<br/>哦，我主，我真爱你，<br/>不自禁消失你里，<br/>因你的爱困迫激励，<br/>愿一生奉献给你。<br/>','',59342,1);
INSERT INTO stanza VALUES('ZS344','2','你甘美如草场、如溪水，<br/>我苏醒来走义路；<br/>凭信心生活有力，<br/>引导我能活出义。<br/>但世界时来搅扰，<br/>世代流行入浪潮，<br/>而你的爱永不动摇，<br/>牧养顾惜不减少。<br/>','',59343,2);
INSERT INTO stanza VALUES('ZS344','3','忽不觉你宝贵的同在，<br/>摸不着可爱的你，<br/>我的心不住犹疑，<br/>你杖干安慰不已。<br/>深领会凭信而活，<br/>我牧人引我行走，<br/>面对仇敌享你筵席，<br/>真经历福杯漫溢。<br/>','',59344,3);
INSERT INTO stanza VALUES('ZS344','4','我牧长，我愿意跟随你，<br/>牧养你托付羊群，<br/>体贴你心中美意，<br/>永远活在经纶里。<br/>哦，我主，我感谢你，<br/>你恩慈随我不离，<br/>愿永住在你的殿里，<br/>彰显你荣耀身体。<br/>','',59345,4);
INSERT INTO stanza VALUES('ZS345','1','主耶稣，你是我至爱，<br/>我全心归你不他依；<br/>天地间有何能与你比拟？<br/>神而人者，你最美丽！<br/>真渴望消失在你里，<br/>当你柔声入我心底；<br/>前我所眷恋，今欢然撇弃，<br/>只愿爱你─全心全意。<br/>','',59346,1);
INSERT INTO stanza VALUES('ZS345','chorus','世上有谁像你如此美丽？<br/>人间有何与你爱情能比？<br/>哦，圣中之圣，你竟住我里；<br/>主耶稣，我深深爱你！<br/><br/>不愿再受欺，不愿再任意；<br/>惟愿脱自己，只被你充溢；<br/>你以外，哦，让一切都绝迹；<br/>我惟一的最爱是你。<br/>','',59347,2);
INSERT INTO stanza VALUES('ZS345','2','主耶稣，你是我至爱，<br/>虽我曾顽梗又悖逆，<br/>今放下一切，你前来侍立，<br/>只愿像你那样无己。<br/>真渴望活着就是你，<br/>顺从神旨，不凭己意；<br/>与你心合拍，只要你所喜；<br/>挣扎全停，尽是安息。<br/>','',59348,3);
INSERT INTO stanza VALUES('ZS345','3','主耶稣，你是我至爱<br/>你与我永远不分离；<br/>你同在是我气息、我动力，<br/>你的笑脸是我欣喜。<br/>真渴望你前吐心意，<br/>爱你、事你，联结依依；<br/>亲爱主，我的永分就是你<br/>你的来临是我所期。<br/>','',59349,4);
INSERT INTO stanza VALUES('ZS346','1','用我的诗歌,向我所爱的主,<br/>唱出我心声,也唱出我愁楚。<br/>年来所行路,是备尝人世苦,<br/>除了我的主,还有谁可倾诉?<br/>除了我的主,还有谁可倾诉?<br/>','',59350,1);
INSERT INTO stanza VALUES('ZS346','2','用我的诗歌,向我所爱的主,<br/>献上我赞美,也倾吐我思慕。<br/>虽然所行路,是凄酸多云雾,<br/>但主手领我,仍前进不后顾。<br/>但主手领我,仍前进不后顾。<br/>','',59351,2);
INSERT INTO stanza VALUES('ZS346','3','用我的诗歌,向我所爱的主,<br/>表示我愿意,一直走此窄路。<br/>虽然所饮杯,是苦胆调酸醋,<br/>我亦无怨言,我亦乐意顺服。<br/>我亦无怨言,我亦乐意顺服。<br/>','',59352,3);
INSERT INTO stanza VALUES('ZS346','4','用我的诗歌,向我所爱的主,<br/>唱这十架路,是我惟一归途。<br/>虽然所经过,是伤心流泪谷,<br/>但主却领我,由此路通国度。<br/>但主却领我,由此路通国度。<br/>','',59353,4);
INSERT INTO stanza VALUES('ZS347','1','主,我心愿更贞洁,<br/>一切求你喜悦,<br/>愿我爱火烧更烈,<br/>众水不能熄灭。<br/>','',59354,1);
INSERT INTO stanza VALUES('ZS347','chorus','哦主,我已奉献给你,<br/>哦,主,我已献给你,<br/>我只怕心偏于邪,<br/>失去纯一清洁,<br/>愿我的心能更爱你,<br/>你外我无他喜悦。<br/>','',59355,2);
INSERT INTO stanza VALUES('ZS347','2','凡事学习要谨守,<br/>恩座前常祈求,<br/>拒绝试探和引诱,<br/>不贪罪中自由。<br/>','',59356,3);
INSERT INTO stanza VALUES('ZS347','3','处世愿自居卑微,<br/>不慕通达高贵,<br/>将来新城荣且美,<br/>恩典福分全备。<br/>','',59357,4);
INSERT INTO stanza VALUES('ZS347','4','今日一切劳和苦,<br/>为主都甘经受,<br/>昔日恩主所行路,<br/>更是历尽苦忧。<br/>','',59358,5);
INSERT INTO stanza VALUES('ZS347','5','卑微通到荣耀路,<br/>必须经过十架,<br/>今日所有的重负,<br/>见主都必卸下。<br/>','',59359,6);
INSERT INTO stanza VALUES('ZS347','6','叹息声音何时已?<br/>劳苦何时得息?<br/>不是旅程走完毕,<br/>便是主来接提。<br/>','',59360,7);
INSERT INTO stanza VALUES('ZS348','1','我是时常輭弱,輭弱至极,<br/>所有信心消没,力量都疲;<br/>但你长久忍耐,从不放弃,<br/>仍要引我归爱,傍你胸臆。<br/>','',59361,1);
INSERT INTO stanza VALUES('ZS348','2','我是时常起伏,忧惧不停,<br/>所有亮光衰微,盼望摇动;<br/>但你应许恩言,不改坚定,<br/>仍来开我心眼,向你忠诚。<br/>','',59362,2);
INSERT INTO stanza VALUES('ZS348','3','我是时常保留,损失都畏,<br/>所有筹划为己,祭坛倾废;<br/>但你柔爱怜悯,竟不收回,<br/>仍来将我吸引,向你全归。<br/>','',59363,3);
INSERT INTO stanza VALUES('ZS348','4','我是时常单独,自己追求,<br/>所有欢乐愁苦,寂寞承受;<br/>但你细细部署,不肯松手,<br/>仍来领我脚步,向你倚投。<br/>','',59364,4);
INSERT INTO stanza VALUES('ZS348','5','我是时常无知,错识你心,<br/>所有思念体贴都在己身;<br/>但你光照不止,启示心意,<br/>仍来转我想愿,与你成一。<br/>','',59365,5);
INSERT INTO stanza VALUES('ZS348','6','当我想到你的一切对待,<br/>我是不知如何回报你爱;<br/>在我每一今日尚有微力,<br/>仍然我要尽力,一生爱你。<br/>','',59366,6);
INSERT INTO stanza VALUES('ZS348','7','不问我的前途光明黑暗,<br/>不理我的道路平顺艰难;<br/>如果是你许可,宁愿等候,<br/>只要是你拣选,欢然行走。<br/>','',59367,7);
INSERT INTO stanza VALUES('ZS349','1','对主我们如同园子,<br/>流露各种的馨香;<br/>耶稣所有宝贵果子,<br/>园中自由的生长。<br/>哪哒凤仙、并番红花,<br/>菖蒲、肉桂、乳香木、<br/>没药沉香在此长出,<br/>甜美芬芳全为归给主。<br/>','',59368,1);
INSERT INTO stanza VALUES('ZS349','2','“主请进入你的园子;<br/>良人请来随意尝,<br/>佳美果子上等香品,<br/>甘美丰盈供你享。<br/>“我的妹子,我的新妇,<br/>园中蜂房滴甘蜜,<br/>还有酒奶丰美、滋养,<br/>在此吃喝,满足实无比。”<br/>','',59369,2);
INSERT INTO stanza VALUES('ZS349','3','园内所产复活果品,<br/>经过变他成珍宝,<br/>不仅甘美,更为建造,<br/>成为圣城主所要。<br/>先是园子,终为圣城,<br/>生长变化何美妙;<br/>基督在此得着彰显,<br/>神的荣光辉煌全显耀。<br/>','',59370,3);
INSERT INTO stanza VALUES('ZS349','4','如今这城美丽、秀美,<br/>得胜如晨光显明,<br/>且是军队刚强有能,<br/>在得胜里向前行。<br/>城与军队─团体圣徒,<br/>变化、建造成为一;<br/>向着仇敌,何等威武,<br/>向着主又是何等美丽！<br/>','',59371,4);
INSERT INTO stanza VALUES('ZS430','1','主,你得胜,我今服矣;<br/>恩典迫使我心决意,<br/>奉献一切于你;<br/>你的可畏我能久抗,<br/>但你大爱有谁能挡?<br/>爱大,我无能力。<br/>','',59372,1);
INSERT INTO stanza VALUES('ZS430','2','即使你命万钧雷霆,<br/>轰击我魂向我施刑,<br/>我仍固执不悔;<br/>但你怜悯征服我心,<br/>当我见主流血情景,<br/>我今恨恶我罪！<br/>','',59373,2);
INSERT INTO stanza VALUES('ZS430','3','主,我羡慕只属于你;<br/>速来释放我这容器,<br/>完全归你占有;<br/>撒但暴政我既得脱,<br/>就愿全人向你而活,<br/>服事你到永久。<br/>','',59374,3);
INSERT INTO stanza VALUES('ZS431','1','只要相信耶稣大名,<br/>在信的人凡事都能;<br/>主,求使我不辱你名,<br/>使你真理在我显明。<br/>只要对你坚信确定,<br/>在信的人凡事都能。<br/>','',59375,1);
INSERT INTO stanza VALUES('ZS431','2','罪恶权势纠缠不已,<br/>我欲挣脱,毫无能力;<br/>但你应许罪奴得释,<br/>此事必成,我心深知。<br/>并无一事在主难成,<br/>在信的人凡事都能。<br/>','',59376,2);
INSERT INTO stanza VALUES('ZS431','3','任凭阴府否认圣言,<br/>神的话语坚定在天;<br/>罪恶锁炼纵然顽强,<br/>主能打碎,将人释放。<br/>难成之事必然得成,<br/>在信的人凡事都能。<br/>','',59377,3);
INSERT INTO stanza VALUES('ZS431','4','不仅在神凡事都能,<br/>在主基督凡事亦然─<br/>祂是“神能”显于人身,<br/>我在祂里全人更新,<br/>罪恶权势不再得逞,<br/>在信的人凡事都能。<br/>','',59378,4);
INSERT INTO stanza VALUES('ZS431','5','哦主,你这神的大能,<br/>求在我里开展、扩增,<br/>直到活着不再是我,<br/>乃是基督在我活着,<br/>此时我要甘甜唱出:<br/>你爱大能无量、全足。<br/>','',59379,5);
INSERT INTO stanza VALUES('ZS432','1','奇妙秘诀我已学会,<br/>就是住在主里面;<br/>在此畅饮生命纯泉,<br/>日日饱尝祂圣言;<br/>在祂有能宝血底下,<br/>我得加力享肥甘;<br/>败坏的『己』日渐消逝,<br/>当我浸没祂里面。<br/>','',59380,1);
INSERT INTO stanza VALUES('ZS432','chorus','我今住在主里面,<br/>相信祂可靠圣言;<br/>甜美、安息,隐藏祂爱胸怀间。<br/>是的,住在主里面,<br/>相信祂可靠圣言、<br/>甜美、安息,隐藏祂爱胸怀间。<br/>','',59381,2);
INSERT INTO stanza VALUES('ZS432','2','我与基督已经同钉,<br/>祂今与我同生活;<br/>我已停下一切挣扎,<br/>今是祂,不再是我。<br/>当我意志降服于祂,<br/>祂灵掌权我心内,<br/>祂的救赎、拯救有能,<br/>使我洁净并脱罪。<br/>','',59382,3);
INSERT INTO stanza VALUES('ZS432','3','我将疾病带来归祂,<br/>由祂一一都担去;<br/>我告祂以輭弱、忧、惧,<br/>祂使我一无罣虑。<br/>我的力量取自基督,<br/>生活行动祂指点;<br/>祂赐我以生命、信、爱,<br/>使我活出祂意念。<br/>','',59383,4);
INSERT INTO stanza VALUES('ZS432','4','我以祂智作我言、语<br/>凭祂灵力而作工;<br/>祂的同在作我道路,<br/>不住保卫、引导我。<br/>祂是无穷喜乐泉源,<br/>作我永分藏心房-<br/>是我救主、圣别、医治、<br/>荣耀主、永世君王。<br/>','',59384,5);
INSERT INTO stanza VALUES('ZS433','1','我今上行,毫不迟疑,<br/>每日迈向更高之地;<br/>前行途中,祷告不息:<br/>“主使我立更高之地。”<br/>','',59385,1);
INSERT INTO stanza VALUES('ZS433','chorus','主,加我力,将我举起,<br/>使我踏上更高之地;<br/>更高境地,凭信站立;<br/>主,使我立更高之地。<br/>','',59386,2);
INSERT INTO stanza VALUES('ZS433','2','我心不愿徘徊旧地,<br/>疑惑四起,恐惧来袭;<br/>人虽宁愿姑且安逸,<br/>我心却在更高之地。<br/>','',59387,3);
INSERT INTO stanza VALUES('ZS433','3','虽有恶者火箭攻击,<br/>我要安坐诸天界里;<br/>信心听见乐歌洋溢,<br/>发自最美,最高之地。<br/>','',59388,4);
INSERT INTO stanza VALUES('ZS433','4','登上山巅,只看见你,<br/>荣光将我心眼开启;<br/>安息在望,仍要求祈:<br/>“主,领我往更高之地。”<br/>','',59389,5);
INSERT INTO stanza VALUES('ZS434','1','每当我们尝主美善,<br/>总是丰富有盈余;<br/>祂赐福杯充盈满溢,<br/>供应充足永不渝。<br/>祂的宝库从不匮乏,<br/>无限无量何充足;<br/>十足量器,连摇带按,<br/>上尖下流何丰富,<br/>祂的供应从不吝惜,<br/>向属祂者时倾注。<br/>','',59390,1);
INSERT INTO stanza VALUES('ZS434','2','每当我们从父领受,<br/>总是丰富有盈余;<br/>祂所量给总是上好,<br/>感谢领受永无虞。<br/>祂赐满足丰富深厚,<br/>供应我需必无误;<br/>自从我心能够领畧,<br/>祂的富足和看顾,<br/>所有心愿因祂满足,<br/>祂外不再有所慕。<br/>','',59391,2);
INSERT INTO stanza VALUES('ZS434','3','每当我们饱尝主爱,<br/>总是丰富有盈余;<br/>阔、长、高、深无法测度,<br/>岂只应付我所需?<br/>无人言语能以尽述,<br/>祂的甘美和富庶;<br/>我们只有希奇感戴,<br/>祂名泱漭且全足,<br/>安然投靠祂爱胸膛,<br/>赞美祂名到永古。<br/>','',59392,3);
INSERT INTO stanza VALUES('ZS435','1','耶稣十架阴影下,<br/>我今欢然站立;<br/>如在炎热疲乏之地,<br/>寻得磐石荫蔽。<br/>旷野之中安居无虞,<br/>途中亦享安息;<br/>日间暑溽,操烦重压<br/>都不能将我袭。<br/>','',59393,1);
INSERT INTO stanza VALUES('ZS435','2','此避难所经试验─<br/>稳妥、可悦、甘甜！<br/>天来恩爱、至上公义<br/>在此竟可两全。<br/>如同先祖梦中所见,<br/>梯子立地顶天,<br/>借我救主钉死木架,<br/>人竟与天结联。<br/>','',59394,2);
INSERT INTO stanza VALUES('ZS435','3','阴间虽扩张其欲,<br/>开口噬人无数,<br/>在我却已尽失权势,<br/>因有十架隔阻。<br/>如同儆夫把守险途,<br/>十架居间耸立,<br/>伸展双臂施行拯救,<br/>永死诅咒消弭。<br/>','',59395,3);
INSERT INTO stanza VALUES('ZS435','4','自从我眼得看见,<br/>耶稣木上流血,<br/>忍辱、受死全是为我,<br/>此景难以磨灭。<br/>痛悔之心顿生感赞,<br/>希奇天来恩惠:<br/>荣耀之爱何竟临及,<br/>我这如蛆之辈。<br/>','',59396,4);
INSERT INTO stanza VALUES('ZS435','5','哦,十字架阴影下,<br/>我得永远安居;<br/>恩主面光我所欣羡,<br/>其他亮光无需。<br/>今世荣华任其消逝,<br/>得失于我无差;<br/>羞惭舍却罪恶、自己,<br/>惟夸荣耀十架。<br/>','',59397,5);
INSERT INTO stanza VALUES('ZS436','1','基督所赐丰满福分,<br/>是否渴慕能得着?<br/>主所命定得胜生活,<br/>秘诀是否已掌握?<br/>答案明示于祂圣言:<br/>“基督是我们生命;”<br/>只要向祂敞开心怀,<br/>凭信取用祂丰盛。<br/>','',59398,1);
INSERT INTO stanza VALUES('ZS436','2','基督受死将你救赎,<br/>且要居衷掌王权;<br/>在你里外显祂能力,<br/>日复一日时加添。<br/>在你不能,在祂都能─<br/>祂灵要作工你身;<br/>“不再是我,乃是基督”─<br/>你要见证此深恩。<br/>','',59399,2);
INSERT INTO stanza VALUES('ZS436','3','神的丰满住祂里面,<br/>你在祂里得丰盛;<br/>起来,取用儿子名分,<br/>切勿辜负父恩情。<br/>全是恩典,绝不迟误,<br/>只要赞美来领受;<br/>神圣供备永无不足,<br/>凭祂而活何饶优。<br/>','',59400,3);
INSERT INTO stanza VALUES('ZS436','4','主我前来,单纯信靠,<br/>你的圣言永不变,<br/>信你救赎洗罪有能,<br/>信你得胜、得荣冕。<br/>但愿你那无穷生命<br/>带爱从我流不息,<br/>临及暗中无望人群,<br/>引领多人来归依。<br/>','',59401,4);
INSERT INTO stanza VALUES('ZS437','1','哦主,你话如同粮仓,<br/>供应充足、多方;<br/>凡饥饿者都可来此<br/>荣耀,丰富饱尝。<br/>你话又如深处宝矿,<br/>稀有珍物尽藏;<br/>凡寻求者来此挖掘,<br/>必得至宝无上。<br/>','',59402,1);
INSERT INTO stanza VALUES('ZS437','2','你话犹如众星发亮,<br/>光芒四射辉煌;<br/>天程旅客在此光中<br/>属天,家乡直往。<br/>你话又如军器库房,<br/>收藏全备军装;<br/>争战虽长,终必奏凯,<br/>因有供备无量。<br/>','',59403,2);
INSERT INTO stanza VALUES('ZS437','3','愿我宝爱你的圣言,<br/>尽享矿藏富源;<br/>愿我取用荣耀丰富<br/>光中,生活无间。<br/>愿我寻得话中兵器,<br/>靠此夸胜敌前;<br/>挥动那灵可靠的剑,<br/>为主权益争战。<br/>','',59404,3);
INSERT INTO stanza VALUES('ZS437','4','哦,永活神生命的话,<br/>你是神的光辉;<br/>得你,我就得神自己<br/>并脱,属地缠累。<br/>求主赐我正直的灵,<br/>话中得你智慧;<br/>犹如孩童心中单纯,<br/>转向属天恩惠。<br/>','',59405,4);
INSERT INTO stanza VALUES('ZS438','1','主,教导我祷告,<br/>不要外邦世俗老套,<br/>不用天然技巧,<br/>每日简单将你圣名求告。<br/>主,愿你长在我里。<br/>','',59406,1);
INSERT INTO stanza VALUES('ZS438','2','主,你在我心中,<br/>乃是奇妙生命之种;<br/>愿你分赐更丰,<br/>在我里面完成所动善工。<br/>主,愿你长在我里。<br/>','',59407,2);
INSERT INTO stanza VALUES('ZS438','3','主,使我心柔輭,<br/>你知我心一切为难;<br/>呼求你名不断,<br/>翻动我心除去硬石阻拦。<br/>主,愿你长在我里。<br/>','',59408,3);
INSERT INTO stanza VALUES('ZS438','4','主,你光照明亮,<br/>暴露我总让你失望;<br/>但你仍赐盼望,<br/>生命种子必定发苗生长。<br/>主,愿你长在我里。<br/>','',59409,4);
INSERT INTO stanza VALUES('ZS438','5','主,倒空我所有─<br/>灵里贫穷毫无保留;<br/>愿你生命涌流,<br/>将我浸透生命达到成熟。<br/>主,愿你长在我里。<br/>','',59410,5);
INSERT INTO stanza VALUES('ZS438','6','主,使我心纯洁,<br/>有你充满,作我一切,<br/>我就一无所缺,<br/>心思情感意志更新不歇。<br/>主,愿你长在我里。<br/>','',59411,6);
INSERT INTO stanza VALUES('ZS438','7','主,铭刻我心上,<br/>愿你深入我心土壤,<br/>天天有路扩长,<br/>生命种子带进国度显彰。<br/>主,愿你长在我里。<br/>','',59412,7);
INSERT INTO stanza VALUES('ZS438','7','主,你长在我里！<br/>生命力量无可匹敌,<br/>必拯救我到底,<br/>以你生命将我更新不已。<br/>主,愿你长在我里。<br/>','',59413,8);
INSERT INTO stanza VALUES('ZS439','1','神阿,你的大爱将我围困,<br/>有如强潮澎湃迫我而来;<br/>不再自缚,全人欢然投顺,<br/>好让你爱流过,毫无阻碍。<br/>','',59414,1);
INSERT INTO stanza VALUES('ZS439','2','困迫之爱,大能有谁能档?<br/>爱潮汹涌,我岂能再顽固?<br/>我神,你的恩慈有谁能抗?<br/>我今投诚不再依然如故。<br/>','',59415,2);
INSERT INTO stanza VALUES('ZS439','3','天上之爱攻破我的天然,<br/>修直心思、意念所有途径,<br/>漫溢我情,纯净所有意愿,<br/>使你纯洁生命流通不停。<br/>','',59416,3);
INSERT INTO stanza VALUES('ZS439','4','如此,我神在我居衷掌权,<br/>恩典带爱缓缓涌自心怀;<br/>恩爱江河从今流到永远,<br/>能爱,是因满享我神大爱。<br/>','',59417,4);
INSERT INTO stanza VALUES('ZS440','1','哦主,圣化我们,加添你的自己;<br/>愿你宝贵人位扩展在我衷里,<br/>使你荣耀召会在此显为实际;<br/>哦主,求你加添自己。<br/>','',59418,1);
INSERT INTO stanza VALUES('ZS440','chorus','哦主,今日圣化我们,<br/>舍此无路满足神心。<br/>惟愿你作人位,扩展徧及四围;<br/>哦主,今日圣化我们。<br/>','',59419,2);
INSERT INTO stanza VALUES('ZS440','2','哦主,洁净我们,向我们心说话;<br/>洗涤我们全人,直至圣别无瑕。<br/>愿你活话扩长,来将我们圣化;<br/>哦主,求你洁净圣化。<br/>','',59420,3);
INSERT INTO stanza VALUES('ZS440','chorus','哦主,今日洁净我们,<br/>不容天然生命留存。<br/>美丽、荣耀添加,<br/>皆因你的说话;<br/>哦主,今日洁净我们。<br/>','',59421,4);
INSERT INTO stanza VALUES('ZS440','3','哦主,滋养我们,惟你是真食物;<br/>只需吃饱喝足,变化自然显出。<br/>惟有得你喂养;我们才真满足;<br/>哦主,求你滋养眷顾。<br/>','',59422,5);
INSERT INTO stanza VALUES('ZS440','chorus','哦主,今日滋养我们,<br/>老旧、天然洗涤净尽。<br/>求你来施洁净,<br/>又将我们充盈;<br/>哦主,今日滋养我们。<br/>','',59423,6);
INSERT INTO stanza VALUES('ZS440','4','哦主,顾惜我们,以你柔爱养育;<br/>借你温情抚慰,眷顾我们所需。<br/>輭化刚硬石心,好来施情占据;<br/>哦主,今日顾惜我们。<br/>','',59424,7);
INSERT INTO stanza VALUES('ZS440','chorus','哦主,今日顾惜我们,<br/>冷淡、死沉全都驱尽。<br/>当你怀搋紧紧,<br/>我们能不欢欣?<br/>哦主,今日顾惜我们。<br/>','',59425,8);
INSERT INTO stanza VALUES('ZS440','5','哦主,荣化我们,借你内里运行;<br/>非为个人明亮,乃为召会得荣。<br/>愿你得着新妇,成就你爱经营;<br/>哦主,求你在我运行。<br/>','',59426,9);
INSERT INTO stanza VALUES('ZS440','chorus','哦主,今日运行我身,<br/>妆饰新妇迎你再临。<br/>愿你开展扩充,<br/>召会荣上加荣,<br/>哦主,今日荣化我们。<br/>','',59427,10);
INSERT INTO stanza VALUES('ZS441','1','求主赐下神圣启示,<br/>使我有光得看见,<br/>你作生命何其真实,<br/>在我灵中时增添;<br/>还要不断充满浸透,<br/>从我灵向外开广,<br/>每一部分让你占有,<br/>你就安家我心房。<br/>','',59428,1);
INSERT INTO stanza VALUES('ZS441','2','非照己意追求完美,<br/>品行端正人称羡,<br/>也非改良外在行为,<br/>举止稳重似完全;<br/>乃是基督活的人位,<br/>与我灵中相调和,<br/>','',59429,2);
INSERT INTO stanza VALUES('ZS441','3','求主使我更深经历,<br/>生活、工作全凭你,<br/>言语、行动、态度、定意,<br/>只求单单出于你。<br/>拒绝虚空教训、<br/>道理,放下规条和力劲,<br/>且在我心独居首位,<br/>使我凭祂而活着。<br/>使我活着惟一凭倚,<br/>是你涌流的生命。<br/>','',59430,3);
INSERT INTO stanza VALUES('ZS441','4','生命感觉我肯响应,<br/>你的生命就流通;<br/>膏油涂抹丰厚运行,<br/>使我活出你性情。<br/>前我凭靠己意、己力,<br/>纵有成就亦速逝;<br/>今我只愿照你心意,<br/>活你─永远的“我是”。<br/>','',59431,4);
INSERT INTO stanza VALUES('ZS441','5','如此我愿被主充满,<br/>使我全人成圣别;<br/>放下老旧宗教观念,<br/>道理、规条全弃绝。<br/>荣耀基督我心安家,<br/>将祂自己时添加;<br/>生命供应无以复加,<br/>全备、充足我所夸。<br/>','',59432,5);
INSERT INTO stanza VALUES('ZS442','1','基督要使寻求祂者,<br/>成为烟柱和卧榻,<br/>且成华轿、荣耀冠冕,<br/>主必作成绝无差。<br/>','',59433,1);
INSERT INTO stanza VALUES('ZS442','chorus','祂的佳偶,祂心所爱,<br/>富有吸引,祂喜悦;<br/>夺得祂心,怡悦祂意,<br/>在祂眼中何超绝。<br/>','',59434,2);
INSERT INTO stanza VALUES('ZS442','2','然而黑影尚未飞逝,<br/>基督尚未全满足;<br/>祂要得着生长园子,<br/>成为祂所爱新妇。<br/>','',59435,3);
INSERT INTO stanza VALUES('ZS442','3','园中石榴、上好果子、<br/>凤仙、哪哒、番红花、<br/>菖蒲、肉桂、没药、沉香,<br/>各种香料全归祂。<br/>','',59436,4);
INSERT INTO stanza VALUES('ZS442','4','基督进到自己园中,<br/>采了没药和香料,<br/>尝了蜂蜜,饮了酒奶,<br/>丰富享受,何美好！<br/>','',59437,5);
INSERT INTO stanza VALUES('ZS442','5','佳美园子产生材料,<br/>经过变化被建造,<br/>成为圣城使神满意,<br/>且使仇敌全窜逃。<br/>','',59438,6);
INSERT INTO stanza VALUES('ZS442','6','“我的佳偶,美如得撒,<br/>秀美如耶路撒冷。”<br/>美妙、绝佳,令人赞赏,<br/>主的心意得完成。<br/>','',59439,7);
INSERT INTO stanza VALUES('ZS443','1','基督乃是真葡萄树,<br/>我们是祂真枝子;<br/>住在主里,让祂内住,<br/>生命流通永不止。<br/>','',59440,1);
INSERT INTO stanza VALUES('ZS443','chorus','葡萄树,真住处,<br/>是我主与我联属;<br/>与主互住时刻无阻,<br/>我就得识祂丰富。<br/>','',59441,2);
INSERT INTO stanza VALUES('ZS443','2','祂乃是话内住我灵,<br/>说话丰富且应时;<br/>神圣发言儆醒倾听,<br/>“互住”经历才真实。<br/>','',59442,3);
INSERT INTO stanza VALUES('ZS443','3','我们若是全心爱主,<br/>就必遵行祂吩咐;<br/>如此必能实际、深入,<br/>居住祂里享富足。<br/>','',59443,4);
INSERT INTO stanza VALUES('ZS443','4','祂爱住在我们里面,<br/>我们也住祂爱里;<br/>生命交通和谐、甘甜,<br/>带来喜乐无可比。<br/>','',59444,5);
INSERT INTO stanza VALUES('ZS443','5','如此互住何等宝贵,<br/>亲密、甜美又丰富,<br/>结出美果丰硕累累,<br/>神、人喜乐同满足。<br/>','',59445,6);
INSERT INTO stanza VALUES('ZS444','1','神是光,在祂里面毫无黑暗污秽;<br/>交通于祂面光,何等甘美。<br/>光中行,神儿子耶稣的血必洗净<br/>一切的罪。<br/>','',59446,1);
INSERT INTO stanza VALUES('ZS445','1','耶稣基督已登宝座,<br/>我们与祂同坐;<br/>世界、撒但、罪、己脱落,<br/>不能再将我迫！<br/>基督一次永远受死,<br/>救赎大工完成;<br/>可怜罪奴得新地位,<br/>与祂同命共荣。<br/>','',59447,1);
INSERT INTO stanza VALUES('ZS445','2','欢然安居活神家中-<br/>荣耀召会生活;<br/>坦然昂首进至圣所,<br/>不再下沉退缩！<br/>魂的旷野不再留恋,<br/>圣所已在身后;<br/>至圣之处永远住留,<br/>全人被神浸透。<br/>','',59448,2);
INSERT INTO stanza VALUES('ZS445','3','更美之约己经立定,<br/>荣耀遗赠有三:<br/>生命之律大能高超,<br/>将我变化完全;<br/>我作祂民,祂作我神,<br/>神圣福分无穷;<br/>对神认识深刻主观,<br/>惟凭内里生命。<br/>','',59449,3);
INSERT INTO stanza VALUES('ZS445','4','此外神已忘记我罪,<br/>不义一概宽恕;<br/>皆因救主十架代死,<br/>我罪全都清除;<br/>罪案全勾,不再追究,<br/>罪过都己消踪;<br/>生命之律灵中引我,<br/>救恩路上直行。<br/>','',59450,4);
INSERT INTO stanza VALUES('ZS445','5','加略妙死双重功绩,<br/>为神经纶效力:<br/>生命之律运行无碍,<br/>罪的拦阻绝迹！<br/>大工完成住入安息,<br/>主今安坐天上;<br/>新约遗赠我们全享,<br/>凭祂代祷馨香。<br/>','',59451,5);
INSERT INTO stanza VALUES('ZS445','6','惟愿弃绝老旧观念,<br/>取用遗赠丰富;<br/>主说成了我们享用,<br/>天天赞美不住！<br/>听大祭司幔内呼召-<br/>“前进！”直到路终:<br/>直至达成终极目标,<br/>荣耀圣城撒冷！<br/>','',59452,6);
INSERT INTO stanza VALUES('ZS446','1','用你大能将我加强,<br/>主,使我进入全人深处,<br/>使我灵刚强、我心顺服,<br/>让你能安家无阻。<br/>','',59453,1);
INSERT INTO stanza VALUES('ZS446','chorus','进入我心！进入我心！<br/>来安家我心,主耶稣！<br/>满带丰富,恩主,请进！<br/>来安家我心,主耶稣！<br/>','',59454,2);
INSERT INTO stanza VALUES('ZS446','2','在我心房开展,主耶稣,<br/>你的安家是我所慕;<br/>从我灵中向外开展,<br/>主,占有我全心各部。<br/>','',59455,3);
INSERT INTO stanza VALUES('ZS446','3','来安家我心中,主耶稣,<br/>使我全心成你住处;<br/>愿你充满,显明你丰足,<br/>来安家我心,恩主。<br/>','',59456,4);
INSERT INTO stanza VALUES('ZS446','4','你必运行,充盈成就,主,<br/>超我所想、所能求诉;<br/>我今敞开,切求主进入,<br/>现在就进来居住。<br/>','',59457,5);
INSERT INTO stanza VALUES('ZS447','1','有一人,有一人,宝座上坐着;<br/>有一人,作先锋,道路已开拓;<br/>这人子是耶稣,我们乐追随;<br/>祂已得胜,我们与祂同登位。<br/>','',59458,1);
INSERT INTO stanza VALUES('ZS447','2','向上去,向上去,与祂同登极;<br/>向上去,经罪世,胜黑暗忧悒;<br/>撒但虽将人掳,我们得释放,<br/>且必同主高升,宝座上为王。<br/>','',59459,2);
INSERT INTO stanza VALUES('ZS447','3','同蒙召,同蒙召,命定作君王;<br/>同蒙召,成后嗣,世界甘埋葬;<br/>但我们岂够格,配得这命定?<br/>求主搜寻、焚烧,将我全炼净。<br/>','',59460,3);
INSERT INTO stanza VALUES('ZS447','4','来搜寻,来搜寻,焚烧我内心;<br/>来搜寻,来焚烧,渣滓都除尽;<br/>毋畏惧,毋退缩,当清楚看见:<br/>如此搜寻、焚烧乃是主恩眷。<br/>','',59461,4);
INSERT INTO stanza VALUES('ZS447','5','一道虹,一道虹,显人子周围;<br/>一道虹,在宣告,信实永不颓:<br/>神审判厉如火,我本当遭祸,<br/>竟蒙赦宥,前来赞祂恩深阔。<br/>','',59462,5);
INSERT INTO stanza VALUES('ZS448','1','神的旨意在这宇宙,全在祂与人关系;<br/>为此主成那灵,进入人灵,与人调为一。<br/>我们为此欢喜,因能有分神永远旨意─<br/>调和是神心意。<br/>','',59463,1);
INSERT INTO stanza VALUES('ZS448','chorus','神人调和,阿利路亚！<br/>神人调和,阿利路亚！<br/>神人调和,阿利路亚！<br/>调和是神心意。<br/>','',59464,2);
INSERT INTO stanza VALUES('ZS448','2','人里有一比心思、情感、意志更深之地,<br/>是神所造的灵,好使人能盛装祂自己。<br/>祂且要从人灵里涌出,像江河无止息─<br/>调和是神心意。<br/>','',59465,3);
INSERT INTO stanza VALUES('ZS448','3','在主恢复中,我们已看见神永远心意,<br/>就是凭祂而活,天天经历祂神圣三一;<br/>转回我们的灵,一直留在调和的灵里─<br/>调和是神心意。<br/>','',59466,4);
INSERT INTO stanza VALUES('ZS448','4','我们看见人子,在灯台中间保养顾惜,<br/>眼目如火、双脚像铜,为神的恢复效力;<br/>祂要完成神的旨意,以得着团体实体─<br/>调和是神心意。<br/>','',59467,5);
INSERT INTO stanza VALUES('ZS448','5','我们何等需要更深经历与神调为一,<br/>行事为人、言语思想,更多得着祂自己。<br/>为着调和,我们愿意奉献,全照祂心意─<br/>调和是神心意。<br/>','',59468,6);
INSERT INTO stanza VALUES('ZS448','6','新耶路撒冷来自我们每日对神经历,<br/>她是神、人二性调和,完全显出的终极;<br/>一同有分享受那城我们喜乐真无比─<br/>调和是神心意。<br/>','',59469,7);
INSERT INTO stanza VALUES('ZS449','1','神的作为公义、公平,<br/>道路、法则皆完备;<br/>祂的行动全然正直,<br/>配得我们的赞美。<br/>祂的定罪、祂的要求,<br/>无一不显祂公义;<br/>律法已将我们判罪,<br/>审判座前谁能立?<br/>','',59470,1);
INSERT INTO stanza VALUES('ZS449','2','律法虽定我们死罪,<br/>神爱始终未遗弃;<br/>公义审判归神儿子,<br/>因祂作了我代替。<br/>阿利路亚！我们今享<br/>基督救赎的功绩:<br/>买回我们归神自己,<br/>甚至成为祂的义。<br/>','',59471,2);
INSERT INTO stanza VALUES('ZS449','3','神的性情圣别超凡,<br/>祂之所是乃至圣;<br/>祂要圣化我们全人,<br/>使其合乎祂性情。<br/>从我灵中向外扩展,<br/>祂要安家我心房;<br/>直到全人内里各部,<br/>尽得更新像祂样。<br/>','',59472,3);
INSERT INTO stanza VALUES('ZS449','4','生机拯救过程奇妙,<br/>全由生命来效力;<br/>每日每时都可经历,<br/>主的救恩何实际。<br/>时常思念那灵的事,<br/>心思就成为生命;<br/>主在我里得着地位,<br/>我得变化成神圣。<br/>','',59473,4);
INSERT INTO stanza VALUES('ZS449','5','荣耀乃是神的彰显,<br/>祂之所是显无尽;<br/>也是救赎终极一步,<br/>具体显明于我身。<br/>荣耀乃是神圣生命<br/>圣别过程的完成;<br/>也是生命供应目的─<br/>身体变像显殊荣。<br/>','',59474,5);
INSERT INTO stanza VALUES('ZS449','6','为此,我们热切等待<br/>得赎、被提、得荣耀;<br/>神的丰满显明于地,<br/>耶稣见证全显照。<br/>我们就要完全像主,<br/>永远彰显祂荣形;<br/>神的众子显于荣耀,<br/>宇宙万有共欢腾。<br/>','',59475,6);
INSERT INTO stanza VALUES('ZS449','7','因神怜悯,蒙神选召,<br/>荣耀定命得有分;<br/>非借人的定意奔跑,<br/>全是神主宰怜悯。<br/>野橄榄枝竟得联于<br/>栽种橄榄的丰富;<br/>生机联结,分享肥汁,<br/>长成荣耀的国度。<br/>','',59476,7);
INSERT INTO stanza VALUES('ZS449','7','在这美妙过程之中,<br/>日日因生命成圣;<br/>满心感谢祂所赐与,<br/>召会生活的供应。<br/>在此全享神的自己,<br/>实际、真切、又富饶;<br/>同作众子,同为后嗣,<br/>召会生活何荣耀！<br/>','',59477,8);
INSERT INTO stanza VALUES('ZS450','1','神话语赐盼望何等坚定:<br/>主来时,我全人必得赎;<br/>但患难带来疑惑与忧惧,<br/>盼望隐,异象逐渐糢糊。<br/>磨难间,本不知如何祷告,<br/>无言中,只有深处叹息;<br/>虽輭弱,有那灵帮同担负,<br/>照着神,为我代祷求祈。<br/>','',59478,1);
INSERT INTO stanza VALUES('ZS450','2','主,我是不敢求受苦更深,<br/>只望能免去试炼袭击;<br/>你若许,求将苦杯速撤去,<br/>但必须是你旨,非我意。<br/>真希奇！此时艰难虽四布,<br/>深处竟安然一无罣虑;<br/>因有神大爱浇灌我心内,<br/>溢我魂,驱尽所有疑惧。<br/>','',59479,2);
INSERT INTO stanza VALUES('ZS450','3','何稳妥！神主宰调度万有,<br/>全为使爱祂者得益处;<br/>勿让我因眼瞎竟不知悉,<br/>无一事非祂爱所部署。<br/>乃是父答应那灵的代求,<br/>赐我以诸般试炼、煎熬;<br/>患难中,愿主扩增我减少,<br/>直到我充满基督荣耀。<br/>','',59480,3);
INSERT INTO stanza VALUES('ZS450','4','神儿女既有神儿子生命,<br/>祂岂不借管教施成全?<br/>如器皿在窰匠甄陶手中,<br/>岂不经琢磨使荣美现?<br/>神衷心所渴望是得众子,<br/>模成祂长子荣耀形像;<br/>我们既是基督许多弟兄,<br/>岂能不与祂一式一样?<br/>','',59481,4);
INSERT INTO stanza VALUES('ZS450','5','何盼望！同基督作神后嗣;<br/>何辉煌！救恩要达至极。<br/>今时的苦楚似沉痛难当,<br/>不配与将来荣耀相比。<br/>凡事上,我们已得胜有余,<br/>乃借祂-那爱我们的主;<br/>荣耀日,神众子就要显出,<br/>受造物享自由何满足！<br/>','',59482,5);
INSERT INTO stanza VALUES('ZS451','1','神已赐、神已赐,神今已赐与;<br/>宝贵信、神能力、并极大应许;<br/>我们信而领受,供备全得着,<br/>就能凭此长大成熟进神国。<br/>','',59483,1);
INSERT INTO stanza VALUES('ZS451','2','何宝贵、何宝贵,同样的宝贵,<br/>信是神所分给,在众圣心内;<br/>我们虽会摇摆,此信不稍减,<br/>且要逐日扶持、加强到永远。<br/>','',59484,2);
INSERT INTO stanza VALUES('ZS451','3','神能力、神能力,如泉源丰盛,<br/>既刚强,又得胜,今在我运行;<br/>在我里赐生命,所需全供应,<br/>使我活出敬虔,彰显神荣形。<br/>','',59485,3);
INSERT INTO stanza VALUES('ZS451','4','借荣耀、借美德,神呼召我们,<br/>又宝贵又极大应许作我分;<br/>脱情欲、脱败坏,世界失权能,<br/>借应许我们得有分神性情。<br/>','',59486,4);
INSERT INTO stanza VALUES('ZS451','5','基督是神能力,在我灵里居,<br/>祂又是神话语─神全备应许;<br/>读祂话,摸祂灵,天天当操练─<br/>呼求、读经、祷告,生命时加添。<br/>','',59487,5);
INSERT INTO stanza VALUES('ZS451','6','神能力、神应许,同宝贵的信,<br/>我们既已得着,应用当殷勤;<br/>多供应、勤浇灌,生命日丰硕,<br/>信心种子必结出爱的美果。<br/>','',59488,6);
INSERT INTO stanza VALUES('ZS451','7','要增长、要增长,主里要增长,<br/>勿闲懒,结美果,丰富又多方;<br/>我们罪已得洁,救恩不该忘,<br/>不再眼瞎,乃要天天让主长。<br/>','',59489,7);
INSERT INTO stanza VALUES('ZS451','7','当殷勤、当殷勤,日日长生命,<br/>神呼召和拣选因此得坚定;<br/>我们与神种子配合使成长,<br/>就必进入神国享丰富无量。<br/>','',59490,8);
INSERT INTO stanza VALUES('ZS451','9','宝贵信、神应许、神圣的能力─<br/>神供备何充足,舍此不他依;<br/>主,我们献自己,愿与你合作,<br/>靠恩长大,直至丰富进神国。<br/>','',59491,9);
INSERT INTO stanza VALUES('ZS452','1','宝贵信仰已经一次<br/>永远交付圣徒,<br/>持守信仰、竭力争辩<br/>乃是我们托付。<br/>','',59492,1);
INSERT INTO stanza VALUES('ZS452','chorus','我们深知所信的是谁,<br/>并且凭信、爱、借内住圣灵,<br/>保守那美好的托付─<br/>健康话语的规范。<br/>','',59493,2);
INSERT INTO stanza VALUES('ZS452','2','美好托付务必持守,<br/>绝不稍微偏离;<br/>这是神经纶的标的,<br/>是主恢复目的。<br/>','',59494,3);
INSERT INTO stanza VALUES('ZS452','3','当用清洁无亏良心,<br/>持守信仰奥秘;<br/>行事为人庄重、圣别,<br/>只活圣别无比！<br/>','',59495,4);
INSERT INTO stanza VALUES('ZS452','4','健康话语善美规范,<br/>凭信和爱持守;<br/>不同教训、虚空言谈,<br/>弃绝,一概不留！<br/>','',59496,5);
INSERT INTO stanza VALUES('ZS452','5','传讲健康纯全教训─<br/>合乎敬虔真理;<br/>保守托付,持守信仰,<br/>生求得主欢喜。<br/>','',59497,6);
INSERT INTO stanza VALUES('ZS452','6','主,使我们忠于所托,<br/>殷勤教导、传扬;<br/>言语、为人、爱、信、纯洁,<br/>都作信徒榜样。<br/>','',59498,7);
INSERT INTO stanza VALUES('ZS453','1','我生活有何等奇妙的大改变,<br/>当我对主话说“阿们”;<br/>主生命何丰富在我里时加添,<br/>当我对主话说“阿们”。<br/>','',59499,1);
INSERT INTO stanza VALUES('ZS453','chorus','对主话我要说“阿们”,<br/>对主话我要说“阿们”;<br/>如此让主安家,我全人得变化-<br/>对主话我要说“阿们”。<br/>','',59500,2);
INSERT INTO stanza VALUES('ZS453','2','神自己在我里成就我所不能,<br/>当我对主话说“阿们”;<br/>这改变何真实,众人皆能印证,<br/>当我对主话说“阿们”。<br/>','',59501,3);
INSERT INTO stanza VALUES('ZS453','3','我流荡得止息,永不再走迷途,<br/>当我对主话说“阿们”;<br/>老爱好、旧思虑不觉间尽消除,<br/>当我对主话说“阿们”。<br/>','',59502,4);
INSERT INTO stanza VALUES('ZS453','4','凭信心过生活,我已寻得秘诀:<br/>只要对主话说“阿们”;<br/>主于我既真实又宝贵,胜一切-<br/>只要对主话说“阿们”。<br/>','',59503,5);
INSERT INTO stanza VALUES('ZS453','5','爱弟兄,无虚假,相调中,益亲热,<br/>当我对主话说“阿们”;<br/>为建造主居所,与众圣相结合,<br/>当我对主话说“阿们”。<br/>','',59504,6);
INSERT INTO stanza VALUES('ZS453','6','我的主,我的爱,惟愿你快显现-<br/>对你话我要说“阿们”;<br/>我朝夕所思慕是见你面对面-<br/>对你话我要说“阿们”。<br/>','',59505,7);
INSERT INTO stanza VALUES('ZS453','chorus','对你话我要说“阿们”,<br/>对你话我要说“阿们”。<br/>你说,“我必快来！”我全心说“阿们”;<br/>对 你话我要说“阿们“。<br/>','',59506,8);
INSERT INTO stanza VALUES('ZS454','1','恩主我心至爱，今我归你怀抱！<br/>你外任何事物，不能将我搅扰。<br/>你曾以爱呼召，我曾被你吸引；<br/>旷野道路默默，爱情结盟紧紧。<br/>','',59507,1);
INSERT INTO stanza VALUES('ZS454','2','我愿奉献自己，全因你的大爱；<br/>此情主未遗忘，时刻铭记心怀。<br/>幼年曙光黎明，前途一片灿烂，<br/>坛火原不该灭，直至天光烂漫。<br/>','',59508,2);
INSERT INTO stanza VALUES('ZS454','3','偶像夺取人心，叫人醉倒倾迷，<br/>无知的心受拐，不觉偷被牵离。<br/>只是幼年恩爱，仍然呼召不已，<br/>能否保持此心，永为未耕之地？<br/>','',59509,3);
INSERT INTO stanza VALUES('ZS454','4','虽我羞步迟疑，你仍诱导依依，<br/>赐我葡萄果园，使我陶醉忘己；<br/>应声亚割幽谷，踏上指望之门，<br/>怜爱脸光披露，重获久别良人。<br/>','',59510,4);
INSERT INTO stanza VALUES('ZS454','5','前虽汗劳一身，仅知工作主人，<br/>今你成我丈夫，以爱聘娶委身。<br/>弃绝破裂池子，归依活水泉源，<br/>享受爱情筵宴，沈溺恩典深渊。<br/>','',59511,5);
INSERT INTO stanza VALUES('ZS454','6','恩主今我属你，与我心心相系，<br/>只望不再我活，永远与你合一，<br/>你我只一空间，密切个人情深，<br/>我愿消失你里，直至永世不分。<br/>','',59512,6);
INSERT INTO stanza VALUES('ZS455','1','为这一天，我献感谢，<br/>全人再次交托与主联结；<br/>祂是生命活水，使我满足欢畅，<br/>从我灵里向外流淌，将我溢漫且从我显彰。<br/>','',59513,1);
INSERT INTO stanza VALUES('ZS455','2','无须忧虑，无须怀疑，<br/>惟寻求祂的国和祂的义，<br/>每天都有需要，凡事向祂述说，<br/>祂赐平安深且广阔，时时保守使我永稳妥。<br/>','',59514,2);
INSERT INTO stanza VALUES('ZS455','3','常常喜乐，不住祷告，<br/>凡事谢恩无何比这更美好；<br/>主是永活源头，作我一切供应，<br/>凡我交托在祂手中，祂能保全一直到路终。<br/>','',59515,3);
INSERT INTO stanza VALUES('ZS456','1','转！黑暗丢在背后,<br/>光,在前头。<br/>转！虚空世界脱落,<br/>爱,在左右。<br/>','',59516,1);
INSERT INTO stanza VALUES('ZS456','chorus','欢然迈入新境地,<br/>凭神脱去陈旧,<br/>神调人新生活,<br/>盼望得荣时候。<br/>走,跟耶稣脚踨！<br/>今我们得神圣生命不朽,<br/>享受神儿子自由;<br/>走,同基督行动！<br/>流,随圣灵涌流！<br/>经纶的神正在呼召,<br/>一个新人─我人生所投。<br/>','',59517,2);
INSERT INTO stanza VALUES('ZS456','2','转！往新方向寻求,<br/>进入方舟。<br/>转！公义、和平、喜乐,<br/>是神的国。<br/>','',59518,3);
INSERT INTO stanza VALUES('ZS456','3','转！离弃狭窄自我,<br/>神旨承托。<br/>转！国度福音展扩,<br/>刚强开拓。<br/>','',59519,4);
INSERT INTO stanza VALUES('ZS457','1','我在这里,天使睽睽注目;<br/>主权已交出,如释重负,<br/>不再为世界奴仆。<br/>我在这里！今全属基督,<br/>愿跟随卑微耶稣,<br/>直至掌权国度！<br/>','',59520,1);
INSERT INTO stanza VALUES('ZS457','2','我在这里,世人瞠目惊喟:<br/>“竟如此枉费?”但我无悔,<br/>因知道所信是谁！<br/>我在这里！得上好机会,<br/>将宝贵玉瓶打碎,<br/>见证祂的甘美。<br/>','',59521,2);
INSERT INTO stanza VALUES('ZS457','3','我在这里,撒但已在抖颤:<br/>真相终揭穿─大巴比伦,<br/>要被神烈火审判。<br/>我在这里！永不向后看！<br/>上到楼房来奉献,<br/>福音地极传遍！<br/>','',59522,3);
INSERT INTO stanza VALUES('ZS457','4','我在这里,我看见祂微笑:<br/>祂的一声“好”,价值何高,<br/>胜一切人的荣耀。<br/>我在这里！归回为建造;<br/>黑夜已深将破晓,<br/>惟愿祂来得早！<br/>','',59523,4);
INSERT INTO stanza VALUES('ZS458','1','我本世人与你为敌,<br/>弃绝你恩漠视你意,<br/>有人对我讲你心肠,<br/>要我归回满你切望,<br/>而我总是置之不理,<br/>引我回家,真是不易。<br/>','',59524,1);
INSERT INTO stanza VALUES('ZS458','2','等我归来得见你面,<br/>才知救恩如此完全:<br/>如虫世人成为信徒,<br/>不过与你和好初步,<br/>直到你我联调为一,<br/>才是与你和好极地。<br/>','',59525,2);
INSERT INTO stanza VALUES('ZS458','3','一重幔子我已经过,<br/>欢然来到你的圣所,<br/>二重幔子虽已裂开,<br/>我的经历仍是不逮,<br/>但你却要引我进入,<br/>至圣所在,享你供输。<br/>','',59526,3);
INSERT INTO stanza VALUES('ZS458','4','和好还是完全分别,<br/>离弃不法,除去不洁,<br/>肉身和灵一切污秽,<br/>需你荣光如同雨沛,<br/>尽都洗去,洗得尽净,<br/>每一部分完全成圣。<br/>','',59527,4);
INSERT INTO stanza VALUES('ZS458','5','拯救之日,悦纳时候,<br/>要我与你和好无隔,<br/>我愿竭力靠你大能,<br/>奔这“完全和好”路程,<br/>你的恩典不致徒受,<br/>你的救恩我能全得。<br/>','',59528,5);
INSERT INTO stanza VALUES('ZS458','6','当我看见你的心意,<br/>你所要我到达境地,<br/>我又羡慕,我又惊惧,<br/>依我能力我怎能及?<br/>求你作工用你恩典,<br/>使我不住,不住向前。<br/>','',59529,6);
INSERT INTO stanza VALUES('ZS459','1','主,你旨意我愿凭,<br/>主,你圣言我听,不让闲话漏生命,<br/>不让俗务扰灵。<br/>求你向我多吸引,<br/>使我与你更亲,<br/>让我常见你荣形,<br/>紧紧跟随你行。<br/>','',59530,1);
INSERT INTO stanza VALUES('ZS459','2','主,你道路我愿走,<br/>不管风狂雨骤,<br/>虽然有忧也有愁,<br/>主恩却更深厚。<br/>我今追求虽不够,<br/>有时会贪优游,<br/>求你仍把我收留,<br/>用爱把我浸透。<br/>','',59531,2);
INSERT INTO stanza VALUES('ZS459','3','主,你十架我愿负,<br/>面向你的国度,<br/>虽然流泪虽然苦,<br/>你手却常搀扶。<br/>前面路程已不长,<br/>属天家乡在望,<br/>有朝,父怀我安躺,<br/>我就喜乐欢畅。<br/>','',59532,3);
INSERT INTO stanza VALUES('ZS459','4','主,你荣耀快显现,<br/>这是我心所羡,<br/>你的应许不改变,<br/>你来将不迟延。<br/>求主使我能自勉,<br/>不向世界流连,<br/>我眼能常望着天,<br/>心能向你恋恋。<br/>','',59533,4);
INSERT INTO stanza VALUES('ZS460','1','我的手不能停作主的圣工,<br/>因我早已对主应许永事奉;<br/>虽然有时会遇患难和贫穷,<br/>但我愿不改变向主的尽忠;<br/>虽然有时会遇患难和贫穷,<br/>但我愿不改变向主的尽忠;<br/>我的手不能停作主的圣工,<br/>因我早已对主应许永事奉。<br/>','',59534,1);
INSERT INTO stanza VALUES('ZS460','2','我的脚不能离十架的窄路,<br/>因那是我爱主所走过路途;<br/>虽然是有眼泪也多有痛苦,<br/>但我仍愿前进不稍有回顾;<br/>虽然是有眼泪也多有痛苦,<br/>但我仍愿前进不稍有回顾;<br/>我的脚不能离属天的家乡,<br/>因那是神计画终极的彰显。<br/>','',59535,2);
INSERT INTO stanza VALUES('ZS460','3','我的眼常仰望属天的家乡,<br/>因那是神计画终极的彰显;<br/>在那里无忧愁也再无悲伤,<br/>只有神恩和爱是我所安享;<br/>在那里无忧愁也再无悲伤,<br/>只有神恩和爱是我所安享;<br/>我的眼常仰望属天的家乡,<br/>因那是神计画终极的彰显。<br/>','',59536,3);
INSERT INTO stanza VALUES('ZS460','4','我的心不能忘救主的再来,<br/>因那是众圣徒久久所悬待;<br/>到那时见主面安息在主怀,<br/>就与主不分开永与主同在。<br/>到那时见主面安息在主怀,<br/>就与主不分开永与主同在;<br/>我的心不能忘救主的再来,<br/>因那是众圣徒久久所悬待。<br/>','',59537,4);
INSERT INTO stanza VALUES('ZS461','1','你竟独行这条十架窄路,<br/>客西马尼,别后成殊途。<br/>羊群逃散,牧人独蹒跚,<br/>幽暗掌权,炭火添冷淡。<br/>','',59538,1);
INSERT INTO stanza VALUES('ZS461','chorus','在人手中被推挤,<br/>在人口中被唾弃,<br/>你面如坚石肃然伫立;<br/>主,爱你却不敢认你。<br/>','',59539,2);
INSERT INTO stanza VALUES('ZS461','2','你何独行这条十架窄路?<br/>前说恩言,今被人厌诅！<br/>叹息声灭,欺凌却暴烈,<br/>神的爱子,何竟遭天绝！<br/>','',59540,3);
INSERT INTO stanza VALUES('ZS461','chorus','我无法停止泪弹,<br/>当你忧伤回首看,<br/>想起曾说与你同苦难;<br/>主我的爱何等不堪。<br/>','',59541,4);
INSERT INTO stanza VALUES('ZS461','3','你终独行这条十架窄路,<br/>各各他山,罪愆独背负。<br/>钉痕的手,困我似囚牢?<br/>无力脱开,枪扎的怀抱?<br/>','',59542,5);
INSERT INTO stanza VALUES('ZS461','chorus','起初的爱未忘记,<br/>跟随的心却离弃,<br/>你爱我,竟为我舍性命;<br/>主我爱你却舍何情?<br/>','',59543,6);
INSERT INTO stanza VALUES('ZS461','4','与你同行这条十架窄路,<br/>断绝世界,今生葬泥土。<br/>“你爱我吗?”是的我爱你！<br/>不再别依,随你脚踪起。<br/>','',59544,7);
INSERT INTO stanza VALUES('ZS461','chorus','去罢！属地的贿赂！<br/>去罢！虚假的祝福！<br/>这条古老的十架窄路,<br/>主爱你的人当同赴。<br/>','',59545,8);
INSERT INTO stanza VALUES('ZS462','1','大哉！敬虔奥秘！神显于肉体,<br/>支搭帐幕,丰满恩典何实际;<br/>神圣奥秘三一,今在我们里,<br/>基督奥秘身体彰显神自己。<br/>','',59546,1);
INSERT INTO stanza VALUES('ZS462','chorus','何神圣！何奥秘！三一竟可进入。<br/>何荣耀！何有福！得享一切丰富。<br/>那灵充满浸透全人每一部,<br/>直到长大成熟,作荣美新妇。<br/>','',59547,2);
INSERT INTO stanza VALUES('ZS462','2','神已经过过程又终极完成,<br/>成为复合那灵,眷临赐生命;<br/>神圣膏油涂抹─神性调人性,<br/>我们得祂分赐,有分神性情。<br/>','',59548,3);
INSERT INTO stanza VALUES('ZS462','3','我们今蒙怜悯,出宗教营外,<br/>跟随基督,不致退缩遭毁坏;<br/>享受那灵运行,和围绕云彩,<br/>经历调和,将身体建造起来。<br/>','',59549,4);
INSERT INTO stanza VALUES('ZS462','4','基督生机身体,是父神的家,<br/>我们互为肢体,调和又配搭;<br/>基督乃是生命、人位和彰显,<br/>神圣奥秘范围,现今得扩大。<br/>','',59550,5);
INSERT INTO stanza VALUES('ZS462','5','我们得着生命,有父神性情,<br/>且借达到圣别,成为一见证;<br/>今在父荣耀里,将三一显明,<br/>至终达到圣城-新耶路撒冷。<br/>','',59551,6);
INSERT INTO stanza VALUES('ZS463','1','创世之前,蒙神拣选,<br/>在你爱里,在你面前成为圣别。<br/>虽然我们常是善变,<br/>但你怜悯和恩典却仍然眷怜。<br/>心清、心輭、心爱与心安,<br/>我要运用我灵,照着你的心意,<br/>心得坚固,使我活你面前,<br/>全然圣别,得以完全。<br/>','',59552,1);
INSERT INTO stanza VALUES('ZS463','2','我们蒙召,虽然年幼,<br/>却受吸引,愿在你前成为圣别。<br/>信心工作、爱心劳苦<br/>并盼望忍耐,是我们属灵特质。<br/>我主,我灵、我心、我全人,<br/>全然倾倒你前,竭力操练敬虔,<br/>靠你宝血,使我履败履站,<br/>胜过肉体,全然圣别。<br/>','',59553,2);
INSERT INTO stanza VALUES('ZS464','1','当遇难处使我踌躇,<br/>属天异象渐糢糊,<br/>四围充满艰辛拦阻,<br/>似乎无力再随主;<br/>但主告我祂曾历世途,<br/>经忧患无枕首处,<br/>被挂木上尝苦胆酸醋,<br/>忧苦祂已担负。<br/>','',59554,1);
INSERT INTO stanza VALUES('ZS464','2','灵中听主题醒嘱咐,<br/>需要凭信走窄路;<br/>祂的患难要我补足,<br/>经历十架学顺服。<br/>祂话内住,时将我鼓舞,<br/>使我得力再举步,<br/>欢然随主历短暂苦楚,<br/>永远荣耀在目。<br/>','',59555,2);
INSERT INTO stanza VALUES('ZS464','3','看见建造异象蓝图,<br/>放胆前行无旁骛;<br/>所有境遇是为帮助,<br/>信徒生命早成熟。<br/>何等荣耀,有分神建筑,<br/>金、银、宝石非草、木,<br/>让神安居,且成主新妇,<br/>主的再临催促。<br/>','',59556,3);
INSERT INTO stanza VALUES('ZS464','4','等我行完此生路途,<br/>我要迎见亲爱主,<br/>且与众圣同声欢呼,<br/>此路原来不孤独。<br/>“好！你这良善忠信奴仆”─<br/>公义的主要宣布;<br/>主人快乐得欢然进入,<br/>才识你恩丰足。<br/>','',59557,4);
INSERT INTO stanza VALUES('ZS465','1','神心所倾,撒冷美丽;<br/>锡安高峰,满祂情衷。<br/>神人合并,互为安息,<br/>至深美意,愿否响应?<br/>','',59558,1);
INSERT INTO stanza VALUES('ZS465','chorus','亲爱良人,我愿随你同行;<br/>荣耀君王,今你据我全心。<br/>作得胜者,被提满足你意,<br/>锡安山上同你站立。<br/>','',59559,2);
INSERT INTO stanza VALUES('ZS465','2','平凡如我,竟入圣城;<br/>心羡锡安:得胜赤诚。<br/>荣耀异象,引我脚踪,<br/>撇下缠累,踏上旅程。<br/>','',59560,3);
INSERT INTO stanza VALUES('ZS465','3','主恩眷临,祂爱激励;<br/>凭信筑坛,“以撒”为祭。<br/>世途成烬,馨香盈溢,<br/>神圣经纶,此生意义。<br/>','',59561,4);
INSERT INTO stanza VALUES('ZS465','4','云彩围绕,同奔向前;<br/>灵中争战,配搭无间。<br/>己意弃绝,身体得建,<br/>高峰在望,实际出现。<br/>','',59562,5);
INSERT INTO stanza VALUES('ZS465','5','爱里同工,劳苦不息;<br/>流中跟随,同魂同心。<br/>国度福音,徧传全地,<br/>建造锡安,迎你再临。<br/>','',59563,6);
INSERT INTO stanza VALUES('ZS466','1','晨光东方升起，唤我起来歌唱，<br/>祂的日头医治亮光，使我苏醒舒畅。<br/>主恩如同甘露，温润冰冷心灵，<br/>在祂慈爱脸光之下，偶像阴影遁形。<br/>','',59564,1);
INSERT INTO stanza VALUES('ZS466','chorus','新的黎明，新的复兴，主我奉献，奉献今天；<br/>靠你得胜，因你更新，直到恩主显现。<br/>','',59565,2);
INSERT INTO stanza VALUES('ZS466','2','时刻扎根主里，生活开花发芽；<br/>天天起来拾取吗哪，爱慕追求主话。<br/>不住恒切祷告，单纯如百合花，<br/>灌满新酒和橄榄油，散发基督荣华。<br/>','',59566,3);
INSERT INTO stanza VALUES('ZS466','3','主必加倍补还，蝗虫吃去时光，<br/>祂的复活生命大能，吞灭失败死亡。<br/>借祂不断显现，步步唱上行诗，<br/>今生功名烟消云逝，谱写神圣历史。<br/>','',59567,4);
INSERT INTO stanza VALUES('ZS466','4','不再劳碌经营，自己破烂草厦，<br/>同心合意上山取木，起来建造神家。<br/>清理打开家门，迎接万邦罪人，<br/>彼此欢呼带回禾捆，牧养群羊归神。<br/>','',59568,5);
INSERT INTO stanza VALUES('ZS466','5','复兴之律来临，昼夜循环不息；<br/>随时随地洋溢赞美，福音遍传四极。<br/>团体神人生活，在地如同在天，<br/>求主时刻保守我们，新鲜直到主前。<br/>','',59569,6);
INSERT INTO stanza VALUES('ZS467','1','荣耀的基督这超越的宝贝，<br/>吸引我们打破玉瓶，<br/>并将一切全然枉费在祂身上；<br/>枉费在祂身上；<br/>燔祭坛上的火要一直烧着，不可熄灭，<br/>好使我们消减成灰，<br/>而成为新耶路撒冷。<br/>我们在帐棚里过团体神人生活，<br/>并接受国度的操练，<br/>好对世界作相反的见证；<br/>为着时期满足时的经纶，<br/>我们需要打开家并栽种召会树，<br/>好成为万邦的祝福。<br/>我们需要打开家并栽种召会树，<br/>好成为万邦的祝福。<br/>','',59570,1);
INSERT INTO stanza VALUES('ZS468','1','谁能配如此的枉费?<br/>谁会肯如此的牺牲;<br/>谁能述说这样的结果！<br/>谁能拥有这样的丰收！<br/>虽已杯倾却仍满溢！<br/>虽已盘罄却仍满席！<br/>从未求福却叫别人得福,<br/>未尝求报却叫别人得饱。<br/>不再受缚,不再无奈;<br/>不再作难,不再悲哀;<br/>永远涌流,永远施爱;<br/>永远倾舍,永远澎湃。<br/><br/>甘心以死亡换来生命的溢洋。<br/>甘心受破碎以散发复活馨香。<br/>这正是你留下的脚踪,<br/>呼召人默默的跟从。<br/>从他们那脸上的笑容,<br/>看见遥远荣耀的路终。<br/><br/>我已算清这条道路的代价,<br/>就此乐意为你把一切放下;<br/>只愿成为供应人喜乐的奠祭,<br/>不断倾倒直至此生止极。<br/>主阿,让我爱！你作我赏赉！<br/>让你的同在永远不离开。<br/>使我维持你里面的喜乐,<br/>让我的眼泪消失在永世。<br/>','',59571,1);
INSERT INTO stanza VALUES('ZS469','1','歌中之歌乃是描绘,<br/>神生命与建造;<br/>基督新妇生命历程,<br/>皆显明于表号,<br/>皆显明于表号。<br/>','',59572,1);
INSERT INTO stanza VALUES('ZS469','2','她之爱主初如骏马,<br/>属世牵连未断;<br/>奔跑迅捷、力大无匹,<br/>刚强却是天然,<br/>刚强却是天然！<br/>','',59573,2);
INSERT INTO stanza VALUES('ZS469','3','观念逐日因主改变,<br/>眼目渐似鸽眼;<br/>无何能与主爱比拟,<br/>惟非她所倚,<br/>惟主是她所羡,<br/>惟主是她所羡！<br/>','',59574,3);
INSERT INTO stanza VALUES('ZS469','4','她之于主有如百合,<br/>单纯靠主怜悯;<br/>属地劳苦非她所倚,<br/>惟主是她吸引,<br/>惟主是她吸引！<br/>','',59575,4);
INSERT INTO stanza VALUES('ZS469','5','在主面前又如良鸽,<br/>藏身磐石穴中,<br/>享主复活、升天生命,<br/>有爱不知惊恐,<br/>有爱不知惊恐！<br/>','',59576,5);
INSERT INTO stanza VALUES('ZS469','6','且成烟柱,立地顶天,<br/>旷野流荡止息;<br/>意志降服,与主合拍,<br/>馨香之气盈溢,<br/>馨香之气盈溢！<br/>','',59577,6);
INSERT INTO stanza VALUES('ZS469','7','看哪,竟成主的卧榻,<br/>在这骇人夜间,<br/>供主躺卧,使主安息,<br/>仇敌崩溃逃窜,<br/>仇敌崩溃逃窜！<br/>','',59578,7);
INSERT INTO stanza VALUES('ZS469','7','还要成为一乘华轿,<br/>为着将主盛装;<br/>万王之王借她行动,<br/>在她得着彰显,<br/>在她得着彰显！<br/>','',59579,8);
INSERT INTO stanza VALUES('ZS469','9','利巴嫩木品质高贵,<br/>充满复活人性;<br/>银柱支撑─赎稳固,<br/>金底显神性情,<br/>金底显神性情！<br/>','',59580,9);
INSERT INTO stanza VALUES('ZS469','10','紫色坐垫君尊宝贵-<br/>王权为其座位;<br/>众女向王所献爱情,<br/>尽都铺陈其内,<br/>尽都铺陈其内！<br/>','',59581,10);
INSERT INTO stanza VALUES('ZS469','11','婚娶日近,心中欢喜,<br/>王要得胜凯归;<br/>得着佳偶作祂荣冕,<br/>与祂全然匹配,<br/>与祂全然匹配。<br/>','',59582,11);
INSERT INTO stanza VALUES('ZS469','12','关锁的园,只为良人<br/>产生宝贵材料;<br/>生命丰盛、美丽芬芳,<br/>更为神圣建造,<br/>更为神圣建造。<br/>','',59583,12);
INSERT INTO stanza VALUES('ZS469','13','佳偶屹立犹如京城,<br/>益显华丽秀美;<br/>又如军队展开旌旗,<br/>威武,使敌败退,<br/>威武,使敌败退！<br/>','',59584,13);
INSERT INTO stanza VALUES('ZS469','14','借着吃主与祂联调,<br/>新妇妆饰整齐;<br/>生命变化带进建造,<br/>成功神圣旨意,<br/>成功神圣旨意。<br/>','',59585,14);
INSERT INTO stanza VALUES('ZS470','1','神圣真理深广无边,<br/>人智岂能局限?<br/>一己残见,囿于时空,<br/>勿将天光遮掩。<br/>崭新亮光,更美盼望,<br/>惟愿人心能见:<br/>主话真光越照越明,<br/>释放真理无限。<br/>','',59586,1);
INSERT INTO stanza VALUES('ZS470','2','天来圣谕普赐万邦,<br/>历代人当称羡;<br/>谁竟擅用无知言语,<br/>阻挡神圣意念?<br/>如同宇宙阔长高深,<br/>浩瀚洋海无边:<br/>主话真光越照越明,<br/>释放真理无限。<br/>','',59587,2);
INSERT INTO stanza VALUES('ZS470','3','先圣迈开追寻旅程,<br/>暗中摸索而前;<br/>晨光乍显,旭辉渐明,<br/>直至如日中天。<br/>荣耀太阳,愿你显身,<br/>辉煌光线尽现。<br/>主话真光越照越明,<br/>释放真理无限。<br/>','',59588,3);
INSERT INTO stanza VALUES('ZS470','4','幽谷已过,昂首上行,<br/>直攻真理之巅;<br/>前人肩上极目一览,<br/>始识主智深远;<br/>清明空中,天乐得聆,<br/>才知主富绵延:<br/>主话真光越照越明,<br/>释放真理无限。<br/>','',59589,4);
INSERT INTO stanza VALUES('ZS470','5','哦愿父神借灵运行,<br/>基督安家心间,<br/>好使众圣能同领畧,<br/>神圣大爱艰言;<br/>如此神圣实际得以<br/>日日加增不断:<br/>主话真光越照越明,<br/>释放真理无限。<br/>','',59590,5);
INSERT INTO stanza VALUES('ZS534','1','哦,主将我帕子去除,<br/>赐下真实启示;<br/>哦,主使我异象清楚,<br/>知你恢复所是。<br/>','',59591,1);
INSERT INTO stanza VALUES('ZS534','2','你从死里复活能力,<br/>我借启示知悉;<br/>大能传输借信经历,<br/>引我到召会里。<br/>','',59592,2);
INSERT INTO stanza VALUES('ZS534','3','你的大能将我释放,<br/>脱离烦扰俗务;<br/>你的大能为我开广<br/>进入召会路途。<br/>','',59593,3);
INSERT INTO stanza VALUES('ZS534','4','我今进入地方召会,<br/>愿以你为人位;<br/>外面旧人日渐销毁,<br/>心向你能绝对。<br/>','',59594,4);
INSERT INTO stanza VALUES('ZS534','5','我接受你作人位主,<br/>与你同钉十架;<br/>里面之人得着恢复,<br/>你在我心安家。<br/>','',59595,5);
INSERT INTO stanza VALUES('ZS534','6','当众肢体都愿舍己,<br/>荣耀身体得显;<br/>人数虽多,人位同一,<br/>新人在地出现。<br/>','',59596,6);
INSERT INTO stanza VALUES('ZS534','7','召会生活─一个新人,<br/>显于各地召会;<br/>你的身体是团体人,<br/>显出一个人位。<br/>','',59597,7);
INSERT INTO stanza VALUES('ZS535','1','基督圣心深爱慕,<br/>无他,惟有召会;<br/>言语、计划并行动,<br/>皆以她为依归。<br/>此情此意永坚定,<br/>无何能以摇撼;<br/>召会萦绕祂心头,<br/>远在创世之前。<br/>','',59598,1);
INSERT INTO stanza VALUES('ZS535','2','万有尚都未开始,<br/>祂已筹划全备,<br/>要得祂心所钟爱,<br/>与祂喜悦匹配。<br/>万物受造虽奇妙,<br/>并非祂所专注;<br/>深藏祂心难追测,<br/>乃一荣耀新妇。<br/>','',59599,2);
INSERT INTO stanza VALUES('ZS535','3','赢得佳偶相与共,<br/>是祂所最心许;<br/>美哉,此情永不移,<br/>此意始终不渝。<br/>人虽被罪深诱害,<br/>无助、无望、无倚;<br/>祂心所望从未弃,<br/>恋慕之情依依。<br/>','',59600,3);
INSERT INTO stanza VALUES('ZS535','4','祂爱何广难估量,<br/>借祂怜悯临及;<br/>亲自施恩来找寻,<br/>深哉,智慧无匹。<br/>倾注爱情得她心,<br/>此爱惟神尽知;<br/>倾倒祂命作祭物,<br/>馨香上扬不止。<br/>','',59601,4);
INSERT INTO stanza VALUES('ZS535','5','今在复活荣耀里,<br/>与她亲近无距,<br/>祂的笑脸时显露,<br/>情深,难以言喻。<br/>日近一日,祂新妇<br/>单单将祂注视,<br/>浸沐新郎荣耀中,<br/>等条被提之时。<br/>','',59602,5);
INSERT INTO stanza VALUES('ZS536','1','何等可爱,哦,何宝贵,<br/>是主众地方召会！<br/>我魂羡慕,甚至渴想,<br/>主,你院宇极华美。<br/>我心渴慕,我灵切望<br/>能交通于众召会;<br/>为此我向活神呼吁,<br/>我心、我命不别归。<br/>','',59603,1);
INSERT INTO stanza VALUES('ZS536','2','心中想往锡安大道,<br/>如此之人为有福;<br/>必因我主行走有力,<br/>终日颂赞与称祝。<br/>召会生活时有乐歌,<br/>因靠我神胜险阻;<br/>虽经巴迦流泪之谷,<br/>却使成为泉源处。<br/>','',59604,2);
INSERT INTO stanza VALUES('ZS536','3','在你召会住留一日,<br/>胜似别处住千日;<br/>我主乃是日头、盾牌,<br/>至微肢体亦得恃。<br/>恩典、荣耀从主倾注,<br/>无一好处祂不赐;<br/>如此安居召会之中,<br/>必蒙祝福永无止。<br/>','',59605,3);
INSERT INTO stanza VALUES('ZS537','1','当日挪亚照神吩咐,努力建造方舟,<br/>多人观看,他的话却无人留意、接受;<br/>惟独挪亚蒙恩,听见神话语谨遵守,<br/>全心建造方舟,不浪费任何的时候。<br/>','',59606,1);
INSERT INTO stanza VALUES('ZS537','chorus','今日耶稣的见证,已向我们显明:<br/>见证的方舟建立在众地方召会中。<br/>','',59607,2);
INSERT INTO stanza VALUES('ZS537','2','那时的世代堕落、弯曲、悖谬又腐朽,<br/>地上的罪恶甚大,人心邪恶无可救;<br/>但挪亚持守异象,抵挡放荡的潮流,<br/>不计较任何代价,建造见证的方舟。<br/>','',59608,3);
INSERT INTO stanza VALUES('ZS537','3','当时也有多人说他们是在敬拜神,<br/>他们事奉、献祭,却不能有分神救恩;<br/>神所渴望建造,他们不耻、不愿过问,<br/>思念属地之事,以致与恶者同浮沉。<br/>','',59609,4);
INSERT INTO stanza VALUES('ZS537','4','一日,方舟建成,神将八人关入里头,<br/>天上窗户尽都敞开,大雨倾泻不休;<br/>水势浩力,但方舟内挪亚安息无忧,<br/>地虽淹没,他却漂浮其上,安全得救。<br/>','',59610,5);
INSERT INTO stanza VALUES('ZS537','5','这方舟就是当代神在地得胜见证,<br/>是一个团体的人,将神荣总全显明;<br/>神也要我们同被建造,显出祂丰盛,<br/>使神显现于肉体,在众地方召会中。<br/>','',59611,6);
INSERT INTO stanza VALUES('ZS537','6','儆醒！莫随洪流浮沉而偏离神心意;<br/>当让耶稣的见证如火在我心燃起！<br/>地方召会乃是方舟,将神见证无遗,<br/>为此我们献上自己,现今世代远离。<br/>','',59612,7);
INSERT INTO stanza VALUES('ZS538','1','在众召会涌流不息─弟兄相爱;<br/>生命、光、爱,流通、洋溢─弟兄相爱。<br/>联结为一,毫无猜忌;<br/>照神接纳,不凭人意;<br/>不再让神圣灵忧戚─弟兄相爱。<br/>','',59613,1);
INSERT INTO stanza VALUES('ZS538','2','爱中洗涤,交通无碍─弟兄相爱;<br/>以爱裹伤,彼此怀搋─弟兄相爱。<br/>凡事相信,凡事忍耐,<br/>凡事盼望,凡事遮盖;<br/>彼此担就,恩慈相待─弟兄相爱。<br/>','',59614,2);
INSERT INTO stanza VALUES('ZS538','3','犹如枝子结果丰盈─弟兄相爱;<br/>又是肢体同命同荣─弟兄相爱。<br/>弃绝天然,己命不从,<br/>只随那灵,狭路前行;<br/>出死入生在此证明─弟兄相爱。<br/>','',59615,3);
INSERT INTO stanza VALUES('ZS538','4','欢然上行,乐歌四起─弟兄相爱！<br/>惧怕、忧疑尽都绝迹─弟兄相爱！<br/>和睦同居,美善无比,<br/>灵与生命─坚固根基;<br/>建造锡安,达到终极─弟兄相爱。<br/>','',59616,4);
INSERT INTO stanza VALUES('ZS538','5','生命种子生长不已─弟兄相爱;<br/>“非拉铁非”涌流、普及─弟兄相爱。<br/>主名、主话,持守不离,<br/>神圣之爱浇灌、充溢;<br/>得胜有余,无何能敌─弟兄相爱！<br/>','',59617,5);
INSERT INTO stanza VALUES('ZS539','1','爱的召会─非拉铁非,<br/>请听荣耀的事实;<br/>天上圣别、真实的主,<br/>述说关于你的事。<br/>国度之门由祂掌管,<br/>大衞钥匙祂手持;<br/>“我已开门,无人能关”─<br/>祂话既出必如是。<br/>','',59618,1);
INSERT INTO stanza VALUES('ZS539','2','阿利路亚！非拉铁非,<br/>行为、工作主悦纳;<br/>看哪,主赐敞开的门,<br/>无人比你更通达。<br/>因你稍微有点能力,<br/>也曾持守祂活话;<br/>未曾否认祂的圣名,<br/>忠信见证殊可嘉。<br/>','',59619,2);
INSERT INTO stanza VALUES('ZS539','3','蒙爱召会,非拉铁非,<br/>忍耐的话既遵守,<br/>主必保守,免你经过<br/>全地试炼的时候。<br/>你的仇敌终必俯伏,<br/>知主爱你到永久;<br/>“我必快来,你要持守,<br/>免得冠冕被夺走。”<br/>','',59620,3);
INSERT INTO stanza VALUES('ZS539','4','阿利路亚！得胜信徒<br/>必定从主得奖赏;<br/>在神殿中不再出去,<br/>作为柱子显坚刚。<br/>神的圣名、主的新名,<br/>圣城之名写身上;<br/>三一之神与人联结,<br/>互住、调和显辉煌。<br/>','',59621,4);
INSERT INTO stanza VALUES('ZS539','5','耶路撒冷从天而降,<br/>神圣新城何荣耀;<br/>珍珠之门、碧玉城墙,<br/>珍贵材料同建造。<br/>非拉铁非─弟兄相爱─<br/>得胜新妇主所要;<br/>众召会中,凡有耳者,<br/>当听那灵在呼召！<br/>','',59622,5);
INSERT INTO stanza VALUES('ZS540','1','荣耀异象，我已看见；神的经纶是我人生意义！ <br/>属地缠累，我已全弃；主的恢复是我全心所倾！ <br/>神圣三一，神圣分赐，基督作生命，那灵为实际； <br/>神的召会，基督身体，新耶路撒冷，圣城我所期。<br/>','',59623,1);
INSERT INTO stanza VALUES('ZS540','chorus','主！我们再献上自己，一生交你训练手里， <br/>制作、甄陶，不断经历，成神尊贵、荣耀大器！ <br/>深愿主恢复的独特，作我生活、工作标记， <br/>建造身体，豫备新妇，接你再来，满足你心意！<br/>','',59624,2);
INSERT INTO stanza VALUES('ZS540','2','天上人间有一生活；生机联结里，神人同生活； <br/>复活大能全备供应，模成基督之死，不再是我！ <br/>随主榜样，步祂脚踪，出宗教营外，幔内过生活， <br/>与神同行，服于元首；成宇宙新人，带进神的国。<br/>','',59625,3);
INSERT INTO stanza VALUES('ZS540','3','同作肢体，相互提携，爱里同建造，灵中共勉励； <br/>分赐基督，供应那灵，我们相调和，在主里合一。 <br/>拼上全人，同心合意，实行活力排，建造主身体； <br/>广传福音，教导真理，照着神牧养，达到新复兴。<br/>','',59626,4);
INSERT INTO stanza VALUES('ZS540','4','锡安大道，心中想往，虽经流泪谷，前进不稍退； <br/>我们愿付一切代价，顾到神权益，异象永不违。 <br/>不让我主再受迟延，作祂得胜者，铺路迎祂归， <br/>击败仇敌，与祂同王，神经纶高峰---锡安何华美！<br/>','',59627,5);
INSERT INTO stanza VALUES('ZS541','1','神造万有美好、有序,<br/>徧布天、地、空中;<br/>仇敌竟来败坏、占据,<br/>阻挠神旨完成。<br/>那权能者恣意背判,<br/>先来将地篡夺;<br/>又在空中蓄势争战,<br/>建立黑暗之国。<br/>','',59628,1);
INSERT INTO stanza VALUES('ZS541','2','神的心意是要在地<br/>建立祂的国度,<br/>好使祂能掌权治理,<br/>显明祂智丰足。<br/>地虽荒废,渊面黑暗,<br/>神来恢复、再造,<br/>且按祂的神圣意念,<br/>造人与祂相肖。<br/>','',59629,2);
INSERT INTO stanza VALUES('ZS541','3','恶者撒但又将人骗,<br/>诱离神恩源头;<br/>亚伯拉罕见神显现,<br/>蒙召族类起首。<br/>神领选民脱离埃及,<br/>经过红海、野疆,<br/>进入迦南应许美地,<br/>神国在此彰显。<br/>','',59630,3);
INSERT INTO stanza VALUES('ZS541','4','以色列民竟弃神治,<br/>属地君主依恃;<br/>神国彰显再次丧失,<br/>直至大衞之时;<br/>借他神得执政道路,<br/>神国重新恢复;<br/>百姓终究仍是失误,<br/>被掳,失去国度。<br/>','',59631,4);
INSERT INTO stanza VALUES('ZS541','5','人虽不堪,神不失败,<br/>亲来成为肉身;<br/>向人宣告“:应当悔改！<br/>因为国度临近。”<br/>神人耶稣,完美绝佳,<br/>为神权柄执掌;<br/>撒但将祂钉死十架,<br/>不过显其愚妄。<br/>','',59632,5);
INSERT INTO stanza VALUES('ZS541','6','妙哉,耶稣救赎成就,<br/>复活胜过死亡,<br/>为要使地得蒙拯救,<br/>脱离撒但捆绑;<br/>且成那灵进入人里,<br/>召会借此建立─<br/>生命洋溢,混乱消弭,<br/>神旨通行于地。<br/>','',59633,6);
INSERT INTO stanza VALUES('ZS541','7','如今召会在地显明,<br/>神国丰满实际;<br/>神圣权柄尽得通行,<br/>使地归神管理。<br/>我们在此为神执政,<br/>撒但只能逃遁;<br/>如此召会作神见证,<br/>国度不再藏隐。<br/>','',59634,7);
INSERT INTO stanza VALUES('ZS542','1','主的恢复需要我们<br/>归回顾到神权益;<br/>出到营外胜过堕落,<br/>建造召会主身体。<br/>灵中站住合一立场,<br/>持守基督作生命;<br/>陈明真理至死忠信,<br/>作主独一活见证。<br/>','',59635,1);
INSERT INTO stanza VALUES('ZS542','chorus','何其怜悯,我们得以<br/>一生作你独特子民;<br/>为你恢复我们全倾,<br/>紧紧跟随不稍偏离。<br/>终极异象管制规律,<br/>枉费一切为你身体;<br/>同奔赛程神旨得成,<br/>荣耀新妇迎你再临！<br/>','',59636,2);
INSERT INTO stanza VALUES('ZS542','2','荣耀召会为神所有,<br/>纯洁无瑕何神圣;<br/>凭神生命活神性情,<br/>窄门狭路灵中行。<br/>照神旨意生活事奉,<br/>伟大成就非我望;<br/>凭着祷告、那灵与话,<br/>与神同工同前往。<br/>','',59637,3);
INSERT INTO stanza VALUES('ZS542','3','独一之神独一心意,<br/>独一经纶已开启;<br/>三一神里神圣的一,<br/>扩大彰显于身体。<br/>独一水流全人投进,<br/>同心合意来事奉;<br/>独一交通、独一工作,<br/>终极完成于撒冷。<br/>','',59638,4);
INSERT INTO stanza VALUES('ZS542','4','时代异象、时代职事,<br/>同负一轭同脚踪;<br/>留在其中抵挡败落,<br/>健康话语当遵从。<br/>使徒教训成我口味,<br/>不同教训不容忍。<br/>同吹独一争战号声,<br/>忠信教导神经纶。<br/>','',59639,5);
INSERT INTO stanza VALUES('ZS543','1','倘若我躭延,你也可以知道<br/>在神的家中当怎样行;<br/>这家就是活神的召会,<br/>真理的柱石和根基。<br/>并且,大哉！敬虔的奥秘！<br/>这是众所公认的,就是:<br/>祂显现于肉体,被称义于灵里,<br/>被天使看见,被传于万邦,<br/>被信仰于世人中,被接去于<br/>荣耀里,被接去于荣耀里。<br/>','',59640,1);
INSERT INTO stanza VALUES('ZS619','1','“同心合意”─楼房上同聚集,<br/>耶稣从者忠信祷告不息;<br/>同一盼望,每魂儆醒所期;<br/>同一目标,众人心志如一。<br/>','',59641,1);
INSERT INTO stanza VALUES('ZS619','2','“同心合意”─直等五旬能力<br/>全备灵中降临,浇灌、充溢;<br/>众见证人宣扬复活信息,<br/>活出神命开拓及于地极。<br/>','',59642,2);
INSERT INTO stanza VALUES('ZS619','3','“同心合意”─神家中何欢畅,<br/>阿利路亚！天天赞美颂扬;<br/>一心一口,基督荣耀显彰,<br/>耶稣尊名传扬达到四方。<br/>','',59643,3);
INSERT INTO stanza VALUES('ZS619','4','那灵浇灌,我们愿再经历,<br/>如同甘雨,使人复苏、得力;<br/>主的子民若真同心合意,<br/>五旬荣景就必重现此地。<br/>','',59644,4);
INSERT INTO stanza VALUES('ZS620','1','赞美父神是生命源头,<br/>我们在你宝贵名里,<br/>作你众子来彰显你。<br/>赞美父神是生命源头。<br/>在生命里,在生命里,<br/>在父生命里我们是一。<br/>在生命里,在生命里,<br/>在父生命里我们是一。<br/>','',59645,1);
INSERT INTO stanza VALUES('ZS620','2','感谢父借你宝贵圣言,<br/>用你性情浸透我们,<br/>分别我们脱离俗尘。<br/>感谢父赐你宝贵圣言。<br/>借你圣言,借你圣言,<br/>借你圣言我们成为一。<br/>','',59646,2);
INSERT INTO stanza VALUES('ZS620','3','哦,三一神的神圣荣耀！<br/>众子得享何等福分！<br/>神的荣耀彰显无尽─。<br/>哦三一神的神圣荣耀！<br/>在荣耀里,在荣耀里,<br/>在你荣耀里我们是一。<br/>','',59647,3);
INSERT INTO stanza VALUES('ZS621','1','让我们同来聚集擘饼，<br/>赞美主！因祂使我们成为一。<br/>饱尝祂，众人同心合意，<br/>作祂召会，全归祂自己。<br/>','',59648,1);
INSERT INTO stanza VALUES('ZS621','chorus','圣徒们，我们吃饼喝杯；<br/>在主里我们是一。<br/>吃喝享受，建造在一起；<br/>见证基督身体的实际。<br/>','',59649,2);
INSERT INTO stanza VALUES('ZS621','2','让我们同来聚集喝杯─是召会，<br/>宝血所买，珍贵无比；<br/>蒙救赎，众人同心合意，<br/>成就祂永远经纶目的。<br/>','',59650,3);
INSERT INTO stanza VALUES('ZS621','chorus','圣徒们，我们吃饼喝杯；<br/>在主里我们是一。<br/>吃喝享受，建造在一起；<br/>见证基督身体的实际。<br/>','',59651,4);
INSERT INTO stanza VALUES('ZS621','3','让我们一同坚定站立─是身体，<br/>就不再作孤单子粒；<br/>相调和，众人同心合意，<br/>成为一饼，彰显在各地。<br/>','',59652,5);
INSERT INTO stanza VALUES('ZS621','chorus','圣徒们，我们吃饼喝杯；<br/>在主里我们是一。<br/>吃喝享受，建造在一起；<br/>见证基督身体的实际。<br/>','',59653,6);
INSERT INTO stanza VALUES('ZS621','4','让我们作神合一子民，齐宣告：<br/>我们是一，不再分离；<br/>有真理，也有生命经历，<br/>见证神作为何等希奇。<br/>','',59654,7);
INSERT INTO stanza VALUES('ZS621','chorus','圣徒们，我们吃饼喝杯；<br/>在主里我们是一。<br/>吃喝享受，建造在一起；<br/>见证基督身体的实际。<br/>','',59655,8);
INSERT INTO stanza VALUES('ZS621','5','让我们同来聚集擘饼，<br/>赞美主！因祂使我们成为一。<br/>饱尝祂，众人同心合意，<br/>作祂召会，全归祂自己。<br/>','',59656,9);
INSERT INTO stanza VALUES('ZS622','1','看哪！桌上摆设筵席,<br/>一饼一杯,神圣表记;<br/>亲爱救主热切邀集,<br/>我们欢喜来坐席。<br/>祂来呼召,神、人同席,<br/>显明救主永远心意;<br/>丰富供应,全备、洋溢,<br/>前来同享勿迟疑。<br/>','',59657,1);
INSERT INTO stanza VALUES('ZS622','2','我们现在与祂同席,<br/>祂与我们何等亲近;<br/>阿利路亚！赞美不已！<br/>上好筵席无止尽。<br/>吃喝享受主的自己,<br/>满足我们全人全心;<br/>豫尝那日荣耀筵席,<br/>作祂新妇何欢欣。<br/>','',59658,2);
INSERT INTO stanza VALUES('ZS623','1','哦主你筵席荣耀无比！<br/>我们蒙召同你坐席,<br/>与你同住,在你家里;<br/>哦主,你筵席荣耀无比！<br/>','',59659,1);
INSERT INTO stanza VALUES('ZS623','chorus','阿利路亚！阿利路亚！<br/>阿利路亚,为这筵席。<br/>阿利路亚！阿利路亚！<br/>哦主,你筵席荣耀无比！<br/>','',59660,2);
INSERT INTO stanza VALUES('ZS623','2','哦主,你筵席何等享受！<br/>在你桌前,交通自由！<br/>阿利路亚！寻见所求;<br/>哦主,你筵席荣耀无比！<br/>','',59661,3);
INSERT INTO stanza VALUES('ZS623','3','哦主,你筵席实在宝贵！<br/>宣告你死,陈列饼杯,<br/>我魂生命再无地位,<br/>全因你筵席丰富全备。<br/>','',59662,4);
INSERT INTO stanza VALUES('ZS623','4','哦主,你筵席富有意义！<br/>饼指我们是你身体,<br/>因着你爱,我们是一;<br/>哦主,你筵席富有意义！<br/>','',59663,5);
INSERT INTO stanza VALUES('ZS623','5','哦主,你筵席令人舒畅！<br/>何等满足,将你全享,<br/>得着供应,无限无量;<br/>哦主,你筵席令人舒畅！<br/>','',59664,6);
INSERT INTO stanza VALUES('ZS623','6','哦主,你筵席将我激励！<br/>“直到你来”坚定不移,<br/>日日等候,盼望见你;<br/>哦主,你筵席将我激励！<br/>','',59665,7);
INSERT INTO stanza VALUES('ZS624','1','今日惟有识你身体,<br/>哦主,才是认识你,<br/>因此我求得蒙开启,<br/>在你肢体看见你;<br/>非仅识你元首身分─<br/>至高、个别救赎主,<br/>更见你已具体化身,<br/>显为身体的基督。<br/>','',59666,1);
INSERT INTO stanza VALUES('ZS624','2','你的圣徒多年追求,<br/>渴慕寻得你实际;<br/>举目仰望,深处探求,<br/>无非要见你自己。<br/>岂知天上荣耀基督,<br/>今乃显为祂身体;<br/>内住基督今正活出,<br/>在祂身体显无遗！<br/>','',59667,2);
INSERT INTO stanza VALUES('ZS624','3','主,我自知易于受欺,<br/>仅识你崇高至极,<br/>却未摸着你的实际,<br/>暗中摸索,凭己意。<br/>岂知在你地上肢体,<br/>我就得见你自己！<br/>永远之神显于肉体,<br/>大哉,敬虔的奥秘！<br/>','',59668,3);
INSERT INTO stanza VALUES('ZS624','4','求主勿让我再单独,<br/>囿于个人的光照;<br/>你的身体促我投入,<br/>凭“身体感”为引导。<br/>不再作那离散尘土,<br/>乃是活石被建造;<br/>如此使你心满意足,<br/>团体显明你荣耀。<br/>','',59669,4);
INSERT INTO stanza VALUES('ZS625','1','我们是神救赎子民,<br/>照祂计画成一个新人;<br/>虽来自各民族方言,<br/>祂里蒙召,合一何甘甜。<br/>是神荣耀显于地,<br/>将祂宝贵显无遗;<br/>我们是神救赎子民<br/>照祂计画成一个新人。<br/>','',59670,1);
INSERT INTO stanza VALUES('ZS625','2','十架上,规条全废弃,<br/>犹太、外邦两下成为一;<br/>主得胜,仇敌祂践踏,<br/>我们与神和好,亲“阿爸”。<br/>隔断的墙已拆除,<br/>我们是一,喊“:哦,主！”<br/>十架上,规条全废弃,<br/>犹太、外邦两下成为一。<br/>','',59671,2);
INSERT INTO stanza VALUES('ZS625','3','主,我们愿同心合意,<br/>接受你作人位,不偏离;<br/>不再凭雄心与己意,<br/>在“身体基督”里调为一。<br/>一个新人在主里,<br/>为神权益得全地;<br/>主,我们愿同心合意<br/>接受你作人位,不偏离。<br/>','',59672,3);
INSERT INTO stanza VALUES('ZS626','1','我们在灵里是一,<br/>凭神生命是一;<br/>我们过身体生活,<br/>一切分裂远离;<br/>救赎已成,隔阂全去,<br/>主里我们是一。<br/>','',59673,1);
INSERT INTO stanza VALUES('ZS626','chorus','(弟兄)<br/>弟兄们,我们是一,<br/>赞美主,赞美主！<br/><br/>(姊妹)<br/>姊妹们,我们是一,<br/>赞美主,赞美主！<br/><br/>(同声)<br/>主已成就大事,<br/>使身体合一得恢复。<br/>','',59674,2);
INSERT INTO stanza VALUES('ZS626','2','我们在灵里是一,<br/>同魂为神站立;<br/>这“一”从我们灵里<br/>向外扩展不已-<br/>心思、情感、意志都被浸透,<br/>我们是一。<br/>','',59675,3);
INSERT INTO stanza VALUES('ZS626','3','我们在灵里是一,<br/>在实际里是一;<br/>“一”是我们的实行,<br/>并非空谈、道理;<br/>在众召会之中,<br/>我们享受一的实际。<br/>','',59676,4);
INSERT INTO stanza VALUES('ZS626','4','我们在灵里是一,<br/>且在各地是一;<br/>为保守主赐的“一”,<br/>我们献上自己,<br/>使这“一”彰显于全地,<br/>叫世人都称奇。<br/>','',59677,5);
INSERT INTO stanza VALUES('ZS627','1','看哪何等美善！弟兄和睦同居;<br/>以和平相结联,所有距离全去。<br/>平安义果,神、人共享,<br/>弟兄相爱,喜乐欢畅。<br/>弟兄相爱,喜乐欢畅。<br/>','',59678,1);
INSERT INTO stanza VALUES('ZS627','2','众圣相联相依,跟随羔羊紧紧;<br/>一灵、一心、一意、一口,为荣耀神;<br/>爱里相调,紧密结联,<br/>其乐无比,非人能言。<br/>其乐无比,非人能言。<br/>','',59679,2);
INSERT INTO stanza VALUES('ZS627','3','这“一”实际出现,带来恩典无量;<br/>我们在地若天,因享甘露舒爽;<br/>上好膏油在此流淌,<br/>流自元首,众圣同享。<br/>流自元首,众圣同享。<br/>','',59680,3);
INSERT INTO stanza VALUES('ZS627','4','这“一”何等芬芳,因有恩膏溢漫;<br/>膏油四处放香,滋润、浸透、充满;<br/>凡受恩者无不赞美,<br/>满口称谢,满脸光辉。<br/>满口称谢,满脸光辉。<br/>','',59681,4);
INSERT INTO stanza VALUES('ZS627','5','凡神赎民都当有分于这膏袜;<br/>站住合一立场,享受福分包罗;<br/>膏油徧及胡须、衣襟,<br/>大小肢体同蒙深恩。<br/>大小肢体同蒙深恩。<br/>','',59682,5);
INSERT INTO stanza VALUES('ZS627','6','上好油浇亚伦,黑门露降锡安;<br/>神所命定福分,丰盈且时加添;<br/>生命之福白白临及,<br/>皆因有分宝贵合一。<br/>皆因有分宝贵合一。<br/>','',59683,6);
INSERT INTO stanza VALUES('ZS628','1','看哪,弟兄和睦同居,<br/>是何等的善,是何等的美！<br/>看哪,弟兄和睦同居,<br/>是何等的善,是何等的美！<br/>','',59684,1);
INSERT INTO stanza VALUES('ZS628','chorus','这好比那上好的油,<br/>上好的油,<br/>浇在亚伦的头上,<br/>流到胡须,<br/>又流到,流到他的衣襟;<br/>','',59685,2);
INSERT INTO stanza VALUES('ZS628','2','看哪,弟兄和睦同居,<br/>是何等的善,是何等的美！<br/>','',59686,3);
INSERT INTO stanza VALUES('ZS628','3','又好比黑门的甘露,降在锡安山;<br/>黑门的甘露,降在锡安山;<br/>因为在那里有耶和华所命定的福,<br/>就是永远的生命。<br/>','',59687,4);
INSERT INTO stanza VALUES('ZS629','1','荣耀基督显现，引我全然奉献；<br/>渴望以嘴亲子，投奔入你里面。<br/>神家是我心愿，伯特利梦实现；<br/>孤独者有居所，伯大尼家筵宴。<br/>赦免、相爱、相依，国度生活实际；<br/>和平、喜乐、公义，城中颂赞洋溢。<br/>校园、家与邦国，开展遍及全地；<br/>主名尊崇不已，见证直到地极。<br/>','',59688,1);
INSERT INTO stanza VALUES('ZS629','chorus','主，我愿献上自己， 建造你生机身体；<br/>打开家，得青年，牧养人，同成全，<br/>带进荣耀召会，让你能早归回。<br/>','',59689,2);
INSERT INTO stanza VALUES('ZS753','1','主,我爱你国度,<br/>就是你的住处;<br/>是你召会,你血所赎,<br/>你将重价已付。<br/>','',59690,1);
INSERT INTO stanza VALUES('ZS753','2','神,我爱你召会,<br/>她与世俗分别;<br/>是你眼中惟一至美,<br/>手中惟一宝贝。<br/>','',59691,2);
INSERT INTO stanza VALUES('ZS753','3','为她祷告不歇,<br/>为她昼夜流泪;<br/>补满基督患难缺欠,<br/>直至与你相会。<br/>','',59692,3);
INSERT INTO stanza VALUES('ZS753','4','她的属天行径,<br/>是我珍爱歌颂:<br/>相交甘甜,相许贞坚,<br/>爱戴、赞美无终。<br/>','',59693,4);
INSERT INTO stanza VALUES('ZS753','5','正如你的真理,<br/>必定屹立不已;<br/>那日锡安必得荣耀,<br/>光辉无比、至极。<br/>','',59694,5);
INSERT INTO stanza VALUES('ZS754','1','为主见证移民开展,<br/>谁愿蒙恩向前走?<br/>何时?何处?照主差遣,<br/>恩主面光当寻求。<br/>','',59695,1);
INSERT INTO stanza VALUES('ZS754','2','为将圣殿、圣城建立,<br/>扩展神国及全地;<br/>背判征服,混乱消弭,<br/>同心合意众如一。<br/>','',59696,2);
INSERT INTO stanza VALUES('ZS754','3','父乃源头,子作管道,<br/>那灵涌流为凭借;<br/>站住立场,灵中相调,<br/>此乃得胜的秘诀。<br/>','',59697,3);
INSERT INTO stanza VALUES('ZS754','4','主所筹画伟大、完全,<br/>激动我们全奉献;<br/>好让圣灵浸透、充满,<br/>神圣定旨得实现。<br/>','',59698,4);
INSERT INTO stanza VALUES('ZS754','5','今日在此学习多方:<br/>配搭建造、灵刚强;<br/>那日前往各城、各邦,<br/>建立灯台显荣光。<br/>','',59699,5);
INSERT INTO stanza VALUES('ZS754','6','诸天掌权需“滩头堡”─<br/>地方召会─先建立;<br/>求主兴起各地建造,<br/>实现国度为目的。<br/>','',59700,6);
INSERT INTO stanza VALUES('ZS754','7','那时,全地荣耀归你,<br/>失败、羞辱归仇敌;<br/>万民称颂你名不已,<br/>国度掌权达至极。<br/>','',59701,7);
INSERT INTO stanza VALUES('ZS754','7','有福之日不久就到,<br/>荣耀经纶得成就;<br/>喜乐、赞美达到至高,<br/>神圣管治徧万有。<br/>','',59702,8);
INSERT INTO stanza VALUES('ZS754','9','赞美圣父,阿利路亚,<br/>赞美圣子,阿利路,<br/>赞美圣灵,阿利路亚,<br/>神旨得成,阿利路。<br/>','',59703,9);
INSERT INTO stanza VALUES('ZS754','10','召会荣耀,阿利路亚,<br/>众圣美善,阿利路,<br/>聚会美善,阿利路亚,<br/>谁不受感来归服?<br/>','',59704,10);
INSERT INTO stanza VALUES('ZS754','11','阿利路亚,阿利路亚,<br/>阿利路亚,高声唱,<br/>阿利路亚,阿利路亚,<br/>阿利路亚,赞我王！<br/>','',59705,11);
INSERT INTO stanza VALUES('ZS755','1','活基督者佳美踪迹,<br/>应当效法且追随;<br/>己意、己力不再凭倚,<br/>跟随榜样不羞愧。<br/>','',59706,1);
INSERT INTO stanza VALUES('ZS755','chorus','弟兄姊妹脚踪佳美,<br/>活主生命何宝贵;<br/>如此榜样应当跟随,<br/>豫备新妇迎主归。<br/>','',59707,2);
INSERT INTO stanza VALUES('ZS755','2','呼求主名取用宝血,<br/>佳美榜样紧跟随;<br/>如此跟随,步履确切,<br/>必将仇敌全击溃。<br/>','',59708,3);
INSERT INTO stanza VALUES('ZS755','3','当将心怀全然开启,<br/>榜样言语乐听取;<br/>并非接受人言、人意,<br/>乃是领受神话语。<br/>','',59709,4);
INSERT INTO stanza VALUES('ZS755','4','如此,主话速速传开,<br/>主的恢复达地极;<br/>神圣行动何能阻碍,<br/>神旨成功日可期。<br/>','',59710,5);
INSERT INTO stanza VALUES('ZS755','5','一路跟随,不偏不倚,<br/>直至婚娶之日临,<br/>直至新妇妆饰整齐,<br/>迎接羔羊同欢欣。<br/>','',59711,6);
INSERT INTO stanza VALUES('ZS756','1','我们今乐意跟随众召会,<br/>主里是一,显无遗;<br/>在众召会中,主今正行动,<br/>坚定跟随,众如一。<br/>','',59712,1);
INSERT INTO stanza VALUES('ZS756','chorus','跟随！跟随主圣灵,<br/>单纯跟随,莫迟误！<br/>跟随！凭灵中羔羊,<br/>绝对跟随,凭基督！<br/>','',59713,2);
INSERT INTO stanza VALUES('ZS756','2','我们今学习跟随众从者,<br/>流中往前无己意;<br/>时刻转向灵,绝不望领头,<br/>首位惟归主自己。<br/>','',59714,3);
INSERT INTO stanza VALUES('ZS756','3','我们今欢然跟羊群脚踪,<br/>享受牧者的照应;<br/>在众召会中,主今正引领,<br/>祂的发言当聆听。<br/>','',59715,4);
INSERT INTO stanza VALUES('ZS756','4','我们今全然献给主基督,<br/>紧紧跟随不他依;<br/>不管何遭遇,随羔羊前行,<br/>无论何往不稍离。<br/>','',59716,5);
INSERT INTO stanza VALUES('ZS756','5','一路紧跟随,宜到进国度,<br/>羔羊婚筵乐有分;<br/>今纵有逼迫、痛苦和试炼,<br/>不过促我享主恩。<br/>','',59717,6);
INSERT INTO stanza VALUES('ZS756','6','在众召会中,主今正召唤,<br/>忠信从者来得赏;<br/>我们愿答应,全人都拼上,<br/>神旨成功不延宕。<br/>','',59718,7);
INSERT INTO stanza VALUES('ZS757','1','紧紧跟随救主耶稣,<br/>灵中生活不迟误;<br/>作得胜者,听主招呼,<br/>心靠恩典得坚固。<br/>跟随耶稣,作得胜者,<br/>灵中行事不凭己;<br/>跟随耶稣,每时每刻─<br/>主,领我们跟随你。<br/>','',59719,1);
INSERT INTO stanza VALUES('ZS757','2','紧紧跟随主内弟兄,<br/>同心合意齐建造;<br/>互作肢体,生命流通,<br/>联络、结合精而牢。<br/>跟随弟兄,同心建造,<br/>不再单独来事奉;<br/>跟随弟兄,彼此相调,<br/>守住等次尽功用。<br/>','',59720,2);
INSERT INTO stanza VALUES('ZS757','3','紧紧跟随地方召会,<br/>为主恢复全奉献;<br/>取得全地归主支配,<br/>国度应许必实现。<br/>跟随召会,献上所有,<br/>同心为着主恢复;<br/>跟随召会,投身水流,<br/>直到带进主国度。<br/>','',59721,3);
INSERT INTO stanza VALUES('ZS757','4','主的圣言欢喜聆听,<br/>必使我们得加力;<br/>惟主、召会、弟兄是从,<br/>羊群脚踪不偏离。<br/>跟随耶稣、召会、弟兄,<br/>跟随圣灵的水流;<br/>“阿们”主话,永不力穷,<br/>神旨必定得成就。<br/>','',59722,4);
INSERT INTO stanza VALUES('ZS758','1','借着救主复活大能,<br/>我们已成祂弟兄─<br/>祂心所爱,复活所生,<br/>同祂得胜,同高升。<br/>','',59723,1);
INSERT INTO stanza VALUES('ZS758','chorus','耶稣基督,满有那灵,<br/>宗教之外神显明;<br/>死而复活,冲破幽冥,<br/>神众子中作长兄。<br/>作祂召会,我们聚集,<br/>老套规条已全弃;<br/>长兄荣面,我们所喜,<br/>祂作中心和目的。<br/>','',59724,2);
INSERT INTO stanza VALUES('ZS758','2','长兄复起,我们亦同,<br/>欢喜聚集复活中;<br/>天然生命,惟愿消踪,<br/>使主喜乐并得荣。<br/>','',59725,3);
INSERT INTO stanza VALUES('ZS758','3','祷读圣言,享受不已,<br/>天天遇见主自己;<br/>灵里火热,同来聚集,<br/>被主充满且洋溢！<br/>','',59726,4);
INSERT INTO stanza VALUES('ZS758','4','每逢聚集都是赴席,<br/>吃主喝主,乐无比;<br/>祂作活粮,无量供给,<br/>滋养、满足且加力。<br/>','',59727,5);
INSERT INTO stanza VALUES('ZS758','5','新鲜基督献作“佳肴”,<br/>使主满足、得荣耀;<br/>各人所献尽管微小,<br/>却叫众人得建造。<br/>','',59728,6);
INSERT INTO stanza VALUES('ZS758','6','聚会非为传讲道理,<br/>乃为与主同聚集;<br/>祂的同在有何能比?<br/>长兄荣美真无匹！<br/>','',59729,7);
INSERT INTO stanza VALUES('ZS759','1','当主在地与人同聚,<br/>宗教、老套全撇弃;<br/>我们今日主里聚集,<br/>仪文岂可再凭倚?<br/>哦,让我们在复活里,<br/>以主基督为实际,<br/>每逢聚集都是新样,<br/>死沉、虚仪无踪迹。<br/>','',59730,1);
INSERT INTO stanza VALUES('ZS759','2','主已复活,桎梏全除,<br/>宗教事物已过时;<br/>祂是活殿,是真供物,<br/>凭祂敬拜才真实。<br/>阿利路亚,同主复活,<br/>何等释放,何超脱！<br/>聚集过节,享受盛筵,<br/>贫穷、老旧都消没。<br/>','',59731,2);
INSERT INTO stanza VALUES('ZS759','3','唉呀！宗教何其狡猾,<br/>堕落血轮中藏着;<br/>求主启示,大光照亮,<br/>使那,恶魔无处躲。<br/>哦主,救我脱离宗教,<br/>脱开魂中的囚牢;<br/>每逢聚集将灵释放,<br/>满足神、人的需要。<br/>','',59732,3);
INSERT INTO stanza VALUES('ZS759','4','山上、海边,处处可聚,<br/>主作实际当持守;<br/>活的基督,我们至爱,<br/>有祂同在复何求?<br/>埋葬宗教,除去老旧,<br/>灵中新样神所宝;<br/>非“基督教,”乃是基督,<br/>才是实际神所要。<br/>','',59733,4);
INSERT INTO stanza VALUES('ZS760','1','救主耶稣受死前,曾对彼得嘱咐:<br/>仇敌会像筛麦子,想要得着门徒;<br/>但祂为我们祈求-真实且有能;<br/>阿利路亚,仇敌必不能得着我们！<br/>','',59734,1);
INSERT INTO stanza VALUES('ZS760','chorus','每天生活中都会经历属灵争战,<br/>走主道路者必定遇见试炼、艰难<br/>祂在一切境遇中,为我们代祷,<br/>祂的全备供应也满足我们需要。<br/>','',59735,2);
INSERT INTO stanza VALUES('ZS760','2','单独、孤立基督徒,无论如何刚强,<br/>在仇敌诡计之下仍然难以抵挡、<br/>我们活在身体中,就坚定站立;<br/>阿利路亚,仇敌必不能胜过身体！<br/>','',59736,3);
INSERT INTO stanza VALUES('ZS760','3','神为我们所命定旨意何等美妙;<br/>经历变化,与基督同王,真是荣耀！<br/>我们有基督召会,仇敌不可畏;<br/>阿利路亚,仇敌必不能胜过召会！<br/>','',59737,4);
INSERT INTO stanza VALUES('ZS761','1','我们在主同在间,同心俯伏祂脚前;<br/>因着祂爱的感动,因着那灵的交通,<br/>甘心放下己荣耀,脱下外衣束上腰,<br/>存心卑微跟随主,彼此洗脚作门徒。<br/>','',59738,1);
INSERT INTO stanza VALUES('ZS761','2','祂舍自己到至极,祂爱我们爱到底;<br/>我们与祂联为一,不再保留魂与己。<br/>一人既替众人死,众人无法再自恃;<br/>跟随受苦的脚踪,彼此牧养作仆从。<br/>','',59739,2);
INSERT INTO stanza VALUES('ZS761','3','这是爱里的服役,这是生命的洗涤;<br/>主既领先下尊位,甘以谦卑作巾围。<br/>彼此服事尽恩爱,体贴救主的胸怀;<br/>借此心再得畅快,洗尽世俗的尘埃。<br/>','',59740,3);
INSERT INTO stanza VALUES('ZS761','4','彼此饶恕相顾惜,爱里扶持共勉励;<br/>同乐同苦同淌泪,同活同行同依偎。<br/>彼此相爱世人睹,从此认出主门徒;<br/>保守我们心相系,隐主肋旁不分离。<br/>','',59741,4);
INSERT INTO stanza VALUES('ZS762','1','我们都是主身上肢体,<br/>彼此相联永不离,<br/>同来关心主在地权益,<br/>为此事奉才合理,<br/>虽然在途中,<br/>经过许可的损失、疼痛,<br/>有分许多的患难交通,<br/>越发坚定而顺从;<br/>没有人单独行动,<br/>你我都是弟兄,<br/>当一人受主感动,<br/>全体跟着向前冲,<br/>彼此扶持,苦乐与共,<br/>我只求这一生<br/>与你们同活在主身体中。<br/>','',59742,1);
INSERT INTO stanza VALUES('ZS762','2','就像迦勒陪同约书亚,<br/>争战为以色列家,<br/>并以利沙跟随以利亚,<br/>同心放胆说主话,<br/>配搭的榜样,<br/>保罗、西拉在灵里刚强,<br/>身陷牢中仍赞美歌唱,<br/>神救恩大得显彰;<br/>看我们脸上荣光更加有福、<br/>盼望同领受一个异象,<br/>没有不同的方向,<br/>跟上时代随主前往,<br/>使新路更开,<br/>广愿为神国度福音走四方。<br/>','',59743,2);
INSERT INTO stanza VALUES('ZS762','3','我们知道眼前所奔跑,<br/>非属地康庄大道,<br/>还要经过主一再焚烧,<br/>炼净我天然、爱好,<br/>尽管我渺小,常是輭弱,<br/>会沮丧跌倒,<br/>你们却又把我带回到<br/>主那起初的怀抱;<br/>我真是欢喜跳跃,<br/>有主作我至宝<br/>又能与你们联调,<br/>没有比这更美好,<br/>我要时时向外宣报,<br/>让更多人进入<br/>基督与召会永远的荣耀。<br/>','',59744,3);
INSERT INTO stanza VALUES('ZS850','1','我爱,我爱我恩主,<br/>不愿自由外出;<br/>因祂是我救赎主,<br/>为我赎价已付。<br/>爱祂、事祂永不离,<br/>何其甘甜、蒙福;<br/>虽然有时会困倦,<br/>祂赐安息稳固。<br/>','',59745,1);
INSERT INTO stanza VALUES('ZS850','2','我主舍命流宝血,<br/>重价买我归属;<br/>救我脱离罪权势,<br/>脱离己的束缚。<br/>祂既召我来事奉,<br/>我愿甘心顺服;<br/>如此永享真自由─<br/>爱中作祂奴仆。<br/>','',59746,2);
INSERT INTO stanza VALUES('ZS850','3','全心事奉不半途,<br/>惟有祂是我主;<br/>祂是爱我将命舍,<br/>我愿永远祂属。<br/>我心感戴、灵欢腾,<br/>口中高歌不住:<br/>我爱,我爱我恩主,<br/>不愿自由外出。<br/>','',59747,3);
INSERT INTO stanza VALUES('ZS851','1','求主发言,教导我舌,<br/>使我能言,照你心意;<br/>寻回愚蒙并失迷者,<br/>像你爱中细细寻觅。<br/>','',59748,1);
INSERT INTO stanza VALUES('ZS851','2','求主引导,使我有光,<br/>领浪荡者归回正途;<br/>供我饮食,使我有粮,<br/>喂养饥渴之徒无数。<br/>','',59749,2);
INSERT INTO stanza VALUES('ZS851','3','求主加力,使我得以<br/>稳踏基督磐石之上,<br/>且能伸出爱的膀臂,<br/>风暴海中救援丧亡。<br/>','',59750,3);
INSERT INTO stanza VALUES('ZS851','4','求主教我如何将你<br/>宝贵救恩向人陈述,<br/>使我言辞如有双翼,<br/>及于人心,触人深处。<br/>','',59751,4);
INSERT INTO stanza VALUES('ZS851','5','赐我以你甜美安息,<br/>使我言语应时如你,<br/>能施安抚,复苏、加力,<br/>使疲乏者都得再起。<br/>','',59752,5);
INSERT INTO stanza VALUES('ZS851','6','用你丰富充满我心,<br/>直至满溢恩典美辞:<br/>述说你爱,颂扬你恩,<br/>分赐生命、亮光不止。<br/>','',59753,6);
INSERT INTO stanza VALUES('ZS851','7','我虽不堪,愿主使用,<br/>随时、随处照你喜悦;<br/>直至见你,荣耀之中,<br/>同享安息,喜乐不绝。<br/>','',59754,7);
INSERT INTO stanza VALUES('ZS852','1','兴起！角声发出,喜信传布;<br/>宣扬万主之主─救主耶稣;<br/>述说祂名宝贵,高举祂的尊位,<br/>好使万众来归─耶稣是主！<br/>','',59755,1);
INSERT INTO stanza VALUES('ZS852','2','谁愿为祂前去?谁愿兴起?<br/>地爱迷人难拒,为祂全弃:<br/>鄙视属地荣华,万事看为卑下,<br/>惟夸救主十架;谁愿兴起?<br/>','',59756,2);
INSERT INTO stanza VALUES('ZS852','3','得赏之日不远,奋勇向前;<br/>晨星快要出现,不再迟延。<br/>高举十架救恩,征服偶像、判民;<br/>惟盼有福之晨,与主相见。<br/>','',59757,3);
INSERT INTO stanza VALUES('ZS852','4','请听胜利角声,耶稣为王！<br/>基督登极执政,无能违抗:<br/>全地复归祂有,惟祂居高为首,<br/>座前无不拜叩─耶稣为王！<br/>','',59758,4);
INSERT INTO stanza VALUES('ZS853','1','速兴起传福音！速抢救灵魂！<br/>请你看千万人天天沉沦！<br/>莫塞住怜悯心,莫看重金银,<br/>松开手传福音,趁着现今。<br/>','',59759,1);
INSERT INTO stanza VALUES('ZS853','chorus','速兴起传福音！速抢救灵魂！<br/>你为何仍忍心,看人沉沦！<br/>','',59760,2);
INSERT INTO stanza VALUES('ZS853','2','人虽藐视真神,祂仍不灰心,<br/>要向人施怜悯,等待殷殷。<br/>人只要肯相信,必得享救恩,<br/>速前去向罪人劝诲谆谆！<br/>','',59761,3);
INSERT INTO stanza VALUES('ZS853','3','撒但虽将人掳,使人心麻木,<br/>神恩典能眷顾,将人恢复。<br/>心弦断祂修复,用恩慈复苏,<br/>爱之乐又发出,远胜当初！<br/>','',59762,4);
INSERT INTO stanza VALUES('ZS853','4','速兴起传福音！尽你我本分,<br/>作主工,靠主恩,不畏艰辛！<br/>生命路将人引,不吝惜耐心;<br/>使罪人都听闻:神爱世人！<br/>','',59763,5);
INSERT INTO stanza VALUES('ZS854','1','洗罪之泉何其深广,<br/>涌自耶稣肋旁！<br/>大能救主为我受戕,<br/>将我罪债清偿。<br/>','',59764,1);
INSERT INTO stanza VALUES('ZS854','chorus','我见血泉流自加略,<br/>立投此泉,使罪得洁！<br/>赞美救主为我流血,<br/>罪魁如我,竟也得洁！<br/>','',59765,2);
INSERT INTO stanza VALUES('ZS854','2','复活救主,我得看见,<br/>听祂美言甘甜;<br/>更美之血为我美言,<br/>我灵苏醒、感赞。<br/>','',59766,3);
INSERT INTO stanza VALUES('ZS854','3','神前行走,光明无比,<br/>世俗罪污远离;<br/>内得新心,外有白衣,<br/>基督居衷登极。<br/>','',59767,4);
INSERT INTO stanza VALUES('ZS855','1','岂能不高声颂扬?<br/>岂能不徧传四方?<br/>宝血洗罪有功效,<br/>罪人速速来投靠！<br/>','',59768,1);
INSERT INTO stanza VALUES('ZS855','2','远比祭牲血更美,<br/>带来救恩福全备;<br/>羔羊无瑕、血无疵,<br/>不见朽坏到永世。<br/>','',59769,2);
INSERT INTO stanza VALUES('ZS855','3','听哪！宝血在发声,<br/>闻于神前显权能;<br/>在宝座前为我言,<br/>功效绝佳永不变。<br/>','',59770,3);
INSERT INTO stanza VALUES('ZS855','4','前我良心有亏欠,<br/>时有控告无平安;<br/>所有玷污尽显露,<br/>叹息、痛苦不止住。<br/>','',59771,4);
INSERT INTO stanza VALUES('ZS855','5','岂知宝血洗罪污,<br/>神前功效永充足;<br/>罪案全销,得近神,<br/>借血罪人蒙神恩！<br/>','',59772,5);
INSERT INTO stanza VALUES('ZS855','6','无须祭牲血再洒,<br/>无须凭“死行”脱罚;<br/>无何能使神喜悦,<br/>诸天惟听主宝血。<br/>','',59773,6);
INSERT INTO stanza VALUES('ZS855','7','因祂流血我得赎,<br/>罪得全赦,享永福;<br/>先民不过将罪遮,<br/>我得洁净,唱乐歌。<br/>','',59774,7);
INSERT INTO stanza VALUES('ZS855','7','进入平安,何稳妥,<br/>良心无亏,罪污脱;<br/>不再羞愧,无重担,<br/>与神和好,心安然。<br/>','',59775,8);
INSERT INTO stanza VALUES('ZS855','9','阿利路亚！深难测！<br/>宝血价值我寻得！<br/>故当歌唱,再歌唱,<br/>祂血永是我保障！<br/>','',59776,9);
INSERT INTO stanza VALUES('ZS856','1','前困深牢中,全然无望;<br/>试图要相信,仍旧徬徨。<br/>耶稣一显现,天光照明亮;<br/>大爱浇灌我心,<br/>神今住我心房！<br/>','',59777,1);
INSERT INTO stanza VALUES('ZS856','chorus','耶稣流宝血,成就平息;<br/>不再有定罪,因信称义。<br/>我今归与神,因救赎永定;<br/>借着耶稣基督,对神有了和平！<br/>','',59778,2);
INSERT INTO stanza VALUES('ZS856','2','生在亚当里,奔向死亡;<br/>身心全受创,病入膏肓。<br/>神差祂儿子,了结旧亚当;<br/>罪、死不再得逞,祂死,我得释放！<br/>','',59779,3);
INSERT INTO stanza VALUES('ZS856','3','今在恩典中,喜乐欢畅;<br/>罪恶全消踪,神在流淌。<br/>神长在我心,我享恩无量─<br/>在生命里得救,在生命中作王！<br/>','',59780,4);
INSERT INTO stanza VALUES('ZS857','1','应当宣扬,宣扬主话使国度来临;<br/>尽力宣扬,宣扬主话直到国度临。<br/>和平福音,和平福音<br/>不该藏隐;不该藏隐;<br/>应当宣扬,宣扬主话直到国度临。<br/>','',59781,1);
INSERT INTO stanza VALUES('ZS857','2','主话有能,尽管释放,必不归徒然;<br/>凭信撒种,必有结果,绝不归徒然。<br/>殷勤撒种,必得亨通;<br/>主话有能,尽管撒种,必不归徒然。<br/>','',59782,2);
INSERT INTO stanza VALUES('ZS857','3','这是时候！我们传扬福音徧人间;<br/>把握今日,传扬福音不怕人弃嫌。<br/>不必畏缩,主已工作！<br/>天程旅客与主合作,不怕人弃嫌。<br/>','',59783,3);
INSERT INTO stanza VALUES('ZS857','4','只管传讲,基督必在人心作见证。<br/>我们传讲,基督就在人心作见证。<br/>宣扬主恩,为主得人;<br/>我们传讲,基督就在人心作见证。<br/>','',59784,4);
INSERT INTO stanza VALUES('ZS857','5','庄稼已熟！前去收割不必再等候！<br/>田已发白！前去收割不必再等候！<br/>基督、召会,丰满全备─<br/>完满福音速速传扬,满足人所求。<br/>','',59785,5);
INSERT INTO stanza VALUES('ZS858','1','高品福音,无上福祉,<br/>应当传扬,无畏无愧;<br/>人得重生,成神儿子,<br/>成全神旨,至高至贵;<br/>不仅出死,脱离罪罚,<br/>更得成为圣别族类;<br/>如此喜信,超凡绝佳,<br/>地上万人都当来归。<br/>','',59786,1);
INSERT INTO stanza VALUES('ZS858','2','长兄基督,神所立定,<br/>万有归祂承受管理;<br/>我们与祂同性、同命,<br/>同作后嗣荣耀无匹。<br/>创世以前,蒙神拣选,<br/>我们得享殊荣无比;<br/>如此基督,如此恩典,<br/>谁能不受吸引归依?<br/>','',59787,2);
INSERT INTO stanza VALUES('ZS858','3','同蒙天召圣别弟兄,<br/>身分崇高,非人能及,<br/>且与兄长定命与共─<br/>如此佳音,谁不称奇?<br/>荣耀基督天上执政,<br/>我们竟得与祂是一,<br/>如此呼召超绝神圣,<br/>谁竟愚顽,弃而不理?<br/>','',59788,3);
INSERT INTO stanza VALUES('ZS859','1','福音的交通,我们同有分,<br/>从头一天至今;<br/>为推广福音,众人如一人,<br/>主话徧传远近。<br/>辩护且证实,我们活福音,<br/>在此同享主恩;<br/>主既动善工,必成全无逊,<br/>直至荣中降临。<br/>','',59789,1);
INSERT INTO stanza VALUES('ZS859','2','每日的境遇,无论苦或甜,<br/>都为福音进展;<br/>为福音、死活,使主显人前,<br/>生活在地如天。<br/>笃信无畏惧,灵中常放胆,<br/>讲说神的圣言;<br/>在爱里行事,凭大能争战,<br/>与主联结无间。<br/>','',59790,2);
INSERT INTO stanza VALUES('ZS859','3','凡事能放胆,不怕仇敌阻,<br/>主灵供应充足;<br/>基督常显大,无论何事故,<br/>生死都不在乎。<br/>无一事羞愧,我们只切慕,<br/>活着就是基督─<br/>惟祂作人位,从我们活出,<br/>事事处处无误。<br/>','',59791,3);
INSERT INTO stanza VALUES('ZS859','4','行事并为人与福音是一,<br/>无论何事临及;<br/>在一个灵里,为福音站立,<br/>同魂一起努力。<br/>让我们宣扬福音的奥秘,<br/>使主称心如意;<br/>基督作生命,召会为身体,<br/>传遍居人之地。<br/>','',59792,4);
INSERT INTO stanza VALUES('ZS860','1','去！使万民作主的门徒，教导神圣的真理，<br/>将国度福音传遍全地，催促主日子来临；<br/>享受包罗万有的基督，将祂分赐外邦人，<br/>使他们都成为神儿女，作神祭物献给神。<br/>','',59793,1);
INSERT INTO stanza VALUES('ZS860','chorus','福音号角在吹响，真理旌旗在飘扬。<br/>起来，神福音勤奋的祭司！<br/>起来！起来！<br/>','',59794,2);
INSERT INTO stanza VALUES('ZS860','2','在素质上并在经纶上，被终极的灵充溢，<br/>传好信息给困苦的人，使被囚的得开释；<br/>宣扬救主悦纳人禧年，让世人都归向祂，<br/>现在正是拯救的日子，主！得着我的全家！<br/>','',59795,3);
INSERT INTO stanza VALUES('ZS860','3','凡我所行都是为福音，我不以福音为耻！<br/>顺从恩膏不住的祷告，真正福音的服事！<br/>放下自己同心并同魂，进入福音的交通。<br/>天天被真理的话构成，展开福音的行动。<br/>','',59796,4);
INSERT INTO stanza VALUES('ZS860','4','主使我作福音的出口，让福音火焚烧我！<br/>交出我家作福音出路，让主骑驴驹经过。<br/>抓住机会尽福音本份，到所有居人地带，<br/>祝福万族催促主再来，带进国度的时代。<br/>','',59797,5);
INSERT INTO stanza VALUES('ZS866','1','一盏灯光,一户人家,<br/>家需要光照亮,<br/>神就是光,圣洁无瑕,<br/>竟来我家施恩无量;<br/>除去忧伤,除去迷惘,<br/>我的家每一心房,<br/>喜乐、欢畅越发明亮。<br/>','',59798,1);
INSERT INTO stanza VALUES('ZS866','2','我家乃是属神的家,<br/>这里有爱流淌,<br/>神就是爱,真实、美佳,<br/>浸润充满,甜美馨香;<br/>带来体谅,带来盼望,<br/>我的家每一心房,<br/>满足、安康越发兴旺。<br/>','',59799,2);
INSERT INTO stanza VALUES('ZS867','1','奋力之神,内里运行,<br/>我愿听招呼,追随祂步武。<br/>属世前途,何屑一顾,<br/>上好的爱,只属良人基督。<br/>天天被提,更近我主;<br/>天天殉道,照耀荣美耶稣。<br/>云彩围绕,同奔天路;<br/>歌中之歌,与众童女共谱。<br/>','',59800,1);
INSERT INTO stanza VALUES('ZS867','chorus','我们愿以奉献为彩饰,<br/>献上自己作清晨甘露,<br/>解主干渴,生死不顾,<br/>同生活,同争战,同荣辱。<br/>起来！写下神行动历史,<br/>承接时代荣耀的托付,<br/>作主新妇,同祂凯归,<br/>全地成主甘甜美丽国度。<br/>','',59801,2);
INSERT INTO stanza VALUES('ZS867','2','我时輭弱、冷淡摇动,<br/>你仍来眷临,保养又顾惜！<br/>爱里回应天上职事,<br/>摆上全人,为神经纶再起。<br/>与主同心,牧养群羊;<br/>坚定持续,实行神所命定。<br/>无论晴雨,劳苦不息,<br/>全为应验神的梦-伯特利。<br/>','',59802,3);
INSERT INTO stanza VALUES('ZS867','3','同受异象,作主先锋,<br/>一听主号令全体向前冲。<br/>独一职事,独一工作,<br/>神的奴仆,相调中同事奉。<br/>调和的灵是我秘诀;<br/>死而复活,在配搭里行动。<br/>同忧同乐,相爱相交,<br/>身体实际,达到锡安高峰。<br/>','',59803,4);
INSERT INTO stanza VALUES('ZS867','4','亘古而出,奋力前进,<br/>祂的出来将得胜者兴起！<br/>我献自己至死忠信,<br/>跟随羔羊,与神七灵是一。<br/>活力事奉,编组成军;<br/>代求守望,以维护神权益。<br/>建立灯台,照亮万民,<br/>国度福音徧传居人之地。<br/>','',59804,5);
INSERT INTO stanza VALUES('ZS869','1','谁肯受托，宣扬神福音？<br/>谁愿答应，受差遣前行？<br/>主爱激励困迫，不再我活。<br/>今日起来应声：『请差遣我！』<br/>','',59805,1);
INSERT INTO stanza VALUES('ZS869','chorus','深愿神福音成我生活，<br/>更新我奉献刚强开拓，<br/>答应主呼召，忠勇迈进，跟随羔羊前行，<br/>遍地叩门！主阿，愿你快临！<br/>','',59806,2);
INSERT INTO stanza VALUES('ZS869','2','生死伙伴，爱里相提携。<br/>同灵站住，同魂齐努力。<br/>只为基督身体，不顾自己。<br/>作主得胜新妇，时代转移。<br/>','',59807,3);
INSERT INTO stanza VALUES('ZS870','1','荣耀异象如日放明,<br/>神心所愿,是我所羡;<br/>主爱困迫、吸引我向前,<br/>答应呼召就在今天。<br/>更新奉献,接受主陶甄,<br/>基督安家,居中掌权！<br/>供应生命,涌流活泉,<br/>基督见证扩展无边。<br/>','',59808,1);
INSERT INTO stanza VALUES('ZS870','chorus','兴起！同主前进！投身圣灵流中。<br/>在神的行动中行动,徧地叩门,<br/>主！我愿你快临！<br/>','',59809,2);
INSERT INTO stanza VALUES('ZS870','2','投身流中,刚强开拓！<br/>羔羊脚踪紧紧跟随;<br/>同灵同魂,服元首权柄,<br/>完成神旨,将敌击溃。<br/>生、养、教、建,栽种召会树,<br/>团体新人,得胜、有为,<br/>召会、身体,荣美新妇<br/>显于各地,促主归回。<br/>','',59810,3);
INSERT INTO stanza VALUES('ZS870','3','作主飞鹰,翱翔天际,<br/>在复活里,与祂是一;<br/>主话扩长,门徒化万民,<br/>国度福音徧传地极。<br/>神的旨意,我荣耀定命:<br/>作得胜者,照神心意,<br/>圣城得建,国度实现,<br/>锡安山上同祂站立。<br/>','',59811,4);
INSERT INTO stanza VALUES('ZS871','1','国度福音徧传地极,<br/>使万民识神心意;<br/>行动大轮随灵前行,<br/>为成就时代目的。<br/>主声呼召、祂爱激励,<br/>你我岂能再迟疑?<br/>随同羔羊出到全地,<br/>宣扬神经纶奥秘。<br/>','',59812,1);
INSERT INTO stanza VALUES('ZS871','chorus','在今天,更新奉献,一生随主往前;<br/>将祂计划实现,是我心愿。<br/>愿一生儆醒主前,等候晨星出现;<br/>直到永远,同祂作王掌权！<br/>','',59813,2);
INSERT INTO stanza VALUES('ZS871','2','灵里扶持,爱里提携,<br/>同作肢体不稍离;<br/>持定元首、结合一起,<br/>众人消失配搭里。<br/>交出自己、信托身体,<br/>靠主权能得加力;<br/>无一失败、同享胜利,<br/>凭祷告击败仇敌！<br/>','',59814,3);
INSERT INTO stanza VALUES('ZS871','3','在身体里向前迈进,<br/>宣扬禧年徧全地;<br/>陈明真理、涌流生命,<br/>与新约职事是一。<br/>突破文化、语言、国籍,<br/>将人迁到基督里;<br/>各地圣徒同心合意,<br/>齐显出新人实际！<br/>','',59815,4);
INSERT INTO stanza VALUES('ZS871','4','起来！回应神的心意,<br/>投身流中趁现今;<br/>拼上！只望讨主欢欣,<br/>奔赛程竭力前进！<br/>作得胜者殉道、被提,<br/>享受主隐殿中密来临;<br/>殿中柱子担负见证,<br/>圣城光辉显无尽！<br/>','',59816,5);
INSERT INTO stanza VALUES('ZS872','1','走过千重山,渡过万里洋,<br/>何处找到安息的地方?<br/>年日去匆匆,人生路茫茫,<br/>何时寻得永远的盼望?<br/>我魂阿！快苏醒,把握不多时光,<br/>神的福音此刻在传扬,<br/>我灵阿！当兴起,走出黑暗、死亡,<br/>基督救恩现今已显彰;<br/>敞开疲困心,接受生命光,<br/>我愿全人脱罪恶捆绑,<br/>主阿,主耶稣！请听我渴望:<br/>我来就你,求将我释放。<br/>','',59817,1);
INSERT INTO stanza VALUES('ZS872','2','原是荣耀神,何竟从天降,<br/>为救罪人甚且将命丧,<br/>身体为我裂,宝血为我淌,<br/>罪的刑罚由祂一人当。<br/>超越知识的爱,过我所求、所想-<br/>祂为我死、复活、升天上,<br/>无穷无尽的恩,供应全备、深广-<br/>祂成那灵内住我心房;<br/>人不再漂泊,心不再流荡,<br/>安家召会,神人同欢畅,<br/>享生命救恩,怀荣耀盼望,<br/>我已寻得属天的家乡。<br/>','',59818,2);
INSERT INTO stanza VALUES('ZS873','1','看哪！我王坐车前往,<br/>刚强无不得胜;<br/>光辉夺人,引我跟随,<br/>就此一定永定。<br/>凯旋行列,撒香俘虏,<br/>欢呼同祂前行;<br/>世途舍弃竭力拼上,<br/>作祂行动见证。<br/>','',59819,1);
INSERT INTO stanza VALUES('ZS873','chorus','站住奉献地位,只听主号令;<br/>作初熟果,迈向荣耀,<br/>建成新耶路撒冷。<br/>','',59820,2);
INSERT INTO stanza VALUES('ZS873','2','主爱牧养,柔细顾惜,<br/>是我全备供应;<br/>使我脱离天然、自己,<br/>显大复活生命。<br/>相爱、相倚,众人如一,<br/>惟凭灵中交通;<br/>基督身体,建造扩展,<br/>新人实际完成。<br/>','',59821,3);
INSERT INTO stanza VALUES('ZS873','3','神圣经纶,独一异象,<br/>我今投身其中。<br/>海口启程,宣扬佳音,<br/>全地灯台照明。<br/>作主新妇,荣耀军队,<br/>敌前显祂得胜;<br/>诸王、万国无不俯伏,<br/>和声尊大主名。<br/>','',59822,4);
INSERT INTO stanza VALUES('ZS874','1','等候耶和华，重新得力；<br/>必如鹰展翅，上腾离地。<br/>凭复活大能，翱翔天际；<br/>奔跑不困倦，行走不疲。<br/>飞向蔚蓝天，远离家乡；<br/>脱世俗羁绊，去地捆绑。<br/>愿受主差遣，同祂前往；<br/>将国度福音，带给万邦。<br/>','',59823,1);
INSERT INTO stanza VALUES('ZS874','chorus','神的飞鹰，展翅翱翔，<br/>直到锡安，永远同主作王。<br/>','',59824,2);
INSERT INTO stanza VALUES('ZS874','2','顾到神权益，不为自己；<br/>使我被取代，让主顶替。<br/>与主成为一，有如飞鹰；<br/>成为得胜者，击拜仇敌。<br/>往普天下去，传扬福音；<br/>栽种召会树，开展移民。<br/>作耶稣见证，跟随七灵；<br/>金灯台照亮，国度降临。<br/>','',59825,3);
INSERT INTO stanza VALUES('ZS875','1','西布伦,出外可以欢喜,<br/>随圣灵大风扬帆起行;<br/>福音船满载基督丰富,<br/>传扬基督复活,作祂见证。<br/>我们是主的见证人,<br/>将祂繁殖达四境;<br/>使万民归顺主门徒,<br/>执行我主伟大使命。<br/>','',59826,1);
INSERT INTO stanza VALUES('ZS875','2','复活里,如母鹿得释放,<br/>拿弗他利出嘉美言语;<br/>满恩惠,蒙耶和华赐福,<br/>必得海和南方为业无虞。<br/>让我们涌流主生命,<br/>刚强开拓无畏惧;<br/>以高品福音人得地,<br/>凭主大能,照主应许。<br/>','',59827,2);
INSERT INTO stanza VALUES('ZS875','3','看,全地尽是饥饿人群,<br/>需你我分赐基督富余;<br/>速兴起,打开约瑟粮仓,<br/>答应主的呼召,供人所需。<br/>主神说,我可差遣谁?<br/>谁肯为我们前去?<br/>哦,主阿,是我,我在这里,<br/>请差遣我,照你所欲。<br/>','',59828,3);
INSERT INTO stanza VALUES('ZS875','4','得胜者─犹大支派狮子,<br/>击败众仇敌,建立国度;<br/>权杖与国杖永不离开,<br/>直到细罗来到,平安处处。<br/>让我们展览主得胜,<br/>黑暗权势尽驱除;<br/>凭那灵,在生命中作王,<br/>使全地众民都蒙福。<br/>','',59829,4);
INSERT INTO stanza VALUES('ZS875','5','约瑟是多结果子树枝,<br/>泉源旁结果累累下垂;<br/>无何能限制生命繁殖,<br/>枝条探出墙外,延展加倍。<br/>让我们住在主里面,生命流通益丰沛;<br/>环境中总将基督显大,<br/>常结新果显主作为。<br/>','',59830,5);
INSERT INTO stanza VALUES('ZS875','6','以萨迦,羊圈间可躺卧,<br/>得佳美之地,满享安息;<br/>帐棚里,尽情享受快乐;<br/>低肩背重,献贡物主所喜。<br/>让我们宗教尽脱落,<br/>享受基督作美地;<br/>召会中作肢体尽功用,<br/>生机建造基督身体。<br/>','',59831,6);
INSERT INTO stanza VALUES('ZS875','7','便雅悯,耶和华所亲爱,<br/>争战中,如同撕掠的狼;<br/>灭仇敌,早晨吃所掠夺,<br/>晚上分所掳获,得胜刚强。<br/>主所爱,必与主同居,<br/>得遮蔽,安息欢畅;<br/>永世里,神人同得满足─<br/>向此标竿,我们直往！<br/>','',59832,7);
INSERT INTO stanza VALUES('ZS876','1','神就是爱,祂差独生爱子前来;<br/>当世人败坏,正堕落无奈,<br/>竟来与人同在。<br/>我犹罪人,基督即已为我受害;<br/>神莫测大爱,在此就布开,<br/>当得我心感戴。<br/>','',59833,1);
INSERT INTO stanza VALUES('ZS876','chorus','你既如此不吝,舍你爱子受害,<br/>父阿,因祂宝贵,我赞美敬拜。<br/>','',59834,2);
INSERT INTO stanza VALUES('ZS876','2','有谁能知,源自父神怀里奇爱?<br/>眼虽未曾见,耳虽未曾闻,<br/>我却得赎蒙爱。<br/>哦,神的爱！祂竟生为人子婴孩,<br/>咒诅祂担代,十架上受害,<br/>流血为将我买。<br/>','',59835,3);
INSERT INTO stanza VALUES('ZS876','chorus','父,感谢你差派独生爱子前来;<br/>祂血流自加略,显明你大爱。<br/>','',59836,4);
INSERT INTO stanza VALUES('ZS876','3','神爱世人,甚至将独生子差来。<br/>信祂不灭亡,永远生命享;<br/>来罢,切勿等待！<br/>信祂不灭亡,永远生命享;<br/>来罢,切勿等待！<br/>','',59837,5);
INSERT INTO stanza VALUES('ZS877','1','甚么使你为我舍命?<br/>为何救我?我是你仇敌。<br/>你上十架,为作我代替;<br/>你受咒诅,我享福气。<br/>','',59838,1);
INSERT INTO stanza VALUES('ZS877','chorus','我原是你仇敌,何来为我舍命?<br/>你受咒诅,我享福气。<br/>神竟为人舍命,哦！是极大奥秘！<br/>你来受死,为你仇敌。<br/>','',59839,2);
INSERT INTO stanza VALUES('ZS877','2','未曾想到,你如此行;<br/>温柔、怜恤,全向我洋溢。<br/>为何你爱?我罪大恶极;<br/>但你爱我─你的仇敌。<br/>','',59840,3);
INSERT INTO stanza VALUES('ZS877','3','你之爱我,从永远起;<br/>你爱恒久、坚定不稍移。<br/>虽我言语,冒犯得罪你;<br/>但你等候,代求不息。<br/>','',59841,4);
INSERT INTO stanza VALUES('ZS877','4','我是罪人,犯罪不已;<br/>活在罪中,行不法不义。<br/>我的恶心,反判又悖逆;<br/>但你慈心,感我衷里。<br/>','',59842,5);
INSERT INTO stanza VALUES('ZS877','chorus','我原是你仇敌,竟也能归服你;<br/>因你眷临,爱里寻觅。<br/>是你爱和怜悯,征服顽梗刚愎;<br/>昔日仇敌,今愿服你。<br/>','',59843,6);
INSERT INTO stanza VALUES('ZS877','5','我一转身,就遇见你;<br/>你正等我,怀圣别爱意。<br/>我怎忍心,再与你为敌?<br/>耶稣,我今降服归你。<br/>','',59844,7);
INSERT INTO stanza VALUES('ZS878','1','人生不定无长久,<br/>我的所有遭剥夺,<br/>无奈承受痛与羞,<br/>独自绝望中倒卧,<br/>深深苦情无人怜,<br/>重重患难谁来遣,<br/>以为生命即消散,<br/>祂竟出现在眼前。<br/>','',59845,1);
INSERT INTO stanza VALUES('ZS878','chorus','今生今世我口最爱提说,<br/>就是我主祂来过,<br/>驱走黑暗,担我輭弱,<br/>作我平安永稳妥。<br/>','',59846,2);
INSERT INTO stanza VALUES('ZS878','2','祂用油酒来敷裹,<br/>我心伤痛与坎坷,<br/>怀我、肩我、扶助我,<br/>那有一点我配得,<br/>我这才知何为爱,<br/>竟然施与我无赖,<br/>为使一生都开怀,<br/>接我到神家里来。<br/>','',59847,3);
INSERT INTO stanza VALUES('ZS878','3','别看今我有何长,<br/>若非主我早崩溃,<br/>我命、我爱、我力量,<br/>全都属祂不别归,<br/>喜乐、盼望真显明,<br/>救恩全备又有能,<br/>我口颂赞心感铭,<br/>一生因祂乐欢腾。<br/>','',59848,4);
INSERT INTO stanza VALUES('ZS878','chorus','我心歌唱主爱高深长濶,<br/>祂必永不离开我,<br/>作我生命,与我同活,<br/>伴我此生共度过。<br/>','',59849,5);
INSERT INTO stanza VALUES('ZS879','1','我一直寻求平安,或能有喜乐半点,<br/>我所有不过愁烦,人生坎坷艰难;<br/>我怨叹:奋鬬努力竟换得失望,<br/>我感伤:为何前景始终凄凉！<br/>真的神阿,你今何在?我需要你理睬,<br/>哦,我真想投入你怀。还是你不存在?<br/>','',59850,1);
INSERT INTO stanza VALUES('ZS879','2','是耶稣将我寻回,正当我万念俱灰,<br/>祂平安入我心内,涌出喜乐眼泪;<br/>我的信终于有了生命的回响,<br/>我的心流进神圣安息、盼望！<br/>哦,主耶稣,我感谢你,与我联结为一,<br/>无人像你真情实意,我余生都给你。<br/>','',59851,2);
INSERT INTO stanza VALUES('ZS879','3','何喜乐,不再是我,是基督在我活着,<br/>祂救我脱罪、死、魔,经历死而复活;<br/>我高喊:耶稣,耶稣,祂真是爱我,<br/>我颂赞:祂赐救恩这大！这博！<br/>哦,真的神是我耶稣,神是万主之主,<br/>我心、我命为你倾注,爱着你就满足。<br/>','',59852,3);
INSERT INTO stanza VALUES('ZS880','1','“当信靠主耶稣,当信当信靠主耶稣,<br/>你和你一家都必得救;”<br/>踏出你信心脚步,神必定为你开路,<br/>祂既如此应许,必定会成就。<br/>你心不要疑惑,你只管放心交托,<br/>在人所不能,在神都能;<br/>只要祂为你掌握,相信总会有结果,<br/>现在起来呼求,高举主圣名。<br/>','',59853,1);
INSERT INTO stanza VALUES('ZS880','2','“当信靠主耶稣,当信当信靠主耶稣,<br/>你和你一家都必得救;”<br/>这蒙恩见证无数,全都在向我说出,<br/>神总不会迟误,要听我祈求。<br/>耶稣的爱何大,爱我也爱我全家,<br/>我一人信主,全家蒙福;<br/>我要全心赞美祂,永远是信实可夸,<br/>同来敬拜称祝,这宝贵救主。<br/>','',59854,2);
INSERT INTO stanza VALUES('ZS861','1','神今日的行动乃是要产生得胜者，<br/>过活力的生活，实行活力的事奉，<br/>照着神牧养，为着建造基督的身体。<br/><br/>我们需要在基督天上的职事里，<br/>与代求的基督是一，好执行祂神圣的行政，<br/>好执行祂神圣的行政，完成祂的经纶。<br/><br/>蒙救赎被圣别的子民，编组成神圣别的军队，<br/>在奋力活动的神里行动并争战，以得着地。<br/><br/>我们要在神的行动中行动，<br/>去，使万民作主的门徒，教导神圣的真理；<br/>将国度的福音传遍居人之地，使金灯台照亮全地，<br/>催促主的日子来到。催促主的日子来到！<br/>','',59855,1);
INSERT INTO stanza VALUES('ZS862','1','我们有分神圣工作,<br/>是因祂恩永远够用;<br/>只要向祂绝对、纯诚,<br/>必得祝福,无量丰富。<br/>','',59856,1);
INSERT INTO stanza VALUES('ZS862','2','有祂无我,舍祂无为;<br/>彼此之间同心、相爱,<br/>没有己意,没有猜忌,<br/>必得祝福,无量丰富。<br/>','',59857,2);
INSERT INTO stanza VALUES('ZS862','3','存心、行动、为人、工作,<br/>完全受灵管治约束,<br/>蒙祂灵的权能同在,<br/>必定见祂工作成就。<br/>','',59858,3);
INSERT INTO stanza VALUES('ZS862','4','时常呼求,凡事祷告,<br/>只凭信心,不凭眼见,<br/>必得祝福,无量丰富,<br/>必定见祂工作成就。<br/>','',59859,4);
INSERT INTO stanza VALUES('ZS863','1','“今日的”真理,带进神行动,<br/>使我得坚固,清楚异象;<br/>在今时代里,我当有耳听,<br/>留意暗处灯,等候晨星。<br/>','',59860,1);
INSERT INTO stanza VALUES('ZS863','chorus','儆醒,儆醒,那灵对我说话！<br/>兴起,兴起,当有真实复兴！<br/>跟上,跟上,经纶大轮行动！<br/>得胜,得胜,持守荣耀冕！<br/>','',59861,2);
INSERT INTO stanza VALUES('ZS863','2','正常基督徒,天天有复兴,<br/>过活力生活,日日得胜;<br/>成为得胜者,脱离老底嘉,<br/>持守主恢复,弃绝撒狄。<br/>','',59862,3);
INSERT INTO stanza VALUES('ZS863','3','配合神行动,成为四活物,<br/>团体行动中,风、云、火、金;<br/>保守身体里,圣别过生活,<br/>焚烧在一起,彼此建造。<br/>','',59863,4);
INSERT INTO stanza VALUES('ZS863','4','基督登宝座,成为代求者,<br/>祷告里祷告,需我配合;<br/>成为守望者,执行神行政,<br/>香气升神前,威力无穷。<br/>','',59864,5);
INSERT INTO stanza VALUES('ZS863','5','国度的福音,传遍居人地,<br/>见证于万民,结束时代;<br/>主能差遣谁,谁愿为主去?<br/>主我在这里,请差遣我！<br/>','',59865,6);
INSERT INTO stanza VALUES('ZS863','6','主,我真爱你,愿作得胜者,<br/>同你写历史,与你是一;<br/>奋力活动神,激动我全人,<br/>起来奔赛程,直到路终。<br/>','',59866,7);
INSERT INTO stanza VALUES('ZS864','1','我看见宽阔天空,就想飞翔;<br/>振翼整装,却常常迷惘,<br/>徧寻不到真方向。<br/>主来,是真光,<br/>带我重新启航,<br/>知道神造人像神,<br/>将祂盛装,<br/>为要代表管理,<br/>且作团体显彰。<br/>','',59867,1);
INSERT INTO stanza VALUES('ZS864','chorus','永远的话成肉身,且成那灵,<br/>来使人变化,有祂生命性情。<br/>这是神新约的经纶如同大轮,<br/>往全地开展,荣耀,我竟有分！<br/>','',59868,2);
INSERT INTO stanza VALUES('ZS864','2','我今有何等荣景,怀抱雄心;<br/>国度福音,如生命种子,<br/>就要百倍结实。<br/>我去,是奴仆,<br/>使人作主门徒,<br/>愿祂现在更照耀,<br/>君王基督那日从天归回,<br/>并自我里透出。<br/>','',59869,3);
INSERT INTO stanza VALUES('ZS865','1','奥秘经纶,藏于神里,<br/>天地之主渴望寻得安息;<br/>神家异象,显于我灵,<br/>抓夺如我,无心竟能知悉:<br/>神成为人,经死、复活,<br/>作天梯,内住我灵里;<br/>人成为神,重生、变化,<br/>成居所满足神心意。<br/>','',59870,1);
INSERT INTO stanza VALUES('ZS865','chorus','恩主,是你极深怜恤,<br/>荣耀经纶引我离地;<br/>爱里回应,奉献全人,<br/>不从己意,惟愿是你。<br/>同灵、同魂、思念同一,<br/>为建神家一齐努力;<br/>成神帐幕─圣城撒冷,<br/>神人永得满足安息。<br/>','',59871,2);
INSERT INTO stanza VALUES('ZS865','2','无奈己意,只求称心,<br/>羡慕神旨,却仍贪享安逸;<br/>光照临及,才识自己,<br/>处处搀杂事,事己意充替。<br/>主手管治,破碎甄陶,<br/>我衰减,逐日脱自己;<br/>圣灵分赐,更新变化,<br/>你扩增,安家我心里。<br/>','',59872,3);
INSERT INTO stanza VALUES('ZS865','3','筑坛奉献,得着加力;<br/>神却呼召:起来,上伯特利！<br/>经历神家─召会实际,<br/>不再是“我,乃基督活我里。”<br/>你爱困迫,脱离个人,<br/>为你家,我们才安息;<br/>同众肢体,献作活祭,<br/>为召会,“枉费”亦欢喜。<br/>','',59873,4);
INSERT INTO stanza VALUES('ZS865','4','答应呼召,凭七倍灵,<br/>作得胜者,此心绝不稍移;<br/>持守主话,靠主圣名,<br/>忠勇向前,一生不再偏离。<br/>竭力奋鬬,同心配搭,<br/>奉差遣,心系于全地。<br/>国度福音,徧传地极,<br/>怀雄心,只讨主欣喜。<br/>','',59874,5);
INSERT INTO stanza VALUES('ZS868','1','耶稣─好牧人,寻找税吏、罪人;<br/>祂是神成肉身,拯救世人脱沉沦;<br/>肩负疲魂,喜乐、情深,领迷羊归神。<br/>','',59875,1);
INSERT INTO stanza VALUES('ZS868','2','那灵─光照者,正寻觅失落者;<br/>生命之光照射,要世人佑罪自责;<br/>银币蒙尘,祂心不舍,终被祂寻得。<br/>','',59876,2);
INSERT INTO stanza VALUES('ZS868','3','父神─亲爱父,怜悯世上罪奴;<br/>放荡挥霍无度,不知何时才醒悟?<br/>慈爱天父,朝思夜慕,浪子上归途。<br/>','',59877,3);
INSERT INTO stanza VALUES('ZS868','4','父神─接纳者,亲吻那流浪者;<br/>披华美,罪全赦,享肥甘,不再饥渴;<br/>死而复活,失而又得,神、人同欢乐。<br/>','',59878,4);
INSERT INTO stanza VALUES('ZS917','1','今日争战凶猛,<br/>撒但尚未退败;<br/>战场传来呼喊之声,<br/>比前更加澎湃;<br/>阴府背叛喧嚣,<br/>虽仍强悍不衰;<br/>请听夜半主发呼声:<br/>“看哪,我必快来！”<br/>','',59879,1);
INSERT INTO stanza VALUES('ZS917','2','虽有更苦试炼,<br/>争战不断接连;<br/>黑暗权势如同军队,<br/>集聚进逼无间,<br/>正当儆醒等候,<br/>正逢艰苦试验;<br/>却闻歌声喜乐、甘甜:<br/>我主已快显现！<br/>','',59880,2);
INSERT INTO stanza VALUES('ZS917','3','当在末后年日,<br/>持守见证不移;<br/>撒但无所不用其极,<br/>我们仍需站立;<br/>应当重新得力,<br/>才能胜过仇敌;<br/>直到见主,何等欢喜,<br/>叹息全都止息。<br/>','',59881,3);
INSERT INTO stanza VALUES('ZS917','4','谁愿奋力进前,<br/>靠主能力遮盖?<br/>谁愿坚定为主争战,<br/>直到那日奏凯?<br/>得胜欢呼号声,<br/>至终必定传开;<br/>何等喜乐,已先听见,<br/>“看哪,我必快来！”<br/>','',59882,4);
INSERT INTO stanza VALUES('ZS917','5','谁愿走上窄路,<br/>将神旨意拣选?<br/>历经风暴,通过考验,<br/>绝不退后、心变?<br/>谁愿忠勇进前,<br/>忍受痛苦、凶险?<br/>众得胜者彷佛看见,<br/>“我主已快显现！”<br/>','',59883,5);
INSERT INTO stanza VALUES('ZS917','6','应当加紧脚步,<br/>尽管黑暗四布;<br/>期待那日被提之福,<br/>荣耀辉煌夺目;<br/>终将撒但征服,<br/>迎接再临基督;<br/>得胜者阿,扬声欢呼:<br/>“看哪！耶稣,我主！”<br/>','',59884,6);
INSERT INTO stanza VALUES('ZS918','1','时日或许更黑暗,长夜更令人倦,<br/>一事我心深确知,尽管我主迟延:<br/>祂必显为更亲近,交通必更甘甜,<br/>更亲、更近、更甘甜,我主与我之间。<br/>','',59885,1);
INSERT INTO stanza VALUES('ZS918','2','我们等候亲爱主─盼望！喜乐！友伴！<br/>一心只想迎见祂─也许在日尽前,<br/>就在隐密转角处,祂的荣身要显;<br/>等候就要成过去,安息就要完全。<br/>','',59886,2);
INSERT INTO stanza VALUES('ZS919','1','创造之神有一目的,<br/>使人活着有意义;<br/>按祂形像我们被造,<br/>将祂权柄显于地。<br/>人虽落入撒但诡计,<br/>使神目标受蒙蔽;<br/>但神终将得祂国度,<br/>子必完成父心意。<br/>','',59887,1);
INSERT INTO stanza VALUES('ZS919','2','耶稣基督要得国度,<br/>撒但诡计必无路;<br/>生命种子长出实际,<br/>不顾一切的拦阻。<br/>并非宗教人士所说,<br/>死后才能进国度;<br/>基督正在建造国度,<br/>我们见证且目睹。<br/>','',59888,2);
INSERT INTO stanza VALUES('ZS919','3','神子耶稣,我们救主,<br/>是神亲来成肉体;<br/>今成那灵进入人里,<br/>作为赐生命之气。<br/>祂是小小生命子粒,<br/>生根在人的灵里;<br/>从里到外,不住扩展,<br/>直到生命全漫溢。<br/>','',59889,3);
INSERT INTO stanza VALUES('ZS919','4','弟兄,时间己经短促,<br/>主正切慕得新妇;<br/>借着生命长大成熟,<br/>我们催促祂脚步。<br/>不再挣扎,不再奋鬬,<br/>只要灵中转向主;<br/>凡事长入元首基督,<br/>生命种子成国度。<br/>','',59890,4);
INSERT INTO stanza VALUES('ZS919','5','惟凭生命正常生长,<br/>基督得着祂国度;<br/>变化并非瞬间即成,<br/>逐日增长是正途。<br/>哦,让我们发展、取用<br/>生命种子的丰富;<br/>宝贵种子长成国度,<br/>神旨成功不迟误。<br/>','',59891,5);
INSERT INTO stanza VALUES('ZS920','1','荣耀新妇主所期,喜乐婚筵祂备齐;<br/>穿上洁净细麻衣─要及时！<br/>经过苦难与死地,基督生命紧凭倚,<br/>活出之义成所披─要及时！<br/>','',59892,1);
INSERT INTO stanza VALUES('ZS920','chorus','要及时！要及时！<br/>羔羊婚筵今在即,要及时！<br/>魂的生命肯离弃,让灵浸透且漫溢,<br/>就必够格来坐席─要及时！<br/>','',59893,2);
INSERT INTO stanza VALUES('ZS920','2','精明童女主所期,豫备新油当积极,<br/>切莫轻忽神心意─要及时！<br/>买油代价不容易,必须我们对付己,<br/>器皿充满且洋溢─要及时！<br/>','',59894,3);
INSERT INTO stanza VALUES('ZS920','3','忠信奴仆主所期,运用恩赐作生意,<br/>莫因懒惰被撇弃─要及时！<br/>一他连得不藏匿,克服松懒的己意,<br/>凭主事奉不乏力─要及时！<br/>','',59895,4);
INSERT INTO stanza VALUES('ZS920','4','成熟麦子主所期,初熟部分先被提,<br/>大体庄稼仍在地─要及时！<br/>勿向世界再寻觅,属地水分不留遗,<br/>生命成熟讨主喜─要及时！<br/>','',59896,5);
INSERT INTO stanza VALUES('ZS920','5','得胜信徒主所期,为祂万事不足惜,<br/>起初的爱总不弃─要及时！<br/>与主联结成为一,胜过所有的死寂,<br/>奔向标竿尽全力─要及时！<br/>','',59897,6);
INSERT INTO stanza VALUES('ZS920','6','看哪,基督要来地,属天国度将临及,<br/>服主权柄莫迟疑─要及时！<br/>悖逆的己须脱离,顺服功课当学习,<br/>让主掌权登至极─要及时！<br/>','',59898,7);
INSERT INTO stanza VALUES('ZS921','1','神在子里成为肉身,乃神所赐宏恩;<br/>基督丰富享受不尽,供应全备常新。<br/>此恩浩大,超人能度,奇妙,难尽述说;<br/>否则灭亡之子如我,怎能成神杰作?<br/>','',59899,1);
INSERT INTO stanza VALUES('ZS921','2','受造之物受缚被囚,殷殷热切等候,<br/>神的众子显现时候,得享永远自由。<br/>我神定旨永远深广,就要完全明朗;<br/>荣耀盼望如今隐藏,那时全得显彰。<br/>','',59900,2);
INSERT INTO stanza VALUES('ZS921','3','番石榴树代替蒺藜,松树顶替荆棘;<br/>和平掌权,战争消弭,咒诅再无踪迹。<br/>大山小山发声欢呼,树木拍掌鼓舞;<br/>荣耀自由得以进入,当神众子显出。<br/>','',59901,3);
INSERT INTO stanza VALUES('ZS921','4','神的深恩细致陶甄,每日作工我身;<br/>分赐之工今虽隐藏,那日要显无尽。<br/>神的自己在我加添,神圣分赐无间;<br/>受造万有无不赞叹,当神杰作展现。<br/>','',59902,4);
INSERT INTO stanza VALUES('ZS921','5','得赎宇宙欢呼颂称,神圣计画成功！<br/>千万天使和声歌颂,无边荣耀之中。<br/>恶者虽曾肆无忌惮,终如烟消云散;<br/>惟主智慧卓越超凡,配得永远称赞。<br/>','',59903,5);
INSERT INTO stanza VALUES('ZS921','6','为此我们欣然奉献,配合主的心愿,<br/>接受祂的分赐、充满,逐日让祂扩展。<br/>惟愿今日生活点滴,尽是因典滴沥;<br/>是神自己加添我里,那日光荣无比。<br/>','',59904,6);
INSERT INTO stanza VALUES('ZS922','1','我们向神的信心,当徧传远近,<br/>宣告已离弃偶像,事奉真活神;<br/>用信调和主圣言,高声说“阿们！<br/>”借主话转向主,时刻经历救恩。<br/>','',59905,1);
INSERT INTO stanza VALUES('ZS922','chorus','信心的工作要不断增长,<br/>爱心的劳苦要漫溢四方,<br/>蒙祂圣别保守,徧及全人里外;<br/>以盼望的忍耐,儆醒等候祂来。<br/>','',59906,2);
INSERT INTO stanza VALUES('ZS922','2','我们以神圣的爱,彼此来关怀,<br/>这爱在末后日子,更洋溢布开;<br/>主引导我们的心,进入神的爱,<br/>豫备我们全人,盼望那日主来。<br/>','',59907,3);
INSERT INTO stanza VALUES('ZS922','3','信实的主必保守我们的各部─<br/>灵、魂、身子全圣别,构成祂新妇;<br/>今日凡事愿听从主大小吩咐,<br/>不久就要听见祂的再临招呼。<br/>','',59908,4);
INSERT INTO stanza VALUES('ZS922','4','我们等候主回来─祂甜美同在;<br/>哦,何等荣耀盼望！“主,愿你快来！”<br/>作光明白、昼之子,儆醒勿懈怠,<br/>惟盼主显荣身,婚娶之日,乐哉！<br/>','',59909,5);
INSERT INTO stanza VALUES('ZS923','1','主,你必快显现,<br/>那日如在眼前,<br/>我们所慕惟你“同在”！<br/>我主、我命、我爱,<br/>你外无可替代,<br/>良人耶稣,愿你快来！<br/>','',59910,1);
INSERT INTO stanza VALUES('ZS923','2','被提时刻临近,<br/>儆醒听你声音,<br/>切盼与你荣中相见。<br/>惟当你显荣身,<br/>在那婚娶之晨,<br/>才识你爱超绝无限。<br/>','',59911,2);
INSERT INTO stanza VALUES('ZS923','3','时日飞逝如箭,<br/>不久要见你面─<br/>阿们,我主,愿你快回！<br/>只盼早日见你,<br/>并且永远偕你-<br/>我们全心别无所归。<br/>','',59912,3);
INSERT INTO stanza VALUES('ZS923','4','是的,再过片时,<br/>新郎不再延迟,<br/>就要迎娶所爱新妇。<br/>祈求终变感赞,<br/>渴望尽成眼见,<br/>主,你也必心满意足。<br/>','',59913,4);
INSERT INTO stanza VALUES('ZS924','1','今在灵里,在召会中,<br/>得见异象,高、深、长、阔:<br/>我们定命卓越超凡,<br/>前所未见,超人能度。<br/>','',59914,1);
INSERT INTO stanza VALUES('ZS924','2','非仅道理,乃是启示<br/>基督自己奇妙、奥秘;<br/>远超心思所能领畧,<br/>但在灵中都成实际。<br/>','',59915,2);
INSERT INTO stanza VALUES('ZS924','3','祂是丰富、无限、深奥,<br/>无法测度、超绝美妙;<br/>竟需我们得着救恩,<br/>同为后嗣显祂荣耀。<br/>','',59916,3);
INSERT INTO stanza VALUES('ZS924','4','神已计划,也来创造,<br/>还要作出新造无穷;<br/>祂已立子作祂后嗣,<br/>执掌祂的神圣行政。<br/>','',59917,4);
INSERT INTO stanza VALUES('ZS924','5','但在神的经纶之中,<br/>并非仅有一子得荣;<br/>乃是长子率众弟兄,<br/>同作后嗣,定命与共。<br/>','',59918,5);
INSERT INTO stanza VALUES('ZS924','6','为着够格作神后嗣,<br/>我们必须长大成熟,<br/>好与基督同得荣耀,<br/>承受神的所是所有。<br/>','',59919,6);
INSERT INTO stanza VALUES('ZS924','7','作神后嗣,随同长兄,<br/>承受万有,丰富无缺;<br/>更是同伙,一同经营<br/>“基督、召会”宇宙大业。<br/>','',59920,7);
INSERT INTO stanza VALUES('ZS924','7','今在灵里,在召会中,<br/>得见我们呼召、盼望:<br/>并非遥望,等“上天堂”,<br/>乃是在地与主同王。<br/>','',59921,8);
INSERT INTO stanza VALUES('ZS924','9','贫寒如我,竟成君王,<br/>有分宝座,承受国度;<br/>凡神所是并祂所有,<br/>全地、万有无不我属。<br/>','',59922,9);
INSERT INTO stanza VALUES('ZS925','1','永远之神荣耀定旨,<br/>已过永远早立定,<br/>跨越时间作为桥梁,<br/>将来永远必达成。<br/>漫长岁月乃是过程,<br/>全为成功祂心意;<br/>我们居此不过客旅,<br/>无终永世为目的。<br/>','',59923,1);
INSERT INTO stanza VALUES('ZS925','2','一个新人是神所要,<br/>照祂计划被建造;<br/>我们在此相联相调─<br/>团体器皿何荣耀！<br/>神的生命、神的性情<br/>调进其中时增添;<br/>神灵、人灵调为一灵,<br/>叫祂荣耀得称赞。<br/>','',59924,2);
INSERT INTO stanza VALUES('ZS925','3','三一之神三方工作,<br/>乃为达成祂定旨;<br/>父、子、圣灵何等奥妙,<br/>将神自己来分赐。<br/>天地宏伟不过背景,<br/>三部分人是标的─<br/>灵、魂、身体何等美妙,<br/>为盛装神作实际。<br/>','',59925,3);
INSERT INTO stanza VALUES('ZS925','4','我们的灵乃是中心,<br/>是神计画的关键;<br/>耶稣大名敞开呼求,<br/>人灵与祂就结联。<br/>心中各房让祂安家,<br/>始于中心达圆周;<br/>更新心思、情感、意志,<br/>每一部分祂浸透。<br/>','',59926,4);
INSERT INTO stanza VALUES('ZS925','5','在生命中同被建造,<br/>爱里联结成为一;<br/>如此成就祂的善工,<br/>成全祂心爱美意。<br/>愿主扩长,我们衰减,<br/>让祂建造我们里;<br/>直到长成团体大器,<br/>充满祂荣耀自己。<br/>','',59927,5);
INSERT INTO stanza VALUES('ZS925','6','最终召会,身体,新人,<br/>要显现于荣耀里;<br/>永世计划终极完成,<br/>神的智慧显无遗。<br/>神终得着团体器皿,<br/>将祂荣耀尽陈明─<br/>为此我们奉献自己,<br/>求使主旨速完成。<br/>','',59928,6);
INSERT INTO stanza VALUES('ZS926','chorus','一道生命的水流，流自神和羔羊宝座，<br/>历经世代未停歇，向前直奔流，<br/>千万爱主青年，<br/>不断纵身入这流，<br/>因基督的爱吸引，往另一方向追寻。<br/>','',59929,1);
INSERT INTO stanza VALUES('ZS926','1','神永远经纶，今向我开启，神来成为人，使我们成神；<br/>产生并建造主生机身体，活出并作出新耶路撒冷。<br/>深入地探究经历中享受，妆饰并豫备祂荣美新妇，<br/>这属天异象，召我跟从主，同灵同魂，与职事同步武。<br/>','',59930,2);
INSERT INTO stanza VALUES('ZS926','chorus','主爱激励我们献自己，蒙召投身时代水流里：<br/>启示高峰，神人生活，照神牧养，达『新的复兴』；<br/>『荣耀托付』引我们前行，同着良人开展到全地，<br/>葡萄园里，献上爱情，香草山上，催促我主快临。<br/>','',59931,3);
INSERT INTO stanza VALUES('ZS926','2','良人爱吸引，童女齐追随，蹿山越岭来，陡岩隐密处；<br/>金辫加银钉，祂香粉薰透，满园播芬芳，全为祂享受。<br/>靠良人上来，切慕听见祂，主坚爱保守，铭刻如印戳，<br/>全心得坚固，全人成为祂，良人与佳偶，同显神的国。<br/>','',59932,4);
INSERT INTO stanza VALUES('ZS926','3','父爱赦免心，子神牧养灵，因和好职事，与神成为一；<br/>为顾神权益，奋力往前行，凭灵同行动，完成神旨意。<br/>爱中受嘱咐，当彼此洗脚，肢体同背负，相互地代祷，<br/>为建造，爱是极超越的路，成身体模型，使主得满足。<br/>','',59933,5);
INSERT INTO stanza VALUES('ZS926','chorus','主爱激励我们献自己，蒙召投身时代水流里：<br/>启示高峰，神人生活，照神牧养，达『新的复兴』；<br/>『荣耀托付』引我们前行，同着良人开展到全地，<br/>葡萄园里，献上爱情，香草山上，催促我主快临。<br/>主耶稣阿！愿你快再临！<br/>','',59934,6);
INSERT INTO stanza VALUES('ZS927','1','三一神已成那灵,满带神圣的生命,<br/>像一道水河,可白白取用,<br/>每当我欢然呼求主名;<br/>还有一棵生命树,供应新鲜又丰富,<br/>祂就是万有、内住的基督,<br/>借着主话作我们食物。<br/>我们吃祂并喝祂,天天享受祂,<br/>作我们内在元素,<br/>得以像祂并活祂,同来彰显祂,<br/>好成为祂活的建筑;<br/>有父圣别的性情,有子复活的生命,<br/>加上灵多方变化并作工,<br/>步步进入荣耀中。<br/>','',59935,1);
INSERT INTO stanza VALUES('ZS927','2','主,我爱你的定旨,愿出代价买金子,<br/>因你,将万事都看为损失,<br/>凭你大能,模成你的死。<br/>那灵借万事管治,除掉我天然杂质,<br/>好构成精金、珍珠和宝石,<br/>像你,纯净而没有瑕疵。<br/>我们供应三一神给需要的人,<br/>作他们内在元素,<br/>活在生命交通中,跟随主行动,<br/>将人带进这活建筑;<br/>这是新耶路撒冷,我们正在建构中,<br/>神与人联调、建造的工程,<br/>全由三一所构成。<br/>','',59936,2);
INSERT INTO stanza VALUES('ZS928','1','赞美神,你是恩典化身,<br/>借成为人,丰丰满满赐给我们,<br/>为救我,竟上十架被戳,<br/>舍了自己,将我救活,同坐宝座;<br/>我要唱,全心歌唱,恩典已作王,<br/>我欢畅,全灵欢畅,恩典真无量,<br/>何喜悦,我的所有了结,<br/>有祂真好,有祂无缺,作我一切。<br/>','',59937,1);
INSERT INTO stanza VALUES('ZS928','2','感谢神,在你神圣经纶,<br/>所得福分完完全全是本于恩,<br/>我因信,借着应许而生,<br/>同来得着儿子名分,出于撒冷;<br/>来享受父、子、圣灵,价值益显明,<br/>来涌流神圣生命,使人得供应,<br/>我一生,必须经过路程,<br/>有祂同在,直到路终,恩典够用。<br/>','',59938,2);
INSERT INTO stanza VALUES('ZS928','3','敬拜神,今我成何等人,<br/>我要见证,全是因着神的宏恩,<br/>从开始,尽是恩典故事,<br/>样样是神恩典所赐,无限展示,<br/>愿今后,向着我们更洋溢扩增,<br/>到永久,终极完成新耶路撒冷,<br/>愿恩典荣耀得着称赞,<br/>借着圣城神得彰显,永永远远。<br/>','',59939,3);
INSERT INTO stanza VALUES('ZS929','1','当我们在生命、性情、彰显<br/>和功用上,成为与基督一样,<br/>我们就够资格为着祂的身体与祂同工。<br/>当我们无依无靠的信靠主,<br/>倚靠祂作我们的爱和力量,<br/>并且听祂说话,<br/>我们的盼望就是借着身体的得赎而被提,<br/>我们的祷告乃是:“主耶稣阿,我愿你来！”<br/>我愿你来！主耶稣来！<br/>','',59940,1);
INSERT INTO stanza VALUES('ZS930','1','日近一日,恩主耶稣快回来;<br/>赎回光阴,勿让今生空白。<br/>精明童女儆醒豫备不稍怠,<br/>切切等候面见新郎风采。<br/>','',59941,1);
INSERT INTO stanza VALUES('ZS930','chorus','当祂来临,我们是否正等待?<br/>己的纠缠,是否脱离无碍?<br/>何等巴望被提进入祂同在,<br/>享受婚筵,作祂新妇、至爱！<br/>','',59942,2);
INSERT INTO stanza VALUES('ZS930','2','主,助我们,黄金岁月全赎回;<br/>属天膏油,器皿里常豫备。<br/>每一试炼,都知是你所量<br/>给,使你加多,你爱更显丰沛。<br/>','',59943,3);
INSERT INTO stanza VALUES('ZS930','chorus','主必快来,现今每刻都宝贵;<br/>被灵充满,买油应当加倍。<br/>苦难试炼,放胆迎接毫不畏;<br/>今虽伤痛,那日国度甘美。<br/>','',59944,4);
INSERT INTO stanza VALUES('ZS930','3','主,转我们,属魂享乐不留恋,<br/>惟注视你温柔,美丽荣脸。<br/>保守我们,奔跑赛程不困倦,<br/>忍耐到底,直至见你显现。<br/>','',59945,5);
INSERT INTO stanza VALUES('ZS930','chorus','当主来临,能否被提到祂前?<br/>能否见祂,坐席享受婚筵?<br/>应当儆醒,无一刻松懒随便;<br/>朝思暮想,惟盼新郎归旋。<br/>','',59946,6);
INSERT INTO stanza VALUES('ZS930','4','同众童女,欢喜出去迎新郎;<br/>灵里焚烧,灯都发光剔亮;<br/>器皿充满,眼目注视祂荣光,<br/>与祂同在,完全满足欢畅。<br/>','',59947,7);
INSERT INTO stanza VALUES('ZS930','chorus','完全满足─新郎新妇永同享;<br/>完全满足─直到永世无疆！<br/>何等安息！喜乐、恩爱又辉煌,<br/>永世对耦,福乐盈溢无上！<br/>','',59948,8);
INSERT INTO stanza VALUES('ZS916','1','神的圣城,居高华美,<br/>荣耀之事论及你;<br/>神已立你作祂居所,<br/>祂话坚定永不移。<br/>永久磐石为你根基,<br/>安稳住处谁能动?<br/>救恩高墙四面环绕,<br/>永向仇敌显光荣。<br/>','',59949,1);
INSERT INTO stanza VALUES('ZS916','2','看那丰沛活水江河，<br/>涌自神圣永远爱；<br/>锡安之民不虞匮乏，<br/>因有供应永不衰。<br/>水河所至，干渴绝迹，<br/>且有恩典施眷顾；<br/>此恩如同赐恩之主，<br/>永不败落永丰足。<br/>','',59950,2);
INSERT INTO stanza VALUES('ZS916','3','锡安圣城蒙福之民，<br/>借血蒙赎得洁净；<br/>作神祭司且作君王，<br/>神前侍立同执政。<br/>因主大爱，凭主恩典，<br/>作王管制己生命；<br/>且作祭司献上感戴，<br/>赞美颂扬无止境。<br/>','',59951,3);
INSERT INTO stanza VALUES('ZS916','4','罪人如我竟登锡安，<br/>这是何等的恩情。<br/>任凭俗世讥笑嘲讽，<br/>我所夸耀惟主名。<br/>世人所乐都在消逝，<br/>所夸、所傲终灭绝；<br/>永久宝藏、真实福乐，<br/>惟锡安民能领畧。<br/>','',59952,4);
INSERT INTO stanza VALUES('Z557','chorus','阿利路亚！阿利路亚！<br/>恩惠临到如同江河；<br/>阿利路亚！阿利路亚！<br/>恩惠临到如同江河。<br/>','',59953,2);
INSERT INTO stanza VALUES('Z557','chorus','阿利路亚！阿利路亚！<br/>荣光照耀将我射过；<br/>阿利路亚！阿利路亚！<br/>荣光照耀将我射过。<br/>','',59954,4);
INSERT INTO stanza VALUES('Z557','chorus','阿利路亚！阿利路亚！<br/>摸着生命活水泉源；<br/>阿利路亚！阿利路亚！<br/>摸着生命活水泉源。<br/>','',59955,6);
INSERT INTO stanza VALUES('Z1001','1','颂赞与尊贵与荣耀归你，<br/>与荣耀归你，<br/>与荣耀归你。<br/>颂赞与尊贵与荣耀归你，<br/>直到永永远远。<br/>赞祂！赞祂！<br/>圣徒都要拜祂！<br/>赞祂！赞祂！<br/>直到永永远远。<br/>阿利路亚！<br/>颂赞与尊贵与荣耀归你，<br/>与荣耀归你，<br/>与荣耀归你。<br/>颂<br/>赞与尊贵与荣耀归你，<br/>直到永永远远。<br/>','',59956,1);
INSERT INTO stanza VALUES('Z1002','chorus','阿利路、阿利路、<br/>阿利路、阿利路亚，<br/>赞美我主！<br/>阿利路、阿利路、<br/>阿利路、阿利路亚，<br/>赞美我主！<br/>赞美我主，阿利路亚，<br/>赞美我主！阿利路亚，<br/>赞美我主！阿利路亚，<br/>赞美我主！<br/>','',59957,1);
INSERT INTO stanza VALUES('Z1003','1','诸天述说神的荣耀；<br/>穹苍传扬祂的巧妙。<br/>日夜发言，晓谕不已，<br/>通遍天下，传到地极。<br/>神的永能，和祂特征，<br/>借祂创造全都显明；<br/>虽非人眼所能见到，<br/>但观造物即可洞晓。<br/>','',59958,1);
INSERT INTO stanza VALUES('Z1003','2','创造天地、万物活神，<br/>为证自己存在可信：<br/>常施恩惠，赏赐丰稔，<br/>使人饱足，喜乐满心。<br/>天降甘霖，地生五谷，<br/>永活真神所赐之福；<br/>丰衣足食，享受天恩，<br/>理当念及造物之神。<br/>','',59959,2);
INSERT INTO stanza VALUES('Z1003','3','天地之主，万物之神，<br/>生命、气息，赐给万人；<br/>年限、疆界，由祂定准，<br/>要人揣摩，将祂求寻。<br/>自隐之神，人间之谜；<br/>不见之神，宇宙之秘。<br/>此一真理，人人当知，<br/>宇宙意义始能赏识。<br/>','',59960,3);
INSERT INTO stanza VALUES('Z1003','4','不见之神显于所见，<br/>神圣启示尚非完全；<br/>神的身位，神的形像，<br/>还需一人前来表彰。<br/>耶稣基督，神的爱子，<br/>降世成为人的样式；<br/>神的特性，神的所是，<br/>全由这人彰显尽致。<br/>','',59961,4);
INSERT INTO stanza VALUES('Z1003','5','奥秘基督，奇妙救主，<br/>乃是神在人间显出。<br/>原是永远无限的神，<br/>竟作时间有限的人。<br/>奥妙基督，神的化身，<br/>神人调和，惊人佳音。<br/>祂是真神，又是真人，<br/>要进你心，作你福分。<br/>','',59962,5);
INSERT INTO stanza VALUES('Z1003','6','神的神性藏祂里面，<br/>神的荣形从祂彰显。<br/>前在肉身成功救赎，<br/>今成那灵与人联属。<br/>神人基督，道成肉身，<br/>舍命流血，救赎罪人；<br/>从死复活，化身那灵，<br/>为进你灵，作你生命。<br/>','',59963,6);
INSERT INTO stanza VALUES('Z1004','1','人是神造的容器，<br/>有灵有魂又有体。<br/>神要作人的内容，<br/>从人显出祂光荣。<br/>','',59964,1);
INSERT INTO stanza VALUES('Z1004','2','人原有神的形像，<br/>身分地位何高尚；<br/>还须有神的生命，<br/>得以分享祂性情。<br/>','',59965,2);
INSERT INTO stanza VALUES('Z1004','3','基督乃是神显出，<br/>为人受死，将人赎；<br/>复活成为生命灵，<br/>进入人灵作生命。<br/>','',59966,3);
INSERT INTO stanza VALUES('Z1004','4','人的生存无基督，<br/>一切尽都感虚无：<br/>失缺人生的意义，<br/>无指无望，无目的。<br/>','',59967,4);
INSERT INTO stanza VALUES('Z1004','5','接受基督作生命，<br/>人就灵里得重生；<br/>时时凭祂而生活，<br/>虚空人生变诗歌。<br/>','',59968,5);
INSERT INTO stanza VALUES('Z1004','6','如此便能彰显神，<br/>也能造福于人群，<br/>流出活水的江河，<br/>解除群众的干渴。<br/>','',59969,6);
INSERT INTO stanza VALUES('Z1004','7','基督凯归荣耀中，<br/>你的身体必得荣，<br/>变得与祂形状同，<br/>同荣共存永无终。<br/>','',59970,7);
INSERT INTO stanza VALUES('Z1005','1','何大神迹！何深奥秘！<br/>神竟与人联调为一！<br/>神成为人，人成为神，<br/>天使、世人莫测经纶；<br/>出自神的心爱美意，<br/>达到神的最高目的。<br/>出自神的心爱美意，<br/>达到神的最高目的。<br/>','',59971,1);
INSERT INTO stanza VALUES('Z1005','2','神成肉身，来作神人，<br/>为要使我能成为神，<br/>生命、性情与祂同类，<br/>惟我无分祂的神位；<br/>祂的属性变我美德，<br/>祂的荣形在我显活。<br/>祂的属性变我美德，<br/>祂的荣形在我显活。<br/>','',59972,2);
INSERT INTO stanza VALUES('Z1005','3','不再是我单独活着，<br/>乃是神我共同生活；<br/>并与众圣神里配搭，<br/>建成三一宇宙之家，<br/>且成基督生机身体，<br/>作祂显身团体大器。<br/>且成基督生机身体，<br/>作祂显身团体大器。<br/>','',59973,3);
INSERT INTO stanza VALUES('Z1005','4','最终圣城耶路撒冷，<br/>异象、启示集其大成。<br/>三一之神，三部分人，<br/>永世对耦是人又神；<br/>神性人性互为居所，<br/>神的荣耀在人显赫。<br/>神性人性互为居所，<br/>神的荣耀在人显赫。<br/>','',59974,4);
INSERT INTO stanza VALUES('Z1006','1','神，你生命所施拯救，<br/>全都照你公义要求；<br/>你的救恩完整无弊，<br/>既合法理，又富生机。<br/>','',59975,1);
INSERT INTO stanza VALUES('Z1006','2','救赎是照法理完成，<br/>拯救是由生机施行；<br/>法理满足你的公义，<br/>生机成就你的美意。<br/>','',59976,2);
INSERT INTO stanza VALUES('Z1006','3','法理使我得你称义，<br/>生机使我与你合一：<br/>将我重生成为神人，<br/>将我圣化全人更新。<br/>','',59977,3);
INSERT INTO stanza VALUES('Z1006','4','将我变化模成荣形，<br/>新陈代谢显于生命；<br/>生命成熟长大成人，<br/>同人配搭建成一身。<br/>','',59978,4);
INSERT INTO stanza VALUES('Z1006','5','身体得赎，进入荣耀，<br/>儿子名分达到至高；<br/>与你相调，互为居所，<br/>圣城撒冷成我诗歌。<br/>','',59979,5);
INSERT INTO stanza VALUES('ZS330','1','让我伫立你背后，主！<br/>让我挨着你的脚哭，<br/>让我头发擦拭你足，<br/>让我香膏，为着你<br/>全然倒出。<br/><br/>我爱你！爱你主耶稣！<br/>为你甘愿枉费，一无所顾。<br/>从我玉瓶倾倒香膏，<br/>为你身、你头、你脚，<br/>为你─挚爱主，我爱，你耶稣！<br/>','',59980,1);
INSERT INTO stanza VALUES('ZS330','2','我将贵重膏油取出，<br/>膏抹我所至爱的主；<br/>在你脚前我今俯伏，<br/>膏油芬芳，因着爱，<br/>漫溢四处。<br/><br/>我爱你！爱你主耶稣！<br/>为你甘愿枉费，一无所顾。<br/>从我玉瓶倾倒香膏，<br/>为你身、你头、你脚，<br/>为你─挚爱主，我爱，你耶稣！<br/>','',59981,2);
INSERT INTO stanza VALUES('ZS330','3','人说你若凡事知道，<br/>必知是谁在摸你脚；<br/>是的，我罪实不可告，<br/>不配摸你，还妄想<br/>献上香膏。<br/><br/>但我爱。。。爱你，主耶稣！<br/>爱深是因多得赦罪之故。<br/>从我玉瓶倾倒香膏，<br/>为你身、你头、你脚，<br/>为你─挚爱主，我爱，你耶稣！<br/>','',59982,3);
INSERT INTO stanza VALUES('ZS330','4','我要用我爱洗你足，<br/>你脚前，我己可不顾；<br/>你的价值有谁能述？<br/>我的爱情并全人<br/>都当你属。<br/><br/>我爱你！爱你，主耶稣！<br/>我爱情我全人都为你，主。<br/>求悦纳我和我香膏，<br/>爱主，这是我上好，<br/>为你─挚爱主，我爱，你耶稣！<br/>','',59983,4);
INSERT INTO stanza VALUES('ZS444','chorus','(姊妹)光中行，<br/>神儿子<br/>必洗净<br/>我们一切的罪。<br/>若认罪，<br/>祂赦免，<br/>祂洗净<br/>一切的罪。<br/>','',59984,2);
INSERT INTO stanza VALUES('ZS444','chorus','(弟兄)彼此交通，<br/>耶稣的血<br/>必洗净我们一切的罪。<br/>祂是信实，<br/>祂是公义，<br/>祂洗净一切的罪。<br/>','',59985,3);
INSERT INTO stanza VALUES('ZS31','chorus','赞美基督是平安祭,<br/>使神与人满意;<br/>距离全去,交通甜蜜,<br/>平安永远坚立！<br/>','',59986,11);
INSERT INTO stanza VALUES('ZS31','chorus','赞美基督是平安祭,<br/>使神与人满意;<br/>距离全去,交通甜蜜,<br/>平安永远坚立！<br/>','',59987,9);
INSERT INTO stanza VALUES('CS429','5','從來不曾估量， 平凡的我得此上好，<br/>以你生命活你， 以你性情行事為人，<br/>天天羅曼蒂克， 多采多姿，可泣可歌。<br/>是你極大憐憫， 今生到我這裡來過；<br/>哦，主阿，謝謝你， 今生到我這裡來過，<br/>哦，主阿，謝謝你， 今生到我這裡來過。<br/>',NULL,59988,5);
INSERT INTO stanza VALUES('ZS429','5','从来不曾估量， 平凡的我得此上好，<br/>以你生命活你， 以你性情行事为人，<br/>天天罗曼蒂克， 多采多姿，可泣可歌。<br/>是你极大怜悯， 今生到我这里来过；<br/>哦，主阿，谢谢你， 今生到我这里来过，<br/>哦，主阿，谢谢你， 今生到我这里来过。<br/>',NULL,59989,5);
INSERT INTO stanza VALUES('C385','5','若非如此吸取，<br/>就難免去空虛；<br/>如此喫你、喝你，<br/>纔能生活有力。<br/>',NULL,59990,5);
INSERT INTO stanza VALUES('Z385','5','若非如此吸取，<br/>就难免去空虚；<br/>如此喫你、喝你，<br/>纔能生活有力。<br/>',NULL,59991,5);
INSERT INTO stanza VALUES('C439','8','當我被提，在人子前站立，<br/>釘十架者要成我的詩題；<br/>你從天來經歷人生苦楚，<br/>又在加略捨去生命血肉。<br/>','',59992,9);
INSERT INTO stanza VALUES('Z439','8','当我被提，在人子前站立，<br/>钉十架者要成我的诗题；<br/>你从天来经歷人生苦楚，<br/>又在加略捨去生命血肉。<br/>','',59993,9);
INSERT INTO stanza VALUES('Z486','1','儆醒阿，黑夜已深！<br/>儆醒，莫恋红尘；<br/>儆醒阿，白昼將近！<br/>儆醒，莫睡沉。<br/>儆醒阿，主就要来！<br/>儆醒，莫鬆腰带；<br/>儆醒阿，主在等待！<br/>儆醒，莫懈怠。<br/>',NULL,59995,1);
INSERT INTO stanza VALUES('Z486','2','儆醒阿，起来事奉！<br/>时间已到末点；<br/>儆醒阿，前来作工！<br/>年日已將残。<br/>儆醒阿，穿上军装！<br/>儆醒，灵要刚强；<br/>儆醒阿，將魔抵挡！<br/>儆醒，心要壮。<br/>',NULL,59996,2);
INSERT INTO stanza VALUES('Z486','3','儆醒阿，等候救主！<br/>晨星就要出现；<br/>儆醒阿，追求国度！<br/>荣耀在眼前。<br/>儆醒阿，务要儆醒！<br/>儆醒，等待主来！<br/>儆醒阿，儆醒莫停！<br/>儆醒到主来！<br/>',NULL,59997,3);
INSERT INTO stanza VALUES('C486','1','儆醒阿，黑夜已深！<br/>儆醒，莫戀紅塵；<br/>儆醒阿，白晝將近！<br/>儆醒，莫睡沉。<br/>儆醒阿，主就要來！<br/>儆醒，莫鬆腰帶；<br/>儆醒阿，主在等待！<br/>儆醒，莫懈怠。<br/>',NULL,59998,1);
INSERT INTO stanza VALUES('C486','2','儆醒阿，起來事奉！<br/>時間已到末點；<br/>儆醒阿，前來作工！<br/>年日已將殘。<br/>儆醒阿，穿上軍裝！<br/>儆醒，靈要剛強；<br/>儆醒阿，將魔抵擋！<br/>儆醒，心要壯。<br/>',NULL,59999,2);
INSERT INTO stanza VALUES('C486','3','儆醒阿，等候救主！<br/>晨星就要出現；<br/>儆醒阿，追求國度！<br/>榮耀在眼前。<br/>儆醒阿，務要儆醒！<br/>儆醒，等待主來！<br/>儆醒阿，儆醒莫停！<br/>儆醒到主來！<br/>',NULL,60000,3);
INSERT INTO stanza VALUES('Z389','1','今世福乐没灭，<br/>基督属我！<br/>地上爱情断绝，<br/>基督属我！<br/>在此幽暗野地，<br/>无处可以安息，<br/>惟有基督可倚，<br/>基督属我！<br/>',NULL,60001,1);
INSERT INTO stanza VALUES('Z389','2','莫诱我心离开，<br/>基督属我！<br/>我愿与主同在，<br/>基督属我！<br/>你这今世欢娱，<br/>一时骗人之局，<br/>从我心中离去，<br/>基督属我！<br/>',NULL,60002,2);
INSERT INTO stanza VALUES('Z389','3','去罢，今世幻梦，<br/>基督属我！<br/>我今已经清醒，<br/>基督属我！<br/>凡我从前所慕，<br/>不过使我痛苦；<br/>惟主使我满足，<br/>基督属我！<br/>',NULL,60003,3);
INSERT INTO stanza VALUES('Z389','4','去罢，短暂今时，<br/>基督属我！<br/>来罢，长久永世，<br/>基督属我！<br/>来罢，可爱福气！<br/>来罢，甜美安息！<br/>来罢，恩主自己！<br/>基督属我！<br/>',NULL,60004,4);
INSERT INTO stanza VALUES('C389','1','今世福樂沒滅，<br/>基督屬我！<br/>地上愛情斷絕，<br/>基督屬我！<br/>在此幽暗野地，<br/>無處可以安息，<br/>惟有基督可倚，<br/>基督屬我！<br/>',NULL,60005,1);
INSERT INTO stanza VALUES('C389','2','莫誘我心離開，<br/>基督屬我！<br/>我願與主同在，<br/>基督屬我！<br/>你這今世歡娛，<br/>一時騙人之局，<br/>從我心中離去，<br/>基督屬我！<br/>',NULL,60006,2);
INSERT INTO stanza VALUES('C389','3','去罷，今世幻夢，<br/>基督屬我！<br/>我今已經清醒，<br/>基督屬我！<br/>凡我從前所慕，<br/>不過使我痛苦；<br/>惟主使我滿足，<br/>基督屬我！<br/>',NULL,60007,3);
INSERT INTO stanza VALUES('C389','4','去罷，短暫今時，<br/>基督屬我！<br/>來罷，長久永世，<br/>基督屬我！<br/>來罷，可愛福氣！<br/>來罷，甜美安息！<br/>來罷，恩主自己！<br/>基督屬我！<br/>',NULL,60008,4);
INSERT INTO stanza VALUES('I1','1','Mulia bagi Allah Bapa<br/>dan Kristus, Putra,<br/>Mulia bagi Roh Kudus<br/>hingga kekal.<br/>',NULL,60009,1);
INSERT INTO stanza VALUES('I1','2','Saat pandang karya agung<br/>dari hikmat-Mu,<br/>Rohku tergugah menyembah,<br/>pun teduh.<br/>',NULL,60010,2);
INSERT INTO stanza VALUES('I1','3','Namun Dikau damba dapatkan<br/>banyak putra,<br/>Dalam Putra apresiasi,<br/>pun puji.<br/>',NULL,60011,3);
INSERT INTO stanza VALUES('I1','4','Dengan firman Kau wahyukan<br/>kasih mesra-Mu,<br/>Biar kami paham, t''rima,<br/>dan cinta-Mu.<br/>',NULL,60012,4);
INSERT INTO stanza VALUES('I1','5','Oleh penebusan Kristus<br/>musuh tertakluk,<br/>Kami ciptaan baru,<br/>menyembah-Mu.<br/>',NULL,60013,5);
INSERT INTO stanza VALUES('I1','6','Mulia bagi Allah Bapa<br/>dan Kristus, Putra,<br/>Mulia bagi Roh Kudus<br/>hingga kekal.<br/>',NULL,60014,6);
INSERT INTO stanza VALUES('I2','1','Mulia, mulia, mulia,<br/>puji, sembah, cinta!<br/>Dengar suara pujian<br/>menggema hingga kekal!<br/>Bapa, Putra, dan Roh,<br/>Allah t''lah ternyata,<br/>Semua orang sujud<br/>sembah Allah.<br/>',NULL,60015,1);
INSERT INTO stanza VALUES('I2','2','Bapa ialah sumber,<br/>mulia, tak terbatas;<br/>Putra dengan kuasa,<br/>menopang segalanya;<br/>Roh Kudus penuhi,<br/>jenuhi semua;<br/>O, limpah mulia,<br/>patut disembah.<br/>',NULL,60016,2);
INSERT INTO stanza VALUES('I2','3','Allah Mahatinggi,<br/>Penguasa semesta;<br/>Dengan kekudusan,<br/>kami datang menyembah!<br/>Khidmat, agung, kuasa,<br/>mulia, unggul, indah,<br/>S''mua ini milik-Mu<br/>sumber kekal!<br/>',NULL,60017,3);
INSERT INTO stanza VALUES('I3','1','Mulia bagi Sang Bapa!<br/>Mulia bagi Sang Putra!<br/>Mulia ba-gi Sang Roh Ku-dus!<br/>Mulia bagi Sang Kekal!<br/>',NULL,60018,1);
INSERT INTO stanza VALUES('I3','chorus','Puji Allah! Puji Allah!<br/>Puji Allah Tritunggal!<br/>Mulia, mulia ba-gi Allah,<br/>Pemberi kurnia kes''lamatan!<br/>',NULL,60019,2);
INSERT INTO stanza VALUES('I3','2','Puji Bapa, Perencana!<br/>Puji Putra, Penggenap!<br/>Puji Roh Kudus, Penggarap!<br/>Puji Dia (Allah Tritunggal) jadi hayat!<br/>',NULL,60020,3);
INSERT INTO stanza VALUES('I4','1','Kudus, kudus, kudus,<br/>Allah Sang Kuasa!<br/>Kami bersorak,<br/>puji-Mu hingga kekal.<br/>Kudus, kudus, kudus,<br/>kuasa pun rahmat;<br/>Tiga Persona,<br/>Allah Tritunggal.<br/>',NULL,60021,1);
INSERT INTO stanza VALUES('I4','2','Kudus, kudus, kudus,<br/>se-mua sembah Dia;<br/>Tua-tua surga buang<br/>mahkota depan takhta;<br/>Kerub dan serafim<br/>juga sembah Dia;<br/>dulu, sekarang,<br/>kekal, Kau ada.<br/>',NULL,60022,2);
INSERT INTO stanza VALUES('I4','3','Kudus, kudus, kudus,<br/>Kau tersembunyi,<br/>hingga orang dosa<br/>tak nampak mulia-Mu.<br/>Hanya Kau yang kudus,<br/>tia-da yang saingi;<br/>sempurna kasih,<br/>murni, kua-sa-Mu.<br/>',NULL,60023,3);
INSERT INTO stanza VALUES('I4','4','Kudus, kudus, kudus,<br/>Allah Sang Kuasa!<br/>Langit, bumi, laut-an,<br/>s''mua makhluk, puji-Mu.<br/>Kudus. kudus, kudus,<br/>ku-a-sa pun rahmat;<br/>Tiga persona,<br/>Allah Tritunggal.<br/>',NULL,60024,4);
INSERT INTO stanza VALUES('I5','1','Puji Bapa sumber berkat,<br/>puji Putra g''nap tebusan,<br/>Puji Roh yang menggarapnya,<br/>puji Bapa, Putra, dan Roh.<br/>',NULL,60025,1);
INSERT INTO stanza VALUES('I5','2','Puji Bapa sumber hayat,<br/>puji Putra alirannya,<br/>Puji Roh ''ngalir dalamku;<br/>puji Tritunggal bagianku.<br/>',NULL,60026,2);
INSERT INTO stanza VALUES('I6','1','Allah, Sang Kasih dan Terang,<br/>pun hayat dalam Putra;<br/>Kasih nyata, terang pancar,<br/>hayat kami terima.<br/>',NULL,60027,1);
INSERT INTO stanza VALUES('I6','chorus','Kau kasih! Kau terang!<br/>Pun hayat dalam Putra!<br/>Kasih nyata, Terang pancar;<br/>Hayat kami terima.<br/>',NULL,60028,2);
INSERT INTO stanza VALUES('I6','2','Kasih ungkapkan diri-Mu,<br/>terang, pancar karya-Mu;<br/>Kasih (dalam), terang (luar),<br/>terang-kasih memancar.<br/>',NULL,60029,3);
INSERT INTO stanza VALUES('I6','3','Wujud kasih itu kur-nia,<br/>terang itu realitas;<br/>demi kasih, Kau ku nikmat,<br/>demi t''rang Kau ku kenal.<br/>',NULL,60030,4);
INSERT INTO stanza VALUES('I6','4','Kar''na kasih Putra wafat,<br/>hingga hayat ku dapat;<br/>kar''na terang ku mengenal,<br/>ku dibasuh darah-Nya.<br/>',NULL,60031,5);
INSERT INTO stanza VALUES('I6','5','Demi kasih dapat hayat,<br/>dengan Kau bermunajat;<br/>Terang beri pembasuhan,<br/>hidup dalam munajat.<br/>',NULL,60032,6);
INSERT INTO stanza VALUES('I6','6','Terang sorot, darah basuh,<br/>bawa urapan minyak;<br/>hayat kasih dan kadar-Mu,<br/>t''rus bertambah di dalam.<br/>',NULL,60033,7);
INSERT INTO stanza VALUES('I6','7','Demi kasih, jadi anak,<br/>sebut Kau, "Abba, Bapa".<br/>Terang mengenyahkan gelap,<br/>jumpa Tuhan, serupa.<br/>',NULL,60034,8);
INSERT INTO stanza VALUES('I6','chorus','Mulia! Bahagia!<br/>Nyatalah kasih dan t''rang!<br/>Puji syukur tak bersudah!<br/>Di-kau kasih, pun terang!<br/>',NULL,60035,9);
INSERT INTO stanza VALUES('I7','1','Allah, Kau Bapa Kekal,<br/>swaada, kekal ada!<br/>Pertama pun utama<br/>dari s''gala yang ada!<br/>',NULL,60036,1);
INSERT INTO stanza VALUES('I7','2','Dikau Allah yang kekal,<br/>lampaui waktu, ruang!<br/>Kepenuhan nan kekal,<br/>kekal ti-a-da batas!<br/>',NULL,60037,2);
INSERT INTO stanza VALUES('I7','3','Dikau sumber segala,<br/>lebih dini dari s''mua!<br/>Kau-lah Yang paling awal,<br/>pula Yang paling depan!<br/>',NULL,60038,3);
INSERT INTO stanza VALUES('I7','4','Dikau hayat yang kekal,<br/>tidak berkesudahan!<br/>Kau-lah yang paling lama,<br/>pula yang paling akhir!<br/>',NULL,60039,4);
INSERT INTO stanza VALUES('I7','5','Awal, Kaulah Sang Alfa;<br/>akhir, Kau-lah Omega!<br/>Awal, akhir, tak kurang;<br/>lengkap, utuh, sempurna!<br/>',NULL,60040,5);
INSERT INTO stanza VALUES('I7','6','Kami puji Kau s''lama,<br/>Kau sungguh tak terbatas!<br/>Diri-Mu, penuh, luap,<br/>sungguh sangat sempurna.<br/>',NULL,60041,6);
INSERT INTO stanza VALUES('I8','1','Bapa, Sang Roh segala roh,<br/>Allah Mahakudus;<br/>Dalam, oleh, dan dengan roh,<br/>kami menyembah-Mu.<br/>',NULL,60042,1);
INSERT INTO stanza VALUES('I8','2','Agar dapat menyembah-Mu,<br/>Kau cipta roh insan;<br/>lahir ulang di dalam roh,<br/>roh kontak dengan roh.<br/>',NULL,60043,2);
INSERT INTO stanza VALUES('I8','3','Bapa - Putra - menjadi Roh,<br/>agar masuk rohku;<br/>Ketiga-Nya jadi hayat,<br/>kur-nia mesra sungguh.<br/>',NULL,60044,3);
INSERT INTO stanza VALUES('I8','4','Dalam Putra, Kau-lah firman,<br/>Firman itu pun Roh;<br/>Roh masuk ke dalam rohku,<br/>menjadi hayatku.<br/>',NULL,60045,4);
INSERT INTO stanza VALUES('I8','5','Roh-Mu tinggal dalam rohku,<br/>menjadi satu roh;<br/>Roh-Mu dan rohku bersaksi,<br/>ku lahir dari-Mu.<br/>',NULL,60046,5);
INSERT INTO stanza VALUES('I8','6','Roh-Mu pimpinku ''tiasa,<br/>tindak menurut roh;<br/>nikmati damai dan hayat,<br/>menjadi rohani.<br/>',NULL,60047,6);
INSERT INTO stanza VALUES('I8','7','Doa, sembah di dalam roh,<br/>''tengadah dalam roh;<br/>hingga mutlak bebaslah roh,<br/>penuh gambar mu-lia.<br/>',NULL,60048,7);
INSERT INTO stanza VALUES('I8','8','Bapa, kami puji Roh-Mu,<br/>puji Dikaulah Roh;<br/>Dalam, oleh, dan dengan roh,<br/>memuji nama-Mu.<br/>',NULL,60049,8);
INSERT INTO stanza VALUES('I9','1','Allah, Kaulah sumber hayat,<br/>kudus, sedap, limpah!<br/>P''ri air hayat t''rus mengalir,<br/>sampai selamanya!<br/>',NULL,60050,1);
INSERT INTO stanza VALUES('I9','2','Dalam Putra, kar''na kasih,<br/>Kau mencapai insan;<br/>demi Roh, alirkan kasih,<br/>masuk dalam umat.<br/>',NULL,60051,2);
INSERT INTO stanza VALUES('I9','3','Meski kami ''nyimpang, sesat,<br/>penuh dosa, jahat;<br/>dalam Putra, Kau menebus,<br/>beri hayat, kur-nia.<br/>',NULL,60052,3);
INSERT INTO stanza VALUES('I9','4','Sering kami menentang-Mu,<br/>dukakan Roh Kudus;<br/>tapi Kau tetap mengasuh,<br/>dan jadi hayatku.<br/>',NULL,60053,4);
INSERT INTO stanza VALUES('I9','5','Dalam Putra pun dalam Roh,<br/>d''ngan kami berbaur;<br/>Kadar-Mu demi gerak-Mu,<br/>makin bertambah t''rus.<br/>',NULL,60054,5);
INSERT INTO stanza VALUES('I9','6','Kasih Allah, kur-nia Putra,<br/>persekutuan Roh;<br/>bawaku nikmat limpah-Mu,<br/>sampai selamanya!<br/>',NULL,60055,6);
INSERT INTO stanza VALUES('I9','7','Bapa, Putra, Roh - Tritunggal,<br/>merawat d''ngan limpah;<br/>patut t''rima puji sembah,<br/>kasih-Mu tak sudah!<br/>',NULL,60056,7);
INSERT INTO stanza VALUES('I10','1','Allah, Kau sangat unggul,<br/>Kau pun sangat kudus!<br/>Tia-da yang seperti-Mu,<br/>tiada saingan-Mu!<br/>Kau-lah yang paling kudus,<br/>sungguh Maha kudus!<br/>Kuasa dan sifatMu,<br/>lampaui s''mua makhluk!<br/>',NULL,60057,1);
INSERT INTO stanza VALUES('I10','2','Kau unik, kudus;<br/>bukan hanya tanpa dosa;<br/>bukan hanya tak cacat;<br/>m''lebihi sempurna.<br/>Tia-da yang setara-Mu,<br/>tia-da tandingan-Mu;<br/>Apa pun gantikan-Mu,<br/>itu menghujat-Mu!<br/>',NULL,60058,2);
INSERT INTO stanza VALUES('I10','3','Unik bagus, elok-Mu,<br/>beda dengan yang lain;<br/>Semua yang bagus, elok,<br/>tiada yang saingi.<br/>Unik baik, indah-Mu,<br/>beda dengan yang lain;<br/>Kar''na baik, indah-Mu,<br/>lampaui s''mua itu.<br/>',NULL,60059,3);
INSERT INTO stanza VALUES('I10','4','Kudus itu sifat-Mu,<br/>Kau b''ri pada kami;<br/>hingga kami berbagian<br/>sifat kudus unik;<br/>kami unggul serta-Mu,<br/>sesifat dengan-Mu;<br/>kami kejar kudus-Mu,<br/>hingga kami kudus.<br/>',NULL,60060,4);
INSERT INTO stanza VALUES('I10','5','Puji sembah bagi-Mu,<br/>Dikau unggul, kudus!<br/>Tia-da yang menandingi<br/>s''mua keunggulan-Mu!<br/>Kami puji sifat-Mu,<br/>Kau b''ri pada kami;<br/>sifat unik-Mu itu,<br/>jadi milik kami.<br/>',NULL,60061,5);
INSERT INTO stanza VALUES('I11','1','Hijau segar p''ri cemara,<br/>tak layu selama!<br/>Dikau Tuhan hidup kekal,<br/>tak luruh selama!<br/>',NULL,60062,1);
INSERT INTO stanza VALUES('I11','chorus','Bapa Kau Allah Sang Segar,<br/>tiada kenal usang!<br/>Laksaan tahun berselang,<br/>Kau segar tak ubah!<br/>',NULL,60063,2);
INSERT INTO stanza VALUES('I11','2','Bapa, Dikaulah Sang Segar,<br/>tanpa Kau usanglah;<br/>Zaman boleh saja tua,<br/>ada Kau segarlah.<br/>',NULL,60064,3);
INSERT INTO stanza VALUES('I11','3','Pada kami, s''mua berkat-Mu,<br/>barulah melulu,<br/>Janji baru, jalan baru,<br/>selamanya baru.<br/>',NULL,60065,4);
INSERT INTO stanza VALUES('I11','4','Kami ciptaan baru-Mu,<br/>orang, hati, dan roh;<br/>Hari-hari kian baru,<br/>penuh ragam baru.<br/>',NULL,60066,5);
INSERT INTO stanza VALUES('I11','5','Langit, bumi, ne''gri baru,<br/>semuanya baru;<br/>Bulan-bulan buah baru,<br/>s''lamanya tak luruh.<br/>',NULL,60067,6);
INSERT INTO stanza VALUES('I11','6','Bapa, Dikau segar terus,<br/>terpuji tak putus!<br/>Pujian bersambung kidung,<br/>segar-Mu tak pupus.<br/>',NULL,60068,7);
INSERT INTO stanza VALUES('I12','1','Ku meninjau alam ciptaan Allah;<br/>langit, bumi, dan semua isinya,<br/>Pusparagam, sungguh indah dan megah;<br/>''nyatakan kuasa-Mu tak terhingga.<br/>',NULL,60069,1);
INSERT INTO stanza VALUES('I12','chorus','Hatiku, rohku pujilah seg''ra.<br/>Dikau ajaib! Dikau agung!<br/>Suara pujian sampai selamanya.<br/>Dikau ajaib! Dikau agung!<br/>',NULL,60070,2);
INSERT INTO stanza VALUES('I12','2','Saat ''ngecap kurnia ajaib nan megah,<br/>terkenang Dikau utus Sang Putra.<br/>Mati, bangkit, lahir ciptaan baru;<br/>menyatakan hayat-Mu sepenuh.<br/>',NULL,60071,3);
INSERT INTO stanza VALUES('I12','3','Dalam sidang nikmat berkat sekutu,<br/>''nampak S''rani penuhlah hayat-Mu.<br/>Dibangunkan menjadi istana-Mu,<br/>k''limpahan-Mu ternyata seluruh.<br/>',NULL,60072,4);
INSERT INTO stanza VALUES('I12','4','Saat tiba, harapanku terpenuh,<br/>ku berbagian Yerusalem Baru.<br/>Usang sirna, semua jadi baru,<br/>genap nyata segala ada-Mu.<br/>',NULL,60073,5);
INSERT INTO stanza VALUES('I13','1','Pada-Mu, ya Bapa, tiada bayangan,<br/>setia-Mu besar tak terbatas.<br/>Dulu, kini, kelak, Kau tetap ada;<br/>Kekal rahmat-Mu, p''ri Kau tak ubah.<br/>',NULL,60074,1);
INSERT INTO stanza VALUES('I13','chorus','Besar setia-Mu! Besar setia-Mu!<br/>Tiap pagi rahmat-Mu t''rus baru!<br/>Semua perluku, Kau yang sediakan;<br/>besar setia-Mu tak bersudah!<br/>',NULL,60075,2);
INSERT INTO stanza VALUES('I13','2','Musim ''tabur, ''tuai, t''rus bergantian,<br/>surya, bulan, bintang beredaran;<br/>Suasana alam b''ri kesaksian;<br/>Besar setia-Mu, tak bersudah!<br/>',NULL,60076,3);
INSERT INTO stanza VALUES('I13','3','Ampunan-Mu bawa damai pun riang,<br/>hadir-Mu b''ri hibur, b''ri bimbingan;<br/>Tenaga kini dan harapan kelak,<br/>s''mua milikku, berkat tak berkurang.<br/>',NULL,60077,4);
INSERT INTO stanza VALUES('I14','1','Bapa Kau betapa setia,<br/>patut diandalkan!<br/>Alam s''mesta persaksikan<br/>kesetiaan-Mu.<br/>',NULL,60078,1);
INSERT INTO stanza VALUES('I14','chorus','Setia-Mu teguh, kukuh,<br/>kami menyembah-Mu!<br/>Hari-hari t''rus menerus,<br/>s''lamanya bagiku.<br/>',NULL,60079,2);
INSERT INTO stanza VALUES('I14','2','Padamu tiada bayangan<br/>atau perubahan;<br/>Dulu, kini, hingga kekal,<br/>Kau tetap tak ubah.<br/>',NULL,60080,3);
INSERT INTO stanza VALUES('I14','3','Firman-Mu s''perti diri-Mu,<br/>tak mungkin berlalu;<br/>Walau langit, bumi lalu,<br/>tetaplah Firman-Mu.<br/>',NULL,60081,4);
INSERT INTO stanza VALUES('I14','4','Atas kurnia dan panggilan,<br/>Kau tak pernah sesal;<br/>Kasih kurnia dan rahmat-Mu,<br/>teguh p''ri nama-Mu.<br/>',NULL,60082,5);
INSERT INTO stanza VALUES('I14','5','Firman-Mu tambah setia-Mu,<br/>jadi jaminanku;<br/>Terhadap ke''slamatan-Mu,<br/>ku yakin, tak ragu.<br/>',NULL,60083,6);
INSERT INTO stanza VALUES('I14','6','Bila aku tak setia,<br/>Kau tetap setia;<br/>Kau tak dapat sangkal diri,<br/>firman-Mu g''nap pasti.<br/>',NULL,60084,7);
INSERT INTO stanza VALUES('I14','7','Janji kurnia-Mu padaku,<br/>Kau genapkan tentu;<br/>Kini nikmati setia-Mu<br/>dan kemanisan-Mu.<br/>',NULL,60085,8);
INSERT INTO stanza VALUES('I14','8','P''langi lingkungi takhta-Mu,<br/>nyatakan setia-Mu;<br/>Pula dasar kota Kudus,<br/>saksikan setia-Mu.<br/>',NULL,60086,9);
INSERT INTO stanza VALUES('I15','1','Tanpa darah, dapat ampun;<br/>mana keadilan?<br/>Darah alir, tetap tuntut;<br/>itu pun tak benar.<br/>',NULL,60087,1);
INSERT INTO stanza VALUES('I15','2','Kini Allah tak menuntut;<br/>Tuhan t''lah berkurban;<br/>Bebas mutlaklah diriku,<br/>dosaku terenyah!<br/>',NULL,60088,2);
INSERT INTO stanza VALUES('I15','3','Tuntutan keadilan-Mu,<br/>dibayar Tuhan-ku;<br/>Berlaku kini ampunan,<br/>usailah hukuman.<br/>',NULL,60089,3);
INSERT INTO stanza VALUES('I15','4','Kasih suruh Dia menebus,<br/>puaskan tuntutan;<br/>Kini Tuhan membebaskan<br/>s''mua tawanan dosa.<br/>',NULL,60090,4);
INSERT INTO stanza VALUES('I15','5','Ajaib, ajaib, atas salib,<br/>nampak kasih-adil;<br/>Kasih-adil saling isi,<br/>pujianku tak henti.<br/>',NULL,60091,5);
INSERT INTO stanza VALUES('I16','1','Kami memuji adil-Mu,<br/>pula kagumi benar-Mu,<br/>Saksikan selalu.<br/>Kaulah Hakim s''luruh bumi,<br/>pada-Mu tiada yang lalim,<br/>Dikau sungguh adil!<br/>',NULL,60092,1);
INSERT INTO stanza VALUES('I16','2','Adil - pondasi takhta-Mu,<br/>olehnya damai bertumpu,<br/>Se''pri setia-Mu!<br/>Demi adil dan benar-Mu,<br/>merajalah kurnia Kristus,<br/>Damaipun milikku!<br/>',NULL,60093,2);
INSERT INTO stanza VALUES('I16','3','Adil-Mu membuat Putra-Mu,<br/>naik salib, t''rima mati,<br/>Genapkan tebusan;<br/>Saat manusia percaya,<br/>adil-Mu se''gra benarkan,<br/>Dapat kes''lamatan.<br/>',NULL,60094,3);
INSERT INTO stanza VALUES('I16','4','Demi tampilkan adil-Mu,<br/>Kau dulu pernah membiarkan,<br/>Semua pelanggaran;<br/>Demi tampilkan adil-Mu,<br/>kini Kau beri ampunan,<br/>Kepada yang dosa.<br/>',NULL,60095,4);
INSERT INTO stanza VALUES('I16','5','Kelak, semua Kau adili,<br/>mutlak nyatalah adil-Mu,<br/>Oleh Kristus Tuhan.<br/>Bersandar pada adil-Mu,<br/>kami ''kan berdiri teguh,<br/>Nyatalah kur-nia-Mu.<br/>',NULL,60096,5);
INSERT INTO stanza VALUES('I16','6','Penuh adil k''rajaan-Mu,<br/>atasnya damai terbangun,<br/>Harmonis seluruh;<br/>Dalam langit, bumi baru,<br/>terlebih penuh adil-Mu,<br/>Sesuai janji-Mu.<br/>',NULL,60097,6);
INSERT INTO stanza VALUES('I17','1','Dalam dosa, penuh d''rita,<br/>adil-Mu tuntut hukuman.<br/>Dia berdarah menebusku,<br/>adil-Mu b''ri sejahtera.<br/>',NULL,60098,1);
INSERT INTO stanza VALUES('I17','2','Adil-Mu membuat Tuhanku<br/>pikul salib, tanggung dosa;<br/>Adil-Mu pun b''ri ampunan,<br/>pembenaran, dan sentosa.<br/>',NULL,60099,2);
INSERT INTO stanza VALUES('I17','3','Adil-Mu tuntut hitungan,<br/>harus lunas semua hutang;<br/>Set''lah lunas Kau menjamin,<br/>tak akan menagih ulang.<br/>',NULL,60100,3);
INSERT INTO stanza VALUES('I17','4','Sekali Tuhan berdarah,<br/>salib tak mungkin diulang;<br/>Rampung sudah s''mua tuntutan,<br/>ku terampun, dibersihkan.<br/>',NULL,60101,4);
INSERT INTO stanza VALUES('I17','5','Dulu dengar "Engkau adil",<br/>ku gemetar, bersembunyi;<br/>Kini dengar "Engkau adil",<br/>ku malah amat tertarik.<br/>',NULL,60102,5);
INSERT INTO stanza VALUES('I17','6','Sejak mengenal adil-Mu,<br/>ku makin paham kurnia-Mu;<br/>Adil membuatku sentosa,<br/>kurnia membuatku p''nuh lega.<br/>',NULL,60103,6);
INSERT INTO stanza VALUES('I18','1','Atas adil-Mu, ya, Bapa,<br/>kami sujud menyembah;<br/>Ku dib''narkan kar''na Pu-tra<br/>siapa dapat menggugat?<br/>Dikau adil pun setia,<br/>atasnya aku tegak;<br/>Dikau adil, adil mutlak,<br/>siapa dapat mengubah?<br/>',NULL,60104,1);
INSERT INTO stanza VALUES('I18','2','Dosaku dipikul Yesus,<br/>''nimpa Dia ganjaran-mu;<br/>Tuntutan hukum Taurat-Mu,<br/>dig''napi-Nya sepenuh.<br/>Terbayarlah harga tebus,<br/>kini bebaslah aku;<br/>Mutlak sempurna adil-Mu,<br/>mustahil ''nagih terus.<br/>',NULL,60105,2);
INSERT INTO stanza VALUES('I18','3','Bapa, Kau t''lah menerima<br/>Yesus jadi pengganti;<br/>Sang Benar t''rima hukuman,<br/>menggantiku yang lalim.<br/>Kanan-Mu, Dia kini duduk,<br/>adil-Mu pun terbukti;<br/>Mutlak puas Dikau kini,<br/>adil kukuh abadi.<br/>',NULL,60106,3);
INSERT INTO stanza VALUES('I18','4','Demi darah adi Kristus,<br/>ku beroleh benar-Mu;<br/>Bawah naungan adil-Mu,<br/>tiada yang goyahkanku.<br/>Bahkan ku jadi benar-Mu,<br/>siapa pula menuduh?<br/>K''lak di Yerusalem Baru,<br/>kesaksianku tak luntur!<br/>',NULL,60107,4);
INSERT INTO stanza VALUES('I19','1','Bapa kudus, kami sujud,<br/>kidung pujian membubung;<br/>Dikau kudus lagi unggul,<br/>kekal layak dijunjung.<br/>',NULL,60108,1);
INSERT INTO stanza VALUES('I19','2','Bapa, hati-Mu p''nuh kasih,<br/>adil-benar tindak-Mu;<br/>Tabiat-Mu kudus, suci,<br/>ku berbagian diri-Mu.<br/>',NULL,60109,2);
INSERT INTO stanza VALUES('I19','3','Oleh darah adi Kristus,<br/>kekal ku jadi kudus;<br/>Pula oleh keb''naran-Mu,<br/>ku terpisah seluruh.<br/>',NULL,60110,3);
INSERT INTO stanza VALUES('I19','4','Melalui Roh Kudus-Mu<br/>ku ditakdis bagi-Mu;<br/>Hingga roh, jiwa, tubuhku,<br/>dikuduskan seluruh.<br/>',NULL,60111,4);
INSERT INTO stanza VALUES('I19','5','Oleh kurnia ku dapatkan<br/>hayat kudus Sang Kristus;<br/>Hingga aku berbagian<br/>dalam sifat kudus-Mu.<br/>',NULL,60112,5);
INSERT INTO stanza VALUES('I19','6','Kelak dalam kota kudus,<br/>berbagian kudus-Mu;<br/>Hingga kekal persaksikan,<br/>Dikau betapa kudus.<br/>',NULL,60113,6);
INSERT INTO stanza VALUES('I20','1','Oleh hikmat-Mu, ya Bapa,<br/>sesuai kehendak-Mu,<br/>Alam s''mesta Kau rancangkan,<br/>terpenuhi Putra.<br/>',NULL,60114,1);
INSERT INTO stanza VALUES('I20','chorus','Hikmat-Mu dalam pun limpah,<br/>siapa bisa ukur?<br/>Olehnya ku mendapatkan<br/>rahmat, kurnia Bapa.<br/>',NULL,60115,2);
INSERT INTO stanza VALUES('I20','2','Sungguh ajaib ciptaan-Mu,<br/>siapa ta''u hati-Mu?<br/>Dari, oleh, dan untuk-Mu,<br/>nyatalah hikmat-Mu.<br/>',NULL,60116,3);
INSERT INTO stanza VALUES('I20','3','Hikmat-Mu bungkam s''mua dosa,<br/>tampaklah rahmat-Mu;<br/>Agar tiada yang bermegah,<br/>selain di dalam-Mu.<br/>',NULL,60117,4);
INSERT INTO stanza VALUES('I20','4','Dengan hikmat, oleh salib,<br/>Kau rampung tebusan;<br/>Agar dalam roh ku s''mayam,<br/>Dikau Sang Mustika.<br/>',NULL,60118,5);
INSERT INTO stanza VALUES('I20','5','G''reja pamerkan hikmat-Mu,<br/>pada penguasa;<br/>Oleh g''reja s''mua hikmat-Mu,<br/>tampak di angkasa.<br/>',NULL,60119,6);
INSERT INTO stanza VALUES('I20','6','Dalam Yerusalem Baru,<br/>rahmat-Mu ku bangga;<br/>Ternyata bulat hikmat-Mu,<br/>sampai selamanya.<br/>',NULL,60120,7);
INSERT INTO stanza VALUES('I21','1','Di dalam Kristus berdiam<br/>hikmat dan kurnia-Mu;<br/>Kau jadikan Dia hikmatku,<br/>aku t''rima berkat.<br/>Kau jadikan Dia hikmatku,<br/>aku t''rima berkat.<br/>',NULL,60121,1);
INSERT INTO stanza VALUES('I21','2','Pada-Nya s''mua rencana-Mu,<br/>jalan karunia-Mu;<br/>Di dalam Dia - hikmat-Mu,<br/>ku nikmat limpah-Mu.<br/>Di dalam Dia - hikmat-Mu,<br/>ku nikmat limpah-Mu.<br/>',NULL,60122,2);
INSERT INTO stanza VALUES('I21','3','Kar''na Dia, ku dibenarkan,<br/>Dia kebenaranku;<br/>Oleh Dia, Sang Kekudusan,<br/>kami dikuduskan.<br/>Oleh Dia, Sang Kekudusan,<br/>kami dikuduskan.<br/>',NULL,60123,3);
INSERT INTO stanza VALUES('I21','4','Sesuai rencana kekal-Mu,<br/>Dia pun P''nebusanku;<br/>Tubuh kami pun ditebus,<br/>dewasa seluruh.<br/>Tubuh kami pun ditebus,<br/>dewasa seluruh.<br/>',NULL,60124,4);
INSERT INTO stanza VALUES('I21','5','Bapa, Dialah hikmat-Mu,<br/>dalam ekonomi-Mu;<br/>Bagi Dia, kami menyembah,<br/>panjatkan pujian.<br/>Bagi Dia, kami menyembah,<br/>panjatkan pujian.<br/>',NULL,60125,5);
INSERT INTO stanza VALUES('I21','6','Hikmat-Mu nyata pada-Nya,<br/>limpah, dalam, luas;<br/>Perlu makin limpah, dalam,<br/>ternyata atasku.<br/>Perlu makin limpah, dalam,<br/>ternyata atasku.<br/>',NULL,60126,6);
INSERT INTO stanza VALUES('I22','1','Bapa, rahmat-Mu terpuja,<br/>besar, agung, tak hingga;<br/>Atas lemah, gagal kami,<br/>rahmat-Mu makin tambah.<br/>Kini kami sujud sembah:<br/>pengangkatan nan rahmat!<br/>Pengangkatan nan rahmat!<br/>',NULL,60127,1);
INSERT INTO stanza VALUES('I22','2','Kami kagum ''tas rahmat-Mu,<br/>luas, besar, tak batas;<br/>Jangkau kami, orang dosa,<br/>bahkan kekal tak ubah.<br/>Dari rahmat yang de-mi-kian,<br/>sia-pa yang ''kan pisahkan?<br/>sia-pa yang ''kan pisahkan?<br/>',NULL,60128,2);
INSERT INTO stanza VALUES('I22','3','Atas rahmat-Mu yang kaya,<br/>syukur kami sembahkan!<br/>Kar''na rahmat, penebusan,<br/>suplai limpah Kau b''rikan.<br/>Tanpa rahmat, bagaimana<br/>kami bisa dikenan?<br/>Kami bisa dikenan?<br/>',NULL,60129,3);
INSERT INTO stanza VALUES('I22','4','O, rahmat-Mu menakjubkan,<br/>lembut, manis, pun mesra!<br/>Sabar-Mu, kasih kur-nia-Mu,<br/>cukupi kebutuhan.<br/>Kami mengapresiasikan<br/>rahmat-Mu nan sempurna.<br/>Rahmat-Mu nan sempurna.<br/>',NULL,60130,4);
INSERT INTO stanza VALUES('I22','5','Kini nikmati rahmat-Mu,<br/>baru, kekal tak usang;<br/>Se-tiap pagi, atas kami,<br/>p''ri embun diris segar.<br/>Sungguh indah! Sungguh nyaman!<br/>Genap hati puji Dia.<br/>Genap hati puji Dia.<br/>',NULL,60131,5);
INSERT INTO stanza VALUES('I22','6','Takkan henti pu-jian kami<br/>''tas rahmat-Mu yang kekal;<br/>Ka-ru-nia dan asuhan-Mu,<br/>pada kami s''lamanya.<br/>Sungguh rahmat, b''tapa rahmat,<br/>meneguhkan s''lamanya,<br/>meneguhkan s''lamanya.<br/>',NULL,60132,6);
INSERT INTO stanza VALUES('I23','1','Bapa, rahmat-Mu t''lah Kau ''nyatakan,<br/>pada kami,<br/>orang dosa p''riku Kau b''ri hayat,<br/>jadi anak.<br/>Wadah rahmat, takdir-Mu ''tas kami,<br/>Wadah mulia, saksikan Kau s''lama.<br/>',NULL,60133,1);
INSERT INTO stanza VALUES('I23','2','"Kenan rahmat, bukan sembah kurban,"<br/>Kau ''nyatakan;<br/>Oleh rahmat, kami t''rima kur-nia,<br/>serta mulia.<br/>Bukan tekad, usaha manusia,<br/>melainkan, Allah Sang Perahmat.<br/>',NULL,60134,2);
INSERT INTO stanza VALUES('I23','3','Rahmat, kasih, kur-nia-Mu, ya Bapa,<br/>kami kecap;<br/>Rahmat-Mu mendatangkan hadir-Mu<br/>dan wajah-Mu.<br/>Atas rahmat, kini kami sembah,<br/>syukur puji, sampai sela-manya.<br/>',NULL,60135,3);
INSERT INTO stanza VALUES('I24','1','Kasih Allah tak terbilang<br/>oleh mulut maupun pena;<br/>lebih tinggi dari bintang,<br/>lebih dalam dari n''raka.<br/>Meski kami t''lah berdosa<br/>Dia b''ri Juru-s''lamat;<br/>kami tobat, Allah sambut,<br/>semua dosa hapus.<br/>',NULL,60136,1);
INSERT INTO stanza VALUES('I24','chorus','Kasih Allah berlimpahlah,<br/>tak mungkin terukur!<br/>teguh s''lama sampai kekal,<br/>kami s''mua bersyukur.<br/>',NULL,60137,2);
INSERT INTO stanza VALUES('I24','2','Zaman demi zaman lewat,<br/>langit bumi pada ubah;<br/>Manusia tolak kasih-Nya,<br/>k''lak menyesal tiada guna.<br/>Kasih Allah tak berubah,<br/>tak mungkin terukur;<br/>Hutang dosa Dia lunaskan,<br/>kami s''mua bersyukur.<br/>',NULL,60138,3);
INSERT INTO stanza VALUES('I24','3','Meski lautan jadi tinta,<br/>cakrawala jadi kertas;<br/>hutan resam jadi pena,<br/>tiap orang jadi sastrawan.<br/>Bila tuliskan kasih-Nya,<br/>sampai habis semua;<br/>Tidak dapat menuliskan<br/>setitik kasih-Nya.<br/>',NULL,60139,4);
INSERT INTO stanza VALUES('I25','1','Bapa, betapa kasih-Mu,<br/>hatiku bersyukur;<br/>sambil sujud di depan-Mu,<br/>ku puji nama-Mu.<br/>',NULL,60140,1);
INSERT INTO stanza VALUES('I25','2','Kau buka isi hati-Mu,<br/>''nyatakan maksud-Mu;<br/>Di dalam Yesus Putra-Mu,<br/>g''naplah kehendak-Mu.<br/>',NULL,60141,2);
INSERT INTO stanza VALUES('I25','3','Kar''na kasih-Mu padaku,<br/>Kau korbankan Putra;<br/>Hingga ku jadi anak-Mu,<br/>sewaris dengan Dia.<br/>',NULL,60142,3);
INSERT INTO stanza VALUES('I25','4','Demi Dia dapat hayat-Mu,<br/>ber-Bapa pada-Mu;<br/>Berbagian tabiat-Mu,<br/>nikmati limpah-Mu.<br/>',NULL,60143,4);
INSERT INTO stanza VALUES('I25','5','Dalam Roh Kau masuk rohku,<br/>Kau ku panggil, "Abba";<br/>Lahir ulang di dalam roh,<br/>dalam roh ku b''rubah.<br/>',NULL,60144,5);
INSERT INTO stanza VALUES('I25','6','Pimpin s''mua ke dalam mulia,<br/>itulah tujuan-Mu;<br/>Serupa dengan Sang Putra,<br/>itu rencana-Mu.<br/>',NULL,60145,6);
INSERT INTO stanza VALUES('I25','7','Dalam proses pengubahan,<br/>Kau yang pimpin ''tiasa;<br/>Tambah t''naga, tambah mulia,<br/>diubah sempurna.<br/>',NULL,60146,7);
INSERT INTO stanza VALUES('I25','8','Bapa, betapa kasih-Mu,<br/>kekal ku bersyukur;<br/>Kekal bersujud pada-Mu,<br/>dan puji nama-Mu.<br/>',NULL,60147,8);
INSERT INTO stanza VALUES('I26','1','Meski kasih-Mu berlimpah,<br/>ya, Pemberi kurnia!<br/>Tapi di surga tiada<br/>yang m''lebihi darah.<br/>',NULL,60148,1);
INSERT INTO stanza VALUES('I26','2','Imanku terhadap darah,<br/>kasih-Mu yang memb''ri;<br/>Jika kurnia tanpa cinta,<br/>sia-sia tak berarti.<br/>',NULL,60149,2);
INSERT INTO stanza VALUES('I26','3','Kasih Allah p''ri samudra,<br/>membenam dosaku;<br/>Lalimku semua Kau tutup,<br/>hutangku Kau hapus.<br/>',NULL,60150,3);
INSERT INTO stanza VALUES('I26','4','Dalam darah ku jumpai,<br/>tanda hati kasih;<br/>Kini ku tahu rahmat-Mu<br/>dan keadilan-Mu.<br/>',NULL,60151,4);
INSERT INTO stanza VALUES('I26','5','Hati lesu, raga renta,<br/>ku tetap beriman;<br/>Meski langit, bumi musnah,<br/>sauhku tak goyah.<br/>',NULL,60152,5);
INSERT INTO stanza VALUES('I26','6','Hari itu ku buktikan,<br/>kasih-Mu mustika;<br/>Namun hidupku sekarang,<br/>bersandar pada-Nya.<br/>',NULL,60153,6);
INSERT INTO stanza VALUES('I26','7','Ku memuji dan memuji,<br/>semua Kau yang memb''ri;<br/>Jurus''lamat yang mustika,<br/>beserta kuasa-Nya.<br/>',NULL,60154,7);
INSERT INTO stanza VALUES('I27','1','Ya, Allah, mengapa<br/>b''rikan Yesus Kristus,<br/>Putra yang Kau cinta,<br/>mati buat yang jatuh?<br/>Tak lain kar''na cinta-Mu,<br/>tak lain kar''na cinta-Mu.<br/>Kau korbankan Kekasih-Mu.<br/>',NULL,60155,1);
INSERT INTO stanza VALUES('I27','2','Putra-Mu mengapa<br/>tinggalkan takhta-Nya,<br/>D''rita sampai mati,<br/>cucurkan darah-Nya?<br/>Tak lain kar''na cinta-Nya,<br/>tak lain kar''na cinta-Nya.<br/>Hingga buatku Dia men''drita.<br/>',NULL,60156,2);
INSERT INTO stanza VALUES('I27','3','Ya, Allah, mengapa<br/>Kau b''rikan Roh Kudus,<br/>Bawa damai surga<br/>penuhi hatiku?<br/>Tak lain kar''na cinta-Mu,<br/>tak lain kar''na cinta-Mu.<br/>Yang mengutus Dia padaku.<br/>',NULL,60157,3);
INSERT INTO stanza VALUES('I27','4','Besarlah kurnia-Mu,<br/>piciklah cintaku!<br/>Patutlah hatiku<br/>bersorak p''nuh syukur.<br/>Ya, Allah, atas cinta-Mu,<br/>ya, Allah, atas cinta-Mu.<br/>Hingga kekallah syukurku<br/>',NULL,60158,4);
INSERT INTO stanza VALUES('I28','1','Allah, Kau di tempat kudus,<br/>t''rima sembah serta syukur,<br/>Kar''na kasih-Mu tulus.<br/>Kami mati dalam dosa,<br/>p''ri tawanan putus asa,<br/>Kau datang membebaskan.<br/>Kasih-Mu tiada batas,<br/>membelas kasihani kami,<br/>Dan meny''lamatkan ka-mi.<br/>',NULL,60159,1);
INSERT INTO stanza VALUES('I28','2','Kau tak mau kami binasa,<br/>Kau ingin kami berbalik,<br/>Kau jadi Jurus''lamat.<br/>Dalam Putra pilih kami,<br/>lepas dari dosa maut,<br/>Kau berikan bahagia.<br/>Kami boleh sebut "Abba",<br/>demi Putra kami b''rani,<br/>berhampir pada Bapa.<br/>',NULL,60160,2);
INSERT INTO stanza VALUES('I28','3','Dia ''kan sambut kami pulang,<br/>kami kitari takhta-Mu,<br/>Sambil sujud dan syukur.<br/>Kidung mesra ''kan membubung,<br/>sampai ke s''gala penjuru,<br/>Dari g''reja semesta.<br/>Kini kami mendambakan<br/>bersembah sujud pada-Mu,<br/>Nyanyikan kidung kurnia.<br/>',NULL,60161,3);
INSERT INTO stanza VALUES('I29','1','Dulu, hanya dosa, maut,<br/>saja kami punya;<br/>Kini, semua berkat bah''gia,<br/>dari Allah s''mata.<br/>',NULL,60162,1);
INSERT INTO stanza VALUES('I29','2','Cinta, mencari yang dosa,<br/>tarikku percaya;<br/>Sejahtera demi iman,<br/>hidup oleh Kristus.<br/>',NULL,60163,2);
INSERT INTO stanza VALUES('I29','3','Yang ku nikmati sekarang,<br/>dan harapan kelak;<br/>Semua tak layak ku dapat,<br/>kurnia-Mu belaka.<br/>',NULL,60164,3);
INSERT INTO stanza VALUES('I29','4','Limpah, kasih-Mu, ya Allah,<br/>siapa dapat balas?<br/>Melampaui segalanya,<br/>kudus, tak terpaham.<br/>',NULL,60165,4);
INSERT INTO stanza VALUES('I29','5','Ajarku ya Bapa,<br/>agar kenal lebih banyak;<br/>Kau Allah Sang Kasih:<br/>jiwa, hati, ku serahkan.<br/>',NULL,60166,5);
INSERT INTO stanza VALUES('I29','6','Bila ku kata di hati,<br/>ingin balas budi;<br/>Pertanda ku b''lum mengerti,<br/>kurnia-Mu tak terp''ri.<br/>',NULL,60167,6);
INSERT INTO stanza VALUES('I29','7','Tak tawar-menawar lagi,<br/>kasih-Mu tak hingga,<br/>Kau mend''rita kar''na kasih,<br/>betapa ku balas?<br/>',NULL,60168,7);
INSERT INTO stanza VALUES('I29','8','Tak b''rani ku kata lagi:<br/>ingin balas budi;<br/>Hati penuh syukur puji,<br/>menyembah abadi.<br/>',NULL,60169,8);
INSERT INTO stanza VALUES('I29','9','Allah Bapa, kami hutang,<br/>banyak tak terbilang;<br/>Sejahtera kar''na Putra,<br/>sembah syukur ''tiasa.<br/>',NULL,60170,9);
INSERT INTO stanza VALUES('I30','1','Bapa, kami sujud, sembah,<br/>takjub kasih-Mu nan besar!<br/>Apa insan? Engkau ingat,<br/>hina p''ri ku, Kau pilih jua.<br/>',NULL,60171,1);
INSERT INTO stanza VALUES('I30','2','Kami puji kehendak-Mu,<br/>manusia ''kan serupa-Mu;<br/>Punya hayat dan sifat-Mu,<br/>segambar-Mu, serupa-Mu.<br/>',NULL,60172,2);
INSERT INTO stanza VALUES('I30','3','Cipta insan segambar-Mu,<br/>bahkan Kau beri kuasa-Mu;<br/>Jadi hayat dalam insan,<br/>insan nikmat s''mua ada-Mu.<br/>',NULL,60173,3);
INSERT INTO stanza VALUES('I30','4','Kau mau masuk dalam insan,<br/>baur pun genapkan insan;<br/>Ubah, bangun seluruhnya,<br/>tampil bait-Mu nan mulia.<br/>',NULL,60174,4);
INSERT INTO stanza VALUES('I30','5','Insan jatuh, Kau tak buang,<br/>kehendak-Mu tetap garap;<br/>Kau menebus, bawa balik,<br/>nyata limpah kasih, hikmat.<br/>',NULL,60175,5);
INSERT INTO stanza VALUES('I30','6','Dalam Kristus, Kau terwahyu,<br/>mati, bangkit, g''nap tebusan;<br/>Menjadi Roh, masuk insan,<br/>rawat, asuh dengan kurnia.<br/>',NULL,60176,6);
INSERT INTO stanza VALUES('I30','7','Rohku tempat maha kudus,<br/>ada takhta kasih kurnia;<br/>Rohku sekutu dengan-Mu,<br/>doa membakar ukupan.<br/>',NULL,60177,7);
INSERT INTO stanza VALUES('I30','8','Kasih kurnia p''ri bengawan,<br/>''ngalir dari takhta kurnia;<br/>Aliriku, mengubahku,<br/>bangun aku jadi bait-Mu.<br/>',NULL,60178,8);
INSERT INTO stanza VALUES('I30','9','T''rima limpah kasih kurnia,<br/>karunia cuma-cuma;<br/>Syukur atas kasih besar,<br/>dalam roh kami menyembah.<br/>',NULL,60179,9);
INSERT INTO stanza VALUES('I31','1','Abba, seb''lum dunia ada,<br/>Kau t''lah pilih kami s''mua;<br/>Kasih ini sungguh mesra,<br/>tarik kami hampir Dia.<br/>Masih perlu Kau p''lihara,<br/>hingga teguh s''lamanya,<br/>hingga teguh ''slamanya.<br/>',NULL,60180,1);
INSERT INTO stanza VALUES('I31','2','Meski alam kian berubah,<br/>Allahku tak berubah;<br/>Kasih Allah dan sabda-Nya,<br/>teguh kukuh s''lamanya.<br/>Hai, marilah, anak Allah,<br/>datang puji nama-Nya!<br/>Datang puji nama-Nya!<br/>',NULL,60181,2);
INSERT INTO stanza VALUES('I31','3','Belas Allah jadi mazmur,<br/>kemegahan riangku;<br/>Seterusnya, kurnia s''mata,<br/>jamah jiwa, hatiku.<br/>Allah kasih akan kami,<br/>hingga s''rahkan Putra Hu!<br/>Hingga s''rahkan Putra Hu!<br/>',NULL,60182,3);
INSERT INTO stanza VALUES('I31','4','Pada Allah, Sang Pengasih,<br/>gita kami serasi;<br/>Sampai surga, jauh duli,<br/>kami tetap memuji.<br/>Semua mulia, kekal bagi<br/>Allah dan Domba Suci,<br/>Allah dan Domba Suci.<br/>',NULL,60183,4);
INSERT INTO stanza VALUES('I32','1','Bapa mulia, ku puji,<br/>aku sasaran-Mu;<br/>Pujian ku sembahkan,<br/>agar s''nang hati-Mu.<br/>S''mua putra masuk mulia,<br/>itu penentuan-Mu;<br/>Dengan Kristus jadilah<br/>sasaran teragung.<br/>',NULL,60184,1);
INSERT INTO stanza VALUES('I32','2','Ku Kau pilih pun takdis,<br/>seb''lum dunia jadi;<br/>T''rima kurnia,<br/>menjadi milik-Mu abadi.<br/>Dapat hak keputraan,<br/>Kau b''ri sejak dini;<br/>Hinggalah akil balig,<br/>berkat ku alami.<br/>',NULL,60185,2);
INSERT INTO stanza VALUES('I32','3','Sesuai penentuan-Mu,<br/>Kau memanggil aku;<br/>S''mua dosaku terhapus,<br/>dapatkan hayat-Mu;<br/>Roh Kudus meteraikan,<br/>pun menyuplai terus;<br/>Kekal aku milik-Mu,<br/>nikmati limpah-Mu.<br/>',NULL,60186,3);
INSERT INTO stanza VALUES('I32','4','Bapa selain Dikau,<br/>siapa lagi mampu:<br/>Membuat kami berbagian,<br/>d''ngan Roh dan hayat-Mu?<br/>Tak lama kami semua,<br/>semulia Putra-Mu;<br/>Kekal hidup depan-Mu,<br/>''nyatakan mulia-Mu<br/>',NULL,60187,4);
INSERT INTO stanza VALUES('I33','1','Ya Bapa, Kau dalam Domba<br/>harapan dan perhentianku.<br/>Dari nama-Mu ternyata<br/>kasih dan berkat bagiku.<br/>',NULL,60188,1);
INSERT INTO stanza VALUES('I33','2','Besar, hikmat, adil, lembut,<br/>Kaulah Bapa dan Allahku;<br/>Oleh darah, ku milik-Mu,<br/>jadi anak, kekal padu.<br/>',NULL,60189,2);
INSERT INTO stanza VALUES('I33','3','Kami bawa roh yang lesu,<br/>datang berharap pada-Mu;<br/>P''nuh d''rita, berkat ku cari,<br/>s''perti rusa rindukan air.<br/>',NULL,60190,3);
INSERT INTO stanza VALUES('I33','4','Mohon Bapa beri berkat,<br/>biar hampir Kau kami dapat;<br/>Hadir-Mu, kediamanku,<br/>kasih-Mu jadi riangku.<br/>',NULL,60191,4);
INSERT INTO stanza VALUES('I33','5','Biarlah ku girang s''lamanya,<br/>malam kelam jadi terang;<br/>Jika ku masih bersuara,<br/>tentu ku puji Kau s''lama.<br/>',NULL,60192,5);
INSERT INTO stanza VALUES('I34','1','Mulia bagi Allah atas karya-Nya,<br/>Putra diutus demilah kasih-Nya.<br/>Korban bagi kita, g''napkan tebusan,<br/>buka pintu hayat bagi manusia.<br/>',NULL,60193,1);
INSERT INTO stanza VALUES('I34','chorus','Puji Dia! Puji Dia!<br/>Semesta puji Dia!<br/>Puji Dia! Puji Dia!<br/>S''mua sorak gempita!<br/>Datang pada Bapa demilah Putra,<br/>Mulia bagi Allah atas karya-Nya.<br/>',NULL,60194,2);
INSERT INTO stanza VALUES('I34','2','Tebusan sempurna, darah-Nya bayar,<br/>bagi kita semua janji-Nya andal;<br/>Orang paling jahat, asal percaya,<br/>t''rima ampunan-Nya sekarang juga.<br/>',NULL,60195,3);
INSERT INTO stanza VALUES('I34','3','Karya mahabesar t''lah Dia rampungkan,<br/>kita pun bergita oleh Sang Putra;<br/>Kita ''kan takjub saat jumpa Tuhan,<br/>sukacita kian tinggi, besar, megah.<br/>',NULL,60196,4);
INSERT INTO stanza VALUES('I35','1','Allah ku puji,<br/>Kau utus Putra-Mu,<br/>mati, bangkit, naik surga,<br/>jadi Imam-ku.<br/>',NULL,60197,1);
INSERT INTO stanza VALUES('I35','chorus','Mulia, mulia bagi Allah!<br/>Haleluya amin!<br/>Mulia, mulia bagi Allah!<br/>Syukur kurnia-Mu!<br/>',NULL,60198,2);
INSERT INTO stanza VALUES('I35','2','Allah ku puji,<br/>Kau beri Roh Terang,<br/>Yang mewahyukan:<br/>Yesus Juruselamat.<br/>',NULL,60199,3);
INSERT INTO stanza VALUES('I35','3','Mu-lia dan puji,<br/>bagi Allah P''rahmat,<br/>Demi tebusan Putra,<br/>aku selamat.<br/>',NULL,60200,4);
INSERT INTO stanza VALUES('I35','4','Puji dan syukur,<br/>kasih-Mu nan besar,<br/>Membarakan hatiku,<br/>sembahkan pu-jian.<br/>',NULL,60201,5);
INSERT INTO stanza VALUES('I36','1','Takkan penat kami nyanyi mazmur pujian;<br/>mulia, mulia, haleluya!<br/>Suara kami tetap, namun iman perkasa;<br/>mulia, mulia, haleluya!<br/>',NULL,60202,1);
INSERT INTO stanza VALUES('I36','chorus','Anak Allah s''mua berhak<br/>menyanyi dan bersorak;<br/>hari depan lebih t''rang,<br/>riang jiwa bag. terbang;<br/>Seg''ra masuk mulia,<br/>berjumpa Maharaja;<br/>Mulia, mulia, haleluya!<br/>',NULL,60203,2);
INSERT INTO stanza VALUES('I36','2','Dalam ria kasih tebusan, kami tergenang;<br/>Mulia, mulia, haleluya!<br/>Hati riang bagaikan terbang ke angkasa;<br/>Mulia, mulia, haleluya!<br/>',NULL,60204,3);
INSERT INTO stanza VALUES('I36','3','Kami menjadi kota yang dibangun Allah;<br/>Mulia, mulia, haleluya!<br/>Di dalamnya tertampak bulat mulia-Nya;<br/>Mulia, mulia, haleluya!<br/>',NULL,60205,4);
INSERT INTO stanza VALUES('I36','4','Di sana kami gubah kidung tebus baru;<br/>Mulia, mulia, haleluya!<br/>Bersama genap saleh mendampingi Yesus;<br/>Mu-ia, mulia, haleluya!<br/>',NULL,60206,5);
INSERT INTO stanza VALUES('I37','1','Abba, Bapa, kar''na Tuhan,<br/>kami datang depan-Mu;<br/>Para anak-Mu berhimpun,<br/>nikmat berkat janji-Mu.<br/>Darah-Nya t''lah membersihkan,<br/>oleh-Nya kurnia nimpa;<br/>Roh-Mu pun mengajar kami,<br/>menyebut Dikau "Abba".<br/>',NULL,60207,1);
INSERT INTO stanza VALUES('I37','2','Dulu kami sesat, hilang,<br/>terlunta dan merana;<br/>Kurnia lampaui dosaku,<br/>tolongku lepas c''laka.<br/>Kau berikan jubah kurnia,<br/>pula pesta bersama;<br/>Kami senang, Dikau girang,<br/>kurnia-Mu tak terbatas.<br/>',NULL,60208,2);
INSERT INTO stanza VALUES('I37','3','Dengan kasih Kau menyambut,<br/>''nyatakan ampun Kau b''ri;<br/>Lembu tambun t''lah tersemb''lih,<br/>kita tak pisah lagi.<br/>Kami dengar suara kasih:<br/>"Kita patut s''nang hati,<br/>Anak mati telah bangkit,<br/>yang hilang telah balik."<br/>',NULL,60209,3);
INSERT INTO stanza VALUES('I37','4','Abba, Bapa, kami puji,<br/>kasih-Mu sangat ajaib!<br/>Tent''ra surga, kar''na kami,<br/>ikut juga kagumi.<br/>Kelak, mengitari takhta,<br/>tetap kami ulangi;<br/>Kasih Abba tak terperi,<br/>nama Abba termanis.<br/>',NULL,60210,4);
INSERT INTO stanza VALUES('I38','1','Abba, dengan rendah hati,<br/>kami puji pun sembah;<br/>Mengenal-Mu kami kini,<br/>sungguh berkat bahagia.<br/>Dapatkan kuasa ini,<br/>nama Yesus sebabnya;<br/>Roh-Mu, roh kami bersaksi:<br/>kami miliki hayat.<br/>',NULL,60211,1);
INSERT INTO stanza VALUES('I38','2','Sebelum dunia bermula,<br/>dalam Dia Kau tetapkan;<br/>Kami jadi anak Allah,<br/>t''rima anug''rah hayat.<br/>Bapa, betapa kasih-Mu,<br/>kami Kau beri rahmat;<br/>kami orang dosa ini,<br/>berbagian sifat mulia.<br/>',NULL,60212,2);
INSERT INTO stanza VALUES('I38','3','Asal kami dalam Adam,<br/>sangat bejat tak tara;<br/>tapi rencana-Mu kekal,<br/>bagi-Mu Kau tetapkan,<br/>Tertebus pun lahir ulang,<br/>kami panggil Kau, Bapa;<br/>Tuhan, Bapa, g''reja - esa,<br/>kurnia ini ajaiblah!<br/>',NULL,60213,3);
INSERT INTO stanza VALUES('I38','4','Meski situasi berubah,<br/>ada d''rita, ujian;<br/>Kasih-Mu tak pernah ubah,<br/>bawaku maju ''tiasa.<br/>Tak lama kami semua,<br/>berhimpun depan takhta;<br/>Kisahkan keselamatan,<br/>syukur pada-Mu s''lama.<br/>',NULL,60214,4);
INSERT INTO stanza VALUES('I39','1','Abba Bapa, kami datang,<br/>dengan khidmat kami sembah;<br/>Kurban lainnya tak Kau ingin,<br/>kami bawa roh dan hati.<br/>',NULL,60215,1);
INSERT INTO stanza VALUES('I39','2','Bapa s''lamanya Kau ada,<br/>dari kekal hingga kekal;<br/>Takhta-Mu teguh di surga,<br/>mulia, kudus, kua-sa, mutlak.<br/>',NULL,60216,2);
INSERT INTO stanza VALUES('I39','3','Dulu kami tiada harap,<br/>kar''na dosa kami gentar;<br/>Hanya ta''u keadilan-Mu,<br/>b''lum kenal hati kasih-Mu.<br/>',NULL,60217,3);
INSERT INTO stanza VALUES('I39','4','Demi Putra-Mu yang tunggal,<br/>Kau mewahyukan diri-Mu;<br/>orang dosa b''lum terte-bus,<br/>di atas takhta Kau tak puas.<br/>',NULL,60218,4);
INSERT INTO stanza VALUES('I39','5','Putra tunggal Kau tinggalkan,<br/>untuk dapat orang dosa;<br/>a-tas salib Dia mend''rita,<br/>biar hampir-Mu kami dapat.<br/>',NULL,60219,5);
INSERT INTO stanza VALUES('I39','6','Putra terkasih-Mu mati,<br/>para putra kami jadi;<br/>Du-lu Dikau menakutkan,<br/>kini Bapa yang terkasih.<br/>',NULL,60220,6);
INSERT INTO stanza VALUES('I39','7','Kasih-Mu dalam, ya, Bapa,<br/>tak terbalaskan anak-Mu;<br/>ka-mi hanya syukur s''lama,<br/>puji dan sujud pada-Mu.<br/>',NULL,60221,7);
INSERT INTO stanza VALUES('I40','1','Lampau kini sudah,<br/>darah, mezbah, kurban;<br/>tiada asap, tiada bakar,<br/>semua telah lewat;<br/>darah adi dari<br/>nadi mulia;<br/>basuh bersih nista,<br/>lunas hutang dosa.<br/>',NULL,60222,1);
INSERT INTO stanza VALUES('I40','2','Ya, Allah, ku puji<br/>atas darah Putra;<br/>Oleh-Nya kami sentosa,<br/>t''rima pembenaran;<br/>Lepas neraka, maut,<br/>kuasa gelap,<br/>Sekali berperang,<br/>musuh lenyap musnah.<br/>',NULL,60223,2);
INSERT INTO stanza VALUES('I40','3','Ya, Allah, ku puji<br/>atas kurnia surga,<br/>Yang membenam kelaliman<br/>dan ampuni dosa!<br/>Syukur atas kasih-Mu<br/>nan jaya,<br/>P''ri mulia, kuasa,<br/>takhta-Mu hingga kekal.<br/>',NULL,60224,3);
INSERT INTO stanza VALUES('I40','4','Ya, Allah, ku puji<br/>atas pengharapan;<br/>Roh yang lembam dibangkitkan,<br/>hari jelang fajar;<br/>Harapan mulia<br/>amat menunjang,<br/>Saat penat dalam<br/>tempuhan nan berat.<br/>',NULL,60225,4);
INSERT INTO stanza VALUES('I40','5','Ya, Allah, ku puji<br/>''tas mahkota mulia;<br/>Yang bukan elok sejenak<br/>dan sekejap pudar;<br/>Tapi sep''ri takhta-Mu<br/>yang kekal;<br/>Semua kuasa, hormat,<br/>pada-Mu tersembah.<br/>',NULL,60226,5);
INSERT INTO stanza VALUES('I41','1','Bapa, Kau panggil kami,<br/>memandang Putra-Mu;<br/>Dia-lah yang Kau perkenan<br/>rampungkan murad-Mu.<br/>Demi menolong kami,<br/>Putra Kau korbankan,<br/>nyatalah dengan pasti,<br/>kurnia penebusan.<br/>',NULL,60227,1);
INSERT INTO stanza VALUES('I41','2','Bapa, Allah Perahmat,<br/>demi nama Putra;<br/>B''rani kami meminta,<br/>t''rima hayat kekal.<br/>Yang senang Kau dengarkan,<br/>merdu di telinga,<br/>Roh, jiwa kami bebas,<br/>dari semua bimbang.<br/>',NULL,60228,2);
INSERT INTO stanza VALUES('I41','3','Orang dosa gemetar,<br/>bila Kau t''rus ingat;<br/>Tapi Dia t''lah diganjar,<br/>silam Kau lupakan.<br/>Saat tiada siapa<br/>yang bisa bebaskan,<br/>Putra-Mu t''lah berkorban,<br/>hutang dosa lunas.<br/>',NULL,60229,3);
INSERT INTO stanza VALUES('I41','4','Tiada lagi murka-Mu<br/>bagi yang percaya;<br/>Tiada gentar dan takut,<br/>kar''na k''nal kasih-Mu.<br/>Yang hilang t''lah kembali,<br/>pakai jubah indah;<br/>Kasih-Mu b''ri hiburan<br/>pada hati duka.<br/>',NULL,60230,4);
INSERT INTO stanza VALUES('I41','5','O,mengapa Kau suka,<br/>pada kami ini?<br/>Kami penuh masalah,<br/>pada-Mu pun benci.<br/>O, betapa ajaib,<br/>rahasia ilahi!<br/>Kini Engkau berkata:<br/>"Milikmu Ku ini."<br/>',NULL,60231,5);
INSERT INTO stanza VALUES('I42','1','Allah Bapa, ku sembah,<br/>serta hormat terpanjat,<br/>Kristus jadi kurbanku,<br/>Bapa Kau ku sembah.<br/>',NULL,60232,1);
INSERT INTO stanza VALUES('I42','2','Kasih-Mu dalam pun luas,<br/>nyata atas wafat-Nya;<br/>Kurnia, adil ku dapat,<br/>Bapa, Kau ku sembah.<br/>',NULL,60233,2);
INSERT INTO stanza VALUES('I42','3','Dulu najis dan dosa,<br/>kini anak Sang Bapa!<br/>Rahmat ini tak tara,<br/>Bapa, Kau ku sembah.<br/>',NULL,60234,3);
INSERT INTO stanza VALUES('I42','4','Di dalam roh menyembah,<br/>Kristus realitas-Nya,<br/>Kurban harum ukupan,<br/>Bapa, Kau ku sembah.<br/>',NULL,60235,4);
INSERT INTO stanza VALUES('I42','5','Kembali ku panjatkan,<br/>pujian penyembahan,<br/>Kasih-Mu tak terhingga,<br/>Bapa, Kau ku sembah.<br/>',NULL,60236,5);
INSERT INTO stanza VALUES('I43','1','Bapa, kasih-Mu tak hingga,<br/>kami datang memuji;<br/>Men''rima kasih karunia,<br/>gembira hati kami.<br/>Sebelum dunia ada,<br/>Kau telah pilih kami;<br/>Dalam waktu Engkau datang,<br/>b''ri kurnia pada kami.<br/>',NULL,60237,1);
INSERT INTO stanza VALUES('I43','2','Dia telah Kau bangkitkan<br/>menjadi Yang Pertama,<br/>Dia rampungkan karya-Nya,<br/>oleh Dia kami menang.<br/>Kini kami jadi putra,<br/>mana mungkin tak senang,<br/>Atas kedaulatan Putra,<br/>kami memuji ''tiasa.<br/>',NULL,60238,2);
INSERT INTO stanza VALUES('I43','3','Allah Yesus, Allah kami,<br/>Bapa-Nya, Bapa kami,<br/>Dia dan kami tak terpisah,<br/>sedarah pun sedaging.<br/>Dia memimpin kami pulang,<br/>memuji dalam sidang,<br/>Kami serupa dengan-Nya,<br/>menjadi putra-putra.<br/>',NULL,60239,3);
INSERT INTO stanza VALUES('I43','4','Kasih, kurnia nan ilahi,<br/>Putra-kami - bersatu,<br/>Ini bagian kekal kami,<br/>menyenangkan hati-Mu.<br/>Di sini kami menanti,<br/>kedatangan Putra-Mu;<br/>Tiada lain minat kami,<br/>memuji di depan-Mu.<br/>',NULL,60240,4);
INSERT INTO stanza VALUES('I44','1','Bapa, nama-Mu terpuji,<br/>karunia-Mu ajarkan;<br/>Girang karena hayat-Mu,<br/>bawa kami ke g''reja.<br/>',NULL,60241,1);
INSERT INTO stanza VALUES('I44','2','Kes''lamatan yang Kau beri,<br/>lampaui pujian kami;<br/>Hati kami hadap kini,<br/>ke takhta-Mu di langit.<br/>',NULL,60242,2);
INSERT INTO stanza VALUES('I44','3','Di sana Dia menjadi<br/>sandaran nan abadi;<br/>Orang dosa, hayat Kau b''ri,<br/>beban dosa tersingkir.<br/>',NULL,60243,3);
INSERT INTO stanza VALUES('I44','4','Alam kekal ''kan kisahkan,<br/>karunia-Mu berlimpah;<br/>Hingga anak-anak Allah,<br/>ucapkan t''rima kasih.<br/>',NULL,60244,4);
INSERT INTO stanza VALUES('I44','5','Walau belum tampak fajar,<br/>tetap maju berjalan;<br/>Hingga Dia jemput kita,<br/>lepas maut, kuburan.<br/>',NULL,60245,5);
INSERT INTO stanza VALUES('I44','6','Kami girang, kar''na Engkau<br/>bagian kekal kami;<br/>S''rupa Putra! Bersama-Nya!<br/>nikmat fajar nan cerah!<br/>',NULL,60246,6);
INSERT INTO stanza VALUES('I44','7','Mohon Bapa, demi Putra,<br/>menjaga kami ''tiasa.<br/>Tanpa cemas, tanpa kuatir,<br/>hingga capai tujuan.<br/>',NULL,60247,7);
INSERT INTO stanza VALUES('I45','1','Allah Bapa terpuji,<br/>girang di depan-Mu;<br/>Kekal lepas dari maut,<br/>bersama Putra-Mu.<br/>Engkau Anak Manusia,<br/>hidup dalam terang,<br/>Dalam kasih tak batas,<br/>nikmat kurnia s''lama.<br/>',NULL,60248,1);
INSERT INTO stanza VALUES('I45','2','Kau, Bapa, Allah Yesus,<br/>juga bagi kami,<br/>Anak yang Kau kasihi,<br/>juga buah hati.<br/>Bawa kami dekat-Mu,<br/>berbagian atas-Nya,<br/>Nikmat limpah kasih-Mu,<br/>dan sinar wajah-Mu.<br/>',NULL,60249,2);
INSERT INTO stanza VALUES('I45','3','Kasih-Mu memelukku,<br/>tak musnah s''lamanya;<br/>Sepenuhnya tercurah,<br/>atas diri Putra.<br/>Di dalam-Nya, putra-Mu -<br/>banyak saudara-Nya -<br/>Dengan-Nya nikmat kasih,<br/>pun terima kurnia.<br/>',NULL,60250,3);
INSERT INTO stanza VALUES('I46','1','Allah Bapa, besarlah kasih-Mu,<br/>kami nikmat;<br/>Kini kami, bebas hampiri-Mu,<br/>demi Putra.<br/>Sungguh ajaib,<br/>kami serupa Dia,<br/>Diperkenan,<br/>kekal tak berbeda.<br/>',NULL,60251,1);
INSERT INTO stanza VALUES('I46','2','Dia dikenan, kami di dalam-Nya,<br/>oleh kurnia;<br/>Dia sasaran kasih-Mu yang unik,<br/>ku berbagian.<br/>Nikmati kasih-Nya<br/>tiada batas,<br/>Mulia-Nya,<br/>depan-Mu tertampak.<br/>',NULL,60252,2);
INSERT INTO stanza VALUES('I46','3','Saat putra-putra-Mu menyanyi<br/>di depan-Mu;<br/>Dia yang pimpin, girang hati kami,<br/>memuji-Mu.<br/>Bapa, dalam rencana<br/>kasih-Mu,<br/>Kau-lah sumber,<br/>s''mua puji bagi-Mu.<br/>',NULL,60253,3);
INSERT INTO stanza VALUES('I47','1','Ya Bapa, kami datang,<br/>Putra-Mu yang pimpin,<br/>Bersembah dan bersyukur,<br/>nikmati kasih-Mu.<br/>Di takhta-Mu Kau girang,<br/>rencana-Mu genap,<br/>Kami jadi anak-Mu,<br/>kar''na Dia t''lah bangkit.<br/>',NULL,60254,1);
INSERT INTO stanza VALUES('I47','2','Hidangan roti, cawan,<br/>t''lah kami terima;<br/>Tanda ini ''nyatakan<br/>j''rih payah Putra-Mu.<br/>Tubuh-Nya t''lah terbelah,<br/>jadi jalan baru,<br/>Kami datang demi ''ni,<br/>sebut "Abba Bapa".<br/>',NULL,60255,2);
INSERT INTO stanza VALUES('I47','3','Darah indah-Nya ''ngalir,<br/>hapus nista dosa;<br/>Keadilan dan murka-Mu,<br/>tidak tuntut kami.<br/>Darah-Nya di depan-Mu,<br/>jadi saksi kami,<br/>Gugatan Iblis musnah,<br/>kami tidak gentar.<br/>',NULL,60256,3);
INSERT INTO stanza VALUES('I47','4','Manusia di depan-Mu,<br/>terbilang apakah?<br/>Kau cari ''pri mustika,<br/>dan damai d''ngan m''reka.<br/>M''laikat jatuh, Kau biarkan,<br/>manusia Kau tolong,<br/>Puji syukur pada-Mu,<br/>kurnia-Mu berlimpah.<br/>',NULL,60257,4);
INSERT INTO stanza VALUES('I48','1','Pesta berlalu, mesra tertinggal,<br/>Bapa, Putra-Mu, pimpin pujian;<br/>Memuji Bapa, sangatlah mesra,<br/>serasi dengan-Nya, puji s''rempak.<br/>',NULL,60258,1);
INSERT INTO stanza VALUES('I48','2','Bapa, selain Kau ku tak harap,<br/>ada apa yang lebih mustika?<br/>Kami menyembah, kar''na t''lah kecap,<br/>hayat-Mu limpah lezat, tak batas.<br/>',NULL,60259,2);
INSERT INTO stanza VALUES('I48','3','Dalam kasih-Mu, kasihku tumbuh,<br/>lampaui sanak, hubungan dunia;<br/>Dengan kuasa, kasih-Mu bimbingku,<br/>makin dalam nikmati hadir-Mu.<br/>',NULL,60260,3);
INSERT INTO stanza VALUES('I48','4','Bapa, kami ikuti Putra-Mu,<br/>pujian bagi-Mu, s''lama tak sudah;<br/>Kenyang nikmati kasih kudus-Mu,<br/>anak-Mu kecap limpah nama-Mu.<br/>',NULL,60261,4);
INSERT INTO stanza VALUES('I49','1','Bapa, kami sujud di depan-Mu, khidmat, tulus;<br/>Para anak-mu semua berhimpun, ''tuk berkidung:<br/>Kurnia ajaib bawa kami pulang,<br/>D''ngan Putra-Mu hampir pada Bapa!<br/>',NULL,60262,1);
INSERT INTO stanza VALUES('I49','2','Sungguh amatlah dalam kasih-Mu, tak terukur;<br/>Dari diri-Nya nyata kasih-Mu, pun terwujud!<br/>Kini di depan-Mu Dia memimpin,<br/>Kami semua bersama memuji.<br/>',NULL,60263,2);
INSERT INTO stanza VALUES('I49','3','Dia memimpin pujian yang merdu, yang Kau gemar;<br/>Hati-Mu pun mengasihi s''lalu, pengikut-Nya;<br/>Sebelum dunia diciptakan,<br/>Kau tetapkan, kamilah mitra-Nya.<br/>',NULL,60264,3);
INSERT INTO stanza VALUES('I50','1','Bapa, Allah, kasih-Mu ternyata,<br/>Depan-Mu pujian kami menggema.<br/>Dia-lah kurban, puaskan hati-Mu,<br/>Pikul salib, dapat perkenan-Mu.<br/>',NULL,60265,1);
INSERT INTO stanza VALUES('I50','2','Dia memimpin panjatkan pujian,<br/>Dengar pujian, hati beresonan.<br/>Saat Dia memimpin angkat suara,<br/>Dalam roh kami tanggap, pujilah.<br/>',NULL,60266,2);
INSERT INTO stanza VALUES('I50','3','Dalam Putra-Mu kami dipilih,<br/>Berbagian pujian di depan-Mu.<br/>Ditakdirkan seb''lum dunia jadi,<br/>Untuk berbagian hayat Putra-Mu.<br/>',NULL,60267,3);
INSERT INTO stanza VALUES('I50','4','Para putra, Roh-Mu perbarui,<br/>Putra-Mu-lah bagian kekal kami.<br/>Masing-masing berbagian unik,<br/>Dikau berkenan hingga abadi.<br/>',NULL,60268,4);
INSERT INTO stanza VALUES('I51','1','Kami berkidung, ya, Allah Bapa,<br/>hanya Engkau yang layak dipuja;<br/>Sembah dalam roh dan realitas,<br/>demikian baru Kau perkenan.<br/>',NULL,60269,1);
INSERT INTO stanza VALUES('I51','2','Melalui Putra, dunia Kau cipta<br/>juga ditopang oleh kuasa-Nya;<br/>Namun kami ada dalam Putra, dekat,<br/>akrab, mesra, Kau ku sembah.<br/>',NULL,60270,2);
INSERT INTO stanza VALUES('I51','3','Dia yang memimpin di alam berkat,<br/>dalam g''reja memuji serempak;<br/>Sungguh senang, bersama s''mua putra,<br/>sama leluasa, sama bergita.<br/>',NULL,60271,3);
INSERT INTO stanza VALUES('I51','4','Padu suara, ka-mi bersama Dia,<br/>agar Kau puas, apresiasikan;<br/>Di tengah pujian pimpinan Putra,<br/>Kau semayam, kekal nikmat pujian.<br/>',NULL,60272,4);
INSERT INTO stanza VALUES('I52','1','Sandar darah adi Juru-s''lamat,<br/>kami datang padaMu, ya Bapa,<br/>Jarak sirna, bebas oleh kurnia,<br/>kami datang sembahkan pujian.<br/>',NULL,60273,1);
INSERT INTO stanza VALUES('I52','2','Bapa, pada-Mu kami sembahkan,<br/>semerbak harum nama Sang Putra;<br/>Kurnia limpah oleh wafat-Nya,<br/>demi iman Dia kami tatap.<br/>',NULL,60274,2);
INSERT INTO stanza VALUES('I52','3','Bersama Dia, gemar-Mu ku nikmat,<br/>di dalam Dia, oleh-Mu ku girang;<br/>Dia utama, pula yang terindah,<br/>kemuliaan-Nya kekal tak pudar.<br/>',NULL,60275,3);
INSERT INTO stanza VALUES('I52','4','Depan takhta-Mu kami tengadah,<br/>demi iman nampak Yang Kau cinta;<br/>Kini Dia pimpin banyak saudara,<br/>pada-Mu s''rempak panjatkan pujian.<br/>',NULL,60276,4);
INSERT INTO stanza VALUES('I53','1','Tuhan Kau-lah firman hayat,<br/>yang bersama Allah;<br/>Kaulah kemuliaan Allah,<br/>ekspresikan Allah.<br/>',NULL,60277,1);
INSERT INTO stanza VALUES('I53','chorus','Puji, Kau-lah Firman hayat,<br/>ekspresikan Allah;<br/>Sifat, kemuliaan Allah,<br/>mutlak Kau tampilkan.<br/>',NULL,60278,2);
INSERT INTO stanza VALUES('I53','2','Langit kisah mulia Allah,<br/>s''mesta angkat suara;<br/>Lewat ciptaan ungkapkan,<br/>kuasa, sifat Allah.<br/>',NULL,60279,3);
INSERT INTO stanza VALUES('I53','3','Firman Allah ajaib, limpah,<br/>bersaksi bagi-Mu;<br/>Dalam firman, Kau ternyata,<br/>Allah pun terwahyu.<br/>',NULL,60280,4);
INSERT INTO stanza VALUES('I53','4','Firman hidup jadi daging,<br/>tinggal tengah insan;<br/>Semua sikap dan tindak-Mu,<br/>menampilkan Allah.<br/>',NULL,60281,5);
INSERT INTO stanza VALUES('I53','5','Firman hidup justru hayat,<br/>pula terang hayat;<br/>Hayat menyorotkan terang,<br/>Allah ternyatakan.<br/>',NULL,60282,6);
INSERT INTO stanza VALUES('I53','6','Penghakiman-Nya Kau emban,<br/>nyata adil Allah;<br/>Ini juga ekspresikan<br/>Allah sepenuhnya.<br/>',NULL,60283,7);
INSERT INTO stanza VALUES('I53','7','Engkaulah ekspresi Allah,<br/>menyatakan Allah;<br/>Kini Allah terwahyukan<br/>kepada manusia.<br/>',NULL,60284,8);
INSERT INTO stanza VALUES('I54','1','Tuhan, Kau-lah firman kekal,<br/>Putra Tunggal Allah,<br/>Yang tertampak dan terdengar,<br/>Sang Terkasih surga.<br/>Kau ilahi, Putra Allah,<br/>dalam-Mu s''mua limpah Allah.<br/>',NULL,60285,1);
INSERT INTO stanza VALUES('I54','2','Dalam-Mu nyata sempurna,<br/>kemuliaan Bapa,<br/>Mengandung keilahian,<br/>selama-lamanya.<br/>Kau ilahi, Putra Allah,<br/>dalam-Mu s''mua limpah Allah.<br/>',NULL,60286,2);
INSERT INTO stanza VALUES('I54','3','Gambar Allah yang tak batas,<br/>esens-Nya terpendam,<br/>Kau-lah terang non ciptaan,<br/>ungkap hati Allah.<br/>Kau ilahi, Putra Allah,<br/>dalam-Mu s''mua limpah Allah.<br/>',NULL,60287,3);
INSERT INTO stanza VALUES('I54','4','Tapi misteri nama-Mu,<br/>malaikat tak paham,<br/>Diri-Mu misteri juga,<br/>Allah saja paham.<br/>Kau ilahi, Putra Allah,<br/>dalam-Mu s''mua limpah Allah.<br/>',NULL,60288,4);
INSERT INTO stanza VALUES('I54','5','Dalam s''luruh jagat raya,<br/>diri-Mu pusatnya,<br/>Kekal panjatkan pujian,<br/>Sang Terkasih surga.<br/>Kau ilahi, Putra Allah,<br/>dalam-Mu s''mua limpah Allah.<br/>',NULL,60289,5);
INSERT INTO stanza VALUES('I55','1','Tuhan, Kau-lah Firman Allah,<br/>juga Putra Allah;<br/>Gambar Allah, riil, benar,<br/>penuh mulia Allah.<br/>',NULL,60290,1);
INSERT INTO stanza VALUES('I55','2','K''limpahan hakiki Allah,<br/>dalam-Mu semayam;<br/>Kau-lah penjelmaan Allah,<br/>ekspresikan Allah.<br/>',NULL,60291,2);
INSERT INTO stanza VALUES('I55','3','Mulia Allah Kau pancarkan,<br/>esa dengan Allah;<br/>Gambar Sebenarnya Allah,<br/>realitaskan Allah.<br/>',NULL,60292,3);
INSERT INTO stanza VALUES('I55','4','Dalam Dikau Allah ialah<br/>hayat terang kami;<br/>Dalam-Mu kami miliki,<br/>sifat yang ilahi.<br/>',NULL,60293,4);
INSERT INTO stanza VALUES('I55','5','Dalam-Mu kasih karunia,<br/>ku dapatkan Allah;<br/>Dalam-Mu ada realitas,<br/>ku melihat Allah.<br/>',NULL,60294,5);
INSERT INTO stanza VALUES('I55','6','Dalam-Mu kami terima,<br/>kepenuhan Allah;<br/>Dalam-Mu kami baurlah,<br/>esa dengan Allah.<br/>',NULL,60295,6);
INSERT INTO stanza VALUES('I55','7','Tuhan, Allah, kami sembah,<br/>pada-Mu s''galaku;<br/>Kau-lah mustika hatiku,<br/>hargai tak putus.<br/>',NULL,60296,7);
INSERT INTO stanza VALUES('I56','1','Tuhan Yesus, kami sembah,<br/>Kau-lah "benih perempuan";<br/>La-hir oleh gadis suci,<br/>esa Allah dan insan.<br/>Memiliki sifat insan,<br/>injak ular jahanam,<br/>Kau remukkan kepalanya,<br/>menang rencana Allah.<br/>',NULL,60297,1);
INSERT INTO stanza VALUES('I56','chorus','Mulia-Mu ku nampak,<br/>dalam bajik insan.<br/>Indah mulia sifat Allah<br/>nyata di insan.<br/>',NULL,60298,2);
INSERT INTO stanza VALUES('I56','2','Inkarnasi, jadi insan,<br/>kenakan darah, daging,<br/>Menghancurkan Iblis, Satan,<br/>jadi Pengganti kami.<br/>Nama "Yesus" Kau diberi,<br/>disebut "Imanuel",<br/>Jadi Jurus''lamat adi,<br/>g''nap kes''lamatan pasti.<br/>',NULL,60299,3);
INSERT INTO stanza VALUES('I56','3','Kau disebut "Adam akhir",<br/>"manusia kedua",<br/>Kepala ciptaan baru,<br/>lampaui yang pertama.<br/>Di atas bumi, hidup-Mu,<br/>Kau-lah insan sejati,<br/>Di surga kini ada-Mu,<br/>insan tetap tertampil.<br/>',NULL,60300,4);
INSERT INTO stanza VALUES('I56','4','Pada hari mulia itu,<br/>Tuhan, Kau ''kan kembali,<br/>Penuh kemuliaan Bapa,<br/>tampil atas insani.<br/>Pada takhta penghakiman,<br/>Insanlah yang hakimi,<br/>Kau ''kan bawa sifat insan,<br/>masuk kekal abadi.<br/>',NULL,60301,5);
INSERT INTO stanza VALUES('I57','1','Tuhan telah inkarnasi,<br/>berbagian sifat insani,<br/>Kenakan darah dan daging,<br/>lahir oleh dara suci.<br/>',NULL,60302,1);
INSERT INTO stanza VALUES('I57','2','Hampa diri pun menghamba,<br/>hidup di bumi derita,<br/>Kecap getir hidup insan,<br/>tanpa elak Kau tempuh s''mua.<br/>',NULL,60303,2);
INSERT INTO stanza VALUES('I57','3','Lahir bayi dalam palung,<br/>dibesarkan dalam papa,<br/>Lelah s''perti tukang kayu,<br/>wafat di-ang-gap penjahat.<br/>',NULL,60304,3);
INSERT INTO stanza VALUES('I57','4','Kau pun bangkit dari mati,<br/>tetap bawa insan ini,<br/>Kenakan corak ilahi,<br/>tetap insan, t''rangkat tinggi.<br/>',NULL,60305,4);
INSERT INTO stanza VALUES('I57','5','Kini daulat atas takhta,<br/>dalam mu-lia tetap insan.<br/>Dalam terang serta Allah,<br/>hati Allah di-pu-as-kan.<br/>',NULL,60306,5);
INSERT INTO stanza VALUES('I57','6','Penuh mu-lia Kau kembali,<br/>masih tampil dalam insan,<br/>Raja atas s''gala raja,<br/>tertampak sebagai insan.<br/>',NULL,60307,6);
INSERT INTO stanza VALUES('I57','7','K''lak di langit, bumi baru,<br/>jadi Pusat segalanya,<br/>Meski Kau Allah Sang Kudus,<br/>kekal tetap bawa insan.<br/>',NULL,60308,7);
INSERT INTO stanza VALUES('I58','1','O, Allahku, Sang Perahmat!<br/>Dosa m''rajalela,<br/>Adam akhir berperanglah,<br/>beri peny''lamatan.<br/>',NULL,60309,1);
INSERT INTO stanza VALUES('I58','2','O, Allahku, Sang Pengasih!<br/>Meski Adam gagal,<br/>Namun Dia sebagai insan,<br/>tempur ulang, jaya.<br/>',NULL,60310,2);
INSERT INTO stanza VALUES('I58','3','Lebih daripada kurnia,<br/>yakni tampil Allah,<br/>Hadir dan hakiki Allah,<br/>baur dalam insan.<br/>',NULL,60311,3);
INSERT INTO stanza VALUES('I58','4','O, Allahku, Sang Pemurah!<br/>Datang dalam insan,<br/>Bagi insan rela wafat;<br/>taklukkan maut, musuh.<br/>',NULL,60312,4);
INSERT INTO stanza VALUES('I58','5','Pencil meratap di taman,<br/>nyata salib wafat,<br/>Tak lain mengajar saudara,<br/>mati pun tak elak.<br/>',NULL,60313,5);
INSERT INTO stanza VALUES('I58','6','Tuhan, Kau Allah pun insan,<br/>dalam diri beta,<br/>S''mua karya-Mu sungguh ajaib,<br/>patut ku memuja!<br/>',NULL,60314,6);
INSERT INTO stanza VALUES('I59','1','Kisah nan mengharukan,<br/>tentang kurnia Allah,<br/>Bawakan wahyu mulia,<br/>t''rukir di wajah-Nya!<br/>Saat ku tatap Dia<br/>gambar terang Allah,<br/>Hati riang, melonjak,<br/>takjub, sujud sembah.<br/>',NULL,60315,1);
INSERT INTO stanza VALUES('I59','2','Sempurna insani-Mu,<br/>nyata ilahi-Mu,<br/>Kasih Allah, manusia<br/>- ilahi, insani.<br/>Mati, bangkit, dan t''rangkat,<br/>Kau Allah pun insan,<br/>Merendah di buana,<br/>almuhit di surga.<br/>',NULL,60316,2);
INSERT INTO stanza VALUES('I59','3','Mulia tak bercela,<br/>wajah nan cemerlang!<br/>Karya limpah tak batas,<br/>''ngubah demi kurnia.<br/>Tak lama kami s''rupa,<br/>celik kar''na cinta,<br/>Atas Anak Manusia,<br/>nampak wajah Allah.<br/>',NULL,60317,3);
INSERT INTO stanza VALUES('I60','1','Nama nan ku sayang,<br/>Yesus Tuhan!<br/>Terunggul dari s''mua,<br/>Yesus Tuhan!<br/>Kau serba segala,<br/>lain ku tak punya,<br/>Tak kurang tiasa,<br/>Yesus Tuhan!<br/>',NULL,60318,1);
INSERT INTO stanza VALUES('I60','2','Pernah jelma insan,<br/>Yesus Tuhan!<br/>Bagiku terpancang,<br/>Yesus Tuhan!<br/>Kasih-Mu teragung,<br/>lampaui siapa jua,<br/>Oleh-Mu selamat,<br/>Yesus Tuhan!<br/>',NULL,60319,2);
INSERT INTO stanza VALUES('I60','3','Kar''na Kau ku hidup,<br/>Yesus Tuhan!<br/>Sandar Kau ku menang,<br/>Yesus Tuhan!<br/>Apakah ku takut,<br/>cemas, Iblis, maut?<br/>Padaku hadir-Mu,<br/>Yesus Tuhan!<br/>',NULL,60320,3);
INSERT INTO stanza VALUES('I60','4','Jenak Kau ''kan tiba,<br/>Yesus Tuhan!<br/>Kita ''kan bersua,<br/>Yesus Tuhan!<br/>Berhadapan wajah,<br/>kami ''kan serupa,<br/>Kekal berdampingan,<br/>Yesus Tuhan!<br/>',NULL,60321,4);
INSERT INTO stanza VALUES('I61','1','Tuhan, nama-Mu "AKULAH",<br/>mulia, indah, riil, kaya,<br/>Apa saja yang ku perlu,<br/>ada pada-Mu!<br/>',NULL,60322,1);
INSERT INTO stanza VALUES('I61','2','Kau-lah Putra, Bapa kudus,<br/>rah''sia Allah, wujud Allah,<br/>Menjadi Roh, diam dalamku,<br/>limpah ku nikmat.<br/>',NULL,60323,2);
INSERT INTO stanza VALUES('I61','3','Kau-lah Kemah, Kau-lah Bait,<br/>tempat kediaman Allah,<br/>Di dalam-Mu, jumpa Allah,<br/>nikmat limpah-Nya.<br/>',NULL,60324,3);
INSERT INTO stanza VALUES('I61','4','Kau-lah Domba, Memp''lai laki,<br/>bagi kami tanggung dosa,<br/>Korban diri, menderita,<br/>ku b''roleh s''lamat.<br/>',NULL,60325,4);
INSERT INTO stanza VALUES('I61','5','Kau-lah hikmat, Kau-lah jalan,<br/>seturut-Nya menataku,<br/>Ku terima berkat, kurnia,<br/>berjalan lurus.<br/>',NULL,60326,5);
INSERT INTO stanza VALUES('I61','6','Kau-lah adil, Kau-lah kudus,<br/>sesuai dan dikenan Allah,<br/>Benarkanku, kuduskanku,<br/>damai d''ngan Allah.<br/>',NULL,60327,6);
INSERT INTO stanza VALUES('I61','7','Kau-lah hayat, Kau-lah terang,<br/>telan maut, usir gelap,<br/>Bangkitkanku, terangiku,<br/>agar ku bebas.<br/>',NULL,60328,7);
INSERT INTO stanza VALUES('I61','8','Kau-lah bangkit, Kau-lah kuasa,<br/>menaklukkan alam maut,<br/>Kuatkanku, menangkanku,<br/>hingga ku jaya.<br/>',NULL,60329,8);
INSERT INTO stanza VALUES('I61','9','Kau-lah pangan, air hidup,<br/>rela m''rendah, datang dunia,<br/>Lerai lapar, dah''ga,<br/>letih, jadi jamuanku.<br/>',NULL,60330,9);
INSERT INTO stanza VALUES('I61','10','Kau Gembala, Kau pun Tabib,<br/>korban nyawa, sembuhkanku,<br/>Rawat, asuh, hibur, jaga,<br/>penuh simpati.<br/>',NULL,60331,10);
INSERT INTO stanza VALUES('I61','11','Kau-lah Imam, Kau-lah Raja,<br/>membawaku depan Allah,<br/>Ku berbagian kuasa-Mu,<br/>sungguh terhormat!<br/>',NULL,60332,11);
INSERT INTO stanza VALUES('I61','12','Kau harapan, Kau penebus,<br/>menggarapku, mengubahku,<br/>Hingga aku serupa-Mu,<br/>ekspresikan-Mu.<br/>',NULL,60333,12);
INSERT INTO stanza VALUES('I61','13','Kau pun mulia, riang, damai,<br/>benar, kurnia, firman, karang,<br/>Surya, p''risai, rumah, gunung,<br/>tidak terkata!<br/>',NULL,60334,13);
INSERT INTO stanza VALUES('I61','14','Kekal, panjang, lebar, tinggi,<br/>dalam, limpah, pun sempurna!<br/>Memenuhi keperluanku!<br/>Luap dariku!<br/>',NULL,60335,14);
INSERT INTO stanza VALUES('I62','1','Nama-Mulah, ya Yesus,<br/>yang ku cinta dan sujud;<br/>Mulia, kuasa, pujian, hormat,<br/>bagi-Mu ku sembahkan;<br/>Suara pujian membubung,<br/>hati, mulut, berpadu;<br/>Yesus patut t''rima puji,<br/>cantik-Mu tak terperi!<br/>',NULL,60336,1);
INSERT INTO stanza VALUES('I62','2','Nama-Mulah, ya Yesus,<br/>yang memberikan wahyu;<br/>Kasih Allah sejak dulu<br/>tertuju pada aku;<br/>Aku orang yang keji,<br/>tapi Kau bersimpati;<br/>Kar''na kasih, ku Kau beli,<br/>jadi mustika adi.<br/>',NULL,60337,2);
INSERT INTO stanza VALUES('I62','3','Nama-Mulah, ya Yesus,<br/>yang selalu ku rindu;<br/>Kau terlahir dalam malaf,<br/>kar''na ku Kau merendah;<br/>Sengsaraku Kau tanggung,<br/>celakaku Kau pikul;<br/>Laknat dan kutuk Kau t''rima,<br/>kar''na kasih-Mu saja.<br/>',NULL,60338,3);
INSERT INTO stanza VALUES('I62','4','Nama-Mulah, ya Yesus,<br/>Anak Domba yang kudus;<br/>Darah-Mu cuci dosaku,<br/>hukumanku Kau pikul;<br/>Kini Kau t''lah bertakhta,<br/>pakai mahkota mulia;<br/>Kau t''lah menang, aku bebas.<br/>Haleluya s''lamanya.<br/>',NULL,60339,4);
INSERT INTO stanza VALUES('I63','1','Yesus, nama-Mu semerbak<br/>bagi orang s''lamat!<br/>Hatiku selalu ingat,<br/>Engkau manis sangat!<br/>',NULL,60340,1);
INSERT INTO stanza VALUES('I63','2','Yesus - Allah jadi insan,<br/>mencakup s''mua kurnia,<br/>Hayat surga, datang dunia,<br/>Engkaulah yang bawa!<br/>',NULL,60341,2);
INSERT INTO stanza VALUES('I63','3','Yesus nama-Mu ''nyatakan,<br/>d''rita kar''na cinta,<br/>Hingga surga bersimpati,<br/>padaku yang keji.<br/>',NULL,60342,3);
INSERT INTO stanza VALUES('I63','4','Tuhan, Kau pikul dosaku,<br/>biarku t''rima kurnia;<br/>Wafat-Mu pikat hatiku,<br/>pun b''rikan sentosa.<br/>',NULL,60343,4);
INSERT INTO stanza VALUES('I63','5','Ingat nama-Mu ku tunduk,<br/>hatiku bersujud;<br/>Ku tertolong, kar''na cinta,<br/>Kau unggul dari s''mua!<br/>',NULL,60344,5);
INSERT INTO stanza VALUES('I64','1','Ya, Tuhan, nama-Mu "Yesus",<br/>nama ajaib, indah,<br/>Kau lahir dari sang dara,<br/>kenakan rupa insan.<br/>Kau Yehova Penolongku,<br/>tolongku lepas dosa,<br/>Saat ku t''rima diri-Mu,<br/>hayat Allah ku dapat.<br/>',NULL,60345,1);
INSERT INTO stanza VALUES('I64','2','Kau disebut pula "Kristus",<br/>atas ministri mulia,<br/>Kau-lah Sang Terurap Allah,<br/>azali ditunjuk-Nya.<br/>Tuhan, Kau Mesias Allah,<br/>ditetapkan kasih-Nya,<br/>Agar ternyata mulia-Nya,<br/>rampungkan kehendak-Nya.<br/>',NULL,60346,2);
INSERT INTO stanza VALUES('I64','3','Kau disebut "Imanuel",<br/>"Allah beserta insan",<br/>berbaur dengan manusia,<br/>abadi tak terpisah.<br/>Allah nyata atas daging,<br/>penuh kurnia, realitas,<br/>Ku nampak mulia Allah,<br/>dapatkan kep''nuhan-Nya.<br/>',NULL,60347,3);
INSERT INTO stanza VALUES('I64','4','Nama-Mu mustika nian,<br/>wahyu limpah tak tara,<br/>Nama-Mu berharga, indah,<br/>ku pegang hingga kekal.<br/>Jurus''lamat, Kristus mulia,<br/>bagi-Mu sujud, sembah,<br/>Tuhan sayang, Imanuel,<br/>ku junjung hingga kekal.<br/>',NULL,60348,4);
INSERT INTO stanza VALUES('I65','1','Yesus, nama agung, mulia,<br/>andalan, sandaranku,<br/>"Duduk surga" kami puji,<br/>nama-Mu-lah menangku.<br/>',NULL,60349,1);
INSERT INTO stanza VALUES('I65','2','Yesus sayang! P''nolong kuat,<br/>nama-Mu-lah ku perlu,<br/>Asal hirup nama Yesus,<br/>air hayat ku minum.<br/>',NULL,60350,2);
INSERT INTO stanza VALUES('I65','3','Yesus, nama mulia, kuasa,<br/>langit, bumi siarkan,<br/>Orang dosa yang terampun,<br/>kenal khasiat nama-Nya.<br/>',NULL,60351,3);
INSERT INTO stanza VALUES('I65','4','Yesus, Yesus, nama indah,<br/>sembuhkan dan kuatkan,<br/>Hidup, perang di dalamnya,<br/>dapat riang dan mulia.<br/>',NULL,60352,4);
INSERT INTO stanza VALUES('I66','1','Yesus, nama ini indah,<br/>hibur hati duka,<br/>Hatiku riang, mulutku<br/>memasyhurkan nama-Mu.<br/>',NULL,60353,1);
INSERT INTO stanza VALUES('I66','chorus','Ajaib, indah, Putra Allah,<br/>Juru-selamatku;<br/>Turun dunia, mati, dan ber-<br/>darah menebusku.<br/>',NULL,60354,2);
INSERT INTO stanza VALUES('I66','2','Yesus, perwujudan Allah,<br/>jadi Anak Insan,<br/>Ku jadi ahli waris-Nya,<br/>kar''na Ia menghamba.<br/>',NULL,60355,3);
INSERT INTO stanza VALUES('I66','3','Yesus Hayat, juga Terang,<br/>Jalan, Kebenaran;<br/>Dalam hatiku meraja,<br/>pimpinku sentosa.<br/>',NULL,60356,4);
INSERT INTO stanza VALUES('I66','4','Yesus Jurus''lamat indah,<br/>memuaskan hatiku;<br/>Lenyapkan duka nestapa,<br/>dan sertaku s''lalu.<br/>',NULL,60357,5);
INSERT INTO stanza VALUES('I66','5','Jurus''lamatku s''gra datang,<br/>menyambutku pulang;<br/>Tubuh b''rubah, mulia p''ri<br/>Dia, s''lamanya sejaht''ra.<br/>',NULL,60358,6);
INSERT INTO stanza VALUES('I67','1','Tiada nama kian mesra,<br/>di langit ''tau di buana!<br/>Dia datang tinggalkan mulia,<br/>jadi Juru-selamat.<br/>',NULL,60359,1);
INSERT INTO stanza VALUES('I67','chorus','Kami junjung Anak Allah,<br/>memuji Kristus Yesus;<br/>Karena tiada lain abjad,<br/>indah, merdu, p''ri Yesus.<br/>',NULL,60360,2);
INSERT INTO stanza VALUES('I67','2','Sewaktu Dia disalibkan,<br/>nama-Nya pun sertalah;<br/>Agar s''mua menikmati-Nya,<br/>kar''nanya ku cinta Dia.<br/>',NULL,60361,3);
INSERT INTO stanza VALUES('I67','3','Tatkala Ia naik takhta,<br/>nama ini dib''rikan,<br/>S''mua berlutut dan bergita,<br/>alam s''mesta bersorak!<br/>',NULL,60362,4);
INSERT INTO stanza VALUES('I67','4','Demi nama yang tak terp''ri,<br/>kurnia takkan berkurang;<br/>Hari-hari Kau tak ubah,<br/>tetap hingga s''lamanya!<br/>',NULL,60363,5);
INSERT INTO stanza VALUES('I68','1','Yesus Kristus, Domba Allah,<br/>t''lah terjunjung tinggi;<br/>Juru-s''lamat orang dosa,<br/>patut t''rima puji.<br/>',NULL,60364,1);
INSERT INTO stanza VALUES('I68','chorus','Puji nama-Nya! Puji nama-Nya!<br/>Hormat, mulia, nama Tuhan;<br/>Haleluya! Haleluya!<br/>Hormat, mulia, nama Tuhan;<br/>Haleluya! Haleluya!<br/>Hormat, mulia, nama Tuhan;<br/>',NULL,60365,2);
INSERT INTO stanza VALUES('I68','2','Nama Yesus yang termulia,<br/>dib''rikan pada-Nya;<br/>S''mua malaikat dan manusia<br/>menyebut-Nya Tuhan.<br/>',NULL,60366,3);
INSERT INTO stanza VALUES('I68','3','Para saleh dan malaikat,<br/>datanglah bersembah;<br/>Hormat, mulia, bagi Kristus,<br/>pujilah Domba t''rus.<br/>',NULL,60367,4);
INSERT INTO stanza VALUES('I68','4','Orang dosa yang tertebus,<br/>puji Juru-s''lamat;<br/>Dia berdarah, cuci dosa,<br/>biar ku s''lalu bah''gia.<br/>',NULL,60368,5);
INSERT INTO stanza VALUES('I68','5','Biarlah kuasa, hikmat, kaya,<br/>hormat, mulia, pujian;<br/>Bagi Yesus, Anak Domba,<br/>selama-lamanya!<br/>',NULL,60369,6);
INSERT INTO stanza VALUES('I69','1','Nama Yesus lampaui s''mua,<br/>langit, bumi, barzakh,<br/>M''laikat, insan, s''mua menghormat,<br/>Iblis tunggang langgang.<br/>',NULL,60370,1);
INSERT INTO stanza VALUES('I69','2','Nama Yesus, manis, mesra,<br/>bagi orang dosa,<br/>Usir takut, dan hukuman,<br/>bawa damai surga.<br/>',NULL,60371,2);
INSERT INTO stanza VALUES('I69','3','Dia hancurkan b''lenggu dosa,<br/>dan kepala Satan;<br/>Kuasa-Nya telan lemah,<br/>hayat-Nya s''lamatkan.<br/>',NULL,60372,3);
INSERT INTO stanza VALUES('I69','4','Moga orang dunia ''ngecap<br/>limpah karunia-Nya!<br/>Menikmati ribaan-Nya,<br/>dalam pelukan-Nya.<br/>',NULL,60373,4);
INSERT INTO stanza VALUES('I69','5','Nama Yesus kekal handal<br/>dalam kehidupan;<br/>Kekal manis dan mustika,<br/>saksiku s''lamanya.<br/>',NULL,60374,5);
INSERT INTO stanza VALUES('I70','1','Nama Yesus amat manis,<br/>bagai musik, ku s''nang nyanyi,<br/>sukacitaku pun penuh,<br/>mustika nama Yesus.<br/>',NULL,60375,1);
INSERT INTO stanza VALUES('I70','chorus','Yesus! Nama yang manis,<br/>Yesus! Tetap tiap hari;<br/>Yesus! Saleh nyanyikan<br/>nilai-Nya sampai kekal.<br/>',NULL,60376,2);
INSERT INTO stanza VALUES('I70','2','Ku cinta nama Pengasih,<br/>Dia tahu, tanggung lemahku,<br/>Lenyapkan takut, cemasku,<br/>ku cinta nama Yesus.<br/>',NULL,60377,3);
INSERT INTO stanza VALUES('I70','3','Ku s''nang dengar nama ini,<br/>yang s''lalu barakan hati,<br/>Olehnya air mata hapus,<br/>tinggikan nama Yesus.<br/>',NULL,60378,4);
INSERT INTO stanza VALUES('I70','4','Tiada kata manusia dapat<br/>kisahkan manis-Nya,<br/>Puji nama-Nya tak putus,<br/>pujilah nama Yesus.<br/>',NULL,60379,5);
INSERT INTO stanza VALUES('I71','1','Tuhan bangkit dari maut,<br/>jadi buah sulung;<br/>Kami nampak Kau t''rangkat,<br/>jadi Kristus, k''pala.<br/>Kurnia, sekutu d''ngan-Mu,<br/>lenyap bimbang ragu,<br/>Kenang akan mulia-Mu,<br/>bersatu dengan-Mu.<br/>',NULL,60380,1);
INSERT INTO stanza VALUES('I71','2','Kepala atas s''gala,<br/>terbesar kuasa-Mu,<br/>"Insan" di kanan Bapa,<br/>teragung nama-Mu!<br/>Puncak kuasa dan cinta,<br/>Golgota paparkan;<br/>Kasih-Mu menang mutlak,<br/>''tas d''rita terganas.<br/>',NULL,60381,2);
INSERT INTO stanza VALUES('I71','3','Alam s''mesta serempak,<br/>memuji nama-Mu,<br/>S''mua mulut pun mengaku,<br/>menyambut hadir-Mu.<br/>Kini hanyalah kami,<br/>yang kenal kasih-Mu;<br/>Nikmat kasih di kalbu,<br/>bersyukur tak putus.<br/>',NULL,60382,3);
INSERT INTO stanza VALUES('I71','4','Nama-Mu paling tenar,<br/>kurnia-Mu terbesar,<br/>Kasih-Mu paling tinggi,<br/>kekal tak bersudah.<br/>Girang, kami memuja,<br/>kar''na kita esa;<br/>Mulia-Mu selamanya,<br/>kasih-Mu pun kekal.<br/>',NULL,60383,4);
INSERT INTO stanza VALUES('I72','1','Kau ada sejak dulu,<br/>sebelum ada waktu!<br/>Kar''na Kau Bapa kekal,<br/>swaada, kekal ada!<br/>',NULL,60384,1);
INSERT INTO stanza VALUES('I72','2','Lahir di tengah insan,<br/>namun kekal serta-Nya!<br/>Sempurna sep''ri Allah,<br/>pula tidak terbatas!<br/>',NULL,60385,2);
INSERT INTO stanza VALUES('I72','3','Satu sumber d''ngan Allah,<br/>lampaui segalanya!<br/>Tiada yang lebih awal,<br/>tiada yang lebih depan!<br/>',NULL,60386,3);
INSERT INTO stanza VALUES('I72','4','Tak ubah pun tak usang,<br/>tahun-Mu tak bersudah!<br/>Tiada yang lebih purba,<br/>tiada yang lebih b''lakang!<br/>',NULL,60387,4);
INSERT INTO stanza VALUES('I72','5','Tiada beda d''ngan Allah,<br/>sama persislah Allah!<br/>Engkau adalah Alfa,<br/>Engkau pula Omega!<br/>',NULL,60388,5);
INSERT INTO stanza VALUES('I72','6','Kami puji kekal-Mu,<br/>pun kesempurnaan-Mu!<br/>Engkau sangat berlimpah,<br/>ajaib, tak terbatas!<br/>',NULL,60389,6);
INSERT INTO stanza VALUES('I73','1','Tuhan, t''rimalah pujian,<br/>meski lemah suaraku;<br/>Kurnia-Mu aku masyhurkan,<br/>Tuhan Juru-s''lamatku.<br/>',NULL,60390,1);
INSERT INTO stanza VALUES('I73','2','Mulia, kaya, Kau tinggalkan,<br/>umat-Mu t''rima berkat;<br/>Diri-Mu Kau biarkan papa,<br/>kami jadilah kaya.<br/>',NULL,60391,2);
INSERT INTO stanza VALUES('I73','3','Kau tak jemu akan surga,<br/>dunia pun Kau tak suka.<br/>Mengapa tinggalkan surga,<br/>datang dunia, sengsara?<br/>',NULL,60392,3);
INSERT INTO stanza VALUES('I73','4','Di surga, Kau mulia, hormat,<br/>di dunia Kau terhina!<br/>Kau tahu akan disesah,<br/>kar''na cinta Kau rela.<br/>',NULL,60393,4);
INSERT INTO stanza VALUES('I73','5','Jika ku ingat budi-Mu,<br/>girang bercampur malu;<br/>Girang, Dikau penuh cinta;<br/>malu, kar''na sikapku.<br/>',NULL,60394,5);
INSERT INTO stanza VALUES('I73','6','Moga harinya s''gra tiba,<br/>ku lepas dari aral;<br/>Masuk ke dalam mulia,<br/>''layani Kau semata.<br/>',NULL,60395,6);
INSERT INTO stanza VALUES('I73','7','Kini di sini menunggu,<br/>gairah, penuh harapan;<br/>Tuhan, hidupku bagi-Mu,<br/>sampai saat berjumpa.<br/>',NULL,60396,7);
INSERT INTO stanza VALUES('I74','1','Dengar, m''laikat memuji,<br/>"Juru-s''lamat t''lah lahir!<br/>Mulia bagi Allah,<br/>sejahtera di bumi."<br/>Bangkitlah, hai s''mua bangsa!<br/>Ikutlah pujian surga!<br/>Semua memproklamirkan,<br/>Dia lahir di Betlehem.<br/>Semua memproklamirkan,<br/>Dia lahir di Betlehem.<br/>',NULL,60397,1);
INSERT INTO stanza VALUES('I74','2','Kristuslah, gambar Allah,<br/>cahaya mulia Allah;<br/>Dalam waktu, Dia datang,<br/>lahir dari sang dara.<br/>Kenakan tubuh daging,<br/>Allah berinkarnasi,<br/>Tinggal di tengah insan,<br/>Yesus-lah Imanuel.<br/>Tinggal di tengah insan,<br/>Yesus-lah Imanuel.<br/>',NULL,60398,2);
INSERT INTO stanza VALUES('I74','3','Mulia, Sang Raja Damai!<br/>Dia Surya Kebenaran!<br/>Beri terang dan hayat,<br/>bangkit, maut tertelan.<br/>Dia tinggalkan mulia-Nya,<br/>jadi Juru-selamat,<br/>Mati, bangkit, naik surga,<br/>lahir ulangkan insan.<br/>Mati, bangkit, naik surga,<br/>lahir ulangkan insan.<br/>',NULL,60399,3);
INSERT INTO stanza VALUES('I74','4','Dambaan semua bangsa,<br/>dalam kami Kau tinggal;<br/>Benih dara t''lah menang,<br/>hancurkan k''pala ular;<br/>Adam lama terhapus,<br/>rupa Kristus terwujud;<br/>K''limpahan "Adam akhir",<br/>ubahku serupa Dia.<br/>K''limpahan "Adam akhir",<br/>ubahku serupa Dia.<br/>',NULL,60400,4);
INSERT INTO stanza VALUES('I75','1','Kisah nan kekal,<br/>Allah datang dunia,<br/>Jadi Juru-s''lamat,<br/>Yesus-lah nama-Nya.<br/>Lahir di malaf,<br/>p''ri tunas di padang,<br/>D''rita sengsara senantiasa.<br/>',NULL,60401,1);
INSERT INTO stanza VALUES('I75','chorus','Ku cinta Dia!<br/>Kusembah Dia!<br/>Nafas, terangku,<br/>segalaku.<br/>Sang Khalik agung,<br/>jadi Penolong;<br/>Takkanlah asat,<br/>limpah Allah.<br/>',NULL,60402,2);
INSERT INTO stanza VALUES('I75','2','Menolong aku,<br/>rendahkan diri-Nya;<br/>Yang di lembah maut,<br/>temui harapan.<br/>Lembut penyayang,<br/>tinggalkan mulia-Nya;<br/>D''rita susah bagi kaum binasa.<br/>',NULL,60403,3);
INSERT INTO stanza VALUES('I75','3','Tiada paksaan,<br/>mengenakan daging;<br/>Dalam rupa insan,<br/>rencana Allah g''nap.<br/>Ajaib, mulia,<br/>esa dengan insan,<br/>S''gala milik-Nya aku nikmati.<br/>',NULL,60404,4);
INSERT INTO stanza VALUES('I76','1','Sungguh indah pekerti-Mu,<br/>elok, kudus, lemah lembut!<br/>Dalam jalan yang Kau tempuh,<br/>penuh kasih, ajaib sungguh.<br/>',NULL,60405,1);
INSERT INTO stanza VALUES('I76','2','Putra Insan, mahaterang,<br/>siapa p''ri Kau jernih, terang?<br/>Siapa p''ri Kau ramah sabar,<br/>tempuh hidup penuh d''rita?<br/>',NULL,60406,2);
INSERT INTO stanza VALUES('I76','3','Dicerca tak balik maki,<br/>disiksa tak sakit hati;<br/>Sungguh m''rendah, sungguh<br/>baik, lemah lembut, mulia bajik.<br/>',NULL,60407,3);
INSERT INTO stanza VALUES('I76','4','Agar tawanan terorak,<br/>Kau rela tanggung hukuman,<br/>Kasih-Mu ternyata jelas,<br/>darah curah, rahmat datang.<br/>',NULL,60408,4);
INSERT INTO stanza VALUES('I76','5','Tuhan ajaib, ku berharap,<br/>makin serupa dengan-Mu,<br/>Teladani Kau yang m''rendah,<br/>ikut jejak-Mu selalu.<br/>',NULL,60409,5);
INSERT INTO stanza VALUES('I77','1','Kaulah Allah tinggi, mulia,<br/>inkarnasi, datang dunia,<br/>Jadi insan yang merendah,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60410,1);
INSERT INTO stanza VALUES('I77','2','Mulia Allah Kau tinggalkan,<br/>tubuh daging Kau kenakan,<br/>Tanpa semarak di luar,<br/>Tuhan Kau ku kenang.<br/>',NULL,60411,2);
INSERT INTO stanza VALUES('I77','3','Bagai akar yang di gurun,<br/>alami d''rita, sengsara,<br/>Dibenci, dihina orang,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60412,3);
INSERT INTO stanza VALUES('I77','4','Hati-Mu ramah, merendah,<br/>rela t''rima s''mua p''ristiwa,<br/>Tak sungut pada siapa jua,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60413,4);
INSERT INTO stanza VALUES('I77','5','Insani-Mu manis, lembut,<br/>imbang dalam segala hal,<br/>Seolah kurban sajian,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60414,5);
INSERT INTO stanza VALUES('I77','6','Murad Allah, perhatian-Mu,<br/>tolak semua dusta Satan,<br/>Tiada yang setia p''ri-Mu,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60415,6);
INSERT INTO stanza VALUES('I77','7','Taat pada murad Allah,<br/>hingga mati pun Kau rela,<br/>Atas salib, Dikau wafat,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60416,7);
INSERT INTO stanza VALUES('I77','8','Dikau ditinggikan Allah,<br/>hormat, mulia Kau dapat,<br/>Langit, bumi, sujud, sembah,<br/>Tuhan, Kau ku kenang.<br/>',NULL,60417,8);
INSERT INTO stanza VALUES('I78','1','Waktu Engkau di dunia,<br/>sungguh elok, bajik,<br/>Insani-Mu luar biasa,<br/>''ngundang apresiasi.<br/>',NULL,60418,1);
INSERT INTO stanza VALUES('I78','2','Dalam sengsara tertampak<br/>kasih-Mu nan sabar,<br/>Tak peduli ajal ''nimpa,<br/>kasih-Mu tak tara.<br/>',NULL,60419,2);
INSERT INTO stanza VALUES('I78','3','Luka hati, ''nanggung beban,<br/>derita berlipat,<br/>Namun Kau tetap membungkam,<br/>sungut tak Kau ucap.<br/>',NULL,60420,3);
INSERT INTO stanza VALUES('I78','4','Musuh benci, sirik, maki,<br/>murid-Mu khianat,<br/>Kau malah berlapang dada,<br/>p''nuh kasih, ampunan.<br/>',NULL,60421,4);
INSERT INTO stanza VALUES('I78','5','Tuhan, hidup-Mu di bumi,<br/>p''ri kurban sajian,<br/>Lembut, harum, ''purna, s''rasi,<br/>Allah, insan, suka.<br/>',NULL,60422,5);
INSERT INTO stanza VALUES('I79','1','Tuhan, tatkala teringat,<br/>jalan-Mu di dunia;<br/>Curah kasih t''radap semua,<br/>setia t''radap Allah.<br/>',NULL,60423,1);
INSERT INTO stanza VALUES('I79','2','Meski kasih-Mu ditolak,<br/>tapi tetap saja;<br/>Darah dan air t''lah tercurah,<br/>cuci semua nista.<br/>',NULL,60424,2);
INSERT INTO stanza VALUES('I79','3','Meski susah, Engkau tetap<br/>amalkan kebaikan;<br/>Meski jalan penuh d''rita,<br/>Engkau tak berkesah.<br/>',NULL,60425,3);
INSERT INTO stanza VALUES('I79','4','Semua khianat, Kau setia,<br/>semua g''lap, Kau terang;<br/>Hati Bapa Kau indahkan,<br/>tak pernah menyanggah.<br/>',NULL,60426,4);
INSERT INTO stanza VALUES('I79','5','Muslihat Iblis tak mempan,<br/>sengsara tak daya;<br/>Sebatang kara di dunia,<br/>tegap hingga wafat.<br/>',NULL,60427,5);
INSERT INTO stanza VALUES('I79','6','Kau merendah, aku heran,<br/>ku ingin ''kan s''rupa;<br/>Sikap-Mu s''lalu ku taulad,<br/>kar''na p''nuh sentosa.<br/>',NULL,60428,6);
INSERT INTO stanza VALUES('I80','1','Ku sembahlah Raja hidup,<br/>bagi-Mu s''mua mulia;<br/>Ku lupakah ''kan bilur-Mu?<br/>Pimpin ke Golgota.<br/>',NULL,60429,1);
INSERT INTO stanza VALUES('I80','chorus','Ku lupakah Getsemani?<br/>Tak ta''ukah hati-Mu g''lisah?<br/>Lupakah kasih-Mu tinggi?<br/>Pimpin ke Golgota.<br/>',NULL,60430,2);
INSERT INTO stanza VALUES('I80','2','Di manakah Kau dikubur,<br/>biar ku dapat ziarah;<br/>Di manakah m''laikat jaga?<br/>Waktu Kau tertidur.<br/>',NULL,60431,3);
INSERT INTO stanza VALUES('I80','3','Kini ku mau tiru Maria,<br/>pada-Mu bersembah;<br/>Dapatkan kubur yang hampa,<br/>pimpin ke Golgota.<br/>',NULL,60432,4);
INSERT INTO stanza VALUES('I80','4','Ku persembahkan hidupku,<br/>pikul salib buat-Mu;<br/>Cawan pahit ku mau minum,<br/>sep''ri Kau bagiku.<br/>',NULL,60433,5);
INSERT INTO stanza VALUES('I80','5','Kau mau tolong semua orang,<br/>biar ku pun begitu;<br/>Mohon Kau basuh mulutku,<br/>kisahkan Golgota.<br/>',NULL,60434,6);
INSERT INTO stanza VALUES('I81','1','Yesus! Sumber hayat kekal!<br/>Yesus! Sang awal nafas!<br/>Lewat wafat dan terhina,<br/>kalahkan alam gelap.<br/>Melalui kesusahan,<br/>memberi keselamatan,<br/>Laksaan suara pujian,<br/>mulia bagi Tuhan!<br/>Laksaan suara pujian,<br/>mulia bagi Tuhan!<br/>',NULL,60435,1);
INSERT INTO stanza VALUES('I81','2','Putra Allah menderita,<br/>ejekan, benci, maki!<br/>Raja mulia tanggung dosa,<br/>pakai mahkota duri;<br/>Wafat demi meny''lamatkan,<br/>rantai dosa lucut hempas;<br/>Laksaan suara pujian,<br/>bagi Juruselamat!<br/>Laksaan suara pujian,<br/>bagi Juruselamat!<br/>',NULL,60436,2);
INSERT INTO stanza VALUES('I81','3','Semua hina dan cercaan,<br/>diam bungkam Kau t''rima;<br/>Bahkan t''rima d''rita maut,<br/>genapkan penebusan.<br/>Merendah-Mu menakjubkan,<br/>datang dunia, pikul dosa;<br/>Laksaan suara pujian,<br/>bagi Juruselamat!<br/>Laksaan suara pujian,<br/>bagi Juruselamat!<br/>',NULL,60437,3);
INSERT INTO stanza VALUES('I81','4','Kar''na Engkau t''lah merendah,<br/>Kau mati, ku pun hidup;<br/>Hati, rohku bangkit seg''ra,<br/>pada-Mu sembah syukur.<br/>Semua susah Engkau tanggung,<br/>semua berkat kami nikmat.<br/>Inilah nyanyianku,<br/>memuji hingga kekal.<br/>Inilah nyanyianku,<br/>memuji hingga kekal.<br/>',NULL,60438,4);
INSERT INTO stanza VALUES('I82','1','Kepala penuh luka,<br/>nyeri sengat tulang;<br/>Dihina dengan keji,<br/>bermahkota duri.<br/>Tapi kini terima<br/>mulia dan pujian;<br/>Kasi''an, dulu dibunuh,<br/>di salib Golgota.<br/>',NULL,60439,1);
INSERT INTO stanza VALUES('I82','2','Wajah-Mu yang cemerlang,<br/>sep''ri surya terang;<br/>Bapa nampak berkenan,<br/>kar''na Kau berkorban.<br/>Tuhan, s''mua yang Kau d''rita,<br/>bagiku yang dosa;<br/>Hutangku Kau lunaskan,<br/>tapi Kau ditentang.<br/>',NULL,60440,2);
INSERT INTO stanza VALUES('I82','3','Betapa sengsara-Mu,<br/>meskipun Kau kudus;<br/>Hatiku penuh syukur,<br/>mulut pun berkidung!<br/>Kini ingat salib-Mu,<br/>di mana Kau mati;<br/>Korban jiwa nan suci,<br/>Kau tak bilang rugi.<br/>',NULL,60441,3);
INSERT INTO stanza VALUES('I82','4','Juruselamat kami,<br/>Kaulah teman s''jati;<br/>Saat darah teralir,<br/>siapa yang simpati?<br/>Biarlah ku sejak kini,<br/>ingat Kau tiap hari;<br/>Di tempat mulia nanti,<br/>bers''kutu abadi.<br/>',NULL,60442,4);
INSERT INTO stanza VALUES('I83','1','Malam larut, Bukit Zaitun,<br/>bintang pudar, redup sinar;<br/>Getsemani, sunyi senyap,<br/>Juru-s''lamat sujud doa.<br/>',NULL,60443,1);
INSERT INTO stanza VALUES('I83','2','Malam larut, sendirian,<br/>Juru-s''lamat, doa, susah;<br/>Murid-murid lesu, lena,<br/>tak peduli Tuhan duka.<br/>',NULL,60444,2);
INSERT INTO stanza VALUES('I83','3','Malam larut, duka amat,<br/>tetes peluh bagai darah;<br/>Malak datang, tunjang t''naga,<br/>tak ditinggal oleh Allah.<br/>',NULL,60445,3);
INSERT INTO stanza VALUES('I83','4','Malam larut, usai doa,<br/>cawan pahit, rela t''rima;<br/>Asal rampung murad Allah,<br/>bagi insan, korban jiwa.<br/>',NULL,60446,4);
INSERT INTO stanza VALUES('I84','1','O, Tuhan, berat beban-Mu,<br/>dosaku tekan-Mu!<br/>Pijak di pihak yang dosa,<br/>menanggung dosaku.<br/>Jadi korban, basuh dosa,<br/>bebaskan diriku.<br/>',NULL,60447,1);
INSERT INTO stanza VALUES('I84','2','Cawanku p''nuh kutuk, maut,<br/>itu bagianku,<br/>Namun tiap tetes getirnya,<br/>Kau minum bagiku.<br/>Cawan pahit t''lah Kau minum,<br/>cawan berkat ''tukku.<br/>',NULL,60448,2);
INSERT INTO stanza VALUES('I84','3','Allah mengangkat tongkat-Nya,<br/>memukul diri-Mu!<br/>Kau disesah, pun terluka,<br/>ku bebas hukuman;<br/>Darah adi bercucuran,<br/>tebusan pun lunas.<br/>',NULL,60449,3);
INSERT INTO stanza VALUES('I84','4','Ombak badai menggelora,<br/>padamu menerjang!<br/>Lapang dada Kau menanggung,<br/>teduhkan hatiku.<br/>Bagiku Kau mati, d''rita,<br/>''jahtera ku dapat.<br/>',NULL,60450,4);
INSERT INTO stanza VALUES('I84','5','Allah menghunus pedang-Nya,<br/>menikam diri-Mu!<br/>Nyala api berputaran,<br/>darah-Mu tercurah.<br/>Tuntutan Allah terjawab,<br/>gugatan pun sirna.<br/>',NULL,60451,5);
INSERT INTO stanza VALUES('I84','6','Bagiku Yesus t''lah mati,<br/>ku mati dalam-Mu;<br/>Kau bangkit, bebaskan aku,<br/>dan hidup dalamku.<br/>Dimurnikan dan diuji,<br/>masuk mulia-Mu.<br/>',NULL,60452,6);
INSERT INTO stanza VALUES('I85','1','Setiap ingat pada salib,<br/>di mana Tuhan t''lah mati;<br/>Hatiku pun sg''ra menangis,<br/>hilang rasa tinggi diri.<br/>',NULL,60453,1);
INSERT INTO stanza VALUES('I85','2','Tiada lain yang ku megahkan,<br/>kecualilah salib Kristus;<br/>Apa yang ku sayang dulu,<br/>ku buang s''mua kar''na darah-Nya.<br/>',NULL,60454,2);
INSERT INTO stanza VALUES('I85','3','Tangan, kaki, dan kepala,<br/>berlumur darah dan cinta;<br/>Penuh kasih, k''pala nyeri,<br/>tertusuk mahkota duri.<br/>',NULL,60455,3);
INSERT INTO stanza VALUES('I85','4','Kujur tubuh penuh darah,<br/>se-p''ri pakai jubah merah!<br/>Kini ku putus d''ngan dunia,<br/>dunia pun mati bagiku.<br/>',NULL,60456,4);
INSERT INTO stanza VALUES('I85','5','Andai jagat s''mua milikku,<br/>tersembah Tuhan b''lum cukup;<br/>Kar''na ajaiblah kasih-Nya,<br/>Dia patut dapatkan s''gala.<br/>',NULL,60457,5);
INSERT INTO stanza VALUES('I86','1','Runduk, rendah, bentak, depak,<br/>pikul salib ke depan;<br/>P''ri domba ke pembantaian,<br/>Diam, bisu, tak elak.<br/>',NULL,60458,1);
INSERT INTO stanza VALUES('I86','chorus','O,Tuhan, Kaulah Sang Benar,<br/>bagiku menderita!<br/>Kasih-Mu tidak terduga,<br/>bagi-Mu hidup beta.<br/>',NULL,60459,2);
INSERT INTO stanza VALUES('I86','2','Tajuk duri, siksa amat,<br/>tangan , kaki terpaku;<br/>Bapa pergi, musuh garang,<br/>melanda roh dan raga.<br/>',NULL,60460,3);
INSERT INTO stanza VALUES('I86','3','Turun palang Kau tak hendak,<br/>malak tolong pun tidak;<br/>Kau dikeji dan dilindas,<br/>puaskan tuntutan Allah.<br/>',NULL,60461,4);
INSERT INTO stanza VALUES('I86','4','Tak tahan surya memandang,<br/>Domba Allah terpancang;<br/>Tirai koyak, jalan buka,<br/>berani hampir Allah.<br/>',NULL,60462,5);
INSERT INTO stanza VALUES('I87','1','Tuhan ku hargai jalan-Mu,<br/>yang p''nuh d''rita dan c''laka;<br/>Kematian-Mu menger-kan,<br/>kian nyatalah cinta-Mu.<br/>',NULL,60463,1);
INSERT INTO stanza VALUES('I87','chorus','Puji Tuhan! Puji Tuhan!<br/>Kau mati buat yang dosa;<br/>Mulia Tuhan! Mulia Tuhan!<br/>Tuhan bangkit, ku pun hiduplah.<br/>',NULL,60464,2);
INSERT INTO stanza VALUES('I87','2','Tuhan, betapa d''rita-Mu,<br/>tak terp''ri tak terukur;<br/>Kau diinjak, Kau ditendang,<br/>sakitnya tak kepalang.<br/>',NULL,60465,3);
INSERT INTO stanza VALUES('I87','3','Waktu Kau g''napkan tebusan,<br/>tiada orang yang serta;<br/>Kar''na s''mua ialah tawanan,<br/>hanya Kau yang bebaskan.<br/>',NULL,60466,4);
INSERT INTO stanza VALUES('I87','4','Kau t''lah paham upah dosa,<br/>murka, laknat dan maut;<br/>Dijual orang, dibuang Allah,<br/>ku ta''u cinta-Mu tulus.<br/>',NULL,60467,5);
INSERT INTO stanza VALUES('I88','1','Yesus berdoa, sendirian,<br/>sunyi Getsemani,<br/>Sungguh sedih, tangis lantang,<br/>peluh bercucuran.<br/>',NULL,60468,1);
INSERT INTO stanza VALUES('I88','chorus','Bagi aku, Dia telah disalib,<br/>Korban jiwa menebusku,<br/>Hati-Nya leleh,<br/>lumer, bagiku.<br/>',NULL,60469,2);
INSERT INTO stanza VALUES('I88','2','Dia dib''lenggu, bagi aku,<br/>pada malam itu;<br/>Sendirian, diperiksa,<br/>di depan Pilatus.<br/>',NULL,60470,3);
INSERT INTO stanza VALUES('I88','3','Dia disesah, bagi aku,<br/>bilur kujur badan,<br/>Tajuk duri dikenakan,<br/>diolok, dihina.<br/>',NULL,60471,4);
INSERT INTO stanza VALUES('I88','4','Dia pun mati, bagi aku,<br/>di Bukit Golgota,<br/>Tangan, kaki, bahkan lambung,<br/>berdarah, tebusku<br/>',NULL,60472,5);
INSERT INTO stanza VALUES('I88','5','Minum cawan, bagi aku,<br/>pahit, murka, laknat,<br/>Agar aku dapat s''lamat,<br/>terhindar binasa.<br/>',NULL,60473,6);
INSERT INTO stanza VALUES('I88','6','Dia berkata,"Sudah Genap!"<br/>Bisakah ku bebal?<br/>Ku tak lagi, degil hati,<br/>kasih-Nya tak terp''ri!<br/>',NULL,60474,7);
INSERT INTO stanza VALUES('I89','1','Tuhan, kasih-Mu desak Kau,<br/>terhina dan wafat!<br/>Agar kami menang atas<br/>dosa, dan si kuat.<br/>',NULL,60475,1);
INSERT INTO stanza VALUES('I89','2','Pikulan-Mu sungguh berat,<br/>betapa tanggungan!<br/>Dosa insan, cemooh setan,<br/>tambah murka Allah.<br/>',NULL,60476,2);
INSERT INTO stanza VALUES('I89','3','Ombak, badai bergelora,<br/>kini teduh reda,<br/>Kami girang kar''na dapat<br/>Nama-Mu nan hebat.<br/>',NULL,60477,3);
INSERT INTO stanza VALUES('I89','4','Kami segera terangkat,<br/>nyanyi kidung pujian;<br/>Namun di tempat wafat-Mu,<br/>mulailah kidungku.<br/>',NULL,60478,4);
INSERT INTO stanza VALUES('I90','1','Puji sekuat hati,<br/>syukur sekuat batin;<br/>Kurnia-Nya ku puji,<br/>bagiku Dia mati.<br/>Lihat, lihat, Putra Allah<br/>bagi kita Dia tersalib.<br/>',NULL,60479,1);
INSERT INTO stanza VALUES('I90','2','Cinta Tuhan besar,<br/>unggul dari semua;<br/>Orang s''lamat puji,<br/>cinta-Nya abadi.<br/>Lihat, lihat, Putra Allah<br/>bagi kita Dia tersalib.<br/>',NULL,60480,2);
INSERT INTO stanza VALUES('I90','3','Orang dosa s''lamat,<br/>Iblis telah kalah;<br/>Siapa dapat c''raikan<br/>cinta-Nya d''ngan kita?<br/>Lihat, lihat, Putra Allah<br/>bagi kita Dia tersalib.<br/>',NULL,60481,3);
INSERT INTO stanza VALUES('I91','1','Dia tak dapat tolong<br/>diri-Nya sendiri;<br/>Rela t''rima mati,<br/>buka pintu kurnia;<br/>Putra Allah t''lah berdarah,<br/>orang dosa baru s''lamat;<br/>Orang dosa baru s''lamat.<br/>',NULL,60482,1);
INSERT INTO stanza VALUES('I91','2','Dia tak dapat tolong<br/>diri-Nya sendiri;<br/>Kar''na Allah adil,<br/>Dia harus tersemb''lih;<br/>Agar hukum terpenuhi,<br/>kami tak berhutang lagi;<br/>Kami tak berhutang lagi.<br/>',NULL,60483,2);
INSERT INTO stanza VALUES('I91','3','Dia tak dapat tolong<br/>diri-Nya sendiri;<br/>Rela t''rima mati<br/>menggantikan kami;<br/>Curahkan darah di salib,<br/>pikul dosa Kaum Serani;<br/>Pikul dosa Kaum Serani.<br/>',NULL,60484,3);
INSERT INTO stanza VALUES('I91','4','Dia tak dapat tolong<br/>diri-Nya sendiri;<br/>Kasih ''ni sejati,<br/>kami tak berarti;<br/>Meski hambar hati kami,<br/>kar''na kasih timbul puji;<br/>Kar''na kasih timbul puji.<br/>',NULL,60485,4);
INSERT INTO stanza VALUES('I92','1','Apa saat! Sendirian,<br/>sekeliling gelap!<br/>Saat Putra Tunggal Bapa,<br/>mati bagi orang dosa,<br/>ini sungguh ''ngenas.<br/>Tuhan mulia disalibkan!<br/>Raja hayat orang tindas!<br/>',NULL,60486,1);
INSERT INTO stanza VALUES('I92','2','Allah insan hidup, mati,<br/>sungguh maha ajaib!<br/>''Nilah inti! Semuanya,<br/>memandang sambil menyembah,<br/>Kau patut dipuji!<br/>O, Tuhan Yesus, salib-Mu,<br/>kekal rumah idamanku!<br/>',NULL,60487,2);
INSERT INTO stanza VALUES('I92','3','O, saat pandang salib-Mu,<br/>hatiku terharu;<br/>Jelmaan kasih dipaku,<br/>kami girang campur haru,<br/>Kau mati bagiku!<br/>Hati pilu mendengar-Mu,<br/>"Eli, lema sabakhtani!"<br/>',NULL,60488,3);
INSERT INTO stanza VALUES('I92','4','Tuhan, kami patut mati,<br/>t''rima murka Allah;<br/>Tapi Putra terkasih-Mu,<br/>gantiku tanggung derita;<br/>p''nuhi keadilan.<br/>Dengan-Mu aku tersalib,<br/>dengan-Mu aku t''lah mati.<br/>',NULL,60489,4);
INSERT INTO stanza VALUES('I92','5','Dengan-Mu ku dapat hayat,<br/>bangkit dari mati;<br/>Kau Kepala, kami Tubuh,<br/>kami dan Kau milik Allah,<br/>t''rima berkat Allah.<br/>Dulu hanya pantas mati,<br/>kini d''ngan-Mu seru, "Abba".<br/>',NULL,60490,5);
INSERT INTO stanza VALUES('I93','1','Aduh, P''nolong t''lah berdarah,<br/>korbankan jiwa-Nya;<br/>Bagiku orang yang hina,<br/>Dia korbankan s''gala.<br/>',NULL,60491,1);
INSERT INTO stanza VALUES('I93','2','Kar''na dosaku yang najis,<br/>Ia mati tersalib!<br/>Belas kasih-Nya berlebih!<br/>Kurnia-Nya tak terp''ri!<br/>',NULL,60492,2);
INSERT INTO stanza VALUES('I93','3','Matahari bersembunyi,<br/>ngeri nampak ini;<br/>Kristus, Allah Mahatinggi,<br/>mati tanggung keji.<br/>',NULL,60493,3);
INSERT INTO stanza VALUES('I93','4','Waktu ingat Dia terpaku,<br/>aku pun terharu;<br/>Hancur luluhlah hatiku,<br/>air mata tercucur.<br/>',NULL,60494,4);
INSERT INTO stanza VALUES('I93','5','Tapi sikapku ''tradap-Mu,<br/>tak s''padan budi-Mu;<br/>Biarlah seumur hidupku<br/>mengabdi pada-Mu.<br/>',NULL,60495,5);
INSERT INTO stanza VALUES('I94','1','Sungguh ajaib tebusan-Mu,<br/>O, Tuhan Yesus-ku!<br/>Belum pernah nampak, dengar,<br/>pula terpikirkan;<br/>Status-Mu ajaib, ilahi,<br/>lampaui tuturku.<br/>Tebusan-Mu ajaib, unggul,<br/>lampaui pujianku.<br/>',NULL,60496,1);
INSERT INTO stanza VALUES('I94','chorus','O, ajaib tebusan-Mu!<br/>O, mulia, ciptaan ba-ru,<br/>Kekal limpah, berkhasiat!<br/>Patut kami puja!<br/>',NULL,60497,2);
INSERT INTO stanza VALUES('I94','2','Di salib Kau luka buatku,<br/>darah, air tercucur,<br/>Agar salur hayat buatku,<br/>menebus diriku.<br/>Darah adi basuh bersih,<br/>Allah ''kenan tentu,<br/>Hayat-Mu lahir-ulangkan,<br/>Satu - Kau dan aku.<br/>',NULL,60498,3);
INSERT INTO stanza VALUES('I94','3','Kau butir gandum ilahi,<br/>buahkan banyak butir;<br/>Sama sifat, sama mutu,<br/>menjadi Tubuh-Mu.<br/>Kaulah hayat, isi kami,<br/>kami kep''nuhan-Mu;<br/>Lewat kami hidup, g''rak-Mu,<br/>mengekspresikan-Mu.<br/>',NULL,60499,4);
INSERT INTO stanza VALUES('I94','4','Tubuh ini kediaman-Mu,<br/>tempat semayam-Mu;<br/>Pada kami Kau bermapan,<br/>taruh percaya-Mu.<br/>Puaskan hati dan maksud-Mu,<br/>juga pasangan-Mu;<br/>Hidup sama, satu Tubuh,<br/>nikmat segala-Mu.<br/>',NULL,60500,5);
INSERT INTO stanza VALUES('I94','5','Pecah roti mengenang-Mu,<br/>nampaklah tanda-Mu,<br/>Hati dan roh penuh puji,<br/>takjub tebusan-Mu.<br/>Kau jadikan kami Tubuh,<br/>kediaman, jodoh-Mu,<br/>Kami hanya t''rima kasih,<br/>sambil sembah, puji.<br/>',NULL,60501,6);
INSERT INTO stanza VALUES('I95','1','Ini cerita indah lagi manis,<br/>Allah utus Anak-Nya kar''na kasih,<br/>Dari surga mulia, mati tersalib,<br/>T''lah genap-kan tebusan bagi kami.<br/>',NULL,60502,1);
INSERT INTO stanza VALUES('I95','chorus','Pujilah! Pujilah!<br/>Karya-Nya t''lah genap!<br/>Syukurlah! Syukurlah!<br/>Kurnia berlimpah!<br/>Yesus, Juru-s''lamat yang amat mulia,<br/>kidung bagi Mesias, s''lama tak sudah.<br/>',NULL,60503,2);
INSERT INTO stanza VALUES('I95','2','Ini cerita betapa ajaib,<br/>Demi darah, tuntutan takhta genap,<br/>Anak Allah tanggung hukuman adil,<br/>Hingga Allah puaslah, kami pun senang.<br/>',NULL,60504,3);
INSERT INTO stanza VALUES('I95','3','Kristus t''lah naik takhta, mulia cemerlang,<br/>Yesus ditinggikan, nama-Nya megah,<br/>Yesus Juru-s''lamat dapat mahkota,<br/>Patut t''rima sembah dan semua pujian.<br/>',NULL,60505,4);
INSERT INTO stanza VALUES('I96','1','Kristus turun ke dunia,<br/>tolong orang berdosa,<br/>Mengalami sengsara,<br/>haleluya! Juru-s''lamat!<br/>',NULL,60506,1);
INSERT INTO stanza VALUES('I96','2','T''rima hina dan nista,<br/>untukku pikul dosa;<br/>Jadi hayat, kuatku,<br/>haleluya! Juru-s''lamat!<br/>',NULL,60507,2);
INSERT INTO stanza VALUES('I96','3','Kami lemah dan buruk,<br/>Dia Domba yang kudus;<br/>Tebusan mampu saja,<br/>haleluya! Juru-s''lamat!<br/>',NULL,60508,3);
INSERT INTO stanza VALUES('I96','4','Dia tersalib, ku hidup,<br/>Dia menang, Iblis takluk;<br/>Dia naik takhta, b''ri kurnia,<br/>haleluya! Juru-s''lamat!<br/>',NULL,60509,4);
INSERT INTO stanza VALUES('I96','5','Dia ''kan utus malaikat,<br/>jemputku jumpa Dia;<br/>Kami tetap bersorak,<br/>haleluya! Juru-s''lamat!c<br/>',NULL,60510,5);
INSERT INTO stanza VALUES('I97','1','Di Golgota, P''nolong korban;<br/>''nempuh hina, dan terpentang;<br/>Tumpah darah, tebus dosa;<br/>s''lenggarakan janji baru.<br/>',NULL,60511,1);
INSERT INTO stanza VALUES('I97','chorus','Oh, Golgota, nyeri pedih,<br/>bagiku Yesus berdarah;<br/>oh, Golgota, berkat agung!<br/>Bagiku Yesus berkorban.<br/>',NULL,60512,2);
INSERT INTO stanza VALUES('I97','2','Batu terb''lah, langit gelap,<br/>Tuhan bers''ru, "Sudah genap!"<br/>Tirai koyak, jalan buka,<br/>hampir Allah, t''rima rahmat.<br/>',NULL,60513,3);
INSERT INTO stanza VALUES('I97','3','Tuhan Yesus, mengapakah<br/>buatku rela menderita?<br/>Atas salib terpancanglah:<br/>luka, siksa, di Golgota!<br/>',NULL,60514,4);
INSERT INTO stanza VALUES('I98','1','Suara pujian sulit dapat,<br/>mari seg''ra angkat suara;<br/>Bila kita berdiam saja,<br/>batu pun akan mencela.<br/>',NULL,60515,1);
INSERT INTO stanza VALUES('I98','2','Mari kita bersorak riang,<br/>pada Tuhan P''nolong kita;<br/>Bagi kita Dia berkorban,<br/>mencurahkan s''mua tenaga.<br/>',NULL,60516,2);
INSERT INTO stanza VALUES('I98','3','Ada kidung amat khusus,<br/>dinyanyikan orang s''lamat;<br/>Orang kafir tidak mampu,<br/>kar''na tak paham maknanya.<br/>',NULL,60517,3);
INSERT INTO stanza VALUES('I98','4','Meski para m''laikat paham,<br/>belas kasih dalam darah;<br/>Tapi tidak sep''ri kita,<br/>yang rasakan khasiat darah.<br/>',NULL,60518,4);
INSERT INTO stanza VALUES('I98','5','Meski m''laikat s''lalu dapat,<br/>sembah sujud pada Allah;<br/>Tapi kita nyanyi riang,<br/>Anak Manusia bertakhta.<br/>',NULL,60519,5);
INSERT INTO stanza VALUES('I98','6','Tuhan, kami mau memuji,<br/>kasih yang m''lewati mati;<br/>Kami seg''ra t''rangkat tinggi,<br/>menyembah-Mu dan memuji.<br/>',NULL,60520,6);
INSERT INTO stanza VALUES('I99','1','Rebah dalam kubur,<br/>Yesus Tuhanku!<br/>Tunggu fajar m''rekah<br/>ya, Tuhanku!<br/>',NULL,60521,1);
INSERT INTO stanza VALUES('I99','chorus','Dari kubur Dia bangkit,<br/>musuh musuh tersapu habis,<br/>Dari maut, t''lah bangkit dan menang kini,<br/>berkuasa beserta para S''rani.<br/>Dia bangkit! Dia bangkit!<br/>Haleluya, Dia bangkit!<br/>',NULL,60522,2);
INSERT INTO stanza VALUES('I99','2','Sia-sia yang menjaga,<br/>Yesus Tuhanku;<br/>Sia-sia yang menyumbat,<br/>ya Tuhanku.<br/>',NULL,60523,3);
INSERT INTO stanza VALUES('I99','3','Maut tak berdaya,<br/>Yesus Tuhanku;<br/>B''lenggu Dia orakkan,<br/>ya Tuhanku.<br/>',NULL,60524,4);
INSERT INTO stanza VALUES('I100','1','Tuhan bangkit, usai vonis maut,<br/>dalam Dia, apa daya maut?<br/>Tuhan bangkit, tak lagi dihukum,<br/>kubur kosong, itu bukti teguh.<br/>',NULL,60525,1);
INSERT INTO stanza VALUES('I100','2','Tuhan bangkit, ku bangkit serta-Nya,<br/>di kubur-Nya, musuh terkubur s''mua.<br/>Tuhan bangkit, ku lepas dari maut,<br/>dalam Dia, hayat bangkit menunjang.<br/>',NULL,60526,2);
INSERT INTO stanza VALUES('I100','3','Tuhan bangkit, ku diselamatkan,<br/>kini jalan ikuti jejak-Nya.<br/>Tuhan bangkit, ku masuk ruang kudus,<br/>serta Dia, hidup depan terang-Nya.<br/>',NULL,60527,3);
INSERT INTO stanza VALUES('I100','4','Tuhan bangkit, Perintis di depan,<br/>di luar kemah, jadi saksi-Nya.<br/>Tuhan bangkit, ku mau sorak menang,<br/>Kau t''lah menang! Umat-Mu bebaslah!<br/>',NULL,60528,4);
INSERT INTO stanza VALUES('I101','1','Kristus bangkit! Haleluya!<br/>Sang Pemenang t''lah bangkit;<br/>Puji nyaring! Haleluya!<br/>Kristus bangkitlah sudah.<br/>Hati penuh puja sembah,<br/>saat t''rang-Nya tertampil;<br/>Sujud dalam sukacita,<br/>lampaui luka, duka.<br/>',NULL,60529,1);
INSERT INTO stanza VALUES('I101','chorus','Kristus bangkit! Haleluya!<br/>Sang Pemenang t''lah bangkit;<br/>Puji nyaring! Haleluya!<br/>Kristus bangkitlah sudah.<br/>',NULL,60530,2);
INSERT INTO stanza VALUES('I101','2','Kristus bangkit! Sungguh girang!<br/>D''rita dunia sirnalah;<br/>Lewat gerbang sukacita,<br/>balik ke alam hayat;<br/>Maut, neraka s''mua takluk,<br/>kepada Dia Sang Menang;<br/>Malak saksikan tindak-Nya,<br/>mahkota dikenakan.<br/>',NULL,60531,3);
INSERT INTO stanza VALUES('I101','3','Kristus bangkit! Sungguh unggul!<br/>Maut, n''raka tak daya;<br/>Ku milik-Nya, bersandar Dia,<br/>menang atas segala.<br/>Semua bimbang, cemas, kesal,<br/>dari hati terenyah;<br/>Hari bangkit, patut girang,<br/>mari kita berpesta.<br/>',NULL,60532,4);
INSERT INTO stanza VALUES('I102','1','Kristus Yesus t''lah bangkit.<br/>Haleluya!<br/>Belenggu maut t''lah sirna.<br/>Haleluya!<br/>Para m''laikat bersorak.<br/>Haleluya!<br/>Kaum saleh memuji.<br/>Haleluya!<br/>',NULL,60533,1);
INSERT INTO stanza VALUES('I102','2','Dia keluar dari maut.<br/>Haleluya!<br/>Maut, mana sengatmu?<br/>Haleluya!<br/>Mati, bangkit, naik surga.<br/>Haleluya!<br/>Kubur, mana cengk''rammu?<br/>Haleluya!<br/>',NULL,60534,2);
INSERT INTO stanza VALUES('I102','3','Tebusan telah genap.<br/>Haleluya!<br/>Perang telah berakhir.<br/>Haleluya!<br/>Sia-sia maut menahan.<br/>Haleluya!<br/>Kristus menang. naik surga.<br/>Haleluya!<br/>',NULL,60535,3);
INSERT INTO stanza VALUES('I102','4','Kami bangkit serta-Nya.<br/>Haleluya!<br/>Duduk surga dengan Dia.<br/>Haleluya!<br/>Ditinggikan s''rupa Dia.<br/>Haleluya!<br/>Lepas belenggu dunia.<br/>Haleluya!<br/>',NULL,60536,4);
INSERT INTO stanza VALUES('I103','1','Penggantiku, b''lum kembali,<br/>membuat ku cemas kuatir;<br/>Dosaku tak terlunasi?<br/>Kar''na itu, Dia terkunci?<br/>',NULL,60537,1);
INSERT INTO stanza VALUES('I103','2','Dosaku terlampau berat?<br/>Banyak, hingga tak terampun?<br/>Atau darah-Nya tak mampu,<br/>t''naga, cakupan, terbatas?<br/>',NULL,60538,2);
INSERT INTO stanza VALUES('I103','3','Sorak! Yesus sudah bangkit!<br/>Mulia, megah, makin tinggi;<br/>Alam maut ditembusi,<br/>kuasa gelap, tak berkutik.<br/>',NULL,60539,3);
INSERT INTO stanza VALUES('I103','4','Kembali-Nya justru bukti,<br/>adil Allah terpenuhi;<br/>Cinta Allah belas kasih,<br/>penebusan rampung kini.<br/>',NULL,60540,4);
INSERT INTO stanza VALUES('I103','5','Kebangkitan tanda bukti,<br/>penebusan oleh darah;<br/>Haleluya, ku t''lah bersih!<br/>Haleluya, diampuni!<br/>',NULL,60541,5);
INSERT INTO stanza VALUES('I104','1','Tuhan pernah j''lajah<br/>alam maut;<br/>Bukan mati kena<br/>racun dosa.<br/>Iblis kuasa maut,<br/>telah Kau remukkan,<br/>Tak daya lagi dia,<br/>cengk''ram orang.<br/>',NULL,60542,1);
INSERT INTO stanza VALUES('I104','2','Tembus alam kubur,<br/>Dikau bangkit;<br/>Maut tak berdaya,<br/>kalah mutlak!<br/>Dikau sudah menang,<br/>atas kubur gelap,<br/>Runtuh kuasa maut,<br/>kelam lewat.<br/>',NULL,60543,2);
INSERT INTO stanza VALUES('I104','3','Kemenangan mutlak,<br/>Kau dapatkan!<br/>Buah limpah, mulia<br/>bagi Allah!<br/>Wafat-Mu lahirkan,<br/>banyak anak Allah,<br/>Bagi kediaman-Mu,<br/>tempuh hidup.<br/>',NULL,60544,3);
INSERT INTO stanza VALUES('I104','4','Dikau buah bungar<br/>nan tersayang;<br/>Putra Sulung Allah,<br/>pimpin tiasa.<br/>Kau-lah Sang Kepala,<br/>ku mau puji s''lama;<br/>Layak t''rima pujian,<br/>sujud sembah.<br/>',NULL,60545,4);
INSERT INTO stanza VALUES('I105','1','Haleluya, "Kristus bangkit!"<br/>Ke tempat tinggi t''rangkat!<br/>Patah sudah t''rali maut,<br/>malak, insan bersorak.<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>Dia hidup, jadi hayat.<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>Dia hidup, jadi hayat.<br/>',NULL,60546,1);
INSERT INTO stanza VALUES('I105','2','Haleluya, Kristus bangkit!<br/>T''rangkat jadi Kepala!<br/>Utus Roh Kudus, bersaksi,<br/>salurkan segala-Nya;<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>benarkan, s''lamatkanku.<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>benarkan, s''lamatkanku.<br/>',NULL,60547,2);
INSERT INTO stanza VALUES('I105','3','Haleluya, Kristus bangkit!<br/>Maut hilang kuasanya!<br/>Kristus itu kebangkitan,<br/>tolongku dari maut;<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>hidup, jadi karunia.<br/>Dia t''lah bangkit, Dia t''lah bangkit,<br/>hidup, jadi karunia.<br/>',NULL,60548,3);
INSERT INTO stanza VALUES('I106','1','Mulia bagi-Mu,<br/>Putra, Sang Bangkit,<br/>Kekal Kau t''lah menang,<br/>lampaui mati;<br/>Malak jubah putih,<br/>batu pun guling;<br/>Kubur telah kosong,<br/>bukti Kau bangkit.<br/>',NULL,60549,1);
INSERT INTO stanza VALUES('I106','chorus','Mulia bagi-Mu, Putra, Sang Bangkit;<br/>Kekal Kau t''lah menang, lampaui mati.<br/>',NULL,60550,2);
INSERT INTO stanza VALUES('I106','2','Kristus t''lah bangkit,<br/>tampilkan diri,<br/>Ramah beri salam,<br/>enyah takut, g''lap;<br/>Dengan kidung menang,<br/>g''reja memuji,<br/>Kar''na Tuhan hidup,<br/>maut terganyang!<br/>',NULL,60551,3);
INSERT INTO stanza VALUES('I106','3','Kau Raja hayat,<br/>mulia nan jaya;<br/>Tanpa-Mu tiada<br/>hayat dan menang.<br/>Menang lebih oleh<br/>kebangkitan-Mu,<br/>Sampai masuk k''rajaan,<br/>hentilah perang.<br/>',NULL,60552,4);
INSERT INTO stanza VALUES('I107','1','Yesus bangkitlah sudah,<br/>t''radap-Nya maut tak daya;<br/>Kami terhibur semua,<br/>hormat, puji bagi-Nya.<br/>Penebusan t''lah genap,<br/>musuh kami t''lah kalah;<br/>Tebusan telah lunas,<br/>tak usah d''rita pula.<br/>',NULL,60553,1);
INSERT INTO stanza VALUES('I107','2','Tutup kubur terlontar,<br/>pintu maut terhempas;<br/>Sejenak Dia mend''rita,<br/>agar ku t''rima kurnia.<br/>Dia t''lah mati sekali,<br/>tak mungkin mati lagi;<br/>Sebuah kubur t''lah hampa,<br/>kubur lain kelak juga.<br/>',NULL,60554,2);
INSERT INTO stanza VALUES('I107','3','Sebutir gandum mati,<br/>tumbuh banyaklah kini;<br/>Dulu hanya Seorang,<br/>kini jadi gereja.<br/>Kami ialah Tubuh-Nya,<br/>s''lalu ikut Kepala;<br/>Mati, bangkit, serta-Nya,<br/>bagi-Nya pujian kekal.<br/>',NULL,60555,3);
INSERT INTO stanza VALUES('I108','1','Kristus Allah, Juru-s''lamat,<br/>bagi-Mu s''mua pujian;<br/>Kau berdarah, g''nap tebusan,<br/>kami kecap berkat.<br/>Kuasa-Mu melibas lawan,<br/>kini duduk takhta;<br/>Pimpin kami masuk mulia,<br/>Kerajaan Surga.<br/>',NULL,60556,1);
INSERT INTO stanza VALUES('I108','2','Kristus Allah, Juru-s''lamat,<br/>bagi-Mu s''mua pujian;<br/>Kau t''lah gempur kubu maut,<br/>taklukkan rajanya,<br/>Tak berkutik alam bawah,<br/>kuasa maut tenggelam,<br/>Kunci maut Kau yang pegang,<br/>kubur tak berdaya.<br/>',NULL,60557,2);
INSERT INTO stanza VALUES('I108','3','Kristus Allah, Juru-s''lamat,<br/>bagi-Mu s''mua pujian;<br/>Oleh salib Kau singkirkan,<br/>raja pemberontak,<br/>Pula oleh kuasa hayat,<br/>tembus alam gelap,<br/>Singkir maut g''lap gulita,<br/>bebaskan tawanan.<br/>',NULL,60558,3);
INSERT INTO stanza VALUES('I108','4','Kristus Allah, Juru-s''lamat,<br/>bagi-Mu s''mua pujian;<br/>Kau-lah Tuhan, kekal menang,<br/>kekal ku merdeka.<br/>Kau-lah kuasa peny''lamatan,<br/>mutlak aku bebas,<br/>Mulia sampai selamanya,<br/>bagi-Mu dan Allah.<br/>',NULL,60559,4);
INSERT INTO stanza VALUES('I109','1','Puji, puji, Kristus menang!<br/>Puji Kristus t''lah menang!<br/>Dosa sirna, hutang impas,<br/>penebusan t''lah genap!<br/>Ganyang Satan dan roh jahat,<br/>menang sandar salib-Nya!<br/>',NULL,60560,1);
INSERT INTO stanza VALUES('I109','2','Puji, puji, Kristus bangkit!<br/>Puji Kristus t''lah bangkit!<br/>Maut keji, sapu bersih;<br/>hayat terbitlah kini!<br/>Alam maut ditembusi,<br/>nyata kuasa bangkit.<br/>',NULL,60561,2);
INSERT INTO stanza VALUES('I109','3','Puji, puji, Kristus t''rangkat!<br/>Puji Kristus terangkat!<br/>Lampaui semua penguasa,<br/>sandang nama terhormat!<br/>Pegang kuasa atas s''gala,<br/>musuh sungkur duli-Nya!<br/>',NULL,60562,3);
INSERT INTO stanza VALUES('I109','4','Haleluya, Kristus menang!<br/>Haleluya, Dia menang!<br/>Haleluya, Kristus bangkit!<br/>Haleluya, Dia bangkit!<br/>Haleluya, Kristus t''rangkat!<br/>Haleluya, Dia t''rangkat!<br/>',NULL,60563,4);
INSERT INTO stanza VALUES('I110','1','Dengar, suara menggelegar,<br/>junjung tinggi Sang Domba;<br/>Laksaan saleh beresonan,<br/>hamonis pun tak hingga.<br/>',NULL,60564,1);
INSERT INTO stanza VALUES('I110','2','Tiap penjuri puji Domba,<br/>genap surga bergita;<br/>Se-mua mulut nyanyi riang,<br/>penuh luap pujian.<br/>',NULL,60565,2);
INSERT INTO stanza VALUES('I110','3','Wangi syukur p''ri ukupan,<br/>membubung pada Bapa;<br/>Se-mua lutut sembah Putra,<br/>memujilah serempak.<br/>',NULL,60566,3);
INSERT INTO stanza VALUES('I110','4','Terang Putra menyatakan,<br/>mulia Bapa sepenuh;<br/>Hikmat Bapa ''nyatakan jua,<br/>Sang Putra sama agung.<br/>',NULL,60567,4);
INSERT INTO stanza VALUES('I110','5','Roh Kudus ''nembus segala,<br/>kaum surga selaras;<br/>kelilingi Domba Suci,<br/>memuji Dia Sang Kekal.<br/>',NULL,60568,5);
INSERT INTO stanza VALUES('I110','6','Cip-taan baru puas kini,<br/>lega, riang, dan pasti;<br/>Berkat s''lamat yang diberi,<br/>bebas, tak t''rikat lagi.<br/>',NULL,60569,6);
INSERT INTO stanza VALUES('I110','7','Dengar! Surga riuh kembali,<br/>kidung puji menggema;<br/>Cakrawala penuh amin!<br/>Amin atas kur-nia-Nya.<br/>',NULL,60570,7);
INSERT INTO stanza VALUES('I111','1','Putra Allah, Juru-s''lamat,<br/>darah adi menebusku,<br/>lepas maut dosa;<br/>kaum saleh-Mu girang nampak:<br/>Kau bermahkota mulia,<br/>dan duduk di takhta,<br/>dan duduk di takhta.<br/>',NULL,60571,1);
INSERT INTO stanza VALUES('I111','2','Kenan Bapa, Kau terangkat,<br/>mulia, hormat, kuasa,<br/>duduk kanan Allah.<br/>Kini puji, hikmat, limpah,<br/>s''mua milik-Mu, Juru-s''lamat!<br/>Hari-Mu tak sudah,<br/>hari-Mu tak sudah.<br/>',NULL,60572,2);
INSERT INTO stanza VALUES('I111','3','Kau Sang Kepala gereja,<br/>berkat bagi g''nap anggota,<br/>milik-Mu milikku;<br/>Kau-lah hayat, kekuatanku,<br/>hingga ku berdiri teguh,<br/>Musuh lari kabur,<br/>musuh lari kabur.<br/>',NULL,60573,3);
INSERT INTO stanza VALUES('I111','4','Hari mulia seg''ra tiba,<br/>mempelai-Mu ''kan terangkat,<br/>tatap Sang Rupawan,<br/>Sungguh girang, nampak Dikau;<br/>lihat, kami s''mua milik-Mu,<br/>Kekal beserta-Mu,<br/>Kekal beserta-Mu.<br/>',NULL,60574,4);
INSERT INTO stanza VALUES('I112','1','Tengok, Sang Menang terangkat,<br/>Raja agung terhormat,<br/>Naik awan kereta-Nya,<br/>balik istana surga;<br/>Dengar malak, padu suara,<br/>haleluya pujilah,<br/>gerbang surga pada sorak:<br/>Sambutlah, sambutlah,<br/>sambut Sang Raja surga.<br/>',NULL,60575,1);
INSERT INTO stanza VALUES('I112','2','Siapa datang dalam mulia,<br/>dengan nafiri Yobel?<br/>Tuhan jaya, Allah s''mesta,<br/>Dia sudah menang perang.<br/>Dia t''lah tanggung d''rita salib,<br/>dari kubur t''lah bangkit,<br/>Singkir dosa, tumpas Iblis,<br/>melalui, Dia mati,<br/>Musuh telah tersingkir.<br/>',NULL,60576,2);
INSERT INTO stanza VALUES('I112','3','Angkat tangan beri berkat,<br/>Dia terangkat ke atas;<br/>Murid-murid terpesona,<br/>Dia terangkat ke surga.<br/>Jalan serta-Nya, Dia kenan,<br/>sebarkan kebenaran;<br/>Henokhku diangkat Allah,<br/>terangkat, ke surga,<br/>Masuk hadirat Allah.<br/>',NULL,60577,3);
INSERT INTO stanza VALUES('I112','4','Masuk tempat Mahakudus,<br/>Harunku bawa darah;<br/>Raja-raja dikalahkan,<br/>Yosua masuk Kanaan;<br/>Umat Allah, Dia tanam,<br/>di tanah perjanjian;<br/>Eliaku beri berkat,<br/>berlipat, dwi ganda;<br/>Berkat yang dari surga.<br/>',NULL,60578,4);
INSERT INTO stanza VALUES('I112','5','Dia tingkatkan insan kita,<br/>di samping kanan Allah;<br/>Duduk surga beserta-Nya,<br/>bersama dalam mulia.<br/>Yesus Raja, malak sembah,<br/>insan m''raja serta-Nya;<br/>Oleh keterangkatan-Nya,<br/>ku yakin, percaya,<br/>Ku t''rangkat beserta-Nya.<br/>',NULL,60579,5);
INSERT INTO stanza VALUES('I113','1','Mahakuasa! Nama Yesus!<br/>Sujud s''mua malaikat,<br/>Menobatkan pun menjunjung,<br/>Dia Tuhan semesta.<br/>Menobatkan pun menjunjung,<br/>Dia Tuhan semesta.<br/>',NULL,60580,1);
INSERT INTO stanza VALUES('I113','2','Saleh martir s''panjang abad,<br/>berseru di mezbah;<br/>Junjung puji akar Isai,<br/>Dia Tuhan semesta.<br/>Junjung puji akar Isai,<br/>Dia Tuhan semesta.<br/>',NULL,60581,2);
INSERT INTO stanza VALUES('I113','3','Turunan Adam yang jatuh,<br/>kini t''lah tertebus;<br/>Telah s''lamat, wajib syukur,<br/>Dia Tuhan semesta.<br/>Telah s''lamat, wajib syukur,<br/>Dia Tuhan semesta.<br/>',NULL,60582,3);
INSERT INTO stanza VALUES('I113','4','Orang dosa takkan lupa,<br/>duka campur cuka;<br/>Mari tatap kepada-Nya,<br/>Dia Tuhan semesta.<br/>Mari tatap kepada-Nya,<br/>Dia Tuhan semesta.<br/>',NULL,60583,4);
INSERT INTO stanza VALUES('I113','5','Moga semua suku bangsa,<br/>bersorak pada-Nya;<br/>Mulia hormat nama-Nya,<br/>Dia Tuhan semesta.<br/>Mulia hormat nama-Nya,<br/>Dia Tuhan semesta.<br/>',NULL,60584,5);
INSERT INTO stanza VALUES('I113','6','Laksaan gegap gempita,<br/>ku juga ''tiarap;<br/>Puji sembah hingga kekal,<br/>Dia Tuhan semesta.<br/>Puji sembah hingga kekal,<br/>Dia Tuhan semesta.<br/>',NULL,60585,6);
INSERT INTO stanza VALUES('I114','1','Tengok! Domba dinobatkan!<br/>Mulia hormat bagi-Nya!<br/>Apa tak layak bagi-Nya?<br/>Surga layak bagi-Nya!<br/>Surga layak bagi-Nya!<br/>',NULL,60586,1);
INSERT INTO stanza VALUES('I114','2','Dia duduk takhta surga,<br/>duduk takhta agunglah!<br/>Dia judul kidung pujian,<br/>mustika Allah Bapa!<br/>Mustika Allah Bapa!<br/>',NULL,60587,2);
INSERT INTO stanza VALUES('I114','3','Dia agung, namun senang<br/>t''rima layanan kita;<br/>Meski lemah suara kita,<br/>Dia tetap berkenan.<br/>Dia tetap berkenan.<br/>',NULL,60588,3);
INSERT INTO stanza VALUES('I114','4','Nyanyian kita satu saja,<br/>junjung DOmba tersemb''lih;<br/>Juga Yang s''mayam di takhta,<br/>t''rima pujian abadi.<br/>T''rima pujian abadi.<br/>',NULL,60589,4);
INSERT INTO stanza VALUES('I114','5','Pernah dulu diremehkan,<br/>kini mulia pun hormat;<br/>Miliki takhta mahkota,<br/>Dia layak pun tepat!<br/>Dia layak pun tepat!<br/>',NULL,60590,5);
INSERT INTO stanza VALUES('I115','1','Tengok, Yesus duduk surga!<br/>Kristus Tuhan bertakhta;<br/>Dia insan nan terangkat,<br/>hormat mulia Dia dapat.<br/>',NULL,60591,1);
INSERT INTO stanza VALUES('I115','2','Mengenakan sifat insan,<br/>hidup taat murad-Nya.<br/>Mati, bangkit, d''ngan tubuh-Nya,<br/>tetap insan di surga.<br/>',NULL,60592,2);
INSERT INTO stanza VALUES('I115','3','Di dalam-Nya Allah m''rendah,<br/>datang tengah manusia;<br/>Di dalam-Nya insan t''rangkat,<br/>bersama-Nya di surga.<br/>',NULL,60593,3);
INSERT INTO stanza VALUES('I115','4','Dia-lah Allah bawa insan,<br/>pamer, ''nyatakan Allah;<br/>Insan - Allah padu esa,<br/>insan beroleh mulia.<br/>',NULL,60594,4);
INSERT INTO stanza VALUES('I115','5','Dari Yesus t''rangkat, mulia,<br/>Roh almuhitlah turunlah;<br/>Persona dan karya Putra,<br/>Roh itu yang buktikan.<br/>',NULL,60595,5);
INSERT INTO stanza VALUES('I115','6','Dengan Yesus t''rangkat,<br/>mulia, bersatulah gereja;<br/>Dalam Roh Yesus inilah, anggota hidup sama.<br/>',NULL,60596,6);
INSERT INTO stanza VALUES('I115','7','Tengok, insan duduk surga!<br/>Raja s''mesta bertakhta!<br/>Dia-lah Yesus Juru-s''lamat,<br/>mulia, hormat, s''lamanya.<br/>',NULL,60597,7);
INSERT INTO stanza VALUES('I116','1','Tuhan Yesus, aku girang,<br/>lewat sudah sengsara-Mu,<br/>Kau menggantikanku;<br/>Menang jaya garapan-Mu,<br/>Kini nikmati hasilnya,<br/>Kau dijunjung mulia.<br/>',NULL,60598,1);
INSERT INTO stanza VALUES('I116','2','Dulu duri di kepala,<br/>kini mahkota mulia,<br/>Duduk takhta Bapa.<br/>Tuhan, bagi-Mu s''mua pujian,<br/>Khidmat kami sujud sembah,<br/>hanya Kau yang layak.<br/>',NULL,60599,2);
INSERT INTO stanza VALUES('I116','3','Di sana Kau-lah Kepala;<br/>tunggu s''mua anggota Tubuh,<br/>Terima s''gala-Mu -<br/>Mulia serta takhta-Mu,<br/>Kuasa dan k''rajaan-Mu;<br/>Kau dan aku satu.<br/>',NULL,60600,3);
INSERT INTO stanza VALUES('I116','4','Dikau senang, kami juga,<br/>Dikau menang, kami gita,<br/>Kau dan kami esa.<br/>Di sini susah dan lelah,<br/>Namun girang saat kenang,<br/>Kau empunya takhta!<br/>',NULL,60601,4);
INSERT INTO stanza VALUES('I117','1','Tuhan t''lah naik takhta, ''lampau s''gala;<br/>Domba t''lah ternobat, unggul mulia;<br/>Dia kekal hidup, kekal unggul;<br/>Allah t''lah junjung Dia lampaui s''gala.<br/>',NULL,60602,1);
INSERT INTO stanza VALUES('I117','chorus','Melampaui segalanya!<br/>Sang Tersalib lampaui segala!<br/>Depan kaki-Nya sembah tak henti,<br/>Allah t''lah junjung Dia, ''lampau s''gala!<br/>',NULL,60603,2);
INSERT INTO stanza VALUES('I117','2','Angin kecamuk, ombak gejolak,<br/>aku dilanda hendak ditelan;<br/>Pada Tuhanku aku tengadah,<br/>jalan atas ombak aman ''luasa.<br/>',NULL,60604,3);
INSERT INTO stanza VALUES('I117','3','Meski kubu musuh tinggi besar,<br/>ada kendala siap menghadang,<br/>Maju tak gentar, bereskan semua,<br/>yakin Dia lampaui segala.<br/>',NULL,60605,4);
INSERT INTO stanza VALUES('I117','4','S''luruh bumi jadi k''rajaan-Nya,<br/>isi semesta takluk pada-Nya;<br/>S''luruh pemenang jaya perkasa,<br/>bersama Dia lampaui segala.<br/>',NULL,60606,5);
INSERT INTO stanza VALUES('I118','1','Dulu kepala berduri,<br/>kini mulia dib''ri;<br/>Tuhan Yesus, P''nolong kami,<br/>Kau terangkat tinggi.<br/>',NULL,60607,1);
INSERT INTO stanza VALUES('I118','2','Dikau sukaria kaum S''rani,<br/>t''rang di langit tinggi;<br/>Kami sesap sungai kasih,<br/>memang tak terperi.<br/>',NULL,60608,2);
INSERT INTO stanza VALUES('I118','3','Olok, cemooh dan kuasa-Mu,<br/>b''ri kami seluruh;<br/>Bumi menyangkal nama-Mu,<br/>Allah junjung agung.<br/>',NULL,60609,3);
INSERT INTO stanza VALUES('I118','4','Yang mau mend''rita bersama,<br/>k''lak mulia di surga;<br/>Tangguhkan kami, ya, Tuhan,<br/>abai mewah dunia.<br/>',NULL,60610,4);
INSERT INTO stanza VALUES('I118','5','Salib bagi-Mu maut, hina,<br/>bagiku dia hayat!<br/>Pun mulia dan kuasa!<br/>Sentosa s''lamanya!<br/>',NULL,60611,5);
INSERT INTO stanza VALUES('I119','1','Mulia, mulia, kekal mulia,<br/>bagi Kristus ternobat!<br/>Mulia, mulia, kekal mulia,<br/>bagi Tuhan terangkat!<br/>Maha terhormat nama-Nya,<br/>surga, buana memuja;<br/>Mulia, mulia, kekal mulia,<br/>bagi Nama terhormat.<br/>',NULL,60612,1);
INSERT INTO stanza VALUES('I119','2','Bertakhta mulia di surga,<br/>Dia setara d''ngan Allah;<br/>Rela kena rupa hamba,<br/>tempuh d''rita manusia;<br/>Taat mutlak pada Bapa,<br/>wafat pun sukarela;<br/>Atas salib mati, hina,<br/>tak elak sedikit jua.<br/>',NULL,60613,2);
INSERT INTO stanza VALUES('I119','3','Mahkota surga nan mulia,<br/>bagi Dia yang merendah;<br/>Jubah surga mewah indah,<br/>kini dikenakan-Nya.<br/>Tekuk lutut semuanya,<br/>s''mua mulut akui-Nya;<br/>Tuhan s''mesta, Raja mulia,<br/>semua pujian bagi-Nya.<br/>',NULL,60614,3);
INSERT INTO stanza VALUES('I119','4','Mulia, mulia, kekal mulia,<br/>bagi Dia Sang Mustika;<br/>Di surga Dia mulia,<br/>di bumi mulia juga.<br/>Mulia bagilah Allah,<br/>bagi "Aku Adalah";<br/>Mulia, mulia, kekal mulia,<br/>bagi Dia s''lamanya.<br/>',NULL,60615,4);
INSERT INTO stanza VALUES('I120','1','O, Tuhan Kau Sang Almuhit,<br/>bermahkota mulia;<br/>Kar''na kuasa, wibawa-Mu,<br/>s''mua pujian bagi-Mu.<br/>',NULL,60616,1);
INSERT INTO stanza VALUES('I120','2','Allah nan Insan di bumi,<br/>berkenan menghamba;<br/>Insan nan Allah di langit,<br/>almuhit terhormat.<br/>',NULL,60617,2);
INSERT INTO stanza VALUES('I120','3','Kau Insan dalam mulia,<br/>duduk takhta Allah;<br/>Kuasa di alam s''mesta,<br/>bagi-Mu semua.<br/>',NULL,60618,3);
INSERT INTO stanza VALUES('I120','4','Naik surga, ditinggikan,<br/>dapat nama agung;<br/>Semua mulut mengaku,<br/>s''mua lutut bertelut.<br/>',NULL,60619,4);
INSERT INTO stanza VALUES('I120','5','Tuhan Kristus Kau diangkat,<br/>Roh Kudus buktikan;<br/>Dalam mulia, dalam surga,<br/>t''rima takhta, kuasa.<br/>',NULL,60620,5);
INSERT INTO stanza VALUES('I120','6','Tuhan mulia kami sembah,<br/>bagi-Mu s''mua pujian;<br/>Sang Almuhit kami junjung,<br/>puji Kau yang patut!<br/>',NULL,60621,6);
INSERT INTO stanza VALUES('I121','1','Tengok, betapa mulia,<br/>d''rita Putra t''lah lewat!<br/>Raih menang dari perang,<br/>duduk takhta mulia!<br/>Nobat Dia, nobat Dia,<br/>Raja segala raja.<br/>',NULL,60622,1);
INSERT INTO stanza VALUES('I121','2','Manusia pernah olok Dia,<br/>tajuk duri Dia kena;<br/>Kini dinobat mulia, malak,<br/>saleh menyembah;<br/>Nobat Dia, nobat Dia,<br/>Sang Kesayangan Allah.<br/>',NULL,60623,2);
INSERT INTO stanza VALUES('I121','3','Nobatkan Sang Penyelamat,<br/>kau piala perang-Nya!<br/>Bergolaklah cakrawala,<br/>hatimu Dia bertakhta;<br/>Nobat Dia, nobat Dia,<br/>Penyanyang orang dosa.<br/>',NULL,60624,3);
INSERT INTO stanza VALUES('I121','4','Dengarlah sorak gempita,<br/>suara kemenangan!<br/>Yesus naik paling atas,<br/>suasana menggelora!<br/>Nobat Dia, nobat Dia,<br/>Mahatinggilah Dia!<br/>',NULL,60625,4);
INSERT INTO stanza VALUES('I122','1','Pandang Yesus dalam mulia,<br/>roh kami s''gra menyembah,<br/>Sambil kenangkan kisah-Nya<br/>terhina dalam dunia.<br/>',NULL,60626,1);
INSERT INTO stanza VALUES('I122','2','Kau dihina tak terkira,<br/>orang du-nia bersorak;<br/>Kini nyata dalam mu-lia,<br/>sengsara-Mu tak sia-sia.<br/>',NULL,60627,2);
INSERT INTO stanza VALUES('I122','3','Waktu Engkau disalibkan,<br/>sepi tia-da simpati;<br/>Kini kami s''mua memuji,<br/>Kau t''rangkat depan Bapa.<br/>',NULL,60628,3);
INSERT INTO stanza VALUES('I122','4','Pernah Allah tak peduli,<br/>pada-Mu bu-ang muka;<br/>Dari wajah-Mu nan sedih,<br/>nyatalah mu-lia Bapa.<br/>',NULL,60629,4);
INSERT INTO stanza VALUES('I122','5','Tuhan, ingat se-mua ini,<br/>tak henti kami puji;<br/>Nya-nyian semesta berpadu:<br/>Domba Allah, Kau patut.<br/>',NULL,60630,5);
INSERT INTO stanza VALUES('I122','6','Hati kami bangun kini,<br/>Allah Bapa terpuji;<br/>Biar nya-nyian, sorak, dan cinta,<br/>bagi Bapa dan Putra.<br/>',NULL,60631,6);
INSERT INTO stanza VALUES('I123','1','Kristus Allah, Tuhan mulia,<br/>hati-Mu penuh rahmat;<br/>D''ngan segenap jiwa, hati,<br/>kami datang depan-Mu;<br/>Bersembah dan memuji,<br/>jalan-Mu sangat luhur.<br/>',NULL,60632,1);
INSERT INTO stanza VALUES('I123','2','Tuhan, Raja (Sang Terurap),<br/>dapat mulia dan bah''gia!<br/>Tapi dulu Kau terhina;<br/>Kau mau tolong, ditolak;<br/>Ku b''ri hormat dan puji,<br/>mulia, mulia s''lamanya.<br/>',NULL,60633,2);
INSERT INTO stanza VALUES('I123','3','Raja hayat pernah wafat,<br/>Pemb''ri berkat dilaknat!<br/>Kau dicinta Bapa Allah,<br/>dalam d''rita Kau taat;<br/>Ku pandang dan kenang-Mu,<br/>Kau mend''rita di dunia.<br/>',NULL,60634,3);
INSERT INTO stanza VALUES('I123','4','Kini mahkota Kau pakai,<br/>tongkat besi Kau pegang!<br/>Kristus Allah, kami s''karang<br/>tunggu Kau datang pula;<br/>Ku mau taat dan cinta,<br/>pada Kristus s''lamanya.<br/>',NULL,60635,4);
INSERT INTO stanza VALUES('I124','1','Dikau Raja di raja,<br/>siapa kami tak taat?<br/>Sang Terurap ku sembah,<br/>batin takwa pun cinta!<br/>Dikau Raja di raja,<br/>semua saleh bergita!<br/>',NULL,60636,1);
INSERT INTO stanza VALUES('I124','2','Negara sini sana,<br/>daulat-Mu yang berkuasa;<br/>Semua bangsa ''kan taat,<br/>''layani Kau Sang Raja;<br/>Dikau Raja di raja,<br/>bangsa mana tak puja?<br/>',NULL,60637,2);
INSERT INTO stanza VALUES('I124','3','Kerajaan-Mu kekal,<br/>takhta-Mu teguh s''lama!<br/>Mulia dan daulat-Mu,<br/>disanjung sampai kekal!<br/>Dikau Raja di raja,<br/>semua saleh memuja!<br/>',NULL,60638,3);
INSERT INTO stanza VALUES('I124','4','Tuhan, Raja di raja,<br/>nama-Mu ku nyanyikan!<br/>P''rintah-Mu akrab mesra,<br/>k''rajaan-Mu datanglah!<br/>Dikau Raja di raja,<br/>kini kami bergita!<br/>',NULL,60639,4);
INSERT INTO stanza VALUES('I125','1','Kau Sang Terurap Allah,<br/>Sang Raja di raja!<br/>Pada-Mu sujud sembah,<br/>lantang gita pujian!<br/>K''rajaan-Mu tak sudah,<br/>takhta-Mu tak goyah!<br/>Pem''rintahan-Mu adil,<br/>mulia tak tara.<br/>',NULL,60640,1);
INSERT INTO stanza VALUES('I125','2','Di bukit kudus Sion,<br/>Allah menetapkan,<br/>Semua bangsa bagi-Mu,<br/>pusaka nan kekal.<br/>Amanat-Nya pada-Mu,<br/>pula kuasa-Nya;<br/>Semua bangsa Kau atur,<br/>sampai selamanya.<br/>',NULL,60641,2);
INSERT INTO stanza VALUES('I125','3','Belum genap waktunya,<br/>g''lap masih berkuasa;<br/>Tetapi tetap ada,<br/>pada-Mu setia!<br/>Dari penjuru buana,<br/>umat-Mu bergita;<br/>Sembah, cinta, ''layani,<br/>Juru-s''lamat - Raja.<br/>',NULL,60642,3);
INSERT INTO stanza VALUES('I125','4','Saat tiba harinya,<br/>Sang Mulia datanglah,<br/>Bangsa-bangsa di bumi<br/>takluk sepenuhnya.<br/>Penuh terang, wibawa,<br/>Kau Raja terhormat;<br/>Tiap suku dan bangsa<br/>panjatkan pujian!<br/>',NULL,60643,4);
INSERT INTO stanza VALUES('I126','1','Alangkah agung dan mesra,<br/>cinta-Mu, ya, Tuhan!<br/>Hingga hati, jiwa, t''naga,<br/>bagi-Mu semuanya.<br/>',NULL,60644,1);
INSERT INTO stanza VALUES('I126','2','Kami cinta kepada-Mu,<br/>kar''na Kau teragung;<br/>Namun Kau rela menanggung<br/>salib, t''rima malu.<br/>',NULL,60645,2);
INSERT INTO stanza VALUES('I126','3','Kebanggaan manusia,<br/>korban bagi kawan;<br/>Kau malah mati buat lawan!<br/>Siapa lagi pernah?<br/>',NULL,60646,3);
INSERT INTO stanza VALUES('I126','4','Meski Kau-lah gambar Allah,<br/>semayam di surga;<br/>Tapi Kau rela menghamba,<br/>derita sengsara.<br/>',NULL,60647,4);
INSERT INTO stanza VALUES('I126','5','Kau rela serupa insan,<br/>(kecualilah dosa),<br/>Agar mirip-Mu ku bisa,<br/>walau dulu beda.<br/>',NULL,60648,5);
INSERT INTO stanza VALUES('I126','6','Lembut, tangguh, sep''ri Tuhan,<br/>atas segala hal!<br/>Tambah hari, tambah mulia,<br/>hingga jumpa kelak.<br/>',NULL,60649,6);
INSERT INTO stanza VALUES('I126','7','Tuhan, biarlah kasih-Mu<br/>tersirat di kalbu;<br/>Sejak kini terhadap-Mu,<br/>syukur, hormat s''lalu!<br/>',NULL,60650,7);
INSERT INTO stanza VALUES('I127','1','Yesusku Raja mulia, kasih-Nya berlimpah!<br/>Rela datang dunia, cari yang sesat;<br/>dalam malaf Ia lahir ke Mesir,<br/>Ia ''ngungsi; ke Galilea, Ia balik d''rita susah.<br/>Tiga puluh tiga ta''un terhina, sengsara;<br/>Luaskan Injil, b''ritakan kabar suka;<br/>Orang lain dilawat-Nya, diri-Nya terlupa;<br/>ajaib, indah, kasih-Nya tak terkata!<br/>',NULL,60651,1);
INSERT INTO stanza VALUES('I127','2','Yesusku Raja s''lamat, kasih-Nya dalamlah!<br/>Di Getsemani kecap pahit getir;<br/>Peluh menetes deras, taat pada Bapa;<br/>S''lamatkan dunia, sikap-Nya perkasa.<br/>Sambut segala d''rita, lawan, cambuk, ludah;<br/>Takkan undur, ke Golgota menuju;<br/>Terpaku pun tertusuk, air, darah tercucur,<br/>Ajaib, indah, kasih-Nya tak terukur!<br/>',NULL,60652,2);
INSERT INTO stanza VALUES('I127','3','Yesusku Raja menang, kasih-Nya tak batas!<br/>Terpancang pun doa-Nya mengandung sayang;<br/>Penyamun b''roleh s''lamat, nyatalah kurnia-Nya;<br/>Pikul dosa, dibuang Allah, kasi''anlah.<br/>Hati-Nya hancur luluh, p''ri cuka empedu;<br/>Tebusan g''nap, Roh terserah, Ia menang;<br/>Mati, bangkit, naik surga, p''ri sembahan wangi;<br/>Ajaib, indah, kasih-Nya tak terperi!<br/>',NULL,60653,3);
INSERT INTO stanza VALUES('I127','4','Yesusku Raja damai, kasih-Nya luar biasa!<br/>Kar''na cinta, korban ganti nan dosa;<br/>Sembuhkan nan terluka, ''nyatakan rahmat-Nya;<br/>Tegur, ''ngajar, b''ri bimbingan yang mesra.<br/>Musuh meski menyerang, tak ubah kurnia-Nya;<br/>Dengan lemah lembut aku dipapah;<br/>Terpandang Ia di surga, hati memuji sg''ra;<br/>Ajaib, indah, kasih-Nya tak terduga!<br/>',NULL,60654,4);
INSERT INTO stanza VALUES('I128','1','Depan Tuhan berlutut,<br/>kagumi kurnia-Mu,<br/>orang dosa p''ri aku,<br/>tapi Kau mau tolong.<br/>Dulu tamak ''kan dunia,<br/>Tuhan tak ku kenang,<br/>dengan kasih Kau undang,<br/>ke pangkuan-Mu datang.<br/>',NULL,60655,1);
INSERT INTO stanza VALUES('I128','2','Dulu hati p''nuh dosa,<br/>s''lalu duka m''rana,<br/>Seb''lum b''lengguku lepas,<br/>Kau s''lalu mengharap!<br/>Meski suara-Mu terd''ngar,<br/>tapi Kau ku biarkan,<br/>Bahkan s''ring menentang-Mu,<br/>menjadi musuh-Mu.<br/>',NULL,60656,2);
INSERT INTO stanza VALUES('I128','3','aku tak ta''u mengapa,<br/>laknatku Kau t''rima,<br/>Di kayu salib wafat,<br/>hingga ku sentosa!<br/>Amat banyak dosaku,<br/>hidup dalam nafsu,<br/>Ta-biat-ku sangat jahat,<br/>Kau mengapa cinta?<br/>',NULL,60657,3);
INSERT INTO stanza VALUES('I128','4','Kau lahir dalam malaf!<br/>Hidup pun merendah!<br/>Di Golgota Kau duka!<br/>Kar''naku semuanya!<br/>Mengapa Kau pandangku,<br/>dan cinta padaku?<br/>Demi ba-ha-gi-a-ku,<br/>Kau rela mend''rita?<br/>',NULL,60658,4);
INSERT INTO stanza VALUES('I128','5','Daripada orang lain,<br/>aku tak lebih baik,<br/>Bagiku Kau terlahir,<br/>dan mati disalib.<br/>Tuhan, kalau ku pikir,<br/>aku tia-da bajik,<br/>api Kau sangat kasih,<br/>ku merasa a-jaib!<br/>',NULL,60659,5);
INSERT INTO stanza VALUES('I128','6','Tak lain aku berkata,<br/>"Kasih-Mu tak sebab!"<br/>Ya, kasih-Mu tak sebab,<br/>kur-nia-Mu a-jaib-lah!<br/>Bukan kar''na aku baik,<br/>bermartabat tinggi,<br/>Hanya belas kasih-Mu<br/>pada orang dosa.<br/>',NULL,60660,6);
INSERT INTO stanza VALUES('I128','7','Kur-nia-Mu t''lah ku t''rima,<br/>ku harus mengabdi,<br/>Cinta, ta-at pada-Mu,<br/>baru Kau s''nang hati.<br/>Tapi sungguhlah sayang,<br/>hati tetap hambar!<br/>Meski ku ta''u kasih-Mu,<br/>pada-Mu tak gairah!<br/>',NULL,60661,7);
INSERT INTO stanza VALUES('I128','8','Meski Kau t''lah berkorban,<br/>tapi ku a-bai-kan;<br/>Meski surga Kau tinggal,<br/>Kau tak ku indahkan.<br/>Ku sayang bu-ang du-nia,<br/>ta''u jalan-Mu sukar,<br/>Ku manjakan diriku,<br/>meski Kau mend''rita.<br/>',NULL,60662,8);
INSERT INTO stanza VALUES('I128','9','Waktu ku pikir s''muanya,<br/>hatiku kecewa,<br/>Ta-biat-ku sangat jahat,<br/>hidupku buruklah.<br/>Tapi Tuhan t''lah tahu,<br/>hatiku de-mi-kian,<br/>Tau ta''u hatiku hambar,<br/>mengapa Kau cinta?<br/>',NULL,60663,9);
INSERT INTO stanza VALUES('I128','10','Kau korbankan jiwa-Mu,<br/>tanggung s''mua dosaku,<br/>D''rita s''gala celaka,<br/>ku balas d''ngan hambar!<br/>Bila Kau ta''u de-mi-kian,<br/>mengapa berkorban?<br/>Kau ta''u ku tidak patut,<br/>mengapa Kau tebus?<br/>',NULL,60664,10);
INSERT INTO stanza VALUES('I128','11','Se-b''lum-nya Kau sudah ta''u,<br/>hatiku ''kan ubah,<br/>Tapi Kau tetap cinta,<br/>mati, hidup buat-ku.<br/>Bila ingat kasih-Mu,<br/>hatiku terharu,<br/>Puji syukur pada-Mu,<br/>besarlah budi-Mu!<br/>',NULL,60665,11);
INSERT INTO stanza VALUES('I128','12','T''radap cinta kasih-Mu,<br/>tak pahamlah aku,<br/>Hatiku amat kagum,<br/>datanglah bersujud.<br/>Biar surga amat indah,<br/>hatiku tak t''rikat,<br/>Ku mau jadi penyanyi,<br/>Tuhan yang ku puji.<br/>',NULL,60666,12);
INSERT INTO stanza VALUES('I128','13','Dalam tempat mu-lia-Mu,<br/>Kau ku puji s''lalu.<br/>Ku syukur ''kan kur-nia-Mu,<br/>bersembah pada-Mu.<br/>Moga di rumah surga,<br/>jadi t''ladan cinta,<br/>S''mua tak dapat ku balas,<br/>pu-jian-ku bertambah!<br/>',NULL,60667,13);
INSERT INTO stanza VALUES('I129','1','Aku punya Juru-s''lamat,<br/>yang kasih-Nya tak terkira;<br/>Lebih dalam dari lautan,<br/>lebih tinggi dari surga;<br/>S''lalu segar,<br/>lagi mesra,<br/>siang malam tidak beda;<br/>Pujilah! Aku Dia cinta!<br/>',NULL,60668,1);
INSERT INTO stanza VALUES('I129','2','Dalam surga Dia terhormat,<br/>tent''ra surga s''mua bersembah;<br/>Kar''na cinta yang amat kuat,<br/>tinggalkan takhta mu-li-a;<br/>Cari domba<br/>yang tersesat,<br/>korbankan nikmat ba-ha-gia;<br/>Pu-ji-lah! Aku Dia cari!<br/>',NULL,60669,2);
INSERT INTO stanza VALUES('I129','3','Jalan Tuhan sungguh senyap,<br/>tia-da kawan, tia-da teman;<br/>Se-mua c''laka dan d''rita-Nya,<br/>yang ta''u hanya Allah dan Dia;<br/>Tapi tetap<br/>majulah Dia,<br/>hingga aku Dia dapatkan;<br/>Pu-ji-lah! Aku Dia jumpa!<br/>',NULL,60670,3);
INSERT INTO stanza VALUES('I129','4','Tak lama harinya tiba,<br/>Dia di-ju-al dan digugat;<br/>Tanpa teman Dia mend''rita:<br/>cambuk, duri, hina, cerca;<br/>Bagi aku ke Golgota,<br/>sakit, pedih,<br/>''nyengat tulang;<br/>Pu-ji-lah! Aku t''lah s''lamat!<br/>',NULL,60671,4);
INSERT INTO stanza VALUES('I129','5','Selamanya ku kisahkan:<br/>kasih Tuhan amat megah!<br/>Hari itu ku terangkat,<br/>tinggal dalam rumah Bapa;<br/>Yang ku ingin jumpa Tuhan,<br/>nyanyi, puji,<br/>menyembah Dia;<br/>Pu-ji-lah! Tuhan ku cinta!<br/>',NULL,60672,5);
INSERT INTO stanza VALUES('I130','1','Kasih-Mu alangkah luas,<br/>melampaui dugaan!<br/>Lebih dalam dari lautan,<br/>atasku nimpa jua!<br/>Kasih membuat Kau berkorban,<br/>agar Kau ku dapatkan;<br/>Kasih membuat kita esa,<br/>bagian-Mu ku jadinya.<br/>',NULL,60673,1);
INSERT INTO stanza VALUES('I130','2','Budi kasih-Mu banyaklah,<br/>tak habis terutara!<br/>Namun yang paling utama,<br/>denganku ba-ur esa.<br/>Diri-Mu jadi milikku,<br/>s''galaku terjamin s''mua;<br/>Biar ku tia-sa nikmat saja,<br/>diri-Mu jadi hayat.<br/>',NULL,60674,2);
INSERT INTO stanza VALUES('I130','3','Kasih itulah diri-Mu,<br/>diri Sang Mahakudus;<br/>Menjadi makna hidupku,<br/>hidupku adalah Kau.<br/>Dikau hayat, tenagaku,<br/>ku alami kasih-Mu;<br/>Aku sasaran kasih-Mu,<br/>Dikau pengalamanku.<br/>',NULL,60675,3);
INSERT INTO stanza VALUES('I130','4','Apa gerangan pemisah?<br/>Takkan sudah kasih-Mu!<br/>Sampai kekal esa kita,<br/>tia-da lawan kasih-Mu!<br/>Kasih-Mu buat ku bersyukur,<br/>jadi tu-juan pu-jian-ku!<br/>kau jadi ku, ku jadi Kau,<br/>''nilah puncak kasih-Mu!<br/>',NULL,60676,4);
INSERT INTO stanza VALUES('I131','1','Tuhan, waktu ku berk''lana,<br/>Kau cari dengan cinta,<br/>Rela mend''rita sengsara<br/>pimpinku dengan sabar.<br/>Jiwaku, ''nilah cinta:<br/>bagimu Dia berkorban.<br/>',NULL,60677,1);
INSERT INTO stanza VALUES('I131','2','Dengarlah, ratapan siapa,<br/>dalam taman yang senyap?<br/>''Nilah Tuhan sedang jaga,<br/>walau murid-Nya lelap.<br/>Jiwaku, ''nilah cinta:<br/>bagimu Dia mend''rita.<br/>',NULL,60678,2);
INSERT INTO stanza VALUES('I131','3','Lihat! Tuhan se-dang berdoa,<br/>t''rima cawan murka-Nya,<br/>Tak lain bagi orang dosa,<br/>Tuhan rela minumnya.<br/>Jiwaku, ''nilah cinta:<br/>bagimu Dia tersiksa.<br/>',NULL,60679,3);
INSERT INTO stanza VALUES('I131','4','Tak lama kejam menimpa,<br/>murka Allah melanda.<br/>Menerjang dan menerkam Dia,<br/>biar ku jadi milik-Nya.<br/>Kasih ini terunggul:<br/>Yesus mati gantiku.<br/>',NULL,60680,4);
INSERT INTO stanza VALUES('I131','5','Dengar! Jeritan-Nya lagi,<br/>waktu Bapa menyingkir,<br/>Allah, m''ngapa Kau tegakan,<br/>pada Putra yang ta-at?<br/>Jiwaku, ''nilah cinta:<br/>bagimu Dia terhempas.<br/>',NULL,60681,5);
INSERT INTO stanza VALUES('I131','6','Tuhan, kini agu girang,<br/>kar''na d''ritamu lewat,<br/>Kau naik surga, duduk takhta,<br/>hidup t''rus hingga kekal.<br/>Yang berkorban untukku:<br/>jiwaku s''mua bagi-Mu.<br/>',NULL,60682,6);
INSERT INTO stanza VALUES('I131','7','Tuhan, karena kur-nia-Mu,<br/>pada-Mu ku bersujud;<br/>Seg''ra ku disempurnakan,<br/>jumpa Tuhan dengan riang.<br/>Kini kami berkidung:<br/>Yesus mati bagiku.<br/>',NULL,60683,7);
INSERT INTO stanza VALUES('I132','1','Panjang tiada ujungnya,<br/>luas tiada batasnya,<br/>Tinggi tiada puncaknya,<br/>dalam tiada dasarnya,<br/>Kasih Kristus!<br/>',NULL,60684,1);
INSERT INTO stanza VALUES('I132','chorus','Agung, maha agung!<br/>Kasih Kristus!<br/>Mustahillah terukur,<br/>menimpa kepadaku hingga kekal!<br/>',NULL,60685,2);
INSERT INTO stanza VALUES('I132','2','Panjang: sudi berkorban,<br/>lu-as: sudi s''lamatkan,<br/>Tinggi: ku diangkat-Nya,<br/>dalam: hayat ku dapat,<br/>Kasih Kristus!<br/>',NULL,60686,3);
INSERT INTO stanza VALUES('I132','3','Panjang: beri ampunan,<br/>luas: beri anug''rah,<br/>Tinggi: duduk di surga,<br/>dalam: hidup serta-Nya,<br/>Kasih Kristus!<br/>',NULL,60687,4);
INSERT INTO stanza VALUES('I132','4','Panjang bukan matranya,<br/>luas bukan ukurnya,<br/>Tinggi, dalam pun tidak,<br/>itu ibarat saja,<br/>Kasih Kristus!<br/>',NULL,60688,5);
INSERT INTO stanza VALUES('I133','1','Dia unggul dari s''galanya,<br/>oh, kasih-Nya!<br/>Lebih ''rat dari saudara,<br/>oh, kasih-Nya!<br/>Teman sering meninggalkan,<br/>kini baik, esok benci,<br/>Tapi Dia tetap sertaku,<br/>oh, kasih-Nya.<br/>',NULL,60689,1);
INSERT INTO stanza VALUES('I133','2','Kini bah''gia ku nikmati,<br/>oh, kasih-Nya!<br/>Hutang dosa Dia lunasi,<br/>oh, kasih-Nya!<br/>Darah-Nya, t''lah menebusku,<br/>Dia datang mencari aku,<br/>Dipimpin-Nya ku berpaling,<br/>oh, kasih-Nya!<br/>',NULL,60690,2);
INSERT INTO stanza VALUES('I133','3','Yesus ia-lah teman kami,<br/>oh, kasih-Nya!<br/>Berkat ba-ha-gia Dia beri,<br/>oh, kasih-Nya!<br/>Kini ku pandang wajah-Nya,<br/>dengan tent''ram ku serta-Nya,<br/>mana mungkin ku tentang Dia,<br/>oh, kasih-Nya!<br/>',NULL,60691,3);
INSERT INTO stanza VALUES('I133','4','Ku di-am-pun-i demi Dia,<br/>oh, kasih-Nya!<br/>Depan musuh kami pesta,<br/>oh, kasih-Nya!<br/>Dia b''rikan ba-gian yang terbaik,<br/>s''gala c''laka Dia yang tolak,<br/>ke tempat mu-lia Dia pimpin,<br/>oh, kasih-Nya!<br/>',NULL,60692,4);
INSERT INTO stanza VALUES('I134','1','Kasih-Mu melampaui dugaan,<br/>Ya, Tuhanku, buatlah ku tahu,<br/>Panjang, lebar, tinggi, dan dalamnya,<br/>Agar kekuatannya makin nyata atas daku.<br/>',NULL,60693,1);
INSERT INTO stanza VALUES('I134','2','Kasih-Mu tak habis terutara,<br/>Ya, Tuhanku, bukalah mulutku,<br/>Beritakan kepada yang dosa,<br/>Kasih-Mu lenyapkan ketakutan, pun b''ri ri-ang!<br/>',NULL,60694,2);
INSERT INTO stanza VALUES('I134','3','Kasih-Mu tak habis dinyanyikan,<br/>Ya, Tuhanku, gugahlah hatiku,<br/>Memuji kasih nan kaya limpah,<br/>Yang membawa orang dosa p''ri-ku dekat Allah!<br/>',NULL,60695,3);
INSERT INTO stanza VALUES('I134','4','Meski aku tak mampu kisahkan,<br/>Kepenuhan kasih-Mu, ya, Tuhan,<br/>Namun wadah yang hampa ku bawa,<br/>Mohon Dikau, sumber hayat, kasih, penuhiku!<br/>',NULL,60696,4);
INSERT INTO stanza VALUES('I134','5','Aku sungguh bejana yang hampa,<br/>Tak pernah pada-Mu jatuh cinta,<br/>Namun ku dapat datang pada-Mu,<br/>Mohon belas kasih, kur-nia, kar''na Kau cintaku!<br/>',NULL,60697,5);
INSERT INTO stanza VALUES('I134','6','Penuhiku d''ngan kasih-Mu, Tuhan,<br/>Bawaku ke mata a-ir hayat,<br/>Dengan iman ku datang ke sana,<br/>Sandar, kecap, menikmati Dikau, la-in tia-da!<br/>',NULL,60698,6);
INSERT INTO stanza VALUES('I134','7','Sa-at bertatap muka, ya, Tuhan,<br/>ku duduk beserta-Mu di takhta,<br/>dengan takjub kasih-Mu ku puja,<br/>panjang, lebar, tinggi, dalam, kekal, selamanya!<br/>',NULL,60699,7);
INSERT INTO stanza VALUES('I135','1','Moga ku berlidah s''laksa,<br/>puji Juru-s''la-mat;<br/>Kisah-kan kurnia-Nya besar,<br/>mulia lagi kaya.<br/>',NULL,60700,1);
INSERT INTO stanza VALUES('I135','2','Nama Yesus hibur duka,<br/>hilangkan kesepian;<br/>Brikan hayat dan sentosa,<br/>hingga ku bergita.<br/>',NULL,60701,2);
INSERT INTO stanza VALUES('I135','3','Kar''na cinta-Nya padalu,<br/>rela t''rima c''laka;<br/>Dia musnahkan kuasa dosa,<br/>s''lamatlah jiwaku.<br/>',NULL,60702,3);
INSERT INTO stanza VALUES('I135','4','Tiap ingat kasih P''nolongku,<br/>ku rasa tak patut;<br/>Mengapa pada yang dosa,<br/>Dia curahkan sayang?<br/>',NULL,60703,4);
INSERT INTO stanza VALUES('I135','5','Ku jadi budak cinta-Nya,<br/>tak harap merdeka;<br/>Kar''na bagiku Dia mati,<br/>terhina di salib.<br/>',NULL,60704,5);
INSERT INTO stanza VALUES('I135','6','Nama-Mu penuh simpati,<br/>dan mengandung kasih;<br/>Bila ku berhati s''laksa,<br/>pada-Mu belaka.<br/>',NULL,60705,6);
INSERT INTO stanza VALUES('I136','1','Kami pada datang<br/>dengan hati girang;<br/>Berkidung kasih yang ajaib,<br/>datang depan takhta.<br/>',NULL,60706,1);
INSERT INTO stanza VALUES('I136','chorus','Girang kar''na kurnia!<br/>Kurnia cuma-cuma!<br/>Dengan sempurna ku diampuni<br/>demi kurnia!<br/>',NULL,60707,2);
INSERT INTO stanza VALUES('I136','2','Yang b''lum kenal Tuhan,<br/>biar diam s''ribu bah''sa;<br/>Umat-Nya yang t''rima berkat,<br/>harus bersorak riang.<br/>',NULL,60708,3);
INSERT INTO stanza VALUES('I136','3','Girang kami rasa,<br/>kar''na kami ingat;<br/>Kota-Nya indah dan mu-lia,<br/>jalannya dari ''mas.<br/>',NULL,60709,4);
INSERT INTO stanza VALUES('I136','4','Nyanyilah d''ngan merdu,<br/>bu-ang-lah s''mua duka;<br/>Penuh harap kami maju<br/>ke tempat yang mu-lia.<br/>',NULL,60710,5);
INSERT INTO stanza VALUES('I137','1','Mulia, hormat, Dia korbankan<br/>datang dunia merendah.<br/>Getir salib dikecap-Nya,<br/>s''mua dosa dipikul-Nya.<br/>',NULL,60711,1);
INSERT INTO stanza VALUES('I137','chorus','Kurnia tak tara,<br/>tidak terbalas,<br/>Kini seluruh kasihku<br/>hanya pada-Nya.<br/>',NULL,60712,2);
INSERT INTO stanza VALUES('I138','1','Tuhan, Kau-lah mustika,<br/>''kenan, pili''an Allah!<br/>Kau diurapi Allah,<br/>melebihi teman.<br/>',NULL,60713,1);
INSERT INTO stanza VALUES('I138','chorus','Hati kami terpikat<br/>pada s''mua indah-Mu,<br/>s''mua harum semerbak-Mu,<br/>s''mua kemanisan-Mu.<br/>',NULL,60714,2);
INSERT INTO stanza VALUES('I138','2','Lebih cantik dari s''mua,<br/>Kau betapa elok;<br/>Mulut-Mu penuh kur-nia,<br/>kami s''lalu cinta.<br/>',NULL,60715,3);
INSERT INTO stanza VALUES('I138','3','Kau lahir, majus sembah,<br/>di-su-kai ma-nu-sia;<br/>Kau mati dirempahi,<br/>Kau tetap terindah.<br/>',NULL,60716,4);
INSERT INTO stanza VALUES('I138','4','Kepala dan kaki-Mu,<br/>pernah di-u-rap-i;<br/>Se-mua apa ada-Mu,<br/>eloklah melulu.<br/>',NULL,60717,5);
INSERT INTO stanza VALUES('I138','5','Wafat-Mu laksana mur,<br/>hibur hati dan roh;<br/>Bangkit-Mu p''ri ukupan,<br/>puas-kan hati Allah.<br/>',NULL,60718,6);
INSERT INTO stanza VALUES('I138','6','Harum-Mu seperti mur,<br/>cantik-Mu p''ri tabo;<br/>Pula p''ri pohon apel,<br/>lebat, manis buah-nya.<br/>',NULL,60719,7);
INSERT INTO stanza VALUES('I138','7','Kasih-Mu elok unggul,<br/>nama-Mu terindah!<br/>Kau betapa mustika,<br/>s''lalu kami kenang.<br/>',NULL,60720,8);
INSERT INTO stanza VALUES('I138','8','Bila kami mengenang,<br/>s''mua ke-in-dah-an-Mu,<br/>Kami makin nikmati,<br/>s''mua kemanisan-Mu!<br/>',NULL,60721,9);
INSERT INTO stanza VALUES('I139','1','"Manis" menghias dahi-Nya,<br/>ilahi, wibawa;<br/>Kepala pancarkan mulia,<br/>mulut luap kurnia.<br/>Mulut luap kurnia.<br/>',NULL,60722,1);
INSERT INTO stanza VALUES('I139','2','Insan fana di buana,<br/>bukan bandingan-Nya,<br/>Semua malak, tent''ra surga,<br/>tak seindah Dia.<br/>Tak seindah Dia.<br/>',NULL,60723,2);
INSERT INTO stanza VALUES('I139','3','Dia-lah hayat dan nafasku<br/>pun sukacitaku;<br/>Ku menang ''tas kuasa maut,<br/>lepas cengk''ram kubur.<br/>Lepas cengk''ram kubur.<br/>',NULL,60724,3);
INSERT INTO stanza VALUES('I139','4','Pada Bapa - kediamanku,<br/>Dia bimbing langkahku;<br/>Mulia-Nya nyata padaku,<br/>penuhlah riangku.<br/>Penuhlah riangku.<br/>',NULL,60725,4);
INSERT INTO stanza VALUES('I139','5','Kurnia limpah menyatakan<br/>kasih-Nya yang besar;<br/>Andai ku berhati s''laksa,<br/>semua bagi-Nya.<br/>Semua bagi-Nya.<br/>',NULL,60726,5);
INSERT INTO stanza VALUES('I140','1','Tuhan, Dikau-lah Mempelai,<br/>Allah pilih, ku sayang;<br/>Diri-Mu sangat memikat,<br/>tak mungkin tak ku cinta.<br/>',NULL,60727,1);
INSERT INTO stanza VALUES('I140','2','Sang Kekasih nan ku sayang,<br/>adil-Mu tak terkisah!<br/>Asmara-mu mesra amat,<br/>elok-Mu tak terkata!<br/>',NULL,60728,2);
INSERT INTO stanza VALUES('I140','3','Tampan-Mu tiada lawan,<br/>manis-Mu tiada tara!<br/>Lemah lembut, mesra akrab,<br/>memang sungguh sempurna!<br/>',NULL,60729,3);
INSERT INTO stanza VALUES('I140','4','Mur memenuhi jubah-Mu,<br/>kurnia di mulut-Mu!<br/>Di aroma sengsara-Mu,<br/>d''ngan cinta Kau ku peluk.<br/>',NULL,60730,4);
INSERT INTO stanza VALUES('I140','5','Kau terurap minyak ria,<br/>melebihilah kawan;<br/>"Istana Gading" terdengar,<br/>puji sorak gempita.<br/>',NULL,60731,5);
INSERT INTO stanza VALUES('I140','6','Allah berkati tak sudah,<br/>jaya terhadap lawan:<br/>Ternobat dan naik takhta,<br/>kuasa daulat tak tara.<br/>',NULL,60732,6);
INSERT INTO stanza VALUES('I140','7','Dikau dambaan s''mua bangsa,<br/>adi-Mu m''reka paham;<br/>Melampaui segalanya,<br/>ku puja selamanya!<br/>',NULL,60733,7);
INSERT INTO stanza VALUES('I141','1','Betapa manis hatiku<br/>setiap ingat Yesus;<br/>Moga ku seg''ra terangkat,<br/>beserta pada-Mu.<br/>',NULL,60734,1);
INSERT INTO stanza VALUES('I141','chorus','Cantik-Mu pri tabo yang indah,<br/>yang mekar di kebun anggur.<br/>Indah permai tak terkata,<br/>memikat hatiku.<br/>',NULL,60735,2);
INSERT INTO stanza VALUES('I141','2','Tiada suara cukup merdu,<br/>nyanyi g''nap kurnia-Mu;<br/>Tiada hati cukup peka,<br/>nikmati kasih-Mu.<br/>',NULL,60736,3);
INSERT INTO stanza VALUES('I141','3','Tapi yang paling ku gemar<br/>bukan ini m''lulu;<br/>M''lainkan diri-Mu yang manis,<br/>memuaskan hatiku.<br/>',NULL,60737,4);
INSERT INTO stanza VALUES('I141','4','Kau tercantik dan termanis<br/>dari segalanya;<br/>Di surga maupun di bumi,<br/>Kau saja ku damba.<br/>',NULL,60738,5);
INSERT INTO stanza VALUES('I142','1','Nyaman sep''ri angin sepoi,<br/>tak henti ku hirup!<br/>Harum tiadalah saing,<br/>laksana mur di dadaku.<br/>P''ri minyak surgawi,<br/>p''ri minyak surgawi!<br/>',NULL,60739,1);
INSERT INTO stanza VALUES('I142','2','Sejuk sep''ri embun pagi,<br/>tak jemu ku sesap!<br/>Segar, nyaman, basa''i batin,<br/>diris hati dan kalbuku.<br/>Mohon Kau celupkan<br/>diriku ke dalam!<br/>',NULL,60740,2);
INSERT INTO stanza VALUES('I142','3','Antara s''mua, Kau tercantik,<br/>tak bosan ku pandang!<br/>Wajah-Mu berpancar cantik,<br/>kian menawan perasaan;<br/>Dikaulah tercantik!<br/>Dikaulah tercantik!<br/>',NULL,60741,3);
INSERT INTO stanza VALUES('I142','4','Terunggul, manis, nama-Mu,<br/>tak penat ku nyanyi!<br/>Hatiku p''nuh rasa manis,<br/>memuji-Mu tiada henti.<br/>Batinku tergenang<br/>oleh sukacita.<br/>',NULL,60742,4);
INSERT INTO stanza VALUES('I142','5','Diri-Mu-lah paling unggul,<br/>tak habis ku tutur!<br/>Simpatik dan lemah lembut,<br/>menarikku bersandar-Mu.<br/>Cukuplah kar''na Kau!<br/>Cukuplah kar''na Kau!<br/>',NULL,60743,5);
INSERT INTO stanza VALUES('I143','1','Yesus terindah!<br/>Penguasa alam!<br/>Putra Allah pun manusia!<br/>Firman nan kekal,<br/>paling ku sayang;<br/>banggaku dan gembiraku!<br/>',NULL,60744,1);
INSERT INTO stanza VALUES('I143','2','Rumput dan pohon,<br/>memang hijau segar!<br/>Bunga mekar lomba elok!<br/>Yesus terelok!<br/>Yesus terindah!<br/>Hati susah jadi senang!<br/>',NULL,60745,2);
INSERT INTO stanza VALUES('I143','3','Surya benderang!<br/>Bulan pun purnama!<br/>Bintang-bintang gemerlapan!<br/>Yesus lebih t''rang!<br/>Yesus lebih c''rah!<br/>Melebihi semuanya!<br/>',NULL,60746,3);
INSERT INTO stanza VALUES('I143','4','Permai di langit,<br/>pun permai di bumi,<br/>Pada-Mu bulat tertilik;<br/>Paling menarik,<br/>pun paling manis!<br/>Unggul, tiada lawan tanding!<br/>',NULL,60747,4);
INSERT INTO stanza VALUES('I144','1','Dari mana ku kisahkan,<br/>s''gala bah''gia yang Dia b''rikan?<br/>Lepas dosa tak tertawan,<br/>singkirkan maut, jadi kawan;<br/>bagaimana ku b''ri hormat,<br/>junjung Tuhan baru tepat?<br/>',NULL,60748,1);
INSERT INTO stanza VALUES('I144','2','Rawatan dan asuhan-Mu,<br/>mana mungkin ku kisahkan?<br/>Anak dosa harus musnah,<br/>tapi Bapa beri berkat!<br/>Ku ta''u dosa t''lah terhapus,<br/>kini ku nikmati surga.<br/>',NULL,60749,2);
INSERT INTO stanza VALUES('I144','3','Hatiku p''nuh dengan Kristus,<br/>dan segala k''limpahan-Nya;<br/>Dia-lah judul nyanyianku,<br/>Dia-lah P''nolong yang ku cinta;<br/>Dia-lah Raja yang teragung,<br/>yang s''lalu ku puja sembah.<br/>',NULL,60750,3);
INSERT INTO stanza VALUES('I144','4','Lebih indah, lebih kudus,<br/>daripada semua makhluk; Kasih,<br/>kurnia, s''mua pada-Mu,<br/>dosaku s''mua Kau yang tanggung;<br/>Kau-lah patut t''rima puji,<br/>ku sembah Kau dengan bakti!<br/>',NULL,60751,4);
INSERT INTO stanza VALUES('I145','1','Juru-s''lamat ajaib,<br/>Raja di raja!<br/>Malaikat menyembah,<br/>kami memuja.<br/>Pengakuan surga:<br/>Dikau terindah!<br/>Kami pun senada,<br/>Dikau terindah!<br/>',NULL,60752,1);
INSERT INTO stanza VALUES('I145','2','Semua nyaman dunia,<br/>hampa semata;<br/>Tanpa Kau di surga,<br/>gelap jadinya.<br/>Kristus, mulia-Mu,<br/>terang di surga;<br/>Yesus, mulia-Mu,<br/>terang di buana.<br/>',NULL,60753,2);
INSERT INTO stanza VALUES('I145','3','Terpisah dengan-Mu,<br/>hidup jadi maut;<br/>Bersama hadir-Mu,<br/>maut jadi hidup.<br/>Dunia, insan, malak,<br/>Kau Penciptanya;<br/>Namun Kau merendah,<br/>kenakan insan.<br/>',NULL,60754,3);
INSERT INTO stanza VALUES('I145','4','Semua kebajikan,<br/>pada diri-Mu;<br/>Cah''ya mulia Allah,<br/>tak lain diri-Mu.<br/>Memandang wajah-Mu,<br/>itu kurnia-Mu;<br/>Semoga kurnia-Mu,<br/>jadi bagianku.<br/>',NULL,60755,4);
INSERT INTO stanza VALUES('I146','1','Marilah semua bersorak,<br/>puji Kristus Allah!<br/>Jika ku berlidah s''laksa, judul satu saja.<br/>',NULL,60756,1);
INSERT INTO stanza VALUES('I146','2','Ya, Domba, Kau memang patut,<br/>t''rima s''gala pujian;<br/>Kami bers''ru Kau-lah patut,<br/>kar''na Kau merendah!<br/>',NULL,60757,2);
INSERT INTO stanza VALUES('I146','3','Tuhan Yesus patut t''rima,<br/>hormat, kuasa, mulia;<br/>Masih banyak b''lum tersembah,<br/>tapi bagi-Mu s''mua!<br/>',NULL,60758,3);
INSERT INTO stanza VALUES('I146','4','Tak lama Kristen terangkat,<br/>nyanyikan pujian;<br/>S''mua makhluk di bawah langit,<br/>bersorak tak henti!<br/>',NULL,60759,4);
INSERT INTO stanza VALUES('I146','5','Sedunia akan sehati,<br/>puji Domba Suci;<br/>Yang t''lah mati, tebus kami;<br/>bangkit, mulia kini!<br/>',NULL,60760,5);
INSERT INTO stanza VALUES('I147','1','Mulia bagi Tuhan!<br/>Alam s''mesta bers''ru,<br/>"Puji Tuhan!"<br/>Kurnia dan kasih-Nya,<br/>tumpas maut dan duka;<br/>Bers''ru hingga kekal,<br/>"Domba patut."<br/>',NULL,60761,1);
INSERT INTO stanza VALUES('I147','2','Yang dicinta datang,<br/>sujud depan takhta,<br/>puji Tuhan!<br/>Darah-Nya bagiku<br/>pendamai d''ngan Allah;<br/>G''nap penjuru bers''ru,<br/>"Domba patut!"<br/>',NULL,60762,2);
INSERT INTO stanza VALUES('I147','3','Yang tertebus datang,<br/>sehati bersujud,<br/>puji Tuhan!<br/>Bergirang kar''na Dia,<br/>serentak berseru,<br/>Dan memuji-muji,<br/>"Domba patut!"<br/>',NULL,60763,3);
INSERT INTO stanza VALUES('I147','4','Meski s''gala ubah,<br/>ku tetap tak ubah,<br/>puji Tuhan!<br/>Tak henti ku puji,<br/>Tuhanku, Rajaku;<br/>S''ruanku melangit,<br/>"Domba patut!"<br/>',NULL,60764,4);
INSERT INTO stanza VALUES('I148','1','Tuhan Yesus,<br/>hatiku ke takhta-Mu,<br/>dengan girang<br/>ku sampaikan pujian!<br/>T''rima berkat,<br/>ku sembah dan kisahkan,<br/>Tuhan patut!<br/>Hanya Kau yang patut!<br/>',NULL,60765,1);
INSERT INTO stanza VALUES('I148','chorus','Tuhan, Kau patut!<br/>Tuhan, Kau patut!<br/>T''rima pujian,<br/>hanya Kau yang patut!<br/>T''rima berkat,<br/>ku sembah dan kisahkan,<br/>Tuhan patut dapat kemuliaan!<br/>',NULL,60766,2);
INSERT INTO stanza VALUES('I148','2','Dikau Allah<br/>s''jati dan insan s''jati,<br/>Jadi kurban<br/>merendahkan diri,<br/>Benih dara<br/>turun ke atas bumi,<br/>Hancur remukkan<br/>kepala ular!<br/>',NULL,60767,3);
INSERT INTO stanza VALUES('I148','3','Tuhan Khalik<br/>rela terima mati,<br/>Merendah diri,<br/>bahkan tersalib!<br/>Kau dibuang,<br/>tiada tolong diri,<br/>Tidak undur<br/>dari cawan pahit!<br/>',NULL,60768,4);
INSERT INTO stanza VALUES('I148','4','Penghulu maut<br/>sudahlah tertaklukkan,<br/>Dikau menang,<br/>menang dengan mutlak!<br/>Ingat ini,<br/>mustahil tak bersorak!<br/>Pintu alam<br/>maut sudah hancur s''mua!<br/>',NULL,60769,5);
INSERT INTO stanza VALUES('I149','1','Tuhan Yesus, Kau-lah patut<br/>t''rima sembah dan sujud;<br/>Cinta dan kasih kurnia-Mu,<br/>lampaui pikiranku.<br/>',NULL,60770,1);
INSERT INTO stanza VALUES('I149','2','Hatiku penuhlah syukur,<br/>datang puji nama-Mu;<br/>Seumurku p''nuh kurnia-Mu,<br/>ku masyhurkan budi-Mu.<br/>',NULL,60771,2);
INSERT INTO stanza VALUES('I149','3','Tuhan Yesus yang ku sembah,<br/>Engkau Maha-pemurah;<br/>Kasih-Mu p''ri tenaga-Mu,<br/>kekal, tidak berubah.<br/>',NULL,60772,3);
INSERT INTO stanza VALUES('I149','4','Yesus, Kau Awal dan Akhir,<br/>ku selalu Kau pimpin;<br/>Ku puji untuk yang sudah,<br/>untuk k''lak ku bersandar.<br/>',NULL,60773,4);
INSERT INTO stanza VALUES('I149','5','Puji! Puji! Sang Perahmat!<br/>Kaum saleh angkat suara!<br/>Puji! Puji sampai surga!<br/>Puji dengan sempurna.<br/>',NULL,60774,5);
INSERT INTO stanza VALUES('I150','1','Tuhan, Kau sungguh almuhit,<br/>kami di dalam-Mu!<br/>Dikau bagian kekal kami,<br/>Kau-lah segalaku.<br/>',NULL,60775,1);
INSERT INTO stanza VALUES('I150','2','Dikau jadi hikmat kami,<br/>oleh-Mu ku s''lamat;<br/>Jalan unik kes''lamatan<br/>dan berkat kurnia!<br/>',NULL,60776,2);
INSERT INTO stanza VALUES('I150','3','Dikau jadi adil kami,<br/>puaskan tuntutan-Nya;<br/>Di dalam-Mu dibenarkan,<br/>tak lagi digugat.<br/>',NULL,60777,3);
INSERT INTO stanza VALUES('I150','4','Dikau jadi kudus kami,<br/>untuk ubah kami;<br/>Di dalam-Mu dikuduskan,<br/>dengan-Mu tak beda.<br/>',NULL,60778,4);
INSERT INTO stanza VALUES('I150','5','Dikau jadi tebusanku,<br/>biar kami s''rupa-Mu;<br/>Kau ''kan ubah tubuh kami,<br/>secorak dengan-Mu.<br/>',NULL,60779,5);
INSERT INTO stanza VALUES('I150','6','Tuhan, saat kami kenang,<br/>nikmati ada-Mu;<br/>Kami mengharap balik-Mu,<br/>tanpa tunda waktu.<br/>',NULL,60780,6);
INSERT INTO stanza VALUES('I150','7','Pengecapan ini manis,<br/>memuaskan kalbu;<br/>Beserta-Mu damba kami,<br/>nikmati diri-Mu.<br/>',NULL,60781,7);
INSERT INTO stanza VALUES('I151','1','Batu rohani nan kekal,<br/>t''lah terbelah bagiku;<br/>Dalam roh minum air hayat,<br/>padu esa dengan-Mu.<br/>Batu kekal kokoh kuat,<br/>atas-Nya ku dibangun;<br/>Tertebus, dengan Kau esa,<br/>tak lagi goyah ragu!<br/>',NULL,60782,1);
INSERT INTO stanza VALUES('I151','chorus','Nilai-Mu mustika unggul,<br/>bagi kami ada-Mu;<br/>Kini kami mengenang-Mu,<br/>penuh nikmat kaya-Mu.<br/>',NULL,60783,2);
INSERT INTO stanza VALUES('I151','2','Batu yang lulus ujian,<br/>Allah kenan, ku sayang;<br/>Amat tangguh, amat handal,<br/>kuat kekal tak ubah.<br/>Pula batu hidup kekal,<br/>Allah pilih bagiku;<br/>Sungguh tegar, sungguh kukuh,<br/>hayat limpah bagianku.<br/>',NULL,60784,3);
INSERT INTO stanza VALUES('I151','3','Dikau juga batu dasar,<br/>Allah yang meletakkan;<br/>Kukuh, kuat pula mantap,<br/>kami aman s''lamanya.<br/>Dasar lain tiada lagi,<br/>yang boleh diletakkan!<br/>Dikau dasar unik kami,<br/>tak ubah selamanya.<br/>',NULL,60785,4);
INSERT INTO stanza VALUES('I151','4','Bagi pembangunan Allah,<br/>Kau-lah batu penjuru;<br/>Yahudi, Kafir serentak,<br/>terbangun jadi satu.<br/>Dikau juga batu atap,<br/>kasih kurnia tak batas;<br/>Dikau tudung, mulia kami,<br/>hati panjat pujian.<br/>',NULL,60786,5);
INSERT INTO stanza VALUES('I152','1','Limpah nian Kau bagiku,<br/>nyata atas kasih-Mu!<br/>Tiada batas kaya-Mu,<br/>dalam roh ku nikmat t''rus.<br/>',NULL,60787,1);
INSERT INTO stanza VALUES('I152','2','Kau-lah Firman juga Allah,<br/>azali serta Allah;<br/>Inkarnasi jadi insan,<br/>Allah terutarakan.<br/>',NULL,60788,2);
INSERT INTO stanza VALUES('I152','3','Tabernakel nan sejati,<br/>pancar mulia Allah;<br/>Pula bait nan sejati,<br/>tempat kediaman Allah.<br/>',NULL,60789,3);
INSERT INTO stanza VALUES('I152','4','Kau-lah Putra Tunggal Allah,<br/>mengekspresikan Bapa;<br/>Hayat Allah ku dapatkan,<br/>berbagian sifat Allah.<br/>',NULL,60790,4);
INSERT INTO stanza VALUES('I152','5','Anak Manusia Kau jadi,<br/>miliki sifat insan;<br/>Anak Allah kami jadi,<br/>dengan Kau berserupa.<br/>',NULL,60791,5);
INSERT INTO stanza VALUES('I152','6','Kau-lah Kristus nan almuhit,<br/>Mesias urapan Allah;<br/>Kau segala, dalam s''gala,<br/>andal Allah dan insan.<br/>',NULL,60792,6);
INSERT INTO stanza VALUES('I152','7','Juru-s''lamat disalibkan,<br/>tumpah darah dan air;<br/>Hingga ku ditebus Allah,<br/>hayat Allah ku milik.<br/>',NULL,60793,7);
INSERT INTO stanza VALUES('I152','8','Kini Kau Yesus nan mulia,<br/>Roh hayat t''lah Kau utus;<br/>Roh inilah yang almuhit,<br/>biar ku nikmat limpah-Mu.<br/>',NULL,60794,8);
INSERT INTO stanza VALUES('I152','9','Kau terang hayat ilahi,<br/>cahaya dalam gelap;<br/>Sinar Allah dalam batin,<br/>menerangi hatiku.<br/>',NULL,60795,9);
INSERT INTO stanza VALUES('I152','10','Kau hayat kekal ilahi,<br/>menghidupkan roh kami;<br/>Hingga aku lepas maut,<br/>nikmat limpah hayat-Mu.<br/>',NULL,60796,10);
INSERT INTO stanza VALUES('I152','11','Tuhan Kau realitas Allah,<br/>hanya Kau ''kenan Allah;<br/>Realitas aku kenal,<br/>tak asat Kau ditimba.<br/>',NULL,60797,11);
INSERT INTO stanza VALUES('I152','12','Kau satu-satunya jalan,<br/>ke dalam diri Allah;<br/>Jalan hayat, realitas,<br/>bawa ku masuk mulia.<br/>',NULL,60798,12);
INSERT INTO stanza VALUES('I152','13','Kau Sang Bangkit nan ajaib,<br/>maut telah tersingkir;<br/>Oleh kuasa bangkit-Mu,<br/>mati hidup serta-Mu.<br/>',NULL,60799,13);
INSERT INTO stanza VALUES('I152','14','Domba Allah tiada cela,<br/>menggenapkan tebusan;<br/>Juga Pemberi Roh Kudus,<br/>hingga hayat ku dapat.<br/>',NULL,60800,14);
INSERT INTO stanza VALUES('I152','15','Ular tembaga di tiang,<br/>tolongku lepas maut;<br/>Atas salib ditinggikan,<br/>Iblis, maut pun hancur.<br/>',NULL,60801,15);
INSERT INTO stanza VALUES('I152','16','Kau Gembala juga pintu,<br/>kandang Taurat ku lepas;<br/>Oleh-Mu kini ku bebas,<br/>kecap nyaman di padang.<br/>',NULL,60802,16);
INSERT INTO stanza VALUES('I152','17','Cuci kaki, membersihkan,<br/>p''ri wadah pembasuhan;<br/>Dalam s''kutu, ku terlindung,<br/>''tiasa nikmat kurnia-Mu.<br/>',NULL,60803,17);
INSERT INTO stanza VALUES('I152','18','Batu terbelah bagiku,<br/>mengalirkan air hayat;<br/>Arus segar, Kau ku minum,<br/>lerai semua penat.<br/>',NULL,60804,18);
INSERT INTO stanza VALUES('I152','19','Kau-lah sumber hayat surga,<br/>pancarkan air hayat;<br/>Minum Kau Sang Air Hayat,<br/>takkan dahaga s''lama.<br/>',NULL,60805,19);
INSERT INTO stanza VALUES('I152','20','Kau Makanan dari surga,<br/>ilahi, kudus, limpah;<br/>Kaya-Mu tiada hingga,<br/>rohku terpelihara.<br/>',NULL,60806,20);
INSERT INTO stanza VALUES('I152','21','Kau-lah nafas hayat kami,<br/>dalam roh kami hirup;<br/>Hidup, gerak bersandar-Mu,<br/>menikmati diri-Mu.<br/>',NULL,60807,21);
INSERT INTO stanza VALUES('I152','22','Butir Gandum nan ilahi,<br/>jatuh ke tanah mati;<br/>Berbuah banyak, kami ini,<br/>jadi Tubuh misteri.<br/>',NULL,60808,22);
INSERT INTO stanza VALUES('I152','23','Kau pohon anggur sejati,<br/>kami ranting-ranting-Mu;<br/>Tinggal pun satu salam-Mu,<br/>nikmat semua ada-Mu.<br/>',NULL,60809,23);
INSERT INTO stanza VALUES('I152','24','Kau-lah Mempelai sejati,<br/>kami mempelai putri;<br/>Satu padu di dalam roh,<br/>nikmat limpah kasih-Mu.<br/>',NULL,60810,24);
INSERT INTO stanza VALUES('I152','25','Dikau-lah tangga surgawi,<br/>buka langit ke bumi;<br/>Bait Allah kami ini,<br/>hubung langit dan bumi.<br/>',NULL,60811,25);
INSERT INTO stanza VALUES('I152','26','Tuhan, Dikau "Sang Adalah",<br/>penuhi s''mua keperluan;<br/>Nikmati Kau Sang segala,<br/>Allah dimuliakan.<br/>',NULL,60812,26);
INSERT INTO stanza VALUES('I153','1','Tuhan, Dikau Pendampingku,<br/>juga Penghiburku;<br/>Kau-lah Penengahku setia,<br/>tampil depan Allah.<br/>',NULL,60813,1);
INSERT INTO stanza VALUES('I153','2','Tuhan, Kau Penasihatku,<br/>juga Pembelaku;<br/>Pendoa syafaat bagiku,<br/>pula Penolongku.<br/>',NULL,60814,2);
INSERT INTO stanza VALUES('I153','3','Tuhan, sesuai ''kenan Allah,<br/>Kau atur segala;<br/>Di surga pun di batinku,<br/>tangani seluruh.<br/>',NULL,60815,3);
INSERT INTO stanza VALUES('I153','4','Tuhan, Kau Roh diam dalamku,<br/>syafaat bagiku;<br/>Mengeluh-Mu di dalamku,<br/>berdoa untukku.<br/>',NULL,60816,4);
INSERT INTO stanza VALUES('I153','5','Hidup sesuai murad Allah,<br/>membantu tak lelah;<br/>Kuasa bangkit menguatkan<br/>insan batiniah.<br/>',NULL,60817,5);
INSERT INTO stanza VALUES('I153','6','Kau-lah Roh pemberi-hayat,<br/>tunjang kelemahan;<br/>Dalam rohku d''ngan kuasa-Mu,<br/>ku hidup sandar-Mu.<br/>',NULL,60818,6);
INSERT INTO stanza VALUES('I153','7','Kau melayankan diri-Mu,<br/>dengan rahmat, kasih;<br/>Kamilah kepenuhan-Mu,<br/>Kau segala kami.<br/>',NULL,60819,7);
INSERT INTO stanza VALUES('I154','1','Sebelum waktu bermula,<br/>sebelum zaman mulai;<br/>Dalam pangkuan mulia Bapa,<br/>Kau Putra Tunggal Allah.<br/>Saat Bapa b''rikan diri-Mu,<br/>status-Mu tetaplah;<br/>Semua kelimpahan Bapa,<br/>lewat Roh ternyatakan.<br/>',NULL,60820,1);
INSERT INTO stanza VALUES('I154','2','Dikau lewat mati, bangkit,<br/>menjadi Putra Sulung;<br/>Kami lewat lahir baru,<br/>menjadi anak Allah.<br/>Kami gandaan hayat-Mu,<br/>menjadi putra-putra;<br/>Pun reproduksi mulia-Mu,<br/>menjadi perluasan-Mu.<br/>',NULL,60821,2);
INSERT INTO stanza VALUES('I154','3','Kaulah butir biji gandum,<br/>jatuh ke tanah, mati;<br/>Agar lewat mati, bangkit,<br/>butiran gandum jadi.<br/>Berbagian dengan hayat-Mu,<br/>kamilah banyak butir;<br/>Terbaur menjadi roti,<br/>diri-Mu terekspresi.<br/>',NULL,60822,3);
INSERT INTO stanza VALUES('I154','4','Kamilah reproduksi-Mu,<br/>Tubuh-Mu, mempelai-Mu;<br/>Ekspresi-mu, luapan-Mu,<br/>tempat tinggal kekal-Mu.<br/>Kamilah perbanyakan-Mu,<br/>perluasan hayat-Mu;<br/>Pertambahan dan limpah-Mu,<br/>kekal esa dengan-Mu.<br/>',NULL,60823,4);
INSERT INTO stanza VALUES('I155','1','Semua lambang zaman dulu,<br/>hanyalah kiasan-Mu;<br/>Sep''ri yang diibaratkan,<br/>Kau mustika bagiku!<br/>Saat renung gambaran-Mu,<br/>segalanya Kau unggul;<br/>Kami takjub ''kan limpah-Mu,<br/>sembah Kau Sang Segala.<br/>',NULL,60824,1);
INSERT INTO stanza VALUES('I155','2','Tuhan Kau-lah pesta Paskah,<br/>kar''na Kau ku bebaslah;<br/>Oleh diri Sang Penebus,<br/>ku damai dengan Allah.<br/>Kau pun Anak Domba Allah,<br/>berdarah menebusku;<br/>Demi darah, lunas hutang,<br/>makan Dikau ku hidup.<br/>',NULL,60825,2);
INSERT INTO stanza VALUES('I155','3','Tuhan, Kau-lah roti surga,<br/>tanpa ragi dalamnya;<br/>Lewat makan, baur d''ngan-Mu,<br/>alami khasiat-Mu.<br/>Domba, roti melambangkan,<br/>Tuhan, Kaulah hayatku;<br/>Pesta, makan, minum Dikau,<br/>menikmati limpah-Mu.<br/>',NULL,60826,3);
INSERT INTO stanza VALUES('I155','4','Kau pun manna dari surga,<br/>tiap hari menunjang;<br/>Rawat, kenyang, kuat,<br/>tunjang, penuhi kebutuhan!<br/>Dikau juga batu hidup,<br/>terbelah alir hayat;<br/>Menyesap pada air hayat,<br/>kekal lerai dahaga.<br/>',NULL,60827,4);
INSERT INTO stanza VALUES('I155','5','Dikau pun tanah Kanaan,<br/>permai, subur pun limpah;<br/>Susu, madu, dan tuaian,<br/>suplai yang serba lengkap.<br/>''Tas limpah-Mu, sembah Allah,<br/>saling sekutu mesra;<br/>',NULL,60828,5);
INSERT INTO stanza VALUES('I156','1','Tuhan, Kau Sang Surya adil,<br/>pancar kesembuhan;<br/>Cah''ya mulia-Mu terangi,<br/>bawa damai hayat.<br/>',NULL,60829,1);
INSERT INTO stanza VALUES('I156','2','Belas kasih hati Allah,<br/>menyuruh Kau datang;<br/>Menerangi semua orang<br/>yang dalam keg''lapan.<br/>',NULL,60830,2);
INSERT INTO stanza VALUES('I156','3','Bagiku Kau fajar cerah,<br/>p''ri surya nan terang;<br/>Kami rerumputan lemah,<br/>perlukan sinarnya.<br/>',NULL,60831,3);
INSERT INTO stanza VALUES('I156','4','Kurnia bawakan cahaya,<br/>bertambah merekah;<br/>Makin terang dalam batin,<br/>sampai rembang hari.<br/>',NULL,60832,4);
INSERT INTO stanza VALUES('I156','5','Terang sinari sengsara,<br/>cerah usai hujan;<br/>Bawakan rahmat dan cinta,<br/>tak henti memancar.<br/>',NULL,60833,5);
INSERT INTO stanza VALUES('I156','6','Tuhan, Kau Sang Bintang Fajar,<br/>pahala siaga;<br/>Menerangi pencinta-Mu,<br/>di malam yang gelap.<br/>',NULL,60834,6);
INSERT INTO stanza VALUES('I156','7','Biar ku damba ''kan terang-Mu,<br/>agar jeli mata;<br/>Siap, doa, ''nantikan-Mu,<br/>terbit Bintang Fajar.<br/>',NULL,60835,7);
INSERT INTO stanza VALUES('I157','1','Terkenang akan diri-Mu,<br/>kami menyembah pada-Mu;<br/>Limpah ajaiblah diri-Mu,<br/>mustika nan elok agung.<br/>',NULL,60836,1);
INSERT INTO stanza VALUES('I157','chorus','Kau-lah justru keperluanku,<br/>hati p''nuh syukur pada-Mu!<br/>Kau puaskan semua hasratku,<br/>s''lalu sedia, limpah sungguh!<br/>',NULL,60837,2);
INSERT INTO stanza VALUES('I157','2','Kau mutlak Allah sejati,<br/>Allah Sang Terang pun Kasih;<br/>Menjadilah hayat kami,<br/>limpah ruah kurnia Kau b''ri.<br/>',NULL,60838,3);
INSERT INTO stanza VALUES('I157','3','Kau mutlak insan sejati,<br/>halus, lembut, tulus, murni;<br/>Bagi Allah: dikenani;<br/>bagi insan: tawan hati.<br/>',NULL,60839,4);
INSERT INTO stanza VALUES('I157','4','Kau rela menjadi hamba,<br/>semua tak lain kar''na kami;<br/>Mutlak taat, hingga wafat,<br/>meny''lamatkan, memberkati.<br/>',NULL,60840,5);
INSERT INTO stanza VALUES('I157','5','Tuhan, Dikau pun Sang Raja,<br/>diurap, diangkat Allah;<br/>Lewat hayat, pula cinta,<br/>bawa kami memerintah.<br/>',NULL,60841,6);
INSERT INTO stanza VALUES('I157','6','Terkenang akan diri-Mu,<br/>kami berbagian ada-Mu;<br/>Dalam kasih nikmati-Mu,<br/>selamanya, t''rus-menerus!<br/>',NULL,60842,7);
INSERT INTO stanza VALUES('I158','1','O, Tuhan, Kau-lah Alfa,<br/>Kau juga Omega;<br/>Tiada yang lebih duluan<br/>dan lebih kemudian.<br/>Kau Sang Awal nan unik,<br/>juga Sang Terakhir,<br/>Dalam Kau segalanya,<br/>Kau sungguh almuhit.<br/>',NULL,60843,1);
INSERT INTO stanza VALUES('I158','2','Tuhan, kar''na Kau Alfa,<br/>Kau awal s''galanya;<br/>Kar''na Kau pun Omega,<br/>Kau akhir s''galanya.<br/>Kau juga s''mua ejaan,<br/>Pengeja s''galanya;<br/>Pun cakup s''mua aksara,<br/>Penunjang segala.<br/>',NULL,60844,2);
INSERT INTO stanza VALUES('I158','3','Sulung dari ciptaan,<br/>Kau-lah yang utama;<br/>Kau akhir dari semua,<br/>akhiri segala.<br/>Sulung dari ciptaan,<br/>Kau sumber segala;<br/>Sang Akhir dari semua,<br/>sandar-Mu s''mua ada.<br/>',NULL,60845,3);
INSERT INTO stanza VALUES('I158','4','Kau Pemula semuanya,<br/>''dului segala;<br/>Kau akhir segalanya,<br/>warisi semuanya.<br/>Sang Pemula nan unik,<br/>awali segala;<br/>Sang Pengakhir nan unik,<br/>akhiri segala.<br/>',NULL,60846,4);
INSERT INTO stanza VALUES('I158','5','Tuhan, kami menyembah,<br/>Kau mustika,<br/>sayang; Alfa pula Omega,<br/>di atas segala.<br/>Puji Kau Sang Pemula,<br/>m''lebihi segala;<br/>Sembah Kau Sang Penyudah,<br/>tiada yang ditambah!<br/>',NULL,60847,5);
INSERT INTO stanza VALUES('I159','1','Tuhan, Kau-lah pohon<br/>hayat nan satu-satunya;<br/>Kaya hayatlah buahnya,<br/>paling sedap lezat.<br/>',NULL,60848,1);
INSERT INTO stanza VALUES('I159','2','Kau-lah pokok anggur surga,<br/>sumber suplai hayat;<br/>Tinggal dan hidup dalam-Mu,<br/>nikmati limpah-Mu.<br/>',NULL,60849,2);
INSERT INTO stanza VALUES('I159','3','Kau pun pohon apel itu,<br/>kecap sepuasku;<br/>Sedap dan lezat buah-Mu,<br/>bawah-Mu, naungku.<br/>',NULL,60850,3);
INSERT INTO stanza VALUES('I159','4','Kau-lah pohon kesembuhan,<br/>pernah mati buatku;<br/>Atas salib terbunuh-Mu,<br/>agar aku sembuh.<br/>',NULL,60851,4);
INSERT INTO stanza VALUES('I159','5','Kau-lah carang tunggal Allah,<br/>kepenuhan Allah;<br/>Atas-Mu Allah ku nikmat,<br/>realitas kurnia.<br/>',NULL,60852,5);
INSERT INTO stanza VALUES('I159','6','Tuhan, Kau pun carang Daud,<br/>lewat inkarnasi;<br/>Pada-Mu kami mengerti<br/>insani sejati.<br/>',NULL,60853,6);
INSERT INTO stanza VALUES('I159','7','Kau Tongkat-Nya yang bertunas,<br/>hayat tak terbatas;<br/>Maut, kekal terkalahkan<br/>oleh kebangkitan.<br/>',NULL,60854,7);
INSERT INTO stanza VALUES('I159','8','Kau-lah kayu yang terapung,<br/>ku "kapak" tenggelam;<br/>Oleh kuasa bangkit-Mu,<br/>''terapung'' ku juga.<br/>',NULL,60855,8);
INSERT INTO stanza VALUES('I159','9','Kau-lah "tumbuhan nan tenar",<br/>limpahnya ku nikmat;<br/>Kini saat kami kenang,<br/>bagi-Mu s''mua pujian.<br/>',NULL,60856,9);
INSERT INTO stanza VALUES('I160','1','Tuhan, Kau kesaksian Allah,<br/>melebihi Taurat;<br/>Taurat hanyalah bayangan,<br/>Kau realitasnya.<br/>Taurat menerangkan Allah,<br/>menggambarkan Allah;<br/>Kau justru realitas Allah<br/>- dalam-Mu huni-Nya.<br/>',NULL,60857,1);
INSERT INTO stanza VALUES('I160','2','Tabut pun melambangkan-Mu,<br/>berisikan Taurat;<br/>Diri Allah di dalam-Mu,<br/>dengan segala-Nya.<br/>Tabut dari kayu padat,<br/>dilapisi emas;<br/>Tanda tepat insani-Mu,<br/>baur sifat Allah.<br/>',NULL,60858,2);
INSERT INTO stanza VALUES('I160','3','Kau Tabernakel sejati,<br/>Allah bersemayam;<br/>Inkarnasi penuh kasih<br/>kurnia dan realitas.<br/>Orang nampak mulia Allah,<br/>Kau firman hidup-Nya;<br/>Tindak kasih dan terang-Mu,<br/>gambar hidup Allah.<br/>',NULL,60859,3);
INSERT INTO stanza VALUES('I160','4','Bait Suci pun lambang-Mu,<br/>Kau bait sejati;<br/>Allah dengan segala-Nya,<br/>pada-Mu ternyata.<br/>Meski Iblis ''nyerang ganas,<br/>mendesak Kau wafat;<br/>Dikau bait lebih besar,<br/>dalam kebangkitan.<br/>',NULL,60860,4);
INSERT INTO stanza VALUES('I160','5','Kota kudus, k''limpahan-Mu,<br/>juga mempelai-Mu;<br/>Meluas kepenuhan-Mu,<br/>oleh luapan-Mu.<br/>Allah dalam-Mu jadi t''rang,<br/>Kau t''rang lampu kota;<br/>S''mua orang dapatkan terang,<br/>nyata mulia Allah.<br/>',NULL,60861,5);
INSERT INTO stanza VALUES('I160','6','Tabernakel, tabut, taurat,<br/>bait, Kota kudus,<br/>Justru diri-Mu sendiri,<br/>''nyatakan limpah-Mu.<br/>Kau inti pun lingkarannya,<br/>semua diri-Mu;<br/>Allah, insan di dalam-Mu,<br/>takjublah hatiku.<br/>',NULL,60862,6);
INSERT INTO stanza VALUES('I161','1','Tuhan, alangkah limpah-Mu,<br/>Kau-lah segalaku;<br/>B''rapa pun kebutuhanku,<br/>semua terpenuh.<br/>Ku apresiasi ada-Mu,<br/>dalam roh sembah-Mu;<br/>kar''na nikmati limpah-Mu,<br/>panjat puji syukur.<br/>',NULL,60863,1);
INSERT INTO stanza VALUES('I161','2','Kau nabi yang Allah tunjuk,<br/>penuh kuasa Allah;<br/>P''ri Musa singkap murad-Nya,<br/>kami semua taat;<br/>P''ri Yunus utusan Allah,<br/>bangkit dari wafat;<br/>Oleh tanda mati bangkit,<br/>ku tobat, percaya.<br/>',NULL,60864,2);
INSERT INTO stanza VALUES('I161','3','Kau nabi di tengah umat,<br/>penuh terang kuasa;<br/>Penuh kasih p''ri Elisa,<br/>lakukan mujizat.<br/>Murah hati p''ri Yesaya,<br/>Kristus terwahyukan;<br/>Ku nikmati Sang Segala,<br/>sungguh riil, limpah.<br/>',NULL,60865,3);
INSERT INTO stanza VALUES('I161','4','Dikau Sang Imam pilihan,<br/>kudus jadi imam;<br/>P''ri Harun dipanggil Allah,<br/>melayani Allah.<br/>Dengan kasih membawaku<br/>datang depan Allah;<br/>Kar''na kasih bersyafaat,<br/>lemahku ditunjang.<br/>',NULL,60866,4);
INSERT INTO stanza VALUES('I161','5','Kau imam utusan Allah,<br/>imam nan rajani;<br/>Melkisedek, Raja Salem,<br/>datang melayani.<br/>Bawakan roti dan anggur,<br/>suplai hayat jadi;<br/>Bawa Allah dan kaya-Nya,<br/>agar ku nikmati.<br/>',NULL,60867,5);
INSERT INTO stanza VALUES('I161','6','Kau-lah Raja s''perti Daud,<br/>taat kehendak-Nya;<br/>Menang perang atas musuh,<br/>murad Allah nyata.<br/>Dapat kuasa, naik takhta,<br/>bukan kar''na orang;<br/>Tapi kar''na kuasa Allah,<br/>meraja bagi-Nya.<br/>',NULL,60868,6);
INSERT INTO stanza VALUES('I161','7','P''ri Salomo Kau meraja,<br/>dengan kedamaian;<br/>Memerintah penuh hikmat,<br/>bangun Bait Allah.<br/>Kini di tengah kaum saleh,<br/>cinta-Mu berperan;<br/>Kelak meraja bersama,<br/>kuasa-Mu ternyata.<br/>',NULL,60869,7);
INSERT INTO stanza VALUES('I161','8','Kau-lah imam, nabi, raja,<br/>ada-Mu berlimpah;<br/>Terhadap Allah dan insan,<br/>Kau adi mustika.<br/>Ada-Mu amat memikat,<br/>sungguh mempesona;<br/>Bagi-Mu sembah, pujian,<br/>syukur tak bersudah.<br/>',NULL,60870,8);
INSERT INTO stanza VALUES('I162','1','Tuhan, Kau-lah "benih dara",<br/>lahir menumpas lawan;<br/>Mengenakan sifat insan,<br/>wafat dapatkan menang.<br/>Kau Allah berinkarnasi,<br/>kenakan darah daging;<br/>Mati meremukkan Iblis,<br/>kuasa maut terbasmi.<br/>',NULL,60871,1);
INSERT INTO stanza VALUES('I162','2','Genap janji Allah,<br/>Kau-lah "keturunan Abraham".<br/>Agar insan mendapatkan,<br/>berkat dari janji-Nya;<br/>Sebelum ada Abraham,<br/>kar''na Kau Sang "Adalah";<br/>Namun Kau demi murad-Nya,<br/>jadi keturunannya.<br/>',NULL,60872,2);
INSERT INTO stanza VALUES('I162','3','Tuhan Kau pun "Anak Daud",<br/>bangun K''rajaan Allah;<br/>Bagi pembangunan Allah,<br/>bagi-Mu takhta Allah.<br/>Meskipun Kau "Anak Daud",<br/>"Tuhanku" dipanggilnya;<br/>Memang Dikau "Akar Daud",<br/>"Sang Almuhit" nan kekal.<br/>',NULL,60873,3);
INSERT INTO stanza VALUES('I162','4','"Bayi" lahir nan insani,<br/>namun "Allah Perkasa";<br/>"Putra" Kau dikaruniakan,<br/>namun "Bapa nan kekal".<br/>Berkat dari janji Allah,<br/>kami mutlak percaya;<br/>Janji-Mu pasti semua,<br/>Kau-lah realitasnya.<br/>',NULL,60874,4);
INSERT INTO stanza VALUES('I163','1','Kau-lah Putra tersayang,<br/>gambar mulia Allah;<br/>Bagian kekal kaum saleh,<br/>kami nikmat s''lama.<br/>Antara ciptaan Allah,<br/>Kau-lah yang utama;<br/>oleh-Mu s''mua tercipta,<br/>bagi-Mu semuanya.<br/>',NULL,60875,1);
INSERT INTO stanza VALUES('I163','2','Kau sumber s''mua ciptaan,<br/>pun eksistensinya,<br/>Kaulah inti segala,<br/>oleh-Mu s''mua ada.<br/>Tuhan, Kaulah Sang Awal,<br/>Sang Bangkit pertama;<br/>Bagi Tubuh-Mu g''reja,<br/>Kau-lah Sang Kepala.<br/>',NULL,60876,2);
INSERT INTO stanza VALUES('I163','3','S''mua kepenuhan Allah,<br/>dalam-Mu berdiam;<br/>Biar Kau yang terutama,<br/>pun terekspresikan.<br/>Darah-Mu mendamaikan<br/>s''galanya d''ngan Allah;<br/>Biar kami kudus, mulia,<br/>tersembah pada-Nya.<br/>',NULL,60877,3);
INSERT INTO stanza VALUES('I163','4','Dalam-Mu limpah Allah,<br/>Kau rahasia Alah;<br/>Wadah segala hikmat<br/>pun pengetahuan.<br/>Kini tinggal dalamku,<br/>Kau harapan mulia;<br/>Dalam-Mu ku dig''napkan,<br/>hingga Allah puas.<br/>',NULL,60878,4);
INSERT INTO stanza VALUES('I163','5','Semua ialah bayangan,<br/>hanya Kau realitas;<br/>Dalam-Mu kini kami<br/>berakar, berada.<br/>Nikmati s''mua kaya-Mu,<br/>jadi kep''nuhan-Mu;<br/>Dengan anggota Tubuh,<br/>saling tunjang-bangun.<br/>',NULL,60879,5);
INSERT INTO stanza VALUES('I163','6','Kami-Kau dalam Allah,<br/>Dikau-lah Sang Hayat;<br/>K''lak nyata dalam mulia,<br/>nikmati limpah-Nya.<br/>Insan baru, Tubuh-Mu,<br/>Kaulah segalanya;<br/>Kristuslah Sang Almuhit,<br/>Kau betapa limpah!<br/>',NULL,60880,6);
INSERT INTO stanza VALUES('I164','1','Tuhan, Kau Sang Putra Allah,<br/>penuh ''nyatakan Allah;<br/>Lewat Kau Allah bersabda,<br/>sangat jelas dan tegas.<br/>',NULL,60881,1);
INSERT INTO stanza VALUES('I164','2','Kau gambar hakiki Allah,<br/>Cahaya mulia Allah.<br/>Dikau justru diri Allah,<br/>justru tampilan Allah.<br/>',NULL,60882,2);
INSERT INTO stanza VALUES('I164','3','Jagat raya Kau yang cipta,<br/>Kau juga penopangnya;<br/>Kelak Kau mewarisinya,<br/>Yang ditetapkan Allah.<br/>',NULL,60883,3);
INSERT INTO stanza VALUES('I164','4','Dosa kami Kau bersihkan,<br/>kini duduk kanan-Nya;<br/>Tunggu musuh tertaklukkan,<br/>tergenap kehendak-Nya.<br/>',NULL,60884,4);
INSERT INTO stanza VALUES('I164','5','Nama terhormat Kau t''rima,<br/>jauh ''lampau s''mua malak;<br/>Dibangkitkan dari maut,<br/>nyata Dikau Putra-Nya.<br/>',NULL,60885,5);
INSERT INTO stanza VALUES('I164','6','Daulat-Mu adil pun lurus,<br/>takhta-Mu kekal jaya;<br/>Kau diurapi d''ngan minyak,<br/>ungguli kawan-kawan.<br/>',NULL,60886,6);
INSERT INTO stanza VALUES('I164','7','Kau manusia sejati,<br/>punya sifat insani,<br/>Bagiku mengecap maut,<br/>ku dapatkan hayat-Mu.<br/>',NULL,60887,7);
INSERT INTO stanza VALUES('I164','8','Hormat, mulia Kau dapat,<br/>alam s''mesta s''mua takluk;<br/>Kau Panglima kes''lamatan,<br/>sempurna kar''na d''rita.<br/>',NULL,60888,8);
INSERT INTO stanza VALUES('I164','9','Lewat wafat, hancur Satan,<br/>dari maut ku bebas;<br/>Kuduskanku dalam hayat,<br/>bahkan masuk mulia.<br/>',NULL,60889,9);
INSERT INTO stanza VALUES('I164','10','Pada kami, saudara-Mu,<br/>nama Bapa Kau sebar;<br/>Memuji dalam gereja,<br/>respons kami serentak.<br/>',NULL,60890,10);
INSERT INTO stanza VALUES('I164','11','P''ri pembangun dengan rumah,<br/>Kau melebihi Musa;<br/>Kau-lah rasul dari Allah,<br/>layak lebih terhormat.<br/>',NULL,60891,11);
INSERT INTO stanza VALUES('I164','12','Kau-lah Yosua sejati,<br/>bawa masuk perhentian;<br/>Kau-lah kurnia kes''lamatan,<br/>iman kami pada-Mu.<br/>',NULL,60892,12);
INSERT INTO stanza VALUES('I164','13','Kau-lah perhentian surgawi,<br/>dalam roh Kau berhuni;<br/>Kami masuk pun nikmati,<br/>di tanah permai ini.<br/>',NULL,60893,13);
INSERT INTO stanza VALUES('I164','14','Imam Besar pilihan-Nya,<br/>unggul Kau dari Harun;<br/>Kudus, suci, mahatinggi,<br/>doa, di tempat kudus.<br/>',NULL,60894,14);
INSERT INTO stanza VALUES('I164','15','Kau Melkisedek sejati,<br/>oleh kuasa hayat;<br/>Pada saat kami perlu,<br/>suplai "roti" dan "anggur".<br/>',NULL,60895,15);
INSERT INTO stanza VALUES('I164','16','Kau kurban yang lebih indah,<br/>melalui Roh kekal;<br/>Tersembah kepada Allah,<br/>khasiat-Nya ku nikmat.<br/>',NULL,60896,16);
INSERT INTO stanza VALUES('I164','17','Perjanjian lebih indah,<br/>oleh darah adi-Mu;<br/>Oleh-Mu, ku berbagian,<br/>Perjanjian yang baru.<br/>',NULL,60897,17);
INSERT INTO stanza VALUES('I164','18','Kau Pembuatnya nan legal,<br/>selain Kau tiada;<br/>Kau Pemberinya nan halal,<br/>ku warisi segala.<br/>',NULL,60898,18);
INSERT INTO stanza VALUES('I164','19','Kau kini Pelaksananya,<br/>d''ngan hayat kebangkitan;<br/>Kau juga Mediatornya,<br/>genapkan tadbir Allah.<br/>',NULL,60899,19);
INSERT INTO stanza VALUES('I164','20','Di balik tirai Kau kini,<br/>Perintisku nan unik;<br/>Sandar kau keluar kemah,<br/>ikut Kau dengan setia.<br/>',NULL,60900,20);
INSERT INTO stanza VALUES('I164','21','Kau-lah Pemula imanku,<br/>pun Perampung imanku;<br/>Jalan serta iman, cinta,<br/>pada-Mu aku taat.<br/>',NULL,60901,21);
INSERT INTO stanza VALUES('I164','22','Nilai-Mu tiada tanding,<br/>ada-Mu pun menarik;<br/>Kau sungguh elok sempurna,<br/>lampaui pengertian.<br/>',NULL,60902,22);
INSERT INTO stanza VALUES('I165','1','Kau-lah aneka kurban<br/>yang Allah sediakan;<br/>Maknanya limpah amat,<br/>mulia pun sedap!<br/>Genap kehendak Bapa,<br/>capai dambaan-Nya;<br/>Penuhi kebutuhan,<br/>tiada kekurangan!<br/>',NULL,60903,1);
INSERT INTO stanza VALUES('I165','2','Kau-lah kurban bakaran,<br/>api kudus bakar;<br/>Semerbak bagi Allah,<br/>puaskan hati-Nya.<br/>Depan-Nya Kau berjalan,<br/>pentingkan murad-Nya;<br/>Kau persembahkan diri,<br/>mengenyangkan Allah.<br/>',NULL,60904,2);
INSERT INTO stanza VALUES('I165','3','Kau-lah kurban sajian,<br/>minyak campur dupa;<br/>Murni, halus, sempurna,<br/>indah menyenangkan.<br/>Kau pun kurban pendamai,<br/>berikan sentosa;<br/>Jadi makanan limpah,<br/>Allah - insan puas.<br/>',NULL,60905,3);
INSERT INTO stanza VALUES('I165','4','Kau kurban hapus dosa,<br/>mengganti yang dosa;<br/>Wafat rampung tebusan,<br/>bayar lunas harga.<br/>Kau kurban pelanggaran,<br/>pikul kesalahan;<br/>Puaskan adil Allah,<br/>ku dapat ampunan.<br/>',NULL,60906,4);
INSERT INTO stanza VALUES('I165','5','Kau juga kurban timang,<br/>bangkit dari wafat;<br/>Barzakh, maut, dan gelap,<br/>terkalahkan semua.<br/>Kau pun kurban unjukan,<br/>naik ke depan-Nya;<br/>Jadi makanan surga,<br/>aku dikenyangkan.<br/>',NULL,60907,5);
INSERT INTO stanza VALUES('I166','1','Dalam nama-Mu berhimpun,<br/>tak melihat yang lain;<br/>Hadir-Mu sukacitaku,<br/>pada-Mu ku Kau panggil.<br/>',NULL,60908,1);
INSERT INTO stanza VALUES('I166','2','Kasih padaku tak ukur,<br/>p''ri Bapa kepada-Mu;<br/>Kehendak Bapa pada-Mu,<br/>ku hargai pun syukur.<br/>',NULL,60909,2);
INSERT INTO stanza VALUES('I166','3','''Kenan, sabat, riang Bapa,<br/>pada-Mu seluruhnya;<br/>Hanya Kau bisa selami,<br/>nilai-Mu di depan-Nya.<br/>',NULL,60910,3);
INSERT INTO stanza VALUES('I166','4','Kasih Bapa s''mua pada-Mu,<br/>"Terkasih" Kau disebut,<br/>Namun agar aku hidup,<br/>Kau berkorban bagiku.<br/>',NULL,60911,4);
INSERT INTO stanza VALUES('I166','5','Kelak tampak s''mua ada-Mu,<br/>ku ''kan panjat pujian;<br/>Tuhan Yesus, nama harum,<br/>s''merbak di hati Allah.<br/>',NULL,60912,5);
INSERT INTO stanza VALUES('I166','6','Lagu riang melantun t''rus,<br/>panjat pujian kekal;<br/>Mazmur mulia berlanjut,<br/>sampai s''lama-lamanya.<br/>',NULL,60913,6);
INSERT INTO stanza VALUES('I167','1','Tuhan, Kau sumber hayat<br/>nan dalam pun sedap;<br/>Air hidup ku sesap,<br/>tak dahaga s''lama.<br/>Luas belas kasih-Mu,<br/>limpah sep''ri laut;<br/>Kurnia cukup bagiku,<br/>seturut hikmat-Mu.<br/>',NULL,60914,1);
INSERT INTO stanza VALUES('I167','2','Ku milik Kekasihku,<br/>Dia pun milikku;<br/>Orang dosa nan cemar,<br/>masuk jamuan-Mu.<br/>Karya-Mu sandaranku,<br/>hanya Kau melulu;<br/>Tinggal dalam terang-Mu,<br/>nikmati lindung-Mu.<br/>',NULL,60915,2);
INSERT INTO stanza VALUES('I167','3','Bukan hiasan memikat,<br/>tapi Kekasihku;<br/>Bukan mulia ditatap,<br/>tapi Kau nan tampan.<br/>Bukan mahkota anggun,<br/>tapi yang terpaku;<br/>Tuhan, Kau muliaku,<br/>sandaran kekalku.<br/>',NULL,60916,3);
INSERT INTO stanza VALUES('I168','1','Tuhan, tiap kami kenang<br/>segenap cinta-Mu,<br/>Roh kami seg''ra berharap,<br/>memandang wajah-Mu.<br/>',NULL,60917,1);
INSERT INTO stanza VALUES('I168','2','Meski kami berkelana,<br/>di padang yang gersang;<br/>Kanan kiri jerat, duri,<br/>penuhlah ancaman.<br/>',NULL,60918,2);
INSERT INTO stanza VALUES('I168','3','Bila kami merenungkan,<br/>kasih-Mu yang agung,<br/>Hati segera terpacu,<br/>puji kurnia-Mu t''rus.<br/>',NULL,60919,3);
INSERT INTO stanza VALUES('I168','4','Kaulah hayat, terang, t''naga,<br/>p''risai, karang, kidung;<br/>Betapa pun kami kenang,<br/>makin girang s''lalu.<br/>',NULL,60920,4);
INSERT INTO stanza VALUES('I168','5','Tuhan, jaga kami semua,<br/>ikut Kau tiap saat;<br/>Hingga masuk pintu surga,<br/>pandang wajah mulia.<br/>',NULL,60921,5);
INSERT INTO stanza VALUES('I169','1','Yesus, Yesus, Kau hayatku,<br/>demi cinta kasih,<br/>Biar nama-Mu ribuan<br/>kali ku sebut tiap hari.<br/>',NULL,60922,1);
INSERT INTO stanza VALUES('I169','chorus','Yesus Penolong kekasih,<br/>bagiku Dikau termanis;<br/>Ku girang kar''na senyum-Mu,<br/>ku cinta pada-Mu.<br/>',NULL,60923,2);
INSERT INTO stanza VALUES('I169','2','Pada-Mu ku mengasihi<br/>tak tertahan diri;<br/>Kasih-Mu p''ri bara api,<br/>menggairahkan hati.<br/>',NULL,60924,3);
INSERT INTO stanza VALUES('I169','3','Kau itu s''gala-galaku,<br/>sandaran, panganku;<br/>Seleraku dan obatku,<br/>tenaga jiwaku.<br/>',NULL,60925,4);
INSERT INTO stanza VALUES('I169','4','Bakar, bakarlah hatiku,<br/>siang malam bakar t''rus;<br/>Hingga berhala hatiku<br/>musnahlah seluruh.<br/>',NULL,60926,5);
INSERT INTO stanza VALUES('I169','5','Kaulah t''rangku dalam gelap,<br/>riangku dalam duka;<br/>Yesus, Kau kasih, kidungku,<br/>mustika bagiku!<br/>',NULL,60927,6);
INSERT INTO stanza VALUES('I169','6','Adakah batas kasih-Mu?<br/>Mungkinkah berhenti?<br/>Tambah hari tambah manis,<br/>manis nan abadi.<br/>',NULL,60928,7);
INSERT INTO stanza VALUES('I170','1','Tuhan, terhadap kasih, damba-Mu,<br/>Mulutku suka mengutarakan;<br/>Kau Sang Bangkit menjadi berkatku,<br/>kini sembahkan syukur pada-Mu.<br/>',NULL,60929,1);
INSERT INTO stanza VALUES('I170','2','Di sini Kau kami kecap lagi,<br/>penyertaan-Mu menawan hati;<br/>Bawah naung-Mu riang legaku,<br/>buah indah-Mu kami santap t''rus.<br/>',NULL,60930,2);
INSERT INTO stanza VALUES('I170','3','Kau sendiri bahkan sampai mati,<br/>buah lebat dari gandum sebutir;<br/>Bangkit hasilkan banyak saudara,<br/>atas s''gala-Mu, kami terlibat.<br/>',NULL,60931,3);
INSERT INTO stanza VALUES('I170','4','Tuhan, kini Kau jadi segala,<br/>dalam-Mu aku tak kekurangan;<br/>Tiap kebutuhan t''lah Kau puaskan,<br/>hati, mulutku, sembah pujian.<br/>',NULL,60932,4);
INSERT INTO stanza VALUES('I171','1','Yesus, setiap mengenang-Mu,<br/>sedaplah hatiku;<br/>Namun ini masih jauh,<br/>dibanding jumpa-Mu.<br/>',NULL,60933,1);
INSERT INTO stanza VALUES('I171','2','Mulut, hati, dan ingatan,<br/>tak pernah terlintas;<br/>Suara mana yang merdu,<br/>sebanding nama-Mu.<br/>',NULL,60934,2);
INSERT INTO stanza VALUES('I171','3','Kau harapan orang dosa,<br/>riangnya peramah;<br/>Yang mencari Kau berkati,<br/>yang jatuh Kau papah.<br/>',NULL,60935,3);
INSERT INTO stanza VALUES('I171','4','Bagi penemu diri-Mu,<br/>tak terkata sungguh;<br/>Luas dalam kasih Yesus,<br/>hanya Dia yang tahu.<br/>',NULL,60936,4);
INSERT INTO stanza VALUES('I171','5','Yesus, Kau terang dunia,<br/>pula sumber hayat!<br/>Lampaui daya nikmatku<br/>dan damba hatiku.<br/>',NULL,60937,5);
INSERT INTO stanza VALUES('I171','6','Sumber lain ku tak punya,<br/>yang lerai dahaga;<br/>Hayat kekal berpancaran,<br/>tak kunjunglah asat.<br/>',NULL,60938,6);
INSERT INTO stanza VALUES('I171','7','Yesus, kini Kau riangku,<br/>kelak pahalaku;<br/>Mulia serta kidungku,<br/>selama tak putus.<br/>',NULL,60939,7);
INSERT INTO stanza VALUES('I172','1','Tuhan, Kaulah sukacita,<br/>sumber hayat, terang insan;<br/>Bah''gia dunia hampa b''laka,<br/>kini pada-Mu tengadah.<br/>',NULL,60940,1);
INSERT INTO stanza VALUES('I172','2','Abadi realitas-Mu,<br/>tunjang papah pencari-Mu;<br/>Terhadapnya, Kau Sang Rahmat,<br/>bahkan segala-galanya.<br/>',NULL,60941,2);
INSERT INTO stanza VALUES('I172','3','Pangan hayat t''lah ku kecap,<br/>rinduku makin menjadi;<br/>Sumber hayat t''lah ku sesap,<br/>dambaku makin tak henti.<br/>',NULL,60942,3);
INSERT INTO stanza VALUES('I172','4','Saat bah''gia dunia ubah,<br/>roh nan resah menengadah;<br/>Girang, memandang senyum-Mu,<br/>iman berpegang pada-Mu.<br/>',NULL,60943,4);
INSERT INTO stanza VALUES('I172','5','Kau tenaga pun penunjang!<br/>Meneguhkan, beri terang;<br/>Enyah angan gelap dosa;<br/>curah terang kudus mulia.<br/>',NULL,60944,5);
INSERT INTO stanza VALUES('I173','1','Sesuai firman-Mu, ya,<br/>Tuhan, dengan rendah hati,<br/>Mengingat Kau himpun ini,<br/>kar''na Kau t''lah mati.<br/>',NULL,60945,1);
INSERT INTO stanza VALUES('I173','2','Tubuh-Mu telah terkoyak,<br/>jadi jaminanku,<br/>Cawan perjanjian ku angkat,<br/>mengingat pada-Mu.<br/>',NULL,60946,2);
INSERT INTO stanza VALUES('I173','3','Dalam Taman Getsemani,<br/>sunyi tanpa kawan,<br/>Peluh, darah, dan tangis-Mu,<br/>ku kenang semuanya.<br/>',NULL,60947,3);
INSERT INTO stanza VALUES('I173','4','Bila ku pandang salib-Mu<br/>di Gunung Golgota,<br/>Domba Allah, Penolongku,<br/>Kau patut ku ingat.<br/>',NULL,60948,4);
INSERT INTO stanza VALUES('I173','5','Ingat Kau dan derita-Mu,<br/>pun kasih sayang-Mu,<br/>Menjelang nafas terakhir,<br/>ku tetap ingat Kau.<br/>',NULL,60949,5);
INSERT INTO stanza VALUES('I173','6','Bila ku jadi kian renta,<br/>ingatan kian lemah,<br/>Saat k''rajaan-Mu tiba,<br/>ingatku, ya, Tuhan.<br/>',NULL,60950,6);
INSERT INTO stanza VALUES('I174','1','Panji kasih Tuhan angkat,<br/>kami santap jamuan-Mu<br/>Tebusan-Mu agung mulia,<br/>kami ingat selalu.<br/>Hidangan roti dan cawan,<br/>tanda kasih tak t''rukur.<br/>T''rima berkat, bahagia,<br/>kami sembah dan sujud.<br/>',NULL,60951,1);
INSERT INTO stanza VALUES('I174','2','Teringat Kau di dunia,<br/>menghamba, menderita;<br/>Dicobai s''ring puasa,<br/>lelah, tiada perhentian.<br/>Mencari orang berdosa,<br/>dibalas tentang, lapar;<br/>Bila ada yang bertobat,<br/>berdarah-Mu bagi dia.<br/>',NULL,60952,2);
INSERT INTO stanza VALUES('I174','3','Teringat Dikau terpentang,<br/>Allah pun buang muka;<br/>''Nebus dosa sendirian,<br/>kasih-Mu tak terhingga.<br/>Kini berada di surga,<br/>bagi kami berdoa;<br/>Kau berjanji ''kan kembali,<br/>jadilah sg''ra, ya, Tuhan.<br/>',NULL,60953,3);
INSERT INTO stanza VALUES('I175','1','Nikmati cawan berkat,<br/>memuji atau bungkam?<br/>Demiku Kau berdarah,<br/>nilainya siapa duga?<br/>Darah mustika nian,<br/>masalahku tuntaslah;<br/>Darah-Mu berkhasiat,<br/>sirna duka dan cemas.<br/>',NULL,60954,1);
INSERT INTO stanza VALUES('I175','2','Oleh darah mujarab,<br/>tegak janji baru-Nya;<br/>Janji yang lebih indah,<br/>pondasi ini kekal.<br/>Kita telah ditebus,<br/>bukan dengan ''mas, perak;<br/>Tapi darah adi-Mu,<br/>di sini ku menyesap.<br/>',NULL,60955,2);
INSERT INTO stanza VALUES('I175','3','Agar dosa terampun,<br/>darah telah Kau tumpah;<br/>Tuntutan keadilan,<br/>terpenuhi semua.<br/>Darah-Mu adi daya,<br/>basuh semua dosa;<br/>Nurani bebas noda,<br/>ku melayani Allah.<br/>',NULL,60956,3);
INSERT INTO stanza VALUES('I175','4','Darah-Mu menyisihkan,<br/>kami pun dikuduskan;<br/>Darah-Mu jaga ''tiasa,<br/>kudus kami saksikan.<br/>Darah-Mu hapus dosa,<br/>kami pun dibenarkan;<br/>Darah-Mu b''ri tebusan,<br/>lenyap sekat dengan-Nya.<br/>',NULL,60957,4);
INSERT INTO stanza VALUES('I175','5','Oleh darah di salib,<br/>kami damai d''ngan Allah;<br/>Terbuka kemungkinan<br/>kontak persekutuan.<br/>Berbagian atas darah,<br/>ku mendapatkan hayat;<br/>Oleh darah dan hayat,<br/>nikmat damai sentosa.<br/>',NULL,60958,5);
INSERT INTO stanza VALUES('I175','6','Darah percik di surga,<br/>membela lebih mantap;<br/>Bawah naungan darah,<br/>lepas serangan setan.<br/>Sandar darah adi-Mu,<br/>kita kalahkan musuh;<br/>Terhadap si penggugat,<br/>kami menanglah mutlak.<br/>',NULL,60959,6);
INSERT INTO stanza VALUES('I175','7','Oleh darah adi-Mu,<br/>kaum saleh sekutu;<br/>Bawah naung darah-Mu,<br/>rohku bebas tak takut.<br/>Bahasa mana mampu,<br/>tutur kisah darah-Mu?<br/>Kekekalan diperlu,<br/>ungkap nilai darah-Mu.<br/>',NULL,60960,7);
INSERT INTO stanza VALUES('I176','1','Atas meja kasih-Mu,<br/>roti, cawan, terbentang;<br/>Tanda ini ''nyatakan,<br/>k''limpahan-Mu ku nikmat.<br/>Syukurku atas cawan,<br/>cawan nan berkat bah''gia;<br/>Kurnia keselamatan,<br/>darah yang sediakan.<br/>',NULL,60961,1);
INSERT INTO stanza VALUES('I176','2','Telah tumpah darah-Mu,<br/>untuk basuh dosaku;<br/>Janji baru tergenap,<br/>berkat Allah ku dapat.<br/>Cawan murka Kau minum,<br/>bagiku maut Kau tempuh;<br/>Cawan berkat tebusan,<br/>bagianku hingga kekal.<br/>',NULL,60962,2);
INSERT INTO stanza VALUES('I176','3','Jatuh jauhi Allah,<br/>diriku dalam Adam;<br/>Darah-Mu t''lah tertumpah,<br/>Allah jadi kurnia.<br/>Tebus, hayat, segala,<br/>tercakup semuanya;<br/>Rencana, murad Allah,<br/>bagiku seluruhnya.<br/>',NULL,60963,3);
INSERT INTO stanza VALUES('I176','4','Bagian kekal kami,<br/>ilahi pun berlimpah;<br/>Di dalam cawan Allah,<br/>terkecap citra surga.<br/>Cawan ini ku angkat,<br/>diri-Mu kami kenang;<br/>Dalam roh pun teresap,<br/>jasa dari Golgota<br/>',NULL,60964,4);
INSERT INTO stanza VALUES('I177','1','Tuhan, mujizatlah sungguh,<br/>satu padu Kau denganku!<br/>Ku dalam Kau, Kau dalamku;<br/>sangat ajaib! Misterius!<br/>',NULL,60965,1);
INSERT INTO stanza VALUES('I177','2','Biar ku berbagian diri-Mu,<br/>tubuh-Mu t''lah Kau korbankan;<br/>Pun agar ku lepas dosa,<br/>darah-Mu telah Kau curah.<br/>',NULL,60966,2);
INSERT INTO stanza VALUES('I177','3','Bangkit menjelma Roh Kudus,<br/>jadi hayat dalam rohku;<br/>Kau ku sesap tiap waktu,<br/>nikmat s''gala k''limpahan-Mu.<br/>',NULL,60967,3);
INSERT INTO stanza VALUES('I177','4','Tanda terbentang di meja,<br/>diri-Mu-lah kami kenang;<br/>Bersyukur atas murad-Mu,<br/>sambil ulangi tempuh-Mu.<br/>',NULL,60968,4);
INSERT INTO stanza VALUES('I177','5','Melalui roti, cawan,<br/>menikmati Kau yang mesra!<br/>Santap, sesap di dalam roh,<br/>puas, sedap, lezat, nyaman.<br/>',NULL,60969,5);
INSERT INTO stanza VALUES('I177','6','Demikian makan, minum,<br/>d''ngan roh men''rima diri-Mu,<br/>Antero penuh dengan Kau,<br/>kenangan yang s''jati sungguh!<br/>',NULL,60970,6);
INSERT INTO stanza VALUES('I178','1','Syukur atas jamuan ini,<br/>roti, cawan tersaji;<br/>Diri-Mu kami nikmati,<br/>betapa limpah ini!<br/>Tubuh-Mu-lah roti ini,<br/>kami makan di sini;<br/>Darah-Mu-lah cawan ini,<br/>kami minum di sini.<br/>',NULL,60971,1);
INSERT INTO stanza VALUES('I178','chorus','Lihat, jamuan ini!<br/>Betapa ajaib!<br/>Makna dalam pun abadi,<br/>tidak terperi!<br/>',NULL,60972,2);
INSERT INTO stanza VALUES('I178','2','Lewat wafat penebusan,<br/>berkat hayat Kau beri;<br/>Diri-Mu t''lah Kau berikan,<br/>agar kami miliki.<br/>Melalui roti, cawan,<br/>kami pamer wafat-Mu;<br/>Makan dan minum diri-Mu,<br/>kenang hingga abadi.<br/>',NULL,60973,3);
INSERT INTO stanza VALUES('I178','3','Roti ini menyatakan<br/>Tubuh-Mu nan misteri;<br/>Kami saling bersekutu,<br/>betapa esa ini.<br/>Cawan bah''gia, kudus ini,<br/>kini kami berkati;<br/>Demi darah-Mu bers''kutu,<br/>kaum saleh sehati.<br/>',NULL,60974,4);
INSERT INTO stanza VALUES('I178','4','Kaulah bagian kekal kami,<br/>kami kecap di sini;<br/>Menunggu kerajaan-Mu,<br/>datang-Mu kami nanti.<br/>Dikau datang, dalam k''rajaan,<br/>dengan saleh pemenang;<br/>Nikmati diri-Mu lagi -<br/>Mempelai nan tersayang.<br/>',NULL,60975,5);
INSERT INTO stanza VALUES('I179','1','Saat ku tatap meja-Mu,<br/>tanda menakjubkan;<br/>Satu roti, satu cawan,<br/>sesuai perkenan-Nya.<br/>',NULL,60976,1);
INSERT INTO stanza VALUES('I179','2','Roti tanda pangan hayat,<br/>makanan surgawi,<br/>Lewat wafat, Kau beriku,<br/>mengecap limpah-Mu.<br/>',NULL,60977,2);
INSERT INTO stanza VALUES('I179','3','Cawan, bagian nan ilahi,<br/>darah-Mu genapkan,<br/>Kami t''rima cawan berkat,<br/>nikmati s''gala-Nya.<br/>',NULL,60978,3);
INSERT INTO stanza VALUES('I179','4','Roti ini kami makan,<br/>Kaulah roti hayat,<br/>Demi kasih mengenang-Mu,<br/>kenyang mengecap-Mu.<br/>',NULL,60979,4);
INSERT INTO stanza VALUES('I179','5','Cawan ini kami minum,<br/>nikmat berkat Allah,<br/>Dengan riang mengenang-Mu,<br/>hingga kami t''rangkat.<br/>',NULL,60980,5);
INSERT INTO stanza VALUES('I179','6','Makan roti, minum cawan,<br/>b''ritakan wafat-Mu,<br/>Saksikan Kau hayat kami,<br/>nikmat t''rus tak henti.<br/>',NULL,60981,6);
INSERT INTO stanza VALUES('I179','7','Hari itu kami nanti,<br/>pesta bersama-Mu,<br/>Nikmati-Mu kian berlebih,<br/>kekal menyembah-Mu.<br/>',NULL,60982,7);
INSERT INTO stanza VALUES('I180','1','Di sini ku ingin jumpa Tuhan,<br/>demi iman jamah yang tak tampak.<br/>Biar lebih dalam paham kurnia-Mu,<br/>lepas letihku depan kaki-Mu.<br/>',NULL,60983,1);
INSERT INTO stanza VALUES('I180','2','Ku mau makan santapan nan limpah,<br/>serta minum cawan bahagia;<br/>Lupakan semua susah dunia,<br/>kecap lagi sentosa ampunan.<br/>',NULL,60984,2);
INSERT INTO stanza VALUES('I180','3','Meski ku berdosa, Tuhan adil;<br/>meski ku nista, darah-Mu sedia;<br/>Mohon darah-Mu basuhku bersih,<br/>adil-Mu bereskan dosaku s''mua.<br/>',NULL,60985,3);
INSERT INTO stanza VALUES('I180','4','Selain Kau, ku tiada bantuan,<br/>selain kurnia-Mu tak harap siapa;<br/>Demi kasih-Mu hatiku puas,<br/>demi kuasa-Mu berdiri tegap.<br/>',NULL,60986,4);
INSERT INTO stanza VALUES('I180','5','Sebentar saja jamuan habis,<br/>tapi kasih-Mu s''lama tak henti!<br/>Hingga sekarang Kau tetap hadir,<br/>menjadi Rajaku nan almuhit.<br/>',NULL,60987,5);
INSERT INTO stanza VALUES('I180','6','Tengok, tiang awan mulai bergerak,<br/>di padang gurun, maju ke depan;<br/>Kau memanggil, kami ikut ketat,<br/>segera masuk kota gemilang.<br/>',NULL,60988,6);
INSERT INTO stanza VALUES('I180','7','Jamuan usai kini kami bubar,<br/>hati kian damba jamuan di surga;<br/>Seb''lumnya kami sudah mengecap,<br/>pesta nikah bagi Anak Domba.<br/>',NULL,60989,7);
INSERT INTO stanza VALUES('I181','1','Tuhan, demi roti, cawan,<br/>kami pamer wafat-Mu;<br/>Teringat genap kasih-Mu,<br/>mengagumi wafat-Mu.<br/>Roti, cawan, berpisahan,<br/>bukti rampung wafat-Mu;<br/>Hati, roh, mulut serentak<br/>bersujud dan berkidung.<br/>',NULL,60990,1);
INSERT INTO stanza VALUES('I181','chorus','Getir maut Kau kecap,<br/>bahagia ku sesap!<br/>Oh, tindakan kasih-Mu,<br/>ku puji selalu!<br/>',NULL,60991,2);
INSERT INTO stanza VALUES('I181','2','Kar''na kasih Kau berdarah,<br/>membimbingku ke Allah;<br/>Tak ada lagi sekatan,<br/>bertatapan ''tiasa.<br/>Tuntutan adil dan mulia,<br/>terpenuhi semua;<br/>Wafat-Mu tinggalkan jasa,<br/>ku lapang menjamah Dia.<br/>',NULL,60992,3);
INSERT INTO stanza VALUES('I181','3','Dikau wafat, tirai belah,<br/>jalan masuk terbuka,<br/>Tersingkir aral rintangan,<br/>menghampiri gafirat.<br/>T''rima rahmat dan kurnia,<br/>bantuan tiap saat,<br/>Menyesap pada air hayat,<br/>kenyang nikmati Allah.<br/>',NULL,60993,4);
INSERT INTO stanza VALUES('I181','4','Demikian ku ditebus,<br/>hingga ku jadi imam,<br/>Nikmati s''mua limpah Allah,<br/>''layani Dia semata.<br/>Sungguh berkat! Sungguh rahmat!<br/>Oleh sebab wafat-Mu;<br/>Tak henti-henti ku ingat,<br/>sampai hari bahagia.<br/>',NULL,60994,5);
INSERT INTO stanza VALUES('I182','1','Menjelang Dikau hadapi mati,<br/>Kau berdoa agar kami esa;<br/>Moga tiap bentangkan mati-Mu,<br/>kami dapat genapkan murad-Mu.<br/>Roti satu, kami satu Tubuh,<br/>pemecahan roti, tanda itu.<br/>',NULL,60995,1);
INSERT INTO stanza VALUES('I182','2','Kami doakan semua gereja,<br/>jangan lagi kami pecah-belah;<br/>Tariklah kami saling melekat,<br/>pada-Mu kami berdamping erat.<br/>Hanya satu roti, satu Tubuh,<br/>pemecahan roti, tanda itu.<br/>',NULL,60996,2);
INSERT INTO stanza VALUES('I182','3','Kami doakan domba yang k''lana,<br/>Gembala baik, bawa m''reka pulang;<br/>Balik pada kebenaran s''mula,<br/>gereja penopang kebenaran.<br/>Kami, satu roti, satu Tubuh,<br/>pemecahan roti, tanda itu.<br/>',NULL,60997,3);
INSERT INTO stanza VALUES('I182','4','Tuhan, semua tanda akan lewat,<br/>esalah kita di Sion surga;<br/>Umat saleh sejahtera kekal,<br/>saling cinta tak berkesudahan.<br/>Giranglah beserta Putra Allah,<br/>nikmati kasih, damai s''lamanya.<br/>',NULL,60998,4);
INSERT INTO stanza VALUES('I183','1','Laknat kutuk Tuhan t''rima,<br/>tapi bah''gia ku yang rasa;<br/>Kasih dalam tak terduga,<br/>hai jiwaku, bersyukurlah!<br/>Cawan pahit Dia yang minum,<br/>jamuan kasih ku yang rasa;<br/>Kurnia besar tak terukur,<br/>hai hatiku, bersyukurlah!<br/>',NULL,60999,1);
INSERT INTO stanza VALUES('I184','1','Manusia di sisi-Mu,<br/>pada malam itu,<br/>Membawa niat yang busuk,<br/>susahkan hati-Mu.<br/>Kau pesan waktu itu:<br/>"Ingatlah pada-Ku";<br/>Kini kami berhimpun,<br/>datang mengingat-Mu.<br/>',NULL,61000,1);
INSERT INTO stanza VALUES('I184','2','Cawan murka yang pahit,<br/>Kau minum bagiku;<br/>Lembah maut yang ngeri,<br/>Kau tempuh bagiku.<br/>Kasi''an Kau di Golgota,<br/>ditinggalkan Allah,<br/>Tuhan, aku bersyukur,<br/>Kau tak ku lupakan.<br/>',NULL,61001,2);
INSERT INTO stanza VALUES('I184','3','Betapalah neraka,<br/>menyesah jiwa-Mu;<br/>Bagai ombak berg''lora,<br/>menerjang diri-Mu.<br/>Di sanalah tertampak<br/>kasih-Mu tak t''rukur;<br/>Kami, duka pun suka,<br/>datang mengingat-Mu.<br/>',NULL,61002,3);
INSERT INTO stanza VALUES('I184','4','Kami ta''u Kau t''lah bangkit,<br/>jadi buah bungar;<br/>Kami ta''u Kau di surga,<br/>jadi K''pala g''reja.<br/>Kar''na Kau ku dit''rima,<br/>jiwa, raga s''lamat;<br/>Kini kami terkenang,<br/>datang mengingat-Mu.<br/>',NULL,61003,4);
INSERT INTO stanza VALUES('I184','5','Seb''lum Kau datang pula,<br/>angkatku dari maut,<br/>Biar ku serta pada-Mu,<br/>sentosa s''lamanya.<br/>Kematian-Mu ku taulad,<br/>dan t''rus ku ''nyatakan,<br/>Ku bertekad cinta-Mu,<br/>dan ingat pada-Mu.<br/>',NULL,61004,5);
INSERT INTO stanza VALUES('I185','1','Syukur atas roti ini,<br/>pertanda ilahi;<br/>Tegas tertampak di sini,<br/>rencana misteri.<br/>',NULL,61005,1);
INSERT INTO stanza VALUES('I185','2','Roti siratkan tubuh-Mu,<br/>Kau korban bagiku;<br/>Hingga ku dapat hayat-Mu,<br/>pun dapat diri-Mu.<br/>',NULL,61006,2);
INSERT INTO stanza VALUES('I185','3','Terkoyak sudah tubuh-Mu,<br/>tersalur diri-Mu;<br/>Diri-Mu jadi hayatku,<br/>ku jadi jodoh-Mu.<br/>',NULL,61007,3);
INSERT INTO stanza VALUES('I185','4','Roti juga menyiratkan<br/>Tubuh misteri-Mu;<br/>Kami anggota Tubuh-Mu,<br/>mutlak esa d''ngan-Mu.<br/>',NULL,61008,4);
INSERT INTO stanza VALUES('I185','5','Meski kami banyak butir,<br/>tapi satu roti;<br/>Demikian mengenang-Mu,<br/>dapatkan suplai-Mu.<br/>',NULL,61009,5);
INSERT INTO stanza VALUES('I185','6','Oleh roti bersekutu,<br/>puaslah hati-Mu;<br/>Umat saleh persaksikan,<br/>kaya pun limpah-Mu.<br/>',NULL,61010,6);
INSERT INTO stanza VALUES('I186','1','Pesta kasih Allah<br/>dari karunia;<br/>Nikmati roti dan anggur,<br/>kami mengingat-Mu.<br/>',NULL,61011,1);
INSERT INTO stanza VALUES('I186','2','Semoga di sini<br/>kami bisa nampak;<br/>Niat Bapa terhadap-Mu,<br/>dan karunia-Mu.<br/>',NULL,61012,2);
INSERT INTO stanza VALUES('I186','3','Rohku puas kini,<br/>hati pun bersaksi;<br/>Roti hayat sedap,<br/>limpah, menyuplai ''tiasa.<br/>',NULL,61013,3);
INSERT INTO stanza VALUES('I186','4','Nurani tak cela,<br/>iman gita lantang;<br/>Darah adi penebusan,<br/>puaskan tuntutan.<br/>',NULL,61014,4);
INSERT INTO stanza VALUES('I186','5','Nikmat pesta ini,<br/>ilahi nan manis;<br/>Kelak bersama-Mu lagi,<br/>manisnya tak terp''ri.<br/>',NULL,61015,5);
INSERT INTO stanza VALUES('I186','6','Saat jumpa kelak,<br/>kenakan mulia-Mu;<br/>Ajaib karunia-Mu,<br/>kekal kesaksianku.<br/>',NULL,61016,6);
INSERT INTO stanza VALUES('I187','1','Kar''na cawan dan roti,<br/>Putra merendah diri,<br/>Hingga kurnia berlebih.<br/>Tuhan t''rima kasih!<br/>',NULL,61017,1);
INSERT INTO stanza VALUES('I187','2','Demi cawan dan roti,<br/>imanku t''lah mengerti,<br/>Kasih Allah tak terp''ri.<br/>Tuhan, t''rima kasih!<br/>',NULL,61018,2);
INSERT INTO stanza VALUES('I187','3','Kar''na Kau t''lah memanggil,<br/>ku datang Kau berkati,<br/>Demi iman berhampir.<br/>Tuhan, t''rima kasih!<br/>',NULL,61019,3);
INSERT INTO stanza VALUES('I187','4','Pesan telah Kau beri,<br/>ingat Tuhan di bumi,<br/>Sungguh ramah dan miskin.<br/>Tuhan, t''rima kasih!<br/>',NULL,61020,4);
INSERT INTO stanza VALUES('I187','5','Kar''na Kau demi kasih,<br/>ingin pulang ku kini,<br/>Menunggu Kau kembali.<br/>Tuhan, t''rima kasih!<br/>',NULL,61021,5);
INSERT INTO stanza VALUES('I187','6','Hingga Kau datang lagi,<br/>ku cabik roti ini,<br/>''Nyatakan hayat Kau b''ri.<br/>Tuhan, t''rima kasih!<br/>',NULL,61022,6);
INSERT INTO stanza VALUES('I187','7','Hingga Kau datang lagi,<br/>ku minum cawan ini,<br/>Berkat mulia Kau beri.<br/>Tuhan, t''rima kasih!<br/>',NULL,61023,7);
INSERT INTO stanza VALUES('I187','8','Kau segera kembali,<br/>harinya telah hampir,<br/>K''rajaan-Mu berdiri.<br/>Tuhan, t''rima kasih!<br/>',NULL,61024,8);
INSERT INTO stanza VALUES('I188','1','Kristus mulia s''mula ada,<br/>sejak azali ada;<br/>Jagat raya belum ada,<br/>Dia Bapa nan kekal.<br/>Tak berawal, tak berakhir,<br/>tak berayah dan bunda;<br/>Tak berubah, tak bersudah,<br/>dulu, kini, pun kelak.<br/>',NULL,61025,1);
INSERT INTO stanza VALUES('I188','2','Kristus mulia, Sang Pencipta,<br/>sumber satu-satunya;<br/>Sang Kuasa, Sang Kepala,<br/>pula Yang terutama;<br/>P''rintah-Nya topang segala,<br/>menyatukan segala;<br/>Allah t''lah menunjuk Dia,<br/>mewarisi s''galanya.<br/>',NULL,61026,2);
INSERT INTO stanza VALUES('I188','3','Kristus mulia, inkarnasi,<br/>berkemah tengah insan;<br/>Dari gadis Dia terlahir,<br/>tampil Allah dari-Nya;<br/>Allah-insan rendah hati,<br/>kenakan rupa hamba;<br/>Dia pancaran cah''ya Allah,<br/>pun citra hakiki-Nya.<br/>',NULL,61027,3);
INSERT INTO stanza VALUES('I188','4','Kristus mulia disalibkan,<br/>rela menanggung dosa;<br/>Dihukum, diganjar Allah,<br/>getir maut dikecap.<br/>Orang lama disalibkan,<br/>musnahkan Iblis, Satan;<br/>Ku terlepas dari dosa,<br/>dari semua perangkap.<br/>',NULL,61028,4);
INSERT INTO stanza VALUES('I188','5','Kristus mulia bangkit sudah,<br/>menjadi buah sulung;<br/>Dia juga bangkitkanku,<br/>beri hayat padaku.<br/>Dia-lah sebutir gandum,<br/>kita perbanyakan-Nya;<br/>Jadi para saudara-Nya,<br/>satu sumber dengan-Nya.<br/>',NULL,61029,5);
INSERT INTO stanza VALUES('I188','6','Kristus mulia, menjadi Roh,<br/>di rohku jadi hayat;<br/>Ku berbagian sifat Allah,<br/>ilahi seperti Dia.<br/>Di dalamku tumbuh besar,<br/>serupa ku dengan-Nya;<br/>Menikmati limpah Allah,<br/>jadi perawakan-Nya.<br/>',NULL,61030,6);
INSERT INTO stanza VALUES('I188','7','Kristus mulia naik surga,<br/>melampaui segala;<br/>Terhormat, mulia, mahkota,<br/>Mahatinggi nama-Nya.<br/>Dia bawaku naik atas,<br/>duduk sama di surga;<br/>Berbagian atas kuasa-Nya,<br/>tinggi, kuat, sama Dia.<br/>',NULL,61031,7);
INSERT INTO stanza VALUES('I188','8','Kristus mulia, curah Roh-Nya,<br/>berdirilah gereja;<br/>Beri fungsi dan talenta,<br/>untuk bangun Tubuh-Nya.<br/>Rawat, asuh, sayang g''reja,<br/>tertampil lewat g''reja;<br/>G''reja kembang-biakkan Dia,<br/>berkembang di semesta.<br/>',NULL,61032,8);
INSERT INTO stanza VALUES('I188','9','Kristus mulia, datang pula,<br/>jemput umat tebus-Nya;<br/>Tumpas musuh, ganjar bangsa,<br/>dirikan K''rajaan-Nya.<br/>Bawa umat memerintah,<br/>sampai ujung buana;<br/>Penuh damai, penuh gita,<br/>tent''ram damai sentosa.<br/>',NULL,61033,9);
INSERT INTO stanza VALUES('I188','10','Kristus mulia, pusat s''gala,<br/>menyunting kota suci;<br/>Langit, bumi dibarui,<br/>usang terbasmi bersih.<br/>Allah terang, Dia dian,<br/>atas-Nya Allah tampil;<br/>Kota suci ekspresi-Nya,<br/>penuh Dia abadi.<br/>',NULL,61034,10);
INSERT INTO stanza VALUES('I189','1','Kidung baru bagilah Domba,<br/>mulia, mulia bagi Tuhan!<br/>Injil-Nya bawa b''rita girang!<br/>Mulia bagi Tuhan!<br/>Kristus lahir dalam malaf,<br/>datang menebus kami s''mua.<br/>Betapa bodoh pun kami,<br/>juga dapat bersyukur.<br/>',NULL,61035,1);
INSERT INTO stanza VALUES('I189','chorus','Sorak-sorai kami memuji,<br/>mulia, mulia bagi Tuhan!<br/>Kidung baru t''rus membubung,<br/>mulia bagi Tuhan.<br/>',NULL,61036,2);
INSERT INTO stanza VALUES('I189','2','Dengarlah nyanyian surga datang.<br/>Mulia, mulia bagi Tuhan!<br/>Allah itu terang dan cinta.<br/>Mulia bagi Tuhan!<br/>Orang berdosa yang duka,<br/>merana tiada sentosa,<br/>Tidak peduli kau siapa,<br/>hutangmu t''lah Ia bayar.<br/>',NULL,61037,3);
INSERT INTO stanza VALUES('I189','3','Bersoraklah, hukuman lalu.<br/>Mulia, mulia bagi Tuhan!<br/>Serta Tuhan kami t''lah bangkit.<br/>Mulia bagi Tuhan!<br/>Meski kami sampai kubur,<br/>tak sampai jatuh dalam maut,<br/>Semua musuh t''lah terbenam,<br/>kar''na Tuhan berkuasa.<br/>',NULL,61038,4);
INSERT INTO stanza VALUES('I189','4','Dia datang sambut para saleh.<br/>Mulia, mulia bagi Tuhan!<br/>Gereja sudahlah sempurna.<br/>Mulia bagi Tuhan!<br/>Kini nampak yang diminta,<br/>dan b''roleh yang didambakan,<br/>Niat kami hanya pada-Nya,<br/>d''ngan Dia kami sejalan.<br/>',NULL,61039,5);
INSERT INTO stanza VALUES('I189','5','Bersorak-sorak lebih nyaring.<br/>Mulia, mulia bagi Tuhan!<br/>Kidung ini t''rus dinyanyikan.<br/>Mulia bagi Tuhan!<br/>Berkidung dengan hati riang,<br/>hingga ke s''gala penjuru,<br/>Orang yang terlahir baru,<br/>menyanyi tidak henti.<br/>',NULL,61040,6);
INSERT INTO stanza VALUES('I190','1','Puji! Puji! Puji Yesus Juru-tebus!<br/>Kami bers''ru nyatakan kasih-Nya.<br/>Puji Tuhan! Para malaikat bersujud!<br/>Hormat, mulia bagi Nama kudus!<br/>P''ri gembala, Tuhan merawat kami,<br/>dalam ribaan-Nya kami aman.<br/>',NULL,61041,1);
INSERT INTO stanza VALUES('I190','chorus','Puji! Puji! Puji kasih-Nya yang ajaib!<br/>Puji! Puji! Nama-Nya yang kudus.<br/>',NULL,61042,2);
INSERT INTO stanza VALUES('I190','2','Puji! Puji! Puji Yesus Juru-tebus!<br/>Kar''na dosa kami, Dia terhukum;<br/>Puji Tuhan! Dia-lah Batu Karang teguh,<br/>G''nap tebusan, mati bagi kami!<br/>Puji Tuhan! Dia tanggung duka kami!<br/>Kasih ini ajaib, tulus, limpah.<br/>',NULL,61043,3);
INSERT INTO stanza VALUES('I190','3','Puji! Puji! Puji Yesus Juru-tebus!<br/>Suara kami membubung: "Hosana!"<br/>Kristus Yesus membangkitkan s''gala makhluk;<br/>Mahkotailah: Tuhan, Imam, Raja!<br/>Kristus Yesus dirikan kerajaan;<br/>Mulia, kuasa bagilah, Sang Raja!<br/>',NULL,61044,4);
INSERT INTO stanza VALUES('I191','1','Sang Pengasih, Sang Perahmat,<br/>limpah kurnia atas s''mua;<br/>Curah darah, selamatkan,<br/>korban jiwa, b''ri hayat;<br/>Moga mulia, k''rajaan,<br/>bagi Dia hingga kekal.<br/>',NULL,61045,1);
INSERT INTO stanza VALUES('I192','1','Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku sembah!<br/>Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku sembah!<br/>',NULL,61046,1);
INSERT INTO stanza VALUES('I192','2','Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku puji!<br/>Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku puji!<br/>',NULL,61047,2);
INSERT INTO stanza VALUES('I192','3','Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku syukur!<br/>Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku syukur!<br/>',NULL,61048,3);
INSERT INTO stanza VALUES('I192','4','Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku junjung!<br/>Hanya Tuhan, hanya Tuhan,<br/>Yesus Juru-selamat, ku junjung!<br/>',NULL,61049,4);
INSERT INTO stanza VALUES('I193','1','Semua hormat, mulia, kaya,<br/>bagi Domba hingga kekal!<br/>Yesus Kristus Penolongku!<br/>Haleluya! Haleluya!<br/>Haleluya, puji Dia!<br/>',NULL,61050,1);
INSERT INTO stanza VALUES('I194','1','Roh Allah kini Roh Kristus,<br/>menjadi Roh realitas,<br/>Dia, Kristus tinggal di rohku,<br/>menyuplaikan realitas.<br/>',NULL,61051,1);
INSERT INTO stanza VALUES('I194','2','Kristus jelmaan Sang Allah,<br/>menyatakan kudus Allah;<br/>Roh ini jelmaan Kristus,<br/>wahyukan Kristus hayatku.<br/>',NULL,61052,2);
INSERT INTO stanza VALUES('I194','3','Limpah kaya Allah Bapa,<br/>bulat nyata pada Kristus;<br/>Kekayaan diri Kristus,<br/>nyata riil di dalam Roh.<br/>',NULL,61053,3);
INSERT INTO stanza VALUES('I194','4','Dalam Putra, Bapa tampil,<br/>Roh realitas, Kristus kini;<br/>Bapa sumber, Putra alir,<br/>Roh mengalir, suplai jadi.<br/>',NULL,61054,4);
INSERT INTO stanza VALUES('I194','5','Insan batin, Roh kuatkan,<br/>di hatiku Kristus s''mayam;<br/>Limpah kaya Allah Bapa,<br/>penuhiku seluruhnya.<br/>',NULL,61055,5);
INSERT INTO stanza VALUES('I194','6','Dalam Putra, dapat Bapa,<br/>penuhi s''mua kebutuhan;<br/>Dalam Roh alami Putra,<br/>Sang Hayat pun Sang Segala.<br/>',NULL,61056,6);
INSERT INTO stanza VALUES('I194','7','Demi realitas nan kudus,<br/>mohon Roh-Mu penuhiku;<br/>Agar daku penuh Dikau,<br/>nikmat limpah-Mu sepenuh.<br/>',NULL,61057,7);
INSERT INTO stanza VALUES('I195','1','Tekun menunggu,<br/>berdoa depan Tuhan,<br/>mengharap lepas dari dosa;<br/>Tuhan b''ri rahmat,<br/>mengabulkan doaku,<br/>Roh Kudus di hatiku.<br/>',NULL,61058,1);
INSERT INTO stanza VALUES('I195','chorus','Roh Kudus di hatiku,<br/>Roh Kudus bebaskanku,<br/>Ku lepas dari dosa, hati,<br/>mulut memuja,<br/>Roh Kudus di hatiku.<br/>',NULL,61059,2);
INSERT INTO stanza VALUES('I195','2','Ku wadah lemah,<br/>cacat, dan tiada guna,<br/>meski ku sadar harus kuat;<br/>Tuhan b''ri rahmat,<br/>penuh girang hatiku,<br/>Roh Kudus di hatiku.<br/>',NULL,61060,3);
INSERT INTO stanza VALUES('I195','3','Kini ku jadi saksi<br/>kuasa Roh Kudus,<br/>kar''na hatiku t''lah terbuka;<br/>Lepas sikap congkak,<br/>serta tingkah dosa,<br/>Roh Kudus di hatiku.<br/>',NULL,61061,4);
INSERT INTO stanza VALUES('I195','4','Kini ku yakin,<br/>dapat pandang wajah-Nya,<br/>kar''na Tuhan basuhku bersih;<br/>Tuhan di rohku,<br/>jadi kurnia nan cukup,<br/>Roh Kudus di hatiku.<br/>',NULL,61062,5);
INSERT INTO stanza VALUES('I196','1','Roh Allah hari ini,<br/>jadi Roh Yesus Kristus;<br/>Manusia - Allah bangkit,<br/>mulia, t''rangkat, jadi Roh.<br/>',NULL,61063,1);
INSERT INTO stanza VALUES('I196','2','Dari Yesus nan t''rangkat,<br/>masuk rohku Roh ini,<br/>Segala realitas-Nya,<br/>boleh aku alami.<br/>',NULL,61064,2);
INSERT INTO stanza VALUES('I196','3','Roh Yesus Kristus ini,<br/>kadar apa pun ada;<br/>Allah, insan, dalam-Nya,<br/>lengkap rangkum tak kurang.<br/>',NULL,61065,3);
INSERT INTO stanza VALUES('I196','4','Daya maut dan d''rita,<br/>daya bangkit dan t''rangkat,<br/>Takhta, kuasa, k''rajaan,<br/>terlingkup Roh ini s''mua.<br/>',NULL,61066,4);
INSERT INTO stanza VALUES('I196','5','Kadar semua digarap,<br/>oleh Roh dalam rohku;<br/>Demi urapan minyak,<br/>limpah Tuhan ku nikmat.<br/>',NULL,61067,5);
INSERT INTO stanza VALUES('I196','6','Roh nan almuhit ini,<br/>kunci s''gala rahasia;<br/>Bekerja t''rus di batin,<br/>Allah jadi s''galanya.<br/>',NULL,61068,6);
INSERT INTO stanza VALUES('I197','1','Wartakan ke tempat<br/>yang ada manusia,<br/>asal ada orang,<br/>asal ada minat.<br/>Mari giat siar<br/>kabar sukacita,<br/>Pembela t''lah tiba!<br/>',NULL,61069,1);
INSERT INTO stanza VALUES('I197','chorus','Pembela t''lah tiba!<br/>Pembela t''lah tiba!<br/>Terkabul janji-Nya,<br/>Roh Kudus tercurah!<br/>Wartakan ke tempat<br/>yang ada manusia,<br/>Pembela t''lah tiba!<br/>',NULL,61070,2);
INSERT INTO stanza VALUES('I197','2','Malam panjang lewat,<br/>jelang fajar ''rekah,<br/>Henti tangis isak,<br/>usai sedu-sedan,<br/>Terbit sinar emas,<br/>memancar gemilang;<br/>Pembela t''lah tiba!<br/>',NULL,61071,3);
INSERT INTO stanza VALUES('I197','3','Tengoklah Sang Raja,<br/>bawa kesembuhan,<br/>Tawanan rohani,<br/>dapat bebas mutlak,<br/>Penjara pun hampa,<br/>sorak kemenangan;<br/>Pembela t''lah tiba!<br/>',NULL,61072,4);
INSERT INTO stanza VALUES('I197','4','Kasih nan ilahi,<br/>sungguh tak terhingga!<br/>Bagi yang berk''lana,<br/>terungkap kasih-Nya,<br/>Pada orang dosa,<br/>Kau justru beserta!<br/>Pembela t''lah tiba!<br/>',NULL,61073,5);
INSERT INTO stanza VALUES('I197','5','Terdengar kumandang<br/>tembus cakrawala,<br/>Malak, tent''ra surga<br/>bersahut-sahutan,<br/>Kasih tak bersudah,<br/>gitaku  melantang!<br/>Pembela t''lah tiba!<br/>',NULL,61074,6);
INSERT INTO stanza VALUES('I198','1','Orang lihat Engkau hanya<br/>orang Nazaret biasa;<br/>Diremehkan dan dihina, disalib korban jiwa.<br/>Orang lihat sejarah-Mu, tamat di sini saja.<br/>',NULL,61075,1);
INSERT INTO stanza VALUES('I198','2','Beda suasana surga,<br/>tatkala Kau terangkat,<br/>Engkau taat, Allah titah<br/>alam s''mesta sedia,<br/>Siap sambut, siap sorak,<br/>Kau Kepala semesta.<br/>',NULL,61076,2);
INSERT INTO stanza VALUES('I198','3','Allah telah tetapkan Kau,<br/>jadi Kristus dan Tuhan,<br/>Surga, bumi, mana saja,<br/>semua kenal diri-Mu,<br/>Tiada yang tak bersujud,<br/>tiada yang tak patuh.<br/>',NULL,61077,3);
INSERT INTO stanza VALUES('I198','4','Yang terjadi dalam surga,<br/>bagaimana ku paham?<br/>Agar fakta dibuktikan,<br/>Roh Kudus diutus-Nya,<br/>Padaku jadi karunia,<br/>bukti Yesus berkuasa.<br/>',NULL,61078,4);
INSERT INTO stanza VALUES('I198','5','Roh Kudus tinggal dalamku,<br/>bukti Yesuslah Kristus,<br/>Allah angkat Yesus Kristus,<br/>tercurahlah ROh Kudus;<br/>Kekal riil, kekal teguh,<br/>orang Nazaret, Tuhan.<br/>',NULL,61079,5);
INSERT INTO stanza VALUES('I198','6','Yesus Tuhan! Yesus Tuhan!<br/>Fakta kekal tak ubah!<br/>Kepadaku Roh tercurah,<br/>fakta wujud karunia;<br/>Kini hanya puji gita,<br/>Roh mulai berperan.<br/>',NULL,61080,6);
INSERT INTO stanza VALUES('I199','1','Tuhan mulia, Kau pernah<br/>curahkan Roh Kudus-Mu;<br/>Aneka karunia,<br/>tercurah atas g''reja;<br/>Berdasar setia-Mu,<br/>mohon ulang kurnia-Mu.<br/>',NULL,61081,1);
INSERT INTO stanza VALUES('I199','2','Baptis dalam nama-Mu,<br/>satu roh ku dengan-Mu;<br/>Tubuh-Mu telah raih,<br/>karunia dan hasil;<br/>Aku juga anggota,<br/>turut dapat kuasa.<br/>',NULL,61082,2);
INSERT INTO stanza VALUES('I199','3','B''ri kuasa buktikan,<br/>nama-Mu mahabesar;<br/>B''ri karunia siarkan,<br/>karya keselamatan;<br/>B''ri kiat pelayanan,<br/>agar umat-Mu menang.<br/>',NULL,61083,3);
INSERT INTO stanza VALUES('I199','4','Ku ditumpangi tangan,<br/>saat tuturkan minat;<br/>Saat harap karunia,<br/>mohon demi fakta-Mu;<br/>Curah kuasa tak hingga,<br/>agar semua berdaya.<br/>',NULL,61084,4);
INSERT INTO stanza VALUES('I200','1','Kini Sang Roh Kudus Allah,<br/>adalah Roh hayat Allah;<br/>Menghidupkan pun b''ri hayat,<br/>sesuai dengan murad Allah.<br/>',NULL,61085,1);
INSERT INTO stanza VALUES('I200','2','Dia, air hayat, lerai dah''ga,<br/>suplai hayat hingga kekal;<br/>Salur Kristus Sang Alhayat,<br/>harapanku Dia genapkan.<br/>',NULL,61086,2);
INSERT INTO stanza VALUES('I200','3','Terang hayat b''ri sorotan,<br/>usir gelap, bersih cerah;<br/>Salur Kristus Sang T''rang hayat,<br/>hingga malam jadi siang.<br/>',NULL,61087,3);
INSERT INTO stanza VALUES('I200','4','Kuasa hayat menguatkan,<br/>insan batin tangguh tegap;<br/>Salur Kristus Sang Tenaga,<br/>laksanakan rencana-Nya.<br/>',NULL,61088,4);
INSERT INTO stanza VALUES('I200','5','Oleh hukum hayat Allah,<br/>dari dosa ku terlepas;<br/>Oleh sifat kudus Allah,<br/>di dalamku ubah, garap.<br/>',NULL,61089,5);
INSERT INTO stanza VALUES('I200','6','Dia-lah Roh hayat Allah,<br/>lewatku berbuah lebat;<br/>Ekspresikan budi Allah,<br/>salur Kristus lewat hayat.<br/>',NULL,61090,6);
INSERT INTO stanza VALUES('I200','7','Sang Roh hayat suplai hayat,<br/>oleh hayat ku terubah;<br/>Perbarui tiap bagian,<br/>mirip Kristus tiada beda.<br/>',NULL,61091,7);
INSERT INTO stanza VALUES('I200','8','Mohon Kau demi Roh hayat,<br/>penuhi tiap p''losokku;<br/>Resap jenuh seluruhnya,<br/>hingga ternyata hayat-Mu.<br/>',NULL,61092,8);
INSERT INTO stanza VALUES('I201','1','Perigi mancurlah!<br/>Ku mau tergali!<br/>Buang s''mua hambatan,<br/>air hayat ''ngalir!<br/>',NULL,61093,1);
INSERT INTO stanza VALUES('I201','2','Karang t''lah terbelah,<br/>air hayat luap;<br/>Dalam kalbu beta,<br/>sayang tersumbat.<br/>',NULL,61094,2);
INSERT INTO stanza VALUES('I201','3','Doa gali p''rigi,<br/>lumpur tersingkir;<br/>Hingga k''luar Roh Kudus,<br/>air hayat ''ngalir.<br/>',NULL,61095,3);
INSERT INTO stanza VALUES('I201','4','Doa terus doa,<br/>gali dan gali!<br/>Gali sampai tuntas,<br/>doa pun mahir.<br/>',NULL,61096,4);
INSERT INTO stanza VALUES('I201','5','Karang telah belah,<br/>ku hanya gali;<br/>Air hayat sedia,<br/>asal ku ''ngalir.<br/>',NULL,61097,5);
INSERT INTO stanza VALUES('I201','6','Roh Kudus atasku,<br/>itu curahan;<br/>Roh Kudus dalamku,<br/>sumber air hayat.<br/>',NULL,61098,6);
INSERT INTO stanza VALUES('I201','7','Yang paling ku perlu,<br/>tak hanya curah;<br/>Bahkan doa tekun,<br/>buka pancaran.<br/>',NULL,61099,7);
INSERT INTO stanza VALUES('I201','8','Gali sampai bersih,<br/>roh leluasa;<br/>Gali sampai ''ngalir,<br/>sungai air hayat.<br/>',NULL,61100,8);
INSERT INTO stanza VALUES('I201','9','Perigi mancurlah!<br/>Ku mau tergali!<br/>Buang s''mua hambatan,<br/>air hayat ''ngalir!<br/>',NULL,61101,9);
INSERT INTO stanza VALUES('I202','1','Di padang gurun Sin, bani Israel,<br/>haus hampir mati, p''rintah Allah b''ri:<br/>Suruh batu pancarkan air!<br/>Batu t''lah belah, tak pukul lagi,<br/>Cukup menyuruhnya mengalir.<br/>',NULL,61102,1);
INSERT INTO stanza VALUES('I202','chorus','Suruh batu, alir air hayat!<br/>Roh Kudus suplai, sertamu ''tiasa;<br/>Semua limpah-Nya tersedia lengkap,<br/>asal kau taat, pasti men''rima.<br/>',NULL,61103,2);
INSERT INTO stanza VALUES('I202','2','Batu kekal kini, tetap terbelah,<br/>karunia Roh Allah tetap ''nantikan;<br/>Apa hasil dari meronta?<br/>Mati dengan-Nya, lepas dahaga;<br/>Dapatkan Roh Kudus di Yordan.<br/>',NULL,61104,3);
INSERT INTO stanza VALUES('I202','3','Moga hati tulus, percaya mutlak!<br/>Hati damai tent''ram, tak rengek, resah!<br/>Sep''ri bayi di pangku-n-Nya,<br/>sapih dunia, sesap cinta-Nya;<br/>Roh teduhlah, penuh oleh-Nya.<br/>',NULL,61105,4);
INSERT INTO stanza VALUES('I203','1','Aliran air hayat,<br/>mengalir dari takhta,<br/>Mengalir penuh berkat,<br/>dari Kristus datangnya.<br/>',NULL,61106,1);
INSERT INTO stanza VALUES('I203','chorus','Aliran air hayat!<br/>Siapa mau, minumlah!<br/>Mengalir luap lewatku,<br/>pada s''mua yang dahaga.<br/>',NULL,61107,2);
INSERT INTO stanza VALUES('I203','2','Air jernih p''ri kristal,<br/>suplai di sini limpah;<br/>Yang dahaga datanglah,<br/>ambillah tanpa bayar.<br/>',NULL,61108,3);
INSERT INTO stanza VALUES('I203','3','Bersihkanlah ku, Tuhan,<br/>biar jadi saluran-Mu;<br/>Hampakan dan isilah,<br/>biar ku taat, percaya.<br/>',NULL,61109,4);
INSERT INTO stanza VALUES('I203','4','Demikian, ya, Tuhan,<br/>aliran baru lancar;<br/>Demikian, ya, Tuhan,<br/>k''limpahan-Mu dikenal.<br/>',NULL,61110,5);
INSERT INTO stanza VALUES('I203','5','Kini s''mua ku sembahkan,<br/>pada Yesus Tuhanku;<br/>Hanya satu minatku,<br/>mengalirkan air hayat.<br/>',NULL,61111,6);
INSERT INTO stanza VALUES('I204','1','Air hayat p''ri kristal,<br/>dari takhta di surga;<br/>Bawa kuasa, sekutu,<br/>ke segala penjuru.<br/>',NULL,61112,1);
INSERT INTO stanza VALUES('I204','chorus','Mengalir air hayat,<br/>menembus ke mana pun;<br/>Bawa kuasa sekutu,<br/>ke segala penjuru.<br/>',NULL,61113,2);
INSERT INTO stanza VALUES('I204','2','Air hayat itu Roh,<br/>Allah jadilah hayat;<br/>Bawa kuasa ''ngalirnya,<br/>sampai ke mana-mana.<br/>',NULL,61114,3);
INSERT INTO stanza VALUES('I204','3','''Ngalir di jalan emas,<br/>pertanda letak jalan; ''<br/>Ngalir di sifat Allah,<br/>di sana ada jalan.<br/>',NULL,61115,4);
INSERT INTO stanza VALUES('I204','4','Pohon hayat di tepian,<br/>Allah jadi santapan;<br/>Air hayat memancar,<br/>suplai tak akan asat.<br/>',NULL,61116,5);
INSERT INTO stanza VALUES('I204','5','Tuhan, Kau pernah terb''lah,<br/>alirkan air hayat;<br/>Ku pun rela dipecah,<br/>air hayat ''ngalirlah.<br/>',NULL,61117,6);
INSERT INTO stanza VALUES('I205','1','Air hayat ''ngalir deras,<br/>dari bait mulia;<br/>Melintas pintu utama,<br/>pun garis pemisahan.<br/>',NULL,61118,1);
INSERT INTO stanza VALUES('I205','chorus','Air hayat Allah,<br/>bawa suplaian segar;<br/>Telan maut tanpa sisa,<br/>nyata hayat nan limpah.<br/>',NULL,61119,2);
INSERT INTO stanza VALUES('I205','2','Laju deras air hayat,<br/>demi mulia ilahi;<br/>Persembahkan s''mua di mezbah,<br/>paling utama ini.<br/>',NULL,61120,3);
INSERT INTO stanza VALUES('I205','3','Air hayat, tiada batas,<br/>Allah takar semua;<br/>Ditakar, dihakimi-Nya,<br/>semua jadi milik-Nya.<br/>',NULL,61121,4);
INSERT INTO stanza VALUES('I205','4','Air hayat makin deras,<br/>jadi sungai membual;<br/>Insan tak lagi berdaya,<br/>kecuali sandar kurnia.<br/>',NULL,61122,5);
INSERT INTO stanza VALUES('I206','1','Pernahkah ku mendukakan Roh?<br/>Undur, tawar, berk''lana?<br/>Tidakkah segala dosaku,<br/>menjemukan hati-Nya?<br/>',NULL,61123,1);
INSERT INTO stanza VALUES('I206','chorus','Moga Roh Kudus kian bertambah,<br/>menyorot dan membakar;<br/>Dengan Kau sebagai hayatku,<br/>aku berdoa s''lalu.<br/>',NULL,61124,2);
INSERT INTO stanza VALUES('I206','2','Betapa Roh-Mu t''lah bersabar,<br/>menanti ku bertobat;<br/>Pernahkah ku tolak cinta-Mu,<br/>waktu Kau rindukanku?<br/>',NULL,61125,3);
INSERT INTO stanza VALUES('I206','3','Roh Kudus-Mu dalam hatiku,<br/>jadi Tuhan bagiku;<br/>Ku dapat berbakti selalu,<br/>kar''na cinta pada-Mu.<br/>',NULL,61126,4);
INSERT INTO stanza VALUES('I206','4','Meski ku tak cinta pada-Mu,<br/>p''ri Kau cinta padaku;<br/>Bila apinya Kau nyalakan,<br/>cintaku ''kan berkobar.<br/>',NULL,61127,5);
INSERT INTO stanza VALUES('I207','1','Allah b''ri kekuatan,<br/>pada hati m''rana;<br/>Jagaku tiap saat,<br/>curah d''ngan kurnia,<br/>Roh-Nya diam dalamku<br/>kendali seluruh;<br/>''Nyala api kasih,<br/>membakar hatiku.<br/>',NULL,61128,1);
INSERT INTO stanza VALUES('I207','chorus','Bakar di hatiku,<br/>bakar di hatiku;<br/>Api surgawi t''rus<br/>bakar di hatiku!<br/>Roh Kudus datanglah,<br/>puji nama Tuhan;<br/>Api surgawi t''rus<br/>bakar di hatiku!<br/>',NULL,61129,2);
INSERT INTO stanza VALUES('I207','2','Di salib ku tunduk,<br/>di mezbah terletak;<br/>Segenap milikku,<br/>serah pada Tuhan.<br/>Tuhan bayar harga,<br/>ku b''roleh sentosa;<br/>Turun api surga,<br/>kurbanku dikenan.<br/>',NULL,61130,3);
INSERT INTO stanza VALUES('I207','3','Aku tiada jasa,<br/>hanya janji Allah,<br/>Putra tanggung ganjar,<br/>ku jadi anak-Nya.<br/>Mulia bagi Allah,<br/>haleluya, amin;<br/>Kasih-Nya membara,<br/>membara di hati.<br/>',NULL,61131,4);
INSERT INTO stanza VALUES('I208','1','Tuhan. tangan ku angkat,<br/>mohon b''ri Roh membara,<br/>Bakar, hingga tiada<br/>satu pun bagi aku.<br/>',NULL,61132,1);
INSERT INTO stanza VALUES('I208','chorus','Curahkan Roh membara,<br/>jadi perkara besar,<br/>Puaskan tuntutan s''mua,<br/>bakarlah tanpa sisa,<br/>Tunggu, kami<br/>menunggu Roh membara.<br/>',NULL,61133,2);
INSERT INTO stanza VALUES('I208','2','Atas mezbah ku serah,<br/>genap roh, jiwa, raga,<br/>Singkirkan nafsu jahat,<br/>tiap p''losok Kau garap.<br/>',NULL,61134,3);
INSERT INTO stanza VALUES('I208','3','Ku rela menyerahkan<br/>hidupku seluruhnya,<br/>Bagi Tuhan mustika,<br/>kar''na tebusan darah.<br/>',NULL,61135,4);
INSERT INTO stanza VALUES('I208','4','Demi iman ku pegang<br/>hak pemberian darah,<br/>Sandar nama Sang Menang,<br/>s''mua janji tentu genap.<br/>',NULL,61136,5);
INSERT INTO stanza VALUES('I209','1','Yesus, kasih-Mu nan jaya,<br/>tercurah di manah,<br/>Niscaya ku tak tergoyah,<br/>berakar di Allah,<br/>berakar di Allah.<br/>',NULL,61137,1);
INSERT INTO stanza VALUES('I209','2','Api kudus di hatiku,<br/>moga berkobar t''rus;<br/>Membakar barang lahirku,<br/>gunung pun terlebur,<br/>gunung pun terlebur.<br/>',NULL,61138,2);
INSERT INTO stanza VALUES('I209','3','Api mezbah telah turun,<br/>bakarlah dosaku;<br/>Pada Roh Bakar ku bers''ru:<br/>penuhi hatiku!<br/>Penuhi hatiku!<br/>',NULL,61139,3);
INSERT INTO stanza VALUES('I209','4','Api penguji ku sambut,<br/>yang usang terhangus;<br/>Sebar hayat di tiap p''losok,<br/>kuduslah seluruh,<br/>kuduslah seluruh.<br/>',NULL,61140,4);
INSERT INTO stanza VALUES('I209','5','Hati goncang, mohon papah,<br/>biar p''ri tebing tangguh;<br/>Kristus jadi duniaku,<br/>hati kasih m''lulu,<br/>hati kasih m''lulu.<br/>',NULL,61141,5);
INSERT INTO stanza VALUES('I210','1','Padaku, hembuslah Roh-Mu,<br/>ajarku menghirup-Mu;<br/>Ke pangkuan-Mu ku acu,<br/>dosaku dan diriku.<br/>',NULL,61142,1);
INSERT INTO stanza VALUES('I210','chorus','Ku hembuskan dukacita,<br/>dosa, nistaku;<br/>Ku hirup dan hirup saja,<br/>genap limpah-Mu.<br/>',NULL,61143,2);
INSERT INTO stanza VALUES('I210','2','Ku hembus kehidupanku,<br/>baru aku terpenuh;<br/>Lepas lemah dan kuatku,<br/>hirup rahmat, kurnia-Mu.<br/>',NULL,61144,3);
INSERT INTO stanza VALUES('I210','3','Ku hembus rantai dosaku,<br/>Kau sapu s''mua buatku;<br/>Hirup kelimpahan kudus,<br/>tahulah Kau Sang Hayat.<br/>',NULL,61145,4);
INSERT INTO stanza VALUES('I210','4','Ku hembus rana murungku,<br/>ke ribaan hangat-Mu;<br/>Hirup riang dan papah-Mu,<br/>manis perhentian-Mu.<br/>',NULL,61146,5);
INSERT INTO stanza VALUES('I210','5','Ku hembuskan penyakitku,<br/>itu telah Kau tanggung;<br/>Ku hirup kesembuhan-Mu,<br/>damai sudah Kau beri.<br/>',NULL,61147,6);
INSERT INTO stanza VALUES('I210','6','Ku hembus rasa dambaku<br/>ke dalam telinga-Mu;<br/>Ku menghirup jawaban-Mu,<br/>tenangkan syak, raguku.<br/>',NULL,61148,7);
INSERT INTO stanza VALUES('I210','7','Saat ke saat ku hirup,<br/>Dikau jadi hayatku;<br/>Hembus, hirup, tergantung-Mu,<br/>''nyatakanlah atasku.<br/>',NULL,61149,8);
INSERT INTO stanza VALUES('I211','1','Tuhan hayat mari hembus,<br/>bukakan sumber hayat-Mu!<br/>Mendorong di dalam kalbu,<br/>terang hayat sorotiku.<br/>',NULL,61150,1);
INSERT INTO stanza VALUES('I211','2','Ajaib sungguh, Kau dalamku!<br/>Tak ke mana mencari-Mu!<br/>Balik ke roh, jumpa tentu;<br/>roh sentuh Roh, erat padu.<br/>',NULL,61151,2);
INSERT INTO stanza VALUES('I211','3','Kau Pembelaku di surga,<br/>pun urapan di dalam roh;<br/>Karya-Mu di depan Allah,<br/>ku menjamah di dalam roh.<br/>',NULL,61152,3);
INSERT INTO stanza VALUES('I211','4','Tiap aku tak setia,<br/>gerakan-Mu tak ku patuh;<br/>Mohon rahmat, dorong, hembus,<br/>agar tunaikan fungsiku.<br/>',NULL,61153,4);
INSERT INTO stanza VALUES('I211','5','Bila rohku lembam m''rosot,<br/>sulit sebar kurnia-Mu;<br/>Mohon hembus di batinku,<br/>terpenuhi Kau seluruh.<br/>',NULL,61154,5);
INSERT INTO stanza VALUES('I212','1','Topan Roh Kudus, hembusan surga,<br/>menimpa p''rilah Pentakosta;<br/>Lunakkan hati dan menghidupkan,<br/>perbarui, pun lepas dosa.<br/>',NULL,61155,1);
INSERT INTO stanza VALUES('I212','chorus','Hembus! Hembus! Hembusan Roh Kudus!<br/>Naung! Naung! Awan Roh menaung!<br/>Bakar! Bakar! Api Roh membakar!<br/>Wujud mulia ''mas murni Allah!<br/>',NULL,61156,2);
INSERT INTO stanza VALUES('I212','2','Awan Roh Kudus, penuh kurnia,<br/>naungi umat p''rilah kemah,<br/>Hingga ku hidup pun dikuduskan,<br/>rohaniah, Allah semayam.<br/>',NULL,61157,3);
INSERT INTO stanza VALUES('I212','3','Api pengudus membakar aku,<br/>tiap pelosok suci, polos,<br/>Membakar cemar, duniawi pun,<br/>insan dan Allah s''rasi kudus.<br/>',NULL,61158,4);
INSERT INTO stanza VALUES('I212','4','Kemilau emas, sorot hatiku,<br/>biar ku dapatkan tabiat Allah,<br/>Allah berbaur denganlah insan,<br/>hayat-Nya nyata atas insan.<br/>',NULL,61159,5);
INSERT INTO stanza VALUES('I213','1','Moga angin dari surga,<br/>kini tiupiku!<br/>Dengan kuasa perkasa,<br/>tiupi jiwaku.<br/>',NULL,61160,1);
INSERT INTO stanza VALUES('I213','chorus','Tuhan perkasa, marilah,<br/>tiupkan Roh Kudus!<br/>Tiup dengan kuasa-Mu,<br/>''ngalir air hidup.<br/>',NULL,61161,2);
INSERT INTO stanza VALUES('I213','2','Dengan Roh kuasa Kau tiup,<br/>singkir s''mua rintangan;<br/>Dengan Roh hayat Kau hembus,<br/>kasih-Mu nan besar.<br/>',NULL,61162,3);
INSERT INTO stanza VALUES('I213','3','Roh-Mu limpah tujuh ganda,<br/>agar Kau ku nikmat;<br/>Biar ku berbagian Roh itu, alami Tritunggal.<br/>',NULL,61163,4);
INSERT INTO stanza VALUES('I214','1','Tuhan, mari hembus!<br/>Kami menantikan;<br/>Hembus d''ngan topan-Mu,<br/>bawa kelepasan;<br/>Hembusi kami s''mua,<br/>terbangunlah mutlak;<br/>O, Tuhan, mari hembuslah!<br/>',NULL,61164,1);
INSERT INTO stanza VALUES('I214','chorus','Tuhan, mari hembus kini!<br/>Singkir s''gala malas, tidur!<br/>O, topan-Mu mari!<br/>Enyah gagal, undur!<br/>O, Tuhan, mari hembuslah!<br/>',NULL,61165,2);
INSERT INTO stanza VALUES('I214','2','Hembus dengan kasih,<br/>dingin jadi gairah;<br/>Udara surgawi<br/>hembusi g''nap jiwa;<br/>Hembusi kami s''mua,<br/>tawar, pudar sirna;<br/>O, Tuhan, mari hembuslah!<br/>',NULL,61166,3);
INSERT INTO stanza VALUES('I214','3','Hembus dengan kuat,<br/>lembam jadi bara;<br/>Kami dibangunkan,<br/>penuh kebangkitan;<br/>Hembusi kami s''mua,<br/>biar tegap perkasa;<br/>O, Tuhan, mari hembuslah!<br/>',NULL,61167,4);
INSERT INTO stanza VALUES('I215','1','Minyak ajaib diam dalamku, mengajar ku ''tiasa,<br/>Membawakan penyertaan Allah, hinggaku bermunajat.<br/>',NULL,61168,1);
INSERT INTO stanza VALUES('I215','chorus','Di dalamku ada minyak ajaib,<br/>Dia mengajarkan semua perkara;<br/>Di dalamku ada minyak ajaib,<br/>Dia mengajarku ''tiasa.<br/>',NULL,61169,2);
INSERT INTO stanza VALUES('I215','2','Roh Kudus berperan dalamku,<br/>halus, lembut mengurap;<br/>Berdasarkan pembasuhan darah,<br/>hingga s''lama-lamanya.<br/>',NULL,61170,3);
INSERT INTO stanza VALUES('I215','3','Dia mengurapkan kadar Allah,<br/>agar ku kenal Allah;<br/>Adanya Allah aku dapatkan,<br/>jenuhiku seluruh.<br/>',NULL,61171,4);
INSERT INTO stanza VALUES('I215','4','Melalui urapan hayat,<br/>aku hidup dalamnya,<br/>Sandar terang, hidup di depan-Nya,<br/>penuhlah kasih kurnia.<br/>',NULL,61172,5);
INSERT INTO stanza VALUES('I216','1','Di mana darah dipercik,<br/>di sana urapan-Nya;<br/>Manusia kontak d''ngan Allah,<br/>persekutuan mesra.<br/>',NULL,61173,1);
INSERT INTO stanza VALUES('I216','2','Darah tanda penebusan,<br/>hapuskan semua dosa;<br/>Pengurapan tanda Sang Roh,<br/>bawa Allah ke insan.<br/>',NULL,61174,2);
INSERT INTO stanza VALUES('I216','3','Darah sirat karya Allah,<br/>pengurapan - diri-Nya,<br/>Oleh karya dan diri-Nya,<br/>Allah baur d''ngan insan.<br/>',NULL,61175,3);
INSERT INTO stanza VALUES('I216','4','Oleh pembasuhan darah,<br/>terlepaslah s''mua dosa;<br/>Oleh gerak urapan Roh,<br/>kadar Allah ku dapat.<br/>',NULL,61176,4);
INSERT INTO stanza VALUES('I216','5','Lewat basuh dan urapan,<br/>ku bersatu d''ngan Allah;<br/>Oleh darah dan urapan,<br/>ku nikmat diri Allah.<br/>',NULL,61177,5);
INSERT INTO stanza VALUES('I216','6','Pembasuhan oleh darah,<br/>dengan iman ku dapat;<br/>Menaati urapan-Nya, hidup,<br/>jalan d''ngan Allah.<br/>',NULL,61178,6);
INSERT INTO stanza VALUES('I216','7','Mengenal Allah Sang Terang,<br/>alami Dia Sang Kasih,<br/>Nikmat Allah Sang Segala,<br/>padu esa dengan-Nya.<br/>',NULL,61179,7);
INSERT INTO stanza VALUES('I217','1','Mulia, bah''gia, tak terperi,<br/>Roh Realitas di hati,<br/>Kesaksian dan wahyu Tuhan,<br/>''nyorot, hibur, pun ''mimpin.<br/>',NULL,61180,1);
INSERT INTO stanza VALUES('I217','chorus','Penuhi! Penuhi!<br/>Roh Kudus penuhiku,<br/>Tuang bersih, kupas bersih,<br/>Roh Kudus penuhiku.<br/>',NULL,61181,2);
INSERT INTO stanza VALUES('I217','2','Moga firman-Mu tergenap,<br/>Roh hayat orak daku,<br/>Bebas dari hukum dosa,<br/>lepas dari kuasa maut.<br/>',NULL,61182,3);
INSERT INTO stanza VALUES('I217','3','P''ri rusa lelah, dahaga,<br/>mohon Roh meleraikan,<br/>Biar ku kecap kelimpahan,<br/>alirkan air hayat.<br/>',NULL,61183,4);
INSERT INTO stanza VALUES('I217','4','Moga diriku tersingkir,<br/>agar Roh memenuhi;<br/>Anteroku Tuhan pimpin,<br/>s''rupa Tuhan ku jadi.<br/>',NULL,61184,5);
INSERT INTO stanza VALUES('I218','1','Ku dibasuh darah adi,<br/>penuh suka surgawi;<br/>Hayat kekal ku miliki,<br/>jadi terusan hayat.<br/>',NULL,61185,1);
INSERT INTO stanza VALUES('I218','chorus','Ku mau jadi t''rusan hayat,<br/>terpenuhi Roh hayat;<br/>Salur hayat, lerai dah''ga,<br/>luap, ''ngalir tak henti.<br/>',NULL,61186,2);
INSERT INTO stanza VALUES('I218','2','Kurnia ajaib, mesra limpah,<br/>betapa memuaskan;<br/>Tiap hari persaksikan,<br/>tarik orang berpaling.<br/>',NULL,61187,3);
INSERT INTO stanza VALUES('I218','3','Tuhan, takdisku sempurna,<br/>jadi wadah mulia;<br/>Penuh kurnia, penuh hayat,<br/>bagi yang haus dan lapar.<br/>',NULL,61188,4);
INSERT INTO stanza VALUES('I218','4','Tuang, agar ku terisi,<br/>diriku Kau miliki;<br/>Air hayat luap, banjir,<br/>''ngalir hingga abadi.<br/>',NULL,61189,5);
INSERT INTO stanza VALUES('I219','1','S''mua dahaga Tuhan tahu,<br/>pada hati yang rindu,<br/>Rindu damba dalam sungguh,<br/>hanya puas oleh-Mu.<br/>',NULL,61190,1);
INSERT INTO stanza VALUES('I219','chorus','Kumohon, ku mohon,<br/>kelimpahan Roh Kudus.<br/>',NULL,61191,2);
INSERT INTO stanza VALUES('I219','2','Gagal semua pekerjaan,<br/>kesaksian, perbuatanku;<br/>Sia-sia semua itu,<br/>tiada pujian bagi-Mu.<br/>',NULL,61192,3);
INSERT INTO stanza VALUES('I219','3','Terhadap-Mu ku mengaku<br/>gagal serta jahatku;<br/>Tinggi hati dan degilku,<br/>pula rah''sia hatiku.<br/>',NULL,61193,4);
INSERT INTO stanza VALUES('I219','4','Ya, Bapa, lepaskan aku,<br/>dari diri, dan angkuh;<br/>Bawaku mati serta-Mu,<br/>pula sama terpaku.<br/>',NULL,61194,5);
INSERT INTO stanza VALUES('I219','5','Sejak kini bukan aku,<br/>kerja, cinta, pun tutur;<br/>Senantiasa Kristus hidup,<br/>mengalir melaluiku.<br/>',NULL,61195,6);
INSERT INTO stanza VALUES('I219','6','Moga kep''nuhan Roh Kudus,<br/>memenuhi lubukku;<br/>Agarku jadi saksi-Mu,<br/>semua mulia bagi-Mu.<br/>',NULL,61196,7);
INSERT INTO stanza VALUES('I219','7','Sandar Putra ku berdoa,<br/>ku yakin Bapa jawab;<br/>Syukur puji, janji tepat,<br/>lega karena firman.<br/>',NULL,61197,8);
INSERT INTO stanza VALUES('I220','1','Dalam roh, lahir oleh Roh,<br/>menjadi anak Allah;<br/>Ku mendapatkan Roh Kudus,<br/>meterai batiniah.<br/>Lebih banyak b''ri padaku,<br/>biar limpah-Mu ku nikmat;<br/>Dengan Roh-Mu penuhiku,<br/>beri hayat nan limpah.<br/>',NULL,61198,1);
INSERT INTO stanza VALUES('I220','2','Roh Kudus-Mu di dalamku,<br/>itu Roh pemb''ri-hayat;<br/>Demilah adanya Dia,<br/>limpah-Mu ku dapatkan.<br/>Roh-Mu tetap ku perlukan,<br/>kuasa yang dari atas;<br/>Ku dilengkapi oleh-Nya,<br/>melayani dan kerja.<br/>',NULL,61199,2);
INSERT INTO stanza VALUES('I220','3','Ku dambakan baptisan Roh,<br/>kenakan kuasa surga;<br/>Di dalam "jubah kuasa",<br/>seteru-Mu ku serang.<br/>Moga angin-Mu tiup keras,<br/>curah api p''ri lidah;<br/>Ku jadi saksi terurap,<br/>kehendak-Mu tergenap.<br/>',NULL,61200,3);
INSERT INTO stanza VALUES('I220','4','Meski t''lah dapat Roh kuasa,<br/>tetap perlu karunia;<br/>Agar ku berdaya guna,<br/>bersama s''mua anggota.<br/>Curahan Roh nan berlimpah,<br/>membagikan talenta;<br/>Hingga Tubuh-Mu terbina,<br/>oleh berkat Kau b''rikan.<br/>',NULL,61201,4);
INSERT INTO stanza VALUES('I220','5','Demi mulia dan k''rajaan,<br/>Tubuh-Mu seru lantang;<br/>Penuhi s''mua keperluan,<br/>murad-Mu terlaksana!<br/>Semoga ku berbagian pun<br/>menerapkan Roh-Mu;<br/>Dalam penuh, luar curah,<br/>untuk jadi saksi-Mu!<br/>',NULL,61202,5);
INSERT INTO stanza VALUES('I221','1','Saat Kristus inkarnasi,<br/>Dia terkandung oleh Roh;<br/>Sebelum mulai ministri,<br/>Dia pun dipenuhi Roh.<br/>Saat awali misi-Nya;<br/>Dia t''rima baptisan Roh;<br/>Mengenakan kuasa surga,<br/>tunai amanat mulia.<br/>',NULL,61203,1);
INSERT INTO stanza VALUES('I221','2','Petrus dan murid lain-Nya,<br/>lahir ulang oleh Roh,<br/>Tuhan hembusi mereka,<br/>Roh Kudus pun terhirup.<br/>Kemudian menerima,<br/>baptisan di dalam Roh;<br/>Diperlengkapi kuasa,<br/>demi amanat kudus.<br/>',NULL,61204,2);
INSERT INTO stanza VALUES('I221','3','Saulus dan orang Efesus,<br/>pun saleh Samaria;<br/>Lahir kembali oleh Roh,<br/>bahkan dihuni Sang Roh.<br/>Saat t''rima tumpang tangan,<br/>baptisan Roh terulang;<br/>Kenakan kuasa surga,<br/>saksi, ''layani Allah.<br/>',NULL,61205,3);
INSERT INTO stanza VALUES('I221','4','Ketika kita beriman,<br/>juga terlahir ulang;<br/>Kini menyesap pada-Nya,<br/>hari-hari nikmat Dia.<br/>Tetap perlu pengalaman<br/>baptisan Roh di dalam,<br/>Kenakan kuasa surga,<br/>bekal tunaikan tugas.<br/>',NULL,61206,4);
INSERT INTO stanza VALUES('I221','5','Tuhan, baptisku dengan Roh,<br/>inilah yang ku perlu;<br/>Ku kenakan kuasa surga,<br/>untuk bangun gereja.<br/>Kini biar ku mengalami,<br/>ku minta sep''nuh hati;<br/>Dengan limpah ku alami,<br/>kuasa surga naungi.<br/>',NULL,61207,5);
INSERT INTO stanza VALUES('I222','1','Fakta nan berkat, Tuhan wahyukan,<br/>Ku dibaptis dalam Roh Kudus.<br/>T''rima segera, tanpa berlambat,<br/>ku dibaptis dalam Roh Kudus.<br/>',NULL,61208,1);
INSERT INTO stanza VALUES('I222','chorus','T''rima! T''rima!<br/>Menerima tanpa lambat;<br/>T''rima! T''rima!<br/>T''rima dengan iman, tak lambat.<br/>',NULL,61209,2);
INSERT INTO stanza VALUES('I222','2','Janji nan baru, t''lah nyata jelas,<br/>Ku dibaptis dalam Roh Kudus.<br/>Cukup berpegang, tanpa berbuat,<br/>Ku dibaptis dalam Roh Kudus.<br/>',NULL,61210,3);
INSERT INTO stanza VALUES('I222','chorus','Pegang! Pegang!<br/>Pegang fakta demi iman;<br/>Pegang! Pegang!<br/>Pegang fakta demilah iman.<br/>',NULL,61211,4);
INSERT INTO stanza VALUES('I222','3','Pada gereja, Roh dicurahkan,<br/>Ku dibaptis dalam Roh Kudus,<br/>Nikmati berkat, nikmat d''ngan limpah,<br/>Ku dibaptis dalam Roh Kudus.<br/>',NULL,61212,5);
INSERT INTO stanza VALUES('I222','chorus','Nikmat! Nikmat!<br/>Nikmat kurnia demi iman;<br/>Nikmat! Nikmat!<br/>Nikmat kurnia demilah iman.<br/>',NULL,61213,6);
INSERT INTO stanza VALUES('I222','4','Di dalam Tubuh, saling selaras,<br/>Demi fakta ini bergerak;<br/>Dosa, bereskan, bimbang, singkirkan;<br/>Demi fakta ini bergerak.<br/>',NULL,61214,7);
INSERT INTO stanza VALUES('I222','chorus','Gerak! Gerak!<br/>Dalam Tubuh demi iman;<br/>Gerak! Gerak!<br/>Dalam Tubuh demilah iman.<br/>',NULL,61215,8);
INSERT INTO stanza VALUES('I223','1','Datang pada-Mu, tekun berdoa,<br/>mohon kurniakan kuasa;<br/>Demi k''rajaan, beri tenaga,<br/>duduk surga, musuh diserang.<br/>Kuasa! Kuasa! Mengenakan kuasa!<br/>Mengenakan kuasa surga!<br/>Kuasa! Kuasa! Mengenakan kuasa!<br/>Kini Tubuh-Mu tekun doa!<br/>',NULL,61216,1);
INSERT INTO stanza VALUES('I223','2','Tengadah dengan hati nan pasti,<br/>mohon beri hujan sejuk;<br/>Demi Tubuh-Mu, curahkan hujan,<br/>layakkan aku kerja buat-Mu.<br/>Hujan! Hujan! Curahkanlah hujan!<br/>Curah hujan darilah surga!<br/>Hujan! Hujan! Curahkanlah hujan!<br/>Kini Tubuh-Mu tekun seru!<br/>',NULL,61217,2);
INSERT INTO stanza VALUES('I223','3','Tuhan, ku tunggu, doa pun tekun,<br/>mohon beri api kudus!<br/>Demi Injil-Mu, bakar diriku,<br/>orang tobat, masuk k''rajaan.<br/>Api kudus, bakarlah diriku!<br/>Bawa gairah kasih bakarku!<br/>Api kudus, bakarlah diriku!<br/>Kini Tubuh-Mu mohon terus!<br/>',NULL,61218,3);
INSERT INTO stanza VALUES('I224','1','Kristus P''nolong t''lah terangkat,<br/>duduk takhta di surga;<br/>Dari Bapa mendapatkan<br/>mahkota hormat, mulia;<br/>Dia-lah Kepala segala,<br/>nyata maha-tinggi-Nya.<br/>',NULL,61219,1);
INSERT INTO stanza VALUES('I224','2','Kristus t''rangkat depan Allah,<br/>Roh Kudus t''lah tercurah;<br/>Curah ke atas Tubuh-Nya,<br/>saluti anggota-Nya;<br/>Tuhan almuhit di surga,<br/>disembah lewat g''reja.<br/>',NULL,61220,2);
INSERT INTO stanza VALUES('I224','3','Kristus lewat inkarnasi<br/>bawa Allah ke insan;<br/>Pula lewat mati, bangkit,<br/>bawa insan ke Allah;<br/>Baur esa Allah insan,<br/>tercapai di dalam-Nya.<br/>',NULL,61221,3);
INSERT INTO stanza VALUES('I224','4','Dia naik tinggi atas surga,<br/>duduk takhta mulia;<br/>Tuhan, Raja atas s''gala,<br/>pada-Nya semua kuasa;<br/>Roh Kudus dicurahkan-Nya,<br/>bukti fakta nan kuat.<br/>',NULL,61222,4);
INSERT INTO stanza VALUES('I224','5','Roh dicurah, Dia ulang<br/>turun atas gereja;<br/>Dia dalam Roh Kudus ini,<br/>baptis genap gereja;<br/>Di dalam baptisan ini,<br/>s''mua saleh berbagian.<br/>',NULL,61223,5);
INSERT INTO stanza VALUES('I224','6','Haleluya, sudah genap!<br/>Sekali selamanya!<br/>Haleluya, ku terima,<br/>kaum beriman juga;<br/>Semua anggota Tubuh-Nya,<br/>sudah dibaptis Roh-Nya.<br/>',NULL,61224,6);
INSERT INTO stanza VALUES('I225','1','Tuhan, ku cari kekuatan-Mu;<br/>tiada hasilku kerja buat-Mu;<br/>Lemah lunglai t''lah cukup lama,<br/>b''riku kekuatan-Mu.<br/>',NULL,61225,1);
INSERT INTO stanza VALUES('I225','chorus','Telut sujud aku menunggu,<br/>tulus tekun bers''ru pada-Mu;<br/>Beri tenaga kekuatan-Mu,<br/>kenakan padaku.<br/>',NULL,61226,2);
INSERT INTO stanza VALUES('I225','2','Rahmat, asuh-Mu, aku minta,<br/>beri karunia pada g''reja;<br/>Biar kerjaku tak layu s''lama,<br/>b''riku kekuatan-Mu!<br/>',NULL,61227,3);
INSERT INTO stanza VALUES('I225','3','Beri t''naga, bawa kuasa-Mu,<br/>seperti hari Pentakosta;<br/>Jawablah seg''ra tanpa tunda,<br/>b''riku kekuatan-Mu!<br/>',NULL,61228,4);
INSERT INTO stanza VALUES('I225','4','Tubuh Kristus, aku dambakan,<br/>sandar iman, mohon genapkan;<br/>Curah hujan, dan nyala api,<br/>b''riku kekuatan-Mu!<br/>',NULL,61229,5);
INSERT INTO stanza VALUES('I226','1','Roh hayat Sang Tuhan<br/>masuk dalamku,<br/>Leraikan dahaga,<br/>p''ri sumber hidup;<br/>Roh ini ku sesap,<br/>Dia penuhi t''rus,<br/>Seperti bengawan,<br/>''ngalir tak putus.<br/>',NULL,61230,1);
INSERT INTO stanza VALUES('I226','2','Roh kuasa Tuhan<br/>turun atasku,<br/>Menyalut p''ri jubah,<br/>jadi kuatku,<br/>Dibaptis dalam-Nya,<br/>Dia membungkus,<br/>Diperlengkapi-Nya,<br/>kerja d''ngan tangguh.<br/>',NULL,61231,2);
INSERT INTO stanza VALUES('I226','3','Roh hayat Sang Tuhan<br/>sep''ri udara,<br/>Realitas hayat<br/>ku hirup tiasa,<br/>Roh kuasa Tuhan,<br/>p''ri angin keras,<br/>Tiup dengan kuat,<br/>aku bergerak.<br/>',NULL,61232,3);
INSERT INTO stanza VALUES('I226','4','Tuhan Sang Bangkit<br/>tiupi murid-Nya;<br/>Hembusan Roh hayat<br/>masuk mereka;<br/>Hari Pentakosta,<br/>surga curahkan,<br/>Roh kuasa Tuhan<br/>p''ri angin topan.<br/>',NULL,61233,4);
INSERT INTO stanza VALUES('I226','5','Roh hayat jadilah<br/>hayat di dalam,<br/>Roh kuasa bagi<br/>hayat ini jua;<br/>P''ri tiupan angin,<br/>b''ri kesegaran,<br/>Roh kuasa datangkan<br/>hembusan hayat.<br/>',NULL,61234,5);
INSERT INTO stanza VALUES('I226','6','Bukan dua berpisah<br/>atau berbeda,<br/>Tetap Roh yang satu,<br/>fungsi tak sama;<br/>Di batin p''nuh Allah,<br/>di lahir juga,<br/>Berbaur dengan Dia,<br/>kekal tak pisah.<br/>',NULL,61235,6);
INSERT INTO stanza VALUES('I226','7','Dengan Roh hayat<br/>Kau penuhi aku,<br/>Hayatku dewasa,<br/>sempurna p''ri Kau;<br/>Bersalut Roh kuasa<br/>pada lahirku,<br/>Hingga laksanakan<br/>s''mua amanat-Mu.<br/>',NULL,61236,7);
INSERT INTO stanza VALUES('I227','1','S''tlah darah baru minyak,<br/>s''tlah bersih baru diris;<br/>Tanpa lewat Golgota,<br/>Pentakosta mustahil.<br/>Seb''lum kita terbasuh,<br/>kuasa-Nya tak''kan turun;<br/>Bila ingin bersaksi,<br/>diri wajib tersalib.<br/>',NULL,61237,1);
INSERT INTO stanza VALUES('I227','chorus','Mohon Tuhan, lewat salib,<br/>mematikan jiwaku;<br/>Biar ku rela bayar harga,<br/>hingga Roh-Mu melimpah.<br/>',NULL,61238,2);
INSERT INTO stanza VALUES('I227','2','Set''lah batu terpukul,<br/>baru ''ngalir air hidup;<br/>Tanpa mati diriku,<br/>tak''kan penuh Roh Kudus.<br/>Jika mati serta-Nya,<br/>rela rugi semuanya;<br/>Kuasa Tuhan ''kan nyata,<br/>s''lamatkan orang dosa.<br/>',NULL,61239,3);
INSERT INTO stanza VALUES('I227','3','S''tlah mezbah baru api,<br/>s''tlah mati baru bangkit;<br/>Tanpa s''luruh tersembah,<br/>pasti takkan naik takhta.<br/>Jika kita mau korban,<br/>s''gala taat pada-Nya;<br/>Niscaya mengalami,<br/>kuasa yang tak terp''ri.<br/>',NULL,61240,4);
INSERT INTO stanza VALUES('I227','4','Setelah botol hampa,<br/>baru diisi minyak;<br/>Penggalian kian dalam,<br/>air hayat kian meluap.<br/>Tanpa menyeb''rang Yordan,<br/>gerakan Roh tak ganda;<br/>Bila t''rima baptisan,<br/>pasti dapat Roh mulia.<br/>',NULL,61241,5);
INSERT INTO stanza VALUES('I227','5','Bila ladang menguning,<br/>hasil lebat kau ingin;<br/>Tapi ingatlah s''lalu,<br/>tanpa mati tak tumbuh.<br/>Siapa ingin berbuah,<br/>harus alami mati;<br/>Yang menolak Golgota,<br/>tiada kuasa-Nya pasti.<br/>',NULL,61242,6);
INSERT INTO stanza VALUES('I227','6','Tuhan, kini ku mohon,<br/>setia tempuh jalan-Mu;<br/>Singkir cita, banggaku,<br/>biar ku patuh pada-Mu.most<br/>Kebesaran tak perlu,<br/>selain mati diriku;<br/>Moga makna Golgota,<br/>terlaksana atasku.<br/>',NULL,61243,7);
INSERT INTO stanza VALUES('I228','1','Mohon darah basuhku,<br/>cuci semua dosa;<br/>Dengan urapan kudus,<br/>ulang urap aku.<br/>Hari-hari hidupku,<br/>sungguh gagal, lemah;<br/>Penuhiku d''ngan Roh-Mu,<br/>hidupku bagi-Mu.<br/>',NULL,61244,1);
INSERT INTO stanza VALUES('I228','chorus','O, Tuhan, lepaskanku,<br/>diri yang kasi''an ini!<br/>Agar ku sejak kini,<br/>Kau-lah yang penuhi.<br/>',NULL,61245,2);
INSERT INTO stanza VALUES('I228','2','Hatiku kering k''rontang,<br/>''tiasa mengeluh;<br/>Ku sungguh mendambakan,<br/>terpenuh Roh Kudus.<br/>Mohon sembunyikanku,<br/>di batu terpukul;<br/>Dengarkanlah doaku,<br/>luap air hayat-Mu.<br/>',NULL,61246,3);
INSERT INTO stanza VALUES('I228','3','Hatiku dingin hambar,<br/>taatku pun lamban;<br/>Moga penuh Roh Kudus,<br/>tak lagi berontak.<br/>Kini rebah di mezbah,<br/>tak berani gerak;<br/>Api surga bakarlah,<br/>bakar habis semua.<br/>',NULL,61247,4);
INSERT INTO stanza VALUES('I228','4','Mohon salib atasku,<br/>garap makin dalam;<br/>Luaskan kapasitasku,<br/>ego lebur tuntas.<br/>Penuh dengan Roh Kudus,<br/>semakin bertambah;<br/>Air hayat memancar,<br/>leraikan dahaga.<br/>',NULL,61248,5);
INSERT INTO stanza VALUES('I229','1','Kiniku dalam Kristus,<br/>terlepas dari Adam,<br/>yang lama jadi baru,<br/>jadi milik surga!<br/>Puji Dia, ku t''lah<br/>b''roleh kurnia,<br/>dapat hidup sentosa!<br/>Puji Dia,<br/>kini ku dalam-Nya!<br/>',NULL,61249,1);
INSERT INTO stanza VALUES('I230','1','Sungguh girang atas firman Bapa,<br/>Menegaskan Dia cinta manusia;<br/>Dalam Alkitab banyak mujizat,<br/>Yang terajaib: Yesus cintaku.<br/>',NULL,61250,1);
INSERT INTO stanza VALUES('I230','chorus','Sungguh girang, Yesus cintaku!<br/>Yesus cinta,Yesus cinta;<br/>Sungguh girang, Yesus cintaku;<br/>Dia cinta padaku.<br/>',NULL,61251,2);
INSERT INTO stanza VALUES('I230','2','Meski ku lupa Dia dan berk''lana,<br/>Namun kasih-Nya tak pernah kurang;<br/>Ku dicari sampai didapat-Nya,<br/>Dengan mesra ku dibawa pulang.<br/>',NULL,61252,3);
INSERT INTO stanza VALUES('I230','3','Dia cintaku, aku pun cinta Dia,<br/>Cinta utus Dia datang tebusku.<br/>Kar''na cinta Dia mati bagiku,<br/>Kini ku tahu Yesus cintaku.<br/>',NULL,61253,4);
INSERT INTO stanza VALUES('I230','4','Cinta ajaib, sungguh tak terkata,<br/>Tapi ku tahu tegas pun mantap!<br/>Di dalam rohku dimeterai-Nya,<br/>Senantiasa buktikan cinta-Nya.<br/>',NULL,61254,5);
INSERT INTO stanza VALUES('I230','5','Kar''na itu rohku p''nuh sentosa,<br/>Hatiku tak lagi bimbang ragu.<br/>Iblis lari jauh tunggang langgang,<br/>Kar''na ku sebut, "Yesus cintaku."<br/>',NULL,61255,6);
INSERT INTO stanza VALUES('I230','6','Dalam mulia kelak jumpa Raja,<br/>Mulut bergita, hati berseru.<br/>Ku ''kan bernyanyi hingga s''lamanya:<br/>"Sungguh ajaib, Yesus cinta aku."<br/>',NULL,61256,7);
INSERT INTO stanza VALUES('I231','1','Kasih-Nya segar, manis,<br/>ku datang memuji;<br/>Tuhan mend''rita buatku,<br/>dan tinggal dalamku;<br/>B''rikan tent''ram dan hidup,<br/>papah merawatku;<br/>Kasih Tuhan kian segar,<br/>kasih-Nya kian manis.<br/>',NULL,61257,1);
INSERT INTO stanza VALUES('I231','chorus','Kasih Tuhan kian manis,<br/>kasih Tuhan kian manis;<br/>Manisnya tak terp''ri,<br/>tak henti ku puji,<br/>Kasih Tuhan kian manis!<br/>',NULL,61258,2);
INSERT INTO stanza VALUES('I231','2','Kasih-Nya dalam sungguh,<br/>ku nyaring bersyukur!<br/>Tuhan beserta s''lalu,<br/>takkan tinggalkanku;<br/>Dia Temanku terakrab,<br/>berpadu denganku;<br/>Kasih Tuhan kian tebal,<br/>kasih-Nya kian dalam!<br/>',NULL,61259,3);
INSERT INTO stanza VALUES('I231','3','Kasih-Nya lemah lembut,<br/>s''lama ku bersyukur!<br/>Kasih-Nya amat teguh,<br/>s''lama takkan rubuh!<br/>Biarpun dunia ''kan musnah,<br/>biarpun laut ''kan asat;<br/>Kasih-Nya tak berkurang,<br/>kasih-Nya tak ubah.<br/>',NULL,61260,4);
INSERT INTO stanza VALUES('I232','1','Dia mengasihiku,<br/>oleh kurnia ku tahu;<br/>Roh Kudus pun b''ri wahyu<br/>hal itu kepadaku.<br/>O, sentosa yang penuh!<br/>Sukacita yang kudus!<br/>Dalam kasih tak putus,<br/>ku milik-Nya, Dia milikku.<br/>Dalam kasih tak putus,<br/>ku milik-Nya, Dia milikku.<br/>',NULL,61261,1);
INSERT INTO stanza VALUES('I232','2','Langit biru nan cerah,<br/>bumi hijau nan segar;<br/>Ada warna cemerlang,<br/>tanpa Kristus tak nampak.<br/>Kicau burung kian merdu,<br/>bunga indah semarak;<br/>Sejak hatiku paham,<br/>ku milik-Nya, Dia milikku.<br/>Sejak hatiku paham,<br/>ku milik-Nya, Dia milikku.<br/>',NULL,61262,2);
INSERT INTO stanza VALUES('I232','3','Dulu takut dan gentar,<br/>kini penuh perhentian;<br/>Sandar tangan yang kekal,<br/>di ribaan kasih-Nya.<br/>Ku mau tinggal dalam-Nya,<br/>lepas diri dan bimbang,<br/>D''ngan lembut Dia bisikkan,<br/>ku milik-Nya, Dia milikku.<br/>D''ngan lembut Dia bisikkan,<br/>ku milik-Nya, Dia milikku.<br/>',NULL,61263,3);
INSERT INTO stanza VALUES('I232','4','Kekal aku milik-Nya,<br/>siapa dapat ceraikan?<br/>Dalamku Dia semayam,<br/>penuh kurnia, perhentian.<br/>Langit, bumi ''kan lalu,<br/>terang surya ''kan redup.<br/>Kekal Tuhan sertaku,<br/>ku milik-Nya, Dia milikku.<br/>Kekal Tuhan sertaku,<br/>ku milik-Nya, Dia milikku.<br/>',NULL,61264,4);
INSERT INTO stanza VALUES('I233','1','Dosaku dibuang Allah,<br/>tak diingat, tak dituntut;<br/>Diinjak bawah telapak,<br/>tak ditilik, tak diusut.<br/>',NULL,61265,1);
INSERT INTO stanza VALUES('I233','chorus','P''langgaranku diampuni,<br/>p''ri awan dihembus sirna;<br/>Dosaku dihapus Allah,<br/>hilang lenyap tanpa bekas.<br/>',NULL,61266,2);
INSERT INTO stanza VALUES('I233','2','Dosaku dibenam Allah,<br/>p''ri batu karam ke dasar;<br/>Tinggalkan diriku s''lama,<br/>sejauh Timur dari Barat.<br/>',NULL,61267,3);
INSERT INTO stanza VALUES('I234','1','Penebusan darah Tuhan,<br/>siapakah ku, ku berbagian?<br/>Ku berdosa, Dia yang wafat,<br/>demikian ku selamat!<br/>Kasih ajaib! B''tapa Tuhan,<br/>Allah mati bagi aku!<br/>Kasih ajaib! B''tapa Tuhan,<br/>Allah mati bagi aku!<br/>',NULL,61268,1);
INSERT INTO stanza VALUES('I234','2','Dia Sang Hidup, rela mati!<br/>Mengherankan, tak terpaham!<br/>Kasih ilahi tak terp''ri,<br/>panjang, lebar, tinggi, dalam!<br/>Ini tak perlu direka,<br/>sungguh rahmat, ku menyembah!<br/>Ini tak perlu direka,<br/>sungguh rahmat, ku menyembah!<br/>',NULL,61269,2);
INSERT INTO stanza VALUES('I234','3','Takhta Bapa ditinggalkan,<br/>inkarnasi, o kurnia!<br/>Korban demi penebusan,<br/>umat Adam dis''lamatkan;<br/>Rahmat nan tiada batas,<br/>padaku menimpa juga!<br/>Rahmat nan tiada batas,<br/>padaku menimpa juga!<br/>',NULL,61270,3);
INSERT INTO stanza VALUES('I234','4','Tabiat gelap, hati jahat,<br/>oleh dosa, roh terkekang;<br/>Sinar mata-Mu menatap,<br/>tersadar ku nampak terang;<br/>Lucut rantai, ku terorak,<br/>ikut Tuhan, hati girang.<br/>Lucut rantai, ku terorak,<br/>ikut Tuhan, hati girang.<br/>',NULL,61271,4);
INSERT INTO stanza VALUES('I234','5','Tak terhukum, sungguh takjub!<br/>Dia, segala - milikku;<br/>Oleh Kepala ku hidup,<br/>adil ilahi menaung;<br/>Dengan b''rani hampir takhta,<br/>Tuhan Kristus mahkotaku.<br/>Dengan b''rani hampir takhta,<br/>Tuhan Kristus mahkotaku.<br/>',NULL,61272,5);
INSERT INTO stanza VALUES('I235','1','Mengapa ku bimbang ragu?<br/>Bukankah semua dosaku,<br/>dipikul Putra-Nya?<br/>Lunas sudah semua hutang,<br/>Mungkinkah Allah yang adil,<br/>menagihku ulang?<br/>',NULL,61273,1);
INSERT INTO stanza VALUES('I235','2','Sempurna penebusan-Mu,<br/>Tiap peser t''lah Kau bayar,<br/>tiada yang sisa;<br/>Murka Allah tak menimpa,<br/>Aku t''lah diperik darah,<br/>bahkan dibenarkan.<br/>',NULL,61274,2);
INSERT INTO stanza VALUES('I235','3','Kau berikan pengampunan,<br/>Pula kurnia cuma-cuma,<br/>lunas hutang dosa;<br/>Pembelaku bayar tuntas,<br/>Mungkinkah Allah Sang Benar,<br/>memintaku ulang?<br/>',NULL,61275,3);
INSERT INTO stanza VALUES('I235','4','Hai hatiku, bersyukurlah,<br/>Kar''na semua karya Tuhan<br/>telah membebaskan!<br/>Kini hanya sandar darah,<br/>Tidak takut Allah tolak,<br/>kar''na Dia t''lah wafat.<br/>',NULL,61276,4);
INSERT INTO stanza VALUES('I236','1','"Tak dihukum!"<br/>Sungguh takjub!<br/>Girang, hai jiwaku!<br/>Dosaku dipikul Yesus,<br/>Dia mati, ku hidup.<br/>',NULL,61277,1);
INSERT INTO stanza VALUES('I236','2','Darah adi-Nya<br/>di surga,<br/>jadilah pembela;<br/>Kita dipandang mustika,<br/>dijaga ''tiasa.<br/>',NULL,61278,2);
INSERT INTO stanza VALUES('I236','3','"Tak dihukum!"<br/>Hai jiwaku,<br/>ini sabda Allah;<br/>Di dalam Kristus yang bangkit,<br/>ku pasti sempurna.<br/>',NULL,61279,3);
INSERT INTO stanza VALUES('I236','4','Bapa,<br/>ajarku memandang,<br/>Kristus Raja daulat;<br/>Pada-Mu baru ku dapat<br/>muliakan nama-Nya.<br/>',NULL,61280,4);
INSERT INTO stanza VALUES('I237','1','Kristus Allah Sang Benarku,<br/>elokku pun pakaianku;<br/>Depan takhta ku kenakan,<br/>ku mendongak nyanyi riang.<br/>',NULL,61281,1);
INSERT INTO stanza VALUES('I237','2','Aku yakin, darah adi,<br/>t''lah bereskan s''mua dosaku;<br/>Depan takhta t''lah dipercik,<br/>kekal dosaku diampun.<br/>',NULL,61282,2);
INSERT INTO stanza VALUES('I237','3','Tebusan-Mu lepaskanku,<br/>dari dosa, malu, gentar;<br/>Hari itu ku menghadap,<br/>Kau benarkan, siapa gugat?<br/>',NULL,61283,3);
INSERT INTO stanza VALUES('I237','4','Sama seperti Abraham,<br/>juga umat yang tertebus;<br/>Siarkan Kau Penyelamat,<br/>hanya megahkan nama-Mu.<br/>',NULL,61284,4);
INSERT INTO stanza VALUES('I237','5','Jubah putih tak berubah,<br/>meski benam dalam usang;<br/>Tidak luntur oleh zaman,<br/>lestari segar eloknya.<br/>',NULL,61285,5);
INSERT INTO stanza VALUES('I237','6','Nampak mulia-Mu di surga,<br/>Kau tetap bangga megahku;<br/>Elokku dan pakaianku,<br/>Tuhan Yesus Sang Benarku.<br/>',NULL,61286,6);
INSERT INTO stanza VALUES('I238','1','Semua dasar harapanku,<br/>Kristuslah kebenaranku,<br/>Tak sandar kebenaranku,<br/>hanya sandar pada Kristus.<br/>',NULL,61287,1);
INSERT INTO stanza VALUES('I238','chorus','Tegak pada karang Kristus,<br/>dasar lain itu lumpur!<br/>Dasar lain itu lumpur!<br/>',NULL,61288,2);
INSERT INTO stanza VALUES('I238','2','Awan tutupi wajah-Nya,<br/>hati dan kurnia-Nya tetap;<br/>Meski angin badai terpa,<br/>sauh iman tetap mantap.<br/>',NULL,61289,3);
INSERT INTO stanza VALUES('I238','3','Darah dan janji-Nya andal,<br/>namaku pada tangan-Nya;<br/>Walau sekeliling runtuh,<br/>Dia tetap ada s''lamanya.<br/>',NULL,61290,4);
INSERT INTO stanza VALUES('I238','4','Dia datang, tiup nafiri,<br/>ku di dalam-Nya tertampil;<br/>Pakai jubah kebenaran,<br/>disembahkan tanpa cela.<br/>',NULL,61291,5);
INSERT INTO stanza VALUES('I239','1','Dosaku Yesus tanggung,<br/>Domba kudus Allah;<br/>Laknatku Dia pikul,<br/>hingga aku bebas.<br/>Salahku Dia angkut,<br/>Domba tanpa cela;<br/>Mend''rita bagi aku,<br/>bayar hutang dosa.<br/>',NULL,61292,1);
INSERT INTO stanza VALUES('I239','2','Sakitku Yesus tanggung,<br/>Dia rela disesah;<br/>Lemahku Dia pikul,<br/>aku sembuh, sehat.<br/>Susahku Dia angkut,<br/>dengan sepenuhnya,<br/>Dukaku Dia hapus,<br/>ganti sukacita.<br/>',NULL,61293,2);
INSERT INTO stanza VALUES('I239','3','Yesus perhentianku,<br/>Dia Raja benarku;<br/>Wafat-Nya puaskan Allah,<br/>darah bersihkanku.<br/>Yesus-lah andalanku,<br/>Dia tenagaku;<br/>Dia hidup tampil Allah,<br/>hayat-Nya kuatku.<br/>',NULL,61294,3);
INSERT INTO stanza VALUES('I239','4','Hati tertuju Yesus,<br/>Sang Raja di raja;<br/>Hayatku pun Tuhan-ku,<br/>dalamku semayam.<br/>S''rupa Yesus ku rindu,<br/>tampilkan citra-Nya;<br/>Sikap serta tindakku,<br/>kekal hidupkan Dia.<br/>',NULL,61295,4);
INSERT INTO stanza VALUES('I240','1','D''ngan b''rani menghadap Allah,<br/>sungguhlah mengherankan!<br/>Orang dosa kar''na kurnia,<br/>bukan lagi musuh-Nya!<br/>',NULL,61296,1);
INSERT INTO stanza VALUES('I240','2','Sifat, sikap, kelakuanku,<br/>d''ngan Allah betapa jauh!<br/>Demi iman, oleh darah,<br/>tidak lagi bersekat.<br/>',NULL,61297,2);
INSERT INTO stanza VALUES('I240','3','Kini ku dekat d''ngan Allah,<br/>s''dikit jarak pun tiada;<br/>Melalui Putra Allah,<br/>d''ngan Allah aku akrab.<br/>',NULL,61298,3);
INSERT INTO stanza VALUES('I240','4','Kasih Allah sudah mutlak,<br/>tak mungkinlah bertambah;<br/>Bagaimana cinta Anak,<br/>padaku pun demikian.<br/>',NULL,61299,4);
INSERT INTO stanza VALUES('I240','5','Ku t''lah dapat Allah ini,<br/>apa yang ku cemaskan?<br/>Lembut, mesra, Dia berbisik,<br/>"Aku milikmu s''lama."<br/>',NULL,61300,5);
INSERT INTO stanza VALUES('I241','1','Betapa perubahan dalam hidupku,<br/>sejak Kristus di hatiku;<br/>Sinar mulia menerangi jiwaku,<br/>Sejak Kristus di hatiku.<br/>',NULL,61301,1);
INSERT INTO stanza VALUES('I241','chorus','Sejak Kristus di hatiku,<br/>Sejak Kristus di hatiku;<br/>Riang ria bergolak melanda jiwaku,<br/>sejak Kristus di hatiku.<br/>',NULL,61302,2);
INSERT INTO stanza VALUES('I241','2','Ikatan dosa telah lepas dariku,<br/>Sejak Kristus di hatiku;<br/>Hawa nafsuku pun terkekang dan takluk,<br/>Sejak Kristus di hatiku.<br/>',NULL,61303,3);
INSERT INTO stanza VALUES('I241','3','Semua mewah dunia luntur dan hambar,<br/>Sejak Kristus di hatiku;<br/>Rasa kuatir pun tak lagi terlintas,<br/>Sejak Kristus di hatiku.<br/>',NULL,61304,4);
INSERT INTO stanza VALUES('I241','4','Dulu berkelana kini telah balik,<br/>Sejak Kristus di hatiku;<br/>Perhentian yang manis puaskan hatiku,<br/>Sejak Kristus di hatiku.<br/>',NULL,61305,5);
INSERT INTO stanza VALUES('I241','5','Yang lalu t''lah tamat, tak lagi terulang,<br/>Sejak Kristus di hatiku;<br/>Harapan bahagia, menarik ku maju,<br/>Sejak Kristus di hatiku.<br/>',NULL,61306,6);
INSERT INTO stanza VALUES('I242','1','Riang luapi!<br/>Luapi! Hatiku!<br/>Riang luapi!<br/>Hati daging<br/>mengganti yang batu,<br/>Roh perbarui<br/>jadi orang baru;<br/>Riang luapi!<br/>Luapi hatiku!<br/>',NULL,61307,1);
INSERT INTO stanza VALUES('I242','2','Roh-Nya penuhi,<br/>penuhi diriku!<br/>Roh-Nya penuhi!<br/>Dosa terhapus,<br/>lemah terpupus,<br/>Berubah daku<br/>dalam hidup kudus;<br/>Roh-Nya penuhi,<br/>penuhi diriku!<br/>',NULL,61308,2);
INSERT INTO stanza VALUES('I243','1','Ku tahu kapan dosaku terlepas;<br/>Lama nian menanggung derita;<br/>Saat aku percaya,<br/>sesuai firman t''rima Dia,<br/>Sekejap, s''mua dosaku terlepas!<br/>',NULL,61309,1);
INSERT INTO stanza VALUES('I243','chorus','Terlepas! Semua!<br/>Aku girang,<br/>semua dosa lepas!<br/>Terlepas! Semua!<br/>Aku girang,<br/>semua dosa lepas!<br/>',NULL,61310,2);
INSERT INTO stanza VALUES('I243','2','Ku tahu tempat dosaku terlepas;<br/>Saat ku takut tak dapat lepas;<br/>Roh Kudus tunjuk jalan,<br/>membawa ke salib-Nya;<br/>Di sana, s''mua dosaku terlepas!<br/>',NULL,61311,3);
INSERT INTO stanza VALUES('I243','3','Ku tahu sebab dosaku terlepas;<br/>T''lah lama beban dosa menekan,<br/>Takhta kurnia ku datang,<br/>mulia-Nya berpancar,<br/>Demikian, s''mua dosaku terlepas!<br/>',NULL,61312,4);
INSERT INTO stanza VALUES('I243','4','Berdendang kar''na dosaku terlepas,<br/>Hati gembira, puji pun puja;<br/>Kini hidup bagi-Nya,<br/>hari-hari bersorak,<br/>Haleluya! S''mua dosa terlepas!<br/>',NULL,61313,5);
INSERT INTO stanza VALUES('I244','1','Memandang Yesus,<br/>segera terorak,<br/>Yesus Penolong,<br/>di hati meraja;<br/>Roh penuhiku,<br/>ku nyanyi ''tiasa,<br/>Tuhan Yesus bebaskanku!<br/>',NULL,61314,1);
INSERT INTO stanza VALUES('I244','chorus','Bebas! Bebas! Bebas mulia!<br/>Tak lagi terb''lenggu dosa;<br/>Darah basuhku hingga bersih, terang,<br/>Tuhan Yesus bebaskanku!<br/>',NULL,61315,2);
INSERT INTO stanza VALUES('I244','2','Dosa terhempas,<br/>nafsu pun tak daya,<br/>khawatir hidup<br/>tak lagi mengganggu.<br/>Ikatan bumi<br/>juga telah putus,<br/>Tuhan Yesus bebaskanku!<br/>',NULL,61316,3);
INSERT INTO stanza VALUES('I244','3','Kepungan dunia<br/>telah dit''robos-Nya,<br/>Iblis penjajah telah<br/>dicampak-Nya;<br/>Sinar kurnia,<br/>mulia cemerlang,<br/>Tuhan Yesus bebaskanku!<br/>',NULL,61317,4);
INSERT INTO stanza VALUES('I245','1','Dulu budak dalam dosa,<br/>menanggung derita;<br/>Dosa menjadi tuan,<br/>aku ditaklukkan;<br/>Gumul ronta, tiada guna,<br/>hanya keluh kesah,<br/>Belum tahu Kristus membebaskan!<br/>',NULL,61318,1);
INSERT INTO stanza VALUES('I245','chorus','Kini ku t''rima kurnia,<br/>terlepas kuasa dosa;<br/>Menyesap sumber hayat,<br/>nikmat pesta s''lamat;<br/>O, haleluya! Limpah mesra,<br/>panjat pujian riang,<br/>O, haleluya, kurnia limpah!<br/>',NULL,61319,2);
INSERT INTO stanza VALUES('I246','1','B''lenggu dosa tak kuat aku tahan,<br/>p''ri tawanan meronta sia-sia,<br/>Tapi dengan ajaib ku terlepas,<br/>kar''na Yesus yang membebaskan.<br/>',NULL,61320,1);
INSERT INTO stanza VALUES('I246','chorus','K''lepasan ajaib! K''lepasan mulia!<br/>Kini ku lepas dari d''rita!<br/>Yesus Juru-s''lamatku yang mulia,<br/>hingga kekal ku tak terikat!<br/>',NULL,61321,2);
INSERT INTO stanza VALUES('I246','2','Lepas dari daging, hawa nafsu,<br/>iri hati, dengki, cemburu;<br/>Lepas dari s''gala mewah dunia,<br/>serta kehidupan yang nista.<br/>',NULL,61322,3);
INSERT INTO stanza VALUES('I246','3','Lepas dari kemilaunya harta,<br/>ambisi, tekad, keras hati;<br/>Lepas dari s''mua ikatan Taurat,<br/>k''lepasan ini sungguh ajaib!<br/>',NULL,61323,4);
INSERT INTO stanza VALUES('I247','1','Kurnia ajaib! Menakjubkan!<br/>Aku t''lah selamat!<br/>Dulu sesat, kini pulang,<br/>buta dicelikkan.<br/>',NULL,61324,1);
INSERT INTO stanza VALUES('I247','2','Kurnia mengajar ku takwa,<br/>singkir rasa gentar;<br/>O, mustika, t''rima kurnia,<br/>saat ku percaya.<br/>',NULL,61325,2);
INSERT INTO stanza VALUES('I247','3','Dia berjanji beri rahmat,<br/>firman-Nya jaminan;<br/>Dia perisai, bagian kekal,<br/>hidupku Dia papah.<br/>',NULL,61326,3);
INSERT INTO stanza VALUES('I247','4','Saat jumpa di k''rajaan, cerah,<br/>t''rang p''ri surya,<br/>Pujian bertambah-tambah,<br/>puji hingga kekal.<br/>',NULL,61327,4);
INSERT INTO stanza VALUES('I248','1','Kurnia ganti dosa,<br/>menggema di kalbu;<br/>Biar ku lepas dari dosa,<br/>dan tabiat yang buruk.<br/>',NULL,61328,1);
INSERT INTO stanza VALUES('I248','chorus','Kurnia-Nya cukup,<br/>ku pakai s''lama!<br/>Kristus hidup dalamku,<br/>limpah ku nikmat Dia!<br/>',NULL,61329,2);
INSERT INTO stanza VALUES('I248','2','Kurnia-Nya memapah,<br/>ku tempuh jalan-Nya,<br/>Suplai-Nya cukup berlimpah,<br/>tidak pernah lambat.<br/>',NULL,61330,3);
INSERT INTO stanza VALUES('I248','3','Betapa kurnia!<br/>Allah jelma insan,<br/>Dia datang, tinggal dalamku,<br/>kurnia besar sungguh!<br/>',NULL,61331,4);
INSERT INTO stanza VALUES('I249','1','Satu hari, rantai rantas,<br/>ku tak lagi nyanyi lantang;<br/>Riang sangat, dibangkitkan,<br/>ku berjumpa dengan Raja.<br/>',NULL,61332,1);
INSERT INTO stanza VALUES('I249','chorus','Nampak Tuhan, berhadapan,<br/>ku kisahkah kurnia s''lamat;<br/>Nampak Tuhan, berhadapan,<br/>ku kisahkan kurnia s''lamat.<br/>',NULL,61333,2);
INSERT INTO stanza VALUES('I249','2','Satu hari, kemah runtuh,<br/>ku tak tahu kapan itu;<br/>Tapi yakin sudah tentu,<br/>ke hadirat-Nya ku tuju.<br/>',NULL,61334,3);
INSERT INTO stanza VALUES('I249','3','Satu hari, Tuhan datang,<br/>rampung sudah pekerjaan;<br/>Dia memuji, "Hamba setia!"<br/>Ku pun masuk perhentian-Nya.<br/>',NULL,61335,4);
INSERT INTO stanza VALUES('I249','4','Wajib aku siap sedia,<br/>nyala dian, tunggu siaga;<br/>Ku berjumpa dengan Tuhan,<br/>kekal nikmati hadir-Nya.<br/>',NULL,61336,5);
INSERT INTO stanza VALUES('I250','1','Mari datang, Sumber Berkat!<br/>Ku nyanyikan kurnia-Mu;<br/>Arus rahmat ''ngalir terus,<br/>ku nyanyikan tak putus.<br/>Waktu aku sesat hilang,<br/>untukku Yesus datang;<br/>Aku s''lamat, tak binasa,<br/>kar''na Dia t''lah berkorban.<br/>',NULL,61337,1);
INSERT INTO stanza VALUES('I250','2','Hutang dosa amat besar,<br/>tapi s''mua t''lah Kau tanggung;<br/>Mohon kurnia-Mu mengikat,<br/>hatiku yang berk''lana.<br/>Aku sungguh t''lah tersesat,<br/>jauhi Allah Bapa, Mohon<br/>Kau d''ngan kuasa Roh-Mu,<br/>tarik balik hatiku.<br/>',NULL,61338,2);
INSERT INTO stanza VALUES('I250','3','Ku t''lah dapatkan kurnia-Mu,<br/>lepas dosa dan maut;<br/>Mohon jadikanku kudus,<br/>ekspresikan diri-Mu.<br/>Kini aku merasakan,<br/>Dikaulah segalaku;<br/>Hingga kekal, ku dambakan,<br/>bimbing dan rawatan-Mu.<br/>',NULL,61339,3);
INSERT INTO stanza VALUES('I251','1','Semua ku punya tak lain berkat-Nya,<br/>ku peroleh setelah percaya;<br/>Bangga diri bukan tempatnya,<br/>ku hanya terima kurnia-Nya.<br/>',NULL,61340,1);
INSERT INTO stanza VALUES('I251','chorus','Aku inilah berdosa,<br/>namun diberi kurnia-Nya!<br/>Hormat mulia bagilah Allah,<br/>orang dosa t''rima kurnia!<br/>',NULL,61341,2);
INSERT INTO stanza VALUES('I251','2','Dulu ku buta karena dosa,<br/>hingga jejakku jauhi Allah;<br/>Kini t''lah balik, hati riang,<br/>orang dosa t''rima kurnia-Nya!<br/>',NULL,61342,3);
INSERT INTO stanza VALUES('I251','3','Tangis dan jasa apa gunanya?<br/>Tanpa rahmat-Nya pasti binasa;<br/>Dulu tak b''rani hampir Allah,<br/>kini diberilah kurnia-Nya.<br/>',NULL,61343,4);
INSERT INTO stanza VALUES('I251','4','Yesus Penolong sangat ku cinta,<br/>senantiasa ''kan ku saksikan;<br/>Ku orang dosa paling bejat,<br/>namun diberilah kurnia-Nya!<br/>',NULL,61344,5);
INSERT INTO stanza VALUES('I252','1','Di tanah Mesir menghamba,<br/>tak kenal tenteram,<br/>Sanubari siang malam<br/>tanggung b''rat dosa;<br/>Ingin bebas, cari ringan,<br/>malah tambah berat,<br/>Kasi''an b''lum mendengar,<br/>tanah permai!<br/>',NULL,61345,1);
INSERT INTO stanza VALUES('I252','chorus','Gunung megah ku tanjak,<br/>di tengah siang bolong,<br/>Sumber hidup ku sesap,<br/>tiada berputus,<br/>Limpah ku dapat susu, madu,<br/>lemak, kurnia tak kurang,<br/>Di tanah permai, berhuniku.<br/>',NULL,61346,2);
INSERT INTO stanza VALUES('I252','2','Untung Domba Paskah dib''ri,<br/>tertebus darah-Nya,<br/>Demi baptis, lepas Mesir,<br/>menempuh padang;<br/>Ada cobaan, ada t''naga,<br/>atau liku jalan,<br/>Tak beriman masuk<br/>tanah permai?<br/>',NULL,61347,3);
INSERT INTO stanza VALUES('I252','3','Bersama duduk di surga,<br/>Kristus yang mengangkat,<br/>Kuasa awang remuk redam,<br/>Satan gemetar;<br/>Nama Tuhan memang jaya,<br/>alam maut tak daya;<br/>Menang mutlak pada<br/>tanah permai!<br/>',NULL,61348,4);
INSERT INTO stanza VALUES('I252','4','Sentosa tak kunjung hingga,<br/>riang tiada lawan,<br/>Duka sirna, sepi lenyap,<br/>teduhlah mutlak;<br/>Mesra sayang, nyanyi riang,<br/>bersekutu girang,<br/>Haleluya, ''nilah<br/>tanah permai!<br/>',NULL,61349,5);
INSERT INTO stanza VALUES('I253','1','Ada musik merdu di kalbu,<br/>padaku Tuhan b''ri ta''u:<br/>"Kamu datang s''lalu Ku sambut,<br/>kekal kamu milikKu."<br/>',NULL,61350,1);
INSERT INTO stanza VALUES('I253','chorus','Yesus, Yesus, Yesus,<br/>manis nama-Mu;<br/>Kau puaskan hatiku,<br/>dengan riang ku maju t''rus.<br/>',NULL,61351,2);
INSERT INTO stanza VALUES('I253','2','Hidupku c''laka kar''na dosa,<br/>hati duka merana;<br/>Sejak Tuhan diam di hatiku,<br/>ku gembira selalu.<br/>',NULL,61352,3);
INSERT INTO stanza VALUES('I253','3','Kurnia dan kasih ku nikmati,<br/>dipangkuan-Nya berbaring,<br/>Memandang senyum-Nya yang manis,<br/>hati riang memuji.<br/>',NULL,61353,4);
INSERT INTO stanza VALUES('I253','4','Meski ada juga sengsara,<br/>Dia pasti menemani;<br/>Meski ada juga pikulan,<br/>tapi Tuhan yang jinjing.<br/>',NULL,61354,5);
INSERT INTO stanza VALUES('I253','5','Pulang surga Tuhan yang sambut,<br/>lepaslah s''mua ikatan;<br/>Kelak aku s''rupa Tuhanku,<br/>jadi raja serta-Nya.<br/>',NULL,61355,6);
INSERT INTO stanza VALUES('I254','1','Bertahun tahun mencari mata air,<br/>yang tak pernah mengering;<br/>Dunia selalu mengecewakanku,<br/>tak memuaskan hati.<br/>',NULL,61356,1);
INSERT INTO stanza VALUES('I254','chorus','Pancaran tak kunjung kering ku sesap,<br/>Sekarang ku minum sumber hayat!<br/>Sedap, riang, puas tiada terhingga,<br/>Sekarang ku minum sumber hayat!<br/>',NULL,61357,2);
INSERT INTO stanza VALUES('I254','2','Tak lagi mengembara dalam dosa,<br/>Mendapat sumber hayat;<br/>Cawan ria ini sungguh berlimpah,<br/>Kristus memuaskanku!<br/>',NULL,61358,3);
INSERT INTO stanza VALUES('I254','3','Rasa puas kian hari kian bertambah,<br/>Penuhlah sejahtera;<br/>Penghiburan makin berlipat ganda,<br/>Kini nikmat berkat-Nya.<br/>',NULL,61359,4);
INSERT INTO stanza VALUES('I254','4','Suplaian di sini tidak terbatas,<br/>Penuhlah karunia;<br/>Terjun ke dalam sumber penyembuhan,<br/>Sampai s''lama-lamanya!<br/>',NULL,61360,5);
INSERT INTO stanza VALUES('I255','1','Musik merdu dalam hatiku,<br/>Tuhan Yesus kidungku;<br/>Tiada musik yang lebih merdu,<br/>bawa surga padaku.<br/>',NULL,61361,1);
INSERT INTO stanza VALUES('I255','chorus','Di hatiku ada musik merdu,<br/>ada musik merdu, musik surgawi.<br/>Di hatiku ada musik merdu<br/>tentang kasih yang ajaib.<br/>',NULL,61362,2);
INSERT INTO stanza VALUES('I255','2','Kasih ajaib! Yesus tolongku,<br/>tak kepalang riangku,<br/>Kurnia besar! Kristus gantiku,<br/>senang, lega hatiku.<br/>',NULL,61363,3);
INSERT INTO stanza VALUES('I255','3','Terang sungguh! Yesus pimpinku,<br/>sambil nyanyi ku maju;<br/>Damai sungguh! Kristus sertaku,<br/>ku memuji selalu.<br/>',NULL,61364,4);
INSERT INTO stanza VALUES('I255','4','Unggul sungguh! Aku diangkat,<br/>kaum saleh nyanyi menang;<br/>Agung sungguh! M''raja serta-Nya,<br/>malak sorak gempita.<br/>',NULL,61365,5);
INSERT INTO stanza VALUES('I255','5','Berkat sungguh! Masuk kota-Nya,<br/>menyesap sungai hayat;<br/>Riang sungguh! Nikmat limpah-Nya,<br/>mengecap buah hayat.<br/>',NULL,61366,6);
INSERT INTO stanza VALUES('I256','1','Kar''na Kristus hati senang,<br/>kar''na Kristus ku bergita;<br/>Dia beserta aku girang,<br/>Dia beserta ku nyanyi riang.<br/>',NULL,61367,1);
INSERT INTO stanza VALUES('I256','chorus','Haleluya, nyanyi riang!<br/>Haleluya, gita lantang!<br/>Dia beserta sungguh senang!<br/>Dia beserta sungguh girang!<br/>',NULL,61368,2);
INSERT INTO stanza VALUES('I256','2','Dulu banyak pikulan b''rat,<br/>kini aku sentosalah;<br/>Dia ampuni s''gala dosa,<br/>Dia memikul s''mua celaka.<br/>',NULL,61369,3);
INSERT INTO stanza VALUES('I256','3','Dulu buta semua gelap,<br/>kini nampak amat jelas;<br/>Ku tersesat Dia memanggil,<br/>di jalan b''nar, Dia yang pimpin.<br/>',NULL,61370,4);
INSERT INTO stanza VALUES('I256','4','Dulu ku seorang diri,<br/>tapi kini Dia temani;<br/>Sangat akrab, sangat karib,<br/>penuh kasih dan simpati.<br/>',NULL,61371,5);
INSERT INTO stanza VALUES('I256','5','Dengan mesra Dia dorongku,<br/>dengan kurnia Dia tunjangku;<br/>Hati kasih-Nya tolongku,<br/>tangan kurnia-Nya jagaku.<br/>',NULL,61372,6);
INSERT INTO stanza VALUES('I256','6','Selain Dia, ada siapa,<br/>selain Dia, tiada lagi!<br/>Cinta-Nya padaku kekal!<br/>Ku cinta Dia, s''penuh kini!<br/>',NULL,61373,7);
INSERT INTO stanza VALUES('I257','1','Seumurku amat rindu<br/>minum sumber air sejuk,<br/>Agar lenyap rasa haus<br/>yang membara dalamku!<br/>',NULL,61374,1);
INSERT INTO stanza VALUES('I257','chorus','Haleluya!<br/>Ku t''lah dapat<br/>yang lama ku dambakan!<br/>Hasratku Kristus puaskan,<br/>d''ngan hayat-Nya ku s''lamat!<br/>',NULL,61375,2);
INSERT INTO stanza VALUES('I257','2','Dulu makan ampas kacang,<br/>hingga hilang tenaga,<br/>Hati ingin makan lezat,<br/>tapi sayang, tak dapat.<br/>',NULL,61376,3);
INSERT INTO stanza VALUES('I257','3','Dulu miskin, cari kaya,<br/>agar laparku lepas;<br/>Tapi lumpur yang ku dapat,<br/>aku malu jadinya.<br/>',NULL,61377,4);
INSERT INTO stanza VALUES('I257','4','Air hayat t''rus mengalir,<br/>roti hayat pun gratis,<br/>Limpah kaya-Nya tak terp''ri,<br/>semua bagiku kini.<br/>',NULL,61378,5);
INSERT INTO stanza VALUES('I258','1','Dulu hati duka m''rana,<br/>tiada hidup kekal;<br/>Kini Kristus yang meraja,<br/>hatiku p''nuh girang.<br/>',NULL,61379,1);
INSERT INTO stanza VALUES('I258','chorus','Yesus memuaskan hatiku,<br/>tiada lain p''ri Dia;<br/>Kasih, hidup, riang, bah''gia,<br/>Yesus-lah yang b''rikan.<br/>',NULL,61380,2);
INSERT INTO stanza VALUES('I258','2','Nikmat dunia t''lah ku rasa,<br/>tapi tetap dah''ga;<br/>Meski dunia serba ada,<br/>tak puaskan beta.<br/>',NULL,61381,3);
INSERT INTO stanza VALUES('I258','3','Dulu berkat yang ku damba,<br/>bukan diri Kristus;<br/>Juru-s''lamat ku lalaikan,<br/>tapi Dia cariku.<br/>',NULL,61382,4);
INSERT INTO stanza VALUES('I258','4','Aneka air t''lah ku minum,<br/>ingin cari puas;<br/>Ternyata sia-sia belaka,<br/>aku tetap dah''ga.<br/>',NULL,61383,5);
INSERT INTO stanza VALUES('I258','5','Tiada berkat, hati duka,<br/>belum ta''u Dia datang;<br/>Dia celik mata hatiku,<br/>ta''ulah Dia tersayang.<br/>',NULL,61384,6);
INSERT INTO stanza VALUES('I259','1','Mengapa kurnia yang ajaib,<br/>padaku Allah b''ri?<br/>Mengapa bagi yang keji,<br/>Dia mau t''rima mati?<br/>',NULL,61385,1);
INSERT INTO stanza VALUES('I259','chorus','Hanya ku ta''u yang ku percaya,<br/>yakin bagi-Nya tiada mustahil;<br/>Dia jaga hingga abadi,<br/>pertaruhanku ini!<br/>',NULL,61386,2);
INSERT INTO stanza VALUES('I259','2','Mengapa iman Allah b''ri,<br/>masuk dalam hati,<br/>Hati baru ku miliki,<br/>demi iman ini?<br/>',NULL,61387,3);
INSERT INTO stanza VALUES('I259','3','Mengapa Roh Kudus kini<br/>selalu memimpin,<br/>Agar Yesus yang p''nuh kasih,<br/>meraja di hati?<br/>',NULL,61388,4);
INSERT INTO stanza VALUES('I259','4','Ku tak ta''u nasibku nanti,<br/>manis atau getir;<br/>Seb''lum aku jumpa Tuhan,<br/>apa yang ''kan nimpa.<br/>',NULL,61389,5);
INSERT INTO stanza VALUES('I259','5','Bila kelak Tuhan datang,<br/>aku ''kan di mana?<br/>Aku tertambat di dunia,<br/>ataukah terangkat?<br/>',NULL,61390,6);
INSERT INTO stanza VALUES('I260','1','Dasar yang teguh<br/>bagi kaum ber-i-man,<br/>dalam firman-Nya<br/>nyatalah d''ngan tegas.<br/>Sandar pada-Nya,<br/>Dia-lah perlindungan,<br/>Allah menjamin<br/>kau sentosa s''lama,<br/>Allah menjamin<br/>kau sentosa s''lama.<br/>',NULL,61391,1);
INSERT INTO stanza VALUES('I260','2','Percaya Yesus,<br/>s''lama tak binasa,<br/>Sia-pa dapat m''rebut<br/>dari tangan-Nya?<br/>Bapa teragung,<br/>Yesus pun de-mi-kian.<br/>Dalam tangan Yesus,<br/>kau takkan hilang.<br/>Dalam tangan Yesus,<br/>kau takkan hilang<br/>',NULL,61392,2);
INSERT INTO stanza VALUES('I260','3','Yang Dia benarkan,<br/>sia-pa ''kan menggugat?<br/>Yang t''lah Dia tebus,<br/>sia-pa ''kan menuntut?<br/>Allah b''ri berkat,<br/>sia-pa ''kan menentang?<br/>Yesus cinta kau,<br/>sia-pa ''kan pisahkan?<br/>Yesus cinta kau,<br/>sia-pa ''kan pisahkan?<br/>',NULL,61393,3);
INSERT INTO stanza VALUES('I260','4','Sia-pa milik-Nya,<br/>kekal takkan Dia buang;<br/>Sia-pa sandar Dia,<br/>Dia tolong s''lamanya.<br/>Dia-lah hayatmu,<br/>kaulah anggota-Nya;<br/>D''ngan Dia bersatu,<br/>tak mungkin berpisah.<br/>D''ngan Dia bersatu,<br/>tak mungkin berpisah<br/>',NULL,61394,4);
INSERT INTO stanza VALUES('I260','5','Waktu si jahat<br/>datang menggodamu,<br/>Hatimu g''lisah,<br/>p''ri ombak, menderu;<br/>Pegang firman-Nya,<br/>teguhkan imanmu,<br/>Ku-at pun kukuh,<br/>s''lamanya tak runtuh,<br/>Ku-at pun kukuh,<br/>s''lamanya tak runtuh,<br/>',NULL,61395,5);
INSERT INTO stanza VALUES('I261','1','Hai yang t''rima kurnia,<br/>sorak gempita,<br/>Panjatkan syukur,<br/>masyhurkan kurnia-Nya!<br/>Kau ditebus-Nya,<br/>pun dib''ri hayat-Nya,<br/>Mari puji Yesus,<br/>mari puji Yesus,<br/>Mari puji Yesus,<br/>Juru-selamat.<br/>',NULL,61396,1);
INSERT INTO stanza VALUES('I261','2','Hai, yang dicinta-Nya,<br/>teguh tak goyah,<br/>Panjatkan syukur,<br/>masyhurkan cinta-Nya!<br/>Kau dis''lamatkan,<br/>juga dihuni-Nya.<br/>Mari junjung Yesus,<br/>mari junjung Yesus,<br/>Mari junjung Yesus,<br/>Juru-selamat.<br/>',NULL,61397,2);
INSERT INTO stanza VALUES('I261','3','Hai yang dipanggil-Nya,<br/>kudus pun mulia,<br/>Panjatkan syukur,<br/>masyhurkan nama-Nya!<br/>Dia almuhit,<br/>juga Maharaja.<br/>Mari sembah Yesus,<br/>mari sembah Yesus,<br/>Mari sembah Yesus,<br/>Juru-selamat.<br/>',NULL,61398,3);
INSERT INTO stanza VALUES('I262','1','Cah''ya mulia t''rangi jiwaku,<br/>makin mulia terang;<br/>Keg''lapan terusir dariku,<br/>kar''na Tuhan terang.<br/>',NULL,61399,1);
INSERT INTO stanza VALUES('I262','chorus','Cah''ya mulia! Cah''ya bah''gia!<br/>Bawa damai, riang gembira!<br/>Seri wajah Yesus padaku,<br/>men''rangiku selalu!<br/>',NULL,61400,2);
INSERT INTO stanza VALUES('I262','2','Musik mengg''lora di jiwaku,<br/>puji Tuhan Raja;<br/>Tuhan s''nang dengar musik itu,<br/>yang t''rus ku nyanyikan.<br/>',NULL,61401,3);
INSERT INTO stanza VALUES('I262','3','Damai membanjiri jiwaku,<br/>s''bab Dia di dalamku,<br/>Roh damai bergita dalamku,<br/>bunga kurnia mekar.<br/>',NULL,61402,4);
INSERT INTO stanza VALUES('I262','4','Riang memenuhi jiwaku,<br/>pun puji dan harap,<br/>Tuhan b''ri kurnia kepadaku,<br/>biar ku kecap surga.<br/>',NULL,61403,5);
INSERT INTO stanza VALUES('I263','1','Hari ini ku putuskan,<br/>pilih Yesus Penolongku!<br/>Hati riang, bagai bara,<br/>sebar luas b''rita girang.<br/>',NULL,61404,1);
INSERT INTO stanza VALUES('I263','chorus','Hari nan bahagia!<br/>Yesus Tuhan, girangkanku!<br/>Darah adi cuci dosa!<br/>Air hayat lerai haus!<br/>Hari nan bahagia!<br/>Yesus Tuhan, girangkanku!<br/>',NULL,61405,2);
INSERT INTO stanza VALUES('I263','2','Putusanku tak ku sesal,<br/>Dia milikku, ku milik-Nya;<br/>Dia menarik, aku ikut,<br/>ku menjawab panggilan-Nya.<br/>',NULL,61406,3);
INSERT INTO stanza VALUES('I263','3','Dulu ragu, cabang hati,<br/>kini Tuhan, inti unik;<br/>Hanya Dia, tiada lain,<br/>ada Dia, berkat pasti.<br/>',NULL,61407,4);
INSERT INTO stanza VALUES('I263','4','Depan Tuhan ku tetapkan,<br/>kian hari kian segar;<br/>Hingga nanti tutup mata,<br/>masuk mulia, makin mesra.<br/>',NULL,61408,5);
INSERT INTO stanza VALUES('I264','1','Sungguh rahasia!<br/>Kristus satu dengan orang dosa.<br/>Siapa, apa, dan kapan pun,<br/>tak dapat pisahkan.<br/>Haleluya! Haleluya!<br/>Rahasia mulia!<br/>Sungguh rahasia!<br/>Dalam Tuhan, ku esa d''ngan Allah.<br/>',NULL,61409,1);
INSERT INTO stanza VALUES('I264','2','Betapa unggul!<br/>Aku telah bangkit bersama Dia!<br/>Sejak kini dosa dan setan,<br/>gangguku tak dapat.<br/>Haleluya! Haleluya!<br/>Unggul nan mulia!<br/>Betapa unggul!<br/>Kini aku hidup bersama Dia.<br/>',NULL,61410,2);
INSERT INTO stanza VALUES('I265','1','Kristus milikku, amat bah''gia!<br/>Kecap mulia-Nya girang sungguh!<br/>Tertebus darah, t''rima kurnia;<br/>jadi anak-Nya lahir baru.<br/>',NULL,61411,1);
INSERT INTO stanza VALUES('I265','chorus','''Nilah b''ritaku dan kidungku,<br/>pujilah pada Juru-s''lamat!<br/>''Nilah b''ritaku dan kidungku,<br/>pujilah pada Juru-s''lamat!<br/>',NULL,61412,2);
INSERT INTO stanza VALUES('I265','2','Hatiku bers''rah, jadi tent''ram,<br/>suasana t''rangkat telah nyata;<br/>Datanglah suara dari surga,<br/>umumkan rahmat dan kasih-Nya.<br/>',NULL,61413,3);
INSERT INTO stanza VALUES('I265','3','Ku patuh sungguh, t''rima sabat;<br/>sekutu d''ngan-Nya, amat berkat;<br/>Harap Dia datang dengan siaga;<br/>kasih mesra-Nya berlimpahlah.<br/>',NULL,61414,4);
INSERT INTO stanza VALUES('I266','1','Ku tak cakap memahami<br/>murad ketetap-an Allah;<br/>Hanya tahu Juru-s''la-mat<br/>ada di kanan Allah.<br/>',NULL,61415,1);
INSERT INTO stanza VALUES('I266','2','Dia mati ''tuk orang dosa,<br/>firman Allah, ku percaya;<br/>Dalam hati aku perlu,<br/>Dia jadi Penyelamat.<br/>',NULL,61416,2);
INSERT INTO stanza VALUES('I266','3','Ti-a-da-kah jalan la-in<br/>bagi Allah, ku tak tahu!<br/>Puji syukur ku panjatkan,<br/>bagi Jurus''lamatku!<br/>',NULL,61417,3);
INSERT INTO stanza VALUES('I266','4','Dia tinggalkan surga mu-lia,<br/>turun du-nia menderita;<br/>Aneh jika belum kenal,<br/>Di-a Sang Penyelamat.<br/>',NULL,61418,4);
INSERT INTO stanza VALUES('I266','5','Semoga hatiku nampak,<br/>kha-si-at jerih lelah-Nya;<br/>Dia pu-as atas karya-Nya,<br/>p''ri ku pu-as t''radap-Nya.<br/>',NULL,61419,5);
INSERT INTO stanza VALUES('I266','6','Ba-ik hidup atau mati,<br/>dapat t''naga, hiburan-Nya;<br/>Kini hidup, Raja kekal,<br/>tempuh wafat, Dia pernah.<br/>',NULL,61420,6);
INSERT INTO stanza VALUES('I267','1','Bertahun-tahun hidup sia-sia,<br/>tak peduli Tuhan terpentang;<br/>Tak tahu bagiku wafat-Nya,<br/>di Golgota.<br/>',NULL,61421,1);
INSERT INTO stanza VALUES('I267','chorus','Kurnia gratis, rahmat besar,<br/>semua dosa terampunkan,<br/>Orak dan lepas beban berat,<br/>di Golgota.<br/>',NULL,61422,2);
INSERT INTO stanza VALUES('I267','2','Terang sorot, nampaklah dosa,<br/>depan hukum takut pun gentar;<br/>Hingga hati mutlak mengarah,<br/>ke Golgota.<br/>',NULL,61423,3);
INSERT INTO stanza VALUES('I267','3','Kini s''mua tersembah pada-Nya,<br/>sukarela jadi hamba-Nya;<br/>Kekal tak lupakan d''rita-Nya,<br/>di Golgota.<br/>',NULL,61424,4);
INSERT INTO stanza VALUES('I267','4','Kasih rancang penyelamatan,<br/>bawakan kurnia ke manusia;<br/>Kuasa giringku ke Allah,<br/>di Golgota.<br/>',NULL,61425,5);
INSERT INTO stanza VALUES('I268','1','Damai p''ri sungai menyertai jalanku;<br/>duka p''ri ombak menggulung;<br/>Apa pun jadi, Dia ajarku bers''ru:<br/>tenanglah, damailah jiwaku!<br/>',NULL,61426,1);
INSERT INTO stanza VALUES('I268','chorus','Tenanglah, jiwaku!<br/>Tenanglah,<br/>damailah, jiwaku!<br/>',NULL,61427,2);
INSERT INTO stanza VALUES('I268','2','Meskipun Iblis menyerang d''ngan ganas,<br/>hatiku tetap tak goyah;<br/>Kar''na Tuhan ta''u, ku tidak berdaya;<br/>bagiku Dia g''napkan tebusan.<br/>',NULL,61428,3);
INSERT INTO stanza VALUES('I268','3','Kini diriku penuh angan mulia,<br/>kar''na dosaku Dia tanggung;<br/>Semua terpaku pada Salib Kristus,<br/>tak lagi diriku yang pikul.<br/>',NULL,61429,4);
INSERT INTO stanza VALUES('I268','4','Kini bagiku hidup ialah Kristus,<br/>walau g''lap maut menggulung,<br/>Tiada derita, baik mati ''tau hidup,<br/>Dia hembus damai ke jiwaku.<br/>',NULL,61430,5);
INSERT INTO stanza VALUES('I268','5','Tuhan, Peny''lamat, ku tunggu balik-Mu!<br/>Yang ku harap bukan kubur;<br/>Saat terdengar bunyi sangkakala,<br/>ku t''rangkat, depan-Mu, s''lamanya.<br/>',NULL,61431,6);
INSERT INTO stanza VALUES('I269','1','Bagai rusa yang rindukan<br/>air pelerai dah''ga,<br/>Jiwaku rindukan Tuhan<br/>dan kurnia segar-Nya.<br/>',NULL,61432,1);
INSERT INTO stanza VALUES('I269','2','Allah hidup, Kau Allahku,<br/>hati rindukan-Mu,<br/>Moga intim ku dengan Kau,<br/>nikmati diri-Mu.<br/>',NULL,61433,2);
INSERT INTO stanza VALUES('I269','3','Kau-lah hayat, tenagaku,<br/>pun kediamanku.<br/>Dalam Kristus, Kau ku sesap,<br/>pula ku dapatkan.<br/>',NULL,61434,3);
INSERT INTO stanza VALUES('I269','4','Senyum-Mu, kes''lamatanku,<br/>ku pandang pada-Mu,<br/>Penyertaan-Mu ku pinta,<br/>mohon curah kurnia.<br/>',NULL,61435,4);
INSERT INTO stanza VALUES('I269','5','Bagai rusa rindukan air,<br/>mohon Kau yang lerai,<br/>Selain Kau tiada yang mampu,<br/>hanya Kau ku perlu.<br/>',NULL,61436,5);
INSERT INTO stanza VALUES('I270','1','Yang aku tuntut Allah melulu,<br/>bukanlah senang, bukanlah bah''gia;<br/>Ku mampu masuk ke tempat kudus,<br/>bukan t''nagaku, m''lainkan kurnia-Nya.<br/>',NULL,61437,1);
INSERT INTO stanza VALUES('I270','2','Maju d''ngan iman, dapatkan Allah,<br/>Ikut d''ngan kasih, tak condong yang lain;<br/>Tuhan tolongku, lepaskan diri,<br/>Hingga s''galanya dalamku p''nuhi.<br/>',NULL,61438,2);
INSERT INTO stanza VALUES('I270','3','Meski jalanku penuh d''ngan ngeri,<br/>Meski korbanku sering tak terp''ri,<br/>Tapi Allah ta''u keperluanku,<br/>Cara dapat Dia selalu lurus.<br/>',NULL,61439,3);
INSERT INTO stanza VALUES('I270','4','Satu yang ku ta''u, Allah tak salah,<br/>Satu yang ku buat cari Dia m''lulu;<br/>Setiap waktu Allah yang ku perlu,<br/>Allah muliaku, itu upahku.<br/>',NULL,61440,4);
INSERT INTO stanza VALUES('I271','1','Allah kuasa, hayat non ciptaan,<br/>mohon dengar doa dan s''ruanku;<br/>Mulia mengelilingi diri-Mu,<br/>Pemb''ri-hayat, luluskan pintaku.<br/>',NULL,61441,1);
INSERT INTO stanza VALUES('I271','2','Lewat salib yang Kristus alami,<br/>lewat khasiat kematian-Nya;<br/>Ku terlepas dari kuasa gelap,<br/>masuk dalam k''rajaan terang-Nya.<br/>',NULL,61442,2);
INSERT INTO stanza VALUES('I271','3','Dari batin Kau memenuhiku,<br/>meluas mencapai pelosokku;<br/>Seanteroku tiada tersisa,<br/>nyata pancarkan terang mulia-Mu.<br/>',NULL,61443,3);
INSERT INTO stanza VALUES('I271','4','Kau Sang Kudus, hayat non ciptaan,<br/>Sang Roh hayat tinggal di hatiku,<br/>Garap peran demi mulia-Mu,<br/>kecuali diri-Mu, tak ku perlu.<br/>',NULL,61444,4);
INSERT INTO stanza VALUES('I271','5','Bapa, t''rima kasih, ''tas kurnia-Mu,<br/>dengan Kristus m''raja dalam hayat,<br/>Bermegah pun puas dalam Kristus,<br/>lewat salib nikmat limpah hayat.<br/>',NULL,61445,5);
INSERT INTO stanza VALUES('I272','1','Semak duri di gurun,<br/>terbakar bagi Allah!<br/>Rahmat ini ku rindu,<br/>mulia-Mu tertampak.<br/>',NULL,61446,1);
INSERT INTO stanza VALUES('I272','2','Semaknya biasa saja,<br/>ajaib, ''nyatakan Allah,<br/>Nyata kuasa Allah,<br/>terpampang mujizat-Nya.<br/>',NULL,61447,2);
INSERT INTO stanza VALUES('I272','3','Diri Allah yang nyala,<br/>bukan bahan bakarnya,<br/>Mulia-Nya ternyata,<br/>itu justru hasrat-Nya.<br/>',NULL,61448,3);
INSERT INTO stanza VALUES('I272','4','Api atas belukar,<br/>mengekspresikan Allah,<br/>Agar lewat kurnia,<br/>mulia-Nya nyata bulat.<br/>',NULL,61449,4);
INSERT INTO stanza VALUES('I273','1','Hari depanku Kau atur ulang,<br/>Bangunanku Kau bumi ratakan;<br/>Pelayan setia makin kurang,<br/>Salah kian tambah, murni kian pudar.<br/>',NULL,61450,1);
INSERT INTO stanza VALUES('I273','chorus','Mata berlinang, nampak Kau tak jelas,<br/>Sabda-Mu seolah meragukan;<br/>Aku kian kurang, agar Kau kian tambah,<br/>Sehingga kehendak-Mu kian mesra.<br/>',NULL,61451,2);
INSERT INTO stanza VALUES('I273','2','Hampir ku jerit kar''na tak tahan,<br/>Mengharap tangan-Mu Kau hentikan.<br/>Kau-lah Allah, mana boleh ''ngalah?<br/>Jangan mengalah, aku mau taat.<br/>',NULL,61452,3);
INSERT INTO stanza VALUES('I273','3','Bila kehendak serta gemar-Mu,<br/>Tergantung pada kuk deritaku,<br/>Moga senangku sama senang-Mu,<br/>Apa derita aku pun mau.<br/>',NULL,61453,4);
INSERT INTO stanza VALUES('I273','4','Seolah Kau senang aku rebah,<br/>Oleh bendungan dan rintangan-Mu,<br/>Dengan rela ku sambut semua,<br/>Asalkan puas lega hati-Mu.<br/>',NULL,61454,5);
INSERT INTO stanza VALUES('I273','5','Yang lain duduk manja di kereta,<br/>Lintas gilas atas kepalaku;<br/>Sungguh tuntas adaku Kau kupas,<br/>Mohon Kau b''ri tangan garapan-Mu.<br/>',NULL,61455,6);
INSERT INTO stanza VALUES('I274','1','Kasih ilahi nan unggul,<br/>limpahkan gita surga;<br/>Tinggal dalamku nan nista,<br/>jadi pahala iman.<br/>Dikau Perahmat, ya Tuhan,<br/>Sang Kasih nan tak batas;<br/>Bawa kurnia kes''lamatan,<br/>ke dalam yang percaya.<br/>',NULL,61456,1);
INSERT INTO stanza VALUES('I274','2','Hembus Roh-Mu kepadaku,<br/>dalam hati yang bingung;<br/>Ku berbagian limpah-Mu,<br/>nikmat sabat janji-Mu.<br/>Buang cenderung dosaku,<br/>singkir semua belenggu;<br/>Agar kenal firman hidup,<br/>merdekaku seluruh.<br/>',NULL,61457,2);
INSERT INTO stanza VALUES('I274','3','Tuhan kuasa meny''lamatkan,<br/>b''riku hayat berlimpah;<br/>Moga kekal Kau beserta,<br/>di bait-Mu ku tinggal.<br/>Ku ''kan memuji nama-mu,<br/>layani seturut-Mu;<br/>Tidak henti doa syukur,<br/>bermegah ''tas kasih-Mu.<br/>',NULL,61458,3);
INSERT INTO stanza VALUES('I274','4','Ciptaan baru Kau g''napkan,<br/>murni tidak bercela;<br/>Kes''lamatan-Mu ku nikmat,<br/>dengan Kau berserupa.<br/>Dibarui, dimuliakan,<br/>tumbuh perawakan-Mu;<br/>Hingga masuk dalam mulia,<br/>kekal puji kasih-Mu.<br/>',NULL,61459,4);
INSERT INTO stanza VALUES('I275','1','Tuhanku! Kasihku!<br/>Ku remehkan halku;<br/>Siapa p''ri Kau elok agung?<br/>Mesra manis, lemah lembut?<br/>Kau-lah paling unggul!<br/>Siapa saingan-Mu?<br/>',NULL,61460,1);
INSERT INTO stanza VALUES('I275','2','Tuhanku! Kasihku!<br/>Ku dengar panggil-Mu;<br/>Suara-Mu resap di kalbu,<br/>hingga lucut s''mua tegarku,<br/>Cita dan banggaku,<br/>hampa pula luntur.<br/>',NULL,61461,2);
INSERT INTO stanza VALUES('I275','3','Tuhanku! Kasihku!<br/>Bolehkah ku bangkang?<br/>Tegar ku buang ke duli-Mu,<br/>pulang rumah nyanyi kidung,<br/>Menjadi hamba-Mu,<br/>taat Kau sepenuh.<br/>',NULL,61462,3);
INSERT INTO stanza VALUES('I275','4','Tuhanku! Kasihku! Ku pilih jalan-Mu;<br/>Sambil patuh, sambil sedu,<br/>tapi ku tak ubah maksud,<br/>Cari perkenan-Mu,<br/>d''rita pun ku mau.<br/>',NULL,61463,4);
INSERT INTO stanza VALUES('I275','5','Tuhanku! Kasihku! Semenjak pergi-Mu;<br/>Wajahku tak pernah senyum,<br/>langitku selalu mendung,<br/>Balik-Mu ku tunggu,<br/>hadir-Mu ku rindu.<br/>',NULL,61464,5);
INSERT INTO stanza VALUES('I275','6','Tuhanku! Kasihku! Dengar utaraku;<br/>Dikau m''lulu lamunanku,<br/>Dikau pula puas maremku,<br/>Ada Kau ku cukup,<br/>lain tak ku tuntut.<br/>',NULL,61465,6);
INSERT INTO stanza VALUES('I275','7','Tuhanku! Kasihku!<br/>Ku s''rahkan s''galaku;<br/>Siapa p''ri Kau elok agung,<br/>mesra manis, lemah lembut?<br/>Kaulah paling unggul!<br/>Siapa saingan-Mu?<br/>',NULL,61466,7);
INSERT INTO stanza VALUES('I276','1','Buah hatiku Kau ambil,<br/>berilah diri-Mu;<br/>Jika aku masih ragu,<br/>berilah diri-Mu;<br/>',NULL,61467,1);
INSERT INTO stanza VALUES('I276','chorus','Yesus, Juru-s''lamatku,<br/>tambahkan diri-Mu;<br/>Taat mutlak ku mau,<br/>tambahkan diri-Mu.<br/>',NULL,61468,2);
INSERT INTO stanza VALUES('I276','2','Bintang harapanku kelam,<br/>berilah diri-Mu;<br/>Hatiku Kau biarkan bimbang,<br/>berilah diri-Mu.<br/>',NULL,61469,3);
INSERT INTO stanza VALUES('I276','3','Sandaranku Kau runtuhkan,<br/>berilah diri-Mu;<br/>Permohonanku Kau tolak,<br/>berilah diri-Mu.<br/>',NULL,61470,4);
INSERT INTO stanza VALUES('I276','4','Andai masih harus sabar,<br/>tetap b''ri diri-Mu;<br/>Andai Kau b''lum juga tiba,<br/>tambahkan diri-Mu.<br/>',NULL,61471,5);
INSERT INTO stanza VALUES('I277','1','Mari, datanglah! Pintu terbuka!<br/>''Nilah suara-Mu, ku mengenalnya.<br/>Senja berlalu, badai menerjang;<br/>''Nilah saat-Mu, Tuhan, marilah!<br/>',NULL,61472,1);
INSERT INTO stanza VALUES('I277','2','Ruang terlantar, porak poranda;<br/>Perabotan pun tidak tertata;<br/>Kursi dan meja, serak b''rantakan;<br/>Apa sikap sambut Tamu kekal?<br/>',NULL,61473,2);
INSERT INTO stanza VALUES('I277','3','Sungguh kasihan keadaannya;<br/>Dikau ku undang, Tuhan, marilah!<br/>Terang-Mu pancar dalam keg''lapan;<br/>Mari tangan-Mu atur semua.<br/>',NULL,61474,3);
INSERT INTO stanza VALUES('I277','4','Depan Sang Agung, tamu mulia;<br/>Tak lagi harap, perbaikan, amal;<br/>S''galanya kurang, serbalah bejat;<br/>Terpaksa Kau tetap menantikan.<br/>',NULL,61475,4);
INSERT INTO stanza VALUES('I277','5','Mari, marilah! Tuhan, layakkan;<br/>Hatiku jadi tempat Kau tinggal;<br/>Gelap dan dosa mutlak terenyah;<br/>Mari masuk! Marilah, ya Tuhan!<br/>',NULL,61476,5);
INSERT INTO stanza VALUES('I278','1','Maha terang, mari!<br/>Enyah malam nista,<br/>Terbit siang suci,<br/>Maha terang, mari!<br/>',NULL,61477,1);
INSERT INTO stanza VALUES('I278','chorus','O, mari, Maha terang,<br/>tinggal di hatiku;<br/>O, Tuhan sukacita,<br/>tinggal di hatiku.<br/>',NULL,61478,2);
INSERT INTO stanza VALUES('I278','2','Mahariang, mari!<br/>Usir getir dosa;<br/>Damai p''nuhi hati,<br/>Mahariang, mari!<br/>',NULL,61479,3);
INSERT INTO stanza VALUES('I278','3','Mahahayat, mari!<br/>Telan maut dosa,<br/>Bangkitkan di hati,<br/>Mahahayat, mari!<br/>',NULL,61480,4);
INSERT INTO stanza VALUES('I278','4','Mahakasih, mari!<br/>Singkir dengki dosa;<br/>Perbarui hati,<br/>Mahakasih, mari!<br/>',NULL,61481,5);
INSERT INTO stanza VALUES('I278','5','Mahatinggi, mari!<br/>Singkap awan pekat;<br/>Ricuh dunia singkir,<br/>Mahatinggi, mari!<br/>',NULL,61482,6);
INSERT INTO stanza VALUES('I278','6','Allah, Tuhan mari,<br/>berhuni di hati;<br/>K''limpahan-Mu hadir,<br/>Allah, Tuhan, mari!<br/>',NULL,61483,7);
INSERT INTO stanza VALUES('I279','1','Tuhan, dengan limpah,<br/>mari, beri pengayoman hati;<br/>Bersihkan nurani.<br/>Diri-Mu suplai tak henti,<br/>Biar limpah-Mu ku nikmati;<br/>Dari-Mu ku lahir.<br/>',NULL,61484,1);
INSERT INTO stanza VALUES('I279','2','Tiada yang dapat pisahkan,<br/>ku tersalib bersama-Mu;<br/>Hidup bagi Allah.<br/>Mati terhadap dunia,<br/>berhala dan pelesiran;<br/>Kau jadi muliaku.<br/>',NULL,61485,2);
INSERT INTO stanza VALUES('I279','3','Damba nan tak kunjung susut,<br/>rindu nan tak kunjung putus;<br/>Kau jantung hatiku.<br/>Selain Kau ku tak mau,<br/>diri-Mu jadi kurniaku;<br/>Seluruh ada-Mu.<br/>',NULL,61486,3);
INSERT INTO stanza VALUES('I279','4','Lenyap benam masa silam,<br/>sejak kini Kau s''galanya;<br/>Bagianku kekal.<br/>Terpanggil dalam sekutu,<br/>selain Kau ku tak damba;<br/>Mari, Tuhan kurnia!<br/>',NULL,61487,4);
INSERT INTO stanza VALUES('I280','1','Tuhan, Dikau-lah hayatku,<br/>pula suplai hayat;<br/>Jagalah ku di dalam roh,<br/>limpah dalam hayat.<br/>',NULL,61488,1);
INSERT INTO stanza VALUES('I280','2','Garap diri-Mu atasku,<br/>tiupi dengan Roh;<br/>Ku terlibat terpaku-Mu,<br/>serupa wafat-Mu.<br/>',NULL,61489,2);
INSERT INTO stanza VALUES('I280','3','Kau kalahkan maut, Iblis,<br/>kami gumul masih;<br/>Mohon Kau garap di batin,<br/>bunuh sambil suplai.<br/>',NULL,61490,3);
INSERT INTO stanza VALUES('I280','4','Alamiah Kau matikan,<br/>Dikau tergarapkan;<br/>Kubur pendam ku seluruh,<br/>hidupku dengan-Mu.<br/>',NULL,61491,4);
INSERT INTO stanza VALUES('I280','5','Pegang daulat di hatiku,<br/>musuh tekuk lutut;<br/>Dariku tampil citra-Mu,<br/>memperhidupkan-Mu.<br/>',NULL,61492,5);
INSERT INTO stanza VALUES('I280','6','Sisa dosa sapu bersih,<br/>diriku Kau huni;<br/>Mulia-Mu resap jenuh,<br/>mengekspresikan-Mu.<br/>',NULL,61493,6);
INSERT INTO stanza VALUES('I281','1','Moga makin cinta pada Tuhan!<br/>Kabulkan ya, Tuhan, niat hamba.<br/>Makin cinta Tuhan,<br/>sungguh ingin hamba,<br/>Makin cinta pada Tuhan!<br/>',NULL,61494,1);
INSERT INTO stanza VALUES('I281','2','Dulu kejar dunia dan mewahnya;<br/>Kini cari Tuhan, dah''ga lenyap.<br/>Tuntutku sekarang:<br/>makin cinta Tuhan,<br/>Makin cinta pada Tuhan!<br/>',NULL,61495,2);
INSERT INTO stanza VALUES('I281','3','Biar duka lara, ujian ''nimpa;<br/>Utusan-Mu indah, sedap, mesra!<br/>Ku nyanyi kar''nanya:<br/>makin cinta Tuhan,<br/>Makin cinta pada Tuhan!<br/>',NULL,61496,3);
INSERT INTO stanza VALUES('I281','4','Bila nafas, suara, mulai renta,<br/>Irama hatiku tetap sama.<br/>Minat pun tak kurang,<br/>makin cinta Tuhan,<br/>Makin cinta pada Tuhan!<br/>',NULL,61497,4);
INSERT INTO stanza VALUES('I282','1','''Pabila jalanku ''nuju sengsara,<br/>Bila ''ni takdir-Mu, mau ku mend''rita.<br/>Ku mohon pada-Mu hubungan akrab,<br/>Tiap saat bers''kutu, lebihlah mesra.<br/>',NULL,61498,1);
INSERT INTO stanza VALUES('I282','2','Susut senang dunia, tambahkan "surga",<br/>Biar hatiku luka - roh tetap muja.<br/>Mesra, manis dunia, oleh-Mu lepas,<br/>Agar Kau denganku erat kian mesra.<br/>',NULL,61499,2);
INSERT INTO stanza VALUES('I282','3','Meski jalan sunyi, Kau serta s''lalu;<br/>Senyum-Mu tarikku, depan t''rus maju.<br/>Lepas dari diri, oleh kurnia-Mu;<br/>Jadi wadah suci, salur hayat-Mu.<br/>',NULL,61500,3);
INSERT INTO stanza VALUES('I283','1','Bangunlah, hai, angin lor! Mari angin kidul!<br/>Tiuplah taman hatiku, biar semerbak harum.<br/>Bangunlah, hai, angin lor! Mari angin kidul!<br/>Tiuplah taman hatiku, biar semerbak harum.<br/>',NULL,61501,1);
INSERT INTO stanza VALUES('I283','chorus','Agar menarik Kekasihku,<br/>berkunjung hadir,<br/>''ngecap cintaku.<br/>Agar menarik Kekasihku,<br/>berkunjung hadir,<br/>''ngecap cintaku.<br/>',NULL,61502,2);
INSERT INTO stanza VALUES('I283','2','Uraplah kepala-Nya d''ngan minyak narwastu,<br/>Dan sekalah kaki-Nya d''ngan rambut yang indah;<br/>Sementara Sang Raja, duduk di mejanya,<br/>Semerbak bau harum, penuhi ruangan.<br/>',NULL,61503,3);
INSERT INTO stanza VALUES('I283','3','Bagaikan pohon limau yang tumbuh di hutan;<br/>Ku sangat senang duduk di bawah naungannya;<br/>Buahnya manis, sedap, di langit-langitku;<br/>Menambah kekuatan, menghibur hatiku.<br/>',NULL,61504,4);
INSERT INTO stanza VALUES('I283','4','Mari, o, Kekasihku! Mari Kekasihku!<br/>Ku adalah milik-Mu, Dikau pun milikku;<br/>Biar kita berdampingan, menuju ke ladang,<br/>Menikmati bersama, aneka buah indah.<br/>',NULL,61505,5);
INSERT INTO stanza VALUES('I283','5','Semoga di hati-Nya, ku tertera p''ri cap,<br/>Kasih-Nya alangkah kuat, tidak terpadamkan.<br/>Semoga di hati-Nya, ku tertera p''ri cap,<br/>Kasih-Nya alangkah kuat, tidak terpadamkan.<br/>',NULL,61506,6);
INSERT INTO stanza VALUES('I283','6','Selain Dikau, di langit ku tiada siapa!<br/>Selain Dikau, di bumi ku tiada sasaran.<br/>Selain Dikau, di langit ku tiada siapa!<br/>Selain Dikau, di bumi ku tiada sasaran.<br/>',NULL,61507,7);
INSERT INTO stanza VALUES('I284','1','Tak bersekat,<br/>ku dengan Tuhan;<br/>wajah-Mu ku rindu,<br/>Tarikku pada-Mu,<br/>dengarkan sabda-Mu;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61508,1);
INSERT INTO stanza VALUES('I284','2','Tak bersekat,<br/>ku dengan Tuhan;<br/>biar dunia bergolak,<br/>Suara-Mu tetap j''las,<br/>ku mau setia;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61509,2);
INSERT INTO stanza VALUES('I284','3','Tak bersekat,<br/>ku dengan Tuhan;<br/>tiada kuatir dunia,<br/>Tiada gairah diri,<br/>tiada munafik;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61510,3);
INSERT INTO stanza VALUES('I284','4','Tak bersekat,<br/>ku dengan Tuhan,<br/>sewaktu Kau dekat,<br/>Prasangka sg''ra sirna,<br/>gentar pun lenyaplah;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61511,4);
INSERT INTO stanza VALUES('I284','5','Tak bersekat,<br/>ku dengan Tuhan,<br/>pancarkan terang-Mu,<br/>Telan sinar jahat,<br/>jadi Raja mulia;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61512,5);
INSERT INTO stanza VALUES('I284','6','Tak bersekat,<br/>ku dengan Tuhan;<br/>ke mana pun Tuhan,<br/>Ku mau s''lalu serta,<br/>dan milik-Mu saja;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61513,6);
INSERT INTO stanza VALUES('I284','7','Tak bersekat,<br/>ku dengan Tuhan;<br/>hingga aku nampak,<br/>Cah''ya-Mu cemerlang,<br/>gelap dunia sirna;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61514,7);
INSERT INTO stanza VALUES('I284','8','Tak bersekat,<br/>ku dengan Tuhan;<br/>hingga perang lewat,<br/>Tinggalkan yang fana,<br/>beserta-Mu s''lama;<br/>tak bersekat,<br/>tak bersekat.<br/>',NULL,61515,8);
INSERT INTO stanza VALUES('I285','1','Ke puncak gunung ku damba,<br/>agar nampak Kau s''mata;<br/>Suara surga terdengar,<br/>hawa segar ku hisap.<br/>',NULL,61516,1);
INSERT INTO stanza VALUES('I285','chorus','Bawalah ku kian ke atas,<br/>sekutu pun kian mesra;<br/>roh kian menyesap hayat,<br/>kian nikmat Sang Tuhan.<br/>',NULL,61517,2);
INSERT INTO stanza VALUES('I285','2','Kian tinggi, kian terang,<br/>s''lubung dunia terhempas;<br/>Meraja di dalam hayat,<br/>ronta diri terlepas.<br/>',NULL,61518,3);
INSERT INTO stanza VALUES('I285','3','Jagaku kian ke atas,<br/>maju pada sasaran;<br/>Dengan Kau aku serupa,<br/>nyata kasih, kurnia.<br/>',NULL,61519,4);
INSERT INTO stanza VALUES('I286','1','Ku perlu Tuhanku,<br/>tiap waktu;<br/>Lain tak selembut<br/>pelipur-Mu.<br/>',NULL,61520,1);
INSERT INTO stanza VALUES('I286','chorus','Ku perlu, o, ku perlu,<br/>tiap saat ku perlu;<br/>Tuhan, kini ku mohon,<br/>b''ri kurnia-Mu.<br/>',NULL,61521,2);
INSERT INTO stanza VALUES('I286','2','Ku perlu hadir-Mu,<br/>tiap waktu;<br/>Godaan tak mampu,<br/>ku dekat-Mu.<br/>',NULL,61522,3);
INSERT INTO stanza VALUES('I286','3','Biar senang, biar sayu,<br/>Kau ku perlu;<br/>Oleh dampingan-Mu,<br/>hilang lesu.<br/>',NULL,61523,4);
INSERT INTO stanza VALUES('I286','4','Ku perlu bimbing-Mu,<br/>tiap waktu;<br/>Dan berkat janji-Mu,<br/>genap s''luruh.<br/>',NULL,61524,5);
INSERT INTO stanza VALUES('I286','5','Ku perlu Sang Kudus,<br/>tiap waktu;<br/>Semata milik-Mu,<br/>akrab d''ngan-mu.<br/>',NULL,61525,6);
INSERT INTO stanza VALUES('I287','1','Aku milik-Mu, ''nilah sabda-Mu,<br/>tak terukur kasih-Mu;<br/>Imanku ingin terus membubung,<br/>lebih akrab dengan-Mu.<br/>',NULL,61526,1);
INSERT INTO stanza VALUES('I287','chorus','Tarik dekat, mari Pengasih,<br/>hingga sisi iga-Mu;<br/>Tarik dekat, dekat, mari Pengasih,<br/>hingga nikmat hadir-Mu.<br/>',NULL,61527,2);
INSERT INTO stanza VALUES('I287','2','Sandar kurnia-Mu, sisihkan aku,<br/>layani-Mu melulu;<br/>Biarku teguh, pandang wajah-Mu,<br/>mau ku lenyap dalam-Mu.<br/>',NULL,61528,3);
INSERT INTO stanza VALUES('I287','3','Walau sejenak, riang membubung,<br/>bila duduk depan-Mu;<br/>Depan kaki-Mu, pandang wajah-Mu,<br/>mesra akrab p''ri kawan.<br/>',NULL,61529,4);
INSERT INTO stanza VALUES('I287','4','Dalam kasih-Mu, di luar pahamku,<br/>''cuali kelak di sana;<br/>Unggul riang-Mu, tidak tergayuh,<br/>''cuali ''ngaso depan-Mu.<br/>',NULL,61530,5);
INSERT INTO stanza VALUES('I288','1','Tinggal sertaku, senja sg''ra lalu,<br/>Malam kian larut, Tuhan sertaku;<br/>Hibur sirna, bantuan tiada,<br/>Tuhan, Sang Bantuan besertaku.<br/>',NULL,61531,1);
INSERT INTO stanza VALUES('I288','2','Hidup pintas, sekejap berlalu,<br/>Mewah dunia layu p''ri rumput.<br/>Isi dunia lapuk membusuk,<br/>Kau, tak ubah, mohon Kau sertaku.<br/>',NULL,61532,2);
INSERT INTO stanza VALUES('I288','3','Tiada murka, Raja di raja,<br/>Murah hati pun b''ri kesembuhan.<br/>Duka Dia hapus, dengar doaku,<br/>Teman orang dosa, besertaku.<br/>',NULL,61533,3);
INSERT INTO stanza VALUES('I288','4','Setiap waktu perlu hadir-Mu,<br/>Datang kurnia-Mu, setan sg''ra kabur.<br/>Hanya Engkau yang papah tunjangku,<br/>Cerah, mendung, Tuhan besertaku.<br/>',NULL,61534,4);
INSERT INTO stanza VALUES('I288','5','Kau b''ri berkat, ku tak takut musuh,<br/>Derita, sakit, air mata hapus.<br/>Apakah racun, maut, dan kubur?<br/>Ku kalahkan, asal Kau sertaku.<br/>',NULL,61535,5);
INSERT INTO stanza VALUES('I288','6','Menjelang ajal, mohon serta-Mu,<br/>Menyorot terang, pandang wajah-Mu.<br/>Fajar sg''ra tiba, bayang maut pupus,<br/>Betapa pun mohon Kau sertaku.<br/>',NULL,61536,6);
INSERT INTO stanza VALUES('I289','1','Yesus, moga Kau terjunjung!<br/>Syarat, upacara,<br/>Perhimpunan, kasih dunia,<br/>bukan bandingan-Mu.<br/>',NULL,61537,1);
INSERT INTO stanza VALUES('I289','2','Yesus, moga Kau terjunjung!<br/>Jayalah kasih-Mu;<br/>Di salib-Mu ku matilah,<br/>hidupku bagi-Mu.<br/>',NULL,61538,2);
INSERT INTO stanza VALUES('I289','3','Yesus, moga Kau terjunjung!<br/>Penuhilah aku;<br/>Biar angan kegemaranku,<br/>sama p''ri Tuhanku.<br/>',NULL,61539,3);
INSERT INTO stanza VALUES('I289','4','Yesus, moga Kau terjunjung!<br/>Ubah ku seluruh;<br/>Lewat tirai (tubuh lapuk),<br/>wujudkan mulia-Mu.<br/>',NULL,61540,4);
INSERT INTO stanza VALUES('I289','5','Yesus, moga Kau terjunjung!<br/>G''nap hati ku mohon;<br/>Jadi hamba-Mu selalu,<br/>patuh kehendak-Mu.<br/>',NULL,61541,5);
INSERT INTO stanza VALUES('I290','1','Tuhan, ku rindu hidup di depan-Mu,<br/>Siang dan malam pun satu alamku;<br/>Janganlah Kau biarkan riang hatiku,<br/>Bila ku dambakan selain diri-Mu.<br/>Tiap saat, tiap hari, d''rita apa pun,<br/>Waktu riang hiburan dunia pupus.<br/>Hatiku pilu air mata tercucur.<br/>Ya, Tuhan, teduhkan keluh kesahku.<br/>',NULL,61542,1);
INSERT INTO stanza VALUES('I290','2','Tatkala terbayang hidup nan manis,<br/>Marilah Tuhanku, ikut nikmati!<br/>Janganlah biarkanku hidup sendiri,<br/>Pun jangan biarkanku pilih sendiri!<br/>''Pabila termenung di dalam sunyi,<br/>Ya, Yesus, ku minta Kau mendampingi;<br/>Menjelang tiap fajar, semasih mimpi,<br/>Gugahlah t''lingaku, serta b''ri bisik.<br/>',NULL,61543,2);
INSERT INTO stanza VALUES('I290','3','Di saat membaca firman kudus-Mu,<br/>Ku perlu sorotan cah''ya mulia-Mu;<br/>Agarlah ku nampak keadian-Mu,<br/>Pun kurnia agung-Mu, semua milikku.<br/>Depan takhta-Mu kini ku bertelut,<br/>Kabulkan doaku, beri ''nugrah-Mu;<br/>Ampuni segala kesalahanku,<br/>Janganlah padaku tarik hadir-Mu.<br/>',NULL,61544,3);
INSERT INTO stanza VALUES('I290','4','Tiap terkenang bahagia surgawi,<br/>Sg''ra pandang wajah-Mu, hatiku ingin,<br/>Balik-Mu melulu, kini ku nanti,<br/>Serta-Mu selalu, riangkan hati.<br/>Ajarku hidup depan-Mu tiap hari,<br/>Sepanjang umurku tak lain mencari,<br/>Agar kenan-Mu padaku terbukti,<br/>Di dalam angan dan gemarku ini.<br/>',NULL,61545,4);
INSERT INTO stanza VALUES('I291','1','Tuhan pimpinku hidup,<br/>dalam roh ku selalu;<br/>jalan dalam t''rang hayat,<br/>tiada meronta-ronta.<br/>',NULL,61546,1);
INSERT INTO stanza VALUES('I291','chorus','Pimpin aku,<br/>''nilah permohonanku;<br/>Demi arus hayat-Mu,<br/>''nempuh atas jalan-Mu.<br/>',NULL,61547,2);
INSERT INTO stanza VALUES('I291','2','Dalamku Kaulah hayat,<br/>tampilkan hukum hayat;<br/>Atasku Kau mem''rintah,<br/>gelap jadilah terang.<br/>',NULL,61548,3);
INSERT INTO stanza VALUES('I291','3','Leluasakan rohku,<br/>agar tertib dan patuh;<br/>Angan-anganku baru,<br/>memuaskan hati-Mu.<br/>',NULL,61549,4);
INSERT INTO stanza VALUES('I292','1','Tuhan bimbingku jalan,<br/>jauh dari yang sesat;<br/>Teguh pada sisi-Mu,<br/>tinggal dalam kasih-Mu.<br/>',NULL,61550,1);
INSERT INTO stanza VALUES('I292','chorus','Bimbing aku,<br/>jauh dari yang sesat;<br/>Jalan depan ku tak ta''u,<br/>Tuhan bimbingku jalan.<br/>',NULL,61551,2);
INSERT INTO stanza VALUES('I292','2','Kaulah Pelindung jiwa,<br/>ku takut akan apa?<br/>Kau berhampir, ku aman,<br/>Kau berahmat, ku puas.<br/>',NULL,61552,3);
INSERT INTO stanza VALUES('I292','3','Tuhan bimbingku terus,<br/>hingga kedatangan-Mu;<br/>Kekal kita bersama,<br/>nikmat, lega s''lamanya.<br/>',NULL,61553,4);
INSERT INTO stanza VALUES('I293','1','Mohon Tuhan pilihkan,<br/>jalan yang ku tempuh,<br/>Aku tiada pilihan,<br/>hanya mau k''hendak-Mu;<br/>Jalan yang Kau pilihkan,<br/>meski penuh d''rita,<br/>Dengan rela ku taat,<br/>biar hati-Mu senang.<br/>',NULL,61554,1);
INSERT INTO stanza VALUES('I293','chorus','Tuhan jabat tanganku<br/>ingatlah lemahku,<br/>Kalau tidak ku meng''luh<br/>betapa ku hidup;<br/>Bila Kau jabat aku,<br/>tak peduli jalan,<br/>Apa yang Kau pilihkan,<br/>aku s''lalu rela.<br/>',NULL,61555,2);
INSERT INTO stanza VALUES('I293','2','Lembah ataupun bukit,<br/>asal Kau yang pilih,<br/>Tentu ''kan ku senangi,<br/>yang lain ku tak sudi;<br/>Aku berbuat sendiri,<br/>sungguh tidak b''rani,<br/>Mohon Kau saja pilih,<br/>pasti ku turuti.<br/>',NULL,61556,3);
INSERT INTO stanza VALUES('I293','3','Waktuku pada-Mu-lah,<br/>lambat atau cepat,<br/>Atur seturut mau-Mu,<br/>ku tiada pilihan;<br/>Bila Kau mau ku sabar,<br/>biar bertahun-tahun,<br/>Aku tetap menunggu,<br/>turut rencana-Mu.<br/>',NULL,61557,4);
INSERT INTO stanza VALUES('I293','4','Tuhan sisa umurku,<br/>mohon Kau yang atur,<br/>Senang atau sengsara,<br/>turut mau-Mu saja;<br/>Sedih menjadi manis,<br/>bila ini mau-Mu,<br/>Nikmat menjadi pahit,<br/>bila Kau tak senang.<br/>',NULL,61558,5);
INSERT INTO stanza VALUES('I293','5','Untukku Tuhan pilih,<br/>sehat atau sakit,<br/>Riang atau menangis,<br/>jahat atau baik;<br/>Perkara besar kecil,<br/>suruh ku memilih,<br/>Sungguh aku tak sudi,<br/>mulia-Mu ku nanti.<br/>',NULL,61559,6);
INSERT INTO stanza VALUES('I294','1','Pegang aku,<br/>ku tiada sandaran,<br/>Tanpa papah,<br/>takut ku melangkah;<br/>Pegang erat,<br/>ya Tuhanku, peganglah!<br/>Mara, ancaman,<br/>ku tidak gentar.<br/>',NULL,61560,1);
INSERT INTO stanza VALUES('I294','2','Pegang aku,<br/>o, pegang lebih erat,<br/>Dekat Tuhan,<br/>Kau s''gala-galaku;<br/>Pegang aku,<br/>agar ku tak menympang,<br/>Hilang dari-Mu,<br/>ku hilang, jatuh.<br/>',NULL,61561,2);
INSERT INTO stanza VALUES('I294','3','Pegang aku,<br/>entah apa di depan,<br/>Perlu sorotan<br/>wajah-Mu, Tuhan,<br/>Oleh iman,<br/>mulia-Mu tertampak,<br/>Hati gembira,<br/>kidung menggema.<br/>',NULL,61562,3);
INSERT INTO stanza VALUES('I294','4','Pegang aku!<br/>Saat lalui malam,<br/>Sunyi, pencil yang<br/>pernah Kau lewat;<br/>Di sini sorot<br/>terang dari surga,<br/>Malam gelap jadi<br/>siang terang.<br/>',NULL,61563,4);
INSERT INTO stanza VALUES('I295','1','Asalkan jalan-Mu,<br/>tak peduli gelap,<br/>Tak peduli d''rita,<br/>mohon Kau pilihkan.<br/>',NULL,61564,1);
INSERT INTO stanza VALUES('I295','2','Datar atau tanjak,<br/>pasti yang terbaik,<br/>Lurus atau liku,<br/>perhentian-Mu pimpin.<br/>',NULL,61565,2);
INSERT INTO stanza VALUES('I295','3','Ku tak b''rani pilih,<br/>walau seizin-Mu,<br/>Kau saja putusi,<br/>agar tak keliru.<br/>',NULL,61566,3);
INSERT INTO stanza VALUES('I295','4','D''rita atau senang,<br/>penuhi pialaku,<br/>Pandangan-Mu tepat,<br/>Kau yang pilih buat-ku.<br/>',NULL,61567,4);
INSERT INTO stanza VALUES('I295','5','Teman, sakit, sehat,<br/>Kau-lah yang tentukan,<br/>Tugas, miskin, marak,<br/>serah Kau belaka.<br/>',NULL,61568,5);
INSERT INTO stanza VALUES('I295','6','Hal-hal besar, kecil,<br/>bukan turut diri,<br/>Dikau yang memimpin,<br/>arif hikmat pasti.<br/>',NULL,61569,6);
INSERT INTO stanza VALUES('I296','1','Moga makin kenal Kristus,<br/>makin menempuh jalan-Nya,<br/>Makin kenal tebusan-Nya,<br/>makin nikmati limpah-Nya.<br/>',NULL,61570,1);
INSERT INTO stanza VALUES('I296','chorus','Makin kenal Kristus,<br/>makin kenal Kristus,<br/>Makin kenal tebusan-Nya,<br/>makin nikmati limpah-Nya.<br/>',NULL,61571,2);
INSERT INTO stanza VALUES('I296','2','Makin kenal kuasa bangkit,<br/>makin kenal hayat limpah,<br/>Makin kecap kuasa t''rangkat,<br/>berbagian menang mulia.<br/>',NULL,61572,3);
INSERT INTO stanza VALUES('I296','3','Makin b''roleh wahyu Roh-Nya,<br/>makin paham maksud Bapa,<br/>Makin tampak balik tirai,<br/>serupa dengan wafat-Nya.<br/>',NULL,61573,4);
INSERT INTO stanza VALUES('I296','4','Makin percaya firman-Nya,<br/>makin bersandar kurnia-Nya,<br/>Makin dambakan datang-Nya,<br/>makin harapkan daulat-Nya.<br/>',NULL,61574,5);
INSERT INTO stanza VALUES('I297','1','Biar ku makin mesra<br/>cinta Tuhan-ku,<br/>Hati makin gairah,<br/>iman makin p''nuh;<br/>Ingat ''kan d''rita-Mu,<br/>aku terharu,<br/>Dalam asuhan-Mu,<br/>ku makin patuh.<br/>',NULL,61575,1);
INSERT INTO stanza VALUES('I297','chorus','Mohon Tuhan tiap hari,<br/>b''ri tenaga, jagaku;<br/>Biar ku di jalan sempit,<br/>memuaskan hati-Mu.<br/>',NULL,61576,2);
INSERT INTO stanza VALUES('I297','2','Biar ku makin menang,<br/>pada-Mu setia,<br/>Dalam tangan Tuhan,<br/>makin berguna,<br/>Sabar dalam d''rita,<br/>sesali dosa,<br/>Makin jerih lelah,<br/>bersandar Tuhan.<br/>',NULL,61577,3);
INSERT INTO stanza VALUES('I297','3','Biar ku makin matang,<br/>pandang wajah-Mu,<br/>Dambakan datang-Mu,<br/>nikmat hadir-Mu,<br/>Makin suka m''rendah,<br/>remehkan pangkat,<br/>Makin s''ring berkorban,<br/>seperti Tuhan.<br/>',NULL,61578,4);
INSERT INTO stanza VALUES('I298','1','Tumbuh dalamku, ya, Tuhan,<br/>yang lain ku tak harap!<br/>Biar pada-Mu lebih dekat,<br/>bebas dari dosa.<br/>',NULL,61579,1);
INSERT INTO stanza VALUES('I298','chorus','Naungilah d''ngan t''naga-Mu,<br/>biar ku jadi teguh;<br/>Sinar-Mu t''rangi jalanku,<br/>hayat-Mu telan maut.<br/>',NULL,61580,2);
INSERT INTO stanza VALUES('I298','2','Waktu sinar-Mu memancar,<br/>angan jahat hilang;<br/>Biar ku sadar, aku papa,<br/>Kau kaya berlimpah.<br/>',NULL,61581,3);
INSERT INTO stanza VALUES('I298','3','Biar ku pandang Tuhan mulia,<br/>kudus tak tercela;<br/>Dalam senang atau susah,<br/>hidup-Mu ku taulad.<br/>',NULL,61582,4);
INSERT INTO stanza VALUES('I298','4','Moga girang surga m''limpah,<br/>hingga ku jadi kuat;<br/>Moga kasih-Mu membara,<br/>hingga ku bergairah.<br/>',NULL,61583,5);
INSERT INTO stanza VALUES('I298','5','Biar egoku makin susut,<br/>hanya Kau tujuanku;<br/>Biarlah ku demi kurnia-Mu,<br/>berhampir pada-Mu.<br/>',NULL,61584,6);
INSERT INTO stanza VALUES('I299','1','Roti hidup surgawi,<br/>makanan musafir;<br/>Manna yang dari atas,<br/>sesuai sifat surga.<br/>Ku damba menikmati<br/>diri-Mu nan limpah;<br/>Sirna senang dunia,<br/>hasrat terpenuh s''mua.<br/>',NULL,61585,1);
INSERT INTO stanza VALUES('I299','2','Air hayat mengalir,<br/>dari batu terb''lah;<br/>Segar, sedap pun manis,<br/>Kau-lah sumber cinta.<br/>Ku sesap dengan gratis,<br/>leraikan dahaga;<br/>Yang lain tak ku cari,<br/>minum Kau semata.<br/>',NULL,61586,2);
INSERT INTO stanza VALUES('I299','3','Makan minum diri-Mu,<br/>kami puji syukur;<br/>Dalam roh, dari firman,<br/>nikmati kasih-Mu.<br/>Ku terawat oleh-Mu,<br/>hidup bersandar-Mu;<br/>Tumbuh perawakan-Mu,<br/>tampilkan diri-Mu.<br/>',NULL,61587,3);
INSERT INTO stanza VALUES('I300','1','Serupa d''ngan Tuhan!<br/>Ku mendambakan!<br/>Tekun ku tengadah,<br/>mohon genapkan!<br/>',NULL,61588,1);
INSERT INTO stanza VALUES('I300','2','Serupa d''ngan Tuhan!<br/>Tuhan, Roh itu;<br/>Roh Tuhan menembus,<br/>niatku terwujud.<br/>',NULL,61589,2);
INSERT INTO stanza VALUES('I300','3','Wajah tak bers''lubung,<br/>pandang mulia-Nya;<br/>P''ri cermin pantulkan,<br/>rupa Sang Tuhan.<br/>',NULL,61590,3);
INSERT INTO stanza VALUES('I300','4','Moga bebas s''lubung,<br/>pantulkan Tuhan;<br/>Hati makin tulus,<br/>tampil Dia s''lalu.<br/>',NULL,61591,4);
INSERT INTO stanza VALUES('I300','5','Berhadapan wajah,<br/>memandang Tuhan;<br/>Terus menatap-Nya,<br/>hati terpikat.<br/>',NULL,61592,5);
INSERT INTO stanza VALUES('I300','6','Serupa d''ngan Tuhan,<br/>sasaran beta;<br/>Batin ditera-Nya,<br/>nyata mulia-Nya.<br/>',NULL,61593,6);
INSERT INTO stanza VALUES('I300','7','Serupa d''ngan Tuhan,<br/>makinlah mulia!<br/>Ekspresikan Tuhan,<br/>sampai s''lamanya.<br/>',NULL,61594,7);
INSERT INTO stanza VALUES('I301','1','Ku mau mirip Kau, Juru-s''lamatku,<br/>inilah doa dan dambaku;<br/>Ku rela buangkan s''mua mewah dunia,<br/>agar aku mirip dengan-Mu.<br/>',NULL,61595,1);
INSERT INTO stanza VALUES('I301','chorus','Ku mau mirip Kau, sep''ri t''ladan-Mu,<br/>Juru-s''lamatku nan p''nuh cinta;<br/>Teguh dan manis, tak pernah ubah,<br/>bentuk-Mu t''rukir di hatiku.<br/>',NULL,61596,2);
INSERT INTO stanza VALUES('I301','2','Ku mau mirip Kau, demikian ramah,<br/>penuh ampunan, kasih, rahmat;<br/>Bantu yang papa, hibur yang duka,<br/>cari yang dosa dengan gairah.<br/>',NULL,61597,3);
INSERT INTO stanza VALUES('I301','3','Ku mau mirip Kau, demikian sabar,<br/>kudus dan m''rendah, tanpa cela,<br/>Rela mend''rita banyak sengsara,<br/>tolong manusia, korban jiwa.<br/>',NULL,61598,4);
INSERT INTO stanza VALUES('I301','4','Ku mau mirip Kau, sangat ku harap,<br/>rela berkorban ikut Tuhan.<br/>Semua adaku, semua milikku,<br/>tersembah pada Tuhan m''lulu.<br/>',NULL,61599,5);
INSERT INTO stanza VALUES('I301','5','Ku mau mirip Kau, ku minta sungguh,<br/>curahkan cinta di hatiku,<br/>Biar ku jadi bait tempat tinggal-Mu,<br/>hidup-Mu tumbuh di dalamku.<br/>',NULL,61600,6);
INSERT INTO stanza VALUES('I302','1','Sungguh misterius,<br/>Roh-Mu di rohku!<br/>Dua roh jadi satu,<br/>realitas sungguh!<br/>',NULL,61601,1);
INSERT INTO stanza VALUES('I302','2','Bergerak dengan roh,<br/>rohani di roh;<br/>''Layani dengan roh,<br/>roh menyembah Roh.<br/>',NULL,61602,2);
INSERT INTO stanza VALUES('I302','3','Sekutu dalam roh,<br/>roh pasti kuat;<br/>Doa, baca d''ngan roh,<br/>roh pasti tegap.<br/>',NULL,61603,3);
INSERT INTO stanza VALUES('I302','4','Rohku dikuatkan,<br/>hidupkan orang!<br/>Rohku ditegapkan,<br/>bebaskan orang!<br/>',NULL,61604,4);
INSERT INTO stanza VALUES('I302','5','Tiap bersuara,<br/>roh tergerak s''mua!<br/>Apa pun gerakan,<br/>suplai roh ''tiasa!<br/>',NULL,61605,5);
INSERT INTO stanza VALUES('I302','6','Begitu roh gerak,<br/>yang lain terbuka!<br/>Begitu roh terjang,<br/>yang lain tertunjang!<br/>',NULL,61606,6);
INSERT INTO stanza VALUES('I302','7','Mohon Tuhan jaga,<br/>hembus dengan roh!<br/>Tiap roh berlimpah,<br/>bahkan berlipat!<br/>',NULL,61607,7);
INSERT INTO stanza VALUES('I303','1','Malaikat-Nya s''lalu lihat wajah-Nya,<br/>tapi tak kenal cinta-Nya;<br/>Kaum saleh kenal cinta-Nya tak batas,<br/>tapi b''lum lihat wajah-Nya.<br/>Tak lama, m''reka ''kan pandang wajah-Nya,<br/>kenal cahaya mulia-Nya;<br/>Tapi Maria nampak air mata-Nya,<br/>ta''u kesedihan hati-Nya,<br/>Ta''u kesedihan hati-Nya.<br/>',NULL,61608,1);
INSERT INTO stanza VALUES('I303','2','Kita segera mengenal diri-Nya,<br/>mengenal dengan sempurna;<br/>Tapi pelipur lara hari ini,<br/>tiada dirasakan kelak.<br/>Hari itu, meski penuh pujian,<br/>tapi tiada ratap doa;<br/>Tiada hiburan kar''na susah d''rita,<br/>sandaran kar''na sengsara,<br/>Sandaran kar''na sengsara.<br/>',NULL,61609,2);
INSERT INTO stanza VALUES('I303','3','Hari itu, meski ada mahkota,<br/>tapi salib telah tiada;<br/>Derita yang Dia alami bagiku,<br/>s''karanglah ku berbagian.<br/>Set''lah mengaso, tiada lagi lelah,<br/>tak sempat d''rita bagi-Nya;<br/>Tiada ujian, pun bahagia dunia<br/>yang ku korbankan bagi-Nya,<br/>Yang ku korbankan bagi-Nya.<br/>',NULL,61610,3);
INSERT INTO stanza VALUES('I303','4','Aduh! Tiada banyak waktu bagi-Nya,<br/>kesempatan seg''ra lewat;<br/>T''rima hina dan d''rita karena Dia,<br/>kelak tak berkesempatan.<br/>Tak lama lagi, tiada cerca-hina,<br/>tak lagi sebatang kara;<br/>S''mua berkat ini, harus ku indahkan,<br/>olehnya d''ngan-Mu ku esa,<br/>Olehnya d''ngan-Mu ku esa.<br/>',NULL,61611,4);
INSERT INTO stanza VALUES('I303','5','Tuhan, aku rindu nampak wajah-Mu,<br/>ini memang paling indah;<br/>Tapi ku tak mau hindarkan ujian-Mu,<br/>hingga hilang s''kutu mesra.<br/>Mohon rahmat, penuhi d''ngan kasih-Mu,<br/>tinggalkan s''gala bagi-Mu;<br/>Biar hamba jangan mendambakan kelak,<br/>kelak sesalkan yang silam,<br/>Kelak sesalkan yang silam.<br/>',NULL,61612,5);
INSERT INTO stanza VALUES('I304','1','Dariku diri-Mu hidup,<br/>Yesus Kau-lah hayatku;<br/>Atas segala soalku,<br/>Engkau-lah jawabanku.<br/>Dari ku diri-Mu hidup,<br/>s''mua turut kehendak-Mu,<br/>Wadah tembus cahaya-Mu,<br/>''nyatakan rahasia-Mu.<br/>',NULL,61613,1);
INSERT INTO stanza VALUES('I304','2','Tubuhku t''lah tersembahkan<br/>dan telah disucikan,<br/>Moga cah''ya mulia Tuhan,<br/>dari diriku nyata.<br/>Bumi harus khidmat sunyi,<br/>kar''na ku sembah diri,<br/>Jadi hamba Tuhan murni,<br/>siap t''rima p''rintah suci.<br/>',NULL,61614,2);
INSERT INTO stanza VALUES('I304','3','S''mua anggota, setiap waktu,<br/>s''lalu tunggu p''rintah-Mu,<br/>Siap sedialah menanggung kuk,<br/>yang tak guna sampingkan.<br/>Dengan sentosa tuntut t''rus,<br/>tiada tegang dan berat,<br/>Tak bersungut kar''na cela,<br/>tak jatuh kar''na sesal.<br/>',NULL,61615,3);
INSERT INTO stanza VALUES('I304','4','Lemah lembut, tenang, henti;<br/>lepas dari mau diri,<br/>Agar kehendak-Mu jadi,<br/>apa yang Tuhan maui.<br/>Dariku diri-Mu hidup,<br/>Yesus, Kau-lah hayatku,<br/>Atas segala soalku,<br/>Engkau-lah jawabanku.<br/>',NULL,61616,4);
INSERT INTO stanza VALUES('I305','1','Bapa, ku ta''u seumurku,<br/>t''lah rapi Kau atur;<br/>Meski segala ''kan b''rubah,<br/>aku tidak takut;<br/>Mohon jaga ku setia,<br/>mencari senyum-Mu.<br/>',NULL,61617,1);
INSERT INTO stanza VALUES('I305','2','B''riku kasih nan "berarti",<br/>hikmat nan siaga;<br/>Hadapi s''gala d''ngan bers''ri,<br/>sekalah air mata;<br/>Hati p''nuh hibur, simpati,<br/>s''perti hati Tuhan.<br/>',NULL,61618,2);
INSERT INTO stanza VALUES('I305','3','Ku tak ingin tekad goyah,<br/>hati ronta g''lisah,<br/>Kejar banyak hal yang besar,<br/>paham s''mua rahasia;<br/>Ku damba p''ri anak lugu,<br/>turuti maksud-Mu.<br/>',NULL,61619,3);
INSERT INTO stanza VALUES('I305','4','Di mana pun ku berada,<br/>situasi apa jua,<br/>Ku harus berpadu s''laras,<br/>hati tetap bara,<br/>Kar''na kasih curah t''naga,<br/>layani Sang Raja.<br/>',NULL,61620,4);
INSERT INTO stanza VALUES('I305','5','Ku mohon kurnia tiap hari,<br/>agar ku terdidik;<br/>Serasi lahir dan batin,<br/>munajat harmonis;<br/>Asal Tuhan dapat mulia,<br/>ku rela menyamping.<br/>',NULL,61621,5);
INSERT INTO stanza VALUES('I305','6','Walau jalan ada semu,<br/>Kau ingin ku sabar;<br/>Tiap p''ristiwa ada salib,<br/>Kau ingin ku sandar;<br/>Sandar Dikau, meski rendah,<br/>mana pun ku suka.<br/>',NULL,61622,6);
INSERT INTO stanza VALUES('I305','7','Bila dalam bahagiaku,<br/>ku lalai sandar-Mu;<br/>Moga hatiku t''radap-Mu,<br/>cinta makin penuh;<br/>Rela s''dikit kerja buat-Mu,<br/>jika perkenan-Mu.<br/>',NULL,61623,7);
INSERT INTO stanza VALUES('I305','8','Takdir kasih-Mu pili''anku,<br/>bukan belengguku;<br/>D''ngan sembunyi Kau pimpinku,<br/>kenal kesaksian-Mu;<br/>Korban diri s''panjang umur,<br/>seperti Tuhanku.<br/>',NULL,61624,8);
INSERT INTO stanza VALUES('I306','1','Bagi-Nya kini hidupku,<br/>wafat-Nya gantiku;<br/>Ku sembahkan semua kasih,<br/>hidup, buat Tuhan-ku.<br/>',NULL,61625,1);
INSERT INTO stanza VALUES('I306','chorus','O. Penebusku, Yesusku!<br/>Biar ku setia ikut-Mu;<br/>Kau t''lah mati dan hidup buatku,<br/>biar ku demikian untuk-Mu!<br/>',NULL,61626,2);
INSERT INTO stanza VALUES('I306','2','Dia mati, ku pun mati;<br/>ego, dunia putus,<br/>O, alangkah rahasia,<br/>ku boleh bersatu!<br/>',NULL,61627,3);
INSERT INTO stanza VALUES('I306','3','Tuhan hidup, ku pun hidup,<br/>tiada "ego", p''ri Dia,<br/>Moga sifat dan hayat-Nya,<br/>dariku ternyata.<br/>',NULL,61628,4);
INSERT INTO stanza VALUES('I306','4','Bagi aku Dia t''lah hidup,<br/>aku penyalur-Nya;<br/>P''ri Dia, hidup bagi yang lain,<br/>jejak-Nya ku tempuh.<br/>',NULL,61629,5);
INSERT INTO stanza VALUES('I307','1','Tuhan-ku, sempurnakanlah diriku;<br/>Tuhan-ku, hiduplah dalam jiwaku;<br/>Singkirkan s''mua berhala dan gagalku;<br/>cucilah aku, putih s''perti salju.<br/>',NULL,61630,1);
INSERT INTO stanza VALUES('I307','chorus','Putih bersih,<br/>seputih salju,<br/>cucilah aku,<br/>putih s''perti salju.<br/>',NULL,61631,2);
INSERT INTO stanza VALUES('I307','2','Tuhanku, buanglah semua najisku,<br/>dengan darah-Mu hapus s''mua nistaku;<br/>Semua ku buang biar ku jadi kudus;<br/>cucilah aku, putih s''perti salju.<br/>',NULL,61632,3);
INSERT INTO stanza VALUES('I307','3','Tuhanku, pandanglah dari takhta-Mu,<br/>sempurnakan s''mua kurbanku pada-Mu;<br/>Telah ku tinggalkan semua "ego"-ku,<br/>cucilah aku putih s''perti salju.<br/>',NULL,61633,4);
INSERT INTO stanza VALUES('I307','4','Tuhanku, dengarlah permohonanku,<br/>lama ku tunggu di bawah salib-Mu;<br/>Kuasa darah-Mu mutlak ku percaya,<br/>cucilah aku, putih s''perti salju.<br/>',NULL,61634,5);
INSERT INTO stanza VALUES('I307','5','Tuhanku, Kau tahu s''mua tuntutanku,<br/>datanglah seg''ra b''riku hati tulus;<br/>Aku meminta, Kau takkan menolak,<br/>cucilah aku, putih s''perti salju.<br/>',NULL,61635,6);
INSERT INTO stanza VALUES('I308','1','Permai dunia t''lah ku nampak,<br/>Tuhan tutup mataku;<br/>Biar penyertaan kasih-Mu,<br/>ku nikmati selalu.<br/>',NULL,61636,1);
INSERT INTO stanza VALUES('I308','chorus','Permai dunia t''lah ku nampak,<br/>Tuhan tutup mataku;<br/>Biar penyertaan kasih-Mu,<br/>ku nikmati selalu.<br/>',NULL,61637,2);
INSERT INTO stanza VALUES('I308','2','Fajar dan senja nan indah,<br/>k''lak ku jumpai di sana;<br/>Kini rahmat-Nya ku t''rima,<br/>hatiku pun puaslah.<br/>',NULL,61638,3);
INSERT INTO stanza VALUES('I308','3','Lepas d''rita tak ku rindu,<br/>asal kurnia bertambah;<br/>Dalam wahyu mulia Tuhan,<br/>tetap t''rangi yang buta.<br/>',NULL,61639,4);
INSERT INTO stanza VALUES('I308','4','Malam kelam sangat indah,<br/>dengan iman ku raba;<br/>Dia dibenci dan dihina,<br/>wajah-Nya bercahaya.<br/>',NULL,61640,5);
INSERT INTO stanza VALUES('I308','5','Kepala tertusuk duri,<br/>pancarkan cah''ya mulia;<br/>Lebih unggul dari s''gala;<br/>bintang, bulan, pun surya.<br/>',NULL,61641,6);
INSERT INTO stanza VALUES('I309','1','Wahyukanlah diri-Mu,<br/>biar ku kenal dagingku,<br/>Kurnia-Mu bekerja t''rus,<br/>biar ku tiarap di debu.<br/>Meski menang ku nanti,<br/>tapi kalah tiap hari;<br/>Berbuat baik ku ingin,<br/>tapi selalu nihil.<br/>',NULL,61642,1);
INSERT INTO stanza VALUES('I309','2','Maksudku pilih Allah,<br/>k''lakuanku membencikan;<br/>Ingin, tapi tak capai,<br/>apa dayaku kini!<br/>Baru hukum-Nya terbit,<br/>dosa pun seg''ra hadir;<br/>Anggotaku tertawan,<br/>tak mampu lepas diri.<br/>',NULL,61643,2);
INSERT INTO stanza VALUES('I309','3','Jatuh bangun berulang,<br/>tekad silih berganti,<br/>Mau menang bahkan gagal,<br/>mau kudus bahkan cemar.<br/>Ku terjual pada dosa,<br/>berupaya tak daya,<br/>Diriku sungguh gelap,<br/>tiada bajik s''dikit jua.<br/>',NULL,61644,3);
INSERT INTO stanza VALUES('I309','4','Agak kenal ku kini,<br/>diri yang getas ini,<br/>Sungguh keji tabiatku,<br/>semua najis hidupku.<br/>Alangkah ku bersedih,<br/>mengecewakan s''kali,<br/>Kini s''mua harapanku,<br/>hanya Yesus, Rajaku.<br/>',NULL,61645,4);
INSERT INTO stanza VALUES('I309','5','Demi salib ku mati,<br/>dengan Kristus ku bangkit,<br/>Dipenuhi Roh suci,<br/>kehendak-Nya yang jadi.<br/>Moga Tuhan d''ngan salib,<br/>menggarapku tiap hari,<br/>Biar diriku terkikis,<br/>hayat Tuhan yang pimpin.<br/>',NULL,61646,5);
INSERT INTO stanza VALUES('I309','6','Sungguh c''laka diriku,<br/>siapa sanggung bebaskan,<br/>Lepas dari kuasa maut,<br/>hinggaku s''lalu menang?<br/>Yesus berdarah buatku,<br/>Kristus jadi kudusku,<br/>Hanya Dia-lah hayatku,<br/>p''rintah-Nya-lah ku turut.<br/>',NULL,61647,6);
INSERT INTO stanza VALUES('I309','7','Kudus tanpa bercela!<br/>Patuh tanpa membantah!<br/>Depan Bapa tak takut!<br/>Depan Tuhan tak malu!<br/>O, hayat agung ini,<br/>d''ngan iman ku dapatkan!<br/>Tuhan saja ku puji,<br/>kini ku riang bebas.<br/>',NULL,61648,7);
INSERT INTO stanza VALUES('I310','1','Tak tersaing di hidupnya,<br/>silam sudah Esau, Ishak;<br/>Kini hadang mati hidup,<br/>meski buntu, masih ronta;<br/>Angkat tangan ku tak mau,<br/>pakai t''naga, berupaya.<br/>',NULL,61649,1);
INSERT INTO stanza VALUES('I310','2','Nampak orang menyelinap,<br/>hati takut, lagak tabah;<br/>Khawatir akhir t''lah tiba,<br/>berusaha sekuatnya;<br/>Dia gumul, ku melawan,<br/>belum mati, tak mengalah.<br/>',NULL,61650,2);
INSERT INTO stanza VALUES('I310','3','Terus gumul s''panjang malam,<br/>namun Dia tak tertaklukkan;<br/>Tenagaku mulai sirna,<br/>Dia malah tak mau menyerang;<br/>Tiada daya, lepas diri,<br/>tapi nyali justru pulih.<br/>',NULL,61651,3);
INSERT INTO stanza VALUES('I310','4','Lawan yang tak pernah jumpa,<br/>menyebut nama diri-Nya;<br/>Entah siapakah Dia,<br/>namun ta''u Dia pemb''ri berkat;<br/>Dia ku desak beri berkat,<br/>Dia ku desak agar ''nyerah.<br/>',NULL,61652,4);
INSERT INTO stanza VALUES('I310','5','Jelang fajar tetap imbang,<br/>tiada cara, tiada daya;<br/>Dia ku paksa beri berkat,<br/>sambil katakan ku menang;<br/>Israel ku digelar-Nya,<br/>namun pincang setelahnya.<br/>',NULL,61653,5);
INSERT INTO stanza VALUES('I310','6','Sinar masuk hati yang g''lap,<br/>sorot terang, ku pun paham;<br/>Kuat, tapi menggeliat?<br/>Menang, tapi jadi pincang?<br/>Ini tanda Dia jaya,<br/>bodohku justru terbongkar.<br/>',NULL,61654,6);
INSERT INTO stanza VALUES('I310','7','Hati digenangi terang,<br/>p''ri terjangan arus deras;<br/>Tampak alangkah mulia,<br/>desak ku menyembah Dia;<br/>Sadar dosa nan keparat,<br/>perbuatanku aib nista.<br/>',NULL,61655,7);
INSERT INTO stanza VALUES('I310','8','Bila ingat menang dari<br/>Sang Pencipta, Sang Kuasa!<br/>Melihat durhaka ini,<br/>layak tulah, layak mati!<br/>Kedua tanganku memb''rontak,<br/>paksa Tuhan tak bergerak!<br/>',NULL,61656,8);
INSERT INTO stanza VALUES('I310','9','Kau Allah yang mahamulia,<br/>Panglima alam semesta;<br/>Saat kenal Kau siapa,<br/>pun kenal Kau bagaimana;<br/>Ku menangis, ku meratap,<br/>sujud, sembah, sesal, tobat.<br/>',NULL,61657,9);
INSERT INTO stanza VALUES('I310','10','Mana boleh, mana pantas?<br/>Bergumul melawan Allah!<br/>Harap ada celah tanah,<br/>kubur rasa malu beta;<br/>Mengapa tak sebelumnya,<br/>sudah tewas dan binasa!<br/>',NULL,61658,10);
INSERT INTO stanza VALUES('I310','11','Benci diri tak terkira,<br/>angkuh membuatku buta;<br/>Ingat menang atas Allah,<br/>hati risi tak kepalang;<br/>Dulu paha yang sebelah,<br/>kini loyo sekujurnya.<br/>',NULL,61659,11);
INSERT INTO stanza VALUES('I310','12','Menengok sepanjang jalan,<br/>penuh dengan aib, bejat;<br/>Jaga diri, korban Allah,<br/>hanya tahu senang awak;<br/>Masih ''ngira berkat ialah<br/>memaksa-Nya dengar beta.<br/>',NULL,61660,12);
INSERT INTO stanza VALUES('I310','13','Hasratku surga patuhi,<br/>usulku surga turuti;<br/>Gemarku Allah ikuti,<br/>kerjaku Allah dampingi;<br/>Mauku surga tanggapi,<br/>Allah kalah sama s''kali.<br/>',NULL,61661,13);
INSERT INTO stanza VALUES('I310','14','Orang yang demikian bejat,<br/>sombong dan penuh muslihat!<br/>Ku Yakub, Kau kenal benar,<br/>sungguh bobrok membencikan!<br/>Tiada lain yang ku harap,<br/>kecuali belas pun rahmat!<br/>',NULL,61662,14);
INSERT INTO stanza VALUES('I310','15','Terjamah ku, rahmat Allah,<br/>pincang pertanda kurnia;<br/>Bila ini terlalaikan,<br/>hilang andalan niscaya.<br/>Israel ku Kau jadikan,<br/>namun Yakub pincang s''lama.<br/>',NULL,61663,15);
INSERT INTO stanza VALUES('I310','16','Dikau menang, bukan aku,<br/>kalah-Mu itu kalahku;<br/>Kar''na menang ku menyerah,<br/>lemah-Mu rebahkan aku;<br/>Aku rela gentar takut,<br/>hidup muliakan nama-Mu.<br/>',NULL,61664,16);
INSERT INTO stanza VALUES('I311','1','Tuhan, tilik dan b''riku,<br/>sederhana nan manis,<br/>Miskin roh, rendah hati,<br/>pandang-Mu tiada lain.<br/>',NULL,61665,1);
INSERT INTO stanza VALUES('I311','2','Lepas diri nan manja,<br/>lepas andalan harta,<br/>Lepas gairah tenar,<br/>pun lepas nafsu bangga.<br/>',NULL,61666,2);
INSERT INTO stanza VALUES('I311','3','Semua keangkuhanku,<br/>mohon tumpas seluruh;<br/>Mau-Mu ku patuhi,<br/>setia hingga mati.<br/>',NULL,61667,3);
INSERT INTO stanza VALUES('I311','4','Jadi p''ri anak kecil,<br/>hikmat diri tersingkir;<br/>Jalan dalam terang-Mu,<br/>gerak sandar t''naga-Mu.<br/>',NULL,61668,4);
INSERT INTO stanza VALUES('I311','5','Sandar ribaan kasih,<br/>tengadah ala sapih;<br/>Rasa damai ilahi,<br/>atasku memenuhi.<br/>',NULL,61669,5);
INSERT INTO stanza VALUES('I311','6','Biar ku hidup demikian,<br/>tiap hari panjat puji,<br/>Tak ubah sampai mati,<br/>datang-Mu aku nanti.<br/>',NULL,61670,6);
INSERT INTO stanza VALUES('I312','1','Tuhan, Kau-lah perhentianku,<br/>ku nikmat sepenuh;<br/>Henti semua ronta gumul,<br/>mengecap diri-Mu.<br/>',NULL,61671,1);
INSERT INTO stanza VALUES('I312','2','O, betapa diri licik,<br/>meronta ''tiasa,<br/>Terpisahlah Kau dan rohku,<br/>hilang perhentian.<br/>',NULL,61672,2);
INSERT INTO stanza VALUES('I312','3','Sungguh berliku diriku,<br/>sok benar semua,<br/>Seolah tent''ram serta-Mu,<br/>namun tak terandal.<br/>',NULL,61673,3);
INSERT INTO stanza VALUES('I312','4','Sabat ilahi ku tuntut,<br/>mutlak lepas diri;<br/>Dikau saja yang berkuasa,<br/>atas lahir batin.<br/>',NULL,61674,4);
INSERT INTO stanza VALUES('I312','5','Berserah dalam tangan-Mu,<br/>Tuhan garapiku;<br/>Moga kurnia-Mu membuat<br/>ku hidup sandar-Mu.<br/>',NULL,61675,5);
INSERT INTO stanza VALUES('I312','6','Tuhan, garap pun remukkan<br/>seluruh egoku;<br/>Hingga aku serupa-Mu,<br/>pancarkan terang-Mu.<br/>',NULL,61676,6);
INSERT INTO stanza VALUES('I313','1','Tuhan, hampakanlah aku<br/>yang penuh tipu;<br/>Ini karya maha kudus,<br/>Tuhan yang sanggup.<br/>',NULL,61677,1);
INSERT INTO stanza VALUES('I313','chorus','Tuhan, hampakanlah aku<br/>yang tak berbajik,<br/>S''panjang hidup terpedaya,<br/>congkak s''bab gelap;<br/>Tuhan, hampakanlah aku<br/>yang gelap sungguh.<br/>',NULL,61678,2);
INSERT INTO stanza VALUES('I313','2','Tuhan, dengarlah doaku,<br/>dosaku numpuk,<br/>Aku sendiri tidak puas,<br/>terlebih Tuhan!<br/>',NULL,61679,3);
INSERT INTO stanza VALUES('I313','3','Mengapa ku tiada tent''ram?<br/>Tuhan jelaskan;<br/>Batinku sering mendakwa,<br/>ku jadi bimbang.<br/>',NULL,61680,4);
INSERT INTO stanza VALUES('I313','4','Tuhan denganku tersekat,<br/>hubungan putus;<br/>Di manakah ku bersalah,<br/>imanku kabur?<br/>',NULL,61681,5);
INSERT INTO stanza VALUES('I314','1','Musuh laten nan bahaya,<br/>sungguh mengerikan;<br/>Lebih licik dari dosa,<br/>alamiah gemar.<br/>Yaitu ego nan tegar,<br/>aku nan terumbar;<br/>Bila ini disalibkan,<br/>Dia hidup dalamku.<br/>',NULL,61682,1);
INSERT INTO stanza VALUES('I314','2','Di dalam sifat usangku,<br/>ego kuat sungguh;<br/>Yakin, iba, bangga, angkuh,<br/>semua pada ego.<br/>Wajib tolak tiap aspeknya,<br/>wajib dimatikan;<br/>Baru bisa masuk Kanaan,<br/>nikmat Dia Sang Sabat.<br/>',NULL,61683,2);
INSERT INTO stanza VALUES('I314','3','Ego yang serobot takhta,<br/>singkirkan, ya Tuhan!<br/>Dalam-Mu "ego"-ku lenyap,<br/>selama-lamanya.<br/>Tuhan, lepaskanku dari<br/>yakin, puas diri;<br/>Dikau saja kekuatanku,<br/>tempat ku berhuni.<br/>',NULL,61684,3);
INSERT INTO stanza VALUES('I314','4','S''lamatkan aku, ya Tuhan,<br/>dari tuntut awak;<br/>Biar ''tiasa baring di mezbah,<br/>rela jadi kurban.<br/>Lepas sombong, bangga, tenar,<br/>kemuliaan sia-sia;<br/>Hanya Kristus ku banggakan,<br/>serta ku agungkan.<br/>',NULL,61685,4);
INSERT INTO stanza VALUES('I314','5','Hembus aku kuat-kuat,<br/>hingga ego sirna!<br/>Tiap aspek dari ego,<br/>hilang lenyap s''lama.<br/>Saat mulia naung kemah,<br/>Musa pun tak tahan;<br/>Mulia-Mu penuhiku,<br/>ego kekal tamat.<br/>',NULL,61686,5);
INSERT INTO stanza VALUES('I315','1','Najis bibir, nista angan,<br/>gagal, cemar, semuanya;<br/>Harapan pun lenyap punah,<br/>tetap adakah kurnia-Mu?<br/>',NULL,61687,1);
INSERT INTO stanza VALUES('I315','2','Kudus tersisip perbuatan,<br/>merendah tersisip ego;<br/>Bahkan tangis penyesalan<br/>pun perlu dibasuh darah.<br/>',NULL,61688,2);
INSERT INTO stanza VALUES('I315','3','Motivasi campur ego,<br/>korban diri sisip pamrih,<br/>Hatiku justru musuhku,<br/>Tuhan, harapku pada-Mu!<br/>',NULL,61689,3);
INSERT INTO stanza VALUES('I315','4','Melayani, mengasihi,<br/>sisip maksud, gairah ego;<br/>Takut gerak, takut diam,<br/>di mana pun selip ego.<br/>',NULL,61690,4);
INSERT INTO stanza VALUES('I315','5','Insan lama susah lepas,<br/>asal gerak, ego serta;<br/>Sungguh damba, mulia-Mu<br/>memenuhi anteroku.<br/>',NULL,61691,5);
INSERT INTO stanza VALUES('I315','6','Takut mohon, takut janji,<br/>hanya menatap pada-Mu;<br/>Bolehkah kirim firman-Mu<br/>yang mewahyukan mulia-Mu.<br/>',NULL,61692,6);
INSERT INTO stanza VALUES('I316','1','Kemampuanku kar''na rahmat;<br/>kasihan, ku salah sangka!<br/>Aku tidak pada tempat,<br/>masih rasa diri ingat!<br/>Sangka diri, sudah takwa,<br/>sudah hidup depan Allah!<br/>',NULL,61693,1);
INSERT INTO stanza VALUES('I316','2','Hidupku penuh ujian,<br/>melebihi kemampuan;<br/>Meski orang tidak paham,<br/>ku rasa diri cukup kuat;<br/>Ego seolah ku buang,<br/>tapi tetap ingat awak!<br/>',NULL,61694,2);
INSERT INTO stanza VALUES('I316','3','Ku ta''u diriku p''nuh kurnia,<br/>orang lain tak setara!<br/>Atas lahir, dalam batin,<br/>ku temukan garapan-Nya!<br/>Ku sadari semuanya,<br/>pula tahu menghargainya!<br/>',NULL,61695,3);
INSERT INTO stanza VALUES('I316','4','Ku tahu semua hasilku,<br/>pun semua kebaikanku,<br/>Tanpa sadar bangga diri,<br/>Allah bukan lagi inti;<br/>Di tangan, manna kemarin,<br/>sudah busuk, sudah basi.<br/>',NULL,61696,4);
INSERT INTO stanza VALUES('I316','5','Saat teman beri hibur,<br/>bersimpati, berprihatin,<br/>Kar''na angkuh, ku tersinggung,<br/>sabarku pun lenyap pupus,<br/>Aku gagal, tiada beda,<br/>ku mengutuk k''lahiranku.<br/>',NULL,61697,5);
INSERT INTO stanza VALUES('I316','6','Dulu dengar tentang Allah,<br/>c''ritakan Dia, aku dapat;<br/>Tapi diriku nan bejat,<br/>tak terubah karenanya;<br/>D''ngan kurnia-Mu pupuk angkuh,<br/>bangga diri makin numpuk.<br/>',NULL,61698,6);
INSERT INTO stanza VALUES('I316','7','Kini ku nampak diri-Mu,<br/>kudus-Mu singkap nistaku,<br/>Terang-Mu meruntuhkanku,<br/>mulia-Mu menyadarkanku,<br/>Sedih, menyesallah aku,<br/>sungguh sesatlah diriku.<br/>',NULL,61699,7);
INSERT INTO stanza VALUES('I316','8','Sungguh malu, sangat malu!<br/>D''ngan kurnia-Mu, hias diri,<br/>Tinggi hati, d''ngan karya-Mu,<br/>motovasi tidak tulus;<br/>Gagal aku, tak tertolong,<br/>s''mua menangku, memalukan.<br/>',NULL,61700,8);
INSERT INTO stanza VALUES('I316','9','Sungguh malu, ku t''lah sombong!<br/>Sungguh buta! Sungguh bodoh!<br/>Nista ku anggap nirmala,<br/>daging ku pandang hal indah;<br/>Membenarkan diri awak!<br/>Mencuri mulia Tuhan!<br/>',NULL,61701,9);
INSERT INTO stanza VALUES('I316','10','Dikau tahu aku bejat,<br/>tapi ku tak kenal diri,<br/>Sangka diri cukup andal,<br/>nyata sangat memalukan;<br/>Tuhan, tolonglah sekarang,<br/>orakkan semua ikatan.<br/>',NULL,61702,10);
INSERT INTO stanza VALUES('I316','11','Tuhan aku sangat ingin,<br/>cari tanah, baring diri;<br/>Atas diri, tabur abu,<br/>kejatuhan, sesal sungguh;<br/>Aku malu, amat malu,<br/>sungguh bejatlah hatiku.<br/>',NULL,61703,11);
INSERT INTO stanza VALUES('I316','12','Ungkapanku tidak tepat,<br/>hayatku pun dangkal amat,<br/>Motivasi cemar nista,<br/>segalaku menjengkelkan;<br/>Kini aku benci diri,<br/>hanya Tuhan harapanku.<br/>',NULL,61704,12);
INSERT INTO stanza VALUES('I317','1','Dari doa yang meminta<br/>lepas dari ombak ganas,<br/>Dari tekad nan penakut,<br/>tidak b''rani jalan maju,<br/>Dari sifat ego angkuh,<br/>Ya Tuhan, selamatkanku.<br/>',NULL,61705,1);
INSERT INTO stanza VALUES('I317','2','Dari kenyamanan awak,<br/>dari sikap tak menunjang,<br/>(Tak membuat roh perkasa,<br/>itu belum disalibkan),<br/>Lepas dari semua itu,<br/>tolongku, ya Domba Allah!<br/>',NULL,61706,2);
INSERT INTO stanza VALUES('I317','3','B''riku kasih, bawa maju,<br/>b''riku iman, tidak undur,<br/>B''ri harapan, tidak pupus,<br/>b''riku gairah, kobar terus,<br/>Hingga aku tinggi bubung,<br/>bukan pasir karam laut.<br/>',NULL,61707,3);
INSERT INTO stanza VALUES('I318','1','Demilah iman ku<br/>''natap Kau terpaku,<br/>Ya, Tuhan-ku!<br/>Dengarlah doaku,<br/>ampuni dosaku,<br/>Sejak kini ku hanya milik-Mu.<br/>',NULL,61708,1);
INSERT INTO stanza VALUES('I318','2','Tuhan b''rilah t''naga,<br/>pada hati lemah,<br/>biar bergairah!<br/>Bagiku Kau d''rita,<br/>pada-Mu ku cinta,<br/>Seperti api nyala kian bara.<br/>',NULL,61709,2);
INSERT INTO stanza VALUES('I318','3','Berjalan di dunia,<br/>tak luput sengsara,<br/>mohon papah!<br/>Seka air mata,<br/>jaga ku tak sesal,<br/>Jauh nista dosa, ikut Tuhan.<br/>',NULL,61710,3);
INSERT INTO stanza VALUES('I318','4','Hidup sangat singkat,<br/>maut seg''ra menerjang,<br/>ku tergenang;<br/>Mohon beri kurnia,<br/>buang hati gentar,<br/>Lewat dengan damai sejahtera.<br/>',NULL,61711,4);
INSERT INTO stanza VALUES('I319','1','Ku lemahlah, Tuhan-ku,<br/>tidak dapat berdiri teguh;<br/>Lemahku jadi berkat,<br/>bila ku bersandar pada-Mu.<br/>',NULL,61712,1);
INSERT INTO stanza VALUES('I319','chorus','Tiap hari, tiap waktu,<br/>ku perlu karunia-Mu,<br/>Harapku hanya satu,<br/>mohon Kau limpahkan diri-Mu.<br/>',NULL,61713,2);
INSERT INTO stanza VALUES('I319','2','Jalanku senyap sungguh,<br/>sering lelah, tidak bersyukur;<br/>Ku tak kenal jalanku,<br/>betapa ku perlu pimpin-Mu.<br/>',NULL,61714,3);
INSERT INTO stanza VALUES('I319','3','P''rasaanku s''ring ubah,<br/>menjemukan, tidak berharga;<br/>Bila buta mataku,<br/>Tuhan paling dekat padaku.<br/>',NULL,61715,4);
INSERT INTO stanza VALUES('I319','4','Ku sendirian, ya, Tuhan,<br/>s''lalu murung, tak dapat sabar,<br/>Jika tanpa asuh-Mu dan<br/>penyertaan-Mu yang mesra.<br/>',NULL,61716,5);
INSERT INTO stanza VALUES('I319','5','Waktu terbanglah laju,<br/>tidak lama ku ''kan menyeb''rang;<br/>K''liling sepi, ku berdoa,<br/>mohon Tuhan ingatlah lemahku.<br/>',NULL,61717,6);
INSERT INTO stanza VALUES('I320','1','Pohon yang tiada berkat,<br/>kering dan tiada teduh,<br/>Hambatan yang tanpa guna,<br/>itulah apa adaku;<br/>Mohon Tuhan, jangan buangku,<br/>moga tangan-Mu mengangkatku.<br/>',NULL,61718,1);
INSERT INTO stanza VALUES('I320','2','''Pri wanita ''nenun lenan,<br/>''pri seniman garap malam,<br/>Pandai besi olah baja,<br/>jadi perkakas, berguna;<br/>Moga tangan-Mu mengangkatku,<br/>jangan kasih-Mu membuangku.<br/>',NULL,61719,2);
INSERT INTO stanza VALUES('I320','3','Tekad kaku sulit remuk,<br/>mutu emas sulit nyata,<br/>Alamiah barang rongsok,<br/>p''ri pualam b''lum terpahat;<br/>Mari, tangan-Mu meremukkan,<br/>mohon jangan Kau membuangku.<br/>',NULL,61720,3);
INSERT INTO stanza VALUES('I320','4','S''perti mesiu meledakkan,<br/>s''perti palu meremukkan,<br/>S''perti kilang melumatkan,<br/>olah buah, b''ri suplaian;<br/>Mari, tangan-Mu meremukkan,<br/>jangan kasih-Mu membuangku.<br/>',NULL,61721,4);
INSERT INTO stanza VALUES('I320','5','Taklah cukup hanya remuk,<br/>perlu pula masuk tanur,<br/>Sudah remuk, belum mampu,<br/>menyuplai orang yang perlu;<br/>Olah aku demi karya-Mu,<br/>mohon jangan Kau membuangku.<br/>',NULL,61722,5);
INSERT INTO stanza VALUES('I320','6','P''ri emas diolah, tempa,<br/>jadi bentuk yang berguna,<br/>P''ri gandum ditumbuk, lumat,<br/>diolah jadi makanan;<br/>Olah aku dengan api-Mu,<br/>jangan kasih-Mu membuangku.<br/>',NULL,61723,6);
INSERT INTO stanza VALUES('I321','1','Kau kasih-Nya yang sembunyi!<br/>Panjang, lebar, dalam, tinggi;<br/>Dari jauh nampak Kau bers''ri,<br/>ingin ''ngaso aku kini;<br/>Jiwa letih, hati pedih,<br/>dalam-Mu hilang s''mua ini.<br/>',NULL,61724,1);
INSERT INTO stanza VALUES('I321','2','Suara-Mu s''lalu mengajak,<br/>"Marilah pikul kuk mesra!"<br/>Nyaris ku datang menjawab,<br/>tapi kuatir ada aral;<br/>Meki aku t''lah bertekad,<br/>pada-Mu tetaplah ingkar.<br/>',NULL,61725,2);
INSERT INTO stanza VALUES('I321','3','Hanya kurnia! Menarikku<br/>''ngaso dalam pelukan-Mu;<br/>Ku menuntut, tetap jauh,<br/>tiada tempat berteduh.<br/>Kapan tak begini s''lalu,<br/>tiap langkah ikut jejak-Mu?<br/>',NULL,61726,3);
INSERT INTO stanza VALUES('I321','4','Adakah barang yang lain,<br/>membuatku cabang hati?<br/>Bila ada k''ratlah kini,<br/>biar Kau m''raja tanpa saing;<br/>Hati tinggalkan duniawi,<br/>dalam-Mu ''ngasokan diri.<br/>',NULL,61727,4);
INSERT INTO stanza VALUES('I321','5','Tuhan, benam "aku" ini,<br/>lewatku Kau hidup kini;<br/>Nafsu jahat mati bersih,<br/>dosa musnah sama s''kali;<br/>Kecuali Tuhan tiada lain,<br/>yang ku harap dan ku ingin.<br/>',NULL,61728,5);
INSERT INTO stanza VALUES('I321','6','Bantuan luar biasa Kau beri,<br/>hilangkan kuatir di hati;<br/>Usir s''mua maksud pribadi,<br/>yang dalamku tersembunyi;<br/>Pada-Mu patuh d''ngan murni,<br/>puji Bapa tak berhenti.<br/>',NULL,61729,6);
INSERT INTO stanza VALUES('I321','7','Kerat aku dari dunia,<br/>tunggu p''rintah d''ngan merendah;<br/>Bisikkan padaku s''lalu,<br/>"Aku Tuhan dan hayatmu!"<br/>Suara, cinta, dan kuasa-Mu,<br/>padaku nyatalah sungguh.<br/>',NULL,61730,7);
INSERT INTO stanza VALUES('I322','1','Ikat aku, Tuhan,<br/>baru ku terorak,<br/>Paksalah aku menyerah,<br/>baru aku menang;<br/>Bila sandar awak,<br/>pasti akan kalah,<br/>Asal tangan-Mu mengekang,<br/>tanganku kian kuat.<br/>',NULL,61731,1);
INSERT INTO stanza VALUES('I322','2','Sebelum berserah,<br/>ku bodoh pun lemah,<br/>Hasratku tak terlaksana,<br/>tiada kepastian;<br/>Bila tak Kau b''lenggu,<br/>ku malah tak maju,<br/>Tuhan, taklukkan hatiku,<br/>baru ku kuat tangguh.<br/>',NULL,61732,2);
INSERT INTO stanza VALUES('I322','3','Hayatku tak mati,<br/>kehilangan pasti,<br/>Menang jarang, gagal numpuk,<br/>keluh kesah s''lalu;<br/>Bila belum mati,<br/>takkan hidup lagi,<br/>Lepas aku dari diri,<br/>biar Kau ku miliki.<br/>',NULL,61733,3);
INSERT INTO stanza VALUES('I322','4','Ku ta''u Tuhan kini,<br/>dan diri sendiri,<br/>Sejak kini ku tak lagi,<br/>bersandarkan lahir.<br/>Moga Sang Roh kekal,<br/>tumpas ego awak,<br/>Tingkah daging dimatikan,<br/>diri-Mu bertambah.<br/>',NULL,61734,4);
INSERT INTO stanza VALUES('I323','1','Tuhan, t''rangi jalanku,<br/>malam semakin larut,<br/>Mohon terang Tuhan-ku,<br/>soroti hatiku.<br/>',NULL,61735,1);
INSERT INTO stanza VALUES('I323','2','Terang, nyatakan s''gala,<br/>singkapkan semuanya;<br/>Terang, sungguh ku perlu,<br/>berikan terang-Mu.<br/>',NULL,61736,2);
INSERT INTO stanza VALUES('I323','3','Ku tak nampak apa pun,<br/>Satan sedang menipu,<br/>Tuhan, sorot terang-Mu,<br/>ke atas diriku.<br/>',NULL,61737,3);
INSERT INTO stanza VALUES('I323','4','Tuhan, t''rangi hayatku,<br/>biar ku kenal diriku,<br/>Singkir gelap ''tau redup,<br/>nampak s''mua lemahku.<br/>',NULL,61738,4);
INSERT INTO stanza VALUES('I323','5','Fokus hati pada-Mu,<br/>biar tak terbelenggu,<br/>Hingga kenal murad-Mu,<br/>terangi diriku!<br/>',NULL,61739,5);
INSERT INTO stanza VALUES('I323','6','Biar s''mua perilakuku,<br/>s''lalu dalam terang-Mu,<br/>T''rus sekutu serta-Mu,<br/>paham rombakan-Mu.<br/>',NULL,61740,6);
INSERT INTO stanza VALUES('I324','1','Buang selubungku,<br/>agar nampak terang,<br/>Tak lagi tertipu,<br/>mengenal d''ngan benar.<br/>',NULL,61741,1);
INSERT INTO stanza VALUES('I324','chorus','Tuhan, Sang Terang hayat,<br/>singkir semua gelap,<br/>Mari, sorot sekarang,<br/>nyatakan segala.<br/>',NULL,61742,2);
INSERT INTO stanza VALUES('I324','2','Terhadap diriku,<br/>ku kenal tak cukup,<br/>Tertipu takabur,<br/>puas diri m''lulu.<br/>',NULL,61743,3);
INSERT INTO stanza VALUES('I324','3','Terhadap diri-Mu,<br/>kenal lebih dangkal,<br/>Banyak doktrin ku ta''u,<br/>sangat kurang wahyu.<br/>',NULL,61744,4);
INSERT INTO stanza VALUES('I324','4','Terhadap hayat-Mu,<br/>ku kenal tak jauh,<br/>Daging dan Roh Kudus,<br/>sering campur aduk.<br/>',NULL,61745,5);
INSERT INTO stanza VALUES('I324','5','Terhadap jalan-Mu,<br/>ku sering tak jelas,<br/>Kar''na menyendiri,<br/>sulit kenal tepat.<br/>',NULL,61746,6);
INSERT INTO stanza VALUES('I324','6','Terhadap murad-Mu,<br/>pun kenal tak cukup,<br/>Mau diri sendiri,<br/>menendang di duri.<br/>',NULL,61747,7);
INSERT INTO stanza VALUES('I324','7','Terhadap g''reja-Mu,<br/>ku perlu wahyu-Mu,<br/>Tahu hayat Tubuh,<br/>mendapat hikmat-Mu.<br/>',NULL,61748,8);
INSERT INTO stanza VALUES('I324','8','Buang selubungku,<br/>sorotkan terang-Mu,<br/>Tak lagi tertipu,<br/>pun tak lagi angkuh.<br/>',NULL,61749,9);
INSERT INTO stanza VALUES('I325','1','Pikiran beta mengira,<br/>diri ini amat kuat;<br/>Tidak tahu sebaliknya,<br/>tuna daya.<br/>',NULL,61750,1);
INSERT INTO stanza VALUES('I325','2','Hidup di tengah khalayak,<br/>tak sadari kekurangan;<br/>Terasa maju pun giat,<br/>itu awak.<br/>',NULL,61751,2);
INSERT INTO stanza VALUES('I325','3','Tatkala di dalam gelap,<br/>tak sadari kedangkalan;<br/>Sangka diri serba bisa,<br/>tak merendah.<br/>',NULL,61752,3);
INSERT INTO stanza VALUES('I325','4','Hadirat-Mu ku menghadap,<br/>terang robek tirai kelam;<br/>Melihat nan belum tampak,<br/>s''mua tersingkap.<br/>',NULL,61753,4);
INSERT INTO stanza VALUES('I325','5','Menyusut aku depan-Mu,<br/>semua kandas dan pupus;<br/>Lemah lunglai semua angkuh,<br/>singkap s''luruh.<br/>',NULL,61754,5);
INSERT INTO stanza VALUES('I325','6','Tiada congkak, tiada bangga,<br/>tiada sandar, tiada andal;<br/>Malu saja, sesal s''mata,<br/>bisa doa?<br/>',NULL,61755,6);
INSERT INTO stanza VALUES('I325','7','Darah-Mu tangkis hukuman,<br/>hayat-Mu suplai pun tunjang;<br/>Namun diri nista nian,<br/>mengaibkan.<br/>',NULL,61756,7);
INSERT INTO stanza VALUES('I325','8','Congkak, angkuh, kar''na degil,<br/>enggan merendahkan diri;<br/>Andalkan awak tak lain,<br/>gelap hati.<br/>',NULL,61757,8);
INSERT INTO stanza VALUES('I325','9','Tenang salah, gerak salah,<br/>bungkam salah, tutur salah;<br/>Semua gagal, serba lemah,<br/>tiada daya.<br/>',NULL,61758,9);
INSERT INTO stanza VALUES('I325','10','Ingin doa, tak beriman, ingin sandar,<br/>bimbang ''golak;<br/>Bagaimana mulai baru ...<br/>Mohon rahmat!<br/>',NULL,61759,10);
INSERT INTO stanza VALUES('I326','1','Tuhan terangi aku, amin!<br/>Nyatakanlah dosaku, haleluya!<br/>Demi darah, cuci bersih,<br/>nista lenyap seluruh, amin!<br/>',NULL,61760,1);
INSERT INTO stanza VALUES('I326','2','Tuhan, orakkan aku, amin!<br/>Hancurkan belengguku, haleluya!<br/>Tumpas Iblis, tumpas Iblis,<br/>hingga ku bebas s''luruh, amin!<br/>',NULL,61761,2);
INSERT INTO stanza VALUES('I326','3','Tuhan, bangunkan aku, amin!<br/>Lenyapkan kelemahan, haleluya!<br/>Barakanlah api kasih,<br/>bagi-Mu-lah hidupku, amin!<br/>',NULL,61762,3);
INSERT INTO stanza VALUES('I327','1','Tuhan, bersihkan rohku;<br/>Tuhan bersihkan rohku;<br/>Tuhan, bersihkan rohku;<br/>nista hapus!<br/>Rohku bersih, nista singkir,<br/>bersih suci!<br/>',NULL,61763,1);
INSERT INTO stanza VALUES('I327','2','Wadahku hampakanlah,<br/>wadahku hampakanlah,<br/>Wadahku hampakanlah,<br/>dosa sirna!<br/>Wadah hampa, dosa sirna,<br/>bersih semua!<br/>',NULL,61764,2);
INSERT INTO stanza VALUES('I327','3','Tuhan, penuhi rohku;<br/>Tuhan, penuhi rohku;<br/>Tuhan, penuhi rohku;<br/>biarku bangun!<br/>Penuhilah! Bangunkanlah!<br/>Bangun s''luruh!<br/>',NULL,61765,3);
INSERT INTO stanza VALUES('I328','1','Tuhan, wajah-Mu ku rindu,<br/>buka mataku biar nampak;<br/>Sinar-Mu t''rangi diriku,<br/>lenyapkan semua yang gelap.<br/>Tuhan, ku pandang wajah-Mu,<br/>janganlah Kau sembunyikan;<br/>Buka mataku biar nampak,<br/>wajah mulia!<br/>',NULL,61766,1);
INSERT INTO stanza VALUES('I328','2','Tuhan, suara-Mu ku rindu,<br/>buka t''lingaku biar dengar;<br/>Suara-Mu yang amat merdu,<br/>singkir s''mua dusta si jahat.<br/>Tuhan, ku pandang wajah-Mu;<br/>janganlah Kau sembunyikan;<br/>Buka t''lingaku biar dengar,<br/>''kan firman-Mu!<br/>',NULL,61767,2);
INSERT INTO stanza VALUES('I328','3','Tuhan, diri-Mu ku rindu,<br/>bukalah pintu hatiku,<br/>Untuk t''rima k''limpahan-Mu,<br/>biar ku terbenam dalam-Mu.<br/>Tuhan, ku pandang wajah-Mu;<br/>janganlah Kau sembunyikan;<br/>Tuhan, penuhi hatiku,<br/>d''ngan kurnia-Mu!<br/>',NULL,61768,3);
INSERT INTO stanza VALUES('I329','1','Ada orang telah menyimpang,<br/>tinggalkan lindungan kawanan,<br/>Hati pun tamak akan dunia,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61769,1);
INSERT INTO stanza VALUES('I329','chorus','Tajam sungguh pertanyaan ini,<br/>menusuk amat dalam di hati!<br/>Orang yang abai berkat kurnia-Mu,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61770,2);
INSERT INTO stanza VALUES('I329','2','Ada orang punggungi Tuhan,<br/>ikuti tipu daya jahat,<br/>Roh Kudus dibuat berduka,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61771,3);
INSERT INTO stanza VALUES('I329','3','Ada orang lupa budi-Mu,<br/>malahan melayani mamon,<br/>Tenggelam dalam dosa nista,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61772,4);
INSERT INTO stanza VALUES('I329','4','Ada orang menyangkal Yesus,<br/>membuat-Nya t''rima malu, hina,<br/>B''rontak, sangkal, menjual Tuhan,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61773,5);
INSERT INTO stanza VALUES('I329','5','Ada orang seg''ra terangkat,<br/>nikmati perhentian nan mesra,<br/>Mendapatkan mahkota hayat,<br/>hambakah itu, ya Tuhan?<br/>',NULL,61774,6);
INSERT INTO stanza VALUES('I330','1','Kasih Tuhan dalam,<br/>sungguh tak terduga;<br/>Orang dosa sep''ri saya,<br/>bisa dapat s''lamat.<br/>',NULL,61775,1);
INSERT INTO stanza VALUES('I330','2','Dengan harga tinggi,<br/>ku tertebus balik;<br/>Kini rela pikul salib,<br/>setia sampai akhir.<br/>',NULL,61776,2);
INSERT INTO stanza VALUES('I330','3','Kini ku buang s''mua,<br/>agar dapat Kristus;<br/>Mati, hidup, tak ku hirau,<br/>ikut Tuhan m''lulu.<br/>',NULL,61777,3);
INSERT INTO stanza VALUES('I330','4','Teman, harta, nama,<br/>bagiku tak guna;<br/>Dia jadi miskin kar''naku,<br/>ku pun mau begitu.<br/>',NULL,61778,4);
INSERT INTO stanza VALUES('I330','5','Ku cinta P''nolongku,<br/>harapkan kenan-Nya;<br/>Senang ku bilangkan d''rita,<br/>kar''na Tuhan saja!<br/>',NULL,61779,5);
INSERT INTO stanza VALUES('I330','6','Kau-lah Penghiburku,<br/>dan Juru-s''lamatku;<br/>Di bumi atau di surga,<br/>Kau saja ku damba.<br/>',NULL,61780,6);
INSERT INTO stanza VALUES('I330','7','D''rita, lawan, c''laka,<br/>tidak ku peduli;<br/>Mohon roh, jiwa, tubuhku,<br/>Kau curahi kasih.<br/>',NULL,61781,7);
INSERT INTO stanza VALUES('I330','8','Tuhan, pimpin aku,<br/>tambahi t''nagaku;<br/>Lewat dunia gelap, dosa,<br/>ku perlu kurnia-Mu.<br/>',NULL,61782,8);
INSERT INTO stanza VALUES('I330','9','Iblis, dunia, nafsu,<br/>sering menggodaku;<br/>Bila Tuhan tak membantu,<br/>bisa bawa malu.<br/>',NULL,61783,9);
INSERT INTO stanza VALUES('I330','10','Waktu sisa s''dikit,<br/>jadikan ku suci;<br/>Tuhan datang, ku memuji:<br/>Haleluya! Amin!<br/>',NULL,61784,10);
INSERT INTO stanza VALUES('I331','1','Bagimu berdarah,<br/>korbankan jiwa-Ku,<br/>Kau Ku cuci bersih,<br/>tolong kau dari maut.<br/>Bagimu Ku korban jiwa,<br/>kau korbankan apa?<br/>Bagimu Ku korban jiwa,<br/>kau korbankan apa?<br/>',NULL,61785,1);
INSERT INTO stanza VALUES('I331','2','Banyak waktu Ku buang,<br/>datang d''rita c''laka,<br/>Biar kau s''lalu senang,<br/>dapatkan perhentian,<br/>Banyak waktu Ku korbankan,<br/>kau korbankan b''rapa?<br/>Banyak waktu Ku korbankan,<br/>kau korbankan b''rapa?<br/>',NULL,61786,2);
INSERT INTO stanza VALUES('I331','3','Rumah Bapa indah,<br/>takhta-Ku yang mulia,<br/>Bagimu Ku tinggal,<br/>datang d''rita susah.<br/>Bagimu Ku tinggalkan s''mua,<br/>kau tinggalkan apa?<br/>Bagimu Ku tinggalkan s''mua,<br/>kau tinggalkan apa?<br/>',NULL,61787,3);
INSERT INTO stanza VALUES('I331','4','Nista dan celaka,<br/>bagimu Ku d''rita,<br/>Sengsara tak terp''ri,<br/>tolong kau dari maut.<br/>Bagimu Ku d''rita semua,<br/>kau derita apa?<br/>Bagimu Ku d''rita semua,<br/>kau derita apa?<br/>',NULL,61788,4);
INSERT INTO stanza VALUES('I331','5','Dari rumah Bapa,<br/>bagimu Ku bawa;<br/>Kurnia yang berlimpah<br/>dan ampunan Bapa.<br/>Bagimu Ku bawa cinta,<br/>kau membawa apa?<br/>Bagimu Ku bawa cinta,<br/>kau membawa apa?<br/>',NULL,61789,5);
INSERT INTO stanza VALUES('I331','6','Kini ku sembahkan waktu,<br/>jiwa, s''gala,<br/>Lepas b''lenggu dunia,<br/>ikut Tuhan saja.<br/>Bagiku Kau korban s''gala,<br/>ku pun harus juga.<br/>Bagiku Kau korban s''gala,<br/>ku pun harus juga.<br/>',NULL,61790,6);
INSERT INTO stanza VALUES('I332','1','Kasih, yang tak lepaskanku,<br/>ku bawa jiwa letihku;<br/>Ku s''rahkan sisa hidupku,<br/>biar diam dalam samudra-Mu,<br/>Tergenang kian luap.<br/>',NULL,61791,1);
INSERT INTO stanza VALUES('I332','2','Cah''ya, yang t''rangi jalanku,<br/>ku bawa p''lita yang redup,<br/>T''rang-mu bangunkan hatiku,<br/>hidupnya demi terang-Mu,<br/>Kian indah cemerlang.<br/>',NULL,61792,2);
INSERT INTO stanza VALUES('I332','3','Girang, yang menemukanku,<br/>hatiku buka pada-Mu,<br/>Dalam hujan, p''langi muncul,<br/>ku ta''u tak ingkar janji-Mu,<br/>Seka air mataku.<br/>',NULL,61793,3);
INSERT INTO stanza VALUES('I332','4','Salib, yang mendongakkanku,<br/>ku tak b''rani tinggalkan-Mu,<br/>Kini kubur mulia dunia,<br/>pasti tumbuh bunga hayat,<br/>Mekar selamanya.<br/>',NULL,61794,4);
INSERT INTO stanza VALUES('I333','1','Pernahkah rohmu berjumpa Dia,<br/>serta hatimu direbut-Nya?<br/>Bila kau kenal Dia yang utama,<br/>kau pasti pilih berkat prima.<br/>',NULL,61795,1);
INSERT INTO stanza VALUES('I333','chorus','Antara insan, Kau yang utama!<br/>Buka mataku, rebut hatiku,<br/>Hancurkan b''rhala, Tuhan ternobat,<br/>antara insan, Kau yang utama.<br/>',NULL,61796,2);
INSERT INTO stanza VALUES('I333','2','Semua mewah mulia dunia,<br/>justru berhala memabukkan;<br/>Bersepuh emas, menarik nian,<br/>bersalut madu, memikat jua.<br/>',NULL,61797,3);
INSERT INTO stanza VALUES('I333','3','Apa yang membuat b''rhala dunia,<br/>kehilangan daya tariknya?<br/>Bukan kecewa, bukan anjuran,<br/>melainkan kemustikaan-Nya.<br/>',NULL,61798,4);
INSERT INTO stanza VALUES('I333','4','Bukanlah dorongan manusia,<br/>mampu kesampingkan berhala;<br/>Tetapi keindahan mulia-Nya,<br/>serta kelembutan hati-Nya.<br/>',NULL,61799,5);
INSERT INTO stanza VALUES('I333','5','Siapa yang padamkan p''litanya,<br/>sebelum sang fajar merekah?<br/>Siapa yang menanggalkan jubahnya,<br/>sebelum musim panas tiba?<br/>',NULL,61800,6);
INSERT INTO stanza VALUES('I333','6','Hanya air mata yang Petrus li''at,<br/>dan wajah yang Stefanus tatap,<br/>Hati yang ''nangis beserta Maria,<br/>yang lepaskanku dari dunia.<br/>',NULL,61801,7);
INSERT INTO stanza VALUES('I333','7','Moga kasih-Mu menarikku,<br/>pula memenuhi hatiku;<br/>Kami tertebus, jadi jodoh-Mu,<br/>berhala mana tandingan-Mu?.<br/>',NULL,61802,8);
INSERT INTO stanza VALUES('I334','1','Tersisihlah mutlak,<br/>bagi Roh Kudus!<br/>Tuntut k''limpahan-Nya,<br/>tak takut korban;<br/>Putus s''mua rintangan,<br/>masuk ke dalam;<br/>Dapatkan kuasa-Ny,<br/>pula berkat-Nya<br/>',NULL,61803,1);
INSERT INTO stanza VALUES('I334','chorus','Tersisihlah mutlak<br/>bagi Sang Tuhan,<br/>Jawab panggil Tuhan,<br/>cari limpah-Nya.<br/>',NULL,61804,2);
INSERT INTO stanza VALUES('I334','2','Tersisihlah mutlak,<br/>bagi Roh Kudus!<br/>Genang ulang genang,<br/>ego tersapu!<br/>Hampakan bejana,<br/>hancur depan-Nya;<br/>Hingga Dia penuhi,<br/>salur kurnia-Nya.<br/>',NULL,61805,3);
INSERT INTO stanza VALUES('I334','3','Tersisihlah mutlak,<br/>bagi murad-Nya!<br/>Tempuh jalan Tuhan,<br/>sandar kurnia-Nya;<br/>Abai nikmat, nyaman,<br/>ikuti Tuhan;<br/>Tunggu pimpinan-Nya,<br/>dengar suara-Nya.<br/>',NULL,61806,4);
INSERT INTO stanza VALUES('I334','4','Tersisihlah mutlak<br/>sampai s''lamanya;<br/>Tak lagi mauku,<br/>tapi murad-Nya;<br/>Damba, rencanaku,<br/>lenyap dalam Dia;<br/>Tak berbagian dunia,<br/>punya segala.<br/>',NULL,61807,5);
INSERT INTO stanza VALUES('I334','5','Tersisihlah mutlak,<br/>alangkah indah,<br/>Ditawan kasih-Nya,<br/>bebas pun takjub;<br/>Lepas cengk''ram dosa,<br/>bimbang, dan takut,<br/>Lepas s''gala beban,<br/>kuatir, dan duka.<br/>',NULL,61808,6);
INSERT INTO stanza VALUES('I334','6','Tersisihlah mutlak,<br/>''ngasolah amat,<br/>Menunggu depan-Nya,<br/>turut hasrat-Nya;<br/>Sampai dipenuhi<br/>oleh Roh Kudus;<br/>Setiap p''losokku,<br/>murni seluruh.<br/>',NULL,61809,7);
INSERT INTO stanza VALUES('I334','7','Roh-Nya penuhiku,<br/>dengan hadir-Nya!<br/>Dalam-Nya ku nikmat<br/>kasih pun berkat!<br/>Terang-Nya dalamku,<br/>kekal tak pudar;<br/>Hidup kepada-Nya,<br/>hingga s''lamanya.<br/>',NULL,61810,8);
INSERT INTO stanza VALUES('I335','1','Ku t''lah belakangi dunia<br/>dan segala senangnya;<br/>Arah hatiku ke surga,<br/>mustika lebih indah;<br/>Semua mewah mulia dunia,<br/>hilang daya tariknya;<br/>Ku t''lah lintas batas dunia,<br/>buang jauh dunia.<br/>',NULL,61811,1);
INSERT INTO stanza VALUES('I335','chorus','Buang dunia,<br/>jauh di b''lakang,<br/>Ku t''lah lintas batas dunia,<br/>buang jauh dunia.<br/>',NULL,61812,2);
INSERT INTO stanza VALUES('I335','2','Ku t''lah lepas hidup dosa<br/>serta tingkah bodohnya;<br/>Kini t''rima pimpinan-Nya,<br/>senang dengar p''rintah-Nya;<br/>Sandar Tuhan, maut lepas,<br/>Tuhan jadi Kepala;<br/>Rela berkorban bagi-Nya,<br/>buang jauh dunia.<br/>',NULL,61813,3);
INSERT INTO stanza VALUES('I335','3','Kini ku tak balik lagi,<br/>dunia lama nan bodoh;<br/>Tiada lagi hukuman,<br/>malah ada perhentian,<br/>Aku sudah ganti Tuan,<br/>kekal layani Dia;<br/>B''lenggu dunia lucut lepas,<br/>buang jauh dunia.<br/>',NULL,61814,4);
INSERT INTO stanza VALUES('I335','4','Hari depan, telah tetap,<br/>demi Tuhan semata;<br/>Injil lain tak ku harap,<br/>kecuali rahmat-Nya;<br/>Tekad hati layani Dia,<br/>tak balik, tak menyesal;<br/>Masa lampau membencikan,<br/>buang jauh dunia.<br/>',NULL,61815,5);
INSERT INTO stanza VALUES('I336','1','Kudus, riang, tersisihkan!<br/>Demikian baru berkat;<br/>Lepas hal selain Tuhan,<br/>hanya Dia yang ku rindu;<br/>Rahat di dalam Kristus,<br/>rahat di dalam Kristus.<br/>',NULL,61816,1);
INSERT INTO stanza VALUES('I336','2','Kristus panggil, ku tersisih,<br/>Dia pimpin tempuh jalan;<br/>Hidup-Nya telah nyatakan,<br/>hidup-Nya telah buktikan;<br/>Siapa taat pimpin-Nya?<br/>Siapa taat pimpin-Nya?<br/>',NULL,61817,2);
INSERT INTO stanza VALUES('I336','3','Tuhan, buat aku senang,<br/>pergi ke luar kemah,<br/>Ku bagi-Mu, taat ikhlas,<br/>t''rima hina bersama-Mu;<br/>Mutlak s''luruh bagi-Mu!<br/>Mutlak s''luruh bagi-Mu!<br/>',NULL,61818,3);
INSERT INTO stanza VALUES('I336','4','Sisih! Agar Kau tak duka.<br/>Sisih! Dari yang dosa;<br/>Namun, Dikau perhatikan<br/>dan mencari orang dosa,<br/>Ikut jejak kasih-Mu!<br/>Ikut jejak kasih-Mu!<br/>',NULL,61819,4);
INSERT INTO stanza VALUES('I336','5','Bagi Penolong tercinta!<br/>Dengan-Mu tanpa sekat;<br/>Konsekrasi, serah mutlak,<br/>konsekrasi, sisih mutlak,<br/>Kekal hanya bagi-Mu!<br/>Kekal hanya bagi-Mu!<br/>',NULL,61820,5);
INSERT INTO stanza VALUES('I337','1','S''mua milikku bagi Kristus,<br/>ku sembahkan d''ngan tulus;<br/>Tiap saat hidup depan-Mu,<br/>cinta-Mu s''panjang umur.<br/>',NULL,61821,1);
INSERT INTO stanza VALUES('I337','chorus','Semua bagi-Mu!<br/>Semua bagi-Mu!<br/>Tuhan inilah minatku,<br/>semua bagi-Mu!<br/>',NULL,61822,2);
INSERT INTO stanza VALUES('I337','2','S''mua milikku bagi Kristus,<br/>depan-Mu ku bersujud;<br/>Dunia bukanlah milikku,<br/>Tuhan, t''rimalah aku.<br/>',NULL,61823,3);
INSERT INTO stanza VALUES('I337','3','S''mua milikku bagi Kristus,<br/>Tuhan-lah pemilikku;<br/>Roh Kudus jadi saksiku,<br/>Tuhan juga milikku.<br/>',NULL,61824,4);
INSERT INTO stanza VALUES('I337','4','S''mua milikku bagi Kristus,<br/>biar ku jadi wadah-Mu;<br/>Penuh kuasa, kurnia-Mu,<br/>menyatakan diri-Mu.<br/>',NULL,61825,5);
INSERT INTO stanza VALUES('I337','5','S''mua milikku bagi Kristus,<br/>Roh-Mu bakar ku murni;<br/>Alangkah manis kurnia-Mu!<br/>Mulia, mulia, ku puji!<br/>',NULL,61826,6);
INSERT INTO stanza VALUES('I338','1','Semuanya bagi Kristus,<br/>sudahlah sepatutnya;<br/>Darah Tuhan menebusku,<br/>hak milikku pada-Nya.<br/>',NULL,61827,1);
INSERT INTO stanza VALUES('I338','chorus','Semuanya bagi Kristus,<br/>bagi Kristus Tuhan-ku!<br/>Semuanya bagi Kristus,<br/>bagi Kristus Tuhan-ku!<br/>',NULL,61828,2);
INSERT INTO stanza VALUES('I338','2','Semuanya bagi Kristus,<br/>''nilah damba hatiku;<br/>Kasih-Nya dorong tak putus,<br/>semua bagi Tuhan-ku.<br/>',NULL,61829,3);
INSERT INTO stanza VALUES('I338','3','Semuanya bagi Kristus,<br/>dikuduskan seluruh;<br/>Tubuh, jiwa, harta, waktu,<br/>hakiki dan s''galaku.<br/>',NULL,61830,4);
INSERT INTO stanza VALUES('I338','4','Tanganku Tuhan gunakan,<br/>kaki ikut jejak-Nya;<br/>Mata menatap wajah-Nya,<br/>bibir panjat pujian.<br/>',NULL,61831,5);
INSERT INTO stanza VALUES('I338','5','Pandang lekat kepada-Nya,<br/>hal lain jadi pudar;<br/>Terkenang d''rita salib-Nya,<br/>ku rela pikul kuk-Nya.<br/>',NULL,61832,6);
INSERT INTO stanza VALUES('I338','6','Kurnia ajaib, tak terkata!<br/>Mulut, hati bergita;<br/>Tuhan mulia, Maharaja,<br/>justru ku disayang-Nya!<br/>',NULL,61833,7);
INSERT INTO stanza VALUES('I339','1','Tuhan, Kau dapatkanku,<br/>biar aku jadi kudus;<br/>Waktuku dan umurku,<br/>bagi-Mu-lah selalu.<br/>',NULL,61834,1);
INSERT INTO stanza VALUES('I339','chorus','Kau bertajuk duri bagiku,<br/>tersalib mend''rita kar''naku;<br/>Kini ku serahkan jiwa dan cinta,<br/>layani Kau semata.<br/>',NULL,61835,2);
INSERT INTO stanza VALUES('I339','2','Dapat tangan, kakiku,<br/>kerja, tempuh jalan-Mu;<br/>Dapat mulut, lidahku,<br/>siarkan firman, budi-Mu.<br/>',NULL,61836,3);
INSERT INTO stanza VALUES('I339','3','Dapat emas, perakku,<br/>tak tersisa bagiku;<br/>Dapat bakat, hikmatku,<br/>pakailah semau-Mu.<br/>',NULL,61837,4);
INSERT INTO stanza VALUES('I339','4','Dapat tekad, hatiku,<br/>bagi-Mu s''mua minatku;<br/>Dapat cinta, kasihku,<br/>bagi-Mu-lah selalu.<br/>',NULL,61838,5);
INSERT INTO stanza VALUES('I339','5','Kau dapatkan s''galaku,<br/>dengan Kau ku bersatu;<br/>Cinta pun layani-Mu,<br/>tenggelam di dalam-Mu.<br/>',NULL,61839,6);
INSERT INTO stanza VALUES('I340','1','Serah seluruh, Tuhan,<br/>ku mau serah seluruh,<br/>di depan-Mu.<br/>Taruh atas mezbah,<br/>serahkan seluruh,<br/>Kau t''lah menebusku,<br/>ku milik-Mu.<br/>',NULL,61840,1);
INSERT INTO stanza VALUES('I340','2','Serah seluruh - hidup,<br/>s''gala, lengkap sempurna<br/>pemb''rian-Mu.<br/>Mohon Kau bersabda,<br/>tak ''nyimpang ku ikut;<br/>Kini hingga kekal,<br/>mutlak patuh.<br/>',NULL,61841,2);
INSERT INTO stanza VALUES('I340','3','Serah seluruh - harta benda;<br/>kaya pun limpah<br/>pemb''rian-Mu.<br/>Semua bagi-Mu,<br/>Dikau Penebusku;<br/>Patut s''mua bagi-Mu,<br/>ya Tuhan-ku.<br/>',NULL,61842,3);
INSERT INTO stanza VALUES('I340','4','Serah seluruh,<br/>pada Kristus,<br/>Dia itulah Juru-s''lamat.<br/>Hidup lewat aku,<br/>Kau kelimpahan-Nya;<br/>Dikau, bukan aku,<br/>menang mutlak.<br/>',NULL,61843,4);
INSERT INTO stanza VALUES('I341','1','Jangan tipuku d''ngan dunia,<br/>dan keuntungan sia-sia;<br/>Jangan godaku d''ngan mewah,<br/>dan impian yang hampa.<br/>Ku t''lah buang s''mua berhala,<br/>kini ku milik Tuhan;<br/>Pada Kristus ku tersembah,<br/>mutlak jadi milik-Nya.<br/>',NULL,61844,1);
INSERT INTO stanza VALUES('I341','chorus','Sekarang aku,<br/>bukan milikku,<br/>Aku milik Kristus,<br/>tak lagi milikku.<br/>',NULL,61845,2);
INSERT INTO stanza VALUES('I341','2','O, akulah milik Kristus,<br/>betapa sejahtera!<br/>Asal diri tak tersisa,<br/>limpah-Nya menjaminlah.<br/>Tuhan Mulia t''rima aku,<br/>jadi milik-Nya s''mata;<br/>Aku layak nikmat Tuhan,<br/>girang aku milik-Nya.<br/>',NULL,61846,3);
INSERT INTO stanza VALUES('I341','3','Hai, yang penat dan yang lelah!<br/>Jangan lagi meronta;<br/>Pada Kristus serahkan s''mua,<br/>tak sisa sedikit jua.<br/>Demi ku Dia berkorban,<br/>biar ku jadi milik-Nya;<br/>Dia t''lah berikan semuanya,<br/>aku pun harus juga.<br/>',NULL,61847,4);
INSERT INTO stanza VALUES('I342','1','Hidup ''tuk Yesus d''ngan hati tulus,<br/>s''mua perkara cari perkenan-Nya.<br/>Tunduk p''rintah-Nya d''ngan sukarela;<br/>inilah jalan berkat dan bah''gia.<br/>',NULL,61848,1);
INSERT INTO stanza VALUES('I342','chorus','Yesus Juru-s''lamatku,<br/>ku s''rahkan diriku,<br/>Kar''na lewat tebusan,<br/>Kau b''rikan diri-Mu.<br/>Ku tiada lain Tuan,<br/>hatiku takhta-Mu,<br/>Seumur hidupku, Kristus,<br/>bagi-Mu selalu.<br/>',NULL,61849,2);
INSERT INTO stanza VALUES('I342','2','Hidup ''tuk Yesus yang mati buatku,<br/>dosa nistaku Dia-lah yang pikul;<br/>Kasih dorongku, jawab panggil-Mu,<br/>s''rahkan s''galaku pada Tuhan-ku.<br/>',NULL,61850,3);
INSERT INTO stanza VALUES('I342','3','Hidup ''tuk Yesus, di mana jua,<br/>lakukan tugas, dalam nama-Nya;<br/>Rela derita, rugi, sengsara;<br/>semua ujian, salib belaka.<br/>',NULL,61851,4);
INSERT INTO stanza VALUES('I342','4','Hidup ''tuk Yesus, waktu sg''ra lalu,<br/>senyum-Nya rahasia mustikaku;<br/>Cari yang sesat, yang t''lah Dia tebus,<br/>bimbing yang lesu, nikmat sabat-Mu.<br/>',NULL,61852,5);
INSERT INTO stanza VALUES('I343','1','Bukan ronta, tapi bers''rah,<br/>yang kuatkanku;<br/>Ronta bagiku tak guna,<br/>bers''rah sentosa.<br/>',NULL,61853,1);
INSERT INTO stanza VALUES('I343','2','Bila aku tak bergumul<br/>d''ngan t''naga diri;<br/>Berserah tanpalah syarat,<br/>perhentian pasti.<br/>',NULL,61854,2);
INSERT INTO stanza VALUES('I343','3','Segalaku sandar Yesus,<br/>Dia Juru-s''lamat;<br/>Ku menghambda demi kasih,<br/>tak ingin bebas.<br/>',NULL,61855,3);
INSERT INTO stanza VALUES('I343','4','Taat, baru ku perkasa;<br/>mati, ku hidup;<br/>Murad-Mu, bukan maksudku,<br/>menanglah tentu.<br/>',NULL,61856,4);
INSERT INTO stanza VALUES('I344','1','Rancang-Mu Tuhan, terlaksana!<br/>Ku tanah liat, Kau Penjunan,<br/>Garap dan olah leluasa,<br/>Ku taat b''laka, serah mutlak.<br/>',NULL,61857,1);
INSERT INTO stanza VALUES('I344','2','Rancang-Mu Tuhan, terlaksana!<br/>Depan-Mu aku bertiarap,<br/>P''riksa dan uji, biar ku nyata,<br/>Kikis dan basuh, bebas noda.<br/>',NULL,61858,2);
INSERT INTO stanza VALUES('I344','3','Rancang-Mu Tuhan, terlaksana!<br/>Ego tertanggal, ku dambakan;<br/>Gempur dan kupas, hingga hampa,<br/>Gali dan tuang, tanpa sisa.<br/>',NULL,61859,3);
INSERT INTO stanza VALUES('I344','4','Rancang-Mu Tuhan, terlaksana!<br/>Ku mau taat dengan mutlak,<br/>Penuh Roh Kudus, salur hayat,<br/>Lewatku Kristus, hidup nyata.<br/>',NULL,61860,4);
INSERT INTO stanza VALUES('I345','1','Bagaimana aku cinta<br/>dan bersembah biar Dia senang?<br/>Bagaimana aku b''lajar<br/>dengan mesra ikut Tuhan?<br/>',NULL,61861,1);
INSERT INTO stanza VALUES('I345','2','Bila jalan penuh d''rita,<br/>Tuhan jaga biar ku setia,<br/>Tetap patuh pada Tuhan,<br/>dan ingat salib-Mu yang b''rat.<br/>',NULL,61862,2);
INSERT INTO stanza VALUES('I345','3','Biar ku ingat Tuhan pernah<br/>buangkan semua mewah surga,<br/>Duka, lelah, lapar, dah''ga,<br/>tiada rumah, tiada rahat.<br/>',NULL,61863,3);
INSERT INTO stanza VALUES('I345','4','Susah drita hingga mati,<br/>tolak kesenangan diri,<br/>Meski mewah dunia nikmat,<br/>pada Tuhan lebih cinta.<br/>',NULL,61864,4);
INSERT INTO stanza VALUES('I345','5','Aku bilang semua rugi,<br/>hati-Mu saja ku cari;<br/>Buangkan dunia sep''ri sampah,<br/>kar''na cinta ku tak sayang.<br/>',NULL,61865,5);
INSERT INTO stanza VALUES('I346','1','Ku mengikut Yesus,<br/>apa pun jalannya;<br/>Lebar atau sempit,<br/>lurus ''tau belokan;<br/>Penyelamat mendampingi,<br/>apa ku bimbang?<br/>Ikut terus sampai<br/>masuk k''rajaan.<br/>',NULL,61866,1);
INSERT INTO stanza VALUES('I346','chorus','Ikut, ikut,<br/>ikut Tuhan Yesus!<br/>Manis atau getir,<br/>ku ikut Yesus!<br/>Ikut, ikut,<br/>ikut Tuhan Yesus!<br/>Ke mana pun dipimpin-Nya,<br/>ku ikut.<br/>',NULL,61867,2);
INSERT INTO stanza VALUES('I346','2','Ku mengikut Yesus,<br/>di mana pun jua;<br/>Dalam senang, lapang,<br/>atau susah, lembah;<br/>Penyelamat melindungi,<br/>apa sengsara?<br/>Ikut terus sampai<br/>kesudahannya.<br/>',NULL,61868,3);
INSERT INTO stanza VALUES('I346','3','Ku mengikut Yesus,<br/>kapan pun saatnya;<br/>Waktu surya cerah,<br/>atau mendung kelam;<br/>Penyelamat mengaturnya,<br/>apa gelisah?<br/>Ikut terus sampai<br/>fajar merekah.<br/>',NULL,61869,4);
INSERT INTO stanza VALUES('I347','1','Ikut Kau ku kini,<br/>salib tak elak;<br/>Nama, mulia dunia,<br/>ku buang tuntas,<br/>Cerca dan olokan,<br/>tak ku hiraukan;<br/>Susah dan tekanan<br/>tak menggoyahkan;<br/>Sandar kurnia firman,<br/>maju d''ngan setia;<br/>Kelak bermahkota<br/>mulia tak hingga,<br/>Mulia tak hingga,<br/>mulia tak hingga.<br/>',NULL,61870,1);
INSERT INTO stanza VALUES('I348','1','Kini ku tinggalkan semua,<br/>ikut Dia pikul salib;<br/>Rela t''rima d''rita susah,<br/>ikut Dia jalan sempit.<br/>Dulu apa yang ku gemar,<br/>kini semua ku buang;<br/>Betapalah bahagiaku,<br/>Kristus, Allah milikku.<br/>',NULL,61871,1);
INSERT INTO stanza VALUES('I348','2','Biarlah ku ditolak dunia,<br/>kar''na Dia pun ditolak;<br/>Banyak orang menipuku,<br/>hanya Tuhan yang sungguh.<br/>Bila Kau senyum padaku,<br/>meski manusia rusuh;<br/>Tetap damailah hatiku,<br/>kar''na nampak wajah-Mu.<br/>',NULL,61872,2);
INSERT INTO stanza VALUES('I348','3','Enyah! Tenar, untung, dunia!<br/>Mari! Olok dan d''rita!<br/>Rugi, d''rita buat Tuhan,<br/>justru untung dan nyaman.<br/>Dia ku panggil "Aba Bapa",<br/>genap hati pada-Nya;<br/>Ombak dahsyat, awan gelap,<br/>bagiku faedah s''mata.<br/>',NULL,61873,3);
INSERT INTO stanza VALUES('I348','4','Meski banyak yang menindas,<br/>itu malah membawa;<br/>Aku lebih dekat Tuhan,<br/>nikmati damai surga.<br/>''mua d''rita tak kupeduli,<br/>bila wajah-Mu bers''ri;<br/>Riang menjadilah duka,<br/>bila Tuhan tak serta.<br/>',NULL,61874,4);
INSERT INTO stanza VALUES('I348','5','Ke tempat mulia ku maju,<br/>teguhkanlah imanku;<br/>Harinya segera tiba,<br/>ku pasti Tuhan bawa.<br/>Perkara dunia ''kan tamat,<br/>tempuhan pun sg''ra usai;<br/>Harapanku jadi nyata,<br/>doaku penuh pujian.<br/>',NULL,61875,5);
INSERT INTO stanza VALUES('I349','1','Berduyun masuk k''rajaan,<br/>salib tak pikul?<br/>Pahala banyak yang damba,<br/>dunia tak tolak?<br/>Jalan Tuhan tak ditempuh,<br/>namun berkat mau!<br/>Jalan Tuhan tak ditempuh,<br/>namun berkat mau!<br/>',NULL,61876,1);
INSERT INTO stanza VALUES('I349','2','Mau kemuliaan Tuhan,<br/>malu tak mau?<br/>Mau berkuasa d''ngan Tuhan,<br/>rugi tak mau?<br/>Siapa pandang s''muanya<br/>sampah karena Tuhan?<br/>Siapa pandang s''muanya<br/>sampah karena Tuhan?<br/>',NULL,61877,2);
INSERT INTO stanza VALUES('I349','3','Mesra Tuhan, semua ''pingin,<br/>puasa tak ingin!<br/>Takhta Tuhan, semua suka,<br/>korban tak rela!<br/>Hanya nyanyi, namun bukan<br/>berjaga-jaga!<br/>Hanya nyanyi, namun bukan<br/>berjaga-jaga!<br/>',NULL,61878,3);
INSERT INTO stanza VALUES('I349','4','Hormat Tuhan, semua rindu,<br/>hina-Nya takut.<br/>Kalau Tuhan s''lalu memb''ri,<br/>seg''ra memuji;<br/>Kalau Tuhan minta s''dikit,<br/>sg''ra sakit hati,<br/>Kalau Tuhan minta s''dikit,<br/>sg''ra sakit hati.<br/>',NULL,61879,4);
INSERT INTO stanza VALUES('I349','5','Namun bagi pencinta-Nya,<br/>s''mua tak dihirau;<br/>Biar nyawa dan darah m''reka<br/>tumpah bagi-Nya!<br/>Tuhan, b''riku tekad ini,<br/>s''tia sampai mati!<br/>Tuhan, b''riku tekad ini,<br/>s''tia sampai mati!<br/>',NULL,61880,5);
INSERT INTO stanza VALUES('I350','1','Siapa di pihak-Nya?<br/>Mengikut Tuhan,<br/>Hidup bagi Tuhan,<br/>tempuh jalan-Nya?<br/>Tinggalkan dunia,<br/>perang bagi-Nya?<br/>Siapa di pihak-Nya,<br/>maju serta-Nya?<br/>',NULL,61881,1);
INSERT INTO stanza VALUES('I350','chorus','Demi penebusan<br/>dan kurnia-Mu,<br/>Juru-s''lamat mulia,<br/>ku dipihak-Mu.<br/>',NULL,61882,2);
INSERT INTO stanza VALUES('I350','2','Jadi tent''ra Tuhan,<br/>rela berperang,<br/>Bukan demi mulia<br/>atau mahkota;<br/>Tetapi dorongan<br/>cinta kasih-Nya,<br/>Atas rahmat Tuhan,<br/>ku di pihak-Nya.<br/>',NULL,61883,3);
INSERT INTO stanza VALUES('I350','3','Kau t''lah menebusku,<br/>jadi umat-Mu;<br/>D''ngan darah adi-Mu,<br/>bukan ''mas, perak;<br/>Bagi pengikut-Mu,<br/>berkat tak batas;<br/>Maju t''rus ke depan,<br/>rela pun bebas.<br/>',NULL,61884,4);
INSERT INTO stanza VALUES('I350','4','Perang bakal sengit,<br/>musuh pun kuat;<br/>Namun pasukan-Nya<br/>mustahil kalah;<br/>Di bawah panji-Nya,<br/>pasti ''kan menang;<br/>tKar''na Dia setia,<br/>jaya niscaya.<br/>',NULL,61885,5);
INSERT INTO stanza VALUES('I350','5','Laskar pilihan-Nya,<br/>kini berperang,<br/>Ku harus setia,<br/>ikut Panglima;<br/>Layani Sang Raja,<br/>gairah tak hambar,<br/>Pegang teguh status,<br/>tulus pun setia.<br/>',NULL,61886,6);
INSERT INTO stanza VALUES('I351','1','T''radap salib, ku setiakah?<br/>Ikut Domba Allah?<br/>Atau ku takut berkorban,<br/>dapat maaf dunia?<br/>',NULL,61887,1);
INSERT INTO stanza VALUES('I351','chorus','Nama-Mu, indah sungguh,<br/>Kau mati untukku,<br/>Entah suasana apa pun,<br/>ku cari ''kenan-Mu.<br/>',NULL,61888,2);
INSERT INTO stanza VALUES('I351','2','Yang lain berp''rang rebut mulia,<br/>darah, p''luh cucuran;<br/>Masa ku manja sendirian,<br/>mimpi masuk surga?<br/>',NULL,61889,3);
INSERT INTO stanza VALUES('I351','3','Bolehkah musuh disambut<br/>- dibiarkan mengganggu?<br/>Bolehkah bahu-membahu,<br/>d''ngan dunia terkutuk?<br/>',NULL,61890,4);
INSERT INTO stanza VALUES('I351','4','Mau kuasa harus bertempur,<br/>ya, Tuhan kuatkanku,<br/>Agar ku rela terhina,<br/>tegap sandar firman.<br/>',NULL,61891,5);
INSERT INTO stanza VALUES('I352','1','Meski kami sering goyah,<br/>tapi Tuhan teguh s''lama;<br/>Janji-Nya tiada yang sia-sia,<br/>sampai pun dunia musnah.<br/>',NULL,61892,1);
INSERT INTO stanza VALUES('I352','2','Meski kami cabang hati,<br/>tapi Dia tak buang kami;<br/>Kami jauhi, Dia dekati,<br/>adakah teman begini?<br/>',NULL,61893,2);
INSERT INTO stanza VALUES('I352','3','Dia tak kecewakan kami,<br/>s''mua pertaru''an Dia lindungi;<br/>S''kali Dia t''lah cinta kami,<br/>Dia cinta hingga abadi.<br/>',NULL,61894,3);
INSERT INTO stanza VALUES('I352','4','Tapi sikap kami ini,<br/>sering menyakiti hati;<br/>Selain Dia, sembah berhala,<br/>sedikit pun tak mendusin!<br/>',NULL,61895,4);
INSERT INTO stanza VALUES('I352','5','Set''lah berhala tersingkir,<br/>dengan sedih kami balik;<br/>Pada Teman yang simpati,<br/>dulu tak kami peduli.<br/>',NULL,61896,5);
INSERT INTO stanza VALUES('I352','6','Kami datang dipeluk-Nya,<br/>di ribaan-Nya yang hangat;<br/>Semua nista dihapus-Nya,<br/>kasih-Nya teguh s''lamanya.<br/>',NULL,61897,6);
INSERT INTO stanza VALUES('I352','7','Tuhan, t''radap kasih ini,<br/>patut kami sorak puji;<br/>Kasih-Mu tak tertandingi,<br/>tak henti kami memuji.<br/>',NULL,61898,7);
INSERT INTO stanza VALUES('I353','1','Dulu ku pernah gairah,<br/>menuntut kemajuan,<br/>Sayang kini t''lah ubah,<br/>menjauhi Tuhan;<br/>Dulu tak kenal lelah,<br/>siang maupun malam,<br/>Sayang kini t''lah dingin,<br/>membeku di hati.<br/>',NULL,61899,1);
INSERT INTO stanza VALUES('I353','chorus','Dapatkah ku lupa,<br/>P''nolongku dan Bapa?<br/>Kar''na ku Dia duka,<br/>masa ku diam saja?<br/>',NULL,61900,2);
INSERT INTO stanza VALUES('I353','2','Dulu ku t''lah sembahkan,<br/>genap jiwa raga,<br/>Tapi kini dip''ralat<br/>oleh mewah dunia!<br/>Dulu sangat ibadah,<br/>tapi kini t''rumbar,<br/>Berk''lana dalam dunia,<br/>kapan baru bosan?<br/>',NULL,61901,3);
INSERT INTO stanza VALUES('I353','3','Dulu genap hatiku,<br/>cinta Tuhan m''lulu,<br/>Tiada lain rinduku,<br/>jaga atau tidur;<br/>Dunia dan s''mua perkara,<br/>ku buang p''ri sampah,<br/>Kini malah ku kejar,<br/>sep''ri orang dunia.<br/>',NULL,61902,4);
INSERT INTO stanza VALUES('I353','4','Dulu mengabdi Tuhan,<br/>hidup p''ri di surga,<br/>Ku berjanji pada-Mu,<br/>"Hanya d''ngar p''rintah-Mu.<br/>Rela patuh selalu,<br/>selain Kau, ku tak mau."<br/>Tapi kini s''mua lalu,<br/>pudarlah janjiku!<br/>',NULL,61903,5);
INSERT INTO stanza VALUES('I353','5','Jerih payah s''mua sia-sia,<br/>p''ri awan sg''ra sirna,<br/>Lama tinggalkan rumah,<br/>belum juga pulang;<br/>Nafsu dunia sg''ra lalu,<br/>jangan mau dipincut,<br/>Lama Tuhan menunggu,<br/>janganlah meragu.<br/>',NULL,61904,6);
INSERT INTO stanza VALUES('I353','6','Bintang fajar sg''ra terbit,<br/>waktu seg''ra habis,<br/>Dari kejatu''an bangkit,<br/>''kenan-Nya ku cari;<br/>Tolak dunia dan Iblis,<br/>menuntut rohani,<br/>Kasih s''mula t''lah pulih,<br/>ku mengabdi lagi.<br/>',NULL,61905,7);
INSERT INTO stanza VALUES('I354','1','Bolehkah ku hambar undur,<br/>membuat duka Roh Kudus,<br/>Biarkan Dia menunggu?<br/>Kini aku rela balik,<br/>tak mau lagi berkelana;<br/>Jalan ikut Tuhan.<br/>',NULL,61906,1);
INSERT INTO stanza VALUES('I354','2','Ku persembahkan diriku,<br/>tak tersisa sedikit pun,<br/>Kini hingga kekal<br/>Mohon Tuhan yang menjaga,<br/>agar lainnya tak ku harap,<br/>Hanya kehendak-Nya.<br/>',NULL,61907,2);
INSERT INTO stanza VALUES('I354','3','Ingat dulu, rasa malu,<br/>tiada jiwa yang ku tolong,<br/>Kurnia-Nya ku bendung;<br/>Mohon Tuhan mencurahkan,<br/>Roh Kudus atas diriku,<br/>Ku jadi saksi-Nya.<br/>',NULL,61908,3);
INSERT INTO stanza VALUES('I354','4','Kurnia-Nya sangat berlimpah,<br/>t''radapku Dia sangat cinta,<br/>Ku jadi jodoh-Nya.<br/>Ku bersandar pada Tuhan,<br/>rela t''rima s''gala d''rita,<br/>Alirkan hayat-Nya.<br/>',NULL,61909,4);
INSERT INTO stanza VALUES('I355','1','Bila orang tolak dunia,<br/>hidup bagi Allah,<br/>Yang dia dapat amat berkat,<br/>tidak terkatakan.<br/>Karena semua miliknya,<br/>hidup, mati, s''gala;<br/>Kristus-lah hayat, nafasnya,<br/>dan tempat tinggalnya.<br/>',NULL,61910,1);
INSERT INTO stanza VALUES('I355','2','Orang p''riku, Raja pilih,<br/>berbagian takhta-Nya,<br/>Tapi aku menolaknya,<br/>sungguh mengherankan;<br/>Jangan sampai bilang korban!<br/>Bayar berapa jua,<br/>Asal jadi pasukan-Nya,<br/>haknya tak terkata!<br/>',NULL,61911,2);
INSERT INTO stanza VALUES('I355','3','Mari! Hitung bisnis ini:<br/>keping jadi utuh -<br/>S''gala benda, hal, manusia,<br/>menjadi milikmu.<br/>Kau milik Dia, s''mua milikmu,<br/>bahkan Dia kau esa;<br/>Dapat nikmat hayat limpah,<br/>tiada tandingannya.<br/>',NULL,61912,3);
INSERT INTO stanza VALUES('I356','1','Esa dengan Putra Kekal,<br/>satu roh demi iman,<br/>Berbagian wafat almuhit,<br/>pun dapatkan hayat-Nya.<br/>Esa dengan Sang Terkasih,<br/>ku jadi bagian-Nya.<br/>Bersama Putra sewaris,<br/>wujud rumah Roh Kudus.<br/>',NULL,61913,1);
INSERT INTO stanza VALUES('I356','2','Esa d''ngan Sang Inkarnasi,<br/>jadi anggota Tubuh,<br/>Ranting melekat tak lepas,<br/>''nempuh hidup di dunia.<br/>Esa dengan Sang Mesias,<br/>t''rima kuasa Roh Kudus,<br/>Tiap hari tiap saat,<br/>koordinasi tak lepas.<br/>',NULL,61914,2);
INSERT INTO stanza VALUES('I356','3','Esa dengan Sang Tersingkir,<br/>lewat ganjar dan kutuk,<br/>D''nganmu mati t''radap dosa,<br/>alam maut tak daya.<br/>Esa denganlah Sang Bangkit,<br/>lucut cengk''raman kubur,<br/>Bersama Kau hidup kini,<br/>wujudkan kebenaran.<br/>',NULL,61915,3);
INSERT INTO stanza VALUES('I356','4','Esa dengan Sang Terangkat,<br/>naik takhta serta-Nya,<br/>Kuasa-Mu ku berbagian,<br/>memerintah bersama.<br/>Dikau seg''ra datang pula,<br/>kita ''kan semulia,<br/>ampil corak-Mu nan mulia,<br/>esa hingga s''lamanya.<br/>',NULL,61916,4);
INSERT INTO stanza VALUES('I357','1','Esa d''ngan Kristus nan jaya,<br/>pun karya salib-Nya;<br/>Apa d''rita, tetap teguh,<br/>kar''na Dia membantu.<br/>',NULL,61917,1);
INSERT INTO stanza VALUES('I357','2','Esa d''ngan Kristus nan bangkit,<br/>semayam di surga;<br/>Mulia salib, seg''ra nyata,<br/>kurnia ajaib, limpah.<br/>',NULL,61918,2);
INSERT INTO stanza VALUES('I357','3','Esa d''ngan Kristus nan menang,<br/>rohku bubung terbang;<br/>Sandar nama-Nya kusiarkan,<br/>kabur kuasa gelap.<br/>',NULL,61919,3);
INSERT INTO stanza VALUES('I357','4','Kristus bangkit, sungguh hebat!<br/>Ingin ku bersatu;<br/>Salib Kristus, menang s''lalu,<br/>Satan hancur lebur.<br/>',NULL,61920,4);
INSERT INTO stanza VALUES('I357','5','Esa d''ngan Kristus nan agung,<br/>kes''lamatan Allah;<br/>Mari puji, selamanya,<br/>Domba memang layak!<br/>',NULL,61921,5);
INSERT INTO stanza VALUES('I358','1','Dalam Kristus, ajaiblah,<br/>posisi tinggi nian!<br/>Kes''lamatan nan mulia,<br/>disamakan dengan-Nya.<br/>Kelak tampil bersama,<br/>serupa pun secitra;<br/>Kini iringi Dia,<br/>ku dapat serupa Dia.<br/>',NULL,61922,1);
INSERT INTO stanza VALUES('I358','chorus','Serupa Dia, secitra Dia,<br/>sungguh ajaib, serupa Dia;<br/>Kurnia ajaib, nimpa atasku,<br/>ku serupa Dia pun esa.<br/>',NULL,61923,2);
INSERT INTO stanza VALUES('I358','2','Esa, mati bersama;<br/>esa, bangkit bersama;<br/>Lepas dari kutukan,<br/>kini hidup bersama.<br/>Esa, t''rangkat bersama;<br/>keputraan bersama;<br/>P''ri suami dan istrinya,<br/>p''ri pohon dan carangnya.<br/>',NULL,61924,3);
INSERT INTO stanza VALUES('I358','3','Esa, garap bersama;<br/>esa, doa bersama;<br/>Khasiat mustika-Nya,<br/>nikmatku kar''na iman.<br/>Esa, iman pun kasih;<br/>sama hayat dengan Dia;<br/>Roh Kudus hadir ''tiasa,<br/>kuduskanku s''perti Dia.<br/>',NULL,61925,4);
INSERT INTO stanza VALUES('I359','1','Esa dengan Tuhan Yesus, esa padu dalam roh,<br/>Di dalamku Dikau hidup, ku nikmati diri-Mu.<br/>',NULL,61926,1);
INSERT INTO stanza VALUES('I359','chorus','Esalah, esalah,<br/>ku dan Kau, esalah,<br/>Kelimpahan-Mu suplaiku,<br/>diri-Mu segalaku.<br/>',NULL,61927,2);
INSERT INTO stanza VALUES('I359','2','Kini berbagian hayat-Mu,<br/>penuh d''ngan insani-Mu,<br/>Kehidupan insani-Mu,<br/>diterapkan atasku.<br/>',NULL,61928,3);
INSERT INTO stanza VALUES('I359','3','Esa dengan-Mu di salib,<br/>ku mati di dalam-Mu,<br/>Ku mati terhadap dunia,<br/>dunia mati t''radapku.<br/>',NULL,61929,4);
INSERT INTO stanza VALUES('I359','4','Esa d''ngan-Mu dalam bangkit,<br/>ku hidup bersama-Mu,<br/>Diri-Mu-lah hayat bangkit,<br/>di batin menyuplaiku.<br/>',NULL,61930,5);
INSERT INTO stanza VALUES('I359','5','Esa d''ngan-Mu dalam t''rangkat,<br/>sama duduk di surga,<br/>Hidupku ada dalam-Mu,<br/>ku musafir di dunia.<br/>',NULL,61931,6);
INSERT INTO stanza VALUES('I359','6','Esa d''ngan-Mu atas takhta,<br/>berbagian kuasa-Mu,<br/>Sama hayat, sama sifat,<br/>esa dalam satu roh.<br/>',NULL,61932,7);
INSERT INTO stanza VALUES('I360','1','O, Golgota! Di sanalah,<br/>Tuhan rela wafat;<br/>Dia dipaku, curah darah,<br/>biar-ku bebas dosa.<br/>',NULL,61933,1);
INSERT INTO stanza VALUES('I360','chorus','Mohon Tuhan mewahyukan,<br/>raha-sia Golgota,<br/>Agar ku ta''u,<br/>kini ku t''lah esa dengan Tuhan.<br/>',NULL,61934,2);
INSERT INTO stanza VALUES('I360','2','O, Golgota! Di sanalah,<br/>mati ku serta-Nya;<br/>Dengan tersalib bersama,<br/>lucut beban berat.<br/>',NULL,61935,3);
INSERT INTO stanza VALUES('I360','3','O, Golgota! kubur tuhan,<br/>menguburku pula;<br/>Bangkit-Nya, ku ber-ba-gi-an,<br/>aku pun hiduplah.<br/>',NULL,61936,4);
INSERT INTO stanza VALUES('I360','4','O, Golgota! Tent''ra Satan,<br/>t''lah dipermalukan;<br/>Sandar tuhan, kua-sa gelap,<br/>depanku jerembab.<br/>',NULL,61937,5);
INSERT INTO stanza VALUES('I360','5','O, Golgota! Demi Tuhan,<br/>aku menang perang;<br/>Satan lari tunggang langgang,<br/>dengar nama Tuhan.<br/>',NULL,61938,6);
INSERT INTO stanza VALUES('I360','6','O, Golgota! Puji Tuhan,<br/>di sana Dia wafat;<br/>Korban jiwa, tebus dosa,<br/>b''lengguku oraklah.<br/>',NULL,61939,7);
INSERT INTO stanza VALUES('I360','7','O, Golgota! Ku mau b''lajar,<br/>maknamu se-mu-a!<br/>Demi iman, aku menang,<br/>tegak beserta-Nya.<br/>',NULL,61940,8);
INSERT INTO stanza VALUES('I361','1','Tuhan wahyukanlah kini,<br/>Yesus mati ku pun mati,<br/>Hanya dengan jalan ini,<br/>dapat menang itu pasti.<br/>',NULL,61941,1);
INSERT INTO stanza VALUES('I361','2','Salib-Mu itu salibku,<br/>yang menerangi hidupku;<br/>Ku terpaku bersama-Mu,<br/>kuasa dunia sudah luruh.<br/>',NULL,61942,2);
INSERT INTO stanza VALUES('I361','3','Ku terpaku bersama-Mu,<br/>lepas dosa, diri, nafsu;<br/>Dapatkah ku kejar lagi,<br/>kenikmatan dunia ini?<br/>',NULL,61943,3);
INSERT INTO stanza VALUES('I361','4','Pada-Mu kami berhampir,<br/>bersama di tempat mati;<br/>Hayat, kuasa-Mu, milikku,<br/>kar''na aku dan Kau satu.<br/>',NULL,61944,4);
INSERT INTO stanza VALUES('I361','5','Kau datang hancurkan Satan<br/>- tindakan, kuasa, mautnya;<br/>Aku menang bersama-Mu,<br/>alami kuasa-Mu s''lalu.<br/>',NULL,61945,5);
INSERT INTO stanza VALUES('I361','6','Hanya sandar pada salib,<br/>baru aku bisa menang;<br/>''Nempuh jalan yang Kau tempuh,<br/>sampai berjumpa dengan-Mu.<br/>',NULL,61946,6);
INSERT INTO stanza VALUES('I361','7','Ku terpaku bersama-Mu,<br/>curahkan Roh-Mu yang kekal;<br/>Biar ku jelas ''kan mati-Mu,<br/>lepas diri, daging, dosa.<br/>',NULL,61947,7);
INSERT INTO stanza VALUES('I361','8','Ku mau menang ''pri Tuhan-ku!<br/>Meraja, berkuasa d''ngan-Mu;<br/>Bila ku mau pikul salib,<br/>dapat mulia itu pasti.<br/>',NULL,61948,8);
INSERT INTO stanza VALUES('I362','1','Ku tersalib dengan Kristus,<br/>lepas dosa dan dunia,<br/>Hingga ku bisa terima<br/>hayat kebangkitan-Nya.<br/>Rela d''rita bersama-Nya,<br/>teladani taat-Nya,<br/>Ikut Tuhan Yesus Kristus,<br/>tempuh jalan salib-Nya.<br/>',NULL,61949,1);
INSERT INTO stanza VALUES('I362','chorus','Tempuh jalan salib-Nya,<br/>wafat Tuhan di sana!<br/>Biar aku serta-Nya,<br/>tempuh jalan salib-Nya.<br/>',NULL,61950,2);
INSERT INTO stanza VALUES('I362','2','Sulitkah mati serta-Nya?<br/>Kebangkitan ku kenal.<br/>Sulitkah d''rita serta-Nya?<br/>Murad-Nya ku mau taat.<br/>Kini Tuhan diam dalamku,<br/>demi kuasa bangkit-Nya,<br/>Hingga ku dengan gembira<br/>tempuh jalan salib-Nya.<br/>',NULL,61951,3);
INSERT INTO stanza VALUES('I362','3','Mati - hidup bersama-Nya;<br/>d''rita - lantik serta-Nya;<br/>Pemenang sedemikian,<br/>baru dapat pahala.<br/>Rianglah! Fajar merekah!<br/>Dengar Tuhan berkata,<br/>"Kaulah hamba yang setia,<br/>tempuh jalan salib-Nya."<br/>',NULL,61952,4);
INSERT INTO stanza VALUES('I363','1','Kristus t''lah mati,<br/>aku pun mati,<br/>bangkit serta Dia,<br/>hayat ku dapat;<br/>T''rangkat serta Dia,<br/>lampaui dunia,<br/>setiap saat,<br/>aku milik-Nya.<br/>',NULL,61953,1);
INSERT INTO stanza VALUES('I363','chorus','Setiap saat, kasih-Nya jaga,<br/>setiap saat, ku p''roleh hayat.<br/>Setiap saat, ku menantikan,<br/>setiap saat, aku milik-Nya.<br/>',NULL,61954,2);
INSERT INTO stanza VALUES('I363','2','Tiada ujian,<br/>tiada pikulan,<br/>tanpa hadir-Nya<br/>serta papah-Nya;<br/>Tiada derita,<br/>tiada sengsara,<br/>tanpa suplai-Nya<br/>serta rawat-Nya.<br/>',NULL,61955,3);
INSERT INTO stanza VALUES('I363','3','Tiada kesepian,<br/>tiada kecewa,<br/>tiada k''luh kesah,<br/>tiada nestapa;<br/>Tiada problema<br/>- atas takhta-Nya,<br/>Dia s''lalu ingat<br/>pada umat-Nya.<br/>',NULL,61956,4);
INSERT INTO stanza VALUES('I363','4','Tiada k''lemahan<br/>yang tak Dia tunjang,<br/>tiada penyakit,<br/>tak Dia sembuhkan.<br/>O, setiap saat,<br/>duka ''tau senang,<br/>Yesus Peny''lamat,<br/>sertaku ''tiasa.<br/>',NULL,61957,5);
INSERT INTO stanza VALUES('I364','1','Mati dan bangkit bersama Dia;<br/>Masih adakah untukku buat?<br/>Tidak perlu ku gumul ronta;<br/>Bertindak berdasarkan hayat.<br/>Mulia bagi-Nya!<br/>',NULL,61958,1);
INSERT INTO stanza VALUES('I364','2','Bangkit bersama Sang Kepala;<br/>Kini ku tempuh jalan kudus;<br/>Melangkah maju, terbayangkan:<br/>Alangkah kurnia, lepas dosa!<br/>Mulia bagi-Nya!<br/>',NULL,61959,2);
INSERT INTO stanza VALUES('I364','3','Hidup, tempuh, bersama Tuhan;<br/>Dia Sang Kekal, tak kenal lambat;<br/>Diri ku bilang: sudah mati;<br/>Ku lepas dari s''mua ikatan.<br/>Mulia bagi-Nya!<br/>',NULL,61960,3);
INSERT INTO stanza VALUES('I364','4','Tubuh tersembah bagi Tuhan;<br/>Layani Allah, s''panjang usia;<br/>Di bawah kurnia, bukan Taurat;<br/>Tuhan mem''rintah, dosa lepas.<br/>Mulia bagi-Nya!<br/>',NULL,61961,4);
INSERT INTO stanza VALUES('I364','5','Sandar Tuhan aku bertumbuh;<br/>Malu, menyinggung masa lalu;<br/>Ku mau berbuahkan buah kudus;<br/>Puaskan kehendak, perkenan-Nya.<br/>Mulia bagi-Nya!<br/>',NULL,61962,5);
INSERT INTO stanza VALUES('I365','1','Dengan Kristus ku terpaku,<br/>salib t''lah bebaskanku;<br/>Dengan Kristus aku bangkit,<br/>Dia m''raja di dalamku.<br/>',NULL,61963,1);
INSERT INTO stanza VALUES('I365','chorus','Mati serta-Nya,<br/>sungguhlah nyaman!<br/>Lepas diri dan dunia!<br/>Hidup serta-Nya,<br/>sungguhlah unggul!<br/>Dia m''raja di dalamku.<br/>',NULL,61964,2);
INSERT INTO stanza VALUES('I365','2','Rahasia berabad-abad,<br/>demi iman ku paham;<br/>Dia dalamku sungguh mulia,<br/>ku mau puji s''lamanya!<br/>',NULL,61965,3);
INSERT INTO stanza VALUES('I365','3','Hukum alam semua paham:<br/>Benih mati tertanam,<br/>Barulah akan bertunas,<br/>tumbuh dan berbuah lebat.<br/>',NULL,61966,4);
INSERT INTO stanza VALUES('I365','4','Inilah rahasia suci,<br/>bukan jasa sendiri;<br/>Tuhan, hampakanlah aku,<br/>isilah d''ngan diri-Mu.<br/>',NULL,61967,5);
INSERT INTO stanza VALUES('I365','5','Yang sembuhkan penyakitmu,<br/>tak lain mati dirimu,<br/>Bahkan kuasa hayat Tuhan,<br/>jadi suplai dirimu.<br/>',NULL,61968,6);
INSERT INTO stanza VALUES('I365','6','Lewat salib, naik ke takhta,<br/>demikian Dia membawa,<br/>Mati dulu, baru mulia,<br/>inilah teladannya.<br/>',NULL,61969,7);
INSERT INTO stanza VALUES('I366','1','Kristus laksaan kali,<br/>lahir di Betlehem,<br/>Kalau b''lum di hati,<br/>kurnia belum jadi.<br/>Salib di Golgota,<br/>belum meny''lamatkan,<br/>Salib di dalammu,<br/>menolong kau tentu.<br/>',NULL,61970,1);
INSERT INTO stanza VALUES('I366','chorus','Marilah, salib Kristus!<br/>Masuk ke hatiku!<br/>Lepas kekang diriku,<br/>mutlak hidup sandar-Mu.<br/>',NULL,61971,2);
INSERT INTO stanza VALUES('I366','2','Apa yang kau kasihi,<br/>itu kau ''kan jadi!<br/>Tuhan atau duli,<br/>salah satu pasti.<br/>Keluar, Allah masuk;<br/>mati, Allah hidup;<br/>Kristus Mahagani,<br/>Dia-lah Sang Almuhit.<br/>',NULL,61972,3);
INSERT INTO stanza VALUES('I366','3','Ingin dapat Allah?<br/>Cinta paling dekat!<br/>Ikut hikmat insan,<br/>buang langkah b''laka.<br/>Kapan mengabaikan<br/>kepentingan diri,<br/>Allah Sang Mulia,<br/>penuhi kau pasti.<br/>',NULL,61973,4);
INSERT INTO stanza VALUES('I367','1','Tuhan, karya-Mu tak henti<br/>hanya sampai pada salib;<br/>Kini Dikau tetap hidup,<br/>berganti dengan corak Roh.<br/>',NULL,61974,1);
INSERT INTO stanza VALUES('I367','2','Kini Kau tetap s''lamatkan,<br/>tetap berfirman, memapah;<br/>Kini Kau Roh, ''ngalir deras,<br/>tetap sorot, orang tobat.<br/>',NULL,61975,2);
INSERT INTO stanza VALUES('I367','3','Kau Roh itu, mahakuat,<br/>beroperasi tak putus;<br/>Menggerakkan pun mendorong,<br/>tetap hibur, b''ri komando.<br/>',NULL,61976,3);
INSERT INTO stanza VALUES('I367','4','Dikau menjadi Roh itu,<br/>Dia datang, itulah Kau;<br/>Masuk lubuk dan penuhi,<br/>Roh-Mu itu - Kau sendiri.<br/>',NULL,61977,4);
INSERT INTO stanza VALUES('I367','5','Kini Dia peran di hati,<br/>perintah nan Kau ingini;<br/>S''perti Kau dulu di bumi,<br/>murad Bapa Kau taati.<br/>',NULL,61978,5);
INSERT INTO stanza VALUES('I367','6','Mengenal Dia - mengenal-Mu,<br/>taat Dia - taat murad-Mu;<br/>Diresap, dijenuhi Roh,<br/>dipenuhi d''ngan diri-Mu.<br/>',NULL,61979,6);
INSERT INTO stanza VALUES('I367','7','Kau bukan di langit tinggi,<br/>bukan pergi tak kembali;<br/>Kau tetap ada di sini,<br/>ajaib, hatiku, Kau huni!<br/>',NULL,61980,7);
INSERT INTO stanza VALUES('I368','1','Saat orang tak k''nal Bapa,<br/>dalam-Mu Dia ke sini;<br/>Walau bodoh kami ini,<br/>mengenal-Mu - kenal Bapa.<br/>',NULL,61981,1);
INSERT INTO stanza VALUES('I368','2','Namun saat Kau di bumi,<br/>yang kenal-Mu, sangat s''dikit;<br/>Seolah terisolasi,<br/>tak menjamah, walau himpit.<br/>',NULL,61982,2);
INSERT INTO stanza VALUES('I368','3','Datang lagi sebagai Roh,<br/>p''ri Bapa dulu atas-Mu;<br/>Mengenal Bapa dari-Mu,<br/>mengenal-Mu dari Sang Roh.<br/>',NULL,61983,3);
INSERT INTO stanza VALUES('I368','4','Tak sama daging yang dulu,<br/>berjerih lelah tak henti;<br/>Semayam kini di rohku,<br/>''tiasa suplaikan diri.<br/>',NULL,61984,4);
INSERT INTO stanza VALUES('I368','5','Pernah Kau ini Sang Bapa,<br/>kini Kau ialah Roh Kudus;<br/>Dengan corak yang berbeda,<br/>keadaan-Mu yang baru.<br/>',NULL,61985,5);
INSERT INTO stanza VALUES('I368','6','Kar''na mengenal Roh Kudus,<br/>ku mengenal mulia-Mu;<br/>Hayat-Mu serta sifat-Mu,<br/>hakiki-Mu nan ajaib.<br/>',NULL,61986,6);
INSERT INTO stanza VALUES('I368','7','Hati memuji nama-Mu,<br/>kenal Kau betapa riil;<br/>Tiada yang lebih karib<br/>atau yang lebih menarik.<br/>',NULL,61987,7);
INSERT INTO stanza VALUES('I369','1','Waktu Dikau dalam daging,<br/>mengenal-Mu ku tak jelas;<br/>Kini Kau jadi Roh itu,<br/>dalam rohku beri wahyu.<br/>',NULL,61988,1);
INSERT INTO stanza VALUES('I369','2','Dulu Dikau Penebusku,<br/>kini Dikau Pembelaku;<br/>Bukan lagi kontak luar,<br/>tapi di dalam bersatu.<br/>',NULL,61989,2);
INSERT INTO stanza VALUES('I369','3','Kini Kau jadi Roh itu,<br/>dalam rohku, t''rus b''ri wahyu;<br/>Diri-Mu pula sifat-Mu,<br/>terasa sungguh hadir-Mu.<br/>',NULL,61990,3);
INSERT INTO stanza VALUES('I369','4','Kini mengenal hayat-Mu,<br/>lampaui murid-Mu dulu,<br/>Meski m''reka makan, tinggal,<br/>kerja, rehat, bersama-Mu.<br/>',NULL,61991,4);
INSERT INTO stanza VALUES('I369','5','Tuhan jadi Roh di dalam,<br/>Dikau sungguh amat riil!<br/>Lebih nyata dari jamah,<br/>tak tampak tapi terkasih.<br/>',NULL,61992,5);
INSERT INTO stanza VALUES('I369','6','Dari batinku, Roh Kudus<br/>suplaikan diri-Mu s''lalu;<br/>Jadi kudus, adil, tebus,<br/>pula hikmat, berbuahku.<br/>',NULL,61993,6);
INSERT INTO stanza VALUES('I369','7','Kau jadi Roh, diam dalamku,<br/>menyuplai, satu denganku;<br/>Tiap saat ialah aku,<br/>tiap saat pun diri-Mu.<br/>',NULL,61994,7);
INSERT INTO stanza VALUES('I370','1','Yesus waktu Kau di dunia,<br/>lama nian m''reka serta-Mu;<br/>Tapi m''reka terhadap-Mu,<br/>kata kenal, namun tidak.<br/>',NULL,61995,1);
INSERT INTO stanza VALUES('I370','2','Suara-Mu pernah m''reka d''ngar,<br/>wajah-Mu t''lah m''reka nampak;<br/>Tubuh-Mu pun m''reka jamah,<br/>tapi siapa Kau, tak ta''ulah.<br/>',NULL,61996,2);
INSERT INTO stanza VALUES('I370','3','Kami seperti bertudung,<br/>meski ta''u, tapi tak jelas;<br/>Bila dikata tak kenal,<br/>kenal sudah sejak dulu.<br/>',NULL,61997,3);
INSERT INTO stanza VALUES('I370','4','Kini Kau jelma dalam Roh,<br/>jadi Pembelaku agung;<br/>Kau jadikan aku bait-Mu,<br/>memb''ri wahyu di dalamku.<br/>',NULL,61998,4);
INSERT INTO stanza VALUES('I370','5','Tuhan, limpahkanlah Roh-Mu,<br/>dalam diriku sepenuh;<br/>Semua bagian Kau harukan,<br/>semua bagian biar Kau jamah.<br/>',NULL,61999,5);
INSERT INTO stanza VALUES('I370','6','Demi Roh Kau telah masuk,<br/>lipat ganda di dalamku;<br/>Tak terdengar, tak terlihat,<br/>tak teraba, tapi nyata.<br/>',NULL,62000,6);
INSERT INTO stanza VALUES('I370','7','Demi rahmat Kau b''ri wahyu,<br/>diri-Mu kepada aku;<br/>Kau-lah tulus serta sungguh,<br/>lainnya tiada satu.<br/>',NULL,62001,7);
INSERT INTO stanza VALUES('I370','8','Limpahilah dengan Roh-Mu,<br/>sep''ri air bah membenamku;<br/>Biar di mana aku ada,<br/>nyatalah t''rang mulia Tuhan.<br/>',NULL,62002,8);
INSERT INTO stanza VALUES('I370','9','Hidup ini sungguh mesra,<br/>rasanya sep''ri di surga;<br/>Hati mulut penuh puji,<br/>Kau sertaku amat manis.<br/>',NULL,62003,9);
INSERT INTO stanza VALUES('I371','1','Tuhan, Kau kini Roh itu,<br/>menghidupkan pun b''ri hayat;<br/>Kelimpahan-mu suplaiku,<br/>amat mulia, amat kudus!<br/>',NULL,62004,1);
INSERT INTO stanza VALUES('I371','2','Tuhan, Kau kini Roh itu,<br/>kuasa-Mu bebaskanku;<br/>Hukum hayat berperan t''rus,<br/>hingga ku luasa, teguh.<br/>',NULL,62005,2);
INSERT INTO stanza VALUES('I371','3','Tuhan, Kau kini Roh itu,<br/>ubah aku bening cerah;<br/>Serupa peta gambar-Mu,<br/>mulia-Mu terpantul bulat.<br/>',NULL,62006,3);
INSERT INTO stanza VALUES('I371','4','Tuhan, Kau kini Roh itu,<br/>di rohku hidup semayam;<br/>Lewat rohkulah gerak-Mu,<br/>dua roh baur jadi esa.<br/>',NULL,62007,4);
INSERT INTO stanza VALUES('I371','5','Tuhan, bimbing latihanku,<br/>sentuh jamah Kau demi roh;<br/>Agar ku hidup di Roh-Mu,<br/>salurkan realitas-Mu!<br/>',NULL,62008,5);
INSERT INTO stanza VALUES('I372','1','Kristus-lah inti Allah,<br/>pun kesemestaan-Nya;<br/>Kristus-lah kenan Allah,<br/>kekal s''lama-lamanya.<br/>',NULL,62009,1);
INSERT INTO stanza VALUES('I372','2','Kristus jelmaan Allah,<br/>juga kepenuhan-Nya,<br/>Karakter ilahi-Nya,<br/>manusia tidak punya.<br/>',NULL,62010,2);
INSERT INTO stanza VALUES('I372','3','Tujuan Allah pada-Nya,<br/>penuhi segalanya,<br/>Biar Dia di alam s''mesta,<br/>dapat mulia sempurna.<br/>',NULL,62011,3);
INSERT INTO stanza VALUES('I372','4','Segala yang tercipta,<br/>oleh-Nya baru ada,<br/>Kini semua untuk-Nya,<br/>kar''na Kristus inti-Nya.<br/>',NULL,62012,4);
INSERT INTO stanza VALUES('I372','5','Kristus Juru-penebus,<br/>damaikan alam s''mesta,<br/>Darah-Nya yang berkhasiat,<br/>damaikan dengan Allah.<br/>',NULL,62013,5);
INSERT INTO stanza VALUES('I372','6','Dia awal segalanya,<br/>juga Kepala g''reja,<br/>Bangkit dari kematian,<br/>hayat dan isi g''reja.<br/>',NULL,62014,6);
INSERT INTO stanza VALUES('I372','7','Dalam K''rajaan Allah,<br/>Dia-lah Raja Penguasa,<br/>Mem''rintah dalam mulia,<br/>seg''nap alam semesta.<br/>',NULL,62015,7);
INSERT INTO stanza VALUES('I372','8','Di langit, bumi baru,<br/>Kristus inti semuanya,<br/>Bagi Allah pun insan,<br/>sampai s''lama-lamanya.<br/>',NULL,62016,8);
INSERT INTO stanza VALUES('I372','9','Allah ingin agar Dia,<br/>terutama dalam s''mua,<br/>Kristus-lah yang almuhit,<br/>jadi nikmatku kini!<br/>',NULL,62017,9);
INSERT INTO stanza VALUES('I373','1','Kristus saksi s''jati Allah,<br/>atas mutu, tutur, tindak;<br/>Penuh nyata mulia Allah,<br/>orang tampak sifat Allah.<br/>',NULL,62018,1);
INSERT INTO stanza VALUES('I373','2','Kristus saksi mutlak Allah,<br/>jauh melampaui Taurat,<br/>Taurat hanyalah harfiah,<br/>bukan hayat nan terkisah.<br/>',NULL,62019,2);
INSERT INTO stanza VALUES('I373','3','Limpah Allah dalam Kristus,<br/>jadi isi dan unsur-Nya;<br/>Dia-lah perwujudan Allah,<br/>kediaman, wadah Allah.<br/>',NULL,62020,3);
INSERT INTO stanza VALUES('I373','4','Mulia Allah, rupa Allah,<br/>atas Kristus nyata bulat;<br/>Hasrat Allah, jalan Allah,<br/>atas Kristus tampil tegas.<br/>',NULL,62021,4);
INSERT INTO stanza VALUES('I373','5','Kini Kristus dalam rohku,<br/>bagianku hingga kekal;<br/>Dalam roh Dia ku nikmati,<br/>s''gala Allah ku miliki.<br/>',NULL,62022,5);
INSERT INTO stanza VALUES('I374','1','Kristus realitas satu-satunya,<br/>bagi Allah pun bagi manusia,<br/>di luar Dia, tiada Allah,<br/>kecuali Dia tiada yang sejati.<br/>',NULL,62023,1);
INSERT INTO stanza VALUES('I374','2','Semua bayangan, semua pralambang,<br/>pun keperluan kecil dan besar,<br/>Justru ibarat Sang Kristus Allah,<br/>menyatakan Dia-lah segala.<br/>',NULL,62024,2);
INSERT INTO stanza VALUES('I374','3','Barang apa pun sia-sia belaka,<br/>andai tanpa Kristus di dalamnya;<br/>Menikmati segala-galanya,<br/>tanpa Kristus itu tetap kurang.<br/>',NULL,62025,3);
INSERT INTO stanza VALUES('I374','4','Kristus Sang Allah, Tuhan sejati,<br/>terang dan segala yang sejati,<br/>Sandang, pangan, air hayat sejati,<br/>hayat dan keindahan sejati.<br/>',NULL,62026,4);
INSERT INTO stanza VALUES('I374','5','Teologi dan doktri, semuanya,<br/>harus ada Kristus Sang Realitas;<br/>Tahu Alkitab di luar Kristus,<br/>itu aksara hampa belaka.<br/>',NULL,62027,5);
INSERT INTO stanza VALUES('I374','6','Kristus realitas waktu dan ruang,<br/>realitas setiap perkara,<br/>Kristus realitas satu-satunya,<br/>sampai kekal tak akan berubah.<br/>',NULL,62028,6);
INSERT INTO stanza VALUES('I375','1','Tuhan Kau buat diri-Mu,<br/>realitas hidupku ini;<br/>Atas iman, mulia riil,<br/>nyata lebihi yang lain;<br/>Elok riil, akrab intim,<br/>sanak daging bukan tanding.<br/>',NULL,62029,1);
INSERT INTO stanza VALUES('I375','2','Ku nampak visi berkat-Mu,<br/>hanya Tuhan sempurnaku,<br/>Kau t''lah murnikan hasratku,<br/>dengan api mahakudus;<br/>Kau t''lah tinggikan sifatku,<br/>penuh d''ngan limpah mulia-Mu.<br/>',NULL,62030,2);
INSERT INTO stanza VALUES('I375','3','Tuhan kekal, Sang Terkasih,<br/>makin dekat Kau dengaku,<br/>Makin pijar t''rang wajah-Mu,<br/>makin berjaya firman-Mu,<br/>Kasih-Mu mutlak ubahku,<br/>bertambah rahmat kurnia-Mu.<br/>',NULL,62031,3);
INSERT INTO stanza VALUES('I376','1','Definisi kurnia paling tinggi,<br/>Allah b''ri diri-Nya dalam Putra,<br/>Bukan perkara atau materi,<br/>Tapi diri-Nya, milikku s''lama.<br/>',NULL,62032,1);
INSERT INTO stanza VALUES('I376','2','Dia inkarnasi, baur d''ngan insan,<br/>Agar dit''rima dan didapatkan;<br/>Kurnia Allah yang diberikan,<br/>Kristus sendiri, huni di dalam.<br/>',NULL,62033,2);
INSERT INTO stanza VALUES('I376','3','Paulus memandang semua p''ri sampah,<br/>Hanyalah Kristus terbilang kurnia;<br/>Dia mengalami Tuhan Sang Kurnia,<br/>Berjerih lelah bagilah Tuhan.<br/>',NULL,62034,3);
INSERT INTO stanza VALUES('I376','4','Kristus dalamku, jadi t''nagaku,<br/>Kurnia sejati, patut diandal;<br/>Kurnia ini di dalam rohku,<br/>Tambah tenaga, rampung murad-Nya.<br/>',NULL,62035,4);
INSERT INTO stanza VALUES('I376','5','Kurnia ini, Kristus Sang Hayat,<br/>Jadi s''galaku, suplaiku ''tiasa;<br/>Tuhan, biarku kenal Kau Sang Kurnia,<br/>Nikmat kurnia-Mu makin bertambah.<br/>',NULL,62036,5);
INSERT INTO stanza VALUES('I377','1','Mulia! Kristus jadi hayatku.<br/>Mulia! Roh Kudus memimpinku,<br/>Lemah jadi kuat, gelap jadi t''rang.<br/>Mulia! Kristus jadi hayatku.<br/>',NULL,62037,1);
INSERT INTO stanza VALUES('I377','2','Mulia! Hidup bersandar Tuhan.<br/>Mulia! Jalan ikut Roh saja,<br/>Kalah jadi menang, puji d''ngan girang.<br/>Mulia! Hidup bersandar Tuhan.<br/>',NULL,62038,2);
INSERT INTO stanza VALUES('I378','1','Hayat dan alangkah teduh!<br/>Di batinku Kristus hidup!<br/>Bersama-Nya tersalibku,<br/>fakta mulia tebusan Hu!<br/>Bukan lagi aku hidup,<br/>tapi Kristus penggantiku!<br/>Bukan lagi aku hidup,<br/>tapi Kristus penggantiku!<br/>',NULL,62039,1);
INSERT INTO stanza VALUES('I378','2','Riang dan alangkah ''ngaso!<br/>Batinku Kristus terbentuk!<br/>Hayat Tuhan sifat kudus,<br/>atas diriku tersusun;<br/>Sudah tamat segalaku<br/>kadar-Nya kini s''galaku!<br/>Sudah tamat segalaku<br/>kadar-Nya kini s''galaku!<br/>',NULL,62040,2);
INSERT INTO stanza VALUES('I378','3','Mulia dan alangkah megah!<br/>Kristus ''tiasa diperbesar!<br/>Mati, hidup, mara, bah''gia,<br/>tiada satu mengaibkan;<br/>Apa suasana, p''ristiwa,<br/>Kristus selalu tertampak!<br/>Apa suasana, p''ristiwa,<br/>Kristus selalu tertampak!<br/>',NULL,62041,3);
INSERT INTO stanza VALUES('I378','4','Nasib dan berkat mulia!<br/>Aku hidup, Kristus nyata!<br/>Kehendak-Nya - aku gemar,<br/>mulia-Nya - ku utarakan;<br/>Lain tak mau, lain tiada,<br/>sasaranku Kristus s''mata!<br/>Lain tak mau, lain tiada,<br/>sasaranku Kristus s''mata!<br/>',NULL,62042,4);
INSERT INTO stanza VALUES('I379','1','Sungguh kuat! Sungguh kuasa!<br/>Allah t''lah bangkitkan Kristus,<br/>Duduk di sisi kanan-Nya,<br/>Dia-lah Kepala semesta,<br/>Kuat kuasa bagi g''reja,<br/>alam s''mesta terpalingkan.<br/>Kuat kuasa bagi g''reja,<br/>alam s''mesta terpalingkan.<br/>',NULL,62043,1);
INSERT INTO stanza VALUES('I379','2','Sungguh berkat! Sungguh mulia!<br/>Ku anggota Tubuh Kristus,<br/>Berbaur dengan umat saleh,<br/>terbangunlah insan baru.<br/>Esa dengan Sang Kepala,<br/>jadi Tubuh perkenan-Nya.<br/>Esa dengan Sang Kepala,<br/>jadi Tubuh perkenan-Nya.<br/>',NULL,62044,2);
INSERT INTO stanza VALUES('I379','3','Panjang, lebar, tinggi, dalam!<br/>Tak terukur selamanya!<br/>Kristus Allah tak terbatas,<br/>besar, luas, tak terduga!<br/>Hakiki-Nya dan milik-Nya,<br/>terampung demi gereja.<br/>Hakiki-Nya dan milik-Nya,<br/>terampung demi gereja.<br/>',NULL,62045,3);
INSERT INTO stanza VALUES('I380','1','Mulia! Mulia! Hayat mulia!<br/>Kristus-lah hayat mulia!<br/>Kudus, adil, bajik, terang!<br/>O, alangkah limpahnya!<br/>S''luruh limpah kaya Allah,<br/>terdapat di dalam-Nya,<br/>Kini Dia jadi hayatku,<br/>di dalamku suplaiku.<br/>',NULL,62046,1);
INSERT INTO stanza VALUES('I380','2','Kudus! Kudus! Hayat kudus!<br/>Kristus-lah hayat kudus!<br/>Terwujud dalam Roh Kudus,<br/>semayam di hatiku.<br/>Gerak, peran, sorot, ajar,<br/>mengurapi p''ri minyak;<br/>P''nuhi, curah, rawat, tunjang,<br/>di dalamku suplaiku.<br/>',NULL,62047,2);
INSERT INTO stanza VALUES('I380','3','Kuasa! Kuasa! Hayat kuasa!<br/>Kristus-lah hayat kuasa!<br/>Ku tersalib bersama-Nya,<br/>tak lagi hamba dosa.<br/>Ku pun bangkit bersama Dia,<br/>hidup bersama Dia,<br/>Alami kuasa bangkit,<br/>di dalamku suplaiku.<br/>',NULL,62048,3);
INSERT INTO stanza VALUES('I380','4','Menang! Menang! Hayat menang!<br/>Kristus-lah hayat menang!<br/>Atas salib Dia menang,<br/>ku tak lagi tawanan.<br/>Iblis, setan, dunia,<br/>iba, telah kalah semua,<br/>Kini Dia hayat menangku,<br/>di dalamku suplaiku.<br/>',NULL,62049,4);
INSERT INTO stanza VALUES('I380','5','Mulia! Kudus! Hayat kuasa,<br/>Kristus-lah hayat menang!<br/>Hingga aku kuat, menang,<br/>bertumbuh dan dewasa;<br/>Ku diubah serupa Dia,<br/>agar ku bebas, unggul,<br/>Hari itu Dia angkatku,<br/>di dalamku suplaiku.<br/>',NULL,62050,5);
INSERT INTO stanza VALUES('I381','1','Tuhan, Kau hayatku,<br/>hidup dalamku,<br/>Bawa limpah Allah,<br/>penuhi aku,<br/>Sifat-Mu yang kudus,<br/>menakdiskanku,<br/>Oleh kuasa bangkit,<br/>jaya ku tempuh.<br/>',NULL,62051,1);
INSERT INTO stanza VALUES('I381','2','Sang Hayat beredar,<br/>ku dapat terang,<br/>Hidup dalam terang,<br/>gaul d''ngan Tuhan;<br/>Suplai beraneka,<br/>tuntutan pula,<br/>Aku dibersihkan,<br/>nikmat s''gala-Mu.<br/>',NULL,62052,2);
INSERT INTO stanza VALUES('I381','3','Roh Kudus berperan,<br/>p''rilah urapan,<br/>Roh dan angan-angan,<br/>teresap semua,<br/>Anteroku t''rubah,<br/>serupa Tuhan,<br/>Bertumbuh dewasa,<br/>diri-Mu nyata.<br/>',NULL,62053,3);
INSERT INTO stanza VALUES('I381','4','Elemen hayat-Mu,<br/>jadi limpahku,<br/>Mendiris ''tiasa,<br/>hingga ku segar,<br/>Hayat telan maut,<br/>lemah jadi kuat;<br/>Ikatan terorak,<br/>luasa perkasa.<br/>',NULL,62054,4);
INSERT INTO stanza VALUES('I381','5','Antero diriku,<br/>serah pada-Mu,<br/>Sesuai murad-Mu,<br/>hidup bers''kutu;<br/>Henti ronta gumul,<br/>perbaikan pun,<br/>Itu malah ganggu<br/>daya kuasa-Mu.<br/>',NULL,62055,5);
INSERT INTO stanza VALUES('I381','6','Hentikan semua,<br/>daya upaya,<br/>Peran-mu mengubah,<br/>ego terlepas,<br/>Kaum saleh koordinat,<br/>jadi Tubuh-Nya,<br/>Dikau bersemayam,<br/>bahkan tertampak.<br/>',NULL,62056,6);
INSERT INTO stanza VALUES('I382','1','Kristus mulia, Juru-s''lamat,<br/>perwujudan mulia Allah!<br/>Asal Allah nan tak batas,<br/>jadi insan dalam waktu.<br/>',NULL,62057,1);
INSERT INTO stanza VALUES('I382','chorus','Kristus mulia, jelmaan Allah,<br/>ajaib, limpah tak bersudah!<br/>Mahakudus, Mahainsan,<br/>dalam roh ku jadi bah''gia.<br/>',NULL,62058,2);
INSERT INTO stanza VALUES('I382','2','Di dalam-Mu limpah Allah,<br/>ekspresikan mulia Allah;<br/>Dalam daging g''nap tebusan,<br/>di roh kini d''ngan ku esa.<br/>',NULL,62059,3);
INSERT INTO stanza VALUES('I382','3','Milik Bapa warisan-Mu,<br/>dalam Roh semua ada-Mu;<br/>Roh di rohku realitas-Mu,<br/>ku dapat alami Dikau.<br/>',NULL,62060,4);
INSERT INTO stanza VALUES('I382','4','Demi Sabda-Mu yang hidup,<br/>Roh riilkan di batinku;<br/>T''rima sabda, menjamah Roh,<br/>Dikau jadi suplaianku.<br/>',NULL,62061,5);
INSERT INTO stanza VALUES('I382','5','Sembah, ''natap di dalam roh,<br/>memantulkan mulia-Mu;<br/>Ku berubah serupa-Mu,<br/>hingga ternyatalah Dikau.<br/>',NULL,62062,6);
INSERT INTO stanza VALUES('I382','6','Demikian baru kudus,<br/>demikian baru menang;<br/>Lain takkan jamah hayat,<br/>lain takkan rohaniah.<br/>',NULL,62063,7);
INSERT INTO stanza VALUES('I382','7','Roh resapi ku merata,<br/>semua Kristus, semua Allah!<br/>Awak diri lucut lontar,<br/>g''nap kaum saleh kediaman-Nya.<br/>',NULL,62064,8);
INSERT INTO stanza VALUES('I383','1','Dalam mulia ada<br/>Allah - manusia,<br/>Kudus adil pun hikmat,<br/>terang pun rahmat;<br/>Bagiku korban jiwa,<br/>g''napkan tebusan;<br/>Ku mendapat sifat-Nya,<br/>serupa Dia.<br/>',NULL,62065,1);
INSERT INTO stanza VALUES('I383','2','Dalam mulia ada<br/>Raja Pemenang,<br/>Singkirkan kuasa gelap,<br/>enyahkan Satan,<br/>Menembus alam maut,<br/>t''rangkat ke surga;<br/>Ku dilantik dengan-Nya,<br/>menang serta-Nya.<br/>',NULL,62066,2);
INSERT INTO stanza VALUES('I383','3','Dalam mulia ada<br/>Dia Sang Hayat,<br/>Di batinku ''tiasa<br/>pimpin pun p''rintah,<br/>Agar sifat kudus-nya,<br/>''tas ku tergarap,<br/>Biar hayat-Nya yang<br/>mulia terekspresikan.<br/>',NULL,62067,3);
INSERT INTO stanza VALUES('I383','4','Dalam mulia ada<br/>Dia Sang Harapan,<br/>Tak lama Dia ''kan datang,<br/>bawa ku pulang,<br/>Dengan kuasa mulia-Nya,<br/>ku diubah-Nya,<br/>Biar ku serupa Dia,<br/>sampai s''lamanya.<br/>',NULL,62068,4);
INSERT INTO stanza VALUES('I384','1','Pohon sebuah, sungai sebuah,<br/>ciri-ciri taman ria,<br/>Beri makan, lerai dah''ga,<br/>hidup depan Allah.<br/>',NULL,62069,1);
INSERT INTO stanza VALUES('I384','chorus','Dia dalam Kristus, makananku;<br/>Kristus jadi Roh, nutrisiku;<br/>Roh yang almuhit kenyangkanku,<br/>Allah ku nikmati.<br/>',NULL,62070,2);
INSERT INTO stanza VALUES('I384','2','Pohon buah lambang Kristus,<br/>menjadi makanan hayat,<br/>Limpah Allah nikmati t''rus,<br/>niscayalah puas.<br/>',NULL,62071,3);
INSERT INTO stanza VALUES('I384','3','Sungai lambangkan Roh Kudus,<br/>menjadi suplaian rohku,<br/>Limpah Allah kecap terus,<br/>insan jadi kudus.<br/>',NULL,62072,4);
INSERT INTO stanza VALUES('I384','4','Kristus mulia jadi hayat,<br/>demi Roh hidup di rohku,<br/>Ku terbaur sifat Allah,<br/>berbagian mulia-Nya.<br/>',NULL,62073,5);
INSERT INTO stanza VALUES('I384','5','Kristus mulia ku agungkan,<br/>Roh tak batas ku mau taat,<br/>Mulia Allah ku wujudkan,<br/>kurnia tak sudah!<br/>',NULL,62074,6);
INSERT INTO stanza VALUES('I385','1','Tuhan, Kau-lah manna,<br/>turun dari surga;<br/>Jadi makananku,<br/>mengenyangkan aku.<br/>',NULL,62075,1);
INSERT INTO stanza VALUES('I385','2','Kau batu terbelah,<br/>alirkan air hayat,<br/>''Tiasa ku minum,<br/>haus lerai pupus.<br/>',NULL,62076,2);
INSERT INTO stanza VALUES('I385','3','Ku lapar dan haus,<br/>datang kepada-Mu,<br/>Dikau merawatku,<br/>beri air hidup.<br/>',NULL,62077,3);
INSERT INTO stanza VALUES('I385','4','Makan serta minum,<br/>menyantap diri-Mu,<br/>Kenyang akan hayat,<br/>menyesap Roh Kudus.<br/>',NULL,62078,4);
INSERT INTO stanza VALUES('I385','5','Tanpa demikian,<br/>akan hampa sia-sia,<br/>Makan serta minum,<br/>hidup kuat perkasa.<br/>',NULL,62079,5);
INSERT INTO stanza VALUES('I386','1','Kristus itu duniaku,<br/>hayat, riang, s''galaku!<br/>Dia-lah kuatku, menunjangku,<br/>jauhi Dia, ku jatuh;<br/>Ku berduka sg''ra hampir Dia,<br/>dengan mesra Dia menghibur;<br/>Hati girang, duka hilang,<br/>Dia temanku!<br/>',NULL,62080,1);
INSERT INTO stanza VALUES('I386','2','Kristus itu duniaku,<br/>bantuan tiap waktu;<br/>B''ri rawatan, b''ri simpati,<br/>b''ri berkat padaku;<br/>Dia b''ri hujan dan mentari,<br/>Dia b''ri benih, panen, subur;<br/>Berlimpahlah yang ku dapat,<br/>Dia temanku!<br/>',NULL,62081,2);
INSERT INTO stanza VALUES('I386','3','Kristus itu duniaku,<br/>pada-Nya ku setia!<br/>Mana mungkin Dia ku tolak,<br/>waktu Dia b''ri kurnia?<br/>Ikut Tuhan takkan sesat,<br/>Dia yang pimpin lewat malam;<br/>Ikut Tuhan sampai fajar,<br/>Dia temanku!<br/>',NULL,62082,3);
INSERT INTO stanza VALUES('I386','4','Kristus itu duniaku,<br/>yang lain ku tak perlu;<br/>Dengan Tuhan aku esa,<br/>s''lama tak terpisah.<br/>Hayat indah milik Tuhan,<br/>hayat indah kekal s''lama;<br/>Hayat kekal di dalamku,<br/>Dia temanku!<br/>',NULL,62083,4);
INSERT INTO stanza VALUES('I387','1','Tak peduli jahat dosa,<br/>tak peduli liku jalan,<br/>Tak peduli situasi,<br/>Kau cukup ku pakai.<br/>',NULL,62084,1);
INSERT INTO stanza VALUES('I387','2','Pencobaan besar kecil,<br/>rasa kuatir, banyak ''dikit,<br/>Bahkan jatuh tergelincir,<br/>Kau cukup ku pakai.<br/>',NULL,62085,2);
INSERT INTO stanza VALUES('I387','3','Saat dunia menarik nian,<br/>cerah langit, lancar jalan,<br/>Awan manja tutup terang,<br/>Kau cukup ku pakai.<br/>',NULL,62086,3);
INSERT INTO stanza VALUES('I387','4','Saat duka rundung datang,<br/>putus asa, suram kelam,<br/>Hati beku, susah doa,<br/>Kau cukup ku pakai.<br/>',NULL,62087,4);
INSERT INTO stanza VALUES('I387','5','Tak peduli situasiku,<br/>tangan-Mu menatang terus,<br/>Hingga aku mengalami<br/>Dikau serba cukup.<br/>',NULL,62088,5);
INSERT INTO stanza VALUES('I388','beginning-note','Syair Kesatu<br/>',NULL,62089,1);
INSERT INTO stanza VALUES('I388','1','Ku dapat maha mustika,<br/>hati gejolak riang,<br/>Ku bersorak, telah dapat<br/>Sang Kristus nan hebat!<br/>',NULL,62090,2);
INSERT INTO stanza VALUES('I388','2','Kristus ialah Domba Allah,<br/>Sang Penanggung dosa,<br/>Surya keadilan Allah,<br/>sinar kesembuhan.<br/>',NULL,62091,3);
INSERT INTO stanza VALUES('I388','3','Kristus ialah pohon hayat,<br/>dalam taman Allah,<br/>Buahnya jadi makanan,<br/>suplai, sedap, limpah.<br/>',NULL,62092,4);
INSERT INTO stanza VALUES('I388','4','Kristus ialah sumber hayat,<br/>alirkan air hayat,<br/>Di batinku hingga kekal,<br/>lerai s''mua dahaga.<br/>',NULL,62093,5);
INSERT INTO stanza VALUES('I388','5','Kristus ialah Imamku,<br/>tampil depan Allah,<br/>Pun Nabi yang penuh wahyu,<br/>Raja yang berdaulat.<br/>',NULL,62094,6);
INSERT INTO stanza VALUES('I388','6','Penolong, Tabib, Pembela,<br/>Gembala, Kepala,<br/>Abang, Bapa, Allah, Tuhan,<br/>Guru, Kasih, Teman.<br/>',NULL,62095,7);
INSERT INTO stanza VALUES('I388','7','Hayat, Kekuatan, Hikmat,<br/>Adil, Kudus, Tebus,<br/>Damai, Riang, Harap, Hibur,<br/>Mulia, T''rang, Jalanku.<br/>',NULL,62096,8);
INSERT INTO stanza VALUES('I388','8','Kristus ialah Sang Almuhit,<br/>tak habis terkisah;<br/>Dia Sang Awal pun Sang Akhir,<br/>segala-galanya.<br/>',NULL,62097,9);
INSERT INTO stanza VALUES('I388','9','Dapat mustika demikian,<br/>tak tahan membungkam!<br/>Ku bersorak, telah dapat,<br/>Sang Kristus nan hebat!<br/>',NULL,62098,10);
INSERT INTO stanza VALUES('I388','beginning-note','Syair Kedua<br/>',NULL,62099,11);
INSERT INTO stanza VALUES('I388','1','Ku dapat maha mustika,<br/>hati gejolak riang,<br/>Ku bersorak, telah dapat<br/>Sang Kristus nan hebat!<br/>',NULL,62100,12);
INSERT INTO stanza VALUES('I388','2','Kristus ialah Domba Allah,<br/>Sang Penanggung dosa,<br/>Surya keadilan Allah,<br/>sinar kesembuhan.<br/>',NULL,62101,13);
INSERT INTO stanza VALUES('I388','3','Kristus ialah pohon hayat,<br/>dalam taman Allah,<br/>Buahnya jadi makanan,<br/>suplai, sedap, limpah.<br/>',NULL,62102,14);
INSERT INTO stanza VALUES('I388','4','Kristus ialah batu terb''lah,<br/>alirkan air hayat;<br/>Di batinku, sumber hayat,<br/>lerai s''mua dahaga.<br/>',NULL,62103,15);
INSERT INTO stanza VALUES('I388','5','Hayat, terang, pula jalan,<br/>hibur, sabat, sehat;<br/>Banggaku, mulia, limpah,<br/>damai, riang, harap.<br/>',NULL,62104,16);
INSERT INTO stanza VALUES('I388','6','Hikmat pula keadilan,<br/>kudus, realitas;<br/>Penebusan, kekuatan,<br/>bebas, jaya menang.<br/>',NULL,62105,17);
INSERT INTO stanza VALUES('I388','7','Kristus ialah Imamku,<br/>tampil depan Allah,<br/>Pun Nabi yang penuh wahyu,<br/>Raja yang berdaulat.<br/>',NULL,62106,18);
INSERT INTO stanza VALUES('I388','8','Penolong, Tabib, Pembela,<br/>Gembala, Kepala,<br/>Abang, Bapa, Allah, Tuhan,<br/>Guru, Kasih, Teman.<br/>',NULL,62107,19);
INSERT INTO stanza VALUES('I388','9','Panglima pun Peloporku,<br/>pimpin perang, tempur;<br/>Bela, bimbing, pula tuntun,<br/>jaga, rawat, lindung.<br/>',NULL,62108,20);
INSERT INTO stanza VALUES('I388','10','Kristus, kediamanku kekal,<br/>tanah permai limpah;<br/>Benteng tinggi, tempat lindung,<br/>tujuan kekalku.<br/>',NULL,62109,21);
INSERT INTO stanza VALUES('I388','11','Pengharapan dan sandaran,<br/>perkenan, kepuasan;<br/>Pahala pula sasaran,<br/>suplaian, bantuan.<br/>',NULL,62110,22);
INSERT INTO stanza VALUES('I388','12','Kristus ialah tanah subur,<br/>hujan, diris, embun;<br/>Pohon anggur sejatiku,<br/>dalam Dia, huniku.<br/>',NULL,62111,23);
INSERT INTO stanza VALUES('I388','13','Hari raya, bulan baru,<br/>hari Sabat s''jati;<br/>Fajar, pagi, siang hari,<br/>kini pun abadi.<br/>',NULL,62112,24);
INSERT INTO stanza VALUES('I388','14','Kristus ialah Sang Almuhit,<br/>tak habis terkisah;<br/>Dia Sang Awal pun Sang Akhir,<br/>segala-galanya.<br/>',NULL,62113,25);
INSERT INTO stanza VALUES('I388','15','Dapat mustika demikian,<br/>tak tahan membungkam!<br/>Ku bersorak, telah dapat,<br/>Sang Kristus nan hebat!<br/>',NULL,62114,26);
INSERT INTO stanza VALUES('I389','1','Nikmat dunia pupus,<br/>Dia milikku!<br/>Tali dunia putus,<br/>Dia milikku!<br/>Padang gurun gelap,<br/>tiada tempat teduh,<br/>Andal hanya Kristus,<br/>Dia milikku!<br/>',NULL,62115,1);
INSERT INTO stanza VALUES('I389','2','Jangan bujuk aku,<br/>Dia milikku!<br/>Hadir-Nya ku mau,<br/>Dia milikku!<br/>Pelesiran dunia,<br/>tipuan melulu,<br/>Enyahlah dariku,<br/>Dia milikku!<br/>',NULL,62116,2);
INSERT INTO stanza VALUES('I389','3','Pergi, hai fantasi,<br/>Dia milikku!<br/>T''lah sadar ku kini,<br/>Dia milikku!<br/>Yang dulu ku damba,<br/>hanya bawa d''rita;<br/>hanya Dia puasku,<br/>Dia milikku!<br/>',NULL,62117,3);
INSERT INTO stanza VALUES('I389','4','Pergi, masa fana,<br/>Dia milikku!<br/>Mari, masa kekal,<br/>Dia milikku!<br/>Mari, berkat bah''gia,<br/>perhentian indah!<br/>Mari, Tuhan kurnia!<br/>Dia milikku!<br/>',NULL,62118,4);
INSERT INTO stanza VALUES('I390','1','Yesus P''nolongku, Dia-lah s''galaku!<br/>Penolong ajaib, penuh simpati!<br/>Yang menjagaku lewat bahaya,<br/>Yesus P''nolongku yang perkasa.<br/>',NULL,62119,1);
INSERT INTO stanza VALUES('I390','chorus','Tuhan Yesus, untuk aku!<br/>Yesus untuk aku setiap waktu!<br/>',NULL,62120,2);
INSERT INTO stanza VALUES('I390','2','Waktu ku sehat atau pun sakit,<br/>waktu ku kaya atau pun miskin,<br/>Waktu hari c''rah atau berawan,<br/>Yesus untukku - sejaht''ralah!<br/>',NULL,62121,3);
INSERT INTO stanza VALUES('I390','3','Dia-lah bentengku dan perisaiku,<br/>Dia-lah hayatku, sinar terangku,<br/>Dia-lah pelopor dan pelindungku,<br/>Yesus untukku - ku terlindung!<br/>',NULL,62122,4);
INSERT INTO stanza VALUES('I390','4','Dia-lah Nabiku, Imam, Rajaku,<br/>Dia-lah air hayat dan makananku,<br/>Dia-lah keb''naran dan sandaranku,<br/>Yesus untukku - ku selamat!<br/>',NULL,62123,5);
INSERT INTO stanza VALUES('I390','5','Waktu gembira atau pun susah,<br/>waktu ku rugi atau pun untung,<br/>Di mana saja Dia ''kan menunjang,<br/>Yesus untukku - hingga kekal!<br/>',NULL,62124,6);
INSERT INTO stanza VALUES('I391','1','Sumber "tenang" nan misteri,<br/>kasih limpah nan ilahi,<br/>Pertolongan pun andalan,<br/>hadir-Mu jaminan aman,<br/>Tinggalkan duka dan dosa,<br/>dalam-Mu aku berdiam.<br/>',NULL,62125,1);
INSERT INTO stanza VALUES('I391','2','Semua keperluanku,<br/>perhentian, penghiburan,<br/>Urapan penutup luka,<br/>sejahtera pun faedah,<br/>Senyum dan mahkota saat<br/>bagi-Mu d''rita sengsara.<br/>',NULL,62126,2);
INSERT INTO stanza VALUES('I391','3','Suplai saat kekurangan,<br/>pelepas atas tawanan;<br/>Kekuatan atas lemah,<br/>terang atas gelap kelam;<br/>Sukacita dalam duka;<br/>bangkit atas kematian.<br/>',NULL,62127,3);
INSERT INTO stanza VALUES('I391','4','Sumber "tenang" nan misteri,<br/>kasih limpah nan ilahi,<br/>Dalam-Mu ku mau sembunyi,<br/>nikmat hadir-Mu nan manis,<br/>Kau-lah segala-galaku,<br/>tak bersudah nikmati-Mu.<br/>',NULL,62128,4);
INSERT INTO stanza VALUES('I392','1','Dia-lah yang tercinta,<br/>bagiku termesra;<br/>Kedambaan insan,<br/>pun sandaran insan!<br/>',NULL,62129,1);
INSERT INTO stanza VALUES('I392','2','Sedia, saat kurang;<br/>papah, saat goyah;<br/>Dia-lah yang terindah,<br/>patut dipercaya!<br/>',NULL,62130,2);
INSERT INTO stanza VALUES('I392','3','Sumber riang tak batas,<br/>tak b''rubah s''lamanya,<br/>Dia-lah yang tercinta,<br/>Dia-lah yang termesra!<br/>',NULL,62131,3);
INSERT INTO stanza VALUES('I393','1','Riang atas riang,<br/>dah''gaku Dia lerai,<br/>Kidung atas kidung,<br/>enyah kesepian.<br/>',NULL,62132,1);
INSERT INTO stanza VALUES('I393','2','Elok atas elok,<br/>sesuai seleraku,<br/>Anggun atas anggun,<br/>mustika terunggul.<br/>',NULL,62133,2);
INSERT INTO stanza VALUES('I393','3','Hayat atas hayat,<br/>aku dibangkitkan,<br/>Kudus atas kudus,<br/>menyisihkan aku.<br/>',NULL,62134,3);
INSERT INTO stanza VALUES('I393','4','Adil atas adil,<br/>tegak ku berdiri,<br/>Kuat atas kuat,<br/>ku jalan tak penat.<br/>',NULL,62135,4);
INSERT INTO stanza VALUES('I393','5','Daya atas daya,<br/>ku terbang p''ri elang,<br/>Menang atas menang,<br/>ku kalahkan lawan.<br/>',NULL,62136,5);
INSERT INTO stanza VALUES('I393','6','Kuat atas kuat,<br/>aku dibebaskan,<br/>Kekar atas kekar,<br/>rohku kuat segar.<br/>',NULL,62137,6);
INSERT INTO stanza VALUES('I393','7','Raja atas raja,<br/>dalamku meraja,<br/>Terang atas terang,<br/>''tiasa pancar terang.<br/>',NULL,62138,7);
INSERT INTO stanza VALUES('I393','8','Tuan atas tuan,<br/>hatiku tinggal-Nya,<br/>Jalan atas jalan,<br/>pimpin tiap langkah.<br/>',NULL,62139,8);
INSERT INTO stanza VALUES('I393','9','Tabib atas tabib,<br/>roh, jiwa, dan tubuh,<br/>Ajaib atas ajaib,<br/>mulia tanpa tanding.<br/>',NULL,62140,9);
INSERT INTO stanza VALUES('I393','10','Harap atas harap,<br/>tarikku ke atas,<br/>Pikat atas pikat,<br/>pimpinku ke depan.<br/>',NULL,62141,10);
INSERT INTO stanza VALUES('I393','11','Kasih atas kasih,<br/>patut ku bersyukur,<br/>Sabar atas sabar,<br/>kekal ku menyembah.<br/>',NULL,62142,11);
INSERT INTO stanza VALUES('I393','12','Dia mahaperkasa,<br/>patut ku agungkan,<br/>Dia mahamulia,<br/>patut t''rima puja.<br/>',NULL,62143,12);
INSERT INTO stanza VALUES('I394','1','Dulu mau berkat,<br/>kini mau Tuhan;<br/>Dulu mau sembuh,<br/>kini Dia s''mata;<br/>Dulu mau kurnia,<br/>kini Pemb''rinya;<br/>Dulu mau kuasa,<br/>kini Sang Kuasa.<br/>',NULL,62144,1);
INSERT INTO stanza VALUES('I394','chorus','Kekal junjung Yesus,<br/>puji tak henti;<br/>Semua dalam Kristus,<br/>Dia segalaku.<br/>',NULL,62145,2);
INSERT INTO stanza VALUES('I394','2','Dulu pegang Tuhan,<br/>kini dipegang;<br/>Dulu ragu bimbang,<br/>kini sauh mantap;<br/>Dulu raba rasa,<br/>kini sabda-Nya;<br/>Dulu berusaha,<br/>kini s''rah mutlak.<br/>',NULL,62146,3);
INSERT INTO stanza VALUES('I394','3','Dulu berencana,<br/>kini berdoa;<br/>Dulu resah bingung,<br/>kini Dia tanggung;<br/>Dulu semau awak,<br/>kini tadbir-Nya;<br/>Dulu minta terus,<br/>kini muji t''rus.<br/>',NULL,62147,4);
INSERT INTO stanza VALUES('I394','4','Dulu ku memakai,<br/>kini Dia pakai;<br/>Dulu karya beta,<br/>kini karya-Nya;<br/>Dulu harap sanjung,<br/>kini kenan-Nya;<br/>Dulu s''lamat s''paruh,<br/>kini seluruh.<br/>',NULL,62148,5);
INSERT INTO stanza VALUES('I394','5','Dulu raih Dia,<br/>kini milik-Nya;<br/>Dulu suram redup,<br/>kini benderang;<br/>Dulu tunggu ajal,<br/>kini balik-Nya;<br/>Segala-galaku,<br/>pada-Nya saja.<br/>',NULL,62149,6);
INSERT INTO stanza VALUES('I395','1','Hanya Yesus! Hanya Yesus,<br/>judul dan beritaku!<br/>Hanya Yesus! Hanya Yesus,<br/>nyanyian dan harapanku!<br/>',NULL,62150,1);
INSERT INTO stanza VALUES('I395','chorus','Hanya Yesus! S''lama Yesus,<br/>jadi isi kidungku,<br/>Dia-lah Hayat dan Tabibku,<br/>Penolong, dan Rajaku.<br/>',NULL,62151,2);
INSERT INTO stanza VALUES('I395','2','Hanya Yesus Penolongku,<br/>yang pikul s''mua dosaku;<br/>Kekal, rampung penebusan,<br/>hingga ku t''rima rahmat.<br/>',NULL,62152,3);
INSERT INTO stanza VALUES('I395','3','Hanya Yesus-lah hayatku,<br/>tolongku lepas dosa;<br/>Dengan Roh-Nya penuhiku,<br/>menjadi tenagaku.<br/>',NULL,62153,4);
INSERT INTO stanza VALUES('I395','4','Hanya Yesus Penyembuhku,<br/>yang tanggung s''mua sakitku;<br/>Hayat bangkit, limpah Tuhan,<br/>penuhi anggota-Nya.<br/>',NULL,62154,5);
INSERT INTO stanza VALUES('I395','5','Hanya Yesus kuasaku,<br/>dan Pemb''ri Pentakosa;<br/>Tuhan, curahkanlah Roh-Mu,<br/>agar ku s''lalu menang.<br/>',NULL,62155,6);
INSERT INTO stanza VALUES('I395','6','Kini kami tunggu Yesus,<br/>memanggil kami semua;<br/>Kami harap hanya Yesus,<br/>Yesus Tuhan semesta.<br/>',NULL,62156,7);
INSERT INTO stanza VALUES('I396','1','Sungguh gelap, hambar,<br/>saat ku tak nampak mulia Kristus;<br/>Kicau burung, bunga indah,<br/>bagiku tak lagi indah,<br/>Cah''ya mentari reduplah,<br/>ladang pun tak lagi hijau,<br/>Bila ku girang dalam Dia,<br/>mendung pun terlihat indah.<br/>',NULL,62157,1);
INSERT INTO stanza VALUES('I396','2','Nama-Nya harum semerbak,<br/>suara-Nya musik terindah;<br/>Hadir-Nya lenyapkan duka,<br/>batinku bersukacita,<br/>Saat Dia dekat akrab,<br/>tiada lagi takut, cemas,<br/>Girang hati tiada tanding,<br/>sukacita nan abadi.<br/>',NULL,62158,2);
INSERT INTO stanza VALUES('I396','3','Nampak wajah-Nya ku puas,<br/>perkenan-Nya yang ku tuntut;<br/>Entah apa suasana,<br/>tak dapat ubah minatku,<br/>Asal kasih-Nya sertaku,<br/>istana pun tak ku acuh;<br/>B''lenggu pun jadi istana,<br/>bila Yesus besertaku.<br/>',NULL,62159,3);
INSERT INTO stanza VALUES('I396','4','Tuhan, bila ku milik-Mu,<br/>Kau pun kidung, mentariku,<br/>M''ngapa ku harus merana?<br/>Lewat musim dingin panjang?<br/>Singkirkanlah awan gelap,<br/>pulihkan riang hadir-Mu;<br/>Bawaku ke hadirat-Mu,<br/>tiada awan gelap, salju.<br/>',NULL,62160,4);
INSERT INTO stanza VALUES('I397','1','Kristus itu subyektifku,<br/>jadi hayat di rohku;<br/>Kristus itu segalaku,<br/>dengan-Nya ku satu Roh.<br/>',NULL,62161,1);
INSERT INTO stanza VALUES('I397','chorus','O, Kristus itulah suyektifku,<br/>riil, manis, pun limpah.<br/>Kristus itu segala-galaku,<br/>perluku terjamin s''mua.<br/>',NULL,62162,2);
INSERT INTO stanza VALUES('I397','2','Kristus itu subyektifku,<br/>suplai hayat tak putus;<br/>Roh hayat menyegarkanku,<br/>rohku bubung selalu.<br/>',NULL,62163,3);
INSERT INTO stanza VALUES('I397','3','Kristus itu subyektifku,<br/>ubah hayat jiwaku;<br/>Angan, tekad alih baru,<br/>hingga ku serupa Hu.<br/>',NULL,62164,4);
INSERT INTO stanza VALUES('I397','4','Kristus itu subyektifku,<br/>orakkan anteroku;<br/>T''naga hukum hayat mampu<br/>dalam roh bebaskanku.<br/>',NULL,62165,5);
INSERT INTO stanza VALUES('I397','5','Kristus itu subyektifku,<br/>jadi prinsip, kaidahku;<br/>Bimbing, ajar, cegah, atur,<br/>membetulkan diriku.<br/>',NULL,62166,6);
INSERT INTO stanza VALUES('I397','6','Kristus itu subyektifku,<br/>apa pun ku tak kurang;<br/>Kaya limpah-Nya suplaiku,<br/>ku nikmati limpah-Nya.<br/>',NULL,62167,7);
INSERT INTO stanza VALUES('I398','1','Kau obyektif dan subyektif bagiku;<br/>Obyektif, di surga berdoa syafaat;<br/>Subyektif, dalamku jadi hayatku,<br/>Setiap saat Kau suplaikan diri-Mu.<br/>',NULL,62168,1);
INSERT INTO stanza VALUES('I398','2','Di sisi kanan Allah Kau bertakhta,<br/>Jadi Imam Besar sembahkan kurban;<br/>Jadi Pembelaku, tanggung bebanku,<br/>Berdasar kasih, setia membelaku.<br/>',NULL,62169,2);
INSERT INTO stanza VALUES('I398','3','Kini Kau Roh itu di dalam rohku;<br/>Jadi hayatku, membawa segala;<br/>Jadi kuat, kurniaku tiap saat,<br/>Pun jadi Pembela agung tunjangku.<br/>',NULL,62170,3);
INSERT INTO stanza VALUES('I398','4','Dia-lah Sang Mulia di surga bagiku,<br/>Pelopor yang g''napkan rencana Allah;<br/>Jadikan Allah dan manusia satu,<br/>Dalam Dia sebagai Putra di surga.<br/>',NULL,62171,4);
INSERT INTO stanza VALUES('I398','5','Dalamku Dia jadi kepenuhanku.<br/>Dia-lah Roh salurkan Allah dalamku,<br/>Oleh wahyu, Allah riil bagiku,<br/>Dalam hayat, Allah - insan pun satu.<br/>',NULL,62172,5);
INSERT INTO stanza VALUES('I398','6','Sang T''rangkat, obyektif, diam di surga;<br/>Tak lama lagi Dia ''kan datang pula;<br/>Kristus subyektif hidup di dalamku;<br/>Dia mengubahku, mulia serupa Dia.<br/>',NULL,62173,6);
INSERT INTO stanza VALUES('I398','7','Langit bumi s''rasi, harinya tiba;<br/>Di Yerusalem Baru baur esa;<br/>Obyektif pun subyektif, saat itu;<br/>Baur esa dalamku, mulia kekal.<br/>',NULL,62174,7);
INSERT INTO stanza VALUES('I399','1','Perkenan dan murad Allah,<br/>agar Kristus terwahyu,<br/>Bukan agama luaran,<br/>tapi Kristus dalamku.<br/>',NULL,62175,1);
INSERT INTO stanza VALUES('I399','chorus','Perkenan dan murad Allah,<br/>Kristus hidup dalamku,<br/>Bukan hasil yang di luar,<br/>tapi Kristus p''nuhiku.<br/>',NULL,62176,2);
INSERT INTO stanza VALUES('I399','2','Perkenan dan murad Allah,<br/>Kristus hidup dalamku,<br/>Bukan pekerjaan luaran,<br/>tapi Kristus kurniaku.<br/>',NULL,62177,3);
INSERT INTO stanza VALUES('I399','3','Perkenan dan murad Allah,<br/>Kristus garap jiwaku,<br/>Bukan tata cara luaran,<br/>tapi Kristus tambah t''rus.<br/>',NULL,62178,4);
INSERT INTO stanza VALUES('I399','4','Perkenan dan murad Allah,<br/>Kristus s''mayam dalamku,<br/>Bukan ibadah luaran,<br/>tapi Kristus mengatur.<br/>',NULL,62179,5);
INSERT INTO stanza VALUES('I399','5','Perkenan dan murad Allah,<br/>Kristus-lah harapanku,<br/>Bukan mulia luaran,<br/>tapi Kristus muliaku.<br/>',NULL,62180,6);
INSERT INTO stanza VALUES('I399','6','Perkenan dan murad Allah,<br/>Kristus jadi segala,<br/>Bukan mendapat yang di luar,<br/>tapi Kristus rah''sianya.<br/>',NULL,62181,7);
INSERT INTO stanza VALUES('I400','1','Tuhan, padaku Kau hayat,<br/>juga segalanya!<br/>Sungguh praktis, sungguh mesra,<br/>sedia hingga kekal!<br/>',NULL,62182,1);
INSERT INTO stanza VALUES('I400','chorus','O, Tuhan, Kau-lah Roh hayat,<br/>dekat, akrab d''nganku!<br/>Praktis, mesra tak terkata,<br/>manis s''lalu baru.<br/>',NULL,62183,2);
INSERT INTO stanza VALUES('I400','2','Atas s''mua keperluanku,<br/>Kau suplai selalu;<br/>Kau b''rikan berlimpah ruah,<br/>berguna di rohku.<br/>',NULL,62184,3);
INSERT INTO stanza VALUES('I400','3','D''ngan Roh Kau mengurapiku,<br/>merawat lemahku;<br/>Oleh kuat-Mu ku dibantu,<br/>hingga ku kuat maju.<br/>',NULL,62185,4);
INSERT INTO stanza VALUES('I400','4','Hukum Roh dan hukum hayat<br/>membebaskan aku;<br/>Kelimpahan realitas-Mu<br/>penuhi diriku.<br/>',NULL,62186,5);
INSERT INTO stanza VALUES('I400','5','D''ngan ku Kau kekal bersatu,<br/>perpaduan yang suci;<br/>Kekal bersatu dalam roh,<br/>tak bercerai lagi.<br/>',NULL,62187,6);
INSERT INTO stanza VALUES('I400','6','Moga Kau p''nuhi p''losokku,<br/>s''mayam di hatiku;<br/>Tambah hari tambah mulia,<br/>ubahku seluruh.<br/>',NULL,62188,7);
INSERT INTO stanza VALUES('I401','1','Ku t''lah dapat kebebasan,<br/>Kristus t''lah bebaskanku!<br/>Kuasa dosa, sengat maut,<br/>atasku lucut luruh.<br/>',NULL,62189,1);
INSERT INTO stanza VALUES('I401','chorus','Menang mutlak oleh Kristus,<br/>salib kebanggaanku!<br/>Kuat hayat dan hukum Roh,<br/>membuatku kuat teguh.<br/>',NULL,62190,2);
INSERT INTO stanza VALUES('I401','2','Kristus membuatku terlepas,<br/>pun mati t''radap Taurat,<br/>Mutlak hidup dalam kurnia,<br/>bebas kekangan Taurat.<br/>',NULL,62191,3);
INSERT INTO stanza VALUES('I401','3','Kristus t''lah hakimi dosa,<br/>kuasa jahat terenyah,<br/>Atasku dosa tak daya,<br/>ku lepas dari dosa.<br/>',NULL,62192,4);
INSERT INTO stanza VALUES('I401','4','Kristus t''lah kalahkan maut,<br/>hayat kekal ternyata,<br/>Maut tak daya menahan<br/>kuasa kebangkitan.<br/>',NULL,62193,5);
INSERT INTO stanza VALUES('I401','5','Kristus t''lah hancurkan Iblis,<br/>hukum dunia, roh najis,<br/>Ku lepas gelap dan maut,<br/>masuk terang dan hayat.<br/>',NULL,62194,6);
INSERT INTO stanza VALUES('I401','6','Kurnia Kristus serba cukup,<br/>kuasa-Nya naungiku,<br/>Pun nyata atas lemahku,<br/>ku banggakan lemahku.<br/>',NULL,62195,7);
INSERT INTO stanza VALUES('I402','1','Bukan huruf Taurat,<br/>Tuhan-lah hayat,<br/>Allah menolongku,<br/>buang beban b''rat;<br/>Bukanlah ajaran<br/>melainkan Kristus,<br/>Hingga dosa,<br/>ego lepas dariku.<br/>',NULL,62196,1);
INSERT INTO stanza VALUES('I402','2','Liturgi apa pun<br/>atau ajaran,<br/>Tak hidupkan rohku,<br/>pun tak mengubah;<br/>Kristus-lah Sang Hayat,<br/>Pemberi-hayat,<br/>Allah ku wujudkan,<br/>turut murad-Nya.<br/>',NULL,62197,2);
INSERT INTO stanza VALUES('I402','3','Bukan teori filsuf<br/>atau logika,<br/>Dapat mewujudkan<br/>anggota Tubuh;<br/>Melainkan Kristus,<br/>atas diriku,<br/>Demi kuasa bangkit,<br/>jadikan Tubuh.<br/>',NULL,62198,3);
INSERT INTO stanza VALUES('I402','4','Ajaran Kristen pun<br/>tidaklah mampu,<br/>Menggenapkan tujuan<br/>dan maksud Allah;<br/>Kristus yang batini,<br/>s''gala-galaku,<br/>Genapkan murad-Nya,<br/>beres semuanya.<br/>',NULL,62199,4);
INSERT INTO stanza VALUES('I402','5','Karunia dan fungsi<br/>yang kita pangku,<br/>Semua tak dapat<br/>mengganti Kristus;<br/>Harus diri Kristus<br/>jadi s''galaku,<br/>Hanya diri Kristus<br/>yang aku perlu.<br/>',NULL,62200,5);
INSERT INTO stanza VALUES('I403','1','K''limpahan ilahi Tuhan,<br/>dalam tidak terduga;<br/>Kelimpahan sifat Allah,<br/>dalam Dia, ku nikmat s''mua.<br/>',NULL,62201,1);
INSERT INTO stanza VALUES('I403','chorus','Kelimpahan kudus mulia!<br/>Bagiku semuanya!<br/>Tak terbatas, tak terduga,<br/>namun itu realitas.<br/>',NULL,62202,2);
INSERT INTO stanza VALUES('I403','2','K''limpahan ilahi Tuhan,<br/>meliputi segala;<br/>Hayat, terang, hikmat, kuasa,<br/>sembuh, damai, dan riang.<br/>',NULL,62203,3);
INSERT INTO stanza VALUES('I403','3','Penebusan nan sempurna,<br/>benar, kudus, bebaskan;<br/>Kebangkitan, naik surga,<br/>Allah amat berkenan.<br/>',NULL,62204,4);
INSERT INTO stanza VALUES('I403','4','K''limpahan ilahi Tuhan,<br/>Allah jadi segala;<br/>Milik dan adanya Allah,<br/>dalam rohku terpaham.<br/>',NULL,62205,5);
INSERT INTO stanza VALUES('I403','5','K''limpahan ilahi Tuhan,<br/>siapa mampu terangkan?<br/>Panjang, lebar, tinggi,<br/>dalam, ku nikmati semua!<br/>',NULL,62206,6);
INSERT INTO stanza VALUES('I403','6','Moga ku kenal limpah-Nya,<br/>alami Kristus Allah;<br/>Saling membagikan nikmat,<br/>Allah puas, ku lega.<br/>',NULL,62207,7);
INSERT INTO stanza VALUES('I404','1','Dia pimpinku, o, manisnya!<br/>Penuhlah hiburan surga!<br/>Apa, kapan, mana saja,<br/>dipimpin oleh tangan-Nya.<br/>',NULL,62208,1);
INSERT INTO stanza VALUES('I404','chorus','Dia pimpinku, Dia pimpinku,<br/>tangan-Nya s''lalu pimpinku;<br/>Mutlak patuh, ku ikut t''rus,<br/>kar''na tangan-Nya pimpinku.<br/>',NULL,62209,2);
INSERT INTO stanza VALUES('I404','2','Kadang terasa derita,<br/>kadang terasa gembira;<br/>Lancar atau badai ombak,<br/>tetap dipimpin tangan-Nya.<br/>',NULL,62210,3);
INSERT INTO stanza VALUES('I404','3','Pegang erat, ya, Tuhan-ku,<br/>hidupku ikut Kau s''lalu;<br/>Bah''gia, susah, terserah-Mu,<br/>asal tangan-Mu pimpinku.<br/>',NULL,62211,4);
INSERT INTO stanza VALUES('I404','4','Saat usai tempuhanku,<br/>sandar kurnia menang unggul;<br/>Jelang maut, ku tak takut,<br/>kar''na tangan-Mu pimpinku.<br/>',NULL,62212,5);
INSERT INTO stanza VALUES('I405','1','Tuhan Sang Kasih,<br/>ku ta''u Kau milikku;<br/>S''mua nikmat dosa,<br/>ku buang demi Kau.<br/>Kau-lah Penolong,<br/>berdarah tebusku.<br/>Kalau ku cinta, ya,<br/>Tuhan, sekarang!<br/>',NULL,62213,1);
INSERT INTO stanza VALUES('I405','2','Dikau cintaku,<br/>ku cinta pada-Mu,<br/>Atas Golgota,<br/>tebusan Kau rampung,<br/>Mahkota duri<br/>Kau pakai untukku;<br/>Kalau ku cinta, ya,<br/>Tuhan, sekarang!<br/>',NULL,62214,2);
INSERT INTO stanza VALUES('I405','3','Hidup ku cinta,<br/>mati pun ku cinta;<br/>Memuji Dikau,<br/>asal Kau b''ri nafas,<br/>Ajal menimpa<br/>ku tetap bersikap;<br/>Kalau ku cinta, ya,<br/>Tuhan, sekarang!<br/>',NULL,62215,3);
INSERT INTO stanza VALUES('I405','4','Dalam mulia nan<br/>tiada hingganya,<br/>Dalam alam t''rang<br/>menyembah Kau s''lama.<br/>Pakai mahkota<br/>ku tetap bergita;<br/>Kalau ku cinta, ya,<br/>Tuhan, sekarang!<br/>',NULL,62216,4);
INSERT INTO stanza VALUES('I406','1','Bers''kutu indah,<br/>girang meluap,<br/>Damai dalam lengan kekal-Nya,<br/>Bah''gia sempurna,<br/>tent''ram raharja,<br/>Damai dalam lengan kekal-Nya.<br/>',NULL,62217,1);
INSERT INTO stanza VALUES('I406','chorus','Damai! Damai!<br/>Sejahtera tanpa gentar!<br/>Damai! Damai!<br/>Damai dalam lengan kekal-Nya!<br/>',NULL,62218,2);
INSERT INTO stanza VALUES('I406','2','Kami berjalan<br/>dengan sentosa,<br/>damai dalam lengan kekal-Nya;<br/>Sinar-Nya pancar,<br/>makinlah terang,<br/>damai dalam lengan kekal-Nya.<br/>',NULL,62219,3);
INSERT INTO stanza VALUES('I406','3','Apa ku takut?<br/>Apa ku gentar?<br/>Damai dalam lengan kekal-Nya;<br/>Hidup serta-Nya,<br/>makin sentosa,<br/>damai dalam lengan kekal-Nya.<br/>',NULL,62220,4);
INSERT INTO stanza VALUES('I407','1','Juru-s''lamat, mentariku,<br/>Kau serta, g''lap jadi terang,<br/>Jangan biarkan barang dunia,<br/>menutup wajah kasih-Mu.<br/>',NULL,62221,1);
INSERT INTO stanza VALUES('I407','2','Saat embun halus murni,<br/>segarkan mata yang letih,<br/>Moga angan malam hari,<br/>sandar dada-Nya abadi.<br/>',NULL,62222,2);
INSERT INTO stanza VALUES('I407','3','Serta ku sepanjang hari,<br/>tanpa-Mu hidup tak arti,<br/>Serta ku di malam hari,<br/>tanpa-Mu takut ''kan mati.<br/>',NULL,62223,3);
INSERT INTO stanza VALUES('I407','4','B''ri berkat, saat ku bangun,<br/>papahku menempuh hidup,<br/>Hingga hari di sisi-Mu,<br/>lebur di dalam kasih-Mu.<br/>',NULL,62224,4);
INSERT INTO stanza VALUES('I408','1','Harum nama-Mu, segar kasih-Mu,<br/>bila Kau tarik, siapa tak ikut?<br/>Kawanan domba kami ikuti,<br/>pasti masuk persekutuan kasih.<br/>',NULL,62225,1);
INSERT INTO stanza VALUES('I408','2','Dia pujaanku, ku juita-Nya,<br/>Dia menarikku, ku mengejar-Nya,<br/>P''ri mur sedap-Nya, simpan di manah,<br/>elok p''ri tabo, ''tiasa ku semat.<br/>',NULL,62226,2);
INSERT INTO stanza VALUES('I408','3','Masuk kasih-Nya, nikmat limpah-Nya,<br/>sandar ribaan-Nya, kecap manis-Nya;<br/>Panji kasih-Nya beri naungan;<br/>cinta kasih-Nya nyamankan manah.<br/>',NULL,62227,3);
INSERT INTO stanza VALUES('I408','4','Dia milikku, aku milik-Nya,<br/>Dia Gembalaku, aku bakung-Nya.<br/>Fajar, datanglah, biar gelap sirna;<br/>nampak muncul-Nya p''ri rusa fajar.<br/>',NULL,62228,4);
INSERT INTO stanza VALUES('I408','5','Wangi maut dan kebangkitan-Nya,<br/>asapiku ''tuk apresiasi-Nya;<br/>Angin kidul, angin lor, hembuslah,<br/>agar hatiku jadi taman-Nya.<br/>',NULL,62229,5);
INSERT INTO stanza VALUES('I408','6','Dalam pandang-Nya ku p''ri merpati,<br/>pula bersih s''perti bakung putih;<br/>Aku milik-Nya, kegemaran-Nya,<br/>Dia milikku, kidung agungku.<br/>',NULL,62230,6);
INSERT INTO stanza VALUES('I408','7','Elok p''ri candra, tampil gambar-Nya;<br/>suci p''ri surya, tampil awak-Nya,<br/>Semua bagi ekspresi hayat-Nya,<br/>semua bagilah puas hati-Nya.<br/>',NULL,62231,7);
INSERT INTO stanza VALUES('I408','8','Dikau hayatku, aku wujud-Mu;<br/>esanya kasih, teguh p''ri maut,<br/>Tak mungkin lenyap, tak mungkin ulah,<br/>hingga di gunung rempah Kau nyata.<br/>',NULL,62232,8);
INSERT INTO stanza VALUES('I409','1','Satu Kawanku akrab,<br/>ku teramat sayang;<br/>Lemah lembutlah sikap-Nya,<br/>manislah cinta-Nya;<br/>Mustahil hidup tanpa Dia,<br/>papah-Nya ku harap;<br/>Kita tinggal bersama,<br/>Tuhan dan ku.<br/>',NULL,62233,1);
INSERT INTO stanza VALUES('I409','2','Kadang ku nyaris rebah,<br/>lemahku Dia paham;<br/>Disuruh-Nya ku sandar Dia,<br/>ku suka rangkul-Nya;<br/>Ke arah t''rang ku Dia bawa,<br/>''nempuh hidup cerah;<br/>Kita jalan searah,<br/>Tuhan dan ku.<br/>',NULL,62234,2);
INSERT INTO stanza VALUES('I409','3','Kasihku terhadap-Nya,<br/>Dia palinglah jelas;<br/>Namun padaku kasih-Nya,<br/>tak habis ku kata;<br/>Kasih-Nya tak pernah padam,<br/>kian hari kian bara;<br/>Kita salinglah cinta,<br/>Tuhan dan ku.<br/>',NULL,62235,3);
INSERT INTO stanza VALUES('I409','4','Semua suka dukaku,<br/>ku b''ri ta''u pada-Nya;<br/>Semua rindu dambaku,<br/>ku ungkap pada-Nya;<br/>Hibur, anjur, amanat-Nya,<br/>Dia beri padaku;<br/>Kita saling bercakap,<br/>Tuhan dan ku.<br/>',NULL,62236,4);
INSERT INTO stanza VALUES('I409','5','Dia ta''u hatiku damba,<br/>meny''lamatkan jiwa;<br/>Disuruh-Nya aku keluar,<br/>wartakan kasih-Nya;<br/>Siarkan cinta ajaib-Nya,<br/>dan kisah wafat-Nya;<br/>Kita berdua ''tiasa,<br/>Tuhan dan ku.<br/>',NULL,62237,5);
INSERT INTO stanza VALUES('I409','6','Dia memberitahukan,<br/>tak jauhlah K''rajaan-Nya;<br/>Hati-Nya sangat mendesak,<br/>bawa ku ke sana;<br/>Bah''gia kekal, riang gembira,<br/>dan takhta mulia;<br/>Kita sama meraja,<br/>Tuhan dan ku.<br/>',NULL,62238,6);
INSERT INTO stanza VALUES('I410','1','O, Kristus dalam mulia,<br/>menerangi hatiku;<br/>Terang lebihi mentari,<br/>bukan p''ri cah''ya bintang.<br/>S''luruh bumi gelap,<br/>kelam, tak dapat memikatku;<br/>Hanya tempuh jalan sempit,<br/>patut hatiku damba.<br/>',NULL,62239,1);
INSERT INTO stanza VALUES('I410','2','Orang sandar terang dunia,<br/>tempuh hidup derita,<br/>Aku nampak terang surga,<br/>sorot terang benderang.<br/>Tidak buram, tidak pudar,<br/>tatap wajah mulia-Nya,<br/>Dan kasih-Nya nan mustika,<br/>kepenuhan kurnia-Nya.<br/>',NULL,62240,2);
INSERT INTO stanza VALUES('I410','3','Nampak mulia-Nya nan ajaib,<br/>kasih-Nya lebih ajaib;<br/>Bagiku Dia t''lah dapatkan,<br/>tumpuan unggul kekal.<br/>S''lubung singkap - tak sekejap;<br/>tinggal di balik tirai;<br/>Selama pandang wajah-Nya,<br/>dengar perkataan indah.<br/>',NULL,62241,3);
INSERT INTO stanza VALUES('I410','4','Nampak wajah Kristus mulia,<br/>lain tidak ku minta,<br/>Dengar firman kasih kurnia,<br/>cukuplah puaskanku.<br/>Oleh cahaya mulia-Nya,<br/>wajah mulia ku nampak,<br/>Mulia ini ''kan menjadi<br/>tempat tinggalku s''lama.<br/>',NULL,62242,4);
INSERT INTO stanza VALUES('I411','1','Surya terb''nam di Barat,<br/>tugas usai tenanglah;<br/>Bintang malam gemerlap,<br/>hampir Tuhan, roh segar;<br/>Sujud sembah.<br/>',NULL,62243,1);
INSERT INTO stanza VALUES('I411','chorus','Dekat, dekat,<br/>dekat, dekat Tuhan!<br/>Hati damba, roh ''nuntut,<br/>diri Tuhan nan elok,<br/>Tuhan mesra.<br/>',NULL,62244,2);
INSERT INTO stanza VALUES('I411','2','Dalam alam semesta,<br/>hatiku dambakan-Mu,<br/>Moga sekelilingku,<br/>pancar terang mulia-Mu,<br/>Puas aku.<br/>',NULL,62245,3);
INSERT INTO stanza VALUES('I411','3','Saat malam kian larut,<br/>hati damba kian rajin,<br/>Tembus semua bintang,<br/>pandang-Mu, beserta-Mu,<br/>D''rita pupus.<br/>',NULL,62246,4);
INSERT INTO stanza VALUES('I411','4','Hingga malam dan bintang,<br/>dari depanku lewat;<br/>Moga fajar nan kekal,<br/>bawakan Kau nan mulia,<br/>Bayang sirna.<br/>',NULL,62247,5);
INSERT INTO stanza VALUES('I412','1','Demi iman menjamah-Mu,<br/>Tuhan sumber suplaiku;<br/>Demi iman terap kuasa,<br/>lewat darah adi-Mu.<br/>',NULL,62248,1);
INSERT INTO stanza VALUES('I412','chorus','Jamah, t''rima suplai hayat,<br/>lewat gerakan Roh-Mu;<br/>Murnikan serta penuhi,<br/>limpah-Mu ku nikmati.<br/>',NULL,62249,2);
INSERT INTO stanza VALUES('I412','2','Demi iman, jamah, terap,<br/>t''rima limpah kaya-Mu;<br/>Ku terbuka kepada-Mu,<br/>Kau beri s''mua ada-Mu.<br/>',NULL,62250,3);
INSERT INTO stanza VALUES('I412','3','Jamah Tuhan makin dalam,<br/>jamah, terap limpah-Mu;<br/>T''rima kurnia, tambah kurnia,<br/>mengalirkan hayat-Mu.<br/>',NULL,62251,4);
INSERT INTO stanza VALUES('I412','4','Kuat, hikmat, kasih, kurnia,<br/>Kau suplai s''mua perluku;<br/>Hingga aku jamah, terap,<br/>senantiasa tak putus.<br/>',NULL,62252,5);
INSERT INTO stanza VALUES('I413','1','Tiada suara pecah sunyi,<br/>tiada jejak usik situasi,<br/>Hanya ada Dia yang elok anggun,<br/>dan suara-Nya nan lembut.<br/>',NULL,62253,1);
INSERT INTO stanza VALUES('I413','chorus','Juru selamat mustika, Yesus,<br/>sudilah beritahuku:<br/>Mengapa dan bagaimana Dikau<br/>diam hening di surga?<br/>',NULL,62254,2);
INSERT INTO stanza VALUES('I413','2','Tengah sunyi Dia tiba,<br/>hatiku dibisik-Nya mesra,<br/>Dalam mahligai, curah hati-Nya,<br/>padaku jatuh cinta.<br/>',NULL,62255,3);
INSERT INTO stanza VALUES('I413','3','Situasi kudus surga,<br/>hening tenang tabu suara,<br/>Ku senang dekat, ingin ku sesap,<br/>kasih-Mu wujud nyata.<br/>',NULL,62256,4);
INSERT INTO stanza VALUES('I413','4','Dalam tenang sujud sembah,<br/>aku tak berani bergerak,<br/>Jangan sampai aku kehilangan,<br/>rayuan dan kasih-Mu.<br/>',NULL,62257,5);
INSERT INTO stanza VALUES('I413','5','Jiwa lega, hati puas,<br/>tercapai puncak sukacita,<br/>Nyaman di ribaan Juru-s''lamat,<br/>tatap wajah elok-Nya.<br/>',NULL,62258,6);
INSERT INTO stanza VALUES('I414','1','Masuk tirai, wajib keluar kemah,<br/>Kecap surga, wajib buang dunia;<br/>Ku t''lah dipuaskan Sang Mahakudus,<br/>Sia-sia, apa bisa menipuku?<br/>',NULL,62259,1);
INSERT INTO stanza VALUES('I414','2','Masuk tirai, pasti keluar kemah,<br/>Surga serta, pasti lepas dunia;<br/>Jika mulia surga menarikku,<br/>dapatkah s''nang dunia dudukiku?<br/>',NULL,62260,2);
INSERT INTO stanza VALUES('I414','3','Masuk tirai, pandang mulia Kristus,<br/>Keluar kemah, ikut jejak Yesus;<br/>Jika mahkota, takhta kuasaiku,<br/>Malaf, salib tak membuatku ragu.<br/>',NULL,62261,3);
INSERT INTO stanza VALUES('I414','4','Masuk tirai, hirup kuasa bangkit,<br/>Keluar kemah, tempuh jalan salib,<br/>Jika ku nampak wajah mulia-Nya,<br/>Pasti rela ikuti langkah-Nya.<br/>',NULL,62262,4);
INSERT INTO stanza VALUES('I414','5','Masuk tirai, nikmat limpah surga,<br/>Keluar kemah, tahan d''rita dunia;<br/>Meski d''rita dunia sakitiku,<br/>Persekutuan surga hiburku.<br/>',NULL,62263,5);
INSERT INTO stanza VALUES('I414','6','Masuk tirai, nikmat kaya Kristus,<br/>Keluar kemah, suplai keperluan;<br/>Hayat surgawi hidup lewatku,<br/>Banyak jiwa selamat olehku.<br/>',NULL,62264,6);
INSERT INTO stanza VALUES('I414','7','Masuk tirai, hingga tirai lenyap,<br/>Keluar kemah, hingga kemah sirna;<br/>Sampai surga dan bumi esalah,<br/>Allah - manusia, kekal tak pisah.<br/>',NULL,62265,7);
INSERT INTO stanza VALUES('I415','1','Di dalam penyertaan-Nya,<br/>ku diam tent''ram, nyaman!<br/>Di depan-Nya ''tiasa sujud,<br/>t''rima ajaran indah!<br/>Kuatir tak dapat gangguku,<br/>ujian bukan tekanan,<br/>Tiap kali Iblis menggoda,<br/>ku masuk hadirat-Nya,<br/>Ku masuk hadirat-Nya.<br/>',NULL,62266,1);
INSERT INTO stanza VALUES('I415','2','Saat ku letih dan dah''ga,<br/>naung bawah sayap-Nya,<br/>Ku tertudung, sejuk, riang,<br/>sumber hidup nan segar;<br/>Rebah di pelukan Tuhan,<br/>saling sekutu mesra,<br/>Meski kecap, tak terkata,<br/>firman-Nya nan rahasia,<br/>Firman-Nya nan rahasia.<br/>',NULL,62267,2);
INSERT INTO stanza VALUES('I415','3','Tapi ku tahu satu hal,<br/>saat ''ngeluh pada-Nya,<br/>Dia mendengar dengan sabar,<br/>bahkan beri dorongan,<br/>Tak pernahkah Dia menegur?<br/>Tentu Dia pura-pura,<br/>Kalau Dia tidak pernah<br/>tegur dosa yang tampak,<br/>Tegur dosa yang tampak.<br/>',NULL,62268,3);
INSERT INTO stanza VALUES('I415','4','Sertaan-Nya sungguh indah,<br/>bila engkau mau tahu,<br/>Tinggallah dalam naungan-Nya,<br/>pasti merasakannya,<br/>Rohmu sekutu dengan-Nya,<br/>tenang dalam terang-Nya,<br/>Wajah-Mu pasti pantulkan<br/>gambar-Nya yang mulia,<br/>Gambar-Nya yang mulia.<br/>',NULL,62269,4);
INSERT INTO stanza VALUES('I416','1','Aku telah percaya, wafat-Nya ku terima;<br/>P''lataran ku lalui, haleluya, puji Dia!<br/>Demi darah adi-Nya, ku jadi milik Allah,<br/>Tak lagi dalam dosa, haleluya, puji Dia!<br/>',NULL,62270,1);
INSERT INTO stanza VALUES('I416','chorus','Haleluya! Haleluya!<br/>Tirai terb''lah, ku masuk,<br/>mulianya tak terhingga!<br/>Haleluya! Haleluya!<br/>Kini ku hidup di depan Sang Raja!<br/>',NULL,62271,2);
INSERT INTO stanza VALUES('I416','2','Tirai luar ku tembus,<br/>masuk ke tempat kudus,<br/>Ku mendapat suplai-Nya,<br/>haleluya, puji Dia!<br/>Ku damai dengan Allah,<br/>tersisih demi mezbah,<br/>Selain Allah ku tolak,<br/>haleluya, puji Dia!<br/>',NULL,62272,3);
INSERT INTO stanza VALUES('I416','3','Tirai dalam ku tembus,<br/>ke tempat mahakudus,<br/>Takhta rahmat ku dekat,<br/>haleluya, puji Dia!<br/>Depan Allah ku hidup,<br/>semayam di dalam-Nya,<br/>Sirna semua sekatan,<br/>haleluya, puji Dia!<br/>',NULL,62273,4);
INSERT INTO stanza VALUES('I416','4','Ku jadi imam Allah,<br/>karena tebusan-Nya,<br/>Ini betapa mulia,<br/>haleluya, puji Dia!<br/>Di dalam roh ku kini<br/>hidup depan mulia-Nya,<br/>Siang malam tak bersekat,<br/>haleluya, puji Dia!<br/>',NULL,62274,5);
INSERT INTO stanza VALUES('I417','1','Pagi subuh, remang buta,<br/>kembali ku hampiri Dia;<br/>Cah''ya mulia-Nya memancar,<br/>nampaklah wajah mulia-Nya.<br/>Terdengar tutur kata-Nya,<br/>"Hari ini limpah sedia!" Nyaman, girang,<br/>Dia ku nikmat,<br/>semua lapar jadi kenyang!<br/>',NULL,62275,1);
INSERT INTO stanza VALUES('I417','2','Bermunajat demi firman,<br/>hatiku gemakan pujian,<br/>Sumber hayat, bawa t''naga,<br/>di dalamku ''ngalir deras.<br/>Terdengar tutur kata-Nya,<br/>"Hari ini limpah sedia!"<br/>Sejuk, sedap, Dia ku sesap,<br/>semua dah''ga lenyap sirna!<br/>',NULL,62276,2);
INSERT INTO stanza VALUES('I417','3','Bila ku tatap wajah-Nya,<br/>koreksi-Nya amat mesra,<br/>Kadar mulia ilahi-Nya,<br/>jenuhi, suplai tak batas.<br/>Terdengar tutur kata-Nya,<br/>"Hari ini limpah sedia!"<br/>Nikmat aneka kaya-Nya,<br/>semua soal beres sudah!<br/>',NULL,62277,3);
INSERT INTO stanza VALUES('I418','1','Tinggal dalam-Nya,<br/>bahagia amat,<br/>Sekutu d''ngan-Nya,<br/>alangkah mesra;<br/>Tinggal dalam-Nya,<br/>berpadu esa,<br/>Sekutu d''ngan-Nya,<br/>lenyap sekatan.<br/>',NULL,62278,1);
INSERT INTO stanza VALUES('I418','2','Tinggal dalam-Nya,<br/>minyak berperan,<br/>Sekutu d''ngan-Nya,<br/>Roh-Nya memapah;<br/>Taati minyak,<br/>nikmat limpah-Nya,<br/>Ikut Roh Kudus,<br/>jadi teman-Nya.<br/>',NULL,62279,2);
INSERT INTO stanza VALUES('I418','3','Tinggal dalam-Nya,<br/>terang mencorong,<br/>Sekutu d''ngan-Nya,<br/>gelap sg''ra sirna,<br/>Patuh terang-Nya,<br/>tumbuhlah hayat,<br/>S''mua gelap sirna,<br/>hati pun lega.<br/>',NULL,62280,3);
INSERT INTO stanza VALUES('I418','4','Tinggal dalam-Nya,<br/>lemah jadi kuat,<br/>Sekutu d''ngan-Nya,<br/>maut tertelan;<br/>Tinggal dalam-Nya,<br/>keluh jadi riang,<br/>Sekutu d''ngan-Nya,<br/>gita melantang.<br/>',NULL,62281,4);
INSERT INTO stanza VALUES('I418','5','Tinggal dalam-Nya,<br/>serupa d''ngan Dia,<br/>Sekutu d''ngan-Nya,<br/>dunia pudar;<br/>Tinggal dalam-Nya,<br/>dosa tak kuasa,<br/>Sekutu d''ngan-Nya,<br/>ego terhempas.<br/>',NULL,62282,5);
INSERT INTO stanza VALUES('I418','6','Tinggal dalam-Nya,<br/>serupa d''ngan Dia,<br/>Sekutu d''ngan-Nya,<br/>penuh hayat-Nya;<br/>Tinggal dalam-Nya,<br/>''nempuh kuasa-Nya,<br/>Sekutu d''ngan-Nya,<br/>sesap limpah-Nya.<br/>',NULL,62283,6);
INSERT INTO stanza VALUES('I418','7','Tinggal dalam-Nya,<br/>hati, roh, damba,<br/>Sekutu d''ngan-Nya,<br/>Sang Roh mendorong;<br/>Moga dalam-Nya<br/>mutlak tercelup,<br/>Sampai kekal baur<br/>esa dengan-Nya.<br/>',NULL,62284,7);
INSERT INTO stanza VALUES('I419','1','Tuhan, Engkau pokok pohon,<br/>aku ini ranting-Mu;<br/>Tapi ku tak ta''u mengapa,<br/>aku tak pernah berbuah.<br/>',NULL,62285,1);
INSERT INTO stanza VALUES('I419','2','Aku ingin berbuah lebat,<br/>ekspresikan hayat-Mu;<br/>Lebih permuliakan takhta,<br/>berdoa makin mampu.<br/>',NULL,62286,2);
INSERT INTO stanza VALUES('I419','3','Tuhan, aku tidak paham,<br/>makna "tinggal dalam-Mu";<br/>Makin aku giat menuntut,<br/>makin rasa di luar.<br/>',NULL,62287,3);
INSERT INTO stanza VALUES('I419','4','Ku tak merasa "di dalam",<br/>ku berdoa dan bertekad;<br/>Tapi terasa Kau jauh,<br/>hidupku tetap mandul.<br/>',NULL,62288,4);
INSERT INTO stanza VALUES('I419','5','Tuhan, Engkau pokok pohon,<br/>aku ini ranting-Mu;<br/>Saat ku t''rima diri-Mu,<br/>diriilkan Roh Kudus.<br/>',NULL,62289,5);
INSERT INTO stanza VALUES('I419','6','Kini aku di dalam-Mu,<br/>tak lagi minta masuk;<br/>Dengan Tuhan ku bersatu,<br/>jadi satu nan utuh.<br/>',NULL,62290,6);
INSERT INTO stanza VALUES('I419','7','Rah''sianya bukan "mau masuk",<br/>melainkan "sudah masuk";<br/>Kini yang ku mohon s''lalu:<br/>teguh diam di tempatku.<br/>',NULL,62291,7);
INSERT INTO stanza VALUES('I419','8','Aku sudah di dalam-Mu!<br/>Inilah karya Allah;<br/>Tak perlu doa, tindakku,<br/>s''mua dibuat tangan Allah.<br/>',NULL,62292,8);
INSERT INTO stanza VALUES('I419','9','T''lah di dalam, ingin masuk,<br/>sungguh bodohlah aku;<br/>Kini ku hanya memuji,<br/>percaya firman suci.<br/>',NULL,62293,9);
INSERT INTO stanza VALUES('I419','10','Kini ku mutlak mengaso,<br/>kar''na ta''u Kau s''galaku;<br/>Kau-lah hayat pun tenaga,<br/>s''galaku sudah tamat.<br/>',NULL,62294,10);
INSERT INTO stanza VALUES('I420','1','Tinggal dalam-Mu, ''nilah minatku,<br/>Tinggal dalam-Mu, tanpa sekatan;<br/>P''ri ranting lekat di pokok anggur,<br/>Ku mau tinggal di dalam-Mu s''lalu.<br/>',NULL,62295,1);
INSERT INTO stanza VALUES('I420','2','Tinggal dalam-Mu, nikmat limpah-Mu,<br/>Semua ada-Mu salur lewatku;<br/>Ku mau menjadi ranting segar-Mu,<br/>Wujudkan hayat, berbuah terus.<br/>',NULL,62296,2);
INSERT INTO stanza VALUES('I420','3','Tinggal dalam-Mu, dosa tak daya,<br/>Hayat batini tak terkalahkan;<br/>Padu dengan-Mu, sekutu mesra,<br/>Roh mengendali seluruh jiwa.<br/>',NULL,62297,3);
INSERT INTO stanza VALUES('I420','4','Tinggal dalam-Mu, tahu murad-Mu,<br/>Jamah hadir-Mu, masuk rah''sia-Mu;<br/>Riang dan damai penuhi aku,<br/>Suplai firman-Mu itu kuatku.<br/>',NULL,62298,4);
INSERT INTO stanza VALUES('I421','1','Tanpa Kau ku tak mampu,<br/>berpikir, berdiri,<br/>Ku tak punya tenaga,<br/>kebaikan, dan hikmat;<br/>Tuhan, Juru-s''lamatku,<br/>segala-galaku,<br/>Lemah menjadi berkat,<br/>bila Kau menunjang.<br/>',NULL,62299,1);
INSERT INTO stanza VALUES('I421','2','Berpikir ku tak bisa,<br/>jalan ini panjang,<br/>Ku letih, lesu, lemah,<br/>keluh ganti pujian;<br/>Ku tak dapat tanpa Kau,<br/>ku tak tahu jalan,<br/>Justru Kau paham jalan,<br/>ku takkan tersesat.<br/>',NULL,62300,2);
INSERT INTO stanza VALUES('I421','3','Berpikir ku tak bisa,<br/>Yesus Juru-s''lamat,<br/>Walau ku tak melihat,<br/>Engkau tetap serta;<br/>Sungguh senyap dan duka,<br/>hidup perantauan,<br/>Jika tiada sekutu,<br/>dan perhentian-Mu.<br/>',NULL,62301,3);
INSERT INTO stanza VALUES('I421','4','Berpikir ku tak bisa,<br/>tiada yang mengenal,<br/>Minat roh dalam nian,<br/>perlu Kau bukakan;<br/>Pelosok batiniah,<br/>siapa mampu selam?<br/>Hibur, teduh, amanat,<br/>Kau saja yang dapat.<br/>',NULL,62302,4);
INSERT INTO stanza VALUES('I421','5','Berpikir ku tak bisa,<br/>hari sisa s''dikit,<br/>Ku wajib s''perti yang lain,<br/>juga menyeb''rangi,<br/>Dikau beserta s''lama,<br/>tak peduli ombak,<br/>Kasih-Mu tidak pudar,<br/>bisik-Mu tenangkan.<br/>',NULL,62303,5);
INSERT INTO stanza VALUES('I422','1','Di surga ku ada siapa? Hanyalah, diri-Mu!<br/>Seumurku ku nyanyikan: Tuhan-ku bagiku!<br/>Dia mend''rita dan berdarah, jadi Domba Penebusku,<br/>Hingga ku damai d''ngan Allah, Tuhan-ku, bagiku!<br/>',NULL,62304,1);
INSERT INTO stanza VALUES('I422','2','Ku tak nuntut bah''gia diri, ku mau, Tuhan-ku!<br/>Ku tak damba mewah dunia, ku mau, Tuhan-ku!<br/>Bah''gia diri, mewah dunia, itu hanya sementara,<br/>Riang hatiku hingga kekal, ku mau, Tuhan-ku!<br/>',NULL,62305,2);
INSERT INTO stanza VALUES('I422','3','Ku buang angan tamak dunia, Tuhan-ku, bagiku!<br/>Ku tak harap hidup nyaman, Tuhan-ku, bagiku!<br/>Meski pohon-pohon ara, anggur, zaitun, tak berbuah,<br/>Tiada lembu, tiada domba, Tuhan-ku, bagiku!<br/>',NULL,62306,3);
INSERT INTO stanza VALUES('I422','4','Kini hatiku damailah, Tuhan-ku, bagiku!<br/>Ku tak takut ujian apa, Tuhan-ku, bagiku!<br/>Meski godaan menggebu, sandar Tuhan ku kuat teguh,<br/>Semua godaan ''kan lalu, Tuhan-ku bagiku!<br/>',NULL,62307,4);
INSERT INTO stanza VALUES('I422','5','Saat usai tempuhanku, ku mau, Tuhan-ku!<br/>Tent''ram bersandar lengan-Nya, ku mau, Tuhan-ku!<br/>Meski kini ada d''rita, s''mua tenaga hilang sirna,<br/>Ku ''kan tetap nyanyi lantang: ku mau, Tuhan-ku!<br/>',NULL,62308,5);
INSERT INTO stanza VALUES('I423','1','Tekad rapuh, t''naga lemah,<br/>harapanku punah sudah;<br/>Hanya sandar garapan-Nya,<br/>lembut, mesra ku dipapah.<br/>',NULL,62309,1);
INSERT INTO stanza VALUES('I423','2','Aku sudah berusaha,<br/>tapi gagal, s''lalu gagal;<br/>Oleh sabar-Mu ''tiasa,<br/>hingga suara-Mu terdengar.<br/>',NULL,62310,2);
INSERT INTO stanza VALUES('I423','3','Waktu hati agak bangga,<br/>nyaris aku terjerembab;<br/>Ku tak b''rani apa-apa,<br/>ku perlu Kau dalam s''gala.<br/>',NULL,62311,3);
INSERT INTO stanza VALUES('I423','4','Ya, P''nolongku yang perkasa,<br/>kini ku pandang wajah-Mu;<br/>Aku orang yang terlemah,<br/>t''nagaku itu kurnia-Mu.<br/>',NULL,62312,4);
INSERT INTO stanza VALUES('I424','1','Pada-Mu hati lega,<br/>sabat yang sejati!<br/>Selain ini, Yesus,<br/>apa harapanku?<br/>Terang-Mu-lah hikmatku,<br/>kasih-Mu dorongku;<br/>Dalam posisi mulia,<br/>Kau pimpinku maju.<br/>',NULL,62313,1);
INSERT INTO stanza VALUES('I424','2','Meski dosaku besar,<br/>kurnia lebih besar;<br/>Kau Domba untuk kurban,<br/>wafat-Mu bebaskan;<br/>Ku lepas dari dosa,<br/>pula terpulihkan;<br/>Firman-Mu sorot terang,<br/>darah-Mu mustika.<br/>',NULL,62314,2);
INSERT INTO stanza VALUES('I424','3','Tuhan lembut,<br/>tujuan-Mu tergenap dariku;<br/>Untuk capai murad-Mu,<br/>hidup s''rah pada-Mu.<br/>Meski ku sangat lemah,<br/>namun Kau perkasa,<br/>Umat-Mu berk''limpahan,<br/>bila Kau miliknya.<br/>',NULL,62315,3);
INSERT INTO stanza VALUES('I424','4','Saat awan g''lap tudungku,<br/>Kau justru dekatku,<br/>Hingga imanku teguh,<br/>ajar rohku kukuh.<br/>Ribaan-Mu ku rebah,<br/>tatap wajah mulia,<br/>Kau tempat perhentianku,<br/>Iblis langkah s''ribu.<br/>',NULL,62316,4);
INSERT INTO stanza VALUES('I424','5','Kau membuatku girang,<br/>orak s''mua ikatan,<br/>Ku mau sembahkan pujian,<br/>sampai selamanya.<br/>Senang, kasih dunia,<br/>seg''ra kering asat,<br/>Kurnia-Mu suplai ''tiasa,<br/>semua beres sudah.<br/>',NULL,62317,5);
INSERT INTO stanza VALUES('I425','1','Ku bejana ciptaan,<br/>Kristus mulia di dalam;<br/>Wajib jadi wadah-Nya<br/>yang berisikan Tuhan.<br/>',NULL,62318,1);
INSERT INTO stanza VALUES('I425','2','Tercipta serupa Dia,<br/>layak Kristus semayam;<br/>Bentuk wadah dibuat,<br/>serasi d''ngan isinya.<br/>',NULL,62319,2);
INSERT INTO stanza VALUES('I425','3','Di rohku Dia semayam,<br/>kuat kuasa-Nya menunjang;<br/>Satu roh ku dengan Dia,<br/>t''rima suplai riil-Nya.<br/>',NULL,62320,3);
INSERT INTO stanza VALUES('I425','4','Di batin b''ri dorongan,<br/>baur, sekutu ''tiasa;<br/>Tiap langkah Dia jaga,<br/>tiap bagian Dia resap.<br/>',NULL,62321,4);
INSERT INTO stanza VALUES('I425','5','Ingin wujudkan Dia,<br/>biar orang lain nampak;<br/>Harus bening dan cerah,<br/>baru Dia nyata bulat.<br/>',NULL,62322,5);
INSERT INTO stanza VALUES('I425','6','Ubah aku butuhkan,<br/>diri remuk tak sisa;<br/>Tanah jadi permata,<br/>ganti corak mustika.<br/>',NULL,62323,6);
INSERT INTO stanza VALUES('I426','1','Jalan serta Tuhan,<br/>dalam t''rang firman-Nya,<br/>cah''ya mulia-Nya t''rus memancar;<br/>Ku taat p''rintah-Nya,<br/>hatiku penuhlah,<br/>penuh dengan kelimpahan-Nya.<br/>',NULL,62324,1);
INSERT INTO stanza VALUES('I426','chorus','Percayalah<br/>dengan hati taat,<br/>Kar''na Tuhan ''kan cinta<br/>pada yang demikian!<br/>',NULL,62325,2);
INSERT INTO stanza VALUES('I426','2','Tiada awan gelap,<br/>tiada bayang kelam,<br/>yang dapat menutup senyum-Nya;<br/>Tiada hati tawar,<br/>tiada air mata,<br/>bila ku taat dan percaya.<br/>',NULL,62326,3);
INSERT INTO stanza VALUES('I426','3','Tiada pikulan b''rat,<br/>tiada susah c''laka,<br/>yang menyerang, kar''na Dia jaga;<br/>Semua rugi susah,<br/>semua hina nista,<br/>jadi berkat bila mau taat.<br/>',NULL,62327,4);
INSERT INTO stanza VALUES('I426','4','Tapi ku tak paham,<br/>kasih-Nya yang indah;<br/>bila aku belum di mezbah;<br/>Tuhan b''rikan senang,<br/>dan kidung pujian;<br/>bila ku taat dan percaya.<br/>',NULL,62328,5);
INSERT INTO stanza VALUES('I426','5','Di dalam terang-Nya,<br/>bersekutu mesra;<br/>ku melangkah maju serta-Nya;<br/>Dia minta ku rela,<br/>Dia utus ku b''rangkat;<br/>pastilah Tuhan-ku berkenan.<br/>',NULL,62329,6);
INSERT INTO stanza VALUES('I427','1','Ku dengar panggilan Tuhan,<br/>ku dengar panggilan Tuhan,<br/>Ku dengar panggilan Tuhan,<br/>"Hai marilah, ikut pada-Ku!"<br/>',NULL,62330,1);
INSERT INTO stanza VALUES('I427','chorus','Biar di mana s''lalu ikut,<br/>kapan saja s''lalu ikut,<br/>Dalam senang atau susah,<br/>s''lalu ikut, ikut tak undur.<br/>',NULL,62331,2);
INSERT INTO stanza VALUES('I427','2','Ku jawab panggilan Tuhan,<br/>ku jawab panggilan Tuhan,<br/>Ku jawab panggilan Tuhan,<br/>"Seumurku ikut pada-Mu."<br/>',NULL,62332,3);
INSERT INTO stanza VALUES('I427','3','Ku tinggalkan bah''gia dunia,<br/>ku tinggalkan bah''gia dunia,<br/>Ku tinggalkan bah''gia dunia,<br/>seumurku ikut pada-Mu.<br/>',NULL,62333,4);
INSERT INTO stanza VALUES('I427','4','Ku rela memikul salib,<br/>ku rela memikul salib,<br/>Menempuh jalan yang sempit,<br/>seumurku ikut pada-Mu.<br/>',NULL,62334,5);
INSERT INTO stanza VALUES('I427','5','Terus maju tanpa ragu,<br/>terus maju tanpa ragu,<br/>Terus maju tanpa ragu,<br/>seumurku ikut pada-Mu.<br/>',NULL,62335,6);
INSERT INTO stanza VALUES('I428','1','Ikut Yesus sungguh manis,<br/>meski d''rita sek''liling;<br/>Ikut Yesus setiap hari,<br/>pada jalan yang sempit.<br/>',NULL,62336,1);
INSERT INTO stanza VALUES('I428','chorus','Setindak, setindak,<br/>ikut Yesus ''tiasa;<br/>Tiap tempat, tiap hari,<br/>pada jalan sempit.<br/>',NULL,62337,2);
INSERT INTO stanza VALUES('I428','2','Ikut Yesus sungguh nyaman,<br/>jabat erat tangan-Nya;<br/>Ikut Yesus ke mana pun,<br/>celaka tak mengganggu.<br/>',NULL,62338,3);
INSERT INTO stanza VALUES('I428','3','Aku s''lalu ikut Yesus,<br/>sejenak pun tak undur;<br/>Ke gunung tinggi ku tanjak,<br/>dengan Tuhan sejalan.<br/>',NULL,62339,4);
INSERT INTO stanza VALUES('I428','4','S''panjang hari ikut Yesus,<br/>hari c''rah mau pun redup;<br/>Jejak darah-Nya menuntun,<br/>aku mengikut Yesus.<br/>',NULL,62340,5);
INSERT INTO stanza VALUES('I428','5','Aku ikut Yesus s''lalu,<br/>meski malam melarut;<br/>Tak lama fajar merekah,<br/>hatiku amat girang.<br/>',NULL,62341,6);
INSERT INTO stanza VALUES('I428','6','Genap S''rani ikut Yesus,<br/>pada jalan yang kudus;<br/>Hilanglah semua yang murung,<br/>lenyaplah s''mua yang redup.<br/>',NULL,62342,7);
INSERT INTO stanza VALUES('I428','7','Tuhan jaga aku s''lalu,<br/>ikut Kau tiap waktu;<br/>Ikut jejak-Mu selalu,<br/>ke mana pun menuju.<br/>',NULL,62343,8);
INSERT INTO stanza VALUES('I429','1','"Keluar kemah" ke Yesus,<br/>tanggung kehinaan-Nya,<br/>Dia mend''rita di luar,<br/>apa ku ingin nyaman?<br/>',NULL,62344,1);
INSERT INTO stanza VALUES('I429','2','"Keluar kemah" ke Yesus,<br/>rela memikul salib,<br/>Dia tempuh jalan sempit,<br/>jejak-Nya ku ikuti.<br/>',NULL,62345,2);
INSERT INTO stanza VALUES('I429','3','"Keluar kemah" ke Yesus,<br/>tinggalkan sanak k''luarga,<br/>Peduli murad Bapa,<br/>tak terhalang manusia.<br/>',NULL,62346,3);
INSERT INTO stanza VALUES('I429','4','"Keluar kemah" ke Yesus,<br/>sebarisan dengan-Nya,<br/>Tak lagi jadi milik<br/>organisasi dunia.<br/>',NULL,62347,4);
INSERT INTO stanza VALUES('I429','5','"Keluar kemah" ke Yesus,<br/>meski orang menjauh,<br/>Jalan sunyi pun sepi,<br/>ada Dia sudah cukup.<br/>',NULL,62348,5);
INSERT INTO stanza VALUES('I429','6','"Keluar kemah" ke Yesus,<br/>serta Dia sungguh senang,<br/>Senyum-Nya mendorongku,<br/>tinggal bersama Dia.<br/>',NULL,62349,6);
INSERT INTO stanza VALUES('I429','7','"Keluar kemah" ke Yesus,<br/>sampai akhir tempuhan,<br/>Jumpa Dia dengan riang,<br/>masuk dalam k''rajaan.<br/>',NULL,62350,7);
INSERT INTO stanza VALUES('I430','1','Allah pilih dan tentukan,<br/>kaum terpanggil<br/>digarap serupa Putra-Nya.<br/>',NULL,62351,1);
INSERT INTO stanza VALUES('I430','chorus','Garap s''rupa Putra Allah!<br/>Garap s''rupa Putra Allah!<br/>Garap s''rupa Putra!<br/>',NULL,62352,2);
INSERT INTO stanza VALUES('I430','2','Berdasarkan diri Allah,<br/>Roh Kudus doa ''tuk kita,<br/>Garap s''rupa Putra.<br/>',NULL,62353,3);
INSERT INTO stanza VALUES('I430','3','Roh Kudus gerak di batin,<br/>pun mendisiplin di lahir,<br/>Garap s''rupa Putra.<br/>',NULL,62354,4);
INSERT INTO stanza VALUES('I430','4','Semua garapan Roh Kudus,<br/>bermaksud menggarap kita,<br/>S''rupa Putra Allah.<br/>',NULL,62355,5);
INSERT INTO stanza VALUES('I430','5','S''gala sesuatu bekerja,<br/>mendatangkan kebaikan,<br/>S''rupa Putra Allah.<br/>',NULL,62356,6);
INSERT INTO stanza VALUES('I430','6','Untuk dapat banyak putra,<br/>Allah harus merampungkan,<br/>Garap s''rupa Putra.<br/>',NULL,62357,7);
INSERT INTO stanza VALUES('I430','7','Untuk memuliakan kita,<br/>Allah harus mengerjakan,<br/>Garap s''rupa Putra.<br/>',NULL,62358,8);
INSERT INTO stanza VALUES('I430','8','Kasih Kristus tak terputus,<br/>agar ini kena jitu,<br/>Garap s''rupa Putra.<br/>',NULL,62359,9);
INSERT INTO stanza VALUES('I431','1','Lihat! Dari wadah tanah,<br/>kasih kurnia memancar,<br/>Pancar wajah Kristus mulia,<br/>dalam hati yang gundah.<br/>',NULL,62360,1);
INSERT INTO stanza VALUES('I431','2','Kristus, penuh terang surga,<br/>kini pancar di bumi,<br/>Roh hayat huni di hati,<br/>terangi tempat mati.<br/>',NULL,62361,2);
INSERT INTO stanza VALUES('I431','3','Dari terang surga mulia,<br/>wadah bawakan Allah,<br/>Diapresiasi manusia,<br/>lebih indah dan mesra.<br/>',NULL,62362,3);
INSERT INTO stanza VALUES('I431','4','Wadah tanah tak rupawan,<br/>tapi harta di batin,<br/>Pancar mulia, baru ''tiasa,<br/>harta kekal surgawi.<br/>',NULL,62363,4);
INSERT INTO stanza VALUES('I431','5','Lewat banyak zaman gersang,<br/>wadah tanah pun lemah,<br/>Namun tampung Putra Allah,<br/>wujud harta tak tara.<br/>',NULL,62364,5);
INSERT INTO stanza VALUES('I432','1','Diri Allah ''nyorot aku,<br/>lepas lama ganti baru,<br/>Orang lahir kian renta,<br/>orang batin baru ''tiasa.<br/>',NULL,62365,1);
INSERT INTO stanza VALUES('I432','chorus','Mustika dalam bejana,<br/>daya hebat ternyatalah,<br/>daya hebat ternyatalah.<br/>',NULL,62366,2);
INSERT INTO stanza VALUES('I432','2','Terkepung, tidak tertawan,<br/>teraniaya, tidak patah,<br/>Hati lara, tak kecewa,<br/>pukul jatuh tak binasa.<br/>',NULL,62367,3);
INSERT INTO stanza VALUES('I432','3','Maut Yesus bawa s''lalu,<br/>hayat Yesus nyata tentu;<br/>Maut gerak ''tas diriku,<br/>hayat segera terwujud.<br/>',NULL,62368,4);
INSERT INTO stanza VALUES('I432','4','Tuhan bangkit dari mati,<br/>aku hidup bersama-Nya;<br/>Orang lahir makin renta,<br/>orang batin baru ''tiasa!<br/>',NULL,62369,5);
INSERT INTO stanza VALUES('I432','5','Sementara d''rita susah,<br/>kelak mulia tak terhingga;<br/>Yang tertampak tak ku indah,<br/>yang tak tampak ku indahkan.<br/>',NULL,62370,6);
INSERT INTO stanza VALUES('I433','1','Bukan aku, melainkan Tuhan-ku,<br/>yang dicinta serta dimasyhurkan;<br/>Bukan aku, melainkan Tuhan-ku,<br/>nyata pada s''mua perbuatanku.<br/>',NULL,62371,1);
INSERT INTO stanza VALUES('I433','chorus','Tuhan, lenyapkanlah diriku,<br/>di dalam diri-Mu!<br/>Moga kini bukan aku,<br/>melainkan Tuhan-ku!<br/>',NULL,62372,2);
INSERT INTO stanza VALUES('I433','2','Bukan aku, melainkan Tuhan-ku,<br/>permulaan dan sumber suplaiku;<br/>Bukan aku,melainkan Tuhan-ku,<br/>yang bekerja dan menempuh hidup.<br/>',NULL,62373,3);
INSERT INTO stanza VALUES('I433','3','Bukan aku, melainkan Tuhan-ku,<br/>hingga kini tak bersungut lagi;<br/>Bukan aku, melainkan Tuhan-ku,<br/>hingga kini tak megahkan diri.<br/>',NULL,62374,4);
INSERT INTO stanza VALUES('I433','4','Bukan aku, melainkan Tuhan-ku,<br/>hingga kini tak lagi takabur;<br/>Bukan aku, melainkan Tuhan-ku,<br/>hingga kini tak lagi meragu.<br/>',NULL,62375,5);
INSERT INTO stanza VALUES('I433','5','Tuhan m''lulu, tampil depan mataku,<br/>indah, mulia, tak lama ''kan nyata;<br/>Tuhan m''lulu, pada-Nya ku bersyukur,<br/>Yesus Kristus, s''galaku yang kekal.<br/>',NULL,62376,6);
INSERT INTO stanza VALUES('I434','1','Ada mustika di surga,<br/>limpah, tidak terkisah,<br/>Kekal perkenan hati-Nya,<br/>Kristus Tuhan Sang Putra.<br/>Ada mustika di bumi,<br/>yang ta''u Allah sendiri;<br/>Kasih dalam tak terperi<br/>wahyu Kristus di hati.<br/>',NULL,62377,1);
INSERT INTO stanza VALUES('I434','2','Oleh lidah api tiba,<br/>kekal pakai tak asat,<br/>Mustika nan tak ternilai<br/>p''nuhi wadah pilihan.<br/>Allah, dari mulia surga,<br/>penuhi wadah ini,<br/>Demi kekayaan kasih,<br/>puaskan rindu hati.<br/>',NULL,62378,2);
INSERT INTO stanza VALUES('I434','3','Walau ada d''rita, coba,<br/>panggilan mulia tetap;<br/>Pokok, ranting saling lekat,<br/>tuang diri pada-Nya.<br/>Wadah tanah memang hina,<br/>lemah, miskin, dan dina,<br/>Berisi Allah - mustika,<br/>ekspresikan mulia-Nya.<br/>',NULL,62379,3);
INSERT INTO stanza VALUES('I434','4','Biarku makin hampa, rendah,<br/>tak dikenal, tak tenar,<br/>Wadah makin kudus, indah,<br/>penuh terang mulia-Nya!<br/>Tak tertutup, terang mulia,<br/>oleh apa pun jua,<br/>Siar kisah ajaib ini,<br/>hampa - Dia yang penuhi.<br/>',NULL,62380,4);
INSERT INTO stanza VALUES('I435','1','Di dalam Adam, dosa, maut milikku,<br/>di dalam Kristus, hayat, kebenaran;<br/>Di dalam daging, Adam yang terwujud,<br/>di dalam Roh, hayat Kristus ternyata.<br/>',NULL,62381,1);
INSERT INTO stanza VALUES('I435','2','Di dalam Adam, tanpa berbuat apa,<br/>sudahlah berdosa, patut diganjar;<br/>Di dalam Kristus, tanpa jasa apa,<br/>ku sudah dibenarkan, dib''ri hayat.<br/>',NULL,62382,2);
INSERT INTO stanza VALUES('I435','3','Di dalam daging, tanpalah sengaja,<br/>bobrok Adam tampil dengan sendiri;<br/>Di dalam Roh pun tanpalah sengaja,<br/>mulia Kristus tampillah sendiri.<br/>',NULL,62383,3);
INSERT INTO stanza VALUES('I435','4','Mati d''ngan Kristus, lepas Adam usang,<br/>bangkit d''ngan Kristus, ''nempuh hidup baru;<br/>Daging disangkal, mati sifat usang,<br/>taat pada Roh, nyata hidup kudus.<br/>',NULL,62384,4);
INSERT INTO stanza VALUES('I435','5','Taat pada Roh, itu cara Allah,<br/>kecuali ini tiada s''lamat;<br/>Taat pada Roh, nafsu patah punah,<br/>niscaya lepas dari hukum dosa.<br/>',NULL,62385,5);
INSERT INTO stanza VALUES('I435','6','Taat pada Roh, mengalami salib,<br/>niscaya mendapat kuasa bangkit;<br/>Taat pada Roh, Kristus pun tertampil,<br/>hayat dewasa itu sudah pasti.<br/>',NULL,62386,6);
INSERT INTO stanza VALUES('I435','7','Dalam Roh Kudus, Kristus itu hayat,<br/>dalam Roh Kudus, hayat mahakuat,<br/>Dalam Roh Kudus, itu pengudusan,<br/>dalam Roh Kudus, itu realitas.<br/>',NULL,62387,7);
INSERT INTO stanza VALUES('I436','1','Kristus-lah hayatku<br/>dan sentosaku;<br/>Roh Kudus ku dapat,<br/>esa dengan-Nya.<br/>',NULL,62388,1);
INSERT INTO stanza VALUES('I436','chorus','Hidup dalam Tuhan,<br/>ikut Roh Kudus;<br/>Menikmati hayat,<br/>damai sepenuh.<br/>',NULL,62389,2);
INSERT INTO stanza VALUES('I436','2','Aku milik Kristus,<br/>tak terbelenggu;<br/>Hukum Sang Roh Hayat,<br/>bebaskan aku.<br/>',NULL,62390,3);
INSERT INTO stanza VALUES('I436','3','Tak pikirkan daging,<br/>melainkan Roh;<br/>Tak turuti diri,<br/>tapi taat Roh.<br/>',NULL,62391,4);
INSERT INTO stanza VALUES('I436','4','Tak lagi melawan,<br/>atau membangkang;<br/>Kebenaran mulia,<br/>lampaui Taurat.<br/>',NULL,62392,5);
INSERT INTO stanza VALUES('I436','5','Roh Kudus di batin,<br/>garap rohani;<br/>Tubuh fana ini,<br/>pasti ''kan bangkit.<br/>',NULL,62393,6);
INSERT INTO stanza VALUES('I436','6','Roh Kudus di rohku,<br/>berpadu esa;<br/>Buktiku anak-Nya,<br/>pimpin ''tiasa.<br/>',NULL,62394,7);
INSERT INTO stanza VALUES('I437','1','Buang dunia, t''rima Kristus,<br/>biar hatiku s''lalu puas;<br/>Lainnya tidak ku harap,<br/>dunia sia-sia bagiku.<br/>',NULL,62395,1);
INSERT INTO stanza VALUES('I437','chorus','K''limpahan-Nya tak terkata!<br/>Bagiku sudah jelas.<br/>Manisnya tiada bandingan!<br/>Tapi ku t''lah rasakan.<br/>',NULL,62396,2);
INSERT INTO stanza VALUES('I437','2','Buang dunia, t''rima Kristus,<br/>lainnya tak ku perlu;<br/>Dapat dunia, tetap picik,<br/>dapat Kristus, berlebih.<br/>',NULL,62397,3);
INSERT INTO stanza VALUES('I437','3','Walau dunia amat luas,<br/>hatiku tak pernah puas;<br/>Dalam hatiku yang kecil,<br/>hanya Dia yang penuhi.<br/>',NULL,62398,4);
INSERT INTO stanza VALUES('I437','4','Ada Kristus, bisa girang,<br/>tanpa Kristus, dukalah;<br/>Kristus jadi jaminanku,<br/>di dalam-Nya, tinggalku.<br/>',NULL,62399,5);
INSERT INTO stanza VALUES('I438','1','Ku pilih Tuhan Yesus, jadi duniaku;<br/>Kasih-Nya limpah sungguh puaskan s''galaku;<br/>Tuhan, aku wadah-Mu, semata untuk-Mu;<br/>Minum air Sikhar itu, tak lerai haus.<br/>',NULL,62400,1);
INSERT INTO stanza VALUES('I438','chorus','Yesus, Yesus,<br/>ku pilihlah Yesus;<br/>Dia sumber manis, mesra, kini di hatiku.<br/>Yesus, Yesus,<br/>Dia puas maremku,<br/>Yang buang permintaanku, teduhkan hasratku.<br/>',NULL,62401,2);
INSERT INTO stanza VALUES('I438','2','Ku pilih Tuhan Yesus, jadi riang riaku;<br/>Boleh ''rana hatiku, tetaplah kidungku;<br/>Alasan lain tak ganggu, ada Dia ku cukup;<br/>Pada hati-Nya m''lulu; s''mua gemarku.<br/>',NULL,62402,3);
INSERT INTO stanza VALUES('I438','3','Ku pilih Tuhan Yesus, jadi harapanku;<br/>warisan limpah sungguh, ku kenang menerus;<br/>Sang Pemberi s''mua itu, mustika milikku;<br/>Hati kini mendesus, Dia terbagus.<br/>',NULL,62403,4);
INSERT INTO stanza VALUES('I438','4','Ku pilih Tuhan Yesus, menjadi Tuhan-ku;<br/>Kasih-Nya tak terukur, hingga ku tertakluk;<br/>Persembahkan s''galaku, tiada lain rinduku,<br/>Perkenan-Nya melulu, biar Dia senyum.<br/>',NULL,62404,5);
INSERT INTO stanza VALUES('I439','1','Ku berdendang dengan hati girang,<br/>kar''na Tuhan hayat, sejaht''raku;<br/>Ya, Tuhan-ku, ku sungguh sentosa,<br/>kar''na ku ta''u Bapa pun milikku.<br/>',NULL,62405,1);
INSERT INTO stanza VALUES('I439','chorus','Kar''na Tuhan!<br/>Kar''na Tuhan!<br/>Karena Golgota!<br/>Kar''na Tuhan!<br/>',NULL,62406,2);
INSERT INTO stanza VALUES('I439','2','Dulu aku kar''na takut mati,<br/>dengan amal menghiasi diri;<br/>Harap bebas hukuman dan kutuk,<br/>kini ku ta''u Kau kes''lamatanku.<br/>',NULL,62407,3);
INSERT INTO stanza VALUES('I439','3','Meski kelak kaum dosa mend''rita,<br/>tapi g''reja-Mu ''kan dapat bah''gia;<br/>Kar''na t''lah Kau perciki darah-Mu,<br/>hingga bisa kalahkan alam maut.<br/>',NULL,62408,4);
INSERT INTO stanza VALUES('I439','4','Domba Allah telah pikul dosa,<br/>ku selamat, dapat hidup kekal;<br/>Kau minum cawan pa''it keadilan,<br/>hukuman lalu, mati pun lewat.<br/>',NULL,62409,5);
INSERT INTO stanza VALUES('I439','5','Kau bawaku ke padang yang subur,<br/>Allah Sang Damai b''ri yang terbaik;<br/>Kini ku baring dalam ribaan-Mu,<br/>persekutuan mesra ku nikmati.<br/>',NULL,62410,6);
INSERT INTO stanza VALUES('I439','6','Jagalah hidupku s''lalu segar,<br/>bahkan dalam ejekan yang hebat;<br/>Dengan iman harap pada Bapa,<br/>b''lajar sandar, riang dalam d''rita.<br/>',NULL,62411,7);
INSERT INTO stanza VALUES('I439','7','Ajarlah ku tolak tenar dunia,<br/>dengan teguh lewat s''mua ujian;<br/>Rela d''rita sengsara serta-Mu,<br/>berani korban jiwa bagi-Mu!<br/>',NULL,62412,8);
INSERT INTO stanza VALUES('I439','8','Saat aku terangkat depan-Mu,<br/>salib-Mu-lah judul nyanyianku;<br/>Dalam dunia Kau d''rita sengsara,<br/>korban jiwa di gunung Golgota.<br/>',NULL,62413,9);
INSERT INTO stanza VALUES('I440','1','Lahir hitam oleh terik surya,<br/>batin anak terang elok cantik,<br/>Tak ada yang ta''u rahasia riang,<br/>pada orang Raja mulia memb''ri;<br/>Yang belum pernah terpikir,<br/>yang belum pernah terjamah;<br/>Tinggal di dalam terang-Nya,<br/>dapat terang mulia Allah.<br/>',NULL,62414,1);
INSERT INTO stanza VALUES('I440','2','Menurut orang Ia bangsa Adam,<br/>bawa rupa dunia, d''rita, lelah;<br/>Serupa orang dosa yang jatuh,<br/>keperluan-Nya sama dengan m''reka;<br/>S''mua corak hidup bumiah,<br/>tidur bangun sama pula;<br/>Hingga mereka menghina-Nya,<br/>orang s''lalu lihat rupa.<br/>',NULL,62415,2);
INSERT INTO stanza VALUES('I440','3','Dalam m''reka ada hayat Allah,<br/>firman Tuhan lahir ulang m''reka;<br/>M''reka dibarakan api kudus,<br/>jadi milik Yerusalem Baru;<br/>M''reka umat saleh terang,<br/>s''lalu nyanyi kidung indah;<br/>Memuji Sang Mahatinggi,<br/>panjat pujian nan ajaib.<br/>',NULL,62416,3);
INSERT INTO stanza VALUES('I440','4','Hidup di bumi, tinggal di surga;<br/>lemah, tapi menguasai bumi;<br/>Sulit, namun batin penuh damai,<br/>miskin, namun semua menggenapi;<br/>Dihajar namun tak mati,<br/>habis akal, tak kecewa;<br/>S''perti dalam lembah maut,<br/>namun hidup hayat limpah.<br/>',NULL,62417,4);
INSERT INTO stanza VALUES('I440','5','Kristus - hayat m''reka nyata kelak,<br/>dengan mulia datang berkuasa;<br/>Mulia yang terkandung dalam m''reka,<br/>bersama Kristus ditampak orang;<br/>O! Anak t''rang, bersinarlah,<br/>bersama Kristus naik surga;<br/>Terang pancar, hingga jauh,<br/>tiap saleh bagai surya.<br/>',NULL,62418,5);
INSERT INTO stanza VALUES('I441','1','Allah kasih, Kau bagianku,<br/>milikku nan kekal;<br/>Di langit ku tiada siapa,<br/>di bumi pun jua,<br/>di bumi pun jua!<br/>',NULL,62419,1);
INSERT INTO stanza VALUES('I441','2','Di langit hampa kosong s''mua,<br/>terlebih di buana!<br/>Tiada yang menyenangkan,<br/>yang setara Allah,<br/>yang setara Allah!<br/>',NULL,62420,2);
INSERT INTO stanza VALUES('I441','3','Bagiku Kau: harta, hayat,<br/>kediaman nan aman;<br/>Lainnya memang ku nikmat,<br/>namun bukan Allah,<br/>namun bukan Allah!<br/>',NULL,62421,3);
INSERT INTO stanza VALUES('I441','4','Terhadap-Mu kilau harta,<br/>bukanlah tandingan!<br/>Apa lagi yang lainnya,<br/>lebih membodohkan,<br/>lebih membodohkan!<br/>',NULL,62422,4);
INSERT INTO stanza VALUES('I441','5','Walau milikku sedunia,<br/>sekalian bintang,<br/>Tanpa Kau jadi segala,<br/>tetaplah kasihan,<br/>tetaplah kasihan!<br/>',NULL,62423,5);
INSERT INTO stanza VALUES('I441','6','Biar orang lain berpeluk<br/>harta seluas laut;<br/>Ku hanya mau hadir-Mu,<br/>lain tak ku rindu,<br/>lain tak ku rindu!<br/>',NULL,62424,6);
INSERT INTO stanza VALUES('I442','1','Waktu ku ditawan Satan,<br/>jadi tahanan maut dosa;<br/>Kar''na kasih Allah datang,<br/>membawaku pada Kristus.<br/>',NULL,62425,1);
INSERT INTO stanza VALUES('I442','chorus','Kurnia agung, lahir ulang,<br/>b''riku hati dan roh baru,<br/>Roh-Nya masuk dalam rohku,<br/>sifat-Nya jadi bagianku.<br/>',NULL,62426,2);
INSERT INTO stanza VALUES('I442','2','Dengan air Allah cuciku,<br/>lepas najis, berhalaku,<br/>Singkirkan hati batuku,<br/>biarku jadi ciptaan baru.<br/>',NULL,62427,3);
INSERT INTO stanza VALUES('I442','3','Allah menjadi hayatku,<br/>sifat-Nya jadi sifatku,<br/>Ku serasi d''ngan kudus-Nya,<br/>perhidupkan perintah-Nya.<br/>',NULL,62428,4);
INSERT INTO stanza VALUES('I442','4','Ku umat-Nya, Dia Allahku,<br/>saling s''kutu, akrab sungguh,<br/>Dia berkatku, Dia bah''giaku,<br/>hanya Dia sasaranku.<br/>',NULL,62429,5);
INSERT INTO stanza VALUES('I442','5','Kristus Allah kediamanku,<br/>kelimpahan-Nya ku nikmat,<br/>Dia makanan hayatku,<br/>aku kenyang sampai kekal.<br/>',NULL,62430,6);
INSERT INTO stanza VALUES('I443','1','O, mulia! O, ilahi! Allah,<br/>hayat yang kekal!<br/>Kaya, limpah, kuat, kuasa,<br/>kudus, rahmat pun terang!<br/>Kodrat dan kelimpahan-Nya<br/>pada hayat ini s''mua.<br/>',NULL,62431,1);
INSERT INTO stanza VALUES('I443','2','Penuh cinta! Penuh kurnia!<br/>Allah sebagai hayat!<br/>Agar masuk dalam insan,<br/>roh insan Dia ciptakan.<br/>Terima Dia jadi hayat,<br/>itulah perkenan-Nya.<br/>',NULL,62432,2);
INSERT INTO stanza VALUES('I443','3','Kasih, kurnia, besar amat!<br/>Allah menjadi hayat!<br/>Tidak lagi tersembunyi,<br/>t''radap insan ternyata;<br/>Inkarnasi, menjadi Roh,<br/>Sang Hayat diterima.<br/>',NULL,62433,3);
INSERT INTO stanza VALUES('I443','4','Sungguh dekat! Sungguh akrab!<br/>Dalam Kristus Dia hayat!<br/>Kristus itu jelmaan-Nya,<br/>dalam bentuk manusia;<br/>Mati, bangkit, dipercaya,<br/>jadi hayat manusia.<br/>',NULL,62434,4);
INSERT INTO stanza VALUES('I443','5','Sungguh ajaib! Sungguh benar!<br/>Di dalam Roh Dia hayat!<br/>Roh Kudus pun jelmaan-Nya,<br/>dalam Roh Dia ternyata;<br/>Masuk dalam kaum beriman,<br/>hayat batinlah Dia.<br/>',NULL,62435,5);
INSERT INTO stanza VALUES('I443','6','Sungguh riil dan mustika!<br/>Tritunggal itu hayat!<br/>Putra ''ngalir dari Bapa,<br/>Roh ''ngalir dari Putra;<br/>Roh masuk itu kurnia,<br/>pun hayat batiniah.<br/>',NULL,62436,6);
INSERT INTO stanza VALUES('I443','7','O, misteri! Amat riil!<br/>Air hayat t''lah mengalir!<br/>Ngalir masuk ke dalamku,<br/>jadi hayat di rohku!<br/>Haleluya, puji syukur,<br/>Allah jadi hayatku!<br/>',NULL,62437,7);
INSERT INTO stanza VALUES('I444','1','Allah itu Gembalaku,<br/>Dia merawat, Dia b''ri berkat;<br/>Dia milikku, ku milik-Nya;<br/>ada Dia tak kekurangan!<br/>',NULL,62438,1);
INSERT INTO stanza VALUES('I444','2','Dia bawa ke padang rumput,<br/>agar ku kenyang selalu;<br/>Di tepi air yang sejuk,<br/>mesra, nikmat bersekutu.<br/>',NULL,62439,2);
INSERT INTO stanza VALUES('I444','3','Ku tersesat, Dia mencari,<br/>hatiku Dia yang memimpin;<br/>Ku s''ring ubah, s''lalu bimbang,<br/>tapi Dia s''lalu menunjang.<br/>',NULL,62440,3);
INSERT INTO stanza VALUES('I444','4','Dalam gelap, penuh kuatir,<br/>bagaimana ku ''kan maju?<br/>Tongkat-Mu-lah yang memimpin,<br/>dan sertaku s''panjang lebuh.<br/>',NULL,62441,4);
INSERT INTO stanza VALUES('I444','5','Kau-lah kuatku dan p''risaiku,<br/>semua musuh tentu kabur,<br/>Kau urapi kepalaku,<br/>Allah berkenan t''lah tentu.<br/>',NULL,62442,5);
INSERT INTO stanza VALUES('I444','6','Kasih ajaib, manis sungguh,<br/>p''nuhi seumur hidupku,<br/>Kar''na kasih-Mu tak ubah,<br/>biarlah pujianku bertambah.<br/>',NULL,62443,6);
INSERT INTO stanza VALUES('I445','1','T''ringat Allah, ku terpikat,<br/>hati lepas dunia,<br/>T''radap impian, hati sebal,<br/>tarik dunia sirna.<br/>',NULL,62444,1);
INSERT INTO stanza VALUES('I445','2','Hanya s''lamat, tak binasa,<br/>tak capai murad-Nya,<br/>Rindu pada-Nya mendesak,<br/>harap lebih tinggi.<br/>',NULL,62445,2);
INSERT INTO stanza VALUES('I445','3','Allah kediaman manusia,<br/>meski jalan sempit,<br/>Selain Allah apa lagi,<br/>yang puaskan hati.<br/>',NULL,62446,3);
INSERT INTO stanza VALUES('I445','4','Asal dari lubuk hati,<br/>''muji nama Allah,<br/>Semua tipu jahat keji,<br/>segera terusir.<br/>',NULL,62447,4);
INSERT INTO stanza VALUES('I445','5','Hati sandar, mata pandang,<br/>pasti dibimbing-Nya,<br/>Iman bisa pindah gunung,<br/>kasih lebih hebat.<br/>',NULL,62448,5);
INSERT INTO stanza VALUES('I445','6','O, jalan menuntut Allah,<br/>baru engkau tempuh,<br/>Hati condong pada Allah,<br/>baru engkau maju.<br/>',NULL,62449,6);
INSERT INTO stanza VALUES('I445','7','Bebas dari kuasa dosa,<br/>hidup dengan ketat,<br/>Semua masih lebih rendah,<br/>dari standar kasih.<br/>',NULL,62450,7);
INSERT INTO stanza VALUES('I445','8','Jalan benar, daging sulit,<br/>namun kasih tidak,<br/>Kalau maju cari Allah,<br/>rintangan ''kan sirna.<br/>',NULL,62451,8);
INSERT INTO stanza VALUES('I445','9','Lalu menjaga nurani,<br/>perasaan batin,<br/>''Tiasa ikut pengurapan,<br/>kunci matang pasti.<br/>',NULL,62452,9);
INSERT INTO stanza VALUES('I446','1','Kediamanku ialah diri Allah,<br/>ke sini Kristus Tuhan bawaku,<br/>Membawaku menempuh jalan-Nya,<br/>tinggal serta-Nya di tempat kudus,<br/>Rumah kudus, ilahi nan indah,<br/>tinggal serta Allah, sungguh indah.<br/>',NULL,62453,1);
INSERT INTO stanza VALUES('I446','2','Siang malam tempuh jalan panjang,<br/>diri ingin cari jalan lain;<br/>Tiada hasil, tiada kemajuan,<br/>gagal total s''mua usaha diri,<br/>Baru sadar Tuhan-lah jalannya,<br/>saat ku tinggal di dalam Allah.<br/>',NULL,62454,2);
INSERT INTO stanza VALUES('I446','3','Kediaman ajaib, rumah mulia!<br/>Serta Allah, sungguh teguh mantap.<br/>Ya Allah, Kau dan ku saling huni,<br/>moga ku hidup hanya t''radap-Mu;<br/>Dalam rumah indah nikmat tent''ram,<br/>setiap waktu mengisahkan Allah.<br/>',NULL,62455,3);
INSERT INTO stanza VALUES('I447','1','Bapa, Putra dan Roh itulah Allah!<br/>Tiga Person, tapi esa saja.<br/>Sungguh ajaib, Allah masuk hatiku,<br/>Jadilah jaminan di dalamku.<br/>',NULL,62456,1);
INSERT INTO stanza VALUES('I447','chorus','Allah Tritunggal jadi s''galaku,<br/>Sungguh mulia! Sungguh ajaib!<br/>Kurnia Allah tak habis ku pakai,<br/>Sungguh nyaman! Sungguh agung!<br/>',NULL,62457,2);
INSERT INTO stanza VALUES('I447','2','Bapa itu sumber dari segala,<br/>Semuanya untuk nikmat kita;<br/>Sungguh bah''gia ini telah ku dapat,<br/>Takkan susut, kekal selamanya!<br/>',NULL,62458,3);
INSERT INTO stanza VALUES('I447','3','Putra itulah wujud Allah Bapa,<br/>Jadi daging, gaul dengan insan;<br/>Khasiat ajaib, di salib tebusan g''nap,<br/>Hingga aku rujuk dengan Allah!<br/>',NULL,62459,4);
INSERT INTO stanza VALUES('I447','4','Roh itulah membawa masuk Putra,<br/>Masuk rohku, jadi suplai hayat;<br/>Sungguh nyaman, d''ngan Roh-Nya ku bersentuh,<br/>Jadilah satu Roh-Nya d''ngan rohku.<br/>',NULL,62460,5);
INSERT INTO stanza VALUES('I447','5','Milik Allah, antero di dalam Roh,<br/>Roh dengan roh salinglah bersentuh;<br/>Sungguh ajaib! Ku esa dengan Allah,<br/>Hayat, sifat, tak lagi berbeda.<br/>',NULL,62461,6);
INSERT INTO stanza VALUES('I448','1','Allah, ajaib-Mu terpuji,<br/>Dikau dapat kami raih;<br/>Dulu di t''rang tak terhampir,<br/>kini di roh d''nganku intim.<br/>',NULL,62462,1);
INSERT INTO stanza VALUES('I448','2','Bapa, Putra, dan Roh Kudus,<br/>Allah Tritunggal hayatku;<br/>Menyuplaiku di dalamku,<br/>hingga ku bertabiat Kristus.<br/>',NULL,62463,2);
INSERT INTO stanza VALUES('I448','3','Bapa, Putra, dan Roh Kudus,<br/>p''ri angin ''nimpa padaku;<br/>Misteri nan ajaib, kudus,<br/>jadilah pengalamanku.<br/>',NULL,62464,3);
INSERT INTO stanza VALUES('I448','4','Milik Bapa, milik Putra,<br/>limpah Putra, Roh terima;<br/>Roh garap lahir batinku,<br/>Kau jadi bagian berkatku.<br/>',NULL,62465,4);
INSERT INTO stanza VALUES('I448','5','Bapa itulah sumbernya,<br/>Putra itulah wujudnya,<br/>Roh masuk di dalam beta;<br/>Bapa, Putra, Roh Tritunggal.<br/>',NULL,62466,5);
INSERT INTO stanza VALUES('I448','6','Bapa junjung tinggi Putra,<br/>Putra ''tiasa taat Bapa;<br/>Roh memuliakan Putra,<br/>di dalamku beri wahyu.<br/>',NULL,62467,6);
INSERT INTO stanza VALUES('I448','7','Roh wujud-Mu yang terakhir,<br/>masuk rohku, t''rima sembah;<br/>Limpah ruah-Mu ku nikmati,<br/>roh dengan Roh bersentuhan.<br/>',NULL,62468,7);
INSERT INTO stanza VALUES('I448','8','Sembah, s''kutu di dalam roh,<br/>doa, puji pun dalam roh;<br/>Bersentuhlah Roh dalam roh,<br/>nikmati suplaian s''luruh.<br/>',NULL,62469,8);
INSERT INTO stanza VALUES('I449','1','Roh itulah esens Allah,<br/>juga hakiki ilahi,<br/>Jamah Allah, nikmati-Nya,<br/>harus d''ngan roh, tiada lain.<br/>',NULL,62470,1);
INSERT INTO stanza VALUES('I449','2','Roh bagian insan terdalam,<br/>bagian yang paling s''jati,<br/>Insan s''jati, jamah Allah,<br/>harus melalui roh pasti.<br/>',NULL,62471,2);
INSERT INTO stanza VALUES('I449','3','Sembah Allah harus d''ngan roh,<br/>nikmati Dia, suplai s''gala,<br/>Roh-Nya masuk roh manusia,<br/>dalam roh satu dengan-Nya.<br/>',NULL,62472,3);
INSERT INTO stanza VALUES('I449','4','Saling s''kutu di dalam roh,<br/>dua roh jadi satu roh,<br/>Roh insan - kediaman-Nya,<br/>Roh Allah - hidup roh insan.<br/>',NULL,62473,4);
INSERT INTO stanza VALUES('I449','5','D''ngan roh insan, sentuh Roh-Nya,<br/>baru nikmati kaya-Nya,<br/>Di roh insan, Roh-Nya serta,<br/>baru dapat sembah Allah.<br/>',NULL,62474,5);
INSERT INTO stanza VALUES('I449','6','Injil, bina, sidang, s''kutu,<br/>bawa orang ke dalam roh,<br/>Baca firman, dengar saksi,<br/>jadi doa, respon di roh.<br/>',NULL,62475,6);
INSERT INTO stanza VALUES('I449','7','Dalam roh doa, ''layani,<br/>menjamah hayat ilahi,<br/>Dalam roh tumbuh, membangun,<br/>menyatakan mulia Kristus.<br/>',NULL,62476,7);
INSERT INTO stanza VALUES('I449','8','Tuhan ku mau balik ke roh,<br/>belajar jamah diri-Mu,<br/>Roh-Mu, rohku, saling kontak,<br/>''ngalir hayat hingga kekal!<br/>',NULL,62477,8);
INSERT INTO stanza VALUES('I450','1','Hubungan normal Allah d''ngan insan,<br/>tergantung pada roh;<br/>Dalam roh menjamah Allah Sang Roh,<br/>baru alami Dia.<br/>',NULL,62478,1);
INSERT INTO stanza VALUES('I450','chorus','Oleh Roh, dengan roh,<br/>lahir dan menyembah;<br/>Roh pun firman,<br/>bawa hayat limpah,<br/>alirkan air hayat.<br/>',NULL,62479,2);
INSERT INTO stanza VALUES('I450','2','Allah Sang Roh ciptakan roh insan,<br/>agar roh sembah Roh;<br/>Olehnya insan t''rima hayat-Nya,<br/>Dia suplai insan.<br/>',NULL,62480,3);
INSERT INTO stanza VALUES('I450','3','Allah Sang Roh masuk ke roh insan,<br/>melahir-ulangkan;<br/>Dalam roh insani sekutu d''ngan-Nya,<br/>nikmati limpah-Nya.<br/>',NULL,62481,4);
INSERT INTO stanza VALUES('I450','4','Allah Sang Roh mendiris, penuhi,<br/>ubah pun barui;<br/>Dari roh ke jiwa dan tubuhku,<br/>diresap seluruh.<br/>',NULL,62482,5);
INSERT INTO stanza VALUES('I450','5','Allah Sang Roh baur esa d''nganku,<br/>mengubah diriku;<br/>Kadar-Nya bertambah t''rus dalamku,<br/>hingga Dia terwujud.<br/>',NULL,62483,6);
INSERT INTO stanza VALUES('I450','6','S''mua limpah Allah ada dalam Roh,<br/>ku nikmat, alami;<br/>Ku harus s''lalu tinggal dalam roh,<br/>Allah ku nikmati.<br/>',NULL,62484,7);
INSERT INTO stanza VALUES('I451','1','Hasrat-Nya, semua milik-Nya<br/>jadi suplaiku,<br/>Ku perlu satu dengan-Nya,<br/>dengan Roh-Nya.<br/>',NULL,62485,1);
INSERT INTO stanza VALUES('I451','chorus','S''gala Bapa, kaya Putra,<br/>semua pada Roh;<br/>Bila ingin sentuh Allah,<br/>harus d''ngan roh.<br/>',NULL,62486,2);
INSERT INTO stanza VALUES('I451','2','Kekayaan hakiki-Nya,<br/>Dia b''ri padaku,<br/>Harus berkontak dalam roh,<br/>baru sentuh.<br/>',NULL,62487,3);
INSERT INTO stanza VALUES('I451','3','Perlu pikiran mengerti,<br/>dan roh menyentuh,<br/>Sandar akal, tak pakai roh,<br/>gagal tentu.<br/>',NULL,62488,4);
INSERT INTO stanza VALUES('I451','4','Jangan hanya dengar khotbah,<br/>tiada doa,<br/>Jangan hanya baca firman,<br/>roh tak jamah.<br/>',NULL,62489,5);
INSERT INTO stanza VALUES('I451','5','Sungguh limpah, sungguh mulia,<br/>roh sentuh Allah,<br/>Milik Allah yang terbaik,<br/>s''mua milikku.<br/>',NULL,62490,6);
INSERT INTO stanza VALUES('I452','1','Roh Allah, transmisi Allah,<br/>dalam Dia, Allah masuk,<br/>Via Dia, Allah dalam Kristus<br/>ku dapatkan, ku alami.<br/>',NULL,62491,1);
INSERT INTO stanza VALUES('I452','2','Allah Bapa jadi sumber,<br/>Allah Putra wujudkan-Nya,<br/>Allah Roh masuk dalamku,<br/>biarku dapat limpah Allah.<br/>',NULL,62492,2);
INSERT INTO stanza VALUES('I452','3','Bapa tinggal dalam terang,<br/>Putra datang ''nyatakan-Nya,<br/>Roh transmisikan ke insan,<br/>dalam roh, insan terima.<br/>',NULL,62493,3);
INSERT INTO stanza VALUES('I452','4','Bapa datang dalam Putra,<br/>Putra juga menjadi Roh,<br/>Bapa, Putra, Roh, Tritungal,<br/>kini tinggal dalam rohku.<br/>',NULL,62494,4);
INSERT INTO stanza VALUES('I452','5','Allah Bapa dalam Putra,<br/>terwujud, terekspresikan,<br/>Allah Roh, realitas Putra,<br/>ku terima jadi kurnia.<br/>',NULL,62495,5);
INSERT INTO stanza VALUES('I452','6','Kasih Bapa kepadaku,<br/>dalam Putra jadi kurnia,<br/>Lewat Roh ditransmisikan,<br/>hingga ku nikmat kaya-Nya.<br/>',NULL,62496,6);
INSERT INTO stanza VALUES('I453','1','Denganku Kau dekat, ya Allah-ku,<br/>Meski salib berat, tetap maju;<br/>Ku s''lalu nyanyikan, kar''na Allah dekat,<br/>Denganku Kau dekat, ya Allah-ku.<br/>',NULL,62497,1);
INSERT INTO stanza VALUES('I453','2','Sampai petang hari ku berk''lana,<br/>Gelap pun menimpa, ku tertidur;<br/>Walau dalam mimpi, ku tetap dekat-Mu,<br/>Denganku Kau dekat, ya Allah-ku.<br/>',NULL,62498,2);
INSERT INTO stanza VALUES('I453','3','Dalam mimpi nampak tangga surga,<br/>Semua yang terjadi, kar''na rahmat;<br/>Kau panggilku datang, mendekat pada-Mu,<br/>Denganku Kau dekat, ya Allah-ku.<br/>',NULL,62499,3);
INSERT INTO stanza VALUES('I453','4','Waktu ku terbangun, ku bersyukur,<br/>S''gala kesukaran yang ku tempuh;<br/>Bahkan menggiringku mendekat pada-Mu,<br/>Denganku Kau dekat, ya Allah-ku.<br/>',NULL,62500,4);
INSERT INTO stanza VALUES('I453','5','Pada hari senang dan sentosa,<br/>Bagai terbang ''layang di angkasa;<br/>Ku tetap berkidung, "Denganku Kau dekat."<br/>Denganku Kau dekat, ya Allah-ku.<br/>',NULL,62501,5);
INSERT INTO stanza VALUES('I454','1','Atas bukit jauh, tegak salib tua,<br/>lambang d''rita, malu, hina,<br/>Salib yang ku cinta, atasnya Dia wafat,<br/>mend''rita bagi yang dosa.<br/>',NULL,62502,1);
INSERT INTO stanza VALUES('I454','chorus','Ku mustikakan salib tua,<br/>hingga ku sujud di depan-Nya;<br/>Ku pegang teguh salib tua,<br/>kelak dia ''kan ganti mahkota.<br/>',NULL,62503,2);
INSERT INTO stanza VALUES('I454','2','Salib tua diremehkan orang,<br/>namun menarik bagiku,<br/>Domba kudus Allah, datang dunia fana,<br/>pikul salib ke Golgota.<br/>',NULL,62504,3);
INSERT INTO stanza VALUES('I454','3','Pada salib tua, ada bercak darah,<br/>diperkenan dalam pandang!<br/>Atas salib tua, Tuhan d''rita, wafat,<br/>untuk beriku ampunan.<br/>',NULL,62505,4);
INSERT INTO stanza VALUES('I454','4','Kekal ku hargai salib tua itu,<br/>rela terhina kar''nanya,<br/>Kelak Tuhan datang, berhadapan wajah,<br/>kekal nikmati mulia-Nya.<br/>',NULL,62506,5);
INSERT INTO stanza VALUES('I455','1','Salib Kristus banggaanku,<br/>lampaui s''panjang masa,<br/>Cemerlang c''rita ilahi,<br/>salib tetaplah inti.<br/>',NULL,62507,1);
INSERT INTO stanza VALUES('I455','2','Waktu jumpa d''rita, siksa,<br/>harap pudar, ku gentar,<br/>Salib Kristus tak buangku,<br/>Lihat! Damai pun riang.<br/>',NULL,62508,2);
INSERT INTO stanza VALUES('I455','3','Waktu surya dengan kasih<br/>menerangi jalanku,<br/>Salib Kristus pancar cah''ya,<br/>biar hidupku kian terang.<br/>',NULL,62509,3);
INSERT INTO stanza VALUES('I455','4','Mara, berkat, duka, riang,<br/>salib menguduskanku,<br/>Sejahtera tak terukur,<br/>sukacita tak putus.<br/>',NULL,62510,4);
INSERT INTO stanza VALUES('I455','5','Salib Kristus banggaanku,<br/>lampaui s''panjang masa,<br/>Cemerlang c''rita ilahi,<br/>salib tetaplah inti.<br/>',NULL,62511,5);
INSERT INTO stanza VALUES('I456','1','Dekatkan ku, ya, Tuhan,<br/>pada salib ''tiasa;<br/>Dari sana mengalir,<br/>aliran air hayat.<br/>',NULL,62512,1);
INSERT INTO stanza VALUES('I456','chorus','Salib-Nya! Salib-Nya!<br/>S''lamanya megahku!<br/>Harga tebusan Tuhan,<br/>kekal sandaranku.<br/>',NULL,62513,2);
INSERT INTO stanza VALUES('I456','2','Dulu ku takut, gentar,<br/>kini t''rima kurnia;<br/>Di salib, cah''ya fajar,<br/>menyoroti beta.<br/>',NULL,62514,3);
INSERT INTO stanza VALUES('I456','3','Saat hampiri salib,<br/>singkapkan wahyu-Mu;<br/>Bawah naungan salib,<br/>pimpinku t''rus maju.<br/>',NULL,62515,4);
INSERT INTO stanza VALUES('I456','4','Berjaga dekat salib,<br/>s''lalu sandar, harap;<br/>Hingga hari terangkat,<br/>jumpa wajah Tuhan.<br/>',NULL,62516,5);
INSERT INTO stanza VALUES('I457','1','Salib menang s''lama,<br/>haleluya! Haleluya!<br/>Musuh terhempas s''mua,<br/>haleluya! Haleluya!<br/>Biar maut gejolak,<br/>biar dunia bergolak,<br/>Biar daging menantang,<br/>salib jaya tak ubah!<br/>',NULL,62517,1);
INSERT INTO stanza VALUES('I457','chorus','Haleluya! Haleluya!<br/>Salib Kristus m''nang s''lama!<br/>Haleluya! Haleluya!<br/>Salib Kristus m''nang s''lama!<br/>',NULL,62518,2);
INSERT INTO stanza VALUES('I457','2','Salib itu hayat,<br/>haleluya! Haleluya!<br/>Salib itu kuasa,<br/>haleluya! Haleluya!<br/>Menang atas iba,<br/>diri, kuasa dunia,<br/>Menang atas musuh,<br/>salib jaya s''lamanya!<br/>',NULL,62519,3);
INSERT INTO stanza VALUES('I457','3','Salib panji jaya,<br/>haleluya! Haleluya!<br/>Ku kekal tinggikan,<br/>haleluya! Haleluya!<br/>Lemah jadi tegap,<br/>lesu jadi gairah,<br/>Gelap jadi terang,<br/>salib yang membebaskan!<br/>',NULL,62520,4);
INSERT INTO stanza VALUES('I458','1','Tanpa buah zaitun digencet,<br/>takkan ''ngalir minyak;<br/>Tanpa buah anggur dikilang,<br/>takkan jadilah arak;<br/>Tanpa nar''stu jadi raksi,<br/>takkan bersemerbak;<br/>Jugakah diriku ini,<br/>Kau bolehkan terluka?<br/>',NULL,62521,1);
INSERT INTO stanza VALUES('I458','chorus','Tiap cemeti, untung sejati;<br/>Barang yang Kau tarik balik,<br/>diri-Mu-lah Pengganti.<br/>',NULL,62522,2);
INSERT INTO stanza VALUES('I458','2','Kau petik dawai hatiku,<br/>gemakan musik-Mu?<br/>Agar musik makin merdu,<br/>perlukah siksaan-Mu?<br/>Atau saat ku terjatuh,<br/>baru k''nal kasih-Mu?<br/>Korban apa tak ku hitung,<br/>asal karib dengan-Mu.<br/>',NULL,62523,3);
INSERT INTO stanza VALUES('I458','3','Ku malu karena sadar,<br/>masih tahan awak;<br/>Walau pernah ku Kau pahat,<br/>namun rasa dipaksa!<br/>Bisakah sesuka Tuhan,<br/>bertindak leluasa?<br/>Perasaanku biar saja,<br/>asal Dikau yang senang.<br/>',NULL,62524,4);
INSERT INTO stanza VALUES('I458','4','Kalau suka duka kita<br/>tak dapat sepaham,<br/>Kau girang, perlu ku korban,<br/>begitu pun ku rela;<br/>Genap hati ku mau taat,<br/>tak peduli harga,<br/>Asal Kau dimuliakan,<br/>salib b''rat ku pikul jua.<br/>',NULL,62525,5);
INSERT INTO stanza VALUES('I458','5','Ku memuji dan memuji,<br/>manisnya tak tara,<br/>Memuji sambil menangis,<br/>mesra kian bertambah;<br/>Adakah yang lebih baik<br/>daripada Tuhan?<br/>Ku berdoa serta ingin,<br/>Kau bertambah ku kurang.<br/>',NULL,62526,6);
INSERT INTO stanza VALUES('I459','1','Salib berat, Allah dekat,<br/>tanpa salib, tiada Allah,<br/>Kalau aku pikul salib,<br/>raja gelap ''kan terinjak.<br/>Yang Dia letakkan di salib,<br/>meski rugi, tetap girang.<br/>',NULL,62527,1);
INSERT INTO stanza VALUES('I459','2','Salib berat, saleh mantap,<br/>ini batu ujian-Nya.<br/>Tanpa siraman air mata,<br/>bunga di taman ''kan layu!<br/>''Mas dibakar jadi murni,<br/>saleh d''rita jadi kudus.<br/>',NULL,62528,2);
INSERT INTO stanza VALUES('I459','3','Salib berat, iman kuat,<br/>pohon tinggi, akar dalam;<br/>Buah anggur lewat kilang,<br/>baru ''ngalir sari manis;<br/>D''rita datang, makin tumbuh,<br/>kerang luka, ''tiara jadi.<br/>',NULL,62529,3);
INSERT INTO stanza VALUES('I460','1','Tanpa rugi, tak mendapat;<br/>tanpa salib, tak ''kan hidup;<br/>Kalau biji gandum mati,<br/>pasti tumbuh banyak butir;<br/>Kalau mau berbuah lebat,<br/>tak mungkin tak lewat remuk.<br/>Kalau mau berbuah lebat,<br/>tak mungkin tak lewat remuk.<br/>',NULL,62530,1);
INSERT INTO stanza VALUES('I460','2','Dipegang jiwa, tercengk''ram;<br/>biar rantai mas, tetap budak;<br/>Barang yang kita senangi,<br/>ia akan mencengk''ram jiwa;<br/>Baik hidup atau harta,<br/>dicintai, rantai jadi.<br/>Baik hidup atau harta,<br/>dicintai, rantai jadi.<br/>',NULL,62531,2);
INSERT INTO stanza VALUES('I460','3','Nampak sawah yang menguning,<br/>tuaian sembah pada-Nya;<br/>Ada biji gandum mati,<br/>ada kaum saleh korban;<br/>Ada yang d''rita sengsara<br/>dan setia sampai mati.<br/>Ada yang d''rita sengsara<br/>dan setia sampai mati.<br/>',NULL,62532,3);
INSERT INTO stanza VALUES('I461','1','Pikul salib, bukan hal derita s''mata!<br/>Lekat salib, tentu alami kematian.<br/>Memang makna salib, insan ditamatkan;<br/>Pengalaman salib, akhir diri pasti.<br/>',NULL,62533,1);
INSERT INTO stanza VALUES('I461','2','Peny''lamatan Allah - insan dimatikan;<br/>Nampak kejam, sadis, padahal mulia.<br/>Tiada kupas salib, tak alami Dia,<br/>Si "aku" berakhir, Kristus baru tampil.<br/>',NULL,62534,2);
INSERT INTO stanza VALUES('I461','3','Tujuan akhir salib, g''napkan kehendak-Nya,<br/>Si "aku" itulah musuh paling besar.<br/>Hayat jiwa sirna, "aku" baru lenyap;<br/>Singkir sifat diri, kehendak-Nya lancar.<br/>',NULL,62535,3);
INSERT INTO stanza VALUES('I462','1','Jalan salib itu berkorban,<br/>sembahkan s''mua bagi-Nya,<br/>Taruh di mezbah maut tanpa sisa,<br/>api baru menyala.<br/>',NULL,62536,1);
INSERT INTO stanza VALUES('I462','chorus','''Nilah jalan salib!<br/>Maukah menempuh?<br/>Mau pikul bagi Tuhan-mu?<br/>Kau telah persembahkan dirimu!<br/>Murnikah setiamu?<br/>',NULL,62537,2);
INSERT INTO stanza VALUES('I462','2','Saat menyanyi dan berdoa,<br/>ingin relakan semua!<br/>Tapi depan ada salib lebih b''rat,<br/>tantangan lebih besar!<br/>',NULL,62538,3);
INSERT INTO stanza VALUES('I462','3','Mundur atau terus berjalan,<br/>meski rugi menimpa?<br/>Hingga hayat kekal nan kaya limpah,<br/>dalam roh penuh luap.<br/>',NULL,62539,4);
INSERT INTO stanza VALUES('I462','4','Setelah mati baru hidup,<br/>dengan Kristus bersatu;<br/>Demi iman bersama Dia terpaku,<br/>atasmu Dia hidup.<br/>',NULL,62540,5);
INSERT INTO stanza VALUES('I462','5','Mujur, malang, tidak mengapa,<br/>yang utama murad-Nya;<br/>Bila segalanya terbilang sampah,<br/>Tuhan tak ''kan terhalang.<br/>',NULL,62541,6);
INSERT INTO stanza VALUES('I463','1','Salib disambut, sempit ditempuh,<br/>alir hayat jangan dibendung;<br/>Dunia buang jauh,<br/>s''lain Dia tak gandrung,<br/>alir hayat jangan dibendung.<br/>',NULL,62542,1);
INSERT INTO stanza VALUES('I463','chorus','Alir! Alir!<br/>Alir hayat, tak dibendung;<br/>Alir! Alir!<br/>Alir hayat, jangan dibendung.<br/>',NULL,62543,2);
INSERT INTO stanza VALUES('I464','1','Bila kenal kuasa bangkit,<br/>pasti cinta ''kan salib;<br/>Mati niscayalah tumbuh,<br/>tanpa mati tak hidup.<br/>',NULL,62544,1);
INSERT INTO stanza VALUES('I464','chorus','Tanpalah mati,<br/>takkanlah hidup!<br/>Mati niscayalah tumbuh,<br/>mati ''kan hidup.<br/>',NULL,62545,2);
INSERT INTO stanza VALUES('I464','2','Kristus terbentuk dalamku,<br/>tersingkirlah diriku;<br/>Hidup bawah naungan salib,<br/>hidup jiwa terbasmi.<br/>',NULL,62546,3);
INSERT INTO stanza VALUES('I464','3','Allah demi Roh yang kekal,<br/>menyalibku serta-Nya;<br/>Berperan maut atasku,<br/>hidup lantas terwujud.<br/>',NULL,62547,4);
INSERT INTO stanza VALUES('I465','1','Mari merenungkan<br/>s''panjang hidup anggur;<br/>Jalannya tak mudah,<br/>tempatnya tak nyaman;<br/>Tak seperti bunga liar,<br/>yang seenaknya berkembang;<br/>Menjalar semaunya,<br/>jadi banyak ragam.<br/>',NULL,62548,1);
INSERT INTO stanza VALUES('I465','2','Tapi bunga anggur,<br/>kecil tiada marak;<br/>Hampir tak dikenal,<br/>namun pernah mekar;<br/>Meski tak sampai sehari,<br/>cepat-cepat jadi buah,<br/>Tak bisa bermegah,<br/>membanggakan awak.<br/>',NULL,62549,2);
INSERT INTO stanza VALUES('I465','3','Ia terikat pasak,<br/>tak tumbuh semaunya;<br/>Kalaupun menjalar,<br/>tertahan rangkanya;<br/>Demikian ia terpancang,<br/>menyesap suplai makanan;<br/>Tak ada pilihan,<br/>t''rima susah, senang.<br/>',NULL,62550,3);
INSERT INTO stanza VALUES('I465','4','Carang hijau indah,<br/>bertebaran luas,<br/>Kar''na penuh hayat,<br/>bertumbuh semarak;<br/>Penuh dengan tunas muda,<br/>menjalar ke tiap bagian;<br/>Pada langit biru,<br/>nikmati indahnya.<br/>',NULL,62551,4);
INSERT INTO stanza VALUES('I465','5','Tapi pemiliknya,<br/>tak kendur padanya;<br/>Bawa gunting, pisau,<br/>memotong sombongnya,<br/>Tak sayang pada tunasnya,<br/>dipotong dalam dan tepat,<br/>Semua keindahan,<br/>diputus, dipapas.<br/>',NULL,62552,5);
INSERT INTO stanza VALUES('I465','6','Pada masa d''rita,<br/>ia tak sayang diri,<br/>Sepenuhnya pasrah,<br/>lebih mutlak lagi,<br/>Berserah pada tangan-Nya,<br/>yang ambil semua miliknya;<br/>Tak untuk yang lain,<br/>hanya untuk berbuah.<br/>',NULL,62553,6);
INSERT INTO stanza VALUES('I465','7','Ranting yang berdarah,<br/>jadi kayu keras;<br/>Bulir yang tersisa,<br/>jadi buah yang lebat;<br/>Surya sorot panas terik,<br/>daun mulai layu rontok,<br/>Agar banyak buah,<br/>sampai waktu ''nuai.<br/>',NULL,62554,7);
INSERT INTO stanza VALUES('I465','8','Kar''na beban berat,<br/>ranting runduk semua;<br/>Ini hasil dari<br/>tindasan yang lama;<br/>Sekarang buahnya indah,<br/>hati pun terhibur sangat;<br/>Segera dituai,<br/>waktu sangat singkat!<br/>',NULL,62555,8);
INSERT INTO stanza VALUES('I465','9','Tangan akan petik,<br/>kaki akan injak,<br/>Semua nilai anggur,<br/>dalam pengirikan,<br/>Sari merah yang berharga,<br/>''ngalir seperti bengawan,<br/>Terus menggelora,<br/>bumi penuh riang.<br/>',NULL,62556,9);
INSERT INTO stanza VALUES('I465','10','Tapi bentuk anggur,<br/>telah hilang lenyap,<br/>Semua diberikan,<br/>lalu masuk gelap,<br/>Tidak ada yang membayar,<br/>riang anggur yang ia berikan,<br/>Malah memangkasnya,<br/>jadi ranting gersang.<br/>',NULL,62557,10);
INSERT INTO stanza VALUES('I465','11','Pada musim dingin,<br/>rasa manis arak,<br/>Beri hangat bagi<br/>orang sedih, gundah,<br/>Tapi pokok anggur di luar,<br/>m''rana beku sendirian,<br/>Menahan derita,<br/>sungguh sulit paham.<br/>',NULL,62558,11);
INSERT INTO stanza VALUES('I465','12','Set''lah musim dingin,<br/>siap berbuah lagi,<br/>Tunas baru muncul,<br/>hijau permai indah,<br/>Tak kar''na dulu sengsara,<br/>hati merasa tak rela;<br/>Tidak kar''na rugi,<br/>kurangi memberi.<br/>',NULL,62559,12);
INSERT INTO stanza VALUES('I465','13','S''mua yang dihirupnya<br/>udara surgawi,<br/>Tak tercemar oleh<br/>kasih duniawi;<br/>Songsong d''rita dengan senyum,<br/>t''rima lagi kupas kasih,<br/>Seperti tak pernah<br/>menderita sakit.<br/>',NULL,62560,13);
INSERT INTO stanza VALUES('I465','14','Dari buah anggur:<br/>arak, darah, sari;<br/>Apa kar''na habis,<br/>lalu lebih miskin?<br/>Orang mabuk, orang k''lana,<br/>meminumnya jadi girang,<br/>Apa kar''na bah''gia,<br/>lalu jadi kaya?<br/>',NULL,62561,14);
INSERT INTO stanza VALUES('I465','15','Prinsip ukur hayat:<br/>rugi, bukan untung,<br/>Bukan minum banyak,<br/>tapi tuang b''rapa;<br/>Karena kekuatan kasih,<br/>pada pengorbanan kasih,<br/>Siapa paling d''rita,<br/>paling bisa beri.<br/>',NULL,62562,15);
INSERT INTO stanza VALUES('I465','16','Siapa paling ketat,<br/>mudah Allah pilih,<br/>Siapa paling luka,<br/>dapat seka linang;<br/>Siapa tak bisa dikupas,<br/>itu gong yang berkumandang,<br/>Siapa tolong diri,<br/>riangnya tak memuncak.<br/>',NULL,62563,16);
INSERT INTO stanza VALUES('I466','1','"Jika mati!"<br/>Inilah perkataan Tuhan!<br/>"Jika mati,<br/>pasti hasilkan banyak buah".<br/>',NULL,62564,1);
INSERT INTO stanza VALUES('I466','2','Kalau ingin dapat hayat,<br/>kau harus mati,<br/>Jatuh dalam tanah,<br/>mati, pasti berbuah.<br/>',NULL,62565,2);
INSERT INTO stanza VALUES('I466','3','Namun tak tinggal di mati,<br/>hayat-Nya kerja,<br/>Dia pasti membangkitkanmu,<br/>p''nuh hayat baru.<br/>',NULL,62566,3);
INSERT INTO stanza VALUES('I466','4','Mau tempuh jalan hayat,<br/>bebaskan hayat?<br/>Harus lewat jalan maut,<br/>suplaikan hayat.<br/>',NULL,62567,4);
INSERT INTO stanza VALUES('I466','5','Belajar rahasia ini,<br/>mati ''kan hidup;<br/>Tuang hayat sampai mati,<br/>limpah menuai.<br/>',NULL,62568,5);
INSERT INTO stanza VALUES('I467','1','M''ngapa kau tak luka?<br/>Tiada bekas luka di lambungmu?<br/>Namamu justru makin termasyhur,<br/>m''reka malah memuji sinarmu?<br/>M''ngapa tiada luka?<br/>',NULL,62569,1);
INSERT INTO stanza VALUES('I467','2','M''ngapa kau tak luka?<br/>Ku tersiksa, digantung di salib,<br/>Sekeliling kejam, tak simpatik,<br/>Ku disesah, dipaku, dilukai,<br/>M''ngapa tiada luka?<br/>',NULL,62570,2);
INSERT INTO stanza VALUES('I467','3','M''ngapa kau tak luka?<br/>Hamba tak lebih tinggi Tuannya,<br/>Guru dipermalu, murid tidak?<br/>Engkau lancar, utuh, tak cidera!<br/>M''ngapa tiada luka?<br/>',NULL,62571,3);
INSERT INTO stanza VALUES('I467','4','M''ngapa kau tak luka?<br/>Bagi-Ku m''reka diikat orang,<br/>B''lenggu, penjara, dibakar,<br/>dibuang, atau mati diterkam binatang,<br/>M''ngapa tiada luka?<br/>',NULL,62572,4);
INSERT INTO stanza VALUES('I467','5','M''ngapa kau tak luka?<br/>Aku diinjak, dicerca orang,<br/>Mereka dibenci, dipukuli,<br/>tapi kau tent''ram tak kekurangan,<br/>Engkau tiada luka?<br/>',NULL,62573,5);
INSERT INTO stanza VALUES('I467','6','Engkau tiada luka!<br/>Apakah kau takluk pada dunia,<br/>Takut diri menderita rugi,<br/>ikut jauh tidak jernih?<br/>Maka tiada luka?<br/>',NULL,62574,6);
INSERT INTO stanza VALUES('I467','7','M''ngapa kau tak luka?<br/>Tidak penat, malah nyaman nikmat?<br/>Adakah yang setia, dapat upah,<br/>yang mutlak ikuti Anak Domba,<br/>Tapi tiada luka?<br/>',NULL,62575,7);
INSERT INTO stanza VALUES('I468','1','Bila ku jalan menyimpang,<br/>cari kesedapan;<br/>Teringatlah serta merta,<br/>Kristus menderita.<br/>',NULL,62576,1);
INSERT INTO stanza VALUES('I468','2','Ku telah membuang dunia<br/>serta kaitannya,<br/>Kian sempit perjalanan,<br/>ku cuma melintas.<br/>',NULL,62577,2);
INSERT INTO stanza VALUES('I468','3','Biar dunia memandang rendah,<br/>asal Tuhan suka;<br/>Banyak orang cari muka,<br/>ku cari kenan-Nya.<br/>',NULL,62578,3);
INSERT INTO stanza VALUES('I468','4','Yang ku harap bukan mewah,<br/>bukan kelajuan;<br/>Berbakti kepada Tuhan,<br/>kelak dipuji-Nya.<br/>',NULL,62579,4);
INSERT INTO stanza VALUES('I468','5','Hari-hari ku memandang,<br/>sorotan hukuman;<br/>Agar ku hidup dan kerja,<br/>tahan pembakaran.<br/>',NULL,62580,5);
INSERT INTO stanza VALUES('I468','6','Kalian saja yang tenar,<br/>banyak harta, kawan,<br/>Hasil pun kalian dapat,<br/>pengiring, pujian.<br/>',NULL,62581,6);
INSERT INTO stanza VALUES('I468','7','Namun ku rela menyamping,<br/>jauh dosa, najis,<br/>Setia polos ku ingin,<br/>ikut Dia abadi.<br/>',NULL,62582,7);
INSERT INTO stanza VALUES('I468','8','Ku paham Tuhan di bumi,<br/>menerima mati,<br/>Lain ku tak damba lagi,<br/>bagi-Nya ku kini.<br/>',NULL,62583,8);
INSERT INTO stanza VALUES('I468','9','Muliaku di kelak hari,<br/>ku sabar menanti;<br/>Tuhan takkan ku dului,<br/>berbah''gia di sini.<br/>',NULL,62584,9);
INSERT INTO stanza VALUES('I468','10','Hari itu ku terangkat,<br/>air mata terseka;<br/>Kini Tuhan berlambatan,<br/>ku maju tak ubah.<br/>',NULL,62585,10);
INSERT INTO stanza VALUES('I469','1','Dari Betlehem berangkat,<br/>mengikuti setia-Nya,<br/>Bagi Allah harus mutlak,<br/>walau linang air mata;<br/>Memang malaf hina dina,<br/>siapa gemar melihat?<br/>Namun kaki ikut Dia,<br/>kalau ingin pahala.<br/>',NULL,62586,1);
INSERT INTO stanza VALUES('I469','2','Pelintasan di Nazaret,<br/>kian jauh kian sempit,<br/>Tahun-tahun penat letih,<br/>terolok dan terpencil.<br/>Nasihat Allah berbunyi:<br/>Menderita tak lain,<br/>Hamba takkan mengungguli,<br/>Sang Majikan sendiri.<br/>',NULL,62587,2);
INSERT INTO stanza VALUES('I469','3','Di Galilea nampak Tuhan,<br/>ditentang dan dicerca;<br/>Apa salahkah jalan-Nya,<br/>hingga banyak sengsara?<br/>Tidak! Jalan memang susah,<br/>tetap tabah langkah-Nya;<br/>Ingin terlantik bersama?<br/>Ayo, maju tak gentar!<br/>',NULL,62588,3);
INSERT INTO stanza VALUES('I469','4','Tibalah di Getsemani,<br/>sendirian teruji;<br/>Bertubi serangan Iblis,<br/>suasana kian genting!<br/>Kita tak akan terguling,<br/>m''laikat pada ''layani,<br/>Pahala sedang menanti,<br/>perang seg''ra berakhir.<br/>',NULL,62589,4);
INSERT INTO stanza VALUES('I469','5','Salib tiba! Jiwa setia!<br/>Tak menghindar Golgota!<br/>Terhina bersama Tuhan,<br/>tak bermanja, tak jera.<br/>Demikian menderita,<br/>''jenak saja saat-nya;<br/>Kelak duka lenyap sirna,<br/>oleh kerling senyum-Nya.<br/>',NULL,62590,5);
INSERT INTO stanza VALUES('I469','6','Dengar, tangisan di makam,<br/>tanda tiada harapan;<br/>(Kawan, terhadapmu dunia,<br/>apa sudah kecewa?)<br/>Terangkat bersama Tuhan,<br/>jauh cengk''ram buana;<br/>Hati diam-diam lega,<br/>abai berkat dunia.<br/>',NULL,62591,6);
INSERT INTO stanza VALUES('I469','7','Lari menuju sasaran,<br/>hari makin mendesak;<br/>Seolah telah melihat,<br/>sinar kota cemerlang;<br/>Sayup-sayup kedengaran,<br/>musik surga menggema;<br/>Yesus menyongsong di sana,<br/>hibur luka dan duka.<br/>',NULL,62592,7);
INSERT INTO stanza VALUES('I469','8','Tak berapa jauh lagi,<br/>lerai penat dan pedih;<br/>Tiada dosa, tiada getir,<br/>tangis, sedih terhenti.<br/>Dengan suara-Nya manis,<br/>"Maju, janganlah jeri!<br/>Sebelum fajar menyingsing,<br/>mungkin sudah berakhir."<br/>',NULL,62593,8);
INSERT INTO stanza VALUES('I470','1','Hanya sering korban,<br/>mau pikul salib,<br/>baru bisa menang,<br/>baru berkuasa.<br/>Bukan kuat diri,<br/>pikiran insan,<br/>tapi nama Yesus,<br/>membuatku menang.<br/>',NULL,62594,1);
INSERT INTO stanza VALUES('I470','chorus','Hanya sering korban,<br/>mau pikul salib,<br/>baru bisa menang,<br/>baru berkuasa.<br/>',NULL,62595,2);
INSERT INTO stanza VALUES('I470','2','Hapus kemegahan,<br/>sombong duniawi,<br/>kita harus berp''rang,<br/>seperti Yesus;<br/>Berkuasa lewat maut,<br/>m''nang lewat gagal,<br/>kar''na d''rita salib,<br/>hancurkan Iblis.<br/>',NULL,62596,3);
INSERT INTO stanza VALUES('I470','3','B''rani, lembut, kasih,<br/>tapi berjuang;<br/>kerja tapi sabat,<br/>kuat tapi lemah;<br/>Ingin mendapatkan,<br/>malah memberi;<br/>tersalib dengan-Nya,<br/>penuh d''ngan hayat.<br/>',NULL,62597,4);
INSERT INTO stanza VALUES('I470','4','Kalau ikut Tuhan,<br/>tempuh jalan-Nya,<br/>harus pikul salib,<br/>satu dengan-Nya.<br/>Tahan sampai akhir,<br/>mati tak hindar,<br/>sampai Tuhan datang,<br/>dapat mahkota.<br/>',NULL,62598,5);
INSERT INTO stanza VALUES('I471','1','"Hancur, datang ke Tuhan!"<br/>Baru dapat bergita!<br/>Kapal kecil di pantai,<br/>takut gelombang besar,<br/>Tak tahu set''lah hancur,<br/>perhentian dalam Tuhan.<br/>',NULL,62599,1);
INSERT INTO stanza VALUES('I471','2','Kita ''ngeluh "T''lah hancur!"<br/>Justru memuji!<br/>Gempuran ombak dahsyat,<br/>makin nikmati Tuhan.<br/>Sentosa dalam Tuhan,<br/>tak dapat digoyahkan.<br/>',NULL,62600,2);
INSERT INTO stanza VALUES('I471','3','Set''lah "hancur" tak perlu<br/>tehnik p''layaran lagi,<br/>Meski tetap berlayar,<br/>tapi sauh di surga;<br/>Tak perlu kuatir g''lisah,<br/>asal beserta Tuhan.<br/>',NULL,62601,3);
INSERT INTO stanza VALUES('I471','4','"Hancur!" jadi berkatku,<br/>pelayar lain heran:<br/>Tampaknya siksaan b''rat,<br/>sesungguhnya anug''rah!<br/>Asal di tangan Tuhan,<br/>dijaga oleh Tuhan.<br/>',NULL,62602,4);
INSERT INTO stanza VALUES('I472','1','Maut tak dapat tahan hayat bangkit,<br/>hayat kekal Allah non ciptaan;<br/>Kuat, menang, tak dapat binasa,<br/>Kristus sendiri telah ternyata.<br/>',NULL,62603,1);
INSERT INTO stanza VALUES('I472','2','Maut tak dapat tahan hayat bangkit,<br/>meski maut sekuatnya menyerang;<br/>Maut justru membuat hayat ini<br/>menyatakan kuasa yang tak hingga.<br/>',NULL,62604,2);
INSERT INTO stanza VALUES('I472','3','Maut tak dapat tahan hayat bangkit,<br/>mati, kubur, membuatnya berkembang;<br/>Semua rintangan membuatnya tumbuh,<br/>menghasilkan buah hayat limpah.<br/>',NULL,62605,3);
INSERT INTO stanza VALUES('I472','4','Maut tak dapat tahan hayat bangkit,<br/>dia menerjang semua rintangan;<br/>Mengalahkan kuasa alam maut,<br/>telan maut dan bebaskan hayat.<br/>',NULL,62606,4);
INSERT INTO stanza VALUES('I472','5','Maut tak dapat tahan hayat bangkit<br/>yang tampilkan semua sifat Allah;<br/>Menghasilkan adil, kudus Allah,<br/>ekspresikan gambar mulia Allah.<br/>',NULL,62607,5);
INSERT INTO stanza VALUES('I472','6','Moga ku mengenal hayat bangkit,<br/>tiap jumpa maut, kuasanya nyata;<br/>Dari pengalaman kekal tahu:<br/>hayat bangkit ialah Kristus hidup.<br/>',NULL,62608,6);
INSERT INTO stanza VALUES('I473','1','Bangkit dari maut, itulah hayat,<br/>Di masa kini ataukah kelak?<br/>Bukan kelak! Melainkan sekarang;<br/>Wadah pecah, serahkan Penjunan.<br/>',NULL,62609,1);
INSERT INTO stanza VALUES('I473','2','Bangkit dari maut, alangkah ajaib!<br/>Tertanam lemah, bangkitnya kuat;<br/>Hidup-Mu wujud, tahan geser, tentang,<br/>Bukan aku, tapi Kristus Raja.<br/>',NULL,62610,2);
INSERT INTO stanza VALUES('I473','3','Bangkit dari maut, jalan yang sempit,<br/>Yang kenal salib, baru mau ''nempuh;<br/>S''rupa mati-Nya, m''reka berbagian,<br/>Kar''na Dia, s''gala terbilang rugi.<br/>',NULL,62611,3);
INSERT INTO stanza VALUES('I473','4','Bangkit dari maut, alangkah bah''gia!<br/>Dari aliran limpah surgawi,<br/>Sumber air hayat yang meluap limpah,<br/>Yang dahaga takkan haus lagi.<br/>',NULL,62612,4);
INSERT INTO stanza VALUES('I474','1','Penempuh jalan benar,<br/>letih kaki tangan,<br/>Pandanglah pada Yesus,<br/>hilanglah kecewa.<br/>Terang cerah wajah-Nya,<br/>singkir semua gelap,<br/>Pandang wajah mulia-Nya,<br/>pasti terang bend''rang.<br/>',NULL,62613,1);
INSERT INTO stanza VALUES('I474','2','Pandanglah pada Yesus,<br/>pasti tak melihat,<br/>Tindas, miskin dan susah,<br/>mengancam seputar;<br/>Tiada tangisan duka<br/>yang rabunkan mata,<br/>Tiada mara bahaya,<br/>memancing prasangka.<br/>',NULL,62614,2);
INSERT INTO stanza VALUES('I474','3','Pandanglah pada Yesus,<br/>rohmu t''rima kurnia,<br/>Dunia penuh derita,<br/>dalam Tuhan tent''ram.<br/>Bahari hidup insan,<br/>ada ombak g''lombang,<br/>Asal pandang wajah-Nya,<br/>hati takkan gentar.<br/>',NULL,62615,3);
INSERT INTO stanza VALUES('I474','4','Pandanglah pada Yesus,<br/>engkau takkan sesat,<br/>Kalau memandang Yesus,<br/>Dia ''kan tunjuk jalan.<br/>Dia pimpin maju depan,<br/>meski kabut tebal,<br/>Asal terus pandang Dia,<br/>pasti takkan salah.<br/>',NULL,62616,4);
INSERT INTO stanza VALUES('I474','5','Pandanglah pada Yesus,<br/>sampai kau terangkat,<br/>Hingga wajah nan mulia,<br/>nyata depan mata.<br/>Kini pandang wajah-Nya,<br/>dapatkan kekuatan,<br/>Kelak jadi pujian,<br/>girang selamanya.<br/>',NULL,62617,5);
INSERT INTO stanza VALUES('I475','1','Sungguh penat, letih dan lelah!<br/>Meraba di dalam gelap!<br/>Bila memandang Kristus Raja,<br/>semua jadi cemerlang.<br/>',NULL,62618,1);
INSERT INTO stanza VALUES('I475','chorus','Pandanglah pada Yesus!<br/>Tataplah wajah-Nya s''lalu!<br/>Isi dunia segera luntur,<br/>oleh sinar kemuliaan-Nya.<br/>',NULL,62619,2);
INSERT INTO stanza VALUES('I475','2','Lewat maut terbitlah hayat,<br/>Dia di depan buka jalan;<br/>Kuasa dosa sudahlah musnah,<br/>kita menang beserta-Nya.<br/>',NULL,62620,3);
INSERT INTO stanza VALUES('I475','3','Janji-Nya tidak pernah sia-sia;<br/>bersandar Dia pasti lancar;<br/>Mari maju tanpalah ragu,<br/>kau ''kan alami kurnia-Nya.<br/>',NULL,62621,4);
INSERT INTO stanza VALUES('I476','1','Hidup dalam terang,<br/>sekutu dengan Dia,<br/>Pandang wajah Tuhan,<br/>patuh gerakan Roh,<br/>Tiap hari kian mulia,<br/>tiap waktu puji Dia,<br/>Hidup dalam terang.<br/>',NULL,62622,1);
INSERT INTO stanza VALUES('I477','1','Giat menghadap Tuhan,<br/>saling bicara,<br/>Tinggal di dalam-Nya,<br/>makan firman-Nya,<br/>Tunggu di depan-Nya,<br/>lembut dan taat,<br/>Atas setiap hal,<br/>cari berkat-Nya.<br/>',NULL,62623,1);
INSERT INTO stanza VALUES('I477','2','Giat menghadap Tuhan,<br/>meskipun sibuk;<br/>Sering sendirian,<br/>beserta Tuhan.<br/>Lewat pandang Yesus,<br/>serupa Dia;<br/>Atas perbuatan,<br/>tampil citra-Nya.<br/>',NULL,62624,2);
INSERT INTO stanza VALUES('I477','3','Giat menghadap Tuhan,<br/>Dia yang memimpin,<br/>Terjadi apa pun,<br/>tak dului Dia;<br/>Senang atau sedih,<br/>t''rus ikut Tuhan,<br/>Percaya firman-Nya,<br/>t''rus pandang Yesus.<br/>',NULL,62625,3);
INSERT INTO stanza VALUES('I477','4','Giat menghadap Tuhan,<br/>hati perlu t''nang;<br/>Dia yang mengurus,<br/>angan dan sifat.<br/>Roh-Nya membawamu,<br/>ke sumber kasih,<br/>Kau layak bekerja,<br/>karya surgawi.<br/>',NULL,62626,4);
INSERT INTO stanza VALUES('I478','1','Hai prajurit Kristus, ke depan maju,<br/>Dulu andal diri, tak mudah menang;<br/>Jangan andal diri, sandar kuasa Kristus;<br/>Dalam Kristus Sang Kuat, mampu lakukan s''mua.<br/>',NULL,62627,1);
INSERT INTO stanza VALUES('I478','2','Hari-hari tugas,<br/>''tuk keadilan,<br/>Apa sering letih,<br/>tak mudah tahan?<br/>Harus sandar Tuhan,<br/>Dia pikul s''mua beban;<br/>Dalam Kristus Sang Kuat,<br/>mampu lakukan s''mua.<br/>',NULL,62628,2);
INSERT INTO stanza VALUES('I478','3','Letih tengah jalan,<br/>Dia pasti papah,<br/>Baik engkau senang,<br/>maupun susah;<br/>Lewat air dan api,<br/>lewat dengan aman;<br/>Dalam Kristus Sang Kuat,<br/>mampu lakukan s''mua.<br/>',NULL,62629,3);
INSERT INTO stanza VALUES('I478','4','Di dunia yang jahat,<br/>banyak ujian;<br/>Kau tak perlu jatuh,<br/>Iblis larilah;<br/>Dia pasti gagal,<br/>asal kau katakan:<br/>Dalam Kristus Sang Kuat,<br/>mampu lakukan s''mua.<br/>',NULL,62630,4);
INSERT INTO stanza VALUES('I478','5','Kuasa Kristus luas,<br/>lebihi lautan;<br/>Dia tolong d''ngan tuntas,<br/>tanggung semua;<br/>Kurnia serba cukup,<br/>tudungi yang lemah;<br/>Dalam Kristus Sang Kuat,<br/>mampu lakukan s''mua.<br/>',NULL,62631,5);
INSERT INTO stanza VALUES('I479','1','Pikirkan Yesus, Dia-lah teladan,<br/>agar atasmu nyata mulia-Nya,<br/>Dia t''lah kurniakan hayat yang kekal,<br/>biar kau nikmat kuasa kebangkitan.<br/>',NULL,62632,1);
INSERT INTO stanza VALUES('I479','2','Pikirkan Yesus, hari ke hari,<br/>rendahkan diri, tak berambisi,<br/>Makin mengenal hayat almuhit,<br/>alami Dia dalam kuasa bangkit.<br/>',NULL,62633,2);
INSERT INTO stanza VALUES('I479','3','Pikirkan Yesus, sepanjang usia,<br/>hidup di balik tirai serta-Nya,<br/>Menyangkal diri - kenal murad-Nya,<br/>lepaskan diri - kudus, sentosa.<br/>',NULL,62634,3);
INSERT INTO stanza VALUES('I479','4','Pikirkan Yesus, saat kau maju,<br/>pandang wajah mulia Tuhan s''lalu,<br/>Makin mulia serupa Tuhan,<br/>hingga atasmu Dia ternyata.<br/>',NULL,62635,4);
INSERT INTO stanza VALUES('I480','1','Bisakah kau patuh<br/>pada Tuhan-mu,<br/>Meski dunia guncang,<br/>langit bergolak?<br/>Bisakah beriman,<br/>Allah beserta,<br/>Biar sengsara tiba,<br/>kau tak celaka?<br/>',NULL,62636,1);
INSERT INTO stanza VALUES('I480','2','Bisakah kau patuh,<br/>pada Tuhan-mu,<br/>Tanpa lemah, ragu,<br/>maju selalu?<br/>Meski di depan-Mu,<br/>maut menunggu,<br/>Bisakah kau patuh,<br/>sandar Tuhan-mu?<br/>',NULL,62637,2);
INSERT INTO stanza VALUES('I480','3','Bisakah kau patuh,<br/>bila Dia suruh,<br/>Ke medan yang rusuh<br/>dan banyak musuh?<br/>Bisakah kau teguh,<br/>senang diutus?<br/>Bisakah bertempur,<br/>di malam larut?<br/>',NULL,62638,3);
INSERT INTO stanza VALUES('I480','4','Bisakah, Saudara?<br/>Allah nantikan,<br/>Kau patuh kuasa-Nya,<br/>taat p''rintah-Nya.<br/>Bila kau berjuang,<br/>hingga menang p''rang,<br/>Kau ''kan Tuhan bilang,<br/>"Hamba yang setia!"<br/>',NULL,62639,4);
INSERT INTO stanza VALUES('I481','1','Tuhan sudah dekat,<br/>janganlah kuatir;<br/>Percaya janji-Nya,<br/>janganlah goyah;<br/>Janganlah kau lengah<br/>dan kurang tertib;<br/>Yesus seg''ra datang,<br/>mungkin sekarang.<br/>',NULL,62640,1);
INSERT INTO stanza VALUES('I481','2','Janganlah kau kuatir,<br/>s''rahkan pada-Nya;<br/>Ia tanggung dosamu,<br/>juga bebanmu;<br/>T''rus maju ke depan,<br/>sambil ''nyatakan:<br/>"Cinta Tuhan manis,<br/>tangan-Nya teguh."<br/>',NULL,62641,2);
INSERT INTO stanza VALUES('I481','3','Janganlah kau kuatir,<br/>meski Ia lambat;<br/>Kuasa-Nya t''rus bantu,<br/>s''panjang hidupmu;<br/>Kau boleh percaya<br/>dan bersandar Dia;<br/>Takut akan apa?<br/>Majulah saja!<br/>',NULL,62642,3);
INSERT INTO stanza VALUES('I482','1','Janji Allah takkan nihil,<br/>teguh seluruhnya;<br/>Iman tak menuntut bukti,<br/>sabda-Nya pasti g''nap.<br/>',NULL,62643,1);
INSERT INTO stanza VALUES('I482','chorus','Langit, bumi terbakar;<br/>bukit, gunung terbongkar;<br/>Yang beriman pada-Nya,<br/>nampak g''nap janji-Nya.<br/>',NULL,62644,2);
INSERT INTO stanza VALUES('I482','2','Hati seperti Abraham,<br/>pandang ke angkasa,<br/>Hitung bintang, tambah iman,<br/>remeh kesulitan.<br/>',NULL,62645,3);
INSERT INTO stanza VALUES('I482','3','Meski awan tebal datang,<br/>surya tak berubah;<br/>Tunggulah sejenak saja,<br/>sinarnya pancarlah.<br/>',NULL,62646,4);
INSERT INTO stanza VALUES('I482','4','Ujian di dapur api,<br/>apa kecil hati?<br/>Putra mulia dampingi,<br/>musuh gigit jari.<br/>',NULL,62647,5);
INSERT INTO stanza VALUES('I482','5','Meski teman berkhianat,<br/>tetaplah beriman;<br/>Yesus justrulah tenaga,<br/>dekat pun b''ri rahmat.<br/>',NULL,62648,6);
INSERT INTO stanza VALUES('I482','6','Sandar pada kuasa Allah,<br/>hingga hari t''rangkat;<br/>Iman dan harapan s''karang,<br/>kelak pasti nyata.<br/>',NULL,62649,7);
INSERT INTO stanza VALUES('I483','1','Maju! Semboyanku,<br/>d''rap langkah laju;<br/>Menuju sasaran,<br/>maju selalu.<br/>Tiang api menyala,<br/>t''rangi jalanku;<br/>Kristus sedang pimpin,<br/>apa ku takut!<br/>Maju lewat padang,<br/>tahan dalam p''rang;<br/>Kanaan t''lah nyata,<br/>Sion bercah''ya t''rang.<br/>',NULL,62650,1);
INSERT INTO stanza VALUES('I483','2','Mulia tambah mulia,<br/>Allah sediakan;<br/>Berbagian dalamnya,<br/>yang cinta Allah;<br/>Meski belum nampak,<br/>b''lum pernah dengar,<br/>Pun b''lum terpikirkan,<br/>b''tapa mulianya.<br/>Maju! Terus maju!<br/>Capai k''rajaan,<br/>Hingga iman kita<br/>jadi k''nyataan.<br/>',NULL,62651,2);
INSERT INTO stanza VALUES('I483','3','Maju! T''lah t''rang tanah,<br/>k''rajaan tiba;<br/>Yerusalem surga,<br/>tunggu kau nikmat.<br/>Masuk bebas, mulia,<br/>pakai mahkota,<br/>D''ngan Kristus meraja,<br/>sampai s''lamanya.<br/>Tamatkan jalanmu,<br/>capai tempuhan,<br/>Sandar kuat kuasa-Nya,<br/>masuk k''rajaan.<br/>',NULL,62652,3);
INSERT INTO stanza VALUES('I484','1','Maju ke sasaran!<br/>Meski k''liling senyap;<br/>P''lopormu sedang memanggil,<br/>maju jangan lambat.<br/>',NULL,62653,1);
INSERT INTO stanza VALUES('I484','2','Maju ke sasaran!<br/>Tuhan mengawasi;<br/>Manusia terbilang apa,<br/>jangan kau peduli!<br/>',NULL,62654,2);
INSERT INTO stanza VALUES('I484','3','Maju ke sasaran!<br/>Jangan tengok b''lakang;<br/>Depan tersedia mahkota,<br/>Tuhan siap berikan.<br/>',NULL,62655,3);
INSERT INTO stanza VALUES('I484','4','Maju ke sasaran!<br/>S''mua jangan hiraukan;<br/>Jalan penuh cucur darah,<br/>maju ikut Tuhan.<br/>',NULL,62656,4);
INSERT INTO stanza VALUES('I485','beginning-note','Syair Kesatu<br/>',NULL,62657,1);
INSERT INTO stanza VALUES('I485','1','Sandar kurnia Sang Kuasa, majulah!<br/>Majulah! Iman pegang janji-Nya, majulah!<br/>Tak k''lana di tanah Ham, Mesir kami tinggalkan;<br/>Maju tanpa berpaling, majulah!<br/>',NULL,62658,2);
INSERT INTO stanza VALUES('I485','2','Meski musuh mengejar, majulah!<br/>Majulah! Depan laut menghadang, majulah!<br/>Laut sibak niscaya, lawan-lawan terbenam;<br/>Jaya oleh kurnia, majulah!<br/>',NULL,62659,3);
INSERT INTO stanza VALUES('I485','3','Tiang asap membimbing, majulah!<br/>Majulah! Tiang api terangi, majulah!<br/>Lapar, manna turunlah, haus batu terbelah;<br/>Musuh pasti ''kan kalah, majulah!<br/>',NULL,62660,4);
INSERT INTO stanza VALUES('I485','4','Jalan gurun bahaya, majulah!<br/>Majulah! Ikut Tabut Perjanjian, majulah!<br/>Sampai seberang Yordan, maju masuk<br/>Kanaan; Maju, mencapai Sion, majulah!<br/>',NULL,62661,5);
INSERT INTO stanza VALUES('I485','beginning-note','Syair Kedua<br/>',NULL,62662,6);
INSERT INTO stanza VALUES('I485','1','Jangan terpikat dunia, majulah!<br/>Majulah! Lepas beban dan dosa, majulah!<br/>Allah panggil, kuduslah; Kristus menjadi hayat;<br/>Roh Kudus jadi kuasa, majulah!<br/>',NULL,62663,7);
INSERT INTO stanza VALUES('I485','2','Jangan tengok belakang, majulah!<br/>Majulah! Jangan hentikan langkah, majulah!<br/>Tatap Yesus Penunjang, kaki tangan pun kuat;<br/>Kian maju kian perkasa, majulah!<br/>',NULL,62664,8);
INSERT INTO stanza VALUES('I485','3','Berani sampai final, majulah!<br/>Majulah! Hingga capai sasaran, majulah!<br/>Sampai fajar merekah, tertampak kerajaan;<br/>Maju! T''rima mahkota, majulah!<br/>',NULL,62665,9);
INSERT INTO stanza VALUES('I486','1','Siaga, malam t''lah larut! Jangan cinta dunia;<br/>Siaga, fajar ''kan m''rekah! Jangan terlelap.<br/>Siaga, Tuhan sg''ra datang! Ikatlah pinggangmu;<br/>Siaga, Tuhan menunggu! Janganlah kendur.<br/>',NULL,62666,1);
INSERT INTO stanza VALUES('I486','2','Siaga, bangun ''layani! Waktu seg''ra habis;<br/>Siaga, datang bekerja! Umur sg''ra usai.<br/>Siaga, angkat senjata! Dalam roh tegaplah;<br/>Siaga, lawanlah setan! Hati tak goyah.<br/>',NULL,62667,2);
INSERT INTO stanza VALUES('I486','3','Siaga, tunggu Dia datang! Tunggu Bintang Fajar,<br/>Siaga, cari k''rajaan! Mulia di depan.<br/>Siaga, dan waspadalah! Menunggu Dia datang;<br/>Siaga sampailah fajar! Hingga Dia datang.<br/>',NULL,62668,3);
INSERT INTO stanza VALUES('I487','1','Latih gunakan roh,<br/>jiwa ditolak,<br/>Hidup, perilaku,<br/>inilah kunci.<br/>',NULL,62669,1);
INSERT INTO stanza VALUES('I487','2','Latih gunakan roh,<br/>dogma dicampak,<br/>Taat urapan Roh,<br/>''tiasa tak sekat.<br/>',NULL,62670,2);
INSERT INTO stanza VALUES('I487','3','Latih gunakan roh,<br/>ego disangkal,<br/>Hidup dalam terang,<br/>Tuhan s''galanya.<br/>',NULL,62671,3);
INSERT INTO stanza VALUES('I487','4','Latih gunakan roh,<br/>jiwa diingkar,<br/>Panjat puji syukur,<br/>beres segala.<br/>',NULL,62672,4);
INSERT INTO stanza VALUES('I487','5','Latih gunakan roh,<br/>Tuhan leluasa,<br/>Latih gunakan roh,<br/>limpah ku nikmat.<br/>',NULL,62673,5);
INSERT INTO stanza VALUES('I487','6','Latih gunakan roh,<br/>menjamah Tuhan,<br/>Latih gunakan roh,<br/>ku dibangunkan.<br/>',NULL,62674,6);
INSERT INTO stanza VALUES('I487','7','Latih gunakan roh,<br/>ini mau-Nya,<br/>Latih gunakan roh,<br/>mulia bagi-Nya.<br/>',NULL,62675,7);
INSERT INTO stanza VALUES('I488','1','Mengapa pelit segenggam?<br/>Beri ''tuk nabi dulu,<br/>Takaran diatur Allah,<br/>apa asat sumber-Mu?<br/>Tiap hari ada perlu,<br/>tiap hari suplai baru,<br/>Kau ini ciptaan tuhan,<br/>mustahil tak diurus.<br/>',NULL,62676,1);
INSERT INTO stanza VALUES('I488','chorus','Tetap kasih, tetap beri,<br/>tetap masih segenggam,<br/>Tiap kasih, tiap beri,<br/>Allah b''ri lipat kali.<br/>',NULL,62677,2);
INSERT INTO stanza VALUES('I488','2','Yakin! Saatnya tak tunda,<br/>tak cepat pun tak lambat,<br/>Yakin! Botol takkan asat,<br/>tak kosong pun tak luap,<br/>Andai bakung perlu jubah,<br/>burung perlu makanan,<br/>Tapi s''dikit tepung janda,<br/>masih segenggam ada.<br/>',NULL,62678,3);
INSERT INTO stanza VALUES('I488','3','Untuk apa kuatir esok?<br/>Kini cukup, giranglah;<br/>Jangan pinjam kuatir esok,<br/>tangan ada segenggam.<br/>Hidup kasih, banyak beri,<br/>makin banyak terima,<br/>Seolah Anda tak punya,<br/>lihat! Masih segenggam.<br/>',NULL,62679,4);
INSERT INTO stanza VALUES('I489','1','Kau rasa kasih Allah?<br/>Bukan hanya ini!<br/>Kau kecap rahmat Allah?<br/>Bukan hanya ini!<br/>Kasih Allah berlimpah,<br/>bukan hanya ini!<br/>Dib''rikan cuma-cuma,<br/>bukan hanya ini!<br/>',NULL,62680,1);
INSERT INTO stanza VALUES('I489','chorus','Berlebih, berlebih!<br/>Bukan hanya ini!<br/>Kasih-Nya tak terperi!<br/>Bukan hanya ini!<br/>',NULL,62681,2);
INSERT INTO stanza VALUES('I489','2','Kau rasakan Dia dekat?<br/>Bukan hanya ini!<br/>Kau senang ''kan hadir-Nya?<br/>Bukan hanya ini!<br/>Kur-nia-Nya sungguh limpah,<br/>bukan hanya ini!<br/>Dib''rikan cuma-cuma,<br/>bukan hanya ini!<br/>',NULL,62682,3);
INSERT INTO stanza VALUES('I489','3','Kau rasa kua-sa Roh-Nya?<br/>Bukan hanya ini!<br/>P''ri hujan mendirismu?<br/>Bukan hanya ini!<br/>Kua-sa Roh sungguh hebat,<br/>bukan hanya ini!<br/>Dib''rikan cuma-cuma,<br/>bukan hanya ini!<br/>',NULL,62683,4);
INSERT INTO stanza VALUES('I490','1','Di dalam kasih surga,<br/>tak takut p''ru-bah-an,<br/>Yakin sedemi-ki-an,<br/>tak ada yang ubah.<br/>Meski angin menerpa,<br/>bagai tiada harap,<br/>Allah tetap menjaga,<br/>meng-a-pa ku bimbang?<br/>',NULL,62684,1);
INSERT INTO stanza VALUES('I490','2','Meski miskin mengganggu,<br/>Tuhan yang memimpin,<br/>Mustahil kekurangan,<br/>gembala di samping.<br/>Hati hikmat-Nya jaga,<br/>waspada mata-Nya,<br/>Jalan-Nya Di-a paham,<br/>ku ikut tak lengah.<br/>',NULL,62685,2);
INSERT INTO stanza VALUES('I490','3','Padang rumput di depan,<br/>ku b''lum pernah nampak,<br/>Tak lama langit cerah,<br/>meski kini kelam.<br/>Harapku sungguh panjang,<br/>jalanku pun terang,<br/>Tuhan pegang tanganku,<br/>berjalan denganku.<br/>',NULL,62686,3);
INSERT INTO stanza VALUES('I490','4','Mungkin sebelum fajar,<br/>rohku tidak sabar,<br/>Lepas daging dan s''gala,<br/>Tuhan ''kan beserta.<br/>Sabat! Tidur! Mustika,<br/>bawah na-ung-an-Nya.<br/>Tiba-tiba Kau datang,<br/>jumpa depan takhta.<br/>',NULL,62687,4);
INSERT INTO stanza VALUES('I490','5','Sa-at itu jumpa-Mu,<br/>dihimpit umat-Mu,<br/>Sungguh mu-lia pun indah,<br/>bernyanyi tak sudah.<br/>Hari janji yang a-jaib,<br/>dengan Kau bersama,<br/>Kekal nikmat sabat-Nya,<br/>kekal girang, pu-as.<br/>',NULL,62688,5);
INSERT INTO stanza VALUES('I491','1','"Ku ''kan besertamu",<br/>janji yang indah,<br/>menghibur hatiku,<br/>hilangkan gentar;<br/>Dalam malam kelam,<br/>Tuhan-lah p''risai,<br/>Dia s''lalu jagaku,<br/>bahkan sertaku.<br/>',NULL,62689,1);
INSERT INTO stanza VALUES('I491','chorus','Tuhan sertaku,<br/>Tuhan sertaku,<br/>Dia janji s''lalu sertaku,<br/>S''lama tak tinggalkanku,<br/>s''lama tak tinggalkanku.<br/>',NULL,62690,2);
INSERT INTO stanza VALUES('I491','2','Walau bunga gugur,<br/>kasih-Nya teguh,<br/>walau surya redup,<br/>Dia terang s''lalu.<br/>Tuhan bagaikan mur,<br/>pada dadaku,<br/>hingga fajar m''rekah,<br/>Dia besertaku.<br/>',NULL,62691,3);
INSERT INTO stanza VALUES('I491','3','Meski jalan susah,<br/>banyak cobaan,<br/>tapi Tuhan serta,<br/>aku tenanglah.<br/>Riang bagai terbang,<br/>masuk hatiku,<br/>ku menyanyi ''tiasa,<br/>"Dia besertaku."<br/>',NULL,62692,4);
INSERT INTO stanza VALUES('I492','1','Bawah Tuhan, ku tinggal dengan tent''ram,<br/>tak peduli gelap atau hujan;<br/>Ku bersandar kar''na Dia pasti jaga,<br/>Dia selamatkanku, ku anak-Nya.<br/>',NULL,62693,1);
INSERT INTO stanza VALUES('I492','chorus','Bawah Tuhan, bawah Tuhan,<br/>siapa mampu pisahkan!<br/>Bawah Tuhan, ini rumahku,<br/>Tuhan s''lama sertaku.<br/>',NULL,62694,2);
INSERT INTO stanza VALUES('I492','2','Bawah Tuhan, terhindar kesedihan,<br/>hati puas, dapat perhentian,<br/>Dunia tak dapat sembuhkan lukaku,<br/>di sini t''rima berkat, hiburan.<br/>',NULL,62695,3);
INSERT INTO stanza VALUES('I492','3','Bawah Tuhan, kenikmatan yang indah,<br/>di sini t''rus sampai ujian lewat;<br/>Dalam naungan Tuhan tak perlu g''lisah,<br/>dalam Tuhan ku tak kuatir s''lama.<br/>',NULL,62696,4);
INSERT INTO stanza VALUES('I493','1','Tinggal bawah naungan-Nya,<br/>kau pasti Dia jaga,<br/>Jangan takut s''gala susah,<br/>kau pasti Dia jaga.<br/>',NULL,62697,1);
INSERT INTO stanza VALUES('I493','chorus','Kau pasti Dia jaga setiap waktu,<br/>Dia menjaga,<br/>Kau pasti Dia jaga,<br/>kau pasti Dia jaga.<br/>',NULL,62698,2);
INSERT INTO stanza VALUES('I493','2','Walau hatimu gelisah,<br/>kau pasti Dia jaga,<br/>Meski banyak kejahatan,<br/>kau pasti Dia jaga.<br/>',NULL,62699,3);
INSERT INTO stanza VALUES('I493','3','Allah mendengar doamu,<br/>kau pasti Dia jaga,<br/>Dia sediakan s''mua perlumu,<br/>kau pasti Dia jaga.<br/>',NULL,62700,4);
INSERT INTO stanza VALUES('I493','4','Waktu godaan menimpa,<br/>kau pasti Dia jaga,<br/>Saat lelah, sandarlah Dia,<br/>kau pasti Dia jaga.<br/>',NULL,62701,5);
INSERT INTO stanza VALUES('I494','1','Bila ujian berat ''nimpa padamu,<br/>Kau rasa kecewa, jalanmu buntu;<br/>Perinci kurnia-Nya satu persatu,<br/>Rawatan-Nya pasti bikin kau takjub.<br/>',NULL,62702,1);
INSERT INTO stanza VALUES('I494','chorus','Perincilah satu persatu!<br/>Betapa Dia telah mengasuh!<br/>Perincilah satu persatu!<br/>Rawatan-Nya pasti bikin kau takjub.<br/>',NULL,62703,2);
INSERT INTO stanza VALUES('I494','2','Saat rasa kuatir, kau kecil hati,<br/>Terhadap salibmu kau rasa ''ngeri;<br/>Asalkan kurnia-Nya kau perinci,<br/>Bimbangmu berganti pujian pasti!<br/>',NULL,62704,3);
INSERT INTO stanza VALUES('I494','3','Duniawi orang lain maju dan laju,<br/>Ingat janji-Nya, tak goyah hatimu,<br/>Berkat tak terbeli sudah milikmu,<br/>Rumah Bapa, kasih Tuhan sepenuh.<br/>',NULL,62705,4);
INSERT INTO stanza VALUES('I494','4','Godaan yang besar maupun yang kecil,<br/>Tuhan tentu hadir sama menjinjing,<br/>Perinci kurnia, m''laikat dampingi,<br/>Melayani sampai tempuhan akhir.<br/>',NULL,62706,5);
INSERT INTO stanza VALUES('I495','1','Jalan jauh, pikulan berat<br/>ingin ''ngaso di rumah,<br/>Dengar, bisikan-Nya ramah,<br/>"Beban s''rah pada TUHAN!"<br/>',NULL,62707,1);
INSERT INTO stanza VALUES('I495','chorus','"Beban s''rah pada TUHAN!"<br/>"Beban s''rah pada TUHAN!"<br/>Dia ''kan menghibur dan meneguhkan,<br/>beban s''rah pada TUHAN!<br/>',NULL,62708,2);
INSERT INTO stanza VALUES('I495','2','Tangan, kaki, lesu lemah,<br/>mata muram berkunang;<br/>Hati hampir putus asa,<br/>beban s''rah pada TUHAN!<br/>',NULL,62709,3);
INSERT INTO stanza VALUES('I495','3','Sanak k''rabat berpencaran,<br/>hati pilu gelisah,<br/>Jasmani pun menderita,<br/>beban s''rah pada TUHAN!<br/>',NULL,62710,4);
INSERT INTO stanza VALUES('I495','4','Terpencil tiada teman,<br/>hati sedih dan gundah,<br/>Kar''na kita telah lupa,<br/>beban s''rah pada TUHAN!<br/>',NULL,62711,5);
INSERT INTO stanza VALUES('I495','5','Dia pasti b''ri rawat, papah,<br/>biar tenagamu tambah,<br/>Dia mau hatimu tent''ram,<br/>beban s''rah pada TUHAN!<br/>',NULL,62712,6);
INSERT INTO stanza VALUES('I496','1','Waktu ku jumpa godaan,<br/>lewat rintangan yang dahsyat,<br/>Timbullah ingatan mesra,<br/>Tuhan ingat aku.<br/>',NULL,62713,1);
INSERT INTO stanza VALUES('I496','chorus','Tuhan ingat aku!<br/>Tuhan ingat aku!<br/>Apakah yang ku takutkan?<br/>Tuhan ingat aku!<br/>',NULL,62714,2);
INSERT INTO stanza VALUES('I496','2','Dunia penuh kekuatiran,<br/>hingga pikiranku gelap,<br/>Tapi untung sg''ra ku sadar:<br/>Tuhan ingat padaku!<br/>',NULL,62715,3);
INSERT INTO stanza VALUES('I496','3','Meski awan gelap datang,<br/>dalam duka maupun senang,<br/>Hatiku puas, kar''na ku ta''u,<br/>Dia ingat padaku!<br/>',NULL,62716,4);
INSERT INTO stanza VALUES('I497','1','B''tapa agung, nama-Mu, ya, Allah!<br/>Aku terlindung dengan sentosa;<br/>Siang panjang, malam gelap pekat,<br/>Tapi cukuplah bila Kau serta.<br/>',NULL,62717,1);
INSERT INTO stanza VALUES('I497','2','Meski sek''lilingku sunyi senyap,<br/>Pula banyak hal rumit dan kacau;<br/>Cukuplah, jika Allah beserta,<br/>Ku dapat menyanyi dan bersorak.<br/>',NULL,62718,2);
INSERT INTO stanza VALUES('I497','3','Allah, Tuhan-ku, Kau kaya limpah!<br/>Kau mampu p''nuhi s''mua kekurangan;<br/>Pada jalan sempit dan bahaya;<br/>Kau pimpinku dengan kasih sayang.<br/>',NULL,62719,3);
INSERT INTO stanza VALUES('I497','4','Demi iman kini aku rebah,<br/>Ke pangkuan-Mu yang sangat hangat;<br/>Sambil s''lalu syukur dan bergita,<br/>Kar''na pimpinan-Mu amat indah.<br/>',NULL,62720,4);
INSERT INTO stanza VALUES('I498','1','''Tiasa bawa nama Yesus,<br/>hai yang susah dan duka,<br/>Dia berimu damai, tent''ram,<br/>singkir semua d''rita.<br/>',NULL,62721,1);
INSERT INTO stanza VALUES('I498','chorus','Nama-Nya, mustika!<br/>B''ri harapan dan riang!<br/>Nama-Nya mustika!<br/>B''ri harapan dan riang!<br/>',NULL,62722,2);
INSERT INTO stanza VALUES('I498','2','''Tiasa bawa nama Yesus,<br/>perisai t''radap lawan,<br/>Saat musuh mengganggumu,<br/>seg''ra seru nama-Nya.<br/>',NULL,62723,3);
INSERT INTO stanza VALUES('I498','3','Saat kasih-Nya menghibur,<br/>mulutku pun nyanyilah,<br/>Nama-Nya sangat berharga,<br/>membuat hatiku girang.<br/>',NULL,62724,4);
INSERT INTO stanza VALUES('I498','4','Saat t''rangkat jumpa Tuhan,<br/>nama Yesus tetaplah,<br/>Sembah sujud di depan-Nya,<br/>Dia-lah Raja di raja.<br/>',NULL,62725,5);
INSERT INTO stanza VALUES('I499','1','Bukan aku, melainkan Tuhan,<br/>hanya ini yang tenangkan hati;<br/>Kasih-Mu (bukan ''ku), singkir ragu,<br/>tenangkan hati yang bergemuruh.<br/>',NULL,62726,1);
INSERT INTO stanza VALUES('I499','2','Dia berkati sampai selamanya,<br/>Dia s''lamatkan juga selamanya.<br/>Dia papahku dalam perjalanan,<br/>Dia pimpinku lewati bahaya.<br/>',NULL,62727,2);
INSERT INTO stanza VALUES('I499','3','Tuhan, Allah-ku, ku mengenal-Mu,<br/>hatiku tenang, mulut p''nuh pujian,<br/>Kau-lah hayat, senang, dan tongkatku,<br/>sandar pada-Mu lemah jadi kuat.<br/>',NULL,62728,3);
INSERT INTO stanza VALUES('I499','4','Aku miskin, haus,<br/>hati damba kemesraan yang sulit didapat;<br/>Yang damba berangsur-angsur pergi,<br/>tingggal kekosongan untuk damba.<br/>',NULL,62729,4);
INSERT INTO stanza VALUES('I499','5','Tuhan Allah-ku, ''moga Kau<br/>makin wahyukan kemuliaan diri-Mu.<br/>Kau makin banyak dalam kurnia,<br/>diri-Mu banyak beriku rahmat.<br/>',NULL,62730,5);
INSERT INTO stanza VALUES('I500','1','Allah yang berdaulat mutlak,<br/>aku senang,<br/>Bila yang lain yang gantikan,<br/>atau aku yang merawat,<br/>Ku berkeluh.<br/>Ku berkesah.<br/>',NULL,62731,1);
INSERT INTO stanza VALUES('I500','2','Kalau cemas hari esok,<br/>kini ''nimpa,<br/>Tanpa memberi pertanda,<br/>mana yang baik ku tak jelas,<br/>Sulit doa.<br/>Sulit doa.<br/>',NULL,62732,2);
INSERT INTO stanza VALUES('I500','3','Kar''na pandanganku kabur,<br/>malah aman,<br/>Ku meraba dalam gelap,<br/>namun suara-Nya terdengar,<br/>Dia dekat.<br/>Dia dekat.<br/>',NULL,62733,3);
INSERT INTO stanza VALUES('I500','4','Rencana-Nya ku tak paham,<br/>tapi ku ta''u;<br/>Senyum-Nya p''ri sinar terang,<br/>kurnia-Nya pimpin terus,<br/>Dalam dunia.<br/>Dalam dunia.<br/>',NULL,62734,4);
INSERT INTO stanza VALUES('I500','5','Ini sudah sangat cukup,<br/>boleh rahat,<br/>Yang mustahil, Dia genapkan,<br/>ada Dia beres semua,<br/>Ku tak cemas.<br/>Ku tak cemas.<br/>',NULL,62735,5);
INSERT INTO stanza VALUES('I501','1','Tent''ram nyaman ku rasa,<br/>dalam pelukan-Nya;<br/>Di sinilah ku dapat<br/>perhentian jiwa.<br/>Dengarlah gita surga,<br/>hibur hati g''lisah;<br/>''Nilah kidung umat-Nya,<br/>ku sambut gembira.<br/>',NULL,62736,1);
INSERT INTO stanza VALUES('I501','chorus','Tentram nyaman ku rasa,<br/>dalam pelukan-Nya;<br/>Di sinilah ku dapat<br/>perhentian jiwa.<br/>',NULL,62737,2);
INSERT INTO stanza VALUES('I501','2','Tentram nyaman ku rasa,<br/>dalam pelukan-Nya;<br/>Di sinilah ku dapat<br/>berkat yang berlimpah.<br/>Meski godaan datang,<br/>sengsara menyerang,<br/>Hatiku tetap tenang,<br/>dalam pelukan-Nya.<br/>',NULL,62738,3);
INSERT INTO stanza VALUES('I501','3','Tentram nyaman ku rasa,<br/>dalam pelukan-Nya;<br/>Di dalam batu karang,<br/>aku s''lalu aman.<br/>Sekarang ku bersabar,<br/>menanti Sang Fajar,<br/>Merekah dan bersinar,<br/>di pantai bahagia.<br/>',NULL,62739,4);
INSERT INTO stanza VALUES('I502','1','Orang yang bersedih, bawa risaumu,<br/>Sujud ibadah depan takhta-Nya,<br/>Papar hati luka dan kesulitan,<br/>Tiada kesedihan yang tak sembuh.<br/>',NULL,62740,1);
INSERT INTO stanza VALUES('I502','2','Girang, dalam sunyi; sesat, t''rang Dia b''ri,<br/>Harapan penyesal - Dia tak ubah,<br/>D''ngan suara lembut Penghibur berkata,<br/>Tiada kesedihan tak terhibur.<br/>',NULL,62741,2);
INSERT INTO stanza VALUES('I502','3','Roti hayat memb''ri gizi pun manis,<br/>Air hayat mengalir dari takhta,<br/>Hadir jamuan kasih, hati terbayang,<br/>Tiada kesedihan tak terlepas.<br/>',NULL,62742,3);
INSERT INTO stanza VALUES('I503','1','Dengar, suara surga bers''ru,<br/>"Genaplah.<br/>" Iman segera membalas,<br/>"Genaplah."<br/>',NULL,62743,1);
INSERT INTO stanza VALUES('I503','chorus','Firman-Nya dari takhta,<br/>ambillah janji Allah,<br/>Dia berkata, "Genaplah",<br/>sahut iman, "Genaplah."<br/>Usai doa, pujian mulai,<br/>haleluya, "Genaplah".<br/>',NULL,62744,2);
INSERT INTO stanza VALUES('I503','2','T''rima kes''lamatan Tuhan,<br/>"Genaplah."<br/>Mutlak persembahkan diri,<br/>"Genaplah."<br/>',NULL,62745,3);
INSERT INTO stanza VALUES('I503','3','Ambil janji penyembuhan,<br/>"Genaplah."<br/>Percaya, bukan p''rasaan,<br/>"Genaplah."<br/>',NULL,62746,4);
INSERT INTO stanza VALUES('I503','4','T''radap janji-Nya, ucapkan,<br/>"Genaplah."<br/>T''radap firman-Nya, mengaku,<br/>"Genaplah."<br/>',NULL,62747,5);
INSERT INTO stanza VALUES('I503','5','T''rima firman dan percaya,<br/>"Genaplah."<br/>Ini rahasia men''rima,<br/>"Genaplah."<br/>',NULL,62748,6);
INSERT INTO stanza VALUES('I504','1','Kaum beriman pejuang, jangan berjuang lagi,<br/>Tidak perlu sengsara, ada yang lebih baik.<br/>',NULL,62749,1);
INSERT INTO stanza VALUES('I504','chorus','Firman-Nya baru terhitung,<br/>o, firman-Nya terhitung,<br/>Aku tak perlu bimbang,<br/>meminta meratap,<br/>Kar''na firman-Nya terhitung,<br/>tenanglah, jangan bingung.<br/>',NULL,62750,2);
INSERT INTO stanza VALUES('I504','2','Taat kehendak Tuhan,<br/>meski nyawa hilang,<br/>Hentikan pertanyaan,<br/>kini putuskanlah.<br/>',NULL,62751,3);
INSERT INTO stanza VALUES('I504','3','Mengapa jatuh bangun,<br/>sandarlah janji-Nya,<br/>Labuhkan sauh iman,<br/>kini tetapkanlah.<br/>',NULL,62752,4);
INSERT INTO stanza VALUES('I504','4','O, kini tak meronta,<br/>berserah pada-Nya,<br/>Kekal percaya Firman,<br/>kini ku berpijak.<br/>',NULL,62753,5);
INSERT INTO stanza VALUES('I505','1','Tuhan, meski k''liling gelap,<br/>gaduh lagi rusuh,<br/>Tapi aku tetap tenang,<br/>cari kehendak-Mu.<br/>',NULL,62754,1);
INSERT INTO stanza VALUES('I505','2','Tuhan penuh kasih sayang,<br/>dan janji yang indah;<br/>Kau tak salah atau lambat,<br/>dan tak pernah dusta.<br/>',NULL,62755,2);
INSERT INTO stanza VALUES('I505','3','Engkau Tuhan yang perkasa,<br/>dan sangat berkuasa;<br/>Ada Tuhan tiada g''lisah,<br/>hati pun damailah.<br/>',NULL,62756,3);
INSERT INTO stanza VALUES('I505','4','Tuhan, hatiku teduhlah,<br/>jiwaku sentosa;<br/>Ada Tuhan cukup sudah,<br/>kar''na Kau segala.<br/>',NULL,62757,4);
INSERT INTO stanza VALUES('I505','5','Tuhan, aku mohon Roh-Mu,<br/>menguatkan imanku;<br/>Biar ku lebih k''nal nama-Mu,<br/>masuk k''limpahan-Mu.<br/>',NULL,62758,5);
INSERT INTO stanza VALUES('I506','1','Dia Allah, Tuhan kami,<br/>Dia tak pernah ingkar janji!<br/>Dia t''lah janji dengan pasti,<br/>kita takut apa lagi?<br/>',NULL,62759,1);
INSERT INTO stanza VALUES('I506','2','Gunung mana tak terdaki?<br/>Laut mana tak terseb''rangi?<br/>Allah mampu mengatasi,<br/>yang bagi orang mustahil.<br/>',NULL,62760,2);
INSERT INTO stanza VALUES('I506','3','Besi dapat Dia apungkan,<br/>laut dapat Dia keringkan;<br/>Waktu laju Dia hentikan,<br/>bagi Allah tiada sukar!<br/>',NULL,62761,3);
INSERT INTO stanza VALUES('I506','4','Laut luas Dia batasi,<br/>ombak ganas, teduh henti;<br/>Pada Allah apa lagi yang<br/>kau kira tidak mungkin?<br/>',NULL,62762,4);
INSERT INTO stanza VALUES('I506','5','Dia cinta kau, ta''u susahmu,<br/>Dia berjanji ''kan mengasuh;<br/>Allah penuh belas kasih,<br/>t''radap umat-Nya yang pedih.<br/>',NULL,62763,5);
INSERT INTO stanza VALUES('I506','6','Allah itu mahaadil,<br/>janji-Nya tentu dig''napi;<br/>Janji Allah dalam Kristus,<br/>semua sungguh, semua amin.<br/>',NULL,62764,6);
INSERT INTO stanza VALUES('I506','7','Allah takkan ingkar janji,<br/>sabda-Nya teguh abadi;<br/>Demi janji Dia genapi,<br/>seruan iman dari hati.<br/>',NULL,62765,7);
INSERT INTO stanza VALUES('I506','8','Kar''na iman bisa nyanyi,<br/>Dia tak pernah ingkar janji!<br/>Dia b''ri apa yang Dia janji,<br/>tak pernah Allah kurangi!<br/>',NULL,62766,8);
INSERT INTO stanza VALUES('I507','1','Tuhan, Kau Nakhodaku,<br/>tempuh gelombang hidup,<br/>Depan lintasan air,<br/>pasir apung, terumbu,<br/>Tuhan berilah kompas,<br/>Tuhan, Kau Nakhodaku.<br/>',NULL,62767,1);
INSERT INTO stanza VALUES('I507','2','Ibu tenangkan anak,<br/>Tuhan teduhkan laut,<br/>Saat Kau katakan, "Diam!"<br/>Ombak badai pun teduh,<br/>Kau sungguh Raja ajaib,<br/>Tuhan, Kau Nakhodaku.<br/>',NULL,62768,2);
INSERT INTO stanza VALUES('I507','3','Saat dekat seberang,<br/>ombak laut berdebur,<br/>Antarku dengan damai,<br/>saat sandar sisi-Mu,<br/>Ku dengar Kau berkata,<br/>"Aku-lah Nakhodamu!"<br/>',NULL,62769,3);
INSERT INTO stanza VALUES('I508','1','S''panjang jalan Tuhan pimpin,<br/>ku minta apa lagi?<br/>Ragukah atas kasih-Nya yang<br/>pimpin s''panjang usia?<br/>Damai surga, hayat kudus,<br/>demi iman ku dapat;<br/>Tiap p''ristiwa ku yakin,<br/>Dia atur yang terbaik;<br/>Tiap p''ristiswa ku yakin,<br/>Dia atur yang terbaik.<br/>',NULL,62770,1);
INSERT INTO stanza VALUES('I508','2','S''panjang jalan Tuhan pimpin,<br/>dorong, tunjang langkahku;<br/>Suplai hayat limpah sungguh,<br/>bantuan tiap waktu;<br/>Walau aku sering goyah,<br/>jiwa rasa dahaga,<br/>Batu karang t''lah terbelah,<br/>suplaikan air hayat,<br/>Batu karang t''lah terbelah,<br/>suplaikan air hayat.<br/>',NULL,62771,2);
INSERT INTO stanza VALUES('I508','3','S''panjang jalan Tuhan pimpin,<br/>kasih-Nya sangat limpah;<br/>Istirahat, Dia janji,<br/>dalam ribaan Bapa.<br/>Mengenakan tubuh mulia,<br/>masuk ke dalam terang,<br/>S''lamanya ku ''kan menyanyi,<br/>"S''panjang jalan Dia pimpin,<br/>"S''lamanya ku ''kan menyanyi,<br/>"S''panjang jalan Dia pimpin."<br/>',NULL,62772,3);
INSERT INTO stanza VALUES('I509','1','Hai, musafir yang berlelah,<br/>yang tempuh jalan mulia;<br/>Allah t''lah b''ri janji indah,<br/>"Ku bimbing d''ngan mataKu."<br/>',NULL,62773,1);
INSERT INTO stanza VALUES('I509','chorus','Aku pasti membimbingmu,<br/>bimbing dengan mata-Ku;<br/>Musafir yang nuju mulia,<br/>Ku bimbing d''ngan mata-Ku."<br/>',NULL,62774,2);
INSERT INTO stanza VALUES('I509','2','Meski hati sering risau,<br/>godaan pun memburu;<br/>Ingat janji-Nya padamu,<br/>"Ku bimbing d''ngan mata-Ku."<br/>',NULL,62775,3);
INSERT INTO stanza VALUES('I509','3','Saat musuh nyaris menang,<br/>teman akrab tinggalkan;<br/>Ingat janji-Nya, menghibur,<br/>"Ku bimbing d''ngan mata-Ku."<br/>',NULL,62776,4);
INSERT INTO stanza VALUES('I509','4','Saat harapanmu pudar,<br/>terkubur oleh waktu;<br/>Ingat janji-Nya, teguhkan,<br/>"Ku bimbing d''ngan mata-Ku."<br/>',NULL,62777,5);
INSERT INTO stanza VALUES('I509','5','Bila ajal jelang tiba,<br/>sg''ra pakai tubuh mulia;<br/>Janji Allah makin jelas,<br/>"Ku bimbing d''ngan mata-Ku."<br/>',NULL,62778,6);
INSERT INTO stanza VALUES('I509','6','Moga Allah jadi riangku,<br/>pun jadi mustikaku;<br/>S''kutu d''ngan Dia, tanpa sekat,<br/>dibimbing d''ngan mata-Nya.<br/>',NULL,62779,7);
INSERT INTO stanza VALUES('I510','1','Saat imanku gagal,<br/>Dia memapahku,<br/>Saat penggoda menang,<br/>Dia memapahku.<br/>',NULL,62780,1);
INSERT INTO stanza VALUES('I510','chorus','Dia memapahku,<br/>Dia memapahku,<br/>Karena Dia cintaku,<br/>Dia memapahku.<br/>',NULL,62781,2);
INSERT INTO stanza VALUES('I510','2','Ku tak dapat berdiri,<br/>papahlah aku,<br/>Karena kasih dingin,<br/>papahlah aku.<br/>',NULL,62782,3);
INSERT INTO stanza VALUES('I510','3','Pandangku p''ri mustika,<br/>Dia memapahku,<br/>S''lamatkan yang Dia gemar,<br/>Dia memapahku.<br/>',NULL,62783,4);
INSERT INTO stanza VALUES('I510','4','Dia tak biarkan ku sedih,<br/>Dia memapahku,<br/>Harga ini Dia bayar,<br/>Dia memapahku.<br/>',NULL,62784,5);
INSERT INTO stanza VALUES('I511','1','Tuhan ta''u kegagalanmu!<br/>Tuhan ta''u kelemahanmu!<br/>Tuhan ta''u s''mua situasimu,<br/>Tuhan sabda: AKu tahu.<br/>',NULL,62785,1);
INSERT INTO stanza VALUES('I511','2','Dia tahu cobaanmu,<br/>tahu kurnia yang kau perlu,<br/>Dia tahu tempuhanmu,<br/>Dia Tuhan-mu, apa takut?<br/>',NULL,62786,2);
INSERT INTO stanza VALUES('I511','3','Meski dihina, ditentang,<br/>dan ditinggal banyak orang,<br/>Tapi Dia tahu s''gala;<br/>Tuhan tahu, kau legalah.<br/>',NULL,62787,3);
INSERT INTO stanza VALUES('I511','4','Beban serah pada Tuhan,<br/>keluh kesah pada Tuhan;<br/>Dia cintamu, ta''u susahmu,<br/>Dia b''ri kurnia dan rawatmu.<br/>',NULL,62788,4);
INSERT INTO stanza VALUES('I511','5','Tuhan tahu, hati puas,<br/>Tuhan tahu, hati girang;<br/>Tuhan tahu, Dia s''lamatkan,<br/>Tuhan tahu, cukup sudah!<br/>',NULL,62789,5);
INSERT INTO stanza VALUES('I512','1','Aku orang pengembara,<br/>tempuh jalan yang jauh;<br/>Meski temui halangan,<br/>kian dekat Bapa.<br/>Tengah jalan awan tebal,<br/>juga ada gangguan,<br/>Kuatir, gundah ''nekan terus,<br/>Bapa-ku tahu.<br/>',NULL,62790,1);
INSERT INTO stanza VALUES('I512','2','Bapa tahu, sangat lega!<br/>Takut ujian apa?<br/>Meski ujian terus kepung,<br/>tak mudah tekun.<br/>Tuhan dekat, aku kuat,<br/>aku tenang, tak goyah!<br/>Sertaan-Nya sungguh manis,<br/>Bapa-ku tahu.<br/>',NULL,62791,2);
INSERT INTO stanza VALUES('I512','3','Tiap hari Bapa tahu,<br/>dalam kasih jagaku;<br/>Datang susah, Dia bantuku,<br/>pandang pada-Nya.<br/>Perjalanan jelang akhir,<br/>hidup ini usailah,<br/>Bagaimana masuk terang,<br/>Bapa tahu s''mua.<br/>',NULL,62792,3);
INSERT INTO stanza VALUES('I512','4','Saat itu di depan-Nya,<br/>nampak wajah kasih-Nya,<br/>Dengan senang sujud sembah,<br/>puji kurnia-Nya.<br/>Depan hadir-Nya nan manis,<br/>tak ada kekuatiran,<br/>Janji Tuhan tergenap s''mua,<br/>Bapa tahu s''mua.<br/>',NULL,62793,4);
INSERT INTO stanza VALUES('I513','1','Begini, begitu, Dia sedia s''lalu;<br/>meski tak seturut mauku atau maumu,<br/>turut mau-Nya m''lulu, Dia sedia s''lalu.<br/>',NULL,62794,1);
INSERT INTO stanza VALUES('I513','chorus','D''ngan hati tent''ram,<br/>sandar pada-Nya.<br/>Kar''na ku tahu,<br/>Dia t''lah sediakan.<br/>',NULL,62795,2);
INSERT INTO stanza VALUES('I513','2','Begini, begitu, Dia sedia s''lalu;<br/>Tak seturut waktuku atau waktumu,<br/>Seturut waktu-Nya, Dia sedia s''lalu.<br/>',NULL,62796,3);
INSERT INTO stanza VALUES('I513','3','Jangan syak hatimu, Dia sedia s''lalu;<br/>Janji Tuhan Yesus, tidak ada satu,<br/>Yang sia-sia bagimu, Dia sedia s''lalu.<br/>',NULL,62797,4);
INSERT INTO stanza VALUES('I513','4','Mari kita maju d''ngan hati teguh;<br/>Laut pasti terbelah, manna pasti turun;<br/>Musuh semua kalah, Dia sedia s''lalu.<br/>',NULL,62798,5);
INSERT INTO stanza VALUES('I514','1','Ku mau nyanyikan janji a-jaib<br/>yang telah Yesus ucapkan,<br/>"Kur-ni-a-Ku cukup kau pa-kai,<br/>kua-sa-Ku s''lalu menunjang.<br/>"Karena takut aku la-lai pada<br/>janji-Nya yang mu-lia,<br/>ulang-ber-u-lang Dia berkata,<br/>"Kur-nia-Ku cukup kau pa-kai."<br/>',NULL,62799,1);
INSERT INTO stanza VALUES('I514','chorus','Sungguh! Tuhan s''lalu berkata,<br/>Kur-nia-Ku cukup kau pa-kai.<br/>Kua-sa-Ku makinlah ternyata,<br/>padamu yang lemah-lung-lai."<br/>',NULL,62800,2);
INSERT INTO stanza VALUES('I514','2','Kur-nia-Nya menyelamatkanku,<br/>lepas dari s''gala dosa;<br/>Kuduskan roh, jiwa, tubuhku,<br/>bahkan penuh Roh Kudus-Mu.<br/>Kur-nia-Nya sanggup membawaku,<br/>lewat co-ba-an terganas;<br/>Janji-Nya menentang s''mua musuh,<br/>"Kur-nia-Ku cukup bagimu."<br/>',NULL,62801,3);
INSERT INTO stanza VALUES('I514','3','Kur-nia-Nya sanggup usir p''nyakit,<br/>memapah dan mengobati;<br/>Kur-nia-Nya bantu ku lewati,<br/>se-mua yang pahit dan getir.<br/>Kur-nia-Nya mampukan ku kerja,<br/>membantu s''mua anak Allah;<br/>Hingga kami se-mua mengerti,<br/>"Kur-nia-Ku cukup bagimu."<br/>',NULL,62802,4);
INSERT INTO stanza VALUES('I514','4','Kur-nia-Nya cukup untuk hidup,<br/>cukup bimbing, cukup tunjang;<br/>T''rangkat atau lewat lembah maut,<br/>kur-nia-Nya cukup menjaga.<br/>Sa-at ku jumpa Jurus''lamat,<br/>sungguh indah, sungguh mu-lia;<br/>Aku bersujud dan mengaku,<br/>"Kur-nia-Mu cukup bagiku."<br/>',NULL,62803,5);
INSERT INTO stanza VALUES('I514','5','Kur-nia kita tak pernah cukup,<br/>yang cukup hanya kur-nia-Nya.<br/>Kur-nia kita sekejap lewat,<br/>kur-nia-Nya kekal tak ubah<br/>Kar''na itu ku ingat terus,<br/>janji yang Tuhan katakan,<br/>"Kua-sa-Ku makinlah ternyata,<br/>atas dirimu yang lemah."<br/>',NULL,62804,6);
INSERT INTO stanza VALUES('I515','1','Bukan kini, tapi nanti;<br/>di sana, bukan di sini;<br/>Kita baru tahu jelas,<br/>arti air mata keluhan.<br/>',NULL,62805,1);
INSERT INTO stanza VALUES('I515','chorus','Sandar Dia, s''panjang usia,<br/>tetap ''muji walau kelam;<br/>Jangan takut, Dia menunjang,<br/>kelak, kita pasti paham.<br/>',NULL,62806,2);
INSERT INTO stanza VALUES('I515','2','Sambunglah benang yang putus,<br/>hidup pasti ada jalan;<br/>Allah mampu menerangkan,<br/>kelak, kita pasti paham.<br/>',NULL,62807,3);
INSERT INTO stanza VALUES('I515','3','M''ngapa awan tutup surya,<br/>susah menggantikan suka,<br/>Keluh melebihi nyanyian?<br/>Kelak, kita pasti paham.<br/>',NULL,62808,4);
INSERT INTO stanza VALUES('I515','4','M''ngapa doa b''lum terjawab?<br/>Terg''nap, namun rasa kurang?<br/>Harapan bagai bayangan?<br/>Kelak, kita pasti paham.<br/>',NULL,62809,5);
INSERT INTO stanza VALUES('I515','5','Allah mengenal jalanku,<br/>Dia bimbing dengan hikmat;<br/>Hari itu ku ''kan nampak,<br/>Dia di sana, ku paham.<br/>',NULL,62810,6);
INSERT INTO stanza VALUES('I516','1','Sandar Yesus, mesra, nyaman,<br/>pegang teguh firman-Nya;<br/>Asal Tuhan beri janji,<br/>''ngaso, janganlah sangsi.<br/>',NULL,62811,1);
INSERT INTO stanza VALUES('I516','chorus','Yesus, Yesus, setia janji,<br/>ku alami sendiri.<br/>Yesus, Yesus, mustikaku,<br/>Allah takkanlah k''liru.<br/>',NULL,62812,2);
INSERT INTO stanza VALUES('I516','2','Sandar Yesus, mesra, nyaman,<br/>alami kuasa darah;<br/>Iman sederhana saja,<br/>semua sakit sirnalah.<br/>',NULL,62813,3);
INSERT INTO stanza VALUES('I516','3','Sandar Yesus, mesra, nyaman,<br/>dosa, diri, terhempas;<br/>Dari-Nya ku t''rima kurnia:<br/>hayat, girang, perhentian.<br/>',NULL,62814,4);
INSERT INTO stanza VALUES('I516','4','Ku bersandar pada Yesus,<br/>Penebus, Mustikaku!<br/>Dengan Kau ku tak terpisah,<br/>sampai s''lama-lamanya.<br/>',NULL,62815,5);
INSERT INTO stanza VALUES('I517','1','Ku tak ta''u masa depan,<br/>mataku tertutup,<br/>Atas setiap langkahku,<br/>suasananya baru,<br/>Sukacita yang Dia beri,<br/>membuat orang takjub.<br/>',NULL,62816,1);
INSERT INTO stanza VALUES('I517','chorus','Ku ikut pimpinan-Nya,<br/>mutlak bersandar Dia,<br/>Tiap saat menyanyikan,<br/>"Dia tahu, Dia tahu",<br/>Tiap saat menyanyikan,<br/>"Dia tahu, Dia tahu".<br/>',NULL,62817,2);
INSERT INTO stanza VALUES('I517','2','Setiap langkah ku nampak,<br/>cukupi keperluan,<br/>Jika buang angan dunia,<br/>terang ''kan memancar,<br/>Dalam ket''nangan terdengar,<br/>"Pada-Ku bersandar."<br/>',NULL,62818,3);
INSERT INTO stanza VALUES('I517','3','Bahagia "orang bodoh",<br/>"tak ta''u" sungguh berkat!<br/>Tangan kanan-Nya genggamku,<br/>tak biarkan ku lepas,<br/>Agar aku tak terkejut,<br/>dalam kasih rahat.<br/>',NULL,62819,4);
INSERT INTO stanza VALUES('I517','4','Meski tak ta''u maju t''rus,<br/>kalau ta''u, ku tak mau,<br/>Tersembunyi jalan d''ngan-Nya,<br/>tak mau sendirian,<br/>Sandar iman jalan d''ngan-Nya,<br/>bukan kar''na m''lihat.<br/>',NULL,62820,5);
INSERT INTO stanza VALUES('I518','1','Sandar Tuhan, sungguhlah bahagia,<br/>pasti t''rima pertolongan;<br/>Kalau dengan ketat ikut Tuhan,<br/>pasti t''rima banyak berkat.<br/>',NULL,62821,1);
INSERT INTO stanza VALUES('I518','chorus','Sandar Tuhan, sandar Tuhan,<br/>akui Dia dalam tindakmu,<br/>Dia pasti membimbingmu.<br/>Sandar Tuhan, sandar Tuhan,<br/>akui Dia dalam tindakmu,<br/>Dia pasti membimbingmu.<br/>',NULL,62822,2);
INSERT INTO stanza VALUES('I518','2','Sandar Tuhan, sungguhlah bahagia,<br/>pasti tempuh jalan surga;<br/>Kalau selalu memandang Tuhan,<br/>pasti melangkah d''ngan tegap.<br/>',NULL,62823,3);
INSERT INTO stanza VALUES('I518','3','Sungguh bah''gia, Sang Bapa menunjang.<br/>Juru-s''lamat pun merawat;<br/>Tinggal bersama Bapa dan Tuhan,<br/>kekal tidak sendirian.<br/>',NULL,62824,4);
INSERT INTO stanza VALUES('I518','4','Sungguh bah''gia, tempuh jalan lurus,<br/>tiap hari maju terus;<br/>Kalau mendapat limpah hadir-Nya,<br/>''kan terbantu tepat waktu.<br/>',NULL,62825,5);
INSERT INTO stanza VALUES('I519','1','Waktu di jalan, ku jumpa godaan,<br/>Iblis berbisik, biar hatiku bimbang;<br/>Tapi meski beban b''rat, ku tak meng''luh,<br/>asal beriman, semuanya ''kan lalu.<br/>',NULL,62826,1);
INSERT INTO stanza VALUES('I519','chorus','Ya, Tuhan-ku, ku percaya!<br/>Mohon Kau kuatkan imanku<br/>''tuk pindahkan gunung;<br/>Ya, Tuhan-ku, ku percaya!<br/>Biar raguku terbenam dalam-Mu.<br/>',NULL,62827,2);
INSERT INTO stanza VALUES('I519','2','Waktu ku berlayar denganlah laju,<br/>mudah ku percaya tangan Tuhan-ku;<br/>Tapi waktu ombak badai memburu,<br/>perlu banyak iman, baru ku teguh.<br/>',NULL,62828,3);
INSERT INTO stanza VALUES('I519','3','Sering ku mendengar orang berkata,<br/>"Hingga ajal, aku tentu setia.<br/>" Tapi sewaktu godaan mengganas,<br/>imannya menghilang, entah ke mana.<br/>',NULL,62829,4);
INSERT INTO stanza VALUES('I519','4','Ada lagi orang sangat bergairah,<br/>m''reka melayani dengan perkasa,<br/>Tapi waktu dosa datang menyerang,<br/>mereka gagal, iman pun melayang.<br/>',NULL,62830,5);
INSERT INTO stanza VALUES('I519','5','Ingatlah s''lalu, dalam hal rohani,<br/>iman tak terasa maupun teraba,<br/>Saat tak nampak sesuatu apa pun,<br/>tetaplah percaya d''ngan hati teguh.<br/>',NULL,62831,6);
INSERT INTO stanza VALUES('I520','1','Segar sep''ri embun pagi,<br/>membawa rasa sejuk;<br/>Demi minyak urapan-Nya,<br/>Kristus berbisik lembut;<br/>Tegap, tahan dalam uji,<br/>ombak, badai, ''kan lewat,<br/>Tegap, bagi mulia Allah,<br/>menang bersama Tuhan.<br/>',NULL,62832,1);
INSERT INTO stanza VALUES('I520','chorus','Sang Harapan,<br/>manislah, suara-Mu!<br/>Di depan-Mu, hatiku p''nuh riang!<br/>',NULL,62833,2);
INSERT INTO stanza VALUES('I520','2','Saat cobaan menimpa,<br/>roh, hatiku tergoyah,<br/>Iman dan bintang harapan,<br/>tiada lagi bersinar.<br/>Moga iman dan kuasa-Mu,<br/>sekuatnya pegangku,<br/>Agar limpah mulia-Mu,<br/>ku nikmati tak putus.<br/>',NULL,62834,3);
INSERT INTO stanza VALUES('I520','3','Sama sep''ri surya fajar,<br/>Tuhan, usirlah gelap,<br/>Demi sinar kesembuhan,<br/>gelap jadilah terang.<br/>Mari, Tuhan P''lipur datang,<br/>pada hati duka, p''nat,<br/>Harapan nan bah''gia mulia,<br/>besertaku s''lamanya.<br/>',NULL,62835,4);
INSERT INTO stanza VALUES('I521','1','Mari, dalam Tuhan kita bergirang,<br/>meski sek''liling p''nuh ancaman;<br/>Mari bergita dengan hati riang,<br/>meski ombak dahsyat menerjang.<br/>',NULL,62836,1);
INSERT INTO stanza VALUES('I521','chorus','Bergirang! Bergirang!<br/>''Tiasa bergirang,<br/>Untung, malang,<br/>nyanyi dengan riang;<br/>Keluh hilang,<br/>maut pun tertelan,<br/>Mari, marilah bergirang!<br/>',NULL,62837,2);
INSERT INTO stanza VALUES('I521','2','Mari, dalam Tuhan kita bergirang,<br/>meski panah api menyerang;<br/>Kar''na Iblis tetap seperti dulu,<br/>dengar suara pujian dia kabur.<br/>',NULL,62838,3);
INSERT INTO stanza VALUES('I521','3','Mari, dalam Tuhan kita bergirang,<br/>meski sakit, jangan mengerang;<br/>Kar''na riang Tuhan itu t''naga menang,<br/>sandar Dia kau pasti ''kan menang.<br/>',NULL,62839,4);
INSERT INTO stanza VALUES('I521','4','Mari, dalam Tuhan kita bergirang,<br/>kemah dunia segera lepas;<br/>Ikut Tuhan ke tempat yang gemilang,<br/>tiada lagi keluh dan kesah.<br/>',NULL,62840,5);
INSERT INTO stanza VALUES('I522','1','Lama dalam sedih, gundah,<br/>kini mundur ke tangan-Mu;<br/>Tak sisa s''dikit pun;<br/>Tangan-Mu seka air mata,<br/>wajahku penuh sinar t''rang,<br/>Tiada tangis duka.<br/>',NULL,62841,1);
INSERT INTO stanza VALUES('I522','2','S''lamat tinggal pelesiran,<br/>senang sia-sia, tak berarti;<br/>Ku tak minat lagi.<br/>Riang sejati pada salib,<br/>sia-sia hiburan yang lain,<br/>Tuhan takdir pasti.<br/>',NULL,62842,2);
INSERT INTO stanza VALUES('I522','3','O, salib! Barulah berkat,<br/>kerugiannya itu berkat;<br/>D''ritanya pun manis!<br/>Pikiran, emosi, tekad,<br/>semua digarap di sini,<br/>Kecap riang s''jati.<br/>',NULL,62843,3);
INSERT INTO stanza VALUES('I522','4','Sayang diri dalam d''rita,<br/>sulit dapat kebaikan;<br/>Lain tiada berkat.<br/>Kasih s''jati, tujuan luhur,<br/>korban diri ia senangi,<br/>D''rita ia sukai.<br/>',NULL,62844,4);
INSERT INTO stanza VALUES('I522','5','Pilihan sama dengan-Mu,<br/>o, kobarkan api kudus,<br/>Biar membara terus!<br/>Pikul salib ikut Tuhan,<br/>kar''na kasih sering puji,<br/>Inilah berkatku.<br/>',NULL,62845,5);
INSERT INTO stanza VALUES('I523','1','Beratlah salib yang Dia beri,<br/>tetapi kurnia lebih;<br/>Badai ombak yang ku takuti,<br/>tutupi Dia, tak mungkin.<br/>',NULL,62846,1);
INSERT INTO stanza VALUES('I523','chorus','Salib tak melampaui kurnia,<br/>badai tak tutupi senyum-Nya;<br/>Hatiku sungguh girang,<br/>ku ta''u Tuhan beserta,<br/>kuasa musuh sirna.<br/>',NULL,62847,2);
INSERT INTO stanza VALUES('I523','2','Duri di jalanku tak s''banding,<br/>mahkota yang berduri;<br/>Cawan getirku tak sepahit,<br/>cawan di Getsemani.<br/>',NULL,62848,3);
INSERT INTO stanza VALUES('I523','3','Cahaya-Nya semakin cerah,<br/>di jalan yang bahaya,<br/>Pikulanku semakin ringan,<br/>bila rela ku t''rima.<br/>',NULL,62849,4);
INSERT INTO stanza VALUES('I523','4','Kini ku hidup di depan-Nya,<br/>rela taat murad-Nya;<br/>Ku tahu dalam s''mua ujian,<br/>berkatlah di dalamnya.<br/>',NULL,62850,5);
INSERT INTO stanza VALUES('I524','1','Aku burung dalam sangkar,<br/>jauh langit, padang luas;<br/>Dia letakkan ku di sini,<br/>syukur pada-Nya tak henti;<br/>Di penjara, tetap senang,<br/>kar''na Allah yang berkenan.<br/>',NULL,62851,1);
INSERT INTO stanza VALUES('I524','2','Dalam penjara menganggur,<br/>setiap hari nyanyi syukur;<br/>Allah yang aku cintai,<br/>dengarkan ku panjat puji;<br/>Meski Dia ikat sayapku,<br/>Dia senang dengar pujianku.<br/>',NULL,62852,2);
INSERT INTO stanza VALUES('I524','3','Allah, telinga-Mu dengar,<br/>hati-Mu b''ri berkat, kasih;<br/>Meskipun suaraku kasar,<br/>tapi Kau tak rasa risih;<br/>Suara ini aku petik dari<br/>hati yang p''nuh kasih.<br/>',NULL,62853,3);
INSERT INTO stanza VALUES('I524','4','Sangkar ini mengunciku,<br/>sulit untuk terbang bebas;<br/>Meski sayapku terikat,<br/>namun roh hatiku lepas;<br/>Penjara tak dapat bendung,<br/>kebebasan roh hatiku.<br/>',NULL,62854,4);
INSERT INTO stanza VALUES('I524','5','Hatiku lampa-i tembok,<br/>rohku terbang bebas lepas!<br/>Memuji Tuhan, kasihku,<br/>kehendak-Nya yang ku sembah;<br/>Dalam murad-Nya yang teguh,<br/>rohku bebas, terbang girang.<br/>',NULL,62855,5);
INSERT INTO stanza VALUES('I525','1','Tembok kukuh sek''liling,<br/>mengurungku ''tiasa;<br/>Tapi yang mengurungku,<br/>tak bisa jauhkan Dia;<br/>Tembok penjara pun indah,<br/>kar''na Allah-ku beserta.<br/>',NULL,62856,1);
INSERT INTO stanza VALUES('I525','2','Yang mengurungku tahu,<br/>sulit pencilkanku;<br/>Tapi m''reka tak tahu,<br/>Allah yang hiburku;<br/>Penjara menjadi terang,<br/>rohku penuh sukacita.<br/>',NULL,62857,2);
INSERT INTO stanza VALUES('I525','3','Kasih-Mu gerakkanku,<br/>keluh jadi pujian;<br/>Dari batin ku sembah,<br/>kapan, di mana pun;<br/>Pasang surut tidak apa,<br/>asal baur dengan murad-Mu.<br/>',NULL,62858,3);
INSERT INTO stanza VALUES('I525','4','Inilah mustikaku,<br/>inilah berkatku;<br/>Kutuk menjadi berkat,<br/>d''rita jadi riang;<br/>Timbul perkara apa pun,<br/>ada Allah sudah cukup.<br/>',NULL,62859,4);
INSERT INTO stanza VALUES('I526','1','Allah tak pernah menjanjikan:<br/>s''panjang hidupmu s''lalu lancar,<br/>Tiada awan, cerah ''tiasa,<br/>tiada susah, girang b''laka.<br/>',NULL,62860,1);
INSERT INTO stanza VALUES('I526','chorus','Tapi perhentian Dia janjikan,<br/>dalam hidup dan jalan kita,<br/>Dalam ujian kau Dia jamin,<br/>simpati dan hiburan Dia b''ri.<br/>',NULL,62861,2);
INSERT INTO stanza VALUES('I526','2','Allah tak pernah menjanjikan,<br/>tiada kuatir dan sengsara!<br/>Dia pun tak janji: ringan saja,<br/>tak usah ''nanggung beban berat.<br/>',NULL,62862,3);
INSERT INTO stanza VALUES('I526','3','Allah tak pernah menjanjikan:<br/>hari depanmu leluasa,<br/>Tak menemui kesulitan,<br/>tak ada gunung dan lautan.<br/>',NULL,62863,4);
INSERT INTO stanza VALUES('I527','1','Tekan berat, tekan hingga tak daya,<br/>berat nian, tiada lagi harap;<br/>Desak jepit hingga ''netes air mata,<br/>sesak nian hingga putus asa.<br/>',NULL,62864,1);
INSERT INTO stanza VALUES('I527','chorus','Allah harapan dan riangku;<br/>Adakan yang tiada, bangkitkan orang!<br/>',NULL,62865,2);
INSERT INTO stanza VALUES('I527','2','Tekan tubuh, hingga tiada tenteram;<br/>tekan hati, sekeliling gelap;<br/>Lawan tekan, kawan juga menekan,<br/>tertekan terus, pupuslah hidup.<br/>',NULL,62866,3);
INSERT INTO stanza VALUES('I527','3','Tekan terus, hingga tiada bantuan;<br/>hingga suka miskin sep''ri kaya;<br/>T''rima sesah bagaikan t''rima hujan;<br/>hingga selain Tuhan tak ku damba.<br/>',NULL,62867,4);
INSERT INTO stanza VALUES('I527','4','Tekan terus, lepas dunia, naik surga;<br/>tertekan hingga tidak terikat;<br/>Percaya Allah mampu melakukan,<br/>hidup mati sandar Tuhan saja.<br/>',NULL,62868,5);
INSERT INTO stanza VALUES('I527','5','Tekan berat, tak tertahan menangis,<br/>tertekan terus, sekuat t''naga;<br/>Hingga tidak bisa ditekan lagi,<br/>selanjutnya dapat rahat kekal.<br/>',NULL,62869,6);
INSERT INTO stanza VALUES('I527','6','"Tekan berat"! Itulah berkat besar;<br/>hingga ternyatalah tangan Allah;<br/>Set''lah itu, orang akan melihat,<br/>walau ditekan tak akan goyang.<br/>',NULL,62870,7);
INSERT INTO stanza VALUES('I527','7','"Tekan berat" kita tetaplah maju;<br/>terus tekan, harap pada Tuhan;<br/>T''rus ditekan, sampai tidak tertahan,<br/>tapi kar''na Allah hati mantap.<br/>',NULL,62871,8);
INSERT INTO stanza VALUES('I528','1','Setelah gelap, datang terang;<br/>setelah lemah, datang kuat;<br/>Setelah rugi, datang untung;<br/>setelah hujan, pasti cerah.<br/>',NULL,62872,1);
INSERT INTO stanza VALUES('I528','2','Setelah sedih, pasti riang;<br/>setelah mati, pasti bangkit;<br/>Setelah lelah, pasti lega;<br/>setelah miskin, pasti kaya.<br/>',NULL,62873,2);
INSERT INTO stanza VALUES('I528','3','Setelah k''lana, pasti tent''ram;<br/>dekat d''ngan Tuhan, sampai jumpa;<br/>Salib menjadi tajuk mulia;<br/>iman, harapan, jadi nyata.<br/>',NULL,62874,3);
INSERT INTO stanza VALUES('I529','1','Allah dalam Taman Eden,<br/>''taruh orang depan pohon;<br/>Pohon hayat wakil Allah,<br/>pengetahuan wakil Satan.<br/>',NULL,62875,1);
INSERT INTO stanza VALUES('I529','2','Pohon hayat inti Allah,<br/>menurut rencana Allah,<br/>Allah damba dalam Kristus,<br/>jadi hayat manusia.<br/>',NULL,62876,2);
INSERT INTO stanza VALUES('I529','3','Pohon pengetahuan tanda,<br/>sumber lain di luar Allah;<br/>Iblis jahat asal maut,<br/>memakannya ''kan binasa.<br/>',NULL,62877,3);
INSERT INTO stanza VALUES('I529','4','Yang terima pohon hayat,<br/>dapat Allah jadi hayat;<br/>Pun jadi batu permata,<br/>murad Allah terlaksana.<br/>',NULL,62878,4);
INSERT INTO stanza VALUES('I529','5','Makan pohon pengetahuan,<br/>Iblis, Satan pasti masuk,<br/>Jadi dosa, datangkan maut,<br/>murad Allah tak tergenap.<br/>',NULL,62879,5);
INSERT INTO stanza VALUES('I529','6','Ini bukti hanya Allah,<br/>sumber unik hayat kita;<br/>Jamah hal di luar Allah,<br/>jamah unsur kematian.<br/>',NULL,62880,6);
INSERT INTO stanza VALUES('I529','7','Pengetahuan bawa maut,<br/>biarpun tampaknya kebaikan;<br/>Semua hal di luar Allah,<br/>ialah rekayasa Satan.<br/>',NULL,62881,7);
INSERT INTO stanza VALUES('I529','8','Kejahatan dan kebaikan,<br/>berlawanan dengan Kristus;<br/>Pengetahuan, baik, jahat,<br/>tak serasi dengan hayat.<br/>',NULL,62882,8);
INSERT INTO stanza VALUES('I529','9','Tuhan biar ku menjamah-Mu,<br/>hingga kami Kau penuhi;<br/>Tak jamah hal di luar-Mu,<br/>yang jahat atau yang baik.<br/>',NULL,62883,9);
INSERT INTO stanza VALUES('I530','1','Hukum Allah di luar insan,<br/>kudus, baik, tapi ''nuntut,<br/>Membuktikan pada insan,<br/>tuntutan-Nya sulit sungguh.<br/>',NULL,62884,1);
INSERT INTO stanza VALUES('I530','2','Di pikiran ada hukum,<br/>tekad ingin berbuat baik,<br/>Di tubuh ada hukum lain,<br/>berlawanan d''ngan yang tadi.<br/>',NULL,62885,2);
INSERT INTO stanza VALUES('I530','3','Hukum pikiran itu baik,<br/>sejak saat diciptakan,<br/>Dari hayat yang tercipta,<br/>kebaikan dilakukan.<br/>',NULL,62886,3);
INSERT INTO stanza VALUES('I530','4','Hukum tubuh itu jahat,<br/>lekat Iblis saat jatuh,<br/>Dari hayat jahat Iblis,<br/>berkuasa lewat maut.<br/>',NULL,62887,4);
INSERT INTO stanza VALUES('I530','5','Hukum dosa tubuh itu,<br/>kalahkan hukum pikiran,<br/>Oleh kuasa jahat Iblis,<br/>manusia ditaklukkan.<br/>',NULL,62888,5);
INSERT INTO stanza VALUES('I530','6','Di dalam roh ada hukum,<br/>yaitu hukum Roh hayat;<br/>Dari kuasa hayat Allah,<br/>dapat saat lahir ulang.<br/>',NULL,62889,6);
INSERT INTO stanza VALUES('I530','7','Hukum hayat yang dalam roh,<br/>lebih kuat dari lainnya,<br/>Lepas dari hukum dosa,<br/>tuntutan hukum Allah g''nap.<br/>',NULL,62890,7);
INSERT INTO stanza VALUES('I530','8','Ku harus ''tiasa letakkan<br/>pikiran di atas rohku,<br/>Tak di atas daging lagi,<br/>hingga lepas dari dosa.<br/>',NULL,62891,8);
INSERT INTO stanza VALUES('I530','9','Pikiran di atas daging,<br/>maut, gelap, menakutkan;<br/>Pikiran di atas rohku,<br/>hayat, damai, bahagia.<br/>',NULL,62892,9);
INSERT INTO stanza VALUES('I530','10','Ini jalan kelepasan,<br/>jalan terbaik jadi kudus!<br/>Biar ku hidup di dalam roh,<br/>jalan serta Tuhan d''ngan roh.<br/>',NULL,62893,10);
INSERT INTO stanza VALUES('I531','1','Hukum harfiah saksi Allah,<br/>menjelaskan diri Allah;<br/>Sangat kudus, sangat adil,<br/>sangat terang, sangat kasih.<br/>',NULL,62894,1);
INSERT INTO stanza VALUES('I531','2','Hukum Allah ''nuntut kita,<br/>tindak sesuai hakiki-Nya;<br/>Hingga Allah b''narkan kita,<br/>demi adil, beri berkat.<br/>',NULL,62895,2);
INSERT INTO stanza VALUES('I531','3','Hukum tak dapat b''ri hayat,<br/>tak dapat suplai tenaga;<br/>Hanya bisa ''nuntut kita,<br/>menyatakan kita lemah.<br/>',NULL,62896,3);
INSERT INTO stanza VALUES('I531','4','Hukum bukan murad Allah,<br/>tapi untuk singkap dosa;<br/>Dilanggar orang, buktikan:<br/>orang penuh dengan dosa.<br/>',NULL,62897,4);
INSERT INTO stanza VALUES('I531','5','Hukum sumbat mulut orang,<br/>kurung orang dalam dosa;<br/>Bawa kita pada Kristus,<br/>dalam Kristus t''rima kurnia.<br/>',NULL,62898,5);
INSERT INTO stanza VALUES('I531','6','Hukum ialah model Kristus,<br/>Kristus saksi riil Allah;<br/>Nyatakan Allah sepenuh,<br/>kudus, adil, kasih, terang.<br/>',NULL,62899,6);
INSERT INTO stanza VALUES('I531','7','Kristus milik Allah ini,<br/>suplai kita dengan hayat;<br/>Semua tuntutan hukum,<br/>tergenapi atas kita.<br/>',NULL,62900,7);
INSERT INTO stanza VALUES('I531','8','Kristus, saksi hidup Allah,<br/>bawaku berbagian hayat;<br/>Kita mati t''radap hukum,<br/>dikuduskan dalam Roh-Nya.<br/>',NULL,62901,8);
INSERT INTO stanza VALUES('I532','1','Hukum Allah zaman lama,<br/>ialah huruf di loh batu;<br/>Tapi kini hukum hayat,<br/>ditulis Roh di hatiku.<br/>',NULL,62902,1);
INSERT INTO stanza VALUES('I532','2','Hukum huruf tuntut insan,<br/>menyatakan lemah insan,<br/>Hukum hayat suplai insan,<br/>kuasa Allah, insan nikmat.<br/>',NULL,62903,2);
INSERT INTO stanza VALUES('I532','3','Hukum hayat di luarku,<br/>membuatku kenal Allah;<br/>Hukum hayat di dalamku,<br/>beri wahyu tentang Allah.<br/>',NULL,62904,3);
INSERT INTO stanza VALUES('I532','4','Hukum huruf di luarku,<br/>berkuasa oleh hukum maut;<br/>Hukum hayat di dalamku,<br/>''ngontrol lewat pengenalan.<br/>',NULL,62905,4);
INSERT INTO stanza VALUES('I532','5','Hukum hayat ini hidup,<br/>bergerak dalam batinku,<br/>Sesuai perasaan batin,<br/>dari dalam tertibkanku.<br/>',NULL,62906,5);
INSERT INTO stanza VALUES('I532','6','Kendalinya halus, lembut,<br/>di dalam lubuk batinku,<br/>Bawa perasaan hidup,<br/>suplaikan Allah padaku.<br/>',NULL,62907,6);
INSERT INTO stanza VALUES('I532','7','Kar''na hukum hayat ini,<br/>tak perlu ajaran luar,<br/>Pengenalan atas Allah,<br/>ia ajarkan dari dalam.<br/>',NULL,62908,7);
INSERT INTO stanza VALUES('I532','8','Hidup demi hukum hayat,<br/>taati Dia di dalam,<br/>Ada pengenalan hidup,<br/>dan nikmati diri Allah.<br/>',NULL,62909,8);
INSERT INTO stanza VALUES('I533','1','Hayat kekal bawa<br/>pers''kutuan hayat;<br/>Sekutu dalam roh,<br/>Roh pun menggarap.<br/>',NULL,62910,1);
INSERT INTO stanza VALUES('I533','2','Hayat kekal beri<br/>pers''kutuan kudus;<br/>Demikian Roh Tuhan,<br/>baur denganku.<br/>',NULL,62911,2);
INSERT INTO stanza VALUES('I533','3','Hayat di dalam Roh<br/>bawa pers''kutuan;<br/>Sekutu dalam roh,<br/>nikmat kurnia-Nya.<br/>',NULL,62912,3);
INSERT INTO stanza VALUES('I533','4','Demi kuasa hayat,<br/>bers''kutu mesra;<br/>Sekutu dalam roh,<br/>hidup dalam t''rang.<br/>',NULL,62913,4);
INSERT INTO stanza VALUES('I533','5','Darah basuh bersih,<br/>jaga pers''kutuan;<br/>Batin diurapi,<br/>sekutu puas.<br/>',NULL,62914,5);
INSERT INTO stanza VALUES('I533','6','Demi karya salib,<br/>s''kutu kian dalam;<br/>Demi gerakan Roh,<br/>s''kutu kian segar.<br/>',NULL,62915,6);
INSERT INTO stanza VALUES('I533','7','Persekutuan hayat,<br/>lepaslah diri;<br/>Persekutuan hayat,<br/>dapatkan Allah.<br/>',NULL,62916,7);
INSERT INTO stanza VALUES('I534','1','Hayat punya perasaan,<br/>perasaan hayat;<br/>hayat ilahi dalamku,<br/>unggul lagi peka.<br/>',NULL,62917,1);
INSERT INTO stanza VALUES('I534','2','Makin tinggi mutu hayat,<br/>rasa makin peka;<br/>Hayat Allah paling tinggi,<br/>paling peka pasti.<br/>',NULL,62918,2);
INSERT INTO stanza VALUES('I534','3','Perasaan hayat Allah,<br/>perasaan Allah;<br/>Dalam rohku Dia berperan,<br/>lampaui kebaikan.<br/>',NULL,62919,3);
INSERT INTO stanza VALUES('I534','4','Perasaan hayat batin,<br/>p''rasaan terdalam;<br/>Memiliki daya tamyiz,<br/>''nyatakan ''kenan-Nya.<br/>',NULL,62920,4);
INSERT INTO stanza VALUES('I534','5','Oleh rasa hayat ini,<br/>ku mengenal Allah;<br/>Bukan gumul ronta lahir,<br/>wahyulah semata.<br/>',NULL,62921,5);
INSERT INTO stanza VALUES('I534','6','Makin tumbuh dalam hayat,<br/>rasa makin peka;<br/>Makin tindak dalam hayat,<br/>rasa makin ketat.<br/>',NULL,62922,6);
INSERT INTO stanza VALUES('I534','7','Latih perasaan hayat,<br/>roh pun makin kuat;<br/>Oleh perasaan Allah,<br/>sekutu meningkat.<br/>',NULL,62923,7);
INSERT INTO stanza VALUES('I535','1','Di dalam roh kaum terlahir ulang,<br/>pengenalannya riil pun limpah;<br/>Tidak perlu ajaran di luar,<br/>perlu pemahaman batiniah.<br/>',NULL,62924,1);
INSERT INTO stanza VALUES('I535','2','Hayat kekal terbaik, terunggul,<br/>miliki banyak fungsi ilahi;<br/>Melalui hayat mengenal Allah,<br/>jauh lampaui pengetahuan.<br/>',NULL,62925,2);
INSERT INTO stanza VALUES('I535','3','Hukum hayat ditaruh dalamku,<br/>ditulis Roh Kudus dalam hati;<br/>Gerak di dalam, ku kenal Allah,<br/>jauh lampaui ajaran luar.<br/>',NULL,62926,3);
INSERT INTO stanza VALUES('I535','4','Urapan minyak tinggal dalam roh,<br/>''nyatakan hal-hal Allah padaku;<br/>Lewat urapan ku kenal Allah,<br/>melebihi ajaran di luar.<br/>',NULL,62927,4);
INSERT INTO stanza VALUES('I535','5','Allah Tritunggal tinggal dalamku,<br/>''tiasa bergerak, kerja, dan hidup;<br/>Lewat p''rasaan gerakan batin,<br/>kenal Allah lebih dalam, tinggi.<br/>',NULL,62928,5);
INSERT INTO stanza VALUES('I535','6','Kini ada pengenalan batin,<br/>tak perlu pengetahuan lahir;<br/>hanya perlu t''rus hidup dalam roh,<br/>bertindak sesuai petunjuk roh.<br/>',NULL,62929,6);
INSERT INTO stanza VALUES('I535','7','Semakin hidup di dalam Kristus,<br/>gerak berdasar p''rasaan batin;<br/>Makin punya pengenalan batin,<br/>mengukir Kristus di dalam hati.<br/>',NULL,62930,7);
INSERT INTO stanza VALUES('I535','8','Lewat pengenalan hayat batin,<br/>kita bersekutu dengan Allah;<br/>Lewat pengenalan tersembunyi,<br/>kepenuhan Allah tersuplaikan.<br/>',NULL,62931,8);
INSERT INTO stanza VALUES('I536','1','Prinsip Allah berinkarnasi,<br/>saling baur Allah - insan;<br/>Jadi satu insan misteri,<br/>menurut rencana Allah.<br/>',NULL,62932,1);
INSERT INTO stanza VALUES('I536','2','Insan mengekspresikan Allah,<br/>Allah ialah hayat insan;<br/>Allah mutlak miliki insan,<br/>Allah dinyatakan insan.<br/>',NULL,62933,2);
INSERT INTO stanza VALUES('I536','3','Tebusan genap pada insan,<br/>menyatakan hikmat Allah;<br/>Insan b''ritakan kes''lamatan,<br/>agar semua makhluk paham.<br/>',NULL,62934,3);
INSERT INTO stanza VALUES('I536','4','Kini pekerjaan rohani,<br/>kerja sama Allah - insan;<br/>Allah - insan erat bersatu,<br/>saling sandar, saling baur.<br/>',NULL,62935,4);
INSERT INTO stanza VALUES('I536','5','Bukan Allah kerja sendiri,<br/>dan insan kerja sendiri;<br/>Tapi Allah, insan,<br/>bersama rampungkan rencana Allah.<br/>',NULL,62936,5);
INSERT INTO stanza VALUES('I536','6','Inilah prinsip inkarnasi,<br/>untuk semua pelayanan;<br/>Pun untuk karunia dan fungsi,<br/>demi layani bersama.<br/>',NULL,62937,6);
INSERT INTO stanza VALUES('I537','1','Tiga bagian atas insan,<br/>yakni tubuh, jiwa dan roh;<br/>''Tuk genapkan rencana-Nya,<br/>juga nikmati suplai-Nya.<br/>',NULL,62938,1);
INSERT INTO stanza VALUES('I537','2','Tubuh bagian di lahir,<br/>dapat merasakan benda;<br/>Punya bentuknya yang konkret,<br/>menjamah alam material.<br/>',NULL,62939,2);
INSERT INTO stanza VALUES('I537','3','Jiwa bagian di dalam,<br/>pusat ego, rasa diri;<br/>Ruang lingkup kejiwaan,<br/>menjamah alam jiwani.<br/>',NULL,62940,3);
INSERT INTO stanza VALUES('I537','4','Roh bagian lubuk batin,<br/>b''ri perasaan ilahi;<br/>Sarana men''rima Allah,<br/>menjamah alam rohani.<br/>',NULL,62941,4);
INSERT INTO stanza VALUES('I537','5','Tiga bagian di jiwa:<br/>pikiran, emosi, tekad;<br/>Pangkal daya-guna insan,<br/>melaksanakan niatnya.<br/>',NULL,62942,5);
INSERT INTO stanza VALUES('I537','6','Tiga bagian dalam roh:<br/>s''kutu, intuisi, nurani;<br/>Untuk sekutu d''ngan Allah,<br/>sembah dan men''rima Allah.<br/>',NULL,62943,6);
INSERT INTO stanza VALUES('I537','7','Gunakan antero jiwa,<br/>pilih s''mua adanya Allah;<br/>Menerima Dia dengan roh,<br/>lewat tubuh, Allah nyata.<br/>',NULL,62944,7);
INSERT INTO stanza VALUES('I537','8','Perlu roh terlahir ulang,<br/>dapat hayat non tercipta;<br/>Jiwa pun perlu diubah,<br/>tubuh tergarap mulia.<br/>',NULL,62945,8);
INSERT INTO stanza VALUES('I537','9','Oleh penggarapan Allah,<br/>di atas tiap bagian;<br/>Mutlak baur dengan Tuhan,<br/>Allah tertampil sempurna.<br/>',NULL,62946,9);
INSERT INTO stanza VALUES('I538','1','Seb''lum dunia dijadikan,<br/>Allah telah tetapkan;<br/>Kita dapat keputraan,<br/>jadi gambar Putra-Nya;<br/>Supaya Putra tunggal-Nya,<br/>menjadi Putra sulung,<br/>Putra-Nya dan saudara-Nya,<br/>ekspresikan mulia-Nya.<br/>',NULL,62947,1);
INSERT INTO stanza VALUES('I538','2','Dengan kelahiran ulang,<br/>jadi anak-anak-Nya;<br/>Tapi kita harus matang,<br/>jadi ahli waris-Nya.<br/>Tumbuh dewasa sepenuh,<br/>kecap hak keputraan;<br/>Mencapai perawakan-Nya,<br/>kecap berkat warisan.<br/>',NULL,62948,2);
INSERT INTO stanza VALUES('I538','3','Roh, jiwa, dan tubuh kita,<br/>diubah s''rupa Tuhan;<br/>Tergenap dengan sempurna,<br/>saat masuk mulia-Nya.<br/>Lewat penebusan tubuh,<br/>keputraan terampung;<br/>Lewat perubahan akhir,<br/>Allah pun puas hati.<br/>',NULL,62949,3);
INSERT INTO stanza VALUES('I538','4','Lewat perubahan akhir,<br/>kita mutlak kuduslah;<br/>Kita masuk dalam mulia,<br/>mirip dengan Putra-Nya.<br/>Semua makhluk menunggu,<br/>para putra-Nya nyata;<br/>M''reka masuk bebas "mulia",<br/>terlepas kebobrokan.<br/>',NULL,62950,4);
INSERT INTO stanza VALUES('I539','1','Kita jadi wadah Allah,<br/>ekspresikan kaya-Nya;<br/>Cipta hati mencintai-Nya,<br/>cipta roh men''rima-Nya.<br/>',NULL,62951,1);
INSERT INTO stanza VALUES('I539','2','Dengan hati cinta Dia,<br/>dengan roh t''rima Dia;<br/>T''rima Allah jadi hayat,<br/>ini pintu masuknya.<br/>',NULL,62952,2);
INSERT INTO stanza VALUES('I539','3','Iblis merusak hatiku,<br/>juga matikan rohku;<br/>Ku tak dapat kontak Allah,<br/>bila sandar hayatku.<br/>',NULL,62953,3);
INSERT INTO stanza VALUES('I539','4','Dalam kes''lamatan Tuhan,<br/>barui roh, hatiku;<br/>Pulihkan rasa kasihku,<br/>daya t''rima hatiku.<br/>',NULL,62954,4);
INSERT INTO stanza VALUES('I539','5','Dengan hati yang dibarui,<br/>kasih dan damba Allah;<br/>Dengan roh yang dibarui,<br/>sembah dan t''rima Allah.<br/>',NULL,62955,5);
INSERT INTO stanza VALUES('I539','6','T''radap Allah hati harus bersih,<br/>murni, dan tulus;<br/>Hingga rohku lincah dan kuat,<br/>kontak Allah selalu.<br/>',NULL,62956,6);
INSERT INTO stanza VALUES('I539','7','Juga hatiku cinta-Mu,<br/>sering segar tak layu;<br/>Hingga rohku lincah dan kuat,<br/>kontak Allah selalu.<br/>',NULL,62957,7);
INSERT INTO stanza VALUES('I540','1','Gaul d''ngan Tuhan, nikmat hayat,<br/>perlu hati tepat,<br/>Demi kurnia, segala-Nya,<br/>kami berbagian.<br/>',NULL,62958,1);
INSERT INTO stanza VALUES('I540','2','Perlu hati polos, murni,<br/>angan tulus, bening,<br/>Agar paham murad suci,<br/>takwa pun layani.<br/>',NULL,62959,2);
INSERT INTO stanza VALUES('I540','3','Perlu hati mengasihi,<br/>emosi p''nuh kasih,<br/>Cari Tuhan seg''nap hati,<br/>tak terebut yang lain.<br/>',NULL,62960,3);
INSERT INTO stanza VALUES('I540','4','Perlu hati tulus, taat,<br/>tekad patuh s''laras,<br/>Tegap, lembut, dengan tepat,<br/>setala murad-Nya.<br/>',NULL,62961,4);
INSERT INTO stanza VALUES('I540','5','Perlu hati bebas cela,<br/>nurani nan lapang,<br/>Berserasi dengan Allah,<br/>darah hapus dosa.<br/>',NULL,62962,5);
INSERT INTO stanza VALUES('I540','6','Tuhan, beri hati ini,<br/>damba Kau tiap detik,<br/>Limpah ruah-Mu ku nikmati,<br/>kaya-Mu ku jadi.<br/>',NULL,62963,6);
INSERT INTO stanza VALUES('I541','1','Tuhan, Kau kini Roh itu,<br/>tinggal di roh kami;<br/>Dua roh jadi satu roh,<br/>satu Kau dan kami.<br/>',NULL,62964,1);
INSERT INTO stanza VALUES('I541','2','Tuhan, Roh-Mu d''ngan roh kami,<br/>bersama bersaksi;<br/>Kami anak-anak Allah,<br/>waris mulia Allah.<br/>',NULL,62965,2);
INSERT INTO stanza VALUES('I541','3','Kau telah jadi Roh hayat,<br/>agar Kau didapat;<br/>Kini kami di dalam roh,<br/>nikmati limpah-Mu.<br/>',NULL,62966,3);
INSERT INTO stanza VALUES('I541','4','Kau kini Roh hayat itu,<br/>pimpin, sorot, s''kutu;<br/>Di dalam roh kami hidup,<br/>ikuti gerak-Mu.<br/>',NULL,62967,4);
INSERT INTO stanza VALUES('I541','5','Kau Roh itu di roh kami,<br/>menguatkan kami;<br/>Kami di roh, oleh Roh-Mu,<br/>sembah dan layani.<br/>',NULL,62968,5);
INSERT INTO stanza VALUES('I541','6','Kau Roh itu di roh kami,<br/>berdoa pada-Mu;<br/>Di dalam roh dan dengan Roh,<br/>syafaat tak putus.<br/>',NULL,62969,6);
INSERT INTO stanza VALUES('I541','7','Kami mau balik dalam roh,<br/>berkontak d''ngan Roh-Mu;<br/>Di dalam roh menikmati,<br/>suplai ilahi-Mu.<br/>',NULL,62970,7);
INSERT INTO stanza VALUES('I541','8','Betapa esanya ini,<br/>dua roh jadi satu!<br/>Roh-Mu hidup di roh kami,<br/>roh kami dalam-Mu!<br/>',NULL,62971,8);
INSERT INTO stanza VALUES('I542','1','Dengan salib bedakan roh,<br/>letakkan jiwa ke maut;<br/>Pikul salib, tolak ego,<br/>terus hidup dalam roh.<br/>',NULL,62972,1);
INSERT INTO stanza VALUES('I542','2','Dengan salib bedakan roh,<br/>sandar firman hayat-Nya;<br/>Pisahkan jiwa dari roh,<br/>hidup dalam roh saja.<br/>',NULL,62973,2);
INSERT INTO stanza VALUES('I542','3','Dengan salib bedakan roh,<br/>perbarui pikiran;<br/>Emosi mutlak tersembah,<br/>tekad pun s''lalu taat.<br/>',NULL,62974,3);
INSERT INTO stanza VALUES('I542','4','Dengan salib bedakan roh,<br/>lewat tirai terbelah;<br/>Daging, jiwa, dihancurkan,<br/>roh jadi terutama.<br/>',NULL,62975,4);
INSERT INTO stanza VALUES('I542','5','Dengan salib bedakan roh,<br/>roh ruang mahakudus-Nya;<br/>Di roh s''kutu dengan Allah,<br/>dapat penyertaan-Nya.<br/>',NULL,62976,5);
INSERT INTO stanza VALUES('I542','6','Dengan salib bedakan roh,<br/>p''ri ''nyeb''rang Sungai Yordan;<br/>Hingga masuk tanah Kanaan,<br/>hidup nikmati Kristus.<br/>',NULL,62977,6);
INSERT INTO stanza VALUES('I542','7','Dengan salib bedakan roh,<br/>gerak harus dalam roh;<br/>Garap Kristus tanah permai,<br/>pasti tuai limpah-Nya.<br/>',NULL,62978,7);
INSERT INTO stanza VALUES('I543','1','Tempat maha kudus Bait,<br/>ada tabut, takhta kurnia;<br/>Atasnya pancar mulia-Nya,<br/>tempat imam jumpa Allah.<br/>',NULL,62979,1);
INSERT INTO stanza VALUES('I543','2','Kini ku jadi Bait Allah,<br/>rohlah tempat mahakudus;<br/>Allah dan Kristus di sini,<br/>oleh Roh hidup denganku.<br/>',NULL,62980,2);
INSERT INTO stanza VALUES('I543','3','Di lubuk batin terdalam,<br/>Kristus Allah segalaku;<br/>Di sini Roh Kudus garap,<br/>Kristus jadi realitasku.<br/>',NULL,62981,3);
INSERT INTO stanza VALUES('I543','4','Di sini aku dalam roh,<br/>kontak Tuhan tinggal d''ngan-Nya;<br/>Di sini ku dengan rohku,<br/>bers''kutu, menjamah Allah.<br/>',NULL,62982,4);
INSERT INTO stanza VALUES('I543','5','Di sini Kristus p''ri tanah,<br/>ku tinggali dan nikmati;<br/>Di sini ku serang musuh,<br/>dengan kuasa bereskannya.<br/>',NULL,62983,5);
INSERT INTO stanza VALUES('I543','6','Ku menuntut mengenal roh,<br/>pisahkan roh dari jiwa;<br/>Hidup dalam tempat kudus,<br/>menikmati hadir Tuhan.<br/>',NULL,62984,6);
INSERT INTO stanza VALUES('I543','7','Ku harus tolak jiwaku,<br/>giat masuk perhentian-Nya;<br/>Dengan limpah dapat Kristus,<br/>rampung murad kekal Allah.<br/>',NULL,62985,7);
INSERT INTO stanza VALUES('I544','1','Ajarku pisahkan roh - jiwa,<br/>hingga sungguh mengenal-Mu;<br/>Kau-lah Roh, tinggal dalam rohku,<br/>dua roh baur jadi satu.<br/>',NULL,62986,1);
INSERT INTO stanza VALUES('I544','2','Ajarku pisahkan roh - jiwa,<br/>s''lalu tolak hayat jiwa;<br/>Dalam roh selalu ikut-Mu,<br/>menerapkan-Mu, Roh hayat.<br/>',NULL,62987,2);
INSERT INTO stanza VALUES('I544','3','Ajarku pisahkan roh - jiwa,<br/>pikiran tidak di daging;<br/>Tapi selalu di atas roh,<br/>lepas dari dosa, diri.<br/>',NULL,62988,3);
INSERT INTO stanza VALUES('I544','4','Ajarku pisahkan roh - jiwa,<br/>tidak jiwani selalu;<br/>Tapi mutlak rohani s''jati,<br/>dalam roh tindak dan hidup.<br/>',NULL,62989,4);
INSERT INTO stanza VALUES('I544','5','Ajarku pisahkan roh - jiwa,<br/>ego yang licik diekspos;<br/>Selalu terapkan salib-Mu,<br/>bukan aku, tapi Kristus.<br/>',NULL,62990,5);
INSERT INTO stanza VALUES('I544','6','Ajarku pisahkan roh - jiwa,<br/>hingga jiwaku terubah,<br/>Ku diserupakan gambar-Mu,<br/>jadi matang, capai tujuan.<br/>',NULL,62991,6);
INSERT INTO stanza VALUES('I544','7','Ajarku pisahkan roh - jiwa,<br/>beriku firman hidup-Mu,<br/>Pisahkan rohku dari jiwa,<br/>dalam roh tinggal serta-Mu.<br/>',NULL,62992,7);
INSERT INTO stanza VALUES('I545','1','Roh mulia Allah Tritunggal,<br/>kini tinggal dalam rohku,<br/>''Tiasa ingin ''ngalir ke luar,<br/>Allah ternyata lewatku.<br/>',NULL,62993,1);
INSERT INTO stanza VALUES('I545','2','Insan alami lahirku,<br/>sering halangi Roh Kudus;<br/>Tidak membuat Dia bebas,<br/>malah jadi penjara-Nya.<br/>',NULL,62994,2);
INSERT INTO stanza VALUES('I545','3','Roh sepertilah mustika,<br/>tak terlihat dalam wadah;<br/>Wadah harus diremukkan,<br/>mustika baru ternyata.<br/>',NULL,62995,3);
INSERT INTO stanza VALUES('I545','4','Egoku harus dibongkar,<br/>hayat jiwani mengganggu,<br/>Insan alami diremuk,<br/>Roh Kudus baru terbebas.<br/>',NULL,62996,4);
INSERT INTO stanza VALUES('I545','5','Inilah sebabnya Tuhan<br/>izinkan ku menderita,<br/>Lewat berbagai tekanan,<br/>remukkan insan lahiriah.<br/>',NULL,62997,5);
INSERT INTO stanza VALUES('I545','6','Insan lahir - jiwa lama -<br/>harus hancur, harus luka,<br/>Insan batin - roh yang baru -<br/>dibebaskan bersama Roh.<br/>',NULL,62998,6);
INSERT INTO stanza VALUES('I545','7','Beri aku peremukan,<br/>jangan lindungi egoku,<br/>Ku terima semua luka,<br/>dengan penuh kerelaan.<br/>',NULL,62999,7);
INSERT INTO stanza VALUES('I545','8','Ku hargai p''remukan-Mu,<br/>s''lamanya tak menggerutu;<br/>Ku indahkan kerugian,<br/>melebihi manfaatku.<br/>',NULL,63000,8);
INSERT INTO stanza VALUES('I546','1','Allah menghendaki kita<br/>agar s''rupa Putra-Nya;<br/>Karenanya Roh tiasa<br/>atasku ''ngubah, garap.<br/>',NULL,63001,1);
INSERT INTO stanza VALUES('I546','chorus','Mohonlah tiap p''losok jiwa,<br/>dengan Kau berserupa;<br/>Demilah Roh ku teresap,<br/>hingga mirip tak beda.<br/>',NULL,63002,2);
INSERT INTO stanza VALUES('I546','2','Oleh hayat kudus Allah,<br/>dalam roh lahir ulang,<br/>Perlu pula pada jiwa,<br/>mengubah dan menggarap.<br/>',NULL,63003,3);
INSERT INTO stanza VALUES('I546','3','Dari dalam rohku meluas,<br/>jiwa ubah semua;<br/>Perbarui tiap bagian,<br/>taatlah seluruhnya.<br/>',NULL,63004,4);
INSERT INTO stanza VALUES('I546','4','Demi kuasa Roh hayat-Nya,<br/>ubah sesuai gambar-Nya;<br/>''Dikit, ''dikit kian mulia,<br/>p''ri Dia baru pun segar.<br/>',NULL,63005,5);
INSERT INTO stanza VALUES('I546','5','Ubah kudus sampai rata,<br/>dewasa serupa Dia;<br/>Ubah meny''luruh di jiwa,<br/>tertebus tubuh fana.<br/>',NULL,63006,6);
INSERT INTO stanza VALUES('I547','1','Bukanlah meronta, tapi berserah;<br/>Yang beri perhentian, pula tenaga.<br/>Bukanlah bertekad, tapi ikut roh;<br/>Biar ku lepas dosa, hingga ku menang.<br/>',NULL,63007,1);
INSERT INTO stanza VALUES('I547','2','Bukan sandar huruf, tapi sandar Roh,<br/>Agar ku dikenan, berbagian hayat.<br/>Bukanlah ajaran, tapi urapan,<br/>Yang berikan terang dan persekutuan.<br/>',NULL,63008,2);
INSERT INTO stanza VALUES('I547','3','Bukan aku mampu, tapi rahmat-Nya,<br/>Ku dapatkan Allah serta berkat-Nya.<br/>Bukan pandai otak, tapi kurnia,<br/>Atasi sengsara, lampaui d''rita.<br/>',NULL,63009,3);
INSERT INTO stanza VALUES('I547','4','Bukan kata indah, tapi kuasa-Nya,<br/>Bimbing yang tersesat kepada hayat.<br/>Bukan hikmat, bakat, tetapi Roh-Nya,<br/>Genapkan amanat dan maksud Allah.<br/>',NULL,63010,4);
INSERT INTO stanza VALUES('I548','1','Injil Allah, sungguh bah''gia!<br/>Selamatkan manusia;<br/>Yesus genapkan tebusan,<br/>bilur-Nya yang sembuhkan.<br/>',NULL,63011,1);
INSERT INTO stanza VALUES('I548','chorus','Puji tebusan sempurna,<br/>selamatkan manusia;<br/>Puji Tuhan, Dia tabibku,<br/>Dia terluka, ku sembuh.<br/>',NULL,63012,2);
INSERT INTO stanza VALUES('I548','2','Siapa minta, Dia ''kan tolong,<br/>tak ada yang ditolak;<br/>Bawa sakitmu pada-Nya,<br/>bilur-Nya yang sembuhkan.<br/>',NULL,63013,3);
INSERT INTO stanza VALUES('I548','3','Puji urapan ilahi,<br/>Roh Kudus beri kurnia;<br/>Mohon Kau tumpangkan tangan,<br/>bilur-Mu yang sembuhkan.<br/>',NULL,63014,4);
INSERT INTO stanza VALUES('I548','4','Saat panah Iblis ''nyerang,<br/>Kau jadi perisaiku;<br/>Hingga akhir kita aman,<br/>bilur-Mu yang sembuhkan.<br/>',NULL,63015,5);
INSERT INTO stanza VALUES('I548','5','Tuhan ku serahkan diri,<br/>memuliakan Kau ''tiasa;<br/>Jangan sampai aku lupa,<br/>bilur-Mu yang sembuhkan.<br/>',NULL,63016,6);
INSERT INTO stanza VALUES('I549','1','Aku sembuh, puji Tuhan!<br/>Ku masyhurkan tebusan-Nya;<br/>Dia hilangkan penyakitku,<br/>Tuhan kuasa, tabib agung.<br/>',NULL,63017,1);
INSERT INTO stanza VALUES('I549','chorus','Aku sembuh, aku sembuh,<br/>Dia berkuasa sembuhkanku,<br/>Banyak orang Dia hidupkan,<br/>ku percaya aku sembuh.<br/>',NULL,63018,2);
INSERT INTO stanza VALUES('I549','2','Aku sembuh demi iman,<br/>ku percaya firman Tuhan;<br/>Penuh harap, penuh tent''ram,<br/>percaya Dia yang sembuhkan.<br/>',NULL,63019,3);
INSERT INTO stanza VALUES('I549','3','Aku sembuh, aku yakin,<br/>datang jamah jumbai Tuhan,<br/>Kuasa-Nya mencapaiku,<br/>s''mua sakitku seg''ra sembuh.<br/>',NULL,63020,4);
INSERT INTO stanza VALUES('I549','4','Aku sembuh, sep''ri dulu,<br/>Dia pikul sakit, dosa;<br/>Kuasa-Nya tak berubah,<br/>Peny''lamatku hidup s''lama.<br/>',NULL,63021,5);
INSERT INTO stanza VALUES('I549','5','Aku sembuh, ku t''lah mohon,<br/>b''rapa kali belum dapat;<br/>Kini yakin sepenuhnya,<br/>iman buatku hidup pula.<br/>',NULL,63022,6);
INSERT INTO stanza VALUES('I550','1','Ketika Tuhan melintas,<br/>orang banyak mendesak-Nya,<br/>Dia jamah jubah Tuhan,<br/>segera disembuhkan.<br/>',NULL,63023,1);
INSERT INTO stanza VALUES('I550','chorus','Asal jamah, disembuhkan,<br/>Tuhan di sini selalu;<br/>Jamahlah Dia, jangan meragu,<br/>asal jamah, ''kan sembuh.<br/>',NULL,63024,2);
INSERT INTO stanza VALUES('I550','2','Asal jamah disembuhkan,<br/>Dia tenteramkan hatiku,<br/>Di depan-Nya beban lepas,<br/>kini ku telah sembuh.<br/>',NULL,63025,3);
INSERT INTO stanza VALUES('I550','3','Asal jamah, semua beres,<br/>lepas dari penyakitku,<br/>Sampai kekal ku memuji,<br/>kar''na ku sudah sembuh.<br/>',NULL,63026,4);
INSERT INTO stanza VALUES('I550','4','Asal jamah, Dia berpaling,<br/>o, pandang-Nya penuh kasih;<br/>Hibur hati, ku bersyukur,<br/>kini ku sudah sembuh.<br/>',NULL,63027,5);
INSERT INTO stanza VALUES('I550','5','Asal jamah, pasti sembuh,<br/>sekarang Dia sembuhkan;<br/>Asal jamah, pasti sembuh,<br/>meski keras sakitnya.<br/>',NULL,63028,6);
INSERT INTO stanza VALUES('I551','1','Tuhan Alfa dari doa,<br/>Roh-Nya ajar rohku;<br/>Ku tak tahu panjat doa,<br/>''cuali Dia menuntun.<br/>',NULL,63029,1);
INSERT INTO stanza VALUES('I551','2','Tuhan pun Omega doa,<br/>"Amin" agung Allah,<br/>Saat ku berhenti doa,<br/>dengar suara desah.<br/>',NULL,63030,2);
INSERT INTO stanza VALUES('I551','3','Namun dalam sela ini,<br/>Dia baurkan kami,<br/>Dengan suara yang tersendat,<br/>jelaskan pikir-Nya.<br/>',NULL,63031,3);
INSERT INTO stanza VALUES('I551','4','O, Sang Awal pun Sang Akhir,<br/>dengarlah doaku,<br/>Padukan d''ngan kehendak-Mu,<br/>hingga genap s''luruh.<br/>',NULL,63032,4);
INSERT INTO stanza VALUES('I551','5','Yang tak mampu ku doakan,<br/>Kau-lah yang awali,<br/>Dalam setiap doaku,<br/>Kau jadi Sang Akhir!<br/>',NULL,63033,5);
INSERT INTO stanza VALUES('I552','1','Doa - ukupan hati yang kudus,<br/>sembah ke Allah lewat yang remuk,<br/>Dibakar oleh api Roh Kudus,<br/>bawa depan-Nya oleh imanku.<br/>',NULL,63034,1);
INSERT INTO stanza VALUES('I552','2','Doa - bau harum kaih kurnia,<br/>bunga baur iman, kasih, d''rita,<br/>Tersimpan dalam kata nan harum,<br/>dihirup Allah aroma sedap.<br/>',NULL,63035,2);
INSERT INTO stanza VALUES('I552','3','Doa - uap yang beri suplaian, hujan berkat,<br/>dan aliran hayat, Basahi bumi yang kering, gersang,<br/>hingga padang gurun tumbuh bunga.<br/>',NULL,63036,3);
INSERT INTO stanza VALUES('I552','4','Doa - pipa emas yang penuh Roh,<br/>isikan minyak pelita Allah,<br/>Saat sehati doa berjaga,<br/>Roh penuhi, pelita menyala.<br/>',NULL,63037,4);
INSERT INTO stanza VALUES('I552','5','Doa - kuasa terunggul di jagat,<br/>doa pun kuat kuasa Allah,<br/>Gerakkan tangan penggerak s''gala,<br/>roda hidup yang lintasi buana.<br/>',NULL,63038,5);
INSERT INTO stanza VALUES('I552','6','Ajarku doa, gerak di rohku,<br/>hingga diri-Mu kuasai diriku,<br/>Doa dalamku hingga ternyata,<br/>Kristus berdoa kepada Kristus.<br/>',NULL,63039,6);
INSERT INTO stanza VALUES('I553','1','Tuhan, dalam hadir-Mu ku tenang,<br/>tarik anteroku ke batinku,<br/>Tidak lagi berdoa di luar,<br/>doa seturut gerakan Roh-Mu.<br/>',NULL,63040,1);
INSERT INTO stanza VALUES('I553','2','Seolah Kau di surga dengarku,<br/>tapi dalam rohku Kau semayam,<br/>Seolah ku berdoa pada-Mu,<br/>tapi Kau yang berdoa dalamku.<br/>',NULL,63041,2);
INSERT INTO stanza VALUES('I553','3','Kadang ku tiada perkataan,<br/>tapi oleh Roh-Mu ku berkesah,<br/>Bukan di luaran ku berdoa,<br/>tapi di dalam Kau yang berdoa.<br/>',NULL,63042,3);
INSERT INTO stanza VALUES('I553','4','Tuhan, ku damba hirup diri-Mu,<br/>makan, minum, nikmati suplai-Mu,<br/>Agar ku dapat s''kutu dengan-Mu,<br/>hingga Kau terekspresi olehku.<br/>',NULL,63043,4);
INSERT INTO stanza VALUES('I553','5','Dalam sekutu terang-Mu pancar,<br/>darah-Mu basuh bersih diriku,<br/>Ku mendapatkan sorotan terang,<br/>diri-Mu jelas terekspresikan.<br/>',NULL,63044,5);
INSERT INTO stanza VALUES('I553','6','Minyak-Mu urapi tiap aspek,<br/>urapkan diri-Mu makin banyak,<br/>Kadar-Mu bertambah, ku berkurang,<br/>lewatku Kau makin ternyatakan.<br/>',NULL,63045,6);
INSERT INTO stanza VALUES('I553','7','Terbuka t''radap-Mu, biar Kau masuk,<br/>t''radap manusia, biar Kau ''ngalir,<br/>Dalam arus hayat-Mu berbaur,<br/>biar diri-Mu mutlak terekspresi.<br/>',NULL,63046,7);
INSERT INTO stanza VALUES('I554','1','Tuhan, ajar ku berdoa!<br/>Agar musuh kalah,<br/>Lepas s''mua tawanan dosa,<br/>tumpas kuasa jahat.<br/>',NULL,63047,1);
INSERT INTO stanza VALUES('I554','2','Tuhan, ajar ku berdoa!<br/>Teguh di medan p''rang,<br/>Dobrak kubu-kubu musuh,<br/>biar m''reka s''mua takluk.<br/>',NULL,63048,2);
INSERT INTO stanza VALUES('I554','3','Tuhan, ajar ku berdoa!<br/>Ta''u kehendak Allah;<br/>D''ngan doa guncangkan dunia,<br/>b''roleh kuasa darah.<br/>',NULL,63049,3);
INSERT INTO stanza VALUES('I554','4','B''lajar berjerih serta-Nya,<br/>demi iman dan doa;<br/>Paham kuasa kemenangan,<br/>milikku s''lamanya.<br/>',NULL,63050,4);
INSERT INTO stanza VALUES('I555','1','Tuhan kami berhimpun,<br/>sehati doa pada-Mu,<br/>Kamilah imam kudus,<br/>berdiri di depan-Mu.<br/>',NULL,63051,1);
INSERT INTO stanza VALUES('I555','chorus','Di sini kami doa,<br/>menjamah yang terbaik,<br/>Sampai berbaur dalam roh,<br/>gereja-Mu terbangun.<br/>',NULL,63052,2);
INSERT INTO stanza VALUES('I555','2','Ingin menjadi imam,<br/>bertugas di depan-Mu,<br/>D''ngan roh jamah murad-Mu,<br/>Dikau kerja pun rampung.<br/>',NULL,63053,3);
INSERT INTO stanza VALUES('I555','3','Ke tempat mahakudus,<br/>jamah takhta anug''rah,<br/>Doa d''ngan inspirasi,<br/>lewat rohku Kau ''ngalir.<br/>',NULL,63054,4);
INSERT INTO stanza VALUES('I555','4','Dari takhta anug''rah,<br/>''ngalir sungai kurnia,<br/>Masuk mendiris rohku,<br/>bantuku tiap saat.<br/>',NULL,63055,5);
INSERT INTO stanza VALUES('I555','5','Semoga doa kami,<br/>pengutaraan Roh-Mu;<br/>Tak minta semauku,<br/>hanya turut mau-Mu.<br/>',NULL,63056,6);
INSERT INTO stanza VALUES('I555','6','Meski banyak urusan,<br/>perlu beri tahu-Mu;<br/>Moga Kau dapat jalan,<br/>lebih dari berkatku.<br/>',NULL,63057,7);
INSERT INTO stanza VALUES('I555','7','Kami pandang rahmat-Mu,<br/>banyak beri air hayat,<br/>Kami nikmat kurnia-Mu,<br/>hingga Kau kerja garap.<br/>',NULL,63058,8);
INSERT INTO stanza VALUES('I556','1','Masuk ruang mahakudus,<br/>hidup di balik tirai,<br/>Jamah takhta anug''rah,<br/>hingga air hayat ''ngalir.<br/>',NULL,63059,1);
INSERT INTO stanza VALUES('I556','2','Rohku, ruang mahakudus,<br/>Tuhan tinggal dalamnya,<br/>Asal balik dalam roh,<br/>aku berjumpa Tuhan.<br/>',NULL,63060,2);
INSERT INTO stanza VALUES('I556','3','Aroma Kristus bangkit,<br/>dalam rohku semerbak,<br/>Aku doa dalam roh,<br/>diri Tuhan ternyata.<br/>',NULL,63061,3);
INSERT INTO stanza VALUES('I556','4','Jamah Kristus dalam roh,<br/>pasti kenyang limpah-Nya,<br/>Terang dan pangan hayat,<br/>tambah wangi bangkit-Nya.<br/>',NULL,63062,4);
INSERT INTO stanza VALUES('I556','5','Kian dalam kian limpah,<br/>jamah Kristus di batin,<br/>Menjamah hukum hayat,<br/>jamah manna sembunyi.<br/>',NULL,63063,5);
INSERT INTO stanza VALUES('I556','6','Jamah bangkit, dikenan,<br/>bagai tongkat bertunas,<br/>Ada takhta anug''rah,<br/>p''ri sungai alir kurnia.<br/>',NULL,63064,6);
INSERT INTO stanza VALUES('I556','7','Kita himpun berdoa,<br/>roh luasa pun baur,<br/>Masuk ruang mahakudus,<br/>jamah Tuhan di situ.<br/>',NULL,63065,7);
INSERT INTO stanza VALUES('I556','8','Dalam ruang mahakudus,<br/>menempuh hidup imam,<br/>Jamah takhta anug''rah,<br/>sampai ''ngalir air hayat.<br/>',NULL,63066,8);
INSERT INTO stanza VALUES('I557','1','Masuk ke dalam ruang mahakudus,<br/>rahmat kurnia p''ri bengawan;<br/>Masuk ke dalam ruang mahakudus,<br/>rahmat kurnia p''ri bengawan.<br/>',NULL,63067,1);
INSERT INTO stanza VALUES('I557','chorus','Haleluya! Haleluya!<br/>Rahmat kurnia p''ri bengawan,<br/>Haleluya! Haleluya!<br/>Rahmat kurnia p''ri bengawan.<br/>',NULL,63068,2);
INSERT INTO stanza VALUES('I557','2','Menempuh hidup di balik tirai,<br/>sinar mulia menembusku;<br/>Menempuh hidup di balik tirai,<br/>sinar mulia menembusku.<br/>',NULL,63069,3);
INSERT INTO stanza VALUES('I557','chorus','Haleluya! Haleluya!<br/>Sinar mulia menembusku,<br/>Haleluya! Haleluya!<br/>Sinar mulia menembusku.<br/>',NULL,63070,4);
INSERT INTO stanza VALUES('I557','3','Kembali ke roh, doa depan-Nya,<br/>jamah mata air hayat;<br/>kembali ke roh, doa depan-Nya,<br/>jamah mata air hayat.<br/>',NULL,63071,5);
INSERT INTO stanza VALUES('I557','chorus','Haleluya! Haleluya!<br/>Jamah mata air hayat,<br/>Haleluya! Haleluya!<br/>Jamah mata air hayat.<br/>',NULL,63072,6);
INSERT INTO stanza VALUES('I558','1','Tirai terb''lah,<br/>buka jalan baru pula hidup;<br/>Demi darah b''rani datang,<br/>depan-Mu berdoa.<br/>',NULL,63073,1);
INSERT INTO stanza VALUES('I558','2','Sandar darah-Mu,<br/>ku masuk ke ruang mahakudus;<br/>Ikuti urapan Roh-Mu,<br/>jamah takhta kurnia.<br/>',NULL,63074,2);
INSERT INTO stanza VALUES('I558','3','Taati roh, tolak diri,<br/>berdoa pada-Mu;<br/>Agar Kristus dari rohku,<br/>nyata p''ri ukupan.<br/>',NULL,63075,3);
INSERT INTO stanza VALUES('I558','4','Kasih kurnia serta rahmat,<br/>''ngalir dari takhta;<br/>Suplai limpah, segar, manis,<br/>mengalir tak henti.<br/>',NULL,63076,4);
INSERT INTO stanza VALUES('I558','5','Untuk semua perkara,<br/>berdoa dalam roh;<br/>Dia tahu keperluanku,<br/>Dia merawatku.<br/>',NULL,63077,5);
INSERT INTO stanza VALUES('I558','6','Walau cobaan menindas,<br/>aku tak gelisah;<br/>Serahkan kuatir pada-Nya,<br/>rohku pun bebaslah.<br/>',NULL,63078,6);
INSERT INTO stanza VALUES('I558','7','Aku mau tulus, murni,<br/>sekutu dengan-Mu;<br/>Oleh Roh-Mu gerak, langkah,<br/>depan-Mu berdoa.<br/>',NULL,63079,7);
INSERT INTO stanza VALUES('I559','1','Demi nama Tuhan Yesus,<br/>depan takhta ku sujud,<br/>Kalahkan tentara gelap,<br/>dan panah api musuh.<br/>',NULL,63080,1);
INSERT INTO stanza VALUES('I559','chorus','Nama-Nya, p''nuh kuasa!<br/>Kami menang kar''na-Nya!<br/>Nama-Nya, p''nuh kuasa!<br/>Iblis, dosa tak daya!<br/>',NULL,63081,2);
INSERT INTO stanza VALUES('I559','2','Saat doa pada Yesus,<br/>tent''ra Iblis pun takluk;<br/>Nama Yesus yang p''nuh kuasa,<br/>menang mutlak s''lamanya!<br/>',NULL,63082,3);
INSERT INTO stanza VALUES('I559','3','Tuhan seg''ra datang pula,<br/>bawa ku masuk mulia;<br/>Nama-Nya yang penuh kuasa,<br/>membuatku meraja!<br/>',NULL,63083,4);
INSERT INTO stanza VALUES('I560','1','Katakan, "Hai gunung,<br/>masuklah ke laut!"<br/>Kalau tidak bimbang,<br/>jadilah katamu.<br/>Percaya Dia, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63084,1);
INSERT INTO stanza VALUES('I560','2','Ambil kuasa tebus,<br/>yang dibeli darah;<br/>Agar berkhasiat,<br/>Tritunggal pun datang.<br/>Taat firman, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63085,2);
INSERT INTO stanza VALUES('I560','3','Diri, dosa, sakit,<br/>sudah Tuhan tanggung,<br/>Syarat-Nya terp''nuhi,<br/>kamu pun bebaslah.<br/>Sandar firman, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63086,3);
INSERT INTO stanza VALUES('I560','4','K''liling tembok tinggi,<br/>doa demi iman;<br/>Seb''lum tembok rubuh,<br/>sorak kemenangan.<br/>Tenang, yakin, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63087,4);
INSERT INTO stanza VALUES('I560','5','Pintu dari besi,<br/>semua takluk, jatuh,<br/>Tent''ra yang percaya,<br/>semua sorak, masuk.<br/>Abai musuh, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63088,5);
INSERT INTO stanza VALUES('I560','6','Ambil iman Allah,<br/>lepas keraguan;<br/>Luaskan perang Allah,<br/>buang alamiah.<br/>Pegang firman, pasti genap,<br/>dalam Tuhan p''rintah gunung!<br/>',NULL,63089,6);
INSERT INTO stanza VALUES('I561','1','Demi iman ku memohon,<br/>berdoa depan takhta,<br/>Kalau yakin, Tuhan jawab,<br/>"Tengoklah, sudah genap!"<br/>',NULL,63090,1);
INSERT INTO stanza VALUES('I561','2','Demi iman ku memohon,<br/>Roh Kudus pimpin doa,<br/>Dia pasti selamatkan,<br/>melampaui dugaan.<br/>',NULL,63091,2);
INSERT INTO stanza VALUES('I561','3','Demi iman ku memohon,<br/>b''rani berdiri tegap,<br/>Penuh damai, harap,<br/>girang, meminta pada Allah.<br/>',NULL,63092,3);
INSERT INTO stanza VALUES('I561','4','Demi iman ku memohon,<br/>tekun minta d''ngan iman,<br/>Kapan saja, mana saja,<br/>jamah Allah, dikenan.<br/>',NULL,63093,4);
INSERT INTO stanza VALUES('I562','1','Nyanyi kidung iman!<br/>Walau malam kelam;<br/>Kita muji, Allah kerja.<br/>Hingga demi iman kita mendapatkan.<br/>',NULL,63094,1);
INSERT INTO stanza VALUES('I562','2','Nyanyi kidung iman!<br/>Jiwaku soraklah!<br/>Allah ''kenan kidung iman.<br/>Melewati malam yang gelap dan panjang.<br/>',NULL,63095,2);
INSERT INTO stanza VALUES('I562','3','Nyanyi kidung iman!<br/>Musuh pasti gentar!<br/>Pujian membuat kita menang.<br/>Setan pasti kalah; puji, jangan diam.<br/>',NULL,63096,3);
INSERT INTO stanza VALUES('I562','4','Nyanyi kidung iman!<br/>Fajar sg''ra merekah;<br/>Kita seg''ra jumpa Tuhan.<br/>Kita nyanyi kidung pujian tak bersudah.<br/>',NULL,63097,4);
INSERT INTO stanza VALUES('I563','1','Dalam roh doa sehati,<br/>bukan demi pikiran,<br/>Hanya ikut urapan-Nya,<br/>genapkan kehendak-Nya.<br/>',NULL,63098,1);
INSERT INTO stanza VALUES('I563','chorus','Dalam roh doa sehati,<br/>bukan demi pikiran,<br/>Hanya ikut urapan-Nya,<br/>genapkan kehendak-Nya.<br/>',NULL,63099,2);
INSERT INTO stanza VALUES('I563','2','Dalam roh doa sehati,<br/>sangkal diri d''mi salib,<br/>Semua harap, s''gala minat,<br/>biar Roh yang kendali.<br/>',NULL,63100,3);
INSERT INTO stanza VALUES('I563','3','Dalam roh doa sehati,<br/>pakai kuasa surgawi,<br/>Injak semua untung bumi,<br/>serang penguasa langit.<br/>',NULL,63101,4);
INSERT INTO stanza VALUES('I563','4','Dalam roh doa sehati,<br/>mohon dengan kaum saleh,<br/>Cari hasrat, pimpinan-Nya,<br/>roh sehati, terjaga.<br/>',NULL,63102,5);
INSERT INTO stanza VALUES('I563','5','Dalam roh doa sehati,<br/>doa jaga, tekunlah,<br/>Demi k''rajaan, mulia-Nya,<br/>berdoa sampai dapat.<br/>',NULL,63103,6);
INSERT INTO stanza VALUES('I563','6','dalam roh doa sehati,<br/>rukun mencari Allah,<br/>Dalam Tubuh-Nya, dalam roh,<br/>doa sehati s''lama.<br/>',NULL,63104,7);
INSERT INTO stanza VALUES('I564','1','Doa harus di dalam roh,<br/>bukan daging dan otak,<br/>Kalau s''lalu demikian,<br/>hadir Allah didapat.<br/>',NULL,63105,1);
INSERT INTO stanza VALUES('I564','chorus','Doa harus di dalam roh,<br/>ini Tuhan wahyukan,<br/>Dalam roh menyentuh Tuhan,<br/>ini harus dipegang.<br/>',NULL,63106,2);
INSERT INTO stanza VALUES('I564','2','Doa harus di dalam roh,<br/>bukan demi pikiran,<br/>Dengan Allah bersekutu,<br/>limpah mengecap Allah.<br/>',NULL,63107,3);
INSERT INTO stanza VALUES('I564','3','Doa harus di dalam roh,<br/>ucapkan kehendak-Nya,<br/>Dalam roh bersama Tuhan,<br/>diriku dibakar-Nya.<br/>',NULL,63108,4);
INSERT INTO stanza VALUES('I564','4','Doa harus di dalam roh,<br/>begitu pun keluhan,<br/>Roh Kudus mengatur, pimpin,<br/>''nyatakan kehendak-Nya.<br/>',NULL,63109,5);
INSERT INTO stanza VALUES('I564','5','Doa harus di dalam roh,<br/>di tempat mahakudus,<br/>Hanya bila di dalam roh,<br/>bisa baur dengan-Nya.<br/>',NULL,63110,6);
INSERT INTO stanza VALUES('I564','6','Doa harus di dalam roh,<br/>ini jalan yang unik,<br/>Kelimpahan ilahi-Nya,<br/>demi doa didapat.<br/>',NULL,63111,7);
INSERT INTO stanza VALUES('I565','1','Doa jamah takhta-Nya,<br/>jamah takhta kurnia,<br/>T''rima rahmat dan kurnia,<br/>bantuan pada waktunya.<br/>',NULL,63112,1);
INSERT INTO stanza VALUES('I565','2','Doa jamah takhta-Nya,<br/>sangat perlu kurnia-Nya,<br/>Di roh bersama Allah,<br/>sekutu tanpa hambat.<br/>',NULL,63113,2);
INSERT INTO stanza VALUES('I565','3','Doa jamah takhta-Nya,<br/>kenal kurnia limpah,<br/>Ambil, nikmati ''tiasa,<br/>puji syukur pada-Nya.<br/>',NULL,63114,3);
INSERT INTO stanza VALUES('I565','4','Doa jamah takhta-Nya,<br/>jamah takhta kuasa-Nya,<br/>Di dalam nama Kristus,<br/>bereskan maut, Satan.<br/>',NULL,63115,4);
INSERT INTO stanza VALUES('I565','5','Doa jamah takhta-Nya,<br/>dengan iman yang hidup,<br/>Pakai kuasa surga,<br/>bereskan kuasa maut.<br/>',NULL,63116,5);
INSERT INTO stanza VALUES('I565','6','Doa jamah takhta-Nya,<br/>kuasa alam maut guncang,<br/>Doa d''ngan kuasa raja,<br/>kini doa dengan-Nya.<br/>',NULL,63117,6);
INSERT INTO stanza VALUES('I566','1','Ku mau doa ''tiasa,<br/>dan berlatih roh!<br/>Dulu kurang doa,<br/>hingga roh tumpul;<br/>Kadang ada doa,<br/>jarang pakai roh;<br/>Banyak mohon hal-hal,<br/>tak ikuti roh.<br/>',NULL,63118,1);
INSERT INTO stanza VALUES('I566','2','Kini di roh doa,<br/>turut kesah-Nya,<br/>Demi roh doakan,<br/>bukan ingatan;<br/>Tak sandarlah otak,<br/>rohlah semata,<br/>Semua doa, pujian,<br/>roh b''ri pimpinan.<br/>',NULL,63119,2);
INSERT INTO stanza VALUES('I566','3','Sendirian berdoa,<br/>ku berlatih roh;<br/>Bersama berdoa,<br/>tetap latih roh.<br/>Bukan doa luar,<br/>tak gunakan roh,<br/>Namun lubuk batin,<br/>roh menyahut roh.<br/>',NULL,63120,3);
INSERT INTO stanza VALUES('I566','4','Bukan sama layan,<br/>tapi lain doa,<br/>Bibir bersekutu,<br/>roh tak bergerak.<br/>Bukan sama doa,<br/>roh tak berkontak,<br/>Jeritan luaran,<br/>batin tak jamah.<br/>',NULL,63121,4);
INSERT INTO stanza VALUES('I566','5','Doa di mana jua,<br/>dan berlatih roh,<br/>Berapa pun orang<br/>tetap pakai roh.<br/>Waktu, tempat, orang,<br/>tiada pengaruh,<br/>Sidang apa saja<br/>roh tak terbalut.<br/>',NULL,63122,5);
INSERT INTO stanza VALUES('I566','6','Begitu roh bubung,<br/>Tuhan ''kan lancar,<br/>Begitu roh tegap,<br/>aku berguna.<br/>Di roh hayat deras,<br/>saleh baurlah,<br/>Mengalir demikian,<br/>g''reja terbina.<br/>',NULL,63123,6);
INSERT INTO stanza VALUES('I567','1','Doa ''nyatakan Tuhan,<br/>tidak ''nyatakan diri,<br/>Tuhan wahyu diri-Nya,<br/>ku nyatakan maksud-Nya.<br/>',NULL,63124,1);
INSERT INTO stanza VALUES('I567','2','Doa ''nyatakan Tuhan,<br/>ucapkan kehendak-Nya,<br/>Tenangkan pikiranku,<br/>lekat pikiran Tuhan.<br/>',NULL,63125,2);
INSERT INTO stanza VALUES('I567','3','Doa ''nyatakan Tuhan,<br/>selalu pandang Tuhan,<br/>Bagai memandang cermin,<br/>pantulkan mulia-Nya.<br/>',NULL,63126,3);
INSERT INTO stanza VALUES('I567','4','Doa ''nyatakan Tuhan,<br/>Dia mohon lewatku,<br/>Kristus yang di batinku,<br/>pada Kristus di surga.<br/>',NULL,63127,4);
INSERT INTO stanza VALUES('I567','5','Doa ''nyatakan Tuhan,<br/>b''lajar tak sandar diri,<br/>Mutlak doa pada-Nya,<br/>sandar Tuhan s''lamanya.<br/>',NULL,63128,5);
INSERT INTO stanza VALUES('I568','1','Doa sekutu d''ngan Tuhan,<br/>mencari-Nya dalam roh,<br/>Di depan-Nya tanya, dengar,<br/>tenang diam menunggu.<br/>',NULL,63129,1);
INSERT INTO stanza VALUES('I568','chorus','Doa sekutu d''ngan Tuhan,<br/>mencari-Nya dalam roh,<br/>Di depan-Nya tanya, dengar,<br/>tenang diam menunggu.<br/>',NULL,63130,2);
INSERT INTO stanza VALUES('I568','2','Doa sekutu d''ngan Tuhan,<br/>buka genap dirimu,<br/>Dengan muka tanpa s''lubung,<br/>murni, suci, dan tulus.<br/>',NULL,63131,3);
INSERT INTO stanza VALUES('I568','3','Doa sekutu d''ngan Tuhan,<br/>demi iman cari Dia,<br/>Jamah Dia Roh yang hidup,<br/>hormat, harap, ''tengadah.<br/>',NULL,63132,4);
INSERT INTO stanza VALUES('I568','4','Doa sekutu d''ngan Tuhan,<br/>roh dan benar kuncinya,<br/>Harus dalam roh berdoa,<br/>jamah rasa di dalam.<br/>',NULL,63133,5);
INSERT INTO stanza VALUES('I568','5','Doa sekutu d''ngan Tuhan,<br/>tekun dengar firman-Nya,<br/>Hasrat-Nya t''rukir dalammu,<br/>kau genapkan maksud-Nya.<br/>',NULL,63134,6);
INSERT INTO stanza VALUES('I568','6','Doa sekutu d''ngan Tuhan,<br/>salut sinar wajah-Nya,<br/>Indah-Nya meresapimu,<br/>kau pantulkan wajah-Nya.<br/>',NULL,63135,7);
INSERT INTO stanza VALUES('I569','1','Doa berlelah d''ngan-Nya,<br/>bubuh jalan bagi-Nya;<br/>Doa mendorong Tuhan,<br/>pun desak ku ikut Dia.<br/>',NULL,63136,1);
INSERT INTO stanza VALUES('I569','2','Doa berlelah d''ngan-Nya,<br/>turut maksud tujuan-Nya;<br/>Mutlak satu dengan-Nya,<br/>sampai berkat melimpah.<br/>',NULL,63137,2);
INSERT INTO stanza VALUES('I569','3','Doa berlelah d''ngan-Nya,<br/>buang ambisi awak;<br/>Tolak opini diri,<br/>peduli kehendak-Nya.<br/>',NULL,63138,3);
INSERT INTO stanza VALUES('I569','4','Doa berlelah d''ngan-Nya,<br/>biar Tuhan yang memulai;<br/>S''mua rencana dan karya,<br/>lewat ku Dia rampungkan.<br/>',NULL,63139,4);
INSERT INTO stanza VALUES('I569','5','Doa berlelah d''ngan-Nya,<br/>sampai roda bergerak;<br/>Doa bersama Tuhan,<br/>sampai g''reja bergerak.<br/>',NULL,63140,5);
INSERT INTO stanza VALUES('I570','1','Ku berperang bagi Tuhan,<br/>Iblis tidak t''rima,<br/>Dia memakai s''mua kuasanya,<br/>untuk menghambatku,<br/>Ku ''tiasa berdoa,<br/>agar musuh kabur,<br/>b''ri pada Tuhan,<br/>semua bereslah.<br/>',NULL,63141,1);
INSERT INTO stanza VALUES('I570','chorus','B''ri tahu pada Tuhan,<br/>semua bereslah,<br/>B''ri tahu pada Tuhan,<br/>semua bereslah,<br/>Syukurlah, tiap kali temui cobaan,<br/>B''ri tahu pada Tuhan,<br/>semua bereslah.<br/>',NULL,63142,2);
INSERT INTO stanza VALUES('I570','2','Meski jumpa gelap, badai,<br/>tempuh jalan sulit,<br/>Meski cobaan bertubi,<br/>hari depan kuatir,<br/>Sekejap ku menang,<br/>kar''na sandar Tuhan,<br/>B''ri tahu pada Tuhan,<br/>semua bereslah.<br/>',NULL,63143,3);
INSERT INTO stanza VALUES('I570','3','Saat teman menyerangku,<br/>tiada yang dukungku,<br/>Saat ku lemah, sendirian,<br/>difitnah, ditolak,<br/>Beri tahu Tuhan,<br/>Dia segera hibur,<br/>Sungguh, b''ri tahu Tuhan,<br/>semua bereslah.<br/>',NULL,63144,4);
INSERT INTO stanza VALUES('I570','4','S''kutu mesra dengan tuhan,<br/>resah hati sirna,<br/>Hari-hari nyanyi riang,<br/>sandar ribaan Tuhan,<br/>Ku sandar bahu-Nya,<br/>s''lama ku buktikan,<br/>B''ri tahu pada Tuhan,<br/>semua bereslah.<br/>',NULL,63145,5);
INSERT INTO stanza VALUES('I571','1','Yesus itu sobat kita,<br/>yang tanggung dosa kita;<br/>Dia beri hak pada kita,<br/>bawa s''mua dalam doa.<br/>Sering damai kita hilang,<br/>malah sakit menindas,<br/>Kar''na kita tak membawa<br/>semua hal dalam doa.<br/>',NULL,63146,1);
INSERT INTO stanza VALUES('I571','2','Adakah coba dan goda,<br/>atau susah derita?<br/>Kita tak perlu kecewa,<br/>bawa s''mua dalam doa.<br/>Siapa p''ri Dia tulus, setia,<br/>yang tanggung d''rita kita?<br/>Yesus tahu lemah kita,<br/>bawa s''mua dalam doa.<br/>',NULL,63147,2);
INSERT INTO stanza VALUES('I571','3','Adakah lelah, beban b''rat,<br/>susah, kuatir, gelisah?<br/>Ingat pada P''nolong kita,<br/>bawa s''mua dalam doa.<br/>Adakah temanmu khianat?<br/>Beri tahu pada-Nya;<br/>Dia perisai, jaga kita,<br/>semua duka lenyaplah.<br/>',NULL,63148,3);
INSERT INTO stanza VALUES('I572','1','Semua d''ritaku, b''ri tahu Tuhan,<br/>tak sanggup ku tanggung sendiri;<br/>Tuhan menghibur, waktu sengsara,<br/>seka air mata, b''ri simpati.<br/>',NULL,63149,1);
INSERT INTO stanza VALUES('I572','chorus','B''ri tahu Tuhan! B''ri tahu Tuhan!<br/>Curah isi hati pada-Nya,<br/>B''ri tahu Tuhan! B''ri tahu Tuhan!<br/>Dia yang tahu, beri hibur.<br/>',NULL,63150,2);
INSERT INTO stanza VALUES('I572','2','Semua susahku, b''ri tahu Tuhan,<br/>tak bisa aku hadapinya,<br/>S''mua perkaraku, Dia yang pikul,<br/>ku rasa lega dan terhibur.<br/>',NULL,63151,3);
INSERT INTO stanza VALUES('I572','3','Semua kurangku, b''ri tahu Tuhan,<br/>tak mampu aku buang kuatirku,<br/>Semua perluku, Tuhan puaskan,<br/>nikmat kaya-Nya limpah sungguh.<br/>',NULL,63152,4);
INSERT INTO stanza VALUES('I572','4','Semua lemahku, b''ri tahu Tuhan,<br/>tak dapat aku lawan nafsu,<br/>S''mua ikatanku, Tuhan yang bantu,<br/>ku bebas dari hukum dosa.<br/>',NULL,63153,5);
INSERT INTO stanza VALUES('I572','5','S''mua cobaanku, b''ri tahu Tuhan,<br/>tak sanggup aku lawan Iblis,<br/>Tuhan dicobai, sama denganku,<br/>hanya Dia mampu bebaskanku.<br/>',NULL,63154,6);
INSERT INTO stanza VALUES('I573','1','Kudus, agung tugas imam!<br/>Sembah kurban pada Allah,<br/>Sering masuk tempat kudus,<br/>membakar ukupan!<br/>',NULL,63155,1);
INSERT INTO stanza VALUES('I573','chorus','Membakar ukupan!<br/>Membakar ukupan!<br/>Depan Allah nyala dian,<br/>pula nyanyi lantang!<br/>',NULL,63156,2);
INSERT INTO stanza VALUES('I573','2','Tempat kudus tiada sinar,<br/>kecuali cahaya dian;<br/>Setiap bakar ukupan,<br/>wajib nyala dian.<br/>',NULL,63157,3);
INSERT INTO stanza VALUES('I573','3','Demi membakar ukupan,<br/>''bubung harum kebangkitan,<br/>Selain dian dan ukupan,<br/>tambah nyanyi lantang!<br/>',NULL,63158,4);
INSERT INTO stanza VALUES('I573','4','Doa membakar ukupan,<br/>''bubung harum kebangkitan,<br/>Allah berkenan pun senang,<br/>Allah - kita nikmat.<br/>',NULL,63159,5);
INSERT INTO stanza VALUES('I573','5','Baca firman, t''rima terang,<br/>itu menyalakan dian;<br/>Sinar ilahi memancar,<br/>semua gelap hilang.<br/>',NULL,63160,6);
INSERT INTO stanza VALUES('I573','6','Ku mau nyanyikan pujian,<br/>seperti imam bergita;<br/>Kasih kurnia-Nya tak hingga,<br/>kenyang nikmati Dia.<br/>',NULL,63161,7);
INSERT INTO stanza VALUES('I573','7','Doa, sembahkan ukupan,<br/>baca firman, t''rima terang;<br/>Nyanyikan kasih kurnia-Nya,<br/>Roh Tuhan berkenan.<br/>',NULL,63162,8);
INSERT INTO stanza VALUES('I574','1','Ku menunggu, ya, ku menunggu,<br/>ku rahat dalam-Mu,<br/>Jelas kehendak-Mu, inilah pintaku -<br/>Ku menunggu, ku menunggu.<br/>',NULL,63163,1);
INSERT INTO stanza VALUES('I574','2','Ku menunggu, ya, ku menunggu,<br/>saat ku di sini,<br/>Selamatkan aku, doa lewat Tuhan -<br/>Ku menunggu, ku menunggu.<br/>',NULL,63164,2);
INSERT INTO stanza VALUES('I574','3','Ku menunggu, ya, ku menunggu,<br/>mutlak baur denganku,<br/>Sampai diam dalamku, gambar-Mu terwujud -<br/>Ku menunggu, ku menunggu.<br/>',NULL,63165,3);
INSERT INTO stanza VALUES('I574','4','Ku menunggu, ya, ku menunggu,<br/>tunjukkan murad-Mu,<br/>Maju di jalan-Mu, alirkan hayat-Mu -<br/>Ku menunggu, ku menunggu.<br/>',NULL,63166,4);
INSERT INTO stanza VALUES('I574','5','Ku menunggu, ya, ku menunggu,<br/>moga s''mua doaku,<br/>Hanya ekspresi-Mu, Allah mulia sungguh -<br/>Ku menunggu, ku menunggu.<br/>',NULL,63167,5);
INSERT INTO stanza VALUES('I575','1','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Dia sabda dulu, baru kau minta.<br/>Doa sejati, Tuhan yang mulai;<br/>Kau-lah bejana, ''nyatakan Tuhan.<br/>',NULL,63168,1);
INSERT INTO stanza VALUES('I575','2','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Semua opini, jangan dihirau.<br/>Dengan diri-Nya, Dia urapimu,<br/>doa dan hidup, lewat dirimu.<br/>',NULL,63169,2);
INSERT INTO stanza VALUES('I575','3','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Henti hasratmu, juga jalanmu.<br/>Buang kuatir, rayuan dunia,<br/>hanya peduli yang Allah maui.<br/>',NULL,63170,3);
INSERT INTO stanza VALUES('I575','4','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Niat hatimu, takluk pada Roh.<br/>Biar roh tunjukkan kehendak Allah,<br/>kau pun menjadi pelayan yang baik.<br/>',NULL,63171,4);
INSERT INTO stanza VALUES('I575','5','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Belajar biar roh lewat doamu.<br/>S''luruh dirimu baur dengan Roh,<br/>hingga doamu, ekspresi Allah.<br/>',NULL,63172,5);
INSERT INTO stanza VALUES('I575','6','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Sampai dalam roh, kau mirip Allah.<br/>Melalui roh, semua takluk,<br/>semua bagian mirip d''ngan Tuhan.<br/>',NULL,63173,6);
INSERT INTO stanza VALUES('I575','7','Jiwaku tenang, tunggu Tuhan-Mu!<br/>Lewat dirimu, Dia ''ngalir bebas.<br/>Tiap saat tutur dan p''rilakumu,<br/>maksud hati-Nya lewatmu rampung.<br/>',NULL,63174,7);
INSERT INTO stanza VALUES('I576','1','Bangkitkan, ya, Tuhan!<br/>Mohon tampilan-Mu!<br/>Kuasa-Mu perintahkan,<br/>kaum saleh siaga t''rus.<br/>',NULL,63175,1);
INSERT INTO stanza VALUES('I576','chorus','Bangkitkan, ya, Tuhan!<br/>Kami mendoakan;<br/>Tatkala kami meranap,<br/>tangan-Mu menggarap.<br/>',NULL,63176,2);
INSERT INTO stanza VALUES('I576','2','Bangkitkan, ya, Tuhan!<br/>Gerakkan gereja;<br/>Berduka terhadap dosa,<br/>gerak-Mu leluasa.<br/>',NULL,63177,3);
INSERT INTO stanza VALUES('I576','3','Bangkitkan, ya, Tuhan!<br/>Wahyukan diri-Mu;<br/>Moga kasih-Mu menjamah<br/>setiap manusia.<br/>',NULL,63178,4);
INSERT INTO stanza VALUES('I576','4','Bangkitkan, ya, Tuhan!<br/>Berkati firman-Mu;<br/>Moga kebenaran sabda,<br/>dijunjung tiasa.<br/>',NULL,63179,5);
INSERT INTO stanza VALUES('I576','5','Bangkitkan, ya, Tuhan!<br/>Buktikan menang-Mu;<br/>Saat umat-Mu berperang,<br/>kuasa musuh runtuh.<br/>',NULL,63180,6);
INSERT INTO stanza VALUES('I576','6','Bangkitkan, ya, Tuhan!<br/>Curahkan kuasa-Mu;<br/>S''mua mulia bagi nama-Mu,<br/>berkat ''tuk umat-Mu.<br/>',NULL,63181,7);
INSERT INTO stanza VALUES('I577','1','B''rikanlah, ya Tuhan,<br/>di tempat ini,<br/>Kebangunan besar,<br/>dalam rohani;<br/>Buang s''mua hambatan,<br/>biar roh meninggi,<br/>Dengan hayat Tuhan,<br/>kami mengabdi.<br/>',NULL,63182,1);
INSERT INTO stanza VALUES('I578','1','Waktu doa, waktu indah!<br/>Membuatku lepas s''mua gundah;<br/>Depan takhta mencurahkan<br/>minat serta keperluan;<br/>Saat ku jumpa tekanan,<br/>rohku malah terbebaskan,<br/>Lepas perangkap si jahat,<br/>Kau beserta waktu doa!<br/>',NULL,63183,1);
INSERT INTO stanza VALUES('I578','2','Waktu doa, waktu indah!<br/>Bagai terbang ke takhta-Nya,<br/>Tekun doa pada Allah,<br/>Dia Sang Setia, Dia Sang Benar.<br/>Dia berkenan ku cari-Nya,<br/>percaya, sandar firman-Nya,<br/>Ku mau serahkan s''mua beban,<br/>di depan-Nya, waktu doa!<br/>',NULL,63184,2);
INSERT INTO stanza VALUES('I578','3','Waktu doa, waktu indah!<br/>Dia serta pun b''ri hiburan,<br/>Bawa ku ke gunung Pisga,<br/>nampak tanah permai indah.<br/>Lepas kemah, tunggu tenang,<br/>iman, harapan ternyata;<br/>Ku mau gita melantang,<br/>aman, damai, waktu doa!<br/>',NULL,63185,3);
INSERT INTO stanza VALUES('I579','1','S''luruh Alkitab, hembusan Allah,<br/>Allah wahyukan lewat Roh Kudus;<br/>Dicatat oleh manusia Allah,<br/>bawa kaya-Nya, untuk manusia.<br/>',NULL,63186,1);
INSERT INTO stanza VALUES('I579','2','Hembusan Allah jadi t''rang insan,<br/>d''ngan sinar kudus terangi insan;<br/>Sorot dalam g''lap,<br/>insan melihat keperluan dan kondisi diri.<br/>',NULL,63187,2);
INSERT INTO stanza VALUES('I579','3','Hembusan Allah menjadi hayat,<br/>hingga insan t''rima hayat Allah;<br/>Hidup dan lahir-ulangkan insan,<br/>barui pikiran pun ubah jiwa.<br/>',NULL,63188,3);
INSERT INTO stanza VALUES('I579','4','Hembusan Allah, menjadi hikmat,<br/>paham pengetahuan ilahi;<br/>Mewahyukan maksud kekal Allah,<br/>pimpin insan capai tujuan Allah.<br/>',NULL,63189,4);
INSERT INTO stanza VALUES('I579','5','Hembusan Allah, jadi kuat insan,<br/>kuat ilahi mensuplai insan;<br/>Yang lemah, letih, jadi kuat segar,<br/>hingga mampu capai murad Allah.<br/>',NULL,63190,5);
INSERT INTO stanza VALUES('I579','6','Hembusan Allah, untuk nafasku,<br/>agar aku nikmati berkat-Nya;<br/>Dengan roh hirup hembusan Allah,<br/>suplai perluku, nikmat limpah-Nya.<br/>',NULL,63191,6);
INSERT INTO stanza VALUES('I580','1','Allah t''lah bersabda singkap diri-Nya;<br/>sifat, status-Nya dikenal manusia;<br/>Wahyukan murad-Nya pada manusia,<br/>ungkap lewat kata, lambang, nubuat.<br/>',NULL,63192,1);
INSERT INTO stanza VALUES('I580','2','Allah bicara ''nyatakan murad-Nya:<br/>Putra-Nya jadi kepala semesta,<br/>Dalam Putra Dia dimuliakan,<br/>terekspresi dalam s''gala sesuatu.<br/>',NULL,63193,2);
INSERT INTO stanza VALUES('I580','3','Allah bicara Kristus diwahyukan;<br/>Dia Allah sejati juga manusia;<br/>Dia segalanya, penuhi semua,<br/>pusat dan lingkaran rencana Allah.<br/>',NULL,63194,3);
INSERT INTO stanza VALUES('I580','4','Allah bicara, bersuara di surga:<br/>Allah Tritunggal baur dengan insan,<br/>Bapa dalam Anak, Anak dalam Roh,<br/>dalam Tubuh Kristus, genap rencana.<br/>',NULL,63195,4);
INSERT INTO stanza VALUES('I580','5','Allah bicara wahyukan rahasia:<br/>Kristus dan g''reja, dua jadi satu,<br/>Bawa limpah Allah, jadi Kepala,<br/>g''reja Tubuh-Nya nikmati s''gala-Nya.<br/>',NULL,63196,5);
INSERT INTO stanza VALUES('I580','6','Allah bicara, wahyukan semua:<br/>hal penciptaan dan inkarnasi-Nya,<br/>Penebusan dan keselamatan-Nya;<br/>moga s''mua yang di bumi memuji-Nya.<br/>',NULL,63197,6);
INSERT INTO stanza VALUES('I581','1','Firman hidup Allah, gambar Allah,<br/>Dikau isi firman tertulis-Nya;<br/>Dalam-Mu kita nampak limpah-Nya,<br/>lewat Alkitab Kau ternyatakan.<br/>',NULL,63198,1);
INSERT INTO stanza VALUES('I581','2','Selain Kau tiada yang lihat Allah,<br/>tanpa Alkitab Kau tak terwahyu;<br/>Kau jelaskan Alah pada insan,<br/>kenal Kau harus lewat Alkitab.<br/>',NULL,63199,2);
INSERT INTO stanza VALUES('I581','3','Kau jelmaan Allah yang sempurna,<br/>Alkitab adalah uraian-Mu;<br/>Dalam-Mu ku paham diri Allah,<br/>lewat Alkitab Kau riil bagiku.<br/>',NULL,63200,3);
INSERT INTO stanza VALUES('I581','4','Dikau Sang Roh hayat juga firman,<br/>penuh kaya limpah Roh ada-Mu;<br/>Lewat roh batini jamah firman,<br/>Kau berikan kaya-Mu padaku.<br/>',NULL,63201,4);
INSERT INTO stanza VALUES('I581','5','Sekutu d''ngan Allah di dalam-Mu,<br/>lewat Alkitab nikmat diri-Mu;<br/>Setiap doa baca d''ngan firman-Mu,<br/>kaya-Mu cukupi keperluanku.<br/>',NULL,63202,5);
INSERT INTO stanza VALUES('I581','6','Tuhan, ajarlah ku pakai rohku,<br/>doa baca firman t''rima suplai;<br/>Kau baur bersatu d''ngan firman-Mu,<br/>jadi manna, suplai harianku.<br/>',NULL,63203,6);
INSERT INTO stanza VALUES('I582','1','Kau-lah firman, Kau juga Roh,<br/>kami puji di dalam roh!<br/>Puji firman-Mu b''ri tahu,<br/>menyembah Roh, Kau ku sentuh.<br/>',NULL,63204,1);
INSERT INTO stanza VALUES('I582','2','Tuhan, Kau-lah segalaku,<br/>satu padu Kau denganku;<br/>Kau-lah firman, Kau juga Roh,<br/>hingga jadi suplaianku.<br/>',NULL,63205,2);
INSERT INTO stanza VALUES('I582','3','Andai Tuhan bukan firman,<br/>bagaimana mengenal-Mu?<br/>Andai Allah pun bukan Roh,<br/>bagaimana ku menyentuh?<br/>',NULL,63206,3);
INSERT INTO stanza VALUES('I582','4','Firman itulah wahyu-Mu,<br/>hingga aku mengenal-Mu;<br/>Roh itulah hakiki-Mu,<br/>hingga ku jamah ada-Mu.<br/>',NULL,63207,4);
INSERT INTO stanza VALUES('I582','5','Kau-lah hayat dan terangku,<br/>jalan, keb''naran, air, suplai;<br/>Lewat firman, mencapaiku,<br/>oleh Roh-Mu, ku alami.<br/>',NULL,63208,5);
INSERT INTO stanza VALUES('I582','6','Firman-Mu dalam Alkitab,<br/>Roh-Mu s''mayam dalam insan;<br/>Firman masuk hati, rohku,<br/>itulah Roh juga hayat.<br/>',NULL,63209,6);
INSERT INTO stanza VALUES('I582','7','Ku mau paham Alkitab-Mu,<br/>pula jamah Roh Kudus-Mu;<br/>Bukan hanya demi otak,<br/>bahkan sembah, doa di roh.<br/>',NULL,63210,7);
INSERT INTO stanza VALUES('I582','8','Firman-Mu itu ku gemar,<br/>Roh-Mu lebih aku sembah;<br/>Dalam firman, hati senang,<br/>dalam Roh-Mu, rohku girang.<br/>',NULL,63211,8);
INSERT INTO stanza VALUES('I583','1','Tuhan, pecahkanlah roti hidup,<br/>sep''ri t''lah Kau perbuat di tepi laut;<br/>Ku harap pada-Mu dengan rindu,<br/>kar''na Kau firman Allah yang hidup.<br/>',NULL,63212,1);
INSERT INTO stanza VALUES('I583','2','Tuhan, pecahkanlah roti hidup,<br/>biar ku p''nuh cinta, ingat nama-Mu!<br/>Lepaskan anganku dari ego,<br/>biar cenderungku hanya pada-Mu.<br/>',NULL,63213,2);
INSERT INTO stanza VALUES('I583','3','Tuhan, buatlah ku ta''u keb''naran-Mu,<br/>yang Tuhan jelaskan demi wahyu;<br/>Hingga ku berjalan beserta-Mu,<br/>tersirat mulia-Mu dalam kalbu.<br/>',NULL,63214,3);
INSERT INTO stanza VALUES('I583','4','Tuhan, berkatilah berita-Mu,<br/>biar ku lepas dari ikatanku;<br/>Hingga ku bekerja serta hidup,<br/>bagi Kristus, Tuhan-ku melulu.<br/>',NULL,63215,4);
INSERT INTO stanza VALUES('I584','1','Tuhan, tiada satu kata?<br/>Agar ku bers''rah pada-Mu,<br/>Tinggalkan semua yang cemar,<br/>Tuhan, b''rilah satu kata.<br/>',NULL,63216,1);
INSERT INTO stanza VALUES('I584','2','Sepatah singkap lemahku,<br/>saat ku megahkan awak,<br/>Jerih lelah dengan sia-sia,<br/>Tuhan, b''rilah satu kata.<br/>',NULL,63217,2);
INSERT INTO stanza VALUES('I584','3','Sepatah sirat mesra-Mu;<br/>kar''na Kau tinggal dalamku,<br/>Ku berbagian hayat-Mu,<br/>Tuhan, b''rilah satu kata.<br/>',NULL,63218,3);
INSERT INTO stanza VALUES('I584','4','Sepatah janji yang kuat,<br/>lawan banyak kekuatiran,<br/>Tutur lembut-Mu yang jelas,<br/>Tuhan, b''rilah satu kata.<br/>',NULL,63219,4);
INSERT INTO stanza VALUES('I584','5','Sepatah sorak kem''nangan,<br/>dapat janji-Mu yang manis,<br/>Kekal riang tinggal d''ngan-Mu,<br/>Tuhan, b''rilah satu kata.<br/>',NULL,63220,5);
INSERT INTO stanza VALUES('I585','1','Tuhan bicaralah,<br/>saat ku tunggu,<br/>Hatiku mendengar,<br/>penuh harapan.<br/>',NULL,63221,1);
INSERT INTO stanza VALUES('I585','2','Tuhan bicaralah,<br/>sewaktu tenang,<br/>Ku nampak wajah-Mu,<br/>t''rima p''tunjuk-Mu.<br/>',NULL,63222,2);
INSERT INTO stanza VALUES('I585','3','Firman yang Kau ucap:<br/>roh juga hayat,<br/>Roti dari surga,<br/>menyuplai rohku.<br/>',NULL,63223,3);
INSERT INTO stanza VALUES('I585','4','Semua bagi Tuhan,<br/>bukan bagiku,<br/>Sukarela tunduk,<br/>jadi milik-Mu.<br/>',NULL,63224,4);
INSERT INTO stanza VALUES('I585','5','Tuhan bicaralah,<br/>jangan membisu,<br/>Rohku menengadah,<br/>dapat firman-Mu.<br/>',NULL,63225,5);
INSERT INTO stanza VALUES('I585','6','Firman-Mu yang kaya,<br/>p''nuhi hatiku,<br/>Hingga s''mua hasrat-Mu,<br/>genap dalamku.<br/>',NULL,63226,6);
INSERT INTO stanza VALUES('I585','7','P''ri tanam disiram,<br/>harum semerbak,<br/>Untuk Kau nikmati,<br/>puaskan hati-Mu.<br/>',NULL,63227,7);
INSERT INTO stanza VALUES('I586','1','Lapar pun haus roh dan hatiku,<br/>Tuhan, ku datang mohon suplai-Mu,<br/>Diri-Mu itulah yang ku perlu,<br/>Yang menjadi hayat dan kuatku.<br/>',NULL,63228,1);
INSERT INTO stanza VALUES('I586','chorus','Tuhan, beriku makan minum!<br/>Lapar hausku, lerai pupus!<br/>Riang segar, ku menempuh hidup,<br/>Tuhan, beriku makan minum.<br/>',NULL,63229,2);
INSERT INTO stanza VALUES('I586','2','Dikau makanan dan air hayatku,<br/>Yang kuatkan dan bangunkan rohku.<br/>Ku rindu makan minum diri-Mu,<br/>Demi baca doa nikmati-Mu.<br/>',NULL,63230,3);
INSERT INTO stanza VALUES('I586','3','Kau-lah Firman, penuh limpah Allah,<br/>Kau pun Roh itu, jadi hayatku.<br/>Dalam Firman, Kau-lah makananku,<br/>Dalam Roh itu, Kau minumanku.<br/>',NULL,63231,4);
INSERT INTO stanza VALUES('I586','4','Turun dunia, Kau jadi makanan,<br/>Dipukul, alirkan air hayat.<br/>Jadi makanan Kau mengenyangkan,<br/>Jadi minuman Kau memuaskan.<br/>',NULL,63232,5);
INSERT INTO stanza VALUES('I586','5','Kini Kau-lah firman, Roh dan hayat,<br/>Di dalamnya ku dapat suplaian;<br/>Kini Kau pun Roh, diam dalam rohku,<br/>Hingga ku dapat minum diri-Mu.<br/>',NULL,63233,6);
INSERT INTO stanza VALUES('I586','6','Kini ku datang ke dalam firman,<br/>Menikmati, menyesap diri-Mu;<br/>Makan firman-Mu hingga tak lapar,<br/>Minum Roh-Mu hingga ku tak haus.<br/>',NULL,63234,7);
INSERT INTO stanza VALUES('I586','7','Moga doaku serta bacaku,<br/>Berupa makan minum diri-Mu.<br/>Doa baca, hingga Kau ku makan,<br/>Doa baca, hingga Kau ku minum.<br/>',NULL,63235,8);
INSERT INTO stanza VALUES('I586','8','Moga diri-Mu jadi jamuanku,<br/>Dengan hidangan Roh dan firman-Mu.<br/>Makan dan minum sepuas hatiku,<br/>Limpah ruah nikmati diri-Mu.<br/>',NULL,63236,9);
INSERT INTO stanza VALUES('I587','1','Kini ku datang ke takhta,<br/>t''rima rahmat dan kurnia-Mu,<br/>Jadi bantuan pada waktunya,<br/>roh hatiku terhibur.<br/>',NULL,63237,1);
INSERT INTO stanza VALUES('I587','2','Pandang wajah mulia-Mu,<br/>wajah-Mu t''rangi lubukku,<br/>Sorotkan terang penyembuh,<br/>basmi lemah dan kurangku.<br/>',NULL,63238,2);
INSERT INTO stanza VALUES('I587','3','Di sini terang-Mu pancar,<br/>''nyatakan keadaanku;<br/>Darah-Mu ''nyatakan daya,<br/>mencuci bersih dosaku.<br/>',NULL,63239,3);
INSERT INTO stanza VALUES('I587','4','Minyak-Mu juga urapi,<br/>aku dapatkan unsur-Mu;<br/>''Tiasa nikmati diri-Mu,<br/>menjamah maksud hati-Mu.<br/>',NULL,63240,4);
INSERT INTO stanza VALUES('I587','5','Baca firman di depan-Mu,<br/>nyala p''lita di ruang kudus;<br/>Perlu Roh-Mu bagai minyak,<br/>hingga firman-Mu bersinar.<br/>',NULL,63241,5);
INSERT INTO stanza VALUES('I587','6','Di sini doa pada-Mu,<br/>bagai imam bakar dupa,<br/>Kristus dalam Roh p''ri dupa,<br/>baur doa pada Allah.<br/>',NULL,63242,6);
INSERT INTO stanza VALUES('I587','7','Firman-Mu p''lita, makanan,<br/>menerangi, mengenyangkan;<br/>Makin baca makin makan,<br/>dapat wahyu dan suplaian.<br/>',NULL,63243,7);
INSERT INTO stanza VALUES('I587','8','Kristus dupa, pun air hidup,<br/>ku diperkenan dan bebas;<br/>Makin doa, makin minum,<br/>sebar wangi, ''ngalir sungai.<br/>',NULL,63244,8);
INSERT INTO stanza VALUES('I587','9','Baca kitab, terang, kenyang;<br/>doa ''bubung, dah''ga sirna,<br/>Baca doa, Tuhan masuk,<br/>doa baca, Tuhan ''ngalir.<br/>',NULL,63245,9);
INSERT INTO stanza VALUES('I587','10','Demikian s''kutu d''ngan-Mu,<br/>doa baca baur d''ngan-Mu;<br/>Kau jenuhi, Kau resapi,<br/>hingga Kau ''ngalir dariku.<br/>',NULL,63246,10);
INSERT INTO stanza VALUES('I588','1','Ku datang pada-Mu,<br/>dambakan diri-Mu!<br/>Makan, minum Kau selalu,<br/>nikmati diri-Mu.<br/>',NULL,63247,1);
INSERT INTO stanza VALUES('I588','2','Menatap wajah-Mu,<br/>hatiku pun rindu!<br/>Bersentuhan ku dengan-Mu,<br/>puaslah di rohku.<br/>',NULL,63248,2);
INSERT INTO stanza VALUES('I588','3','Wajah mulia-Mu,<br/>eloklah di kalbu!<br/>Rela tinggal di sini t''rus,<br/>memandang tak putus.<br/>',NULL,63249,3);
INSERT INTO stanza VALUES('I588','4','Di dalam munajat,<br/>Kau-lah kurniaku!<br/>Hati riang, roh pun limpah,<br/>damailah hatiku.<br/>',NULL,63250,4);
INSERT INTO stanza VALUES('I588','5','Masih harus tunggu,<br/>dan pula menuntut!<br/>Doa-baca t''rus-menerus,<br/>hingga resap jenuh!<br/>',NULL,63251,5);
INSERT INTO stanza VALUES('I589','1','Bukan demi roti saja,<br/>tapi demi firman Allah;<br/>Wajib terima firman-Nya<br/>sebagai makanan hayat.<br/>',NULL,63252,1);
INSERT INTO stanza VALUES('I589','2','Bukan hanya tubuh saja,<br/>tapi tubuh, jiwa, dan roh;<br/>Roh berada paling dalam,<br/>guna t''rima suplai Allah.<br/>',NULL,63253,2);
INSERT INTO stanza VALUES('I589','3','Tubuh memang perlu gizi,<br/>yakni makanan materi;<br/>Roh pun perlu firman Allah,<br/>sebagai makanan hayat.<br/>',NULL,63254,3);
INSERT INTO stanza VALUES('I589','4','Tuhan, Sang Roh, demi firman,<br/>tegas ''nyatakan diri-Mu;<br/>Kini ku perlu pakai roh,<br/>demi firman t''rima Roh-Mu.<br/>',NULL,63255,4);
INSERT INTO stanza VALUES('I589','5','Kami men''rima firman-Mu,<br/>bukan baca huruf m''lulu;<br/>Tapi pikiran mengerti,<br/>pun pakai roh memahami.<br/>',NULL,63256,5);
INSERT INTO stanza VALUES('I589','6','Dalam roh makan firman-Mu,<br/>t''rima masuk dalam kalbu;<br/>Doa-bacakan firman-Mu,<br/>Kau menyuplai, resap s''luruh.<br/>',NULL,63257,6);
INSERT INTO stanza VALUES('I589','7','Firman hinggap di pikiran,<br/>itu beban memberatkan;<br/>Firman masuk dalam rohku,<br/>itu hayat, damai, teduh.<br/>',NULL,63258,7);
INSERT INTO stanza VALUES('I589','8','Tatkala ku memakai roh,<br/>t''rima firman, menjamah-Mu;<br/>Ku nikmati rawatan-Mu,<br/>menjamah Kau dalam kalbu.<br/>',NULL,63259,8);
INSERT INTO stanza VALUES('I589','9','Ajarku tiap baca firman,<br/>berlatih gunakan rohku;<br/>Sehingga rohku terawat,<br/>Kau-lah suplai hayat tentu.<br/>',NULL,63260,9);
INSERT INTO stanza VALUES('I590','1','Kristus itu firman dan Roh,<br/>Dia juga Roh dalam firman;<br/>Firman-Nya terhadap kita,<br/>adalah roh juga hayat.<br/>',NULL,63261,1);
INSERT INTO stanza VALUES('I590','2','Di luarku, Dia b''ri Alkitab;<br/>dalamku, Dia b''ri Roh Kudus;<br/>Hadiah besar dari Allah,<br/>t''rima Allah jadi suplai.<br/>',NULL,63262,2);
INSERT INTO stanza VALUES('I590','3','Roh Kudus singkap Alkitab,<br/>Roh Kudus pun realitasnya;<br/>Satu yang beraspek dua,<br/>tidak boleh dipisahkan.<br/>',NULL,63263,3);
INSERT INTO stanza VALUES('I590','4','Saat Roh t''rangi Alkitab,<br/>masuk rohku itu hayat;<br/>Jika pisah: Roh, Alkitab;<br/>seg''ra hampa, suplai tiada.<br/>',NULL,63264,4);
INSERT INTO stanza VALUES('I590','5','Pakai roh baca Alkitab,<br/>dia jadilah Roh dan hayat;<br/>Dari ku, Roh terutara,<br/>itu firman suplai orang.<br/>',NULL,63265,5);
INSERT INTO stanza VALUES('I590','6','Kita harus memakai roh,<br/>t''rima firman dalam kalbu;<br/>Harus pula salurkan Roh,<br/>Roh dan firman, esa padu.<br/>',NULL,63266,6);
INSERT INTO stanza VALUES('I590','7','Moga firman-Mu dalamku,<br/>menjadi Roh dan hayatku;<br/>Moga Roh dalam firman-Mu,<br/>jadi ekspresi s''jatiku.<br/>',NULL,63267,7);
INSERT INTO stanza VALUES('I591','1','Firman bukan pengeta''uan,<br/>m''lainkan suplaikan hayat;<br/>Menyingkapkan pikiran-Nya,<br/>agar Allah didapat.<br/>Mewahyukan maksud Allah,<br/>Tuhan hayat datanglah;<br/>Bukan sekadar ajaran,<br/>tapi suplaikan Tuhan.<br/>',NULL,63268,1);
INSERT INTO stanza VALUES('I591','2','Membaca huruf belaka,<br/>itu pengetahuan;<br/>Demi roh berdoa baca,<br/>itu hayat, realitas.<br/>Huruf dan pengetahuan,<br/>datangkan kematian;<br/>Dalam Roh men''rima firman -<br/>hayat dan menghidupkan.<br/>',NULL,63269,2);
INSERT INTO stanza VALUES('I591','3','Baca tanpa jamah Tuhan,<br/>itu paham nan hampa;<br/>Di dalam roh jamah Kristus,<br/>t''rima makanan hayat.<br/>Baca tanpa jamah Tuhan,<br/>otak s''mata mendapat;<br/>Doa baca jamah Kristus,<br/>t''rima hayat nan limpah.<br/>',NULL,63270,3);
INSERT INTO stanza VALUES('I591','4','Pengetahuan Alkitab,<br/>wajib menjurus hayat;<br/>Pengertian dalam otak,<br/>wajib di roh dicerna.<br/>Paham terhadap Alkitab,<br/>perlu aliran hayat;<br/>Pengenalan yang harfiah,<br/>perlu di roh dit''rima.<br/>',NULL,63271,4);
INSERT INTO stanza VALUES('I591','5','Menuntut pengetahuan,<br/>itu tindakan Hawa;<br/>Justru kena taktik setan,<br/>bujuk orang berdosa.<br/>T''rima hayat dari firman,<br/>itu makan buah hayat;<br/>Wajib t''rima firman Tuhan,<br/>s''bagai makanan hayat.<br/>',NULL,63272,5);
INSERT INTO stanza VALUES('I592','1','Kita nikmat kaya Kristus,<br/>pasti jadi kep''nuhan-Nya;<br/>Mengalami s''mua ada-Nya,<br/>pasti mengekspresikan Dia.<br/>',NULL,63273,1);
INSERT INTO stanza VALUES('I592','2','Limpah Kristus - hakiki-Nya,<br/>jadi s''gala nikmat kita;<br/>Kep''nuhan-Nya ialah g''reja,<br/>nikmat Kristus terjadinya.<br/>',NULL,63274,2);
INSERT INTO stanza VALUES('I592','3','Hasil Kanaan limpah ruah,<br/>lambang Kristus nan berlimpah;<br/>Terbangunlah Bait Allah,<br/>lambang gereja dari Dia.<br/>',NULL,63275,3);
INSERT INTO stanza VALUES('I592','4','Kepenuhan Adam - Hawa,<br/>lambang g''reja t''radap Kristus;<br/>Dari Adam asal Hawa,<br/>dari Kristus asal g''reja.<br/>',NULL,63276,4);
INSERT INTO stanza VALUES('I592','5','Kristus k''limpahan di dalam,<br/>g''reja kep''nuhan di luar;<br/>Penuh Kristus, tampilkan Dia,<br/>d''ngan Kristus sama mustika.<br/>',NULL,63277,5);
INSERT INTO stanza VALUES('I593','1','Allah itu Yang tak nampak,<br/>tidak terlihat wujud-Nya,<br/>Namun Kristus, rah''sia Allah,<br/>menyatakan diri Allah.<br/>',NULL,63278,1);
INSERT INTO stanza VALUES('I593','2','Kristus-lah firman hidup-Nya,<br/>pernyataan unik Allah,<br/>Kristus-lah perwujudan-Nya,<br/>terlihat hakiki Allah.<br/>',NULL,63279,2);
INSERT INTO stanza VALUES('I593','3','Kristus gambar wujud Allah,<br/>terang dari mulia Allah,<br/>Limpah Allah di dalam-Nya,<br/>pancarkan hakiki Allah.<br/>',NULL,63280,3);
INSERT INTO stanza VALUES('I593','4','Kristus kini tersembunyi,<br/>tidak tertampak di bumi,<br/>Namun g''reja rah''sia Kristus,<br/>''nyatakan di depan orang.<br/>',NULL,63281,4);
INSERT INTO stanza VALUES('I593','5','Gereja keluapan-Nya,<br/>Dia isi dan hayat g''reja,<br/>G''reja itu duplikat-Nya,<br/>lewat g''reja ''nyatakan Dia.<br/>',NULL,63282,5);
INSERT INTO stanza VALUES('I593','6','G''reja gambar konkret Kristus,<br/>pertambahan, kes''mestaan,<br/>Hakiki-Nya dalam g''reja,<br/>gereja itu Tubuh-Nya.<br/>',NULL,63283,6);
INSERT INTO stanza VALUES('I593','7','Bapa ada dalam Putra,<br/>Putra di dalam Roh Kudus,<br/>Kini Dia Roh Tritunggal,<br/>dalam g''reja, esa d''ngannya.<br/>',NULL,63284,7);
INSERT INTO stanza VALUES('I594','1','Tubuh kepenuhan orang,<br/>pamer hayatnya,<br/>Demikian, d''ngan Tubuh-Nya,<br/>nyatakan Dia.<br/>',NULL,63285,1);
INSERT INTO stanza VALUES('I594','2','Hawa itu bagian Adam,<br/>Adam sumbernya,<br/>G''reja pertambahan Kristus,<br/>dari rusuk-Nya.<br/>',NULL,63286,2);
INSERT INTO stanza VALUES('I594','3','Biji gandum jatuh mati,<br/>berbuah banyak,<br/>Digiling menjadi tepung,<br/>baur jadi Tubuh.<br/>',NULL,63287,3);
INSERT INTO stanza VALUES('I594','4','Kristus itu mati, bangkit,<br/>berkembang biak,<br/>Kaum beriman satu Tubuh,<br/>''nyatakan Dia.<br/>',NULL,63288,4);
INSERT INTO stanza VALUES('I594','5','Ranting-ranting pohon zaitun,<br/>perluasan pohon,<br/>Esa, tinggal dalam pohon,<br/>berbuah limpah.<br/>',NULL,63289,5);
INSERT INTO stanza VALUES('I594','6','Demikian anggota Tubuh,<br/>perbesaran-Nya,<br/>Esa dan hidup dalam-Nya,<br/>Dia diperbesar.<br/>',NULL,63290,6);
INSERT INTO stanza VALUES('I594','7','Berkembang biak, pertambahan,<br/>kesemestaan,<br/>Salinan, lanjutan, kaya,<br/>kepenuhan-Nya.<br/>',NULL,63291,7);
INSERT INTO stanza VALUES('I594','8','''Nilah Kristus, sumber g''reja,<br/>muliakan Allah,<br/>Lewat kaum tebusan-Nya,<br/>kekal bersinar.<br/>',NULL,63292,8);
INSERT INTO stanza VALUES('I594','9','Itulah Kristus dan g''reja,<br/>rahasia Allah,<br/>Sifat ilahi, insani,<br/>berbaur esa.<br/>',NULL,63293,9);
INSERT INTO stanza VALUES('I595','1','G''reja itu wadah Kristus,<br/>diisi Dia, tampilkan Dia,<br/>Sep''ri tubuh daging kita,<br/>menyatakan diri kita.<br/>',NULL,63294,1);
INSERT INTO stanza VALUES('I595','2','Sep''ri bait juga tabut,<br/>wadah, tempat perhentian,<br/>G''reja tempat tinggal Kristus,<br/>tempat tinggal berisi Dia.<br/>',NULL,63295,2);
INSERT INTO stanza VALUES('I595','3','Kristus itu rah''sia Allah,<br/>jelaskan Dia, ''nyatakan Dia,<br/>G''reja itu rah''sia Kristus,<br/>jelaskan Dia, tampilkan Dia.<br/>',NULL,63296,3);
INSERT INTO stanza VALUES('I595','4','Kristus, g''reja, g''nap anggota,<br/>s''mua berasal dari tanah,<br/>Lahir ulang dan diubah,<br/>bening cerah p''ri mustika.<br/>',NULL,63297,4);
INSERT INTO stanza VALUES('I595','5','Lewat ubah, terbangunlah,<br/>jadi wadah Kristus mulia,<br/>Diisi kelimpahan-Nya,<br/>dinyatakan orang banyak.<br/>',NULL,63298,5);
INSERT INTO stanza VALUES('I595','6','Sang Tritunggal kerja sama,<br/>merampungkan pengubahan,<br/>Gereja wadah korporat,<br/>p''ri kota kudus hunian-Nya.<br/>',NULL,63299,6);
INSERT INTO stanza VALUES('I595','7','Sungguh mustika p''ri g''reja,<br/>tiap aspek bening, terang,<br/>Tampung Kristus, limpah Allah,<br/>pancar Kristus, mulia Allah.<br/>',NULL,63300,7);
INSERT INTO stanza VALUES('I595','8','Allah terang, Tuhan hayat,<br/>Roh menjadi arus hayat,<br/>Tritunggal diekspresikan,<br/>kekal ''nyatakan segala.<br/>',NULL,63301,8);
INSERT INTO stanza VALUES('I596','1','G''reja kaki dian emas,<br/>Kristus dian, Allah Terang;<br/>T''rang ilahi dari Tuhan,<br/>gereja topang mulia-Nya.<br/>',NULL,63302,1);
INSERT INTO stanza VALUES('I596','2','Dian pancar t''rang ilahi,<br/>Allah Sang Hayat memancar;<br/>Kar''na itu dian emas,<br/>padu dengan terang Allah.<br/>',NULL,63303,2);
INSERT INTO stanza VALUES('I596','3','Dalam zaman gelap ini,<br/>terang hayat Allah pancar;<br/>T''rangi hati banyak orang,<br/>siar kesaksian Tuhan.<br/>',NULL,63304,3);
INSERT INTO stanza VALUES('I596','4','Mau jadi saksi murni,<br/>pelihara "kasih s''mula";<br/>Ini bagian pemenang,<br/>menikmati "pohon hayat".<br/>',NULL,63305,4);
INSERT INTO stanza VALUES('I596','5','T''rima d''rita, aniaya,<br/>baru t''rima "pah''la hayat";<br/>Singkirkan zina rohani,<br/>dapat "manna tersembunyi".<br/>',NULL,63306,5);
INSERT INTO stanza VALUES('I596','6','Tolak ajaran "Izebel",<br/>baru dapat memerintah;<br/>Kalahkan noda kematian,<br/>kenakan "pakaian putih".<br/>',NULL,63307,6);
INSERT INTO stanza VALUES('I596','7','Harus p''ri "Filadelfia",<br/>pegang firman dan nama-Nya;<br/>"Suam kuku" dikalahkan,<br/>pesta, nikmati limpah-Nya.<br/>',NULL,63308,7);
INSERT INTO stanza VALUES('I596','8','Gereja haruslah suci,<br/>jadi kaki dian emas;<br/>S''laras kesaksian murni-Nya,<br/>pancarkan Dia, penuh mulia.<br/>',NULL,63309,8);
INSERT INTO stanza VALUES('I596','9','Gereja di tiap lokal,<br/>zaman ini s''bagai dian;<br/>Kelak Yerusalem Baru,<br/>s''bagai dian selamanya.<br/>',NULL,63310,9);
INSERT INTO stanza VALUES('I596','10','Kota kudus nan mustika,<br/>dian Tuhan nan terakhir;<br/>Topang Kristus s''bagai dian,<br/>terang ilahi cemerlang.<br/>',NULL,63311,10);
INSERT INTO stanza VALUES('I597','1','Allah berkenan, memilih,<br/>sebelum dunia jadi,<br/>Agar g''reja dalam Putra,<br/>dapat hak keputraan;<br/>Ditebus, jadi warisan,<br/>dimeterai Roh Kudus,<br/>Dijamin dapat warisan,<br/>menikmati diri-Nya.<br/>',NULL,63312,1);
INSERT INTO stanza VALUES('I597','2','Duduk sisi kanan Allah,<br/>lampau segala kuasa,<br/>Jadi Kepala segala,<br/>gereja Tubuh Kristus;<br/>Memenuhi segalanya,<br/>gereja kep''nuhan-Nya,<br/>Sebar luas lewat gereja,<br/>mutlak ekspresikan Dia.<br/>',NULL,63313,2);
INSERT INTO stanza VALUES('I597','3','Dulu mati dalam dosa,<br/>ikut tradisi dunia,<br/>Patuhi setan, roh jahat,<br/>nafsu daging terumbar;<br/>Kini bangkit dengan Kristus,<br/>sama duduk di surga,<br/>Jadi karya agung mulia,<br/>ciptaan unik Kristus.<br/>',NULL,63314,3);
INSERT INTO stanza VALUES('I597','4','Dia jadi batu penjuru;<br/>rasul, nabi - pondasi,<br/>Wahyukan rahasia Allah,<br/>umat-Nya satu Tubuh;<br/>Sama terbangun dalam-Nya,<br/>jadi kediaman Allah,<br/>Saling baur di dalam Roh,<br/>Allah mapan berhuni.<br/>',NULL,63315,4);
INSERT INTO stanza VALUES('I597','5','Gereja rahasia Allah,<br/>rencana kekal Allah,<br/>Ekspresikan hikmat Allah,<br/>Kristus tenang semayam;<br/>Kaum saleh pahami Kristus,<br/>kecap Kristus tak tara,<br/>Kasih-Nya di luar dugaan,<br/>penuhlah limpah Allah.<br/>',NULL,63316,5);
INSERT INTO stanza VALUES('I597','6','Satu Tubuh, Roh, harapan,<br/>Tuhan, iman, baptisan,<br/>Allah Bapa semua orang,<br/>g''reja pun wajib esa;<br/>Mengenal Kristus, bertumbuh,<br/>''capai perawakan-Nya,<br/>Tak lagi diombang-ambing,<br/>rupa angin ajaran.<br/>',NULL,63317,6);
INSERT INTO stanza VALUES('I597','7','Kristus berikan karunia,<br/>untuk bangun Tubuh-Nya,<br/>G''napkan fungsi kaum saleh,<br/>membangun dalam kasih;<br/>Lepaskan insan yang lama,<br/>kenakan insan baru,<br/>Roh pikiran dibarui,<br/>penuh d''ngan gambar Allah.<br/>',NULL,63318,7);
INSERT INTO stanza VALUES('I597','8','Kristus korban bagi g''reja,<br/>agar g''reja cemerlang,<br/>Kudus, tak bercacat cela,<br/>jadi jodoh mulia-Nya;<br/>Mengasihi, rawat, asuh,<br/>gerejalah Tubuh-Nya,<br/>Satu Tubuh dengan g''reja,<br/>rahasia yang besar.<br/>',NULL,63319,8);
INSERT INTO stanza VALUES('I597','9','Tubuh, insan baru, jodoh,<br/>juga tempat kediaman,<br/>Laskar berp''rang bagi Allah,<br/>musnahkan musuh Allah;<br/>Pakai s''ragam laskar Allah,<br/>sandar kuat kuasa Tuhan,<br/>Tegak tegap sandar Tuhan,<br/>setiap waktu berdoa.<br/>',NULL,63320,9);
INSERT INTO stanza VALUES('I598','1','Gereja Tubuh Tuhan,<br/>kediaman Allah;<br/>Himpunan kaum terpanggil,<br/>bauran Allah insan.<br/>Pili''an Allah pra cipta,<br/>tebusan salib-Nya;<br/>Mutunya milik surga,<br/>bukan milik dunia.<br/>',NULL,63321,1);
INSERT INTO stanza VALUES('I598','2','Insan ciptaan baru<br/>dari kebangkitan;<br/>Dibaptis di dalam Roh,<br/>dikuduskan firman.<br/>Hayatnya dari Kristus,<br/>Dia-lah Kepala;<br/>Sesifat dengan Kristus,<br/>lampaui segala.<br/>',NULL,63322,2);
INSERT INTO stanza VALUES('I598','3','Kristus s''laku pondasi<br/>telah dibubuhkan;<br/>Kudus seperti Kristus,<br/>itu ciri g''reja.<br/>Semua milik-Nya mesti<br/>''nempuh kematian;<br/>Dibangun dalam bangkit,<br/>''mas, perak, permata.<br/>',NULL,63323,3);
INSERT INTO stanza VALUES('I598','4','Satulah elemen-Nya:<br/>Allah, Tuhan, dan Roh,<br/>Tubuh, iman, baptisan,<br/>harapan pun satu.<br/>Sang Tritunggal berbaur,<br/>jadi satu Tubuh;<br/>Demi iman berpadu,<br/>''nantikan balik Hu.<br/>',NULL,63324,4);
INSERT INTO stanza VALUES('I598','5','Anggota masing-masing<br/>beda asal usul;<br/>Semua esa kini,<br/>silam ciri lampau.<br/>Yahudi atau kafir,<br/>martabat apa pun,<br/>Singkir semua kecuali,<br/>Kristus - Insan Baru.<br/>',NULL,63325,5);
INSERT INTO stanza VALUES('I598','6','Satu yang universal<br/>muncul di tiap lokal;<br/>Berprinsip otonomi<br/>atas unit lokal.<br/>Tanggung jawab tiap<br/>lokal terhadap Kepala;<br/>Sekutu universal,<br/>lenyap s''mua sekatan.<br/>',NULL,63326,6);
INSERT INTO stanza VALUES('I598','7','Muncul di tiap lokal,<br/>Yerusalem mini;<br/>Limpah Kristus dalamnya,<br/>ciri Kota suci.<br/>Kristus Dian, Allah T''rang,<br/>gereja kaki dian;<br/>Tampilkan wujud mulia,<br/>rampung Yerusalem.<br/>',NULL,63327,7);
INSERT INTO stanza VALUES('I599','1','Benih gereja, Kristus sendiri,<br/>butiran hayat, tabur di hati,<br/>Tumbuh p''ri gandum, hasilkan tepung,<br/>jadi makanan, Allah insan puas.<br/>',NULL,63328,1);
INSERT INTO stanza VALUES('I599','2','Iblis datang campurkan yang palsu,<br/>asli dan palsu menjadi samar,<br/>P''ri lalang hambat gandum bertumbuh,<br/>tak dapat puaskan Allah dan insan.<br/>',NULL,63329,2);
INSERT INTO stanza VALUES('I599','3','Hayat gereja s''perti sesawi,<br/>bertumbuh dari Kristus - sesawi,<br/>Sesaat saja tumbuh di bumi,<br/>jadi suplaian orang yang lapar.<br/>',NULL,63330,3);
INSERT INTO stanza VALUES('I599','4','Iblis datang mengubah sesawi,<br/>atas mutunya juga bentuknya,<br/>Bertumbuh menjadi pohon besar,<br/>b''ri tempat tinggal pada si jahat.<br/>',NULL,63331,4);
INSERT INTO stanza VALUES('I599','5','Iblis pakai "g''reja" b''rubah mutu,<br/>bawa masuk adat kafir jahat,<br/>P''ri ragi mengkhamirkan adonan,<br/>rusak kekudusan dan tujuan-Nya.<br/>',NULL,63332,5);
INSERT INTO stanza VALUES('I599','6','Tuhan Sang Hayat, ubah kaum saleh,<br/>agar jadi mutiara permata;<br/>Jadi bahan membangun gereja,<br/>ada realitas kerajaan.<br/>',NULL,63333,6);
INSERT INTO stanza VALUES('I599','7','Sandar Tuhan hayat, g''reja tumbuh,<br/>baur dengan Kristus, serupa Dia;<br/>P''ri mutiara terpendam di tanah,<br/>sesuai bangunan, k''rajaan tiba.<br/>',NULL,63334,7);
INSERT INTO stanza VALUES('I599','8','Tuhan keluarkan ku dari "alang",<br/>tinggalkan "pohon besar" agama;<br/>Singkirkan dariku semua "ragi",<br/>p''ri makanan, suplai Allah, insan.<br/>',NULL,63335,8);
INSERT INTO stanza VALUES('I599','9','Agar kami tumbuh dalam hayat,<br/>diubah, dibangun jadi Tubuh;<br/>Jadi gereja, tampilkan Tuhan,<br/>agar dapat realitas k''rajaan.<br/>',NULL,63336,9);
INSERT INTO stanza VALUES('I600','1','Kaum saleh hidup bersatu, barulah g''reja esa,<br/>Roh Kudus ciptakan esa dalam diri kaum saleh.<br/>Kar''na berasal dari Roh, disebut kesatuan Roh,<br/>Diterima oleh iman bersama kaum saleh.<br/>',NULL,63337,1);
INSERT INTO stanza VALUES('I600','2','Iman mustika bersama diterima kaum saleh,<br/>Tersusun d''ngan diri Kristus dan karya penebusan.<br/>Di sini kaum saleh satu, sama iman, tak beda,<br/>Melalui iman ini, baru ada gereja.<br/>',NULL,63338,2);
INSERT INTO stanza VALUES('I600','3','G''reja universal satu, jadi warisan Kristus,<br/>Gereja lokal pun sama, menjadi wujud Tuhan.<br/>Elemen gereja satu, satu Allah, Tuhan, Roh,<br/>Iman, baptisan, dan Tubuh, pula satu harapan.<br/>',NULL,63339,3);
INSERT INTO stanza VALUES('I600','4','"Satu" ini tumpuan g''reja, pendirian bersama,<br/>Pendirian esa unik, diharapkan Roh Kudus.<br/>G''reja baru laksanakan, kesatuan sejati,<br/>Tampilnya di tiap lokal, terbangun oleh ini.<br/>',NULL,63340,4);
INSERT INTO stanza VALUES('I600','5','Tuhan bantu ku menjaga kesatuan Roh Kudus,<br/>Di atas tumpuan esa, alami hidup g''reja.<br/>Biar hasrat agung hati-Mu, dapat dilaksanakan,<br/>Dan rencana kekal Allah, tergenapkan sempurna.<br/>',NULL,63341,5);
INSERT INTO stanza VALUES('I601','1','Kristus Putra Allah dan tebusan-Nya,<br/>keselamatan kepercayaanku,<br/>Doktrin lain bukan kepercayaan,<br/>hanya pekerjaan dan persona-Nya.<br/>',NULL,63342,1);
INSERT INTO stanza VALUES('I601','2','Ajaran lain tak tepat dipakai,<br/>itu "angin pengajaran" perusak;<br/>Tiup kaum saleh lepas dari Kristus,<br/>tak membangun Tubuh, malah merusak.<br/>',NULL,63343,2);
INSERT INTO stanza VALUES('I601','3','Bersihkanlah semua macam ajaran,<br/>jaga iman, praktekkan keesaan.<br/>Dalam Kristus Roh itu, kita satu,<br/>jaga esa ini, yang lain buang.<br/>',NULL,63344,3);
INSERT INTO stanza VALUES('I601','4','Kita harus pegang Kristus sendiri,<br/>akan ditolong Tuhan lepas sekte,<br/>Dalam segala hal tumbuh ke Kristus,<br/>Tubuh terbangun jadi limpah Kristus.<br/>',NULL,63345,4);
INSERT INTO stanza VALUES('I601','5','Capai "kesatuan kepercayaan",<br/>buang semua "angin kepercayaan".<br/>Dalam roh pegang Kristus Sang Realitas,<br/>lewat keesaan, Tubuh bertumbuh.<br/>',NULL,63346,5);
INSERT INTO stanza VALUES('I602','1','Tuhan, Kau batu penjuru,<br/>dibuang orang Yahudi,<br/>Tapi Kau dipandang Allah,<br/>bangkit dari kematian.<br/>Kar''na Kau kami selamat,<br/>dan bersama terbangun,<br/>Yahudi dan orang kafir,<br/>jadi manusia baru.<br/>',NULL,63347,1);
INSERT INTO stanza VALUES('I602','2','Kau batu karang rohani,<br/>lerai dahaga insan,<br/>Menjadi sandaran insan,<br/>bahkan bangunan Allah.<br/>Kau-lah dasar yang di Sion,<br/>t''ruji, dilantik Allah,<br/>Batu sandaran gereja,<br/>dasar unik gereja.<br/>',NULL,63348,2);
INSERT INTO stanza VALUES('I602','3','G''reja terbangun atas-Mu,<br/>tumpas pintu alam maut,<br/>Meski badai t''rus menerpa,<br/>tetap berdiri teguh.<br/>G''reja punya kuasa-Mu,<br/>mengikat yang Kau ikat,<br/>Datangkan K''rajaan Surga<br/>melepas yang Kau lepas.<br/>',NULL,63349,3);
INSERT INTO stanza VALUES('I602','4','Tuhan batu hayat hidup,<br/>Allah pilih, hargai,<br/>Kita jadi batu hidup,<br/>sekarakter dengan-Mu.<br/>Jadi istana rohani,<br/>dapat Allah tinggali,<br/>Jadi imamat rohani,<br/>sembah kurban pada-Mu.<br/>',NULL,63350,4);
INSERT INTO stanza VALUES('I602','5','Tuhan, Engkau Tunas Daud,<br/>untuk bangun Bait Allah,<br/>Jabat tugas Raja, Imam,<br/>tunaikan amanat-Mu.<br/>Berkuasa bagi Allah,<br/>semua pastilah tunduk,<br/>Jadi imam depan Allah,<br/>semua terbawa masuk.<br/>',NULL,63351,5);
INSERT INTO stanza VALUES('I602','6','Kuasa dari takhta Allah,<br/>umat Allah sejaht''ra,<br/>Persekutuan sungai hayat,<br/>umat Allah tersuplai.<br/>Kuasa, persekutuan imbang,<br/>baru dapat membangun,<br/>Gabung tugas raja, imam,<br/>pembangunan terampung.<br/>',NULL,63352,6);
INSERT INTO stanza VALUES('I602','7','Kau, Allah berinkarnasi,<br/>Bait Allah nan mulia,<br/>Allah tinggal dalam insan,<br/>dalam-Mu terekspresi.<br/>G''reja bauran Allah insan,<br/>penuh d''ngan limpah Allah,<br/>Kami, setiap orang saleh,<br/>untuk bangun Bait Allah.<br/>',NULL,63353,7);
INSERT INTO stanza VALUES('I602','8','Kau-lah kediaman kekal,<br/>rumah abadi kami,<br/>Di dalam-Mu kami hidup,<br/>dapat lindungan kekal.<br/>Allah beserta manusia,<br/>Kau tempat kudus kami,<br/>Saling hidup dengan Allah,<br/>''tiasa sembah pada-Nya.<br/>',NULL,63354,8);
INSERT INTO stanza VALUES('I602','9','Batu dasar, batu atap,<br/>bait, g''reja, batu hidup,<br/>Tempat tinggal, tempat kudus,<br/>Engkaulah semuanya;<br/>Kami puji hakiki-Mu,<br/>puji keajaiban-Mu,<br/>Kami batu hidup ini,<br/>terbangun di dalam-Mu.<br/>',NULL,63355,9);
INSERT INTO stanza VALUES('I603','1','Ku memuji rencana-Mu,<br/>kami dibuat rumah-Mu,<br/>Kau semayam dan penuhi,<br/>dalam Putra Kau tertampil.<br/>',NULL,63356,1);
INSERT INTO stanza VALUES('I603','2','Kami ini ciptaan-Mu,<br/>segambar-Mu dan wakil-Mu,<br/>Wadah kasar dari tanah,<br/>roh di dalam, raga di luar.<br/>',NULL,63357,2);
INSERT INTO stanza VALUES('I603','3','T''rima Kau sebagai hayat,<br/>baru punya sifat emas,<br/>Kau dan kami baur padu,<br/>kami dan Kau satu Tubuh.<br/>',NULL,63358,3);
INSERT INTO stanza VALUES('I603','4','Hayat ''ngalir pun mendiris,<br/>segenap jiwa dan hati,<br/>Jadi mutiara, permata,<br/>secorak-Mu, semulia.<br/>',NULL,63359,4);
INSERT INTO stanza VALUES('I603','5','Kami paham ini semua,<br/>bukan diapresiasikan,<br/>Tapi untuk pembangunan,<br/>jadi rumah-Mu yang mulia.<br/>',NULL,63360,5);
INSERT INTO stanza VALUES('I603','6','Kini serahkan diriku,<br/>moga terulur tangan-Mu,<br/>Taklukkan dan susun aku,<br/>jadilah tempat teduh-Mu.<br/>',NULL,63361,6);
INSERT INTO stanza VALUES('I603','7','Hayat lahir, watak kerdil,<br/>gempur enyah sampai habis,<br/>Pupus sirna bangga diri,<br/>kaum saleh baur serasi.<br/>',NULL,63362,7);
INSERT INTO stanza VALUES('I603','8','Jadi sejoli dengan-Mu,<br/>nikmati Kau dan s''gala-Mu,<br/>Hidup sama, saling huni,<br/>Kau berkenan, puas hati.<br/>',NULL,63363,8);
INSERT INTO stanza VALUES('I604','1','Tuhan, Kau-lah Penjunan,<br/>Pembangun yang mulia,<br/>Tak hanya membentukku,<br/>terlebih membangunku.<br/>Ku bukan saja tanah,<br/>juga batu yang hidup;<br/>Ku jadi bejana-Mu,<br/>pun jadi istana-Mu.<br/>Ku jadi bejana-Mu,<br/>pun jadi istana-Mu.<br/>',NULL,63364,1);
INSERT INTO stanza VALUES('I604','2','Meski ku dari tanah,<br/>akan berubah sifat,<br/>Ada emas hayat-Mu,<br/>dan mutiara, permata.<br/>Terbangun jadi satu,<br/>jadi jodoh kasih-Mu,<br/>Satu tubuh dengan-Mu,<br/>memuaskan hati-Mu.<br/>Satu tubuh dengan-Mu,<br/>memuaskan hati-Mu.<br/>',NULL,63365,2);
INSERT INTO stanza VALUES('I604','3','Yang Engkau kehendaki,<br/>bukan bahan yang mahal.<br/>Tapi bahan terbangun,<br/>jadi tempat tinggal-Mu.<br/>Engkau Kristus almuhit,<br/>perlu g''reja terbangun.<br/>Untuk mengekspresikan<br/>limpah-Mu yang mulia.<br/>Untuk mengekspresikan<br/>limpah-Mu yang mulia.<br/>',NULL,63366,3);
INSERT INTO stanza VALUES('I604','4','Bukan rohani tunggal,<br/>mendapat pujian-Mu.<br/>Tapi hayat korporat,<br/>baru rampung hasrat-Mu.<br/>Anggota yang terpisah,<br/>tak dapat wujudkan-Mu.<br/>Tubuh yang koordinasi,<br/>jadi kepenuhan-Mu.<br/>Tubuh yang koordinasi,<br/>jadi kepenuhan-Mu.<br/>',NULL,63367,4);
INSERT INTO stanza VALUES('I604','5','Ku tak mau sendirian,<br/>Tuhan bangunkan aku.<br/>Menurut rencana-Mu,<br/>lekat erat d''ngan kuat.<br/>Tak megahkan rohani,<br/>tak sombongkan karunia.<br/>Semua untuk bangunan,<br/>untuk kemuliaan-Mu.<br/>Semua untuk bangunan,<br/>untuk kemuliaan-Mu.<br/>',NULL,63368,5);
INSERT INTO stanza VALUES('I605','1','Hembusilah aku,<br/>hingga rohku bangkit!<br/>Lepas sedih, kalahkan maut,<br/>masuk alam bangkit.<br/>',NULL,63369,1);
INSERT INTO stanza VALUES('I605','2','Hembusilah aku,<br/>hingga aku kuat!<br/>Kuat kerja, kuat jalan,<br/>kuat bagai elang.<br/>',NULL,63370,2);
INSERT INTO stanza VALUES('I605','3','Hembusilah aku,<br/>masuk perhentian!<br/>Roh bersandar, hati nyaman,<br/>kar''na-Mu ku girang.<br/>',NULL,63371,3);
INSERT INTO stanza VALUES('I605','4','Hembusilah aku,<br/>hingga p''nuh diri-Mu!<br/>Bukan aku, tapi Kristus,<br/>dalam tingkah laku.<br/>',NULL,63372,4);
INSERT INTO stanza VALUES('I605','5','Hembusilah aku,<br/>hidup dalam Tubuh!<br/>Terbangun dengan kaum saleh,<br/>tak lagi sendirian.<br/>',NULL,63373,5);
INSERT INTO stanza VALUES('I606','1','Lepaskanku dari ego,<br/>Tuhan, ku mau terbangun,<br/>Bersama jadi bait-Mu,<br/>dipenuhi mulia-Mu.<br/>Lepas dari sifat aneh,<br/>sombong, dan menyendiri,<br/>Rela taat kuasa-Mu,<br/>hingga Kau punya bait.<br/>',NULL,63374,1);
INSERT INTO stanza VALUES('I606','2','Air hayat suplai, ''ngalir,<br/>tumbuh, ubah, dewasa,<br/>Berfungsi sesuai urutan,<br/>genapkan orang lain.<br/>Tak lagi memandang tinggi,<br/>pengalaman dan visi,<br/>Kemampuan dan milikku,<br/>seimbang d''ngan yang lain.<br/>',NULL,63375,2);
INSERT INTO stanza VALUES('I606','3','Pegang Kristus, saling suplai,<br/>nikmati k''limpahan-Nya,<br/>Penuh dengan limpah Allah,<br/>Dia bertambah, ku matang.<br/>Kecap kasih agung Kristus,<br/>kenal panjang lebar-Nya,<br/>Tumbuh menjadi dewasa,<br/>capai perawakan-Nya.<br/>',NULL,63376,3);
INSERT INTO stanza VALUES('I606','4','Jadi tempat tinggal Allah,<br/>Tuhan, ku mau terbangun,<br/>Jadi bejana korporat,<br/>tampilkan mulia Tuhan.<br/>Kota kudus, mempelai-Nya,<br/>kini terekspresikan,<br/>Pancarkan sinar mulia-Nya,<br/>di tengah manusia.<br/>',NULL,63377,4);
INSERT INTO stanza VALUES('I607','1','Tuhan hembus dan berfirman!<br/>Lihat, bumi penuh tulang,<br/>Berserakan dalam kubur,<br/>Tuhan hembus, berfirman!<br/>',NULL,63378,1);
INSERT INTO stanza VALUES('I607','2','Tuhan hembus dan berfirman!<br/>Hembus bangun tulang kering,<br/>Keluar dari kubur maut,<br/>Tuhan hembus, berfirman!<br/>',NULL,63379,2);
INSERT INTO stanza VALUES('I607','3','Tuhan hembus dan berfirman!<br/>Biar umat-Mu hidup semua,<br/>Jadi tent''ra, serang musuh,<br/>Tuhan hembus, berfirman!<br/>',NULL,63380,3);
INSERT INTO stanza VALUES('I607','4','Tuhan hembus dan berfirman!<br/>Biar umat-Mu jadi satu,<br/>Kuasa, pimpinan, tak bentrok,<br/>Tuhan hembus, berfirman!<br/>',NULL,63381,4);
INSERT INTO stanza VALUES('I607','5','Tuhan hembus dan berfirman!<br/>Biar umat-Mu jadi Tubuh,<br/>Jadi tempat s''mayam Tuhan,<br/>Tuhan hembus, berfirman!<br/>',NULL,63382,5);
INSERT INTO stanza VALUES('I607','6','Tuhan hembus dan berfirman!<br/>Ku bangun, balik ke Tubuh,<br/>Tak terpencil, tidak picik,<br/>Tuhan hembus sekarang.<br/>',NULL,63383,6);
INSERT INTO stanza VALUES('I607','7','Tuhan hembus dan berfirman!<br/>Kaum saleh serang musuh,<br/>Rumah-Mu seg''ra terbangun,<br/>Tuhan hembus sekarang!<br/>',NULL,63384,7);
INSERT INTO stanza VALUES('I608','1','Tuhan, hembuskan nafas hayat,<br/>aku tulang berserakan,<br/>Perlu Kau hidupkan, pulihkan,<br/>biar ku hidup dalam Tubuh.<br/>',NULL,63385,1);
INSERT INTO stanza VALUES('I608','2','Tuhan, hembuskan nafas hayat,<br/>rohku sangat terbelenggu,<br/>Perlu Kau lepaskan b''lengguku,<br/>biar ku baur dalam roh Tubuh.<br/>',NULL,63386,2);
INSERT INTO stanza VALUES('I608','3','Tuhan, hembuskan nafas hayat,<br/>rohku lembam, gerak pelan,<br/>Perlu Kau bangunkan dan hibur,<br/>biar ku dapat suplai Tubuh.<br/>',NULL,63387,3);
INSERT INTO stanza VALUES('I608','4','Tuhan, hembuskan nafas hayat,<br/>rohku kosong, tiada puas,<br/>Perlu Kau kenyangkan, b''ri berkat,<br/>biar ku nikmat kaya Tubuh.<br/>',NULL,63388,4);
INSERT INTO stanza VALUES('I608','5','Tuhan, hembuskan nafas hayat,<br/>biar ku tidak berserakan,<br/>Faktor kematian Kau hancurkan,<br/>mutlak hidup dalam Tubuh.<br/>',NULL,63389,5);
INSERT INTO stanza VALUES('I609','1','Cetak biru dari Tuhan,<br/>tunjukkan kemah yang sungguh;<br/>Beritahu cara bangun,<br/>cara ''nyatakan mulia-Mu.<br/>',NULL,63390,1);
INSERT INTO stanza VALUES('I609','2','Tabut inti dari kemah,<br/>kemah tempat penampungnya;<br/>S''puluh p''rintah di dalamnya,<br/>selamanya dalam kemah.<br/>',NULL,63391,2);
INSERT INTO stanza VALUES('I609','3','Tabut lambang insan - Allah,<br/>s''perti kayu disalut mas;<br/>Hukum Taurat wujud Allah,<br/>tinggal dalam Kristus, Putra.<br/>',NULL,63392,3);
INSERT INTO stanza VALUES('I609','4','Kristus inti dari g''reja,<br/>yakni tempat semayam-Nya;<br/>Dalam Kristus ada Bapa,<br/>Kristus ada dalam g''reja.<br/>',NULL,63393,4);
INSERT INTO stanza VALUES('I609','5','Kemah perluasan tabut,<br/>dari kayu bersalut mas;<br/>G''reja perluasan Kristus,<br/>Allah baur dengan insan.<br/>',NULL,63394,5);
INSERT INTO stanza VALUES('I609','6','Papan-papan tunjang kemah,<br/>tegak atas dasar perak;<br/>Lapis emas, pakai gelang,<br/>saling kait, kukuh, kuat.<br/>',NULL,63395,6);
INSERT INTO stanza VALUES('I609','7','G''reja himpunan kaum saleh,<br/>atas dasar penebusan;<br/>Roh mengikat, dalam hayat,<br/>sama bangun, tegak, kuat.<br/>',NULL,63396,7);
INSERT INTO stanza VALUES('I609','8','Tutup kemah lapis empat,<br/>tiap tahap lambang Kristus;<br/>Menyatakan mulia Allah,<br/>menudungi tempat kudus.<br/>',NULL,63397,8);
INSERT INTO stanza VALUES('I609','9','Kristus mulia jadi tudung,<br/>kaum saleh jalin rapi;<br/>Nikmati semua ada-Nya,<br/>dan terbangun di dalam-Nya.<br/>',NULL,63398,9);
INSERT INTO stanza VALUES('I609','10','Hukum ada dalam tabut,<br/>tabut ada dalam kemah;<br/>Allah ada dalam Kristus,<br/>Kristus nyata dalam g''reja.<br/>',NULL,63399,10);
INSERT INTO stanza VALUES('I610','1','Leluasa roh hati ku ingini:<br/>Antar sesama roh baur esa,<br/>Menuntut bersama tanpa pamrih,<br/>lucut ego, terbangun selaras.<br/>',NULL,63400,1);
INSERT INTO stanza VALUES('I610','2','Leluasa roh hati ku ingini:<br/>Tak pula tertutup dan memencil,<br/>Lama pun jauh mengurung diri,<br/>tak lepas dari ego, tak bebas.<br/>',NULL,63401,2);
INSERT INTO stanza VALUES('I610','3','Leluasa roh hati ku gemari:<br/>Keluar mutlak dari egoku,<br/>Agar Roh Kudus jangan terjepit,<br/>limpah-Mu wujud atas hadir-Mu.<br/>',NULL,63402,3);
INSERT INTO stanza VALUES('I610','4','Leluasa roh hati ku dambakan!<br/>Enyah pencil diri, kering gersang,<br/>Menyendiri hanya sesak, papa,<br/>lepas diri kini, nikmat limpah.<br/>',NULL,63403,4);
INSERT INTO stanza VALUES('I610','5','Leluasa roh hati ku merindu!<br/>Bongkar kiat konyol si penipu,<br/>Enggan menyendiri di tempurung,<br/>dalam tak terbatasan ku terjun.<br/>',NULL,63404,5);
INSERT INTO stanza VALUES('I610','6','Leluasa roh hati ku mengharap:<br/>Bebas ku dari belenggu awak,<br/>Baur sesama, tangguh pun cerah,<br/>nikmat s''gala-Mu yang tak terbatas.<br/>',NULL,63405,6);
INSERT INTO stanza VALUES('I611','1','Ku damba bers''kutu dalam roh!<br/>Damba saling baur dalam roh,<br/>Damba terlepas dari ego,<br/>damba terbangun dalam roh.<br/>',NULL,63406,1);
INSERT INTO stanza VALUES('I611','2','Ku damba bers''kutu dalam roh!<br/>Terbuka kepada yang lain,<br/>Damba terlepas dari picik,<br/>damba menyembah dalam roh.<br/>',NULL,63407,2);
INSERT INTO stanza VALUES('I611','3','Ku damba bers''kutu dalam roh!<br/>Damba roh dapat tertampil,<br/>Damba terlepas ulah diri,<br/>damba kalahkan rintangan.<br/>',NULL,63408,3);
INSERT INTO stanza VALUES('I611','4','Ku damba bers''kutu dalam roh!<br/>Damba doa d''ngan kaum saleh,<br/>Damba lepas kemunafikan,<br/>damba sekutu sejati.<br/>',NULL,63409,4);
INSERT INTO stanza VALUES('I611','5','Ku damba bers''kutu dalam roh!<br/>Damba s''kutu imbang kuasa,<br/>Damba lepas beratkan kerja,<br/>damba s''kutu imbang kerja.<br/>',NULL,63410,5);
INSERT INTO stanza VALUES('I611','6','Tuhan genapkan hasrat ini,<br/>dorong kaum saleh bers''kutu,<br/>Hingga rencana-Mu tergenap,<br/>pembangunan-Mu pun rampung.<br/>',NULL,63411,6);
INSERT INTO stanza VALUES('I612','1','Berkat pula kehormatan,<br/>dipanggil jadi imam!<br/>Walau aku kecil, lemah,<br/>t''rima jabatan kudus.<br/>',NULL,63412,1);
INSERT INTO stanza VALUES('I612','chorus','Pembangunan Tubuh ini,<br/>tergantung pada imam,<br/>S''lalu doa di dalam roh,<br/>untuk tunaikan tugas.<br/>',NULL,63413,2);
INSERT INTO stanza VALUES('I612','2','Menjaga panggilan ini<br/>di bawah wewenang-Mu,<br/>Laksanakan tugas imam,<br/>gereja ''kan terbangun.<br/>',NULL,63414,3);
INSERT INTO stanza VALUES('I612','3','Gereja itu imamat,<br/>itu kita perlukan,<br/>Bila imam berjalinan,<br/>gereja terbangunkan.<br/>',NULL,63415,4);
INSERT INTO stanza VALUES('I612','4','Kar''na jatuh dan merosot,<br/>imamat terabaikan,<br/>Kar''na lemah di dalam roh,<br/>berkhotbah mendominan.<br/>',NULL,63416,5);
INSERT INTO stanza VALUES('I612','5','Banyak yang andalkan khotbah,<br/>tekankan pemb''ritaan,<br/>Anggap remeh doa imam,<br/>abaikan latihan roh.<br/>',NULL,63417,6);
INSERT INTO stanza VALUES('I612','6','Garap aku, atur aku,<br/>doa, khotbah, seimbang,<br/>Ajak orang sering doa,<br/>pula b''ritakan firman.<br/>',NULL,63418,7);
INSERT INTO stanza VALUES('I612','7','Dengan doa melayani,<br/>roh kita berbaur pasti,<br/>Doa, khotbah sama porsi,<br/>g''reja terbangun pasti.<br/>',NULL,63419,8);
INSERT INTO stanza VALUES('I613','1','Batu hidup gereja,<br/>ialah imam yang kudus,<br/>Bila mau terbangun,<br/>berdoa itu harus.<br/>',NULL,63420,1);
INSERT INTO stanza VALUES('I613','chorus','Masuk ruang mahakudus,<br/>dengan roh jamah takhta,<br/>Doa biar Allah tembus,<br/>baru bangunan ada.<br/>',NULL,63421,2);
INSERT INTO stanza VALUES('I613','2','Kaum saleh jadi imam,<br/>pun jadi batu hidup,<br/>Tunai tugas imamat,<br/>fungsi nyatalah tentu.<br/>',NULL,63422,3);
INSERT INTO stanza VALUES('I613','3','Dalam Perjanjian Lama,<br/>kemah - imam berpadu,<br/>Imam layan di kemah,<br/>keduanya jadi satu.<br/>',NULL,63423,4);
INSERT INTO stanza VALUES('I613','4','Dalam Perjanjian Baru,<br/>ada rumah rohani,<br/>Realitas rumah ini,<br/>imamat yang organik.<br/>',NULL,63424,5);
INSERT INTO stanza VALUES('I613','5','Hakiki pembangunan,<br/>ialah fungsi imamat,<br/>Imam tunai tugasnya,<br/>pembangunan tergenap.<br/>',NULL,63425,6);
INSERT INTO stanza VALUES('I613','6','Bawa insan ke Allah,<br/>itulah tugas imam,<br/>Dalam persekutuan,<br/>kaum saleh bangun esa.<br/>',NULL,63426,7);
INSERT INTO stanza VALUES('I613','7','Roh baur, doa sama,<br/>kita baru terbangun,<br/>Jadi susunan imam,<br/>sembah kurban pada-Nya.<br/>',NULL,63427,8);
INSERT INTO stanza VALUES('I613','8','Tuhan, beriku kurnia,<br/>tinggikan tugas imam!<br/>Doa, layan dalam roh,<br/>terbangunlah gereja.<br/>',NULL,63428,9);
INSERT INTO stanza VALUES('I614','1','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Kini mohon Tuhan ''ngalirkannya.<br/>Dobrak masa lalu, runtuh tembok besi.<br/>Roh ''ngalir d''ngan bebas, rohku ''ngalir.<br/>',NULL,63429,1);
INSERT INTO stanza VALUES('I614','2','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Kini mohon Tuhan ''ngalirkannya.<br/>Tidak puas diri, tidak bangga diri.<br/>Rohku tak terhalang, rohku ''ngalir.<br/>',NULL,63430,2);
INSERT INTO stanza VALUES('I614','3','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Kini minta Tuhan ''ngalirkannya.<br/>Tidak muluk-muluk, tidak rasa pandai.<br/>Roh ''ngalir tak henti, rohku ''ngalir.<br/>',NULL,63431,3);
INSERT INTO stanza VALUES('I614','4','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Kini cari Tuhan, ''ngalirkannya.<br/>Tidak bersembunyi, tidak menyendiri.<br/>Roh ''ngalir kian dalam, rohku ''ngalir.<br/>',NULL,63432,4);
INSERT INTO stanza VALUES('I614','5','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Kini minta Tuhan ''ngalirkannya.<br/>Tidak sandar diri, turun dari takhta.<br/>Sungai hayat luap, rohku ''ngalir.<br/>',NULL,63433,5);
INSERT INTO stanza VALUES('I614','6','Rohku ''ngalir, Tuhan, rohku ''ngalir.<br/>Dengar doaku, Tuhan, ''ngalirkannya.<br/>Moga ku terbangun, sekutu d''ngan Tuhan.<br/>Berbaur dengan orang, rohku ''ngalir.<br/>',NULL,63434,6);
INSERT INTO stanza VALUES('I615','1','Betapa indah rumah-Mu,<br/>ku rindu pelatarannya!<br/>Ku damba penyertaan-Mu,<br/>dari lubuk ku menyeru.<br/>',NULL,63435,1);
INSERT INTO stanza VALUES('I615','2','Pada mezbah-mezbah Allah,<br/>di sana pipit berteduh;<br/>Burung pipit dapat rumah,<br/>burung sriti dapat sarang.<br/>',NULL,63436,2);
INSERT INTO stanza VALUES('I615','3','Selemah pipit dan sriti,<br/>dapat berkat dalam bait-Mu!<br/>D''ngan nilai mezbah tebusan,<br/>nikmati mezbah ukupan.<br/>',NULL,63437,3);
INSERT INTO stanza VALUES('I615','4','Bersandar Kau jadi kuat,<br/>tak takut mara bahaya,<br/>Yang rindu jalan ke Sion,<br/>pasti menerima berkat!<br/>',NULL,63438,4);
INSERT INTO stanza VALUES('I615','5','Baka, lembah air mata,<br/>berubah jadi mata air;<br/>Hujan musim curah berkah,<br/>jadi berkat perjalanan.<br/>',NULL,63439,5);
INSERT INTO stanza VALUES('I615','6','Kuat tambah kuat pula,<br/>sampai Sion jumpa Allah;<br/>Demikian cari Tuhan,<br/>perlu Kau rawat, b''ri kurnia.<br/>',NULL,63440,6);
INSERT INTO stanza VALUES('I615','7','Tinggal sehari di bait-Mu,<br/>lebih baik dari yang lain;<br/>Rela jaga pintu bait,<br/>dari diam di rumah fasik.<br/>',NULL,63441,7);
INSERT INTO stanza VALUES('I615','8','Kau mentari, Kau perisai,<br/>Kau beri kurnia mulia;<br/>Diri dan penyertaan-Mu,<br/>puaskan keperluanku.<br/>',NULL,63442,8);
INSERT INTO stanza VALUES('I615','9','Kau tak menahan kebaikan,<br/>dari yang hidup tak cela,<br/>Berbah''gialah yang sandar-Mu,<br/>pasti dapat kasih, mulia.<br/>',NULL,63443,9);
INSERT INTO stanza VALUES('I616','1','Tuhan, ku cinta rumah-Mu,<br/>yakni gereja-Mu!<br/>Perkenan-Mu dan gemar-Mu,<br/>juga dambaanku.<br/>',NULL,63444,1);
INSERT INTO stanza VALUES('I616','2','Kau berkorban bagi g''reja,<br/>agar dia bagi-Mu;<br/>Ku pun sembahkan tubuhku,<br/>genapkan murad-Mu.<br/>',NULL,63445,2);
INSERT INTO stanza VALUES('I616','3','Dikau adalah hayatku,<br/>gereja hidupku;<br/>Ku rela lepas tabiatku,<br/>biar mapan s''mayam-Mu.<br/>',NULL,63446,3);
INSERT INTO stanza VALUES('I616','4','Dia pasangan kasih-Mu,<br/>dia pun Tubuh-Mu;<br/>Dia itu idamanku,<br/>pula andalanku.<br/>',NULL,63447,4);
INSERT INTO stanza VALUES('I616','5','Di dalamnya Kau nikmatku,<br/>jadi kesaksianku;<br/>Di dalamnya ku milik-Mu,<br/>puaskan hati-Mu.<br/>',NULL,63448,5);
INSERT INTO stanza VALUES('I616','6','Tuhan, ku cinta rumah-Mu,<br/>yakni gereja-Mu;<br/>Padanya ku tempuh hidup,<br/>yang lain ku tak mau.<br/>',NULL,63449,6);
INSERT INTO stanza VALUES('I617','1','Makhluk hidup dari Kristus,<br/>cenderung temu sejenis,<br/>Penyaliban diberlaku,<br/>Kristus korporat tertampil.<br/>',NULL,63450,1);
INSERT INTO stanza VALUES('I617','chorus','Bersekutu, koordinasi,<br/>amanat mulia,<br/>Setindakan dan sederap,<br/>wujud takhta Allah.<br/>',NULL,63451,2);
INSERT INTO stanza VALUES('I617','2','Hidup sandar kurnia-Nya,<br/>tak andal diri sendiri,<br/>Bangga bernaung pada-Nya,<br/>Tuhan Allah terekspresi.<br/>',NULL,63452,3);
INSERT INTO stanza VALUES('I617','3','Murni, polos, lurus, tepat,<br/>roh lembut dan rendah hati,<br/>Mana saja ikuti roh,<br/>bukan gemar, bukan ego.<br/>',NULL,63453,4);
INSERT INTO stanza VALUES('I617','4','Jalin kokoh, melekat pas,<br/>saling genap, saling tunjang,<br/>Beda fungsi, sama langkah,<br/>tercapai wahyu mulia-Nya.<br/>',NULL,63454,5);
INSERT INTO stanza VALUES('I617','5','Api kudus bakar marak,<br/>lebur nista dan campuran,<br/>Sorot api penyisihan,<br/>tingkah langkah bercahaya.<br/>',NULL,63455,6);
INSERT INTO stanza VALUES('I617','6','Roda Allah iring putar,<br/>cakrawala jernih cerah,<br/>Sini takhta-Nya berdaulat,<br/>sini citra-Nya terpancar.<br/>',NULL,63456,7);
INSERT INTO stanza VALUES('I618','1','Kaum saleh Kristus,<br/>anggota Tubuh,<br/>Berkoordinasi,<br/>dalam seutuh.<br/>',NULL,63457,1);
INSERT INTO stanza VALUES('I618','2','Banyaklah karunia,<br/>Roh tetap satu,<br/>Banyak ministrinya,<br/>satu Tuhan-nya.<br/>',NULL,63458,2);
INSERT INTO stanza VALUES('I618','3','Semua saling perlu,<br/>tak dibedakan,<br/>Berbagai posisi,<br/>berbagai fungsi.<br/>',NULL,63459,3);
INSERT INTO stanza VALUES('I618','4','Sesuai kasih kurnia,<br/>t''rima talenta,<br/>Kadar masing-masing,<br/>m''rendah tak congkak.<br/>',NULL,63460,4);
INSERT INTO stanza VALUES('I618','5','Tunai tugas diri,<br/>tampilkan fungsi,<br/>Tak ada yang kendur,<br/>mutlak setia.<br/>',NULL,63461,5);
INSERT INTO stanza VALUES('I618','6','Saling jalin suplai,<br/>saling toleran,<br/>Tidak ada cela,<br/>Dia yang utama.<br/>',NULL,63462,6);
INSERT INTO stanza VALUES('I618','7','Gereja Tubuh-Nya,<br/>Kristus Kepala,<br/>Roh minyak urapan,<br/>satukan kita.<br/>',NULL,63463,7);
INSERT INTO stanza VALUES('I619','1','Makhluk hidup ilahi,<br/>''nyatakan Kristus mulia;<br/>Terbangun jadi satu,<br/>rampung murad yang kudus;<br/>Ikuti Roh bergerak,<br/>Allah pasti bertindak.<br/>',NULL,63464,1);
INSERT INTO stanza VALUES('I619','chorus','Seiring makhluk hidup,<br/>roda Allah berputar,<br/>Dahsyat, bening pun anggun,<br/>nyata gambar mulia-Nya,<br/>Rampung rencana ilahi-Nya.<br/>',NULL,63465,2);
INSERT INTO stanza VALUES('I619','2','Api kudus membakar,<br/>buang najis sekular,<br/>Api kudus menyorot,<br/>terangi tiap sudut,<br/>Bertindak dalam terang,<br/>gerakan Allah maju.<br/>',NULL,63466,3);
INSERT INTO stanza VALUES('I619','3','Turut Roh dalam terang,<br/>langit sebening kristal;<br/>Nurani bebas cela,<br/>bunyikan kesaksian;<br/>Bersuara dan mendengar,<br/>gerakan Allah ''luasa.<br/>',NULL,63467,4);
INSERT INTO stanza VALUES('I619','4','Demikian ada rumah,<br/>dan juga takhta Allah;<br/>Berkembang kuasa-Nya,<br/>terlihat mulia-Nya;<br/>Tuhan berupa insan,<br/>sama t''rang kota kudus.<br/>',NULL,63468,5);
INSERT INTO stanza VALUES('I620','1','Awan Roh Kudus, api pengudus,<br/>emas kilau sifat Allah;<br/>Makhluk ciptaan dapatkan hayat,<br/>Allah tampil dalam insan.<br/>',NULL,63469,1);
INSERT INTO stanza VALUES('I620','2','Hidup p''ri insan, gagah p''ri singa,<br/>jerih lembu, unggul elang;<br/>Demikianlah citra Sang Kristus,<br/>tiap aspek tampil mulia-Nya.<br/>',NULL,63470,2);
INSERT INTO stanza VALUES('I620','3','Langkah-Nya tegap, gerak-Nya kudus,<br/>segar, lincah, bening, cerah;<br/>Ditempa juga diolah Allah,<br/>jadi terang, hakim insan.<br/>',NULL,63471,3);
INSERT INTO stanza VALUES('I620','4','Bersandar Allah, bubung ke atas,<br/>bekerja tetap insani;<br/>Bernaung Allah, bermegah Tuhan,<br/>papar Dia, bukan diri.<br/>',NULL,63472,4);
INSERT INTO stanza VALUES('I620','5','Sandar kurnia, saling koordinasi,<br/>tunai tugas, sikap tegas;<br/>Bakar p''ri bara, sorot p''ri obor,<br/>tindak langkah terang kilau.<br/>',NULL,63473,5);
INSERT INTO stanza VALUES('I620','6','Iringi Dia, menuruti Roh,<br/>gaya dahsyat, mata jeli;<br/>Aktif beraksi, pantul wajah-Nya,<br/>gerak serasi dalam Roh.<br/>',NULL,63474,6);
INSERT INTO stanza VALUES('I620','7','Langit transparan, nurani murni,<br/>bersuara pun mendengar;<br/>Bersuara oleh koordinasi,<br/>p''ri laskar menggempur lawan.<br/>',NULL,63475,7);
INSERT INTO stanza VALUES('I620','8','Takhta di surga, coraknya surga,<br/>wujud Tuhan bentuk insan;<br/>Kemilau emas, kudus membara,<br/>sepelangi kota kudus.<br/>',NULL,63476,8);
INSERT INTO stanza VALUES('I621','1','Ikatan d''ngan kasih,<br/>padukan kaum saleh,<br/>Saling sekutu sehati,<br/>seperti di surga.<br/>',NULL,63477,1);
INSERT INTO stanza VALUES('I621','2','Depan takhta Bapa,<br/>sehati berdoa,<br/>Sama harap, sama d''rita,<br/>pun kuatir, dan lega.<br/>',NULL,63478,2);
INSERT INTO stanza VALUES('I621','3','Lemah saling tunjang,<br/>beban saling pikul,<br/>Satu sedih, s''mua menangis,<br/>penuh d''ngan simpati.<br/>',NULL,63479,3);
INSERT INTO stanza VALUES('I621','4','Bila kita pisah,<br/>dalam batin susah,<br/>Dalam roh tetaplah esa,<br/>kelak jumpa pula.<br/>',NULL,63480,4);
INSERT INTO stanza VALUES('I621','5','Pada hari itu,<br/>takkan pisah pula,<br/>Saling kasih, saling s''kutu,<br/>gembira s''lamanya.<br/>',NULL,63481,5);
INSERT INTO stanza VALUES('I622','1','Hidup dengan rukun, amat mesra;<br/>Minyak di kepala turun jubah;<br/>Embun dari Hermon turun Sion;<br/>Di sinilah berkat hayat kekal.<br/>',NULL,63482,1);
INSERT INTO stanza VALUES('I622','2','Pesta dengan tulus, sukacita;<br/>Kecap kurnia Tuhan, penuh pujian!<br/>Saling bersekutu, sangat indah;<br/>Hari itu tiba, tak berpisah!<br/>',NULL,63483,2);
INSERT INTO stanza VALUES('I623','1','Harum surga kami hisap,<br/>segar, nyaman, sedap;<br/>Hingga jiwa lepas daging,<br/>roh dip''nuhi kasih.<br/>',NULL,63484,1);
INSERT INTO stanza VALUES('I623','2','Moga kami saling cinta,<br/>penuh rasa kudus;<br/>S''lamanya takkan berubah,<br/>cinta Tuhan s''lalu.<br/>',NULL,63485,2);
INSERT INTO stanza VALUES('I623','3','Cinta ''kan pimpinan salib,<br/>patuh kehendak-Mu;<br/>Saling cinta kian berlebih,<br/>kian dekat pada-Mu.<br/>',NULL,63486,3);
INSERT INTO stanza VALUES('I624','1','Setiap sidang bawa Kristus,<br/>dan semua kelimpahan-Nya,<br/>Persembahkan pada Allah,<br/>kita pamer Kristus.<br/>',NULL,63487,1);
INSERT INTO stanza VALUES('I624','chorus','Mari pamer Kristus!<br/>Mari pamer Kristus!<br/>Semua membawa limpah-Nya,<br/>kita pamer Kristus!<br/>',NULL,63488,2);
INSERT INTO stanza VALUES('I624','2','Hidup, perang, sandar Kristus,<br/>siang, malam, garap Kristus,<br/>Dengan limpah-Nya berpadu,<br/>untuk pamer Kristus!<br/>',NULL,63489,3);
INSERT INTO stanza VALUES('I624','3','Hidup dan adanya kita,<br/>Kristus jadi realitas,<br/>Hingga tiap kita sidang,<br/>dapat pamer Kristus!<br/>',NULL,63490,4);
INSERT INTO stanza VALUES('I624','4','Dalam sidang bawa Kristus,<br/>saling nikmati limpah-Nya,<br/>Allah pun nikmati Kristus,<br/>kita pamer Kristus!<br/>',NULL,63491,5);
INSERT INTO stanza VALUES('I624','5','Bawalah Kristus yang bangkit,<br/>sembahkan Kristus yang t''rangkat,<br/>Puaskan tuntutan Allah,<br/>kita pamer Kristus!<br/>',NULL,63492,6);
INSERT INTO stanza VALUES('I624','6','Inti dan realitas sidang,<br/>suasana, pelayanan,<br/>Semuanya bertujuan,<br/>kita pamer Kristus!<br/>',NULL,63493,7);
INSERT INTO stanza VALUES('I624','7','Semua kesaksian, doa,<br/>persekutuan dalam roh,<br/>Daya guna dan ajaran,<br/>harus pamer Kristus!<br/>',NULL,63494,8);
INSERT INTO stanza VALUES('I624','8','Agar Bapa dimuliakan,<br/>agar Kristus diagungkan,<br/>Pun agar sidang berlimpah,<br/>harus pamer Kristus!<br/>',NULL,63495,9);
INSERT INTO stanza VALUES('I625','1','Tuhan, kini kami datang,<br/>mohon kurnia yang mendalam,<br/>Biar hayat-Mu tumbuh pesat, dan kesaksianku kian indah;<br/>Tuhan, inilah ku minta,<br/>moga Tuhan yang genapkan.<br/>',NULL,63496,1);
INSERT INTO stanza VALUES('I625','2','Banyak orang kering k''rontang,<br/>dan berjalan dalam kelam;<br/>Moga Tuhan yang menyiram dan<br/>b''ri kurnia sinar terang,<br/>Biar mereka semua siuman,<br/>bangun, cinta pada Tuhan.<br/>',NULL,63497,2);
INSERT INTO stanza VALUES('I625','3','Tuhan, kuatkan di dalamku,<br/>lepaskan ikatan luarku;<br/>Agar rohku bertambah kuat,<br/>batin lepas dari ego;<br/>Hayat-Mu dalamku wujud,<br/>kehendak-Mu ''kan tersalur.<br/>',NULL,63498,3);
INSERT INTO stanza VALUES('I625','4','Tuhan, aku mohon lagi,<br/>kuasa Pentakosta suci,<br/>Agar m''reka g''lisah hati,<br/>balik cari kurnia s''jati;<br/>Sakit - sembuh, buta - celik,<br/>yang terikat - bebas pasti.<br/>',NULL,63499,4);
INSERT INTO stanza VALUES('I626','1','Dalam roh dan realitas,<br/>kami menyembah-Mu;<br/>Sesuai yang Kristus ucapkan,<br/>kami hampiri-Mu.<br/>',NULL,63500,1);
INSERT INTO stanza VALUES('I626','2','Syukur ya Allah, Dikau Roh,<br/>dekat pula mesra;<br/>Ku menjamah dan menyembah,<br/>d''ngan roh dan realitas.<br/>',NULL,63501,2);
INSERT INTO stanza VALUES('I626','3','Kau ciptakan roh untukku,<br/>menjadi hayatku;<br/>Bukan bergumul di luar,<br/>asal paling ke roh.<br/>',NULL,63502,3);
INSERT INTO stanza VALUES('I626','4','Tuhan lahir ulang rohku,<br/>menjadi hayatku.;<br/>Perbarui pikiranku,<br/>hingga ku m''layani.<br/>',NULL,63503,4);
INSERT INTO stanza VALUES('I626','5','Sesuai perasaan batin,<br/>kami menyembah-Mu;<br/>Oleh peran urapan Roh,<br/>tampilkan diri-Mu.<br/>',NULL,63504,5);
INSERT INTO stanza VALUES('I626','6','Dengan keb''naran menyembah,<br/>bukan d''ngan bayangan;<br/>Dalam Kristus Sang Realitas,<br/>menyembah, memuji.<br/>',NULL,63505,6);
INSERT INTO stanza VALUES('I626','7','Kami persembahkan Kristus,<br/>yang kami alami;<br/>Bersama Allah nikmati<br/>manis dan indah-Nya.<br/>',NULL,63506,7);
INSERT INTO stanza VALUES('I626','8','Di sini kami bersidang,<br/>d''ngan roh dan realitas;<br/>Kitari takhta kurnia,<br/>menyembah, memuji.<br/>',NULL,63507,8);
INSERT INTO stanza VALUES('I627','1','Hidup pribadi atau bersidang,<br/>Kristus-lah inti, Kristus-lah isi;<br/>Bukan teori, bukan liturgi,<br/>m''lulu untuk Kristus sidang kami.<br/>',NULL,63508,1);
INSERT INTO stanza VALUES('I627','2','Kristus-lah jalan, Kristus-lah terang,<br/>bertindak dalam Dia dan terang-Nya,<br/>Kristus-lah roti dan air hayat,<br/>makan minum Dia terpelihara.<br/>',NULL,63509,2);
INSERT INTO stanza VALUES('I627','3','Kristus Sang Benar, kita saksikan,<br/>Kristus Sang Hayat, kita suplaikan,<br/>Kristus Sang Kurnia, kita agungkan,<br/>Kristus Kepala, kita tinggikan.<br/>',NULL,63510,3);
INSERT INTO stanza VALUES('I627','4','Terhadap Allah atau manusia,<br/>Kristus-lah semua, Kristus segala;<br/>Dia realitas dan isi g''reja,<br/>hayat dan jumlah tumbuh oleh-Nya.<br/>',NULL,63511,4);
INSERT INTO stanza VALUES('I627','5','Kidung dan doa yang dipanjatkan,<br/>oleh roh, Kristus terekspresikan,<br/>Persekutuan dan pelayanan,<br/>wajib nampakkan Kristus berperan.<br/>',NULL,63512,5);
INSERT INTO stanza VALUES('I627','6','Demi nama-Nya bersidang ini,<br/>oleh urapan doa dan puji;<br/>Bukan otak atau tata cara,<br/>tapi lewat roh Dia tertampilkan.<br/>',NULL,63513,6);
INSERT INTO stanza VALUES('I627','7','Bagilah Kristus setia kita,<br/>terapkan Dia hingga dewasa;<br/>nggap s''mua rugi karena Dia,<br/>biarlah kini Dia jadi s''galanya.<br/>',NULL,63514,7);
INSERT INTO stanza VALUES('I628','1','Roh perlu dilatih,<br/>angan ditolak;<br/>Setiap bersidang,<br/>ini kuncinya.<br/>',NULL,63515,1);
INSERT INTO stanza VALUES('I628','2','Roh perlu dilatih,<br/>buang liturgi;<br/>Saling bersekutu,<br/>nikmati Kristus.<br/>',NULL,63516,2);
INSERT INTO stanza VALUES('I628','3','Roh perlu dilatih,<br/>buang emosi;<br/>Saling melayani,<br/>Kristus realitas.<br/>',NULL,63517,3);
INSERT INTO stanza VALUES('I628','4','Roh perlu dilatih,<br/>buang jiwani;<br/>Bersandarkan Tuhan,<br/>saling berkaitan.<br/>',NULL,63518,4);
INSERT INTO stanza VALUES('I628','5','Roh bebas leluasa,<br/>tak benar diri;<br/>Tidak tuduh diri,<br/>tak p''duli diri.<br/>',NULL,63519,5);
INSERT INTO stanza VALUES('I628','6','Roh bebas leluasa,<br/>tak bangga diri;<br/>Tidak mulia diri,<br/>tak cinta diri.<br/>',NULL,63520,6);
INSERT INTO stanza VALUES('I628','7','Roh perlu dilatih,<br/>mencapai menang;<br/>Berdasarkan darah<br/>serta nama-Nya.<br/>',NULL,63521,7);
INSERT INTO stanza VALUES('I628','8','Roh perlu dilatih,<br/>''tuk jamah Tuhan;<br/>Roh menjamah firman,<br/>nikmat kaya-Nya.<br/>',NULL,63522,8);
INSERT INTO stanza VALUES('I628','9','Dengan memakai roh<br/>saksikan Kristus;<br/>Dengan memakai roh<br/>insan dipuaskan.<br/>',NULL,63523,9);
INSERT INTO stanza VALUES('I628','10','Roh perlu dilatih,<br/>''nilah perluku;<br/>Berlatih tak henti,<br/>Tuhan yang bimbing.<br/>',NULL,63524,10);
INSERT INTO stanza VALUES('I629','1','Anggota Tubuh Kristus,<br/>menampilkan Kristus;<br/>Berfungsi semuanya,<br/>pampangkan kaya-Nya;<br/>Bukan jadi penonton,<br/>semua berperan;<br/>Jangan membawa maut,<br/>bawa persekutuan.<br/>',NULL,63525,1);
INSERT INTO stanza VALUES('I629','2','Bergerak p''ri kesatuan,<br/>tak sebatang kara;<br/>Dalam koordinasi,<br/>saling b''ri bantuan;<br/>Bukan pilihan kita,<br/>ikut arus hayat;<br/>Takkan pernah menyimpang,<br/>suplaikan Roh Kudus.<br/>',NULL,63526,2);
INSERT INTO stanza VALUES('I629','3','Hanya Kristus pusatnya,<br/>bukan yang lainnya;<br/>Bersekutu dalam-Nya,<br/>nikmati kurnia-Nya;<br/>Dia Kepala pun isi,<br/>kita kep''nuhan-Nya;<br/>Aktivitas di sidang,<br/>''nyatakan diri-Nya.<br/>',NULL,63527,3);
INSERT INTO stanza VALUES('I629','4','Terbangun dalam kasih,<br/>tiada kritikan;<br/>Saling menyempurnakan,<br/>saling b''ri dukungan;<br/>Tertolong dari ego,<br/>tolak alamiah;<br/>Terlatih di dalam roh,<br/>melayani Tubuh.<br/>',NULL,63528,4);
INSERT INTO stanza VALUES('I630','1','Bagi hadir dan firman hidup-Mu,<br/>Panjatkan pujian menjelang pisah.<br/>Kami tertarik oleh diri-Mu,<br/>Berita kuat menangkap hatiku.<br/>',NULL,63529,1);
INSERT INTO stanza VALUES('I630','2','Firman-Mu, roh dan hayat bagiku;<br/>Tiap saat merawat, menyuplaiku.<br/>Aku diubah s''rupa diri-Mu,<br/>Hingga tercapai perawakan-Mu.<br/>',NULL,63530,2);
INSERT INTO stanza VALUES('I630','3','Lebih banyak suplaikan diri-Mu,<br/>Agar ku hidup, gerak dalam roh.<br/>Jaga ku dalam persekutuan-Mu,<br/>Kelak kita kembali bertemu.<br/>',NULL,63531,3);
INSERT INTO stanza VALUES('I631','1','Tuhan, menjelang kami berpisah,<br/>Oleh kelimpahan mulia-Mu;<br/>Pula kasih kurnia-Mu nan segar,<br/>Dari lubuk kami panjat syukur.<br/>',NULL,63532,1);
INSERT INTO stanza VALUES('I631','2','Walau perhimpunan hampir usai,<br/>Namun hadir-Mu kekal tak putus;<br/>Kuasa tunjang di dalam Roh-Mu.<br/>Kar''na kasih Kau suplai tak henti.<br/>',NULL,63533,2);
INSERT INTO stanza VALUES('I631','3','Penyertaan-Mu menggiring terus,<br/>Turut menanggung resah hatiku;<br/>Tiap waktu nikmati diri-Mu,<br/>Hingga nanti kembali berhimpun.<br/>',NULL,63534,3);
INSERT INTO stanza VALUES('I632','1','Tegaklah bagi Kristus,<br/>tent''ra salib kalian;<br/>Tinggikan panji Tuhan,<br/>masyhurkan nama-Nya.<br/>Tuhan-lah yang b''ri aba,<br/>menang dengan mutlak,<br/>Sampai musuh s''mua musnah,<br/>Dia Tuhan nan jaya.<br/>',NULL,63535,1);
INSERT INTO stanza VALUES('I632','2','Tegaklah bagi Kristus,<br/>dengar perintah-Nya!<br/>Maju ke medan perang,<br/>sandar nama Tuhan.<br/>Meskipun musuh ganas,<br/>jangan kamu gentar,<br/>Maju, terjang d''ngan b''rani,<br/>s''mua musuh tersingkir!<br/>',NULL,63536,2);
INSERT INTO stanza VALUES('I632','3','Tegaklah bagi Kristus,<br/>demi kuat kuasa-Nya;<br/>Jangan andalkan "aku"<br/>dan darah dagingmu.<br/>Pakailah senjata roh,<br/>berdoa tiap waktu,<br/>Lawanlah musuh-musuh,<br/>majulah demi roh.<br/>',NULL,63537,3);
INSERT INTO stanza VALUES('I632','4','Tegaklah bagi Kristus,<br/>pep''rangan s''gra lalu,<br/>Kini kuasa p''rang hebat,<br/>besok nyanyi menang.<br/>Siapa menang demi Dia,<br/>''kan dapat mahkota,<br/>Girang beserta Kristus,<br/>m''raja hingga kekal.<br/>',NULL,63538,4);
INSERT INTO stanza VALUES('I633','1','Maju! Laskar Kristus,<br/>maju berperang!<br/>Maju ikut Tuhan,<br/>ke medan juang!<br/>Panji salib junjung,<br/>serbulah musuh;<br/>Ikut komando-Nya,<br/>musuh ''kan runtuh.<br/>',NULL,63539,1);
INSERT INTO stanza VALUES('I633','chorus','Maju! Laskar Kristus,<br/>maju berperang!<br/>Panji salib junjung,<br/>ikutlah Tuhan.<br/>',NULL,63540,2);
INSERT INTO stanza VALUES('I633','2','Besar nama Yesus,<br/>tent''ra g''lap lenyap,<br/>hingga laskar Kristus<br/>selalu menang,<br/>Alam maut guncang,<br/>s''bab sorak pujian,<br/>marilah saudara<br/>kuatkan pujian.<br/>',NULL,63541,3);
INSERT INTO stanza VALUES('I633','3','Eklesia berperang,<br/>p''ri laskar besar,<br/>segenap kaum saleh,<br/>jawab panggil-Nya,<br/>Bukanlah terpisah,<br/>melainkan esa,<br/>satu: tubuh, iman,<br/>roh, dan harapan.<br/>',NULL,63542,4);
INSERT INTO stanza VALUES('I633','4','Takhta k''rajaan dunia,<br/>pasti ''kan lenyap,<br/>g''reja Kristus saja<br/>yang kekal ada,<br/>Ganas alam maut,<br/>tak kalahkan dia,<br/>g''reja pasti menang,<br/>ikut serta-Nya.<br/>',NULL,63543,5);
INSERT INTO stanza VALUES('I633','5','Maju! Hai umat-Nya!<br/>Masuk barisan!<br/>Semua angkat suara,<br/>nyanyikan menang!<br/>Mulia, pujian, hormat,<br/>bagi Sang Raja,<br/>insan pun malaikat<br/>puji Dia s''lama.<br/>',NULL,63544,6);
INSERT INTO stanza VALUES('I634','1','Terjang! Pahlawan terjang!<br/>Medan p''rang membara;<br/>Golgota sudah menang,<br/>nyanyilah d''ngan girang.<br/>Kuasa gelap, terganyang!<br/>Sarang Iblis guncang!<br/>Panglima p''rang nan jaya,<br/>datang gagah megah.<br/>',NULL,63545,1);
INSERT INTO stanza VALUES('I634','2','Terjang! Pahlawan terjang!<br/>Tengadah pada-Nya;<br/>Bagi-Nya menang perang,<br/>pasti duduk takhta.<br/>Ini perang rohani,<br/>bukan duniawi,<br/>Tuhan ta''u musuh ganas,<br/>mengepung, menyerang!<br/>',NULL,63546,2);
INSERT INTO stanza VALUES('I634','3','Terjang! Pahlawan terjang!<br/>Kau duduk takhta-Nya;<br/>Kuasa kebangkitan-Nya,<br/>padamu Dia b''rikan.<br/>Oleh Dia kau berkuasa,<br/>oleh Dia kau menang,<br/>Oleh Dia kau bersorak,<br/>oleh Dia kau t''rangkat.<br/>',NULL,63547,3);
INSERT INTO stanza VALUES('I634','4','Terjang! Pahlawan terjang!<br/>Kau duduk takhta-Nya;<br/>Pesta bagimu sedia,<br/>sambutlah d''ngan girang.<br/>Kita bangkit serta-Nya,<br/>duduk takhta surga,<br/>Bebas dari p''rang dahsyat,<br/>bebas dari dosa.<br/>',NULL,63548,4);
INSERT INTO stanza VALUES('I634','5','Terjang! Pahlawan terjang!<br/>Kau duduk takhta-Nya;<br/>Kau orang pilihan-Nya,<br/>meraja serta-Nya.<br/>Hari depanmu cerah,<br/>tiada gelap duka,<br/>Serta Yesus s''lamanya,<br/>nikmati kasih-Nya.<br/>',NULL,63549,5);
INSERT INTO stanza VALUES('I634','6','Terjang! Pahlawan terjang!<br/>Depan ada takhta;<br/>Mari semua menyanyi,<br/>kidung kemenangan.<br/>Anak Domba tersemb''lih,<br/>sudah menang kini,<br/>Sorak sorai puji Dia,<br/>Dia menang s''lamanya.<br/>',NULL,63550,6);
INSERT INTO stanza VALUES('I635','1','Waktu godaan menimpa,<br/>sekitarmu gelaplah;<br/>Roh jahat s''lalu berbisik,<br/>untung, malang, ya, nasib.<br/>',NULL,63551,1);
INSERT INTO stanza VALUES('I635','chorus','Pahlawan, kau harus tegap!<br/>Ingat, Tuhan t''lah menang!<br/>Yesus t''lah kalahkan Satan,<br/>serbulah, jangan gentar!<br/>',NULL,63552,2);
INSERT INTO stanza VALUES('I635','2','Sewaktu temanmu b''rubah,<br/>padamu berkhianat;<br/>Tetanggamu pun menghina,<br/>berkawan dengan lawan.<br/>',NULL,63553,3);
INSERT INTO stanza VALUES('I635','3','Waktu dunia d''ngan mewahnya,<br/>diam-diam ''kan memperangkap,<br/>Menawan d''ngan simpatinya,<br/>hingga kau hilang iman.<br/>',NULL,63554,4);
INSERT INTO stanza VALUES('I635','4','Waktu urusan membukit,<br/>jiwa p''nat, badan letih;<br/>Rugi, sakit, susah hati,<br/>j''rih payah tak berarti.<br/>',NULL,63555,5);
INSERT INTO stanza VALUES('I635','5','Perang segera berakhir,<br/>Satan, roh jahat t''rusir;<br/>Gereja seg''ra terangkat,<br/>dapat mulia dan menang.<br/>',NULL,63556,6);
INSERT INTO stanza VALUES('I635','6','Set''lah itu Raja menang,<br/>berkuasa atas s''mesta;<br/>Bangsa-bangsa ''kan bersujud,<br/>menyembah pada Yesus.<br/>',NULL,63557,7);
INSERT INTO stanza VALUES('I636','1','Tegaklah tent''ra Tuhan,<br/>tak hirau kata orang,<br/>Tak takut muka tanah,<br/>di hari jahat.<br/>',NULL,63558,1);
INSERT INTO stanza VALUES('I636','2','Tegaklah tent''ra Tuhan,<br/>mau membayar harga,<br/>Ikut langkah kaum saleh,<br/>kar''na firman-Nya.<br/>',NULL,63559,2);
INSERT INTO stanza VALUES('I636','3','Tegaklah tent''ra Tuhan,<br/>tak tertipu p''lesiran,<br/>Tak terbujuk manusia,<br/>kalahkan musuh.<br/>',NULL,63560,3);
INSERT INTO stanza VALUES('I636','4','Tegaklah tent''ra Tuhan,<br/>hanya mau Tuhan saja,<br/>Berjaga dalam doa,<br/>sampai Dia datang.<br/>',NULL,63561,4);
INSERT INTO stanza VALUES('I637','1','Berperang di dalam Tubuh,<br/>jangan perang sendiri,<br/>Tubuh melekat Kepala,<br/>perang kalahkan musuh.<br/>',NULL,63562,1);
INSERT INTO stanza VALUES('I637','chorus','Berperang di dalam Tubuh,<br/>dengan sandar Kepala,<br/>Kukuh tegak dalam Tubuh,<br/>kau pasti menang perang.<br/>',NULL,63563,2);
INSERT INTO stanza VALUES('I637','2','Semua senjata Allah,<br/>bagi Tubuh-Nya s''mata,<br/>Dalam Tubuh kau berperang,<br/>s''mua faedah kau rasakan.<br/>',NULL,63564,3);
INSERT INTO stanza VALUES('I637','3','Atas Kristus g''reja tegak,<br/>alam maut tak berdaya,<br/>Tubuh bersama terbangun,<br/>menentang kuasa jahat.<br/>',NULL,63565,4);
INSERT INTO stanza VALUES('I637','4','Oleh Tubuh, sandar K''pala,<br/>duduk di dalam surga,<br/>Berperang lawan roh jahat,<br/>tak kendur sedikit jua.<br/>',NULL,63566,5);
INSERT INTO stanza VALUES('I637','5','Sebagai anggota Tubuh,<br/>berdiri di pihak-Nya,<br/>''Tiasa doa di dalam Roh,<br/>menang bersandar darah.<br/>',NULL,63567,6);
INSERT INTO stanza VALUES('I637','6','Salam surga menang mutlak,<br/>oleh kuat kuasa-Nya,<br/>Sebagai tentara Allah,<br/>berperang dalam Tuhan.<br/>',NULL,63568,7);
INSERT INTO stanza VALUES('I637','7','Tetap maju dalam Tubuh,<br/>si jahat tertaklukkan,<br/>Ikat, lepas, seturut-Nya,<br/>musuh jadi makanan.<br/>',NULL,63569,8);
INSERT INTO stanza VALUES('I638','1','Allah itu benteng kukuh,<br/>kuat teguh tak runtuh;<br/>Meski dosa jahat kepung,<br/>Dia bantu apa takut?<br/>Musuh incar terus,<br/>s''lalu siap menyerbu,<br/>Penuh siasat tipu,<br/>ganas dan pembunuh,<br/>Insan ''nentang tak mampu.<br/>',NULL,63570,1);
INSERT INTO stanza VALUES('I638','2','Bila andal kuat diri,<br/>kalah perang t''lah pasti;<br/>Pilihan Allah dampingi,<br/>sandar Dia tak alih!<br/>Orang yang terpilih,<br/>Kristus Sang Almuhit,<br/>Dia raja semesta,<br/>hinggalah abadi,<br/>Jaya takkan terguling.<br/>',NULL,63571,2);
INSERT INTO stanza VALUES('I638','3','Walau dunia penuh setan,<br/>mengacau dan merusak,<br/>Allah pasti ''mihak kita,<br/>''nyatakan kebenaran.<br/>Enyah untung, tenar;<br/>mati hidup bers''rah,<br/>Bagi keb''naran-Nya,<br/>ku rela berkorban,<br/>K''rajaan-Nya kekalah.<br/>',NULL,63572,3);
INSERT INTO stanza VALUES('I639','1','Bila perang sengit,<br/>musuh keji;<br/>Percaya firman-Nya,<br/>dan memuji.<br/>',NULL,63573,1);
INSERT INTO stanza VALUES('I639','2','Berserulah saja,<br/>menang pasti;<br/>Dan lawanlah dengan<br/>ucap saksi.<br/>',NULL,63574,2);
INSERT INTO stanza VALUES('I639','3','Gundah sebal rohmu,<br/>dan melesu;<br/>Doa berdasar darah,<br/>pasti bubung.<br/>',NULL,63575,3);
INSERT INTO stanza VALUES('I639','4','Musuh memang sadis,<br/>jangan gentar;<br/>Bertahan di kubu,<br/>jaya tentu.<br/>',NULL,63576,4);
INSERT INTO stanza VALUES('I639','5','Mari, sorak lantang,<br/>Tuhan menang!<br/>Gelap di seputar,<br/>pasti sirna.<br/>',NULL,63577,5);
INSERT INTO stanza VALUES('I640','1','Pada Iblis s''lalu:<br/>"Tidak!" Pada Bapa pasti : "Ya!"<br/>Supaya rencana Tuhan<br/>genap pula sempurna.<br/>Waktu ku taat perintah,<br/>Tuhan b''rikanlah kuasa,<br/>Biar t''naga Roh-Mu melimpah,<br/>murad-Mu terlaksana.<br/>',NULL,63578,1);
INSERT INTO stanza VALUES('I640','2','Pada Iblis s''lalu:<br/>"Tidak!" Pada Bapa pasti : "Ya!"<br/>Inilah sikapku s''lama,<br/>Bapa lindungi ''tiasa.<br/>Biar pada-Mu tetap patuh,<br/>meski Iblis membujuk,<br/>Waktu ku taat p''rintah-Mu,<br/>jagalah, ya, Tuhanku.<br/>',NULL,63579,2);
INSERT INTO stanza VALUES('I640','3','Pada Iblis s''lalu:<br/>"Tidak!" Pada Bapa pasti : "Ya!"<br/>Ku mau patuh dengan mutlak,<br/>meski banyak derita.<br/>Waktu ku maju d''ngan Tuhan,<br/>Dia pasti menjaga,<br/>Meski banyak mara bah''ya,<br/>aku takkan menyesal.<br/>',NULL,63580,3);
INSERT INTO stanza VALUES('I641','1','Kini perang dahsyat, musuh ganas;<br/>Seruan dari medan p''rang kian lantang!<br/>Tantangan kuasa maut, kian hebat!<br/>Tapi Dia berseru, "Ku sg''ra datang!"<br/>',NULL,63581,1);
INSERT INTO stanza VALUES('I641','2','Kini ujian berat, perang meluas;<br/>Kuasa maut siap dengan tent''ranya.<br/>Nampak ini semua, hati gundah;<br/>Tapi terd''ngar b''rita, "Dia t''lah dekat!"<br/>',NULL,63582,2);
INSERT INTO stanza VALUES('I641','3','Saksikan nama-Nya makin sukar,<br/>Kar''na Satan selalu menindas.<br/>Mengalahkan lawan, perlu kuasa,<br/>Bila Tuhan datang, o, giranglah!<br/>',NULL,63583,3);
INSERT INTO stanza VALUES('I641','4','Siapa yang t''rus maju demi Tuhan?<br/>Siapa yang beriman hingga menang?<br/>Siapa yang berperang dengan gagah?<br/>Pasti senang dengar, "Ku sg''ra datang!"<br/>',NULL,63584,4);
INSERT INTO stanza VALUES('I641','5','Jalan salib sempit, siapa pilih?<br/>Meskipun sengsara tidak balik!<br/>Siapa b''rani maju, tanpa gentar?<br/>Pasti nampak Yesus sudah dekat!<br/>',NULL,63585,5);
INSERT INTO stanza VALUES('I641','6','Meski malam larut, majulah t''rus,<br/>Hingga depan Tuhan, nampak mulia!<br/>Waktu itu musuh hancur luluh,<br/>Yang menang berseru, "Yesus datang!"<br/>',NULL,63586,6);
INSERT INTO stanza VALUES('I642','1','Tegap demi nama Yesus,<br/>menang, jaya, teguh;<br/>Tidak sandar kuat diri,<br/>kemampuan lain.<br/>Bukan dengan tubuh daging,<br/>tapi d''ngan Roh suci;<br/>Memakai senjata Allah,<br/>panah musuh runtuh.<br/>',NULL,63587,1);
INSERT INTO stanza VALUES('I642','2','Tengok! Musuh ''kan menyerbu,<br/>jagalah tempatmu!<br/>K''liling gelap, perang gawat,<br/>tegap sandar Tuhan.<br/>Bila kau undur dan bimbang,<br/>goyahkan pasukan,<br/>Jangan kar''na kau seorang,<br/>semuanya celaka.<br/>',NULL,63588,2);
INSERT INTO stanza VALUES('I642','3','Musuh ta''u akhir sg''ra tiba,<br/>m''reka makin marah,<br/>Sebelum perang berkobar,<br/>rohmu diusiknya.<br/>Kini godaan kian hebat,<br/>derita kian banyak,<br/>Kuasa maut menindas,<br/>kian lama kian jahat.<br/>',NULL,63589,3);
INSERT INTO stanza VALUES('I642','4','Bagaimana sikap kita,<br/>t''radap ini semua?<br/>Bolehkah lalai dan lengah,<br/>musuh m''raja lela?<br/>Atau d''rita kian bertambah,<br/>kita kian b''rani p''rang?<br/>Mati hidup seg''ra nyata!<br/>Siapa mau pahala?<br/>',NULL,63590,4);
INSERT INTO stanza VALUES('I642','5','Tegap bagi nama Tuhan,<br/>Yesus-lah pemenang;<br/>Bertahanlah dalam susah,<br/>hingga Tuhan datang.<br/>Tuhan seg''ra datang pula,<br/>peperangan tamat,<br/>Kini d''rita bagi Tuhan,<br/>kelak dapat kuasa.<br/>',NULL,63591,5);
INSERT INTO stanza VALUES('I643','1','Menang, menang, haleluya!<br/>Menang, menang, haleluya!<br/>Menang, menang, haleluya!<br/>Kristus sudah menang!<br/>',NULL,63592,1);
INSERT INTO stanza VALUES('I643','2','Menang, menang, haleluya!<br/>Menang, menang, haleluya!<br/>Menang, menang, haleluya!<br/>Kristus buat ku menang!<br/>',NULL,63593,2);
INSERT INTO stanza VALUES('I643','3','Mulia, mulia, haleluya!<br/>Mulia, mulia, haleluya!<br/>Mulia, mulia, haleluya!<br/>Mulia bagi Tuhan!<br/>',NULL,63594,3);
INSERT INTO stanza VALUES('I644','1','Haleluya, Yesus menang!<br/>Mari bersorak!<br/>Yesus menang! Menang atas maut,<br/>Iblis, dosa!<br/>',NULL,63595,1);
INSERT INTO stanza VALUES('I644','chorus','Haleluya! Yesus menang!<br/>B''rita yang mulia!<br/>Yesus menang, tetap menang<br/>atas s''mua lawan!<br/>',NULL,63596,2);
INSERT INTO stanza VALUES('I644','2','Haleluya, Yesus menang!<br/>Darah berkuasa!<br/>Demi salib-Nya bermegah,<br/>Iblis ''kan gentar.<br/>',NULL,63597,3);
INSERT INTO stanza VALUES('I644','3','Haleluya, Yesus menang!<br/>Sakit pun hilang!<br/>Demi Yesus menang mutlak<br/>pada Golgota.<br/>',NULL,63598,4);
INSERT INTO stanza VALUES('I644','4','Haleluya, Yesus menang!<br/>Bersiap sedialah,<br/>Diutus ke mana saja,<br/>pergi d''ngan rela!<br/>',NULL,63599,5);
INSERT INTO stanza VALUES('I644','5','Haleluya, Yesus menang!<br/>Jangan mengalah!<br/>Meski depan sangat gelap,<br/>Dia bukan jalan.<br/>',NULL,63600,6);
INSERT INTO stanza VALUES('I644','6','Haleluya, Yesus menang!<br/>Dia seg''ra datang!<br/>Semua yang menang serta-Nya<br/>pasti gembira!<br/>',NULL,63601,7);
INSERT INTO stanza VALUES('I645','1','Kuasa di bumi dan langit,<br/>pada Kristus yang t''lah bangkit;<br/>Hidup padu pun sandar Dia,<br/>semua musuh tentu rebah.<br/>',NULL,63602,1);
INSERT INTO stanza VALUES('I645','2','Demi nama-Nya ku pasti,<br/>tumpas s''gala kuasa Iblis;<br/>Dari Tuhan t''rima kuasa,<br/>remukkan kepala ular.<br/>',NULL,63603,2);
INSERT INTO stanza VALUES('I645','3','Tak peduli, hai s''mua bukit!<br/>Di langit atau di bumi!<br/>Demi Yesus, aku pasti<br/>usir kamu seg''ra pergi.<br/>',NULL,63604,3);
INSERT INTO stanza VALUES('I645','4','Dengan iman aku halau,<br/>ke dalam laut kau terbenam!<br/>Aku mau, harus, dan pasti,<br/>rampung murad-Nya abadi.<br/>',NULL,63605,4);
INSERT INTO stanza VALUES('I646','1','Menang demi darah Kristus,<br/>kalahkan semua lawan;<br/>Demi khasiat dan kuasanya,<br/>kau pasti raih menang.<br/>',NULL,63606,1);
INSERT INTO stanza VALUES('I646','chorus','Menang demi darah Kristus,<br/>kalahkan semua lawan;<br/>Demi khasiat dan kuasanya,<br/>kau pasti raih menang.<br/>',NULL,63607,2);
INSERT INTO stanza VALUES('I646','2','Menang demi darah Kristus,<br/>lawanlah si pendakwa;<br/>Demi darah yang membela,<br/>tolaklah si pemfitnah.<br/>',NULL,63608,3);
INSERT INTO stanza VALUES('I646','3','Menang demi darah Kristus,<br/>percaya setia-Nya;<br/>Lewat darah yang menebus,<br/>terima ampunan-Nya.<br/>',NULL,63609,4);
INSERT INTO stanza VALUES('I646','4','Menang demi darah Kristus,<br/>umumkan posisimu;<br/>Lewat darah yang menang t''rus,<br/>kalahkan semua musuh.<br/>',NULL,63610,5);
INSERT INTO stanza VALUES('I646','5','Menang demi darah Kristus,<br/>pakailah kuasa-Nya;<br/>Gunakanlah darah Kristus,<br/>kau pasti mutlak menang.<br/>',NULL,63611,6);
INSERT INTO stanza VALUES('I646','6','Menang demi darah Kristus,<br/>dalam suasana surga;<br/>Dalam kuasa kenaikan-Nya,<br/>injak semua lawan.<br/>',NULL,63612,7);
INSERT INTO stanza VALUES('I647','1','Maukah jadi pemenang-Nya?<br/>Tuhan memanggil!<br/>Maukah jadi pengikut-Nya?<br/>Lain tak peduli!<br/>',NULL,63613,1);
INSERT INTO stanza VALUES('I647','chorus','Maukah jadi pemenang-Nya?<br/>Puaskan hati-Nya?<br/>Tuhan panggil, Tuhan panggil,<br/>beri mahkota!<br/>',NULL,63614,2);
INSERT INTO stanza VALUES('I647','2','Maukah jadi pemenang-Nya?<br/>Tertarik Tuhan!<br/>"Kasih semula" tak pudar,<br/>fajar s''gra tiba.<br/>',NULL,63615,3);
INSERT INTO stanza VALUES('I647','3','Maukah jadi pemenang-Nya?<br/>Sandar hayat-Nya;<br/>Berani tanggung aniaya,<br/>setia tak ubah.<br/>',NULL,63616,4);
INSERT INTO stanza VALUES('I647','4','Maukah jadi pemenang-Nya?<br/>Jadi saksi-Nya;<br/>T''rima "manna tersembunyi",<br/>sudahlah pasti.<br/>',NULL,63617,5);
INSERT INTO stanza VALUES('I647','5','Maukah jadi pemenang-Nya?<br/>Polos dan tulus;<br/>Kalahkan s''mua kalut jahat,<br/>dapat "kuasa-Nya".<br/>',NULL,63618,6);
INSERT INTO stanza VALUES('I647','6','Maukah jadi pemenang-Nya?<br/>Sandar Sang Hidup;<br/>"Jubah" bebas noda maut,<br/>terima hayat.<br/>',NULL,63619,7);
INSERT INTO stanza VALUES('I647','7','Maukah jadi pemenang-Nya?<br/>Junjung nama-Nya;<br/>Dan pegang "firman tekun-Nya",<br/>sekuat tenaga.<br/>',NULL,63620,8);
INSERT INTO stanza VALUES('I647','8','Maukah jadi pemenang-Nya?<br/>Tak "suam kuku"!<br/>Jangan puas dengan yang ada,<br/>perlu meningkat.<br/>',NULL,63621,9);
INSERT INTO stanza VALUES('I647','9','Maukah jadi pemenang-Nya?<br/>Tuhan memanggil!<br/>Maukah setia kepada-Nya,<br/>g''napkan murad-Nya?<br/>',NULL,63622,10);
INSERT INTO stanza VALUES('I648','1','Nampak salib di sana,<br/>ku tak b''rani lengah,<br/>Tuhan Yesus t''lah menang,<br/>kuasa gelap patah.<br/>B''ri wahyu kemenangan,<br/>biar ku b''rani perang,<br/>Perang hinggalah menang,<br/>sandar kuasa Tuhan.<br/>',NULL,63623,1);
INSERT INTO stanza VALUES('I648','chorus','Menang, pemenang,<br/>karena Golgota;<br/>Aku jadi pemenang,<br/>karena Tuhan sudah menang.<br/>',NULL,63624,2);
INSERT INTO stanza VALUES('I648','2','Yesus Kristus di sana,<br/>ku tak b''rani lengah,<br/>Ku maju ke medang p''rang,<br/>berjuang serta-Nya.<br/>Moga Tuhan b''ri tabah,<br/>kuat, dan perkasa,<br/>Biar ku jadi pemenang,<br/>dapatkan pahala.<br/>',NULL,63625,3);
INSERT INTO stanza VALUES('I648','3','Kar''na Yesus b''ri aba,<br/>ku tak b''rani lengah,<br/>Tumpas kuasa si jahat,<br/>naik takhta serta-Nya.<br/>Tuhan b''ri perwira-Mu,<br/>tenaga yang ampuh,<br/>Biar ku jadi pemenang,<br/>demi firman Tuhan.<br/>',NULL,63626,4);
INSERT INTO stanza VALUES('I648','4','Waktu sudahlah senja,<br/>ku tak b''rani lengah,<br/>Tuhan tunggu di sana,<br/>sediakan pahala.<br/>Moga Tuhan kurniakan,<br/>tenaga yang segar,<br/>Biar ku jadi pemenang,<br/>menang hingga kekal.<br/>',NULL,63627,5);
INSERT INTO stanza VALUES('I649','1','Iblis t''lah tetapkan<br/>lawan Benih Allah-ku;<br/>G''reja pasukan-Nya siap!<br/>T''lah t''rima kabar.<br/>',NULL,63628,1);
INSERT INTO stanza VALUES('I649','chorus','Kita tinggal di dunia<br/>untuk berperang!<br/>Ingin genapkan murad-Nya,<br/>harus berperang.<br/>',NULL,63629,2);
INSERT INTO stanza VALUES('I649','2','Bala gelap dikerahkan,<br/>sudah mendesak;<br/>Bangun! G''reja pasukan-Nya!<br/>Tent''ra intinya.<br/>',NULL,63630,3);
INSERT INTO stanza VALUES('I649','3','Siapa yang berkhianat?<br/>Cinta dunia?<br/>G''reja pasukan-Nya lengah<br/>apa jadinya?<br/>',NULL,63631,4);
INSERT INTO stanza VALUES('I649','4','Siapa kecut hatinya<br/>di depan lawan?<br/>G''reja pasukan-Nya malu<br/>bila menghindar.<br/>',NULL,63632,5);
INSERT INTO stanza VALUES('I649','5','Siapa tak untuk Tuhan;<br/>membantu musuh!<br/>G''reja pasukan-Nya ingin<br/>membela siapa?<br/>',NULL,63633,6);
INSERT INTO stanza VALUES('I649','6','Pemenang tetaplah menang,<br/>nikmat jasa-Nya;<br/>G''reja pasukan-Nya sadar,<br/>salib baginya!<br/>',NULL,63634,7);
INSERT INTO stanza VALUES('I649','7','Tuhan kita sang Pejuang,<br/>mengapa gentar?<br/>Sikap takut jelas bukan<br/>sikap pejuang.<br/>',NULL,63635,8);
INSERT INTO stanza VALUES('I649','8','Tuhan memanggil pemenang,<br/>siapa memihak?<br/>G''reja pasukan-Nya lekas<br/>angkat senjata.<br/>',NULL,63636,9);
INSERT INTO stanza VALUES('I650','1','Bukan semau kita,<br/>melainkan pimpinan-Nya;<br/>Arah air hidup ''ngalir,<br/>di sana hati terang.<br/>',NULL,63637,1);
INSERT INTO stanza VALUES('I650','2','Bukan pilihan kita,<br/>menarik perkenan-Nya;<br/>Tapi rampung tugas-Nya,<br/>baru t''rima pahala.<br/>',NULL,63638,2);
INSERT INTO stanza VALUES('I650','3','Bukan menurut ego,<br/>doa di depan takhta;<br/>Keluh kesah Roh Kudus,<br/>menjamah keperluan.<br/>',NULL,63639,3);
INSERT INTO stanza VALUES('I650','4','Bila menjawab "tidak",<br/>bisikan-Nya "Ku perlu";<br/>Kurban taruh di altar,<br/>tak menarik hati-Nya.<br/>',NULL,63640,4);
INSERT INTO stanza VALUES('I650','5','Mati terhadap ego,<br/>hidup surga dengan-Nya;<br/>Konsekrasi, ''layani,<br/>Tuhan jadi pahala.<br/>',NULL,63641,5);
INSERT INTO stanza VALUES('I651','1','''Layani Tuhan tidak harus<br/>arung lautan jauh,<br/>Tanjak tebing gunung yang terjal,<br/>terobos tempat rawan;<br/>Bila Dia memanggilku pergi,<br/>ke tujuan tak dikenal,<br/>Tuhan, ku pasti menjawab d''ngan tegas:<br/>mana saja ku siap.<br/>',NULL,63642,1);
INSERT INTO stanza VALUES('I651','chorus','Tuhan, aku siap, dataran,<br/>gunung, maupun lembah;<br/>Ke mana, ku siap; berkata apa,<br/>ku mau mutlak taat.<br/>',NULL,63643,2);
INSERT INTO stanza VALUES('I651','2','Mungkin ada kata indah-Mu,<br/>yang Kau suruh siarkan,<br/>Jiwa k''lana di jalan dosa,<br/>perlu ku rebut pulang;<br/>Tuhan, asal Kau yang memimpin,<br/>meski jalan amat g''lap,<br/>Ku akan gemakan kabar baik-Mu,<br/>seturut kehendak-Mu.<br/>',NULL,63644,3);
INSERT INTO stanza VALUES('I651','3','Di tanah ladang luas dunia,<br/>aku punya sejengkal,<br/>Ku habiskan sisa hidupku,<br/>untuk Tuhan yang wafat;<br/>Ku serah diri ke tangan-Mu,<br/>karena Kau cintaku,<br/>Dari lubuk ku taat kehendak-Mu,<br/>apa saja ku turut.<br/>',NULL,63645,4);
INSERT INTO stanza VALUES('I652','1','Jangan tunggu, terus mimpi k''lak sukses besar;<br/>Jangan tunggu, sorotkan terang,<br/>Banyak tugasmu, tunaikan, bereskan s''karang;<br/>Sorot terangmu di s''putar.<br/>',NULL,63646,1);
INSERT INTO stanza VALUES('I652','chorus','Sorot terangmu di s''putar!<br/>Sorot terangmu di s''putar!<br/>Suasana buruk, lebih memerlukan terang;<br/>Sorot terangmu di s''putar!<br/>',NULL,63647,2);
INSERT INTO stanza VALUES('I652','2','P''rintah Tuhan, "Terangmu sorot depan orang."<br/>Taati, jangan tudung terang;<br/>Perlu orang dosa ditolong dari gelap;<br/>Sorot terangmu di s''putar!<br/>',NULL,63648,3);
INSERT INTO stanza VALUES('I652','3','Tengok, banyak orang saleh yang berkelana;<br/>Jangan cari di kejauhan,<br/>Anjur, hibur, rawat, b''ri simpati, p''ri Tuhan;<br/>Sorot terangmu di s''putar!<br/>',NULL,63649,4);
INSERT INTO stanza VALUES('I652','4','''Tiasa sekutu d''ngan Tuhan, pandang wajah-Nya;<br/>Baru pantulkan cah''ya mulia,<br/>Setia kepada Tuhan, orang terjamah;<br/>Sorot terangmu di s''putar!<br/>',NULL,63650,5);
INSERT INTO stanza VALUES('I652','5','Bintang fajar seg''ra terbit, Tuhan ''kan tiba;<br/>Hamba akan t''rima pahala,<br/>Rebut jiwa, rawat orang, mumpung sekarang;<br/>Sorot terangmu di s''putar!<br/>',NULL,63651,6);
INSERT INTO stanza VALUES('I653','1','Di dalam arus-Nya,<br/>bekerja bagi-Nya,<br/>Menurut cara-Nya,<br/>sesuai firman-Nya,<br/>Di dalam hayat-Nya,<br/>dengan kuasa-Nya,<br/>Demi gereja-Nya,<br/>''layani bersama.<br/>',NULL,63652,1);
INSERT INTO stanza VALUES('I653','chorus','Di dalam arus-Nya,<br/>bekerja bagi-Nya.<br/>Di dalam arus-Nya!<br/>Berkoordinasi bekerja!<br/>',NULL,63653,2);
INSERT INTO stanza VALUES('I653','2','Di dalam arus-Nya!<br/>Bekerja bagi-Nya,<br/>Dalam arus roh-Nya,<br/>sesuai firman-Nya,<br/>Tak semau diri,<br/>tak sandar kuat diri,<br/>Tapi melayani,<br/>harmonis, serasi.<br/>',NULL,63654,3);
INSERT INTO stanza VALUES('I653','3','Di dalam arus-Nya!<br/>Bekerja bagi-Nya,<br/>Bersama gereja,<br/>dalam t''rang firman-Nya,<br/>Salur firman hayat<br/>kepada manusia,<br/>Genap rencana-Nya,<br/>maju di arus-Nya.<br/>',NULL,63655,4);
INSERT INTO stanza VALUES('I654','1','Pelayanan zaman baru,<br/>bukan huruf tapi Roh,<br/>Huruf niscaya membunuh,<br/>hanya Roh beri hidup.<br/>Lahiriah tak terhitung,<br/>batiniah terhitung,<br/>Cara usang tak berlaku,<br/>melainkan corak baru.<br/>',NULL,63656,1);
INSERT INTO stanza VALUES('I654','2','Bukan ajaran di luar,<br/>tapi urapan minyak,<br/>Bukan pola lahiriah,<br/>tapi terang di dalam.<br/>Bukan aturan manusia,<br/>tapi aturan surga,<br/>Bukan putusan manusia,<br/>tapi turut wahyu-Nya.<br/>',NULL,63657,2);
INSERT INTO stanza VALUES('I654','3','Suplaikan Kristus yang hidup,<br/>bukan agama mati,<br/>Perhidupkan limpah Kristus,<br/>bukan hampa teologi.<br/>Kristus berita pun judul,<br/>bukan huruf teori,<br/>Kristus jadi realitas,<br/>bukan cara, liturgi.<br/>',NULL,63658,3);
INSERT INTO stanza VALUES('I654','4','''Layani dengan subyektif,<br/>bukan sembah yang obyektif,<br/>Atasku Kristus tertampak,<br/>bukannya yang obyektif.<br/>Melalui roh dan hayat,<br/>bukan Alkitab s''mata,<br/>Sandar kuasa Roh Kudus,<br/>bukan sandarkan awak.<br/>',NULL,63659,4);
INSERT INTO stanza VALUES('I655','1','Alir hayat itu karya,<br/>itu pun kehidupan;<br/>Hidup, karya jadi satu,<br/>baru ada hasilnya.<br/>Pengalaman jadi b''rita,<br/>b''rita hasil p''ngalaman,<br/>Esa - pengalaman, b''rita;<br/>B''rita barulah kuat.<br/>',NULL,63660,1);
INSERT INTO stanza VALUES('I655','2','Karya itu buah hayat,<br/>hasil dari Roh itu;<br/>S''perti ranting anggur berbuah,<br/>''nyatakan hayat limpah.<br/>Kristus yang kerja lewatku,<br/>ekspresikan hayat-Nya,<br/>Hingga kaya limpah hayat,<br/>tertampak depan orang.<br/>',NULL,63661,2);
INSERT INTO stanza VALUES('I655','3','Bukan gerakan manusia,<br/>tapi Roh Kudus Tuhan;<br/>Bukan tindakan luaran,<br/>tapi tindakan batin.<br/>Bukan semacam usaha,<br/>tapi hidupkan hayat;<br/>Bukan jerih untuk sukses,<br/>tapi Kristus tertampil.<br/>',NULL,63662,3);
INSERT INTO stanza VALUES('I655','4','Rencana dan usahaku,<br/>harus dikesampingkan;<br/>Biar Dia bekerja lewatku,<br/>merampungkan hasrat-Nya.<br/>Hakikiku dan milikku,<br/>dimatikan semua;<br/>Tuhan hidup melaluiku,<br/>nyata limpah, elok-Nya.<br/>',NULL,63663,4);
INSERT INTO stanza VALUES('I656','1','Kerja, ''layan dalam Tubuh,<br/>ini inti murad-Nya;<br/>Tubuh ialah dambaan-Nya,<br/>harus gerak d''ngan Tubuh.<br/>',NULL,63664,1);
INSERT INTO stanza VALUES('I656','chorus','Kerja, ''layan dalam Tubuh,<br/>janganlah individu;<br/>Sebagai anggota Tubuh,<br/>bersama ''layani-Nya.<br/>',NULL,63665,2);
INSERT INTO stanza VALUES('I656','2','Kita jadi anggota-Nya,<br/>bukan yang menyendiri;<br/>Harus bersama kaum saleh,<br/>saling berkoordinasi.<br/>',NULL,63666,3);
INSERT INTO stanza VALUES('I656','3','Batu hidup yang terbangun,<br/>jadi istana Allah;<br/>Jadi imamat yang kudus,<br/>serasi ''layani-Nya.<br/>',NULL,63667,4);
INSERT INTO stanza VALUES('I656','4','Harus terbangun bersama,<br/>''layan sesuai talenta;<br/>Dasar semua pelayanan<br/>adalah sifat Tubuh.<br/>',NULL,63668,5);
INSERT INTO stanza VALUES('I656','5','Pelayanan, kerja kita,<br/>terima suplai Tubuh;<br/>Bila lepas dari Tubuh,<br/>hilang fungsi dan daya.<br/>',NULL,63669,6);
INSERT INTO stanza VALUES('I656','6','Kalau ''layani di Tubuh,<br/>t''rima kaya Kepala;<br/>Tunaikan fungsi anggota,<br/>capai perawakan-Nya.<br/>',NULL,63670,7);
INSERT INTO stanza VALUES('I656','7','S''lamanya pegang Kepala,<br/>oleh-Nya kita tumbuh;<br/>Dari-Nya terima suplai,<br/>untuk antero Tubuh.<br/>',NULL,63671,8);
INSERT INTO stanza VALUES('I656','8','Tuhan, diri ku sembahkan,<br/>ubahlah pikiranku;<br/>Hingga ku paham murad-Mu,<br/>''layan lewat Tubuh-Mu.<br/>',NULL,63672,9);
INSERT INTO stanza VALUES('I657','1','Hidup imam sungguh berkat,<br/>Kristus jadi s''galanya!<br/>Kristus, sandang, pangan,<br/>papan, pun warisan mereka.<br/>',NULL,63673,1);
INSERT INTO stanza VALUES('I657','chorus','Hidup imam sungguh berkat!<br/>Kristus jadi s''galanya!<br/>Kristus, sandang, pangan,<br/>papan, pun warisan mereka.<br/>',NULL,63674,2);
INSERT INTO stanza VALUES('I657','2','Pakaian pelayanannya,<br/>s''mua keindahan Kristus;<br/>Tutup bahu, tutup dada,<br/>s''marak, hormat, dan mulia.<br/>',NULL,63675,3);
INSERT INTO stanza VALUES('I657','3','Imam persembahkan Kristus,<br/>kurban perkenan Allah;<br/>''Nikmati Dia s''bagai pangan,<br/>penuh d''ngan kaya Kristus.<br/>',NULL,63676,4);
INSERT INTO stanza VALUES('I657','4','Pakai Kristus esa d''ngan-Nya,<br/>lahir ada wujud-Nya;<br/>Makan Kristus baur dengan-Nya,<br/>batin dipenuhi-Nya.<br/>',NULL,63677,5);
INSERT INTO stanza VALUES('I657','5','Kediaman imam ilahi,<br/>Kristus yang diperluas;<br/>Di sini imam terbangun,<br/>jadi rumah rohani.<br/>',NULL,63678,6);
INSERT INTO stanza VALUES('I657','6','Kristus segalanya imam,<br/>warisan unik imam;<br/>Hidup dan perihal imam,<br/>semuanya ialah Kristus.<br/>',NULL,63679,7);
INSERT INTO stanza VALUES('I658','1','P''layananku untuk g''reja,<br/>inilah hasrat Allah;<br/>Jalan pelayanan ini,<br/>ditempuh oleh rasul.<br/>',NULL,63680,1);
INSERT INTO stanza VALUES('I658','chorus','P''layananku untuk g''reja,<br/>bukan untuk yang lain;<br/>''Nilah murad sempurna-Nya,<br/>yang harus kita tempuh.<br/>',NULL,63681,2);
INSERT INTO stanza VALUES('I658','2','Rencana Allah yang kekal,<br/>g''reja jadi wadah-Nya;<br/>Semua pelayanan kita,<br/>untuk bangun rumah-Nya.<br/>',NULL,63682,3);
INSERT INTO stanza VALUES('I658','3','Orang yang berkarunia,<br/>semua untuk Tubuh-Nya;<br/>M''reka harus bangun g''reja,<br/>tampilkan limpah Tuhan.<br/>',NULL,63683,4);
INSERT INTO stanza VALUES('I658','4','Semua kurnia, semua fungsi,<br/>kuasa yang roh ''nyatakan;<br/>Serta ministri yang beda,<br/>semua untuk Tubuh-Nya.<br/>',NULL,63684,5);
INSERT INTO stanza VALUES('I658','5','Semua pemb''ritaan Injil,<br/>ajaran, pengasuhan;<br/>Pun berbagai pekerjaan,<br/>juga untuk Tubuh-Nya.<br/>',NULL,63685,6);
INSERT INTO stanza VALUES('I658','6','Ministri untuk gereja,<br/>bukan yang sebaliknya;<br/>Kaki dian ialah gereja,<br/>tapi ministri bukan.<br/>',NULL,63686,7);
INSERT INTO stanza VALUES('I658','7','Ini jaga g''reja esa,<br/>terlepas dari sekte;<br/>Ini uji hati kita,<br/>koreksi tujuan kita.<br/>',NULL,63687,8);
INSERT INTO stanza VALUES('I658','8','Tolong ku lepas kerjaan,<br/>lepas kerjaan sekte;<br/>Hanya berlelah ''tuk g''reja,<br/>hanya hidup ''tuk g''reja.<br/>',NULL,63688,9);
INSERT INTO stanza VALUES('I659','1','Pelayanan: suplai Kristus<br/>pada Allah dan insan,<br/>S''lalu suplai limpah Kristus,<br/>Dia-lah kurban bagi-Nya.<br/>',NULL,63689,1);
INSERT INTO stanza VALUES('I659','chorus','Pelayanan: suplai Kristus<br/>pada Allah dan insan,<br/>S''lalu suplai limpah Kristus,<br/>Dia-lah kurban bagi-Nya.<br/>',NULL,63690,2);
INSERT INTO stanza VALUES('I659','2','Israel mempersembahkan<br/>hasil tanah nan limpah,<br/>Kita pun layak sembahkan<br/>k''limpahan anug''rah-Nya.<br/>',NULL,63691,3);
INSERT INTO stanza VALUES('I659','3','Kristus, tanah permai kita,<br/>harus kita kelola,<br/>Tuai Dia limpah ruah,<br/>bagi nikmat bersama.<br/>',NULL,63692,4);
INSERT INTO stanza VALUES('I659','4','Pegang Kristus, tumbuh besar,<br/>berfungsi tiap anggota,<br/>T''rima Kristus, suplai Kristus,<br/>melayani Tubuh-Nya.<br/>',NULL,63693,5);
INSERT INTO stanza VALUES('I659','5','S''kutu, saksi, ''layan sabda,<br/>aneka pelayanan,<br/>Harus memamerkan Kristus,<br/>suplaikan k''limpahan-Nya.<br/>',NULL,63694,6);
INSERT INTO stanza VALUES('I660','1','Kini waktu tak panjang,<br/>pelancong seg''ra pulang,<br/>Terangkat ke angkasa,<br/>jumpa Raja semesta,<br/>Rajinlah senantiasa,<br/>sampai kedatangan-Nya.<br/>',NULL,63695,1);
INSERT INTO stanza VALUES('I660','2','Bekerja dengan rajin,<br/>tak pernah takut letih,<br/>Pikul salib tiap hari,<br/>tempuh sengsara b''rani,<br/>Setia melayani, b''lum pulang,<br/>tak berhenti.<br/>',NULL,63696,2);
INSERT INTO stanza VALUES('I660','3','Rajin tumpas roh jahat,<br/>hancurkan kegelapan,<br/>Dalam mara t''rus menang,<br/>tak undur seb''lum tent''ram,<br/>Siang malam sandar doa,<br/>teguh di medan perang.<br/>',NULL,63697,3);
INSERT INTO stanza VALUES('I660','4','Waktu lewat p''ri kilat,<br/>air mata sg''ra terseka,<br/>Moga Tuhan menjaga,<br/>ku s''lalu dengar p''rintah,<br/>Sambil berjaga-jaga,<br/>hingga Dia datang pula.<br/>',NULL,63698,4);
INSERT INTO stanza VALUES('I660','5','Siaga, meski terancam,<br/>siaga, meski terhina,<br/>Siaga, hingga ku dapat<br/>berkata pada Tuhan:<br/>"Tuhan datanglah seg''ra!<br/>Tuhan datanglah s''karang!"<br/>',NULL,63699,5);
INSERT INTO stanza VALUES('I661','1','Kerja, malam sg''ra tiba,<br/>mumpung pagi hari;<br/>Bekerja saat segar,<br/>muda, perkasa.<br/>Kerja, saat hari c''rah,<br/>bekerja di ladang;<br/>Kerja, malam sg''ra tiba,<br/>tinggalkan ladang.<br/>',NULL,63700,1);
INSERT INTO stanza VALUES('I661','2','Kerja, malam sg''ra tiba,<br/>mumpung hari siang;<br/>Kerja, berjerih-lelah,<br/>sejenak saja.<br/>Tiap waktu yang lewat,<br/>bawa hasil limpah;<br/>Kerja, malam sg''ra tiba,<br/>waktu perhentian.<br/>',NULL,63701,2);
INSERT INTO stanza VALUES('I661','3','Kerja, malam sg''ra tiba,<br/>mumpung waktu ada;<br/>Surya terbit, terbenam,<br/>lalu d''ngan cepat.<br/>Hari-hari terakhir,<br/>segera ''kan lewat;<br/>Kerja, malam sg''ra tiba,<br/>tegak depan-Nya.<br/>',NULL,63702,3);
INSERT INTO stanza VALUES('I662','1','Injil mulia sebar luas,<br/>ialah aliran hayat;<br/>Oleh kesaksian hidup,<br/>orang dosa selamat.<br/>',NULL,63703,1);
INSERT INTO stanza VALUES('I662','chorus','Ku alirkan arus hayat,<br/>agar hayat-Mu nyata;<br/>Lewat aku wadah hidup,<br/>roh orang lain hiduplah.<br/>',NULL,63704,2);
INSERT INTO stanza VALUES('I662','2','Saksi hayat menaklukkan,<br/>hingga orang percaya;<br/>Arus hayat ''ngalir suplai,<br/>orang terima Tuhan.<br/>',NULL,63705,3);
INSERT INTO stanza VALUES('I662','3','S''lalu tinggal dalam Tuhan,<br/>jadi ranting yang berbuah;<br/>Arus hayat dari batin,<br/>salur Kristus ke yang lain.<br/>',NULL,63706,4);
INSERT INTO stanza VALUES('I662','4','Hidup ialah pemb''ritaan,<br/>kenalkan diri Kristus;<br/>Tidak saja b''rita, doktrin,<br/>terlebih ''nabur benih.<br/>',NULL,63707,5);
INSERT INTO stanza VALUES('I663','1','Hai, kaum S''rani, pergi ke ujung bumi!<br/>Wartakanlah Allah penuh kasih;<br/>Biar s''mua paham, Yesus g''napkan tebusan,<br/>Dia tak rela satu pun binasa.<br/>',NULL,63708,1);
INSERT INTO stanza VALUES('I663','chorus','Wartakanlah sg''ra kabar suka!<br/>Wartakan Yesus tolong orang dosa!<br/>',NULL,63709,2);
INSERT INTO stanza VALUES('I663','2','Tengok, banyak orang dosa yang sesat,<br/>t''rus terikat jadi budak Iblis;<br/>Tiada yang b''ri ta''u tebusan t''lah genap,<br/>Yesus menang, bangkit dari mati.<br/>',NULL,63710,3);
INSERT INTO stanza VALUES('I663','3','Yesus tolong manusia lepas dosa,<br/>benih Adam mati dalam Yesus,<br/>Kita harus maju tanpalah takut,<br/>bawa orang dosa pada Yesus.<br/>',NULL,63711,4);
INSERT INTO stanza VALUES('I663','4','Mari! Mari semua bangsa di dunia,<br/>kabarkanlah kurnia-Nya yang jaya,<br/>Biar s''mua jelas, Allah jadi manusia,<br/>b''rikan hayat, rela korban jiwa.<br/>',NULL,63712,5);
INSERT INTO stanza VALUES('I663','5','Jangan cegah anakmu mengembara,<br/>demi Injil persembahkan harta!<br/>Berdoa ''tiasa, mohon Allah b''ri berkat,<br/>s''mua korbanmu, Dia balas berlipat.<br/>',NULL,63713,6);
INSERT INTO stanza VALUES('I663','6','Harus ingat, Yesus ''kan datang pula,<br/>waktu lewat, tugas tak terkejar,<br/>Jangan kar''na kamu tidak bergairah,<br/>ada orang tidak dapat s''lamat.<br/>',NULL,63714,7);
INSERT INTO stanza VALUES('I664','1','Kabarkanlah Injil! S''lamatkan jiwa!<br/>Tengoklah banyak orang binasa!<br/>''Nyatakan simpati, amalkan harta,<br/>Ulurkan tanganmu s''karang juga!<br/>',NULL,63715,1);
INSERT INTO stanza VALUES('I664','chorus','Kabarkanlah Injil! S''lamatkan jiwa!<br/>Tegakah nampak m''reka binasa<br/>',NULL,63716,2);
INSERT INTO stanza VALUES('I665','1','Ke dunia suplai Kristus,<br/>tak hanya dengan kata,<br/>Lewat hidup salur Kristus,<br/>ke orang yang kasihan.<br/>',NULL,63717,1);
INSERT INTO stanza VALUES('I665','chorus','Ke dunia, suplai Kristus,<br/>Dia tampil di hidupmu.<br/>Hidup sandar, salur Kristus,<br/>orang dapatkan Kristus.<br/>',NULL,63718,2);
INSERT INTO stanza VALUES('I665','2','Ke dunia suplai Kristus -<br/>Tuhan yang kau miliki;<br/>Salurkan pada famili,<br/>jadi sukses, limpahnya.<br/>',NULL,63719,3);
INSERT INTO stanza VALUES('I665','3','Ke dunia suplai Kristus -<br/>Kristus yang kau nikmati;<br/>Salurkan kepada teman,<br/>jadi megah, berkatnya.<br/>',NULL,63720,4);
INSERT INTO stanza VALUES('I665','4','Ke dunia suplai Kristus,<br/>Dia hayat dan s''galamu,<br/>Salurkan pada s''mua orang,<br/>orang nikmat limpah-Nya.<br/>',NULL,63721,5);
INSERT INTO stanza VALUES('I666','1','Kumpulkan bahan bagi rumah-Nya;<br/>Bawa orang berpaling pada-Nya;<br/>Bimbing yang dosa, lepas binasa;<br/>Cari yang sesat balik ke rumah.<br/>',NULL,63722,1);
INSERT INTO stanza VALUES('I666','2','Kumpulkan bahan bagi rumah-Nya;<br/>Tolong orang dari jerat dunia;<br/>Lepas gelap dan tipuan setan;<br/>Lepas perangkap dan muslihatnya.<br/>',NULL,63723,2);
INSERT INTO stanza VALUES('I666','3','Kumpulkan bahan bagi rumah-Nya;<br/>Bimbing yang terlantar ke ribaan-Nya;<br/>Kalahkan Iblis - seteru Allah;<br/>Orak tawanan, paling ke Tuhan.<br/>',NULL,63724,3);
INSERT INTO stanza VALUES('I666','4','Kumpulkan bahan bagi rumah-Nya;<br/>Tegak di tumpuan, Kristus tersiar;<br/>Segenap umat seroh sejiwa;<br/>Tiup nafiri Injil di tiap tempat.<br/>',NULL,63725,4);
INSERT INTO stanza VALUES('I667','1','Fajar kita ''nabur,<br/>siang kita ''nabur,<br/>senja ''nabur pula,<br/>kasih sayang Hu;<br/>Tunggu hari masak,<br/>dan masa tuaian,<br/>dengan riang gembira,<br/>angkut tuaian.<br/>',NULL,63726,1);
INSERT INTO stanza VALUES('I667','chorus','Angkut tuaian!<br/>Angkut tuaian!<br/>Dengan riang gembira,<br/>angkut tuaian!<br/>Angkut tuaian!<br/>Angkut tuaian!<br/>Dengan riang gembira,<br/>angkut tuaian!<br/>',NULL,63727,2);
INSERT INTO stanza VALUES('I667','2','Jangan pilih waktu,<br/>terik atau mendung,<br/>Biar angin menderu,<br/>awan mengepung;<br/>Sejenaklah saja,<br/>tuaian ''kan masak,<br/>Dengan riang gembira,<br/>angkut tuaian.<br/>',NULL,63728,3);
INSERT INTO stanza VALUES('I667','3','Bangkitlah segera,<br/>walau mata ''linang,<br/>Berkorban bagi-Nya,<br/>takkan menyesal;<br/>Tangisan ''kan lewat,<br/>sambutan meriah,<br/>Dengan riang gembira,<br/>angkut tuaian.<br/>',NULL,63729,4);
INSERT INTO stanza VALUES('I668','1','Bolehkah d''ngan hampa tangan,<br/>ku pulang jumpa Tuhan?<br/>Tak pernah kerja buat Tuhan,<br/>tiada yang ku sembahkan.<br/>',NULL,63730,1);
INSERT INTO stanza VALUES('I668','chorus','Bolehkah d''ngan hampa tangan,<br/>ku pulang jumpa Tuhan?<br/>D''ngan tak pernah pimpin<br/>orang menghadap pada Tuhan?<br/>',NULL,63731,2);
INSERT INTO stanza VALUES('I668','2','Kini ku tak kuatir ''kan maut,<br/>kar''na ku t''lah ditebus;<br/>Bila ingat tangan hampa,<br/>hatiku seg''ra duka!<br/>',NULL,63732,3);
INSERT INTO stanza VALUES('I668','3','Bila kini dapat lepas,<br/>s''gala dosa yang ku buat,<br/>S''gala milik ku sembahkan,<br/>dengan senang pada-Nya.<br/>',NULL,63733,4);
INSERT INTO stanza VALUES('I668','4','Biar umat S''rani siang malam,<br/>bekerja giat untuk-Nya,<br/>Seb''lum ajal kita tiba,<br/>giat selamatkan jiwa.<br/>',NULL,63734,5);
INSERT INTO stanza VALUES('I669','1','Juru-s''lamat cinta kepada aku,<br/>Serta berdoa bagiku selalu;<br/>Teman, s''mua kabur, Dia makin dekat aku,<br/>Moga Dia jadi Juru-selamatmu.<br/>',NULL,63735,1);
INSERT INTO stanza VALUES('I669','chorus','Bagimu doaku!<br/>Bagimu doaku!<br/>Moga Dia jadi Juru-selamatmu!<br/>',NULL,63736,2);
INSERT INTO stanza VALUES('I669','2','Bapa Allah semayam dalam terang,<br/>Beri harapan yang pasti dan kekal;<br/>Dia segera jemputku berserta-Nya,<br/>Moga kamu pun bersamaku juga!<br/>',NULL,63737,3);
INSERT INTO stanza VALUES('I669','3','Girang hatiku p''ri ombak menderu,<br/>Kar''na Dia telah pikul s''mua dosaku;<br/>Bahkan kini Dia tetap hidup dalamku,<br/>Moga girang ini m''limpah padamu!<br/>',NULL,63738,4);
INSERT INTO stanza VALUES('I669','4','Damai hatiku tenang p''ri air danau,<br/>Damai yang ajaib, teman-teman tak ta''u;<br/>Hanya Tuhan Yesus sumber damai ini,<br/>Moga damai ini pun kau alami!<br/>',NULL,63739,5);
INSERT INTO stanza VALUES('I669','5','Set''lah s''lamat b''ri tahu lain orang,<br/>Bagaimana kau dis''lamatkan Tuhan;.<br/>Doakanlah agar mereka selamat,<br/>Doamu pasti didengarkan Tuhan!<br/>',NULL,63740,6);
INSERT INTO stanza VALUES('I670','1','Bersiaplah jumpa Allah!<br/>Bersiaplah jumpa Allah!<br/>Bertobat dan percaya,<br/>jangan lambat!<br/>Bertobat dan percayalah,<br/>t''rima s''lamat!<br/>',NULL,63741,1);
INSERT INTO stanza VALUES('I670','2','Bersiaplah jumpa Allah!<br/>Bersiaplah jumpa Allah!<br/>Dosamu dihapuskan,<br/>bersiap seg''ra!<br/>Jumpa Allah, dosa hapus,<br/>jadi baru!<br/>',NULL,63742,2);
INSERT INTO stanza VALUES('I670','3','Bersiaplah jumpa Allah!<br/>Bersiaplah jumpa Allah!<br/>Sembahkan jiwa raga,<br/>jangan lambat!<br/>Sembahkanlah jiwa raga,<br/>s''mua bagi-Nya!<br/>',NULL,63743,3);
INSERT INTO stanza VALUES('I671','1','Tebusan t''lah Kristus g''napkan,<br/>Juru-s''lamat yang ajaib!<br/>Kini aku t''lah ditebus,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63744,1);
INSERT INTO stanza VALUES('I671','chorus','Juru-s''lamat yang ajaib,<br/>Yesus-ku, Yesus-ku!<br/>Juru-s''lamat yang ajaib,<br/>Yesus, Tuhan-ku!<br/>',NULL,63745,2);
INSERT INTO stanza VALUES('I671','2','Darah-Nya cuci dosaku<br/>Juru-s''lamat yang ajaib!<br/>Ku berdamai dengan Allah,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63746,3);
INSERT INTO stanza VALUES('I671','3','Dia cuci s''gala najisku,<br/>Juru-s''lamat yang ajaib!<br/>Kini m''raja di hatiku,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63747,4);
INSERT INTO stanza VALUES('I671','4','Setiap waktu Dia berhampir,<br/>Juru-s''lamat yang ajaib!<br/>Jaga biar ku setia hati,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63748,5);
INSERT INTO stanza VALUES('I671','5','Daya menang t''rus dib''rikan,<br/>Juru-s''lamat yang ajaib!<br/>Biar ku s''lalu menang perang,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63749,6);
INSERT INTO stanza VALUES('I671','6','Ku persembahkan diriku,<br/>Juru-s''lamat yang ajaib!<br/>Nafsu dunia tiada bagian,<br/>Juru-s''lamat yang ajaib!<br/>',NULL,63750,7);
INSERT INTO stanza VALUES('I672','1','Satu hari, pujian riuh di surga,<br/>satu hari, dosa cemar insan.<br/>Yesus terlahir oleh anak dara,<br/>hidup di dunia, tampilkan Allah!<br/>',NULL,63751,1);
INSERT INTO stanza VALUES('I672','chorus','Lahir, cintaku; wafat,<br/>tebusku; dikubur,<br/>angkut semua dosaku;<br/>Bangkit, beri kurnia;<br/>pun benarkanku;<br/>Dia ''kan datang,<br/>jemputku pulang.<br/>',NULL,63752,2);
INSERT INTO stanza VALUES('I672','2','Satu hari, Dia d''rita di Golgota,<br/>di kayu salib, terpancang pentang,<br/>Serba sengsara, tertindas, terluka,<br/>jadi Penebus, menanggung dosa!<br/>',NULL,63753,3);
INSERT INTO stanza VALUES('I672','3','Satu hari, Dia sendirian di taman,<br/>damai sentosa, lepas s''mua d''rita,<br/>Datanglah malak, rondai makam-Nya,<br/>tiada harapan, Dia-lah harapan!<br/>',NULL,63754,4);
INSERT INTO stanza VALUES('I672','4','Satu hari, makam tiada daya,<br/>goleklah batu penutup liang,<br/>Dia t''lah bangkit, kuasa maut terpatah,<br/>jadi Tuhan-ku, naik ke surga.<br/>',NULL,63755,5);
INSERT INTO stanza VALUES('I672','5','Satu hari, nafiri siar balik-Nya,<br/>mulia terpancar bulat di surga,<br/>Saat ajaib, Kekasihku tiba,<br/>Penolong mulia, Yesus-ku Tuhan.<br/>',NULL,63756,6);
INSERT INTO stanza VALUES('I673','1','Juru-s''lamat lahir dalam malaf,<br/>jadi manusia, d''rita sengsara;<br/>Sungguh heran, Dia patut ku puji!<br/>Dia mencari aku!<br/>',NULL,63757,1);
INSERT INTO stanza VALUES('I673','chorus','Dia mencari aku!<br/>Dia mencari aku!<br/>Sungguh heran,<br/>Dia patut ku puji!<br/>Dia mencari aku!<br/>',NULL,63758,2);
INSERT INTO stanza VALUES('I673','2','Juru-s''lamatku mati di salib,<br/>bayar hutangku, membebaskanku;<br/>Sungguh heran, mengapa demikian?<br/>Dia mati bagiku!<br/>',NULL,63759,3);
INSERT INTO stanza VALUES('I673','3','Juru-s''lamat s''lama tak ubah,<br/>ku berk''lana Dia panggilku balik,<br/>Meski ku tolak Dia tetap kasih,<br/>Dia panggil ku balik!<br/>',NULL,63760,4);
INSERT INTO stanza VALUES('I673','4','Juru-s''lamat jemput umat-Nya,<br/>inilah janji yang penuh harap,<br/>Ku nampak Dia turun dari surga,<br/>datang menyambutku!<br/>',NULL,63761,5);
INSERT INTO stanza VALUES('I674','1','Tabib agung, akrab, mesra,<br/>beri simpatik, Yesus;<br/>Luka dosa, Dia sembuhkan,<br/>datanglah pada Yesus!<br/>',NULL,63762,1);
INSERT INTO stanza VALUES('I674','chorus','Dia tersalib bagimu,<br/>Dia menanggung dosamu,<br/>Dia tabib, sembuhkanmu,<br/>datang pada Yesus.<br/>',NULL,63763,2);
INSERT INTO stanza VALUES('I674','2','Dosa banyak, Dia b''ri ampun,<br/>bila mau hampir Yesus!<br/>Hati gundah, Dia b''ri tent''ram,<br/>datanglah pada Yesus!<br/>',NULL,63764,3);
INSERT INTO stanza VALUES('I674','3','Tabiat jahat, Dia lenyapkan,<br/>Jurusembuhmu, Yesus!<br/>Keluh kesah, Dia b''ri hibur,<br/>datanglah pada Yesus!<br/>',NULL,63765,4);
INSERT INTO stanza VALUES('I674','4','Duka rana, hidup hambar,<br/>datanglah pada Yesus!<br/>Dia berikan air hidup,<br/>datanglah pada Yesus!<br/>',NULL,63766,5);
INSERT INTO stanza VALUES('I674','5','Kini aku telah sembuh,<br/>kar''na ku t''rima Yesus!<br/>Mulia bagi Domba kudus,<br/>aku percaya Yesus!<br/>',NULL,63767,6);
INSERT INTO stanza VALUES('I674','6','Ku cinta pada Tuhan-ku,<br/>nama terkasih, Yesus!<br/>Nama-Nya tunjang pun hibur,<br/>nama terindah, Yesus!<br/>',NULL,63768,7);
INSERT INTO stanza VALUES('I674','7','Saat ku t''rangkat depan-Nya,<br/>pandang wajah mulia-Nya;<br/>Dalam mulia ku memuja,<br/>Yesus, maha mustika!<br/>',NULL,63769,8);
INSERT INTO stanza VALUES('I675','1','B''rita mulia, amat manis,<br/>percaya saja;<br/>Dulu, kini, selamanya,<br/>Yesus tak ubah.<br/>Sembuhkan orang yang sakit,<br/>tolong yang dosa,<br/>Hibur duka, teduh badai,<br/>mulia bagi-Nya!<br/>',NULL,63770,1);
INSERT INTO stanza VALUES('I675','chorus','Dulu, kini, hingga kekal,<br/>Yesus tak ubah,<br/>Langit, bumi s''mua berubah,<br/>Yesus tak ubah!<br/>Yesus tak ubah!<br/>Yesus tak ubah!<br/>Langit, bumi s''mua berubah,<br/>Yesus tak ubah!<br/>',NULL,63771,2);
INSERT INTO stanza VALUES('I675','2','Yesus sobat orang dosa,<br/>kau dicari-Nya,<br/>Mengaku dosa depan-Nya,<br/>kau dit''rima-Nya;<br/>Dia pasti bertutur indah,<br/>p''ri masa silam,<br/>"Dosamu t''lah diampuni,<br/>pergi d''ngan damai."<br/>',NULL,63772,3);
INSERT INTO stanza VALUES('I675','3','Dia sembuhkan orang sakit<br/>dengan kuasa-Nya;<br/>Hingga kini tetap sama,<br/>t''rima firman-Nya;<br/>Dia sembuhkan perempuan<br/>yang menjamah-Nya;<br/>Kalau kita mau percaya,<br/>t''rima kurnia-Nya.<br/>',NULL,63773,4);
INSERT INTO stanza VALUES('I675','4','Pernah iringi murid-Nya,<br/>turun ke Emaus;<br/>Sepanjang hidup,<br/>Dia s''lalu beserta kita.<br/>Tak lama, Dia seg''ra datang,<br/>kita berjumpa,<br/>Tuhan tetap sama s''perti<br/>saat terangkat.<br/>',NULL,63774,5);
INSERT INTO stanza VALUES('I676','1','Ku dengar b''rita indah:<br/>Dia tolong manusia!<br/>Sebarkan ini b''rita:<br/>Dia tolong manusia!<br/>Pergilah ke s''mua tempat,<br/>jangan takut derita,<br/>B''ritakan ke s''mua bangsa:<br/>Dia tolong manusia!<br/>',NULL,63775,1);
INSERT INTO stanza VALUES('I676','2','Siarkan ke kaum papa:<br/>Dia tolong manusia!<br/>Siarkan ke kaum dosa:<br/>Dia tolong manusia!<br/>Genap benua bergita,<br/>genap lautan bergema,<br/>Genap bumi siarkan:<br/>Dia tolong manusia!<br/>',NULL,63776,2);
INSERT INTO stanza VALUES('I676','3','Salib-Nya menyatakan:<br/>Dia tolong manusia!<br/>Darah-Nya t''rus bersabda,<br/>Dia tolong manusia!<br/>Dia mati, orang bebas;<br/>Dia bangkit, hayat ada,<br/>Naik surga, ditinggikan,<br/>Dia tolong manusia!<br/>',NULL,63777,3);
INSERT INTO stanza VALUES('I676','4','Inilah Injil benar:<br/>Dia tolong manusia!<br/>Inilah p''lipur duka:<br/>Dia tolong manusia!<br/>Yang lelah dapat sabat;<br/>yang duka dapat senang,<br/>Yang dosa jangan bimbang,<br/>Dia tolong manusia!<br/>',NULL,63778,4);
INSERT INTO stanza VALUES('I676','5','B''ritakan Injil ini:<br/>Dia tolong manusia!<br/>Biar semua orang paham:<br/>Dia tolong manusia!<br/>Berlimpah kurnia Allah,<br/>yang dosa dapat s''lamat,<br/>S''lamanya ku bersorak:<br/>Dia tolong manusia!<br/>',NULL,63779,5);
INSERT INTO stanza VALUES('I677','1','Rahmani dan cinta, pun lemah lembut,<br/>Bagi kaum berdosa, rela terbunuh;<br/>Mencari yang sesat, darah tercucur,<br/>''Nilah Kristus Yesus, apa sikapmu?<br/>',NULL,63780,1);
INSERT INTO stanza VALUES('I678','1','Selain Tuhan Yesus, selain Tuhan Yesus,<br/>Tiada kes''lamatan, tiada kes''lamatan;<br/>Kar''na di dalam dunia, kar''na di dalam dunia,<br/>Tiada nama lainnya yang bisa b''ri s''lamat.<br/>',NULL,63781,1);
INSERT INTO stanza VALUES('I679','1','Berbuat amal, baik,<br/>tak dapat s''lamatkanku,<br/>Meski banyak berjasa,<br/>hanya tenar namaku,<br/>hati tetap jahat.<br/>',NULL,63782,1);
INSERT INTO stanza VALUES('I679','chorus','Yesus susah untukku!<br/>Yesus tanggung dosaku!<br/>S''karang Yesus b''ri berkat!<br/>Biarku dapat s''lamat!<br/>',NULL,63783,2);
INSERT INTO stanza VALUES('I679','2','Tangis tak berhasil<br/>hibur hati yang pedih,<br/>Meski air mata habis,<br/>dosaku takkan bersih,<br/>Hati makin pedih!<br/>',NULL,63784,3);
INSERT INTO stanza VALUES('I679','3','Tunggu tiada guna,<br/>dosaku makin banyak,<br/>Diriku makin c''laka,<br/>tunggu masuk neraka,<br/>Aku makin c''laka!<br/>',NULL,63785,4);
INSERT INTO stanza VALUES('I679','4','Iman yang s''lamatkan,<br/>kar''na Yesus berdarah,<br/>Cucikan s''gala nista,<br/>ku percaya pada-Nya,<br/>Dapat hidup kekal!<br/>',NULL,63786,5);
INSERT INTO stanza VALUES('I680','1','Kasih ajaib nyata di Golgota!<br/>Takhta di surga ditinggalkan;<br/>Rela jadi miskin,<br/>t''rima sengsara,<br/>s''panjang jalan susah bagiku.<br/>',NULL,63787,1);
INSERT INTO stanza VALUES('I680','chorus','Dia menempuh Golgota bagiku,<br/>ya, bagiku!<br/>Ya, bagiku!<br/>Dia menempuh Golgota bagiku,<br/>demi s''lamatkanku!<br/>',NULL,63788,2);
INSERT INTO stanza VALUES('I680','2','Oh, betapa kejam, Tuhan terpancang!<br/>Mahkota duri, paku, hunjam;<br/>Tubuh penuh bilur,<br/>darah tercucur,<br/>s''mua kar''na Dia mengasihiku!<br/>',NULL,63789,3);
INSERT INTO stanza VALUES('I680','3','Oh, langit pun gelap, Allah hukum Dia!<br/>Tuntutan murka-Nya membakar;<br/>Karena Dia tanggung semua dosaku,<br/>Allah menghukum-Nya gantiku!<br/>',NULL,63790,4);
INSERT INTO stanza VALUES('I680','4','Dulu kami tak mengenal kurnia-Nya!<br/>Tapi, kini kami t''lah nampak;<br/>Bahkan dengar:<br/>"Ku berdarah untukmu",<br/>baru ta''u Dia t''lah menebusku!<br/>',NULL,63791,5);
INSERT INTO stanza VALUES('I681','1','Aduh! Penolong disalib,<br/>tangan, kaki pedih;<br/>Kepala tertusuk duri,<br/>tubuh tercemeti.<br/>',NULL,63792,1);
INSERT INTO stanza VALUES('I681','chorus','Di salib, ku nampak sinar kurnia Tuhan,<br/>pikulan dosaku lepaslah!<br/>Saat ku percaya, mataku terbuka,<br/>hidupku s''lamanya gembira.<br/>',NULL,63793,2);
INSERT INTO stanza VALUES('I681','2','Di salib Dia tanggung keji,<br/>siksaku Dia ganti;<br/>Belas kasih tak terperi,<br/>cinta-Nya tertinggi!<br/>',NULL,63794,3);
INSERT INTO stanza VALUES('I681','3','Allah t''lah timpakan<br/>dosa pada diri Yesus;<br/>Hingga surya bersembunyi,<br/>gelaplah di bumi.<br/>',NULL,63795,4);
INSERT INTO stanza VALUES('I681','4','Tuhan wafat, tirai terb''lah,<br/>terbukalah jalan;<br/>Kuburan saleh terbuka,<br/>maut tak berdaya.<br/>',NULL,63796,5);
INSERT INTO stanza VALUES('I681','5','Aduh, lambung-Nya ditombak,<br/>darah, air teralir;<br/>B''riku hayat, hindar maut,<br/>dosaku terhapus.<br/>',NULL,63797,6);
INSERT INTO stanza VALUES('I681','6','Seb''lum mati Tuhan bers''ru:<br/>"Karya sudah genap!"<br/>Dengar suara Tuhan ini,<br/>hatiku memuji.<br/>',NULL,63798,7);
INSERT INTO stanza VALUES('I682','1','Suara-Mu ku dengar,<br/>katakan ku lemah,<br/>Jika tak percaya,<br/>tak ''kan lepas dosa.<br/>',NULL,63799,1);
INSERT INTO stanza VALUES('I682','chorus','Semua hutangku,<br/>Tuhan lunaskan;<br/>Meski aku berdosa,<br/>Tuhan b''ri ampunan.<br/>',NULL,63800,2);
INSERT INTO stanza VALUES('I682','2','Tuhan, kini ku ta''u,<br/>hanya Kau berkuasa,<br/>Menghapus s''mua nista,<br/>jadikan ku kuat.<br/>',NULL,63801,3);
INSERT INTO stanza VALUES('I682','3','Aku tak berjasa,<br/>t''rima kurnia Tuhan;<br/>Tapi Kau p''nuh cinta,<br/>untukku Kau datang.<br/>',NULL,63802,4);
INSERT INTO stanza VALUES('I682','4','Meski ajal tiba,<br/>aku tidak gentar;<br/>Kar''na Kau lunaskan,<br/>semua hutang dosa.<br/>',NULL,63803,5);
INSERT INTO stanza VALUES('I682','5','K''lak di depan Allah,<br/>ku takkan dihukum;<br/>Kar''na Dia t''lah wafat,<br/>tanggung hukumanku.<br/>',NULL,63804,6);
INSERT INTO stanza VALUES('I683','1','Turun surga demi cinta,<br/>menjelma jadi manusia,<br/>Cerca, cambuk, olok, hina,<br/>akhirnya Dia disaliblah.<br/>',NULL,63805,1);
INSERT INTO stanza VALUES('I683','chorus','Yesus mati buatku!<br/>Yesus mati buatku!<br/>Buatku, buatku,<br/>buatku, buatku!<br/>Yesus mati buatku!<br/>',NULL,63806,2);
INSERT INTO stanza VALUES('I684','1','Ingin dosa terhapus?<br/>Hanya oleh darah Yesus!<br/>Ingin pulih sempurna?<br/>Hanya oleh darah Yesus.<br/>',NULL,63807,1);
INSERT INTO stanza VALUES('I684','chorus','O, darah yang ajaib!<br/>Basuh aku bersih!<br/>Tiada sumber lain:<br/>Hanya oleh darah Yesus.<br/>',NULL,63808,2);
INSERT INTO stanza VALUES('I684','2','Untuk suci ku tahu,<br/>hanya oleh darah Yesus!<br/>Untuk ampun dosaku,<br/>hanya oleh darah Yesus!<br/>',NULL,63809,3);
INSERT INTO stanza VALUES('I684','3','Untuk hapus dosaku,<br/>hanya oleh darah Yesus!<br/>Untuk pembenaranku,<br/>hanya oleh darah Yesus!<br/>',NULL,63810,4);
INSERT INTO stanza VALUES('I684','4','Kudus, keadilanku,<br/>hanya oleh darah Yesus!<br/>Harapan, sentosaku,<br/>hanya oleh darah Yesus.<br/>',NULL,63811,5);
INSERT INTO stanza VALUES('I685','1','Yesus Kristus-lah Domba Allah,<br/>telah mati menanggung dosa,<br/>Allah nampak akan darah-Nya,<br/>Allah lampaui, kau selamat.<br/>',NULL,63812,1);
INSERT INTO stanza VALUES('I685','chorus','Bila Ku nampak darah Domba-Ku,<br/>tentu Ku lewat,<br/>hingga kau selamat selalu.<br/>',NULL,63813,2);
INSERT INTO stanza VALUES('I685','2','Dosamu meski tak terhitung,<br/>ada Yesus sedia tanggung,<br/>Dalam darah-Nya kau bernaung,<br/>Allah lampaui, kau terampun.<br/>',NULL,63814,3);
INSERT INTO stanza VALUES('I685','3','Hukuman Allah seg''ra tiba,<br/>tak seorang pun ''kan terhindar,<br/>Hanya berlindung dalam darah,<br/>Allah lampaui, kau bebaslah.<br/>',NULL,63815,4);
INSERT INTO stanza VALUES('I685','4','Oh! Berlimpah belas kasih-Nya!<br/>Alangkah indah karunia-Nya!<br/>Demi darah-Nya kau sentosa,<br/>Allah lampaui, kau pujilah!<br/>',NULL,63816,5);
INSERT INTO stanza VALUES('I686','1','Satu sumber ''ngalir luap, dari s''la rusuk-Nya,<br/>Orang dosa, asal datang, terbasuh cemarnya.<br/>Terbasuh cemarnya, terbasuh cemarnya.<br/>Orang dosa, asal datang, terbasuh cemarnya.<br/>',NULL,63817,1);
INSERT INTO stanza VALUES('I686','2','Penyamun sama tersalib, nampak khasiat ini,<br/>Dosaku tak lebih s''dikit, namun jadi bersih.<br/>Namun jadi bersih, namun jadi bersih.<br/>Dosaku tak lebih s''dikit, namun jadi bersih.<br/>',NULL,63818,2);
INSERT INTO stanza VALUES('I686','3','Darah Domba tersembelih, kuasanya abadi,<br/>Dibersihkan, kaum terpilih, jauh nista najis.<br/>Jauh nista najis, jauh nista najis.<br/>Dibersihkan, kaum terpilih, jauh nista najis.<br/>',NULL,63819,3);
INSERT INTO stanza VALUES('I686','4','Sumber ini terbukalah, kar''na Kau terluka,<br/>Kasih tebusan ku puji, tak henti s''lamanya.<br/>Tak henti s''lamanya, tak henti s''lamanya.<br/>Kasih tebusan ku puji, tak henti s''lamanya.<br/>',NULL,63820,4);
INSERT INTO stanza VALUES('I686','5','Jelang ajal, mulut lidah, diam s''ribu bah''sa,<br/>Suara bangkit ku nyanyikan, ''tas kuasa tebusan.<br/>''Tas kuasa tebusan, ''tas kuasa tebusan.<br/>Suara bangkit ku nyanyikan, ''tas kuasa tebusan.<br/>',NULL,63821,5);
INSERT INTO stanza VALUES('I687','1','Maukah kau bebas dari s''mua beban?<br/>Darah Yesus-lah yang berkuasa.<br/>Maukah kau luput dari hukuman?<br/>Kuasa ajaib dalam darah.<br/>',NULL,63822,1);
INSERT INTO stanza VALUES('I687','chorus','Ada kuasa dalam darah-Nya,<br/>darah Domba Allah!<br/>Ada kuasa, kuasa yang ajaib,<br/>dalam darah Domba Allah!<br/>',NULL,63823,2);
INSERT INTO stanza VALUES('I687','2','Maukah kau tanggalkan cemar dosa?<br/>Darah Yesus-lah yang berkuasa.<br/>Maukah kau tanggalkan nafsu nista?<br/>Kuasa ajaib dalam darah.<br/>',NULL,63824,3);
INSERT INTO stanza VALUES('I687','3','Maukah kau bersih seputih salju?<br/>Darah Yesus-lah yang berkuasa.<br/>Maukah kau suci sep''ri Tuhan-mu?<br/>Kuasa ajaib dalam darah.<br/>',NULL,63825,4);
INSERT INTO stanza VALUES('I687','4','Maukah kau t''rima s''lamat sempurna?<br/>Darah Yesus-lah yang berkuasa.<br/>Maukah kau nikmat bahagia kekal?<br/>Kuasa ajaib dalam darah.<br/>',NULL,63826,5);
INSERT INTO stanza VALUES('I687','5','Demikian s''mua dosa tertumpas,<br/>oleh darah-Nya yang berkuasa.<br/>Bersandarlah pada darah Domba,<br/>ajaib, indah dan berkuasa.<br/>',NULL,63827,6);
INSERT INTO stanza VALUES('I688','1','Sudahkah kau mohon pada Tuhan-mu,<br/>darah-Nya mencuci dosamu?<br/>Sudahkah kau percaya Tuhan Yesus,<br/>menerima Dia di hatimu?<br/>',NULL,63828,1);
INSERT INTO stanza VALUES('I688','chorus','Sudahkah s''mua dosa tercuci dengan darah Domba?<br/>Sudahkah jubahmu seputih salju?<br/>Sudah bersihkah s''mua dosamu?<br/>',NULL,63829,2);
INSERT INTO stanza VALUES('I688','2','Sudahkah kau menerima kurnia-Nya?<br/>Ampunan dalam darah Domba?<br/>Sudahkah kau kar''na kematian-Nya,<br/>hatimu menjadi sentosa?<br/>',NULL,63830,3);
INSERT INTO stanza VALUES('I688','3','Sudahkah jubahmu teruci bersih<br/>oleh darah Domba nan suci?<br/>Patutkah terima mahkota mulia,<br/>bila Tuhan-mu datang pula?<br/>',NULL,63831,4);
INSERT INTO stanza VALUES('I688','4','Di salib t''lah tercurah darah Domba,<br/>bagi dirimu yang berdosa;<br/>Jubahmu yang najis jangan dipakai,<br/>cucilah dengan darah Domba.<br/>',NULL,63832,5);
INSERT INTO stanza VALUES('I689','1','Kasih ajaib! Yesus ke dunia,<br/>Kasih ajaib! Yesus terkoyak!<br/>Bagi yang dosa, pikul salib;<br/>Bagiku yang hutang, tumpah darah.<br/>',NULL,63833,1);
INSERT INTO stanza VALUES('I690','1','Kasih ajaib, kurnia besar,<br/>Allah utus Putra;.<br/>Dia yang menanggung hukuman,<br/>mati bagi kita.<br/>Pintu kurnia t''lah terbuka,<br/>tiada lain jalan selamat,<br/>Allah sangat menantikan,<br/>t''rimalah kasih-Nya.<br/>',NULL,63834,1);
INSERT INTO stanza VALUES('I691','1','Suara merdu kurnia,<br/>hibur hati orang,<br/>Surga penuh d''ngan gemanya,<br/>bumi dengar juga.<br/>',NULL,63835,1);
INSERT INTO stanza VALUES('I691','chorus','Keselamatan,<br/>oleh kurnia;<br/>Yesus mati untukku,<br/>tolong ku yang dosa.<br/>',NULL,63836,2);
INSERT INTO stanza VALUES('I691','2','Kurnia dalam Kristus,<br/>limpah tak terkata!<br/>Rampung tebusan untukku,<br/>lepas hamba dosa.<br/>',NULL,63837,3);
INSERT INTO stanza VALUES('I691','3','Kurnia penebusan<br/>memberi ampunan;<br/>Ku dapat pandang wajah-Nya,<br/>nikmat damai surga.<br/>',NULL,63838,4);
INSERT INTO stanza VALUES('I691','4','Kurnia beri hayat,<br/>ku dapat sifat-Nya;<br/>Kekal ku milik nama-Nya,<br/>lepas maut gelap.<br/>',NULL,63839,5);
INSERT INTO stanza VALUES('I692','1','Seorang pejabat datang ke Yesus;<br/>Tanya jalan kes''lamatan dan terang;<br/>D''ngan tegas Tuhan berkata padanya,<br/>"Harus lahir ulang!"<br/>',NULL,63840,1);
INSERT INTO stanza VALUES('I692','chorus','Harus lahir ulang!<br/>Harus lahir ulang!<br/>D''ngan tegas Tuhan berkata padanya,<br/>"Harus lahir ulang!"<br/>',NULL,63841,2);
INSERT INTO stanza VALUES('I692','2','Hai manusia, dengarkan firman ini,<br/>D''ngan khidmat diucapkan Juru-s''lamat,<br/>Jangan meremehkan pesan ilahi,<br/>"Harus lahir ulang!"<br/>',NULL,63842,3);
INSERT INTO stanza VALUES('I692','3','O, siapa ingin masuk kota kudus,<br/>D''ngan kaum tebusan nikmat perhentian,<br/>Dia harus beroleh hidup yang kekal,<br/>"Harus lahir ulang!"<br/>',NULL,63843,4);
INSERT INTO stanza VALUES('I692','4','Dia ditinggikan, yang percaya, hidup,<br/>Roh Kudus mendorong, yang taat, kudus,<br/>Asal kau bertobat, percaya Tuhan,<br/>"Harus lahir ulang!"<br/>',NULL,63844,5);
INSERT INTO stanza VALUES('I693','1','Kristus mengenakan insan,<br/>jadi insan p''ri aku;<br/>Mati tersalib,<br/>aku bebas dari hayat Adam;<br/>Dia bangkit, menjadi Roh,<br/>masuk dan hidup dalamku;<br/>Dia jadi hayatku.<br/>',NULL,63845,1);
INSERT INTO stanza VALUES('I693','chorus','Mulia, mulia, haleluya!<br/>Mulia, mulia, haleluya!<br/>Mulia, mulia, haleluya!<br/>Dia jadi hayatku!<br/>',NULL,63846,2);
INSERT INTO stanza VALUES('I694','1','Tuhan hayat, kebangkitan,<br/>hayat di dalam-Nya;<br/>Demi mati, tumpas Iblis,<br/>kini hidup kekal,<br/>Kini hidup kekal,<br/>kini Dia hidup kekal.<br/>',NULL,63847,1);
INSERT INTO stanza VALUES('I694','2','Mulia, mulia, hayat mulia,<br/>kini t''lah ku dapat!<br/>Gelap, maut, sengat dosa,<br/>kini sudah musnah,<br/>Kini sudah musnah,<br/>kini semua sudah musnah!<br/>',NULL,63848,2);
INSERT INTO stanza VALUES('I695','1','Betapa ajaib, Dia mati buatku!<br/>Aku terhukum, Dia bebaskanku;<br/>Berulang kata-Nya,<br/>"Yang percaya, berpindah ke hidup."<br/>',NULL,63849,1);
INSERT INTO stanza VALUES('I695','chorus','Berita gembira, dengarlah dengar!<br/>Berita gembira, Kristus jelaskan:<br/>"Siapa yang percaya kepada-Ku,<br/>berpindah ke hidup."<br/>',NULL,63850,2);
INSERT INTO stanza VALUES('I695','2','Semua salahku Dia yang tanggung;<br/>Semua hutangku Dia yang pikul;<br/>Siapa yang percaya pada-Nya,<br/>berpindah ke hidup!<br/>',NULL,63851,3);
INSERT INTO stanza VALUES('I695','3','Meski p''nuh dosa, ku t''rima Tuhan;<br/>Meski ku lemah, ku t''rima Roh-Nya;<br/>Teman, ini sungguh berkat mulia!<br/>"Berpindah ke hidup!"<br/>',NULL,63852,4);
INSERT INTO stanza VALUES('I695','4','Walau tak layak, aku tak ragu;<br/>Yang datang pada-Nya tak dibuang;<br/>Yang percaya Tuhan harus ingat,<br/>"Berpindah ke hidup."<br/>',NULL,63853,5);
INSERT INTO stanza VALUES('I696','1','Dengar, rah''sia tersembunyi,<br/>dari sejarah manusia!<br/>Jika t''rima rah''sia ini,<br/>Kristus - insan esa!<br/>Mulia, mulia, haleluya!<br/>Mulia, mulia, haleluya!<br/>Jika t''rima rah''sia ini,<br/>Kristus - insan esa!<br/>',NULL,63854,1);
INSERT INTO stanza VALUES('I697','1','B''rita suka!<br/>Menggemparkan,<br/>Allah tinggal dengan insan!<br/>Meski insan,<br/>hina dina,<br/>Allah mau menerima.<br/>',NULL,63855,1);
INSERT INTO stanza VALUES('I697','chorus','Berita rahasia!<br/>Allah tinggal dengan insan!<br/>Kekal esa, kekal tent''ram,<br/>kekal nikmat diri Allah!<br/>Berita rahasia!<br/>Allah tinggal dengan insan.<br/>',NULL,63856,2);
INSERT INTO stanza VALUES('I698','1','Tuhan Yesus sumber hayat,<br/>Tuhan Yesus air hayat,<br/>Minum Dia,<br/>pasti takkan haus selama-lamanya.<br/>',NULL,63857,1);
INSERT INTO stanza VALUES('I698','chorus','Benarkah takkan haus?<br/>Ya, benar tak haus!<br/>Benarkah takkan haus?<br/>Ya, benar tak haus! Minum Dia,<br/>pasti takkan haus selama-lamanya.<br/>',NULL,63858,2);
INSERT INTO stanza VALUES('I698','2','Tuhan Yesus sumber hayat,<br/>Tuhan Yesus suplai hayat,<br/>Makan Dia,<br/>pasti takkan lapar selama-lamanya.<br/>',NULL,63859,3);
INSERT INTO stanza VALUES('I698','3','Tuhan Yesus kebangkitan,<br/>Tuhan Yesus Raja Hayat,<br/>Yang percaya,<br/>pasti tak binasa selama-lamanya.<br/>',NULL,63860,4);
INSERT INTO stanza VALUES('I699','1','Meski merah seperti<br/>kirmizilah dosamu.<br/>Tuhan pasti cucikan,<br/>hingga putih p''ri salju.<br/>Meski warna dosamu,<br/>semerah padma.<br/>Tuhan pasti cucikan,<br/>hingga putih p''ri salju.<br/>Tuhan pasti cucikan,<br/>hingga putih p''ri salju.<br/>',NULL,63861,1);
INSERT INTO stanza VALUES('I699','2','Dengarlah seruan Tuhan,<br/>baliklah d''ngan segera!<br/>Dengarlah seruan Tuhan,<br/>baliklah d''ngan segera!<br/>P''nuh kasih Dia memanggil;<br/>Baliklah seg''ra!<br/>Dengarlah seruan Tuhan!<br/>Dengarlah seruan Tuhan!<br/>Baliklah d''ngan segera<br/>pada Juru-selamat!<br/>',NULL,63862,2);
INSERT INTO stanza VALUES('I699','3','Dosamu diampuni,<br/>bahkan tak diingat-Nya!<br/>Dosamu diampuni,<br/>bahkan tak diingat-Nya!<br/>Dosamu seg''ra sirna,<br/>lenyap p''ri awan.<br/>Dosamu diampuni,<br/>dosamu diampuni,<br/>Bahkan tak diingat-Nya,<br/>bahkan tak diingat-Nya!<br/>',NULL,63863,3);
INSERT INTO stanza VALUES('I700','1','Dapat dunia, hilang Penolong,<br/>apa arti hidup demikian?<br/>Bisakah hati t''rima hiburan,<br/>atas barang seg''ra lewat?<br/>Dapat dunia, hilang Penolong,<br/>dapatkah ku pakai seumurku?<br/>Semua senang dunia tak dapat<br/>tandingi penuh hayat Kristus.<br/>',NULL,63864,1);
INSERT INTO stanza VALUES('I700','2','Andai ku kaya dan dicintai,<br/>namaku tenar dihormati,<br/>Tetap tiada harapan, dermaga,<br/>tempat p''rahuku sandar henti.<br/>Dapat dunia, hilang Penolong<br/>yang mati bagiku di salib.<br/>Dapatkah dunia beriku lega,<br/>lepas dari derita hati?<br/>',NULL,63865,2);
INSERT INTO stanza VALUES('I700','3','Betapa kosong, tanpa Penolong!<br/>Di tengah dosa, dukacita!<br/>Betapa gelap, tanpa diri-Nya!<br/>Hanya malam penuh celaka!<br/>Bila ku hidup tanpa Penolong,<br/>ajal tiba, ku bagaimana?<br/>O, masuk lembah duka tanpa Dia,<br/>tanpa Dia selama-lamanya!<br/>',NULL,63866,3);
INSERT INTO stanza VALUES('I700','4','Sungguh riang, dalam Dia dapat s''gala,<br/>sungguh menghibur hati duka!<br/>Semua dosa Dia ampuni,<br/>tiada susah yang tak Dia tanggung!<br/>Walau hanya punya Kristus Tuhan,<br/>tanpa yang lain dalam dunia,<br/>Dalam Dia, kau miliki s''gala,<br/>p''nuhi perlu tiada batas.<br/>',NULL,63867,4);
INSERT INTO stanza VALUES('I701','1','Jerih payah apa guna?<br/>Semua hanya menjemukan!<br/>Sekekap saja t''lah lewat!<br/>Sia-sia, sia-sialah!<br/>',NULL,63868,1);
INSERT INTO stanza VALUES('I701','chorus','Sia-sialah! Sia-sialah!<br/>Sia-sialah! Sia-sialah!<br/>Semua sia-sialah,<br/>p''ri asap, sg''ra sirna!<br/>',NULL,63869,2);
INSERT INTO stanza VALUES('I701','2','Hidup manusia p''nuh d''rita;<br/>kian banyak ilmu, kian gundah!<br/>Kian banyak hikmat, kian resah!<br/>Sia-sia, sia-sialah!<br/>',NULL,63870,3);
INSERT INTO stanza VALUES('I701','3','Harta, k''luarga, kenikmatan,<br/>dapatkah membahagiakan?<br/>Justru makin menyusahkan!<br/>Sia-sia, sia-sialah!<br/>',NULL,63871,4);
INSERT INTO stanza VALUES('I701','4','Jerih payah jadi c''laka,<br/>mungkin s''karang b''lum terasa;<br/>Bila maut tiba, s''mua musnah!<br/>Sia-sia, sia-sialah!<br/>',NULL,63872,5);
INSERT INTO stanza VALUES('I701','5','Mumpung muda cari Tuhan!<br/>Barulah dapat bahagia!<br/>Dapat Dia, hati puaslah!<br/>Dia tak sia-sia!<br/>',NULL,63873,6);
INSERT INTO stanza VALUES('I702','1','Derita, nestapa,<br/>pikul beban b''rat,<br/>Hidup penuh susah,<br/>d''rita, berkeluh kesah.<br/>',NULL,63874,1);
INSERT INTO stanza VALUES('I702','2','Tuhan-lah yang mampu<br/>pikul derita,<br/>Jangan lambat, jangan bimbang,<br/>datang pada-Nya.<br/>',NULL,63875,2);
INSERT INTO stanza VALUES('I703','1','Kekal, kekal, selamanya!<br/>Bagaimana kau laluinya?<br/>Bereskanlah soal ini,<br/>jangan sampai sesal nanti!<br/>Mati, hidup, semua kekal,<br/>bagaimana kau laluinya?<br/>',NULL,63876,1);
INSERT INTO stanza VALUES('I703','2','Kekal, kekal, selamanya!<br/>Bagaimana kau laluinya?<br/>Banyak orang pilih Yesus,<br/>dan tinggalkan semua dosa,<br/>Percaya Dia, dapat kurnia,<br/>lahir baru, hampir Allah.<br/>',NULL,63877,2);
INSERT INTO stanza VALUES('I703','3','Kekal, kekal, selamanya!<br/>Bagaimana kau laluinya?<br/>Tidak masuk pintu kurnia,<br/>tentu menempuh binasa,<br/>Kini pikirkan d''ngan cermat,<br/>akhir mana yang kau minat!<br/>',NULL,63878,3);
INSERT INTO stanza VALUES('I703','4','Kekal, kekal, selamanya!<br/>Bagaimana kau laluinya?<br/>Jumpa Tuhan dalam surga,<br/>atau d''rita dalam n''raka?<br/>Amat serius, amat fatal,<br/>pilihlah sekarang juga!<br/>',NULL,63879,4);
INSERT INTO stanza VALUES('I703','5','Kekal, kekal, selamanya!<br/>Bagaimana kau laluinya?<br/>Mumpung kini percaya Dia,<br/>lepas maut, masuk hidup!<br/>Dengan b''rani kau berkata,<br/>"Kini aku t''lah selamat!"<br/>',NULL,63880,5);
INSERT INTO stanza VALUES('I704','1','Siapa dapat s''lamatkanku?<br/>Kristus-lah! Kristus-lah!<br/>Siapa singkirkan d''ritaku?<br/>Kristus-lah!<br/>S''lamatlah! S''lamatlah!<br/>Siapa dapat s''lamatkanku?<br/>Kristus-lah!<br/>',NULL,63881,1);
INSERT INTO stanza VALUES('I704','2','Yang pimpinku ''nempuh mulia,<br/>Kristus-lah! Kristus-lah!<br/>Yang beriku bah''gia kekal,<br/>Kristus-lah!<br/>Maut sirna! P''nuh bah''gia!<br/>Yang suplaiku dengan limpah,<br/>Kristus-lah!<br/>',NULL,63882,2);
INSERT INTO stanza VALUES('I705','1','Orang dosa, budak dosa,<br/>kena sengat maut;<br/>Tak percaya Tuhan,<br/>pasti mati dalam dosa.<br/>Dia-lah Sang Kekal<br/>yang mampu bebaskan kita,<br/>Budak dosa terorakkan,<br/>bebas selamanya.<br/>',NULL,63883,1);
INSERT INTO stanza VALUES('I706','1','Lembut, mesra, suara Yesus memanggil,<br/>memanggil aku dan kau!<br/>Dengan sabar Tuhan Yesus menunggu,<br/>menunggu aku dan kau!<br/>',NULL,63884,1);
INSERT INTO stanza VALUES('I706','chorus','Pulang! Pulang!<br/>Orang yang lelah pulang!<br/>Dengan mesra Tuhan Yesus memanggil<br/>orang berdosa, pulang!<br/>',NULL,63885,2);
INSERT INTO stanza VALUES('I706','2','Mengapa tidak mendengar Dia panggil?<br/>Dia panggil aku dan kau!<br/>Mengapa tidak menyambut kurnia-Nya?<br/>Dia rahmati ku dan kau!<br/>',NULL,63886,3);
INSERT INTO stanza VALUES('I706','3','Waktu lewat, kesempatan pun lalu,<br/>lalui aku dan kau;<br/>Bayang maut makin dekat mengancam,<br/>mengancam aku dan kau.<br/>',NULL,63887,4);
INSERT INTO stanza VALUES('I706','4','Sungguh indah kasih yang Dia janjikan,<br/>untuklah aku dan kau;<br/>Semua dosa nista, Dia ampuni,<br/>ampuni aku dan kau.<br/>',NULL,63888,5);
INSERT INTO stanza VALUES('I707','1','Ku dengar panggilan Tuhan,<br/>"Marilah, marilah, ikut-Ku!"<br/>Suara-Nya terus memanggil,<br/>"Marilah, marilah, ikut-Ku!<br/>Jalan yang susah Ku tempuh,<br/>bagimu korban jiwa-Ku,<br/>Bahkan Ku pikul bebanmu;<br/>Marilah, marilah, ikut-Ku!"<br/>',NULL,63889,1);
INSERT INTO stanza VALUES('I707','2','S''mua dosamu Ku ampuni,<br/>marilah, marilah ikut-Ku!<br/>Lepas b''lenggu, kau bebaslah,<br/>marilah, marilah, ikut-Ku!<br/>Aku ''kan jadi Allah-mu,<br/>yang membimbingmu selalu;<br/>Pun jadi bahagiamu, marilah,<br/>marilah, ikut-Ku!<br/>',NULL,63890,2);
INSERT INTO stanza VALUES('I707','3','Serahkan s''gala kuatirmu,<br/>marilah, marilah, ikut-Ku!<br/>Bebanmu akan Ku tanggung,<br/>marilah, marilah, ikut-Ku!<br/>Kuatir masa depanmu,<br/>percayakan kepada-Ku,<br/>Tangan-Ku seka tangismu,<br/>marilah, marilah, ikut-Ku!<br/>',NULL,63891,3);
INSERT INTO stanza VALUES('I708','1','Dengan lembut Yesus memanggilmu,<br/>memanggilmu, memanggilmu!<br/>Mengapa kau tinggalkan kasih-Nya,<br/>mengembara, merana?<br/>',NULL,63892,1);
INSERT INTO stanza VALUES('I708','chorus','Dia memanggil!<br/>Memanggilmu!<br/>Yesus memanggil,<br/>dengan lembut memanggilmu!<br/>',NULL,63893,2);
INSERT INTO stanza VALUES('I708','2','Yesus memanggil yang letih lesu,<br/>memanggilmu, memanggilmu!<br/>Serahkan kepada-Nya bebanmu,<br/>Ia sambut, tak buangmu.<br/>',NULL,63894,3);
INSERT INTO stanza VALUES('I708','3','Yesus menunggu kedatanganmu,<br/>Ia menunggu, Ia menunggu!<br/>Letakkan dosamu di kaki-Nya,<br/>sekarang, jangan tunda.<br/>',NULL,63895,4);
INSERT INTO stanza VALUES('I708','4','Yesus memanggil, dengar suara-Nya,<br/>dengarkanlah, dengarkanlah!<br/>Seru nama-Nya, t''rima kurnia-Nya,<br/>Dia b''ri berkat limpah.<br/>',NULL,63896,5);
INSERT INTO stanza VALUES('I709','1','Siapa saja suka, sg''ra dapat s''lamat,<br/>''nilah b''rita surga bagi yang dosa;<br/>B''ritakanlah seg''ra pada manusia,<br/>"Siapa pun boleh datang!"<br/>',NULL,63897,1);
INSERT INTO stanza VALUES('I709','chorus','Siapa pun juga, pulanglah seg''ra!<br/>''Nilah panggilan Bapa yang p''nuh cinta;<br/>Tua, muda, pria, wanita, tanpa jasa;<br/>Semuanya boleh datang!<br/>',NULL,63898,2);
INSERT INTO stanza VALUES('I709','2','Siapa yang mau datang, jangan terlambat,<br/>pintu t''lah terbuka, masuklah seg''ra;<br/>Yesus Juru-s''lamat telah bersabda,<br/>"Siapa pun boleh datang!"<br/>',NULL,63899,3);
INSERT INTO stanza VALUES('I709','3','Siapa saja suka - hidup yang kekal;<br/>Siapa saja suka - sabda-Nya benar;<br/>Siapa saja suka - janji-Nya tepat;<br/>Siapa pun boleh datang!<br/>',NULL,63900,4);
INSERT INTO stanza VALUES('I710','1','Tok, tok, tok, tok, siapakah?<br/>Tunggu, tunggu, d''ngan sabar!<br/>Tamu agung t''lah berkunjung,<br/>berbahagia sungguh;<br/>Hai hatiku, jangan lambat!<br/>Buka seg''ra pintumu!<br/>',NULL,63901,1);
INSERT INTO stanza VALUES('I710','2','Tok, tok, tok, tok, siapakah?<br/>Tunggu, tunggu, d''ngan sabar!<br/>Tapi puntu masih tutup,<br/>banyak lalang dan rumput;<br/>Engsel pintu t''lah berkarat,<br/>kayu pun sudah lapuk.<br/>',NULL,63902,2);
INSERT INTO stanza VALUES('I710','3','Tok, tok, tok, tok, siapakah?<br/>Tunggu, tunggu, d''ngan sabar!<br/>Tangan luka, kar''na paku,<br/>mengetuk t''rus menerus;<br/>Juru-s''lamat, tetap tunggu,<br/>engkau buka hatimu.<br/>',NULL,63903,3);
INSERT INTO stanza VALUES('I711','1','Dengar! Tuhan ketuk,<br/>ketuk, pintu hatimu!<br/>Mengapa kau keras,<br/>degil, tak mau peduli?<br/>Lekas buka hatimu!<br/>Sambut Dia masuk!<br/>Mau masuk hatimu,<br/>Dia, pula b''ri kurnia!<br/>',NULL,63904,1);
INSERT INTO stanza VALUES('I711','chorus','Silakan Dia masuk!<br/>Dia mengetuk pintu!<br/>Silakan Tuhan masuk,<br/>dalam hatimu!<br/>',NULL,63905,2);
INSERT INTO stanza VALUES('I711','2','Yang datang pada-Ku,<br/>pasti t''rima sentosa;<br/>Bagimu Ku korban jiwa,<br/>pada Golgota.<br/>Agar kau t''rima kurnia,<br/>Ku t''lah berdarah,<br/>Cuci s''mua dosamu,<br/>hingga seputih salju.<br/>',NULL,63906,3);
INSERT INTO stanza VALUES('I711','3','Mengapa kau lambat saja?<br/>Tuhan ''nantikan!<br/>Ingat, waktu lewat<br/>takkan kembali pula!<br/>Dia mengasihimu,<br/>jangan kau tolak;<br/>Dia beri hayat,<br/>agar kau tak binasa.<br/>',NULL,63907,4);
INSERT INTO stanza VALUES('I711','4','Bila kau terlambat,<br/>pasti sehari kelak,<br/>Kau ''kan sangat sesal,<br/>tapi sudah terlambat.<br/>Pintu kurnia t''lah tutup,<br/>tiada harapan;<br/>Mumpung kini, mari, Tuhan,<br/>masuklah s''karang!<br/>',NULL,63908,5);
INSERT INTO stanza VALUES('I712','1','S''ratus domba, hilang satu,<br/>Sang Gembala sedih,<br/>Terjang gunung, terjang bah''ya,<br/>Dia pergi mencari.<br/>Domba sesat, lekas pulang,<br/>depan banyak hewan buas,<br/>Lekas pulang, jangan lambat!<br/>',NULL,63909,1);
INSERT INTO stanza VALUES('I713','1','Domba hilang, di mana kini?<br/>Juru-s''lamat sedang mencari!<br/>Seekor domba telah hilang,<br/>mungkinkah engkau?<br/>',NULL,63910,1);
INSERT INTO stanza VALUES('I713','chorus','Mungkinkah engkau?<br/>Mungkinkah engkau?<br/>Seekor domba telah hilang,<br/>mungkinkah engkau?<br/>',NULL,63911,2);
INSERT INTO stanza VALUES('I713','2','Dinar hilang, di mana kini?<br/>Sang Roh Kudus sedang mencari!<br/>Dinar telah hilang sekeping,<br/>mungkinkah engkau?<br/>',NULL,63912,3);
INSERT INTO stanza VALUES('I713','3','Yang berk''lana, kau sentosakah?<br/>Di dalam rumah banyak berkat!<br/>Bapa Allah sedang menunggu,<br/>mungkinkah engkau?<br/>',NULL,63913,4);
INSERT INTO stanza VALUES('I714','1','Datang pada Yesus,<br/>Dia di sini;<br/>Jangan tempuh mati,<br/>Dia di sini;<br/>Mari semua datang,<br/>waktu tidak banyak;<br/>Jangan berlambatan,<br/>Dia di sini.<br/>',NULL,63914,1);
INSERT INTO stanza VALUES('I714','2','Datang pada Yesus,<br/>Dia di sini;<br/>Jangan salah jalan,<br/>Dia di sini;<br/>Tuhan beri kurnia,<br/>biar kau tak binasa;<br/>Jangan cinta dunia,<br/>Dia di sini.<br/>',NULL,63915,2);
INSERT INTO stanza VALUES('I714','3','Datang pada Yesus,<br/>Dia di sini;<br/>Jangan ragu bimbang,<br/>Dia di sini;<br/>Meski dosa berat,<br/>kasih-Nya berlebih;<br/>Jangan putus asa,<br/>Dia di sini.<br/>',NULL,63916,3);
INSERT INTO stanza VALUES('I714','4','Datang pada Yesus,<br/>Dia di sini;<br/>Tiada jalan lain,<br/>Dia di sini;<br/>Tuhan g''nap tebusan,<br/>Tuhan sedang panggil;<br/>Sg''ra datang pada-Nya,<br/>Dia di sini.<br/>',NULL,63917,4);
INSERT INTO stanza VALUES('I715','1','Kau jatuh di dosa, alami d''rita,<br/>mengapa tidak seg''ra bertobat?<br/>Kau di jalan salah, penuh perangkap;<br/>tak balik pasti jatuh ke jurang.<br/>',NULL,63918,1);
INSERT INTO stanza VALUES('I715','chorus','Tuhan mau tolongmu!<br/>Tuhan menunggu!<br/>Mumpung kini biar<br/>Dia s''lamatkanmu!<br/>',NULL,63919,2);
INSERT INTO stanza VALUES('I715','2','Bawah tangan musuh, dipermainkan,<br/>meski ingin, tidak dapat lepas;<br/>Diganggu, digoda, sungguh sengsara,<br/>p''ri ikan dan burung kau terjerat.<br/>',NULL,63920,3);
INSERT INTO stanza VALUES('I715','3','Usia bertambah, justru berkurang,<br/>hidup p''ri awan seg''ra menghilang!<br/>Ada penghakiman, n''raka mengancam,<br/>bagaimana lepas api bara?<br/>',NULL,63921,4);
INSERT INTO stanza VALUES('I715','4','Wafat-Nya menumpas Iblis dan dosa,<br/>bangkit-Nya, Dia jadi Tuhan, Raja;<br/>Hayat telan maut, b''ri kebebasan,<br/>mengapa harus tunggu binasa?<br/>',NULL,63922,5);
INSERT INTO stanza VALUES('I715','5','Meski Tuhan duka, kar''na kau keras,<br/>Dia tetap damba b''ri kes''lamatan;<br/>Meski kau menolak, Dia tetap tunggu,<br/>tunggu kau percaya dan bertobat.<br/>',NULL,63923,6);
INSERT INTO stanza VALUES('I716','1','Yesus menunggu, tunggu kau datang,<br/>Dia menunggu t''lah lama.<br/>Dia t''rus menunggu, biar kau bertobat,<br/>terima hidup kekal.<br/>',NULL,63924,1);
INSERT INTO stanza VALUES('I716','chorus','Mari! Mari datang!<br/>Siapa pun juga!<br/>''Nilah panggilan Tuhan.<br/>Dia mau dan menunggu,<br/>hendak b''ri kurnia,<br/>asal kau mau percaya!<br/>',NULL,63925,2);
INSERT INTO stanza VALUES('I716','2','Meski t''lah lama kau berkelana,<br/>tenggelam dalam dosa.<br/>Tapi Dia tetap ingin dapatkan<br/>dirimu yang t''lah lelah.<br/>',NULL,63926,3);
INSERT INTO stanza VALUES('I716','3','Meski dirimu sering menolak,<br/>tapi Dia takkan bosan.<br/>Dengan p''nuh kasih Di-a menunggu,<br/>kau datang kepada-Nya.<br/>',NULL,63927,4);
INSERT INTO stanza VALUES('I716','4','Kau harus takluk, pada kasih-Nya,<br/>kasih Yesus yang agung.<br/>Yesus memanggil,"mari datanglah!<br/>" Jawablah,"Aku ma-u!"<br/>',NULL,63928,5);
INSERT INTO stanza VALUES('I717','beginning-note','Syair Kesatu<br/>',NULL,63929,1);
INSERT INTO stanza VALUES('I717','1','Wahai yang tertindih dosa,<br/>Tuhan penuh rahmat;<br/>Dia mau tolong kau selamat,<br/>asal kau percaya.<br/>',NULL,63930,2);
INSERT INTO stanza VALUES('I717','chorus','Percayalah! Percayalah!<br/>Percaya Tuhan!<br/>Dia mau tolong!<br/>Dia mau tolong!<br/>Dia tolong s''karang.<br/>',NULL,63931,3);
INSERT INTO stanza VALUES('I717','2','Untuk beri kurnia limpah,<br/>Yesus t''lah berdarah;<br/>Masuk dalam "sumber merah",<br/>pasti putih bersih.<br/>',NULL,63932,4);
INSERT INTO stanza VALUES('I717','3','Tuhan jalan, kebenaran,<br/>untuk masuk sabat;<br/>Percayalah, jangan ragu,<br/>dapat hidup kekal.<br/>',NULL,63933,5);
INSERT INTO stanza VALUES('I717','4','Mari ikut jalur ini,<br/>menuju ke mulia;<br/>Surga indah tiada susah,<br/>nikmat bah''gia kekal.<br/>',NULL,63934,6);
INSERT INTO stanza VALUES('I717','beginning-note','Syair Kedua<br/>',NULL,63935,7);
INSERT INTO stanza VALUES('I717','1','Wahai yang tertindih dosa,<br/>datang pada Tuhan;<br/>Dia mau tolong kau selamat,<br/>asal kau percaya.<br/>',NULL,63936,8);
INSERT INTO stanza VALUES('I717','chorus','Percayalah!<br/>Percayalah!<br/>Percaya s''karang!<br/>Dia mau tolong!<br/>Dia mau tolong!<br/>Dia tolong s''karang!<br/>',NULL,63937,9);
INSERT INTO stanza VALUES('I717','2','Bagimu Yesus t''lah mati,<br/>berdarah di salib.<br/>Dapat s''lamat tanpa jasa,<br/>asal kau percaya.<br/>',NULL,63938,10);
INSERT INTO stanza VALUES('I717','3','Pintu kurnia t''lah terbuka,<br/>demi kasih Yesus.<br/>Waktu lewat tak kembali,<br/>percayalah seg''ra.<br/>',NULL,63939,11);
INSERT INTO stanza VALUES('I717','4','Set''lah mati, kau ke mana?<br/>Surga atau n''raka?<br/>Hidup kekal, mati kekal,<br/>pilihlah sekarang!<br/>',NULL,63940,12);
INSERT INTO stanza VALUES('I718','1','Jangan tolak firman kurnia,<br/>pun jangan tutup terang-Nya,<br/>Hai teman, jangan berkeras,<br/>seg''ra percaya.<br/>',NULL,63941,1);
INSERT INTO stanza VALUES('I718','chorus','Jangan kau tunda!<br/>Jangan kau tunda!<br/>Seg''ra percaya,<br/>dapat selamat!<br/>',NULL,63942,2);
INSERT INTO stanza VALUES('I718','2','Surya esok belum tentu<br/>masih soroti dirimu,<br/>Kini saatnya, seg''ralah,<br/>jangan menunggu!<br/>',NULL,63943,3);
INSERT INTO stanza VALUES('I718','3','Apa yang ada di dunia,<br/>tiada yang riil dan kekal,<br/>Mari t''rima kurnia-Nya,<br/>kini saatnya!<br/>',NULL,63944,4);
INSERT INTO stanza VALUES('I718','4','Tuhan penuh kasih kurnia,<br/>tak tolak orang yang datang,<br/>Dia beri keselamatan,<br/>kini saatnya!<br/>',NULL,63945,5);
INSERT INTO stanza VALUES('I719','1','Kalau ingin lepas d''rita dosa,<br/>biar Kristus masuk hatimu,<br/>Kalau ingin ''nempuh hidup baru,<br/>biar Kristus masuk hatimu.<br/>',NULL,63946,1);
INSERT INTO stanza VALUES('I719','chorus','Kini, buang ragumu,<br/>kini serah pada-Nya,<br/>Kini buka hatimu,<br/>biar Kristus masuk hatimu.<br/>',NULL,63947,2);
INSERT INTO stanza VALUES('I719','2','Kalau tabiat jahat, ego mucul,<br/>biar Kristus masuk hatimu,<br/>Dunia t''rasa hampa, tiada puas,<br/>biar Kristus masuk hatimu.<br/>',NULL,63948,3);
INSERT INTO stanza VALUES('I719','3','Kalau ingin gelap jadi terang,<br/>biar Kristus masuk hatimu,<br/>Kalau ingin sakit jadi sembuh,<br/>biar Kristus masuk hatimu.<br/>',NULL,63949,4);
INSERT INTO stanza VALUES('I719','4','Kalau ingin hati penuh girang,<br/>biar Kristus masuk hatimu,<br/>Kalau ingin masuk damai tenang,<br/>biar Kristus masuk hatimu.<br/>',NULL,63950,5);
INSERT INTO stanza VALUES('I720','1','Pandanglah diri Yesus,<br/>memandang, sg''ra hidup!<br/>Pandanglah Dia t''lah korban!<br/>Pandanglah!<br/>Pandanglah Dia di salib,<br/>memandang, sg''ra hidup!<br/>Dia bersabda, "Pandang-Ku!"<br/>Pandanglah!<br/>',NULL,63951,1);
INSERT INTO stanza VALUES('I720','chorus','Lihat! Tuhan di salib,<br/>mati ganti yang dosa,<br/>Pandang Dia, tak binasa,<br/>pandanglah!<br/>',NULL,63952,2);
INSERT INTO stanza VALUES('I720','2','Walau kau najis, jahat;<br/>memandang, sg''ra hidup!<br/>Pandang Dia, dosa lepas,<br/>pandanglah!<br/>Lama kau dibelenggu;<br/>memandang, sg''ra hidup!<br/>Pandang Dia, kau selamat,<br/>pandanglah!<br/>',NULL,63953,3);
INSERT INTO stanza VALUES('I720','3','Walau kau t''lah tersesat,<br/>memandang, sg''ra hidup!<br/>Jangan k''raskan hatimu,<br/>pandanglah!<br/>Bapa panggil kau pulang,<br/>memandang, sg''ra hidup!<br/>Siapa mau boleh datang,<br/>pandanglah!<br/>',NULL,63954,4);
INSERT INTO stanza VALUES('I721','1','Miskin, lemah, duka, m''rana,<br/>orang dosa marilah!<br/>Yesus tunggu b''ri selamat,<br/>penuh kuasa pun rahmat;<br/>Dia sanggup menolongmu!<br/>Dia sanggup, jangan bimbang.<br/>',NULL,63955,1);
INSERT INTO stanza VALUES('I721','2','Dia sambutmu, mari datang,<br/>Dia tidak menolakmu,<br/>Kau bertobat dan percaya,<br/>kau pasti t''rima kurnia,<br/>Tanpa bayar, tanpa bayar,<br/>cukup datang pada-Nya.<br/>',NULL,63956,2);
INSERT INTO stanza VALUES('I721','3','Jangan terkecoh nurani,<br/>ingin layakkan diri,<br/>Sudah layak, mari datang,<br/>engkau perlu kasih-Nya,<br/>Tanpa syarat! Tanpa syarat!<br/>Pintu kurnia terbuka.<br/>',NULL,63957,3);
INSERT INTO stanza VALUES('I721','4','Hati gundah, beban berat,<br/>lelah, duka, dan gagal,<br/>Kalau tunggu diri baik,<br/>kau takkan pernah datang,<br/>Yesus kurban atas salib,<br/>membayar hutang dosa.<br/>',NULL,63958,4);
INSERT INTO stanza VALUES('I721','5','Pikirkanlah Getsemani,<br/>Juru-s''lamat berdoa,<br/>Dengarlah Dia di Golgota,<br/>berseru dengan lantang,<br/>"Sudah genap!" "Sudah genap!"<br/>Orang dosa s''lamatlah.<br/>',NULL,63959,5);
INSERT INTO stanza VALUES('I721','6','Darah-Nya telah puaskan<br/>tuntutan adil Allah,<br/>Percayalah, percayalah,<br/>s''mua dosa terampunkan,<br/>Hanya Yesus, hanya Yesus,<br/>sanggup tolong yang dosa.<br/>',NULL,63960,6);
INSERT INTO stanza VALUES('I722','1','Hidup manusia singkat,<br/>p''ri awan tertiup angin,<br/>hidup s''perti bermimpi,<br/>seg''ralah!<br/>Waktu lewat p''ri kilat,<br/>tanpa tanda maut tiba,<br/>terlambat, masuk n''raka,<br/>seg''ralah!<br/>',NULL,63961,1);
INSERT INTO stanza VALUES('I722','chorus','Seg''ralah!<br/>Seg''ralah!<br/>Tuhan Yesus memanggil:<br/>Seg''ralah!<br/>Bila kau tak bertobat,<br/>pintu kurnia tertutup,<br/>berseru pun tak guna,<br/>seg''ralah!<br/>',NULL,63962,2);
INSERT INTO stanza VALUES('I722','2','Yang pandai pasti sadar,<br/>bunga indah pun layu,<br/>Remaja pun ''kan lewat,<br/>seg''ralah!<br/>Marilah kau pikirkan,<br/>jangan sampai terlambat,<br/>Jiwamu masuk n''raka,<br/>seg''ralah!<br/>',NULL,63963,3);
INSERT INTO stanza VALUES('I722','3','Roh Kudus s''ring memanggil,<br/>mengharukan hatimu,<br/>Kau tunduk seg''ra s''lamat,<br/>seg''ralah!<br/>Tuhan tunggu b''ri kurnia,<br/>tolong kau dari susah,<br/>Kau tolak, sungguh bodoh,<br/>seg''ralah!<br/>',NULL,63964,4);
INSERT INTO stanza VALUES('I722','4','Orang dosa dengarlah,<br/>kurnia-Nya jangan tolak,<br/>T''rima Yesus, Penolong,<br/>seg''ralah!<br/>Datang kepada Yesus,<br/>t''rima Kristus dalammu,<br/>T''rimalah s''karang juga,<br/>seg''ralah!<br/>',NULL,63965,5);
INSERT INTO stanza VALUES('I723','1','Yesus itu keperluan kita.<br/>Dia Allah, terlahir di malaf;<br/>Jadi insan, serbalah sengsara,<br/>akhirnya tersalib ''tuk selamatkan Anda.<br/>',NULL,63966,1);
INSERT INTO stanza VALUES('I723','chorus','Perlu Yesus! Perlu Yesus!<br/>Tiap orang perlu Yesus!<br/>Oleh-Nya dosa lenyap!<br/>Oleh-Nya s''lamat tiba!<br/>Mau dapat hidup kekal,<br/>perlulah Yesus!<br/>',NULL,63967,2);
INSERT INTO stanza VALUES('I723','2','Dia Syafaat, bangkit naik surga;<br/>utus Roh-Nya, mencarilah Anda;<br/>Percayalah, s''ru nama agung-Nya,<br/>anteromu pasti dipuaskan berkat-Nya.<br/>',NULL,63968,3);
INSERT INTO stanza VALUES('I723','3','Hati gelap diberi sorotan,<br/>dosa banyak, diberi ampunan;<br/>Cemar, nista, dibasuh darah-Nya,<br/>Roh-Nya beri hayat, singkirkan kelemahan.<br/>',NULL,63969,4);
INSERT INTO stanza VALUES('I723','4','Hidup s''lalu t''rasa kekurangan,<br/>entah apa, diri pun tak paham;<br/>Justru Yesus, jawaban yang tepat,<br/>Dia saja mampu puaskan hati hampa.<br/>',NULL,63970,5);
INSERT INTO stanza VALUES('I723','5','Dunia memang penuh gundah g''lisah,<br/>tidak ada satu pun sandaran;<br/>Ingkar, bohong, mana boleh andal?<br/>Menandakan Yesus itu keperluan kita.<br/>',NULL,63971,6);
INSERT INTO stanza VALUES('I723','6','Tua, muda, pria dan wanita,<br/>berdosalah, kurang mulia Allah;<br/>Percaya Dia, baru bisa s''lamat,<br/>hanya Yesus memuaskan Allah dan insan.<br/>',NULL,63972,7);
INSERT INTO stanza VALUES('I724','1','Adaku ini tak layak,<br/>namun darah-Mu tertumpah,<br/>Bahkan Kau rela b''ri hayat,<br/>Yesus Penolong, ku datang!<br/>',NULL,63973,1);
INSERT INTO stanza VALUES('I724','2','Adaku ini t''rus datang,<br/>jasa diri, tak ku harap,<br/>Darah adi b''ri ampunan,<br/>Yesus, Penolong, ku datang!<br/>',NULL,63974,2);
INSERT INTO stanza VALUES('I724','3','Adaku ini penuh syak,<br/>ombang-ambing p''rilah ombah,<br/>Lahir, batin, ronta ''tiasa,<br/>Yesus, Penolong, ku datang!<br/>',NULL,63975,3);
INSERT INTO stanza VALUES('I724','4','Adaku ini kasihan, buta,<br/>miskin, timpang, nista,<br/>Kurnia-Mu ku perlukan, Yesus,<br/>Penolong, ku datang!<br/>',NULL,63976,4);
INSERT INTO stanza VALUES('I724','5','Adaku ini Kau t''rima,<br/>beri hayat dan ampunan,<br/>Janji-Mu tak pernah ingkar,<br/>Yesus, Penolong, ku datang!<br/>',NULL,63977,5);
INSERT INTO stanza VALUES('I725','1','Lucut b''lenggu, duka dan gelap,<br/>Tuhan Yesus, aku datang!<br/>Masuk bebas, suka dan terang,<br/>Yesus, aku datang!<br/>Lepas sakit, masuk sehat-Mu;<br/>lepas miskin, masuk kaya-Mu.<br/>Lepas dosa, masuk kurnia-Mu;<br/>Yesus, aku datang!<br/>',NULL,63978,1);
INSERT INTO stanza VALUES('I725','2','Lucut gagal, malu, dan hina,<br/>Tuhan Yesus, aku datang!<br/>Masuk salib, serta mulia-Mu,<br/>Yesus, aku datang!<br/>Lepas d''rita, masuk p''lipur-Mu,<br/>lepas badai, masuk teduh-Mu.<br/>Lepas keluh, masuk riang-Mu,<br/>Yesus, aku datang!<br/>',NULL,63979,2);
INSERT INTO stanza VALUES('I725','3','Lucut pongah dan lahiriah,<br/>Tuhan Yesus, aku datang!<br/>Masuk bahagia sempurna,<br/>Yesus, aku datang!<br/>Ego ''nyingkir, oleh kasih-Mu,<br/>riang lega, tunggu raptur-Mu.<br/>Bubung ''ngawang, p''ri nasar mabur,<br/>Yesus, aku datang!<br/>',NULL,63980,3);
INSERT INTO stanza VALUES('I725','4','Lucut kelam, ngeri alam g''lap,<br/>Tuhan Yesus, aku datang!<br/>Masuk suka, t''rang rumah Bapa,<br/>Yesus, aku datang!<br/>Lepas jurang bobrok dan bejat,<br/>masuk naungan kawanan domba.<br/>Kekal pandang wajah mulia-Mu,<br/>Yesus aku datang!<br/>',NULL,63981,4);
INSERT INTO stanza VALUES('I726','1','Suara sambutan-Mu,<br/>tarikku pada-Mu;<br/>Darah adi-Mu tercucur,<br/>cuci nuraniku.<br/>',NULL,63982,1);
INSERT INTO stanza VALUES('I726','chorus','Tuhan pada-Mu;<br/>ku datang bers''ru,<br/>Cuciku d''ngan darah-Mu,<br/>putih sep''ri salju.<br/>',NULL,63983,2);
INSERT INTO stanza VALUES('I726','2','Najislah diriku,<br/>beramal tak sanggup;<br/>Tapi Kau beri kurnia-Mu,<br/>hapus s''mua yang buruk.<br/>',NULL,63984,3);
INSERT INTO stanza VALUES('I726','3','Kau pesan padaku,<br/>tinggalkan dosaku;<br/>Bertobat d''ngan hati tulus,<br/>berpaling pada-Mu.<br/>',NULL,63985,4);
INSERT INTO stanza VALUES('I726','4','Kau panggil d''ngan lembut,<br/>t''rangi d''ngan Roh Kudus;<br/>Agar ku ta''u diri buruk,<br/>sandar Tuhan m''lulu.<br/>',NULL,63986,5);
INSERT INTO stanza VALUES('I726','5','Roh Kudus dalamku,<br/>bukti ada hidup;<br/>Janji Allah t''lah terkabul,<br/>kar''na ku t''lah patuh.<br/>',NULL,63987,6);
INSERT INTO stanza VALUES('I726','6','Allah cinta aku,<br/>dan menebus aku; Ajaib,<br/>hingga aku takjub,<br/>kini s''mua bagi-Mu.<br/>',NULL,63988,7);
INSERT INTO stanza VALUES('I727','1','Ku datang pada salib,<br/>meski lemah dan miskin;<br/>Isi dunia s''mua sia-sia,<br/>ku perlu kurnia Tuhan.<br/>',NULL,63989,1);
INSERT INTO stanza VALUES('I727','chorus','Ku sandar pada Tuhan,<br/>bawah salib bersujud;<br/>Ku mohon Domba Allah,<br/>tolongku dari maut.<br/>',NULL,63990,2);
INSERT INTO stanza VALUES('I727','2','Ku mau kurnia Tuhan,<br/>tapi dosa berkuasa;<br/>Syukur ku dengar suara,<br/>"Dosamu Ku singkirkan."<br/>',NULL,63991,3);
INSERT INTO stanza VALUES('I727','3','Tuhan p''nuhi hatiku,<br/>dan perbarui aku;<br/>Darah-Mu mencuciku,<br/>tebus dan ''purnakanku.<br/>',NULL,63992,4);
INSERT INTO stanza VALUES('I727','4','Kini ku persembahkan:<br/>seg''nap roh, jiwa, raga,<br/>Hikmat, waktu, pun harta,<br/>pada Tuhan s''lamanya.<br/>',NULL,63993,5);
INSERT INTO stanza VALUES('I728','1','Kau berk''lana jauhkan Bapa,<br/>m''ngapa tak pulang?<br/>Dalam dosa, kau mend''rita,<br/>m''ngapa tak pulang?<br/>',NULL,63994,1);
INSERT INTO stanza VALUES('I728','chorus','Pulanglah! Pulanglah!<br/>Jangan berk''lana!<br/>Bapa Allah yang p''nuh cinta,<br/>tunggu kau pulang!<br/>',NULL,63995,2);
INSERT INTO stanza VALUES('I728','2','Ku berk''lana jauhkan Bapa,<br/>s''karang mau pulang;<br/>Dalam dosa ku terbenam,<br/>ku pulang, Tuhan!<br/>',NULL,63996,3);
INSERT INTO stanza VALUES('I728','3','Banyak tahun ku buang sia-sia,<br/>s''karang mau pulang;<br/>Menyesallah aku s''karang,<br/>ku pulang, Tuhan!<br/>',NULL,63997,4);
INSERT INTO stanza VALUES('I728','4','Berbuat dosa ku t''lah lelah,<br/>s''karang mau pulang;<br/>Sandar kasih, t''rima firman,<br/>ku pulang, Tuhan!<br/>',NULL,63998,5);
INSERT INTO stanza VALUES('I728','5','Hati hancur, jiwa m''rana,<br/>s''karang mau pulang;<br/>Tambah t''naga dan harapan,<br/>ku pulang, Tuhan!<br/>',NULL,63999,6);
INSERT INTO stanza VALUES('I729','1','Yesus, pengasih jiwa,<br/>ku datang ke ribaan-Mu,<br/>Ombak dahsyat menggulung,<br/>hujan badai mengamuk.<br/>Tuhan, sembunyikanku,<br/>hingga s''mua badai teduh!<br/>Tuhan, bimbing tempuhku,<br/>terimalah jiwaku!<br/>',NULL,64000,1);
INSERT INTO stanza VALUES('I729','2','Tiada lain p''lindung jiwa,<br/>hanya Yesus Tuhan-ku,<br/>Tuhan, jangan buangku,<br/>hibur hatiku s''lalu.<br/>Pada-Mu ku bersandar,<br/>mengharap bantuan-Mu,<br/>Atas jiwa dan raga,<br/>harapkan asuhan-Mu.<br/>',NULL,64001,2);
INSERT INTO stanza VALUES('I729','3','Tuhan, Kau-lah s''galaku,<br/>penuhi s''mua perluku,<br/>Ku jatuh, Tuhan angkat,<br/>ku sakit, disembuhkan.<br/>Nama-Mu kudus, benar;<br/>diriku dosa, cemar,<br/>Hatiku jahat b''laka,<br/>mohon curahkan kurnia.<br/>',NULL,64002,3);
INSERT INTO stanza VALUES('I729','4','Pada-Mu ku dapati,<br/>kurnia ampunan s''jati,<br/>Air hayat-Mu mengalir,<br/>basuh hati yang keji.<br/>Kau sumber hidup kekal,<br/>memancar dalam hati,<br/>Mengalir tidak henti,<br/>hingga kekal abadi.<br/>',NULL,64003,4);
INSERT INTO stanza VALUES('I730','1','Hai, yang dosa, dengarkanlah!<br/>Dia memanggil!<br/>Pada waktu Dia memanggil,<br/>jangan tertinggal!<br/>',NULL,64004,1);
INSERT INTO stanza VALUES('I730','chorus','Hai, yang dosa,<br/>dengar suara-Nya;<br/>Pada waktu Dia memanggil,<br/>jangan tertinggal!<br/>',NULL,64005,2);
INSERT INTO stanza VALUES('I730','2','Tuhan, jangan tinggalkanku!<br/>''Nilah pintaku!<br/>Waktu Kau panggil yang lain,<br/>ingatlah aku!<br/>',NULL,64006,3);
INSERT INTO stanza VALUES('I730','3','Biarku di depan takhta-Mu,<br/>t''rima kurnia-Mu;<br/>Sesal dosa, sembah, sujud,<br/>kuatkan imanku.<br/>',NULL,64007,4);
INSERT INTO stanza VALUES('I730','4','Mutlak sandar kuasa salib,<br/>ku mencari-Mu;<br/>Sembuhkan dan pulihkanku,<br/>dengan kurnia-Mu.<br/>',NULL,64008,5);
INSERT INTO stanza VALUES('I730','5','Kau-lah sumber hiburanku,<br/>Kau mustikaku;<br/>Padaku tiada yang lain,<br/>''cuali diri-Mu!<br/>',NULL,64009,6);
INSERT INTO stanza VALUES('I731','1','Batu kekal terbelah,<br/>pada-Mu-lah ''lindungku;<br/>Darah, air-Mu cucuran,<br/>''tuk dwi ganda dosaku;<br/>Ganjaranku lunas s''mua,<br/>lenyap patah kuasa maut.<br/>',NULL,64010,1);
INSERT INTO stanza VALUES('I731','2','Walau rajin tanganku,<br/>tak penuhi tuntut-Mu;<br/>Sia-sia tekun gairahku,<br/>tiada guna tangisku;<br/>''Nebus dosa tak cukup,<br/>Dikau saja Penebus.<br/>',NULL,64011,2);
INSERT INTO stanza VALUES('I731','3','Dua tanganku hampa,<br/>naung salib-Mu b''laka;<br/>T''lanjang, b''rilah ku jubah; picik,<br/>b''rilah ku kurnia;<br/>Nista, b''riku ampunan;<br/>tanpa ini ku c''laka.<br/>',NULL,64012,3);
INSERT INTO stanza VALUES('I731','4','Bila tiba ajalku,<br/>tutup pejam mataku;<br/>Mulai alam bakaku,<br/>tampil depan takhta-Mu;<br/>Terbelah-Mu bagiku,<br/>jamin penuh amanku.<br/>',NULL,64013,4);
INSERT INTO stanza VALUES('I732','1','Surga, takhta, dan mahkota Kau tinggalkan,<br/>datang ke dunia tolongku.<br/>Tapi Betlehem tiada serumah pun<br/>sedia bagi hadir-Mu.<br/>',NULL,64014,1);
INSERT INTO stanza VALUES('I732','chorus','Yesus, tinggallah dalamku!<br/>Dalamkulah tempat untuk-Mu!<br/>Oh, tinggallah dalam hatiku!<br/>Tinggallah dalam hatiku!<br/>',NULL,64015,2);
INSERT INTO stanza VALUES('I732','2','Malaikat dan tentara surga berseru,<br/>sembah, puji kebesaran-Mu;<br/>Di kota miskin dan hina terlahir-Mu,<br/>sepi, tiada yang mau tahu.<br/>',NULL,64016,3);
INSERT INTO stanza VALUES('I732','3','Di gua srigala temui tempatnya,<br/>burung pun punya sarang hangat;<br/>Namun ''numpang-Mu tidak berketentuan,<br/>di padang, lembah melarat.<br/>',NULL,64017,4);
INSERT INTO stanza VALUES('I732','4','Tuhan, datang-Mu bawa rahmat dan hidup,<br/>bebaslah sengsara umat-Mu;<br/>Mahkota duri menyiksai diri-Mu,<br/>atas saliblah wafat-Mu.<br/>',NULL,64018,5);
INSERT INTO stanza VALUES('I732','5','Surga riuh rendah, malaikat sorak nyaring,<br/>Kau mencapai menang, mulia!<br/>Saat itu panggilan-Mu ku dambakan,<br/>"Rumah-Ku ada tempatmu!"<br/>',NULL,64019,6);
INSERT INTO stanza VALUES('I733','1','Masuk hatiku, ya, Yesus!<br/>Ku bertobat dan t''rima-Mu;<br/>Hatiku sia-sia pun hampa,<br/>masuklah ke hatiku!<br/>',NULL,64020,1);
INSERT INTO stanza VALUES('I733','chorus','Mari masuk, ke hatiku!<br/>Masuk hatiku, ya, Yesus!<br/>S''karang masuk, beri kurnia,<br/>masuk hatiku, ya, Yesus!<br/>',NULL,64021,2);
INSERT INTO stanza VALUES('I733','2','Masuk hatiku, ya, Yesus!<br/>Curahkan kurnia d''ngan limpah;<br/>S''lamatkanku dari dosa,<br/>masuklah ke hatiku!<br/>',NULL,64022,3);
INSERT INTO stanza VALUES('I733','3','Masuk hatiku, ya, Yesus!<br/>Bersihkan seg''nap diriku;<br/>Roh hayat masuk dalamku,<br/>masuklah ke hatiku!<br/>',NULL,64023,4);
INSERT INTO stanza VALUES('I734','1','Dosa terbasuh,<br/>nafsu terhapus,<br/>T''rima Kristus<br/>jadi P''nolongku;<br/>Iblis tertakluk,<br/>dunia t''lah luntur,<br/>t''rima Kristus<br/>jadi P''nolongku.<br/>',NULL,64024,1);
INSERT INTO stanza VALUES('I734','chorus','T''rima! T''rima!<br/>T''rima seg''ra tanpa ragu,<br/>T''rima! T''rima!<br/>T''rima Kristus jadi P''nolongku!<br/>',NULL,64025,2);
INSERT INTO stanza VALUES('I734','2','Hayat berubah,<br/>rohku bert''naga,<br/>T''rima Kristus<br/>jadi hayatku!<br/>Damai di hati,<br/>hari depan t''rang,<br/>T''rima Kristus<br/>jadi hayatku!<br/>',NULL,64026,3);
INSERT INTO stanza VALUES('I734','3','Sakit t''lah sembuh,<br/>lemah jadi kuat,<br/>T''rima Kristus<br/>jadi Tabibku;<br/>Pedih t''lah hilang,<br/>maut terbenam,<br/>T''rima Kristus<br/>jadi Tabibku.<br/>',NULL,64027,4);
INSERT INTO stanza VALUES('I734','4','Susah jadi s''nang,<br/>duka jadi riang,<br/>T''rima Kristus<br/>jadi Rajaku;<br/>Surga bagianku,<br/>mulia nikmatku,<br/>T''rima Kristus<br/>jadi Rajaku.<br/>',NULL,64028,5);
INSERT INTO stanza VALUES('I735','1','Tenggelam dalam dosa,<br/>jauh pantai damai,<br/>Tenggelam amat dalam,<br/>tak berdaya bangkit!<br/>Dia dengar seruanku,<br/>seg''ra menolongku,<br/>Terjang badai,<br/>Dia datang s''lamatkanku.<br/>',NULL,64029,1);
INSERT INTO stanza VALUES('I735','chorus','Kasih Yesus,<br/>tolong aku,<br/>saat ku dalam dosa,<br/>Dia tolongku.<br/>Kasih Yesus,<br/>tolong aku,<br/>saat ku dalam dunia,<br/>Dia tolongku.<br/>',NULL,64030,2);
INSERT INTO stanza VALUES('I735','2','Kini ku damai,<br/>tent''ram lepas dosa d''rita,<br/>Penuh girang, perhentian,<br/>milik Kristus s''mata.<br/>Kasih kuat, sejati,<br/>patut ku memuji,<br/>Hati, hidup, diriku,<br/>s''mua milik-Nya.<br/>',NULL,64031,3);
INSERT INTO stanza VALUES('I735','3','Dengar dan percayalah,<br/>Yesus Juru-s''lamat,<br/>Kurnia kes''lamatan-Nya,<br/>t''rimalah sekarang.<br/>Dia damba menolongmu,<br/>t''lah lama menunggu,<br/>Percaya tanpa ragu,<br/>kau selamat!<br/>',NULL,64032,4);
INSERT INTO stanza VALUES('I736','1','Di lembah dosa berk''lana,<br/>jiwaku merana;<br/>Sejak Kristus diam dalamku,<br/>aku sentosalah.<br/>',NULL,64033,1);
INSERT INTO stanza VALUES('I736','chorus','Tuhan-ku, mulialah!<br/>Kini aku t''lah nampak, haleluya!<br/>Tuhan-ku, mulialah!<br/>Kini aku t''lah nampak!<br/>',NULL,64034,2);
INSERT INTO stanza VALUES('I736','2','Mataku Tuhan celikkan,<br/>ku nampak mulia-Nya;<br/>Kasih-Nya padaku indah,<br/>sungguh tak terkata.<br/>',NULL,64035,3);
INSERT INTO stanza VALUES('I736','3','Darah indah sandaranku,<br/>biar ku menang s''lalu;<br/>Tiada bandingan, Yesus-ku,<br/>Dia jantung hatiku.<br/>',NULL,64036,4);
INSERT INTO stanza VALUES('I737','1','Ku berdosa dan nista,<br/>duka dan merana,<br/>Dia memanggil ku datang<br/>dengan sikap ramah;<br/>Para malaikat giranglah,<br/>kurnia-Nya tiada bandingan.<br/>',NULL,64037,1);
INSERT INTO stanza VALUES('I737','chorus','Panggilan kasih-Nya!<br/>Tebusan darah-Nya!<br/>Kurnia-Nya membawaku datang!<br/>Kurnia-Nya membawaku datang!<br/>',NULL,64038,2);
INSERT INTO stanza VALUES('I737','2','Diriku penuh bilur,<br/>Dia urap d''ngan minyak;<br/>Firman-Nya yang menghibur,<br/>"Kau milik-Ku s''lama!"<br/>Tiada suara kian mesra,<br/>menghibur hati yang duka.<br/>',NULL,64039,3);
INSERT INTO stanza VALUES('I737','3','Dia dipaku, ditombak,<br/>darah, air tercurah;<br/>Tajuk duri menyengat,<br/>terhina, tersiksa;<br/>Apa kebaikan beta,<br/>hingga Dia mau korban jiwa?<br/>',NULL,64040,4);
INSERT INTO stanza VALUES('I737','4','Ku duduk di depan-Nya,<br/>menatap wajah-Nya,<br/>Ku kenangkan kurnia-Nya,<br/>dengan penuh syukur;<br/>Selamanya tak''kan cukup<br/>waktu untuk memuji Dia.<br/>',NULL,64041,5);
INSERT INTO stanza VALUES('I737','5','Biar waktu berkejaran,<br/>ku nikmat perhentian,<br/>Ku harap ''rekah fajar<br/>yang paling gemilang,<br/>Ku terpanggil ke sisi-Nya,<br/>berdampingan selamanya.<br/>',NULL,64042,6);
INSERT INTO stanza VALUES('I738','1','Kurnia yang s''lamatkanku,<br/>betapa limpah ruah,<br/>Kurnia yang s''lamatkanku,<br/>tidak terkata!<br/>',NULL,64043,1);
INSERT INTO stanza VALUES('I738','chorus','Tuhan orak rantaiku,<br/>Tuhan orak rantaiku,<br/>Hingga ku lepas bebas<br/>dengan sempurna!<br/>',NULL,64044,2);
INSERT INTO stanza VALUES('I738','2','Dosaku Kau ampunkan,<br/>hatiku sentosalah,<br/>Kini ku telah bebas<br/>dengan sempurna!<br/>',NULL,64045,3);
INSERT INTO stanza VALUES('I738','3','Dosa maupun godaan,<br/>dunia maupun setan,<br/>Penyakit maupun d''rita,<br/>sudah tak daya!<br/>',NULL,64046,4);
INSERT INTO stanza VALUES('I738','4','Haleluya!<br/>Nama-Nya sungguh harum dan manis,<br/>Haleluya!<br/>Nama-Nya s''lalu ku puji!<br/>',NULL,64047,5);
INSERT INTO stanza VALUES('I738','5','Ku sorak, "Haleluya!"<br/>Ku sorak, "Haleluya!"<br/>Ku sorak, "Haleluya!"<br/>Ku, Dia bebaskan!<br/>',NULL,64048,6);
INSERT INTO stanza VALUES('I739','1','Di salib Tuhan korban jiwa,<br/>darah berkuasa basuh dosa;<br/>Darah adi basuhku bersih,<br/>mulia bagi-Nya!<br/>',NULL,64049,1);
INSERT INTO stanza VALUES('I739','chorus','Mulia bagi-Nya!<br/>Mulia bagi-Nya!<br/>Darah adi basuhku bersih,<br/>mulia bagi-Nya!<br/>',NULL,64050,2);
INSERT INTO stanza VALUES('I739','2','Di salib Tuhan beri kurnia,<br/>darah adi basuh s''mua dosa;<br/>Pembasuhan ajaib pun manis,<br/>mulia bagi-Nya!<br/>',NULL,64051,3);
INSERT INTO stanza VALUES('I739','3','Sungguh bersih aku dibasuh,<br/>kini aku seputih salju!<br/>Darah s''lalu membuatku unggul,<br/>mulia bagi-Nya!<br/>',NULL,64052,4);
INSERT INTO stanza VALUES('I739','4','Mari terjun ke sumber ini,<br/>s''rahkan dirimu kepada-Nya,<br/>Kini datang, kini sempurna,<br/>mulia bagi-Nya!<br/>',NULL,64053,5);
INSERT INTO stanza VALUES('I740','1','Mengitari kubur-Mu,<br/>kami semua kumpul,<br/>Mulut penuh pujian,<br/>siar perbuatan-Mu.<br/>Dengan iman ikut-Mu,<br/>menempuh jalan-Mu,<br/>Lewat air baptisan,<br/>masuki karya-Mu.<br/>',NULL,64054,1);
INSERT INTO stanza VALUES('I740','2','Ya Yesus, kami ingat,<br/>derita jiwa-Mu,<br/>Kar''na menolong kami,<br/>badai menerpa-Mu.<br/>Dibaptis dalam maut,<br/>berdarah bagiku,<br/>Tinggalkan surga ''tuk ku,<br/>serahkan nyawa-Mu.<br/>',NULL,64055,2);
INSERT INTO stanza VALUES('I740','3','Tuhan, Kau telah bangkit,<br/>gelap telah lewat,<br/>Kini Kau duduk takhta,<br/>hidup selamanya.<br/>Dosa, maut, neraka,<br/>telah Kau kalahkan,<br/>Kar''na Kau hayat kami,<br/>bersama-Mu menang.<br/>',NULL,64056,3);
INSERT INTO stanza VALUES('I740','4','Dibaptis dalam maut,<br/>mati bersama-Mu,<br/>Pula bangkit dengan-Mu,<br/>berbagian mulia-Mu.<br/>Iblis, dunia, dan dosa,<br/>tak bisa jamahku,<br/>Kini jadi musafir,<br/>hidup bersama-Mu.<br/>',NULL,64057,4);
INSERT INTO stanza VALUES('I741','1','Kristus mati ku serta,<br/>aku terendam air dengan Dia;<br/>Biar dunia, Iblis ganas,<br/>kini t''lah hilang sirna kuasanya.<br/>Kristus bangkit ku serta,<br/>keluar dari air, hidup serta-Nya,<br/>Hayat dan Roh Kudus kuat,<br/>berkat dan kemuliaan berlimpah.<br/>',NULL,64058,1);
INSERT INTO stanza VALUES('I742','1','Saat masuk dalam air,<br/>mati bersama-Mu,<br/>Nilai rahmat dan kurnia-Mu,<br/>wahyukan padaku.<br/>',NULL,64059,1);
INSERT INTO stanza VALUES('I742','2','Lewat air masuk maut,<br/>dengan-Mu dikubur,<br/>Sudah mati bagi dosa,<br/>lepas s''mua belenggu.<br/>',NULL,64060,2);
INSERT INTO stanza VALUES('I742','3','Lewat air masuk maut,<br/>dengan-Mu dikubur,<br/>Dengan dunia ku terpisah,<br/>lepas raja dunia.<br/>',NULL,64061,3);
INSERT INTO stanza VALUES('I742','4','Bangkit bersama dengan-Mu,<br/>lepas kuasa maut,<br/>Menghasilkan buah kudus,<br/>tampil hayat baru.<br/>',NULL,64062,4);
INSERT INTO stanza VALUES('I742','5','Dibaptis dalam nama-Mu,<br/>tak lagi milikku,<br/>Hidup bagi-Mu, oleh-Mu,<br/>kekal esa d''ngan-Mu.<br/>',NULL,64063,5);
INSERT INTO stanza VALUES('I743','1','Sudah mati dan dikubur!<br/>Sejak kini ku sudah tamat!<br/>Sudah mati dan dikubur!<br/>Sejak kini ku sudah tamat!<br/>',NULL,64064,1);
INSERT INTO stanza VALUES('I743','2','Sudah tamat semuanya!<br/>Sejak kini ku sudah tamat!<br/>Sudah tamat semuanya!<br/>Sejak kini ku sudah tamat!<br/>',NULL,64065,2);
INSERT INTO stanza VALUES('I743','3','Bukan aku! Bukan aku!<br/>Tapi Kristus hidup dalamku!<br/>Bukan aku! Bukan aku!<br/>Tapi Kristus hidup dalamku!<br/>',NULL,64066,3);
INSERT INTO stanza VALUES('I744','1','"B''roleh s''lamat demi air",<br/>Tuhan beri wahyu,<br/>Agar ku ta''u kurnia tinggi,<br/>sempurna tolongku.<br/>',NULL,64067,1);
INSERT INTO stanza VALUES('I744','2','Demi air dunia lucut,<br/>pindah alam baru,<br/>Masa lampau kini tutup,<br/>dalam air terkubur.<br/>',NULL,64068,2);
INSERT INTO stanza VALUES('I744','3','Nuh ditolong oleh air bah,<br/>lepas zaman itu,<br/>Kini demi salib Tuhan,<br/>ku pisah d''ngan dunia.<br/>',NULL,64069,3);
INSERT INTO stanza VALUES('I744','4','Air laut tolong Israel,<br/>lepas kuasa Mesir,<br/>Kini juga tolong kami,<br/>dari cengk''ram dunia.<br/>',NULL,64070,4);
INSERT INTO stanza VALUES('I744','5','Demi air ku terorak,<br/>sungguh bebas, mulia,<br/>Terlepas ikatan dunia,<br/>sakit, duka, setan.<br/>',NULL,64071,5);
INSERT INTO stanza VALUES('I744','6','Demi air ku milik-Nya,<br/>bukan milik dunia,<br/>Sembah, bakti sungguh bah''gia,<br/>kuduslah bagi-Nya.<br/>',NULL,64072,6);
INSERT INTO stanza VALUES('I745','1','K''rajaan, daulat Allah,<br/>jaga mulia Allah,<br/>Kedaulatan kuasa-Nya,<br/>tunjang tatanan-Nya.<br/>Allah melaksanakan<br/>s''luruh wewenang-Nya,<br/>Mengatur k''rajaan-Nya,<br/>sampai selamanya.<br/>',NULL,64073,1);
INSERT INTO stanza VALUES('I745','2','Takhta, pusat k''rajaan,<br/>atasnya Dia daulat,<br/>Segala diatur-Nya,<br/>sesuai kehendak-Nya.<br/>Dia Sang Maharaja,<br/>s''mua dikendali-Nya,<br/>Status Raja pun Tuan,<br/>bawahi segala.<br/>',NULL,64074,2);
INSERT INTO stanza VALUES('I745','3','Demi pem''rintahan-Nya,<br/>maksud Allah genap,<br/>Di bawah kuasa-Nya,<br/>hasrat-Nya tergenap.<br/>Hanya dalam k''rajaan,<br/>berkat-Nya ternyata,<br/>Dari takhta kuasa-Nya,<br/>''ngalir arus hayat.<br/>',NULL,64075,3);
INSERT INTO stanza VALUES('I745','4','Tunduk pada kuasa-Nya,<br/>dasar t''rima berkat,<br/>Berontak kepada-Nya,<br/>itu akar dosa.<br/>Tujuan jahat Iblis,<br/>gulingkan takhta-Nya,<br/>Tujuan kita justru,<br/>''nyatakan kuasa-Nya.<br/>',NULL,64076,4);
INSERT INTO stanza VALUES('I745','5','Dalam kerajaan-Nya,<br/>Kristus diperbesar,<br/>Saat Kristus mem''rintah,<br/>Bapa dimuliakan.<br/>Saat Allah berkuasa,<br/>semua bahagia,<br/>Saat Kristus mem''rintah,<br/>mulia-Nya ternyata.<br/>',NULL,64077,5);
INSERT INTO stanza VALUES('I745','6','Dalam keg''napan waktu,<br/>Kristus-lah Kepala,<br/>Semua mengenal-Nya,<br/>patuh kuasa-Nya.<br/>Mem''rintah dalam hayat,<br/>gereja mengecap,<br/>K''rajaan seg''ra nyata,<br/>semua t''rima berkat.<br/>',NULL,64078,6);
INSERT INTO stanza VALUES('I746','1','K''rajaan Allah di bumi,<br/>Allah berdaulat di hati,<br/>Kristus hidup di dalamku,<br/>menjadi Tuhan, Rajaku.<br/>',NULL,64079,1);
INSERT INTO stanza VALUES('I746','2','Hayat Krsitus dan kuasa-Nya,<br/>''nobatkan Dia di hatiku,<br/>Mengatur s''luruh bagianku,<br/>juga tutur dan tingkahku.<br/>',NULL,64080,2);
INSERT INTO stanza VALUES('I746','3','Kristus bertakhta di hati,<br/>kerajaan-Nya berdiri,<br/>Dia berhak memerintah,<br/>genapkan tujuan Allah.<br/>',NULL,64081,3);
INSERT INTO stanza VALUES('I746','4','Memerintah dalam hati,<br/>suplaikan hayat tak henti,<br/>T''rima Dia Tuhan Raja,<br/>limpah Allah ku nikmati.<br/>',NULL,64082,4);
INSERT INTO stanza VALUES('I746','5','Oleh pem''rintahan batin,<br/>kepenuhan-Nya tertampil,<br/>Saat Dia memerintah,<br/>Tubuh Kristus terbangunlah.<br/>',NULL,64083,5);
INSERT INTO stanza VALUES('I746','6','Oleh kendali surgawi,<br/>kita jadi warga surga,<br/>Oleh patuh kuasa-Nya,<br/>kerajaan-Nya ternyata.<br/>',NULL,64084,6);
INSERT INTO stanza VALUES('I746','7','Dalam wilayah surgawi,<br/>memiliki kuasa surga,<br/>Hidup, perang, dalam terang,<br/>sampai k''rajaan ternyata.<br/>',NULL,64085,7);
INSERT INTO stanza VALUES('I747','1','Tuntutan kerajaan-Nya,<br/>lebih berat dari Taurat,<br/>Tiada lagi permintaan<br/>lebih tinggi dari ini.<br/>',NULL,64086,1);
INSERT INTO stanza VALUES('I747','2','K''rajaan dekat, bertobatlah,<br/>ini tuntutan pertama,<br/>Pikiran harus berpaling<br/>dan berpihak pada Allah.<br/>',NULL,64087,2);
INSERT INTO stanza VALUES('I747','3','Untuk masuk kerajaan,<br/>perlu kebenaran unggul,<br/>Yang berasal dari hayat,<br/>melampaui hukum Taurat.<br/>',NULL,64088,3);
INSERT INTO stanza VALUES('I747','4','Untuk masuk kerajaan,<br/>perlu lakukan murad-Nya,<br/>Bukan turut pilihanku,<br/>tapi turut kehendak-Nya.<br/>',NULL,64089,4);
INSERT INTO stanza VALUES('I747','5','Untuk masuk kerajaan,<br/>harus jadi s''perti anak,<br/>Tulus, taat, lemah lembut,<br/>tiada puas, bangga awak.<br/>',NULL,64090,5);
INSERT INTO stanza VALUES('I747','6','Kerajaan pun menuntut,<br/>kita sempurna p''ri Allah,<br/>Standar ini harus genap,<br/>kerajaan-Nya ternyata.<br/>',NULL,64091,6);
INSERT INTO stanza VALUES('I747','7','Kerajaan, Allah kuasa,<br/>sesuai dengan sifat-Nya,<br/>Hanya dengan hayat Allah,<br/>dapat masuk ke dalamnya.<br/>',NULL,64092,7);
INSERT INTO stanza VALUES('I747','8','Kerajaan nan surgawi,<br/>sesuai suasana surga,<br/>Jika ingin berbagian,<br/>harus punya hayat surga.<br/>',NULL,64093,8);
INSERT INTO stanza VALUES('I748','1','Realitas kerajaan ialah<br/>hidup sesuai surga,<br/>Hidup bersifat ilahi,<br/>biarkan Kristus tampil nyata.<br/>',NULL,64094,1);
INSERT INTO stanza VALUES('I748','2','Hidup yang miskin dalam roh,<br/>hati damba, duka, lembut,<br/>T''radap orang penuh rahmat,<br/>t''radap Allah murni, tulus.<br/>',NULL,64095,2);
INSERT INTO stanza VALUES('I748','3','Anak Allah, bawa damai,<br/>demi adil, menderita,<br/>Bagi Yesus disakiti,<br/>senantiasa sukacita.<br/>',NULL,64096,3);
INSERT INTO stanza VALUES('I748','4','Bagai garam bunuh kuman,<br/>juga terang sorot gelap,<br/>Hati, tindak, lurus, jujur,<br/>hanya kasih, tidak benci.<br/>',NULL,64097,4);
INSERT INTO stanza VALUES('I748','5','Tolak sombong, bangga diri,<br/>doa untuk kerajaan,<br/>Cari dulu K''rajaan Allah,<br/>setiap hal sandar Allah.<br/>',NULL,64098,5);
INSERT INTO stanza VALUES('I748','6','Ketat terhadap sendiri,<br/>lapang terhadap lain orang,<br/>Mutlak sesuai standar ini,<br/>realitas kerajaan.<br/>',NULL,64099,6);
INSERT INTO stanza VALUES('I748','7','T''radap setan tak mengalah,<br/>tolak juga kasih dunia,<br/>Hanya taat daulat surga,<br/>mutlak t''rima kuasa Allah.<br/>',NULL,64100,7);
INSERT INTO stanza VALUES('I748','8','Ini taklukkan semua,<br/>oleh kuat kuasa Allah,<br/>Desak kedatangan Tuhan,<br/>datangkan berkat k''rajaan.<br/>',NULL,64101,8);
INSERT INTO stanza VALUES('I749','1','Lihat, sungguh mulia,<br/>s''marak! K''rajaan Surga nyata!<br/>Raja mulia, Kristus Allah,<br/>dilantik oleh Allah.<br/>Dalam daging, Ia merendah,<br/>ditolak manusia,<br/>Kini datang dalam mulia,<br/>rampungkan kerajaan.<br/>',NULL,64102,1);
INSERT INTO stanza VALUES('I749','2','Mewarisi kerajaan, kuasa,<br/>Allah Sang Kekal,<br/>Datang dengan kerajaan,<br/>mulia terekspresikan.<br/>"Batu non ciptaan insan"<br/>hancurkan bangsa-bangsa,<br/>Jadi gunung tinggi besar,<br/>tampilkan kerajaan.<br/>',NULL,64103,2);
INSERT INTO stanza VALUES('I749','3','Semua k''rajaan di bumi,<br/>menjadi milik Tuhan,<br/>Di bawah kedaulatan-Nya,<br/>penuh damai sentosa.<br/>Tiada perang, tiada benci,<br/>tiada lagi medan p''rang,<br/>Bumi p''nuh peng''nalan Allah,<br/>bagai air p''nuhi lautan.<br/>',NULL,64104,3);
INSERT INTO stanza VALUES('I749','4','S''mua orang Kristen pemenang<br/>meraja bersama-Nya,<br/>Sisa Israel yang s''lamat,<br/>mendapatkan imamat.<br/>Bangsa-bangsa jadi rakyat,<br/>Dip''rintah pun diajar,<br/>Semua makhluk ciptaan,<br/>dipulihkan mulia.<br/>',NULL,64105,4);
INSERT INTO stanza VALUES('I749','5','Iblis diikat, dicampak,<br/>bumi bebas darinya,<br/>Di bawah Kristus, Kepala,<br/>bumi penuhlah berkat.<br/>S''gala takluk pada Kristus,<br/>patuh p''rintah, atur-Nya,<br/>Dia Kepala, Inti s''gala,<br/>genapkan murad Allah.<br/>',NULL,64106,5);
INSERT INTO stanza VALUES('I750','1','Putra Allah jadi benih,<br/>tabur diri dalam insan,<br/>Agar kerajaan tumbuh,<br/>merampungkan kehendak-Nya.<br/>',NULL,64107,1);
INSERT INTO stanza VALUES('I750','2','Dia butir biji gandum,<br/>banyak butir dihasilkan,<br/>Jadi anak kerajaan,<br/>tampilkan pem''rintahan-Nya.<br/>',NULL,64108,2);
INSERT INTO stanza VALUES('I750','3','Tapi Iblis, musuh Allah,<br/>menaburkan benih lalang,<br/>Kacaukan anak k''rajaan,<br/>mendatangkan kerusakan.<br/>',NULL,64109,3);
INSERT INTO stanza VALUES('I750','4','Kar''na perbuatan liciknya,<br/>campurkan gandum dan lalang,<br/>Penampilan kerajaan,<br/>jadi abnormal, membesar.<br/>',NULL,64110,4);
INSERT INTO stanza VALUES('I750','5','Kerajaan p''ri sesawi,<br/>sayur kecil, ''tuk dimakan,<br/>Tapi b''rubah jadi pohon,<br/>sistem besar, meraksasa.<br/>',NULL,64111,5);
INSERT INTO stanza VALUES('I750','6','Bukan lagi ''tuk dimakan,<br/>tapi jadi sarang burung,<br/>Tempat orang-orang jahat,<br/>bahkan roh jahat bernaung.<br/>',NULL,64112,6);
INSERT INTO stanza VALUES('I750','7','Agama besar di dunia,<br/>bentuk luarnya ''nyatakan,<br/>Meliputi hal-hal jahat,<br/>p''ri ragi dalam adonan.<br/>',NULL,64113,7);
INSERT INTO stanza VALUES('I750','8','Sistem dunia demikian,<br/>berubah wujud lahirnya,<br/>Serap barang-barang jahat,<br/>mendatangkan kebobrokan.<br/>',NULL,64114,8);
INSERT INTO stanza VALUES('I750','9','Allah cari yang sembunyi,<br/>p''ri mutiara atau harta,<br/>Tuhan ''kan mengubah kita,<br/>agar mutiara ternyata.<br/>',NULL,64115,9);
INSERT INTO stanza VALUES('I750','10','Jauh dari yang abnormal,<br/>megah kerajaan dunia,<br/>Namun dalam realitas,<br/>serupa Kristus dan Allah.<br/>',NULL,64116,10);
INSERT INTO stanza VALUES('I750','11','Tuhan lepaskanlah kami,<br/>dari lalang, pohon besar,<br/>Pula singkir semua ragi,<br/>hingga kami tulus, murni.<br/>',NULL,64117,11);
INSERT INTO stanza VALUES('I750','12','Ubah kami d''ngan hayat-Mu,<br/>menjadi bahan berharga,<br/>Membawa realitas-Mu,<br/>sepadan dengan rumah-Mu.<br/>',NULL,64118,12);
INSERT INTO stanza VALUES('I751','1','Sekarang k''rajaan suatu latihan,<br/>Saat Kristus mem''rintah, jadi pahala.<br/>Ini hikmat Allah, kini latih kita,<br/>Rampungkan rencana-Nya, tampil adil-Nya.<br/>',NULL,64119,1);
INSERT INTO stanza VALUES('I751','2','Lahir dari Allah, untuk meraja,<br/>Masih perlu dilatih, jadi pemenang.<br/>Bisa memerintah dalam k''rajaan-Nya,<br/>Agar kerajaan-Nya nyata sempurna.<br/>',NULL,64120,2);
INSERT INTO stanza VALUES('I751','3','Sekarang belajar taat kuasa-Nya,<br/>Dengan ketat tanggulangi tutur, tindak.<br/>Demikian kita berbagian, kuasa-Nya,<br/>Memerintah bangsa bersama Putra-Nya.<br/>',NULL,64121,3);
INSERT INTO stanza VALUES('I751','4','Menempuh hidup ketat, adil, benar,<br/>Lapang t''radap orang, girang t''radap Allah.<br/>''Tiasa hidup dalam realitas k''rajaan,<br/>Bersiap untuk tampil dan memerintah.<br/>',NULL,64122,4);
INSERT INTO stanza VALUES('I751','5','Bila Kristus datang d''ngan k''rajaan-Nya,<br/>Beri jabatan raja s''bagai pahala.<br/>Demikian ekspresikan keadilan-Nya,<br/>''Nyatakan hikmat-Nya kepada malaikat.<br/>',NULL,64123,5);
INSERT INTO stanza VALUES('I751','6','Untuk hal ini rasul giat maju,<br/>Bayar s''gala harga, tidak mau tertinggal.<br/>Kar''na ini juga, dia anjuri kita,<br/>Agar k''rajaan jadi pahala kita.<br/>',NULL,64124,6);
INSERT INTO stanza VALUES('I751','7','Tuhan, beri kurnia, demi k''rajaan,<br/>Berlatih agar Kau memberi pahala.<br/>Realitas k''rajaan, latihan kita,<br/>Manifestasinya menjadi pahala.<br/>',NULL,64125,7);
INSERT INTO stanza VALUES('I752','1','Yesus b''ri pah''la pada hamba-Nya,<br/>entah siang ''tau malam,<br/>Sediakah kita saat datang-Nya?<br/>Pelita ada minyak?<br/>',NULL,64126,1);
INSERT INTO stanza VALUES('I752','chorus','Bisakah ku bilang sudah siap,<br/>menghadap wajah Tuhan?<br/>Tak terlelap di saat balik-Nya,<br/>tetap tunggu kedatangan-Nya?<br/>',NULL,64127,2);
INSERT INTO stanza VALUES('I752','2','Fajar tiba, hitungan dibentang,<br/>tiap nama dipanggil,<br/>Serahkan talenta masing-masing,<br/>dapatkah pujian-Nya?<br/>',NULL,64128,3);
INSERT INTO stanza VALUES('I752','3','Setiakah pada amanat-Nya,<br/>tunaikan sekuatnya?<br/>Jika hati tiada suara cela,<br/>kita pasti diangkat.<br/>',NULL,64129,4);
INSERT INTO stanza VALUES('I752','4','Bahagia bagi yang waspada,<br/>meraja bersama-Nya,<br/>Saat Dia datang, entah kapan,<br/>sedang jagakah kita?<br/>',NULL,64130,5);
INSERT INTO stanza VALUES('I753','1','Ya, Yesus, aku rindu<br/>terangkat depan-Mu,<br/>Kecuali kembali-Mu,<br/>tiada mesraku.<br/>Kembali-Mu ku tunggu,<br/>walaupun tak jauh,<br/>Ku rasakan hadir-Mu<br/>k''lilingi hatiku.<br/>',NULL,64131,1);
INSERT INTO stanza VALUES('I753','2','Pada lubuk batinku,<br/>dengar suara-Mu,<br/>Ku bersyukur pada-Mu,<br/>atas rencana-Mu.<br/>Sudah dekat datang-Mu,<br/>sg''ra tampil diri-Mu!<br/>Waktu hanya sejurus,<br/>musuh hancur lebur!<br/>',NULL,64132,2);
INSERT INTO stanza VALUES('I753','3','Tebas habis, ya Tuhan,<br/>biar ku leluasa,<br/>Lucut tali gendala,<br/>ikut Kau tak renggang.<br/>Lepas perkara "halal",<br/>agar tak terikat,<br/>Jangan saat Kau datang,<br/>ku masih terpancang.<br/>',NULL,64133,3);
INSERT INTO stanza VALUES('I753','4','Siaga senantiasa,<br/>inilah minatku,<br/>Taat roh sepenuhnya,<br/>kelak ku terangkat.<br/>Jangan kar''na terlena,<br/>mengantuk, tertidur,<br/>Hingga ku tidak layak,<br/>malahan dihukum.<br/>',NULL,64134,4);
INSERT INTO stanza VALUES('I753','5','Hai hatiku, sadarlah!<br/>Ini sungguh serius,<br/>Buang s''mua berhalamu,<br/>campakkan seluruh.<br/>Damba Tuhan melulu,<br/>pun rindu bertemu,<br/>Saat Tuhan memanggil,<br/>ku tak bimbang ragu.<br/>',NULL,64135,5);
INSERT INTO stanza VALUES('I753','6','Meskipun perang sengit,<br/>ulah Iblis keji,<br/>Sejenak Dia lantik,<br/>mengapakah jeri?<br/>Gelap kini bertambah,<br/>hari tebus dekat,<br/>Menunggu sambil harap,<br/>Tuhan seg''ra datang.<br/>',NULL,64136,6);
INSERT INTO stanza VALUES('I753','7','Moga hanya Tuhan yang<br/>ku pikir, ku cinta,<br/>olak suap dunia,<br/>hatiku Kau saja.<br/>Ikat bumi melonggar,<br/>datanglah ya Tuhan,<br/>T''rangkat naik ku damba,<br/>jumpa Tuhan sayang.<br/>',NULL,64137,7);
INSERT INTO stanza VALUES('I754','1','Waktu Tuhan datang pula,<br/>sangkakala terdengar,<br/>yang mati bangkit,<br/>hayat telan maut;<br/>Tuhan turun dari surga,<br/>para malak bersorak,<br/>yang hidup t''rangkat,<br/>tubuh b''rubah rupa.<br/>',NULL,64138,1);
INSERT INTO stanza VALUES('I754','chorus','Tuhan turun dari surga,<br/>ku ''kan nampak mulia-Nya;<br/>Tubuh saleh ditebus-Nya,<br/>di dalamnya aku ada.<br/>',NULL,64139,2);
INSERT INTO stanza VALUES('I754','2','Waktu Tuhan datang pula,<br/>terang fajar merekah,<br/>Malam sirna,<br/>tangisan pun usailah;<br/>Tuhan turun dari surga,<br/>hari mulia datanglah,<br/>Kuasa jahat lenyap,<br/>keluh hilanglah.<br/>',NULL,64140,3);
INSERT INTO stanza VALUES('I754','3','Waktu Tuhan datang pula,<br/>Bintang Fajar cemerlang,<br/>Mahkota bagi yang<br/>siaga dan setia;<br/>Tuhan turun dari surga,<br/>Surya Adil berkuasa,<br/>Terbangunlah genap<br/>alam semesta.<br/>',NULL,64141,4);
INSERT INTO stanza VALUES('I754','4','Tuhan seg''ra datang pula,<br/>yang menunggu, siagalah!<br/>Ikat pinggang kencang,<br/>dian berkobar;<br/>Tuhan seg''ra datang pula,<br/>layanilah d''ngan setia,<br/>Fungsikan talenta,<br/>jangan dipendam.<br/>',NULL,64142,5);
INSERT INTO stanza VALUES('I755','1','Kristus seg''ra datang, waktu t''lah dekat;<br/>Derap kaki-Nya kami dengar.<br/>Bangun, umat saleh! Siap siaga!<br/>Jumpa Tuhan, sungguh gembira!<br/>',NULL,64143,1);
INSERT INTO stanza VALUES('I755','chorus','Mulia! Mulia! Kristus sg''ra datang!<br/>Mulia! Mulia! Kita bergirang!<br/>Tubuh b''rubah mulia, serupa Tuhan,<br/>Bebas mulia, nikmat serta-Nya.<br/>',NULL,64144,2);
INSERT INTO stanza VALUES('I755','2','Kristus datang, Bintang Fajar ternyata,<br/>malam telah larut, sg''ra fajar.<br/>Bangun, umat saleh! Janganlah lengah!<br/>Agar luput dari bencana.<br/>',NULL,64145,3);
INSERT INTO stanza VALUES('I755','3','Kristus seg''ra datang, bawa pahala,<br/>dan mahkota bagi hamba-Nya.<br/>Bangun, umat saleh! Buang dunia!<br/>Genap hati cinta pada-Nya.<br/>',NULL,64146,4);
INSERT INTO stanza VALUES('I755','4','Kristus seg''ra datang, menjadi Raja,<br/>lawan Iblis, s''lamatkan bangsa.<br/>Bangun, umat saleh! Maju ke depan,<br/>jadi raja, betapa mulia!<br/>',NULL,64147,5);
INSERT INTO stanza VALUES('I756','1','Rajaku hampirlah tiba,<br/>udara t''lah p''nuh Dia!<br/>Alam s''mesta terpulihkan,<br/>tebusan t''lah genap!<br/>Derap langkah-Nya ku dengar,<br/>dari dalam awan;<br/>Bayangan tubuh mulia-Nya,<br/>ku nampak di surga.<br/>',NULL,64148,1);
INSERT INTO stanza VALUES('I756','2','Ku harap Tuhan beserta,<br/>tak berani lengah;<br/>Ku nantikan Dia s''gra tiba,<br/>harapanku nyata.<br/>Kecuali Dia seg''ra tiba,<br/>bawaku serta-Nya,<br/>Tiada perkara lainnya<br/>yang aku dambakan.<br/>',NULL,64149,2);
INSERT INTO stanza VALUES('I756','3','Saat ku pandang Tuhan-ku,<br/>hatiku terpikat;<br/>Tiada lain yang ku dambakan,<br/>jumpa Dia belaka.<br/>Kedatangan-Nya t''lah dekat,<br/>untukku datang-Nya;<br/>Janji-Nya teguh s''lamanya,<br/>tidak pernah sia-sia.<br/>',NULL,64150,3);
INSERT INTO stanza VALUES('I756','4','Sungguhlah Tuhan, firman-Mu,<br/>kudus lagi jitu;<br/>Ku mau setia tanpa malu,<br/>demilah firman-Mu.<br/>Moga mulia-Mu sg''ra nyata,<br/>Iblis, musuh kalah;<br/>Moga janji-Mu tergenap,<br/>sambut aku pulang.<br/>',NULL,64151,4);
INSERT INTO stanza VALUES('I756','5','Lengan-Mu tempat berlindung,<br/>ya, Yesus, P''nolongku!<br/>Yang berlindung kepada-Mu,<br/>Kau b''rikan naungan-Mu.<br/>Domba, senasib gembala,<br/>p''ri tubuh, Kepala!<br/>Siapa pun mustahil m''rebut<br/>umat yang Kau tebus.<br/>',NULL,64152,5);
INSERT INTO stanza VALUES('I756','6','Berlaksa tangan dan mata,<br/>bukan halanganku;<br/>Bahkan duri ''kan membantu,<br/>ku maju d''ngan gagah.<br/>Bangunlah hati dan rohku,<br/>biarkan dunia lewat!<br/>Tuhan hayatku, datanglah!<br/>Bawa aku pulang!<br/>',NULL,64153,6);
INSERT INTO stanza VALUES('I756','7','Kesembuhan dan harapan,<br/>ku cinta sinar-Mu;<br/>Raja adil, Tuhan mulia,<br/>ku sujud depan-Mu.<br/>Moga Kau seg''ra naik takhta,<br/>''nyatakan wajah-Mu!<br/>K''rajaan Surga tegaklah,<br/>Kau curah kurnia-Mu!<br/>',NULL,64154,7);
INSERT INTO stanza VALUES('I756','8','Keb''naran dan Kebebasan,<br/>harus jadi Raja!<br/>Tapi dusta t''lah mengganas,<br/>menguasai dunia!<br/>Kar''nanya mohon Kau datang,<br/>bawa sinar surga!<br/>Agar musuh seg''ra kalah,<br/>umat-Mu berbah''gia!<br/>',NULL,64155,8);
INSERT INTO stanza VALUES('I757','1','Ku lupakah Dia sg''ra tiba?<br/>Tidak! Aku rindu ''tiasa;<br/>Bagi Dia ku mohon Bapa,<br/>Bagi Dia ku nyanyi riang.<br/>',NULL,64156,1);
INSERT INTO stanza VALUES('I757','chorus','Tuhan, datanglah!<br/>Rajaku, datanglah sg''ra!<br/>',NULL,64157,2);
INSERT INTO stanza VALUES('I757','2','Apa mungkin aku lengah?<br/>Tidak! Siang malam ku jaga!<br/>Agar aku bisa t''rangkat,<br/>mewah dunia tak mengikat.<br/>',NULL,64158,3);
INSERT INTO stanza VALUES('I757','3','Apa ku terpikat dunia?<br/>Tidak! Ku tetap pandang Dia!<br/>Ku mau lepas jerat dunia,<br/>hanya cinta, kenang Tuhan.<br/>',NULL,64159,4);
INSERT INTO stanza VALUES('I757','4','Moga ku hidup dalam roh,<br/>sesap hayat, tenaga-Nya,<br/>Berjaga hingga Dia datang,<br/>sejenak pun tidak lengah.<br/>',NULL,64160,5);
INSERT INTO stanza VALUES('I757','5','Moga ku tak takut musuh,<br/>makin hari makin teguh,<br/>Alam maut pasti runtuh,<br/>Kristus Allah daulat penuh.<br/>',NULL,64161,6);
INSERT INTO stanza VALUES('I757','6','Ku tak lupa b''rita ini,<br/>Kristus menang, itu pasti,<br/>Hingga genap iman kita,<br/>firman-Nya seg''ra terbukti.<br/>',NULL,64162,7);
INSERT INTO stanza VALUES('I758','1','Sejak kita berpisah di Baitani,<br/>hati hampa, tiada yang mengisi;<br/>Petik gitar, ku ingin hibur diri,<br/>tiada Kau di sisi, hati pedih.<br/>Malam sunyi, ku termenung sendiri,<br/>meski tiada rumit, hati menangis.<br/>Oh, Kekasih, berapa lama lagi?<br/>Bilakah janji-Mu akan terbukti?<br/>',NULL,64163,1);
INSERT INTO stanza VALUES('I758','2','Ingat malaf, ku lupa rumah dunia,<br/>nampak salib, gemarku pun hilang,<br/>Yang ku harap hanya Kau seg''ra datang,<br/>yang ku rindu Kekasihku b''laka.<br/>Tanpa Engkau, kesenangan pun hambar,<br/>kidung merdu bahkan membuat duka.<br/>Kau tak hadir, hatiku taklah puas, Tuhan,<br/>mari datang! Jangan Kau tunda.<br/>',NULL,64164,2);
INSERT INTO stanza VALUES('I758','3','Meski penyertaan-Mu ku nikmati,<br/>tapi tetaplah kurang di hati;<br/>Terang dan sayang s''lalu Kau cukupi,<br/>tapi rasa tak puas itu masih!<br/>Dalam damai, hati bahkan kian sepi,<br/>waktu senang, keluh kesah tak henti,<br/>Semua sedia, tetap kosong di hati,<br/>kar''na wajah-Mu belum ku nikmati.<br/>',NULL,64165,3);
INSERT INTO stanza VALUES('I758','4','Pelancong idamkan kampung halaman!<br/>Tawanan rindukan tanah airnya!<br/>Kekasih terpisah, hati tak karuan,<br/>anak berjauhan, rindu ''kan rumah.<br/>Tapi rinduku pada-Mu, ya, Tuhan,<br/>melebihi keadaan mereka;<br/>Kini wajah-Mu b''lum dapat ku pandang,<br/>haruskah ku tunggu sambil k''luh kesah?<br/>',NULL,64166,4);
INSERT INTO stanza VALUES('I758','5','Tuhan, lupakah Kau akan janji-Mu,<br/>Kau ''kan balik, menjemputku pulang?<br/>Hari lepas hari, tahun pun lewat,<br/>ku menunggu, Kau tak kunjung datang.<br/>Tuhan, ingatlah, lelah ku menunggu,<br/>tapi kaki-Mu b''lum juga melangakah!<br/>B''rapa lama aku harus menunggu,<br/>janji-Mu genap, aku pun terangkat?<br/>',NULL,64167,5);
INSERT INTO stanza VALUES('I758','6','Matahari terbit, ''benam, berulang,<br/>kaum saleh pun bernasib demikian,<br/>Satu demi satu semuanya lewat, tunggu,<br/>tunggu, kapankah Kau datang?<br/>O, Tuhan-ku, mengapa Kau tetap diam?<br/>Langit tertutup, bayang-Mu tak nampak;<br/>Kami tunggu, tunggu, tunggu ''tiasa,<br/>kami tunggu, masa b''lum cukup lama?<br/>',NULL,64168,6);
INSERT INTO stanza VALUES('I758','7','Bila ingat lama nian ku menunggu,<br/>Tak tertahan, air mata tercucur,<br/>Kabulkan doaku s''karang, ya Tuhan,<br/>datanglah sg''ra, ajak aku pulang.<br/>Mari Tuhan, gereja-Mu berseru!<br/>Mari Tuhan, kaum saleh pun mendesak!<br/>Dengar, suara hamba-Mu kian menderu:<br/>Tuhan! Mari datang! Jangan Kau tunda!<br/>',NULL,64169,7);
INSERT INTO stanza VALUES('I759','1','Bila Tuhan ''kan datang pula?<br/>Ku s''lalu mendambakan-Nya!<br/>Bila ku ''kan nampak mulia-Nya,<br/>berjumpa d''ngan jantung hatiku?<br/>Ya, Tuhan-ku, sg''ra datanglah!<br/>Agar hatiku dapat penghiburan!<br/>Ku menunggu sampai s''karang,<br/>dan ingin beserta-Mu!<br/>',NULL,64170,1);
INSERT INTO stanza VALUES('I760','1','Sejak berpisah di Bukit Zaitun,<br/>belum pernah Tuhan memanggilku;<br/>Lama nian ku rindu nampak wajah-Mu,<br/>agaknya doaku tak Kau dengar.<br/>',NULL,64171,1);
INSERT INTO stanza VALUES('I760','chorus','Mari, Tuhan!<br/>Mohon Kau seg''ra datang!<br/>Hatiku rindu Kau segera datang,<br/>Tuhan datanglah seg''ra!<br/>',NULL,64172,2);
INSERT INTO stanza VALUES('I760','2','Tuhan, sejak hari Dikau terangkat,<br/>di sini jadi hambar, kersang s''mua;<br/>Ku s''lalu berjaga sambil berdoa,<br/>tiap gemersik, ku sangka Kau datang.<br/>',NULL,64173,3);
INSERT INTO stanza VALUES('I760','3','Tamasya, indah, - bila kita jumpa?<br/>Burung berkicau, bunga semerbak,<br/>Sedikit pun tak menarik hatiku,<br/>karena ku rindukan wajah-Mu.<br/>',NULL,64174,4);
INSERT INTO stanza VALUES('I760','4','Tuhan, ku tunggu Kau hingga gelisah,<br/>entah harus tunggu sampai kapan,<br/>Sepanjang hari dan sepanjang malam,<br/>tiap waktu harap Kau seg''ra datang.<br/>',NULL,64175,5);
INSERT INTO stanza VALUES('I760','5','Tiap turun hujan, angin menderu,<br/>bulan purnama, air laut pasang,<br/>Harap Kau datang pada waktu itu,<br/>tapi sayang, Kau tak kunjung datang.<br/>',NULL,64176,6);
INSERT INTO stanza VALUES('I760','6','Bila ku tak ingat akan janji-Mu,<br/>lama sudah putus harapanku,<br/>Tapi Kau pesan biar ku sambil tunggu<br/>sambil giat kerja, hidup bagi-Mu.<br/>',NULL,64177,7);
INSERT INTO stanza VALUES('I760','7','Tuhan, ingatlah sudah cukup lama,<br/>janji-Mu belum juga ternyata,<br/>Harap dan harap, harapkan ''tiasa,<br/>datang seg''ra, datanglah sekarang!<br/>',NULL,64178,8);
INSERT INTO stanza VALUES('I761','1','Ya, Yesus! Ya, Yesus!<br/>M''ngapa tak datang?<br/>Ya, Yesus! Ya, Yesus!<br/>Kapan Kau datang?<br/>S''mua makhluk menunggu,<br/>harinya tiba,<br/>Kami pun mengharap,<br/>Kau seg''ra datang,<br/>Alam s''mesta kini,<br/>usang pun tua,<br/>kami s''mua berdoa,<br/>Datanglah seg''ra,<br/>datanglah seg''ra,<br/>datanglah seg''ra.<br/>',NULL,64179,1);
INSERT INTO stanza VALUES('I761','2','Ya, Yesus! Ya, Yesus!<br/>M''ngapa tak datang?<br/>Mengapa Kau tunda,<br/>s''karang b''lum datang?<br/>Tahun demi tahun,<br/>kami menunggu;<br/>Gen''rasi berganti,<br/>kami pun ''nunggu,<br/>Mengapa Kau tak<br/>singkat hari itu,<br/>kami s''mua berseru,<br/>Janganlah tunda,<br/>janganlah tunda,<br/>janganlah tunda.<br/>',NULL,64180,2);
INSERT INTO stanza VALUES('I761','3','Ya, Yesus! Ya, Yesus!<br/>M''ngapa tak datang?<br/>Sejak Kau terangkat,<br/>hatiku hampa,<br/>Langitku seolah<br/>tak lagi cerah,<br/>Wajahku seolah<br/>tak lagi riang;<br/>Semua ambisi lenyaplah kini.<br/>Ya, Yesus!<br/>Ya, Yesus!<br/>M''ngapa tak datang?<br/>M''ngapa tak datang?<br/>M''ngapa tak datang?<br/>',NULL,64181,3);
INSERT INTO stanza VALUES('I761','4','Datanglah! Datanglah!<br/>Lihatlah seg''ra!<br/>Banyak yang t''lah undur,<br/>tawar, berubah,<br/>Kasih t''lah menghambar,<br/>d''rita tak rela,<br/>Iman makin goyah,<br/>langkah makin b''rat,<br/>Harapan kian luntur,<br/>ingin tak ''nunggu,<br/>ya, Yesus! Lihatlah!<br/>M''ngapa tak datang?<br/>M''ngapa tak datang?<br/>M''ngapa tak datang?<br/>',NULL,64182,4);
INSERT INTO stanza VALUES('I761','5','Ya, Yesus! Ya, Yesus!<br/>M''ngapa tak datang?<br/>Ya, Yesus! Ya, Yesus!<br/>M''ngapa tak datang?<br/>B''rapa lama lagi<br/>harus menunggu?<br/>Berdoa, berjaga,<br/>hampir tak mampu?<br/>Ya, Yesus! Ya, Yesus!<br/>Mohon Kau datang!<br/>Ya, Yesus! Ya, Yesus!<br/>Datanglah seg''ra!<br/>Datanglah seg''ra!<br/>Datanglah seg''ra!<br/>',NULL,64183,5);
INSERT INTO stanza VALUES('I762','1','Tuhan, ku menunggu balik-Mu,<br/>t''rus menunggu,<br/>Seolah ''nunggu tiada akhir,<br/>terus ku menunggu.<br/>Ku rindu memandang wajah-Mu,<br/>d''ngar suara-Mu,<br/>Ku damba sekutu dengan-Mu,<br/>beserta-Mu s''lalu.<br/>',NULL,64184,1);
INSERT INTO stanza VALUES('I762','chorus','Haruskah menunggu t''rus,<br/>tahun lewat tahun?<br/>Haruskah air mata tercucur,<br/>baru muncul hadir-Mu?<br/>',NULL,64185,2);
INSERT INTO stanza VALUES('I762','2','Tak sedihkah janda mengenang,<br/>masa lampau?<br/>Ingin jumpa, tapi tak dapat,<br/>hati sungguh risau!<br/>Tidakkah ia sakit asmara,<br/>rindukan Dia?<br/>Hari nikah tak kunjung tiba,<br/>hati pun gelisah.<br/>',NULL,64186,3);
INSERT INTO stanza VALUES('I762','3','Gereja menunggu balik-Mu,<br/>sejak dulu,<br/>Abad demi abad t''lah lewat,<br/>Kau tak juga datang.<br/>Sejak remaja hingga tua,<br/>ku menunggu,<br/>Hari demi hari pun lewat,<br/>Kau masih b''lum datang.<br/>',NULL,64187,4);
INSERT INTO stanza VALUES('I762','4','Penat dan lelah ku menunggu,<br/>ya, Tuhan-ku,<br/>Ujian datang menggoyahkanku,<br/>Tuhan, ingatlahku.<br/>Tuhan, jangan lagi Kau tunda,<br/>ya, datanglah,<br/>Hingga kini ku t''rus bersabar,<br/>janganlah Kau lambat.<br/>',NULL,64188,5);
INSERT INTO stanza VALUES('I762','5','Tuhan, ingatlah penantianku,<br/>ku tak tahan,<br/>Bila Kau tak segera datang,<br/>biarlah ku ke sana.<br/>Lama Kau tidak juga datang,<br/>diam di sana,<br/>Orang lain menertawakan,<br/>"Kau memang tak datang."<br/>',NULL,64189,6);
INSERT INTO stanza VALUES('I762','6','Semua duka d''rita hatiku,<br/>tak terlerai,<br/>Siapa pun tak dapat membantu,<br/>kar''na Kau tak serta.<br/>Saat Kau datang dalam mulia,<br/>baru ku puas,<br/>Semua d''rita ''kan ku lupakan,<br/>saat kita jumpa.<br/>',NULL,64190,7);
INSERT INTO stanza VALUES('I763','1','Kristus, harapan mulia, Dia-lah hayatku;<br/>Lahirkan ku kembali dan ubah jiwaku;<br/>Dengan kuat kuasa-Nya mengubah tubuhku,<br/>Hingga menjadi mulia, p''ri tubuh-Nya.<br/>',NULL,64191,1);
INSERT INTO stanza VALUES('I763','chorus','Dia datang, ubahku mulia!<br/>Tubuhku diubah rupa, serupa tubuh-Nya.<br/>Dia datang, untukku datang-Nya!<br/>Dia-lah harapan mulia, muliakan kita.<br/>',NULL,64192,2);
INSERT INTO stanza VALUES('I763','2','Kristus harapan mulia, Dia rahasia Allah;<br/>Bawa Allah padaku, jadi bagianku,<br/>Dia datang, baurkanku dengan diri Allah,<br/>Berbagian mulia-Nya, pantulkan Dia.<br/>',NULL,64193,3);
INSERT INTO stanza VALUES('I763','3','Kristus harapan mulia, Dia-lah Penebusku;<br/>Dia menebus tubuhku, lepas d''rita, maut.<br/>Dia mengubah tubuhku, jadi tubuh mulia;<br/>Kekal menelan maut, bebaskanku.<br/>',NULL,64194,4);
INSERT INTO stanza VALUES('I763','4','Kristus, harapan mulia, Dia-lah riwayatku;<br/>Ku alami hayat-Nya, Dia esa denganku;<br/>Dia bawa ku masuk kebebasan, mulia,<br/>Mutlak esa dengan-Nya hingga kekal.<br/>',NULL,64195,5);
INSERT INTO stanza VALUES('I764','1','Misteri berabad, kini tersingkap,<br/>Kristus mulia, realitas Allah,<br/>Perwujudan Allah, Dia-lah hayatku,<br/>jadi mulia, pengharapanku.<br/>',NULL,64196,1);
INSERT INTO stanza VALUES('I764','chorus','Mulia, mulia, Kristus dalamku!<br/>Mulia, mulia, Dia harapanku!<br/>Kini dalam rohku, rahasia itu!<br/>Kelak pasti jadi muliaku.<br/>',NULL,64197,2);
INSERT INTO stanza VALUES('I764','2','Lahirkan kembali, di dalam rohku,<br/>mengubahku dalam jiwaku,<br/>Pun ubah tubuhku s''perti tubuh-Nya,<br/>menjadi serupa dengan-Nya.<br/>',NULL,64198,3);
INSERT INTO stanza VALUES('I764','3','Sehayat, sesifat kini denganku,<br/>kelak ku di dalam mulia-Nya,<br/>Nikmati hadir-Nya sampai s''lamanya,<br/>dengan Tuhan mutlak serupa.<br/>',NULL,64199,4);
INSERT INTO stanza VALUES('I765','1','Waktu Tuhan datang lagi,<br/>hilanglah semua yang sedih;<br/>Dengan g''nap S''rani ikut Dia,<br/>puji Tuhan!<br/>Puji Tuhan!<br/>Puji Tuhan!<br/>Dengan g''nap S''rani ikut Dia,<br/>puji Tuhan!<br/>',NULL,64200,1);
INSERT INTO stanza VALUES('I765','2','Waktu jumpa Tuhan lagi,<br/>tinggal serta-Nya abadi;<br/>Hati riang mulut bernyanyi,<br/>puji Tuhan!<br/>Puji Tuhan!<br/>Puji Tuhan!<br/>Hati riang mulut bernyanyi,<br/>puji Tuhan!<br/>',NULL,64201,2);
INSERT INTO stanza VALUES('I765','3','Saat jumpa di angkasa,<br/>d''rita salib, ringan sudah;<br/>Jumpa Tuhan sungguh senang,<br/>puji Tuhan!<br/>Puji Tuhan!<br/>Puji Tuhan!<br/>Jumpa Tuhan sungguh senang,<br/>puji Tuhan!<br/>',NULL,64202,3);
INSERT INTO stanza VALUES('I765','4','Waktu itu ''kan terbukti:<br/>hayat Tuhan menang pasti,<br/>Dengan girang ku bernyanyi,<br/>puji Tuhan!<br/>Puji Tuhan!<br/>Puji Tuhan!<br/>Dengan girang ku bernyanyi,<br/>puji Tuhan!<br/>',NULL,64203,4);
INSERT INTO stanza VALUES('I765','5','Di sela tulang rusuk-Nya,<br/>kita bersatu tak pisah,<br/>Hingga Tuhan puas hati,<br/>Dia sg''ra datang!<br/>Dia sg''ra datang!<br/>Dia sg''ra datang!<br/>Hingga Tuhan puas hati,<br/>Dia sg''ra datang!<br/>',NULL,64204,5);
INSERT INTO stanza VALUES('I765','6','Ya, Rajaku mari datang!<br/>Kami sangat menantikan,<br/>Bawakan pahala indah,<br/>mari datang!<br/>Mari datang!<br/>Mari datang!<br/>Bawakah pahala indah,<br/>mari datang!<br/>',NULL,64205,6);
INSERT INTO stanza VALUES('I766','1','Harapan mulia, Kristus sg''ra datang!<br/>Ku ''kan diangkat, masuk mulia;<br/>Beserta Tuhan nikmat indah-Nya;<br/>Sungguhlah agung karunia-Nya.<br/>',NULL,64206,1);
INSERT INTO stanza VALUES('I766','chorus','Sungguh mulia, Kristus datang!<br/>Sungguh mulia, Kristus datang!<br/>Ku ''kan diangkat, masuk mulia,<br/>Harapan mulia, Kristus sg''ra datang!<br/>',NULL,64207,2);
INSERT INTO stanza VALUES('I766','2','Harapan mulia, Kristus sg''ra datang!<br/>Yang lama lalu, datang yang baru;<br/>Tiada keluhan, tiada sengsara;<br/>Baru ku nikmat, kur-nia agung-Nya.<br/>',NULL,64208,3);
INSERT INTO stanza VALUES('I766','3','Harapan mulia, Kristus sg''ra datang!<br/>Jadi raja berkuasa serta-Nya;<br/>Pun jadi imam Allah Sang Hayat;<br/>Mahatinggilah karunia-Nya.<br/>',NULL,64209,4);
INSERT INTO stanza VALUES('I766','4','Harapan mulia, Kristus sg''ra datang!<br/>Sabar menanti, setia mengabdi;<br/>Minyak sedia, jalan tak lengah;<br/>Baru ku patut t''rima pahala.<br/>',NULL,64210,5);
INSERT INTO stanza VALUES('I767','1','Semua makhluk pada tunggu,<br/>anak Allah ternyata,<br/>Bila tiba, saat itu,<br/>mereka pun bebaslah.<br/>',NULL,64211,1);
INSERT INTO stanza VALUES('I767','2','Semua makhluk ''ngeluh,<br/>takluk kepada kesia-siaan,<br/>Harap dapat bebas mutlak<br/>dari kebinasaan.<br/>',NULL,64212,2);
INSERT INTO stanza VALUES('I767','3','Bahkan kita juga ''ngeluh,<br/>sampai kita dewasa,<br/>Saat ini, kita tumbuh,<br/>dengan Kristus serupa.<br/>',NULL,64213,3);
INSERT INTO stanza VALUES('I767','4','Kar''na ini Roh berkesah,<br/>biar kita serupa Dia,<br/>Segala hal, kerja sama,<br/>agar kita diubah.<br/>',NULL,64214,4);
INSERT INTO stanza VALUES('I767','5','Allah bawa kita masuk,<br/>masuk ke dalam mulia,<br/>Diresapi oleh Dia,<br/>tentu kudus semua.<br/>',NULL,64215,5);
INSERT INTO stanza VALUES('I767','6','Semua makhluk akan bebas,<br/>dalam bebas yang mulia,<br/>Anak baring pinggir macan,<br/>singa lembu bersama.<br/>',NULL,64216,6);
INSERT INTO stanza VALUES('I767','7','Bila kita akil balig,<br/>miliki warisan-Nya,<br/>Bersama-Nya dimuliakan,<br/>mengekspresikan Allah.<br/>',NULL,64217,7);
INSERT INTO stanza VALUES('I768','1','Inti pikiran Allah,<br/>Dia satu d''ngan manusia,<br/>S''gala bagi manusia,<br/>rencana-Nya tergenap.<br/>',NULL,64218,1);
INSERT INTO stanza VALUES('I768','2','Manusia, wadah tanah,<br/>ada roh, jiwa, raga,<br/>T''rima Allah, hayat-Nya,<br/>esa mutlak dengan-Nya.<br/>',NULL,64219,2);
INSERT INTO stanza VALUES('I768','3','Demi aliran hayat,<br/>insan jadi permata,<br/>Bahan bangunan Allah,<br/>ekspresikan mulia-Nya.<br/>',NULL,64220,3);
INSERT INTO stanza VALUES('I768','4','Kota yang Allah bangun,<br/>tempat kediaman-Nya,<br/>Yerusalem yang baru,<br/>yang rampungkan hasrat-Nya.<br/>',NULL,64221,4);
INSERT INTO stanza VALUES('I768','5','Pembangunan kaum saleh,<br/>bauran Allah manusia,<br/>Oleh kehendak Bapa,<br/>Allah manusia puas.<br/>',NULL,64222,5);
INSERT INTO stanza VALUES('I768','6','Takhta Allah dan Domba,<br/>dalam tempat mulia,<br/>Dari pusat kuasa-Nya,<br/>mengalir sungai hayat.<br/>',NULL,64223,6);
INSERT INTO stanza VALUES('I768','7','Kristus, Sang Pohon Hayat,<br/>tumbuh di sungai hayat,<br/>Hasilkan buah hayat,<br/>suplai makanan hayat.<br/>',NULL,64224,7);
INSERT INTO stanza VALUES('I768','8','Allah di dalam Kristus,<br/>terpancar dari kota,<br/>Usir malam g''lap maut<br/>dengan terang hayat-Nya.<br/>',NULL,64225,8);
INSERT INTO stanza VALUES('I768','9','Allah dengan manusia,<br/>saling huni, bersama,<br/>Allah - isi manusia,<br/>manusia - tampil Allah.<br/>',NULL,64226,9);
INSERT INTO stanza VALUES('I769','1','Hasrat kekal Allah,<br/>esa d''ngan insan,<br/>insan wadah Allah,<br/>tampung diri-Nya,<br/>Jadi hayat insan,<br/>penuh meluap,<br/>insan ''nyatakan Dia,<br/>esa dengan-Nya.<br/>',NULL,64227,1);
INSERT INTO stanza VALUES('I769','2','Menurut gambar-Nya,<br/>ciptakan insan,<br/>agar insan bisa<br/>capai maksud-Nya;<br/>Allah diterima p''ri<br/>pohon hayat,<br/>jadi kep''nuhan-Nya,<br/>pula istri-Nya.<br/>',NULL,64228,2);
INSERT INTO stanza VALUES('I769','3','Dalam aliran-Nya,<br/>insan diubah,<br/>menjadi permata,<br/>serupa Dia.<br/>Insan dibangunkan,<br/>jadi jodoh-Nya,<br/>jadi kediaman-Nya,<br/>puaskan hati-Nya.<br/>',NULL,64229,3);
INSERT INTO stanza VALUES('I769','4','Ini kota kudus,<br/>Salem yang baru,<br/>Allah - umat, baur,<br/>bangun rumah-Nya.<br/>Allah isi m''reka,<br/>m''reka tampil-Nya,<br/>berbagian mulia-Nya,<br/>esa dengan-Nya.<br/>',NULL,64230,4);
INSERT INTO stanza VALUES('I769','5','Allah-lah pusatnya,<br/>m''rintah di takhta,<br/>dengan kuasa hayat,<br/>umat terjaga.<br/>Dengan terang mulia,<br/>umat benderang,<br/>nikmati harmonis,<br/>nyata mulia-Nya.<br/>',NULL,64231,5);
INSERT INTO stanza VALUES('I769','6','Allah - air hayat,<br/>makanan hayat,<br/>lapar dan dahaga,<br/>Dia puaskan.<br/>Dia bait m''reka,<br/>kediaman m''reka,<br/>di dalam hadir-Nya,<br/>kekal menyembah.<br/>',NULL,64232,6);
INSERT INTO stanza VALUES('I770','1','Tuhan, Salem hasil rancang-Mu;<br/>Disediakan untuk orang yang tertebus;<br/>Semua orang yang terbasuh darah;<br/>Diberi kuasa masuk ke dalamnya.<br/>Kemilaunya saja, menarik nian;<br/>Terlebih Dikau tinggal di dalamnya!<br/>Mana mungkin tak menarik pandangan?<br/>Tanpa sengaja pun s''lalu terkenang.<br/>',NULL,64233,1);
INSERT INTO stanza VALUES('I770','2','Tuhan, tiap ingat pada Salem,<br/>Pandang wajah-Mu hati sangat rindukan,<br/>Hati berharap segera terangkat,<br/>Bersanding dengan-Mu lebih dinian.<br/>Menuju tempat baru ku dambakan,<br/>Dengan pencinta-Mu curahkah cinta,<br/>Memuji kasih-Mu tiada batas,<br/>Mengenang kasih yang ikhlas berkorban.<br/>',NULL,64234,2);
INSERT INTO stanza VALUES('I770','3','Tuhan, yang ku suka pun damba,<br/>Bukan batu permata pun bukan emas,<br/>Tapi diri-Mu, Tuhan Pengasihku!<br/>Kau menarik sungguh, pikat hatiku!<br/>Mohon Kau seg''ra kabulkan minatku,<br/>Terangkat depan-Mu, tak lagi pisah,<br/>Tinggal bersama sampai selamanya,<br/>Pandang wajah-Mu, dengar suara-Mu.<br/>',NULL,64235,3);
INSERT INTO stanza VALUES('I770','4','Salem - kasih, terang, pujian,<br/>Tuhan-lah justru pusat dan pahalanya;<br/>Diri-Mu dan pamor-Mu di dalamnya,<br/>Salem bagiku jadilah harapan!<br/>Ada diri-Mu, jadi baru semua,<br/>Keluhan lewat, air mata terseka,<br/>Penuh perhentian dan sukacita,<br/>Tuhan, mengapa Kau tak seg''ra datang?<br/>',NULL,64236,4);
INSERT INTO stanza VALUES('I771','1','Tinggal dalam kemah, memandang kota;<br/>Berjalan d''ngan cepat, musafir surga;<br/>Luhur harapannya, agung tujuannya;<br/>Hingga mewah dunia, tidak ia suka.<br/>',NULL,64237,1);
INSERT INTO stanza VALUES('I771','chorus','Kota yang indah!<br/>Kediaman Allah,<br/>insan - Yerusalem!<br/>',NULL,64238,2);
INSERT INTO stanza VALUES('I771','2','Pada kota Allah, mata memandang,<br/>Hingga rumah dunia, tidak ia kenang;<br/>Kar''na Allah janji kota surgawi,<br/>Bagilah musafir yang setia hati.<br/>',NULL,64239,3);
INSERT INTO stanza VALUES('I771','3','Meski hati gundah, hidup sengsara,<br/>Dalam perjalanan ada k''luh kesah;<br/>Bila ingat kota, seg''ra bergita,<br/>Meski jalan sempit, segra ''kan tiba.<br/>',NULL,64240,4);
INSERT INTO stanza VALUES('I771','4','Kami bersama dia, pandang ke kota,<br/>Moga kami seg''ra serta-Mu ''tiasa;<br/>Nikmati segala yang t''lah Kau sedia,<br/>Kar''na kami rela mend''rita s''karang.<br/>',NULL,64241,5);
INSERT INTO stanza VALUES('I772','1','Kota dan Tuhan, sasaran kita,<br/>bagian kita, megah pun mulia,<br/>Meski tubuh hidup di buana,<br/>roh kita bersama Tuhan mulia,<br/>roh kita bersama Tuhan mulia.<br/>',NULL,64242,1);
INSERT INTO stanza VALUES('I772','2','Yerusalem Baru - tujuan kita,<br/>kota kudus, Allah - manusia,<br/>Semua orang yang tertebus darah,<br/>berhak nikmati berkat bahagia,<br/>Berhak nikmati berkat bahagia.<br/>',NULL,64243,2);
INSERT INTO stanza VALUES('I772','3','Tiap mengenangkan kota kudus,<br/>hati rindu memandang wajah-Nya,<br/>Damba mendengar panggilan Tuhan,<br/>masuki kota, nikmat limpah-Nya,<br/>Masuki kota, nikmat limpah-Nya.<br/>',NULL,64244,3);
INSERT INTO stanza VALUES('I772','4','Bukan harap perhentian yang manis,<br/>bukan pula kecap berkat dunia,<br/>Tapi diri-Mu, harapan mulia,<br/>bagian kekal dan pahalaku,<br/>Bagian kekal dan pahalaku.<br/>',NULL,64245,4);
INSERT INTO stanza VALUES('I772','5','Ya, Tuhan Yesus, dengar doaku,<br/>datanglah! Bawa kami ke kota,<br/>Di dalam kota nikmat diri-Mu,<br/>saling huni, mulia, selamanya,<br/>Saling huni, mulia, selamanya.<br/>',NULL,64246,5);
INSERT INTO stanza VALUES('I772','6','"Aku membuat semuanya baru",<br/>langit, bumi, manusia baru,<br/>Allah mulia, bagian kekalku,<br/>o, saat mulia, Tuhan, datanglah!<br/>O, saat mulia, Tuhan, datanglah!<br/>',NULL,64247,6);
INSERT INTO stanza VALUES('I773','1','Saat ku capai akhir penempuhan pertempuran;<br/>ku pasti diangkat masuk mulia;<br/>Atas iman pegang firman,<br/>walau sahid tak ingkar;<br/>Pasti t''rima pahala.<br/>',NULL,64248,1);
INSERT INTO stanza VALUES('I773','chorus','Ku pasti masuk mulia,<br/>serta Tuhan selamanya,<br/>Di Yerusalem,<br/>di Yerusalem,<br/>Genap saleh bersorak, nyanyi puji nama Tuhan,<br/>Di Yerusalem baru!<br/>',NULL,64249,2);
INSERT INTO stanza VALUES('I773','2','Meski kini ada d''rita, hati tetap gembira;<br/>Kar''na kota lebih indah t''lah sedia,<br/>Meski handai taulan kejar dunia,<br/>ku tetap setia;<br/>Kota kudus t''lah sedia!<br/>',NULL,64250,3);
INSERT INTO stanza VALUES('I773','3','Meski jalan penuh liku, tangan, kaki pun penat;<br/>Ingat kota, t''naga pulih pun tegap;<br/>Meski air mata ''ngalir,<br/>hatiku tak putus asa;<br/>Kota kudus t''lah sedia!<br/>',NULL,64251,4);
INSERT INTO stanza VALUES('I773','4','Bukan tinju tempat kosong, atau lari membuta;<br/>Tapi seturut-Nya, tuntut yang terbaik;<br/>Lupa b''lakang, maju depan,<br/>menuju ke sasaran;<br/>Dapat mahkota mulia.<br/>',NULL,64252,5);
INSERT INTO stanza VALUES('I773','chorus','Kasih, kurnia berlimpah, membawaku nikmati Dia;<br/>Di Yerusalem,<br/>di Yerusalem!<br/>Genap saleh bersorak, nyanyi puji nama Tuhan,<br/>Di Yerusalem Baru!<br/>',NULL,64253,6);
INSERT INTO stanza VALUES('I774','1','Pada mulanya, sebuah taman,<br/>akhirnya jadi sebuah kota;<br/>Di taman, ialah ciptaan Allah,<br/>di kota, jadi bangunan Allah.<br/>',NULL,64254,1);
INSERT INTO stanza VALUES('I774','2','Di dalam taman atau di kota,<br/>terdapat sungai dan pohon hayat;<br/>Sungai lambangkan Roh alir hayat,<br/>pohon lambang Kristus suplai hayat.<br/>',NULL,64255,2);
INSERT INTO stanza VALUES('I774','3','Di dalam taman atau di kota,<br/>terdapat tiga benda berharga:<br/>Emas, mutiara dan permata,<br/>bagi bangunan, ekspresi Allah.<br/>',NULL,64256,3);
INSERT INTO stanza VALUES('I774','4','Di dalam taman, s''mua benda itu<br/>hanyalah bahan yang berserakan;<br/>Di dalam kota, semua terbangun,<br/>jadi kediaman-Nya yang mulia.<br/>',NULL,64257,4);
INSERT INTO stanza VALUES('I774','5','Di dalam taman, mutu manusia,<br/>milik tanah, tanpa mulia surga;<br/>Pohon hayat di luar manusia,<br/>b''lum jadi hayat yang mengubahnya.<br/>',NULL,64258,5);
INSERT INTO stanza VALUES('I774','6','Di dalam kota, hayat yang mulia,<br/>tumbuh dalam manusia korporat;<br/>Wahyukan Kristus sebagai hayat,<br/>menjadi suplai hayat manusia.<br/>',NULL,64259,6);
INSERT INTO stanza VALUES('I774','7','Bagi kota, manusia dicipta,<br/>lahir kembali pula diubah;<br/>Jadi emas, mutiara, permata,<br/>wujud Tubuh Kristus, serupa Dia.<br/>',NULL,64260,7);
INSERT INTO stanza VALUES('I774','8','Di dalam taman, mempelai p''rempuan:<br/>jodohnya Adam, dari iganya;<br/>Kota itu pun mempelai p''rempuan:<br/>keluapan Kristus, tampil limpah-Nya.<br/>',NULL,64261,8);
INSERT INTO stanza VALUES('I774','9','Kota itu hasil karya Allah,<br/>saleh terbangun, dalam roh satu;<br/>Jadi tempat kediaman Allah,<br/>pun mempelai kesayangan Kristus.<br/>',NULL,64262,9);
INSERT INTO stanza VALUES('I774','10','Ekspresi akhir Allah yang unggul,<br/>korporat, universal, sempurna;<br/>Mulia Allah mutlak ternyatakan,<br/>pasangan Kristus, mulia tak hingga.<br/>',NULL,64263,10);
INSERT INTO stanza VALUES('I775','1','Tuhan, umat yang Kau tebus:<br/>Tubuh-Mu, mempelai-Mu,<br/>Kep''nuhan-Mu, tampilan-Mu,<br/>ekspresikan limpah-Mu.<br/>Dikau, kekal segalanya,<br/>tersiarlah limpah-Mu,<br/>Penuh jenuhi dirinya,<br/>berbagian mulia-Mu.<br/>',NULL,64264,1);
INSERT INTO stanza VALUES('I775','chorus','Tengok, kota kudus!<br/>Penuh mulia Allah!<br/>Ekspresi sempurna<br/>Allah dalam manusia.<br/>',NULL,64265,2);
INSERT INTO stanza VALUES('I775','2','Rahasia agung ibadah,<br/>perbauran Allah insan,<br/>Mulia, limpah kaya Allah,<br/>nyata lewat manusia.<br/>Satu wadah universal,<br/>''nyatakan kep''nuhan-Nya,<br/>Tampilkan keindahan-Nya<br/>dengan kekudusan-Nya.<br/>',NULL,64266,3);
INSERT INTO stanza VALUES('I775','3','Satu susunan yang hidup,<br/>umat yang diubah-Nya,<br/>Bagai mutiara, permata,<br/>serupa d''ngan gambar-Nya.<br/>Dari takhta-Nya - pusatnya,<br/>mengalir air hayat,<br/>Kristus jadi pohon hayat,<br/>hasilkan buah hayat.<br/>',NULL,64267,4);
INSERT INTO stanza VALUES('I775','4','Kaki dian emas kekal,<br/>dengan Kristus, diannya,<br/>Dalam Kristus, Allah terang,<br/>bagai Roh yang memancar.<br/>Ekspresi akhir sempurna,<br/>bangunan Allah - insan,<br/>Tempat tinggal saling huni,<br/>sasaran kekal Allah.<br/>',NULL,64268,5);
INSERT INTO stanza VALUES('I776','1','Sungguh mulia! Sungguh terang!<br/>Kota kudus, Yerusalem!<br/>Kemah Allah tengah insan,<br/>mempelai Sang Anak Domba.<br/>',NULL,64269,1);
INSERT INTO stanza VALUES('I776','2','Umat Allah s''panjang zaman,<br/>unsur pembangunan kota,<br/>T''lah tertebus, t''rima janji,<br/>terbangunkan, Allah huni.<br/>',NULL,64270,2);
INSERT INTO stanza VALUES('I776','3','Kota kudus, mirip kubus,<br/>sama tinggi, panjang, lebar,<br/>Tak berlebih, panjang, pendek,<br/>tidak miring, lurus tegak.<br/>',NULL,64271,3);
INSERT INTO stanza VALUES('I776','4','Kota dengan jalan emas, bening,<br/>transparan p''ri kaca,<br/>Lambang hayat unggul Allah,<br/>itu sifat, mutu kota.<br/>',NULL,64272,4);
INSERT INTO stanza VALUES('I776','5','Pintu kota dua belas,<br/>tiap pintu mutiara,<br/>Lambang insan yang diubah,<br/>masuk dalam alam Allah.<br/>',NULL,64273,5);
INSERT INTO stanza VALUES('I776','6','Dua belas batu dasar,<br/>dua belas batu mulia,<br/>Lewat api dan tekanan,<br/>bahan berharga nan kekal.<br/>',NULL,64274,6);
INSERT INTO stanza VALUES('I776','7','Tembok kota yaspis jernih,<br/>pancarkan mulia Allah,<br/>Terang mulia-Nya gemerlap,<br/>nyata yaspis tampilan-Nya.<br/>',NULL,64275,7);
INSERT INTO stanza VALUES('I776','8','Tembok sebagai pemisah,<br/>sisihkan s''gala yang najis,<br/>Emas, mutiara, permata,<br/>itu saja isi kota.<br/>',NULL,64276,8);
INSERT INTO stanza VALUES('I776','9','Allah, Domba, jadi bait,<br/>tampilkan wajah mulia-Nya,<br/>Hadir-Nya tak pernah absen,<br/>kekal kami menyembah-Nya.<br/>',NULL,64277,9);
INSERT INTO stanza VALUES('I776','10','Tak perlu surya pun bulan,<br/>mulia Allah terangnya,<br/>Domba menjadi pelita,<br/>pancar terang s''mua jurusan.<br/>',NULL,64278,10);
INSERT INTO stanza VALUES('I776','11','Dari takhta Allah-Domba,<br/>''ngalir sungai air hayat,<br/>Di kedua tepiannya tumbuh<br/>pohon kehidupan.<br/>',NULL,64279,11);
INSERT INTO stanza VALUES('I776','12','Bukan sekadar makanan,<br/>atau air yang mengalir,<br/>Hayat Allah bawa kuasa,<br/>ke mana pun ia mengalir.<br/>',NULL,64280,12);
INSERT INTO stanza VALUES('I776','13','Jalan dari emas murni,<br/>sifat Allah kita tempuh,<br/>Air sungai jadi minuman,<br/>buah hayat segar, subur.<br/>',NULL,64281,13);
INSERT INTO stanza VALUES('I776','14','Dua belas angka kuasa,<br/>sempurna, pula abadi,<br/>Allah baur d''ngan manusia,<br/>angka tiga empat kali.<br/>',NULL,64282,14);
INSERT INTO stanza VALUES('I776','15','Tiada lagi gelap, maut,<br/>kutuk, pedih pun tersingkir,<br/>Usang sirna, ganti baru,<br/>Allah-insan saling huni.<br/>',NULL,64283,15);
INSERT INTO stanza VALUES('I776','16','Kota penuh gambar Allah,<br/>berkuasa bagi Raja,<br/>Genapkan rencana Allah,<br/>Allah puas hingga kekal.<br/>',NULL,64284,16);
INSERT INTO stanza VALUES('I777','1','Di langit, bumi baru,<br/>Yerusalem Baru,<br/>Berasal dari Allah,<br/>penuh terang Allah.<br/>',NULL,64285,1);
INSERT INTO stanza VALUES('I777','chorus','Padanya gambar Allah,<br/>dan juga mulia Allah,<br/>Meraja serta Tuhan,<br/>di kota kudus.<br/>',NULL,64286,2);
INSERT INTO stanza VALUES('I777','2','Jalan di tengah kota,<br/>murni dari emas,<br/>Batu dasar permata,<br/>pintu mutiara.<br/>',NULL,64287,3);
INSERT INTO stanza VALUES('I777','3','Sungai hayat p''ri kristal,<br/>''ngalir dalam kota;<br/>Pohon hayat di tepi,<br/>puaskan keperluan.<br/>',NULL,64288,4);
INSERT INTO stanza VALUES('I777','4','Allah Sang Segalanya,<br/>dalam kota terang;<br/>Anak Domba terangnya,<br/>tiada lagi malam.<br/>',NULL,64289,5);
INSERT INTO stanza VALUES('I778','1','Dalam seluruh Alkitab,<br/>banyak lambang kaum saleh,<br/>P''ri mempelai, Allah gemar,<br/>p''ri bangunan, Allah s''mayam.<br/>',NULL,64290,1);
INSERT INTO stanza VALUES('I778','2','Semua lambang gereja<br/>dalam Perjanjian Lama,<br/>Mempelai ''tuk kepuasan,<br/>bangunan ''tuk memerintah.<br/>',NULL,64291,2);
INSERT INTO stanza VALUES('I778','3','Umat Allah zaman dulu,<br/>disebut Allah "jodoh-Nya",<br/>Kota Allah, rumah Allah,<br/>terbangun di tengah m''reka.<br/>',NULL,64292,3);
INSERT INTO stanza VALUES('I778','4','Manusia - Allah, Sang Kristus,<br/>datang p''ri mempelai laki,<br/>D''ngan hayat-Nya, lahir ulang,<br/>insan menjadi jodoh-Nya.<br/>',NULL,64293,4);
INSERT INTO stanza VALUES('I778','5','Kristus dalam kebangkitan,<br/>p''ri Salomo bangun bait,<br/>Tempat Allah bersemayam,<br/>rampungkan s''mua kehendak-Nya.<br/>',NULL,64294,5);
INSERT INTO stanza VALUES('I778','6','Gereja mempelai Kristus,<br/>di dalamnya Dia bergemar,<br/>Tempat kediaman Allah,<br/>Allah s''mayam, tertampilkan.<br/>',NULL,64295,6);
INSERT INTO stanza VALUES('I778','7','Yerusalem Baru kelak,<br/>kegenapan yang sempurna,<br/>Dari lambang bait, memp''lai,<br/>merampungkan rencana-Nya.<br/>',NULL,64296,7);
INSERT INTO stanza VALUES('I778','8','Mempelai padanan Kristus,<br/>yang ekspresikan diri-Nya,<br/>Juga Tabernakel Allah,<br/>tempat s''mayam, memerintah.<br/>',NULL,64297,8);
INSERT INTO stanza VALUES('I778','9','Perampungan yang sempurna,<br/>karya Allah dalam insan,<br/>Ekspresi-Nya yang mulia,<br/>ilahi nan limpah kekal.<br/>',NULL,64298,9);
INSERT INTO stanza VALUES('I779','1','Kristus Kepala segala,<br/>itu ekonomi-Nya,<br/>T''rima Kristus Sang Kepala,<br/>semua padu mesra.<br/>',NULL,64299,1);
INSERT INTO stanza VALUES('I779','2','Kristus akan jadi pusat,<br/>Allah menjadi terang,<br/>Kristus dan Allah naik takhta,<br/>genapkan perkenan-Nya.<br/>',NULL,64300,2);
INSERT INTO stanza VALUES('I779','3','Kristus jadi hayat, isi,<br/>Kepala dalam terang,<br/>Kaum saleh jadi wadah-Nya,<br/>kekal tampil mulia-Nya.<br/>',NULL,64301,3);
INSERT INTO stanza VALUES('I779','4','Iblis sudah menyelinap,<br/>merusak manusia,<br/>Bawa gelap, bobrok, rusak,<br/>gagalkan rencana-Nya.<br/>',NULL,64302,4);
INSERT INTO stanza VALUES('I779','5','Kristus datang,<br/>menyalurkan diri-Nya s''bagai hayat,<br/>Agar kuasa maut, gelap,<br/>tak lagi memperdaya.<br/>',NULL,64303,5);
INSERT INTO stanza VALUES('I779','6','Lewat gereja, Tubuh-Nya,<br/>Kristus jadi Kepala,<br/>Semua berjalin rapi,<br/>perkara besar kecil.<br/>',NULL,64304,6);
INSERT INTO stanza VALUES('I779','7','Dengan Kristus Sang Kepala,<br/>semua jadi esa,<br/>Dalam sorot terang g''reja,<br/>semuanya esalah.<br/>',NULL,64305,7);
INSERT INTO stanza VALUES('I779','8','Kristus Kepala pun pusat,<br/>semua padu mesra,<br/>Lewat pancaran Tubuh-Nya,<br/>semua damai lega.<br/>',NULL,64306,8);
INSERT INTO stanza VALUES('I779','9','Tiada lagi rusak, gelap,<br/>maut, dan sia-sia,<br/>Semua belenggu terorak,<br/>sampai s''lama-lamanya.<br/>',NULL,64307,9);
INSERT INTO stanza VALUES('I780','1','Tak lagi di periuk,<br/>harta milik Allah,<br/>Dalam wadah terubah,<br/>Tuhan tampil indah.<br/>',NULL,64308,1);
INSERT INTO stanza VALUES('I780','2','Lewat bejana emas,<br/>mulia Allah pancar,<br/>Tidak perlu mentari,<br/>Allah jadi terang.<br/>',NULL,64309,2);
INSERT INTO stanza VALUES('I780','3','Permata dan mutiara,<br/>penuh indah mulia,<br/>Memancar bagai yaspis,<br/>mulia tak terkata.<br/>',NULL,64310,3);
INSERT INTO stanza VALUES('I780','4','Dalam bejana besar,<br/>mulia terang pancar,<br/>Pancar ke s''mua jurusan,<br/>singkir gelap dunia.<br/>',NULL,64311,4);
INSERT INTO stanza VALUES('I780','5','Dalam ciptaan baru,<br/>mulia-Nya tertampak,<br/>Mempelai Anak Domba,<br/>jadi pelita-Nya.<br/>',NULL,64312,5);
INSERT INTO stanza VALUES('I780','6','Bejana emas mulia,<br/>mulia bagi Allah,<br/>Allah di dalam Domba,<br/>ternyata s''lamanya.<br/>',NULL,64313,6);
INSERT INTO stanza VALUES('I781','1','Hormat, pujian,<br/>mulia bagi-Mu;<br/>Mulia bagi-Mu!<br/>Mulia bagi-Mu!<br/>Hormat, pujian,<br/>mulia bagi-Mu,<br/>sampai selamanya.<br/>Puji Tuhan!<br/>Mari menyembah Dia!<br/>Puji Tuhan!<br/>Sampai selamanya!<br/>Haleluya!<br/>',NULL,64314,1);
INSERT INTO stanza VALUES('I783','1','Langit kisahkan mulia-Nya,<br/>cakrawala siar ajaib-Nya,<br/>Siang, malam berbicara,<br/>sampai ke ujung buana.<br/>Kuasa kekal dan ciri-Nya<br/>dari ciptaan ternyata,<br/>Meski insan tak melihat,<br/>lewat ciptaan tertampak.<br/>',NULL,64315,1);
INSERT INTO stanza VALUES('I783','2','Allah Pencipta yang hidup,<br/>memberikan kurnia limpah;<br/>Mengenyangkan, menyukakan,<br/>agar diri-Nya ternyata.<br/>Langit, bumi beri berkat,<br/>berkat Allah hidup, benar;<br/>Cukup sandang, cukup pangan,<br/>ingatlah pada Pencipta.<br/>',NULL,64316,2);
INSERT INTO stanza VALUES('I783','3','Tuhan Allah alam s''mesta,<br/>beri hidup pada semua,<br/>Batas umur dan kediaman,<br/>Dia tentukan bagi insan.<br/>Agar insan mencari-Nya,<br/>tahu rah''sia alam s''mesta,<br/>Insan paham kebenaran,<br/>hargai makna alam s''mesta.<br/>',NULL,64317,3);
INSERT INTO stanza VALUES('I783','4','Allah tampakkan diri-Nya,<br/>wahyu ini belum lengkap,<br/>Status Allah, gambar Allah,<br/>masih perlu dinyatakan.<br/>Yesus Kristus,<br/>Putra Allah kenakan rupa manusia,<br/>Ciri dan hakiki Allah,<br/>diwujudkan oleh Dia.<br/>',NULL,64318,4);
INSERT INTO stanza VALUES('I783','5','Kristus Peny''lamat ajaib,<br/>perwujudan mulia Allah,<br/>Asal Allah nan tak batas,<br/>jadi insan dalam waktu.<br/>Kristus ajaib, jelmaan Allah,<br/>pembauran Allah insan,<br/>Allah s''jati, isan s''jati,<br/>masuk jadi bagian insan.<br/>',NULL,64319,5);
INSERT INTO stanza VALUES('I783','6','Sifat Allah di dalam-Nya,<br/>mulia Allah Dia tampilkan,<br/>Dalam daging g''nap tebusan,<br/>di roh kini d''ngan ku esa.<br/>Kristus, Allah inkarnasi,<br/>korban jiwa tolong insan,<br/>Mati, bangkit, menjadi Roh,<br/>masuk rohku jadi hayat.<br/>',NULL,64320,6);
INSERT INTO stanza VALUES('I784','1','Manusia wadah Allah,<br/>punya roh, jiwa, raga;<br/>Allah jadi isinya,<br/>''tuk wujudkan mulia-Nya.<br/>',NULL,64321,1);
INSERT INTO stanza VALUES('I784','2','Miliki gambar Allah,<br/>luhur sungguh statusnya;<br/>Masih perlu hayat-Nya,<br/>berbagian sifat-Nya.<br/>',NULL,64322,2);
INSERT INTO stanza VALUES('I784','3','Kristus-lah wujud Allah,<br/>mati, ''nebus manusia;<br/>Bangkit, jadi Roh hayat,<br/>masuk ke roh manusia.<br/>',NULL,64323,3);
INSERT INTO stanza VALUES('I784','4','Manusia tanpa Kristus,<br/>tentu hampa, melompong;<br/>Hidupnya tak bermakna,<br/>tanpa harap, tujuan.<br/>',NULL,64324,4);
INSERT INTO stanza VALUES('I784','5','T''rima Kristus Sang Hayat,<br/>lahir ulang dalam roh;<br/>S''lalu hidup demi Dia,<br/>hidup penuh pujian.<br/>',NULL,64325,5);
INSERT INTO stanza VALUES('I784','6','Demikian Dia ternyata,<br/>manusia dapat bah''gia;<br/>Alirkan sungai hayat,<br/>meleraikan dahaga.<br/>',NULL,64326,6);
INSERT INTO stanza VALUES('I784','7','Kristus dalam mulia,<br/>muliakan tubuh kita;<br/>Jadi serupa Dia,<br/>beserta Dia s''lamanya.<br/>',NULL,64327,7);
INSERT INTO stanza VALUES('I785','1','O, ajaib! O, misteri!<br/>Allah berbaur d''ngan manusia!<br/>Allah jadi manusia,<br/>biar manusia jadi Allah!<br/>Ekonomi nan misteri,<br/>yang tidak dapat diduga,<br/>Dari hasrat hati Allah,<br/>capai tujuan tertinggi-Nya.<br/>',NULL,64328,1);
INSERT INTO stanza VALUES('I785','2','Allah jadi manusia,<br/>agar aku "jadi Allah";<br/>Hayat, sifat sama d''ngan Dia,<br/>namun tanpa ke-Allah-an!<br/>Atribut-Nya-lah bajikku,<br/>citra mulia-Nya ku pancar!<br/>Atribut-Nya-lah bajikku,<br/>citra mulia-Nya ku pancar!<br/>',NULL,64329,2);
INSERT INTO stanza VALUES('I785','3','Bukan lagi aku hidup,<br/>tapi ku hidup dengan-Nya;<br/>D''ngan kaum saleh dibangunkan<br/>di dalam Allah Tritunggal;<br/>Jadi rumah semesta-Nya,<br/>juga Tubuh organik-Nya;<br/>Jadi wadah korporat-Nya,<br/>yang ekspresikan diri-Nya.<br/>',NULL,64330,3);
INSERT INTO stanza VALUES('I785','4','Kelak Yerusalem Baru,<br/>totalitas visi, wahyu; Allah<br/>Tritunggal, manusia,<br/>jadi pasangan yang kekal,<br/>Sifat Allah, sifat insan,<br/>saling huni, saling tinggal,<br/>Mulia Allah dalam insan,<br/>terpancar luas t''rang benderang.<br/>',NULL,64331,4);
INSERT INTO stanza VALUES('I786','1','Kes''lamatan oleh hayat,<br/>menurut keadilan-Mu;<br/>Benar secara yuridis,<br/>kaya secara organik.<br/>',NULL,64332,1);
INSERT INTO stanza VALUES('I786','2','Penebusan yang yuridis,<br/>memenuhi tuntutan-Mu;<br/>Kes''lamatan yang organik,<br/>genapkan hasrat hati-Mu.<br/>',NULL,64333,2);
INSERT INTO stanza VALUES('I786','3','Yuridis, ku dibenarkan,<br/>organik, ku satu d''ngan-Mu;<br/>Lahir ulang, insan-Allah,<br/>jadi kudus juga baru.<br/>',NULL,64334,3);
INSERT INTO stanza VALUES('I786','4','Diubah jadi mulia,<br/>metabolis dalam hayat,<br/>Hayat matang dan dewasa,<br/>koordinasi jadi Tubuh.<br/>',NULL,64335,4);
INSERT INTO stanza VALUES('I786','5','Tubuh tertebus dan mulia,<br/>dapat keputraan penuh;<br/>Baur d''ngan-Mu, saling huni,<br/>Salem Barulah kidungku.<br/>',NULL,64336,5);
INSERT INTO stanza VALUES('I1001','1','Bila kita memuji,<br/>Tuhan dapat mulia;<br/>Kita memuji nyaring,<br/>malaikat bersorak!<br/>Kitalah kesaksian-Nya,<br/>biar dunia paham;<br/>Gemetar laskar Iblis,<br/>kabur tunggang langgang.<br/>',NULL,64337,1);
INSERT INTO stanza VALUES('I1001','2','Tutup mulut ''kan kalah,<br/>Iblis pun cemoohkan;<br/>Mari bangun serentak,<br/>usir Iblis jahat!<br/>Sembahkan "kurban pujian",<br/>sorak kemenangan!<br/>Buang s''mua tipis muka,<br/>membara bagi-Nya!<br/>',NULL,64338,2);
INSERT INTO stanza VALUES('I1001','3','Dunia tak pernah bantu<br/>persembahkan puji;<br/>Muliakan nama Tuhan,<br/>bersyukur abadi.<br/>Mari puji selalu,<br/>tak perlulah izin, Sorak!<br/>Bebaskan rohmu!<br/>Kurnia-Nya tak terp''ri!<br/>',NULL,64339,3);
INSERT INTO stanza VALUES('I1001','4','Saudara jangan diam!<br/>Saudari pun sorak!<br/>Siar kemenangan-Nya<br/>ke penjuru dunia!<br/>Kini saat memuja,<br/>harus b''rani korban!<br/>Girang kar''na kurnia-Nya,<br/>seru, "Haleluya!"<br/>',NULL,64340,4);
INSERT INTO stanza VALUES('I1002','1','Tengok, s''mua bangsa berkumpul,<br/>reka-reka yang sia-sia;<br/>Raja serta bawahannya,<br/>sekata lawan Tuhan.<br/>"Putuskan semua belenggu,<br/>tali ikatan juga;"<br/>Raja dunia menantang<br/>Allah dan Sang Terurap.<br/>',NULL,64341,1);
INSERT INTO stanza VALUES('I1002','2','Dia yang duduk di surga,<br/>menertawai m''reka;<br/>Dalam murka Dia bersabda,<br/>terkejutlah mereka.<br/>Di Sion, gunung yang kudus,<br/>Allah melantik Raja,<br/>Ini ketetapan Allah,<br/>p''ringatan bagi m''reka.<br/>',NULL,64342,2);
INSERT INTO stanza VALUES('I1002','3','Kini Kristus Sang Terurap,<br/>siarkan murad Allah;<br/>"Kau Anak-Ku,<br/>hari ini Kau telah Kulahirkan.<br/>Bangsa-bangsa Kuberikan<br/>jadi milik pusaka;<br/>Menggunakan tongkat besi,<br/>Kau remukkan mereka."<br/>',NULL,64343,3);
INSERT INTO stanza VALUES('I1002','4','"Berhikmatlah, raja-raja!<br/>B''lajarlah hakim-hakim!<br/>Ibadahlah kepada-Nya<br/>dengan takut dan gentar.<br/>Cium kaki-Nya d''ngan gentar<br/>agar kau tak binasa,<br/>Yang sandar Dia bahagia!"<br/>Mari kita bergita!<br/>',NULL,64344,4);
INSERT INTO stanza VALUES('I1002','5','O, puji Dia, kita nampak,<br/>Sang Terurap nan tunggal;<br/>Berpaling dari yang hampa,<br/>cium Putra tersayang.<br/>"Sandar Dia, bahagia!"<br/>Bukan "berpegang taurat";<br/>Beriman pada Sang Bangkit,<br/>berkat kekal tak sudah.<br/>',NULL,64345,5);
INSERT INTO stanza VALUES('I1003','1','Di bentala, ya Yehova,<br/>eloklah nama-Mu!<br/>Bangsa-bangsa di mana jua,<br/>masyhurkan nama-Mu.<br/>Mulut bayi semuanya,<br/>memuji nama-Mu;<br/>Msuuh-musuh terbungkamlah,<br/>kubunya pun hancur.<br/>',NULL,64346,1);
INSERT INTO stanza VALUES('I1003','2','Ketika ku tengok pada<br/>jagat karya Tuhan,<br/>Surya, bulan,<br/>dan s''mua bintang,<br/>kisahkan hikmat-Mu.<br/>Manusia terbilang apa,<br/>Tuhan jaga ''tiasa?<br/>Dalam rencana-Mu kekal,<br/>Kau b''rikan kurnia-Mu!<br/>',NULL,64347,2);
INSERT INTO stanza VALUES('I1003','3','Tuhan Yesus,<br/>Kau-lah Allah baur d''ngan manusia,<br/>Mengenakan tubuh daging<br/>dan rendahkan diri.<br/>Kini Kau-lah Sang Penguasa,<br/>bermahkota mulia,<br/>Demi Tubuh-Mu berdaulat,<br/>s''mua takluklah kini!<br/>',NULL,64348,3);
INSERT INTO stanza VALUES('I1003','4','Firman menjelma manusia,<br/>mati, bangkit,<br/>t''rangkat; Kuasa, Tubuh,<br/>Kerajaan, s''mua t''lah Kau genapkan.<br/>D''ngan pekerjaan ilahi<br/>Kau bangun pujian;<br/>Girang luap hati kami,<br/>puji Kau yang layak.<br/>',NULL,64349,4);
INSERT INTO stanza VALUES('I1003','5','O, hari bah''gia s''gra tiba,<br/>s''mua mulut bergita!<br/>Tapi kini dalam g''reja,<br/>nikmatnya ku rasa.<br/>O, eloklah di bentala,<br/>nama-Mu Yehova!<br/>Biar bangsa-bangsa di dunia,<br/>siar nama-Mu indah!<br/>',NULL,64350,5);
INSERT INTO stanza VALUES('I1004','1','Amarah-Mu sekejap mata b''laka;<br/>Karunia-Mu sepanjang usia.<br/>Semalam ratap sedu,<br/>pagi sorak riang.<br/>',NULL,64351,1);
INSERT INTO stanza VALUES('I1005','1','Ratapku Kau ubah menjadi tarian,<br/>kain kabungku Kau lepas,<br/>Ratapku Kau ubah menjadi tarian,<br/>Kau beri sukacita.<br/>Girang, rohku memuji-Mu,<br/>tak bersudah TUHAN ALLAH-ku.<br/>Ya Allah-ku, syukur pada-Mu,<br/>hingga kekal!<br/>',NULL,64352,1);
INSERT INTO stanza VALUES('I1006','1','Hatiku meluapkan<br/>kata-kata indah;<br/>Aku hendak sampaikan<br/>sajak pada Raja.<br/>Lidahku bagai pena<br/>juru tulis pintar, Elok,<br/>Mempelai Laki,<br/>ku cinta, ku sayang.<br/>',NULL,64353,1);
INSERT INTO stanza VALUES('I1006','2','Elok-Mu, Tuhan Yesus,<br/>lampaui segala;<br/>Bajik-Mu tiada tara,<br/>lampaui s''mua insan.<br/>Mulut-Mu mencurahkan,<br/>kemurahan limpah,<br/>Allah berkati ''tiasa,<br/>selama-lamanya.<br/>',NULL,64354,2);
INSERT INTO stanza VALUES('I1006','3','Kau Perwira perkasa,<br/>melaju d''ngan gagah;<br/>Mulia, menang mutlak,<br/>semarak, wibawa.<br/>Semua bangsa rebah,<br/>siapa bisa halang?<br/>Panah-Mu tajam, tepat,<br/>tembus jantung lawan.<br/>',NULL,64355,3);
INSERT INTO stanza VALUES('I1006','4','O, takhta-Mu ya, Allah,<br/>kekal selamanya;<br/>Kuasa dan K''rajaan-Mu,<br/>lurus pun sempurna.<br/>Allah, yakni Allah-Mu,<br/>urapi diri-Mu,<br/>Melebihi mitra-Mu,<br/>Engkau sungguh patut!<br/>',NULL,64356,4);
INSERT INTO stanza VALUES('I1006','5','Mur, kemenyan, dan teja,<br/>aroma jubah-Mul;<br/>Mafat-Mu dan bangkit-Mu,<br/>''nyatakan karya-Mu.<br/>Dari gereja lokal,<br/>pujian membubung,<br/>Pujian tambah syukur,<br/>puaslah hati-Mu.<br/>',NULL,64357,5);
INSERT INTO stanza VALUES('I1007','1','Ratu berhias ''mas Ofir,<br/>di sisi kanan-Mu;<br/>Putri Raja, diapit,<br/>para putri sanjung.<br/>G''reja mulia sepadan<br/>dengan Raja mulia;<br/>Genap putri (kaum saleh),<br/>tampilkan mulia-Mu.<br/>',NULL,64358,1);
INSERT INTO stanza VALUES('I1007','2','Lihatlah, wahai putri,<br/>sendengkan t''lingamu;<br/>Lupakanlah bangsamu<br/>dan rumah ayahmu.<br/>Cantikmu pasti muncul,<br/>menarik Rajamu;<br/>Sujudlah kepada-Nya,<br/>kar''na Dia Tuanmu!<br/>',NULL,64359,2);
INSERT INTO stanza VALUES('I1007','3','Putri bejubah indah,<br/>bersulamkan emas;<br/>Dalam mahligai Raja,<br/>s''marak tiada tara!<br/>Kemuliaan Allah,<br/>jadi busananya;<br/>Hidup dan p''rilakunya,<br/>menampilkan Allah.<br/>',NULL,64360,3);
INSERT INTO stanza VALUES('I1007','4','Bawa ke depan Raja,<br/>pakaian bersulam;<br/>Lenan putih nan indah,<br/>tampil kebenaran.<br/>Roh Kudus menyulamkan<br/>Kristus ke atasnya;<br/>Kenakan jubah mulia,<br/>diperkenan Raja.<br/>',NULL,64361,4);
INSERT INTO stanza VALUES('I1007','5','Tampak Raja rupawan,<br/>betapa senangnya!<br/>Mari memuji lantang,<br/>gita riang kekal.<br/>Menyembah pada Raja,<br/>ratu pun megahlah;<br/>Dalam segala nikmat,<br/>s''mua mulia bagi-Nya.<br/>',NULL,64362,5);
INSERT INTO stanza VALUES('I1008','1','Maha agung,<br/>dalam neg''ri Allah.<br/>Di gunung kudus-Nya,<br/>patutlah memuji lantang!<br/>Gunung Sion di utara,<br/>menjulang permai indah,<br/>Kegirangan seluruh bumi,<br/>kota Raja Besar,<br/>Kegirangan seluruh bumi,<br/>kota Raja Besar.<br/>',NULL,64363,1);
INSERT INTO stanza VALUES('I1009','1','Dia bangkit, musuh terserak,<br/>pembenci-Nya larilah;<br/>Luluh lantak orang jahat,<br/>depan hadirat Allah.<br/>Giranglah orang benar,<br/>sorak menang semarak,<br/>Nyanyi puji, sorak lantang,<br/>tinggikan nama-Nya.<br/>',NULL,64364,1);
INSERT INTO stanza VALUES('I1009','2','Lintas padang pedati-Nya,<br/>bebaskan kaum papa,<br/>Yatim piatu dirawat,<br/>janda diperhatikan.<br/>Dalam ruang kudus-Nya,<br/>kurnia mengagumkan!<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64365,2);
INSERT INTO stanza VALUES('I1009','3','Orang yang sebatang kara,<br/>menemukan rumahnya;<br/>Yang tertawan lepas sudah,<br/>nikmat berkat tak batas.<br/>Bagi kawanan domba,<br/>berkat, rahmat, sedia!<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64366,3);
INSERT INTO stanza VALUES('I1009','4','Tuhan kini menang megah,<br/>sebarkan kejayaan;<br/>Kaum wanita siarkan,<br/>"Semburat raja lawan!"<br/>Tanpa peluh dan lelah,<br/>bagi-bagi jarahan!<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64367,4);
INSERT INTO stanza VALUES('I1009','5','Tengok, Kristus t''rangkat sudah,<br/>bawa banyak tawanan;<br/>Itulah pemberian-Nya,<br/>bagi Allah dan insan.<br/>Kita semua adalah<br/>tawanan yang terubah!<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64368,5);
INSERT INTO stanza VALUES('I1009','6','Puji syukur sampai kekal,<br/>suplai indah tak kurang;<br/>Dia-lah Allah Penyelamat,<br/>suara pujian meluas!<br/>Berwisata ke barzakh,<br/>kepala musuh pecah!<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64369,6);
INSERT INTO stanza VALUES('I1009','7','Allah, kami telah nampak,<br/>di ruang kudus - Kau jalan;<br/>Parade nan menang, jaya,<br/>serta musik iringan.<br/>Suara pujian di depan,<br/>panjat ulang-berulang,<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64370,7);
INSERT INTO stanza VALUES('I1009','8','Bungsu - Benyamin di depan,<br/>Yehuda menyusulnya;<br/>Putra duka di kanan-Nya,<br/>singa pemegang kuasa.<br/>Zebulon dan Naftali,<br/>warta kabar gembira:<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64371,8);
INSERT INTO stanza VALUES('I1009','9','Hai, umat-Nya,<br/>kekuatanmu dari bait nan mulia;<br/>Mohon Allah menguatkan,<br/>sampai kami tergenap.<br/>Puji syukur tak henti,<br/>bergema ujung bumi;<br/>Haleluya, haleluya,<br/>haleluya, amin!<br/>',NULL,64372,9);
INSERT INTO stanza VALUES('I1010','1','Bersorak-sorak bagi TUHAN,<br/>hai seluruh bumi!<br/>Dengan rela layan-i TUHAN,<br/>datanglah, bersorak!<br/>Kenallah Di-a-lah Allah,<br/>kitalah cipta-an-Nya,<br/>juga milik-Nya.<br/>Kita umat juga<br/>kawanan domba-Nya.<br/>Sambil syukur masuk gerbang-Nya,<br/>ke dalam halaman-Nya.<br/>Bersyukurlah kepada Di-a,<br/>junjung nama-Nya.<br/>Dia-lah Sang Bijak,<br/>kekal cinta kemurah-an-Nya.<br/>Se-ti-a-Nya pada<br/>kita hingga kekal.<br/>',NULL,64373,1);
INSERT INTO stanza VALUES('I1011','1','Jika Tuhan p''riksa,<br/>tuntut dosa,<br/>si-a-pa yang tahan?<br/>Jika Tuhan p''riksa,<br/>tuntut dosa,<br/>sia-pa yang tahan?<br/>Pada-Mu ada ampunan,<br/>pada-Mu ada ampunan.<br/>Yang membu-at<br/>manusia takwa pada-Mu.<br/>',NULL,64374,1);
INSERT INTO stanza VALUES('I1012','1','Tengoklah, hamba TUHAN,<br/>malam berdiri di ba-it-Nya.<br/>Marilah memuji TUHAN!<br/>Puji nama-Nya.<br/>Angkat tangan ke ba-it-Nya,<br/>pujilah TUHAN!<br/>Moga Pencipta dari Si-on,<br/>mencurahkan berkat-Nya.<br/>',NULL,64375,1);
INSERT INTO stanza VALUES('I1013','1','Ku mau s''lalu nyanyikan<br/>kasih rahmat Yesus,<br/>ku nyanyi, nyanyikan.<br/>Sungguhlah rahmat,<br/>kini ku hidup di g''reja,<br/>ku nyanyikan kasih rahmat Tuhan.<br/>Mulutku menyi-ar-kan se-ti-a-Nya,<br/>se-ti-a-Nya.<br/>Mulutku menyi-ar-kan se-ti-a-Nya,<br/>sampai selamanya.<br/>Ku mau s''lalu nyanyikan<br/>kasih rahmat Yesus,<br/>ku nyanyi, nyanyikan.<br/>Sungguhlah rahmat,<br/>kini ku hidup di g''reja,<br/>ku nyanyikan kasih rahmat Tuhan.<br/>',NULL,64376,1);
INSERT INTO stanza VALUES('I1014','1','Pujilah, masyhurkanlah,<br/>nama-Nya tinggi luhur!<br/>Pujilah, masyhurkanlah,<br/>nama-Nya tinggi luhur!<br/>Sebab perbuatan-Nya mu-li-a.<br/>Si-ar-kan ke s''luruh bumi.<br/>Pujilah, masyhurkanlah,<br/>nama-Nya tinggi luhur!<br/>',NULL,64377,1);
INSERT INTO stanza VALUES('I1015','1','Ku memuji Allah tak henti,<br/>Dia hidup dalamku,<br/>Dia-lah segalaku,<br/>suplai hayat s''lalu.<br/>Ku memuji Allah tak henti,<br/>Dia hidup dalamku, selama tak pisah.<br/>',NULL,64378,1);
INSERT INTO stanza VALUES('I1015','chorus','Kini dalam roh ku nikmat<br/>Kristus jadi s''galaku.<br/>Seru nama-Nya,<br/>Dia-lah rea-li-tas-ku.<br/>Buka mulut, ku ''kan kecap,<br/>Tuhan betapa limpah,<br/>Dialah suplai hayat a-jaib pun limpah.<br/>',NULL,64379,2);
INSERT INTO stanza VALUES('I1015','2','Oleh pohon hayat ku hidup,<br/>bu-ah-nya rawatku.<br/>Hayatnya kuat-kanku,<br/>ku hidup selalu.<br/>Oleh pohon hayat ku hidup,<br/>tiap hari ku nikmat,<br/>Dia makanan hayat.<br/>',NULL,64380,3);
INSERT INTO stanza VALUES('I1015','3','Aliran hayat di dalamku,<br/>mengalir tak putus.<br/>Pancar, ''ngalir terus, ku teresap jenuh.<br/>Aliran hayat di dalamku,<br/>Dia aliran hayat.<br/>''Ngalir hingga kekal.<br/>',NULL,64381,4);
INSERT INTO stanza VALUES('I1016','1','Marilah memuji Di-a serempak,<br/>di gunung kudus kita berada.<br/>Saksikan karya-Nya kecil dan besar,<br/>Kristus berdaulat Sang Raja kita.<br/>Hidup gereja ri-il pun limpah.<br/>Dosa dan du-nia makinlah punah.<br/>Kita melonjak ri-ang memuncak,<br/>kita melonjak ri-ang memuncak.<br/>',NULL,64382,1);
INSERT INTO stanza VALUES('I1016','2','Puji Di-a setara dengan Allah,<br/>berinkarnasi luka buat kita.<br/>Bangkit dari ma-ut, duduk bertakhta,<br/>limpah ruah bangkit, kita nikmat s''mua.<br/>Dia kelimpahan penuhi s''gala,<br/>kita jadilah wujud kaya-Nya.<br/>O, haleluya, wujud nan limpah.<br/>O, haleluya, wujud nan limpah.<br/>',NULL,64383,2);
INSERT INTO stanza VALUES('I1016','3','Pujilah Di-a Roh di dalam rohku,<br/>agama, sya-riat, ku tak cenderung.<br/>Nikmati ''ti-a-sa diri-Nya m''lulu,<br/>limpah kaya-Nya re-a-li-tas-ku.<br/>Di g''reja lokal kita be-ri-uh,<br/>dengan roh tegap ''muji dan junjung.<br/>Di-a itu Roh Sang Raja agung,<br/>Di-a itu Roh Sang Raja agung.<br/>',NULL,64384,3);
INSERT INTO stanza VALUES('I1016','4','Diri-Nya muli-a penuhi g''reja,<br/>ke-sak-sian g''reja jaya dan cerlang.<br/>Penuhi limpah, roh kita bersorak,<br/>biar se-mua tahu Sang Maharaja.<br/>Tinggalkanlah alam kepicikan,<br/>ke ujung bumi Roh bimbing kita.<br/>Mu-lia, ri-a, ''ngalirkan diri-Nya,<br/>mu-lia, ri-a, ''ngalirkan diri-Nya.<br/>',NULL,64385,4);
INSERT INTO stanza VALUES('I1017','1','Riang! Riang! Riang!<br/>Hatiku penuh riang!<br/>Riang! Riang! Riang!<br/>Dia jadikan ku riang.<br/>Nyanyikan kasih-Nya yang a-jaib.<br/>Di-a mati membebaskanku.<br/>Kini aku bebas pun unggul,<br/>ri-ang hatiku!<br/>',NULL,64386,1);
INSERT INTO stanza VALUES('I1017','2','Tuhanku,<br/>''ngalir dalam rohku.<br/>Tuhanku,<br/>menggarap jiwaku.<br/>Bakar se-mua usang batinku,<br/>ubah diriku jadi baru.<br/>Aku matang, sambut datang-Mu,<br/>Yesus, Tuhanku!<br/>',NULL,64387,2);
INSERT INTO stanza VALUES('I1017','3','Pujilah!<br/>Si-ar murad Allah!<br/>Pujilah !<br/>Dlam roh membara!<br/>Hati - mulut penuh pu-ji-an,<br/>beritakan rencana Allah.<br/>Yang berk''lana balik pada-Nya,<br/>pujilah lantang!<br/>',NULL,64388,3);
INSERT INTO stanza VALUES('I1017','4','Greja,<br/>wujud di tiap lokal!<br/>Gereja,<br/>terpecah, kasihan!<br/>Babel besar kini runtuhlah,<br/>di Yerusalem Tuhan serta.<br/>Pada lokalitas dirikan gereja lokal!<br/>',NULL,64389,4);
INSERT INTO stanza VALUES('I1017','5','G''reja lokal,<br/>kita telah nampak.<br/>G''reja lokal,<br/>kita di dalamnya.<br/>Kota terang di gunung kudus,<br/>Kristus, g''reja terekspresikan.<br/>Tergenaplah kehendak Allah,<br/>di g''reja lokal!<br/>',NULL,64390,5);
INSERT INTO stanza VALUES('I1018','1','Kidung nya-nyian yang ku gemar,<br/>sejak ku tertebus.<br/>Puji Tuhan ku Sang Raja,<br/>sejak ku tertebus.<br/>',NULL,64391,1);
INSERT INTO stanza VALUES('I1018','chorus','Sejak ku tertebus,<br/>sejak ku tertebus,<br/>ku bermegah dalam-Nya.<br/>Sejak ku tertebus,<br/>ku bermegah dalam nama-Nya.<br/>',NULL,64392,2);
INSERT INTO stanza VALUES('I1018','2','Kristus memu-askan aku, sejak ku tertebus.<br/>Kehendak-Nya aku rindu, sejak ku tertebus.<br/>',NULL,64393,3);
INSERT INTO stanza VALUES('I1018','3','Ku miliki Sang Sya-fa-at, sejak ku tertebus.<br/>Hilanglah bimbang dan duka, sejak ku tertebus.<br/>',NULL,64394,4);
INSERT INTO stanza VALUES('I1018','4','Girangku tak terkatakan, sejak ku tertebus.<br/>Tuhanlah kebenaranku, sejak ku tertebus.<br/>',NULL,64395,5);
INSERT INTO stanza VALUES('I1018','5','Allah sudah ku miliki, sejak ku tertebus.<br/>Allah sertaku abadi, sejak ku tertebus.<br/>',NULL,64396,6);
INSERT INTO stanza VALUES('I1018','chorus','Sejak ku tertebus,<br/>sejak ku tertebus,<br/>sejak ku tertebus,<br/>ku bermegah dalam-Nya.<br/>Sejak ku tertebus,<br/>sejak ku tertebus,<br/>ku bermegah dalam nama-Nya.<br/>',NULL,64397,7);
INSERT INTO stanza VALUES('I1019','1','Ku tegak d''ngan takjub depan Yesus,<br/>orang Nazaret.<br/>Orang dosa, najis, p''riku,<br/>cinta kasih-Nya ''nimpa.<br/>',NULL,64398,1);
INSERT INTO stanza VALUES('I1019','chorus','Sunguh takjub! Sungguh a-jaib!<br/>S''lamanya ku nyanyikan.<br/>Sungguh takjub! Sungguh a-jaib!<br/>Besarlah kasih Tuhan!<br/>',NULL,64399,2);
INSERT INTO stanza VALUES('I1019','2','Di taman Di-a berdo-a,<br/>"Jadilah kehendak-Mu."<br/>Bukan ''nangisi diri-Nya,<br/>peluh darah kar''naku.<br/>',NULL,64400,3);
INSERT INTO stanza VALUES('I1019','3','Malak iba nampak Di-a,<br/>muncullah dalam terang.<br/>Dalam dukacita sangat,<br/>hingga pulih t''naga-Nya.<br/>',NULL,64401,4);
INSERT INTO stanza VALUES('I1019','4','Di-a hapus s''mua dosaku,<br/>nestapaku Dia tanggung.<br/>Di-a pikul di Golgota,<br/>d''rita ma-ut bagiku.<br/>',NULL,64402,5);
INSERT INTO stanza VALUES('I1019','5','Hari itu kaum tertebus,<br/>dalam mu-lia nampak Dia.<br/>Sungguh girang, nyanyi ri-ang,<br/>sampai s''lama-lamanya.<br/>',NULL,64403,6);
INSERT INTO stanza VALUES('I1020','1','Nama Yesus Maha-kua-sa!<br/>Malak malak tia-rap.<br/>Malak-malak tia-rap.<br/>Sembahkan hormat, mahkota.<br/>',NULL,64404,1);
INSERT INTO stanza VALUES('I1020','chorus','Nobat Dia!<br/>Nobat, nobat,<br/>nobat Sang Almuhit Tuhan!<br/>',NULL,64405,2);
INSERT INTO stanza VALUES('I1020','2','Turunan Adam tertebus,<br/>dari lembah jatuh.<br/>Dari lembah jatuh.<br/>Kini s''lamat, wajar sujud.<br/>',NULL,64406,3);
INSERT INTO stanza VALUES('I1020','3','Orang dosa jangan lupa,<br/>luka sengsara-Nya.<br/>Luka sengsara-Nya.<br/>Mari pandang hadirat-Nya.<br/>',NULL,64407,4);
INSERT INTO stanza VALUES('I1020','4','Ti-ap suku, ti-ap bangsa,<br/>se-mua sujud, sembah.<br/>Se-mua sujud, sembah.<br/>Mu-lia, hormat, bagi Di-a.<br/>',NULL,64408,5);
INSERT INTO stanza VALUES('I1020','5','Sua-ra laksa-an gempita,<br/>ku juga bersorak.<br/>Ku juga bersorak.<br/>Sembah, puji hingga kekal.<br/>',NULL,64409,6);
INSERT INTO stanza VALUES('I1021','1','Dia Tuhan, Dia Tuhan,<br/>bangkit dari kema-tian,<br/>Dialah Tuhan!<br/>S''mua lutut bertelut,<br/>s''mua mulut mengaku,<br/>Yesus Kristus Tuhan.<br/>',NULL,64410,1);
INSERT INTO stanza VALUES('I1022','1','Nyanyi bagi Raja Maha-kua-sa,<br/>mulia bagi Dia, Domba tersemb''lih.<br/>K''raja-an-Nya bawa sejahtera,<br/>mu-lia bagilah Yesus Sang Raja.<br/>',NULL,64411,1);
INSERT INTO stanza VALUES('I1022','chorus','Menyanyilah! Bersoraklah!<br/>Yesus Raja! Yesus Raja!<br/>Umat Tuhan senang menyanyikan:<br/>Mu-lia bagilah Yesus Sang Raja.<br/>',NULL,64412,2);
INSERT INTO stanza VALUES('I1022','2','Bangsa-bangsa diam dalam terang-Nya,<br/>seg''nap umat lebur oeh cinta.<br/>Adil dan benar pada takhta-Nya,<br/>yang lalim lenyaplah, Yesus m''raja.<br/>',NULL,64413,3);
INSERT INTO stanza VALUES('I1022','3','Dalam K''ra-jaan-Nya penuh sentosa,<br/>jaya merdeka, lenyap angkara.<br/>Tia-da seteru, ''cua-li-lah kawan,<br/>pedang jadi arit, Yesus m''raja.<br/>',NULL,64414,4);
INSERT INTO stanza VALUES('I1022','4','Kenal ''kan Allah sebar merata,<br/>p''ri a-ir memenuhi la-ut-an.<br/>Se-mua makhluk subur, segar, bugar,<br/>harmonis se-mu-a, Yesus m''raja.<br/>',NULL,64415,5);
INSERT INTO stanza VALUES('I1022','5','Moga Ke-ra-ja-an Kristus tiba,<br/>sinar fajar lekaslah merekah.<br/>Cip-ta-an baru sorak serentak,<br/>Satan terhempaslah, Yesus m''raja.<br/>',NULL,64416,6);
INSERT INTO stanza VALUES('I1023','1','''Nilah sua-ra menang g''reja,<br/>Domba layak!<br/>Surga penuh puji ri-ang,<br/>Domba layak!<br/>Takhta dau-lat pada Allah,<br/>harum s''merbak bubung atas.<br/>Sua-ra pu-jian tidak henti,<br/>Domba layak!<br/>',NULL,64417,1);
INSERT INTO stanza VALUES('I1023','2','Ti-ap bangsa dan negara,<br/>Domba layak!<br/>S''mua berkidung kur-nia besar,<br/>Domba layak!<br/>Sua-ra pu-jian menggelegar,<br/>sep''ri air bah g''lora terjang.<br/>Sujud sembah di duli-Nya,<br/>Domba layak!<br/>',NULL,64418,2);
INSERT INTO stanza VALUES('I1023','3','Nya-nyi-an musik tak henti,<br/>Domba layak!<br/>Kur-nia melebihi dosa,<br/>Domba layak!<br/>Darah adi, beli kita, yang tersesat,<br/>dicari-Nya.<br/>Dipimpin-Nya masuk mu-lia,<br/>Domba layak!<br/>',NULL,64419,3);
INSERT INTO stanza VALUES('I1023','4','Betapa harapan berkat,<br/>Domba layak!<br/>U-jian ''nimpa, gita tetap,<br/>Domba layak!<br/>Lebih manis dari s''gala,<br/>judul hanya satu saja.<br/>Takkan habis dikisahkan,<br/>Domba layak!<br/>',NULL,64420,4);
INSERT INTO stanza VALUES('I1024','1','Tuhan, kami haleluya,<br/>menyanyi nyaring.<br/>Ni-lai-Mu tia-da taranya,<br/>lam-pau-i s''gala.<br/>',NULL,64421,1);
INSERT INTO stanza VALUES('I1024','chorus','Puji Domba!<br/>Kaulah layak!<br/>Pu-jian abadi!<br/>Haleluya! Haleluya!<br/>Pujilah! Amin!<br/>',NULL,64422,2);
INSERT INTO stanza VALUES('I1024','2','Puji Domba!<br/>Darah adi telah teralir.<br/>Kami tertebus jadi<br/>imamat rajani.<br/>',NULL,64423,3);
INSERT INTO stanza VALUES('I1024','3','haleluya! Tuhan Yesus,<br/>kekal kasih-Mu.<br/>Kami milik-Mu abadi,<br/>d''ngan-Mu bersatu.<br/>',NULL,64424,4);
INSERT INTO stanza VALUES('I1024','4','Puji Tuhan! Haleluya!<br/>Sia-pa diam diri?<br/>Umat saleh tiap<br/>penjuru pada menyanyi.<br/>',NULL,64425,5);
INSERT INTO stanza VALUES('I1025','1','Sa-uk-lah dengan girang<br/>dari mata a-ir ke-s''la-mat-an.<br/>Sa-at itu ucapkan: Puji Dia!<br/>Sa-uklah dengan girang<br/>dari mata a-ir kes''lamatan.<br/>Sa-at itu ucapkan: Puji Dia!<br/>Seru nama-Nya,<br/>siarkan pada bangsa per-buat-an-Nya,<br/>masyhurkanlah nama Sang Terhormat.<br/>Sorak nyaring, umat Si-on se-mu-a-nya!<br/>Karena Sang Kudus,<br/>bani Is-ra-el Maha agung!<br/>',NULL,64426,1);
INSERT INTO stanza VALUES('I1026','1','Kecap dan lihatlah akan Tuhan!<br/>Betapa ba-ik-nya Dia!<br/>Tuhan Yesus se-ti-a, sandar Dia,<br/>pasti ''kan bahagia.<br/>Takwa Dia, takkan kekurangan,<br/>singa merana kelaparan.<br/>Orang yang mencari Tuhan,<br/>yang baik ada padanya.<br/>',NULL,64427,1);
INSERT INTO stanza VALUES('I1027','1','Haleluya Haleluya Haleluya Haleluya !<br/>Haleluya Haleluya Haleluya Haleluya !<br/>Haleluya Haleluya Haleluya Haleluya !<br/>Haleluya Haleluya Haleluya Haleluya !<br/>',NULL,64428,1);
INSERT INTO stanza VALUES('I1028','1','Makan roti, hai umat Allah,<br/>pujilah, Dia esakan kita.<br/>Kini makan Dia atas tumpu-an tunggal,<br/>saksikan Tubuh-Nya.<br/>',NULL,64429,1);
INSERT INTO stanza VALUES('I1028','chorus','Kaum saleh, nikmat roti, cawan!<br/>Dalam Dia, kita esa!<br/>Tegaklah pada esa lokal,<br/>se-u-tuh makan nikmat Dia!<br/>',NULL,64430,2);
INSERT INTO stanza VALUES('I1028','2','Minum cawan, hai umat Allah,<br/>berdarah, Dia membeli kita.<br/>Per-jan-jian Baru meng-e-sa-kan,<br/>tercapai kehendak kekal-Nya.<br/>',NULL,64431,3);
INSERT INTO stanza VALUES('I1028','3','Tegap, ka-um saleh esalah;<br/>bukanlah butir berantakan.<br/>Ber-ba-ur sehatilah kita,<br/>satu roti di ti-ap lokal.<br/>',NULL,64432,4);
INSERT INTO stanza VALUES('I1028','4','Makan roti, hai umat Allah;<br/>pujilah, Dia esakan kita.<br/>Kini makan Dia atas tum-pu-an tunggal,<br/>saksikan Tubuh-Nya.<br/>(setelah bait terakhir,<br/>koor tak perlu dinyanyikan)<br/>',NULL,64433,5);
INSERT INTO stanza VALUES('I1029','1','O, puji Dia! O, puji Dia!<br/>Mu-li-a, hormat nama-Nya!<br/>O, puji Dia! O, puji Dia!<br/>Mu-li-a, hormat nama-Nya!<br/>Siar pada bangsa per-bu-at-an-Nya,<br/>sebutlah nama Sang Terhormat.<br/>Umat Si-on, angkat suara,<br/>nyaring menjunjung kurnia-Nya.<br/>Haleluya! Haleluya!<br/>Sorak, nya-nyian tak bersudah!<br/>Haleluya! Haleluya!<br/>Sorak, nya-nyian tak bersudah!<br/>',NULL,64434,1);
INSERT INTO stanza VALUES('I1101','1','Allah ku puji,<br/>Kau beri Roh Kristus.<br/>Dia semayam dalamku,<br/>jadi hayatku.<br/>Haleluya, Roh Sang Kristus!<br/>Haleluya, s''mayam!<br/>Haleluya, hayat limpah!<br/>Kekal s''lamanya.<br/>',NULL,64435,1);
INSERT INTO stanza VALUES('I1101','2','Puj dalam roh,<br/>Adam akhir sudah.<br/>Jadi Roh pemb''ri-hayat,<br/>dengan ku esa.<br/>Haleluya, Yesus ini!<br/>Haleluya, Sang Roh!<br/>Haleluya, esa d''ngan-Nya!<br/>Dua roh pun esa.<br/>',NULL,64436,2);
INSERT INTO stanza VALUES('I1101','3','Lahir dalam roh,<br/>kita di-u-bah-Nya.<br/>Serupa Putra Allah,<br/>tumbuh dewasa.<br/>Haleluya, suplai hayat!<br/>Haleluya, ubah!<br/>Haleluya, di-u-bah-Nya!<br/>Serupa Di-a!<br/>',NULL,64437,3);
INSERT INTO stanza VALUES('I1101','4','Serupa Di-a,<br/>oleh rawatan Roh.<br/>Makan minum Sang Hayat,<br/>suplai tak putus.<br/>Haleluya, kur-nia ''purna!<br/>S''luruhnya milikku!<br/>Haleluya, serba cukup!<br/>Hidup terunggul!<br/>',NULL,64438,4);
INSERT INTO stanza VALUES('I1102','1','Tengok, zaman beralih,<br/>ke dalam Roh beralih.<br/>Tujuh Roh depan takhta,<br/>datang bekerja kini.<br/>',NULL,64439,1);
INSERT INTO stanza VALUES('I1102','chorus','O, tujuh Roh, marilah,<br/>genapkan pemulihan!<br/>Bakar dan s''lidik-i-lah,<br/>''tuk pembangunan g''reja.<br/>Bakar, s''lidik,<br/>''tuk pembangunan g''reja.<br/>',NULL,64440,2);
INSERT INTO stanza VALUES('I1102','2','Roh itu tujuh ganda,<br/>singkir kema-tian g''reja.<br/>Para saleh hiduplah,<br/>gereja terpulihkan.<br/>',NULL,64441,3);
INSERT INTO stanza VALUES('I1102','3','Kini Roh Allah ini,<br/>jadi suplai gereja.<br/>Tujuh lipat lebih kuat,<br/>sungguh limpah, sempurna!<br/>',NULL,64442,4);
INSERT INTO stanza VALUES('I1102','4','Tujuh Roh itu ia-lah<br/>tujuh obor menyala.<br/>Bukan untuk mengajar,<br/>tapi untuk membakar.<br/>',NULL,64443,5);
INSERT INTO stanza VALUES('I1102','5','Kini tujuh Roh Allah,<br/>pun tujuh mata nyala.<br/>Daging, nafsu terenyah,<br/>hempas di luar gereja.<br/>',NULL,64444,6);
INSERT INTO stanza VALUES('I1102','6','Tujuh Roh diberikan,<br/>bawa hayat nan limpah.<br/>Dalam gereja lokal,<br/>ku alami pun nikmat.<br/>',NULL,64445,7);
INSERT INTO stanza VALUES('I1103','1','Dengan Roh penghakiman,<br/>ha-kim-i s''mua yang jahat!<br/>Bukan diri mencari,<br/>Roh-Mu yang menyatakan.<br/>',NULL,64446,1);
INSERT INTO stanza VALUES('I1103','2','Dengan roh yang membara,<br/>bakar habis najisku.<br/>Bakar habis du-ni-a,<br/>sampai ludes diriku.<br/>',NULL,64447,2);
INSERT INTO stanza VALUES('I1103','3','Dengan roh hikmat Tuhan,<br/>wahyukan ra-ha-sia-Mu.<br/>Kau akar, carang, bu-ah,<br/>isi nan limpah sungguh.<br/>',NULL,64448,3);
INSERT INTO stanza VALUES('I1103','4','Dengan roh strategi-Mu,<br/>nyatakan bimbingan-Mu.<br/>Cara-cara tak guna,<br/>kua-sa roh itu perlu.<br/>',NULL,64449,4);
INSERT INTO stanza VALUES('I1103','5','Dengan roh pengeta-huan,<br/>bukan sandar indraku.<br/>Agar kenal hasrat-Mu,<br/>hidupkan ka-ru-nia-Mu.<br/>',NULL,64450,5);
INSERT INTO stanza VALUES('I1103','6','Dengan roh tepat, benar,<br/>bawaku tempuh jalan.<br/>Tak undur kar''na s''lera,<br/>tak b''rubah kar''na susah.<br/>',NULL,64451,6);
INSERT INTO stanza VALUES('I1103','7','Singkirkan roh tidurku,<br/>celik mata ku jaga.<br/>Sudah dekat balik-Mu,<br/>moga ku s''lalu si-ap.<br/>',NULL,64452,7);
INSERT INTO stanza VALUES('I1104','1','Kristus Tuhanku,<br/>Roh Pemb''ri-hayat,<br/>Roh pemb''ri hayat,<br/>Roh pemb''ri hayat.<br/>Kristus Tuhanku,<br/>Roh pemb''ri hayat,<br/>Dia hidup dalamku.<br/>Tuhan hidup,<br/>terbentuk dalamku!<br/>Aku hidup Tuhan ku pamerkan!<br/>Haleluya!<br/>Kristus Tuhanku,<br/>Roh Pemb''ri-hayat,<br/>Roh pemb''ri hayat,<br/>Roh pemb''ri hayat.<br/>Kristus Tuhanku,<br/>Roh pemb''ri hayat,<br/>Dia hidup dalamku.<br/>',NULL,64453,1);
INSERT INTO stanza VALUES('I1105','1','Kristus itu Roh pemb''ri hayat,<br/>masuk rohku b''riku hayat.<br/>Kristus itu Roh pemb''ri hayat,<br/>dalam rohku bimbing, suplai.<br/>',NULL,64454,1);
INSERT INTO stanza VALUES('I1105','chorus','Tuhan! Amin!<br/>Tuhan! Amin! Haleluya!<br/>Tuhan! Amin!<br/>Tuhan! Amin! Haleluya!<br/>',NULL,64455,2);
INSERT INTO stanza VALUES('I1105','2','Kini Kristus ia-lah Roh itu,<br/>Roh-Nya - rohku esa padu.<br/>Kini Kristus ia-lah Roh itu,<br/>serupa Tuhan, ubahku.<br/>',NULL,64456,3);
INSERT INTO stanza VALUES('I1106','1','Ku cintalah Yesusku,<br/>Dia-lah Roh pemb''ri hayat.<br/>Dengan Dia ku bersatu,<br/>dua roh ba-ur esa!<br/>',NULL,64457,1);
INSERT INTO stanza VALUES('I1107','1','Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Dia di mana?<br/>(Dia di mana?)<br/>',NULL,64458,1);
INSERT INTO stanza VALUES('I1107','chorus','Tuhan tinggal dalam rohku,<br/>jadi hayat, nafasku.<br/>Tuhan dan aku bersatu,<br/>''nilah raha-sia sungguh!<br/>',NULL,64459,2);
INSERT INTO stanza VALUES('I1107','2','Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Kaum saleh harus tahu!<br/>(Kaum saleh harus tahu!)<br/>Kristus hidup!<br/>(Kristus hidup!)<br/>',NULL,64460,3);
INSERT INTO stanza VALUES('I1107','chorus','Kristus Roh pemberi-hayat,<br/>penuh k''limpahan Allah.<br/>Takkan asat Dia ku nikmat,<br/>asal seru nama-Nya.<br/>',NULL,64461,4);
INSERT INTO stanza VALUES('I1108','1','Allah Tritunggal sudah di dalamku,<br/>Roh a-jaib ada di dalamku.<br/>Dengan Tuhan ku berpadu satu roh,<br/>Roh hayat ada di dalamku.<br/>',NULL,64462,1);
INSERT INTO stanza VALUES('I1108','chorus','O, Roh a-jaib ada di dalamku!<br/>Roh a-jaib ada di dalamku! Allah dalam Putra,<br/>Putra itu Roh, Roh a-jaib ada di dalamku.<br/>',NULL,64463,2);
INSERT INTO stanza VALUES('I1108','2','"Ya, Aba" dari lubuk ku menyeru,<br/>dari Roh a-jaib di dalamku.<br/>Seru-an Roh Putera kepada-Mu,<br/>Roh hayat ada di dalamku.<br/>',NULL,64464,3);
INSERT INTO stanza VALUES('I1108','3','Tuhan Yesus Kristus tinggal dalamku,<br/>Roh a-jaib tinggal di dalamku.<br/>Lewat perubahan jadi nikmatku,<br/>Roh hayat s''mayam di dalamku.<br/>',NULL,64465,4);
INSERT INTO stanza VALUES('I1108','4','Roh re-a-li-tas kini telah tiba,<br/>Roh a-jaib ada di dalamku.<br/>Se-an-te-ro Kristus, ri-il pun terang,<br/>demi Roh hayat di dalamku.<br/>',NULL,64466,5);
INSERT INTO stanza VALUES('I1108','5','Ka-ru-nia ini s''lalu ku barakan,<br/>Roh a-jaib ada di dalamku. "Tuhan Yesus!"<br/>membu-at roh melonjak,<br/>oleh Roh hayat di dalamku.<br/>',NULL,64467,6);
INSERT INTO stanza VALUES('I1109','1','Urapan-Nya!<br/>Tuhan bergerak dalamku,<br/>O, mustika,<br/>urapi ''ti-a-sa. Kua-sa darah!<br/>Bawa kita bersekutu,<br/>kini kita hidup dalam hayat.<br/>',NULL,64468,1);
INSERT INTO stanza VALUES('I1109','chorus','(saudari)<br/>Ada urapan! Hai saudara!<br/>Urapan, kita percaya!<br/>Darilah Tuhan, t''rima urapan,<br/>dalam rohku Roh-Nya gerak!<br/>(Saudara)<br/>Ada urapan! Hai saudari!<br/>Urapan terus berperan.<br/>Oleh urapan, tinggal dalam-Nya,<br/>o, haleluya, berlimpah!<br/>',NULL,64469,2);
INSERT INTO stanza VALUES('I1109','2','Urapan-Nya! Memba-ur-kan Allah - insan,<br/>Allah - insan ba-ur jadi satu!<br/>Ti-ap sa-at hidup, gerak, perilaku<br/>bersandar Dia, Allah dalam kita.<br/>',NULL,64470,3);
INSERT INTO stanza VALUES('I1109','3','Urapan-Nya! Mengajar kita segala,<br/>kita punya pe-ra-sa-an hayat.<br/>Ta-at ini, kita tahu bagaimana,<br/>sandar Di-a segalanya jelas.<br/>',NULL,64471,4);
INSERT INTO stanza VALUES('I1110','1','Dalam firman ku nampak,<br/>urapan di dalamku!<br/>Tanpa orang mengajar,<br/>urapan memimpinku!<br/>',NULL,64472,1);
INSERT INTO stanza VALUES('I1110','chorus','O, di dalam rohku,<br/>Di-a berperan!<br/>Urapan memimpinku!<br/>Dalamku mengalir!<br/>O, puji dan syukur,<br/>firman-Nya tutur,<br/>ku harus patuh s''lalu,<br/>hidup dalam urapan.<br/>',NULL,64473,2);
INSERT INTO stanza VALUES('I1110','2','Hidup alami Kristus,<br/>lewat firman murni-Nya.<br/>Roh-Nya satu denganku,<br/>kekal tak terpisahkan!<br/>',NULL,64474,3);
INSERT INTO stanza VALUES('I1110','3','Ada basuhan darah,<br/>sirna jarak dan sekat.<br/>Urapan minyak susul,<br/>diri Allah ku dapat.<br/>',NULL,64475,4);
INSERT INTO stanza VALUES('I1110','4','Kristus justru Roh hayat,<br/>masuk ke dalam rohku.<br/>Sang Kudus urapiku,<br/>Allah dan insan ba-ur.<br/>',NULL,64476,5);
INSERT INTO stanza VALUES('I1110','5','Dia itu Roh, ku jamah,<br/>''ngalir di dalam rohku.<br/>Makin dalam dan limpah,<br/>hingga ku kenal Allah.<br/>',NULL,64477,6);
INSERT INTO stanza VALUES('I1110','6','S''turut urapan minyak,<br/>''tia-sa tinggal dalam-Nya.<br/>Dia mengajar, melu-as,<br/>jenuhi anteroku.<br/>',NULL,64478,7);
INSERT INTO stanza VALUES('I1111','1','Sudahkah temukan rohmu!<br/>Tak pisah d''ngan mulutmu!<br/>Seru,"Tuhan, haleluya!"<br/>rohmu bebaslah tentu!<br/>',NULL,64479,1);
INSERT INTO stanza VALUES('I1111','chorus','Dari Roh Kudus terlahir roh kita,<br/>karya ini t''lah genap.<br/>Dari Roh Kudus terlahir roh kita,<br/>dua roh baur jadi satu.<br/>',NULL,64480,2);
INSERT INTO stanza VALUES('I1111','2','Jangan menunggu "gerakan",<br/>jangan tertipu setan.<br/>Buka mulut, bebaskan roh,<br/>saksikan kau t''lah bebas.<br/>',NULL,64481,3);
INSERT INTO stanza VALUES('I1112','1','Balik ke roh,<br/>jamah Roh rea-li-tas!<br/>Balik ke roh,<br/>jamah Roh rea-li-tas!<br/>Dari huruf,<br/>doktrin berbalik ke roh.<br/>O, berbalik,<br/>berbalik dalam roh!<br/>Hai, saudara!<br/>Hai, saudari!<br/>Raslitas dalam roh!<br/>(Mu-lia, haleluya!)<br/>Balik ke dalam roh,<br/>berbalik d''ngan mutlak.<br/>Balik ke dalam roh!<br/>',NULL,64482,1);
INSERT INTO stanza VALUES('I1112','2','Ikut Tuhan,<br/>dalam roh ikut Dia.<br/>Ikut Tuhan,<br/>dalam roh ikut Dia!<br/>Tengok, zaman beralih,<br/>ikut Tuhan!<br/>O, maju, maju,<br/>maju ikut Dia!<br/>Hai, saudara!<br/>Hai, saudari!<br/>Dalam roh majulah!<br/>(Mu-lia, haleluya!)<br/>Dalam roh t''rus maju,<br/>hingga nampak mu-lia!<br/>Maju, t''rus majulah!<br/>',NULL,64483,2);
INSERT INTO stanza VALUES('I1113','1','Balik ke rohmu,<br/>hubung lekat d''ngan Tuhan!<br/>Balik ke rohmu,<br/>dapat suplai hayat!<br/>Balik ke rohmu,<br/>seru nama-Nya ''tia-sa!<br/>Hidup dalam roh,<br/>jangan minggat!<br/>',NULL,64484,1);
INSERT INTO stanza VALUES('I1113','2','Balik ke rohmu,<br/>hubung lekat d''ngan Tuhan!<br/>Balik ke rohmu,<br/>kau pasti nyanyi riang!<br/>Balik ke rohmu,<br/>walau banyak urusan!<br/>Hidup dalam roh,<br/>jangan minggat!<br/>',NULL,64485,2);
INSERT INTO stanza VALUES('I1113','3','Balik ke rohmu,<br/>hubung lekat d''ngan Tuhan!<br/>Balik ke rohmu,<br/>lembam atau lega!<br/>Tuhan tak ubah,<br/>sekarang hingga kekal!<br/>Hidup dalam roh,<br/>jangan minggat!<br/>',NULL,64486,3);
INSERT INTO stanza VALUES('I1114','1','Kita t''lah dibebaskan,<br/>puji Hu! (Puji Hu!)<br/>Kita t''lah dibebaskan,<br/>puji Hu! (Puji Hu!)<br/>Lepas agama usang,<br/>tata cara yang mati.<br/>Kita t''lah dibebaskan,<br/>puji Hu! (Puji Hu!)<br/>',NULL,64487,1);
INSERT INTO stanza VALUES('I1114','2','Kita t''lah dibebaskan,<br/>dalam Roh! (Dalam Roh!)<br/>Kita t''lah dibebaskan,<br/>dalam Roh! (Dalam Roh!)<br/>Nikmati hidup bebas<br/>dan selamat sempurna.<br/>Kita t''lah dibebaskan,<br/>dalam Roh! (Dalam Roh!)<br/>',NULL,64488,2);
INSERT INTO stanza VALUES('I1115','1','Nikmat-i Kristus dalam roh,<br/>makan Dia, sedaplah,<br/>tak banding!<br/>Limpah-Nya jadi rea-li-tas-ku,<br/>pu-as, sentosa, tak henti.<br/>Dalam roh, dalam roh,<br/>nikmat-i Kristus dalam roh.<br/>Dalam roh, dalam roh,<br/>dalam roh,<br/>nikmati Kristus dalam roh!<br/>',NULL,64489,1);
INSERT INTO stanza VALUES('I1116','1','Kita nyanyi dalam roh bagi-Nya,<br/>dari batin nyanyi bagi-Nya.<br/>Nyanyi haleluya bagi Tuhan,<br/>ba-ur jadi satu dengan-Nya.<br/>',NULL,64490,1);
INSERT INTO stanza VALUES('I1116','2','Lama nian dibelenggu ajaran.<br/>Tertambat dalam angan-angan.<br/>Dan terkurung oleh rasa iba.<br/>Makin nuntut makinlah gelap.<br/>',NULL,64491,2);
INSERT INTO stanza VALUES('I1116','3','Latih menyentuh Tuhan dengan roh.<br/>Dan berlatih memakai Kristus.<br/>Berlatih makan dan minum Yesus.<br/>Lepas dari derita ronta.<br/>',NULL,64492,3);
INSERT INTO stanza VALUES('I1116','4','Haleluya! Hayat RohulKudus!<br/>Haleluya! Serbalah baru!<br/>Dari angan pindah alih ke roh.<br/>Kelimpahan kita rasakan.<br/>',NULL,64493,4);
INSERT INTO stanza VALUES('I1117','1','Kami bertekad, tindak dalam roh.<br/>Kami bertekad, tindak dalam roh.<br/>Kami bertekad, tindak dalam roh.<br/>Dia dalam roh, haleluya!<br/>',NULL,64494,1);
INSERT INTO stanza VALUES('I1117','2','Tindak dalam roh, seru,"O, Tuhan!"<br/>Tindak dalam roh, seru,"O, Tuhan!"<br/>Tindak dalam roh, seru,"O, Tuhan!"<br/>Dia kayalah, haleluya!<br/>',NULL,64495,2);
INSERT INTO stanza VALUES('I1117','3','Mengikut Yesus, perlulah "Tubuh".<br/>Mengikut Yesus, perlulah "Tubuh".<br/>Mengikut Yesus, perlulah "Tubuh".<br/>Ri-il sungguh, haleluya!<br/>',NULL,64496,3);
INSERT INTO stanza VALUES('I1117','4','Sama terbangun, girang tak hingga.<br/>Sama terbangun, girang tak hingga.<br/>Sama terbangun, girang tak hingga.<br/>Dalam g''reja, haleluya!<br/>',NULL,64497,4);
INSERT INTO stanza VALUES('I1117','5','Allah pulihkan hidup gereja.<br/>Allah pulihkan hidup gereja.<br/>Allah pulihkan hidup gereja.<br/>Ku dalamnya, haleluya!<br/>',NULL,64498,5);
INSERT INTO stanza VALUES('I1118','1','Ya Allah, dalam-Mu,<br/>ada hayat kekal,<br/>tertampil di dalam Sang Putra.<br/>Dalam kebangkitan,<br/>jadilah Roh hayat,<br/>dalamku b''ri hidup, b''ri hayat.<br/>',NULL,64499,1);
INSERT INTO stanza VALUES('I1118','2','Tengoklah!<br/>Dari takhta Allah dan Domba,<br/>sungai hayat telah mengalir.<br/>Allah-lah sumbernya,<br/>Tuhan pancarannya,<br/>Tritunggal mengalirkan hayat.<br/>',NULL,64500,2);
INSERT INTO stanza VALUES('I1118','3','Tuhanku, Yesusku,<br/>ku buka pada-Mu,<br/>seru nama-Mu, Kau ku sesap.<br/>Tuhanku, Yesusku,<br/>ku cebur dalam-Mu,<br/>Tritunggal jenuhi antero.<br/>',NULL,64501,3);
INSERT INTO stanza VALUES('I1119','1','Tuhan Pem-b''ri hayat,<br/>b''riku hayat.<br/>Bila pada-Nya ku bers''ru,<br/>Dia bebaskan rohku.<br/>Tuhan Pemb''ri hayat,<br/>diam dalamku.<br/>Dia bukan nama melulu,<br/>bahkan rea-litasku.<br/>',NULL,64502,1);
INSERT INTO stanza VALUES('I1120','1','Dulu mati dalam dosa,<br/>hati gelap buta.<br/>Kini oleh firman Tuhan,<br/>ku ta''u Dia dalamku.<br/>',NULL,64503,1);
INSERT INTO stanza VALUES('I1120','chorus','Dia di dalamku!<br/>Dia di dalamku!<br/>O, kur-nia ini agung!<br/>Tuhan di dalamku!<br/>',NULL,64504,2);
INSERT INTO stanza VALUES('I1120','2','Surya menyoroti bumi,<br/>bunga mekar cantik.<br/>Nyatakan t''rang, hayat,<br/>kasih, Tuhan di dalamku.<br/>',NULL,64505,3);
INSERT INTO stanza VALUES('I1120','3','Penuh kur-nia dan rea-litas,<br/>Firman t''lah menjelma.<br/>Kita nikmati kaya-Nya,<br/>Tuhan di dalamku.<br/>',NULL,64506,4);
INSERT INTO stanza VALUES('I1120','4','Dia-lah hayat, Dia-lah bangkit,<br/>mu-li-a ilahi.<br/>Biji gandum telah mati,<br/>hidup di dalamku.<br/>',NULL,64507,5);
INSERT INTO stanza VALUES('I1120','5','Ku rindulah serupa Dia,<br/>pancarkan Dia ''tia-sa.<br/>Ku pun rela dimatikan,<br/>agar Tuhan hidup.<br/>',NULL,64508,6);
INSERT INTO stanza VALUES('I1121','1','Yesus Tuhanku,<br/>hidup dalamku,<br/>kini tak tara gembiraku!<br/>O, haleluya!<br/>O, haleluya!<br/>Hidup dalamku.<br/>',NULL,64509,1);
INSERT INTO stanza VALUES('I1121','2','Du-ni-a penuhlah<br/>si-a-si-a,<br/>hanya Kristuslah Sang Rea-li-tas.<br/>O, haleluya!<br/>O, haleluya!<br/>Hidup dalamku.<br/>',NULL,64510,2);
INSERT INTO stanza VALUES('I1122','1','Ki-ta nampak Kristus rea-li-tas,<br/>ta-pi tak cu-kup ha-nya nampak;<br/>Dalam s''mua pengalaman ki-ta,<br/>Dia-lah se-ga-la.<br/>Sa-at do-a pandang wa-jah-Nya,<br/>ba-ca fir-man ke-nal kur-nia-Nya,<br/>Ta-pi se-hari-hari ki-ta,<br/>Dia-kah se-ga-la?<br/>Ha-le-lu-ya! Dalam t''rang nampak<br/>Tuhan sungguh ri-il sem-pur-na,<br/>A-sal ki-ta se-ti-ap sa-at,<br/>se-tiap ha-ri, se-ti-ap per-ka-ra,<br/>Ba-lik pa-da ha-di-rat-Nya -<br/>Per-lu ri-il a-lam-i Di-a!<br/>Ti-dak ka-bur, me-reka-reka!<br/>Ki-ta a-lam-i dan te-rap-kan,<br/>Dia-lah se-ga-la!<br/>',NULL,64511,1);
INSERT INTO stanza VALUES('I1122','2','Hidup penuhlah ke-sem-pat-an,<br/>di-a-tur o-leh hik-mat Ba-pa,<br/>Yang ter-ba-ik t''lah di-a-tur-Nya,<br/>da-pat-kan Kris-tus.<br/>Kristus i-si dan re-a-li-tas,<br/>ki-ta pan-car-kan Di-a ''tia-sa,<br/>A-tas-ku dan kau, Di-a ha-rus<br/>da-pat-kan ja-lan.<br/>Ha-le-lu-ya di da-lam tu-buh<br/>''tia-sa ba-wa kema-ti-an-Nya,<br/>A-gar ha-yat-Nya ter-nya-ta-kan,<br/>in-san la-hir ma-kin ru-sak, ta-pi<br/>In-san ba-tin ma-kin ba-ru<br/>[O-rang di se-ki-tar ''kan nam-pak<br/>Har-ta da-lam be-ja-na ta-nah,<br/>Si-nar mu-lia In-jil ter-pan-car<br/>me-la-lui ki-ta]<br/>[Bu-kan teo-ri a-tau teo-lo-gi,<br/>me-la-in-kan i-si rea-li-tas,<br/>Kristus ja-di se-ga-la ki-ta,<br/>Dia-lah se-ga-la!]<br/>',NULL,64512,2);
INSERT INTO stanza VALUES('I1123','1','Haleluya! Haleluya!<br/>Yesus kini hidup di dalamku.<br/>Haleluya! Haleluya!<br/>Yesus hidup dalamku.<br/>(hidup bisa diganti dengan:<br/>garap, tumbuh, s''mayam)<br/>',NULL,64513,1);
INSERT INTO stanza VALUES('I1124','1','Olehlah hayat, ku menyanyi lantang:<br/>Haleluya! Puji Hu!<br/>Olehlah hayat, ku menyanyi lantang:<br/>Haleluya! Puji Hu!<br/>Hati lu-ap sukacita,<br/>Tuhan hidup di dalamku.<br/>Tuhan hidup di dalamku!<br/>',NULL,64514,1);
INSERT INTO stanza VALUES('I1125','1','Tuhan benih hayat tertabur dalam hatiku.<br/>Dia bertunas, tumbuh besar jadi p''ra-wak-an-Nya.<br/>Dia perlu air hidup, tak perlu cara, aturan,<br/>hayat yang amuhit membu-at-nya tumbuh besar.<br/>Benih hayat a-ja-ib, yakni Yesus Tuhan,<br/>Dia tertabur dalamku, tumbuh besar dan matang.<br/>',NULL,64515,1);
INSERT INTO stanza VALUES('I1125','2','Kita butir gandum bukan sema-u sendiri,<br/>se-mua butir gandum ''kan digiling sampai halus.<br/>Gandum jadi tepung halus, bahkan satu roti,<br/>se-mua orang saleh ba-ur jadi satu Tubuh.<br/>Kita perlu digiling hingga hilang ego,<br/>butir gandum digiling, satu Tubuh terbentuk.<br/>',NULL,64516,2);
INSERT INTO stanza VALUES('I1125','3','Benih t''lah tertanam, gandum tumbuh besar matang,<br/>kita ladang Allah, tumbuh dalam ke-esa-an.<br/>Se-mua pertumbuhan untuk membangun gereja,<br/>Allah insan bersemayam tak lagi kelana.<br/>Hayat untuk bangunan, Allah insan lega,<br/>di sini Dia dan umat rukun tinggal bersama.<br/>',NULL,64517,3);
INSERT INTO stanza VALUES('I1125','4','Bangunan-Nya tergantung emas, perak, permata,<br/>untuk pengubahan, tepung halus perlu d''rita.<br/>Gandum tak dapat berhenti pada pu-as diri,<br/>harus berubah jadi emas, perak, permata.<br/>Tepung perlu di-o-lah, jadilah permata,<br/>untuk bangun bersama, tercapailah murad-Nya.<br/>',NULL,64518,4);
INSERT INTO stanza VALUES('I1125','5','Hayat b''rubah, matang menghasilkan muti-ara,<br/>sederhana, mustika, almuhit, pula mahal.<br/>Tuhan mu-lia bangkit dari mati, lewat d''rita,<br/>akhirnya dapat g''reja - kepu-asan hati-Nya.<br/>Muti-ara, gemar-Nya, mempelai, ''kenan-Nya,<br/>pasangan terkasih-Nya, tulus, murni, mustika.<br/>',NULL,64519,5);
INSERT INTO stanza VALUES('I1125','6','Moga Tuhan jaga aku miskin di dalam roh,<br/>agar jadi tanah ba-ik, benih tumbuh, limpah.<br/>Capai sasaran, pembangunan, pu-as hati-Nya,<br/>dapat mustika tak ternilai, yakni mempelai.<br/>Tuhan kosongkan rohku, tulus, murni suci,<br/>hayat matang menjadi memp''lai p''rem-puan terkasih.<br/>',NULL,64520,6);
INSERT INTO stanza VALUES('I1126','1','Benih hayat di dalamku, ku biarkan bertumbuh.<br/>Benih hayat di dalamku. Ku biar-kan bertumbuh,<br/>bertumbuh, bertumbuh, bertumbuh!<br/>',NULL,64521,1);
INSERT INTO stanza VALUES('I1126','2','Jiwaku tak menghimpitnya, ku biarkan bertumbuh ...<br/>',NULL,64522,2);
INSERT INTO stanza VALUES('I1126','3','Rawat demi do-a baca, ku biarkan bertumbuh ...<br/>',NULL,64523,3);
INSERT INTO stanza VALUES('I1126','4','Tiap hari s''ru,"Tuhan Yesus", ku biarkan bertumbuh ...<br/>',NULL,64524,4);
INSERT INTO stanza VALUES('I1126','5','Bersekutu d''ngan kaum saleh, ku biarkan bertumbuh ...<br/>',NULL,64525,5);
INSERT INTO stanza VALUES('I1126','6','Berdiri bertutur-sabda, ku biarkan bertumbuh ...<br/>',NULL,64526,6);
INSERT INTO stanza VALUES('I1126','7','Tuhan berfirman, ku,"Amin", ku biarkan bertumbuh ...<br/>',NULL,64527,7);
INSERT INTO stanza VALUES('I1126','8','Bertumbuh dengan kaum saleh, ku biarkan bertumbuh ...<br/>',NULL,64528,8);
INSERT INTO stanza VALUES('I1126','9','Tumbuh perawakan Kristus, ku biarkan bertumbuh ...<br/>',NULL,64529,9);
INSERT INTO stanza VALUES('I1126','10','Hingga k''ra-ja-an ternyata, ku biarkan bertumbuh ...<br/>',NULL,64530,10);
INSERT INTO stanza VALUES('I1127','1','Kami nampak maksud hati-Mu,<br/>pada keraja-an.<br/>Tidak perlu berjerih bodoh,<br/>sandar kur-nia saja.<br/>Tidak perlu tunggu kelak,<br/>kami masuk keraja-an.<br/>Asal Dikau tumbuh dalamku,<br/>k''ra-ja-an ''kan nyata.<br/>',NULL,64531,1);
INSERT INTO stanza VALUES('I1127','2','Keraja-an per-luas-an Kristus,<br/>benih t''lah tertabur.<br/>Yesus itulah benih hayat,<br/>teruslah bertumbuh.<br/>Batu, tanah - hayat jiwa;<br/>semak duri - kua-tir harta.<br/>Jangan jadi pinggiran jalan;<br/>jadi tanah subur.<br/>',NULL,64532,2);
INSERT INTO stanza VALUES('I1127','3','Tanah subur, gandum bertumbuh,<br/>menghasilkan bu-ah.<br/>Gandum harus menjadi tepung,<br/>pangan Allah, insan.<br/>Kehendak-Nya ''kan tergenap,<br/>bila t''rima gilingan-Nya.<br/>Jadi kurban saji-an kudus,<br/>satu dalam Tuhan.<br/>',NULL,64533,3);
INSERT INTO stanza VALUES('I1127','4','Lewat d''rita, ubah ke batu,<br/>bagi pembangunan!<br/>Di dalam Roh tumbuh, berubah,<br/>''mas, perak, permata.<br/>T''rima Tuhanlah pribadi,<br/>mengendali hidup kita.<br/>Demi hayat tumbuh, berubah,<br/>keraja-an nyata.<br/>',NULL,64534,4);
INSERT INTO stanza VALUES('I1127','5','Muti-ara murni sempurna,<br/>mutu paling tinggi.<br/>Walau d''rita bertubi-tubi,<br/>hayat tumbuh tinggi.<br/>Tuhan hayat dan pribadi,<br/>k''raja-an - Tuhan sendiri.<br/>Dalam kita tumbuh tak henti,<br/>Allah - insan s''rasi.<br/>',NULL,64535,5);
INSERT INTO stanza VALUES('I1128','1','Keraja-an i-a-lah Kristus,<br/>penuh limpah di dalamku.<br/>Bergerak ''tia-sa dalam bangkit,<br/>Kristus jadi insan baru.<br/>O, limpah-Mu tak batas,<br/>jadi suplai t''nagaku,<br/>agarku tiap hari nikmat-i,<br/>menikmati, menikmati,<br/>s''gala limpah-Mu.<br/>O, mu-li-a kua-sa-Mu,<br/>''tia-sa gerak dalamku,<br/>agarku tiap hari ubah tumbuh,<br/>ubah tumbuh, ubah tumbu serupa-Mu.<br/>Ada rea-litas k''raja-an,<br/>ada pengalaman g''reja,<br/>dengan kaum saleh<br/>terbangun bersa-ma.<br/>O, kuasa k''raja-an-Mu,<br/>bawa alam surgawi,<br/>Kau bisa gerak le-lu-a-sa,<br/>le-lu-a-sa, le-lu-a-sa,<br/>ku dalam mu-lia.<br/>',NULL,64536,1);
INSERT INTO stanza VALUES('I1129','1','Yesus suryaku satu-satunya,<br/>terang-i sepanjang jalanku.<br/>Bi-ar berawan ma-u-pun cerah,<br/>Yesus, Yesus, surya tunggalku.<br/>',NULL,64537,1);
INSERT INTO stanza VALUES('I1129','2','Yesus hayatku a-ja-ib indah,<br/>satu denganku, suplai, tunjang.<br/>S''lama-lamanya takkan berubah,<br/>Yesus, Yesus, hayat tunggalku.<br/>',NULL,64538,2);
INSERT INTO stanza VALUES('I1130','1','Yesuslah jadi Pribadi.<br/>Yesuslah, jadi Pribadi.<br/>O, kini Dia jadi Pribadiku.<br/>Kristus s''mayam di hatiku,<br/>limpah Allah penuh-i-ku.<br/>O, kini Dia jadi Pribadiku.<br/>',NULL,64539,1);
INSERT INTO stanza VALUES('I1131','1','Insan lamaku t''lah terenyah,<br/>di salib mati bersama-Nya.<br/>Kini dia tak lagi berguna, berlalu sudah.<br/>Insan baru tinggal di rohku,<br/>dalam ku p''ri sumber memancar.<br/>Penuh-i seluruh diriku, d''ngan hayat limpah.<br/>Kristus menjadi pribadiku,<br/>pada-Nya hatiku tertuju.<br/>Insan batin temukan rumah:<br/>satu tempat per-hen-ti-an,<br/>satu tempat ke-di-am-an -<br/>mutlak jadi re-a-li-tas-ku,<br/>diri-Nya terbuka padaku,<br/>limpah kaya diam di hatiku,<br/>Dia pribadiku.<br/>',NULL,64540,1);
INSERT INTO stanza VALUES('I1131','2','Demi Dia terbentuk dalamku,<br/>aku jadi anggota Tubuh.<br/>Tindakan tak lagi sendiri, ber-koor-dinasi.<br/>Kristus harus jadi Pribadi,<br/>alam-i-ah harus terbasmi.<br/>Tersingkir terus hingga sirna,<br/>Krsituslah s''gala. Hanya Kristus jadi pribadi,<br/>tia-da lagi tu-ju-an diri,<br/>Hingga gereja terbangunkan,<br/>jadi satu insan baru, nyata murad kekal Allah -<br/>Allah ingin mutlak ber-ba-ur,<br/>dapatkan satu ke-di-am-an,<br/>tegak kua-sa kerajaan-Nya, di s''luruh bumi.<br/>Bukan hanya Kristus sen-di-rian.<br/>Ada g''reja bekerja sama,<br/>terapkan Kristuslah segala, manu-sia baru.<br/>',NULL,64541,2);
INSERT INTO stanza VALUES('I1132','1','Sungguh menang! Sungguh jaya!<br/>Allah jadi manu-sia!<br/>Mengenakan sifat insan,<br/>agar murad-Nya genap.<br/>Demi salib tumpas Iblis,<br/>Anak Manu-sia bangkit!<br/>',NULL,64542,1);
INSERT INTO stanza VALUES('I1132','2','Yesus demi bajik insan<br/>t''lah menahan si licik.<br/>S''ba-gai insan Dia menang,<br/>lewati se-mua u-jian!<br/>Kini dalam roh ku t''rima<br/>s''gala kebajikan-Nya.<br/>',NULL,64543,2);
INSERT INTO stanza VALUES('I1132','3','Dia menjadi hayat insan,<br/>yakni dalam Roh Yesus.<br/>Bajik insan jadi putra,<br/>d''ngan Roh Allah berba-ur.<br/>Kini Roh ini almuhit,<br/>penuhi s''mua perluku.<br/>',NULL,64544,3);
INSERT INTO stanza VALUES('I1132','4','Sungguh a-jaib! Sungguh ri-il!<br/>Anak tinggal dalamku!<br/>Me-lu-as ke anteroku,<br/>hidup nyata lewatku.<br/>Haleluya! Haleluya!<br/>Ku memuji tak putus.<br/>',NULL,64545,4);
INSERT INTO stanza VALUES('I1132','5','Sungguh a-jaib! Sungguh mu-lia!<br/>Atas insan Dia nyata!<br/>Kita ia-lah anggota-Nya,<br/>untuk ekspresikan Dia.<br/>Kini hidup bersandar Dia,<br/>membangun ke-diam-an-Nya.<br/>',NULL,64546,5);
INSERT INTO stanza VALUES('I1133','1','Tengok! Zaman telah ubah,<br/>perang telah mu-lai!<br/>K''lompok Iblis pemberontak,<br/>kini ''nyerang ganas.<br/>Ka-um saleh dilengkapi,<br/>d''ngan insani Yesus.<br/>Menampilkan rupa Allah,<br/>''nyata kua-sa Allah.<br/>',NULL,64547,1);
INSERT INTO stanza VALUES('I1133','chorus','Tegaklah berdasar<br/>pada insani Yesus.<br/>Lu-apkan kebajikan,<br/>tegak lawan arus.<br/>Zaman ini, jahat dosa,<br/>bengkok rusak, tegar tengkuk.<br/>G''reja pancar kesaksi-an<br/>kebajikan Yesus!<br/>',NULL,64548,2);
INSERT INTO stanza VALUES('I1133','2','Tengok! Iblis datang du-nia,<br/>merusak manu-sia,<br/>tapi Allah pilih seo-rang,<br/>nilai-Nya tak tara!<br/>Keturunan perempu-an,<br/>Allah jadi insan;<br/>Di-a Yesus, Adam akhir,<br/>hancur sia-sat Satan.<br/>',NULL,64549,3);
INSERT INTO stanza VALUES('I1133','3','Menakutkan, du-nia cemar,<br/>dosa makin parah;<br/>makin m''rosot, tia-da obat,<br/>insan bobrok sudah!<br/>Tapi kita umat surga,<br/>jadi garam du-nia;<br/>dalam du-nia serba jahat,<br/>terlindung oleh-Nya.<br/>',NULL,64550,4);
INSERT INTO stanza VALUES('I1133','4','Kini kita makan minum,<br/>seru nama Tuhan;<br/>nikmat s''luruh insani-Nya,<br/>menginjak si Satan.<br/>O, paling kepada Tuhan,<br/>tolak hayat jiwa;<br/>hancurkan s''mua sia-sat Satan,<br/>suplai insan hayat.<br/>',NULL,64551,5);
INSERT INTO stanza VALUES('I1134','chorus','Tahukah, apa k''ra-ja-an,<br/>k''ra-ja-an, k''ra-ja-an?<br/>Tahukah, apa k''ra-ja-an?<br/>''Nilah jawaban:<br/>',NULL,64552,1);
INSERT INTO stanza VALUES('I1134','1','Kristus benih kecil,<br/>mengalahkan ma-ut.<br/>Tahukan demiki-an<br/>K''ra-ja-an Allah?<br/>',NULL,64553,2);
INSERT INTO stanza VALUES('I1134','2','Allah tanam benih,<br/>tumbuh t''rus di hat.<br/>Tahukan demiki-an,<br/>K''ra-ja-an Allah?<br/>',NULL,64554,3);
INSERT INTO stanza VALUES('I1134','3','Kristus bertambah t''rus,<br/>melu-as di kalbu.<br/>Tahukan demiki-an,<br/>K''ra-ja-an Allah?<br/>',NULL,64555,4);
INSERT INTO stanza VALUES('I1134','4','Dia tumbuh dewasa,<br/>''ngepa-lai segala.<br/>Tahukan demiki-an,<br/>K''ra-ja-an Allah?<br/>',NULL,64556,5);
INSERT INTO stanza VALUES('I1134','5','Jangan sampai sesal,<br/>d''ngan Roh usir setan.<br/>Tahukan demiki-an,<br/>K''ra-ja-an Allah?<br/>',NULL,64557,6);
INSERT INTO stanza VALUES('I1201','1','Pada Yesus hati tertarik,<br/>rasa kian mes-ra,<br/>Dia tercantik,<br/>lebih segar dari embun pagi,<br/>Ni-lai-Nya tak terlukiskan<br/>sastera terindah,<br/>Ki-an hari ki-an indah,<br/>lam-pau-i kemarin!<br/>',NULL,64558,1);
INSERT INTO stanza VALUES('I1201','chorus','Limpah ruah kaya Tuhan,<br/>s''pa-ruh pun tak t''ritung,<br/>Dia kian hari kian indah<br/>me-le-bih-i yang lalu!<br/>',NULL,64559,2);
INSERT INTO stanza VALUES('I1201','2','Kita nampak mu-lia-Nya<br/>terpancar dalam g''reja,<br/>Di sinilah limpah-Nya,<br/>tak perlu cari ke lain,<br/>Di-a selalu memu-askan<br/>roh lapar kita,<br/>Dia kian hari kian indah,<br/>melebihi yang tadi!<br/>',NULL,64560,3);
INSERT INTO stanza VALUES('I1201','3','Kini Dia-lah Roh hidup,<br/>tinggal dalam roh kita,<br/>B''ri urapan yang manis,<br/>hayat roh lebih penuh!<br/>Bila kita bersidang,<br/>sungguh bebas roh kita,<br/>Dia kian hari kian indah<br/>melebihi yang dulu!<br/>',NULL,64561,4);
INSERT INTO stanza VALUES('I1201','4','Disatukan kita demilah<br/>pemulihan-Nya,<br/>Tampilkan kaya limpah<br/>Kristus dan gereja-Nya,<br/>Tercurah pada-Nya milik<br/>dan adanya kita,<br/>Bagi rencana-Nya yang agung,<br/>lebih mustika!<br/>',NULL,64562,5);
INSERT INTO stanza VALUES('I1202','1','Kita telah ber-o-leh Kristus,<br/>Dia-lah segala kita;<br/>Seru nama-Nya bah''gia sungguh,<br/>ku-dus, la-gi mu-li-a!<br/>',NULL,64563,1);
INSERT INTO stanza VALUES('I1202','chorus','A-lang-kah gembira-nya!<br/>Penuhlah mu-lia!<br/>Penuh mu-lia!<br/>Pe-nuh mu-lia!<br/>A-lang-kah gem-bi-ra-nya!<br/>Pe-nuh-lah mu-lia!<br/>Separuhpun tak ter-ka-ta-kan!<br/>',NULL,64564,2);
INSERT INTO stanza VALUES('I1202','2','Kristus - Roh itu, kita kenal,<br/>tinggal dalam roh kita,<br/>Amat mudahlah didekati,<br/>manis-Nya tak terperi!<br/>',NULL,64565,3);
INSERT INTO stanza VALUES('I1202','3','Raha-sia hidup kita dapat:<br/>makan dan minum Tuhan,<br/>Baca firman, seru nama-Nya,<br/>nilainya memang nyata!<br/>',NULL,64566,4);
INSERT INTO stanza VALUES('I1202','4','Kita temukan g''reja lokal,<br/>kini kita di rumah!<br/>S''lamanya tak merantau pula,<br/>dalam g''reja indahlah.<br/>',NULL,64567,5);
INSERT INTO stanza VALUES('I1202','5','Dengan para saleh berhimpun,<br/>palinglah menggirangkan,<br/>Dan roh kita pun takkan layu,<br/>hidup kita bermakna.<br/>',NULL,64568,6);
INSERT INTO stanza VALUES('I1203','1','Mari menikmati Yesus<br/>yang segar lincah,<br/>makan, minum<br/>Tuhan se-puas-nya.<br/>Mari menikmati Yesus<br/>yang segar lincah,<br/>ri-il benar, makan,<br/>minum Tuhan sepuasnya.<br/>Mari menikmati Yesus<br/>yang segar lincah, ri-il benar,<br/>dalam g''reja, makan,<br/>minum Tuhan se-puas-nya.<br/>Mari menikmati Yesus<br/>yang segar lincah, ri-il benar,<br/>dalam g''reja, esa sayang,<br/>makan, minum Tuhan se-puas-nya.<br/>Mari menikmati Yesus<br/>yang segar lincah, Yesus Tuhan!<br/>Ri-il benar, dalam g''reja,<br/>esa sayang, makan,<br/>minum Tuhan se-puas-nya.<br/>',NULL,64569,1);
INSERT INTO stanza VALUES('I1204','1','Nikmat-i, nikmat-i limpah kaya Tuhan.<br/>Nikmat-i, nikmat-i limpah kaya Tuhan.<br/>Nikmat-i, nikmat-i limpah kaya Tuhan.<br/>Nikmat-i, nikmat-i limpah kaya Tuhan.<br/>Nikmat Tuhan, bu-ang-lah gundah gelisah.<br/>Nikmat Tuhan, kita jadi kesak-sian-Nya.<br/>Nikmati, nikmati limpah kaya Tuhan.<br/>Nikmati, nikmati limpah kaya Tuhan.<br/>',NULL,64570,1);
INSERT INTO stanza VALUES('I1204','2','(Nikmati boleh juga diganti:<br/>Saksikan! Pujilah! Bagilah!<br/>Hiruplah! Dst.)<br/>',NULL,64571,2);
INSERT INTO stanza VALUES('I1205','1','Ku mau b''roleh Kristus,<br/>semakin banyak! (Peng! Peng! Peng!)<br/>Agar Kristus ki-an hari<br/>bertambah-tambah (Peng! Peng! Peng!)<br/>Dia menjadi hayatku,<br/>limpah tak sudah.<br/>Sehingga aku pun dimiliki oleh-Nya!<br/>',NULL,64572,1);
INSERT INTO stanza VALUES('I1205','2','Makan Tuhan Yesus,<br/>bertambah banyak (Nyam! Nyam! Nyam!)<br/>Makan Tuhan Yesus,<br/>me-lam-pau-i yang sudah (Nyam! Nyam! Nyam!)<br/>Di-a-lah makanan yang<br/>sedap pun lezat.<br/>Makan Tuhan Yesus,<br/>ti-ap hari dan sa-at.<br/>',NULL,64573,2);
INSERT INTO stanza VALUES('I1206','1','Tegak di menara jaga,<br/>memandang dengan waspada.<br/>Dalam batin Dia bersabda,<br/>"Waktu-Ku tidak tertunda!"<br/>',NULL,64574,1);
INSERT INTO stanza VALUES('I1206','chorus','Mumpung kini nikmat-i Dia,<br/>jangan tunggu k''lak sengsara.<br/>Sa-at itu terlambatlah!<br/>',NULL,64575,2);
INSERT INTO stanza VALUES('I1206','2','Orang dungu ''nyusun sarang,<br/>guna timbun harta benda.<br/>Sebelum api menimpa,<br/>demi iman kita bakar.<br/>',NULL,64576,3);
INSERT INTO stanza VALUES('I1206','3','Bila pohon-pohon bu-ah:<br/>anggur, za-i-tun dan ara.<br/>Tak hasilkan produksinya,<br/>ladang pun tia-da tu-ai-an.<br/>',NULL,64577,4);
INSERT INTO stanza VALUES('I1206','4','Kaya Kristus nikmat saja,<br/>so-al bumi, so-al b''lakang.<br/>Lembu, kambing, meski tia-da,<br/>bagi kita tak mengapa.<br/>',NULL,64578,5);
INSERT INTO stanza VALUES('I1206','5','Ada Tuhan senang sudah,<br/>ki-an hari ki-an ku-at!<br/>Ada Tuhan lari pesat,<br/>langkah-langkah kian memuncak!<br/>',NULL,64579,6);
INSERT INTO stanza VALUES('I1207','1','Mari datang, nikmati limpah-Nya.<br/>Yesus itu Roh Pemberi hayat.<br/>Berhuni di roh kita, beri su-plai-an<br/>hayat, garap, ba-ur pun ''ngubah.<br/>O, a-ja-ib-lah Tuhan, d''nganku padu esa,<br/>ku nyanyilah lantang,"Haleluya, puji Tuhan!"<br/>nikmati segala kelimpahan Tuhan.<br/>Tuhan almuhit mengenyangkan!<br/>',NULL,64580,1);
INSERT INTO stanza VALUES('I1208','1','Sukacita kar''na Tuhan,<br/>itu t''nagamu.<br/>Sukacita kar''na Tuhan,<br/>itu t''nagamu.<br/>Makan minumlah yang enak.<br/>Inilah hari kudus Tuhan.<br/>Sukacita kar''na Tuhan,<br/>itu t''nagamu.<br/>',NULL,64581,1);
INSERT INTO stanza VALUES('I1209','1','Pohon hayat, bu-ah nyaman,<br/>penuh limpah Allah.<br/>Dulu mati, kini hidup,<br/>lapar jadi kenyang.<br/>',NULL,64582,1);
INSERT INTO stanza VALUES('I1209','2','Dia antar ke pohon hayat,<br/>nikmat Kristus limpah.<br/>Buka mulut, nikmat Kristus,<br/>sedapnya tak sudah!<br/>',NULL,64583,2);
INSERT INTO stanza VALUES('I1209','3','Kristus ia-lah suplai hayat,<br/>Dia makanan hayat.<br/>Nikmatku yang paling murni,<br/>s''la-in Dia, tak pu-as.<br/>',NULL,64584,3);
INSERT INTO stanza VALUES('I1209','4','Kini makan se-pu-as-nya,<br/>makanlah jalannya!<br/>Demi makan hayat masuk,<br/>hidupku sandar Dia.<br/>',NULL,64585,4);
INSERT INTO stanza VALUES('I1210','1','Allah t''lah b''rikan Putra-Nya,<br/>jadi pohon hayat kita.<br/>Agar Di-a kita kecap,<br/>Dia makanan kita!<br/>Dia makanan kita!<br/>Dia makanan kita!<br/>Kita kecap dan saksikan,<br/>Dia makanan kita!<br/>',NULL,64586,1);
INSERT INTO stanza VALUES('I1210','2','Lewat makan, terima Dia,<br/>lewat hidup,<br/>pamerkan Dia.<br/>Betapa kaya dan limpah,<br/>Dia hidangan kita.<br/>Dia hidangan kita!<br/>Dia hidangan kita!<br/>Makan Tuhan, pamerkan Dia,<br/>Dia hidangan kita!<br/>',NULL,64587,2);
INSERT INTO stanza VALUES('I1210','3','Kristuslah yang kita makan,<br/>Dia-lah manna dari surga.<br/>Menyuplai kita d''ngan limpah,<br/>s''lalu kita makan.<br/>S''lalu kita makan!<br/>S''lalu kita makan!<br/>Menyuplai kita d''ngan limpah,<br/>s''lalu kita makan!<br/>',NULL,64588,3);
INSERT INTO stanza VALUES('I1210','4','Nikmat amat sa-jian ini!<br/>Serba ada, kenyang pasti!<br/>Kini sia-pa saja ingin,<br/>boleh makan gratis.<br/>Boleh makan gratis!<br/>Boleh makan gratis!<br/>Kini sia-pa saja ingin,<br/>boleh makan gratis!<br/>',NULL,64589,4);
INSERT INTO stanza VALUES('I1211','1','Ma-nu-sia hidup bukan<br/>dari roti saja.<br/>Tapi dari tiap firman<br/>dari mulut Allah.<br/>',NULL,64590,1);
INSERT INTO stanza VALUES('I1211','chorus','Haleluya! Haleluya!<br/>Haleluya! Amin! Haleluya!<br/>',NULL,64591,2);
INSERT INTO stanza VALUES('I1211','2','Rohlah yang memb''ri hidup,<br/>daging tak berguna.<br/>Firman yang Ku katakan,<br/>itu roh dan hayat<br/>(Yohanes 6:63).<br/>',NULL,64592,3);
INSERT INTO stanza VALUES('I1211','3','Bertemu d''ngan firman-Mu,<br/>aku memakannya.<br/>Firman-Mu di hatiku,<br/>jadi sukacita<br/>(Yeremia 15:16).<br/>',NULL,64593,4);
INSERT INTO stanza VALUES('I1211','4','Terimalah pedang Roh,<br/>yakni firman Allah.<br/>Dalam segala do-a,<br/>do-a di dalam roh<br/>(Efesus 6:17-18).<br/>',NULL,64594,5);
INSERT INTO stanza VALUES('I1211','5','Dengan air dalam<br/>firman menyucikan g''reja.<br/>Dib''rikan kepada-Nya<br/>jadi g''reja mu-lia<br/>(Efesus 5:26-27).<br/>',NULL,64595,6);
INSERT INTO stanza VALUES('I1212','1','Tuhan Yesus, atas roti dan cawan.<br/>Syukur pu-jian tersembah pada-Mu.<br/>S''rentak puji, Dikau jadi makanan,<br/>hingga kami nikamti diri-Mu.<br/>',NULL,64596,1);
INSERT INTO stanza VALUES('I1212','chorus','Hati dan rohku, pujilah seg''ra.<br/>Dikau kecil, Dikau kecil.<br/>Hingga kekal, makan minum ''tiasa.<br/>Dikau kecil, Dikau kecil.<br/>',NULL,64597,2);
INSERT INTO stanza VALUES('I1212','2','Sungguh ka-si''an, ketika Kristus datang.<br/>Membawakan suplai hayat limpah.<br/>Insan tolak, malah sandar ajaran.<br/>Tidak tahu terapkan limpah-Nya.<br/>',NULL,64598,3);
INSERT INTO stanza VALUES('I1212','chorus','Kami perlu memakan diri-Mu.<br/>Sungguh a-jaib, sungguh nyaman!<br/>Makan Tuhan, kami dibangunkan.<br/>Hayat matang, nyata Kristus.<br/>',NULL,64599,4);
INSERT INTO stanza VALUES('I1212','3','Tuhan Yesus, Kau m''rendah datang bua-na.<br/>Bukan untuk jadi raja du-nia.<br/>Tapi jadi makanan, suplai insan.<br/>Bawa kami matang dalam hayat.<br/>',NULL,64600,5);
INSERT INTO stanza VALUES('I1212','chorus','(memakai koor bait pertama)<br/>',NULL,64601,6);
INSERT INTO stanza VALUES('I1212','4','Tuhan Yesus, Kau sungguh agung, mu-lia.<br/>Mahakua-sa, limpah tak terbatas.<br/>Tapi Dikau jadi makanan - kecil.<br/>Pu-jian bagi-Mu hingga abadi.<br/>',NULL,64602,7);
INSERT INTO stanza VALUES('I1213','1','Menang, menang,<br/>menang, balik ke semula!<br/>Dalam Kristus,<br/>Allah jadilah makanan.<br/>Makan minum ''tia-sa,<br/>kita nikmati Dia.<br/>Dalam pemu-li''an,<br/>nikmati saja.<br/>',NULL,64603,1);
INSERT INTO stanza VALUES('I1213','2','Seru Tuhan Yesus,<br/>o, betapa nyaman!<br/>Dia di mulut kita,<br/>tunggu kita makan.<br/>Dengan roh menyeru,<br/>singkir di-am, bisu.<br/>Dalam pemu-li''an,<br/>nikmati saja.<br/>',NULL,64604,2);
INSERT INTO stanza VALUES('I1213','3','Kunyah, kunyah, kunyah,<br/>bukan yang lu-ar-an.<br/>Lepas se-mua beban,<br/>duduk minum makan.<br/>Pesta, pesta, pesta,<br/>singkir pe-nge-ta''u-an.<br/>Dalam pe-mu-li''an,<br/>makan, minumlah!<br/>',NULL,64605,3);
INSERT INTO stanza VALUES('I1214','1','Tuhan memanggil kita,<br/>agar jadi pemenang.<br/>Mari jawab,"Ya, amin!" -<br/>menanglah!<br/>Gereja telah jatuh,<br/>teo-ri-teo-ri menumpuk,<br/>tidak menjamah hayat -<br/>menanglah!<br/>',NULL,64606,1);
INSERT INTO stanza VALUES('I1214','chorus','Menanglah! Menanglah!<br/>Lepas agama mati, menanglah!<br/>Tinggalkan gumul ronta,<br/>singkirkan s''mua yang usang.<br/>Makanlah diri Tuhan, menanglah!<br/>',NULL,64607,2);
INSERT INTO stanza VALUES('I1214','2','Allah telah tetapkan,<br/>agar ma-nu-sia makan.<br/>Makan, pemulihan-Nya -<br/>menanglah!<br/>Lekas, nikmati hayat,<br/>ikatan teo-ri lepas.<br/>Makan Kristus ''kan menang -<br/>menanglah!<br/>',NULL,64608,3);
INSERT INTO stanza VALUES('I1214','3','Doktrin tak ubah jiwa,<br/>malah m''rusak murad-Nya.<br/>Makan itu standar-Nya -<br/>menanglah!<br/>Makan barulah menang,<br/>sidang atau sen-di-rian.<br/>Makan hingga puas kenyang -<br/>menanglah!<br/>',NULL,64609,4);
INSERT INTO stanza VALUES('I1214','4','Mendesak kembali-Nya,<br/>demi minum dan makan.<br/>Lahir se-o-rang putra -<br/>menanglah!<br/>Untuk kaki dian Tuhan,<br/>untuk putra pemenang.<br/>Untuk memp''lai ''kenan-Nya -<br/>menanglah!<br/>',NULL,64610,5);
INSERT INTO stanza VALUES('I1215','1','"Mari makan!"<br/>Tuhan mengundang,<br/>"Mari makan!"<br/>Kapan saja boleh<br/>makan minum Dia!<br/>Tuhan makanan kita,<br/>Di-a pu-as-kan kita,<br/>"Mari makan!"<br/>Tuhan mengundang,<br/>"Mari makan!"<br/>',NULL,64611,1);
INSERT INTO stanza VALUES('I1215','2','"Mari makan!"<br/>Tuhan mengundang,<br/>"Mari makan!"<br/>Kapan saja boleh<br/>makan minum Dia!<br/>Di-a-lah hayat kita,<br/>terus penuhi kita.<br/>"Mari makan!"<br/>Tuhan mengundang,<br/>"Mari makan!"<br/>',NULL,64612,2);
INSERT INTO stanza VALUES('I1216','1','Minum! A-ir hayat mengalir dari takhta!<br/>Makan! Bu-ah hayat lezat pula berlimpah!<br/>Lihat! Kota Kudus sungguh terang benderang,<br/>ti-a-da malam!<br/>',NULL,64613,1);
INSERT INTO stanza VALUES('I1216','chorus','"Mari!" kata Roh dan mempelai p''rem-puan,<br/>"Mari! Marilah!" Jawab yang mendengar!<br/>Orang yang ha-us, marilah, minumlah!<br/>Minum air hayat!<br/>',NULL,64614,2);
INSERT INTO stanza VALUES('I1216','2','Kristuslah a-ir hayat dalamku t''rus ''ngalir.<br/>Kristuslah bu-ah hayat untuk ku nikmati.<br/>Kristuslah surya, bintang fajar, dan siang hari.<br/>Kristuslah almuhit!<br/>',NULL,64615,3);
INSERT INTO stanza VALUES('I1216','3','Jubah kita bersih, layak makan buah hayat.<br/>Tuhan, amin, haleluya, sungguhlah berkat!<br/>Kita latih roh kita untuk alami Dia -<br/>Kristuslah almuhit!<br/>',NULL,64616,4);
INSERT INTO stanza VALUES('I1216','4','Kini kita memiliki rumah nan terang.<br/>Saudara-saudari teguh pada tum-pu-an.<br/>G''reja lokal mi-nia-tur Yerusalem baru.<br/>Betapa mu-lia!<br/>',NULL,64617,5);
INSERT INTO stanza VALUES('I1217','1','Marilah! Marilah! Ke Ba-it Allah.<br/>Di sana ada aliran air hayat.<br/>Di kanan, siang malam, ''ngalir tak sudah.<br/>Mendiris kami hinga ber-buah lebat!<br/>',NULL,64618,1);
INSERT INTO stanza VALUES('I1217','2','Dari Ba-it ini a-ir memancar.<br/>Mengalir ke s''gala penjuru bua-na.<br/>Semoga air ini semakin dalam.<br/>Ukur kami hingga dimiliki-Nya!<br/>',NULL,64619,2);
INSERT INTO stanza VALUES('I1217','3','Ya, Tuhan! Ukurlah hari ke hari.<br/>Ukurlah kian banyak, jangan berhenti.<br/>Hingga kami nampak air jadi sungai.<br/>Berkat mengaliri seluruh bumi!<br/>',NULL,64620,3);
INSERT INTO stanza VALUES('I1217','4','Pimpinlah kami s''mua lewat aliran.<br/>Lewati aliran ulang-berulang.<br/>Hingga a-ir pasang, kami berenang.<br/>Berkecimpung dalam ka-ru-nia Allah!<br/>',NULL,64621,4);
INSERT INTO stanza VALUES('I1217','5','Hiduplah, hiduplah, hidup se-mu-a.<br/>Hiduplah karena aliran hayat.<br/>Semoga membawa k''limpahan hayat.<br/>Hingga ti-ap tempat g''reja ternyata!<br/>',NULL,64622,5);
INSERT INTO stanza VALUES('I1218','1','Kita minum a-ir hayat, a-ir ''ngalir bag'' pancaran!<br/>Meminumnya, pasti takkan ha-us selama-lamanya.<br/>Benarkah takkan ha-us? Ya, benar, tak ha-us!<br/>Benarkah takkan ha-us? Ya, benar, tak ha-us!<br/>Meminumnya, pasti takkan ha-us selama-lamanya.<br/>',NULL,64623,1);
INSERT INTO stanza VALUES('I1218','2','Kita makan roti hayat, ja-muan Allah t''lah se-di-a.<br/>Memakannya, pasti takkan lapar selama-lamanya.<br/>Benarkah takkan lapar? Ya, benar, tak lapar!<br/>Benarkah takkan lapar? Ya, benar, tak lapar!<br/>Memakannya, pasti takkan lapar selama-lamanya.<br/>',NULL,64624,2);
INSERT INTO stanza VALUES('I1218','3','Kita hirup hawa hayat, itulah Roh pem-b''ri-hayat.<br/>Menghirupnya, pasti kekal mendapatkan hayat Allah.<br/>Benarkah dapat hayat? Ya, benar, dapatkan!<br/>Benarkah dapat hayat? Ya, benar, dapatkan!<br/>Menghirupnya, pasti kekal mendapatkan hayat Allah.<br/>',NULL,64625,3);
INSERT INTO stanza VALUES('I1218','4','Kita kecap anggur hayat, rasa nikmat, tia-da tara.<br/>Mengecapnya, pasti ''tia-sa miliki sukacita-Nya.<br/>Benarkah sukacita? Ya, bersukacita!<br/>Benarkah sukacita? Ya, bersukacita!<br/>Mengecapnya, pasti ''tiasa miliki sukacita-Nya.<br/>',NULL,64626,4);
INSERT INTO stanza VALUES('I1218','5','Kristus Raja, mati bangkit, beri hayat pada insan.<br/>Terima Dia, pasti bah''gia, bahkan hidup selamanya.<br/>Benarkah hidup s''lama? Ya, hidup s''lamanya!<br/>Benarkah hidup s''lama? Ya, hidup s''lamanya!<br/>Terima Dia, pasti bah''gia, bahkan hidup selamanya.<br/>',NULL,64627,5);
INSERT INTO stanza VALUES('I1219','1','A-ir hayat (''Ngalir! ''Ngalir!)<br/>Air hayat ''ngalir (''Ngalir! ''Ngalir!)<br/>P''nuh hayat Allah (Hayat! Hayat!)<br/>Su-plai-an hayat (Suplai! Suplai!)<br/>Kita serupa (S''rupa! S''rupa!)<br/>dengan mulia-Nya (Mulia! Mulia!)<br/>Jadi corak-Nya,<br/>Allah dan manu-sia terpu-as-kan.<br/>Hayat berlimpah,<br/>suka tak batas,<br/>a-jaib, manis,<br/>makin ru-ah.<br/>Tuhan Sang Kaya,<br/>taklah terduga,<br/>mengalir,<br/>beri kenikmatan.<br/>Nikmat, nikmat terus,<br/>tumbuh, tidak henti,<br/>permata pun emas jadi rumah-Nya,<br/>saksi mu-lia.<br/>A-ir hayat  (''Ngalir! ''Ngalir!)<br/>Air hayat ''ngalir (''Ngalir! ''Ngalir!)<br/>P''nuh hayat Allah (Hayat! Hayat!)<br/>Su-plai-an hayat (Suplai! Suplai!)<br/>Kita serupa (S''rupa! S''rupa!)<br/>dengan mulia-Nya (Mulia! Mulia!)<br/>Jadi corak-Nya,<br/>Allah dan manu-sia terpu-as-kan.<br/>',NULL,64628,1);
INSERT INTO stanza VALUES('I1220','1','Hidup di Babilon dah''ga kering k''rontang,<br/>''ti-a-sa satupun memu-as-kan.<br/>Satu hari, ku datang dalam gereja,<br/>ku temukan sumber a-ir hayat.<br/>',NULL,64629,1);
INSERT INTO stanza VALUES('I1220','chorus','Pancaran a-ir hayat ku sesap,<br/>ri-ang tak hingga, anteroku lega!<br/>Pancaran a-ir hayat ku sesap,<br/>suplai limpah a-ja-ib-pun kekal.<br/>',NULL,64630,2);
INSERT INTO stanza VALUES('I1220','2','A-ir dari takhta alangkah manisnya,<br/>di batinku, mengalir ''ti-a-sa.<br/>Ku dapatkan sumber yang lama ku damba,<br/>hayat di sini limpah pun segar.<br/>',NULL,64631,3);
INSERT INTO stanza VALUES('I1220','3','Hai, saudara, marilah himpun bersama!<br/>Sumber nan limpah si-ap se-di-a.<br/>Gembala yang ba-ik menanti kau datang,<br/>agar terkabul yang kau harapkan.<br/>',NULL,64632,4);
INSERT INTO stanza VALUES('I1221','1','Kasih kur-nia dari Kristus,<br/>sesaplah sumber hayat!<br/>Mari puji, tia-da henti,<br/>di g''reja rumah-Nya.<br/>',NULL,64633,1);
INSERT INTO stanza VALUES('I1221','chorus','Mu-lia Allah!<br/>Menyesap sumber hayat!<br/>Mu-lia Allah!<br/>Kita di rumah-Nya!<br/>',NULL,64634,2);
INSERT INTO stanza VALUES('I1221','2','Tuhan suka beri kur-nia.<br/>Sesaplah sumber hayat!<br/>Tak usah cari ke mana.<br/>Dia ada di rumah.<br/>',NULL,64635,3);
INSERT INTO stanza VALUES('I1221','3','Bi-ar saja setan ''go-da.<br/>Sesaplah sumber hayat!<br/>Setan tidak mungkin,<br/>dapat mengalahkan kita.<br/>',NULL,64636,4);
INSERT INTO stanza VALUES('I1221','4','Sa-at dah''ga, lekas datang.<br/>Sesaplah sumber hayat!<br/>Sesap saja, jangan bimbang,<br/>kau ada di rumah.<br/>',NULL,64637,5);
INSERT INTO stanza VALUES('I1222','1','Haleluya!<br/>Dia-lah hayat,<br/>mari hirup Tuhan!<br/>Pada murid Dia menghembus,<br/>bahkan "Trimalah Roh Kudus."<br/>Kita hirup DI-a,<br/>kita hirup Di-a.<br/>Kini kita hirup Di-a.<br/>',NULL,64638,1);
INSERT INTO stanza VALUES('I1223','1','Kristus itu Roh pemb''ri  hayat,<br/>Kristus itu firman hayat.<br/>Roh hayat menyuplai di rohku,<br/>firman Kristus jadi hayat.<br/>Se-tiap waktu,<br/>makan minum dan hirup Dia!<br/>Se-tiap waktu,<br/>makan minum dan hirup Dia!<br/>',NULL,64639,1);
INSERT INTO stanza VALUES('I1223','2','Kristus itu Roh pemb''ri hayat!<br/>Kristus itu firman hayat!<br/>Roh hayat menyuplai di rohku,<br/>firman Kristus jadi hayat.<br/>Do-a baca, nyanyi,<br/>puji, s''ru nama-Nya!<br/>Do-a baca, nyanyi,<br/>puji, s''ru nama-Nya!<br/>',NULL,64640,2);
INSERT INTO stanza VALUES('I1224','1','Bernafas hirup Tuhan,<br/>amin! Amin!<br/>Demi-kian ku t''rus hidup,<br/>amin! Amin!<br/>Dia menghembus, ku menghirup,<br/>hayat-Nya ''ngalir lewatku.<br/>Ku t''lah b''lajar<br/>hirup Dia lu-ap penuh.<br/>',NULL,64641,1);
INSERT INTO stanza VALUES('I1224','2','Yahya 3:8 (tiga d''lapan) -<br/>hawa di lu-ar,<br/>angin berti-up ke<br/>mana ia ma-u.<br/>Entah datang dari mana,<br/>entah menuju ke mana.<br/>De-mi-ki-an lahir dari Roh Kudus.<br/>',NULL,64642,2);
INSERT INTO stanza VALUES('I1224','3','Yahya 20:22 (dua nol dua dua) -<br/>hawa di dalam,<br/>Yesus menghembuskan<br/>udara hayat.<br/>Asal kita menerima,<br/>demi hirup, bukan otak.<br/>Niscayalah mengalami<br/>hayat-Nya!<br/>',NULL,64643,3);
INSERT INTO stanza VALUES('I1224','4','Di mana-mana<br/>terdapat udara!<br/>Dia selalu<br/>menyelubungi kita!<br/>Kaya, limpah, gratis,<br/>se-dia,hidup kita limpah ru-ah.<br/>Mari kita se-mua,<br/>hirup Sang hayat!<br/>',NULL,64644,4);
INSERT INTO stanza VALUES('I1224','5','Seru saja nama-Nya,<br/>Tuhan Yesus!<br/>Di-a-lah nafas kita,<br/>Tuhan Yesus!<br/>Hirup dari lubuk batin,<br/>hingga hayat memenuhi.<br/>Yesuslah suplai hayat,<br/>benar sungguh!<br/>',NULL,64645,5);
INSERT INTO stanza VALUES('I1225','1','Tuhan dekat pada orang<br/>yang menyeru-Nya!<br/>Ti-ap seru, penyertaan-Nya<br/>mengu-at-kan!<br/>Cari Yesus. ''kan bertemu;<br/>seru, Dia dekat.<br/>Kita pun terhibur,<br/>karna Dia sungguh mesra!<br/>',NULL,64646,1);
INSERT INTO stanza VALUES('I1225','chorus','Yesus, nama indah!<br/>Tuhan Yesus, beri hayat!<br/>Nama menang, nama mu-lia,<br/>nama unggul, nama indah!<br/>Yesus, nama kua-sa!<br/>Tuhan Yesus, beri hibur!<br/>Hirup nama-Nya, seru ''ti-a-sa,<br/>Tuhan Yesus, nama indah!<br/>',NULL,64647,2);
INSERT INTO stanza VALUES('I1225','2','Asal seru nama Yesus,<br/>kita selamat. Tuhan Yesus,<br/>haleluya,<br/>lepas s''mua kekang!<br/>Angkat cawan kes''lamatan,<br/>seru nama-Nya.<br/>Kita ters''lamatkan<br/>dari banyak masalah!<br/>',NULL,64648,3);
INSERT INTO stanza VALUES('I1225','3','Yahudi atau Yunani,<br/>tia-da bedanya.<br/>Terhadap yang menyeru-Nya,<br/>Dia sungguh kaya.<br/>Tuhan Yesus, Tuhan Yesus,<br/>sungguh gembira!<br/>Seti-ap hirup nama-Mu,<br/>kami gembira!<br/>',NULL,64649,4);
INSERT INTO stanza VALUES('I1225','4','Kita nikmat ''tia-sa<br/>Tuhan pemberi kur-nia.<br/>Susah, senang, d''rita,<br/>bah''gia, tetap berseru!<br/>Asal aku masih hidup,<br/>ku ''kan berseru.<br/>Di-a senang mendengarkan,<br/>b''ri berkat kur-nia.<br/>',NULL,64650,5);
INSERT INTO stanza VALUES('I1225','5','De-mi-ki-an takkan penat,<br/>seru nama-Nya.<br/>Puji syukur kepada-Nya,<br/>terpanjat ''tia-sa.<br/>Kitalah orang yang<br/>berseru pada Tuhan.<br/>D''ngan orang yang suci hati,<br/>t''rima berkat-Nya.<br/>',NULL,64651,6);
INSERT INTO stanza VALUES('I1226','1','Seorang anak,<br/>Dia-lah Allah kua-sa.<br/>Seorang putra,<br/>Bapa Allah kekal.<br/>O, a-ja-ib!<br/>Allah insan pada-Nya.<br/>Penasihat,<br/>g''nap tebusan kekal.<br/>Pem''rintahan<br/>ada atas bahu-Nya!<br/>Raja da-mai,<br/>da-mai tak bersudah!<br/>',NULL,64652,1);
INSERT INTO stanza VALUES('I1227','1','Nama-Nya A-ja-ib,<br/>pula Penasihat.<br/>Allah Maha-kuasa,<br/>Bapa kekal.<br/>Sang Bayi terlahir,<br/>Putra diberikan,<br/>Dialah Raja damai,<br/>Yesus Tuhan.<br/>Puji Pencipta,<br/>Yesus Peny''lamat,<br/>Dia Roh pemb''ri hayat.<br/>Dalam roh kusembah,<br/>layan-i pun cinta.<br/>A-ja-ib nama-Nya,<br/>Yesus Tuhan.<br/>',NULL,64653,1);
INSERT INTO stanza VALUES('I1228','1','Kita s''mua hidup,<br/>demi hirup Tuhan,<br/>bukan demi pikiran,<br/>hiruplah jalannya.<br/>Seru,"Ya, Tuhan!"<br/>dari lubuk kita.<br/>Sukacita saksikan,<br/>kita hirup Tuhan.<br/>',NULL,64654,1);
INSERT INTO stanza VALUES('I1228','chorus','Hirup t''rus!<br/>Hirup t''rus!<br/>Kristuslah hayat!<br/>Dialah suplaian hayat,<br/>hirup dan berseru!<br/>Hirup t''rus!<br/>Hirup t''rus!<br/>Kristuslah hayat!<br/>Dialah suplaian hayat,<br/>hirup dan berseru!<br/>',NULL,64655,2);
INSERT INTO stanza VALUES('I1228','2','Dia sungguh a-jaib!<br/>Dia-lah nafas hayat.<br/>Dulu bertubuh daging,<br/>kini Dia nafasku.<br/>Wujud t''lah ganti,<br/>menjadi Roh itu.<br/>Allah hembuskan Kristus,<br/>ku hirup Roh Kudus!<br/>',NULL,64656,3);
INSERT INTO stanza VALUES('I1228','chorus','Kristuslah hayatku,<br/>di mana ju-a.<br/>Asal seru nama-Nya,<br/>nafas masuk rohku! (2x)<br/>',NULL,64657,4);
INSERT INTO stanza VALUES('I1229','1','Tuhan Yesus!<br/>Tuhan Yesus!<br/>Manislah nama Yesus!<br/>Paling segar,<br/>mesra manis,<br/>Tuhan Yesus!<br/>Amin!<br/>',NULL,64658,1);
INSERT INTO stanza VALUES('I1230','1','Kita t''lah dapat jalan singkat<br/>untuk jamah Tuhan.<br/>Tuhan berjanji s''lamatkan orang<br/>yang menyeru-Nya.<br/>Kapan saja kita demi roh<br/>berseru pada-Nya,<br/>pasti menjamah-Nya.<br/>Tuhan! Amin! Haleluya!<br/>Tuhan! Amin! Haleluya!<br/>Tuhan! Amin! Haleluya!<br/>Pasti menjamah-Nya!<br/>',NULL,64659,1);
INSERT INTO stanza VALUES('I1231','1','Sa-at seru,"Ya Yesus!"<br/>Batinku t''rasa ''bara.<br/>Hayat-Nya makin berkembang,<br/>tumbuh di dalamku.<br/>Mari seru,"Ya Yesus!"<br/>Girangnya tak terkata.<br/>Tuhan ''kan masuk dalammu,<br/>jadi suplai hayatmu.<br/>',NULL,64660,1);
INSERT INTO stanza VALUES('I1231','2','Mari seru,"Ya Yesus!"<br/>Dia ''kan membebaskanmu.<br/>Entahkan hatimu k''lana,<br/>s''perti kuda li-ar.<br/>Hanya seru,"Ya Yesus!"<br/>Walau di mana saja.<br/>Segera Di-a datanglah,<br/>Dia ada di dekatmu.<br/>',NULL,64661,2);
INSERT INTO stanza VALUES('I1231','3','Seru Tuhan Peny''lamat,<br/>Dia pasti mendengarkan.<br/>Mengapa tidak sandar Dia,<br/>beban jadi ringan?<br/>Di-a gunung batuku,<br/>pun ri-ang, sabat, t''naga.<br/>Asal kau kecap, tahulah,<br/>anug''rah-Nya tak tara.<br/>',NULL,64662,3);
INSERT INTO stanza VALUES('I1231','4','Yang terba-ik, ya Yesus,<br/>tungguh kau men''rima Dia.<br/>Marilah buka hatimu,<br/>Dia ''kan menolongmu.<br/>Sa-at Di-a kembali,<br/>kita tak takut, gentar.<br/>Me-lain-kan nampak mu-lia-Nya,<br/>jika biar-kan Dia tumbuh.<br/>',NULL,64663,4);
INSERT INTO stanza VALUES('I1232','1','Seru,"Tuhan",<br/>kau sebutkan kata yang sulit diungkap.<br/>Seru,"Tuhan",<br/>kau umumkan yang kau perlu hanya "Tuhan" saja.<br/>Se-lain Dia, tak damba,<br/>se-mua si-a-si-a.<br/>Hanya Dia-lah s''gala,<br/>ada Dia tak kurang.<br/>Seru "Tuhan Yesus!"<br/>Dia-lah segala.<br/>',NULL,64664,1);
INSERT INTO stanza VALUES('I1233','1','S''ru,"O, Tuhan Yesus!"<br/>me-ngu-at-kan roh kita!<br/>Jamah Dia dalam roh,<br/>resah jadi pu-ji-an!<br/>Jangan ma-u diganggu,<br/>tolak saja setan.<br/>Bertindak di dalam roh,<br/>janganlah gentar!<br/>S''ru,"O, Tuhan Yesus!"<br/>Nikmat-i Dia ''ti-a-sa.<br/>',NULL,64665,1);
INSERT INTO stanza VALUES('I1234','1','Seru,"O, Tuhan Yesus!",<br/>biar ku hidup dalam roh.<br/>''Tia-sa seru nama-Nya,<br/>rohku dipenuhi-Nya.<br/>',NULL,64666,1);
INSERT INTO stanza VALUES('I1234','chorus','"O, Tuhan Yesus!"<br/>"O, Tuhan Yesus!"<br/>"O, Tuhan Yesus!"<br/>T''rus,"O, Tuhan Yesus!"<br/>',NULL,64667,2);
INSERT INTO stanza VALUES('I1234','2','"O, Tuhan!" ia-lah jalan,<br/>baru ku takkan sesat.<br/>Ku seru si-ang malam,<br/>ku pasti ditolong-Nya.<br/>',NULL,64668,3);
INSERT INTO stanza VALUES('I1234','3','Dari jiwa pindah roh,<br/>s''ru nama-Nya,"O, Tuhan!"<br/>Lekat pandang pada-Nya,<br/>tak hentilah,"O, Tuhan!"<br/>',NULL,64669,4);
INSERT INTO stanza VALUES('I1234','4','De-mi-ki-an p''nuh Tuhan,<br/>Dia Roh Kudus pun hayat.<br/>Demi seru ''nyatakan,<br/>kasihku kepada-Nya.<br/>',NULL,64670,5);
INSERT INTO stanza VALUES('I1235','1','''Tia-sa s''ru nama Tuhan,<br/>maju serta-Nya.<br/>''Tia-sa s''ru nama Tuhan,<br/>memang giranglah.<br/>Meski awan mendung hitam,<br/>tutup jalanan.<br/>Seru saja nama-Nya,<br/>sirna niscaya.<br/>Just''ru Di-a-lah,<br/>kawan se-ti-a.<br/>Sandar pada-Nya,<br/>capai tempuhan.<br/>''Tia-sa s''ru nama Tuhan,<br/>maju serta-Nya.<br/>''Tia-sa s''ru nama Tuhan,<br/>memang giranglah.<br/>Meski awan mendung hitam,<br/>tutup jalanan.<br/>Seru saja nama-Nya,<br/>sirna niscaya.<br/>',NULL,64671,1);
INSERT INTO stanza VALUES('I1236','1','Sejak aku terlepas,<br/>hati penuhlah girang.<br/>Sejak aku terlepas mulut<br/>pun nyanyi girang.<br/>''Tia-sa seru nama-Nya,<br/>''nempuh hidup p''ri surga.<br/>Sunggulah nyaman!<br/>Sungguhlah nikmat!<br/>Sejak aku terlepas!<br/>',NULL,64672,1);
INSERT INTO stanza VALUES('I1237','1','Pagi kita berseru:<br/>Tuhan Yesus!<br/>Si-ang-pun berseru:<br/>Tuhan Yesus!<br/>Malam tetap berseru:<br/>Tuhan Yesus!<br/>Sepanjang hari s''ru:<br/>Tuhan Yesus!<br/>Dia tinggal di dalam roh,<br/>jangan sia-siakan waktu.<br/>Puji Hu! Puji Hu! O, ...<br/>',NULL,64673,1);
INSERT INTO stanza VALUES('I1237','2','Ber-s''ru dalam roh,<br/>nikmati limpah-Nya.<br/>Berk''luh dalam roh,<br/>menjamah Tuhan.<br/>Do-a dalam roh,<br/>hingga gai-rah ''bubung.<br/>Tinggal dalam roh,<br/>niscaya teguh.<br/>Berba-gian hayat limpah,<br/>makin serupa Tuhan.<br/>Mu-lia. Haleluya!<br/>Mu-lia bagi-Nya!<br/>Mu-lia. Haleluya!<br/>Mu-lia bagi-Nya!<br/>',NULL,64674,2);
INSERT INTO stanza VALUES('I1238','1','Dalam nama Yesus,<br/>dalam nama Yesus,<br/>kita pasti menang!<br/>Dalam nama Yesus,<br/>dalam nama Yesus,<br/>setan pasti gentar!<br/>Dalam nama Tuhan Yesus,<br/>tia-da yang melawan.<br/>Dalam nama Yesus,<br/>kita pasti menang!<br/>',NULL,64675,1);
INSERT INTO stanza VALUES('I1239','1','''Mas, perak ku tak punya,<br/>yang ku punya ku berikan:<br/>Demi nama Yesus Tuhan,<br/>ku perintah kau "Berjalan!"<br/>Dia berjalan, melompat,<br/>puji Tuhan!<br/>Jalan, melompat,<br/>puji Tuhan!<br/>Haleluya! Puji Tuhan!<br/>Mu-lia, mu-lia bagi Allah!<br/>',NULL,64676,1);
INSERT INTO stanza VALUES('I1239','2','''Mas, perak ku tak punya,<br/>Roh tujuh ganda ku punya:<br/>Demi nama Yesus Tuhan,<br/>teguh bersaksi bagi-Nya.<br/>Dalam gereja memuji, bersaksi,<br/>''ti-a-sa memuji,<br/>bersaksi.<br/>Haleluya, puji Tuhan!<br/>Mu-lia, mu-lia,<br/>bagi Allah!<br/>',NULL,64677,2);
INSERT INTO stanza VALUES('I1240','1','Kristus itu tanah subur,<br/>Allah b''ri pada kita!<br/>Gunung, lembah, sumber pancar,<br/>haleluya, mu-lia-lah!<br/>',NULL,64678,1);
INSERT INTO stanza VALUES('I1240','2','Kristus itu tanah subur,<br/>Allah b''ri pada kita!<br/>Susu, madu, serba cukup,<br/>limpah gratis, mu-lia-lah!<br/>',NULL,64679,2);
INSERT INTO stanza VALUES('I1240','3','Kristus itu tanah subur,<br/>Allah b''ri pada kita!<br/>Ada ara, ada anggur,<br/>suplaian limpah ru-ah!<br/>',NULL,64680,3);
INSERT INTO stanza VALUES('I1240','4','Kristus itu tanah subur,<br/>Allah b''ri pada kita!<br/>Nikmat minyak, padi, gandum,<br/>lezat, nyaman, mu-lia-lah!<br/>',NULL,64681,4);
INSERT INTO stanza VALUES('I1240','5','Giat menggarap, giat usaha,<br/>atas tanah nan permai!<br/>Si-ang, malam, tak k''nal penat,<br/>subur panen, mu-lia-lah!<br/>',NULL,64682,5);
INSERT INTO stanza VALUES('I1240','6','Pesta limpah dalam sidang,<br/>kenyang nikmati Tuhan!<br/>Bu-ah ''neka, ternak tambun,<br/>nikmati bersama Dia!<br/>',NULL,64683,6);
INSERT INTO stanza VALUES('I1240','7','Haleluya! Haleluya!<br/>Allah b''ri tanah permai!<br/>Terus garap, terus nikmat,<br/>haleluya, mu-lia-lah!<br/>',NULL,64684,7);
INSERT INTO stanza VALUES('I1241','1','Kristuslah tanah yang dijanjikan.<br/>Perang sandar Dia, musuh ''kan kalah.<br/>Ikut Panglima, masuk perhen-tian.<br/>Bagilah Anda dan aku.<br/>',NULL,64685,1);
INSERT INTO stanza VALUES('I1241','2','Kota berkubu, bukan kau bangun;<br/>rumah nan indah, bukan kau hi-as.<br/>Sumur yang ''bu-al, bukan kau gali;<br/>anggur, zai-tun tak kau tanam.<br/>',NULL,64686,2);
INSERT INTO stanza VALUES('I1241','3','Sungai dan sumber, ''ngalir di lembah,<br/>gandum, je-lai, buah, minyak dan madu.<br/>Tinggal di sini, tak kekurangan;<br/>mineral pun se-mua ada.<br/>',NULL,64687,3);
INSERT INTO stanza VALUES('I1241','4','Kita bersorak, datang ke Si-on;<br/>maju bersama, masuk bait-Nya.<br/>Arak, tu-ai-an, hasil berlimpah,<br/>tanah permai sungguh kaya.<br/>',NULL,64688,4);
INSERT INTO stanza VALUES('I1241','5','Kristus milikku, juga milikmu,<br/>nikmati Di-a, ti-a-da beda.<br/>Ba-gi-an kita, sungguh tak hingga;<br/>seluruhnya untuk kita.<br/>',NULL,64689,5);
INSERT INTO stanza VALUES('I1241','6','Nikmat nan limpah ''tas tanah indah,<br/>teteskan minyak, hasilkan madu.<br/>Limpah me-lu-ap, mari mengecap,<br/>Kristus tanah permai kita.<br/>',NULL,64690,6);
INSERT INTO stanza VALUES('I1241','7','Dia inkarnasi, t''rima derita,<br/>mati dan bangkit, na-ik ke surga.<br/>Dapat mu-li-a, pakai mahkota,<br/>kini Dia ada dalamku.<br/>',NULL,64691,7);
INSERT INTO stanza VALUES('I1241','8','Kita alami Kristus di batin,<br/>bawa limpah-Nya, bagai makanan.<br/>Sembahlah Kristus, Allah-insan puas.<br/>S''lamanya nyanyi tak henti.<br/>',NULL,64692,8);
INSERT INTO stanza VALUES('I1241','9','Puji Dia, jadi tanah permaiku.<br/>Puji Dia, jadi tanah permaimu.<br/>O, haleluya! Tanah yang mu-lia.<br/>Kini kita di dalamnya!<br/>',NULL,64693,9);
INSERT INTO stanza VALUES('I1242','1','Tanah permai, Allah beri kita;<br/>Kristus tanah permai itu.<br/>Ke-e-sa-an g''reja, berhimpun bersama.<br/>Lepas zaman bengkok, du-nia enyah tuntas!<br/>',NULL,64694,1);
INSERT INTO stanza VALUES('I1242','2','Mari datang! Pada tanah permai,<br/>kita jalan dalam Kristus.<br/>Tegak di tum-pu-an, garap tanah permai.<br/>Hayat tumbuh matang, sambut Tuhan datang!<br/>',NULL,64695,2);
INSERT INTO stanza VALUES('I1242','3','Kristus, Kristus, limpah tak terkata!<br/>G''reja - kepenuhan Kristus!<br/>Kita alami Dia, ''nyatakan ibadah.<br/>Dia-lah Sang A-ja-ib, se-mu-a bagi-Nya.<br/>',NULL,64696,3);
INSERT INTO stanza VALUES('I1243','1','Kita dapat tanah permai dari Allah,<br/>ti-ap hari, penuh limpah Kristus.<br/>Se-mua se-dia, tia-da kurang, darah adi,<br/>firman saksi, Roh itu dan g''reja.<br/>',NULL,64697,1);
INSERT INTO stanza VALUES('I1243','chorus','(Saudari)<br/>Dapatkan tanah, hai saudara!<br/>Allah beri pada kita.<br/>Tegap berperang, kita ''kan menang!<br/>Tanah permai! Sungguh mulia!<br/>(Saudara)<br/>Dapatkan tanah, hai saudari!<br/>Serah diri, ikut ketat.<br/>Di-a memanggil, jalan di depan,<br/>se-mu-a Dia yang berikan.<br/>',NULL,64698,2);
INSERT INTO stanza VALUES('I1243','2','Ada darah, Kristus kurban tanpa cela;<br/>Dia tersembah, Allah pun pu-as-lah.<br/>Hingga kita dengan b''rani hampir Allah,<br/>asal ''tia-sa pakai darah adi.<br/>',NULL,64699,3);
INSERT INTO stanza VALUES('I1243','3','Ada firman, sebagai makanan kita,<br/>kita nikmat pula kata "Amin".<br/>Ti-ap hari, Roh-Nya beri per-ka-ta-an,<br/>dari dalam garap, atur kita.<br/>',NULL,64700,4);
INSERT INTO stanza VALUES('I1243','4','Ada Roh-Nya, sebagai Roh re-a-li-tas,<br/>bukan kita, tapi bersandar Dia.<br/>Roh mengajar kita tinggal di dalam-Nya,<br/>bawa kita masuk re-a-li-tas.<br/>',NULL,64701,5);
INSERT INTO stanza VALUES('I1243','5','Masih ada g''reja, betapa mustika!<br/>Nikmat limpah tak ''kan kekurangan.<br/>Kita himpun, dapatkan Kristus almuhit,<br/>Di-a-lah segala-gala kita.<br/>',NULL,64702,6);
INSERT INTO stanza VALUES('I1244','1','Diam di tanah per-mai,<br/>me-ngu-at-kan roh kita!<br/>Rajinlah menggarap,<br/>nikmat Kristus tak batas!<br/>Limpah kaya Tuhan,<br/>dan segala ku-at-Nya<br/>jadilah pengalaman<br/>kita ''ti-a-sa!<br/>Almuhitlah Di-a,<br/>kita di tanah permai!<br/>',NULL,64703,1);
INSERT INTO stanza VALUES('I1245','1','Kita menetap di tanah permai!<br/>O, haleluya, per-mai-lah!<br/>Kristus itulah tanah nan permai!<br/>Puji Tuhan, sungguh permai!<br/>Susu, madu, gandum, jelai,<br/>minyak, arak, limpah suplai.<br/>Kita menetap di tanah permai!<br/>O, haleluya, nan permai!<br/>',NULL,64704,1);
INSERT INTO stanza VALUES('I1245','2','Di tanah permai, subur berlimpah,<br/>aneka gandum dan bu-ah.<br/>Ada mata air, ada pancaran,<br/>aliran tak kesudahan.<br/>Ingin nikmat produksinya?<br/>Rajin-rajinlah menggarap!<br/>Sajikan Kristus ti-ap bersidang,<br/>Kristus suplaian terindah!<br/>',NULL,64705,2);
INSERT INTO stanza VALUES('I1246','1','Tuhan Kaulah tanah<br/>permai unggul lu-as,<br/>untuk kami nikmat,<br/>hari-hari garap!<br/>A-ir hayat ''ngalir,<br/>bangkit dari mati,<br/>ada arak, bu-ah,<br/>air susu dan minyak.<br/>',NULL,64706,1);
INSERT INTO stanza VALUES('I1246','2','Kami batu hidup,<br/>bahan bangunan-Nya.<br/>Tujuh soko guru,<br/>genap tu-juan Allah!<br/>Kemenangan Kristus,<br/>untuk ganyang lawan.<br/>K''ra-ja-an-Nya datang,<br/>m''raja hingga kekal.<br/>',NULL,64707,2);
INSERT INTO stanza VALUES('I1247','1','Pagi kita garap,<br/>si-ang kita garap,<br/>senja tetap garap,<br/>terus menggarap.<br/>Hasil tanah permai,<br/>bersama di-tu-ai,<br/>se-tiap kita sidang,<br/>bawa tu-ai-an.<br/>',NULL,64708,1);
INSERT INTO stanza VALUES('I1247','chorus','Bawa tu-ai-an,<br/>bawa tu-ai-an!<br/>Dengan riang gembira,<br/>bawa tu-ai-an!<br/>Bawa tu-ai-an,<br/>bawa tu-ai-an!<br/>Dengan riang gembira,<br/>bawa tu-ai-an!<br/>',NULL,64709,2);
INSERT INTO stanza VALUES('I1247','2','Tu-ai jelai, gandum,<br/>nyata, mati, bangkit.<br/>Meski jumpa rugi,<br/>diri terkubur.<br/>Tapi dalam bangkit,<br/>alami hayat-Nya.<br/>Se-tiap kita sidang,<br/>bawa tu-ai-an.<br/>',NULL,64710,3);
INSERT INTO stanza VALUES('I1247','3','Anggur, bu-ah ara,<br/>delima. Za-i-tun.<br/>Nyaman, mesra, limpah,<br/>unggul pun indah.<br/>Lembu, domba kurban,<br/>susu, madu pula.<br/>Persembahkan se-mua,<br/>bawa tu-ai-an.<br/>',NULL,64711,4);
INSERT INTO stanza VALUES('I1248','1','Kecaplah akan Tuhan!<br/>Haleluya!<br/>Di-a-lah paling sedap,<br/>haleluya!<br/>Ku sudahlah mengecap-Nya,<br/>haleluya!<br/>Memang benar Tuhan sedap,<br/>haleluya!<br/>',NULL,64712,1);
INSERT INTO stanza VALUES('I1248','2','Pandanglah akan Tuhan!<br/>Haleluya!<br/>Di-a-lah paling elok,<br/>haleluya!<br/>Ku sudahlah memandang-Nya,<br/>haleluya!<br/>Memang benar Tuhan elok,<br/>haleluya!<br/>',NULL,64713,2);
INSERT INTO stanza VALUES('I1248','3','Ci-um-lah akan Tuhan,<br/>haleluya!<br/>Di-a-lah paling harum,<br/>haleluya!<br/>Ku sudahlah men-ci-um-Nya,<br/>haleluya!<br/>Memang benar Tuhan harum,<br/>haleluya!<br/>',NULL,64714,3);
INSERT INTO stanza VALUES('I1249','1','Mari, makan Tuhan,<br/>hidup gereja,<br/>roh terpelihara,<br/>hayat berkembang.<br/>Sa-at hati penuh sebal dan gudah,<br/>datang nikmati Tuhan!<br/>Segera, makan Dia;<br/>gereja terbina.<br/>Janganlah kau ragu,<br/>Tuhan b''ri hibur berkat.<br/>Mari, makan Tuhan,<br/>hidup gereja, roh terpelihara,<br/>hayat berkembang.<br/>Sa-at hati penuh sebal dan gundah,<br/>datang nikmati Tuhan!<br/>',NULL,64715,1);
INSERT INTO stanza VALUES('I1249','2','Mari, b''ri kesak-sian,<br/>nikmat bersama.<br/>Se-mu-a terbina,<br/>rohmu pun ku-at.<br/>K''limpahanmu banyak,<br/>jangan disimpan,<br/>mari membagi nikmat!<br/>Nikmati bersama,<br/>gereja terbina.<br/>Janganlah kau ragu,<br/>kita perlu p''lihara.<br/>Mari, b''ri kesak-sian,<br/>nikmat bersama.<br/>Se-mu-a terbina,<br/>rohmu pun ku-at.<br/>K''limpahanmu banyak,<br/>jangan disimpan,<br/>mari membagi nikmat!<br/>',NULL,64716,2);
INSERT INTO stanza VALUES('I1250','1','Kita nampak ki-at hidup.<br/>Nampak visi ilahi.<br/>Kita tinggal dalam Kristus,<br/>kita tinggal dalam pokok anggur.<br/>',NULL,64717,1);
INSERT INTO stanza VALUES('I1250','chorus','Dalam pokok anggur,<br/>dalam pokok anggur.<br/>Limpah hayat Allah bu-at-ku!<br/>(Buat-mu, buat kita s''mua, hai!)<br/>Kini, ku di sini, tidak pergi lagi,<br/>ku tinggal dalam pokok anggur.<br/>',NULL,64718,2);
INSERT INTO stanza VALUES('I1250','2','Tak perlu lagi bergumul.<br/>Mencari jalan masuk.<br/>Kini kita t''lah di dalam.<br/>Haleluya, dalam pokok anggur.<br/>',NULL,64719,3);
INSERT INTO stanza VALUES('I1250','3','Urapan kerja di batin.<br/>Urapan yang ilahi.<br/>Urapkan hakiki Allah.<br/>Sa-at tinggal dalam pokok anggur.<br/>',NULL,64720,4);
INSERT INTO stanza VALUES('I1250','4','Hidup dalam arus hayat.<br/>Terang pancar di dalam.<br/>Allah dan insan, serumah.<br/>Saling tinggal dalam pokok anggur.<br/>(Perlu ditambah tentang berbuah!)<br/>',NULL,64721,5);
INSERT INTO stanza VALUES('I1251','1','Ku milik Tuhan!<br/>Sukacita sungguh.<br/>Re-ak-si manis<br/>t''radap kasih-Mu.<br/>Iman jawab,"Ya",<br/>t''radap bi-sik-an-Mu,<br/>"Jangan takut,<br/>eng-kau-lah milikKu."<br/>',NULL,64722,1);
INSERT INTO stanza VALUES('I1251','2','Ku milik Tuhan!<br/>Peng-a-ku-an ri-ang.<br/>Mempelai putri,<br/>sangat ba-ha-gia.<br/>Kasih jawab,"Mau",<br/>t''rima Dia s''lamanya.<br/>Kasih, hormat,<br/>ta-at kepada-Nya.<br/>',NULL,64723,2);
INSERT INTO stanza VALUES('I1251','3','Ku milik Tuhan!<br/>Ajarku maknanya.<br/>Mencakup kasih<br/>dan ke-se-tia-an.<br/>P''layanan kudus,<br/>penyerahan mutlak.<br/>Ta-at kepada-Mu<br/>tanpa syarat.<br/>',NULL,64724,3);
INSERT INTO stanza VALUES('I1251','4','Ku milik Tuhan!<br/>Tubuh, jiwa, dan roh.<br/>Kau me-te-rai-kan,<br/>milik-Mu s''lama.<br/>Seperti Engkau,<br/>dalam kasih kur-nia.<br/>Jadi milikku<br/>s''lama-lamanya.<br/>',NULL,64725,4);
INSERT INTO stanza VALUES('I1301','1','Yesus, kasihku, Kau menarik-ku,<br/>Hingga ku mendambakan datang pada-Mu.<br/>Hingga ku mendambakan datang pada-Mu.<br/>Kaulah kasihku, oh, elok, mes-ra sungguh,<br/>Hati amat merindukan-Mu;<br/>Kaulah kasihku, oh, elok, mes-ra sungguh,<br/>Hati amat merindukan-Mu.<br/>',NULL,64726,1);
INSERT INTO stanza VALUES('I1301','2','Yesus, kasihku, Kau paling unggul,<br/>Harum s''merbak minyak-Mu, jadi ri-ang-ku,<br/>Harum s''merbak minyak-Mu, jadi ri-ang-ku.<br/>Kau-lah mata air, pun sumber a-ir hidup,<br/>''Ngalir dari gunung Libanon,<br/>Kau-lah mata air, pun sumber a-ir hidup,<br/>Ngalir dari gunung Libanon.<br/>',NULL,64727,2);
INSERT INTO stanza VALUES('I1301','3','Mari, kasihku, kita ke padang,<br/>Aneka ba-u harum, wangi semerbak,<br/>Aneka ba-u harum, wangi semerbak.<br/>Aku t''lah datang, o, dinda pengantin-Ku,<br/>Minum anggur, susu, dan madu;<br/>Aku t''lah datang, o, dinda pengantin-Ku,<br/>Minum anggur, susu, dan madu.<br/>',NULL,64728,3);
INSERT INTO stanza VALUES('I1301','4','Tuhan, ukirlah ku di hati-Mu,<br/>Ke-ga-i-rah-an gigih sep''ri ke-ma-tian,<br/>Kasih sangatlah ku-at, seperti ma-ut,<br/>Sungai, air banyak, tak dapat memadamkan,<br/>Kasih-Mu yang tia-da taranya,<br/>Sungai, air banyak, tak dapat memadamkan,<br/>Kasih-mu yang tia-da taranya.<br/>',NULL,64729,4);
INSERT INTO stanza VALUES('I1302','1','Nama-Mu, mi-nyak ter-cu-rah,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Nama-Mu, minyak tercurah,<br/>Nama-Mu, minyak tercurah.<br/>',NULL,64730,1);
INSERT INTO stanza VALUES('I1302','2','Kasih-Mu lam-pau-i anggur,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Kasih-Mu lam-pau-i anggur,<br/>Kasih-Mu lam-pau-i anggur,<br/>',NULL,64731,2);
INSERT INTO stanza VALUES('I1302','3','Gadis-gadis pun cinta-Mu,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Gadis-gadis pun cinta-Mu,<br/>Gadis-gadis pun cinta-Mu,<br/>',NULL,64732,3);
INSERT INTO stanza VALUES('I1302','4','Manis, Dikau, Kekasihku,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Manis, Dikau, Kekasihku,<br/>Manis, Dikau, Kekasihku,<br/>',NULL,64733,4);
INSERT INTO stanza VALUES('I1302','5','Ku t''lah dapat Yang ku damba,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Manis, Dikau, Kekasihku,<br/>Manis, Dikau, Kekasihku,<br/>',NULL,64734,5);
INSERT INTO stanza VALUES('I1302','6','Dia ku tarik, tak ku lepas,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Dia ku tarik, tak ku lepas,<br/>Dia ku tarik, tak ku lepas,<br/>',NULL,64735,6);
INSERT INTO stanza VALUES('I1302','7','Datanglah seg''ra, Kasihku,<br/>Ye-sus, Ye-sus, Ye-sus, Ye-sus,<br/>Datanglah seg''ra, Kasihku,<br/>Datanglah seg''ra, Kasihku,<br/>',NULL,64736,7);
INSERT INTO stanza VALUES('I1303','1','Di atas ranjang ku cari,<br/>jantung hatiku, kekasihku.<br/>Ku mencari, berkeliling,<br/>tapi tak ku te-mui.<br/>Hai saudara, beritahuku,<br/>kekasihku ada di mana,<br/>ku ''kan bawa Dia ke rumah,<br/>ku nikmati lagi kasih-Nya.<br/>Ka-li-an yang membimbingku,<br/>baru ku p''roleh perseku-tuan.<br/>Ternyata Dia di sampingku,<br/>tak meninggalkanku.<br/>',NULL,64737,1);
INSERT INTO stanza VALUES('I1303','2','Ku dapat jadi kasih-Mu,<br/>penuh Roh Kudus p''ri tiang asap.<br/>T''ladani mati, bangkit-Mu,<br/>harum mur, kemenyan.<br/>Aku dapat jadi joli-Mu,<br/>lewatku gerak dan sabat-Mu.<br/>Ku menjadi pahlawan-Mu,<br/>hadapi kedahsyatan malam.<br/>Kar''na banyak orang garap,<br/>ku nyaman marem di dalamnya.<br/>Kar''na kasih-Mu tak batas,<br/>garapku s''rupa-Mu.<br/>',NULL,64738,2);
INSERT INTO stanza VALUES('I1303','3','O, ku damba ke gunung mur,<br/>agar diriku dimatikan.<br/>Pula ke bukit kemenyan,<br/>hingga bayang hilang.<br/>Kau sebut aku cantik sungguh,<br/>Kau nikmat kasih ter-ba-ik-ku.<br/>Kejap mataku pikat-mu<br/>minyakku semerbak pun unggul.<br/>Ku ma-u dari Libanon,<br/>alami ke-naik-an unggul-Mu.<br/>Juga rela diam di Hermon,<br/>megahkan salib-Mu.<br/>',NULL,64739,3);
INSERT INTO stanza VALUES('I1303','4','Bibirku bertetes madu,<br/>Kau nikmati manisnya cinta.<br/>Hidupku penuh bau harum,<br/>seperti Libanon.<br/>Tuhan, datanglah secepatnya,<br/>seluruh diriku milik-Mu.<br/>Kebun, mata air tertutup,<br/>hanya untuk Dikau melulu.<br/>Kebun hatiku semerbak,<br/>oleh angin utara, s''latan.<br/>Bawa Kekasihku masuk,<br/>nikmati milik-Nya.<br/>',NULL,64740,4);
INSERT INTO stanza VALUES('I1304','1','Akulah milik-Nya,<br/>Dia-lah pu-ja-an-ku.<br/>Mari kita pergi ke ladang.<br/>Tinggal di antara<br/>bunga-bunga pacar.<br/>Menikmati kasih mesra.<br/>',NULL,64741,1);
INSERT INTO stanza VALUES('I1304','2','Pagi-pagi bangun,<br/>''nuju kebun anggur.<br/>Nikmat bu-ah-bu-ah nan sedap.<br/>Anggur dan delima,<br/>sudahkah berbunga.<br/>Di sana ku b''rikan cinta.<br/>',NULL,64742,2);
INSERT INTO stanza VALUES('I1304','3','Harum buah du-da-im,<br/>berbagai buah lezat.<br/>Bagi-Mu se-mu-a tersimpan.<br/>Cinta kasih mesra,<br/>kita nikmat sama.<br/>Kasih sungguh amat ku-at.<br/>',NULL,64743,3);
INSERT INTO stanza VALUES('I1305','1','Cantik-Mu, Tuhan, rebut hatiku,<br/>hatiku terbuka pada-Mu.<br/>Lepasku dari ri-tual agama,<br/>agar ku nikmati hadir-Mu.<br/>Sa-at ku pandang ke-mu-lia-an-Mu,<br/>hatiku penuh d''ngan mulia-Mu.<br/>Penuh-i-lah diriku, ya Tuhan,<br/>biar Roh-Mu berba-ur d''ngan rohku.<br/>',NULL,64744,1);
INSERT INTO stanza VALUES('I1305','2','Sang Terang, langitku jernih cerah,<br/>ku nampak Ma-nu-sia di takhta.<br/>Sang Kudus, d''ngan api membakarku,<br/>hingga ku pancarkan cah''ya-Mu!<br/>Kali pertama nampak mu-lia-Mu,<br/>bangga dan sayang diri sirna.<br/>Hatiku penuh kasih dan pu-jian,<br/>kecap kemanisan nama-Mu.<br/>',NULL,64745,2);
INSERT INTO stanza VALUES('I1305','3','Tuhanku, ku bawa narwastuku,<br/>d''ngan kasih ku pecah bagi-Mu.<br/>Ku datang urapi kepala-Mu,<br/>sembahkan yang ter-baik bagi-Mu.<br/>Kekasih, ku boroskan diriku,<br/>dari lubuk cinta pada-Mu.<br/>Ku siap-kan minyak mahal bagi-Mu,<br/>curah kasih dari lubukku.<br/>',NULL,64746,3);
INSERT INTO stanza VALUES('I1305','4','Kasihku, cepat datang ke gunung,<br/>ku rindu menatap wajah-Mu.<br/>Minumlah sumber dari hatiku,<br/>ku damba s''lalu di sisi-Mu.<br/>Tak sen-di-ri-an mengasihi-Mu,<br/>d''ngan kaum saleh jadi jodoh-Mu.<br/>Cepat datang, kami lama tunggu,<br/>agar pu-as lega hati-Mu.<br/>',NULL,64747,4);
INSERT INTO stanza VALUES('I1306','1','Yesus, Yesus,<br/>dengar ku utarakan,<br/>nama-Mu limpah t''radapku,<br/>ku cinta-Mu.<br/>',NULL,64748,1);
INSERT INTO stanza VALUES('I1307','1','O, nama nan ku gemar-i,<br/>nilainya ku nyanyi.<br/>Merdu, nyaman, p''rilah musik,<br/>du-nia ti-ada sa-ing.<br/>',NULL,64749,1);
INSERT INTO stanza VALUES('I1307','chorus','Ku cintalah Yesus!<br/>Ku cintalah Yesus!<br/>Ku cintalah Yesus!<br/>Dia du-luan cintaku.<br/>',NULL,64750,2);
INSERT INTO stanza VALUES('I1307','2','Nama-Nya nyatakan cinta,<br/>wafat-Nya b''ri bebas.<br/>Darah-Nya sudah tercurah,<br/>abadi membela.<br/>',NULL,64751,3);
INSERT INTO stanza VALUES('I1307','3','Bagi aku, Allah Bapa<br/>atur beres s''gala.<br/>Walau aku ''nempuh gelap,<br/>''nyorotlah cah''ya-Nya!<br/>',NULL,64752,4);
INSERT INTO stanza VALUES('I1307','4','Hati-Nya penuhlah cinta,<br/>hibur dukacita.<br/>Ti-ap picik Dia u-rai-kan,<br/>besarlah rahmat-Nya.<br/>',NULL,64753,5);
INSERT INTO stanza VALUES('I1308','1','Tuhan dapatkan orang: Abraham,<br/>ba-gai teman. Sa-mu-el, si penyeru.<br/>Raja Da-ud, penuh pu-jian;<br/>kini sekelompok.<br/>',NULL,64754,1);
INSERT INTO stanza VALUES('I1308','2','Kami damba menjadi orang yang layani-Mu,<br/>mengerti keper-luan-Mu.<br/>Dikau lega pula senang,<br/>jadi sahabat-Mu, ga-ul akrab.<br/>',NULL,64755,2);
INSERT INTO stanza VALUES('I1308','chorus','Kami memuji, kami menyeru,<br/>paling pada-Mu.<br/>Kau yang mengatur, hanya cinta-Mu,<br/>sampai s''lamanya. Takkan berubah.<br/>',NULL,64756,3);
INSERT INTO stanza VALUES('I1308','3','Tuhan, limpah rahmat-Mu,<br/>tak kikir t''radap kami!<br/>Kami insan korporat, bagi kehendak kekal-Mu.<br/>inta hingga kekal, tak berubah ...<br/>',NULL,64757,4);
INSERT INTO stanza VALUES('I1308','chorus','Kami memuji, kami menyeru,<br/>paling pada-Mu.<br/>Kau yang mengatur, hanya cinta-Mu,<br/>sampai s''lamanya. Takkan berubah.<br/>',NULL,64758,5);
INSERT INTO stanza VALUES('I1309','1','Ya, Tuhan! Ku s''rahkan diriku,<br/>se-lain Kau, ku tak mau,<br/>du-nia sudah pupus.<br/>Du-ni-a, di tangan si jahat,<br/>tapi ku milik-Mu,<br/>kasih-Mu jaminku.<br/>',NULL,64759,1);
INSERT INTO stanza VALUES('I1309','chorus','Kini ku s''rahkan s''luruh, ya Tuhan,<br/>ku ma-u alami arus hayat.<br/>Yesus, Yesus, Yesus, Yesus, Yesus,<br/>segenap hati, Di-kau ku cinta.<br/>',NULL,64760,2);
INSERT INTO stanza VALUES('I1309','2','Ku damba dariku Kau ''ngalir,<br/>hatiku tak ingin,<br/>terisi hal la-in.<br/>Pada-Mu ku berseru nyaring,<br/>agar mesra, manis,<br/>dariku teralir.<br/>',NULL,64761,3);
INSERT INTO stanza VALUES('I1309','3','Terang-Mu tiap hari sorot t''rus,<br/>singkir s''mua yang semu,<br/>biar ku tak tertipu.<br/>Betapa ku perlu terang-Mu,<br/>sorotiku s''lalu,<br/>ku jadi milik-Mu.<br/>',NULL,64762,4);
INSERT INTO stanza VALUES('I1309','4','Bersihkan, tia-da lagi dosa,<br/>tiap hari Kau ubah,<br/>hayat-Mu berperan.<br/>Ampuni dosa dan lemahku,<br/>bersih lahir batin,<br/>air hayat le-lua-sa.<br/>',NULL,64763,5);
INSERT INTO stanza VALUES('I1309','5','Giranglah, hayat, sejahtera,<br/>nikmat hadir Tuhan,<br/>ma-ut gelap sirna.<br/>Giranglah, s''kutu hayat mesra,<br/>bahkan rasa surga,<br/>takkanlah setara.<br/>',NULL,64764,6);
INSERT INTO stanza VALUES('I1309','chorus','Kini ku s''rahkan s''luruh, ya Tuhan.<br/>Puji Tuhan atas arus hayat.<br/>Yesus, Yesus, Yesus, Yesus, Yesus,<br/>segenap hati, Dikau ku cinta.<br/>',NULL,64765,7);
INSERT INTO stanza VALUES('I1310','1','Betapa senang,<br/>sa-at ku ti-a-da jalan.<br/>Dia rebut hatiku dari g''lap<br/>pekat masuk dalam k''ra-ja-an-Nya.<br/>',NULL,64766,1);
INSERT INTO stanza VALUES('I1310','2','Hidup yang baru,<br/>memiliki hayat Anak.<br/>Ku tak mabuk lagi di dalam mimpi,<br/>sumber hidup pun mengalir!<br/>',NULL,64767,2);
INSERT INTO stanza VALUES('I1310','3','Paling pada-Nya,<br/>Dia menyuplaikan hayat-Nya.<br/>Hayat-Nya jadi rea-li-tas hidupku,<br/>o haleluya, dalamku!<br/>',NULL,64768,3);
INSERT INTO stanza VALUES('I1310','4','Aku cinta-Mu,<br/>bakarlah cinta yang la-in.<br/>Kini hingga kekal, Kaulah hayatku,<br/>Kaulah segala-galaku.<br/>',NULL,64769,4);
INSERT INTO stanza VALUES('I1311','1','Pesona kasih-Mu segar, sejuk,<br/>melampau-i madu, resap, sedap, jitu!<br/>Genggamlah tanganku, bawa maju,<br/>rebah di ri-baan-Mu, asmara kudus.<br/>Tuhan, ku rindu akan cinta-Mu,<br/>bernaung pada kasih-Mu.<br/>O, panji cinta-Mu memang satu,<br/>diri-Mu dengan kasih-Mu.<br/>',NULL,64770,1);
INSERT INTO stanza VALUES('I1311','2','Dikau mustikaku nan melulu.<br/>Dikau sasaranku, ku cinta diri-Mu.<br/>Sekadar menebus d''ngan kasih-Mu,<br/>tidak cukup pu-as-kan roh, hatiku.<br/>Tuhan, ku rindu akan diri-Mu,<br/>Dikaulah segalaku.<br/>Sang Pengasih agung, ku menuntut,<br/>Kaulah mustika tunggalku.<br/>',NULL,64771,2);
INSERT INTO stanza VALUES('I1312','1','Saat tercelup kasih-Nya,<br/>tuntut, kuatir hilanglah.<br/>Kasih-Nya na-ung-i ''tia-sa,<br/>pada-Nya aku lenyap.<br/>Bila pandang wajah mu-lia,<br/>tak kepalang mesranya.<br/>Ku tak tahan jatuh cinta,<br/>lekat, lebur, tak pisah.<br/>Sa-at tercelup kasih-Nya,<br/>tuntut, kua-tir hilanglah.<br/>Kasih-Nya na-ung-i ''tia-sa,<br/>pada-Nya aku lenyap.<br/>',NULL,64772,1);
INSERT INTO stanza VALUES('I1312','2','Tinggal dalam kasih Tuhan,<br/>saling ber-se-ku-tu-an.<br/>Tertambat oleh kasih-Nya,<br/>erat padu s''lamanya.<br/>Kasih-Nya ''ngitari kita,<br/>saling sayang mesralah.<br/>Dalam kasih hidup sama,<br/>s''mua hati lekat esa.<br/>Tinggal dalam kasih Tuhan,<br/>saling ber-se-ku-tu-an.<br/>Tertambat oleh kasih-Nya,<br/>erat padu s''lamanya.<br/>',NULL,64773,2);
INSERT INTO stanza VALUES('I1313','1','Dulu ku sering,<br/>s''ru Tuhan Yesus,<br/>namun tak se-ri-il<br/>ini menjamah Tuhan,<br/>tanpa terduga,<br/>nampak wajah-Mu, ya,<br/>Yesus, ku cinta pada-Mu!<br/>Cinta-Mu!<br/>Yesus! A-ja-ib Yesus!<br/>Sungguhlah,<br/>Penolongku, Tuhan,<br/>cintaku untuk-Mu,<br/>tiap hari, sukacita, nikmat diri-Mu!<br/>',NULL,64774,1);
INSERT INTO stanza VALUES('I1313','2','Perkara du-nia, ku tak berpa-uit,<br/>ku telah dapatkan Juruselamat hayat,<br/>biar se-mua musnah,<br/>asalku dapat di dalam gereja.<br/>Cinta-Mu! Yesus!<br/>',NULL,64775,2);
INSERT INTO stanza VALUES('I1314','1','Kami dan Yesus sayang,<br/>sama nikmat gembira,<br/>bangkit rasa kasih,<br/>nyanyi bagi Tuhan,<br/>nyanyikan lagu baru.<br/>Dapat damai dari-Nya,<br/>kar''na-Nya kita bebas;<br/>Dia Juruselamat,<br/>juga hayat kita,<br/>d''ngan kita kekal esa!<br/>Yesus! Yesus, kaya nama-Mu!<br/>Lucut se-mua belenggu,<br/>nyanyikan lagu baru.<br/>Haleluya, nyanyi bu-at-Mu.<br/>Kami dan Yesus sayang,<br/>sama nikmat gembira,<br/>bangkit rasa kasih,<br/>nyanyi bagi Tuhan,<br/>nyanyikan lagu baru.<br/>Dapat damai dari-Nya,<br/>kar''na-Nya kita bebas;<br/>Dia Juruselamat,<br/>juga hayat kita,<br/>d''ngan kita kekal esa!<br/>',NULL,64776,1);
INSERT INTO stanza VALUES('I1315','1','Tiap hari cinta Tuhan,<br/>meskipun ada topan.<br/>Meski lemah minatku,<br/>ku tetap cinta Yesus!<br/>',NULL,64777,1);
INSERT INTO stanza VALUES('I1315','chorus','Wa-lau waktu berlalu,<br/>meski hari berganti.<br/>Bi-ar banyak perkara,<br/>ku tetap cinta Yesus!<br/>',NULL,64778,2);
INSERT INTO stanza VALUES('I1315','2','Roh-Nya menyorotiku,<br/>masuk dalam hatiku.<br/>Waktu Di-a pimpinku,<br/>ku tetap cinta Yesus!<br/>',NULL,64779,3);
INSERT INTO stanza VALUES('I1315','3','Nyanyi di sa-at cerah,<br/>do-a di jalan liku.<br/>Seru sa-at bahaya,<br/>ku tetap cinta Yesus!<br/>',NULL,64780,4);
INSERT INTO stanza VALUES('I1315','4','Cinta Dia hingga ajal,<br/>hingga lenyap bu-a-na.<br/>Hingga Dia datang pula,<br/>ku tetap cinta Yesus.<br/>',NULL,64781,5);
INSERT INTO stanza VALUES('I1316','1','Tuhan, Di-kau tersayang,<br/>lain sasaranku tia-da.<br/>Kasih-Mu me-mu-as-kan,<br/>dalamnya ku ba-ha-gia.<br/>Diri-Mu yang tersayang,<br/>daripada segala.<br/>Di-kau tia-da sa-ing-an,<br/>ku cinta, sedap, lega.<br/>',NULL,64782,1);
INSERT INTO stanza VALUES('I1316','chorus','Banyak sudah pernah ku nikmat,<br/>kini se-mua rela ku bu-ang.<br/>Tia-da la-in aku dambakan,<br/>yang ter-ba-ik ku sembahkan.<br/>',NULL,64783,2);
INSERT INTO stanza VALUES('I1316','2','Tanpa Kau, Sang Rea-litas,<br/>apa yang menarikku?<br/>Polos, murni, ku pinta,<br/>Kau penuhi diriku. Tuhan,<br/>Dikau tersayang,<br/>pada-Mu s''mua cintaku.<br/>Kasih-Mu me-mu-as-kan,<br/>dalamnya sentosaku.<br/>',NULL,64784,3);
INSERT INTO stanza VALUES('I1317','chorus','Sam-pai ku masuk<br/>ru-ang maha-kudus-Nya.<br/>Baru nampak akhir m''reka.<br/>Sam-pai ku masuk suang<br/>maha-kudus Allah.<br/>Baru nampak akhir m''reka.<br/>',NULL,64785,1);
INSERT INTO stanza VALUES('I1317','1','Yang jahat,  yang sombong,<br/>nikmati da-mai.<br/>Kakiku hampir tergelincir.<br/>Tak habis ku pikir,<br/>sulit ku t''rima!<br/>(Diteruskan dengan koor yang di atas)<br/>',NULL,64786,2);
INSERT INTO stanza VALUES('I1317','2','Kau taruh mereka<br/>di jalan licin.<br/>Mereka jatuh dan binasa.<br/>Yang m''reka megahkan<br/>sekejap hilang.<br/>',NULL,64787,3);
INSERT INTO stanza VALUES('I1317','chorus','Hatiku pahit dan paruku tertusuk.<br/>Aku jadi bodoh, dungu.<br/>Hatiku lelah dan paruku tertusuk.<br/>Aku jadi bodoh, dungu.<br/>',NULL,64788,4);
INSERT INTO stanza VALUES('I1317','3','Se-la-in Kau di<br/>surga ada sia-pa?<br/>Di bumi tia-da yang ku damba.<br/>Engkaulah t''nagaku,<br/>ba-gian yang kekal!<br/>',NULL,64789,5);
INSERT INTO stanza VALUES('I1317','chorus','Kau papah tanganku,<br/>ajaran-Mu ''mimpin.<br/>Kelak jemputku ke mu-lia.<br/>Kau papah tanganku,<br/>ajaran-Mu ''mimpin.<br/>Kelak jemputku ke mu-lia.<br/>',NULL,64790,6);
INSERT INTO stanza VALUES('I1318','1','Kali pertama jumpa-Mu,<br/>hatiku girang sungguh.<br/>Haleluya, girang lu-ap,<br/>Tuhan Yesus penuhiku.<br/>Kasih semula, yang paling mesra,<br/>Yesus, Kaulah kasihku.<br/>Lam-pau s''gala, kasih Allah,<br/>''nimpa diriku.<br/>Cinta kasih, kasih sejati,<br/>Yesus, Kaulah kasihku.<br/>',NULL,64791,1);
INSERT INTO stanza VALUES('I1319','1','Kau, Kau, s''lalu di hatiku,<br/>mimpi, sekeliling.<br/>Kau, Kau, manislah kasih-Mu,<br/>lebih ba-ik dari s''mua.<br/>Yesus, Yesus,<br/>lebih ba-ik dari s''mua. Yesus,<br/>Yesus, lebih ba-ik dari s''mua.<br/>',NULL,64792,1);
INSERT INTO stanza VALUES('I1319','2','Kasih, lu-as tak bertepi,<br/>manis bagai madu.<br/>''Ngalir basahi hatiku,<br/>nikmat segar kasih-Mu.<br/>Yesus, Yesus,<br/>nikmat segar kasih-Mu.<br/>Yesus, Yesus,<br/>nikmat segar kasih-Mu<br/>',NULL,64793,2);
INSERT INTO stanza VALUES('I1320','1','Demilah tarikan-Mu,<br/>baru akrab ku ikut.<br/>Almuhitlah diri-Mu,<br/>tak habis ku menempuh.<br/>Elok p''ri bunga tabo,<br/>tengah padang terwujud,<br/>pula sepertilah mur,<br/>tersimpan di dadaku.<br/>Dengarlah bisikanku,<br/>tuan la-in ku tak ma-u.<br/>limpah-Mu ku nikmat t''rus,<br/>hayat-Mu dewasaku.<br/>',NULL,64794,1);
INSERT INTO stanza VALUES('I1321','1','Mungkinkah ku tinggal dan lupakan Tuhan.<br/>Sa-at kasih-Nya bara di dalam?<br/>Se-mu-a ''kan lalu, ke-cu-a-li kasih.<br/>Se-lain Tuhan, sia-pa ku sandar-i?<br/>',NULL,64795,1);
INSERT INTO stanza VALUES('I1321','2','Mungkinkah ku tinggal dan lupakan Tuhan?<br/>Sa-at kasih-Nya ''ngalir di dalam?<br/>Meresapi aku, hingga aku bangkit.<br/>Se-lain Tuhan, sia-pa ku sandari?<br/>',NULL,64796,2);
INSERT INTO stanza VALUES('I1322','1','D''ngan tulus ku buka hatiku,<br/>ya Yesus, masuklah.<br/>D''ngan tulus ku buka hatiku,<br/>ya Yesus, masuklah.<br/>',NULL,64797,1);
INSERT INTO stanza VALUES('I1322','2','D''ngan tulus ku cinta pada-Mu,<br/>tinggallah dalamku.<br/>D''ngan tulus ku cinta pada-Mu,<br/>tinggallah dalamku.<br/>',NULL,64798,2);
INSERT INTO stanza VALUES('I1322','3','Tuhan, Kau Persona yang hidup,<br/>hidup dalamku.<br/>Tuhan, Kau Persona yang hidup,<br/>hidup dalamku<br/>',NULL,64799,3);
INSERT INTO stanza VALUES('I1322','4','Dalam roh ku nikmat diri-Mu,<br/>Dikaulah hayatku.<br/>Dalam roh ku nikmat diri-Mu,<br/>Dikaulah hayatku.<br/>',NULL,64800,4);
INSERT INTO stanza VALUES('I1322','5','Tuhan, Kaulah sabat sejati,<br/>p''nuhi anteroku.<br/>Tuhan, Kaulah sabat sejati,<br/>p''nuhi anteroku.<br/>',NULL,64801,5);
INSERT INTO stanza VALUES('I1323','1','Paling, ku pada-Mu,<br/>diriku sungguh hampa sia-sia.<br/>Hati yang berk''lana,<br/>hanya puas oleh kasih-Mu.<br/>',NULL,64802,1);
INSERT INTO stanza VALUES('I1323','chorus','Ya, Yesus!<br/>Ku berseru,<br/>Engkaulah keper-luan-ku.<br/>',NULL,64803,2);
INSERT INTO stanza VALUES('I1323','2','Kur-nia Cuma-Cuma, yang berseru,<br/>''ngecap manis-Nya.<br/>Pemurah sikap-Nya,<br/>hingga kekal tak berubah.<br/>',NULL,64804,3);
INSERT INTO stanza VALUES('I1323','3','Kasih, kasih Kristus,<br/>p''ri sungai yang mengalir deras.<br/>Kasih penuhi ku,<br/>atas diriku p''nuh lu-ap.<br/>',NULL,64805,4);
INSERT INTO stanza VALUES('I1324','1','Ti-ap Kau buka isi hati,<br/>seg''ra menggema hatiku.<br/>Tangan-Mu pegangku,<br/>ku pun curahkan isi hatiku.<br/>Mana mungkin terkata,<br/>mana mungkin terkata.<br/>',NULL,64806,1);
INSERT INTO stanza VALUES('I1324','2','Tapi ku tahu sua-ra hati,<br/>Kau juga senang mendengar.<br/>Cinta dan kesahku,<br/>se-mua di Roh-Mu, guncang hati-Mu.<br/>Tak ''kan terguncang habis,<br/>tak ''kan terguncang habis.<br/>',NULL,64807,2);
INSERT INTO stanza VALUES('I1324','3','Moga kasihku kepada-Mu,<br/>lewati peng-u-ji-an-Mu.<br/>Seluruh diriku, tercurah ''tuk-Mu,<br/>kecap kasih-Mu.<br/>Mengecap hingga akhir,<br/>mengecap hingga akhir.<br/>',NULL,64808,3);
INSERT INTO stanza VALUES('I1325','1','Dariku teralun musik,<br/>kasih Di-a yang mati bagiku.<br/>Mungkinkah ku lupakan-Mu,<br/>sa-at ku terbenam di dalam-Mu.<br/>Nikmat berlimpah, hayat pun nyata,<br/>ri-ang melu-ap, dapatkan hatiku!<br/>Dapatkan genap diriku.<br/>O, Tuhanku, ku bers''rah pada-Mu.<br/>',NULL,64809,1);
INSERT INTO stanza VALUES('I1325','2','Semenjak ku berjumpa-Mu,<br/>ku tak dapat tak cinta pada-Mu.<br/>Dahulu, ku hampa, cemas,<br/>tia-da kasih jadi sandaranku.<br/>Su-a-tu hari ku buka hati,<br/>kasih-Mu ''ngalir,  penuhi hatiku!<br/>Ku tahu, Kau-ku bersatu,<br/>hingga aku sembahkan diriku.<br/>O, Tuhanku, ku bers''rah pada-Mu!<br/>',NULL,64810,2);
INSERT INTO stanza VALUES('I1326','1','Kasih-Mu-lah jumpa-i aku,<br/>sa-at aku berdosa, jatuh.<br/>Kasih-Mu-lah menarik aku,<br/>hingga aku dapat hayat-Mu.<br/>A-ja-ib, kasih-Mu-lah<br/>per-ba-ru-i s''luruh hidupku.<br/>Kasih-Mu-lah mengubah hati,<br/>sa-at aku dingin t''radap-Mu.<br/>Kasih-Mu-lah b''ri hati baru,<br/>aku dan Kau lekat tak putus.<br/>',NULL,64811,1);
INSERT INTO stanza VALUES('I1326','2','Kasih-Mu-lah s''lalu menunjang,<br/>agar kami maju tak henti.<br/>Kasih-Mu-lah s''lalu menyuplai,<br/>agar kami tinggalkan mimpi.<br/>A-ja-ib, kasih-Mu-lah jadi<br/>t''naga untuk berjalan.<br/>Kasih-Mu-lah mem-buat diri-Mu<br/>menjadi Roh tinggal di rohku.<br/>Kasih-Mu-lah, gerak dalamku,<br/>hingga aku damba murad-Mu.<br/>',NULL,64812,2);
INSERT INTO stanza VALUES('I1326','3','Kasih-Mulah kerja dalamku,<br/>menggarapku hingga terbentuk.<br/>Kasih-Mulah ukur diriku,<br/>agar aku ''ngalirkan hidup.<br/>A-ja-ib, kasih-Mulah s''lalu<br/>garap dalam hatiku.<br/>Aku tinggal di dalam g''reja?<br/>Tidak la-in kar''na kasih-Mu!<br/>Aku nikmat di dalam rumah?<br/>Hanya kar''na tangan kasih-Mu!<br/>',NULL,64813,3);
INSERT INTO stanza VALUES('I1326','4','Kasih-Mulah yang mengubahku,<br/>wadah tanah pamer mu-lia-Mu.<br/>Kasih-Mulah b''riku harapan,<br/>seg''ra t''rangkat s''rupa diri-Mu.<br/>A-ja-ib, kasih-Mulah yang ubahku,<br/>desak datang-Mu.<br/>Tuhan, aku sungguh tak tahu,<br/>pun tak mampu siar-kan kasih-Mu.<br/>Curahilah dengan kasih-Mu,<br/>agar aku hilang dalam-Mu.<br/>',NULL,64814,4);
INSERT INTO stanza VALUES('I1327','1','Tia-da yang manis,<br/>se-lain kasih-Mu.<br/>Yang lebih harum,<br/>p''ri nama-Mu.<br/>Tia-da yang sejuk,<br/>segar p''ri embun.<br/>Harum semerbaklah<br/>diri-Mu.<br/>',NULL,64815,1);
INSERT INTO stanza VALUES('I1327','2','K''lana di bumi,<br/>sepi sendiri.<br/>Mulut p''nuh kur-nia,<br/>hati kasih.<br/>Kasih teralir,<br/>sembuhkan luka.<br/>Tapi hati-Mu,<br/>sia-pa paham?<br/>',NULL,64816,2);
INSERT INTO stanza VALUES('I1327','3','Wajah-Mu tegar,<br/>langkah tak gentar.<br/>''Salem Kau tuju,<br/>hidupkan Hu.<br/>Menjelang ajal,<br/>kelam pun tiba.<br/>Allah pun insan,<br/>tinggalkan Dia.<br/>',NULL,64817,3);
INSERT INTO stanza VALUES('I1327','4','Dalam gelap-Mu,<br/>s''mua-nya ti-a-da.<br/>Dalam kubur-Mu,<br/>s''mua berlalu.<br/>Kau yang teragung,<br/>mengapa lenyap?<br/>Kau yang terkasih,<br/>t''lah dikubur.<br/>',NULL,64818,4);
INSERT INTO stanza VALUES('I1327','5','Harapan pupus,<br/>dambaku sirna.<br/>Terang ter-s''lubung,<br/>bumi gelap.<br/>Tuhan, kasihku,<br/>m''ngapa Kau hilang.<br/>Tuhan Sang Hayat,<br/>m''ngapa mati?<br/>',NULL,64819,5);
INSERT INTO stanza VALUES('I1327','6','Kau t''lah kembali,<br/>dalam bangkit-Mu.<br/>Harum pun mu-lia,<br/>oh, Kasihku.<br/>Kasih alirkan hayat<br/>bangkit-Mu.<br/>Kuasa t''rangkat-Mu,<br/>rea-litasku.<br/>',NULL,64820,6);
INSERT INTO stanza VALUES('I1327','7','Nampak wajah-Mu,<br/>yang la-in pudar.<br/>Kecap manis-Mu,<br/>yang lain sirna.<br/>Tercelup kasih,<br/>nan amat mesra.<br/>Hati diriku,<br/>''tuk Mu s''mata.<br/>',NULL,64821,7);
INSERT INTO stanza VALUES('I1328','1','Tuhan, jaga hatiku tulus.<br/>Tak pernah mundur, s''lalu pandang-Mu.<br/>Hati polos, murni t''radap diri-mu.<br/>Cinta pada-Mu, memustikakan-Mu.<br/>',NULL,64822,1);
INSERT INTO stanza VALUES('I1328','chorus','Kasih-Mu desakku, s''rahkan s''galaku.<br/>Ku tak berdaya, Kau pikat hatiku.<br/>O, sungguh mu-li-a, Kau t''rima diriku.<br/>Ku cinta-Mu, Tuhanku, ku cinta pada-Mu.<br/>',NULL,64823,2);
INSERT INTO stanza VALUES('I1328','2','Tuhan, jaga kasihku ''bara.<br/>Tak pernah padam, s''lalu menyala.<br/>Kasih yang membara gai-rah t''radap-Mu.<br/>Kasih yang segar, p''ri awal jumpa-Mu.<br/>',NULL,64824,3);
INSERT INTO stanza VALUES('I1328','3','Tuhan dapatkanlah hidupku.<br/>Andai laksa-an, se-mua bagi-Mu.<br/>Tia-da yang tersisa, se-mua untuk-Mu.<br/>Masa depanku, ya Tuhan, milik-Mu.<br/>',NULL,64825,4);
INSERT INTO stanza VALUES('I1401','1','Tuhan hayat tiup-i aku,<br/>bukakan sumber hayat-Mu.<br/>Pada batin, dorong aku,<br/>sinar hayat, so-rot-i-ku.<br/>',NULL,64826,1);
INSERT INTO stanza VALUES('I1401','2','Kau dalam ku a-jaib sungguh.<br/>Tak ke mana mencari-Mu.<br/>Balik di roh, berjumpa Kau,<br/>Roh sentuh Roh, satu padu.<br/>',NULL,64827,2);
INSERT INTO stanza VALUES('I1401','3','Kau Pembelaku di surga.<br/>Urapan roh ba-ti-ni-ah.<br/>Yang Kau bu-at depan Allah.<br/>Dalam rohku terjamah s''mua.<br/>',NULL,64828,3);
INSERT INTO stanza VALUES('I1401','4','Hatiku kurang se-ti-a.<br/>Ada dorong tak kuat ta-at.<br/>Mohon rahmat, tiup, dan tunjang.<br/>Agar ku berdaya guna.<br/>',NULL,64829,4);
INSERT INTO stanza VALUES('I1401','5','Sa-at rohku lembam, m''rosot.<br/>Sulit si-ar-kan kur-nia-Mu.<br/>Dari batin mohonlah tiup.<br/>Anteroku penuhlah kau.<br/>',NULL,64830,5);
INSERT INTO stanza VALUES('I1402','1','Tariklah, tarik kami kepada Tuhan.<br/>Hari depan lebih ba-ik ku tak damba.<br/>Mumpung sa-at ini hidupku masihlah.<br/>Meng-ab-di pada Kristus dan g''reja!<br/>',NULL,64831,1);
INSERT INTO stanza VALUES('I1402','2','O, hidup gereja menariklah amat.<br/>Hari ke hari Allah curahkan berkat.<br/>Bunga mekar, burung kicau, penuh hayat.<br/>Kita nikmati Dia, tampilkan Dia.<br/>',NULL,64832,2);
INSERT INTO stanza VALUES('I1402','3','Mempelai Laki hampir menjelang kini.<br/>Di-a datang dengan membawa pahala.<br/>Hari itu di angkasa Di-a datang.<br/>Sekejap mata ku terangkatlah!<br/>',NULL,64833,3);
INSERT INTO stanza VALUES('I1403','1','Ya, Yesus! Ya, Yesus!<br/>Ku damba jamah Kau!<br/>Tumbuhlah dalamku,<br/>lebih banyak terus.<br/>Semoga hayat-Mu bertumbuh,<br/>"bunga mu-lia" mekar!<br/>Supaya Kau Tuhan,<br/>atasku tertampak.<br/>',NULL,64834,1);
INSERT INTO stanza VALUES('I1404','1','Du-nia jahat, penuh dusta,<br/>tapi ku sangka kawan.<br/>Apa ju-a belum dapat,<br/>hatiku dipikatnya.<br/>Padahal Tuhan menunggu,<br/>mencurahkan kasih-Nya!<br/>Tuhan kini ku bertobat,<br/>agar Kau tak kecewa.<br/>',NULL,64835,1);
INSERT INTO stanza VALUES('I1404','2','Ya, Tuhanku, t''rima kasih,<br/>Kau jagaku tiap hari.<br/>Kur-ni-a-Mu sungguh lebih,<br/>hingga ku girang hati.<br/>Kini ku mau cinta Tuhan,<br/>seg''nap hati untuk-Mu!<br/>Dengan du-nia, sudah putus,<br/>haleluya, puji Hu!<br/>',NULL,64836,2);
INSERT INTO stanza VALUES('I1405','1','Hati berpaling kepada Tuhan.<br/>Selubung seg''ra tersingkap.<br/>Berpaling ''tiasa kepada Tuhan.<br/>Selubung seg''ra tersingkap.<br/>Kini Tuhan ia-lah Roh itu,<br/>di mana Roh Tuhan,<br/>di sana ada kemerdeka-an.<br/>Hati berpaling kepada Tuhan.<br/>Selubung seg''ra tersingkap.<br/>',NULL,64837,1);
INSERT INTO stanza VALUES('I1406','1','Demi salib Tuhan,<br/>biar-lah aku masuk kian dalam.<br/>Ma-ut gandeng hayat,<br/>agar arus bertambah deras.<br/>Tuhan, garap-i-lah<br/>aku lebih dalam,<br/>penuh-i p''losokku,<br/>hingga ter-ba-ru-i s''mua.<br/>',NULL,64838,1);
INSERT INTO stanza VALUES('I1406','2','Dalam hayat Tuhan,<br/>aku ingin lebih meningkat!<br/>Oleh hayat Tuhan,<br/>aku makin ''nuju ke atas.<br/>Tuhan, perubahan<br/>sedang ku butuhkan.<br/>Arus tambah limpah,<br/>hayat-Mulah ku kenal.<br/>',NULL,64839,2);
INSERT INTO stanza VALUES('I1406','3','Makin besar, Tuhan di batinku,<br/>hari ke hari.<br/>Mengaliri seluruh hidupku -<br/>Dia kehendaki.<br/>Tuhan, bertambahlah<br/>dalamku tak henti.<br/>Bukan pe-nge-ta''u-an,<br/>agar ku akil balig.<br/>',NULL,64840,3);
INSERT INTO stanza VALUES('I1406','4','Kristus, Kristus, hidupku tiap hari,<br/>rea-li-tas megah!<br/>Se-mu-a hal, besar mau-pun kecil,<br/>pada-Nya m''lulu.<br/>Hidup dan alirkan<br/>Kristus ''nan-ti-a-sa.<br/>Serulah nama-Nya,<br/>serahkan Dia seluruh.<br/>',NULL,64841,4);
INSERT INTO stanza VALUES('I1406','5','Kristus, Kristus, jadi pribadiku,<br/>s''mayam di kalbu.<br/>Selera, sikap,<br/>dan tindakanku alangkah a-jaib!<br/>Tuhan pribadiku,<br/>menghuni kalbuku.<br/>Hayat dan s''galaku,<br/>lekat padu abadi!<br/>',NULL,64842,5);
INSERT INTO stanza VALUES('I1406','6','G''reja, g''reja,<br/>dalam g''reja lokal ada arus Roh.<br/>Makin dalam, makin tinggi,<br/>Kristus dapatkan aku.<br/>G''reja per-nya-ta-an<br/>s''gala aspek Kristus.<br/>Ku mau lepas diri,<br/>untuk bangun Tubuh-Mu.<br/>',NULL,64843,6);
INSERT INTO stanza VALUES('I1406','7','Bangun, bangun,<br/>membangun gereja denganlah Kristus.<br/>Tanpa mengalami Kristus<br/>ti-a-da jalan la-in.<br/>Tuhan, aku mohon,<br/>Kau bangunkan aku.<br/>Hayat ki-an tambah,<br/>bagilah Salem Baru.<br/>',NULL,64844,7);
INSERT INTO stanza VALUES('I1406','8','Seg''ra datang, Kristus seg''ra datang,<br/>sambut jodoh-Nya.<br/>Dalam g''reja,<br/>kini kita tunggu tubuh tertebus.<br/>Tuhan, kembalilah,<br/>hatiku dambakan.<br/>Ku terus memuji,<br/>lekas datang, ya, Yesus!<br/>',NULL,64845,8);
INSERT INTO stanza VALUES('I1407','1','Kebelakangkanlah<br/>perihal kemarin.<br/>Lari kencang menuju<br/>ke sasaran!<br/>Kita dalam arus,<br/>ikuti Tuhan.<br/>Bagi pemuli''an-Nya,<br/>jawab panggil-Nya.<br/>',NULL,64846,1);
INSERT INTO stanza VALUES('I1408','1','Galilah, galilah, galilah,<br/>gali s''mua batu dalam hatiku!<br/>Galilah, galilah, galilah,<br/>gali s''mua batu dalam hatiku!<br/>S''mua dosa, lepaslah,<br/>biar hayat ''ngalir, haleluya!<br/>Galilah, galilah, galilah,<br/>gali s''mua batu dalam hatiku!<br/>',NULL,64847,1);
INSERT INTO stanza VALUES('I1408','2','Galilah, galilah, galilah,<br/>gali khayalan sia-sia benakku!<br/>Galilah, galilah, galilah,<br/>gali khayalan sia-sia benakku!<br/>S''mua mimpi, tersadar,<br/>biar hayat ''ngalir, haleluya!<br/>Galilah, galilah, galilah,<br/>gali khayalan sia-sia benakku!<br/>',NULL,64848,2);
INSERT INTO stanza VALUES('I1408','3','Galilah, galilah, galilah,<br/>gali emosi yang meresahkan!<br/>Galilah, galilah, galilah,<br/>gali emosi yang meresahkan!<br/>Gemarku, ku tolak,<br/>biar hayat ''ngalir, haleluya!<br/>Galilah, galilah, galilah,<br/>gali emosi yang meresahkan!<br/>',NULL,64849,3);
INSERT INTO stanza VALUES('I1408','4','Galilah, galilah, galilah,<br/>hali s''mua tegar tengkuk tekadku!<br/>Galilah, galilah, galilah,<br/>hali s''mua tegar tengkuk tekadku!<br/>Mau diri, terhenti,<br/>biar hayat ''ngalir, haleluya!<br/>Galilah, galilah, galilah,<br/>hali s''mua tegar tengkuk tekadku!<br/>',NULL,64850,4);
INSERT INTO stanza VALUES('I1408','5','Galilah, galilah, galilah,<br/>gali s''mua tuntutan pribadiku!<br/>Galilah, galilah, galilah,<br/>gali s''mua tuntutan pribadiku!<br/>Harapku sirnalah,<br/>biar hayat ''ngalir, haleluya!<br/>Galilah, galilah, galilah,<br/>gali s''mua tuntutan pribadiku!<br/>',NULL,64851,5);
INSERT INTO stanza VALUES('I1408','6','Mengalir! Puji Hu! Mengalir!<br/>Hayat mengalir dari hatiku!<br/>Mengalir! Puji Hu! Mengalir!<br/>Hayat mengalir dari hatiku!<br/>Hatiku bebaslah!<br/>Rohku memuji, "Haleluya!"<br/>Mengalir! Puji Hu! Mengalir!<br/>Hayat mengalir dari hatiku!<br/>("memuji" dalam bait 6 dapat<br/>diganti dengan "berdoa",<br/>"menyanyi", "bertumbuh")<br/>',NULL,64852,6);
INSERT INTO stanza VALUES('I1409','1','Hayat itulah paling dalam,<br/>di dalam roh ku alami, kuduslah!<br/>Bukan ''palang a-ja-ib,<br/>penuh mu-lia Allah, megah,<br/>agung, ti-a-da-lah terduga.<br/>Hayat ini Allah Sang Kekal,<br/>ditampilkan Yesus, Anak Manu-sia.<br/>Kini Roh pemb''ri hayat di rohku membesar,<br/>menjadi gereja kesayangan-Nya.<br/>',NULL,64853,1);
INSERT INTO stanza VALUES('I1409','chorus','Mengalir! Tuhan, marilah!<br/>Untuk ini makna hidup kita,<br/>dan masuk-Mu di batin kita!<br/>Palingkan, ya Tuhan!<br/>Demi hayat Di-kau kan<br/>beroleh gereja, rumah idaman.<br/>',NULL,64854,2);
INSERT INTO stanza VALUES('I1409','2','Di g''reja kita pada paham,<br/>di dalam kita hayat limpah ru-ah.<br/>Sejahtera di lubuk, bukan ronta lu-ar,<br/>tergenang menjadi sungai me-lu-ap.<br/>Seluruh kaum saleh serempak, ''nuntut,<br/>nikmat, pegang hayat nan kaya.<br/>Barang se-la-in Tuhan, bu-ang ke belakang,<br/>hingga gereja penuh hayat Allah.<br/>',NULL,64855,3);
INSERT INTO stanza VALUES('I1409','3','Tuhan, mohon palingkan hamba,<br/>hidupku berdasarkan Kau belaka.<br/>Lepas konsep yang lama, mutlak ikut hayat,<br/>b''ri kur-nia agar berpaling kian mantap.<br/>Dalam roh nikmati sentosa,<br/>insan batin ki-an baru tiap sa-at!<br/>Di lubukku semayam, Tuhanku, marilah,<br/>''moga hadir-Mu mengitari hamba.<br/>',NULL,64856,4);
INSERT INTO stanza VALUES('I1410','1','Dari lubuk rohku,<br/>air hayat memancar,<br/>itu aliran Sang Trinitas.<br/>Sang Bapa sumbernya,<br/>Sang Kristus sungainya,<br/>Sang Roh arus pemberi hayat.<br/>',NULL,64857,1);
INSERT INTO stanza VALUES('I1410','chorus','Ku harga-i aliran hayat,<br/>hayat jiwa tak ku sisakan.<br/>Perdalam aliran, ya, Tuhan!<br/>Pada datang-Mu ku dewasa.<br/>',NULL,64858,2);
INSERT INTO stanza VALUES('I1410','2','Rumput subur segar,<br/>a-ir amat tenang.<br/>Nikmat Tuhan, ikut kawanan.<br/>Tanpa ronta-ronta,<br/>berjerih percuma.<br/>Aliran anteronya berkat!<br/>',NULL,64859,3);
INSERT INTO stanza VALUES('I1410','3','Tempat maha kudus,<br/>masuk demi darah.<br/>Lekat sumber, hidup depan-Nya.<br/>Halelu, tutur-Nya,<br/>jangan men-jauh-i-Nya.<br/>Sekutu t''rus tinggal dalam-Nya.<br/>',NULL,64860,4);
INSERT INTO stanza VALUES('I1411','1','Kita bisa menang atas musuh,<br/>menang atas musuh, menang atas musuh.<br/>Kita bisa menang atas musuh,<br/>gunakan darah.<br/>Gunakan darah, gunakan darah.<br/>Kita bisa menang atas musuh,<br/>gunakan darah.<br/>',NULL,64861,1);
INSERT INTO stanza VALUES('I1411','2','Menang bukan karena rohani,<br/>karena rohani, karena rohani.<br/>Menang bukan karena rohani,<br/>me-lain-kan darah.<br/>Me-lain-kan darah, me-lain-kan darah.<br/>Menang bukan karena rohani,<br/>me-lain-kan darah.<br/>',NULL,64862,2);
INSERT INTO stanza VALUES('I1411','3','Kita jadi orang Kristen normal,<br/>orang Kristen normal,<br/>orang Kristen normal.<br/>Kita jadi orang Kristen normal,<br/>bersandar darah.<br/>Bersandar darah, bersandar darah.<br/>Kita jadi orang Kristen normal,<br/>bersandar darah.<br/>',NULL,64863,3);
INSERT INTO stanza VALUES('I1411','4','Demi darah pulih per-se-ku-tuan,<br/>pulih per-se-ku-tuan,<br/>pulih per-se-ku-tuan.<br/>Demi darah pulih per-se-ku-tuan,<br/>jangan berlambat.<br/>Jangan berlambat, jangan berlambat.<br/>Demi darah pulih per-se-ku-tuan,<br/>jangan berlambat.<br/>',NULL,64864,4);
INSERT INTO stanza VALUES('I1412','1','Makan firman, kau takkan layu,<br/>senang amin, tanpa paksa-an!<br/>Cebur dalam firman,<br/>sam-pai m''rasa segar.<br/>Waktu kita sangat berharga!<br/>Sering do-a baca tak undur,<br/>gemar sidang bukan pak-sa-an!<br/>Kita s''mua terbakar,<br/>hingga s''mua membara.<br/>Tak peduli sua-sa-na apa!<br/>Ceburlah!<br/>',NULL,64865,1);
INSERT INTO stanza VALUES('I1413','1','Amin, Tuhan Yesus!<br/>Amin. Ya, amin tak sudah.<br/>Amin atas firman tertulis,<br/>dalam Alkitab.<br/>Amin atas firman rhema,<br/>Kau ta''u ke-per-luan-ku.<br/>Ku s''lalu berkata,"Amin",<br/>s''mua ba-ik bagiku.<br/>',NULL,64866,1);
INSERT INTO stanza VALUES('I1414','1','Mau lepas dari belenggu du-nia?<br/>Aminlah firman-Nya!<br/>Dan menempuh rea-litas rohani?<br/>Aminlah firman-Nya!<br/>Amin firman Allah!<br/>Amin firman Allah!<br/>T''rima firman-Nya, jangan ragukan!<br/>Aminlah firman-Nya!<br/>',NULL,64867,1);
INSERT INTO stanza VALUES('I1414','2','Mau lepas dari dosa dan diri?<br/>Aminlah firman-Nya!<br/>Serta pikiran di-per-ba-ru-i?<br/>Aminlah firman-Nya!<br/>Amin firman Allah!<br/>Amin firman Allah!<br/>Firman-Nya hidup, memberi hayat,<br/>aminlah firman-Nya!<br/>',NULL,64868,2);
INSERT INTO stanza VALUES('I1414','3','Tanah nan permai, jadi ba-gian-ku,<br/>aminlah firman-Nya!<br/>Ta-at firman-Nya, janganlah bantut,<br/>aminlah firman-Nya!<br/>Amin firman Allah!<br/>Amin firman Allah!<br/>Firman-Nya tamyiz, p''ri pedang ampuh,<br/>aminlah firman-Nya!<br/>',NULL,64869,3);
INSERT INTO stanza VALUES('I1414','4','Waktunya hampir, Yesus ''kan tiba,<br/>aminlah firman-Nya!<br/>Berani kau jawab sudah si-ap?<br/>Aminlah firman-Nya!<br/>Amin firman Allah!<br/>Amin firman Allah!<br/>Janganlah tegar, sandarlah firman,<br/>aminlah firman-Nya!<br/>',NULL,64870,4);
INSERT INTO stanza VALUES('I1415','1','Dengan b''rani ke takhta kur-nia,<br/>t''rima rahmat, kur-nia, bantu-an.<br/>Tidak lagi pu-tar-i salib,<br/>kar''na Tuhan, tak di sana.<br/>Dia t''lah hancurkan b''lenggu ma-ut,<br/>bangkit, t''rangkat, mu-li-a!<br/>Kini dari takhta kur-nia,<br/>suplai-ku dengan hayat.<br/>',NULL,64871,1);
INSERT INTO stanza VALUES('I1415','2','Meski takhta kur-nia di surga,<br/>Dia-lah tangga, tembus ke rohku.<br/>Jangan lagi k''lana di jiwa,<br/>ti-ap sa-at balik ke roh.<br/>Yesus, Imam Besar agungku,<br/>simpati ''tas lemahku!<br/>Sandar Di-a, hampir Allah,<br/>Dia pasti s''lamatkanku.<br/>',NULL,64872,2);
INSERT INTO stanza VALUES('I1415','3','Puji Yesus, Imam Besarku,<br/>s''turut aturan Melkisedek.<br/>Kini perang bagilah Allah,<br/>sya-fa-at-Nya, suplai t''naga.<br/>Set''lah menang atas s''mua musuh,<br/>Dia b''ri roti dan anggur!<br/>Sungguh bebas le-lu-a-sa,<br/>mengalami kur-nia-Nya.<br/>',NULL,64873,3);
INSERT INTO stanza VALUES('I1416','1','Kitar-i takhta-Nya,<br/>ini p''rintah surga.<br/>Di ruang mahakudus,<br/>nikmat kur-nia limpah.<br/>Di dalam roh kumpul sama,<br/>nikmat Kristus hingga kekal.<br/>Nikmat Kristus hingga kekal.<br/>',NULL,64874,1);
INSERT INTO stanza VALUES('I1416','2','Di ruang mahakudus,<br/>capai takhta kur-nia.<br/>Lewat pelataran,<br/>juga ru-ang kudus.<br/>Bu-ang du-nia, basmi dosa,<br/>balik tirai, beserta-Nya.<br/>Balik tirai, beserta-Nya.<br/>',NULL,64875,2);
INSERT INTO stanza VALUES('I1416','3','Tebusan t''lah genap,<br/>Harun sudah lewat.<br/>Se-suai Melkisedek,<br/>Kristus, Imam Besar.<br/>Janji, ministri yang indah,<br/>roti, anggur, suplai tunjang.<br/>Roti, anggur, suplai tunjang.<br/>',NULL,64876,3);
INSERT INTO stanza VALUES('I1416','4','Kristus jauh di surga,<br/>aku di bu-a-na.<br/>Bisa kontak Allah?<br/>Dalam roh jalannya.<br/>Dalam rohku rangkum tiga -<br/>Allah, takhta, mahakudus.<br/>Allah, takhta, mahakudus.<br/>',NULL,64877,4);
INSERT INTO stanza VALUES('I1416','5','Kita yang korporat,<br/>bukan yang terserak.<br/>Asal dalam Tubuh,<br/>tak sebatang kara.<br/>Ti-ap sidang tia-da sekat,<br/>k''liling takhta, puji, sembah.<br/>K''liling takhta, puji, sembah.<br/>',NULL,64878,5);
INSERT INTO stanza VALUES('I1417','1','K''liling derita, ti-a-da per-hen-tian,<br/>hatiku leleh bag'' a-ir.<br/>Tapi di lubuk terdengar su-a-ra:<br/>Sudahkah, kau tahu, Dia Tuhan?<br/>',NULL,64879,1);
INSERT INTO stanza VALUES('I1417','chorus','Tenanglah hatiku.<br/>Dia Tuhan,<br/>Dia Tuhan,<br/>Dia Tuhan!<br/>',NULL,64880,2);
INSERT INTO stanza VALUES('I1417','2','Co-ba-an datang bagai bunga mimpi,<br/>indah, elok, dan menawan.<br/>Senyum menggodaku balik ke du-nia,<br/>di lubuk terdengar: Dia Tuhan!<br/>',NULL,64881,3);
INSERT INTO stanza VALUES('I1417','3','Se-mua t''lah hancur, tak ada yang utuh,<br/>bayangan gelap mencekam.<br/>Tangan menggapai, tak ada pegangan,<br/>di lubuk terdengar: Dia Tuhan!<br/>',NULL,64882,4);
INSERT INTO stanza VALUES('I1417','4','Ambisi hilang bagai angin lewat,<br/>duri yang Dia b''ri menghunjam.<br/>Lembut ku tanya,"Apakah ku ter-buang?"<br/>Dia jawab,"Aku ia-lah Tuhan."<br/>',NULL,64883,5);
INSERT INTO stanza VALUES('I1417','5','Malu dan sedih, ingat Yang Tercinta,<br/>bertahun Dia b''ri kur-ni-a.<br/>Tapi ku degil, tak pancar mu-lia-Nya,<br/>bekas paku, bukti: Dia Tuhan!<br/>',NULL,64884,6);
INSERT INTO stanza VALUES('I1418','1','Aku bunga kecil, menengadah.<br/>Paling pada Allah. T''rima kur-nia.<br/>Tak tahu la-in-nya, hanyalah p''ri.<br/>Bunga bakung bersandar-Nya.<br/>',NULL,64885,1);
INSERT INTO stanza VALUES('I1418','2','Du-nia tia-da satu yang ku rindu.<br/>Dan tia-da apa pun me-muas-kan-ku.<br/>Namun ada satu yang ku mohon.<br/>Sandar-Nya p''ri bunga bakung.<br/>',NULL,64886,2);
INSERT INTO stanza VALUES('I1418','3','Bila sandar Tuhan, ku terhina.<br/>Jalan dengan Tuhan, tak merdeka.<br/>Itu tak mengapa, tak mengapa.<br/>Bunga bakung bersandar-Nya.<br/>',NULL,64887,3);
INSERT INTO stanza VALUES('I1418','4','Walau tahu banyak, gagal saja.<br/>Gumul dan usaha berpeluhan.<br/>Se-mua si-a-si-a, dan akhirnya.<br/>Bunga bakung bersandar-Nya.<br/>',NULL,64888,4);
INSERT INTO stanza VALUES('I1418','5','Seperti akulah, sandar saja.<br/>Aku tahu benar prihatin-Nya.<br/>Mari, ja-uh-i-lah duka rana.<br/>Mau-kah jadi bunga bakung?<br/>',NULL,64889,5);
INSERT INTO stanza VALUES('I1419','1','Jagalah aku, ya, Tuhan,<br/>biar ku jalan d''ngan lurus.<br/>Wahyukan diri-Mu Tuhan,<br/>biar ku capai tem-pu''an-ku.<br/>Hanya oleh pimpinan-Mu,<br/>baru ku maju, tak takut.<br/>Mohon sinar t''rang wajah-Mu,<br/>menyorot-i-ku s''lalu.<br/>',NULL,64890,1);
INSERT INTO stanza VALUES('I1419','2','Tiap langkah perlu Kau bimbing,<br/>k''liling p''nuh semak duri.<br/>Tiap sikap perlu Kau garap,<br/>agar se-suai murad-Mu.<br/>Hanya dengan ser-ta-an-Mu,<br/>baru ku maju, tak undur.<br/>Mohon Tuhan ser-ta-an-Mu,<br/>nyata atasku s''lalu.<br/>',NULL,64891,2);
INSERT INTO stanza VALUES('I1419','3','Sa-at ku cari ''kenan-Mu,<br/>baru ku k''nal diriku.<br/>Sa-at mau ta-at p''rintah-Mu,<br/>nyatalah ku tak mampu.<br/>Hanya demi mu-li-a-Mu,<br/>mem-buat-ku benam dalam-Mu.<br/>Mohon Tuhan d''ngan mu-lia-Mu,<br/>menarikku selalu.<br/>',NULL,64892,3);
INSERT INTO stanza VALUES('I1419','4','Tuhan, b''riku satu tekad,<br/>hanya damba diri-Mu.<br/>Tuhan b''riku satu harap,<br/>tak dukakan hati-Mu.<br/>Ya, Tuhanku, ku bermohon,<br/>erat dekaplah diriku.<br/>Agar s''mua ke-in-dah-an-Mu,<br/>jadi t''naga, damaiku.<br/>',NULL,64893,4);
INSERT INTO stanza VALUES('I1420','1','Kita tempuh jalan depan,<br/>lepas letih, beban berat.<br/>Tak harap, tak harap,<br/>tak harap, s''lain Tuhan.<br/>Ke-mu-lia-an kita ra-ih,<br/>Tuhan kuat-kan, Tuhan tunjang.<br/>Tak harap, tak harap,<br/>tak harap, s''lain Tuhan.<br/>Dia t''lah pimpin ke depan,<br/>menang, menang.<br/>Kini duduk kanan Allah,<br/>bawaku masuk mu-lia.<br/>Tia-da harap,<br/>se-la-in Tuhan Yesus.<br/>Tia-da harap,<br/>se-la-in Tuhan Yesus.<br/>',NULL,64894,1);
INSERT INTO stanza VALUES('I1421','1','Ha-nya sa-tu te-kad-ku:<br/>ber-la-ri ke sa-sar-an,<br/>''tuk da-pat pa-ha-la;<br/>Me-lu-pa-kan yang silam,<br/>menganggap se-mua ru-gi,<br/>ha-nya Di-a mus-ti-ka.<br/>Bu-ang se-mua pri sampah,<br/>me-nun-tut tan-pa le-ngah,<br/>A-gar da-pat ke-nal<br/>Kris-tus yang bang-kit.<br/>Wa-lau d''ri-ta  me-nge-pung,<br/>mem-buat ta-war ha-ti-ku,<br/>ku te-tap per-caya;<br/>Baik hi-dup a-tau ma-ti,<br/>ku da-pat me-nanggungnya,<br/>hing-ga Dia ter-nya-ta-kan.<br/>',NULL,64895,1);
INSERT INTO stanza VALUES('I1422','1','''Nuju sasaran,<br/>menempuh hayat,<br/>menerima pahala.<br/>Lepas beban,<br/>dosa yang merintang-i,<br/>tak ingkar visi surga.<br/>Saksi di sekitar<br/>lihat ku lari,<br/>tak undur pun tak jatuh.<br/>Nuju sasaran,<br/>menempuh hayat,<br/>menerima pahala.<br/>',NULL,64896,1);
INSERT INTO stanza VALUES('I1423','1','Ma-ju kencang! Maju kencang!<br/>Tu-han-lah sa-sar-an,<br/>Pah''-la se-dia, ja-ngan ''nyimpang,<br/>t''rus maju ke de-pan.<br/>',NULL,64897,1);
INSERT INTO stanza VALUES('I1423','chorus','Ke de-pan! Ke de-pan!<br/>Ter-janglah! Ha-le-lu-ya!<br/>Ma-ju ''nyongsong paha-la.<br/>Ter-jang t''rus!<br/>Kris-tus-lah pahala!<br/>',NULL,64898,2);
INSERT INTO stanza VALUES('I1423','2','Maju kencang! Lempar du-nia!<br/>Pandang s''mua p''ri sampah!<br/>Hanya Kristus, pah''la mu-lia,<br/>langkah ku a-rah-kan!<br/>',NULL,64899,3);
INSERT INTO stanza VALUES('I1423','3','Maju kencang! Kenal Kristus,<br/>alami bangkit-Nya;<br/>O, pahala megah agung,<br/>bagilah pemenang!<br/>',NULL,64900,4);
INSERT INTO stanza VALUES('I1423','4','Maju kencang! Itu saja!<br/>Yang sudah, lupakan!<br/>Kristus di depan, majulah!<br/>Tanpa ''noleh b''lakang!<br/>',NULL,64901,5);
INSERT INTO stanza VALUES('I1424','1','Ada jalan di depan, haleluya!<br/>Menempuh terus, tak henti!<br/>Terhadap yang berlari, haleluya!<br/>Pandang saja kepada-Nya.<br/>',NULL,64902,1);
INSERT INTO stanza VALUES('I1424','chorus','Pandang saja pada-Nya!<br/>Tempuh terus, tak henti!<br/>Tidak pandang yang la-in, hanya Yesus.<br/>Pandang saja kepada-Nya!<br/>',NULL,64903,2);
INSERT INTO stanza VALUES('I1424','2','Lepas hal-hal seputar, haleluya!<br/>Terlepas risau dan ronta.<br/>Memandang Tuhan Sabat, haleluya!<br/>Pandang saja kepada-Nya!<br/>',NULL,64904,3);
INSERT INTO stanza VALUES('I1424','3','Lepas hati yang bimbang, haleluya!<br/>Lepas ba-ik atau kurang.<br/>Khusus pandang sasaran, haleluya!<br/>Pandang saja kepada-Nya!<br/>',NULL,64905,4);
INSERT INTO stanza VALUES('I1424','4','Lepas hal-hal di b''lakang, haleluya!<br/>Ba-ik buruk tak hiraukan.<br/>Pegang Tuhan yang hidup, haleluya!<br/>Pandang saja kepada-Nya!<br/>',NULL,64906,5);
INSERT INTO stanza VALUES('I1424','5','Pandang wajah mu-lia-Nya, haleluya!<br/>Dia-lah Alfa dan Omega.<br/>T''rima kur-nia, larilah, haleluya!<br/>Pandang saja kepada-Nya!<br/>',NULL,64907,6);
INSERT INTO stanza VALUES('I1425','1','Ke K''ra-ja-an Surga,<br/>waktunya t''lah dekat,<br/>janganlah bermalas,<br/>hidup bagi Tuhan.<br/>S''lalu pikul salib,<br/>pada jalan sempit,<br/>lekaslah! Rebutlah!<br/>Di sana p''nuh nikmat!<br/>',NULL,64908,1);
INSERT INTO stanza VALUES('I1425','chorus','Ke K''ra-ja-an Surga!<br/>Di sana p''nuh nikmat!<br/>Lekaslah! Rebutlah!<br/>Di sana beserta Tuhan!<br/>',NULL,64909,2);
INSERT INTO stanza VALUES('I1425','2','Ke K''ra-ja-an Surga!<br/>Kalahkan s''mua dosa.<br/>Matikanlah nafsu,<br/>du-nia bu-ang ja-uh.<br/>Go-da-an si jahat,<br/>tolaklah d''ngan tegas.<br/>Lekaslah! Rebutlah!<br/>Di sana p''nuh nikmat.<br/>',NULL,64910,3);
INSERT INTO stanza VALUES('I1425','3','Ke K''ra-ja-an Surga!<br/>Kur-nia-Nya berlimpah.<br/>Masuk tempat kudus,<br/>pandang Dia di takhta.<br/>Terima kur-nia-Nya,<br/>lerailah dahaga.<br/>Lekaslah! Rebutlah!<br/>Di sana p''nuh nikmat!<br/>',NULL,64911,4);
INSERT INTO stanza VALUES('I1425','4','Ke K''ra-ja-an Surga!<br/>Nyanyikan pu-ji-an.<br/>Salib s''lamatkanku,<br/>s''mua musuh t''lah takluk.<br/>Ke K''ra-ja-an Surga!<br/>Marilah bersorak.<br/>Ke sana naik takhta,<br/>serta Tuhan s''lama!<br/>',NULL,64912,5);
INSERT INTO stanza VALUES('I1425','chorus','Ke K''ra-ja-an Surga,<br/>naik takhta, serta-Nya!<br/>Bermahkota mu-lia,<br/>bersenang d''ngan Tuhan s''lama!<br/>',NULL,64913,6);
INSERT INTO stanza VALUES('I1426','1','Hari-hari lewat lintas saja,<br/>percaya tadbir kur-ni-a-Nya.<br/>Tenaga-Mu cukup atas u-jian,<br/>dukaku tanpalah alasan.<br/>Hati-Nya prihatin tanpa batas,<br/>yang ter-ba-ik, Di-a berikan.<br/>Susah, senang, jerih, rahat,<br/>se-mua sudah ditakar-Nya seksama.<br/>',NULL,64914,1);
INSERT INTO stanza VALUES('I1426','2','Hari-hari Tuhan di batinku,<br/>kur-ni-a memeliharaku.<br/>Pikul se-mu-a duka bagiku,<br/>nama-Nya a-jaib beri hidup.<br/>Atas ti-ap hal ku bisa patuh,<br/>Dia bertanggung jawab atasku.<br/>"Tenagamu seperti harimu",<br/>hak ini Dia beri padaku.<br/>',NULL,64915,2);
INSERT INTO stanza VALUES('I1426','3','Ajarku dalam se-tiap perkara,<br/>pada-Mu berserah, bersandar.<br/>Jangan ku hilang hiburan iman,<br/>oleh sabda henti bertimbang.<br/>Dikau pribadiku nan tersayang,<br/>gantiku nempuh hidup mu-lia.<br/>Aku susut, Dikau kian berkembang,<br/>hingga ma-u-Mu terlaksana.<br/>',NULL,64916,3);
INSERT INTO stanza VALUES('I1427','1','Tiap do-a ada jawaban,<br/>asalkan kau beriman.<br/>Kau minta Tuhan dengarkan,<br/>meskipun alam goncang.<br/>',NULL,64917,1);
INSERT INTO stanza VALUES('I1427','chorus','Tiap do-a ada jawaban,<br/>janji-Nya pasti genap.<br/>Meski-pun alam berubah,<br/>firman Tuhan tak goyah.<br/>',NULL,64918,2);
INSERT INTO stanza VALUES('I1427','2','Tuhan pernah menjanjikan,<br/>"Yang minta, pasti Ku b''ri!"<br/>Janji Tuhan pasti jadi,<br/>asal tak bimbang hati.<br/>',NULL,64919,3);
INSERT INTO stanza VALUES('I1427','3','Tiap do-a ada jawaban,<br/>lambat atau pun cepat.<br/>Kau harus tahan di-u-ji,<br/>lewat jalan yang sempit.<br/>',NULL,64920,4);
INSERT INTO stanza VALUES('I1427','4','Mintalah berdasar iman,<br/>penuh harap dan pu-jian.<br/>Bila t''lah sampai waktunya,<br/>nampak janji-Nya genap.<br/>',NULL,64921,5);
INSERT INTO stanza VALUES('I1428','1','"Balik ti-rai", kasih itu bagian-mu.<br/>Tinggal dalam raha-sia Tuhan-mu.<br/>Memandang-Nya, hingga mu-lia rupamu.<br/>Penuh kasih, pu-jian di bibirmu.<br/>',NULL,64922,1);
INSERT INTO stanza VALUES('I1428','2','"Balik tirai", ketika kau menatap.<br/>Wajah rupawan tia-da bandingan.<br/>Dapatkah kau jadi wahyu yang hidup.<br/>Kasih besar, kur-nia tak terkata.<br/>',NULL,64923,2);
INSERT INTO stanza VALUES('I1428','3','"Balik tirai", harum-Nya dicurahkan.<br/>Di luar tirai harum-Nya tersebar.<br/>"Balik tirai", musik-Nya dilantunkan.<br/>Gemakan pu-ji-an-Nya di bua-na.<br/>',NULL,64924,3);
INSERT INTO stanza VALUES('I1428','4','"Balik tirai", rohmu labuhkan sa-uh.<br/>Kau ''kan tenang di du-nia yang rusuh.<br/>"Balik tirai", kau dan Di-a bersatu.<br/>Hayat bangkit, di bumi kau tempuh.<br/>',NULL,64925,4);
INSERT INTO stanza VALUES('I1429','1','Tuhan memanggil kita s''mua,<br/>''tuk e-ko-no-mi ke-kal-Nya,<br/>I-ni-lah tu-juan hidup-ku,<br/>(oh! Hale-lu-ya, A-min)!<br/>((in-ti penghidupan-ku))<br/>Allah menjadi ma-nu-sia,<br/>manu-sia menjadi Al-lah,<br/>Di-a ma-ti bangkit ja-di Roh,<br/>di rohku ja-di ba-gian-ku.<br/>',NULL,64926,1);
INSERT INTO stanza VALUES('I1429','chorus','Vi-si e-ko-no-mi-Nya,<br/>mo-ga ter-u-kir di ha-ti-ku,<br/>so-rot-ku, a-gar roh-ku bang-kit,<br/>dan ku-at,<br/>Ja-di se-ru-pa d''ngan gambar-Nya,<br/>m''raja da-lam ha-yat,<br/>da-tang-kan (k''ra-jaan dan ku-a-sa).<br/>((Ye-ru-sa-lem Ba-ru))<br/>',NULL,64927,2);
INSERT INTO stanza VALUES('I1429','2','Oh, alangkah baha-gia-nya,<br/>Allah ba-ur d''ngan ma-nu-sia,<br/>Di tanah permai nikmati,<br/>Kristus Sang Re-a-li-tas;<br/>Har-ga-i hak istimewa,<br/>bangun Tubuh organik-Nya,<br/>Jadi ekspresi korporat-Nya,<br/>me-luas ke seluruh bumi.<br/>',NULL,64928,3);
INSERT INTO stanza VALUES('I1429','3','hati gembira roh berat,<br/>t''radap puncak visi ini.<br/>Aku perlu kua-sa bangkit,<br/>''tuk dapat dibangunkan.<br/>Tindak tanduk menurut Roh,<br/>bagi-Nya menabur benih,<br/>Menjadi model korporat-Nya,<br/>s''perti yang Tuhan kerjakan.<br/>',NULL,64929,4);
INSERT INTO stanza VALUES('I1429','4','Menurut roh pem-ba-ur-an,<br/>menempuh mati dan bangkit,<br/>Menanggalkan hayat jiwa,<br/>dosa daging, du-ni-a.<br/>Aku mau jadi pemenang,<br/>mengarah ke tu-juan ini.<br/>Tempuh hidup ma-nu-sia-Allah,<br/>tampilkan hidup k''ra-ja-an.<br/>',NULL,64930,5);
INSERT INTO stanza VALUES('I1430','1','Menga-sih-i, tan-pa di-ka-sih-i,<br/>mela-yan-i, tanpa diu-pah-i;<br/>Je-rih le-lah, tanpa o-rang i-ngat,<br/>mende-ri-ta tanpa o-rang li-hat,<br/>Tu-ang a-rak tanpa me-mi-numnya;<br/>pecah ro-ti tanpa mema-kannya;<br/>Cu-rah ha-yat biar orang lain bah''gia,<br/>lepas nyaman biar orang lain tent''ram,<br/>Tak mengharap ra-wat, sim-pa-ti,<br/>tak mengharap hi-bur dan pu-ji;<br/>Re-la gersang, re-la ter-ku-cil,<br/>re-la di-am, re-la ter-pen-cil.<br/>Air mata, darah s''bagai harga mahkota,<br/>re-la meru-gi, hidup ba-gai musa-fir;<br/>Kar''na sa-at Kau hidup di bu-mi,<br/>Kau-pun menempuh jalan i-ni.<br/>dengan gi-rang t''ri-ma s''ga-la d''ri-ta,<br/>a-gar yang dekat-Mu sento-sa.<br/>',NULL,64931,1);
INSERT INTO stanza VALUES('I1430','chorus','Ku tak ta-hu b''rapa jauh ja-lan i-ni,<br/>s''ka-li tempuh tak mungkin ku ulang-i;<br/>Biar ku b''lajar sempurna s''perti di-ri-Mu<br/>dihi-na o-rang tidak menge-luh.<br/>Mohon di ma-sa pri-ha-tin i-ni,<br/>se-ka-lah a-ir ma-ta ba-ti-ni,<br/>B''lajar kenal Kaulah Penghiburku,<br/>biar ku ja-di berkat s''panjang umur.<br/>',NULL,64932,2);
INSERT INTO stanza VALUES('I1431','1','Lahir kembali,<br/>kita mendapat hayat ilahi-Nya.<br/>Pem-ba-ru-an,<br/>kita menjadi cip-ta-an baru-Nya.<br/>Pe-ngu-dus-an,<br/>kita mendapatkan sifat kudus-Nya.<br/>Peng-u-bah-an,<br/>kita mendapat gambar ilahi-Nya.<br/>Pe-nye-ru-pa-an,<br/>kita mendapat kadar ilahi-Nya.<br/>Pe-mu-lia-an,<br/>kita tersusun gambar ilahi-Nya.<br/>Demi kes''lamatan organik,<br/>jadi raja dalam hayat.<br/>Genapkan ekonomi-Nya,<br/>ca-pai tu-juan ilahi-Nya.<br/>',NULL,64933,1);
INSERT INTO stanza VALUES('I1432','1','Berbicaralah, ya Tuhan!<br/>Ku ''nantikan firman-Mu.<br/>Damba dengar su-a-ra-Mu,<br/>bertuturlah, ya Tuhan!<br/>Ku mau dengar, ya Tuhan,<br/>ku mau dengar firman-Mu.<br/>',NULL,64934,1);
INSERT INTO stanza VALUES('I1432','2','Sering di dalam hatiku<br/>bukan sua-ra dari-Mu.<br/>Banyak bisikan menyusup<br/>dari balik ba-it-Mu.<br/>Bicaralah, ya Tuhan!<br/>Bungkam sua-ra yang palsu.<br/>',NULL,64935,2);
INSERT INTO stanza VALUES('I1432','3','Berbicaralah, ya Tuhan!<br/>Walau sayup sua-ra-Mu.<br/>Berbicaralah, ya Tuhan!<br/>Kau ta''u rindu dambaku.<br/>Se-mu-a yang ku perlu<br/>ti-dak la-in firman-Mu.<br/>',NULL,64936,3);
INSERT INTO stanza VALUES('I1432','4','Berbicaralah, ya Tuhan!<br/>Ku mau siap-kan hatiku.<br/>Dengan senang, pula ta-at,<br/>ku turuti firman-Mu.<br/>Ku ''kan dengar, ya Tuhan,<br/>bicaralah padaku!<br/>',NULL,64937,4);
INSERT INTO stanza VALUES('I1432','5','Panggil namaku, ya Tuhan,<br/>agar ku mendengar-Mu.<br/>Berbicaralah, ya Tuhan!<br/>Ku mau ikut jejak-Mu.<br/>Ke tempat Sang Gembala<br/>giring kawanan domba.<br/>',NULL,64938,5);
INSERT INTO stanza VALUES('I1501','1','O, baha-gia, dari Tau-rat<br/>beralih kepada Kristus.<br/>Kita t''lah nampak mu-lia-Nya,<br/>hanya ma-u Kristus!<br/>Hanya ma-u Kristus,<br/>hanya ma-u Kristus.<br/>Kita t''lah nampak mu-lia-Nya,<br/>hanya ma-u Kristus!<br/>',NULL,64939,1);
INSERT INTO stanza VALUES('I1501','2','Kristus bawa kita tinggal<br/>di Bait Allah, memuji Dia.<br/>O, haleluya Dia serta!<br/>Ba-it Allah indah!<br/>Ba-it Allah indah,<br/>Ba-it Allah indah.<br/>O, haleluya Dia serta!<br/>Ba-it Allah indah!<br/>',NULL,64940,2);
INSERT INTO stanza VALUES('I1501','3','Kota per-lu-as-an Ba-it,<br/>genap bangsa menggemari.<br/>Allah meraja ber-kua-sa,<br/>di bukit Sion suci.<br/>Di bukit Sion suci,<br/>di bukit Sion suci.<br/>Allah meraja ber-kua-sa,<br/>di bukit Sion suci.<br/>',NULL,64941,3);
INSERT INTO stanza VALUES('I1501','4','Dari Sion Tuhan raih bumi,<br/>atur, hibur, g''nap insani.<br/>G''nap bangsa datang berbakti,<br/>puji sorak nyaring!<br/>Puji sorak nyaring,<br/>puji sorak nyaring.<br/>G''nap bangsa datang berbakti,<br/>puji sorak nyaring!<br/>',NULL,64942,4);
INSERT INTO stanza VALUES('I1501','5','Kristus, Ba-it, kota, bumi,<br/>genapkan murad ilahi.<br/>Demilah tu-ju-an ini,<br/>kita s''mua sehati!<br/>Kita s''mua sehati,<br/>kita s''mua sehati.<br/>Demilah tu-ju-an ini,<br/>kita s''mua sehati.<br/>',NULL,64943,5);
INSERT INTO stanza VALUES('I1502','1','Ke Sion, Allah pulangkan yang tertawan.<br/>Puji syukur gegap p''ri orang khilaf.<br/>Gelak tawa, sorak-so-rai gempita.<br/>Hal besar t''lah Allah per-bu-at!<br/>Tuhan tamba''i bilang-an-nya,<br/>deras p''ri sungai s''latan.<br/>Tengok kaum tu-a meratap,<br/>dengar kaum muda bersorak!<br/>Kini kita kerja sama dengan riang.<br/>Jerih menabur, me-nu-ai ri-a.<br/>Haleluya, angkut tuai-an ke rumah!<br/>Di Sion mu-lia bagi Yehova.<br/>',NULL,64944,1);
INSERT INTO stanza VALUES('I1503','1','Ter-buang di Babel, tanah tawanan,<br/>ya, Tuhan, gugahlah roh kami!<br/>Terce-rai-be-rai, hilang ke-sa-tuan;<br/>ya, Tuhan, gugahlah roh kami!<br/>Gugah! Gugah!<br/>Ya, Tuhan, gugahlah roh kami!<br/>Gugah! Gugah!<br/>Ya, Tuhan gugahlah roh kami!<br/>',NULL,64945,1);
INSERT INTO stanza VALUES('I1503','2','Tinggalkan Babel, tanah s''mua sekte,<br/>bangkit dari s''mua perpecahan!<br/>Babel bukan tempat yang benar,<br/>bangkit dari s''mua perpecahan!<br/>Bangkit! Bangkit!<br/>Bangkit dari s''mua perpecahan!<br/>Bangkit! Bangkit!<br/>Bangkit dari s''mua perpecahan!<br/>',NULL,64946,2);
INSERT INTO stanza VALUES('I1503','3','Ke Yerusalem, kembali kita,<br/>balik, Allah beserta kita!<br/>Satu k''dudukan, saksi pun esa,<br/>balik, Allah beserta kita!<br/>Balik! Balik! Balik!<br/>Allah beserta kita!<br/>Balik! Balik! Balik!<br/>Allah beserta kita!<br/>',NULL,64947,3);
INSERT INTO stanza VALUES('I1503','4','Wadah p''nuh Kristus, cawan p''nuh Roh-Nya,<br/>bawalah se-mu-a bejana!<br/>Bawa ke g''reja, se-suai murad-Nya,<br/>bawalah se-mu-a bejana!<br/>Bawa! Bawa!<br/>Bawalah se-mu-a bejana!<br/>Bawa! Bawa!<br/>Bawalah se-mu-a bejana!<br/>',NULL,64948,4);
INSERT INTO stanza VALUES('I1503','5','Di Yerusalem, pilihan Allah,<br/>kita membangun Ba-it Allah!<br/>Layani s''rempak, sehati tia-sa,<br/>kita membangun Ba-it Allah!<br/>Bangun! Bangun!<br/>Kita membangun Ba-it Allah!<br/>Bangun! Bangun!<br/>Kita membangun Ba-it Allah!<br/>',NULL,64949,5);
INSERT INTO stanza VALUES('I1504','1','Aku t''lah pilih Si-on,<br/>tempat tinggal-Ku.<br/>Ini tempat perhen-tian kekal,<br/>tinggal di sini, inilah minat-Ku.<br/>Bekal makanannya penuh limpah,<br/>yang miskin ''kan dikenyangkan.<br/>Imamnya berjubahkan s''lamat.<br/>Ka-um saleh bersorak ri-ang.<br/>',NULL,64950,1);
INSERT INTO stanza VALUES('I1505','1','Umat tebusan pasti kembalilah,<br/>tiba di Si-on, sorak ri-ang!<br/>Sukacita kekal liput-i mereka;<br/>suka, girang, p''nuhi m''reka.<br/>S''mua duka, k''luh kesah,<br/>men-ja-uh-lah!<br/>Umat tebusan pasti kembalilah,<br/>tiba di Si-on,<br/>sorak ri-ang!<br/>Sukacita kekal liput-i mereka.<br/>',NULL,64951,1);
INSERT INTO stanza VALUES('I1506','1','K''liling, kelilingi Sion,<br/>di empat penjurunya.<br/>K''liling, kelilingi Si-on,<br/>hitunglah menaranya.<br/>',NULL,64952,1);
INSERT INTO stanza VALUES('I1506','2','O, perhatikan temboknya,<br/>o, jalani purinya.<br/>O, perhatikan temboknya,<br/>pun jalani purinya.<br/>',NULL,64953,2);
INSERT INTO stanza VALUES('I1506','3','Ja-uh di seb''lah utara,<br/>perkenan s''luruh bumi.<br/>Ja-uh di seb''lah utara,<br/>Si-on - menjulang permai!<br/>',NULL,64954,3);
INSERT INTO stanza VALUES('I1506','4','Sungai mengalir di Si-on,<br/>ada banyak cabangnya.<br/>Sungai mengalir di Si-on,<br/>semaraknya bertambah.<br/>',NULL,64955,4);
INSERT INTO stanza VALUES('I1506','5','Tuhan, Si-on memuji-Mu,<br/>Si-on ''kan memuji-Mu.<br/>Tuhan, Si-on memuji-Mu,<br/>kar''na penuh oleh-Mu.<br/>',NULL,64956,5);
INSERT INTO stanza VALUES('I1506','6','TUHAN, besar pula agung,<br/>layak t''rima pu-ji-an.<br/>TUHAN, besar pula agung,<br/>kota-Nya julang permai.<br/>',NULL,64957,6);
INSERT INTO stanza VALUES('I1506','7','O, mari memuji Allah,<br/>sua-ra pu-jian tak sudah.<br/>O, mari memuji Allah,<br/>yang takwa kepada-Nya.<br/>',NULL,64958,7);
INSERT INTO stanza VALUES('I1506','8','Dari Sion Allah b''ri berkat,<br/>berkat yang tak terbatas.<br/>Dari Sion Allah b''ri berkat,<br/>berkat hayat s''lamanya.<br/>',NULL,64959,8);
INSERT INTO stanza VALUES('I1506','9','Betapa ba-ik dan indah,<br/>saudara diam d''ngan rukun.<br/>Betapa ba-ik dan indah,<br/>saudara rukun satu!<br/>',NULL,64960,9);
INSERT INTO stanza VALUES('I1506','10','B''ri tahu keturunanmu,<br/>yang ma-u boleh datang.<br/>B''ri tahu keturunanmu, "Mari",<br/>kata Roh - mempelai.<br/>',NULL,64961,10);
INSERT INTO stanza VALUES('I1507','1','Kumpul di Yerusalem,<br/>lepas Babilo-ni-a.<br/>Saksikan ke-e-sa-an.<br/>O, mu-li-a bagi-Nya!<br/>Tolak s''mua teo-ri hampa,<br/>lepas s''mua doktrin sia-sia.<br/>Jaga ke-e-sa-an roh,<br/>dalam gereja lokal.<br/>',NULL,64962,1);
INSERT INTO stanza VALUES('I1507','chorus','Haleluya! Haleluya!<br/>Satu hatilah kita membangun Tubuh Kristus.<br/>Haleluya! Haleluya!<br/>Di gereja lokal kita s''mua hidup.<br/>',NULL,64963,2);
INSERT INTO stanza VALUES('I1507','2','Agar pe-mu-li''an lancar,<br/>iman kita perlukan.<br/>Tinggal di dalam Tuhan,<br/>o, mu-li-a bagi-Nya!<br/>Imam hidup depan-Nya,<br/>Kristus meresapinya.<br/>Bangun istana Allah,<br/>di se-mua g''reja lokal.<br/>',NULL,64964,3);
INSERT INTO stanza VALUES('I1507','3','Mata kita tercelik,<br/>nampak pengaturan-Nya.<br/>Allah mutlak ber-kua-sa,<br/>o, mu-li-a bagi-Nya!<br/>Agar g''reja terbangun,<br/>peganglah syarat ini:<br/>Pada roh ta-at mutlak,<br/>di se-mua g''reja lokal.<br/>',NULL,64965,4);
INSERT INTO stanza VALUES('I1507','4','Mezbah kita hampiri,<br/>s''mua tersembah bagi-Nya.<br/>De-mi-ki-an mengabdi,<br/>o, mu-li-a bagi-Nya!<br/>Rela s''rahkan bagi-Nya,<br/>tanpa berbantah-bantah.<br/>Nyata Tubuh yang esa di<br/>se-mua g''reja lokal.<br/>',NULL,64966,5);
INSERT INTO stanza VALUES('I1507','5','Pondasi t''lah berdiri,<br/>mu-lia megah ternyata.<br/>Kita bergirang hati,<br/>o, mu-li-a bagi-Nya!<br/>Mari kita bersorak,<br/>biar bangsa-bangsa dengar.<br/>Musuh-musuh terhempas,<br/>di se-mua g''reja lokal.<br/>',NULL,64967,6);
INSERT INTO stanza VALUES('I1508','1','Kristus ada g''reja mu-lia, kita ada ba-gi-an.<br/>Sungguh girang Tuhan yang mengesakan!<br/>Tengok ada satu Tubuh raya, kita miliknya.<br/>Haleluya! Tuhan yang mengesakan! Haleluya!<br/>Tubuh mu-lia! Kita ini anggotanya!<br/>Bagi Tuhan anteronya!<br/>Haleluya! Tuhan yang mengesakan!<br/>',NULL,64968,1);
INSERT INTO stanza VALUES('I1508','2','Bukan Kristen sen-di-ri-an me-la-in-kan korporat,<br/>agar dapat ''nyatakan diri Allah.<br/>Bukan satu g''reja lokal, tapi Tubuh segenap,<br/>haleluya! Kita ada dalam-Nya!<br/>Haleluya! Tubuh mu-lia! Iblis gentar terhadap-Nya!<br/>Dalam Tubuh kita menang!<br/>Haleluya! Kita ada dalam-Nya!<br/>',NULL,64969,2);
INSERT INTO stanza VALUES('I1508','3','Sifat Allah yang kudus mutlak, ''nyata di dian emas,<br/>hidup Tubuh singkirkan la-hi-ri-ah.<br/>Esa dan ''ngandung sifat Allah, dian emas cemerlang.<br/>Haleluya! Bercahaya cemerlang!<br/>Haleluya! Tubuh mu-lia! Tubuh ini kaki dian ''mas!<br/>Di mana pun ''nyorot cerah!<br/>Haleluya! Bercahaya cemerlang!<br/>',NULL,64970,3);
INSERT INTO stanza VALUES('I1508','4','Esa ini telah ternyata, kudus lagi cerah,<br/>haleluya, santap Yesus jalannya!<br/>Dia pohon hayat dan manna, hidangan segar,<br/>nikmat. Haleluya! Hari-hari santap Dia!<br/>De-mi-ki-an kita esa! Serupa teladan mu-lia!<br/>De-mi-ki-an bercahaya!<br/>Haleluya! Santap Yesus jalannya!<br/>',NULL,64971,4);
INSERT INTO stanza VALUES('I1509','1','Dalam roh, dalam roh,<br/>dalam roh, dalam roh,<br/>Tuhan mewahyukan<br/>ra-ha-si-a besar!<br/>Dalam roh ku nampak,<br/>gereja dan du-nia.<br/>Dalam roh ku nampak,<br/>agama dan kota.<br/>',NULL,64972,1);
INSERT INTO stanza VALUES('I1509','chorus','Dalam roh, dalam roh!<br/>Buang dunia, agama!<br/>Mem-pe-lai siap se-dia,<br/>Tuhan segera datanglah!<br/>',NULL,64973,2);
INSERT INTO stanza VALUES('I1509','2','Dalam roh ku nampak,<br/>mata-Nya p''ri bara.<br/>S''mua yang tersembunyi,<br/>tersingkap depan-Nya.<br/>Ya Tuhan, ku tobat!<br/>Yang perlu, bakarlah!<br/>Buang du-nia, d''ngan tuntas,<br/>biar kakiku terang!<br/>',NULL,64974,3);
INSERT INTO stanza VALUES('I1509','3','Dalam roh ku nampak,<br/>tujuh Roh dan bintang.<br/>Roh ku-at, bintang t''rang,<br/>ma-ut tia-da ba-gian.<br/>Ku tak ma-u teo-ri,<br/>tapi roh dan kua-sa.<br/>Lepaslah agama,<br/>hingga roh membara.<br/>',NULL,64975,4);
INSERT INTO stanza VALUES('I1509','4','Dalam roh,<br/>ku pegang kunci ke-ra-ja-an.<br/>Do-a baca firman,<br/>seru nama Tuhan!<br/>Saling mengasihi,<br/>bu-ang cacar kerut.<br/>Menjaga mahkota,<br/>dapat nama baru.<br/>',NULL,64976,5);
INSERT INTO stanza VALUES('I1509','5','Dalam roh aminlah,<br/>dalam roh esalah.<br/>Ada awal baru,<br/>tak ma-u yang usang.<br/>Jadikanku mutlak,<br/>rela bayar harga.<br/>Latih roh, bebas roh,<br/>ta-at roh, penuh roh.<br/>',NULL,64977,6);
INSERT INTO stanza VALUES('I1510','1','Dalam zaman wahyu ini,<br/>nampak Anak Ma-nu-sia.<br/>Di tengah tujuh kandil ''mas,<br/>bergerak serta g''reja.<br/>Dia-lah penyataan Allah,<br/>pula kesak-sian Allah.<br/>Gereja ekspresi Allah,<br/>sifatnya murni emas.<br/>',NULL,64978,1);
INSERT INTO stanza VALUES('I1510','2','Tuhan sedang panggil g''reja,<br/>bersinar saksikan Dia.<br/>Kami rampungkan murad-Nya,<br/>singkirkan se-mua cela.<br/>Walau zaman penuh liku,<br/>gelap, ti-a-da hayat.<br/>Tapi g''reja ''nyorot terang,<br/>Tuhan terekspresikan.<br/>',NULL,64979,2);
INSERT INTO stanza VALUES('I1510','3','Tuhan, kami syukur puji,<br/>g''reja memp''lai p''rem-puan-Mu.<br/>Hasilkan anak lelaki,<br/>mengalahkan musuh-Mu.<br/>Tuhan, kami ma-u menang,<br/>memulihkan kua-sa-Mu.<br/>Dosa, du-nia, bersih hapus,<br/>dirikan k''ra-ja-an-Mu.<br/>',NULL,64980,3);
INSERT INTO stanza VALUES('I1510','4','Hakiki dan karya Tuhan,<br/>se-mua ada di g''reja.<br/>Sejak nampak isi g''reja,<br/>hati kami tak goyah.<br/>Nampak wahyu, hati pikat,<br/>damba tempuh jalan-Mu.<br/>Untuk visi wahyu ini,<br/>Tuhan, mu-lia bagi-Mu!<br/>',NULL,64981,4);
INSERT INTO stanza VALUES('I1511','1','Tengok g''reja lokal,<br/>di larut malam.<br/>Jadi saksi Tuhan,<br/>pancar terang-Nya.<br/>Kristus pembentuknya,<br/>Roh pencetaknya.<br/>Sama dalam kodrat,<br/>Kristus tertampak.<br/>',NULL,64982,1);
INSERT INTO stanza VALUES('I1511','chorus','Tengok!<br/>G''reja lokal di larut malam.<br/>Roh Kudus membakar,<br/>terang benderang.<br/>',NULL,64983,2);
INSERT INTO stanza VALUES('I1511','2','Dalam Kristus,<br/>Allah t''lah berlembaga;<br/>kini Roh itulah<br/>jadi rea-li-tas.<br/>Ti-ap g''reja lokal,<br/>reproduksi-Nya,<br/>masing-masing lokal,<br/>g''reja ternyata.<br/>',NULL,64984,3);
INSERT INTO stanza VALUES('I1511','3','Jalan antar g''reja,<br/>Anak Ma-nu-sia;<br/>jubah ka-in lenan,<br/>''tuk Imam Besar!<br/>Dada berlilit mas,<br/>rawatan cinta;<br/>ada tujuh bintang,<br/>g''reja kian mantap!<br/>',NULL,64985,4);
INSERT INTO stanza VALUES('I1511','4','Sia-pa bisa halang<br/>kaki dian emas?<br/>Tentangan kian dahsyat,<br/>kembang kian pesat!<br/>Si-tua-si kian kelam,<br/>terang kian tajam!<br/>Oleh hayat Allah<br/>adanya g''reja.<br/>',NULL,64986,5);
INSERT INTO stanza VALUES('I1511','5','Dari g''reja lokal<br/>mempelai Tuhan,<br/>Yerusalem tiba,<br/>Kota Kudus-Nya.<br/>Se-mua kaki di-an,<br/>jadilah esa.<br/>Nampakkan di jagat,<br/>Allah Trinitas.<br/>',NULL,64987,6);
INSERT INTO stanza VALUES('I1511','chorus','Turun dari surga,<br/>nampak di bua-na.<br/>Penampilan Allah<br/>s''lama-lamanya.<br/>',NULL,64988,7);
INSERT INTO stanza VALUES('I1512','1','Wahyu pasal dua dan tiga,<br/>menampakkan asli g''reja.<br/>Mengajar aku dan Anda,<br/>dalam pu-li''an, jangan lengah.<br/>',NULL,64989,1);
INSERT INTO stanza VALUES('I1512','2','M''reka perlu b''ri telinga,<br/>kita lebih harus cermat.<br/>Murad Tuhan memp''ringatkan,<br/>agar g''reja kudus, mu-lia.<br/>',NULL,64990,2);
INSERT INTO stanza VALUES('I1512','3','Di Efesus, Dia mencela,<br/>"Kasih s''mula telah hilang.<br/>Rajin kerja, lupa Tuhan;<br/>lekas tobat, p''ri semula."<br/>',NULL,64991,3);
INSERT INTO stanza VALUES('I1512','4','Berpalinglah, ''hadap Tuhan,<br/>kasih la-in boleh tia-da.<br/>Mari kita dengarkan Dia;<br/>jangan hilang Sang Mustika.<br/>',NULL,64992,4);
INSERT INTO stanza VALUES('I1512','5','Pada Smirna yang mend''rita,<br/>"Kau teruji, tia-da jera.<br/>Se-ti-a-mu sampai ajal,<br/>rela korban jiwa raga."<br/>',NULL,64993,5);
INSERT INTO stanza VALUES('I1512','6','Se-tia hingga lahir lenyap,<br/>jangan tengok su-a-sa-na.<br/>Tentu ada maksud Tuhan,<br/>yang menguji cinta kita.<br/>',NULL,64994,6);
INSERT INTO stanza VALUES('I1512','7','Di Pergamus, lebih parah,<br/>kawin ba-ur dengan du-nia.<br/>Si Antipas, martir se-tia,<br/>hanya di-a b''rani ''nentang.<br/>',NULL,64995,7);
INSERT INTO stanza VALUES('I1512','8','Wajib kita gentar ''tia-sa,<br/>jangan zina dengan du-nia.<br/>Firman Tuhan tolong kita,<br/>asal amin terhadap-Nya.<br/>',NULL,64996,8);
INSERT INTO stanza VALUES('I1512','9','Ti-a-ti-ra menyusulnya,<br/>dari la-in ku-a-sa-nya.<br/>Tepung, ragi, bercampuran,<br/>sundal, satwa, gabung ju-a.<br/>',NULL,64997,9);
INSERT INTO stanza VALUES('I1512','10','Yang tak murni, sorotilah;<br/>imitasi, Tuhan bongkar!<br/>Ba-ik, jelek, lontar se-mua,<br/>hingga Dikau p''roleh mutlak.<br/>',NULL,64998,10);
INSERT INTO stanza VALUES('I1512','11','Dari Sardis, nampak jelas,<br/>hayat saja, itu jalan.<br/>''Ngaku hidup, namun tidak,<br/>wahai Sardis, perlu tobat.<br/>',NULL,64999,11);
INSERT INTO stanza VALUES('I1512','12','Tuhan pimpin jamah hayat,<br/>menang atas ke-ma-ti-an.<br/>Campak latar beragama,<br/>penuh hayat, Dikau pu-as.<br/>',NULL,65000,12);
INSERT INTO stanza VALUES('I1512','13','Fi-la-del-fia menyatakan:<br/>Pelihara yang t''lah ada.<br/>Nama, firman, saling cinta,<br/>gereja nan Tuhan sayang.<br/>',NULL,65001,13);
INSERT INTO stanza VALUES('I1512','14','Umat Allah esa mutlak,<br/>demi hayat be-rea-li-tas.<br/>Pegang m''lulu diri Tuhan,<br/>laksanakan murad Allah.<br/>',NULL,65002,14);
INSERT INTO stanza VALUES('I1512','15','Hai, Lao-di-kia, perhatikan,<br/>merosotnya disebabkan.<br/>''Ngaku diri sudah kaya,<br/>tia-da tahu, Tuhan di luar.<br/>',NULL,65003,15);
INSERT INTO stanza VALUES('I1512','16','Jangan lagi su-am-su-am,<br/>Roh berkobar, ikut ''tia-sa.<br/>Masuk hayat de-ngan limpah,<br/>diperkenan pesta s''rempak.<br/>',NULL,65004,16);
INSERT INTO stanza VALUES('I1512','17','Mohon Tuhan beri terang,<br/>tempuhan-Mu aku damba.<br/>Usap mata, agar nampak,<br/>pe-mu-li''an-Mu ''capai seg''ra.<br/>',NULL,65005,17);
INSERT INTO stanza VALUES('I1513','1','Lihat! O-rang ti-ap suku dan bangsa.<br/>Pa-kai jubah putih di depan takhta Domba.<br/>Seru lantang,"S''lamat bagi Allah - Domba".<br/>Mu-lia, pu-jian bagi-Nya sam-pai kekal.<br/>',NULL,65006,1);
INSERT INTO stanza VALUES('I1513','2','Yang duduk di takhta tudung-i kita.<br/>Tak lagi ha-us, lapar dan tersengat surya.<br/>Anak Domba bawa kita ke air hayat.<br/>Allah pasti hapus a-ir mata kita.<br/>',NULL,65007,2);
INSERT INTO stanza VALUES('I1514','1','Tengok! Mereka bersidang,<br/>memegang kedudukan.<br/>Kaki dian ''mas bercahaya,<br/>hingga Allah semayam.<br/>',NULL,65008,1);
INSERT INTO stanza VALUES('I1514','chorus','''Nilah g''reja lokal pilihan Allah,<br/>g''nap kaum saleh esalah!<br/>''Nilah g''reja lokal pilihan Allah,<br/>g''nap kaum saleh esalah!<br/>',NULL,65009,2);
INSERT INTO stanza VALUES('I1514','2','Tengok! Mereka bersidang,<br/>angkat su-a-ra lantang.<br/>Kisahkan kur-nia serempak,<br/>Tuhan, Kristus, masyhurlah!<br/>',NULL,65010,3);
INSERT INTO stanza VALUES('I1514','3','Dengar! M''reka do-a-baca,<br/>menyesap firman hayat.<br/>Do-a, puji, makan, minum,<br/>memang sangatlah nikmat!<br/>',NULL,65011,4);
INSERT INTO stanza VALUES('I1514','4','Dengar! M''reka s''ru,<br/>"O, Yesus!" Nama Tuhan tersayang!<br/>Proklamirkan,"Yesus Tuhan!"<br/>Ri-ang ki-an bertambah.<br/>',NULL,65012,5);
INSERT INTO stanza VALUES('I1514','5','Dengar! S''ru-an,"Haleluya!"<br/>Menggema p''ri ledakan!<br/>Haleluya! Haleluya!<br/>Musuh sudah tercampak!<br/>',NULL,65013,6);
INSERT INTO stanza VALUES('I1514','6','Tengok! Kaum saleh tersebar,<br/>mu-lai gerakan Tuhan.<br/>Wujud g''reja di tiap lokal,<br/>biar Dia segera datang!<br/>',NULL,65014,7);
INSERT INTO stanza VALUES('I1514','7','Tengok! Kristus se-g''ra datang,<br/>bagi g''reja Dia korban.<br/>Meng-hi-as-i mempelai-Nya,<br/>sambut jodoh-Nya sayang!<br/>',NULL,65015,8);
INSERT INTO stanza VALUES('I1514','chorus','Gereja mu-lia, tak bercacat cela,<br/>penuhlah mu-lia Tuhan!<br/>Gereja mu-lia, tak bercacat cela,<br/>penuhlah mu-lia Tuhan!<br/>',NULL,65016,9);
INSERT INTO stanza VALUES('I1515','1','Ini se-ruan g''reja:<br/>Yesus itu Tuhan!<br/>Yang beriman bers''ru:<br/>Yesus itu Tuhan!<br/>Sudah rampung s''mua karya-Nya,<br/>ten-t''ra setan ditaklukkan.<br/>Dia naik takhta mu-lia:<br/>Yesus itu Tuhan!<br/>',NULL,65017,1);
INSERT INTO stanza VALUES('I1515','2','Kini Dia Roh hidup:<br/>Yesus itu Tuhan!<br/>Dalam umat dengar:<br/>Yesus itu Tuhan!<br/>Tidak perlu kau bersedih,<br/>seru nama-Nya,<br/>Dia masuk. Jadi pribadimu:<br/>Yesus itu Tuhan!<br/>',NULL,65018,2);
INSERT INTO stanza VALUES('I1515','3','Dia ubah hidupmu:<br/>Yesus itu Tuhan!<br/>Limpah-Nya bagimu:<br/>Yesus itu Tuhan!<br/>Dia s''lalu puas-kan hatimu,<br/>ti-ap hari suplai hayat!<br/>Di-a dan kau satu:<br/>Yesus itu Tuhan!<br/>',NULL,65019,3);
INSERT INTO stanza VALUES('I1515','4','Rahmat-Nya t''rimaku:<br/>Yesus itu Tuhan!<br/>Dia tak tinggalkanku:<br/>Yesus itu Tuhan!<br/>Dalam Tubuh kita nampak<br/>s''mua kelimpahan sifat-Nya.<br/>Iblis lari kabur:<br/>Yesus itu Tuhan!<br/>',NULL,65020,4);
INSERT INTO stanza VALUES('I1516','1','Di gereja lokal,<br/>pi-li''an Allah.<br/>Kristus jadilah hayat,<br/>Roh-Nya berkua-sa<br/>(Haleluya!)<br/>Tegaplah dalam roh,<br/>tegap berp''rang!<br/>Kita pastilah menang,<br/>datanglah Keraja-an Allah!<br/>',NULL,65021,1);
INSERT INTO stanza VALUES('I1517','1','Kristus Kepala,<br/>di g''reja lokal,<br/>di g''reja lokal,<br/>di g''reja lokal.<br/>Kristus Kepala,<br/>di g''reja lokal,<br/>Kristus Kepala.<br/>',NULL,65022,1);
INSERT INTO stanza VALUES('I1517','2','Kristus rea-litas,<br/>di g''reja lokal,<br/>di g''reja lokal,<br/>di g''reja lokal.<br/>Kristus rea-litas,<br/>di g''reja lokal,<br/>Kristus rea-litas.<br/>',NULL,65023,2);
INSERT INTO stanza VALUES('I1517','3','Suplaian limpah,<br/>di g''reja lokal,<br/>di g''reja lokal,<br/>di g''reja lokal.<br/>Suplaian limpah,<br/>di g''reja lokal,<br/>suplaian limpah.<br/>',NULL,65024,3);
INSERT INTO stanza VALUES('I1517','4','Kita berteduh,<br/>di g''reja lakl,<br/>di g''reja lokal,<br/>di g''reja lokal.<br/>Kita berteduh,<br/>di g''reja lokal,<br/>rumah nan indah.<br/>',NULL,65025,4);
INSERT INTO stanza VALUES('I1518','1','G''reja lokal (G''reja lokal);<br/>g''reja tersayang (g''reja tersayang).<br/>Yang ku rindu! (Yang ku rindu!)<br/>Yang ku cinta! (Yang ku cinta!)<br/>Limpah Kristus (Limpah Kristus)<br/>ada pada-nya! (ada padanya!)<br/>Amat bah''-gia! (Amat bah''-gia!)<br/>Amat berkat! (Amat berkat!)<br/>Demi kasih-Nya kita<br/>digarap menjadi istana-Nya.<br/>Betapa indah! Betapa mu-lia!<br/>G''reja lokal (G''reja lokal),<br/>g''reja tersayang (g''reja tersayang).<br/>Yang ku rindu! (Yang ku rindu!)<br/>Yang ku cinta! (Yang ku cinta!)<br/>',NULL,65026,1);
INSERT INTO stanza VALUES('I1519','1','Tengok! Bangsa-bangsa datang,<br/>ke tempat pilihan-Nya.<br/>Mari! Menuju rumah-Nya,<br/>dari Sion p''rintah Dia b''ri.<br/>',NULL,65027,1);
INSERT INTO stanza VALUES('I1519','chorus','O, g''reja lokal,<br/>sungguh penuh berkat,<br/>penuh ka-ru-nia mu-lia.<br/>O, g''reja lokal,<br/>ku sayang padamu,<br/>hati, jiwaku buat-mu!<br/>',NULL,65028,2);
INSERT INTO stanza VALUES('I1519','2','Tengok! Saudara rukunlah,<br/>alangkah manis, indah!<br/>Dari kepala ke jubah,<br/>minyak ''ngalir s''dap segar!<br/>',NULL,65029,3);
INSERT INTO stanza VALUES('I1519','3','Tengok! Tuhan sayang g''reja,<br/>korban diri baginya.<br/>Basuh dengan firman hayat,<br/>dijadikan jodoh-Nya!<br/>',NULL,65030,4);
INSERT INTO stanza VALUES('I1519','chorus','Gereja mu-lia,<br/>tanpa cacat kerut,<br/>penuhlah mu-lia Tuhan!<br/>Mempelai p''rem-puan,<br/>negeri yang baru,<br/>penuhlah mu-lia Tuhan!<br/>',NULL,65031,5);
INSERT INTO stanza VALUES('I1519','4','Tengok! Mu-lia-Nya ternyata,<br/>tujuh bintang, tujuh Roh!<br/>Kaki dian ''mas bercahaya,<br/>akhiri zaman bobrok.<br/>',NULL,65032,6);
INSERT INTO stanza VALUES('I1520','1','Penyembahan usang sia-sia,<br/>liturgi dan la-in-nya.<br/>Tata cara dan ajaran,<br/>kekristenan yang usang!<br/>Kini nampak kehendak-Nya,<br/>nyata di g''reja lokal.<br/>Tum-puan esa, kita himpun,<br/>kini kita hiduplah!<br/>Kita hiduplah!<br/>Kita hiduplah!<br/>Konsep usang s''mua enyahlah,<br/>Kristus kita dapatkan.<br/>',NULL,65033,1);
INSERT INTO stanza VALUES('I1520','2','Dulu damba na-ik surga,<br/>istana di angkasa.<br/>Meski tahu ini sia-sia,<br/>kita tetap ters''lubung.<br/>Himpun di tum-pu-an g''reja,<br/>temukan re-a-li-tas.<br/>Kristuslah K''ra-ja-an Allah,<br/>kini nyata di g''reja.<br/>Nyata di g''reja!<br/>Nyata di g''reja!<br/>Kehendak<br/>Allah tak hampa,<br/>mutlak nyata di g''reja.<br/>',NULL,65034,2);
INSERT INTO stanza VALUES('I1521','1','Bu-ang se-mua latar belakang,<br/>asal berpaling,<br/>sorot terang-Nya.<br/>Bu-ang se-mua ajaran mati,<br/>Kristus yang hidup,<br/>yang kau butuhkan.<br/>',NULL,65035,1);
INSERT INTO stanza VALUES('I1521','chorus','Mari, ke tempat a-jaib,<br/>pilihan Allah, wujud murad-Nya.<br/>Mari, ke rumah a-jaib,<br/>teduh, nikmat, tak merantau pula.<br/>',NULL,65036,2);
INSERT INTO stanza VALUES('I1521','2','G''reja, g''reja, tum-pu-an lokal.<br/>Kaki dian emas, terang memancar.<br/>G''reja rencana kekal Allah.<br/>Kristus semayam, nyata hikmat-Nya.<br/>',NULL,65037,3);
INSERT INTO stanza VALUES('I1521','3','Mari kita se-mua berhimpun.<br/>Jadi saksi-Nya, membangun g''reja.<br/>Mari, se-mu-a sudah genap.<br/>Kristus Kepala memanggil kita.<br/>',NULL,65038,4);
INSERT INTO stanza VALUES('I1522','1','Nampak su-ngai hidup,<br/>kami terjun segera.<br/>Pada tum-pu-an lokal.<br/>Nampak su-ngai hidup,<br/>kami terjun segera.<br/>Pada tum-pu-an lokal.<br/>',NULL,65039,1);
INSERT INTO stanza VALUES('I1522','chorus','Tuhan, kami se-mua,<br/>pada tum-pu-an lokal.<br/>Tuhan, kami se-mua,<br/>pada tum-pu-an lokal.<br/>',NULL,65040,2);
INSERT INTO stanza VALUES('I1522','2','Kita telah nampak visi<br/>pe-mu-li''an g''reja,<br/>pada tum-pu-an lokal ...<br/>',NULL,65041,3);
INSERT INTO stanza VALUES('I1522','3','Gereja lokal<br/>bukanlah denominasi,<br/>pada tum-pu-an lokal ...<br/>',NULL,65042,4);
INSERT INTO stanza VALUES('I1522','4','Tuhan, kami mengasihi<br/>se-mua saudara,<br/>pada tum-pu-an lokal ...<br/>',NULL,65043,5);
INSERT INTO stanza VALUES('I1522','5','Kita terpanggil untuk<br/>bersama berlatih,<br/>pada tum-pu-an lokal ...<br/>',NULL,65044,6);
INSERT INTO stanza VALUES('I1522','6','Kita pasukan Tuhan,<br/>berperang bagi-Nya,<br/>pada tum-pu-an lokal ...<br/>',NULL,65045,7);
INSERT INTO stanza VALUES('I1522','7','Kita tetap se-ti-a,<br/>sampai Tuhan datang,<br/>pada tum-pu-an lokal ...<br/>',NULL,65046,8);
INSERT INTO stanza VALUES('I1523','1','Ku t''lah bebas dari du-nia,<br/>tak mungkin aku balik!<br/>Allah t''lah me-ny''lamatkanku,<br/>tak mungkin aku balik!<br/>',NULL,65047,1);
INSERT INTO stanza VALUES('I1523','chorus','Tidak, tidak mungkin,<br/>tak mungkin aku balik!<br/>Tidak, tidak mungkin,<br/>tak mungkin aku balik!<br/>',NULL,65048,2);
INSERT INTO stanza VALUES('I1523','2','Ku t''lah ke-luar dari Babel,<br/>tak mungkin aku balik ...<br/>',NULL,65049,3);
INSERT INTO stanza VALUES('I1523','3','Ku t''lah dapatkan gereja,<br/>tak mungkin aku balik ...<br/>',NULL,65050,4);
INSERT INTO stanza VALUES('I1523','4','Puji Tuhan, ku t''lah pulang,<br/>tak mungkin aku balik ...<br/>',NULL,65051,5);
INSERT INTO stanza VALUES('I1523','5','Ku sudah menjamah Tuhan,<br/>tak mungkin aku balik ...<br/>',NULL,65052,6);
INSERT INTO stanza VALUES('I1523','6','Kristus adalah s''galaku,<br/>tak mungkin aku balik ...<br/>',NULL,65053,7);
INSERT INTO stanza VALUES('I1523','7','Aku bagi pe-mu-li''an-Nya,<br/>tak mungkin aku balik ...<br/>',NULL,65054,8);
INSERT INTO stanza VALUES('I1524','1','Seumurku telah tetap,<br/>haleluya!Haleluya!<br/>Kristus, g''reja bagi-an-ku,<br/>haleluya! Haleluya!<br/>Tak ber-k''lana dalam du-nia,<br/>teduh di g''reja nikmat limpah-Nya,<br/>haleluya! Haleluya!<br/>',NULL,65055,1);
INSERT INTO stanza VALUES('I1525','1','Kami bagi pemulihan<br/>gereja Tuhan.<br/>Agarlah di ti-ap lokal,<br/>nampak wujudnya.<br/>Teguh pada lokalitas,<br/>esa dalam-Nya.<br/>Membangun ke-diam-an Allah,<br/>g''napkan murad-Nya.<br/>',NULL,65056,1);
INSERT INTO stanza VALUES('I1525','chorus','Kami bagi-Nya,<br/>kami bagi-Nya,<br/>bagilah pe-muli''an Tuhan!<br/>Kami bagi-Nya,<br/>kami bagi-Nya,<br/>bagi pe-muli''an-Nya.<br/>',NULL,65057,2);
INSERT INTO stanza VALUES('I1525','2','Kami bagi pemulihan<br/>gereja Tuhan.<br/>Saksi Kristus dan junjunglah,<br/>siap-kan K''ra-ja-an-Nya!<br/>Hidup di roh di tiap lokal,<br/>luas-kan Injil-nya.<br/>Tuhan! Amin!<br/>Haleluya!<br/>Datang segera!<br/>',NULL,65058,3);
INSERT INTO stanza VALUES('I1525','3','Kami bagi pemulihan<br/>gereja Tuhan.<br/>Latih roh se-nan-ti-a-sa,<br/>visi kian tegas!<br/>Sudah runtuh Babel besar,<br/>Iblis terganyang.<br/>Kota Kudus pun turunlah,<br/>mu-lia cemerlang!<br/>',NULL,65059,4);
INSERT INTO stanza VALUES('I1526','1','Dia tolong kita lepas zaman jahat,<br/>himpun kita bagi kehendak-Nya.<br/>Kita s''mua harus nampak visi ini,<br/>haleluya! Ini pemu-li''an-Nya.<br/>',NULL,65060,1);
INSERT INTO stanza VALUES('I1526','chorus','Di tiap kota, tegak atas tumpuan lokal.<br/>Tak sandar kuat diri, a-la-mi-ah.<br/>Tak lagi individu, ''nuntut sen-di-rian,<br/>tapi ''tia-sa ikut arus g''reja, sambut Tuhan.<br/>',NULL,65061,2);
INSERT INTO stanza VALUES('I1526','2','Di arus, lupa b''lakang, maju depan,<br/>buang agama, buang bersih du-ni-a.<br/>Kini Tuhan melakukan hal baru,<br/>haleluya! Ini pemu-lia''an-Nya.<br/>',NULL,65062,3);
INSERT INTO stanza VALUES('I1526','3','Tujuh Roh - g''reja lokal kaki dian ''mas,<br/>dalam g''reja, Putra nyata pancar.<br/>Tujuh kaki dian ''mas sorot pun bakar,<br/>haleluya! Ini pemu-li''an-Nya.<br/>',NULL,65063,4);
INSERT INTO stanza VALUES('I1526','4','Dia menang, dengan kua-sa bangun g''reja,<br/>kita tegak di atas jaya-Nya.<br/>Genaplah! Musuh di bawah kaki-Nya,<br/>haleluya! Ini pemu-li''an-Nya.<br/>',NULL,65064,5);
INSERT INTO stanza VALUES('I1526','5','Dalam g''reja hayat-Nya suplai ''tia-sa,<br/>haleluya, genap g''reja maju.<br/>Aliran ini Kristus Sang Rea-li-tas,<br/>haleluya! Ini pemu-li''an-Nya.<br/>',NULL,65065,6);
INSERT INTO stanza VALUES('I1526','6','Di g''reja kita nampak visi ini,<br/>tak sendiri, dibangun bersama.<br/>Bersama maju, jadi saksi Tuhan,<br/>haleluya! Ini pemu-li''an-Nya.<br/>',NULL,65066,7);
INSERT INTO stanza VALUES('I1527','1','Kita se-mua bagi pu-li''an Allah,<br/>pu-li''an Allah, pu-li''an Allah.<br/>Kita bagi kesak-si-an Allah,<br/>kesaksian-Nya, kesaksian-Nya.<br/>Tegap, roh membara, membakar kita,<br/>bakar kita, bakar kita.<br/>Hati tulus, polos, hampiri Allah,<br/>hampiri Dia, hampiri Dia.<br/>Hari depan tak hiraukan!<br/>Hidup bagi pulihan-Nya.<br/>Pulihan-Nya,<br/>pulihan-Nya,<br/>pulihan-Nya!<br/>Bagi pemulihan dan kesak-sian Allah!<br/>Hari depan tak hiraukan!<br/>Hidup bagi pulihan-Nya.<br/>Pulih, pulih, pulih,<br/>pulih, pulih, pulih !<br/>Bagi pemulihan dan kesak-sian Allah!<br/>',NULL,65067,1);
INSERT INTO stanza VALUES('I1528','1','Kinilah sa-at-nya, waktu tidak banyak.<br/>Pilihlah sia-pa yang kau layani!<br/>Ma-u-kah bersama ber-p''rang bagi Tuhan.<br/>Tumpas musuh, si Iblis yang licik?<br/>',NULL,65068,1);
INSERT INTO stanza VALUES('I1528','2','Kinilah sa-at-nya, banyak orang bimbang.<br/>Iblis ganas, bikin kerusuhan.<br/>Maka kita harus anggap se-mua sampah.<br/>Bayar harga, bagi pemu-li''an-Nya!<br/>',NULL,65069,2);
INSERT INTO stanza VALUES('I1528','3','Kinilah sa-at-nya, Roh Kudus bekerja.<br/>Pemulihan makin dipercepat.<br/>Bentuk "insan baru" se-suai rencana-Nya.<br/>Tarik orang datang kepada-Nya.<br/>',NULL,65070,3);
INSERT INTO stanza VALUES('I1528','4','Kini hari akhir, ke-luar mem-b''ritakan.<br/>Biar s''mua tahu, k''ra-ja-an ''kan tiba!<br/>Pasukan-Nya datang, musuh tunggang langgang.<br/>S''luruh bumi, ta-at kepada-Nya.<br/>',NULL,65071,4);
INSERT INTO stanza VALUES('I1529','1','Masuk dalam zaman wahyu,<br/>denominasi lepaslah.<br/>Dalam g''reja lokal,<br/>roh kita esalah.<br/>Tanpa belenggu agama,<br/>orang saleh bintang cerah.<br/>Ti-ap g''reja kaki dian ''mas,<br/>nyala terang.<br/>Tuhan dan gereja!<br/>Tuhan dan gereja!<br/>Di g''reja kaum saleh<br/>terang p''ri bintang!<br/>Haleluya! Haleluya!<br/>Genap jiwa tersembahkan.<br/>Dalam roh kita berkobar,<br/>Kristus terpancar.<br/>',NULL,65072,1);
INSERT INTO stanza VALUES('I1530','1','Bakar, bakar, siang malam t''rus,<br/>do-a dalam roh tak putus.<br/>Bagi rencana kekal-Mu roh bersatu.<br/>Lokalitas pegang teguh,<br/>gereja tunggal terwujud.<br/>Satu Tubuh dikepa-lai oleh Kristus.<br/>',NULL,65073,1);
INSERT INTO stanza VALUES('I1530','chorus','Kritus dan g''reja-Nya,<br/>Kristus dan g''reja-Nya.<br/>Itulah rea-li-tas dan hidup kita.<br/>Haleluya! Haleluya!<br/>Kita persembahkan jiwa.<br/>Bagi pembangunan Tubuh di dalam cinta.<br/>',NULL,65074,2);
INSERT INTO stanza VALUES('I1530','2','Hirup, hirup, kita hirup,<br/>mari hirup hawa segar.<br/>S''mua ber-u-bah yang<br/>usang di-ba-ru-i-lah.<br/>Hembuskan diri yang lama,<br/>hirup hayat dan ke-sa-tuan.<br/>Kita hirup Tuhan Yesus, hirup hayat.<br/>',NULL,65075,3);
INSERT INTO stanza VALUES('I1531','1','Kita berada di dalam arus!<br/>Haleluya, dalam arus!<br/>Kita berada di dalam arus!<br/>Haleluya, dalam arus!<br/>Puji Tuhan, di dalam arus!<br/>Haleluya, dalam arus!<br/>Puji Tuhan, di dalam arus!<br/>Haleluya dalam arus!<br/>',NULL,65076,1);
INSERT INTO stanza VALUES('I1532','1','Fakta alangkah a-jaib,<br/>akulah warisan-Mu!<br/>Limpah-Mu tia-da banding,<br/>namun kurang tanpaku.<br/>',NULL,65077,1);
INSERT INTO stanza VALUES('I1532','chorus','O, kesayangan-Mu,<br/>kami s''mua ini,<br/>ekspresikan limpah-Mu.<br/>Mu-lia-Mu terpuji!<br/>O, kesayangan-Mu,<br/>kami s''mua ini,<br/>ekspresikan limpah-Mu.<br/>Mu-lia-Mu terpujilah!<br/>',NULL,65078,2);
INSERT INTO stanza VALUES('I1532','2','Demi takdir indah-Mu,<br/>''neka bah''-gia ku milik.<br/>Ku Kau pilih pra waktu,<br/>tertebus, takdis kini.<br/>',NULL,65079,3);
INSERT INTO stanza VALUES('I1532','3','Roh Kudus tanda bukti,<br/>atas penebusanku.<br/>Penuh hikmat dan wahyu,<br/>jelas kenal diri-Mu.<br/>',NULL,65080,4);
INSERT INTO stanza VALUES('I1532','4','Sa-at celik mataku,<br/>ta''u harapan panggilan.<br/>Ku-at kua-sa bangkit-Mu,<br/>atas kami tertampak.<br/>',NULL,65081,5);
INSERT INTO stanza VALUES('I1532','5','Hati penuh pu-ji-an,<br/>kami s''mua: warisan-Mu.<br/>Tubuh-Mulah gereja,<br/>itu barulah cukup.<br/>',NULL,65082,6);
INSERT INTO stanza VALUES('I1533','1','Berkelana di padang,<br/>sudah cukup lama.<br/>Masuk tanah Ka-na-an,<br/>bukankah sa-at-nya?<br/>Mu-li-a di depan,<br/>harus kuat perkasa!<br/>Kita angkatan baru,<br/>wajib t''rima warisan.<br/>Demi pemu-li''an Tuhan,<br/>jangan lagi tertinggal.<br/>',NULL,65083,1);
INSERT INTO stanza VALUES('I1533','2','Kita miliki tabut,<br/>berjalan di depan.<br/>Pimpin kita menempuh,<br/>s''panjang penempuhan.<br/>Tengok, Sungai Yordan,<br/>sibak sep''ri kubu.<br/>Wajib angkatan kita<br/>putuskan arus du-nia!<br/>Maju! Marilah maju,<br/>maju dengan perkasa!<br/>',NULL,65084,2);
INSERT INTO stanza VALUES('I1533','3','Pujilah, haleluya!<br/>Kita capai Gilgal.<br/>Yang usang t''lah terkubur,<br/>daging pun terkerat.<br/>Makan hasil Ka-naan,<br/>tak heran ''kan manna.<br/>Kita tak lagi usang,<br/>hidup sandar mujizat.<br/>Makan untuk berperang,<br/>makan hasil Ka-na-an!<br/>',NULL,65085,3);
INSERT INTO stanza VALUES('I1533','4','Berdiri di pihak-Nya,<br/>Dia pasti beserta.<br/>Lakukan se-suai p''rintah,<br/>kar''na Dia Panglima!<br/>Walau tutup rapat,<br/>hai kota Yerikho.<br/>Sa-at kami berseru,<br/>ambruk runtuhlah pasti!<br/>Marilah kita pergi,<br/>merebut tiap negeri.<br/>',NULL,65086,4);
INSERT INTO stanza VALUES('I1533','5','Seluruh bumi ini,<br/>tak lain bagi g''reja!<br/>Agar Kau cepat balik,<br/>Tuhan, ku s''rahkan s''mua.<br/>Jika Kau tak pu-as,<br/>kami pun tak pu-as.<br/>Kita tergila-gila,<br/>bagi-Mu t''rus-menerus.<br/>Hingga s''mua janji Allah,<br/>tidak satu pun sia-sia.<br/>',NULL,65087,5);
INSERT INTO stanza VALUES('I1534','chorus','Api pemulihan Tuhan membara dalamku,<br/>bakar hatiku, segenap jiwaku.<br/>Tujuh Roh Tuhan memanggil<br/>pemenang mu-lia-Nya.<br/>Api t''rus membara dalamku.<br/>',NULL,65088,1);
INSERT INTO stanza VALUES('I1534','1','Lihat dalam puncak visi-Nya,<br/>k''ra-ja-an-Nya ''kan tiba.<br/>Buka hati biar Roh membakar<br/>hatimu ''tuk kehendak-Nya.<br/>',NULL,65089,2);
INSERT INTO stanza VALUES('I1534','2','Kesampingkan s''galanya bagi<br/>panggilan nan mu-li-a.<br/>Tanpa gentar, d''ngan roh menuntut,<br/>maju d''ngan hati membara.<br/>',NULL,65090,3);
INSERT INTO stanza VALUES('I1534','3','Pe-mu-li''an-Nya me-luas di bumi,<br/>b''ri-kan se-g''nap jiwamu.<br/>S''lalu padu dengan gerak-Nya,<br/>dengan hati t''rus membara.<br/>',NULL,65091,4);
INSERT INTO stanza VALUES('I1534','4','Di tiap kota maju serentak,<br/>bagi kaki dian mu-lia.<br/>Dalam kasih siap-kan mem-p''lai-Nya,<br/>sambut Dia - m''raja bersama.<br/>',NULL,65092,5);
INSERT INTO stanza VALUES('I1534','5','S''lalu esa, s''lalu sehati,<br/>bangun Tubuh mu-lia-Nya.<br/>Yerusalem Baru rampunglah,<br/>pancarkan ke-mu-lia-an-Nya.<br/>',NULL,65093,6);
INSERT INTO stanza VALUES('I1534','6','''Nilah kami, sambut panggilan<br/>ekonomi mulia-Mu.<br/>Latih kami, bangun bersama:<br/>Full Time Training di Jakarta.<br/>',NULL,65094,7);
INSERT INTO stanza VALUES('I1535','1','Hasrat Allah di semesta<br/>ada pada manu-sia.<br/>Tuhan menjadi Roh itu<br/>ba-ur esa dengannya.<br/>Kami girang dapat<br/>ber-ba-gi-an ekonomi-Nya.<br/>Ber-ba-ur - jalannya!<br/>',NULL,65095,1);
INSERT INTO stanza VALUES('I1535','chorus','Ba-ur, ba-ur, haleluya!<br/>Ba-ur, ba-ur, haleluya!<br/>Ba-ur, ba-ur, haleluya!<br/>Ber-ba-ur - jalannya.<br/>',NULL,65096,2);
INSERT INTO stanza VALUES('I1535','2','Di pusat diri kita,<br/>lam-pau-i ba-gi-an jiwa.<br/>Ada ba-gian yang Tuhan<br/>cipta untuk di-i-si-Nya.<br/>Dia memenuhi dengan<br/>aliran dan lu-ap-an-Nya.<br/>Ber-ba-ur - jalannya.<br/>',NULL,65097,3);
INSERT INTO stanza VALUES('I1535','3','Kini dalam pemulihan,<br/>girang dapat jalannya.<br/>Alami Allah Tritunggal<br/>serta hidup oleh-Nya.<br/>Balik ke roh pem-ba-ur-an<br/>dan tinggal dalamnya.<br/>Ber-ba-ur - jalannya.<br/>',NULL,65098,4);
INSERT INTO stanza VALUES('I1535','4','Di tengah tujuh kaki dian,<br/>lihat Anak Ma-nu-sia.<br/>Mata bersinar, kaki ''bara,<br/>bagi pe-mu-li''an-Nya.<br/>Hasrat Allah Dia genapkan -<br/>sa-tu-an yang korporat.<br/>Ber-ba-ur - jalannya.<br/>',NULL,65099,5);
INSERT INTO stanza VALUES('I1535','5','S''mua yang kita lakukan<br/>dalam kehidupan kita.<br/>Perlu ber-ba-ur lebih dalam<br/>''tuk dapatkan Tuhan.<br/>Tuhan, ku s''rahkan seluruh,<br/>masuk dalam pem-baur-an.<br/>Ber-ba-ur - jalannya.<br/>',NULL,65100,6);
INSERT INTO stanza VALUES('I1535','6','Yerusalem Baru tertampil<br/>dari hidup kita.<br/>Pem-ba-ur-an ilahi -<br/>insani rampung sempurna.<br/>Sukacita sungguh,<br/>ber-ba-gian secara korporat.<br/>Ber-ba-ur - jalannya.<br/>',NULL,65101,7);
INSERT INTO stanza VALUES('I1601','1','Hayat Allah, insan perlu;<br/>pembangunan tu-ju-an Allah.<br/>Kristus menang, Iblis malu;<br/>rencana-Nya seg''ra tergenap!<br/>',NULL,65102,1);
INSERT INTO stanza VALUES('I1601','chorus','Bangunkan ku Tuhan!<br/>Ku tak mau jalan sendiri.<br/>Hidup di roh,<br/>''tiasa do-a dan baca Aminlah!<br/>',NULL,65103,2);
INSERT INTO stanza VALUES('I1601','2','Tuhan hayat, penuh rahmat,<br/>k''limpahan-Nya, suplai-an kita.<br/>Untuk bangun, perlu hayat;<br/>hayat, bangun, saling menunjang.<br/>',NULL,65104,3);
INSERT INTO stanza VALUES('I1601','3','Kita bangkit, serah diri;<br/>sambil bangun, pegang senjata.<br/>Singkir debat, basmi ego;<br/>pedang firman menusuk musuh.<br/>',NULL,65105,4);
INSERT INTO stanza VALUES('I1601','4','Ada jalan ''nuju<br/>k''limpahan hayat Tuhan.<br/>Pertumbuhan hayat,<br/>bawa pembangunan.<br/>Asal buka diri t''radap Tuhan,<br/>dalam roh.<br/>Tiap hari doa baca,<br/>doa baca.<br/>',NULL,65106,5);
INSERT INTO stanza VALUES('I1602','1','Kami nampak murad mu-lia-Mu,<br/>atas bumi bangun rumah.<br/>Kami do-a,"Dapatkan kami,<br/>bangun kami seturut-Mu!"<br/>Jawaban-Mu cepat dan tegas,<br/>"Harus tahu, ''tuk rumah-Ku.<br/>Hayat jiwa harus disangkal,<br/>harus rebah atas mezbah."<br/>',NULL,65107,1);
INSERT INTO stanza VALUES('I1602','2','Dengar takhta yang sangat se-rius.<br/>Menakutkan, tak terhindar.<br/>Tapi kami s''lalu dekat-Mu.<br/>S''gala harga tak peduli.<br/>''Tuk rumah-Mu, ku rela mati.<br/>Biar Kau jadi segalaku.<br/>Kaulah suplai sempurna kami.<br/>Kau sarana bangun kami.<br/>',NULL,65108,2);
INSERT INTO stanza VALUES('I1602','3','''Tuk murad-Mu, ku serah diri.<br/>Entah apa makna s''jati.<br/>Hayat se-mua, dipersembahkan.<br/>Jadi kurban, tu-ang, hilang.<br/>Atas mezbah, Tuhan, bakarlah.<br/>Jadi abu, habis se-mua.<br/>Biar harum-Mu, s''merbak terputus.<br/>Dalam pu-jian t''rus bagi-Mu.<br/>',NULL,65109,3);
INSERT INTO stanza VALUES('I1603','1','Da-ud angkat sumpah,<br/>tak akan masuk kemah.<br/>Tak baring di ranjang,<br/>matapun takkan pejam.<br/>Sam-pai Tuhan mendapatkan<br/>tempat per-hen-ti-an.<br/>Sang Alkadir menantikan<br/>tempat bersemayam.<br/>',NULL,65110,1);
INSERT INTO stanza VALUES('I1603','2','Kita sungguh buta,<br/>mengurus awak saja.<br/>Ba-it Allah kersang;<br/>o, utamakan Tuhan!<br/>Na-ik  gunung, cari bahan,<br/>bangun Ba-it Allah.<br/>Jangan bilang,"Besok saja",<br/>hendaklah sekarang!<br/>',NULL,65111,2);
INSERT INTO stanza VALUES('I1603','3','Hentaklah antero,<br/>biar serempak membangun.<br/>Sep''ri hari Da-ud<br/>menjawab panggilan-Nya.<br/>Sehati, jalin tersusun,<br/>amanat teragung.<br/>Gemar kita, perkenan-Nya,<br/>ya, kita membangun!<br/>',NULL,65112,3);
INSERT INTO stanza VALUES('I1603','4','Bagi g''reja Tuhan,<br/>lupakan yang la-in-nya.<br/>Sembahkan segala,<br/>''tuk rumah-Nya semata!<br/>T''radap gereja terbina,<br/>alam maut tak daya.<br/>Bangun kita, tanpa lambat,<br/>balik-Nya biar cepat.<br/>T''radap gereja terbina,<br/>alam maut tak daya.<br/>Bangun kita, tanpa lambat,<br/>balik-Nya biar cepat.<br/>',NULL,65113,4);
INSERT INTO stanza VALUES('I1604','1','Bumi di-am tenang,<br/>namun bagi kesak-sian-Nya,<br/>Allah ri-sau cemas.<br/>Dia sungguh gelisah!<br/>Hai, saudara!<br/>Jangan terus pelesiran,<br/>hanya tahu awak,<br/>kita ''kan ter-bu-ang.<br/>',NULL,65114,1);
INSERT INTO stanza VALUES('I1604','2','Sa-at telah tiba,<br/>Allah ma-u pilih kita.<br/>Bangun g''reja s''mesta,<br/>sekarang waktunya!<br/>Hai, saudara!<br/>Mari pegang kesempatan.<br/>Kerja bersama Dia,<br/>janganlah lalaikan!<br/>',NULL,65115,2);
INSERT INTO stanza VALUES('I1604','3','Dengar, janji Tuhan;<br/>Ku balik ke Yerusalem,<br/>tinggal bersamamu,<br/>kau ''kan makmur, s''marak.<br/>Kota ini,<br/>''kan tak bertembok p''ri desa.<br/>Kar''na kembang bi-ak,<br/>hingga tak cukup muat.<br/>',NULL,65116,3);
INSERT INTO stanza VALUES('I1604','4','Allah mulai garap,<br/>membangkitkan su-a-sa-na.<br/>Bangsa-bangsa guncang,<br/>g''reja angkat pandang.<br/>Umumkanlah,<br/>bumi dan alam semesta.<br/>Se-mua milik Tuhan,<br/>Iblis tia-da ba-gian.<br/>',NULL,65117,4);
INSERT INTO stanza VALUES('I1604','5','Ada firman Tuhan,<br/>bukan sandar ku-at du-nia.<br/>Atau pun talenta;<br/>tetapi Roh Tuhan.<br/>Wahai, gunung,<br/>jangan coba-coba halang.<br/>Kau terhitung apa?<br/>Datarlah akhirnya!<br/>',NULL,65118,5);
INSERT INTO stanza VALUES('I1604','6','Tujuh mata p''riksa,<br/>tali ukur kita pegang.<br/>Allah amat suka!<br/>La-in tak Dia tanggap!<br/>Mu-lia! Mu-lia!<br/>Dasar Ba-it sudah letak.<br/>Ba-it seg''ra rampung,<br/>lewat tangan kita.<br/>',NULL,65119,6);
INSERT INTO stanza VALUES('I1605','1','Azali ku terpilih,<br/>sekarang ku terpanggil.<br/>Bagi bangunan-Nya<br/>ku tersisih!<br/>Demilah darah adi,<br/>keputra-an ku p''roleh.<br/>Bagi bangunan-Nya<br/>ku terlahir.<br/>',NULL,65120,1);
INSERT INTO stanza VALUES('I1605','chorus','Bagilah bangunan!<br/>Bu-ang pendapat dan gemar diri!<br/>Amin Roh dan gereja,<br/>amin firman nan murni.<br/>Kelola Tuhan bagi bangunan.<br/>',NULL,65121,2);
INSERT INTO stanza VALUES('I1605','2','Ka-um terpanggil layak<br/>ikut urapan minyak.<br/>Rendah hati pula<br/>ramah tamah.<br/>Perlu sikap toleran,<br/>perlu sikap b''ri ma-af.<br/>Bagi pembangunan-Nya,<br/>roh esa!<br/>',NULL,65122,3);
INSERT INTO stanza VALUES('I1605','3','Rasul, nabi, dib''ri-Nya,<br/>jadi dasar, sandaran.<br/>Seluruh ka-um<br/>saleh terbina.<br/>Tumbuh lekat Kepala,<br/>sendi lekat selaras.<br/>Masing-masing tu-nai-kan<br/>fungsinya!<br/>',NULL,65123,4);
INSERT INTO stanza VALUES('I1605','4','Jangan kanak-kanakan,<br/>terombang-ambing b''laka.<br/>Dalam kasih berpegang<br/>rea-li-tas.<br/>Berpadu seluruh-Nya,<br/>hingga satu pun esa.<br/>Koor-dinasi bagi<br/>bangunan-Nya!<br/>',NULL,65124,5);
INSERT INTO stanza VALUES('I1606','1','Membangun Ba-it Allah,<br/>kinilah sa-atnya.<br/>Se-mu-a g''reja lokal,<br/>terbangun sempurna.<br/>Bukan ''tuk diri m''lulu,<br/>m''lainkan rumah Allah.<br/>Mari kita segera,<br/>bangun g''reja!<br/>',NULL,65125,1);
INSERT INTO stanza VALUES('I1606','chorus','Ku-at! Tegap!<br/>Serentak membangun!<br/>Hadir Allah pada kita,<br/>Ba-it penuh mu-lia.<br/>Ku-at! Tegap!<br/>Sehati bekerja.<br/>Hingga se-mua bangsa nampak,<br/>mu-lia rumah Allah.<br/>',NULL,65126,2);
INSERT INTO stanza VALUES('I1606','2','Dengar! Allah bersabda,<br/>"P''riksa ke-la-kuan-mu.<br/>Tabur banyak, tuai s''dikit,<br/>kar''na kurang syukur.<br/>Lekaslah na-ik gunung,<br/>cari bahan bangun.<br/>Sehati bangun rumah-Ku<br/>nan mu-lia."<br/>',NULL,65127,3);
INSERT INTO stanza VALUES('I1606','3','Ka-lian imam terpanggil,<br/>ta-at-i-lah Allah.<br/>Tak pedulikan du-nia,<br/>asal Allah serta.<br/>Dengan roh yang berkobar,<br/>kita kerja kompak.<br/>Moga tia-da se-o-rang<br/>pun yang lengah.<br/>',NULL,65128,4);
INSERT INTO stanza VALUES('I1606','4','Firman Allah semesta,<br/>"Ba-it-Ku p''nuh mu-lia."<br/>Dam-ba-an se-mua bangsa,<br/>segera terwujud.<br/>Mu-li-a rumah ini,<br/>lam-pau-i yang lalu.<br/>Kita nikmat bersama,<br/>girang sungguh!<br/>',NULL,65129,5);
INSERT INTO stanza VALUES('I1607','1','Haleluya, batu hidup,<br/>untuk bangun Tubuh!<br/>Ku berkata,"Kau-lah Kristus,"<br/>Di-a pun berkata,<br/>"Kau-lah se-buah batu,"<br/>Haleluya, batu hidup!<br/>',NULL,65130,1);
INSERT INTO stanza VALUES('I1608','1','Batu hidup, sama bangun,<br/>tembok di Yerusalem.<br/>Kami tak lagi dihina,<br/>kota tersambung rapat.<br/>',NULL,65131,1);
INSERT INTO stanza VALUES('I1608','chorus','Haleluya, di dalam-Nya<br/>kami se-mua terbangun.<br/>Menjadi ke-diam-an Allah,<br/>ekspresikan mu-lia-Nya.<br/>',NULL,65132,2);
INSERT INTO stanza VALUES('I1608','2','Terjun ke dalam arus-Nya,<br/>hasilkan batu mu-lia.<br/>Tidak lagi sen-di-ri-an,<br/>terbangunkan bersama.<br/>',NULL,65133,3);
INSERT INTO stanza VALUES('I1608','3','Roh kami ber-ba-ur esa,<br/>baru nyata bangunan.<br/>Tak bicara e-mo-sio-nal,<br/>tapi kontak antar roh.<br/>',NULL,65134,4);
INSERT INTO stanza VALUES('I1608','4','Bukan slogan, teo-ri saja,<br/>tapi untuk rea-li-tas.<br/>Sama nikmat, koor-di-na-si,<br/>tidak kendur bekerja.<br/>',NULL,65135,5);
INSERT INTO stanza VALUES('I1608','5','Pembangunan di dalam roh,<br/>a-ir hayat mengalir.<br/>Seperti roda berputar,<br/>ke-em-pat makhluk hidup.<br/>',NULL,65136,6);
INSERT INTO stanza VALUES('I1608','6','Haleluya, sungguh girang,<br/>ku anggota Tubuh-Nya.<br/>Lepas diri yang tertutup,<br/>masuk kelola mu-lia.<br/>',NULL,65137,7);
INSERT INTO stanza VALUES('I1608','chorus','Tuhan, ubah pikiranku,<br/>menjadi milik surga.<br/>Hidup, kerja, dan tuturku,<br/>mengekspresikan Allah.<br/>',NULL,65138,8);
INSERT INTO stanza VALUES('I1609','1','Ba-ur esa,<br/>roh ber-ba-ur esa!<br/>Ba-ur esa,<br/>roh ber-ba-ur esa!<br/>K''luar dari ego,<br/>masuk dalam roh,<br/>o, roh ber-ba-ur,<br/>ber-ba-ur esa.<br/>Mari ba-ur!<br/>Hai kaum saleh!<br/>Dalam roh ber-ba-ur!<br/>(Mu-lia, haleluya!)<br/>Sekutu, layan-i,<br/>dalam roh ber-ba-ur,<br/>ba-ur, ber-ba-ur-lah!<br/>',NULL,65139,1);
INSERT INTO stanza VALUES('I1609','2','Dibangunlah!<br/>Mari dibangunlah!<br/>Dibangunlah!<br/>Mari dibangunlah!<br/>Bu-ang angkuh, degil,<br/>dan s''mua sekatan.<br/>O, saling terbangun<br/>d''ngan selaras.<br/>Bangun s''rentak!<br/>Warga surga!<br/>Bangun dalam cinta,<br/>(Mu-lia, haleluya!)<br/>Saling beranggota,<br/>saling ber-ta-at-an,<br/>bangun dalam cinta.<br/>',NULL,65140,2);
INSERT INTO stanza VALUES('I1610','1','Darah adi, menebuslah kita.<br/>Darah adi, menebuslah kita.<br/>Darah adi menebuslah kita.<br/>Mu-lia, mu-lia tertampak!<br/>Dosa kita terampunkan,<br/>terampunkan!<br/>',NULL,65141,1);
INSERT INTO stanza VALUES('I1610','2','Kita ini imam pi-li''an Tuhan.<br/>Kita ini imam pi-li''an Tuhan.<br/>Kita ini imam pi-li''an Tuhan.<br/>Mu-lia, mu-lia tertampak!<br/>Melayani depan Allah, depan Allah!<br/>',NULL,65142,2);
INSERT INTO stanza VALUES('I1610','3','Dalam Kristus, kita bersaudara.<br/>Dalam Kristus, kita bersaudara.<br/>Dalam Kristus, kita bersaudara.<br/>Mu-lia, mu-lia tertampak!<br/>Maju dalam kasih Tuhan, maju s''rempak!<br/>',NULL,65143,3);
INSERT INTO stanza VALUES('I1610','4','Dalam Kristus, kita bersaudari.<br/>Dalam Kristus, kita bersaudari.<br/>Dalam Kristus, kita bersaudari.<br/>Mu-lia, mu-lia tertampak!<br/>Maju dalam kasih Tuhan, maju s''rempak!<br/>',NULL,65144,4);
INSERT INTO stanza VALUES('I1610','5','Kita saling berkasih-kasihan.<br/>Kita saling berkasih-kasihan.<br/>Kita saling berkasih-kasihan.<br/>Mu-lia, mu-lia tertampak!<br/>Fi-la-del-fia di sinilah, di sinilah!<br/>',NULL,65145,5);
INSERT INTO stanza VALUES('I1610','6','Lokalitas, kita pegang tegap.<br/>Lokalitas, kita pegang tegap.<br/>Lokalitas, kita pegang tegap.<br/>Mu-lia, mu-lia tertampak!<br/>Pe-mu-li''an-Nya terwujudlah, terwujudlah.<br/>',NULL,65146,6);
INSERT INTO stanza VALUES('I1611','1','Himpun sidang, kamilah Tubuh Tuhan,<br/>Tubuh esa, anggota ''nekalah.<br/>Demi hayat, jadi anggota Tubuh;<br/>dalam hayat, kami mutlak satu<br/>',NULL,65147,1);
INSERT INTO stanza VALUES('I1611','chorus','Jagat raya Tubuh hanya satu,<br/>di bumi pun wujud satu.<br/>Utuh tunggal, atas tum-puan lokal,<br/>biar s''mua orang pada paham.<br/>',NULL,65148,2);
INSERT INTO stanza VALUES('I1611','2','Ibarat tubuh-Mu-lah roti ini,<br/>t''lah terbelah, biar kami nikmati.<br/>De-mi-ki-an, Dikau kami miliki,<br/>menyaksikan esa nan sejati.<br/>',NULL,65149,3);
INSERT INTO stanza VALUES('I1611','3','Roti, cawan, masing-masing se-bu-ah,<br/>menyatakan kami pun setunggal.<br/>Mewadahi kasih ka-ru-nia Tuhan,<br/>tanpa bantah,"Amin, kita esa!"<br/>',NULL,65150,4);
INSERT INTO stanza VALUES('I1611','4','Sia-pa saja tak mampu menceraikan,<br/>ke-sa-tu-an yang berasal Kristus.<br/>Roti, cawan, kami makan bersama,<br/>tampak nyata ke-e-sa-an Tubuh.<br/>',NULL,65151,5);
INSERT INTO stanza VALUES('I1611','5','Ri-ang, bah''-gia dan sedap esa ini,<br/>yakni Tuhan pu-as, senang pasti!<br/>Nyaman marem, laksana menikmati,<br/>hari nikah yang sangat menarik.<br/>',NULL,65152,6);
INSERT INTO stanza VALUES('I1612','1','Kita telah nampak<br/>g''reja dalam ke-e-sa-an;<br/>Saksi, nyanyi, syukur puji,<br/>melekat selaras.<br/>G''reja lokal,<br/>mempe-lai kesayangan tunggal-Nya.<br/>Seru Tuhan,<br/>kita per-o-leh Kristus kian banyak.<br/>',NULL,65153,1);
INSERT INTO stanza VALUES('I1612','chorus','Di-a-lah kasih,<br/>kita ti-ap hari,<br/>menikmat-i kasih,<br/>yang sejati.<br/>',NULL,65154,2);
INSERT INTO stanza VALUES('I1612','2','Nikmat Kristus, dalam g''reja,<br/>sungguh pu-as lega.<br/>Roh dan g''reja itu<br/>pemulihan sebenarnya.<br/>Seru Tuhan,<br/>kita hirup segala limpah-Nya.<br/>Resap jenuh antero-Nya,<br/>roh lantas le-lua-sa.<br/>',NULL,65155,3);
INSERT INTO stanza VALUES('I1612','3','Arus kasih, dari takhta,<br/>menyegar-beningkan.<br/>Mesra, mu-lia, tak kepalang,<br/>kita nikmati s''mua.<br/>Lekat padu, kukuh padat,<br/>g''nap kita terbina.<br/>Mari, kita dalam<br/>g''reja dewasa bersama!<br/>',NULL,65156,4);
INSERT INTO stanza VALUES('I1613','1','Dalam Tuhan bersatu,<br/>dalam Roh bersatu,<br/>dalam Tuhan bersatu,<br/>dalam Roh bersatu,<br/>pujilah Tuhan kar''na Tuhan kita bersatu.<br/>',NULL,65157,1);
INSERT INTO stanza VALUES('I1613','chorus','(suara laki-laki)<br/>Dalam Roh selamanya bersatu!<br/>Bersatu!<br/>(Suara perempuan)<br/>Dalam Roh selamanya bersatu.<br/>Bersatu!<br/>(Semua menyanyi)<br/>Pujilah Tuhan, kar''na Tuhan,<br/>kita bersatu! (bersatu)<br/>',NULL,65158,2);
INSERT INTO stanza VALUES('I1613','2','Kita s''mua dibangunkan<br/>dalam kasih Tuhan.<br/>Kita s''mua dibangunkan<br/>dalam kasih Tuhan.<br/>Ki-an hari ki-an<br/>menyatakan mu-li-a-Nya.<br/>',NULL,65159,3);
INSERT INTO stanza VALUES('I1613','3','Kini Tuhan Roh itu,<br/>Roh-Nya dalam rohku.<br/>Kini Tuhan Roh itu,<br/>Roh-Nya dalam rohku.<br/>Di dalam Roh kita<br/>dibangunkan jadi satu.<br/>',NULL,65160,4);
INSERT INTO stanza VALUES('I1613','4','Pu-ji-an bagi Bapa<br/>sumber hidup kekal.<br/>Pu-ji-an bagi Putra<br/>peredaran hayat.<br/>Pu-ji-an bagi Roh<br/>Kudus yang resapi kita.<br/>',NULL,65161,5);
INSERT INTO stanza VALUES('I1613','chorus','Puji Allah Tritunggal<br/>bersatu abadi!<br/>Puji Allah Tritunggal<br/>bersatu abadi!<br/>Kota Kudus muncul,<br/>Allah ma-nu-sia bersatu.<br/>',NULL,65162,6);
INSERT INTO stanza VALUES('I1614','chorus','Masuk dalam Pu-tra Allah,<br/>demi Roh-Nya kita esa.<br/>Masuk dalam Pu-tra Allah,<br/>demi Roh-Nya kita esa.<br/>O, kita adalah esa!<br/>O, kita adalah esa!<br/>O, kita adalah esa!<br/>Ya, esa!<br/>Du-nia cari per-da-mai-an,<br/>deru perang takkan gencat.<br/>G''lisah resah, takkan reda,<br/>Tuhanlah jalannya.<br/>Tanpa Dia menderita!<br/>',NULL,65163,1);
INSERT INTO stanza VALUES('I1614','1','Dalam kasih tinggal sama,<br/>padu esa terpulihlah.<br/>Tanpa per-be-da-an apa,<br/>seperti Bapa dan Putra-Nya, esa kita!<br/>',NULL,65164,2);
INSERT INTO stanza VALUES('I1614','2','Ka-um saleh, rukun, tent''ram;<br/>memang elok, memang indah!<br/>Penuh minyak, diris, segar,<br/>hayat kekal-Nya cukup kita nikmat s''lama!<br/>',NULL,65165,3);
INSERT INTO stanza VALUES('I1615','1','Allah ada ke-per-luan,<br/>tahukah ka-li-an?<br/>Allah perlu ke-diam-an,<br/>teduh nyaman!<br/>Jika kita bersatu,<br/>terbangunlah rumah-Nya.<br/>Allah ayem pu-as,<br/>kita pun demi-kian.<br/>',NULL,65166,1);
INSERT INTO stanza VALUES('I1615','2','Bila kita terpecah,<br/>wujudkah rumah-Nya?<br/>Yang diperkenan Tuhan,<br/>se-ia, s''kata.<br/>Letakkan segala hal<br/>yang m''rusak ke-sa-tu-an.<br/>De-mi-kian datangkan<br/>ke-sa-tu-an indah.<br/>',NULL,65167,2);
INSERT INTO stanza VALUES('I1615','3','Hidup dalam ke-sa-tuan,<br/>tampil saling kasih.<br/>Nyata di rumah Allah,<br/>kasih ini.<br/>Kita kecap niscaya:<br/>Limpah saleh berabad.<br/>Limpah rumah Allah,<br/>limpah rumah Allah.<br/>',NULL,65168,3);
INSERT INTO stanza VALUES('I1615','4','Apa kau untuk g''reja?<br/>Tunjukkan sekarang!<br/>Mau-kah kau s''rahkan diri?<br/>''Tuk pe-mu-li''an?<br/>Mau-kah t''rima tantangan,<br/>pikul amanat g''reja?<br/>Mutlak untuk Tuhan,<br/>mutlak untuk Tuhan.<br/>',NULL,65169,4);
INSERT INTO stanza VALUES('I1615','5','Dari zaman ke zaman,<br/>Tuhan pilih kita.<br/>Generasi yang mu-lia,<br/>K''ra-jaan nyata.<br/>Kita tak dapat b''renti,<br/>kar''na puas ''kan kea-da-an<br/>Kita tetap maju,<br/>kita tetap maju.<br/>',NULL,65170,5);
INSERT INTO stanza VALUES('I1616','1','Dulu kita mati di dosa,<br/>hidup di du-nia, b''rantak-an.<br/>Allah bangkitkan kita s''rempak,<br/>sama Kristus terlantik duduk takhta.<br/>',NULL,65171,1);
INSERT INTO stanza VALUES('I1616','chorus','Yesus himpun kita se-mu-a,<br/>tengoklah, kaum saleh selaras!<br/>Kasih Tuhan mempersatukan,<br/>terca-pai perawakan lu-ap Tuhan.<br/>',NULL,65172,2);
INSERT INTO stanza VALUES('I1616','2','Ka-um saleh kompak serempak,<br/>cinta Kristus terpahamkan.<br/>Lu-as, besarnya tak terduga,<br/>namun limpah Allah ''tia-sa ternikmat.<br/>',NULL,65173,3);
INSERT INTO stanza VALUES('I1616','3','Berzaman tertutup murad-Nya,<br/>kini telah tersingkapkan.<br/>Kristus, g''reja, t''lah kita nampak,<br/>menjadikan Iblis malu, terhina!<br/>',NULL,65174,4);
INSERT INTO stanza VALUES('I1616','4','Mohon Bapa, kita ber-do-a,<br/>ku-at-kan insan ba-ti-niah.<br/>Biar dalam kita Kau semayam,<br/>dalam kasih-Mu berakar, beralas.<br/>',NULL,65175,5);
INSERT INTO stanza VALUES('I1616','5','Dalam Tubuh padu serasi,<br/>suplai Kristus urat sendi.<br/>Masing-masing tunaikan fungsi,<br/>Tubuh terbina dan tumbuh tak henti.<br/>',NULL,65176,6);
INSERT INTO stanza VALUES('I1616','6','Esa mutlak kita sekarang,<br/>insan baru tertampilkan.<br/>Dalam Kristus, dalam gereja,<br/>mu-lia bagi Allah sampai s''lamanya!<br/>',NULL,65177,7);
INSERT INTO stanza VALUES('I1617','1','Kita berhimpun, nik-mat-i ja-mu-an-Nya;<br/>Makan, minum Tuhan, wujudkan e-sa.<br/>A-lam-i hadir-Nya, persaksikan cinta,<br/>Demi-ki-an ini menarik berkat-Nya.<br/>',NULL,65178,1);
INSERT INTO stanza VALUES('I1617','2','Roti yang terbentang tandakan tubuh-Nya,<br/>Makan bersama mewujudkan esa.<br/>Roti seketul nyatakan satu Tubuh;<br/>Persaksikan kita satu dalam Tuhan.<br/>',NULL,65179,2);
INSERT INTO stanza VALUES('I1617','3','Minum cawan berkat, per-jan-ji-an Tuhan;<br/>S''kutu bersama berkat kha-siat darah.<br/>Menyambut umat saleh yang t''lah tertebus;<br/>Syukur depan Allah, atas s''mua berkat-Nya.<br/>',NULL,65180,3);
INSERT INTO stanza VALUES('I1617','4','Kata apalagi, ''cua-li "Haleluya!"<br/>Rea-li-tas ini t''lah Tuhan berikan.<br/>Gunakan darah-Nya, nikmati tubuh-Nya,<br/>Jadi g''reja mu-lia yang Di-a idamkan.<br/>',NULL,65181,4);
INSERT INTO stanza VALUES('I1618','1','Dalam rumah Allah,<br/>sama terpanggil,<br/>kar''na darah-Nya,<br/>menjadi kudus.<br/>Lahir kembali,<br/>satu d''ngan Allah,<br/>jadi anak-Nya,<br/>pun warisan-Nya.<br/>Bebas, kenyang,<br/>sabat, puji,<br/>sorak ''tia-sa,<br/>o, haleluya,<br/>sama terpanggil.<br/>',NULL,65182,1);
INSERT INTO stanza VALUES('I1618','2','Di dalam Roh Kudus,<br/>sama sekutu,<br/>bu-ang te-o-ri,<br/>singkir yang basi.<br/>Tak mau liturgi,<br/>tak pandang huruf,<br/>hayat yang baru,<br/>air hayat ''ngalir.<br/>Bukan agamawi,<br/>kejar re-a-li-tas,<br/>o, haleluya,<br/>s''kutu bersama.<br/>',NULL,65183,2);
INSERT INTO stanza VALUES('I1618','3','Di dalam gereja,<br/>sama layani,<br/>buang racun jahat,<br/>makan rohani.<br/>Menghadap Tuhan,<br/>p''ri batu hidup,<br/>jadi istana,<br/>imam rajani.<br/>Demi Yesus Kristus,<br/>s''rah kurban rohani,<br/>o, haleluya,<br/>sama layani.<br/>',NULL,65184,3);
INSERT INTO stanza VALUES('I1618','4','Dalam kasih Tuhan,<br/>lekat bersama,<br/>t''rima d''ngan kasih,<br/>kontak d''ngan damai.<br/>Satu gembira,<br/>s''mua sukacita,<br/>se-o-rang sedih,<br/>se-mua menangis.<br/>Se-mua saling bantu,<br/>sehati sepikir,<br/>o, haleluya,<br/>lekat bersama.<br/>',NULL,65185,4);
INSERT INTO stanza VALUES('I1618','5','Dalam kemah Tuhan,<br/>perang bersama,<br/>pegang tum-pu-an,<br/>berdiri tegap.<br/>Pakai s''ragam-Nya,<br/>pegang senjata,<br/>demi nama-Nya,<br/>sandar Kepala.<br/>''Ti-a-sa ber-do-a,<br/>singkir tipu jahat,<br/>o, haleluya,<br/>perang bersama.<br/>',NULL,65186,5);
INSERT INTO stanza VALUES('I1618','6','Kita dalam mu-lia,<br/>bersama Tuhan,<br/>bu-ang yang lalu,<br/>alam serasi.<br/>Dahaga lerai,<br/>lapar ter-pu-as,<br/>dua mempelai,<br/>saling menyayang.<br/>Allah-insan esa,<br/>terang, girang, lu-ap,<br/>o, haleluya,<br/>bersama Tuhan.<br/>',NULL,65187,6);
INSERT INTO stanza VALUES('I1619','1','Mengenal-Mu s''bagai Tubuh,<br/>itu keperlu-an-ku.<br/>Tiap anggota pancarkan-Mu,<br/>itu do-a, dambaku.<br/>Tak hanya ta''u Kau Kepala,<br/>secara individu.<br/>Tapi ku ingin nampak<br/>Kau menjadi Tubuh Kristus.<br/>',NULL,65188,1);
INSERT INTO stanza VALUES('I1619','2','Tahunan kami mencari,<br/>dambakan re-a-li-tas.<br/>Cari di luar, lacak batin,<br/>harap jumpa diri-Mu.<br/>Kini nampak Kau di surga,<br/>ternyata dalam Tubuh.<br/>Kristus yang di-am di batin,<br/>ternyata s''bagai Tubuh.<br/>',NULL,65189,2);
INSERT INTO stanza VALUES('I1619','3','Mudah sangat ku tersesat<br/>oleh angan-anganku.<br/>Mudah amat mencari-Mu,<br/>tapi dapat yang semu.<br/>Aku perlu mencari-Mu<br/>di dalam anggota-Mu.<br/>Allah kekal yang di batin<br/>ternyata dalam daging.<br/>',NULL,65190,3);
INSERT INTO stanza VALUES('I1619','4','Batasilah aku, Tuhan,<br/>palingkan ke Tubuh-Mu.<br/>Bukan cari terang surga,<br/>tapi p''ra-sa-an Tubuh.<br/>Moga kami jadi batu,<br/>bukan lempung yang rapuh.<br/>ati terisi hasrat-Mu,<br/>memamerkan diri-Mu.<br/>',NULL,65191,4);
INSERT INTO stanza VALUES('I1701','1','Dengar sua-ra pengembara,<br/>kisah p''ngalamannya.<br/>Pada hri-hari lam-pau,<br/>dia tak pu-as s''lalu.<br/>',NULL,65192,1);
INSERT INTO stanza VALUES('I1701','chorus','Puji-Hu! Puji-HU! Puji-Hu!<br/>Haleluya! Haleluya, puji-Hu! Puji-Hu!<br/>Kita takkan mengulang!<br/>(1-3)<br/>',NULL,65193,2);
INSERT INTO stanza VALUES('I1701','2','Berkelana di du-ni-a,<br/>cari senang pu-as.<br/>Namun tubuh, hati, dan roh,<br/>tetap duka, kosong.<br/>',NULL,65194,3);
INSERT INTO stanza VALUES('I1701','3','Si-ang malam banting tulang,<br/>membangun di pasir.<br/>Puji Tuhan! Dia membongkar,<br/>b''ri yang lebih indah.<br/>',NULL,65195,4);
INSERT INTO stanza VALUES('I1701','4','Kini dapat g''reja lokal,<br/>jadi anggota riang.<br/>Hidup berk''lana berakhir,<br/>teduh di rumah-Nya.<br/>',NULL,65196,5);
INSERT INTO stanza VALUES('I1701','chorus','Puji-Hu! Puji-HU! Puji-Hu!<br/>Haleluya! Haleluya, puji-Hu!<br/>Puji-Hu! Ku hidup di g''reja.<br/>(4-7)<br/>',NULL,65197,6);
INSERT INTO stanza VALUES('I1701','5','Dulu aku pencil sunyi,<br/>hidup dalam diri.<br/>Kini dengan ka-um kudus,<br/>dalam-Nya terbangun.<br/>',NULL,65198,7);
INSERT INTO stanza VALUES('I1701','6','Ku tertarik pada g''reja,<br/>nikmat s''kutu mesra.<br/>Dalam sua-sa-na apa pun,<br/>t''rima Tuhan s''lalu.<br/>',NULL,65199,8);
INSERT INTO stanza VALUES('I1701','7','K''lana henti, diam di g''reja,<br/>hidup di murad-Nya.<br/>Ra-ha-si-a sukacita:<br/>nikmat per-hen-tian-Nya.<br/>',NULL,65200,9);
INSERT INTO stanza VALUES('I1702','1','M''ngapa kau sering tak gembira,<br/>tiap hari datar kurang ri-ang?<br/>Apakah kau b''lenggu dirimu,<br/>lingkungan hidup, sempit, sesak.<br/>Hingga merasa gamang?<br/>(Oh ...!)<br/>A-tau kau sedang cari yang lain,<br/>lupakan Tuhan Sang Mustika?<br/>Kar''na-nya kau s''ring putus asa,<br/>tak balik ke kawanan domba.<br/>Hingga merasa bimbang?<br/>(Oh ...!)<br/>',NULL,65201,1);
INSERT INTO stanza VALUES('I1702','chorus','Yang kucinta,<br/>yang ku cinta cepat datang!<br/>Nikmat-i-lah, nikmat-i-lah,<br/>s''karang juga.<br/>Keperlu-an Allah dan kau,<br/>di-puas-kan se-mua.<br/>Sa-at kau bers''rah, bagi gereja,<br/>pasti dapat mahkota.<br/>Haleluya!<br/>',NULL,65202,2);
INSERT INTO stanza VALUES('I1702','2','Kau sering ''ngeluh pada orang:<br/>Mengapa aku sering buntu.<br/>Tak dapat ''nembus awan mendung,<br/>gumul ronta, tak juga cerah.<br/>O, kapan dapat ku-at!<br/>(Oh ...!)<br/>Kar''na tak tahu kebebasan,<br/>sering terp''rosok dalam lumpur!<br/>Kar''na tak tahu nilai hayat,<br/>kar''na tak ma-u bebaskan Dia.<br/>Hingga begini gersang!<br/>(Oh ...!)<br/>',NULL,65203,3);
INSERT INTO stanza VALUES('I1702','1','Kau  masih terus menuntut Dia,<br/>juga mengecap manis Tuhan.<br/>Tapi Tuhan tak penuhimu,<br/>kar''na kau masih tidak mutlak.<br/>Pula sering berubah<br/>(Oh ...!)<br/>Kau t''lah bertekad depan Tuhan,<br/>se-la-in Di-a tak kau harap.<br/>Sa-at Tuhan minta padamu,<br/>kau merasa sangatlah sulit.<br/>Tak mampu d''rita rugi!<br/>(Oh ...!)<br/>',NULL,65204,4);
INSERT INTO stanza VALUES('I1702','chorus','Yang kucinta,<br/>yang ku cinta cepat datang!<br/>Nikmat-i-lah, nikmat-i-lah,<br/>s''karang juga.<br/>Keperlu-an Allah dan kau,<br/>di-puas-kan se-mua.<br/>Sa-at kau bers''rah, bagi gereja,<br/>pasti dapat mahkota.<br/>Haleluya!<br/>',NULL,65205,5);
INSERT INTO stanza VALUES('I1702','2','Kau juga sering rasa bingung,<br/>mengapa diri sangat lemah.<br/>Kar''na kau ingin dapat "kuasa",<br/>ingin "bekerja" bagi Tuhan.<br/>Ke-mur-ni-an t''lah hilang!<br/>(Oh ...!)<br/>Atau kau "menang" lalu sombong,<br/>atau kau penuh gundah g''lisah.<br/>Kar''na ingin diri rohani,<br/>lupa bersandar pada "m''reka".<br/>Hilanglah ke-ku-at-an!<br/>(Oh ...!)<br/>',NULL,65206,6);
INSERT INTO stanza VALUES('I1702','1','Kau pernah berkata pada-Nya,<br/>mangkir tak tenang, datang bimbang.<br/>Dalam sidang ingin mendapat,<br/>tutupi miskin, lemah awak.<br/>Tapi entah caranya<br/>(Oh ...!)<br/>Mungkin kau s''lalu datang sidang,<br/>ikut berseru "amin" juga.<br/>Tapi kau rasa kosong m''lompong,<br/>kar''na kau ikut "luar-an" saja.<br/>Tak tahu tentang hayat<br/>(Oh ...!)<br/>',NULL,65207,7);
INSERT INTO stanza VALUES('I1702','2','Sa-at orang lain dalam arus,<br/>kau hanya pandang dari ja-uh.<br/>Nampak berkat-Nya, engkau senang,<br/>nampak kegagalan, kau m''rana.<br/>Kau masih de-mi-ki-an<br/>(Oh ...!)<br/>Kau ingin banyak kewajiban,<br/>biar namamu jadi terkenal.<br/>Sering "membantu", dapat "upah",<br/>sering "simpati" dapat "pu-jian".<br/>Tuhanmu tak de-mi-kian<br/>(Oh ...!)<br/>',NULL,65208,8);
INSERT INTO stanza VALUES('I1703','1','Dulu aku pernah sendi-rian,<br/>mau rohani pribadi.<br/>Harap bisa layani Tuhan,<br/>supaya Di-a pu-as.<br/>Meski sering merasa senang,<br/>sering juga kese-pian.<br/>Ku sudah banyak putus asa,<br/>tahu jangan ter-u-lang.<br/>',NULL,65209,1);
INSERT INTO stanza VALUES('I1703','2','Dalam Tuhan ku jumpa ka-lian,<br/>seperti jumpa Tuhan.<br/>Ku tahu t''lah dapat ke-diam-an,<br/>nikmati limpah Tuhan.<br/>Oleh ka-lian ku jadi ku-at,<br/>terus maju ke depan.<br/>Ku damba bersatu d''ngan ka-lian,<br/>hidup untuk ka-li-an.<br/>',NULL,65210,2);
INSERT INTO stanza VALUES('I1704','1','Kini kau hidup di g''reja,<br/>merasakan sukacita!<br/>Puji Dia, sungguh mu-li-a,<br/>kami temukan sasaran.<br/>',NULL,65211,1);
INSERT INTO stanza VALUES('I1704','2','Tak lagi mencari-cari,<br/>kami t''lah pulang ke rumah.<br/>Saudara tinggal d''ngan rukun,<br/>sukacita tia-da tanding!<br/>',NULL,65212,2);
INSERT INTO stanza VALUES('I1704','3','Ini tempat pi-li''an Allah,<br/>sering pandang wajah Allah.<br/>Nama-Nya ada di sini,<br/>diam di sini beda pasti.<br/>',NULL,65213,3);
INSERT INTO stanza VALUES('I1704','4','Haleluya, Dia yang pilih,<br/>sejak dengar su-a-ra-Nya.<br/>Dari lubuk kata,"Amin",<br/>kita sedang di dalamnya.<br/>',NULL,65214,4);
INSERT INTO stanza VALUES('I1705','1','Tuhan puncak sayangku,<br/>pada-Nya s''galaku.<br/>Papah dan tunjangku,<br/>pula p''lipur laraku.<br/>Korban ''tuk menebus,<br/>kini pancar hidup.<br/>Sejahteraku, ri-ang ri-a-ku.<br/>Ya Tuhan!<br/>Ku cinta pada-Mu,<br/>sampai kekal.<br/>',NULL,65215,1);
INSERT INTO stanza VALUES('I1705','2','G''reja rumah nan mesra,<br/>me-mu-as-kan manah!<br/>Pasangan sayang-Nya,<br/>sandaran s''panjang u-sia.<br/>Penuh kasih sayang,<br/>suplaian tak batas.<br/>Beri tenaga,<br/>bimbing ku jalan.<br/>Gereja! Ku cinta padamu,<br/>rumah mesra!<br/>',NULL,65216,2);
INSERT INTO stanza VALUES('I1706','1','Hari riang, pulang ke rumah,<br/>mengecap kasih Bapa.<br/>Menempuh hidup gereja,<br/>limpah Kristus kita nikmat.<br/>',NULL,65217,1);
INSERT INTO stanza VALUES('I1706','chorus','Bagi pemu-li''an Tuhan,<br/>latih roh di tiap lokal.<br/>Esalah, sama layan-i,<br/>Tubuh Kristus lantas wujud.<br/>',NULL,65218,2);
INSERT INTO stanza VALUES('I1706','2','Tujuh Roh, Roh yang membakar,<br/>menguji, membersihkan.<br/>Terangi, tu-ang, dan isi,<br/>hingga aku s''rupa Tuhan.<br/>',NULL,65219,3);
INSERT INTO stanza VALUES('I1707','1','Sungguh riang, s''mua anak Allah,<br/>me-riah berhimpun di rumah-Nya.<br/>Bersama kisahkan kur-nia a-jaib,<br/>Roh membubung sua-ra pu-jian tak henti.<br/>',NULL,65220,1);
INSERT INTO stanza VALUES('I1708','1','Kita semua puji sorak,<br/>kita tinggal serta Raja!<br/>Visi jelas, hidup mutlak,<br/>kitalah g''reja pilihan-Nya.<br/>',NULL,65221,1);
INSERT INTO stanza VALUES('I1708','2','Kita dengar sua-ra guntur,<br/>saleh tegak tum-puan lokal.<br/>Haleluya! Kita bers''ru,<br/>dalam sidang terus puji Dia.<br/>',NULL,65222,2);
INSERT INTO stanza VALUES('I1708','3','Kita tak berk''lana lagi,<br/>mencari bintang di langit.<br/>Haleluya, sorot terang,<br/>kini kita sudah di rumah.<br/>',NULL,65223,3);
INSERT INTO stanza VALUES('I1709','1','Teduh di g''reja, tak lagi berk''lana,<br/>hati ''tia-sa ri-ang dan pu-as.<br/>Kristuslah hayat, henti peronta-an.<br/>Haleluya! Teduh di rumah!<br/>Rumahku g''reja,<br/>kini ku tak berk''lana pula.<br/>S''panjang hidupku, memuji tak henti.<br/>Haleluya! Kristus dan g''reja!<br/>',NULL,65224,1);
INSERT INTO stanza VALUES('I1709','2','Di sini Allah dapatkan perhen-tian,<br/>hati-Nya ri-ang dan pu-as-lah.<br/>G''reja ku sayang; hai, Satan, enyahlah!<br/>Di sini mu-lia-Nya tertampak.<br/>Rumahku g''reja,<br/>kini Allah ayem berkenan.<br/>S''panjang hidupku, memuji tak henti.<br/>Haleluya! Kristus dan g''reja!<br/>',NULL,65225,2);
INSERT INTO stanza VALUES('I1710','1','Dari Sodom k''lu-ar-lah!<br/>(Dari Sodom k''lu-arlah!)<br/>Dari Sodom k''lu-ar-lah!<br/>(Dari Sodom k''luarlah!)<br/>Dari Sodom k''lu-ar-lah!<br/>(Dari Sodom k''luarlah!)<br/>Dia sg''ra datang!<br/>(Dia sg''ra datang!)<br/>Du-ni-a segera lewat.<br/>Apa yang kau dambakan?<br/>Hari t''rangkat hampir tiba,<br/>mau t''rangkat a-tau tinggal?<br/>',NULL,65226,1);
INSERT INTO stanza VALUES('I1710','2','Di tempat Dia tersalib,<br/>di tempat Dia tersalib.<br/>Di tempat Dia tersalib,<br/>ku pun mati.<br/>Serta-Nya aku tersalib,<br/>du-nia hilanglah arti.<br/>Kini hidupku di bumi,<br/>nantikan Dia kembali.<br/>',NULL,65227,2);
INSERT INTO stanza VALUES('I1710','3','Lekas masuk bahtera,<br/>lekas masuk bahtera.<br/>Lekas masuk bahtera,<br/>hidup g''reja.<br/>Dalam baht''ra kita nikmat,<br/>Tuhan jadi segala.<br/>Banyak alami dan nikmat,<br/>tak layu dan tak penat.<br/>',NULL,65228,3);
INSERT INTO stanza VALUES('I1711','1','Yesus, Gembala a-ja-ib,<br/>pimpinku ke-luar kandang.<br/>Padang subur, sangat lu-as,<br/>aku ada di sana!<br/>',NULL,65229,1);
INSERT INTO stanza VALUES('I1711','chorus','O, hidup g''reja,<br/>sungguh mu-lia dan limpah!<br/>Di sini kita bersatu,<br/>nikmati berkat hayat.<br/>',NULL,65230,2);
INSERT INTO stanza VALUES('I1711','2','Tempat asing, d''rita lapar,<br/>Di-a yang mencariku.<br/>Bawa ku ke tanah permai,<br/>rasa nyaman dalam roh.<br/>',NULL,65231,3);
INSERT INTO stanza VALUES('I1711','3','Yesus itu padang rumput,<br/>Di-a makanan kita.<br/>Kita adalah domba-Nya,<br/>tiap sidang pasti kenyang.<br/>',NULL,65232,4);
INSERT INTO stanza VALUES('I1711','4','Kita tinggal atas gunung,<br/>embun diris nan segar!<br/>Tidak lagi rasa dah''ga,<br/>Di-a-lah a-ir hayat.<br/>',NULL,65233,5);
INSERT INTO stanza VALUES('I1711','5','Kristus adalah nikmatku,<br/>tak perlu kua-tir lagi.<br/>Di sini kita t''lah mantap,<br/>kar''na Di-a lindungi.<br/>',NULL,65234,6);
INSERT INTO stanza VALUES('I1712','1','Hidup g''reja t''rang benderang,<br/>taman Allah nan indah,<br/>alami Kristus, dewasa pujilah!<br/>Dalam Kristus,<br/>limpah Allah suplai kita tak sudah,<br/>betapa segarnya, se-dia pun akrab!<br/>',NULL,65235,1);
INSERT INTO stanza VALUES('I1712','chorus','Sungguh ri-ang di taman Allah!<br/>Bukan kepalang, elok mesra!<br/>Hari-hari kenyang bu-ah,<br/>menyesap sungai hayat,<br/>bumi tia-da hidup yang lebih sedap!<br/>',NULL,65236,2);
INSERT INTO stanza VALUES('I1712','2','Bukan gedung, bukan pabrik,<br/>atau pun sekolahan.<br/>G''reja taman hayat,<br/>Kristus dewasa.<br/>Kita telah Tuhan tanam, dipupuk,<br/>dan disiram.<br/>Kita ini ladang garapan Allah!<br/>',NULL,65237,3);
INSERT INTO stanza VALUES('I1712','3','Dalam taman hidup g''reja,<br/>terdapat pohon hayat.<br/>Penuh bu-ah hayat se-dia makanan.<br/>Buang pendapat, buang pikiran,<br/>makan buah hayat saja.<br/>Ti-a-sa ''nikmati Kristus nan mesra!<br/>',NULL,65238,4);
INSERT INTO stanza VALUES('I1712','4','Tengok! Ada sungai hayat<br/>''ngalir t''rus dari takhta.<br/>Leraikan segala lelah dan dah''ga.<br/>Dalam taman,<br/>Kristus ''ngalir di batin, haleluya!<br/>Mendiris aku sehingga dewasa!<br/>',NULL,65239,5);
INSERT INTO stanza VALUES('I1712','5','Ke sini aku terbawa,<br/>''nikmati diri Kristus.<br/>Alangkah terasa lega pun sejuk.<br/>Sesap, santap, di dalam roh,<br/>ri-ang ri-a tak putus.<br/>Bulan-bulan hasilkan bu-ah baru!<br/>',NULL,65240,6);
INSERT INTO stanza VALUES('I1713','1','O, hidup g''reja nan nyaman!<br/>Di sini kita minum dan makan.<br/>Tak lagi lapar dan dah''ga.<br/>Mari, nikmati bersama!<br/>',NULL,65241,1);
INSERT INTO stanza VALUES('I1713','chorus','Lekas masuk baht''ra,<br/>''nempuh hidup g''reja.<br/>Minum, makan ''tia-sa,<br/>Dia ''kan datang seg''ra!<br/>Lekas masuk baht''ra,<br/>''nempuh hidup g''reja.<br/>Sambut Memp''lai Laki,<br/>paling girang!<br/>',NULL,65242,2);
INSERT INTO stanza VALUES('I1713','2','O, hidup g''reja nan nyaman!<br/>Untuk ini persembahkan se-mua!<br/>Bagi Kristus dan gereja,<br/>la-in-nya tak ku dambakan.<br/>',NULL,65243,3);
INSERT INTO stanza VALUES('I1713','3','O, hidup g''reja nan nyaman!<br/>K''lu-ar-ga Allah serbalah kaya!<br/>Berfungsi ti-ap bersidang,<br/>bimbing jiwa t''rima s''lamar!<br/>',NULL,65244,4);
INSERT INTO stanza VALUES('I1713','4','O, hidup g''reja nan nyaman!<br/>Dia tanah permai, palinglah subur!<br/>Rajin garap dan menyiram,<br/>bekerja terus-menerus!<br/>',NULL,65245,5);
INSERT INTO stanza VALUES('I1713','5','O, hidup g''reja nan nyaman!<br/>Kita dibangunkan jadi esa!<br/>Kaulah malu, hai, Satan tua!<br/>Memp''lai p''rem-puan dip''roleh-Nya!<br/>',NULL,65246,6);
INSERT INTO stanza VALUES('I1714','1','Ada orang bilang Yesus bukan santapan.<br/>Mengetahui dan berbuat bajik sudah cukup.<br/>Namun sebenarnya bukanlah demiki-an.<br/>Yesus, roti hayat, kita makan tiap hari.<br/>',NULL,65247,1);
INSERT INTO stanza VALUES('I1714','chorus','O, hidup gereja, makan, minum, hirup Yesus.<br/>O, hidup gereja, t''rima sabda-Nya.<br/>O, sedap terdengar,<br/>"Tuhan! Amin! Haleluya!"<br/>O, hidup gereja, pesta dengan-Nya.<br/>',NULL,65248,2);
INSERT INTO stanza VALUES('I1714','2','Seru nama-Nya, k''limpahan-Nya kita kecap.<br/>Dia-pun memenuhi se-ti-ap p''losok kita.<br/>Hari-hari berhimpun, nikmat per-se-ku-tuan.<br/>Hingga Tuhan datang, kita se-mua terangkat.<br/>',NULL,65249,3);
INSERT INTO stanza VALUES('I1714','3','Jika si-tu-a-si du-nia zaman sekarang.<br/>Mem-bu-at Anda rasa dipusari jahat.<br/>Dengarkanlah apa yang Roh Kudus katakan,<br/>"Mari ''nempuh hidup g''reja - hidup p''nuh berkat!"<br/>',NULL,65250,4);
INSERT INTO stanza VALUES('I1715','1','Bangunlah pagi, t''rus makan Tuhan,<br/>menempuh hidup g''reja serempak.<br/>Munajat tiap fajar, buka roh,<br/>aminlah, nikmati hadir Tuhan.<br/>Haleluya! Dia hadir!<br/>Haleluya! Dia hadir!<br/>Di mana pun menempuh hidup gereja!<br/>',NULL,65251,1);
INSERT INTO stanza VALUES('I1715','2','Kawak, baru, ti-a-da bedanya,<br/>datang saksikan Kristus bersama.<br/>Saling beranggota, saling b''ri suplaian,<br/>dalam kasih menunjang.<br/>Haleluya, kita s''mua adalah anggota-Nya.<br/>''Nyatakan daya guna di dalam g''reja!<br/>',NULL,65252,2);
INSERT INTO stanza VALUES('I1715','3','Kristus kita miliki bersama,<br/>mari, bagikan nikmat atas-Nya.<br/>Di g''reja, di rumah, alami berkat-Nya,<br/>haleluya, giranglah!<br/>Haleluya, giranglah!<br/>Haleluya, giranglah!<br/>Tubuh Kristus berlimpah!<br/>Itulah g''reja!<br/>',NULL,65253,3);
INSERT INTO stanza VALUES('I1715','4','Yesuslah Tuhan, s''ru,"Haleluya!"<br/>Mari pamerkan Kristus serentak.<br/>Kau nyanyi, ku ''muji, dia saksi,<br/>aminlah, sedap bukan bu-at-an.<br/>Haleluya, sedaplah!<br/>Haleluya, sedaplah!<br/>Segar, kaya dan lincah,<br/>hidup gereja!<br/>',NULL,65254,4);
INSERT INTO stanza VALUES('I1716','1','Sua-ra hayat dalam g''reja,<br/>terdengar mana jua.<br/>Kristus itu ri-ang kita,<br/>terekspresikan.<br/>Babilon dan du-ni-a-wi<br/>ku tak bersangkutan.<br/>Kita sudah pulang,<br/>tanah s''jah-t''ra.<br/>',NULL,65255,1);
INSERT INTO stanza VALUES('I1716','chorus','Dalam roh,<br/>''nempuh g''reja atas tum-pu-an lokal.<br/>Saudara ''nempuh g''reja,<br/>kita sudah pulang.<br/>Ikut s''mua g''reja, ''nempuh g''reja,<br/>genap bumi bergita.<br/>O, haleluya!<br/>Tanah s''jah-t''ra.<br/>',NULL,65256,2);
INSERT INTO stanza VALUES('I1716','2','Latar b''lakang, teori-teori,<br/>bu-ang ja-uh-ja-uh.<br/>Adat, iba, nikmat dosa,<br/>lebih ter-ja-uh.<br/>Kasih unggul Yesus Kristus<br/>membanjiri kalbu.<br/>Tak tinggalkan Kristus,<br/>tanah s''jah-t''ra!<br/>',NULL,65257,3);
INSERT INTO stanza VALUES('I1716','3','"Ku mau bangun gereja<br/>di atas batu karang!"<br/>De-mi-ki-an firman<br/>Tuhan genap niscaya.<br/>Se-suai dengan kehendak-Nya<br/>Tubuh koor-di-na-si.<br/>Dirikan di atas<br/>tanah s''jah-t''ra!<br/>',NULL,65258,4);
INSERT INTO stanza VALUES('I1716','4','Kini Tuhan sedang mempercepat<br/>pe-mu-li''an-Nya.<br/>G''reja lokal,<br/>pada Tuhan mohon serempak.<br/>Segera akhiri zaman,<br/>''nyongsong mempelai-Nya.<br/>Haleluya, Kristus,<br/>tanah s''jaht''ra!<br/>',NULL,65259,5);
INSERT INTO stanza VALUES('I1717','1','Hidup gereja, indah,<br/>p''ri ''ngecap hari itu.<br/>O, Yerusalem, negeri da-mai,<br/>pu-as dan teduh.<br/>',NULL,65260,1);
INSERT INTO stanza VALUES('I1717','2','Gereja hari ini alirkan:<br/>susu, madu.<br/>Nikmati saja se-pu-as-pu-as,<br/>hayat sepenuh.<br/>',NULL,65261,2);
INSERT INTO stanza VALUES('I1717','3','G''reja terbangun, istana Allah,<br/>Dia semayam.<br/>Pegang ku-a-sa bagilah Allah,<br/>g''napkan murad-Nya.<br/>',NULL,65262,3);
INSERT INTO stanza VALUES('I1718','1','Kita amat rindu berhari raya, ayo,<br/>kita pergi bersuka-ri-a!<br/>Masa duka dan pua-sa sudah lewat,<br/>kini sa-at-nya nikmati gembira bersama.<br/>O, haleluya, sungguh nikmat,<br/>beginilah sidang kita,<br/>yang pernah mengecap berkata:<br/>sedapnya tia-da taranya.<br/>Kita  amat rindu berhari raya,<br/>ayo, kita pergi bersuka-ri-a!<br/>Masa duka dan pua-sa sudah lewat,<br/>kini sa-at-nya nikmati gembira bersama.<br/>',NULL,65263,1);
INSERT INTO stanza VALUES('I1718','2','Di Yerusalemlah pe-ra-ya-an-nya,<br/>lambang ke-sak-sian ke-e-sa-an kita.<br/>Kaki berdiri di dalam pintunya,<br/>hati taklah tertahan memuji nama Tuhan!<br/>Tengok! Yerusalem yang rapi!<br/>Tengok! Fakta esa indah!<br/>Pencintamu pastilah jaya,<br/>di sinilah mu-lia Allah!<br/>Di Yerusalemlah pe-ra-ya-an-nya,<br/>lambang ke-sak-sian ke-e-sa-an kita.<br/>Kaki berdiri di dalam pintunya,<br/>hati taklah tertahan memuji nama Tuhan!<br/>',NULL,65264,2);
INSERT INTO stanza VALUES('I1718','3','Jangan jumpa Allah d''ngan hampa tangan,<br/>bawalah lembu, domba, merpati, dan ...<br/>Apam fatir mayang dan tepung, minyak,<br/>persembahkanlah agar Allah dan kita kenyang.<br/>Tengok! Se-tiap-nya tak lain Kristus!<br/>Tengok! Alangkah limpahnya!<br/>Apabila kita mau kenyang,<br/>Allah harus kenyang du-luan.<br/>Jangan jumpa Allah d''ngan hampa tangan,<br/>bawalah lembu, domba, merpati, dan ...<br/>Apam fatir, mayang dan tepung, minyak,<br/>persembahkanlah agar Allah dan kita kenyang.<br/>',NULL,65265,3);
INSERT INTO stanza VALUES('I1719','1','Putus hubungan dengan berhala,<br/>Kristuslah melulu nikmat kita!<br/>Tak tertipu lagi oleh du-nia,<br/>gereja rea-li-tas hidup kita.<br/>',NULL,65266,1);
INSERT INTO stanza VALUES('I1719','chorus','O, rasa nikmat bukan kepalang!<br/>Gunung menetes, netes, neteslah arak!<br/>O, puji Tuhan, sungguh berlimpah.<br/>Bukit alir, alir susu sedap!<br/>',NULL,65267,2);
INSERT INTO stanza VALUES('I1719','2','Tanpa liturgi, tanpa yang usang.<br/>P''nuh arak baru sungguh gai-rah-kan!<br/>Ada yang mimpi pun ada visi.<br/>Sidang apa lagi yang tandingi?<br/>',NULL,65268,3);
INSERT INTO stanza VALUES('I1719','3','Hidup dalam roh, cepat terpulih.<br/>Yang hilang, kini telah kembali.<br/>Tiap orang lincah, suplaikan Kristus.<br/>Makin bersidang makin berlimpah.<br/>',NULL,65269,4);
INSERT INTO stanza VALUES('I1720','1','Kristus itulah tanah nan subur,<br/>lezat berlimpah susu dan madu.<br/>Tak usah bayar, mari kecap t''rus,<br/>untuklah Anda dan aku!<br/>',NULL,65270,1);
INSERT INTO stanza VALUES('I1720','2','Dia Allah hidup, s''ru,"Haleluya!"<br/>Hidup dalamku, s''ru,"Haleluya!"<br/>Dia-lah ba-gian-ku, lezat berlimpah,<br/>s''ru,"O, Tuhan!", mengecap Dia.<br/>',NULL,65271,2);
INSERT INTO stanza VALUES('I1720','3','Kita bersidang, alangkah indah,<br/>kar''na dalam roh, sama anggota.<br/>Jadi Tubuh-Nya, ekspresikan Dia,<br/>Kristus re-a-li-tas kita.<br/>',NULL,65272,3);
INSERT INTO stanza VALUES('I1720','4','Kita bersidang pamer kaya-Nya,<br/>di g''reja lokal, agungkan Tuhan.<br/>Ke-sak-sian esa, diperkenan-Nya,<br/>terpenuhi s''mua ke-per-luan!<br/>',NULL,65273,4);
INSERT INTO stanza VALUES('I1720','5','Kita terlatih, di g''reja lokal,<br/>mig''rasi untuk seluruh bangsa.<br/>Ba-ur dengan Dia, sebar Injil-Nya,<br/>merata di ti-ap kota!<br/>',NULL,65274,5);
INSERT INTO stanza VALUES('I1721','1','Dalam g''reja Tuhan, terse-dia kasih;<br/>kasih murni, lembut, dalam dan tulus.<br/>M''ngapa rasa sepi, ti-a-da teman?<br/>Di g''reja Tuhan ada suplai limpah.<br/>',NULL,65275,1);
INSERT INTO stanza VALUES('I1721','2','Dalam g''reja Tuhan, ter-se-dia hayat.<br/>Hangat p''ri mentari, segar p''ri embun.<br/>Untuk apa takut, kua-tir, gelisah?<br/>G''reja m''rawat orang yang Tuhan tebus.<br/>',NULL,65276,2);
INSERT INTO stanza VALUES('I1721','3','Dalam g''reja Tuhan, ada ker-ja-an.<br/>Malaikat pun suka ambil ba-gi-an.<br/>Untuk apa tunggu, kerjalah seg''ra!<br/>G''reja perlu kita berdaya guna.<br/>',NULL,65277,3);
INSERT INTO stanza VALUES('I1721','4','Dalam g''reja Tuhan, ada ke-diam-an.<br/>Mu-lia, terang, ri-ang, adil, sentosa.<br/>Jangan berkelana, lelah merana.<br/>Dalam g''reja ada tempat ke-diam-an.<br/>',NULL,65278,4);
INSERT INTO stanza VALUES('I1722','1','Alangkah nikmat hidup di rumah-Nya,<br/>hidup g''reja amat mesra.<br/>Hirup nama-Nya, santap, sesap sabda,<br/>bagi puli''an-Nya nan mu-lia.<br/>Jalan, kita berjalan dalam terang hayat,<br/>hidup, kita ''nempuh hidup gereja Allah.<br/>Cinta-Nya jaga, terang-Nya pancar,<br/>saling kasih, terbangun s''rempak.<br/>',NULL,65279,1);
INSERT INTO stanza VALUES('I1723','1','Kini kita bersidang, segar lagi lincah.<br/>Dalam roh bebaslah berhimpun dan menyembah.<br/>Kristus itu re-a-li-tas nikmat kita.<br/>Gelap sirna oleh se-ru-an nama Tuhan.<br/>',NULL,65280,1);
INSERT INTO stanza VALUES('I1723','chorus','Sidang segar dan lincah, teladan pun baru.<br/>Di taman dan sekolah a-tau di tepi laut.<br/>Campakkan s''mua liturgi agama mati.<br/>Haleluya! Roh Tuhan dobrak s''gala limit!<br/>',NULL,65281,2);
INSERT INTO stanza VALUES('I1723','2','Bu-ang se-mua tata cara agama mati.<br/>Tolak mentah aturan dan pendapat daging.<br/>Singkir huruf dan te-o-ri mematikan.<br/>Haleluya! Dalam roh kita sungguh bebas.<br/>',NULL,65282,3);
INSERT INTO stanza VALUES('I1723','3','Segar, lincah, basi lenyap, usang tersapu.<br/>Do-a baca, nyanyi, membagi nikmat Kristus.<br/>Usang enyah, terbasmilah tak membekas.<br/>Haleluya! Hal baru kini Tuhan garap!<br/>',NULL,65283,4);
INSERT INTO stanza VALUES('I1724','1','Kita ini ka-um berambisi,<br/>bawa berkat ke dalam sidang.<br/>Tak lagi garap liturgi mati,<br/>tapi se-mua berdaya guna.<br/>Haleluya! S''kutu, do-a, puji,<br/>kita s''mua berba-gian dalamnya!<br/>Sidang apa pun janganlah mati;<br/>tapi hidup, lincah, dan segar.<br/>',NULL,65284,1);
INSERT INTO stanza VALUES('I1724','2','Kita ini ka-um berambisi,<br/>Roh Sang Firman ada di dalam.<br/>Dulu ''ngangur, kar''na Dia terkunci,<br/>kini haruslah dibebaskan.<br/>Haleluya! Bebaskan Roh ini,<br/>hingga sidang tak lagi lembam.<br/>Harus bertutur-sabda bagi-Nya,<br/>agar kaum saleh terbangunkan.<br/>',NULL,65285,2);
INSERT INTO stanza VALUES('I1725','1','Dia bers''ruling, kita menari;<br/>Dia meratap, kita menangis.<br/>Kita anak kecil, tak kenal liturgi,<br/>hanya tahu Tuhan yang pimpin.<br/>Orang pandai banyak berpikir,<br/>tidak bers''rah pada Roh suci.<br/>Hingga Tuhan tertutup-i,<br/>ke-cu-a-li ternyata pada bayi.<br/>',NULL,65286,1);
INSERT INTO stanza VALUES('I1725','2','Mari kita memikul kuk-Nya,<br/>mengikuti gerak-gerik-Nya.<br/>Kita lembu muda, bukan tak ber-tu-an,<br/>tiap langkah patuh perintah-Nya.<br/>Dia ke Timur, kita ke Timur;<br/>Dia ke Barat, kita ke Barat.<br/>Sungguh mudah, ringan, pun girang,<br/>karena Dia-lah Penanggung kuk-Nya.<br/>',NULL,65287,2);
INSERT INTO stanza VALUES('I1726','1','Amin, roh itulah<br/>re-a-li-tas g''reja.<br/>Bukanlah cara liturgi,<br/>''cua-li roh belaka.<br/>Roh resap-i kita,<br/>mudah le-lu-a-sa!<br/>Lepas diri, lepas usang,<br/>se-suai kehendak-Nya.<br/>',NULL,65288,1);
INSERT INTO stanza VALUES('I1726','2','Arak, kirbat baru,<br/>s''mua usang tersapu.<br/>Dobrak se-mua limit diri,<br/>''ngalirlah Roh Kudus!<br/>Kita s''mua le-lua-sa!<br/>G''reja pasti ku-at!<br/>P''ri api roh kita membara,<br/>g''reja s''gar s''lama.<br/>',NULL,65289,2);
INSERT INTO stanza VALUES('I1727','1','Kristus telah bebaskanku,<br/>''lua-sakan Dia, ku pun harus.<br/>Oleh hayat, dosa lucut,<br/>lewat saksi, Dia terwujud.<br/>',NULL,65290,1);
INSERT INTO stanza VALUES('I1727','chorus','Haleluya! Bebas mu-lia!<br/>Tergenaplah murad Allah!<br/>',NULL,65291,2);
INSERT INTO stanza VALUES('I1727','2','Dalam Kristus, aku bebas,<br/>lepas dari kekang du-nia.<br/>Masa depan tak ku hirau,<br/>saksikan Dia, di dalam roh.<br/>',NULL,65292,3);
INSERT INTO stanza VALUES('I1727','3','Limpah Kristus, di dalam roh,<br/>tunggu aku alami-Nya.<br/>Tiap ''lua-sa-kan Kristus di roh,<br/>ku-at, hikmat s''mua milikku.<br/>',NULL,65293,4);
INSERT INTO stanza VALUES('I1727','4','Tuhan tolong lepaskanku<br/>dari se-mua doktrin kosong.<br/>K''limpahan roh garap terus,<br/>Kristus mu-lia ''lua-sa-kan t''rus.<br/>',NULL,65294,5);
INSERT INTO stanza VALUES('I1727','5','Demi ku Kristus terpamer,<br/>tertampaklah indah mu-lia.<br/>Tiap kali Dia ku ''lua-sa-kan,<br/>hatiku penuh ri-ang-Nya.<br/>',NULL,65295,6);
INSERT INTO stanza VALUES('I1727','6','Tuhan ku menyesal atas<br/>"pengalaman" sudah-sudah.<br/>Tak mau lagi ku tertipu,<br/>balik ke roh ''lua-sa-kan-Mu.<br/>',NULL,65296,7);
INSERT INTO stanza VALUES('I1728','1','Haleluya! Rah''-sia amat,<br/>Allah jelma insan.<br/>Ke-lim-pah-an Allah mu-lia.<br/>Atasku ternyata,<br/>atasku ternyata.<br/>Haleluya, nyata bulat.<br/>',NULL,65297,1);
INSERT INTO stanza VALUES('I1728','2','Entah aku ini apa,<br/>namun ''ngandung Allah.<br/>Fungsi apa ku tak tanya.<br/>Asalkan roh bebas,<br/>asalkan roh bebas.<br/>Haleluya! Roh bebaslah!<br/>',NULL,65298,2);
INSERT INTO stanza VALUES('I1728','3','Kedudukan tak ku hirau,<br/>ke-cu-a-li Tuhan.<br/>Jika aku tidak ta-at.<br/>Sidang ''kan terkekang;<br/>biar-kan Allah nyata.<br/>Haleluya! Allah nyata.<br/>',NULL,65299,3);
INSERT INTO stanza VALUES('I1728','4','Mu-lia! Mu-lia! Rah''-sia amat,<br/>dalam roh kita s''mua.<br/>Saling bangun, rukun erat.<br/>Wujud g''reja mu-lia,<br/>wujud g''reja mu-lia.<br/>Haleluya! G''reja mu-lia.<br/>',NULL,65300,4);
INSERT INTO stanza VALUES('I1729','1','Haleluya, bebas! Haleluya, bebas!<br/>Ku tak lagi t''rikat dosa.<br/>Dosa ku t''lah Tuhan paku atas salib.<br/>Haleluya! Ku bebas!<br/>',NULL,65301,1);
INSERT INTO stanza VALUES('I1729','2','Haleluya, bebas! Haleluya,<br/>bebas! Ku tak ikut tata cara.<br/>Lepas usang, mutlak kudus, insan baru.<br/>Haleluya! Ku bebas!<br/>',NULL,65302,2);
INSERT INTO stanza VALUES('I1729','3','Haleluya, bebas! Haleluya, bebas!<br/>Hayat Tuhan, mengubahku.<br/>Di-ba-ru-i, capai perawakan Kristus.<br/>Haleluya! Ku bebas!<br/>',NULL,65303,3);
INSERT INTO stanza VALUES('I1729','4','Haleluya, bebas! Haleluya, bebas!<br/>Kita untuk ke-sak-sian-Nya.<br/>Dalam Tubuh, dis''rupakan gambar Allah.<br/>Haleluya! Bebaslah!<br/>',NULL,65304,4);
INSERT INTO stanza VALUES('I1729','5','Haleluya, bebas! Haleluya, bebas!<br/>Ta-at g''reja, koor-di-na-si.<br/>K''lola, bangun, jadi Tubuh mu-lia Tuhan.<br/>Haleluya! Bebaslah!<br/>',NULL,65305,5);
INSERT INTO stanza VALUES('I1729','6','Haleluya, bebas! Haleluya, bebas!<br/>Pembangunan sungguh ri-il.<br/>Mendapatkan g''reja lokal, rumah Allah.<br/>Haleluya! Bebaslah!<br/>',NULL,65306,6);
INSERT INTO stanza VALUES('I1730','1','Dalam rumah banyak wadah,<br/>kau jadi yang mana?<br/>Mas, perak, permata,<br/>atau kayu, rumput, j''rami?<br/>',NULL,65307,1);
INSERT INTO stanza VALUES('I1730','chorus','Suci murni, lepas nista,<br/>pasti jadi yang mu-lia.<br/>Kudus, diperkenan,<br/>untuk dipakai Tu-an-nya!<br/>',NULL,65308,2);
INSERT INTO stanza VALUES('I1730','2','Wadah rendah: sumpek,<br/>lembam, alangkah kasihan!<br/>Wadah mu-lia: tegap,<br/>gagah, alangkah mu-li-a!<br/>',NULL,65309,3);
INSERT INTO stanza VALUES('I1730','3','Duduk di-am, pikir timbang,<br/>jadi wadah rendah.<br/>Ta-at-i Roh, bebaskan roh,<br/>itu wadah mu-lia.<br/>',NULL,65310,4);
INSERT INTO stanza VALUES('I1731','1','Tidak menempuh liturgi,<br/>doktrin, huruf mati.<br/>Paling ke roh, baru benar,<br/>cepat masuk arus!<br/>Hidup di roh, kita esa,<br/>se-ia sekata.<br/>Seru,"Tuhan, amin,<br/>haleluya! Yesus Tuhan!"<br/>',NULL,65311,1);
INSERT INTO stanza VALUES('I1732','1','Alir, alir, alir k''limpahan-Nya,<br/>lewat diriku teralir limpah hayat.<br/>Alir, alir, alir k''limpahan-Nya,<br/>jadi suplai se-mua orang limpah hayat.<br/>Sa-at ku ta''u k''limpahan dalamku,<br/>sa-at ku ta''u k''limpahan nan pu-as.<br/>Ku rela alirkan se-mu-a-nya,<br/>agar ti-ap orang pu-as karenanya.<br/>',NULL,65312,1);
INSERT INTO stanza VALUES('I1732','2','Bebas, bebas, bebaskan hayat-Nya,<br/>agar teralir se-mu-a limpah hayat.<br/>Kua-sa hikmat, ada dalam hayat,<br/>si-ap ternyata dari diriku ''tia-sa.<br/>Tidak perlu t''ri-ak baru bebas,<br/>tidak perlu tenang diam agama.<br/>Segala-Nya ada pada hayat,<br/>Dia pasti teralir bila aku bebas.<br/>',NULL,65313,2);
INSERT INTO stanza VALUES('I1733','1','Kini kita menikmati Kristus<br/>yang ada dalam kaum saleh.<br/>Lepas sempit picik diri yang<br/>anggap Kristus hanya milikku.<br/>Limpah Kristus, dalam m''reka<br/>yang di dalam kita.<br/>Mari kita menikmati Kristus<br/>yang ada dalam kaum saleh.<br/>',NULL,65314,1);
INSERT INTO stanza VALUES('I1733','chorus','Hai, Saudara, lekas datang,<br/>menikmati s''mua milikmu.<br/>Ka-lau Tuhan dapat bebas,<br/>kita dapat saling nikmat.<br/>Tempuhanku, k''limpahanmu,<br/>kelolamu, suplaianku.<br/>Kita se-mua saling nikmat,<br/>Allah insan sama pu-as.<br/>',NULL,65315,2);
INSERT INTO stanza VALUES('I1733','2','Ku nikmat kau, kau nikmat ku,<br/>baru ta''u Kristus betapa kaya.<br/>Ku suplai kau, kau suplaiku,<br/>baru dapat re-a-li-tas hayat.<br/>Warisan yang Tuhan beri<br/>sungguh kaya limpah.<br/>Kini kita menikmati,<br/>alami hidup yang sangat indah.<br/>',NULL,65316,3);
INSERT INTO stanza VALUES('I1734','1','Hai, Saudara! Ku mau bertanya,<br/>bisakah kau bersaksi.<br/>Suplai rohku, puas-kan hatiku,<br/>hingga aku maju.<br/>Rohku sangat dahaga,<br/>damba disuplai.<br/>Kalau kamu s''mua tutup mulut,<br/>ku tak dapat kenyang.<br/>Sering ku sangat<br/>berharap sa-atnya tiba.<br/>Berhimpun bersama denganmu,<br/>dapat su-plai.<br/>',NULL,65317,1);
INSERT INTO stanza VALUES('I1734','2','Hai, Saudara! Ku ''kan katakan,<br/>ku ada ke-sak-si-an.<br/>Sering ku alami limpah-Nya,<br/>tak habis ku ucap.<br/>Apakah satu ke-sak-si-an<br/>puas-kan-mu?<br/>Kita pamerkan limpah ini,<br/>saling menikmati.<br/>Bukan kami lebih kuat,<br/>tetapi oleh Roh.<br/>Hingga dapat kumpul bersama,<br/>saling suplai.<br/>',NULL,65318,2);
INSERT INTO stanza VALUES('I1735','1','Sa-at kita alami Tuhan<br/>Sang Kasih nan a-jaib.<br/>Sa-at Roh-Nya penuhiku<br/>seperti bara api.<br/>Sa-at Dia wahyukan murad<br/>mu-lia-Nya di hatiku.<br/>Ku bicara ''tuk-Nya.<br/>',NULL,65319,1);
INSERT INTO stanza VALUES('I1735','chorus','Berbicara, haleluya!<br/>Berbicara, haleluya!<br/>Berbicara, haleluya!<br/>Kita berbicara!<br/>',NULL,65320,2);
INSERT INTO stanza VALUES('I1735','2','Tiap latih gunakan rohku,<br/>nikmat s''gala kaya-Nya.<br/>Dalam sidang, depan orang,<br/>atau hidup sen-di-rian.<br/>Ku ''ngalirkan kata indah,<br/>saksikan rawatan-Nya.<br/>Ku bicara ''tuk-Nya.<br/>',NULL,65321,3);
INSERT INTO stanza VALUES('I1735','3','Tuhan ku mau kelola<br/>ke-ka-ya-an batiniku.<br/>Agar hayat-Mu bekerja<br/>hidupkan tiap p''losokku.<br/>Bersekutu, do-a baca firman,<br/>seru nama-Mu.<br/>Ku bicara ''tuk-Mu.<br/>',NULL,65322,4);
INSERT INTO stanza VALUES('I1735','4','Moga roh kita lincah<br/>''ngalir terus dengan bebas.<br/>Ti-ap sidang Tuhan dapat<br/>bergerak le-lu-a-sa.<br/>Tidak lagi turut liturgi,<br/>tradisi yang usang.<br/>Kita s''mua bicara.<br/>',NULL,65323,5);
INSERT INTO stanza VALUES('I1736','1','Dalam gereja har-gai indah-Mu,<br/>kecantikan-Mu tarik kami se-mua.<br/>O, Haleluya! O, haleluya!<br/>Engkau yang tarik kami se-mu-a.<br/>',NULL,65324,1);
INSERT INTO stanza VALUES('I1736','2','Di g''reja temukan rumah indah,<br/>dalam per-hen-tian nikmati kaya-Nya.<br/>O, haleluya! O, haleluya!<br/>Dalam per-hen-tian nikmat kaya-Nya.<br/>',NULL,65325,2);
INSERT INTO stanza VALUES('I1736','3','Dalam g''reja sehati ikut Dia,<br/>hingga karena kita Di-a pu-as.<br/>O, haleluya! O, haleluya!<br/>Hingga karena kita Dia pu-as.<br/>',NULL,65326,3);
INSERT INTO stanza VALUES('I1736','4','Dalam g''reja, kita anggota-Nya,<br/>ti-ap orang berfungsi dengan lincah.<br/>O, haleluya! O, haleluya!<br/>Ti-ap orang berfungsi d''ngan lincah.<br/>',NULL,65327,4);
INSERT INTO stanza VALUES('I1736','5','Dalam g''reja kita saling cinta,<br/>dalamkasih saling menyuplai hayat.<br/>O, haleluya! O, haleluya!<br/>Dalam kasih saling suplai hayat.<br/>',NULL,65328,5);
INSERT INTO stanza VALUES('I1736','6','Dalam g''reja kita tumbuh besar,<br/>capai kepenuhan perawakan-Nya.<br/>O, haleluya! O, haleluya!<br/>Capai ke-p''nuh-an perawakan-Nya.<br/>',NULL,65329,6);
INSERT INTO stanza VALUES('I1736','7','Se-mua milik kita bagi g''reja,<br/>sampai gereja mu-lia mutlak nyata.<br/>O, haleluya! O, haleluya!<br/>Sampai gereja mu-lia ternyata.<br/>',NULL,65330,7);
INSERT INTO stanza VALUES('I1737','1','Firman Tuhan s''mesta alam.<br/>Bawa s''luruh persembahan.<br/>Dalam rumah perbendahara-an,<br/>dengan ini ujilah-Ku.<br/>Tidakkah Ku buka langit,<br/>curahkan berkat bagimu!<br/>''Kan Ku hardik belalang bagimu,<br/>tak rusak hasil tanahmu.<br/>Pohon anggur di ladangmu,<br/>ber-bu-ah lebat bagi-mu.<br/>Bangsa-bangsa sebut kau baha-gia,<br/>tanahmu, negeri ri-ang.<br/>',NULL,65331,1);
INSERT INTO stanza VALUES('I1738','1','Berilah, kami pun di-b''ri,<br/>satu takaran yang cukup.<br/>Diguncang dan tumpah ke-luar,<br/>dicurah ke ri-ba-an-mu.<br/>',NULL,65332,1);
INSERT INTO stanza VALUES('I1739','1','Giranglah! Menyambut kaum saleh!<br/>Giranglah! Menyambut kaum saleh!<br/>Giranglah! Nikmat s''kutu indah!<br/>Nyanyi mulia, haleluya!<br/>Alangkah berkatnya!<br/>',NULL,65333,1);
INSERT INTO stanza VALUES('I1739','2','Giranglah! Menyambut kaum saleh!<br/>Giranglah! Menyambut kaum saleh!<br/>Giranglah! Hidup g''reja limpah!<br/>Nyanyi mu-lia, haleluya!<br/>Hidup g''reja limpah!<br/>',NULL,65334,2);
INSERT INTO stanza VALUES('I1740','1','Sia-pa memihak Dia?<br/>Sambut Sang Raja?<br/>Sia-pa yang diba-rui?<br/>Segar selalu?<br/>Lepas tata cara,<br/>hidup dalam Roh.<br/>Bagi pemulihan,<br/>memihak Tuhan!<br/>Kita memihak Dia,<br/>janganlah tawar.<br/>Dalam roh membara,<br/>pula perkasa!<br/>',NULL,65335,1);
INSERT INTO stanza VALUES('I1741','1','Bagi Dia! Bagi Dia!<br/>Bagi Dia! Bagi Dia!<br/>Bagi pu-li''an g''reja-Nya!<br/>Biar kita! Biar kita!<br/>Biar kita! Biar kita!<br/>Sehati maju perang bersama!<br/>Di-a ada keper-luan,<br/>janganlah a-bai-kan,<br/>Di-a memanggil kita,<br/>mari jawab: Ya! Tuhan!<br/>',NULL,65336,1);
INSERT INTO stanza VALUES('I1741','2','Bagi Dia! Bagi Dia!<br/>Bagi Dia! Bagi Dia!<br/>Bagi ke-sak-sian mu-lia!<br/>Biar kita! Biar kita!<br/>Biar kita! Biar kita!<br/>Sehati membangunlah bersama!<br/>Kita nampak ke-per-luan,<br/>di sinilah kita.<br/>Mari kerja bersama,<br/>sampai Dia marem pu-as.<br/>',NULL,65337,2);
INSERT INTO stanza VALUES('I1742','1','Kini kekristenan,<br/>lembam, pecah, hampa.<br/>Kea-da-an ini,<br/>hanya membuktikan:<br/>hanya diri Kristus,<br/>wujud ke-e-sa-an.<br/>Mem-bu-at hidup<br/>kita mantap bermakna.<br/>',NULL,65338,1);
INSERT INTO stanza VALUES('I1742','2','Kita nampak:<br/>pikiran, emosi, tekad,<br/>s''mua yang dari jiwa,<br/>tak se-su-ai Kristus.<br/>Dia mencipta kita,<br/>jadi bejana-Nya, ''<br/>tia-sa dipenuhi roh<br/>tampilkan Kristus.<br/>',NULL,65339,2);
INSERT INTO stanza VALUES('I1742','3','Tuhan, kami cukup<br/>lama dalam usang,<br/>seperti "rohani"<br/>tapi hilang kasih.<br/>Mari kita tobat,<br/>hidup dalam hayat,<br/>jadi kekasih-Mu,<br/>bagi gereja-Mu.<br/>',NULL,65340,3);
INSERT INTO stanza VALUES('I1742','4','Untuk pe-mu-li''an-Nya,<br/>kita tersisihkan,<br/>lepas ti-puan du-nia,<br/>tolak kesombongan;<br/>kini bagi Kristus,<br/>jadi bejana t''rang,<br/>hingga s''luruh bumi,<br/>nampak mu-lia Allah!<br/>',NULL,65341,4);
INSERT INTO stanza VALUES('I1742','5','Babel telah runtuh,<br/>jangan ragu lagi,<br/>ke-luar dari Babel,<br/>jangan berlambatan!<br/>Pada tum-puan lokal,<br/>tegak bagi Kristus,<br/>kita jadi satu,<br/>bagi ke-sak-sian-Nya.<br/>',NULL,65342,5);
INSERT INTO stanza VALUES('I1742','6','Kini masa kacau,<br/>awan tutup tebal,<br/>mohon Tuhan datang<br/>bawa ke-ra-ja-an.<br/>Yesus matahari,<br/>gereja rembulan,<br/>Yerusalem Baru,<br/>wujudkan mu-lia-Nya.<br/>',NULL,65343,6);
INSERT INTO stanza VALUES('I1743','1','Tersisihlah mutlak,<br/>hidup di g''reja!<br/>Alami limpah-Nya,<br/>tak takut korban.<br/>Putus s''mua rintangan,<br/>terjun arus-Nya.<br/>Penuh suplai hayat,<br/>jadi berkat-Nya.<br/>',NULL,65344,1);
INSERT INTO stanza VALUES('I1743','chorus','Tersisihlah mutlak,<br/>bagi gereja.<br/>Jawab panggil Tuhan,<br/>luaskan k''ra-jaan-Nya.<br/>',NULL,65345,2);
INSERT INTO stanza VALUES('I1743','2','Tersisihlah mutlak,<br/>hidup di g''reja!<br/>Mati ulang mati,<br/>"ego" terenyah!<br/>Hampakan bejana,<br/>remuk depan-Nya;<br/>hingga roh terpenuh,<br/>Kristuslah hayat.<br/>',NULL,65346,3);
INSERT INTO stanza VALUES('I1743','3','Tersisihlah mutlak,<br/>bagi murad-Nya!<br/>Tempuh jalan Tuhan,<br/>tenaga tambah.<br/>Penuh mu-lia, ri-a,<br/>majulah saja;<br/>dalam pimpinan-Nya,<br/>saksi gerak-Nya.<br/>',NULL,65347,4);
INSERT INTO stanza VALUES('I1743','4','Tersisihlah mutlak,<br/>sampai s''lamanya;<br/>tak lagi ma-u-ku,<br/>tapi murad-Nya.<br/>Cita, rencanaku,<br/>lenyap kar''na Dia;<br/>tak ber-ba-gian du-nia,<br/>punya segala.<br/>',NULL,65348,5);
INSERT INTO stanza VALUES('I1743','5','Tersisihlah mutlak,<br/>hidup di g''reja!<br/>Nampak murad Tuhan,<br/>roh ''ngaso amat.<br/>Terus garap Kristus,<br/>seru nama-Nya;<br/>insan baru nyata,<br/>demi roh kobar.<br/>',NULL,65349,6);
INSERT INTO stanza VALUES('I1743','6','Nempuh hidup g''reja,<br/>rohku penuh Dia;<br/>berkat dan tumbuhku<br/>pada gereja.<br/>Visi batiniah,<br/>makinlah terang;<br/>hidup bagi g''reja,<br/>sambut balik-Nya!<br/>',NULL,65350,7);
INSERT INTO stanza VALUES('I1744','1','Aku mau kehendak Allah genap,<br/>ini tekad tunggalku.<br/>La-in-nya, ku tidak tahu apa,<br/>hanya harap Di-a puas.<br/>Biar api du-nia hari depanku,<br/>atasku rugi hilang.<br/>Ti-ap titik hidup ini,<br/>se-mu-a bagi Tuhan saja.<br/>',NULL,65351,1);
INSERT INTO stanza VALUES('I1744','2','Biar orang gi-at membangun kota,<br/>untuk hidup yang nyaman.<br/>Biar orang nikmati pelesiran,<br/>mencari senang du-nia.<br/>Biar orang mem-bu-at peralatan,<br/>untuk du-nia bisnisnya.<br/>Aku hanya untuk Tuhan,<br/>mutlak tak tunduk pada du-nia.<br/>',NULL,65352,2);
INSERT INTO stanza VALUES('I1744','3','Ku nampak Kristus mu-lia yang bangkit,<br/>ternyata lewat aku.<br/>Ku nampak kua-sa na-ik surga-Nya,<br/>bergerak di dalamku.<br/>Ku nampak kua-sa unggul<br/>takhta-Nya terwujud di diriku.<br/>Aku nampak Dia-lah s''gala,<br/>pun segala dari hayatku.<br/>',NULL,65353,3);
INSERT INTO stanza VALUES('I1745','1','Ka-lau untuk rohani-"ku",<br/>ku tak layak menuntut.<br/>Pengalaman rohaniku,<br/>untuk membangun g''reja.<br/>',NULL,65354,1);
INSERT INTO stanza VALUES('I1745','chorus','S''mua untuk g''reja,<br/>s''mua untuk g''reja.<br/>S''luruh diri dan milikku,<br/>s''mua untuk g''reja.<br/>',NULL,65355,2);
INSERT INTO stanza VALUES('I1745','2','Kalau hanya "terang", "wahyu",<br/>Kau tutuplah diri-Mu.<br/>S''mua pengenalan t''radap-Mu,<br/>untuk membangun g''reja.<br/>',NULL,65356,3);
INSERT INTO stanza VALUES('I1745','3','Kalau hanya "ka-ru-nia Roh",<br/>Kau tariklah berkat-Mu;<br/>Moga rohku terus penuh,<br/>untuk membangun g''reja.<br/>',NULL,65357,4);
INSERT INTO stanza VALUES('I1745','4','Kalau hanya "hasil kerja",<br/>Kau bongkarlah hasilnya;<br/>Moga s''mua jerih lelahku,<br/>hanya ''tuk bangun g''reja.<br/>',NULL,65358,5);
INSERT INTO stanza VALUES('I1745','5','Kalau hanya "kedudukan",<br/>biar ku merasa malu;<br/>Mohon Tuhan t''rus terangi,<br/>murni ''tuk bangun g''reja.<br/>',NULL,65359,6);
INSERT INTO stanza VALUES('I1746','1','Ke tangan-Mu kini serahkan diriku,<br/>harapan bagi g''reja melulu.<br/>Entah susah, entah d''rita hari depanku.<br/>Apa sesalku bagi gereja-Mu!<br/>',NULL,65360,1);
INSERT INTO stanza VALUES('I1746','2','Tuhan, dalam kasih kita padu esa.<br/>Bersama bagi pe-mu-li''an g''reja.<br/>Meski jalan kita tak lain penuh air mata.<br/>Kalau Tuhan k''hendaki, sangat mesra!<br/>',NULL,65361,2);
INSERT INTO stanza VALUES('I1747','1','Tuhan ku mau korban diri,<br/>untuk bangun gereja-Mu;<br/>Sayang kurang mengenal-Mu,<br/>kurang peng-a-lam-an ri-il.<br/>',NULL,65362,1);
INSERT INTO stanza VALUES('I1747','chorus','Kini aku t''lah bertekad,<br/>ma-u mutlak kenal Kristus;<br/>Nikmat dan alami Kristus,<br/>demi menyu-plai gereja.<br/>',NULL,65363,2);
INSERT INTO stanza VALUES('I1747','2','Kristus ada di dalamku,<br/>Dia-lah sumber juga arus;<br/>Lebih banyak mengalami,<br/>baru bisa su-plai yang lain.<br/>',NULL,65364,3);
INSERT INTO stanza VALUES('I1747','3','Tak cukup "mengenal Kristus",<br/>harus praktek dalam hidup,<br/>Makin praktek, makin korban,<br/>makin dalam, makin mutlak.<br/>',NULL,65365,4);
INSERT INTO stanza VALUES('I1747','4','Meski belum duduk surga,<br/>penuh Roh, rasa terangkat;<br/>Meski tetap dalam daging,<br/>alami mati dan bangkit.<br/>',NULL,65366,5);
INSERT INTO stanza VALUES('I1747','5','Ku nikmat Dia, Dia nikmatku,<br/>ku dapat Dia, Dia dapatku;<br/>Kita saling menikmati,<br/>pengalaman limpah pasti.<br/>',NULL,65367,6);
INSERT INTO stanza VALUES('I1747','6','Mau berkorban, bayar harga,<br/>kenal Kristus Sang Mustika;<br/>Bagiku se-mua p''ri sampah,<br/>ku mau dapat Kristus s''mata.<br/>',NULL,65368,7);
INSERT INTO stanza VALUES('I1748','1','Dunia bukan rumahku,<br/>tetapi g''reja,<br/>hidup dan hartaku,<br/>se-mua untuk g''reja.<br/>Perkara du-ni-a<br/>se-mua si-a si-a,<br/>kalau tak ''tuk g''reja,<br/>terhambur di du-nia.<br/>Tuhan! Hatiku<br/>hanya ''tuk g''reja,<br/>luas-kan K''ra-ja-an-Mu,<br/>terapkan kua-sa-Mu.<br/>Diri dan milikku<br/>tak lagi ''tuk du-nia,<br/>sejak kini ku hidup<br/>hanya ''tuk g''reja.<br/>',NULL,65369,1);
INSERT INTO stanza VALUES('I1749','1','Tuhan, kami s''mua di sini,<br/>nyatakan tekad kami.<br/>Bagi pe-mu-li''an g''reja-Mu,<br/>kami erat bersatu.<br/>Kami bersama mend''rita,<br/>bersama pikul beban.<br/>Pula bersama berkorban,<br/>sam-pai kedatangan-Mu.<br/>Tuhan kabulkan niat ini,<br/>sandar-Mu hingga akhir.<br/>Oleh kami Tuhan pu-as,<br/>kehendak-Mu tergenap.<br/>',NULL,65370,1);
INSERT INTO stanza VALUES('I1750','1','Kini ku tinggalkan se-mua,<br/>pikul salib buat g''reja.<br/>Rela miskin, d''rita hina,<br/>''nempuh jalan sempit-Nya.<br/>Dulu yang ku tuntut damba,<br/>kini musnah terbenam.<br/>Namun alangkah bah''gianya,<br/>Kristus g''reja milikku.<br/>',NULL,65371,1);
INSERT INTO stanza VALUES('I1750','2','Biar du-nia, benci, tolakku,<br/>g''reja bukan miliknya.<br/>Dalam du-nia penuh tipu,<br/>g''reja baru rea-li-tas.<br/>Sa-at ku hidup di g''reja,<br/>walau pencil terancam.<br/>Hati tetap sejahtera,<br/>ku nampak g''reja mu-lia.<br/>',NULL,65372,2);
INSERT INTO stanza VALUES('I1750','3','Enyah tenar, untung, du-nia!<br/>Mari ce-mooh dan d''rita.<br/>Rugi, d''rita bu-at Tuhan,<br/>justru untung dan nyaman.<br/>Dia ku panggil "Abba Bapa",<br/>hatiku pun pada-Nya.<br/>Angin ribut, awan tebal,<br/>bawa fae-dah bagiku.<br/>',NULL,65373,3);
INSERT INTO stanza VALUES('I1750','4','Meski orang meng-a-nia-ya,<br/>minatku tidak ubah.<br/>Sengsara ki-an menekan,<br/>hidup g''reja kian mesra.<br/>Apa arti duka luka,<br/>depan wajah mu-li-a.<br/>Apa arti suka ri-a,<br/>bila bukan gereja.<br/>',NULL,65374,4);
INSERT INTO stanza VALUES('I1750','5','Maju! Masuk dalam mu-lia,<br/>alami kua-sa Tubuh.<br/>Limpah-Nya re-a-li-tas-ku,<br/>bagi-Nya s''mua hidupku.<br/>Hingga ministri terhenti,<br/>hingga mencapai akhir.<br/>Hingga harapan terbukti,<br/>''ngitar takhta memuji.<br/>',NULL,65375,5);
INSERT INTO stanza VALUES('I1751','1','Yesus tersayang, Yesus tersayang,<br/>Yesus hayatku, jaminanku.<br/>Yesus tersayang, Yesus tersayang,<br/>haleluya! Dia sayangku!<br/>',NULL,65376,1);
INSERT INTO stanza VALUES('I1751','2','Saudara sayang, saudari sayang,<br/>berhayat Tuhan, mu-lia Tuhan.<br/>Saudara sayang, saudari sayang,<br/>haleluya! G''reja sayang!<br/>',NULL,65377,2);
INSERT INTO stanza VALUES('I1752','1','Semi, rontok berselingan,<br/>waktu larut layang.<br/>Umur kita amat pintas,<br/>jangan sia-sia hamburkan.<br/>Mumpung sekarang (mumpunglah muda),<br/>bagi gereja.<br/>Moga s''panjang u-sia kita,<br/>hanya untuk gereja.<br/>',NULL,65378,1);
INSERT INTO stanza VALUES('I1801','chorus','Masuk arus pemulihan,<br/>berba-gian ekonomi-Nya.<br/>Masuk pelayanan Tubuh, bangun,<br/>g''napkan kehendak-Nya.<br/>Bangun, g''napkan kehendak-Nya,<br/>bangun, g''napkan kehendak-Nya.<br/>Bangun, g''napkan kehendak-Nya.<br/>Giranglah!<br/>Nikmat du-nia seg''ra lewat,<br/>kehendak-Nya teguh s''lama.<br/>Kita tidak rela gagal,<br/>kita mau terbangun bersama,<br/>tak terpisah.<br/>',NULL,65379,1);
INSERT INTO stanza VALUES('I1801','1','Dulu terhambur di du-nia,<br/>tak peduli gerakan-Nya.<br/>Yang dituntut im-pian b''laka,<br/>p''ri memegang bayang.<br/>Se-mu-a, si-a si-a.<br/>',NULL,65380,2);
INSERT INTO stanza VALUES('I1801','2','Kini mendapat rahmat-Nya,<br/>kasih-Nya bawa ke rumah.<br/>Terjun dalam kelola-Nya,<br/>hidup pun bermakna.<br/>Mantaplah, p''nuh rea-li-tas.<br/>',NULL,65381,3);
INSERT INTO stanza VALUES('I1802','1','Raja kita agung, mu-lia,<br/>bertakhta di atas langit.<br/>Bumi bentang di duli-Nya,<br/>se-mua bangsa Dia kendali.<br/>Tengah umat-Nya Dia tinggal,<br/>sama pikul sama jinjing.<br/>Kerja sama dengan Raja,<br/>mu-lia mana yang bertanding.<br/>',NULL,65382,1);
INSERT INTO stanza VALUES('I1802','2','Kerja sama dengan Raja,<br/>bagilah Dia bukan aku.<br/>Dengan mu-lia ku digarap,<br/>lewat kami yang lain hidup.<br/>Kerja sama dengan Raja,<br/>kuat kua-sa-Nya menopang t''rus.<br/>Kewajiban jadi ringan,<br/>do-a jadi kidung syukur.<br/>',NULL,65383,2);
INSERT INTO stanza VALUES('I1802','3','Kerja sama dengan Raja,<br/>Injil mu-lia siar tak henti.<br/>Selamatkan lak-saan jiwa,<br/>tarik K''ra-ja-an ke bumi.<br/>Apa pun upah du-ni-a,<br/>kami tak ma-u peduli.<br/>Tugas m''lulu garap orang<br/>untuk si-ap-kan mempelai.<br/>',NULL,65384,3);
INSERT INTO stanza VALUES('I1802','4','Kerja sama, jangan lengah,<br/>hari-hari ''tia-sa garap.<br/>Seb''lum musim dingin tiba,<br/>mungkin Raja sudah datang.<br/>Kita akan kitari-Nya, puji,<br/>ri-ang, sorak, lonjak.<br/>Haleluya! M''raja s''rentak!<br/>Haleluya! Sampai kekal!<br/>',NULL,65385,4);
INSERT INTO stanza VALUES('I1803','1','Ku tak pernah sesal,<br/>jawab panggil-Nya.<br/>Ku tak pernah sesal,<br/>sembahkan se-mua.<br/>Berjalan dengan-Nya,<br/>ki-an memuncak.<br/>Ku tak pernah sesal,<br/>se-ti-ap langkah.<br/>',NULL,65386,1);
INSERT INTO stanza VALUES('I1804','1','Pagi, orang kerja,<br/>si-ang orang kerja;<br/>tapi aku ''nganggur,<br/>baru dipanggil.<br/>Ku a-bai-kan pagi,<br/>ku hamburkan si-ang;<br/>Dia tetap memilih,<br/>o, t''rima kasih!<br/>',NULL,65387,1);
INSERT INTO stanza VALUES('I1804','chorus','Demilah kasih,<br/>kerja d''ngan baik!<br/>Kasih kur-nia berkat,<br/>tak rasa d''rita!<br/>Ayo, sau-dara!<br/>Ayo, saudari!<br/>Satu jam yang sisa,<br/>mari giat kerja!<br/>',NULL,65388,2);
INSERT INTO stanza VALUES('I1804','2','Aku paling akhir,<br/>berbangga tak patut;<br/>atas ke-se-tia-an,<br/>ku di-am tunduk.<br/>Tapi Kau perahmat,<br/>angkat kepalaku;<br/>"kasih" menjamahku,<br/>s''lalu pandang-Mu.<br/>',NULL,65389,3);
INSERT INTO stanza VALUES('I1804','3','Tak perlu berk''ringat,<br/>yang lain t''lah menanam;<br/>tak perlu menangis,<br/>Roh-Nya t''lah kerja.<br/>Waktunya tak banyak,<br/>tugas amat ringan;<br/>kita tinggal ''nu-ai,<br/>gi-at-lah kerja!<br/>',NULL,65390,4);
INSERT INTO stanza VALUES('I1805','1','Kristus maju berkuda!<br/>G''reja lokal muncul!<br/>Sejak kini gereja<br/>menjadi rumah-Mu.<br/>Dalam roh kami hiduplah,<br/>ku-at oleh hayat-Mu.<br/>Kristus maju berkuda,<br/>pu-ji-an membubung.<br/>',NULL,65391,1);
INSERT INTO stanza VALUES('I1806','1','Majulah! Majulah!<br/>Di dalam Roh majulah!<br/>Haleluya d''ngan g''reja maju.<br/>Majulah! Majulah!<br/>Di dalam Roh majulah!<br/>Haleluya d''ngan g''reja maju.<br/>Kita t''lah nampak pemulihan g''reja,<br/>maju d''ngan Roh tujuh ganda!<br/>Di mana-mana biar s''mua orang tahu,<br/>zaman ini Tuhan t''rus maju!<br/>Zaman ini Tuhan t''rus maju!<br/>',NULL,65392,1);
INSERT INTO stanza VALUES('I1807','1','"Yang baru" muncul,<br/>kaum sa-leh majulah.<br/>Lihat! Mu-lia-Nya nyata di bumi!<br/>Tanda pemu-li''an g''reja,<br/>s''mua aspeknya tertampak.<br/>Haleluya! "Yang baru" muncul.<br/>',NULL,65393,1);
INSERT INTO stanza VALUES('I1808','1','Mu-lai dari kota Sabang,<br/>sampai kota Me-rau-ke.<br/>Dalam ke-ba-ruan roh kita,<br/>berperang bagi Tuhan.<br/>Sebar luas-kan ke-sak-si-an<br/>gereja lokal Tuhan.<br/>Terjang maju t''rus ke depan,<br/>j''la-jah-I ti-ap kota!<br/>Inilah pemulihan-Nya<br/>dan pergerakan Tuhan.<br/>Kita harus se-ia s''ka-ta,<br/>t''rus maju demi Tuhan.<br/>',NULL,65394,1);
INSERT INTO stanza VALUES('I1809','1','Ku-at dalam-Nya!<br/>Sandar kuat kua-sa Tuhan,<br/>ku-at dalam-Nya!<br/>Ku-at dalam-Nya!<br/>Sandar kuat kua-sa Tuhan,<br/>ku-at dalam-Nya!<br/>Ku-at dalam-Nya!<br/>Sandar kuat kua-sa Tuhan!<br/>D''ngan s''ragam lengkap,<br/>tolak muslihat setan!<br/>Ku-at dalam-Nya!<br/>Ku-at dalam-Nya!<br/>Sandar ku-at ku-a-sa Tuhan!<br/>',NULL,65395,1);
INSERT INTO stanza VALUES('I1810','1','Menang p''rang bagi Tuhan,<br/>hidup bagi-Nya, di gereja!<br/>Tak takut s''rangan lawan,<br/>bersandar Tuhan, menginjaknya!<br/>Ber-do-a agar hidup g''reja,<br/>se-mua membara di dalam roh.<br/>P''rang dalam insan baru,<br/>ca-pai tu-juan Allah!<br/>(Mulia, haleluya!)<br/>',NULL,65396,1);
INSERT INTO stanza VALUES('I1811','1','Ku tak berani gagal<br/>demi g''reja mu-lia.<br/>Kristuslah Kepalanya,<br/>di langit ke tiga.<br/>Hidup dalam visi-Nya,<br/>ku tegap ti-a-sa.<br/>Kini aku pemenang<br/>bagi puli''an g''reja.<br/>',NULL,65397,1);
INSERT INTO stanza VALUES('I1811','chorus','Menang, pemenang!<br/>Demi g''reja mu-lia.<br/>Kini aku pemenang,<br/>demilah, demilah gereja.<br/>',NULL,65398,2);
INSERT INTO stanza VALUES('I1811','2','Ku tak berani gagal<br/>demi Kristus mu-lia.<br/>Panggilan garis depan,<br/>nikmati menang-Nya.<br/>Kini hatiku besar;<br/>roh ku-at perkasa.<br/>Kini aku pemenang,<br/>terpenuhi Tuhan.<br/>',NULL,65399,3);
INSERT INTO stanza VALUES('I1811','3','Ku tak berani gagal<br/>demi perang g''reja.<br/>Alam ma-ut didobrak,<br/>murad Allah genap.<br/>Kita se-mu-a laskar,<br/>tangkas bersenjata.<br/>Bersama s''mua pemenang,<br/>saksikan firman-Nya.<br/>',NULL,65400,4);
INSERT INTO stanza VALUES('I1811','4','Ku tak berani gagal<br/>sa-at jelang menang.<br/>Raja mu-lia ''kan tiba,<br/>b''ri puji hamba-Nya.<br/>Sama hidup di surga,<br/>gunakan kua-sa-Nya.<br/>Hari ke hari menang,<br/>menang sampai kekal.<br/>',NULL,65401,5);
INSERT INTO stanza VALUES('I1812','1','Sudah menang!<br/>Kristus t''lah kalahkan musuh!<br/>Sua-ra menang menggetar hingga jauh!<br/>Demi darah,<br/>kita pasti menanglah t''rus!<br/>Tuhan Pemenang seg''ra terwujud.<br/>',NULL,65402,1);
INSERT INTO stanza VALUES('I1812','chorus','(Suara saudari)<br/>Sudah menang, hai s''mua saudara!<br/>Sudah menang, bersoraklah!<br/>Proklamirkanlah kemenangan-Nya,<br/>dari Sion ke mana-mana!<br/>(Suara saudara)<br/>Sudah menang, hai s''mua saudari!<br/>Kehendak Allah genaplah!<br/>Dialah Pemenang, musuh t''lah kalah!<br/>Marilah bersuka-ri-a!<br/>',NULL,65403,2);
INSERT INTO stanza VALUES('I1812','2','Sudah menang!<br/>Musuh t''lah kita kalahkan!<br/>Dengan b''rani saksikan firman-Nya.<br/>Firman hidup<br/>beri hayat dan tenaga.<br/>Hingga kita sanggup ''nantang lawan.<br/>',NULL,65404,3);
INSERT INTO stanza VALUES('I1812','3','Sudah menang!<br/>Musuh sudah kita injak.<br/>Kar''na kita tidak sayang jiwa. Tuhan Yesus,<br/>Kaulah mem-buat kita menang!<br/>Mu-lia! Mu-lia!<br/>Pu-ji-an tak sudah!<br/>',NULL,65405,4);
INSERT INTO stanza VALUES('I1813','1','Puji Tuhan, di dalam Kristus kita<br/>m''nang mutlak!<br/>Segala se-sua-tu mendatangkan<br/>ke-ba-ik-an.<br/>Gereja pilihan-Nya,<br/>se-suai dengan maksud-Nya.<br/>Awal menang, mutlak menang,<br/>hakikinya menang!<br/>Meski musuh benci,<br/>selalu menyerang.<br/>Susah, d''rita, tekan,<br/>lapar dan telanjang.<br/>Sandar Tuhan,<br/>menang mutlak atas se-mu-a.<br/>Menang! Sudahlah menang mutlak!<br/>Sudahlah menang mutlak!<br/>Sudahlah menang mutlak!<br/>Puji Tuhan, di dalam Kristus<br/>kita m''nang mutlak!<br/>Segala se-sua-tu mendatangkan<br/>ke-ba-ik-an.<br/>Gereja pilihan-Nya,<br/>se-suai dengan maksud-Nya.<br/>Awal menang, mutlak menang,<br/>hakikinya menang!<br/>',NULL,65406,1);
INSERT INTO stanza VALUES('I1814','1','Kini kita dalam<br/>kemenangan Tuhan.<br/>Tak perlu kita meronta,<br/>berusaha.<br/>Nikmati saja dalam<br/>roh dan ambillah.<br/>Rea-li-tas kemenangan.<br/>Mengapa tak memuji<br/>kemenangan-Nya!<br/>Kita sudah terangkat<br/>bersama Tuhan!<br/>T''rangkat dalam roh<br/>ke langit tingkat tiga!<br/>Iblis di bawah kita.<br/>Kita ber-ba-gian<br/>dalam kemenangan-Nya.<br/>Kemenangan ini tak<br/>putus s''lamanya.<br/>Dapatkah ku gagal,<br/>lemah, putus asa?<br/>Ku nikmati menang-<br/>',NULL,65407,1);
INSERT INTO stanza VALUES('I1815','1','Ku manu-sia,<br/>aku makna alam semesta,<br/>ku ma-nu-sia<br/>aku makna alam semesta.<br/>Allah buat-ku (allah buat-ku),<br/>sedemikian (sedemikian).<br/>Akulah makna dan pusat alam semesta.<br/>',NULL,65408,1);
INSERT INTO stanza VALUES('I1815','2','Ada Kristus,<br/>Dia adalah makna hidupku!<br/>Ada Kristus,<br/>Dia adalah makna hidupku!<br/>Diri Kristus, (diri Kristus),<br/>segalaku (segalaku).<br/>Dia-lah isi, rea-li-tas, dan makna hidupku.<br/>',NULL,65409,2);
INSERT INTO stanza VALUES('I1815','3','G''reja itu,<br/>pe-nya-ta-an Kristus di bumi!<br/>G''reja itu,<br/>pe-nya-ta-an Kristus di bumi!<br/>Perhimpunan, (perhimpunan),<br/>wakil Allah (wakil Allah).<br/>Ber-kua-sa di bumi, genapkan rencana-Nya.<br/>',NULL,65410,3);
INSERT INTO stanza VALUES('I1815','4','G''reja lokal,<br/>kehidupan insan korporat!<br/>G''reja lokal,<br/>kehidupan insan korporat!<br/>Hidup kita (hidup kita), ada jalan (ada jalan).<br/>Makan, minum Kristus, terbangunlah gereja.<br/>',NULL,65411,4);
INSERT INTO stanza VALUES('I1815','5','Bagaimana?<br/>Seg''ra beri tahu yang la-in!.<br/>Bagaimana?<br/>Seg''ra beri tahu yang la-in!.<br/>Bangsa-bangsa, (bangsa-bangsa), jadi murid (jadi murid).<br/>Mari siar-kan b''rita ini ke s''luruh du-nia.<br/>',NULL,65412,5);
INSERT INTO stanza VALUES('I1816','1','Pernahkah pikir dan tahu,<br/>perihal terciptamu?<br/>Apakah tu-ju-an hidup<br/>kini  tengah kau tempuh?<br/>Allah mau jadi hayatmu,<br/>mau jadi hayatmu,<br/>mau jadi hayatmu!<br/>Kau ini wadah cipta-an Hu,<br/>terisi Hu, nyatakan Hu!<br/>',NULL,65413,1);
INSERT INTO stanza VALUES('I1816','2','Batinmu ada terkandung<br/>roh di dalam lubukmu.<br/>Hatimu me-mu-at penuh,<br/>roh tetaplah melompong!<br/>Bertahun-tahun kecewa t''rus,<br/>kecewalah terus,<br/>kecewalah terus.<br/>Sekarang bukalah dirimu,<br/>sambut Yesus biar Dia masuk!<br/>',NULL,65414,2);
INSERT INTO stanza VALUES('I1816','3','Adakah se-o-rang insan,<br/>tak pernah ber-buat dosa?<br/>Darah Yesus t''lah tercurah,<br/>cuci bersih dosamu!<br/>Jurus''lamat genapkan se-mua,<br/>tak perlu jasamu,<br/>tak perlu jasamu.<br/>Di-a Sang Roh, terima saja,<br/>masuk menjadi hayatmu!<br/>',NULL,65415,3);
INSERT INTO stanza VALUES('I1816','4','Seperti tubuh jasmani<br/>untuk tampilan lu-ar.<br/>Di lubukmu terdapat<br/>roh untuk di-i-si Tuhan.<br/>Kini sa-atnya kau terbuka,<br/>biar-kan Tuhan masuk,<br/>penuhi hatimu.<br/>Kini sa-at-nya kau terbuka,<br/>seru Tuhan, biar Dia masuk!<br/>',NULL,65416,4);
INSERT INTO stanza VALUES('I1817','1','Pernahkah pikir dan tahu,<br/>kes''lamatan dirimu?<br/>Apakah rencana Allah?<br/>Mengapa menebusmu?<br/>Hingga kini, kita s''mua tahu,<br/>"Kristus di dalamku".<br/>Ini indah sungguh.<br/>Tapi wahyu-Nya lebih dalam,<br/>murad-Nya harus tergenap.<br/>',NULL,65417,1);
INSERT INTO stanza VALUES('I1817','2','A-ir sungai Taman Eden,<br/>mendiris, suplai hayat.<br/>Penebusan-Nya p''ri a-ir<br/>lewati pengalaman.<br/>Pertama lepas kua-sa Iblis,<br/>lalu lepas dari belenggu agama.<br/>Pemulihan Allah t''rus maju,<br/>tak putus di tengah jalan.<br/>',NULL,65418,2);
INSERT INTO stanza VALUES('I1817','3','Bukan hanya perorangan,<br/>sen-di-ri-an terserak.<br/>Batu hidup terbangunkan,<br/>Tubuh Kristus tertampak.<br/>Lahir ulang menjadi baru,<br/>Kristus di hatimu,<br/>ada maksud la-in.<br/>Di-a menjadi hayat kita,<br/>untuk dapat mempelai-Nya.<br/>',NULL,65419,3);
INSERT INTO stanza VALUES('I1817','4','Bukan permata berkeping,<br/>perorangan rohani.<br/>Tapi dalam hayat kita<br/>dibangunkan bersama.<br/>Selamanya kau takkan pu-as,<br/>jika Kristus tidak<br/>dapatkan memp''lai-Nya.<br/>Tahukah kau,<br/>Tuhan sekarang,<br/>menantimu dibangunkan!<br/>',NULL,65420,4);
INSERT INTO stanza VALUES('I1818','1','Apakah makna hidup?<br/>Inilah jawabannya!<br/>Cobalah s''ru,<br/>"O, Yesus!"<br/>Dia itulah rea-litas!<br/>Hayat-Nya limpah sungguh,<br/>air hayat su-plai pancar.<br/>Mu-lailah hidup baru,<br/>ri-ang tak kesudahan.<br/>Kasih pun bertambah t''rus,<br/>tak la-in-lah kar''na Dia!<br/>Haleluya! Cobalah s''ru,<br/>"O, Yesus!" Dia itulah rea-litas!<br/>Hayat-Nya limpah sungguh,<br/>air hayat su-plai pancar.<br/>Mu-lailah hidup baru,<br/>ri-ang tak kesudahan.<br/>Kasih pun bertambah t''rus,<br/>tak la-in-lah kar''na Dia!<br/>',NULL,65421,1);
INSERT INTO stanza VALUES('I1819','1','Kami pernah cari ke penjuru du-nia;<br/>apa makna hidup manu-sia?<br/>Tapi kami terus menerus kecewa,<br/>tahu du-nia, hanya demi-kian.<br/>Hingga suatu hari, Kau temukan kami,<br/>di ri-ba-an-Mu, rebah kami.<br/>Ke-in-dah-an-Mu memikat hati kami,<br/>dapat arti hidup sejati.<br/>',NULL,65422,1);
INSERT INTO stanza VALUES('I1819','2','Kami nampak wajah mu-lia kebangkitan,<br/>ingat Kau bermahkota duri.<br/>Tangan kasih-Mu adalah sandaranku,<br/>dengan bebas luka terpaku.<br/>Kini kami nikmat diri-Mu nan manis,<br/>makin rasa kau sungguh ri-il.<br/>Seperti air sungai mengalir ke la-ut,<br/>diriku ''kan lenyap dalam-Mu.<br/>',NULL,65423,2);
INSERT INTO stanza VALUES('I1820','1','O, di mana engkau, tiap hari sibuk lelah.<br/>Namun hidup rasa hampa belaka!<br/>Pernah ''ngejar segala, namun ti-a-da pu-as.<br/>Rasa berkurang saja, berkurang saja!<br/>',NULL,65424,1);
INSERT INTO stanza VALUES('I1820','chorus','Tuhan Yesuslah kau butuhkan!<br/>Mari nikmati k''limpahan-Nya!<br/>Hatimu tak pernahlah pu-as. Namun<br/>Di-a sanggup, sanggup memu-as-kan!<br/>',NULL,65425,2);
INSERT INTO stanza VALUES('I1820','2','O, kau cukup ada, segala telah punya.<br/>Tapi tetap rasa, rasa tak pu-as!<br/>Usahamu sukseslah, pendidikan tak kurang.<br/>Namun dalam batin terasa berkurang<br/>',NULL,65426,3);
INSERT INTO stanza VALUES('I1821','1','(T)<br/>Teman! Teman!<br/>Jelaskanlah,<br/>sebab apa kau gembira?<br/>Mengapa s''lalu berseri,<br/>p''ri pancaran hidup ''ngalir?<br/>(J)<br/>Karena Yesus Tuhanku,<br/>t''lah korban pikul dosaku.<br/>Lewat salib, menebusku,<br/>se-mu-a dosa terhapus.<br/>(B) La, la, la, ... (1x)<br/>',NULL,65427,1);
INSERT INTO stanza VALUES('I1821','2','(T)<br/>Hai, teman, jelaskan lagi,<br/>sungguhkah kau de-mi-ki-an?<br/>Meski dosaku terhapus,<br/>hidupku masihlah kurang.<br/>(J)<br/>O, Tuhanku sungguh limpah,<br/>tak mampu ku jelaskan s''mua.<br/>Dia bangkit, jadi hayatku,<br/>tenaga, dan suplaianku.<br/>(B) La, la, la, ... (1x)<br/>',NULL,65428,2);
INSERT INTO stanza VALUES('I1821','3','(T)<br/>A-jaib sungguh yang kau dapat,<br/>dosa t''ram-pun, t''rima hayat.<br/>Tapi sep''ri aku ini,<br/>bisakah menikmatinya?<br/>(J)<br/>Marilah kenal kasih-Nya,<br/>Dia sedang tunggu kau datang.<br/>Dia ingin b''rikan tebusan,<br/>jadi hayat, Penolongmu.<br/>(B) La, la, la, ... (1x)<br/>',NULL,65429,3);
INSERT INTO stanza VALUES('I1821','4','(T)<br/>Teman, teman, ku mau buka,<br/>pintu hati biar Dia masuk.<br/>Penebusan, hayat, kua-sa,<br/>sumber ri-ang ''ngaliriku.<br/>(J)<br/>Hai, saudara mari datang,<br/>sekarang menikmati Dia.<br/>Orang dosa t''rima kur-nia,<br/>puji syukur kasih Tuhan.<br/>(B) La, la, la, ... (1x)<br/>(T)= tanya;<br/>(J)= jawab;<br/>(B)= bersama<br/>',NULL,65430,4);
INSERT INTO stanza VALUES('I1822','1','Pernah ku rasa hampa,<br/>hidup ini untuk apa?<br/>Betapa semu hidup ini,<br/>lahir tersenyum,<br/>batin ''nangis.<br/>Rasa getir ini tak terpaham,<br/>bi-us orang.<br/>Entah kapan, si-um-an.<br/>',NULL,65431,1);
INSERT INTO stanza VALUES('I1822','2','Meski aku tak tahu,<br/>membereskan dan ber-do-a.<br/>Tapi lubukku damba s''lalu,<br/>ingin mencari makna hidup.<br/>Sua-tu hari seru,"Tuhan Yesus!"<br/>Dia pun masuk.<br/>Hampa, d''rita, sirnalah.<br/>',NULL,65432,2);
INSERT INTO stanza VALUES('I1822','3','Yesus hidup dalamku,<br/>jadi Tuhan dan hayatku!<br/>Demi menyeru nama Yesus,<br/>hayat, damai, semakin penuh.<br/>Di bumi tia-da yang ku dambakan,<br/>ku t''lah pu-as.<br/>Telah dapat Yesusku.<br/>',NULL,65433,3);
INSERT INTO stanza VALUES('I1823','1','Bila kau merasa sepi,<br/>resah, Yesus, Yesus.<br/>Dia sertamu:<br/>Bila kau rasa gelap,<br/>se-mua kabur.<br/>Yesus, Yesus,<br/>Dia terangmu.<br/>Bila berpaling pada-Nya,<br/>lepas beban,<br/>Dia pasti menanggungnya<br/>Dia besertamu.<br/>Jangan cari jawaban,<br/>sia-sia, harap,<br/>Yesus, Yesus,<br/>Dia jawabnya:<br/>Dari batinmu, berseru,<br/>Dia tak la-lai!<br/>Sa-at jumpa coba-an,<br/>ingatlah ''tia-sa:<br/>Wa-lau bumi penuh<br/>dengan masalah,<br/>Yesus, Yesus,<br/>Dia-lah Tuhan.<br/>',NULL,65434,1);
INSERT INTO stanza VALUES('I1824','1','Mendapat banyak ni-an<br/>yang kamu minta.<br/>Sandang, pangan, papan, hiburan;<br/>se-t''lah dapat, bia-sa saja.<br/>',NULL,65435,1);
INSERT INTO stanza VALUES('I1824','2','Bekerja gai-rah<br/>senang hanya sekejap.<br/>Benci usang, harap yang baru;<br/>tapi nyata, tia-da baru.<br/>',NULL,65436,2);
INSERT INTO stanza VALUES('I1824','3','Hidup ba-gai angin lalu,<br/>buru-buru.<br/>Sibuk tiap hari,<br/>hasilnya si-a si-a melulu.<br/>Kau minta adakah<br/>yang memu-askanmu.<br/>Walau dapat banyak tak<br/>bisa bereskan duka hatimu.<br/>',NULL,65437,3);
INSERT INTO stanza VALUES('I1824','4','Ada satu hal yang<br/>belum engkau tempuh.<br/>Se-mua yang pernah kau<br/>minta t''lah kau dapatkan se-mua.<br/>Dia Tuhan - Dia-lah<br/>re-a-li-tas yang limpah.<br/>Kekosonganmu akan sirna,<br/>Dia yang pu-as-kan dirimu.<br/>Tuhan Yesus, rea-li-tas-mu!<br/>',NULL,65438,4);
INSERT INTO stanza VALUES('I1825','1','Pancar-an telah ku dapat,<br/>le-rai-kan dah''-ga bati-niah,<br/>Pancar-an la-in tak dapat,<br/>me-mu-as-kan sedikit jua.<br/>Akhirnya ku dapat,<br/>ku da-pat-i Tuhan.<br/>Di lubuk-ku ber-pancar ''tia-sa,<br/>sam-pai-lah kekal. Haleluya!<br/>Yesus! Yesus!<br/>Yesus! Yesus!<br/>Dah''ga-ku Dia le-rai-kan.<br/>Yesus! Yesus!<br/>Yesus! Yesus!<br/>Padaku Dia-lah hayat.<br/>',NULL,65439,1);
INSERT INTO stanza VALUES('I1825','2','Pancar-an di dalam beta,<br/>hari-hari lu-ap saja.<br/>Mengarah murad kekal-Nya,<br/>yakni g''reja-Nya nan mu-lia.<br/>Akhirnya Dia bawa;<br/>bawaku ke rumah.<br/>Akupun menghuni di g''reja,<br/>Dia rasa pu-as. Haleluya!<br/>G''reja! G''reja!<br/>G''reja! G''reja!<br/>G''reja itu pu-as-Nya.<br/>G''reja! G''reja!<br/>G''reja! G''reja!<br/>Bagiku kehidup-an<br/>',NULL,65440,2);
INSERT INTO stanza VALUES('I1826','1','Dulu nista, penuh duka,<br/>gumul ronta si-a si-a.<br/>Tuhan Yesus masuk hatiku,<br/>jadi riangku dan pu-as-ku.<br/>O, a-jaib sungguh,<br/>Yesus Tuhanku!<br/>Mari t''rima Yesus Peny''lamat.<br/>Seru nama-Nya,<br/>pasti selamat!<br/>',NULL,65441,1);
INSERT INTO stanza VALUES('I1827','1','Terserah kau kawan,<br/>terciptamu ''tuk di-i-si hayat-Nya.<br/>Kapan saja hatimu terbuka,<br/>Dia seg''ra masuk,<br/>semayam dalammu.<br/>S''ru nama-Nya Yesus,<br/>Penolong ri-il hidup penuh sayang.<br/>Roh-Nya seperti udara hayat,<br/>buka pada-Nya, pasti kau menghirup.<br/>Jangan a-bai-kan Dia,<br/>Engkau sia-sia;<br/>kasih-Nya me-mu-as-kan.<br/>Serulah segera, sambut Di-a,<br/>kau takkan kurang,<br/>malah penuh limpah.<br/>O! Tuhan! Haleluya!<br/>Haleluya! Yesus.<br/>O! Tuhan! Haleluya!<br/>Haleluya! Yesus.<br/>',NULL,65442,1);
INSERT INTO stanza VALUES('I1828','1','Rindu mendapat Tuhan?<br/>Jangan cari du-ni-a,<br/>Du-ni-a bukan tempat<br/>ke-diam-an-Nya.<br/>Bukan tempat ke-diam-an-Nya (2x),<br/>Du-ni-a bukan tempat ke-diam-an-Nya.<br/>',NULL,65443,1);
INSERT INTO stanza VALUES('I1828','2','Rindu mendapat Tuhan?<br/>Jangan demi pikiran.<br/>Itu hanya b''ri paham,<br/>bukan kecap,<br/>Bukan kecap, bukan kecap,<br/>bukan kecap, bukan kecap.<br/>Itu hanya b''ri paham, bukan kecap.<br/>',NULL,65444,2);
INSERT INTO stanza VALUES('I1828','3','Rindu mendapat Tuhan?<br/>Buka saja hatimu.<br/>Buka saja hatimu,<br/>biar Dia masuk.<br/>Biar Dia masuk (4x).<br/>Buka saja hatimu,<br/>biar Dia masuk.<br/>',NULL,65445,3);
INSERT INTO stanza VALUES('I1828','4','Kau ingin biar Dia masuk?<br/>Hanya seru nama-Nya.<br/>Hanya seru nama-Nya,<br/>Dia ''kan masuk.<br/>Tuhan Yesus! (4x)<br/>Hanya seru nama-Nya,<br/>Dia ''kan masuk.<br/>',NULL,65446,4);
INSERT INTO stanza VALUES('I1829','1','Rasa hampa,<br/>entah hidup ''tuk apa,<br/>inilah jawabnya - Yesus!<br/>Dalam batin te-ra-sa lapar,<br/>dah''ga ini pe-mu-as-nya - Yesus!<br/>Tidak lagi terbelenggu,<br/>bingung masa depan;<br/>bukan lagi budak dosa,<br/>hidup s''lalu bimbang;<br/>Yesus dekat,<br/>di hatimu, mulutmu,<br/>Dia menunggu kau terbuka berseru,<br/>Dia-pun masuk.<br/>Yesus - gelap jadi terang;<br/>Yesus - damai tak terkata;<br/>Yesus - hidup baru sekarang!<br/>',NULL,65447,1);
INSERT INTO stanza VALUES('I1830','1','Seru nama-Nya! Seru nama-Nya!<br/>S''ru nama-Nya pasti s''lamat! (2x).<br/>Tuhan Yesus! Tuhan Yesus!<br/>S''ru nama-Nya pasti s''lamat! (2x)<br/>',NULL,65448,1);
INSERT INTO stanza VALUES('I1830','2','Seru nama-Nya! Seru nama-Nya!<br/>S''ru nama-Nya pasti s''lamat! (2x)<br/>Tuhan Yesus! Tuhan Yesus!<br/>Haleluya ku t''lah s''lamat! (2x)<br/>',NULL,65449,2);
INSERT INTO stanza VALUES('I1831','1','Teman, teman, d''ngar panggilan-Nya,<br/>''tia-sa datang ke hatimu.<br/>Su-a-ra-Nya begitu lembut,<br/>juga sangat ri-il.<br/>Dia mengundangmu nikmat kasih.<br/>Alami limpah-Nya nan unggul;<br/>Dia ajak kau hidup bagi-Nya,<br/>agar Dia pu-as lewatmu.<br/>',NULL,65450,1);
INSERT INTO stanza VALUES('I1831','2','Sungguh nyaman, sungguh a-ja-ib,<br/>sua-ra kasih-Mu yang mesra.<br/>Hatiku pun lumer pada-Mu,<br/>juga lupa diri.<br/>Bukan sekadar t''rima berkat,<br/>juga dapat ikut jejak-Mu.<br/>Jadi teman-Mu nan sehati,<br/>agar Dia pu-as lewatku.<br/>',NULL,65451,2);
INSERT INTO stanza VALUES('I1832','1','Ku t''lah dengar sabda Yesus,<br/>"Trimalah perhen-tian!<br/>Yang berlelah, mari datanglah,<br/>baring di ri-baan-Ku."<br/>Aku datang pada Yesus,<br/>lelah, susah, dan d''rita,<br/>Dia-lah tempat per-hen-tian-ku,<br/>hatiku legalah.<br/>',NULL,65452,1);
INSERT INTO stanza VALUES('I1832','2','Ku t''lah dengar sabda Yesus,<br/>"Ku b''ri Cuma-Cuma.<br/>Yang dahaga, minum air hidup,<br/>ambillah d''ngan ri-ang."<br/>Ku buka hati pada-Nya,<br/>dan meminum a-ir hayat.<br/>Ha-us hilang, jiwa segar,<br/>hidup di depan-Nya.<br/>',NULL,65453,2);
INSERT INTO stanza VALUES('I1832','3','Ku t''lah dengar sabda Yesus,<br/>"Akulah t''rang du-nia.<br/>Pandang Aku, terbitlah terang,<br/>terangi jalanmu."<br/>Kini ku balik pada-Nya,<br/>Dia surya, Bintang Fajar.<br/>Ku berjalan dengan ri-ang,<br/>di dalam t''rang hayat.<br/>',NULL,65454,3);
INSERT INTO stanza VALUES('I1833','1','Hayat yang baru, a-jaib,<br/>ri-ang, terang;<br/>kau ''kan dapatkan,<br/>asal kau ma-u.<br/>Yesus mampu pu-as-kan hati roh-mu;<br/>Dia kan mem-bu-at ri-ang hatimu.<br/>Kau dapat alami perubahan a-jaib,<br/>kau dapat masuki alam agung.<br/>Kau dapat alami hal unggul mu-li-a,<br/>ka-lau kau t''rima Tuhan di hatimu.<br/>',NULL,65455,1);
INSERT INTO stanza VALUES('I1833','2','Tidak perlu kau paham sepenuhnya,<br/>tidak perlu ta''u apa sebabnya.<br/>Dia memberi lebih dari harapan,<br/>melampaui yang engkau pikirkan.<br/>',NULL,65456,2);
INSERT INTO stanza VALUES('I1834','1','S''mua sudah si-ap, mari datang!<br/>Mari! Hidangan t''lah se-dia!<br/>Hai yang lapar dan yang lelah,<br/>kau pasti pu-as, kenyang!<br/>',NULL,65457,1);
INSERT INTO stanza VALUES('I1834','chorus','Dengarlah dengar,<br/>se-ru-an undangan-Nya!<br/>Kur-ni-a sempurna,<br/>si-a-pa saja boleh!<br/>',NULL,65458,2);
INSERT INTO stanza VALUES('I1834','2','S''mua sudah si-ap, mari datang!<br/>Pintu kur-ni-a terbuka.<br/>Tempat agung ''tuk mu se-dia.<br/>Dekat ri-ba-an Tuhan.<br/>',NULL,65459,3);
INSERT INTO stanza VALUES('I1834','3','S''mua sudah si-ap, mari datang!<br/>Kecaplah kasih kur-nia-Nya.<br/>Kini waktunya, segera!<br/>Besok tia-da tentulah.<br/>',NULL,65460,4);
INSERT INTO stanza VALUES('I1834','4','S''mua sudah si-ap, mari datang!<br/>Bu-ang kua-tir, gumul du-nia.<br/>Makan Kristus, kur-nia Allah.<br/>Dan minum hayat kekal!<br/>',NULL,65461,5);
INSERT INTO stanza VALUES('I1835','1','Sungguh rahmat, kenal dan nampak Allah.<br/>Lepas gelap, nikmat bebas, terang!<br/>Kur-nia besar, ku beroleh selamat.<br/>Tanpa jasa dan usaha awak!<br/>',NULL,65462,1);
INSERT INTO stanza VALUES('I1835','2','Mohon Tuhan ingat pula k''luar-ga-ku.<br/>Dosa m''reka juga t''lah Kau tanggung.<br/>Mohon Tuhan, Kau genapkan janji-Mu.<br/>Kes''lamatan se-i-si rumahku.<br/>',NULL,65463,2);
INSERT INTO stanza VALUES('I1835','3','Ya, Tuhanku, dengarkanlah do-a-ku.<br/>Kau dapatkan se-i-si rumahku.<br/>Aku beserta se-i-si rumahku.<br/>Beribadah, melayani Tuhan!<br/>',NULL,65464,3);
INSERT INTO stanza VALUES('I1836','1','Sepanjang jalan hidup manusia,<br/>banyak duka dan penat;<br/>Bawalah terang ke dalam gelap,<br/>legakan penderita.<br/>',NULL,65465,1);
INSERT INTO stanza VALUES('I1836','chorus','Jadikan beta saluran berkat,<br/>agar sinar-Mu terpancar;<br/>jadikan beta saluran berkat,<br/>Menarik jiwa kepada Tuhan.<br/>',NULL,65466,2);
INSERT INTO stanza VALUES('I1836','2','Wartakanlah Kristus dan kasih-Nya,<br/>serta kuasa ampun-Nya;<br/>Se-ti-a ti-a-sa terhadap-Nya,<br/>pasti banyak percaya.<br/>',NULL,65467,3);
INSERT INTO stanza VALUES('I1836','3','Seperti Tuhan beri padamu,<br/>pun mengasihi kamu;<br/>B''rilah bantu kepada yang perlu,<br/>abdi untuklah Kristus.<br/>',NULL,65468,4);
INSERT INTO stanza VALUES('I1837','1','Orang yang tersesat,<br/>mengapa bisa pulang?<br/>Tak la-in-lah kasih Allah!<br/>Orang yang berdosa,<br/>mengapa bisa sadar?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65469,1);
INSERT INTO stanza VALUES('I1837','chorus','Oleh kasih, Di-a utus Putra-Nya,<br/>wafat tersalib bagi yang berdosa!<br/>Di mana saja orang dipu-as-kan,<br/>tak la-in-lah kasih Allah!<br/>',NULL,65470,2);
INSERT INTO stanza VALUES('I1837','2','Hati yang g''lap kelam,<br/>mengapa bisa terang!<br/>Tak la-in-lah kasih Allah!<br/>Hati yang t''lah layu,<br/>mengapa bisa segar?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65471,3);
INSERT INTO stanza VALUES('I1837','3','Orang yang berduka,<br/>mengapa bisa ri-ang?<br/>Tak la-in-lah kasih Allah!<br/>Cucuran air mata,<br/>''ngapa bisa terseka?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65472,4);
INSERT INTO stanza VALUES('I1837','4','Hati yang terluka,<br/>mengapa bisa sembuh?<br/>Tak la-in-lah kasih Allah!<br/>Hati yang t''lah patah,<br/>''ngapa bisa terhibur?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65473,5);
INSERT INTO stanza VALUES('I1837','5','Hidup si-a si-a,<br/>mengapa bisa pu-as?<br/>Tak la-in-lah kasih Allah!<br/>Ajal meski datang,<br/>mengapa tak gelisah?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65474,6);
INSERT INTO stanza VALUES('I1837','6','Tanda apakah t''lah<br/>dinyatakan malaikat?<br/>Tak la-in-lah kasih Allah!<br/>Kidung apakah yang orang<br/>Kristen nyanyikan?<br/>Tak la-in-lah kasih Allah!<br/>',NULL,65475,7);
INSERT INTO stanza VALUES('I1838','chorus','Dengar! Ada orang datang,<br/>mengetuk pintu hatimu.<br/>Wa-hai orang yang berdosa,<br/>bukalah pintu hatimu.<br/>',NULL,65476,1);
INSERT INTO stanza VALUES('I1838','1','Yesus t''lah datang,<br/>mengetuk pintu hatimu.<br/>Yesus t''lah datang,<br/>mengetuk pintu hatimu.<br/>Wa-hai orang yang berdosa,<br/>bukalah pintu hatimu.<br/>',NULL,65477,2);
INSERT INTO stanza VALUES('I1838','2','Sudahkah dengar, ada orang ketuk pintu? (x).<br/>Wahai orang yang berdosa,<br/>bukalah pintu hatimu.<br/>',NULL,65478,3);
INSERT INTO stanza VALUES('I1838','3','Yesus memanggil, di depan pintu hatimu (2x).<br/>Wahai orang yang berdosa,<br/>bukalah pintu hatimu.<br/>',NULL,65479,4);
INSERT INTO stanza VALUES('I1838','4','Jawablah seg''ra, ada orang ketuk pintu (2x).<br/>Wahai orang yang berdosa,<br/>bukalah pintu hatimu.<br/>',NULL,65480,5);
INSERT INTO stanza VALUES('I1839','1','Dengan riang ku b''ritahu engkau,<br/>teman, aku telah bebas sungguh.<br/>D''rita, tekanan, sedih s''mua sirna,<br/>sejak percaya Tuhan.<br/>Dia bukan sya-riat untuk ku pegang,<br/>bukan p''rintah yang menuntut-ku.<br/>Dia Putra Allah, Peny''lamat jiwaku,<br/>alirkan kasih dan hayat.<br/>Bebaskan dari d''rita, b''lenggu dosa,<br/>mati ''tuk pimpinku hidup.<br/>',NULL,65481,1);
INSERT INTO stanza VALUES('I1839','2','Ku terbang melayang di langit biru,<br/>Yesus, bebas sejatiku.<br/>Hari ke hari, nikmat tak putus,<br/>ada Dia ku cukup.<br/>Di manakah teman yang begini?<br/>Dia cinta kau, lama menunggu.<br/>Mumpung Di-a masih buka hati-Nya,<br/>datanglah, sandar pada-Nya.<br/>Sa-at kau masuk mu-lia a-nak Allah,<br/>hatimu pasti memuja.<br/>',NULL,65482,2);
INSERT INTO stanza VALUES('I1840','1','Kali pertama dengar mereka,<br/>tak pernah tahu Penyelamat.<br/>Namun di kalbu terbit p''rasa-an,<br/>arus hangat nan sejahtera.<br/>Sengsara silam se-o-lah lupa,<br/>tahu-tahu ku lepas penjara.<br/>Wajah mereka polos pancarkan,<br/>bahwa Allah memang ada.<br/>',NULL,65483,1);
INSERT INTO stanza VALUES('I1840','2','Mereka bilang, Allah mau masuk,<br/>jadi hayat dan Penyelamat.<br/>Belum melihat pun tak mengenal,<br/>kar''na perlu ku mau mencoba.<br/>Pada-Nya paling darilah lubuk,<br/>seru: Oh, Tuhan, mohon selamat.<br/>Tia-da nama lain manis pun merdu,<br/>mesra, nyaman, tidak pudar.<br/>',NULL,65484,2);
INSERT INTO stanza VALUES('I1840','3','Beban terlepas, masuk per-hen-tian,<br/>di-am-pun-i dan dibenarkan.<br/>Di-a hayatku, satu dengan-Nya,<br/>oleh iman hidup t''radap-Nya.<br/>Di dalam Kristus, mu-lia, le-lua-sa,<br/>cip-ta-an baru esa dengan-Nya.<br/>Ini kisahku tentang percaya,<br/>kidung, kasih, maha indah.<br/>',NULL,65485,3);
INSERT INTO stanza VALUES('I1841','1','Hayat terindah!<br/>Hidup bermakna tinggi!<br/>Ku cinta hayat,<br/>mohon singkap kebenaran.<br/>S''ru-an pertama dari lubukku.<br/>Tuhan Yesus!<br/>Nama terang, nama bebas.<br/>Hayatku t''lah merekah.<br/>Tuhan Yesus!<br/>Nama terang, nama bebas.<br/>Hayatku mu-la-i terbit Fajar.<br/>',NULL,65486,1);
INSERT INTO stanza VALUES('I1841','2','Hayat terindah!<br/>Memang Allah yang cipta.<br/>Ku cinta hayat,<br/>gi-at cari sumber hayat.<br/>S''ruan pertama dari lubukku.<br/>Tuhan Yesus!<br/>Sumber hayat, sumber manis.<br/>Hayatku segar nyaman.<br/>Tuhan Yesus!<br/>Sumber hayat, sumber manis.<br/>Hayatku ''ngalirkan a-ir hayat.<br/>',NULL,65487,2);
INSERT INTO stanza VALUES('I1841','3','Hayat terindah!<br/>Carilah kebenaran.<br/>Ku cinta hayat,<br/>ku cinta Tuhan Sang Hayat.<br/>S''ruan pertama dari lubukku.<br/>Tuhan Yesus!<br/>Masuk hatiku pun masuk rohku.<br/>Hayatku jadi baru.<br/>Tuhan Yesus!<br/>Masuk hatiku pun masuk rohku.<br/>Hayatku kar''na-Mu jadi baru!<br/>',NULL,65488,3);
INSERT INTO stanza VALUES('I1901','1','Petunjuk zaman akhir;<br/>Kristus se-g''ra kembali.<br/>Kita si-ap se-di-a,<br/>Tuhan ''kan datang pula.<br/>',NULL,65489,1);
INSERT INTO stanza VALUES('I1901','chorus','Dia ''kan datang, Dia ''kan datang.<br/>Waktu tidak menunggu,<br/>tak lama terdengar se-ruan!<br/>Dia ''kan datang, Dia ''kan datang!<br/>Siap sedia p''ri gadis bijaksana,<br/>Tuhan ''kan datang pula!<br/>',NULL,65490,2);
INSERT INTO stanza VALUES('I1901','2','Dari jiwa dan diri,<br/>pada Tuhan berpaling.<br/>Tia-da waktu meragu,<br/>Tuhan ''kan datang pula!<br/>',NULL,65491,3);
INSERT INTO stanza VALUES('I1901','3','Yang bodoh cinta du-nia,<br/>Dia datang baru sadar.<br/>Wadah ti-a-da minyak,<br/>Tuhan ''kan datang pula!<br/>',NULL,65492,4);
INSERT INTO stanza VALUES('I1901','4','Yang pandai rajin garap,<br/>tak kecap anggur du-nia.<br/>Rohnya penuh pun terang,<br/>Tuhan ''kan datang pula!<br/>',NULL,65493,5);
INSERT INTO stanza VALUES('I1901','5','Menyambut Memp''lai Laki,<br/>lampu bersinar terang.<br/>Jaga lampu tak padam,<br/>Tuhan ''kan datang pula!<br/>',NULL,65494,6);
INSERT INTO stanza VALUES('I1901','6','Yang pandai pasti masuk,<br/>jadi mem-p''lai, berpesta.<br/>Pintu buka buat m''reka,<br/>Tuhan ''kan datang pula!<br/>',NULL,65495,7);
INSERT INTO stanza VALUES('I1901','7','Tuhan sedang di jalan,<br/>tia-da yang tahu kapan.<br/>Berajga, s''kutu d''ngan-Nya,<br/>Tuhan ''kan datang pula!<br/>',NULL,65496,8);
INSERT INTO stanza VALUES('I1902','1','Tuhan sg''ra datang,<br/>singkirkan du-ni-a!<br/>Lepas se-mu-a beban,<br/>lari ke depan.<br/>',NULL,65497,1);
INSERT INTO stanza VALUES('I1902','chorus','Tuhan datang, seg''ra datang,<br/>Tuhan seg''ra datang!<br/>Tuhan datang, seg''ra datang,<br/>amin, datanglah!<br/>',NULL,65498,2);
INSERT INTO stanza VALUES('I1902','2','Sejaklah kini -<br/>Pandang Dia tak putus.<br/>Su-a-sa-na apa pun,<br/>pandang Yesus t''rus.<br/>',NULL,65499,3);
INSERT INTO stanza VALUES('I1902','3','Paling ke Tuhan,<br/>dari diri, dosa ...<br/>Apa yang Dia mu-la-i,<br/>rampunglah pasti.<br/>',NULL,65500,4);
INSERT INTO stanza VALUES('I1902','4','Tatap wajah-Nya.<br/>T''rima ka-ru-nia-Nya.<br/>Kelak di k''ra-ja-an-Nya.<br/>Tampil bersama.<br/>',NULL,65501,5);
INSERT INTO stanza VALUES('I1902','5','Amin firman-Nya -<br/>Baca dan dengarlah,<br/>roh kita pun tergugah,<br/>si-ap sambut Dia.<br/>',NULL,65502,6);
INSERT INTO stanza VALUES('I1903','1','Tuhan ''kan datang, mungkin sekarang.<br/>Tuhan ''kan datang, mungkin sekarang.<br/>Tuhan ''kan datang, mungkin sekarang.<br/>Mari kita, siap se-di-a!<br/>',NULL,65503,1);
INSERT INTO stanza VALUES('I1903','2','Kristus Mempe-lai Laki terkasih (3x).<br/>Kita mem-pe-lai p''rem-puan-Nya!<br/>',NULL,65504,2);
INSERT INTO stanza VALUES('I1903','3','Kita berpaling memandang Tuhan (x).<br/>Tak beralih selamanya!<br/>',NULL,65505,3);
INSERT INTO stanza VALUES('I1903','4','Tempuh jalan-Nya, bu-ang s''mua beban (3x).<br/>Terus maju, makin cepat!<br/>',NULL,65506,4);
INSERT INTO stanza VALUES('I1903','5','Kita berlari, sambut Dia datang (3x).<br/>Kita seg''ra berjumpa Dia!<br/>',NULL,65507,5);
INSERT INTO stanza VALUES('I1904','1','Ayo bangkit!<br/>Ayo bangkit!<br/>Malam larut,<br/>fajar t''lah menyingsing!<br/>Tuhan segera balik,<br/>sg''ra balik, seg''ra balik!<br/>Tuhan segera balik,<br/>ber-dau-lat abadi!<br/>',NULL,65508,1);
INSERT INTO stanza VALUES('I1904','2','Sa-at pintas!<br/>Jangan malas!<br/>Rajin-rajin di<br/>hadapan Tuhan!<br/>Kita terpenuhi Dia,<br/>penuh Dia, penuh Dia!<br/>Kita terpenuhi Dia,<br/>penuh hingga lu-ap!<br/>',NULL,65509,2);
INSERT INTO stanza VALUES('I1904','3','Girang ''tia-sa!<br/>Sorak lantang!<br/>Ada u-jian,<br/>tinggallah dalam-Nya.<br/>Terjang maju ke depan,<br/>ke depan, ke depan!<br/>Biar-pun malam gulita,<br/>ada Dia amanlah!<br/>',NULL,65510,3);
INSERT INTO stanza VALUES('I1904','4','Tegak ku-at!<br/>Tegak ku-at!<br/>P''rang kan lewat,<br/>dalam roh tegaplah!<br/>Tahan sampai Dia datang,<br/>Dia datang, Dia datang!<br/>Tahan sampai Dia datang,<br/>meraja bersa<br/>',NULL,65511,4);
INSERT INTO stanza VALUES('I1905','1','Sungguh girang,<br/>Mempe-lai Laki seg''ra datang tak lambat.<br/>Fajar tibalah, hari nikah,<br/>kidung baru nyanyikan.<br/>',NULL,65512,1);
INSERT INTO stanza VALUES('I1905','chorus','Sa-at indah!<br/>Pagi mu-li-a, Kristus kasihku tiba.<br/>Wadah penuh, pelita terang,<br/>menyambut kembali-Nya.<br/>Sungguh girang,<br/>Mempe-lai Laki seg''ra datang tak lambat.<br/>Fajar tibalah, hari nikah,<br/>kidung baru nyanyikan.<br/>',NULL,65513,2);
INSERT INTO stanza VALUES('I1905','2','Mari kita menebus waktu,<br/>lebih banyak b''li minyak.<br/>Sa-at malam dengar se-ru-an,<br/>kita sudah p''nuh Tuhan.<br/>',NULL,65514,3);
INSERT INTO stanza VALUES('I1905','3','O, sungguh girang, si-ap se-dia,<br/>tunggu Kristus ''kan datang.<br/>Untuk dapat pahala mu-lia,<br/>abai susah, co-ba-an.<br/>',NULL,65515,4);
INSERT INTO stanza VALUES('I1905','4','O, sa-at hari nikah tiba,<br/>sungguh mu-lia semarak!<br/>S''ribu tahun m''raja serta-Nya,<br/>ja-mu-an Anak Domba.<br/>',NULL,65516,5);
INSERT INTO stanza VALUES('I1906','1','Tuhan yang ku cinta,<br/>datanglah seg''ra, sertaku s''lalu.<br/>Ku sandar ri-ba-an-Mu,<br/>pandang cah''-ya rahmat-Mu.<br/>Ungkap se-mua isi hatiku,<br/>kenang kisah Kau dan aku.<br/>Tuhan, ku cinta, Tuhan,<br/>ku ci-um, ku cumbu.<br/>Ba-gai rusa dah''ga,<br/>damba a-ir jernih.<br/>Tunas semi, hancur hati, angan duka,<br/>kapan dapat hibur hati.<br/>',NULL,65517,1);
INSERT INTO stanza VALUES('I1906','2','Tuhan, Kau ter-ba-ik,<br/>Kau mustikaku, dalam jiwaku.<br/>Kau ku cinta, ku damba,<br/>moga bersama s''lalu.<br/>Bayang tak pisah, dalam mimpi,<br/>tetap mengenang diri-Mu.<br/>Sua-sana ini, Tuhan!<br/>Mungkinkah terkata?<br/>Hatiku men-ca-ir,<br/>se-mu-a bagi-Mu.<br/>Dalam alam s''mesta<br/>sia-pa tandingan-Mu?<br/>Rahmat unggul, mari, Tuhan.<br/>',NULL,65518,2);
INSERT INTO stanza VALUES('I1906','3','Tuhan mu-li-a-ku, Kau gembalaku,<br/>ada Kau, puas-ku.<br/>Di salib korban jiwa,<br/>tumpah darah tebusku.<br/>Kini diri, s''galaku,<br/>tersembah bagi-Mu selamanya.<br/>Tuhan, cepatlah datang,<br/>nikmati kasihku.<br/>Kasihku p''ri minyak,<br/>lam-pau kasih du-nia.<br/>Bulan, tahun,<br/>ga-ul, d''ngan-Mu.<br/>Tekad tegar, teguh s''lama,<br/>mari Tuhan.<br/>',NULL,65519,3);
INSERT INTO stanza VALUES('I1906','4','Tuhan, Kau termesra,<br/>ingin ku terbang, ke pang-ku-an-Mu.<br/>Terus menunggu-nunggu<br/>penampakan diri-Mu.<br/>T''rangkat depan-Mu, mu-li-a tak pudar,<br/>pelangi gemerlap.<br/>Langit janganlah menahan-Nya,<br/>hati pedih.<br/>Bagaimana Kau ''kan tenang,<br/>Tuhan kasih?<br/>Bagaimana Kau ''kan sabar?<br/>Betapapun, kembalilah,<br/>genapkanlah!<br/>',NULL,65520,4);
INSERT INTO stanza VALUES('I1907','1','Bu-ang du-nia! Bu-ang du-nia!<br/>Biar-kan du-nia lewat!<br/>Tuhan datang, seg''ra datang!<br/>Apa yang ku damba?<br/>Bu-ang nyaman, buang sia-sia,<br/>buang nikmat du-nia.<br/>Lepas lelah, beban berat,<br/>tak lagi berminat.<br/>("nyaman", "sia-sia" boleh diganti dengan<br/>"kaya", "pangkat", "TV" dll)<br/>',NULL,65521,1);
INSERT INTO stanza VALUES('I1908','1','Tengoklah! Ara sudah semi.<br/>Waktu terinjak genap kini.<br/>Kita baga-gia, segera nampak hari tebusan,<br/>haleluya!<br/>Kita justru angkatan terakhir.<br/>Wajib menyongsong Dia kembali!<br/>',NULL,65522,1);
INSERT INTO stanza VALUES('I1908','2','Janganlah tamak ke-ben-da-an.<br/>Janganlah ter-kait manis du-nia.<br/>Tinggalkan Sodom, masuk bahtera.<br/>Tiap hari ''nempuh hidup g''reja.<br/>Mumpung sekarang, busungkan dada.<br/>Merebut jiwa, biar selamat.<br/>',NULL,65523,2);
INSERT INTO stanza VALUES('I1908','3','Roh, jiwa, tubuhmu Dia jaga.<br/>Moga kau hadir tiap bersidang.<br/>Mungkin sewaktu kita bersidang.<br/>Pu-jian memuncak, Tuhan datang.<br/>Sekonyong-konyong kita terangkat.<br/>Ke dalam mu-lia, haleluya!<br/>',NULL,65524,3);
INSERT INTO stanza VALUES('I1909','1','Lihat k''ra-ja-an du-nia jadilah K''ra-ja-an Tuhan!<br/>Kaum saleh bersorak,"Dia Raja kekal duduk takhta!"<br/>Lak-sa-an sua-ra menggema serempak memuji Dia.<br/>Kristus sudah menang!<br/>',NULL,65525,1);
INSERT INTO stanza VALUES('I1909','chorus','Menang! Menang! Haleluya!<br/>Menang! Menang! Haleluya!<br/>Menang! Menang! Haleluya!<br/>Kristus sudah menang!<br/>',NULL,65526,2);
INSERT INTO stanza VALUES('I1909','2','Naga besar, ular tu-a, Iblis telah tercampak.<br/>Se-mua pengikutnya tak mungkin menyesatkan pula.<br/>Sua-ra pu-jian membubung, memuji kebesaran-Nya.<br/>Kristus sudah menang!<br/>',NULL,65527,3);
INSERT INTO stanza VALUES('I1909','3','Kur-nia, kua-sa, Ke-ra-ja-an Kristus Allah t''lah tiba.<br/>Si pendakwa saudara siang malam telah tercampak.<br/>Sekarang kua-sa Kristus atas bumi terlaksana.<br/>Kristus sudah menang!<br/>',NULL,65528,4);
INSERT INTO stanza VALUES('I1909','4','Dengan darah Domba kita kalahkan si pendakwa.<br/>Demi ke-sak-si-an tolak se-mua cela pendusta.<br/>Kar''na kasih Tuhan, kita tidak sayangi jiwa.<br/>Kristus sudah menang!<br/>',NULL,65529,5);
INSERT INTO stanza VALUES('I1909','5','Saudara, saudari, dengarlah sua-ra dari surga,<br/>"Babilon sudah rubuh!" Marilah bersorak ri-ang.<br/>Sungguh ba-ha-gia, kami sudah ke-lu-ar darinya.<br/>Kristus sudah menang!<br/>',NULL,65530,6);
INSERT INTO stanza VALUES('I1909','6','Babel besar ra-ha-si-a ibu segala sundal.<br/>Kami sangat benci segala cemar dan najisnya.<br/>Gembiralah! Allah menghukumnya berlipat ganda.<br/>Kristus sudah menang!<br/>',NULL,65531,7);
INSERT INTO stanza VALUES('I1909','7','Mu-lia, kua-sa, hormat, se-mu-a milik Allah kita.<br/>Dengan benar dan adil Dia menghukum sundal besar.<br/>"Haleluya! Bahkan asapnya na-ik se-la-ma-nya".<br/>Kristus sudah menang!<br/>',NULL,65532,8);
INSERT INTO stanza VALUES('I1909','8','Pujilah Tuhan! Hai hamba-Nya yang kecil ''tau besar.<br/>Bagaikan guntur dan desau air bah deru bunyinya,<br/>"Haleluya! Allah Maha-kua-sa memerintahlah!"<br/>Kristus sudah menang!<br/>',NULL,65533,9);
INSERT INTO stanza VALUES('I1909','9','Marilah kita gembira dan memberi Dia mu-lia.<br/>Hari nikah Domba tiba, pasangan-Nya t''lah se-dia.<br/>Ber-hi-as ka-in lenan halus, bersih, bercahaya.<br/>Kristus sudah menang!<br/>',NULL,65534,10);
INSERT INTO stanza VALUES('I1909','10','Yohanes nampak Iblis t''lah tercampak ke laut api.<br/>Haleluya! Sejak kini tia-da hasutan lagi.<br/>Genap ka-um saleh proklamirkan dengan berani,<br/>"Kristus sudah menang!"<br/>',NULL,65535,11);
INSERT INTO stanza VALUES('I1909','11','Lihatlah! Yerusalem Baru turun dari surga.<br/>Mempelai pe-rem-pu-an Kristus t''lah si-ap se-di-a.<br/>Allah - manu-sia ber-ba-ur, nyatalah mu-lia Allah.<br/>Kristus sudah menang!<br/>',NULL,65536,12);
INSERT INTO stanza VALUES('I1909','12','Kemah ke-di-am-an Allah di tengah ma-nu-si-a.<br/>Kudus dan mu-lia Allah tertampil dengan sempurna.<br/>Dengar Tuhan bers''ru,"Genaplah!" Allah pun pu-as-lah.<br/>Kristus sudah menang!<br/>',NULL,65537,13);
INSERT INTO stanza VALUES('I1909','chorus','Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Kristus sudah menang!<br/>',NULL,65538,14);
INSERT INTO stanza VALUES('I1910','1','Kami dambakan pengalaman murid-Mu,<br/>yang nampak Kau di puncak gunung.<br/>Wajah-Mu cerah mu-lia p''ri sinar surya,<br/>jubah-Mu pun putih menyala!<br/>Kini teringatlah, Kau seg''ra kembali,<br/>sukacita me-luap di hati.<br/>Sebelum angkatan kami mengecap maut,<br/>kami pun ''kan nampak muncul-Mu!<br/>',NULL,65539,1);
INSERT INTO stanza VALUES('I1910','2','Mu-lia yang ditampak m''reka kali itu.<br/>Meski indah, namun sepintas.<br/>Kar''na sa-at itu Kau belum lewat maut.<br/>Kau baru Putra yang terpangku.<br/>Kau ''kan datang pula, mu-lia-Mu sempurna.<br/>Lak-sa-an saleh puji sorak!<br/>Dikau maharaja, Tuhan atas s''gala<br/>. Beserta umat-Mu s''lamanya.<br/>',NULL,65540,2);
INSERT INTO stanza VALUES('I1910','3','Puji Tuhan, kar''na Kau t''lah di-mu-lia-kan.<br/>Ka-um putra pun Kau mu-lia-kan!<br/>Kami asal dosa Kau beri kur-nia-Mu.<br/>Hingga jadi pola kasih-Mu.<br/>Kami asal debu, jadilah permata.<br/>Nantikan nyata dalam mu-lia.<br/>Dalam alam kekal, tak henti bernyanyi.<br/>Penuh rasa terima kasih.<br/>',NULL,65541,3);
INSERT INTO stanza VALUES('I1911','1','Sa-atnya s''gra tiba!<br/>Anggur dikilang,<br/>ti-ap tetes digirik se-mu-a!<br/>Tuhan sep''ri tunas di tanah gersang,<br/>kau malah akrab dengan du-ni-a!<br/>',NULL,65542,1);
INSERT INTO stanza VALUES('I1911','chorus','Lepaskan dirimu dari du-nia,<br/>jadi bu-ah bungar bagi Allah.<br/>',NULL,65543,2);
INSERT INTO stanza VALUES('I1911','2','Sa-at-nya sg''ra tiba!<br/>Gandum di-tu-ai!<br/>Agar matang, bu-ang nikmat du-nia.<br/>Saratlah di dalam,<br/>kering di lu-ar.<br/>Ada Tuhan, tak perlukan du-nia.<br/>',NULL,65544,3);
INSERT INTO stanza VALUES('I1911','3','Jadi bu-ah bungar,<br/>alangkah berkat!<br/>Pesta nikah pula duduk takhta!<br/>Janganlah menunggu du-nia bertindak.<br/>Mumpung sekarang, bu-ang-lah sampah.<br/>',NULL,65545,4);
INSERT INTO stanza VALUES('I1912','1','Minyak dalam di-an, roh berkobar,<br/>minyak dalam di-an s''karang!<br/>Palingkan ''tiasa ke roh, ya, Tuhan,<br/>minyak penuh di-an tak padam.<br/>Tuhan! Amin! Haleluya!<br/>Bakar si-ang malam tak sudah!<br/>Tuhan! Amin! Haleluya!<br/>Paling ke roh ''ti-a-sa!<br/>',NULL,65546,1);
INSERT INTO stanza VALUES('I1912','2','Wadah kami perlu ada minyak,<br/>Kau datang tia-da malukan.<br/>Tuhan resapi tiap p''losok jiwa,<br/>hingga kami penuhlah minyak.<br/>Tuhan Yesus, penuhilah,<br/>ka-ru-nia-kan diri-Mu ''tia-sa!<br/>Tuhan Yesus, resapilah,<br/>hingga penuh rea-li-tas!<br/>',NULL,65547,2);
INSERT INTO stanza VALUES('I1912','3','Penuh minyak, hingga t''rus berkobar,<br/>sampai kedatangan Tuhan.<br/>Bersama Mempelai duduk pesta,<br/>hari raya indah cemerlang.<br/>Tuhan, mari! Lekas datang!<br/>Tengok, kami penuh pun cerlang!<br/>Tuhan, mari! Lekas datang!<br/>Sambut jodoh-Mu s''karan<br/>',NULL,65548,3);
INSERT INTO stanza VALUES('I1913','1','S''puluh dara jemput s''rempak,<br/>m''ngapa nasib berbeda?<br/>Cerdik, bodoh, sama p''lita,<br/>minyaklah yang tentukan.<br/>Mumpung s''karang, lekas si-ap,<br/>roh penuh, resap jiwa.<br/>Sia-ga sam-pai Tuhan datang,<br/>berpesta bersama-Nya.<br/>',NULL,65549,1);
INSERT INTO stanza VALUES('I1913','2','Tiga hamba s''mua bermodal,<br/>m''ngapa nasib berbeda?<br/>Yang se-ti-a pergi dagang,<br/>yang jahat memendamnya.<br/>Fae-dah-kan-lah tiap talenta,<br/>garap s''rentak di g''reja.<br/>Se-tia sampai Tuhan datang,<br/>pasti t''rima pahala.<br/>',NULL,65550,2);
INSERT INTO stanza VALUES('I1913','3','Sa-at sudahlah mendesak,<br/>mari sama waspada.<br/>Jangan sia-sia amanat-Nya,<br/>pahala-Nya t''lah se-dia.<br/>Sa-at ganjar, depan takhta,<br/>nyata adil mu-lia-Nya.<br/>Tahan api, emas, perak;<br/>mi-le-ni-um meraja.<br/>',NULL,65551,3);
INSERT INTO stanza VALUES('I1914','1','Zaman ini akan tamat,<br/>sepuluh dara pegang dian.<br/>Menjemput Mempe-lai sayang,<br/>lima bodoh lima bijak.<br/>Yang bijak berminyak penuh,<br/>yang bodoh hampirlah asat.<br/>Mumpung kini beli minyak,<br/>sia-sia sesal ke-mu-di-an.<br/>',NULL,65552,1);
INSERT INTO stanza VALUES('I1914','2','Firman-Mu cukuplah jelas,<br/>bagi yang bijak Kau datang.<br/>Yang selalu se-dia minyak,<br/>tang-gulangi s''mua rintangan.<br/>Ubah mutu genap jiwa,<br/>roh penuhi seluruhnya.<br/>Terus jaga dan si-a-ga,<br/>kelak nikmat pesta nikah.<br/>',NULL,65553,2);
INSERT INTO stanza VALUES('I1914','3','Wajib terang p''lita rohku,<br/>demi ''tia-sa s''ru nama-Mu.<br/>Hidup di roh berlatih t''rus,<br/>barang usang bakar s''luruh.<br/>Mohon Tuhan, Kau yang tumbuh,<br/>lu-as sebar ke jiwaku.<br/>Di hatiku Kau semayam,<br/>wadah minyak lu-ap penuh.<br/>',NULL,65554,3);
INSERT INTO stanza VALUES('I1914','4','G''lap gulita masa kini,<br/>hari berkat sudah hampir.<br/>Kedatangan Sang Mempelai,<br/>akan sekonyong terjadi.<br/>Amat berkat, pesta nikah,<br/>esa padu dua mempelai.<br/>Biar hidupku depan Tuhan,<br/>berjaga p''ri dara pandai.<br/>',NULL,65555,4);
INSERT INTO stanza VALUES('I1915','1','Sua-tu senja, di perigi,<br/>duduk hamba Abraham,<br/>hendak mencari mempelai perem-puan.<br/>Ribka datang tepat waktu,<br/>berasal dari Tuhan,<br/>hamba itu berhasil berkat Allah.<br/>',NULL,65556,1);
INSERT INTO stanza VALUES('I1915','chorus','Lekas si-ap, mema-kai cadar,<br/>dengar derap langkah sang hamba!<br/>Hari penuh ba-ha-gi-a telah di depan mata;<br/>mempe-lai dibawa ke kemah Ishak.<br/>',NULL,65557,2);
INSERT INTO stanza VALUES('I1915','2','Bapa mengutus Roh Kudus,<br/>membawa limpah Kristus.<br/>Hendak mencari mem-pe-lai nan kudus.<br/>Ishak kita t''lah siap<br/>kemah dalam rumah bapanya.<br/>Se-dia sambut Ribka tinggal dalamnya.<br/>',NULL,65558,3);
INSERT INTO stanza VALUES('I1915','3','"S''lamat tinggal du-nia!"<br/>kini kita ikuti Tuhan.<br/>Jawab panggilan-Nya,<br/>s''rahkan se-mua-nya.<br/>Cacat kerut hilang sirna,<br/>berjumpa wajah Tuhan.<br/>Sungguh girang,<br/>kita mempelai mu-lia!<br/>',NULL,65559,4);
INSERT INTO stanza VALUES('I1916','1','Mungkin pagi, mungkin si-ang,<br/>mungkin malam datangnya.<br/>Boleh juga sekarang,<br/>nyatalah mu-li-a-Nya.<br/>Kristus datang,<br/>Kristus datang segera!<br/>',NULL,65560,1);
INSERT INTO stanza VALUES('I1916','2','Kristus segera kembali,<br/>tent''ra surga iringi.<br/>Terasalah di batin,<br/>Di-a sambut pengantin.<br/>Sa-at dekat Tuan<br/>''nyatakan diri.<br/>',NULL,65561,2);
INSERT INTO stanza VALUES('I1916','3','Penuh mu-li-a datang-Nya,<br/>kita hadir bersama.<br/>Menyongsonglah datang-Nya,<br/>tercapai murad Allah.<br/>Wajib pengantin<br/>selesai ter-hi-as.<br/>',NULL,65562,3);
INSERT INTO stanza VALUES('I1916','4','Kristus segera baliklah,<br/>sisa waktu tak lama.<br/>Ya, segera datang-Nya,<br/>yang masak di-tu-ai-Nya.<br/>Terangkatlah kita lekat Kepala.<br/>',NULL,65563,4);
INSERT INTO stanza VALUES('I1916','5','Mempelai Laki sg''ra tiba,<br/>menjemput pasangan-Nya.<br/>Betapa ba-ha-gi-a,<br/>Roh dan memp''lai senada.<br/>Amin! Haleluya!<br/>Yesus datanglah!<br/>',NULL,65564,5);
INSERT INTO stanza VALUES('I1917','1','Tengoklah! Sungai hayat ''ngalir dari takhta!<br/>Pohon hayat berbu-ah subur lagi lebat!<br/>Di sini tak ''merlukan surya dan pelita,<br/>Tuhanlah terangnya.<br/>',NULL,65565,1);
INSERT INTO stanza VALUES('I1917','chorus','"Mari!"<br/>tutur Roh dan mempelai p''rempuan.<br/>"Mari, marilah!"<br/>sahut si pendengar.<br/>Kaum dahaga, marilah!<br/>Marilah! Air hayat g''ratislah!<br/>',NULL,65566,2);
INSERT INTO stanza VALUES('I1917','2','Kristuslah a-ir hayat dalamku t''rus ''ngalir!<br/>Kristuslah bu-ah hayat untuk ku nikmati!<br/>Kristuslah surya, bintang fajar dan siang hari.<br/>Kristuslah Almuhit!<br/>',NULL,65567,3);
INSERT INTO stanza VALUES('I1917','3','Tuhan bersabda,"Ya, Aku segera datang!"<br/>Tuhan bersabda,"Ya, Aku segera datang!"<br/>Tuhan bersabda,"Ya, Aku segera datang!"<br/>"Aku seg''ra datang!"<br/>',NULL,65568,4);
INSERT INTO stanza VALUES('I1917','chorus','"Marilah datang! Ya, Tuhan datanglah!"<br/>"Marilah datang! Ya, Tuhan datanglah!"<br/>"Marilah datang! Ya, Tuhan datanglah!"<br/>"Amin! Ya, datanglah!"<br/>',NULL,65569,5);
INSERT INTO stanza VALUES('I2001','1','Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>Haleluya! Haleluya!<br/>',NULL,65570,1);
INSERT INTO stanza VALUES('I2002','1','O, puji Dia! O, puji Dia!<br/>Mu-li-a, hormat nama-Nya!<br/>O, puji Dia! O, puji Dia!<br/>Mu-li-a, hormat nama-Nya!<br/>Siar pada bangsa per-bu-at-an-Nya,<br/>sebutlah nama Sang terhormat;<br/>Umat Si-on, angkat suara,<br/>Nyaring menjunjung kurnia-Nya.<br/>Haleluya! Haleluya!<br/>Sorak, nya-nyian tak bersudah!<br/>Haleluya! Haleluya!<br/>Sorak, nya-nyian tak bersudah!<br/>',NULL,65571,1);
INSERT INTO stanza VALUES('I2025','1','Kisah nan misteri, ra-ha-sia semesta.<br/>Kini terungkapkan dalam Firman Tuhan.<br/>Kisah kasih Allah, yang tak terpahamkan,<br/>Kisah nan romantis, Allah dan ma-nu-sia.<br/>',NULL,65572,1);
INSERT INTO stanza VALUES('I2025','2','Walau ma-nu-sia menolak kasih-Nya,<br/>Hati-Nya tak b’rubah Dia tak putus a-sa.<br/>Menjadi ma-nu-sia, Yesuslah nama-Nya.<br/>Mencari d’ngan damba, idaman hati-Nya.<br/>',NULL,65573,2);
INSERT INTO stanza VALUES('I2025','3','Walau ku berdosa, Dia mati tebusku,<br/>Bangkit-Nya bagiku jadi cip-taan baru.<br/>Bersatu dengan-Nya, Dia jadi hayatku.<br/>Berkontak dengan-Nya, Dia jadi nikmatku.<br/>',NULL,65574,3);
INSERT INTO stanza VALUES('I2025','4','Kasih Yesus manis, sungguhlah memikat.<br/>Nama-Nya yang harum sangat mempesona.<br/>Diri-Nya menawan, menarik hatiku,<br/>Hingga ku berkata, “Aku cinta Yesus!”<br/>',NULL,65575,4);
INSERT INTO stanza VALUES('I2025','5','Kristus-lah ke-puas-an ‘tas s’gala ke-puas-an.<br/>Di lu-ar Diri-Nya tia-da yang ku damba.<br/>Dia-lah Sang kekasih, aku pengasih-Nya.<br/>Saling mengasihi, saling me-muas-kan.<br/>',NULL,65576,5);
INSERT INTO stanza VALUES('I2025','6','Di-a yang ilahi pun juga insani.<br/>Aku pengasih-Nya di-ubah oleh-Nya.<br/>Aku yang insani pun juga ilahi,<br/>Serupa serasi jadi pasangan-Nya.<br/>',NULL,65577,6);
INSERT INTO stanza VALUES('I2025','7','Kristus-lah Sang raja, Salomo sejati.<br/>Aku gadis desa Sang ratu Sulami.<br/>Sia-pa-kah ku ini, Dia mau ni-kah-i-ku.<br/>Datang-Nya kembali, Sang mem-p’lai jemputku.<br/>',NULL,65578,7);
INSERT INTO stanza VALUES('I2026','1','Persona-Mu mempesona,<br/>daya tarik bagiku.<br/>Saat men-ci-um keharuman-Mu,<br/>cukup ‘tuk ku cinta-Mu.<br/>Ke-ma-tian-Mu nan semerbak;<br/>timbul pu-jian hatiku.<br/>Derita salib p’nuh ke-pa-hit-an<br/>su-plai hayat manis-Mu.<br/>Waktu s’karang jasmani-Mu tak hadir,<br/>Demi iman kasihku memeluk-Mu.<br/>Nikmat hayat persekutuan,<br/>hadir persona-Mu ku rindu.<br/>',NULL,65579,1);
INSERT INTO stanza VALUES('I2026','2','Ku bukakan pintu hati,<br/>masuk ke mahligai-Mu,<br/>Selalu naikkan persembahanku,<br/>agar puaslah hati-Mu.<br/>Biar hatiku dimurnikan,<br/>tiada lagi bercabang.<br/>P’ri burung dara memandang<br/>lurus pada-Mu yang menawan.<br/>Nyaman di sisi-Mu, o, Kekasihku,<br/>Berbaring di petiduran yang hijau;<br/>Perhentian penuh hayat,<br/>karena nikmat pandang wajah-Mu.<br/>',NULL,65580,2);
INSERT INTO stanza VALUES('I2026','3','Taruh aku p’ri meterai<br/>kekal dalam hati-Mu.<br/>Pada lengan-Mu tidak terhapus,<br/>jangan bu-ang diriku.<br/>Jangan biarkan noda dunia<br/>p’nuhi milik kekal-Mu.<br/>Kar’na cinta-Mu kuat p’ri maut,<br/>kejam pun cemburu-Mu.<br/>Bakar habis dengan api cinta-Mu,<br/>bila sesuatu timbulkan cemburu.<br/>Cinta kasih yang tak padam,<br/>topangku hingga bersua d’ngan-Mu.<br/>',NULL,65581,3);
INSERT INTO stanza VALUES('I2026','4','Saat itu sudah dekat,<br/>cepat datang Kekasih,<br/>Cepat p’ri kijang di atas gunung,<br/>Tuhan Yesus datanglah.<br/>Saat itu iman nyata,<br/>doa jadi pu-ji-an.<br/>Cintaku akan amat<br/>sempurna tanpa bayangan gelap.<br/>Tuhan Yesus, cepat Engkau datanglah!<br/>Pengasih-Mu sudah tunggu tak sabar.<br/>Berjumpa-Mu sungguh mu-lia,<br/>melayani-Mu selamanya.<br/>',NULL,65582,4);
INSERT INTO stanza VALUES('I2027','1','Menga-sih-i-Mu-lah hidupku.<br/>Mengasih-i-Mu hingga s’penuh.<br/>Tuhan ampuniku, t’lah tinggalkan<br/>Kasih pertama d’ngan-Mu.<br/>Kau lebih dari yang ku cinta,<br/>Kau lebih dari yang ku punya,<br/>Lebih dari ku, tia-da se-sua-tu<br/>Dibandingkan yang ku punya.<br/>',NULL,65583,1);
INSERT INTO stanza VALUES('I2027','chorus','Kaulah yang utama dalam s’galanya.<br/>Tak t’rebut tempat-Mu di hatiku,<br/>Infuskan diri-Mu dengan limpah!<br/>K’lak kita jumpa, kasih terbaik bagi-Mu.<br/>',NULL,65584,2);
INSERT INTO stanza VALUES('I2027','2','Kau berhak ambil yang ku cinta,<br/>Namun b’ri Diri-Mu berlimpah.<br/>Kau-lah ku perlu, b’rikan Diri-mu,<br/>Jangan b’ri yang ku ma-u.<br/>Se-tiap hal pasti akan lewat,<br/>Se-tiap orang punya jalan-nya.<br/>Namun ku dan Kau saling miliki,<br/>Saling kasih nan manis.<br/>',NULL,65585,3);
INSERT INTO stanza VALUES('I2027','3','Mustikanya waktu ku d’ngan-Mu.<br/>B’ri kasih ter-baik yang Kau rindu.<br/>Sua-mi terkasih, tariklah aku<br/>ke dalam mahligai-Mu.<br/>Kau yang pertama dalam hidup,<br/>pun pe-ker-jaan, pelayananku.<br/>Dengan sia-pa pun, hanya Di-kau-lah<br/>Yang utama dalam-ku.<br/>',NULL,65586,4);
INSERT INTO stanza VALUES('I2028','1','Tuhan Yesus Kau kasihku,<br/>Kau rebut s’luruh hatiku.<br/>Sia-pa s’perti Kau,<br/>yang cantik sungguh.<br/>Tak satu pun tandingi-Mu.<br/>Saat ku dengar sua-ra-Mu,<br/>berbisik dalam hatiku.<br/>Tersingkir se-mua, pen-ca-ri-an-ku,<br/>Hilang s’mua bangga diriku.<br/>',NULL,65587,1);
INSERT INTO stanza VALUES('I2028','chorus','Sia-pa s’perti Kau yang cantik sungguh.<br/>Sia-pa s’perti Kau yang manis sungguh.<br/>Kau berhak dapatkan s’mua cintaku.<br/>Tuhan Yesus ku cinta-Mu.<br/>Tak lagi tertipu p’rasaanku.<br/>Tak lagi percaya si-tua-si-ku.<br/>Ku hanya tahu mengasihi-Mu.<br/>Tuhan Yesus ku cinta-Mu<br/>',NULL,65588,2);
INSERT INTO stanza VALUES('I2028','2','Tuhan Yesus, Kau kasihku,<br/>Ku buang s’mua lega hatiku.<br/>Ku suka jadi budak cinta-Mu.<br/>Ku senang menaati-Mu.<br/>Ku tetap pilih jalan-Mu.<br/>Meski sulit ta-at-i-Mu.<br/>Ku hanya dambakan perkenan-Mu.<br/>Cinta-Mu, damai bagiku.<br/>',NULL,65589,3);
INSERT INTO stanza VALUES('I2028','3','Tuhan Yesus, Kau kasihku,<br/>Ku tak-kan meninggalkan-Mu.<br/>Jangan Kau simpan, senyum wajah-Mu.<br/>Ku hanya ma-u hadir-Mu.<br/>Ku ungkap s’mua kepada-Mu.<br/>Kaulah kasih, ke-puas-an-ku.<br/>Hingga kekal Kaulah ba-gi-an-ku.<br/>Ku hanya ma-u di-ri-Mu.<br/>',NULL,65590,4);
INSERT INTO stanza VALUES('I2029','1','Manis-Mu selera kenikmatanku.<br/>Cantik-Mu, tarikan bati bagiku.<br/>Sinar-Mu menangkapku,<br/>mata-Mu memikatku.<br/>Tiap saat memeluk-Mu dan men-ci-um-Mu.<br/>',NULL,65591,1);
INSERT INTO stanza VALUES('I2029','chorus','O, Yesus ku cinta pada-Mu.<br/>O, Yesus ku cinta pada-Mu.<br/>O, Yesus ku cinta pada-Mu,<br/>hingga lupa diriku.<br/>O, Yesus ku cinta pada-Mu.<br/>O, Yesus ku cinta pada-Mu.<br/>O, Yesus ku cinta pada-Mu,<br/>lenyap dalam-Mu.<br/>',NULL,65592,2);
INSERT INTO stanza VALUES('I2029','2','Lupakan aktivitas yang lu-ar-an.<br/>Lupakan per-baik-an diri lu-ar-an.<br/>Kau hanya mau dicinta,<br/>ku pengasih-Mu ‘tia-sa,<br/>yang tergila-gila, riang melonjak.<br/>',NULL,65593,3);
INSERT INTO stanza VALUES('I2029','3','Hidupku hanya cinta Kau sepenuh.<br/>Kerjaku hanya cinta Kau sepenuh.<br/>Cinta Kau lah nikmatku,<br/>juga pelayananku.<br/>Cinta Kau lah motifku,<br/>juga tekadku.<br/>',NULL,65594,4);
INSERT INTO stanza VALUES('I2029','4','Kasihku butakanku t’radap s’gala.<br/>Kasihku buat du-nia bukan segala.<br/>Hanya Kau yang ku pandang,<br/>hanya Kau ku perlukan.<br/>Bagiku la-in tia-da,<br/>O Yesus saja.<br/>',NULL,65595,5);
INSERT INTO stanza VALUES('I2030','1','Sukacita-Mu ku-at-ku,<br/>p’nuhi hatiku nyanyi s’lalu.<br/>Kuat-kan yang lemah,<br/>teguhkan lutut goyah, sukacita.<br/>Sukacita-Mu ku-at-ku,<br/>bu-at hatiku se-tia s’lalu.<br/>Sua-sa-na mati,<br/>hayat Kau b’ri, ku hidup.<br/>Lemah tia-da!<br/>Sang sukacita, ku memuji-Mu.<br/>Di hati senang, Kau bertumbuh.<br/>Bersukacita dalam s’gala se-sua-tu.<br/>Haleluya Rajaku!<br/>Sang sukacita, ku memuji-Mu.<br/>Senyum-Mu s’lalu di wajahku.<br/>Bersukacita dalam s’gala se-sua-tu.<br/>Haleluya Rajaku!<br/>',NULL,65596,1);
INSERT INTO stanza VALUES('I2031','1','Allah Sang mu-lia,<br/>Kau tampakkan<br/>diri pada Abraham.<br/>D’ngan janji berkat,<br/>Kau panggil dia dari<br/>Ke-di-am-an-nya,<br/>ke ke-diam-an-Mu.<br/>O, mu-li-a-Mu Tuhan,<br/>daya tarik baginya,<br/>Yang memisahkannya dari<br/>du-nia gelap pada diri-Mu.<br/>O, mu-lia-Mu Tuhan,<br/>dorongan yang terbesar<br/>Pun ke-kuat-an baginya,<br/>membuat dia ikut visi-Mu.<br/>Oleh mu-lia-Mu,<br/>Kau memanggil<br/>kami t’rus menerus.<br/>Mu-lia-Mu s’karang<br/>tak nampak mata,<br/>D’ngan iman pegang janji-Mu.<br/>Meski Kau memimpin ke jalan<br/>yang kami pun tak tahu,<br/>Bahkan rugi derita<br/>tapi kami percaya-Mu.<br/>',NULL,65597,1);
INSERT INTO stanza VALUES('I2031','2','Bila melihat wajah mu-lia-Mu<br/>di takhta surgawi,<br/>Kami tak dapat tak<br/>tinggalkan s’gala.<br/>Kau sasaranku,<br/>Kaulah tu-juan-ku.<br/>Memang mamon gemerlap,<br/>memang du-nia memikat.<br/>Namun mu-lia-Mu jauh<br/>lebih-i s’mua itu,<br/>s’mua tak terhitung.<br/>Kami anggap s’mua rugi,<br/>dibandingkan diri-Mu.<br/>Kaulah yang paling unggul,<br/>paling berharga,<br/>lampau s’mua itu,<br/>Oleh mu-lia-Mu Kau memanggil<br/>kami t’rus menerus.<br/>Mu-lia-Mu s’karang<br/>tak nampak mata,<br/>D’ngan iman pegang  janji-Mu.<br/>Meski Kau memimpin ke jalan<br/>yang kami pun tak tahu,<br/>bahkan rugi derita,<br/>tapi kami percaya-Mu.<br/>',NULL,65598,2);
INSERT INTO stanza VALUES('I2031','3','Orang menganggap s’mua<br/>persembahan kami “pemborosan”.<br/>Mereka hitung rugi atau untung,<br/>Tapi Kau layak atas s’mua itu.<br/>S’lama berabad-abad<br/>ri-buan jiwa dan harta,<br/>posisi,<br/>Masa depan t’lah diboroskan<br/>curah pada-Mu.<br/>S’lama berabad-abad<br/>ri-buan jiwa dan harta,<br/>posisi,<br/>Masa depan t’lah diboroskan<br/>curah pada-Mu.<br/>Kami mau menebus curahkan<br/>yang ter-ba-ik pada-Mu.<br/>Itu bukan sua-tu pemborosan,<br/>tapi kesaksian yang harum.<br/>Kami mau menebus curahkan<br/>yang ter-ba-ik pada-Mu.<br/>Mungkin ini waktu akhir<br/>yang Kau b’ri, s’mua bagi-Mu.<br/>',NULL,65599,3);
INSERT INTO stanza VALUES('I2032','1','O, berkat sejati tidak ter-ni-lai<br/>B''ri sukacita penuh pu-as pun da-mai.<br/>Tia-da yang lam-pau-i berkat kekal ini,<br/>Bukanlah perkara benda,<br/>atau materi.<br/>Kasih ka-ru-ni-a,<br/>berkat yang terbesar ini,<br/>Allah b’ri diri-Nya sendiri.<br/>Di-a kenikmatan yang termanis,<br/>Unggul su-plai serba cukup hari ke hari.<br/>',NULL,65600,1);
INSERT INTO stanza VALUES('I2032','2','Tuhan limpahkan kasih ka-ru-nia-Mu,<br/>P’ri embun yang surgawi penuhi aku.<br/>Dalam si-tu-a-si dan waktu apa pun,<br/>B’ri kekuat-an, perlindungan,<br/>s’mua keper-luan-ku.<br/>Hidup g’reja indah, kaya<br/>‘kan kasih ka-ru-nia,<br/>Tempat warisan Allah ada.<br/>Kasih ka-ru-nia-Mu besertaku,<br/>Asal ku hidup gereja,<br/>',NULL,65601,2);
INSERT INTO stanza VALUES('F1','1','جلال بر خدای پدر،<br/>و مسیح، پسر،<br/>جلال بر آن روحِ قدوس –<br/>دائم یک.<br/>',NULL,65603,1);
INSERT INTO stanza VALUES('F1','2','خلقتِ عظیم را بینیم،<br/>با طرحی عالی،<br/>پس پرستش ات کنیم و<br/>باز ایستیم.<br/>',NULL,65604,2);
INSERT INTO stanza VALUES('F1','3','لیک، آرزویت برای<br/>پسران که در<br/>پسر ستایش ات کنند،<br/>ثبتِ عشق!<br/>',NULL,65605,3);
INSERT INTO stanza VALUES('F1','4','فکرت را فاش کردی، تا به<br/>انسانها  دهی<br/>دل بستی در آنها بهرِ<br/>دلشان.<br/>',NULL,65606,4);
INSERT INTO stanza VALUES('F1','5','پس در مسیح، بازخریدش،<br/>(شر را نابود کرد!)<br/>پرستش از خلقتِ نو<br/>حاصل شد!<br/>',NULL,65607,5);
INSERT INTO stanza VALUES('F1','6','جلال بر خدای پدر،<br/>و مسیح، پسر،<br/>جلال بر آن روحِ قدوس –<br/>دائم یک.<br/>',NULL,65608,6);
INSERT INTO stanza VALUES('F7','1','جلال، جلال بر تو پدر!<br/>جلال، جلال بر پسر!<br/>جلال، جلال بر روحْ قدوس!<br/>جلال بر هر سه در یک!<br/>',NULL,65609,1);
INSERT INTO stanza VALUES('F7','chorus','ستايش كن! ستايش كن!<br/>ستايش خداى سه-يكتا!<br/>جلالش دِه؛ جلالش دِه!<br/>كارهاى عجيب كرد برامون!<br/>',NULL,65610,2);
INSERT INTO stanza VALUES('F7','2','ستايشْ پدر، هدف داشت!<br/>ستايشْ پسر، کارکرد!<br/>ستایشْ روح، انتقال داد!<br/>ستايش بر سه در يک!<br/>',NULL,65611,3);
INSERT INTO stanza VALUES('F9','1','جلال باد خدای پدر،<br/>جلال، خدای پسر،<br/>جلال باد بر خدای روح،<br/>جلال خدا سه-یکتا!<br/>آن که بود، هست و خواهد بود<br/>طی گذرِ سالها.<br/>',NULL,65612,1);
INSERT INTO stanza VALUES('F11','1','تو، پدر، روحِ راستینی،<br/>همان قدوس ترین؛<br/>حال در روح می پرستیمت،<br/>در راستی می خوانیم.<br/>',NULL,65613,1);
INSERT INTO stanza VALUES('F11','2','بهرِ ما یک روح ساختی تا<br/>تو را بپرستیم،<br/>در روحمان بازتاب کنیم<br/>پس یک روح بشویم.<br/>',NULL,65614,2);
INSERT INTO stanza VALUES('F11','3','پدر در پسر آمده،<br/>پسر آن روح است تا<br/>خدا در روحِ ما آید.<br/>این فیض است، شگفتا!<br/>',NULL,65615,3);
INSERT INTO stanza VALUES('F11','4','پسر کلامِ زنده است،<br/>و نیز کلام، روح است؛<br/>آن روح آمد در روحِ ما،<br/>تازه کرد با حیات.<br/>',NULL,65616,4);
INSERT INTO stanza VALUES('F11','5','روحِ تو در روحمان است،<br/>و در چنین وحدت،<br/>روحت با روحِ ما گوید:<br/>هستیم فرزندانت.<br/>',NULL,65617,5);
INSERT INTO stanza VALUES('F11','6','روحت هدایت کند تا<br/>در پی تو رَویم؛<br/>این گونه روحانی شویم،<br/>حیات و صلح داریم.<br/>',NULL,65618,6);
INSERT INTO stanza VALUES('F11','7','تو را در روح می پرستیم،<br/>با تو تماس گیریم،<br/>تا روحمان رها شود،<br/>تو را ابراز کنیم.<br/>',NULL,65619,7);
INSERT INTO stanza VALUES('F11','8','پدر تو را می ستاییم<br/>که تو آن روح هستی؛<br/>در روح و در راستی حالا<br/>تو را می پرستیم.<br/>',NULL,65620,8);
INSERT INTO stanza VALUES('F12','1','خدا، منشأ حياتى،<br/>غنی و آزادی!<br/>چون آبِ حیاتی، جارى<br/>تا به ابدیَت!<br/>',NULL,65621,1);
INSERT INTO stanza VALUES('F12','2','عشقت در پسر شد جاری<br/>بینِ نسل بشر؛<br/>تو چون روح نيز جاری شدى،<br/>در ما از راه فيض.<br/>',NULL,65622,2);
INSERT INTO stanza VALUES('F12','3','گرچه ما در گناه و شر<br/>زود از تو دور شديم،<br/>بازخرید کردی در پسر،<br/>حيات و فيض دهی.<br/>',NULL,65623,3);
INSERT INTO stanza VALUES('F12','4','گرچه تحقيرت می كرديم،<br/>روحت محزون می شد،<br/>اما چون روحْ باز می آيى<br/>بهرِ حیات دادن.<br/>',NULL,65624,4);
INSERT INTO stanza VALUES('F12','5','تو همچون آن روحْ در پسر<br/>با ما آميخته ای؛<br/>در مشاركت مسح كنى،<br/>و توسعه یابی.<br/>',NULL,65625,5);
INSERT INTO stanza VALUES('F12','6','عشقِ خدا، فيضِ مسيح،<br/>جريانِ روح، آزاد،<br/>شريک ثروتهات هستیم<br/>تا ابدالاباد.<br/>',NULL,65626,6);
INSERT INTO stanza VALUES('F12','7','پدر، پسر و روح – يكى،<br/>بَس مراقبِ ما؛<br/>عشقت خوانیم با یکدلی،<br/>دائم ستاییمت.<br/>',NULL,65627,7);
INSERT INTO stanza VALUES('F13','1','نور و عشق هستی، خداوند،<br/>در پسر، حیات هستی؛<br/>ابرازِ عشق، تابشِ نور،<br/>به ما حیات می بخشی.<br/>',NULL,65628,1);
INSERT INTO stanza VALUES('F13','chorus','عشق هستی! نور هستی!<br/>در پسر، حیات هستی؛<br/>ابرازِ عشق، تابشِ نور<br/>به ما حیات می بخشی.<br/>',NULL,65629,2);
INSERT INTO stanza VALUES('F13','2','عشق حاکی است از وجودت،<br/>نور نشانِ کارهایت؛<br/>عشقْ درونی ، نورْ بُرونی،<br/>عشق به همراهِ نور است.<br/>',NULL,65630,3);
INSERT INTO stanza VALUES('F13','3','عشق با فیض آشکار می شود،<br/>و نور با واقعیت؛<br/>با عشق لذت می بریمت،<br/>با نور می شناسیمت.<br/>',NULL,65631,4);
INSERT INTO stanza VALUES('F13','4','از عشق، به جلجتا رفتی،<br/>تا حیات دریافت کنیم؛<br/>نور به ما فهم و درک بخشید،<br/>تا خونت بکار بریم.<br/>',NULL,65632,5);
INSERT INTO stanza VALUES('F13','5','از عشق، چون حیات آمدی<br/>با ما به مشارکت؛<br/>روشنی گیریم از نورت،<br/>مانیم در مشارکت.<br/>',NULL,65633,6);
INSERT INTO stanza VALUES('F13','6','از نور و خون که پاک کند،<br/>مَسح را دریافت می کنیم؛<br/>پس عشق، حیاتِ عنصرت،<br/>در ما جاری می شود.<br/>',NULL,65634,7);
INSERT INTO stanza VALUES('F13','7','در عشقت فرزندانت ایم،<br/>اَبا، پدر خوانیم ات؛<br/>نور، تاریکی را دور کرده<br/>تا بینیم چون پسرت.<br/>',NULL,65635,8);
INSERT INTO stanza VALUES('F13','chorus','چه فیضی! چه راستی!<br/>درعشق و نور بینیم ات!<br/>دائم ستایش ات کنیم،<br/>درعشق و نور دانیم ات!<br/>',NULL,65636,9);
INSERT INTO stanza VALUES('F15','1','ای خدای متعال،<br/>تو آن قدوس هستی!<br/>هیچ کس با تو برابر<br/>نیست، تو بی نظیری!<br/>آن قدوس ترین قدوس<br/>این عالم بخوانَد!<br/>قدرت و طبیعتت<br/>فراترین رَوَد!<br/>',NULL,65637,1);
INSERT INTO stanza VALUES('F15','2','متمایز، تک، قدوس،<br/>نه فقط راست، پاکی؛<br/>نه تنها بی نقص و عیب،<br/>بلکه کامل هستی؛<br/>هیچ چیز به تو نرسد،<br/>هم ترازِ تو نیست؛<br/>جای تو را گرفتن،<br/>به تو اهانت است.<br/>',NULL,65638,2);
INSERT INTO stanza VALUES('F15','3','آن عالی ترین عالی،<br/>تو تنها نیکویی؛<br/>مرغوب تر از مرغوبی،<br/>منحصر به فردی.<br/>عدالتت یگانه،<br/>چون تو مطلق هستی؛<br/>زیبایی ات بی رقیب،<br/>تو برترین هستی.<br/>',NULL,65639,3);
INSERT INTO stanza VALUES('F15','4','ما را مقدس کردی<br/>با قدوسیَت ات؛<br/>این ذاتِ متمایز<br/>را هستیم شریک ات.<br/>با داشتن ذاتِ تو<br/>چون تو والا شدیم؛<br/>از حیاتت برخوردار،<br/>تا کمال رشد کنیم.<br/>',NULL,65640,4);
INSERT INTO stanza VALUES('F15','5','حمد و پرستش کنیم<br/>بهرِ قداست ات،<br/>بهرِ ذاتِ والایت،<br/>و بی نظیری ات.<br/>شکرت کنیم که ذاتت<br/>را با هم شریکیم؛<br/>این ذاتِ مقدس را<br/>ما همیشه داریم.<br/>',NULL,65641,5);
INSERT INTO stanza VALUES('F16','1','پدرمان، هميشه سبز،<br/>تا ابد نو هستى؛<br/>خداى هميشه زنده،<br/>چون شبنم تازه ای.<br/>',NULL,65642,1);
INSERT INTO stanza VALUES('F16','chorus','اى پدر، تغيير نکنی،<br/>هرگز كهنه نَشى؛<br/>همۀ اعصار، همیشه<br/>آشكاره تازگیْت.<br/>',NULL,65643,2);
INSERT INTO stanza VALUES('F16','2','تويى خدا و تويى نو؛<br/>همه كهنه ست بى تو،<br/>اما همه چيز با تو نو،<br/>حتى پس از سالها.<br/>',NULL,65644,3);
INSERT INTO stanza VALUES('F16','3','هر برْكتى دادى به ما<br/>داراست نویی ات را؛<br/>عهدِ تو و راههايت نو،<br/>تا ابدالاباد.<br/>',NULL,65645,4);
INSERT INTO stanza VALUES('F16','4','حال ما خلقتِ نو هستیم –<br/>روحِ نو، قلبِ نو؛<br/>روزانه تازه می شويم،<br/>دَهی حياتِ نو.<br/>',NULL,65646,5);
INSERT INTO stanza VALUES('F16','5','زمين و آسمانِ نو،<br/>شريک در شهرِ نو؛<br/>هر ماه حاضر ميوۀ نو،<br/>آنجا همه چیز نو.<br/>',NULL,65647,6);
INSERT INTO stanza VALUES('F16','6','اى پدر، هميشه نویی،<br/>همه چيز نوست در تو؛<br/>با شعرِ نویِ ابدی،<br/>ستايیم تو را نو.<br/>',NULL,65648,7);
INSERT INTO stanza VALUES('F17','1','خدا پدر، چون خلقتِ وسیعت،<br/>آسمان و زمین را نِگرم،<br/>بزرگ و کوچک، خارج از شمارش،<br/>قدرتِ عظیمَت آشکار کنند؛<br/>',NULL,65649,1);
INSERT INTO stanza VALUES('F17','chorus','پس وجودم ستایش ات کند،<br/>چه شگرفی! چه عظیمی!<br/>این را خوانم تا به ابدیَت،<br/>چه شگرفی! چه عظیمی!<br/>',NULL,65650,2);
INSERT INTO stanza VALUES('F17','2','چون از فیضِ نجاتت لذت برَم،<br/>اینکه چطور پسرت را دادی،<br/>آن که مُرد تا ما خلقتِ نو شویم،<br/>و ابرازِ کاملِ حیاتت؛<br/>',NULL,65651,3);
INSERT INTO stanza VALUES('F17','3','چون در کلیسا، در سهمِ مبارک،<br/>میلیونها را با حیاتت بینم،<br/>چطور بنا شدند بهر مسکن ات،<br/>حاویِ تو، ابرازِ پُری ات؛<br/>',NULL,65652,4);
INSERT INTO stanza VALUES('F17','4','چون منتظرِ ظهورِ آن عصرم<br/>و در امیدِ اورشلیمِ نو،<br/>با آسمان و زمین در تازگی<br/>و ابرازت در همۀ آنها؛<br/>',NULL,65653,5);
INSERT INTO stanza VALUES('F18','1','چه امین و با امانت<br/>هستی، خدا پدر؛<br/>جهان و هر چه در آن است<br/>گویند از وفایت.<br/>',NULL,65654,1);
INSERT INTO stanza VALUES('F18','chorus','ثابت است وفاداریَت!<br/>پس می ستایمَت؛<br/>وفای تو در آسمان،<br/>دائم برایم هست.<br/>',NULL,65655,2);
INSERT INTO stanza VALUES('F18','2','سایۀ چرخش در تو نیست،<br/>تغییر ناپذیری؛<br/>آنچه بودی، حال هستی و<br/>همیشه می باشی.<br/>',NULL,65656,3);
INSERT INTO stanza VALUES('F18','3','کلامت قطعی چون خودت،<br/>هیچ زایل نشود،<br/>زمین و سما محو شوند،<br/>کلام تو مانَد.<br/>',NULL,65657,4);
INSERT INTO stanza VALUES('F18','4','پس نگیری عطایایت،<br/>نیز فراخوانی ات؛<br/>فیض ات همیشه ماندگار،<br/>نیز رحمت و نامت.<br/>',NULL,65658,5);
INSERT INTO stanza VALUES('F18','5','کلام و وفاداریَت<br/>اطمینانِ من است؛<br/>با نجاتِ حتمی تو،<br/>یقین مالِ من است.<br/>',NULL,65659,6);
INSERT INTO stanza VALUES('F18','6','گر بهر نفْس، من شک کنم،<br/>لیک تو وفاداری؛<br/>خود را نهی نتوانی کرد،<br/>حرفت اجرا کنی.<br/>',NULL,65660,7);
INSERT INTO stanza VALUES('F18','7','چون با وفا اجرا کنی<br/>قول و انتخاب ات؛<br/>پس، از وفایت برخوردار،<br/>می کنم دریافت ات.<br/>',NULL,65661,8);
INSERT INTO stanza VALUES('F18','8','رنگین کمانِ تخت تو<br/>از وفایت گوید؛<br/>این صفت را شهرِ قدوس<br/>مدام حاوی باشد.<br/>',NULL,65662,9);
INSERT INTO stanza VALUES('F19','1','«وفایت عظیم است،» ای خدا، پدر،<br/>در تو نیست هیچ سایۀ تغییری؛<br/>مِهر و ترحمِ تو بی پایان است؛<br/>همان که بودی، همیشه هستی.<br/>',NULL,65663,1);
INSERT INTO stanza VALUES('F19','chorus','«وفایت عظیم است!»<br/>«وفایت عظیم است!»<br/>هر روز رحمتهای تازه بینم؛<br/>بهرِ نیازم، دستت فراهم کرد –<br/>«وفایت عظیم است،» برای من!<br/>',NULL,65664,2);
INSERT INTO stanza VALUES('F19','2','تابستان، زمستان، پاییز و بهار،<br/>خورشید، ماه، ستارگانْ منظم،<br/>با کلِ خلقت شهادت می دهند<br/>به وفایت، رحمت و عشقت هم.<br/>',NULL,65665,3);
INSERT INTO stanza VALUES('F19','3','بخششِ گناه و صلحِ ماندگار،<br/>با حضورت، خوشایند و رهبر؛<br/>قوتِ امروز و امیدِ فردا،<br/>برْکاتِ من با هزاران بیشتر!<br/>',NULL,65666,4);
INSERT INTO stanza VALUES('F22','1','پدرِ قدوس، پرستیم،<br/>گرامی ات می داریم؛<br/>تو قدوس و ارجمندی،<br/>«نامت قدوس»، ستاییم.<br/>',NULL,65667,1);
INSERT INTO stanza VALUES('F22','2','قلبت پُر مهر است، ای پدر،<br/>راههای تو صالح است؛<br/>اما ذات تو قدوس است،<br/>بیانگرِ مسیح است.<br/>',NULL,65668,2);
INSERT INTO stanza VALUES('F22','3','ما را تقدیس کرده ای با<br/>خونِ مسیحْ خداوند؛<br/>گناهکار را جدا کردی<br/>با کلامِ حقیقت.<br/>',NULL,65669,3);
INSERT INTO stanza VALUES('F22','4','با روحِ قدوست ما را<br/>بهرِ خود تقدیس کردی؛<br/>روح، روان و بدن ما<br/>را کامل تقدیس کنی.<br/>',NULL,65670,4);
INSERT INTO stanza VALUES('F22','5','حیاتِ قدوسِ عیسی<br/>با فیض تصرف کنیم؛<br/>حتی از قدوسیّت ات<br/>ما برخوردار می شویم.<br/>',NULL,65671,5);
INSERT INTO stanza VALUES('F22','6','وقتی در شهر مقدس،<br/>سهیم در قدوسیّت،<br/>بگوییم «تو قدوس هستی»،<br/>دائم و بی نهایت.<br/>',NULL,65672,6);
INSERT INTO stanza VALUES('F23','1','در حکمتت، خدا پدر،<br/>طبق اراده ات،<br/>قصدت جاوْدان، که همه را<br/>پُر کند پسرت.<br/>',NULL,65673,1);
INSERT INTO stanza VALUES('F23','chorus','عمیق و غنی حکمتت،<br/>که داند حدش را؟<br/>لیک، پدر، یابیم ما در آن<br/>رحمت و فیض ات را!<br/>',NULL,65674,2);
INSERT INTO stanza VALUES('F23','2','شگرف است کلِ خلقتت،<br/>که داند فکرت را؟<br/>همه با تو، از تو، در تو،<br/>حکمتت هویدا.<br/>',NULL,65675,3);
INSERT INTO stanza VALUES('F23','3','حکمتت در گناه بند کرد،<br/>تا رحمت فاش شود،<br/>که هیچ کسی در هیچ چیزی<br/>جُز تو فخر نکند.<br/>',NULL,65676,4);
INSERT INTO stanza VALUES('F23','4','در حکمت، از راه صلیب،<br/>بازخرید حاصل شد،<br/>تا روحِ ما خودِ تو را<br/>چون گنج حاوی باشد.<br/>',NULL,65677,5);
INSERT INTO stanza VALUES('F23','5','حکمتِ تو را قدرتها،<br/>از کلیسا دانند،<br/>حکمت گوناگون ات را<br/>از راه ما بینند.<br/>',NULL,65678,6);
INSERT INTO stanza VALUES('F23','6','در اورشلیم نو وقتی<br/>فخر کنیم در رحمت،<br/>حکمتت شناخته شود<br/>به حد نهایت.<br/>',NULL,65679,7);
INSERT INTO stanza VALUES('F26','1','خدا، شکر بهرِ رحمتت،<br/>که بس عظیم و ژَرف است!<br/>در ضعف و شکست های ما؛<br/>با عظمت سرشار است.<br/>ستاییمت! ستاییمت!<br/>این رحمت، تاج ما است!<br/>',NULL,65680,1);
INSERT INTO stanza VALUES('F26','2','از این رحمت در حیرت ایم،<br/>که وسیع و گسترده ست!<br/>به ما مجرمین هم رسید<br/>و ما را نگه دارد.<br/>از این رحمت، از این رحمت،<br/>چه ما را جدا کند؟<br/>',NULL,65681,2);
INSERT INTO stanza VALUES('F26','3','شکر کنیم بَهرِ رحمتت،<br/>که غنی و سرشار است!<br/>از رحمتت در بازخرید،<br/>محبت کردی ما را.<br/>بدون آن، بدون آن،<br/>چطور عزت یابیم ما؟<br/>',NULL,65682,3);
INSERT INTO stanza VALUES('F26','4','آه، رحمتت، بس الهام بخش!<br/>آرام، لطیف و شیرین!<br/>با صبر و مهربانی ات،<br/>نیازمان رفع کند.<br/>گر قدر دانیم، گر قدر دانیم،<br/>هیچ رقیبی ندارد.<br/>',NULL,65683,4);
INSERT INTO stanza VALUES('F26','5','پدر، مسرت بَریم از<br/>رحمتت، نو و تازه؛<br/>آن هر صبح جاری است بر ما،<br/>تازه کند چون شبنم.<br/>می چشیمش! می چشیمش!<br/>پُر از ستایش شویم.<br/>',NULL,65684,5);
INSERT INTO stanza VALUES('F26','6','از ستایش باز نایستیم،<br/>چون رحمتت ماندگار؛<br/>کل فیض و لطفِ تو را<br/>ایمن کند بهرِ ما.<br/>تکیه بر آن، تکیه بر آن،<br/>اطمینان بخشد ما را.<br/>',NULL,65685,6);
INSERT INTO stanza VALUES('F28','1','عشقِ خدا عمیق تر است<br/>از بیانِ آدمیان؛<br/>فراتر از آسمانهاست،<br/>رسد به اعماقِ زمین.<br/>بهرِ آن زوجِ تقصیرکار،<br/>خدا پسرش را داد؛<br/>و آشتی داد ما را با خود،<br/>چون گناهان را بخشید.<br/>',NULL,65686,1);
INSERT INTO stanza VALUES('F28','chorus','عشقِ خدا، غنی و ناب!<br/>چه قوی و بیکران!<br/>تا ابد دوام آورد<br/>سرودِ مقدسان.<br/>',NULL,65687,2);
INSERT INTO stanza VALUES('F28','2','چون این زمانها گذرند،<br/>حکومتها سقوط کنند؛<br/>آن که دعا نمی کند،<br/>بر تپه ها فریاد زنَد؛<br/>عشقِ خدا هنوز مانَد،<br/>قوی و بیکران؛<br/>فیض بخشد به نسل آدم –<br/>سرودِ مقدسان.<br/>',NULL,65688,3);
INSERT INTO stanza VALUES('F28','3','گر دریا با جوهر پُر بود،<br/>و آسْمانها کاغذ بودند؛<br/>گر هر ساقه یک قلم بود،<br/>و انسانها کاتب بودند؛<br/>نوشتن از عشقِ خدا<br/>خشک می کرد دریا را؛<br/>کاغذها هم کم می آمد<br/>از سَما تا سَما.<br/>',NULL,65689,4);
INSERT INTO stanza VALUES('F30','1','چه عشقى به ما بخشيدى،<br/>از قلب شكرت كنيم؛<br/>پدرمان، پَرَستيم و<br/>ستايش ات كنيم.<br/>',NULL,65690,1);
INSERT INTO stanza VALUES('F30','2','قلبت به ما آشكار كردى،<br/>خواستَت شناساندى؛<br/>در پسر جلو آمدى،<br/>قصدت کامل کنى.<br/>',NULL,65691,2);
INSERT INTO stanza VALUES('F30','3','دادى پسرِ محبوبت<br/>در عشق، تا بميرد،<br/>که ما شويم پسرانت،<br/>و با او وارث ات.<br/>',NULL,65692,3);
INSERT INTO stanza VALUES('F30','4','در او حياتت را داريم،<br/>تو پدر مايى؛<br/>ذات و همۀ وجودت<br/>را به ما مى دهى.<br/>',NULL,65693,4);
INSERT INTO stanza VALUES('F30','5','روحِ تو در ما آمده<br/>تا «اَبا» بخوانيم؛<br/>مولودِ روح و مُهر با روح،<br/>تا دگرگون شويم.<br/>',NULL,65694,5);
INSERT INTO stanza VALUES('F30','6','پسرانت جلال دهى<br/>هدفِ ابدی،<br/>به صورتِ پسرِ خود،<br/>همشکلِ او کنی.<br/>',NULL,65695,6);
INSERT INTO stanza VALUES('F30','7','در كارِ دگرگونى ات<br/>هدايت می كنى،<br/>از جلال به جلال آرى<br/>تا كار انجام شود.<br/>',NULL,65696,7);
INSERT INTO stanza VALUES('F30','8','چه عشقى، پدر، بخشيدى؛<br/>هميشه شكر كنيم؛<br/>می پرستيم ات تا ابد،<br/>پيوسته ستاييم.<br/>',NULL,65697,8);
INSERT INTO stanza VALUES('F32','1','می پرستیمت، ای پدر،<br/>از عشق تو در شگفتیم.<br/>انسان چیست که تو لطف کردی<br/>به او چنین فیضی دهی!<br/>',NULL,65698,1);
INSERT INTO stanza VALUES('F32','2','بهرِ قصدت ستاییم که<br/>انسان شبیه تو باشد،<br/>که با حیات و ذاتت پُر،<br/>صورتت را اظهار کند.<br/>',NULL,65699,2);
INSERT INTO stanza VALUES('F32','3','ما را به صورتت ساختی،<br/>و اقتدارت را دادی،<br/>خود را چون حیات بخشیدی<br/>تا با غنایت زیست کنیم.<br/>',NULL,65700,3);
INSERT INTO stanza VALUES('F32','4','بهرِ وارد شدن در ما،<br/>با فیض آمیخته ای با ما،<br/>تا دگرگون، بنا شویم،<br/>و تا مسکن تو باشیم.<br/>',NULL,65701,4);
INSERT INTO stanza VALUES('F32','5','انسان سقوط کرد، تو اما<br/>تغییر ندادی قصدت را؛<br/>انسان را بازخرید کردی،<br/>عشق و حِکمت ثابت کردی.<br/>',NULL,65702,5);
INSERT INTO stanza VALUES('F32','6','تو در مسیح آشکار شدی،<br/>که مُرد، قیام، بازخرید کرد؛<br/>و چون روح در ما آمدی<br/>و حیات و فیض بخشیدی.<br/>',NULL,65703,6);
INSERT INTO stanza VALUES('F32','7','روحم، قدوس ترین مکان،<br/>تختِ فیض یافت شود آنجا؛<br/>خواهی بخور بسوزانیم<br/>در روحمان و با دعا.<br/>',NULL,65704,7);
INSERT INTO stanza VALUES('F32','8','این فیض همچون نهری پُر است<br/>که از تختِ فیض می آید؛<br/>جریانش دگرگون، بنا<br/>سازد چون خانه ات ما را.<br/>',NULL,65705,8);
INSERT INTO stanza VALUES('F32','9','فیضِ بی نظیر، رایِگان<br/>را با حیرت دریافت کنیم؛<br/>مدیونِ عشقِ عظیم ات،<br/>در روح، تو را می پرستیم.<br/>',NULL,65706,9);
INSERT INTO stanza VALUES('F33','1','پدر،  قبل از خلقتْ ما را<br/>در عشقت برگزیدی؛<br/>عشقت ژرف، تکان دهنده،<br/>جذب کرد ما را به مسیح،<br/>و حفظ کند، و حفظ کند<br/>ما را تنها در مسیح،<br/>ما را تنها در مسیح.<br/>',NULL,65707,1);
INSERT INTO stanza VALUES('F33','2','گرچه دنیا تغییر کند،<br/>اما خدا یکسان است؛<br/>شفقت او و عهدش<br/>طیِ دورانْ پابرجاست.<br/>فرزندانش، فرزندانش،<br/>باید بستاییمش،<br/>باید بستاییمش.<br/>',NULL,65708,2);
INSERT INTO stanza VALUES('F33','3','شفقت های خدایم<br/>فخر و داستان من است؛<br/>رحمت های بی زوالش<br/>هادیِ راهِ من است.<br/>عشقِ خدا، عشقِ خدا،<br/>داد به ما پسرش را،<br/>داد به ما پسرش را.<br/>',NULL,65709,3);
INSERT INTO stanza VALUES('F33','4','ای پدرِ محبوبِ ما<br/>عشقت را می ستاییم؛<br/>شعرِ ما بی وقفه بُوَد<br/>تا ملاقاتت کنیم،<br/>جلال دهیم، جلال دهیم،<br/>به خدا و به برّه،<br/>به خدا و به برّه.<br/>',NULL,65710,4);
INSERT INTO stanza VALUES('F36','1','می ستاییمت، پدر،<br/>موردِ فیضت ایم،<br/>بهرِ خشنودیِ تو،<br/>حال در حضورت ایم:<br/>تو ما را نشان کردی –<br/>از قبل، بهرِ جلال –<br/>با مسیحِ محبوبت،<br/>هدفِ متعال.<br/>',NULL,65711,1);
INSERT INTO stanza VALUES('F36','2','کی غیر از تو، ای پدر،<br/>در پسر و با روح<br/>ما را سعادت دهد<br/>و تصرف کند؟<br/>بزودی و تا ابد<br/>با مسیحْ در جلال،<br/>در شکل او درخشیم<br/>همیشگی، آمین!<br/>',NULL,65712,2);
INSERT INTO stanza VALUES('F39','1','جلال بر خدا، کارهای بزرگ کرد،<br/>دنیا را دوست داشت که پسرش را داد،<br/>او جانش را داد و بازخرید ما را،<br/>و بر همه گشود دَرِ حیات را.<br/>',NULL,65713,1);
INSERT INTO stanza VALUES('F39','chorus','شکرْ خدا، شکرْ خدا،<br/>صدایش بشْنوید؛<br/>شکرْ خدا، شکرْ خدا،<br/>مردم شادی کنید؛<br/>اوه، از راهِ پسر به پدر آیید،<br/>کارهای بزرگ کرد؛ جلالش دهید.<br/>',NULL,65714,2);
INSERT INTO stanza VALUES('F39','2','آه، بازخریدْ کامل، با خونش خرید،<br/>به هر ایماندار عهدِ خدا بخشید؛<br/>هر گناهکاری که ایمان آورَد،<br/>آن لحظه از عیسی بخشش می گیرد.<br/>',NULL,65715,3);
INSERT INTO stanza VALUES('F39','3','کارهایِ عالی آموخته و کرده،<br/>در عیسی شادی ما افزون شده؛<br/>پاک تر، عالی تر و بزرگتر اما<br/>شادیِ ما تا ببینیم عیسی را.<br/>',NULL,65716,4);
INSERT INTO stanza VALUES('F40','1','شکرت خدایا،<br/>بهرِ پسرِ عشق،<br/>منجی عيسی که مُرد و<br/>اکنون در سَماست.<br/>',NULL,65717,1);
INSERT INTO stanza VALUES('F40','chorus','هللویاه! جلال از توست،<br/>هللویاه!  آمین؛<br/>هللویاه! جلال از توست،<br/>می ستاییمت.<br/>',NULL,65718,2);
INSERT INTO stanza VALUES('F40','2','شکرت خدایا،<br/>بهرِ روحِ نورت،<br/>نمایان کرد منجی و<br/>جدا كرد شب را.<br/>',NULL,65719,3);
INSERT INTO stanza VALUES('F40','3','جلال، ستایش<br/>بر تو پدرِ عشق،<br/>از بازخریدِ عیسی<br/>ثابت شد قلبت.<br/>',NULL,65720,4);
INSERT INTO stanza VALUES('F40','4','ستایش تو را؛<br/>پُر شدیم از عشقت،<br/>قلبها افروخته شد با<br/>آتش از بالا.<br/>',NULL,65721,5);
INSERT INTO stanza VALUES('F41','1','از خواندنِ شعرِ جاوید خسته نشویم:<br/>حمدْ خدا را، هللوياه!<br/>تا ابد با روحْ ستايش اش را سَراییم:<br/>حمدْ خدا را، هللوياه!<br/>',NULL,65722,1);
INSERT INTO stanza VALUES('F41','chorus','آه فرزندانِ خدا شعرِ شگرفی دارند،<br/>با فيض اش خدا پسرانش را جلال دهد،<br/>در آن روز خواهیم رفت ما به حضور پادشاه:<br/>حمدْ خدا را، هللوياه!<br/>',NULL,65723,2);
INSERT INTO stanza VALUES('F41','2','میانِ شورِ عشقِ بازخرید گم شديم:<br/>حمدْ خدا را، هللوياه!<br/>جوييم تا هر لحظه فيض اش را ثابت كنيم:<br/>حمدْ خدا را، هللوياه!<br/>',NULL,65724,3);
INSERT INTO stanza VALUES('F41','3','آن طور كه خدا گفته به جلال مى رسيم:<br/>حمدْ خدا را، هللوياه!<br/>آنجا كه شاه را در زيباییهايش بينيم:<br/>حمدْ خدا را، هللوياه!<br/>',NULL,65725,4);
INSERT INTO stanza VALUES('F41','4','فيض و رحمتش را در سرودی نو خوانيم:<br/>حمدْ خدا را، هللوياه!<br/>پرجلال منجى را با سعیدان ستاييم:<br/>حمدْ خدا را، هللوياه!<br/>',NULL,65726,5);
INSERT INTO stanza VALUES('F48','1','برْكتت دهيم، پدر،<br/>شاديم رو به رویت؛<br/>وَراى مرگ تا ابد،<br/>در سهمِ پسرت.<br/>او مَرديست مقابلت،<br/>در نورِ درخشان،<br/>در فيضِ بیکرانت،<br/>عشقِ ابدیْت.<br/>',NULL,65727,1);
INSERT INTO stanza VALUES('F48','2','پدرش، پدرِ ما،<br/>خداى او و ما؛<br/>او محبوبِ عزيزت،<br/>خشنودىِ قلبت.<br/>از اوييم، ما را آرَد<br/>شريک جا و خود،<br/>تا دانيم عشق و لطفت،<br/>در روى پُر نورت.<br/>',NULL,65728,2);
INSERT INTO stanza VALUES('F48','3','عشقت در بر گرفته،<br/>سرد و تار نمیشه؛<br/>او كه مركزِ عشقه،<br/>ما در او محبوبيم.<br/>در او جلال و عشقت<br/>آرام اند تا ابد؛<br/>پسران – برادرهاش –<br/>در او نزديک، خوشبخت!<br/>',NULL,65729,3);
INSERT INTO stanza VALUES('F50','1','پدر، پسر در ما ستایَدت<br/>بعد از تمام شدنِ ضيافت؛<br/>چه عزيز و شيرين ستايش اش،<br/>ما با ستایش اش يكى هستيم.<br/>',NULL,65730,1);
INSERT INTO stanza VALUES('F50','2','پدر، هيچ نیکی جز تو نخواهيم،<br/>و عشقى كمتر از تو نجوييم؛<br/>چه مى پرستيمَت چون حال دانيم<br/>حياتِ ابدى و الهی.<br/>',NULL,65731,2);
INSERT INTO stanza VALUES('F50','3','پدر، در عشقت عشقمان به تو<br/>از هر رابطه فراتر رَود؛<br/>عشقِ عزيزِ تو حاکم ماست،<br/>حضورت عمیقاً راضى كند.<br/>',NULL,65732,3);
INSERT INTO stanza VALUES('F50','4','پدر، از پيوستن با محبوبت،<br/>حال با شادى ستايش ات كنيم؛<br/>شاد، جشن گیریم درعشقِ قدوست،<br/>چون پسران، نامِ خوبت چِشیم.<br/>',NULL,65733,4);
INSERT INTO stanza VALUES('F52','1','پدر، سرود شادی سراییم،<br/>با فرزندان؛<br/>نزد تو، با آوازِ ستایش<br/>برای تو؛<br/>نزدیکیم به تو– ای فیضِ شگرف،<br/>ما را در جای پسر گذاشتی.<br/>',NULL,65734,1);
INSERT INTO stanza VALUES('F52','2','چه عمیق است شادیِ مقدس،<br/>شناختِ عشق!<br/>عشقت، پدر، حال دیده می شود،<br/>در پسرت؛<br/>چون در آرامشِ قدوسِ تو،<br/>او پیشوای ستایشِ مان است.<br/>',NULL,65735,2);
INSERT INTO stanza VALUES('F52','3','چه نفیس است به گوش تو، پدر،<br/>سرودِ او!<br/>چه نفیس نیز – چه نزدیک و عزیز،<br/>یارانِ او<br/>سهیم در او: این طرحِ تو بوده؛<br/>محبوبت قبل از آغاز عالم.<br/>',NULL,65736,3);
INSERT INTO stanza VALUES('F66','1','چه شیرین است نام عیسی<br/>به گوش ایماندار!<br/>تسکین غم، شفای زخم،<br/>دور کنندۀ ترس.<br/>',NULL,65737,1);
INSERT INTO stanza VALUES('F66','2','روحِ شکسته را کامل،<br/>تسکین دهد دل را؛<br/>منّای جانِ گرسنه،<br/>و آرامِ جانهاست.<br/>',NULL,65738,2);
INSERT INTO stanza VALUES('F66','3','نام عزیز! صخرۀ ما؛<br/>آن سپر و پناه؛<br/>گنجینۀ بی انتها،<br/>از فیضِ بی پایان.<br/>',NULL,65739,3);
INSERT INTO stanza VALUES('F66','4','عیسی، منجی، دوست و شبان،<br/>نبی، کاهن، حاکم؛<br/>خدا، حیات، راه و پایان،<br/>ستایش ات کنیم.<br/>',NULL,65740,4);
INSERT INTO stanza VALUES('F66','5','کوشش قلبمان ضعیف،<br/>افکار ما سرد است؛<br/>لیک چون درست تو را بینیم،<br/>ستایش ات کنیم.<br/>',NULL,65741,5);
INSERT INTO stanza VALUES('F66','6','پس عشقت را اعلام کنیم<br/>با هر نَفَسِمان؛<br/>پیروزی در نام عیسی،<br/>سرکوب کند مرگ را.<br/>(برای هر بند، دو خط آخر را تکرار کنید)<br/>',NULL,65742,6);
INSERT INTO stanza VALUES('F67','1','نام عیسی چه شیرینه،<br/>من عاشقِ تکرارش ام؛<br/>شادیم پُر و کامل کنه،<br/>نامِ نفیسِ عیسی.<br/>',NULL,65743,1);
INSERT INTO stanza VALUES('F67','chorus','عیسی! آه، نامِ شیرین،<br/>عیسی! هر روز همانند؛<br/>عیسی! همه بگویید<br/>ستایش اش همیشه.<br/>',NULL,65744,2);
INSERT INTO stanza VALUES('F67','2','عاشقشم آنکه قلبش<br/>می داند کلِ غمهام را؛<br/>و دور می کنه ترسهام را،<br/>عاشقِ نامِ عیسی.<br/>',NULL,65745,3);
INSERT INTO stanza VALUES('F67','3','عاشقِ شنیدنش ام،<br/>قلبم هر بار شاد می کنه،<br/>اشکِ ریزان خشک می کنه؛<br/>تمجید کن نامِ عیسی.<br/>',NULL,65746,4);
INSERT INTO stanza VALUES('F67','4','انسان نتواند گوید<br/>خوشیِ نامِ عیسی را،<br/>آه، ستایش اش زیاد شه،<br/>ستایش نامِ عیسی.<br/>',NULL,65747,5);
INSERT INTO stanza VALUES('F70','1','نامی هست که عاشقشم،<br/>سرودش را خوانم؛<br/>آن چون آهنگ است در گوشم،<br/>آن شیرین ترین نام.<br/>',NULL,65748,1);
INSERT INTO stanza VALUES('F70','chorus','آه، عاشق عیسام،<br/>آه، عاشق عیسام،<br/>آه، عاشق عیسام،<br/>چون عاشقِ من بود.<br/>',NULL,65749,2);
INSERT INTO stanza VALUES('F70','2','آن از عشق منجی گوید،<br/>مُرد تا رهام کند؛<br/>آن از خون نفیس گوید،<br/>پاسخی کامل است.<br/>',NULL,65750,3);
INSERT INTO stanza VALUES('F70','3','آن از پدرم می گوید،<br/>چه برایم دارد،<br/>با اینکه راه تاریک است، لیک<br/>دائم نور می دهد.<br/>',NULL,65751,4);
INSERT INTO stanza VALUES('F70','4','آن از عشقِ قلبش گوید<br/>که عمقِ غم داند،<br/>او در هر غمی سهم دارد<br/>که پُرتحمل است.<br/>',NULL,65752,5);
INSERT INTO stanza VALUES('F73','1','نام پرجلالِ عیسی،<br/>نام تو پناهم است؛<br/>سِتایم، پرستش کنم،<br/>چون نامت پیروزی است!<br/>',NULL,65753,1);
INSERT INTO stanza VALUES('F73','2','عیسی، منجیِ پر برْکت!<br/>در نامت همه چیز است؛<br/>تنفسِ نام عیسی،<br/>نوشیدن از حیات است.<br/>',NULL,65754,2);
INSERT INTO stanza VALUES('F73','3','نام پرجلالِ عیسی،<br/>عالمگیر است قدرتش؛<br/>لیک گناهکارِ بخشیده،<br/>داند مرهمِ نامش.<br/>',NULL,65755,3);
INSERT INTO stanza VALUES('F73','4','عیسی! عیسی! نامِ نفیس،<br/>مرهمِ درد، و قوی؛<br/>در نامت زنده و پیروز،<br/>پرجلال عیسی آیی.<br/>',NULL,65756,4);
INSERT INTO stanza VALUES('F82','1','جلالش ترک کرد،<br/>روايتی جاوْدان،<br/>منجیِ ما آمد،<br/>و عيسى نامش بود.<br/>مولود در آخور،<br/>با خودى، غريبه،<br/>مَردِ اشكها و غمها و رنجها.<br/>',NULL,65757,1);
INSERT INTO stanza VALUES('F82','chorus','آه عاشقشم! مى پرستمش!<br/>نفَس، خورشيدم، همه چيزم!<br/>خالقِ عظيم، منجىِ من شد،<br/>پُرىِ خدا، ساكن در اوست.<br/>',NULL,65758,2);
INSERT INTO stanza VALUES('F82','2','چقدر افتاده،<br/>بازخرید آورده؛<br/>در تاريكىِ شب،<br/>بی امید و هدف،<br/>خداى رحيم،<br/>گذشت از جلالش،<br/>خوار شد تا جانم را نجات دهد.<br/>',NULL,65759,3);
INSERT INTO stanza VALUES('F82','3','بدونِ اكراه،<br/>با ذاتِ جسم و خون؛<br/>شكلِ انسان گرفت،<br/>فاش كرد طرحِ نهان.<br/>راز پرجلال،<br/>ایثارِ جُلجتا،<br/>حال دانم که تو «من هستم» هستى.<br/>',NULL,65760,4);
INSERT INTO stanza VALUES('F86','1','گرچه پرجلال، خدایی،<br/>در جسمْ به ما نزدیک شدی،<br/>پس انسانی ناچیز شدی؛<br/>عیسی، یادت کنم!<br/>',NULL,65761,1);
INSERT INTO stanza VALUES('F86','2','جلال را کنار گذاشتی<br/>و در خیمۀ جسم ماندی،<br/>ظاهری چشم گیر نداشتی؛<br/>عیسی، یادت کنم!<br/>',NULL,65762,2);
INSERT INTO stanza VALUES('F86','3','ریشه از زمینِ خشکی،<br/>تو مَردِ غم و رنج بودی،<br/>از اطراف بس تحقیر شدی؛<br/>عیسی، یادت کنم!<br/>',NULL,65763,3);
INSERT INTO stanza VALUES('F86','4','نرم است دلت و فروتن،<br/>حاضر به رنج، سختی دیدن،<br/>بی هیچ نوع شکایت کردن؛<br/>عیسی، یادت کنم!<br/>',NULL,65764,4);
INSERT INTO stanza VALUES('F86','5','انسانی لطیف و دلبر،<br/>کامل، میزان از هر نظر،<br/>هدیۀ آدریِ پدر؛<br/>عیسی، یادت کنم!<br/>',NULL,65765,5);
INSERT INTO stanza VALUES('F86','6','کارَت ارادۀ خدا،<br/>و به دروغ بی اعتنا،<br/>خودت امین، حکیمْ تنها؛<br/>عیسی، یادت کنم!<br/>',NULL,65766,6);
INSERT INTO stanza VALUES('F86','7','تسلیمِ خواستۀ خدا،<br/>متحمل شدی مرگ را،<br/>بر صلیب رفتی جای ما،<br/>عیسی، یادت کنم!<br/>',NULL,65767,7);
INSERT INTO stanza VALUES('F86','8','پس تمجید کرد خدا تو را<br/>با شکوهمندی و جلال،<br/>خم شوند زمین و سَما؛<br/>عیسی، حَمدت کنم!<br/>',NULL,65768,8);
INSERT INTO stanza VALUES('F116','1','چه شگرف است بازخریدت،<br/>خداى بخشنده!<br/>نَدید، نَشنید، نه درک شده<br/>چكار كردى بَرام!<br/>تو خدایی، اسرار آميز،<br/>بيش از عبارت هام!<br/>بازخرید چه عالی تر است<br/>از قدرتِ بیان.<br/>',NULL,65769,1);
INSERT INTO stanza VALUES('F116','2','مصلوب شدى و بهرِ ما<br/>خون و آب جارى شد؛<br/>كه حياتت به ما دهى،<br/>تا بازخرید شويم.<br/>خونِ نفيس ات شست ما را،<br/>تا كه قبول شويم؛<br/>تولدِ تازه داریم،<br/>حال با تو يک هستيم.<br/>',NULL,65770,2);
INSERT INTO stanza VALUES('F116','3','دانۀ الهى مُردى،<br/>دانه ها حمل كنى،<br/>مخلوط شده، بدنت ايم،<br/>در ذاتت شريکيم.<br/>ما افزايشِ خودتيم،<br/>تو محتواى ما؛<br/>از راه ما حرْكت كنى<br/>و آشكار مى شوى.<br/>',NULL,65771,3);
INSERT INTO stanza VALUES('F116','4','چون بدنت ايم، تو آيى<br/>در ما ساكن شوى؛<br/>در ما خانه ات را يابى،<br/>اعتمادت شويم.<br/>قلبت راضى، خشنود كنيم،<br/>همتاى تو هستيم،<br/>حال در يک بدن با خودت،<br/>شاديم در وجودت.<br/>',NULL,65772,4);
INSERT INTO stanza VALUES('F116','5','حال در يادت با یکدگر<br/>نمادها را بينيم،<br/>بهرِ بازخریدت کامل<br/>پُر از ستايش ايم.<br/>چون بدنت شديم، خدا،<br/>مسكن و عروست،<br/>شكر و پرستش ات كنيم،<br/>در ستايش مانیم.<br/>',NULL,65773,5);
INSERT INTO stanza VALUES('F117','1','مسيحْ خدا برخاسته،<br/>هللوياه!<br/>نيازمان رفع كرده،<br/>هللوياه!<br/>شادى و پيروزى كن،<br/>هللویاه!<br/>آسْمان و زمين، بخوان،<br/>هللویاه!<br/>',NULL,65774,1);
INSERT INTO stanza VALUES('F117','2','شاهِ پرجلال زِندَست،<br/>هللویاه!<br/>كو، ای مرگ، حالا نيش ات؟<br/>هللویاه!<br/>با مرگش نجات دهد،<br/>هللویاه!<br/>كو، ای قبر، پيروزی ات؟<br/>هللویاه!<br/>',NULL,65775,2);
INSERT INTO stanza VALUES('F117','3','كارِ بازخریدْ تمام،<br/>هللویاه!<br/>جنگید و نَبرْد را بُرد،<br/>هللویاه!<br/>مرگ نیست مانعِ قیام،<br/>هللویاه!<br/>مسيحْ صعود كرد بالا،<br/>هللویاه!<br/>',NULL,65776,3);
INSERT INTO stanza VALUES('F117','4','حال با مسيح اوج گيريم،<br/>هللویاه!<br/>دنبال او، سَرِ ما،<br/>هللویاه!<br/>مثلِ او برخواهیم خاست،<br/>هللویاه!<br/>آزاد از کلِ بندها<br/>هللویاه!<br/>',NULL,65777,4);
INSERT INTO stanza VALUES('F124','1','ستایش! مسیح پیروز است!<br/>او به پیروزی رسید!<br/>گناه و کهنگی، تمام،<br/>بازخریدْ کامل داریم!<br/>شکست قدرتهای شریر<br/>بر صلیب فاتحانه!<br/>',NULL,65778,1);
INSERT INTO stanza VALUES('F124','2','ستایش! مسیح قیام کرد!<br/>خدا او را برخیزاند!<br/>قدرتِ مرگ بلعیده شد،<br/>از مرگ به حیات آییم!<br/>ظلمت و جهنم شکست،<br/>قدرتش نمایان شد!<br/>',NULL,65779,2);
INSERT INTO stanza VALUES('F124','3','ستایش! مسیح صعود کرد!<br/>بر تختِ شاهی نشست!<br/>بالاتر از هر حکومت<br/>و قدرتى نام گرفت!<br/>قدرتِ تمام دریافت کرد،<br/>تا سرکوب شود دشمن!<br/>',NULL,65780,3);
INSERT INTO stanza VALUES('F124','4','هللویاه، مسیح پیروز!<br/>پیروز شد در جُلجُتا!<br/>هللویاه، رستاخیز کرد،<br/>آشکار کرد پیروزی اش.<br/>هللویاه، حال در صعود،<br/>تا ابد حکم می کند!<br/>',NULL,65781,4);
INSERT INTO stanza VALUES('F132','1','در سَما عیسی نشسته،<br/>مسيح در سلطنته؛<br/>خدا بالا بُرد انسان را،<br/>جلال تاجِ او شده.<br/>',NULL,65782,1);
INSERT INTO stanza VALUES('F132','2','ذاتِ انسانى پوشيد و<br/>طبقِ طرحِ خدا مُرد،<br/>در بدنْ رستاخيز كرد و<br/>چون انسانی صعود كرد.<br/>',NULL,65783,2);
INSERT INTO stanza VALUES('F132','3','خدا در او چه كوچک شد،<br/>و با انسان ساكن گشت؛<br/>انسان در او چه والا شد،<br/>انسان به خدا برگشت.<br/>',NULL,65784,3);
INSERT INTO stanza VALUES('F132','4','خدا با انسان آميخته،<br/>انسان شاهدِ خداست؛<br/>انسان با خدا آميخته،<br/>در خدا جلال يافته.<br/>',NULL,65785,4);
INSERT INTO stanza VALUES('F132','5','از آن پُرشکوه در سَما<br/>آن روحِ کامل آمد؛<br/>کلِ کار و شخصِ عیسی<br/>این روح اعلام می کند.<br/>',NULL,65786,5);
INSERT INTO stanza VALUES('F132','6','با آن پُرشکوه در سَما<br/>كليسا شناخته شد؛<br/>با روحِ قدوسِ عيسى<br/>اعضايش پيراسته اند.<br/>',NULL,65787,6);
INSERT INTO stanza VALUES('F132','7','حال يک انسان در سَماست چون<br/>او خدای عالمه؛<br/>عيسىْ مسيح منجىِ ما،<br/>تا ابد در جلاله!<br/>',NULL,65788,7);
INSERT INTO stanza VALUES('F133','1','خداوندِ همه، عیسی،<br/>جلال است تاجِ تو؛<br/>در قدرت و شکوهمندی،<br/>به کل، نامداری تو.<br/>',NULL,65789,1);
INSERT INTO stanza VALUES('F133','2','خدا در انسان، بر زمین،<br/>در قالبِ غلام؛<br/>انسان در خدا، در آسْمان،<br/>خداوندِ تمام.<br/>',NULL,65790,2);
INSERT INTO stanza VALUES('F133','3','تو انسانْ در جلال هستی،<br/>بر تختِ سلطنت؛<br/>بر زمین و در آسمان<br/>از توست کلِ قدرت.<br/>',NULL,65791,3);
INSERT INTO stanza VALUES('F133','4','متعال در آسمانها<br/>با والاترین نام،<br/>اقرار کنند تویی خدا<br/>و سَجده به آن نام.<br/>',NULL,65792,4);
INSERT INTO stanza VALUES('F133','5','هم خداوند و مسیحا،<br/>روحْ اعلام کرده ات؛<br/>در جلال، در آسمانها<br/>بر تخت می بینیم ات.<br/>',NULL,65793,5);
INSERT INTO stanza VALUES('F133','6','خداوند می پرستیمت،<br/>بهرَت می سراییم؛<br/>تو هستی خدای عالم،<br/>تو را می ستاییم.<br/>',NULL,65794,6);
INSERT INTO stanza VALUES('F147','1','تو مسح شدی، خداوند،<br/>شاه شاهان هستی!<br/>با پرستشِ کامل<br/>بهرَت می سراییم!<br/>ملکوتت جاوْدان است،<br/>تختِ تو استوار!<br/>حکمِ تو با عشق و عدل<br/>در  جلال، بر قرار!<br/>',NULL,65795,1);
INSERT INTO stanza VALUES('F147','2','بر بلندای صهیون<br/>خدا مستقر کرد<br/>تو را، و امتها را<br/>چون میراث به تو داد.<br/>خدا به تو سپرده<br/>اقتدارِ کل را،<br/>حکم کنی بر امتها<br/>تا ابدالاباد.<br/>',NULL,65796,2);
INSERT INTO stanza VALUES('F147','3','قبل از پُریِ زمان،<br/>چون ظلمت حکم فرماست،<br/>هزاران نفر هر روز<br/>فراخوانند تو را!<br/>مردمِ تو از هر جا<br/>می ستایند تو را؛<br/>با عشق می پرستند ات<br/>ای منجی-پادشاه!<br/>',NULL,65797,3);
INSERT INTO stanza VALUES('F147','4','چون در وقتِ معین<br/>تو با جلال آیی،<br/>زمین را با امتها<br/>ملکوتت کنی.<br/>در شُکوه و درخشش<br/>خدمت شَوی چون شاه،<br/>قومها و مردم همه<br/>بِسِتایند تو را!<br/>',NULL,65798,4);
INSERT INTO stanza VALUES('F151','1','پادشاه می آید تا حکم کند،<br/>جلال بر عیسی، آن برّۀ ذبح؛<br/>عدالت و آرامش آورَد،<br/>شادی بر قومها، چون عیسی شاه است.<br/>',NULL,65799,1);
INSERT INTO stanza VALUES('F151','chorus','سراییم شاه را ستاییم،<br/>عیسای ما، اوست شاهِ ما:<br/>سرودمان تنها بهرِ عیساست:<br/>جلال بر عیسی که اوست شاهِ ما.<br/>',NULL,65800,2);
INSERT INTO stanza VALUES('F151','2','همه در نور محشرش مانند،<br/>قومها در عشقش به هم پیوندند،<br/>عدل و راستی از او طلوع کند،<br/>شر پایان گیرد چون او شاه شود.<br/>',NULL,65801,3);
INSERT INTO stanza VALUES('F151','3','ملکوت او از آرامش است،<br/>آزادی پُر، حکمت فراوان است،<br/>دشمن، دوست شود در سرودِ فتح،<br/>شمشیر، داس شود چون عیسی شاه است.<br/>',NULL,65802,4);
INSERT INTO stanza VALUES('F151','4','سپس شناخت  و ترس از خداوند<br/>چون دریا زمین را فراگیرد؛<br/>همه چیز شکوهِ بهار باشد،<br/>و هماهنگ، چون عیسی شاه شود.<br/>',NULL,65803,5);
INSERT INTO stanza VALUES('F151','5','دعا کنیم ملکوت بیاید،<br/>زودتر آور، ای پدر، آن روز را<br/>تا خلقت این سرودِ نو خواند<br/>شریر سرکوب شود، و عیسی شاه.<br/>',NULL,65804,6);
INSERT INTO stanza VALUES('F152','1','اوه، چه عمیق و گسترده،<br/>عشقت خداوند عیسی!<br/>بیشتر از قدرتِ درکم،<br/>عمیق تر از هر دریا!<br/>باعث شد فدایم شوی<br/>و حیاتت را دهی،<br/>که  در تو پیوند بخورم<br/>و جزو خودت شَوم.<br/>',NULL,65805,1);
INSERT INTO stanza VALUES('F152','2','كى می تونه بگه چه چیز<br/>عشقت برایم آورد،<br/>اما بزرگترين شگرف<br/>این است که تو را آورد.<br/>اوه، اين عشقت داده به من<br/>تمامِ وجودت را؛<br/>شدم شريکِ حياتت<br/>و مسرور از ثروتت.<br/>',NULL,65806,2);
INSERT INTO stanza VALUES('F152','3','خدایا، عشقت ابرازِ<br/>ذاتِ الهىِ توست،<br/>ساختی حیاتم پُرمعنا،<br/>همشكلِ طرحِ خدا.<br/>فيضِ حياتم، چقدر هست<br/>سهمم كافى روز به روز؛<br/>من هستم هدفِ عشقت،<br/>پيوسته چِشَم تو را.<br/>',NULL,65807,3);
INSERT INTO stanza VALUES('F152','4','چى می تونه جدا كنه؟<br/>تا آخر عاشقمی!<br/>اوه، عشقت چه حکمی داره،<br/>خود را با من آميختی!<br/>تا ابد یک هستيم با هم؛<br/>تو در من و من در تو!<br/>اینه شهادتم خدا:<br/>با هم در عشقت گيريم!<br/>',NULL,65808,4);
INSERT INTO stanza VALUES('F154','1','از دانش فراتر است عشقِ تو،<br/>منجیْ عیسی، اما این جانِ من<br/>باشد که عرض و طول و بلندا<br/>و عمق، نیروی جاویدِ آن، را<br/>بیش شناسد.<br/>',NULL,65809,1);
INSERT INTO stanza VALUES('F154','2','از بیان فراتر است عشق تو،<br/>منجیْ عیسی، اما لبان من<br/>باشد بگوید به گناهکاران<br/>عشقت بردارد ترس را، در آنان<br/>عشق بِکارَد.<br/>',NULL,65810,2);
INSERT INTO stanza VALUES('F154','3','از ثنا فراتر است عشق تو،<br/>منجیْ عیسی، اما این دل من<br/>خوانَد از عشقت  پُر، غنی، آزاد<br/>که نزدیک کرد گناهکاری چون من<br/>را به خدا.<br/>',NULL,65811,3);
INSERT INTO stanza VALUES('F154','4','گرچه نتوان سرایید یا گفت<br/>و یا دانست عشق تو را اینجا،<br/>نزدت آورم خالی ظرفم را؛<br/>تو چشمۀ زندۀ عشق، پر کن<br/>ظرف مرا.<br/>',NULL,65812,4);
INSERT INTO stanza VALUES('F154','5','من ظرفی خالی ام ـ نه با یک فکر<br/>یا نگاهی عاشقانه به تو؛<br/>لیک آیم، و باز آیم نزد تو<br/>با این عذر، و اتکای کامل<br/>به عشق تو.<br/>',NULL,65813,5);
INSERT INTO stanza VALUES('F154','6','پُر کن، عیسی، با عشق خود مرا!<br/>رهبری کن به چشمۀ بالا؛<br/>باشد در ایمان نزدیکتر آیم،<br/>هیچ چشمۀ دیگری نجویم<br/>جز عشق تو.<br/>',NULL,65814,6);
INSERT INTO stanza VALUES('F154','7','عیسی، چون تو را رو در رو بینم،<br/>وقتی بر تختت با تو نشینم،<br/>از عشقت، عرض و طول و بلندا<br/>و عمق، نیروی جاویدِ آن، از<br/>جان سرایم.<br/>',NULL,65815,7);
INSERT INTO stanza VALUES('F162','1','در شکر و ثنا ایستاده جماعت<br/>با این سرودِ نو، در حضور عیسی.<br/>',NULL,65816,1);
INSERT INTO stanza VALUES('F162','chorus','بر آن که عاشق ما بود،<br/>ما را پاک کرد،<br/>بر او جلال تا ابدالاباد!<br/>آمین!<br/>',NULL,65817,2);
INSERT INTO stanza VALUES('F162','2','اینها روزی از گناهکاران بودند،<br/>حال با نظم، در جامه های پاک، سِتایند.<br/>',NULL,65818,3);
INSERT INTO stanza VALUES('F162','3','او سرکش را کاهن و شاه می سازد،<br/>ما را خریده و شعر نو یاد داده.<br/>',NULL,65819,4);
INSERT INTO stanza VALUES('F162','4','زبون و نومید بودیم ما مجرمین،<br/>گر هرگز ما را با عشق پاک نکرده بود.<br/>',NULL,65820,5);
INSERT INTO stanza VALUES('F162','5','رَسا ستایش اش فریاد می زنیم،<br/>تا دیگران با ایمان، این سرود خوانند.<br/>',NULL,65821,6);
INSERT INTO stanza VALUES('F163','1','هزاران زبان بخوانند<br/>ستایشِ او را،<br/>جلالِ شاه و خدایم،<br/>ظفرِ فیض اش را.<br/>',NULL,65822,1);
INSERT INTO stanza VALUES('F163','2','سَرور، خدای بخشنده،<br/>مرا کمک کن تا<br/>بر کلِ زمین پخش کنم<br/>حرمتِ نامت را.<br/>',NULL,65823,2);
INSERT INTO stanza VALUES('F163','3','عیسی! نامی که پایانِ<br/>ترسها و هم غمهاست؛<br/>به گوشِ گناهکار آهنگ،<br/>حیات، صلح و شفاست.<br/>',NULL,65824,3);
INSERT INTO stanza VALUES('F163','4','عشقش اسیر کرد قلبم را،<br/>اسیرش خواهم بود،<br/>چون او رنج کشید و مُرد تا<br/>جانم را رهانَد.<br/>',NULL,65825,4);
INSERT INTO stanza VALUES('F163','5','قدرتِ گناه را شکست،<br/>اسیر را آزاد کرد؛<br/>خونش تواند پاک کند؛<br/>خونش مرا پاک کرد.<br/>',NULL,65826,5);
INSERT INTO stanza VALUES('F163','6','پس حال عاشقِ نامت ام،<br/>خواستِ تو خواستم است.<br/>گر هزار دل داشتم، همه<br/>مال تو می بودند!<br/>',NULL,65827,6);
INSERT INTO stanza VALUES('F166','1','ستایش بر آن قادر مطلق،<br/>شاهِ خلقت!<br/>جانم بسِتایَش، اوست سلامت<br/>و نجاتت!<br/>هر که شنید،<br/>حال به او نزدیک آیید؛<br/>سرودِ نیایش خوانید!<br/>',NULL,65828,1);
INSERT INTO stanza VALUES('F166','2','ستایش بر خدا، بر همه چیز<br/>او حکم کند،<br/>بر بال های عقاب بالا بَرَد،<br/>نگه دارد.<br/>ندیدی که<br/>آرزویت در آنچه<br/>مقدر کرد، انجام شده؟<br/>',NULL,65829,2);
INSERT INTO stanza VALUES('F166','3','ستایش بر خدا، با ظرافت<br/>تو را خلق کرد!<br/>سلامت داد، اما چون افتادی،<br/>تو را حفظ کرد.<br/>چه نیازی<br/>هرگز بی جواب مانده؟<br/>رحمتش سایه افکنده.<br/>',NULL,65830,3);
INSERT INTO stanza VALUES('F166','4','ستایش بر خدا، رونق دهد،<br/>دفاع کند،<br/>آنکه از آسمان نهرهای<br/>رحمت فرستد.<br/>تعمُق کن،<br/>او قادرِ مطلق است،<br/>که با عشق رفتار می کند.<br/>',NULL,65831,4);
INSERT INTO stanza VALUES('F166','5','ستایش بر خدا، جانم او را<br/>می پرستد!<br/>هر که جان و نَفَس دارد، او را<br/>بِسِتاید!<br/>باشد «آمین»<br/>از قومش کند طنین؛<br/>او را پَرستیم تا ابد.<br/>',NULL,65832,5);
INSERT INTO stanza VALUES('F167','1','چه نیک است خداوندِ ما،<br/>آن دوستِ ثابت و امین؛<br/>عشقش چون قدرتش عظیم<br/>بیکران است و بی پایان.<br/>',NULL,65833,1);
INSERT INTO stanza VALUES('F167','2','آن عیساست، اول و آخر،<br/>که ما را به تخت رسانَد؛<br/>شکر او را بهرِ گذشته،<br/>با یقین بهرِ آینده.<br/>',NULL,65834,2);
INSERT INTO stanza VALUES('F169','1','ای عیسای ارزشمند،<br/>خشنودیِ خدا؛<br/>با روغنِ شادمانی،<br/>مَسح شدۀ خدا.<br/>',NULL,65835,1);
INSERT INTO stanza VALUES('F169','chorus','در عشق، ارزش ات دانیم<br/>زیباییِ تو را،<br/>شیرینی و عطرت را،<br/>نیکوییِ تو را.<br/>',NULL,65836,2);
INSERT INTO stanza VALUES('F169','2','از هر نظر جذابی<br/>زیبای زیبایان،<br/>لبانت پر از فیض است،<br/>این گوید قلبمان.<br/>',NULL,65837,3);
INSERT INTO stanza VALUES('F169','3','در تولد، حکیمان<br/>آوردند هدایا؛<br/>در مرگ، همانطور جذاب،<br/>دفن کرد شخصی والا.<br/>',NULL,65838,4);
INSERT INTO stanza VALUES('F169','4','سَرِ تو مَسح گردیده،<br/>تو هستی آن جذاب؛<br/>پایِ تو نیز مَسح گشته،<br/>از هر جهت محبوب.<br/>',NULL,65839,5);
INSERT INTO stanza VALUES('F169','5','چون مُر، شیرینْ مرگ تو<br/>و تسلی بخش است؛<br/>عطر رستاخیزِ تو<br/>رضایت خداست.<br/>',NULL,65840,6);
INSERT INTO stanza VALUES('F169','6','هستی چون گلِ حنا<br/>کاملاً دل انگیز؛<br/>چون درختی پُر سیب، با<br/>میوۀ فراوان.<br/>',NULL,65841,7);
INSERT INTO stanza VALUES('F169','7','عشقت بِه از شراب است،<br/>و ضیافتِ ما؛<br/>نام تو چون مرهم است،<br/>چِشیم شادی ات را.<br/>',NULL,65842,8);
INSERT INTO stanza VALUES('F169','8','چون در فکر تو هستیم<br/>و نیکوییهایت،<br/>شیرینی ات را چِشیم،<br/>آرام در آغوشت.<br/>',NULL,65843,9);
INSERT INTO stanza VALUES('F170','1','عیسی، تو دامادِ نیکو،<br/>منصوب شدۀ خدا؛<br/>عزیز و بسیار جذابی،<br/>در دلمان بس زیبا!<br/>',NULL,65844,1);
INSERT INTO stanza VALUES('F170','2','ای محبوب، می ستاییمت،<br/>کِه گوید ارزش ات را؛<br/>ارزشِ عشقت را دانیم،<br/>همه نیکویی ات را.<br/>',NULL,65845,2);
INSERT INTO stanza VALUES('F170','3','ای تو دلرباترینی،<br/>تو شیرین تر از شیرین؛<br/>تو حلیم و پر فیض هستی،<br/>از هر جهت بی رقیب.<br/>',NULL,65846,3);
INSERT INTO stanza VALUES('F170','4','جامه هایت با عطرِ مُر،<br/>و پر از فیض لبانت؛<br/>با طعمِ رنج های تو، ما<br/>در آغوش می کشیمت.<br/>',NULL,65847,4);
INSERT INTO stanza VALUES('F170','5','با روغنِ شادمانیست که<br/>خدا مسح کرده تو را؛<br/>از کاخ های عاج، ما دائم<br/>ستایش کنیم تو را.<br/>',NULL,65848,5);
INSERT INTO stanza VALUES('F170','6','خداوندِ متبارک،<br/>پیروزی حاصل کردی؛<br/>حال در جلال بر تختی با<br/>قدرت و شکوهمندی.<br/>',NULL,65849,6);
INSERT INTO stanza VALUES('F170','7','تویی خواستۀ امتها،<br/>ارزش ات ثابت کنند؛<br/>تویی سالارِ هزارها،<br/>شایستۀ عشقِ ما.<br/>',NULL,65850,7);
INSERT INTO stanza VALUES('F171','1','عیسی مسیح، دلهای ما<br/>شیرین با فکرِ تو،<br/>در آرزوی عروج تا<br/>آییم حضورِ تو!<br/>',NULL,65851,1);
INSERT INTO stanza VALUES('F171','chorus','خداوند، چون گل حنایی،<br/>در تاکستانها شکوفا؛<br/>بی همتایی در زیبایی،<br/>شیفته، عاشقیم ما!<br/>',NULL,65852,2);
INSERT INTO stanza VALUES('F171','2','هیچ آوایی کافی نیست تا<br/>فیض ات را ستایَد،<br/>نه هیچ قلبی تا از عشقت<br/>کامل لذت بَرَد.<br/>',NULL,65853,3);
INSERT INTO stanza VALUES('F171','3','لیک، بیشترین خوشیِ ما<br/>نه عشق، نه فیض ات است؛<br/>بلکه خودِ محبوبتی<br/>که رضایت بخشی.<br/>',NULL,65854,4);
INSERT INTO stanza VALUES('F171','4','آه، زیباتر از زیبایی،<br/>شیرین تر از شیرین؛<br/>نَه در زمین و آسمان،<br/>بجز تو را جوییم.<br/>',NULL,65855,5);
INSERT INTO stanza VALUES('F180','1','عیسی، خداوند، ما شیفتۀ توییم،<br/>تو را می ستاییم، که بر تختی!<br/>پربرْکت در حضورت، می پرستیم،<br/>تنها تو لایق، تو لایق هستی.<br/>',NULL,65856,1);
INSERT INTO stanza VALUES('F180','chorus','خداوند، لایق: خداوند، لایق؛<br/>خداوند، تنها تو لایق هستی!<br/>پربرکت در حضورت، می پرستیم،<br/>تنها تو لایق، تو لایق هستی!<br/>',NULL,65857,2);
INSERT INTO stanza VALUES('F180','2','همانا خدا، اما انسان شدی،<br/>جای ما مرگ را تجربه کردی،<br/>همان وعدۀ دیرین از «نسل زن»<br/>کوبیدی سَرِ مار، له اش کردی!<br/>',NULL,65858,3);
INSERT INTO stanza VALUES('F180','3','خودت را فروتن و تسلیم ساختی،<br/>از مخلوقاتت بر صلیب شدی،<br/>انسان رَدَت، و خدا هم ترک ات کرد،<br/>از ظلمت و لعنت نگریختی.<br/>',NULL,65859,4);
INSERT INTO stanza VALUES('F180','4','پیروز شدی، با جلال پیروز شدی،<br/>کل نیروی مرگ را پس زدی!<br/>چگونه خودداری کنیم از گفتن؟<br/>که بر مرگ و قبر، تو پیروز هستی.<br/>',NULL,65860,5);
INSERT INTO stanza VALUES('F185','1','ای پربرکت، هللویاه<br/>بهرَت سراییم.<br/>هیچ نتوانیم گوییم ما<br/>ارزش تو را!<br/>',NULL,65861,1);
INSERT INTO stanza VALUES('F185','chorus','شکرت، برّۀ پُربها!<br/>همیشه شیرین.<br/>هللویاه! هللویاه!<br/>شکر، خدا، آمین!<br/>',NULL,65862,2);
INSERT INTO stanza VALUES('F185','2','شکرت برّه، پُربهایی،<br/>خونت را ریختی<br/>تا رهانی، ما را شاه و<br/>کاهنان سازی!<br/>',NULL,65863,3);
INSERT INTO stanza VALUES('F185','3','هللویاه! عیسی خدا،<br/>عشقت بی پایان؛<br/>مالِ تو هستیم همیشه،<br/>یک با تو شادمان.<br/>',NULL,65864,4);
INSERT INTO stanza VALUES('F185','4','شکر خدایا! هللویاه!<br/>که ساکت کند؟<br/>بپیوند به مقدسین،<br/>هر قوم و زبان.<br/>',NULL,65865,5);
INSERT INTO stanza VALUES('F189','1','تو پسر محبوبی،<br/>آن صورتِ خدا؛<br/>سهمِ مقدسینی،<br/>که خونت داد به ما.<br/>بینِ خلقتِ خدا<br/>نخست زاده هستی؛<br/>خلق کردی همه چیز را<br/>تا تصرف کنی.<br/>',NULL,65866,1);
INSERT INTO stanza VALUES('F189','2','تو قبل از مخلوقاتی،<br/>در تو همه هستند؛<br/>بهرِ کل، تو مرکزی،<br/>از تو همه هستند.<br/>تو تنها سرآغازی،<br/>رستاخیزِ اول،<br/>بهرِ کلیسا، بدن،<br/>تو سَرِ پرجلال.<br/>',NULL,65867,2);
INSERT INTO stanza VALUES('F189','3','خشنودیِ پدر بود،<br/>کمالِ او در توست،<br/>در هر چیزْ مقدمی،<br/>برای ما نخست.<br/>همه را آشتی دادی<br/>به خدا، با خونت،<br/>ما را ارائه دهی<br/>مقدس و بی عیب.<br/>',NULL,65868,3);
INSERT INTO stanza VALUES('F189','4','در تو پُریِ خداست،<br/>تو رازِ خدایی؛<br/>گنج های فهم و حکمت<br/>همه در توست مخفی.<br/>تو امیدِ جلالی،<br/>در ما مسکن داری؛<br/>ما را بی عیب می کنی<br/>و خدا را راضی.<br/>',NULL,65869,4);
INSERT INTO stanza VALUES('F189','5','همه چیزها سایه اند،<br/>تو را نشان دهند؛<br/>تو تنها واقعیت،<br/>در تو ریشه داریم.<br/>غنایت لذت بریم،<br/>کمالت خواهیم شد؛<br/>در پیوند، بدنت ایم،<br/>در تو رشد می کنیم.<br/>',NULL,65870,5);
INSERT INTO stanza VALUES('F189','6','با تو در خدا پنهان،<br/>تو در ما حیاتی؛<br/>صلح ات در ما حکم فرما،<br/>نداریم درگیری.<br/>در انسانِ نو، بدن،<br/>همه، در همه ای؛<br/>منجی، شاملِ تمام<br/>دائم تو را خوانیم.<br/>',NULL,65871,6);
INSERT INTO stanza VALUES('F190','1','عیسی، چون می نگریمت،<br/>می ستاییم وجودت را؛<br/>خیلی غنی، شگرف، عزیز<br/>و نفیس هستی بهرِ ما.<br/>',NULL,65872,1);
INSERT INTO stanza VALUES('F190','chorus','وجودت هر نیاز رفع کند!<br/>از ستایش ات لبریزیم!<br/>فَرای خواسته ها رَوی<br/>و دائماً راضی کنی.<br/>',NULL,65873,2);
INSERT INTO stanza VALUES('F190','2','خدای حقیقی هستی،<br/>خدایی که عشق و نور است؛<br/>خدایی که حیاتِ ماست،<br/>خدایی که شادیِ ماست.<br/>',NULL,65874,3);
INSERT INTO stanza VALUES('F190','3','همچنین یک انسان هستی،<br/>انسانِ نیک، عالی، خالص؛<br/>انسانِ محبوبِ خدا،<br/>آن انسانِ محبوبِ ما.<br/>',NULL,65875,4);
INSERT INTO stanza VALUES('F190','4','حتی بَرده ای فروتن،<br/>از خدا، به خدمتِ ما؛<br/>و مطیع به مرگِ صلیب<br/>تا توانیم شَویم رها.<br/>',NULL,65876,5);
INSERT INTO stanza VALUES('F190','5','همچنین پادشاه هستی،<br/>شاهی که در عشق حکم کنی،<br/>مَسحِ خدا، با قدرتش<br/>تا در او با ما حکم کنی.<br/>',NULL,65877,6);
INSERT INTO stanza VALUES('F190','6','عیسی، چون یادت می کنیم،<br/>پس تو را سهیم می شویم؛<br/>چون درعشق لذت ات بَریم،<br/>چون همتا سهیم ات شَویم.<br/>',NULL,65878,7);
INSERT INTO stanza VALUES('F191','1','خداوند، «نسل زن» هستی،<br/>به دشمن ضربه زدی؛<br/>ذات انسان را پوشیدی،<br/>بهرِ پیروزی مُردی.<br/>چون خدای جسم پوشیده،<br/>جسم و خون دارا بودی؛<br/>با مرگْ ابلیس را کوبیدی،<br/>زورِ مرگ را شکستی.<br/>',NULL,65879,1);
INSERT INTO stanza VALUES('F191','2','تو «نسل ابراهیم» هستی،<br/>همان وعدۀ خدا،<br/>تا برْکت موعود او<br/>بر مردم شود اجرا.<br/>تو قبل از ابراهیم بودی،<br/>زیرا آن «هستم» هستی،<br/>لیک چون نسل او آمدی،<br/>«برّۀ» موعود شدی.<br/>',NULL,65880,2);
INSERT INTO stanza VALUES('F191','3','خداوند، «نسل داوودی،»<br/>بهرِ پادشاهی و<br/>جلال و بنای خدا،<br/>بر تخت نشانده شدی.<br/>تو از «اولاد داوودی»<br/>لیک تو را «خداوند» خوانْد،<br/>چون ریشه، چشمه اش هستی،<br/>تو خدای سرمدی.<br/>',NULL,65881,3);
INSERT INTO stanza VALUES('F191','4','«کودکی» زاده شد، تو را<br/>«خدای قدیر» خواندند؛<br/>آن «پسر» که داده شد را<br/>«پدر جاوید» خواندند.<br/>کل برَکاتِ خدا<br/>با ایمان به تو وصل است؛<br/>تو «آری» و «آمین» هستی،<br/>محتوی و انتها!<br/>',NULL,65882,4);
INSERT INTO stanza VALUES('F197','1','چه شاملِ تمام هستی<br/>عیسی، ما در توییم –<br/>سهمِ مقرر شده ای،<br/>تا همه چیز باشی.<br/>',NULL,65883,1);
INSERT INTO stanza VALUES('F197','2','تو حکمت خدا هستی،<br/>در تو نجات یافتیم؛<br/>تو تنها راه نجاتی،<br/>تنها عذرِ مایی.<br/>',NULL,65884,2);
INSERT INTO stanza VALUES('F197','3','تو صداقت ما هستی،<br/>بهرِ خواستِ خدا؛<br/>در تو، عادل محسوب شویم،<br/>در تو کاملیم ما.<br/>',NULL,65885,3);
INSERT INTO stanza VALUES('F197','4','تویی قدوسیتِ ما<br/>تا دگرگون شویم؛<br/>در تو تقدیس می شویم ما<br/>همشکلِ تو شویم.<br/>',NULL,65886,4);
INSERT INTO stanza VALUES('F197','5','تو هستی بازخریدِ ما؛<br/>مانندِ تو شویم؛<br/>تبدیل شود بدنِ ما؛<br/>آزادی ات سهیم.<br/>',NULL,65887,5);
INSERT INTO stanza VALUES('F197','6','خداوند، چون یادت کنیم،<br/>از تو لذت بَریم،<br/>بازگشتت را سرعت بخشیم،<br/>از تو دور نشویم.<br/>',NULL,65888,6);
INSERT INTO stanza VALUES('F197','7','چه پیش مزه ی شیرینی،<br/>طعمی بسیار عالی،<br/>لیک مشتاقِ با تو بودن،<br/>کمالِ خرسندی.<br/>',NULL,65889,7);
INSERT INTO stanza VALUES('F203','1','در آغوشِ پدر قبل از<br/>شروع شدنِ زمان،<br/>در جلالِ پدر بودى،<br/>تنها پسرِ خدا.<br/>تا پدر تو را به ما داد،<br/>در وجود همسان بودی،<br/>همۀ پُرىِ پدر<br/>در روحْ اعلام می کنی.<br/>',NULL,65890,1);
INSERT INTO stanza VALUES('F203','2','با مرگ و قيام، پسرِ<br/>اولِ خدا شدى؛<br/>حياتت به ما بخشيدى،<br/>تا خودت تكثير شوى،<br/>تولد تازه دادی،<br/>اولادِ خدا شديم؛<br/>واقعاً برادرانت،<br/>ما مثل خودت هستيم.<br/>',NULL,65891,2);
INSERT INTO stanza VALUES('F203','3','زمانى دانه اى بودى،<br/>افتادى زمين به مرگ،<br/>تا طىِ مرگ و قيامت<br/>در حيات تكثير شوى.<br/>در ذاتت مولود شده و<br/>دانه ها زياد شديم؛<br/>همچون يک نان مخلوط شدیم،<br/>پُری ات اعلام كنيم.<br/>',NULL,65892,3);
INSERT INTO stanza VALUES('F203','4','نسخۀ کاملت هستیم،<br/>بدنْ عزیز، عروس ات،<br/>ابراز تو و پُری ات،<br/>تا همیشه بمانی.<br/>ما ادامۀ تو هستيم،<br/>حيات و گسترش ات،<br/>رشدِ كامل و غنى، یک<br/>با تو سَرِ پرجلال.<br/>',NULL,65893,4);
INSERT INTO stanza VALUES('F206','1','آه  مسیح هست آن چشمه،<br/>آن چشمۀ حیات:<br/>نهرهایش را چشیدم<br/>که می دهد نجات.<br/>چون دریا گسترده و<br/>آکنده از رحمت؛<br/>فیض او بَس کافیست و<br/>طرح او با حکمت.<br/>',NULL,65894,1);
INSERT INTO stanza VALUES('F206','2','من از محبوبم هستم،<br/>محبوبم از من است؛<br/>او مجرمی ناچیز را<br/>به خانه اش آرَد!<br/>بر لطف او ایستادم،<br/>جایگاهی دیگر نیست<br/>در حضورش پنهانم<br/>و در دستش هستم.<br/>',NULL,65895,2);
INSERT INTO stanza VALUES('F206','3','عروس چشم بر لباس نیست،<br/>چشمش بر داماد است؛<br/>بر جلال چشم ندوزم،<br/>لیک بر شاهِ فیض ام.<br/>نه بر تاجی که بخشد،<br/>لیک بر دستش سوراخ؛<br/>کلِ جلال از برّه ست،<br/>او جایگاهِ من است!<br/>',NULL,65896,3);
INSERT INTO stanza VALUES('F208','1','اى عيسى، عيسى، نازنین!<br/>ببخش اگر میگم،<br/>در عشق، نام قدوست را<br/>هزاران بار در روز.<br/>',NULL,65897,1);
INSERT INTO stanza VALUES('F208','chorus','عيسى، خدا، با من بمان؛<br/>هرچه شود، در تو مانم؛<br/>لبخند تو پاداشِ من؛<br/>عاشق، عاشقتم!<br/>',NULL,65898,2);
INSERT INTO stanza VALUES('F208','2','عاشقتم، نمى دانم<br/>اين چطور حمل كنم؛<br/>عشقت چون آتشِ سوزان<br/>درونِ جان من.<br/>',NULL,65899,3);
INSERT INTO stanza VALUES('F208','3','تو بهرم همه چيز هستى؛<br/>ارزش و ثروتم؛<br/>خواهش قلب و قوتم،<br/>سلامتِ جانم.<br/>',NULL,65900,4);
INSERT INTO stanza VALUES('F208','4','بسوز، بسوز اى عشق در من،<br/>سخت بسوز روز و شب،<br/>تا کلِ عشقهاى زمين<br/>سوزد، تمام شود.<br/>',NULL,65901,5);
INSERT INTO stanza VALUES('F208','5','نور در ظلمت، شادى در غم،<br/>اى آسْمان بر زمين؛<br/>عيسى، عشقم، گنجينه ام،<br/>چه ارزشى دارى.<br/>',NULL,65902,6);
INSERT INTO stanza VALUES('F208','6','چه حَدى روى اين عشق است؟<br/>به کجا می روی؟<br/>خدایمان عزیزتر است<br/>امروز از روز پیش.<br/>',NULL,65903,7);
INSERT INTO stanza VALUES('F220','1','از نمادها بر میزِ تو،<br/>در شگفتیم، عیسی؛<br/>یک قطعه نان، جامِ شراب،<br/>طبق طرح خدا.<br/>',NULL,65904,1);
INSERT INTO stanza VALUES('F220','2','تصویری از نانِ حیات،<br/>غذای روحانی،<br/>که با مرگِ تو داده شد<br/>تا سهیم ات شویم.<br/>',NULL,65905,2);
INSERT INTO stanza VALUES('F220','3','سهم ما جامِ الهی ست،<br/>که از خونِ عیساست؛<br/>جامِ برْکت را برگیریم،<br/>خدا را کسب کنیم.<br/>',NULL,65906,3);
INSERT INTO stanza VALUES('F220','4','نان حیات، خوریم تو را،<br/>با خوردن از این نان؛<br/>پس در عشق یادت آوریم<br/>با تو تأمین شویم.<br/>',NULL,65907,4);
INSERT INTO stanza VALUES('F220','5','ما این برْکت را کسب کنیم<br/>با نوشیدن از جام؛<br/>با شادی یادت آوریم،<br/>تا ارتقاء یابیم.<br/>',NULL,65908,5);
INSERT INTO stanza VALUES('F220','6','با ضیافت بر نان و جام<br/>مرگت اعلام کنیم،<br/>که تو هستی حیات ما<br/>و همه چیزِ ما.<br/>',NULL,65909,6);
INSERT INTO stanza VALUES('F220','7','منتظر آن لحظه ایم،<br/>چون بطور کامل<br/>تو را و با تو جشن گیریم<br/>و تو را پَرستیم.<br/>',NULL,65910,7);
INSERT INTO stanza VALUES('F221','1','خداوند، شكر بهرِ میزَت،<br/>به همراهِ نان و جام؛<br/>از تو لذت بَریم اینجا<br/>چون جشنِ عشقِ خدا.<br/>مى خوريم آن نان، نشانِ<br/>بدنت براى ما؛<br/>می نوشیم از جام، نمادِ<br/>خون كه ریختی بهرِ ما.<br/>',NULL,65911,1);
INSERT INTO stanza VALUES('F221','chorus','هان، میزِ مقدس!<br/>نمادهای قدوس؛<br/>اهميت نشان اش،<br/>كاوش ناپذير!<br/>',NULL,65912,2);
INSERT INTO stanza VALUES('F221','2','با مرگت بازخريد كردى،<br/>تا حياتت را دهى،<br/>حتى خود را دادى به ما<br/>تا سهيم شویم تو را.<br/>با خوردن از اين نان و جام،<br/>مرگت را نشان دهيم؛<br/>خوردن و نوشيدن از تو،<br/>با عشق یادت آوریم.<br/>',NULL,65913,3);
INSERT INTO stanza VALUES('F221','3','با اين نان كه حاكى است از<br/>یک بدنِ عرفانی،<br/>شریک شویم با اعضايت<br/>در رابطه ای يكسان.<br/>با جامِ قدوسِ برْكت،<br/>جام كه حال تقديس كنيم،<br/>در خونت همه شریکیم<br/>با دگر ايمانداران.<br/>',NULL,65914,4);
INSERT INTO stanza VALUES('F221','4','سهمِ ابدیِ مایی،<br/>حال پیش مزۀ شیرین؛<br/>منتظرِ ملكوتت،<br/>و زود برگردانیم ات.<br/>چون آيى در ملكوتت،<br/>با همۀ پیروزان،<br/>از نو با تو جشن مى گيريم،<br/>عروسِ محبوبت ایم.<br/>',NULL,65915,5);
INSERT INTO stanza VALUES('F222','1','خداوند، شکر بهرِ این نان،<br/>الهی ست این نشان؛<br/>می بینیم اسرارِ طرحِ<br/>خدا را، ما در آن.<br/>',NULL,65916,1);
INSERT INTO stanza VALUES('F222','2','این نان نشانِ بدنت<br/>که دادی بهرِ ما،<br/>تا حیاتت شریک شویم،<br/>و از تو برخوردار.<br/>',NULL,65917,2);
INSERT INTO stanza VALUES('F222','3','بهرِ ما بدنت شکست<br/>تا اضافه کنی<br/>خودت را چون حیات، تا ما<br/>را همتایت کنی.<br/>',NULL,65918,3);
INSERT INTO stanza VALUES('F222','4','این نان نیز نشان دهد آن<br/>بدنت عرفانی،<br/>که ما اعضای آن هستیم<br/>زنده، با تو یکی.<br/>',NULL,65919,4);
INSERT INTO stanza VALUES('F222','5','ما دانه های بسیار، لیک<br/>یک قرصِ نان هستیم؛<br/>با خوردنِ تو، اینگونه<br/>تو را یاد می کنیم.<br/>',NULL,65920,5);
INSERT INTO stanza VALUES('F222','6','با هم از این نان برخوردار،<br/>تو راضی می کنی،<br/>ما در مشارکت تو را<br/>شهادت می دهیم.<br/>',NULL,65921,6);
INSERT INTO stanza VALUES('F223','1','روى ميز عشق تو،<br/>نان و جامْ گسترده است.<br/>با خوردن از اين نشان،<br/>با تو تغذیه شویم.<br/>چقدر شُكرت بهر جام،<br/>جامِ برْكتت، خدا،<br/>جامِ نجاتِ كامل،<br/>جامِ همه پُر کنی.<br/>',NULL,65922,1);
INSERT INTO stanza VALUES('F223','2','خون كه بهر ما ريختى،<br/>گناهانمان بخشد؛<br/>عهدى كه با ما بستى،<br/>برْكتِ تو را دهد.<br/>جامِ غضب نوشيدى،<br/>چشيدى مرگ بهرِ ما،<br/>جامِ برْكت خریدی،<br/>به عنوانِ سهمِ ما.<br/>',NULL,65923,2);
INSERT INTO stanza VALUES('F223','3','اینجا خدا را داریم،<br/>که در سقوط گم کردیم؛<br/>با ريختنِ خونِ تو،<br/>خدا همه چيزِ ماست.<br/>در اين سهمْ همه داريم -<br/>حيات و صلح، بازخرید؛<br/>طرح و خواستۀ خدا،<br/>در اين سهمْ ایمن کنیم.<br/>',NULL,65924,3);
INSERT INTO stanza VALUES('F223','4','اين سهمِ ابدى است،<br/>مقدسْ جامِ لبريز؛<br/>طعمِ الهى چشيم<br/>در جامِ طرحِ خدا.<br/>در عشق، اين جام مى نوشيم<br/>در يادت خداوندا؛<br/>پس در روحْ سهیم شويم<br/>اعمالت در جُلجُتا.<br/>',NULL,65925,4);
INSERT INTO stanza VALUES('F227','1','با نان و جام، خداوندا،<br/>آشکار می کنیم مرگت؛<br/>بهرِ ما چکار کرد عشقت،<br/>توسطِ رنجهایت.<br/>نان و جام که جدا هستند،<br/>مرگت را نشان دهند.<br/>شکر کنیم، در روح پرستیم،<br/>و بهرَت سرود خوانیم.<br/>',NULL,65926,1);
INSERT INTO stanza VALUES('F227','chorus','جامِ رنج نوشیدی،<br/>جامِ برْکت نوشیم؛<br/>بهرِ عشق در بازخریدت،<br/>ستایش کنیم!<br/>',NULL,65927,2);
INSERT INTO stanza VALUES('F227','2','در عشقْ خونَت ریختی، عیسی،<br/>آوردیمان به خدا،<br/>تا از خدا دور نباشیم،<br/>و صورتش را بینیم.<br/>عدالت و جلالش را<br/>کاملاً راضی کردی؛<br/>از شایستگیِ مرگت،<br/>حال ساکنیم با خدا.<br/>',NULL,65928,3);
INSERT INTO stanza VALUES('F227','3','با مرگت، آن پرده شکافت،<br/>و مکانِ قُدس باز شد،<br/>موانع شکسته شدند؛<br/>به تختِ فیض ات آییم،<br/>تا فیض و رحمت بیابیم،<br/>پس هر نیاز رفع شود،<br/>آبِ زنده را می نوشیم،<br/>پس خدا را می چشیم.<br/>',NULL,65929,4);
INSERT INTO stanza VALUES('F227','4','تو در فیضْ بازخرید کردی،<br/>تا کاهنانت شویم؛<br/>وظیفۀ قدوس دادی،<br/>با خدا سهیم شویم.<br/>چه برْکتی، چه رحمتی،<br/>از پِیِ مرگت آمد؛<br/>دائم یادت آوریم تا<br/>از نو با تو بنوشیم.<br/>',NULL,65930,5);
INSERT INTO stanza VALUES('F233','1','چه معجزه ایه، خدا،<br/>كه من در تو و تو در من،<br/>كه تو و من يكى هستيم؛<br/>چه راز فوق العاده ای!<br/>',NULL,65931,1);
INSERT INTO stanza VALUES('F233','2','بهرِ من بدنت دادى،<br/>تا دائم سهيم ات باشم؛<br/>و خونِ نفيس ات ريختى<br/>تا از گناهان رها شَم.<br/>',NULL,65932,2);
INSERT INTO stanza VALUES('F233','3','در قيام فُرم ات عوض شد،<br/>آمدى به عنوانِ روح؛<br/>و خواستى از تو پُر شوم<br/>تا غنایت از من شوند.<br/>',NULL,65933,3);
INSERT INTO stanza VALUES('F233','4','حال نمادها را بنگريم،<br/>از نو عشقِ تو را بينيم؛<br/>بهرِ قلبت شُكرت كنيم،<br/>چون زحمتهايت را بينيم.<br/>',NULL,65934,4);
INSERT INTO stanza VALUES('F233','5','نان بخوريم، جام بنوشيم،<br/>و به شيرينى ات آیيم؛<br/>در روحْ تو را دريافت كنيم،<br/>روحمان تغذيه كنى.<br/>',NULL,65935,5);
INSERT INTO stanza VALUES('F233','6','خواهیم بیشتر دریافت کنیم،<br/>در روحْ تو را سهیم شویم؛<br/>تا وجودمان پُر سازى،<br/>و در راستی یادت کنیم.<br/>',NULL,65936,6);
INSERT INTO stanza VALUES('F241','1','برْکت و حرمت و جلال بر تو،<br/>و جلال  بر تو،<br/>و جلال بر تو.<br/>برْکت و حرمت و جلال بر تو،<br/>حالا و همیشه.<br/>',NULL,65937,1);
INSERT INTO stanza VALUES('F241','chorus','حمد کن! حمد کن!<br/>نیایش کنیم همه<br/>حمد کن! حمد کن!<br/>حالا و همیشه.<br/>هللویاه!<br/>',NULL,65938,2);
INSERT INTO stanza VALUES('F241','2','برْکت و حرمت و جلال بر تو،<br/>و جلال  بر تو،<br/>و جلال بر تو.<br/>برْکت و حرمت و جلال بر تو،<br/>حالا و همیشه.<br/>',NULL,65939,3);
INSERT INTO stanza VALUES('F242','1','روحِ خدا امروزه<br/>همان روحِ عیسی است،<br/>خدا-انسان مُرد، برخاست،<br/>و صعود کرد در جلال.<br/>',NULL,65940,1);
INSERT INTO stanza VALUES('F242','2','از همین عیسی آمد<br/>آن روحِ عیسی به ما،<br/>تا واقعیت اش را<br/>تجربه نماییم ما.<br/>',NULL,65941,2);
INSERT INTO stanza VALUES('F242','3','آن روحِ عیسی دارد<br/>عنصرِ خدا، انسان؛<br/>در او جلال خدا،<br/>با هم حیاتِ انسان.<br/>',NULL,65942,3);
INSERT INTO stanza VALUES('F242','4','رنجِ حیات انسان،<br/>و تأثیرِ مرگ او،<br/>قیام و حکومتش،<br/>در نفَسِ روحِ اوست.<br/>',NULL,65943,4);
INSERT INTO stanza VALUES('F242','5','با کل این ترکیبات<br/>روحْ در ما حرْکت کند،<br/>و با مَسحِ کامل اش<br/>غنایش ثابت شود.<br/>',NULL,65944,5);
INSERT INTO stanza VALUES('F242','6','آن روحِ عیسی دارد<br/>هر چیز، بزرگ و کوچک؛<br/>او در ما کار کند تا<br/>خدا همه چیز شود.<br/>',NULL,65945,6);
INSERT INTO stanza VALUES('F244','1','آن روحِ قدوس هست امروز<br/>روحِ حیاتِ الهی،<br/>زنده کند، حیات دهد،<br/>بهرِ خدا، ترتیب دهد.<br/>',NULL,65946,1);
INSERT INTO stanza VALUES('F244','2','آبِ زنده سیراب کند،<br/>نهرِ حیات تامین کند؛<br/>مسیح، حیات الهی،<br/>قلبم را راضی می کند.<br/>',NULL,65947,2);
INSERT INTO stanza VALUES('F244','3','نورِ حیات روشن کند،<br/>او تاریکی را دور کند؛<br/>مسیح، آن نور الهی،<br/>در ما شب را روز می کند.<br/>',NULL,65948,3);
INSERT INTO stanza VALUES('F244','4','قوّتِ حیات با قدرت،<br/>درونِ ما نیرو بخشد؛<br/>مسیح، قوّتِ الهی،<br/>در درون عمل می کند.<br/>',NULL,65949,4);
INSERT INTO stanza VALUES('F244','5','قانون حیات، رهانَد،<br/>رها از قانون گناه؛<br/>و با آن ذات الهی،<br/>از درون، تنظیم می کند.<br/>',NULL,65950,5);
INSERT INTO stanza VALUES('F244','6','روحِ حیاتِ الهی،<br/>در ما بسیار میوه دهد؛<br/>صفات خدا در مسیح،<br/>در حیات، ابراز می کند.<br/>',NULL,65951,6);
INSERT INTO stanza VALUES('F244','7','آن روح دائم حیات بخشد،<br/>پس مرا دگرگون سازد؛<br/>اَجزای درونم را نو،<br/>همشکلِ مسیح می سازد.<br/>',NULL,65952,7);
INSERT INTO stanza VALUES('F244','8','پُر کن مرا از روح، خدا،<br/>روحِ حیاتِ الهی؛<br/>و کامل اشباع کن مرا<br/>تا با تو پُر شه حیاتم.<br/>',NULL,65953,8);
INSERT INTO stanza VALUES('F250','1','بجوش، چشمه، از آب؛<br/>حفر کن تو خداوند؛<br/>بردار سدها را تا<br/>جاری شوی از من.<br/>',NULL,65954,1);
INSERT INTO stanza VALUES('F250','2','از مسیح، آن صخره،<br/>آب حیات جاریست؛<br/>لیک در قلبم اکنون<br/>راهش بسته شده ست.<br/>',NULL,65955,2);
INSERT INTO stanza VALUES('F250','3','دور ریزم با دعا،<br/>خار و خاشاک ها را،<br/>تا روح رها شود،<br/>جریانِ نهر، آزاد.<br/>',NULL,65956,3);
INSERT INTO stanza VALUES('F250','4','نیاز نیست آن صخره،<br/>مسیح، باز شِکنَد؛<br/>لیک بهرِ حفر شدن،<br/>خود را بسپارم من.<br/>',NULL,65957,4);
INSERT INTO stanza VALUES('F250','5','نیازم عمیقاً<br/>هست از روح پُر شدن،<br/>تا آن آبِ حیات<br/>جاری شود از من.<br/>',NULL,65958,5);
INSERT INTO stanza VALUES('F250','6','حفر کن تا نماند<br/>سدّی در گذرگاه؛<br/>حفر کن، جاری شود<br/>آن پیامِ زنده.<br/>',NULL,65959,6);
INSERT INTO stanza VALUES('F250','7','بجوش، چشمه، از آب؛<br/>حفر کن تو خداوند؛<br/>بردار سدها را تا<br/>جاری شوی از من.<br/>',NULL,65960,7);
INSERT INTO stanza VALUES('F251','1','نهرهای آب های زنده<br/>جاری از تختِ خدا،<br/>نهرهای سرشار از برْکت،<br/>از عیسی آید تنها.<br/>',NULL,65961,1);
INSERT INTO stanza VALUES('F251','chorus','نهرهای آبِ زنده<br/>نهرِ حیات، رها،<br/>از تو جاریست، منجی ام،<br/>در من جاری کن آن را.<br/>',NULL,65962,2);
INSERT INTO stanza VALUES('F251','2','هر که تشنه است بیاید،<br/>اینجاست وفورِ نعمت؛<br/>آب شفاف و بلورین<br/>بیا بخر بی قیمت.<br/>',NULL,65963,3);
INSERT INTO stanza VALUES('F251','3','پاک کن، پاک کن مرا، منجی،<br/>چون مَجرایی کن مرا؛<br/>از خودم خالی، تو پُر کن،<br/>بر تو کنم اتکا.<br/>',NULL,65964,4);
INSERT INTO stanza VALUES('F251','4','سپس، ای خداوندْ عیسی،<br/>بجوشد در من نهرها؛<br/>سپس، دیگران دریابند<br/>پُریِ تامِ تو را.<br/>',NULL,65965,5);
INSERT INTO stanza VALUES('F251','5','حال تسلیمِ عیسی هستم،<br/>همه چیزِ من از اوست؛<br/>هر چیز و هر کجا، تنها<br/>برای خدمتِ اوست!<br/>',NULL,65966,6);
INSERT INTO stanza VALUES('F255','1','خدا، روحت بر من بِدَم،<br/>ياد دِه نفَس ات كِشم؛<br/>ياريم دِه بِآغوشت ریزم<br/>همه نفْس و گناهم.<br/>',NULL,65967,1);
INSERT INTO stanza VALUES('F255','chorus','بازدم كنم اندوهم را،<br/>و گناهم را؛<br/>نفَس، نفَس، نفَس كِشم،<br/>پُریِ تو را.<br/>',NULL,65968,2);
INSERT INTO stanza VALUES('F255','2','بازدم كنم زندگى ام،<br/>تا که با تو پُر شَوم؛<br/>رها كنم قوت و ضعف،<br/>حياتت نفَس كشم.<br/>',NULL,65969,3);
INSERT INTO stanza VALUES('F255','3','بازدم كنم ذاتِ گناه،<br/>همه را حمل كردی تو؛<br/>نفَس كِشم پُرى ات را،<br/>يافتم حياتم در تو.<br/>',NULL,65970,4);
INSERT INTO stanza VALUES('F255','4','بازدم کنم اندوهم را<br/>بر دلِ مهربانت؛<br/>نفَس کِشم شادی، رفاه،<br/>صلح و آرامش ات را.<br/>',NULL,65971,5);
INSERT INTO stanza VALUES('F255','5','بازدم كنم بيمارى ام،<br/>آن را نيز حمل كردى تو؛<br/>نفَس كشم شفايت را،<br/>هميشه مقرر، نو.<br/>',NULL,65972,6);
INSERT INTO stanza VALUES('F255','6','بازدم كنم آرزوهام<br/>در گوشِ شنوايت؛<br/>نفس كِشم جوابهايت،<br/>خاموش كند شک و ترس.<br/>',NULL,65973,7);
INSERT INTO stanza VALUES('F255','7','هر لحظه نفَس مى كِشم،<br/>كِشَم از تو حیاتم؛<br/>دم به دَم با تو زنده ام،<br/>روحت را در من بِدَم.<br/>',NULL,65974,8);
INSERT INTO stanza VALUES('F260','1','بارش های برْکت آید:<br/>عشق وعده داده این را؛<br/>فصل های تازگی آید،<br/>از سوی منجیِ ما.<br/>',NULL,65975,1);
INSERT INTO stanza VALUES('F260','chorus','بارشِ برْکت،<br/>بارشِ برْکت خواهیم؛<br/>قطره های رحمت ریزد،<br/>لیک بارش را می جوییم.<br/>',NULL,65976,2);
INSERT INTO stanza VALUES('F260','2','بارش های برْکت آید –<br/>احیای گران قیمت؛<br/>بر تپه ها و دره ها،<br/>ریزد باران برْکت.<br/>',NULL,65977,3);
INSERT INTO stanza VALUES('F260','3','بارش های برْکت آید؛<br/>خدایا، آن را بفرست!<br/>اکنون ما را تازه گردان؛<br/>مطابق کلامت.<br/>',NULL,65978,4);
INSERT INTO stanza VALUES('F260','4','بارش های برْکت آید؛<br/>باشد امروز بیاید،<br/>چون به خدا اقرار کنیم،<br/>چون عیسی را بخوانیم!<br/>',NULL,65979,5);
INSERT INTO stanza VALUES('F260','5','بارش های برْکت آید،<br/>گر تسلیم، تکیه کنیم؛<br/>فصل های تازگی آید<br/>گر به خدا راه دهیم.<br/>',NULL,65980,6);
INSERT INTO stanza VALUES('F264','1','عیسی، عشقِ پیروزمندت<br/>در جانم ریخته شد؛<br/>دل منحرف نشود، در<br/>خدا ریشه گیرد،<br/>در او ریشه گیرد.<br/>',NULL,65981,1);
INSERT INTO stanza VALUES('F264','2','در من، آتشِ مقدس<br/>باشد حال بتابد؛<br/>ناخالصی را سوزانَد،<br/>کوه را جاری کند،<br/>کوه را جاری کند.<br/>',NULL,65982,2);
INSERT INTO stanza VALUES('F264','3','او در پنتیکاست جاری شد،<br/>گناهانم سوزانْد؛<br/>بخوانم روحِ قدوس را؛<br/>روحِ سوزان، بیا،<br/>روحِ سوزان، بیا.<br/>',NULL,65983,3);
INSERT INTO stanza VALUES('F264','4','آتشِ جلادهنده<br/>جانم را روشن کن؛<br/>حیاتت توزیع کن در من،<br/>همه را تقدیس کن،<br/>همه را تقدیس کن.<br/>',NULL,65984,4);
INSERT INTO stanza VALUES('F264','5','جانم از لغزش رها کن،<br/>تا محکم بمانَد،<br/>چون مسیح هست همه چیزم،<br/>عشق است کلِ قلبم،<br/>عشق است کلِ قلبم.<br/>',NULL,65985,5);
INSERT INTO stanza VALUES('F266','1','مسحِ الهی ساکن در من،<br/>همه چیز یادم دهد؛<br/>که در خداوند زندگی کنم،<br/>و حضورش را آرَد.<br/>',NULL,65986,1);
INSERT INTO stanza VALUES('F266','chorus','آن مسحْ در روحم ساکن است،<br/>آه آن مسحْ ساکن است و یادم می دهد؛<br/>آن مسحْ درونِ روحم ساکن است<br/>و دائم یادم می دهد.<br/>',NULL,65987,2);
INSERT INTO stanza VALUES('F266','2','آن مسح همان حرْکتِ روح است<br/>پُر فیض چون مرهمْ خالص؛<br/>بر اساس پاشیدنِ خون است،<br/>و همیشه ماندگار.<br/>',NULL,65988,3);
INSERT INTO stanza VALUES('F266','3','مسح ام کند با ذاتِ خدا،<br/>بهرِ شناختِ خدا،<br/>که دارای عنصرِ او باشم<br/>تا اشباع کند مرا.<br/>',NULL,65989,4);
INSERT INTO stanza VALUES('F266','4','من با این مسحِ درونی، در<br/>مشارکت پیش رَوَم؛<br/>در نورِ خدا راه می روم،<br/>عشقِ فیض ثابت کنم.<br/>',NULL,65990,5);
INSERT INTO stanza VALUES('F267','1','از روحِ فيض بخش ات پُر كن،<br/>روحِ مشتاقم حالا؛<br/>پُر از حضورِ قدوست،<br/>خدا جان، پُر کن مرا!<br/>',NULL,65991,1);
INSERT INTO stanza VALUES('F267','chorus','پُر كن، پُر كن مرا!<br/>پُر كن از روحَت مرا!<br/>كامل از خودم خالى كن،<br/>پُر كن از روحَت مرا!<br/>',NULL,65992,2);
INSERT INTO stanza VALUES('F267','2','با روحت پُرم مى كنى،<br/>نتوانم گفت چطور؛<br/>اما محتاجتم بسيار؛<br/>خدا جان، پُر کن مرا!<br/>',NULL,65993,3);
INSERT INTO stanza VALUES('F267','3','من ضعيف و پُر از ضعفم؛<br/>خَم بر پاىِ قدوست؛<br/>از روحِ پُر برکتِ خود<br/>با قوت پُر كن مرا.<br/>',NULL,65994,4);
INSERT INTO stanza VALUES('F267','4','پاک کن، تسكين و نجات ده<br/>روحِ شكسته ام را؛<br/>آرام بخش و منجى هستى،<br/>چه شيرين پُر می كنى!<br/>',NULL,65995,5);
INSERT INTO stanza VALUES('F268','1','ستایمَت، منجیِ من،<br/>که مرا یافت عشقِ تو؛<br/>نجات دادی، پاک، پُر کردی،<br/>تا باشم مَجرای تو.<br/>',NULL,65996,1);
INSERT INTO stanza VALUES('F268','chorus','مَجرا تنها، سَرورِ ما،<br/>لیک با فیضِ شگرف ات،<br/>جاری از ما، تا تو از ما<br/>بهره بَری هر ساعت.<br/>',NULL,65997,2);
INSERT INTO stanza VALUES('F268','2','فقط مَجرا، پُر از برکت<br/>بهرِ قلوبِ تشنه؛<br/>بهرِ بشارتِ نجات،<br/>پیامِ محبته.<br/>',NULL,65998,3);
INSERT INTO stanza VALUES('F268','3','خالی تا با تو پُر شوم،<br/>ظرفی پاک در دستهایت؛<br/>بی قوت لیک با قوتی<br/>که تو دهی با حکم ات.<br/>',NULL,65999,4);
INSERT INTO stanza VALUES('F268','4','شاهدِ فیضِ نجاتت،<br/>آزاد از نفْس و گناه؛<br/>بهرِ خود مرا خریدی،<br/>در کمالِ خود بیا.<br/>',NULL,66000,5);
INSERT INTO stanza VALUES('F268','5','خدایا با روحت پُر کن<br/>قلوبِ تسلیم ات را؛<br/>تا نهرهای آبِ زنده<br/>آید از درون ما.<br/>',NULL,66001,6);
INSERT INTO stanza VALUES('F271','1','از روح، متولد در روح،<br/>چون پسران خدا،<br/>دارای روحِ قدوسیم،<br/>آن که ساکن است در ما.<br/>لیک بیش محتاجیم، تا با تو<br/>پُر شویم، خداوندا؛<br/>ما را با روحِ خود پُر کن،<br/>وافر حیات دِه به ما.<br/>',NULL,66002,1);
INSERT INTO stanza VALUES('F271','2','خداوند، روح تو در ماست،<br/>لیک از حیات است روحت،<br/>تا در غنای پُری ات<br/>در او باشیم سهیم ات.<br/>لیک هنوز ملزم هستیم به<br/>روح چون قدرت از بالا،<br/>تا بهرِ کار و خدمتت<br/>مجهز بشویم ما.<br/>',NULL,66003,2);
INSERT INTO stanza VALUES('F271','3','ما را تعمید دِه با روحت،<br/>با قدرتت بپوشان؛<br/>پس با «رَدای» قدرتت<br/>نبرد را بجنگیم ما.<br/>زبانۀ آتش ببخش،<br/>چون تندباد وَزَد بر ما،<br/>تا شاهدانِ مسح شده،<br/>قلبت راضی کنیم ما.<br/>',NULL,66004,3);
INSERT INTO stanza VALUES('F271','4','با نیروی روح، عطایا<br/>را باید سهیم شویم،<br/>چون اعضا عملکرد داریم،<br/>حامل شهادتیم.<br/>با برون ریزشِ روحت،<br/>آنچه نیاز است ببخش،<br/>تا بنای بدنِ تو<br/>پیش رود با برکتت.<br/>',NULL,66005,4);
INSERT INTO stanza VALUES('F271','5','بهرِ جلال و ملکوت،<br/>بشنو دادِ بدن را!<br/>حال قصدت را اجرا کن و<br/>رفع کن گشنگیْمان را.<br/>باشد از تو برخوردار شیم<br/>و روح را بکار بَریم؛<br/>پُریِ درون و برون،<br/>عطایا سهیم شویم.<br/>',NULL,66006,5);
INSERT INTO stanza VALUES('F273','1','خداوند، آزاد آییم نزد تو،<br/>طالبِ قدرتت حالا؛<br/>بهرِ ملکوتت، قدرت گیریم،<br/>بهرِ جنگ نشستیم در سما.<br/>',NULL,66007,1);
INSERT INTO stanza VALUES('F273','chorus','قدرت! قدرت! بپوشان با قدرت!<br/>قوّی با قدرتت از بالا!<br/>قدرت! قدرت! بپوشان با قدرت!<br/>خواهیم، چون بدنَت، بی پروا!<br/>',NULL,66008,2);
INSERT INTO stanza VALUES('F273','2','خداوند، بی شک بر تو بنگریم،<br/>خواهیم بارشِ الهی،<br/>بهرِ بدنَت، سهیم در بارِش،<br/>تا شایانِ کارِ تو باشیم.<br/>',NULL,66009,3);
INSERT INTO stanza VALUES('F273','chorus','بارش! بارش! ریزان بر ما بارش!<br/>بریز بارش ات از بالا!<br/>بارش! بارش! ریزان بر ما بارش!<br/>خواهیم، چون بدنَت، بی پروا!<br/>',NULL,66010,4);
INSERT INTO stanza VALUES('F273','3','خداوند، قاطع منتظرِ تو،<br/>خواهیم آتشِ الهی.<br/>بهرِ انجیل ات، سهیم در آتش،<br/>تا قلبِ مردم را صاف کنی.<br/>',NULL,66011,5);
INSERT INTO stanza VALUES('F273','chorus','آتش! آتش! زبانۀ آتش!<br/>اعلامِ پیامت از بالا!<br/>آتش! آتش! زبانۀ آتش!<br/>خواهیم، چون بدنَت، بی پروا!<br/>',NULL,66012,6);
INSERT INTO stanza VALUES('F278','1','روحِ حیات امروز هست درونِ ما،<br/>که چون آب است بهرِ تشنگیِ ما؛<br/>از او می نوشیم و از او پر شویم،<br/>تا او چون یک نهر جاری شود از ما.<br/>',NULL,66013,1);
INSERT INTO stanza VALUES('F278','2','روحِ قدرت امروز می آید بر ما،<br/>که چون لباس است بهرِ پوششِ ما؛<br/>در او تعمید شیم و با او ملبس،<br/>مجهز با قدرت بهرِ خدمت، ما.<br/>',NULL,66014,2);
INSERT INTO stanza VALUES('F278','3','روحِ حیات چون نفَسِ پرجلال،<br/>که دمیده شده به درون ما؛<br/>روحِ قدرت در باد نمایان شده،<br/>با قدرت از بالا می وزد بر ما.<br/>',NULL,66015,3);
INSERT INTO stanza VALUES('F278','4','عیسی قیام کرد، بر شاگردان دمید،<br/>پس روحِ حیات را به آنها بخشید؛<br/>خداوند در صعود، روزِ پنتیکاست،<br/>بر شاگردانش ریخت روحِ قدرت را.<br/>',NULL,66016,4);
INSERT INTO stanza VALUES('F278','5','روحِ حیات، آن حیاتْ درونِ ماست،<br/>روحِ قدرت برای این حیات است؛<br/>چون وزشِ بادْ هوای نفَس است،<br/>پس روحِ قدرتْ میراثِ حیات است.<br/>',NULL,66017,5);
INSERT INTO stanza VALUES('F278','6','این دو روحْ دور از هم و جدا نیستند،<br/>لیک یک روح با دو عملکرد می باشد،<br/>ملبس با خدا و پُر در درون،<br/>تا ما کامل با او آمیخته شویم.<br/>',NULL,66018,6);
INSERT INTO stanza VALUES('F278','7','عیسی، با روحِ حیات پر کن ما را،<br/>تا در حیاتت چون تو رشد کنیم ما؛<br/>و با روحِ قدرت بپوشان ما را<br/>تا خواستِ تو در خدمت شود اجرا.<br/>',NULL,66019,7);
INSERT INTO stanza VALUES('F279','1','نخست خون، و سپس مرهم،<br/>مَسح از پی شستشوست؛<br/>گر از جُلجُتا نگذریم،<br/>نرسیم به پنتیکاست.<br/>گر با خونْ پاک نشده ایم،<br/>قدرتِ روح نشناسیم،<br/>گر شهادتِ مسیح ایم،<br/>پس بر صلیب بمانیم.<br/>',NULL,66020,1);
INSERT INTO stanza VALUES('F279','chorus','با صلیب، ای خداوند،<br/>نفْسم را از بین ببر؛<br/>هر بهایی پَردازم،<br/>تا مَسح را دریافت کنم.<br/>',NULL,66021,2);
INSERT INTO stanza VALUES('F279','2','مسیح آن صخره، شکست تا<br/>آبِ حیّ جاری شود؛<br/>بدونِ مرگ، کمالِ روح<br/>در ما ساکن نشود.<br/>گر در مرگِ مسیح مانیم،<br/>حاضر به کاسته شدن،<br/>با قدرت مُلبس شویم<br/>و دنیا مطیع شود.<br/>',NULL,66022,3);
INSERT INTO stanza VALUES('F279','3','نخست مذبح، سپس آتش،<br/>سود از کاستن بیاید؛<br/>گر خود را اهدا نکنیم،<br/>هرگز به تخت نرسیم.<br/>گر کل را قربانی کنیم،<br/>به خدا تسلیم شویم،<br/>به او متعهد شده،<br/>قدرتش آشکار سازیم.<br/>',NULL,66023,4);
INSERT INTO stanza VALUES('F279','4','نخست ظروف باید باشند<br/>تا با روغن پُر شوند؛<br/>گودالها در دره حفر کن<br/>تا از باران پُر شوند.<br/>نخست از اُردُن بگذریم<br/>تا از بالا مَسح شویم؛<br/>نخست در مرگ تعمید شویم،<br/>تا از روح پوشش گیریم.<br/>',NULL,66024,5);
INSERT INTO stanza VALUES('F279','5','وقتی ما محصول را بینیم<br/>آن محصولِ رسیده،<br/>دانیم که بسیار دانه ها<br/>بر خاک افتاده، مُرده.<br/>گر میوۀ حیات خواهیم،<br/>باید از مرگ بگذریم؛<br/>گر با مسیح دفن نشدیم،<br/>روح را نَفَس نکشیم.<br/>',NULL,66025,6);
INSERT INTO stanza VALUES('F279','6','پس کمکم کن، خداوند،<br/>راهِ باریک را رَوَم؛<br/>فروتن و حاضر باشم،<br/>تو را اطاعت کنم.<br/>دعایم بهرِ قدرت نیست،<br/>نیازم مرگِ بیش است؛<br/>کل مفهومِ صلیب را<br/>ای خدا، در من کاربَر.<br/>',NULL,66026,7);
INSERT INTO stanza VALUES('F280','1','عیسی، پاک کن با خونَت،<br/>گناهانِ مرا،<br/>تا با روحِ قدوست<br/>مَسح فرمایی مرا.<br/>خدمت ام، خداوندا،<br/>ناقص است و ضعیف؛<br/>پُرم کن با روحت تا<br/>ابراز کنم تو را.<br/>',NULL,66027,1);
INSERT INTO stanza VALUES('F280','chorus','آه، از خودم بِرَهان<br/>از همۀ پستی ها؛<br/>از این پس تا همیشه<br/>پُر با خودت تنها.<br/>',NULL,66028,2);
INSERT INTO stanza VALUES('F280','2','آه، قلبم خشک است، خدا،<br/>بهرِ تو می تپد؛<br/>پُر شدن با روحت را<br/>شَدید می طلبد.<br/>درونِ تو، ای صخره<br/>کامل پنهان شوم؛<br/>بِریزان آبِ زنده،<br/>تا راضی بشوم.<br/>',NULL,66029,3);
INSERT INTO stanza VALUES('F280','3','قلبم سرد بوده، خدا<br/>کُنْد در اطاعتت؛<br/>با روحت پُر کن مرا،<br/>تا نباشم سرسخت.<br/>مانم بر قربانگاهت<br/>و تکان نخورم؛<br/>باشد آید شعله ات<br/>و از بِین ببرد.<br/>',NULL,66030,4);
INSERT INTO stanza VALUES('F280','4','آه، باشد صلیبت در<br/>من عمیق تر شود،<br/>تا در من زیاد شوی،<br/>من خاکستر شوم.<br/>آه، پُرم کن با روحت،<br/>هر روز بیشتر از پیش،<br/>باشد آبِ زنده ات<br/>از من جاری شود.<br/>',NULL,66031,5);
INSERT INTO stanza VALUES('F296','1','آیا می شد علاقه مند<br/>شوَم به خونِ منجی، من؟<br/>مُرد بهرِ من، کی باعث شد؟<br/>او را تا مرگ تعقیب کردم.<br/>عشقِ شگرف! چطور شد که<br/>برایم مُردی، خدایم؟<br/>عشقِ شگرف! چطور شد که<br/>برایم مُردی، خدایم؟<br/>',NULL,66032,1);
INSERT INTO stanza VALUES('F296','2','عجب رازیست! نامیرا مُرد!<br/>کی طرح عجیبش داند؟<br/>فرشته بیهوده سعی کرد<br/>عمقِ عشقش را فاش کند!<br/>چه رحمتی ست! بپَرستید،<br/>تا ملائک جویا نَشَند.<br/>چه رحمتی ست! بپَرستید،<br/>تا ملائک جویا نَشَند.<br/>',NULL,66033,2);
INSERT INTO stanza VALUES('F296','3','ترک کرد تختِ سلطنت را،<br/>با فیضِ خود بس بیکران؛<br/>خالی از هر چیز، غیر از عشق،<br/>خونش را ریخت بهرِ انسان:<br/>چه رحمتی ست، عظیم، رها،<br/>چون، خدایم، آن یافت مرا.<br/>چه رحمتی ست، عظیم، رها،<br/>چون، خدایم، آن یافت مرا.<br/>',NULL,66034,3);
INSERT INTO stanza VALUES('F296','4','مدتی روحم زنجیر بود<br/>در بندِ گناه و ظلمت؛<br/>نورِ حیات بخشید چشمت،<br/>منْ بیدار، دخمه پر نور گشت؛<br/>بندها گسست، آزاد دلم،<br/>برخاستم، از پی ات رَوَم.<br/>بندها گسست، آزاد دلم،<br/>برخاستم، از پی ات رَوَم.<br/>',NULL,66035,4);
INSERT INTO stanza VALUES('F296','5','حال هیچ محکومیتی نیست<br/>زیرا عیسی مال من است!<br/>زنده در او، سَرِ زنده،<br/>لباسم عدلِ الهی ست،<br/>به تختِ جاوْدان می روم،<br/>با مسیح تاج را می گیرم.<br/>به تختِ جاوْدان می روم،<br/>با مسیح تاج را می گیرم.<br/>',NULL,66036,5);
INSERT INTO stanza VALUES('F298','1','امیدم هیچ چیز دگر نیست<br/>مگر مسیح، صداقتم،<br/>ظاهر را اعتمادی نیست،<br/>تکیه گاهم نامِ عیساست.<br/>',NULL,66037,1);
INSERT INTO stanza VALUES('F298','chorus','ایستم بر مسیح آن صخره؛<br/>باقی دگر شن و ماسه،<br/>باقی دگر شن و ماسه.<br/>',NULL,66038,2);
INSERT INTO stanza VALUES('F298','2','چون ظلمت پنهانش کند،<br/>بر فیض او تکیه کنم؛<br/>در هر طوفانِ شدیدی،<br/>در او محکم لنگر زدم.<br/>',NULL,66039,3);
INSERT INTO stanza VALUES('F298','3','قولِ او، عهد و خونِ او،<br/>در طوفان تأمین ام کند؛<br/>چون جانم ناامید شود،<br/>پس او همه امیدم است.<br/>',NULL,66040,4);
INSERT INTO stanza VALUES('F298','4','با ندای شیپور آید،<br/>باشد در او پیدا شوم؛<br/>در او، تنها صداقتم،<br/>بی عیب در حضورش ایستم.<br/>',NULL,66041,5);
INSERT INTO stanza VALUES('F308','1','تضمین برْکت، عیساىِ من؛<br/>چشیدم جلالِ الهی اش!<br/>وارثِ نجات، مِلکِ خدا،<br/>مولودِ روحَش، شسته خونَش.<br/>',NULL,66042,1);
INSERT INTO stanza VALUES('F308','chorus','این داستانمه، این سُرودم،<br/>ستایش کنم منجی ام را.<br/>این داستانمه، این سُرودم،<br/>ستایش کنم منجی ام را.<br/>',NULL,66043,2);
INSERT INTO stanza VALUES('F308','2','تسلیمِ کامل، در شادمانی،<br/>بینشِ عروج در نظر دارم؛<br/>فرشتگانش نزول کنند،<br/>پیامِ عشق و رحمت آرند.<br/>',NULL,66044,3);
INSERT INTO stanza VALUES('F308','3','تسلیمِ کامل، در آرامش،<br/>در منجی ام شادم و مسرورم؛<br/>هشيار و صبور، بالا بينم،<br/>پر از نیکی اش، غرق در عشقش.<br/>',NULL,66045,4);
INSERT INTO stanza VALUES('F309','1','چه تغییر شگرفی یافته زندگیم<br/>چون عیسی آمد به قلبم!<br/>در جانم دارم نوری را که می گشتم،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66046,1);
INSERT INTO stanza VALUES('F309','chorus','چون عیسی آمد به قلبم!<br/>چون عیسی آمد به قلبم!<br/>سِیلِ شادی در جانم چون موج می غلتد،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66047,2);
INSERT INTO stanza VALUES('F309','2','سرگردانی، انحراف پایان گرفته،<br/>چون عیسی آمد به قلبم!<br/>و گناهانِ بسیارم شسته شده،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66048,3);
INSERT INTO stanza VALUES('F309','3','گشته امیدم مطمئن و استوار،<br/>چون عیسی آمد به قلبم!<br/>ابرهای شَک راه مرا نکنند تار،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66049,4);
INSERT INTO stanza VALUES('F309','4','حال در درۀ مرگ هست نوری برایم،<br/>چون عیسی آمد به قلبم!<br/>و دروازهای آن شهر را می بینم،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66050,5);
INSERT INTO stanza VALUES('F309','5','در آن شهر مسکن خواهم گزید، می دانم،<br/>چون عیسی آمد به قلبم!<br/>و خوشحالم، خیلی خوشحال چون پیش رَوَم،<br/>چون عیسی آمد به قلبم!<br/>',NULL,66051,6);
INSERT INTO stanza VALUES('F310','1','با گناه در غُل و زنجير بودم،<br/>بيهوده تقلا مى كردم؛<br/>اما چه پر جلال آزاد شدم،<br/>چون عيسى زنجيرهام را شكست.<br/>',NULL,66052,1);
INSERT INTO stanza VALUES('F310','chorus','آزادىِ پر جلال و شگرف،<br/>نمانم در زنجير گناه!<br/>عیسی، پر جلال آزاد کننده،<br/>حال و هميشه مال من است.<br/>',NULL,66053,2);
INSERT INTO stanza VALUES('F310','2','آزاد از علايق جسمانى،<br/>آزاد از رشک، كينه و نزاع؛<br/>آزاد از جاه طلبىِ دنيا،<br/>آزاد از هر چه غمگين می کرد.<br/>',NULL,66054,3);
INSERT INTO stanza VALUES('F310','3','آزاد از تكبر و حماقت،<br/>آزاد از عشق و برقِ طلا؛<br/>آزاد از خوىِ شرّ و عصبى،<br/>آزادىِ پر جلال، با وجد.<br/>',NULL,66055,4);
INSERT INTO stanza VALUES('F310','4','آزاد از ترس با همه عذابش،<br/>آزاد از غم با همه رنجهاش،<br/>آزاد در مسيح، منجىِ خوبم،<br/>آن كه زنجيرهايم را شكست.<br/>',NULL,66056,5);
INSERT INTO stanza VALUES('F312','1','فيض! صدايى گيراست.<br/>به گوشْ خوش آهنگ است؛<br/>آسِمان طنين اندازد،<br/>و زمين شنوَد.<br/>',NULL,66057,1);
INSERT INTO stanza VALUES('F312','chorus','فيضْ بسیار كافى ست!<br/>بى قدرت هرگز!<br/>درونم مسيح زِندَست،<br/>و هميشه پايدار.<br/>',NULL,66058,2);
INSERT INTO stanza VALUES('F312','2','فيض نامم را نوشت<br/>در كتاب حيات؛<br/>فيض به آن برّه داد مرا،<br/>كه غمهام را برداشت.<br/>',NULL,66059,3);
INSERT INTO stanza VALUES('F312','3','فيض یاد داد مرا تا<br/>چون مسافر باشم؛<br/>و تأمين شَوم هر لحظه<br/>با تكيه بر خدا.<br/>',NULL,66060,4);
INSERT INTO stanza VALUES('F312','4','فيض دعا يادم داد<br/>و چشمانم پُر كرد؛<br/>فيض نگهم داشت تا حالا،<br/>رهايم نكند.<br/>',NULL,66061,5);
INSERT INTO stanza VALUES('F312','5','فيض پاداشِ کارهاست<br/>سرتاسرِ زمان؛<br/>سنگِ سَر را می گذارد،<br/>و ستايش از اوست.<br/>',NULL,66062,6);
INSERT INTO stanza VALUES('F312','6','بگذار الهامِ فيض<br/>قوت بخشد قلبم؛<br/>عمیقاً مشتاقت باشم،<br/>از تو باد روزهایم.<br/>',NULL,66063,7);
INSERT INTO stanza VALUES('F313','1','فیضِ شگرف! صداش شیرین،<br/>که داده نجاتم!<br/>گم بودم لیک پیدا شدم،<br/>کور بودم، حال بینم.<br/>',NULL,66064,1);
INSERT INTO stanza VALUES('F313','2','فیض بود که قلبم تعلیم داد،<br/>فیض ترسم خاموش کرد؛<br/>چه پر ارزشْ فیض ظاهر شد،<br/>چون ایمان آوردم.<br/>',NULL,66065,2);
INSERT INTO stanza VALUES('F313','3','خدا قولِ نیک داد به من،<br/>کلامش امیدم؛<br/>سپرِ من و سهمِ من،<br/>تا ابدالاباد!<br/>',NULL,66066,3);
INSERT INTO stanza VALUES('F313','4','ده هزار سال گذر کند،<br/>چون خورشیدِ تابان،<br/>کمتر نشد ستایش ها<br/>از آغازِ ایمان.<br/>',NULL,66067,4);
INSERT INTO stanza VALUES('F319','1','بیا سرچشمۀ برْکت،<br/>قلبم خوانَد از فیض ات؛<br/>بی پایان است نهرِ رحمت،<br/>واجب است ستایش ات.<br/>عیسی جُست در غربت مرا،<br/>پَرت از حضورِ خدا؛<br/>از خطر داد نجات مرا،<br/>از راهِ خونِ پاکش.<br/>',NULL,66068,1);
INSERT INTO stanza VALUES('F319','2','آه، به فیضْ مدیونم بسیار،<br/>روزانه ناگزیرم!<br/>خدا بگذار فیضْ چون زنجیر،<br/>به تو بکند وصلم.<br/>یادم ده در تو شاد باشم،<br/>تا ثابت شود فیض ات،<br/>چون از عشق تو سَرایم<br/>که تغییرناپذیر است.<br/>',NULL,66069,2);
INSERT INTO stanza VALUES('F319','3','چه نزدیک هستم به خطا؛<br/>خطای دوری از تو:<br/>بگیر و مُهر کن قلبم را<br/>با روحِ والای تو.<br/>از خطر و شر رها، با<br/>بهای خونِ منجی،<br/>در این دنیا غریبه ام،<br/>چون وارثِ خدایم.<br/>',NULL,66070,3);
INSERT INTO stanza VALUES('F322','1','سالهای بسیار چشمه ای می جُستم،<br/>که هرگز خشک نشود؛<br/>هرآنچه دنیا داشت نخورد به دردم،<br/>هیچی راضی نمی کرد.<br/>',NULL,66071,1);
INSERT INTO stanza VALUES('F322','chorus','نوشم از چشمه ای که خشک نشود،<br/>نوشم از سرچشمۀ حیات، من؛<br/>یابم وجد و شادی<br/>به حد زیادی<br/>من می نوشم از چشمۀ حیات.<br/>',NULL,66072,2);
INSERT INTO stanza VALUES('F322','2','در صحرای گناه پَرسه نزنم،<br/>یافتم چشمه ای زنده،<br/>و حالا لبریز است با شادی جامم،<br/>عیسی، شاه، خدایمه.<br/>',NULL,66073,3);
INSERT INTO stanza VALUES('F322','3','اینجاست قناعت در گذرِ روزها<br/>اینجاست صلح و آرامش؛<br/>اینجاست دلگرمی در طیِ لحظه ها،<br/>قلبم پر از برْکتش.<br/>',NULL,66074,4);
INSERT INTO stanza VALUES('F322','4','اینجا همیشه ذخیره ای یابم،<br/>ذخیره ای بی پایان؛<br/>به این چشمۀ شفا پرواز کنم<br/>و فرو رَوم در آن.<br/>',NULL,66075,5);
INSERT INTO stanza VALUES('F330','1','ایمانم جایی محکم است،<br/>نه در طرح و آیین؛<br/>اعتمادم بر آن حیّ است،<br/>زخمش دعویِ من.<br/>',NULL,66076,1);
INSERT INTO stanza VALUES('F330','chorus','دلیلی دیگر نخواهم،<br/>هیچ عذری ندارم؛<br/>چون مرگ عیسی بس کافیست،<br/>که او مُرد برایم.<br/>',NULL,66077,2);
INSERT INTO stanza VALUES('F330','2','این کافیست که عیسی منجی ست،<br/>اتمامِ شَک و ترس؛<br/>گناهکارم، نزدش آیم،<br/>بیرونم نکند.<br/>',NULL,66078,3);
INSERT INTO stanza VALUES('F330','3','قلبم بر روی کلام است،<br/>نوشتارِ خدا،<br/>نجاتم در نام منجی ست،<br/>از طریق خونش.<br/>',NULL,66079,4);
INSERT INTO stanza VALUES('F330','4','شفای درد بیماران،<br/>نجاتِ مفقودان؛<br/>بهرم ریخت خون نفیس اش،<br/>بهرِ من داد جانش.<br/>',NULL,66080,5);
INSERT INTO stanza VALUES('F333','1','ندانم چرا فیض اش را<br/>خدا بر من  فاش کرد،<br/>یا چرا منِ ناچیز را<br/>مسیح بازخرید کرد.<br/>',NULL,66081,1);
INSERT INTO stanza VALUES('F333','chorus','لیک «دانم به که ایمان دارم<br/>و یقین دارم که او قادر است<br/>حفظ کند امانت ام را<br/>بهرِ خود تا به آن روز.»<br/>',NULL,66082,2);
INSERT INTO stanza VALUES('F333','2','ندانم چطور ایمان داد<br/>برای نجاتم،<br/>یا چطور ایمان در کلام<br/>صلح آورْد به قلبم.<br/>',NULL,66083,3);
INSERT INTO stanza VALUES('F333','3','ندانم چگونه آن روح<br/>توبه می آورد،<br/>در عیسی از راه  کلام<br/>ایمان می آورد.<br/>',NULL,66084,4);
INSERT INTO stanza VALUES('F333','4','ندانم چه از بد یا خوب<br/>در شرایط باشد،<br/>که قبل از دیدارم با او<br/>راه سخت یا سهل باشد.<br/>',NULL,66085,5);
INSERT INTO stanza VALUES('F333','5','ندانم او کِی می آید،<br/>در شب یا وقت ظهر،<br/>یا با او در دره همراه،<br/>یا «در هوا دیدار.»<br/>',NULL,66086,6);
INSERT INTO stanza VALUES('F348','1','چون آزاد کرد جانم مسیح،<br/>حیاتش شد شادمانی ام؛<br/>در غم و اندوهِ زمین،<br/>شناختِ عیساست شادی ام.<br/>',NULL,66087,1);
INSERT INTO stanza VALUES('F348','chorus','اوه، هللویاه، شادمانی ست!<br/>چون شادیِ من مسیح است!<br/>خشکی یا آب، چه فرق داره؟<br/>هر جا عیساست، شادیم آنجاست.<br/>',NULL,66088,2);
INSERT INTO stanza VALUES('F348','2','روزی زمین جایی تلخ بود<br/>تا نورِ عیسی درخشید؛<br/>حال در جانم شادی آمد،<br/>و تا ابد در من مانَد.<br/>',NULL,66089,3);
INSERT INTO stanza VALUES('F348','3','چه فرق داره مکان زیست؟<br/>بر قله، یا تَهِ دره،<br/>در کلبه، یا قصری بزرگ،<br/>هر جا عیساست، شادیم آنجاست.<br/>',NULL,66090,4);
INSERT INTO stanza VALUES('F350','1','هدفم خداست، نه صلح و شادی،<br/>نه حتی برْکت، لیک خودِ خدا؛<br/>با اوست تا رهبری کند مرا –<br/>به هر قیمتی، از هر جاده ای.<br/>',NULL,66091,1);
INSERT INTO stanza VALUES('F350','2','پس ایمان پیش رَود سوی هدف،<br/>و عشق بر خداوند تکیه کند؛<br/>در دست او، جانم در پی اوست<br/>تا او دعایم اجابت کند.<br/>',NULL,66092,2);
INSERT INTO stanza VALUES('F350','3','مهم نیست گر گاه راه تاریک باشد،<br/>مهم نیست گر بها سنگین باشد،<br/>او داند چطور رِسم به مقصد،<br/>راهِ رسیدن به او تنگ باشد.<br/>',NULL,66093,3);
INSERT INTO stanza VALUES('F350','4','یک چیز دانم، به او «نه» نگویم؛<br/>یک کار کنم، به سویش پیش رَوَم؛<br/>خدایم هست جلالم روز به روز،<br/>و در همان جلال است پاداشم.<br/>',NULL,66094,4);
INSERT INTO stanza VALUES('F352','1','در صحرا بهرِ خدا!<br/>فقط بوته ای سوزان!<br/>این گونه برْکتم دِه،<br/>بهرِ نامت درخشان.<br/>',NULL,66095,1);
INSERT INTO stanza VALUES('F352','2','بوته ای عادی تا در<br/>آن، خدا ساکن شود،<br/>و خدا سخن گوید،<br/>از طریق آن گوید،<br/>',NULL,66096,2);
INSERT INTO stanza VALUES('F352','3','از خواستش بهرِ انسان،<br/>از نیت های عشقش،<br/>نه با نورِ زمینی،<br/>لیک با نورِ جلالش.<br/>',NULL,66097,3);
INSERT INTO stanza VALUES('F352','4','خدا در بوته ساکن،<br/>فقط نور است نمایان؛<br/>مرا این چنین گردان<br/>بهرِ نامت درخشان.<br/>',NULL,66098,4);
INSERT INTO stanza VALUES('F354','1','بیا، بیا! درب باز شده حالا؛<br/>صدایت را شناختم، ای عیسی.<br/>غروب کرد خورشید، آغاز شد طوفان؛<br/>داخل شو ای منجی، شد وقتِ آن!<br/>',NULL,66099,1);
INSERT INTO stanza VALUES('F354','2','آه که اتاقْ بی نظم و ترتیب است؛<br/>اسبابْ وسط اش انباشت شده است،<br/>میز خالی و بی پوشش مبلمان؛<br/>چه استقبالی از جاوید میهمان!<br/>',NULL,66100,2);
INSERT INTO stanza VALUES('F354','3','لیک خوش آمدی، چون این وضعیت<br/>باعث شد تا از تو کنم دعوت؛<br/>این اغتشاش می طلبد فوراً<br/>دستت نظم بخش و حضورت روشن.<br/>',NULL,66101,3);
INSERT INTO stanza VALUES('F354','4','دیگر سعی ام اصلاحِ چیزها نیست،<br/>قبل از آمدنِ این چنین دوست؛<br/>همه ناشایسته و پُر آزار،<br/>چون تو را گذاشتم در انتظار.<br/>',NULL,66102,4);
INSERT INTO stanza VALUES('F354','5','بیا خودْ این دلِ آزرده را<br/>مسکنی لایقِ خودت نما؛<br/>بیرون کن ملالت، ترس و گناه:<br/>خودْ بیا داخل، خداوندْ عیسی!<br/>',NULL,66103,5);
INSERT INTO stanza VALUES('F356','1','جاذبۀ جانم!<br/>بگذار نزدیک شوم<br/>تا نبضِ زندگیِ نفْس<br/>دیگر هیچ نتپد.<br/>',NULL,66104,1);
INSERT INTO stanza VALUES('F356','2','ای خورشیدِ قلبم!<br/>پُر کن هر قسمتم،<br/>تا باغ ات عطری خوشایند<br/>برایت بدهد.<br/>',NULL,66105,2);
INSERT INTO stanza VALUES('F356','3','ای که فدیه دادی!<br/>اسیرت حفظ کنی:<br/>بهرِ استفادۀ خود،<br/>که غنیمت بردی.<br/>',NULL,66106,3);
INSERT INTO stanza VALUES('F356','4','ای خدای نور و<br/>حیات، سجده کنم،<br/>افتخاری مقدس است<br/>تسلیمِ تو شدن.<br/>',NULL,66107,4);
INSERT INTO stanza VALUES('F356','5','ای هدیۀ شِگِرف!<br/>محبتِ خدا؛<br/>دلم شکنم، محبوبم،<br/>تا جای دهم تو را.<br/>',NULL,66108,5);
INSERT INTO stanza VALUES('F362','1','بهرِ من مرد تا زیست کنم؛<br/>بهرِ او زیست کنم،<br/>عمر و عشقم به او دهم –<br/>آن عیسای مصلوب.<br/>',NULL,66109,1);
INSERT INTO stanza VALUES('F362','chorus','عیسی، خدا و منجی ام،<br/>کمک کن از پی ات روم<br/>در حیات و مرگ و خدمت،<br/>چون زیستی، مُردی، برایم.<br/>',NULL,66110,2);
INSERT INTO stanza VALUES('F362','2','او مرد برام تا بمیرم<br/>به شیطان، نفْس، گناه؛<br/>مرگی ژرف! حیاتی والا!<br/>باشد وارد شوم.<br/>',NULL,66111,3);
INSERT INTO stanza VALUES('F362','3','بهرِ من زیست کند تا من<br/>چون او بی عیب باشم؛<br/>ذاتت به من دِه، منجی ام،<br/>زندگی کن در من.<br/>',NULL,66112,4);
INSERT INTO stanza VALUES('F362','4','بهرِ من زیست کند تا من<br/>عشقش را پخش کنم؛<br/>چون او برای دیگران<br/>با او همپا باشم.<br/>',NULL,66113,5);
INSERT INTO stanza VALUES('F371','1','هر دَم نیاز به تو،<br/>خدای فیض؛<br/>هیچ صدا مثل تو<br/>آرام بخش نیست.<br/>',NULL,66114,1);
INSERT INTO stanza VALUES('F371','chorus','نیاز به تو، آه، به تو؛<br/>هر دَم نیاز به تو؛<br/>آه، منجی ام، برکت دِه!<br/>آیم به تو.<br/>',NULL,66115,2);
INSERT INTO stanza VALUES('F371','2','هر دَم نیاز به تو،<br/>نزدیک بمان؛<br/>اغوا بی قدرته<br/>چون تو هستی.<br/>',NULL,66116,3);
INSERT INTO stanza VALUES('F371','3','هر دَم نیاز به تو،<br/>شاد یا غمناک؛<br/>بیا و بمان، چون<br/>بی تو، تهی ست.<br/>',NULL,66117,4);
INSERT INTO stanza VALUES('F371','4','هر دَم نیاز به تو،<br/>خواستت فاش کن؛<br/>قولهای غنی ات<br/>در من اجرا کن.<br/>',NULL,66118,5);
INSERT INTO stanza VALUES('F371','5','هر دَم نیاز به تو،<br/>تویی قدوس؛<br/>آه، تصاحبم کن،<br/>ای پر برکت.<br/>',NULL,66119,6);
INSERT INTO stanza VALUES('F373','1','بی مانع، خداوند، بی مانع؛<br/>بینم جلالت را،<br/>جذب کن جان مرا،<br/>با من صحبت فرما –<br/>بی هیچ مانع.<br/>',NULL,66120,1);
INSERT INTO stanza VALUES('F373','2','بی مانع، خداوند، بی مانع؛<br/>کاش صدای دنیا،<br/>نکُشد نجوایت را؛<br/>شادم در آن نجوا –<br/>بی هیچ مانع.<br/>',NULL,66121,2);
INSERT INTO stanza VALUES('F373','3','بی مانع، خداوند، بی مانع؛<br/>نه غصۀ دنیا،<br/>نه اشک و یا دعا،<br/>نه پوششْ بَهرِ نفْس –<br/>بی هیچ مانع.<br/>',NULL,66122,3);
INSERT INTO stanza VALUES('F373','4','بی مانع، خداوند، بی مانع؛<br/>بی ایمانی رَوَد،<br/>شک و ترس محو شود،<br/>چون تو نزدیک شوی –<br/>بی هیچ مانع.<br/>',NULL,66123,4);
INSERT INTO stanza VALUES('F373','5','بی مانع، خداوند، بی مانع؛<br/>بتاب به روشنی،<br/>هر مه را دور کنی،<br/>بر دل مسلط شو –<br/>بی هیچ مانع.<br/>',NULL,66124,5);
INSERT INTO stanza VALUES('F373','6','بی مانع، خداوند، بی مانع؛<br/>پس با تو راه روم،<br/>تنها تو را بینم،<br/>تنها از تو باشم –<br/>بی هیچ مانع.<br/>',NULL,66125,6);
INSERT INTO stanza VALUES('F373','7','بی مانع، خداوند، بی مانع؛<br/>تا نورِ جاوْدانت،<br/>بر زمین برآید،<br/>بر چشمانم تابد –<br/>بی هیچ مانع.<br/>',NULL,66126,7);
INSERT INTO stanza VALUES('F389','1','ای عیسی، خواهم در حضورت باشم،<br/>صبح تا شب تو تنها دنیای منی؛<br/>آه، نگذار قانع یا آسوده باشم،<br/>گر باشم غیر از تو جویای چیزی.<br/>هر لحظه، هر روز در طیِ رنج و درد،<br/>چون شادی یا آرامش بخش نیست چیزی،<br/>چون اشک و آه مرا در بر بگیرد،<br/>مرا آرام بخشی، اشکهام پاک کنی.<br/>',NULL,66127,1);
INSERT INTO stanza VALUES('F389','2','هر بار که خواستارِ نیکویی باشم،<br/>دعا کنم، عیسی، تو در آن باشی؛<br/>اجازه نده خودسر برگزینم،<br/>و یا جویم غیر از تو هر نوع خوشی.<br/>هر شب چون تَک در سکوت آرامیدم،<br/>دعا کنم، عیسی، تو نزدیک باشی؛<br/>هر صبحِ سحر چون هنوز در خوابم،<br/>نجوا کرده و گوشم را باز کنی.<br/>',NULL,66128,2);
INSERT INTO stanza VALUES('F389','3','هر بار کلامِ قدوست را خوانم،<br/>دعا کنم نورت بر هر خط تابَد،<br/>تا منجی ام را به وضوح ببینم<br/>و نجاتِ عالی ات دیده شود.<br/>چون عاجز بر تختت زانو بزنم،<br/>لطفاً مرا بشنو و فیض عطا کن؛<br/>گر زِ کمبودم نشنیدی دعایم،<br/>حضورت را نگیر، روی ات نپوشان.<br/>',NULL,66129,3);
INSERT INTO stanza VALUES('F389','4','هر بار که اندیشم به برْکات تو،<br/>آه، بگذار آرزوی عروج کنم؛<br/>تنها امیدم اینجا بازگشتِ توست،<br/>تنها شادیم اینجا در حضورِ توست.<br/>یادم ده مُدام در حضورت باشم،<br/>صبح تا شب تو تنها دنیای منی؛<br/>آه، نگذار قانع یا آسوده باشم،<br/>گر باشم غیر از تو جویای چیزی.<br/>',NULL,66130,4);
INSERT INTO stanza VALUES('F390','1','منجی، رهبری ام کن،<br/>در روح و در کل روز؛<br/>سلوک در نورِ حیات،<br/>باز ایستم از تقلا.<br/>',NULL,66131,1);
INSERT INTO stanza VALUES('F390','chorus','رهبری کن،<br/>منجی، هدایتم کن؛<br/>به عمق نهرِ حیات،<br/>در راهت رهبری کن.<br/>',NULL,66132,2);
INSERT INTO stanza VALUES('F390','2','چون حیات در من هستی<br/>هادی؛ قانونِ حیات؛<br/>چون حکم کنی با قوت،<br/>نور می شود هر ظلمت.<br/>',NULL,66133,3);
INSERT INTO stanza VALUES('F390','3','روحِ رهایی بخشی،<br/>تنظیم و میزانم کن؛<br/>تازه خواهی کرد ذهنم،<br/>خواسته ات را شناسم.<br/>',NULL,66134,4);
INSERT INTO stanza VALUES('F395','1','عيسى مسيح، رشد كن در من،<br/>دگرچیزها دور کن؛<br/>قلبم هر روز نزديكترت،<br/>رها از گناهان.<br/>',NULL,66135,1);
INSERT INTO stanza VALUES('F395','chorus','هر روز بگذار تا قدرتت<br/>ضعف ام در بر گيرد؛<br/>تاريكى ام محو در نورت،<br/>مرگ، محو در حیاتت.<br/>',NULL,66136,2);
INSERT INTO stanza VALUES('F395','2','در نورِ روشنت بر من،<br/>هر فكرِ شر محو كن؛<br/>كه من هيچم، تو همه چيز،<br/>روزانه ياد گيرم.<br/>',NULL,66137,3);
INSERT INTO stanza VALUES('F395','3','بگذار از جلالت بينم،<br/>قدوس، حكيم و راست؛<br/>تصويرِ زنده ات باشم،<br/>در شادى و در غم.<br/>',NULL,66138,4);
INSERT INTO stanza VALUES('F395','4','مرا  پُر كن  با شادی ات،<br/>نگه دار با قوت؛<br/>خدایا، تابشِ عشقت<br/>از وجودم تابَد.<br/>',NULL,66139,5);
INSERT INTO stanza VALUES('F395','5','خودم كم و كمتر شوم،<br/>خودت حیاتم باش؛<br/>باشد هر روز از فيض تو<br/>نامت جلال دهم.<br/>',NULL,66140,6);
INSERT INTO stanza VALUES('F396','1','پیش روم به سوی بالا،<br/>هر روز بیشتر رَوَم بالا؛<br/>پیوسته در دعا مانم،<br/>«خدایا، بالاتر روم.»<br/>',NULL,66141,1);
INSERT INTO stanza VALUES('F396','chorus','مرا بالا بَر تا ایستم<br/>با ایمان بر کنعانْ بلند؛<br/>سطحی بالاتر را یافتم،<br/>خدایا، بالاتر روم.<br/>',NULL,66142,2);
INSERT INTO stanza VALUES('F396','2','دلم مشتاق به ماندن نیست<br/>در جایی که شک و ترس هست؛<br/>چون اینها زیادتر شوند،<br/>لیک قصدم هست سطحی بلند.<br/>',NULL,66143,3);
INSERT INTO stanza VALUES('F396','3','فَرای دنیا زیست کنم،<br/>چون شیطان کرده نشانم؛<br/>چون سرود مقدسین<br/>بر بلندا را شنیدم.<br/>',NULL,66144,4);
INSERT INTO stanza VALUES('F396','4','والاترین را می جویم<br/>تا برقِ جلال را بینم؛<br/>تا آن آسایش را یابم،<br/>خدایا، بالاتر روم.<br/>',NULL,66145,5);
INSERT INTO stanza VALUES('F403','1','در من زندگی کن، عیسی،<br/>چون حیاتِ من هستی؛<br/>بهرِ مشکلاتم  تویی<br/>راه حل واقعی.<br/>در من زندگی کن، عیسی،<br/>شود خواست تو اجرا؛<br/>من ظرفی شفاف باشم تا<br/>نمایان سازم تو را.<br/>',NULL,66146,1);
INSERT INTO stanza VALUES('F403','2','معبد تو وقف شده است،<br/>پاک از لکه و زیان؛<br/>باشد شعلۀ جلالت<br/>شود از آن نمایان.<br/>بگذار دنیا دست به دهان،<br/>داوطلب بیند مرا،<br/>که غلامی گوش به فرمان،<br/>بهرِ تو هستم تنها.<br/>',NULL,66147,2);
INSERT INTO stanza VALUES('F403','3','هر لحظه و همه اعضا<br/>منتظرِ فرمانت،<br/>که آیا کار کنند و یا<br/>ایست کنند طبق طرحت.<br/>هنگام محدود شدن ها<br/>هیچ تشویش نخواهد بود؛<br/>هنگام مقابله ها<br/>تأسف نخواهد بود.<br/>',NULL,66148,3);
INSERT INTO stanza VALUES('F403','4','ملایم، ساکت و آرام،<br/>گرایش ها به کنار،<br/>تحت هدایتت باشم<br/>تا راه را کنی آشکار.<br/>در من زندگی کن، عیسی،<br/>چون حیاتِ من هستی<br/>بهرِ مشکلاتم تویی<br/>راه حل واقعی.<br/>',NULL,66149,4);
INSERT INTO stanza VALUES('F426','1','نقابم را بردار<br/>تا نورت را بینم،<br/>و فریب نخورم،<br/>لیک درست ببینم.<br/>',NULL,66150,1);
INSERT INTO stanza VALUES('F426','chorus','آه، تا نورت، خداوند،<br/>شب مرا محو کند،<br/>روشن کند، خداوند،<br/>از تو درخواست کنم.<br/>',NULL,66151,2);
INSERT INTO stanza VALUES('F426','2','خود را کم شناختم؛<br/>فریفته با غرور،<br/>خود را درست بینم<br/>و از خود راضی ام.<br/>',NULL,66152,3);
INSERT INTO stanza VALUES('F426','3','شناخت تو کمتر،<br/>در تعالیم، سطحی؛<br/>مکاشفۀ کم<br/>از واقعیتت.<br/>',NULL,66153,4);
INSERT INTO stanza VALUES('F426','4','حیاتت در درون،<br/>لیک اشتباه گیرم –<br/>گر روح و یا نفْس است،<br/>اشتباه می گیرم.<br/>',NULL,66154,5);
INSERT INTO stanza VALUES('F426','5','خداوند در راهت،<br/>اغلب روشن نیستم؛<br/>رو به انحرافم،<br/>خلافِ مسیرم.<br/>',NULL,66155,6);
INSERT INTO stanza VALUES('F426','6','قصدت را برایم<br/>خوب نمی شِناسم؛<br/>قصدم را جایگزین،<br/>و طغیان می کنم.<br/>',NULL,66156,7);
INSERT INTO stanza VALUES('F426','7','بهرِ کلیسا به<br/>بینش نیاز دارم،<br/>زندگیِ بدن،<br/>حکمتت شناسم.<br/>',NULL,66157,8);
INSERT INTO stanza VALUES('F426','8','نقاب نمی خواهم،<br/>باشد روشن شوم،<br/>تا فریب نخورم،<br/>بر غرور نایستم.<br/>',NULL,66158,9);
INSERT INTO stanza VALUES('F433','1','از خدایم! شادیِ وصف ناپذیر،<br/>آه، واکنش به عشقِ الهی؛<br/>«بله» گفتن با ایمان به این نجواست:<br/>«نترس! تو را بازخرید کرده ام.»<br/>',NULL,66159,1);
INSERT INTO stanza VALUES('F433','2','از خدایم! اعترافِ خوشایند<br/>چون عروس که آن روز را یاد آرَد،<br/>عشق «بله» گفت و خدا را پذیرفت،<br/>در محبت، حرمت و اطاعت.<br/>',NULL,66160,2);
INSERT INTO stanza VALUES('F433','3','از خدایم! لیک یاد دِه معنی اش چیست،<br/>که شاملِ عشق و وفاداریست،<br/>خدمتِ قدوس و تسلیمِ مطلق،<br/>و از تو بی قید و شرط اطاعت.<br/>',NULL,66161,3);
INSERT INTO stanza VALUES('F433','4','از خدایم! آری؛ بدن، روان، روح،<br/>آه، تو مُهر کن، با مُهری ابَدی؛<br/>چون تو، ای محبوب، در فیض و کمالت،<br/>تا ابدلاباد از من هستی.<br/>',NULL,66162,4);
INSERT INTO stanza VALUES('F436','1','جان دادی بهرِ من،<br/>خداوند، خونت ریخت،<br/>تا رها شوم من،<br/>و تا جان بگیرم؛<br/>تو جانت دادی بهرِ من؛<br/>چه برایت دادم؟<br/>',NULL,66163,1);
INSERT INTO stanza VALUES('F436','2','صرفِ من شد سالها<br/>با خستگی و غم،<br/>تا در طی سالها<br/>جلالت شناسم؛<br/>تو صرف من کردی سالها؛<br/>چه صرف تو کردم؟<br/>',NULL,66164,2);
INSERT INTO stanza VALUES('F436','3','خانۀ پدر، با<br/>نور و رنگین کمان<br/>ترک کردی بهرِ ما،<br/>در تنهایی و حزن؛<br/>آری، ترک کردی بهرِ من؛<br/>چه بهرت ترک کردم؟<br/>',NULL,66165,3);
INSERT INTO stanza VALUES('F436','4','تو تحمل کردی<br/>طوری ناگفتنی،<br/>در رنجی جگرسوز،<br/>تا آزادم کنی؛<br/>بهرِ من تحمل کردی؛<br/>چه بهرت حمل کردم؟<br/>',NULL,66166,4);
INSERT INTO stanza VALUES('F436','5','بهرِ من آوردی،<br/>از خانه ات بالا،<br/>نجات و آزادی،<br/>بخشش و عشقت را؛<br/>بهرم هدایا آوردی؛<br/>چه بهرت آوردم؟<br/>',NULL,66167,5);
INSERT INTO stanza VALUES('F436','6','آه، جانم را دهم،<br/>بهرِ تو سال هایم؛<br/>قِید دنیا زنم،<br/>رنج و شادی باهم؛<br/>تو خود را بهرِ من دادی،<br/>خود را به تو دهم.<br/>',NULL,66168,6);
INSERT INTO stanza VALUES('F437','1','آیا می شناسی او را؟<br/>آیا قلبت شیفته نیست؟<br/>سالار در بین هزارها؛<br/>بهترین را برگزین.<br/>',NULL,66169,1);
INSERT INTO stanza VALUES('F437','chorus','شیفتۀ زیباییِ او،<br/>شایانِ ستایش است؛<br/>تحت بی همتاییِ او،<br/>او شاهِ بی نظیر است.<br/>',NULL,66170,2);
INSERT INTO stanza VALUES('F437','2','بُتها افسونت می کردند،<br/>همان چیزهای زیبا؛<br/>پس گناه خلع سِلاح کرد،<br/>پشتِ روکشِ طلا.<br/>',NULL,66171,3);
INSERT INTO stanza VALUES('F437','3','چه زیبایی بتها را<br/>که ظاهری بود، فاش کرد؟<br/>نه حق یا رفع تکلیف بود<br/>لیک دیدار عیسی بود.<br/>',NULL,66172,4);
INSERT INTO stanza VALUES('F437','4','نه خُرد کردنِ بتها بود،<br/>با پوچی و تلخی اش؛<br/>لیک تابش روی او بود،<br/>آشکارسازیِ قلبش.<br/>',NULL,66173,5);
INSERT INTO stanza VALUES('F437','5','کِه شمع شان خاموش کند<br/>تا طلوع را ببینند؟<br/>زمستان را وداع گوید<br/>تا بهار آغاز شود؟<br/>',NULL,66174,6);
INSERT INTO stanza VALUES('F437','6','آن که پطرس را مجذوب کرد،<br/>آن کس که استیفان دید،<br/>آن که با مریم گریه کرد،<br/>او از بتها رهانید:<br/>',NULL,66175,7);
INSERT INTO stanza VALUES('F437','7','جذب کن و کاملاً پُر شو،<br/>تا که جام شود سرشار؛<br/>ما را با بتها چه کاریست<br/>چونکه او را هستیم یار؟<br/>',NULL,66176,8);
INSERT INTO stanza VALUES('F438','1','من به دنیا پشت کرده ام<br/>با خوشی های پوچش.<br/>قلبم بر چیزهای بهتر،<br/>و گنجی مقدس است؛<br/>دیگر زرق و برق دنیا<br/>کورَم نتواند کرد؛<br/>از مَرز گذشتم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66177,1);
INSERT INTO stanza VALUES('F438','chorus','دور، دور پشت سر!<br/>دور، دور پشت سر!<br/>از مرز گذشتم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66178,2);
INSERT INTO stanza VALUES('F438','2','زیستنِ کهنه با گناه<br/>و بدی را ترک کردم؛<br/>جایگاهم حالا مسیح است،<br/>عهد قدوسش با من؛<br/>در زیر معیار صلیب،<br/>مرا خواهد یافت دنیا؛<br/>در مسیح زِندَم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66179,3);
INSERT INTO stanza VALUES('F438','chorus','دور، دور پشت سر!<br/>دور، دور پشت سر!<br/>در مسیح زِندَم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66180,4);
INSERT INTO stanza VALUES('F438','3','جانم آنجا برنگردد<br/>به جایگاه سابقش،<br/>چون تنها اینجا آرامش<br/>و راحت است از تهمت؛<br/>حال اربابم تغییر کرده،<br/>در بندِ نذرِ جلال،<br/>من برای اَبد دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66181,5);
INSERT INTO stanza VALUES('F438','chorus','دور، دور پشت سر!<br/>دور، دور پشت سر!<br/>من برای اَبد دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66182,6);
INSERT INTO stanza VALUES('F438','4','همیشگی است تصمیمم،<br/>منجی نخواهم جز او؛<br/>خوشیِ دگر نجویم<br/>بجز عشق و فیضِ او؛<br/>در عیسی مسیح دل بستم،<br/>با دنیا کور نشوم؛<br/>از مرگ گذشتم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66183,7);
INSERT INTO stanza VALUES('F438','chorus','دور، دور پشت سر!<br/>دور، دور پشت سر!<br/>از مرگ گذشتم و دنیا<br/>را گذاشتم پشت سر.<br/>',NULL,66184,8);
INSERT INTO stanza VALUES('F441','1','همه چیز تسلیم به عیسی،<br/>همه را به او دهم؛<br/>دائم با عشق و اعتماد<br/>در حضورش بمانم.<br/>',NULL,66185,1);
INSERT INTO stanza VALUES('F441','chorus','همه را تسلیم،<br/>همه را تسلیم؛<br/>به تو پُربرکت منجی ام،<br/>همه را تسلیم.<br/>',NULL,66186,2);
INSERT INTO stanza VALUES('F441','2','همه چیز تسلیم به عیسی،<br/>بر پای اش زانو زنم،<br/>ترک کنم لذت دنیا؛<br/>ای عیسی، مالِ تو ام.<br/>',NULL,66187,3);
INSERT INTO stanza VALUES('F441','3','همه چیز تسلیم به عیسی،<br/>منجی، تصرفم کن؛<br/>لمس کنم روح قدوست،<br/>تا دانم تویی از من.<br/>',NULL,66188,4);
INSERT INTO stanza VALUES('F441','4','همه چیز تسلیم به عیسی،<br/>خودم را به تو دهم؛<br/>با عشق و قوت پُرم کن،<br/>با خودت دِه برْکتم.<br/>',NULL,66189,5);
INSERT INTO stanza VALUES('F441','5','همه چیز تسلیم به عیسی،<br/>حس می کنم شعله ات.<br/>شادیِ نجاتِ کامل!<br/>جلال، جلال بر نامت!<br/>',NULL,66190,6);
INSERT INTO stanza VALUES('F445','1','بگير جانم و بگذار<br/>وقفِ تو باشد، خدا؛<br/>بگير لحظه و روزهام،<br/>جارى در شكرِ دائم،<br/>جارى در شكرِ دائم.<br/>',NULL,66191,1);
INSERT INTO stanza VALUES('F445','2','بگير دستهام و بگذار<br/>در عشقت حركت كنند؛<br/>بگير پاهام تا برایت<br/>چابک و زيبا باشند،<br/>چابک و زيبا باشند.<br/>',NULL,66192,2);
INSERT INTO stanza VALUES('F445','3','بگير صدام تا خوانم<br/>فقط براى شاهم؛<br/>بگير لبانم ، بگذار<br/>از پيامت پُر باشند،<br/>از پیامت پُر باشند.<br/>',NULL,66193,3);
INSERT INTO stanza VALUES('F445','4','بگير نقره و طلام؛<br/>هيچ چيز دريغ ندارم؛<br/>بگير هوشَم و آن را<br/>طبقِ خواستت به کار بر،<br/>طبقِ خواستت به کار بر.<br/>',NULL,66194,4);
INSERT INTO stanza VALUES('F445','5','بگير اراده ام را،<br/>مالِ توست و نه از من؛<br/>بگير قلبم، قلبِ توست،<br/>تختِ سلطنتِ توست،<br/>تختِ سلطنتِ توست.<br/>',NULL,66195,5);
INSERT INTO stanza VALUES('F445','6','بگير عشقم، خدايم<br/>گنجش به پايَت ريزم.<br/>بگير خودم، تا دائم<br/>فقط بهرِ تو باشم،<br/>فقط بهرِ تو باشم.<br/>',NULL,66196,6);
INSERT INTO stanza VALUES('F452','1','نگو از خوشیِ دنیا،<br/>نَفریبان با ثروت؛<br/>دست نینداز با خیالات،<br/>نَیازار با منزلت.<br/>ترک کرده ام من بُتها را؛<br/>زین پس از خودم نیستم؛<br/>به عیسی دادم قلبم را،<br/>تنها از آنِ اویم.<br/>',NULL,66197,1);
INSERT INTO stanza VALUES('F452','chorus','از خودم نیستم،<br/>از خودم نیستم.<br/>از آنِ عیسایم،<br/>و از خودم نیستم.<br/>',NULL,66198,2);
INSERT INTO stanza VALUES('F452','2','آه، آسایشِ مبارک،<br/>از مسیح بودن تنها؛<br/>برخوردار از کمالِ او<br/>چون هیچ چیز نداریم ما.<br/>عیسی، تصاحب کن مرا،<br/>حفظ و از خود کن مرا.<br/>بپذیر سهمِ تو باشم،<br/>چون از خود دانم تو را.<br/>',NULL,66199,3);
INSERT INTO stanza VALUES('F452','3','جانِ خسته، تلاش نکن<br/>که صاحبِ خود باشی؛<br/>خودت را به عیسی ببخش<br/>تا تنها از او باشی.<br/>او خودش را داد بهرِ تو،<br/>حال خودت را می خواهد؛<br/>هرچه دارد دهد به تو؛<br/>عشقت سهم او باشد.<br/>',NULL,66200,4);
INSERT INTO stanza VALUES('F463','1','سَروَرم را دوست دارم،<br/>آزاد بیرون نَرَم،<br/>او مرا بازخرید کرد؛<br/>بها داده بهرم.<br/>خدمتش ترک نکنم،<br/>خوش و مبارک است؛<br/>او در فرسودگی ها<br/>استراحت دهد.<br/>',NULL,66201,1);
INSERT INTO stanza VALUES('F463','2','سَروَرم خونَش را ریخت<br/>تا مرا کسب کند،<br/>مرا نجات داده از<br/>بندِ نفْس و گناه.<br/>بهرِ خدمت برگزید،<br/>حقِ انتخاب داد؛<br/>آن آزادیِ کامل<br/>از بین نمی رود.<br/>',NULL,66202,2);
INSERT INTO stanza VALUES('F463','3','نیمه خدمت نکنم،<br/>تماماً از اویَم؛<br/>او که عاشقِ من بود،<br/>خود را داد بهرِ من.<br/>پس شادی و ستایش<br/>خواهد بود سرودم،<br/>سَروَرم را دوست دارم،<br/>آزاد بیرون نَرَم.<br/>',NULL,66203,3);
INSERT INTO stanza VALUES('F472','1','اکثر ملکوت را خواهند،<br/>اندک صلیب را؛<br/>اکثر دلداری می خواهند،<br/>اندک ضرر را.<br/>برای سَرور حساب کن<br/>فضله چیزها را.<br/>برای سَرور حساب کن<br/>فضله چیزها را.<br/>',NULL,66204,1);
INSERT INTO stanza VALUES('F472','2','اکثر بر میزِ عیسایند،<br/>اندک در روزه،<br/>چون آن جامِ غم و اندوه<br/>تا سر پُر بشه،<br/>اندک با او بیدار مانند<br/>که سرود خواندند.<br/>اندک با او بیدار مانند<br/>که سرود خواندند.<br/>',NULL,66205,2);
INSERT INTO stanza VALUES('F472','3','اکثر حکمتش را دانند،<br/>اندک شرم اش را.<br/>اکثر در حضورش گویند<br/>ستایش اش را؛<br/>لیک در غیابش ترک کنند<br/>همان نامش را.<br/>لیک در غیابش ترک کنند<br/>همان نامش را.<br/>',NULL,66206,3);
INSERT INTO stanza VALUES('F472','4','لیک آنها که عاشقش اند،<br/>محزون یا خرسند،<br/>خون در رگهای خودشان<br/>را از او دانند.<br/>منجی، که عاشقی چنین،<br/>به من دِه همین.<br/>منجی، که عاشقی چنین،<br/>به من دِه همین.<br/>',NULL,66207,4);
INSERT INTO stanza VALUES('F473','1','زبان نتواند گوید<br/>آزادی جان را،<br/>از هر رشوۀ زمینی،<br/>به دستهای خدا.<br/>همه از اوست، مرگ و حیات،<br/>حالا و آینده؛<br/>از مسیح هر نفَس آید،<br/>در مسیح است خانه.<br/>',NULL,66208,1);
INSERT INTO stanza VALUES('F473','2','چون شاه را برگزینیم تا<br/>سهیمِ تخت باشیم،<br/>عجیب است که نپذیریم<br/>تنها از او باشیم.<br/>هرگز از قربانی نگو!<br/>که یک افتخار است؛<br/>از او باشیم به هر بها،<br/>افرادِ جُلجُتا.<br/>',NULL,66209,2);
INSERT INTO stanza VALUES('F473','3','برخیز! سودای الهی ست –<br/>جزئی برای کل –<br/>جان که فدیه شد را باید<br/>همه خدمت کنند.<br/>همه از توست چون از اویی،<br/>و او با تو یکیست؛<br/>در اوست حیاتِ نامحدود،<br/>چون شَک و ترسی نیست.<br/>',NULL,66210,3);
INSERT INTO stanza VALUES('F474','1','يک با تو، خداوندْ عيسى،<br/>يک در روحْ حالا با تو؛<br/>تو را دارم ،اى خداوند،<br/>در من زندگی کنی.<br/>',NULL,66211,1);
INSERT INTO stanza VALUES('F474','chorus','يک با تو، يک با تو.<br/>يک با تو، يک با تو.<br/>روز به روز سهيم ات هستم،<br/>تو همه چيزى بَرام.<br/>',NULL,66212,2);
INSERT INTO stanza VALUES('F474','2','حال سهیم شَوم حياتت،<br/>پر از انسانيتت،<br/>مطیع بودنِ كاملت<br/>برايم در دسترس است.<br/>',NULL,66213,3);
INSERT INTO stanza VALUES('F474','3','يک با تو در مصلوب شدن،<br/>بر صليب مُردم در تو؛<br/>من مُردم به دنيا، خدا،<br/>و دنيا مُرده به من.<br/>',NULL,66214,4);
INSERT INTO stanza VALUES('F474','4','يک با تو در رستاخيزت،<br/>بهرِ زندگى در تو،<br/>آن حيات كه خودت هستى،<br/>حال در من، حتی در من.<br/>',NULL,66215,5);
INSERT INTO stanza VALUES('F474','5','يک با تو در صعودِ تو،<br/>در آسمان حال با تو؛<br/>اينجا زَوار و غريبه،<br/>حياتم پنهان در تو.<br/>',NULL,66216,6);
INSERT INTO stanza VALUES('F474','6','يک با تو درسلطنتت،<br/>سهيم در اقتدارت،<br/>حتی در حياتت، خدا،<br/>من در تو و تو در من.<br/>',NULL,66217,7);
INSERT INTO stanza VALUES('F475','1','يک با تو، پسرِ جاوید،<br/>وصل با ايمان در يک روح،<br/>سهيم در مرگِ شامل ات<br/>و در حياتت، خدا.<br/>يک با تو، پسرِ محبوب<br/>از فيض جزو تو شديم،<br/>وارث با تو از يک پدر،<br/>مسكنِ روحت هستيم.<br/>',NULL,66218,1);
INSERT INTO stanza VALUES('F475','2','يک با تو كه جسم پوشيدى،<br/>زاده با تو، ای نفیس،<br/>ما اعضاى بدنِ تو،<br/>بر زمين سَيار با تو.<br/>يک با پسرِ مسح شده،<br/>سهيم در روحِ قدرت،<br/>ما در همكارىِ كامل<br/>كار با تو در هر ساعت.<br/>',NULL,66219,2);
INSERT INTO stanza VALUES('F475','3','يک با تويى كه تَرک گشتى،<br/>از قضاوت گذشتيم؛<br/>تا ابد به گناه مُرديم،<br/>دوزخ زير پا افتاد.<br/>يک با تو در رستاخیزت،<br/>مرگ رنجمان ندهد؛<br/>در خلقت نو زيست كنيم،<br/>با ميوۀ صداقت.<br/>',NULL,66220,3);
INSERT INTO stanza VALUES('F475','4','يک با تو كه صعود كردى،<br/>بر تخت سلطنتت،<br/>سهيم در اقتدارت و<br/>حكم با تو در مقامت.<br/>يک با تو كه بر مى گردى،<br/>با تو جلال می یابيم،<br/>زيبايیْت نمايان سازيم،<br/>تا ابد يک با توييم.<br/>',NULL,66221,4);
INSERT INTO stanza VALUES('F482','1','من مصلوب شدم با مسيح،<br/>و صليب آزادم كرد؛<br/>من برخاسته ام با مسيح،<br/>در من زیست و حکم کند.<br/>',NULL,66222,1);
INSERT INTO stanza VALUES('F482','chorus','اوه! شيرينه مردن با مسيح،<br/>به دنيا، نفْس و گناه؛<br/>اوه! شيرينه زيستن با مسيح،<br/>در من زیست و حکم کند.<br/>',NULL,66223,2);
INSERT INTO stanza VALUES('F482','2','رازِ پنهانِ باستانى<br/>در ايمان آشكار شده:<br/>دائم گویم که مسيح در<br/>من امیدِ جلاله.<br/>',NULL,66224,3);
INSERT INTO stanza VALUES('F482','3','اين رمزِ طبيعت است که<br/>دفن بذر میوه دهد؛<br/>آن شاخۀ پيوند خورده،<br/>حياتِ غنى گيرد.<br/>',NULL,66225,4);
INSERT INTO stanza VALUES('F482','4','اين رمزِ مقدسان است<br/>که او قدوس است نه ما؛<br/>خداوند، خالى و پُر كن،<br/>با خودت لبريز نما.<br/>',NULL,66226,5);
INSERT INTO stanza VALUES('F482','5','مرهمْ بهرِ مرض و درد،<br/>مُردن به قوتِ خود،<br/>و حيات  و پُرىِ او<br/>نيازمان رفع كند.<br/>',NULL,66227,6);
INSERT INTO stanza VALUES('F482','6','اين حکایتِ سَرور است،<br/>از صليب به تخت رسيد،<br/>چون او، راهمان به جلال<br/>تنها از راهِ مرگ است.<br/>',NULL,66228,7);
INSERT INTO stanza VALUES('F483','1','دفن با مسیح، با او برخاستم؛<br/>چه کار مانده تا انجام دهم؟<br/>فقط اتمامِ جنگ، درگیری،<br/>فقط راه رفتن در تازگی.<br/>جلال بر خدا!<br/>',NULL,66229,1);
INSERT INTO stanza VALUES('F483','2','برخاستم با مسیحِ جلال،<br/>راه می روم در قدوسیت،<br/>فکری قشنگ هست در طیِ راه:<br/>آن که مُرده رهاست از گناه.<br/>جلال بر خدا!<br/>',NULL,66230,2);
INSERT INTO stanza VALUES('F483','3','زیستن با مسیح، که نمیرد،<br/>از پیِ او که پیشتر رود؛<br/>کاملاً از بندْ آزاد شدم،<br/>نفْسم را مرده می شمارم.<br/>جلال بر خدا!<br/>',NULL,66231,3);
INSERT INTO stanza VALUES('F483','4','بهرِ مسیح، تسلیمِ اویَم،<br/>خادمِ خدا، مُهر شده ام،<br/>تحت فیض ام و نه شریعت،<br/>گناه رفت، مسیح کرد سکونت.<br/>جلال بر خدا!<br/>',NULL,66232,4);
INSERT INTO stanza VALUES('F483','5','رشد در مسیح؛ نام نیاورم<br/>چیزهایی که از آن خجلم،<br/>میوۀ قِداست آورم،<br/>من حیات ابدی دارم.<br/>جلال بر خدا!<br/>',NULL,66233,5);
INSERT INTO stanza VALUES('F490','1','عیسی، پدر ناشناس بود،<br/>پدر از راه تو آمد،<br/>تا ما که در جهل می زیستیم،<br/>از تو پدر را بشناسیم.<br/>',NULL,66234,1);
INSERT INTO stanza VALUES('F490','2','لیک وقتی بر زمین بودی،<br/>چه اندک تو را شناختند؛<br/>پرده ای مابین تان بود؛<br/>گِرد آمده لیک ندیدند.<br/>',NULL,66235,2);
INSERT INTO stanza VALUES('F490','3','حال چون آن روح آمده ای<br/>چون پدر که در تو آمد؛<br/>از تو پدر را شناسیم،<br/>حال از روحْ تو را شناسیم.<br/>',NULL,66236,3);
INSERT INTO stanza VALUES('F490','4','حال به جسم ملبس نیستی –<br/>که در مشقت راه روی؛<br/>لیک چون روحْ در قلب مایی<br/>خود را آزادانه دهی.<br/>',NULL,66237,4);
INSERT INTO stanza VALUES('F490','5','روزی پدر لقب داشتی،<br/>لیک حالا روح قدوسی؛<br/>آن روحْ شکلِ دیگر توست،<br/>در قلب ما ساکن شوی.<br/>',NULL,66238,5);
INSERT INTO stanza VALUES('F490','6','با شناختت چون روح، عیسی،<br/>جریان حیات را دانیم،<br/>جلال و شخصیت تو،<br/>شگرفی ات را شناسیم.<br/>',NULL,66239,6);
INSERT INTO stanza VALUES('F490','7','دلها از ستایش لبریز؛<br/>هیچکس مثل تو عزیز نیست؛<br/>چون تو هستی واقعیت،<br/>هیچکس محبوب تر از تو نیست.<br/>',NULL,66240,7);
INSERT INTO stanza VALUES('F493','1','خداوند، حالا روح هستى،<br/>حيات دهى، زنده كنى؛<br/>با غنایت قوت دهى،<br/>چه پرجلال و الهى!<br/>',NULL,66241,1);
INSERT INTO stanza VALUES('F493','2','خداوند، حالا روح هستى،<br/>با قدرتت آزاد كنى؛<br/>با آزادىِ واقعى<br/>در حياتت ميزان كنى.<br/>',NULL,66242,2);
INSERT INTO stanza VALUES('F493','3','خداوند، حالا روح هستى،<br/>دگرگون و اشباع كنى؛<br/>به صورتت همشکل سازی<br/>و با نورت روشن کنی.<br/>',NULL,66243,3);
INSERT INTO stanza VALUES('F493','4','خداوند، حالا روح هستى،<br/>در روحِ من خانه كنى؛<br/>آميخته با روحم شدى،<br/>و هر دو يک روح مى شويم.<br/>',NULL,66244,4);
INSERT INTO stanza VALUES('F493','5','خدا، ياد ده تمرین کنم،<br/>در روح با تو تماس گيرم،<br/>تا در روحِ تو راه روم<br/>در واقعیت زيست كنم.<br/>',NULL,66245,5);
INSERT INTO stanza VALUES('F496','1','مسیح تنها واقعیتِ کل<br/>از خدا، انسان و همه چیزهاست؛<br/>بی او انسان خدا را نیابد،<br/>بی او انسان و همه کاذب است.<br/>',NULL,66246,1);
INSERT INTO stanza VALUES('F496','2','نمادها و تصاویرِ باستان،<br/>نیازهای ما، بزرگ و کوچک،<br/>فقط سایۀ مسیحِ خداست،<br/>اینکه او باید همه چیز باشد.<br/>',NULL,66247,2);
INSERT INTO stanza VALUES('F496','3','همه چیزها باطلِ اباطیل،<br/>مسیح، آن محتوای واقعی ست؛<br/>هرچیز داشته و لذت ببریم،<br/>بدون مسیح همه چیز تهی ست.<br/>',NULL,66248,3);
INSERT INTO stanza VALUES('F496','4','مسیح خدای واقعی ماست،<br/>مسیح حیات و نورِ واقعی ست؛<br/>مسیح غذا و آبِ واقعی،<br/>لباس و هم نیروی واقعی ست.<br/>',NULL,66249,4);
INSERT INTO stanza VALUES('F496','5','مسیح نیز آن تنها واقعیت<br/>از الهیات و تعالیم است؛<br/>دانشِ روحانی بدون او<br/>تنها حروف است و بطالت است.<br/>',NULL,66250,5);
INSERT INTO stanza VALUES('F496','6','مسیح، اصلِ زمان و مکان است،<br/>مسیح، واقعیتِ هر پله؛<br/>مسیح تنها واقعیتِ کل<br/>از ازل و از دوره به دوره.<br/>',NULL,66251,6);
INSERT INTO stanza VALUES('F497','1','فیض به معنای واقعیِ آن،<br/>خداست در پسر مَسرت مان؛<br/>آن نه تنها کاری یا بخششی ست،<br/>لیک سهمِ پرجلال خودِ خداست.<br/>',NULL,66252,1);
INSERT INTO stanza VALUES('F497','2','خدا جسم پوشید و جسم شد تا ما<br/>دریافت و تجربه کنیم او را؛<br/>آنچه ما از او می یابیم فیض است،<br/>که از مسیح و خودِ مسیح است.<br/>',NULL,66253,2);
INSERT INTO stanza VALUES('F497','3','پولس حساب کرد فضله همه را،<br/>خدا در مسیح را فیض خوانْد تنها؛<br/>با این فیض است، تجربۀ خدا<br/>که او جلو زد مسابقه را.<br/>',NULL,66254,3);
INSERT INTO stanza VALUES('F497','4','همین فیض است، مسیح نیروی ما<br/>که به کفایت پُر کند ما را؛<br/>فیض در روحمان انرژی بخشد،<br/>خواست خدا را اجرا می کند.<br/>',NULL,66255,4);
INSERT INTO stanza VALUES('F497','5','این فیض که خودِ مسیحِ زِندَست،<br/>نیاز ما بهرِ تجربه است؛<br/>خداوند، باشد با فیض زیست کنم،<br/>و تو را چون فیض بیشتر شناسم.<br/>',NULL,66256,5);
INSERT INTO stanza VALUES('F499','1','آه چه حيات و چه صلحى!<br/>مسيح در من زیست می کند.<br/>من با او مصلوب شده ام؛<br/>پر جلال است این حقیقت.<br/>حال دگر من زیست نکنم،<br/>لیک مسيح در من زنده است.<br/>حال دگر من زیست نکنم،<br/>لیک مسيح در من زنده است.<br/>',NULL,66257,1);
INSERT INTO stanza VALUES('F499','2','آه چه شادى! چه آسايش!<br/>مسيح در من شكل می گيرد.<br/>ذات و حياتِ الهی،<br/>در درونِ وجودم است.<br/>هر چه هستم تمام شده،<br/>هر چه او هست همه چيزم.<br/>هر چه هستم تمام شده،<br/>هر چه او هست همه چيزم.<br/>',NULL,66258,2);
INSERT INTO stanza VALUES('F499','3','آه چه فكرى! چه افتخار!<br/>مسيح در من تجلیل شود.<br/>در هيچ شرمنده نشوم،<br/>چون او را بكار مى برم.<br/>غم يا شادى، مرگ يا حيات،<br/>او را شهادت مى دهم.<br/>غم يا شادى، مرگ يا حيات،<br/>او را شهادت مى دهم.<br/>',NULL,66259,3);
INSERT INTO stanza VALUES('F499','4','آه چه پاداش و چه سودى!<br/>مسيح هدفِ جاوْدانم.<br/>هيچ گنج و ميلى ندارم،<br/>جز مسيح، شاملِ تمام.<br/>اميد، جلال و تاجِ من،<br/>مسيح، آن شخصِ بى همتاست.<br/>اميد، جلال و تاجِ من<br/>مسيح، آن شخصِ بى همتاست.<br/>',NULL,66260,4);
INSERT INTO stanza VALUES('F500','1','آه چه قدرت، چه قوتى!<br/>خدا مسيح را برخيزانْد.<br/>بالاتر از کل عالم،<br/>بر همه چيزِ ما سَر اوست.<br/>کلِ قدرت به كليساست<br/>تا دشمن را پایمال كند.<br/>کلِ قدرت به كليساست<br/>تا دشمن را پایمال كند.<br/>',NULL,66261,1);
INSERT INTO stanza VALUES('F500','2','آه حقيقتِ خوشايند!<br/>كه عضوى از مسيح هستم.<br/>با مقدسينْ يکپارچه،<br/>در حياتِ انسانِ نو.<br/>وصل به سَرِ صعود كرده،<br/>كليساى طرحش هستيم.<br/>وصل به سَرِ صعود كرده،<br/>كليساى طرحش هستيم.<br/>',NULL,66262,2);
INSERT INTO stanza VALUES('F500','3','آه چه عرضى و چه طولى!<br/>بُلندا، عمقِ بى پايان!<br/>مسيح، خداى نامحدود،<br/>عظيم، وسيع و بیكران.<br/>هر چه هست و دارد، حالا<br/>حياتِ پرشکوهِ ماست.<br/>هر چه هست و دارد، حالا<br/>حياتِ پرشکوهِ ماست.<br/>',NULL,66263,3);
INSERT INTO stanza VALUES('F501','1','آه مسیح، پرجلال منجی،<br/>تو هستی نورِ الهی؛<br/>خدای جاوْدان، سَرمَدى،<br/>ليک انسانِ محدود شدى.<br/>',NULL,66264,1);
INSERT INTO stanza VALUES('F501','chorus','اوه! مسيح، ابراز خدایی،<br/>پايدار و غنى و شيرين!<br/>خدا آميخته با انسان<br/>زندگی كند در من.<br/>',NULL,66265,2);
INSERT INTO stanza VALUES('F501','2','پُریِ خدا در تو است؛<br/>جلالش نمايان سازى؛<br/>در جسم، بازخرید آوردى؛<br/>در روح، با من يكى شدى.<br/>',NULL,66266,3);
INSERT INTO stanza VALUES('F501','3','همه چیزِ پدر در توست؛<br/>همه چیزت در روح، از من؛<br/>تو را روحْ واقعی كند،<br/>تا شَوى تجربۀ من.<br/>',NULL,66267,4);
INSERT INTO stanza VALUES('F501','4','روحِ حيات باعث شود<br/>آیی به من از کلامت.<br/>لمسِ روح، دريافتِ كلام،<br/>حیاتت در من شکل گیرد.<br/>',NULL,66268,5);
INSERT INTO stanza VALUES('F501','5','در روح، چون بر تو چشم دوزم،<br/>جلالت انعکاس دهم،<br/>چون خودت دگرگون شوم،<br/>تا تو از من ابراز شوى.<br/>',NULL,66269,6);
INSERT INTO stanza VALUES('F501','6','هیچطور دِگر نتوانيم<br/>در ظفرت تقديس شويم؛<br/>پس فقط روحانى باشيم،<br/>حياتِ جلال لمس كنيم.<br/>',NULL,66270,7);
INSERT INTO stanza VALUES('F501','7','روحت اشباعم مى كند،<br/>در من خدا نفوذ كند،<br/>از كهنگى رها كند،<br/>طبقِ طرحش بنا سازد.<br/>',NULL,66271,8);
INSERT INTO stanza VALUES('F505','1','یک انسان در جلاله<br/>كه حياتِ منه.<br/>خالص و قدوسه،<br/>پيروز و آزاد.<br/>داناست و مهربان،<br/>چقدر رحیمه!<br/>حياتش در جلال،<br/>حياتم بايد؛<br/>حياتش در جلال،<br/>حياتم بايد.<br/>',NULL,66272,1);
INSERT INTO stanza VALUES('F505','2','يک انسان در جلاله<br/>كه حياتِ منه.<br/>بر شيطان غالب شد؛<br/>از بند آزاد است.<br/>در حيات حکم رانَد؛<br/>چقدر شاهانه ست!<br/>حياتش در جلال،<br/>حياتم بايد؛<br/>حياتش در جلال،<br/>حياتم بايد.<br/>',NULL,66273,2);
INSERT INTO stanza VALUES('F505','3','يک انسان در جلاله<br/>كه حياتِ منه.<br/>در او بيمارى نيست؛<br/>ضعفى نداره.<br/>قوى  و توانا،<br/>چقدر سرزندَست!<br/>حياتش در جلال،<br/>حياتم شود؛<br/>حياتش در جلال،<br/>حياتم شود.<br/>',NULL,66274,3);
INSERT INTO stanza VALUES('F505','4','يک انسان در جلاله<br/>كه حياتِ منه.<br/>صلحش ماندگاره؛<br/>چقدر صبوره!<br/>مسرور و درخشان،<br/>خواهد ببيند:<br/>حياتش در جلال،<br/>زندگیِ من،<br/>حياتش در جلال،<br/>زندگیِ من.<br/>',NULL,66275,4);
INSERT INTO stanza VALUES('F507','1','دور از خدا و در گناه،<br/>نورى نمى ديدم؛<br/>پيدا كردم نور در كلام،<br/>مسيح درونمه.<br/>',NULL,66276,1);
INSERT INTO stanza VALUES('F507','chorus','مسيح، درونمه،<br/>مسيح، درونمه؛<br/>اوه، عجب نجاتيه،<br/>مسيح، درونمه.<br/>',NULL,66277,2);
INSERT INTO stanza VALUES('F507','2','همچون درخششِ خورشيد<br/>كه گُل مى روياند،<br/>حيات و نور و عشق آيد<br/>از مسيحِ در من.<br/>',NULL,66278,3);
INSERT INTO stanza VALUES('F507','3','همچون گُل درونِ دانه،<br/>و ميوه بر درخت،<br/>شُكرْ مسيحِ راستى و فيض،<br/>روحش درونمه.<br/>',NULL,66279,4);
INSERT INTO stanza VALUES('F507','4','قلبم با آرزو پُر است،<br/>كه شكلِ او شوم،<br/>چون در اين فكرِ شگرفم:<br/>مسيح درونمه.<br/>',NULL,66280,5);
INSERT INTO stanza VALUES('F509','1','یک نهرِ جاری و درخت<br/>هستند ویژگیِ عَدَن،<br/>آب و غذا تأمین کنند،<br/>بهرِ دائم زیستن.<br/>',NULL,66281,1);
INSERT INTO stanza VALUES('F509','chorus','خدا در مسیح نعمتم است،<br/>خدا چون روح غذایم دهد؛<br/>گر در روح با او تغذیه شَم،<br/>با حیات پر شَوم.<br/>',NULL,66282,2);
INSERT INTO stanza VALUES('F509','2','درخت نشانِ مسیح است،<br/>که چون غذای زنده است،<br/>تا از خدا لذت بریم،<br/>و راضی بشویم.<br/>',NULL,66283,3);
INSERT INTO stanza VALUES('F509','3','نهر نشانِ همان روح است،<br/>که آمد تا سیراب کند،<br/>تا از غنایش پُر شویم،<br/>ما را تقدیس کند.<br/>',NULL,66284,4);
INSERT INTO stanza VALUES('F509','4','مسیح زندگیِ من است،<br/>چون روح، زیست کند در روحم،<br/>تا با خدا یکی شوم<br/>و ابرازش کنم.<br/>',NULL,66285,5);
INSERT INTO stanza VALUES('F509','5','مسیح را تجلی کنم،<br/>از روح اطاعت خواهم کرد،<br/>جلالش را آشکار کنم،<br/>با فیض اش پُر شوم.<br/>',NULL,66286,6);
INSERT INTO stanza VALUES('F513','1','روزى برکات بود،<br/>حال خود خداست؛<br/>روزى احساسات بود،<br/>حال كلامِ اوست؛<br/>روزى هدیه خواستم،<br/>حال بخشنده را؛<br/>روزى شفا خواستم،<br/>حال خودش تنها.<br/>',NULL,66287,1);
INSERT INTO stanza VALUES('F513','chorus','دائم و همیشه،<br/>مسيح خواهم خواند،<br/>همه چيز در مسيح،<br/>مسيح همه چيز است.<br/>',NULL,66288,2);
INSERT INTO stanza VALUES('F513','2','روزى تقلا بود،<br/>حال اعتماد است؛<br/>روزى نیمه نجات،<br/>حال تا نهايت؛<br/>روزی حفظِ چیزها،<br/>حال محافظ اوست؛<br/>روزى سرگردانی،<br/>حال رسیده ام.<br/>',NULL,66289,3);
INSERT INTO stanza VALUES('F513','3','روزى طرح ریختن بود،<br/>حال دعا كردن؛<br/>روزى اضطراب بود،<br/>حال مراقبْ اوست؛<br/>روزى خواستِ من بود،<br/>حال عيسى گويد؛<br/>روزى پرسيدن بود،<br/>حال ستايش است.<br/>',NULL,66290,4);
INSERT INTO stanza VALUES('F513','4','روزى كارِ من بود،<br/>حال كارها از اوست؛<br/>روزى سود بردن بود،<br/>حال من سودِ او؛<br/>روزى قدرت خواستم،<br/>حال آن قدرتمند؛<br/>روزى برای خود<br/>حال برای او.<br/>',NULL,66291,5);
INSERT INTO stanza VALUES('F513','5','روزى اميد به او،<br/>حال مالِ من است؛<br/>روزى نورم خاموش،<br/>حال درخشان است؛<br/>روزى چِشم به مُردن،<br/>حال آمدنش؛<br/>اميدم محكم شد<br/>در حضور او.<br/>',NULL,66292,6);
INSERT INTO stanza VALUES('F523','1','آمدم به چشمۀ حیات،<br/>همان که از بالا جاریست؛<br/>از آبهای نارام گذشتم،<br/>و، به باغِ عشق آمدم؛<br/>از چاه آسمانی نوشم،<br/>در عمقِ وجودم می جهد.<br/>هیچ حدی و کلامی نیست<br/>بهرِ شادی که  می دهد.<br/>',NULL,66293,1);
INSERT INTO stanza VALUES('F523','chorus','بیا به چشمۀ حیات،<br/>چشمه ای که خشک نشود؛<br/>بنوش از نعمتِ سرشار،<br/>مسیح هست چشمۀ حیات.<br/>',NULL,66294,2);
INSERT INTO stanza VALUES('F523','2','آمدم به آن چشمۀ خون،<br/>آن که بهرِ گناه جاریست؛<br/>در آبش شستشو کرده ام،<br/>از برفْ سفیدتر جامه ام.<br/>صداقت را از خود ندانم<br/>آن عیساست که در من زنده است.<br/>از ذات او برخوردارم،<br/>در او وجودم کامل است.<br/>',NULL,66295,3);
INSERT INTO stanza VALUES('F523','3','آمدم به چشمۀ سالم،<br/>که تأمینی نامحدود است؛<br/>رمزی است که حکمت و ثروت<br/>خریداری یا کشف نکرد.<br/>اما آنچه خدا آشکار کرد<br/>از نهرِ جاری از پهلویش،<br/>در زخمهایش شفا یابیم،<br/>همانطور که در ما مانَد.<br/>',NULL,66296,4);
INSERT INTO stanza VALUES('F523','4','آمدم به چشمۀ شادی؛<br/>شادیِ او قوتم است.<br/>خشنودی ام بی اختلاط است،<br/>خورشیدم غروب نکند.<br/>درخت انجیر خشک شد و مُرد،<br/>در خوشیِ دنیا پایان است؛<br/>لیک چشمه ام خشک نشود<br/>سهم و شادی ام الهی ست.<br/>',NULL,66297,5);
INSERT INTO stanza VALUES('F529','1','ملال انگیزند لحظه ها<br/>وقتی عیسی را نبینم!<br/>نما، بلبل ها و گُل ها<br/>دیگر گیرا نیست برایم.<br/>خورشید می تابد، لیک کم سو،<br/>دشت و هامون شادی بخش نیست؛<br/>لیک وقتی در عیسی شادم<br/>بهمن همچون خرداد زیباست.<br/>',NULL,66298,1);
INSERT INTO stanza VALUES('F529','2','نامش معطر، صدایش<br/>بهتر است از هر آهنگی؛<br/>حضورش غم را زُداید،<br/>دل را پُر کند از شادی.<br/>هرگاه چنین نزدیک باشد،<br/>هیچ خواست یا ترسی ندارم؛<br/>هیچ شادی بیشتر نباشد؛<br/>بی پایان باشد بهارم.<br/>',NULL,66299,2);
INSERT INTO stanza VALUES('F529','3','خرسند با دیدار رویَش،<br/>کل وجودم فدایش؛<br/>نه تغییر جا یا فصلی،<br/>فکرم را دهد تغییری.<br/>با برْکتِ حسِ عشقش،<br/>قصر به چشمْ بازیچه آید؛<br/>و زندان چون قصر باشد، گر<br/>عیسی با من آنجا باشد.<br/>',NULL,66300,3);
INSERT INTO stanza VALUES('F529','4','خداوند، گر از تو هستم،<br/>گر خورشید و سرودمی،<br/>چرا غم و غصه دارم؟<br/>و زمستانم طولانی؟<br/>آه، ابر از آسمان بردار،<br/>حضورت جانم را شادی؛<br/>یا با خود بالایم بِبر،<br/>که نیست زمستان و ابری.<br/>',NULL,66301,4);
INSERT INTO stanza VALUES('F538','1','قصد و خواست خدا اینکه<br/>مسیح در من فاش شود،<br/>نه مذهبِ ظاهری، لیک<br/>مسیحِ درون باشد.<br/>',NULL,66302,1);
INSERT INTO stanza VALUES('F538','chorus','قصد و خواست خدا اینکه<br/>مسیح در من شکل گیرد؛<br/>نه تظاهر، بلکه مسیح،<br/>همه چیزِ من باشد.<br/>',NULL,66303,2);
INSERT INTO stanza VALUES('F538','2','قصد و خواست خدا اینکه<br/>مسیح در من زیست کند؛<br/>نه چون تمرین از بیرون، لیک<br/>مسیح در من کار کند.<br/>',NULL,66304,3);
INSERT INTO stanza VALUES('F538','3','قصد و خواست خدا اینکه<br/>مسیح در من شکل گیرد؛<br/>نه تقلیدِ ظاهری، لیک<br/>مسیح در من رشد کند.<br/>',NULL,66305,4);
INSERT INTO stanza VALUES('F538','4','قصد و خواست خدا اینکه<br/>او در من خانه سازد؛<br/>نه خدمت ظاهری، لیک<br/>مسیح مسکن گزیند.<br/>',NULL,66306,5);
INSERT INTO stanza VALUES('F538','5','قصد و خواست خدا اینکه<br/>مسیح امیدم باشد؛<br/>این جلالی ظاهری نیست،<br/>لیک مسیحِ درونی ست.<br/>',NULL,66307,6);
INSERT INTO stanza VALUES('F538','6','قصد و خواست خدا اینکه<br/>مسیح همه چیز باشد؛<br/>نه داراییِ ظاهری،<br/>اما مسیح تا ابد.<br/>',NULL,66308,7);
INSERT INTO stanza VALUES('F539','1','ای خدا، تو در من حيات<br/>و همه چیز هستی!<br/>همیشه حاضر، در دسترس،<br/>تجربه ات کنم.<br/>',NULL,66309,1);
INSERT INTO stanza VALUES('F539','chorus','خدايا، آن روحْ هستی!<br/>چه نزدیک و عزیز!<br/>دسترسی عجیبت را<br/>مسرت مى برم!<br/>',NULL,66310,2);
INSERT INTO stanza VALUES('F539','2','بهرِ نيازم هر چه هست<br/>تدارکى غنی؛<br/>آماده و کافی هستی<br/>بهرم از هر نظر.<br/>',NULL,66311,3);
INSERT INTO stanza VALUES('F539','3','مَسحِ شیرین با نیرویَت<br/>در ضعف قوتم است؛<br/>با نیرویِ دائمِ خود<br/>قوتم حفظ کنی.<br/>',NULL,66312,4);
INSERT INTO stanza VALUES('F539','4','قانونِ حيات در وجود<br/>هدایتم کند؛<br/>ثروتِ واقعیتت<br/>مرا سيراب کند.<br/>',NULL,66313,5);
INSERT INTO stanza VALUES('F539','5','ای هميشه با من یکی،<br/>وحدتى بى نظير!<br/>یک روح هميشه با منی<br/>تا ابدلاباد!<br/>',NULL,66314,6);
INSERT INTO stanza VALUES('F540','1','منجی رهایی داد مرا!<br/>مسیح مرا آزاد کرد!<br/>شکست قدرت گناه را،<br/>نیشِ مرگ از من گذشت!<br/>',NULL,66315,1);
INSERT INTO stanza VALUES('F540','chorus','در مسیح بیش از پیروزم،<br/>با قدرتِ پیروزش،<br/>حالا قدرتِ قیامش<br/>در روحْ  قوتِ من است!<br/>',NULL,66316,2);
INSERT INTO stanza VALUES('F540','2','از شریعت آزادم کرد،<br/>مُردم به الزاماتش؛<br/>هرگز در بندِ آن نیستم،<br/>با فیض زندگی کنم.<br/>',NULL,66317,3);
INSERT INTO stanza VALUES('F540','3','مسیح محکوم کرد گناه را<br/>از بین برد قدرتش را؛<br/>حال در من جایی ندارد،<br/>از نوسان آزادم.<br/>',NULL,66318,4);
INSERT INTO stanza VALUES('F540','4','مسیح مرگ را از میان برداشت،<br/>حیاتِ جاوید پیداست؛<br/>بندهای اسارت شکست،<br/>حیاتِ قیام گیراست.<br/>',NULL,66319,5);
INSERT INTO stanza VALUES('F540','5','مسیح شیطان را مغلوب کرد،<br/>دنیا و پلیدی را؛<br/>مرا از تاریکی آورد<br/>درونِ نور و حیات.<br/>',NULL,66320,6);
INSERT INTO stanza VALUES('F540','6','او فیض کامل می بخشد،<br/>با قدرت می پوشاند؛<br/>در ناتوانی فخر کنم،<br/>چون او قوتم بخشد.<br/>',NULL,66321,7);
INSERT INTO stanza VALUES('F541','1','نه قانونِ حروف،<br/>لیک مسیحِ حیّ<br/>را خدا می دهد،<br/>تا نکنیم سعی؛<br/>این یک تعلیم نیست، لیک<br/>خودِ مسیحاست<br/>که آزاد می کند<br/>از نفْسِ گناه.<br/>',NULL,66322,1);
INSERT INTO stanza VALUES('F541','2','هیچ گونه تعلیم یا<br/>هیچ گونه رسوم،<br/>زنده نمی کند<br/>و یا دگرگون؛<br/>آن مسیحِ روح است<br/>که حیات بخشد،<br/>تا حیاتِ خدا<br/>از ما زیست شود.<br/>',NULL,66323,2);
INSERT INTO stanza VALUES('F541','3','نه فلسفه و یا<br/>هیچ گونه عنصر،<br/>شکل مسیح کند<br/>ما را، با او جور؛<br/>لیک این مسیح است که<br/>ذاتمان پوشید<br/>و در رستاخیزش<br/>ما را اعضا کرد.<br/>',NULL,66324,3);
INSERT INTO stanza VALUES('F541','4','هیچ مذهبی، حتی<br/>مسیحیت هم<br/>تحقق ندهد<br/>قصد خدا را؛<br/>همه و در همه،<br/>آن مسیح در ما،<br/>که خدا را راضی<br/>می کند تنها.<br/>',NULL,66325,4);
INSERT INTO stanza VALUES('F541','5','کل عطایا و<br/>آن عملکردها<br/>جایگزین نباشد<br/>بهرِ مسیحا.<br/>خودِ مسیح همه<br/>و در همه است!<br/>تنها خودِ مسیح<br/>در همه چیزها!<br/>',NULL,66326,5);
INSERT INTO stanza VALUES('F542','1','آه غنای منجیِ من،<br/>کاوش ناپذیر، عظیم؛<br/>کل پُریِ خدا را<br/>ما حال تجربه کنیم.<br/>',NULL,66327,1);
INSERT INTO stanza VALUES('F542','chorus','آه غنایش، آه غنایش،<br/>غنای مسیحْ به من!<br/>چه کاوش ناپذیر است، لیک،<br/>هست واقعیتِ من!<br/>',NULL,66328,2);
INSERT INTO stanza VALUES('F542','2','آه غنای منجیِ من،<br/>شاملِ نور و حیات،<br/>حکمت، قدرت، شفا، راحت،<br/>گنجی از لطف خدا؛<br/>',NULL,66329,3);
INSERT INTO stanza VALUES('F542','3','بازخرید، نجاتِ کامل،<br/>رستاخیزش با قدرت،<br/>و تقدیس و تجلیل کردن<br/>بیشتر شود هر ساعت!<br/>',NULL,66330,4);
INSERT INTO stanza VALUES('F542','4','آه غنای منجیِ من<br/>چیزی بجز خدا نیست!<br/>کل شخص و دارایی اش،<br/>در روح از آنِ من است.<br/>',NULL,66331,5);
INSERT INTO stanza VALUES('F542','5','آه غنای منجیِ من!<br/>کِه داند عرض و طول را،<br/>یا عمق و بلندای آن،<br/>لیک هست مسرت ما.<br/>',NULL,66332,6);
INSERT INTO stanza VALUES('F542','6','باشد آنها را شناسم<br/>در تجربه از مسیح؛<br/>با دیگران سهیم شوم<br/>در فراوانیِ آن.<br/>',NULL,66333,7);
INSERT INTO stanza VALUES('F546','1','عاشقِ خدا، نه با عشقِ خود،<br/>چون من هیچ ندارم؛<br/>عاشقتم، خدا، آن عشق از توست،<br/>چون با عشقت زِندَم.<br/>من مثلِ هيچم، و شادم باشم<br/>خالى شده، گم، غوطه ور در تو.<br/>',NULL,66334,1);
INSERT INTO stanza VALUES('F546','2','خدا، تنها تویی نيازمان،<br/>و هيچ چيز دگر نيست؛<br/>از تو نهرهاى سعادت جاريست،<br/>در تو اند سعیدان.<br/>چشمۀ حيات و وفورِ فيض،<br/>منشأ و مركز و مسكن مان.<br/>',NULL,66335,2);
INSERT INTO stanza VALUES('F548','1','از خاک، ظرف ساخته شدم،<br/>مسیح است گنجینه ام؛<br/>حاویِ او باشم من،<br/>و او محتوای من.<br/>',NULL,66336,1);
INSERT INTO stanza VALUES('F548','2','به شکلش ساخته شدم،<br/>مسیح در بر گیردم؛<br/>پس خدا داد ظرف را شکل<br/>با محتوای هم شکل.<br/>',NULL,66337,2);
INSERT INTO stanza VALUES('F548','3','او در روحم می ماند،<br/>با قدرت نگه دارد؛<br/>او چون روحْ با من یکیست،<br/>او واقعیتم است.<br/>',NULL,66338,3);
INSERT INTO stanza VALUES('F548','4','روزانه در حرْکت است<br/>با من درآمیخته است،<br/>گامهایم تنظیم کند،<br/>هر بخش را اشباع کند.<br/>',NULL,66339,4);
INSERT INTO stanza VALUES('F548','5','ابراز او از درون،<br/>نمایان به دیگران،<br/>شفاف باید باشم من<br/>تا ابراز شود از من.<br/>',NULL,66340,5);
INSERT INTO stanza VALUES('F548','6','نیازم دگرگونی ست،<br/>شکستنِ بیشتری ست،<br/>گِل تغییرِ شکل دهد،<br/>چون گنجینه اش شود.<br/>',NULL,66341,6);
INSERT INTO stanza VALUES('F551','1','کلام را باور دارم،<br/>هللویاه بر برّه!<br/>صحنِ بیرونی گذشت،<br/>آه جلال بر خدا!<br/>جانبِ عیسی هستم،<br/>بر مذبح تقدیس شدم،<br/>به دنیا، گناه، مُردم،<br/>هللویاه بر برّه!<br/>',NULL,66342,1);
INSERT INTO stanza VALUES('F551','chorus','هللویاه! هللویاه!<br/>از پرده که پاره شد<br/>رَد شدم، جلال اینجاست،<br/>هللویاه! هللویاه!<br/>در حضور پادشاه زیست می کنم.<br/>',NULL,66343,2);
INSERT INTO stanza VALUES('F551','2','شاه، کاهن بهرِ خدام،<br/>هللویاه بر برّه!<br/>با شسته شدن با خون،<br/>آه  جلال بر خدا!<br/>با نیرو و نورِ روح<br/>زیست کنم من شب و روز،<br/>در نورِ مکانِ قدس،<br/>هللویاه بر برّه!<br/>',NULL,66344,3);
INSERT INTO stanza VALUES('F551','3','پردۀ بیرون گذشت،<br/>هللویاه بر برّه!<br/>پنهان بود نورِ خدا،<br/>آه جلال بر خدا!<br/>لیک خون وارد کرد مرا<br/>به تقدسِ خدا،<br/>نیست اینجا مرگ و گناه،<br/>هللویاه بر برّه!<br/>',NULL,66345,4);
INSERT INTO stanza VALUES('F551','4','در قدس الاقداس هستم،<br/>هللویاه بر برّه!<br/>پردۀ درون گذشت،<br/>آه جلال بر خدا!<br/>تقدیس کرد خدا مرا<br/>با قدرت همان خون،<br/>حال مسکن من خداست،<br/>هللویاه بر برّه!<br/>',NULL,66346,5);
INSERT INTO stanza VALUES('F554','1','از نو به حضورش آيم،<br/>چون شب گذشت و صبح بیايد؛<br/>صورتش بينم كه بر من تابد<br/>خدا در من طلوع كند.<br/>با من حرف زند، برمن فاش كند<br/>غنایش بهرِ من امروز؛<br/>و با شوق از او بهره مى برم،<br/>گشنگى ام رفع شده.<br/>',NULL,66347,1);
INSERT INTO stanza VALUES('F554','2','چون روح، حرف زند از كلام<br/>تا قلبم در بازتاب بخواند،<br/>چشمۀ حيات با فيض و قدرت<br/>درونِ جانم مى جهد.<br/>با من حرف زند، برمن فاش كند<br/>غنایش بهرِ من امروز؛<br/>و نوشم از او بهرِ هر نياز،<br/>تشنگى ام رفع شده.<br/>',NULL,66348,2);
INSERT INTO stanza VALUES('F554','3','با دلسوزى برخورد كند،<br/>وقتى شاد مانم در حضورش؛<br/>و جانم اشباع و تأمين كند<br/>با همهْ ذاتِ نفيسش.<br/>با من حرف زند، برمن فاش كند<br/>غنایش بهرِ من امروز؛<br/>و از هر جهت دريافتش كنم،<br/>مشكلاتم رفع شده.<br/>',NULL,66349,3);
INSERT INTO stanza VALUES('F564','1','آموختم رازِ شگرفِ<br/>ماندنْ در خداوند را؛<br/>چشيدم چشمۀ حيات،<br/>مى نوشم كلامش را؛<br/>يافتم قوت و شيرينی<br/>در ماندنْ زيرِ خون را؛<br/>گم كردم خود را در عيسى،<br/>فرو رَوم در خدا.<br/>',NULL,66350,1);
INSERT INTO stanza VALUES('F564','chorus','من مى مانم در خدا<br/>و ایمان در كلامش؛<br/>نهفته ام در آغوشِ عشقِ او،<br/>آرى، مانَم در خدا<br/>و ایمان در كلامش،<br/>نهفته ام در آغوشِ عشقِ او.<br/>',NULL,66351,2);
INSERT INTO stanza VALUES('F564','2','من مصلوب شدم با عيسى،<br/>با من ساكن و زندَست؛<br/>از تقلا دست کشیدم،<br/>دگر من نيستم، ليک اوست.<br/>اراده ام تسليمِ اوست،<br/>روحش در من حكم فرماست؛<br/>خونِ نفيسش هر لحظه<br/>پاکی و رهاییم است.<br/>',NULL,66352,3);
INSERT INTO stanza VALUES('F564','3','مرضهایم را آورم،<br/>او متحمل شود؛<br/>ترس و غمهام به او گويم،<br/>و هر کاری که دارم،<br/>قوتم از عيسى گيرم،<br/>زنده ام از نفَسَش؛<br/>حتی ذهنش به من دهد،<br/>ايمان، حيات و عشقش.<br/>',NULL,66353,4);
INSERT INTO stanza VALUES('F564','4','بهرِ كلامم حكمتش،<br/>بهرِ كار، قدرتِ روح؛<br/>بهرِ راهم حضور او<br/>پناه و راهنمايم.<br/>او سهمِ قلبم مى باشد<br/>و سرچشمۀ شاديم؛<br/>منجى، تقديس و شفا ده،<br/>شکوهمند، شاهِ در راه.<br/>',NULL,66354,5);
INSERT INTO stanza VALUES('F569','1','هر روز تنها اعتماد؛<br/>اعتماد در طوفانها؛<br/>حتی با ایمانِ کم،<br/>اعتماد کن به عیسی.<br/>',NULL,66355,1);
INSERT INTO stanza VALUES('F569','chorus','اعتماد در لحظه ها،<br/>اعتماد کلِ روزها،<br/>اعتماد هر چه شود،<br/>اعتماد کن به عیسی.<br/>',NULL,66356,2);
INSERT INTO stanza VALUES('F569','2','روحش روشن درخشد<br/>در این قلب بینوا؛<br/>چون او هدایت کند،<br/>اعتماد کن به عیسی.<br/>',NULL,66357,3);
INSERT INTO stanza VALUES('F569','3','بِسرای در طیِ راه،<br/>دعا کن در راهِ سخت؛<br/>بخوان نامش هرکجا،<br/>اعتماد کن به عیسی.<br/>',NULL,66358,4);
INSERT INTO stanza VALUES('F569','4','اعتماد باقیِ عمر،<br/>اعتماد تا به پایان،<br/>تا ظهورش پرجلال،<br/>اعتماد کن به عیسی.<br/>',NULL,66359,5);
INSERT INTO stanza VALUES('F578','1','اراده و قوتم سُست،<br/>اميدم تقريباً تمام؛<br/>اما اعتمادم به توست،<br/>حفظ و هدايتم كنى.<br/>حفظ و هدايتم كنی.<br/>',NULL,66360,1);
INSERT INTO stanza VALUES('F578','2','سعى كردم، لیک، باز افتادم،<br/>حتى چون قبل خطا كردم؛<br/>صبرت تنها اعتمادم،<br/>كه در كلامت بمانم.<br/>كه در كلامت بمانم.<br/>',NULL,66361,2);
INSERT INTO stanza VALUES('F578','3','هر وقت قلبم مغرور شود،<br/>چه نزديک به افتادنم؛<br/>جرأتِ فكر و عمل نيست،<br/>به هر ترتيب محتاجتم.<br/>به هر ترتيب محتاجتم.<br/>',NULL,66362,3);
INSERT INTO stanza VALUES('F578','4','منجى، قوت و سنگرم،<br/>خدايا، صورتت جويم؛<br/>گر ضعيف تر از ضعيفم،<br/>قوتم نيست بجز فيض ات.<br/>قوتم نيست بجز فيض ات.<br/>',NULL,66363,4);
INSERT INTO stanza VALUES('F582','1','چون با خداوندیم<br/>در نورِ کلامش،<br/>چه شکوهی در راه درخشد؛<br/>چون پیش بَریم قصدش،<br/>او در ما می ماند،<br/>هر که مطیع اعتماد کند.<br/>',NULL,66364,1);
INSERT INTO stanza VALUES('F582','chorus','اعتماد و<br/>اطاعت، این است راه<br/>بهرِ شادی درعیسی،<br/>مطیع اعتماد کن.<br/>',NULL,66365,2);
INSERT INTO stanza VALUES('F582','2','نه تیرِگیْ بالا،<br/>نه ابری در سَما،<br/>لبخندش دور کند آنها را؛<br/>نه شک و نه ترسی<br/>نه آه و نه اشکی،<br/>چون مطیع اعتماد کنیم ما.<br/>',NULL,66366,3);
INSERT INTO stanza VALUES('F582','3','نه باری حمل کنیم،<br/>نه غمی سهم بریم،<br/>چون سزای زحمت را دهد؛<br/>نه حزن و زیانی،<br/>نه اخم و نه سختی،<br/>گر مطیع اعتماد کنیم ما.<br/>',NULL,66367,4);
INSERT INTO stanza VALUES('F582','4','نتوان ثابت کرد<br/>شادکامیِ عشقش<br/>گر کل را بر مذبح نگْذاریم؛<br/>چون ابراز لطفش،<br/>شادیست که دهد به،<br/>مطیع و اعتماد کننده.<br/>',NULL,66368,5);
INSERT INTO stanza VALUES('F582','5','پس در مشارکت<br/>بر پایش نشینیم،<br/>در راه، در کنارش راه رَویم؛<br/>حرفش اجرا کنیم؛<br/>چون فرستد، رَویم،<br/>نترس، اطاعت، اعتماد کن.<br/>',NULL,66369,6);
INSERT INTO stanza VALUES('F591','1','من نه، مسیح حرمت و عزت شود،<br/>من نه، مسیح دیده، شنیده شه.<br/>من نه، مسیح در هر نگاه و کاری،<br/>من نه، مسیح در هر فکر و کلام.<br/>',NULL,66370,1);
INSERT INTO stanza VALUES('F591','chorus','آه، باشد از خود نجات یابم،<br/>آه، در تو غرق شوم،<br/>تا که دگر من نباشم،<br/>اما مسیح در من.<br/>',NULL,66371,2);
INSERT INTO stanza VALUES('F591','2','من نه، مسیح در رنج تسلی دهد،<br/>من نه، مسیح اشکها را پاک کند.<br/>من نه، مسیح بارها را بلند کند،<br/>من نه، مسیح ترس را از بین بَرَد.<br/>',NULL,66372,3);
INSERT INTO stanza VALUES('F591','3','مسیح، مسیح، نه هیچ حرف باطلی،<br/>مسیح، مسیح، نه سر و صدایی؛<br/>مسیح، مسیح، نه هیچ خود بزرگ بینی،<br/>مسیح، مسیح، بدون هیچ نفْسی.<br/>',NULL,66373,4);
INSERT INTO stanza VALUES('F591','4','من نه، مسیح نیازها را رفع کند،<br/>من نه، مسیح قوت و بُنیه ام؛<br/>مسیح، بهرِ روح و روان و بدن،<br/>مسیح، زیست کن حیاتت را در من.<br/>',NULL,66374,5);
INSERT INTO stanza VALUES('F591','5','مسیح، مسیح، نگاهم را پُر کند،<br/>جلالِ فوق العاده خواهم دید؛<br/>مسیح آرزوها را اجرا کند،<br/>مسیح، مسیح، همه چیزم باشد.<br/>',NULL,66375,6);
INSERT INTO stanza VALUES('F593','1','مِلکِ من در آدم مرگ و گناه است،<br/>در مسیح وارثِ حیات، صداقت؛<br/>چون در جسم باشم آدم ابراز شود،<br/>چون  در روح باشم مسیح اظهار شود.<br/>',NULL,66376,1);
INSERT INTO stanza VALUES('F593','2','با اینکه در آدم گناه نکنم،<br/>گناهکاری محکوم به مرگ هستم من؛<br/>نیاز به درستیم نیست چون در مسیح<br/>صالح و عادل شمرده می شوم.<br/>',NULL,66377,2);
INSERT INTO stanza VALUES('F593','3','در جسم لازم نیست که تقلا کنم<br/>تا گناه، ذاتِ آدم را فاش سازم؛<br/>در روح لازم نیست سعی و تلاش کنم،<br/>در روح چون او زیست کنم و حکم رانم.<br/>',NULL,66378,3);
INSERT INTO stanza VALUES('F593','4','در مرگ با مسیح، از آدم آزادم،<br/>با مسیح حیاتِ تازه گرفتم!<br/>بی توجه به جسم، فعال نشود،<br/>توجه به روح، حیاتِ الهی ست.<br/>',NULL,66379,4);
INSERT INTO stanza VALUES('F593','5','توجه به روح، نجات خدا است،<br/>توجه به روح، ابراز مسیح است؛<br/>توجه به روح، ما غلبه کنیم،<br/>توجه به روح، در میدان می دویم.<br/>',NULL,66380,5);
INSERT INTO stanza VALUES('F593','6','توجه به روح، صلیب را شناسیم،<br/>قدرت رستاخیز را جاری کنیم؛<br/>توجه به روح، مسیح از من تابد،<br/>و حیاتش در درون بالغ شود.<br/>',NULL,66381,6);
INSERT INTO stanza VALUES('F593','7','در روح، مسیح حیات و همه چیزم،<br/>قوت و برْکتِ شاملِ تمام؛<br/>زیستن در روح، اثبات قدوسیت،<br/>خدای سه-یکتا در من کار کند.<br/>',NULL,66382,7);
INSERT INTO stanza VALUES('F595','1','همیشه چیزی بیشتر هست،<br/>چون خداوند را چشیم؛<br/>هر جامی را که پُر کند،<br/>غنی، سرشار می شود.<br/>چیزی اندک و یا محدود<br/>از انبارش نیاید؛<br/>به خودی، کامل می بخشد،<br/>سرشار و تا به ابد،<br/>به خودی، کامل می بخشد،<br/>سرشار و تا به ابد.<br/>',NULL,66383,1);
INSERT INTO stanza VALUES('F595','2','همیشه چیزی بیشتر هست،<br/>چون از دست پدر، ما،<br/>شکرگزار، سهمِ خود گیریم،<br/>و ستاییم طرحش را.<br/>رضایت، عمیق و کامل،<br/>بهرِ نیازهای ما،<br/>قلبی که عیسی را چشد،<br/>گیرد رضایتش را.<br/>قلبی که عیسی را چشد،<br/>گیرد رضایتش را.<br/>',NULL,66384,2);
INSERT INTO stanza VALUES('F595','3','همیشه چیزی بیشتر هست،<br/>چون در عشق سهیم ایم ما؛<br/>با اعماقی بی پایان و<br/>با ارتفاعی زیاد.<br/>زبانِ انسان قادر نیست<br/>بگوید وصفِ او را.<br/>تنها با حیرت ستاییم،<br/>برْکت دهیم نامش را،<br/>تنها با حیرت ستاییم،<br/>برْکت دهیم نامش را.<br/>',NULL,66385,3);
INSERT INTO stanza VALUES('F602','1','چه پرجلال و چه قدوس!<br/>خداست حیاتِ جاوْدان!<br/>پُر، نامحدود و قدرتمند،<br/>پاک و رحیم و تابان!<br/>غنایش در حیاتِ اوست،<br/>کلِ ذات، عشق و نورش.<br/>',NULL,66386,1);
INSERT INTO stanza VALUES('F602','2','چه پر محبت و پر فیض!<br/>خداست حیاتِ انسان!<br/>او بهرِ اجرای طرحش.<br/>روح را سِرِشت در انسان.<br/>خواست و آرزویش اینکه<br/>دریافتش کند انسان.<br/>',NULL,66387,2);
INSERT INTO stanza VALUES('F602','3','چه عشق و فیض بی حدی!<br/>حیاتْ جاریست در انسان!<br/>خدا چون رازی پنهان نیست،<br/>لیک خود را داده نشان،<br/>اول در جسم، سپس در روح<br/>او خود را کرد شناسان.<br/>',NULL,66388,3);
INSERT INTO stanza VALUES('F602','4','چه نزدیک و چه مهیا!<br/>خداست حیات در مسیح!<br/>خدا در مسیح جسم پوشید،<br/>تا انسان او را بیند.<br/>مُرد و برخاست و وارد شد<br/>در انسان، حیات باشد.<br/>',NULL,66389,4);
INSERT INTO stanza VALUES('F602','5','چه عجیب است! خدا چون روح<br/>حیاتِ انسان شده!<br/>خدا روحِ حیات بخش است،<br/>او خود را شناسانده؛<br/>حکم کند و الهام بخشد،<br/>در ما خانه اش سازد.<br/>',NULL,66390,5);
INSERT INTO stanza VALUES('F602','6','چه پرجلال و ارزشمند!<br/>شناختِ آن سه-یکتاست!<br/>پدر در آن پسر آمد،<br/>پسر در آن روح جاریست.<br/>چون روح درونِ ما آید،<br/>خدا چون حیات در ماست.<br/>',NULL,66391,6);
INSERT INTO stanza VALUES('F602','7','چه مرموز، اما واقعی!<br/>خدا درونم جاریست!<br/>در قلبم هست با من یکی،<br/>او حیاتِ من شده ست.<br/>هللویاه! هللویاه!<br/>کار من ستایش است!<br/>',NULL,66392,7);
INSERT INTO stanza VALUES('F608','1','عجب رازى، پدر و پسر و روح،<br/>سه در شخص، در وجود، همه يكی.<br/>چه با شكوه، خدا به درون آید<br/>تا از روح، در پسر با ما باشد!<br/>',NULL,66393,1);
INSERT INTO stanza VALUES('F608','chorus','خدا سه-يكتا، همه چيزِ ما!<br/>چه شگرفه! چه با شكوه!<br/>هديۀ الهى بى پايانه!<br/>چه عاليه! چه بى نظير!<br/>',NULL,66394,2);
INSERT INTO stanza VALUES('F608','2','منشأ غنى، پدر است سرچشمه،<br/>خواهد از ثروتش لذت بريم!<br/>آه اين سهم كه وسيع و بى پايانه<br/>حال بهرِ ماست براى هميشه!<br/>',NULL,66395,3);
INSERT INTO stanza VALUES('F608','3','چه شگرفه، پسر ابرازِ خداست،<br/>آمد در جسم، ساکن شد با انسان!<br/>بازخریدش كاملاً مؤثر است،<br/>ما مجرمين با او يكى شويم.<br/>',NULL,66396,4);
INSERT INTO stanza VALUES('F608','4','آن روح كه تبدیلِ شكلِ پسر است،<br/>حيات و تأمينِ كاملِ ماست.<br/>فوق العاده ست که روحِ ما با آن روح<br/>حال آمیخته و یکی شده است!<br/>',NULL,66397,5);
INSERT INTO stanza VALUES('F608','5','چه واقعیست، خدا روح است تا او را<br/>لمس و تجربه كنيم روز به روز!<br/>شگفت انگيز است با خدا يک روحيم<br/>و در حيات هيچ فرقى نداريم.<br/>',NULL,66398,6);
INSERT INTO stanza VALUES('F611','1','روح، ذات نفیسِ خداست،<br/>ذات قدوس و الهی؛<br/>بهرِ مسرت از خدا،<br/>باید روحش را لمس کنی.<br/>',NULL,66399,1);
INSERT INTO stanza VALUES('F611','2','روح درونی ترین بخش است،<br/>همان بخشِ اصیلِ ما؛<br/>برای تماس با خدا،<br/>باید به روح پردازیم ما.<br/>',NULL,66400,2);
INSERT INTO stanza VALUES('F611','3','پرستش به خواست پدر،<br/>به قوت روح است تنها؛<br/>روحش در روح ما آید،<br/>تا او یکی باشد با ما.<br/>',NULL,66401,3);
INSERT INTO stanza VALUES('F611','4','چون خوانَد روحش روحمان،<br/>در هم آمیخته، یک شوند؛<br/>روحمان خانۀ آن روح،<br/>آن روح، حیاتمان شود.<br/>',NULL,66402,4);
INSERT INTO stanza VALUES('F611','5','روحِ ما، روحش لمس کند،<br/>گر خواهیم کمالش شویم؛<br/>پس تنها با روح توانیم،<br/>خدا را پرستش کنیم.<br/>',NULL,66403,5);
INSERT INTO stanza VALUES('F611','6','در خدمت و مشارکت<br/>انسان را آوریم به روح؛<br/>تمام خدمت در دعاست،<br/>آن روح، پاسخ گوید به روح.<br/>',NULL,66404,6);
INSERT INTO stanza VALUES('F611','7','در روح، دعا، خدمت کنیم،<br/>در روح، حیاتش لمس کنیم،<br/>در روح، رشد، در روح، بسازیم،<br/>تا مسیح را بازتاب کنیم.<br/>',NULL,66405,7);
INSERT INTO stanza VALUES('F611','8','خداوند، به روح بازگردم<br/>تا با تو تماس بگیرم؛<br/>پس جاری و سرشار باشد،<br/>تا ابد روحمان با هم.<br/>',NULL,66406,8);
INSERT INTO stanza VALUES('F612','1','خدا می خواهد وجودش<br/>تأمینم باشد؛<br/>باید با او یکی شوم،<br/>نزدیک در روح.<br/>',NULL,66407,1);
INSERT INTO stanza VALUES('F612','chorus','وجود و غنای خدا<br/>لبریز است در روح؛<br/>باید روحم تمرین دهم<br/>تا پی بَرَم.<br/>',NULL,66408,2);
INSERT INTO stanza VALUES('F612','2','کلِ غنای ذاتِ خود<br/>را به من داده؛<br/>در روح او را لمس کنم تا<br/>این را بینم.<br/>',NULL,66409,3);
INSERT INTO stanza VALUES('F612','3','با ذهن، او را درک می کنیم،<br/>با روح، لمس کنیم؛<br/>گر روح را بکار نبریم،<br/>کمبود داریم.<br/>',NULL,66410,4);
INSERT INTO stanza VALUES('F612','4','چون به پیامها گوش کنم،<br/>دعا می کنم؛<br/>پس کلام را هضم خواهم کرد<br/>در وجودم.<br/>',NULL,66411,5);
INSERT INTO stanza VALUES('F612','5','در مطالعۀ کلام،<br/>لمس کنم خدا؛<br/>گر در ذهن باشم، نه در روح،<br/>مُرده ست کلام.<br/>',NULL,66412,6);
INSERT INTO stanza VALUES('F612','6','چه غنایی، چه جلالی<br/>در روح درخشد!<br/>چون روحم را تمرین دهم،<br/>آن، از من است.<br/>',NULL,66413,7);
INSERT INTO stanza VALUES('F626','1','زیتون های نافشرده<br/>روغن ندهند؛<br/>انگورها چَرخُشت نشده،<br/>با مِی جاری نشوند؛<br/>سُنبل های لِه نشده<br/>عطر پخش نکنند.<br/>از رنج که مقدر شده<br/>آیا گریزان باشم؟<br/>',NULL,66414,1);
INSERT INTO stanza VALUES('F626','chorus','هر ضربۀ رنج<br/>هست به نفع من.<br/>جای هرچه که بگیری<br/>دهی خودت را به من.<br/>',NULL,66415,2);
INSERT INTO stanza VALUES('F626','2','آیا تارهای قلب من<br/>باید کِش آیند؟<br/>تا آهنگی الهی و<br/>سازی خوشایند زنَد؟<br/>خدا، از فقر نترسم<br/>گر تو را دهد؛<br/>کاملاً تسلیم خواهم شد<br/>عشقت نمایان شود.<br/>',NULL,66416,3);
INSERT INTO stanza VALUES('F626','3','شرمسارم، خداوند، چون از<br/>خود دفاع کنم؛<br/>با اینکه عشقت پاک کند،<br/>لیک اینطور ناچار شدم.<br/>خداوند، طبقِ مِیلِ خود<br/>کار کن روی من؛<br/>برای خشنودیِ خود،<br/>نه چون احساساتِ من.<br/>',NULL,66417,4);
INSERT INTO stanza VALUES('F626','4','گر ذهنم خلافت باشد،<br/>پیشْ بَر راهِ خود؛<br/>اراده ات هرچه باشد،<br/>دلِ من «آری» گوید!<br/>مشتاقم خشنودت سازم،<br/>هر باختی باشد؛<br/>چون دلخوشی و جلالت<br/>در تابِ صلیب باشد.<br/>',NULL,66418,5);
INSERT INTO stanza VALUES('F626','5','آه، ستایم، حتی با غم<br/>در آوازِ من.<br/>بهرِ لطفِ افزونت شکر<br/>و ستایش کنم من.<br/>تو با ارزش تر از همه<br/>هستی بهرِ من:<br/>خداوند، زیاد شو، من کم<br/>همین است خواهشِ من.<br/>',NULL,66419,6);
INSERT INTO stanza VALUES('F631','1','قدرتِ قيامِ مسيح،<br/>در عشقْ به صليبِ اوست؛<br/>تنها از مرگ خیزد حيات؛<br/>كسب، جز از دست دادن نیست.<br/>',NULL,66420,1);
INSERT INTO stanza VALUES('F631','chorus','مرگ بهرِ حيات،<br/>مرگ بهر حيات؛<br/>تنها از مرگ خيزد حيات؛<br/>مرگ بهر حيات.<br/>',NULL,66421,2);
INSERT INTO stanza VALUES('F631','2','بهر شکل گیریِ مسيح،<br/>نفَسِ آخر كِشم،<br/>در سايۀ صليب مانم،<br/>حياتِ نفْسم كُشم.<br/>',NULL,66422,3);
INSERT INTO stanza VALUES('F631','3','گر خدا از روحِ جاوید<br/>با او ميخكوبم كند؛<br/>آنگاه که مرگ كار مى كند<br/>حياتش جارى شود.<br/>',NULL,66423,4);
INSERT INTO stanza VALUES('F639','1','مرگ نتواند بازدارد قيام،<br/>حياتِ جاوْدانِ خدا پیداست؛<br/>آن، نامخلوق و فناناپذير،<br/>آن، ابرازِ مسيحِ پيروز است.<br/>',NULL,66424,1);
INSERT INTO stanza VALUES('F639','2','مرگ نتواند بازدارد قيام،<br/>گرچه قدرتش بر ضد آن است،<br/>مرگ فقط آن را فرصت مى دهد<br/>تا نشان دهد قدرت حيات.<br/>',NULL,66425,2);
INSERT INTO stanza VALUES('F639','3','مرگ نتواند بازدارد قيام،<br/>هر چه مدفون، بيشتر تكثير شود؛<br/>هر رنجى باعث رُشدش شود،<br/>ميوۀ حيات به ثمر آرَد.<br/>',NULL,66426,3);
INSERT INTO stanza VALUES('F639','4','مرگ نتواند بازدارد قيام،<br/>هر سد و مانعى را شكنَد؛<br/>غالب بر قدرت ظلمت و مرگ،<br/>مرگ را بَلعَد، ظفر سهیم شود.<br/>',NULL,66427,4);
INSERT INTO stanza VALUES('F639','5','مرگ نتواند بازدارد قیام،<br/>پُری خدا را فاش خواهد کرد؛<br/>صداقت و قدوسیت آرَد،<br/>شکل خدا از آن ابراز شود.<br/>',NULL,66428,5);
INSERT INTO stanza VALUES('F639','6','باشد شناسم حیاتِ قیام،<br/>در هر مرگ قدرتش بیرون ریزد،<br/>در تجربه دائم پی برم که<br/>این حیات، خودِ مسیحِ زندَست.<br/>',NULL,66429,6);
INSERT INTO stanza VALUES('F643','1','زمان با او صرف کن،<br/>به خدا بگو،<br/>دائم در او بمان،<br/>کلامش غذاست.<br/>صبر کن در حضورش،<br/>تسلیم و آرام،<br/>جویای برْکتش<br/>در همه چیزها.<br/>',NULL,66430,1);
INSERT INTO stanza VALUES('F643','2','زمان با او صرف کن،<br/>گذَرَد دنیا؛<br/>وقت صرف کن در پنهان<br/>با عیسی تنها.<br/>بنگر بر عیسی تا<br/>مثل او شَوی؛<br/>و دیگران در تو<br/>شکلش را بینند.<br/>',NULL,66431,2);
INSERT INTO stanza VALUES('F643','3','زمان با او صرف کن،<br/>هدایت کند؛<br/>از او جدا نشو<br/>هر آنچه شود؛<br/>در شادی یا اندوه<br/>با خدا بمان،<br/>چشمانت بر عیسی،<br/>امید در کلام.<br/>',NULL,66432,3);
INSERT INTO stanza VALUES('F643','4','زمان با او صرف کن،<br/>آرام باش در جان،<br/>هر فکر و مشکلی<br/>به او واگذار.<br/>هدایت شو در روح<br/>به منبعِ عشق،<br/>تا سپس گواهِ<br/>رحمتش باشی.<br/>',NULL,66433,4);
INSERT INTO stanza VALUES('F645','1','ای جان، خسته و آشفته ای؟<br/>نبینی نور در تاریکی؟<br/>نور هست بهرِ دیدنِ منجی،<br/>حیات، غنی و مجانی.<br/>',NULL,66434,1);
INSERT INTO stanza VALUES('F645','chorus','چِشم بِدوز سویِ عیسی،<br/>بنگر بر روی شگرفش،<br/>امورِ زمین عجب تار شود،<br/>در آن نورِ جلال و فیضش.<br/>',NULL,66435,2);
INSERT INTO stanza VALUES('F645','2','از مرگ به حیاتِ جاوید رفت،<br/>و ما به همراهش آنجا؛<br/>گناه هیچ بر ما حکمفرما نیست<br/>چون بیش از پیروزمندیم ما!<br/>',NULL,66436,3);
INSERT INTO stanza VALUES('F645','3','کلامش بی وفا نیست، قول داد؛<br/>با ایمان همه چیز نیکوست؛<br/>به دنیای در حالِ مرگ رو،<br/>نجاتِ کاملش بگو!<br/>',NULL,66437,4);
INSERT INTO stanza VALUES('F686','1','«نترس، من با تو ام»؛<br/>پرتویِ مبارک،<br/>ستارۀ جلال،<br/>نورِ راهِ من!<br/>لایِ ابرهای شب،<br/>این وعده تابَد:<br/>«تنهایت نگْذارم،<br/>تنها نگْذارم تو را.»<br/>',NULL,66438,1);
INSERT INTO stanza VALUES('F686','chorus','نه هرگز تنها،<br/>نه هرگز تنها؛<br/>او وعده داد که هرگز<br/>تنها نگْذارد مرا؛<br/>نه هرگز تنها،<br/>نه هرگز تنها؛<br/>او وعده داد که هرگز<br/>تنها نگْذارد مرا.<br/>',NULL,66439,2);
INSERT INTO stanza VALUES('F686','2','گلِ رُز بِخُشکد،<br/>سوسن ها هم نیز،<br/>نورِ زمین مَحو شد<br/>لیک پُر نور سَماست!<br/>عیسی، آن گلِ حنا،<br/>بهرِ ما شکوفاست،<br/>عیسی، نورِ سَما،<br/>تنها نگْذارد مرا.<br/>',NULL,66440,3);
INSERT INTO stanza VALUES('F686','3','پله های نادیده،<br/>به خطرْ نزدیک؛<br/>منجی، لیک، نزدیک تر،<br/>نجوا کند: «شاد باش»؛<br/>شادی چون مرغِ بهار،<br/>به دل پرواز کرده،<br/>با نغمه ای شیرین:<br/>«تنها نگْذارد مرا.»<br/>',NULL,66441,4);
INSERT INTO stanza VALUES('F717','1','آه شادی کنیم در خدا همیشه،<br/>گرچه اطراف پُر از مشکل است،<br/>گرچه سیلِ رنج چون دریا خروشد،<br/>خواندن بهتر از نالیدن است.<br/>',NULL,66442,1);
INSERT INTO stanza VALUES('F717','chorus','پس دائم شادی کن، دائم شادی کن،<br/>چه بهتر است خواندن از نالیدن:<br/>چه بهتر است زندگی از مردن؛<br/>پس دائماً شادی کنیم.<br/>',NULL,66443,2);
INSERT INTO stanza VALUES('F717','2','آه شادی کنیم در خدا همیشه،<br/>وقتی تیر پرتاب کند دشمن؛<br/>زیرا شیطان هنوز هم  می هراسد،<br/>از خواندن بیشتر از نالیدن.<br/>',NULL,66444,3);
INSERT INTO stanza VALUES('F717','3','آه شادی کنیم در خدا همیشه،<br/>حتی در هنگامِ ناخوشی؛<br/>هیچ چیز چون شادی ترمیم  نمی کنه،<br/>چون سرچشمۀ شفاست شادی.<br/>',NULL,66445,4);
INSERT INTO stanza VALUES('F723','1','او بیشتر فیض دهد چون بار سنگین شود،<br/>قوتْ بیش دهد چون زحمتْ بیش شود،<br/>در رنجِ بیشتر، رحمتش را رِسانَد،<br/>در سختیها، آرامش بیفزاید.<br/>',NULL,66446,1);
INSERT INTO stanza VALUES('F723','2','وقتی ما تحمل مان تمام شود،<br/>وقتی قوتمان به آخر رسد،<br/>وقتی به تَهِ ذخیره ها رسیدیم،<br/>بخششِ پدر ما آغاز شود.<br/>',NULL,66447,2);
INSERT INTO stanza VALUES('F723','3','عشقش نامحدود است، فیضش بیکران است،<br/>قوت و قدرتش حدی ندارد،<br/>چون از غنای بیشمارَش در عیسی،<br/>او بخشد و بخشد و باز می بخشد.<br/>',NULL,66448,3);
INSERT INTO stanza VALUES('F724','1','پرنده ای کوچک،<br/>دور از جوّ و هوا،<br/>در قفس سَرایم از او<br/>که نهادم آنجا؛<br/>از اسارتم خشنودم،<br/>چون تو خشنودی، ای خدا.<br/>',NULL,66449,1);
INSERT INTO stanza VALUES('F724','2','کاری بیش ندارم،<br/>کل روز سَرایم؛<br/>او که لبخندش را جویم<br/>گوش می دهد به من؛<br/>بالِ سرگردانم بسته،<br/>به سرودم گوش سپرده.<br/>',NULL,66450,2);
INSERT INTO stanza VALUES('F724','3','تو با عشق و برْکت،<br/>به من گوش سپردی؛<br/>گرچه نوایم نارام است،<br/>هنوز گوش می دهی؛<br/>چونکه می دانی از عشق است،<br/>وحیِ عشق است، هر سرودی.<br/>',NULL,66451,3);
INSERT INTO stanza VALUES('F724','4','قفس گرداگردم،<br/>بیرون پَر نکشم؛<br/>با اینکه در بند است بالم،<br/>لیک دلم هست رها؛<br/>چون حبس نتواند گیرد<br/>پرواز، رهاییِ جان را.<br/>',NULL,66452,4);
INSERT INTO stanza VALUES('F724','5','پرواز نیک است بالا،<br/>فرای زنجیرها!<br/>که مشیتِ الهی،<br/>ستایَم قصدت را؛<br/>و در اراده ات یابم<br/>شادی، آزادیِ ذهن را.<br/>',NULL,66453,5);
INSERT INTO stanza VALUES('F737','1','حیاتِ ابدی،<br/>مشارکتش،<br/>مشارکت در روح،<br/>رها از تلاش.<br/>',NULL,66454,1);
INSERT INTO stanza VALUES('F737','2','حیاتِ ابدی،<br/>مشارکتش،<br/>خداوند چون روح است<br/>در پیوند با ما.<br/>',NULL,66455,2);
INSERT INTO stanza VALUES('F737','3','زندگی در روح است<br/>این مشارکت؛<br/>مشارکت در روح،<br/>فیض می افزاید.<br/>',NULL,66456,3);
INSERT INTO stanza VALUES('F737','4','توسط حیات،<br/>اشتراک داریم؛<br/>مشارکت در روح،<br/>در نور می آییم.<br/>',NULL,66457,4);
INSERT INTO stanza VALUES('F737','5','در ظاهر پاک شدن،<br/>با مشارکت؛<br/>و محصول آن از<br/>مسحِ در درون.<br/>',NULL,66458,5);
INSERT INTO stanza VALUES('F737','6','عمقِ مشارکت<br/>با مرگ بر صلیب؛<br/>والاتر شود با<br/>نفَسِ آن روح.<br/>',NULL,66459,6);
INSERT INTO stanza VALUES('F737','7','مشارکت ما را<br/>از نفْس رهانَد؛<br/>و درونِ خدا<br/>ما را آورَد.<br/>',NULL,66460,7);
INSERT INTO stanza VALUES('F738','1','یک حسِ حیات برای<br/>هر نوع حیاتی هست؛<br/>حیاتِ ابدی در ما<br/>حسِ الهی است.<br/>',NULL,66461,1);
INSERT INTO stanza VALUES('F738','2','حیات هر چه برتر باشد،<br/>حسِ آن بهتر است؛<br/>حیاتِ الهی والاست،<br/>حس اش قوی تر است.<br/>',NULL,66462,2);
INSERT INTO stanza VALUES('F738','3','این آن حسِ حیات در ماست،<br/>همان حسِ خداست؛<br/>در روحِ ما زنده شود،<br/>بیش از حسِ خوب است.<br/>',NULL,66463,3);
INSERT INTO stanza VALUES('F738','4','این حسِ درونی در ماست،<br/>آگاهیِ نهان،<br/>از درون تشخیص می دهد<br/>خواست خداوند را.<br/>',NULL,66464,4);
INSERT INTO stanza VALUES('F738','5','با حسِ حیاتِ درون،<br/>شناسیم خدا را؛<br/>قوی است و ناخودآگاه،<br/>بدون تقلا.<br/>',NULL,66465,5);
INSERT INTO stanza VALUES('F738','6','هر چه در حیات رشد کنیم،<br/>این حس بیشتر شود؛<br/>چون در حیات گام برداریم،<br/>آن شدیدتر شود.<br/>',NULL,66466,6);
INSERT INTO stanza VALUES('F738','7','روحمان شهامت گیرد<br/>با تمرینِ آن حس،<br/>و با این حسِ خداست که<br/>مشارکت داریم.<br/>',NULL,66467,7);
INSERT INTO stanza VALUES('F743','1','خدا ما را چون ظرف خلق کرد<br/>ابرازش را کسب کند؛<br/>قلب داد تا عاشقش باشیم،<br/>روح داد برای دریافت.<br/>',NULL,66468,1);
INSERT INTO stanza VALUES('F743','2','از قلبمان دوستش داریم،<br/>و در روح او را داریم،<br/>از حیاتش برخورداریم،<br/>تا او را ابراز کنیم.<br/>',NULL,66469,2);
INSERT INTO stanza VALUES('F743','3','شیطان قلبمان فاسد کرد،<br/>و روحمان را مرده،<br/>تا خدا را لمس نکنیم،<br/>ولی با نفْس زیست کنیم.<br/>',NULL,66470,3);
INSERT INTO stanza VALUES('F743','4','پس خداوند در نجاتش<br/>تازه کرد قلب و روح را،<br/>تا بازیابد عضوِ دریافت<br/>و محبتِ ما را.<br/>',NULL,66471,4);
INSERT INTO stanza VALUES('F743','5','با نوسازیِ قلب ماست<br/>که با عشق جویایش ایم،<br/>و در تازگیِ روح است<br/>که او را لمس می کنیم.<br/>',NULL,66472,5);
INSERT INTO stanza VALUES('F743','6','راست، خالص و تک، قلبِ ما<br/>باید باشد به خدا،<br/>فقیر در روح، دائم جویا<br/>جهت لمسِ خدا.<br/>',NULL,66473,6);
INSERT INTO stanza VALUES('F743','7','قلبمان در عشق نگه دار،<br/>روحمان را قوت ده،<br/>تا ما در تازگیِ روح<br/>لمس ات کنیم همواره.<br/>',NULL,66474,7);
INSERT INTO stanza VALUES('F744','1','در تماس با خدا، محتاج<br/>به قلبی پاک هستیم<br/>که در غنا و فیضِ او<br/>کامل سهیم باشیم.<br/>',NULL,66475,1);
INSERT INTO stanza VALUES('F744','2','قلبی خالص در همه چیز،<br/>و ذهنی پاک و راست،<br/>با ترس و لرز بهرِ فهمِ<br/>افکار و قلبِ اوست.<br/>',NULL,66476,2);
INSERT INTO stanza VALUES('F744','3','قلبی پرشور و مهربان،<br/>قلبی با عشقْ سوزان،<br/>با احساسی بیش از هر چیز<br/>بهرِ او جانفِشان.<br/>',NULL,66477,3);
INSERT INTO stanza VALUES('F744','4','قلبی راستین، رام و مطیع،<br/>اراده ای تسلیم،<br/>اراده ای نرم، لیک قوی،<br/>قصدش اجرا کنیم.<br/>',NULL,66478,4);
INSERT INTO stanza VALUES('F744','5','قلبی که محکوم نکند،<br/>و درست با خداست؛<br/>قلبی با وجدانی پاک که<br/>با خون پوشیده است.<br/>',NULL,66479,5);
INSERT INTO stanza VALUES('F744','6','خداوند، چنین قلبی دِه،<br/>متمرکز بر تو،<br/>و کامل از تو برخوردار<br/>بهرِ کمالِ تو.<br/>',NULL,66480,6);
INSERT INTO stanza VALUES('F745','1','خداوندا، حال روح هستی<br/>در روحم زیست کنی؛<br/>آن دو با هم یک روح شدند،<br/>که وحدت می بخشد.<br/>',NULL,66481,1);
INSERT INTO stanza VALUES('F745','2','خدا روحت با روحمان<br/>شهادت می دهد<br/>که فرزندان خداییم<br/>و وارث جلال.<br/>',NULL,66482,2);
INSERT INTO stanza VALUES('F745','3','لمس ات کنیم در روحمان،<br/>از غنایت مسرور،<br/>تو به عنوان روح، دهی<br/>خودت را بی عیار.<br/>',NULL,66483,3);
INSERT INTO stanza VALUES('F745','4','در روحمان می توانیم<br/>از پی ات راه رویم،<br/>تو چون روح، رهبری کنی<br/>و هر روز نور بخشی.<br/>',NULL,66484,4);
INSERT INTO stanza VALUES('F745','5','در روح، با روحت، خداوند،<br/>پرستش ات کنیم؛<br/>با قوتت، در روحِ ما،<br/>دائم قوت بخشی.<br/>',NULL,66485,5);
INSERT INTO stanza VALUES('F745','6','در روح، با روحت، خداوند،<br/>دعا تقدیم کنیم،<br/>تو روح در ما، ناله هایِ<br/>بیان ناشدنی.<br/>',NULL,66486,6);
INSERT INTO stanza VALUES('F745','7','به روحمان بازگشت کنیم،<br/>بهرِ تماس با تو؛<br/>در روح است که سهیم هستیم<br/>میراثِ الهی.<br/>',NULL,66487,7);
INSERT INTO stanza VALUES('F745','8','ای خداوند، چه وحدتی ست –<br/>دو روح درهم جفت اند!<br/>روحت در روحم زیست کند،<br/>روحم در تو مانَد!<br/>',NULL,66488,8);
INSERT INTO stanza VALUES('F750','1','قصد خدا اینکه ما را<br/>شکل پسرش كنه؛<br/>پس عملِ دگرگونى<br/>از روحْ بايد انجام شه.<br/>',NULL,66489,1);
INSERT INTO stanza VALUES('F750','chorus','خدا، ما را دگرگون كن<br/>در احساس، فكر، اراده؛<br/>با روحت ما را اشباع كن،<br/>وجودمان را پر كن.<br/>',NULL,66490,2);
INSERT INTO stanza VALUES('F750','2','خدا تولدِ تازه<br/>داد در روح، با حياتش؛<br/>لیک بايد فراتر رَوَد –<br/>در روان، با حياتش.<br/>',NULL,66491,3);
INSERT INTO stanza VALUES('F750','3','وسعت يابد از روحمان،<br/>دگرگون كند روان،<br/>نو کند از باطنمان،<br/>تا آرد تحتِ فرمان.<br/>',NULL,66492,4);
INSERT INTO stanza VALUES('F750','4','از راهِ قدرتِ روحش،<br/>دگرگونی به شکلش؛<br/>از جلالش تا جلالش<br/>سازد همشكلِ خودش.<br/>',NULL,66493,5);
INSERT INTO stanza VALUES('F750','5','دگرگون و تقديس كند،<br/>پخته شیم مثلِ خودش؛<br/>روان را تصرف کند،<br/>تا پایدار شه قامتش.<br/>',NULL,66494,6);
INSERT INTO stanza VALUES('F762','1','دعا بخورِ قلبِ مقدس،<br/>به خدا رِسَد از شکسته ها،<br/>شعله ور با نَفَسِ روح شود<br/>و با بالِ ایمان رَوَد بالا.<br/>',NULL,66495,1);
INSERT INTO stanza VALUES('F762','2','دعا عطر نهال های فیض است،<br/>گُلِ صبر، ایمان، عشقِ شکیبا؛<br/>گنجی «پر از رایحۀ شیرین»،<br/>خدا استنشاق کند عطرش را.<br/>',NULL,66496,2);
INSERT INTO stanza VALUES('F762','3','دعا بخارِ صعود کنندَه ست،<br/>که بارش های برْکت آوَرَد،<br/>نهرْ جاری شود در جاهای خشک<br/>تا صحرا با گل شکوفه کند.<br/>',NULL,66497,3);
INSERT INTO stanza VALUES('F762','4','دعا تلفنِ آسمانی ست،<br/>به زمین آوَرَد آسمان را،<br/>توانیم در قلب و گوشِ پدر<br/>درد دل کنیم، غرق شوند غم ها.<br/>',NULL,66498,4);
INSERT INTO stanza VALUES('F762','5','دعا چون تلگراف می فرستد<br/>تپشِ قلب را بر موجِ آسْمان؛<br/>قلب خدا را یابد و پاسخ<br/>به زمین بازگردد، عشق و ایمان.<br/>',NULL,66499,5);
INSERT INTO stanza VALUES('F762','6','دعا چون لولۀ زرینِ روح<br/>با روغن پر کند چراغ ها را،<br/>با یکدلی در صبر و دعا، روح<br/>پُر کند، و دِرخشند چراغ ها.<br/>',NULL,66500,6);
INSERT INTO stanza VALUES('F762','7','دعا نیروی زمین و سماست،<br/>دعا همان دینامیتِ خداست؛<br/>حرکت دهد دست خدا را،<br/>و بر زمین، چرخاندنِ چرخهاست.<br/>',NULL,66501,7);
INSERT INTO stanza VALUES('F762','8','دعا یاد دِه! دل ها را تکان دِه،<br/>تا شوقِ خودت جوشد در جان ها!<br/>در ما دعا کن، تا مسیحْ در ما<br/>دعا کند به مسیح در بالا!<br/>',NULL,66502,8);
INSERT INTO stanza VALUES('F762','9','دعا یادم دِه! خواستت را فاش کن،<br/>تا قصدت تِکانَد وجودم را!<br/>در ما دعا کن، تا خدا در ما<br/>پاسخ  دهد به خدا در بالا!<br/>',NULL,66503,9);
INSERT INTO stanza VALUES('F767','1','ياد دِه دعا کنیم تا ما<br/>دشمن را برانیم،<br/>قدرتِ شرير را بسته،<br/>اسيران رهانیم.<br/>',NULL,66504,1);
INSERT INTO stanza VALUES('F767','2','ياد ده دعا كرده، ايستيم<br/>بر روى نبردگاه،<br/>برای سنگر شكستن،<br/>عاجزىِ دشمن.<br/>',NULL,66505,2);
INSERT INTO stanza VALUES('F767','3','ياد ده دعا در قدرتت،<br/>دعاى حكم فرما،<br/>زيرِ خون، تا زمين لرزد<br/>و قُوای هوا.<br/>',NULL,66506,3);
INSERT INTO stanza VALUES('F767','4','با دعا و ايمان زحمت<br/>کِشیم، خدا با تو،<br/>بدانيم پيروزى از ماست<br/>و اقتدار از تو.<br/>',NULL,66507,4);
INSERT INTO stanza VALUES('F769','1','به قدس الاقداس آیم،<br/>به پرده داخل شوم؛<br/>بهرِ جریانِ حیات،<br/>تخت فیض را لمس کنم.<br/>',NULL,66508,1);
INSERT INTO stanza VALUES('F769','2','حال آن مقدس ترین،<br/>درون روح من است؛<br/>اینجا خدا در من و<br/>روحمان به هم وصل است.<br/>',NULL,66509,2);
INSERT INTO stanza VALUES('F769','3','به روحم باز می گردم،<br/>اینجا خدا را بینم؛<br/>آه که چقدر محشر است!<br/>او درون، کامل در من.<br/>',NULL,66510,3);
INSERT INTO stanza VALUES('F769','4','عطرِ رستاخیزِ او<br/>از روحِ من پخش شود؛<br/>گر در روح دعا کنم،<br/>مسیح آشکار می شود.<br/>',NULL,66511,4);
INSERT INTO stanza VALUES('F769','5','گر در روح لمس اش کنم،<br/>با غنایش پر شوم؛<br/>حیات، نور، عشق و فیض چون<br/>نهر از من جاری شود.<br/>',NULL,66512,5);
INSERT INTO stanza VALUES('F769','6','عمیق و غنی او را<br/>لمس و تجربه کنم،<br/>پس قانونِ حیات را<br/>لمس کرده، و مسح شوم.<br/>',NULL,66513,6);
INSERT INTO stanza VALUES('F769','7','در روحم خداوند را<br/>که دوست دارم، لمس کنم،<br/>در عمقِ نهانِ او<br/>منّای پنهان دارم.<br/>',NULL,66514,7);
INSERT INTO stanza VALUES('F769','8','چون حیاتِ رستاخیز<br/>بر من واقعی شود،<br/>چون عصای شکوفا<br/>قبول و تصدیق شوم.<br/>',NULL,66515,8);
INSERT INTO stanza VALUES('F769','9','اینجا از آن تختِ فیض،<br/>آبهای زنده جاریست<br/>که چون نهری پر فیض در<br/>درونم فیض می بخشد.<br/>',NULL,66516,9);
INSERT INTO stanza VALUES('F769','10','پس هر وقت دعا کنیم،<br/>روحمان تمرین دهیم؛<br/>روحمان آمیخته و<br/>چون کاهن خدمت کنیم.<br/>',NULL,66517,10);
INSERT INTO stanza VALUES('F769','11','در قدس الاقداس است که<br/>تماس گیریم با خدا،<br/>و تختش را لمس کنیم<br/>تا فیض اش ریزَد بر ما.<br/>',NULL,66518,11);
INSERT INTO stanza VALUES('F770','1','در قُدس الاقداس، لمس كن تختِ فيض،<br/>رودِ فيض جارى شود؛<br/>در قُدس الاقداس، لمس كن تختِ فيض،<br/>رودِ فيض جارى شود.<br/>',NULL,66519,1);
INSERT INTO stanza VALUES('F770','chorus','هللوياه! هللوياه!<br/>رودِ فيض جارى شود؛<br/>هللوياه! هللوياه!<br/>رودِ فيض جارى شود.<br/>',NULL,66520,2);
INSERT INTO stanza VALUES('F770','2','در قُدس الاقداس، رو به روى او،<br/>نورِ جلال از من تابد؛<br/>در قُدس الاقداس، رو به روی او،<br/>نورِ جلال از من تابد؛<br/>',NULL,66521,3);
INSERT INTO stanza VALUES('F770','chorus','هللوياه! هللوياه!<br/>نورِ جلال از من تابد؛<br/>هللوياه! هللوياه!<br/>نورِ جلال از من تابد.<br/>',NULL,66522,4);
INSERT INTO stanza VALUES('F770','3','سوىِ روح بچرخ، بخور بسوزان،<br/>لمس كن سرچشمۀ حيات؛<br/>سوىِ روح بچرخ، بخور بسوزان،<br/>لمس كن سرچشمۀ حيات.<br/>',NULL,66523,5);
INSERT INTO stanza VALUES('F770','chorus','هللوياه! هللوياه!<br/>لمس كن سرچشمۀ حيات،<br/>هللوياه! هللوياه!<br/>لمس كن سرچشمۀ حيات.<br/>',NULL,66524,6);
INSERT INTO stanza VALUES('F771','1','پرده پاره و باز شده<br/>راهی نو و زنده؛<br/>با جرأت از خونِ نفیس،<br/>نزدت دعا کنیم.<br/>',NULL,66525,1);
INSERT INTO stanza VALUES('F771','2','با بازخریدت می آییم<br/>در آن قدس الاقداس؛<br/>با روحت ما را مسح کنی،<br/>تخت فیض لمس کنیم.<br/>',NULL,66526,2);
INSERT INTO stanza VALUES('F771','3','تنها در روح دعا کنیم،<br/>با تو اِشغال شویم،<br/>تا مسیح از روحمان چون<br/>بخور ابراز شود.<br/>',NULL,66527,3);
INSERT INTO stanza VALUES('F771','4','فیض و رحمتت چون نهری<br/>از تخت جاری شود،<br/>به موقع تازه می کند<br/>چه دلگرمی دهد!<br/>',NULL,66528,4);
INSERT INTO stanza VALUES('F771','5','بهرِ نیاز نخواهیم، لیک<br/>با دعای روحت<br/>هر نیازی را می دانی،<br/>در مراقبتت.<br/>',NULL,66529,5);
INSERT INTO stanza VALUES('F771','6','زیر فشار غم و رنج<br/>مضطرب نشویم،<br/>همه را به تو بسپاریم،<br/>روح را آزاد کنیم.<br/>',NULL,66530,6);
INSERT INTO stanza VALUES('F771','7','باشد متمرکز باشم<br/>در مشارکتت،<br/>دعا، بخور اهدا کنم<br/>پیروی از روحت.<br/>',NULL,66531,7);
INSERT INTO stanza VALUES('F775','1','در نام قدیرِ عیسی،<br/>به تختش زانو زنیم،<br/>دشمن ها سرکوب می شوند،<br/>پیروزی حاصل کنیم.<br/>',NULL,66532,1);
INSERT INTO stanza VALUES('F775','chorus','نامِ تو! نامِ تو!<br/>در آن بَرنده ایم ما.<br/>نامِ تو! نامِ تو!<br/>غالب بر شر، مرگ، گناه.<br/>',NULL,66533,2);
INSERT INTO stanza VALUES('F775','2','با خواندنِ نام عیسی،<br/>شیطان فرار می کند.<br/>عیسی! عیسی! عزیزْ عیسی!<br/>در نامت پیروزی است.<br/>',NULL,66534,3);
INSERT INTO stanza VALUES('F775','3','بزودی آن لحظه آید<br/>نبَرد بَرَنده شود،<br/>نام قدیرِ عیسی ما<br/>را به تخت بالا بَرَد.<br/>',NULL,66535,4);
INSERT INTO stanza VALUES('F778','1','بخوان شعرِ ایمان،<br/>چه شب تاریک باشد؛<br/>حمد کن تا خدا ایمان را<br/>به دید تبدیل کند.<br/>',NULL,66536,1);
INSERT INTO stanza VALUES('F778','2','بخوان شعرِ ایمان،<br/>قلبت باشد قوی،<br/>خدا خشنود از ستایش<br/>در شبِ طولانی.<br/>',NULL,66537,2);
INSERT INTO stanza VALUES('F778','3','بخوان شعرِ ایمان،<br/>بهرِ دشمن دوری ست؛<br/>نگذار خموش کند شعر را،<br/>ستایش پیروزی ست.<br/>',NULL,66538,3);
INSERT INTO stanza VALUES('F778','4','بخوان شعرِ ایمان،<br/>آید سحرگاهان<br/>و ملاقاتِ خداوند<br/>با شعرِ بی پایان.<br/>',NULL,66539,4);
INSERT INTO stanza VALUES('F779','1','دعا کن یکدل و در روح،<br/>نه بر طبق ذهنمان،<br/>لیک تنها توسط مسح،<br/>چون خداوند هست خواهان.<br/>',NULL,66540,1);
INSERT INTO stanza VALUES('F779','chorus','دعا کن یکدل و در روح،<br/>نه بر طبق ذهنمان،<br/>لیک تنها توسط مَسح،<br/>چون خداوند هست خواهان.<br/>',NULL,66541,2);
INSERT INTO stanza VALUES('F779','2','دعا کن یکدل و در روح،<br/>با صلیب، خود انکار کن؛<br/>نیت ها، امیال را بگذار<br/>روح آرَد تحت فرمان.<br/>',NULL,66542,3);
INSERT INTO stanza VALUES('F779','3','دعا کن یکدل و در روح،<br/>دعا در آسمانها؛<br/>چیزهای زمین به کنار،<br/>بجنگ با آن قدرت ها.<br/>',NULL,66543,4);
INSERT INTO stanza VALUES('F779','4','دعا کن یکدل و در روح،<br/>درخواست کن همیشگی؛<br/>جویای ذهن خداوند<br/>با روح در هماهنگی.<br/>',NULL,66544,5);
INSERT INTO stanza VALUES('F779','5','دعا کن یکدل و در روح،<br/>بیدار باش با پایداری؛<br/>بهرِ ملکوتِ خدا،<br/>بیدار در هماهنگی.<br/>',NULL,66545,6);
INSERT INTO stanza VALUES('F779','6','دعا کن یکدل و در روح،<br/>جویا در یگانگی؛<br/>در آن روحِ بدنِ او<br/>دعا در هماهنگی.<br/>',NULL,66546,7);
INSERT INTO stanza VALUES('F782','1','اسرار آمیز است، خدا،<br/>که روح تو در من است؛<br/>چقدر معجزه آسا<br/>که این دو روح یکی است.<br/>',NULL,66547,1);
INSERT INTO stanza VALUES('F782','2','در روح قدم بردارم،<br/>در روح روحانی باشم؛<br/>در روح خدمت می کنم،<br/>و در روح می پرستم.<br/>',NULL,66548,2);
INSERT INTO stanza VALUES('F782','3','از کلام و با دعا<br/>در روح لمس ات می کنم،<br/>روحم یابد ارتقا<br/>و از تو قوت گیرم.<br/>',NULL,66549,3);
INSERT INTO stanza VALUES('F782','4','روحم را قوت بده،<br/>بهرِ روحِ دیگران؛<br/>روحم را ارتقا دِه<br/>بهرِ رشد دیگران.<br/>',NULL,66550,4);
INSERT INTO stanza VALUES('F782','5','هر بار صحبت می کنم،<br/>خدایا، در روح باشد؛<br/>و هر کاری بکنم،<br/>با تشویقِ روح باشد.<br/>',NULL,66551,5);
INSERT INTO stanza VALUES('F782','6','هر بار روحم کار کند،<br/>روحِ آنها باز شود،<br/>هر بار روحم حرْکت کرد<br/>دیگران به تو آیند.<br/>',NULL,66552,6);
INSERT INTO stanza VALUES('F782','7','خداوندا، رحمت کن<br/>با روحت بر من بدَم؛<br/>روح مرا غنی کن،<br/>تا با تو تازه شوم.<br/>',NULL,66553,7);
INSERT INTO stanza VALUES('F783','1','لمس کن تختِ خدا را،<br/>تختِ فیضِ الهی،<br/>فیض و رحمت پیدا کن<br/>رفع شود هر نیازی.<br/>',NULL,66554,1);
INSERT INTO stanza VALUES('F783','2','لمس کن تخت را در دعا،<br/>حس کن نیاز به فیض را؛<br/>مشارکت رو در رو،<br/>در روح بمان با خدا.<br/>',NULL,66555,2);
INSERT INTO stanza VALUES('F783','3','لمس کن تخت را در دعا،<br/>بیاموز قدرِ فیض را؛<br/>دائم بچش، دریافت کن،<br/>شکر و سپاس خدا را.<br/>',NULL,66556,3);
INSERT INTO stanza VALUES('F783','4','لمس کن تخت را در دعا،<br/>لمس کن تختِ قدرت را؛<br/>در نامِ عیسی مسیح،<br/>رسیدگی به چیزها.<br/>',NULL,66557,4);
INSERT INTO stanza VALUES('F783','5','لمس کن تخت را در دعا<br/>با دستِ ایمانِ حیّ<br/>به کار ببر اقتدار<br/>را بر هر قدرتِ مرگ.<br/>',NULL,66558,5);
INSERT INTO stanza VALUES('F783','6','لمس کن تخت را در دعا،<br/>لرزان قدرتِ شر را؛<br/>با سلطنتِ بر تخت،<br/>دعا کن با مسیحا.<br/>',NULL,66559,6);
INSERT INTO stanza VALUES('F784','1','مشارکت کن با عیسی،<br/>در روح جویای او باش؛<br/>بخواه و گوش بده او را،<br/>منتظر در حضورش.<br/>',NULL,66560,1);
INSERT INTO stanza VALUES('F784','chorus','مشارکت کن با عیسی،<br/>در روح جویای او باش؛<br/>بخواه و گوش بده او را،<br/>منتظر در حضورش.<br/>',NULL,66561,2);
INSERT INTO stanza VALUES('F784','2','مشارکت کن با عیسی،<br/>از درون به او باز باش،<br/>با رویِ بی نقاب، او را<br/>بنگر، امین و بی غش.<br/>',NULL,66562,3);
INSERT INTO stanza VALUES('F784','3','مشارکت کن با عیسی،<br/>با اعتمادِ کامل؛<br/>یاد بگیر لمس کنی او را،<br/>با احترامِ کامل.<br/>',NULL,66563,4);
INSERT INTO stanza VALUES('F784','4','مشارکت کن با عیسی،<br/>از دورویی پرهیز کن؛<br/>بر طبق روح از او بخواه،<br/>با حسِ روح دعا کن.<br/>',NULL,66564,5);
INSERT INTO stanza VALUES('F784','5','مشارکت کن با عیسی،<br/>گوش بده با شوق به او؛<br/>تحت تاثیر قصدِ او،<br/>از درون تسلیم به او.<br/>',NULL,66565,6);
INSERT INTO stanza VALUES('F784','6','مشارکت کن با عیسی،<br/>غرق در نورِ چهره اش؛<br/>اشباع شده با زیباییش،<br/>درخشندۀ نورش.<br/>',NULL,66566,7);
INSERT INTO stanza VALUES('F786','1','دعا در کار با خدا،<br/>تا راهش هموار کنیم؛<br/>تا با او حرکت کنیم<br/>از مرکز به حاشیه.<br/>',NULL,66567,1);
INSERT INTO stanza VALUES('F786','2','دعا در کار با خدا،<br/>با او شناخته شوید<br/>در قصد و در هدفش،<br/>تا برْکت جاری شود.<br/>',NULL,66568,2);
INSERT INTO stanza VALUES('F786','3','دعا در کار با خدا،<br/>جاه طلبی و نفْس را<br/>باید دائم دور کنیم<br/>تا قصدش شود اجرا.<br/>',NULL,66569,3);
INSERT INTO stanza VALUES('F786','4','دعا در کار با خدا،<br/>آغازِ کار با خداست،<br/>کلِ طرح و کلِ کار،<br/>اجرایش از راه ماست.<br/>',NULL,66570,4);
INSERT INTO stanza VALUES('F786','5','دعا در کار با خدا،<br/>تا آن چرخ حرْکت کند؛<br/>دعا با هم با خدا،<br/>تا قدرتش فاش شود.<br/>',NULL,66571,5);
INSERT INTO stanza VALUES('F792','1','منتظر، خدا، منتظرت؛<br/>در تو آرام گیرم؛<br/>خواستت فاش کن بر من،<br/>این است تقاضایم<br/>منتظر، خدا، منتظرت.<br/>',NULL,66572,1);
INSERT INTO stanza VALUES('F792','2','منتظر، خدا، منتظرت؛<br/>اینجا با تو مانم،<br/>راهت فاش کن بر من،<br/>با تو دعا کنم<br/>منتظر، خدا، منتظرت.<br/>',NULL,66573,2);
INSERT INTO stanza VALUES('F792','3','منتظر، خدا، منتظرت؛<br/>خود درآمیز با من،<br/>تا با تو یک شوم<br/>شکل تو خواهم بود<br/>منتظر، خدا، منتظرت.<br/>',NULL,66574,3);
INSERT INTO stanza VALUES('F792','4','منتظر، خدا، منتظرت؛<br/>تا شناسم خواستت،<br/>راه تو را رَوم،<br/>جاری شود حیات<br/>منتظر، خدا، منتظرت.<br/>',NULL,66575,4);
INSERT INTO stanza VALUES('F792','5','منتظر، خدا، منتظرت؛<br/>دعاهایم، باشد<br/>ابرازِ تو باشد،<br/>به من دِه کلیدت<br/>منتظر، خدا، منتظرت.<br/>',NULL,66576,5);
INSERT INTO stanza VALUES('F811','1','قلبم گشنه است و روحم تشنه؛<br/>آيم به تو تا تأمينم كنى؛<br/>احتياجم هيچى به جز تو نيست،<br/>تو مى توانى راضى ام كنى.<br/>',NULL,66577,1);
INSERT INTO stanza VALUES('F811','chorus','غذام ده عيسى، بنوشانم،<br/>گشنگيم و تشنگيم رفع كن؛<br/>غرق در شادى كن و قدرتم باش،<br/>گشنگيم و تشنگيم رفع كن.<br/>',NULL,66578,2);
INSERT INTO stanza VALUES('F811','2','تو غذا و آبِ حيات هستى،<br/>روحم احيا و حمايت كنى؛<br/>مِيلم خوردن و نوشيدن از تو،<br/>مَسرت بردن با دعا خوانى.<br/>',NULL,66579,3);
INSERT INTO stanza VALUES('F811','3','كلام و پُرىِ خدا هستی،<br/>چون روحى، خدا حياتم باشد؛<br/>در كلامت تو غذايم هستى،<br/>به عنوان روحْ، آب هستى برام.<br/>',NULL,66580,4);
INSERT INTO stanza VALUES('F811','4','از آسمان چون غذا آمدى،<br/>ضربه خوردی تا آب شوى برام؛<br/>منبعِ غذاى بى پايانى،<br/>به عنوان آب، یک نهرى برام.<br/>',NULL,66581,5);
INSERT INTO stanza VALUES('F811','5','تو در كلام، روح و حيات هستى،<br/>پس با كلامت از تو مى خورم؛<br/>چون روح در روحم زندگى كنى،<br/>پس من در روحم از تو مى نوشم.<br/>',NULL,66582,6);
INSERT INTO stanza VALUES('F811','6','حال در کلام از تو لذت بَرَم،<br/>از تو خورم تمام شه گشنگيم.<br/>حال در روح بسوى تو مى چرخم،<br/>مى نوشم تا تمام شه تشنگيم.<br/>',NULL,66583,7);
INSERT INTO stanza VALUES('F811','7','خورم و نوشم از تو اى عيسى،<br/>خورم با خواندن، نوشم با دعا؛<br/>خواندن و دعا، خورم و نوشم،<br/>دعا و خواندن، روزی ام خدا.<br/>',NULL,66584,8);
INSERT INTO stanza VALUES('F811','8','خدايا اينجا در تو جشن گيرم؛<br/>غرق در روحت و پُر با كلامت؛<br/>باشد خدايا  تو جشنم باشى<br/>آنچه هیچ کس نشْنیده، ندیده.<br/>',NULL,66585,9);
INSERT INTO stanza VALUES('F812','1','آيم نزدت، خدا،<br/>قلبم تشنۀ توست؛<br/>از تو خورم، از تو نوشم،<br/>از تو لذت برم.<br/>',NULL,66586,1);
INSERT INTO stanza VALUES('F812','2','صورتت بنگرم،<br/>فقط اين را جويم؛<br/>عميقاً از تو بنوشم<br/>تا رفع شه تشنگيْم.<br/>',NULL,66587,2);
INSERT INTO stanza VALUES('F812','3','صورتِ پُر نورت<br/>ميل دارم ببينم،<br/>اينجا مانم، خارج نشم،<br/>پيوسته بنگرم.<br/>',NULL,66588,3);
INSERT INTO stanza VALUES('F812','4','در اين مشاركت<br/>تو هستى فيض من؛<br/>قلب و روحم شاد، پُر كنى،<br/>در تو بیاسایم.<br/>',NULL,66589,4);
INSERT INTO stanza VALUES('F812','5','خدا، اينجا مانم،<br/>دائم دنبالِ تو،<br/>دائم در دعا و كلام<br/>تا لبريز شى در من.<br/>',NULL,66590,5);
INSERT INTO stanza VALUES('F819','1','چون بدنِ ما ابرازِ<br/>حیاتمان است،<br/>کلیسا، بدنِ مسیح،<br/>هم ابراز اوست.<br/>',NULL,66591,1);
INSERT INTO stanza VALUES('F819','2','چون حوّا بخشیست از آدم،<br/>و از او آمد،<br/>کلیسا وفور مسیح<br/>و حاوی اوست.<br/>',NULL,66592,2);
INSERT INTO stanza VALUES('F819','3','چون از دانۀ دفن شده<br/>دانه ها رویند؛<br/>و دانه ها ترکیب با هم<br/>چون قرصِ نان اند؛<br/>',NULL,66593,3);
INSERT INTO stanza VALUES('F819','4','کلیسا هم با اعضایش،<br/>تکثیر مسیح،<br/>چون بدن، ابرازش بهرِ<br/>جلالِ خداست.<br/>',NULL,66594,4);
INSERT INTO stanza VALUES('F819','5','همچون شاخه های آن تاک<br/>که ابرازش اند،<br/>در هم ساکن و یک هستند،<br/>میوه آورند؛<br/>',NULL,66595,5);
INSERT INTO stanza VALUES('F819','6','کلیسا هم با اعضایش،<br/>وفورِ مسیح،<br/>یک با او در حیات و زیست،<br/>گسترشِ او.<br/>',NULL,66596,6);
INSERT INTO stanza VALUES('F819','7','پُری، ازدیاد و تکثیر،<br/>ابرازش کامل،<br/>رشد، گسترش و ادامه<br/>و فراوانی،<br/>',NULL,66597,7);
INSERT INTO stanza VALUES('F819','8','کلیساست بهرِ مسیح، تا<br/>خدا در مسیح<br/>جلال یابد تا به ابد<br/>توسط ما.<br/>',NULL,66598,8);
INSERT INTO stanza VALUES('F819','9','مسیح و کلیسا با هم،<br/>این رازِ خداست،<br/>آمیخته شدنِ خدا<br/>با انسانیت.<br/>',NULL,66599,9);
INSERT INTO stanza VALUES('F821','1','کلیسا چون ظرف، مسیح را<br/>حاوی است و ابراز کند،<br/>همچون بدنِ انسان که<br/>انسان را ابراز می کند.<br/>',NULL,66600,1);
INSERT INTO stanza VALUES('F821','2','چون آن صندوقِ شهادت،<br/>که جای آن در معبد بود؛<br/>کلیسا حاویِ مسیح<br/>و جای سکونتِ اوست.<br/>',NULL,66601,2);
INSERT INTO stanza VALUES('F821','3','چون مسیح آن رازِ خداست،<br/>و توضیح و ابرازِ اوست؛<br/>کلیسا راز مسیح است،<br/>و توضیح و ابرازِ اوست.<br/>',NULL,66602,3);
INSERT INTO stanza VALUES('F821','4','اعضای کلیسای او<br/>از خاک سرشته شده اند؛<br/>باید دگرگون و شفاف<br/>و روز به روز نفیس شوند.<br/>',NULL,66603,4);
INSERT INTO stanza VALUES('F821','5','دگرگون، بنا شده، و<br/>ظرفی بهرِ مسیح شوند،<br/>و با تمامیتِ او؛<br/>شفاف، او را ابراز کنند.<br/>',NULL,66604,5);
INSERT INTO stanza VALUES('F821','6','طی کارِ دگرگونی<br/>که خدا انجام می دهد،<br/>کلیسا ظرفی جمعی است،<br/>و همچون اورشلیمِ نوست.<br/>',NULL,66605,6);
INSERT INTO stanza VALUES('F821','7','او از هر جهت نفیس است،<br/>و از هر جنبه شفاف است؛<br/>با مسیح، پُریِ خدا،<br/>جلالش نمایان سازد.<br/>',NULL,66606,7);
INSERT INTO stanza VALUES('F821','8','با مسیحْ حیات، خدا نور،<br/>و با روحِ زنده جریان،<br/>او خدای سه-یکتا را<br/>نمایان کند به جهان.<br/>',NULL,66607,8);
INSERT INTO stanza VALUES('F824','1','کلیسا تَنِ مسیح،<br/>مسکنِ پدر است،<br/>جمعِ فراخواندگان،<br/>خدا انسان در هم؛<br/>معیّن پیش از خلقت،<br/>بازخرید بر صلیب،<br/>شخصیت و مقامش<br/>آسْمانی، نه خاکیست.<br/>',NULL,66608,1);
INSERT INTO stanza VALUES('F824','2','انسانِ خلقتِ نو،<br/>مولود از خداوند،<br/>تعمید در خدای روح،<br/>تقدیس در کلامش؛<br/>مسیح سَرِ پرجلال<br/>و محتوای اوست؛<br/>با خداوند صعود کرد،<br/>غالب بر دشمنان.<br/>',NULL,66609,2);
INSERT INTO stanza VALUES('F824','3','مسیح، تک بنیادِ اوست،<br/>بنیادی دگر نیست؛<br/>هرچه از اوست، چون مسیح<br/>تماماً الهی ست؛<br/>اعضایش از راهِ روح<br/>مرگش را سهیم اند؛<br/>بنا در رستاخیزند<br/>چون سنگهای نفیس.<br/>',NULL,66610,3);
INSERT INTO stanza VALUES('F824','4','یک خدا، سَرور و روح<br/>عناصری واحد<br/>یک ایمان، امید، تعمید،<br/>یک بدن در پسر؛<br/>خدا سه-یکتا در او،<br/>اعضا در یک بدن،<br/>در ایمان وحدت دارند،<br/>در امیدِ جلال.<br/>',NULL,66611,4);
INSERT INTO stanza VALUES('F824','5','از هر قوم و ملتی<br/>اعضایش می آیند،<br/>صرف نظر از رتبه،<br/>باهم در یک وحدت.<br/>نه بالا و نه پست هست،<br/>نه دین دار، نه بی دین،<br/>نه آزاد، نه غلام، لیک<br/>مسیح، «انسانِ نو.»<br/>',NULL,66612,5);
INSERT INTO stanza VALUES('F824','6','یک بدنِ جهانی،<br/>در هر جا یک ابراز؛<br/>محلۀ سکونت<br/>تنها زمینه اش؛<br/>اداره اش محلی،<br/>جوابگوی خدا؛<br/>اشتراکِ جهانی،<br/>با هم در یکدلی.<br/>',NULL,66613,6);
INSERT INTO stanza VALUES('F824','7','الگوی جلساتش<br/>چون اورشلیم نو؛<br/>در جوانب و تفصیل<br/>هر دو مثل هم اند.<br/>مسیح چراغِ تابان،<br/>خدا نورْ درونش؛<br/>چراغدان ها حاویِ<br/>شکلِ درخشانش.<br/>',NULL,66614,7);
INSERT INTO stanza VALUES('F837','1','خدایا شکر بهرِ طرحت،<br/>که ما مسکن تو باشیم؛<br/>تو در ما، و ما پر از تو،<br/>تا در پسر ابراز شوی.<br/>',NULL,66615,1);
INSERT INTO stanza VALUES('F837','2','گرچه به شکلت خلق شدیم،<br/>و اقتدارت را داریم،<br/>لیک از خاک ساخته شده ایم،<br/>بدون بخشی الهی.<br/>',NULL,66616,2);
INSERT INTO stanza VALUES('F837','3','وقتی تو را دریافت کنیم،<br/>ذاتت از آنِ ما شود؛<br/>با تو آمیخته می شویم،<br/>بهرِ ابراز بدنت.<br/>',NULL,66617,3);
INSERT INTO stanza VALUES('F837','4','چون حیات به روان رسد،<br/>هر بخش را پُر، تازه کند،<br/>سنگهای نفیس خواهیم شد،<br/>به شکل تو، همچون خودت.<br/>',NULL,66618,4);
INSERT INTO stanza VALUES('F837','5','لیک دانیم، ای خداوند، این<br/>بهرِ تمجید مردم نیست،<br/>لیک بهرِ بنا شدن است<br/>با هم، برای خانه ات.<br/>',NULL,66619,5);
INSERT INTO stanza VALUES('F837','6','خدا، خود را به تو دهیم؛<br/>در دست های حکیمِ تو؛<br/>خَم و بنا گشته با هم<br/>در تو، برای خانه ات.<br/>',NULL,66620,6);
INSERT INTO stanza VALUES('F837','7','حیاتِ فطری را شِکن،<br/>به ناروالی پایان دِه،<br/>تا ما مستقل نباشیم،<br/>با مقدسین یک باشیم.<br/>',NULL,66621,7);
INSERT INTO stanza VALUES('F837','8','عروسِ محبوبت شویم،<br/>با هم در جای تو مانیم،<br/>از کمال عشق برخوردار.<br/>آنگاه تو راضی خواهی بود!<br/>',NULL,66622,8);
INSERT INTO stanza VALUES('F839','1','کوزه گری ماهری،<br/>سازنده ای پرجلال،<br/>بهرِ ظرف عظیمت،<br/>با دیدگاه خانه ات.<br/>من هم فردی گِلی ام<br/>هم سنگی زنده، نوساز،<br/>تا من باشم ظرف تو<br/>و همان معبد تو.<br/>',NULL,66623,1);
INSERT INTO stanza VALUES('F839','2','گرچه از گِل ساختی مان<br/>لیک دگرگون خواهی کرد؛<br/>به سنگ نفیس همشکل،<br/>با حیاتت از طلا.<br/>از راه بناسازی،<br/>پس ما عروست شویم،<br/>در یک بدن، وصل به تو،<br/>تا قلبت راضی کنیم.<br/>',NULL,66624,2);
INSERT INTO stanza VALUES('F839','3','آنچه قلبت می خواهد<br/>سنگ های تنها نیستند،<br/>لیک باهم بنا شده<br/>بهرِ جلال، خانه ات.<br/>مسیحْ شاملِ تمام،<br/>کلیسا را می خواهی،<br/>تا غنایت پرشکوه<br/>چون نورِ آن درخشد.<br/>',NULL,66625,3);
INSERT INTO stanza VALUES('F839','4','نه یک شخصِ روحانی<br/>به طور انفرادی،<br/>لیک آن ابرازِ جمعی<br/>قلبت را راضی کند.<br/>اعضای تک و جدا<br/>ابرازی کامل نیستند،<br/>لیک بدن، میزان، بنا،<br/>پُری ات دائم باشد.<br/>',NULL,66626,4);
INSERT INTO stanza VALUES('F839','5','خداوند، بنایم کن،<br/>انفرادی نباشم،<br/>لیک بر طبق طرحِ خود<br/>حالْ مرا پیوند بزن.<br/>به تجارب نبالم،<br/>به عَطْیه فخر نکنم؛<br/>خود را برایت دهم،<br/>تا تو جلال بیابی.<br/>',NULL,66627,5);
INSERT INTO stanza VALUES('F840','1','آزاد از نفْس، ذاتِ آدم،<br/>خداوند، بنایم کن<br/>با مقدسین، معبدت،<br/>تا جلالت را بینیم.<br/>از خُلقِ غریب برهان،<br/>از روالِ خودفرمان،<br/>تا مسکن تو، خداوند،<br/>باشیم تمامِ دوران.<br/>',NULL,66628,1);
INSERT INTO stanza VALUES('F840','2','در حیات و جریان آن،<br/>رشد کرده، تبدیل شوم؛<br/>با مقدسین هماهنگ،<br/>بنا، همشکلت شوم؛<br/>نظمِ بدن نگه دارم،<br/>بهرِ ارادۀ تو،<br/>خدمت به دیگران بهرِ<br/>اجرای مقصود تو.<br/>',NULL,66629,2);
INSERT INTO stanza VALUES('F840','3','در شناخت و تجربه ام<br/>پرغرور نخواهم شد،<br/>لیک تسلیم شوم، پذیرم،<br/>با بدن تنظیم شوم؛<br/>در پیوند با سَر رشد کنم<br/>در کمال و راه او،<br/>و با تأمین مفصل ها،<br/>در پیوندی روز به روز.<br/>',NULL,66630,3);
INSERT INTO stanza VALUES('F840','4','هر روز از روحت به قوت<br/>نیرو گیرم در درون،<br/>تا به عشقت عارف شوم،<br/>به ابعادت پی بَرم؛<br/>از غنایت بهره بَرم،<br/>با کمالت پُر شوم،<br/>بسوی بلوغ رشد کنم،<br/>تا بدن بنا شود.<br/>',NULL,66631,4);
INSERT INTO stanza VALUES('F840','5','در مسکن و بدنِ تو<br/>طالبم بنا شوم،<br/>تا در چنین ظرف جمعی<br/>جلالت دیده شود؛<br/>تا عروس، شهرِ پرشکوه،<br/>بر زمین آشکار شود،<br/>چون چراغدانی درخشان<br/>بهرِ ابراز خودت.<br/>',NULL,66632,5);
INSERT INTO stanza VALUES('F841','1','تو در من، خدایا،<br/>حیاتم هستی؛<br/>کمالِ خدا را<br/>به من می دهی.<br/>با ذاتِ قدوست<br/>تقدیس می شوم،<br/>و در رستاخیزت،<br/>در پیروزی ام.<br/>',NULL,66633,1);
INSERT INTO stanza VALUES('F841','2','خدایا، حیاتت<br/>روشنم کند،<br/>روح را می آورد<br/>در مشارکت؛<br/>نیازم رفع کند<br/>بهرِ خواست تو،<br/>و مرا پاک کند<br/>تا ایستم در تو.<br/>',NULL,66634,2);
INSERT INTO stanza VALUES('F841','3','مسحِ روحت مرا<br/>آغشته سازد،<br/>روح و روانم را<br/>اشباع خواهی کرد؛<br/>دگرگون سازی تا<br/>همشکل ات شوم،<br/>تا حیاتت در من<br/>به کمال رسد.<br/>',NULL,66635,3);
INSERT INTO stanza VALUES('F841','4','خدایا، حیاتت<br/>فراوان جاریست،<br/>دائم تازه کند<br/>و قوت دهد.<br/>مرگ بلعیده شود،<br/>ضعف، قوت گیرد،<br/>بندهایم افتند و<br/>غم، سُرور شود.<br/>',NULL,66636,4);
INSERT INTO stanza VALUES('F841','5','خودم را می دهم<br/>به تو، ای خدا،<br/>تا خواسته ات در من<br/>بشود اجرا.<br/>دیگر سعی نکنم<br/>بسازم خود را،<br/>و شوم مانعِ<br/>کارِ تو در ما.<br/>',NULL,66637,5);
INSERT INTO stanza VALUES('F841','6','کاملاً بازایستم<br/>از هر تقلا،<br/>تا دگرگون شوم،<br/>کاملاً رها؛<br/>با دیگران مرا<br/>بنایم کن تا<br/>کامل ابراز کنیم<br/>جلالِ تو را.<br/>',NULL,66638,6);
INSERT INTO stanza VALUES('F846','1','روحم جارى شود،<br/>جارى شود!<br/>خواهشمند، ای خدا،<br/>جارى شود!<br/>سابق را ترک كنم،<br/>ديوارها بشكنند،<br/>روحم آزاد شود؛<br/>جارى شود!<br/>',NULL,66639,1);
INSERT INTO stanza VALUES('F846','2','روحم جارى شود،<br/>جارى شود!<br/>التماس، اى خدا،<br/>جارى شود!<br/>نه رضايت از خود،<br/>نه تكبر در خود،<br/>نه مشكلى در روح،<br/>جارى شود!<br/>',NULL,66640,2);
INSERT INTO stanza VALUES('F846','3','روحم جارى شود،<br/>جارى شود!<br/>استدعا، اى خدا،<br/>جارى شود!<br/>تا مغرور نباشم،<br/>در فخر زندان نشم،<br/>دائم جارى شوم،<br/>جارى در روح.<br/>',NULL,66641,3);
INSERT INTO stanza VALUES('F846','4','روحم جارى شود،<br/>جارى شود!<br/>از تو جويم، خدا،<br/>جارى شود!<br/>ديگر نه انزوا،<br/>ديگر نه خود كمال،<br/>فرو ننشيند روح،<br/>جارى شود.<br/>',NULL,66642,4);
INSERT INTO stanza VALUES('F846','5','روحم جارى شود،<br/>جارى شود!<br/>از تو خواهم، خدا،<br/>جارى شود!<br/>بی اعتماد به خود،<br/>از تخت پایین آیم،<br/>تا آب جارى شود<br/>در روح، خدا.<br/>',NULL,66643,5);
INSERT INTO stanza VALUES('F846','6','روحم جارى شود،<br/>جارى شود!<br/>جواب ده، ای خدا،<br/>جارى شود!<br/>نه تنها حرف زدن،<br/>خواهم بنا شوم،<br/>وحدت با ديگران<br/>در روح، خدا.<br/>',NULL,66644,6);
INSERT INTO stanza VALUES('F852','1','عاشقِ خانه ات، خدا،<br/>كليسات پُر بركت،<br/>شادى و خشنودىِ توست،<br/>آرامشِ قلبت.<br/>',NULL,66645,1);
INSERT INTO stanza VALUES('F852','2','دادى خود بهرِ او، خدا،<br/>تا مالِ تو شود؛<br/>نيز دهم بهرِ او خود را،<br/>خشنودى قلبت.<br/>',NULL,66646,2);
INSERT INTO stanza VALUES('F852','3','بهرِ او، شدى حياتم،<br/>تا زيستنم شود؛<br/>بهرِ او، خود انكار كنم،<br/>كه از تو پر شود.<br/>',NULL,66647,3);
INSERT INTO stanza VALUES('F852','4','كليسا، عروس و عشقت،<br/>در بدن فاش شوی؛<br/>او خشنودى قلبم است،<br/>بر او تكيه كنم.<br/>',NULL,66648,4);
INSERT INTO stanza VALUES('F852','5','در او وجودت را، خدا،<br/>عطايم مى كنى؛<br/>در او تصرفم كردى،<br/>شود قلبت راضى.<br/>',NULL,66649,5);
INSERT INTO stanza VALUES('F852','6','عاشقِ خانه ات، خدا،<br/>كليسا خانه ات؛<br/>در آن تا ابد خواهم زيست،<br/>سرگردان نشوم.<br/>',NULL,66650,6);
INSERT INTO stanza VALUES('F863','1','در زندگی و در جلسات نیز،<br/>مسیح مرکز است، مسیح همه چیز؛<br/>نه برای ظاهر یا تعالیم<br/>لیک تنها بهرِ مسیح جمع شویم.<br/>',NULL,66651,1);
INSERT INTO stanza VALUES('F863','2','مسیح راه است، مسیح نورِ حیات،<br/>در او راه رویم، هدایت شویم؛<br/>مسیح آبِ زنده است و غذا؛<br/>از او نوشیم، با او سیراب شویم.<br/>',NULL,66652,2);
INSERT INTO stanza VALUES('F863','3','مسیح راستی ست، او شهادت ماست،<br/>مسیح حیات است، خدمتش کنیم؛<br/>مسیح خداست، او را جلال دهیم،<br/>مسیح سَر است، او را تمجید کنیم.<br/>',NULL,66653,3);
INSERT INTO stanza VALUES('F863','4','مسیح همه چیزِ ما و خداست –<br/>با او ما و خدا راضی هستیم؛<br/>مسیح واقعیتِ کلیساست –<br/>در حیات و تعداد تکثیر یابیم.<br/>',NULL,66654,4);
INSERT INTO stanza VALUES('F863','5','با سرودها و دعاهایمان ،<br/>مسیح، حقیقت، را ابراز کنیم؛<br/>همۀ کارها در مشارکت –<br/>مسیح در عملکرد اظهار کنیم.<br/>',NULL,66655,5);
INSERT INTO stanza VALUES('F863','6','در نامِ او، در روح عمل کنیم،<br/>چیزی را چون فرمول درنَیاریم؛<br/>با مَسح دعا و ستایش کنیم،<br/>و با او روح را بکار می بریم.<br/>',NULL,66656,6);
INSERT INTO stanza VALUES('F863','7','به مسیح می چسبیم، نه به عقب،<br/>او را بکار بریم، بالغ شویم؛<br/>همه را بهرش فضله شماریم،<br/>برای او، تا ابدلاباد.<br/>',NULL,66657,7);
INSERT INTO stanza VALUES('F864','1','در ملاقاتمان مسيح،<br/>وفورِ فراوانِ او<br/>چون هدیه به خدا دهيم،<br/>مسيحْ آشکار كنيم.<br/>',NULL,66658,1);
INSERT INTO stanza VALUES('F864','chorus','مسيح آشکار كنيم،<br/>مسيح آشکار كنيم؛<br/>وفورِ او در كليساست،<br/>مسيح آشکار كنيم.<br/>',NULL,66659,2);
INSERT INTO stanza VALUES('F864','2','در مسيحْ زیست کنیم، جنگیم،<br/>دائم رويش زحمت كشيم،<br/>با وفورش يكى هستيم<br/>تا آشکارش كنيم.<br/>',NULL,66660,3);
INSERT INTO stanza VALUES('F864','3','حيات، وجود، و كارِ ما<br/>در مسيحْ ذاتِ راستى مان،<br/>كه هر وقت ملاقات كنيم<br/>مسيحْ آشکار كنيم.<br/>',NULL,66661,4);
INSERT INTO stanza VALUES('F864','4','مسيح را ارائه دهيم<br/>مسيحْ با هم سهیم شویم،<br/>در جلسات لذت بريم،<br/>مسيح آشکار كنيم.<br/>',NULL,66662,5);
INSERT INTO stanza VALUES('F864','5','مسیح ِ قيام و صعود-<br/>كرده را به خدا دهيم،<br/>پس خدا را راضى كنيم،<br/>مسيح آشکار كنيم.<br/>',NULL,66663,6);
INSERT INTO stanza VALUES('F864','6','آن مركز و واقعيت،<br/>محيط و خدمتگزارى،<br/>اصلِ ملاقات اين است كه:<br/>مسيح آشکار كنيم.<br/>',NULL,66664,7);
INSERT INTO stanza VALUES('F864','7','آن شهادت و آن دعا،<br/>كلِ مشاركتِ ما،<br/>عطایا و همه فقط<br/>مسيح آشکار كنند.<br/>',NULL,66665,8);
INSERT INTO stanza VALUES('F864','8','پدر را ما جلال دهيم،<br/>چون مسيح را تمجيد كنيم،<br/>هدف ملاقات این که:<br/>مسيح آشکار کنیم.<br/>',NULL,66666,9);
INSERT INTO stanza VALUES('F866','1','روح را بکار برید!<br/>نه فکر انسان؛<br/>گرد هم بیایید،<br/>برای بدن.<br/>',NULL,66667,1);
INSERT INTO stanza VALUES('F866','2','روح را بکار برید!<br/>خارج از رسوم،<br/>با هم سهیم شوید،<br/>در مسیح سهیم.<br/>',NULL,66668,2);
INSERT INTO stanza VALUES('F866','3','روح را بکار برید!<br/>نه حسِ فِطری؛<br/>با هم خدمت کنید،<br/>اعلامِ مسیح.<br/>',NULL,66669,3);
INSERT INTO stanza VALUES('F866','4','روح را بکار برید!<br/>نه نفْس و روان؛<br/>مفید به یکدیگر،<br/>تکیه بر خدا.<br/>',NULL,66670,4);
INSERT INTO stanza VALUES('F866','5','آزاد درونِ روح<br/>از خود-صداقت،<br/>از خود-محکومیت،<br/>از خود-رضایت.<br/>',NULL,66671,5);
INSERT INTO stanza VALUES('F866','6','آزاد درونِ روح<br/>از فیس و غرور،<br/>از خودبزرگ بینی،<br/>از همه آزاد.<br/>',NULL,66672,6);
INSERT INTO stanza VALUES('F866','7','روح را بکار برید،<br/>اعلامِ ظفر<br/>با خون که پاک کند،<br/>و نامِ قدیر.<br/>',NULL,66673,7);
INSERT INTO stanza VALUES('F866','8','روح را بکار برید،<br/>با لمسِ خدا؛<br/>و همیشه با روح<br/>از راهِ کلام.<br/>',NULL,66674,8);
INSERT INTO stanza VALUES('F866','9','شهادتِ مسیح،<br/>تنها با روح است؛<br/>رضایتِ انسان،<br/>تنها با روح است.<br/>',NULL,66675,9);
INSERT INTO stanza VALUES('F866','10','روح را بکار برید!<br/>این نیاز ماست!<br/>روح را بکار برید!<br/>به خواست خدا!<br/>',NULL,66676,10);
INSERT INTO stanza VALUES('F880','1','به دشمن هميشه گویم «نه،»<br/>به پدر گويم «آرى،»<br/>تا نقشه و اراده اش<br/>انجام شه با پيروزى؛<br/>چون اطاعت كنم اَمرَت،<br/>اقتدارعطايم كن؛<br/>تا اجرا شود نقشه ات،<br/>از قدرتِ روح در من.<br/>',NULL,66677,1);
INSERT INTO stanza VALUES('F880','2','به دشمن هميشه گویم «نه،»<br/>به پدر گويم «آرى،»<br/>اين روش ام است تا ابد؛<br/>خدا، حفظ کن، برْکت ده،<br/>مبادا در اطاعتم،<br/>شيطان ضعیفم کنه؛<br/>وقتى دستورت گوش ميدم،<br/>خداوند، رحمتم ده.<br/>',NULL,66678,2);
INSERT INTO stanza VALUES('F880','3','به دشمن هميشه گویم «نه،»<br/>به پدر گويم «آرى،»<br/>کاملاً اطاعت كنم،<br/>گرچه رنج سرکوب كند.<br/>گر خدا نگه ام دارد،<br/>چون جلو روم با او،<br/>پس هيچ مانعم نشود،<br/>نه مقابله سهمگين.<br/>',NULL,66679,3);
INSERT INTO stanza VALUES('F886','1','خدای ما دژی قویست،<br/>محافظی تواناست؛<br/>کمک ما در طوفانهاست<br/>غالب بر هر چه فانی ست:<br/>چون دشمنِ دیرین<br/>هست بلاآفرین؛<br/>او مکار و قویست،<br/>تجهیز با سنگدلی ست،<br/>دنیا حریف او نیست.<br/>',NULL,66680,1);
INSERT INTO stanza VALUES('F886','2','گر با قوتِ خود رَویم،<br/>در نبرد بازنده ایم؛<br/>گر نمی بود آن شخص با ما،<br/>برگزیدۀ خدا؛<br/>می دانی آن شخص کیست؟<br/>همان مسیحْ عیساست؛<br/>خدای لشکرهاست،<br/>تغییرناپذیر است،<br/>او در نبرد پیروز است.<br/>',NULL,66681,2);
INSERT INTO stanza VALUES('F886','3','لیک گر این دنیای شیطان،<br/>خواست کند نابودمان،<br/>باکی نیست چون خدا خواهد<br/>حقیقت پیروز شود؛<br/>ظلمت بیداد کند،<br/>ما را نلرزانَد؛<br/>پاینده خواهیم بود،<br/>چون پایانش آید،<br/>با یک کلام نابود است.<br/>',NULL,66682,3);
INSERT INTO stanza VALUES('F886','4','آن کلام، قدرتِ تام است،<br/>و همیشه ماندگار؛<br/>آن روح و عطایا از ماست<br/>که از جانب خداست.<br/>مال، قوم و زندگی<br/>همه هستند فانی؛<br/>می توان جسم را کُشت:<br/>لیک حقیقت مانَد،<br/>و ملکوت تا ابد.<br/>',NULL,66683,4);
INSERT INTO stanza VALUES('F887','1','نام عیسی جایگاه ماست،<br/>و پیروزیِ ما؛<br/>بر خود تکیه نخواهیم کرد،<br/>لیک بر تو، ای خدا.<br/>سلاح های ما از جسم نیست،<br/>لیک شمشیرِ روح است،<br/>با زرهِ خدا بر تن<br/>در او نبرد کنیم.<br/>',NULL,66684,1);
INSERT INTO stanza VALUES('F887','2','بنگر، دشمن نقشه کِشد،<br/>در یکدلی ایستید!<br/>چون جنگ بد و تاریک باشد،<br/>در خداوند ایستید!<br/>گر فرد از ترس عقبگرد کرد،<br/>باقی آسیب بینند.<br/>مأیوس نکن دیگران را<br/>تا نشوند دردمند.<br/>',NULL,66685,2);
INSERT INTO stanza VALUES('F887','3','ابلیس داند وقتش کم است،<br/>پس بیشتر خشمگین است،<br/>خواهد ما را فریب دهد<br/>و ضعیف گردانَد.<br/>سختی ها اکنون بیش شدند،<br/>نیز رنج فراوان تر،<br/>نیروی مرگ بر ضد ماست<br/>از پیش بسیار بدتر.<br/>',NULL,66686,3);
INSERT INTO stanza VALUES('F887','4','پس حالت ما چه باشد<br/>در این لحظۀ حاد؟<br/>آیا پیِ خوشی باشیم<br/>به شرّ بی اعتنا؟<br/>یا چون ستیز حادتر شود،<br/>دلاور تر شویم؟<br/>مسئله مرگ یا حیات است!<br/>در ستایش مانیم.<br/>',NULL,66687,4);
INSERT INTO stanza VALUES('F887','5','باید بهرِ مسیح ایستیم،<br/>او همان فاتح است!<br/>بهرِ او تحمل کنیم<br/>تا جنگ تمام شود.<br/>روزِ ظفر را می بینیم –<br/>خداوند می آید؛<br/>گر حال بهرِ او رنج کِشیم،<br/>با او حکم خواهیم کرد.<br/>',NULL,66688,5);
INSERT INTO stanza VALUES('F889','1','با خونِ مسیحِ پیروز<br/>دشمن را مغلوب نما؛<br/>با تقوی و قدرتِ آن<br/>پیروزی اعلام نما.<br/>',NULL,66689,1);
INSERT INTO stanza VALUES('F889','chorus','با خونِ مسیحِ پیروز<br/>دشمن را مغلوب بنما؛<br/>با تقوی و قدرتِ آن<br/>پیروزی اعلام نما.<br/>',NULL,66690,2);
INSERT INTO stanza VALUES('F889','2','با خونِ مسیحِ پیروز<br/>با تهمت برخورد نما؛<br/>با حمایتِ خون او<br/>خنثی کن هر تهمت را.<br/>',NULL,66691,3);
INSERT INTO stanza VALUES('F889','3','با خونِ مسیحِ پیروز<br/>وفایش یقین نما؛<br/>از راهِ خونِ منجی ات<br/>بخشش را دریافت نما.<br/>',NULL,66692,4);
INSERT INTO stanza VALUES('F889','4','با خونِ مسیحِ پیروز<br/>اعلام کن مقامت را؛<br/>با خونِ همیشه قوی<br/>پیروزیْش شرکت نما.<br/>',NULL,66693,5);
INSERT INTO stanza VALUES('F889','5','با خونِ مسیحِ پیروز<br/>طلب کن قدرتش را؛<br/>به قدرت ِخونِ عیسی<br/>دشمن را مغلوب نما.<br/>',NULL,66694,6);
INSERT INTO stanza VALUES('F889','6','با خونِ مسیحِ پیروز<br/>ایستاده در آسْمانها؛<br/>در قدرتِ صعودِ او،<br/>فرو ریز قدرتها را.<br/>',NULL,66695,7);
INSERT INTO stanza VALUES('F890','1','هللوياه! مسيحْ پيروز،<br/>با هر دَم بگو،<br/>كه منجى فاتح است بر مرگ<br/>و گناه هنوز.<br/>',NULL,66696,1);
INSERT INTO stanza VALUES('F890','chorus','هللوياه! مسيحْ پيروز،<br/>بگو در هر جا،<br/>كه خدا فاتح است هنوز،<br/>بر هر نوع جفا.<br/>',NULL,66697,2);
INSERT INTO stanza VALUES('F890','2','هللوياه! مسيحْ پيروز،<br/>از رنجها رها،<br/>چون طلب كنيم پيروزى<br/>را بر جلجتا.<br/>',NULL,66698,3);
INSERT INTO stanza VALUES('F890','3','هللوياه! مسيحْ پيروز،<br/>با جرأت کار كن؛<br/>هر جا عيسى فرِستد رو،<br/>و ستایش كن.<br/>',NULL,66699,4);
INSERT INTO stanza VALUES('F890','4','هللوياه! مسيحْ پيروز،<br/>نه ترس و نه شکست<br/>بينش ات تار تواند كرد!<br/>مسيح روشنی ست.<br/>',NULL,66700,5);
INSERT INTO stanza VALUES('F890','5','هللوياه! مسيحْ پيروز،<br/>صدایش آید،<br/>«فاتحان بِپيونديد به<br/>فاتحْ شاهتان.»<br/>',NULL,66701,6);
INSERT INTO stanza VALUES('F892','1','با قدرتِ کل ملبس<br/>در رستاخیز خدای ما؛<br/>گر باهم با او زیست کنیم،<br/>شکست خواهیم داد دشمن را.<br/>',NULL,66702,1);
INSERT INTO stanza VALUES('F892','2','می گوییم، در نام عیسی،<br/>که بر خصم پیروز می شویم؛<br/>اقتدار گیریم از عیسی،<br/>سَرِ مار را له می کنیم.<br/>',NULL,66703,2);
INSERT INTO stanza VALUES('F892','3','کوهِ بلند را در هر جا،<br/>بر زمین و یا در سما،<br/>هموار کنیم به هر بها،<br/>مطرود شو، در نام عیسی!<br/>',NULL,66704,3);
INSERT INTO stanza VALUES('F892','4','با ایمان: «از جا کنده شو،<br/>و افکنده شو به دریا!»<br/>باید، توانیم، خواهیم کرد،<br/>ما خواست خدا را اجرا.<br/>',NULL,66705,4);
INSERT INTO stanza VALUES('F893','1','جنگ امروز شدید است،<br/>نیروی شریر، بیش؛<br/>صدای شیپورِ نبرد<br/>بلندتر است از پیش.<br/>عصیان جهنم<br/>حال بیشتر می شود؛<br/>لیک بشنو صدایی در شب:<br/>بزودی می آیم!<br/>',NULL,66706,1);
INSERT INTO stanza VALUES('F893','2','رنج ها بیشتر شوند،<br/>دعوا شدت یابد؛<br/>کل قدرت های شریر<br/>همگی جمع شوند.<br/>چون ما با صبر بینیم<br/>جنگ شدیدتر شود،<br/>سرود شادی شنویم،<br/>عیسی نزدیک شده!<br/>',NULL,66707,2);
INSERT INTO stanza VALUES('F893','3','مشکل تر خواهد شد<br/>شهادتِ کلام،<br/>چون می کوشد مقابله<br/>کند شیطان با آن.<br/>قوت لازم داریم<br/>تا غلبه کنیم؛<br/>شاد با دیدن خداوند،<br/>آسوده می شویم!<br/>',NULL,66708,3);
INSERT INTO stanza VALUES('F893','4','پس کی به پیش رود<br/>محکم در خداوند؟<br/>کی بر خدا تکیه کند<br/>تا وقتِ پیروزمند؛<br/>تا با پیروزمندان<br/>سرود فتخ خوانَد؟<br/>پس او با شادی شنوَد،<br/>بزودی می آیم!<br/>',NULL,66709,4);
INSERT INTO stanza VALUES('F893','5','کی با خدا ایستد،<br/>از درِ تنگ رود،<br/>حتی با گذر از طوفان،<br/>عقب برنگردد؟<br/>کی با جرات رَوَد،<br/>با تحملِ رنج؟<br/>او سپس با شادی بیند،<br/>عیسی نزدیک شده!<br/>',NULL,66710,5);
INSERT INTO stanza VALUES('F893','6','هر چقدر هم تاریک،<br/>به پیش رویم باید،<br/>تا روز عروج آید و<br/>جلال بدرخشد.<br/>پس خدا را بینیم،<br/>بر شر پیروز شویم؛<br/>پیروزمندان شادی کنند،<br/>عیسی، خدا، آمد!<br/>',NULL,66711,6);
INSERT INTO stanza VALUES('F894','1','آیا پیروزمند می شوی؟<br/>مسیح کرد صدا!<br/>آیا از پی اش می روی<br/>نا آگاه از راه؟<br/>',NULL,66712,1);
INSERT INTO stanza VALUES('F894','chorus','آیا پیروزمند می شوی؟<br/>بر می گزینی؟<br/>مسیح خوانَد، مسیح خوانَد،<br/>صدایش بشنو!<br/>',NULL,66713,2);
INSERT INTO stanza VALUES('F894','2','آیا پیروزمند می شوی؟<br/>نزدیک به خدا!<br/>«عشقِ اول» حفظ کن، رِسَد<br/>زود سحر از راه.<br/>',NULL,66714,3);
INSERT INTO stanza VALUES('F894','3','آیا پیروزمند می شوی؟<br/>با تکیه بر او!<br/>با تحملِ آزار، تا<br/>تَه امین به او.<br/>',NULL,66715,4);
INSERT INTO stanza VALUES('F894','4','آیا پیروزمند می شوی؟<br/>جزوِ شاهدان!<br/>دور از مذهب و سهیم در<br/>«منّای پنهان.»<br/>',NULL,66716,5);
INSERT INTO stanza VALUES('F894','5','آیا پیروزمند می شوی؟<br/>ساده، راست، سالم؟<br/>غالب بر هر اختلاط، با<br/>نیروی حاکم.<br/>',NULL,66717,6);
INSERT INTO stanza VALUES('F894','6','آیا پیروزمند می شوی؟<br/>تکیه کن بر او!<br/>برای پاداشِ حیات،<br/>از مُردگی دور.<br/>',NULL,66718,7);
INSERT INTO stanza VALUES('F894','7','آیا پیروزمند می شوی؟<br/>نه وِلرم، هرگز؛<br/>بینشِ بیشتر لیک نه از<br/>خود-راضی، هرگز.<br/>',NULL,66719,8);
INSERT INTO stanza VALUES('F894','8','آیا پیروزمند می شوی؟<br/>مسیح کرد صدا!<br/>وفادار به او تا شود<br/>خواسته اش اجرا.<br/>',NULL,66720,9);
INSERT INTO stanza VALUES('F907','1','نه جایی که می خواهیم،<br/>لیک هر جا عیسی گوید،<br/>آنجا آب جریان دارد،<br/>آنجا شب روز می شود.<br/>',NULL,66721,1);
INSERT INTO stanza VALUES('F907','2','نه کارهای خودسر را<br/>خداوند تصدیق کند،<br/>لیک کارِ نخواسته را<br/>برایش تمام کند.<br/>',NULL,66722,2);
INSERT INTO stanza VALUES('F907','3','نه دعای مِیلِ خود<br/>چون زانو زنیم بر تخت،<br/>لیک با ناله های روح<br/>که بیان ناشدنی ست.<br/>',NULL,66723,3);
INSERT INTO stanza VALUES('F907','4','هدیۀ ما بر مذبح<br/>را توجه نکند<br/>اگر او را رد کنیم<br/>وقتی نیازی دارد.<br/>',NULL,66724,4);
INSERT INTO stanza VALUES('F907','5','به خود مُرده، با خدا<br/>زنده هستیم در سَما؛<br/>خدمت، بخشش و دعا،<br/>مسیحْ خود، پاداشِ ما.<br/>',NULL,66725,5);
INSERT INTO stanza VALUES('F911','1','خجسته زیستنِ کاهن،<br/>مسیح همه چیزِ اوست:<br/>لباس، غذا و مسکنش<br/>و همچنین سهمِ اوست.<br/>',NULL,66726,1);
INSERT INTO stanza VALUES('F911','chorus','خجسته زیستنِ کاهن،<br/>مسیح همه چیزِ اوست:<br/>لباس، غذا و مسکنش<br/>و همچنین سهمِ اوست.<br/>',NULL,66727,2);
INSERT INTO stanza VALUES('F911','2','آن لباسِ خدمت او<br/>زیبایی خدا است؛<br/>سینه و شانه پوشِ او<br/>با جلال درخشان است.<br/>',NULL,66728,3);
INSERT INTO stanza VALUES('F911','3','مسیح را چون قربانی به<br/>خدا اهدا می کند،<br/>پس، از او برخوردار گشته<br/>و از او پُر می شود.<br/>',NULL,66729,4);
INSERT INTO stanza VALUES('F911','4','مسیح را بهرِ ابرازش<br/>چون لباس بر تن کند؛<br/>مسیح را خورَد و نوشَد،<br/>و دارای او شود.<br/>',NULL,66730,5);
INSERT INTO stanza VALUES('F911','5','مسکنِ آنها قدوس است،<br/>آن، افزایش خداست؛<br/>کاهنان باهم بنا شَند<br/>بهرِ خانۀ خدا.<br/>',NULL,66731,6);
INSERT INTO stanza VALUES('F911','6','همه سهم و زندگی و<br/>هر چیزی کاهن داراست –<br/>همه مسیح و فقط اوست،<br/>آن که شاملِ همه ست.<br/>',NULL,66732,7);
INSERT INTO stanza VALUES('F912','1','توزیعِ مسیح خدمت است<br/>به خدا و دیگران،<br/>تأمینِ وفورِ مسیح،<br/>خدمتِ اهدای اوست.<br/>',NULL,66733,1);
INSERT INTO stanza VALUES('F912','chorus','توزیعِ مسیح خدمت است<br/>به خدا و دیگران،<br/>تأمین وفورِ مسیح،<br/>خدمتِ اهدای اوست.<br/>',NULL,66734,2);
INSERT INTO stanza VALUES('F912','2','چون اسراییل که اهدا کرد<br/>از وفور سرزمین،<br/>باید محصولی از عیسی<br/>باشد در دست های ما.<br/>',NULL,66735,3);
INSERT INTO stanza VALUES('F912','3','بر مسیح کوشش باید کرد<br/>تا او را درو کنیم؛<br/>از خوراکش سرشار شویم،<br/>تا او را سهیم گردیم.<br/>',NULL,66736,4);
INSERT INTO stanza VALUES('F912','4','رُشد کنیم چون عضوِ مسیح،<br/>هر یک، عملکردِ خویش؛<br/>سهیم، بهره مند از مسیح،<br/>به بدن، مسیح بخشیم.<br/>',NULL,66737,5);
INSERT INTO stanza VALUES('F912','5','مشارکت و شهادت،<br/>نیز پرستش و خدمت،<br/>در هر کار و هر خدمتی<br/>خدمتِ راست، مسیح است.<br/>',NULL,66738,6);
INSERT INTO stanza VALUES('F913','1','کار و خدمت کن در بدن،<br/>خداوند نمایاند؛<br/>چون مقصود او هست بدن،<br/>پس پیروی باید کرد.<br/>',NULL,66739,1);
INSERT INTO stanza VALUES('F913','chorus','کار و خدمت کن در بدن،<br/>نه هرگز آزادانه؛<br/>لیک چون اعضای بدن، در<br/>عملکردی وابسته.<br/>',NULL,66740,2);
INSERT INTO stanza VALUES('F913','2','چون اعضا زنده گشته ایم،<br/>نه اعضایی مستقل؛<br/>باید با هم خدمت کنیم،<br/>مربوط و متقابل.<br/>',NULL,66741,3);
INSERT INTO stanza VALUES('F913','3','سنگ های زنده، بنا شیم<br/>بهرِ خانۀ خدا،<br/>چون کهانت خدمت کنیم،<br/>همدل و در برکت، ما.<br/>',NULL,66742,4);
INSERT INTO stanza VALUES('F913','4','پس با هم بنا شویم در<br/>خدمتِ متناسب؛<br/>چون اساس خدمتمان،<br/>شخصیتِ بدن است.<br/>',NULL,66743,5);
INSERT INTO stanza VALUES('F913','5','در خدمتگزاری و کار،<br/>از بدن تأمین شویم؛<br/>گر باشیم تنها و جدا،<br/>بی عملکرد می میریم.<br/>',NULL,66744,6);
INSERT INTO stanza VALUES('F913','6','با خدمت کردن در بدن<br/>غنای سَر شریکیم؛<br/>با عمل کردن چون اعضا<br/>کمالِ مسیح شویم.<br/>',NULL,66745,7);
INSERT INTO stanza VALUES('F913','7','در پیوندی دائم با سَر،<br/>تا با هم رشد کنیم ما،<br/>و تأمینِ حاصل از سَر<br/>به بدن رسد از ما.<br/>',NULL,66746,8);
INSERT INTO stanza VALUES('F913','8','خداوند، خود را بدهیم؛<br/>باشد دگرگون شویم،<br/>خواسته ات، شناخت بدن،<br/>و اینجا خدمت کنیم.<br/>',NULL,66747,9);
INSERT INTO stanza VALUES('F925','1','توسعۀ خبرِ خوش<br/>جريانِ حيات در ماست؛<br/>اين با شهادتمان است<br/>كه گناهكاران آیند.<br/>',NULL,66748,1);
INSERT INTO stanza VALUES('F925','chorus','خدا، دِه جريانِ زنده،<br/>حياتت پیداست از ما؛<br/>از ما ظروفِ زنده ات،<br/>شد روحِ مَردم احيا.<br/>',NULL,66749,2);
INSERT INTO stanza VALUES('F925','2','حيات است كه قانع كند<br/>تا مردم ایمان آرند؛<br/>با رساندنِ حيات است<br/>كه جان ها حيات گيرند.<br/>',NULL,66750,3);
INSERT INTO stanza VALUES('F925','3','هميشه در خدا مانيم،<br/>چون شاخه ميوه دهيم؛<br/>از لبريز شدنِ حيات،<br/>مسيح را سهیم شویم.<br/>',NULL,66751,4);
INSERT INTO stanza VALUES('F925','4','باشد که بشارتِ ما<br/>باشد زندگیِ ما؛<br/>نه فقط موعظه، اما<br/>كاشتنِ بذرِ حيات.<br/>',NULL,66752,5);
INSERT INTO stanza VALUES('F936','1','در آبهای مرگ دفن شدم،<br/>چون با منجیْ مسیح مرده ام؛<br/>حال دنیا در پیِ من نیست،<br/>چون اینجا قدرتش خنثی شد.<br/>با مسیح برخاسته ام،<br/>با او راه روم و زیست کنم؛<br/>حال روح، حیاتم دهد<br/>و قوتِ پایدارش به من دهد.<br/>',NULL,66753,1);
INSERT INTO stanza VALUES('F941','1','ملکوتِ خدا هست<br/>حکم و جلالِ او؛<br/>حکمرانی مطلقش<br/>و حفظِ نظم او.<br/>کاملاً بکار بَرَد<br/>اقتدار خود را<br/>در ملکوت خودش<br/>تا ابدالاباد.<br/>',NULL,66754,1);
INSERT INTO stanza VALUES('F941','2','بر تخت، همان مرکزِ<br/>دولتِ الهی،<br/>خدا حکم می کند و<br/>قصدش ترتیب دهد.<br/>ریاست و سَروری<br/>فقط از آنِ اوست<br/>چون شاه در ملکوتش<br/>حکم کند بر هر چیز.<br/>',NULL,66755,2);
INSERT INTO stanza VALUES('F941','3','خدا با حکمرانی اش<br/>خواست اش اجرا کند،<br/>و تحت قلمرو اش<br/>قصدش کامل کند.<br/>فقط در ملکوتش<br/>برْکتش شناسیم؛<br/>از تخت متعالش<br/>نهرِ حیات جاریست.<br/>',NULL,66756,3);
INSERT INTO stanza VALUES('F941','4','تسلیمِ حکمِ خدا،<br/>کلِ محسنات است؛<br/>طغیان بر ضد حُکمش،<br/>ریشۀ گناه است.<br/>قصد خبیث شیطان –<br/>ضد تخت خداست؛<br/>نشان و هدف ما<br/>شناختِ حکم اوست.<br/>',NULL,66757,4);
INSERT INTO stanza VALUES('F941','5','در ملکوتِ خدا<br/>مسیح ارجمند است؛<br/>چون مسیح حکم می کند،<br/>پدر جلال یابد.<br/>در قلمرو خدا،<br/>برکتِ حقیقی ست؛<br/>در حکمرانیِ مسیح،<br/>جلال ابراز شود.<br/>',NULL,66758,5);
INSERT INTO stanza VALUES('F941','6','در تکاملِ ایام<br/>مسیح حکم خواهد کرد،<br/>پس همه بپرستند<br/>از بزرگ و کوچک.<br/>حکم در حیات و جلال<br/>را کلیسا چِشَد،<br/>و تسلیم حکم او،<br/>تا ملکوت آید.<br/>',NULL,66759,6);
INSERT INTO stanza VALUES('F942','1','ملکوتِ خدا اینجا،<br/>حکمِ او درون ما است؛<br/>زیستنِ مسیح در درون،<br/>چون پادشاهِ حاکم است.<br/>',NULL,66760,1);
INSERT INTO stanza VALUES('F942','2','حیات و اقتدار او،<br/>او را در دل بر تخت نشانْد<br/>تا کلام و اعمالِ ما<br/>را در درون تنظیم کند.<br/>',NULL,66761,2);
INSERT INTO stanza VALUES('F942','3','خداوند بر تختِ دلها<br/>ملکوتش بنا نهد،<br/>با حقِ کامل برای<br/>حکمرانی و قصد خدا.<br/>',NULL,66762,3);
INSERT INTO stanza VALUES('F942','4','با حکمرانی در دلهامان،<br/>حیات به ما تأمین شود؛<br/>سَرور و پادشاه ماست،<br/>پس ما را راضی می کند.<br/>',NULL,66763,4);
INSERT INTO stanza VALUES('F942','5','با حکم کردنش از درون،<br/>کمالش بیان می شود؛<br/>چون در درون حکم می کند،<br/>بدن، کامیاب، تهذیب شود.<br/>',NULL,66764,5);
INSERT INTO stanza VALUES('F942','6','با حکم کردنش در درون،<br/>آسمانی زیست می کنیم؛<br/>با اطاعت از حکمِ او،<br/>حکمش را ابراز می کنیم.<br/>',NULL,66765,6);
INSERT INTO stanza VALUES('F942','7','در این قلمرو زیست کنیم،<br/>با قدرتِ آسمانی؛<br/>در نور راه رویم و جنگیم<br/>تا ملکوت ظاهر شود.<br/>',NULL,66766,7);
INSERT INTO stanza VALUES('F944','1','ذاتِ ملکوتْ زیستنی<br/>تحت حکمِ آسمانهاست.<br/>یک زندگیِ الهی<br/>با تجربه های مسیح.<br/>',NULL,66767,1);
INSERT INTO stanza VALUES('F944','2','فقیر در روح است این زیستن،<br/>با قلبی توبه کار و رام،<br/>پر از رحمت به دیگران<br/>و تنها جویای خدا؛<br/>',NULL,66768,2);
INSERT INTO stanza VALUES('F944','3','پسرانِ صلح جوی او<br/>بهرِ صداقت رنج کِشند،<br/>بهرِ عیسی آزار بینند،<br/>شادیِ بسیار کسب کنند؛<br/>',NULL,66769,3);
INSERT INTO stanza VALUES('F944','4','چون نمک، فساد را کُشند،<br/>در ظلمت چون نور درخشند،<br/>در دل و رفتار درستند،<br/>در عشق ادعا ندارند.<br/>',NULL,66770,4);
INSERT INTO stanza VALUES('F944','5','جلالِ خود نمی جویند<br/>جلال بر خدا می دهند؛<br/>تنها بر او تکیه کنند،<br/>جویای ملکوت باشند.<br/>',NULL,66771,5);
INSERT INTO stanza VALUES('F944','6','بر خود سختگیر، با دیگران<br/>اما همیشه مهربان،<br/>با خداست سر و کارشان،<br/>بر طبقِ حرف و خواست او.<br/>',NULL,66772,6);
INSERT INTO stanza VALUES('F944','7','راه نمی دهند به شیطان،<br/>نه به خود، گناه و دنیا،<br/>لیک تحت حکمِ آسمان،<br/>دارند اقتدارِ خدا.<br/>',NULL,66773,7);
INSERT INTO stanza VALUES('F944','8','این زیستن آوَرَد همه<br/>را تحت فرمانِ خدا؛<br/>و نزدیک کند آن لحظه<br/>که ملکوت شود پیدا.<br/>',NULL,66774,8);
INSERT INTO stanza VALUES('F945','1','پسرِ خدا کاشت خود را<br/>چون بذرِ حیات در انسان،<br/>تا ملکوتش رشد کند،<br/>طرحِ جاودان اجرا شود.<br/>',NULL,66775,1);
INSERT INTO stanza VALUES('F945','2','او تنها دانۀ گندم<br/>تولید کرد دانه ها بسیار،<br/>فرزندانِ ملکوتند،<br/>سلطۀ خدا از آنهاست.<br/>',NULL,66776,2);
INSERT INTO stanza VALUES('F945','3','لیک شیطان، دشمن خدا،<br/>بِین گندم ها علف کاشت،<br/>تا فرزندان را گیج کند،<br/>و لطمۀ بسیار زَنَد.<br/>',NULL,66777,3);
INSERT INTO stanza VALUES('F945','4','با این کارِ زیرکانه،<br/>مخلوط شد علف و گندم،<br/>پس ظاهر ملکوت هست<br/>ناهنجار و بی تناسب.<br/>',NULL,66778,4);
INSERT INTO stanza VALUES('F945','5','ملکوت باشد چون خردل،<br/>دانۀ کوچک لیک غنی،<br/>لیک تغییر کرد به یک «درخت،»<br/>یک سازماندهیِ عظیم.<br/>',NULL,66779,5);
INSERT INTO stanza VALUES('F945','6','بجای تغذیه کردن،<br/>لانۀ «پرنده ها» شد؛<br/>پس حال جاییست که شریران<br/>و شیاطین خانه سازند.<br/>',NULL,66780,6);
INSERT INTO stanza VALUES('F945','7','مذهبِ بزرگِ دنیا<br/>ظاهرش نمایان سازد،<br/>که شامل کفر و شر است،<br/>همچون خمیرْ مخلوط با آرد.<br/>',NULL,66781,7);
INSERT INTO stanza VALUES('F945','8','پس سازماندهی دنیا<br/>ظاهر آن را تغییر داد؛<br/>و با جذب چیزهای شر،<br/>در درونْ غرق شد در فساد.<br/>',NULL,66782,8);
INSERT INTO stanza VALUES('F945','9','چیزی پنهان جویَد خدا،<br/>چون «مروارید» و «گنجینه».<br/>پس ما را تبدیل کند تا<br/>آن گنجینه شود آشکار.<br/>',NULL,66783,9);
INSERT INTO stanza VALUES('F945','10','این از مذهب پنهان مانده<br/>از مسیحیت در نما،<br/>لیک پر از واقعیت است<br/>همشکل مسیح و خدا.<br/>',NULL,66784,10);
INSERT INTO stanza VALUES('F945','11','خداوند، ما را از «علف»،<br/>«درختِ» هیولا و از<br/>«خمیرِمایه» جدا ساز،<br/>تا خالصاً از تو باشیم.<br/>',NULL,66785,11);
INSERT INTO stanza VALUES('F945','12','جانمان دگرگون ساز تا<br/>چون سنگ های نفیس شویم،<br/>تا خانه ات بنا سازیم<br/>در حقیقتِ ملکوت.<br/>',NULL,66786,12);
INSERT INTO stanza VALUES('F947','1','حال يک تمرين است ملکوتِ خدا،<br/>لیک پاداشى ست بزرگ وقتی مسیح آید؛<br/>حكمتِ الهی ست حال آموزش بينيم<br/>تا عدالتش حفظ، طرحش کامل شود.<br/>',NULL,66787,1);
INSERT INTO stanza VALUES('F947','2','ما شاهيم با او، فرزندانِ خدا،<br/>بايد آموزش بينيم تا غالب شويم<br/>و دانيم چطور در ملكوت حكم كنيم؛<br/>حکم او بر همه از ما ابراز شود.<br/>',NULL,66788,2);
INSERT INTO stanza VALUES('F947','3','حال بايد يادگيريم تسليمش شويم،<br/>زندگى با انضباط، با حكومتش؛<br/>تا توانيم اقتدارش سهيم شويم،<br/>تا با آن وارث بر امتها حكم كنيم.<br/>',NULL,66789,3);
INSERT INTO stanza VALUES('F947','4','سختگير بر خود، صداقت نگه داریم،<br/>با مردم در صلح، با خدا شاد و دلير؛<br/>دائم در حقيقتِ ملكوت مانيم،<br/>تا برای حکم در آن آماده شویم.<br/>',NULL,66790,4);
INSERT INTO stanza VALUES('F947','5','چون مسيح آيد با ملكوت خود،<br/>پادشاهى اش سهيم شويم چون پاداش؛<br/>پس صداقت خدا در ما حفظ گردد<br/>و حكمتش بر قدرتها آشكار شود.<br/>',NULL,66791,5);
INSERT INTO stanza VALUES('F947','6','پس آن رسول به پیش رفت به هر بها،<br/>ملكوتْ تضمین کرد که گم نخواهد شد؛<br/>بهرِ این از ما خواست: به خدا امين باش،<br/>تا ملكوت بهرِ شما پاداش شود.<br/>',NULL,66792,6);
INSERT INTO stanza VALUES('F947','7','خدا، فيض بخش، بهرِ ملكوت باشيم،<br/>آموزش بينيم تا تو را پاداش گيريم؛<br/>در حقيقتِ ملكوت تمرین کنیم،<br/>تا ظهورش پاداشِ عالیْ مان شود.<br/>',NULL,66793,7);
INSERT INTO stanza VALUES('F948','1','رازِ پنهان حالا بر من فاش شده،<br/>آن مسیح، حقیقتِ خداست.<br/>تجسمِ خداست و حیاتِ من،<br/>امیدِ جلالم خواهد بود.<br/>',NULL,66794,1);
INSERT INTO stanza VALUES('F948','chorus','جلال، جلال، مسیح حیاتم!<br/>جلال، جلال، او چه امیدیست!<br/>حالا او رازِ درونِ روحم است!<br/>سپس جلالِ من خواهد شد.<br/>',NULL,66795,2);
INSERT INTO stanza VALUES('F948','2','در روحم تولد تازه ام داد،<br/>حال روانم دگرگون کند.<br/>بدنم را چون خودش تغییر دهد،<br/>من را کامل مثل خود کند.<br/>',NULL,66796,3);
INSERT INTO stanza VALUES('F948','3','حال در حیات و ذاتْ او با من یکیست؛<br/>پس من در او جلال خواهم یافت؛<br/>حضورش تا ابد مسرت بَرَم<br/>با او در تشابهِ کامل.<br/>',NULL,66797,4);
INSERT INTO stanza VALUES('F949','1','مسيح اميدِ جلال، او حياتِ من است،<br/>تولدِ تازه ام بخشید و اشباع كرد؛<br/>چو آید با قوت، بدنم تغییر دهد<br/>چون بدنِ پرشكوه اش در جلال!<br/>',NULL,66798,1);
INSERT INTO stanza VALUES('F949','chorus','آيد، آيد، مسيح جلالم دهد!<br/>بدنم را تبديل كند تا مثل او شود.<br/>آيد، آيد، بازخرید کار بَرَد!<br/>چون امیدِ جلال آيد، ما را جلال دهد.<br/>',NULL,66799,2);
INSERT INTO stanza VALUES('F949','2','مسيح، اميدِ جلال، او راز خدا است؛<br/>او با من سهیم شود پُریِ خدا را.<br/>آيد مرا با خدا کامل یکی کند،<br/>تا ابد سهيم شوم جلالش را.<br/>',NULL,66800,3);
INSERT INTO stanza VALUES('F949','3','مسيح، اميدِ جلال، بازخریدِ کامل:<br/>بازخریدِ بدنم، از مرگ رها کند؛<br/>آيد تا بدنم را پر از جلال سازد،<br/>پيروزى مرگ را ببلعد تا ابد.<br/>',NULL,66801,4);
INSERT INTO stanza VALUES('F949','4','مسيح اميدِ جلال، تاريخچۀ من است:<br/>حياتش تجربه ام، چون او با من يكیست؛<br/>آيد به آزادىِ پر جلال آوَرَد،<br/>تا کامل با او يک شوم تا ابد.<br/>',NULL,66802,5);
INSERT INTO stanza VALUES('F956','1','خداوند آید، آن روز نزديک شده،<br/>شنويم صداى پايش را.<br/>بايد هشيار باشيم، دائم گوش به زنگ<br/>تا با خودش ببرَد ما را.<br/>',NULL,66803,1);
INSERT INTO stanza VALUES('F956','chorus','جلال! جلال! مسيح می آيد،<br/>جلال! جلال! با او حكم كنيم!<br/>بدنى پر جلال، دائم با خدا،<br/>ستايشش خوانيم يک صدا.<br/>',NULL,66804,2);
INSERT INTO stanza VALUES('F956','2','خداوند آيد، آن ستارۀ صبح،<br/>شبْ تمام و روز طلوع كند.<br/>هيچگاه با موجِ اين عصر نمى رَويم،<br/>تا از آزمایش ها دور مانيم.<br/>',NULL,66805,3);
INSERT INTO stanza VALUES('F956','3','خداوند آيد و پاداشش با اوست؛<br/>عاشقانش شريک اند تاج را.<br/>هشيار باشيم و دنيا را نخواهيم،<br/>عاشقش، حمل کنیم بارش را.<br/>',NULL,66806,4);
INSERT INTO stanza VALUES('F956','4','خداوند آيد، در ملکوت حاکم؛<br/>شيطان در بند، دنيا رام شود.<br/>بجنگيم نبَرد، پيروزيم بر دشمن،<br/>پس برتخت ما را شامل كند.<br/>',NULL,66807,5);
INSERT INTO stanza VALUES('F957','1','بیدار باش! صبح طلوع کند،<br/>هر لحظه او خواهد آمد!<br/>مِه و سایه ها می گریزند،<br/>ظلمت ناپدید خواهد شد؛<br/>و او، انتظارِ دوران ها،<br/>خداوند، که درنگ کرده،<br/>در نورِ جلال خواهد آمد<br/>و هر لحظه ما خواهیم رفت.<br/>',NULL,66808,1);
INSERT INTO stanza VALUES('F957','2','بیدار باش! صبح طلوع کند،<br/>هر لحظه تاج حاصل شود!<br/>هر لحظه ما با او خواهیم بود،<br/>هر لحظه سفر گُذرَد!<br/>خدا، ما را بیدار نگاه دار،<br/>و ما را سزاوار شمار<br/>تا بخشی از دیدبانانِ تو<br/>باشیم، و با تو بس هشیار.<br/>',NULL,66809,2);
INSERT INTO stanza VALUES('F958','1','دیریست پس از جدایی در بِیت عَنیا،<br/>که پیوسته در قلبم خَلَائیست؛<br/>چطور از بید پایین آورم ساز را؟<br/>چطور شعرْ بی تو لذت بخش باشد؟<br/>و چون دعا کنم شب در تنهایی –<br/>بی حس به هر دو، هم غم و خوشی –<br/>وعدۀ آمدنت را یاد آرم،<br/>ای خداوند، چرا هنوز نیامدی؟<br/>',NULL,66810,1);
INSERT INTO stanza VALUES('F958','2','یادِ آخور: من نیز بی خانمانم؛<br/>صلیب مِیلِ دنیا زدود از من؛<br/>بیا، جویای شهری بهترم من،<br/>حالْ تویی هدفِ نهایی ام.<br/>چون تو رفتی رنگ باخته است خوشی ام،<br/>شعرم را به ناچار بیان کنم.<br/>چون تو رفته ای حسی تهی دارم.<br/>آه، از ته دل خواهم زودتر بیایی.<br/>',NULL,66811,2);
INSERT INTO stanza VALUES('F958','3','با اینکه حضورت را می شناسم،<br/>لیک هنوز هست در دلم کمبودی.<br/>روشنگری و نگهداری دیگر<br/>کافی نیست: می خواهم تو بازگردی.<br/>با وجودِ صلحِ درونم، تنهام؛<br/>با وجودِ شادی لیک هست آهی؛<br/>در خرسندی، اشتیاقِ دیدنت<br/>رو در رو، فریادم است که تو بازگردی.<br/>',NULL,66812,3);
INSERT INTO stanza VALUES('F958','4','چه تبعید شده ای در آرزوی<br/>وطن و مردمانش نباشد؟<br/>چه کس در غربتْ قومش از یاد بَرَد؟<br/>چه عاشقی دیدار نطلبد؟<br/>ای خداوند، چطور خوشیِ دنیا<br/>با بازگشتت مقایسه شود؟<br/>پس، گر اینجا نتوان نگریست ات،<br/>چه کنم غیر از آه کشیدن، تا آیی؟<br/>',NULL,66813,4);
INSERT INTO stanza VALUES('F958','5','فراموش توانی کرد وعده ات را<br/>که بزودی بهرِ من می آیی؟<br/>لیک روز به روز و سالهاست منتظرم،<br/>و هنوز منتظر، تا بیایی!<br/>یاد آر، خداوند، سالهای صبرم<br/>چون ردپای خوبت دور مانده است.<br/>چه وقت؟ چه مدت؟ باید صبر کنم بیش<br/>تا در نمای پرجلالت بازگردی؟<br/>',NULL,66814,5);
INSERT INTO stanza VALUES('F958','6','نسل اندر نسل مقدسین آمدند<br/>و رفتند، اما هنوز ندیدند<br/>وعدۀ پرشکوهت کامل شود.<br/>چه مدت، چه مدتِ مدیدی!<br/>چرا تشخیص ندادیم ردپایت؟<br/>چرا هنوز آسمانها مُهر است؟<br/>آه، آیا باید بیش انتظار کشیم<br/>تا در جلالِ بی نظیرت بیایی؟<br/>',NULL,66815,6);
INSERT INTO stanza VALUES('F958','7','خداوند، یادآرم سالها انتظار<br/>بهرِ بازگشتت، لیک نه تنها من،<br/>بلکه مقدسین در طی نسل ها –<br/>استدعا می کنند که بیایی.<br/>به اشکها و درخواستهای بی شمار،<br/>با ظهورت زودتر جواب بده.<br/>آه، باشد آیی، آهنگِ دوران ها،<br/>بیا، حال جواب دِه فریادِ جمعی را!<br/>',NULL,66816,7);
INSERT INTO stanza VALUES('F959','1','از وقتِ رفتنت از کوه زیتون<br/>پس چرا آمدنت طول کشید؟<br/>سالها مشتاقِ آمدنت، آیا<br/>دعاهامان به گوش ات نرسید؟<br/>',NULL,66817,1);
INSERT INTO stanza VALUES('F959','chorus','بیا، حالا:<br/>مشتاقیم که بیایی؛<br/>تنها خواستمان بازگشتِ موعودت است،<br/>باشد زودتر بیایی.<br/>',NULL,66818,2);
INSERT INTO stanza VALUES('F959','2','ای خداوند، از وقتِ صعودِ تو<br/>همه چیز اینجا خشک و بی مزه؛<br/>اغلب در دعا، اغلب در بیداری<br/>آه کشیم برای تو، هر لحظه.<br/>',NULL,66819,3);
INSERT INTO stanza VALUES('F959','3','صحنه ها زیباست، لیک کِی بینیم تو را؟<br/>گلها و بلبلها خوش و زیبا،<br/>لیک هیچ یک خرسند نمی کنند مرا،<br/>مشتاقم ببینم صورتت را.<br/>',NULL,66820,4);
INSERT INTO stanza VALUES('F959','4','عیسی، منتظرتیم بی صبرانه،<br/>چه مدت بیش طول کِشد، ندانیم؛<br/>از هر طلوع تا هر غروب، هر لحظه<br/>با امید که آمدنت را بینیم.<br/>',NULL,66821,5);
INSERT INTO stanza VALUES('F959','5','چه باران آید، و یا طوفان شود،<br/>چه ماه درخشد، دریا خروشد،<br/>هر دَم امیدواریم زودتر آیی؛<br/>چه مأیوس که اثری نبُوَد!<br/>',NULL,66822,6);
INSERT INTO stanza VALUES('F959','6','گر به خاطرِ وعده ات نمی بود،<br/>از خدمت به دور، دلسرد می شدیم؛<br/>لیک چون منتظرت هستیم، تو خواهی،<br/>بهرِ تو زندگی و کار کنیم.<br/>',NULL,66823,7);
INSERT INTO stanza VALUES('F959','7','ای خدا، روزها طولانی تر شده<br/>از وقتی که قول دادی و رفتی؛<br/>امید و باز امید، و امیدواریم<br/>که بیایی. هم امروز می آیی؟<br/>',NULL,66824,8);
INSERT INTO stanza VALUES('F960','1','شاهم بزودى بازگردد،<br/>آسمان پُر با او؛<br/>جهان که بازخرید شود<br/>ببیند نورِ او.<br/>نقشه اش كامل می کند،<br/>صداى پاش آيد؛<br/>شکلِ باشکوهش بینم<br/>که ظاهر می شود.<br/>',NULL,66825,1);
INSERT INTO stanza VALUES('F960','2','مشتاقِ حضورش هستم،<br/>نمی شه تنبل بود،<br/>بهرِ بازگشتش صبر كنم،<br/>عزيزم را بينم.<br/>تنها اميد، که او آيد،<br/>ايمانم را بینم؛<br/>هيچ خوشىِ دِگرى نيست<br/>كه شاد كند قلبم.<br/>',NULL,66826,2);
INSERT INTO stanza VALUES('F960','3','قلبِ من هميشه با اوست،<br/>چشمهام به آسمان،<br/>لبهام هيچ دِگر نگويد<br/>جُز ملاقاتمان.<br/>خدايم بزودى آید،<br/>برای من آيد؛<br/>قولِ همچون پا برجایش<br/>بينم كامل شود.<br/>',NULL,66827,3);
INSERT INTO stanza VALUES('F960','4','منجى ام، در كلامِ تو،<br/>هیچ شکی ندارم؛<br/>با تشويقِ آن روز به روز،<br/>به تو امین مانم.<br/>آه، جلالت ظاهر شود،<br/>سرنگون دشمنت؛<br/>وعده هات تحقق يابند،<br/>ما آييم به تختت.<br/>',NULL,66828,4);
INSERT INTO stanza VALUES('F960','5','بازوىِ نجاتت، منجی،<br/>برایم هست پناه؛<br/>تو چون پدر نگه دارى<br/>وابستگان ات را.<br/>گوسفندان و شبان يكى،<br/>سَر و بدن همتا؛<br/>هيچكس از دستت نگیرد<br/>اميدوارانت را.<br/>',NULL,66829,5);
INSERT INTO stanza VALUES('F960','6','هزاران دست مانع نَشَند،<br/>و نَه هزاران چشم؛<br/>خارهاى راه كمک كنند<br/>تا رِسَم به پاداش.<br/>بلند شو روح و قلبِ من،<br/>بگذار رَوَد دنيا؛<br/>خدا بزودى بَرَدم<br/>با او باشم بالا.<br/>',NULL,66830,6);
INSERT INTO stanza VALUES('F960','7','نورِ شفا، اميدمان،<br/>عاشقِ نورت ام.<br/>خداى صالح، شاهِمان،<br/>سجده، دعا كنم:<br/>آه، از تخت خود بلند و<br/>زودتر نمايان شو؛<br/>ملكوتت بنا كنى<br/>و فيضت را دهی.<br/>',NULL,66831,7);
INSERT INTO stanza VALUES('F960','8','''راستى'' پيروز و شاه شود،<br/>''آزادى،'' شهبانو؛<br/>لیک فریبکاریِ بسیار،<br/>حال سَرِ این دنياست.<br/>مى پرسيم، ''راستى،''  زود بيا،<br/>با نور از آسمان؛<br/>دشمنْ لِه و پسرانت<br/>بیار به آغوشت.<br/>',NULL,66832,8);
INSERT INTO stanza VALUES('F962','1','کِی بازمیگردد خداوندم،<br/>چهره ات را می طلبم،<br/>تا بخوانم سرودِ فتح را،<br/>بنگرم، پُر فیض محبوبم را.<br/>زودتر بیا، خداوندا!<br/>کِی بازمیگردی تسکین یابم؛<br/>زودتر بیا، خداوندا!<br/>قلبم می طلبد تو را.<br/>',NULL,66833,1);
INSERT INTO stanza VALUES('F965','1','چون بازگردد خداوندم،<br/>از دردهایم رها شوم،<br/>با قدوسان به دنبالش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>با قدوسان به دنبالش،<br/>آه، ستایش!<br/>',NULL,66834,1);
INSERT INTO stanza VALUES('F965','2','چون رو در رو ببینمش،<br/>دائم با او ساکن شوم،<br/>شاد، بِسرایم از فیض اش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>شاد، بِسرایم از فیض اش،<br/>آه، ستایش!<br/>',NULL,66835,2);
INSERT INTO stanza VALUES('F965','3','مقابلِ تخت بینم اش،<br/>تمام خواهند شد رنجهایم،<br/>ظفر باشد و شادی اش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>ظفر باشد و شادی اش،<br/>آه، ستایش!<br/>',NULL,66836,3);
INSERT INTO stanza VALUES('F965','4','آن روز شهادت دهم که<br/>برتر از مسیح هیچ چیز نیست،<br/>چه پرجلال است رُبایِش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>چه پرجلال است رُبایش،<br/>آه، ستایش!<br/>',NULL,66837,4);
INSERT INTO stanza VALUES('F965','5','باشد در او پنهان شویم،<br/>یک بوده، تقسیم نشویم،<br/>تا راضی بشود قلبش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>تا راضی بشود قلبش،<br/>آه، ستایش!<br/>',NULL,66838,5);
INSERT INTO stanza VALUES('F965','6','بیا ای شاه، خداوندم!<br/>طبق وعده دریافتم کن،<br/>و به پیروزان پاداش اش،<br/>آه، ستایش!<br/>آه، ستایش! آه، ستایش!<br/>و به پیروزان پاداش اش،<br/>آه، ستایش!<br/>',NULL,66839,6);
INSERT INTO stanza VALUES('F966','1','امیدِ جلال، مسیح بازگردد!<br/>عروج کنیم و تبدیل خواهیم شد؛<br/>با او جلال، از او لذت بریم،<br/>همانند و شکلِ او خواهیم شد.<br/>',NULL,66840,1);
INSERT INTO stanza VALUES('F966','chorus','امیدِ ما! مسیح آید!<br/>امیدِ ما! مسیح آید!<br/>عروج کنیم و تبدیل خواهیم شد؛<br/>امیدِ جلال، مسیح می آید!<br/>',NULL,66841,2);
INSERT INTO stanza VALUES('F966','2','امیدِ جلال، مسیح می آید!<br/>خلقتِ کهنه ناپدید شود،<br/>ما رهایی کامل خواهیم یافت،<br/>لذت از نجات، کامل می شود.<br/>',NULL,66842,3);
INSERT INTO stanza VALUES('F966','3','امیدِ جلال، مسیح می آید!<br/>با او بر امت ها حکم خواهیم کرد،<br/>چون کاهنان او را خدمت کنیم،<br/>پس نجاتِ کامل کسب خواهیم کرد.<br/>',NULL,66843,4);
INSERT INTO stanza VALUES('F966','4','امیدِ جلال، مسیح می آید!<br/>صبور و بیدار، وفادار مانیم،<br/>به سوی هدف به پیش رَویم تا<br/>پاداشِ ملکوت را کسب کنیم.<br/>',NULL,66844,5);
INSERT INTO stanza VALUES('F971','1','قصد خدا اینکه<br/>با ما یک شود،<br/>تا انسان، ظرفش، باز<br/>تولد یابد.<br/>حیاتِ خود دهد،<br/>ظرف را پُر کند؛<br/>انسانْ یکی با او،<br/>ابرازش کند.<br/>',NULL,66845,1);
INSERT INTO stanza VALUES('F971','2','خدا به شکلِ خود<br/>آفرید ما را،<br/>تا طرحِ او یابد<br/>تحقق در ما؛<br/>تا دریافتش کنیم،<br/>درختِ حیات،<br/>و کمالش شویم<br/>چون زوجۀ او.<br/>',NULL,66846,2);
INSERT INTO stanza VALUES('F971','3','در جریانِ حیات،<br/>دگرگون شویم<br/>به گوهری نفیس،<br/>همشکلش شویم.<br/>پس بنا شَویم چون<br/>همتای خودش،<br/>و مسکن اش شویم،<br/>راضی شه قلبش.<br/>',NULL,66847,3);
INSERT INTO stanza VALUES('F971','4','آن شهرِ قدوس است<br/>اورشلیمِ نو؛<br/>خدا، یک با انسان،<br/>خانه اش با او؛<br/>خدا محتوایش<br/>و ابرازِ او؛<br/>سهیم در جلالش،<br/>دائم یک با او.<br/>',NULL,66848,4);
INSERT INTO stanza VALUES('F971','5','خدا آن مرکز است،<br/>بر تخت حکم کند؛<br/>نیروی حیاتش،<br/>وحدت حفظ کند.<br/>با نورِ جلالش،<br/>در نور خواهیم ماند،<br/>در هماهنگی و<br/>کاملاً دلشاد.<br/>',NULL,66849,5);
INSERT INTO stanza VALUES('F971','6','او آبِ حیات است،<br/>تأمینِ غذاست؛<br/>تشنگیِ ما را<br/>راضی می کند.<br/>او معبد ماست، ما<br/>در او زیست کنیم،<br/>در حضورش او را<br/>پرستش کنیم.<br/>',NULL,66850,6);
INSERT INTO stanza VALUES('F972','1','قصدِ اصلیِ خدا<br/>یک بودن با انسان است؛<br/>خدا همه چیزِ ماست،<br/>طرحش در ما کامل است.<br/>',NULL,66851,1);
INSERT INTO stanza VALUES('F972','2','ظروفِ خاکی هستیم –<br/>روح، روان و نیز بدن<br/>خدا حیاتمان است<br/>در یک وحدتِ راستین.<br/>',NULL,66852,2);
INSERT INTO stanza VALUES('F972','3','در جریانِ حیاتش،<br/>گوهری نفیس شویم<br/>بهرِ مسکن خدا،<br/>جلالش ابراز کنیم.<br/>',NULL,66853,3);
INSERT INTO stanza VALUES('F972','4','این شهرِ ساختِ خداست،<br/>مسکنِ خواستِ خداست،<br/>همان اورشلیمِ نوست<br/>که قصدش اجرا کند.<br/>',NULL,66854,4);
INSERT INTO stanza VALUES('F972','5','بنای مقدسین،<br/>باهم، خدا و انسان،<br/>طبق هدف پدر<br/>قبل از شروعِ جهان.<br/>',NULL,66855,5);
INSERT INTO stanza VALUES('F972','6','مرکز و قدرتِ آن،<br/>تخت مسیح و خداست،<br/>و از آن، نهرِ حیات،<br/>آن روحِ زنده جاریست.<br/>',NULL,66856,6);
INSERT INTO stanza VALUES('F972','7','مسیح، درخت حیات،<br/>در جریانِ آن روح است،<br/>میوۀ حیات دهد،<br/>آن، عالی ترین غذاست.<br/>',NULL,66857,7);
INSERT INTO stanza VALUES('F972','8','خداست نورِ پرجلال<br/>که شهر را روشن کند،<br/>و این شبِ مرگبار را<br/>با نورش پایان دهد.<br/>',NULL,66858,8);
INSERT INTO stanza VALUES('F972','9','خدا و انسان در هم<br/>مسکنی مشترک اند؛<br/>انسان، حاویِ خدا،<br/>خدا را ابراز کند.<br/>',NULL,66859,9);
INSERT INTO stanza VALUES('F976','1','عیسی، بازخریدشدگان،<br/>یک بدن، عروست اند؛<br/>همان کمال و ابرازت،<br/>که بهرِ جلال توست.<br/>تو همه چیزِ او هستی،<br/>او تو را آشکار کند؛<br/>او را سرشار از خود کردی،<br/>در جلال سهیم کردی.<br/>',NULL,66860,1);
INSERT INTO stanza VALUES('F976','chorus','هان، شهرِ مقدس،<br/>با شکوهِ تابان!<br/>ابراز کاملِ خداست<br/>در انسانیت.<br/>',NULL,66861,2);
INSERT INTO stanza VALUES('F976','2','خدا با انسان آمیخته،<br/>رازِ خدایی بودن،<br/>خدا پرشکوه و تابان،<br/>و ابراز اوست انسان.<br/>این یک ظرفِ عالم گیر است<br/>خدا را ابراز کند؛<br/>زیبایی و تقدس را<br/>کاملاً آشکار سازد.<br/>',NULL,66862,3);
INSERT INTO stanza VALUES('F976','3','این یک ترکیبِ زنده است<br/>از مقدسینِ او؛<br/>چون مروارید و جواهر،<br/>شده اند همشکلِ او؛<br/>از تختِ خدا، مرکزش،<br/>آبهای زنده جاریست؛<br/>مسیح، آن درختِ حیات،<br/>پُر میوه و شکوفاست.<br/>',NULL,66863,4);
INSERT INTO stanza VALUES('F976','4','این چراغدانِ جاوید است،<br/>با مسیح چون لامپِ نور،<br/>و خدا نور جلال است<br/>که روح، تابشِ آن است!<br/>این است ابرازِ نهایی –<br/>خدا و انسان در هم؛<br/>در مسکنی متقابل،<br/>که آن هدفِ خداست.<br/>',NULL,66864,5);
INSERT INTO stanza VALUES('F979','1','درخشد شگرف و روشن،<br/>مقدس، اورشلیم نو؛<br/>مسکن خدا با انسان،<br/>عروسِ آن برّه، مسیح.<br/>',NULL,66865,1);
INSERT INTO stanza VALUES('F979','2','تمامی مقدسین،<br/>وارثانِ عهد خدا،<br/>بخشهایی از آن شهر هستند،<br/>بنای مسکن خدا.<br/>',NULL,66866,2);
INSERT INTO stanza VALUES('F979','3','شهر، مربع شکل، برابر-<br/>درازا، پهنا، بلندا؛<br/>نه بلندتر، نه کوتاهتر،<br/>و نه کج، بلکه صاف بر جا.<br/>',NULL,66867,3);
INSERT INTO stanza VALUES('F979','4','خیابانِ شهر از طلا،<br/>چون شیشهْ شفاف و روشن،<br/>گویای حیات خدا<br/>با کیفیت و ذات آن.<br/>',NULL,66868,4);
INSERT INTO stanza VALUES('F979','5','دوازده دروازۀ شهر<br/>مروارید از بازخرید اند<br/>احیا شده و دگرگون،<br/>در قلمرو خدایند.<br/>',NULL,66869,5);
INSERT INTO stanza VALUES('F979','6','دوازده پِیِ دیوارش،<br/>دوازده سنگ نفیس اند،<br/>حاصل از فشار و آتش<br/>و تا ابد پر ارزشند.<br/>',NULL,66870,6);
INSERT INTO stanza VALUES('F979','7','دیوارِ یَشم، شفاف و صاف،<br/>نشان جلال خدا؛<br/>تابان با نور الهی،<br/>که سنگِ یشم است در نما.<br/>',NULL,66871,7);
INSERT INTO stanza VALUES('F979','8','آن دیوار جدا می سازد،<br/>ناپاکی ها را مانع است؛<br/>طلا، مروارید و گوهر،<br/>تنها محتوای شهر است.<br/>',NULL,66872,8);
INSERT INTO stanza VALUES('F979','9','معبد، خدا است و برّه!<br/>روی شگرف اش بنگریم؛<br/>حضورش ترک نخواهد شد،<br/>تا ابد پرستش کنیم.<br/>',NULL,66873,9);
INSERT INTO stanza VALUES('F979','10','نه خورشید و نه ماه آنجاست،<br/>نورِ آن، جلالِ خداست؛<br/>برّه آن چراغِ شهر است،<br/>در هر سویی درخشان است.<br/>',NULL,66874,10);
INSERT INTO stanza VALUES('F979','11','از تختِ خدا و برّه،<br/>در شهر، نهرِ زنده جاریست،<br/>که در اطراف و هر سمتش<br/>درخت حیات هویداست.<br/>',NULL,66875,11);
INSERT INTO stanza VALUES('F979','12','پس حیاتِ خدا، تنها<br/>نه بهرِ غذا و آب است،<br/>لیک بُردنِ اقتدارش<br/>به گوشه کنارِ شهر است.<br/>',NULL,66876,12);
INSERT INTO stanza VALUES('F979','13','خیابانش طلای ناب،<br/>نشان ذات خدا است؛<br/>و نهری که در آن جاریست،<br/>می دهد میوۀ حیات.<br/>',NULL,66877,13);
INSERT INTO stanza VALUES('F979','14','دوازده یعنی حکومت<br/>و تکاملِ جاویدان؛<br/>حاصل از سه ضرب در چهار –<br/>نشان خدا با انسان.<br/>',NULL,66878,14);
INSERT INTO stanza VALUES('F979','15','دگر مرگ و تاریکی نیست،<br/>و خواهد گذشت رنج و درد،<br/>کهنه رفت، همه نو شود،<br/>خدا با انسان تا ابد.<br/>',NULL,66879,15);
INSERT INTO stanza VALUES('F979','16','شهر دارای شکل خداست،<br/>بهرِ پادشاه حکم کند،<br/>طرحِ جاوید اجرا کند،<br/>خدا را راضی نماید.<br/>',NULL,66880,16);
INSERT INTO stanza VALUES('F981','1','مسیحْ سَرِ همه شود،<br/>این اقتصاد خداست؛<br/>چون مسیحْ سَر، مرکز، باشد،<br/>همه یک و همسازند.<br/>',NULL,66881,1);
INSERT INTO stanza VALUES('F981','2','مرکزْ مسیحِ سَر بُوَد؛<br/>خدا در درون، نور است؛<br/>مسیحِ بر تخت، خدا درون،<br/>اجرای خواستۀ اوست.<br/>',NULL,66882,2);
INSERT INTO stanza VALUES('F981','3','مسیحِ حیات، محتوی،<br/>کل را در نور گِرد آرَد؛<br/>مقدسین آن ظرف اند تا<br/>جلالش بتابانند.<br/>',NULL,66883,3);
INSERT INTO stanza VALUES('F981','4','تزریقِ شیطان در انسان<br/>همه را تباه کرده،<br/>تاریکی، فساد، آورد و<br/>طرح خدا، رَد کرده.<br/>',NULL,66884,4);
INSERT INTO stanza VALUES('F981','5','مسیح آمد، خود را بخش کرد<br/>در انسان و نجات داد،<br/>قدرتِ مرگ و تاریکی<br/>دگر اسیر نکند.<br/>',NULL,66885,5);
INSERT INTO stanza VALUES('F981','6','از کلیسا، بدنِ او،<br/>مسیحِ سَر، گِرد آرَد؛<br/>همه به هم پیوند خورند،<br/>چه بزرگ یا کوچکند.<br/>',NULL,66886,6);
INSERT INTO stanza VALUES('F981','7','تحت سَروریِ مسیح،<br/>همه در وحدت مانند؛<br/>در تابِ نورِ کلیسا،<br/>در یگانگی مانند.<br/>',NULL,66887,7);
INSERT INTO stanza VALUES('F981','8','با مسیح چون سَر و مرکز،<br/>همه در هماهنگی؛<br/>از تابشِ بدنِ او،<br/>سهیم ایم در آزادی.<br/>',NULL,66888,8);
INSERT INTO stanza VALUES('F981','9','نه تاریکی و تباهی،<br/>نه مرگ و نه بطالت؛<br/>همه آزاد از اسارت<br/>در طولِ ابدیت.<br/>',NULL,66889,9);
INSERT INTO stanza VALUES('F984','1','همان نهرِ آبِ زنده،<br/>جاری از تختِ خدا،<br/>مشارکت دهد، سازد<br/>فاش اقتدارِ خدا.<br/>',NULL,66890,1);
INSERT INTO stanza VALUES('F984','chorus','آن نهرِ آبِ زنده،<br/>مشارکت می بخشد؛<br/>با خود اقتدار آورَد<br/>هر جا جریان پذیرد.<br/>',NULL,66891,2);
INSERT INTO stanza VALUES('F984','2','آبِ زنده همان روح است،<br/>خدا چون حیاتْ جاری؛<br/>سَروریِ او را بَرَد<br/>چون برود هر جایی.<br/>',NULL,66892,3);
INSERT INTO stanza VALUES('F984','3','آن در کوی طلا جاریست،<br/>پس فاش می سازد راه را؛<br/>چون در ذاتِ خدا جاریست،<br/>پس در راهش مانیم ما.<br/>',NULL,66893,4);
INSERT INTO stanza VALUES('F984','4','درختِ حیاتْ نزد نهر،<br/>خدا خوراکمان است؛<br/>ما نزد جریانِ نهریم،<br/>سیر از نعمتِ درخت.<br/>',NULL,66894,5);
INSERT INTO stanza VALUES('F986','1','مسیح بازخریدِ کامل:<br/>چه منجیِ شگرفی!<br/>ما را خرید! بها را داد:<br/>چه منجیِ شگرفی!<br/>',NULL,66895,1);
INSERT INTO stanza VALUES('F986','chorus','چه منجیِ شگرفیست عیسی<br/>منجیِ من؛<br/>چه منجیِ شگرفیست عیسی<br/>خدایم.<br/>',NULL,66896,2);
INSERT INTO stanza VALUES('F986','2','ستایم بهرِ خونْ او را،<br/>چه منجیِ شگرفی!<br/>مرا آشتی داد با خدا،<br/>چه منجیِ شگرفی!<br/>',NULL,66897,3);
INSERT INTO stanza VALUES('F986','3','شسته از گناهان مرا:<br/>چه منجیِ شگرفی!<br/>حکم کند در درون حالا؛<br/>چه منجیِ شگرفی!<br/>',NULL,66898,4);
INSERT INTO stanza VALUES('F986','4','روز به روز در من زیست کند،<br/>چه منجیِ شگرفی!<br/>وفادار نگاهم دارد،<br/>چه منجیِ شگرفی!<br/>',NULL,66899,5);
INSERT INTO stanza VALUES('F986','5','دهد قدرتِ پیروزی،<br/>چه منجیِ شگرفی!<br/>و غالب در هر ستیزی،<br/>چه منجیِ شگرفی!<br/>',NULL,66900,6);
INSERT INTO stanza VALUES('F986','6','قلبم کامل به او دهم،<br/>چه منجیِ شگرفی!<br/>به دنیا جا نمی دهم،<br/>چه منجیِ شگرفی!<br/>',NULL,66901,7);
INSERT INTO stanza VALUES('F998','1','مسیح یک شد با مجرمین،<br/>شریک در زندگیِ ما؛<br/>مصلوب شد بهرِ مجرمین،<br/>حیاتِ عالی داد به ما.<br/>',NULL,66902,1);
INSERT INTO stanza VALUES('F998','chorus','مسیح آمد بهرِ ما<br/>مسیح جان داد بهرِ ما<br/>برای ما، برای ما.<br/>آمد، جان داد بهرِ ما.<br/>',NULL,66903,2);
INSERT INTO stanza VALUES('F1003','1','چرا بترسم، شک کنم؟<br/>آیا خداوند حمل نکرد<br/>گناهان من را؟<br/>قرضم را که مسیح پرداخت،<br/>مگر خدا دو فکر دارد<br/>که پس گیرد آن را؟<br/>',NULL,66904,1);
INSERT INTO stanza VALUES('F1003','2','خداوند بازخرید نمود،<br/>قرضهام را کامل پرداخت کرد،<br/>آزاد از شریعت.<br/>از خشم خدا نترسم،<br/>چون با خون پاشیده شدم،<br/>آن پوششِ من است.<br/>',NULL,66905,2);
INSERT INTO stanza VALUES('F1003','3','بهرِ من بخشش حاصل کرد،<br/>بخشودگی بدست آمد،<br/>پرداخت کرد قرضهایم؛<br/>خدا طلب نکند هم<br/>از پسرش، ضامنِ من،<br/>و همچنین از من.<br/>',NULL,66906,3);
INSERT INTO stanza VALUES('F1003','4','حال راحت، آرامش دارم،<br/>منجیْ مسیح انجام داد و<br/>کاملاً آزاد کرد؛<br/>با خونِ مؤثرِ او<br/>خدا محکومم نکند،<br/>او برای من مُرد!<br/>',NULL,66907,4);
INSERT INTO stanza VALUES('F1007','1','نزد عیسی رفته ای تا پاک شوی؟<br/>آیا شُستی در خون برّه؟<br/>آیا هم اکنون بر او تکیه کردی؟<br/>آیا شُستی در خون برّه؟<br/>',NULL,66908,1);
INSERT INTO stanza VALUES('F1007','chorus','آیا شسته شدی<br/>در خونِ پاکیزه کننده؟<br/>جامه ات بی لک و سفید چون برف هست؟<br/>آیا شستی در خون برّه؟<br/>',NULL,66909,2);
INSERT INTO stanza VALUES('F1007','2','روزانه تو با منجی راه میروی؟<br/>آیا شُستی در خون برّه؟<br/>آیا در مصلوب شده آرام داری؟<br/>آیا شُستی در خون برّه؟<br/>',NULL,66910,3);
INSERT INTO stanza VALUES('F1007','3','چون داماد آید، ردایت سفید است؟<br/>آیا شُستی در خون برّه؟<br/>حاضری بهرِ حضورِ پرنورَش،<br/>آیا شُستی در خون برّه؟<br/>',NULL,66911,4);
INSERT INTO stanza VALUES('F1007','4','جامه ای که با گناه لک است دور کن،<br/>شستشو دِه در خون برّه؛<br/>بهرِ جان که ناپاک است، چشمه ای هست،<br/>شستشو دِه در خون برّه.<br/>',NULL,66912,5);
INSERT INTO stanza VALUES('F1008','1','چه گناهم را شوید؟<br/>فقط خون پاک عیسی؛<br/>چه مرا کامل کند؟<br/>فقط خون پاک عیسی.<br/>',NULL,66913,1);
INSERT INTO stanza VALUES('F1008','chorus','اوه! نهرِ پر بها<br/>که پاک كند مرا؛<br/>ندانم چشمه ای،<br/>به جز خون پاک عیسی!<br/>',NULL,66914,2);
INSERT INTO stanza VALUES('F1008','2','بهرِ پاکی ام بینم<br/>فقط خون پاک عیسی!<br/>تنها راهِ بخششم<br/>فقط خون پاک عیسی!<br/>',NULL,66915,3);
INSERT INTO stanza VALUES('F1008','3','هیچ گناهم نشوید –<br/>فقط خون پاک عیسی!<br/>فیضِ اوست، نه کارِ ما –<br/>فقط خون پاک عیسی.<br/>',NULL,66916,4);
INSERT INTO stanza VALUES('F1008','4','آرامش و امیدم –<br/>فقط خون پاک عیسی!<br/>صداقتم همین است –<br/>فقط خون پاک عیسی!<br/>',NULL,66917,5);
INSERT INTO stanza VALUES('F1017','1','مسيحْ ذاتِ انسان پوشيد و انسانی شد چون من،<br/>مُرد بر روى صليب تا من از آدم رها شوم،<br/>برخاست و چون روحْ آمد تا در من زندگى كند<br/>تا حياتم شود.<br/>',NULL,66918,1);
INSERT INTO stanza VALUES('F1017','chorus','جلال! جلال! هللوياه!<br/>جلال! جلال! هللوياه!<br/>جلال! جلال! هللوياه!<br/>مسيحْ حال حياتم!<br/>',NULL,66919,2);
INSERT INTO stanza VALUES('F1017','2','مسيحْ ذاتِ انسان پوشيد و انسانی شد چون من،<br/>مُرد بر روى صليب تا من از آدم رها شوم،<br/>برخاست و چون روحْ آمد تا در من زندگى كند<br/>تا حياتم شود.<br/>',NULL,66920,3);
INSERT INTO stanza VALUES('F1017','chorus','پيروز! پيروز! هللوياه!<br/>پيروز! پيروز! هللوياه!<br/>پيروز! پيروز! هللوياه!<br/>مسيحْ همه چيزم!<br/>',NULL,66921,4);
INSERT INTO stanza VALUES('F1024','1','منجیْ مسیح، تنها نیازِ توست،<br/>او تجسمِ خداست، چون انسان<br/>در بدنش رنجِ بسیار کشید<br/>و مُرد تا پاک شی از گناه،<br/>نیازت عیساست!<br/>',NULL,66922,1);
INSERT INTO stanza VALUES('F1024','chorus','نیازت عیساست! نیازت عیساست!<br/>همه نیازش دارند!<br/>نیاز بهرِ بازخرید،<br/>نیاز بهرِ نجاتت!<br/>بهرِ حیاتِ جاوید،<br/>نیازت عیساست!<br/>',NULL,66923,2);
INSERT INTO stanza VALUES('F1024','2','برخاست و به آسمان صعود کرد،<br/>تا حیاتِ ابدی ببخشد؛<br/>دریافتش کن، ایمان آر در قلبت،<br/>در او رفع شود نیازت،<br/>نیازت عیساست!<br/>',NULL,66924,3);
INSERT INTO stanza VALUES('F1024','3','قلبت را با نور روشن خواهد کرد،<br/>ببخشد و رهایی ات دهد؛<br/>با خونش لکه هایت پاک کند،<br/>حیات خدا را دهد،<br/>نیازت عیساست!<br/>',NULL,66925,4);
INSERT INTO stanza VALUES('F1024','4','در زندگیْت کمبودی حس کنی،<br/>که در طی سالها زیاد شده؛<br/>تنها عیسی نیازت رفع کند،<br/>کمبودها را جبران کند،<br/>نیازت عیساست!<br/>',NULL,66926,5);
INSERT INTO stanza VALUES('F1024','chorus','نیازت عیساست! نیازت عیساست!<br/>همه نیازش دارند!<br/>بهرِ گریز از پوچی،<br/>بهرِ کسبِ حقیقت،<br/>بهرِ زندگیِ پُر،<br/>نیازت عیساست!<br/>',NULL,66927,6);
INSERT INTO stanza VALUES('F1024','5','حال این دنیا پُر است از درد و رنج،<br/>در زحمتها هیچ نوع تضمینی نیست؛<br/>همه تُهی ست، بر چه تکیه کنی؟<br/>همه چیز گواهی دهد:<br/>نیازت عیساست!<br/>',NULL,66928,7);
INSERT INTO stanza VALUES('F1025','1','وِل کن دنیا، کسب کن مسیح،<br/>او نیازِ قلبت است؛<br/>چه چیزْ دگر خواهی یا جویی؟<br/>چیزهای دیگر تهی ست!<br/>',NULL,66929,1);
INSERT INTO stanza VALUES('F1025','chorus','بسیار غنی ست، بسیار کامل،<br/>نیازهایت رفع کند!<br/>بسیار نیکوست، بسیار شیرین،<br/>از نیاز فراتر رَوَد!<br/>',NULL,66930,2);
INSERT INTO stanza VALUES('F1025','2','وِل کن دنیا، کسب کن مسیح،<br/>همان که لازم داری؛<br/>وقتی مسیح را دریافت کنی،<br/>چیزی دیگر نخواهی.<br/>',NULL,66931,3);
INSERT INTO stanza VALUES('F1025','3','دنیا با این که بزرگ است،<br/>و کوچک است دل ما،<br/>لیک دنیا با کل داراییش<br/>پر نکرد دل ما را.<br/>',NULL,66932,4);
INSERT INTO stanza VALUES('F1025','4','کسبِ مسیح، کسبِ شادیست؛<br/>بدون او، دردناک است؛<br/>مسیح هر جاست آنجا صبح است؛<br/>جایی که نیست، شب باقیست.<br/>',NULL,66933,5);
INSERT INTO stanza VALUES('F1040','1','بشنو، منجی در زد، در زد،<br/>درِ دلت را!<br/>آه، خود را سخت مکن، مکن،<br/>رَوَد از اینجا.<br/>برخیز، دلت را باز کن،<br/>او را بِدِه راه؛<br/>به تو حیات بخشد، بخشد،<br/>آمرزد گناه.<br/>',NULL,66934,1);
INSERT INTO stanza VALUES('F1040','chorus','راهش دِه! راهش دِه!<br/>زَنَد دَرِ دل را؛<br/>راهش دِه! آه، راهش دِه!<br/>راه بِدِه او را.<br/>',NULL,66935,2);
INSERT INTO stanza VALUES('F1040','2','چرا کنی تأخیر، تأخیر،<br/>او در انتظار؟<br/>مهربان است، فیض-بخش، فیض-بخش،<br/>رحیم و عزیز.<br/>بشنو صدای او را،<br/>نشکن دلش را؛<br/>بگذار شود داخل، داخل،<br/>فیض بخشد تو را.<br/>',NULL,66936,3);
INSERT INTO stanza VALUES('F1048','1','همین گونه، بدون عُذر،<br/>اما خون ات بهرِ من ریخت،<br/>و خواهی نزد تو آیم،<br/>برّه خدا، آیم! آیم!<br/>',NULL,66937,1);
INSERT INTO stanza VALUES('F1048','2','همین گونه، بدون صبر<br/>تا جانم پاکیزه شود؛<br/>به تو که خون ات پاک کند،<br/>برّه خدا، آیم، آیم!<br/>',NULL,66938,2);
INSERT INTO stanza VALUES('F1048','3','همین گونه، اما خسته<br/>با نبرد و شَکِ بسیار؛<br/>جنگ در درون، ترس از بیرون،<br/>برّه خدا، آیم، آیم!<br/>',NULL,66939,3);
INSERT INTO stanza VALUES('F1048','4','همین گونه، فقیر، پست، کور؛<br/>نور، غنایم، شفایِ ذهن؛<br/>هر چه خواهم، در تو یابم،<br/>برّه خدا، آیم، آیم!<br/>',NULL,66940,4);
INSERT INTO stanza VALUES('F1048','5','همین گونه، دریافت کنی،<br/>آیی، بخشی، آزاد کنی،<br/>چون وعده ات باور کنم،<br/>برّه خدا، آیم، آیم!<br/>',NULL,66941,5);
INSERT INTO stanza VALUES('F1048','6','همین گونه، عشقت عظیم،<br/>شکسته هر مانعی را؛<br/>حالا تنها از تو باشم،<br/>برّه خدا، آیم، آیم!<br/>',NULL,66942,6);
INSERT INTO stanza VALUES('F1050','1','از اسارت، غم و تاریکی،<br/>عیسی، آیم! عیسی، آیم!<br/>به آزادی، شادی و نورَت،<br/>عیسی، آیم نزدت!<br/>از مرض، به سلامتِ تو،<br/>از تنگدستی، به غنای تو،<br/>از گناه، به درون خودت،<br/>عیسی، آیم نزدت!<br/>',NULL,66943,1);
INSERT INTO stanza VALUES('F1050','2','از شکست و زیانِ ننگین،<br/>عیسی، آیم! عیسی، آیم!<br/>به سودِ شگرفِ صلیبت،<br/>عیسی، آیم نزدت!<br/>از غمها، سوی مرهمِ تو،<br/>از طوفان، سوی آرامِ تو،<br/>از اندوه، به سرودی سرمَست،<br/>عیسی، آیم نزدت!<br/>',NULL,66944,2);
INSERT INTO stanza VALUES('F1050','3','از آشوب، تکبر و غرور،<br/>عیسی، آیم! عیسی، آیم!<br/>به ارادۀ پر برکتت،<br/>عیسی، آیم نزدت!<br/>از خود، به سکونت در عشقت،<br/>از دلسردی، به وجد در روحت،<br/>بالا با بالها چون کبوتر،<br/>عیسی، آیم نزدت!<br/>',NULL,66945,3);
INSERT INTO stanza VALUES('F1050','4','از ترس و دلواپسی از قبر،<br/>عیسی، آیم! عیسی، آیم!<br/>به شادی و سُرور خودت،<br/>عیسی، آیم نزدت!<br/>از عمقِ ویرانیِ بی حد،<br/>به انبوهِ آغوشِ عشقت،<br/>ببینم روی پرجلالت،<br/>عیسی، آیم نزدت!<br/>',NULL,66946,4);
INSERT INTO stanza VALUES('F1051','1','صدایت شنوم،<br/>مرا فرا خوانی،<br/>بهرِ پاک کردن با خون ات<br/>که در جلجتا ریخت.<br/>',NULL,66947,1);
INSERT INTO stanza VALUES('F1051','chorus','آیم، خداوند،<br/>حال آیم نزدت:<br/>پاک کن مرا با خونت<br/>که در جلجتا ریخت.<br/>',NULL,66948,2);
INSERT INTO stanza VALUES('F1051','2','ضعیف و پست آیم،<br/>لیک دهی قوتم؛<br/>مرا کلاً پاک کنی تا<br/>پاک و خالص شوم.<br/>',NULL,66949,3);
INSERT INTO stanza VALUES('F1051','3','عیسی تأیید کند<br/>کار درونی را،<br/>با افزودنِ فیض بر فیض،<br/>جای حکم گناه.<br/>',NULL,66950,4);
INSERT INTO stanza VALUES('F1051','4','او شهادت دهد<br/>به قلب هایِ امین،<br/>که وعده ها اجرا شوند،<br/>گر خواهید با ایمان.<br/>',NULL,66951,5);
INSERT INTO stanza VALUES('F1051','5','درود، خونِ فِدیه!<br/>درود، حیاتِ فیض!<br/>درود، هدیۀ مسیحا،<br/>قوت و صداقت.<br/>',NULL,66952,6);
INSERT INTO stanza VALUES('F1059','1','عیسی، نزد صلیبت<br/>مانم؛ چشمه ای هست<br/>مجانی – نهرِ شفاست،<br/>از جلجتا جاریست.<br/>',NULL,66953,1);
INSERT INTO stanza VALUES('F1059','chorus','در صلیب، در صلیب،<br/>در آن است فخرِ من؛<br/>از آن جدا نشوم،<br/>فدیه شد جان من.<br/>',NULL,66954,2);
INSERT INTO stanza VALUES('F1059','2','نزد صلیب محبت<br/>و رحمت یافت مرا؛<br/>نورِ ستارۀ صبح<br/>بر من تابید آنجا.<br/>',NULL,66955,3);
INSERT INTO stanza VALUES('F1059','3','صلیب! برّۀ خدا،<br/>در پیشم صحنه اش؛<br/>یاری ده راه روم من<br/>در زیر سایه اش.<br/>',NULL,66956,4);
INSERT INTO stanza VALUES('F1059','4','نزدِ صلیب صبر کنم،<br/>با امید، اعتماد،<br/>تا منجی ام را بینم،<br/>در حضورش مانم .<br/>',NULL,66957,5);
INSERT INTO stanza VALUES('F1061','1','بیا به قلبم، آه ای عیسی،<br/>بیا به قلبم، خدا؛<br/>جانم آشفته و خسته است،<br/>بیا به قلبم حالا.<br/>',NULL,66958,1);
INSERT INTO stanza VALUES('F1061','chorus','به قلب من، به قلب من،<br/>بیا به قلبم، ای عیسی؛<br/>بیا حالا، بیا بمان،<br/>بیا به قلبم، ای عیسی.<br/>',NULL,66959,2);
INSERT INTO stanza VALUES('F1061','2','بیا به قلبم، آه ای عیسی،<br/>نیازت دارم اینجا؛<br/>بار گناه خیلی سنگین است،<br/>بمان در قلبم، بیا.<br/>',NULL,66960,3);
INSERT INTO stanza VALUES('F1061','3','بیا به قلبم، آه ای عیسی،<br/>جانم پاک و روشن کن؛<br/>مرا با روح خودت پر کن،<br/>بیا و کنترل کن.<br/>',NULL,66961,4);
INSERT INTO stanza VALUES('F1065','1','چه نجات بزرگی!<br/>چه نجات بزرگی!<br/>چه نجات بزرگی!<br/>عیسی نجات است!<br/>',NULL,66962,1);
INSERT INTO stanza VALUES('F1065','chorus','عیسی هر بند شِکنَد!<br/>عیسی هر بند شِکنَد!<br/>عیسی هر بند شِکنَد!<br/>عیسی آزادی ست!<br/>',NULL,66963,2);
INSERT INTO stanza VALUES('F1065','2','گناهانم را بخشید!<br/>زنجیرهایم را گسست!<br/>صلحِ آسْمانی بخشید!<br/>عیسی نجات است!<br/>',NULL,66964,3);
INSERT INTO stanza VALUES('F1065','3','نه گناه و وسوسه،<br/>نه اذیت های شیطان،<br/>نه لذت های دنیا<br/>اسیرم کند!<br/>',NULL,66965,4);
INSERT INTO stanza VALUES('F1065','4','می خوانم هللویاه!<br/>می خوانم هللویاه!<br/>می خوانم هللویاه!<br/>عیسی نجات است!<br/>',NULL,66966,5);
INSERT INTO stanza VALUES('F1066','1','بر صلیب جایی که منجی مُرد،<br/>جایی که از گناه گِریستم،<br/>آن خون بکار رفت بر گناهم؛<br/>جلال بر نامش!<br/>',NULL,66967,1);
INSERT INTO stanza VALUES('F1066','chorus','جلال بر نامش،<br/>جلال بر نامش؛<br/>آن خون بکار رفت بر گناهم؛<br/>جلال بر نامش!<br/>',NULL,66968,2);
INSERT INTO stanza VALUES('F1066','2','نجات پیدا کردم از گناه،<br/>در درونْ چه شیرین است عیسی؛<br/>او بر صلیب پذیرفت مرا؛<br/>جلال بر نامش.<br/>',NULL,66969,3);
INSERT INTO stanza VALUES('F1066','3','آن چشمه از گناه رهانَد.<br/>با شادی در آن وارد شدم؛<br/>آنجا عیسی نجات و پاکی ست؛<br/>جلال بر نامش.<br/>',NULL,66970,4);
INSERT INTO stanza VALUES('F1066','4','بیا به این چشمۀ غنی؛<br/>جانت افکن بر پای منجی؛<br/>در آن فرو رو و کامل شو؛<br/>جلال بر نامش.<br/>',NULL,66971,5);
INSERT INTO stanza VALUES('F1068','1','با مِهر جویای من بود،<br/>خسته، پر از گناه،<br/>بر شانه هایش آورد<br/>به گله اش مرا.<br/>چون ملائک می سرودند<br/>در طنینِ آسمانی.<br/>',NULL,66972,1);
INSERT INTO stanza VALUES('F1068','chorus','آه، عشق، جویای من!<br/>آه، خون، بهای من!<br/>آه، فیض مرا به گله آورد،<br/>آن فیضِ شگرف مرا آورد!<br/>',NULL,66973,2);
INSERT INTO stanza VALUES('F1068','2','زخمِ  گناهان را شُست،<br/>و بر آن مرهم ریخت؛<br/>و اطمینان داد مرا:<br/>«تو مال من هستی.»<br/>این دلپذیرترین ندا،<br/>دلِ شکسته ام شاد کرد.<br/>',NULL,66974,3);
INSERT INTO stanza VALUES('F1068','3','جای میخ را نشان داد،<br/>بهرِ من ریخت خونش؛<br/>تاجی ساختگی از خار<br/>نهادند بر سرش:<br/>فکر کردم چه دید در من، که<br/>این رنج را متحمل شد.<br/>',NULL,66975,4);
INSERT INTO stanza VALUES('F1068','4','در حضورش نشستم،<br/>در روی تابانش،<br/>و با شگرف و تحسین<br/>یاد آرم برکاتش.<br/>گویی این روزها کوتاهند<br/>بهرِ او را ستاییدن.<br/>',NULL,66976,5);
INSERT INTO stanza VALUES('F1068','5','در گذرِ لحظه ها،<br/>حالا آسایش است؛<br/>در انتظار صبحم،<br/>آن روزِ بهترین،<br/>ما را بخواند نزد خویش،<br/>تا با او باشیم، عروسش.<br/>',NULL,66977,6);
INSERT INTO stanza VALUES('F1073','1','بشنو، این است رازِ نهان،<br/>پنهان از تاریخِ انسان!<br/>بشنو و برگیر این راز را،<br/>یک با تو مسیحا!<br/>جلال، جلال، هللویاه!<br/>جلال، جلال، هللویاه!<br/>بشنو و برگیر این راز را،<br/>یک با تو مسیحا!<br/>',NULL,66978,1);
INSERT INTO stanza VALUES('F1074','1','آه عجب رازی است که منجی<br/>با من یکیست!<br/>آه عجب نجاتیست که خدا<br/>در پسر به من داد!<br/>هللویاه! هللویاه!<br/>رازِ پر جلال!<br/>هیچ چیز نتواند من را از<br/>عیسی جدا کند!<br/>',NULL,66979,1);
INSERT INTO stanza VALUES('F1080','1','زحمت را چه سود است اینجا؟<br/>چیزی تازه نیست بهرِ ما!<br/>فراموش کن گذشته را،<br/>این بطالت است!<br/>',NULL,66980,1);
INSERT INTO stanza VALUES('F1080','chorus','بطالت! بطالت!<br/>بطالت! بطالت!<br/>در تعقیبِ باد،<br/>همه بطالت!<br/>',NULL,66981,2);
INSERT INTO stanza VALUES('F1080','2','زندگی پر از رنج  و درد،<br/>حکمت بر اندوه افزاید!<br/>دانشِ بیشْ رنج آورَد،<br/>این بطالت است!<br/>',NULL,66982,3);
INSERT INTO stanza VALUES('F1080','3','لذت و ثروت را چه سود؟<br/>با داشتن خانواده<br/>هنوز نگرانی باقیست،<br/>این بطالت است!<br/>',NULL,66983,4);
INSERT INTO stanza VALUES('F1080','4','روزها رنج، شبها ناآرام:<br/>چیزها بسیار ولی همه<br/>هنگام مرگ نابود شود،<br/>این بطالت است!<br/>',NULL,66984,5);
INSERT INTO stanza VALUES('F1080','5','خدا را این روزها یاد آر!<br/>خداترس باش، او را کسب کن!<br/>با او رضایت یابی چون<br/>او بطالت نیست!<br/>',NULL,66985,6);
INSERT INTO stanza VALUES('F1080','chorus','بی مسیح، بطالت!<br/>با مسیح، منفعت!<br/>همه باطل است؛<br/>مسیح سودمند است!<br/>',NULL,66986,7);
INSERT INTO stanza VALUES('F1081','1','ای پدر، منبعِ حیاتی.<br/>ما فرزندان، ابرازِ تو؛<br/>مِلکِ خوبِ ما، نامِ تو.<br/>ای پدر، منبعِ حیاتی.<br/>',NULL,66987,1);
INSERT INTO stanza VALUES('F1081','chorus','در حیاتت، در حیاتت،<br/>در حیاتت يک هستيم.<br/>در حیاتت، درحیاتت،<br/>در حیاتت، پدر، یک هستیم.<br/>',NULL,66988,2);
INSERT INTO stanza VALUES('F1081','2','شکر بهرِ كلامِ قدوست<br/>با ذاتت سیراب می کند؛<br/>از دنیا جدا می سازد.<br/>شکر بهرِ کلامِ قدوست.<br/>',NULL,66989,3);
INSERT INTO stanza VALUES('F1081','chorus','در کلامت، در کلامت،<br/>در کلامت يک هستيم.<br/>در کلامت، در کلامت،<br/>در کلامت همه یک شدیم.<br/>',NULL,66990,4);
INSERT INTO stanza VALUES('F1081','3','جلالِ خدای سه-یکتا!<br/>مبارکْ ما پسرانش!<br/>جلالش نمایان سازیم –<br/>جلالِ خدای سه-یکتا!<br/>',NULL,66991,5);
INSERT INTO stanza VALUES('F1081','chorus','درجلالت، در جلالت،<br/>در جلالت یک هستیم.<br/>در جلالت، در جلالت،<br/>در جلالت همه یک شدیم.<br/>',NULL,66992,6);
INSERT INTO stanza VALUES('F1083','1','چه نزدیک است خداوند به خوانندگانش!<br/>چون خوانیم، به ما نیرو می بخشد حضورش.<br/>سراغش گیر، مهیاست؛ بخوانش، نزدیک است –<br/>خواندنش چه تسکینی برای دلهای ماست!<br/>',NULL,66993,1);
INSERT INTO stanza VALUES('F1083','chorus','عیسی! عجب نامی!<br/>ای خداوند! حیات بخشی!<br/>نامِ پیروز، و پرجلال،<br/>نامِ والا، عجب نامی!<br/>عیسی! نامِ قوی!<br/>ای خداوند! تسکین دهی!<br/>نامت چون دعاست، نفَس در هر جاست،<br/>«خداوندْ عیسی!» عجب نامی!<br/>',NULL,66994,2);
INSERT INTO stanza VALUES('F1083','2','نام عیسی را بخوان و نجات خواهد داد،<br/>ای خداوند، هللویاه، نه هرگز در بند!<br/>جام نجات را برگیر با خواندن عیسی؛<br/>نام عزیزش نجات دهد از خیلی چیزها.<br/>',NULL,66995,3);
INSERT INTO stanza VALUES('F1083','3','برای خداوند همگی یکسان هستند؛<br/>او غنی ست به هر کسی که نامش را خواند.<br/>خداوندْ عیسی، خوش است خواندن و زیستن ات؛<br/>هرگاه نفَس می کشیم ما نام لذت بخش ات.<br/>',NULL,66996,4);
INSERT INTO stanza VALUES('F1083','4','در خدای نجاتمان شادی می کنیم،<br/>در شادی یا غم، مدام نام او را خوانیم.<br/>نامش را تا دَمِ آخر صدا خواهم زد،<br/>چون گوش سپرده است و به وفور فیض می بخشد.<br/>',NULL,66997,5);
INSERT INTO stanza VALUES('F1083','5','نامِ لایقِ ستایشش را بخوانیم؛<br/>و ما از او در پرستش قدردانی کنیم.<br/>ما در هر کجا نامش را صدا می زنیم<br/>با مقدسین که از قلبی خالص می خوانند.<br/>',NULL,66998,6);
INSERT INTO stanza VALUES('F1084','1','نامَت چون مرهمِ جاريست:<br/>عيسى، عيسى، عيسى، عيسى!<br/>نامَت چون مرهمِ جاريست،<br/>نامَت چون مرهمِ جاريست.<br/>',NULL,66999,1);
INSERT INTO stanza VALUES('F1084','2','لذا عاشقتند پاكان:<br/>عيسى، عيسى، عيسى، عيسى!<br/>لذا عاشقتند پاكان،<br/>لذا عاشقتند پاكان.<br/>',NULL,67000,2);
INSERT INTO stanza VALUES('F1084','3','عشقت بهتر از شراب است:<br/>عيسى، عيسى، عيسى، عيسى!<br/>عشقت بهتر از شراب است،<br/>عشقت بهتر از شراب است.<br/>',NULL,67001,3);
INSERT INTO stanza VALUES('F1084','4','جذبم كن، دنبالت دَويم:<br/>عيسى، عيسى، عيسى، عيسى!<br/>جذبم كن، دنبالت دَويم،<br/>جذبم كن، دنبالت دَويم.<br/>',NULL,67002,4);
INSERT INTO stanza VALUES('F1084','5','ای محبوبم، دلربایی:<br/>عيسى، عيسى، عيسى، عيسى!<br/>ای محبوبم، دلربایی،<br/>ای محبوبم، دلربایی.<br/>',NULL,67003,5);
INSERT INTO stanza VALUES('F1084','6','یافتم محبوبِ جانم را:<br/>عيسى، عيسى، عيسى، عيسى!<br/>یافتم محبوبِ جانم را،<br/>يافتم محبوبِ جانم را.<br/>',NULL,67004,6);
INSERT INTO stanza VALUES('F1084','7','گیرم، رهایش نكنم:<br/>عيسى، عيسى، عيسى، عيسى!<br/>گیرم، رهایش نكنم،<br/>گیرم، رهایش نكنم.<br/>',NULL,67005,7);
INSERT INTO stanza VALUES('F1084','8','زودتر بیا محبوب من:<br/>عيسى، عيسى، عيسى، عيسى!<br/>زودتر بیا محبوب من،<br/>زودتر بيا محبوب من.<br/>',NULL,67006,8);
INSERT INTO stanza VALUES('F1084','9','عاشقتيم با دل و جان:<br/>عيسى، عيسى، عيسى، عيسى!<br/>عاشقتيم با دل و جان،<br/>عاشقتيم با دل و جان.<br/>',NULL,67007,9);
INSERT INTO stanza VALUES('F1085','1','نام او عجیب است؛<br/>نام او مشاور،<br/>خداى مقتدر،<br/>خدایم عیسی.<br/>',NULL,67008,1);
INSERT INTO stanza VALUES('F1085','2','فرزند و پسر است؛<br/>پدرِ اَبَدیست؛<br/>شاهِ آرامشم،<br/>خدایم عیسی.<br/>',NULL,67009,2);
INSERT INTO stanza VALUES('F1085','3','ستایش او را،<br/>عیسی منجی را،<br/>حال روحِ حیات بخش.<br/>در روح بپِرستش،<br/>با عشق ستایَش؛<br/>نام او عجیب است،<br/>خدایم عیسی.<br/>',NULL,67010,3);
INSERT INTO stanza VALUES('F1086','1','آه، نامَش را دوست داریم،<br/>آن نامِ عیسی!<br/>بالاتراز هر نام در<br/>زمین و سَما.<br/>تا نامَش نَفَس کشیم،<br/>نمانَد مرگ و تاریکی؛<br/>چون خوانیم نامَش و دریافتش کنیم!<br/>',NULL,67011,1);
INSERT INTO stanza VALUES('F1086','2','خداوندْ عیسی، عزیز،<br/>با شادى كنيم اعلام،<br/>نامَت به جلالِ پدرِ آسْمان.<br/>چون ستایش کردنت،<br/>مسرتِ روزهای ماست؛<br/>خواندنِ عیسی خواندنِ عشقِ ماست!<br/>',NULL,67012,2);
INSERT INTO stanza VALUES('F1089','1','برّۀ خدا پاک، بی نقص،<br/>برای گناهکاران<br/>ذبح شدی، خونت بازخرید<br/>و پاک کرد لکه ها را.<br/>بازخرید کرد، بازخرید کرد،<br/>و گناهان را برداشت،<br/>و گناهان را برداشت!<br/>',NULL,67013,1);
INSERT INTO stanza VALUES('F1089','2','مارِ برنجین، افراشته<br/>شدی، بر تو بنگریم.<br/>شبیه جسمِ گناهکار،<br/>بر صلیب مصلوب شدی.<br/>پایان یافت خلقت کهنه،<br/>شیطان و دنیا تمام،<br/>شیطان و دنیا تمام!<br/>',NULL,67014,2);
INSERT INTO stanza VALUES('F1089','3','دانۀ گندم، بس کوچک،<br/>نمرده، تنها مانَد؛<br/>حیاتِ الهی در آن<br/>در مرگ کاشته می شود.<br/>حیاتِ مسیح پخش شود،<br/>بذرها بسیار آورَد،<br/>بذرها بسیار آورَد!<br/>',NULL,67015,3);
INSERT INTO stanza VALUES('F1089','4','برّۀ خدا – بازخرید،<br/>برنجینْ مار – ختمِ شر،<br/>بذر گندم – پخشِ حیات،<br/>ما آن بذرهای بسیار.<br/>هللویاه! هللویاه!<br/>مرگی شاملِ تمام،<br/>مرگی شاملِ تمام!<br/>',NULL,67016,4);
INSERT INTO stanza VALUES('F1095','1','خداوند جلال یابد<br/>گر ستایش کنیم،<br/>فرشته ها گوش دهند<br/>چون رَسا بخوانیم؛<br/>اطراف شنوند و به<br/>خدا جلال دهند،<br/>و شیطان و سپاهش<br/>لرزند، فرار کنند.<br/>',NULL,67017,1);
INSERT INTO stanza VALUES('F1095','2','دهانِ بسته شکست،<br/>لبخندِ ابلیس است؛<br/>پس چرا نجنگیم و<br/>او را دور نکنیم.<br/>با «قربانیِ سپاس،»<br/>ندای پیروزی –<br/>خود را فراموش کنیم<br/>مجنون خداییم!<br/>',NULL,67018,2);
INSERT INTO stanza VALUES('F1095','3','دنیا کمک نکرد تا<br/>منجی را حمد گوییم،<br/>او را تمجید نکرد و<br/>هیچ شکرگزار نبود؛<br/>پس بهرِ حمدش آیا<br/>اجازه لازم است؟<br/>فریاد کن! روح را بکار<br/>بَر، او فیض می بخشد!<br/>',NULL,67019,3);
INSERT INTO stanza VALUES('F1095','4','برادر، ساکت نباش!<br/>خواهر، فریاد بزن!<br/>این از ظفرِ خدا<br/>و برْکاتش گوید.<br/>حال وقت ستایش است،<br/>حالا، به هر بها!<br/>شادی کن در نجاتت،<br/>سرافراز در رحمت.<br/>',NULL,67020,4);
INSERT INTO stanza VALUES('F1097','1','خداى ما، چقدر عاليست<br/>نامت روی زمين!<br/>هر مَردم، قوم و زبانى<br/>گویند ارزشِ این.<br/>از دهانِ كوچكتران<br/>حَمد را بنا کردی،<br/>تا دشمن را خاموش كنى،<br/>روزهايش را تمام.<br/>',NULL,67021,1);
INSERT INTO stanza VALUES('F1097','2','وقتى جهان را بنگريم،<br/>عظيم كارِ دستت –<br/>خورشيد، ماه و ستارگان<br/>طرح شدند با حكمت؛<br/>انسان چيست كه يادش آرى<br/>و به فكرش هستى؟<br/>انسان را ملاقات كنى<br/>در اقتصادِ خود.<br/>',NULL,67022,2);
INSERT INTO stanza VALUES('F1097','3','خداوندْ عيسى، آن انسان<br/>هستى از نسلِ ما،<br/>آن كه جسم پوشيدى، پایین<br/>آمدى نزدِ ما.<br/>ليک حال تاجِ جلال دارى<br/>و تمامِ قدرت.<br/>از بَدنَت حكم مى كنى،<br/>همه زيرِ پایَت.<br/>',NULL,67023,3);
INSERT INTO stanza VALUES('F1097','4','جسم پوشيدن و برخاستن،<br/>و صعودت والا،<br/>مقام، سَرى و سلطنت،<br/>و بَدنَت اینجا.<br/>با مراحلِ كارِ خود<br/>حَمد را بنا کردی.<br/>با قلبهاى لبريز به تو،<br/>سَراييم با شادی.<br/>',NULL,67024,4);
INSERT INTO stanza VALUES('F1097','5','آن روزِ پر بركت آيد –<br/>همه اقرار كنند.<br/>ليک حالا در كليساها<br/>پيش مزه اش داريم –<br/>خداى ما، چقدرعاليست<br/>نامت روی زمين!<br/>هر مردم، ايل و زبانى<br/>گویند ارزشِ این.<br/>',NULL,67025,5);
INSERT INTO stanza VALUES('F1101','1','بنگر، سلطنتِ دنيا حال سلطنتِ خداست!<br/>آه، حكومتِ ابدى اش چه لذتى دارد!<br/>بيا پُر قدرت ستايشش بخوانيم هم صدا -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67026,1);
INSERT INTO stanza VALUES('F1101','chorus','پيروز، پيروز، هللوياه!<br/>پيروز، پيروز، هللوياه!<br/>پيروز، پيروز، هللوياه!<br/>پيروزى بَرَندَه ست !<br/>',NULL,67027,2);
INSERT INTO stanza VALUES('F1101','2','اژدها، مارِ كهنه، شرير، به زير افكنده شد؛<br/>گذشت روزهاى فريبندۀ ارواحِ شرير!<br/>حال ستايشهامان مثل رعد دورِ جهان پیچَد -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67028,3);
INSERT INTO stanza VALUES('F1101','3','حال نجات و قدرت و سلطنتِ خدا آمد؛<br/>مُدعیِ برادران زيرِ پایِمان افتاد!<br/>اقتدارِ مسيح حالْ عصاى حكم كليساست -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67029,4);
INSERT INTO stanza VALUES('F1101','4','با خونِ رهايى بخش بر مُدعى پيروز شديم؛<br/>با كلامِ شهادتمان بگوييم، ''تمام شد!''<br/>تا به مرگ جانمان دوست نداريم، جلال بر پسر!<br/>پيروزى بَرَندَه ست!<br/>',NULL,67030,5);
INSERT INTO stanza VALUES('F1101','5','برادرها، خواهرها، شنويد صداىِ دگر،<br/>«بابِل افتاده، افتاده،» وَجد و شادى می كنيم!<br/>آه چه برْكتى داشت از او بيرون آمدنمان -<br/>پيروزی  بَرَندَه ست!<br/>',NULL,67031,6);
INSERT INTO stanza VALUES('F1101','6','او مادر فواحش است، رازِ بابِلِ عظيم!<br/>چقدر يادگرفتيم از كارهاش متنفر باشيم!<br/>اما دو بار داورى شد، روحمان مژده دهد.<br/>پيروزى بَرَندَه ست!<br/>',NULL,67032,7);
INSERT INTO stanza VALUES('F1101','7','هللوياه! جلال و قدرت از خدایمان است!<br/>راست و صادق است همه قضاوتهايش بر شرير!<br/>ببين دودش بلند شد! شعرِهللوياه بخوان -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67033,8);
INSERT INTO stanza VALUES('F1101','8','حال، ستايیدَش خدا را تمامیِ خادمان.<br/>همچون صداى آبهاى بسيار فرا می خوانیم:<br/>هللوياه، هللوياه، خدا سلطنت کند!<br/>پيروزى بَرَندَه ست!<br/>',NULL,67034,9);
INSERT INTO stanza VALUES('F1101','9','حال وجد و شادى كن كه چه جلالی نمايان است!<br/>بهرِعروسىِ برّه، عروسش آماده شد!<br/>كتانِ پاک و تابان داده شد، آراسته شود -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67035,10);
INSERT INTO stanza VALUES('F1101','10','شرير در دریای آتش، يوحنا او را ديده؛<br/>هللویاه، لازم نیست دگر تحملش کنیم!<br/>مقدسينِ پيروز داورى اش اعلام كنند -<br/>پيروزى بَرَندَه ست!<br/>',NULL,67036,11);
INSERT INTO stanza VALUES('F1101','11','حال بنگر، شِگِفتا، اورشليمِ نو پايين آيد!<br/>بَنای خدا با انسان، چه تركيبِ كاملی!<br/>عروسِ مسیح آماده، تكميلِ كارِ خداست!<br/>پيروزى بَرَندَه ست!<br/>',NULL,67037,12);
INSERT INTO stanza VALUES('F1101','12','مسکن خدایمان و سکونتش با انسان؛<br/>در تقدس و جلال، او در همه ابراز شود.<br/>«تمام شد!» ای برادران بينيد اورشليمِ نو!<br/>پيروزى بَرَندَه ست!<br/>',NULL,67038,13);
INSERT INTO stanza VALUES('F1101','chorus','هللویاه، هللویاه!<br/>هللویاه، هللویاه!<br/>هللویاه، هللویاه!<br/>پيروزى بَرَندَه ست!<br/>',NULL,67039,14);
INSERT INTO stanza VALUES('F1103','1','او چه هست: او پدر است.<br/>او هست پدرِ ابدی.<br/>در آفرینشْ اولین است.<br/>او حیاتِ درونی ماست.<br/>او پدر است! عجیب است!<br/>',NULL,67040,1);
INSERT INTO stanza VALUES('F1103','2','او چه هست: او رودخانه ست.<br/>رودخانه، روان و قوی.<br/>در دشت آبیاری ام می کند.<br/>پناهم است؛ او خداوند است.<br/>او رودخانه ست! عجیب است!<br/>',NULL,67041,2);
INSERT INTO stanza VALUES('F1103','3','او چه هست: درخت موست.<br/>او شاخه، ریشۀ یَسی ست.<br/>درختِ حیات است: می تونیم<br/>از او بخوریم، حیات گیریم.<br/>درخت موست! عجیب است!<br/>',NULL,67042,3);
INSERT INTO stanza VALUES('F1103','4','او چه هست: او شبان است.<br/>او همان برّۀ خداست.<br/>در مرتع ها آسایش دهد.<br/>ریخته خونش، شد غذای ما.<br/>او شبان است! عجیب است!<br/>',NULL,67043,4);
INSERT INTO stanza VALUES('F1103','5','او چه هست: روح قدوس.<br/>او روحِ شاملِ تمام.<br/>همه چیز است، همه چیزِ ماست.<br/>هرگاه خوانیمش، حیات دهد.<br/>روح قدوس! عجیب است!<br/>',NULL,67044,5);
INSERT INTO stanza VALUES('F1103','6','او چه هست: او یک شخص است.<br/>شخصی واقعی و زنده.<br/>حال در ما زندگی می کند.<br/>چقدَر پرجلال است این شخص.<br/>او یک شخص است! عجیب است!<br/>',NULL,67045,6);
INSERT INTO stanza VALUES('F1103','7','او چه هست:  او بدن هست؛<br/>او پُریِ سَر خداست؛<br/>مرکزِ نقشۀ پدراست،<br/>مسیح و کلیسا، انسان نو<br/>او عجیب است، عجیب است.<br/>او عجیب است، عجیب است.<br/>او عجیب است، عجیب است.<br/>',NULL,67046,7);
INSERT INTO stanza VALUES('F1106','1','گِردِ هم آمدیم، شامِ خدا خوريم:<br/>با خوردن و نوشيدن يكى هستيم.<br/>حضورش را داريم، وحدت اعلام كنيم،<br/>اينطور دریافت کنیم و برْكتش دانيم.<br/>',NULL,67047,1);
INSERT INTO stanza VALUES('F1106','2','نانِ بدنش كه شكسته شد خوريم<br/>از بدنِ يكتاش مسرت بريم :<br/>يک تكه نان بر میز – یک بدن، می تونیم<br/>که شهادت دهيم خدا یک كرد ما را.<br/>',NULL,67048,2);
INSERT INTO stanza VALUES('F1106','3','ما همچنين جامِ برْكتش را نوشيم،<br/>مشارکتِ كليسا در خونش؛<br/>بازخرید با ايمان، قدوسان پذيرا،<br/>آنها از بازخرید به خدا آمدند.<br/>',NULL,67049,3);
INSERT INTO stanza VALUES('F1106','4','آه، حالا چه گوييم به جز «هللوياه!»<br/>بهرِ حقيقت كه داده شد به ما.<br/>خونت بکار برده، بَدَنت سهم بَریم؛<br/>اينطور كليسايت را يابى پرجلال.<br/>',NULL,67050,4);
INSERT INTO stanza VALUES('F1107','1','بدنِ تو هستیم، ای عیسی، اینجا<br/>چندين هستيم، اما همه يكى.<br/>حیاتت سهیم و اعضاى بدن،<br/>و در حيات، همه يكى هستيم.<br/>',NULL,67051,1);
INSERT INTO stanza VALUES('F1107','chorus','فقط يک بدن در اين جهانه،<br/>بر زمين ابرازش كنيم؛<br/>يک ايستاده ايم در هر محله،<br/>همه بينند، همه بينند.<br/>',NULL,67052,2);
INSERT INTO stanza VALUES('F1107','2','يک قرصِ نان، نمادِ بدنِ تو:<br/>شكست تا مقدسين سهيم شَند.<br/>اين نان بخوريم و چون سهیم شویم،<br/>يكى بودنمان اعلام كنيم.<br/>',NULL,67053,3);
INSERT INTO stanza VALUES('F1107','3','يک نان، يک جام، حالا بر روى میز اند،<br/>نشانۀ يكى بودنِ ما.<br/>بازخرید کرد، مسیح، و بدنش ساخت:<br/>چه گوييم جز، «آمين، خدا، يک ايم!»<br/>',NULL,67054,4);
INSERT INTO stanza VALUES('F1107','4','يک ايستاديم، جدا نتوانيم شد،<br/>چون وحدتمان فقط مسيح است.<br/>يكى هستيم: يک نان، يک جام شريكيم،<br/>پس وحدتمان واضحاً پيداست.<br/>',NULL,67055,5);
INSERT INTO stanza VALUES('F1107','5','چه شاديم از اين وحدتِ مبارک!<br/>حس كنيم، خدايا، راضى هستى؛<br/>ما هم در رضايتِ تو شريكیم-<br/>پيش مزۀ داماد و عروسش.<br/>',NULL,67056,6);
INSERT INTO stanza VALUES('F1109','1','بنوش جامِ خون را،<br/>بازخریدِ خدا.<br/>مسیح صلح حاصل کرد،<br/>هست در این جام پیدا.<br/>با پسر، شراکتِ ما:<br/>کار انجام شد بر جلجتا:<br/>راه باز شده، حالا بیا!<br/>',NULL,67057,1);
INSERT INTO stanza VALUES('F1109','2','جام را برگیر، بنوش،<br/>نشانِ مرگش تا<br/>آید، این جشن برجا،<br/>آن برّۀ خدا!<br/>دورِ میز بخور شامش را؛<br/>بخور نان را، بنوش جام را.<br/>در این جام است برِکتها.<br/>',NULL,67058,2);
INSERT INTO stanza VALUES('F1109','3','نه خونِ گاو یا بُز<br/>دهد هیچ امیدی.<br/>گناه همچون باقی<br/>بی هیچ نوع تغییری.<br/>باید باشد این قربانی –<br/>بی گناه خدا-انسانی،<br/>بهرِ ما، بی عیب برّه ای.<br/>',NULL,67059,3);
INSERT INTO stanza VALUES('F1109','4','به کار بِبَر خون را؛<br/>دسترسی به خداست!<br/>قوی پاک می کند<br/>به ما جریان دارد.<br/>یک قربانی بهرِ همه،<br/>در وجدان، صلح نفوذ کرده،<br/>چون بازخرید انجام شده!<br/>',NULL,67060,4);
INSERT INTO stanza VALUES('F1109','5','پادشاه و منجی،<br/>از خونت سراییم،<br/>چون می بینیم در آن،<br/>رحمتت فراوان.<br/>جام، سهمِ مبارکِ ما،<br/>آن خونِ عهدِ توست با ما –<br/>خونِ بسیار گرانبها!<br/>',NULL,67061,5);
INSERT INTO stanza VALUES('F1112','1','اوه، چه پرجلالْ ميزَت، خدا-<br/>تو آن مرد، ميزبان و سَرور،<br/>در منزل، خانه ات، مانى؛<br/>اوه، چه پرجلالْ ميزَت، خدا!<br/>',NULL,67062,1);
INSERT INTO stanza VALUES('F1112','chorus','هللوياه! هللوياه!<br/>هللوياه بهرِ اين جشن!<br/>هللوياه! هللوياه!<br/>اوه، چه پرجلالْ ميزَت، خدا!<br/>',NULL,67063,2);
INSERT INTO stanza VALUES('F1112','2','چه پر مسرت ميزت، خدا-<br/>دورش مشاركت داريم،<br/>هللوياه، پيداش كرديم،<br/>چه پر مسرت ميزَت، خدا!<br/>',NULL,67064,3);
INSERT INTO stanza VALUES('F1112','3','اوه، چه پر ارزش ميزَت، خدا-<br/>نان و جام اعلامِ مرگت؛<br/>اينجا انكار كنيم نفْس را،<br/>با خوردن از ميزت، اى خدا.<br/>',NULL,67065,4);
INSERT INTO stanza VALUES('F1112','4','چه پر معنى است ميزَت، خدا-<br/>بَدَنَت در اين نان بینيم،<br/>حاكى از هدفِ عشقت؛<br/>چه پر معنى است ميزت، خدا!<br/>',NULL,67066,5);
INSERT INTO stanza VALUES('F1112','5','چه پر طراوت میزَت، خدا-<br/>کاملاً راضی مى كند،<br/>روز به روز تأمین می كند؛<br/>چه پر طراوت میزَت، خدا.<br/>',NULL,67067,6);
INSERT INTO stanza VALUES('F1112','6','چه دلگرميه ميزَت، خدا-<br/>«تا او آید،» وعده دهد،<br/>با اميد پُرمان سازد؛<br/>چه دلگرميه ميزَت، خدا!<br/>',NULL,67068,7);
INSERT INTO stanza VALUES('F1113','1','حال خدای سه-يكتا درونِ ماست<br/>كه آن روحِ شگرف است در ما.<br/>با خدا آميخته و يكى هستيم،<br/>چون روحِ حيات بخش است در ما.<br/>',NULL,67069,1);
INSERT INTO stanza VALUES('F1113','chorus','اوه، او آن روحِ شگرف است در ما،<br/>او آن روحِ شگرف است در ما!<br/>خدا در پسر،  پسر، روح است حالا –<br/>او آن روحِ شگرف است در ما!<br/>',NULL,67070,2);
INSERT INTO stanza VALUES('F1113','2','«اَبّا، پدر» فريادِ درونِ ماست<br/>از همان روحِ شگرف در ما.<br/>روحِ پسر است كه او را مى خواند<br/>چون روحِ حيات بخش است در ما.<br/>',NULL,67071,3);
INSERT INTO stanza VALUES('F1113','3','خداوندْ عيسى مسيح در ماست حالا<br/>كه آن روحِ شگرف است در ما.<br/>او تبديل شده، او را لذت بريم<br/>چون روحِ حيات بخش است در ما.<br/>',NULL,67072,4);
INSERT INTO stanza VALUES('F1113','4','حالا آن روحِ واقعيت اينجاست<br/>که آن روحِ شگرف است در ما.<br/>حالا مسيح چه روشن و واقعيست<br/>با آن روحِ  حيات بخش در ما.<br/>',NULL,67073,5);
INSERT INTO stanza VALUES('F1113','5','برافروزیم اين هدیۀ درونى<br/>كه آن روحِ شگرف است در ما.<br/>خوانيم «خداوندْ عيسى،» در روح جوشيم<br/>با اين روحِ حيات بخش در ما!<br/>',NULL,67074,6);
INSERT INTO stanza VALUES('F1117','1','شکرت خدایا،<br/>بهرِ روحِ مسیح<br/>که در ما ساکن شده<br/>تا حیات باشه.<br/>',NULL,67075,1);
INSERT INTO stanza VALUES('F1117','chorus','هللویاه! عجب روحی!<br/>هللویاه! درون!<br/>هللویاه! پُر از حیات،<br/>پایان ناپذیر!<br/>',NULL,67076,2);
INSERT INTO stanza VALUES('F1117','2','در روح می خوانیم<br/>از آن که آمده<br/>چون آن روحِ حیات بخش<br/>با ما یک باشه.<br/>',NULL,67077,3);
INSERT INTO stanza VALUES('F1117','chorus','هللویاه! این است عیسی،<br/>هللویاه! حالا،<br/>هللویاه! او آن روح است،<br/>حیاتِ ابد.<br/>',NULL,67078,4);
INSERT INTO stanza VALUES('F1117','3','تولد در روح،<br/>دگرگون می شویم،<br/>و با پسرِ خدا<br/>همشکل خواهیم شد.<br/>',NULL,67079,5);
INSERT INTO stanza VALUES('F1117','chorus','هللویاه! پخشِ حیات،<br/>هللویاه! تبدیل،<br/>هللویاه! دگرگون و<br/>همشکلش شویم!<br/>',NULL,67080,6);
INSERT INTO stanza VALUES('F1117','4','همشکل خواهیم شد<br/>چون در روح سهم بَریم<br/>از حیاتِ آن که<br/>نیازهامان دانَد.<br/>',NULL,67081,7);
INSERT INTO stanza VALUES('F1117','chorus','هللویاه! نجاتِ پُر!<br/>هللویاه! پاداش!<br/>هللویاه! چقدر کافیست<br/>تمامیِ عمر.<br/>',NULL,67082,8);
INSERT INTO stanza VALUES('F1122','1','هفت روحِ خدایمان –<br/>بنگر، عصر چرخيده است<br/>به آن روح با پسر كه<br/>مسئولِ كليساهاست.<br/>',NULL,67083,1);
INSERT INTO stanza VALUES('F1122','chorus','بيا، ای هفت روح، بيا<br/>برای بازيابى ات!<br/>بِسوز و بِگرد كامل،<br/>كليساها از تو اند.<br/>بسوز، بِگَرد،<br/>كليساها از تو اَند!<br/>',NULL,67084,2);
INSERT INTO stanza VALUES('F1122','2','هفت برابر، روحْ بهرِ<br/>مُردگىِ كليساست،<br/>كه مقدسين چَرخَند،<br/>كه خداوند سوزانَد.<br/>',NULL,67085,3);
INSERT INTO stanza VALUES('F1122','3','حال روحِ خدايمان<br/>قوی تر تشديد شده:<br/>يک نه، هفت برابره<br/>كه كليسا تأمين شه.<br/>',NULL,67086,4);
INSERT INTO stanza VALUES('F1122','4','حالا آن هفت روح هستند<br/>هفت چراغدانِ سوزان،<br/>نه تعليم، ليک سوزانند،<br/>خدا را راضى كنند.<br/>',NULL,67087,5);
INSERT INTO stanza VALUES('F1122','5','حالا بنگر آن هفت روح–<br/>هفت چشم، بازرس و نافذ،<br/>اِفشا می کند ما را،<br/>پاک كند كليسا را.<br/>',NULL,67088,6);
INSERT INTO stanza VALUES('F1122','6','هفت روحْ را خدا بهرِ<br/>كليساها گذاشته؛<br/>در کلیسای محل<br/>حال از آن لذت بَرند.<br/>',NULL,67089,7);
INSERT INTO stanza VALUES('F1125','1','بر صلیب جایی که منجی مُرد،<br/>عدالتِ خدا راضی شد،<br/>آن خون بکار رفت بر گناهم؛<br/>جلال بر نامش!<br/>',NULL,67090,1);
INSERT INTO stanza VALUES('F1125','chorus','جلال بر نامش،<br/>جلال بر نامش؛<br/>آن خون بکار رفت بر گناهم؛<br/>جلال بر نامش!<br/>',NULL,67091,2);
INSERT INTO stanza VALUES('F1125','2','این چشمه رهانَد از گناه،<br/>از بازخرید لذت بریم ما؛<br/>این مسرتِ دائمِ ماست،<br/>جلال بر نامش!<br/>',NULL,67092,3);
INSERT INTO stanza VALUES('F1125','chorus','جلال بر نامش،<br/>جلال بر نامش؛<br/>آن خون بکار رفت بر گناهم؛<br/>جلال بر نامش!<br/>',NULL,67093,4);
INSERT INTO stanza VALUES('F1125','3','به راستی وقتی منجی ام مرد،<br/>نه تنها قرضِ گناه را داد،<br/>بلکه چشمۀ حیات باز شد؛<br/>جلال بر نامش!<br/>',NULL,67094,5);
INSERT INTO stanza VALUES('F1125','chorus','جلال بر نامش،<br/>جلال بر نامش؛<br/>چشمۀ آبِ حیات باز شد؛<br/>جلال بر نامش!<br/>',NULL,67095,6);
INSERT INTO stanza VALUES('F1125','4','هم بازخرید هم حیات داریم،<br/>پاک در خونش، آنجا می مانیم<br/>و آب حیات را می نوشیم؛<br/>جلال بر نامش!<br/>',NULL,67096,7);
INSERT INTO stanza VALUES('F1125','chorus','جلال بر نامش،<br/>جلال بر نامش؛<br/>چشمۀ آبِ حیات باز شد؛<br/>جلال بر نامش!<br/>',NULL,67097,8);
INSERT INTO stanza VALUES('F1130','1','ستایش بر مسیحْ در ما،<br/>خدای نجاتمان؛<br/>با حیاتش نجات دهد،<br/>نه با تنظیم و آیین؛<br/>پس از بهترین سعیِ ما،<br/>حیاتش هست قادر، تنها،<br/>که تغییر دهد ما را.<br/>',NULL,67098,1);
INSERT INTO stanza VALUES('F1130','2','ما را کامل نجات دهد<br/>با قدرتِ حیات بخش؛<br/>خود را در ما تزریق کند،<br/>هر لحظه نجات دهد.<br/>او با آمدن، نجات داد،<br/>بیش از گناه نجات دهد<br/>تا جلال نجات دهد!<br/>',NULL,67099,2);
INSERT INTO stanza VALUES('F1130','3','خداوندِ ما کاهن بود<br/>تا آن حیات بخش باشد؛<br/>حیات است ذاتِ این شخص که<br/>قادر است از نفْس رهانَد:<br/>حیاتش فناناپذیر،<br/>نجاتِ کامل می دهد،<br/>شکرش که او قادر است!<br/>',NULL,67100,3);
INSERT INTO stanza VALUES('F1130','4','حیاتِ او شایسته است<br/>ما را به جلال آرَد؛<br/>گر بهرِ حیاتش نبود،<br/>داستانی دیگر می بود:<br/>از تولد، مصلوب می زیست،<br/>حیاتی آزمون-شده زیست،<br/>از مرگ و قبر عبور کرد.<br/>',NULL,67101,4);
INSERT INTO stanza VALUES('F1130','5','عهد کرد ما را نجات دهد،<br/>حیاتش کار می کند؛<br/>بهرِ ما همه کار کند<br/>تا ما را بی عیب کند؛<br/>بهترینِ ما شکست است،<br/>تنها حیاتش قادر است:<br/>نجاتِ کامل آرَد!<br/>',NULL,67102,5);
INSERT INTO stanza VALUES('F1130','6','حالا شفاعت می کند،<br/>دائم ادامه دارد؛<br/>او این را به عهده گرفت،<br/>هرگز تغییر نکند؛<br/>دائم شفاعت می کند،<br/>اوست آنچه ما نیاز داریم:<br/>او بلندتر از سَماست.<br/>',NULL,67103,6);
INSERT INTO stanza VALUES('F1130','7','از او نزدیک شو به خدا ،<br/>هرگز عقبگرد نکن؛<br/>حال بیا تا حیات یابی،<br/>با آن، عملکرد آید؛<br/>حال نزدیک شو، حیات بگیر،<br/>با حیات، مردمش شویم،<br/>مرگ را به کل ببلعیم.<br/>',NULL,67104,7);
INSERT INTO stanza VALUES('F1132','1','یاد دِه دعا کنیم،<br/>نه سطحی مثل امتها،<br/>لیک برگردان ما را،<br/>تا هر روز بخوانیم نام تو را –<br/>عیسی، رشد کن در ما.<br/>',NULL,67105,1);
INSERT INTO stanza VALUES('F1132','2','تو بذرِ حیاتی،<br/>کاشتی خود را در دل ما،<br/>آغاز کردی این را؛<br/>روز به روز بیشتر حیات دِه به ما –<br/>عیسی، رشد کن در ما.<br/>',NULL,67106,2);
INSERT INTO stanza VALUES('F1132','3','خداوند، دلها را<br/>نرم کن، کاوشگرِ دلها،<br/>خوانیم نام تو را،<br/>تا نماند سنگلاخ در دل بر جا –<br/>عیسی، رشد کن در ما.<br/>',NULL,67107,3);
INSERT INTO stanza VALUES('F1132','4','نورت روشن کرده<br/>که دائم شکست می خوریم؛<br/>لیک پیام را داریم،<br/>که با بذرِ حیات غالب شویم –<br/>عیسی، رشد کن در ما.<br/>',NULL,67108,4);
INSERT INTO stanza VALUES('F1132','5','در روح فقیر کن ما<br/>را، خالی از هر چه دانیم.<br/>خود را باز می کنیم،<br/>تا در حیاتِ خودت رشد کنیم –<br/>عیسی، رشد کن در ما.<br/>',NULL,67109,5);
INSERT INTO stanza VALUES('F1132','6','دل ها را خالص کن؛<br/>چون قانع نمی شویم ما،<br/>تا پُر کنی ما را،<br/>نو کن ذهن، احساس و اراده را –<br/>عیسی، رشد کن در ما.<br/>',NULL,67110,6);
INSERT INTO stanza VALUES('F1132','7','خداوند، نفوذ کن<br/>در دل، تا برگیریم تو را،<br/>دهیم به آن بذر راه؛<br/>رشدِ تو آوَرَد ملکوت را –<br/>عیسی، رشد کن در ما.<br/>',NULL,67111,7);
INSERT INTO stanza VALUES('F1132','8','آمین! رشد در حیات!<br/>قادر است آن حیاتِ تو<br/>تازه کند و نو.<br/>ما فقط موفق شویم با تو.<br/>عیسی، رشد کن در ما.<br/>عیسی، رشد کن در ما.<br/>',NULL,67112,8);
INSERT INTO stanza VALUES('F1134','1','قوت دِه روحِ مرا، عیسی،<br/>قوت دِه روحِ مرا؛<br/>قوت دِه با نیرو روحم را،<br/>در قلبم گسترش یاب.<br/>',NULL,67113,1);
INSERT INTO stanza VALUES('F1134','chorus','در قلب من، در قلب من،<br/>در قلبْ گسترش یاب، عیسی؛<br/>خانه بساز و مختار باش<br/>در قلب من، خداوندا.<br/>',NULL,67114,2);
INSERT INTO stanza VALUES('F1134','2','در قلبم گسترش یاب، عیسی،<br/>در قلبم گسترش یاب؛<br/>گسترش یاب از روح به قلبم<br/>در قلبم گسترش یاب.<br/>',NULL,67115,3);
INSERT INTO stanza VALUES('F1134','3','ساکن شو در قلبم، ای عیسی،<br/>ساکن شو در قلب من؛<br/>تا از کمال تو پُر شویم،<br/>ساکن شو در قلب من.<br/>',NULL,67116,4);
INSERT INTO stanza VALUES('F1134','4','به او که قادر به انجام است<br/>فزونتر از خواست یا فکر،<br/>قلبمان باز کنیم و او را<br/>خوش آمد گوییم درون.<br/>',NULL,67117,5);
INSERT INTO stanza VALUES('F1135','1','تقدیس کن خداوند؛ حال در ما افزون شو،<br/>در تجربۀ ما، در ما گسترده شو،<br/>تا پر جلال باشد در واقع کلیسا،<br/>ای خدا، افزون شو در ما.<br/>',NULL,67118,1);
INSERT INTO stanza VALUES('F1135','chorus','خداوندا، تقدیس نما؛<br/>عیسی، تو تنها راه هستی.<br/>برگیریم شخصت را؛<br/>گسترش یاب در ما.<br/>خداوندا، تقدیس نما.<br/>',NULL,67119,2);
INSERT INTO stanza VALUES('F1135','2','خالص کن، خداوند، با سخن ات در ما؛<br/>با کلامت زنده، شستشو ده ما را،<br/>بیش کن سخن ات را، بخشهامان پاک نما،<br/>ای خدا، خالص کن ما را.<br/>',NULL,67120,3);
INSERT INTO stanza VALUES('F1135','chorus','خداوندا، خالص نما؛<br/>پاک کن حیاتِ فطری را.<br/>سخن بگو در ما،<br/>پر جلال کن ما را.<br/>خدا، سخن بگو در ما.<br/>',NULL,67121,4);
INSERT INTO stanza VALUES('F1135','3','خداوند، خوراک دِه؛ تویی خوراکمان؛<br/>چون بخوریم تو را، دگرگون شویم ما؛<br/>چون از تو بخوریم، چقدْر خرسندیم ما،<br/>ای خدا، خوراک ده ما را.<br/>',NULL,67122,5);
INSERT INTO stanza VALUES('F1135','chorus','خداوندا، خوران ما را<br/>چون محو کنی نفْسِ ما را.<br/>نه تنها پاک نما،<br/>پُر و راضی فرما؛<br/>خداوندا، خوران ما را.<br/>',NULL,67123,6);
INSERT INTO stanza VALUES('F1135','4','خدا، پرورش ده، چون از تو بخوریم؛<br/>ما را دلگرم نما، رفع کن نیازها را.<br/>سرسختیْمان نرم کن، تا مالِ تو شویم؛<br/>ای خداوند، پرورش ده.<br/>',NULL,67124,7);
INSERT INTO stanza VALUES('F1135','chorus','خداوندا، پرورش ده،<br/>تا سرد نباشیم ما،<br/>نزدیکت نگه دار<br/>و عزیز دار ما را؛<br/>خداوندا، پرورش ده.<br/>',NULL,67125,8);
INSERT INTO stanza VALUES('F1135','5','خدا، پرجلال کن، کار کن درونِ ما،<br/>نه جلال بهرِ خویش، لیک بهرِ کلیسا؛<br/>پایان ده جستجو، بیاب عروست را.<br/>ای خداوند، کار کن بر ما.<br/>',NULL,67126,9);
INSERT INTO stanza VALUES('F1135','chorus','خداوندا، کار کن بر ما!<br/>شکل دِه کلیسا را.<br/>گسترش یاب در ما<br/>تا پرجلال شویم؛<br/>خداوند، جلال دِه ما را.<br/>',NULL,67127,10);
INSERT INTO stanza VALUES('F1141','1','سَراييم با روحْ بهرِ خداوند،<br/>سَراييم از درونْ به خدا،<br/>سَراييم هللوياه به عيسى؛<br/>بیاميزيم با او در وحدت.<br/>',NULL,67128,1);
INSERT INTO stanza VALUES('F1141','2','سالهاى بسيار در مذهب بوديم،<br/>سالهاى بسيار در فكرمان،<br/>سالهاى بسيار در احساسمان،<br/>دائم جويا، اما نيافتيم.<br/>',NULL,67129,2);
INSERT INTO stanza VALUES('F1141','3','حال يادگيريم چرخيدن به روح را،<br/>حال يادگيريم مسيح است حيات؛<br/>حال ياد گيريم خوردنِ عيسى را،<br/>رها از تقلا و نزاع.<br/>',NULL,67130,3);
INSERT INTO stanza VALUES('F1141','4','هللوياه بهرِ حيات در روح،<br/>هللوياه بر درونِ نو؛<br/>تا بچرخيم از ذهنمان به روح،<br/>ثروتهايش مسرت بَريم.<br/>',NULL,67131,4);
INSERT INTO stanza VALUES('F1142','1','عیسی روحِ زنده است و<br/>حقیقتِ ما؛<br/>لذت بریم با خواندنش<br/>در سادگی، ما.<br/>',NULL,67132,1);
INSERT INTO stanza VALUES('F1142','chorus','عیسی روحِ زنده است، این<br/>را گوییم حالا؛<br/>او غنیست به هر آن که<br/>بخواند نامش را.<br/>',NULL,67133,2);
INSERT INTO stanza VALUES('F1142','2','او در ما زیست می کند حال،<br/>آزادی بخشید؛<br/>نیکوست و رحیم، بچشید<br/>و هم ببینید.<br/>',NULL,67134,3);
INSERT INTO stanza VALUES('F1142','3','عیسی روحِ زنده است و<br/>کلامِ زنده؛<br/>در دعا-خوانی لمس کنیم<br/>او را سرزنده.<br/>',NULL,67135,4);
INSERT INTO stanza VALUES('F1142','4','عیسی روحِ زنده است که<br/>جاریست بینِ ما؛<br/>مشارکتِ حیات در<br/>روح، وحدتِ ما.<br/>',NULL,67136,5);
INSERT INTO stanza VALUES('F1142','5','عیسی روح زنده است و<br/>ضیافتِ ما؛<br/>از او لذت بریم، سرشار<br/>از ستایش ها.<br/>',NULL,67137,6);
INSERT INTO stanza VALUES('F1151','1','بِنوش! نهرِ پاک و صاف كه از تختش جاريست؛<br/>بخور! درختِ حيات با وفورِ ميوه؛<br/>ببين! نياز نيست به نورِ لامپ، خورشيد و ماه، چون<br/>اين جا شبى نيست.<br/>',NULL,67138,1);
INSERT INTO stanza VALUES('F1151','chorus','بيا، اوه، بيا،<br/>روح و عروس گويد:<br/>بيا، اوه، بيا،<br/>آنكه شنید، خوانَد.<br/>بيا، اوه، بيا،<br/>آن كه تشنه است،<br/>آبِ حيات مجانى بگير!<br/>',NULL,67139,2);
INSERT INTO stanza VALUES('F1151','2','مسيح، نهرم، مسيح، آبم، درونم جاريست؛<br/>مسيح، درخت، مسيح، ميوه، شادم در او،<br/>مسيح روزم، مسيح نورم، ستارۀ صبح:<br/>مسيح کلِ چيزها!<br/>',NULL,67140,3);
INSERT INTO stanza VALUES('F1151','3','جامه ها شسته، درخت حيات مى خوريم؛<br/>«خدایا، آمين، هللوياه!» – عيسى شيرين!<br/>با تمرينِ روح ما تجربه كنيم مسيح.<br/>چه مسيحى داريم!<br/>',NULL,67141,4);
INSERT INTO stanza VALUES('F1151','4','خانه اى داريم كه تابان تر از خورشيد است،<br/>آنجا كه برادران راستى يكى هستند.<br/>عيسى جمع كرده ما را، او را نشان دهيم<br/>در اين كليسا.<br/>',NULL,67142,5);
INSERT INTO stanza VALUES('F1153','1','یافتیم مسیح همه در همه ست؛<br/>او همه چیز بهرِ ماست؛<br/>چه برْکتی ست خواندنِ نامش<br/>الهی و پرجلال!<br/>',NULL,67143,1);
INSERT INTO stanza VALUES('F1153','chorus','شادیِ وصف ناپذیر و پر از جلال،<br/>پر از جلال، پر از جلال؛<br/>شادیِ وصف ناپذیر و پر از جلال،<br/>و نصف اش هم گفته نشده!<br/>',NULL,67144,2);
INSERT INTO stanza VALUES('F1153','2','یافتیم مسیح همان روح است که<br/>در روحمان ساکن است؛<br/>چه نزدیک است و چه مهیا،<br/>نیکویی اش ممتاز است.<br/>',NULL,67145,3);
INSERT INTO stanza VALUES('F1153','3','یافتیم راه زیستن با او را–<br/>خوانیم کلام و نامش!<br/>همین خوردن، نوشیدن کافیست<br/>و حال گوییم ارزش اش.<br/>',NULL,67146,4);
INSERT INTO stanza VALUES('F1153','4','یافتیم کلیسای محل را<br/>که خانه، خانۀ ماست!<br/>در بابِل پرسه نخواهیم زد؛<br/>مایحتاج در کلیساست.<br/>',NULL,67147,5);
INSERT INTO stanza VALUES('F1153','5','یافتیم دیدارِ مقدسین<br/>خوش ترین چیز در دنیاست؛<br/>اینطور روحمان سست نشود،<br/>زندگیْمان پر بهاست.<br/>',NULL,67148,6);
INSERT INTO stanza VALUES('F1154','1','عشق من عیسی،<br/>عشق تو به من،<br/>مرا جذبِ تو کرده،<br/>تا تو را جویم.<br/>مرا جذبِ تو کرده،<br/>تا تو را جویم.<br/>تو محبوب هستی،<br/>از هر جهت جذابی،<br/>تو که شادیِ قلبم هستی.<br/>',NULL,67149,1);
INSERT INTO stanza VALUES('F1154','2','عشقت، ای عیسی،<br/>بِه از شراب است،<br/>با رایحۀ عطرت<br/>قلبم درگیر است.<br/>با رایحۀ عطرت<br/>قلبم درگیر است.<br/>چشمۀ باغ ها،<br/>برکۀ آبِ زنده،<br/>که نهرهاییست جاری از کوه ها.<br/>',NULL,67150,2);
INSERT INTO stanza VALUES('F1154','3','برخیز محبوبم،<br/>بِدَم بر باغم،<br/>تا عطر ادویه ها<br/>منتشر شود.<br/>تا عطر ادویه ها<br/>منتشر شود.<br/>خواهر، عروسم،<br/>به باغم خواهم آمد<br/>بهرِ خوردنِ شیر و عسل.<br/>',NULL,67151,3);
INSERT INTO stanza VALUES('F1154','4','خدایا، مُهر کن<br/>مرا بر دلت؛<br/>غیرتْ ستم کیش چون گور،<br/>عشق چون مرگ، پُرزور.<br/>غیرتْ ستم کیش چون گور،<br/>عشق چون مرگ، پُرزور.<br/>سیل نتواند<br/>عشق را فرونشاند.<br/>همه خوار است در قیاس با عشق.<br/>',NULL,67152,4);
INSERT INTO stanza VALUES('F1159','1','عيسی جان، اسیرِ زيباییتم،<br/>قلبم را بر رویَت باز کنم؛<br/>حال آزاد از تكاليفِ مذهب،<br/>فقط بگذار در تو بمانم.<br/>چون خيره بنگرم جلالت را،<br/>پُرم كن با نورِ الهی؛<br/>خواهشمندم، خداوند، اشباع كن،<br/>بیامیز حال روحت را با من.<br/>',NULL,67153,1);
INSERT INTO stanza VALUES('F1159','2','ای تابان، صافِ آسِمانْ بالا!<br/>ای انسان، برتخت می بینمت!<br/>ای قدوس، شعله ورم در خدا،<br/>تا وجودم با تو درخشد.<br/>وقتى تو را در جلالت ديدم،<br/>عشقْ به خود غرق شد در خجالت؛<br/>حال عشق و ستايش کند قلبم،<br/>بچشد شيرينىِ نامت.<br/>',NULL,67154,2);
INSERT INTO stanza VALUES('F1159','3','ای عزیز، ظرفِ مرمرين ام را<br/>با شادی در عشقت شکنم؛<br/>مَسح كنم سَرَت محبوبْ سَروَرم؛<br/>بنگر، بهرِ توست بهترينم .<br/>خدايم، خود را اتلافت كنم؛<br/>عاشقت، عميقاً راضى ام.<br/>عشق ريزد از اعماقِ وجودم،<br/>گران بها مهيا كنم.<br/>',NULL,67155,3);
INSERT INTO stanza VALUES('F1159','4','محبوبم، بيا به كوهِ زيتون؛<br/>مشتاقتم صورت در صورت.<br/>بنوش، عزيز، از چشمۀ قلبم،<br/>تا در آغوشت بیاسایم.<br/>نه تنها، خدايا، عاشقتم،<br/>لیک با مقدسين، عروست؛<br/>زود بيا، با عشق منتظرتیم؛<br/>عيسى خدا، راضى خواهى شد.<br/>',NULL,67156,4);
INSERT INTO stanza VALUES('F1164','1','عیسی سرزمینِ نیکوست،<br/>همه چیزِ من است:<br/>مسیحِ نهر و چشمه ها،<br/>و آبهای جوشان<br/>که از درّه و کوه جاریست،<br/>تا همه جا را پر کند،<br/>سیراب کند، چه پرجلال –<br/>با حیات!<br/>',NULL,67157,1);
INSERT INTO stanza VALUES('F1164','2','عیسی زمینِ گندم است –<br/>مجسم و مصلوب.<br/>لیک او حیاتِ رستاخیز<br/>در نمادِ جو است.<br/>زمینِ انجیر و تاک است –<br/>شیرۀ انگور، شادی بخش.<br/>با این نعمت راضی کند –<br/>آن مسیح!<br/>',NULL,67158,2);
INSERT INTO stanza VALUES('F1164','3','مسیحِ غنی و سرشار:<br/>انارِ واقعیست،<br/>درخت زیتون که ما را<br/>با روغن مَسح کند،<br/>شیر و عسل می آورد،<br/>مطبوع، کافی و مُغذی.<br/>این مسیح است؛ او لبریز است!<br/>آن مسیح!<br/>',NULL,67159,3);
INSERT INTO stanza VALUES('F1164','4','در سرزمینْ نان می خوریم –<br/>هیچ نوع کمبودی نیست.<br/>در او هیچ چیز کم نداریم،<br/>او غنی و پُر است.<br/>او سرزمینی وسیع است؛<br/>از هر جهتی کامل است.<br/>گسترده است، این سرزمین –<br/>او در ما!<br/>',NULL,67160,4);
INSERT INTO stanza VALUES('F1164','5','مسیحْ سنگهای آهن است،<br/>که اقتدار دارد.<br/>باید او را کاوش کنیم<br/>و دشمن را در بند.<br/>پس باید از رنج بگذریم<br/>تا چون مِس صِیقل بشویم،<br/>چون آهنْ سخت، چون مِسْ براق،<br/>نیازِ ماست.<br/>',NULL,67161,5);
INSERT INTO stanza VALUES('F1164','6','خداوند، شکر بهرِ زمین،<br/>مسیحْ شامل-تمام!<br/>خوریم و پُر شویم از او،<br/>کفایتِ تمام!<br/>یاد دِه دائم زحمت کشیم<br/>بر واقعیتِ وسیع؛<br/>این است شادی، و کارِ ما –<br/>آن مسیح!<br/>',NULL,67162,6);
INSERT INTO stanza VALUES('F1170','1','خدا شبانم است تا ابد،<br/>مرا راحتی دهد؛<br/>به آبهای راحت می بَرَد،<br/>آه، او راضی می کند!<br/>',NULL,67163,1);
INSERT INTO stanza VALUES('F1170','chorus','هرآینه مِهر و رحمت دنبالم است،<br/>تمامِ ایامِ عمر من؛<br/>هرآینه مِهر و رحمت دنبالم است،<br/>تمامِ ایامِ عمر من؛<br/>و تا ابد در خانۀ خدا مى مانم،<br/>می خورم از سفرۀ پهن برایم.<br/>هرآینه مِهر و رحمت دنبالم است،<br/>تمامِ ایامِ عمر من.<br/>',NULL,67164,2);
INSERT INTO stanza VALUES('F1170','2','شبانم خود چِراگاهم است،<br/>شبانم، آبهایِ راحت؛<br/>در روح از غنایش می خورم،<br/>می نوشم، آه چه خوشبختم!<br/>',NULL,67165,3);
INSERT INTO stanza VALUES('F1170','3','شبانم جانم زنده کند،<br/>خواسته و احساس و فکرم؛<br/>با اینکه در درّه راه روم،<br/>چه همراهی پیدا كردم!<br/>',NULL,67166,4);
INSERT INTO stanza VALUES('F1170','4','شبانم سفره را حاضر کرد،<br/>در جشنم، شیطان نابوده؛<br/>سَرِ من با روغن مَسح شده،<br/>جامَم از شادی لبریزه!<br/>',NULL,67167,5);
INSERT INTO stanza VALUES('F1170','5','حال در خانۀ او ساکنم،<br/>شادم در نیکیِ خدا؛<br/>خوشی ام مافوقِ گفتنه،<br/>شادیم عیسیْ خدایمه!<br/>',NULL,67168,6);
INSERT INTO stanza VALUES('F1174','1','چه پیروزی و ظفری!<br/>خدا خودش شد انسان،<br/>ذات انسانی پوشید تا<br/>طرحش شود نمایان.<br/>مرگش شیطان را نابود کرد؛<br/>برخاست پسرِ انسان!<br/>',NULL,67169,1);
INSERT INTO stanza VALUES('F1174','2','عیسی با انسانیت اش<br/>توقیف کرد آن زیرک را؛<br/>چون انسان مقاومت کرد،<br/>قبول شد هر آزمون را.<br/>حال در روح از او برخوردار،<br/>صفات او مهیا.<br/>',NULL,67170,2);
INSERT INTO stanza VALUES('F1174','3','در روحِ همین عیسی هست<br/>آن حیاتِ انسانی.<br/>صفاتِ انسانی افزود<br/>بر آن روحِ الهی.<br/>به وفور در این روح بهرِ<br/>انسان هست هر نعمتی.<br/>',NULL,67171,3);
INSERT INTO stanza VALUES('F1174','4','چه اسرارآمیز! لیک راستین!<br/>این شخص هست حالا در من.<br/>در قلبم وسعت می یابد –<br/>او می شود زیستنم.<br/>هللویاه! هللویاه!<br/>دائم ستایش کنم.<br/>',NULL,67172,4);
INSERT INTO stanza VALUES('F1174','5','آه، چه شگرف و باشکوه!<br/>در جسم ظاهر شد خدا.<br/>ما اعضای بدنِ او<br/>ابراز می کنیم او را.<br/>بهرِ بنای مسکن اش<br/>حیاتش را داریم ما.<br/>',NULL,67173,5);
INSERT INTO stanza VALUES('F1179','1','با او مصلوب شد انسان کهنه،<br/>و نیز دفن شد آن ذاتِ مارگونه<br/>با تمامِ فسادِ درونش؛<br/>کارش تمام شد، از آنِ من است<br/>این حقیقت.<br/>',NULL,67174,1);
INSERT INTO stanza VALUES('F1179','2','اما یک شخص در روحم است اکنون،<br/>مولود شد همچون کودکی زبون؛<br/>او با شیرِ کلام رشد کند تا<br/>شود انسانِ باطن و به دست<br/>آرَد دل را.<br/>',NULL,67175,2);
INSERT INTO stanza VALUES('F1179','3','مسیح، شخصِ من، باید قلبم را<br/>مالک شود، با مقامی والا.<br/>مالکِ قبلی مُرد، هنوز آید.<br/>خدا، بیا؛ ذهن، احساس، اراده<br/>تو را خواهد.<br/>',NULL,67176,3);
INSERT INTO stanza VALUES('F1179','4','خداوند، یک روح و یکدل هستیم،<br/>انسانیت، الوهیت با هم؛<br/>لیک باید عضوی مناسب باشد<br/>تا شخصیتِ پرجلالِ تو<br/>ابراز شود.<br/>',NULL,67177,4);
INSERT INTO stanza VALUES('F1179','5','پس به تو دهم امروز قلبم را،<br/>تا باشد خانۀ تو، ای خدا،<br/>که بمانی، جایی برای تو،<br/>تا کارِ بازیابی اوج گیرد در<br/>انسانِ نو.<br/>',NULL,67178,5);
INSERT INTO stanza VALUES('F1191','1','در درونِ روحم چشمه حیات جاریست –<br/>خدا در من جریان دارد؛<br/>خدا پدرْ منشأ، مسیحْ پسرْ مسير،<br/>و روحْ حیاتم می بخشد.<br/>',NULL,67179,1);
INSERT INTO stanza VALUES('F1191','chorus','جریانِ حیات گنجینه ام،<br/>آخر خودم را انکار کنم؛<br/>خدا عمیق تر کن جریانت؛<br/>تا آیی حیات تاجم شود.<br/>',NULL,67180,2);
INSERT INTO stanza VALUES('F1191','2','در مرتعهای سبز، عیسی خوابانَدَم؛<br/>به آبهای راحت بَرَد؛<br/>درگيرى ندارم؛ هر تلاش بیهودَه ست؛<br/>در جریانْ كاملاً خوشبختم.<br/>',NULL,67181,3);
INSERT INTO stanza VALUES('F1191','3','عیسی روزی مرا خوانْد به قُدس الاقداس،<br/>به زندگی در حضورش،<br/>هللویاه، شنیدم کلامى مُشوق:<br/>«بمان، شاخۀ تاک هستى.»<br/>',NULL,67182,4);
INSERT INTO stanza VALUES('F1193','1','خدای پدر در مسیح عیسی<br/>حیات است، چون روح، در جریان است.<br/>چه مسرت بخش، این شخص چقدْر عالیست!<br/>غنی و وافر، حیاتِ ماست.<br/>',NULL,67183,1);
INSERT INTO stanza VALUES('F1193','2','تولد تازه دریافت کردیم<br/>چون خود را به آن حیّ بازکردیم.<br/>باز مولود گشتیم، با حیاتی دیگر.<br/>چون سیل در ما، ما را کند پُر.<br/>',NULL,67184,2);
INSERT INTO stanza VALUES('F1193','3','او در ما روحِ زنده می باشد<br/>و از روحمان جاری شود<br/>به درون قلب، دگرگون می سازد<br/>با حیاتی که به ما بخشَد.<br/>',NULL,67185,3);
INSERT INTO stanza VALUES('F1193','4','باید هماهنگی کنیم با او،<br/>ذهنمان را بر او گذاریم.<br/>باید بازگردیم از هر بیراهه ای،<br/>تا فکرمان پر شود با او.<br/>',NULL,67186,4);
INSERT INTO stanza VALUES('F1193','5','خداوند، حال در روح ما هستی.<br/>قصدت را در ما اجرا کنی؛<br/>ذهنِ سرگردان، افکارت را رد کن،<br/>حیات و آرامش پیدا کن.<br/>',NULL,67187,5);
INSERT INTO stanza VALUES('F1193','6','خدا،  هر فکر را اسیرِ خود کن،<br/>از مسرت ها در کلامت<br/>تأمین می شویم، در کلام می مانیم،<br/>تا افکار را تقدیس نماییم.<br/>',NULL,67188,6);
INSERT INTO stanza VALUES('F1193','7','بیا به تمرین ادامه دهیم<br/>با تنها چشم دوختن بر عیسی.<br/>ستایش بر او بهرِ راهش امروز!<br/>ذهنِ ما بر او مانَد هر روز.<br/>',NULL,67189,7);
INSERT INTO stanza VALUES('F1196','1','خداست زنده  - بگو: هللویاه!<br/>در ماست زنده – بگو: هللویاه!<br/>غنایش چشیم،<br/>چون اوست سهمِ ما.<br/>بخوان: «عیسی» تا بچشی.<br/>',NULL,67190,1);
INSERT INTO stanza VALUES('F1196','2','گردهم آییم – هیچ چیز بهتر نیست –<br/>چون در روح خانوادَش هستیم؛<br/>بدنش هستیم!<br/>ابرازش کنیم.<br/>عیسی واقعیتِ ماست.<br/>',NULL,67191,2);
INSERT INTO stanza VALUES('F1196','3','در کلیساها پُر شویم حالا<br/>بهرِ ابرازش در کل دنیا<br/>توزیعِ عیسی،<br/>به همه شهرها –<br/>این جا مسیح را خواهد دید.<br/>',NULL,67192,3);
INSERT INTO stanza VALUES('F1198','1','خدا جریانی ست نیرومند،<br/>جاریست در طی اعصار.<br/>بهرِ جریانش در انسان،<br/>طی کرد مراحلی را؛<br/>لیک فقط یک خداست،<br/>یک جریانِ جاوْدان؛<br/>مراحلش راهی ست<br/>تا رِسَد به انسان،<br/>او حالا در ما جاریست!<br/>',NULL,67193,1);
INSERT INTO stanza VALUES('F1198','2','در آغاز می توانیم دید،<br/>خدا چون نهری جاریست؛<br/>آن نهر حاملِ درخت است،<br/>که حیاتِ خودِ اوست.<br/>و در آخر هم نیز،<br/>هنوز آن نهر باقیست،<br/>او در برّه جاریست،<br/>درختِ حیات نیز،<br/>خدا تا ابد جاریست.<br/>',NULL,67194,2);
INSERT INTO stanza VALUES('F1198','3','خدا در انسان جاری شد،<br/>که نامش مسیحْ عیساست.<br/>او جانش را بهرِ ما داد<br/>تا ما را حیات بخشد.<br/>شیطان سعی اش را کرد<br/>جریان را بازدارد –<br/>بر صلیب بُرد او را،<br/>شکافت پهلویش را –<br/>لیک خون و آب جاری شد!<br/>',NULL,67195,3);
INSERT INTO stanza VALUES('F1198','4','خون و آب از او جاری گشت،<br/>در نهرِ پاکِ نجات.<br/>خون، گناهان را پاک کند؛<br/>آب، نو-تولد دهد.<br/>و حال آن روح جاریست،<br/>خدا را آوَرَد.<br/>کارِ دشمن، تنها<br/>آزاد کرد جریان را.<br/>و خدا دائم جاریست.<br/>',NULL,67196,4);
INSERT INTO stanza VALUES('F1206','1','میدانِ دویدن است، هللویاه،<br/>راهی بهرِ بَرنده شدن.<br/>آنها که شروع کردند، هللویاه،<br/>خدا گفته، «چِشم بِدوز به او!»<br/>',NULL,67197,1);
INSERT INTO stanza VALUES('F1206','chorus','چِشم بِدوز!  آه چِشم بِدوز!<br/>چِشم به عیسی حال امروز!<br/>چِشم بدوز از همه چیز سویِ عیسی،<br/>چِشم بدوز از همه چیز به او!<br/>',NULL,67198,2);
INSERT INTO stanza VALUES('F1206','2','چِشم بَردار از دُور و بَر، هللویاه،<br/>چِشم بردار از نزاع و غوغا؛<br/>چِشم بدوز به آرامش، هللویاه،<br/>چِشم بدوز از همه چیز به او.<br/>',NULL,67199,3);
INSERT INTO stanza VALUES('F1206','3','چِشم بردار از روانِ  بی ثباتت،<br/>چِشم بردار از نفْسِ درمانده؛<br/>چِشم بدوز سویِ هدف، هللویاه!<br/>چِشم بدوز از همه چیز به او.<br/>',NULL,67200,4);
INSERT INTO stanza VALUES('F1206','4','چِشم بردار از گذشته، هللویاه،<br/>چِشم بردار از هر دو بد وُ خوب؛<br/>به آن جاویدان بچسب، هللویاه،<br/>چِشم بدوز از همه چیز به او.<br/>',NULL,67201,5);
INSERT INTO stanza VALUES('F1206','5','چِشم بدوز به صورتش، هللویاه،<br/>کامل کند آنچه شروع کرد.<br/>چه فیضی است رسیدن، هللویاه –<br/>می رسیم با چِشم دوختن به او!<br/>',NULL,67202,6);
INSERT INTO stanza VALUES('F1210','1','از کلام، امیدم به بازگشتش<br/>تا وجودم رهایی یابد؛<br/>لیک در زمانِ رنج و مصیبت،<br/>امیدی دیده نمی شود.<br/>پس دعا به زبان نمی آید،<br/>تنها از دل ناله برآید.<br/>ناله های روح یاری می دهد<br/>تا در ضعفم به خدا آیم.<br/>',NULL,67203,1);
INSERT INTO stanza VALUES('F1210','2','خداوند، دعایم رنجِ بیش نیست،<br/>لیک از آزمونها رها شوم،<br/>که جامِ تلخی از من دور شود،<br/>به ارادۀ تو، و نه من.<br/>با این که سختیها اطرافم هست،<br/>هنوز در دل آرامشی هست،<br/>چون عشق خدا که در دل جاریست<br/>دل را سیراب، شک را برکَنَد.<br/>',NULL,67204,2);
INSERT INTO stanza VALUES('F1210','3','تظمینِ کل! خدا دستور داده<br/>همه چیز را با اختیارش؛<br/>هر شخص را (با این که ما نبینیم)،<br/>و هر چیز را بر طبق طرحش.<br/>در هر آزمون پاسخِ پدر است<br/>به دعا و ناله های روح؛<br/>باشد او ما را به دست آورَد<br/>تا در جلال با مسیح باشیم.<br/>',NULL,67205,3);
INSERT INTO stanza VALUES('F1210','4','چطور رسیدگی نکند چون<br/>پسرِ خود را دریغ نداشت؟<br/>چطور دستِ کوزه گر ظرفش را<br/>نیمه شکل داده رها کند؟<br/>چون مرکزِ ارادۀ خدا<br/>این است که برادران باشیم<br/>بهرِ مسیح، همان نخست زاده،<br/>و کامل همشکل او شویم.<br/>',NULL,67206,4);
INSERT INTO stanza VALUES('F1210','5','وارثانش! با خداوندْ عیسی!<br/>این امیدِ جلال بهرِ ماست!<br/>رنجهای این زمان در قیاس با<br/>جلال که آشکار شود، هیچ است!<br/>آری، بیش از پیروزیم در اینها،<br/>از او که ما را محبت کرد؛<br/>به زودی انتظار، در ظهورِ<br/>پسرانِ خدا، سر آید!<br/>',NULL,67207,5);
INSERT INTO stanza VALUES('F1218','1','گر خواهی از دنیا رها بشی،<br/>آمین گو کلام را!<br/>گر خواهی در حقیقت زیست کنی،<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>دریافتِ کلام، ایمان به کلام،<br/>آمین گو کلام را!<br/>',NULL,67208,1);
INSERT INTO stanza VALUES('F1218','2','گر از گناه و نفْس ات خسته ای،<br/>آمین  گو کلام را!<br/>گر ذهنت با خدا تازه کنی،<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>کلامت زنده، قوت دهنده –<br/>آمین گو کلام را!<br/>',NULL,67209,2);
INSERT INTO stanza VALUES('F1218','3','مسیح چون کنعان سرزمینِ ماست –<br/>آمین گو کلام را!<br/>گر خواهی آیی، قلبت نکن سخت –<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>کلام تمیز دهد مسائل را –<br/>آمین گو کلام را!<br/>',NULL,67210,3);
INSERT INTO stanza VALUES('F1218','4','عیسی می آید، حالا در راه است-<br/>آمین گو کلام را!<br/>آیا حاضری گر امروز آید –<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>آمین گو کلام را!<br/>کلامش ما را به عیسی بَرَد –<br/>آمین گو کلام را!<br/>',NULL,67211,4);
INSERT INTO stanza VALUES('F1220','1','پرده  را بردار از قلبم؛<br/>آشکار ساز، خداوند؛<br/>بینشی روشن دِه به من،<br/>از بازیابیِ خود.<br/>',NULL,67212,1);
INSERT INTO stanza VALUES('F1220','2','با مکاشفه درک کنم<br/>قدرتِ رستاخیز؛<br/>چون با ایمان دریافت کنم،<br/>به کلیسا آیم.<br/>',NULL,67213,2);
INSERT INTO stanza VALUES('F1220','3','قدرتت آزادم کرد از<br/>چیزهای دنیوی؛<br/>آورد به کلیسا اینجا،<br/>آن قدرتِ عالی.<br/>',NULL,67214,3);
INSERT INTO stanza VALUES('F1220','4','در کلیسای محل، من<br/>دارم شخصِ تو را؛<br/>شخصِ برونی کم شود،<br/>قلبم مالِ خدا.<br/>',NULL,67215,4);
INSERT INTO stanza VALUES('F1220','5','شخصِ من هستی، خداوند؛<br/>من با تو مصلوب ام.<br/>شخصِ درونی ترمیم شد،<br/>چون تو هستی در من.<br/>',NULL,67216,5);
INSERT INTO stanza VALUES('F1220','6','چون اعضا نفْس انکار کنند،<br/>بدنت را دانیم؛<br/>چون از تو برخودار شویم،<br/>انسانِ نو بینیم.<br/>',NULL,67217,6);
INSERT INTO stanza VALUES('F1220','7','کلیسا، یک انسانِ نوست<br/>در محلْ ابرازش؛<br/>بدنت انسانِ جمعی ست،<br/>آشکار شود شخصش.<br/>',NULL,67218,7);
INSERT INTO stanza VALUES('F1221','1','عیسی، شبان نیکومان<br/>ما را از آغل آورد<br/>به مرتع های سرشارش،<br/>به غنای نامحدود.<br/>',NULL,67219,1);
INSERT INTO stanza VALUES('F1221','chorus','کلیسا شگرف،<br/>جشن از انباری غنی!<br/>اینجا در وحدت ساکنیم،<br/>حیاتِ جاوْدان داریم.<br/>',NULL,67220,2);
INSERT INTO stanza VALUES('F1221','2','او در فرقه ها ما را جُست،<br/>خسته و هم گرسنه؛<br/>به سرزمینِ نیک آورد،<br/>به روحمان، چه نیکو!<br/>',NULL,67221,3);
INSERT INTO stanza VALUES('F1221','chorus','کلیسا شگرف،<br/>جشن با انباری غنی!<br/>اینجا در وحدت ساکنیم،<br/>حیاتِ جاوْدان داریم.<br/>',NULL,67222,4);
INSERT INTO stanza VALUES('F1221','3','عیسی خودش مرتعِ ماست،<br/>غذایی که می خوریم؛<br/>چون گوسفندانِ پرواری،<br/>وقتی که باهم هستیم.<br/>',NULL,67223,5);
INSERT INTO stanza VALUES('F1221','chorus','کلیسا شگرف،<br/>جشن با انباری غنی!<br/>اینجا در وحدت ساکنیم،<br/>حیاتِ جاوْدان داریم.<br/>',NULL,67224,6);
INSERT INTO stanza VALUES('F1221','4','ساکن بر کوهی بلندیم،<br/>تَر با شبنمِ صبحگاه،<br/>سیراب شویم سَر ِچشمه،<br/>با آب نو و زنده.<br/>',NULL,67225,7);
INSERT INTO stanza VALUES('F1221','chorus','کلیسا شگرف،<br/>جشن با انباری غنی!<br/>اینجا در وحدت ساکنیم،<br/>حیاتِ جاوْدان داریم.<br/>',NULL,67226,8);
INSERT INTO stanza VALUES('F1221','5','مسیح آرامی و لذت،<br/>اینجا هیچ باک نداریم؛<br/>اینجا گوسفندان امن هستند،<br/>در حضور عزیزش.<br/>',NULL,67227,9);
INSERT INTO stanza VALUES('F1221','chorus','کلیسا شگرف،<br/>جشن با انباری غنی!<br/>اینجا در وحدت ساکنیم،<br/>حیاتِ جاوْدان داریم.<br/>',NULL,67228,10);
INSERT INTO stanza VALUES('F1222','1','ستایش کنید خدای عالم را،<br/>او در اورشلیم نو ساکن است.<br/>کارهایش را اعلام کن در بینِ ما،<br/>تختش در آسْمان، لیک با انسان است.<br/>آه، آن نجات از صهیون می آید؛<br/>او ما را از اسارت بازگردانْد.<br/>حال شادیم و بی نهایت خوشحال؛<br/>حال شادیم و بی نهایت خوشحال!<br/>',NULL,67229,1);
INSERT INTO stanza VALUES('F1222','2','او در شهر قدوس با ما ساکن است؛<br/>خدای ما، نامت چقدْر عالیست!<br/>تختش بر تمجیدِ مقدسین است؛<br/>همه خشنودی اش در صهیون است.<br/>حال حرکت او در کلیساهاست –<br/>او سهم ماست، با او راضی هستیم.<br/>آه، چه میراث نیکویی داریم؛<br/>آه، چه میراث نیکویی داریم!<br/>',NULL,67230,2);
INSERT INTO stanza VALUES('F1222','3','کِه در مسکنِ او ساکن می شود؟<br/>کِه به کوه قدس صعود می کند؟<br/>آنها که جویندش با قلبی خالص؛<br/>این نسلی که رویَش را می جویند.<br/>آه، جویید رویَش را ای مردمان،<br/>باز کن قلبت، بگذار شاه بیاید.<br/>او آید، و حکم و زیست خواهد کرد؛<br/>او آید، و حکم و زیست خواهد کرد!<br/>',NULL,67231,3);
INSERT INTO stanza VALUES('F1222','4','بنگر! مسکنِ خدا با انسان است؛<br/>عِمانوئیل – خدا با ماست، گوییم.<br/>همه چیز انجام شد، همه بیایند؛<br/>مسیح، کلیسا – خدا با انسان!<br/>سر بلند کنید، شهرهای زمین،<br/>شاه می آید، درها را باز کنید.<br/>ستایش کن – او آید حکم کند!<br/>ستایش کن – او آید حکم کند!<br/>',NULL,67232,4);
INSERT INTO stanza VALUES('F1225','1','عیسی، شناختت در بدن،<br/>نیاز شدیدم است،<br/>تو را در اعضایت دیدن،<br/>مِیل و دعای من است.<br/>نه تنها سَروری ات را<br/>در تکرَوی شناسم،<br/>بلکه جسم پوشیدنت را<br/>در مسیح-بدن بینم.<br/>',NULL,67233,1);
INSERT INTO stanza VALUES('F1225','2','طیِ سالهاست مقدسین<br/>جویای راستی بودند؛<br/>از بیرون و درون گشتند،<br/>تشنۀ دیدنت اند.<br/>حال فاش کن که همان مسیح،<br/>در بدنْ نمایان است؛<br/>آن مسیح که درونِ ماست،<br/>ابرازِ او، بدن است.<br/>',NULL,67234,2);
INSERT INTO stanza VALUES('F1225','3','چه نزدیک به گمراهی ام،<br/>با فکرِ پَرتم از تو،<br/>سَهل است خودخواه تو را جُستن،<br/>لیک بی حقیقتِ تو.<br/>آه، نیازم تو را یافتن<br/>در اعضایت هم اینجاست.<br/>در بین  ما خداست ساکن،<br/>در جسم آشکار شده است.<br/>',NULL,67235,3);
INSERT INTO stanza VALUES('F1225','4','کم کن استقلالم را، تا<br/>به بدن رجوع کنم؛<br/>نه تنها جویَم آسْمان را،<br/>لیک حسِ کلیسا را.<br/>باشد سنگِ بنا باشیم،<br/>نه گِلِ بی شکل و سود،<br/>خواسته ات را کسب کن در ما،<br/>تا نشان دهیم تو را.<br/>',NULL,67236,4);
INSERT INTO stanza VALUES('F1226','1','كليساى مسيح پُر جلاله، ما از آن هستيم-<br/>خوشحالیم که خدا ما را یکی کرد!<br/>يک بدن در اين جهانه و ما عضوِ آن هستيم-<br/>هللویاه، خدا ما را یکی کرد!<br/>',NULL,67237,1);
INSERT INTO stanza VALUES('F1226','chorus','هللوياه بهرِ بدن!<br/>ما هستيم اعضاى بدن!<br/>ما هستيم براى بدن!<br/>هللوياه، خدا ما را یکی كرد!<br/>',NULL,67238,2);
INSERT INTO stanza VALUES('F1226','2','نَه مسيحیِ منفرد، بلكه يک فرد جمعى-<br/>اين بهرِ ابرازِ كاملِ خداست؛<br/>نَه كليساهاى تنها، بلكه بدنِ جمعى-<br/>هللوياه، در بدن هستيم حالا!<br/>',NULL,67239,3);
INSERT INTO stanza VALUES('F1226','chorus','هللوياه بهرِ بدن!<br/>شيطان مى لرزد از بدن!<br/>ما پيروز هستيم در بدن!<br/>هللوياه، در بدن هستيم حالا!<br/>',NULL,67240,4);
INSERT INTO stanza VALUES('F1226','3','هفت چراغدانِ طلایى، همه در ذاتْ الهى-<br/>هيچ دگر حياتْ مجاز نمى داند.<br/>تا در ذاتِ او يكى هستيم، چراغدان درخشد-<br/>هللوياه، هم اكنون درخشان است.<br/>',NULL,67241,5);
INSERT INTO stanza VALUES('F1226','chorus','هللوياه بهرِ بدن!<br/>بهرِ شمعدانىِ بدن!<br/>چه طلایى و درخشان!<br/>هللوياه، هم اكنون درخشان است!<br/>',NULL,67242,6);
INSERT INTO stanza VALUES('F1226','4','چطور ما يكى، الهى و درخشان بمانيم؟<br/>هللوياه، راهش خوردنِ عيساست!<br/>او درختِ حيات، مَنّا و جشنِ هميشه نوست-<br/>هللوياه، هر روز بخوریم او را!<br/>',NULL,67243,7);
INSERT INTO stanza VALUES('F1226','chorus','يكى با خوردنِ عيسى!<br/>قدوس با خوردنِ عيسى!<br/>تابان با خوردنِ عيسى!<br/>هللوياه، راهش خوردنِ عيساست!<br/>',NULL,67244,8);
INSERT INTO stanza VALUES('F1229','1','کلیسا خواستِ مسیح<br/>و خشنودیِ اوست.<br/>سخن و کارِ مسیح،<br/>با نگرش به اوست.<br/>عشقش به او استوار،<br/>منصرف نشود؛<br/>قبل از بنیاد عالم،<br/>فکرش با او پُر بود.<br/>',NULL,67245,1);
INSERT INTO stanza VALUES('F1229','2','حوّای کلِ خلقت،<br/>دلخوشیِ او بود،<br/>و مشخصات آن،<br/>در نظرش خوش بود.<br/>خلقت به وجود آمد،<br/>لیک در قلبِ خدا<br/>حسی درک ناپذیر بود<br/>تنها بهرِ عروس.<br/>',NULL,67246,2);
INSERT INTO stanza VALUES('F1229','3','پس او خواست تا همتایش<br/>را بدست آورد:<br/>این قصدِ قاطعِ او<br/>همیشه یکسان است.<br/>با اینکه گناه آمد<br/>و انسان گمراه شد،<br/>خدا او را ترک نکرد،<br/>قصدش عوض نشد.<br/>',NULL,67247,3);
INSERT INTO stanza VALUES('F1229','4','پس رحمتش جاری شد<br/>و عشقِ عظیمش،<br/>با حکمتی بی نظیر،<br/>خود، جویای او شد.<br/>میزان عشق او را<br/>فقط خدا داند!<br/>جان خود را فدا کرد<br/>عطرش هنوز پخش است.<br/>',NULL,67248,4);
INSERT INTO stanza VALUES('F1229','5','و حالا در رستاخیز<br/>او بسیار نزدیک است،<br/>با محبتِ بسیار<br/>در جلال هویداست.<br/>چون جلالِ دامادش<br/>را عروس نِگرَد،<br/>تا وقت عروج رسد<br/>همتایش را بیند.<br/>',NULL,67249,5);
INSERT INTO stanza VALUES('F1230','1','انسان نو، طرح پدر؛<br/>بازخرید کرد از نسل بشر.<br/>هر خاندان، قوم و زبان،<br/>در خودش ما را کرده یکسان.<br/>ابرازِ او بر زمین<br/>فاش کند ارزشش را.<br/>انسان نو، طرحِ پدر؛<br/>بازخرید کرد از نسل بشر.<br/>',NULL,67250,1);
INSERT INTO stanza VALUES('F1230','2','بر صلیب مقررات را<br/>باطل ساخت، یک کرد آن دو را.<br/>با خود داد آشتی ما را،<br/>پس او کوبید سَرِ آن مار را.<br/>دیوارِ جدایی را<br/>شکست چون خوانیم او را؛<br/>بر صلیب مقررات را<br/>باطل ساخت، یک کرد آن دو را.<br/>',NULL,67251,2);
INSERT INTO stanza VALUES('F1230','3','پس شخصت را، خداوندا،<br/>برگیریم و یکدل ایستیم ما؛<br/>پس خود را انکار کنیم<br/>از مسیح-بدن برخورداریم.<br/>در او چون انسانِ نو،<br/>می گیریم سرزمین را.<br/>پس شخصت را، خداوندا<br/>برگیریم و یکدل ایستیم ما.<br/>',NULL,67252,3);
INSERT INTO stanza VALUES('F1232','1','روزی مرده بودیم در گناه،<br/>در دنیایی پر از سرکشی؛<br/>لیک خدا، زنده کردی ما را،<br/>برخیزانده، با خداوند نشاندی.<br/>',NULL,67253,1);
INSERT INTO stanza VALUES('F1232','chorus','عیسی گردِ هم آرَد ما را،<br/>مقدسین را بنگر یکدل.<br/>عشقش بهم پیوندد ما را،<br/>تا به قامتِ خداوند در کمال.<br/>',NULL,67254,2);
INSERT INTO stanza VALUES('F1232','2','پس با مقدسین پی بریم<br/>به ابعادِ وسیعِ خدا.<br/>به عشقِ مسیح، فَرای فهم<br/>عارف شویم، پُر از کمالِ خدا.<br/>',NULL,67255,3);
INSERT INTO stanza VALUES('F1232','3','حال می دانیم قصد خدا را،<br/>آن راز بر ما نمایان شده:<br/>با هم مسیح و کلیسا را<br/>ببینیم و شیطان شود شرمنده.<br/>',NULL,67256,4);
INSERT INTO stanza VALUES('F1232','4','به این علت، ای خدا پدر –<br/>قوت دِه انسان درون را؛<br/>در دلهای ما ساکن بشو،<br/>تا در عشق تو ریشه دوانیم ما.<br/>',NULL,67257,5);
INSERT INTO stanza VALUES('F1232','5','باهم بنا شویم در بدن<br/>چون اعضای بسیارِ مسیح؛<br/>هر یک متناسب در عمل،<br/>رشد کنیم، در عشق بنا شود بدن.<br/>',NULL,67258,6);
INSERT INTO stanza VALUES('F1232','6','یک بهرِ اجرای قصد او،<br/>انسانِ نو در طرحش همین.<br/>در کلیسا جلال باد بر او،<br/>و در عیسی مسیح تا ابد، آمین!<br/>',NULL,67259,7);
INSERT INTO stanza VALUES('F1248','1','ياد آر عهدِ داوود،<br/>«به خانه ام نیايم،<br/>نه رَوَم به تختم،<br/>كه خواب آيد به چشمم،<br/>تا يابم جايى برايت،<br/>خدایا، برایت.»<br/>خدای ما خانه خواهد<br/>كه مردمش آیند.<br/>',NULL,67260,1);
INSERT INTO stanza VALUES('F1248','2','چقدْر نابیناییم،<br/>مَسدود با چيزهاى خود؛<br/>ليک خانه ات ويران –<br/>خدا، بِشکن، واژگون کن؛<br/>بر بلندا بِرویم<br/>و خانه ات سازيم؛<br/>هرگز به فردا نندازيم!<br/>وقتشه!  بسازيم!<br/>',NULL,67261,2);
INSERT INTO stanza VALUES('F1248','3','خدايا، اين روزها،<br/>تكان ده تعدادى را،<br/>مثل وقتِ داوود –<br/>گروهى كه مايل اند<br/>در خانه ات كار كنند،<br/>فرمانِ مبارک!<br/>خواستۀ تو، خواستۀ ماست –<br/>آييم، خدا، سازيم.<br/>',NULL,67262,3);
INSERT INTO stanza VALUES('F1248','4','در آنان كه خوانى،<br/>بى قرارى قرار ده،<br/>برای بنایَت –<br/>وقتِ حاضر شدنه؛<br/>قدرتِ مرگ نبَرَد بر<br/>كليساى بنا!<br/>وقت کم و سازندگان كم –<br/>خدا، بساز در ما!<br/>(چهار خط آخر را تكرار كنيد)<br/>',NULL,67263,4);
INSERT INTO stanza VALUES('F1301','1','عیسی آن ملکوتْ درونِ ماست،<br/>حاکم و تابان، او پرجلال است،<br/>مسیح به عنوان بذر، آن شاه است،<br/>در روحِ ما ملکوتش را کاشت.<br/>',NULL,67264,1);
INSERT INTO stanza VALUES('F1301','chorus','رشد کن در ما، رشد کن در ما؛<br/>حیاتت همه چیزِ ماست.<br/>عیسی بذرِ ملکوت است در ما؛<br/>عیسی ملکوت است، چقدر عالیست!<br/>',NULL,67265,2);
INSERT INTO stanza VALUES('F1301','2','توبه کنیم، ملکوت نزدیک است؛<br/>کار، فکر، احساس و برنامۀ ما<br/>باید تغییر کند در ذهنمان؛<br/>دنیا و خود خواهی ها را ترک کن.<br/>',NULL,67266,3);
INSERT INTO stanza VALUES('F1301','3','ادیان و مذاهب کوتاه هستند،<br/>افکارِ انسان را تعلیم دهند؛<br/>تنها انتظار دارند که از غِیب،<br/>دورانِ ملکوت ظاهر شود.<br/>',NULL,67267,4);
INSERT INTO stanza VALUES('F1301','4','لیک به ما ملکوت آشکار شده،<br/>که چیزی نیست بجز عیسی تنها.<br/>آن، شخصِ مسیح در همۀ ماست،<br/>که چون بذر آید چون خوانیمش ما.<br/>',NULL,67268,5);
INSERT INTO stanza VALUES('F1302','1','نشانهای آخر است،<br/>مسیح بزودی آید؛<br/>باید آماده باشیم –<br/>عیسی دارد می آید!<br/>',NULL,67269,1);
INSERT INTO stanza VALUES('F1302','chorus','باز می آید، باز می آید،<br/>زمان زود می گُذرد،<br/>بانگِ نیمه شب می آید!<br/>باز می آید، باز می آید،<br/>چون دانایان باید حاضر شویم!<br/>عیسی دارد می آید!<br/>',NULL,67270,2);
INSERT INTO stanza VALUES('F1302','2','از خود و نفْس روی گردان،<br/>چشم بر عیسی همزمان؛<br/>وقتِ تأخیر کردن نیست –<br/>عیسی دارد می آید!<br/>',NULL,67271,3);
INSERT INTO stanza VALUES('F1302','3','نادانها بازنگردند؛<br/>چون خداوند بیاید،<br/>روغنِ سوخت ندارند –<br/>عیسی دارد می آید!<br/>',NULL,67272,4);
INSERT INTO stanza VALUES('F1302','4','دانایان وقت دریابند؛<br/>مَست از دنیا نشوند،<br/>پُر با روح، می درخشند –<br/>عیسی دارد می آید!<br/>',NULL,67273,5);
INSERT INTO stanza VALUES('F1302','5','به سوی او رَویم ما،<br/>نه تنها با چراغها<br/>مرتب، لیک با روغن –<br/>عیسی دارد می آید!<br/>',NULL,67274,6);
INSERT INTO stanza VALUES('F1302','6','اکنون در راه است عیسی،<br/>بیدار باش! نگفت روز را؛<br/>در حضور او بمان –<br/>عیسی دارد می آید!<br/>',NULL,67275,7);
INSERT INTO stanza VALUES('F1306','1','چِشم به آمدنت!<br/>تا کِی، نمی دانیم،<br/>لیک از انحراف بازگردان<br/>تا صورتت بینیم.<br/>',NULL,67276,1);
INSERT INTO stanza VALUES('F1306','2','خدمت به خدایِ<br/>زنده، تا دیدارِش؛<br/>پس باید ایمان، عشق، امید<br/>بیابد افزایش.<br/>',NULL,67277,2);
INSERT INTO stanza VALUES('F1306','3','در حضورت، خدا،<br/>امیدواریم باشیم<br/>تاجِ جلال و شادمانی<br/>به آنها که بینیم.<br/>',NULL,67278,3);
INSERT INTO stanza VALUES('F1306','4','چِشم به آمدنت؛<br/>آن روز بس نزدیک است.<br/>باشد قلبمان بی تقصیر<br/>باشد در دیدارت.<br/>',NULL,67279,4);
INSERT INTO stanza VALUES('F1306','5','خداوند می آید<br/>با کلامی رسا،<br/>و مقدسین در مسیح<br/>با او باشند همراه.<br/>',NULL,67280,5);
INSERT INTO stanza VALUES('F1306','6','فرزندانِ روزیم،<br/>فرزندانِ نوریم؛<br/>آن روز نباید چون دزد در<br/>شب باشد بهرِ ما.<br/>',NULL,67281,6);
INSERT INTO stanza VALUES('F1306','7','خداوند، تقدیس کن<br/>تا بی تقصیر باشیم<br/>در روح، روان و بدن تا<br/>آن روز با تو باشیم.<br/>',NULL,67282,7);
INSERT INTO stanza VALUES('F1307','1','آن روز نزدیک شد؛ عیسی زود می آید.<br/>وقت را دریاب، تا از دست نرود.<br/>خدا، ما را حاضر کن: «بنگریمش!»<br/>با دریافتنِ هر لحظه، هر روز.<br/>',NULL,67283,1);
INSERT INTO stanza VALUES('F1307','chorus','عیسی آید، آیا با او می رویم؟<br/>عیسی آید، آیا نفْس را ترک کردیم؟<br/>او می آید دانایان را ببرَد.<br/>آه، باشد بیرون از جشن نمانیم.<br/>',NULL,67284,2);
INSERT INTO stanza VALUES('F1307','2','خدا، کمک کن دریابیم لحظه ها؛<br/>ظرفهامان پُر با مَرهم از بالا؛<br/>کمک کن آمین گوییم در سختیها؛<br/>رشد کن در ما؛ در عشق لبریز شویم.<br/>',NULL,67285,3);
INSERT INTO stanza VALUES('F1307','chorus','او می آید، این لحظه ها نفیس اند.<br/>روغن اینجاست، بیایید بخریم.<br/>آمین آزمایش ها و سختی ها را –<br/>از این طریق ملکوت مالِ ماست.<br/>',NULL,67286,4);
INSERT INTO stanza VALUES('F1307','3','چرخان ما را از امیالِ نفْسانی،<br/>بر صورتِ پُرمهرت چِشم دوزیم.<br/>آه، بِدَویم تا ملاقاتِ داماد،<br/>صبورانه در میدان بمانیم.<br/>',NULL,67287,5);
INSERT INTO stanza VALUES('F1307','chorus','عیسی آید، آیا حضورش داریم؟<br/>عیسی آید، آیا صورتش بینیم؟<br/>آه، بیایید برنگردیم به سُستی،<br/>اما حضورش را نگه داریم.<br/>',NULL,67288,6);
INSERT INTO stanza VALUES('F1307','4','چون عروسش، رَویم به ملاقاتش،<br/>مشعل ها درست، سوزان درخشند،<br/>ظرفهامان پُر، چشمهامان بر جلالش،<br/>تا با او باشیم،  کاملاً راضی.<br/>',NULL,67289,7);
INSERT INTO stanza VALUES('F1307','chorus','آری، راضی – مسیح و عروس با هم.<br/>آری، راضی – تا ابدالاباد.<br/>آه، چه آسایش، شادی، عشق و فیضی<br/>که عروسش باشیم در جشن او!<br/>',NULL,67290,8);
INSERT INTO stanza VALUES('F1308','1','روغن در چراغ داریم، سوزانیم!<br/>روغن در چراغ هست امروز!<br/>به روح، خداوند، یاد آر بازگردیم،<br/>پس بازگردیم، کامل بازگردیم!<br/>',NULL,67291,1);
INSERT INTO stanza VALUES('F1308','chorus','خدا! آمین! هللویاه!<br/>ما روزانه سوزان، سوزانیم!<br/>خدا! آمین! هللویاه!<br/>بازگردیم و بازگردیم!<br/>',NULL,67292,2);
INSERT INTO stanza VALUES('F1308','2','لیک ظرفهامان بهرِ آمدنت<br/>به روغن احتیاج دارند.<br/>پس ظرفها دهیم بهرِ پُر شدن<br/>تا چراغها کم سو نشوند.<br/>',NULL,67293,3);
INSERT INTO stanza VALUES('F1308','chorus','پُر کن، عیسی! پُر کن عیسی!<br/>هر دَم بیشتر بِده از خودت!<br/>پُر کن، عیسی! پُر کن عیسی!<br/>پُر کن با واقعیت!<br/>',NULL,67294,4);
INSERT INTO stanza VALUES('F1308','3','پس سوزان تا دیدارِ خداوند،<br/>پس سوزان تا آن روز آید.<br/>پس با هم به عروسی برویم<br/>و درخشنده سوزان باشیم.<br/>',NULL,67295,5);
INSERT INTO stanza VALUES('F1308','chorus','بیا، عیسی! بیا، عیسی!<br/>بیا، ما را دریاب درخشان!<br/>بیا، عیسی! بیا، عیسی!<br/>بیا، از عروسْ شادمان.<br/>',NULL,67296,6);
INSERT INTO stanza VALUES('F1310','1','عیسی عروسش را خواهد،<br/>پرجلالْ در درون.<br/>آنگاه قلبش راضی شود<br/>چون که هست مثلِ اون.<br/>',NULL,67297,1);
INSERT INTO stanza VALUES('F1310','2','کلامْ کلیسا را تقدیس،<br/>چون او خالص کند؛<br/>پاک کند لک و چین ها را<br/>تا عروسش شود.<br/>',NULL,67298,2);
INSERT INTO stanza VALUES('F1310','3','باید روزها را دریابیم،<br/>در دعا با کلام،<br/>آمین به هر سطر و واژه،<br/>بهرش حاضر شویم.<br/>',NULL,67299,3);
INSERT INTO stanza VALUES('F1310','4','کلامْ نفوذ کند، و روح<br/>و روان را جدا،<br/>تا هر بارِ اضافه از<br/>ما بشود سَوا.<br/>',NULL,67300,4);
INSERT INTO stanza VALUES('F1310','5','خداوند، شکر بهرِ کلام،<br/>مؤثر و زنده.<br/>بهرِ آمدنت، با آن<br/>زیست کنیم همیشه!<br/>',NULL,67301,5);
INSERT INTO stanza VALUES('F1310','6','باشد بازگردانیم تو را<br/>و راضی قلبت را.<br/>با کلامْ جبران کن کمبود،<br/>تو را باشیم همتا.<br/>',NULL,67302,6);
INSERT INTO stanza VALUES('F1314','1','خداوند، می آيى،<br/>روزت نزدیک شده.<br/>مشتاقِ آمدنت ایم!<br/>هيچ کسی، حیات یا<br/>معشوقی نداریم،<br/>جز توعيسى، دامادِ ما!<br/>',NULL,67303,1);
INSERT INTO stanza VALUES('F1314','2','ساعت نزديک شده،<br/>بانگت را شنويم،<br/>با تو در اَبْر پايين آييم.<br/>آه، ساعتِ شيرين<br/>دیدار عروس، داماد<br/>و درکِ عشقِ بى نظير.<br/>',NULL,67304,2);
INSERT INTO stanza VALUES('F1314','3','لحظه ها گذرند،<br/>صورتت را بینیم!<br/>آمين، عيسى خدا بيا!<br/>خواهيم تو را بينيم،<br/>دائم با تو باشيم،<br/>تو که قلبمان بُرده اى.<br/>',NULL,67305,3);
INSERT INTO stanza VALUES('F1314','4','حال لحظه اى بيش نیست؛<br/>تو، خدای داماد<br/>برگردى بهرِ عروست.<br/>اوه هللوياه!<br/>اين را مى طلبيم،<br/>تو همچنين راضى شوى.<br/>',NULL,67306,4);
INSERT INTO stanza VALUES('F1315','1','شاد باش! شاد باش! داماد می آید،<br/>دگر نمانده وقتی<br/>به لحظۀ صبحِ عروسی،<br/>سرودِ نوی شادی.<br/>',NULL,67307,1);
INSERT INTO stanza VALUES('F1315','chorus','آه، روزِ شگرف، صبحِ پرشکوه!<br/>مسیح عشقمان آید:<br/>با ظرفِ پُر، مشعل ها سوزان<br/>به استقبالش رَویم.<br/>شاد باش! شاد باش! داماد می آید،<br/>دگر نمانده وقتی<br/>به لحظۀ صبحِ عروسی<br/>سرودِ نوی شادی.<br/>',NULL,67308,2);
INSERT INTO stanza VALUES('F1315','2','آه، بیا حال وقت را دریابیم،<br/>بیش روغن را بخریم،<br/>ظرفهامان با مرهم پر کنیم<br/>قبل از بانگِ نیمه شب.<br/>',NULL,67309,3);
INSERT INTO stanza VALUES('F1315','3','آه، شادیست حاضر شدن بهرِ<br/>عروسی با خداوند،<br/>حتی در رنجها شریک هستیم<br/>برای چنین پاداش!<br/>',NULL,67310,4);
INSERT INTO stanza VALUES('F1315','4','آه، با چه شادی و سُروری<br/>آغاز خواهد شد آن روز؛<br/>سپس هزار سال ضیافت در<br/>جشنِ عروسی با او!<br/>',NULL,67311,5);
INSERT INTO stanza VALUES('F1319','1','آن كه انبيا مى جُستند،<br/>صادقان مشتاقش،<br/>روزهاى آخر ظاهر شد<br/>در واقعيتش.<br/>',NULL,67312,1);
INSERT INTO stanza VALUES('F1319','chorus','حال در مراحلِ آخريم،<br/>تكاملِ تمامِ اعصار است.<br/>آن ایمانداران به عهدت،<br/>حال در ما کامل شدند.<br/>',NULL,67313,2);
INSERT INTO stanza VALUES('F1319','2','پربركتْ چشمها که بينند،<br/>گوشها که شِنوَند؛<br/>آنچه مَلائک نديدند<br/>حال بر ما روشن شد.<br/>',NULL,67314,3);
INSERT INTO stanza VALUES('F1319','3','حسِ ما يكی و قوى،<br/>فيض اش رایْگان گیریم؛<br/>همه به پيش، تشويق كنيم،<br/>برای ملكوت.<br/>',NULL,67315,4);
INSERT INTO stanza VALUES('F1319','4','خسته نشویم طىِ راه،<br/>با شادی می دَویم؛<br/>چون دانيم حوالىِ نبش،<br/>خداوند را بینیم.<br/>',NULL,67316,5);
INSERT INTO stanza VALUES('F1325','1','خدا قصدی جاوید دارد،<br/>که از ازل ترتیب داد،<br/>و به ابدیَت رِسَد؛<br/>بِین این دو، زمان است.<br/>زمانْ مراحلی دارد،<br/>مراحلِ دستیابی؛<br/>ما در زمانْ مسافریم –<br/>بهرِ ابدیَت ایم.<br/>',NULL,67317,1);
INSERT INTO stanza VALUES('F1325','2','خدا مردمی خواهد داشت<br/>بنا-گشته در طرحش،<br/>مخلوط-شده و هماهنگ،<br/>چون یک ظرف، انسانِ نو.<br/>خداست محتوای این ظرف،<br/>با ذات و حیاتِ او،<br/>روح با روحِ ما آمیخته<br/>بهرِ خشنودیِ او.<br/>',NULL,67318,2);
INSERT INTO stanza VALUES('F1325','3','خدا از سه جهت کار کرد<br/>بهرِ طرحش بی نظیر:<br/>چون پدر، پسر و آن روح<br/>تا در ما توزیع شود!<br/>کلِ خلقت بهرِ این است –<br/>هم آسمان و زمین؛<br/>برای این انسان خلق شد<br/>با روح، روان و بدن.<br/>',NULL,67319,3);
INSERT INTO stanza VALUES('F1325','4','مرکز و هستۀ طرحِ<br/>خدا، روحِ ما باشد؛<br/>با خواندنِ نامِ عیسی<br/>روحمان یکی شود.<br/>از مرکز تا پیرامون را<br/>خدا اشباع خواهد کرد؛<br/>احساس، ذهن و اراده، نو،<br/>در ما خانه اش سازد.<br/>',NULL,67320,4);
INSERT INTO stanza VALUES('F1325','5','پس در حیات بنا شویم،<br/>و در عشق یکی گردیم؛<br/>خدا طرحش کامل کند،<br/>همان طرح که آغاز کرد.<br/>خدایا، در ما زیاد شو<br/>تا با تو بنا شویم<br/>به شکلِ آن ظرفِ جمعی<br/>با تو تنها پُر شویم.<br/>',NULL,67321,5);
INSERT INTO stanza VALUES('F1325','6','چون نتیجه و تکامل،<br/>کلیسا در جلال است.<br/>کمالِ همان نیّت که<br/>از ازل طرح شده است.<br/>خدا ظرفِ جمعی اش را<br/>خواهد داشت با جلالش؛<br/>بهرِ قصدت هستیم، خدا،<br/>اجرا کن قصدت در ما.<br/>',NULL,67322,6);
INSERT INTO stanza VALUES('F1327','1','روزی چشمه ای می جُستم،<br/>که تشنگی را رفع کند،<br/>لیک از هر چیز که نوشیدم،<br/>خشک و ناراضی ماندم من.<br/>یک روز پیداش کردم،<br/>تشنگیم را رفع کرد،<br/>آن منشأ ژَرف، جوشان شد با<br/>آبِ زنده در من.<br/>حال می نوشم!<br/>عیسی، عیساست حیاتم حال،<br/>عیسی، عیساست حیاتم؛<br/>کاملاً خرسندم حال،<br/>عیسی، عیساست حیاتم.<br/>',NULL,67323,1);
INSERT INTO stanza VALUES('F1327','2','پس از چشیدنِ چشمه،<br/>مشتاقِ مکانش بودم؛<br/>یک بینش بر کوهی دیدم<br/>از جماعتِ اورشلیم.<br/>یک روز او پیدام کرد،<br/>به کلیسا آورْد،<br/>خوشی ها اینجا جاوْدان، و<br/>جستجو تمام شد.<br/>هللویاه!<br/>عیسی، عیساست حیاتم حال،<br/>عیسی، عیساست حیاتم؛<br/>کاملاً خرسندم حال،<br/>عیسی، عیساست حیاتم.<br/>',NULL,67324,2);
INSERT INTO stanza VALUES('F1327','3','سرگردان، بس است کوشیدن –<br/>ارزشِ زحمت ندارد،<br/>دل با ایمان باز کن، بگو:<br/>«خداوندْ عیسی»؛ او آید!<br/>امروز او را یابی،<br/>با خواندنِ نامش،<br/>پیوند با او، یکی با او –<br/>نه هرگز مثل قبل<br/>و نخواهی!<br/>عیسی، عیساست حیاتم حال،<br/>عیسی، عیساست حیاتم؛<br/>کاملاً خرسندم حال،<br/>عیسی، عیساست حیاتم.<br/>',NULL,67325,3);
INSERT INTO stanza VALUES('F1331','1','بِچش، ببین که خدا نیکوست؛<br/>بِچش، ببین که خدا نیکوست.<br/>نیک بهرِ تو، نیز بهرِ من؛<br/>پس هرآنچه کنی، بِچش، ببین.<br/>',NULL,67326,1);
INSERT INTO stanza VALUES('F1331','2','بخوان: عيسى – دگرگون سازد؛<br/>بخوان: عيسى – دگرگون سازد.<br/>فیضی عجیب به ما دهد؛<br/>هرجا خوانی: خداوندْ عیسی.<br/>',NULL,67327,2);
INSERT INTO stanza VALUES('F1331','3','عشقِ واقعی به قلبت آید؛<br/>عشقِ واقعی به قلبت آید.<br/>جریانِ عشق را حس کنی؛<br/>مى فهمی که عشق را یافتی.<br/>',NULL,67328,3);
INSERT INTO stanza VALUES('F1331','4','خدا را شکر، بهرِ حیاتش؛<br/>خدا را شکر، بهرِ حیاتش.<br/>در ما جاریست حیاتِ مسیح؛<br/>خدا را شکر کن، چون او در ماست!<br/>',NULL,67329,4);
INSERT INTO stanza VALUES('F1333','1','چه روزِ شادی<br/>که نکنم رویگردانی،<br/>که از ظلمت گرفت عیسی قلبم را<br/>و بُرد به نورِ خود مرا.<br/>',NULL,67330,1);
INSERT INTO stanza VALUES('F1333','2','حال زنده شدم،<br/>با آن حیاتِ واقعی.<br/>نه دیگر اسیرِ امیالِ تُهی؛<br/>در من نهری زِندَست جاری.<br/>',NULL,67331,2);
INSERT INTO stanza VALUES('F1333','3','چون به او رَوَم،<br/>با حیاتش پُر می شوم.<br/>حیاتش در واقع حیاتِ من است؛<br/>او، هللویاه، در من است!<br/>',NULL,67332,3);
INSERT INTO stanza VALUES('F1333','4','عاشقت، خدا،<br/>عشقِ دگر کاسْتی از من.<br/>تو هستی برای ابد حیاتم؛<br/>تو تنها کسی برایم.<br/>',NULL,67333,4);
INSERT INTO stanza VALUES('F1335','1','خداست بزرگ، لایقِ ستایش،<br/>در شهرِ خدایمان،<br/>در کوهِ قدوسیتِ او.<br/>آن در ارتفاعش زیباست، شادیِ جهان است،<br/>کوهِ صهیون در اطرافِ شمال،<br/>همان شهرِ پادشاه.<br/>',NULL,67334,1);
INSERT INTO stanza VALUES('F1336','1','چه تقدیم کنم خداوند را؟<br/>بهرِ، کلِ، احسان هایش به من؟<br/>برگیرم جامِ نجات را،<br/>خوانم، خوانم، خوانم نام خداوند را.<br/>',NULL,67335,1);
INSERT INTO stanza VALUES('F1339','1','اینک چه خوش و چه دلپسند است،<br/>که برادران یکدل  به سر برند!<br/>اینک چه خوش و چه دلپسند است،<br/>که برادران یکدل  به سر برند!<br/>',NULL,67336,1);
INSERT INTO stanza VALUES('F1339','chorus','آن مثلِ روغنِ نیکو بر سر است که<br/>بر ریش فرود می آید،<br/>بر ریشِ هارون:<br/>که تا به ردایش فرود آمد.<br/>',NULL,67337,2);
INSERT INTO stanza VALUES('F1339','2','اینک چه خوش و چه دلپسند است،<br/>که برادران یکدل  به سر برند!<br/>',NULL,67338,3);
INSERT INTO stanza VALUES('F1339','chorus','آن مثل روغنِ نیکو بر سر است که<br/>بر ریش فرود می آید،<br/>بر ریشِ هارون:<br/>که تا به ردایش فرود آمد.<br/>',NULL,67339,4);
INSERT INTO stanza VALUES('F1339','3','چون شبنمِ حِرمون،<br/>و شبنم که فرود آمد<br/>بر روی کوه های صهیون:<br/>آنجا خدا برْکتش را امر کرد،<br/>حتی حیاتِ جاوْدان.<br/>',NULL,67340,5);
INSERT INTO stanza VALUES('F1340','1','پس با شادی آب خواهی کشید<br/>از آن چشمه های نجات.<br/>و خواهی گفت: ستایش<br/>بر خدا.<br/>',NULL,67341,1);
INSERT INTO stanza VALUES('F1340','2','پس با شادی آب خواهی کشید<br/>از آن چشمه های نجات.<br/>و خواهی گفت: ستایش<br/>بر خدا.<br/>',NULL,67342,2);
INSERT INTO stanza VALUES('F1340','3','نامش را بخوان، به همه اعلام کن کارهایش را ،<br/>ذکر کن که نام او متعال است.<br/>فریاد زنید، شما ساکنینِ صهیون:<br/>چون آن قدوسِ اسراییلْ عالیست در بین شما.<br/>',NULL,67343,3);
INSERT INTO stanza VALUES('F1341','1','آری، فِدیه شدگانِ خداوند<br/>سرودخوان بازگردند بر صَهیون؛<br/>و شادیِ جاوید بر سَرِشان باشد.<br/>آری، فِدیه شدگانِ خداوند<br/>سرودخوان بازگردند بر صَهیون؛<br/>و شادیِ جاوید بر سَرِشان باشد.<br/>',NULL,67344,1);
INSERT INTO stanza VALUES('F1341','2','وَجد و شادی حاصل کنند؛<br/>و اندوه و ناله خواهد گریخت.<br/>',NULL,67345,2);
INSERT INTO stanza VALUES('F1341','3','آری، فِدیه شدگانِ خداوند<br/>سرودخوان بازگردند بر صَهیون؛<br/>و شادیِ جاوید بر سَرِشان باشد.<br/>',NULL,67346,3);
INSERT INTO stanza VALUES('F1345','1','وقتی كه قلب به خدا بازگردد،<br/>نقاب برداشته مى شود.<br/>پس قلبت سوىِ خدا بازگردان،<br/>و نقاب برداشته مى شود.<br/>حالْ خداوند آن روح است،<br/>و هر کجا که  روحِ خداست،<br/>آنجا آزاديست - این آزادى!<br/>وقتی كه قلب به خدا بازگردد،<br/>نقاب برداشته مى شود.<br/>',NULL,67347,1);
INSERT INTO stanza VALUES('F1347','1','حال آمد نجات و قوت،<br/>ملكوتِ خدایْمان<br/>و اقتدارِ مسيحِ او:<br/>چون اتهامگرِ برادران افتاد<br/>كه تهمت زد نزدِ خدا روز و شب.<br/>',NULL,67348,1);
INSERT INTO stanza VALUES('F1347','2','و با خونِ برّه بر او پيروز شدند،<br/>و با كلامِ شهادتشان؛<br/>جانشان را تا مرگ دوست نداشتند.<br/>پس شادى کن، شادى، شادى!<br/>',NULL,67349,2);
INSERT INTO stanza VALUES('F1349','1','چه معجزه ای! چه رازی!<br/>خدا و انسان یک شوند!<br/>خدا انسان شد تا انسان<br/>چون او شود؛ اقتصادش!<br/>از خواستِ نیکوی خدا<br/>هدفِ او انجام شود.<br/>از خواستِ نیکوی خدا<br/>هدفِ او انجام شود.<br/>',NULL,67350,1);
INSERT INTO stanza VALUES('F1349','2','جسم پوشید، آن خدا-انسان،<br/>و خواست من مثل او شوم:<br/>در حیات، ذات، خدا گونه،<br/>لیک نه در هستیِ خدا.<br/>خواصِ او صفاتِ من،<br/>جلالِ او از من تابد.<br/>خواصِ او صفاتِ من،<br/>جلالِ او از من تابد.<br/>',NULL,67351,2);
INSERT INTO stanza VALUES('F1349','3','من تنها زیست نمی کنم،<br/>در من خدا زیست می کند.<br/>با مقدسین در خدا،<br/>خانۀ عالمگیرِ او،<br/>و بدنِ زنده اش، ما<br/>ابرازِ جمعی اش هستیم.<br/>و بدنِ زنده اش، ما<br/>ابرازِ جمعی اش هستیم.<br/>',NULL,67352,3);
INSERT INTO stanza VALUES('F1349','4','اورشلیم، آن نهایت و<br/>کمالِ کلِ بینش هاست؛<br/>خدا سه-یکتا، و انسان<br/>سه-بخش – جفت باهم تا ابد –<br/>چون خدا-انسان در هم اند،<br/>یک مسکنِ متقابل؛<br/>جلال خدا در انسان<br/>با شکوه درخشد تابان!<br/>',NULL,67353,4);
INSERT INTO stanza VALUES('F1350','1','اقتصادِ خدا اين است كه ما را مثل خود كند<br/>در حيات و ذات لیک نه در هستی اش<br/>و خود را با ما يک كند، ما را یک با خود،<br/>تا زياد شود و گسترش يابد ابرازش،<br/>تا خواصِ او، تا خواصِ او،<br/>همه در صفاتِ انسان ابراز شود.<br/>',NULL,67354,1);
INSERT INTO stanza VALUES('F1351','1','چه رحمتی، خدای حق را دیدم،<br/>خوشحال، از تاریکی به نور رفتم!<br/>چه فیضی، آزادانه نجات یافتم،<br/>بدون کار، کوشش و قوتم!<br/>',NULL,67355,1);
INSERT INTO stanza VALUES('F1351','2','حال، خداوند، به یاد آر خاندانم را،<br/>حمل کردی گناهان را، باز شد راه؛<br/>حال اجرا کن وعده ات را، در عیسی<br/>«ایمان آور؛ نجات یابد خانه.»<br/>',NULL,67356,2);
INSERT INTO stanza VALUES('F1351','3','بشنو دعایم را بهرِ خاندانم!<br/>دل من با این نذرْ شعله ور است:<br/>«با خاندانم خدا را خدمت کنیم!»<br/>خدا را می پرستیم که حق است!<br/>',NULL,67357,3);
INSERT INTO stanza VALUES('F1353','1','در نورِ حیات باش،<br/>شراکتِ شیرین؛<br/>بنگر بر صورتش،<br/>هر روز جلال کسب کن،<br/>مطیعِ آن روح باش،<br/>شادی، حمد، دعا کن؛<br/>در نورِ حیات باش.<br/>',NULL,67358,1);
INSERT INTO stanza VALUES('F1354','1','چون خداوند از آسمان نزول کند و آید،<br/>خفتگان برخاسته، مرگ نابود شود.<br/>چون خداوند آید، ما زندگان ربوده شویم،<br/>با بدن های دگرگون و آزاد.<br/>',NULL,67359,1);
INSERT INTO stanza VALUES('F1354','chorus','چون خدا آید در جلال<br/>بینیم بدنش پرجلال؛<br/>چون خدا آید در جلال،<br/>ما پسرانش را تبدیل می کند.<br/>',NULL,67360,2);
INSERT INTO stanza VALUES('F1354','2','چون خداوند آید، صبحِ روشن طلوع خواهد کرد،<br/>این شب گذرَد، زاری تمام شود.<br/>چون خداوند آید، روزهای جلال آغاز شود؛<br/>افسوس و تباهی از بین می رود.<br/>',NULL,67361,3);
INSERT INTO stanza VALUES('F1354','3','چون خداوند آید، ستارۀ صبح می درخشد،<br/>آنها که بیدارند پاداش را گیرند.<br/>خداوند چون خورشیدِ عدالت آید حکم کند<br/>و زمین در رحمت ترمیم می شود.<br/>',NULL,67362,4);
INSERT INTO stanza VALUES('F1354','4','بزودی خداوند آید؛ در دعا بیدار باشیم،<br/>کمرها بسته، چراغها درخشان.<br/>بزودی خداوند آید، وفادار خدمت کنیم،<br/>خدمتْ کامل، عطایا بکار بریم.<br/>',NULL,67363,5);
INSERT INTO stanza VALUES('F1359','1','بگير جانم و بگذار<br/>وقفِ تو باشد، خدا؛<br/>بگير لحظه و روزهام،<br/>جارى در شكرِ دائم.<br/>',NULL,67364,1);
INSERT INTO stanza VALUES('F1359','chorus','برایم تحقیر، مصلوب شدی؛<br/>برایم خونت ریخت، جان دادی.<br/>عیسی، عشق و جانم را با میل دهم،<br/>مدام خدمتت کنم.<br/>',NULL,67365,2);
INSERT INTO stanza VALUES('F1359','2','بگير دستهام و بگذار<br/>در عشقت حركت كنند؛<br/>بگير پاهام تا برایت<br/>چابک و زيبا باشند.<br/>',NULL,67366,3);
INSERT INTO stanza VALUES('F1359','3','بگير صدام تا خوانم<br/>فقط براى شاهم؛<br/>بگير لبانم ، بگذار<br/>از پيامت پر باشند.<br/>',NULL,67367,4);
INSERT INTO stanza VALUES('F1359','4','بگير نقره و طلام؛<br/>هيچ چيز دريغ ندارم؛<br/>بگير هوشَم و آن را<br/>طبقِ خواستت به کار بر.<br/>',NULL,67368,5);
INSERT INTO stanza VALUES('F1359','5','بگير اراده ام را،<br/>مالِ توست و نه از من؛<br/>بگير قلبم، قلبِ توست،<br/>تختِ سلطنتِ توست.<br/>',NULL,67369,6);
INSERT INTO stanza VALUES('F1359','6','بگيرعشقم، خدايم<br/>گنجش به پايَت ريزم.<br/>بگير خودم، تا دائم<br/>فقط بهرِ تو باشم.<br/>',NULL,67370,7);
INSERT INTO stanza VALUES('F1360','1','چه پرجلال! چه با ارزش!<br/>آن روح در من ساکن است!<br/>نور و حقیقت می بخشد،<br/>تابَد، رهبری کند.<br/>',NULL,67371,1);
INSERT INTO stanza VALUES('F1360','chorus','پُر كن، پُر كن مرا!<br/>پُر كن از روحَت مرا!<br/>كامل از خودم خالى كن،<br/>پُر كن از روحَت مرا!<br/>',NULL,67372,2);
INSERT INTO stanza VALUES('F1360','2','وعده واقعیست درونم،<br/>حیات آزادم کند  –<br/>از چنگِ گناه رها، از<br/>زورِ مرگ آزاد کند.<br/>',NULL,67373,3);
INSERT INTO stanza VALUES('F1360','3','مشتاقِ چشمۀ حیات،<br/>چون آهو تشنۀ تو –<br/>از پُری ات بنوشم تا<br/>از من جاری شوی تو.<br/>',NULL,67374,4);
INSERT INTO stanza VALUES('F1360','4','نفْسم را به مرگ سپارم،<br/>خدا، تحت تو باشم،<br/>دگرگون شوم به شکلت،<br/>من با تو جاری شوم.<br/>',NULL,67375,5);
INSERT INTO stanza VALUES('F1400','1','خدایم،<br/>خدايم،<br/>او از مرگ برخاسته و هست<br/>خدايم؛<br/>هر زانو خم شه،<br/>هر زبان باز شه:<br/>عيسی مسيح خداست.<br/>',NULL,67376,1);
INSERT INTO stanza VALUES('F1401','1','حال مسيحْ روحِ حيات بخشه،<br/>حال مسيحْ آن روحِ امروز.<br/>حال مسيحْ روحِ حيات بخشه،<br/>بچرخ به روحت و بگو:<br/>',NULL,67377,1);
INSERT INTO stanza VALUES('F1401','chorus','خدايا، آمين،<br/>خدا، آمين، هللوياه!<br/>خدايا، آمين،<br/>خدا، آمين، هللویاه!<br/>',NULL,67378,2);
INSERT INTO stanza VALUES('F1401','2','حال مسيحْ روحِ حيات بخشه،<br/>حال مسيحْ کلامِ زِندَست،<br/>روح در روحِ ما جریان داره،<br/>کلام، حیات است از راهِ –<br/>',NULL,67379,3);
INSERT INTO stanza VALUES('F1401','chorus','دعا، خواندن، ستایش<br/>و خواندنِ نامش؛<br/>دعا، خواندن، ستایش<br/>و خواندن نامش.<br/>',NULL,67380,4);
INSERT INTO stanza VALUES('F1402','1','خدايا عاشقتم،<br/>خيلى عاشقتم؛<br/>بدونِ تو زندگى هيچه.<br/>تو شيفته مى سازى،<br/>و چه گيرا هستى،<br/>ثروت هایت كاوش ناپذير.<br/>نامت عزيز و شيرين،<br/>خواندنت راضى كند؛<br/>تو مال من، من مال تو، خدا.<br/>پيوند، آمیخته با تو،<br/>خدا-انسان در هم؛<br/>پيش مزۀ اورشليمِ نو.<br/>',NULL,67381,1);
INSERT INTO stanza VALUES('F1403','1','همیشه شاد،<br/>پیوسته دعا کن؛<br/>در همه چیز شاکر،<br/>چون این است خواستِ خدا،<br/>در مسیحْ عیسیْ برایت.<br/>',NULL,67382,1);
INSERT INTO stanza VALUES('F1404','1','عشقِ خدا و فيضِ مسيح<br/>و مشاركتِ روحِ قدوس<br/>با شما، با شما باد،<br/>با شما باد، با شما باد.<br/>',NULL,67383,1);
INSERT INTO stanza VALUES('F1404','2','از آن تختِ خدا و برّه<br/>نهری از آبِ حیات جاریست،<br/>روشن چون كريستال، رِسَد به ما.<br/>',NULL,67384,2);
INSERT INTO stanza VALUES('F1405','1','این است روزی،<br/>این است روزی<br/>که خداوند ساخت،<br/>که خداوند ساخت.<br/>',NULL,67385,1);
INSERT INTO stanza VALUES('F1405','chorus','شادی کنیم،<br/>شادی کنیم<br/>و وَجد نماییم<br/>و وَجد نماییم.<br/>',NULL,67386,2);
INSERT INTO stanza VALUES('F1405','2','این است روزی که خداوند ساخت؛<br/>شادی کنیم و وجد نماییم.<br/>این است روزی،<br/>این است روزی که خداوند ساخت.<br/>',NULL,67387,3);
INSERT INTO stanza VALUES('F1406','1','بگذار مِهر ورزم، بدون اجر.<br/>بگذار خدمت کنم، بی پاداش.<br/>بگذار زحمت بکشم، بی یادبود.<br/>بگذار سختی کِشم، بی توجه.<br/>',NULL,67388,1);
INSERT INTO stanza VALUES('F1406','2','آن ریختن است، نه نوشیدن؛<br/>شکستن است، نه حفظ کردن –<br/>جویای برْکت بهرِ دیگران،<br/>حیاتی تسلی بخش، مهربان.<br/>',NULL,67389,2);
INSERT INTO stanza VALUES('F1406','3','نه در انتظارِ دلسوزی،<br/>نه پذیرای ستایشی؛<br/>حتی تنها و فراموش شده؛<br/>حتی بی زبان و ترک گشته.<br/>',NULL,67390,3);
INSERT INTO stanza VALUES('F1406','4','بهای تاجِ صداقتْ اشک و<br/>خون است؛<br/>بهای ترکِ کل، حیاتِ<br/>زوار است.<br/>این بود حیاتِ تو، ای خداوند،<br/>آن وقت که بر زمین راه رفتی؛<br/>با مِیل متحملِ رنج شدی<br/>تا دیگران بیابند آرامی.<br/>',NULL,67391,4);
INSERT INTO stanza VALUES('F1406','5','ندانم آینده چه خواهد آوَرد؛<br/>لیک پیش رَوَم،<br/>دانم که بازگشتی نیست.<br/>پیرو الگوی تو، ای خداوندم،<br/>متحملِ همه، بی گِله.<br/>',NULL,67392,5);
INSERT INTO stanza VALUES('F1406','6','در این زمانِ آزمایش، خدا،<br/>پاک کن اشکهای پنهان مرا؛<br/>یادم دِه تو پاداش من هستی؛<br/>شَوم بهرِ دیگران برْکتی.<br/><br/>',NULL,67393,6);
INSERT INTO stanza VALUES('NS754','1','Sitting in an ordinary home on the couch,<br/>Feasting on the Christ that’s growing in all the saints;<br/>Here I touch the purpose of why I am living—<br/>Eating, drinking, building with the saints!<br/>',NULL,67394,1);
INSERT INTO stanza VALUES('NS754','chorus','Day by day as we partake of such a Christ,<br/>We are built together as His house, so bright!<br/>Here the river’s flowing with the tree of life,<br/>In God’s light we’re headed up aright!<br/>',NULL,67395,2);
INSERT INTO stanza VALUES('NS754','2','Drawn by Him each morning at His dear face we gaze,<br/>Sitting at His feet each day His speaking we heed,<br/>Then in Him we’re living, Him to others shining,<br/>Bearing fruit we’re filled with joy indeed!<br/>',NULL,67396,3);
INSERT INTO stanza VALUES('NS754','3','Holding truth in love we’re growing up into Christ,<br/>Honouring each other, that we’re members we prove;<br/>Through the cross, by Spirit, Christ we are dispensing,<br/>Blended as the one new man we move.<br/>',NULL,67397,4);
INSERT INTO stanza VALUES('NS754','chorus','House to house we’re practising the Body life,<br/>We in life are reigning as His loving bride;<br/>Here we have the foretaste of our destiny—<br/>God and man completely satisfied!<br/>',NULL,67398,5);
INSERT INTO stanza VALUES('NS755','chorus','So that seasons of refreshing may come,<br/>From the presence of the Lord,<br/>From the presence of the Lord.<br/>',NULL,67399,1);
INSERT INTO stanza VALUES('NS755','end-note','(repeat)<br/>',NULL,67400,2);
INSERT INTO stanza VALUES('NS755','chorus','And that He may send the Christ,<br/>And that He may send the Christ,<br/>Who has been previously appointed for you,<br/>',NULL,67401,3);
INSERT INTO stanza VALUES('NS755','chorus','Jesus,<br/>Jesus,<br/>Jesus,<br/>Jesus.<br/>',NULL,67402,4);
INSERT INTO stanza VALUES('NS756','1','I’ve been possessed by God,<br/>Secured with His own blood,<br/>Held by His perfect love,<br/>Our Bridegroom from above.<br/>',NULL,67403,1);
INSERT INTO stanza VALUES('NS756','chorus','I belong to You<br/>And You belong to me!<br/>As one organic entity,<br/>Overcome in me!<br/>',NULL,67404,2);
INSERT INTO stanza VALUES('NS756','2','Engrave Your name on me,<br/>(God as my identity),<br/>And Your holy city named<br/>The New Jerusalem.<br/>',NULL,67405,3);
INSERT INTO stanza VALUES('NS756','chorus','I belong to You<br/>And You belong to me!<br/>As one organic entity,<br/>Overcome in me!<br/>',NULL,67406,4);
INSERT INTO stanza VALUES('NS756','3','Dear Lord, I am Your claim,<br/>I will treasure our new name;<br/>I will call Your name again,<br/>The wedding can begin!<br/>',NULL,67407,5);
INSERT INTO stanza VALUES('NS756','chorus','I belong to You<br/>And You belong to me!<br/>As one organic entity,<br/>Overcome in me!<br/>',NULL,67408,6);
INSERT INTO stanza VALUES('NS757','chorus','Everything is in the Breath, O Lord! (Exo. 30)<br/>Though I don’t know what I need, You know. (Rom. 8:26)<br/>I don’t believe in what I feel or am—<br/>I believe the Breath in me who can.<br/>',NULL,67409,1);
INSERT INTO stanza VALUES('NS757','chorus','I can’t live without Thee, Jesus,<br/>As breath to me.<br/>Lord, I breathe me out and breathe Thee in. (Lam. 3:55-56)<br/>I adore Thee, precious Jesus—<br/>How rich and free! (Rom. 10:12)<br/>Come in, and live in me.<br/>',NULL,67410,2);
INSERT INTO stanza VALUES('NS758','1','The more we worship God for His mercy,<br/>The more we will be uplifted;<br/>The more we worship God for His mercy,<br/>The more we’re deeply in His heart.<br/>',NULL,67411,1);
INSERT INTO stanza VALUES('NS758','chorus','“I will have mercy on whomever I will;”<br/>So it’s not of him who runs nor wills,<br/>But of God the One who shows mercy at will,<br/>All of grace, not of works, to His praise.<br/>',NULL,67412,2);
INSERT INTO stanza VALUES('NS758','2','The more we worship God for His mercy,<br/>The more we shall taste His sweetness;<br/>The more we worship God for His mercy,<br/>The more we shall gaze upon Him.<br/>',NULL,67413,3);
INSERT INTO stanza VALUES('NS758','chorus','Lord, I thank You for Your rich mercy which flowed,<br/>Reaching me even when I had strayed,<br/>That I might live Christ in the church as Your bride.<br/>I will praise! I will sing! O I’m blest!<br/>I will praise! I will sing! O I’m blest!<br/>',NULL,67414,4);
INSERT INTO stanza VALUES('NS759','chorus','And a man will be like a refuge from the wind,<br/>And a covering from the tempest,<br/>Like streams of water in a dry place,<br/>Like the shadow of a massive rock<br/>in a wasted land.<br/>',NULL,67415,1);
INSERT INTO stanza VALUES('NS759','chorus','Christ is that Man as our refuge,<br/>He is our shield from the tempest,<br/>He is our comfort, satisfaction<br/>and supply in a dry place,<br/>He is our shade from all the heat<br/>in a wasted land.<br/>',NULL,67416,2);
INSERT INTO stanza VALUES('NS760','1','When we call Lord Jesus,<br/>Do you know what we get?<br/>We get a God who’s processed now,<br/>The all-inclusive Spirit!<br/>',NULL,67417,1);
INSERT INTO stanza VALUES('NS760','chorus','He’s olive oil, He’s myrrh,<br/>He’s cinnamon, and He’s calamus,<br/>The power of Christ’s resurrection,<br/>He’s the cassia in us!<br/>',NULL,67418,2);
INSERT INTO stanza VALUES('NS760','2','Olive oil, the Spirit,<br/>Anoints us all our days.<br/>Myrrh the fragrant death of Christ<br/>Negative secretions slays!<br/>',NULL,67419,3);
INSERT INTO stanza VALUES('NS760','chorus','He’s olive oil, He’s myrrh,<br/>He’s cinnamon, and He’s calamus,<br/>The power of Christ’s resurrection,<br/>He’s the cassia in us!<br/>',NULL,67420,4);
INSERT INTO stanza VALUES('NS760','3','Cinnamon is for Christ’s death,<br/>So effective and sweet.<br/>Calamus—Christ’s resurrection<br/>Nothing can defeat!<br/>',NULL,67421,5);
INSERT INTO stanza VALUES('NS760','chorus','He’s olive oil, He’s myrrh,<br/>He’s cinnamon, and He’s calamus,<br/>The power of Christ’s resurrection,<br/>He’s the cassia in us!<br/>',NULL,67422,6);
INSERT INTO stanza VALUES('NS760','4','Cassia—resurrection,<br/>Repelling insects and snakes.<br/>All of these ingredients<br/>Are now for us to take!<br/>',NULL,67423,7);
INSERT INTO stanza VALUES('NS760','chorus','He’s olive oil, He’s myrrh,<br/>He’s cinnamon, and He’s calamus,<br/>The power of Christ’s resurrection,<br/>He’s the cassia in us!<br/>',NULL,67424,8);
INSERT INTO stanza VALUES('NS761','1','In these times of restlessness,<br/>In these times of uncertainty,<br/>When all we trusted has become<br/>But sand and we sink helplessly,<br/>Reaching out, a Rock we hold.<br/>He is still and unshakable.<br/>Eternally and silently,<br/>He waited for us with love untold.<br/>',NULL,67425,1);
INSERT INTO stanza VALUES('NS761','2','How we think we have control<br/>When all things go predictably,<br/>But when waves crash, when storm winds blast,<br/>We see our human frailty.<br/>Then He’s always there to say,<br/>“It is I, do not be afraid.”<br/>It’s up to us to take Him in<br/>Our boats, our lives, for Him e’er to stay.<br/>',NULL,67426,2);
INSERT INTO stanza VALUES('NS761','chorus','So that’s why we call, “O Lord Jesus!”<br/>Desper’tely for peace inside<br/>And peace He gives,<br/>A peace beyond understanding.<br/>And still then we call, “O Lord Jesus!”<br/>Just to find the peace supplied<br/>Is Christ Himself resting in our being.<br/>',NULL,67427,3);
INSERT INTO stanza VALUES('NS762','1','He stepped out of glory<br/>And put on the lowly.<br/>And life’s very Author<br/>A creature became.<br/>Despised and forsaken,<br/>Afflicted with sorrow,<br/>From infinite splendor<br/>To the likeness of shame.<br/>',NULL,67428,1);
INSERT INTO stanza VALUES('NS762','2','He chose to be humbled,<br/>He chose limitation,<br/>He chose to be finite,<br/>He chose to be man.<br/>God’s unfathomed purpose<br/>Found substance in Jesus;<br/>A two-natured being—<br/>The unique God-man.<br/>',NULL,67429,2);
INSERT INTO stanza VALUES('NS762','3','His own shell was broken,<br/>Releasing His glory.<br/>This life-impartation<br/>Produced many grains.<br/>The Firstborn rejoices<br/>With His many brothers;<br/>An incorporation—<br/>Divine and human.<br/>',NULL,67430,3);
INSERT INTO stanza VALUES('NS762','4','We cannot but love Him,<br/>Our lovely Forerunner.<br/>His shame was our vict’ry,<br/>His anguish our joy.<br/>The children of judgement<br/>He brought into glory.<br/>The millions of God-men<br/>Forever rejoice.<br/>',NULL,67431,4);
INSERT INTO stanza VALUES('NS763','1','I tell you truly, by no means this generation shall<br/>pass away,<br/>until all these things take place. (x2) (Matt. 24:34)<br/>',NULL,67432,1);
INSERT INTO stanza VALUES('NS763','2','Though heaven and earth will pass away,<br/>My words shall by no means pass away. (x2) (Matt. 24:33)<br/>',NULL,67433,2);
INSERT INTO stanza VALUES('NS763','3','Go therefore, disciple all nations,<br/>disciple all nations,<br/>baptize into the name of the Father and Son<br/>and Holy Spirit,<br/>',NULL,67434,3);
INSERT INTO stanza VALUES('NS763','4','And behold, I’m with you;<br/>I’m with you<br/>all the days;<br/>And behold, I’m with you;<br/>I’m with you<br/>to the consummation of the age.<br/>',NULL,67435,4);
INSERT INTO stanza VALUES('NS764','1','Where I am, there You are.<br/>In the darkness, my Morning Star.<br/>When in sickness, You are my health.<br/>When I’m poor, Lord, You’re my wealth.<br/>',NULL,67436,1);
INSERT INTO stanza VALUES('NS764','chorus','Looking at You Lord, You’re all I need.<br/>As You flow life to me so free,<br/>Jesus fill me, with grace each day.<br/>How to go on, You are the way.<br/>',NULL,67437,2);
INSERT INTO stanza VALUES('NS764','2','When alone, You’re my song.<br/>In my weakness, Lord, You are strong.<br/>When there’s doubt then, as faith You come.<br/>Now I have hope, You’re the One.<br/>',NULL,67438,3);
INSERT INTO stanza VALUES('NS764','chorus','Looking at You Lord, You’re all I need.<br/>As You flow life to me so free,<br/>Jesus fill me, with grace each day.<br/>How to go on, You are the way.<br/>',NULL,67439,4);
INSERT INTO stanza VALUES('NS764','3','In the storms, You’re the calm.<br/>In my pain, Lord, You are the balm.<br/>In self-pity, as light You’ll shine,<br/>Filling me with love divine.<br/>',NULL,67440,5);
INSERT INTO stanza VALUES('NS764','chorus','Looking at You Lord, You’re all I need.<br/>As You flow life to me so free,<br/>Jesus fill me, with grace each day.<br/>How to go on, You are the way.<br/>',NULL,67441,6);
INSERT INTO stanza VALUES('NS764','4','Praising You, is my joy.<br/>You’re the pure One, without alloy,<br/>Showing me, Lord, Your wondrous love,<br/>When You came down, from above.<br/>',NULL,67442,7);
INSERT INTO stanza VALUES('NS764','chorus','Looking at You Lord, You’re all I need.<br/>As You flow life to me so free,<br/>Jesus fill me, with grace each day.<br/>How to go on, You are the way.<br/>',NULL,67443,8);
INSERT INTO stanza VALUES('NS764','5','Now in me, all in all,<br/>For this living, Your Name I’ll call.<br/>O Lord Jesus, for growth I’ll pray.<br/>By Your Spirit, that’s the way.<br/>',NULL,67444,9);
INSERT INTO stanza VALUES('NS764','chorus','Looking at You Lord, You’re all I need.<br/>As You flow life to me so free,<br/>Jesus fill me, with grace each day.<br/>How to go on, You are the way.<br/>',NULL,67445,10);
INSERT INTO stanza VALUES('NS765','chorus','Watch, be ready,<br/>We know not the day He comes,<br/>Are your vessels filled with oil?<br/>Are you faithful serving ones?<br/>Let’s go out, to meet Him,<br/>He’s the most precious One,<br/>Turn your heart toward Christ, the Bridegroom,<br/>Whom you love.<br/>',NULL,67446,1);
INSERT INTO stanza VALUES('NS765','1','Lord, I open wide to You,<br/>Lord, I’m ready to be filled,<br/>Lord, a virgin pure in heart I want to be,<br/>I’ll pay for extra oil willingly.<br/>',NULL,67447,2);
INSERT INTO stanza VALUES('NS765','2','Lord, I give my time to You,<br/>Lord, I’ll watch by loving You,<br/>Lord, Your living Word I want more to receive,<br/>Lord, find me washed and cleansed so thoroughly.<br/>',NULL,67448,3);
INSERT INTO stanza VALUES('NS765','3','Lord, a talent I’ve received,<br/>Lord, through my ability,<br/>Lord, I now begin to trade immediately,<br/>Lord, find me good and faithful serving Thee.<br/>',NULL,67449,4);
INSERT INTO stanza VALUES('NS765','4','Lord, You’ve met my every need,<br/>Lord, I’ll serve You as a priest,<br/>Lord, I’ll minister the Life that I’ve received,<br/>Lord, find me giving food so timely.<br/>',NULL,67450,5);
INSERT INTO stanza VALUES('NS766','1','Enoch and God, walked for three centuries<br/>And then God took him, and he was not,<br/>And Abraham, lingered in God’s presence<br/>As they were talking God showed His heart.<br/>',NULL,67451,1);
INSERT INTO stanza VALUES('NS766','chorus','Lord, I’m here<br/>Just spending time to get to know You;<br/>Just draw near,<br/>Reveal Your heart, show me Your purpose,<br/>Keep dispensing into me.<br/>',NULL,67452,2);
INSERT INTO stanza VALUES('NS766','2','Walking with God, we are in fellowship;<br/>Talking to Him, shows me His heart;<br/>Gazing at God, He’s infused into me;<br/>As I abide here, we both are one.<br/>',NULL,67453,3);
INSERT INTO stanza VALUES('NS766','chorus','Lord, I’m here<br/>Just spending time to get to know You;<br/>Just draw near,<br/>Reveal Your heart, show me Your purpose,<br/>Keep dispensing into me.<br/>',NULL,67454,4);
INSERT INTO stanza VALUES('NS766','3','Regular days, but there is God in them;<br/>Regular hours, spent talking with Him.<br/>Do not despise, days full of the small things;<br/>God’s being added to you, when you say:<br/>',NULL,67455,5);
INSERT INTO stanza VALUES('NS766','chorus','Lord, I’m here<br/>Just spending time to get to know You;<br/>Just draw near,<br/>Reveal Your heart, show me Your purpose,<br/>Keep dispensing into me.<br/>',NULL,67456,6);
INSERT INTO stanza VALUES('NS767','chorus','Be strong and take courage, and press on to the Lord;<br/>Be very courageous, and press on, press on, press on.<br/>',NULL,67457,1);
INSERT INTO stanza VALUES('NS767','1','For you will inherit this good land, which is Christ, (Col. 1:12)<br/>For God will be with you and will be all your life. (Col. 3:4)<br/>',NULL,67458,2);
INSERT INTO stanza VALUES('NS767','chorus','Be strong and take courage, and press on to the Lord;<br/>Be very courageous, and press on, press on, press on.<br/>',NULL,67459,3);
INSERT INTO stanza VALUES('NS767','2','My word shall not leave from your mouth day and night,<br/>But dwell in you richly as you live in its light. (Col. 3:16)<br/>',NULL,67460,4);
INSERT INTO stanza VALUES('NS767','chorus','Be strong and take courage, and press on to the Lord;<br/>Be very courageous, and press on, press on, press on.<br/>',NULL,67461,5);
INSERT INTO stanza VALUES('NS767','3','And be empowered in the might of His strength,<br/>Know Christ and enjoy Christ in His depth, height, breadth, and length.<br/>(Phil. 3:10; Eph. 3:18)<br/>',NULL,67462,6);
INSERT INTO stanza VALUES('NS767','chorus','Be strong and take courage, and press on to the Lord;<br/>Be very courageous, and press on, press on, press on.<br/>',NULL,67463,7);
INSERT INTO stanza VALUES('NS768','chorus','Steal me away, I want to be well-pleasing to You.<br/>Through all my time with You, would You fill me through and through?<br/>You’re coming as a thief, my house will be broken into, so<br/>while I still have today, make me precious to You.<br/>',NULL,67464,1);
INSERT INTO stanza VALUES('NS768','1','Lord, restore the years the locusts have eaten.<br/>You redeemed me from a life that is fleeting;<br/>A life of much activity, but no concern for Your deep need.<br/>May we find grace like Noah in Your eyes.<br/>',NULL,67465,2);
INSERT INTO stanza VALUES('NS768','2','We can choose, will we be foolish or prudent<br/>Vessels filled when we go forth to meet Him?<br/>We’ll be with our Bridegroom sweet, and we’ll enjoy the wedding feast.<br/>May we grasp every opportunity.<br/>',NULL,67466,3);
INSERT INTO stanza VALUES('NS768','3','When we rise, we must make time in the morning.<br/>Lord, You’ll hear, our voices singing and praising.<br/>Lord, grow in us day by day, make us stones, transform the clay;<br/>Constitute us the men of preciousness.<br/>',NULL,67467,4);
INSERT INTO stanza VALUES('NS768','4','We must not forsake assembling together<br/>As we see the day draw nearer and nearer.<br/>Thus together we’ll possess, the vast dimensions of this Christ.<br/>May we be those who hasten Your return.<br/>',NULL,67468,5);
INSERT INTO stanza VALUES('NS769','1','He bears the whole universe;<br/>He can bear my little heart;<br/>The image of the Invisible,<br/>Revealing all God’s heart.<br/>All things cohere, subsist in Him,<br/>The Holding Center, Keeper strong.<br/>The universe His worth proclaims:<br/>Christ as reality, its song.<br/>',NULL,67469,1);
INSERT INTO stanza VALUES('NS769','2','Through His Word, all things have life;<br/>Everything, of Him, to Him;<br/>And in the heavens now, He stands<br/>Lord of Lords, King of Kings.<br/>In Him we live, in Him we move;<br/>In Him we are, have life and breath.<br/>In wisdom great He metes the earth,<br/>Apportions each their hill and heath.<br/>',NULL,67470,2);
INSERT INTO stanza VALUES('NS769','3','This One and I—unified,<br/>Mingled and incorporate—<br/>He bears me in His mighty hand—<br/>On Him my hope is set.<br/>The universe in which I live<br/>Is sometimes turbulent with storm,<br/>But all I wish to see therein—<br/>His mighty, lovely, lordly form.<br/>',NULL,67471,3);
INSERT INTO stanza VALUES('NS770','1','Lord, we praise you for Your life in us!<br/>Divine, eternal, uncreated, indestructible.<br/>Have Your way in us that we may grow into maturity.<br/><br/>Day by day, Spirit’s moving and anointing.<br/>Amen! Saturate us,<br/>We don’t want to remain the same,<br/>Lord, You spread into our mind, emotion, will.<br/>Make Your home in all our hearts.<br/>',NULL,67472,1);
INSERT INTO stanza VALUES('NS770','chorus','We give ourselves to You,<br/>We give ourselves to You,<br/>Remind us where You are,<br/>Remind us where You are,<br/>You are all we need,<br/>You are all we need,<br/>The only One that’s real.<br/>',NULL,67473,2);
INSERT INTO stanza VALUES('NS770','2','As we’re living in this world today,<br/>Preserve our being, so it’s fully occupied with You,<br/>Fleeing other things,<br/>Growing in life with those who call on the Lord.<br/><br/>Day by day Through our repenting and confessing,<br/>Amen! Lord renew us.<br/>We don’t want to remain the same.<br/>Lord, do spread into our mind, emotion, will.<br/>Make Your home in all our hearts.<br/>',NULL,67474,3);
INSERT INTO stanza VALUES('NS770','chorus','We give ourselves to You,<br/>We give ourselves to You,<br/>Remind us where You are,<br/>Remind us where You are,<br/>You are all we need,<br/>You are all we need,<br/>The only One that’s real.<br/>',NULL,67475,4);
INSERT INTO stanza VALUES('NS771','1','Don’t you know? Don’t you know?<br/>Jesus Christ is in you.<br/>He is near, He is here—<br/>He is in you!<br/>He’s within, speak to Him,<br/>Pour out your love on Him.<br/>He is waiting for you to speak to Him...<br/>',NULL,67476,1);
INSERT INTO stanza VALUES('NS771','chorus','Tell Him you love Him! Oh, just love Him!<br/>He is this wonderful Person in you!<br/>Don’t forget, don’t forget,<br/>That you are not alone,<br/>And then through you, His life will be made known.<br/>',NULL,67477,2);
INSERT INTO stanza VALUES('NS771','2','Don’t forget, don’t forget,<br/>That the Lord is in you.<br/>He’s not far like the stars,<br/>No, He’s in you.<br/>If you fall, just recall:<br/>There’s a Person in you.<br/>Then with His strength you will rise up anew.<br/>',NULL,67478,3);
INSERT INTO stanza VALUES('NS771','chorus','Tell Him you love Him! Oh, just love Him!<br/>He is this wonderful Person in you!<br/>Don’t forget, don’t forget,<br/>That you are not alone,<br/>And then through you, His life will be made known.<br/>',NULL,67479,4);
INSERT INTO stanza VALUES('NS772','chorus','It is Jehovah’s lovingkindness<br/>That we are not consumed,<br/>We are not consumed,<br/>For His compassions do not fail;<br/>They are new every morning;<br/>Great is Your faithfulness.<br/>',NULL,67480,1);
INSERT INTO stanza VALUES('NS772','chorus','Satisfy us in the morning<br/>With Your lovingkindness<br/>That we may give a ringing shout<br/>And rejoice all our days.<br/>',NULL,67481,2);
INSERT INTO stanza VALUES('NS772','chorus','Satisfy us in the morning<br/>With Your lovingkindness<br/>That we may give a ringing shout<br/>And rejoice all our days.<br/>',NULL,67482,3);
INSERT INTO stanza VALUES('NS773','1','It is no longer I who live,<br/>But it is Christ who lives in me;<br/>No longer I, yet in me lives<br/>Christ the Preeminent.<br/>',NULL,67483,1);
INSERT INTO stanza VALUES('NS773','2','Christ makes His home now in our hearts—<br/>He makes His home in us through faith;<br/>Spread into all our inward parts,<br/>Christ the Preeminent.<br/>',NULL,67484,2);
INSERT INTO stanza VALUES('NS773','3','As always, even now, yes, now,<br/>Christ will be magnified in me;<br/>Through life or death I would express<br/>Christ the Preeminent.<br/>',NULL,67485,3);
INSERT INTO stanza VALUES('NS773','4','The hope of glory—Christ in us,<br/>Indwelling us our hope to be,<br/>To be our life, our love, our all—<br/>Christ the Preeminent.<br/>',NULL,67486,4);
INSERT INTO stanza VALUES('NS774','1','We have this ministry:<br/>To teach and propagate,<br/>To fight with Satan and contend,<br/>Build up, and cultivate.<br/>',NULL,67487,1);
INSERT INTO stanza VALUES('NS774','2','Empowered in God’s grace,<br/>Commit all things we’ve learned<br/>To faithful men, that they may then<br/>Impart the healthy word.<br/>',NULL,67488,2);
INSERT INTO stanza VALUES('NS774','3','We as good soldiers true<br/>Entangle not ourselves,<br/>That we may please the One who has<br/>Enlisted us to serve.<br/>',NULL,67489,3);
INSERT INTO stanza VALUES('NS774','4','Though all the race may run,<br/>But one receives the prize;<br/>That we’d receive the crown of life,<br/>Control we exercise.<br/>',NULL,67490,4);
INSERT INTO stanza VALUES('NS774','5','Some plant, some watering,<br/>As farmers, cultivate;<br/>Through patient labor we’ll partake<br/>And fruit abundant yield.<br/>',NULL,67491,5);
INSERT INTO stanza VALUES('NS774','6','As workmen unashamed,<br/>Present ourselves approved;<br/>Restore all men unto the truth;<br/>Cut straight the holy word.<br/>',NULL,67492,6);
INSERT INTO stanza VALUES('NS774','7','Teachers and soldiers we;<br/>Contenders, farmers too;<br/>In grace we’re cutting straight the truth;<br/>In many ways we serve.<br/>',NULL,67493,7);
INSERT INTO stanza VALUES('NS775','1','Truly I say to you,<br/>Everyone who sins<br/>Is a slave of sin,<br/>But you can be freed.<br/><br/>Things I don’t will, I do.<br/>Things I will, I don’t do.<br/>I need to be set free.<br/>Who can deliver me?<br/>',NULL,67494,1);
INSERT INTO stanza VALUES('NS775','chorus','The law of the Spirit of life<br/>Has freed me from the law of sin and of death.<br/>The Son has set you free,<br/>And you are free indeed.<br/>Stand fast in Christ and you are free.<br/>',NULL,67495,2);
INSERT INTO stanza VALUES('NS775','2','You shall know the truth,<br/>And the truth shall set you free.<br/>You have received Him,<br/>Been delivered from sin!<br/><br/>The freedom is in you—<br/>Christ the Jubilee.<br/>Never be entangled <br/>With a yoke of slavery!<br/>',NULL,67496,3);
INSERT INTO stanza VALUES('NS775','chorus','The law of the Spirit of life<br/>Has freed me from the law of sin and of death.<br/>The Son has set you free,<br/>And you are free indeed.<br/>Stand fast in Christ and you are free.<br/>',NULL,67497,4);
INSERT INTO stanza VALUES('NS776','chorus','God is spreading in my being!<br/>As the Spirit filling me!<br/>From my spirit to my soul<br/>To my body, I am wholly<br/>sanctified in Christ,<br/>preserved complete!<br/>',NULL,67498,1);
INSERT INTO stanza VALUES('NS776','1','And the God of peace Himself<br/>Sanctify you wholly,<br/>And the God of peace Himself<br/>Sanctify you wholly.<br/>',NULL,67499,2);
INSERT INTO stanza VALUES('NS776','2','May your spirit and your soul and body<br/>Be preserved complete, without blame,<br/>Be preserved complete and without blame<br/>At the coming of our Lord Jesus Christ.<br/>',NULL,67500,3);
INSERT INTO stanza VALUES('NS777','1','In Genesis we see, God’s desire being<br/>For man to eat the tree of life.<br/>After Adam was created, the first thing that God wanted<br/>Was for him to eat but to eat what?<br/>',NULL,67501,1);
INSERT INTO stanza VALUES('NS777','chorus','Eat God, eat the Lord, eat Him in the Holy Word.<br/>He’s the Lamb who reduced Himself, and the tree of life.<br/>Leave your concepts behind and God’s concept you will find:<br/>All He wants is for you to eat Him.<br/>',NULL,67502,2);
INSERT INTO stanza VALUES('NS777','2','In Exodus we see, God’s desire being<br/>For man to eat the Lamb.<br/>As a creature so small, He’s approachable to all;<br/>This Lamb is God Himself.<br/>',NULL,67503,3);
INSERT INTO stanza VALUES('NS777','chorus','Eat God, eat the Lord, eat Him in the Holy Word.<br/>He’s the Lamb who reduced Himself, and the tree of life.<br/>Leave your concepts behind and God’s concept you will find:<br/>All He wants is for you to eat Him.<br/>',NULL,67504,4);
INSERT INTO stanza VALUES('NS778','1','The high gospel’s been preached; the high truth’s been released.<br/>But we still sense a lack; is this all that God needs?<br/>This He longs for today: some who’d wholeheartedly<br/>Give the ground for Christ to live in them intrinsically.<br/>',NULL,67505,1);
INSERT INTO stanza VALUES('NS778','chorus','God is longing for His ultimate move,<br/>That He and we would be one eternally.<br/>“Lord, these days are the consummation of the age.<br/>Lord, in these days rekindle our love toward You.”<br/>',NULL,67506,2);
INSERT INTO stanza VALUES('NS778','2','As the Body of Christ, we would all let Him grow,<br/>From our spirit expand, from our heart overflow;<br/>Thus, we’ll build up the church and make ready the Bride;<br/>Thus, the kingdom life within us will be magnified.<br/>',NULL,67507,3);
INSERT INTO stanza VALUES('NS778','chorus','God is longing for His ultimate move,<br/>That He and we would be one eternally.<br/>“Lord, these days are the consummation of the age.<br/>Lord, in these days rekindle our love toward You.”<br/>',NULL,67508,4);
INSERT INTO stanza VALUES('NS778','3','Now the world stage is set and the Lord’s coming soon.<br/>He’ll be not first the Judge, but our lovely Bridegroom.<br/>As we follow the Lamb, He is mingled with us.<br/>When He sees we’ve been prepared, He’ll come to marry us.<br/>',NULL,67509,5);
INSERT INTO stanza VALUES('NS778','chorus','God is longing for His ultimate move,<br/>That He and we would be one eternally.<br/>“Lord, these days are the consummation of the age.<br/>Lord, in these days rekindle our love toward You.”<br/>',NULL,67510,6);
INSERT INTO stanza VALUES('NS778','4','Consummated, our God is the Spirit today.<br/>What He needs now in us is an unhindered way.<br/>By His Spirit transformed, matching Him, we would pray:<br/>“Dearest One! Oh, quickly come! Make haste! Do not delay!”<br/>',NULL,67511,7);
INSERT INTO stanza VALUES('NS778','chorus','God is longing for His ultimate move,<br/>That He and we would be one eternally.<br/>“Lord, these days are the consummation of the age.<br/>Lord, in these days rekindle our love toward You.”<br/>',NULL,67512,8);
INSERT INTO stanza VALUES('NS779','1','Lord, I love You! Draw me with Your beauty.<br/>When I wake each day, fully turn my heart to You.<br/>Lord, there’s nothing else that can compare to You.<br/>Lord, I won’t move on till we are one; that’s my plea.<br/>',NULL,67513,1);
INSERT INTO stanza VALUES('NS779','2','Lord, I open to Your working today;<br/>Saturate each part, Lord without reservation.<br/>Lord, I offer You my full coop’ration;<br/>Lord, that You alone possess my whole heart today.<br/>',NULL,67514,2);
INSERT INTO stanza VALUES('NS779','3','Lord, I do thank You for dying for me;<br/>Lord, Your precious blood has redeemed me from all dross;<br/>Lord, you bore my sins on that old rugged cross.<br/>Lord, You sacrificed Your whole life fully for me.<br/>',NULL,67515,3);
INSERT INTO stanza VALUES('NS779','4','Lord, I’ve been constrained by God’s love through You.<br/>Master, how can I ever turn away from You?<br/>Lord, I do love You; I give myself to You.<br/>Lord, I consecrate my whole life fully to You.<br/>',NULL,67516,4);
INSERT INTO stanza VALUES('NS780','chorus','Peace I leave with you;<br/>My peace I give to you;<br/>Not as the world gives do I give to you.<br/>Peace I leave with you;<br/>My peace I give to you;<br/>Not as the world gives do I give to you.<br/>',NULL,67517,1);
INSERT INTO stanza VALUES('NS780','chorus','Do not let your heart,<br/>Do not let your heart,<br/>Do not let your heart be troubled,<br/>Neither let it be afraid,<br/>Neither let it be afraid.<br/>Peace I leave with you, I give to you.<br/>',NULL,67518,2);
INSERT INTO stanza VALUES('NS781','1','There was once a time wherein just one man,<br/>Could come close to God to be His companion.<br/>‘Twas by the shed blood he could come boldly,<br/>Drawing nigh to God, to behold His glory!<br/>',NULL,67519,1);
INSERT INTO stanza VALUES('NS781','chorus','Face to face!He met with Him there!<br/>He beheld God’s form!What sweetness they shared!<br/>God and man spoke intimately.<br/>God could speak with that one man openly.<br/>',NULL,67520,2);
INSERT INTO stanza VALUES('NS781','2','God no longer dwells in His tent of old.<br/>The spirit of man has now become His home.<br/>When we turn our heart, unveiled is our face,<br/>Then we meet the Lord before the throne of grace!<br/>',NULL,67521,3);
INSERT INTO stanza VALUES('NS781','chorus','Face to face! Together we meet!<br/>We are transformed from glory to glory!<br/>Here we’re one, no longer apart.<br/>Here we see what is hidden in God’s heart.<br/>',NULL,67522,4);
INSERT INTO stanza VALUES('NS782','1','Every day there is much work to be done,<br/>We are entrusted with the work of the Lord!<br/>We need to do business until He comes,<br/>Bringing in more men and feeding them with His word.<br/>Yet each day before we start,<br/>He brings this word up in our hearts:<br/>',NULL,67523,1);
INSERT INTO stanza VALUES('NS782','chorus','First we need to rest, just to lay down,<br/>This is what God wants, before the work abounds.<br/>First enjoy the Lord! Just drink Him in.<br/>Once we’re filled with Him—let the work begin.<br/>',NULL,67524,2);
INSERT INTO stanza VALUES('NS782','2','He ordained our days to start in this way,<br/>We clearly see in the creation of man—<br/>The first day of man was the seventh day,<br/>To enjoy God’s presence, ere he worked on the land.<br/>In our time it is the same,<br/>This divine principle remains...<br/>',NULL,67525,3);
INSERT INTO stanza VALUES('NS782','chorus','First we need to rest, just to lay down,<br/>This is what God wants, before the work abounds.<br/>First enjoy the Lord! Just drink Him in.<br/>Once we’re filled with Him—let the work begin.<br/>',NULL,67526,4);
INSERT INTO stanza VALUES('NS782','3','So begin your day reclining on Him,<br/>Enjoying Him as the pleasant pasture land,<br/>Sing until He overflows from the brim,<br/>Flowing out from you to reach whoever’s at hand.<br/>If you first behold His face,<br/>Your labor will be done by grace!<br/>',NULL,67527,5);
INSERT INTO stanza VALUES('NS782','chorus','First we need to rest, just to lay down,<br/>This is what God wants, before the work abounds.<br/>First enjoy the Lord! Just drink Him in.<br/>Once we’re filled with Him—let the work begin.<br/>',NULL,67528,6);
INSERT INTO stanza VALUES('NS783','chorus','God as our Potter has sovereignly created us to be His vessels,<br/>His vessels, His containers, to contain Himself according to His predestination;<br/>God’s purpose in creating man was to make man His vessel,<br/>His earthenware container, to contain and be filled with Christ as life<br/>for the building up of the Body of Christ<br/>as God’s great corporate vessel for His expression.<br/>',NULL,67529,1);
INSERT INTO stanza VALUES('NS784','1','We need to see a spiritual vision of the throne,<br/>the throne of God<br/>as the center of God’s administration<br/>throughout the universe;<br/>We need to see a spiritual vision of the throne,<br/>the throne of God<br/>as the center of God’s administration<br/>throughout the universe.<br/>',NULL,67530,1);
INSERT INTO stanza VALUES('NS784','2','and realize that the sovereign God<br/>has the full capacity<br/>to carry out what He wants<br/>according to the desire of His heart<br/>and according to His eternal economy<br/>',NULL,67531,2);
INSERT INTO stanza VALUES('NS784','chorus','[BRIDGE]<br/>as He is ruling over everyone and everything,<br/>as He is ruling over everyone and everything,<br/>as He is ruling over everyone and everything,<br/>and everything.<br/>',NULL,67532,3);
INSERT INTO stanza VALUES('NS784','end-note','Part 1 and Part 2 can be sung together.<br/>',NULL,67533,4);
INSERT INTO stanza VALUES('NS785','1','God is seeking some today to turn the age,<br/>Some who’ve dispensational value gained;<br/>He is calling us to be His Nazarites.<br/>Oh, will you be one who fully pays the price?<br/>',NULL,67534,1);
INSERT INTO stanza VALUES('NS785','chorus','And they overcame him by the blood of the Lamb<br/>And by the word of their testimony;<br/>They loved not their soul life unto death;<br/>They did not love their soul life<br/>Unto death.<br/>',NULL,67535,2);
INSERT INTO stanza VALUES('NS785','2','Though the devil does his best to trouble us,<br/>In a world of darkness, sin, rebelliousness;<br/>Blent and built into one loaf, the Lord’s army<br/>Let us gather to defeat the enemy.<br/>',NULL,67536,3);
INSERT INTO stanza VALUES('NS785','3','Just like Daniel and his three companions were,<br/>Men of prayer who joined themselves unto God’s word,<br/>God needs us to pave the way for Him to move;<br/>Lord, our full cooperation we give You!<br/>',NULL,67537,4);
INSERT INTO stanza VALUES('NS785','4','Gain us Lord as overcomers in this age;<br/>This is what You need and what You seek today;<br/>With a thorough consecration and true heart,<br/>Yes! We choose from this dark world to stand apart!<br/>',NULL,67538,5);
INSERT INTO stanza VALUES('NS785','chorus','And we overcame him by the blood of the Lamb<br/>And by the word of our testimony;<br/>We loved not our soul life unto death;<br/>We did not love our soul life<br/>Unto death.<br/>',NULL,67539,6);
INSERT INTO stanza VALUES('NS786','chorus','[Intro]<br/>What is your Beloved<br/>More than some other beloved,<br/>Most beautiful among women?<br/>Tell us of Him.<br/>What is your Beloved<br/>More than some other beloved,<br/>Most beautiful among women?<br/>Tell us of Him.<br/>',NULL,67540,1);
INSERT INTO stanza VALUES('NS786','1','My Beloved’s dazzling<br/>And there’s no one quite like Him,<br/>Distinguished among ten thousand.<br/>That’s the One I have found.<br/><br/>His head is the finest gold;<br/>Yet of Him is still untold;<br/>His eyes are like the dove’s eyes,<br/>This is My Beloved.<br/>',NULL,67541,2);
INSERT INTO stanza VALUES('NS786','chorus','No one’s like Him;<br/>He is so dazzling!<br/>That’s the One I have found<br/>From the ten thousand.<br/>',NULL,67542,3);
INSERT INTO stanza VALUES('NS786','2','He has cheeks like a bed of spices,<br/>And His lips like pure lilies,<br/>His legs are pillars of marble,<br/>He’s the most desirable.<br/><br/>His appearance like Lebanon,<br/>As the cedars excellent.<br/>His mouth is sweetness itself,<br/>That’s my Beloved and friend.<br/>',NULL,67543,4);
INSERT INTO stanza VALUES('NS787','1','He set me apart from my mother’s womb.<br/>He prepared my heart to receive His word.<br/>He came to me in love as the Bridegroom.<br/>He spoke to me—His lovely voice I heard.<br/>Though I was far off in darkness,<br/>He caused me to turn by His kindness;<br/>A lost son of disobedience<br/>Was led to repentance<br/>By the riches of God’s kindness!<br/>',NULL,67544,1);
INSERT INTO stanza VALUES('NS787','chorus','God has shepherded me<br/>All my life to this very day.<br/>The Lord is my Shepherd.<br/>All my life I have lacked nothing.<br/>',NULL,67545,2);
INSERT INTO stanza VALUES('NS787','2','He preserved me and arranged my daily walk.<br/>He patiently works to transform my soul.<br/>He brought me to the church, the one true flock<br/>Here we enjoy Him and His name extol.<br/>Though there were times in the valleys,<br/>I did not fear for He was with me.<br/>He used every joy and distress<br/>To conform and to bless,<br/>Looking back now I can confess…<br/>',NULL,67546,3);
INSERT INTO stanza VALUES('NS787','chorus','God has shepherded me<br/>All my life to this very day.<br/>The Lord is my Shepherd.<br/>All my life I have lacked nothing.<br/>',NULL,67547,4);
INSERT INTO stanza VALUES('NS787','3','I onward run for I must finish my course,<br/>As long as He grants me more days to live.<br/>He supplies me with the grace to be my force.<br/>He’s always near, full of more life to give.<br/>There is not much time remaining.<br/>While I have breath He’s sustaining.<br/>As I follow Him and don’t stray,<br/>Then I know in that day<br/>By His mercy I will still say…<br/>',NULL,67548,5);
INSERT INTO stanza VALUES('NS787','chorus','God has shepherded me<br/>All my life to this very day.<br/>The Lord is my Shepherd.<br/>All my life I have lacked nothing.<br/>',NULL,67549,6);
INSERT INTO stanza VALUES('NS788','1','There may be days when I’m lost and afraid,<br/>And I can’t seem to find my own way;<br/>Weakened with doubts, looking for a way out.<br/>Help me turn to the spirit, call on Your name, and say,<br/>',NULL,67550,1);
INSERT INTO stanza VALUES('NS788','chorus','I love You, Lord.<br/>(You are in me just waiting for me to say)<br/>I love You, Lord.<br/>(You are Love, You are Light, You are the Way.)<br/>Just keep me, Lord.<br/>I’m Yours evermore.<br/>',NULL,67551,2);
INSERT INTO stanza VALUES('NS788','2','You are light in the darkest of night.<br/>In Your Word I have light for the way.<br/>You’re faithful and true. Give me eyes to see You,<br/>To see you in spirit, trust in Your name, and say,<br/>',NULL,67552,3);
INSERT INTO stanza VALUES('NS788','chorus','I love You, Lord.<br/>(You are in me just waiting for me to say)<br/>I love You, Lord.<br/>(You are Love, You are Light, You are the Way.)<br/>Just keep me, Lord.<br/>I’m Yours.<br/>',NULL,67553,4);
INSERT INTO stanza VALUES('NS788','chorus','[Bridge]<br/>In the darkness I see Your face,<br/>Having peace knowing You are the Way.<br/>Keep my heart ever turned to You<br/>To be walking in spirit, strengthened by Grace to say,<br/>',NULL,67554,5);
INSERT INTO stanza VALUES('NS788','chorus','I love You, Lord.<br/>(You are leading me, keeping my path straight.)<br/>I love You, Lord.<br/>(When I call on You I can trust Your name.)<br/>Just keep me, Lord.<br/>I’m Yours evermore.<br/>',NULL,67555,6);
INSERT INTO stanza VALUES('NS789','1','Long I’ve been on my own, far from my Father’s home,<br/>Living a destitute life of wandering.<br/>I’ve lived dissolutely, I am full of misery.<br/>All my inheritance I’ve been squandering.<br/>',NULL,67556,1);
INSERT INTO stanza VALUES('NS789','2','There have been many tears along with many fears<br/>Since I wandered away from my Father.<br/>I am a prodigal with a living abysmal,<br/>Since I wandered away from my Father.<br/>',NULL,67557,2);
INSERT INTO stanza VALUES('NS789','3','What am I doing here? Stuck in want, without cheer,<br/>I am wasting away from my Father.<br/>Back home all are well fed—everyone abounds in bread—<br/>From the wealth in the house of my Father.<br/>',NULL,67558,3);
INSERT INTO stanza VALUES('NS789','4','Though I went far abroad, sinned against man and God,<br/>I desire to return to my Father!<br/>I am now coming home, nevermore again to roam.<br/>I am coming back home to my Father!<br/>',NULL,67559,4);
INSERT INTO stanza VALUES('NS789','5','Still a long way off, I look up—to my surprise—<br/>There is my Father running to meet me!<br/>Then on my neck he falls, and despite all my shortfalls,<br/>He starts to kiss me affectionately.<br/>',NULL,67560,5);
INSERT INTO stanza VALUES('NS789','6','I regret all I’ve done; I’m an unworthy son,<br/>Yet my dear Father is full of mercy!<br/>The best robe He gives me… a ring… sandals for my feet;<br/>And He feeds me—I’m no longer hungry!<br/>',NULL,67561,6);
INSERT INTO stanza VALUES('NS789','7','Oh what joy to be here! Back with my Father dear!<br/>I am no longer far from my Father!<br/>Father, how I love You!And I know You love me too.<br/>Here in Your house I will dwell forever!<br/>',NULL,67562,7);
INSERT INTO stanza VALUES('NS790','1','’Tis so sweet to read my Bible,<br/>Word by word and day by day;<br/>As I read the Lord speaks to me!<br/>On His word I’ll ever stay.<br/>',NULL,67563,1);
INSERT INTO stanza VALUES('NS790','chorus','Word by word! Word by word!<br/>I would read my Bible.<br/>Oh how dear, Him to hear,<br/>As I read my Bible.<br/>',NULL,67564,2);
INSERT INTO stanza VALUES('NS790','2','There’s a feast spread in the Bible,<br/>For His word is man’s true food.<br/>How I long to eat more, for I,<br/>Have tasted the Lord is good.<br/>',NULL,67565,3);
INSERT INTO stanza VALUES('NS790','3','So much wealth is in the Bible,<br/>Mine its words for precious ore.<br/>In it I find all God’s riches,<br/>They become my treasure store!<br/>',NULL,67566,4);
INSERT INTO stanza VALUES('NS790','4','Words of love are in the Bible,<br/>Unveiling the Author’s heart.<br/>These words draw and woo His seekers,<br/>Making them His counterpart.<br/>',NULL,67567,5);
INSERT INTO stanza VALUES('NS790','5','Yet, most precious in the Bible,<br/>Is not wisdom, truth and grace.<br/>But behind its words is Jesus!<br/>I behold Him face to face.<br/>',NULL,67568,6);
INSERT INTO stanza VALUES('NS790','chorus','Face to face! Face to face!<br/>While I read my Bible.<br/>He is near, He is here,<br/>As I read my Bible.<br/>',NULL,67569,7);
INSERT INTO stanza VALUES('NS791','1','I’m a crazy lover of the Lord!<br/>Every day I love You more.<br/>Your beauty has attracted me.<br/>I’m longing for Your sweet embrace<br/>Just to see You face to face.<br/>I turn my heart a thousand times a day to say:<br/>',NULL,67570,1);
INSERT INTO stanza VALUES('NS791','chorus','I love You!<br/>Lord, I love You!<br/>Yes, it’s true,<br/>I’m in love with You!<br/>',NULL,67571,2);
INSERT INTO stanza VALUES('NS791','2','I’m done with all formalities.<br/>Lord, I simply want to be<br/>In spirit where You live in me.<br/>Everything I am, have, and can do<br/>Only comes from loving You.<br/>I turn my heart a thousand times a day to say:<br/>',NULL,67572,3);
INSERT INTO stanza VALUES('NS791','chorus','I love You!<br/>Lord, I love You!<br/>Yes, it’s true,<br/>I’m in love with You!<br/>',NULL,67573,4);
INSERT INTO stanza VALUES('NS791','chorus','[Bridge]<br/>Forget about perfection.<br/>Forget about correction.<br/>Forget about what you are or what you aren’t.<br/>(Forget about it!)<br/>The Lord is always seeking<br/>To spread throughout your being,<br/>To make His home in all your heart<br/>So turn your heart to Him and say:<br/>',NULL,67574,5);
INSERT INTO stanza VALUES('NS791','chorus','I love You!<br/>Lord, I love You!<br/>Yes, it’s true,<br/>I’m in love with You!<br/>(sing twice)<br/>',NULL,67575,6);
INSERT INTO stanza VALUES('NS791','chorus','I love You!<br/>',NULL,67576,7);
INSERT INTO stanza VALUES('NS792','1','The Lord desires to gain<br/>A people filled with Him as life,<br/>Being built up on earth, His Body and bride.<br/>Who is willing to give the ground for Him to move?<br/>',NULL,67577,1);
INSERT INTO stanza VALUES('NS792','2','Where does the Lord have a way?<br/>Who are the people He can use?<br/>What people on earth afford Him a way?<br/>We must turn to the Lord and ask for His mercy.<br/>',NULL,67578,2);
INSERT INTO stanza VALUES('NS792','3','Where does the Lord have a way?<br/>Who are the people He can use?<br/>What people on earth afford Him a way?<br/>We must turn to the Lord and ask for His mercy.<br/>',NULL,67579,3);
INSERT INTO stanza VALUES('NS793','1','In the womb of the morning, I will come to You, O Lord;<br/>I’ll be dew, so refreshing, as I eat You in Your Word.<br/>And my praise and my calling, fruit of lips, will strengthen You;<br/>Drinking you, living water, You, my Lord, are watered, too.<br/>',NULL,67580,1);
INSERT INTO stanza VALUES('NS793','chorus','Lift up Your head, ascended Christ, in victory!<br/>I’m a volunteer come unto You to eat!<br/>From the womb of the morning I’m reborn to be<br/>One who overcomes in You triumphantly!<br/>',NULL,67581,2);
INSERT INTO stanza VALUES('NS794','1','We need to be in our spirit<br/>so that we can be men on the earth,<br/>We need to be in our spirit<br/>so that we can be men on the earth<br/>with God’s heart, with God’s heart,<br/>',NULL,67582,1);
INSERT INTO stanza VALUES('NS794','2','Men to whom heaven can be opened<br/>to see the vision of God,<br/>Men to whom heaven can be opened<br/>to see the vision of God<br/>concerning the destiny of the world,<br/>concerning the destiny of the world.<br/>',NULL,67583,2);
INSERT INTO stanza VALUES('NS795','1','Jehovah bless you and keep you;<br/>Jehovah make His face shine upon you,<br/>Be gracious to you;<br/>Be gracious to you;<br/>',NULL,67584,1);
INSERT INTO stanza VALUES('NS795','chorus','Jehovah lift up His count’nance,<br/>Jehovah lift up His count’nance on you,<br/>And give you much peace,<br/>And give you much peace.<br/>',NULL,67585,2);
INSERT INTO stanza VALUES('NS795','2','The love of God,<br/>The grace of Christ,<br/>The fellowship of the Spirit,<br/>Be with you all,<br/>Be with you all!<br/>',NULL,67586,3);
INSERT INTO stanza VALUES('NS795','chorus','The love of God,<br/>The grace of Christ,<br/>The fellowship of the Spirit,<br/>Be with you all,<br/>Be with you all!<br/>The Triune God be with you all!<br/>',NULL,67587,4);
INSERT INTO stanza VALUES('NS796','1','In the morning He wakes me.<br/>He awakens my ear.<br/>He longs to sustain the weary,<br/>Thus, I rise Him to hear.<br/>',NULL,67588,1);
INSERT INTO stanza VALUES('NS796','chorus','Yet ere I speak to the weary,<br/>The Lord must first be heard,<br/>He fills me anew so I’m able to,<br/>Sustain them with a word.<br/>',NULL,67589,2);
INSERT INTO stanza VALUES('NS796','2','Open my ear this morning.<br/>I want to hear Your voice.<br/>From everything else I’m turning,<br/>You only are my choice.<br/>',NULL,67590,3);
INSERT INTO stanza VALUES('NS796','chorus','Lord Jesus, I long to be filled!<br/>Spring up from within me!<br/>That others could know Your life-giving flow,<br/>And no more be thirsty.<br/>',NULL,67591,4);
INSERT INTO stanza VALUES('NS796','3','Oh Lord, care for the weary,<br/>These sheep with no Shepherd.<br/>Dear Lord I pray You could use me,<br/>Make me a good steward.<br/>',NULL,67592,5);
INSERT INTO stanza VALUES('NS796','chorus','Lord, here I am! Fill me freshly!<br/>I long for Your supply,<br/>If I’m filled today, You will have a way,<br/>These ones to satisfy.<br/>',NULL,67593,6);
INSERT INTO stanza VALUES('NS796','chorus','This is the reason I’m living,<br/>To feed the weary ones.<br/>This is my true bliss.I would still do this,<br/>Until my Master comes.<br/>',NULL,67594,7);
INSERT INTO stanza VALUES('NS797','chorus','Send forth Your light and Your truth;<br/>They will lead me;<br/>They will bring me<br/>to Your holy mountain<br/>And to Your tabernacles.<br/>And I will go,<br/>Yes I will go,<br/>to the altar of God,<br/>To God my exceeding joy;<br/>And I will praise You with the harp,<br/>O God, my God.<br/>',NULL,67595,1);
INSERT INTO stanza VALUES('NS798','1','My outward state has left me defeated;<br/>With every trial yet further I fall.<br/>It seems as if there’s been no progress made.<br/>But in the midst of it all…<br/>',NULL,67596,1);
INSERT INTO stanza VALUES('NS798','chorus','“I choose to love my Lord,<br/>Regardless of my outward sight!<br/>I choose to love my Lord,<br/>With all my heart, with all my might!<br/>I love my Lord!”<br/>',NULL,67597,2);
INSERT INTO stanza VALUES('NS798','2','When I come face to face with temptations,<br/>It seems that I still haven’t yet learned.<br/>So powerless my strength is to resist.<br/>All I can do then is turn…<br/>',NULL,67598,3);
INSERT INTO stanza VALUES('NS798','3','But even then, the guilt comes to haunt me:<br/>My body’s full of weakness and sin.<br/>Yet His word says, “new heart” He’s given me.<br/>So I by faith say within…<br/>',NULL,67599,4);
INSERT INTO stanza VALUES('NS798','4','Although I’ve failed, I know He still loves me.<br/>He’s gaining me each step of the way.<br/>His heart of love towards me shall never change.<br/>Oh, how my heart burns to say…<br/>',NULL,67600,5);
INSERT INTO stanza VALUES('NS798','chorus','“I choose to love You, Lord,<br/>Regardless of my outward sight!<br/>I choose to love You, Lord,<br/>With all my heart, with all my might!<br/>I love You, Lord!”<br/>',NULL,67601,6);
INSERT INTO stanza VALUES('NS799','1','As we open to Christ, open to Christ<br/>And take Him as our total living,<br/>This gives Him the way, gives Him the way<br/>As our all-sufficient grace to<br/>',NULL,67602,1);
INSERT INTO stanza VALUES('NS799','chorus','Be what we cannot be,<br/>Do what we cannot do,<br/>Give what we cannot give<br/>for the church.<br/>',NULL,67603,2);
INSERT INTO stanza VALUES('NS799','2','As receivers of grace, we’re filled with Him<br/>And we’re made stewards of God’s grace.<br/>This grace is to me, but it is for you<br/>For us to build the Body together.<br/>',NULL,67604,3);
INSERT INTO stanza VALUES('NS799','chorus','No longer separate,<br/>Now we’re dependent;<br/>Corporately building<br/>the Body of Christ.<br/>',NULL,67605,4);
INSERT INTO stanza VALUES('NS800','1','In the darkness of the night,<br/>Sailing on a stormy ocean,<br/>With no hope or peace in sight,<br/>On a churning, gloomy sea.<br/>Amidst the wind and waves, what do I see?<br/>It’s a Man who walks above the waves to me.<br/>And He said,<br/>',NULL,67606,1);
INSERT INTO stanza VALUES('NS800','chorus','“It is I.<br/>It is I. Don’t be afraid.<br/>Let me in—<br/>To your boat, I’ll calm the waves.<br/>I can be in you<br/>A harbor, warm and safe.<br/>Just open up your heart.<br/>I am the way.”<br/>',NULL,67607,2);
INSERT INTO stanza VALUES('NS800','2','All the troubles in my life<br/>Make me feel like I’m surrounded,<br/>Countless problems, pain, and strife,<br/>Come to rob my soul of peace.<br/>I’m worn and weary fighting off the grief.<br/>Is there no one who my suffering can relieve?<br/>The Lord says,<br/>',NULL,67608,3);
INSERT INTO stanza VALUES('NS800','chorus','“It is I.<br/>It is I. Don’t be afraid.<br/>Let me in—<br/>To your boat, I’ll calm the waves.<br/>I can be in you<br/>A harbor, warm and safe.<br/>Just open up your heart.<br/>I am the way.”<br/>',NULL,67609,4);
INSERT INTO stanza VALUES('NS800','3','Jesus is the Son of God,<br/>Come as man, full of compassion.<br/>Crucified upon a cross,<br/>He bore all your sins away.<br/>His life subdues the power of the grave.<br/>Will you let Him soothe your aching heart today?<br/>Then He’ll say,<br/>',NULL,67610,5);
INSERT INTO stanza VALUES('NS800','chorus','“It is I.<br/>It is I. Don’t be afraid.<br/>Just believe,<br/>Call My name and you’ll be saved.”<br/>Oh Lord Jesus,<br/>You’re the One I need today.<br/>I let You in my heart,<br/>Come in to stay.<br/>',NULL,67611,6);
INSERT INTO stanza VALUES('NS801','1','We need to see our daily walk, living and work,<br/>Schooling and job must all be a part of God’s present hist’ry;<br/>We need to see our daily walk, living and work,<br/>Schooling and job must all be a part of God’s present hist’ry,<br/>In His marvellous, excellent move on the earth today!<br/>In Him! With Him! By Him! And for Him!<br/>We all need to write God’s today’s hist’ry!<br/>',NULL,67612,1);
INSERT INTO stanza VALUES('NS801','2','We need to be one with God in His history,<br/>Moving and energizing in His loving overcomers;<br/>We need to be one with God in His history,<br/>Moving and energizing in His loving overcomers;<br/>One with God in life, living, and all that we do today!<br/>In Him! With Him! By Him! And for Him!<br/>We need to be vital, living and active!<br/>',NULL,67613,2);
INSERT INTO stanza VALUES('NS802','40','Let us examine our ways and try them,<br/>And let us turn again to Jehovah.<br/>',NULL,67614,1);
INSERT INTO stanza VALUES('NS802','41','Let us lift up our heart with our hands (unto God)<br/>Unto God in the heavens.<br/>',NULL,67615,2);
INSERT INTO stanza VALUES('NS802','55','I called upon Your name, O Jehovah,<br/>(O Jehovah) From the lowest pit.<br/>',NULL,67616,3);
INSERT INTO stanza VALUES('NS802','56','You’ve heard my voice; don’t hide<br/>Your ear at my breathing, at my cry.<br/>',NULL,67617,4);
INSERT INTO stanza VALUES('NS802','57','You drew near in the day that I called upon You;<br/>(You said) You said, Do not fear.<br/>',NULL,67618,5);
INSERT INTO stanza VALUES('NS802','58','Lord, You have pleaded my soul’s case;<br/>(You said, Do not fear)<br/>You have redeemed my life.<br/>',NULL,67619,6);
INSERT INTO stanza VALUES('NS803','1','O Lord, You know I don’t like this.<br/>O Lord, does it have to be this way?<br/>I’m worn, but still longing for Your kiss.<br/>And deep in my heart I still love You,<br/>So keep me open anyway to Your<br/>',NULL,67620,1);
INSERT INTO stanza VALUES('NS803','chorus','Showers of blessing.<br/>Rain down, rain down.<br/>Showers of blessing.<br/>I’m open now to Your showers of blessing.<br/>Bless me now with Your showers of blessing.<br/>Bless me now.<br/>',NULL,67621,2);
INSERT INTO stanza VALUES('NS803','2','O Lord, my heart has been broken.<br/>So closed, yet full of so many things.<br/>O Lord, come heal me and empty me.<br/>I give You my heart; I’m wide open.<br/>Flow into my entire being with Your<br/>',NULL,67622,3);
INSERT INTO stanza VALUES('NS803','chorus','[Bridge]<br/>The greatest blessing is to hear Your speaking,<br/>Making You so real to me each day.<br/>I won’t let You go till the blessings overflow.<br/>Reach me in my deepest parts. Fill me today.<br/>Fill me with<br/>',NULL,67623,4);
INSERT INTO stanza VALUES('NS803','chorus','Showers of blessing.<br/>Rain down, rain down.<br/>Showers of blessing.<br/>I’m open now to Your showers of blessing.<br/>Bless me now with Your showers of blessing.<br/>Bless me now.<br/>',NULL,67624,5);
INSERT INTO stanza VALUES('NS803','chorus','Bless me now.<br/>Bless me now.<br/>Bless me now.<br/>Bless me now.<br/>Bless me now.<br/>',NULL,67625,6);
INSERT INTO stanza VALUES('NS804','1','I love the Lord, He is my strength,<br/>I love the Lord, Jesus, my drink;<br/>I love the Lord whatever others think,<br/>I love the Lord, He is my strength. (Psa. 18:1)<br/>I love the Lord because He hears,<br/>I love the Lord, I know He cares;<br/>I love the Lord even through many tears,<br/>I love the Lord, because He hears. (Psa. 119:167)<br/>',NULL,67626,1);
INSERT INTO stanza VALUES('NS804','2','I love, You Lord, I love Your words,<br/>Your words, the sweetest ever heard;<br/>To turn away from You would be absurd,<br/>I love You Lord, I love Your words. (Psa. 119:163)<br/>I love You, Lord, so very much,<br/>I love You, Lord, I love Your touch;<br/>All other loves, Your love will surely crush,<br/>I love You, Lord, so very much! (Psa. 119:167)<br/>',NULL,67627,2);
INSERT INTO stanza VALUES('NS805','1','Jesus, how we long for Thee!<br/>Come, Thou, be with us still.<br/>Thou, our Bridegroom and Lover,<br/>Only, this vessel can fill.<br/>Yes, Lord, Thou, Lord,<br/>Only, this vessel can fill.<br/>',NULL,67628,1);
INSERT INTO stanza VALUES('NS805','2','Take me, Best Love, O take me!<br/>Thy compassion now sway<br/>My heart, will, and emotion;<br/>Burn all the idols away.<br/>Burn, burn, burn, burn,<br/>Burn all the idols away.<br/>',NULL,67629,2);
INSERT INTO stanza VALUES('NS805','3','Guard me in Thine affection;<br/>Keep me simple and chaste.<br/>None beside Thee in heaven,<br/>None on earth long we to taste.<br/>Jesus only! None on earth long we to taste.<br/>',NULL,67630,3);
INSERT INTO stanza VALUES('NS805','4','Time takes moment by moment<br/>Our hearts closer each day<br/>To Thee; Lord, we beseech Thee:<br/>Quickly come, even today!<br/>Amen, Jesus, quickly come, even today!<br/>',NULL,67631,4);
INSERT INTO stanza VALUES('NS806','chorus','God’s purpose in dealing with those who love Him<br/>is that they may gain Him to the fullest extent,<br/>surpassing the loss of all that they have other than Him,<br/>surpassing the loss of all that they have other than Him,<br/>so that He might be expressed through them<br/>for the fulfillment of His purpose in creating man.<br/>',NULL,67632,1);
INSERT INTO stanza VALUES('NS806','chorus','God’s purpose in dealing with His holy people<br/>is that they would be emptied of everything<br/>and receive, receive only God as their gain,<br/>and receive, receive only God as their gain;<br/>the desire of God’s heart is that they would gain Him in full as life,<br/>as the life supply, and as everything,<br/>as life, as the life supply, and as everything to their being.<br/>',NULL,67633,2);
INSERT INTO stanza VALUES('NS807','1','God in Christ drew me—Sweet is the story:<br/>Though we were fallen, God sent His Son!<br/>Christ stooped to woo me, leaving His glory,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67634,1);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67635,2);
INSERT INTO stanza VALUES('NS807','2','Life of compassion, kind words and gestures,<br/>God’s love revealed in His human ways,<br/>Feasting with sinners, healing the lepers,<br/>How deep His pity, mercy and grace!<br/>',NULL,67636,3);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67637,4);
INSERT INTO stanza VALUES('NS807','3','Christ was uplifted, draws all men to Him:<br/>The cross of Christ—O fathomless love!<br/>By men afflicted, by God forsaken,<br/>There He redeemed us by His shed blood.<br/>',NULL,67638,5);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67639,6);
INSERT INTO stanza VALUES('NS807','4','All of death’s forces could not subdue Him;<br/>Seed of the Woman, Satan He trod,<br/>Broke all our bondage, raised us up with Him,<br/>Made us alive, brought us into God.<br/>',NULL,67640,7);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67641,8);
INSERT INTO stanza VALUES('NS807','5','This Man ascended—highest place given:<br/>Lord, Christ, and Leader, Savior of all!<br/>Beloved Master, King, and Redeemer,<br/>Highest name “Jesus!” gladly we call!<br/>',NULL,67642,9);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67643,10);
INSERT INTO stanza VALUES('NS807','6','This our confession, Christ is our Savior,<br/>Our God has raised Him on the third day,<br/>His love transforms us for His good pleasure,<br/>Builds us up into His dwelling place.<br/>',NULL,67644,11);
INSERT INTO stanza VALUES('NS807','chorus','God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love,”<br/>God in Christ drew me, God in Christ drew me,<br/>With “cords of man, and with bands of love.”<br/>',NULL,67645,12);
INSERT INTO stanza VALUES('NS808','chorus','Make me a channel of blessing to my family,<br/>Never a source of contention.<br/>Bless my father, mother, sisters, and my brothers<br/>And so many others through our family.<br/>',NULL,67646,1);
INSERT INTO stanza VALUES('NS808','chorus','Forgive; Don’t be so selfish;<br/>Consider one another;<br/>Enjoy the Lord;<br/>Pray with our family.<br/>',NULL,67647,2);
INSERT INTO stanza VALUES('NS809','1','Let earth in wonder see my consecration;<br/>All, for this generation is outpoured.<br/>Time swiftly flies; eternity is nearing;<br/>A new age dawns, with my appearing Lord.<br/>Time swiftly flies; eternity is nearing;<br/>A new age dawns, with my appearing Lord.<br/>',NULL,67648,1);
INSERT INTO stanza VALUES('NS809','2','O Seven Spirits, earnest I beseech Thee!<br/>O burning fire, set all my heart ablaze!<br/>Search all my being, from my self deliv’ring;<br/>O Morning Star, direct through all my days.<br/>Search all my being, from my self deliv’ring;<br/>O Morning Star, direct through all my days.<br/>',NULL,67649,2);
INSERT INTO stanza VALUES('NS809','3','Affix mine eyes, that I behold Thee only;<br/>Strengthen my spirit, with me ever stay;<br/>Lord, set my steps to walk Thy path, unswerving;<br/>Hold fast my hands, unceasingly to pray.<br/>Lord, set my steps to walk Thy path, unswerving;<br/>Hold fast my hands, unceasingly to pray.<br/>',NULL,67650,3);
INSERT INTO stanza VALUES('NS810','1','Whether or not God now has a way depends on us today,<br/>Whether or not we’ll be absolute, trading for Him right away.<br/>“In a few things” serve faithfully, our “one talent” not burying,<br/>Ultimate move of God partaking, for Him to turn this age.<br/>',NULL,67651,1);
INSERT INTO stanza VALUES('NS810','chorus','We give all, learn how to perfect, vital groups to form;<br/>As all serve, the Body we build, man-child to bring forth;<br/>This ultimate commission bear, ushering back the Lord!<br/>',NULL,67652,2);
INSERT INTO stanza VALUES('NS811','1','Oh, what a glorious day!<br/>God sent His Christ, the “true light,”<br/>Coming to men in His grace,<br/>Scattering night, giving sight,<br/>Shined, while in darkness I strayed,<br/>And, as “great light,” drew me nigh,<br/>Cleansed and forgave when I prayed;<br/>Entered me, filled me with life!<br/>',NULL,67653,1);
INSERT INTO stanza VALUES('NS811','chorus','Shining in me! Shining in me!<br/>Oh, rays of light that rise in me!<br/>Scatters my darkness that I may see,<br/>Jesus my Savior, shining in me!<br/>',NULL,67654,2);
INSERT INTO stanza VALUES('NS811','2','His Word enlightens my ways;<br/>His Word the Spirit imparts;<br/>Here, as we meet face to face,<br/>Glories of Christ fill my heart!<br/>His words are spirit and life;<br/>Fill me with radiance divine!<br/>Bright Morning Star here I find;<br/>Rising in this heart of mine!<br/>',NULL,67655,3);
INSERT INTO stanza VALUES('NS811','chorus','Shining in me! Shining in me!<br/>Oh, rays of light that rise in me!<br/>Scatters my darkness that I may see,<br/>Jesus my Savior, shining in me!<br/>',NULL,67656,4);
INSERT INTO stanza VALUES('NS811','3','The Triune God in me shines,<br/>Increase of glory bestows;<br/>His life and mine intertwine,<br/>Till in His image I glow!<br/>With all the saints in His light,<br/>Ruled by His sweet flow of life<br/>Till, in us no trace of night,<br/>We as that City shine bright!<br/>',NULL,67657,5);
INSERT INTO stanza VALUES('NS811','chorus','Shining in me! Shining in me!<br/>Oh, rays of light that rise in me!<br/>Scatters my darkness that I may see,<br/>Jesus my Savior, shining in me!<br/>',NULL,67658,6);
INSERT INTO stanza VALUES('NS812','1','Time to get up, but you want to sleep;<br/>Test is tougher than you thought it would be.<br/>Bus runs early when you’re running late;<br/>Feels like there’s too much on your plate.<br/>But you can<br/>',NULL,67659,1);
INSERT INTO stanza VALUES('NS812','chorus','Call on Jesus! (Call on Jesus!)<br/>O Lord Jesus! (O Lord Jesus!)<br/>Don’t say, “Oh no!”<br/>Call, “O Lord!”<br/>',NULL,67660,2);
INSERT INTO stanza VALUES('NS812','2','Homework to do, and essays to write;<br/>Seems like every little thing is a fight.<br/>Car’s not starting and the outlook’s bleak;<br/>Don’t know how you’ll get through the week.<br/>But you can<br/>',NULL,67661,3);
INSERT INTO stanza VALUES('NS812','chorus','Call on Jesus! (Call on Jesus!)<br/>O Lord Jesus! (O Lord Jesus!)<br/>Don’t say, “Oh no!”<br/>Call, “O Lord!”<br/>',NULL,67662,4);
INSERT INTO stanza VALUES('NS812','chorus','Bridge (after Chorus 2):<br/>Any situation<br/>Can turn out to your salvation<br/>As long as you’re exclaiming<br/>A life-giving exclamation! (O Lord Jesus!)<br/>',NULL,67663,5);
INSERT INTO stanza VALUES('NS812','3','Call on Him softly, call right out loud;<br/>Call alone, or you can call with a crowd.<br/>Call His name and make His riches yours;<br/>Don’t confuse “Oh no!” and “O Lord!”<br/>You’ve got to<br/>',NULL,67664,6);
INSERT INTO stanza VALUES('NS812','chorus','Call on Jesus! (Call on Jesus!)<br/>O Lord Jesus! (O Lord Jesus!)<br/>Don’t say, “Oh no!”<br/>Call, “O Lord!”<br/>',NULL,67665,7);
INSERT INTO stanza VALUES('NS813','1','It’s just another ordinary day.<br/>But I don’t want to let it slip away.<br/>Though nothing much is happening,<br/>I turn unto the Lord again<br/>To gain more God today.<br/>',NULL,67666,1);
INSERT INTO stanza VALUES('NS813','chorus','Oh, so many ordinary<br/>days and ways for Him to get inside<br/>of me!<br/>',NULL,67667,2);
INSERT INTO stanza VALUES('NS813','2','It’s just another ordinary day.<br/>But I can turn my heart and see His face.<br/>In little things the Lord can be<br/>Dispensing life divine in me<br/>To fill me up today.<br/>',NULL,67668,3);
INSERT INTO stanza VALUES('NS813','chorus','Oh, so many ordinary<br/>days and ways for Him to get inside<br/>of me!<br/>',NULL,67669,4);
INSERT INTO stanza VALUES('NS813','3','Don’t have to wait until the perfect day.<br/>Life doesn’t have to fall apart to pray.<br/>Make every moment count with Him<br/>By taking Christ as life within<br/>To gain more God today.<br/>',NULL,67670,5);
INSERT INTO stanza VALUES('NS813','chorus','Oh, so many ordinary<br/>days and ways for Him to get inside<br/>of me!<br/>',NULL,67671,6);
INSERT INTO stanza VALUES('NS813','chorus','I’m enjoying the Lord in the<br/>morning and all through the day.<br/>When it’s late in the night as I<br/>turn out the light I can pray,<br/>For in big things and small things,<br/>In any and all things are ways<br/>To gain more God today.<br/>',NULL,67672,7);
INSERT INTO stanza VALUES('NS813','chorus','Oh, so many ordinary<br/>days and ways for Him to get inside<br/>of me!<br/>',NULL,67673,8);
INSERT INTO stanza VALUES('NS814','1','These are the days of salvation:<br/>Our past has been washed by His blood.<br/>And these are the days of redemption for you:<br/>Sinners become sons of God!<br/>And though you may feel you’re unworthy,<br/>Still Jesus has called you by name.<br/>Now we will proclaim to all nations ’round us:<br/>“Repent and believe in the Lord!”<br/>',NULL,67674,1);
INSERT INTO stanza VALUES('NS814','chorus','Behold, He comes: Christ our risen Lord!<br/>Let the trumpets ring: Hosannas to the King!<br/>Lift your voice! It’s the year of Jubilee!<br/>In the name of Jesus Christ salvation comes!<br/>',NULL,67675,2);
INSERT INTO stanza VALUES('NS814','2','These are the days of rejoicing:<br/>Lift up your praise to our King!<br/>And these are the days of pressing forward:<br/>As brothers and sisters we sing.<br/>And these are the days of Your kingdom:<br/>We stand and declare to the world<br/>That we are forever one in spirit<br/>Declaring the name of the Lord!<br/>',NULL,67676,3);
INSERT INTO stanza VALUES('NS814','chorus','Behold, He comes: Christ our risen Lord!<br/>Let the trumpets ring: Hosannas to the King!<br/>Lift your voice! It’s the year of Jubilee!<br/>In the name of Jesus Christ salvation comes!<br/>',NULL,67677,4);
INSERT INTO stanza VALUES('NS815','1','Oh, sunshine I find in my Savior!<br/>His rays now illuminate me!<br/>Effulgence that overcomes darkness<br/>Releases and satisfies me.<br/>Thy beaming and Thy beauty<br/>Enlighten my inner sight.<br/>The entrance of Thy word gives light,<br/>And floods me with radiance bright!<br/>',NULL,67678,1);
INSERT INTO stanza VALUES('NS815','2','As day after day is unfolding,<br/>And hours and moments pass by,<br/>Keep granting Thy fresh visitation,<br/>Thy countenance, each time I rise.<br/>Thy goodness and Thy glory<br/>Infuse me, time after time,<br/>Thy rich supply strengthening me,<br/>Thy Spirit to mingle with mine.<br/>',NULL,67679,2);
INSERT INTO stanza VALUES('NS815','3','Thou art the true light, O Lord Jesus;<br/>In Thee all my steps are so clear;<br/>With Thee I’m in fellowship’s sweetness;<br/>Thy sin-cleansing blood brings Thee near.<br/>Thy presence with Thy promise,<br/>A great lamp, leadeth me on!<br/>When my dark heart Thou entered in,<br/>Thy light changed my sighing to song!<br/>',NULL,67680,3);
INSERT INTO stanza VALUES('NS815','4','Eternal Light, brightness unchanging,<br/>Thou reachest me, scatt’ring all gloom;<br/>With Thee is the fountain of life, Lord;<br/>In Thy light, life in me doth bloom.<br/>Thy wonders and Thy workings<br/>Have touched me by Thy word’s light!<br/>My God who said, “Let there be light!”<br/>Is living and speaking inside!<br/>',NULL,67681,4);
INSERT INTO stanza VALUES('NS815','5','From darkness to light, Lord Thou brought me;<br/>Fresh mercies descend from above;<br/>With saints in Thy kingdom rejoicing,<br/>Announcing Thy life and Thy love!<br/>Thy vict’ry and Thy virtues,<br/>Exhibit light to all men,<br/>In newness, through Thy City shine,<br/>Bright, glorious Jerusalem!<br/>',NULL,67682,5);
INSERT INTO stanza VALUES('NS816','1','Together, Lord, our voice we raise<br/>To overcome, unto Your praise.<br/>Your Kingdom come, Your will be done<br/>On earth in us, as at the throne.<br/>',NULL,67683,1);
INSERT INTO stanza VALUES('NS816','chorus','Authority and reigning stand<br/>For executing God’s command;<br/>’Tis ours to pray, God’s burden own,<br/>Till answers pour out from the throne.<br/>',NULL,67684,2);
INSERT INTO stanza VALUES('NS816','2','Our God’s administration needs<br/>Our fighting prayer to intercede.<br/>We seek God’s heart and stand in death,<br/>Allowing Christ to be expressed.<br/>',NULL,67685,3);
INSERT INTO stanza VALUES('NS816','chorus','Pass through the cross in prayer to God<br/>Becoming precious to the Lord;<br/>By life and light we’re energized,<br/>And weighty prayer is exercised.<br/>',NULL,67686,4);
INSERT INTO stanza VALUES('NS816','3','At every time renewed and fresh,<br/>In resurrection we possess<br/>And claim ascension’s heavenly sphere,<br/>Position, nature, atmosphere.<br/>',NULL,67687,5);
INSERT INTO stanza VALUES('NS816','chorus','Our prayers will judge and end this age<br/>As we the Kingdom’s warfare wage.<br/>Such prayers are bowls with Christ therein,<br/>Added to bring God’s Kingdom in.<br/>',NULL,67688,6);
INSERT INTO stanza VALUES('NS816','4','The Devil will be cast to earth<br/>As overcomers come to birth,<br/>Before the throne a loud voice heard,<br/>“Rejoice, O heavens! Woe to earth!”<br/>',NULL,67689,7);
INSERT INTO stanza VALUES('NS816','chorus','“For now is come salvation, power,<br/>God’s Kingdom ’stablished in this hour.”<br/>With Satan driven from the throne,<br/>Authority of Christ’s made known.<br/>',NULL,67690,8);
INSERT INTO stanza VALUES('NS816','5','O Lord, our corporate prayer we raise<br/>To overcome, to end this age.<br/>Your Kingdom come, Your will be done<br/>On earth in us, as at the throne.<br/>',NULL,67691,9);
INSERT INTO stanza VALUES('NS816','chorus','Authority and reigning stand<br/>For executing God’s command;<br/>’Tis ours to pray, God’s burden own,<br/>Till answers pour out from the throne.<br/>',NULL,67692,10);
INSERT INTO stanza VALUES('NS817','1','The Lord gave gifts to the churches,<br/>Precious saints who love the Lord.<br/>First apostles and prophets,<br/>Speaking forth Christ as the word!<br/>Then He gave some gifts as evangelists,<br/>Who proclaim the gospel of Christ!<br/>There are shepherd-teachers, feeding the saints.<br/>But Lord, who am I?<br/>',NULL,67693,1);
INSERT INTO stanza VALUES('NS817','chorus','Lord, I’m ready and willing to be perfected by You,<br/>Through the saints all around me, to build Your Body too!<br/>',NULL,67694,2);
INSERT INTO stanza VALUES('NS817','2','Lord, I feel I’m unable to do what others can do.<br/>As I look all around me, they all seem more useful to You.<br/>But I see, dear Lord, I‘m here for Your need,<br/>To build up Your church today!<br/>And You gave these gifts that I may be trained,<br/>Lord, perfect me, I pray!<br/>',NULL,67695,3);
INSERT INTO stanza VALUES('NS817','chorus','Lord, I’m ready and willing to be perfected by You,<br/>Through the saints all around me, to build Your Body too!<br/>',NULL,67696,4);
INSERT INTO stanza VALUES('NS817','3','In the church I’m perfected by the saints with the life supply.<br/>I am growing and building, as I learn to minister Christ!<br/>“Till we all arrive,” yes, this is our goal!<br/>Every member builds today!<br/>Lord, I give myself, Your Body to build.<br/>Lord, for this now I pray!<br/>',NULL,67697,5);
INSERT INTO stanza VALUES('NS817','chorus','Lord, I’m ready and willing to be perfected by You,<br/>Through the saints all around me, to build Your Body too!<br/>',NULL,67698,6);
INSERT INTO stanza VALUES('NS818','1','As the days go by, and months turn to years,<br/>So much time I’ve lost, a slave to my fears.<br/>Jesus! Dear Lord, to You I would pray;<br/>When the morning comes, let me not waste this day.<br/>',NULL,67699,1);
INSERT INTO stanza VALUES('NS818','2','When I walk with You, my spirit is bright,<br/>And I’m covered in Your radiant light.<br/>Remind me Lord, just to look on Your face,<br/>If I turn away, bring me back to Your grace.<br/>',NULL,67700,2);
INSERT INTO stanza VALUES('NS818','3','While I’m waiting for the sun in my sky,<br/>I will call on You, to be my supply.<br/>Jesus! Dear Lord, though life takes its toll,<br/>I just ask of You, be forever my goal.<br/>',NULL,67701,3);
INSERT INTO stanza VALUES('NS819','1','Dearest Lord, I have heard of Your soon return,<br/>To silently come as a thief to steal away<br/>Vessels who have become precious in Your eyes.<br/>For them, You would hasten Your coming day.<br/>',NULL,67702,1);
INSERT INTO stanza VALUES('NS819','chorus','So make me to be precious<br/>And valuable to You,<br/>To be a man of preciousness,<br/>E’en preciousness itself.<br/>For this, O Lord, I pray:<br/>Your riches I would gain!<br/>Make me precious, Lord, more today!<br/>',NULL,67703,2);
INSERT INTO stanza VALUES('NS819','2','As a virgin have I been betrothed to You;<br/>How can I still choose to be tainted by this world?<br/>Purchased with precious blood, I belong to You.<br/>No longer my own, I am fully Yours.<br/>',NULL,67704,3);
INSERT INTO stanza VALUES('NS819','chorus','So make me to be precious<br/>And lovely in Your eyes,<br/>To be a virgin chaste and pure,<br/>By Spirit beautified.<br/>Out of my love, I choose<br/>To keep myself for You,<br/>My Beloved, dear Bridegroom.<br/>',NULL,67705,4);
INSERT INTO stanza VALUES('NS819','3','These last days, there is much You desire to do,<br/>But first You need some faithful ones to intercede.<br/>Just to those who have ceased seeking their own things<br/>You would nothing hide but would freely speak.<br/>',NULL,67706,5);
INSERT INTO stanza VALUES('NS819','chorus','So make me to be precious<br/>And intimate with You,<br/>To be Your close companion, Lord,<br/>Your interests, all I view.<br/>Lord, as I’m lingering,<br/>Speak face to face with me.<br/>Dearest Lord, I am listening.<br/>',NULL,67707,6);
INSERT INTO stanza VALUES('NS819','4','As this age darker grows, still the cry sounds out:<br/>“Redeem the time and pay the price to buy the oil.”<br/>No more days can I waste if I want to hear<br/>The call, “Enter into your Master’s joy.”<br/>',NULL,67708,7);
INSERT INTO stanza VALUES('NS819','chorus','So make me to be precious<br/>And one You’d steal away,<br/>By loving Your appearing,<br/>Expecting You each day.<br/>There’s no more time to waste!<br/>Your coming, I await!<br/>Dearest Jesus, oh, come! Make haste!<br/>',NULL,67709,8);
INSERT INTO stanza VALUES('NS820','1','What will turn our sorrows to joy?<br/>Abounding thanks, unceasing praise!<br/>Anxiety succumbs to peace<br/>By prayers with thanks that never cease.<br/>',NULL,67710,1);
INSERT INTO stanza VALUES('NS820','chorus','O thank You, Jesus—<br/>Your care, Your love unchanging.<br/>In everything, we can praise and sing;<br/>No more complaining,<br/>Our joy maintaining through the<br/>One who supplies all our needs!<br/>',NULL,67711,2);
INSERT INTO stanza VALUES('NS820','2','What’s the will of God for our days?<br/>Always rejoice, at all times pray;<br/>In everything, our thanksgiving<br/>To God for bountiful blessings!<br/>',NULL,67712,3);
INSERT INTO stanza VALUES('NS820','chorus','O thank You, Jesus—<br/>Your care, Your love unchanging.<br/>In everything, we can praise and sing;<br/>No more complaining,<br/>Our joy maintaining through the<br/>One who supplies all our needs!<br/>',NULL,67713,4);
INSERT INTO stanza VALUES('NS820','3','Turn away, give thanks, yes! Give thanks!<br/>Never obey what feelings say<br/>And as we turn, we’ll be released,<br/>For thanking God has set us free!<br/>',NULL,67714,5);
INSERT INTO stanza VALUES('NS820','chorus','O thank You, Jesus—<br/>Your care, Your love unchanging.<br/>In everything, we can praise and sing;<br/>No more complaining,<br/>Our joy maintaining through the<br/>One who supplies all our needs!<br/>',NULL,67715,6);
INSERT INTO stanza VALUES('NS821','chorus','Do not let me forget You,<br/>O Jehovah, O Jehovah.<br/>Do not let me forsake Your<br/>Holy mountain, holy mountain.<br/>',NULL,67716,1);
INSERT INTO stanza VALUES('NS821','chorus','May my right hand forget its skill,<br/>If I do not remember, Your church, Lord.<br/>May my tongue stay mute,<br/>If I do not prefer Your church,<br/>Above my chief joy.<br/>',NULL,67717,2);
INSERT INTO stanza VALUES('NS821','end-note','(Repeat)<br/>',NULL,67718,3);
INSERT INTO stanza VALUES('NS821','chorus','Above my chief joy.<br/>',NULL,67719,4);
INSERT INTO stanza VALUES('NS822','chorus','Christ loved the church, and gave Himself up for her,<br/>He gave His perfect life up for her;<br/>Christ loved the church, and gave Himself up for her<br/>That He might sanctify her,<br/>Cleansing her by the washing of the water in the Word.<br/>',NULL,67720,1);
INSERT INTO stanza VALUES('NS822','end-note','(repeat)<br/>',NULL,67721,2);
INSERT INTO stanza VALUES('NS822','chorus','Not having spot or wrinkle—<br/>Or any such things,<br/>That she might be holy and without blemish,<br/>That He might present the church to Himself<br/>Glorious, Christ and the church,<br/>Glorious, Christ and the church.<br/>',NULL,67722,3);
INSERT INTO stanza VALUES('NS823','1','Job was upright and he was perfect in the eyes of man,<br/>But he suffered loss and affliction according to God’s plan.<br/>Job thought that this was unfair, so he and God had a chat.<br/>What was hidden deep in God’s heart, and why would God let him go through that?<br/>',NULL,67723,1);
INSERT INTO stanza VALUES('NS823','2','The mystery hidden in God’s heart is God’s eternal economy.<br/>His heart’s desire’s to dispense Himself into all of His chosen people<br/>To be our life and nature that we might be the same as He is,<br/>His duplication, an organism, the Body for God’s fullness—His expression.<br/>',NULL,67724,2);
INSERT INTO stanza VALUES('NS823','3','See God has a purpose in bringing His loved ones through suffering;<br/>His goal is that we’d be emptied and our heart would be wide open to gain Him.<br/>So when you’re suffering just seek God to gain in you what He’s after,<br/>Then the life of Christ comes in.<br/>',NULL,67725,3);
INSERT INTO stanza VALUES('NS824','1','For God so loved the world that He,<br/>He gave His only begotten Son,<br/>That everyone who believes into<br/>Him would not perish, but would<br/>have eternal life.<br/>',NULL,67726,1);
INSERT INTO stanza VALUES('NS825','chorus','Drop by drop<br/>The Lord will get inside of you;<br/>Drop by drop<br/>In emotion, mind, and will.<br/>Drop by drop<br/>The vessel that the Lord has made<br/>He will gladly fill.<br/>',NULL,67727,1);
INSERT INTO stanza VALUES('NS825','chorus','There is oil in your lamp,<br/>But there’s the vessel too;<br/>Is it filled with Christ<br/>Or just filled with you?<br/>',NULL,67728,2);
INSERT INTO stanza VALUES('NS826','1','What a day when Christ reached me<br/>And freely gave to me His Spirit!<br/>What an hour and moment sweet<br/>When Christ saved me—not by my merit!<br/>Shed His blood upon the cross,<br/>Died to save the weak and lost;<br/>This I saw and I believed,<br/>That Jesus died and rose for me!<br/>',NULL,67729,1);
INSERT INTO stanza VALUES('NS826','2','Who could change a soul like mine?<br/>The life I lived—God was so distant;<br/>He arranged the day and time—<br/>Salvation came, and in an instant!<br/>Touched my sight; His light came in;<br/>Words of light shined on my sins!<br/>What a change my God has done!<br/>I’m one with Christ, the risen Son!<br/>',NULL,67730,2);
INSERT INTO stanza VALUES('NS826','3','Now I’m free—yes, free in Christ—<br/>For all my chains my God has broken!<br/>From that hold of sin and death,<br/>My God has freed! For He has spoken:<br/>“If the Son has set you free,<br/>You are free, yes, free indeed!”<br/>On the cross, Christ died for me<br/>And bore my sins upon the tree!<br/>',NULL,67731,3);
INSERT INTO stanza VALUES('NS826','4','Now I rest from all my strife,<br/>For all my works could never save me!<br/>I depend on Christ my life,<br/>My Strength, my Hope, my Rock, my Safety!<br/>Not of works—’tis all by grace!<br/>Rest in Him—my Dwelling Place!<br/>What supply my Savior gives,<br/>“Because He lives, I also live!”<br/>',NULL,67732,4);
INSERT INTO stanza VALUES('NS826','5','Day by day, I now receive<br/>Abundant grace, and without measure;<br/>When I call His precious Name,<br/>He fills my heart with streams of pleasure!<br/>Call His Name and take God in!<br/>Let Him fill you to the brim!<br/>Let His Spirit fill your soul,<br/>Till with His joy you overflow!<br/>',NULL,67733,5);
INSERT INTO stanza VALUES('NS827','1','Cross over to grace and leave the law,<br/>Cross over to grace and leave the law,<br/>Cross over to grace and leave the law,<br/>Open up, enjoy and call;<br/>God of glory appear to me!<br/>Cross over to grace!<br/>',NULL,67734,1);
INSERT INTO stanza VALUES('NS827','2','Cross over to the new and leave the old,<br/>Cross over to the new and leave the old,<br/>Cross over to the new and leave the old,<br/>God imparts life and God we know;<br/>God of glory appear to me!<br/>Cross over to the new!<br/>',NULL,67735,2);
INSERT INTO stanza VALUES('NS827','3','Cross over to the church, leave religion behind,<br/>Cross over to the church, leave religion behind,<br/>Cross over to the church, leave religion behind,<br/>Be renewed in the spirit of your mind;<br/>God of glory appear to me!<br/>Cross over to the church!<br/>',NULL,67736,3);
INSERT INTO stanza VALUES('NS827','4','Cross over to the truth, leave vanity alone,<br/>Cross over to the truth, leave vanity alone,<br/>Cross over to the truth, leave vanity alone,<br/>When Christ appears all the rituals are gone!<br/>God of glory appear to me!<br/>Cross over to the truth!<br/>',NULL,67737,4);
INSERT INTO stanza VALUES('NS827','5','Cross over to the spirit, and deny the soul,<br/>Cross over to the spirit, and deny the soul,<br/>Cross over to the spirit, and deny the soul,<br/>Holy of Holies becomes your home.<br/>God of glory appear to me!<br/>Cross over to the spirit!<br/>',NULL,67738,5);
INSERT INTO stanza VALUES('NS827','6','Cross over to life, leave death in the grave,<br/>Cross over to life, leave death in the grave,<br/>Cross over to life, leave death in the grave,<br/>Be transfused, infused and saved!<br/>God of glory appear to me!<br/>Cross over to life!<br/>',NULL,67739,6);
INSERT INTO stanza VALUES('NS827','7','Cross over to Christ, again and again,<br/>Cross over to Christ, again and again,<br/>Cross over to Christ, again and again,<br/>We are through with the devil and sin!<br/>God of glory appear to me!<br/>Cross over to Christ!<br/>',NULL,67740,7);
INSERT INTO stanza VALUES('NS828','chorus','The Propagation of the Resurrected Christ<br/>in His Ascension,<br/>by the Spirit,<br/>through the Disciples,<br/>for the Producing of the Churches—<br/>The Kingdom of God.<br/>',NULL,67741,1);
INSERT INTO stanza VALUES('NS829','1','In Him there is the eternal life,<br/>The life in Him is the light of man.<br/>The light which in the darkness shines<br/>can never be overcome,<br/>can never be overcome.<br/>',NULL,67742,1);
INSERT INTO stanza VALUES('NS829','2','In Him there is the eternal life.<br/>And Jesus said “I am the light of the world,<br/>And those that choose to follow Me,<br/>They will have the light of life,<br/>They will have the light of life.”<br/>',NULL,67743,2);
INSERT INTO stanza VALUES('NS830','1','The Triune God has journeyed down to reach man;<br/>The God who dwells in unseen light—a Man becomes!<br/>Flesh and blood to partake,<br/>In our form He came, all for our sake;<br/>The Triune God,<br/>Has journeyed down.<br/>',NULL,67744,1);
INSERT INTO stanza VALUES('NS830','2','The Triune God has journeyed down to reach man;<br/>A child born, our “Christ the Lord,” in Bethlehem!<br/>Both divine and human,<br/>The perfect God-man walks on the earth; <br/>The Triune God<br/>A Man became.<br/>',NULL,67745,2);
INSERT INTO stanza VALUES('NS830','3','What love is this? Redemption shows its greatness!<br/>Love manifest, God in the flesh dies for man’s sins,<br/>Who can fathom this love?<br/>God shed “His own blood” to purchase us;<br/>The Triune God,<br/>His love reached man.<br/>',NULL,67746,3);
INSERT INTO stanza VALUES('NS830','4','Christ died and rose, the Spirit thus becoming!<br/>As Spirit, now He spreads in our tripartite being!<br/>Men of dust are made stones,<br/>Built up as God’s home, His dwelling place!<br/>The Triune God,<br/>Has entered man.<br/>',NULL,67747,4);
INSERT INTO stanza VALUES('NS830','5','God now transmits life bit by bit within man;<br/>Now Christ and His redeemed can live and walk as one!<br/>Thus His plan is fulfilled<br/>His Body is built, organically;<br/>The Triune God,<br/>On earth expressed!<br/>',NULL,67748,5);
INSERT INTO stanza VALUES('NS830','6','One day in fullness shall appear God’s glory,<br/>Down out of heav’n from God—the holy city see!<br/>God Himself is her light;<br/>She’s glorious, bright, eternally!<br/>The Triune God,<br/>One with His bride!<br/>',NULL,67749,6);
INSERT INTO stanza VALUES('NS831','1','Thy name, dear Father, is for Thee<br/>Much more than just a title;<br/>By Thine eternal life divine<br/>’Tis living, real, and vital!<br/>',NULL,67750,1);
INSERT INTO stanza VALUES('NS831','2','As Father Thou art shown to us,<br/>Life’s source, origination,<br/>Thou dost beget, and propagate<br/>For Thy multiplication.<br/>',NULL,67751,2);
INSERT INTO stanza VALUES('NS831','3','The riches of Thy life are seen<br/>In children without number;<br/>Now we, as those whom Thou brought forth,<br/>Praise Thee: “How great a Father!”<br/>',NULL,67752,3);
INSERT INTO stanza VALUES('NS831','4','To us the Son has made Thee known<br/>Not in a teaching; rather,<br/>By His imparting of Thy life,<br/>We know Thee as our Father.<br/>',NULL,67753,4);
INSERT INTO stanza VALUES('NS831','5','Though still we’re living in the world,<br/>As long as we remain here<br/>Keep, guard, and sanctify us in<br/>Thy name, O Holy Father.<br/>',NULL,67754,5);
INSERT INTO stanza VALUES('NS831','6','We many sons in life as one<br/>Enjoy Thy name’s sweet flavor;<br/>“O Father” is our corporate cry;<br/>Such sweetness now we savor!<br/>',NULL,67755,6);
INSERT INTO stanza VALUES('NS831','7','Now by Thy life and nature we<br/>Are one with one another;<br/>Our inner joy here overflows<br/>In praises to Thee, Father!<br/>',NULL,67756,7);
INSERT INTO stanza VALUES('NS832','chorus','Lord, sanctify me in the truth,<br/>In every word breathed out by You.<br/>Your word contains, conceals the Triune God within.<br/>Your word is the reality,<br/>It brings the Triune God to me,<br/>To separate me from the world and sin.<br/>',NULL,67757,1);
INSERT INTO stanza VALUES('NS832','chorus','Your word conveys the truth to me,<br/>Of all You are in Your reality.<br/>',NULL,67758,2);
INSERT INTO stanza VALUES('NS832','chorus','Counter melody:<br/>God is light,<br/>And God is love,<br/>And God is life to me.<br/>Righteousness,<br/>And holiness,<br/>And my reality.<br/>',NULL,67759,3);
INSERT INTO stanza VALUES('NS833','1','God is working Himself into man,<br/>We’re becoming His full expression,<br/>We are filled with the nature of God,<br/>Christ is making His home in our hearts.<br/>',NULL,67760,1);
INSERT INTO stanza VALUES('NS833','chorus','We are the church,<br/>The mingling of God and man!<br/>The Triune God<br/>has produced the golden lampstands!<br/>',NULL,67761,2);
INSERT INTO stanza VALUES('NS833','2','God the Father is the husbandman,<br/>God the Son is the true vine in Him,<br/>God the Spirit flows within the vine,<br/>Bringing us all the riches of life.<br/>',NULL,67762,3);
INSERT INTO stanza VALUES('NS833','chorus','We are branches!<br/>Abide in the vine! Live in Him!<br/>We must bear fruit!<br/>Let’s share all these riches to friends!<br/>',NULL,67763,4);
INSERT INTO stanza VALUES('NS833','3','God the Father, His nature pure gold,<br/>Is the street, our way which we go!<br/>God in Christ, the Spirit who flows,<br/>Is our life! We are jasper stones!<br/>',NULL,67764,5);
INSERT INTO stanza VALUES('NS833','chorus','We are shining,<br/>Expressing the richness of life!<br/>We must receive!<br/>Partake of His nature divine!<br/>',NULL,67765,6);
INSERT INTO stanza VALUES('NS833','4','What’s the ultimate consummation?<br/>It’s a mutual habitation!<br/>God lives in us and we live in Him!<br/>We’re in God! Such a coinherence!<br/>',NULL,67766,7);
INSERT INTO stanza VALUES('NS833','chorus','We are the church,<br/>The mingling of God and man!<br/>Our destiny!<br/>The New Jerusalem!<br/>',NULL,67767,8);
INSERT INTO stanza VALUES('NS834','1','What a mystery,<br/>Mystery of mysteries,<br/>Our God is Triune,<br/>Our God is one yet three!<br/>Father, Son, and Spirit flow in me,<br/>Praise the Lord for His divine Trinity!<br/>',NULL,67768,1);
INSERT INTO stanza VALUES('NS834','chorus','God the Father planned for His purpose,<br/>God the Son died and redeemed,<br/>We were sealed with God, the Holy Spirit,<br/>Oh, the Triune God has a plan, economy!<br/>',NULL,67769,2);
INSERT INTO stanza VALUES('NS834','2','What a mystery,<br/>Wonderful mystery,<br/>Our God is Spirit,<br/>He flows the Son to me!<br/>Calling Jesus’ name, we get all three,<br/>Praise the Lord for His divine Trinity!<br/>',NULL,67770,3);
INSERT INTO stanza VALUES('NS834','chorus','How I love His name, “Oh Lord Jesus!”<br/>When I call He comes to me,<br/>As the Spirit from and with the Father,<br/>Oh, the Triune God reaches me, even me!<br/>',NULL,67771,4);
INSERT INTO stanza VALUES('NS834','3','What a mystery,<br/>Wonderful mystery,<br/>The Triune God has,<br/>Incorporated me,<br/>As a member I’m in the Body,<br/>Reconciled through His divine Trinity.<br/>',NULL,67772,5);
INSERT INTO stanza VALUES('NS834','chorus','Hallelujah He is dispensing,<br/>Hallelujah all His being,<br/>One with Him we stand as His own Body,<br/>Oh, the Triune God has the church eternally.<br/>',NULL,67773,6);
INSERT INTO stanza VALUES('NS835','chorus','We will choose life! Choose the life of God!<br/>We will lay hold—on eternal life!<br/>In an age of passivity, we will make this choice to be<br/>Enjoyers and partakers of this life!<br/>',NULL,67774,1);
INSERT INTO stanza VALUES('NS835','1','Life is God Himself,<br/>He’s the source of life divine,<br/>Christ the Son is the course,<br/>And the Spirit is the flow of this life<br/>Now this life is in us, flowing free!<br/>',NULL,67775,2);
INSERT INTO stanza VALUES('NS835','2','We must fight to maintain,<br/>And enjoy this life everyday,<br/>Read the word, call His name,<br/>Praise and sing with Him throughout all the day.<br/>There’s no need to wait to grow in life!<br/>',NULL,67776,3);
INSERT INTO stanza VALUES('NS835','3','As we grow in this life,<br/>God and man are mingled as one.<br/>Life will build up the church,<br/>And produce the New Jerusalem.<br/>Then in us, God’s purpose is fulfilled!<br/>',NULL,67777,4);
INSERT INTO stanza VALUES('NS836','1','A prodigal, no need I sensed<br/>For God my folks had known;<br/>The world’s allure enticed me thence;<br/>Its friendship close had grown.<br/>',NULL,67778,1);
INSERT INTO stanza VALUES('NS836','chorus','My emptiness relentless still,<br/>I searched, but naught did find.<br/>Confused, I tried whatever thrilled;<br/>It more my void defined.<br/>',NULL,67779,2);
INSERT INTO stanza VALUES('NS836','2','God’s vessels kind would not forget<br/>This poor soul, most decried.<br/>A God so real, through them I met;<br/>I could no more deny.<br/>',NULL,67780,3);
INSERT INTO stanza VALUES('NS836','chorus','Alone, distressed, from peace apart,<br/>I for God’s solace yearned;<br/>Their tender love warmed up my heart<br/>Until it Godward turned.<br/>',NULL,67781,4);
INSERT INTO stanza VALUES('NS836','3','O precious faith! O sweetest love!<br/>O joy beyond compare!<br/>Life’s every turn God’s mercy proved,<br/>Unfailing, secret care.<br/>',NULL,67782,5);
INSERT INTO stanza VALUES('NS836','chorus','Yet God would know my dreams remained;<br/>I craved what earthlings craved.<br/>By mercy I God’s vision gained;<br/>His goal my path re-paved.<br/>',NULL,67783,6);
INSERT INTO stanza VALUES('NS836','4','E’en if I take the wings of dawn,<br/>At ocean’s limits dwell*,<br/>God faithful, wise, will lead me on,<br/>His searchings keep me well.<br/>',NULL,67784,7);
INSERT INTO stanza VALUES('NS836','chorus','My heart o’erflows with songs of praise;<br/>God’s mercy is my crown.<br/>His love a wretched soul embraced,<br/>Transforms to glory-bound.<br/>',NULL,67785,8);
INSERT INTO stanza VALUES('NS836','5','Go forth! Our Shepherd yearns that more<br/>Lost prodigals we’d find<br/>Into each wounded heart outpour<br/>Fresh, timely oil and wine!<br/>',NULL,67786,9);
INSERT INTO stanza VALUES('NS836','chorus','Search out the weak, the wayward, lost;<br/>In meekness bring them home!<br/>Warm, tender love they need the most<br/>And God’s acceptance shown.<br/>',NULL,67787,10);
INSERT INTO stanza VALUES('NS836','6','The Lord is pleased to build His home<br/>In every contrite heart;<br/>The feeble in His hand become<br/>His warring counterpart.<br/>',NULL,67788,11);
INSERT INTO stanza VALUES('NS836','chorus','Christ will all Satan’s work efface<br/>Through wisdom full and grace;<br/>The church will e’er His foe disgrace<br/>To universal praise!<br/>',NULL,67789,12);
INSERT INTO stanza VALUES('NS836','end-note','* Psa. 139:9<br/>',NULL,67790,13);
INSERT INTO stanza VALUES('NS837','1','There are days blue skies can’t be found,<br/>When dark and gloomy clouds are all around.<br/>Do we treasure God’s life within,<br/>Or do we struggle on with right and wrong?<br/>No food, no drink, no home, no rest, no peace<br/>If we let thorns our oneness pierce;<br/>If one day stormy winds come our way,<br/>Will we then be shaken, fall away?<br/>',NULL,67791,1);
INSERT INTO stanza VALUES('NS837','chorus','Highways to life, the path our feet must tread<br/>By enjoying Christ, we’re safely led.<br/>Check God in living!<br/>In Him remain, just enjoy Him;<br/>Therefore disheartened, we dare not to be<br/>Firm in heart, now, we<br/>Stay in this line continually<br/>He’ll give Himself faithfully.<br/>',NULL,67792,2);
INSERT INTO stanza VALUES('NS837','2','Life that swallows death now has come;<br/>‘Tis Christ as our eternal portion.<br/>True Vine, Bread of life, all we need,<br/>Life’s Author, even life itself indeed.<br/>This Tree of Life, to us a promise giv’n,<br/>Closed to us by the fall of man;<br/>Christ us redeemed, re-op’ning the way,<br/>Then rising, life conquered death for aye.<br/>',NULL,67793,3);
INSERT INTO stanza VALUES('NS837','chorus','Highways to life, the path our feet must tread<br/>By enjoying Christ, we’re safely led.<br/>Check God in living!<br/>In Him remain, just enjoy Him;<br/>Therefore disheartened, we dare not to be<br/>Firm in heart, now, we<br/>Stay in this line continually<br/>He’ll give Himself faithfully.<br/>',NULL,67794,4);
INSERT INTO stanza VALUES('NS837','3','Daily eat and drink, breathe in Christ,<br/>Our thirst is quenched, our hunger satisfied;<br/>With our spirit pray, touch the Word,<br/>By pray’r in private, touch the living Lord.<br/>Confess, be dealt with for the genuine growth;<br/>His life in us may freely flow.<br/>Have more of Christ wrought into our being<br/>Till others receive life’s watering.<br/>',NULL,67795,5);
INSERT INTO stanza VALUES('NS837','chorus','Highways to life, the path our feet must tread<br/>By enjoying Christ, we’re safely led.<br/>Check God in living!<br/>In Him remain, just enjoy Him;<br/>Therefore disheartened, we dare not to be<br/>Firm in heart, now, we<br/>Stay in this line continually<br/>He’ll give Himself faithfully.<br/>',NULL,67796,6);
INSERT INTO stanza VALUES('NS837','4','Life results in building, we see;<br/>Fulfilling God’s divine economy.<br/>God Triune is our oneness real<br/>One corp’rate Body’s what He wants to see;<br/>Each one grows with the growth of God each day,<br/>We have real building, God display;<br/>The New Jerusalem we will be,<br/>Our glorious eternal destiny.<br/>',NULL,67797,7);
INSERT INTO stanza VALUES('NS837','chorus','Highways to life, the path our feet must tread<br/>By enjoying Christ, we’re safely led.<br/>Check God in living!<br/>In Him remain, just enjoy Him;<br/>Therefore disheartened, we dare not to be<br/>Firm in heart, now, we<br/>Stay in this line continually<br/>He’ll give Himself faithfully.<br/>',NULL,67798,8);
INSERT INTO stanza VALUES('NS838','1','We believers should follow the sunrising<br/>Follow the sunrising to be revived,<br/>We believers should follow the sunrising<br/>Follow the sunrising to be revived,<br/>And to have a new beginning,<br/>A new beginning every morning;<br/>Every day we need a “sunrising”<br/>And this is our revival.<br/>We need to follow the sunrising—<br/>Waiting for new beginning!<br/>',NULL,67799,1);
INSERT INTO stanza VALUES('NS838','2','In the morning we enjoy Christ’s shining,<br/>Receiving His healing and enlivening. (Mal. 4:2)<br/>In the morning we enjoy Christ’s shining,<br/>Receiving His healing and enlivening. (Mal. 4:2)<br/>If we love Him with our being,<br/>We’ll be like the sun in its rising! (Judg. 5:31)<br/>Every day we behold His shining,<br/>And we’ll be just like Him.<br/>We need to follow the sunrising—<br/>Yearning for His appearing!<br/>',NULL,67800,2);
INSERT INTO stanza VALUES('NS839','chorus','March on as one with the energizing God!<br/>In Him! With Him!<br/>March on in Christ with the Spirit and the Word!<br/>By Him! And for Him!<br/>',NULL,67801,1);
INSERT INTO stanza VALUES('NS839','1','By Christ our Savior, Joshua,<br/>We press into the Land,<br/>The promised all-inclusive One,<br/>The grace on which we stand.<br/>',NULL,67802,2);
INSERT INTO stanza VALUES('NS839','2','Our Captain Jesus leading us<br/>To glory and to peace,<br/>Defeats the devil, flesh, and sin<br/>As on the Land we feast.<br/>',NULL,67803,3);
INSERT INTO stanza VALUES('NS839','3','Gain Christ for Christ to be in us,<br/>The land we all possess;<br/>Now we respond to overcome,<br/>Christ’s riches to express!<br/>',NULL,67804,4);
INSERT INTO stanza VALUES('NS839','4','Our Christian call to live by faith<br/>And not by what we see<br/>Is Christ in us, the faithful One,<br/>In whom is victory!<br/>',NULL,67805,5);
INSERT INTO stanza VALUES('NS839','end-note','(2021 July Training Joshua, Message 1)<br/>',NULL,67806,6);
INSERT INTO stanza VALUES('NS840','1','Lord, You are the way<br/>To heal my heart today,<br/>The cure to all my anxious thoughts and fears.<br/>When I call Your name,<br/>Within me there’s a change,<br/>A love that cleanses all the ash and tears.<br/>',NULL,67807,1);
INSERT INTO stanza VALUES('NS840','chorus','Lord, You are my everything,<br/>And in You I find rest;<br/>Hear me when I say to You<br/>That I have found the best,<br/>And words that can explain Your perfect love<br/>I’ll never know.<br/>',NULL,67808,2);
INSERT INTO stanza VALUES('NS840','2','Gentle as a breeze,<br/>Your love puts me at ease<br/>Like water in the desert of my heart.<br/>Lord, I need You now,<br/>As much as You’ll allow;<br/>When called to You I’ll joyously depart.<br/>',NULL,67809,3);
INSERT INTO stanza VALUES('NS840','chorus','Lord, You are my everything,<br/>And in You I find rest;<br/>Hear me when I say to You<br/>That I have found the best,<br/>And words that can explain Your perfect love<br/>I’ll never know.<br/>',NULL,67810,4);
INSERT INTO stanza VALUES('NS840','3','If You took pen in hand<br/>To write Your love for man<br/>The ocean turned to ink would soon run dry.<br/>Now my worries cease;<br/>Inside me only peace.<br/>Forever in Your pastures I will lie.<br/>',NULL,67811,5);
INSERT INTO stanza VALUES('NS840','chorus','Lord, You are my everything,<br/>And in You I find rest;<br/>Hear me when I say to You<br/>That I have found the best,<br/>And words that can explain Your perfect love<br/>I’ll never know.<br/>',NULL,67812,6);
INSERT INTO stanza VALUES('NS841','1','Blessed is the man whose strength is in You,<br/>In whose heart are the highways to Zion.<br/>',NULL,67813,1);
INSERT INTO stanza VALUES('NS841','2','Passing through the valley of Baca,<br/>They make it a spring;<br/>Indeed the early rain covers it with blessings.<br/>',NULL,67814,2);
INSERT INTO stanza VALUES('NS841','3','They go from strength to strength;<br/>Each appears before God in Zion.<br/>They go from strength to strength;<br/>Each appears before God in Zion.<br/>',NULL,67815,3);
INSERT INTO stanza VALUES('NS842','1','Oh tell me, what’s the key<br/>To build the Body?<br/>How to be deified,<br/>The Body realise?<br/>',NULL,67816,1);
INSERT INTO stanza VALUES('NS842','chorus','Eat the hidden manna—<br/>Get God into you,<br/>’Cause when God gets into you,<br/>You get into God!<br/>',NULL,67817,2);
INSERT INTO stanza VALUES('NS842','2','Our God is enterable,<br/>And He’s enjoyable,<br/>Our Christ—He is the way,<br/>We eat Him ev’ry day!<br/>',NULL,67818,3);
INSERT INTO stanza VALUES('NS842','chorus','Eat the hidden manna—<br/>Get God into you,<br/>’Cause when God gets into you,<br/>You get into God!<br/>',NULL,67819,4);
INSERT INTO stanza VALUES('NS842','3','Center of centers ’tis,<br/>The hidden manna is.<br/>Our deepest life supply;<br/>How He does satisfy!<br/>',NULL,67820,5);
INSERT INTO stanza VALUES('NS842','chorus','Eat the hidden manna—<br/>Get God into you,<br/>’Cause when God gets into you,<br/>You get into God!<br/>',NULL,67821,6);
INSERT INTO stanza VALUES('NS842','4','Don’t trust the circumstance,<br/>For it is just the chance<br/>To get more God in you,<br/>Become Him through and through!<br/>',NULL,67822,7);
INSERT INTO stanza VALUES('NS842','chorus','Eat the hidden manna—<br/>Get God into you,<br/>’Cause when God gets into you,<br/>You get into God!<br/>',NULL,67823,8);
INSERT INTO stanza VALUES('NS842','5','Spend time alone with Him,<br/>Just love Him, talk to Him;<br/>By this we’re deified<br/>And we become His Bride!<br/>',NULL,67824,9);
INSERT INTO stanza VALUES('NS842','chorus','Eat the hidden manna—<br/>Get God into you,<br/>’Cause when God gets into you,<br/>You get into God!<br/>',NULL,67825,10);
INSERT INTO stanza VALUES('NS843','1','In order for us to fully gain<br/>and possess Christ as the all-inclusive land<br/>for God’s building,<br/>we must learn to be kept, to be ruled,<br/>to be governed, and to be guided<br/>by the direct, firsthand presence of the Lord;<br/>if we have the Lord’s presence,<br/>we have wisdom, insight, foresight,<br/>and the inner knowledge concerning things;<br/>if we have the Lord’s presence,<br/>we have wisdom, insight, foresight,<br/>and the inner knowledge concerning things;<br/>the Lord’s presence is everything,<br/>the Lord’s presence is everything,<br/>the Lord’s presence is everything to us.<br/>',NULL,67826,1);
INSERT INTO stanza VALUES('NS844','1','In the Church we are living as one<br/>To express the love of Christ the Son!<br/>(Brothers:) We are one!<br/>(Sisters:) We are one!<br/>In the Body and in spirit we are one!<br/>',NULL,67827,1);
INSERT INTO stanza VALUES('NS844','2','In the Church, fellowship in the Lord<br/>Is the way to walk in one accord!<br/>(Brothers:) Fellowship!<br/>(Sisters:) Fellowship!<br/>Blending with the saints and building day by day!<br/>',NULL,67828,2);
INSERT INTO stanza VALUES('NS844','3','What a joy when we open our home<br/>To receive the saints; God’s love is shown!<br/>(Brothers:) What a joy!<br/>(Sisters:) What a joy!<br/>That an open home is where we’re built today!<br/>',NULL,67829,3);
INSERT INTO stanza VALUES('NS844','4','Thank You Lord, through Your great love of man<br/>You’ve revealed to us Your perfect plan!<br/>(Brothers:) By Your grace!<br/>(Sisters:) By Your grace!<br/>We have seen the vision of the church today!<br/>',NULL,67830,4);
INSERT INTO stanza VALUES('NS845','1','Lord, today, I open my being<br/>And allow Your flame to search my inward parts;<br/>Burn away all the wicked way in my heart,<br/>Cleanse away, Lord, today, today.<br/>',NULL,67831,1);
INSERT INTO stanza VALUES('NS845','2','If my Bridegroom further delays,<br/>Shall I passive be while waiting for too long?<br/>As I wait I’d be clothed with Thy garment,<br/>As a bride adorned for her Husband to be, to be.<br/>',NULL,67832,2);
INSERT INTO stanza VALUES('NS845','3','Lord, it’s just a matter of time<br/>You would make us all perfected somehow.<br/>But I’d rather be judged and exposed now<br/>Than to wait for that coming day,<br/>Lest I miss Thy face<br/>Today, today, Lord, today.<br/>',NULL,67833,3);
INSERT INTO stanza VALUES('NS846','1','Up the mount, I am coming;<br/>To Your call, I’m responding.<br/>Dearest Lord, I am here to seek Your face.<br/>I have seen how my living<br/>Falls so short of Your building—<br/>How could I match You, Lord, without Your grace?<br/>',NULL,67834,1);
INSERT INTO stanza VALUES('NS846','chorus','Make me holy as You!<br/>This is Your promise true!<br/>Purify me for the building of Your house.<br/>',NULL,67835,2);
INSERT INTO stanza VALUES('NS846','2','Cleanse me from all things sinful;<br/>Deal with all worldly idols.<br/>Separate me from all defilement.<br/>Then impart life into me;<br/>Flow throughout my whole being.<br/>Saturate me with Your life element.<br/>',NULL,67836,3);
INSERT INTO stanza VALUES('NS846','3','Here the air is so clear, Lord.<br/>Speak to me through Your Word more.<br/>Have Your way in me; heav’nly Light, do shine!<br/>Search my heart, every chamber;<br/>From each part, darkness scatter.<br/>Make my whole body full of light divine!*<br/>',NULL,67837,4);
INSERT INTO stanza VALUES('NS846','end-note','* cf. Matt. 6:22<br/>',NULL,67838,5);
INSERT INTO stanza VALUES('NS846','4','In Your presence, I linger.<br/>It’s Your beauty—I’m captured!<br/>You have won me with Your attractiveness.<br/>Vanity I’m exhaling,<br/>All Your fullness inhaling;<br/>Deeply breathe into me Your holiness.<br/>',NULL,67839,6);
INSERT INTO stanza VALUES('NS846','5','Purify and make holy<br/>And reconstitute fully—<br/>Keep me growing, pursuing, in this way.<br/>Gain us, Lord, for Your building!<br/>For the Body, we’re willing!<br/>To fulfill Your heart’s longing we will say:<br/>',NULL,67840,7);
INSERT INTO stanza VALUES('NS846','chorus','We will rise up and build!<br/>Spirits stirred up, hearts filled,<br/>We love You and we give all to build Your house!<br/>',NULL,67841,8);
INSERT INTO stanza VALUES('NS847','1','The more Christ lives in us, the more we’re one, <br/>One in the Triune God! <br/>His living now perfects us into one, <br/>One in the Triune God.<br/><br/>One in the Triune God,<br/>One in the Triune God,<br/>One in the Father, Son, and the Spirit,<br/>One in the Triune God!<br/>',NULL,67842,1);
INSERT INTO stanza VALUES('NS847','2','Concepts, opinions, and ambitions rife <br/>Aren’t in the Triune God.<br/>Self-exaltation, worldliness, and strife <br/>Aren’t in the Triune God.<br/><br/>We need the Triune God,<br/>We need the Triune God,<br/>We need the Father, Son, and the Spirit,<br/>We need the Triune God!<br/>',NULL,67843,2);
INSERT INTO stanza VALUES('NS847','3','Genuine oneness comes by normal growth<br/>Into the Triune God!<br/>Exit the self, by consecration’s oath, <br/>Into the Triune God!<br/><br/>Into the Triune God,<br/>Into the Triune God,<br/>Into the Father, Son, and the Spirit,<br/>Into the Triune God!<br/>',NULL,67844,3);
INSERT INTO stanza VALUES('NS847','4','Drop the opinions! God’s expression heed! <br/>Be in the Triune God!<br/>Deny the self! Take up the cross indeed! <br/>Be in the Triune God!<br/><br/>Be in the Triune God,<br/>Be in the Triune God,<br/>Be in the Father, Son, and the Spirit,<br/>Be in the Triune God!<br/>',NULL,67845,4);
INSERT INTO stanza VALUES('NS847','5','Christ’s death and resurrection paved the way<br/>Into the Triune God!<br/>Moment by moment, let us choose to stay, <br/>Stay in the Triune God!<br/><br/>Stay in the Triune God!<br/>Stay in the Triune God!<br/>Stay in the Father, Son, and the Spirit!<br/>Stay in the Triune God!<br/>',NULL,67846,5);
INSERT INTO stanza VALUES('NS847','6','The Father’s life and nature we express—<br/>Here in the Triune God!<br/>Within His glory, oneness we possess—<br/>Here in the Triune God!<br/><br/>We’re in the Triune God!<br/>We’re in the Triune God!<br/>We’re in the Father, Son, and the Spirit!<br/>We’re in the Triune God!<br/>',NULL,67847,6);
INSERT INTO stanza VALUES('NS848','1','If there is a song, a song I must sing,<br/>That song is of Christ, my Savior and King!<br/>The Lamb who was slain and made my robes white,<br/>And opened the way to the tree of life!<br/>',NULL,67848,1);
INSERT INTO stanza VALUES('NS848','chorus','Oh, He is my joy, Oh,He is my rest,<br/>None other but Christ, Oh, He is the best!<br/>If there is a song, a song I must sing,<br/>That song is of Christ, my Savior and King!<br/>',NULL,67849,2);
INSERT INTO stanza VALUES('NS848','2','Oh, Christ is my strength, salvation and song!<br/>Of Him I must sing, and sing all day long!<br/>The God-man who came, yes, Jesus His name—<br/>Today, yesterday, forever the same!<br/>',NULL,67850,3);
INSERT INTO stanza VALUES('NS848','chorus','Oh, He is my joy, Oh,He is my rest,<br/>None other but Christ, Oh, He is the best!<br/>If there is a song, a song I must sing,<br/>That song is of Christ, my Savior and King!<br/>',NULL,67851,4);
INSERT INTO stanza VALUES('NS848','3','This One is my peace, my healing, my rest,<br/>My light in the night, my joy in distress;<br/>My Shepherd who guides to rivers of life<br/>Brings joy to my heart and blissful delight!<br/>',NULL,67852,5);
INSERT INTO stanza VALUES('NS848','chorus','Oh, He is my joy, Oh,He is my rest,<br/>None other but Christ, Oh, He is the best!<br/>If there is a song, a song I must sing,<br/>That song is of Christ, my Savior and King!<br/>',NULL,67853,6);
INSERT INTO stanza VALUES('NS848','4','My Christ is true joy, my sunlight each day,<br/>When I sing of Him no sorrow can stay!<br/>My death He made life, my mourning made song,<br/>Of Him I must sing and sing all day long!<br/>',NULL,67854,7);
INSERT INTO stanza VALUES('NS848','chorus','Oh, He is my joy, Oh,He is my rest,<br/>None other but Christ, Oh, He is the best!<br/>If there is a song, a song I must sing,<br/>That song is of Christ, my Savior and King!<br/>',NULL,67855,8);
INSERT INTO stanza VALUES('NS849','chorus','Let the word of Christ dwell in you richly<br/>in all wisdom, teaching and admonishing<br/>one another with psalms and hymns and spiritual songs,<br/>singing with grace in your hearts to God.<br/>',NULL,67856,1);
INSERT INTO stanza VALUES('NS850','chorus','Whither shall I go from Thy Spirit,<br/>And whither shall I flee from Thy presence?<br/>',NULL,67857,1);
INSERT INTO stanza VALUES('NS850','1','If I ascend up into the heaven, Thou art there;<br/>For if I make my bed in Sheol,<br/>Behold, Thou art there.<br/>',NULL,67858,2);
INSERT INTO stanza VALUES('NS850','2','If I take the wings of the dawn<br/>And dwell in the uttermost parts of the sea,<br/>Behold, Thou art there.<br/>',NULL,67859,3);
INSERT INTO stanza VALUES('NS850','3','Even there shall Thy hand lead me<br/>And even there Thy right hand shall hold me.<br/>Behold, Thou art there.<br/>',NULL,67860,4);
INSERT INTO stanza VALUES('NS851','1','Dig up the wells my father made;<br/>Call them by the same names.<br/>His portion was a life of faith;<br/>Mine, inheriting grace.<br/>',NULL,67861,1);
INSERT INTO stanza VALUES('NS851','2','Stake out the camp within the dell;<br/>There we’ll find a springing well.<br/>Theirs is the claim that leads to strife;<br/>Mine, inheriting life.<br/>',NULL,67862,2);
INSERT INTO stanza VALUES('NS851','3','Richer and great I grew to be;<br/>Such gave rise to enmity.<br/>Destined for joy, yet this I know,<br/>God will not let me go.<br/>',NULL,67863,3);
INSERT INTO stanza VALUES('NS851','4','Though wells availed in all the land,<br/>Still I came to doubt my stand.<br/>Blessings divine can ne’er replace<br/>God’s appearing in grace.<br/>',NULL,67864,4);
INSERT INTO stanza VALUES('NS851','5','I, in Beersheba, will remain,<br/>Build an altar, call His name,<br/>Draw from the well that flows so free<br/>By the tamarisk tree.<br/>',NULL,67865,5);
INSERT INTO stanza VALUES('NS851','6','Dig up the wells my father made;<br/>Call them by the same names.<br/>His portion was a life of faith;<br/>Mine, inheriting grace.<br/>',NULL,67866,6);
INSERT INTO stanza VALUES('NS852','chorus','I’m very encouraged, my Lord is Jesus Christ,<br/>I’m very encouraged, I have eternal life;<br/>For God my Father has chosen me in love,<br/>And through His Spirit I’m joined to His Beloved!<br/>',NULL,67867,1);
INSERT INTO stanza VALUES('NS852','1','Christ’s work is my faith, My trust is all in Him,<br/>And my salvation has glory as its end.<br/>',NULL,67868,2);
INSERT INTO stanza VALUES('NS852','2','Now through the gospel, Christ’s vict’ry is my claim,<br/>And through His ministry in life I am the same.<br/>',NULL,67869,3);
INSERT INTO stanza VALUES('NS852','3','Now Him who loved us is comfort, hope, and grace,<br/>As we anticipate His coming, shining face!<br/>',NULL,67870,4);
INSERT INTO stanza VALUES('NS852','end-note','You can repeat using “Don’t be discouraged”   and change to third person.<br/>',NULL,67871,5);
INSERT INTO stanza VALUES('NS853','1','Father, how we love You,<br/>How we worship You in Your dispensing.<br/>Father, how we love You,<br/>How we worship You in Your sonship.<br/>Lord, we honor Your Son<br/>By our living in truthfulness,<br/>And we worship You, God,<br/>Holy Father, as Your true worshippers....<br/>True worshippers.... Father God!<br/>',NULL,67872,1);
INSERT INTO stanza VALUES('NS853','2','Father, how we love You,<br/>How we worship You in Your one Body;<br/>Father, how we love You,<br/>How we worship You in our feasting;<br/>By our eating this bread,<br/>And our drinking of this one cup,<br/>We do worship You, God,<br/>Holy Father, as Your true worshippers....<br/>True worshippers.... Father God!<br/>',NULL,67873,2);
INSERT INTO stanza VALUES('NS854','1','The age is turning! Saints, awake!<br/>The Lord returns to judgment make!<br/>Behind the scenes our God is reigning,<br/>Heaven’s will on earth attaining.<br/>Don’t with past gains be satisfied;<br/>Recalculate in judgment’s light.<br/>The world forsake, with its ties; leave all behind.<br/>“Who will overcome?” “Lord, here am I!”<br/>',NULL,67874,1);
INSERT INTO stanza VALUES('NS854','chorus','Overcomers, steadfast in heart,<br/>From the Lamb’s lead never depart.<br/>Love with all our heart, all our strength, faithful to death;<br/>Serve in resurrection fragrantly.<br/>Christ, the church—life’s meaning we see;<br/>We’ll spend all our being gladly,<br/>Build God’s temple and city grand, God one with man;<br/>New Jerus’lem radiant be!<br/>',NULL,67875,2);
INSERT INTO stanza VALUES('NS854','2','As we pursue, and trials face,<br/>Your sov’reign mercy we can trace.<br/>We’re open vessels, consecrated.<br/>Living Spring, come permeate us.<br/>Inscribe Your law, our mind renew;<br/>Come sanctify us wholly, too.<br/>We’ll watch, buy oil now, “today,” feast’s entrance gain;<br/>Virgins, echo You—“O Lord, come soon!”<br/>',NULL,67876,3);
INSERT INTO stanza VALUES('NS854','chorus','Overcomers, steadfast in heart,<br/>From the Lamb’s lead never depart.<br/>Love with all our heart, all our strength, faithful to death;<br/>Serve in resurrection fragrantly.<br/>Christ, the church—life’s meaning we see;<br/>We’ll spend all our being gladly,<br/>Build God’s temple and city grand, God one with man;<br/>New Jerus’lem radiant be!<br/>',NULL,67877,4);
INSERT INTO stanza VALUES('NS854','3','Today You call for instruments<br/>Who will respond, Your heart reprint,<br/>Be vital, fervent, overcoming,<br/>Time redeeming ev’ry instant.<br/>As stewards, timely food dispense;<br/>As servants, wisely to invest;<br/>Perfected, functioning, we build corp’ rately,<br/>Blend, coordinate, new man to be.<br/>',NULL,67878,5);
INSERT INTO stanza VALUES('NS854','chorus','Overcomers, steadfast in heart,<br/>From the Lamb’s lead never depart.<br/>Love with all our heart, all our strength, faithful to death;<br/>Serve in resurrection fragrantly.<br/>Christ, the church—life’s meaning we see;<br/>We’ll spend all our being gladly,<br/>Build God’s temple and city grand, God one with man;<br/>New Jerus’lem radiant be!<br/>',NULL,67879,6);
INSERT INTO stanza VALUES('NS854','4','These final days, Your call we heed,<br/>As remnants, standing mightily.<br/>The arrow’s fired; the fight’s decided;<br/>The white horse in triumph rideth.<br/>High gospel to all earth declare!<br/>We’ll migrate, spread, His witness bear;<br/>We’ll forward race with bold strides, stake our whole lives,<br/>Kingdom’s entrance share, glory fore’er!<br/>',NULL,67880,7);
INSERT INTO stanza VALUES('NS854','chorus','Overcomers, steadfast in heart,<br/>From the Lamb’s lead never depart.<br/>Love with all our heart, all our strength, faithful to death;<br/>Serve in resurrection fragrantly.<br/>Christ, the church—life’s meaning we see;<br/>We’ll spend all our being gladly,<br/>Build God’s temple and city grand, God one with man;<br/>New Jerus’lem radiant be!<br/>',NULL,67881,8);
INSERT INTO stanza VALUES('NS855','chorus','Jehovah ’ppeared to me<br/>From afar,<br/>Saying, Indeed I have loved you<br/>With an eternal love,<br/>Therefore I have drawn you<br/>With lovingkindness.<br/>Therefore I have<br/>Drawn you<br/>With lovingkindness.<br/>',NULL,67882,1);
INSERT INTO stanza VALUES('NS856','1','Lord, it seems<br/>That I fail and fail again.<br/>I see Your face,<br/>But then the veils return again.<br/>Emotion’s stirred, but there’s no change in me.<br/>I’m living in my soul; I have to learn<br/>A little more, each day, O Lord, to turn.<br/>',NULL,67883,1);
INSERT INTO stanza VALUES('NS856','2','Lord, I know<br/>That I’ve truly seen You, but<br/>The vision fades;<br/>I look away to other things.<br/>Remind me, Lord, reveal Yourself to me,<br/>That from my idols I would be set free.<br/>A little more, each day, I want to see.<br/>',NULL,67884,2);
INSERT INTO stanza VALUES('NS856','3','Lord, my mind<br/>Is occupied with many things—<br/>This thorny age,<br/>With all of its anxieties.<br/>My faith is weak; I’m caught up in my cares.<br/>I need to learn to tell it all to You!<br/>A little more, each day, my mind renew.<br/>',NULL,67885,3);
INSERT INTO stanza VALUES('NS856','4','Lord, my will<br/>Is resistant to Your touch.<br/>Disarm me, Lord;<br/>Don’t let me win against Your grace.<br/>I turn my eyes and see Your patient love—<br/>What can I do but stop and come to You?<br/>A little more, each day, my will subdue.<br/>',NULL,67886,4);
INSERT INTO stanza VALUES('NS856','5','Lord, I pray,<br/>Make me desperate for You.<br/>Keep drawing me<br/>And training me to hear Your voice.<br/>Lord, even though my progress is so slow,<br/>You’re by my side; You will not let me go.<br/>A little more, each day, I’d love You so.<br/>A little more, each day, and I will grow.<br/>',NULL,67887,5);
INSERT INTO stanza VALUES('NS857','1','When I wake up<br/>To the morning sun<br/>Before the day has come and gone.<br/>I will open<br/>All my heart to You<br/>And from my spirit sing this song;<br/>',NULL,67888,1);
INSERT INTO stanza VALUES('NS857','chorus','What a wonder,<br/>What a mystery<br/>That You would be<br/>The life in me.<br/>Dear Lord Jesus,<br/>How I love You.<br/>Today, be all that I pursue.<br/>',NULL,67889,2);
INSERT INTO stanza VALUES('NS857','2','When I lay down<br/>To the moonlit sky<br/>And weary eyes begin to fade<br/>I will thank You<br/>For another day<br/>And for the life in me You gave.<br/>',NULL,67890,3);
INSERT INTO stanza VALUES('NS857','chorus','What a wonder,<br/>What a blessing;<br/>The joy You bring<br/>In everything!<br/>Dear Lord Jesus,<br/>How I love You.<br/>Tomorrow, be all I pursue.<br/>',NULL,67891,4);
INSERT INTO stanza VALUES('NS858','1','Everything seems to be a downward spiral<br/>But I’m on an upward path;<br/>Currents flow against me, still I keep on going.<br/>Wond’ring if I’ll ever last,<br/>“Do not fear”—I hear the voice of my Christ Jesus:<br/>“Just have faith, for I am the Lord.<br/>All will pass, but what you have in you’s eternal.”<br/>So I simply trust His word.<br/>',NULL,67892,1);
INSERT INTO stanza VALUES('NS858','chorus','I am not ashamed to be a Christian!<br/>I am not ashamed to love the Lord!<br/>I am not afraid to stand up for Him no matter what I’m told!<br/>The world can’t understand,<br/>But nonetheless I’ll stand;<br/>Fire will only manifest the gold.<br/>',NULL,67893,2);
INSERT INTO stanza VALUES('NS858','2','Though I feel like I’m the only one that’s different<br/>In these cruel, crooked times,<br/>I will be the salt that kills the world’s corruption<br/>And the light that brightly shines.<br/>Lord, it seems like I’m the only one who’s standing;<br/>Could it be, I’m left on my own?<br/>“Worry not for I have set apart a remnant<br/>Who, like you, seek Me alone.”<br/>',NULL,67894,3);
INSERT INTO stanza VALUES('NS858','chorus','We are not ashamed to be Christians!<br/>We are not ashamed to love the Lord!<br/>We are not afraid to stand up for Him no matter what we’re told;<br/>The world can’t see it now,<br/>But time will tell, somehow<br/>Fire will only manifest the gold!<br/>',NULL,67895,4);
INSERT INTO stanza VALUES('NS859','1','As the Author and the source of faith,<br/>Jesus is also the Leader,<br/>The Pioneer, and the Forerunner of faith.<br/>He cut the way, the way of faith<br/>And, as the Forerunner, took the lead,<br/>The lead to pioneer it.<br/>As the Author and the source of faith,<br/>Jesus is also the Leader.<br/>',NULL,67896,1);
INSERT INTO stanza VALUES('NS859','2','Hence, He can carry, carry us,<br/>Carry us in His footsteps<br/>Through the pathway, the pathway of faith.<br/>As we look, we look to Him<br/>As the Originator of faith,<br/>Faith in His life and in His path on earth,<br/>Hence, He can carry, carry us,<br/>Carry us in His footsteps.<br/>',NULL,67897,2);
INSERT INTO stanza VALUES('NS860','1','We must enjoy, experience, and take Christ as our King,<br/>The One who rules the universe, in us, is everything;<br/>With conscience clear, His presence here beneath the heav’nly throne<br/>Allow the reigning life within to make our hearts His home.<br/>',NULL,67898,1);
INSERT INTO stanza VALUES('NS860','2','We must enjoy, experience, and take Christ as our Lord,<br/>We live to Him, we die to Him, bought by His precious blood;<br/>We are the Lord’s, His life outpoured becomes our strength within,<br/>Then all our labor in the Lord is absolutely Him.<br/>',NULL,67899,2);
INSERT INTO stanza VALUES('NS860','3','We must enjoy, experience, and take Christ as our Head;<br/>By Christ, the resurrected One, we constantly are led;<br/>This fourfold power to the church becomes our heav’nly link,<br/>Abundantly supplying all, more than we ask or think.<br/>',NULL,67900,3);
INSERT INTO stanza VALUES('NS860','4','We must enjoy, experience, and take Christ as our Spouse,<br/>Our Husband, the pneumatic Christ, will build our spiritual house;<br/>Affectionate and personal, our Husband is our Friend,<br/>Our Advocate, our Comforter, our Shepherd without end.<br/>',NULL,67901,4);
INSERT INTO stanza VALUES('NS860','5','Our Husband, Head, our Lord and King, is Christ, the glorified;<br/>By life His Body will be built, His Bride be beautified;<br/>The gates of hell cannot prevail when we are built in Him,<br/>This Christ enjoyed will usher in the New Jerusalem!<br/>',NULL,67902,5);
INSERT INTO stanza VALUES('NS861','1','Days grew dark, O God,<br/>Cords of Sheol surrounded me;<br/>The snares of death came forth,<br/>Destruction had assailed on me;<br/>And in my deep distress<br/>I called upon His name.<br/>He heard my voice, descended down<br/>And saved me by His hand.<br/>',NULL,67903,1);
INSERT INTO stanza VALUES('NS861','chorus','I will call on You,<br/>For You will answer me.<br/>God hears me, speak to Thee,<br/>My refuge’s in Your love.<br/>',NULL,67904,2);
INSERT INTO stanza VALUES('NS861','2','God is my retreat,<br/>I’m the pupil of His eye.<br/>My crag, my rock, my shield,<br/>My strength is God in Him I lie.<br/>The shadow of His wings<br/>Is now the place I hide;<br/>His presence here, my comfort here,<br/>All by one simple word.<br/>',NULL,67905,3);
INSERT INTO stanza VALUES('NS861','chorus','I will call on You,<br/>For You will answer me.<br/>God hears me, speak to Thee,<br/>My refuge’s in Your love.<br/>',NULL,67906,4);
INSERT INTO stanza VALUES('NS861','3','God, I know one thing:<br/>You’re the song within my heart.<br/>You are a boundless stream,<br/>You flow in me to my delight.<br/>Oh just fill me now,<br/>Satisfaction’s in Your life.<br/>I want to stay, here with You,<br/>Salvation’s in Your name.<br/>',NULL,67907,5);
INSERT INTO stanza VALUES('NS861','chorus','I will call on You,<br/>For You will answer me.<br/>God hears me, speak to Thee,<br/>My refuge’s in Your love.<br/>',NULL,67908,6);
INSERT INTO stanza VALUES('NS862','1','O Jesus Lord, Thou fairest of the fair—<br/>None in heav’n nor on the earth can e’er compare.<br/>Better than wine is Thy sweet love to me,<br/>How could I still seek what’s less than Thee?<br/>All the earthly pleasures could not fill my soul,<br/>Failed to satisfy the longing to be whole.<br/>These all shall pass,<br/>Wither, and fade, and flee,<br/>But, You’re mine<br/>Eternally.<br/>',NULL,67909,1);
INSERT INTO stanza VALUES('NS862','2','Lord, deep within, I’ve still so many things<br/>Hidden in the chambers of my inner being<br/>I hear Thy call—Thy voice, Thy knock—a song.<br/>Lord, come in; hast Thou been kept too long?<br/>Search my heart! There’s nothing I desire to keep.<br/>All is Thine! Do then what Thou, Thy heart, doth please.<br/>But in return<br/>For what Thou take from me,<br/>Fill me Lord,<br/>Eternally.<br/>',NULL,67910,2);
INSERT INTO stanza VALUES('NS862','3','Draw me, Beloved into Thy presence dear,<br/>I would kiss Thy feet and wash them with my tears.<br/>My love I pour, my life I waste on Thee;<br/>Seize this precious opportunity!<br/>I gave all, and yet the gain was so much more:<br/>Thine own person in exchange for love outpoured.<br/>’Tis ne’er a loss<br/>To lose myself to Thee,<br/>My Beloved,<br/>Eternally.<br/>',NULL,67911,3);
INSERT INTO stanza VALUES('NS863','1','Come, come, let’s sing for joy to Jehovah;<br/>Come, come, let’s sing for joy to Jehovah;<br/>Let’s make a joyful noise to the rock of our salvation.<br/>Let’s come before His presence with thanksgiving;<br/>Let’s make a joyful noise to Him with psalms.<br/>For Jehovah is a great God, a great God, a great God.<br/>',NULL,67912,1);
INSERT INTO stanza VALUES('NS863','2','Come, come, let’s sing for joy to Jehovah;<br/>Come, come, let’s sing for joy to Jehovah;<br/>Let’s make a joyful noise to the rock of our salvation.<br/>Let’s come before His presence with thanksgiving;<br/>Let’s make a joyful noise to Him with psalms.<br/>For Jehovah is a great God, a great God, a great God<br/>And a great King above all gods,<br/>And a great King above all gods, all gods.<br/>Jehovah is a great God!<br/>',NULL,67913,2);
INSERT INTO stanza VALUES('NS864','1','Blessed with a love I did not earn<br/>When I had nowhere left to turn.<br/>Blessed with a love that’s pure, divine;<br/>Oh, what a joy that You are mine!<br/>',NULL,67914,1);
INSERT INTO stanza VALUES('NS864','chorus','Oh! Oh, Hallelujah! A love so real.<br/>Oh! Oh, Hallelujah! A love so rare, the way You care,<br/>A love that is always there.<br/>',NULL,67915,2);
INSERT INTO stanza VALUES('NS864','2','Lord, You are always in control,<br/>Able to calm my troubled soul,<br/>And would my fears be here at all<br/>If I just turned to You and called?<br/>',NULL,67916,3);
INSERT INTO stanza VALUES('NS864','chorus','Oh! Oh, Hallelujah! A love so real.<br/>Oh! Oh, Hallelujah! A love so rare, the way You care,<br/>A love that is always there.<br/>',NULL,67917,4);
INSERT INTO stanza VALUES('NS864','3','Lord, keep me always by Your side;<br/>Guard me from all that would divide,<br/>And light a fire deep in me,<br/>Burning to seek You desperately.<br/>',NULL,67918,5);
INSERT INTO stanza VALUES('NS864','chorus','Oh! Oh, Hallelujah! A love so real.<br/>Oh! Oh, Hallelujah! A love so rare, the way You care,<br/>A love that is always there.<br/>',NULL,67919,6);
INSERT INTO stanza VALUES('NS864','4','Taking more time to call Your name,<br/>Praying that more of You I’d gain,<br/>Watching all things just pass away,<br/>I cannot waste a single day.<br/>',NULL,67920,7);
INSERT INTO stanza VALUES('NS864','chorus','Oh! Oh, Hallelujah! The time is now.<br/>Oh! Oh, Hallelujah! The days are few, the world is through,<br/>Lord, keep my heart turned to You!<br/>',NULL,67921,8);
INSERT INTO stanza VALUES('NS865','1','It is God, it is God,<br/>It is God who operates in you,<br/>It is God, it is God,<br/>It is God who operates in you<br/>Both the willing and the working for His good pleasure,<br/>Both the willing and the working for His good pleasure.<br/>',NULL,67922,1);
INSERT INTO stanza VALUES('NS866','chorus','And there he built an altar to Jehovah<br/>Who had appeared to him,<br/>And called upon the name of Jehovah<br/>And built an altar to Him.<br/>',NULL,67923,1);
INSERT INTO stanza VALUES('NS866','1','Come out from your land and from your relatives,<br/>And come to the land which I will show you.<br/>Come out from your land and from your relatives,<br/>And come to the land which I will show you.<br/>',NULL,67924,2);
INSERT INTO stanza VALUES('NS866','2','For all the land that you see I will give to you<br/>And to your seed forever.<br/>For all the land that you see I will give to you<br/>And to your seed forever.<br/>',NULL,67925,3);
INSERT INTO stanza VALUES('NS866','3','Rise up, go to Bethel, make an altar there to God<br/>Who appears to you and is always with you.<br/>Rise up, go to Bethel, make an altar there to God<br/>Who appears to you and is always with you.<br/>',NULL,67926,4);
INSERT INTO stanza VALUES('NS867','1','Draw me, Lord, with the bands<br/>Of Your love, with cords of man,<br/>Going forth in my being entire;<br/>I’d in harmony stand<br/>With Your goal, for Your plan<br/>Through Your word, joined to Your<br/>heart’s desire.<br/>',NULL,67927,1);
INSERT INTO stanza VALUES('NS867','2','Make me one who would pray<br/>Mingled with God as my faith,<br/>Always praying and not losing heart;<br/>I’d persistently pray,<br/>And through prayer be saved each day,<br/>Not in self but in God<br/>fully trusting.<br/>',NULL,67928,2);
INSERT INTO stanza VALUES('NS867','3','Teach me, Lord, not to waste<br/>But to number all my days,<br/>Better one day with You than a thousand; <br/>Keep me faithful, in grace<br/>To express You all my days,<br/>In all matters, for Your<br/>propagation.<br/>',NULL,67929,3);
INSERT INTO stanza VALUES('NS867','4','If I struggle within,<br/>You must never let me win.<br/>Lord, defeat me, and conquer me wholly;<br/>Not a half consecration,<br/>But absolutely giv’n,<br/>Lord, I’ll pay the full price<br/>for You solely.<br/>',NULL,67930,4);
INSERT INTO stanza VALUES('NS868','chorus','It is Jehovah’s lovingkindness<br/>That we are not consumed,<br/>For His compassions do not fail;<br/>They are new every morning.<br/>Jehovah is my portion; therefore I hope in Him.<br/>He is good to those who wait on Him, Him, who wait on Him.<br/>',NULL,67931,1);
INSERT INTO stanza VALUES('NS869','chorus','There is no other way to reach the high peak<br/>of God’s eternal economy,<br/>the reality of the Body of Christ,<br/>except by praying;<br/>our becoming the overcomers<br/>as the reality of the Body of Christ<br/>to be the bride of Christ<br/>will close this age, the age of the church,<br/>and will bring Christ as the King of glory<br/>back to take, possess, and rule over this earth<br/>with His overcomers in the kingdom age,<br/>the kingdom age.<br/>',NULL,67932,1);
INSERT INTO stanza VALUES('NS870','chorus','God’s economy is to work Himself, work Himself into us<br/>so that we may experience a metabolic process<br/>of spiritual digestion and assimilation<br/>that produces, produces transformation<br/>as a gradual and intrinsic metabolic change<br/>in our natural life with the divine life;<br/>this is for the building up of the Body of Christ<br/>to consummate the New Jerusalem.<br/>',NULL,67933,1);
INSERT INTO stanza VALUES('NS871','chorus','Looking away,<br/>Looking away,<br/>Looking away, looking away unto Jesus.<br/>(repeat)<br/>',NULL,67934,1);
INSERT INTO stanza VALUES('NS871','chorus','“Looking away unto” denotes looking with undivided attention by<br/>Turning away from every other object.<br/>',NULL,67935,2);
INSERT INTO stanza VALUES('NS871','chorus','Looking away,<br/>Looking away,<br/>Looking away, looking away unto Jesus.<br/>',NULL,67936,3);
INSERT INTO stanza VALUES('NS871','chorus','The Hebrew believers had to look away from all the things in their environment,<br/>Away from their old religion, Judaism, and its persecution,<br/>And away from all earthly things, that they might<br/>Look, look unto Jesus, who is now seated on the<br/>Right hand of the throne of God in the heavens.<br/>Look, look unto Jesus, who is now seated on the<br/>Right hand of the throne of God in the heavens.<br/>',NULL,67937,4);
INSERT INTO stanza VALUES('NS872','chorus','For the mountains may depart,<br/>And the hills may shake.<br/>But My lovingkindness will not depart from you,<br/>And My covenant of peace,<br/>Will not shake, says Jehovah,<br/>Who has compassion,<br/>Compassion on you.<br/>',NULL,67938,1);
INSERT INTO stanza VALUES('NS872','chorus','For your Maker is your Husband;<br/>Jehovah of hosts’s His name.<br/>And the Holy One of Israel<br/>Is your Redeemer; He is called<br/>The God of all the earth.<br/>This One is Jesus—<br/>Our Husband, Savior, God!<br/>',NULL,67939,2);
INSERT INTO stanza VALUES('CB1108','end-note','(Do not repeat the chorus after last verse)<br/>',NULL,67940,7);
INSERT INTO stanza VALUES('NS873','1','In the stillness of the dark of night,<br/>I anticipate the morning light.<br/>Hearing whispers of the dawn, I rise<br/>To go forth and meet my Lord.<br/>Jesus, Thou art the Sun of my soul;<br/>Thou stirrest love I cannot control.<br/>By Thine appearing, I am made whole;<br/>All the darkness flees and shadows roll<br/>When I go to meet my Lord.<br/>',NULL,76285,1);
INSERT INTO stanza VALUES('NS873','2','When the anxious thoughts of life appear,<br/>When the path grows dim, the way unclear,<br/>And the whispers, doubts, assail mine ear,<br/>I go forth to meet my Lord.<br/>Jesus, Thou art my Rock and my Shield,<br/>Speak to me, and my faith shall be healed.<br/>All trust and hope to Thee I would yield.<br/>All the fears are shut away and sealed,<br/>When I go to meet my Lord.<br/>',NULL,76286,2);
INSERT INTO stanza VALUES('NS873','3','As the days on earth pass swiftly by,<br/>And the day of Thy return draws nigh,<br/>I await each dawning of the sky:<br/>I will surely meet my Lord.<br/>Jesus—the longing deep in my heart,<br/>E’en from Thy shadow I’d ne’er depart.<br/>Lord, Thou hast won me right from the start.<br/>Soon we nevermore shall be apart,<br/>On the day I’ll meet Thee, Lord.<br/>',NULL,76287,3);
INSERT INTO stanza VALUES('NS874','1','Jesus my Shepherd in tenderness came,<br/>Seeking my soul, one lost sheep to reclaim!<br/>Laid down His life when He died on the tree,<br/>Now He’s the risen One living in me!<br/>',NULL,76288,1);
INSERT INTO stanza VALUES('NS874','chorus','I am so glad that God dwells in me,<br/>The Triune God—now dwells in me!<br/>Oh what a day, the Triune God came—<br/>And now He lives in me!<br/>',NULL,76289,2);
INSERT INTO stanza VALUES('NS874','2','Like a fine woman, He swept and He searched,<br/>For one lost coin which to Him had great worth;<br/>When by His Spirit He shined on my sin,<br/>All night was scattered, and He entered in!<br/>',NULL,76290,3);
INSERT INTO stanza VALUES('NS874','chorus','I am so glad that God dwells in me,<br/>The Triune God—now dwells in me!<br/>Oh what a day, the Triune God came—<br/>And now He lives in me!<br/>',NULL,76291,4);
INSERT INTO stanza VALUES('NS874','3','Once, lost in sin, from my Father I roamed,<br/>Yet deep within I still longed for a home;<br/>But by His mercy this prodigal sees!<br/>I was once dead, but now God lives in me!<br/>',NULL,76292,5);
INSERT INTO stanza VALUES('NS874','chorus','I am so glad that God dwells in me,<br/>The Triune God—now dwells in me!<br/>Oh what a day, the Triune God came—<br/>And now He lives in me!<br/>',NULL,76293,6);
INSERT INTO stanza VALUES('NS874','4','Through the Son’s death, I have access to God,<br/>Through the sweet washing of His precious blood;<br/>One Spirit now reconciled indeed,<br/>One with the Triune God, living in me!<br/>',NULL,76294,7);
INSERT INTO stanza VALUES('NS874','chorus','I am so glad that God dwells in me,<br/>The Triune God—now dwells in me!<br/>Oh what a day, the Triune God came—<br/>And now He lives in me!<br/>',NULL,76295,8);
INSERT INTO stanza VALUES('NS874','5','What love divine that my God has made known,<br/>Sinners and the Triune God find a home!<br/>What grace bestowed to the less than the least—<br/>Oh, hallelujah! God’s living in me!<br/>',NULL,76296,9);
INSERT INTO stanza VALUES('NS874','chorus','I am so glad that God dwells in me,<br/>The Triune God—now dwells in me!<br/>Oh what a day, the Triune God came—<br/>And now He lives in me!<br/>',NULL,76297,10);
INSERT INTO stanza VALUES('NS875','chorus','When I call on You, Lord,<br/>It seems nothing has changed,<br/>But deep within a great transfer was made<br/>From myself to my spirit—<br/>From old to new;<br/>Thus the whole day I’m turned to You.<br/>',NULL,76298,1);
INSERT INTO stanza VALUES('NS875','chorus','A thousand times a day,<br/>A thousand times I’ll pray;<br/>From morning to evening<br/>I won’t stop from calling;<br/>One call on Your name, You transform my being;<br/>By then I’ve found out that I will never ever be the same!<br/>',NULL,76299,2);
INSERT INTO stanza VALUES('NS876','chorus','The Spirit of the Lord Jehovah is upon Me,<br/>Because Jehovah has anointed Me<br/>To bring good news to the afflicted;<br/>He has sent Me to bind up the wounds of the brokenhearted,<br/>To proclaim liberty to the captives,<br/>And the opening of the eyes to those,<br/>to those who are bound;<br/>Isaiah sixty-one one.<br/>',NULL,76300,1);
INSERT INTO stanza VALUES('NS877','chorus','Listen carefully to the word of God<br/>As the Lord is opening our ears;<br/>Circumcised, cleansed and anointed,<br/>Hear the Spirit’s speaking.<br/>',NULL,76301,1);
INSERT INTO stanza VALUES('NS877','chorus','Ponder on it, walk on it<br/>His words consider;<br/>Rise up to have a great resolution<br/>To cooperate to live to Him<br/>And live out Him,<br/>Not holding back until He comes back.<br/>',NULL,76302,2);
INSERT INTO stanza VALUES('NS878','chorus','Author, Originator, Inaugurator, Leader, Pioneer, Forerunner.<br/>Author, Originator, Inaugurator, Leader, Pioneer, Forerunner.<br/>',NULL,76303,1);
INSERT INTO stanza VALUES('NS878','chorus','All the overcoming saints in the Old Testament are only witnesses of faith,<br/>Whereas Jesus is the Author, Jesus is the Author of faith.<br/>He is the Originator, the Inaugurator, the source, and the cause of faith.<br/>In our natural man we have no, we have no believing, we have no believing ability.<br/>',NULL,76304,2);
INSERT INTO stanza VALUES('NS878','chorus','We do not have faith by ourselves.<br/>The faith by which we are saved<br/>Is the precious faith that we have received,<br/>we have received, we have received from the Lord.<br/>',NULL,76305,3);
INSERT INTO stanza VALUES('NS878','chorus','Author, Originator, Inaugurator, Leader, Pioneer, Forerunner.<br/>Author, Originator, Inaugurator, Leader, Pioneer, Forerunner.<br/>',NULL,76306,4);
INSERT INTO stanza VALUES('NS878','chorus','When we look unto Jesus, He as the life-giving Spirit<br/>Transfuses us with Himself, with His believing element.<br/>Then, spontaneously, a kind of believing arises in our being,<br/>And we have the faith to believe, we have the faith to believe in Him.<br/>',NULL,76307,5);
INSERT INTO stanza VALUES('NS878','chorus','This faith is not of ourselves but of Him who imparts<br/>Himself as the believing element into us that He may believe for us.<br/>',NULL,76308,6);
INSERT INTO stanza VALUES('NS879','1','Abide in me, Lord, deep within my heart,<br/>Make Your abode within my deepest part!<br/>Lord, may Your Spirit make His home in me,<br/>Thus all my being Your abode will be.<br/>',NULL,76309,1);
INSERT INTO stanza VALUES('NS879','2','Your Spirit with my spirit is the key—<br/>A mutual dwelling place for You and me!<br/>By this organic union that we share<br/>We have become by grace one loving pair.<br/>',NULL,76310,2);
INSERT INTO stanza VALUES('NS879','3','By faith I have been joined to You, dear Lord,<br/>Now our two spirits are in one accord!<br/>Thus joined and mingled, I abide in You,<br/>In thought, intention, and in all I do.<br/>',NULL,76311,3);
INSERT INTO stanza VALUES('NS879','4','“Abide in Me and I’ll abide in you,”<br/>Both a commandment and a promise true!<br/>We may much fruit unto the Father bear<br/>As we abide in Him whose life we share.<br/>',NULL,76312,4);
INSERT INTO stanza VALUES('NS880','1','In Lo-debar, I was just lame there,<br/>So crippled, so sad, and so poor.<br/>In fear of my life with no answers,<br/>My future so bleak and unsure.<br/>',NULL,76313,1);
INSERT INTO stanza VALUES('NS880','chorus','“Where are you,” came the sweetest voice<br/>“I love you, I’ll care for your need!<br/>Come, enjoy this feast at My table here.<br/>I have covered your poor crippled feet.”<br/>',NULL,76314,2);
INSERT INTO stanza VALUES('NS880','2','This world fills my heart not with pleasure,<br/>But hunger and much anxious care.<br/>What joy, in the midst of my suff’ring,<br/>My Christ came and saved me from there.<br/>',NULL,76315,3);
INSERT INTO stanza VALUES('NS880','chorus','“Where are you,” came the sweetest voice<br/>“I love you, I’ll care for your need!<br/>Come, enjoy this feast at My table here.<br/>I have covered your poor crippled feet.”<br/>',NULL,76316,4);
INSERT INTO stanza VALUES('NS880','3','At first I was fearful and fled Him,<br/>Why would He seek someone like me?<br/>But calling my name, He disarmed me,<br/>His voice warm, compassionate, sweet.<br/>',NULL,76317,5);
INSERT INTO stanza VALUES('NS880','chorus','“Where are you,” came the sweetest voice<br/>“I love you, I’ll care for your need!<br/>Come, enjoy this feast at My table here.<br/>I have covered your poor crippled feet.”<br/>',NULL,76318,6);
INSERT INTO stanza VALUES('NS880','4','It’s here I forget my condition,<br/>And failure my standard to meet.<br/>I see only Christ in His richness,<br/>And worship my Lord at His feast!<br/>',NULL,76319,7);
INSERT INTO stanza VALUES('NS880','chorus','“Where are you,” came the sweetest voice<br/>“I love you, I’ll care for your need!<br/>Come, enjoy this feast at My table here.<br/>I have covered your poor crippled feet.”<br/>',NULL,76320,8);
